/* Generated by tools/build-ielts-reading-passage2-flashcards.py. */
window.EDMUND_IELTS_READING_PASSAGE_2_SEED = {"ielts/reading/passage-2/Practice 24":[{"front":"Caveat Scriptor","meaning":"寫作者慎之","examples":[{"en":"Caveat Scriptor warns would-be writers about the difficulties of writing.","zh":"「寫作者慎之」提醒有意成為作家的人注意寫作的困難。"},{"en":"Caveat Scriptor means “let the writer beware”.","zh":"「Caveat Scriptor」意思是「讓寫作者小心」。"},{"en":"A teacher may write Caveat Scriptor at the start of a lesson about how hard publishing can be.","zh":"老師講解出版有多困難時，可能在課堂開首寫下 Caveat Scriptor。"},{"en":"If someone thinks writing is only glamorous, Caveat Scriptor reminds them to expect rejection and revision.","zh":"如果有人以為寫作只是光鮮亮麗，Caveat Scriptor 會提醒他們要預期被拒和反覆修改。"},{"en":"The phrase sounds humorous because it treats writing like a risky adventure.","zh":"這個短語帶幽默感，因為它把寫作說成像一場有風險的冒險。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":1},{"front":"would-be writer","meaning":"有意成為作家的人","examples":[{"en":"Let the would-be writer beware before starting a writing career.","zh":"有意成為作家的人在開始寫作職業前應小心。"},{"en":"A would-be writer is someone who hopes or intends to become a writer.","zh":"「would-be writer」是希望或打算成為作家的人。"},{"en":"A student who keeps a notebook of story ideas may be a would-be writer.","zh":"經常用筆記本記下故事點子的學生，可能是有意成為作家的人。"},{"en":"If a would-be writer understands the hard work involved, they may prepare more realistically.","zh":"如果有意成為作家的人明白當中涉及的辛苦工作，他們可能會更現實地準備。"},{"en":"The phrase describes ambition before the person has fully become a writer.","zh":"這個短語描述人在真正成為作家之前的志向。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":1},{"front":"beware","meaning":"小心；慎防","examples":[{"en":"Let the would-be writer beware.","zh":"有意成為作家的人應小心。"},{"en":"Beware means be careful because there may be danger, difficulty, or trouble ahead.","zh":"「beware」意思是要小心，因為前方可能有危險、困難或麻煩。"},{"en":"A sign saying “Beware of wet floor” warns students not to slip.","zh":"寫着「小心地滑」的標誌提醒學生不要滑倒。"},{"en":"If a writer does not beware of endless editing, one chapter may take far too long.","zh":"如果作家不慎防無止境編輯，一章可能花太久時間。"},{"en":"The word is a strong warning, not just friendly advice.","zh":"這個詞是強烈警告，而不只是友善建議。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":1},{"front":"foolhardy enough to","meaning":"魯莽到……","examples":[{"en":"Anyone foolhardy enough to become a writer should read this first.","zh":"任何魯莽到想成為作家的人，都應先讀這篇文章。"},{"en":"Foolhardy enough to do something means brave in a careless or unwise way.","zh":"「foolhardy enough to」做某事，意思是勇敢得有點粗心或不明智。"},{"en":"A student foolhardy enough to start an essay at midnight may regret it the next morning.","zh":"魯莽到半夜才開始寫作文的學生，第二天早上可能會後悔。"},{"en":"If someone is foolhardy enough to ignore warnings, they may face avoidable problems.","zh":"如果有人魯莽到無視警告，他們可能面對本可避免的問題。"},{"en":"The phrase suggests that the action is risky and perhaps not very sensible.","zh":"這個短語暗示該行動有風險，而且也許不太明智。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":1},{"front":"embark on a career as","meaning":"開始從事……職業","examples":[{"en":"Some people want to embark on a career as a writer.","zh":"有些人想開始從事作家職業。"},{"en":"To embark on a career as something means to begin that professional path.","zh":"「embark on a career as」某職業，意思是開始走上該專業道路。"},{"en":"A graduate may embark on a career as a teacher after finishing university.","zh":"畢業生完成大學後，可能開始從事教師職業。"},{"en":"If someone embarks on a writing career, they need discipline as well as imagination.","zh":"如果有人開始寫作事業，他們需要紀律，也需要想像力。"},{"en":"The phrase sounds formal and marks the start of a long-term career.","zh":"這個短語較正式，標誌長期職業的開始。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":1},{"front":"academic treatise","meaning":"學術論著","examples":[{"en":"A writer may work on an academic treatise, a novel, or an article.","zh":"作家可能撰寫學術論著、小說或文章。"},{"en":"An academic treatise is a long, serious piece of writing about a scholarly subject.","zh":"「academic treatise」是關於學術題目的長篇嚴肅著作。"},{"en":"A professor may spend years writing an academic treatise on climate history.","zh":"教授可能花數年撰寫關於氣候歷史的學術論著。"},{"en":"If a treatise requires detailed evidence, the writer must research carefully before drafting.","zh":"如果論著需要詳細證據，作者在起草前必須仔細研究。"},{"en":"The phrase describes formal academic writing, not casual opinion writing.","zh":"這個短語描述正式學術寫作，而不是隨意意見文章。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":1},{"front":"people think that","meaning":"人們以為","examples":[{"en":"People think that writing as a profession is glamorous.","zh":"人們以為以寫作為職業是光鮮的。"},{"en":"People think that introduces a common belief or assumption.","zh":"「people think that」引出常見信念或假設。"},{"en":"People think that online lessons are easy, but teachers may spend hours preparing them.","zh":"人們以為網課很容易，但老師可能花數小時準備。"},{"en":"If people think that writing is simple, they may underestimate editing and rejection.","zh":"如果人們以為寫作很簡單，他們可能低估編輯和被拒的辛苦。"},{"en":"The phrase often introduces an idea the writer will question or correct.","zh":"這個短語常引出作者將會質疑或更正的想法。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":1},{"front":"writing as a profession","meaning":"以寫作為職業","examples":[{"en":"Writing as a profession is often misunderstood.","zh":"以寫作為職業常被誤解。"},{"en":"Writing as a profession means earning a living by producing books, articles, scripts, or other texts.","zh":"「writing as a profession」指透過撰寫書籍、文章、劇本或其他文本謀生。"},{"en":"A journalist practises writing as a profession every day under deadlines.","zh":"記者每天在限期下工作，就是以寫作為職業。"},{"en":"If writing becomes a profession, creativity must be combined with planning and discipline.","zh":"如果寫作成為職業，創意必須結合規劃和紀律。"},{"en":"The phrase separates professional writing from writing only as a hobby.","zh":"這個短語把專業寫作與純粹作為興趣的寫作分開。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":1},{"front":"glamorous","meaning":"令人嚮往的；光鮮的","examples":[{"en":"Many people think a writing career is glamorous.","zh":"許多人以為寫作生涯令人嚮往。"},{"en":"Glamorous means attractive, exciting, and connected with fame or admiration.","zh":"「glamorous」意思是吸引、刺激，並與名氣或羨慕有關。"},{"en":"Some students think acting is glamorous because they see awards and red carpets.","zh":"有些學生覺得演戲很光鮮，因為他們看到頒獎禮和紅地氈。"},{"en":"If a job looks glamorous from the outside, people may ignore its long hours and stress.","zh":"如果一份工作從外面看很光鮮，人們可能忽略其長工時和壓力。"},{"en":"The word describes a shiny public image, not necessarily the real experience.","zh":"這個詞描述亮麗的公眾形象，而不一定是真實經歷。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":1},{"front":"sit down and","meaning":"坐下來並……","examples":[{"en":"People imagine writers simply sit down and produce words.","zh":"人們想像作家只是坐下來並寫出文字。"},{"en":"Sit down and do something means begin an activity by taking a seat and starting the task.","zh":"「sit down and」做某事，意思是坐下並開始該任務。"},{"en":"A student may sit down and revise after dinner.","zh":"學生可能晚飯後坐下來溫習。"},{"en":"If writing were only sitting down and typing, everyone could finish a book quickly.","zh":"如果寫作只是坐下來打字，每個人都可以很快完成一本書。"},{"en":"The phrase can make a task sound easier than it really is.","zh":"這個短語可以令一項任務聽起來比實際容易。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":1},{"front":"churn out words","meaning":"大量快速寫出文字","examples":[{"en":"People think writers just churn out words on a page.","zh":"人們以為作家只是把文字大量快速寫在頁面上。"},{"en":"To churn out words means to produce a lot of writing quickly, often without much care.","zh":"「churn out words」意思是快速產出大量文字，通常未必很仔細。"},{"en":"A student may churn out words before a deadline but still need to edit them later.","zh":"學生可能在限期前大量快速寫出文字，但之後仍需要編輯。"},{"en":"If writers only churn out words, the text may lack structure, accuracy, and style.","zh":"如果作家只是大量快速寫字，文本可能缺乏結構、準確性和風格。"},{"en":"The phrase can sound slightly negative because it suggests quantity over quality.","zh":"這個短語可帶輕微負面意思，因為它暗示重數量多於質素。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":1},{"front":"on a computer screen","meaning":"在電腦螢幕上","examples":[{"en":"Writers are more likely these days to write on a computer screen.","zh":"現今作家更可能在電腦螢幕上寫作。"},{"en":"On a computer screen means displayed or created on the visual display of a computer.","zh":"「on a computer screen」意思是在電腦的顯示屏上顯示或創作。"},{"en":"Students often draft essays on a computer screen before printing them.","zh":"學生常在電腦螢幕上起草文章，然後才列印。"},{"en":"If writing is done on a computer screen, editing becomes easy but endless revision becomes tempting.","zh":"如果寫作在電腦螢幕上進行，編輯會變容易，但無止境修改也變得很有誘惑。"},{"en":"The phrase contrasts modern digital writing with writing on paper.","zh":"這個短語把現代數碼寫作與紙上寫作作對比。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":2},{"front":"if only it were","meaning":"要是真的如此就好了","examples":[{"en":"If only it were that easy to write a book.","zh":"寫一本書要是真的如此容易就好了。"},{"en":"If only it were means the speaker wishes something were true, but knows it is not.","zh":"「if only it were」意思是說話者希望某事是真的，但知道它不是。"},{"en":"If only it were that easy to learn English after watching one video.","zh":"要是看一條影片就能學好英文，那就好了。"},{"en":"If a task is much harder than people think, “if only it were” expresses gentle frustration.","zh":"如果任務比人們想像困難得多，“if only it were” 表達溫和的無奈。"},{"en":"The phrase often introduces disappointment after an unrealistic idea.","zh":"這個短語常在不切實際的想法後引出失望。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":2},{"front":"what exactly does something entail","meaning":"……到底涉及甚麼","examples":[{"en":"What exactly does writing a book entail?","zh":"寫一本書到底涉及甚麼？"},{"en":"What exactly does something entail asks what tasks, duties, or difficulties are involved.","zh":"「what exactly does something entail」是在問某事涉及哪些任務、責任或困難。"},{"en":"Before joining a club, a student may ask what exactly membership entails.","zh":"加入社團前，學生可能問會員身份到底涉及甚麼。"},{"en":"If writing a book entails research, editing, and rejection, beginners should not expect an easy path.","zh":"如果寫書涉及研究、編輯和被拒，初學者就不應期待道路輕鬆。"},{"en":"The phrase asks for the real work behind an activity.","zh":"這個短語詢問活動背後真正的工作。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":2},{"front":"manage contradictory feelings","meaning":"處理矛盾情緒","examples":[{"en":"Being a writer is about managing contradictory feelings.","zh":"成為作家就是要處理矛盾情緒。"},{"en":"To manage contradictory feelings means to handle opposite emotions at the same time.","zh":"「manage contradictory feelings」意思是同時處理相反的情緒。"},{"en":"A student waiting for exam results may manage hope and fear together.","zh":"等待考試成績的學生可能同時處理希望和恐懼。"},{"en":"If writing brings both joy and despair, the writer must learn to stay steady.","zh":"如果寫作同時帶來喜悅和絕望，作家必須學會保持穩定。"},{"en":"The phrase describes emotional control during a difficult process.","zh":"這個短語描述在困難過程中的情緒管理。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":2},{"front":"a galaxy of","meaning":"一大堆；各式各樣的","examples":[{"en":"A writer manages a galaxy of contradictory feelings.","zh":"作家要處理一大堆矛盾情緒。"},{"en":"A galaxy of something means a very large and varied collection of it.","zh":"「a galaxy of」某物，意思是數量很多而且種類豐富。"},{"en":"A school fair may offer a galaxy of activities, from games to food stalls.","zh":"學校嘉年華可能提供各式各樣的活動，由遊戲到食物攤位都有。"},{"en":"If a writer feels excitement, fear, pride, and doubt, the emotions form a huge mix.","zh":"如果作家感到興奮、恐懼、自豪和懷疑，這些情緒就形成龐大混合。"},{"en":"The phrase is expressive and means “a great variety of”.","zh":"這個短語較有表現力，意思是「大量不同種類」。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":2},{"front":"contradictory feelings","meaning":"矛盾情緒","examples":[{"en":"Writers often experience contradictory feelings.","zh":"作家常經歷矛盾情緒。"},{"en":"Contradictory feelings are emotions that seem opposite or difficult to hold together.","zh":"「contradictory feelings」是看似相反或難以同時承受的情緒。"},{"en":"A student leaving school may feel excited about freedom but sad to leave friends.","zh":"離校學生可能既為自由感到興奮，又因離開朋友而傷感。"},{"en":"If a book is accepted but heavily edited, the writer may feel proud and hurt at once.","zh":"如果書被接受但被大幅修改，作家可能同時感到自豪和受傷。"},{"en":"The phrase describes emotional conflict inside one person.","zh":"這個短語描述一個人內心的情緒衝突。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":2},{"front":"elation","meaning":"興高采烈","examples":[{"en":"Writing can bring moments of elation.","zh":"寫作可以帶來興高采烈的時刻。"},{"en":"Elation is a feeling of great happiness and excitement.","zh":"「elation」是非常快樂和興奮的感覺。"},{"en":"A student may feel elation after receiving an unexpected scholarship.","zh":"學生收到意外獎學金後可能感到興高采烈。"},{"en":"If a writer finally solves a difficult chapter, elation may replace frustration.","zh":"如果作家終於解決困難章節，興奮可能取代挫敗感。"},{"en":"The word describes a high emotional point.","zh":"這個詞描述情緒上的高點。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":2},{"front":"despair","meaning":"絕望","examples":[{"en":"A writer may experience despair during the writing process.","zh":"作家可能在寫作過程中經歷絕望。"},{"en":"Despair is a feeling that a situation is hopeless.","zh":"「despair」是覺得情況沒有希望的感覺。"},{"en":"A student may feel despair after failing the same exam twice.","zh":"學生兩次考同一科不合格後可能感到絕望。"},{"en":"If a writer cannot fix a weak chapter, despair may set in.","zh":"如果作家無法修好薄弱章節，絕望可能出現。"},{"en":"The word describes deep discouragement, not just mild sadness.","zh":"這個詞描述深深氣餒，而不只是輕微傷心。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":2},{"front":"frustration","meaning":"挫敗感","examples":[{"en":"Frustration is one of the emotions involved in writing.","zh":"挫敗感是寫作涉及的情緒之一。"},{"en":"Frustration is the annoyed feeling people get when progress is blocked.","zh":"「frustration」是進展受阻時產生的煩躁感。"},{"en":"A student may feel frustration when a maths answer keeps coming out wrong.","zh":"當數學答案一直計錯，學生可能感到挫敗。"},{"en":"If a writer rewrites the same paragraph many times, frustration can grow.","zh":"如果作家多次重寫同一段，挫敗感可能增加。"},{"en":"The word describes irritation caused by difficulty or delay.","zh":"這個詞描述由困難或延誤造成的煩躁。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":2},{"front":"satisfaction","meaning":"滿足感","examples":[{"en":"Writing can also bring satisfaction.","zh":"寫作也可以帶來滿足感。"},{"en":"Satisfaction is a calm feeling of pleasure when something has been done well.","zh":"「satisfaction」是在某事做得好後產生的平靜愉快感。"},{"en":"A student may feel satisfaction after finishing a difficult project on time.","zh":"學生準時完成困難專題後可能感到滿足。"},{"en":"If a writer finally improves a weak draft, satisfaction can follow the hard work.","zh":"如果作家終於改善薄弱初稿，努力後可能會有滿足感。"},{"en":"The word describes a positive feeling after effort.","zh":"這個詞描述努力後的正面感覺。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":2},{"front":"not all separately","meaning":"並非全都分開出現","examples":[{"en":"These emotions do not always appear separately.","zh":"這些情緒並非總是分開出現。"},{"en":"Not all separately means not one by one or not in clearly divided parts.","zh":"「not all separately」意思是不是一個接一個，或不是清楚分開的部分。"},{"en":"A student may feel nervous and excited at the same time, not separately.","zh":"學生可能同時感到緊張和興奮，而不是分開感受。"},{"en":"If writing brings joy and anxiety together, the emotions overlap.","zh":"如果寫作同時帶來喜悅和焦慮，情緒就會重疊。"},{"en":"The phrase shows that experiences can mix rather than stay separate.","zh":"這個短語顯示經歷可以混合，而不是保持分開。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":2},{"front":"carry out detailed research","meaning":"進行詳細研究","examples":[{"en":"Writing a book involves carrying out detailed research.","zh":"寫一本書涉及進行詳細研究。"},{"en":"To carry out detailed research means to study a topic carefully and collect accurate information.","zh":"「carry out detailed research」意思是仔細研究題目並收集準確資料。"},{"en":"A student writing about pollution should carry out detailed research before making claims.","zh":"寫污染題目的學生在提出主張前應進行詳細研究。"},{"en":"If research is weak, a book may contain errors or miss important facts.","zh":"如果研究薄弱，書本可能包含錯誤或漏掉重要事實。"},{"en":"The phrase describes serious preparation before writing.","zh":"這個短語描述寫作前的認真準備。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":3},{"front":"establish whether","meaning":"確定是否","examples":[{"en":"The writer must establish whether there is a market.","zh":"作者必須確定是否有市場。"},{"en":"To establish whether means to find out clearly if something is true or possible.","zh":"「establish whether」意思是清楚查明某事是否真實或可能。"},{"en":"A teacher may establish whether students understand grammar before moving on.","zh":"老師可能先確定學生是否理解文法，再繼續教下去。"},{"en":"If a writer cannot establish whether readers want the book, publishing it becomes risky.","zh":"如果作者不能確定讀者是否想要該書，出版就變得有風險。"},{"en":"The phrase focuses on confirming a fact.","zh":"這個短語集中於確認事實。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":3},{"front":"market for","meaning":"……的市場","examples":[{"en":"The writer needs to know whether there is a market for the publication.","zh":"作者需要知道該出版物是否有市場。"},{"en":"A market for something means a group of people who may want to buy or read it.","zh":"「market for」某物，意思是可能想購買或閱讀它的一群人。"},{"en":"A company checks whether there is a market for a new lunchbox before producing it.","zh":"公司生產新飯盒前會查看是否有市場。"},{"en":"If there is no market for a book, publishers may refuse it even if it is well written.","zh":"如果一本書沒有市場，即使寫得好，出版社也可能拒絕。"},{"en":"The phrase describes demand from potential buyers or readers.","zh":"這個短語描述潛在買家或讀者的需求。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":3},{"front":"planned publication","meaning":"計劃中的出版物","examples":[{"en":"Research helps determine the market for the planned publication.","zh":"研究有助判斷計劃中的出版物是否有市場。"},{"en":"A planned publication is a book, article, or text that a writer intends to publish.","zh":"「planned publication」是作者打算出版的書、文章或文本。"},{"en":"A teacher may ask students to outline a planned publication before writing the first chapter.","zh":"老師可能要求學生在寫第一章前，先為計劃中的出版物列大綱。"},{"en":"If the planned publication has no clear readers, its content may need to change.","zh":"如果計劃中的出版物沒有清楚讀者，其內容可能需要改變。"},{"en":"The phrase describes a work before it is actually published.","zh":"這個短語描述實際出版前的作品。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":3},{"front":"determine what","meaning":"決定……應該是甚麼","examples":[{"en":"Research helps determine what the book’s content should be.","zh":"研究有助決定書本內容應該是甚麼。"},{"en":"To determine what means to decide or find out the correct thing.","zh":"「determine what」意思是決定或查明正確事物。"},{"en":"A teacher may determine what students need by checking their mistakes.","zh":"老師可能透過檢查學生錯誤來決定學生需要甚麼。"},{"en":"If research shows readers want practical advice, the book’s content may become more useful.","zh":"如果研究顯示讀者想要實用建議，書本內容可能變得更有用。"},{"en":"The phrase describes deciding based on information.","zh":"這個短語描述根據資料作決定。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":3},{"front":"book’s content","meaning":"書本內容","examples":[{"en":"The writer must decide what the book’s content should be.","zh":"作者必須決定書本內容應該是甚麼。"},{"en":"A book’s content is the information, story, ideas, examples, and chapters inside it.","zh":"「book’s content」是書中包含的資料、故事、想法、例子和章節。"},{"en":"A textbook’s content may include explanations, diagrams, questions, and answers.","zh":"教科書內容可能包括解釋、圖表、問題和答案。"},{"en":"If the book’s content does not match readers’ needs, it may not sell well.","zh":"如果書本內容不符合讀者需要，它可能賣得不好。"},{"en":"The phrase describes what the book actually contains.","zh":"這個短語描述書實際包含甚麼。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":3},{"front":"instinct takes the place of","meaning":"直覺取代……","examples":[{"en":"Sometimes instinct takes the place of market research.","zh":"有時直覺會取代市場調查。"},{"en":"If instinct takes the place of something, people rely on feeling or judgement instead of that method.","zh":"如果直覺取代某方法，人們就是依靠感覺或判斷，而不是該方法。"},{"en":"A chef may let instinct take the place of a recipe when adjusting a soup.","zh":"廚師調整湯味時，可能讓直覺取代食譜。"},{"en":"If a writer knows a subject deeply, instinct may guide choices before formal research does.","zh":"如果作家很熟悉某題目，直覺可能先於正式研究指導選擇。"},{"en":"The phrase shows one thing replacing another.","zh":"這個短語顯示一事取代另一事。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":3},{"front":"market research","meaning":"市場調查","examples":[{"en":"Market research may help establish demand for a book.","zh":"市場調查可能有助確定一本書的需求。"},{"en":"Market research is the study of what customers or readers want and may buy.","zh":"「market research」是研究顧客或讀者想要甚麼、可能購買甚麼。"},{"en":"A café may do market research before adding expensive new drinks.","zh":"咖啡店在加入昂貴新飲品前，可能做市場調查。"},{"en":"If market research shows little interest, a writer may rethink the topic.","zh":"如果市場調查顯示興趣很少，作者可能重新考慮題目。"},{"en":"The phrase describes research into demand and audience needs.","zh":"這個短語描述對需求和受眾需要的研究。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":3},{"front":"be dictated by","meaning":"由……決定","examples":[{"en":"The contents may be dictated by experience and knowledge.","zh":"內容可能由經驗和知識決定。"},{"en":"To be dictated by something means to be decided or strongly controlled by it.","zh":"「be dictated by」某事，意思是由它決定或強烈控制。"},{"en":"A school timetable may be dictated by room availability and teacher schedules.","zh":"學校時間表可能由課室可用情況和老師日程決定。"},{"en":"If a book is dictated by the writer’s expertise, research may support rather than create its content.","zh":"如果一本書由作者專長決定內容，研究可能只是支援而不是創造內容。"},{"en":"The phrase shows what controls a decision.","zh":"這個短語顯示甚麼控制決定。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":3},{"front":"exhaustive research","meaning":"詳盡研究","examples":[{"en":"The contents are not always dictated by exhaustive research.","zh":"內容並不總是由詳盡研究決定。"},{"en":"Exhaustive research is very thorough research that tries to cover everything important.","zh":"「exhaustive research」是非常徹底、試圖涵蓋所有重要內容的研究。"},{"en":"A historian may carry out exhaustive research before writing about a war.","zh":"歷史學家寫戰爭之前，可能進行詳盡研究。"},{"en":"If time is limited, exhaustive research may be impossible before a first draft.","zh":"如果時間有限，在初稿前進行詳盡研究可能不可能。"},{"en":"The phrase describes research that is detailed and comprehensive.","zh":"這個短語描述詳細而全面的研究。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":3},{"front":"experience and knowledge","meaning":"經驗和知識","examples":[{"en":"Sometimes the contents are shaped by experience and knowledge.","zh":"有時內容由經驗和知識塑造。"},{"en":"Experience and knowledge mean what someone has learned from doing things and studying them.","zh":"「experience and knowledge」指某人從實踐和學習中獲得的東西。"},{"en":"A nurse’s advice is often based on both experience and medical knowledge.","zh":"護士的建議常基於經驗和醫學知識。"},{"en":"If a writer has years of teaching experience, it may shape a textbook strongly.","zh":"如果作者有多年教學經驗，它可能強烈塑造一本教科書。"},{"en":"The phrase combines practical learning with factual understanding.","zh":"這個短語結合實踐學習和事實理解。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":3},{"front":"be embarked upon","meaning":"被開始進行","examples":[{"en":"Once the publication has been embarked upon, the text slowly takes shape.","zh":"一旦出版計劃被開始進行，文本便慢慢成形。"},{"en":"When a project is embarked upon, it has been started.","zh":"當一個項目被 embarked upon，意思是它已經開始。"},{"en":"Once a school renovation has been embarked upon, classrooms may be moved temporarily.","zh":"一旦學校翻新工程開始進行，課室可能暫時搬遷。"},{"en":"If a book has been embarked upon, the writer must begin turning ideas into actual pages.","zh":"如果一本書已開始進行，作者就必須開始把想法變成實際頁面。"},{"en":"The phrase is formal and describes the start of a major task.","zh":"這個短語較正式，描述重大任務的開始。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":4},{"front":"long period of turmoil","meaning":"長時間混亂期","examples":[{"en":"There is a long period of turmoil as the text takes shape.","zh":"隨着文本逐漸成形，會有一段長時間混亂期。"},{"en":"A long period of turmoil is a long time of confusion, stress, or disorder.","zh":"「long period of turmoil」是長時間的混亂、壓力或失序。"},{"en":"A family may face a long period of turmoil during a major house move.","zh":"家庭在大型搬屋期間可能面對長時間混亂期。"},{"en":"If a writer changes chapters repeatedly, the writing process can feel chaotic for months.","zh":"如果作家反覆改動章節，寫作過程可能數月都感覺混亂。"},{"en":"The phrase describes extended difficulty before order appears.","zh":"這個短語描述秩序出現前的長期困難。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":4},{"front":"take shape","meaning":"逐漸成形","examples":[{"en":"The text slowly takes shape during writing.","zh":"文本在寫作期間慢慢成形。"},{"en":"To take shape means to gradually become clear, organised, or complete.","zh":"「take shape」意思是逐漸變得清楚、有組織或完整。"},{"en":"A school project takes shape when students decide the topic, roles, and final design.","zh":"當學生決定題目、角色和最終設計，學校專題便逐漸成形。"},{"en":"If a draft takes shape, scattered notes begin to become a real text.","zh":"如果初稿逐漸成形，零散筆記開始變成真正文本。"},{"en":"The phrase describes gradual formation.","zh":"這個短語描述逐步形成。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":4},{"front":"first draft","meaning":"初稿","examples":[{"en":"A first draft is rarely the final text of the book.","zh":"初稿很少是書本的最終文本。"},{"en":"A first draft is the first complete version of a piece of writing.","zh":"「first draft」是一篇文字的第一個完整版本。"},{"en":"A student’s first draft of an essay may contain weak examples and grammar mistakes.","zh":"學生的作文初稿可能有薄弱例子和文法錯誤。"},{"en":"If the first draft is rough, editing can improve structure, clarity, and style.","zh":"如果初稿粗糙，編輯可以改善結構、清晰度和風格。"},{"en":"The phrase describes a starting version, not the finished product.","zh":"這個短語描述起始版本，而不是完成品。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":4},{"front":"final text","meaning":"最終文本","examples":[{"en":"The first draft is rarely the final text.","zh":"初稿很少是最終文本。"},{"en":"The final text is the finished version that is ready to be printed or published.","zh":"「final text」是已完成、準備印刷或出版的版本。"},{"en":"A teacher may ask students to submit both the first draft and the final text.","zh":"老師可能要求學生同時提交初稿和最終文本。"},{"en":"If editing changes many paragraphs, the final text may look very different from the draft.","zh":"如果編輯改動許多段落，最終文本可能與初稿很不同。"},{"en":"The phrase describes the completed form of a written work.","zh":"這個短語描述書面作品的完成形式。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":4},{"front":"countless hours of","meaning":"無數小時的……","examples":[{"en":"Books are the result of countless hours of editing.","zh":"書本是無數小時編輯的結果。"},{"en":"Countless hours of something means so many hours that they are difficult to count.","zh":"「countless hours of」某事，意思是多到難以計算的小時。"},{"en":"A dancer may spend countless hours of practice before a performance.","zh":"舞者在表演前可能花無數小時練習。"},{"en":"If a book requires countless hours of editing, writing is not as effortless as it appears.","zh":"如果一本書需要無數小時編輯，寫作就不像外表看來那樣輕鬆。"},{"en":"The phrase emphasises a very large amount of time.","zh":"這個短語強調非常大量的時間。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":4},{"front":"altering and reordering","meaning":"修改和重新排序","examples":[{"en":"Writing involves altering and reordering chunks of text.","zh":"寫作涉及修改和重新排序大段文字。"},{"en":"Altering and reordering means changing parts and putting them in a different order.","zh":"「altering and reordering」意思是改變部分內容，並把它們放到不同次序。"},{"en":"A student may improve an essay by altering weak sentences and reordering paragraphs.","zh":"學生可以透過修改薄弱句子和重新排序段落來改善作文。"},{"en":"If ideas appear in the wrong sequence, reordering can make the argument clearer.","zh":"如果想法出現次序錯誤，重新排序可以令論點更清楚。"},{"en":"The phrase describes two common editing actions.","zh":"這個短語描述兩種常見編輯動作。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":4},{"front":"chunks of text","meaning":"大段文字","examples":[{"en":"Writers often move chunks of text around.","zh":"作家常把大段文字搬來搬去。"},{"en":"Chunks of text are large sections or blocks of writing.","zh":"「chunks of text」是較大的文字段落或區塊。"},{"en":"A student may move chunks of text when changing the order of an essay.","zh":"學生改變作文次序時，可能移動大段文字。"},{"en":"If one chunk of text belongs earlier, moving it can improve flow.","zh":"如果某段文字應該放在更前位置，移動它可以改善流暢度。"},{"en":"The phrase describes pieces of writing larger than single words or sentences.","zh":"這個短語描述比單字或句子更大的文字部分。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":4},{"front":"deleting the superfluous bits","meaning":"刪除多餘部分","examples":[{"en":"Editing involves deleting the superfluous bits.","zh":"編輯涉及刪除多餘部分。"},{"en":"Deleting the superfluous bits means removing unnecessary parts of a text.","zh":"「deleting the superfluous bits」意思是移除文本中不必要的部分。"},{"en":"A student may delete repeated examples to make an essay shorter and clearer.","zh":"學生可能刪除重複例子，使作文更短更清楚。"},{"en":"If extra words do not add meaning, deleting them can strengthen the paragraph.","zh":"如果多餘字詞沒有增加意思，刪除它們可以強化段落。"},{"en":"The phrase describes cutting material that is not needed.","zh":"這個短語描述剪走不需要的材料。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":4},{"front":"checking and editing process","meaning":"檢查和編輯過程","examples":[{"en":"Technology does not necessarily speed up the checking and editing process.","zh":"科技不一定會加快檢查和編輯過程。"},{"en":"The checking and editing process is the stage of reviewing, correcting, and improving a text.","zh":"「checking and editing process」是審閱、更正和改善文本的階段。"},{"en":"A teacher may guide students through the checking and editing process before final submission.","zh":"老師可能在最終提交前，帶學生完成檢查和編輯過程。"},{"en":"If editing tools make changes easy, writers may spend even more time revising.","zh":"如果編輯工具令改動容易，作家可能花更多時間修改。"},{"en":"The phrase describes the careful work after drafting.","zh":"這個短語描述起草後的仔細工作。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":4},{"front":"be sped up","meaning":"被加快","examples":[{"en":"Some people think new technology speeds up editing.","zh":"有些人以為新科技會加快編輯。"},{"en":"To be sped up means to be made faster.","zh":"「be sped up」意思是被弄得更快。"},{"en":"Online payment can speed up the checkout process in a shop.","zh":"網上付款可以加快商店結帳過程。"},{"en":"If a process is sped up too much, mistakes may be missed.","zh":"如果過程被加快太多，錯誤可能被忽略。"},{"en":"The phrase describes increasing speed.","zh":"這個短語描述速度增加。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":4},{"front":"experienced writer","meaning":"經驗豐富的作家","examples":[{"en":"The experienced writer would hardly agree.","zh":"經驗豐富的作家不大會同意。"},{"en":"An experienced writer is someone who has written for a long time and understands the process well.","zh":"「experienced writer」是長時間寫作並深入理解寫作過程的人。"},{"en":"An experienced writer knows that a short article can still need several rounds of editing.","zh":"經驗豐富的作家知道短文章仍可能需要幾輪編輯。"},{"en":"If beginners think writing is quick, an experienced writer may warn them otherwise.","zh":"如果初學者以為寫作很快，經驗豐富的作家可能會提醒他們並非如此。"},{"en":"The phrase describes a writer with practical knowledge, not just talent.","zh":"這個短語描述具有實踐知識的作家，而不只是有才華的人。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":5},{"front":"hardly agree","meaning":"不大會同意","examples":[{"en":"The experienced writer would hardly agree with that idea.","zh":"經驗豐富的作家不大會同意那個想法。"},{"en":"To hardly agree means to almost not agree at all.","zh":"「hardly agree」意思是幾乎完全不同意。"},{"en":"A teacher would hardly agree that students can learn grammar without practice.","zh":"老師不大會同意學生不練習也能學好文法。"},{"en":"If someone knows the real difficulty of writing, they will hardly agree that technology solves everything.","zh":"如果有人知道寫作真正的困難，他不大會同意科技能解決一切。"},{"en":"The phrase expresses strong but slightly indirect disagreement.","zh":"這個短語表達強烈但稍微間接的不同意。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":5},{"front":"advanced technology","meaning":"先進科技","examples":[{"en":"Advanced technology allows writers to make countless edits.","zh":"先進科技讓作家能作出無數次編輯。"},{"en":"Advanced technology means highly developed tools, systems, or machines.","zh":"「advanced technology」意思是高度發展的工具、系統或機器。"},{"en":"A hospital uses advanced technology to scan the body and detect disease early.","zh":"醫院使用先進科技掃描身體並及早發現疾病。"},{"en":"If advanced technology makes editing easy, writers may keep changing the text endlessly.","zh":"如果先進科技令編輯容易，作家可能不停修改文本。"},{"en":"The phrase describes modern tools with powerful functions.","zh":"這個短語描述具強大功能的現代工具。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":5},{"front":"allow someone the luxury of","meaning":"讓某人享有……的便利","examples":[{"en":"Technology allows the writer the luxury of countless edits.","zh":"科技讓作家享有無數次編輯的便利。"},{"en":"To allow someone the luxury of something means to give them the useful freedom or comfort of having it.","zh":"「allow someone the luxury of」某事，意思是給某人擁有它的自由、便利或舒適。"},{"en":"A quiet study room allows students the luxury of working without interruption.","zh":"安靜溫習室讓學生享有不受打擾地工作的便利。"},{"en":"If writers have the luxury of easy editing, they may revise more than necessary.","zh":"如果作家享有輕易編輯的便利，他們可能修改得超過必要。"},{"en":"The phrase suggests an advantage that may also become a temptation.","zh":"這個短語暗示一種優勢，但也可能變成誘惑。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":5},{"front":"countless edits","meaning":"無數次編輯","examples":[{"en":"Advanced technology makes countless edits possible.","zh":"先進科技使無數次編輯成為可能。"},{"en":"Countless edits are so many changes to a text that they are hard to count.","zh":"「countless edits」是多到難以計算的文本改動。"},{"en":"A student using a laptop may make countless edits before submitting an essay.","zh":"使用手提電腦的學生在提交作文前可能作出無數次編輯。"},{"en":"If every sentence can be changed easily, countless edits may delay completion.","zh":"如果每一句都能輕易修改，無數次編輯可能拖延完成。"},{"en":"The phrase emphasises repeated revision.","zh":"這個短語強調反覆修改。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":5},{"front":"temptation","meaning":"誘惑","examples":[{"en":"Endless editing is a temptation many writers find hard to resist.","zh":"無止境編輯是許多作家難以抗拒的誘惑。"},{"en":"A temptation is something attractive that makes people want to do it, even if it may not be wise.","zh":"「temptation」是吸引人想做某事的東西，即使它未必明智。"},{"en":"A phone can be a temptation when a student is trying to study.","zh":"當學生正在溫習，電話可能是一種誘惑。"},{"en":"If editing is too easy, the temptation to keep improving one sentence may slow the whole book.","zh":"如果編輯太容易，不停改善一句話的誘惑可能拖慢整本書。"},{"en":"The word describes a pull toward something appealing but risky.","zh":"這個詞描述被有吸引力但有風險的東西拉動。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":5},{"front":"hard to resist","meaning":"難以抗拒","examples":[{"en":"Many writers find repeated editing hard to resist.","zh":"許多作家覺得反覆編輯難以抗拒。"},{"en":"Hard to resist means difficult to say no to or stop doing.","zh":"「hard to resist」意思是難以拒絕或停止做。"},{"en":"Freshly baked bread can be hard to resist when someone is hungry.","zh":"當人肚餓時，新鮮出爐的麵包可能難以抗拒。"},{"en":"If editing tools are convenient, changing a sentence again and again becomes hard to resist.","zh":"如果編輯工具方便，一次又一次改句子就變得難以抗拒。"},{"en":"The phrase describes a strong attraction or urge.","zh":"這個短語描述強烈吸引力或衝動。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":5},{"front":"endlessly reworked","meaning":"被反覆修改","examples":[{"en":"A passage that is endlessly reworked may become very different.","zh":"被反覆修改的段落可能變得非常不同。"},{"en":"Endlessly reworked means changed again and again without a clear stopping point.","zh":"「endlessly reworked」意思是一次又一次被修改，而且沒有清楚停止點。"},{"en":"A school speech can become weaker if it is endlessly reworked the night before delivery.","zh":"如果演講稿在發表前一晚被反覆修改，它可能變得更弱。"},{"en":"If a paragraph is reworked too many times, it may no longer fit the rest of the essay.","zh":"如果段落被修改太多次，它可能不再配合文章其他部分。"},{"en":"The phrase warns that too much revision can damage unity.","zh":"這個短語警告過度修改可能破壞整體一致性。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":5},{"front":"end up nothing remotely like","meaning":"最終完全不像……","examples":[{"en":"The passage may end up nothing remotely like the original.","zh":"該段落最終可能完全不像原文。"},{"en":"To end up nothing remotely like something means to become completely different from it.","zh":"「end up nothing remotely like」某物，意思是最後變得與它完全不同。"},{"en":"A simple classroom plan may end up nothing remotely like the first idea after many changes.","zh":"簡單課堂計劃經過許多改動後，最終可能完全不像最初想法。"},{"en":"If a writer rewrites too much, the final paragraph may lose the original tone entirely.","zh":"如果作家重寫太多，最終段落可能完全失去原本語氣。"},{"en":"The phrase strongly emphasises how far the final version has changed.","zh":"這個短語強烈強調最終版本改變得有多遠。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":5},{"front":"the original","meaning":"原文；原本版本","examples":[{"en":"The final passage may be very different from the original.","zh":"最終段落可能與原文非常不同。"},{"en":"The original is the first or earliest version of something.","zh":"「the original」是某物最初或最早的版本。"},{"en":"A teacher may compare the original essay with the final version to show improvement.","zh":"老師可能比較原本作文與最終版本，以展示進步。"},{"en":"If too many changes are made, the original idea may disappear.","zh":"如果改動太多，原本想法可能消失。"},{"en":"The phrase contrasts the starting version with later versions.","zh":"這個短語把起始版本與後來版本作對比。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":5},{"front":"out of place","meaning":"格格不入","examples":[{"en":"The reworked passage may seem out of place.","zh":"經修改的段落可能顯得格格不入。"},{"en":"Out of place means not fitting naturally with the surrounding text, situation, or setting.","zh":"「out of place」意思是與周圍文本、情況或環境不自然地配合。"},{"en":"A formal sentence may look out of place in a friendly text message.","zh":"正式句子在友善短訊中可能看起來格格不入。"},{"en":"If one paragraph has a different tone, it may feel separate from the rest of the chapter.","zh":"如果一段語氣不同，它可能感覺與章節其餘部分分離。"},{"en":"The phrase describes something that does not belong where it is.","zh":"這個短語描述某物不屬於所在位置。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":5},{"front":"compared with","meaning":"與……相比","examples":[{"en":"The passage may look out of place compared with the rest of the text.","zh":"與文本其餘部分相比，該段可能看起來格格不入。"},{"en":"Compared with means when judged beside another thing.","zh":"「compared with」意思是與另一事物並列判斷時。"},{"en":"Compared with last year, this student’s writing is clearer and more organised.","zh":"與去年相比，這名學生的寫作更清楚、更有組織。"},{"en":"If one section sounds too formal compared with the others, it may need rewriting.","zh":"如果某部分與其他部分相比太正式，它可能需要重寫。"},{"en":"The phrase introduces a comparison.","zh":"這個短語引入比較。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":6},{"front":"trauma of self-editing","meaning":"自我編輯的痛苦","examples":[{"en":"After the trauma of self-editing, the writer shows the text to others.","zh":"經過自我編輯的痛苦後，作者把文本給其他人看。"},{"en":"The trauma of self-editing means the painful stress of judging and changing one’s own writing.","zh":"「trauma of self-editing」指評判和修改自己作品時的痛苦壓力。"},{"en":"A student may feel the trauma of self-editing when cutting a paragraph they like.","zh":"學生刪掉自己喜歡的段落時，可能感受到自我編輯的痛苦。"},{"en":"If writers are too close to their work, self-editing can feel emotionally difficult.","zh":"如果作家與作品太親近，自我編輯可能在情感上很困難。"},{"en":"The phrase uses strong language to show how painful revision can be.","zh":"這個短語使用強烈語氣，顯示修改可以多痛苦。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":6},{"front":"self-editing","meaning":"自我編輯","examples":[{"en":"Self-editing can be a difficult part of writing.","zh":"自我編輯可以是寫作中困難的一部分。"},{"en":"Self-editing means checking and improving one’s own writing before others read it.","zh":"「self-editing」意思是在別人閱讀前，檢查和改善自己的寫作。"},{"en":"A student does self-editing when they correct grammar and remove repeated ideas.","zh":"學生更正文法並刪除重複想法時，就是在自我編輯。"},{"en":"If self-editing is careful, the draft becomes clearer before feedback.","zh":"如果自我編輯仔細，初稿在得到回饋前會更清楚。"},{"en":"The phrase describes editing done by the writer themselves.","zh":"這個短語描述由作者自己完成的編輯。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":6},{"front":"look for howlers","meaning":"找出嚴重錯誤","examples":[{"en":"The writer must look for howlers before showing the text.","zh":"作者在展示文本前必須找出嚴重錯誤。"},{"en":"To look for howlers means to search for serious or embarrassing mistakes.","zh":"「look for howlers」意思是尋找嚴重或令人尷尬的錯誤。"},{"en":"A student should look for howlers, such as writing the wrong exam date, before submitting a notice.","zh":"學生提交通告前應找出嚴重錯誤，例如寫錯考試日期。"},{"en":"If obvious errors remain, readers may lose confidence in the whole text.","zh":"如果明顯錯誤仍然存在，讀者可能對整篇文本失去信心。"},{"en":"The phrase is informal and focuses on major mistakes, not tiny style choices.","zh":"這個短語較口語，集中於重大錯誤，而不是細小風格選擇。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":6},{"front":"show the text to","meaning":"把文本給……看","examples":[{"en":"It is time to show the text to other people.","zh":"是時候把文本給其他人看了。"},{"en":"To show the text to someone means to let them read it and give a reaction or opinion.","zh":"「show the text to」某人，意思是讓他閱讀並給反應或意見。"},{"en":"A student may show an essay to a classmate before handing it in.","zh":"學生可能在交作文前把文章給同學看。"},{"en":"If writers show the text to others, they may notice problems they missed alone.","zh":"如果作家把文本給其他人看，他們可能注意到自己獨自看時忽略的問題。"},{"en":"The phrase describes sharing a draft for feedback.","zh":"這個短語描述分享草稿以取得回饋。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":6},{"front":"for appraisal","meaning":"以供評價","examples":[{"en":"The writer shows the text to friends for appraisal.","zh":"作者把文本給朋友看，以供評價。"},{"en":"For appraisal means for judgement, evaluation, or feedback.","zh":"「for appraisal」意思是為了判斷、評估或給回饋。"},{"en":"A student may give a presentation plan to a teacher for appraisal.","zh":"學生可能把演講計劃交給老師以供評價。"},{"en":"If friends read a draft for appraisal, they can say whether it is clear or confusing.","zh":"如果朋友閱讀草稿以供評價，他們可以說它清楚還是混亂。"},{"en":"The phrase describes the purpose of asking others to review something.","zh":"這個短語描述請別人審閱某物的目的。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":6},{"front":"at this stage","meaning":"在這個階段","examples":[{"en":"At this stage, it is not wise to send the draft to an agent.","zh":"在這個階段，把草稿寄給經紀人並不明智。"},{"en":"At this stage means at this particular point in a process.","zh":"「at this stage」意思是在某過程中的這個特定時點。"},{"en":"At this stage of revision, students should focus on structure before grammar.","zh":"在修改的這個階段，學生應先集中於結構，再處理文法。"},{"en":"If a draft still has major problems, sending it out too early may damage its chances.","zh":"如果草稿仍有重大問題，太早寄出去可能損害機會。"},{"en":"The phrase helps organise advice according to timing.","zh":"這個短語幫助按時間安排建議。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":6},{"front":"send it off to","meaning":"把它寄給……","examples":[{"en":"It is not wise to send it off to a literary agent too early.","zh":"太早把它寄給文學經紀人並不明智。"},{"en":"To send it off to someone means to send a document or item away for their attention.","zh":"「send it off to」某人，意思是把文件或物件寄出去給對方處理。"},{"en":"A student should check an application carefully before sending it off to a university.","zh":"學生把申請寄給大學前，應仔細檢查。"},{"en":"If a writer sends a weak draft off too soon, the agent may reject it quickly.","zh":"如果作家太早把薄弱草稿寄出去，經紀人可能很快拒絕。"},{"en":"The phrase describes submitting something to another person or organisation.","zh":"這個短語描述把某物提交給另一人或組織。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":6},{"front":"literary agent","meaning":"文學經紀人","examples":[{"en":"A literary agent may consider a writer’s draft publication.","zh":"文學經紀人可能考慮作家的出版草稿。"},{"en":"A literary agent is a professional who helps writers sell their work to publishers.","zh":"「literary agent」是幫助作家把作品售予出版社的專業人士。"},{"en":"A novelist may send a synopsis and sample chapters to a literary agent.","zh":"小說家可能把概要和樣章寄給文學經紀人。"},{"en":"If an agent likes a draft, they may help the writer find a publisher.","zh":"如果經紀人喜歡草稿，他們可能幫作者尋找出版社。"},{"en":"The phrase names a middle person between writer and publisher.","zh":"這個短語指出作家與出版社之間的中介人。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":6},{"front":"direct to publishers","meaning":"直接寄給出版社","examples":[{"en":"The draft should not be sent direct to publishers too soon.","zh":"草稿不應太早直接寄給出版社。"},{"en":"Direct to publishers means straight to publishing companies without going through another person.","zh":"「direct to publishers」意思是不經其他人，直接送到出版公司。"},{"en":"Some writers send proposals direct to publishers, while others use agents.","zh":"有些作者直接寄提案給出版社，另一些則使用經紀人。"},{"en":"If a draft is sent directly too early, publishers may reject it before it is polished.","zh":"如果草稿太早直接寄出，出版社可能在它完善前拒絕。"},{"en":"The phrase describes the route by which a manuscript is submitted.","zh":"這個短語描述手稿提交的途徑。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":6},{"front":"further fine-tuning","meaning":"進一步微調","examples":[{"en":"The draft may need further fine-tuning.","zh":"草稿可能需要進一步微調。"},{"en":"Further fine-tuning means more small adjustments to improve quality.","zh":"「further fine-tuning」意思是再作細小調整，以改善質素。"},{"en":"A student’s speech may need further fine-tuning after the main ideas are clear.","zh":"當主要想法清楚後，學生的演講可能需要進一步微調。"},{"en":"If a draft is almost ready, fine-tuning can improve wording, order, and tone.","zh":"如果草稿差不多準備好，微調可以改善用詞、次序和語氣。"},{"en":"The phrase describes careful final improvement, not complete rewriting.","zh":"這個短語描述仔細的最後改善，而不是完全重寫。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":6},{"front":"be unaware of","meaning":"沒有察覺","examples":[{"en":"The author may be unaware of problems in the draft.","zh":"作者可能沒有察覺草稿中的問題。"},{"en":"To be unaware of something means not to know or notice it.","zh":"「be unaware of」某事，意思是不知道或沒有注意到它。"},{"en":"A student may be unaware of a spelling mistake after reading the same essay many times.","zh":"學生多次閱讀同一篇作文後，可能沒有察覺串字錯誤。"},{"en":"If writers are unaware of weaknesses, outside feedback becomes important.","zh":"如果作家沒有察覺弱點，外部回饋就變得重要。"},{"en":"The phrase describes a lack of awareness.","zh":"這個短語描述缺乏意識。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":7},{"front":"be approached","meaning":"被接洽","examples":[{"en":"Once an agent has been approached, rejection can be difficult to reverse.","zh":"一旦經紀人被接洽，被拒就可能難以逆轉。"},{"en":"When someone has been approached, they have been contacted with a request or proposal.","zh":"當某人 has been approached，意思是有人帶着請求或提案聯絡了他。"},{"en":"A teacher may be approached by students who want to start a new club.","zh":"想開新社團的學生可能接洽老師。"},{"en":"If an agent is approached with a weak draft, their first impression may be hard to change.","zh":"如果以薄弱草稿接洽經紀人，對方的第一印象可能很難改變。"},{"en":"The phrase describes making contact with someone for help or consideration.","zh":"這個短語描述為求幫助或考慮而聯絡某人。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":7},{"front":"reject a draft publication","meaning":"拒絕出版草稿","examples":[{"en":"An agent may reject a draft publication.","zh":"經紀人可能拒絕出版草稿。"},{"en":"To reject a draft publication means to refuse to accept or represent an unfinished manuscript.","zh":"「reject a draft publication」意思是拒絕接受或代理未完成的手稿。"},{"en":"A magazine may reject a draft article if it does not fit the theme.","zh":"如果草稿文章不符合主題，雜誌可能拒絕它。"},{"en":"If a draft is rejected too early, the writer may lose a useful chance.","zh":"如果草稿太早被拒，作家可能失去有用機會。"},{"en":"The phrase describes refusal at the submission stage.","zh":"這個短語描述提交階段的拒絕。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":7},{"front":"revamped text","meaning":"經修改的文本","examples":[{"en":"It is difficult to ask an agent to consider the revamped text again.","zh":"要求經紀人再次考慮經修改的文本是困難的。"},{"en":"A revamped text is a piece of writing that has been revised and improved substantially.","zh":"「revamped text」是經過大幅修改和改善的文字作品。"},{"en":"A student may submit a revamped essay after changing the introduction and examples.","zh":"學生改動引言和例子後，可能提交經修改的作文。"},{"en":"If a text is revamped, it may become clearer, stronger, and more suitable for readers.","zh":"如果文本被修改，它可能變得更清楚、更有力、更適合讀者。"},{"en":"The phrase describes a revised version, not the original draft.","zh":"這個短語描述修訂版本，而不是原本草稿。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":7},{"front":"be considered again","meaning":"再次被考慮","examples":[{"en":"The writer may want the revised text to be considered again.","zh":"作者可能希望修訂文本再次被考慮。"},{"en":"To be considered again means to be looked at or judged another time.","zh":"「be considered again」意思是再次被審視或評判。"},{"en":"A student may ask for an answer to be considered again if a marking error occurred.","zh":"如果出現評分錯誤，學生可能要求答案再次被考慮。"},{"en":"If an agent has already rejected a draft, getting it considered again may be difficult.","zh":"如果經紀人已拒絕草稿，要讓它再次被考慮可能很困難。"},{"en":"The phrase describes a second chance at evaluation.","zh":"這個短語描述獲得第二次評估機會。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":7},{"front":"synopsis of the book","meaning":"書本概要","examples":[{"en":"It helps to offer a synopsis of the book.","zh":"提供書本概要會有幫助。"},{"en":"A synopsis of the book is a short summary of the main story, argument, or content.","zh":"「synopsis of the book」是書本主要故事、論點或內容的簡短摘要。"},{"en":"A novelist may send a synopsis of the book before sending the full manuscript.","zh":"小說家可能在寄完整手稿前，先寄書本概要。"},{"en":"If an agent reads a clear synopsis, they can understand the book quickly.","zh":"如果經紀人讀到清楚概要，他們可以快速理解該書。"},{"en":"The phrase describes a brief overview used for review.","zh":"這個短語描述用於審閱的簡短概覽。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":7},{"front":"if it is a novel","meaning":"如果它是小說","examples":[{"en":"A synopsis is useful if it is a novel.","zh":"如果它是小說，概要會有用。"},{"en":"If it is a novel means on the condition that the book is a fictional story.","zh":"「if it is a novel」意思是條件是該書是虛構故事。"},{"en":"If it is a novel, readers may want to know the plot, characters, and ending.","zh":"如果它是小說，讀者可能想知道情節、角色和結局。"},{"en":"If a writer submits fiction, a synopsis can show whether the story works as a whole.","zh":"如果作者提交小說，概要可以顯示故事整體是否有效。"},{"en":"The phrase introduces a condition based on book type.","zh":"這個短語根據書本類型引入條件。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":7},{"front":"an outline","meaning":"大綱","examples":[{"en":"An outline is useful if the book is a textbook.","zh":"如果書本是教科書，大綱會有用。"},{"en":"An outline is a planned list of main sections, chapters, or ideas.","zh":"「an outline」是主要部分、章節或想法的計劃清單。"},{"en":"A student may write an outline before starting an essay.","zh":"學生開始寫作文前，可能先寫大綱。"},{"en":"If a textbook has a clear outline, readers can see how the subject is organised.","zh":"如果教科書有清楚大綱，讀者可以看到科目如何組織。"},{"en":"The phrase describes a skeleton plan before full writing.","zh":"這個短語描述完整寫作前的骨架計劃。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":7},{"front":"act as a guide for","meaning":"作為……的指引","examples":[{"en":"The synopsis acts as a guide for the author.","zh":"概要作為作者的指引。"},{"en":"To act as a guide for someone means to help them know what direction to follow.","zh":"「act as a guide for」某人，意思是幫助他知道應跟隨甚麼方向。"},{"en":"A revision timetable acts as a guide for students before exams.","zh":"溫習時間表在考試前作為學生的指引。"},{"en":"If a synopsis guides the author, it can prevent the story from losing direction.","zh":"如果概要引導作者，它可以防止故事失去方向。"},{"en":"The phrase describes something that gives structure or direction.","zh":"這個短語描述提供結構或方向的東西。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":7},{"front":"general reference","meaning":"一般參考","examples":[{"en":"The outline can serve as a general reference for friends and agents.","zh":"大綱可以作為朋友和經紀人的一般參考。"},{"en":"A general reference is something people can consult for basic information.","zh":"「general reference」是人們可以查閱以取得基本資料的東西。"},{"en":"A school handbook serves as a general reference for rules and procedures.","zh":"學校手冊作為校規和程序的一般參考。"},{"en":"If readers have a general reference, they can understand the project without reading every page.","zh":"如果讀者有一般參考，他們不用讀每一頁也能理解項目。"},{"en":"The phrase describes a useful overview source.","zh":"這個短語描述有用的概覽來源。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":7},{"front":"tempting to","meaning":"很吸引人去……","examples":[{"en":"It is tempting to send the draft to every possible agent.","zh":"把草稿寄給每一個可能的經紀人很吸引。"},{"en":"It is tempting to do something means it feels attractive or hard to resist.","zh":"「tempting to」做某事，意思是該行動很吸引或難以抗拒。"},{"en":"It is tempting to check your phone while studying, especially when messages arrive.","zh":"溫習時查看電話很吸引，尤其是訊息到來時。"},{"en":"If a writer fears rejection, it may be tempting to contact many agents at once.","zh":"如果作家害怕被拒，一次過聯絡很多經紀人可能很吸引。"},{"en":"The phrase suggests an action is appealing but may not be wise.","zh":"這個短語暗示行動有吸引力，但未必明智。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":7},{"front":"draft","meaning":"草稿","examples":[{"en":"The writer may send the draft to agents.","zh":"作者可能把草稿寄給經紀人。"},{"en":"A draft is an unfinished version of a piece of writing.","zh":"「draft」是一篇文字的未完成版本。"},{"en":"A student may write a draft before producing the final essay.","zh":"學生可能先寫草稿，再完成最終作文。"},{"en":"If a draft is shown to others, feedback can help improve it.","zh":"如果草稿給別人看，回饋可以幫助改善它。"},{"en":"The word describes work in progress, not the final version.","zh":"這個詞描述進行中的作品，而不是最終版本。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":8},{"front":"every possible agent","meaning":"每一個可能的經紀人","examples":[{"en":"It is unwise to send the draft to every possible agent at one time.","zh":"同一時間把草稿寄給每一個可能的經紀人並不明智。"},{"en":"Every possible agent means all agents the writer can think of or find.","zh":"「every possible agent」指作者能想到或找到的所有經紀人。"},{"en":"A student should not email every possible teacher for help before checking the instructions.","zh":"學生不應在查看指示前，就電郵每一位可能幫忙的老師。"},{"en":"If a writer contacts every agent at once, they may waste chances for later revision.","zh":"如果作家一次過聯絡所有經紀人，他們可能浪費之後修改後再提交的機會。"},{"en":"The phrase suggests a broad and perhaps careless approach.","zh":"這個短語暗示做法很廣泛，也可能有點草率。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":8},{"front":"at one time","meaning":"同一時間","examples":[{"en":"Sending the draft to every agent at one time is probably unwise.","zh":"同一時間把草稿寄給每位經紀人大概不明智。"},{"en":"At one time means at the same moment or during the same period.","zh":"「at one time」意思是在同一時刻或同一段時間內。"},{"en":"A small lift should not carry too many people at one time.","zh":"小型升降機不應同一時間載太多人。"},{"en":"If a writer sends the draft everywhere at one time, rejection from all sides may come quickly.","zh":"如果作家同一時間把草稿寄到所有地方，拒絕可能很快從各方而來。"},{"en":"The phrase describes simultaneous action.","zh":"這個短語描述同時進行的行動。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":8},{"front":"reject something out of hand","meaning":"斷然拒絕","examples":[{"en":"Some agents may reject the publication out of hand.","zh":"有些經紀人可能斷然拒絕該出版物。"},{"en":"To reject something out of hand means to refuse it immediately without serious consideration.","zh":"「reject something out of hand」意思是立即拒絕某事，而不認真考慮。"},{"en":"A teacher should not reject a student’s unusual idea out of hand before hearing the reason.","zh":"老師不應在聽原因前就斷然拒絕學生的不尋常想法。"},{"en":"If a draft looks careless, an agent may reject it quickly without reading much.","zh":"如果草稿看起來粗心，經紀人可能很快拒絕而不讀太多。"},{"en":"The phrase describes firm and immediate refusal.","zh":"這個短語描述堅決而即時的拒絕。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":8},{"front":"proffer advice","meaning":"提供建議","examples":[{"en":"Other agents may proffer invaluable advice.","zh":"其他經紀人可能提供非常寶貴的建議。"},{"en":"To proffer advice means to offer advice, usually in a formal or helpful way.","zh":"「proffer advice」意思是提供建議，通常較正式或出於幫助。"},{"en":"A senior teacher may proffer advice to new teachers after observing their lessons.","zh":"資深老師觀課後可能向新老師提供建議。"},{"en":"If an agent proffers advice, the writer may improve the draft before submitting elsewhere.","zh":"如果經紀人提供建議，作者可能在提交到其他地方前改善草稿。"},{"en":"The phrase is more formal than “give advice”.","zh":"這個短語比 “give advice” 更正式。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":8},{"front":"invaluable advice","meaning":"非常寶貴的建議","examples":[{"en":"Some agents may offer invaluable advice.","zh":"有些經紀人可能提供非常寶貴的建議。"},{"en":"Invaluable advice is advice that is extremely useful and important.","zh":"「invaluable advice」是極其有用和重要的建議。"},{"en":"A teacher’s advice about essay structure can be invaluable before an exam.","zh":"老師關於作文結構的建議在考試前可能非常寶貴。"},{"en":"If advice helps a writer avoid repeated rejection, it may be more valuable than praise.","zh":"如果建議幫助作家避免反覆被拒，它可能比讚美更有價值。"},{"en":"The phrase means the advice is so useful that it is hard to measure its value.","zh":"這個短語意思是建議非常有用，其價值難以衡量。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":8},{"front":"direction to be taken","meaning":"應採取的方向","examples":[{"en":"An agent may advise on the direction to be taken.","zh":"經紀人可能就應採取的方向提出建議。"},{"en":"The direction to be taken means the future path, approach, or strategy to follow.","zh":"「direction to be taken」指未來應跟隨的路徑、方法或策略。"},{"en":"A career counsellor may advise a student on the direction to be taken after graduation.","zh":"職業輔導員可能就畢業後應採取的方向建議學生。"},{"en":"If a book lacks focus, advice on direction can help the writer reshape it.","zh":"如果一本書缺乏焦點，關於方向的建議可以幫作者重塑它。"},{"en":"The phrase describes the next course of action.","zh":"這個短語描述下一步行動方向。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":8},{"front":"be of use in","meaning":"對……有用","examples":[{"en":"Such information may be of use in getting a contract.","zh":"這類資料可能對取得合約有用。"},{"en":"To be of use in something means to be helpful for achieving it.","zh":"「be of use in」某事，意思是對達成它有幫助。"},{"en":"A clear timetable may be of use in preparing for exams.","zh":"清楚時間表可能對準備考試有用。"},{"en":"If feedback improves a manuscript, it may be of use in persuading an agent.","zh":"如果回饋改善手稿，它可能對說服經紀人有用。"},{"en":"The phrase is a formal way to say “be useful for”.","zh":"這個短語是 “be useful for” 的正式說法。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":8},{"front":"be given a contract","meaning":"獲得合約","examples":[{"en":"A writer may finally be given a contract by an agent or publisher.","zh":"作家最終可能獲經紀人或出版社給予合約。"},{"en":"To be given a contract means to receive a formal agreement to work with someone.","zh":"「be given a contract」意思是收到與某人合作的正式協議。"},{"en":"A tutor may be given a contract after a school accepts their proposal.","zh":"如果學校接受導師的提案，導師可能獲得合約。"},{"en":"If a writer is given a contract, their book has moved closer to publication.","zh":"如果作家獲得合約，他的書就更接近出版。"},{"en":"The phrase describes formal acceptance in professional work.","zh":"這個短語描述專業工作中的正式接納。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":8},{"front":"the lucky few","meaning":"少數幸運者","examples":[{"en":"The lucky few are taken on by publishers or agents.","zh":"少數幸運者會獲出版社或經紀人接納。"},{"en":"The lucky few means the small number of people who succeed when many others do not.","zh":"「the lucky few」指在很多人失敗時成功的少數人。"},{"en":"In a popular scholarship competition, only the lucky few receive full funding.","zh":"在熱門獎學金比賽中，只有少數幸運者獲得全額資助。"},{"en":"If only a few writers are accepted, publication is clearly competitive.","zh":"如果只有少數作家被接納，出版明顯競爭激烈。"},{"en":"The phrase stresses rarity and good fortune.","zh":"這個短語強調稀少和幸運。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":8},{"front":"be taken on by","meaning":"獲……接納；被……簽下","examples":[{"en":"Some writers are taken on by publishers or agents.","zh":"有些作家獲出版社或經紀人接納。"},{"en":"To be taken on by someone means to be accepted, hired, or represented by them.","zh":"「be taken on by」某人，意思是被他接納、聘用或代理。"},{"en":"A trainee may be taken on by a company after a successful interview.","zh":"見工成功後，實習生可能被公司聘用。"},{"en":"If a writer is taken on by an agent, the agent may help sell the book.","zh":"如果作家被經紀人簽下，經紀人可能幫他出售書本。"},{"en":"The phrase describes professional acceptance.","zh":"這個短語描述專業上的接納。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":8},{"front":"be subjected to","meaning":"被交給……處理","examples":[{"en":"Their books are subjected to a number of readers.","zh":"他們的書會被交給多名審稿讀者處理。"},{"en":"To be subjected to something means to be made to go through it, often as a test or review.","zh":"「be subjected to」某事，意思是被迫或被安排經歷它，常作為測試或審查。"},{"en":"A new school policy may be subjected to public consultation before approval.","zh":"新校政在批准前可能被交給公眾諮詢審視。"},{"en":"If a manuscript is subjected to readers, they will judge its quality and usefulness.","zh":"如果手稿被交給讀者審閱，他們會判斷其質素和用途。"},{"en":"The phrase suggests the text must undergo examination.","zh":"這個短語暗示文本必須接受檢查。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":9},{"front":"a number of readers","meaning":"多名審稿讀者","examples":[{"en":"A book may be read by a number of readers before publication.","zh":"一本書在出版前可能由多名審稿讀者閱讀。"},{"en":"A number of readers means several people who read and judge a manuscript.","zh":"「a number of readers」指幾位閱讀並評判手稿的人。"},{"en":"A school magazine article may be checked by a number of teachers before printing.","zh":"學校雜誌文章在印刷前可能由多名老師檢查。"},{"en":"If several readers review a book, different weaknesses may be discovered.","zh":"如果幾位讀者審閱一本書，不同弱點可能被發現。"},{"en":"The phrase describes multiple reviewers.","zh":"這個短語描述多名審閱者。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":9},{"front":"vet a book","meaning":"審查一本書","examples":[{"en":"The readers’ job is to vet a book.","zh":"讀者的工作是審查一本書。"},{"en":"To vet a book means to examine it carefully before deciding whether it is acceptable.","zh":"「vet a book」意思是在決定是否接受前仔細檢查一本書。"},{"en":"A school may vet library books before placing them on shelves.","zh":"學校可能在把書放上書架前審查圖書。"},{"en":"If readers vet a manuscript, they may check quality, accuracy, and market suitability.","zh":"如果讀者審查手稿，他們可能檢查質素、準確性和市場適合度。"},{"en":"The phrase describes careful screening.","zh":"這個短語描述仔細篩選。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":9},{"front":"worth publishing","meaning":"值得出版","examples":[{"en":"The readers decide whether the book is worth publishing.","zh":"讀者決定這本書是否值得出版。"},{"en":"Worth publishing means good, useful, or marketable enough to be printed and sold.","zh":"「worth publishing」意思是好到、有用到或有市場到值得印刷和出售。"},{"en":"A school anthology is worth publishing if the stories are strong and well edited.","zh":"如果學校文集故事有力且編輯良好，它就值得出版。"},{"en":"If a book is not worth publishing yet, the writer may need more revision.","zh":"如果一本書暫時不值得出版，作者可能需要更多修改。"},{"en":"The phrase judges whether publication is justified.","zh":"這個短語判斷出版是否有充分理由。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":9},{"front":"as it stands","meaning":"以目前狀態","examples":[{"en":"The readers decide whether the text as it stands is acceptable.","zh":"讀者決定文本以目前狀態是否可接受。"},{"en":"As it stands means in its present form, without further changes.","zh":"「as it stands」意思是以現在形式，不再進一步改動。"},{"en":"As it stands, the essay needs a clearer introduction before it can receive a high mark.","zh":"以目前狀態，這篇作文需要更清楚的引言，才可取得高分。"},{"en":"If a manuscript is acceptable as it stands, only minor edits may be needed.","zh":"如果手稿以目前狀態可接受，可能只需要小修改。"},{"en":"The phrase describes the current condition of something.","zh":"這個短語描述某物的現時狀況。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":9},{"front":"be accepted by","meaning":"獲……接受","examples":[{"en":"The book may finally be accepted by a publisher.","zh":"這本書最終可能獲出版社接受。"},{"en":"To be accepted by someone means to be approved or agreed to by them.","zh":"「be accepted by」某人，意思是獲得對方批准或同意。"},{"en":"A student may be accepted by a university after submitting strong results and references.","zh":"學生提交優秀成績和推薦信後，可能獲大學取錄。"},{"en":"If a book is accepted by a publisher, it can move into editing and production.","zh":"如果一本書獲出版社接受，它可以進入編輯和製作階段。"},{"en":"The phrase describes formal approval.","zh":"這個短語描述正式批准。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":9},{"front":"one of the greatest difficulties","meaning":"最大困難之一","examples":[{"en":"One of the greatest difficulties is accepting the publisher’s changes.","zh":"最大困難之一是接受出版社的修改。"},{"en":"One of the greatest difficulties means one of the hardest problems in a situation.","zh":"「one of the greatest difficulties」意思是某情況中最困難的問題之一。"},{"en":"One of the greatest difficulties in learning English is using grammar naturally under pressure.","zh":"學英文最大困難之一是在壓力下自然使用文法。"},{"en":"If a writer must accept major changes, emotional attachment to the text can make it hard.","zh":"如果作家必須接受重大改動，對文本的情感依附會令事情變難。"},{"en":"The phrase highlights a major challenge, not a small inconvenience.","zh":"這個短語突出重大挑戰，而不是小不便。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":9},{"front":"lie in","meaning":"在於","examples":[{"en":"The difficulty lies in taking on board the publisher’s alterations.","zh":"困難在於接受並考慮出版社的修改。"},{"en":"To lie in something means that the main problem or explanation is found there.","zh":"「lie in」某事，意思是主要問題或解釋位於那裡。"},{"en":"The difficulty of public speaking often lies in controlling nerves, not knowing the topic.","zh":"公開演說的困難常在於控制緊張，而不是不懂題目。"},{"en":"If the difficulty lies in accepting criticism, writers need emotional flexibility.","zh":"如果困難在於接受批評，作家就需要情緒彈性。"},{"en":"The phrase identifies where the real issue is.","zh":"這個短語指出真正問題所在。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":9},{"front":"take on board","meaning":"接受並考慮","examples":[{"en":"The writer must take on board the publisher’s alterations.","zh":"作者必須接受並考慮出版社的修改。"},{"en":"To take on board advice or changes means to accept them seriously and consider using them.","zh":"「take on board」建議或改動，意思是認真接受並考慮使用它們。"},{"en":"A student should take on board a teacher’s comments before rewriting an essay.","zh":"學生重寫作文前，應接受並考慮老師的評語。"},{"en":"If a writer refuses to take feedback on board, the book may not improve.","zh":"如果作家拒絕接受回饋，書本可能無法改善。"},{"en":"The phrase describes accepting and thinking about outside input.","zh":"這個短語描述接受並思考外來意見。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":9},{"front":"publisher’s alterations","meaning":"出版社的修改","examples":[{"en":"The publisher’s alterations may be difficult for the writer to accept.","zh":"出版社的修改可能令作者難以接受。"},{"en":"Publisher’s alterations are changes suggested or required by the publisher.","zh":"「publisher’s alterations」是出版社建議或要求的改動。"},{"en":"A publisher may ask for shorter chapters, clearer titles, or simpler wording.","zh":"出版社可能要求章節更短、標題更清楚或用詞更簡單。"},{"en":"If alterations affect the writer’s favourite passages, accepting them can feel painful.","zh":"如果修改影響作者最喜歡的段落，接受它們可能令人痛苦。"},{"en":"The phrase describes edits coming from the publishing side.","zh":"這個短語描述來自出版方的編輯改動。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":9},{"front":"overall story","meaning":"整體故事","examples":[{"en":"The overall story of the book may be acceptable.","zh":"書本的整體故事可能可以接受。"},{"en":"The overall story is the main plot or general narrative of a book.","zh":"「overall story」是一本書的主要情節或一般敘事。"},{"en":"A teacher may say the overall story is strong even if some scenes need rewriting.","zh":"老師可能說整體故事很強，即使有些場景需要重寫。"},{"en":"If the overall story works, editing may focus on structure, pace, and style.","zh":"如果整體故事有效，編輯可能集中於結構、節奏和風格。"},{"en":"The phrase describes the big picture of the narrative.","zh":"這個短語描述敘事的大局。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":9},{"front":"thrust of the book","meaning":"書本主旨","examples":[{"en":"The thrust of the book may be acceptable to the publisher.","zh":"書本主旨可能獲出版社接受。"},{"en":"The thrust of the book is its main argument, direction, or central purpose.","zh":"「thrust of the book」是書的主要論點、方向或核心目的。"},{"en":"The thrust of a textbook may be to make difficult ideas easier for beginners.","zh":"教科書主旨可能是令初學者更容易理解困難概念。"},{"en":"If the thrust is strong but details are weak, the publisher may still ask for revisions.","zh":"如果主旨有力但細節薄弱，出版社仍可能要求修改。"},{"en":"The phrase describes the central drive of the book.","zh":"這個短語描述書本的核心推動方向。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":10},{"front":"conform to","meaning":"符合……","examples":[{"en":"The text will probably have to conform to an in-house style.","zh":"文本大概必須符合出版社內部風格規範。"},{"en":"To conform to something means to follow its rules, standards, or pattern.","zh":"「conform to」某事，意思是跟從其規則、標準或模式。"},{"en":"Students must conform to exam instructions when writing answers.","zh":"學生作答時必須符合考試指示。"},{"en":"If a book must conform to a publisher’s style, spelling and punctuation may be changed.","zh":"如果一本書必須符合出版社風格，拼寫和標點可能被改動。"},{"en":"The phrase describes fitting an external standard.","zh":"這個短語描述配合外部標準。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":10},{"front":"in-house style","meaning":"內部風格規範","examples":[{"en":"The publisher may require the book to follow an in-house style.","zh":"出版社可能要求書本跟隨內部風格規範。"},{"en":"An in-house style is a publisher’s own set of rules for spelling, punctuation, formatting, and language.","zh":"「in-house style」是出版社自己關於拼寫、標點、格式和語言的一套規則。"},{"en":"A newspaper may have an in-house style for writing names, dates, and headlines.","zh":"報章可能有關於姓名、日期和標題寫法的內部風格規範。"},{"en":"If every book follows the same style, the publisher’s output looks consistent.","zh":"如果每本書都跟隨同一風格，出版社作品看起來會一致。"},{"en":"The phrase describes internal editorial rules.","zh":"這個短語描述內部編輯規則。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":10},{"front":"as regards","meaning":"關於；至於","examples":[{"en":"The style may cover language, spelling and punctuation.","zh":"該風格可能涵蓋語言、拼寫和標點。"},{"en":"As regards means concerning or in relation to a particular topic.","zh":"「as regards」意思是關於或就某個題目而言。"},{"en":"As regards homework, the school expects students to submit it on time.","zh":"至於功課，學校期望學生準時提交。"},{"en":"If a publisher gives rules as regards punctuation, the writer must follow them carefully.","zh":"如果出版社就標點給出規則，作者必須仔細遵守。"},{"en":"The phrase is formal and introduces the area being discussed.","zh":"這個短語較正式，用來引入正在討論的範疇。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":10},{"front":"spelling and punctuation","meaning":"拼寫和標點","examples":[{"en":"The publisher may change spelling and punctuation.","zh":"出版社可能改變拼寫和標點。"},{"en":"Spelling and punctuation refer to how words are written and how marks such as commas and full stops are used.","zh":"「spelling and punctuation」指字詞如何書寫，以及逗號和句號等標記如何使用。"},{"en":"A teacher may correct spelling and punctuation before marking the ideas in an essay.","zh":"老師可能在評改文章想法前先更正拼寫和標點。"},{"en":"If spelling and punctuation are inconsistent, a text can look careless.","zh":"如果拼寫和標點不一致，文本可能看起來粗心。"},{"en":"The phrase describes basic written accuracy.","zh":"這個短語描述基本書面準確性。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":10},{"front":"more seriously","meaning":"更嚴重的是","examples":[{"en":"More seriously, the integrity of the text may be challenged.","zh":"更嚴重的是，文本的完整性可能受到挑戰。"},{"en":"More seriously introduces a point that is more important or worrying than the previous one.","zh":"「more seriously」引出比前一點更重要或更令人擔心的內容。"},{"en":"The essay has spelling mistakes; more seriously, its argument is unclear.","zh":"這篇作文有串字錯誤；更嚴重的是，其論點不清楚。"},{"en":"If edits affect the core meaning, the problem is more serious than style changes.","zh":"如果修改影響核心意思，問題就比風格改動更嚴重。"},{"en":"The phrase signals a stronger concern.","zh":"這個短語標示更強烈的關注。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":10},{"front":"integrity of the text","meaning":"文本的完整性","examples":[{"en":"The integrity of the text may be challenged.","zh":"文本的完整性可能受到挑戰。"},{"en":"The integrity of the text is the wholeness, honesty, and original meaning of the writing.","zh":"「integrity of the text」是文字作品的完整、真實和原本意思。"},{"en":"A teacher may protect the integrity of a student’s poem by correcting grammar without changing the voice.","zh":"老師可以更正文法而不改變學生詩作的聲音，以保護文本完整性。"},{"en":"If edits remove the central argument, the integrity of the text is damaged.","zh":"如果修改刪去核心論點，文本完整性就受損。"},{"en":"The phrase describes whether the writing still remains true to itself.","zh":"這個短語描述作品是否仍忠於自身。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":10},{"front":"be challenged","meaning":"被質疑；受到挑戰","examples":[{"en":"The text’s integrity may be challenged by the publisher.","zh":"文本的完整性可能被出版社質疑。"},{"en":"To be challenged means to be questioned, tested, or put under pressure.","zh":"「be challenged」意思是被質疑、被測試或受到壓力。"},{"en":"A student’s answer may be challenged if it lacks evidence.","zh":"如果學生答案缺乏證據，它可能受到質疑。"},{"en":"If a publisher questions major parts of a book, the writer’s original vision may be challenged.","zh":"如果出版社質疑書中主要部分，作者原本構想可能受到挑戰。"},{"en":"The phrase describes pressure from criticism or demands.","zh":"這個短語描述來自批評或要求的壓力。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":10},{"front":"require radical re-drafting","meaning":"需要大幅重寫","examples":[{"en":"The publisher’s changes may require radical re-drafting.","zh":"出版社的修改可能需要大幅重寫。"},{"en":"To require radical re-drafting means to need major rewriting, not just small corrections.","zh":"「require radical re-drafting」意思是需要重大重寫，而不只是小更正。"},{"en":"A weak report may require radical re-drafting if its argument is in the wrong order.","zh":"如果報告論點次序錯誤，薄弱報告可能需要大幅重寫。"},{"en":"If a publisher asks for radical re-drafting, the writer may have to rebuild whole chapters.","zh":"如果出版社要求大幅重寫，作者可能要重建整個章節。"},{"en":"The phrase describes a large and difficult revision task.","zh":"這個短語描述大型而困難的修改任務。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":10},{"front":"unpalatable to","meaning":"令……難以接受","examples":[{"en":"Radical re-drafting is usually unpalatable to the author.","zh":"大幅重寫通常令作者難以接受。"},{"en":"Unpalatable to someone means unpleasant or difficult for them to accept.","zh":"「unpalatable to」某人，意思是令他不愉快或難以接受。"},{"en":"A pay cut is unpalatable to workers even if a company says it is necessary.","zh":"即使公司說減薪是必要，減薪對員工來說仍難以接受。"},{"en":"If a writer must delete favourite chapters, the change may feel unpalatable.","zh":"如果作家必須刪去最喜歡的章節，改動可能令人難以接受。"},{"en":"The phrase describes something hard to accept emotionally or practically.","zh":"這個短語描述情感上或實際上難以接受的事情。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":10},{"front":"creation period","meaning":"創作期","examples":[{"en":"A book’s creation period is complex and unnerving.","zh":"一本書的創作期複雜且令人不安。"},{"en":"A creation period is the time during which something is planned, written, built, or developed.","zh":"「creation period」是某物被規劃、書寫、建造或發展的時期。"},{"en":"A school play’s creation period includes writing, rehearsing, designing costumes, and solving problems.","zh":"學校話劇的創作期包括寫劇本、排練、設計服裝和解決問題。"},{"en":"If a book’s creation period is long, the writer may experience both hope and exhaustion.","zh":"如果一本書的創作期很長，作者可能同時經歷希望和疲憊。"},{"en":"The phrase describes the development stage before the finished work appears.","zh":"這個短語描述完成作品出現前的發展階段。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":10},{"front":"unnerving","meaning":"令人不安的","examples":[{"en":"The creation period can be complex and unnerving.","zh":"創作期可以複雜且令人不安。"},{"en":"Unnerving means making someone feel worried, unsettled, or less confident.","zh":"「unnerving」意思是令人擔心、不安或失去信心。"},{"en":"It can be unnerving to give a speech in front of a silent audience.","zh":"在沉默的觀眾面前演講可能令人不安。"},{"en":"If a publisher requests major changes, the writer may feel unsettled and unsure.","zh":"如果出版社要求重大改動，作者可能感到不安和不確定。"},{"en":"The word describes emotional discomfort caused by pressure or uncertainty.","zh":"這個詞描述由壓力或不確定造成的情緒不適。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":11},{"front":"reworkings","meaning":"重新加工；修改","examples":[{"en":"The publisher’s reworkings can be difficult for the writer.","zh":"出版社的重新修改對作者來說可能很困難。"},{"en":"Reworkings are revised versions or repeated changes made to a text.","zh":"「reworkings」是文本的修訂版本或反覆改動。"},{"en":"A teacher may ask for several reworkings of an essay before it becomes clear.","zh":"老師可能要求學生多次修改作文，直到它變得清楚。"},{"en":"If reworkings improve structure but remove the writer’s voice, conflict may arise.","zh":"如果修改改善結構但移除作者聲音，衝突可能出現。"},{"en":"The phrase describes repeated revision of existing material.","zh":"這個短語描述對已有材料的反覆修改。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":11},{"front":"text amputations","meaning":"大幅刪改文本","examples":[{"en":"Text amputations can be a tortuous process.","zh":"大幅刪改文本可以是一個曲折艱難的過程。"},{"en":"Text amputations means large, painful cuts made to a piece of writing.","zh":"「text amputations」指對文字作品作出大幅而痛苦的刪剪。"},{"en":"A student may feel hurt when a favourite paragraph is cut from an essay.","zh":"當最喜歡的段落被作文刪走，學生可能感到受傷。"},{"en":"If a chapter is too long, text amputations may be needed to keep readers focused.","zh":"如果章節太長，可能需要大幅刪改文本，以保持讀者專注。"},{"en":"The phrase is dramatic because it compares editing to cutting off a body part.","zh":"這個短語很戲劇化，因為它把編輯比作切除身體部分。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":11},{"front":"tortuous process","meaning":"曲折艱難的過程","examples":[{"en":"The publisher’s edits can be a tortuous process.","zh":"出版社的編輯可以是一個曲折艱難的過程。"},{"en":"A tortuous process is a long, difficult, and complicated process.","zh":"「tortuous process」是漫長、困難且複雜的過程。"},{"en":"Applying for a complicated visa can be a tortuous process for families.","zh":"申請複雜簽證對家庭來說可能是曲折艱難的過程。"},{"en":"If every revision creates new problems, editing becomes slow and painful.","zh":"如果每次修改都製造新問題，編輯就變得緩慢而痛苦。"},{"en":"The phrase describes a process that is not straightforward.","zh":"這個短語描述不直接順利的過程。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":11},{"front":"painful period","meaning":"痛苦時期","examples":[{"en":"For many writers, the most painful period comes after acceptance.","zh":"對許多作家來說，最痛苦時期在獲接納後才來臨。"},{"en":"A painful period is a time that is emotionally difficult or stressful.","zh":"「painful period」是情緒上困難或有壓力的一段時間。"},{"en":"A student may face a painful period after failing an important exam.","zh":"學生在重要考試失敗後可能面對痛苦時期。"},{"en":"If a writer’s accepted book is heavily changed, the joy of acceptance may turn into stress.","zh":"如果獲接納的書被大幅修改，接納的喜悅可能變成壓力。"},{"en":"The phrase describes a difficult stage in a longer process.","zh":"這個短語描述較長過程中的困難階段。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":11},{"front":"put together for the printer","meaning":"排版送印","examples":[{"en":"The writer waits for the text to be put together for the printer.","zh":"作者等待文本被排版送印。"},{"en":"To be put together for the printer means to be arranged and prepared for printing.","zh":"「put together for the printer」意思是被整理和準備作印刷。"},{"en":"A school magazine must be put together for the printer after all articles are checked.","zh":"學校雜誌在所有文章檢查後，必須排版送印。"},{"en":"If the text is being prepared for printing, the writer may have little left to change.","zh":"如果文本正在準備印刷，作者可能已沒有太多可改動。"},{"en":"The phrase describes the production stage before printing.","zh":"這個短語描述印刷前的製作階段。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":11},{"front":"by this stage","meaning":"到了這個階段","examples":[{"en":"By this stage, the writer may be sick of the text.","zh":"到了這個階段，作者可能已厭倦該文本。"},{"en":"By this stage means by this point in the process.","zh":"「by this stage」意思是到了過程中的這一點。"},{"en":"By this stage of exam preparation, students should be practising past papers.","zh":"到了備考的這個階段，學生應該在做歷屆試題。"},{"en":"If a writer has read the same book for months, tiredness is understandable by this stage.","zh":"如果作家數月來一直讀同一本書，到了這個階段感到疲倦是可以理解的。"},{"en":"The phrase marks a later point after many earlier steps.","zh":"這個短語標示許多早前步驟後的較後時點。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":11},{"front":"not uncommon for","meaning":"……並不罕見","examples":[{"en":"It is not uncommon for writers to be sick of their own text.","zh":"作家厭倦自己的文本並不罕見。"},{"en":"Not uncommon for someone means it happens fairly often to that group.","zh":"「not uncommon for」某群體，意思是這種情況在該群體中頗常發生。"},{"en":"It is not uncommon for students to feel nervous before speaking exams.","zh":"學生在口試前感到緊張並不罕見。"},{"en":"If writers reread one manuscript repeatedly, becoming tired of it is understandable.","zh":"如果作家反覆閱讀同一手稿，對它感到厭倦是可以理解的。"},{"en":"The phrase means “quite common”, but sounds softer.","zh":"這個短語意思是「頗常見」，但語氣較柔和。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":11},{"front":"thoroughly sick of","meaning":"對……極度厭倦","examples":[{"en":"The writer may be thoroughly sick of the text.","zh":"作者可能對文本極度厭倦。"},{"en":"Thoroughly sick of something means extremely tired of it and no longer wanting to deal with it.","zh":"「thoroughly sick of」某物，意思是對它非常厭倦，並不再想處理它。"},{"en":"A student may be thoroughly sick of a project after revising it for weeks.","zh":"學生連續數星期修改專題後，可能對它極度厭倦。"},{"en":"If a writer has edited every page many times, the text may feel exhausting.","zh":"如果作家多次編輯每一頁，文本可能令人感到疲憊。"},{"en":"The phrase expresses strong boredom or frustration.","zh":"這個短語表達強烈厭煩或挫敗。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":11},{"front":"abandon writing","meaning":"放棄寫作","examples":[{"en":"The writer asks whether one should abandon writing.","zh":"作者問人是否應該放棄寫作。"},{"en":"To abandon writing means to stop writing completely or give up the writing life.","zh":"「abandon writing」意思是完全停止寫作或放棄寫作生活。"},{"en":"A student should not abandon writing just because one essay received a low mark.","zh":"學生不應只因一篇作文低分就放棄寫作。"},{"en":"If rejection feels painful, some writers may consider giving up.","zh":"如果被拒令人痛苦，有些作家可能考慮放棄。"},{"en":"The phrase describes quitting the activity altogether.","zh":"這個短語描述完全退出該活動。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":11},{"front":"nonsense","meaning":"胡說；荒謬","examples":[{"en":"The writer rejects the idea as nonsense.","zh":"作者把這個想法斥為胡說。"},{"en":"Nonsense means an idea, statement, or suggestion that is foolish or not true.","zh":"「nonsense」是愚蠢或不真確的想法、說法或建議。"},{"en":"A teacher may say it is nonsense to believe grammar can improve without practice.","zh":"老師可能說相信不練習也能改善文法是荒謬的。"},{"en":"If an argument ignores all evidence, people may dismiss it as nonsense.","zh":"如果論點忽略所有證據，人們可能把它斥為胡說。"},{"en":"The word expresses strong rejection of an idea.","zh":"這個詞表達對想法的強烈否定。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":11},{"front":"once smitten","meaning":"一旦着迷","examples":[{"en":"Once smitten, it is not easy to escape writing.","zh":"一旦着迷，就不容易逃離寫作。"},{"en":"Once smitten means once someone has fallen strongly in love with or become deeply attracted to something.","zh":"「once smitten」意思是一旦某人深深愛上或被某事吸引。"},{"en":"Once smitten with music, a child may practise piano every day without being forced.","zh":"一旦對音樂着迷，孩子可能不用被迫也每天練琴。"},{"en":"If writers are smitten by storytelling, frustration may not stop them for long.","zh":"如果作家被敘事迷住，挫敗未必能長時間阻止他們。"},{"en":"The phrase describes powerful attraction that is hard to shake off.","zh":"這個短語描述難以擺脫的強烈吸引。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":12},{"front":"escape the compulsion to","meaning":"擺脫……的衝動","examples":[{"en":"It is not easy to escape the compulsion to create and write.","zh":"要擺脫創作和寫作的衝動並不容易。"},{"en":"To escape the compulsion to do something means to free oneself from a strong inner urge to do it.","zh":"「escape the compulsion to」做某事，意思是擺脫做它的強烈內在衝動。"},{"en":"A singer may find it hard to escape the compulsion to perform even after retiring.","zh":"歌手退休後，可能仍難以擺脫表演的衝動。"},{"en":"If writing feels like a compulsion, difficulties may slow the writer but not stop them.","zh":"如果寫作像一種衝動，困難可能拖慢作家，但不會阻止他。"},{"en":"The phrase describes an urge that feels almost unavoidable.","zh":"這個短語描述幾乎無法避免的衝動。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":12},{"front":"create and write","meaning":"創作和寫作","examples":[{"en":"Writers feel a compulsion to create and write.","zh":"作家感到創作和寫作的衝動。"},{"en":"To create and write means to produce ideas, stories, arguments, or texts through imagination and language.","zh":"「create and write」意思是透過想像和語言產生想法、故事、論點或文本。"},{"en":"A student may create and write a short play for a school performance.","zh":"學生可能為學校表演創作並寫出短劇。"},{"en":"If someone feels driven to create and write, they may keep notebooks everywhere.","zh":"如果有人強烈想創作和寫作，他可能到處放筆記本。"},{"en":"The phrase combines imagination with the act of putting words on a page.","zh":"這個短語結合想像力和把文字寫在頁面上的行動。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":12},{"front":"despite","meaning":"儘管","examples":[{"en":"Writers continue despite the roller-coaster ride of emotions.","zh":"儘管情緒像過山車般起伏，作家仍繼續寫作。"},{"en":"Despite means although something difficult or negative exists.","zh":"「despite」意思是儘管有困難或負面情況存在。"},{"en":"A student passed the exam despite feeling nervous during the test.","zh":"儘管考試期間感到緊張，學生仍然合格。"},{"en":"If writers continue despite rejection, writing must still feel meaningful to them.","zh":"如果作家儘管被拒仍繼續寫作，寫作對他們一定仍有意義。"},{"en":"The word introduces contrast between difficulty and action.","zh":"這個詞引出困難與行動之間的對比。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":12},{"front":"roller-coaster ride","meaning":"過山車般的經歷","examples":[{"en":"Writing involves a roller-coaster ride of contradictory emotions.","zh":"寫作涉及矛盾情緒的過山車般經歷。"},{"en":"A roller-coaster ride is an experience with rapid emotional ups and downs.","zh":"「roller-coaster ride」是情緒快速高低起伏的經歷。"},{"en":"Preparing for a competition can feel like a roller-coaster ride of hope, fear, and excitement.","zh":"準備比賽可能像一場充滿希望、恐懼和興奮的過山車經歷。"},{"en":"If writing brings elation one day and despair the next, it feels emotionally unstable.","zh":"如果寫作今天帶來興奮、明天帶來絕望，它就感覺情緒很不穩。"},{"en":"The phrase uses an amusement ride as a metaphor for dramatic changes.","zh":"這個短語用遊樂設施比喻劇烈變化。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":12},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the box.","zh":"學生使用方框中的詞語完成以下摘要。"},{"en":"Complete the summary below means fill in the missing words in the summary that follows.","zh":"「complete the summary below」意思是填寫下方摘要中的空缺字詞。"},{"en":"In reading practice, students complete a summary by choosing words that fit grammar and meaning.","zh":"在閱讀練習中，學生透過選擇符合文法和意思的詞語完成摘要。"},{"en":"If the summary is incomplete, students must connect each gap with evidence from the passage.","zh":"如果摘要不完整，學生必須把每個空格與文章證據連繫起來。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":12},{"front":"words from the box","meaning":"方框中的詞語","examples":[{"en":"The answers should be chosen from the words in the box.","zh":"答案應從方框中的詞語中選擇。"},{"en":"Words from the box are the answer choices listed in a box in an exercise.","zh":"「words from the box」是練習中列在方框內的答案選項。"},{"en":"A grammar worksheet may ask students to fill gaps using words from the box.","zh":"文法工作紙可能要求學生使用方框中的詞語填空。"},{"en":"If the correct word is not copied exactly, the answer may be marked wrong.","zh":"如果正確詞語沒有準確抄寫，答案可能被判錯。"},{"en":"The phrase tells students where the possible answers come from.","zh":"這個短語告訴學生可能答案來自哪裡。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":12},{"front":"associate writing with","meaning":"把寫作與……聯繫起來","examples":[{"en":"People often associate writing with glamour.","zh":"人們常把寫作與光鮮聯繫起來。"},{"en":"To associate writing with something means to connect writing in one’s mind with that idea or image.","zh":"「associate writing with」某事，意思是在心中把寫作和該想法或形象連起來。"},{"en":"Some students associate exams with stress because they have had bad experiences.","zh":"有些學生把考試與壓力聯繫起來，因為他們有不愉快經驗。"},{"en":"If people associate writing only with fame, they may ignore research, editing, and rejection.","zh":"如果人們只把寫作與名氣聯繫起來，他們可能忽略研究、編輯和被拒。"},{"en":"The phrase describes a mental connection.","zh":"這個短語描述心理上的連繫。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":12},{"front":"conflicting emotions","meaning":"矛盾情緒","examples":[{"en":"Being a writer involves managing conflicting emotions.","zh":"成為作家涉及處理矛盾情緒。"},{"en":"Conflicting emotions are feelings that pull a person in different directions.","zh":"「conflicting emotions」是把人拉向不同方向的情緒。"},{"en":"A student may feel conflicting emotions before moving abroad: excitement and fear.","zh":"學生移居海外前可能有矛盾情緒：興奮和害怕。"},{"en":"If a writer receives criticism, pride and disappointment may appear together.","zh":"如果作家收到批評，自豪和失望可能同時出現。"},{"en":"The phrase is very close in meaning to “contradictory feelings”.","zh":"這個短語與 “contradictory feelings” 意思很接近。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":12},{"front":"contrary to","meaning":"與……相反","examples":[{"en":"Contrary to what some people believe, technology does not make editing faster.","zh":"與一些人所相信的相反，科技並不會令編輯更快。"},{"en":"Contrary to means opposite to or different from what has been said or believed.","zh":"「contrary to」意思是與已說或已相信的內容相反或不同。"},{"en":"Contrary to popular belief, a high mark usually needs planning, not just talent.","zh":"與普遍看法相反，高分通常需要規劃，而不只是天分。"},{"en":"If the truth is contrary to expectations, the writer uses the phrase to signal correction.","zh":"如果真相與預期相反，作者會用這個短語標示更正。"},{"en":"The phrase introduces contrast with a belief.","zh":"這個短語引出與信念的對比。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":12},{"front":"prepare a summary","meaning":"準備摘要","examples":[{"en":"When a draft is ready, it is useful to prepare a summary.","zh":"當草稿準備好時，準備摘要會很有用。"},{"en":"To prepare a summary means to write a short version of the main points.","zh":"「prepare a summary」意思是寫出主要內容的簡短版本。"},{"en":"A student may prepare a summary of a chapter before revising for a test.","zh":"學生考試溫習前，可能為一章準備摘要。"},{"en":"If an agent receives a clear summary, they can judge the book more quickly.","zh":"如果經紀人收到清楚摘要，他們可以更快判斷該書。"},{"en":"The phrase describes making a brief guide to a longer text.","zh":"這個短語描述為較長文本製作簡短指引。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":12},{"front":"for friends and agents to review","meaning":"供朋友和經紀人審閱","examples":[{"en":"A summary helps friends and agents review the draft.","zh":"摘要幫助朋友和經紀人審閱草稿。"},{"en":"For friends and agents to review means so that these people can read, judge, and give feedback.","zh":"「for friends and agents to review」意思是讓這些人閱讀、評判並給予回饋。"},{"en":"A student may prepare a short plan for classmates and teachers to review before writing.","zh":"學生可能在寫作前準備簡短計劃，供同學和老師審閱。"},{"en":"If reviewers understand the main idea first, their feedback may be more useful.","zh":"如果審閱者先理解主要想法，他們的回饋可能更有用。"},{"en":"The phrase explains who will examine the material and why.","zh":"這個短語解釋誰會檢查材料以及為何檢查。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":13},{"front":"be given to readers","meaning":"被交給讀者審閱","examples":[{"en":"If a publisher accepts an author, the draft is given to readers.","zh":"如果出版社接受作者，草稿會被交給讀者審閱。"},{"en":"To be given to readers means to be passed to people who will read and evaluate it.","zh":"「be given to readers」意思是被交給會閱讀和評估的人。"},{"en":"A school magazine article may be given to teachers before publication.","zh":"學校雜誌文章在出版前可能被交給老師審閱。"},{"en":"If a draft is given to readers, their opinions may influence whether it is published.","zh":"如果草稿被交給讀者審閱，他們的意見可能影響它是否出版。"},{"en":"The phrase describes sending a manuscript for review.","zh":"這個短語描述把手稿送去審查。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":13},{"front":"for vetting","meaning":"以供審查","examples":[{"en":"The draft is given to readers for vetting.","zh":"草稿被交給讀者以供審查。"},{"en":"For vetting means for careful checking before approval.","zh":"「for vetting」意思是為了在批准前仔細檢查。"},{"en":"A school trip plan may be sent to senior teachers for vetting.","zh":"學校旅行計劃可能被送交資深老師以供審查。"},{"en":"If a manuscript is sent for vetting, readers look for problems before publication.","zh":"如果手稿被送去審查，讀者會在出版前尋找問題。"},{"en":"The phrase describes the purpose of formal screening.","zh":"這個短語描述正式篩選的目的。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":13},{"front":"difficult to accept","meaning":"難以接受","examples":[{"en":"The writer may find the alterations difficult to accept.","zh":"作者可能覺得那些修改難以接受。"},{"en":"Difficult to accept means emotionally or practically hard to agree with.","zh":"「difficult to accept」意思是在情感上或實際上難以同意。"},{"en":"A student may find a low mark difficult to accept after working very hard.","zh":"學生努力很久後得到低分，可能覺得難以接受。"},{"en":"If changes remove a writer’s favourite scene, acceptance may be painful.","zh":"如果改動刪去作者最喜歡的場景，接受可能很痛苦。"},{"en":"The phrase describes resistance to an unwelcome result or suggestion.","zh":"這個短語描述對不受歡迎結果或建議的抗拒。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":13},{"front":"remain compelling","meaning":"仍然令人欲罷不能","examples":[{"en":"Writing remains compelling despite its difficulties.","zh":"儘管寫作有困難，它仍然令人欲罷不能。"},{"en":"To remain compelling means to continue being strongly attractive or hard to resist.","zh":"「remain compelling」意思是繼續強烈吸引人或令人難以抗拒。"},{"en":"A difficult sport may remain compelling because each small improvement feels rewarding.","zh":"困難運動可能仍然令人欲罷不能，因為每一點進步都令人有成就感。"},{"en":"If writing gives meaning and creative pleasure, writers may continue despite stress.","zh":"如果寫作給人意義和創作快樂，作家可能儘管有壓力仍繼續。"},{"en":"The phrase describes attraction that survives problems.","zh":"這個短語描述在問題之後仍存在的吸引力。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":13},{"front":"involve ups and downs","meaning":"涉及起伏","examples":[{"en":"Writing involves ups and downs.","zh":"寫作涉及起伏。"},{"en":"To involve ups and downs means to include both good and bad periods.","zh":"「involve ups and downs」意思是包括好時期和壞時期。"},{"en":"Learning a language involves ups and downs: some weeks feel easy, others frustrating.","zh":"學語言涉及起伏：有些星期感覺容易，有些則令人挫敗。"},{"en":"If a career has ups and downs, people need patience during difficult times.","zh":"如果職業有起有跌，人們在困難時期需要耐心。"},{"en":"The phrase describes changing fortunes or emotions.","zh":"這個短語描述運氣或情緒的變化。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":13},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter from the options.","zh":"學生從選項中選出正確字母。"},{"en":"Choose the correct letter means select the option letter that matches the answer.","zh":"「choose the correct letter」意思是選擇與答案相符的選項字母。"},{"en":"In a reading test, students may choose A, B, C, or D.","zh":"在閱讀測驗中，學生可能選擇 A、B、C 或 D。"},{"en":"If the correct idea is matched to the wrong letter, the answer may still be marked wrong.","zh":"如果正確想法配錯字母，答案仍可能被判錯。"},{"en":"The phrase is a standard exam instruction.","zh":"這個短語是標準考試指示。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":13},{"front":"planning stages","meaning":"計劃階段","examples":[{"en":"In the planning stages of a book, instinct may replace research.","zh":"在一本書的計劃階段，直覺可能取代研究。"},{"en":"Planning stages are the early steps when a project is being organised before full work begins.","zh":"「planning stages」是完整工作開始前，項目被組織安排的早期步驟。"},{"en":"In the planning stages of a school event, teachers choose the date, venue, and budget.","zh":"在學校活動的計劃階段，老師會選擇日期、場地和預算。"},{"en":"If the planning stages are weak, later writing may become confused.","zh":"如果計劃階段薄弱，後來寫作可能變得混亂。"},{"en":"The phrase describes the beginning phase of preparation.","zh":"這個短語描述準備的起始階段。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":13},{"front":"replace market research","meaning":"取代市場調查","examples":[{"en":"Instinct can replace market research in some cases.","zh":"在某些情況下，直覺可以取代市場調查。"},{"en":"To replace market research means to use personal judgement instead of formal study of demand.","zh":"「replace market research」意思是使用個人判斷，而不是正式研究市場需求。"},{"en":"A small shop owner may rely on experience instead of market research when choosing new products.","zh":"小店老闆選擇新產品時，可能依靠經驗而不是市場調查。"},{"en":"If instinct replaces research, the decision may be quicker but less evidence-based.","zh":"如果直覺取代研究，決定可能較快，但較少建基於證據。"},{"en":"The phrase shows one decision-making method taking the place of another.","zh":"這個短語顯示一種決策方法取代另一種。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":13},{"front":"essential","meaning":"必不可少的","examples":[{"en":"One option says market research is essential.","zh":"一個選項說市場調查是必不可少的。"},{"en":"Essential means absolutely necessary or very important.","zh":"「essential」意思是絕對必要或非常重要。"},{"en":"Sleep is essential for students who want to remember what they study.","zh":"睡眠對想記住所學內容的學生是必不可少的。"},{"en":"If market research is essential, a writer should not skip it before planning a book.","zh":"如果市場調查必不可少，作家在計劃書本前就不應跳過它。"},{"en":"The word describes something that cannot be safely ignored.","zh":"這個詞描述不能安全忽略的東西。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":13},{"front":"frequently replaces","meaning":"經常取代","examples":[{"en":"One option says instinct frequently replaces market research.","zh":"一個選項說直覺經常取代市場調查。"},{"en":"Frequently replaces means often takes the place of something else.","zh":"「frequently replaces」意思是經常代替另一事物。"},{"en":"Online messaging frequently replaces phone calls among students.","zh":"在學生之間，網上訊息經常取代電話通話。"},{"en":"If instinct frequently replaces research, decisions may depend more on experience than data.","zh":"如果直覺經常取代研究，決定可能更依賴經驗而不是數據。"},{"en":"The phrase describes repeated substitution.","zh":"這個短語描述反覆替代。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":13},{"front":"problem with using","meaning":"使用……的問題","examples":[{"en":"The question asks about the problem with using advanced technology.","zh":"問題問使用先進科技的問題。"},{"en":"The problem with using something is the difficulty or disadvantage caused by using it.","zh":"「problem with using」某物，是使用它造成的困難或缺點。"},{"en":"The problem with using a phone for study is that notifications can distract students.","zh":"使用電話溫習的問題是通知可能分散學生注意力。"},{"en":"If advanced technology makes editing too easy, writers may never stop revising.","zh":"如果先進科技令編輯太容易，作家可能永遠不停止修改。"},{"en":"The phrase introduces a drawback of a method or tool.","zh":"這個短語引出方法或工具的缺點。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":14},{"front":"edited text","meaning":"經編輯的文本","examples":[{"en":"The edited text may become different from the original.","zh":"經編輯的文本可能變得與原文不同。"},{"en":"Edited text is writing that has been changed, corrected, or improved after drafting.","zh":"「edited text」是起草後經修改、更正或改善的文字。"},{"en":"A teacher may compare edited text with the first draft to show what improved.","zh":"老師可能把經編輯的文本與初稿比較，以顯示改進了甚麼。"},{"en":"If edited text changes too much, it may lose the writer’s original tone.","zh":"如果經編輯的文本改動太多，它可能失去作者原本語氣。"},{"en":"The phrase describes the version after revision.","zh":"這個短語描述修改後的版本。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":14},{"front":"cannot resist changing","meaning":"忍不住反覆修改","examples":[{"en":"Many writers cannot resist changing the text repeatedly.","zh":"許多作家忍不住反覆修改文本。"},{"en":"Cannot resist changing means cannot stop oneself from making changes.","zh":"「cannot resist changing」意思是無法阻止自己作出改動。"},{"en":"A student may cannot resist changing slides again and again before a presentation.","zh":"學生在匯報前可能忍不住一次又一次修改簡報。"},{"en":"If a writer cannot resist changing every sentence, finishing the book becomes harder.","zh":"如果作家忍不住修改每一句，完成書本會更困難。"},{"en":"The phrase describes a strong urge to revise.","zh":"這個短語描述強烈的修改衝動。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":14},{"front":"complete the sentences below","meaning":"完成以下句子","examples":[{"en":"Students complete the sentences below with words from the passage.","zh":"學生用文章中的詞語完成以下句子。"},{"en":"Complete the sentences below means fill in the missing parts of the sentences that follow.","zh":"「complete the sentences below」意思是填寫下方句子中的空缺部分。"},{"en":"In a reading exercise, students complete sentences by finding exact words in the text.","zh":"在閱讀練習中，學生透過在文本中找準確字詞完成句子。"},{"en":"If the sentence must be grammatically correct, students should check the word form carefully.","zh":"如果句子必須文法正確，學生應仔細檢查詞形。"},{"en":"The phrase is an exam instruction for gap-filling questions.","zh":"這個短語是填空題的考試指示。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":14},{"front":"words taken from","meaning":"從……取出的詞語","examples":[{"en":"The answers should be words taken from the reading passage.","zh":"答案應是從閱讀文章取出的詞語。"},{"en":"Words taken from a passage are exact words copied from the text.","zh":"「words taken from」篇章，是直接從文本抄出的準確字詞。"},{"en":"A student may lose marks if they use their own wording instead of words taken from the passage.","zh":"如果學生不用文章原詞而用自己措辭，可能會失分。"},{"en":"If the instruction asks for passage words, spelling must match the original text.","zh":"如果指示要求使用文章字詞，拼寫必須與原文相符。"},{"en":"The phrase reminds students not to invent answers.","zh":"這個短語提醒學生不要自創答案。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":14},{"front":"no more than three words","meaning":"不超過三個詞","examples":[{"en":"Each answer should contain no more than three words.","zh":"每個答案應包含不超過三個詞。"},{"en":"No more than three words means one, two, or three words only.","zh":"「no more than three words」意思是只能一個、兩個或三個詞。"},{"en":"If the answer is “market research”, it fits a three-word limit.","zh":"如果答案是 “market research”，它符合三詞限制。"},{"en":"If students write four words, the answer may be wrong even if the meaning is close.","zh":"如果學生寫四個詞，即使意思接近，答案也可能錯。"},{"en":"The phrase sets a strict word limit.","zh":"這個短語設定嚴格字數限制。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":14},{"front":"get the appraisal of","meaning":"得到……的評價","examples":[{"en":"Once a text is finished, the writer needs to get the appraisal of other people.","zh":"文本完成後，作者需要得到其他人的評價。"},{"en":"To get the appraisal of someone means to receive their judgement, evaluation, or feedback.","zh":"「get the appraisal of」某人，意思是取得他們的判斷、評估或回饋。"},{"en":"A student may get the appraisal of a teacher before submitting a scholarship essay.","zh":"學生提交獎學金文章前，可能得到老師的評價。"},{"en":"If writers get outside appraisal, they can discover weaknesses they missed.","zh":"如果作家得到外部評價，他們可以發現自己忽略的弱點。"},{"en":"The phrase describes asking others to evaluate a piece of work.","zh":"這個短語描述請他人評估作品。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":14},{"front":"offer invaluable advice","meaning":"提供寶貴意見","examples":[{"en":"Some agents may offer invaluable advice.","zh":"有些經紀人可能提供寶貴意見。"},{"en":"To offer invaluable advice means to give advice that is extremely useful.","zh":"「offer invaluable advice」意思是給予極其有用的建議。"},{"en":"A coach may offer invaluable advice before a student’s first public speech.","zh":"教練可能在學生第一次公開演說前提供寶貴意見。"},{"en":"If an agent explains why a draft fails, the writer may revise more effectively.","zh":"如果經紀人解釋草稿為何失敗，作者可能更有效修改。"},{"en":"The phrase describes advice whose value is very high.","zh":"這個短語描述價值很高的建議。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":14},{"front":"apart from requiring","meaning":"除了要求……之外","examples":[{"en":"A publisher may ask for changes apart from requiring an in-house style.","zh":"出版社除了要求內部風格外，也可能要求其他改動。"},{"en":"Apart from requiring something means in addition to demanding that thing.","zh":"「apart from requiring」某事，意思是除了要求該事之外。"},{"en":"Apart from requiring uniforms, a school may also require students to arrive on time.","zh":"學校除了要求制服外，也可能要求學生準時到校。"},{"en":"If a publisher asks for style changes and deeper rewriting, the work becomes more demanding.","zh":"如果出版社要求風格修改和更深層重寫，工作會變得更吃力。"},{"en":"The phrase adds another requirement beyond the first one.","zh":"這個短語在第一項要求之外加入另一項要求。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":14},{"front":"include radical re-drafting","meaning":"包括大幅重寫","examples":[{"en":"The publisher’s changes may include radical re-drafting.","zh":"出版社的修改可能包括大幅重寫。"},{"en":"To include radical re-drafting means to involve major rewriting as part of the changes.","zh":"「include radical re-drafting」意思是改動中包含重大重寫。"},{"en":"A teacher’s feedback may include radical re-drafting if an essay answers the wrong question.","zh":"如果作文答錯題目，老師的回饋可能包括大幅重寫。"},{"en":"If revisions include radical re-drafting, the writer must rethink structure, content, and wording.","zh":"如果修改包括大幅重寫，作者必須重新思考結構、內容和措辭。"},{"en":"The phrase describes serious revision beyond small corrections.","zh":"這個短語描述超越小更正的嚴重修改。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":14},{"front":"while the book is being produced","meaning":"在書本製作期間","examples":[{"en":"The waiting period is difficult while the book is being produced.","zh":"在書本製作期間，等待階段是困難的。"},{"en":"While the book is being produced means during the time when the book is being edited, designed, printed, or prepared for release.","zh":"「while the book is being produced」意思是在書本被編輯、設計、印刷或準備推出的期間。"},{"en":"An author may feel impatient while the book is being produced because they cannot control every step.","zh":"在書本製作期間，作者可能感到不耐煩，因為他不能控制每一步。"},{"en":"If production takes months, the writer may become tired of seeing the same text again.","zh":"如果製作需時數月，作者可能厭倦再次看到同一文本。"},{"en":"The phrase describes the stage after acceptance but before publication.","zh":"這個短語描述獲接納後、出版前的階段。"}],"source":"Passage 2 Flash Cards  24 - Caveat Scriptor.pdf","sourcePage":14}],"ielts/reading/passage-2/Practice 25":[{"front":"make itself unmistakably felt","meaning":"明確顯現出來","examples":[{"en":"Global warming at last made itself unmistakably felt in the summer of 2003.","zh":"全球暖化終於在2003年夏天明確顯現出來。"},{"en":"If something makes itself unmistakably felt, its effect becomes so clear that people cannot ignore it.","zh":"如果某事明確顯現出來，它的影響就變得非常清楚，令人無法忽視。"},{"en":"A teacher’s absence made itself unmistakably felt when the class became noisy and confused.","zh":"當課室變得嘈雜混亂時，老師缺席的影響明確顯現出來。"},{"en":"When prices rise every week, inflation makes itself unmistakably felt in family shopping bills.","zh":"當物價每星期上升，通脹就在家庭購物帳單中明確顯現出來。"},{"en":"The phrase describes an impact that changes from hidden or gradual into obvious and powerful.","zh":"這個短語描述某種影響由隱藏或漸進變成明顯而有力。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":1},{"front":"global warming","meaning":"全球暖化","examples":[{"en":"Scientists now realise that global warming affected the summer of 2003.","zh":"科學家現在意識到全球暖化影響了2003年夏天。"},{"en":"Global warming is the long-term rise in the Earth’s average temperature.","zh":"全球暖化是地球平均溫度長期上升。"},{"en":"Students may learn about global warming by studying heatwaves, melting ice and rising sea levels.","zh":"學生可以透過研究熱浪、冰層融化和海平面上升來了解全球暖化。"},{"en":"If global warming continues, extreme weather may become more frequent or more severe.","zh":"如果全球暖化持續，極端天氣可能變得更頻繁或更嚴重。"},{"en":"The phrase refers to a broad climate trend, not just one hot day.","zh":"這個短語指廣泛的氣候趨勢，而不只是某一天很熱。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":1},{"front":"remarkable","meaning":"非同尋常的","examples":[{"en":"We knew that summer 2003 was remarkable.","zh":"我們知道2003年夏天是非同尋常的。"},{"en":"Remarkable means unusual, impressive or clearly worth noticing.","zh":"“Remarkable” 指不尋常、令人印象深刻或明顯值得注意。"},{"en":"A student’s improvement is remarkable if they move from failing to top marks in one term.","zh":"如果學生一個學期內由不合格進步到最高分，其進步就是非同尋常的。"},{"en":"If a summer breaks many temperature records, scientists may call it remarkable.","zh":"如果一個夏天打破許多氣溫紀錄，科學家可能稱它為非同尋常。"},{"en":"The word suggests something is far from ordinary.","zh":"這個詞暗示某事遠非普通。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":1},{"front":"record high temperature","meaning":"歷來最高氣溫","examples":[{"en":"Britain experienced its record high temperature.","zh":"英國經歷了其歷來最高氣溫。"},{"en":"A record high temperature is the highest temperature ever measured in a particular place or period.","zh":"歷來最高氣溫是在某地或某時期量度到的最高溫度。"},{"en":"A city may close outdoor playgrounds when it reaches a record high temperature.","zh":"當城市達到歷來最高氣溫時，可能關閉戶外遊樂場。"},{"en":"If a country records a new high temperature, heat safety becomes a public concern.","zh":"如果一個國家錄得新的最高氣溫，酷熱安全就成為公共關注。"},{"en":"The phrase marks an extreme point in weather records.","zh":"這個短語標示天氣記錄中的極端點。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":1},{"front":"continental Europe","meaning":"歐洲大陸","examples":[{"en":"Continental Europe saw forest fires raging out of control.","zh":"歐洲大陸出現森林大火失控地肆虐。"},{"en":"Continental Europe means the main landmass of Europe, excluding islands such as Britain and Ireland.","zh":"歐洲大陸指歐洲主要陸地部分，不包括英國和愛爾蘭等島嶼。"},{"en":"Travellers may take trains across continental Europe from France to Germany or Italy.","zh":"旅客可能乘火車橫跨歐洲大陸，從法國到德國或意大利。"},{"en":"If heat spreads across continental Europe, many countries can be affected at the same time.","zh":"如果酷熱蔓延至歐洲大陸，許多國家可同時受影響。"},{"en":"The phrase gives a broad geographical area.","zh":"這個短語給出廣闊地理區域。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":1},{"front":"forest fires","meaning":"山火；森林大火","examples":[{"en":"Continental Europe saw forest fires raging out of control.","zh":"歐洲大陸出現森林大火失控地肆虐。"},{"en":"Forest fires are large fires that burn trees and land in wooded areas.","zh":"森林大火是在樹林地區燃燒樹木和土地的大火。"},{"en":"During a dry summer, campers must be careful because a small spark can start forest fires.","zh":"在乾燥夏季，露營者必須小心，因為一點火花也可能引發山火。"},{"en":"If forest fires spread quickly, people may need to leave homes and roads may close.","zh":"如果森林大火快速蔓延，人們可能需要離家，道路也可能關閉。"},{"en":"The phrase describes serious fires in natural areas.","zh":"這個短語描述自然地區中的嚴重火災。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":1},{"front":"rage out of control","meaning":"失控地肆虐","examples":[{"en":"Forest fires were raging out of control across Europe.","zh":"森林大火在歐洲各地失控地肆虐。"},{"en":"To rage out of control means to spread violently and become impossible to manage.","zh":"“Rage out of control” 指猛烈蔓延並變得無法控制。"},{"en":"A kitchen fire can rage out of control if no one notices it quickly.","zh":"如果沒有人迅速發現，廚房火災可以失控地肆虐。"},{"en":"When strong winds feed a fire, it may rage out of control within minutes.","zh":"當強風助長火勢，它可能在數分鐘內失控地肆虐。"},{"en":"The phrase describes a dangerous situation that has gone beyond control.","zh":"這個短語描述已超出控制的危險情況。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":1},{"front":"dry to a trickle","meaning":"乾涸至只剩細流","examples":[{"en":"Great rivers dried to a trickle during the heatwave.","zh":"大河在熱浪期間乾涸至只剩細流。"},{"en":"To dry to a trickle means to lose so much water that only a small flow remains.","zh":"“Dry to a trickle” 指失去大量水分，只剩下一小股水流。"},{"en":"A village stream may dry to a trickle after months without rain.","zh":"如果數月沒有下雨，村莊溪流可能乾涸至只剩細流。"},{"en":"If rivers dry to a trickle, boats, farms and drinking-water supplies can be affected.","zh":"如果河流乾涸至只剩細流，船運、農業和飲用水供應都可能受影響。"},{"en":"The phrase shows severe water loss.","zh":"這個短語顯示嚴重失水。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":1},{"front":"heat-related deaths","meaning":"與酷熱有關的死亡","examples":[{"en":"Europe suffered thousands of heat-related deaths.","zh":"歐洲出現數以千計與酷熱有關的死亡。"},{"en":"Heat-related deaths are deaths caused or worsened by extremely hot weather.","zh":"與酷熱有關的死亡，是由極端高溫造成或加劇的死亡。"},{"en":"Elderly people living alone may face a higher risk of heat-related deaths during a heatwave.","zh":"在熱浪期間，獨居長者可能面對較高的與酷熱有關的死亡風險。"},{"en":"If nights stay hot, the body may not recover, and heat-related deaths can increase.","zh":"如果夜晚仍然炎熱，身體可能無法恢復，與酷熱有關的死亡可增加。"},{"en":"The phrase connects mortality with high temperature.","zh":"這個短語把死亡率與高溫連繫起來。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":1},{"front":"just how remarkable","meaning":"究竟有多非凡","examples":[{"en":"Just how remarkable the summer was is only now becoming clear.","zh":"那個夏天究竟有多非凡，現在才開始變得清楚。"},{"en":"Just how remarkable means exactly how unusual, extreme or important something was.","zh":"“Just how remarkable” 指某事究竟有多不尋常、極端或重要。"},{"en":"After exam results came out, the school realised just how remarkable the students’ progress had been.","zh":"考試結果公布後，學校才意識到學生進步究竟有多非凡。"},{"en":"Sometimes data is needed before people understand just how remarkable an event really was.","zh":"有時需要數據，人們才明白某事件究竟有多非凡。"},{"en":"The phrase emphasises the true degree of something unusual.","zh":"這個短語強調某件不尋常事情的真實程度。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":1},{"front":"become clear","meaning":"變得清楚","examples":[{"en":"The true scale of the heatwave is only now becoming clear.","zh":"熱浪的真實規模現在才變得清楚。"},{"en":"To become clear means to become easy to understand or see.","zh":"“Become clear” 指變得容易理解或看見。"},{"en":"After the teacher gave an example, the grammar rule became clear.","zh":"老師給出例子後，文法規則變得清楚。"},{"en":"When more evidence appears, the cause of a problem may become clear.","zh":"當更多證據出現，問題成因可能變得清楚。"},{"en":"The phrase describes a movement from uncertainty to understanding.","zh":"這個短語描述由不確定走向理解。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":1},{"front":"the warmest ever recorded","meaning":"有記錄以來最暖","examples":[{"en":"The three months were the warmest ever recorded in western and central Europe.","zh":"這三個月是西歐和中歐有記錄以來最暖的三個月。"},{"en":"The warmest ever recorded means the hottest measured since records began.","zh":"有記錄以來最暖，指自有記錄以來量度到的最高溫。"},{"en":"A city may call a night the warmest ever recorded if no earlier record was higher.","zh":"如果沒有任何較早紀錄更高，城市可稱某晚為有記錄以來最暖的夜晚。"},{"en":"If a season is the warmest ever recorded, it stands out in historical data.","zh":"如果一個季節是有記錄以來最暖，它就在歷史數據中特別突出。"},{"en":"The phrase depends on actual temperature records.","zh":"這個短語依賴實際氣溫記錄。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":2},{"front":"western and central Europe","meaning":"西歐和中歐","examples":[{"en":"The summer was exceptionally hot in western and central Europe.","zh":"那個夏天在西歐和中歐異常炎熱。"},{"en":"Western and central Europe refers to countries in the west and middle of the European continent.","zh":"西歐和中歐指歐洲大陸西部和中部的國家。"},{"en":"France, Germany and Switzerland are often discussed as parts of western or central Europe.","zh":"法國、德國和瑞士常被視為西歐或中歐的一部分。"},{"en":"If heat affects western and central Europe together, the event covers a wide region.","zh":"如果高溫同時影響西歐和中歐，該事件就覆蓋廣闊地區。"},{"en":"The phrase gives a regional focus within Europe.","zh":"這個短語給出歐洲內部的區域焦點。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":2},{"front":"record national highs","meaning":"全國最高紀錄","examples":[{"en":"Several countries recorded national highs in temperature.","zh":"幾個國家錄得全國最高氣溫紀錄。"},{"en":"Record national highs are the highest temperatures ever measured within individual countries.","zh":"全國最高紀錄是在個別國家內量度到的歷來最高氣溫。"},{"en":"A country may warn citizens when a record national high is expected.","zh":"當預料會出現全國最高紀錄時，國家可能提醒市民。"},{"en":"If several countries record national highs, the heatwave is not just a local event.","zh":"如果幾個國家錄得全國最高紀錄，熱浪就不只是本地事件。"},{"en":"The phrase points to extreme national temperature records.","zh":"這個短語指極端的全國氣溫紀錄。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":2},{"front":"by a very long way","meaning":"遠遠超出其他","examples":[{"en":"The summer was the warmest by a very long way.","zh":"那個夏天遠遠超出其他年份，成為最暖夏季。"},{"en":"By a very long way means by a large margin, far more than the others.","zh":"“By a very long way” 指以很大幅度，遠遠超過其他。"},{"en":"She won the race by a very long way because the second runner was far behind.","zh":"她遠遠拋離其他人勝出比賽，因為第二名落後很多。"},{"en":"If one year is hotter by a very long way, it is not just slightly above the record.","zh":"如果某一年遠遠更熱，它就不只是略高於紀錄。"},{"en":"The phrase strongly emphasises distance or difference.","zh":"這個短語強烈強調距離或差異。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":2},{"front":"rectangular block of the earth","meaning":"地球上一大片長方形區域","examples":[{"en":"The heat covered a great rectangular block of the earth.","zh":"高溫覆蓋了地球上一大片長方形區域。"},{"en":"A rectangular block of the earth means a large area on the map shaped roughly like a rectangle.","zh":"地球上一大片長方形區域，指地圖上一個大致呈長方形的大範圍地區。"},{"en":"Weather maps may describe a rectangular block of land when a pattern covers a clearly bounded area.","zh":"當天氣模式覆蓋界線清楚的地區時，天氣圖可能描述一大片長方形土地。"},{"en":"If heat covers a large rectangular block, the affected zone can be mapped and studied.","zh":"如果高溫覆蓋大片長方形區域，受影響地帶就可以被繪製和研究。"},{"en":"The phrase gives a visual way to describe geographical spread.","zh":"這個短語以視覺方式描述地理擴散。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":2},{"front":"stretch from…to…","meaning":"從……延伸至……","examples":[{"en":"The affected area stretched from west of Paris to northern Italy.","zh":"受影響地區從巴黎以西延伸至意大利北部。"},{"en":"To stretch from one place to another means to extend across the distance between them.","zh":"“Stretch from…to…” 指從一處延伸到另一處，跨越兩地之間的距離。"},{"en":"The traffic jam stretched from the tunnel entrance to the city centre.","zh":"交通擠塞從隧道入口延伸至市中心。"},{"en":"If a heatwave stretches across many regions, emergency services may face pressure in several places.","zh":"如果熱浪延伸跨越多個地區，多地緊急服務都可能面對壓力。"},{"en":"The phrase describes geographical length or coverage.","zh":"這個短語描述地理長度或覆蓋範圍。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":2},{"front":"taking in","meaning":"包括；涵蓋","examples":[{"en":"The area took in Switzerland and southern Germany.","zh":"該地區包括瑞士和德國南部。"},{"en":"Taking in means including places, people or things as part of a larger area or group.","zh":"“Taking in” 指把某些地方、人或事物包括在較大範圍或群體之內。"},{"en":"A school trip route may take in a museum, a park and an old market street.","zh":"學校旅行路線可能涵蓋博物館、公園和舊市場街。"},{"en":"If a storm path takes in several cities, many communities need warnings.","zh":"如果風暴路徑包括幾個城市，許多社區都需要警告。"},{"en":"The phrase shows what is included within a wider range.","zh":"這個短語顯示較大範圍內包括甚麼。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":2},{"front":"average temperature","meaning":"平均氣溫","examples":[{"en":"The average temperature for the summer months was far above normal.","zh":"夏季月份的平均氣溫遠高於正常水平。"},{"en":"Average temperature is the typical temperature calculated from many measurements.","zh":"平均氣溫是由多次量度計算出的典型溫度。"},{"en":"A teacher may ask students to find the average temperature for a week by adding daily temperatures and dividing by seven.","zh":"老師可能要求學生把每日氣溫相加再除以七，找出一星期平均氣溫。"},{"en":"If the average temperature is high, the whole period was warm, not just one afternoon.","zh":"如果平均氣溫高，整段時期都炎熱，而不只是某個下午。"},{"en":"The phrase helps compare weather over time.","zh":"這個短語幫助比較不同時期的天氣。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":2},{"front":"summer months","meaning":"夏季月份","examples":[{"en":"The average temperature for the summer months was 3.78°C above the norm.","zh":"夏季月份的平均氣溫比正常水平高3.78°C。"},{"en":"Summer months are the months that make up the summer season.","zh":"夏季月份是構成夏季的月份。"},{"en":"In many school calendars, summer months are when students have a long holiday.","zh":"在許多校曆中，夏季月份是學生放長假的時候。"},{"en":"If summer months become hotter, electricity use and health risks may rise.","zh":"如果夏季月份變得更熱，用電量和健康風險可能上升。"},{"en":"The phrase gives the seasonal time period being measured.","zh":"這個短語給出被量度的季節時期。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":2},{"front":"above the long-term norm","meaning":"高於長期正常水平","examples":[{"en":"The average temperature was 3.78°C above the long-term norm.","zh":"平均氣溫比長期正常水平高3.78°C。"},{"en":"Above the long-term norm means higher than the usual level measured over many years.","zh":"“Above the long-term norm” 指高於多年量度出的通常水平。"},{"en":"If a student’s score is far above the long-term class norm, the result is exceptional.","zh":"如果學生分數遠高於班級長期正常水平，該結果就是異常出色。"},{"en":"When temperatures stay above the long-term norm, scientists look for possible climate patterns.","zh":"當氣溫持續高於長期正常水平，科學家會尋找可能的氣候模式。"},{"en":"The phrase compares a current value with a long-established average.","zh":"這個短語把當前數值與長期平均作比較。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":2},{"front":"long-term norm","meaning":"長期正常水平","examples":[{"en":"The long-term norm was exceeded by almost four degrees.","zh":"長期正常水平被超過了接近四度。"},{"en":"A long-term norm is the usual average pattern measured over many years.","zh":"長期正常水平是多年量度出的通常平均模式。"},{"en":"A school may compare this year’s attendance with the long-term norm to see if absence has increased.","zh":"學校可能把今年出席率與長期正常水平比較，看缺席是否增加。"},{"en":"If a value exceeds the long-term norm, it is higher than what is normally expected.","zh":"如果某數值超過長期正常水平，它就高於通常預期。"},{"en":"The phrase provides a stable baseline for comparison.","zh":"這個短語提供穩定的比較基準。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":2},{"front":"Climatic Research Unit","meaning":"氣候研究組","examples":[{"en":"The Climatic Research Unit analysed the temperature records.","zh":"氣候研究組分析了氣溫記錄。"},{"en":"The Climatic Research Unit is a research group that studies climate and temperature data.","zh":"氣候研究組是研究氣候和氣溫數據的研究團隊。"},{"en":"A university research unit may analyse long-term records to understand environmental change.","zh":"大學研究組可能分析長期記錄，以理解環境變化。"},{"en":"If a climatic research unit studies a heatwave, its findings can help explain how unusual the event was.","zh":"如果氣候研究組研究熱浪，其發現可以幫助解釋事件有多異常。"},{"en":"The phrase names a specialist climate research body.","zh":"這個短語指一個專門氣候研究機構。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":3},{"front":"University of East Anglia","meaning":"東英吉利亞大學","examples":[{"en":"The Climatic Research Unit is part of the University of East Anglia.","zh":"氣候研究組是東英吉利亞大學的一部分。"},{"en":"The University of East Anglia is a university in England associated here with climate research.","zh":"東英吉利亞大學是英格蘭一所大學，在此與氣候研究相關。"},{"en":"A student may cite a university department when using research data in an essay.","zh":"學生在作文中使用研究數據時，可能引用大學部門。"},{"en":"If a research unit belongs to a university, its work is usually academic and evidence-based.","zh":"如果研究組隸屬於大學，其工作通常是學術和以證據為本的。"},{"en":"The phrase identifies the institution connected with the research unit.","zh":"這個短語指出與研究組相關的機構。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":3},{"front":"leading institutions","meaning":"領先機構","examples":[{"en":"The CRU is one of the world’s leading institutions for temperature analysis.","zh":"氣候研究組是世界上氣溫分析方面的領先機構之一。"},{"en":"Leading institutions are organisations recognised as especially important or expert in a field.","zh":"領先機構是在某領域中被認為特別重要或專業的組織。"},{"en":"A leading hospital may attract patients because its doctors handle difficult cases well.","zh":"領先醫院可能因醫生擅長處理困難病例而吸引病人。"},{"en":"If a leading institution reports unusual data, people are likely to take it seriously.","zh":"如果領先機構報告異常數據，人們很可能認真看待。"},{"en":"The phrase suggests authority, expertise and reputation.","zh":"這個短語暗示權威、專業和聲譽。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":3},{"front":"monitoring and analysis","meaning":"監測和分析","examples":[{"en":"The institution specialises in the monitoring and analysis of temperature records.","zh":"該機構專門監測和分析氣溫記錄。"},{"en":"Monitoring and analysis means collecting information over time and studying it carefully.","zh":"監測和分析指隨時間收集資料並仔細研究它。"},{"en":"A school may use monitoring and analysis of attendance to find students who need help.","zh":"學校可能透過監測和分析出席率，找出需要幫助的學生。"},{"en":"If scientists monitor and analyse temperatures, they can detect unusual climate patterns.","zh":"如果科學家監測並分析氣溫，就能偵測異常氣候模式。"},{"en":"The phrase combines observation with explanation.","zh":"這個短語結合觀察與解釋。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":3},{"front":"temperature records","meaning":"氣溫記錄","examples":[{"en":"The CRU studies long-term temperature records.","zh":"氣候研究組研究長期氣溫記錄。"},{"en":"Temperature records are collected measurements of temperature over time.","zh":"氣溫記錄是隨時間收集的氣溫量度數據。"},{"en":"A weather station keeps temperature records so people can compare today with past years.","zh":"氣象站保存氣溫記錄，使人們可以把今天與過去年份比較。"},{"en":"If temperature records go back many decades, scientists can identify trends more reliably.","zh":"如果氣溫記錄追溯數十年，科學家就能更可靠地識別趨勢。"},{"en":"The phrase refers to data, not casual memories of hot weather.","zh":"這個短語指數據，而不是對炎熱天氣的隨意記憶。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":3},{"front":"that excess","meaning":"那個超出幅度","examples":[{"en":"That excess might not seem a lot without context.","zh":"如果沒有背景，那個超出幅度可能看似不多。"},{"en":"That excess means the amount by which something is above the normal or expected level.","zh":"那個超出幅度指某事高於正常或預期水平的量。"},{"en":"A bill that is $5 above normal may not seem serious until it happens every week.","zh":"一張帳單比平常高5美元可能看似不嚴重，直到它每星期都發生。"},{"en":"If the excess temperature is nearly four degrees, the number becomes important when compared with past data.","zh":"如果超出正常水平的氣溫接近四度，與過往數據比較時這數字就變得重要。"},{"en":"The phrase points back to an amount that has gone beyond a standard.","zh":"這個短語指回已超過某標準的幅度。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":3},{"front":"be aware of the context","meaning":"了解背景","examples":[{"en":"You realise the excess is enormous when you are aware of the context.","zh":"當你了解背景時，就會意識到那個超出幅度非常巨大。"},{"en":"To be aware of the context means to understand the background needed to judge something properly.","zh":"“Be aware of the context” 指理解正確判斷某事所需的背景。"},{"en":"A student may think a score is low until they are aware of the context that the test was extremely difficult.","zh":"學生可能以為分數低，直到了解到該測驗極其困難這個背景。"},{"en":"If readers know the climate records, they become aware of why a few degrees matter.","zh":"如果讀者知道氣候記錄，就會明白為何幾度也重要。"},{"en":"The phrase shows that meaning depends on surrounding information.","zh":"這個短語顯示意義取決於周邊資料。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":3},{"front":"previous data","meaning":"以往數據","examples":[{"en":"There is nothing like this in previous data.","zh":"以往數據中沒有任何類似情況。"},{"en":"Previous data means information collected earlier or from past records.","zh":"以往數據指較早或過去記錄中收集的資料。"},{"en":"Doctors compare new test results with previous data to see whether a patient is improving.","zh":"醫生把新檢查結果與以往數據比較，以判斷病人是否改善。"},{"en":"If a heatwave has no match in previous data, it may be historically exceptional.","zh":"如果熱浪在以往數據中沒有相似案例，它可能在歷史上異常。"},{"en":"The phrase helps compare new findings with older evidence.","zh":"這個短語幫助把新發現與舊證據比較。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":3},{"front":"be considered so exceptional that","meaning":"被認為異常到……","examples":[{"en":"The summer is considered so exceptional that scientists link it to global warming.","zh":"那個夏天被認為異常到科學家把它與全球暖化聯繫起來。"},{"en":"To be considered so exceptional that means to be judged unusually extreme enough to lead to a conclusion or result.","zh":"“Be considered so exceptional that” 指被判斷為異常到足以導致某結論或結果。"},{"en":"A student’s performance may be considered so exceptional that the school offers a scholarship.","zh":"學生表現可能被認為出色到學校提供獎學金。"},{"en":"If a weather event is so unusual, researchers may look beyond normal variation for causes.","zh":"如果天氣事件如此異常，研究人員可能尋找正常變異以外的原因。"},{"en":"The phrase links an extreme judgement with its consequence.","zh":"這個短語把極端判斷與其後果連繫起來。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":3},{"front":"be prepared to say openly","meaning":"願意公開表示","examples":[{"en":"Professor Jones is prepared to say openly that global warming was involved.","zh":"Jones 教授願意公開表示全球暖化牽涉其中。"},{"en":"To be prepared to say openly means to be willing to state something clearly in public.","zh":"“Be prepared to say openly” 指願意在公開場合清楚表明某事。"},{"en":"A manager may be prepared to say openly that a project failed because planning was weak.","zh":"經理可能願意公開表示項目失敗是因為規劃薄弱。"},{"en":"If scientists say something openly, they are no longer hiding behind cautious language.","zh":"如果科學家公開表示某事，他們就不再躲在謹慎措辭後。"},{"en":"The phrase suggests confidence and public willingness.","zh":"這個短語暗示信心和公開表態的意願。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":3},{"front":"directly attributed to","meaning":"直接歸因於","examples":[{"en":"The 2003 extreme may be directly attributed to global warming.","zh":"2003年的極端情況可能直接歸因於全球暖化。"},{"en":"To be directly attributed to something means to be explained as a direct result of it.","zh":"“Be directly attributed to” 某事指被解釋為它的直接結果。"},{"en":"A student’s tiredness may be directly attributed to staying up all night.","zh":"學生疲倦可能直接歸因於通宵不睡。"},{"en":"If a heatwave is directly attributed to warming, scientists believe the link is strong.","zh":"如果熱浪直接歸因於暖化，科學家就認為其關聯很強。"},{"en":"The phrase connects an effect to a specific cause.","zh":"這個短語把結果連接到特定原因。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":3},{"front":"natural climate variability","meaning":"自然氣候變化","examples":[{"en":"The heatwave was not simply due to natural climate variability.","zh":"這場熱浪並不只是由自然氣候變化造成。"},{"en":"Natural climate variability means normal changes in climate that happen without human-caused warming.","zh":"自然氣候變化指沒有由人為暖化造成的正常氣候變動。"},{"en":"Some years are wetter or hotter because of natural climate variability.","zh":"有些年份較濕或較熱，是因為自然氣候變化。"},{"en":"If an event is far beyond natural variability, scientists may look for human influence.","zh":"如果某事件遠超自然變異，科學家可能尋找人類影響。"},{"en":"The phrase separates ordinary climate fluctuation from longer-term climate change.","zh":"這個短語把普通氣候波動與較長期氣候變化分開。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":4},{"front":"caused by human actions","meaning":"由人類活動造成","examples":[{"en":"Global warming is caused by human actions.","zh":"全球暖化由人類活動造成。"},{"en":"Caused by human actions means produced or made worse by what people do.","zh":"“Caused by human actions” 指由人類所做的事產生或加劇。"},{"en":"Air pollution near busy roads is often caused by human actions such as driving and burning fuel.","zh":"繁忙道路附近的空氣污染常由駕駛和燃燒燃料等人類活動造成。"},{"en":"If a problem is caused by human actions, people may also have power to reduce it.","zh":"如果問題由人類活動造成，人類也可能有能力減少它。"},{"en":"The phrase points to human responsibility.","zh":"這個短語指向人類責任。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":4},{"front":"meteorologists","meaning":"氣象學家","examples":[{"en":"Meteorologists had previously used more cautious language.","zh":"氣象學家以前使用較謹慎的語言。"},{"en":"Meteorologists are scientists who study weather and atmosphere.","zh":"氣象學家是研究天氣和大氣的科學家。"},{"en":"Meteorologists help the public prepare for storms, heatwaves and heavy rain.","zh":"氣象學家幫助公眾準備風暴、熱浪和大雨。"},{"en":"If meteorologists use cautious language, they may be avoiding claims beyond the evidence.","zh":"如果氣象學家使用謹慎語言，他們可能在避免超出證據的說法。"},{"en":"The word refers to weather experts.","zh":"這個詞指天氣專家。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":4},{"front":"hitherto","meaning":"迄今為止","examples":[{"en":"Meteorologists had hitherto contented themselves with cautious statements.","zh":"迄今為止，氣象學家一直只限於作出謹慎陳述。"},{"en":"Hitherto means until now or until that point in time.","zh":"“Hitherto” 指直到現在或直到那個時間點為止。"},{"en":"The school had hitherto avoided online lessons, but the storm forced a change.","zh":"學校迄今為止一直避免網上課堂，但風暴迫使情況改變。"},{"en":"If scientists had hitherto been cautious, a stronger statement marks a change.","zh":"如果科學家迄今為止一直謹慎，更強烈的陳述就標誌着改變。"},{"en":"The word is formal and points to the period before a new development.","zh":"這個詞較正式，指向新發展以前的時期。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":4},{"front":"content themselves with","meaning":"滿足於；只限於","examples":[{"en":"Meteorologists had contented themselves with saying the heat was consistent with predictions.","zh":"氣象學家一直只限於說高溫與預測一致。"},{"en":"To content themselves with something means to accept doing only that and not go further.","zh":"“Content themselves with” 某事指接受只做那件事，而不再進一步。"},{"en":"A student may content himself with passing the test instead of aiming for a higher score.","zh":"學生可能滿足於考試合格，而不是追求更高分數。"},{"en":"If experts content themselves with cautious claims, they avoid making stronger conclusions.","zh":"如果專家只限於謹慎說法，他們就避免作出更強結論。"},{"en":"The phrase suggests restraint or limited ambition.","zh":"這個短語暗示克制或有限追求。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":4},{"front":"be consistent with","meaning":"與……一致","examples":[{"en":"Recent high temperatures are consistent with predictions of climate change.","zh":"近期高溫與氣候變化預測一致。"},{"en":"To be consistent with something means to match it or agree with what it suggests.","zh":"“Be consistent with” 某事指與它相符或符合它所暗示的內容。"},{"en":"A student’s tired face is consistent with the fact that she slept badly.","zh":"學生疲倦的臉色與她睡得不好這個事實一致。"},{"en":"If new data is consistent with a theory, it supports the theory but may not prove it alone.","zh":"如果新數據與理論一致，它支持該理論，但單獨未必能證明它。"},{"en":"The phrase shows agreement between evidence and expectation.","zh":"這個短語顯示證據與預期相符。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":4},{"front":"predictions of climate change","meaning":"氣候變化預測","examples":[{"en":"The high temperatures matched predictions of climate change.","zh":"高溫符合氣候變化預測。"},{"en":"Predictions of climate change are forecasts about how climate may alter in the future.","zh":"氣候變化預測是關於未來氣候可能如何改變的預測。"},{"en":"Scientists compare real weather data with predictions of climate change to test their models.","zh":"科學家把真實天氣數據與氣候變化預測比較，以測試模型。"},{"en":"If heatwaves match earlier predictions, confidence in those climate models may increase.","zh":"如果熱浪符合早前預測，人們對那些氣候模型的信心可能增加。"},{"en":"The phrase refers to expected climate patterns based on research.","zh":"這個短語指基於研究而預期的氣候模式。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":4},{"front":"reliable temperature records","meaning":"可靠氣溫記錄","examples":[{"en":"The CRU has reliable temperature records dating back to 1781.","zh":"氣候研究組擁有可追溯至1781年的可靠氣溫記錄。"},{"en":"Reliable temperature records are trustworthy measurements that can be used for serious comparison.","zh":"可靠氣溫記錄是可信、可用於嚴肅比較的量度數據。"},{"en":"A school needs reliable attendance records before it can identify long-term absence problems.","zh":"學校需要可靠出席記錄，才能識別長期缺席問題。"},{"en":"If temperature records are reliable, scientists can compare modern heat with past climate more fairly.","zh":"如果氣溫記錄可靠，科學家就能更公平地比較現代高溫與過去氣候。"},{"en":"The phrase stresses accuracy and trustworthiness in data.","zh":"這個短語強調數據的準確性和可信度。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":4},{"front":"date back to","meaning":"追溯至","examples":[{"en":"The records date back to 1781.","zh":"這些記錄追溯至1781年。"},{"en":"To date back to a time means to have existed since that time.","zh":"“Date back to” 某時指自該時起已存在。"},{"en":"The school building dates back to the nineteenth century.","zh":"這座校舍可追溯至十九世紀。"},{"en":"If records date back a long way, they help people study long-term change.","zh":"如果記錄追溯得很久，它們有助人們研究長期變化。"},{"en":"The phrase connects something present with an earlier starting point.","zh":"這個短語把現在存在的事物與較早起點連繫起來。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":4},{"front":"using as a baseline","meaning":"以……作為基準","examples":[{"en":"The researchers used average summer temperature as a baseline.","zh":"研究人員以夏季平均氣溫作為基準。"},{"en":"Using something as a baseline means using it as a standard for comparison.","zh":"“Using something as a baseline” 指用某物作比較標準。"},{"en":"A teacher may use the first quiz score as a baseline to measure later progress.","zh":"老師可能以第一次小測分數作為基準，量度之後進步。"},{"en":"If scientists use a baseline, they can see how far new values move away from normal.","zh":"如果科學家使用基準，就能看出新數值偏離正常水平多少。"},{"en":"The phrase explains the reference point for comparison.","zh":"這個短語解釋比較用的參照點。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":4},{"front":"average summer temperature","meaning":"夏季平均氣溫","examples":[{"en":"The baseline was the average summer temperature from 1961 to 1990.","zh":"基準是1961年至1990年的夏季平均氣溫。"},{"en":"Average summer temperature is the typical summer temperature calculated across many years or measurements.","zh":"夏季平均氣溫是跨多年或多次量度計算出的典型夏季溫度。"},{"en":"A city can compare today’s summer heat with its average summer temperature from past decades.","zh":"城市可以把今天夏季高溫與過去數十年的夏季平均氣溫比較。"},{"en":"If the average summer temperature rises, summers are becoming warmer overall.","zh":"如果夏季平均氣溫上升，整體夏天就變得更暖。"},{"en":"The phrase helps measure seasonal climate change.","zh":"這個短語有助量度季節性氣候變化。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":4},{"front":"departures from the temperature norm","meaning":"偏離氣溫正常值","examples":[{"en":"The graph shows departures from the temperature norm.","zh":"圖表顯示偏離氣溫正常值的情況。"},{"en":"Departures from the temperature norm are differences between actual temperatures and the usual expected level.","zh":"偏離氣溫正常值，是實際氣溫與通常預期水平之間的差異。"},{"en":"A class score of 90 may be a departure from the norm if the usual average is 60.","zh":"如果平常平均分是60分，班級分數90分可能就是偏離正常值。"},{"en":"If temperature departures are large, the weather is far from normal.","zh":"如果氣溫偏離幅度大，天氣就遠離正常。"},{"en":"The phrase is useful when comparing measured values with a baseline.","zh":"這個短語適用於把量度值與基準比較。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":5},{"front":"anomalies","meaning":"異常值","examples":[{"en":"Temperature anomalies can be plotted over time.","zh":"氣溫異常值可以隨時間被繪製出來。"},{"en":"Anomalies are values or events that differ from what is normal or expected.","zh":"異常值是與正常或預期不同的數值或事件。"},{"en":"A teacher may notice anomalies in test results when several strong students suddenly score very low.","zh":"當幾名強學生突然得很低分，老師可能注意到測驗結果中的異常值。"},{"en":"If temperature anomalies keep rising, scientists may investigate deeper climate causes.","zh":"如果氣溫異常值持續上升，科學家可能研究更深層氣候原因。"},{"en":"The word points to unusual differences in data.","zh":"這個詞指數據中的不尋常差異。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":5},{"front":"as a whole","meaning":"整體而言","examples":[{"en":"The anomalies were measured over the area as a whole.","zh":"這些異常值是就整個地區整體而言量度的。"},{"en":"As a whole means considering all parts together rather than separately.","zh":"“As a whole” 指把所有部分一起考慮，而不是分開看。"},{"en":"A teacher may judge a student’s progress as a whole, not from one bad quiz.","zh":"老師可能整體而言判斷學生進步，而不是只看一次差的小測。"},{"en":"If a region is studied as a whole, local differences are combined into a general picture.","zh":"如果以整體方式研究一個地區，本地差異會被合併成總體圖像。"},{"en":"The phrase focuses on the overall view.","zh":"這個短語強調整體觀點。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":5},{"front":"be plotted","meaning":"被繪製出來","examples":[{"en":"Temperature anomalies can easily be plotted on a graph.","zh":"氣溫異常值可以容易地在圖表上被繪製出來。"},{"en":"To be plotted means to be marked or shown on a chart, map or graph.","zh":"“Be plotted” 指被標示或顯示在圖表、地圖或曲線圖上。"},{"en":"A student may plot daily spending on a graph to see where money goes.","zh":"學生可能把每日開支繪製在圖表上，以看出金錢流向。"},{"en":"If temperature changes are plotted, patterns can become easier to see.","zh":"如果氣溫變化被繪製出來，模式就更容易被看見。"},{"en":"The phrase describes turning data into a visual form.","zh":"這個短語描述把數據轉化為視覺形式。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":5},{"front":"such is the variability of","meaning":"……的變化性如此之大","examples":[{"en":"Such is the variability of our climate that hot years have occurred before.","zh":"我們氣候的變化性如此之大，以致過去也曾出現炎熱年份。"},{"en":"Such is the variability of something means it changes so much that a certain result is possible.","zh":"“Such is the variability of” 某事指它變化如此之大，以致某結果可能發生。"},{"en":"Such is the variability of school timetables that students must check updates every week.","zh":"學校時間表的變化性如此之大，以致學生必須每星期查看更新。"},{"en":"If climate variability is high, occasional hot years can happen naturally.","zh":"如果氣候變異性高，偶爾自然出現炎熱年份是可能的。"},{"en":"The phrase uses formal inversion to emphasise how changeable something is.","zh":"這個短語使用正式倒裝，強調某事有多變。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":5},{"front":"over the past 200 years","meaning":"在過去二百年","examples":[{"en":"There have been several hot anomalies over the past 200 years.","zh":"在過去二百年，曾有幾個炎熱異常值。"},{"en":"Over the past 200 years means during the two centuries before the present point being discussed.","zh":"“Over the past 200 years” 指在所討論現在之前的兩個世紀期間。"},{"en":"Over the past 200 years, many cities have grown from small towns into huge urban areas.","zh":"在過去二百年，許多城市由小鎮發展成巨大都市。"},{"en":"If records cover the past 200 years, researchers can compare many generations of data.","zh":"如果記錄涵蓋過去二百年，研究人員就能比較許多世代的數據。"},{"en":"The phrase gives a long historical time frame.","zh":"這個短語給出長歷史時段。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":5},{"front":"at least half a dozen","meaning":"至少六個","examples":[{"en":"There have been at least half a dozen major anomalies before 2003.","zh":"2003年之前，至少有六個重大異常值。"},{"en":"At least half a dozen means six or more.","zh":"“At least half a dozen” 指六個或以上。"},{"en":"A teacher may receive at least half a dozen emails before the school day begins.","zh":"老師可能在上課日開始前已收到至少六封電郵。"},{"en":"If at least half a dozen earlier anomalies existed, hot years were not completely unknown.","zh":"如果早前至少有六個異常值，炎熱年份就並非完全未見過。"},{"en":"The phrase gives a minimum number in a natural way.","zh":"這個短語以自然方式給出最低數量。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":5},{"front":"in terms of","meaning":"就……而言","examples":[{"en":"The anomalies were measured in terms of excess temperature.","zh":"這些異常值是就超出正常水平的氣溫而言量度的。"},{"en":"In terms of means according to a particular aspect or measure.","zh":"“In terms of” 指按照某個特定方面或量度標準。"},{"en":"In terms of cost, taking the bus may be better than driving.","zh":"就成本而言，乘巴士可能比駕車更好。"},{"en":"If a heatwave is measured in terms of excess temperature, the focus is how far above normal it was.","zh":"如果熱浪是就超出氣溫而言量度，重點就是它高於正常水平多少。"},{"en":"The phrase limits the discussion to one angle.","zh":"這個短語把討論限制在某一角度。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":5},{"front":"excess temperature","meaning":"超出正常水平的氣溫","examples":[{"en":"The peaks on the graph show years with excess temperature.","zh":"圖表上的峰值顯示氣溫超出正常水平的年份。"},{"en":"Excess temperature is the amount by which temperature is higher than the normal level.","zh":"超出正常水平的氣溫，是氣溫高於正常水平的幅度。"},{"en":"If a classroom is five degrees warmer than usual, that extra heat is excess temperature.","zh":"如果課室比平常暖五度，那額外熱度就是超出正常水平的氣溫。"},{"en":"Excess temperature can increase health risks during long heatwaves.","zh":"在長時間熱浪期間，超出正常水平的氣溫可增加健康風險。"},{"en":"The phrase focuses on the difference above a baseline.","zh":"這個短語強調高於基準的差距。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":5},{"front":"peaks on the graph","meaning":"圖表上的峰值","examples":[{"en":"The peaks on the graph denote very hot years.","zh":"圖表上的峰值表示非常炎熱的年份。"},{"en":"Peaks on the graph are the highest points that show unusually large values.","zh":"圖表上的峰值是顯示異常高數值的最高點。"},{"en":"In a sales chart, peaks on the graph may appear during holiday shopping seasons.","zh":"在銷售圖表中，峰值可能出現在假期購物季。"},{"en":"If temperature peaks are high, they show years that stood out from the average.","zh":"如果氣溫峰值很高，它們就顯示那些年份突出於平均水平。"},{"en":"The phrase helps students read visual data.","zh":"這個短語幫助學生閱讀視覺數據。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":5},{"front":"denote","meaning":"表示","examples":[{"en":"The peaks denote very hot years.","zh":"這些峰值表示非常炎熱的年份。"},{"en":"To denote something means to represent, indicate or stand for it.","zh":"“Denote” 某事指代表、表示或象徵它。"},{"en":"On a map, a blue line may denote a river.","zh":"在地圖上，藍線可能表示河流。"},{"en":"If a symbol denotes danger, people should recognise it quickly.","zh":"如果符號表示危險，人們應能迅速認出。"},{"en":"The word is useful when explaining charts, signs and symbols.","zh":"這個詞適合用來解釋圖表、標誌和符號。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":5},{"front":"approach or exceed","meaning":"接近或超過","examples":[{"en":"Some earlier anomalies approached or exceeded 2°C.","zh":"一些較早異常值接近或超過2°C。"},{"en":"To approach or exceed a number means to come near it or go beyond it.","zh":"“Approach or exceed” 某數字指接近它或超過它。"},{"en":"A student’s score may approach or exceed the class average after extra practice.","zh":"經過額外練習後，學生分數可能接近或超過班級平均。"},{"en":"If temperatures approach or exceed a warning level, public health alerts may be issued.","zh":"如果氣溫接近或超過警戒水平，可能發出公共健康警告。"},{"en":"The phrase covers values near and above a threshold.","zh":"這個短語涵蓋接近和高於門檻的數值。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":6},{"front":"remotely like","meaning":"與……相似的","examples":[{"en":"There has been nothing remotely like 2003.","zh":"從來沒有任何事情稍微與2003年相似。"},{"en":"Remotely like means even slightly similar to something.","zh":"“Remotely like” 指即使只有一點點相似。"},{"en":"The school had seen difficult exams before, but nothing remotely like this year’s paper.","zh":"學校以前見過困難考試，但沒有任何試卷與今年這份稍微相似。"},{"en":"If no previous summer was remotely like 2003, the difference was extreme.","zh":"如果以前沒有任何夏天稍微像2003年，差異就是極端的。"},{"en":"The phrase is usually used to emphasise strong dissimilarity.","zh":"這個短語通常用來強調強烈不相似。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":6},{"front":"in a statistical sense","meaning":"從統計角度看","examples":[{"en":"The 2003 summer was very unusual in a statistical sense.","zh":"從統計角度看，2003年夏天非常不尋常。"},{"en":"In a statistical sense means according to numbers, probability and data patterns.","zh":"“In a statistical sense” 指根據數字、概率和數據模式。"},{"en":"In a statistical sense, one unusually high score may not prove that the whole class improved.","zh":"從統計角度看，一個異常高分未必證明全班都有進步。"},{"en":"If an event is rare in a statistical sense, the data shows it is unlikely to occur often.","zh":"如果事件從統計角度看罕見，數據就顯示它不太可能經常發生。"},{"en":"The phrase frames a claim through numerical analysis.","zh":"這個短語用數值分析框定某說法。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":6},{"front":"normal statistical distribution","meaning":"正常統計分布","examples":[{"en":"The 2003 figure would not appear in a normal statistical distribution.","zh":"2003年的數值不會出現在正常統計分布中。"},{"en":"A normal statistical distribution is a common bell-shaped pattern in which most values sit near the average.","zh":"正常統計分布是一種常見鐘形模式，大多數數值集中在平均值附近。"},{"en":"In a normal statistical distribution of test scores, most students cluster around the middle.","zh":"在測驗分數的正常統計分布中，大多數學生集中在中間附近。"},{"en":"If a value falls far outside the normal distribution, it may be an extreme outlier.","zh":"如果某數值遠遠落在正常分布之外，它可能是極端離群值。"},{"en":"The phrase describes an expected pattern in data.","zh":"這個短語描述數據中的預期模式。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":6},{"front":"return period","meaning":"重現週期","examples":[{"en":"The return period would be something like one in a thousand years.","zh":"重現週期大概是一千年一遇。"},{"en":"A return period is the estimated average time between events of a similar size or severity.","zh":"重現週期是類似規模或嚴重程度事件之間的估計平均時間。"},{"en":"Engineers use return periods when deciding how strong flood barriers should be.","zh":"工程師決定防洪屏障應有多強時，會使用重現週期。"},{"en":"If a heatwave has a long return period, it is expected to happen very rarely.","zh":"如果熱浪重現週期很長，就預期它非常罕見地發生。"},{"en":"The phrase expresses rarity in time-based terms.","zh":"這個短語以時間方式表達罕見程度。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":6},{"front":"be expected to recur","meaning":"預期再次發生","examples":[{"en":"The event could be expected to recur only very rarely.","zh":"該事件預期只會非常罕見地再次發生。"},{"en":"To be expected to recur means to be predicted to happen again.","zh":"“Be expected to recur” 指被預測會再次發生。"},{"en":"A flood may be expected to recur if the drainage problem is not fixed.","zh":"如果排水問題沒有修好，水浸可能預期會再次發生。"},{"en":"If an event is expected to recur only once in many centuries, it is extremely rare.","zh":"如果事件預期許多世紀才重現一次，它就是極其罕見。"},{"en":"The phrase focuses on future repetition.","zh":"這個短語強調未來重複發生。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":6},{"front":"one in a thousand years","meaning":"一千年一遇","examples":[{"en":"The return period could be one in a thousand years.","zh":"重現週期可能是一千年一遇。"},{"en":"One in a thousand years means an event is expected to happen only once in about a thousand years.","zh":"一千年一遇指某事件預期大約一千年才發生一次。"},{"en":"A one-in-a-thousand-year flood would be far beyond what most people have experienced.","zh":"一千年一遇的洪水會遠超大多數人經歷過的情況。"},{"en":"If a heatwave is described this way, it is statistically extraordinary.","zh":"如果熱浪被這樣描述，它在統計上就是非凡的。"},{"en":"The phrase emphasises extreme rarity.","zh":"這個短語強調極端罕見。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":6},{"front":"excess above the average","meaning":"高於平均值的幅度","examples":[{"en":"The heatwave showed an excess above the average of nearly four degrees.","zh":"這場熱浪顯示高於平均值的幅度接近四度。"},{"en":"Excess above the average means the amount higher than the usual average level.","zh":"高於平均值的幅度指高於通常平均水平的數量。"},{"en":"If a family spends $300 more than average this month, that is an excess above the average.","zh":"如果家庭本月開支比平均多300美元，那就是高於平均值的幅度。"},{"en":"When temperature excess above the average is large, ordinary weather explanations may not be enough.","zh":"當氣溫高於平均值的幅度很大，普通天氣解釋可能不足。"},{"en":"The phrase measures how far something rises beyond normal.","zh":"這個短語量度某事超出正常多少。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":6},{"front":"natural variability","meaning":"自然變異","examples":[{"en":"Part of the heat was due to natural variability.","zh":"部分高溫是由自然變異造成。"},{"en":"Natural variability means normal ups and downs that happen without a single unusual cause.","zh":"自然變異指沒有單一異常原因下出現的正常高低變化。"},{"en":"A student’s marks may show natural variability from test to test.","zh":"學生分數在不同測驗之間可能顯示自然變異。"},{"en":"If weather changes because of natural variability, some years may be hotter or cooler by chance.","zh":"如果天氣因自然變異而改變，有些年份可能偶然較熱或較冷。"},{"en":"The phrase describes ordinary variation in a system.","zh":"這個短語描述系統中的普通變化。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":6},{"front":"be likely to be due to","meaning":"很可能是由於","examples":[{"en":"The final degree is likely to be due to global warming.","zh":"最後一度很可能是由於全球暖化。"},{"en":"To be likely to be due to something means probably caused by it.","zh":"“Be likely to be due to” 某事指很可能由它造成。"},{"en":"A child’s tiredness is likely to be due to lack of sleep if they stayed up all night.","zh":"如果孩子整晚不睡，他的疲倦很可能是由於睡眠不足。"},{"en":"If one part of the heat cannot be explained by natural variability, it may be due to warming.","zh":"如果部分高溫不能由自然變異解釋，它可能是由暖化造成。"},{"en":"The phrase expresses a probable cause without claiming absolute certainty.","zh":"這個短語表達可能原因，但不是絕對肯定。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":6},{"front":"in a sense","meaning":"在某種意義上","examples":[{"en":"The summer of 2003 had, in a sense, long been expected.","zh":"2003年夏天在某種意義上早已被預期。"},{"en":"In a sense means from one particular point of view or in one way.","zh":"“In a sense” 指從某個特定角度或在某種方面來說。"},{"en":"In a sense, homework is practice for exams, but it is also a way to build habits.","zh":"在某種意義上，功課是考試練習，但它也是建立習慣的方法。"},{"en":"If scientists expected a very hot summer eventually, 2003 was not surprising in one sense.","zh":"如果科學家預期終有一天會出現非常炎熱的夏天，2003年在某種意義上就不令人意外。"},{"en":"The phrase softens a statement by limiting how it should be understood.","zh":"這個短語透過限制理解角度，使陳述較溫和。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":6},{"front":"climate scientists","meaning":"氣候科學家","examples":[{"en":"Climate scientists had long expected an unprecedented hot summer.","zh":"氣候科學家早已預期會有前所未有的酷熱夏季。"},{"en":"Climate scientists are researchers who study long-term climate patterns and change.","zh":"氣候科學家是研究長期氣候模式和變化的研究人員。"},{"en":"Climate scientists use data from oceans, ice, air and land to understand the planet.","zh":"氣候科學家使用海洋、冰層、空氣和土地數據來理解地球。"},{"en":"If climate scientists warn about heatwaves, governments may need to plan public health measures.","zh":"如果氣候科學家警告熱浪，政府可能需要規劃公共健康措施。"},{"en":"The phrase refers to experts in climate, not just daily weather.","zh":"這個短語指氣候專家，而不只是每日天氣專家。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":7},{"front":"manifest itself","meaning":"顯現出來","examples":[{"en":"Warming has manifested itself mainly in milder winters.","zh":"暖化主要以較溫和冬季的形式顯現出來。"},{"en":"To manifest itself means to appear or show itself clearly.","zh":"“Manifest itself” 指明顯出現或表現出來。"},{"en":"Stress may manifest itself as headaches, poor sleep or irritability.","zh":"壓力可能以頭痛、睡眠差或易怒的形式顯現出來。"},{"en":"If climate change manifests itself in winter first, summers may not look dramatically different at the beginning.","zh":"如果氣候變化最初在冬季顯現，夏季一開始可能看起來沒有巨大差異。"},{"en":"The phrase describes how a hidden process becomes visible.","zh":"這個短語描述隱藏過程如何變得可見。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":7},{"front":"milder winters","meaning":"較溫和的冬季","examples":[{"en":"Global warming first appeared mainly as milder winters.","zh":"全球暖化最初主要以較溫和的冬季出現。"},{"en":"Milder winters are winters that are warmer or less severe than usual.","zh":"較溫和的冬季是比平常更暖或較不嚴酷的冬天。"},{"en":"A city with milder winters may need less heating and see less snow.","zh":"冬季較溫和的城市可能需要較少暖氣，也較少下雪。"},{"en":"If winters become milder, ski resorts at lower levels may lose snow.","zh":"如果冬季變得較溫和，低海拔滑雪度假區可能失去積雪。"},{"en":"The phrase compares winter conditions with colder past norms.","zh":"這個短語把冬季情況與過去較冷正常水平作比較。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":7},{"front":"much hotter summers","meaning":"炎熱得多的夏季","examples":[{"en":"Warming had not previously appeared mainly as much hotter summers.","zh":"暖化以前主要並非以炎熱得多的夏季出現。"},{"en":"Much hotter summers are summers that are far warmer than usual or than past summers.","zh":"炎熱得多的夏季，是遠比平常或過去夏天更熱的夏季。"},{"en":"Families may need fans or air conditioning during much hotter summers.","zh":"在炎熱得多的夏季，家庭可能需要風扇或冷氣。"},{"en":"If summers become much hotter, schools, hospitals and transport systems may face new pressure.","zh":"如果夏季變得炎熱得多，學校、醫院和交通系統可能面對新壓力。"},{"en":"The phrase stresses a strong increase in summer heat.","zh":"這個短語強調夏季高溫大幅增加。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":7},{"front":"the United Nations","meaning":"聯合國","examples":[{"en":"The United Nations predicted changes to winter sports.","zh":"聯合國預測冬季運動會出現變化。"},{"en":"The United Nations is an international organisation made up of many countries.","zh":"聯合國是由許多國家組成的國際組織。"},{"en":"The United Nations may issue reports on climate, health, education and peace.","zh":"聯合國可能發布關於氣候、健康、教育和和平的報告。"},{"en":"If the United Nations warns about a problem, governments may pay more attention.","zh":"如果聯合國警告某問題，政府可能更加關注。"},{"en":"The phrase names a global institution.","zh":"這個短語指一個全球機構。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":7},{"front":"lower-level ski resorts","meaning":"低海拔滑雪度假區","examples":[{"en":"Winter sports may die out in Europe’s lower-level ski resorts.","zh":"冬季運動可能在歐洲低海拔滑雪度假區消失。"},{"en":"Lower-level ski resorts are ski areas located at lower altitudes.","zh":"低海拔滑雪度假區是位於較低海拔的滑雪地區。"},{"en":"A lower-level ski resort may suffer if warmer winters bring rain instead of snow.","zh":"如果較暖冬季帶來的是雨而不是雪，低海拔滑雪度假區可能受損。"},{"en":"If snow disappears from lower slopes, visitors may choose higher mountain resorts.","zh":"如果低坡積雪消失，遊客可能選擇較高山區度假村。"},{"en":"The phrase links ski tourism with altitude and climate.","zh":"這個短語把滑雪旅遊與海拔和氣候連繫起來。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":7},{"front":"sooner or later","meaning":"遲早","examples":[{"en":"Sooner or later, an unprecedented hot summer was bound to come.","zh":"遲早，前所未有的酷熱夏季必然會來臨。"},{"en":"Sooner or later means eventually, even if the exact time is unknown.","zh":"“Sooner or later” 指終有一天，即使確切時間未知。"},{"en":"If a student never reviews vocabulary, sooner or later they will forget many words.","zh":"如果學生從不溫習詞彙，遲早會忘記許多字。"},{"en":"If warming continues, sooner or later a record-breaking summer may occur.","zh":"如果暖化持續，遲早可能出現破紀錄夏天。"},{"en":"The phrase suggests something is expected to happen eventually.","zh":"這個短語暗示某事最終會發生。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":7},{"front":"unprecedented hot summer","meaning":"前所未有的酷熱夏季","examples":[{"en":"The summer of 2003 was an unprecedented hot summer.","zh":"2003年夏天是前所未有的酷熱夏季。"},{"en":"An unprecedented hot summer is a summer hotter than anything previously experienced or recorded.","zh":"前所未有的酷熱夏季，是比以前經歷或記錄過的任何夏天都更熱的夏季。"},{"en":"A city may open cooling centres during an unprecedented hot summer.","zh":"城市可能在前所未有的酷熱夏季開放避暑中心。"},{"en":"If a hot summer is unprecedented, old emergency plans may not be enough.","zh":"如果酷熱夏季前所未有，舊有應急計劃可能不足。"},{"en":"The phrase stresses that the heat has no previous equal.","zh":"這個短語強調高溫沒有過去的相等例子。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":7},{"front":"be bound to","meaning":"必然會","examples":[{"en":"An unprecedented hot summer was bound to come eventually.","zh":"前所未有的酷熱夏季最終必然會來臨。"},{"en":"To be bound to happen means to be very likely or certain to happen.","zh":"“Be bound to” 發生指非常可能或必然會發生。"},{"en":"If a student never sleeps enough, mistakes are bound to appear in exams.","zh":"如果學生一直睡眠不足，考試中必然會出現錯誤。"},{"en":"If temperatures keep rising, more heat records are bound to be broken.","zh":"如果氣溫持續上升，更多高溫紀錄必然會被打破。"},{"en":"The phrase expresses strong expectation.","zh":"這個短語表達強烈預期。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":7},{"front":"dramatic features","meaning":"最顯著特徵","examples":[{"en":"One of the most dramatic features of the summer was the hot nights.","zh":"那個夏天最顯著特徵之一是炎熱夜晚。"},{"en":"Dramatic features are striking or especially noticeable parts of something.","zh":"最顯著特徵是某事中引人注目或特別明顯的部分。"},{"en":"A school play’s dramatic features may include sudden silence, strong lighting and emotional dialogue.","zh":"學校戲劇的顯著特徵可能包括突然沉默、強烈燈光和情感對白。"},{"en":"If hot nights were a dramatic feature, they made the heatwave especially memorable and dangerous.","zh":"如果炎熱夜晚是顯著特徵，它們就令熱浪尤其難忘和危險。"},{"en":"The phrase points to the most impressive or alarming characteristics.","zh":"這個短語指出最令人印象深刻或令人警覺的特性。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":7},{"front":"hot nights","meaning":"炎熱夜晚","examples":[{"en":"Hot nights were one of the summer’s most dramatic features.","zh":"炎熱夜晚是那個夏天最顯著特徵之一。"},{"en":"Hot nights are nights when temperatures remain unusually high after sunset.","zh":"炎熱夜晚是日落後氣溫仍異常高的夜晚。"},{"en":"During hot nights, people may sleep badly because rooms do not cool down.","zh":"在炎熱夜晚，人們可能睡不好，因為房間無法降溫。"},{"en":"If nights stay hot during a heatwave, older people may face greater health risks.","zh":"如果熱浪期間夜晚仍然炎熱，長者可能面對更大健康風險。"},{"en":"The phrase highlights heat that continues after daytime.","zh":"這個短語強調白天以後仍持續的高溫。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":7},{"front":"first half of August","meaning":"八月上半月","examples":[{"en":"The hot nights were especially severe in the first half of August.","zh":"炎熱夜晚在八月上半月尤其嚴重。"},{"en":"The first half of August means the period from the beginning of August to around the middle of the month.","zh":"八月上半月指八月初到大約月中這段時期。"},{"en":"A school may collect forms in the first half of August before the new term starts.","zh":"學校可能在八月上半月收集表格，準備新學期開始。"},{"en":"If heat is severe in the first half of a month, several nights in a row may be affected.","zh":"如果高溫在一個月上半月嚴重，可能連續幾晚受影響。"},{"en":"The phrase gives a specific part of a month.","zh":"這個短語給出月份中的特定部分。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":8},{"front":"drop below","meaning":"跌穿；低於","examples":[{"en":"The temperature never dropped below 23°C in Paris for several nights.","zh":"巴黎連續幾晚氣溫從未低於23°C。"},{"en":"To drop below a level means to fall lower than that point.","zh":"“Drop below” 某水平指跌到低於該點。"},{"en":"If a student’s attendance drops below 80%, the school may contact their parents.","zh":"如果學生出席率跌穿80%，學校可能聯絡家長。"},{"en":"When night temperatures do not drop below a safe level, the body cannot cool properly.","zh":"當夜間氣溫沒有降至安全水平以下，身體就無法正常降溫。"},{"en":"The phrase is often used with numbers and limits.","zh":"這個短語常與數字和界限一起使用。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":8},{"front":"warmest-ever night","meaning":"有史以來最暖的夜晚","examples":[{"en":"Paris recorded its warmest-ever night on 11–12 August.","zh":"巴黎在8月11至12日錄得有史以來最暖的夜晚。"},{"en":"A warmest-ever night is the hottest night ever recorded in a place.","zh":"有史以來最暖的夜晚，是某地有記錄以來最熱的夜晚。"},{"en":"A city may warn residents if it expects a warmest-ever night because sleep and health can be affected.","zh":"如果城市預料出現有史以來最暖的夜晚，可能提醒居民，因為睡眠和健康會受影響。"},{"en":"If the night temperature breaks records, the heatwave continues even after sunset.","zh":"如果夜間氣溫破紀錄，熱浪就在日落後仍持續。"},{"en":"The phrase marks an extreme nighttime temperature record.","zh":"這個短語標示極端夜間氣溫紀錄。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":8},{"front":"the mercury","meaning":"溫度計水銀柱；氣溫","examples":[{"en":"The mercury did not drop below 25.5°C that night.","zh":"那晚氣溫沒有跌穿25.5°C。"},{"en":"The mercury is a traditional way to refer to the temperature shown on a thermometer.","zh":"“The mercury” 是傳統上指溫度計所顯示氣溫的說法。"},{"en":"People may say the mercury is rising when the weather is getting hotter.","zh":"當天氣變熱，人們可能說水銀柱正在上升。"},{"en":"If the mercury stays high at night, people may struggle to sleep.","zh":"如果夜晚氣溫仍高，人們可能難以入睡。"},{"en":"The phrase is a weather expression meaning temperature.","zh":"這個短語是天氣用語，意思是氣溫。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":8},{"front":"lowest figure","meaning":"最低數值","examples":[{"en":"Germany recorded a lowest figure of 27.6°C at night.","zh":"德國錄得夜間最低數值27.6°C。"},{"en":"A lowest figure is the smallest number recorded in a set of measurements.","zh":"最低數值是一組量度中記錄到的最小數字。"},{"en":"In a week of hot nights, the lowest figure may still be too high for comfort.","zh":"在一星期炎熱夜晚中，最低數值仍可能高得令人不舒服。"},{"en":"If the lowest night temperature is 27.6°C, the night never became cool.","zh":"如果夜間最低氣溫是27.6°C，那晚就從未變涼。"},{"en":"The phrase points to the minimum value.","zh":"這個短語指最低值。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":8},{"front":"record-breaking nighttime temperatures","meaning":"破紀錄夜間氣溫","examples":[{"en":"Several countries recorded record-breaking nighttime temperatures.","zh":"幾個國家錄得破紀錄夜間氣溫。"},{"en":"Record-breaking nighttime temperatures are night temperatures higher than any previously measured.","zh":"破紀錄夜間氣溫是高於以往任何量度值的夜間氣溫。"},{"en":"Hospitals may prepare for extra patients during record-breaking nighttime temperatures.","zh":"醫院可能在破紀錄夜間氣溫期間準備接收額外病人。"},{"en":"If night temperatures break records, the heat can become more dangerous because people cannot recover overnight.","zh":"如果夜間氣溫破紀錄，高溫可能更危險，因為人們不能在夜間恢復。"},{"en":"The phrase describes extreme heat during the night.","zh":"這個短語描述夜晚的極端高溫。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":8},{"front":"excess deaths","meaning":"額外死亡人數","examples":[{"en":"France recorded 15,000 excess deaths during August.","zh":"法國在八月錄得15,000宗額外死亡。"},{"en":"Excess deaths are deaths above the number normally expected for a period.","zh":"額外死亡人數是某時期高於正常預期數目的死亡。"},{"en":"Health officials compare this year’s deaths with previous years to calculate excess deaths.","zh":"衛生官員把今年死亡數字與以往年份比較，以計算額外死亡人數。"},{"en":"If excess deaths rise during a heatwave, the heat may have caused serious public-health harm.","zh":"如果額外死亡人數在熱浪期間上升，高溫可能造成嚴重公共健康傷害。"},{"en":"The phrase measures unusual mortality beyond the normal level.","zh":"這個短語量度超出正常水平的異常死亡率。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":8},{"front":"compared with previous years","meaning":"與以往年份相比","examples":[{"en":"The deaths were counted compared with previous years.","zh":"這些死亡數字是與以往年份相比計算出來的。"},{"en":"Compared with previous years means measured against data from earlier years.","zh":"“Compared with previous years” 指與較早年份的數據作比較。"},{"en":"A school may judge this year’s exam results compared with previous years.","zh":"學校可能把今年考試結果與以往年份相比來判斷。"},{"en":"If deaths are higher compared with previous years, something unusual may have happened.","zh":"如果死亡數字與以往年份相比較高，可能發生了不尋常事情。"},{"en":"The phrase uses past records as the standard for comparison.","zh":"這個短語使用過去記錄作比較標準。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":8},{"front":"be related to","meaning":"與……有關","examples":[{"en":"The excess deaths have been related to high night-time temperatures.","zh":"額外死亡人數被認為與高夜間氣溫有關。"},{"en":"To be related to something means to be connected with it in cause, effect or association.","zh":"“Be related to” 某事指在原因、結果或關聯上與它有連繫。"},{"en":"A student’s headache may be related to dehydration after outdoor sports.","zh":"學生頭痛可能與戶外運動後脫水有關。"},{"en":"If deaths are related to night temperatures, heat at night may be an important risk factor.","zh":"如果死亡與夜間氣溫有關，夜間高溫可能是重要風險因素。"},{"en":"The phrase shows a connection without always proving direct cause.","zh":"這個短語顯示關聯，但不一定完全證明直接原因。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":8},{"front":"night-time temperatures","meaning":"夜間氣溫","examples":[{"en":"High night-time temperatures were linked to excess deaths.","zh":"高夜間氣溫與額外死亡人數有關。"},{"en":"Night-time temperatures are temperatures measured during the night.","zh":"夜間氣溫是在夜晚量度的溫度。"},{"en":"Weather reports may show night-time temperatures so people know whether rooms will cool down.","zh":"天氣報告可能顯示夜間氣溫，讓人知道房間會否降溫。"},{"en":"If night-time temperatures remain high, vulnerable people may suffer because the body gets no rest from heat.","zh":"如果夜間氣溫維持高企，弱勢人士可能受苦，因為身體無法從高溫中休息。"},{"en":"The phrase focuses on heat after sunset.","zh":"這個短語強調日落後的高溫。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":8},{"front":"gradually increased","meaning":"逐漸增加","examples":[{"en":"The number of deaths gradually increased during the first 12 days of August.","zh":"死亡人數在八月首12天逐漸增加。"},{"en":"Gradually increased means rose slowly or step by step over time.","zh":"“Gradually increased” 指隨時間慢慢或一步步上升。"},{"en":"A student’s confidence gradually increased after several successful speaking practices.","zh":"經過幾次成功口語練習後，學生信心逐漸增加。"},{"en":"If deaths gradually increase during a heatwave, the health impact may be building day by day.","zh":"如果死亡人數在熱浪期間逐漸增加，健康影響可能每日累積。"},{"en":"The phrase describes a slow upward change.","zh":"這個短語描述緩慢上升變化。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":8},{"front":"peak at","meaning":"達到高峰","examples":[{"en":"The number of deaths peaked at about 2,000 per day.","zh":"死亡人數達到每天約2,000人的高峰。"},{"en":"To peak at a number means to reach the highest level at that number.","zh":"“Peak at” 某數字指在該數字達到最高水平。"},{"en":"Bus use may peak at 8 a.m. when most students and workers travel.","zh":"巴士使用量可能在早上8時達到高峰，因為大多數學生和工人出行。"},{"en":"If deaths peak at 2,000 per day, that is the worst point in the period measured.","zh":"如果死亡人數達到每天2,000人高峰，那就是量度時期中的最嚴重點。"},{"en":"The phrase identifies the highest point of a trend.","zh":"這個短語指出趨勢的最高點。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":9},{"front":"fall off dramatically","meaning":"急劇下降","examples":[{"en":"The number of deaths fell off dramatically after 14 August.","zh":"8月14日後，死亡人數急劇下降。"},{"en":"To fall off dramatically means to decrease suddenly and by a large amount.","zh":"“Fall off dramatically” 指突然並大幅下降。"},{"en":"Restaurant bookings may fall off dramatically after a food-safety warning.","zh":"食物安全警告後，餐廳訂座可能急劇下降。"},{"en":"If deaths fall off dramatically after temperatures drop, heat may have been a major factor.","zh":"如果氣溫下降後死亡人數急劇下降，高溫可能曾是主要因素。"},{"en":"The phrase describes a sharp decline.","zh":"這個短語描述急速下跌。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":9},{"front":"minimum temperatures","meaning":"最低氣溫","examples":[{"en":"The deaths fell after minimum temperatures dropped.","zh":"最低氣溫下降後，死亡人數也下降。"},{"en":"Minimum temperatures are the lowest temperatures recorded during a period, often at night.","zh":"最低氣溫是某時期內記錄到的最低溫度，通常出現在夜間。"},{"en":"Farmers check minimum temperatures to know whether frost may damage crops.","zh":"農民查看最低氣溫，以知道霜凍會否損害農作物。"},{"en":"If minimum temperatures stay high, nights do not provide relief from heat.","zh":"如果最低氣溫維持高企，夜晚就不能提供酷熱緩解。"},{"en":"The phrase focuses on the lowest point, not the daytime maximum.","zh":"這個短語強調最低點，而不是白天最高溫。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":9},{"front":"the elderly","meaning":"長者","examples":[{"en":"The elderly were most affected by the heatwave.","zh":"長者受熱浪影響最大。"},{"en":"The elderly means older people, especially those in later life.","zh":"長者指年紀較大的人，尤其是晚年人士。"},{"en":"During extreme heat, the elderly may need extra water, shade and regular check-ins.","zh":"在極端高溫期間，長者可能需要額外飲水、遮蔭和定期探訪。"},{"en":"If the elderly live alone, heatwaves can be especially dangerous because help may arrive late.","zh":"如果長者獨居，熱浪可能尤其危險，因為幫助可能來得太遲。"},{"en":"The phrase refers to older members of the community.","zh":"這個短語指社區中的年長成員。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":9},{"front":"mortality rate","meaning":"死亡率","examples":[{"en":"The mortality rate increased sharply among older people.","zh":"長者的死亡率急劇上升。"},{"en":"Mortality rate is the rate at which people die in a particular group or period.","zh":"死亡率是某個群體或時期中人們死亡的比率。"},{"en":"Hospitals track mortality rates to understand whether treatments are improving.","zh":"醫院追蹤死亡率，以了解治療是否改善。"},{"en":"If the mortality rate rises during a heatwave, the heat has become a serious health threat.","zh":"如果死亡率在熱浪期間上升，高溫就成為嚴重健康威脅。"},{"en":"The phrase is a statistical way to discuss deaths.","zh":"這個短語是討論死亡的統計方式。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":9},{"front":"those aged 75–94","meaning":"75至94歲人士","examples":[{"en":"The mortality rate rose among those aged 75–94.","zh":"75至94歲人士的死亡率上升。"},{"en":"Those aged 75–94 means people whose ages are between 75 and 94.","zh":"“Those aged 75–94” 指年齡介乎75至94歲的人。"},{"en":"Health services may offer extra support to those aged 75–94 during extreme weather.","zh":"在極端天氣期間，醫療服務可能向75至94歲人士提供額外支援。"},{"en":"If a risk rises among this age group, age is an important factor in vulnerability.","zh":"如果這個年齡組別的風險上升，年齡就是脆弱性的重要因素。"},{"en":"The phrase identifies a specific age range.","zh":"這個短語指出特定年齡範圍。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":9},{"front":"the year as a whole","meaning":"全年整體","examples":[{"en":"For Britain, the year as a whole was likely to be the warmest recorded.","zh":"對英國而言，全年整體很可能成為有記錄以來最暖。"},{"en":"The year as a whole means the full year considered together, not only one season or month.","zh":"全年整體指把整個年份一起考慮，而不是只看一季或一個月。"},{"en":"A student may have one weak test but still perform well for the year as a whole.","zh":"學生可能有一次測驗較弱，但全年整體仍表現良好。"},{"en":"If the year as a whole is warm, cooler months did not cancel out the overall heat.","zh":"如果全年整體偏暖，較涼月份也沒有抵消整體高溫。"},{"en":"The phrase focuses on the complete annual picture.","zh":"這個短語強調完整年度圖像。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":9},{"front":"despite","meaning":"儘管","examples":[{"en":"Despite the high temperature record, Britain’s summer was not the hottest.","zh":"儘管創下高溫紀錄，英國的夏天並不是最熱的。"},{"en":"Despite means although something is true, another contrasting fact is also true.","zh":"“Despite” 指雖然某事為真，但另一個相反事實也成立。"},{"en":"Despite feeling nervous, the student gave a clear presentation.","zh":"儘管感到緊張，學生仍作出清晰匯報。"},{"en":"If Britain set a high temperature record but did not have its hottest summer overall, the contrast matters.","zh":"如果英國創下高溫紀錄，但整體夏天不是最熱，這個對比就重要。"},{"en":"The word introduces a surprising contrast.","zh":"這個詞引出令人意外的對比。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":9},{"front":"high temperature record","meaning":"高溫紀錄","examples":[{"en":"Britain set a high temperature record on 10 August.","zh":"英國在8月10日創下高溫紀錄。"},{"en":"A high temperature record is the highest temperature measured for a place or period.","zh":"高溫紀錄是某地或某時期量度到的最高氣溫。"},{"en":"A school may cancel outdoor sports if the city sets a high temperature record.","zh":"如果城市創下高溫紀錄，學校可能取消戶外運動。"},{"en":"If a high temperature record is broken, people may need new safety measures.","zh":"如果高溫紀錄被打破，人們可能需要新的安全措施。"},{"en":"The phrase refers to an extreme heat measurement.","zh":"這個短語指極端高溫量度。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":9},{"front":"be defined as","meaning":"被定義為","examples":[{"en":"Summer was defined as the June, July and August period.","zh":"夏季被定義為六月、七月和八月這段時期。"},{"en":"To be defined as something means to be described or fixed in meaning in a particular way.","zh":"“Be defined as” 某物指以特定方式描述或固定其意思。"},{"en":"In a school policy, lateness may be defined as arriving more than five minutes after the bell.","zh":"在校政中，遲到可能被定義為鐘聲響後超過五分鐘才到達。"},{"en":"If summer is defined as three specific months, the calculation excludes May and September.","zh":"如果夏季被定義為三個特定月份，計算就不包括五月和九月。"},{"en":"The phrase sets a clear meaning or boundary.","zh":"這個短語設定清楚意思或界線。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":9},{"front":"come behind","meaning":"排在……之後","examples":[{"en":"The summer of 2003 still came behind 1976 and 1995 in Britain.","zh":"2003年夏天在英國仍排在1976年和1995年之後。"},{"en":"To come behind something means to rank lower than it or be placed after it.","zh":"“Come behind” 某事指排名低於它或排在它後面。"},{"en":"In the race, May came behind Tom but ahead of three other runners.","zh":"在比賽中，May 排在 Tom 之後，但領先另外三名跑手。"},{"en":"If 2003 came behind 1976 and 1995, those two summers were hotter by the chosen measure.","zh":"如果2003年排在1976年和1995年之後，按所選量度標準，那兩個夏天更熱。"},{"en":"The phrase is used when comparing rankings.","zh":"這個短語用於比較排名。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":9},{"front":"intense heat","meaning":"酷熱","examples":[{"en":"1976 and 1995 had longer periods of intense heat.","zh":"1976年和1995年有更長時間的酷熱。"},{"en":"Intense heat is very strong heat that can feel uncomfortable or dangerous.","zh":"酷熱是非常強烈、可能令人不適或危險的高溫。"},{"en":"Outdoor workers need rest breaks and water during intense heat.","zh":"戶外工人在酷熱期間需要休息和飲水。"},{"en":"If intense heat lasts for many days, health risks and energy demand can rise.","zh":"如果酷熱持續多日，健康風險和能源需求都可能上升。"},{"en":"The phrase describes heat that is stronger than ordinary warmth.","zh":"這個短語描述比普通溫暖強得多的高溫。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":10},{"front":"at the moment","meaning":"目前","examples":[{"en":"At the moment, the year is on course to be very hot globally.","zh":"目前，這一年很可能在全球範圍內非常炎熱。"},{"en":"At the moment means now, at the present time.","zh":"“At the moment” 指現在，在目前這個時間。"},{"en":"At the moment, the library is closed because workers are repairing the roof.","zh":"目前，圖書館因工人維修屋頂而關閉。"},{"en":"If data at the moment shows a hot year, later records may still change the final ranking.","zh":"如果目前數據顯示某年炎熱，之後的記錄仍可能改變最終排名。"},{"en":"The phrase gives a current but possibly temporary situation.","zh":"這個短語給出當前但可能暫時的情況。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":10},{"front":"be on course to be","meaning":"很可能成為","examples":[{"en":"The year was on course to be the third hottest ever.","zh":"這一年很可能成為有史以來第三熱的年份。"},{"en":"To be on course to be something means to be likely to reach that result if the current trend continues.","zh":"“Be on course to be” 某事指如果目前趨勢持續，就很可能達到該結果。"},{"en":"A student is on course to pass if their practice scores keep improving.","zh":"如果學生練習分數持續改善，他就很可能合格。"},{"en":"If global temperatures remain high, a year may be on course to become one of the hottest recorded.","zh":"如果全球氣溫維持高企，某年可能很可能成為有記錄以來最熱年份之一。"},{"en":"The phrase predicts an outcome based on current progress.","zh":"這個短語根據目前進展預測結果。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":10},{"front":"global temperature record","meaning":"全球氣溫記錄","examples":[{"en":"The global temperature record goes back to 1856.","zh":"全球氣溫記錄追溯到1856年。"},{"en":"The global temperature record is the collected record of temperatures measured around the world over time.","zh":"全球氣溫記錄是隨時間收集的世界各地氣溫量度記錄。"},{"en":"Scientists use the global temperature record to compare modern years with earlier periods.","zh":"科學家使用全球氣溫記錄，把現代年份與較早時期比較。"},{"en":"If the global temperature record shows many recent hot years, it may suggest a warming trend.","zh":"如果全球氣溫記錄顯示近年有許多炎熱年份，可能表示暖化趨勢。"},{"en":"The phrase refers to worldwide climate data.","zh":"這個短語指全球氣候數據。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":10},{"front":"go back to","meaning":"追溯到","examples":[{"en":"The global temperature record goes back to 1856.","zh":"全球氣溫記錄追溯到1856年。"},{"en":"To go back to a date means to extend into the past as far as that date.","zh":"“Go back to” 某日期指向過去延伸至該日期。"},{"en":"The school’s old photographs go back to the 1920s.","zh":"學校舊照片可追溯到1920年代。"},{"en":"If records go back many years, they allow stronger historical comparison.","zh":"如果記錄追溯多年，它們就能支持更有力的歷史比較。"},{"en":"The phrase describes how far into the past evidence reaches.","zh":"這個短語描述證據延伸到過去多遠。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":10},{"front":"records are collated","meaning":"記錄被整理","examples":[{"en":"When all records are collated, the ranking may change.","zh":"當所有記錄被整理後，排名可能改變。"},{"en":"When records are collated, they are collected, organised and compared together.","zh":"當記錄被整理，它們就是被收集、組織並一起比較。"},{"en":"A teacher may collate homework marks from several classes before writing a report.","zh":"老師可能先整理幾個班的功課分數，再撰寫報告。"},{"en":"If weather records are collated from many stations, the final result may become more accurate.","zh":"如果從多個氣象站整理天氣記錄，最終結果可能更準確。"},{"en":"The phrase describes bringing separate data together.","zh":"這個短語描述把分散數據集中起來。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":10},{"front":"move into second place","meaning":"升至第二位","examples":[{"en":"The year might move into second place.","zh":"這一年可能升至第二位。"},{"en":"To move into second place means to rise or change position to become ranked second.","zh":"“Move into second place” 指上升或改變位置，成為排名第二。"},{"en":"A runner may move into second place near the end of a race.","zh":"跑手可能在比賽尾段升至第二位。"},{"en":"If new temperature data is added, a year may move higher in the ranking.","zh":"如果加入新氣溫數據，某年份可能在排名中上升。"},{"en":"The phrase describes a change in rank.","zh":"這個短語描述排名變化。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":10},{"front":"the ten hottest years","meaning":"十個最熱年份","examples":[{"en":"The ten hottest years in the record have all occurred since 1990.","zh":"記錄中十個最熱年份全都發生在1990年之後。"},{"en":"The ten hottest years are the ten years with the highest recorded temperatures.","zh":"十個最熱年份是記錄中氣溫最高的十個年份。"},{"en":"A climate chart may list the ten hottest years to show long-term warming.","zh":"氣候圖表可能列出十個最熱年份，以顯示長期暖化。"},{"en":"If all ten hottest years are recent, the pattern may suggest a changing climate.","zh":"如果十個最熱年份全都很近期，該模式可能表示氣候正在改變。"},{"en":"The phrase identifies the top-ranked hot years in a record.","zh":"這個短語指出記錄中排名最高的炎熱年份。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":10},{"front":"in no doubt about","meaning":"對……毫不懷疑","examples":[{"en":"Professor Jones is in no doubt about the exceptional nature of the summer.","zh":"Jones 教授對那個夏天的異常性毫不懷疑。"},{"en":"To be in no doubt about something means to be completely certain about it.","zh":"“Be in no doubt about” 某事指對它完全肯定。"},{"en":"A teacher may be in no doubt about a student’s effort after seeing daily practice.","zh":"老師看見每日練習後，可能對學生的努力毫不懷疑。"},{"en":"If a scientist is in no doubt, the evidence has convinced them strongly.","zh":"如果科學家毫不懷疑，就是證據已強烈說服他。"},{"en":"The phrase expresses firm certainty.","zh":"這個短語表達堅定肯定。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":10},{"front":"astonishing nature","meaning":"驚人的性質","examples":[{"en":"Professor Jones emphasised the astonishing nature of the 2003 summer.","zh":"Jones 教授強調2003年夏天驚人的性質。"},{"en":"Astonishing nature means the surprising and extraordinary quality of something.","zh":"驚人的性質指某事令人驚訝和非凡的特質。"},{"en":"The astonishing nature of the student’s recovery impressed the whole medical team.","zh":"學生康復的驚人性質令整個醫療團隊印象深刻。"},{"en":"If a heatwave is astonishing in nature, it is not just hot but shockingly unusual.","zh":"如果熱浪性質驚人，它就不只是炎熱，而是驚人地不尋常。"},{"en":"The phrase focuses on how remarkable something is.","zh":"這個短語強調某事有多非凡。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":10},{"front":"out of all proportion to","meaning":"與……完全不成比例","examples":[{"en":"The temperatures were out of all proportion to the previous record.","zh":"這些氣溫與以往紀錄完全不成比例。"},{"en":"Out of all proportion to something means far greater or more extreme than it in an unreasonable or surprising way.","zh":"“Out of all proportion to” 某事指比它大得多或極端得多，程度令人不合理或驚訝。"},{"en":"The punishment was out of all proportion to the student’s small mistake.","zh":"該懲罰與學生的小錯誤完全不成比例。"},{"en":"If new temperatures are out of all proportion to the old record, the increase is shockingly large.","zh":"如果新氣溫與舊紀錄完全不成比例，增幅就是驚人地巨大。"},{"en":"The phrase stresses an extreme mismatch in scale.","zh":"這個短語強調規模上的極端不匹配。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":10},{"front":"previous record","meaning":"以往紀錄","examples":[{"en":"The 2003 temperatures far exceeded the previous record.","zh":"2003年的氣溫遠遠超過以往紀錄。"},{"en":"A previous record is the highest or best measurement before a new one is made.","zh":"以往紀錄是在新紀錄出現之前的最高或最佳量度。"},{"en":"A runner breaks the previous record when they finish faster than anyone before.","zh":"跑手比以前任何人更快完成時，就打破以往紀錄。"},{"en":"If temperatures exceed the previous record by a large amount, the new event is exceptional.","zh":"如果氣溫大幅超過以往紀錄，新事件就是異常的。"},{"en":"The phrase compares a new result with the old top result.","zh":"這個短語把新結果與舊最高結果比較。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":11},{"front":"way beyond that","meaning":"遠超於此","examples":[{"en":"The summer was probably the warmest for way beyond 500 years.","zh":"那個夏天可能是遠超500年以來最暖的。"},{"en":"Way beyond that means far more or much further than that point or amount.","zh":"“Way beyond that” 指遠多於或遠超過該點或數量。"},{"en":"The repair cost was not just high; it was way beyond the family’s budget.","zh":"維修費不只是高，而是遠超該家庭預算。"},{"en":"If evidence suggests warmth beyond 500 years, the event may be exceptional on a very long scale.","zh":"如果證據顯示暖度遠超500年範圍，事件可能在非常長時間尺度上異常。"},{"en":"The phrase strongly extends a comparison.","zh":"這個短語強烈延伸比較。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":11},{"front":"enormously exceptional","meaning":"極其異常","examples":[{"en":"The 2003 summer was enormously exceptional.","zh":"2003年夏天極其異常。"},{"en":"Enormously exceptional means extremely unusual to a very great degree.","zh":"“Enormously exceptional” 指在非常大程度上極不尋常。"},{"en":"A student who learns a new language fluently in six months would be enormously exceptional.","zh":"如果學生六個月內流利掌握新語言，就是極其異常。"},{"en":"If a climate event is enormously exceptional, normal explanations may not be enough.","zh":"如果氣候事件極其異常，普通解釋可能不足。"},{"en":"The phrase strongly emphasises rarity and scale.","zh":"這個短語強烈強調罕見程度和規模。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":11},{"front":"colleagues","meaning":"同事","examples":[{"en":"Jones’s colleagues are planning a special study of the heatwave.","zh":"Jones 的同事正計劃對這場熱浪進行專門研究。"},{"en":"Colleagues are people who work with someone in the same organisation or field.","zh":"同事是在同一組織或領域中與某人一起工作的人。"},{"en":"A teacher may discuss lesson plans with colleagues before the new term begins.","zh":"老師可能在新學期開始前與同事討論教案。"},{"en":"If colleagues study the same problem together, they can share data and expertise.","zh":"如果同事一起研究同一問題，他們可以分享數據和專業知識。"},{"en":"The word refers to fellow workers or professional partners.","zh":"這個詞指一起工作的同僚或專業伙伴。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":11},{"front":"Tyndall Centre for Climate Change Research","meaning":"廷德爾氣候變化研究中心","examples":[{"en":"The Tyndall Centre is planning a special study of the 2003 heatwave.","zh":"廷德爾中心正計劃對2003年熱浪進行專門研究。"},{"en":"The Tyndall Centre for Climate Change Research is a research centre focused on climate change.","zh":"廷德爾氣候變化研究中心是專注於氣候變化的研究中心。"},{"en":"A climate research centre may study heatwaves, floods and future adaptation plans.","zh":"氣候研究中心可能研究熱浪、水災和未來適應計劃。"},{"en":"If such a centre studies a heatwave, it may examine both scientific data and social impacts.","zh":"如果這類中心研究熱浪，它可能同時檢視科學數據和社會影響。"},{"en":"The phrase names a specialist research institution.","zh":"這個短語指一間專門研究機構。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":11},{"front":"plan a special study","meaning":"計劃進行專門研究","examples":[{"en":"Researchers are planning a special study of the heatwave.","zh":"研究人員正計劃對熱浪進行專門研究。"},{"en":"To plan a special study means to organise detailed research into a particular issue.","zh":"“Plan a special study” 指組織針對某特定議題的詳細研究。"},{"en":"A school may plan a special study of why students are absent more often after exams.","zh":"學校可能計劃進行專門研究，了解為何學生考試後缺席增加。"},{"en":"If an event is unusual, researchers may plan a special study to understand its causes and effects.","zh":"如果事件不尋常，研究人員可能計劃專門研究，以理解其原因和影響。"},{"en":"The phrase describes preparing focused investigation.","zh":"這個短語描述準備集中調查。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":11},{"front":"be experienced before","meaning":"以前經歷過","examples":[{"en":"The summer had not been experienced before.","zh":"這樣的夏天以前未曾經歷過。"},{"en":"To be experienced before means to have happened or been lived through in the past.","zh":"“Be experienced before” 指過去曾發生或曾被人經歷。"},{"en":"A school may face a problem that has never been experienced before, such as a sudden long closure.","zh":"學校可能面對以前未經歷過的問題，例如突然長期停課。"},{"en":"If a heatwave has not been experienced before, old plans may not be enough.","zh":"如果熱浪以前未曾經歷過，舊有計劃可能不足。"},{"en":"The phrase points to lack of previous experience.","zh":"這個短語指缺乏過往經驗。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":11},{"front":"in terms of","meaning":"就……而言","examples":[{"en":"The summer was unusual in terms of both temperature extremes and impacts.","zh":"這個夏天就極端氣溫和影響而言都不尋常。"},{"en":"In terms of means when considered from a particular aspect.","zh":"“In terms of” 指從某個特定方面考慮。"},{"en":"In terms of time, the train is faster than the bus.","zh":"就時間而言，火車比巴士快。"},{"en":"If a heatwave is unusual in terms of impact, its effects on people and services were severe.","zh":"如果熱浪就影響而言不尋常，它對人和服務的影響就很嚴重。"},{"en":"The phrase helps specify the angle of comparison.","zh":"這個短語幫助指定比較角度。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":11},{"front":"temperature extremes","meaning":"極端氣溫","examples":[{"en":"The heatwave reached unusual temperature extremes.","zh":"這場熱浪達到不尋常的極端氣溫。"},{"en":"Temperature extremes are very high or very low temperatures far from normal conditions.","zh":"極端氣溫是遠離正常情況的非常高或非常低溫度。"},{"en":"Outdoor sports may be cancelled during temperature extremes to protect students.","zh":"在極端氣溫期間，戶外運動可能被取消，以保護學生。"},{"en":"If temperature extremes become more common, cities may need better emergency planning.","zh":"如果極端氣溫變得更常見，城市可能需要更好的應急規劃。"},{"en":"The phrase refers to the outer limits of hot or cold weather.","zh":"這個短語指炎熱或寒冷天氣的外圍極限。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":11},{"front":"range and diversity of","meaning":"……的範圍和多樣性","examples":[{"en":"The heatwave produced a wide range and diversity of impacts.","zh":"這場熱浪造成廣泛而多樣的影響。"},{"en":"Range and diversity of something means the variety and spread of different types it includes.","zh":"某事的範圍和多樣性，指它包含的不同類型的廣度和變化。"},{"en":"A school library needs a range and diversity of books so different students can find something useful.","zh":"學校圖書館需要書籍的範圍和多樣性，使不同學生都能找到有用內容。"},{"en":"If a disaster has a wide range of impacts, it affects health, transport, farming and business.","zh":"如果災害有廣泛影響，它會影響健康、交通、農業和商業。"},{"en":"The phrase stresses many different kinds, not just one effect.","zh":"這個短語強調許多不同種類，而不只是一種影響。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":11},{"front":"impacts of extreme heat","meaning":"極端高溫的影響","examples":[{"en":"The study will examine the impacts of extreme heat.","zh":"研究將檢視極端高溫的影響。"},{"en":"Impacts of extreme heat are the effects very high temperatures have on people, places and systems.","zh":"極端高溫的影響，是非常高氣溫對人、地方和系統造成的後果。"},{"en":"The impacts of extreme heat can include poor sleep, hospital pressure and damage to crops.","zh":"極端高溫的影響可以包括睡眠差、醫院壓力和農作物受損。"},{"en":"If cities understand these impacts, they can prepare cooling centres and health warnings.","zh":"如果城市理解這些影響，就可以準備避暑中心和健康警告。"},{"en":"The phrase focuses on consequences, not just temperature numbers.","zh":"這個短語強調後果，而不只是氣溫數字。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":11},{"front":"leave its mark on","meaning":"對……留下深遠影響","examples":[{"en":"The heatwave will leave its mark on several countries.","zh":"這場熱浪將對幾個國家留下深遠影響。"},{"en":"To leave its mark on something means to have a lasting effect on it.","zh":"“Leave its mark on” 某事指對它產生持久影響。"},{"en":"A strict but kind teacher may leave her mark on students for many years.","zh":"嚴格但仁慈的老師可能多年來對學生留下深遠影響。"},{"en":"If a disaster leaves its mark on a country, policies and memories may change afterward.","zh":"如果災害對國家留下深遠影響，之後政策和記憶可能改變。"},{"en":"The phrase describes lasting influence.","zh":"這個短語描述持久影響。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":12},{"front":"think and plan for","meaning":"思考並規劃","examples":[{"en":"Countries may change how they think and plan for climate change.","zh":"各國可能改變它們如何思考並規劃氣候變化。"},{"en":"To think and plan for something means to understand it and prepare practical responses to it.","zh":"“Think and plan for” 某事指理解它並準備實際應對。"},{"en":"Families think and plan for retirement by saving money and discussing future needs.","zh":"家庭透過儲蓄和討論未來需要來思考並規劃退休。"},{"en":"If governments think and plan for heatwaves, they can reduce deaths and disruption.","zh":"如果政府思考並規劃熱浪，就能減少死亡和混亂。"},{"en":"The phrase combines awareness with preparation.","zh":"這個短語結合意識和準備。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":12},{"front":"climate change in the future","meaning":"未來氣候變化","examples":[{"en":"The heatwave affected planning for climate change in the future.","zh":"這場熱浪影響了未來氣候變化的規劃。"},{"en":"Climate change in the future means the climate changes expected to happen in coming years or decades.","zh":"未來氣候變化指預期在未來數年或數十年發生的氣候改變。"},{"en":"Schools may teach students about climate change in the future so they understand risks ahead.","zh":"學校可能教學生認識未來氣候變化，使他們理解前方風險。"},{"en":"If extreme heat shows future dangers, governments may plan housing and hospitals differently.","zh":"如果極端高溫顯示未來危險，政府可能以不同方式規劃住房和醫院。"},{"en":"The phrase looks forward rather than only describing past weather.","zh":"這個短語向前看，而不只是描述過去天氣。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":12},{"front":"much as","meaning":"正如……一樣","examples":[{"en":"The heatwave may change thinking much as the 2000 floods did.","zh":"這場熱浪可能改變思維，正如2000年洪災所做的一樣。"},{"en":"Much as means in a similar way to how something else happened.","zh":"“Much as” 指以與另一件事相似的方式。"},{"en":"Online learning changed school routines much as email changed office communication.","zh":"網上學習改變學校日常運作，正如電郵改變辦公室溝通一樣。"},{"en":"If one disaster changes policy much as an earlier disaster did, the two events have similar effects.","zh":"如果一場災害像早前災害一樣改變政策，兩件事就有相似影響。"},{"en":"The phrase draws a comparison between two situations.","zh":"這個短語在兩種情況之間作比較。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":12},{"front":"revolutionise the way","meaning":"徹底改變……的方式","examples":[{"en":"The 2000 floods revolutionised the way the Government thought about flooding.","zh":"2000年洪災徹底改變了政府思考水浸的方式。"},{"en":"To revolutionise the way something is done means to change it completely and deeply.","zh":"“Revolutionise the way” 某事被做，指徹底而深刻地改變它。"},{"en":"Smartphones revolutionised the way many people communicate, shop and travel.","zh":"智能手機徹底改變了許多人溝通、購物和出行的方式。"},{"en":"If floods revolutionise policy thinking, governments stop treating them as rare minor events.","zh":"如果洪災徹底改變政策思維，政府就不再把它們視為罕見小事。"},{"en":"The phrase describes a major transformation in method or understanding.","zh":"這個短語描述方法或理解上的重大轉變。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":12},{"front":"flooding","meaning":"水浸；洪災","examples":[{"en":"The 2000 floods changed thinking about flooding in the UK.","zh":"2000年洪災改變了英國對水浸的思考。"},{"en":"Flooding is the covering of normally dry land with water.","zh":"水浸是水覆蓋通常乾燥的土地。"},{"en":"Heavy rain can cause flooding in streets, homes and railway stations.","zh":"大雨可以在街道、住宅和火車站造成水浸。"},{"en":"If flooding becomes more common, cities may need better drains and flood barriers.","zh":"如果洪災變得更常見，城市可能需要更好的排水渠和防洪屏障。"},{"en":"The word describes water overflow that disrupts normal life.","zh":"這個詞描述擾亂正常生活的水泛濫。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":12},{"front":"similar repercussions","meaning":"類似深遠影響","examples":[{"en":"The 2003 heatwave will have similar repercussions across Europe.","zh":"2003年熱浪將在歐洲各地產生類似深遠影響。"},{"en":"Similar repercussions are comparable long-term effects or consequences.","zh":"類似深遠影響是可比較的長期效果或後果。"},{"en":"A school cheating scandal may have similar repercussions in different schools if trust is damaged.","zh":"如果信任受損，學校作弊醜聞可能在不同學校產生類似深遠影響。"},{"en":"If heatwaves and floods both change policy, their repercussions are similar in public planning.","zh":"如果熱浪和洪災都改變政策，它們在公共規劃上的後果就是相似的。"},{"en":"The phrase focuses on later consequences, not the event itself.","zh":"這個短語強調後來後果，而不是事件本身。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":12},{"front":"across Europe","meaning":"遍及歐洲","examples":[{"en":"The heatwave will have repercussions across Europe.","zh":"這場熱浪將在歐洲各地產生深遠影響。"},{"en":"Across Europe means throughout many parts or countries of Europe.","zh":"“Across Europe” 指遍及歐洲許多地區或國家。"},{"en":"A popular song may spread across Europe through radio, streaming and festivals.","zh":"一首流行歌曲可能透過電台、串流和音樂節傳遍歐洲。"},{"en":"If a heatwave affects planning across Europe, many governments face similar lessons.","zh":"如果熱浪影響歐洲各地的規劃，許多政府就面對相似教訓。"},{"en":"The phrase describes wide geographical reach within Europe.","zh":"這個短語描述在歐洲內的廣泛地理覆蓋。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":12},{"front":"do the following statements agree with","meaning":"以下陳述是否與……相符","examples":[{"en":"Students decide whether the statements agree with the writer’s views.","zh":"學生判斷這些陳述是否與作者觀點相符。"},{"en":"Do the following statements agree with means decide whether each statement matches what the writer says or believes.","zh":"“Do the following statements agree with” 指判斷每項陳述是否符合作者所說或相信的內容。"},{"en":"In reading tests, students should compare each statement carefully with the passage.","zh":"在閱讀測驗中，學生應仔細把每項陳述與文章比較。"},{"en":"If one word changes the meaning, the statement may no longer agree with the writer’s view.","zh":"如果一個字改變意思，陳述可能不再與作者觀點相符。"},{"en":"The phrase introduces a YES/NO/NOT GIVEN type of task.","zh":"這個短語引出 YES/NO/NOT GIVEN 類題目。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":12},{"front":"views of the writer","meaning":"作者觀點","examples":[{"en":"The questions ask about the views of the writer.","zh":"題目問作者觀點。"},{"en":"Views of the writer are the opinions, beliefs or attitudes expressed by the author.","zh":"作者觀點是作者表達出的意見、信念或態度。"},{"en":"Students can identify the writer’s views by noticing words such as “clearly,” “surprisingly” or “unfortunately.”","zh":"學生可以透過留意 “clearly”、“surprisingly” 或 “unfortunately” 等詞識別作者觀點。"},{"en":"If a statement matches the writer’s view, it should be supported by the passage.","zh":"如果陳述符合作者觀點，就應得到文章支持。"},{"en":"The phrase focuses on opinion and attitude, not only factual details.","zh":"這個短語強調意見和態度，而不只是事實細節。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":12},{"front":"write YES if","meaning":"如……則寫YES","examples":[{"en":"Students write YES if the statement agrees with the writer’s views.","zh":"如果陳述與作者觀點一致，學生寫 YES。"},{"en":"Write YES if means choose YES only under the condition that follows.","zh":"“Write YES if” 指只有在後面條件成立時才選 YES。"},{"en":"In an exam, write YES if the whole statement matches the writer’s opinion.","zh":"在考試中，如果整項陳述符合作者意見，才寫 YES。"},{"en":"If the passage only gives a fact but not the writer’s view, YES may not be safe.","zh":"如果文章只給事實而沒有作者觀點，YES 未必安全。"},{"en":"The phrase gives a conditional answer instruction.","zh":"這個短語給出條件式作答指示。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":12},{"front":"contradict the views of","meaning":"與……觀點矛盾","examples":[{"en":"Students write NO if the statement contradicts the views of the writer.","zh":"如果陳述與作者觀點矛盾，學生寫 NO。"},{"en":"To contradict the views of someone means to say the opposite of what that person believes or argues.","zh":"“Contradict the views of” 某人指說出與該人相信或主張相反的意思。"},{"en":"A statement contradicts the teacher’s view if she says practice helps but the statement says practice is useless.","zh":"如果老師說練習有幫助，但陳述說練習無用，該陳述就與老師觀點矛盾。"},{"en":"If an answer contradicts the writer’s view, students should choose NO rather than NOT GIVEN.","zh":"如果答案與作者觀點矛盾，學生應選 NO，而不是 NOT GIVEN。"},{"en":"The phrase helps identify direct opposition.","zh":"這個短語幫助識別直接相反。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":13},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"Write NOT GIVEN if it is impossible to say what the writer thinks.","zh":"如果無法判斷作者想法，則寫 NOT GIVEN。"},{"en":"Impossible to say means there is not enough information to know the answer.","zh":"“Impossible to say” 指沒有足夠資料知道答案。"},{"en":"If a passage mentions a teacher but not her age, it is impossible to say how old she is.","zh":"如果文章提到一位老師但沒有提及年齡，就無法判斷她多大。"},{"en":"When the writer gives no opinion, students should not guess from outside knowledge.","zh":"當作者沒有給出意見，學生不應根據外部知識猜測。"},{"en":"The phrase signals that the text does not support a clear answer.","zh":"這個短語表示文本不支持清楚答案。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":13},{"front":"long-term average","meaning":"長期平均值","examples":[{"en":"The statement refers to the long-term average temperature.","zh":"該陳述提到長期平均氣溫。"},{"en":"A long-term average is the usual level calculated from data over many years.","zh":"長期平均值是由多年數據計算出的通常水平。"},{"en":"A shop may compare this month’s sales with the long-term average to see if business is unusual.","zh":"商店可能把本月銷售額與長期平均值比較，看生意是否異常。"},{"en":"If temperature rises far above the long-term average, the change is more meaningful than one hot day.","zh":"如果氣溫遠高於長期平均值，這變化就比單一天炎熱更有意義。"},{"en":"The phrase provides a stable point of comparison.","zh":"這個短語提供穩定比較點。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":13},{"front":"temperature variation","meaning":"氣溫變化","examples":[{"en":"The question asks whether the 2003 temperature variation was normal.","zh":"題目問2003年的氣溫變化是否正常。"},{"en":"Temperature variation means change or difference in temperature from the usual level.","zh":"氣溫變化指氣溫相對於通常水平的改變或差異。"},{"en":"A classroom may have temperature variation if one side is sunny and the other is near air conditioning.","zh":"如果課室一邊曬太陽，另一邊靠近冷氣，就可能有氣溫變化。"},{"en":"If temperature variation is extreme, people may question whether normal weather patterns can explain it.","zh":"如果氣溫變化極端，人們可能質疑正常天氣模式能否解釋它。"},{"en":"The phrase describes difference in temperature.","zh":"這個短語描述氣溫差異。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":13},{"front":"within the normal range","meaning":"在正常範圍內","examples":[{"en":"Jones did not believe the 2003 variation was within the normal range.","zh":"Jones 不相信2003年的變化在正常範圍內。"},{"en":"Within the normal range means inside the limits usually expected.","zh":"“Within the normal range” 指在通常預期的界限之內。"},{"en":"A doctor may say a blood test result is within the normal range.","zh":"醫生可能說血液檢查結果在正常範圍內。"},{"en":"If a temperature change is not within the normal range, scientists may treat it as unusual.","zh":"如果氣溫變化不在正常範圍內，科學家可能視它為異常。"},{"en":"The phrase compares a value with accepted limits.","zh":"這個短語把數值與可接受界限比較。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":13},{"front":"be measured twice a day","meaning":"每日量度兩次","examples":[{"en":"The question asks whether temperatures are measured twice a day.","zh":"題目問氣溫是否每日量度兩次。"},{"en":"To be measured twice a day means to be recorded two times each day.","zh":"“Be measured twice a day” 指每天被記錄兩次。"},{"en":"A patient’s blood pressure may be measured twice a day in hospital.","zh":"病人在醫院的血壓可能每日量度兩次。"},{"en":"If temperatures are measured twice a day, the data may show daily highs and lows more clearly.","zh":"如果氣溫每日量度兩次，數據可能更清楚顯示每日高低。"},{"en":"The phrase describes frequency of measurement.","zh":"這個短語描述量度頻率。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":13},{"front":"major cities","meaning":"主要城市","examples":[{"en":"The statement refers to temperature measurement in major cities.","zh":"該陳述提到主要城市中的氣溫量度。"},{"en":"Major cities are large and important urban areas with many people and services.","zh":"主要城市是人口眾多、服務重要的大型都市地區。"},{"en":"Major cities often have airports, hospitals, universities and transport networks.","zh":"主要城市通常有機場、醫院、大學和交通網絡。"},{"en":"If heat affects major cities, many people can be exposed at once.","zh":"如果高溫影響主要城市，許多人可以同時暴露於高溫中。"},{"en":"The phrase describes important population centres.","zh":"這個短語描述重要人口中心。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":13},{"front":"high-altitude ski resorts","meaning":"高海拔滑雪度假區","examples":[{"en":"The question asks whether governments are building high-altitude ski resorts.","zh":"題目問政府是否正在建造高海拔滑雪度假區。"},{"en":"High-altitude ski resorts are ski areas located high in the mountains.","zh":"高海拔滑雪度假區是位於高山地區的滑雪場。"},{"en":"A high-altitude ski resort may keep snow longer than one lower down.","zh":"高海拔滑雪度假區可能比低海拔度假區更長時間保留積雪。"},{"en":"If lower resorts lose snow, investors may become more interested in high-altitude resorts.","zh":"如果低海拔度假區失去積雪，投資者可能更有興趣投資高海拔度假區。"},{"en":"The phrase links skiing with elevation and climate conditions.","zh":"這個短語把滑雪與海拔和氣候條件連繫起來。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":13},{"front":"answer the questions below","meaning":"回答以下問題","examples":[{"en":"Students answer the questions below using words from the passage.","zh":"學生使用文章中的詞語回答以下問題。"},{"en":"Answer the questions below means respond to the tasks printed after the reading text or instruction.","zh":"“Answer the questions below” 指回答閱讀文本或指示下方列出的題目。"},{"en":"Students should scan the passage for evidence before answering the questions below.","zh":"學生回答以下問題前，應掃讀文章尋找證據。"},{"en":"If answers must use passage words, outside knowledge should not replace the text.","zh":"如果答案必須使用文章詞語，外部知識不應取代文本。"},{"en":"The phrase is a common reading-test instruction.","zh":"這個短語是常見閱讀測驗指示。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":13},{"front":"no more than two words and/or numbers","meaning":"不多於兩個字及／或數字","examples":[{"en":"Students should use no more than two words and/or numbers.","zh":"學生應使用不多於兩個字及／或數字。"},{"en":"No more than two words and/or numbers means the answer must stay within that exact limit.","zh":"“No more than two words and/or numbers” 指答案必須符合該限制。"},{"en":"If the answer is “1976 and 1995,” it fits because it uses numbers and a joining word.","zh":"如果答案是 “1976 and 1995”，它符合要求，因為使用數字和連接詞。"},{"en":"Students may lose marks if they add extra words beyond the limit.","zh":"如果學生加入超出限制的額外詞語，可能會失分。"},{"en":"The phrase gives a strict answer format.","zh":"這個短語給出嚴格答案格式。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":13},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must come from the passage.","zh":"答案必須來自文章。"},{"en":"From the passage means using information or exact words found in the reading text.","zh":"“From the passage” 指使用閱讀文本中的資料或準確詞語。"},{"en":"Students should copy the answer from the passage if the instruction asks for passage words.","zh":"如果指示要求使用文章詞語，學生應從文章抄出答案。"},{"en":"If the answer is not in the passage, students should not invent it from general knowledge.","zh":"如果答案不在文章中，學生不應根據常識編造。"},{"en":"The phrase reminds learners to rely on the source text.","zh":"這個短語提醒學習者依靠來源文本。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":13},{"front":"hottest summers","meaning":"最熱夏季","examples":[{"en":"The question asks which years had Britain’s hottest summers.","zh":"題目問哪些年份有英國最熱夏季。"},{"en":"Hottest summers are the summers with the highest measured temperatures in a record.","zh":"最熱夏季是記錄中量度氣溫最高的夏天。"},{"en":"A climate chart may rank the hottest summers to show which years were most extreme.","zh":"氣候圖表可能排列最熱夏季，以顯示哪些年份最極端。"},{"en":"If several hottest summers occur close together, scientists may look for a warming trend.","zh":"如果幾個最熱夏季接近發生，科學家可能尋找暖化趨勢。"},{"en":"The phrase compares summer seasons by heat.","zh":"這個短語按熱度比較夏季。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":14},{"front":"earlier event","meaning":"較早前事件","examples":[{"en":"The question asks which earlier event changed UK government policy.","zh":"題目問哪個較早前事件改變了英國政府政策。"},{"en":"An earlier event is something that happened before the event currently being discussed.","zh":"較早前事件是目前討論事件之前發生的事情。"},{"en":"A school may change safety rules because of an earlier event in which a student was injured.","zh":"學校可能因較早前有學生受傷的事件而改變安全規則。"},{"en":"If an earlier event changed policy, later disasters may be compared with it.","zh":"如果較早前事件改變政策，後來災害可能與它作比較。"},{"en":"The phrase points back to a previous cause or example.","zh":"這個短語指回以前的原因或例子。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":14},{"front":"change government policy","meaning":"改變政府政策","examples":[{"en":"The earlier floods changed UK government policy.","zh":"較早前的洪災改變了英國政府政策。"},{"en":"To change government policy means to alter the rules, plans or priorities of a government.","zh":"“Change government policy” 指改變政府的規則、計劃或優先事項。"},{"en":"A serious public health crisis can change government policy on hospitals and emergency planning.","zh":"嚴重公共健康危機可以改變政府在醫院和應急規劃方面的政策。"},{"en":"If disasters reveal weak preparation, they can force governments to change policy.","zh":"如果災害揭示準備不足，就可以迫使政府改變政策。"},{"en":"The phrase connects events with official decision-making.","zh":"這個短語把事件與官方決策連繫起來。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":14},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的詞語完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the summary printed after the instruction.","zh":"“Complete the summary below” 指填寫指示下方摘要中的缺漏詞語。"},{"en":"Students should read the whole summary before choosing words from the passage.","zh":"學生應先閱讀整段摘要，再從文章選詞。"},{"en":"If the grammar before a blank requires a noun, that clue can help identify the answer.","zh":"如果空格前文法需要名詞，該線索可以幫助識別答案。"},{"en":"The phrase is a common reading-test instruction.","zh":"這個短語是常見閱讀測驗指示。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":14},{"front":"no more than three words","meaning":"不多於三個字","examples":[{"en":"Students should choose no more than three words from the passage.","zh":"學生應從文章選擇不多於三個字。"},{"en":"No more than three words means the answer must contain three words or fewer.","zh":"“No more than three words” 指答案必須包含三個字或更少。"},{"en":"If the correct answer is “the ten hottest years,” students must check whether it exceeds the limit.","zh":"如果正確答案是 “the ten hottest years”，學生必須檢查它是否超出限制。"},{"en":"Extra words can make an otherwise correct answer wrong in reading tests.","zh":"在閱讀測驗中，額外字詞可以令本來正確的答案變錯。"},{"en":"The phrase gives a strict word limit.","zh":"這個短語給出嚴格字數限制。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":14},{"front":"hottest years worldwide","meaning":"全球最熱年份","examples":[{"en":"The summary refers to the hottest years worldwide.","zh":"摘要提到全球最熱年份。"},{"en":"Hottest years worldwide are the years with the highest global temperatures on record.","zh":"全球最熱年份是全球氣溫記錄中最高溫的年份。"},{"en":"A climate report may list the hottest years worldwide to show a global trend.","zh":"氣候報告可能列出全球最熱年份，以顯示全球趨勢。"},{"en":"If the hottest years worldwide all occur recently, the pattern may suggest continued warming.","zh":"如果全球最熱年份全都在近年發生，該模式可能表示持續暖化。"},{"en":"The phrase focuses on global, not local, temperature ranking.","zh":"這個短語強調全球而非本地氣溫排名。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":14},{"front":"on record","meaning":"有記錄以來","examples":[{"en":"The ten hottest years on record occurred after 1990.","zh":"有記錄以來十個最熱年份都發生在1990年之後。"},{"en":"On record means officially measured, written down or recorded.","zh":"“On record” 指被正式量度、寫下或記錄。"},{"en":"This may be the busiest day on record for the airport if passenger numbers are confirmed.","zh":"如果旅客人數獲確認，這可能是機場有記錄以來最繁忙的一天。"},{"en":"If a year is the hottest on record, no recorded year before it was hotter.","zh":"如果某年是有記錄以來最熱，之前沒有任何有記錄年份更熱。"},{"en":"The phrase depends on available official data.","zh":"這個短語依賴可用官方數據。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":14},{"front":"began in","meaning":"始於","examples":[{"en":"The global temperature record began in 1856.","zh":"全球氣溫記錄始於1856年。"},{"en":"Began in means started at a particular time or in a particular year.","zh":"“Began in” 指在某個特定時間或年份開始。"},{"en":"The school’s exchange programme began in 2010 with only ten students.","zh":"學校交換計劃始於2010年，當時只有十名學生。"},{"en":"If a record began in 1856, comparisons before that year may be less certain.","zh":"如果記錄始於1856年，該年以前的比較可能較不確定。"},{"en":"The phrase marks the starting point of a period or record.","zh":"這個短語標示一段時期或記錄的起點。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":14},{"front":"thousands of people","meaning":"數以千計的人","examples":[{"en":"Thousands of people died during the heatwave.","zh":"數以千計的人在熱浪期間死亡。"},{"en":"Thousands of people means a very large number of people, at least several thousand.","zh":"數以千計的人指非常多人，至少數千人。"},{"en":"Thousands of people may use a train station every morning.","zh":"每天早上可能有數以千計的人使用一個火車站。"},{"en":"If thousands of people die in a heatwave, the event is a major public-health disaster.","zh":"如果數以千計的人在熱浪中死亡，該事件就是重大公共健康災難。"},{"en":"The phrase gives a large but not exact number.","zh":"這個短語給出大但不精確的數目。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":14},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter, A, B, C or D.","zh":"學生選出正確字母 A、B、C 或 D。"},{"en":"To choose the correct letter means to select the answer option marked by the right letter.","zh":"“Choose the correct letter” 指選出由正確字母標示的答案選項。"},{"en":"Students should read all four options before choosing the correct letter.","zh":"學生應先閱讀所有四個選項，再選出正確字母。"},{"en":"If two options look similar, passage evidence should decide which letter is correct.","zh":"如果兩個選項看起來相似，文章證據應決定哪個字母正確。"},{"en":"The phrase is a common multiple-choice instruction.","zh":"這個短語是常見選擇題指示。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":14},{"front":"best title for","meaning":"……的最佳標題","examples":[{"en":"The question asks for the best title for the passage.","zh":"題目問文章的最佳標題。"},{"en":"The best title for a passage is the heading that most accurately captures its main idea.","zh":"文章的最佳標題，是最準確概括其主旨的題目。"},{"en":"A story about a lost dog returning home should not have a title about cats.","zh":"關於走失狗回家的故事，不應有關於貓的標題。"},{"en":"If a passage focuses on one heatwave and its meaning, the best title should reflect that focus.","zh":"如果文章集中於一場熱浪及其意義，最佳標題應反映該焦點。"},{"en":"The phrase asks students to identify the overall theme.","zh":"這個短語要求學生識別整體主題。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":14},{"front":"what caused global warming","meaning":"全球暖化的成因","examples":[{"en":"One option focuses on what caused global warming.","zh":"其中一個選項集中於全球暖化的成因。"},{"en":"What caused global warming means the reasons or human activities that led to the warming trend.","zh":"全球暖化的成因指導致暖化趨勢的原因或人類活動。"},{"en":"A science lesson may ask what caused global warming before discussing its effects.","zh":"科學課可能先問全球暖化的成因，再討論其影響。"},{"en":"If a passage mainly discusses a heatwave’s impact, an option about causes may be too narrow or off focus.","zh":"如果文章主要討論熱浪影響，關於成因的選項可能太狹窄或偏離焦點。"},{"en":"The phrase points to causes, not consequences.","zh":"這個短語指原因，而不是後果。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":15},{"front":"effects of global warming","meaning":"全球暖化的影響","examples":[{"en":"One option focuses on the effects of global warming.","zh":"其中一個選項集中於全球暖化的影響。"},{"en":"Effects of global warming are the results or consequences caused by rising global temperatures.","zh":"全球暖化的影響，是全球氣溫上升造成的結果或後果。"},{"en":"The effects of global warming can include heatwaves, melting ice and pressure on water supplies.","zh":"全球暖化的影響可以包括熱浪、冰層融化和水資源壓力。"},{"en":"If a passage shows deaths, fires and record heat, it is discussing possible effects of warming.","zh":"如果文章展示死亡、山火和破紀錄高溫，它就是在討論暖化的可能影響。"},{"en":"The phrase focuses on what global warming does.","zh":"這個短語強調全球暖化造成甚麼。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":15},{"front":"that hot year in Europe","meaning":"歐洲那個炎熱年份","examples":[{"en":"The title “That Hot Year in Europe” refers to the 2003 heatwave.","zh":"標題「歐洲那個炎熱年份」指2003年熱浪。"},{"en":"That hot year in Europe means a particular year remembered for extreme heat across Europe.","zh":"歐洲那個炎熱年份，指因歐洲各地極端高溫而被記住的某一年。"},{"en":"A documentary might call 2003 “that hot year in Europe” to make the event memorable for viewers.","zh":"紀錄片可能稱2003年為「歐洲那個炎熱年份」，令觀眾更容易記住事件。"},{"en":"If one year changes climate planning across Europe, it can become known by its heat.","zh":"如果某一年改變了歐洲各地的氣候規劃，它就可能因高溫而為人所知。"},{"en":"The phrase gives an informal title for a historically significant hot year.","zh":"這個短語為一個具歷史意義的炎熱年份給出較口語化標題。"}],"source":"Passage 2 Flash Cards  25 - The 2003 Heatwave.pdf","sourcePage":15}],"ielts/reading/passage-2/Practice 26":[{"front":"being left-handed","meaning":"慣用左手","examples":[{"en":"The passage explores what it means to be left-handed in a right-handed world.","zh":"文章探討在右撇子主導的世界中慣用左手意味着甚麼。"},{"en":"Being left-handed means naturally using the left hand more comfortably than the right hand.","zh":"being left-handed 指自然地使用左手比右手更舒服。"},{"en":"A left-handed student may find some scissors difficult to use because they were made for right-handed users.","zh":"慣用左手的學生可能覺得某些剪刀難用，因為它們是為右撇子使用者而設計的。"},{"en":"If many tools are designed for right-handed people, being left-handed can make daily tasks less convenient.","zh":"如果許多工具都為右撇子設計，慣用左手會令日常任務較不方便。"},{"en":"This phrase describes a natural hand preference, not a bad habit.","zh":"這個片語描述自然的用手偏好，而不是壞習慣。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":1},{"front":"right-handed world","meaning":"右撇子主導的世界","examples":[{"en":"Left-handed people live in a right-handed world.","zh":"左撇子生活在右撇子主導的世界中。"},{"en":"A right-handed world is a society where most tools, habits, and designs suit right-handed people.","zh":"right-handed world 指大多數工具、習慣和設計都適合右撇子使用者的社會。"},{"en":"A classroom desk with the writing board on the right side may suit right-handed students more.","zh":"書寫板在右側的課桌可能更適合右撇子學生。"},{"en":"If everyday objects favour right-handed users, left-handed people may need to adapt constantly.","zh":"如果日常物件偏向右撇子使用者，左撇子可能需要不斷適應。"},{"en":"This phrase highlights how the majority shapes ordinary design.","zh":"這個片語突出多數人如何塑造普通設計。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":1},{"front":"be designed for","meaning":"為……而設計","examples":[{"en":"The world is designed for right-handed people.","zh":"這個世界是為右撇子而設計的。"},{"en":"To be designed for someone means to be made with that person’s needs or habits in mind.","zh":"be designed for someone 指製作時考慮到某人的需要或習慣。"},{"en":"A children’s playground is designed for young users, so the equipment is lower and safer.","zh":"兒童遊樂場是為年幼使用者而設計的，所以設施較矮也較安全。"},{"en":"If a product is designed for one group, other users may find it uncomfortable.","zh":"如果產品是為某一群體而設計，其他使用者可能會覺得不舒服。"},{"en":"This phrase explains who a thing is mainly intended to serve.","zh":"這個片語解釋某物主要打算服務誰。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":1},{"front":"a tenth of the population","meaning":"人口的十分之一","examples":[{"en":"A tenth of the population prefers the left hand.","zh":"人口的十分之一較喜歡用左手。"},{"en":"A tenth of the population means one out of every ten people in a group.","zh":"a tenth of the population 指一個群體中每十人有一人。"},{"en":"If a school has 1,000 students, a tenth of the population is about 100 students.","zh":"如果一所學校有1,000名學生，人口的十分之一大約是100名學生。"},{"en":"When a tenth of the population has a need, public design should not ignore it.","zh":"當人口的十分之一有某種需要，公共設計就不應忽視它。"},{"en":"This phrase gives a simple fraction of a whole population.","zh":"這個片語表示整體人口中的簡單分數。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":1},{"front":"prefer the left","meaning":"較喜歡用左手","examples":[{"en":"Some people naturally prefer the left hand.","zh":"有些人自然較喜歡用左手。"},{"en":"To prefer the left means to choose or use the left side more naturally than the right side.","zh":"prefer the left 指比右側更自然地選擇或使用左側。"},{"en":"A child may prefer the left when drawing, brushing teeth, or throwing a ball.","zh":"孩子畫畫、刷牙或拋球時可能較喜歡用左手。"},{"en":"If someone prefers the left, forcing them to use the right may feel awkward.","zh":"如果某人較喜歡用左手，強迫他用右手可能會感覺笨拙。"},{"en":"This phrase usually refers to natural preference rather than a conscious decision.","zh":"這個片語通常指自然偏好，而不是有意識的決定。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":1},{"front":"the probability that","meaning":"……的可能性","examples":[{"en":"The probability that two right-handed people will have a left-handed child is low.","zh":"兩名右撇子生出左撇子孩子的可能性較低。"},{"en":"The probability that something will happen means the chance that it will happen.","zh":"probability that something will happen 指某事發生的機會。"},{"en":"The probability that it will rain affects whether students bring umbrellas.","zh":"下雨的可能性會影響學生是否帶雨傘。"},{"en":"If the probability is low, the event can still happen, but it is less expected.","zh":"如果可能性較低，事件仍可發生，但較不預期。"},{"en":"This phrase is useful for talking about chances, risks, and predictions.","zh":"這個片語適合談論機會、風險和預測。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":1},{"front":"right-handed people","meaning":"慣用右手的人","examples":[{"en":"Two right-handed people may still have a left-handed child.","zh":"兩名慣用右手的人仍可能有慣用左手的孩子。"},{"en":"Right-handed people are people who naturally use their right hand more often or more easily.","zh":"right-handed people 是自然更常或更容易使用右手的人。"},{"en":"Most classroom scissors are comfortable for right-handed people.","zh":"大多數課室剪刀對慣用右手的人較舒服。"},{"en":"If both parents are right-handed, their child may still develop a different hand preference.","zh":"即使父母雙方都是右撇子，孩子仍可能形成不同用手偏好。"},{"en":"This phrase describes a common hand preference.","zh":"這個片語描述常見的用手偏好。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":1},{"front":"left-handed child","meaning":"慣用左手的孩子","examples":[{"en":"The chance of having a left-handed child rises if one parent is left-handed.","zh":"如果父母其中一方是左撇子，生出慣用左手孩子的機會會上升。"},{"en":"A left-handed child is a child who naturally uses the left hand more comfortably.","zh":"left-handed child 是自然使用左手較舒服的孩子。"},{"en":"A left-handed child may need a different desk position when writing beside classmates.","zh":"慣用左手的孩子與同學並排寫字時，可能需要不同座位位置。"},{"en":"If teachers recognise a left-handed child’s needs early, writing practice becomes less frustrating.","zh":"如果老師早些認識慣用左手孩子的需要，寫字練習會較少挫敗。"},{"en":"This phrase describes a child’s natural hand preference.","zh":"這個片語描述孩子自然的用手偏好。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":1},{"front":"the chance rises to","meaning":"機會上升至","examples":[{"en":"The chance rises to 19.5 percent if one parent is left-handed.","zh":"如果父母其中一方是左撇子，機會上升至19.5%。"},{"en":"The chance rises to a number means the probability increases until it reaches that level.","zh":"the chance rises to a number 指可能性增加並達到某水平。"},{"en":"If more students revise daily, the chance of passing may rise to a higher level.","zh":"如果更多學生每天溫習，合格機會可能上升至較高水平。"},{"en":"When one risk factor is present, the chance can rise even if the result is not guaranteed.","zh":"當一個風險因素存在，機會可以上升，即使結果不保證。"},{"en":"This phrase describes an increase in probability.","zh":"這個片語描述可能性的增加。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":1},{"front":"if one parent is a lefty","meaning":"如果父母其中一方是左撇子","examples":[{"en":"The chance rises if one parent is a lefty.","zh":"如果父母其中一方是左撇子，機會會上升。"},{"en":"If one parent is a lefty means if either the mother or father naturally uses the left hand.","zh":"if one parent is a lefty 指如果母親或父親其中一方自然使用左手。"},{"en":"If one parent is a lefty, a child may grow up seeing left-handed actions at home.","zh":"如果父母其中一方是左撇子，孩子可能在家中看到左手動作。"},{"en":"The child’s hand preference may be influenced by genes, imitation, or development.","zh":"孩子的用手偏好可能受基因、模仿或發育影響。"},{"en":"This phrase gives a condition involving one left-handed parent.","zh":"這個片語給出涉及一名左撇子父母的條件。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":1},{"front":"lefty","meaning":"左撇子","examples":[{"en":"A lefty is a person who is left-handed.","zh":"lefty 是一個慣用左手的人。"},{"en":"A lefty is an informal word for someone who prefers to use the left hand.","zh":"lefty 是指較喜歡使用左手的人的非正式說法。"},{"en":"A lefty may turn a notebook slightly differently when writing.","zh":"左撇子寫字時可能把筆記本轉成稍微不同的角度。"},{"en":"If a lefty uses tools made for right-handed people, small tasks can become annoying.","zh":"如果左撇子使用為右撇子製造的工具，小任務可能變得煩人。"},{"en":"This word is casual and common in everyday speech.","zh":"這個詞較口語，常見於日常說話。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":1},{"front":"both parents are left-handed","meaning":"父母雙方都是左撇子","examples":[{"en":"The chance is higher if both parents are left-handed.","zh":"如果父母雙方都是左撇子，機會會較高。"},{"en":"Both parents are left-handed means the child’s mother and father both naturally prefer the left hand.","zh":"both parents are left-handed 指孩子的母親和父親都自然較喜歡使用左手。"},{"en":"If both parents are left-handed, a child may see many left-handed habits at home.","zh":"如果父母雙方都是左撇子，孩子可能在家中看到許多左手習慣。"},{"en":"This condition may increase the chance of left-handedness, but it does not guarantee it.","zh":"這種情況可能增加左撇子傾向的機會，但不保證一定如此。"},{"en":"This phrase describes a family situation involving two left-handed parents.","zh":"這個片語描述涉及兩名左撇子父母的家庭情況。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":2},{"front":"stem from","meaning":"源自","examples":[{"en":"The preference could stem from an infant’s imitation of parents.","zh":"這種偏好可能源自嬰兒對父母的模仿。"},{"en":"To stem from something means to come from it or be caused by it.","zh":"stem from something 指來自某事或由某事造成。"},{"en":"A student’s fear of speaking may stem from being laughed at in the past.","zh":"學生害怕說話可能源自過去被取笑。"},{"en":"If a habit stems from early childhood, it may feel natural later in life.","zh":"如果習慣源自童年早期，長大後可能感覺很自然。"},{"en":"This phrase points to the origin or cause of something.","zh":"這個片語指出某事的起源或原因。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":2},{"front":"infant’s imitation of","meaning":"嬰兒對……的模仿","examples":[{"en":"Hand preference could stem from an infant’s imitation of parents.","zh":"用手偏好可能源自嬰兒對父母的模仿。"},{"en":"An infant’s imitation of someone means a baby copying that person’s actions.","zh":"infant’s imitation of someone 指嬰兒模仿某人的動作。"},{"en":"A baby may copy a parent’s smile, wave, or hand movement.","zh":"嬰兒可能模仿父母的微笑、揮手或手部動作。"},{"en":"If infants imitate adults often, early habits may begin before they can explain them.","zh":"如果嬰兒經常模仿成人，早期習慣可能在他們能解釋之前已開始。"},{"en":"This phrase describes learning by copying during early life.","zh":"這個片語描述生命早期透過模仿學習。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":2},{"front":"genetic influence","meaning":"遺傳影響","examples":[{"en":"Marian Annett tested genetic influence on handedness.","zh":"Marian Annett 測試遺傳影響對慣用手傾向的作用。"},{"en":"Genetic influence means the effect that inherited genes may have on a trait.","zh":"genetic influence 指遺傳基因可能對某特徵產生的影響。"},{"en":"Eye colour often shows genetic influence because children inherit genes from parents.","zh":"眼睛顏色常顯示遺傳影響，因為孩子從父母繼承基因。"},{"en":"If handedness has genetic influence, family patterns may partly explain it.","zh":"如果慣用手有遺傳影響，家庭模式可能部分解釋它。"},{"en":"This phrase does not mean genes are the only cause.","zh":"這個片語不代表基因是唯一原因。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":2},{"front":"beginning in the 1970s","meaning":"始於1970年代","examples":[{"en":"Research into genetic influence began in the 1970s.","zh":"關於遺傳影響的研究始於1970年代。"},{"en":"Beginning in the 1970s means starting during the decade from 1970 to 1979.","zh":"beginning in the 1970s 指在1970年至1979年這十年間開始。"},{"en":"A school tradition beginning in the 1970s may still be remembered by older teachers.","zh":"始於1970年代的學校傳統，可能仍被年長教師記得。"},{"en":"If research began in the 1970s, later studies have had decades to test the idea.","zh":"如果研究始於1970年代，後來研究已有數十年時間測試這個想法。"},{"en":"This phrase gives the starting period of an activity.","zh":"這個片語給出某活動的起始時期。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":2},{"front":"British biologist","meaning":"英國生物學家","examples":[{"en":"Marian Annett was a British biologist at the University of Leicester.","zh":"Marian Annett 是萊斯特大學的一名英國生物學家。"},{"en":"A British biologist is a scientist from Britain who studies living organisms.","zh":"British biologist 是來自英國並研究生物的科學家。"},{"en":"A British biologist may study plants, animals, genes, or human development.","zh":"英國生物學家可能研究植物、動物、基因或人類發育。"},{"en":"If a biologist studies handedness, they may look for links between genes and body development.","zh":"如果生物學家研究慣用手，他們可能尋找基因與身體發育之間的關聯。"},{"en":"This phrase identifies both nationality and scientific field.","zh":"這個片語同時指出國籍和科學領域。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":2},{"front":"hypothesize that","meaning":"假設；提出假說","examples":[{"en":"Annett hypothesized that no single gene determines handedness.","zh":"Annett 假設沒有單一基因決定慣用手傾向。"},{"en":"To hypothesize that means to suggest a possible explanation that can be tested.","zh":"hypothesize that 指提出一個可以被測試的可能解釋。"},{"en":"A scientist may hypothesize that poor sleep affects memory before running an experiment.","zh":"科學家可能先假設睡眠不足影響記憶，再進行實驗。"},{"en":"If evidence is incomplete, researchers hypothesize first and test later.","zh":"如果證據不完整，研究人員會先提出假說，之後再測試。"},{"en":"This phrase introduces a scientific guess, not a proven fact.","zh":"這個片語引入科學猜想，而不是已證實事實。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":2},{"front":"no single gene determines","meaning":"沒有單一基因決定","examples":[{"en":"No single gene determines whether a child is left-handed.","zh":"沒有單一基因決定孩子是否慣用左手。"},{"en":"No single gene determines something means one gene alone does not decide the result.","zh":"no single gene determines something 指單靠一個基因不能決定結果。"},{"en":"No single habit determines exam success; sleep, practice, teaching, and motivation all matter.","zh":"沒有單一習慣決定考試成功；睡眠、練習、教學和動機都重要。"},{"en":"If no single gene determines handedness, several factors may work together.","zh":"如果沒有單一基因決定慣用手，幾個因素可能共同作用。"},{"en":"This phrase rejects an overly simple genetic explanation.","zh":"這個片語否定過於簡單的遺傳解釋。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":2},{"front":"handedness","meaning":"慣用手傾向","examples":[{"en":"Handedness may be influenced by both genes and development.","zh":"慣用手傾向可能同時受基因和發育影響。"},{"en":"Handedness means a person’s natural preference for using one hand rather than the other.","zh":"handedness 指一個人自然較喜歡使用某一隻手。"},{"en":"Teachers may notice a child’s handedness when the child writes, cuts paper, or throws a ball.","zh":"老師可能在孩子寫字、剪紙或拋球時注意到其慣用手傾向。"},{"en":"If handedness develops gradually, a young child may switch hands before settling on one.","zh":"如果慣用手傾向逐漸發展，年幼孩子可能在固定使用某手之前來回轉換。"},{"en":"This word refers to right-handedness, left-handedness, or mixed hand preference.","zh":"這個詞指右撇子、左撇子或混合用手偏好。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":2},{"front":"fetal development","meaning":"胎兒發育","examples":[{"en":"Handedness may be influenced during fetal development.","zh":"慣用手傾向可能在胎兒發育期間受影響。"},{"en":"Fetal development is the process by which a baby grows inside the mother before birth.","zh":"fetal development 是嬰兒出生前在母體內成長的過程。"},{"en":"Doctors use scans to check fetal development during pregnancy.","zh":"醫生在懷孕期間使用掃描檢查胎兒發育。"},{"en":"If body movement begins before birth, fetal development may affect later hand preference.","zh":"如果身體動作在出生前已開始，胎兒發育可能影響日後用手偏好。"},{"en":"This phrase describes growth before a baby is born.","zh":"這個片語描述嬰兒出生前的成長。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":2},{"front":"molecular factor","meaning":"分子因素","examples":[{"en":"A certain molecular factor may strengthen the brain’s left hemisphere.","zh":"某種分子因素可能強化大腦左半球。"},{"en":"A molecular factor is a tiny biological element that can affect how the body develops or works.","zh":"molecular factor 是能影響身體如何發育或運作的微小生物元素。"},{"en":"Hormones and proteins can act as molecular factors during development.","zh":"荷爾蒙和蛋白質可以在發育期間作為分子因素。"},{"en":"If a molecular factor affects the brain, it may influence behaviour later.","zh":"如果分子因素影響大腦，它可能日後影響行為。"},{"en":"This phrase points to a small biological cause inside the body.","zh":"這個片語指出身體內部的微小生物原因。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":2},{"front":"strengthen the brain’s left hemisphere","meaning":"強化大腦左半球","examples":[{"en":"A molecular factor helps to strengthen the brain’s left hemisphere.","zh":"一種分子因素幫助強化大腦左半球。"},{"en":"To strengthen the brain’s left hemisphere means to make the left side of the brain develop or function more strongly.","zh":"strengthen the brain’s left hemisphere 指令大腦左側發育或運作得更強。"},{"en":"Repeated language practice may strengthen brain networks linked to speech and reading.","zh":"反覆語言練習可能強化與說話和閱讀有關的大腦網絡。"},{"en":"If one hemisphere becomes stronger for certain tasks, it may influence which hand becomes dominant.","zh":"如果某個半球在某些任務上變得更強，它可能影響哪隻手成為主導。"},{"en":"This phrase describes biological development in one side of the brain.","zh":"這個片語描述大腦一側的生物發育。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":3},{"front":"left hemisphere","meaning":"左腦半球","examples":[{"en":"The left hemisphere controls the right side of the body.","zh":"左腦半球控制身體右側。"},{"en":"The left hemisphere is the left half of the brain.","zh":"left hemisphere 是大腦的左半部分。"},{"en":"A doctor may study the left hemisphere when a patient has language difficulties.","zh":"當病人有語言困難時，醫生可能研究左腦半球。"},{"en":"If the left hemisphere is damaged, speech or right-side movement may be affected.","zh":"如果左腦半球受損，說話或右側身體動作可能受影響。"},{"en":"This phrase refers to one of the brain’s two main halves.","zh":"這個片語指大腦兩個主要半球之一。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":3},{"front":"increase the probability that","meaning":"增加……的可能性","examples":[{"en":"The factor increases the probability that the right hand will be dominant.","zh":"這個因素增加右手成為主導的可能性。"},{"en":"To increase the probability that something will happen means to make it more likely.","zh":"increase the probability that something will happen 指令某事更有可能發生。"},{"en":"Studying regularly increases the probability that a student will pass the exam.","zh":"定期溫習會增加學生通過考試的可能性。"},{"en":"If a biological factor supports one side of the brain, it may increase the chance of one hand being preferred.","zh":"如果生物因素支持大腦某一側，它可能增加某隻手被偏好的機會。"},{"en":"This phrase describes raising the chance of an outcome.","zh":"這個片語描述提高某結果的機會。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":3},{"front":"dominant","meaning":"佔主導的；主要使用的","examples":[{"en":"The right hand is dominant in most people.","zh":"大多數人的右手是主要使用的。"},{"en":"Dominant means stronger, more commonly used, or more controlling than another option.","zh":"dominant 指比另一選項更強、更常使用或更具控制力。"},{"en":"In a group discussion, one loud student may become dominant if others stay quiet.","zh":"在小組討論中，如果其他人保持安靜，一名大聲學生可能變得佔主導。"},{"en":"If the right hand is dominant, a person will usually write, throw, or cut with it.","zh":"如果右手佔主導，一個人通常會用右手寫字、拋球或剪東西。"},{"en":"This word describes the side or choice that takes the leading role.","zh":"這個詞描述佔領導角色的一側或選擇。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":3},{"front":"controls the right side of the body","meaning":"控制身體右側","examples":[{"en":"The left side of the brain controls the right side of the body.","zh":"大腦左側控制身體右側。"},{"en":"Controls the right side of the body means sends signals that help move or manage the body’s right side.","zh":"controls the right side of the body 指發送訊號以幫助移動或管理身體右側。"},{"en":"A brain injury on one side can affect movement on the opposite side of the body.","zh":"一側腦部受傷可以影響身體相反一側的活動。"},{"en":"If the left brain controls the right body, brain dominance may relate to hand preference.","zh":"如果左腦控制右側身體，腦部主導性可能與用手偏好有關。"},{"en":"This phrase explains a basic cross-body brain connection.","zh":"這個片語解釋基本的交叉身體腦部連繫。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":3},{"front":"and vice versa","meaning":"反之亦然","examples":[{"en":"The left brain controls the right body, and vice versa.","zh":"左腦控制右側身體，反之亦然。"},{"en":"And vice versa means the reverse is also true.","zh":"and vice versa 指相反方向也同樣成立。"},{"en":"Teachers can learn from students, and vice versa.","zh":"老師可以向學生學習，反之亦然。"},{"en":"If the left brain controls the right body and vice versa, each brain side affects the opposite body side.","zh":"如果左腦控制右側身體，反之亦然，則每個腦半球都影響相反一側身體。"},{"en":"This phrase avoids repeating the same idea in reverse.","zh":"這個片語避免重複說出反向的同一個意思。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":3},{"front":"among the minority of","meaning":"在少數……之中","examples":[{"en":"Among the minority of people who lack this factor, handedness develops by chance.","zh":"在缺乏這個因素的少數人之中，慣用手傾向靠偶然發展。"},{"en":"Among the minority of means within the smaller group of people or things.","zh":"among the minority of 指在較小的一群人或事物之中。"},{"en":"Among the minority of students who cycle to school, rain can be a major problem.","zh":"在少數騎單車上學的學生之中，下雨可能是大問題。"},{"en":"If only a minority lack a factor, most people may develop differently from that smaller group.","zh":"如果只有少數人缺乏某因素，大多數人的發展可能不同於這個小群體。"},{"en":"This phrase highlights a smaller part of a larger population.","zh":"這個片語突出較大群體中的較小部分。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":3},{"front":"lack this factor","meaning":"缺乏這個因素","examples":[{"en":"Some people may lack the factor that promotes right-handedness.","zh":"有些人可能缺乏促進右撇子的這個因素。"},{"en":"To lack this factor means not to have this particular cause or influence.","zh":"lack this factor 指沒有這個特定原因或影響因素。"},{"en":"A plant may grow slowly if it lacks the factor that helps it absorb nutrients.","zh":"如果植物缺乏幫助吸收養分的因素，可能生長緩慢。"},{"en":"If someone lacks this biological factor, their hand preference may develop less predictably.","zh":"如果某人缺乏這個生物因素，其用手偏好可能較難預測地發展。"},{"en":"This phrase describes the absence of a specific influence.","zh":"這個片語描述某個特定影響因素的缺失。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":3},{"front":"entirely by chance","meaning":"完全靠偶然","examples":[{"en":"Handedness may develop entirely by chance.","zh":"慣用手傾向可能完全靠偶然發展。"},{"en":"Entirely by chance means only because of random events, not because of a clear plan or fixed cause.","zh":"entirely by chance 指只因隨機事件發生，而不是因清楚計劃或固定原因。"},{"en":"A student may meet an old friend entirely by chance at a train station.","zh":"學生可能在火車站完全偶然地遇到老朋友。"},{"en":"If handedness develops by chance, the result cannot be fully predicted from genes alone.","zh":"如果慣用手靠偶然發展，結果就不能單靠基因完全預測。"},{"en":"This phrase stresses randomness rather than intention or certainty.","zh":"這個片語強調隨機性，而不是意圖或確定性。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":3},{"front":"research conducted on twins","meaning":"對雙胞胎進行的研究","examples":[{"en":"Research conducted on twins complicates the theory.","zh":"對雙胞胎進行的研究令這個理論變得複雜。"},{"en":"Research conducted on twins means studies that use twins as research subjects.","zh":"research conducted on twins 指以雙胞胎作為研究對象的研究。"},{"en":"Scientists study twins to compare the influence of genes and environment.","zh":"科學家研究雙胞胎，以比較基因和環境的影響。"},{"en":"If identical twins differ in handedness, twin research can challenge simple genetic explanations.","zh":"如果同卵雙胞胎的慣用手不同，雙胞胎研究可以挑戰簡單的遺傳解釋。"},{"en":"This phrase describes a research method using twin pairs.","zh":"這個片語描述使用雙胞胎組合的研究方法。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":3},{"front":"complicate the theory","meaning":"令理論變得複雜","examples":[{"en":"Twin research complicates the genetic theory of handedness.","zh":"雙胞胎研究令慣用手的遺傳理論變得複雜。"},{"en":"To complicate the theory means to make the explanation less simple or less certain.","zh":"complicate the theory 指令解釋變得不那麼簡單或不那麼確定。"},{"en":"A new witness can complicate the theory of what happened in an accident.","zh":"新目擊者可以令事故成因理論變得複雜。"},{"en":"If evidence does not fit a theory, researchers must revise or expand the explanation.","zh":"如果證據不符合某理論，研究人員必須修訂或擴展解釋。"},{"en":"This phrase shows that a simple idea needs more detail.","zh":"這個片語顯示簡單想法需要更多細節。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":3},{"front":"one in five sets of","meaning":"每五對……中有一對","examples":[{"en":"One in five sets of identical twins includes one left-handed person.","zh":"每五對同卵雙胞胎中有一對包括一名左撇子。"},{"en":"One in five sets of means one group out of every five groups.","zh":"one in five sets of 指每五組之中有一組。"},{"en":"One in five sets of exam papers may need extra checking if the instructions were unclear.","zh":"如果指示不清楚，每五份試卷中可能有一份需要額外檢查。"},{"en":"If one in five twin pairs differs in handedness, genes cannot explain everything alone.","zh":"如果每五對雙胞胎中有一對慣用手不同，基因就不能單獨解釋一切。"},{"en":"This phrase gives a proportion using groups rather than individuals.","zh":"這個片語用群組而非個人來表示比例。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":4},{"front":"identical twins","meaning":"同卵雙胞胎","examples":[{"en":"Identical twins share the same genetic material.","zh":"同卵雙胞胎擁有相同的遺傳物質。"},{"en":"Identical twins are twins who develop from the same fertilised egg and have almost the same genes.","zh":"identical twins 是由同一受精卵發育而來、基因幾乎相同的雙胞胎。"},{"en":"Teachers may still notice different personalities in identical twins.","zh":"老師仍可能注意到同卵雙胞胎有不同性格。"},{"en":"If identical twins show different hand preferences, development or environment may also matter.","zh":"如果同卵雙胞胎顯示不同用手偏好，發育或環境也可能重要。"},{"en":"This phrase describes twins who are genetically very similar.","zh":"這個片語描述基因非常相似的雙胞胎。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":4},{"front":"despite the fact that","meaning":"儘管事實是","examples":[{"en":"One twin may be left-handed despite the fact that both twins share the same genes.","zh":"儘管兩名雙胞胎擁有相同基因，其中一人仍可能是左撇子。"},{"en":"Despite the fact that means although something is true.","zh":"despite the fact that 指雖然某事是真的。"},{"en":"A student may fail a test despite the fact that they studied hard.","zh":"儘管學生努力溫習，他仍可能考試不合格。"},{"en":"If twins differ despite sharing genes, other influences must be considered.","zh":"如果雙胞胎儘管共享基因仍有差異，就必須考慮其他影響。"},{"en":"This phrase introduces a surprising contrast with a known fact.","zh":"這個片語引入與已知事實形成的意外對比。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":4},{"front":"genetic material","meaning":"遺傳物質","examples":[{"en":"Identical twins have the same genetic material.","zh":"同卵雙胞胎有相同的遺傳物質。"},{"en":"Genetic material is the biological information inherited from parents, mainly DNA.","zh":"genetic material 是從父母繼承的生物資訊，主要是 DNA。"},{"en":"Doctors may test genetic material to understand inherited diseases.","zh":"醫生可能檢測遺傳物質，以了解遺傳疾病。"},{"en":"If two people share genetic material, they may still differ because development and environment also matter.","zh":"如果兩個人共享遺傳物質，他們仍可能不同，因為發育和環境也重要。"},{"en":"This phrase refers to inherited biological instructions.","zh":"這個片語指被繼承的生物指令。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":4},{"front":"solely responsible for","meaning":"對……負唯一責任","examples":[{"en":"Genes are not solely responsible for handedness.","zh":"基因並非對慣用手傾向負唯一責任。"},{"en":"Solely responsible for means being the only cause of something.","zh":"solely responsible for 指是某事的唯一原因。"},{"en":"A poor grade is not solely responsible for a student’s future; support and effort still matter.","zh":"一次差成績並非對學生未來負唯一責任；支援和努力仍然重要。"},{"en":"If genes are not solely responsible, researchers must examine development and experience too.","zh":"如果基因不是唯一原因，研究人員也必須檢視發育和經驗。"},{"en":"This phrase rejects the idea that one factor explains everything.","zh":"這個片語否定單一因素解釋一切的想法。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":4},{"front":"genetic theory","meaning":"遺傳理論","examples":[{"en":"Genetic theory is challenged by fetal-development research.","zh":"遺傳理論受到胎兒發育研究挑戰。"},{"en":"Genetic theory is an explanation based on the role of inherited genes.","zh":"genetic theory 是基於遺傳基因作用的解釋。"},{"en":"A genetic theory of height would examine how parents’ genes affect children’s growth.","zh":"關於身高的遺傳理論會檢視父母基因如何影響孩子成長。"},{"en":"If new evidence weakens a genetic theory, scientists may add environmental or developmental factors.","zh":"如果新證據削弱遺傳理論，科學家可能加入環境或發育因素。"},{"en":"This phrase describes an explanation centred on heredity.","zh":"這個片語描述以遺傳為中心的解釋。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":4},{"front":"be undermined by","meaning":"被……削弱","examples":[{"en":"Genetic theory is undermined by results from Peter Hepper’s team.","zh":"遺傳理論被 Peter Hepper 團隊的結果削弱。"},{"en":"To be undermined by something means to be weakened by it.","zh":"be undermined by something 指被某事削弱。"},{"en":"A student’s confidence may be undermined by constant criticism.","zh":"學生信心可能被持續批評削弱。"},{"en":"If new results do not fit a theory, the theory may be undermined.","zh":"如果新結果不符合某理論，該理論可能被削弱。"},{"en":"This phrase shows that evidence reduces the strength of an idea.","zh":"這個片語顯示證據降低某想法的力量。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":4},{"front":"psychologists","meaning":"心理學家","examples":[{"en":"The psychologists used ultrasound to study fetal thumb preference.","zh":"心理學家使用超聲波研究胎兒拇指偏好。"},{"en":"Psychologists are specialists who study the mind, behaviour, learning, emotion, or development.","zh":"psychologists 是研究心智、行為、學習、情緒或發展的專家。"},{"en":"Psychologists may study why children become anxious before exams.","zh":"心理學家可能研究孩子為何在考試前焦慮。"},{"en":"If psychologists study babies before birth, they may learn when behaviour patterns begin.","zh":"如果心理學家研究出生前的嬰兒，他們可能了解行為模式何時開始。"},{"en":"This word refers to researchers or professionals in psychology.","zh":"這個詞指心理學研究人員或專業人士。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":4},{"front":"ultrasound","meaning":"超聲波","examples":[{"en":"Ultrasound showed that fetuses already had a thumb preference.","zh":"超聲波顯示胎兒已經有拇指偏好。"},{"en":"Ultrasound is a medical imaging method that uses sound waves to see inside the body.","zh":"ultrasound 是使用聲波觀察身體內部的醫學影像方法。"},{"en":"Pregnant women often have ultrasound scans to check fetal growth.","zh":"孕婦常做超聲波掃描，以檢查胎兒成長。"},{"en":"If ultrasound shows movement before birth, researchers can study early behaviour safely.","zh":"如果超聲波顯示出生前的動作，研究人員可以安全研究早期行為。"},{"en":"This word refers to a common non-invasive scanning technology.","zh":"這個詞指常見的非侵入式掃描技術。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":4},{"front":"by the 15th week of pregnancy","meaning":"到懷孕第15週","examples":[{"en":"By the 15th week of pregnancy, fetuses may show a preference.","zh":"到懷孕第15週，胎兒可能顯示偏好。"},{"en":"By the 15th week of pregnancy means no later than week fifteen during pregnancy.","zh":"by the 15th week of pregnancy 指不遲於懷孕第十五週。"},{"en":"By the 15th week of pregnancy, some parents may already have seen the baby move on a scan.","zh":"到懷孕第15週，一些父母可能已在掃描中看到胎兒活動。"},{"en":"If a preference appears this early, it may begin before conscious learning.","zh":"如果偏好這麼早出現，它可能在有意識學習之前已開始。"},{"en":"This phrase gives a precise point in prenatal development.","zh":"這個片語給出產前發育中的精確時間點。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":4},{"front":"fetuses","meaning":"胎兒","examples":[{"en":"Fetuses may prefer one thumb before birth.","zh":"胎兒在出生前可能偏好某一隻拇指。"},{"en":"Fetuses are unborn babies developing inside the womb.","zh":"fetuses 是在子宮內發育、尚未出生的嬰兒。"},{"en":"Doctors monitor fetuses to check their growth, heartbeat, and movement.","zh":"醫生監測胎兒，以檢查成長、心跳和動作。"},{"en":"If fetuses show repeated movements, researchers may study whether early preferences are forming.","zh":"如果胎兒顯示重複動作，研究人員可能研究早期偏好是否正在形成。"},{"en":"This word refers to babies before they are born.","zh":"這個詞指尚未出生的嬰兒。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":4},{"front":"have a preference as to","meaning":"對……有偏好","examples":[{"en":"Fetuses have a preference as to which thumb they suck.","zh":"胎兒對吮吸哪隻拇指有偏好。"},{"en":"To have a preference as to something means to favour one option over another.","zh":"have a preference as to something 指在幾個選項之間較偏好其中一個。"},{"en":"A student may have a preference as to where they sit in class.","zh":"學生可能對坐在課室哪個位置有偏好。"},{"en":"If a baby has a preference before birth, later behaviour may not be entirely learned after birth.","zh":"如果嬰兒在出生前已有偏好，日後行為可能不完全是在出生後學習的。"},{"en":"This phrase is a formal way to describe choosing between options.","zh":"這個片語是描述選項偏好的較正式說法。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":5},{"front":"suck their thumb","meaning":"吮吸拇指","examples":[{"en":"Some fetuses prefer to suck one thumb rather than the other.","zh":"有些胎兒較喜歡吮吸其中一隻拇指，而不是另一隻。"},{"en":"To suck their thumb means to put a thumb in the mouth and draw on it, often for comfort.","zh":"suck their thumb 指把拇指放入口中吸吮，常用來安撫自己。"},{"en":"A baby may suck their thumb when tired or sleepy.","zh":"嬰兒疲倦或想睡時可能吮吸拇指。"},{"en":"If a fetus repeatedly sucks one thumb, researchers may see an early side preference.","zh":"如果胎兒反覆吮吸某一隻拇指，研究人員可能看到早期側向偏好。"},{"en":"This phrase describes a common early child behaviour.","zh":"這個片語描述常見的早期兒童行為。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":5},{"front":"in most cases","meaning":"在大多數情況下","examples":[{"en":"In most cases, the preference continued after birth.","zh":"在大多數情況下，這種偏好在出生後持續。"},{"en":"In most cases means usually or in the majority of situations.","zh":"in most cases 指通常或在大部分情況中。"},{"en":"In most cases, students improve when they practise a skill every day.","zh":"在大多數情況下，學生每天練習技能就會進步。"},{"en":"If something happens in most cases, there may still be exceptions.","zh":"如果某事在大多數情況下發生，仍可能有例外。"},{"en":"This phrase describes a general pattern, not an absolute rule.","zh":"這個片語描述一般模式，而不是絕對規則。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":5},{"front":"continue after birth","meaning":"出生後持續","examples":[{"en":"The thumb preference often continued after birth.","zh":"拇指偏好常在出生後持續。"},{"en":"To continue after birth means to remain present once the baby has been born.","zh":"continue after birth 指嬰兒出生後仍然存在。"},{"en":"Some sleep patterns that begin before birth may continue after birth for a short time.","zh":"一些出生前開始的睡眠模式可能在出生後短時間持續。"},{"en":"If a preference continues after birth, it may be linked to earlier development.","zh":"如果某種偏好在出生後持續，它可能與較早發育有關。"},{"en":"This phrase connects prenatal behaviour with later infancy.","zh":"這個片語把產前行為與後來嬰兒期連接起來。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":5},{"front":"have control over","meaning":"控制……","examples":[{"en":"At 15 weeks, the brain does not yet have control over the body’s limbs.","zh":"在15週時，大腦尚未控制身體四肢。"},{"en":"To have control over something means to be able to direct or manage it.","zh":"have control over something 指能夠指揮或管理某事物。"},{"en":"A young child may not yet have full control over a pencil when learning to write.","zh":"幼兒學寫字時，可能尚未完全控制鉛筆。"},{"en":"If the brain does not control the limbs yet, early movement may come from other developmental processes.","zh":"如果大腦尚未控制四肢，早期動作可能來自其他發育過程。"},{"en":"This phrase describes the ability to guide action.","zh":"這個片語描述引導行動的能力。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":5},{"front":"body’s limbs","meaning":"身體四肢","examples":[{"en":"The fetal brain does not yet control the body’s limbs.","zh":"胎兒大腦尚未控制身體四肢。"},{"en":"The body’s limbs are the arms and legs, or similar body parts used for movement.","zh":"body’s limbs 指手臂和腿，或用於移動的類似身體部位。"},{"en":"A doctor checks a baby’s limbs to see whether movement is developing normally.","zh":"醫生檢查嬰兒四肢，以了解動作是否正常發展。"},{"en":"If the body’s limbs develop at different speeds, early movement patterns may differ.","zh":"如果身體四肢發育速度不同，早期動作模式可能不同。"},{"en":"This phrase refers to the main moving parts of the body.","zh":"這個片語指身體主要的活動部位。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":5},{"front":"speculate that","meaning":"推測","examples":[{"en":"Hepper speculates that fetuses prefer the side developing more quickly.","zh":"Hepper 推測胎兒偏好發育得較快的一側。"},{"en":"To speculate that means to suggest a possible explanation without having complete proof.","zh":"speculate that 指在沒有完整證明下提出可能解釋。"},{"en":"A teacher may speculate that low attendance caused weaker test results.","zh":"老師可能推測出席率低導致測驗成績較弱。"},{"en":"If evidence is suggestive but incomplete, researchers may speculate carefully.","zh":"如果證據有暗示但不完整，研究人員可能謹慎推測。"},{"en":"This phrase signals an educated guess rather than certainty.","zh":"這個片語表示有根據的猜測，而不是確定。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":5},{"front":"tend to prefer","meaning":"傾向於偏好","examples":[{"en":"Fetuses tend to prefer whichever side of the body develops faster.","zh":"胎兒傾向於偏好身體發育較快的一側。"},{"en":"To tend to prefer something means to usually favour it, though not always.","zh":"tend to prefer something 指通常較喜歡某事，但不是永遠如此。"},{"en":"Some students tend to prefer quiet study spaces to noisy cafés.","zh":"有些學生傾向於偏好安靜溫習空間，而不是嘈吵咖啡店。"},{"en":"If one option feels easier, people tend to prefer it over a harder one.","zh":"如果某選項感覺較容易，人們傾向於偏好它而不是較難的選項。"},{"en":"This phrase describes a common but not universal pattern.","zh":"這個片語描述常見但非普遍的模式。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":5},{"front":"whichever side of the body","meaning":"身體任何一側","examples":[{"en":"The fetus may prefer whichever side of the body is developing more quickly.","zh":"胎兒可能偏好身體發育較快的任何一側。"},{"en":"Whichever side of the body means any side, left or right, depending on the situation.","zh":"whichever side of the body 指左側或右側其中任何一側，視乎情況而定。"},{"en":"A physiotherapist may strengthen whichever side of the body is weaker after an injury.","zh":"物理治療師可能強化受傷後較弱的身體任何一側。"},{"en":"If one side develops faster, early movement may favour that side.","zh":"如果其中一側發育較快，早期動作可能偏向該側。"},{"en":"This phrase leaves the exact side open until evidence identifies it.","zh":"這個片語在證據指出前不限定具體是哪一側。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":5},{"front":"developing more quickly","meaning":"發育得更快","examples":[{"en":"One side of the fetus’s body may be developing more quickly.","zh":"胎兒身體其中一側可能發育得更快。"},{"en":"Developing more quickly means growing or becoming mature faster than another part.","zh":"developing more quickly 指比另一部分更快成長或成熟。"},{"en":"A child’s reading ability may be developing more quickly than their handwriting.","zh":"孩子的閱讀能力可能比書寫能力發展得更快。"},{"en":"If one body side develops faster, movement preference may appear before birth.","zh":"如果身體一側發育得更快，動作偏好可能在出生前出現。"},{"en":"This phrase describes unequal speed in growth or development.","zh":"這個片語描述成長或發展速度不一。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":5},{"front":"in turn","meaning":"繼而","examples":[{"en":"Their movements, in turn, may influence brain development.","zh":"牠們的動作繼而可能影響大腦發育。"},{"en":"In turn means as the next step in a chain of cause and effect.","zh":"in turn 指作為因果鏈中的下一步。"},{"en":"Good sleep improves concentration; concentration, in turn, improves learning.","zh":"良好睡眠改善專注；專注繼而改善學習。"},{"en":"If body movement affects brain development, early actions may create later differences.","zh":"如果身體動作影響大腦發育，早期行動可能造成後來差異。"},{"en":"This phrase links one result to the next result.","zh":"這個片語把一個結果連接到下一個結果。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":5},{"front":"influence the brain’s development","meaning":"影響大腦發育","examples":[{"en":"Fetal movements may influence the brain’s development.","zh":"胎兒動作可能影響大腦發育。"},{"en":"To influence the brain’s development means to affect how the brain grows or organises itself.","zh":"influence the brain’s development 指影響大腦如何成長或組織。"},{"en":"Early language exposure can influence a child’s brain development.","zh":"早期語言接觸可以影響孩子的大腦發育。"},{"en":"If repeated movement affects the brain, the body and brain may shape each other.","zh":"如果重複動作影響大腦，身體和大腦可能互相塑造。"},{"en":"This phrase describes an effect on how the brain develops over time.","zh":"這個片語描述對大腦長期發展方式的影響。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":6},{"front":"early preference","meaning":"早期偏好","examples":[{"en":"This early preference may not last throughout childhood.","zh":"這種早期偏好可能不會在整個童年持續。"},{"en":"An early preference is a choice or tendency that appears at an early stage of life or development.","zh":"early preference 是在生命或發展早期出現的選擇或傾向。"},{"en":"A toddler may show an early preference for drawing before learning to write properly.","zh":"幼兒在真正學會寫字前，可能顯示對畫畫的早期偏好。"},{"en":"If an early preference changes later, it may not predict final behaviour.","zh":"如果早期偏好後來改變，它未必能預測最終行為。"},{"en":"This phrase describes a tendency that appears before it is fully settled.","zh":"這個片語描述在完全固定前已出現的傾向。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":6},{"front":"be temporary","meaning":"是暫時的","examples":[{"en":"It is unknown whether this early preference is temporary.","zh":"目前未知這種早期偏好是否暫時。"},{"en":"To be temporary means to last for only a short time and not become permanent.","zh":"be temporary 指只持續短時間，而不會成為永久。"},{"en":"A student’s tiredness may be temporary after a busy exam week.","zh":"學生在繁忙考試週後的疲倦可能是暫時的。"},{"en":"If a child’s hand preference is temporary, it may change as the child grows.","zh":"如果孩子的用手偏好是暫時的，它可能隨成長而改變。"},{"en":"This phrase contrasts short-term states with lasting ones.","zh":"這個片語把短期狀態與持久狀態作對比。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":6},{"front":"hold up throughout development","meaning":"在整個發展過程中維持","examples":[{"en":"Researchers do not know whether early preference holds up throughout development.","zh":"研究人員不知道早期偏好是否會在整個發展過程中維持。"},{"en":"To hold up throughout development means to remain true or stable during the whole process of growth.","zh":"hold up throughout development 指在整個成長過程中仍然成立或穩定。"},{"en":"A child’s early interest in music may or may not hold up throughout development.","zh":"孩子早期對音樂的興趣未必會在整個發展過程中維持。"},{"en":"If an early pattern holds up, it can help predict later behaviour.","zh":"如果早期模式能維持，它可以幫助預測後來行為。"},{"en":"This phrase asks whether something lasts as a person grows.","zh":"這個片語詢問某事是否在人成長期間持續。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":6},{"front":"infancy","meaning":"嬰兒期","examples":[{"en":"Hand preference may change during infancy.","zh":"慣用手偏好可能在嬰兒期改變。"},{"en":"Infancy is the earliest period of life when a person is a baby.","zh":"infancy 是人生最早的嬰兒時期。"},{"en":"During infancy, children learn to roll, crawl, reach, and recognise familiar voices.","zh":"在嬰兒期，孩子學會翻身、爬行、伸手和辨認熟悉聲音。"},{"en":"If hand preference changes during infancy, it may not be fixed before birth.","zh":"如果用手偏好在嬰兒期改變，它可能不是出生前已固定。"},{"en":"This word refers to babyhood.","zh":"這個詞指嬰兒階段。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":6},{"front":"genetic predetermination","meaning":"遺傳預定論","examples":[{"en":"Genetic predetermination is contradicted by children’s late hand preference.","zh":"遺傳預定論與兒童較晚形成用手偏好相矛盾。"},{"en":"Genetic predetermination is the idea that genes decide an outcome before development is complete.","zh":"genetic predetermination 是認為基因在發育完成前已決定某結果的想法。"},{"en":"A belief in genetic predetermination may ignore the role of practice, environment, and experience.","zh":"相信遺傳預定論可能忽視練習、環境和經驗的作用。"},{"en":"If children settle on a hand only later, strict genetic predetermination becomes less convincing.","zh":"如果兒童較晚才固定使用某手，嚴格的遺傳預定論就較不令人信服。"},{"en":"This phrase refers to the claim that genes decide something in advance.","zh":"這個片語指基因預先決定某事的主張。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":6},{"front":"be contradicted by","meaning":"與……相矛盾","examples":[{"en":"The theory is contradicted by observations of young children.","zh":"這個理論與對幼兒的觀察相矛盾。"},{"en":"To be contradicted by something means to be opposed or disproved by it.","zh":"be contradicted by something 指被某事反駁或證明不一致。"},{"en":"A student’s excuse may be contradicted by the attendance record.","zh":"學生的藉口可能與出席記錄相矛盾。"},{"en":"If a theory predicts early certainty but children change later, the theory is contradicted.","zh":"如果理論預測早期已確定，但孩子後來改變，該理論就被反駁。"},{"en":"This phrase shows that evidence says the opposite of a claim.","zh":"這個片語顯示證據說出的內容與主張相反。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":6},{"front":"widespread observation","meaning":"廣泛觀察","examples":[{"en":"A widespread observation is that children settle on a hand only later.","zh":"一個廣泛觀察是，兒童只在較後時間才固定使用某一隻手。"},{"en":"A widespread observation is something noticed by many people or in many cases.","zh":"widespread observation 是許多人或許多個案中都注意到的事情。"},{"en":"A widespread observation among teachers is that tired students make more careless mistakes.","zh":"老師之間的一個廣泛觀察是，疲倦學生會犯更多粗心錯誤。"},{"en":"If many parents notice the same pattern, it may become important evidence.","zh":"如果許多父母注意到同一模式，它可能成為重要證據。"},{"en":"This phrase describes a commonly noticed fact.","zh":"這個片語描述普遍被注意到的事實。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":6},{"front":"settle on","meaning":"選定；固定使用","examples":[{"en":"Children do not settle on either hand until they are older.","zh":"兒童要到較大時才會選定其中一隻手。"},{"en":"To settle on something means to finally choose it after a period of uncertainty.","zh":"settle on something 指在一段不確定後最終選擇某物。"},{"en":"A student may settle on a university after comparing location, cost, and courses.","zh":"學生比較地點、費用和課程後，可能最終選定一所大學。"},{"en":"If children do not settle on one hand early, their preference may still be developing.","zh":"如果兒童早期尚未固定使用某一隻手，其偏好可能仍在發展。"},{"en":"This phrase describes reaching a final choice.","zh":"這個片語描述作出最終選擇。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":6},{"front":"either their right or left hand","meaning":"右手或左手其中一隻","examples":[{"en":"Children may not settle on either their right or left hand until age two or three.","zh":"兒童可能到兩三歲才固定使用右手或左手其中一隻。"},{"en":"Either their right or left hand means one of the two hands, right or left.","zh":"either their right or left hand 指右手或左手之中的其中一隻。"},{"en":"A toddler may use either their right or left hand when reaching for toys.","zh":"幼兒伸手拿玩具時，可能使用右手或左手其中一隻。"},{"en":"If a child switches between hands, adults should avoid rushing the final preference.","zh":"如果孩子在兩隻手之間轉換，成人不應急於迫使最終偏好。"},{"en":"This phrase presents two possible hand choices.","zh":"這個片語呈現兩種可能的用手選擇。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":6},{"front":"even if","meaning":"即使","examples":[{"en":"Even if the correlations were true, they did not explain the cause.","zh":"即使這些相關性是真的，它們也沒有解釋原因。"},{"en":"Even if means although something may be true.","zh":"even if 指即使某事可能是真的。"},{"en":"Even if a student memorises many words, they still need practice using them in sentences.","zh":"即使學生記住很多生字，仍需要練習在句子中使用它們。"},{"en":"If a connection exists, it does not automatically prove what caused it.","zh":"如果關聯存在，也不會自動證明是甚麼造成它。"},{"en":"This phrase introduces a contrast or limitation.","zh":"這個片語引入對比或限制。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":6},{"front":"correlations","meaning":"相關性","examples":[{"en":"The correlations did not fully explain left-handedness.","zh":"這些相關性未能完全解釋左撇子傾向。"},{"en":"Correlations are relationships where two things appear to change together.","zh":"correlations 是兩件事看似一起變化的關係。"},{"en":"There may be a correlation between sleep and exam performance.","zh":"睡眠和考試表現之間可能有相關性。"},{"en":"A correlation can suggest a link, but it does not always prove cause and effect.","zh":"相關性可以暗示連繫，但不一定證明因果。"},{"en":"This word is important when discussing evidence carefully.","zh":"討論證據時，這個詞很重要。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":7},{"front":"what actually causes","meaning":"究竟是甚麼導致","examples":[{"en":"The studies did not explain what actually causes left-handedness.","zh":"這些研究沒有解釋究竟是甚麼導致左撇子傾向。"},{"en":"What actually causes something asks for the real reason behind it.","zh":"what actually causes something 詢問某事背後的真正原因。"},{"en":"Teachers may ask what actually causes students to stop reading, not just why scores are low.","zh":"老師可能問究竟是甚麼導致學生停止閱讀，而不只是問為何分數低。"},{"en":"If studies show a pattern but not the cause, more research is needed.","zh":"如果研究顯示模式但沒有顯示原因，就需要更多研究。"},{"en":"This phrase focuses on the true cause, not only the visible connection.","zh":"這個片語聚焦於真正原因，而不只是表面連繫。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":7},{"front":"left-handedness","meaning":"左撇子傾向","examples":[{"en":"Left-handedness may have several causes.","zh":"左撇子傾向可能有幾種成因。"},{"en":"Left-handedness is the tendency to use the left hand more naturally than the right hand.","zh":"left-handedness 是比起右手更自然地使用左手的傾向。"},{"en":"Left-handedness can affect how a child writes, cuts paper, or plays certain sports.","zh":"左撇子傾向可以影響孩子如何寫字、剪紙或玩某些運動。"},{"en":"If left-handedness has many causes, no single explanation will be enough.","zh":"如果左撇子傾向有很多成因，單一解釋就不夠。"},{"en":"This word names the condition or tendency of being left-handed.","zh":"這個詞指出慣用左手這種情況或傾向。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":7},{"front":"furthermore","meaning":"此外","examples":[{"en":"Furthermore, side preference is common among animals.","zh":"此外，側向偏好在動物中很常見。"},{"en":"Furthermore means in addition to what has just been said.","zh":"furthermore 指除了剛才所說之外。"},{"en":"The school library is quiet; furthermore, it stays open after lessons.","zh":"學校圖書館很安靜；此外，它放學後仍開放。"},{"en":"If a writer uses furthermore, they are adding another supporting point.","zh":"如果作者使用 furthermore，就是在加入另一個支持點。"},{"en":"This word helps build an argument by adding extra evidence.","zh":"這個詞透過加入額外證據來建立論點。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":7},{"front":"specialization on either side of the body","meaning":"身體某一側的專門化","examples":[{"en":"Specialization on either side of the body is common among animals.","zh":"身體某一側的專門化在動物中很常見。"},{"en":"Specialization on either side of the body means one side becomes better suited for a particular action.","zh":"specialization on either side of the body 指身體其中一側更適合某種特定動作。"},{"en":"A cat may use one paw more often when reaching under furniture.","zh":"貓伸爪到家具下方時，可能更常使用其中一隻爪。"},{"en":"If one side becomes specialised, the animal may perform repeated actions more efficiently.","zh":"如果其中一側變得專門化，動物可能更有效率地執行重複動作。"},{"en":"This phrase describes side-based skill development.","zh":"這個片語描述基於身體側面的技能發展。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":7},{"front":"common among animals","meaning":"在動物中常見","examples":[{"en":"Side preference is common among animals.","zh":"側向偏好在動物中常見。"},{"en":"Common among animals means found in many animal species.","zh":"common among animals 指在許多動物物種中都可見。"},{"en":"Tool use is less common among animals than simple side preference.","zh":"使用工具比簡單的側向偏好較少在動物中常見。"},{"en":"If a behaviour is common among animals, it may have an evolutionary advantage.","zh":"如果某行為在動物中常見，它可能有進化優勢。"},{"en":"This phrase shows that something is not limited to humans.","zh":"這個片語顯示某事不限於人類。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":7},{"front":"favor one paw over another","meaning":"較偏好某一隻爪","examples":[{"en":"Cats may favor one paw over another.","zh":"貓可能較偏好某一隻爪。"},{"en":"To favor one paw over another means to use one paw more often or more comfortably than the other.","zh":"favor one paw over another 指比另一隻爪更常或更舒服地使用某一隻爪。"},{"en":"A cat may favor one paw when pulling a toy from under a sofa.","zh":"貓從梳化底下拉玩具時，可能較偏好某一隻爪。"},{"en":"If an animal favours one paw, repeated practice may make that paw more skilled.","zh":"如果動物偏好某一隻爪，反覆練習可能令那隻爪更熟練。"},{"en":"This phrase describes animal side preference.","zh":"這個片語描述動物的側向偏好。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":7},{"front":"fish toys out from","meaning":"從……撈出","examples":[{"en":"Cats use one paw when fishing toys out from under the couch.","zh":"貓從梳化底下撈出玩具時會使用一隻爪。"},{"en":"To fish something out from somewhere means to pull or get it out with careful effort.","zh":"fish something out from somewhere 指小心費力地把某物從某處取出。"},{"en":"A student may fish a pencil out from the bottom of a school bag.","zh":"學生可能從書包底部撈出一支鉛筆。"},{"en":"If an object is stuck under furniture, someone may need to reach in and pull it out slowly.","zh":"如果物件卡在家具下面，有人可能需要伸手進去慢慢拉出來。"},{"en":"This phrase describes retrieving something from a difficult place.","zh":"這個片語描述從困難位置取回某物。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":7},{"front":"stomp more frequently with","meaning":"較常用……跺腳","examples":[{"en":"Horses stomp more frequently with one hoof than the other.","zh":"馬較常用其中一隻蹄跺腳。"},{"en":"To stomp more frequently with one hoof means to strike the ground more often with that hoof.","zh":"stomp more frequently with one hoof 指更常用某一隻蹄踏擊地面。"},{"en":"A horse may stomp with one hoof to shake off flies.","zh":"馬可能用一隻蹄跺腳來趕走蒼蠅。"},{"en":"If an animal uses one limb more often, that side may show a natural preference.","zh":"如果動物更常使用某一肢體，該側可能顯示自然偏好。"},{"en":"This phrase describes repeated movement with one specific limb.","zh":"這個片語描述用特定肢體反覆動作。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":7},{"front":"gesture predominantly with","meaning":"主要用……做手勢","examples":[{"en":"Certain crabs gesture predominantly with one claw.","zh":"某些蟹主要用其中一隻螯做手勢。"},{"en":"To gesture predominantly with one claw means to use one claw mainly when signalling or moving expressively.","zh":"gesture predominantly with one claw 指主要使用某一隻螯來傳遞訊號或作表達性動作。"},{"en":"A speaker may gesture mostly with one hand during a presentation.","zh":"演講者在匯報時可能主要用一隻手做手勢。"},{"en":"If a crab uses one claw more for display, that claw may be more important for communication.","zh":"如果蟹更常用一隻螯作展示，那隻螯可能對溝通更重要。"},{"en":"This phrase describes a main limb used for signalling.","zh":"這個片語描述用於傳遞訊號的主要肢體。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":7},{"front":"in evolutionary terms","meaning":"從進化角度來看","examples":[{"en":"In evolutionary terms, focusing dexterity in one limb is efficient.","zh":"從進化角度來看，把靈巧集中於一隻肢體是有效率的。"},{"en":"In evolutionary terms means when considered from the viewpoint of survival and long-term biological change.","zh":"in evolutionary terms 指從生存和長期生物變化的角度來考慮。"},{"en":"In evolutionary terms, fear can be useful because it helps animals avoid danger.","zh":"從進化角度來看，恐懼可能有用，因為它幫助動物避開危險。"},{"en":"If one-sided skill saves energy or improves performance, it may be favoured over time.","zh":"如果單側技能節省能量或改善表現，它可能隨時間被保留。"},{"en":"This phrase frames an explanation through evolution.","zh":"這個片語透過進化來框定解釋。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":7},{"front":"focus power and dexterity in","meaning":"將力量和靈巧集中於……","examples":[{"en":"Animals may focus power and dexterity in one limb.","zh":"動物可能將力量和靈巧集中於一隻肢體。"},{"en":"To focus power and dexterity in one limb means to concentrate strength and skill in that limb.","zh":"focus power and dexterity in one limb 指把力量和技巧集中在那隻肢體上。"},{"en":"A tennis player may develop more power and dexterity in the arm used for serving.","zh":"網球員可能在用來發球的手臂上發展更多力量和靈巧。"},{"en":"If practice is concentrated in one limb, that limb can become more skilled than the others.","zh":"如果練習集中在一隻肢體上，那隻肢體可能比其他肢體更熟練。"},{"en":"This phrase explains why one side may become especially capable.","zh":"這個片語解釋為何一側可能變得特別有能力。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":8},{"front":"one limb","meaning":"一隻肢體","examples":[{"en":"It may be efficient to train one limb more than others.","zh":"較多訓練一隻肢體可能更有效率。"},{"en":"One limb means one arm, leg, paw, claw, or similar body part used for movement.","zh":"one limb 指一隻手臂、腿、爪、螯或類似活動身體部位。"},{"en":"A dog may favour one limb after another limb is injured.","zh":"狗在另一隻肢體受傷後，可能偏用其中一隻肢體。"},{"en":"If one limb is used repeatedly, it may become stronger or more coordinated.","zh":"如果一隻肢體被反覆使用，它可能變得更強或更協調。"},{"en":"This phrase refers to a single moving body part.","zh":"這個片語指單一活動身體部位。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":8},{"front":"more efficient than","meaning":"比……更有效率","examples":[{"en":"Training one limb is more efficient than training all limbs equally.","zh":"訓練一隻肢體比平均訓練所有肢體更有效率。"},{"en":"More efficient than means using less time, energy, or effort than another method.","zh":"more efficient than 指比另一方法使用更少時間、能量或努力。"},{"en":"Planning before writing is more efficient than rewriting the whole essay many times.","zh":"寫作前先規劃，比多次重寫整篇文章更有效率。"},{"en":"If one method saves energy and produces good results, it may be more efficient.","zh":"如果一種方法節省能量並產生好結果，它可能更有效率。"},{"en":"This phrase compares effectiveness in using resources.","zh":"這個片語比較資源使用上的效果。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":8},{"front":"train two limbs equally","meaning":"平均訓練兩隻肢體","examples":[{"en":"It is less efficient to train two or more limbs equally.","zh":"平均訓練兩隻或更多肢體效率較低。"},{"en":"To train two limbs equally means to practise both limbs to the same level.","zh":"train two limbs equally 指把兩隻肢體練到相同水平。"},{"en":"A boxer may train both arms, but one arm may still become naturally stronger.","zh":"拳擊手可能訓練雙臂，但其中一臂仍可能自然較強。"},{"en":"If every limb is trained equally, the body may use more energy than focusing on one main limb.","zh":"如果每隻肢體都平均訓練，身體可能比集中訓練一隻主要肢體使用更多能量。"},{"en":"This phrase describes balanced training across body parts.","zh":"這個片語描述不同身體部位之間的均衡訓練。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":8},{"front":"seemingly random","meaning":"看似隨機","examples":[{"en":"For most animals, the preference for one side is seemingly random.","zh":"對大多數動物來說，對某一側的偏好看似隨機。"},{"en":"Seemingly random means appearing to happen without a clear pattern or reason.","zh":"seemingly random 指看起來沒有清楚模式或原因。"},{"en":"A teacher may see seemingly random mistakes in a student’s spelling before noticing a hidden pattern.","zh":"老師可能先看到學生拼字中看似隨機的錯誤，後來才注意到隱藏模式。"},{"en":"If animal side preference is seemingly random, it may not strongly favour left or right across the species.","zh":"如果動物的側向偏好看似隨機，整個物種可能不會強烈偏向左或右。"},{"en":"This phrase describes something that looks unpredictable.","zh":"這個片語描述看起來不可預測的事情。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":8},{"front":"overwhelming dominance","meaning":"壓倒性的主導","examples":[{"en":"The overwhelming dominance of the right hand is associated only with humans.","zh":"右手的壓倒性主導只與人類有關。"},{"en":"Overwhelming dominance means one option is much stronger or more common than all others.","zh":"overwhelming dominance 指一個選項遠比其他選項更強或更常見。"},{"en":"One shop may have overwhelming dominance in a town if nearly everyone buys from it.","zh":"如果鎮上幾乎所有人都在某店購物，那間店可能有壓倒性的主導地位。"},{"en":"If right-hand use is overwhelmingly dominant in humans, researchers ask why humans are different.","zh":"如果右手使用在人類中佔壓倒性主導，研究人員會問為何人類不同。"},{"en":"This phrase describes a very strong majority pattern.","zh":"這個片語描述非常強的多數模式。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":8},{"front":"be associated only with","meaning":"只與……有關","examples":[{"en":"Right-hand dominance is associated only with humans.","zh":"右手主導只與人類有關。"},{"en":"To be associated only with something means to be linked specifically to that thing and not others.","zh":"be associated only with something 指專門與某事相關，而不與其他事相關。"},{"en":"A school uniform colour may be associated only with one particular school.","zh":"某種校服顏色可能只與一所特定學校有關。"},{"en":"If a trait is associated only with humans, it may reveal something unusual about human evolution.","zh":"如果某特徵只與人類有關，它可能揭示人類進化中的特殊之處。"},{"en":"This phrase limits a connection to one group.","zh":"這個片語把某種連繫限制於一個群體。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":8},{"front":"direct attention toward","meaning":"將注意力引向……","examples":[{"en":"This fact directs attention toward the brain’s hemispheres.","zh":"這個事實將注意力引向大腦兩個半球。"},{"en":"To direct attention toward something means to make people focus on it.","zh":"direct attention toward something 指令人們把注意力集中到某事上。"},{"en":"A sudden drop in grades may direct attention toward sleep, stress, or teaching methods.","zh":"成績突然下降可能將注意力引向睡眠、壓力或教學方法。"},{"en":"If one clue stands out, it can direct researchers toward a new explanation.","zh":"如果一條線索特別突出，它可以把研究人員引向新解釋。"},{"en":"This phrase describes shifting focus to a likely area of importance.","zh":"這個片語描述把焦點轉到可能重要的範圍。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":8},{"front":"brain’s two hemispheres","meaning":"大腦兩個半球","examples":[{"en":"Handedness may be linked to the brain’s two hemispheres.","zh":"慣用手傾向可能與大腦兩個半球有關。"},{"en":"The brain’s two hemispheres are the left and right halves of the brain.","zh":"brain’s two hemispheres 是大腦的左半球和右半球。"},{"en":"Doctors may study the brain’s two hemispheres to understand speech, movement, and perception.","zh":"醫生可能研究大腦兩個半球，以理解說話、動作和感知。"},{"en":"If the hemispheres control different functions, damage to each side may produce different effects.","zh":"如果兩個半球控制不同功能，每側受損可能產生不同影響。"},{"en":"This phrase refers to the brain’s major left-right division.","zh":"這個片語指大腦主要的左右分區。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":8},{"front":"date back to","meaning":"可追溯至","examples":[{"en":"Interest in hemispheres dates back to at least 1836.","zh":"對大腦半球的興趣至少可追溯至1836年。"},{"en":"To date back to a time means to have existed since that time.","zh":"date back to a time 指自某時期起已存在。"},{"en":"A school tradition may date back to the first headmaster.","zh":"學校傳統可能可追溯至第一任校長。"},{"en":"If an idea dates back nearly two centuries, it has a long research history.","zh":"如果一個想法可追溯近兩個世紀，它就有悠久研究歷史。"},{"en":"This phrase gives the historical origin of something.","zh":"這個片語給出某事的歷史起源。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":8},{"front":"medical conference","meaning":"醫學會議","examples":[{"en":"Marc Dax reported his findings at a medical conference.","zh":"Marc Dax 在一場醫學會議上報告他的發現。"},{"en":"A medical conference is a professional meeting where doctors and researchers discuss health-related findings.","zh":"medical conference 是醫生和研究人員討論健康相關發現的專業會議。"},{"en":"Doctors may attend a medical conference to learn about new treatments.","zh":"醫生可能參加醫學會議，以了解新治療方法。"},{"en":"If findings are presented at a conference, other experts can question and evaluate them.","zh":"如果研究發現在會議上呈現，其他專家可以質疑和評估它們。"},{"en":"This phrase describes a formal gathering in medicine.","zh":"這個片語描述醫學領域中的正式聚會。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":8},{"front":"French physician","meaning":"法國醫生","examples":[{"en":"Marc Dax was a French physician.","zh":"Marc Dax 是一名法國醫生。"},{"en":"A French physician is a doctor from France.","zh":"French physician 是來自法國的醫生。"},{"en":"A physician may examine patients, diagnose illness, and record unusual symptoms.","zh":"醫生可能檢查病人、診斷疾病並記錄不尋常症狀。"},{"en":"If a physician notices the same pattern in many patients, it may become an important medical clue.","zh":"如果醫生在許多病人身上注意到同一模式，它可能成為重要醫學線索。"},{"en":"This phrase identifies a doctor by nationality.","zh":"這個片語以國籍指出一名醫生。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":9},{"front":"report on","meaning":"報告關於……","examples":[{"en":"Dax reported on an unusual commonality among his patients.","zh":"Dax 報告關於病人之間一個不尋常共同點。"},{"en":"To report on something means to describe or present information about it.","zh":"report on something 指描述或呈現關於某事的資料。"},{"en":"A student may report on a science experiment in front of the class.","zh":"學生可能在班前報告關於一項科學實驗。"},{"en":"If a doctor reports on patient patterns, others can compare them with their own cases.","zh":"如果醫生報告病人模式，其他人可以把它們與自己的個案比較。"},{"en":"This phrase describes formally giving information about a topic.","zh":"這個片語描述正式提供某主題的資料。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":9},{"front":"unusual commonality","meaning":"不尋常的共同點","examples":[{"en":"Dax noticed an unusual commonality among his patients.","zh":"Dax 注意到病人之間一個不尋常的共同點。"},{"en":"An unusual commonality is a shared feature that is surprising or unexpected.","zh":"unusual commonality 是令人意外或不尋常的共同特徵。"},{"en":"A teacher may notice an unusual commonality when many absent students sit near the same window.","zh":"如果許多缺席學生都坐在同一窗邊附近，老師可能注意到不尋常的共同點。"},{"en":"If several patients share the same brain injury and speech problem, the pattern may matter.","zh":"如果幾位病人都有相同腦傷和語言問題，這個模式可能很重要。"},{"en":"This phrase describes a surprising shared feature.","zh":"這個片語描述令人意外的共同特徵。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":9},{"front":"country doctor","meaning":"鄉郊醫生","examples":[{"en":"Dax worked for many years as a country doctor.","zh":"Dax 多年來擔任鄉郊醫生。"},{"en":"A country doctor is a doctor who serves people in rural areas or small towns.","zh":"country doctor 是為鄉郊地區或小鎮居民服務的醫生。"},{"en":"A country doctor may know families for decades and treat many everyday illnesses.","zh":"鄉郊醫生可能認識幾代家庭，並治療許多日常疾病。"},{"en":"If a country doctor sees many patients over time, repeated patterns may become noticeable.","zh":"如果鄉郊醫生長期看很多病人，反覆模式可能變得明顯。"},{"en":"This phrase describes a doctor working outside major cities.","zh":"這個片語描述在大城市以外工作的醫生。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":9},{"front":"encounter","meaning":"遇到","examples":[{"en":"Dax encountered many patients with speech difficulties.","zh":"Dax 遇到許多有說話困難的病人。"},{"en":"To encounter someone or something means to meet or come across them, often unexpectedly.","zh":"encounter someone or something 指遇見或碰到某人或某事，常帶有意外意味。"},{"en":"A teacher may encounter the same grammar error in many students’ essays.","zh":"老師可能在許多學生文章中遇到同一文法錯誤。"},{"en":"If a doctor encounters repeated symptoms, they may begin to look for a common cause.","zh":"如果醫生反覆遇到相同症狀，可能開始尋找共同原因。"},{"en":"This word describes coming across a person, problem, or situation.","zh":"這個詞描述碰到人、問題或情況。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":9},{"front":"speech was difficult","meaning":"說話有困難","examples":[{"en":"Speech was difficult for patients with left-brain damage.","zh":"左腦受損的病人說話有困難。"},{"en":"Speech was difficult means speaking clearly or producing language was hard.","zh":"speech was difficult 指清楚說話或產生語言很困難。"},{"en":"After a sore throat, speech may be difficult for a few days.","zh":"喉嚨痛後，說話可能有幾天困難。"},{"en":"If brain damage affects language areas, speech can become slow or unclear.","zh":"如果腦部損傷影響語言區，說話可能變慢或不清楚。"},{"en":"This phrase describes trouble with speaking.","zh":"這個片語描述說話方面的困難。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":9},{"front":"brain damage","meaning":"腦部損傷","examples":[{"en":"The patients had speech problems as a result of brain damage.","zh":"這些病人因腦部損傷而有語言問題。"},{"en":"Brain damage is injury to the brain that can affect movement, speech, memory, or thinking.","zh":"brain damage 是大腦受傷，可能影響動作、說話、記憶或思考。"},{"en":"A serious car accident can cause brain damage if the head is badly injured.","zh":"如果頭部嚴重受傷，嚴重車禍可能造成腦部損傷。"},{"en":"If brain damage occurs in a language area, the person may struggle to speak.","zh":"如果腦部損傷發生在語言區，人可能難以說話。"},{"en":"This phrase refers to physical harm to the brain.","zh":"這個片語指對大腦的實體傷害。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":9},{"front":"what was unique was that","meaning":"獨特之處在於","examples":[{"en":"What was unique was that every patient had damage to the left brain.","zh":"獨特之處在於每名病人都有左腦損傷。"},{"en":"What was unique was that introduces the special or unusual part of a situation.","zh":"what was unique was that 用來引入某情況中最特別或不尋常的部分。"},{"en":"What was unique was that every student made the same mistake in a different sentence.","zh":"獨特之處在於每名學生都在不同句子中犯同一錯誤。"},{"en":"If all cases share one unexpected feature, that feature may be the key clue.","zh":"如果所有個案都有一個意外共同特徵，該特徵可能是關鍵線索。"},{"en":"This phrase highlights what makes something different from ordinary cases.","zh":"這個片語突出某事與普通個案不同之處。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":9},{"front":"suffer damage to","meaning":"遭受……損傷","examples":[{"en":"Every individual suffered damage to the left side of the brain.","zh":"每個人都遭受大腦左側損傷。"},{"en":"To suffer damage to something means that part is harmed or injured.","zh":"suffer damage to something 指某部分受到傷害或損傷。"},{"en":"A phone may suffer damage to its screen if it falls onto concrete.","zh":"如果手機跌落混凝土地面，螢幕可能遭受損傷。"},{"en":"If a person suffers damage to a brain area, related abilities may weaken.","zh":"如果人遭受某腦區損傷，相關能力可能變弱。"},{"en":"This phrase describes injury to a specific part.","zh":"這個片語描述對特定部分的傷害。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":9},{"front":"left side of the brain","meaning":"大腦左側","examples":[{"en":"Speech difficulties were linked to damage on the left side of the brain.","zh":"說話困難與大腦左側損傷有關。"},{"en":"The left side of the brain is the left hemisphere, often involved in language functions.","zh":"left side of the brain 是左腦半球，常涉及語言功能。"},{"en":"Doctors may test speech after injury to the left side of the brain.","zh":"醫生可能在大腦左側受傷後測試說話能力。"},{"en":"If the left side of the brain controls speech, damage there can affect communication.","zh":"如果大腦左側控制說話，該處受損便會影響溝通。"},{"en":"This phrase names one half of the brain.","zh":"這個片語指出大腦其中一半。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":9},{"front":"elaborate on","meaning":"詳細闡述","examples":[{"en":"Dax elaborated on his theory at the conference.","zh":"Dax 在會議上詳細闡述他的理論。"},{"en":"To elaborate on something means to explain it in more detail.","zh":"elaborate on something 指更詳細地解釋某事。"},{"en":"A student may elaborate on an answer by giving an example and a reason.","zh":"學生可以透過提供例子和理由來詳細闡述答案。"},{"en":"If an idea is new, the speaker should elaborate so listeners understand it.","zh":"如果一個想法很新，發言者應詳細闡述，讓聽眾理解。"},{"en":"This phrase describes adding detail to an explanation.","zh":"這個片語描述為解釋加入細節。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":9},{"front":"be responsible for","meaning":"負責……","examples":[{"en":"Dax argued that each half of the brain was responsible for certain functions.","zh":"Dax 主張大腦每一半負責某些功能。"},{"en":"To be responsible for something means to control it, cause it, or have the duty of managing it.","zh":"be responsible for something 指控制、造成或有職責管理某事。"},{"en":"A class monitor may be responsible for collecting homework.","zh":"班長可能負責收功課。"},{"en":"If one brain area is responsible for speech, damage there can affect speaking.","zh":"如果某腦區負責說話，該處受損會影響說話。"},{"en":"This phrase links a role, cause, or duty to someone or something.","zh":"這個片語把角色、原因或職責連接到某人或某物。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":10},{"front":"certain functions","meaning":"某些功能","examples":[{"en":"Each half of the brain controls certain functions.","zh":"大腦每一半控制某些功能。"},{"en":"Certain functions means particular jobs or activities performed by a part of the body, machine, or system.","zh":"certain functions 指身體部位、機器或系統執行的特定工作或活動。"},{"en":"A smartphone has certain functions such as calling, messaging, and taking photos.","zh":"智能手機有某些功能，例如打電話、傳訊息和拍照。"},{"en":"If each brain side has certain functions, injury to each side may produce different problems.","zh":"如果大腦每一側有某些功能，每側受傷可能產生不同問題。"},{"en":"This phrase refers to specific roles.","zh":"這個片語指特定角色。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":10},{"front":"controlled speech","meaning":"控制說話","examples":[{"en":"Dax believed the left hemisphere controlled speech.","zh":"Dax 相信左腦半球控制說話。"},{"en":"Controlled speech means managed or directed the ability to produce spoken language.","zh":"controlled speech 指管理或指揮產生口語的能力。"},{"en":"A brain area that controls speech helps people form words and sentences aloud.","zh":"控制說話的腦區幫助人們大聲組成詞語和句子。"},{"en":"If the left hemisphere controls speech, left-brain damage can make speaking difficult.","zh":"如果左腦半球控制說話，左腦受損會令說話困難。"},{"en":"This phrase connects a brain region with spoken language.","zh":"這個片語把腦部區域與口語連接起來。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":10},{"front":"show little interest in","meaning":"對……不太感興趣","examples":[{"en":"Other experts showed little interest in Dax’s ideas.","zh":"其他專家對 Dax 的想法不太感興趣。"},{"en":"To show little interest in something means to pay little attention to it or not care much about it.","zh":"show little interest in something 指很少注意某事或不太關心它。"},{"en":"Students may show little interest in a topic if it feels unrelated to their lives.","zh":"如果學生覺得某主題與生活無關，可能對它不太感興趣。"},{"en":"If experts show little interest in an idea, it may take years before it is tested seriously.","zh":"如果專家對某想法不太感興趣，它可能多年後才被認真測試。"},{"en":"This phrase describes weak attention or enthusiasm.","zh":"這個片語描述注意力或熱情不足。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":10},{"front":"over time","meaning":"隨着時間","examples":[{"en":"Over time, scientists found more evidence for Dax’s theory.","zh":"隨着時間，科學家找到更多支持 Dax 理論的證據。"},{"en":"Over time means gradually as days, years, or generations pass.","zh":"over time 指隨着日子、年份或世代逐漸過去。"},{"en":"A student’s pronunciation improves over time with regular speaking practice.","zh":"學生定期練習說話，發音會隨着時間改善。"},{"en":"If evidence builds over time, an old idea may become more accepted.","zh":"如果證據隨着時間累積，舊想法可能變得更被接受。"},{"en":"This phrase describes gradual change.","zh":"這個片語描述逐漸變化。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":10},{"front":"more and more evidence of","meaning":"越來越多……的證據","examples":[{"en":"Scientists found more and more evidence of speech difficulties after left-brain injury.","zh":"科學家找到越來越多左腦受傷後出現說話困難的證據。"},{"en":"More and more evidence of something means increasing proof or support for it.","zh":"more and more evidence of something 指對某事的證明或支持不斷增加。"},{"en":"Doctors found more and more evidence of stress affecting students’ sleep.","zh":"醫生找到越來越多壓力影響學生睡眠的證據。"},{"en":"If evidence grows, a theory becomes harder to ignore.","zh":"如果證據增加，理論就更難被忽視。"},{"en":"This phrase shows that support is accumulating.","zh":"這個片語顯示支持正在累積。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":10},{"front":"following injury to","meaning":"在……受傷之後","examples":[{"en":"Speech difficulties often followed injury to the left brain.","zh":"說話困難常在左腦受傷之後出現。"},{"en":"Following injury to something means after that part has been damaged.","zh":"following injury to something 指在某部分受損之後。"},{"en":"Following injury to his ankle, the runner stopped training for two months.","zh":"腳踝受傷之後，跑手停止訓練兩個月。"},{"en":"If speech problems follow left-brain injury, the two may be connected.","zh":"如果說話問題在左腦受傷後出現，兩者可能有關。"},{"en":"This phrase describes what happens after damage.","zh":"這個片語描述損傷之後發生的事。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":10},{"front":"display disruptions in","meaning":"顯示……方面的障礙","examples":[{"en":"Patients with right-brain damage displayed disruptions in perception.","zh":"右腦受損的病人顯示感知方面的障礙。"},{"en":"To display disruptions in something means to show problems or disturbances in that ability.","zh":"display disruptions in something 指顯示某能力中的問題或干擾。"},{"en":"A tired student may display disruptions in concentration during a long lesson.","zh":"疲倦學生在長課堂中可能顯示專注力方面的障礙。"},{"en":"If a brain injury disrupts perception, a person may misread space, faces, or visual details.","zh":"如果腦傷干擾感知，人可能誤讀空間、面孔或視覺細節。"},{"en":"This phrase describes visible problems in a function.","zh":"這個片語描述某功能中可見的問題。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":10},{"front":"perception or concentration","meaning":"感知或專注力","examples":[{"en":"Right-hemisphere damage often affected perception or concentration.","zh":"右腦半球受損常影響感知或專注力。"},{"en":"Perception or concentration means the ability to notice and understand information, or to stay focused.","zh":"perception or concentration 指注意和理解資訊的能力，或保持專注的能力。"},{"en":"Lack of sleep can reduce perception or concentration during class.","zh":"睡眠不足可以降低上課時的感知或專注力。"},{"en":"If the right brain affects perception, damage there may change how people interpret the world.","zh":"如果右腦影響感知，該處受損可能改變人們如何詮釋世界。"},{"en":"This phrase names two important mental abilities.","zh":"這個片語指出兩種重要心智能力。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":10},{"front":"major advancements in","meaning":"在……方面的重大進展","examples":[{"en":"Major advancements in understanding brain asymmetry were made in the 1960s.","zh":"在理解大腦不對稱性方面的重大進展出現在1960年代。"},{"en":"Major advancements in something are important improvements in knowledge, technology, or methods.","zh":"major advancements in something 是知識、科技或方法上的重要改善。"},{"en":"Major advancements in medicine can help doctors treat diseases that were once fatal.","zh":"醫學方面的重大進展可以幫助醫生治療曾經致命的疾病。"},{"en":"If new surgery allows better research, it can lead to major advancements in brain science.","zh":"如果新手術讓研究更容易，它可以帶來腦科學方面的重大進展。"},{"en":"This phrase describes significant progress.","zh":"這個片語描述重大進步。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":10},{"front":"brain’s asymmetry","meaning":"大腦的不對稱性","examples":[{"en":"Split-brain surgery improved understanding of the brain’s asymmetry.","zh":"裂腦手術改善了人們對大腦不對稱性的理解。"},{"en":"The brain’s asymmetry means the two sides of the brain are not exactly the same in function or organisation.","zh":"brain’s asymmetry 指大腦兩側在功能或組織上並非完全相同。"},{"en":"Brain asymmetry helps explain why some abilities are stronger on one side than the other.","zh":"大腦不對稱性有助解釋為何某些能力在一側較強。"},{"en":"If the brain’s asymmetry affects language, one hemisphere may handle speech more strongly.","zh":"如果大腦不對稱性影響語言，某個半球可能更強地處理說話。"},{"en":"This phrase describes left-right differences in the brain.","zh":"這個片語描述大腦左右兩側的差異。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":10},{"front":"as a result of","meaning":"由於","examples":[{"en":"Advancements were made as a result of split-brain surgery.","zh":"由於裂腦手術，人們取得了進展。"},{"en":"As a result of means because of something.","zh":"as a result of 指因為某事。"},{"en":"As a result of daily practice, the student became more confident in speaking.","zh":"由於每天練習，學生說話變得更有信心。"},{"en":"If a new method creates better evidence, knowledge may improve as a result.","zh":"如果新方法產生更好證據，知識可能因此改善。"},{"en":"This phrase connects a result with its cause.","zh":"這個片語把結果與原因連接起來。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":11},{"front":"so-called","meaning":"所謂的","examples":[{"en":"So-called split-brain surgery was developed for patients with epilepsy.","zh":"所謂的裂腦手術是為癲癇病人而開發的。"},{"en":"So-called introduces the name people use for something, sometimes with caution or explanation.","zh":"so-called 用來引入人們對某事使用的名稱，有時帶有謹慎或解釋意味。"},{"en":"So-called smart devices can still waste time if people use them badly.","zh":"所謂的智能裝置，如果使用不當，仍可能浪費時間。"},{"en":"If a term is unfamiliar, writers may use so-called before naming it.","zh":"如果術語不熟悉，作者可能在命名前使用 so-called。"},{"en":"This phrase signals that a label is being introduced.","zh":"這個片語表示正在引入一個標籤。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":11},{"front":"split-brain surgery","meaning":"裂腦手術","examples":[{"en":"Split-brain surgery allowed researchers to study each hemisphere separately.","zh":"裂腦手術讓研究人員分開研究每個半球。"},{"en":"Split-brain surgery is an operation that cuts communication between the brain’s two hemispheres.","zh":"split-brain surgery 是切斷大腦兩個半球之間溝通的手術。"},{"en":"Doctors used split-brain surgery to help some patients with severe epilepsy.","zh":"醫生曾使用裂腦手術幫助一些嚴重癲癇病人。"},{"en":"If the hemispheres cannot communicate normally, researchers can observe what each side does alone.","zh":"如果兩個半球不能正常溝通，研究人員便能觀察每一側單獨做甚麼。"},{"en":"This phrase refers to a medical procedure that became important for brain research.","zh":"這個片語指對腦部研究變得重要的醫療程序。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":11},{"front":"be developed to","meaning":"被開發用作……","examples":[{"en":"Split-brain surgery was developed to help patients with epilepsy.","zh":"裂腦手術被開發用作幫助癲癇病人。"},{"en":"To be developed to do something means to be created for that purpose.","zh":"be developed to do something 指為某目的而被創造。"},{"en":"A new app may be developed to help students organise revision.","zh":"新應用程式可能被開發用作幫助學生組織溫習。"},{"en":"If a treatment is developed to solve one problem, it may later help researchers learn something else.","zh":"如果治療方法被開發用來解決一個問題，它後來也可能幫助研究人員學到其他東西。"},{"en":"This phrase explains the original purpose of a method or tool.","zh":"這個片語解釋方法或工具的原本目的。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":11},{"front":"epilepsy","meaning":"癲癇","examples":[{"en":"Split-brain surgery was developed to help patients with epilepsy.","zh":"裂腦手術被開發用作幫助癲癇病人。"},{"en":"Epilepsy is a medical condition that can cause repeated seizures.","zh":"epilepsy 是一種可能造成反覆癲癇發作的醫療狀況。"},{"en":"A person with epilepsy may need medicine, regular sleep, and medical monitoring.","zh":"癲癇患者可能需要藥物、規律睡眠和醫療監察。"},{"en":"If seizures are severe, doctors may consider special treatments.","zh":"如果癲癇發作很嚴重，醫生可能考慮特殊治療。"},{"en":"This word names a neurological condition.","zh":"這個詞指出一種神經系統疾病。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":11},{"front":"during this operation","meaning":"在這項手術期間","examples":[{"en":"During this operation, doctors severed the corpus callosum.","zh":"在這項手術期間，醫生切斷胼胝體。"},{"en":"During this operation means while the surgical procedure was taking place.","zh":"during this operation 指在這項外科程序進行期間。"},{"en":"During this operation, the medical team carefully monitors the patient’s heart and breathing.","zh":"在這項手術期間，醫療團隊仔細監測病人的心跳和呼吸。"},{"en":"If something happens during an operation, it happens as part of the surgery itself.","zh":"如果某事在手術期間發生，它就是手術本身的一部分。"},{"en":"This phrase gives the time frame inside a medical procedure.","zh":"這個片語給出醫療程序內的時間框架。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":11},{"front":"sever","meaning":"切斷","examples":[{"en":"Doctors severed the nerve bundle connecting the two hemispheres.","zh":"醫生切斷連接兩個半球的神經束。"},{"en":"To sever something means to cut it completely.","zh":"sever something 指完全切斷某物。"},{"en":"A storm may sever power lines and leave homes without electricity.","zh":"暴風雨可能切斷電線，令住戶停電。"},{"en":"If doctors sever a nerve bundle, signals can no longer pass normally through it.","zh":"如果醫生切斷神經束，訊號便不能再正常通過它。"},{"en":"This word describes a complete cutting or separation.","zh":"這個詞描述完全切開或分離。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":11},{"front":"corpus callosum","meaning":"胼胝體","examples":[{"en":"The corpus callosum connects the two brain hemispheres.","zh":"胼胝體連接大腦兩個半球。"},{"en":"The corpus callosum is a thick bundle of nerve fibres joining the left and right sides of the brain.","zh":"corpus callosum 是連接大腦左右兩側的厚神經纖維束。"},{"en":"Doctors study the corpus callosum to understand communication between brain hemispheres.","zh":"醫生研究胼胝體，以理解大腦半球之間的溝通。"},{"en":"If the corpus callosum is cut, the two sides of the brain cannot share information normally.","zh":"如果胼胝體被切斷，大腦兩側便不能正常共享資訊。"},{"en":"This phrase names the brain bridge between hemispheres.","zh":"這個片語指出大腦半球之間的橋樑。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":11},{"front":"nerve bundle","meaning":"神經束","examples":[{"en":"The corpus callosum is a nerve bundle between the hemispheres.","zh":"胼胝體是兩個半球之間的神經束。"},{"en":"A nerve bundle is a group of nerve fibres that carry signals together.","zh":"nerve bundle 是一組一起傳遞訊號的神經纖維。"},{"en":"An injury to a nerve bundle in the arm may affect movement or feeling.","zh":"手臂神經束受傷可能影響活動或感覺。"},{"en":"If a nerve bundle connects two areas, cutting it can stop communication between them.","zh":"如果神經束連接兩個區域，切斷它會停止兩者之間的溝通。"},{"en":"This phrase describes grouped nerves working as a pathway.","zh":"這個片語描述作為通路運作的一組神經。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":11},{"front":"connect the two hemispheres","meaning":"連接兩個半球","examples":[{"en":"The corpus callosum connects the two hemispheres.","zh":"胼胝體連接兩個半球。"},{"en":"To connect the two hemispheres means to link the left and right halves of the brain.","zh":"connect the two hemispheres 指連接大腦左右兩半。"},{"en":"A bridge connects two sides of a river so people can cross easily.","zh":"橋樑連接河流兩岸，讓人們容易通過。"},{"en":"If the brain’s hemispheres are connected, information can pass from one side to the other.","zh":"如果大腦兩個半球相連，資訊可以從一側傳到另一側。"},{"en":"This phrase describes the brain’s internal communication link.","zh":"這個片語描述大腦內部的溝通連結。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":11},{"front":"surgical cut","meaning":"手術切口","examples":[{"en":"The surgical cut stopped communication between the hemispheres.","zh":"這個手術切口停止了兩個半球之間的溝通。"},{"en":"A surgical cut is an incision made by doctors during an operation.","zh":"surgical cut 是醫生在手術期間作出的切口。"},{"en":"A surgeon makes a surgical cut carefully to reach the part that needs treatment.","zh":"外科醫生小心作出手術切口，以到達需要治療的部位。"},{"en":"If a surgical cut separates a nerve pathway, normal signals may stop.","zh":"如果手術切口分隔神經通路，正常訊號可能停止。"},{"en":"This phrase refers to a deliberate cut made in surgery.","zh":"這個片語指手術中刻意作出的切口。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":11},{"front":"normal communication between","meaning":"……之間的正常溝通","examples":[{"en":"The operation stopped normal communication between the two hemispheres.","zh":"這項手術停止了兩個半球之間的正常溝通。"},{"en":"Normal communication between two parts means the usual exchange of information between them.","zh":"normal communication between two parts 指兩個部分之間平常的資訊交換。"},{"en":"A broken Internet cable can stop normal communication between an office and its server.","zh":"斷裂的網絡線可以停止辦公室與伺服器之間的正常溝通。"},{"en":"If normal communication between brain hemispheres stops, each side may act more independently.","zh":"如果大腦半球之間的正常溝通停止，每一側可能更獨立地運作。"},{"en":"This phrase describes ordinary information flow between two connected parts.","zh":"這個片語描述兩個相連部分之間的正常資訊流動。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":12},{"front":"offer researchers the opportunity to","meaning":"為研究人員提供機會去……","examples":[{"en":"The surgery offered researchers the opportunity to study each side’s activity.","zh":"這項手術為研究人員提供機會去研究每一側的活動。"},{"en":"To offer researchers the opportunity to do something means to give them a chance to investigate it.","zh":"offer researchers the opportunity to do something 指給研究人員機會去調查某事。"},{"en":"A new telescope can offer researchers the opportunity to study distant planets.","zh":"新望遠鏡可以為研究人員提供機會去研究遙遠行星。"},{"en":"If a medical procedure creates unusual conditions, it may offer scientists valuable research chances.","zh":"如果醫療程序創造不尋常條件，它可能為科學家提供寶貴研究機會。"},{"en":"This phrase explains how a situation creates a research possibility.","zh":"這個片語解釋某情況如何創造研究可能性。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":12},{"front":"investigate","meaning":"調查；研究","examples":[{"en":"Researchers could investigate each side’s activity.","zh":"研究人員可以調查每一側的活動。"},{"en":"To investigate means to study, examine, or look into something carefully.","zh":"investigate 指仔細研究、檢查或查明某事。"},{"en":"A teacher may investigate why many students missed the same question.","zh":"老師可能調查為何許多學生都錯同一題。"},{"en":"If researchers investigate brain activity, they collect evidence before drawing conclusions.","zh":"如果研究人員調查腦部活動，他們會先收集證據，再得出結論。"},{"en":"This word describes careful examination.","zh":"這個詞描述仔細檢查。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":12},{"front":"each side’s activity","meaning":"每一側的活動","examples":[{"en":"Split-brain surgery allowed scientists to investigate each side’s activity.","zh":"裂腦手術讓科學家調查每一側的活動。"},{"en":"Each side’s activity means what the left or right half of the brain is doing.","zh":"each side’s activity 指大腦左半或右半正在做甚麼。"},{"en":"Brain scans can help doctors see each side’s activity during a task.","zh":"腦部掃描可以幫助醫生看到任務期間每一側的活動。"},{"en":"If each side’s activity is measured separately, researchers can learn which functions belong where.","zh":"如果每一側的活動被分開量度，研究人員可以了解哪些功能屬於哪裡。"},{"en":"This phrase refers to separate activity in the two brain hemispheres.","zh":"這個片語指大腦兩個半球中的分開活動。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":12},{"front":"neurosurgeon","meaning":"神經外科醫生","examples":[{"en":"Juhn Wada was a neurosurgeon who devised a language test.","zh":"Juhn Wada 是一名設計語言測試的神經外科醫生。"},{"en":"A neurosurgeon is a doctor who performs surgery on the brain, spine, or nervous system.","zh":"neurosurgeon 是對大腦、脊椎或神經系統進行手術的醫生。"},{"en":"A neurosurgeon may operate on a patient with a serious brain condition.","zh":"神經外科醫生可能為嚴重腦部疾病病人動手術。"},{"en":"If a neurosurgeon develops a test, it may help doctors plan safer brain surgery.","zh":"如果神經外科醫生開發測試，它可能幫助醫生規劃更安全的腦部手術。"},{"en":"This word names a specialist in nervous-system surgery.","zh":"這個詞指出神經系統外科專家。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":12},{"front":"devise the first test","meaning":"設計首個測試","examples":[{"en":"Wada devised the first test for brain language organisation.","zh":"Wada 設計了首個大腦語言組織測試。"},{"en":"To devise the first test means to invent or design the earliest method for measuring something.","zh":"devise the first test 指發明或設計最早用來測量某事的方法。"},{"en":"A teacher may devise the first test for a new course to check basic skills.","zh":"老師可能為新課程設計首個測試，以檢查基本技能。"},{"en":"If no suitable test exists, researchers must devise one before collecting reliable data.","zh":"如果沒有合適測試，研究人員必須先設計測試，才能收集可靠數據。"},{"en":"This phrase describes creating an original testing method.","zh":"這個片語描述創造原創測試方法。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":12},{"front":"provide access to","meaning":"讓人了解……","examples":[{"en":"The test provided access to the brain’s functional organization of language.","zh":"這個測試讓人了解大腦中語言的功能組織。"},{"en":"To provide access to something means to make it possible to reach, observe, or understand it.","zh":"provide access to something 指使人能夠接觸、觀察或理解某事。"},{"en":"Online libraries provide access to books for students who live far away.","zh":"網上圖書館讓住得遠的學生能夠接觸書籍。"},{"en":"If a test provides access to hidden brain functions, doctors can study them more safely.","zh":"如果測試讓人了解隱藏腦功能，醫生便能更安全地研究它們。"},{"en":"This phrase describes opening a way to information or use.","zh":"這個片語描述打開取得資訊或使用的途徑。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":12},{"front":"functional organization of language","meaning":"語言的功能組織","examples":[{"en":"Wada’s test studied the functional organization of language in the brain.","zh":"Wada 的測試研究大腦中語言的功能組織。"},{"en":"Functional organization of language means how different brain areas share the work of understanding and producing language.","zh":"functional organization of language 指不同腦區如何分工理解和產生語言。"},{"en":"Researchers study language organisation to know which brain areas support speaking or reading.","zh":"研究人員研究語言組織，以了解哪些腦區支援說話或閱讀。"},{"en":"If language functions are organised mainly on one side, surgery must avoid damaging that side.","zh":"如果語言功能主要組織在一側，手術必須避免損傷該側。"},{"en":"This phrase describes how language tasks are arranged in the brain.","zh":"這個片語描述語言任務如何在大腦中安排。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":12},{"front":"inject an anaesthetic into","meaning":"將麻醉劑注入……","examples":[{"en":"Wada injected an anaesthetic into the carotid artery.","zh":"Wada 將麻醉劑注入頸動脈。"},{"en":"To inject an anaesthetic into something means to put a numbing or sleep-inducing drug into that part with a needle.","zh":"inject an anaesthetic into something 指用針把令部位麻木或令人失去感覺的藥物注入該處。"},{"en":"A dentist may inject an anaesthetic into the gum before removing a tooth.","zh":"牙醫拔牙前可能將麻醉劑注入牙肉。"},{"en":"If an anaesthetic reaches one brain side, that side can be temporarily switched off for testing.","zh":"如果麻醉劑到達大腦一側，該側可以被暫時關閉以作測試。"},{"en":"This phrase describes giving a medical drug by injection.","zh":"這個片語描述以注射方式給予醫療藥物。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":12},{"front":"carotid artery","meaning":"頸動脈","examples":[{"en":"The anaesthetic was injected into the right or left carotid artery.","zh":"麻醉劑被注入右側或左側頸動脈。"},{"en":"The carotid artery is a major blood vessel in the neck that carries blood to the brain.","zh":"carotid artery 是頸部一條主要血管，負責把血液送往大腦。"},{"en":"Doctors check the carotid artery when they are concerned about blood flow to the brain.","zh":"醫生擔心大腦血流時會檢查頸動脈。"},{"en":"If medicine enters one carotid artery, it can affect the brain side supplied by that vessel.","zh":"如果藥物進入某一側頸動脈，它可以影響由該血管供血的大腦一側。"},{"en":"This phrase names an important artery linked to the brain.","zh":"這個片語指出與大腦相關的重要動脈。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":12},{"front":"temporarily paralyze","meaning":"暫時麻痺","examples":[{"en":"The anaesthetic temporarily paralyzed one side of the brain.","zh":"麻醉劑暫時麻痺大腦一側。"},{"en":"To temporarily paralyze something means to stop it from working for a short time.","zh":"temporarily paralyze something 指令某物短時間停止運作。"},{"en":"A local anaesthetic can temporarily paralyze feeling in a small area during dental treatment.","zh":"局部麻醉劑可以在牙科治療期間暫時麻痺小範圍感覺。"},{"en":"If one brain side is temporarily paralysed, doctors can test what the other side can do.","zh":"如果大腦一側被暫時麻痺，醫生可以測試另一側能做甚麼。"},{"en":"This phrase describes short-term loss of function.","zh":"這個片語描述短期功能喪失。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":12},{"front":"healthy brain","meaning":"健康大腦","examples":[{"en":"Wada temporarily paralyzed one side of a healthy brain.","zh":"Wada 暫時麻痺健康大腦的一側。"},{"en":"A healthy brain is a brain that is functioning normally without disease or serious injury.","zh":"healthy brain 是沒有疾病或嚴重損傷、正常運作的大腦。"},{"en":"Sleep, exercise, and learning can support a healthy brain.","zh":"睡眠、運動和學習可以支持健康大腦。"},{"en":"If doctors test a healthy brain safely, they can learn about normal brain organisation.","zh":"如果醫生安全測試健康大腦，他們可以了解正常腦部組織。"},{"en":"This phrase contrasts normal function with damaged or diseased brain function.","zh":"這個片語把正常功能與受損或患病大腦功能作對比。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":13},{"front":"enabling someone to","meaning":"使某人能夠……","examples":[{"en":"The test enabled Wada to study the other side’s capabilities.","zh":"這個測試使 Wada 能夠研究另一側的能力。"},{"en":"Enabling someone to do something means making it possible for them to do it.","zh":"enabling someone to do something 指使某人能夠做某事。"},{"en":"Online lessons enable students in remote areas to study with qualified teachers.","zh":"網上課堂使偏遠地區學生能夠跟合資格老師學習。"},{"en":"If a test blocks one brain side, it enables researchers to examine the other side separately.","zh":"如果測試阻斷大腦一側，它就使研究人員能夠分開檢查另一側。"},{"en":"This phrase explains what a method allows someone to do.","zh":"這個片語解釋某方法容許某人做甚麼。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":13},{"front":"capabilities","meaning":"能力","examples":[{"en":"Wada studied the capabilities of each brain hemisphere.","zh":"Wada 研究每個腦半球的能力。"},{"en":"Capabilities are the abilities or functions that someone or something can perform.","zh":"capabilities 是某人或某物能執行的能力或功能。"},{"en":"A school may test students’ language capabilities before placing them in classes.","zh":"學校可能先測試學生語言能力，再安排班級。"},{"en":"If one brain side has different capabilities, each side may support different tasks.","zh":"如果大腦一側有不同能力，每一側可能支援不同任務。"},{"en":"This word refers to what a person, system, or body part can do.","zh":"這個詞指人、系統或身體部位能做甚麼。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":13},{"front":"based on this approach","meaning":"基於這種方法","examples":[{"en":"Based on this approach, Milner and Rasmussen published a major study.","zh":"基於這種方法，Milner 和 Rasmussen 發表了一項重要研究。"},{"en":"Based on this approach means using this method or idea as the foundation.","zh":"based on this approach 指以這種方法或想法作為基礎。"},{"en":"Based on this approach, a teacher may design lessons around examples before rules.","zh":"基於這種方法，老師可能圍繞例子再到規則來設計課堂。"},{"en":"If a method provides useful results, later researchers may build studies on it.","zh":"如果某方法提供有用結果，後來研究人員可能以它建立研究。"},{"en":"This phrase shows that one piece of work grows from an earlier method.","zh":"這個片語顯示一項工作源自較早方法。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":13},{"front":"the late Theodore Rasmussen","meaning":"已故的 Theodore Rasmussen","examples":[{"en":"Brenda Milner worked with the late Theodore Rasmussen.","zh":"Brenda Milner 與已故的 Theodore Rasmussen 合作。"},{"en":"The late Theodore Rasmussen means Theodore Rasmussen, who had died by the time of writing or speaking.","zh":"the late Theodore Rasmussen 指在寫作或說話時已經去世的 Theodore Rasmussen。"},{"en":"People may refer to the late professor Lee when honouring a scholar who has passed away.","zh":"人們紀念已故學者時，可能稱他為已故李教授。"},{"en":"If someone is called the late, the phrase shows respect and indicates that the person is no longer alive.","zh":"如果某人被稱為 the late，這個片語表示尊重並指出該人已不在人世。"},{"en":"This phrase is used before the name of a deceased person.","zh":"這個片語用於已故人士姓名前。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":13},{"front":"publish a major study","meaning":"發表一項重要研究","examples":[{"en":"Milner and Rasmussen published a major study in 1975.","zh":"Milner 和 Rasmussen 於1975年發表一項重要研究。"},{"en":"To publish a major study means to make an important research paper or report publicly available.","zh":"publish a major study 指公開發布一篇重要研究論文或報告。"},{"en":"A university team may publish a major study on children’s reading habits.","zh":"大學團隊可能發表一項關於兒童閱讀習慣的重要研究。"},{"en":"If a study is major, it may influence later research for many years.","zh":"如果研究很重要，它可能多年影響後來研究。"},{"en":"This phrase describes releasing important academic work.","zh":"這個片語描述發布重要學術作品。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":13},{"front":"confirm the theory that","meaning":"證實……理論","examples":[{"en":"The study confirmed the theory that language is mainly processed in the left hemisphere.","zh":"該研究證實語言主要在左腦半球處理的理論。"},{"en":"To confirm the theory that means to provide evidence showing that a theory is likely correct.","zh":"confirm the theory that 指提供證據顯示某理論很可能正確。"},{"en":"Test results may confirm the theory that sleep improves memory.","zh":"測驗結果可能證實睡眠改善記憶的理論。"},{"en":"If repeated evidence confirms a theory, scientists become more willing to accept it.","zh":"如果反覆證據證實某理論，科學家會更願意接受它。"},{"en":"This phrase connects evidence with stronger belief in an explanation.","zh":"這個片語把證據與對解釋更強的信念連接起來。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":13},{"front":"formulate a theory","meaning":"提出理論","examples":[{"en":"Dax had formulated the theory nearly 140 years earlier.","zh":"Dax 早在近140年前已提出這個理論。"},{"en":"To formulate a theory means to develop and express an explanation in a clear form.","zh":"formulate a theory 指發展並清楚表達一個解釋。"},{"en":"A scientist may formulate a theory after noticing the same result in many experiments.","zh":"科學家在許多實驗中注意到同一結果後，可能提出理論。"},{"en":"If a theory is formulated clearly, later researchers can test it.","zh":"如果理論被清楚提出，後來研究人員就能測試它。"},{"en":"This phrase describes creating a structured explanation.","zh":"這個片語描述創造有結構的解釋。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":13},{"front":"language is processed","meaning":"語言被處理","examples":[{"en":"Language is processed much more intensely in the left hemisphere.","zh":"語言在左腦半球被密集得多地處理。"},{"en":"Language is processed means the brain receives, understands, and produces language.","zh":"language is processed 指大腦接收、理解和產生語言。"},{"en":"When a student reads a sentence, language is processed through brain networks.","zh":"當學生閱讀句子時，語言會透過大腦網絡被處理。"},{"en":"If language is processed mainly in one hemisphere, damage there can affect speech or reading.","zh":"如果語言主要在某半球處理，該處受損可能影響說話或閱讀。"},{"en":"This phrase describes how the brain handles language.","zh":"這個片語描述大腦如何處理語言。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":13},{"front":"much more intensely","meaning":"密集得多","examples":[{"en":"Language is processed much more intensely in the left hemisphere.","zh":"語言在左腦半球被密集得多地處理。"},{"en":"Much more intensely means with far greater activity, strength, or concentration.","zh":"much more intensely 指以遠高得多的活動、強度或集中程度。"},{"en":"A student may study much more intensely during the week before an exam.","zh":"學生在考試前一星期可能溫習得密集得多。"},{"en":"If one brain area works more intensely during language tasks, it may be more important for language.","zh":"如果某腦區在語言任務中活動密集得多，它可能對語言更重要。"},{"en":"This phrase describes a strong difference in level or activity.","zh":"這個片語描述程度或活動上的強烈差異。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":13},{"front":"the correlation is not as clear","meaning":"相關性沒有那麼清楚","examples":[{"en":"The correlation is not as clear in lefties.","zh":"這種相關性在左撇子身上沒有那麼清楚。"},{"en":"The correlation is not as clear means the relationship is weaker, less obvious, or more complicated.","zh":"the correlation is not as clear 指關係較弱、較不明顯或較複雜。"},{"en":"The link between study time and marks is not as clear if students use very different study methods.","zh":"如果學生使用非常不同的溫習方法，溫習時間與分數之間的關聯就沒有那麼清楚。"},{"en":"If left-handed people show varied brain patterns, the correlation becomes harder to interpret.","zh":"如果左撇子顯示多樣腦部模式，相關性就更難詮釋。"},{"en":"This phrase warns that a relationship is not simple.","zh":"這個片語提醒某關係並不簡單。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":13},{"front":"active language processor","meaning":"活躍的語言處理區","examples":[{"en":"For many lefties, the left hemisphere is still the most active language processor.","zh":"對許多左撇子而言，左腦半球仍是最活躍的語言處理區。"},{"en":"An active language processor is the brain area that works most strongly when handling language.","zh":"active language processor 是處理語言時運作最強的腦區。"},{"en":"During reading aloud, an active language processor helps turn words into speech.","zh":"朗讀時，活躍的語言處理區幫助把文字轉成說話。"},{"en":"If one hemisphere is the active language processor, it may be especially important during language tasks.","zh":"如果某半球是活躍的語言處理區，它在語言任務中可能尤其重要。"},{"en":"This phrase describes the brain side most involved in language.","zh":"這個片語描述最參與語言的大腦一側。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":14},{"front":"remaining third","meaning":"餘下三分之一","examples":[{"en":"For the remaining third, language dominance is different.","zh":"對餘下三分之一而言，語言主導情況不同。"},{"en":"The remaining third means the one-third left after the other two-thirds have been counted.","zh":"remaining third 指計算了另外三分之二後剩下的三分之一。"},{"en":"If two-thirds of a class choose history, the remaining third may choose geography.","zh":"如果班中三分之二選歷史，餘下三分之一可能選地理。"},{"en":"In research, the remaining third may show a different pattern from the majority.","zh":"在研究中，餘下三分之一可能顯示與多數不同的模式。"},{"en":"This phrase refers to the part left over in a three-part proportion.","zh":"這個片語指三部分比例中剩下的部分。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":14},{"front":"right side is dominant","meaning":"右側佔主導","examples":[{"en":"For some lefties, the right side is dominant for language.","zh":"對一些左撇子而言，右側在語言方面佔主導。"},{"en":"Right side is dominant means the right hemisphere plays the leading role in a function.","zh":"right side is dominant 指右腦半球在某功能中扮演主導角色。"},{"en":"In some people, one brain side is dominant for certain tasks.","zh":"在一些人身上，大腦某一側在某些任務上佔主導。"},{"en":"If the right side is dominant for language, brain organisation differs from the usual pattern.","zh":"如果右側在語言方面佔主導，腦部組織就不同於一般模式。"},{"en":"This phrase describes right-hemisphere leadership in a function.","zh":"這個片語描述右腦半球在某功能中的主導性。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":14},{"front":"both sides work equally","meaning":"兩側同等運作","examples":[{"en":"In some lefties, both sides work equally.","zh":"在一些左撇子中，兩側同等運作。"},{"en":"Both sides work equally means the left and right hemispheres share a task at a similar level.","zh":"both sides work equally 指左右腦半球以相似程度分擔某任務。"},{"en":"A team works equally when both partners do similar amounts of work.","zh":"當兩名伙伴做相近工作量時，團隊就是同等運作。"},{"en":"If both brain sides work equally, language may be less concentrated in one hemisphere.","zh":"如果大腦兩側同等運作，語言可能較少集中在單一半球。"},{"en":"This phrase describes balanced activity between two sides.","zh":"這個片語描述兩側之間的平衡活動。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":14},{"front":"controlling different language functions","meaning":"控制不同語言功能","examples":[{"en":"Both hemispheres may control different language functions.","zh":"兩個半球可能控制不同語言功能。"},{"en":"Controlling different language functions means each brain side manages different parts of language ability.","zh":"controlling different language functions 指每個腦半球管理不同部分的語言能力。"},{"en":"One area may help with grammar, while another helps with tone or meaning.","zh":"一個區域可能幫助文法，另一個區域幫助語氣或意思。"},{"en":"If language functions are divided, damage to one side may affect only some language skills.","zh":"如果語言功能被分開，某一側受損可能只影響部分語言技能。"},{"en":"This phrase describes shared but specialised brain control.","zh":"這個片語描述共享但專門化的腦部控制。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":14},{"front":"slow acceptance of","meaning":"減慢對……的接受","examples":[{"en":"This statistic slowed acceptance of the left-hemisphere theory.","zh":"這項統計減慢了人們對左腦半球理論的接受。"},{"en":"To slow acceptance of something means to make people take longer to believe or support it.","zh":"slow acceptance of something 指令人們花更長時間相信或支持某事。"},{"en":"Confusing evidence can slow acceptance of a new school policy.","zh":"混亂證據可以減慢人們對新校政的接受。"},{"en":"If data does not fit neatly, acceptance of a theory may be delayed.","zh":"如果數據不完全吻合理論，人們接受該理論可能被延遲。"},{"en":"This phrase describes resistance or delay in accepting an idea.","zh":"這個片語描述接受想法時的阻力或延誤。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":14},{"front":"the notion that","meaning":"……這個概念","examples":[{"en":"The statistic challenged the notion that right-handedness is driven by language dominance.","zh":"這項統計挑戰了右撇子由語言主導推動這個概念。"},{"en":"The notion that means the idea or belief that something is true.","zh":"the notion that 指某事為真的想法或信念。"},{"en":"The notion that good students never make mistakes can make learners afraid to try.","zh":"好學生永不犯錯這個概念可能令學習者害怕嘗試。"},{"en":"If new evidence challenges a notion, people may need to rethink it.","zh":"如果新證據挑戰某概念，人們可能需要重新思考它。"},{"en":"This phrase introduces an idea that may be discussed or questioned.","zh":"這個片語引入可被討論或質疑的想法。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":14},{"front":"predominance of right-handedness","meaning":"右撇子的主導地位","examples":[{"en":"The predominance of right-handedness may not be fully explained by language.","zh":"右撇子的主導地位可能不能完全由語言解釋。"},{"en":"Predominance of right-handedness means the fact that right-handed people are much more common.","zh":"predominance of right-handedness 指右撇子遠較常見這一事實。"},{"en":"The predominance of online payment in a city can change how shops serve customers.","zh":"網上付款在城市中的主導地位可以改變店舖服務顧客的方式。"},{"en":"If right-handedness predominates, scientists ask why one side became so common.","zh":"如果右撇子佔主導，科學家會問為何某一側變得如此常見。"},{"en":"This phrase describes the strong majority of right-handed people.","zh":"這個片語描述右撇子佔強大多數。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":14},{"front":"be driven by","meaning":"由……推動","examples":[{"en":"Some believe right-handedness is driven by left-hemisphere dominance.","zh":"有些人相信右撇子傾向由左腦半球主導推動。"},{"en":"To be driven by something means to be caused, guided, or strongly influenced by it.","zh":"be driven by something 指由某事造成、引導或強烈影響。"},{"en":"A student’s progress may be driven by regular feedback and clear goals.","zh":"學生進步可能由定期回饋和清晰目標推動。"},{"en":"If handedness is driven by brain dominance, brain organisation may shape body preference.","zh":"如果慣用手由腦半球主導推動，腦部組織可能塑造身體偏好。"},{"en":"This phrase identifies a force behind a result.","zh":"這個片語指出結果背後的力量。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":14},{"front":"language processing","meaning":"語言處理","examples":[{"en":"Left-hemisphere dominance is important in language processing.","zh":"左腦半球主導在語言處理中很重要。"},{"en":"Language processing is the brain’s work of understanding, producing, and organising language.","zh":"language processing 是大腦理解、產生和組織語言的工作。"},{"en":"Reading, listening, speaking, and writing all involve language processing.","zh":"閱讀、聆聽、說話和寫作都涉及語言處理。"},{"en":"If language processing is damaged, a person may struggle to find words or understand speech.","zh":"如果語言處理受損，人可能難以找詞或理解說話。"},{"en":"This phrase describes mental work involved in language.","zh":"這個片語描述語言所涉及的心智工作。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":14},{"front":"not at all clear","meaning":"完全不清楚","examples":[{"en":"It is not at all clear why language control affected body movement.","zh":"語言控制為何影響身體動作完全不清楚。"},{"en":"Not at all clear means completely unclear or very uncertain.","zh":"not at all clear 指完全不清楚或非常不確定。"},{"en":"It is not at all clear why some students improve quickly while others need more time.","zh":"為何有些學生進步很快，而另一些需要更多時間，完全不清楚。"},{"en":"If the reason is not clear, researchers should avoid making strong claims.","zh":"如果原因不清楚，研究人員應避免作出強烈聲稱。"},{"en":"This phrase expresses strong uncertainty.","zh":"這個片語表達強烈不確定性。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":14},{"front":"language control","meaning":"語言控制","examples":[{"en":"Language control may be linked to hand preference.","zh":"語言控制可能與用手偏好有關。"},{"en":"Language control means the brain’s management of speaking, understanding, and organising language.","zh":"language control 指大腦對說話、理解和組織語言的管理。"},{"en":"A person with poor language control after injury may know an idea but struggle to say it.","zh":"受傷後語言控制較差的人可能知道一個想法，但難以說出來。"},{"en":"If language control and hand preference are linked, speech and movement may share brain pathways.","zh":"如果語言控制與用手偏好有關，說話和動作可能共享腦部通路。"},{"en":"This phrase refers to how the brain manages language.","zh":"這個片語指大腦如何管理語言。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":15},{"front":"drag something with it","meaning":"把……一併帶動","examples":[{"en":"Language control may have dragged body-movement control with it.","zh":"語言控制可能把身體動作控制一併帶動。"},{"en":"To drag something with it means to pull or bring another thing along as it develops or moves.","zh":"drag something with it 指在某事發展或移動時，把另一事物一起拉動或帶走。"},{"en":"A new school rule about phones may drag classroom routines with it because teachers must change lessons.","zh":"關於手機的新校規可能把課堂流程一併帶動改變，因為老師必須調整課堂。"},{"en":"If language control developed strongly on one side, movement control might have been pulled in the same direction.","zh":"如果語言控制在一側強烈發展，動作控制可能被帶向同一方向。"},{"en":"This phrase describes one change bringing another change along.","zh":"這個片語描述一種變化帶來另一種變化。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":15},{"front":"reign over","meaning":"主宰","examples":[{"en":"The left hemisphere reigns over language in most right-handed people.","zh":"左腦半球在大多數右撇子身上主宰語言。"},{"en":"To reign over something means to dominate or have main control over it.","zh":"reign over something 指主導或主要控制某事。"},{"en":"In a busy kitchen, the head chef may reign over the cooking process.","zh":"在繁忙廚房中，主廚可能主宰烹調過程。"},{"en":"If one brain hemisphere reigns over language, it becomes the main centre for that function.","zh":"如果一個腦半球主宰語言，它就成為該功能的主要中心。"},{"en":"This phrase gives a strong image of control or dominance.","zh":"這個片語給出控制或主導的強烈意象。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":15},{"front":"organs of speech processing","meaning":"語音處理器官","examples":[{"en":"The larynx and tongue are organs of speech processing.","zh":"喉頭和舌頭是語音處理器官。"},{"en":"Organs of speech processing are body parts used to produce spoken sounds.","zh":"organs of speech processing 是用來產生語音的身體部位。"},{"en":"The tongue, lips, and larynx help shape sounds when people speak.","zh":"舌頭、嘴唇和喉頭在人說話時幫助塑造聲音。"},{"en":"If speech organs do not move smoothly, pronunciation may become unclear.","zh":"如果語音器官不能順暢活動，發音可能變得不清楚。"},{"en":"This phrase refers to physical body parts involved in speaking.","zh":"這個片語指涉及說話的身體部位。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":15},{"front":"larynx and tongue","meaning":"喉頭和舌頭","examples":[{"en":"The larynx and tongue are positioned on the body’s symmetry axis.","zh":"喉頭和舌頭位於身體的對稱軸上。"},{"en":"The larynx and tongue are body parts used in producing speech sounds.","zh":"larynx and tongue 是用來產生語音的身體部位。"},{"en":"A speech therapist may help patients control the larynx and tongue more effectively.","zh":"言語治療師可能幫助病人更有效控制喉頭和舌頭。"},{"en":"If the larynx or tongue moves poorly, speech can become unclear.","zh":"如果喉頭或舌頭活動不佳，說話可能變得不清楚。"},{"en":"This phrase names two important speech organs.","zh":"這個片語指出兩個重要語音器官。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":15},{"front":"symmetry axis","meaning":"對稱軸","examples":[{"en":"Speech organs lie on the body’s symmetry axis.","zh":"語音器官位於身體的對稱軸上。"},{"en":"The symmetry axis is the central line that divides the body into left and right halves.","zh":"symmetry axis 是把身體分成左右兩半的中央線。"},{"en":"The nose lies close to the body’s symmetry axis, while the hands are on either side.","zh":"鼻子接近身體對稱軸，而雙手位於兩側。"},{"en":"If an organ lies on the symmetry axis, both body sides may be involved in controlling it.","zh":"如果器官位於對稱軸上，身體兩側都可能參與控制它。"},{"en":"This phrase describes the body’s middle line.","zh":"這個片語描述身體的中線。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":15},{"front":"in evolutionary terms","meaning":"從進化角度來看","examples":[{"en":"In evolutionary terms, one brain side may have needed to control speech organs.","zh":"從進化角度來看，大腦一側可能需要控制語音器官。"},{"en":"In evolutionary terms means from the viewpoint of survival, adaptation, and long-term biological change.","zh":"in evolutionary terms 指從生存、適應和長期生物變化角度來看。"},{"en":"In evolutionary terms, cooperation can help groups survive danger.","zh":"從進化角度來看，合作可以幫助群體在危險中生存。"},{"en":"If smooth speech improved communication, evolution may have favoured one-side control.","zh":"如果流暢說話改善溝通，進化可能偏向由一側控制。"},{"en":"This phrase frames an explanation through long-term human development.","zh":"這個片語透過長期人類發展來框定解釋。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":15},{"front":"shared operation","meaning":"共同運作","examples":[{"en":"Shared operation by both hemispheres may not produce smooth movement.","zh":"兩個半球共同運作可能無法產生流暢動作。"},{"en":"Shared operation means two parts working together to control one task.","zh":"shared operation 指兩個部分一起控制同一任務。"},{"en":"A group project uses shared operation when every member controls part of the work.","zh":"當每名成員控制工作的一部分，小組專題就是共同運作。"},{"en":"If two controllers send mixed signals, movement may become less smooth.","zh":"如果兩個控制者發出混合訊號，動作可能變得較不流暢。"},{"en":"This phrase describes joint control rather than single control.","zh":"這個片語描述共同控制，而不是單一控制。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":15},{"front":"result in","meaning":"導致","examples":[{"en":"Shared operation might not result in smooth motor activity.","zh":"共同運作可能不會導致流暢的運動活動。"},{"en":"To result in something means to cause it to happen.","zh":"result in something 指造成某事發生。"},{"en":"Poor sleep can result in slower thinking the next day.","zh":"睡眠不足可以導致翌日思考較慢。"},{"en":"If two brain sides compete during a movement, the result may be less smooth action.","zh":"如果大腦兩側在動作中互相競爭，結果可能是動作較不流暢。"},{"en":"This phrase links a cause with an outcome.","zh":"這個片語把原因與結果連接起來。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":15},{"front":"smooth motor activity","meaning":"流暢的運動活動","examples":[{"en":"Speech requires smooth motor activity.","zh":"說話需要流暢的運動活動。"},{"en":"Smooth motor activity means coordinated, controlled physical movement.","zh":"smooth motor activity 指協調而受控制的身體動作。"},{"en":"Writing neatly requires smooth motor activity in the fingers and wrist.","zh":"工整書寫需要手指和手腕有流暢的運動活動。"},{"en":"If motor activity is not smooth, speech sounds or handwriting may become unclear.","zh":"如果運動活動不流暢，語音或筆跡可能變得不清楚。"},{"en":"This phrase describes precise movement controlled by the body and brain.","zh":"這個片語描述由身體和大腦控制的精確動作。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":15},{"front":"develop preferentially for","meaning":"因偏向……而發展","examples":[{"en":"Language and handedness could have developed preferentially for different reasons.","zh":"語言和慣用手可能因非常不同的原因而偏向性發展。"},{"en":"To develop preferentially for something means to grow or become stronger because of particular advantages or pressures.","zh":"develop preferentially for something 指因特定優勢或壓力而成長或變得更強。"},{"en":"A student may develop preferentially in speaking if they practise conversation more than writing.","zh":"如果學生比寫作更常練習對話，口語能力可能偏向性發展。"},{"en":"If two abilities developed for different reasons, they should not be explained by one cause alone.","zh":"如果兩種能力因不同原因發展，就不應只用一個原因解釋。"},{"en":"This phrase describes development favouring one direction or purpose.","zh":"這個片語描述發展偏向某方向或目的。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":15},{"front":"very different reasons","meaning":"非常不同的原因","examples":[{"en":"Language and handedness may have developed for very different reasons.","zh":"語言和慣用手可能因非常不同的原因而發展。"},{"en":"Very different reasons means causes that are not the same and may be unrelated.","zh":"very different reasons 指不相同且可能無關的原因。"},{"en":"Two students may miss class for very different reasons: illness and transport problems.","zh":"兩名學生可能因非常不同的原因缺課：生病和交通問題。"},{"en":"If two patterns have different causes, one theory may not explain both.","zh":"如果兩種模式有不同原因，一個理論可能不能同時解釋兩者。"},{"en":"This phrase stresses strong difference in explanation.","zh":"這個片語強調解釋上的強烈差異。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":16},{"front":"evolutionary psychologist","meaning":"進化心理學家","examples":[{"en":"Michael Corballis is an evolutionary psychologist.","zh":"Michael Corballis 是一名進化心理學家。"},{"en":"An evolutionary psychologist studies how human behaviour may have developed through evolution.","zh":"evolutionary psychologist 研究人類行為可能如何透過進化形成。"},{"en":"An evolutionary psychologist may ask why humans cooperate, speak, or prefer certain patterns.","zh":"進化心理學家可能問人類為何合作、說話或偏好某些模式。"},{"en":"If a behaviour helped survival in the past, evolutionary psychologists may study it closely.","zh":"如果某行為在過去有助生存，進化心理學家可能仔細研究它。"},{"en":"This phrase names a researcher linking psychology with evolution.","zh":"這個片語指出把心理學與進化連結的研究人員。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":16},{"front":"origin of human speech","meaning":"人類語言的起源","examples":[{"en":"Some researchers think the origin of human speech lies in gestures.","zh":"一些研究人員認為人類語言的起源在於手勢。"},{"en":"The origin of human speech means how spoken language first began.","zh":"origin of human speech 指口語最初如何開始。"},{"en":"A language teacher may discuss the origin of human speech when explaining why gestures help communication.","zh":"語言老師解釋為何手勢有助溝通時，可能討論人類語言的起源。"},{"en":"If speech began from gesture, body movement may be deeply linked to language.","zh":"如果語言源自手勢，身體動作可能與語言有深層連繫。"},{"en":"This phrase asks where spoken language came from.","zh":"這個片語詢問口語從何而來。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":16},{"front":"lie in","meaning":"在於","examples":[{"en":"The origin of human speech may lie in gestures.","zh":"人類語言的起源可能在於手勢。"},{"en":"To lie in something means to be found in it or depend on it as the main explanation.","zh":"lie in something 指存在於某事中，或以某事作為主要解釋。"},{"en":"The strength of a good essay may lie in clear examples rather than difficult words.","zh":"好文章的力量可能在於清楚例子，而不是深字。"},{"en":"If the origin of speech lies in gesture, movement may have come before words.","zh":"如果語言起源在於手勢，動作可能早於詞語出現。"},{"en":"This phrase identifies the deeper source of something.","zh":"這個片語指出某事的深層來源。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":16},{"front":"gestures","meaning":"手勢","examples":[{"en":"Gestures may have helped human speech emerge.","zh":"手勢可能幫助人類語言出現。"},{"en":"Gestures are movements of the hands, face, or body used to communicate meaning.","zh":"gestures 是用來傳達意思的手、面部或身體動作。"},{"en":"A teacher may use gestures to show students when to listen, stop, or repeat.","zh":"老師可能使用手勢，示意學生聆聽、停止或重複。"},{"en":"If gestures carry meaning, they can support communication before or alongside words.","zh":"如果手勢承載意思，它們可以在詞語出現之前或與詞語一起支援溝通。"},{"en":"This word describes body movements used as signals.","zh":"這個詞描述用作訊號的身體動作。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":16},{"front":"predate words","meaning":"早於詞語出現","examples":[{"en":"Gestures predated words.","zh":"手勢早於詞語出現。"},{"en":"To predate words means to exist or happen before spoken words appeared.","zh":"predate words 指在口語詞彙出現之前已存在或發生。"},{"en":"Pictures on cave walls predate modern writing systems.","zh":"洞穴牆上的圖畫早於現代文字系統。"},{"en":"If gestures predated words, early communication may have begun with body movement.","zh":"如果手勢早於詞語出現，早期溝通可能始於身體動作。"},{"en":"This phrase describes something existing earlier than language in words.","zh":"這個片語描述某事比詞語語言更早存在。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":16},{"front":"help language emerge","meaning":"幫助語言出現","examples":[{"en":"Gestures may have helped language emerge.","zh":"手勢可能幫助語言出現。"},{"en":"To help language emerge means to contribute to the development or appearance of language.","zh":"help language emerge 指有助語言發展或出現。"},{"en":"Parent-child interaction helps spoken language emerge in young children.","zh":"親子互動幫助幼兒口語出現。"},{"en":"If gestures carried meaning first, they may have helped words develop later.","zh":"如果手勢先承載意思，它們可能幫助詞語後來發展。"},{"en":"This phrase describes one factor supporting the rise of language.","zh":"這個片語描述支援語言興起的一個因素。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":16},{"front":"begin to dominate","meaning":"開始主導","examples":[{"en":"The left hemisphere may have begun to dominate speech.","zh":"左腦半球可能開始主導說話。"},{"en":"To begin to dominate means to start becoming the main controlling or leading force.","zh":"begin to dominate 指開始成為主要控制或領導力量。"},{"en":"Online learning began to dominate during periods when schools were closed.","zh":"在學校停課期間，網上學習開始主導。"},{"en":"If one brain side begins to dominate a function, that function becomes less evenly shared.","zh":"如果大腦一側開始主導某功能，該功能就變得較不平均分配。"},{"en":"This phrase describes the start of increasing control.","zh":"這個片語描述控制力增加的開始。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":16},{"front":"dominate gestures","meaning":"主導手勢","examples":[{"en":"If the left hemisphere dominated speech, it may have dominated gestures too.","zh":"如果左腦半球主導說話，它可能也主導手勢。"},{"en":"To dominate gestures means to have main control over gesture production or coordination.","zh":"dominate gestures 指主要控制手勢的產生或協調。"},{"en":"A performer’s right hand may dominate gestures during a speech if it is more expressive.","zh":"如果表演者右手更有表現力，演講期間右手可能主導手勢。"},{"en":"If one brain side controls both speech and gestures, the two systems may be linked.","zh":"如果大腦一側同時控制說話和手勢，兩個系統可能有關。"},{"en":"This phrase describes control over body signals.","zh":"這個片語描述對身體訊號的控制。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":16},{"front":"develop more strongly","meaning":"發展得更強","examples":[{"en":"The right hand may have developed more strongly because of left-brain control.","zh":"右手可能因左腦控制而發展得更強。"},{"en":"To develop more strongly means to grow, improve, or become more powerful than another part.","zh":"develop more strongly 指比另一部分成長、改善或變得更強。"},{"en":"A student’s reading may develop more strongly than writing if they read every day but rarely write.","zh":"如果學生每天閱讀但很少寫作，閱讀可能比寫作發展得更強。"},{"en":"If one hand is controlled more effectively, its skill may develop more strongly.","zh":"如果某隻手受到更有效控制，其技能可能發展得更強。"},{"en":"This phrase compares uneven development.","zh":"這個片語比較不平均的發展。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":16},{"front":"in the meantime","meaning":"與此同時","examples":[{"en":"In the meantime, we can consider the possible differences handedness brings.","zh":"與此同時，我們可以思考慣用手可能帶來的差異。"},{"en":"In the meantime means during the period before something else is known or happens.","zh":"in the meantime 指在另一件事被知道或發生之前的期間。"},{"en":"The exam results will arrive next week; in the meantime, students can review their mistakes.","zh":"考試結果下星期公布；與此同時，學生可以檢討錯誤。"},{"en":"If scientists do not yet know the final answer, they can still discuss related possibilities.","zh":"如果科學家尚未知道最終答案，他們仍可以討論相關可能性。"},{"en":"This phrase introduces what can be done while waiting.","zh":"這個片語引入等待期間可以做的事。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":16},{"front":"revel in","meaning":"享受；欣賞","examples":[{"en":"We can revel in the differences handedness may bring.","zh":"我們可以欣賞慣用手可能帶來的差異。"},{"en":"To revel in something means to enjoy it deeply and openly.","zh":"revel in something 指深深並公開地享受某事。"},{"en":"A student who loves books may revel in a quiet afternoon at the library.","zh":"喜愛書本的學生可能盡情享受圖書館中安靜的下午。"},{"en":"If people revel in differences, they appreciate variety instead of seeing it as a problem.","zh":"如果人們欣賞差異，他們會重視多樣性，而不是把它視為問題。"},{"en":"This phrase describes strong enjoyment or appreciation.","zh":"這個片語描述強烈享受或欣賞。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":17},{"front":"what differences handedness brings","meaning":"慣用手帶來甚麼差異","examples":[{"en":"Researchers still ask what differences handedness brings.","zh":"研究人員仍在問慣用手帶來甚麼差異。"},{"en":"What differences handedness brings means what effects hand preference may have on ability, behaviour, or experience.","zh":"what differences handedness brings 指用手偏好可能對能力、行為或經驗有甚麼影響。"},{"en":"Teachers may ask what differences learning style brings to classroom participation.","zh":"老師可能問學習風格會為課堂參與帶來甚麼差異。"},{"en":"If handedness affects daily tools, it may also affect confidence or skill development.","zh":"如果慣用手影響日常工具使用，它也可能影響信心或技能發展。"},{"en":"This phrase asks about the consequences of being right- or left-handed.","zh":"這個片語詢問右撇子或左撇子的後果。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":17},{"front":"human talents","meaning":"人類才能","examples":[{"en":"Handedness may be linked to different human talents.","zh":"慣用手可能與不同人類才能有關。"},{"en":"Human talents are natural or developed abilities such as music, art, logic, sport, or language.","zh":"human talents 是天生或後天發展的能力，例如音樂、藝術、邏輯、運動或語言。"},{"en":"Schools help students discover human talents through lessons, clubs, and competitions.","zh":"學校透過課堂、社團和比賽幫助學生發現人類才能。"},{"en":"If a trait is linked to certain talents, researchers must still prove the connection carefully.","zh":"如果某特徵與某些才能有關，研究人員仍必須小心證明這種連繫。"},{"en":"This phrase refers to abilities found in people.","zh":"這個片語指人身上的能力。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":17},{"front":"popular wisdom says","meaning":"大眾智慧認為","examples":[{"en":"Popular wisdom says right-handed people excel at logical thinking.","zh":"大眾智慧認為右撇子擅長邏輯思維。"},{"en":"Popular wisdom says means many ordinary people commonly believe something.","zh":"popular wisdom says 指許多普通人普遍相信某事。"},{"en":"Popular wisdom says breakfast is the most important meal, though research may be more complicated.","zh":"大眾智慧認為早餐是最重要的一餐，雖然研究可能更複雜。"},{"en":"If popular wisdom is not tested, it may become a stereotype rather than fact.","zh":"如果大眾智慧沒有被測試，它可能變成刻板印象，而不是事實。"},{"en":"This phrase introduces a common belief, not necessarily scientific truth.","zh":"這個片語引入常見信念，而不一定是科學真相。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":17},{"front":"left-brained people","meaning":"左腦型人士","examples":[{"en":"Right-handed, left-brained people are thought to be logical.","zh":"右撇子、左腦型人士被認為較有邏輯。"},{"en":"Left-brained people are people popularly believed to rely more on logical and analytical thinking.","zh":"left-brained people 是大眾認為較依賴邏輯和分析思維的人。"},{"en":"A left-brained student may enjoy puzzles, grammar rules, and step-by-step problems.","zh":"左腦型學生可能喜歡謎題、文法規則和一步一步解題。"},{"en":"If people label someone left-brained too quickly, they may ignore that person’s creativity.","zh":"如果人們太快把某人標籤為左腦型，可能忽視那人的創意。"},{"en":"This phrase is common in popular discussion but should be used cautiously.","zh":"這個片語常見於大眾討論，但應謹慎使用。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":17},{"front":"excel at","meaning":"擅長","examples":[{"en":"Right-handed people are often said to excel at logical thinking.","zh":"人們常說右撇子擅長邏輯思維。"},{"en":"To excel at something means to be very good at it.","zh":"excel at something 指非常擅長某事。"},{"en":"A student may excel at speaking because they practise conversations every week.","zh":"學生可能因每週練習對話而擅長口語。"},{"en":"If someone excels at problem-solving, classmates may ask them for help with difficult tasks.","zh":"如果某人擅長解難，同學可能請他幫忙處理困難任務。"},{"en":"This phrase describes strong ability in a particular area.","zh":"這個片語描述在特定範疇有強能力。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":17},{"front":"logical, analytical thinking","meaning":"邏輯和分析思維","examples":[{"en":"Right-handed people are often associated with logical, analytical thinking.","zh":"右撇子常與邏輯和分析思維有關。"},{"en":"Logical, analytical thinking means using reason, evidence, and careful steps to solve problems.","zh":"logical, analytical thinking 指使用理性、證據和仔細步驟來解決問題。"},{"en":"Solving a maths proof requires logical, analytical thinking.","zh":"解數學證明需要邏輯和分析思維。"},{"en":"If a task needs clear cause-and-effect reasoning, analytical thinking becomes useful.","zh":"如果任務需要清楚因果推理，分析思維就變得有用。"},{"en":"This phrase describes careful reasoning rather than emotional guessing.","zh":"這個片語描述仔細推理，而不是情緒化猜測。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":17},{"front":"right-brained individuals","meaning":"右腦型人士","examples":[{"en":"Left-handed, right-brained individuals are thought to be more creative.","zh":"左撇子、右腦型人士被認為更有創意。"},{"en":"Right-brained individuals are people popularly believed to rely more on creativity, imagination, or visual thinking.","zh":"right-brained individuals 是大眾認為較依賴創意、想像或視覺思維的人。"},{"en":"A right-brained individual may enjoy drawing, music, and open-ended projects.","zh":"右腦型人士可能喜歡繪畫、音樂和開放式專題。"},{"en":"If people assume all artists are right-brained, they may ignore the planning behind art.","zh":"如果人們假設所有藝術家都是右腦型，就可能忽略藝術背後的規劃。"},{"en":"This phrase reflects a popular idea, not a simple scientific rule.","zh":"這個片語反映大眾想法，而不是簡單科學規則。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":17},{"front":"possess more creative skills","meaning":"擁有更多創意技能","examples":[{"en":"Left-handed people are often thought to possess more creative skills.","zh":"左撇子常被認為擁有更多創意技能。"},{"en":"To possess more creative skills means to have stronger abilities in imagination, design, art, or original problem-solving.","zh":"possess more creative skills 指在想像、設計、藝術或原創解難方面有較強能力。"},{"en":"A student may possess creative skills if they can turn a simple poster into a memorable design.","zh":"如果學生能把簡單海報變成令人難忘的設計，他可能擁有創意技能。"},{"en":"If a group is believed to have creative skills, people may expect more art or music from them.","zh":"如果某群體被認為有創意技能，人們可能期待他們產出更多藝術或音樂。"},{"en":"This phrase describes having creative ability, but it should not be treated as automatic.","zh":"這個片語描述擁有創意能力，但不應視為必然。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":17},{"front":"combine functions","meaning":"結合功能","examples":[{"en":"Some left-handers may be better at combining functions from both hemispheres.","zh":"一些左撇子可能較擅長結合兩個半球的功能。"},{"en":"To combine functions means to bring different abilities or roles together so they work as one.","zh":"combine functions 指把不同能力或角色放在一起，使它們共同運作。"},{"en":"A good presentation combines speaking, visuals, timing, and audience awareness.","zh":"好匯報結合說話、視覺材料、時間控制和觀眾意識。"},{"en":"If both brain hemispheres contribute, a person may combine different kinds of processing.","zh":"如果兩個腦半球都有貢獻，人可能結合不同類型的處理。"},{"en":"This phrase describes joining separate abilities into a shared process.","zh":"這個片語描述把分開能力加入同一過程。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":17},{"front":"associated with","meaning":"與……有關","examples":[{"en":"Some functions are associated with both hemispheres.","zh":"一些功能與兩個半球都有關。"},{"en":"Associated with means connected to or linked with something.","zh":"associated with 指與某事連接或相關。"},{"en":"Poor sleep is often associated with weak concentration.","zh":"睡眠不足常與專注力弱有關。"},{"en":"If a function is associated with both hemispheres, it may not belong to only one side.","zh":"如果某功能與兩個半球都有關，它可能不只屬於一側。"},{"en":"This phrase describes a connection, not always a direct cause.","zh":"這個片語描述關聯，不一定是直接原因。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":17},{"front":"pure speculation","meaning":"純粹猜測","examples":[{"en":"Some neuroscientists see such claims as pure speculation.","zh":"一些神經科學家把這類說法視為純粹猜測。"},{"en":"Pure speculation means guessing without enough solid evidence.","zh":"pure speculation 指沒有足夠堅實證據的猜想。"},{"en":"Saying a student will fail before seeing their work is pure speculation.","zh":"還未看學生作品就說他會失敗，是純粹猜測。"},{"en":"If a claim about creativity lacks data, scientists may treat it as speculation.","zh":"如果關於創意的聲稱缺乏數據，科學家可能把它視為猜測。"},{"en":"This phrase warns that an idea is not yet proven.","zh":"這個片語提醒某想法尚未被證實。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":18},{"front":"creative potential","meaning":"創意潛能","examples":[{"en":"Few scientists are ready to claim that left-handedness means greater creative potential.","zh":"很少科學家準備聲稱左撇子傾向意味着更大創意潛能。"},{"en":"Creative potential is the ability or possibility to produce original ideas or artistic work.","zh":"creative potential 是產生原創想法或藝術作品的能力或可能性。"},{"en":"A child’s creative potential may appear when they invent stories from ordinary objects.","zh":"孩子用普通物件創作故事時，可能展現創意潛能。"},{"en":"If creative potential is real, it still needs practice and opportunity to develop.","zh":"如果創意潛能存在，它仍需要練習和機會來發展。"},{"en":"This phrase refers to possible creativity, not guaranteed achievement.","zh":"這個片語指可能的創意，而不是保證的成就。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":18},{"front":"prevalent among","meaning":"在……中常見","examples":[{"en":"Lefties are prevalent among artists and composers.","zh":"左撇子在藝術家和作曲家中常見。"},{"en":"Prevalent among means common or frequently found within a group.","zh":"prevalent among 指在某群體中常見或經常出現。"},{"en":"Part-time jobs are prevalent among university students who need extra income.","zh":"兼職工作在需要額外收入的大學生中常見。"},{"en":"If a trait is prevalent among artists, researchers may ask whether the link is real or coincidental.","zh":"如果某特徵在藝術家中常見，研究人員可能問這種關聯是真實還是巧合。"},{"en":"This phrase describes something common within a particular group.","zh":"這個片語描述某事在特定群體中常見。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":18},{"front":"artists and composers","meaning":"藝術家和作曲家","examples":[{"en":"Left-handed people are often found among artists and composers.","zh":"左撇子常見於藝術家和作曲家之中。"},{"en":"Artists and composers are people who create visual art, music, or other creative works.","zh":"artists and composers 是創作視覺藝術、音樂或其他創意作品的人。"},{"en":"A school concert may feature young composers and artists who designed the stage backdrop.","zh":"學校音樂會可能展示年輕作曲家和設計舞台背景的藝術家。"},{"en":"If many left-handed people appear among artists and composers, people may link handedness with creativity.","zh":"如果許多左撇子出現在藝術家和作曲家之中，人們可能把慣用手與創意連繫起來。"},{"en":"This phrase names two creative occupations.","zh":"這個片語指出兩種創意職業。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":18},{"front":"generally acknowledged","meaning":"普遍公認的","examples":[{"en":"Some great political thinkers are generally acknowledged as outstanding.","zh":"一些偉大政治思想家被普遍公認為傑出。"},{"en":"Generally acknowledged means widely accepted or recognised by most people.","zh":"generally acknowledged 指被大多數人廣泛接受或認可。"},{"en":"A teacher may be generally acknowledged as fair if students trust her decisions.","zh":"如果學生信任老師的決定，她可能被普遍公認為公平。"},{"en":"If a thinker is generally acknowledged as important, their ideas are respected across many groups.","zh":"如果思想家被普遍公認為重要，其想法會在許多群體中受尊重。"},{"en":"This phrase describes broad recognition.","zh":"這個片語描述廣泛認可。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":18},{"front":"political thinkers","meaning":"政治思想家","examples":[{"en":"Lefties are found among great political thinkers.","zh":"左撇子可見於偉大政治思想家之中。"},{"en":"Political thinkers are people who develop ideas about government, society, power, and justice.","zh":"political thinkers 是提出關於政府、社會、權力和公義想法的人。"},{"en":"Students may study political thinkers to understand democracy, rights, and law.","zh":"學生可能研究政治思想家，以理解民主、權利和法律。"},{"en":"If political thinkers change public ideas, their influence can last for generations.","zh":"如果政治思想家改變公眾想法，其影響可以持續幾代。"},{"en":"This phrase refers to people known for political ideas rather than daily politics alone.","zh":"這個片語指以政治思想聞名的人，而不只是日常政治。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":18},{"front":"evenly distributed between hemispheres","meaning":"在兩個半球之間平均分佈","examples":[{"en":"Some lefties may have language abilities evenly distributed between hemispheres.","zh":"一些左撇子的語言能力可能在兩個半球之間平均分佈。"},{"en":"Evenly distributed between hemispheres means shared in a balanced way between the left and right brain halves.","zh":"evenly distributed between hemispheres 指在左右腦半球之間平衡分配。"},{"en":"Work is evenly distributed in a group when every member carries a fair share.","zh":"當每名成員承擔公平份量，小組工作就是平均分配的。"},{"en":"If language ability is evenly distributed, both brain sides may support communication.","zh":"如果語言能力平均分佈，兩個腦半球都可能支援溝通。"},{"en":"This phrase describes balanced division across the brain’s two halves.","zh":"這個片語描述在大腦兩半之間的平衡分工。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":18},{"front":"intense interplay","meaning":"密切互動","examples":[{"en":"Intense interplay between hemispheres could lead to unusual capabilities.","zh":"兩個半球之間的密切互動可能帶來不尋常能力。"},{"en":"Intense interplay means strong interaction or exchange between two parts.","zh":"intense interplay 指兩個部分之間強烈互動或交流。"},{"en":"A good debate involves intense interplay between questions, evidence, and responses.","zh":"好辯論包含問題、證據和回應之間的密切互動。"},{"en":"If brain hemispheres interact intensely, they may combine information in unusual ways.","zh":"如果大腦半球密切互動，它們可能以不尋常方式結合資訊。"},{"en":"This phrase describes active two-way influence.","zh":"這個片語描述積極的雙向影響。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":18},{"front":"unusual mental capabilities","meaning":"不尋常的心智能力","examples":[{"en":"Such interplay may lead to unusual mental capabilities.","zh":"這種互動可能帶來不尋常的心智能力。"},{"en":"Unusual mental capabilities are rare or special thinking abilities.","zh":"unusual mental capabilities 是罕見或特殊的思考能力。"},{"en":"A person with unusual mental capabilities may remember music, patterns, or images especially well.","zh":"擁有不尋常心智能力的人可能特別善於記住音樂、模式或圖像。"},{"en":"If brain networks work differently, they may produce strengths that are not common.","zh":"如果大腦網絡運作不同，它們可能產生不常見的優勢。"},{"en":"This phrase describes special cognitive abilities.","zh":"這個片語描述特殊認知能力。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":18},{"front":"get by","meaning":"應付；過活","examples":[{"en":"Some lefties become creative because they must get by in a right-handed world.","zh":"一些左撇子變得有創意，因為他們必須在右撇子世界中應付生活。"},{"en":"To get by means to manage or survive with difficulty or limited support.","zh":"get by 指在困難或支援有限下勉強應付或生存。"},{"en":"A student may get by with an old laptop until they can afford a new one.","zh":"學生可能先靠舊手提電腦應付，直到能負擔新電腦。"},{"en":"If left-handed people must adapt to right-handed tools, they may develop flexible problem-solving habits.","zh":"如果左撇子必須適應右撇子工具，他們可能發展出靈活解難習慣。"},{"en":"This phrase describes coping rather than thriving easily.","zh":"這個片語描述應付，而不是輕鬆成功。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":18},{"front":"battle begins","meaning":"這場戰鬥開始","examples":[{"en":"This battle begins during the very early stages of childhood.","zh":"這場戰鬥在童年非常早期階段開始。"},{"en":"Battle begins means a difficult struggle or challenge starts.","zh":"battle begins 指困難的掙扎或挑戰開始。"},{"en":"For many students, the battle against procrastination begins when homework becomes demanding.","zh":"對許多學生來說，與拖延對抗的戰鬥在功課變得吃力時開始。"},{"en":"If left-handed children face unsuitable tools early, the struggle starts in childhood.","zh":"如果左撇子孩子早期面對不合適工具，這場掙扎就在童年開始。"},{"en":"This phrase uses battle as a metaphor for ongoing difficulty.","zh":"這個片語用戰鬥比喻持續困難。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":18},{"front":"early stages of childhood","meaning":"童年早期階段","examples":[{"en":"Left-handed children face difficulties from the early stages of childhood.","zh":"左撇子孩子從童年早期階段開始面對困難。"},{"en":"Early stages of childhood means the first years of a child’s life and development.","zh":"early stages of childhood 指孩子生命和發展的最初幾年。"},{"en":"During the early stages of childhood, children learn basic movement, language, and social habits.","zh":"在童年早期階段，孩子學習基本動作、語言和社交習慣。"},{"en":"If challenges appear early, they can shape confidence and learning habits later.","zh":"如果挑戰早期出現，它們可以塑造日後信心和學習習慣。"},{"en":"This phrase refers to the beginning period of childhood.","zh":"這個片語指童年的開始時期。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":19},{"front":"lay the groundwork for","meaning":"為……奠定基礎","examples":[{"en":"These challenges may lay the groundwork for exceptional achievements.","zh":"這些挑戰可能為卓越成就奠定基礎。"},{"en":"To lay the groundwork for something means to prepare the conditions that make it possible later.","zh":"lay the groundwork for something 指準備條件，使某事日後成為可能。"},{"en":"Daily reading can lay the groundwork for stronger writing in secondary school.","zh":"每日閱讀可以為中學更強寫作能力奠定基礎。"},{"en":"If children learn to adapt early, those skills may support later success.","zh":"如果孩子早期學會適應，這些技能可能支持日後成功。"},{"en":"This phrase describes building a foundation for future results.","zh":"這個片語描述為未來結果建立基礎。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":19},{"front":"exceptional achievements","meaning":"卓越成就","examples":[{"en":"Adapting to a right-handed world may support exceptional achievements.","zh":"適應右撇子世界可能支持卓越成就。"},{"en":"Exceptional achievements are unusually great successes or accomplishments.","zh":"exceptional achievements 是非常出色的成功或成就。"},{"en":"Winning an international science prize as a teenager is an exceptional achievement.","zh":"青少年贏得國際科學獎是一項卓越成就。"},{"en":"If early challenges build resilience and flexibility, they may contribute to later achievement.","zh":"如果早期挑戰建立韌性和靈活性，它們可能有助日後成就。"},{"en":"This phrase describes success far above the ordinary level.","zh":"這個片語描述遠高於普通水平的成功。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":19},{"front":"contains the following information","meaning":"包含以下資料","examples":[{"en":"Candidates identify which section contains the following information.","zh":"考生識別哪一部分包含以下資料。"},{"en":"Contains the following information means includes the specific details listed in the question.","zh":"contains the following information 指包括題目列出的特定細節。"},{"en":"In a reading test, a paragraph may contain the information even if it uses different words.","zh":"在閱讀測驗中，即使段落使用不同字眼，也可能包含該資料。"},{"en":"If students search for meaning rather than only keywords, they can locate answers more accurately.","zh":"如果學生搜尋意思而不只是關鍵字，就能更準確定位答案。"},{"en":"This phrase is common in information-matching questions.","zh":"這個片語常見於資訊配對題。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":19},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Candidates write the correct letter in the answer box.","zh":"考生在答案框中寫上正確字母。"},{"en":"To write the correct letter means to record the letter that matches the right answer.","zh":"write the correct letter 指記下與正確答案相符的字母。"},{"en":"If section C contains the answer, candidates should write C, not the whole sentence.","zh":"如果 C 部分包含答案，考生應寫 C，而不是整句。"},{"en":"If students know the answer but write the wrong letter, they may lose marks.","zh":"如果學生知道答案但寫錯字母，可能會失分。"},{"en":"This phrase reminds candidates to follow the required answer format.","zh":"這個片語提醒考生遵守指定答案格式。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":19},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Candidates write their answers on their answer sheet.","zh":"考生在答題紙上寫下答案。"},{"en":"On your answer sheet means in the official place where exam answers must be recorded.","zh":"on your answer sheet 指在考試答案必須記錄的正式位置上。"},{"en":"A student should check that every answer is written on the answer sheet before time ends.","zh":"學生應在時間完結前檢查每個答案都寫在答題紙上。"},{"en":"If an answer remains only in the question booklet, it may not be marked.","zh":"如果答案只留在題目簿中，可能不會被評分。"},{"en":"This phrase refers to the official answer document.","zh":"這個片語指正式答案文件。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":19},{"front":"preference for using one side of the body","meaning":"偏好使用身體某一側","examples":[{"en":"The question asks about a preference for using one side of the body.","zh":"題目問關於偏好使用身體某一側的資料。"},{"en":"Preference for using one side of the body means favouring the left or right side for repeated actions.","zh":"preference for using one side of the body 指在重複動作中偏好左側或右側。"},{"en":"A cat may show a preference for using one side of the body when it reaches for food.","zh":"貓伸爪取食物時可能顯示偏好使用身體某一側。"},{"en":"If one side is used more often, it may become stronger or more skilled.","zh":"如果某一側被更常使用，它可能變得更強或更熟練。"},{"en":"This phrase describes side preference in movement.","zh":"這個片語描述動作中的側向偏好。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":19},{"front":"among animal species","meaning":"在動物物種之中","examples":[{"en":"Side preference is found among animal species.","zh":"側向偏好在動物物種之中被發現。"},{"en":"Among animal species means across different kinds of animals.","zh":"among animal species 指在不同種類的動物之中。"},{"en":"Tool use is found among animal species such as apes, birds, and dolphins.","zh":"使用工具可見於猿、鳥和海豚等動物物種之中。"},{"en":"If a behaviour appears among animal species, it may not be uniquely human.","zh":"如果某行為出現在動物物種中，它可能不是人類獨有。"},{"en":"This phrase describes patterns seen across animals.","zh":"這個片語描述在動物之間看到的模式。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":19},{"front":"likelihood that","meaning":"……的可能性","examples":[{"en":"The question asks about the likelihood that a child will be left-handed.","zh":"題目問孩子會成為左撇子的可能性。"},{"en":"The likelihood that something will happen means the chance or probability of it happening.","zh":"likelihood that something will happen 指某事發生的機會或可能性。"},{"en":"The likelihood that a student will pass increases with regular practice.","zh":"學生合格的可能性會隨定期練習而增加。"},{"en":"If one parent is left-handed, the likelihood may rise but the result is not certain.","zh":"如果父母其中一方是左撇子，可能性可能上升，但結果不確定。"},{"en":"This phrase is useful for discussing chances.","zh":"這個片語適合討論機會。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":19},{"front":"become established","meaning":"確立","examples":[{"en":"The question asks when a preference for one hand becomes established.","zh":"題目問對某一隻手的偏好何時確立。"},{"en":"To become established means to become fixed, accepted, or stable.","zh":"become established 指變得固定、被接受或穩定。"},{"en":"A morning routine becomes established when a student repeats it every school day.","zh":"如果學生每個上學日都重複早晨習慣，該習慣就會確立。"},{"en":"If hand preference becomes established later, early signs may still change.","zh":"如果用手偏好較晚才確立，早期跡象仍可能改變。"},{"en":"This phrase describes something becoming settled over time.","zh":"這個片語描述某事隨時間變得穩定。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":19},{"front":"occupations in which","meaning":"……常見的職業","examples":[{"en":"The question refers to occupations in which left-handed people are commonly found.","zh":"題目提及左撇子常見的職業。"},{"en":"Occupations in which means jobs or professions where something occurs.","zh":"occupations in which 指某事出現的工作或專業。"},{"en":"Occupations in which creativity matters include design, music, writing, and advertising.","zh":"創意重要的職業包括設計、音樂、寫作和廣告。"},{"en":"If left-handed people appear often in certain occupations, researchers may ask why.","zh":"如果左撇子常出現在某些職業中，研究人員可能問原因。"},{"en":"This phrase introduces job categories linked to a pattern.","zh":"這個片語引入與某模式相關的職業類別。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":19},{"front":"commonly found","meaning":"常見於","examples":[{"en":"Left-handed people are commonly found among artists and composers.","zh":"左撇子常見於藝術家和作曲家之中。"},{"en":"Commonly found means often present in a particular group or place.","zh":"commonly found 指經常出現在某一群體或地方。"},{"en":"Bilingual students are commonly found in international schools.","zh":"雙語學生常見於國際學校。"},{"en":"If a trait is commonly found in a group, people may look for an explanation.","zh":"如果某特徵常見於某群體，人們可能尋找解釋。"},{"en":"This phrase describes frequent occurrence.","zh":"這個片語描述經常出現。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":20},{"front":"reference to","meaning":"提及……","examples":[{"en":"The question asks for a reference to an early discovery.","zh":"題目要求找出對早期發現的提及。"},{"en":"A reference to something is a mention of it in speech or writing.","zh":"reference to something 是在說話或寫作中提到某事。"},{"en":"A history essay may include a reference to an old law to support its argument.","zh":"歷史文章可能提及一條舊法律，以支持其論點。"},{"en":"If a paragraph contains a reference to Dax’s discovery, it may answer the matching question.","zh":"如果某段提及 Dax 的發現，它可能回答配對題。"},{"en":"This phrase describes a mention, not necessarily a long explanation.","zh":"這個片語描述提到某事，不一定是長篇解釋。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":20},{"front":"early discovery","meaning":"早期發現","examples":[{"en":"Dax made an early discovery about the brain’s hemispheres.","zh":"Dax 作出關於大腦半球的早期發現。"},{"en":"An early discovery is a finding made near the beginning of a field’s development.","zh":"early discovery 是在某研究領域發展初期作出的發現。"},{"en":"An early discovery in medicine may be ignored at first but later become important.","zh":"醫學中的早期發現起初可能被忽視，但後來變得重要。"},{"en":"If an early discovery is confirmed later, the original researcher may be seen as ahead of their time.","zh":"如果早期發現後來被證實，原本研究者可能被視為超前於時代。"},{"en":"This phrase describes a finding made before wider acceptance.","zh":"這個片語描述在廣泛接受之前作出的發現。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":20},{"front":"functions of the brain’s hemispheres","meaning":"大腦半球的功能","examples":[{"en":"The passage discusses the functions of the brain’s hemispheres.","zh":"文章討論大腦半球的功能。"},{"en":"Functions of the brain’s hemispheres means the jobs carried out by the left and right sides of the brain.","zh":"functions of the brain’s hemispheres 指大腦左右兩側所執行的工作。"},{"en":"One hemisphere may be more involved in language, while the other may support perception.","zh":"一個半球可能較多參與語言，另一個可能支援感知。"},{"en":"If the hemispheres have different functions, injury to each side can create different symptoms.","zh":"如果兩個半球有不同功能，每側受傷會造成不同症狀。"},{"en":"This phrase refers to what each brain half does.","zh":"這個片語指大腦每一半做甚麼。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":20},{"front":"list of findings","meaning":"研究發現列表","examples":[{"en":"Candidates match each researcher with the correct finding.","zh":"考生將每位研究者與正確研究發現配對。"},{"en":"A list of findings is a set of research results or discoveries presented together.","zh":"list of findings 是一組一起呈現的研究結果或發現。"},{"en":"A science report may include a list of findings after the experiment section.","zh":"科學報告可能在實驗部分後包括研究發現列表。"},{"en":"If candidates understand each finding, they can match it to the correct researcher.","zh":"如果考生理解每項發現，就能把它配對到正確研究者。"},{"en":"This phrase describes organised research results.","zh":"這個片語描述有組織的研究結果。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":20},{"front":"match each researcher with","meaning":"將每位研究者與……配對","examples":[{"en":"Candidates match each researcher with the correct finding.","zh":"考生將每位研究者與正確發現配對。"},{"en":"To match each researcher with something means to connect every researcher to the correct idea, result, or statement.","zh":"match each researcher with something 指把每位研究者連接到正確想法、結果或陳述。"},{"en":"In a reading task, students may match each researcher with the experiment they conducted.","zh":"在閱讀題中，學生可能將每位研究者與其進行的實驗配對。"},{"en":"If several researchers study similar topics, careful reading is needed to match accurately.","zh":"如果幾位研究者研究相似主題，就需要仔細閱讀才能準確配對。"},{"en":"This phrase is common in matching questions.","zh":"這個片語常見於配對題。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":20},{"front":"evolution of language","meaning":"語言的演化","examples":[{"en":"Some researchers connect the evolution of language with gesture.","zh":"一些研究人員把語言的演化與手勢連繫起來。"},{"en":"Evolution of language means the gradual development of human communication into spoken language.","zh":"evolution of language 指人類溝通逐漸發展成口語的過程。"},{"en":"A linguistics class may study the evolution of language through sounds, gestures, and social life.","zh":"語言學課可能透過聲音、手勢和社會生活研究語言的演化。"},{"en":"If language evolved from gestures, body movement may have shaped speech.","zh":"如果語言由手勢演化而來，身體動作可能塑造了說話。"},{"en":"This phrase refers to how language developed over time.","zh":"這個片語指語言如何隨時間發展。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":20},{"front":"be connected with","meaning":"與……有關","examples":[{"en":"The evolution of language is connected with bodily gesture.","zh":"語言的演化與身體手勢有關。"},{"en":"To be connected with something means to have a relationship or link with it.","zh":"be connected with something 指與某事有關係或連繫。"},{"en":"Poor sleep is connected with weaker concentration in many students.","zh":"睡眠不足與許多學生專注力較弱有關。"},{"en":"If speech is connected with gesture, movement and language may have developed together.","zh":"如果說話與手勢有關，動作和語言可能共同發展。"},{"en":"This phrase describes a relationship between two things.","zh":"這個片語描述兩件事之間的關係。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":20},{"front":"bodily gesture","meaning":"身體手勢","examples":[{"en":"Bodily gesture may have shaped hand preference.","zh":"身體手勢可能塑造慣用手偏好。"},{"en":"Bodily gesture means movement of the body used to communicate or express meaning.","zh":"bodily gesture 指用來溝通或表達意思的身體動作。"},{"en":"Nodding, pointing, waving, and shrugging are common bodily gestures.","zh":"點頭、指向、揮手和聳肩都是常見身體手勢。"},{"en":"If early humans used bodily gestures often, one hand may have become more skilled.","zh":"如果早期人類經常使用身體手勢，某一隻手可能變得更熟練。"},{"en":"This phrase refers to meaningful body movement.","zh":"這個片語指有意義的身體動作。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":20},{"front":"affect hand preference","meaning":"影響慣用手偏好","examples":[{"en":"Gesture may have affected hand preference.","zh":"手勢可能影響慣用手偏好。"},{"en":"To affect hand preference means to influence which hand a person tends to use.","zh":"affect hand preference 指影響一個人傾向使用哪隻手。"},{"en":"A child’s classroom tools may affect hand preference if one hand becomes easier to use.","zh":"如果某隻手較容易使用，孩子的課室工具可能影響慣用手偏好。"},{"en":"If gestures required one hand more often, they could shape long-term hand use.","zh":"如果手勢更常需要某一隻手，它們可能塑造長期用手習慣。"},{"en":"This phrase describes an influence on left- or right-handedness.","zh":"這個片語描述對左撇子或右撇子傾向的影響。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":20},{"front":"biological factor","meaning":"生物因素","examples":[{"en":"No single biological factor determines handedness.","zh":"沒有單一生物因素決定慣用手傾向。"},{"en":"A biological factor is a body-related cause such as genes, hormones, or development.","zh":"biological factor 是與身體相關的原因，例如基因、荷爾蒙或發育。"},{"en":"Sleep, age, and health can be biological factors affecting learning energy.","zh":"睡眠、年齡和健康都可以是影響學習精力的生物因素。"},{"en":"If handedness depends on several biological factors, the explanation becomes complex.","zh":"如果慣用手取決於幾個生物因素，解釋就變得複雜。"},{"en":"This phrase refers to a cause inside the living body.","zh":"這個片語指生命體內部的原因。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":20},{"front":"faster development of","meaning":"……較快發育","examples":[{"en":"The faster development of one side of the fetus’s body may influence handedness.","zh":"胎兒身體一側較快發育可能影響慣用手。"},{"en":"Faster development of something means that part grows or matures more quickly than another part.","zh":"faster development of something 指某部分比另一部分更快成長或成熟。"},{"en":"Faster development of reading skills may happen when a child hears stories every night.","zh":"如果孩子每晚聽故事，閱讀能力可能較快發展。"},{"en":"If one body side develops faster, it may become preferred in early movement.","zh":"如果身體一側較快發育，它可能在早期動作中被偏好。"},{"en":"This phrase compares different rates of development.","zh":"這個片語比較不同發展速度。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":21},{"front":"hemispheric preference","meaning":"腦半球偏好","examples":[{"en":"Fetal movement may influence later hemispheric preference.","zh":"胎兒動作可能影響日後腦半球偏好。"},{"en":"Hemispheric preference means one brain hemisphere becoming more active or dominant for certain functions.","zh":"hemispheric preference 指某一腦半球在某些功能中變得更活躍或佔主導。"},{"en":"Scientists study hemispheric preference to understand why language is often left-sided.","zh":"科學家研究腦半球偏好，以理解為何語言常偏向左側。"},{"en":"If movement affects brain development, it may shape which hemisphere becomes more important.","zh":"如果動作影響大腦發育，它可能塑造哪個半球變得更重要。"},{"en":"This phrase describes preference between the brain’s left and right halves.","zh":"這個片語描述大腦左右兩半之間的偏好。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":21},{"front":"fully mature","meaning":"完全成熟","examples":[{"en":"One option says brain function is fully mature by the end of fetal development.","zh":"其中一個選項說腦功能在胎兒發育結束時已完全成熟。"},{"en":"Fully mature means completely developed and ready to function at an adult or final level.","zh":"fully mature 指完全發育並準備以成人或最終水平運作。"},{"en":"A child’s handwriting is not fully mature when they first learn to hold a pencil.","zh":"孩子剛學握筆時，筆跡尚未完全成熟。"},{"en":"If brain function is not fully mature before birth, later experience may still shape it.","zh":"如果腦功能在出生前尚未完全成熟，後來經驗仍可能塑造它。"},{"en":"This phrase describes complete development.","zh":"這個片語描述完整發展。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":21},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"Candidates decide whether the statements agree with the writer’s views.","zh":"考生判斷以下陳述是否與作者觀點一致。"},{"en":"Do the following statements agree with asks whether each statement matches the text or opinion given.","zh":"do the following statements agree with 問每項陳述是否符合文本或所給觀點。"},{"en":"In reading tests, students should compare exact meaning, not just similar words.","zh":"在閱讀測驗中，學生應比較確切意思，而不只是相似字詞。"},{"en":"If a statement changes the writer’s view, it does not agree with the passage.","zh":"如果陳述改變作者觀點，它就不與文章一致。"},{"en":"This phrase is common in TRUE, FALSE, and NOT GIVEN style tasks.","zh":"這個片語常見於 TRUE、FALSE 和 NOT GIVEN 類題目。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":21},{"front":"views of the writer","meaning":"作者觀點","examples":[{"en":"The answer depends on the views of the writer.","zh":"答案取決於作者觀點。"},{"en":"Views of the writer means the opinions or attitudes expressed by the author.","zh":"views of the writer 指作者表達的意見或態度。"},{"en":"Students should identify the writer’s views by looking at words of approval, doubt, or criticism.","zh":"學生應透過表示認同、懷疑或批評的字眼識別作者觀點。"},{"en":"If a question asks for the writer’s views, facts alone may not be enough.","zh":"如果題目問作者觀點，單靠事實可能不足夠。"},{"en":"This phrase focuses on the author’s position.","zh":"這個片語聚焦於作者立場。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":21},{"front":"contradict the views of","meaning":"與……的觀點相矛盾","examples":[{"en":"A false statement contradicts the views of the writer.","zh":"錯誤陳述與作者觀點相矛盾。"},{"en":"To contradict the views of someone means to express the opposite of that person’s opinion.","zh":"contradict the views of someone 指表達與某人意見相反的意思。"},{"en":"If a writer supports early practice, saying practice is useless contradicts the writer’s views.","zh":"如果作者支持早期練習，說練習無用就與作者觀點相矛盾。"},{"en":"Students should choose FALSE when the statement clearly opposes the writer’s position.","zh":"當陳述清楚反對作者立場時，學生應選 FALSE。"},{"en":"This phrase describes disagreement with an opinion.","zh":"這個片語描述與某意見不一致。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":21},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"The answer is not given if it is impossible to say what the writer thinks.","zh":"如果無法判斷作者怎樣想，答案就是 NOT GIVEN。"},{"en":"Impossible to say means there is not enough information to decide.","zh":"impossible to say 指沒有足夠資料作決定。"},{"en":"If a passage never mentions gender differences, it is impossible to say whether men are more affected.","zh":"如果文章從未提及性別差異，就無法判斷男性是否更受影響。"},{"en":"When it is impossible to say from the text, students should not use outside knowledge.","zh":"當文本無法判斷時，學生不應使用外部知識。"},{"en":"This phrase signals uncertainty due to missing information.","zh":"這個片語表示因資料缺失而不確定。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":21},{"front":"research involving twins","meaning":"涉及雙胞胎的研究","examples":[{"en":"Research involving twins shows that genes are not the only factor.","zh":"涉及雙胞胎的研究顯示基因不是唯一因素。"},{"en":"Research involving twins means studies that include twins as participants or evidence.","zh":"research involving twins 指包含雙胞胎作參加者或證據的研究。"},{"en":"Twin research can help separate genetic influence from environment.","zh":"雙胞胎研究可以幫助區分遺傳影響和環境影響。"},{"en":"If twins with the same genes show different traits, researchers look beyond genetics.","zh":"如果基因相同的雙胞胎顯示不同特徵，研究人員會尋找遺傳以外的因素。"},{"en":"This phrase describes research using twins to understand development.","zh":"這個片語描述使用雙胞胎理解發育的研究。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":21},{"front":"the only factor determining","meaning":"決定……的唯一因素","examples":[{"en":"Genes are not the only factor determining left-handedness.","zh":"基因不是決定左撇子傾向的唯一因素。"},{"en":"The only factor determining something means the single cause that decides the result.","zh":"only factor determining something 指決定結果的單一原因。"},{"en":"Exam ability is not the only factor determining success; sleep and confidence also matter.","zh":"考試能力不是決定成功的唯一因素；睡眠和信心也重要。"},{"en":"If genes are not the only factor, development and experience must also be considered.","zh":"如果基因不是唯一因素，發育和經驗也必須被考慮。"},{"en":"This phrase challenges one-cause explanations.","zh":"這個片語挑戰單一成因解釋。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":21},{"front":"widely accepted in his time","meaning":"在他所處時代被廣泛接受","examples":[{"en":"Dax’s report was not widely accepted in his time.","zh":"Dax 的報告在他所處時代未被廣泛接受。"},{"en":"Widely accepted in his time means broadly believed or supported during the period when he lived or worked.","zh":"widely accepted in his time 指在他生活或工作的時期被廣泛相信或支持。"},{"en":"A new teaching method may not be widely accepted in its time if it challenges old habits.","zh":"如果新教學方法挑戰舊習慣，它在其時代可能不被廣泛接受。"},{"en":"If an idea is not accepted at first, later evidence may still prove it important.","zh":"如果想法起初不被接受，後來證據仍可能證明它重要。"},{"en":"This phrase describes acceptance within a historical period.","zh":"這個片語描述某歷史時期中的接受程度。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":21},{"front":"base findings on","meaning":"將研究發現建基於……","examples":[{"en":"The question asks whether Wada based his findings on people with language problems.","zh":"題目問 Wada 是否將研究發現建基於有語言問題的人。"},{"en":"To base findings on something means to use it as the evidence or foundation for conclusions.","zh":"base findings on something 指用某事作為結論的證據或基礎。"},{"en":"A teacher may base findings on test results, homework, and classroom observation.","zh":"老師可能將發現建基於測驗結果、功課和課堂觀察。"},{"en":"If findings are based on the wrong group, the conclusion may be less reliable.","zh":"如果研究發現建基於錯誤群體，結論可能較不可靠。"},{"en":"This phrase explains where research conclusions come from.","zh":"這個片語解釋研究結論從何而來。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":21},{"front":"people with language problems","meaning":"有語言問題的人","examples":[{"en":"Some studies involved people with language problems.","zh":"一些研究涉及有語言問題的人。"},{"en":"People with language problems are individuals who have difficulty speaking, understanding, reading, or producing language.","zh":"people with language problems 是在說話、理解、閱讀或產生語言方面有困難的人。"},{"en":"A speech therapist may help people with language problems after a stroke.","zh":"中風後，言語治療師可能幫助有語言問題的人。"},{"en":"If research only uses people with language problems, results may not represent healthy brains.","zh":"如果研究只使用有語言問題的人，結果可能不能代表健康大腦。"},{"en":"This phrase describes participants with difficulties in language ability.","zh":"這個片語描述在語言能力方面有困難的參加者。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":22},{"front":"tend to be more","meaning":"往往較多","examples":[{"en":"The question asks whether there tend to be more left-handed men than women.","zh":"題目問左撇子男性是否往往比女性較多。"},{"en":"Tend to be more means are usually greater in number, amount, or degree.","zh":"tend to be more 指通常在數量、程度或比例上較多。"},{"en":"There tend to be more students in the library before final exams.","zh":"期末考前，圖書館往往有較多學生。"},{"en":"If one group tends to be more common than another, researchers may look for biological or social reasons.","zh":"如果某一群體往往比另一群體更常見，研究人員可能尋找生物或社會原因。"},{"en":"This phrase describes a general pattern rather than an absolute rule.","zh":"這個片語描述一般模式，而不是絕對規則。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":22},{"front":"men with left-handedness","meaning":"左撇子男性","examples":[{"en":"The statement refers to men with left-handedness.","zh":"該陳述指左撇子男性。"},{"en":"Men with left-handedness are male people who naturally prefer using the left hand.","zh":"men with left-handedness 是自然較喜歡使用左手的男性。"},{"en":"A sports coach may notice men with left-handedness because their playing angle is different.","zh":"運動教練可能注意到左撇子男性，因為他們的擊球或出手角度不同。"},{"en":"If there are more men with left-handedness than women, researchers may ask whether biology or reporting habits explain it.","zh":"如果左撇子男性比女性多，研究人員可能問這是由生物因素還是報告習慣解釋。"},{"en":"This phrase identifies a subgroup by sex and hand preference.","zh":"這個片語以性別和用手偏好識別一個小群體。"}],"source":"Passage 2 Flash Cards  26 - Being Left-handed in a Right-handed World.pdf","sourcePage":22}],"ielts/reading/passage-2/Practice 27":[{"front":"a new ice age","meaning":"新冰河時期","examples":[{"en":"Some scientists believe conditions may be ripe for a new ice age.","zh":"有些科學家認為，條件可能已成熟，會出現新冰河時期。"},{"en":"A new ice age would be a future period when large parts of the world become much colder for a long time.","zh":"新冰河時期是未來一段世界大部分地區長期變得寒冷得多的時期。"},{"en":"If winters became much longer and rivers froze every year, people might fear a new ice age.","zh":"如果冬天變得長得多，而河流每年都結冰，人們可能會擔心新冰河時期。"},{"en":"A new ice age could affect farming, heating costs, transport, and migration.","zh":"新冰河時期可能影響農業、取暖成本、交通和遷移。"},{"en":"This phrase describes serious long-term cooling, not just one cold winter.","zh":"這個短語描述嚴重的長期降溫，而不只是一個寒冷冬天。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":1},{"front":"serious, sober climate scientist","meaning":"嚴謹而冷靜的氣候科學家","examples":[{"en":"William Curry is a serious, sober climate scientist, not an art critic.","zh":"William Curry 是一位嚴謹而冷靜的氣候科學家，不是藝術評論家。"},{"en":"A serious, sober climate scientist is a careful expert who studies climate without exaggeration or drama.","zh":"嚴謹而冷靜的氣候科學家，是一位謹慎研究氣候、而不誇張或戲劇化的專家。"},{"en":"A serious, sober scientist checks data before making a public warning.","zh":"嚴謹而冷靜的科學家會在公開警告前檢查數據。"},{"en":"When a sober scientist sounds worried, people may take the warning more seriously.","zh":"當冷靜的科學家表達憂慮，人們可能更認真看待警告。"},{"en":"This phrase suggests reliability and calm judgement.","zh":"這個短語暗示可靠和冷靜判斷。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":1},{"front":"art critic","meaning":"藝術評論家","examples":[{"en":"William Curry is a climate scientist, not an art critic.","zh":"William Curry 是氣候科學家，不是藝術評論家。"},{"en":"An art critic is a person who studies, evaluates, and writes about works of art.","zh":"藝術評論家是研究、評價並撰寫藝術作品評論的人。"},{"en":"An art critic may discuss the colours, composition, and meaning of a painting.","zh":"藝術評論家可能討論一幅畫的色彩、構圖和意義。"},{"en":"The phrase is used here to contrast scientific analysis with artistic judgement.","zh":"這個短語在此用來對比科學分析與藝術判斷。"},{"en":"An art critic focuses on art, while a climate scientist focuses on climate evidence.","zh":"藝術評論家聚焦藝術，而氣候科學家聚焦氣候證據。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":1},{"front":"spent a lot of time","meaning":"花了很多時間","examples":[{"en":"Curry has spent a lot of time studying a famous painting.","zh":"Curry 花了很多時間研究一幅著名畫作。"},{"en":"Spent a lot of time means used many hours or much effort doing something.","zh":"花了很多時間，是指用了許多小時或大量努力做某事。"},{"en":"A student may spend a lot of time preparing for an important speaking exam.","zh":"學生可能花很多時間準備重要口試。"},{"en":"Spending a lot of time on a task often leads to deeper understanding.","zh":"在任務上花很多時間通常會帶來更深入理解。"},{"en":"This phrase stresses effort and duration.","zh":"這個短語強調努力和時間長度。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":1},{"front":"perusing","meaning":"細看；仔細閱讀","examples":[{"en":"Curry has spent time perusing Leutze’s famous painting.","zh":"Curry 花時間細看 Leutze 的著名畫作。"},{"en":"Perusing means reading or looking at something carefully and thoughtfully.","zh":"細看或仔細閱讀，是指認真而細心地閱讀或觀看某物。"},{"en":"A lawyer may spend hours perusing a contract before signing it.","zh":"律師可能花幾小時仔細閱讀合約才簽署。"},{"en":"Perusing a painting slowly can reveal details that a quick glance misses.","zh":"慢慢細看一幅畫，可以發現匆匆一瞥會錯過的細節。"},{"en":"This word suggests careful attention, not casual looking.","zh":"這個詞暗示仔細注意，而不是隨便看。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":1},{"front":"famous painting","meaning":"著名畫作","examples":[{"en":"The famous painting depicts Washington crossing the Delaware.","zh":"這幅著名畫作描繪華盛頓橫渡特拉華河。"},{"en":"A famous painting is a work of art widely known by many people.","zh":"著名畫作是許多人廣泛認識的藝術作品。"},{"en":"The Mona Lisa is a famous painting that attracts visitors from around the world.","zh":"《蒙娜麗莎》是一幅吸引世界各地遊客的著名畫作。"},{"en":"Famous paintings can shape how people imagine historical events.","zh":"著名畫作可以塑造人們如何想像歷史事件。"},{"en":"This phrase describes a painting with public recognition.","zh":"這個短語描述有公眾知名度的畫。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":1},{"front":"George Washington Crossing the Delaware","meaning":"《華盛頓橫渡特拉華河》","examples":[{"en":"George Washington Crossing the Delaware depicts soldiers crossing a frozen river.","zh":"《華盛頓橫渡特拉華河》描繪士兵橫渡一條結冰河流。"},{"en":"George Washington Crossing the Delaware is a famous historical painting about the American Revolution.","zh":"《華盛頓橫渡特拉華河》是一幅關於美國革命的著名歷史畫作。"},{"en":"A history teacher might use George Washington Crossing the Delaware to discuss leadership and war imagery.","zh":"歷史老師可能用《華盛頓橫渡特拉華河》討論領導力和戰爭意象。"},{"en":"The painting matters here because its icy river helps introduce climate change.","zh":"這幅畫在此重要，因為其冰河有助引入氣候變化。"},{"en":"This title names a specific artwork, not the real event itself.","zh":"這個標題命名特定藝術作品，而不是事件本身。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":1},{"front":"depicts","meaning":"描繪","examples":[{"en":"The painting depicts colonial American soldiers crossing the river.","zh":"這幅畫描繪美國殖民地士兵橫渡河流。"},{"en":"Depicts means shows or represents something in a picture, story, or description.","zh":"描繪，是指在圖畫、故事或描述中展示或表現某事。"},{"en":"A textbook diagram depicts how water moves through the water cycle.","zh":"教科書圖表描繪水如何在水循環中移動。"},{"en":"A painting can depict an event in a dramatic way and influence public memory.","zh":"畫作可以以戲劇化方式描繪事件，並影響公眾記憶。"},{"en":"This verb is common when explaining what an image or text shows.","zh":"這個動詞常用於解釋圖像或文本展示甚麼。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":1},{"front":"a boatload of","meaning":"一船的……","examples":[{"en":"The painting depicts a boatload of colonial American soldiers.","zh":"這幅畫描繪一船美國殖民地士兵。"},{"en":"A boatload of people means enough people to fill a boat, or informally, a large group.","zh":"一船的人，是指足以裝滿一艘船的人，或非正式地指一大群人。"},{"en":"A boatload of tourists arrived at the small island in the morning.","zh":"一船遊客早上抵達小島。"},{"en":"A boatload of soldiers suggests a crowded boat moving together toward one purpose.","zh":"一船士兵暗示一艘擁擠的船正共同朝同一目的前進。"},{"en":"This phrase can be literal or casual, depending on the context.","zh":"這個短語可按字面或日常口語理解，視乎語境。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":1},{"front":"colonial American soldiers","meaning":"美國殖民地士兵","examples":[{"en":"The painting shows colonial American soldiers crossing the Delaware.","zh":"這幅畫顯示美國殖民地士兵橫渡特拉華河。"},{"en":"Colonial American soldiers were fighters from the American colonies before the United States became independent.","zh":"美國殖民地士兵，是美國獨立前來自殖民地的戰士。"},{"en":"In history class, students may learn how colonial American soldiers fought British forces.","zh":"在歷史課中，學生可能學習美國殖民地士兵如何與英軍作戰。"},{"en":"These soldiers are important because they represent the American Revolution.","zh":"這些士兵重要，因為他們代表美國革命。"},{"en":"This phrase refers to soldiers from colonial America, not modern U.S. troops.","zh":"這個短語指殖民地時期美國士兵，而不是現代美軍。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":1},{"front":"making their way to","meaning":"前往……","examples":[{"en":"The soldiers were making their way to attack enemy troops.","zh":"士兵正前往攻擊敵軍。"},{"en":"Making their way to a place means moving toward it, often with effort or difficulty.","zh":"前往某地，是指朝那裡移動，通常帶有努力或困難。"},{"en":"Students made their way to school through heavy rain.","zh":"學生在大雨中前往學校。"},{"en":"If people are making their way through snow or ice, the journey may be slow and dangerous.","zh":"如果人們正穿過雪地或冰面前往某處，旅程可能又慢又危險。"},{"en":"This phrase focuses on movement toward a destination.","zh":"這個短語聚焦朝目的地移動。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":1},{"front":"Hessian troops","meaning":"黑森僱傭兵","examples":[{"en":"The soldiers were going to attack English and Hessian troops.","zh":"士兵正前往攻擊英軍和黑森僱傭兵。"},{"en":"Hessian troops were German soldiers hired by Britain during the American Revolutionary War.","zh":"黑森僱傭兵是美國獨立戰爭期間由英國僱用的德國士兵。"},{"en":"A history lesson may explain why Britain used Hessian troops in America.","zh":"歷史課可能解釋英國為何在美洲使用黑森僱傭兵。"},{"en":"Mentioning Hessian troops helps identify the conflict and period in the painting.","zh":"提到黑森僱傭兵有助識別畫中的衝突和時期。"},{"en":"This phrase names a specific group of soldiers, not ordinary local fighters.","zh":"這個短語命名特定士兵群體，而不是普通本地戰士。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":1},{"front":"the day after Christmas","meaning":"聖誕節翌日","examples":[{"en":"The attack took place the day after Christmas in 1776.","zh":"這次攻擊發生於 1776 年聖誕節翌日。"},{"en":"The day after Christmas means December 26.","zh":"聖誕節翌日是指 12 月 26 日。"},{"en":"Many shops begin large sales the day after Christmas.","zh":"許多商店在聖誕節翌日開始大型減價。"},{"en":"An attack on the day after Christmas feels striking because people usually associate that time with rest.","zh":"聖誕節翌日發生攻擊令人印象深刻，因為人們通常把那段時間與休息聯繫起來。"},{"en":"This phrase gives a clear calendar reference.","zh":"這個短語給出清楚日曆時間。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":1},{"front":"rowing","meaning":"划船","examples":[{"en":"Most people think the men in the boat are rowing.","zh":"大多數人以為船上的男子正在划船。"},{"en":"Rowing means moving a boat through water by pulling oars.","zh":"划船是指透過拉動船槳使船在水中前進。"},{"en":"Students may learn rowing at a sports club on a calm river.","zh":"學生可能在平靜河上的體育會學划船。"},{"en":"Rowing requires rhythm because several people may need to pull together.","zh":"划船需要節奏，因為幾個人可能需要一起拉槳。"},{"en":"This word describes boat movement powered by human effort.","zh":"這個詞描述由人力推動的船隻移動。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":1},{"front":"pushing the ice away","meaning":"把冰推開","examples":[{"en":"The men are actually pushing the ice away.","zh":"這些男子其實正在把冰推開。"},{"en":"Pushing the ice away means moving ice aside so a boat can pass.","zh":"把冰推開，是指把冰移到一旁，讓船可以通過。"},{"en":"A person may push floating ice away from a small boat with a pole.","zh":"一個人可能用長杆把小船旁的浮冰推開。"},{"en":"Pushing ice away would be necessary if the river is too frozen for easy rowing.","zh":"如果河流結冰太多而難以划行，就需要把冰推開。"},{"en":"This phrase shows that the scene is colder and harder than it first appears.","zh":"這個短語顯示場景比初看時更寒冷、更困難。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":2},{"front":"tapping his finger on","meaning":"用手指輕敲……","examples":[{"en":"Curry tapped his finger on a reproduction of the painting.","zh":"Curry 用手指輕敲畫作複製品。"},{"en":"Tapping his finger on something means touching it lightly and repeatedly with a finger.","zh":"用手指輕敲某物，是指用手指輕而反覆地觸碰它。"},{"en":"A teacher may tap her finger on a word to show students where to look.","zh":"老師可能用手指輕敲某個字，示意學生看那裡。"},{"en":"Tapping can draw attention to a small detail without using many words.","zh":"輕敲可以不用太多說話就把注意力引到小細節。"},{"en":"This phrase describes a small pointing or attention-guiding action.","zh":"這個短語描述小型指示或引導注意的動作。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":2},{"front":"reproduction of the painting","meaning":"畫作複製品","examples":[{"en":"Curry pointed to a reproduction of the painting.","zh":"Curry 指着一幅畫作複製品。"},{"en":"A reproduction of a painting is a copy of the original artwork.","zh":"畫作複製品是一幅原作的副本。"},{"en":"A classroom may display a reproduction of a famous painting instead of the real one.","zh":"課室可能展示著名畫作的複製品，而不是原作。"},{"en":"Reproductions allow people to study details without needing access to the original work.","zh":"複製品讓人們不需要接觸原作也能研究細節。"},{"en":"This phrase refers to a copy, not the original painting.","zh":"這個短語指副本，而不是原始畫作。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":2},{"front":"sure enough","meaning":"果然","examples":[{"en":"Sure enough, the lead oarsman is pushing ice with his boot.","zh":"果然，領頭划槳手正用靴子推冰。"},{"en":"Sure enough means as expected, or confirming what someone has just said.","zh":"果然，是指如預期那樣，或證實某人剛說的話。"},{"en":"The teacher warned that the test would be difficult; sure enough, many students needed extra time.","zh":"老師警告測驗會很難；果然，許多學生需要額外時間。"},{"en":"This phrase is used when evidence proves a point right.","zh":"這個短語用於證據證明某個觀點正確時。"},{"en":"It often introduces confirmation after someone checks something.","zh":"它常在某人檢查某事後引入確認。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":2},{"front":"lead oarsman","meaning":"領頭划槳手","examples":[{"en":"The lead oarsman is bashing the frozen river with his boot.","zh":"領頭划槳手正用靴子猛擊結冰河流。"},{"en":"The lead oarsman is the main rower or front rowing figure in a boat.","zh":"領頭划槳手是船上的主要划槳者或前方划槳人物。"},{"en":"In a rowing team, the lead oarsman may help set the rhythm for others.","zh":"在划艇隊中，領頭划槳手可能幫助其他人建立節奏。"},{"en":"In the painting, the lead oarsman draws attention because he is dealing with the ice.","zh":"在畫中，領頭划槳手因正在處理冰而引人注意。"},{"en":"This phrase identifies a specific person in the boat scene.","zh":"這個短語識別船上場景中的特定人物。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":2},{"front":"bashing","meaning":"猛擊","examples":[{"en":"The lead oarsman is bashing the frozen river with his boot.","zh":"領頭划槳手正用靴子猛擊結冰河流。"},{"en":"Bashing means hitting something hard and repeatedly.","zh":"猛擊，是指用力且反覆打某物。"},{"en":"A mechanic may bash a stuck metal part gently with a tool to loosen it.","zh":"機械師可能用工具輕輕猛敲卡住的金屬零件，使它鬆開。"},{"en":"Bashing ice with a boot suggests force, urgency, and difficulty.","zh":"用靴子猛擊冰面暗示力度、急切和困難。"},{"en":"This word is stronger than simply touching or pushing.","zh":"這個詞比單純觸碰或推動更強。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":2},{"front":"frozen river","meaning":"結冰河流","examples":[{"en":"The painting shows soldiers crossing a frozen river.","zh":"這幅畫顯示士兵橫渡結冰河流。"},{"en":"A frozen river is a river whose surface has turned into ice because of very cold weather.","zh":"結冰河流是因天氣非常寒冷而表面變成冰的河流。"},{"en":"Children may be warned not to walk on a frozen river because the ice may break.","zh":"孩子可能被警告不要走上結冰河流，因為冰面可能破裂。"},{"en":"A frozen river can block boats and change how people travel.","zh":"結冰河流會阻礙船隻並改變人們出行方式。"},{"en":"This phrase signals severe winter conditions.","zh":"這個短語表示嚴寒冬季情況。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":2},{"front":"grew up in","meaning":"在……長大","examples":[{"en":"Curry grew up in Philadelphia.","zh":"Curry 在費城長大。"},{"en":"Grew up in a place means spent one’s childhood or early years there.","zh":"在某地長大，是指童年或早年在那裡度過。"},{"en":"A student who grew up in a village may know farming life well.","zh":"在村莊長大的學生可能很熟悉農村生活。"},{"en":"Where someone grew up can shape what they consider normal or unusual.","zh":"一個人成長的地方會塑造他認為甚麼正常或不尋常。"},{"en":"This phrase connects a person’s childhood with a place.","zh":"這個短語把人的童年與地方連接起來。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":2},{"front":"this kind of thing","meaning":"這種事情","examples":[{"en":"Curry says this kind of thing no longer happens there.","zh":"Curry 說這種事情在那裡已不再發生。"},{"en":"This kind of thing means this type of event, situation, or behaviour.","zh":"這種事情，是指這類事件、情況或行為。"},{"en":"A teacher may say, “This kind of thing happens when students rush their answers.”","zh":"老師可能說：「當學生匆忙回答時，這種事情就會發生。」"},{"en":"The phrase is useful when referring to an example without repeating all details.","zh":"這個短語適合在不重複所有細節時指回某個例子。"},{"en":"It sounds conversational and general.","zh":"它聽起來較口語和概括。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":2},{"front":"doesn’t happen anymore","meaning":"不再發生","examples":[{"en":"Frozen-river scenes like this do not happen anymore.","zh":"像這樣的冰河場景不再發生。"},{"en":"Doesn’t happen anymore means something used to happen but no longer does.","zh":"不再發生，是指某事以前會發生，但現在不會了。"},{"en":"In many cities, children playing freely in the street does not happen anymore as often as before.","zh":"在許多城市，孩子在街上自由玩耍不像以前那樣常發生了。"},{"en":"When climate changes, weather events that once happened may stop happening.","zh":"當氣候改變，曾經發生的天氣事件可能停止出現。"},{"en":"This phrase contrasts the past with the present.","zh":"這個短語對比過去和現在。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":2},{"front":"it may again soon","meaning":"它可能很快再次發生","examples":[{"en":"Curry suggests that such freezing may happen again soon.","zh":"Curry 暗示這種結冰可能很快再次發生。"},{"en":"It may again soon means something that stopped happening might return in the near future.","zh":"它可能很快再次發生，是指已停止出現的事情可能在不久將來回來。"},{"en":"If old flood patterns return, a village may face the same danger again soon.","zh":"如果舊有水浸模式回來，村莊可能很快再次面對相同危險。"},{"en":"This phrase creates a warning because the past may become relevant again.","zh":"這個短語帶有警告意味，因為過去可能再次變得相關。"},{"en":"It suggests possibility, not certainty.","zh":"它表示可能性，而不是確定性。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":2},{"front":"ice-choked scenes","meaning":"冰封堵塞的景象","examples":[{"en":"Ice-choked scenes may return to Europe.","zh":"冰封堵塞的景象可能重返歐洲。"},{"en":"Ice-choked scenes are views of places blocked, crowded, or filled with ice.","zh":"冰封堵塞的景象，是指被冰阻塞、擠滿或覆蓋的地方景象。"},{"en":"A harbour full of frozen water and trapped boats would be an ice-choked scene.","zh":"充滿冰水和被困船隻的海港，就是冰封堵塞的景象。"},{"en":"Such scenes can disrupt transport, trade, and ordinary winter life.","zh":"這類景象會擾亂交通、貿易和普通冬季生活。"},{"en":"This phrase creates an image of severe cold and obstruction.","zh":"這個短語營造嚴寒和阻塞的畫面。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":2},{"front":"similar to","meaning":"與……相似","examples":[{"en":"Ice-choked scenes similar to Brueghel’s paintings may return.","zh":"與 Brueghel 畫作相似的冰封景象可能會回來。"},{"en":"Similar to means like something else but not exactly the same.","zh":"與某物相似，是指像另一物，但不完全相同。"},{"en":"A school uniform may be similar to another school’s uniform but use different colours.","zh":"一間學校的校服可能與另一間學校的校服相似，但顏色不同。"},{"en":"Comparing one thing to a similar example helps readers picture it more clearly.","zh":"把某事與相似例子比較，有助讀者更清楚想像它。"},{"en":"This phrase shows resemblance.","zh":"這個短語表示相似性。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":2},{"front":"immortalised by","meaning":"由……永垂不朽地呈現","examples":[{"en":"Such winter scenes were immortalised by Pieter Brueghel the Elder.","zh":"這類冬季景象由 Pieter Brueghel the Elder 永垂不朽地呈現。"},{"en":"Immortalised by someone means made famous or remembered for a long time through that person’s work.","zh":"由某人永垂不朽地呈現，是指透過那人的作品而變得著名或長久被記住。"},{"en":"A small village may be immortalised by a novelist who sets a classic story there.","zh":"如果小說家把經典故事設於某小村，該村可能因此被永垂不朽地呈現。"},{"en":"Art can immortalise ordinary scenes by preserving them in public memory.","zh":"藝術可以透過把普通景象保存在公眾記憶中，使其長久流傳。"},{"en":"This phrase links lasting fame with artistic representation.","zh":"這個短語把持久名聲與藝術呈現連接起來。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":2},{"front":"Flemish painter","meaning":"佛蘭芒畫家","examples":[{"en":"Pieter Brueghel the Elder was a 16th-century Flemish painter.","zh":"Pieter Brueghel the Elder 是一位十六世紀佛蘭芒畫家。"},{"en":"A Flemish painter is an artist from Flanders, a historical region in northern Europe.","zh":"佛蘭芒畫家是來自佛蘭德斯這個北歐歷史地區的藝術家。"},{"en":"A museum label may describe an artist as a Flemish painter to show cultural origin.","zh":"博物館標籤可能把藝術家描述為佛蘭芒畫家，以顯示文化來源。"},{"en":"Knowing the painter’s background helps viewers understand the style and period of the work.","zh":"了解畫家背景有助觀眾理解作品風格和時期。"},{"en":"This phrase identifies both artistic profession and regional identity.","zh":"這個短語同時指出藝術職業和地區身份。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":3},{"front":"masterpiece","meaning":"傑作","examples":[{"en":"Hunters in the Snow is a 1565 masterpiece.","zh":"《雪中獵人》是一幅 1565 年的傑作。"},{"en":"A masterpiece is an excellent work of art, literature, music, or craft.","zh":"傑作是非常出色的藝術、文學、音樂或工藝作品。"},{"en":"A teacher may call a student’s final project a masterpiece if it is unusually careful and creative.","zh":"如果學生的期末作品異常細緻且有創意，老師可能稱它為傑作。"},{"en":"Masterpieces remain important because later generations still study and admire them.","zh":"傑作保持重要，是因為後世仍會研究和欣賞它們。"},{"en":"This word signals exceptional quality.","zh":"這個詞表示卓越品質。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":3},{"front":"Hunters in the Snow","meaning":"《雪中獵人》","examples":[{"en":"Hunters in the Snow shows a cold European landscape.","zh":"《雪中獵人》展示寒冷的歐洲景觀。"},{"en":"Hunters in the Snow is a famous painting by Pieter Brueghel the Elder.","zh":"《雪中獵人》是 Pieter Brueghel the Elder 的著名畫作。"},{"en":"An art teacher may use Hunters in the Snow to discuss winter imagery and daily life.","zh":"美術老師可能用《雪中獵人》討論冬季意象和日常生活。"},{"en":"The painting matters here because it shows Europe as colder than it usually is today.","zh":"這幅畫在此重要，因為它顯示歐洲比今日通常情況更寒冷。"},{"en":"This title names a specific artwork used as climate evidence in the passage.","zh":"這個標題命名篇章中用作氣候證據的特定藝術作品。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":3},{"front":"now-temperate European landscapes","meaning":"現今溫和的歐洲景觀","examples":[{"en":"The painting makes now-temperate European landscapes look much colder.","zh":"這幅畫令現今溫和的歐洲景觀看起來寒冷得多。"},{"en":"Now-temperate European landscapes are European places that currently have relatively mild climates.","zh":"現今溫和的歐洲景觀，是目前氣候相對溫和的歐洲地方。"},{"en":"A river that rarely freezes today may belong to a now-temperate European landscape.","zh":"今日很少結冰的河流，可能屬於現今溫和的歐洲景觀。"},{"en":"If old paintings show these places frozen, they may suggest past climate differences.","zh":"如果舊畫顯示這些地方結冰，它們可能暗示過去氣候差異。"},{"en":"This phrase contrasts present mildness with past cold.","zh":"這個短語對比現在的溫和與過去的寒冷。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":3},{"front":"look more like","meaning":"看起來更像……","examples":[{"en":"The landscapes look more like Lapland than modern Europe.","zh":"這些景觀看起來更像拉普蘭，而不是現代歐洲。"},{"en":"Look more like means resemble one thing more strongly than another.","zh":"看起來更像，是指外觀上更接近某物而不是另一物。"},{"en":"After heavy snow, a city street may look more like a ski resort than a business district.","zh":"大雪後，城市街道可能看起來更像滑雪度假村，而不是商業區。"},{"en":"This phrase helps readers compare appearances quickly.","zh":"這個短語幫助讀者快速比較外觀。"},{"en":"It often highlights a surprising resemblance.","zh":"它常突出令人意外的相似。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":3},{"front":"Lapland","meaning":"拉普蘭","examples":[{"en":"The frozen landscapes in the painting look more like Lapland.","zh":"畫中的冰封景觀看起來更像拉普蘭。"},{"en":"Lapland is a northern region associated with very cold weather, snow, and Arctic scenery.","zh":"拉普蘭是北方地區，常與嚴寒天氣、雪和北極景色聯繫起來。"},{"en":"Tourists visit Lapland to see snow, reindeer, and winter landscapes.","zh":"遊客到拉普蘭看雪、馴鹿和冬季景觀。"},{"en":"Comparing Europe to Lapland makes the old winter scenes sound extremely cold.","zh":"把歐洲比作拉普蘭，令舊時冬季景象聽起來極度寒冷。"},{"en":"This place name is used here as a symbol of severe northern cold.","zh":"這個地名在此用作嚴寒北方的象徵。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":3},{"front":"frigid settings","meaning":"嚴寒景象","examples":[{"en":"Such frigid settings were once commonplace in Europe.","zh":"這類嚴寒景象曾在歐洲很常見。"},{"en":"Frigid settings are extremely cold places or scenes.","zh":"嚴寒景象是極度寒冷的地方或場面。"},{"en":"A frozen harbour with snow-covered roofs creates a frigid setting.","zh":"結冰海港加上覆雪屋頂，形成嚴寒景象。"},{"en":"Frigid settings can shape clothing, travel, food supply, and daily routines.","zh":"嚴寒景象會塑造衣着、交通、食物供應和日常規律。"},{"en":"This phrase gives a strong image of intense cold.","zh":"這個短語給出強烈寒冷畫面。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":3},{"front":"commonplace","meaning":"常見的","examples":[{"en":"Frigid settings were commonplace during the little ice age.","zh":"嚴寒景象在小冰河時期很常見。"},{"en":"Commonplace means normal, frequent, or not unusual.","zh":"常見的，是指正常、頻繁或不罕見。"},{"en":"Online meetings became commonplace after many offices adopted remote work.","zh":"許多辦公室採用遙距工作後，網上會議變得很常見。"},{"en":"When something becomes commonplace, people stop treating it as surprising.","zh":"當某事變得常見，人們便不再覺得驚奇。"},{"en":"This word describes something ordinary in a particular time or place.","zh":"這個詞描述在特定時間或地方很普通的事物。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":3},{"front":"a period dating roughly from…to…","meaning":"大約由……至……的一段時期","examples":[{"en":"The little ice age was a period dating roughly from 1300 to 1850.","zh":"小冰河時期大約是由 1300 年至 1850 年的一段時期。"},{"en":"A period dating roughly from A to B means a time span that began around A and ended around B.","zh":"大約由 A 至 B 的一段時期，是指約在 A 開始並約在 B 結束的時間跨度。"},{"en":"The Industrial Revolution is often described as a period dating roughly from the late 1700s to the 1800s.","zh":"工業革命常被描述為大約由十八世紀末至十九世紀的一段時期。"},{"en":"The word roughly shows that the dates are approximate, not exact boundaries.","zh":"“roughly” 顯示日期是約略，而不是精確界線。"},{"en":"This phrase is useful for describing historical periods.","zh":"這個短語適合描述歷史時期。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":3},{"front":"in the throes of","meaning":"正處於……的困境中","examples":[{"en":"North America and Europe were in the throes of a little ice age.","zh":"北美和歐洲正處於小冰河時期的困境中。"},{"en":"In the throes of something means experiencing a difficult, intense, or active period of it.","zh":"正處於某事的困境中，是指正在經歷該事困難、強烈或活躍的時期。"},{"en":"A school may be in the throes of exam season when every classroom is busy.","zh":"當每間課室都很忙，學校可能正處於考試季的壓力中。"},{"en":"The phrase often suggests struggle, pressure, or major change.","zh":"這個短語常暗示掙扎、壓力或重大變化。"},{"en":"It is stronger than simply saying something is happening.","zh":"它比單純說某事正在發生更強烈。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":3},{"front":"little ice age","meaning":"小冰河時期","examples":[{"en":"Much of Europe and North America experienced a little ice age.","zh":"歐洲和北美大部分地區經歷了小冰河時期。"},{"en":"The little ice age was a historical period of cooler climate in parts of the Northern Hemisphere.","zh":"小冰河時期是北半球部分地區氣候較寒冷的歷史時期。"},{"en":"During a little ice age, rivers may freeze more often and growing seasons may become shorter.","zh":"在小冰河時期，河流可能更常結冰，農作季節可能縮短。"},{"en":"Colder conditions can affect food supply, transport, and ordinary life.","zh":"較寒冷情況會影響食物供應、交通和日常生活。"},{"en":"This phrase refers to a limited cooling period, not a full global ice age.","zh":"這個短語指有限的降溫時期，而不是完整全球冰河時期。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":3},{"front":"mounting evidence","meaning":"越來越多證據","examples":[{"en":"There is mounting evidence that the chill could return.","zh":"越來越多證據顯示寒冷可能會回來。"},{"en":"Mounting evidence means more and more information is supporting the same idea.","zh":"越來越多證據，是指越來越多資訊支持同一想法。"},{"en":"There is mounting evidence that poor sleep affects students’ memory and mood.","zh":"越來越多證據顯示睡眠不足會影響學生記憶和心情。"},{"en":"As evidence mounts, a warning becomes harder to dismiss.","zh":"隨着證據增加，警告變得更難被忽視。"},{"en":"This phrase suggests that support for a claim is growing.","zh":"這個短語暗示某主張的支持正在增加。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":3},{"front":"a growing number of scientists","meaning":"越來越多科學家","examples":[{"en":"A growing number of scientists believe another cooldown is possible.","zh":"越來越多科學家相信另一輪降溫是可能的。"},{"en":"A growing number of scientists means more scientists than before are accepting or considering an idea.","zh":"越來越多科學家，是指比以前更多科學家接受或考慮某個想法。"},{"en":"A growing number of doctors now support earlier screening for certain diseases.","zh":"越來越多醫生現在支持更早篩查某些疾病。"},{"en":"When expert support grows, a topic may receive more funding and public attention.","zh":"當專家支持增加，課題可能得到更多資金和公眾關注。"},{"en":"This phrase shows increasing professional interest or agreement.","zh":"這個短語顯示專業興趣或認同正在增加。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":3},{"front":"conditions are ripe for","meaning":"條件已成熟，可以……","examples":[{"en":"Some scientists believe conditions are ripe for another prolonged cooldown.","zh":"有些科學家認為條件已成熟，可能出現另一段長期降溫。"},{"en":"Conditions are ripe for something means the situation is suitable for it to happen.","zh":"條件已成熟可以發生某事，是指情況適合它發生。"},{"en":"If many students are tired and lessons are rushed, conditions are ripe for mistakes.","zh":"如果許多學生疲倦而課堂又匆忙，條件就成熟，容易出錯。"},{"en":"Conditions become ripe when several causes come together at the right time.","zh":"當幾個原因在合適時間共同出現，條件就變得成熟。"},{"en":"This phrase suggests readiness or strong possibility.","zh":"這個短語暗示準備狀態或很大可能性。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":3},{"front":"prolonged cooldown","meaning":"長期降溫","examples":[{"en":"Scientists warn of a possible prolonged cooldown.","zh":"科學家警告可能出現長期降溫。"},{"en":"A prolonged cooldown is a long-lasting period of lower temperatures.","zh":"長期降溫是一段持續很久的較低氣溫時期。"},{"en":"A prolonged cooldown could make farmers plant later and harvest less.","zh":"長期降溫可能令農民較遲播種並收成減少。"},{"en":"Long cooling matters more than a short cold spell because societies must adapt for years.","zh":"長期降溫比短暫寒潮更重要，因為社會必須多年適應。"},{"en":"This phrase describes sustained climate cooling.","zh":"這個短語描述持續的氣候降溫。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":4},{"front":"brutal ice sheet","meaning":"嚴酷冰蓋","examples":[{"en":"No one is predicting a brutal ice sheet like the ancient one.","zh":"沒有人預測會出現像古代那樣嚴酷的冰蓋。"},{"en":"A brutal ice sheet is a vast, severe mass of ice covering large areas of land.","zh":"嚴酷冰蓋是覆蓋大片陸地的巨大而嚴重冰層。"},{"en":"A brutal ice sheet would bury roads, forests, homes, and farms under thick ice.","zh":"嚴酷冰蓋會把道路、森林、房屋和農場埋在厚冰之下。"},{"en":"The phrase suggests extreme cold and destructive force.","zh":"這個短語暗示極端寒冷和破壞力。"},{"en":"It is used here to clarify that scientists are not predicting the worst ancient type of glaciation.","zh":"它在此用來澄清科學家不是預測最嚴重的古代冰川化。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":4},{"front":"covered the Northern Hemisphere","meaning":"覆蓋北半球","examples":[{"en":"An ice sheet once covered the Northern Hemisphere with glaciers.","zh":"一片冰蓋曾以冰川覆蓋北半球。"},{"en":"Covered the Northern Hemisphere means spread over large northern parts of the Earth.","zh":"覆蓋北半球，是指蔓延到地球北部大片地區。"},{"en":"During an ancient ice age, ice covered huge areas of North America and northern Europe.","zh":"在古代冰河時期，冰覆蓋北美和北歐大片地區。"},{"en":"If glaciers cover land, ecosystems and human settlement patterns change greatly.","zh":"如果冰川覆蓋陸地，生態系統和人類聚落模式會大幅改變。"},{"en":"This phrase describes enormous geographical coverage by ice.","zh":"這個短語描述冰的巨大地理覆蓋範圍。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":4},{"front":"glaciers","meaning":"冰川","examples":[{"en":"The Northern Hemisphere was once covered with glaciers.","zh":"北半球曾被冰川覆蓋。"},{"en":"Glaciers are huge slow-moving masses of ice formed from compacted snow.","zh":"冰川是由壓實積雪形成、緩慢移動的巨大冰體。"},{"en":"Mountain glaciers can carve valleys as they slowly move downhill.","zh":"山地冰川向下緩慢移動時，可以切割出山谷。"},{"en":"When glaciers melt, they add water to rivers and oceans.","zh":"當冰川融化，它們會向河流和海洋增加水量。"},{"en":"This word refers to natural ice bodies much larger than ordinary snowfields.","zh":"這個詞指比普通雪地大得多的天然冰體。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":4},{"front":"cooling trend","meaning":"降溫趨勢","examples":[{"en":"The next cooling trend could lower average temperatures.","zh":"下一個降溫趨勢可能降低平均氣溫。"},{"en":"A cooling trend is a pattern in which temperatures become lower over time.","zh":"降溫趨勢是氣溫隨時間變低的模式。"},{"en":"A city may notice a cooling trend if several winters become colder than usual.","zh":"如果幾個冬天都比平常寒冷，城市可能注意到降溫趨勢。"},{"en":"A cooling trend can affect heating demand, farming calendars, and wildlife.","zh":"降溫趨勢可以影響取暖需求、農業日程和野生動物。"},{"en":"This phrase describes a direction of change, not one cold day.","zh":"這個短語描述變化方向，而不是一天寒冷天氣。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":4},{"front":"drop average temperatures","meaning":"令平均氣溫下降","examples":[{"en":"The cooling trend could drop average temperatures by several degrees.","zh":"這個降溫趨勢可能令平均氣溫下降幾度。"},{"en":"To drop average temperatures means to cause the usual temperature level to fall.","zh":"令平均氣溫下降，是指造成一般氣溫水平降低。"},{"en":"A long cloudy period can drop average temperatures in a region.","zh":"長時間多雲天氣可以令某地區平均氣溫下降。"},{"en":"Even a few degrees of average cooling can affect crops and energy use.","zh":"即使平均降溫幾度，也能影響農作物和能源使用。"},{"en":"This phrase focuses on overall climate levels, not daily weather alone.","zh":"這個短語聚焦整體氣候水平，而不只是每日天氣。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":4},{"front":"degrees Fahrenheit","meaning":"華氏度","examples":[{"en":"The temperature could drop by 5 degrees Fahrenheit.","zh":"氣溫可能下降 5 華氏度。"},{"en":"Degrees Fahrenheit are units used to measure temperature, mainly in the United States.","zh":"華氏度是量度溫度的單位，主要在美國使用。"},{"en":"A weather report may say the temperature is 68 degrees Fahrenheit.","zh":"天氣報告可能說氣溫是 68 華氏度。"},{"en":"A change of several degrees Fahrenheit can feel noticeable in daily life.","zh":"幾華氏度的變化在日常生活中可以感覺明顯。"},{"en":"This phrase gives the measurement scale for temperature.","zh":"這個短語給出溫度量度單位。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":4},{"front":"over much of","meaning":"在……大部分地區","examples":[{"en":"Average temperatures could fall over much of the United States.","zh":"平均氣溫可能在美國大部分地區下降。"},{"en":"Over much of a place means across a large part of that area.","zh":"在某地大部分地區，是指橫跨該區域的很大部分。"},{"en":"Heavy rain fell over much of the city during the night.","zh":"夜間大雨落在城市大部分地區。"},{"en":"If a change happens over much of a country, millions of people may be affected.","zh":"如果變化發生在一個國家大部分地區，數百萬人可能受影響。"},{"en":"This phrase describes broad geographical coverage.","zh":"這個短語描述廣闊地理覆蓋。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":4},{"front":"northern Europe","meaning":"北歐","examples":[{"en":"The cooling trend could strongly affect northern Europe.","zh":"降溫趨勢可能強烈影響北歐。"},{"en":"Northern Europe means the northern part of Europe, including colder high-latitude regions.","zh":"北歐是指歐洲北部，包括較寒冷的高緯度地區。"},{"en":"Countries such as Norway, Sweden, and Finland are often associated with northern Europe.","zh":"挪威、瑞典和芬蘭等國常與北歐聯繫起來。"},{"en":"Climate shifts in northern Europe can affect forests, energy use, and winter transport.","zh":"北歐氣候變化會影響森林、能源使用和冬季交通。"},{"en":"This phrase identifies a broad European region.","zh":"這個短語指出歐洲的一個廣泛地區。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":4},{"front":"northern Asia","meaning":"北亞","examples":[{"en":"Northern Asia could experience a large temperature drop.","zh":"北亞可能經歷大幅氣溫下降。"},{"en":"Northern Asia means the northern part of Asia, including very cold regions such as Siberia.","zh":"北亞是指亞洲北部，包括西伯利亞等非常寒冷地區。"},{"en":"A cold wave in northern Asia can affect transport, heating, and energy demand.","zh":"北亞寒潮可以影響交通、取暖和能源需求。"},{"en":"Because northern Asia is already cold, further cooling could be especially difficult for communities.","zh":"因為北亞本來已經寒冷，進一步降溫對社區可能特別困難。"},{"en":"This phrase identifies a broad Asian region.","zh":"這個短語指出亞洲的一個廣泛地區。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":4},{"front":"chairs the department","meaning":"擔任……系主任","examples":[{"en":"Terrence Joyce chairs the Woods Hole Physical Oceanography Department.","zh":"Terrence Joyce 擔任 Woods Hole 物理海洋學系主任。"},{"en":"To chair a department means to lead or head that academic or professional unit.","zh":"擔任某系主任，是指領導或主管該學術或專業部門。"},{"en":"A professor who chairs a department may manage staff, budgets, and research direction.","zh":"擔任系主任的教授可能管理員工、預算和研究方向。"},{"en":"Chairing a department gives a scientist authority in that field.","zh":"擔任系主任令科學家在該領域有權威。"},{"en":"This phrase describes a leadership position.","zh":"這個短語描述領導職位。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":4},{"front":"physical oceanography","meaning":"物理海洋學","examples":[{"en":"Terrence Joyce works in physical oceanography.","zh":"Terrence Joyce 從事物理海洋學。"},{"en":"Physical oceanography is the study of ocean movement, temperature, salinity, currents, and waves.","zh":"物理海洋學是研究海洋運動、溫度、鹽度、洋流和波浪的學科。"},{"en":"Scientists use physical oceanography to understand how ocean currents affect climate.","zh":"科學家使用物理海洋學理解洋流如何影響氣候。"},{"en":"Changes in salinity and temperature matter because they can alter deep-water circulation.","zh":"鹽度和溫度變化很重要，因為它們能改變深海環流。"},{"en":"This phrase refers to the physics of the ocean.","zh":"這個短語指海洋的物理學研究。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":4},{"front":"take hundreds of years to reverse","meaning":"需要數百年才能逆轉","examples":[{"en":"Once the change happens, it can take hundreds of years to reverse.","zh":"一旦變化發生，可能需要數百年才能逆轉。"},{"en":"Take hundreds of years to reverse means require centuries to return to the earlier condition.","zh":"需要數百年才能逆轉，是指需要幾個世紀才能回到較早狀態。"},{"en":"Forest loss can take hundreds of years to reverse if old ecosystems disappear.","zh":"如果古老生態系統消失，森林損失可能需要數百年才能逆轉。"},{"en":"Slow reversal makes a change dangerous because people cannot fix it quickly.","zh":"逆轉緩慢令變化危險，因為人們不能迅速修復。"},{"en":"This phrase warns that some environmental changes are long-lasting.","zh":"這個短語警告有些環境變化會持續很久。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":4},{"front":"alarmed that","meaning":"對……感到憂慮","examples":[{"en":"Joyce is alarmed that Americans have not taken the threat seriously.","zh":"Joyce 對美國人尚未認真看待威脅感到憂慮。"},{"en":"Alarmed that means seriously worried because of a situation or fact.","zh":"對某事感到憂慮，是指因某情況或事實而嚴重擔心。"},{"en":"A teacher may be alarmed that many students have stopped reading outside class.","zh":"如果許多學生停止課外閱讀，老師可能感到憂慮。"},{"en":"People become alarmed when a risk seems serious but others ignore it.","zh":"當風險看似嚴重但其他人忽視它，人們會感到憂慮。"},{"en":"This phrase expresses strong concern.","zh":"這個短語表達強烈關注。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":4},{"front":"take the threat seriously","meaning":"認真看待威脅","examples":[{"en":"Many Americans have yet to take the threat seriously.","zh":"許多美國人仍未認真看待這項威脅。"},{"en":"To take the threat seriously means to recognise danger and respond with proper concern.","zh":"認真看待威脅，是指承認危險並以適當關注回應。"},{"en":"A school takes a fire risk seriously when it holds regular drills.","zh":"學校定期舉行消防演習，就是認真看待火警風險。"},{"en":"If people do not take a threat seriously, they may fail to prepare.","zh":"如果人們不認真看待威脅，就可能未能準備。"},{"en":"This phrase describes respectful attention to danger.","zh":"這個短語描述對危險的認真關注。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":5},{"front":"a drop of","meaning":"……的下降","examples":[{"en":"A drop of 5 to 10 degrees could have major effects.","zh":"5 至 10 度的下降可能產生重大影響。"},{"en":"A drop of a number means a decrease by that amount.","zh":"某數量的下降，是指減少該數量。"},{"en":"A drop of ten points in a test score may worry a teacher.","zh":"測驗分數下降十分可能令老師擔心。"},{"en":"Even a small drop in average temperature can affect crops if it lasts long enough.","zh":"如果持續足夠久，即使平均氣溫小幅下降也會影響農作物。"},{"en":"This phrase describes a measured decrease.","zh":"這個短語描述可量度的減少。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":5},{"front":"entails much more than","meaning":"意味着遠不止……","examples":[{"en":"A temperature drop entails much more than adjusting the thermostat.","zh":"氣溫下降意味着遠不止調整暖氣溫度。"},{"en":"Entails much more than means involves far more consequences than one simple action.","zh":"意味着遠不止某事，是指涉及比一個簡單行動更多後果。"},{"en":"Moving house entails much more than packing boxes; it also means changing bills, schools, and routines.","zh":"搬屋遠不止收拾箱子；它也意味着更改帳單、學校和生活規律。"},{"en":"Climate cooling entails wider effects because food, energy, and ecosystems are connected.","zh":"氣候降溫涉及更廣泛影響，因為食物、能源和生態系統互相連接。"},{"en":"This phrase warns that a problem is more complex than it first appears.","zh":"這個短語提醒問題比初看更複雜。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":5},{"front":"bumping up the thermostat","meaning":"調高暖氣溫度","examples":[{"en":"A colder climate means more than bumping up the thermostat.","zh":"更寒冷氣候意味着不只是調高暖氣溫度。"},{"en":"Bumping up the thermostat means increasing the heating setting slightly.","zh":"調高暖氣溫度，是指稍微提高供暖設定。"},{"en":"A family may bump up the thermostat on a cold night to make the room warmer.","zh":"家庭可能在寒冷夜晚調高暖氣溫度，令房間更暖。"},{"en":"If climate change affects crops and water, simply turning up the heat will not solve the problem.","zh":"如果氣候變化影響農作物和水源，單純調高暖氣不能解決問題。"},{"en":"This phrase describes a small household response to cold.","zh":"這個短語描述家庭對寒冷的小型回應。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":5},{"front":"carrying on","meaning":"照常生活","examples":[{"en":"People cannot simply adjust the thermostat and carry on.","zh":"人們不能只是調高暖氣並照常生活。"},{"en":"Carrying on means continuing as before.","zh":"照常生活或繼續下去，是指像以前一樣繼續。"},{"en":"After a minor mistake, a student may correct it and carry on with the exercise.","zh":"小錯後，學生可能改正並繼續完成練習。"},{"en":"People cannot always carry on normally when a problem changes basic living conditions.","zh":"當問題改變基本生活條件，人們未必能照常生活。"},{"en":"This phrase suggests continuing without major change.","zh":"這個短語暗示沒有重大改變地繼續。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":5},{"front":"economically and ecologically","meaning":"在經濟和生態方面","examples":[{"en":"The cooling could have serious effects economically and ecologically.","zh":"降溫可能在經濟和生態方面造成嚴重影響。"},{"en":"Economically and ecologically means in terms of money, industry, resources, and natural systems.","zh":"在經濟和生態方面，是指從金錢、產業、資源和自然系統角度來看。"},{"en":"A drought can harm a region economically and ecologically by reducing crops and damaging habitats.","zh":"乾旱會透過減少農作物和破壞棲息地，在經濟和生態方面傷害地區。"},{"en":"Climate shifts matter because they affect both human economies and natural ecosystems.","zh":"氣候變化重要，因為它同時影響人類經濟和自然生態系統。"},{"en":"This phrase links financial and environmental consequences.","zh":"這個短語連接財務和環境後果。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":5},{"front":"quick, persistent chilling","meaning":"快速而持續的寒冷","examples":[{"en":"Quick, persistent chilling could have devastating consequences.","zh":"快速而持續的寒冷可能造成災難性後果。"},{"en":"Quick, persistent chilling means fast cooling that continues over time.","zh":"快速而持續的寒冷，是指迅速降溫並持續一段時間。"},{"en":"If a growing region experiences quick, persistent chilling, crops may fail before harvest.","zh":"如果農作區經歷快速而持續的寒冷，農作物可能在收成前失敗。"},{"en":"Sudden and lasting cold is dangerous because people and ecosystems have little time to adapt.","zh":"突然且持久的寒冷很危險，因為人和生態系統幾乎沒有時間適應。"},{"en":"This phrase stresses both speed and duration.","zh":"這個短語同時強調速度和持續性。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":5},{"front":"devastating consequences","meaning":"災難性後果","examples":[{"en":"A sudden cooling could have devastating consequences.","zh":"突然降溫可能造成災難性後果。"},{"en":"Devastating consequences are extremely harmful results that cause major damage or suffering.","zh":"災難性後果是造成重大破壞或痛苦的極其有害結果。"},{"en":"A major flood can have devastating consequences for families who lose homes and jobs.","zh":"大型水災會對失去家園和工作的家庭造成災難性後果。"},{"en":"Consequences become devastating when they affect food, health, housing, and safety at once.","zh":"當後果同時影響食物、健康、住屋和安全，它們就變得災難性。"},{"en":"This phrase signals very serious results.","zh":"這個短語表示非常嚴重的結果。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":5},{"front":"Abrupt Climate Change","meaning":"《突發氣候變化》","examples":[{"en":"Abrupt Climate Change: Inevitable Surprises was a 2002 report.","zh":"《突發氣候變化：不可避免的意外》是一份 2002 年報告。"},{"en":"Abrupt climate change means sudden major change in climate rather than slow gradual change.","zh":"突發氣候變化，是指氣候突然出現重大變化，而不是慢慢逐步變化。"},{"en":"A sudden shift in rainfall patterns could be an example of abrupt climate change.","zh":"降雨模式突然轉變可以是突發氣候變化的例子。"},{"en":"Abrupt change is dangerous because farms, cities, and ecosystems may not adapt quickly.","zh":"突然變化很危險，因為農場、城市和生態系統可能無法迅速適應。"},{"en":"This phrase describes climate change that happens unexpectedly fast.","zh":"這個短語描述出乎意料地快速發生的氣候變化。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":5},{"front":"inevitable surprises","meaning":"不可避免的意外","examples":[{"en":"The report was titled Abrupt Climate Change: Inevitable Surprises.","zh":"該報告題為《突發氣候變化：不可避免的意外》。"},{"en":"Inevitable surprises are events that are hard to predict in detail but almost certain to occur in some form.","zh":"不可避免的意外，是細節難以預測但幾乎肯定會以某種形式發生的事件。"},{"en":"A school knows unexpected problems will happen during a trip; these are inevitable surprises.","zh":"學校知道旅行期間會出現意外問題；這些就是不可避免的意外。"},{"en":"Planning for inevitable surprises helps people respond better when shocks arrive.","zh":"為不可避免的意外作規劃，有助人們在衝擊到來時更好回應。"},{"en":"This phrase combines uncertainty with certainty.","zh":"這個短語結合不確定性與必然性。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":5},{"front":"produced by","meaning":"由……製作","examples":[{"en":"The report was produced by the National Academy of Sciences.","zh":"該報告由美國國家科學院製作。"},{"en":"Produced by means created, prepared, or published by a person or organisation.","zh":"由某人或組織製作，是指由其創作、準備或出版。"},{"en":"A safety guide produced by a hospital may explain how to prevent infection.","zh":"由醫院製作的安全指南可能解釋如何預防感染。"},{"en":"Knowing who produced a report helps readers judge its authority.","zh":"知道報告由誰製作，有助讀者判斷其權威性。"},{"en":"This phrase identifies the source or creator of a document.","zh":"這個短語指出文件的來源或創作者。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":5},{"front":"National Academy of Sciences","meaning":"美國國家科學院","examples":[{"en":"The National Academy of Sciences produced a report on abrupt climate change.","zh":"美國國家科學院製作了一份關於突發氣候變化的報告。"},{"en":"The National Academy of Sciences is a major scientific institution in the United States.","zh":"美國國家科學院是美國一個重要科學機構。"},{"en":"Policymakers may read a National Academy of Sciences report before making environmental decisions.","zh":"政策制定者在作出環境決定前，可能閱讀美國國家科學院報告。"},{"en":"A report from such an institution can carry weight because it reflects scientific expertise.","zh":"這類機構的報告有分量，因為它反映科學專業知識。"},{"en":"This phrase names an authoritative scientific organisation.","zh":"這個短語命名一個權威科學組織。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":5},{"front":"pegged the cost at","meaning":"將成本估算為","examples":[{"en":"The report pegged the cost from agricultural losses at up to $250 billion.","zh":"該報告將農業損失成本估算為高達 2,500 億美元。"},{"en":"Pegged the cost at means estimated or fixed the cost at a particular amount.","zh":"將成本估算為，是指把成本估計或定為某個金額。"},{"en":"The school pegged the cost of the new library at two million dollars.","zh":"學校將新圖書館成本估算為二百萬美元。"},{"en":"Cost estimates help people understand the scale of possible damage.","zh":"成本估算幫助人們理解可能損害的規模。"},{"en":"This phrase is common in reports about financial impact.","zh":"這個短語常見於關於財務影響的報告。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":5},{"front":"agricultural losses","meaning":"農業損失","examples":[{"en":"Abrupt climate change could cause huge agricultural losses.","zh":"突發氣候變化可能造成巨大農業損失。"},{"en":"Agricultural losses are damage or reductions in crops, livestock, farm income, or food production.","zh":"農業損失是農作物、牲畜、農場收入或糧食生產的損害或減少。"},{"en":"A drought can cause agricultural losses if farmers cannot water their fields.","zh":"如果農民無法灌溉田地，乾旱可能造成農業損失。"},{"en":"Agricultural losses can raise food prices and hurt rural communities.","zh":"農業損失會推高食物價格並傷害農村社區。"},{"en":"This phrase refers to farming-related damage.","zh":"這個短語指與農業相關的損害。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":5},{"front":"predicting that","meaning":"預測","examples":[{"en":"The report predicted that damage to ecosystems could be vast.","zh":"該報告預測對生態系統的破壞可能非常巨大。"},{"en":"Predicting that means saying something is likely to happen in the future.","zh":"預測某事，是指說某事將來可能發生。"},{"en":"A weather centre may predict that a storm will reach the coast by Friday.","zh":"天文台可能預測風暴會在星期五前到達海岸。"},{"en":"Predictions help people prepare, even though they may not be perfectly exact.","zh":"預測能幫助人們準備，即使未必完全精確。"},{"en":"This phrase introduces a forecast or expected result.","zh":"這個短語引入預報或預期結果。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":6},{"front":"damage to ecosystems","meaning":"對生態系統的破壞","examples":[{"en":"Abrupt climate change could cause vast damage to ecosystems.","zh":"突發氣候變化可能對生態系統造成巨大破壞。"},{"en":"Damage to ecosystems means harm to the plants, animals, habitats, and natural relationships in an area.","zh":"對生態系統的破壞，是指傷害某地區的植物、動物、棲息地和自然關係。"},{"en":"Pollution can cause damage to ecosystems by killing fish and poisoning water plants.","zh":"污染可以透過殺死魚類和毒害水生植物來破壞生態系統。"},{"en":"Ecosystem damage can reduce food, shelter, and survival chances for many species.","zh":"生態系統破壞會減少許多物種的食物、棲身處和生存機會。"},{"en":"This phrase describes harm to whole natural systems.","zh":"這個短語描述對整個自然系統的傷害。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":6},{"front":"vast and incalculable","meaning":"巨大且無法估量","examples":[{"en":"The damage to ecosystems could be vast and incalculable.","zh":"對生態系統的破壞可能巨大且無法估量。"},{"en":"Vast and incalculable means extremely large and impossible to measure exactly.","zh":"巨大且無法估量，是指極大而且不可能準確量度。"},{"en":"A major oil spill can cause vast and incalculable harm to marine life.","zh":"大型漏油可以對海洋生物造成巨大且無法估量的傷害。"},{"en":"Some damage is hard to calculate because effects spread through many systems over many years.","zh":"有些損害難以計算，因為影響會多年來擴散到許多系統。"},{"en":"This phrase stresses both size and uncertainty.","zh":"這個短語同時強調規模和不確定性。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":6},{"front":"a grim sampler","meaning":"一組嚴峻例子","examples":[{"en":"The report gives a grim sampler of possible consequences.","zh":"該報告給出一組可能後果的嚴峻例子。"},{"en":"A grim sampler is a small set of serious, worrying examples.","zh":"一組嚴峻例子，是一小組嚴重而令人擔心的例子。"},{"en":"A doctor’s report may give a grim sampler of health risks from smoking.","zh":"醫生報告可能給出一組吸煙健康風險的嚴峻例子。"},{"en":"Such examples can make an abstract danger feel real and urgent.","zh":"這類例子可以令抽象危險變得真實而緊迫。"},{"en":"This phrase suggests the full list may be even worse.","zh":"這個短語暗示完整列表可能更糟。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":6},{"front":"disappearing forests","meaning":"消失中的森林","examples":[{"en":"Disappearing forests could be one consequence of cooling.","zh":"消失中的森林可能是降溫的一個後果。"},{"en":"Disappearing forests are forests that are shrinking, dying, or being lost.","zh":"消失中的森林，是正在縮小、死亡或流失的森林。"},{"en":"Disappearing forests may leave animals without shelter and communities without resources.","zh":"消失中的森林可能令動物失去棲息地，社區失去資源。"},{"en":"Climate shifts can cause forests to disappear if trees cannot survive new conditions.","zh":"如果樹木無法在新環境中生存，氣候變化會令森林消失。"},{"en":"This phrase describes environmental loss.","zh":"這個短語描述環境損失。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":6},{"front":"increased housing expenses","meaning":"住屋開支增加","examples":[{"en":"A colder climate could lead to increased housing expenses.","zh":"更寒冷氣候可能導致住屋開支增加。"},{"en":"Increased housing expenses are higher costs for heating, repairs, rent, or maintaining a home.","zh":"住屋開支增加，是指取暖、維修、租金或維持住所的成本上升。"},{"en":"A family may face increased housing expenses if winter heating bills rise sharply.","zh":"如果冬季取暖費急升，家庭可能面對住屋開支增加。"},{"en":"Colder weather can increase housing costs because homes need more insulation and energy.","zh":"更寒冷天氣會增加住房成本，因為房屋需要更多隔熱和能源。"},{"en":"This phrase connects climate or economic change with household costs.","zh":"這個短語把氣候或經濟變化與家庭成本連接起來。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":6},{"front":"dwindling fresh water","meaning":"淡水減少","examples":[{"en":"Abrupt climate change could cause dwindling fresh water supplies.","zh":"突發氣候變化可能導致淡水供應減少。"},{"en":"Dwindling fresh water means clean usable water is becoming less available.","zh":"淡水減少，是指乾淨可用的水變得較少。"},{"en":"A village may face dwindling fresh water if wells dry up after years of drought.","zh":"如果多年乾旱後水井乾涸，村莊可能面對淡水減少。"},{"en":"Less fresh water can affect drinking, farming, hygiene, and health.","zh":"淡水減少會影響飲水、農業、衛生和健康。"},{"en":"This phrase describes a shrinking essential resource.","zh":"這個短語描述基本資源縮減。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":6},{"front":"lower crop yields","meaning":"農作物產量下降","examples":[{"en":"Climate change could lead to lower crop yields.","zh":"氣候變化可能導致農作物產量下降。"},{"en":"Lower crop yields mean farmers produce less food from the same land.","zh":"農作物產量下降，是指農民從同一土地生產較少食物。"},{"en":"A cold spring can cause lower crop yields if seeds fail to grow properly.","zh":"如果種子無法正常生長，寒冷春天會造成農作物產量下降。"},{"en":"Lower yields can raise food prices and reduce farmers’ income.","zh":"產量下降會推高食物價格並減少農民收入。"},{"en":"This phrase refers to reduced agricultural output.","zh":"這個短語指農業產出減少。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":6},{"front":"accelerated species extinctions","meaning":"物種加速滅絕","examples":[{"en":"Rapid cooling could cause accelerated species extinctions.","zh":"快速降溫可能造成物種加速滅絕。"},{"en":"Accelerated species extinctions are faster-than-normal disappearances of animal or plant species.","zh":"物種加速滅絕，是動植物物種以比平常更快速度消失。"},{"en":"If habitats change too quickly, some species may die out before they can adapt.","zh":"如果棲息地變化太快，有些物種可能在適應前滅絕。"},{"en":"Faster extinctions reduce biodiversity and weaken ecosystems.","zh":"滅絕加速會減少生物多樣性並削弱生態系統。"},{"en":"This phrase describes an alarming speed-up in species loss.","zh":"這個短語描述物種流失令人憂慮地加速。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":6},{"front":"huge effects","meaning":"巨大影響","examples":[{"en":"The reason for such huge effects is simple.","zh":"這類巨大影響的原因很簡單。"},{"en":"Huge effects are very large or serious results caused by an event or process.","zh":"巨大影響，是由事件或過程造成的非常大或嚴重結果。"},{"en":"A small error in a medical dose can have huge effects on a patient’s safety.","zh":"醫療劑量中的小錯誤可以對病人安全造成巨大影響。"},{"en":"Climate changes can have huge effects because many systems depend on stable conditions.","zh":"氣候變化會有巨大影響，因為許多系統依賴穩定條件。"},{"en":"This phrase emphasises the size of the consequences.","zh":"這個短語強調後果的規模。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":6},{"front":"wreaks far more disruption than","meaning":"比……造成更大破壞","examples":[{"en":"A quick climate change wreaks far more disruption than a slow one.","zh":"快速氣候變化比緩慢氣候變化造成更大破壞。"},{"en":"Wreaks far more disruption than means causes much more serious disturbance than something else.","zh":"比某事造成更大破壞，是指造成遠比另一事物更嚴重的干擾。"},{"en":"A sudden school closure wreaks far more disruption than a planned holiday.","zh":"學校突然停課比已安排假期造成更大破壞。"},{"en":"Fast change is disruptive because people have less time to prepare.","zh":"快速變化具破壞性，因為人們較少時間準備。"},{"en":"This phrase compares the damage caused by two situations.","zh":"這個短語比較兩種情況造成的損害。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":6},{"front":"depend on","meaning":"依賴","examples":[{"en":"Economies depend on people, animals and plants.","zh":"經濟依賴人、動物和植物。"},{"en":"Depend on means need something in order to function, survive, or succeed.","zh":"依賴，是指需要某物才能運作、生存或成功。"},{"en":"Students depend on clear instructions when preparing for exams.","zh":"學生準備考試時依賴清晰指示。"},{"en":"If farms depend on stable weather, sudden climate change can damage food supply.","zh":"如果農場依賴穩定天氣，突然氣候變化會損害食物供應。"},{"en":"This phrase describes reliance.","zh":"這個短語描述倚靠關係。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":6},{"front":"pose few problems","meaning":"造成很少問題","examples":[{"en":"High water may pose few problems until it crosses a threshold.","zh":"高水位在越過臨界點前可能造成很少問題。"},{"en":"Pose few problems means cause little difficulty or danger.","zh":"造成很少問題，是指引起很少困難或危險。"},{"en":"A small delay may pose few problems if everyone still arrives before the exam.","zh":"如果所有人仍能在考試前到達，小延誤可能造成很少問題。"},{"en":"A situation can seem harmless until it passes a critical limit.","zh":"一個情況在超過關鍵限制前可能看似無害。"},{"en":"This phrase shows that danger may depend on degree.","zh":"這個短語顯示危險可能取決於程度。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":6},{"front":"runs over the bank","meaning":"漫過河岸","examples":[{"en":"Flooding begins when river water runs over the bank.","zh":"當河水漫過河岸，水浸便開始。"},{"en":"Runs over the bank means water rises above the side of a river and spills onto nearby land.","zh":"漫過河岸，是指水位升過河邊並溢到附近土地。"},{"en":"After heavy rain, the stream may run over the bank and flood the road.","zh":"大雨後，小溪可能漫過河岸並淹沒道路。"},{"en":"Once water runs over the bank, damage can increase quickly.","zh":"一旦水漫過河岸，破壞會迅速增加。"},{"en":"This phrase describes the moment a river overflow starts.","zh":"這個短語描述河流開始泛濫的一刻。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":6},{"front":"levees","meaning":"堤壩","examples":[{"en":"Levees can be breached during massive flooding.","zh":"堤壩在大規模水浸期間可能被沖破。"},{"en":"Levees are raised banks or walls built to stop river or sea water from flooding land.","zh":"堤壩是為阻止河水或海水淹沒土地而建的高起河岸或牆。"},{"en":"A town near a river may build levees to protect homes during storms.","zh":"靠近河流的城鎮可能建造堤壩，以在暴風雨期間保護房屋。"},{"en":"If levees fail, water can rush into areas people thought were safe.","zh":"如果堤壩失效，水會湧入人們以為安全的地區。"},{"en":"This word refers to flood-control structures.","zh":"這個詞指防洪結構。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":7},{"front":"be breached","meaning":"被沖破","examples":[{"en":"Levees can be breached when water rises too high.","zh":"當水位升得太高，堤壩可能被沖破。"},{"en":"To be breached means to be broken through or crossed by force.","zh":"被沖破，是指被力量突破或越過。"},{"en":"A fence may be breached if a crowd pushes through it.","zh":"如果人群推開圍欄，圍欄可能被突破。"},{"en":"When a levee is breached, floodwater can spread very quickly.","zh":"當堤壩被沖破，洪水會迅速擴散。"},{"en":"This phrase describes a protective barrier failing.","zh":"這個短語描述保護屏障失效。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":7},{"front":"massive flooding","meaning":"大規模水浸","examples":[{"en":"Massive flooding can occur when levees are breached.","zh":"當堤壩被沖破，可能出現大規模水浸。"},{"en":"Massive flooding is very large-scale flooding that covers wide areas and causes serious damage.","zh":"大規模水浸是覆蓋廣泛地區並造成嚴重破壞的大型水災。"},{"en":"Massive flooding may close schools, damage homes, and stop transport.","zh":"大規模水浸可能令學校停課、房屋受損並中斷交通。"},{"en":"Broken levees can turn high water into massive flooding.","zh":"被沖破的堤壩可以把高水位變成大規模水浸。"},{"en":"This phrase describes severe water disaster.","zh":"這個短語描述嚴重水災。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":7},{"front":"biological processes","meaning":"生物過程","examples":[{"en":"Many biological processes undergo shifts at climate thresholds.","zh":"許多生物過程會在氣候臨界點經歷轉變。"},{"en":"Biological processes are natural activities in living things, such as growth, reproduction, migration, and flowering.","zh":"生物過程是生命體中的自然活動，例如生長、繁殖、遷徙和開花。"},{"en":"A plant’s flowering time is a biological process affected by temperature.","zh":"植物開花時間是受氣溫影響的生物過程。"},{"en":"If climate crosses a threshold, biological processes may change suddenly.","zh":"如果氣候越過臨界點，生物過程可能突然改變。"},{"en":"This phrase refers to how living systems function.","zh":"這個短語指生命系統如何運作。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":7},{"front":"undergo shifts","meaning":"經歷轉變","examples":[{"en":"Biological processes undergo shifts at particular thresholds.","zh":"生物過程會在特定臨界點經歷轉變。"},{"en":"To undergo shifts means to experience changes, often important or noticeable ones.","zh":"經歷轉變，是指經歷變化，通常是重要或明顯的變化。"},{"en":"A student’s study habits may undergo shifts after moving to a new school.","zh":"學生轉到新學校後，學習習慣可能經歷轉變。"},{"en":"Systems undergo shifts when pressure reaches a level that changes how they behave.","zh":"當壓力達到改變行為的水平，系統就會經歷轉變。"},{"en":"This phrase focuses on change happening to a process or system.","zh":"這個短語聚焦過程或系統正在發生變化。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":7},{"front":"particular thresholds","meaning":"特定臨界點","examples":[{"en":"Temperature and precipitation can reach particular thresholds.","zh":"氣溫和降水可以達到特定臨界點。"},{"en":"Particular thresholds are specific points where a small further change can create a big effect.","zh":"特定臨界點是進一步小變化就能造成大影響的具體界線。"},{"en":"A river reaches a threshold when one more hour of rain makes it overflow.","zh":"當再下一小時雨就令河流泛濫時，河流達到臨界點。"},{"en":"Thresholds matter because systems may behave differently after crossing them.","zh":"臨界點重要，因為系統越過後可能以不同方式運作。"},{"en":"This phrase describes critical limits.","zh":"這個短語描述關鍵限制。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":7},{"front":"precipitation","meaning":"降水","examples":[{"en":"Many biological processes depend on temperature and precipitation.","zh":"許多生物過程依賴氣溫和降水。"},{"en":"Precipitation is water that falls from the sky, such as rain, snow, sleet, or hail.","zh":"降水是從天空落下的水，例如雨、雪、雨夾雪或冰雹。"},{"en":"Farmers watch precipitation carefully because crops need enough water.","zh":"農民密切留意降水，因為農作物需要足夠水分。"},{"en":"Too little or too much precipitation can damage ecosystems and food production.","zh":"降水太少或太多都會損害生態系統和糧食生產。"},{"en":"This word is a scientific term for falling water.","zh":"這個詞是指從天空落下的水的科學用語。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":7},{"front":"political changes","meaning":"政治變化","examples":[{"en":"Political changes could make survival more difficult.","zh":"政治變化可能令生存更困難。"},{"en":"Political changes are shifts in laws, borders, governments, rights, or public policies.","zh":"政治變化是法律、邊界、政府、權利或公共政策的轉變。"},{"en":"New visa rules are political changes that can affect workers and families.","zh":"新簽證規則是會影響工人和家庭的政治變化。"},{"en":"Political changes matter in climate crises because they can limit movement and aid.","zh":"政治變化在氣候危機中很重要，因為它們會限制移動和援助。"},{"en":"This phrase connects government decisions with daily survival.","zh":"這個短語把政府決策與日常生存連接起來。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":7},{"front":"since the last ice age","meaning":"自上一次冰河時期以來","examples":[{"en":"Political changes since the last ice age could affect survival.","zh":"自上一次冰河時期以來的政治變化可能影響生存。"},{"en":"Since the last ice age means during the long period after the most recent major glacial age.","zh":"自上一次冰河時期以來，是指最近一次主要冰川時代之後的漫長時期。"},{"en":"Human societies have built borders, cities, and governments since the last ice age.","zh":"自上一次冰河時期以來，人類社會建立了邊界、城市和政府。"},{"en":"Modern political systems can make ancient survival strategies harder to use.","zh":"現代政治制度會令古代生存策略更難使用。"},{"en":"This phrase creates a long historical comparison.","zh":"這個短語建立長期歷史比較。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":7},{"front":"make survival far more difficult","meaning":"令生存困難得多","examples":[{"en":"Closed borders could make survival far more difficult for the poor.","zh":"邊境封閉可能令貧困人口生存困難得多。"},{"en":"To make survival far more difficult means to greatly reduce people’s ability to stay alive or maintain basic life.","zh":"令生存困難得多，是指大大降低人們維持生命或基本生活的能力。"},{"en":"A blocked road can make survival far more difficult after a flood if food cannot arrive.","zh":"水災後如果食物無法送達，被阻塞道路會令生存困難得多。"},{"en":"When people cannot move away from danger, survival becomes harder.","zh":"當人們不能離開危險，生存會變得更困難。"},{"en":"This phrase describes a serious increase in life-threatening difficulty.","zh":"這個短語描述威脅生命的困難大幅增加。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":7},{"front":"the world’s poor","meaning":"全球貧困人口","examples":[{"en":"The world’s poor may suffer most from abrupt climate change.","zh":"全球貧困人口可能最受突發氣候變化影響。"},{"en":"The world’s poor are people globally who lack enough money, resources, or security.","zh":"全球貧困人口，是世界各地缺乏足夠金錢、資源或保障的人。"},{"en":"The world’s poor often have fewer savings, weaker housing, and less access to healthcare.","zh":"全球貧困人口通常儲蓄較少、住房較脆弱，醫療服務較難取得。"},{"en":"Climate shocks hurt poor communities most because they have fewer safety nets.","zh":"氣候衝擊最傷害貧困社區，因為他們安全網較少。"},{"en":"This phrase refers to poor people worldwide, not one country only.","zh":"這個短語指全球窮人，而不只是一個國家的人。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":7},{"front":"cooling periods","meaning":"降溫時期","examples":[{"en":"During previous cooling periods, whole tribes moved south.","zh":"在以往降溫時期，整個部落會向南遷移。"},{"en":"Cooling periods are times when climate becomes colder for a while.","zh":"降溫時期是氣候一段時間內變得較寒冷的時期。"},{"en":"During cooling periods, farmers may change crops or move animals to warmer areas.","zh":"在降溫時期，農民可能改種農作物或把動物移到較暖地區。"},{"en":"Cooling periods can force people to adapt, migrate, or change food sources.","zh":"降溫時期會迫使人們適應、遷移或改變食物來源。"},{"en":"This phrase describes colder phases in climate history.","zh":"這個短語描述氣候歷史中的較冷階段。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":7},{"front":"picked up and moved south","meaning":"收拾行裝向南遷移","examples":[{"en":"Whole tribes simply picked up and moved south.","zh":"整個部落只是收拾行裝向南遷移。"},{"en":"Picked up and moved south means left a place and migrated toward warmer southern areas.","zh":"收拾行裝向南遷移，是指離開一個地方，遷往較溫暖的南方地區。"},{"en":"A family may pick up and move to another city when work disappears locally.","zh":"當本地工作消失，家庭可能收拾行裝搬到另一個城市。"},{"en":"Moving south could once help people escape cold, hunger, or danger.","zh":"向南遷移曾可幫助人們逃避寒冷、飢餓或危險。"},{"en":"This phrase suggests leaving with one’s belongings and starting elsewhere.","zh":"這個短語暗示帶着家當離開並在別處重新開始。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":7},{"front":"that option doesn’t work","meaning":"這個選擇行不通","examples":[{"en":"That option does not work in the modern world.","zh":"這個選擇在現代世界行不通。"},{"en":"That option doesn’t work means that choice is not practical or effective.","zh":"這個選擇行不通，是指該選擇不實際或無效。"},{"en":"If buses stop running, walking twenty kilometres to school does not work for most students.","zh":"如果巴士停駛，對大多數學生來說步行二十公里上學行不通。"},{"en":"An old solution may stop working when laws, borders, or social conditions change.","zh":"當法律、邊界或社會條件改變，舊解決方法可能不再可行。"},{"en":"This phrase rejects a possible solution as unsuitable.","zh":"這個短語否定某可能方案不合適。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":7},{"front":"tense world of closed borders","meaning":"邊境封閉、局勢緊張的現代世界","examples":[{"en":"Migration is difficult in the modern, tense world of closed borders.","zh":"在邊境封閉、局勢緊張的現代世界，遷移很困難。"},{"en":"A tense world of closed borders is a political situation where countries restrict movement and relations feel strained.","zh":"邊境封閉、局勢緊張的世界，是國家限制流動且關係緊繃的政治情況。"},{"en":"Refugees may struggle in a tense world of closed borders because safe entry becomes harder.","zh":"在邊境封閉的緊張世界中，難民可能很困難，因為安全入境變得更難。"},{"en":"Closed borders can turn migration from a survival strategy into a political problem.","zh":"邊境封閉會把遷移由生存策略變成政治問題。"},{"en":"This phrase contrasts modern restrictions with older freedom to move.","zh":"這個短語對比現代限制與古代較自由的移動。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":8},{"front":"to the extent that","meaning":"在……程度上","examples":[{"en":"To the extent that climate change affects livelihoods, migration becomes important.","zh":"在氣候變化影響生計的程度上，遷移變得重要。"},{"en":"To the extent that means as far as, or in proportion to how much something is true.","zh":"在某程度上，是指就某事為真的範圍或比例而言。"},{"en":"To the extent that students lack sleep, their concentration may suffer.","zh":"在學生睡眠不足的程度上，他們的專注力可能受損。"},{"en":"This phrase links the strength of one effect to the degree of another condition.","zh":"這個短語把一種影響的強度與另一條件的程度連接起來。"},{"en":"It is useful for careful, qualified statements.","zh":"它適合用於謹慎而有限定的陳述。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":8},{"front":"rapid and extensive changes of fortune","meaning":"命運的快速而廣泛轉變","examples":[{"en":"Abrupt climate change may cause rapid and extensive changes of fortune.","zh":"突發氣候變化可能造成命運的快速而廣泛轉變。"},{"en":"Rapid and extensive changes of fortune are sudden, wide-reaching shifts in people’s wealth, security, or living conditions.","zh":"命運的快速而廣泛轉變，是人們財富、安全或生活條件突然且廣泛改變。"},{"en":"A fishing town may suffer a rapid change of fortune if the sea suddenly yields fewer fish.","zh":"如果海中魚量突然減少，漁村可能遭遇命運的快速轉變。"},{"en":"Such changes are dangerous because families may lose income before they can adapt.","zh":"這類轉變危險，因為家庭可能在適應前已失去收入。"},{"en":"This phrase describes major life changes affecting many people quickly.","zh":"這個短語描述迅速影響許多人的重大生活變化。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":8},{"front":"live off the land","meaning":"靠土地維生","examples":[{"en":"People who live off the land may be badly affected.","zh":"靠土地維生的人可能受到嚴重影響。"},{"en":"To live off the land means to survive mainly by farming, hunting, fishing, or gathering natural resources.","zh":"靠土地維生，是指主要透過耕作、狩獵、捕魚或採集自然資源來生存。"},{"en":"A rural family may live off the land by growing vegetables and keeping animals.","zh":"農村家庭可能透過種菜和飼養動物靠土地維生。"},{"en":"Climate change can hurt people who live off the land because their food depends directly on nature.","zh":"氣候變化會傷害靠土地維生的人，因為他們的食物直接依賴自然。"},{"en":"This phrase describes close dependence on local natural resources.","zh":"這個短語描述對本地自然資源的密切依賴。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":8},{"front":"inability to migrate","meaning":"無法遷移","examples":[{"en":"The inability to migrate may remove a major safety net.","zh":"無法遷移可能移除一個主要安全網。"},{"en":"Inability to migrate means people cannot move to another place when conditions become dangerous or unlivable.","zh":"無法遷移，是指當環境變得危險或不宜居時，人們不能搬到另一地方。"},{"en":"A family’s inability to migrate may trap them in an area with no work or water.","zh":"家庭無法遷移，可能令他們被困在沒有工作或水源的地區。"},{"en":"If people cannot migrate, they lose one traditional way of escaping crisis.","zh":"如果人們不能遷移，他們就失去一種逃避危機的傳統方式。"},{"en":"This phrase describes a lack of movement as a serious vulnerability.","zh":"這個短語描述不能移動是一種嚴重脆弱性。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":8},{"front":"remove one of","meaning":"移除其中一個……","examples":[{"en":"The inability to migrate may remove one of the major safety nets.","zh":"無法遷移可能移除其中一個主要安全網。"},{"en":"Remove one of something means take away one item from a larger group.","zh":"移除其中一個某物，是指從較大群組中拿走一項。"},{"en":"Closing a library may remove one of the few quiet study places in a neighbourhood.","zh":"關閉圖書館可能移除社區中少數安靜學習地點之一。"},{"en":"Removing one support can make people more vulnerable when other supports are weak.","zh":"當其他支援薄弱，移除其中一項支援會令人更脆弱。"},{"en":"This phrase shows loss of an important option.","zh":"這個短語顯示重要選項的喪失。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":8},{"front":"major safety nets","meaning":"主要安全網","examples":[{"en":"Migration was once a major safety net for distressed people.","zh":"遷移曾是受困苦人士的一個主要安全網。"},{"en":"Major safety nets are important protections that help people survive during crisis.","zh":"主要安全網是幫助人們在危機中生存的重要保護。"},{"en":"Savings, family support, and public healthcare can be major safety nets.","zh":"儲蓄、家庭支援和公共醫療都可以是主要安全網。"},{"en":"Without safety nets, a sudden shock can push vulnerable people into danger quickly.","zh":"沒有安全網，突然衝擊會很快把弱勢人士推入危險。"},{"en":"This phrase describes systems or options that reduce risk.","zh":"這個短語描述降低風險的系統或選項。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":8},{"front":"distressed people","meaning":"受困苦的人","examples":[{"en":"Abrupt climate change may leave distressed people without options.","zh":"突發氣候變化可能令受困苦的人沒有選擇。"},{"en":"Distressed people are people suffering from serious worry, hardship, danger, or need.","zh":"受困苦的人，是承受嚴重憂慮、困難、危險或需要的人。"},{"en":"After a flood, distressed people may need food, shelter, medicine, and information.","zh":"水災後，受困苦的人可能需要食物、住所、藥物和資訊。"},{"en":"Distress becomes worse when people cannot leave danger or receive support.","zh":"當人們不能離開危險或獲得支援，困苦會加劇。"},{"en":"This phrase describes people under serious pressure.","zh":"這個短語描述承受嚴重壓力的人。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":8},{"front":"first things first","meaning":"首要問題先處理","examples":[{"en":"But first things first: is the Earth actually warming?","zh":"但首要問題先處理：地球是否真的正在變暖？"},{"en":"First things first means the most basic or important question should be dealt with before anything else.","zh":"首要問題先處理，是指最基本或最重要問題應先處理。"},{"en":"Before choosing a course, first things first: what is your goal?","zh":"在選課前，首要問題先處理：你的目標是甚麼？"},{"en":"This phrase helps organise thinking by starting with the foundation.","zh":"這個短語透過先處理基礎來幫助整理思路。"},{"en":"It is often used before returning to a key basic issue.","zh":"它常用於回到關鍵基本問題前。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":8},{"front":"actually warming","meaning":"實際上正在變暖","examples":[{"en":"The Earth is actually warming, according to Joyce.","zh":"根據 Joyce 的說法，地球實際上正在變暖。"},{"en":"Actually warming means really becoming warmer, even if the later result may seem surprising.","zh":"實際上正在變暖，是指真的變得更暖，即使之後結果可能令人意外。"},{"en":"A room may be actually warming even if one corner still feels cold.","zh":"即使房間一角仍感覺寒冷，整個房間可能實際上正在變暖。"},{"en":"In the passage, actual warming is important because it may paradoxically lead to cooling elsewhere.","zh":"在篇章中，實際變暖很重要，因為它可能反常地導致其他地方降溫。"},{"en":"This phrase confirms warming as a real process.","zh":"這個短語確認變暖是真實過程。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":8},{"front":"cluttered office","meaning":"雜亂的辦公室","examples":[{"en":"Joyce explained the theory in his cluttered office.","zh":"Joyce 在他雜亂的辦公室解釋這個理論。"},{"en":"A cluttered office is a workplace full of papers, books, equipment, or objects in a messy way.","zh":"雜亂的辦公室，是充滿文件、書籍、設備或物件而顯得凌亂的工作場所。"},{"en":"A scientist’s cluttered office may contain maps, reports, samples, and old notes.","zh":"科學家的雜亂辦公室可能有地圖、報告、樣本和舊筆記。"},{"en":"Clutter can make a place look busy, though not necessarily unproductive.","zh":"雜亂會令地方看似忙碌，但不一定代表沒有生產力。"},{"en":"This phrase describes a messy working environment.","zh":"這個短語描述凌亂的工作環境。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":8},{"front":"Cape Cod","meaning":"科德角","examples":[{"en":"Joyce’s office was on a foggy Cape Cod morning.","zh":"Joyce 的辦公室位於一個霧濛濛的科德角早晨。"},{"en":"Cape Cod is a coastal region in Massachusetts in the northeastern United States.","zh":"科德角是美國東北部麻省的一個沿海地區。"},{"en":"A foggy Cape Cod morning may make the sea and shoreline look grey and quiet.","zh":"霧濛濛的科德角早晨會令海和海岸線看起來灰暗而安靜。"},{"en":"Mentioning Cape Cod places the scientific discussion in a real coastal setting.","zh":"提到科德角，把科學討論放在真實沿海環境中。"},{"en":"This phrase names a specific place associated with the ocean.","zh":"這個短語命名一個與海洋相關的特定地方。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":8},{"front":"the surprising culprit of","meaning":"……令人意外的元兇","examples":[{"en":"Global warming may be the surprising culprit of the next mini-ice age.","zh":"全球暖化可能是下一個小型冰河時期令人意外的元兇。"},{"en":"The surprising culprit of something is the unexpected cause of a problem.","zh":"某事令人意外的元兇，是造成問題的出乎意料原因。"},{"en":"Lack of sleep may be the surprising culprit of a student’s poor memory.","zh":"睡眠不足可能是學生記憶差的令人意外元兇。"},{"en":"A surprising culprit matters because people may look for the cause in the wrong place.","zh":"令人意外的元兇很重要，因為人們可能在錯誤地方尋找原因。"},{"en":"This phrase introduces an unexpected explanation.","zh":"這個短語引入出乎意料的解釋。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":8},{"front":"mini-ice age","meaning":"小型冰河時期","examples":[{"en":"Warming may contribute to a future mini-ice age.","zh":"暖化可能促成未來的小型冰河時期。"},{"en":"A mini-ice age is a limited period of colder climate, less severe than a full ice age.","zh":"小型冰河時期是有限的較寒冷氣候時期，沒有完整冰河時期那麼嚴重。"},{"en":"A mini-ice age could bring colder winters without covering whole continents in ice.","zh":"小型冰河時期可能帶來更寒冷冬天，但不會以冰覆蓋整個大陸。"},{"en":"Even a smaller cooling period can disrupt farming, heating, and ecosystems.","zh":"即使是較小規模的降溫時期，也會擾亂農業、取暖和生態系統。"},{"en":"This phrase describes a smaller-scale but still serious cooling event.","zh":"這個短語描述規模較小但仍嚴重的降溫事件。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":8},{"front":"the paradox","meaning":"悖論","examples":[{"en":"The paradox is that warming could cause cooling.","zh":"這個悖論是暖化可能導致降溫。"},{"en":"A paradox is a situation that seems contradictory but may still be true.","zh":"悖論是看似矛盾但仍可能真實的情況。"},{"en":"It is a paradox that working fewer hours can sometimes make people more productive.","zh":"工作較少時間有時能令人更有生產力，這就是一個悖論。"},{"en":"Climate paradoxes confuse people because the cause and result seem opposite.","zh":"氣候悖論令人困惑，因為原因和結果看似相反。"},{"en":"This phrase introduces an apparently impossible relationship.","zh":"這個短語引入看似不可能的關係。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":9},{"front":"a result of","meaning":"……的結果","examples":[{"en":"The paradox is a result of fresh water entering the North Atlantic.","zh":"這個悖論是淡水進入北大西洋的結果。"},{"en":"A result of something means caused by it or happening because of it.","zh":"某事的結果，是指由它造成或因它而發生。"},{"en":"The traffic jam was a result of an accident near the tunnel.","zh":"交通擠塞是隧道附近意外的結果。"},{"en":"Understanding results helps people trace problems back to their causes.","zh":"理解結果有助人們把問題追溯到原因。"},{"en":"This phrase links effect with cause.","zh":"這個短語把結果與原因連接起來。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":9},{"front":"the appearance of","meaning":"……的出現","examples":[{"en":"The appearance of fresh water in the North Atlantic is worrying.","zh":"淡水在北大西洋的出現令人擔憂。"},{"en":"The appearance of something means its arrival, emergence, or becoming noticeable.","zh":"某事的出現，是指它到來、浮現或變得可察覺。"},{"en":"The appearance of cracks in a wall may worry a building manager.","zh":"牆上出現裂縫可能令大廈管理員擔心。"},{"en":"When something unusual appears in an important system, scientists investigate why.","zh":"當重要系統出現不尋常事物，科學家會調查原因。"},{"en":"This phrase describes something becoming present or visible.","zh":"這個短語描述某物變得存在或可見。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":9},{"front":"over the past 30 years","meaning":"在過去三十年","examples":[{"en":"Fresh water has appeared in the North Atlantic over the past 30 years.","zh":"在過去三十年，淡水出現在北大西洋。"},{"en":"Over the past 30 years means during the thirty years leading up to the time being discussed.","zh":"在過去三十年，是指截至正在討論的時間之前的三十年期間。"},{"en":"Over the past 30 years, many people have changed how they communicate because of the internet.","zh":"在過去三十年，許多人因互聯網而改變溝通方式。"},{"en":"Long time spans help scientists identify trends rather than short-term variation.","zh":"長時間跨度幫助科學家識別趨勢，而不是短期波動。"},{"en":"This phrase gives a recent multi-decade period.","zh":"這個短語給出近期的數十年時期。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":9},{"front":"North Atlantic","meaning":"北大西洋","examples":[{"en":"Fresh water in the North Atlantic may disrupt ocean circulation.","zh":"北大西洋中的淡水可能擾亂海洋環流。"},{"en":"The North Atlantic is the northern part of the Atlantic Ocean between North America and Europe.","zh":"北大西洋是位於北美和歐洲之間的大西洋北部。"},{"en":"Weather in Europe is influenced partly by currents in the North Atlantic.","zh":"歐洲天氣部分受北大西洋洋流影響。"},{"en":"Changes in the North Atlantic matter because its waters help drive global ocean circulation.","zh":"北大西洋變化很重要，因為其海水幫助推動全球海洋環流。"},{"en":"This phrase names a key ocean region.","zh":"這個短語命名一個關鍵海洋區域。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":9},{"front":"huge rivers of fresh water","meaning":"大量淡水流","examples":[{"en":"Huge rivers of fresh water have mixed into the salty sea.","zh":"大量淡水流已混入鹹海水中。"},{"en":"Huge rivers of fresh water means very large flows or amounts of non-salty water.","zh":"大量淡水流，是非常大的非鹹水流動或水量。"},{"en":"Melting ice can send huge rivers of fresh water into the ocean.","zh":"融冰可以把大量淡水流送入海洋。"},{"en":"Large amounts of fresh water can reduce salinity and change ocean density.","zh":"大量淡水可以降低鹽度並改變海水密度。"},{"en":"This phrase uses river imagery to describe massive freshwater input.","zh":"這個短語用河流意象描述大量淡水輸入。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":9},{"front":"the equivalent of","meaning":"相當於","examples":[{"en":"The fresh water is the equivalent of a 10-foot-thick layer.","zh":"這些淡水相當於一層 10 英尺厚的水層。"},{"en":"The equivalent of something means equal in amount, value, or effect to it.","zh":"相當於某物，是指在數量、價值或效果上等同於它。"},{"en":"A long walk may burn the equivalent of one small meal in energy.","zh":"長距離步行可能消耗相當於一小餐的能量。"},{"en":"Equivalents help readers imagine numbers that are otherwise hard to picture.","zh":"等量比較幫助讀者想像原本難以理解的數字。"},{"en":"This phrase explains scale by comparison.","zh":"這個短語透過比較解釋規模。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":9},{"front":"mixed into","meaning":"混入……","examples":[{"en":"Fresh water has mixed into the salty sea.","zh":"淡水已混入鹹海水中。"},{"en":"Mixed into means combined with another substance so that they are no longer fully separate.","zh":"混入，是指與另一種物質結合，使兩者不再完全分開。"},{"en":"Sugar mixed into tea changes the taste of the drink.","zh":"糖混入茶中會改變飲品味道。"},{"en":"When fresh water mixes into salty sea water, salinity becomes lower.","zh":"當淡水混入鹹海水，鹽度會降低。"},{"en":"This phrase describes one substance entering and blending with another.","zh":"這個短語描述一種物質進入並與另一種物質融合。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":9},{"front":"salty sea","meaning":"鹹海水","examples":[{"en":"Fresh water has entered the salty sea of the North Atlantic.","zh":"淡水已進入北大西洋的鹹海水中。"},{"en":"Salty sea means ocean water containing a high amount of dissolved salt.","zh":"鹹海水是含有大量溶解鹽分的海洋水。"},{"en":"Swimming in a salty sea feels different from swimming in a freshwater lake.","zh":"在鹹海水中游泳與在淡水湖中游泳感覺不同。"},{"en":"Adding fresh water to a salty sea can change density and circulation.","zh":"向鹹海水加入淡水會改變密度和環流。"},{"en":"This phrase contrasts ocean water with fresh water.","zh":"這個短語把海水與淡水作對比。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":9},{"front":"fresh torrents","meaning":"大量淡水急流","examples":[{"en":"No one is certain where the fresh torrents are coming from.","zh":"沒有人確定大量淡水急流來自哪裡。"},{"en":"Fresh torrents are large, fast flows of fresh water.","zh":"大量淡水急流，是大而快速流動的淡水。"},{"en":"Melting ice can create fresh torrents that pour into the sea.","zh":"融冰可以造成大量淡水急流湧入海洋。"},{"en":"Scientists care about fresh torrents because they can change ocean salinity quickly.","zh":"科學家關心大量淡水急流，因為它們能迅速改變海洋鹽度。"},{"en":"This phrase suggests powerful freshwater movement.","zh":"這個短語暗示強大的淡水流動。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":9},{"front":"a prime suspect","meaning":"主要疑兇；主要原因","examples":[{"en":"A prime suspect is melting Arctic ice.","zh":"主要疑兇是正在融化的北極冰。"},{"en":"A prime suspect is the most likely cause or person responsible for something.","zh":"主要疑兇或主要原因，是最可能造成某事的人或原因。"},{"en":"If several students get sick after lunch, contaminated food may be a prime suspect.","zh":"如果幾名學生午餐後生病，受污染食物可能是主要疑兇。"},{"en":"Scientists call something a prime suspect when evidence points strongly toward it.","zh":"當證據強烈指向某物，科學家會稱它為主要疑兇。"},{"en":"This phrase is often used when the exact cause is not yet certain.","zh":"這個短語常用於確切原因尚未肯定時。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":9},{"front":"melting Arctic ice","meaning":"融化中的北極冰","examples":[{"en":"Melting Arctic ice may be adding fresh water to the ocean.","zh":"融化中的北極冰可能正向海洋加入淡水。"},{"en":"Melting Arctic ice is ice in the Arctic region turning into water because of warming.","zh":"融化中的北極冰，是北極地區的冰因暖化而變成水。"},{"en":"Melting Arctic ice can affect sea levels, wildlife, and ocean circulation.","zh":"融化中的北極冰會影響海平面、野生動物和海洋環流。"},{"en":"As Arctic ice melts, fresh water can enter salty ocean systems.","zh":"隨着北極冰融化，淡水會進入鹹海水系統。"},{"en":"This phrase links warming with changes in northern ice.","zh":"這個短語把暖化與北方冰層變化連接起來。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":9},{"front":"build-up of carbon dioxide","meaning":"二氧化碳積聚","examples":[{"en":"A build-up of carbon dioxide traps solar energy.","zh":"二氧化碳積聚會困住太陽能。"},{"en":"A build-up of carbon dioxide is an increasing amount of carbon dioxide in the atmosphere.","zh":"二氧化碳積聚，是大氣中二氧化碳數量增加。"},{"en":"Burning coal and oil can contribute to a build-up of carbon dioxide.","zh":"燃燒煤和石油會促成二氧化碳積聚。"},{"en":"This build-up matters because it can strengthen the greenhouse effect.","zh":"這種積聚重要，因為它會加強溫室效應。"},{"en":"This phrase describes accumulation of a climate-related gas.","zh":"這個短語描述與氣候相關氣體的累積。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":9},{"front":"carbon dioxide","meaning":"二氧化碳","examples":[{"en":"Carbon dioxide in the atmosphere can trap solar energy.","zh":"大氣中的二氧化碳會困住太陽能。"},{"en":"Carbon dioxide is a gas produced by breathing, burning fuel, and many natural processes.","zh":"二氧化碳是由呼吸、燃燒燃料和許多自然過程產生的氣體。"},{"en":"Cars and power stations release carbon dioxide when they burn fossil fuels.","zh":"汽車和發電廠燃燒化石燃料時會釋放二氧化碳。"},{"en":"More carbon dioxide can warm the planet by trapping heat in the atmosphere.","zh":"更多二氧化碳會透過在大氣中困住熱量而令地球變暖。"},{"en":"This phrase names an important greenhouse gas.","zh":"這個短語命名一種重要溫室氣體。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":9},{"front":"traps solar energy","meaning":"困住太陽能","examples":[{"en":"Carbon dioxide traps solar energy in the atmosphere.","zh":"二氧化碳在大氣中困住太陽能。"},{"en":"Traps solar energy means keeps heat from the sun from escaping easily.","zh":"困住太陽能，是指令來自太陽的熱量不容易逃走。"},{"en":"A greenhouse traps solar energy so plants stay warmer inside.","zh":"溫室困住太陽能，使室內植物保持較暖。"},{"en":"When gases trap too much solar energy, global temperatures can rise.","zh":"當氣體困住太多太陽能，全球氣溫會上升。"},{"en":"This phrase explains the warming effect of greenhouse gases.","zh":"這個短語解釋溫室氣體的增溫作用。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":10},{"front":"freshwater trend","meaning":"淡水增加趨勢","examples":[{"en":"The freshwater trend is major news in ocean-science circles.","zh":"淡水增加趨勢是海洋科學界的重大消息。"},{"en":"A freshwater trend is a pattern of increasing or changing amounts of fresh water in an ocean area.","zh":"淡水趨勢是某海域淡水量增加或改變的模式。"},{"en":"Scientists may track a freshwater trend by measuring salinity over many years.","zh":"科學家可能透過多年量度鹽度追蹤淡水趨勢。"},{"en":"This trend matters because fresh water can change ocean density and circulation.","zh":"這個趨勢重要，因為淡水能改變海水密度和環流。"},{"en":"This phrase describes a long-term ocean change.","zh":"這個短語描述長期海洋變化。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":10},{"front":"major news","meaning":"重大消息","examples":[{"en":"The freshwater trend is major news among ocean scientists.","zh":"淡水趨勢是海洋科學家之間的重大消息。"},{"en":"Major news means very important information that many people in a field pay attention to.","zh":"重大消息，是某領域中許多人關注的非常重要資訊。"},{"en":"A new treatment for a common disease would be major news in medicine.","zh":"常見疾病的新療法會是醫學界的重大消息。"},{"en":"Something becomes major news when it changes how experts understand a problem.","zh":"當某事改變專家如何理解問題，它就成為重大消息。"},{"en":"This phrase signals high importance.","zh":"這個短語表示高度重要性。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":10},{"front":"ocean-science circles","meaning":"海洋科學界","examples":[{"en":"The trend is important in ocean-science circles.","zh":"這個趨勢在海洋科學界很重要。"},{"en":"Ocean-science circles are communities of scientists and researchers who study the ocean.","zh":"海洋科學界是研究海洋的科學家和研究人員社群。"},{"en":"A discovery about deep currents may spread quickly through ocean-science circles.","zh":"關於深海洋流的發現可能在海洋科學界迅速傳開。"},{"en":"Ideas discussed in scientific circles can later shape public policy and media attention.","zh":"科學界討論的想法之後可能塑造公共政策和媒體關注。"},{"en":"This phrase refers to a professional research community.","zh":"這個短語指專業研究社群。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":10},{"front":"sounded an alarm","meaning":"發出警號","examples":[{"en":"Bob Dickson sounded an alarm at a conference.","zh":"Bob Dickson 在會議上發出警號。"},{"en":"Sounded an alarm means gave a warning about danger or a serious problem.","zh":"發出警號，是指對危險或嚴重問題提出警告。"},{"en":"A doctor sounded an alarm when many patients showed the same unusual symptoms.","zh":"當許多病人出現相同不尋常症狀，醫生發出警號。"},{"en":"People sound alarms to make others notice risks before damage becomes worse.","zh":"人們發出警號，是為了讓其他人在損害惡化前注意風險。"},{"en":"This phrase describes public warning.","zh":"這個短語描述公開警告。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":10},{"front":"conference in Honolulu","meaning":"檀香山會議","examples":[{"en":"Dickson warned scientists at a conference in Honolulu.","zh":"Dickson 在檀香山會議上警告科學家。"},{"en":"A conference in Honolulu is a professional meeting held in Honolulu, Hawaii.","zh":"檀香山會議是在夏威夷檀香山舉行的專業會議。"},{"en":"Scientists may attend a conference in Honolulu to share ocean research and climate data.","zh":"科學家可能參加檀香山會議，分享海洋研究和氣候數據。"},{"en":"Conferences allow experts to warn others about new findings quickly.","zh":"會議讓專家能快速警告其他人新發現。"},{"en":"This phrase gives the location and setting of the warning.","zh":"這個短語給出警告的地點和場景。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":10},{"front":"termed","meaning":"稱為","examples":[{"en":"Dickson termed the change one of the largest recorded ocean changes.","zh":"Dickson 稱這項變化為有紀錄以來最大的海洋變化之一。"},{"en":"Termed means called or described something using a particular word or phrase.","zh":"稱為，是指用特定字詞或短語稱呼或描述某事。"},{"en":"A doctor termed the illness mild because the symptoms were not severe.","zh":"醫生稱該疾病為輕微，因為症狀並不嚴重。"},{"en":"The word chosen to term a change can influence how seriously people take it.","zh":"用來稱呼變化的字詞會影響人們有多認真看待它。"},{"en":"This verb is formal and often used in reports.","zh":"這個動詞較正式，常見於報告中。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":10},{"front":"drop in salinity","meaning":"鹽度下降","examples":[{"en":"Scientists observed a drop in salinity in the Labrador Sea.","zh":"科學家觀察到拉布拉多海鹽度下降。"},{"en":"A drop in salinity means the water becomes less salty.","zh":"鹽度下降，是指水變得較不鹹。"},{"en":"Heavy rain can cause a drop in salinity near a river mouth.","zh":"大雨可以令河口附近海水鹽度下降。"},{"en":"Lower salinity can change water density and affect ocean circulation.","zh":"鹽度降低會改變水的密度並影響海洋環流。"},{"en":"This phrase describes a measurable chemical change in seawater.","zh":"這個短語描述海水中可量度的化學變化。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":10},{"front":"Labrador Sea","meaning":"拉布拉多海","examples":[{"en":"The Labrador Sea lies between northeastern Canada and Greenland.","zh":"拉布拉多海位於加拿大東北部和格陵蘭之間。"},{"en":"The Labrador Sea is a cold part of the North Atlantic between Canada and Greenland.","zh":"拉布拉多海是加拿大和格陵蘭之間、北大西洋的一個寒冷海域。"},{"en":"Scientists study the Labrador Sea because deep water forms there.","zh":"科學家研究拉布拉多海，因為深層水在那裡形成。"},{"en":"Changes in the Labrador Sea can affect wider ocean circulation.","zh":"拉布拉多海的變化會影響更廣泛海洋環流。"},{"en":"This phrase names an important northern ocean region.","zh":"這個短語命名一個重要北方海域。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":10},{"front":"body of water","meaning":"水域","examples":[{"en":"The Labrador Sea is a body of water between Canada and Greenland.","zh":"拉布拉多海是加拿大與格陵蘭之間的一片水域。"},{"en":"A body of water is a lake, sea, river, ocean, or other large area of water.","zh":"水域是湖、海、河、洋或其他大型水面區域。"},{"en":"A reservoir is a body of water used for storing drinking water.","zh":"水庫是用來儲存飲用水的一片水域。"},{"en":"Different bodies of water can affect local climate, transport, and ecosystems.","zh":"不同水域可以影響本地氣候、交通和生態系統。"},{"en":"This phrase is a general term for water areas.","zh":"這個短語是水面區域的通用詞。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":10},{"front":"northeastern Canada","meaning":"加拿大東北部","examples":[{"en":"The Labrador Sea lies near northeastern Canada.","zh":"拉布拉多海位於加拿大東北部附近。"},{"en":"Northeastern Canada means the part of Canada located toward the north and east.","zh":"加拿大東北部，是指加拿大北方和東方一帶。"},{"en":"Northeastern Canada includes cold coastal areas near the North Atlantic.","zh":"加拿大東北部包括靠近北大西洋的寒冷沿海地區。"},{"en":"Its location matters because nearby seas and ice influence climate research.","zh":"其位置重要，因為附近海域和冰影響氣候研究。"},{"en":"This phrase gives a regional location.","zh":"這個短語給出地區位置。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":10},{"front":"adjoins the Atlantic","meaning":"毗鄰大西洋","examples":[{"en":"The Labrador Sea adjoins the Atlantic Ocean.","zh":"拉布拉多海毗鄰大西洋。"},{"en":"Adjoins the Atlantic means lies next to or connects directly with the Atlantic Ocean.","zh":"毗鄰大西洋，是指位於大西洋旁邊或直接與其相連。"},{"en":"A coastal city may adjoin the sea and depend on ships for trade.","zh":"沿海城市可能毗鄰海洋，並依賴船運貿易。"},{"en":"If a water body adjoins a major ocean, changes there can spread widely.","zh":"如果某水域毗鄰主要海洋，那裡的變化可以廣泛擴散。"},{"en":"This phrase describes geographical connection.","zh":"這個短語描述地理連接。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":10},{"front":"arguably","meaning":"可以說","examples":[{"en":"Dickson called the changes arguably the largest full-depth changes recorded.","zh":"Dickson 稱這些變化可以說是有紀錄以來最大的全深度變化。"},{"en":"Arguably means it can reasonably be argued or claimed, though others may disagree.","zh":"可以說，是指有理由這樣主張，雖然其他人可能不同意。"},{"en":"This is arguably the best study plan for students who need both structure and flexibility.","zh":"這可以說是最適合需要結構和彈性的學生的學習計劃。"},{"en":"Writers use arguably when they want to make a strong but careful claim.","zh":"作者在想提出強烈但謹慎主張時會使用 arguably。"},{"en":"This word softens a statement while still supporting it.","zh":"這個詞讓陳述稍為柔和，但仍支持它。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":10},{"front":"full-depth changes","meaning":"全深度變化","examples":[{"en":"Scientists observed full-depth changes in the Labrador Sea.","zh":"科學家在拉布拉多海觀察到全深度變化。"},{"en":"Full-depth changes are changes that affect water from the surface down to deep layers.","zh":"全深度變化，是影響由表層到深層水體的變化。"},{"en":"A lake showing full-depth temperature change would be altered from top to bottom.","zh":"如果湖泊出現全深度溫度變化，它由上到下都被改變。"},{"en":"Full-depth ocean changes matter because they can affect deep currents, not only surface conditions.","zh":"全深度海洋變化很重要，因為它能影響深海洋流，而不只是表面情況。"},{"en":"This phrase describes change through the whole vertical water column.","zh":"這個短語描述整個垂直水柱中的變化。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":10},{"front":"modern instrumental oceanographic record","meaning":"現代儀器海洋學記錄","examples":[{"en":"The change is significant in the modern instrumental oceanographic record.","zh":"這項變化在現代儀器海洋學記錄中很重要。"},{"en":"The modern instrumental oceanographic record is the ocean data collected by modern measuring instruments.","zh":"現代儀器海洋學記錄，是由現代測量儀器收集的海洋數據。"},{"en":"Buoys, ships, and sensors help build the modern instrumental oceanographic record.","zh":"浮標、船隻和感測器幫助建立現代儀器海洋學記錄。"},{"en":"This record allows scientists to compare today’s ocean changes with measured past data.","zh":"這項記錄讓科學家把今日海洋變化與過去測量數據比較。"},{"en":"This phrase refers to scientific ocean records based on instruments, not stories.","zh":"這個短語指基於儀器的科學海洋記錄，而不是故事。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":11},{"front":"subverting","meaning":"破壞；削弱","examples":[{"en":"The trend could cause cooling by subverting the northern penetration of Gulf Stream waters.","zh":"這個趨勢可能透過削弱墨西哥灣流水向北深入而造成降溫。"},{"en":"Subverting means weakening, disrupting, or undermining how something normally works.","zh":"破壞或削弱，是指令某事正常運作變弱、受擾或被暗中破壞。"},{"en":"A bad rumour can subvert trust in a class even when most students behave well.","zh":"即使大多數學生表現良好，壞謠言也會破壞班中的信任。"},{"en":"Fresh water may subvert ocean circulation by changing the density that drives sinking.","zh":"淡水可能透過改變驅動下沉的密度來破壞海洋環流。"},{"en":"This word suggests damage from within a system.","zh":"這個詞暗示系統內部受到損害。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":11},{"front":"northern penetration","meaning":"向北深入","examples":[{"en":"Fresh water may weaken the northern penetration of Gulf Stream waters.","zh":"淡水可能削弱墨西哥灣流水向北深入。"},{"en":"Northern penetration means movement or extension northward into a region.","zh":"向北深入，是指朝北方移動或延伸進入某地區。"},{"en":"Warm air’s northern penetration can make a normally cold city feel unusually mild.","zh":"暖空氣向北深入會令本來寒冷的城市異常溫和。"},{"en":"If ocean water cannot penetrate northward, less heat may reach northern areas.","zh":"如果海水不能向北深入，較少熱量會到達北方地區。"},{"en":"This phrase describes how far something moves north.","zh":"這個短語描述某物向北移動多遠。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":11},{"front":"Gulf Stream","meaning":"墨西哥灣流","examples":[{"en":"The Gulf Stream carries warm water northwards.","zh":"墨西哥灣流把暖水向北帶去。"},{"en":"The Gulf Stream is a powerful Atlantic Ocean current that moves warm water from the tropics toward the north.","zh":"墨西哥灣流是強大的大西洋洋流，把熱帶暖水向北移動。"},{"en":"Europe is warmer partly because the Gulf Stream helps move heat across the Atlantic.","zh":"歐洲較溫暖，部分原因是墨西哥灣流幫助把熱量帶過大西洋。"},{"en":"If the Gulf Stream weakens, nearby climates may become colder.","zh":"如果墨西哥灣流減弱，附近氣候可能變冷。"},{"en":"This phrase names a major ocean current.","zh":"這個短語命名一條主要洋流。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":11},{"front":"laden with heat","meaning":"充滿熱量","examples":[{"en":"The Gulf Stream is laden with heat from the tropics.","zh":"墨西哥灣流充滿來自熱帶的熱量。"},{"en":"Laden with heat means carrying a large amount of heat.","zh":"充滿熱量，是指帶有大量熱能。"},{"en":"A metal roof can become laden with heat after hours of strong sun.","zh":"金屬屋頂在烈日下數小時後會充滿熱量。"},{"en":"Ocean currents laden with heat can warm the air above them.","zh":"充滿熱量的洋流可以加熱其上方空氣。"},{"en":"This phrase presents heat as something being carried.","zh":"這個短語把熱量呈現為被攜帶的東西。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":11},{"front":"soaked up","meaning":"吸收","examples":[{"en":"The Gulf Stream carries heat soaked up in the tropics.","zh":"墨西哥灣流攜帶在熱帶吸收的熱量。"},{"en":"Soaked up means absorbed or taken in.","zh":"吸收，是指吸入或接收某物。"},{"en":"A sponge soaks up water from a kitchen table.","zh":"海綿吸收廚房桌面上的水。"},{"en":"Ocean water can soak up heat from strong tropical sunlight.","zh":"海水可以吸收強烈熱帶陽光帶來的熱量。"},{"en":"This phrase describes taking something in from the surroundings.","zh":"這個短語描述從周圍環境接收某物。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":11},{"front":"the tropics","meaning":"熱帶地區","examples":[{"en":"The Gulf Stream absorbs heat in the tropics.","zh":"墨西哥灣流在熱帶地區吸收熱量。"},{"en":"The tropics are warm regions near the equator.","zh":"熱帶地區是靠近赤道的溫暖地區。"},{"en":"Tropical countries often have strong sunlight, warm seas, and humid weather.","zh":"熱帶國家通常有強烈陽光、暖海水和潮濕天氣。"},{"en":"Water warmed in the tropics can carry heat into cooler regions.","zh":"在熱帶地區被加熱的水可以把熱量帶到較冷地區。"},{"en":"This phrase names the Earth’s warm low-latitude zone.","zh":"這個短語命名地球的溫暖低緯度地帶。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":11},{"front":"meanders up","meaning":"蜿蜒北上","examples":[{"en":"The Gulf Stream meanders up the east coast of North America.","zh":"墨西哥灣流沿北美東岸蜿蜒北上。"},{"en":"Meanders up means moves northward in a winding or curving path.","zh":"蜿蜒北上，是指以彎曲路線向北移動。"},{"en":"A river may meander through farmland before reaching the sea.","zh":"河流可能在到達大海前蜿蜒穿過農田。"},{"en":"The word suggests movement that is not perfectly straight.","zh":"這個詞暗示移動路線不是完全筆直。"},{"en":"This phrase describes the path of a current or route.","zh":"這個短語描述洋流或路線的路徑。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":11},{"front":"east coasts","meaning":"東岸","examples":[{"en":"The Gulf Stream flows along the east coasts of the United States and Canada.","zh":"墨西哥灣流沿美國和加拿大東岸流動。"},{"en":"East coasts are the eastern shorelines of countries or continents.","zh":"東岸是國家或大陸東面的海岸線。"},{"en":"Cities on east coasts often face the ocean and depend on ports and trade.","zh":"位於東岸的城市通常面向海洋，並依賴港口和貿易。"},{"en":"Ocean currents along east coasts can influence local climate and weather.","zh":"沿東岸流動的洋流會影響本地氣候和天氣。"},{"en":"This phrase gives a coastal location.","zh":"這個短語給出沿海位置。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":11},{"front":"flows northward","meaning":"向北流動","examples":[{"en":"As the Gulf Stream flows northward, it gives off heat.","zh":"當墨西哥灣流向北流動時，它會釋放熱量。"},{"en":"Flows northward means moves toward the north.","zh":"向北流動，是指朝北方移動。"},{"en":"A river flows northward if its water travels toward higher latitudes.","zh":"如果河水流向較高緯度，該河就是向北流動。"},{"en":"When warm water flows northward, it can carry heat into colder regions.","zh":"當暖水向北流動，它可以把熱量帶到較冷地區。"},{"en":"This phrase describes direction of movement.","zh":"這個短語描述移動方向。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":11},{"front":"surrenders heat to","meaning":"把熱量釋放給……","examples":[{"en":"The Gulf Stream surrenders heat to the air.","zh":"墨西哥灣流把熱量釋放給空氣。"},{"en":"Surrenders heat to something means gives up or releases heat to it.","zh":"把熱量釋放給某物，是指放出熱量並傳給它。"},{"en":"A hot cup of tea surrenders heat to the air as it cools.","zh":"一杯熱茶冷卻時會把熱量釋放給空氣。"},{"en":"When ocean water surrenders heat to the air, nearby air becomes warmer.","zh":"當海水把熱量釋放給空氣，附近空氣會變暖。"},{"en":"This phrase describes heat transfer.","zh":"這個短語描述熱量轉移。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":11},{"front":"prevailing winds","meaning":"盛行風","examples":[{"en":"Prevailing North Atlantic winds blow eastward.","zh":"北大西洋盛行風向東吹。"},{"en":"Prevailing winds are the winds that most often blow in a particular direction in a region.","zh":"盛行風是某地區最常朝某方向吹的風。"},{"en":"Sailors study prevailing winds before planning a sea journey.","zh":"水手在規劃航程前會研究盛行風。"},{"en":"Prevailing winds can carry heat, moisture, pollution, or storms across long distances.","zh":"盛行風可以把熱量、水分、污染或風暴帶到遠處。"},{"en":"This phrase describes the usual wind pattern.","zh":"這個短語描述通常的風向模式。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":11},{"front":"blow eastward","meaning":"向東吹","examples":[{"en":"The prevailing winds blow eastward across the Atlantic.","zh":"盛行風橫越大西洋向東吹。"},{"en":"Blow eastward means move toward the east as wind.","zh":"向東吹，是指風朝東方移動。"},{"en":"Smoke may blow eastward if the wind is coming from the west.","zh":"如果風從西方吹來，煙可能向東吹。"},{"en":"Eastward winds can carry warmth from the ocean toward Europe.","zh":"向東吹的風可以把海洋暖氣帶向歐洲。"},{"en":"This phrase describes wind direction.","zh":"這個短語描述風向。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":11},{"front":"wafts to","meaning":"飄送到……","examples":[{"en":"A lot of heat wafts to Europe.","zh":"大量熱量飄送到歐洲。"},{"en":"Wafts to means moves gently through air toward a place.","zh":"飄送到，是指在空氣中輕輕移向某處。"},{"en":"The smell of bread wafts to the street from a bakery.","zh":"麵包香味從麵包店飄送到街上。"},{"en":"Heat carried by winds can waft across the ocean and warm distant regions.","zh":"由風攜帶的熱量可以飄過海洋，溫暖遠方地區。"},{"en":"This word suggests gentle movement rather than forceful pushing.","zh":"這個詞暗示輕柔移動，而不是用力推動。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":11},{"front":"the Continent","meaning":"歐洲大陸","examples":[{"en":"Winter temperatures on the Continent are warmer because of ocean heat.","zh":"歐洲大陸冬季氣溫因海洋熱量而較暖。"},{"en":"The Continent often means mainland Europe, especially when contrasted with Britain.","zh":"歐洲大陸常指歐洲本土，尤其與英國作對比時。"},{"en":"British newspapers may refer to travel to France or Germany as travel to the Continent.","zh":"英國報章可能把前往法國或德國稱為到歐洲大陸旅行。"},{"en":"In this passage, the Continent is warmed by heat carried across the Atlantic.","zh":"在這篇文章中，歐洲大陸受到橫越大西洋的熱量變暖。"},{"en":"This phrase is a regional term, not a geological explanation.","zh":"這個短語是地區用語，而不是地質解釋。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":12},{"front":"at the same latitude","meaning":"在相同緯度","examples":[{"en":"Europe is warmer than North America at the same latitude.","zh":"在相同緯度，歐洲比北美更暖。"},{"en":"At the same latitude means at the same distance north or south of the equator.","zh":"在相同緯度，是指距離赤道南北的位置相同。"},{"en":"Two cities at the same latitude can have different climates because of oceans and winds.","zh":"兩個位於相同緯度的城市，可能因海洋和風而有不同氣候。"},{"en":"This phrase helps compare places that receive similar amounts of sunlight.","zh":"這個短語幫助比較接收相似陽光量的地方。"},{"en":"It is useful for explaining unexpected climate differences.","zh":"它適合解釋意外的氣候差異。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":12},{"front":"frigid Boston","meaning":"嚴寒的波士頓","examples":[{"en":"Frigid Boston lies at almost the same latitude as Rome.","zh":"嚴寒的波士頓與羅馬幾乎位於相同緯度。"},{"en":"Frigid Boston means Boston described as very cold, especially in winter.","zh":"嚴寒的波士頓，是把波士頓描述為非常寒冷，尤其在冬季。"},{"en":"A traveller from a warm country may find frigid Boston difficult in January.","zh":"來自暖國的旅客可能覺得一月的嚴寒波士頓很難適應。"},{"en":"Calling Boston frigid highlights the contrast with warmer Rome at a similar latitude.","zh":"稱波士頓嚴寒，突出它與相似緯度的較暖羅馬之間的對比。"},{"en":"This phrase uses a city as an example of cold climate.","zh":"這個短語用城市作為寒冷氣候例子。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":12},{"front":"balmy Rome","meaning":"氣候溫和的羅馬","examples":[{"en":"Balmy Rome lies at nearly the same latitude as Boston.","zh":"氣候溫和的羅馬與波士頓幾乎位於相同緯度。"},{"en":"Balmy Rome means Rome described as pleasantly warm or mild.","zh":"氣候溫和的羅馬，是把羅馬描述為令人舒適地暖和或溫和。"},{"en":"Tourists may enjoy balmy Rome in winter when other cities feel freezing.","zh":"當其他城市感覺冰冷時，遊客可能享受冬季氣候溫和的羅馬。"},{"en":"The phrase highlights how ocean currents can make climates differ at similar latitudes.","zh":"這個短語突出洋流如何令相同緯度的氣候不同。"},{"en":"This phrase uses a city as an example of mild climate.","zh":"這個短語用城市作為溫和氣候例子。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":12},{"front":"solely as","meaning":"純粹視為……","examples":[{"en":"Joyce says it is a mistake to think of this solely as a European phenomenon.","zh":"Joyce 說，把這純粹視為歐洲現象是錯誤的。"},{"en":"Solely as means only as one thing and not in any other way.","zh":"純粹視為某事，是指只把它當作一件事，而不從其他方式理解。"},{"en":"It is wrong to view education solely as exam preparation.","zh":"把教育純粹視為考試準備是錯誤的。"},{"en":"Thinking solely in one way can hide wider effects and causes.","zh":"只以一種方式思考會隱藏更廣泛影響和原因。"},{"en":"This phrase warns against too narrow an interpretation.","zh":"這個短語提醒不要作過於狹窄的解讀。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":12},{"front":"European phenomenon","meaning":"歐洲現象","examples":[{"en":"The Gulf Stream’s effect is not solely a European phenomenon.","zh":"墨西哥灣流的影響並不純粹是歐洲現象。"},{"en":"A European phenomenon is something that happens in or mainly affects Europe.","zh":"歐洲現象是在歐洲發生或主要影響歐洲的事情。"},{"en":"High-speed rail is often seen as a European phenomenon, though it exists elsewhere too.","zh":"高速鐵路常被視為歐洲現象，雖然其他地方也存在。"},{"en":"The passage warns that ocean circulation affects more than Europe alone.","zh":"篇章提醒，海洋環流影響的不只是歐洲。"},{"en":"This phrase describes a region-specific event or pattern.","zh":"這個短語描述特定地區的事件或模式。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":12},{"front":"having given up its heat","meaning":"釋放熱量後","examples":[{"en":"Having given up its heat, the water becomes denser.","zh":"釋放熱量後，水變得密度較高。"},{"en":"Having given up its heat means after the water has released its warmth.","zh":"釋放熱量後，是指水已把其熱量放出之後。"},{"en":"Having given up its heat to the room, a cup of tea becomes cooler.","zh":"一杯茶把熱量釋放到房間後，就會變冷。"},{"en":"Water that loses heat becomes cooler and may sink if it becomes dense enough.","zh":"失去熱量的水會變冷，如果密度足夠高，就可能下沉。"},{"en":"This phrase shows what happens after heat transfer.","zh":"這個短語顯示熱量轉移後發生甚麼。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":12},{"front":"denser","meaning":"密度較高的","examples":[{"en":"Cooler water becomes denser and sinks.","zh":"較冷的水變得密度較高並下沉。"},{"en":"Denser means having more mass packed into the same amount of space.","zh":"密度較高，是指同樣空間中包含更多質量。"},{"en":"Oil floats on water because it is less dense than water.","zh":"油浮在水上，因為它比水密度低。"},{"en":"Dense cold seawater can sink and help drive ocean circulation.","zh":"密度高的冷海水會下沉，並幫助驅動海洋環流。"},{"en":"This word describes physical heaviness per volume.","zh":"這個詞描述每單位體積的物理重量。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":12},{"front":"sinks into","meaning":"下沉到……","examples":[{"en":"Cold dense water sinks into the North Atlantic.","zh":"寒冷而密度高的水下沉到北大西洋。"},{"en":"Sinks into means moves downward into a liquid, space, or surface.","zh":"下沉到，是指向下移入液體、空間或表面中。"},{"en":"A stone sinks into a pond because it is denser than water.","zh":"石頭會下沉到池塘中，因為它比水密度高。"},{"en":"When dense seawater sinks, it can pull surface water into a larger circulation system.","zh":"當高密度海水下沉，它可以把表層水拉入更大環流系統。"},{"en":"This phrase describes downward movement.","zh":"這個短語描述向下移動。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":12},{"front":"thermohaline circulation","meaning":"溫鹽環流","examples":[{"en":"Oceanographers call this process thermohaline circulation.","zh":"海洋學家稱這個過程為溫鹽環流。"},{"en":"Thermohaline circulation is deep ocean circulation driven by differences in temperature and salinity.","zh":"溫鹽環流是由溫度和鹽度差異驅動的深海環流。"},{"en":"Cold salty water can sink and help maintain thermohaline circulation.","zh":"寒冷鹹水會下沉並幫助維持溫鹽環流。"},{"en":"If fresh water weakens sinking, thermohaline circulation may slow or change.","zh":"如果淡水削弱下沉，溫鹽環流可能減慢或改變。"},{"en":"This phrase names a major ocean-climate process.","zh":"這個短語命名一個主要海洋氣候過程。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":12},{"front":"massive column of","meaning":"巨大的……柱","examples":[{"en":"A massive column of cold water powers a deep-water current.","zh":"巨大的冷水柱驅動深海洋流。"},{"en":"A massive column of something is a very large vertical mass of it.","zh":"巨大的某物柱，是非常大的垂直物質團。"},{"en":"A massive column of smoke rose above the burning factory.","zh":"巨大的煙柱從燃燒中的工廠上方升起。"},{"en":"In the ocean, a column of sinking cold water can drive movement far below the surface.","zh":"在海洋中，下沉的冷水柱可以驅動表面下很深處的運動。"},{"en":"This phrase helps readers picture vertical scale.","zh":"這個短語幫助讀者想像垂直規模。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":12},{"front":"cascading cold","meaning":"向下傾瀉的冷水","examples":[{"en":"The cascading cold water powers a global current.","zh":"向下傾瀉的冷水驅動全球洋流。"},{"en":"Cascading cold water is cold water falling or flowing downward like a waterfall.","zh":"向下傾瀉的冷水，是像瀑布般向下落或流動的冷水。"},{"en":"Rainwater may cascade down a hillside after a storm.","zh":"暴風雨後，雨水可能沿山坡向下傾瀉。"},{"en":"In ocean circulation, cascading cold water can pull water masses into deep movement.","zh":"在海洋環流中，向下傾瀉的冷水可以把水團拉入深層運動。"},{"en":"This phrase gives a vivid image of downward flow.","zh":"這個短語給出向下流動的生動畫面。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":12},{"front":"main engine powering","meaning":"驅動……的主要引擎","examples":[{"en":"The sinking cold water is the main engine powering the Great Ocean Conveyor.","zh":"下沉冷水是驅動全球海洋輸送帶的主要引擎。"},{"en":"Main engine powering something means the key force that drives it.","zh":"驅動某事的主要引擎，是推動它的關鍵力量。"},{"en":"Student motivation is the main engine powering steady improvement.","zh":"學生動機是驅動穩定進步的主要引擎。"},{"en":"If the main engine weakens, the whole system may slow down.","zh":"如果主要引擎變弱，整個系統可能減慢。"},{"en":"This phrase identifies the central driving force.","zh":"這個短語指出核心驅動力。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":12},{"front":"deep-water current","meaning":"深海洋流","examples":[{"en":"The Great Ocean Conveyor is a deep-water current.","zh":"全球海洋輸送帶是一股深海洋流。"},{"en":"A deep-water current is a flow of ocean water far below the surface.","zh":"深海洋流是在海洋表面之下很深處流動的海水。"},{"en":"Deep-water currents move slowly but can influence climate across the world.","zh":"深海洋流移動緩慢，但能影響全球氣候。"},{"en":"These currents matter because they transport heat, salt, and nutrients.","zh":"這些洋流重要，因為它們運送熱量、鹽分和養分。"},{"en":"This phrase refers to ocean movement beneath surface waves.","zh":"這個短語指表面波浪以下的海洋運動。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":12},{"front":"Great Ocean Conveyor","meaning":"全球海洋輸送帶","examples":[{"en":"The Great Ocean Conveyor snakes through all the world’s oceans.","zh":"全球海洋輸送帶蜿蜒穿過世界所有海洋。"},{"en":"The Great Ocean Conveyor is a global system of connected ocean currents that move water around the planet.","zh":"全球海洋輸送帶是連接起來、把水繞地球移動的全球洋流系統。"},{"en":"Scientists use the idea of the Great Ocean Conveyor to explain how heat travels through oceans.","zh":"科學家用全球海洋輸送帶概念解釋熱量如何在海洋中移動。"},{"en":"If this conveyor slows, climate patterns may change in many regions.","zh":"如果這條輸送帶減慢，許多地區的氣候模式可能改變。"},{"en":"This phrase names a global ocean circulation system.","zh":"這個短語命名全球海洋環流系統。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":13},{"front":"snakes through","meaning":"蜿蜒穿過","examples":[{"en":"The current snakes through all the world’s oceans.","zh":"這股洋流蜿蜒穿過世界所有海洋。"},{"en":"Snakes through means moves in a long, winding path through a place.","zh":"蜿蜒穿過，是指以長而彎曲的路線穿過某地。"},{"en":"A narrow road snakes through the mountains before reaching the village.","zh":"一條狹窄道路蜿蜒穿過山區才到達村莊。"},{"en":"A current that snakes through oceans connects distant regions over time.","zh":"蜿蜒穿過海洋的洋流會隨時間連接遙遠地區。"},{"en":"This phrase describes twisting movement across space.","zh":"這個短語描述跨越空間的彎曲移動。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":13},{"front":"fills with fresh water","meaning":"充滿淡水","examples":[{"en":"As the North Atlantic fills with fresh water, it grows less dense.","zh":"隨着北大西洋充滿淡水，它的密度變低。"},{"en":"Fills with fresh water means becomes increasingly mixed or covered with non-salty water.","zh":"充滿淡水，是指越來越多非鹹水混入或覆蓋。"},{"en":"A harbour may fill with fresh water after days of heavy rain and river flow.","zh":"幾天大雨和河水流入後，海港可能充滿淡水。"},{"en":"When ocean water fills with fresh water, its salinity and density can change.","zh":"當海水充滿淡水，鹽度和密度會改變。"},{"en":"This phrase describes freshwater accumulation.","zh":"這個短語描述淡水累積。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":13},{"front":"grows less dense","meaning":"密度變低","examples":[{"en":"Fresh water makes the North Atlantic grow less dense.","zh":"淡水令北大西洋密度變低。"},{"en":"Grows less dense means becomes lighter per unit of volume.","zh":"密度變低，是指每單位體積變得較輕。"},{"en":"Warm air grows less dense and rises above cooler air.","zh":"暖空氣密度變低，會升到較冷空氣之上。"},{"en":"Less dense ocean water is less likely to sink into deep layers.","zh":"密度較低的海水較不容易下沉到深層。"},{"en":"This phrase describes a physical change in density.","zh":"這個短語描述密度上的物理變化。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":13},{"front":"carried northward","meaning":"被向北帶去","examples":[{"en":"The Gulf Stream carries water northward.","zh":"墨西哥灣流把水向北帶去。"},{"en":"Carried northward means moved toward the north by a current, wind, or other force.","zh":"被向北帶去，是指由洋流、風或其他力量帶向北方。"},{"en":"Seeds may be carried northward by wind during a storm.","zh":"暴風中，種子可能被風向北帶去。"},{"en":"Water carried northward by the Gulf Stream can bring heat to cooler regions.","zh":"被墨西哥灣流向北帶去的水可以把熱量帶到較冷地區。"},{"en":"This phrase describes direction and transport.","zh":"這個短語描述方向和運送。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":13},{"front":"less able to sink","meaning":"較難下沉","examples":[{"en":"Fresher water is less able to sink.","zh":"較淡的水較難下沉。"},{"en":"Less able to sink means not as likely or capable of moving downward into deeper water.","zh":"較難下沉，是指較不可能或較不能向下移入深水。"},{"en":"A plastic bottle is less able to sink than a stone because it is lighter.","zh":"膠樽比石頭較難下沉，因為它較輕。"},{"en":"Fresher ocean water may stay near the surface because it is less dense.","zh":"較淡海水可能停留在表面附近，因為它密度較低。"},{"en":"This phrase links density with downward movement.","zh":"這個短語把密度與向下移動連接起來。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":13},{"front":"relatively fresh water","meaning":"相對較淡的水","examples":[{"en":"A new mass of relatively fresh water sits on top of the ocean.","zh":"一團新的相對較淡的水停留在海洋表面。"},{"en":"Relatively fresh water is water that is less salty compared with surrounding seawater.","zh":"相對較淡的水，是與周圍海水相比鹽度較低的水。"},{"en":"Water near a river mouth may be relatively fresh after heavy rainfall.","zh":"大雨後，河口附近的水可能相對較淡。"},{"en":"Relatively fresh water can sit above denser salty water and affect mixing.","zh":"相對較淡的水可以停留在較密的鹹水之上並影響混合。"},{"en":"This phrase describes lower salinity by comparison.","zh":"這個短語透過比較描述較低鹽度。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":13},{"front":"sits on top of","meaning":"停留在……上面","examples":[{"en":"Fresh water sits on top of denser ocean water.","zh":"淡水停留在密度較高的海水上面。"},{"en":"Sits on top of means rests or remains above something else.","zh":"停留在某物上面，是指在另一物之上保持或存在。"},{"en":"Oil sits on top of water because it is less dense.","zh":"油停留在水上面，因為它密度較低。"},{"en":"Fresh water can sit on top of salty water and stop normal sinking.","zh":"淡水可以停留在鹹水上面，並阻止正常下沉。"},{"en":"This phrase describes layering.","zh":"這個短語描述分層。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":13},{"front":"thermal blanket","meaning":"保溫毯","examples":[{"en":"The fresh water sits on top of the ocean like a thermal blanket.","zh":"淡水像保溫毯一樣停留在海洋上面。"},{"en":"A thermal blanket is a layer that keeps heat in and reduces heat movement.","zh":"保溫毯是保持熱量並減少熱量移動的層。"},{"en":"A blanket on a bed acts like a thermal blanket by keeping body heat close.","zh":"床上的毯子像保溫毯一樣，把身體熱量留在附近。"},{"en":"Fresh surface water can act like a thermal blanket if it stops heat and water from mixing normally.","zh":"如果表層淡水阻止熱量和水正常混合，它可以像保溫毯。"},{"en":"This phrase uses a familiar object to explain ocean layering.","zh":"這個短語用熟悉物件解釋海洋分層。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":13},{"front":"threatening","meaning":"威脅着","examples":[{"en":"The fresh water is threatening the thermohaline circulation.","zh":"淡水正威脅着溫鹽環流。"},{"en":"Threatening means creating danger for something or making it likely to be harmed.","zh":"威脅着，是指為某事造成危險或令其可能受損。"},{"en":"A leaking roof is threatening the books in a school library.","zh":"漏水屋頂正威脅着學校圖書館中的書籍。"},{"en":"Fresh water threatens circulation because it can weaken sinking and slow currents.","zh":"淡水威脅環流，因為它能削弱下沉並減慢洋流。"},{"en":"This word signals possible harm.","zh":"這個詞表示可能傷害。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":13},{"front":"in turn","meaning":"繼而","examples":[{"en":"That in turn could make the Gulf Stream slow down.","zh":"這繼而可能令墨西哥灣流減慢。"},{"en":"In turn means as the next result in a chain of cause and effect.","zh":"繼而，是指作為因果鏈中的下一個結果。"},{"en":"Poor sleep reduces focus; this in turn can lower exam performance.","zh":"睡眠不足會降低專注；這繼而會降低考試表現。"},{"en":"The phrase helps show how one change leads to another.","zh":"這個短語幫助顯示一項變化如何導致另一項。"},{"en":"It is useful for explaining sequences of effects.","zh":"它適合解釋一連串影響。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":13},{"front":"slow or veer southward","meaning":"減慢或轉向南方","examples":[{"en":"The Gulf Stream could slow or veer southward.","zh":"墨西哥灣流可能減慢或轉向南方。"},{"en":"Slow or veer southward means become slower or turn toward the south.","zh":"減慢或轉向南方，是指速度變慢或朝南方改變方向。"},{"en":"A river current may slow or veer southward after heavy sediment blocks its usual path.","zh":"如果大量沉積物阻塞原本路徑，河流可能減慢或轉向南方。"},{"en":"If the Gulf Stream slows or turns south, less heat may reach northern Europe.","zh":"如果墨西哥灣流減慢或轉南，較少熱量會到達北歐。"},{"en":"This phrase describes changes in both speed and direction.","zh":"這個短語描述速度和方向的變化。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":13},{"front":"at some point","meaning":"在某個時候","examples":[{"en":"At some point, the whole system could shut down.","zh":"在某個時候，整個系統可能停止運作。"},{"en":"At some point means at an unknown or unspecified time.","zh":"在某個時候，是指在未知或未指定的時間。"},{"en":"If a student never rests, at some point they may burn out.","zh":"如果學生從不休息，在某個時候可能會精疲力竭。"},{"en":"This phrase is used when the timing is uncertain but the possibility is real.","zh":"當時間不確定但可能性真實時，會使用這個短語。"},{"en":"It helps describe future risk without giving an exact date.","zh":"它幫助描述未來風險而不給出精確日期。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":13},{"front":"shut down","meaning":"停止運作","examples":[{"en":"The whole ocean circulation system could shut down quickly.","zh":"整個海洋環流系統可能迅速停止運作。"},{"en":"Shut down means stop operating or functioning.","zh":"停止運作，是指停止運行或發揮功能。"},{"en":"A computer may shut down if its battery runs out.","zh":"電腦電池耗盡時可能停止運作。"},{"en":"If an ocean circulation system shuts down, heat transport can change dramatically.","zh":"如果海洋環流系統停止運作，熱量輸送會大幅改變。"},{"en":"This phrase describes a system stopping, not just slowing.","zh":"這個短語描述系統停止，而不只是減慢。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":13},{"front":"increasing evidence","meaning":"越來越多證據","examples":[{"en":"There is increasing evidence that the system is nearing a transition point.","zh":"越來越多證據顯示該系統正接近轉變臨界點。"},{"en":"Increasing evidence means more information is gradually supporting a conclusion.","zh":"越來越多證據，是指更多資訊逐步支持某結論。"},{"en":"There is increasing evidence that regular exercise improves mood and sleep.","zh":"越來越多證據顯示定期運動能改善心情和睡眠。"},{"en":"When evidence increases, scientists become more confident that a pattern is real.","zh":"當證據增加，科學家更有信心某模式是真實的。"},{"en":"This phrase shows growing support for a claim.","zh":"這個短語顯示對主張的支持正在增加。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":14},{"front":"getting closer to","meaning":"越來越接近……","examples":[{"en":"Scientists believe we may be getting closer to a transition point.","zh":"科學家相信我們可能越來越接近轉變臨界點。"},{"en":"Getting closer to something means approaching it in time, distance, or degree.","zh":"越來越接近某事，是指在時間、距離或程度上接近它。"},{"en":"A student is getting closer to fluency when they can speak without translating every sentence.","zh":"當學生能不逐句翻譯地說話，他就越來越接近流利。"},{"en":"If a system gets closer to a limit, small changes may have larger effects.","zh":"如果系統越來越接近界線，小變化可能有更大影響。"},{"en":"This phrase describes movement toward a point or condition.","zh":"這個短語描述朝某點或狀態移動。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":14},{"front":"transition point","meaning":"轉變臨界點","examples":[{"en":"The system may be approaching a transition point.","zh":"該系統可能正接近轉變臨界點。"},{"en":"A transition point is a critical moment when a system changes from one state to another.","zh":"轉變臨界點是系統由一種狀態轉到另一種狀態的關鍵時刻。"},{"en":"A student reaches a transition point when they stop memorising phrases and start using them freely.","zh":"當學生停止背誦短語並開始自由使用時，就到達學習上的轉變臨界點。"},{"en":"In climate systems, crossing a transition point may cause sudden and lasting change.","zh":"在氣候系統中，越過轉變臨界點可能造成突然且持久變化。"},{"en":"This phrase describes a turning point in a system.","zh":"這個短語描述系統中的轉折點。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":14},{"front":"jump to a new state","meaning":"躍遷至新狀態","examples":[{"en":"The climate system could jump to a new state.","zh":"氣候系統可能躍遷至新狀態。"},{"en":"Jump to a new state means change suddenly into a different condition.","zh":"躍遷至新狀態，是指突然變成另一種情況。"},{"en":"A quiet classroom can jump to a new state of chaos if the fire alarm rings.","zh":"如果火警鐘響起，安靜課室可能突然變成混亂新狀態。"},{"en":"Climate systems may jump suddenly when gradual pressure crosses a threshold.","zh":"當逐步累積的壓力越過臨界點，氣候系統可能突然躍遷。"},{"en":"This phrase stresses abrupt change rather than slow adjustment.","zh":"這個短語強調突變，而不是慢慢調整。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":14},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter for each question.","zh":"學生為每條問題選出正確字母。"},{"en":"To choose the correct letter means to select the answer option that matches the text.","zh":"選出正確字母，是指選擇與文本相符的答案選項。"},{"en":"In a multiple-choice reading task, students choose A, B, C, or D.","zh":"在選擇題閱讀任務中，學生選擇 A、B、C 或 D。"},{"en":"Students should choose based on meaning, not just matching familiar words.","zh":"學生應根據意思選擇，而不只是配對熟悉字眼。"},{"en":"This phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":14},{"front":"opening paragraphs","meaning":"開首段落","examples":[{"en":"The writer uses paintings in the opening paragraphs.","zh":"作者在開首段落使用畫作。"},{"en":"Opening paragraphs are the first paragraphs of a text.","zh":"開首段落是文章最初的段落。"},{"en":"In an essay, opening paragraphs often introduce the topic and catch the reader’s attention.","zh":"在文章中，開首段落通常介紹題目並吸引讀者注意。"},{"en":"Strong opening paragraphs prepare readers for the main argument.","zh":"有力的開首段落讓讀者準備理解主要論點。"},{"en":"This phrase refers to the beginning section of a passage.","zh":"這個短語指篇章的開始部分。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":14},{"front":"illustrate","meaning":"說明","examples":[{"en":"The writer uses paintings to illustrate possible future climate change.","zh":"作者使用畫作來說明可能出現的未來氣候變化。"},{"en":"Illustrate means explain or make an idea clearer by using an example, picture, or comparison.","zh":"說明，是指透過例子、圖片或比較解釋或令想法更清楚。"},{"en":"A teacher may use a diagram to illustrate how blood moves through the heart.","zh":"老師可能用圖表說明血液如何流經心臟。"},{"en":"Illustrations help readers understand abstract ideas through visible examples.","zh":"說明能透過可見例子幫助讀者理解抽象想法。"},{"en":"This verb means show in a way that makes meaning clearer.","zh":"這個動詞指以令意思更清楚的方式展示。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":14},{"front":"possible future climate change","meaning":"可能出現的未來氣候變化","examples":[{"en":"The paintings illustrate possible future climate change.","zh":"這些畫作說明可能出現的未來氣候變化。"},{"en":"Possible future climate change means climate shifts that may happen later but are not certain.","zh":"可能出現的未來氣候變化，是指將來可能發生但未確定的氣候轉變。"},{"en":"City planners study possible future climate change before building flood defences.","zh":"城市規劃者在建造防洪設施前會研究可能出現的未來氣候變化。"},{"en":"Considering future possibilities helps people prepare before danger arrives.","zh":"考慮未來可能性有助人們在危險到來前準備。"},{"en":"This phrase describes predicted but uncertain climate developments.","zh":"這個短語描述被預測但不確定的氣候發展。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":14},{"front":"led his troops across","meaning":"帶領軍隊橫渡……","examples":[{"en":"The painting shows how Washington led his troops across the river.","zh":"這幅畫顯示華盛頓如何帶領軍隊橫渡河流。"},{"en":"Led his troops across means guided soldiers from one side of something to the other.","zh":"帶領軍隊橫渡，是指引導士兵從一邊穿過某物到另一邊。"},{"en":"A commander may lead troops across a bridge during a military operation.","zh":"指揮官可能在軍事行動中帶領軍隊橫過橋樑。"},{"en":"Leading troops across dangerous water shows leadership and risk.","zh":"帶領軍隊橫渡危險水域顯示領導力和風險。"},{"en":"This phrase describes military movement under command.","zh":"這個短語描述受指揮的軍事移動。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":14},{"front":"scientists believe to be possible","meaning":"科學家認為可能發生的事","examples":[{"en":"The question asks what scientists believe to be possible.","zh":"題目問科學家認為可能發生的事。"},{"en":"Scientists believe something to be possible means experts think it could happen, based on evidence.","zh":"科學家認為某事可能發生，是指專家根據證據認為它有可能。"},{"en":"Doctors may believe a new treatment to be possible after early trials show success.","zh":"早期試驗成功後，醫生可能認為新療法可行。"},{"en":"Scientific possibility does not always mean certainty; it means evidence supports the chance.","zh":"科學上的可能不一定是確定；它表示證據支持這個機會。"},{"en":"This phrase reports expert judgement carefully.","zh":"這個短語謹慎報告專家判斷。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":14},{"front":"may drop over","meaning":"可能在……下降","examples":[{"en":"The temperature may drop over much of the Northern Hemisphere.","zh":"氣溫可能在北半球大部分地區下降。"},{"en":"May drop over a region means might fall across a large part of that area.","zh":"可能在某地下降，是指可能在該區域大部分範圍內降低。"},{"en":"Rainfall may drop over the whole district during a long drought.","zh":"長期乾旱期間，降雨量可能在整個地區下降。"},{"en":"If temperature drops over a wide region, many people and ecosystems are affected.","zh":"如果氣溫在廣泛地區下降，許多人和生態系統會受影響。"},{"en":"This phrase combines possibility, decrease, and geographical coverage.","zh":"這個短語結合可能性、下降和地理範圍。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":14},{"front":"find it difficult to survive","meaning":"發現難以生存","examples":[{"en":"The world’s poor might find it difficult to survive another ice age.","zh":"全球貧困人口可能發現難以在另一個冰河時期生存。"},{"en":"To find it difficult to survive means to struggle to stay alive or maintain basic living conditions.","zh":"發現難以生存，是指難以維持生命或基本生活條件。"},{"en":"Families may find it difficult to survive if food prices rise and jobs disappear.","zh":"如果食物價格上升而工作消失，家庭可能發現難以生存。"},{"en":"Survival becomes harder when people lack savings, shelter, or freedom to move.","zh":"當人們缺乏儲蓄、住所或遷移自由，生存會更困難。"},{"en":"This phrase describes serious hardship.","zh":"這個短語描述嚴重困境。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":14},{"front":"another ice age","meaning":"另一個冰河時期","examples":[{"en":"Another ice age could be especially hard for poor communities.","zh":"另一個冰河時期對貧困社區可能特別艱難。"},{"en":"Another ice age means a further period of major cooling after earlier ice ages.","zh":"另一個冰河時期，是指在早期冰河時期之後再次出現的重大降溫時期。"},{"en":"People may fear another ice age if climate systems begin showing strong cooling signs.","zh":"如果氣候系統開始顯示強烈降溫跡象，人們可能擔心另一個冰河時期。"},{"en":"Another ice age would be difficult because societies are built around current climate conditions.","zh":"另一個冰河時期會很困難，因為社會是圍繞現時氣候條件建立的。"},{"en":"This phrase refers to a possible repeat of severe past cooling.","zh":"這個短語指嚴重過去降溫可能再次出現。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":14},{"front":"borders are closed","meaning":"邊境關閉","examples":[{"en":"Migration is harder because borders are closed.","zh":"遷移更困難，因為邊境關閉。"},{"en":"Borders are closed means countries do not allow people to cross freely.","zh":"邊境關閉，是指國家不容許人們自由跨越邊界。"},{"en":"During a crisis, closed borders can stop families from escaping danger.","zh":"危機期間，關閉邊境會阻止家庭逃離危險。"},{"en":"Closed borders make climate migration more difficult because people cannot simply move south.","zh":"邊境關閉令氣候遷移更困難，因為人們不能簡單向南移動。"},{"en":"This phrase describes political restriction on movement.","zh":"這個短語描述對流動的政治限制。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":14},{"front":"continental Europe","meaning":"歐洲大陸","examples":[{"en":"Continental Europe is warmer than North America at the same latitude.","zh":"在相同緯度，歐洲大陸比北美更暖。"},{"en":"Continental Europe means mainland Europe, excluding islands such as Britain and Ireland.","zh":"歐洲大陸是指歐洲本土，不包括英國和愛爾蘭等島嶼。"},{"en":"Travellers from Britain may refer to France, Germany, and Italy as continental Europe.","zh":"來自英國的旅客可能把法國、德國和意大利稱為歐洲大陸。"},{"en":"The phrase is useful when comparing mainland Europe with nearby islands or other continents.","zh":"這個短語適合比較歐洲本土與附近島嶼或其他大陸。"},{"en":"In this passage, it helps explain Europe’s unusual warmth.","zh":"在篇章中，它有助解釋歐洲異常溫暖。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":15},{"front":"released by tropical currents","meaning":"由熱帶洋流釋放的熱量","examples":[{"en":"Prevailing winds carry heat released by tropical currents towards Europe.","zh":"盛行風把由熱帶洋流釋放的熱量帶向歐洲。"},{"en":"Heat released by tropical currents is warmth given off by ocean currents that came from warm regions.","zh":"由熱帶洋流釋放的熱量，是來自溫暖地區的洋流放出的熱。"},{"en":"Warm sea currents can release heat to the air above them.","zh":"暖海流可以把熱量釋放給其上方空氣。"},{"en":"Winds can then carry that released heat toward distant land areas.","zh":"然後風可以把這些釋放出的熱量帶向遠方陸地。"},{"en":"This phrase explains how ocean heat reaches Europe.","zh":"這個短語解釋海洋熱量如何到達歐洲。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":15},{"front":"towards Europe","meaning":"朝向歐洲","examples":[{"en":"Warmth from ocean currents is carried towards Europe.","zh":"來自洋流的暖意被帶向歐洲。"},{"en":"Towards Europe means in the direction of Europe.","zh":"朝向歐洲，是指朝歐洲方向。"},{"en":"A flight from New York towards Europe crosses the Atlantic Ocean.","zh":"從紐約飛往歐洲的航班會橫越大西洋。"},{"en":"Heat moving towards Europe can affect winter temperatures there.","zh":"向歐洲移動的熱量會影響那裡的冬季氣溫。"},{"en":"This phrase describes direction of movement.","zh":"這個短語描述移動方向。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":15},{"front":"list of people and organisations","meaning":"人物和組織列表","examples":[{"en":"Students match statements with the correct person or organisation.","zh":"學生把陳述與正確人物或組織配對。"},{"en":"A list of people and organisations is a set of names used as answer choices in a matching task.","zh":"人物和組織列表，是配對題中用作答案選項的一組姓名和機構名稱。"},{"en":"In a reading test, students may match ideas to a list of scientists, reports, and institutions.","zh":"在閱讀測驗中，學生可能把想法配對到科學家、報告和機構列表。"},{"en":"Such lists test whether students can connect information with the correct source.","zh":"這類列表測試學生能否把資訊與正確來源連接起來。"},{"en":"This phrase describes an exam matching section.","zh":"這個短語描述考試配對部分。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":15},{"front":"appropriate letter","meaning":"適當字母","examples":[{"en":"Students write the appropriate letter in each box.","zh":"學生在每個方格中寫上適當字母。"},{"en":"Appropriate letter means the correct option letter for the answer.","zh":"適當字母，是答案的正確選項字母。"},{"en":"If paragraph B contains the information, B is the appropriate letter.","zh":"如果 B 段包含該資訊，B 就是適當字母。"},{"en":"Choosing the appropriate letter requires understanding meaning, not guessing from keywords.","zh":"選擇適當字母需要理解意思，而不是從關鍵字猜測。"},{"en":"This phrase is common in answer-sheet instructions.","zh":"這個短語常見於答題紙指示。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":15},{"front":"may use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"Students may use any letter more than once.","zh":"學生可重複使用任何字母。"},{"en":"May use any letter more than once means the same answer option can be chosen for several questions.","zh":"可重複使用任何字母，是指同一答案選項可以用於幾條問題。"},{"en":"In a matching task, one scientist may match more than one statement.","zh":"在配對題中，一位科學家可能配對多於一項陳述。"},{"en":"This instruction prevents students from wrongly assuming each option is used only once.","zh":"這項指示防止學生錯誤假設每個選項只用一次。"},{"en":"This phrase is important in IELTS-style matching questions.","zh":"這個短語在 IELTS 類型配對題中很重要。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":15},{"front":"not prepared for","meaning":"未為……做好準備","examples":[{"en":"Most Americans may not be prepared for the next ice age.","zh":"大多數美國人可能未為下一個冰河時期做好準備。"},{"en":"Not prepared for something means not ready to deal with it.","zh":"未為某事做好準備，是指尚未準備好應對它。"},{"en":"A student who has not revised may not be prepared for a surprise test.","zh":"沒有溫習的學生可能未為突擊測驗做好準備。"},{"en":"People who are not prepared for a crisis may react slowly or make poor decisions.","zh":"未為危機做好準備的人可能反應緩慢或作出差劣決定。"},{"en":"This phrase describes lack of readiness.","zh":"這個短語描述缺乏準備。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":15},{"front":"result of abrupt climate change","meaning":"突發氣候變化的結果","examples":[{"en":"The result of abrupt climate change could be catastrophic.","zh":"突發氣候變化的結果可能是災難性的。"},{"en":"Result of abrupt climate change means the consequence caused by sudden major climate shifts.","zh":"突發氣候變化的結果，是由突然重大氣候轉變造成的後果。"},{"en":"Crop failure can be a result of abrupt climate change if temperatures change too quickly.","zh":"如果氣溫變化太快，農作物失收可以是突發氣候變化的結果。"},{"en":"Results may be severe because societies cannot adapt immediately.","zh":"結果可能嚴重，因為社會不能立即適應。"},{"en":"This phrase links sudden climate change with its effects.","zh":"這個短語把突然氣候變化與其影響連接起來。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":15},{"front":"catastrophic","meaning":"災難性的","examples":[{"en":"Abrupt climate change could be catastrophic.","zh":"突發氣候變化可能是災難性的。"},{"en":"Catastrophic means causing extreme damage, suffering, or failure.","zh":"災難性的，是指造成極大破壞、痛苦或失敗。"},{"en":"A hospital power failure during surgery could be catastrophic.","zh":"醫院在手術期間停電可能是災難性的。"},{"en":"Climate change becomes catastrophic when food, water, health, and safety are all threatened.","zh":"當食物、水、健康和安全都受威脅，氣候變化就變得災難性。"},{"en":"This word describes disaster-level seriousness.","zh":"這個詞描述災害級嚴重性。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":15},{"front":"not as cold as it once was","meaning":"不像過去那樣寒冷","examples":[{"en":"The world is not as cold as it once was.","zh":"世界不像過去那樣寒冷。"},{"en":"Not as cold as it once was means it used to be colder than it is now.","zh":"不像過去那樣寒冷，是指以前比現在更冷。"},{"en":"A city where rivers no longer freeze is not as cold as it once was.","zh":"河流不再結冰的城市，已不像過去那樣寒冷。"},{"en":"This phrase compares present climate with past climate.","zh":"這個短語比較現時氣候與過去氣候。"},{"en":"It suggests warming or reduced cold over time.","zh":"它暗示隨時間出現變暖或寒冷減少。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":15},{"front":"closely connected to","meaning":"與……密切相關","examples":[{"en":"Global warming may be closely connected to a future ice age.","zh":"全球暖化可能與未來冰河時期密切相關。"},{"en":"Closely connected to something means strongly related to it.","zh":"與某事密切相關，是指與它有強烈關係。"},{"en":"Poor sleep is closely connected to weak concentration in class.","zh":"睡眠不足與課堂專注力差密切相關。"},{"en":"In climate systems, one change can be closely connected to another through oceans and air.","zh":"在氣候系統中，一項變化可以透過海洋和空氣與另一項變化密切相關。"},{"en":"This phrase shows a strong relationship, not coincidence.","zh":"這個短語顯示強烈關係，而不是巧合。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":15},{"front":"warned a conference about","meaning":"在會議上警告有關……","examples":[{"en":"Bob Dickson warned a conference about changes in ocean water.","zh":"Bob Dickson 在會議上警告有關海水變化。"},{"en":"Warned a conference about something means told meeting participants about a serious risk or problem.","zh":"在會議上警告有關某事，是指向會議參加者說明嚴重風險或問題。"},{"en":"A doctor warned a conference about rising antibiotic resistance.","zh":"醫生在會議上警告有關抗生素抗藥性上升。"},{"en":"Experts warn conferences so information spreads quickly among professionals.","zh":"專家在會議上提出警告，讓資訊在專業人士之間快速傳播。"},{"en":"This phrase describes a formal public warning.","zh":"這個短語描述正式公開警告。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":15},{"front":"changes in ocean water","meaning":"海水變化","examples":[{"en":"Scientists are concerned about changes in ocean water.","zh":"科學家擔心海水變化。"},{"en":"Changes in ocean water are shifts in temperature, salinity, density, movement, or chemical condition.","zh":"海水變化是溫度、鹽度、密度、流動或化學狀況的轉變。"},{"en":"A drop in salinity is one type of change in ocean water.","zh":"鹽度下降就是一種海水變化。"},{"en":"Ocean-water changes can affect currents, weather, marine life, and climate.","zh":"海水變化會影響洋流、天氣、海洋生物和氣候。"},{"en":"This phrase refers to physical or chemical ocean changes.","zh":"這個短語指海洋的物理或化學變化。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":15},{"front":"complete the flow chart","meaning":"完成流程圖","examples":[{"en":"Students complete the flow chart using words from the passage.","zh":"學生用文章中的字詞完成流程圖。"},{"en":"Complete the flow chart means fill missing parts in a diagram that shows a process.","zh":"完成流程圖，是指填補顯示過程的圖表中的缺失部分。"},{"en":"In a reading test, students may complete a flow chart about how ocean circulation changes.","zh":"在閱讀測驗中，學生可能完成關於海洋環流如何變化的流程圖。"},{"en":"Flow charts help students see cause-and-effect steps in order.","zh":"流程圖幫助學生按順序看見因果步驟。"},{"en":"This phrase is an exam instruction for process completion.","zh":"這個短語是流程填空題的考試指示。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":15},{"front":"no more than three words","meaning":"不超過三個詞","examples":[{"en":"Students should choose no more than three words from the passage.","zh":"學生應從文章中選擇不超過三個詞。"},{"en":"No more than three words means the answer may contain one, two, or three words, but not four.","zh":"不超過三個詞，是指答案可以有一、二或三個詞，但不能有四個。"},{"en":"If the instruction says no more than three words, “fresh water enters” has three words and is allowed.","zh":"如果指示說不超過三個詞，“fresh water enters” 有三個詞，可以接受。"},{"en":"Word limits prevent students from copying long unnecessary phrases.","zh":"字數限制防止學生抄寫冗長而不必要的短語。"},{"en":"This phrase gives a strict answer-length rule.","zh":"這個短語給出嚴格答案長度規則。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":16},{"front":"flow chart","meaning":"流程圖","examples":[{"en":"The flow chart shows stages in a climate process.","zh":"流程圖顯示氣候過程中的階段。"},{"en":"A flow chart is a diagram that shows steps in a process using boxes, arrows, or short labels.","zh":"流程圖是用方格、箭嘴或短標籤顯示過程步驟的圖表。"},{"en":"A teacher may use a flow chart to explain how a bill becomes a law.","zh":"老師可能用流程圖解釋法案如何成為法律。"},{"en":"Flow charts make complex processes easier because they show order clearly.","zh":"流程圖令複雜過程更容易理解，因為它清楚顯示次序。"},{"en":"This phrase refers to a visual process diagram.","zh":"這個短語指視覺化過程圖表。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":16},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers should be taken from the passage.","zh":"答案應從文章中取得。"},{"en":"From the passage means the information or words must come directly from the reading text.","zh":"從文章中，是指資訊或字詞必須直接來自閱讀文本。"},{"en":"In IELTS reading, students should use words from the passage when the instruction requires it.","zh":"在 IELTS 閱讀中，當指示要求時，學生應使用文章中的字詞。"},{"en":"Using outside knowledge can lead to wrong answers if the passage does not support it.","zh":"如果文章不支持，使用外部知識可能導致錯誤答案。"},{"en":"This phrase tells students the source of the answer.","zh":"這個短語告訴學生答案來源。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":16},{"front":"fresh water enters","meaning":"淡水進入","examples":[{"en":"Fresh water enters the North Atlantic and changes ocean density.","zh":"淡水進入北大西洋並改變海洋密度。"},{"en":"Fresh water enters means non-salty water moves into another body of water.","zh":"淡水進入，是指非鹹水流入另一片水域。"},{"en":"After heavy rain, fresh water enters the harbour from nearby rivers.","zh":"大雨後，淡水從附近河流進入海港。"},{"en":"When fresh water enters salty ocean water, salinity and density can fall.","zh":"當淡水進入鹹海水，鹽度和密度會下降。"},{"en":"This phrase describes the first step in the climate-process flow chart.","zh":"這個短語描述氣候流程圖中的第一步。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":16},{"front":"ocean circulation","meaning":"海洋環流","examples":[{"en":"Fresh water can disrupt ocean circulation.","zh":"淡水可以擾亂海洋環流。"},{"en":"Ocean circulation is the large-scale movement of seawater around the world.","zh":"海洋環流是海水在全球範圍內的大規模移動。"},{"en":"Ocean circulation moves heat, salt, oxygen, and nutrients through the seas.","zh":"海洋環流在海洋中移動熱量、鹽分、氧氣和養分。"},{"en":"If ocean circulation changes, climate and marine ecosystems may also change.","zh":"如果海洋環流改變，氣候和海洋生態系統也可能改變。"},{"en":"This phrase refers to the ocean’s moving current system.","zh":"這個短語指海洋中移動的洋流系統。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":16},{"front":"becomes less dense","meaning":"密度變低","examples":[{"en":"Water becomes less dense when more fresh water is added.","zh":"加入更多淡水時，水的密度變低。"},{"en":"Becomes less dense means becomes lighter for the same volume.","zh":"密度變低，是指同樣體積下變得較輕。"},{"en":"Warm air becomes less dense and rises above cool air.","zh":"暖空氣密度變低，會升到冷空氣之上。"},{"en":"Ocean water that becomes less dense may fail to sink properly.","zh":"密度變低的海水可能無法正常下沉。"},{"en":"This phrase describes a density change that affects movement.","zh":"這個短語描述影響移動的密度變化。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":16},{"front":"unable to sink","meaning":"無法下沉","examples":[{"en":"Less dense water becomes unable to sink properly.","zh":"密度較低的水變得無法正常下沉。"},{"en":"Unable to sink means not able to move downward into deeper water.","zh":"無法下沉，是指不能向下移入更深的水中。"},{"en":"A floating toy is unable to sink because it is too light.","zh":"漂浮玩具因太輕而無法下沉。"},{"en":"If surface water is unable to sink, deep ocean circulation may weaken.","zh":"如果表層水無法下沉，深海環流可能減弱。"},{"en":"This phrase links physical density with ocean movement.","zh":"這個短語把物理密度與海洋運動連接起來。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":16},{"front":"circulation slows","meaning":"環流減慢","examples":[{"en":"The Gulf Stream may slow if thermohaline circulation is disrupted.","zh":"如果溫鹽環流受擾，墨西哥灣流可能減慢。"},{"en":"Circulation slows means a moving system of water or air begins to move more slowly.","zh":"環流減慢，是指水或空氣的流動系統開始移動得較慢。"},{"en":"Blood circulation slows when a person sits still for too long.","zh":"人坐着不動太久時，血液循環會減慢。"},{"en":"If ocean circulation slows, less heat may be transported to distant regions.","zh":"如果海洋環流減慢，較少熱量會被運送到遠方地區。"},{"en":"This phrase describes reduced movement in a circulation system.","zh":"這個短語描述環流系統中的移動減弱。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":16},{"front":"cooling may follow","meaning":"隨後可能出現降溫","examples":[{"en":"If the Gulf Stream weakens, cooling may follow.","zh":"如果墨西哥灣流減弱，隨後可能出現降溫。"},{"en":"Cooling may follow means colder conditions may happen as the next result.","zh":"隨後可能出現降溫，是指較冷情況可能作為下一個結果發生。"},{"en":"If clouds block the sun all week, cooler weather may follow.","zh":"如果雲層整星期遮住太陽，之後可能出現較冷天氣。"},{"en":"In the passage, cooling may follow because less ocean heat reaches northern regions.","zh":"在篇章中，隨後可能出現降溫，是因為較少海洋熱量到達北方地區。"},{"en":"This phrase shows a possible consequence in a sequence.","zh":"這個短語顯示一連串過程中的可能後果。"}],"source":"Passage 2 Flash Cards 27 - A New Ice Age.pdf","sourcePage":16}],"ielts/reading/passage-2/Practice 28":[{"front":"The Ant and the Mandarin","meaning":"螞蟻與柑橘","examples":[{"en":"The passage explains how ants were used to protect mandarin orange trees.","zh":"文章解釋螞蟻如何被用來保護柑橘樹。"},{"en":"The Ant and the Mandarin is a title about ants and mandarin orange farming.","zh":"The Ant and the Mandarin 是一個關於螞蟻和柑橘種植的標題。"},{"en":"A reading passage with this title may discuss insects, fruit trees, and farming methods.","zh":"以這個標題命名的閱讀篇章，可能討論昆蟲、果樹和農業方法。"},{"en":"The title suggests that a small insect plays an important role in protecting fruit.","zh":"這個標題暗示一種小昆蟲在保護水果方面扮演重要角色。"},{"en":"This title connects an animal with a crop to introduce biological pest control.","zh":"這個標題把動物與農作物連起來，以引出生物害蟲防治。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":1},{"front":"rid their fields of","meaning":"使田地擺脫……","examples":[{"en":"The farmers wanted to rid their fields of cutworms.","zh":"農民想使田地擺脫地老虎幼蟲。"},{"en":"To rid a place of something means to remove something unwanted from it.","zh":"rid a place of something 指從某地移除不想要的東西。"},{"en":"A school may try to rid classrooms of noise during exams.","zh":"學校可能嘗試在考試期間使課室擺脫噪音。"},{"en":"Farmers rid fields of pests so crops can grow safely.","zh":"農民清除田地中的害蟲，好讓農作物安全生長。"},{"en":"This phrase is used when something harmful or annoying must be removed.","zh":"當有害或令人煩惱的東西必須被移除時，可以使用這個短語。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":1},{"front":"cutworms","meaning":"地老虎幼蟲；切根蟲","examples":[{"en":"The cutworms were attacking the farmers’ crops.","zh":"地老虎幼蟲正在侵害農民的農作物。"},{"en":"Cutworms are caterpillar-like pests that damage young plants near the ground.","zh":"cutworms 是像毛蟲的害蟲，會在近地面位置傷害幼苗。"},{"en":"A vegetable farmer may find cutworms around damaged seedlings.","zh":"種菜農民可能在受損幼苗附近發現地老虎幼蟲。"},{"en":"Cutworms can reduce harvests because they cut through young stems.","zh":"地老虎幼蟲會咬斷幼莖，因此可能降低收成。"},{"en":"Farmers usually control cutworms before they destroy too many plants.","zh":"農民通常會在地老虎幼蟲摧毀太多植物前控制牠們。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":1},{"front":"attacking their crops","meaning":"侵害他們的農作物","examples":[{"en":"The farmers wanted to stop the pests attacking their crops.","zh":"農民想阻止害蟲侵害他們的農作物。"},{"en":"Attacking their crops means damaging or eating the plants they grow.","zh":"attacking their crops 指破壞或吃掉他們種植的植物。"},{"en":"Insects attacking a farmer’s crops may leave holes in leaves.","zh":"侵害農作物的昆蟲可能在葉上留下洞。"},{"en":"When pests attack crops, farmers may lose food and income.","zh":"當害蟲侵害農作物時，農民可能失去食物和收入。"},{"en":"This phrase is common when describing plant damage caused by animals or insects.","zh":"這個短語常用於描述動物或昆蟲造成的植物損害。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":1},{"front":"took the pests to court","meaning":"將害蟲告上法庭","examples":[{"en":"The farmers took the pests to court.","zh":"農民將害蟲告上法庭。"},{"en":"To take someone to court means to bring a legal case against them.","zh":"take someone to court 指對某人提出法律訴訟。"},{"en":"A tenant may take a landlord to court over unsafe housing.","zh":"租客可能因住房不安全而將業主告上法庭。"},{"en":"Taking pests to court sounds absurd because insects cannot understand human law.","zh":"將害蟲告上法庭聽起來荒謬，因為昆蟲不能理解人類法律。"},{"en":"This phrase is humorous here because farmers treated insects like criminals.","zh":"這個短語在此帶幽默感，因為農民把昆蟲當成罪犯。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":1},{"front":"were tried","meaning":"被審判","examples":[{"en":"The worms were tried and found guilty.","zh":"這些蟲被審判並被判有罪。"},{"en":"Were tried means were judged in a court or formal legal process.","zh":"were tried 指在法庭或正式法律程序中被審理。"},{"en":"The suspect was tried after the police collected evidence.","zh":"警方收集證據後，疑犯被審判。"},{"en":"If someone is tried fairly, both sides can present evidence.","zh":"如果某人受到公平審判，雙方都可以提出證據。"},{"en":"In this passage, the idea of worms being tried creates comic absurdity.","zh":"在這篇文章中，蟲被審判的想法製造了荒謬喜感。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":1},{"front":"found guilty","meaning":"被判有罪","examples":[{"en":"The worms were found guilty by the court.","zh":"這些蟲被法庭判有罪。"},{"en":"Found guilty means officially judged to have committed an offence.","zh":"found guilty 指被正式判定犯了罪。"},{"en":"A driver may be found guilty if evidence shows they ignored a red light.","zh":"如果證據顯示司機衝紅燈，他可能被判有罪。"},{"en":"When someone is found guilty, punishment may follow.","zh":"當某人被判有罪後，可能會受到懲罰。"},{"en":"The phrase is legal, but here it is used humorously for worms.","zh":"這個短語屬法律用語，但在這裡被幽默地用於蟲身上。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":1},{"front":"excommunicated","meaning":"被逐出教會","examples":[{"en":"The worms were excommunicated by the archbishop.","zh":"這些蟲被大主教逐出教會。"},{"en":"Excommunicated means officially expelled from a religious community.","zh":"excommunicated 指被正式逐出宗教群體。"},{"en":"In old religious history, a person could be excommunicated for serious offences.","zh":"在舊時宗教歷史中，一個人可能因嚴重罪行被逐出教會。"},{"en":"Excommunication removes someone from church membership or religious acceptance.","zh":"逐出教會會使某人失去教會成員身份或宗教接納。"},{"en":"Using this word for worms makes the story sound strange and comic.","zh":"把這個字用於蟲身上，令故事聽起來奇怪而滑稽。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":1},{"front":"archbishop","meaning":"大主教","examples":[{"en":"The archbishop excommunicated the worms.","zh":"大主教將這些蟲逐出教會。"},{"en":"An archbishop is a high-ranking bishop in some Christian churches.","zh":"archbishop 是某些基督教教會中的高級主教。"},{"en":"An archbishop may lead important religious ceremonies.","zh":"大主教可能主持重要宗教儀式。"},{"en":"Because an archbishop has authority, his judgement could carry great weight.","zh":"由於大主教有權威，他的判斷可能很有分量。"},{"en":"In this story, the archbishop’s role makes the pest trial even more unusual.","zh":"在這個故事中，大主教的角色令害蟲審判更加不尋常。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":1},{"front":"a more practical approach to","meaning":"對……較實際的方法","examples":[{"en":"Chinese farmers had a more practical approach to pest control.","zh":"中國農民對害蟲防治有較實際的方法。"},{"en":"A more practical approach to something is a method that works better in real life.","zh":"a more practical approach to something 指在現實中更有效的方法。"},{"en":"A school may take a more practical approach to discipline by teaching students clear routines.","zh":"學校可能透過教學生清楚常規，採取更實際的紀律方法。"},{"en":"Practical approaches often solve problems directly instead of relying on hope.","zh":"實際方法通常直接解決問題，而不是依賴希望。"},{"en":"This phrase contrasts useful action with unrealistic ideas.","zh":"這個短語把有用行動與不切實際想法作對比。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":1},{"front":"pest control","meaning":"害蟲防治","examples":[{"en":"Chinese farmers used frogs, ducks and ants for pest control.","zh":"中國農民使用青蛙、鴨和螞蟻進行害蟲防治。"},{"en":"Pest control means managing or removing animals and insects that damage crops or homes.","zh":"pest control 指管理或清除會傷害農作物或家居的動物和昆蟲。"},{"en":"A restaurant needs pest control if cockroaches appear in the kitchen.","zh":"如果餐廳廚房出現蟑螂，就需要害蟲防治。"},{"en":"Good pest control protects food, health, and property.","zh":"良好的害蟲防治可以保護食物、健康和財產。"},{"en":"Pest control can use chemicals, traps, animals, or natural predators.","zh":"害蟲防治可以使用化學品、陷阱、動物或天然捕食者。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":2},{"front":"rather than relying on","meaning":"而不是依賴……","examples":[{"en":"Rather than relying on divine intervention, Chinese farmers used animals.","zh":"中國農民使用動物，而不是依賴神明介入。"},{"en":"Rather than relying on something means choosing another method instead of depending on it.","zh":"rather than relying on something 指選擇另一種方法，而不是依靠某事。"},{"en":"Rather than relying on luck, students should revise before exams.","zh":"學生應該在考試前溫習，而不是依賴運氣。"},{"en":"Farmers used animals because practical control worked better than prayer alone.","zh":"農民使用動物，因為實際防治比單靠祈禱更有效。"},{"en":"This phrase clearly contrasts two possible ways of solving a problem.","zh":"這個短語清楚對比兩種可能的解決問題方式。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":2},{"front":"divine intervention","meaning":"神明介入","examples":[{"en":"Chinese farmers did not rely on divine intervention.","zh":"中國農民沒有依賴神明介入。"},{"en":"Divine intervention means help or action believed to come from a god.","zh":"divine intervention 指被認為來自神明的幫助或行動。"},{"en":"Some people pray for divine intervention when a situation seems hopeless.","zh":"當情況看似無望時，有些人會祈求神明介入。"},{"en":"Depending only on divine intervention may delay practical action.","zh":"只依靠神明介入可能延遲實際行動。"},{"en":"This phrase is often used when people hope a higher power will solve a problem.","zh":"當人們希望更高力量解決問題時，常使用這個短語。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":2},{"front":"put their faith in","meaning":"信任；寄望於……","examples":[{"en":"Chinese farmers put their faith in frogs, ducks and ants.","zh":"中國農民信任青蛙、鴨和螞蟻。"},{"en":"To put your faith in someone or something means to trust them strongly.","zh":"put your faith in someone or something 指強烈信任某人或某物。"},{"en":"Parents may put their faith in a good teacher to help a struggling child.","zh":"父母可能寄望於好老師幫助學習有困難的孩子。"},{"en":"Farmers put faith in natural predators when they believe those predators can protect crops.","zh":"當農民相信天然捕食者能保護作物時，就會寄望於牠們。"},{"en":"This phrase shows trust, confidence, and hope.","zh":"這個短語表示信任、信心和希望。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":2},{"front":"snap up","meaning":"快速吃掉","examples":[{"en":"Frogs and ducks were encouraged to snap up pests in the paddies.","zh":"人們鼓勵青蛙和鴨在稻田中快速吃掉害蟲。"},{"en":"To snap up something means to take or eat it quickly.","zh":"snap up something 指快速拿走或吃掉某物。"},{"en":"Customers may snap up discounted phones during a sale.","zh":"顧客可能在減價期間快速搶購折扣手機。"},{"en":"Frogs snap up insects quickly, so they can reduce pest numbers.","zh":"青蛙能快速吃掉昆蟲，因此可以減少害蟲數量。"},{"en":"This phrase suggests fast action before something escapes or disappears.","zh":"這個短語暗示在某物逃走或消失前迅速行動。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":2},{"front":"paddies","meaning":"稻田","examples":[{"en":"Frogs and ducks caught pests in the paddies.","zh":"青蛙和鴨在稻田中捕捉害蟲。"},{"en":"Paddies are wet fields where rice is grown.","zh":"paddies 是種植稻米的濕田。"},{"en":"Farmers may walk carefully through paddies filled with water and young rice plants.","zh":"農民可能小心走過充滿水和幼稻的稻田。"},{"en":"Paddies attract insects, so frogs and ducks can help control pests there.","zh":"稻田會吸引昆蟲，所以青蛙和鴨可以在那裡幫助控制害蟲。"},{"en":"This word is mainly used when talking about rice farming.","zh":"這個字主要用於談論稻米種植。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":2},{"front":"plague of locusts","meaning":"蝗災","examples":[{"en":"Frogs and ducks also dealt with the occasional plague of locusts.","zh":"青蛙和鴨也會處理偶爾出現的蝗災。"},{"en":"A plague of locusts is a huge swarm of locusts that destroys crops.","zh":"plague of locusts 指大量蝗蟲群摧毀農作物。"},{"en":"A village may face hunger after a plague of locusts eats the fields.","zh":"一條村莊在蝗災吃光田地後可能面臨飢餓。"},{"en":"Locust plagues are dangerous because many insects attack at the same time.","zh":"蝗災很危險，因為大量昆蟲同時攻擊。"},{"en":"This phrase describes a serious farming disaster, not a few insects.","zh":"這個短語描述嚴重農業災害，而不是幾隻昆蟲。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":2},{"front":"the notion of","meaning":"……的概念","examples":[{"en":"The notion of biological control began with an ant.","zh":"生物防治的概念始於一種螞蟻。"},{"en":"The notion of something means the idea or concept of it.","zh":"the notion of something 指某事的想法或概念。"},{"en":"The notion of online learning became more familiar during school closures.","zh":"網上學習的概念在停課期間變得更熟悉。"},{"en":"A simple observation can lead to the notion of a new solution.","zh":"一個簡單觀察可以帶來新解決方法的概念。"},{"en":"This phrase is useful when introducing an idea.","zh":"這個短語適合用來介紹一個想法。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":2},{"front":"biological control","meaning":"生物防治","examples":[{"en":"Biological control began with the use of ants.","zh":"生物防治始於使用螞蟻。"},{"en":"Biological control means using living organisms to control pests.","zh":"biological control 指使用生物來控制害蟲。"},{"en":"Farmers may use ladybirds as biological control against aphids.","zh":"農民可能使用瓢蟲作為對付蚜蟲的生物防治方法。"},{"en":"Biological control can reduce the need for chemical pesticides.","zh":"生物防治可以減少對化學農藥的需要。"},{"en":"This method works best when the predator and pest are carefully balanced.","zh":"當捕食者與害蟲之間保持良好平衡時，這種方法最有效。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":2},{"front":"more specifically","meaning":"更準確地說","examples":[{"en":"More specifically, it started with the yellow citrus ant.","zh":"更準確地說，它始於黃柑橘蟻。"},{"en":"More specifically means giving a clearer or more exact detail.","zh":"more specifically 指給出更清楚或更精確的細節。"},{"en":"I need help with English; more specifically, I need help with grammar.","zh":"我需要英文幫助；更準確地說，我需要文法幫助。"},{"en":"Writers use this phrase to narrow a general statement.","zh":"作者使用這個短語來收窄一般陳述。"},{"en":"It helps readers understand exactly what the speaker means.","zh":"它幫助讀者準確理解說話者的意思。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":2},{"front":"predatory yellow citrus ant","meaning":"捕食性的黃柑橘蟻","examples":[{"en":"The predatory yellow citrus ant protected orange groves.","zh":"捕食性的黃柑橘蟻保護了橙園。"},{"en":"A predatory yellow citrus ant is an ant that hunts other insects around citrus trees.","zh":"predatory yellow citrus ant 指在柑橘樹附近捕食其他昆蟲的黃色螞蟻。"},{"en":"Farmers may value predatory ants because they eat pests.","zh":"農民可能重視捕食性螞蟻，因為牠們會吃害蟲。"},{"en":"Predatory insects help crops when they kill insects that damage plants.","zh":"捕食性昆蟲殺死傷害植物的昆蟲時，能幫助農作物。"},{"en":"This phrase highlights the ant’s colour, habitat, and hunting role.","zh":"這個短語突出螞蟻的顏色、棲息環境和捕食角色。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":3},{"front":"Oecophylla smaragdina","meaning":"黃猄蟻；織葉蟻的一種","examples":[{"en":"Oecophylla smaragdina has been used in southern China for centuries.","zh":"黃猄蟻在中國南方已被使用了數百年。"},{"en":"Oecophylla smaragdina is the scientific name of a weaver ant species.","zh":"Oecophylla smaragdina 是一種織葉蟻的學名。"},{"en":"Scientists use Latin names like Oecophylla smaragdina to identify species exactly.","zh":"科學家使用 Oecophylla smaragdina 這類拉丁名稱來準確識別物種。"},{"en":"Scientific names prevent confusion when common names differ between regions.","zh":"當普通名稱因地區而異時，學名可以避免混淆。"},{"en":"In this passage, the name refers to the yellow citrus ant.","zh":"在這篇文章中，這個名稱指黃柑橘蟻。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":3},{"front":"polishing off pests","meaning":"消滅害蟲","examples":[{"en":"The yellow citrus ant has been polishing off pests in orange groves.","zh":"黃柑橘蟻一直在橙園中消滅害蟲。"},{"en":"To polish off pests means to kill or eat them completely and efficiently.","zh":"polish off pests 指完全而有效地殺死或吃掉害蟲。"},{"en":"A cat may polish off mice in a barn over several nights.","zh":"貓可能在幾個晚上內消滅穀倉中的老鼠。"},{"en":"Ants polish off pests because they hunt and bite other insects.","zh":"螞蟻會消滅害蟲，因為牠們會捕食和咬其他昆蟲。"},{"en":"This phrase is informal and suggests effective removal.","zh":"這個短語較口語，暗示有效清除。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":3},{"front":"orange groves","meaning":"橙園","examples":[{"en":"The ants protected the orange groves of southern China.","zh":"螞蟻保護了中國南方的橙園。"},{"en":"Orange groves are groups of orange trees grown together.","zh":"orange groves 指成片種植的橙樹。"},{"en":"A family may own orange groves that produce fruit every winter.","zh":"一個家庭可能擁有每年冬天結果的橙園。"},{"en":"Pests in orange groves can damage leaves, flowers, and fruit.","zh":"橙園中的害蟲可以傷害葉、花和果實。"},{"en":"This phrase is used when talking about orange farming areas.","zh":"這個短語用於談論橙樹種植區。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":3},{"front":"for at least 1,700 years","meaning":"至少一千七百年","examples":[{"en":"The ants have been used for at least 1,700 years.","zh":"這些螞蟻已被使用至少一千七百年。"},{"en":"For at least 1,700 years means for no less than 1,700 years.","zh":"for at least 1,700 years 指不少於一千七百年。"},{"en":"Some traditions have lasted for at least several hundred years.","zh":"有些傳統已延續至少數百年。"},{"en":"If a method survives for 1,700 years, people probably found it useful.","zh":"如果一種方法延續一千七百年，人們很可能認為它有用。"},{"en":"This phrase stresses a very long period of use.","zh":"這個短語強調非常長的使用時間。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":3},{"front":"weaver ant","meaning":"織葉蟻","examples":[{"en":"The yellow citrus ant is a type of weaver ant.","zh":"黃柑橘蟻是一種織葉蟻。"},{"en":"A weaver ant is an ant that builds nests by joining leaves together.","zh":"weaver ant 是一種透過把葉子連在一起築巢的螞蟻。"},{"en":"Weaver ants may use silk from larvae to hold leaves in place.","zh":"織葉蟻可能使用幼蟲吐出的絲固定葉子。"},{"en":"Their nest-building behaviour makes them different from many other ants.","zh":"牠們的築巢行為令牠們有別於許多其他螞蟻。"},{"en":"This phrase describes both the insect and its special building method.","zh":"這個短語同時描述昆蟲及其特殊築巢方法。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":3},{"front":"binds leaves and twigs with silk","meaning":"用絲把葉和小枝綁起來","examples":[{"en":"The weaver ant binds leaves and twigs with silk.","zh":"織葉蟻用絲把葉和小枝綁起來。"},{"en":"To bind leaves and twigs with silk means to tie plant parts together using silk threads.","zh":"bind leaves and twigs with silk 指用絲線把植物部分綁在一起。"},{"en":"A child may bind sticks with string to make a small model shelter.","zh":"孩子可能用繩把小木枝綁起來，製作小模型庇護所。"},{"en":"Weaver ants bind leaves together so they can create protected nests.","zh":"織葉蟻把葉子綁在一起，好建立受保護的巢。"},{"en":"This phrase shows how the ants build rather than simply dig.","zh":"這個短語顯示螞蟻是建造巢穴，而不只是挖洞。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":3},{"front":"twigs","meaning":"小枝","examples":[{"en":"The ants bind leaves and twigs to make nests.","zh":"螞蟻把葉和小枝綁起來築巢。"},{"en":"Twigs are small thin branches from a tree or bush.","zh":"twigs 指樹或灌木上的細小枝條。"},{"en":"Children may collect twigs to build a small fire under adult supervision.","zh":"孩子可能在成人監督下收集小枝來生小火。"},{"en":"Birds and insects use twigs because they are light and easy to move.","zh":"鳥和昆蟲使用小枝，因為它們輕而容易移動。"},{"en":"This word refers to small branches, not large logs.","zh":"這個字指細小枝條，而不是大木頭。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":3},{"front":"a neat, tent-like nest","meaning":"整齊、帳篷狀的巢","examples":[{"en":"The ants form a neat, tent-like nest.","zh":"螞蟻形成一個整齊、帳篷狀的巢。"},{"en":"A neat, tent-like nest is a tidy shelter shaped like a small tent.","zh":"neat, tent-like nest 指整齊、形狀像小帳篷的庇護巢。"},{"en":"Children may make a neat, tent-like shelter with sheets and chairs.","zh":"孩子可能用床單和椅子做一個整齊、帳篷狀的小屋。"},{"en":"The tent-like shape protects the ants inside the leaves.","zh":"帳篷狀形態可以保護葉子內的螞蟻。"},{"en":"This phrase helps readers picture the nest clearly.","zh":"這個短語幫助讀者清楚想像巢的外形。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":3},{"front":"in the beginning","meaning":"起初","examples":[{"en":"In the beginning, farmers used the occasional ant nest.","zh":"起初，農民只是偶爾使用蟻巢。"},{"en":"In the beginning means at the start of a process or story.","zh":"in the beginning 指在一個過程或故事開始時。"},{"en":"In the beginning, a new student may feel shy and confused.","zh":"起初，新學生可能感到害羞和困惑。"},{"en":"Early methods are often simple before people improve them.","zh":"早期方法通常很簡單，之後人們才改進它們。"},{"en":"This phrase marks the first stage before later development.","zh":"這個短語標示後來發展之前的第一階段。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":3},{"front":"made do with","meaning":"勉強湊合使用","examples":[{"en":"Farmers made do with the occasional ant nest here and there.","zh":"農民勉強湊合使用零星的蟻巢。"},{"en":"To make do with something means to manage with something limited or imperfect.","zh":"make do with something 指用有限或不完美的東西勉強應付。"},{"en":"A family may make do with one old laptop until they can buy another.","zh":"一個家庭可能先勉強使用一部舊手提電腦，直到能買另一部。"},{"en":"People make do when better resources are not available.","zh":"當沒有更好資源時，人們會勉強湊合。"},{"en":"This phrase suggests accepting a practical but not ideal solution.","zh":"這個短語暗示接受實用但不理想的解決方法。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":4},{"front":"here and there","meaning":"零星地；到處一點點","examples":[{"en":"Farmers used ant nests here and there.","zh":"農民零星地使用蟻巢。"},{"en":"Here and there means in several scattered places.","zh":"here and there 指在幾個分散地方。"},{"en":"A student may leave books here and there around the house.","zh":"學生可能把書到處一點點地放在家中。"},{"en":"If nests appear here and there, they are not yet organised into a system.","zh":"如果巢穴零星出現，它們還未形成有組織的系統。"},{"en":"This phrase suggests something is spread unevenly.","zh":"這個短語暗示某物分布不均。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":4},{"front":"it wasn’t long before","meaning":"不久之後就……","examples":[{"en":"It wasn’t long before demand led to a thriving trade.","zh":"不久之後，需求就帶來了興旺買賣。"},{"en":"It wasn’t long before means something happened soon afterwards.","zh":"it wasn’t long before 指某事不久後就發生。"},{"en":"It wasn’t long before the new café became popular with students.","zh":"不久之後，新咖啡店就受到學生歡迎。"},{"en":"Strong demand can quickly turn a small practice into a business.","zh":"強烈需求可以很快把小做法變成生意。"},{"en":"This phrase shows that the next development happened quite soon.","zh":"這個短語顯示下一個發展很快出現。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":4},{"front":"growing demand","meaning":"不斷增加的需求","examples":[{"en":"Growing demand led to a thriving trade in ant nests.","zh":"不斷增加的需求帶來了興旺的蟻巢買賣。"},{"en":"Growing demand means more and more people want something.","zh":"growing demand 指越來越多人想要某物。"},{"en":"Growing demand for online lessons can make tutors busier.","zh":"對網課不斷增加的需求可能令補習老師更忙。"},{"en":"When demand grows, prices and supply may also change.","zh":"當需求增加，價格和供應也可能改變。"},{"en":"This phrase is often used in business and market contexts.","zh":"這個短語常用於商業和市場語境。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":4},{"front":"led to the development of","meaning":"導致……的發展","examples":[{"en":"Growing demand led to the development of ant farming.","zh":"不斷增加的需求導致螞蟻養殖的發展。"},{"en":"Led to the development of something means caused something new to grow or appear.","zh":"led to the development of something 指導致某種新事物成長或出現。"},{"en":"Better phones led to the development of mobile payment.","zh":"更好的手機導致流動支付的發展。"},{"en":"Need and demand often lead to the development of new industries.","zh":"需要和需求常導致新行業的發展。"},{"en":"This phrase explains how one change creates another.","zh":"這個短語解釋一個變化如何創造另一個變化。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":4},{"front":"a thriving trade in","meaning":"……的興旺買賣","examples":[{"en":"A thriving trade in ant nests developed in southern China.","zh":"中國南方發展出興旺的蟻巢買賣。"},{"en":"A thriving trade in something is a busy and successful business buying and selling it.","zh":"a thriving trade in something 指買賣某物的繁忙而成功的生意。"},{"en":"A tourist town may have a thriving trade in handmade souvenirs.","zh":"旅遊城鎮可能有興旺的手工紀念品買賣。"},{"en":"A thriving trade grows when many people want the same product.","zh":"當許多人想要同一產品，興旺買賣就會發展。"},{"en":"This phrase suggests strong demand and active selling.","zh":"這個短語暗示強烈需求和活躍銷售。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":4},{"front":"ant farming","meaning":"螞蟻養殖","examples":[{"en":"A new type of agriculture, ant farming, developed.","zh":"一種新的農業形式——螞蟻養殖——發展起來。"},{"en":"Ant farming means raising or managing ants for a practical purpose.","zh":"ant farming 指為實際目的飼養或管理螞蟻。"},{"en":"Farmers may practise ant farming if ants protect valuable crops.","zh":"如果螞蟻能保護有價值的農作物，農民可能進行螞蟻養殖。"},{"en":"Ant farming developed because natural nests alone could not meet demand.","zh":"螞蟻養殖之所以發展，是因為單靠天然蟻巢無法滿足需求。"},{"en":"This phrase shows that insects can become part of agriculture.","zh":"這個短語顯示昆蟲也可以成為農業的一部分。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":4},{"front":"for an insect that bites","meaning":"對於一種會咬人的昆蟲來說","examples":[{"en":"For an insect that bites, the yellow citrus ant is remarkably popular.","zh":"對於一種會咬人的昆蟲來說，黃柑橘蟻異常受歡迎。"},{"en":"For an insect that bites means considering that the insect can hurt people.","zh":"for an insect that bites 指考慮到該昆蟲會傷害人。"},{"en":"For a dog that barks loudly, it is surprisingly gentle with children.","zh":"對一隻大聲吠叫的狗來說，牠對孩子卻出奇溫柔。"},{"en":"This structure introduces a surprising contrast.","zh":"這個結構引出令人意外的對比。"},{"en":"Here, the surprise is that farmers liked an insect that could bite them.","zh":"在這裡，令人意外之處是農民喜歡一種會咬人的昆蟲。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":4},{"front":"remarkably popular","meaning":"異常受歡迎","examples":[{"en":"The yellow citrus ant is remarkably popular with orange growers.","zh":"黃柑橘蟻在橙農之間異常受歡迎。"},{"en":"Remarkably popular means surprisingly or unusually well liked.","zh":"remarkably popular 指出奇地或異常地受喜愛。"},{"en":"A simple school app may become remarkably popular if it saves teachers time.","zh":"如果一個簡單學校應用程式能節省老師時間，它可能異常受歡迎。"},{"en":"Something painful or difficult can still be popular if it is very useful.","zh":"某物即使痛苦或困難，若非常有用，仍可能受歡迎。"},{"en":"This phrase highlights popularity that is unexpected.","zh":"這個短語突出意想不到的受歡迎程度。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":4},{"front":"even by ant standards","meaning":"即使以螞蟻標準來說","examples":[{"en":"Even by ant standards, Oecophylla smaragdina is a fearsome predator.","zh":"即使以螞蟻標準來說，黃猄蟻也是可怕的捕食者。"},{"en":"Even by ant standards means surprising even when compared with other ants.","zh":"even by ant standards 指即使與其他螞蟻比較也令人驚訝。"},{"en":"Even by city standards, the traffic near the stadium is terrible.","zh":"即使以城市標準來說，體育場附近的交通也很糟。"},{"en":"This phrase shows that something is extreme within its own group.","zh":"這個短語顯示某物在自己群體內也很極端。"},{"en":"It suggests the ant is especially fierce, even among ants.","zh":"它暗示這種螞蟻即使在螞蟻中也特別兇猛。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":4},{"front":"fearsome predator","meaning":"可怕的捕食者","examples":[{"en":"The yellow citrus ant is a fearsome predator.","zh":"黃柑橘蟻是一種可怕的捕食者。"},{"en":"A fearsome predator is an animal that hunts powerfully and frightens prey.","zh":"fearsome predator 指強力捕獵並令獵物害怕的動物。"},{"en":"A hawk can be a fearsome predator for small birds.","zh":"鷹對小鳥來說可以是可怕的捕食者。"},{"en":"Fearsome predators help control prey populations in nature.","zh":"可怕的捕食者有助控制自然界中獵物的數量。"},{"en":"This phrase stresses danger, hunting ability, and power.","zh":"這個短語強調危險、捕獵能力和力量。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":5},{"front":"powerful nip","meaning":"強而有力的一咬","examples":[{"en":"The ant has a powerful nip.","zh":"這種螞蟻有強而有力的一咬。"},{"en":"A powerful nip is a strong bite or pinch.","zh":"powerful nip 指強烈的一咬或一夾。"},{"en":"A crab can give a powerful nip if someone touches its claw.","zh":"如果有人碰到蟹鉗，螃蟹可能強而有力地夾一下。"},{"en":"A powerful nip hurts because the jaws or pincers close firmly.","zh":"強而有力的一咬會痛，因為顎或鉗子會緊緊合上。"},{"en":"This phrase is informal and often describes a small animal’s bite.","zh":"這個短語較口語，常描述小動物的咬擊。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":5},{"front":"painful to humans","meaning":"對人類來說很痛","examples":[{"en":"The ant’s bite is painful to humans.","zh":"這種螞蟻的咬傷對人類來說很痛。"},{"en":"Painful to humans means causing pain when people experience it.","zh":"painful to humans 指人類經歷時會感到疼痛。"},{"en":"A bee sting can be painful to humans, especially on sensitive skin.","zh":"蜜蜂螫傷對人類來說可能很痛，尤其是在敏感皮膚上。"},{"en":"Farmers may tolerate a painful bite if the insect protects crops.","zh":"如果昆蟲能保護農作物，農民可能忍受疼痛的咬傷。"},{"en":"This phrase describes how something affects people physically.","zh":"這個短語描述某物對人體的影響。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":5},{"front":"lethal to","meaning":"對……致命","examples":[{"en":"The ant’s bite is lethal to many insect pests.","zh":"這種螞蟻的咬傷對許多害蟲是致命的。"},{"en":"Lethal to something means able to kill it.","zh":"lethal to something 指能殺死某物。"},{"en":"Some cleaning chemicals are lethal to insects but dangerous to children too.","zh":"有些清潔化學品對昆蟲致命，但對孩子也危險。"},{"en":"A predator is useful in farming if it is lethal to harmful pests.","zh":"如果捕食者對有害害蟲致命，它在農業中就有用。"},{"en":"This phrase describes something that can cause death.","zh":"這個短語描述能導致死亡的東西。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":5},{"front":"insects that plague","meaning":"困擾……的昆蟲","examples":[{"en":"The ants kill insects that plague the orange groves.","zh":"螞蟻殺死困擾橙園的昆蟲。"},{"en":"Insects that plague a place are insects that trouble it repeatedly or seriously.","zh":"insects that plague a place 指反覆或嚴重困擾某地的昆蟲。"},{"en":"Mosquitoes that plague a village can make outdoor life unpleasant.","zh":"困擾村莊的蚊子可以令戶外生活很不舒服。"},{"en":"If insects plague orchards, fruit quality may fall.","zh":"如果昆蟲困擾果園，水果質素可能下降。"},{"en":"This phrase suggests repeated annoyance or damage.","zh":"這個短語暗示反覆的煩擾或破壞。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":5},{"front":"Guangdong and Guangxi","meaning":"廣東和廣西","examples":[{"en":"The ants protect orange groves in Guangdong and Guangxi.","zh":"螞蟻保護廣東和廣西的橙園。"},{"en":"Guangdong and Guangxi are regions in southern China.","zh":"Guangdong and Guangxi 指中國南方的地區。"},{"en":"Many citrus-growing areas in Guangdong and Guangxi have warm climates.","zh":"廣東和廣西的許多柑橘種植區氣候溫暖。"},{"en":"A method used in Guangdong and Guangxi may suit southern farming conditions.","zh":"在廣東和廣西使用的方法，可能適合南方農業環境。"},{"en":"This phrase names the geographical setting of the farming practice.","zh":"這個短語指出該農業做法的地理背景。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":5},{"front":"harnessed","meaning":"利用；駕馭","examples":[{"en":"Chinese orange growers have harnessed these ants for centuries.","zh":"中國橙農幾百年來一直利用這些螞蟻。"},{"en":"To harness something means to use its power for a practical purpose.","zh":"harness something 指利用某物的力量達成實際目的。"},{"en":"A city can harness sunlight by installing solar panels on public buildings.","zh":"城市可以透過在公共建築安裝太陽能板來利用陽光。"},{"en":"Farmers harness ants when they use their hunting behaviour to protect crops.","zh":"農民利用螞蟻的捕食行為來保護農作物。"},{"en":"This word suggests controlling natural power rather than wasting it.","zh":"這個字暗示駕馭自然力量，而不是浪費它。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":5},{"front":"six-legged killing machines","meaning":"六腳殺蟲機器","examples":[{"en":"Orange growers used these six-legged killing machines to protect crops.","zh":"橙農使用這些六腳殺蟲機器來保護農作物。"},{"en":"Six-legged killing machines is a vivid nickname for insects that kill pests effectively.","zh":"six-legged killing machines 是對有效殺死害蟲的昆蟲的生動稱呼。"},{"en":"A writer might call ladybirds tiny pest-control machines in a garden.","zh":"作者可能把瓢蟲稱為花園中的小型害蟲控制機器。"},{"en":"The phrase makes ants sound powerful despite their small size.","zh":"這個短語令螞蟻雖小卻聽起來很強大。"},{"en":"It is not literal machinery; it is a colourful metaphor.","zh":"它不是字面上的機器，而是一個生動比喻。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":5},{"front":"keep their fruit groves healthy and productive","meaning":"使果園保持健康且高產","examples":[{"en":"The ants kept the fruit groves healthy and productive.","zh":"螞蟻使果園保持健康且高產。"},{"en":"To keep fruit groves healthy and productive means to help trees stay strong and bear good crops.","zh":"keep fruit groves healthy and productive 指幫助果樹保持強壯並結出好收成。"},{"en":"Careful watering can keep a small garden healthy and productive.","zh":"小心澆水可以使小花園保持健康且高產。"},{"en":"Pest control keeps orchards productive by preventing leaf and fruit damage.","zh":"害蟲防治透過防止葉和果實受損，使果園保持高產。"},{"en":"This phrase connects plant health with harvest results.","zh":"這個短語把植物健康與收成結果連起來。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":5},{"front":"evolved in","meaning":"在……演化","examples":[{"en":"Citrus fruits evolved in the Far East.","zh":"柑橘類水果在遠東演化。"},{"en":"Evolved in a place means developed naturally there over a long time.","zh":"evolved in a place 指在某地經長時間自然發展。"},{"en":"Some plants evolved in dry areas and can survive with little water.","zh":"有些植物在乾旱地區演化，因此能以少量水存活。"},{"en":"When a crop evolved in a region, local pests may also be diverse there.","zh":"當一種作物在某地演化，當地害蟲也可能很多樣。"},{"en":"This phrase is used for natural development over generations.","zh":"這個短語用於描述跨世代的自然發展。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":5},{"front":"the Far East","meaning":"遠東","examples":[{"en":"Citrus fruits evolved in the Far East.","zh":"柑橘類水果在遠東演化。"},{"en":"The Far East usually refers to East and Southeast Asia from a Western viewpoint.","zh":"the Far East 通常從西方角度指東亞和東南亞。"},{"en":"Many foods, plants, and traditions from the Far East reached Europe through trade.","zh":"許多來自遠東的食物、植物和傳統透過貿易傳到歐洲。"},{"en":"The phrase is historical and should be used carefully in modern writing.","zh":"這個短語帶歷史色彩，在現代寫作中應小心使用。"},{"en":"In this passage, it refers to the Asian origin of citrus fruits.","zh":"在這篇文章中，它指柑橘類水果的亞洲起源。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":6},{"front":"discovered the delights of","meaning":"發現……的美味","examples":[{"en":"The Chinese discovered the delights of citrus flesh early on.","zh":"中國人很早就發現柑橘果肉的美味。"},{"en":"To discover the delights of something means to find that it is enjoyable or pleasing.","zh":"discover the delights of something 指發現某物令人愉快或有吸引力。"},{"en":"A child may discover the delights of reading after finding the right book.","zh":"孩子找到合適的書後，可能發現閱讀的樂趣。"},{"en":"People keep using something when they discover its pleasures or benefits.","zh":"當人們發現某物的樂趣或好處，就會繼續使用它。"},{"en":"This phrase sounds positive and slightly literary.","zh":"這個短語語氣正面，略帶文學色彩。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":6},{"front":"flesh","meaning":"果肉","examples":[{"en":"The Chinese enjoyed the flesh of citrus fruits.","zh":"中國人喜愛柑橘類水果的果肉。"},{"en":"Flesh means the soft edible part inside a fruit.","zh":"flesh 指水果內部柔軟可食用的部分。"},{"en":"The flesh of a mango is sweet, soft, and orange.","zh":"芒果的果肉香甜、柔軟而呈橙色。"},{"en":"Fruit flesh attracts people and animals because it contains juice and sugar.","zh":"果肉含有果汁和糖分，因此吸引人和動物。"},{"en":"In this context, flesh means fruit pulp, not animal meat.","zh":"在這個語境中，flesh 指果肉，而不是動物肉。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":6},{"front":"early on","meaning":"早早地","examples":[{"en":"The Chinese discovered citrus fruits early on.","zh":"中國人早早地發現了柑橘類水果。"},{"en":"Early on means near the beginning of a period or process.","zh":"early on 指在某段時期或過程接近開始的時候。"},{"en":"Students should ask questions early on before confusion becomes serious.","zh":"學生應早早提問，避免困惑變得嚴重。"},{"en":"If a problem is noticed early on, it is easier to fix.","zh":"如果問題早早被發現，就較容易修正。"},{"en":"This phrase focuses on something happening at an early stage.","zh":"這個短語集中於某事在早期階段發生。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":6},{"front":"ancestral home of","meaning":"……的原產地","examples":[{"en":"China is the ancestral home of oranges, lemons and pomelos.","zh":"中國是橙、檸檬和柚子的原產地。"},{"en":"The ancestral home of something is the place where it originally came from.","zh":"ancestral home of something 指某物最初起源的地方。"},{"en":"A village may be the ancestral home of a family that later moved abroad.","zh":"一條村可能是一個後來移居海外家族的祖籍地。"},{"en":"Knowing a crop’s ancestral home helps scientists understand its pests and varieties.","zh":"了解作物的原產地，有助科學家理解其害蟲和品種。"},{"en":"This phrase connects origin with history.","zh":"這個短語把起源與歷史連起來。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":6},{"front":"pomelos","meaning":"柚子","examples":[{"en":"China is the ancestral home of oranges, lemons and pomelos.","zh":"中國是橙、檸檬和柚子的原產地。"},{"en":"Pomelos are large citrus fruits with thick skin and sweet or slightly bitter flesh.","zh":"pomelos 是大型柑橘類水果，外皮厚，果肉甜或略帶苦味。"},{"en":"Families may eat pomelos during festivals because they are easy to share.","zh":"家庭可能在節日吃柚子，因為它們容易分享。"},{"en":"Pomelos belong to the citrus family, like oranges and lemons.","zh":"柚子和橙、檸檬一樣屬於柑橘類。"},{"en":"This word names a specific fruit, not a general fruit category.","zh":"這個字指一種特定水果，而不是一般水果類別。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":6},{"front":"greatest diversity of","meaning":"最多樣化的……","examples":[{"en":"China has the greatest diversity of citrus pests.","zh":"中國有最多樣化的柑橘害蟲。"},{"en":"The greatest diversity of something means the widest variety of it.","zh":"greatest diversity of something 指某物種類最廣泛。"},{"en":"A large library may have the greatest diversity of children’s books in town.","zh":"大型圖書館可能擁有鎮上最多樣化的兒童書籍。"},{"en":"Diversity increases when many different types exist in one place.","zh":"當很多不同類型存在於同一地方，多樣性就會增加。"},{"en":"This phrase compares variety, not total number only.","zh":"這個短語比較的是種類多樣性，而不只是總數。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":6},{"front":"citrus pests","meaning":"柑橘害蟲","examples":[{"en":"China has a great diversity of citrus pests.","zh":"中國有很多種類的柑橘害蟲。"},{"en":"Citrus pests are insects or organisms that damage citrus trees and fruits.","zh":"citrus pests 指傷害柑橘樹和果實的昆蟲或生物。"},{"en":"Farmers check citrus trees for pests that eat leaves or suck sap.","zh":"農民會檢查柑橘樹上是否有吃葉或吸食樹液的害蟲。"},{"en":"Citrus pests can reduce fruit quality and harvest size.","zh":"柑橘害蟲可以降低水果質素和收成量。"},{"en":"This phrase is used in farming and plant protection.","zh":"這個短語用於農業和植物保護。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":6},{"front":"produce the sweetest fruits","meaning":"結出最甜的果實","examples":[{"en":"The trees produce the sweetest fruits, the mandarins.","zh":"這些樹結出最甜的果實，也就是柑橘。"},{"en":"To produce the sweetest fruits means to grow fruit with especially sweet flesh.","zh":"produce the sweetest fruits 指長出果肉特別甜的水果。"},{"en":"A well-watered tree may produce sweeter fruit than a neglected one.","zh":"澆水充足的樹可能比被忽視的樹結出更甜的果實。"},{"en":"Good soil and careful care can help trees produce better fruit.","zh":"良好泥土和細心照料可以幫助樹結出更好的果實。"},{"en":"This phrase links farming conditions with fruit quality.","zh":"這個短語把農業環境與水果質素連起來。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":6},{"front":"mandarins","meaning":"柑；橘","examples":[{"en":"Mandarins attract many plant-eating insects.","zh":"柑橘吸引許多食植物昆蟲。"},{"en":"Mandarins are small sweet citrus fruits with loose orange skin.","zh":"mandarins 是小型甜柑橘，橙色外皮較鬆，容易剝。"},{"en":"Families often buy mandarins because they are easy to peel and share.","zh":"家庭常買柑橘，因為它們容易剝皮和分享。"},{"en":"Sweet mandarins can attract insects as well as people.","zh":"甜美的柑橘可以吸引昆蟲，也吸引人。"},{"en":"This word refers to the fruit, not the language in this passage.","zh":"在這篇文章中，這個字指水果，而不是語言。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":6},{"front":"attract a host of","meaning":"吸引大量……","examples":[{"en":"Mandarin trees attract a host of plant-eating insects.","zh":"柑橘樹吸引大量食植物昆蟲。"},{"en":"To attract a host of something means to draw in a large number of them.","zh":"attract a host of something 指吸引大量某類東西。"},{"en":"A popular market can attract a host of tourists on weekends.","zh":"受歡迎的市場在週末可以吸引大量遊客。"},{"en":"Sweet fruit attracts many insects because it offers food.","zh":"甜水果會吸引許多昆蟲，因為它提供食物。"},{"en":"This phrase means “many”, often with a sense of variety.","zh":"這個短語意思是「大量」，常帶有種類多的感覺。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":7},{"front":"plant-eating insects","meaning":"食植物昆蟲","examples":[{"en":"Mandarin trees attract many plant-eating insects.","zh":"柑橘樹吸引許多食植物昆蟲。"},{"en":"Plant-eating insects are insects that feed on leaves, stems, sap, or fruit.","zh":"plant-eating insects 指吃葉、莖、樹液或果實的昆蟲。"},{"en":"Caterpillars are plant-eating insects when they chew leaves in a garden.","zh":"毛蟲在花園中咬葉時，就是食植物昆蟲。"},{"en":"Plant-eating insects can weaken crops if there are too many of them.","zh":"如果食植物昆蟲太多，會削弱農作物。"},{"en":"This phrase explains what the insects eat.","zh":"這個短語說明昆蟲吃甚麼。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":7},{"front":"sap-sucking mealy bugs","meaning":"吸食樹液的粉蚧","examples":[{"en":"Mandarin trees attract sap-sucking mealy bugs.","zh":"柑橘樹吸引吸食樹液的粉蚧。"},{"en":"Sap-sucking mealy bugs are small insects that feed on plant sap.","zh":"sap-sucking mealy bugs 是吸食植物樹液的小昆蟲。"},{"en":"A gardener may notice mealy bugs as white cottony spots on leaves.","zh":"園丁可能在葉上看到白色棉絮狀斑點，那就是粉蚧。"},{"en":"Sap-sucking pests weaken plants by taking away their fluids.","zh":"吸食樹液的害蟲會取走植物汁液，使植物變弱。"},{"en":"This phrase describes both the insect and its feeding method.","zh":"這個短語同時描述昆蟲及其進食方式。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":7},{"front":"leaf-devouring caterpillars","meaning":"吃葉的毛蟲","examples":[{"en":"The trees also attract leaf-devouring caterpillars.","zh":"這些樹也吸引吃葉的毛蟲。"},{"en":"Leaf-devouring caterpillars are caterpillars that eat large amounts of leaves.","zh":"leaf-devouring caterpillars 指大量吃葉的毛蟲。"},{"en":"A gardener may find leaf-devouring caterpillars after seeing holes in leaves.","zh":"園丁看到葉上有洞後，可能找到吃葉的毛蟲。"},{"en":"When caterpillars devour leaves, trees lose energy for growth and fruiting.","zh":"當毛蟲大量吃葉，樹木會失去生長和結果的能量。"},{"en":"This phrase makes the damage sound serious and active.","zh":"這個短語令傷害聽起來嚴重而主動。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":7},{"front":"with so many enemies","meaning":"面對這麼多敵人","examples":[{"en":"With so many enemies, growers needed protection for their orchards.","zh":"面對這麼多敵人，種植者需要保護果園。"},{"en":"With so many enemies means because there are many threats or attackers.","zh":"with so many enemies 指因為有許多威脅或攻擊者。"},{"en":"With so many deadlines, a student needs a clear study plan.","zh":"面對這麼多限期，學生需要清楚的學習計劃。"},{"en":"Many pests create pressure, so growers need strong protection.","zh":"許多害蟲造成壓力，所以種植者需要強力保護。"},{"en":"This phrase introduces the reason for needing help.","zh":"這個短語引出需要幫助的原因。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":7},{"front":"fruit growers","meaning":"果農","examples":[{"en":"Fruit growers needed a way to protect their orchards.","zh":"果農需要一種方法來保護果園。"},{"en":"Fruit growers are farmers who grow fruit trees or fruit crops.","zh":"fruit growers 指種植果樹或水果作物的農民。"},{"en":"Fruit growers may sell apples, oranges, grapes, or berries.","zh":"果農可能出售蘋果、橙、葡萄或莓果。"},{"en":"Fruit growers lose money when pests damage harvests.","zh":"當害蟲破壞收成時，果農會損失金錢。"},{"en":"This phrase identifies farmers by the crop they produce.","zh":"這個短語按作物類型識別農民。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":7},{"front":"protecting their orchards","meaning":"保護他們的果園","examples":[{"en":"Growers needed a way of protecting their orchards.","zh":"種植者需要一種保護他們果園的方法。"},{"en":"Protecting their orchards means keeping fruit-growing areas safe from harm.","zh":"protecting their orchards 指使水果種植區免受傷害。"},{"en":"Farmers protect orchards by controlling pests, watering trees, and pruning branches.","zh":"農民透過控制害蟲、澆水和修剪樹枝來保護果園。"},{"en":"Without protection, insects and disease can reduce fruit production.","zh":"如果沒有保護，昆蟲和疾病可以降低水果產量。"},{"en":"This phrase focuses on keeping fruit trees healthy and productive.","zh":"這個短語集中於保持果樹健康和高產。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":7},{"front":"secret weapon","meaning":"秘密武器","examples":[{"en":"The West did not discover the growers’ secret weapon until the 20th century.","zh":"西方直到二十世紀才發現種植者的秘密武器。"},{"en":"A secret weapon is a hidden method or advantage that gives someone success.","zh":"secret weapon 指使人成功的隱藏方法或優勢。"},{"en":"A student’s secret weapon may be a simple revision timetable.","zh":"學生的秘密武器可能是一份簡單的溫習時間表。"},{"en":"The ants were a secret weapon because they quietly protected the trees.","zh":"螞蟻是秘密武器，因為牠們默默保護樹木。"},{"en":"This phrase can be literal in war or figurative in daily life.","zh":"這個短語可以在戰爭中按字面使用，也可在日常生活中作比喻使用。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":7},{"front":"until the early 20th century","meaning":"直到二十世紀初","examples":[{"en":"The West discovered the Chinese method only in the early 20th century.","zh":"西方直到二十世紀初才發現中國的方法。"},{"en":"Until the early 20th century means not before the beginning of the 1900s.","zh":"until the early 20th century 指直到1900年代初期之前都沒有發生。"},{"en":"Some medical ideas were not widely accepted until the early 20th century.","zh":"有些醫學觀念直到二十世紀初才被廣泛接受。"},{"en":"A long delay can show that knowledge stayed local for many years.","zh":"長時間延遲可以顯示知識多年來只停留在本地。"},{"en":"This phrase gives a historical time boundary.","zh":"這個短語給出歷史時間界線。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":7},{"front":"was suffering an epidemic of","meaning":"正遭受……疫症","examples":[{"en":"Florida was suffering an epidemic of citrus canker.","zh":"佛羅里達正遭受柑橘潰瘍病疫症。"},{"en":"Was suffering an epidemic of something means was experiencing a serious widespread outbreak.","zh":"was suffering an epidemic of something 指正在經歷嚴重而廣泛的爆發。"},{"en":"A town may suffer an epidemic of flu during winter.","zh":"一個城鎮可能在冬季遭受流感疫症。"},{"en":"An epidemic damages many plants or people at the same time.","zh":"疫症會同時傷害許多植物或人。"},{"en":"This phrase shows that the problem was widespread and serious.","zh":"這個短語顯示問題廣泛而嚴重。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":7},{"front":"citrus canker","meaning":"柑橘潰瘍病","examples":[{"en":"Florida was suffering an epidemic of citrus canker.","zh":"佛羅里達正遭受柑橘潰瘍病疫症。"},{"en":"Citrus canker is a disease that damages citrus trees and fruit.","zh":"citrus canker 是一種傷害柑橘樹和果實的疾病。"},{"en":"Farmers may remove infected trees to stop citrus canker from spreading.","zh":"農民可能移除受感染的樹，以阻止柑橘潰瘍病擴散。"},{"en":"Citrus canker can harm harvests because it scars leaves and fruit.","zh":"柑橘潰瘍病會令葉和果實留下疤痕，因此傷害收成。"},{"en":"This phrase names a specific plant disease.","zh":"這個短語指一種特定植物疾病。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":8},{"front":"plant physiologist","meaning":"植物生理學家","examples":[{"en":"Walter Swingle was a plant physiologist.","zh":"Walter Swingle 是一名植物生理學家。"},{"en":"A plant physiologist is a scientist who studies how plants function.","zh":"plant physiologist 是研究植物如何運作的科學家。"},{"en":"A plant physiologist may study growth, disease resistance, or water use.","zh":"植物生理學家可能研究生長、抗病能力或水分使用。"},{"en":"Farmers can benefit from plant physiology because it explains plant health.","zh":"農民可以從植物生理學中受益，因為它解釋植物健康。"},{"en":"This phrase describes a scientific role, not a general gardener.","zh":"這個短語描述科學職位，而不是一般園丁。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":8},{"front":"US Department of Agriculture","meaning":"美國農業部","examples":[{"en":"Swingle worked for the US Department of Agriculture.","zh":"Swingle 任職於美國農業部。"},{"en":"The US Department of Agriculture is a government department dealing with farming and food.","zh":"US Department of Agriculture 是處理農業和食物事務的政府部門。"},{"en":"Researchers in the department may study crops, pests, and plant diseases.","zh":"該部門的研究者可能研究農作物、害蟲和植物疾病。"},{"en":"Government agricultural research can help farmers solve serious crop problems.","zh":"政府農業研究可以幫助農民解決嚴重作物問題。"},{"en":"This phrase names the official organisation behind Swingle’s work.","zh":"這個短語指出 Swingle 工作背後的官方機構。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":8},{"front":"was sent to China","meaning":"被派往中國","examples":[{"en":"Swingle was sent to China to search for resistant orange varieties.","zh":"Swingle 被派往中國尋找抗病橙品種。"},{"en":"Was sent to China means was officially asked or assigned to go to China.","zh":"was sent to China 指被正式要求或指派前往中國。"},{"en":"A doctor may be sent to another city to help during an emergency.","zh":"醫生可能在緊急情況中被派往另一個城市協助。"},{"en":"Swingle was sent because Florida needed a solution to citrus disease.","zh":"Swingle 被派出，是因為佛羅里達需要柑橘疾病的解決方法。"},{"en":"This phrase often shows duty, mission, or official assignment.","zh":"這個短語常表示職責、任務或官方指派。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":8},{"front":"in search of","meaning":"尋找……","examples":[{"en":"Swingle travelled to China in search of disease-resistant oranges.","zh":"Swingle 前往中國尋找抗病橙。"},{"en":"In search of means looking for something.","zh":"in search of 指尋找某物。"},{"en":"A family may visit several flats in search of a safer home.","zh":"一個家庭可能看幾個單位，以尋找更安全的家。"},{"en":"Researchers travel in search of answers when local information is not enough.","zh":"當本地資訊不足時，研究者會出行尋找答案。"},{"en":"This phrase gives the purpose of a journey or effort.","zh":"這個短語交代旅程或努力的目的。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":8},{"front":"varieties of orange","meaning":"橙的品種","examples":[{"en":"He searched for varieties of orange that resisted disease.","zh":"他尋找能抵抗疾病的橙品種。"},{"en":"Varieties of orange are different types of orange.","zh":"varieties of orange 指不同種類的橙。"},{"en":"A fruit shop may sell several varieties of orange with different sweetness levels.","zh":"水果店可能出售幾種甜度不同的橙品種。"},{"en":"Some varieties resist disease better than others because of genetic differences.","zh":"有些品種因基因差異，比其他品種更能抗病。"},{"en":"This phrase is useful when comparing types within one crop.","zh":"這個短語適合用於比較同一作物中的不同類型。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":8},{"front":"resistant to the disease","meaning":"對該病有抵抗力","examples":[{"en":"Swingle looked for orange varieties resistant to the disease.","zh":"Swingle 尋找對該病有抵抗力的橙品種。"},{"en":"Resistant to the disease means able to avoid or fight that disease well.","zh":"resistant to the disease 指能有效避免或抵抗該疾病。"},{"en":"Some plants are resistant to disease because their leaves are thicker.","zh":"有些植物因葉子較厚而對疾病有抵抗力。"},{"en":"Disease-resistant crops help farmers reduce losses.","zh":"抗病作物幫助農民減少損失。"},{"en":"This phrase describes natural or bred protection against illness.","zh":"這個短語描述對疾病的天然或育種保護。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":8},{"front":"spent some time studying","meaning":"花了一段時間研究","examples":[{"en":"Swingle spent some time studying citrus orchards around Guangzhou.","zh":"Swingle 花了一段時間研究廣州一帶的柑橘果園。"},{"en":"Spent some time studying means used a period of time to examine or learn about something.","zh":"spent some time studying 指用一段時間檢查或了解某事。"},{"en":"A student may spend time studying old exam papers before a test.","zh":"學生可能在測驗前花時間研究舊試卷。"},{"en":"Researchers study a place carefully before drawing conclusions.","zh":"研究者在下結論前會仔細研究一個地方。"},{"en":"This phrase suggests focused observation, not a quick glance.","zh":"這個短語暗示專注觀察，而不是快速看一眼。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":8},{"front":"citrus orchards","meaning":"柑橘果園","examples":[{"en":"Swingle studied the citrus orchards around Guangzhou.","zh":"Swingle 研究了廣州一帶的柑橘果園。"},{"en":"Citrus orchards are farms or gardens where citrus trees are grown.","zh":"citrus orchards 是種植柑橘樹的農場或果園。"},{"en":"Citrus orchards may contain oranges, lemons, mandarins, or pomelos.","zh":"柑橘果園可能種有橙、檸檬、柑或柚子。"},{"en":"Orchards need protection because pests and disease can damage the fruit.","zh":"果園需要保護，因為害蟲和疾病會傷害水果。"},{"en":"This phrase refers to cultivated fruit-growing areas.","zh":"這個短語指經人工栽培的水果種植區。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":8},{"front":"came across","meaning":"偶然發現","examples":[{"en":"Swingle came across the story of the cultivated ant.","zh":"Swingle 偶然發現了被人工培養的螞蟻的故事。"},{"en":"To come across something means to find it by chance.","zh":"come across something 指偶然找到某事物。"},{"en":"A student may come across a useful article while searching online.","zh":"學生可能在網上搜尋時偶然發現一篇有用文章。"},{"en":"Chance discoveries can lead researchers in a new direction.","zh":"偶然發現可以把研究者帶向新方向。"},{"en":"This phrase suggests accidental discovery, not planned searching.","zh":"這個短語暗示意外發現，而不是有計劃尋找。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":8},{"front":"cultivated ant","meaning":"被人工培養的螞蟻","examples":[{"en":"Swingle heard the story of the cultivated ant.","zh":"Swingle 聽到被人工培養的螞蟻的故事。"},{"en":"A cultivated ant is an ant raised or managed by people for use.","zh":"cultivated ant 指由人飼養或管理以供使用的螞蟻。"},{"en":"Farmers cultivate helpful insects when they encourage them to live near crops.","zh":"當農民鼓勵有益昆蟲住在作物附近時，就是在培養牠們。"},{"en":"The cultivated ant was valuable because it protected fruit trees.","zh":"被人工培養的螞蟻有價值，因為牠保護果樹。"},{"en":"This phrase shows that the ant was treated almost like a farm resource.","zh":"這個短語顯示螞蟻幾乎被當成農業資源。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":9},{"front":"by the nestful","meaning":"以一巢一巢的方式","examples":[{"en":"The ants were sold to orange growers by the nestful.","zh":"螞蟻以一巢一巢的方式賣給橙農。"},{"en":"By the nestful means in whole nests or nest-sized amounts.","zh":"by the nestful 指以整個巢或一巢的數量計算。"},{"en":"A shop may sell flowers by the bunch rather than one by one.","zh":"商店可能以一束一束的方式賣花，而不是逐枝賣。"},{"en":"Selling ants by the nestful made it easier for farmers to start colonies.","zh":"以一巢一巢方式出售螞蟻，令農民更容易建立群落。"},{"en":"This phrase describes the unit used for selling.","zh":"這個短語描述出售時使用的單位。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":9},{"front":"earliest report of","meaning":"最早關於……的記載","examples":[{"en":"The earliest report of citrus ants appeared in AD 304.","zh":"最早關於柑橘蟻的記載出現在公元304年。"},{"en":"The earliest report of something is the first known written mention of it.","zh":"earliest report of something 指目前已知最早的書面提及。"},{"en":"The earliest report of a disease can help historians trace its spread.","zh":"最早關於一種疾病的記載可以幫助歷史學家追蹤其傳播。"},{"en":"Early reports matter because they show how old an idea or practice is.","zh":"早期記載很重要，因為它們顯示某想法或做法有多古老。"},{"en":"This phrase is common in historical discussion.","zh":"這個短語常見於歷史討論。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":9},{"front":"citrus ants","meaning":"柑橘蟻","examples":[{"en":"The earliest report of citrus ants appeared in a book on botany.","zh":"最早關於柑橘蟻的記載出現在一本植物學書中。"},{"en":"Citrus ants are ants used or found around citrus trees.","zh":"citrus ants 指用於或出現在柑橘樹附近的螞蟻。"},{"en":"Farmers valued citrus ants because they attacked insects on fruit trees.","zh":"農民重視柑橘蟻，因為牠們攻擊果樹上的昆蟲。"},{"en":"Citrus ants became important when growers realised they could protect mandarins.","zh":"當種植者發現柑橘蟻可以保護柑橘時，牠們變得重要。"},{"en":"This phrase links the insects directly with citrus farming.","zh":"這個短語把昆蟲直接與柑橘種植連起來。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":9},{"front":"at work among","meaning":"在……中發揮作用","examples":[{"en":"The report described citrus ants at work among orange trees.","zh":"該記載描述柑橘蟻在橙樹中發揮作用。"},{"en":"At work among something means actively doing their job within that place or group.","zh":"at work among something 指在某地方或群體中積極工作或發揮功能。"},{"en":"Volunteers were at work among the crowd, helping lost visitors.","zh":"義工在人群中發揮作用，幫助迷路的訪客。"},{"en":"Ants at work among trees hunt pests and build nests.","zh":"螞蟻在樹中發揮作用，捕食害蟲並築巢。"},{"en":"This phrase shows activity happening inside a larger setting.","zh":"這個短語顯示活動在較大環境中發生。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":9},{"front":"tropical and subtropical botany","meaning":"熱帶及亞熱帶植物學","examples":[{"en":"The report appeared in a book on tropical and subtropical botany.","zh":"該記載出現在一本關於熱帶及亞熱帶植物學的書中。"},{"en":"Tropical and subtropical botany is the study of plants from warm climate regions.","zh":"tropical and subtropical botany 指研究溫暖氣候地區植物的學科。"},{"en":"A scientist studying mangoes may read books on tropical botany.","zh":"研究芒果的科學家可能閱讀熱帶植物學書籍。"},{"en":"Warm regions often have many plant species and pests.","zh":"溫暖地區通常有許多植物物種和害蟲。"},{"en":"This phrase identifies the scientific subject of the book.","zh":"這個短語指出該書的科學主題。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":9},{"front":"written by","meaning":"由……撰寫","examples":[{"en":"The book was written by Hsi Han in AD 304.","zh":"這本書由 Hsi Han 於公元304年撰寫。"},{"en":"Written by someone means that person authored the text.","zh":"written by someone 指該人創作了該文本。"},{"en":"A poem written by a student may still feel powerful.","zh":"由學生撰寫的詩仍可能很有力量。"},{"en":"Knowing who a text was written by helps readers judge its background.","zh":"知道文本由誰撰寫，有助讀者判斷其背景。"},{"en":"This phrase identifies authorship.","zh":"這個短語指出作者身份。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":9},{"front":"AD 304","meaning":"公元304年","examples":[{"en":"The earliest report appeared in AD 304.","zh":"最早的記載出現在公元304年。"},{"en":"AD 304 means the year 304 in the Common Era calendar.","zh":"AD 304 指公曆紀年中的304年。"},{"en":"A historical text dated AD 304 is over 1,700 years old.","zh":"標示為公元304年的歷史文本已有超過一千七百年歷史。"},{"en":"Exact dates help readers understand how ancient a practice is.","zh":"精確日期幫助讀者理解一種做法有多古老。"},{"en":"This phrase gives a precise historical date.","zh":"這個短語給出精確歷史日期。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":9},{"front":"sell in their markets","meaning":"在市場出售","examples":[{"en":"The people sold ants in their markets.","zh":"人們在市場出售螞蟻。"},{"en":"To sell something in their markets means to offer it for sale in local trading places.","zh":"sell something in their markets 指在本地交易場所出售某物。"},{"en":"Farmers may sell fruit in local markets every morning.","zh":"農民可能每天早上在本地市場出售水果。"},{"en":"If ants were sold in markets, they had become a useful commodity.","zh":"如果螞蟻在市場出售，就表示牠們已成為有用商品。"},{"en":"This phrase shows that ant use had become part of trade.","zh":"這個短語顯示螞蟻使用已成為貿易的一部分。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":9},{"front":"bags of rush matting","meaning":"燈芯草席袋","examples":[{"en":"The ants were sold in bags of rush matting.","zh":"螞蟻被裝在燈芯草席袋中出售。"},{"en":"Bags of rush matting are bags made from woven rush plants.","zh":"bags of rush matting 指用燈芯草編織材料製成的袋。"},{"en":"Before plastic bags, people often used woven plant materials for carrying goods.","zh":"在膠袋出現前，人們常用編織植物材料攜帶貨物。"},{"en":"Rush matting bags could hold ant nests while allowing some air to pass.","zh":"燈芯草席袋可以裝蟻巢，同時讓一些空氣通過。"},{"en":"This phrase describes the traditional packaging used for ants.","zh":"這個短語描述出售螞蟻時使用的傳統包裝。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":9},{"front":"attached to","meaning":"附在……上","examples":[{"en":"The bags were attached to twigs and leaves.","zh":"這些袋附在小枝和葉上。"},{"en":"Attached to something means fixed or connected to it.","zh":"attached to something 指固定或連接在某物上。"},{"en":"A name tag may be attached to a school bag.","zh":"名牌可能附在書包上。"},{"en":"If a bag of ants is attached to a branch, ants can move into the tree.","zh":"如果一袋螞蟻附在樹枝上，螞蟻就能移入樹中。"},{"en":"This phrase describes physical connection.","zh":"這個短語描述實際連接。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":10},{"front":"reddish-yellow in colour","meaning":"顏色呈紅黃色","examples":[{"en":"The ants were reddish-yellow in colour.","zh":"這些螞蟻顏色呈紅黃色。"},{"en":"Reddish-yellow in colour means having a colour between red and yellow.","zh":"reddish-yellow in colour 指顏色介乎紅色和黃色之間。"},{"en":"Autumn leaves may become reddish-yellow before falling.","zh":"秋葉掉落前可能變成紅黃色。"},{"en":"Colour descriptions help people identify insects or plants more easily.","zh":"顏色描述幫助人們更容易識別昆蟲或植物。"},{"en":"This phrase gives a visual detail.","zh":"這個短語提供視覺細節。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":10},{"front":"ordinary ants","meaning":"普通螞蟻","examples":[{"en":"The citrus ants were bigger than ordinary ants.","zh":"柑橘蟻比普通螞蟻更大。"},{"en":"Ordinary ants are common ants, not special or unusual types.","zh":"ordinary ants 指常見螞蟻，而不是特殊或不尋常類型。"},{"en":"Children may see ordinary ants walking along a pavement after rain.","zh":"孩子可能在雨後看見普通螞蟻沿著行人路走。"},{"en":"Comparing citrus ants with ordinary ants shows why they seemed remarkable.","zh":"把柑橘蟻與普通螞蟻比較，顯示牠們為何顯得特別。"},{"en":"This phrase means normal examples of the same insect group.","zh":"這個短語指同一昆蟲類別中的一般例子。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":10},{"front":"harmful insects","meaning":"有害昆蟲","examples":[{"en":"The fruits would be damaged by many harmful insects.","zh":"果實會被許多有害昆蟲破壞。"},{"en":"Harmful insects are insects that damage plants, food, animals, or people.","zh":"harmful insects 指會傷害植物、食物、動物或人的昆蟲。"},{"en":"Mosquitoes are harmful insects because they can spread disease.","zh":"蚊子是有害昆蟲，因為牠們可以傳播疾病。"},{"en":"Harmful insects in orchards can reduce both fruit quality and yield.","zh":"果園中的有害昆蟲可以降低水果質素和產量。"},{"en":"This phrase describes insects by the damage they cause.","zh":"這個短語按昆蟲造成的傷害來描述牠們。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":10},{"front":"not a single fruit","meaning":"沒有一個果實","examples":[{"en":"Without ants, not a single fruit would be perfect.","zh":"沒有螞蟻，沒有一個果實會完美。"},{"en":"Not a single fruit means no fruit at all.","zh":"not a single fruit 指完全沒有任何一個果實。"},{"en":"After the storm, not a single flower remained on the tree.","zh":"暴風雨後，樹上沒有一朵花留下。"},{"en":"This phrase strongly emphasises total absence or failure.","zh":"這個短語強烈強調完全沒有或徹底失敗。"},{"en":"In the passage, it shows how serious insect damage could be.","zh":"在文章中，它顯示昆蟲傷害可能有多嚴重。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":10},{"front":"initially","meaning":"起初","examples":[{"en":"Initially, farmers relied on nests collected from the wild.","zh":"起初，農民依賴從野外收集的蟻巢。"},{"en":"Initially means at first or in the early stage.","zh":"initially 指起初或在早期階段。"},{"en":"Initially, a new employee may need help with simple tasks.","zh":"起初，新員工可能需要別人幫助處理簡單工作。"},{"en":"Initial methods often change when people gain more experience.","zh":"早期方法常在人們獲得更多經驗後改變。"},{"en":"This word introduces the first step before later development.","zh":"這個字引出後來發展之前的第一步。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":10},{"front":"relied on","meaning":"依賴","examples":[{"en":"Farmers relied on nests collected from the wild.","zh":"農民依賴從野外收集的蟻巢。"},{"en":"To rely on something means to depend on it for help or success.","zh":"rely on something 指依靠某物取得幫助或成功。"},{"en":"Students may rely on public transport to get to school.","zh":"學生可能依賴公共交通上學。"},{"en":"Farmers relied on wild nests because they had no organised ant farms yet.","zh":"農民依賴野外蟻巢，因為當時還沒有有組織的螞蟻養殖。"},{"en":"This phrase shows dependence on a resource or person.","zh":"這個短語顯示對資源或人的依賴。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":10},{"front":"collected from the wild","meaning":"從野外收集","examples":[{"en":"The nests were collected from the wild.","zh":"這些蟻巢是從野外收集的。"},{"en":"Collected from the wild means taken from natural places, not farms or shops.","zh":"collected from the wild 指從自然環境取得，而不是從農場或商店取得。"},{"en":"Wild mushrooms should not be collected from the wild unless people can identify them safely.","zh":"除非能安全辨認，否則不應從野外採集野生蘑菇。"},{"en":"Collecting from the wild can reduce natural populations if done too heavily.","zh":"如果過度從野外收集，可能減少天然種群。"},{"en":"This phrase contrasts natural collection with controlled farming.","zh":"這個短語把自然收集與受控養殖作對比。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":10},{"front":"trade in nests was brisk","meaning":"蟻巢買賣興旺","examples":[{"en":"Trade in ant nests was brisk in the market.","zh":"市場中的蟻巢買賣很興旺。"},{"en":"If trade is brisk, buying and selling are active and fast.","zh":"如果 trade is brisk，買賣活動活躍而快速。"},{"en":"Trade in umbrellas becomes brisk when heavy rain is expected.","zh":"當預計會下大雨，雨傘買賣會變得興旺。"},{"en":"Brisk trade shows that many customers want the product.","zh":"買賣興旺顯示許多顧客想要該產品。"},{"en":"This phrase describes a busy market situation.","zh":"這個短語描述繁忙市場情況。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":10},{"front":"free of ants","meaning":"沒有螞蟻的","examples":[{"en":"Orange trees that were free of ants had wormy fruits.","zh":"沒有螞蟻的橙樹會結出有蟲蛀的果實。"},{"en":"Free of ants means having no ants present.","zh":"free of ants 指沒有螞蟻存在。"},{"en":"A kitchen should be free of ants if food is stored properly.","zh":"如果食物妥善儲存，廚房應該沒有螞蟻。"},{"en":"Trees free of protective ants may suffer more pest damage.","zh":"沒有保護性螞蟻的樹可能遭受更多害蟲傷害。"},{"en":"This phrase means “without ants”, not “released by ants”.","zh":"這個短語意思是「沒有螞蟻」，不是「被螞蟻釋放」。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":10},{"front":"wormy fruits","meaning":"有蟲蛀的果實","examples":[{"en":"Orange trees without ants produced wormy fruits.","zh":"沒有螞蟻的橙樹結出有蟲蛀的果實。"},{"en":"Wormy fruits are fruits damaged or infested by worms or larvae.","zh":"wormy fruits 指被蟲或幼蟲破壞或侵入的果實。"},{"en":"A shopper may avoid wormy apples with holes in the skin.","zh":"顧客可能避開表皮有洞的蟲蛀蘋果。"},{"en":"Fruits become wormy when insects lay eggs inside them.","zh":"當昆蟲在果實內產卵，果實就會蟲蛀。"},{"en":"This phrase describes fruit quality damaged by pests.","zh":"這個短語描述受害蟲破壞的水果質素。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":11},{"front":"race to buy","meaning":"爭相購買","examples":[{"en":"People raced to buy nests for their orange trees.","zh":"人們爭相購買蟻巢給自己的橙樹。"},{"en":"To race to buy something means to hurry to buy it before others do.","zh":"race to buy something 指趕快購買，以免被其他人先買走。"},{"en":"Customers may race to buy discounted tickets when sales open.","zh":"減價開始時，顧客可能爭相購買折扣票。"},{"en":"People race to buy a product when supply is limited and demand is high.","zh":"當供應有限而需求高，人們會爭相購買產品。"},{"en":"This phrase suggests urgency and competition.","zh":"這個短語暗示急迫和競爭。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":11},{"front":"became more sophisticated","meaning":"變得更精細成熟","examples":[{"en":"The business quickly became more sophisticated.","zh":"這門生意很快變得更精細成熟。"},{"en":"Became more sophisticated means became more developed, organised, or technically advanced.","zh":"became more sophisticated 指變得更發達、更有組織或技術上更先進。"},{"en":"A small school project may become more sophisticated after students collect real data.","zh":"學生收集真實數據後，小型學校專題可能變得更精細成熟。"},{"en":"Businesses become sophisticated when they develop better methods and systems.","zh":"當生意發展出更好方法和系統，就會變得成熟。"},{"en":"This phrase shows improvement beyond a simple early stage.","zh":"這個短語顯示超越簡單早期階段的改進。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":11},{"front":"from the 10th century","meaning":"從十世紀起","examples":[{"en":"From the 10th century, people began to trap ants artificially.","zh":"從十世紀起，人們開始人工捕捉螞蟻。"},{"en":"From the 10th century means starting in the period of the 900s AD.","zh":"from the 10th century 指從公元900年代開始。"},{"en":"From the 19th century, many cities expanded rapidly because of industry.","zh":"從十九世紀起，許多城市因工業而迅速擴張。"},{"en":"This phrase marks the historical starting point of a change.","zh":"這個短語標示一個變化的歷史起點。"},{"en":"It helps readers follow the timeline of development.","zh":"它幫助讀者跟隨發展時間線。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":11},{"front":"country people","meaning":"鄉間人士","examples":[{"en":"Country people began to trap ants in artificial nests.","zh":"鄉間人士開始用人工巢穴捕捉螞蟻。"},{"en":"Country people are people living in rural areas rather than cities.","zh":"country people 指住在鄉村地區而非城市的人。"},{"en":"Country people may know practical farming skills passed down through families.","zh":"鄉間人士可能懂得家族代代相傳的實用農業技巧。"},{"en":"Rural knowledge often develops from daily contact with land and animals.","zh":"鄉村知識常從日常接觸土地和動物中發展出來。"},{"en":"This phrase contrasts rural people with city people.","zh":"這個短語把鄉村人士與城市人士作對比。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":11},{"front":"artificial nests","meaning":"人工巢穴","examples":[{"en":"People trapped ants in artificial nests baited with fat.","zh":"人們用以脂肪作誘餌的人工巢穴捕捉螞蟻。"},{"en":"Artificial nests are human-made structures designed for animals or insects to live in.","zh":"artificial nests 指人造、供動物或昆蟲居住的結構。"},{"en":"A bird box is an artificial nest for birds in a garden.","zh":"鳥箱是花園中給鳥使用的人工巢穴。"},{"en":"Artificial nests help people attract and manage useful animals.","zh":"人工巢穴幫助人們吸引和管理有用動物。"},{"en":"This phrase contrasts made nests with natural nests.","zh":"這個短語把人造巢與天然巢作對比。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":11},{"front":"baited with fat","meaning":"以脂肪作誘餌","examples":[{"en":"The artificial nests were baited with fat.","zh":"這些人工巢穴以脂肪作誘餌。"},{"en":"Baited with fat means food fat was used to attract animals or insects.","zh":"baited with fat 指使用食用脂肪來吸引動物或昆蟲。"},{"en":"A trap may be baited with cheese to attract mice.","zh":"捕鼠器可能以芝士作誘餌來吸引老鼠。"},{"en":"Bait works because animals move toward food they want.","zh":"誘餌有效，是因為動物會靠近牠們想吃的食物。"},{"en":"This phrase explains how people attracted the ants.","zh":"這個短語解釋人們如何吸引螞蟻。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":11},{"front":"fruit-growing families","meaning":"種果家庭","examples":[{"en":"Fruit-growing families bought ants from vendors.","zh":"種果家庭從小販那裡購買螞蟻。"},{"en":"Fruit-growing families are families whose work involves growing fruit.","zh":"fruit-growing families 指以種植水果為工作的一些家庭。"},{"en":"A fruit-growing family may care for trees together across generations.","zh":"種果家庭可能幾代人一起照料果樹。"},{"en":"Such families buy tools or insects if these help protect crops.","zh":"如果工具或昆蟲能幫助保護作物，這些家庭會購買它們。"},{"en":"This phrase connects family life with farming work.","zh":"這個短語把家庭生活與農業工作連起來。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":11},{"front":"vendors","meaning":"小販；賣家","examples":[{"en":"Vendors made a business of collecting and selling ants.","zh":"小販以收集和出售螞蟻為生意。"},{"en":"Vendors are people who sell goods, often in markets or on streets.","zh":"vendors 指出售貨品的人，常在市場或街頭營業。"},{"en":"Street vendors may sell fruit, snacks, flowers, or small tools.","zh":"街頭小販可能賣水果、小食、花或小工具。"},{"en":"Vendors appear when customers regularly want a product.","zh":"當顧客經常想要某產品，小販就會出現。"},{"en":"This word describes sellers, not the people buying the goods.","zh":"這個字描述賣方，而不是買方。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":11},{"front":"make a business of","meaning":"以……為生意","examples":[{"en":"Some vendors made a business of collecting and selling ants.","zh":"有些小販以收集和出售螞蟻為生意。"},{"en":"To make a business of something means to earn money by doing it regularly.","zh":"make a business of something 指透過定期做某事賺錢。"},{"en":"A teenager may make a business of repairing neighbours’ bicycles.","zh":"青少年可能以維修鄰居單車為生意。"},{"en":"When demand is high, a small activity can become a business.","zh":"當需求高，小活動可以變成生意。"},{"en":"This phrase shows how an activity becomes a source of income.","zh":"這個短語顯示一項活動如何成為收入來源。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":11},{"front":"such creatures","meaning":"這些生物","examples":[{"en":"Vendors collected and sold such creatures.","zh":"小販收集並出售這些生物。"},{"en":"Such creatures means animals or insects of the kind just mentioned.","zh":"such creatures 指剛才提到的那類動物或昆蟲。"},{"en":"After discussing frogs and lizards, a writer may say such creatures help control insects.","zh":"討論青蛙和蜥蜴後，作者可能說這些生物有助控制昆蟲。"},{"en":"This phrase avoids repeating the exact animal name again.","zh":"這個短語避免再次重複同一動物名稱。"},{"en":"It points back to the creatures already being discussed.","zh":"它指回正在討論的生物。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":12},{"front":"hogs’ or sheep’s bladders","meaning":"豬或羊的膀胱","examples":[{"en":"Vendors filled hogs’ or sheep’s bladders with fat.","zh":"小販把脂肪裝入豬或羊的膀胱。"},{"en":"Hogs’ or sheep’s bladders are animal bladder sacs from pigs or sheep.","zh":"hogs’ or sheep’s bladders 指來自豬或羊的膀胱囊。"},{"en":"In older times, animal bladders were sometimes used as containers.","zh":"在舊時，動物膀胱有時被用作容器。"},{"en":"Filling bladders with fat created a baited space for ants.","zh":"把脂肪裝入膀胱，創造了吸引螞蟻的空間。"},{"en":"This phrase describes a traditional material that sounds unusual today.","zh":"這個短語描述一種今天聽起來不尋常的傳統材料。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":12},{"front":"cavities open","meaning":"空腔打開","examples":[{"en":"The bladders were placed with the cavities open.","zh":"這些膀胱被放置時空腔打開。"},{"en":"Cavities open means the hollow spaces were left open.","zh":"cavities open 指中空部分保持打開。"},{"en":"A box trap works only if the entrance cavity is open.","zh":"盒形陷阱只有入口空腔打開才會有效。"},{"en":"Leaving the cavities open allowed ants to enter the bladders.","zh":"讓空腔打開可以讓螞蟻進入膀胱。"},{"en":"This phrase describes how the container was positioned.","zh":"這個短語描述容器如何被放置。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":12},{"front":"next to","meaning":"在……旁邊","examples":[{"en":"The bladders were placed next to the ants’ nests.","zh":"這些膀胱被放在蟻巢旁邊。"},{"en":"Next to means beside or very close to something.","zh":"next to 指在某物旁邊或很接近。"},{"en":"A student may sit next to a friend in class.","zh":"學生可能在課堂上坐在朋友旁邊。"},{"en":"Placing bait next to a nest makes it easier for ants to find it.","zh":"把誘餌放在巢旁邊，螞蟻會更容易找到它。"},{"en":"This phrase describes position.","zh":"這個短語描述位置。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":12},{"front":"migrated into","meaning":"遷入……","examples":[{"en":"The ants migrated into the bladders.","zh":"螞蟻遷入這些膀胱。"},{"en":"To migrate into a place means to move into it and begin living there.","zh":"migrate into a place 指移入某地並開始在那裡生活。"},{"en":"Birds may migrate into warmer areas during winter.","zh":"鳥類可能在冬天遷入較暖地區。"},{"en":"Ants migrated into the bladders because food attracted them.","zh":"螞蟻遷入膀胱，是因為食物吸引牠們。"},{"en":"This phrase shows movement into a new living space.","zh":"這個短語顯示進入新居住空間的移動。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":12},{"front":"rearing orange ants","meaning":"飼養柑橘蟻","examples":[{"en":"This practice was known as rearing orange ants.","zh":"這種做法被稱為飼養柑橘蟻。"},{"en":"Rearing orange ants means raising or keeping citrus ants for use in orchards.","zh":"rearing orange ants 指為果園用途飼養或保存柑橘蟻。"},{"en":"Farmers rear animals or insects when they help them grow and survive.","zh":"農民幫助動物或昆蟲生長和存活時，就是在飼養牠們。"},{"en":"Rearing ants allowed growers to supply orchards more reliably.","zh":"飼養螞蟻讓種植者能更可靠地供應果園。"},{"en":"This phrase treats ant care as a kind of farming.","zh":"這個短語把照顧螞蟻視為一種農業。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":12},{"front":"attached the bladders to","meaning":"將膀胱綁到……上","examples":[{"en":"Farmers attached the bladders to their trees.","zh":"農民將膀胱綁到樹上。"},{"en":"To attach something to something else means to fasten or connect it.","zh":"attach something to something else 指把某物固定或連接到另一物上。"},{"en":"A teacher may attach a label to each student’s folder.","zh":"老師可能把標籤貼到每個學生的文件夾上。"},{"en":"Farmers attached the bladders so ants could move onto the trees.","zh":"農民把膀胱綁上去，好讓螞蟻移到樹上。"},{"en":"This phrase shows a physical action used to transfer ants.","zh":"這個短語顯示用來轉移螞蟻的實際動作。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":12},{"front":"spread to other trees","meaning":"擴散到其他樹","examples":[{"en":"The ants spread to other trees and built new nests.","zh":"螞蟻擴散到其他樹並建立新巢。"},{"en":"To spread to other trees means to move from one tree to more trees.","zh":"spread to other trees 指從一棵樹移動到更多樹。"},{"en":"A plant disease can spread to other trees if tools are not cleaned.","zh":"如果工具沒有清潔，植物疾病可能擴散到其他樹。"},{"en":"Ants spread through orchards when branches or bridges connect trees.","zh":"當樹枝或橋連接樹木，螞蟻就會在果園中擴散。"},{"en":"This phrase describes expansion across a growing area.","zh":"這個短語描述在種植區中的擴展。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":12},{"front":"built new nests","meaning":"建立新巢","examples":[{"en":"The ants built new nests in the trees.","zh":"螞蟻在樹上建立新巢。"},{"en":"Built new nests means created new places to live and raise young.","zh":"built new nests 指建造新的居住和育幼地方。"},{"en":"Birds build new nests when spring arrives.","zh":"春天來臨時，鳥會建立新巢。"},{"en":"New nests allow an insect colony to expand through an orchard.","zh":"新巢讓昆蟲群落能在果園中擴展。"},{"en":"This phrase shows settlement and growth.","zh":"這個短語顯示定居和增長。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":12},{"front":"by the 17th century","meaning":"到十七世紀時","examples":[{"en":"By the 17th century, growers were building bamboo walkways.","zh":"到十七世紀時，種植者已在樹間建造竹製通道。"},{"en":"By the 17th century means no later than the 1600s.","zh":"by the 17th century 指不遲於1600年代。"},{"en":"By the 20th century, many cities had electric streetlights.","zh":"到二十世紀時，許多城市已有電力街燈。"},{"en":"This phrase shows that a development had happened by a certain historical period.","zh":"這個短語顯示某發展在某個歷史時期之前已發生。"},{"en":"It helps organise events on a timeline.","zh":"它有助按時間線整理事件。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":12},{"front":"bamboo walkways","meaning":"竹製通道","examples":[{"en":"Growers built bamboo walkways between their trees.","zh":"種植者在樹與樹之間建造竹製通道。"},{"en":"Bamboo walkways are paths or bridges made from bamboo.","zh":"bamboo walkways 指用竹製成的道路或橋。"},{"en":"Gardeners may use bamboo walkways to cross wet ground without damaging plants.","zh":"園丁可能使用竹製通道穿過濕地，而不傷害植物。"},{"en":"Bamboo walkways helped ants travel safely from tree to tree.","zh":"竹製通道幫助螞蟻安全地從一棵樹走到另一棵樹。"},{"en":"This phrase describes a simple structure made from a natural material.","zh":"這個短語描述由天然材料製成的簡單結構。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":13},{"front":"speed the colonisation of","meaning":"加快……的定居擴散","examples":[{"en":"The walkways helped speed the colonisation of orchards.","zh":"這些通道有助加快螞蟻在果園中的定居擴散。"},{"en":"To speed the colonisation of a place means to help a species settle there more quickly.","zh":"speed the colonisation of a place 指幫助某物種更快在某地定居。"},{"en":"Connecting fish tanks could speed the spread of tiny aquatic animals.","zh":"連接魚缸可能加快小型水生動物的擴散。"},{"en":"Bridges between trees allowed ants to occupy orchards faster.","zh":"樹與樹之間的橋讓螞蟻更快佔據果園。"},{"en":"This phrase links movement with settlement and expansion.","zh":"這個短語把移動與定居擴展連起來。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":13},{"front":"narrow bridges","meaning":"窄橋","examples":[{"en":"The ants ran along narrow bridges from tree to tree.","zh":"螞蟻沿著窄橋從一棵樹跑到另一棵樹。"},{"en":"Narrow bridges are thin crossings that connect two places.","zh":"narrow bridges 指連接兩個地方的狹窄通道。"},{"en":"Children may cross a narrow bridge carefully in a park.","zh":"孩子可能在公園小心走過窄橋。"},{"en":"Narrow bridges let ants move without going down to the ground.","zh":"窄橋讓螞蟻不用下到地面也能移動。"},{"en":"This phrase describes small connecting paths.","zh":"這個短語描述細小的連接通道。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":13},{"front":"established nests","meaning":"建立巢穴","examples":[{"en":"The ants established nests by the hundreds of thousands.","zh":"螞蟻數以十萬計地建立巢穴。"},{"en":"Established nests means built and settled in nests successfully.","zh":"established nests 指成功建造並定居於巢穴中。"},{"en":"Birds establish nests when they build them and begin raising young.","zh":"鳥建好巢並開始育雛時，就是建立巢穴。"},{"en":"Once ants establish nests, they can defend and expand their territory.","zh":"一旦螞蟻建立巢穴，牠們就能保衛並擴張領地。"},{"en":"This phrase suggests successful settlement, not just temporary arrival.","zh":"這個短語暗示成功定居，而不只是暫時到達。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":13},{"front":"by the hundreds of thousands","meaning":"數以十萬計地","examples":[{"en":"The ants established nests by the hundreds of thousands.","zh":"螞蟻數以十萬計地建立巢穴。"},{"en":"By the hundreds of thousands means in extremely large numbers.","zh":"by the hundreds of thousands 指以極大數量。"},{"en":"Fans may watch a popular final by the hundreds of thousands online.","zh":"粉絲可能數以十萬計地在網上觀看熱門決賽。"},{"en":"Large numbers can show how successful or widespread something is.","zh":"大量數字可以顯示某事有多成功或廣泛。"},{"en":"This phrase strongly emphasises scale.","zh":"這個短語強烈強調規模。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":13},{"front":"clearly thought so","meaning":"顯然如此認為","examples":[{"en":"The orange growers clearly thought the method worked.","zh":"橙農顯然認為這種方法有效。"},{"en":"Clearly thought so means obviously believed that this was true.","zh":"clearly thought so 指明顯相信某事是真的。"},{"en":"The students clearly thought the lesson was useful because they asked for more practice.","zh":"學生要求更多練習，顯然認為這堂課有用。"},{"en":"Repeated use of a method often shows people believe it works.","zh":"反覆使用某方法常顯示人們相信它有效。"},{"en":"This phrase points to a conclusion based on behaviour.","zh":"這個短語指向基於行為作出的結論。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":13},{"front":"one authority","meaning":"一位權威人士","examples":[{"en":"One authority stressed the importance of controlling pests.","zh":"一位權威人士強調控制害蟲的重要性。"},{"en":"One authority means one expert or respected source.","zh":"one authority 指一位專家或受尊重的來源。"},{"en":"One authority on education argued that sleep affects learning strongly.","zh":"一位教育權威人士指出睡眠強烈影響學習。"},{"en":"Quoting an authority can make an argument more credible.","zh":"引用權威人士可以令論點更可信。"},{"en":"This phrase introduces a source with expertise or status.","zh":"這個短語引入具有專業知識或地位的來源。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":13},{"front":"stressed how important it was to","meaning":"強調……有多重要","examples":[{"en":"Chhii Ta-Chun stressed how important it was to keep trees pest-free.","zh":"Chhii Ta-Chun 強調使果樹免受害蟲有多重要。"},{"en":"To stress how important it is to do something means to strongly emphasise its importance.","zh":"stress how important it is to do something 指強烈強調做某事的重要性。"},{"en":"A doctor may stress how important it is to finish a course of medicine.","zh":"醫生可能強調完成整個療程有多重要。"},{"en":"People stress importance when ignoring advice could cause serious problems.","zh":"當忽視建議可能造成嚴重問題，人們會強調其重要性。"},{"en":"This phrase signals strong warning or advice.","zh":"這個短語表示強烈警告或建議。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":13},{"front":"keep the fruit trees free of","meaning":"使果樹免受……","examples":[{"en":"Growers wanted to keep the fruit trees free of insect pests.","zh":"種植者想使果樹免受害蟲侵害。"},{"en":"To keep trees free of pests means to prevent pests from living on or damaging them.","zh":"keep trees free of pests 指防止害蟲住在樹上或傷害樹木。"},{"en":"Gardeners keep flowers free of insects by checking leaves regularly.","zh":"園丁透過定期檢查葉子，使花免受昆蟲侵害。"},{"en":"Trees stay healthier when harmful insects are kept away.","zh":"當有害昆蟲被隔離，樹木會更健康。"},{"en":"This phrase describes prevention, not repair after damage.","zh":"這個短語描述預防，而不是受損後修補。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":13},{"front":"insect pests","meaning":"害蟲","examples":[{"en":"It was important to keep fruit trees free of insect pests.","zh":"使果樹免受害蟲侵害很重要。"},{"en":"Insect pests are insects that damage crops, trees, stored food, or homes.","zh":"insect pests 指會傷害農作物、樹木、儲存食物或家居的昆蟲。"},{"en":"Ants may be helpful if they kill insect pests in an orchard.","zh":"如果螞蟻殺死果園中的害蟲，牠們可能很有用。"},{"en":"Insect pests reduce harvests when they eat leaves or fruit.","zh":"害蟲吃葉或果實時，會減少收成。"},{"en":"This phrase describes insects from the human farming point of view.","zh":"這個短語從人類農業角度描述昆蟲。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":13},{"front":"it is essential to","meaning":"……是必要的","examples":[{"en":"It is essential to eliminate caterpillars.","zh":"消滅毛蟲是必要的。"},{"en":"It is essential to do something means it is necessary and very important.","zh":"it is essential to do something 指做某事是必要且非常重要的。"},{"en":"It is essential to wear a helmet when cycling on busy roads.","zh":"在繁忙道路上踩單車時，戴頭盔是必要的。"},{"en":"Something becomes essential when failure to do it causes serious harm.","zh":"當不做某事會造成嚴重傷害，它就變得必要。"},{"en":"This phrase gives strong advice or instruction.","zh":"這個短語給出強烈建議或指示。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":14},{"front":"eliminate them","meaning":"消滅它們","examples":[{"en":"It is essential to eliminate the pests.","zh":"消滅這些害蟲是必要的。"},{"en":"To eliminate them means to remove or destroy them completely.","zh":"eliminate them 指完全移除或消滅它們。"},{"en":"A school may eliminate distractions by asking students to put phones away.","zh":"學校可能要求學生收起手機，以消除干擾。"},{"en":"Farmers eliminate pests to prevent damage from spreading.","zh":"農民消滅害蟲，以防損害擴散。"},{"en":"This phrase suggests a complete solution, not a small reduction.","zh":"這個短語暗示完整解決，而不只是稍微減少。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":14},{"front":"so that","meaning":"以便；使得","examples":[{"en":"The pests must be eliminated so that the trees are not injured.","zh":"必須消滅害蟲，以免樹木受損。"},{"en":"So that introduces the purpose or intended result of an action.","zh":"so that 用來引出某行動的目的或預期結果。"},{"en":"Students should save their work often so that they do not lose it.","zh":"學生應經常儲存功課，以免失去檔案。"},{"en":"Farmers control pests so that crops can grow safely.","zh":"農民控制害蟲，使農作物能安全生長。"},{"en":"This phrase connects an action with its goal.","zh":"這個短語把行動與目標連起來。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":14},{"front":"injured","meaning":"受損","examples":[{"en":"The trees could be injured by insect pests.","zh":"樹木可能被害蟲弄至受損。"},{"en":"Injured means harmed, damaged, or hurt.","zh":"injured 指受到傷害、損壞或受傷。"},{"en":"A football player may be injured after falling badly.","zh":"足球員嚴重跌倒後可能受傷。"},{"en":"Trees are injured when insects damage leaves, bark, or fruit.","zh":"當昆蟲傷害葉、樹皮或果實時，樹木就會受損。"},{"en":"This word can describe harm to people, animals, or plants.","zh":"這個字可以描述人、動物或植物受到傷害。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":14},{"front":"hand labour","meaning":"人手勞動","examples":[{"en":"Hand labour was not as efficient as ant power.","zh":"人手勞動不如螞蟻力量有效率。"},{"en":"Hand labour means work done by people using their hands rather than machines or animals.","zh":"hand labour 指人用雙手而不是機器或動物完成的工作。"},{"en":"Picking fruit often requires hand labour because machines may damage it.","zh":"採摘水果通常需要人手勞動，因為機器可能弄壞水果。"},{"en":"Hand labour can be slow when a field is large and pests are numerous.","zh":"當田地很大而害蟲很多，人手勞動可能很慢。"},{"en":"This phrase contrasts human effort with other sources of work.","zh":"這個短語把人力與其他工作力量作對比。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":14},{"front":"not nearly as efficient as","meaning":"遠不及……有效率","examples":[{"en":"Hand labour is not nearly as efficient as ant power.","zh":"人手勞動遠不及螞蟻力量有效率。"},{"en":"Not nearly as efficient as means much less effective or productive than something else.","zh":"not nearly as efficient as 指比某物有效率低得多。"},{"en":"Walking is not nearly as efficient as taking the train for a long journey.","zh":"長途旅程中，步行遠不及乘火車有效率。"},{"en":"If one method is not nearly as efficient, people may replace it.","zh":"如果一種方法遠不及另一種有效，人們可能會替換它。"},{"en":"This phrase shows a large difference in effectiveness.","zh":"這個短語顯示效率上的巨大差距。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":14},{"front":"ant power","meaning":"螞蟻力量","examples":[{"en":"Ant power was more efficient than hand labour.","zh":"螞蟻力量比人手勞動更有效率。"},{"en":"Ant power means the useful work done by ants.","zh":"ant power 指螞蟻完成的有用工作。"},{"en":"In this passage, ant power means ants hunting pests in orchards.","zh":"在這篇文章中，螞蟻力量指螞蟻在果園中捕食害蟲。"},{"en":"Natural animal power can sometimes replace slow human work.","zh":"天然動物力量有時可以取代緩慢的人手工作。"},{"en":"This phrase is a playful way to describe insects doing useful labour.","zh":"這個短語以帶玩味的方式描述昆蟲做有用勞動。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":14},{"front":"just as impressed","meaning":"同樣印象深刻","examples":[{"en":"Swingle was just as impressed by the Chinese method.","zh":"Swingle 對中國方法同樣印象深刻。"},{"en":"Just as impressed means equally surprised, interested, or admiring.","zh":"just as impressed 指同樣感到驚訝、感興趣或欣賞。"},{"en":"The teacher liked the quiet student’s essay and was just as impressed by her speech.","zh":"老師喜歡安靜學生的作文，也對她的演講同樣印象深刻。"},{"en":"If a method works well, observers may be impressed even if it seems unusual.","zh":"如果一種方法很有效，即使看似不尋常，觀察者也可能印象深刻。"},{"en":"This phrase compares equal levels of admiration.","zh":"這個短語比較相同程度的欣賞。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":14},{"front":"despite his reports","meaning":"儘管有他的報告","examples":[{"en":"Despite his reports, many Western biologists were sceptical.","zh":"儘管有他的報告，許多西方生物學家仍然懷疑。"},{"en":"Despite his reports means although he had written or given reports.","zh":"despite his reports 指雖然他已寫出或提交報告。"},{"en":"Despite the doctor’s warnings, some patients still ignored the advice.","zh":"儘管有醫生警告，有些病人仍然忽視建議。"},{"en":"Evidence does not always convince people immediately.","zh":"證據不一定立即說服人。"},{"en":"This phrase introduces a contrast between evidence and reaction.","zh":"這個短語引出證據與反應之間的對比。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":14},{"front":"Western biologists","meaning":"西方生物學家","examples":[{"en":"Many Western biologists were sceptical of Swingle’s reports.","zh":"許多西方生物學家對 Swingle 的報告表示懷疑。"},{"en":"Western biologists are scientists from Western countries who study living organisms.","zh":"Western biologists 指來自西方國家、研究生物的科學家。"},{"en":"Western biologists may study plants, insects, animals, or ecosystems.","zh":"西方生物學家可能研究植物、昆蟲、動物或生態系統。"},{"en":"Scientists may be sceptical when a claim challenges accepted ideas.","zh":"當一個說法挑戰既有觀念，科學家可能會懷疑。"},{"en":"This phrase identifies the group that doubted the Chinese method.","zh":"這個短語指出懷疑中國方法的群體。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":14},{"front":"sceptical","meaning":"懷疑的","examples":[{"en":"Many Western biologists were sceptical.","zh":"許多西方生物學家是懷疑的。"},{"en":"Sceptical means doubtful and not easily convinced.","zh":"sceptical 指有所懷疑，不容易被說服。"},{"en":"A parent may be sceptical of an expensive product with no evidence.","zh":"對沒有證據的昂貴產品，家長可能會懷疑。"},{"en":"People become sceptical when a claim sounds too unusual or too good.","zh":"當一個說法聽起來太不尋常或太好，人們會變得懷疑。"},{"en":"This word describes a cautious attitude toward belief.","zh":"這個字描述對相信某事持謹慎態度。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":15},{"front":"highly controversial","meaning":"極具爭議","examples":[{"en":"The idea of using one insect against another was highly controversial.","zh":"用一種昆蟲對付另一種昆蟲的想法極具爭議。"},{"en":"Highly controversial means causing strong disagreement or debate.","zh":"highly controversial 指引起強烈分歧或辯論。"},{"en":"A new school rule may be highly controversial if parents and students strongly disagree.","zh":"如果家長和學生強烈不同意，新校規可能極具爭議。"},{"en":"Ideas become controversial when they challenge habits or values.","zh":"當想法挑戰習慣或價值觀時，就會變得具爭議。"},{"en":"This phrase shows that people argued seriously about the idea.","zh":"這個短語顯示人們對該想法有嚴肅爭論。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":15},{"front":"first breakthrough","meaning":"首次突破","examples":[{"en":"The first breakthrough in the West had come in 1888.","zh":"西方的首次突破出現在1888年。"},{"en":"A first breakthrough is the first major success after difficulty.","zh":"first breakthrough 指經歷困難後第一次重大成功。"},{"en":"A student’s first breakthrough in speaking may come when they answer without translating.","zh":"學生在說話方面的首次突破，可能是不用翻譯就能回答。"},{"en":"Breakthroughs matter because they change what people think is possible.","zh":"突破很重要，因為它改變人們認為可能的事情。"},{"en":"This phrase marks an important turning point.","zh":"這個短語標示重要轉折點。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":15},{"front":"infant orange industry","meaning":"初起步的橙業","examples":[{"en":"California’s infant orange industry was saved from extinction.","zh":"加州初起步的橙業從滅絕中被拯救。"},{"en":"An infant industry is a new industry that is still young and developing.","zh":"infant industry 指仍然年輕、正在發展的新興行業。"},{"en":"A city may support an infant technology industry with grants and training.","zh":"城市可能透過資助和培訓支持初起步的科技產業。"},{"en":"Infant industries are vulnerable because they are not yet strong or established.","zh":"初起步行業很脆弱，因為它們尚未強大或穩固。"},{"en":"This phrase compares a young industry to a young child.","zh":"這個短語把年輕行業比作幼兒。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":15},{"front":"saved from extinction","meaning":"從滅絕中被拯救","examples":[{"en":"The orange industry was saved from extinction by a beetle.","zh":"橙業被一種甲蟲從滅絕中拯救出來。"},{"en":"Saved from extinction means prevented from disappearing completely.","zh":"saved from extinction 指被防止完全消失。"},{"en":"Conservation work can save rare animals from extinction.","zh":"保育工作可以把稀有動物從滅絕中拯救出來。"},{"en":"If pests had destroyed the crop, the young industry might have disappeared.","zh":"如果害蟲摧毀作物，年輕行業可能已經消失。"},{"en":"This phrase describes rescue from total loss.","zh":"這個短語描述從徹底喪失中被拯救。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":15},{"front":"Australian vedalia beetle","meaning":"澳洲瓢蟲","examples":[{"en":"The Australian vedalia beetle controlled a serious citrus pest.","zh":"澳洲瓢蟲控制了一種嚴重柑橘害蟲。"},{"en":"The Australian vedalia beetle is a beetle species used to control scale insects.","zh":"Australian vedalia beetle 是一種用來控制介殼蟲的甲蟲。"},{"en":"Farmers may introduce helpful beetles to eat crop pests.","zh":"農民可能引入有益甲蟲來吃作物害蟲。"},{"en":"The beetle became important because it saved citrus crops naturally.","zh":"這種甲蟲變得重要，是因為牠自然地拯救柑橘作物。"},{"en":"This phrase names a biological control agent.","zh":"這個短語指一種生物防治工具。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":15},{"front":"made any inroads into","meaning":"對……取得進展","examples":[{"en":"The beetle made inroads into the pest explosion.","zh":"這種甲蟲對害蟲激增問題取得進展。"},{"en":"To make inroads into a problem means to make progress in reducing it.","zh":"make inroads into a problem 指在減少某問題方面取得進展。"},{"en":"A new bus route may make inroads into traffic congestion.","zh":"新巴士路線可能對交通擠塞問題取得進展。"},{"en":"Progress is meaningful when it reduces a large problem step by step.","zh":"逐步減少大問題時，進展就是有意義的。"},{"en":"This phrase suggests partial but real success.","zh":"這個短語暗示部分但真實的成功。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":15},{"front":"explosion of","meaning":"……的激增","examples":[{"en":"The orange industry faced an explosion of cottony cushion scale.","zh":"橙業面對吹綿蚧的激增。"},{"en":"An explosion of something means a sudden large increase in it.","zh":"explosion of something 指某物突然大量增加。"},{"en":"A school may face an explosion of messages after exam results are released.","zh":"考試成績公布後，學校可能面對訊息激增。"},{"en":"Pest explosions happen when conditions allow insects to multiply quickly.","zh":"當環境讓昆蟲快速繁殖，就會出現害蟲激增。"},{"en":"This phrase describes rapid growth, not a literal blast.","zh":"這個短語描述快速增長，而不是字面爆炸。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":15},{"front":"cottony cushion scale","meaning":"吹綿蚧","examples":[{"en":"Cottony cushion scale threatened California’s citrus crops.","zh":"吹綿蚧威脅加州的柑橘作物。"},{"en":"Cottony cushion scale is a scale insect pest that can damage citrus trees.","zh":"cottony cushion scale 是一種會傷害柑橘樹的介殼蟲害蟲。"},{"en":"Growers may notice cottony cushion scale as white cottony masses on plants.","zh":"種植者可能在植物上看到白色棉絮狀物，那就是吹綿蚧。"},{"en":"This pest weakens trees by feeding on plant sap.","zh":"這種害蟲透過吸食植物汁液削弱樹木。"},{"en":"This phrase names a specific agricultural pest.","zh":"這個短語指一種特定農業害蟲。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":15},{"front":"threatening to destroy","meaning":"威脅要摧毀","examples":[{"en":"The pest was threatening to destroy California’s citrus crops.","zh":"這種害蟲威脅要摧毀加州的柑橘作物。"},{"en":"Threatening to destroy means creating a serious risk of completely ruining something.","zh":"threatening to destroy 指造成完全破壞某物的嚴重風險。"},{"en":"Heavy rain may threaten to destroy a village harvest.","zh":"大雨可能威脅要摧毀村莊收成。"},{"en":"A pest becomes urgent when it threatens to destroy valuable crops.","zh":"當害蟲威脅要摧毀有價值作物，問題就變得緊急。"},{"en":"This phrase describes a danger that may soon cause major loss.","zh":"這個短語描述很快可能造成重大損失的危險。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":15},{"front":"citrus crops","meaning":"柑橘作物","examples":[{"en":"Cottony cushion scale threatened the state’s citrus crops.","zh":"吹綿蚧威脅該州的柑橘作物。"},{"en":"Citrus crops are crops such as oranges, lemons, mandarins, and pomelos.","zh":"citrus crops 指橙、檸檬、柑和柚子等作物。"},{"en":"Farmers grow citrus crops in warm regions with enough sunlight.","zh":"農民在陽光充足的溫暖地區種植柑橘作物。"},{"en":"Disease and pests can reduce the value of citrus crops.","zh":"疾病和害蟲可以降低柑橘作物的價值。"},{"en":"This phrase refers to citrus plants grown for harvest.","zh":"這個短語指為收成而種植的柑橘植物。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":16},{"front":"nothing of the sort","meaning":"根本不是那回事","examples":[{"en":"California’s “first” was nothing of the sort.","zh":"加州的「第一次」根本不是那回事。"},{"en":"Nothing of the sort means not that kind of thing at all.","zh":"nothing of the sort 指完全不是那類事情。"},{"en":"People called it a new idea, but it was nothing of the sort.","zh":"人們稱它為新想法，但它根本不是那回事。"},{"en":"This phrase rejects a claim strongly and directly.","zh":"這個短語強烈而直接地否定一個說法。"},{"en":"Here, it means the Western “first” was not truly the first example.","zh":"在這裡，它表示西方的「首次」其實不是真正首次。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":16},{"front":"expert in","meaning":"精於……","examples":[{"en":"The Chinese had been expert in biological control for centuries.","zh":"中國人數百年來一直精於生物防治。"},{"en":"Expert in something means highly skilled or knowledgeable in that area.","zh":"expert in something 指在某方面很有技能或知識。"},{"en":"A nurse may be expert in caring for newborn babies.","zh":"護士可能精於照顧初生嬰兒。"},{"en":"People become expert through long practice and observation.","zh":"人們透過長期練習和觀察變得精通。"},{"en":"This phrase describes deep ability in a field.","zh":"這個短語描述某領域中的深厚能力。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":16},{"front":"long tradition","meaning":"悠久傳統","examples":[{"en":"The long tradition of ants in Chinese orchards began to weaken.","zh":"中國果園使用螞蟻的悠久傳統開始減弱。"},{"en":"A long tradition is a practice that has continued for many years or generations.","zh":"long tradition 指持續多年或多代人的做法。"},{"en":"A family may have a long tradition of gathering for dinner on Sundays.","zh":"一個家庭可能有星期日一起吃晚飯的悠久傳統。"},{"en":"Long traditions can weaken when new technology or habits replace them.","zh":"當新科技或習慣取代舊做法，悠久傳統可能減弱。"},{"en":"This phrase connects continuity with cultural or practical history.","zh":"這個短語把延續性與文化或實用歷史連起來。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":16},{"front":"began to waver","meaning":"開始動搖","examples":[{"en":"The use of ants began to waver in the 1950s and 1960s.","zh":"螞蟻的使用在1950和1960年代開始動搖。"},{"en":"Began to waver means started to become weaker, less certain, or less stable.","zh":"began to waver 指開始變弱、變得不確定或不穩定。"},{"en":"A student’s confidence may begin to waver after several poor test results.","zh":"學生在幾次測驗成績差後，自信可能開始動搖。"},{"en":"A tradition wavers when fewer people continue to practise it.","zh":"當越來越少人繼續實踐，傳統就會動搖。"},{"en":"This phrase shows weakening, not complete disappearance.","zh":"這個短語顯示減弱，而不是完全消失。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":16},{"front":"introduction of","meaning":"……的引入","examples":[{"en":"The tradition weakened with the introduction of insecticides.","zh":"隨著殺蟲劑的引入，這個傳統減弱了。"},{"en":"The introduction of something means the arrival or first use of it.","zh":"introduction of something 指某物的到來或首次使用。"},{"en":"The introduction of online payment changed how many people shop.","zh":"網上支付的引入改變了許多人購物的方式。"},{"en":"New technology can weaken old practices when people switch quickly.","zh":"當人們迅速轉用新科技，舊做法可能減弱。"},{"en":"This phrase links a new arrival with later effects.","zh":"這個短語把新事物的出現與之後影響連起來。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":16},{"front":"powerful organic insecticides","meaning":"強效有機殺蟲劑","examples":[{"en":"Powerful organic insecticides replaced ants in many orchards.","zh":"強效有機殺蟲劑在許多果園中取代了螞蟻。"},{"en":"Powerful organic insecticides are strong chemical pest killers made from organic compounds.","zh":"powerful organic insecticides 指由有機化合物製成的強力化學殺蟲劑。"},{"en":"Farmers may use powerful insecticides when pest damage becomes severe.","zh":"當害蟲傷害變得嚴重時，農民可能使用強效殺蟲劑。"},{"en":"Strong chemicals can work quickly but may create cost and resistance problems.","zh":"強力化學品可以快速見效，但可能造成成本和抗藥性問題。"},{"en":"This phrase refers to chemical control, not natural ant control.","zh":"這個短語指化學防治，而不是天然螞蟻防治。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":16},{"front":"switched to chemicals","meaning":"轉用化學品","examples":[{"en":"Most fruit growers switched to chemicals.","zh":"大多數果農轉用化學品。"},{"en":"Switched to chemicals means changed from another method to chemical treatment.","zh":"switched to chemicals 指從另一種方法改用化學處理。"},{"en":"A gardener may switch to chemicals after natural sprays fail.","zh":"天然噴劑失效後，園丁可能轉用化學品。"},{"en":"People switch methods when they believe a new option is easier or faster.","zh":"當人們相信新選項更容易或更快，就會轉換方法。"},{"en":"This phrase describes a change in pest-control strategy.","zh":"這個短語描述害蟲防治策略的改變。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":16},{"front":"hung onto","meaning":"堅持保留","examples":[{"en":"A few growers hung onto their ants.","zh":"少數種植者堅持保留他們的螞蟻。"},{"en":"To hang onto something means to keep it and not give it up.","zh":"hang onto something 指保留某物而不放棄。"},{"en":"A family may hang onto old photos because they carry memories.","zh":"家庭可能保留舊照片，因為它們承載回憶。"},{"en":"Some growers kept ants because they still trusted the old method.","zh":"有些種植者保留螞蟻，因為他們仍信任舊方法。"},{"en":"This phrase suggests holding on despite pressure to change.","zh":"這個短語暗示即使有改變壓力，仍然堅持保留。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":16},{"front":"abandoned ants in favour of","meaning":"放棄螞蟻而改用……","examples":[{"en":"Some growers abandoned ants in favour of chemicals.","zh":"有些種植者放棄螞蟻而改用化學品。"},{"en":"To abandon one thing in favour of another means to stop using the first and choose the second.","zh":"abandon one thing in favour of another 指停止使用第一樣東西並選擇第二樣。"},{"en":"A school may abandon paper notices in favour of email.","zh":"學校可能放棄紙本通告而改用電郵。"},{"en":"Growers chose chemicals because they believed they were more modern or convenient.","zh":"種植者選擇化學品，因為他們相信它們更現代或方便。"},{"en":"This phrase clearly shows replacement.","zh":"這個短語清楚顯示替換。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":16},{"front":"became disillusioned","meaning":"感到幻滅；不再抱幻想","examples":[{"en":"Growers who used chemicals quickly became disillusioned.","zh":"使用化學品的種植者很快感到幻滅。"},{"en":"Became disillusioned means stopped believing something was good after disappointment.","zh":"became disillusioned 指因失望而不再相信某事很好。"},{"en":"A student may become disillusioned with a course if promises do not match reality.","zh":"如果課程承諾與現實不符，學生可能對課程感到幻滅。"},{"en":"People become disillusioned when results are worse than expected.","zh":"當結果比預期差，人們會不再抱幻想。"},{"en":"This phrase describes loss of faith after experience.","zh":"這個短語描述經歷後失去信心。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":17},{"front":"costs soared","meaning":"成本急升","examples":[{"en":"Growers became disillusioned as costs soared.","zh":"隨著成本急升，種植者感到幻滅。"},{"en":"Costs soared means expenses rose very quickly and sharply.","zh":"costs soared 指開支非常迅速而大幅上升。"},{"en":"A family may struggle if rent and food costs soar at the same time.","zh":"如果租金和食物成本同時急升，家庭可能會吃力。"},{"en":"When costs soar, people may look for cheaper methods.","zh":"當成本急升，人們可能尋找較便宜方法。"},{"en":"This phrase describes a sudden and serious increase in expense.","zh":"這個短語描述開支突然且嚴重增加。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":17},{"front":"develop resistance to","meaning":"對……產生抗藥性","examples":[{"en":"Pests began to develop resistance to the chemicals.","zh":"害蟲開始對化學品產生抗藥性。"},{"en":"To develop resistance to something means to become less affected by it over time.","zh":"develop resistance to something 指隨時間變得較不受某物影響。"},{"en":"Bacteria may develop resistance to medicine if antibiotics are misused.","zh":"如果抗生素被濫用，細菌可能對藥物產生抗藥性。"},{"en":"Pests resist chemicals when weak individuals die but resistant ones survive.","zh":"當較弱個體死去而具抗性的個體存活，害蟲就會抵抗化學品。"},{"en":"This phrase explains why a treatment may stop working.","zh":"這個短語解釋治療或處理方法為何可能失效。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":17},{"front":"revive the old ant patrols","meaning":"恢復舊有螞蟻巡邏","examples":[{"en":"Growers began to revive the old ant patrols.","zh":"種植者開始恢復舊有螞蟻巡邏。"},{"en":"To revive the old ant patrols means to bring back the traditional use of ants for pest control.","zh":"revive the old ant patrols 指恢復傳統上用螞蟻防治害蟲的方法。"},{"en":"A school may revive an old reading club after students ask for it.","zh":"學生提出要求後，學校可能恢復舊閱讀會。"},{"en":"People revive old methods when newer methods become costly or harmful.","zh":"當新方法變得昂貴或有害，人們會恢復舊方法。"},{"en":"This phrase combines restoration with biological pest control.","zh":"這個短語結合恢復傳統與生物害蟲防治。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":17},{"front":"had good reason to","meaning":"有充分理由去……","examples":[{"en":"They had good reason to have faith in their ants.","zh":"他們有充分理由信任自己的螞蟻。"},{"en":"Had good reason to do something means had strong evidence or justification for doing it.","zh":"had good reason to do something 指有強而有力的證據或理由去做某事。"},{"en":"A parent has good reason to worry if a child is missing late at night.","zh":"如果孩子深夜失蹤，父母有充分理由擔心。"},{"en":"Farmers trusted ants because past experience showed they worked.","zh":"農民信任螞蟻，因為過往經驗顯示牠們有效。"},{"en":"This phrase shows that a belief is not random.","zh":"這個短語顯示信念不是隨機的。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":17},{"front":"insect workforce","meaning":"昆蟲勞動隊伍","examples":[{"en":"Growers had faith in their insect workforce.","zh":"種植者信任他們的昆蟲勞動隊伍。"},{"en":"An insect workforce is a group of insects doing useful work like a labour force.","zh":"insect workforce 指像勞動隊伍一樣做有用工作的昆蟲群。"},{"en":"Bees can be an insect workforce when they pollinate crops.","zh":"當蜜蜂為作物授粉時，牠們可以是昆蟲勞動隊伍。"},{"en":"Farmers trust an insect workforce when insects provide repeated practical benefits.","zh":"當昆蟲反覆提供實際好處，農民就會信任這支昆蟲勞動隊伍。"},{"en":"This phrase is a playful metaphor for helpful insects.","zh":"這個短語是對有益昆蟲的有趣比喻。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":17},{"front":"as long as","meaning":"只要……","examples":[{"en":"As long as there were enough ants, they controlled many pests.","zh":"只要有足夠螞蟻，牠們就能控制許多害蟲。"},{"en":"As long as means if and only while a condition is true.","zh":"as long as 指只要某條件成立。"},{"en":"You can borrow my notes as long as you return them tomorrow.","zh":"只要你明天歸還，我可以借你我的筆記。"},{"en":"Ant control worked only if the orchards had enough ants.","zh":"螞蟻防治只有在果園有足夠螞蟻時才有效。"},{"en":"This phrase introduces a condition.","zh":"這個短語引出條件。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":17},{"front":"did an excellent job of","meaning":"在……方面做得非常好","examples":[{"en":"The ants did an excellent job of dispatching larger pests.","zh":"螞蟻在消滅較大型害蟲方面做得非常好。"},{"en":"To do an excellent job of something means to do it very well.","zh":"do an excellent job of something 指某事做得非常好。"},{"en":"The class did an excellent job of cleaning the room after the event.","zh":"活動後，全班在清潔房間方面做得非常好。"},{"en":"Ants were valued because they performed pest control effectively.","zh":"螞蟻受到重視，是因為牠們有效進行害蟲防治。"},{"en":"This phrase praises successful performance.","zh":"這個短語讚揚成功表現。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":17},{"front":"dispatching","meaning":"消滅","examples":[{"en":"The ants were effective at dispatching some pests.","zh":"螞蟻能有效消滅一些害蟲。"},{"en":"Dispatching pests means killing or getting rid of them quickly.","zh":"dispatching pests 指迅速殺死或清除害蟲。"},{"en":"A gardener may use traps for dispatching rats in a store room.","zh":"園丁可能用陷阱消滅儲物室中的老鼠。"},{"en":"Predators dispatch pests by catching and eating them.","zh":"捕食者透過捕捉和吃掉害蟲來消滅牠們。"},{"en":"This word is a slightly formal or vivid way to say “kill”.","zh":"這個字是 “kill” 較正式或較生動的說法。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":17},{"front":"larger insects","meaning":"較大型昆蟲","examples":[{"en":"The ants mainly controlled the larger insects.","zh":"螞蟻主要控制較大型昆蟲。"},{"en":"Larger insects are insects bigger than the smaller pests being compared.","zh":"larger insects 指比被比較的小型害蟲更大的昆蟲。"},{"en":"A bird may eat larger insects such as beetles or grasshoppers.","zh":"鳥可能吃甲蟲或蚱蜢等較大型昆蟲。"},{"en":"Ants may control larger insects more easily than tiny scale insects.","zh":"螞蟻控制較大型昆蟲可能比控制細小介殼蟲更容易。"},{"en":"This phrase describes size within the insect group.","zh":"這個短語描述昆蟲群體中的大小。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":17},{"front":"modest success against","meaning":"對……有一定成效","examples":[{"en":"The ants had modest success against some other pests.","zh":"螞蟻對一些其他害蟲有一定成效。"},{"en":"Modest success against something means limited but real success in dealing with it.","zh":"modest success against something 指在處理某事上有有限但真實的成功。"},{"en":"A new study plan may have modest success against exam stress.","zh":"新學習計劃可能對考試壓力有一定成效。"},{"en":"Modest success is useful, but it may not solve the whole problem.","zh":"一定成效是有用的，但未必能解決整個問題。"},{"en":"This phrase gives careful, not exaggerated, praise.","zh":"這個短語給出謹慎而非誇張的讚賞。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":18},{"front":"healthy leaves","meaning":"健康葉片","examples":[{"en":"Trees with yellow ants produced more healthy leaves.","zh":"有黃蟻的樹長出更多健康葉片。"},{"en":"Healthy leaves are leaves that are green, strong, and not badly damaged.","zh":"healthy leaves 指綠色、強壯且沒有嚴重受損的葉子。"},{"en":"A plant with healthy leaves usually has enough light, water, and protection.","zh":"有健康葉片的植物通常有足夠陽光、水分和保護。"},{"en":"Healthy leaves help trees make food and produce fruit.","zh":"健康葉片幫助樹木製造養分並結果。"},{"en":"This phrase is a sign of good plant condition.","zh":"這個短語是植物狀況良好的標誌。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":18},{"front":"recent trials","meaning":"近期試驗","examples":[{"en":"Recent trials have shown that ant-protected trees yield large crops.","zh":"近期試驗顯示，受螞蟻保護的樹產量很大。"},{"en":"Recent trials are recent tests or experiments.","zh":"recent trials 指近期進行的測試或實驗。"},{"en":"Recent trials of a new teaching method may compare two classes.","zh":"一種新教學方法的近期試驗可能比較兩個班級。"},{"en":"Trials provide evidence because they test whether a method actually works.","zh":"試驗提供證據，因為它們測試方法是否真的有效。"},{"en":"This phrase connects modern testing with older farming practices.","zh":"這個短語把現代測試與舊農業做法連起來。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":18},{"front":"yield just as big a crop as","meaning":"產量與……一樣大","examples":[{"en":"Trees with ants yield just as big a crop as chemically protected trees.","zh":"有螞蟻的樹產量與受化學保護的樹一樣大。"},{"en":"To yield just as big a crop as another method means to produce the same harvest size.","zh":"yield just as big a crop as another method 指產生相同大小的收成。"},{"en":"A small garden may yield just as many tomatoes as a larger one if cared for well.","zh":"如果照顧得好，小花園產出的番茄可能與大花園一樣多。"},{"en":"Equal yield matters because cheaper or safer methods become more attractive.","zh":"產量相同很重要，因為較便宜或較安全的方法會更吸引。"},{"en":"This phrase compares production results.","zh":"這個短語比較生產結果。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":18},{"front":"protected by chemical sprays","meaning":"受化學噴劑保護","examples":[{"en":"Some trees were protected by expensive chemical sprays.","zh":"有些樹受昂貴化學噴劑保護。"},{"en":"Protected by chemical sprays means treated with sprayed chemicals to prevent pests or disease.","zh":"protected by chemical sprays 指用噴灑化學品處理，以防害蟲或疾病。"},{"en":"A farmer may spray vegetables to protect them from insects.","zh":"農民可能噴灑蔬菜，以保護它們免受昆蟲侵害。"},{"en":"Chemical sprays can protect crops but may cost money and affect the environment.","zh":"化學噴劑可以保護作物，但可能花錢並影響環境。"},{"en":"This phrase describes chemical pest control.","zh":"這個短語描述化學害蟲防治。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":18},{"front":"apparent drawback","meaning":"表面上的缺點","examples":[{"en":"One apparent drawback of using ants concerned mealy bugs.","zh":"使用螞蟻的一個表面缺點與粉蚧有關。"},{"en":"An apparent drawback is a disadvantage that seems to exist at first sight.","zh":"apparent drawback 指初看似乎存在的缺點。"},{"en":"Online learning has the apparent drawback of less face-to-face contact.","zh":"網上學習有較少面對面接觸這個表面缺點。"},{"en":"A drawback may be only apparent if later evidence shows the problem is smaller.","zh":"如果後來證據顯示問題較小，缺點可能只是表面上的。"},{"en":"This phrase invites readers to question an early negative impression.","zh":"這個短語邀請讀者質疑初步負面印象。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":18},{"front":"main reasons for","meaning":"……的主要原因之一","examples":[{"en":"This was one of the main reasons for Western scepticism.","zh":"這是西方懷疑態度的主要原因之一。"},{"en":"Main reasons for something are the most important causes behind it.","zh":"main reasons for something 指某事背後最重要的原因。"},{"en":"High cost is one of the main reasons for students choosing online lessons.","zh":"高成本是學生選擇網課的主要原因之一。"},{"en":"Knowing the main reasons helps explain people’s attitudes or decisions.","zh":"了解主要原因有助解釋人們的態度或決定。"},{"en":"This phrase identifies key causes, not minor details.","zh":"這個短語指出關鍵成因，而不是次要細節。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":18},{"front":"do nothing to control","meaning":"對控制……毫無作用","examples":[{"en":"Citrus ants do nothing to control mealy bugs.","zh":"柑橘蟻對控制粉蚧毫無作用。"},{"en":"To do nothing to control something means to have no effect in reducing or managing it.","zh":"do nothing to control something 指對減少或管理某事沒有作用。"},{"en":"A closed window does nothing to control noise if the glass is broken.","zh":"如果玻璃破了，關窗對控制噪音毫無作用。"},{"en":"If a method does nothing to control a pest, another solution is needed.","zh":"如果一種方法對控制害蟲毫無作用，就需要另一個解決方法。"},{"en":"This phrase strongly states lack of usefulness.","zh":"這個短語強烈表示沒有用處。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":18},{"front":"mealy bugs","meaning":"粉蚧","examples":[{"en":"Citrus ants do not control mealy bugs.","zh":"柑橘蟻不控制粉蚧。"},{"en":"Mealy bugs are small plant pests covered with a white waxy coating.","zh":"mealy bugs 是覆有白色蠟質的小型植物害蟲。"},{"en":"A gardener may find mealy bugs on leaves, stems, or fruit.","zh":"園丁可能在葉、莖或果實上發現粉蚧。"},{"en":"Mealy bugs damage plants by sucking sap.","zh":"粉蚧透過吸食樹液傷害植物。"},{"en":"This phrase names a common plant pest.","zh":"這個短語指一種常見植物害蟲。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":18},{"front":"waxy-coated scale insects","meaning":"覆有蠟質的介殼蟲","examples":[{"en":"Mealy bugs are waxy-coated scale insects.","zh":"粉蚧是覆有蠟質的介殼蟲。"},{"en":"Waxy-coated scale insects are small plant insects covered with a wax-like layer.","zh":"waxy-coated scale insects 指身上有蠟狀外層的小型植物昆蟲。"},{"en":"The waxy coat can protect insects from some sprays or predators.","zh":"蠟質外層可以保護昆蟲免受某些噴劑或捕食者傷害。"},{"en":"Scale insects damage plants by feeding on sap.","zh":"介殼蟲透過吸食樹液傷害植物。"},{"en":"This phrase describes both the body covering and insect type.","zh":"這個短語同時描述身體覆蓋物和昆蟲種類。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":18},{"front":"considerable damage","meaning":"相當大的損害","examples":[{"en":"Mealy bugs can do considerable damage to fruit trees.","zh":"粉蚧可以對果樹造成相當大的損害。"},{"en":"Considerable damage means serious or fairly large harm.","zh":"considerable damage 指嚴重或相當大的傷害。"},{"en":"A leaking roof can cause considerable damage to a classroom.","zh":"漏水屋頂可以對課室造成相當大的損害。"},{"en":"Pest damage becomes considerable when many leaves or fruits are affected.","zh":"當許多葉或果實受影響，害蟲傷害就變得相當大。"},{"en":"This phrase shows damage that is important enough to worry about.","zh":"這個短語顯示傷害大到值得擔心。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":19},{"front":"protect something in exchange for","meaning":"保護……以換取……","examples":[{"en":"The ants protect mealy bugs in exchange for honeydew.","zh":"螞蟻保護粉蚧，以換取蜜露。"},{"en":"To protect something in exchange for something else means to guard it because you receive a benefit.","zh":"protect something in exchange for something else 指因得到好處而保護某物。"},{"en":"A shop may advertise a brand in exchange for free products.","zh":"商店可能為品牌做宣傳，以換取免費產品。"},{"en":"Ants protect mealy bugs because they receive sweet honeydew from them.","zh":"螞蟻保護粉蚧，因為牠們從粉蚧得到甜蜜露。"},{"en":"This phrase describes a trade-like relationship.","zh":"這個短語描述一種像交易的關係。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":19},{"front":"sweet honeydew","meaning":"甜蜜露","examples":[{"en":"Mealy bugs secrete sweet honeydew.","zh":"粉蚧分泌甜蜜露。"},{"en":"Sweet honeydew is a sugary liquid produced by some sap-sucking insects.","zh":"sweet honeydew 是某些吸食樹液昆蟲產生的含糖液體。"},{"en":"Ants may gather around insects that produce sweet honeydew.","zh":"螞蟻可能聚集在會產生甜蜜露的昆蟲周圍。"},{"en":"Honeydew attracts ants because it gives them food.","zh":"蜜露會吸引螞蟻，因為它給牠們食物。"},{"en":"This phrase describes the reward ants receive from mealy bugs.","zh":"這個短語描述螞蟻從粉蚧得到的回報。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":19},{"front":"secrete","meaning":"分泌","examples":[{"en":"Mealy bugs secrete honeydew.","zh":"粉蚧分泌蜜露。"},{"en":"To secrete something means to produce and release a liquid substance.","zh":"secrete something 指產生並釋放液體物質。"},{"en":"Flowers may secrete nectar to attract insects.","zh":"花可能分泌花蜜來吸引昆蟲。"},{"en":"Insects secrete honeydew after feeding on plant sap.","zh":"昆蟲吸食植物汁液後會分泌蜜露。"},{"en":"This verb is often used in biology.","zh":"這個動詞常用於生物學。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":19},{"front":"denied this was a problem","meaning":"否認這是一個問題","examples":[{"en":"The orange growers denied this was a problem.","zh":"橙農否認這是一個問題。"},{"en":"Denied this was a problem means said that it was not really a problem.","zh":"denied this was a problem 指說這其實不是問題。"},{"en":"A manager may deny a delay is a problem until customers complain.","zh":"經理可能在顧客投訴前否認延誤是問題。"},{"en":"People deny problems when their experience suggests the issue is not serious.","zh":"當人們的經驗顯示問題不嚴重，他們可能否認它是問題。"},{"en":"This phrase shows disagreement with a criticism.","zh":"這個短語顯示對批評的不同意。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":19},{"front":"thought they knew better","meaning":"自以為更清楚","examples":[{"en":"Western scientists thought they knew better than the growers.","zh":"西方科學家自以為比種植者更清楚。"},{"en":"Thought they knew better means believed they understood the situation more correctly than others.","zh":"thought they knew better 指相信自己比別人更正確地理解情況。"},{"en":"A teenager may think they know better than their parents about sleep.","zh":"青少年可能自以為比父母更清楚睡眠問題。"},{"en":"People who think they know better may ignore local experience.","zh":"自以為更清楚的人可能忽視本地經驗。"},{"en":"This phrase often suggests overconfidence.","zh":"這個短語通常暗示過度自信。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":19},{"front":"right all along","meaning":"一直都是對的","examples":[{"en":"Research suggests that the growers were right all along.","zh":"研究顯示種植者一直都是對的。"},{"en":"Right all along means correct from the beginning, even when others doubted it.","zh":"right all along 指從一開始就是正確的，即使別人曾懷疑。"},{"en":"The quiet student was right all along about the answer.","zh":"那位安靜學生對答案一直都是對的。"},{"en":"Later evidence can show that local knowledge was correct from the start.","zh":"後來證據可以顯示本地知識從一開始就是正確的。"},{"en":"This phrase often corrects an earlier misunderstanding.","zh":"這個短語常用來修正早前誤解。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":19},{"front":"proliferate under","meaning":"在……下大量繁殖","examples":[{"en":"Mealy bugs may proliferate under the ants’ protection.","zh":"粉蚧可能在螞蟻保護下大量繁殖。"},{"en":"To proliferate under certain conditions means to multiply quickly because of those conditions.","zh":"proliferate under certain conditions 指因某些條件而快速繁殖。"},{"en":"Mould can proliferate under warm and damp conditions.","zh":"霉菌可以在溫暖潮濕條件下大量繁殖。"},{"en":"Mealy bugs may increase when ants protect them from enemies.","zh":"當螞蟻保護粉蚧免受天敵傷害，粉蚧可能增加。"},{"en":"This phrase links rapid growth with a supporting environment.","zh":"這個短語把快速增長與支持性環境連起來。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":19},{"front":"heavily parasitised","meaning":"被大量寄生","examples":[{"en":"The mealy bugs are usually heavily parasitised.","zh":"粉蚧通常被大量寄生。"},{"en":"Heavily parasitised means many parasites live on or inside the organism.","zh":"heavily parasitised 指許多寄生物生活在某生物身上或體內。"},{"en":"A fish may be heavily parasitised if many tiny parasites attach to its body.","zh":"如果許多小寄生物附在魚身上，那條魚可能被大量寄生。"},{"en":"Parasites can limit pest numbers by harming or killing their hosts.","zh":"寄生物可以透過傷害或殺死宿主來限制害蟲數量。"},{"en":"This phrase describes strong pressure from parasites.","zh":"這個短語描述來自寄生物的強大壓力。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":19},{"front":"limits the harm","meaning":"限制其危害","examples":[{"en":"Parasitism limits the harm that mealy bugs can do.","zh":"寄生作用限制了粉蚧能造成的危害。"},{"en":"To limit the harm means to reduce how much damage something can cause.","zh":"limit the harm 指減少某事能造成的傷害程度。"},{"en":"Wearing a seat belt limits the harm from a car accident.","zh":"戴安全帶可以限制車禍造成的傷害。"},{"en":"Natural enemies limit pest damage by keeping numbers lower.","zh":"天敵透過降低害蟲數量來限制其危害。"},{"en":"This phrase means reducing damage, not removing it completely.","zh":"這個短語意思是減少傷害，而不是完全消除傷害。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":19},{"front":"rely on","meaning":"依靠","examples":[{"en":"Some orange growers rely on carnivorous ants.","zh":"有些橙農依靠肉食性螞蟻。"},{"en":"To rely on something means to depend on it for help or success.","zh":"rely on something 指依靠某物取得幫助或成功。"},{"en":"Students may rely on dictionaries when reading difficult texts.","zh":"學生閱讀困難文本時，可能依靠字典。"},{"en":"Growers rely on ants when ants provide steady pest control.","zh":"當螞蟻提供穩定害蟲防治，種植者就會依靠牠們。"},{"en":"This phrase shows trust and dependence.","zh":"這個短語顯示信任和依賴。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":20},{"front":"carnivorous ants","meaning":"肉食性螞蟻","examples":[{"en":"Orange growers rely on carnivorous ants rather than chemicals.","zh":"橙農依靠肉食性螞蟻，而不是化學品。"},{"en":"Carnivorous ants are ants that eat other animals or insects.","zh":"carnivorous ants 指吃其他動物或昆蟲的螞蟻。"},{"en":"Carnivorous insects can help gardens by eating pests.","zh":"肉食性昆蟲可以透過吃害蟲來幫助花園。"},{"en":"Carnivorous ants protect crops when they hunt harmful insects.","zh":"肉食性螞蟻捕獵有害昆蟲時，就能保護農作物。"},{"en":"This phrase describes ants by what they eat.","zh":"這個短語按螞蟻吃甚麼來描述牠們。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":20},{"front":"rather than poisonous chemicals","meaning":"而不是有毒化學品","examples":[{"en":"Some growers use ants rather than poisonous chemicals.","zh":"有些種植者使用螞蟻，而不是有毒化學品。"},{"en":"Rather than poisonous chemicals means instead of harmful chemical substances.","zh":"rather than poisonous chemicals 指而不是使用有害化學物質。"},{"en":"A family may use soap and hot water rather than strong chemicals for simple cleaning.","zh":"家庭可能用肥皂和熱水清潔簡單污漬，而不是使用強效化學品。"},{"en":"Farmers choose ants when they want pest control with less chemical harm.","zh":"農民想要較少化學傷害的害蟲防治時，會選擇螞蟻。"},{"en":"This phrase contrasts a natural method with a toxic one.","zh":"這個短語把自然方法與有毒方法作對比。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":20},{"front":"maintain a better balance of species","meaning":"維持較好的物種平衡","examples":[{"en":"Ant-based orchards maintain a better balance of species.","zh":"以螞蟻為基礎的果園維持較好的物種平衡。"},{"en":"To maintain a better balance of species means to keep different organisms in healthier proportions.","zh":"maintain a better balance of species 指令不同生物保持較健康比例。"},{"en":"A pond with fish, plants, and insects needs a balance of species.","zh":"有魚、植物和昆蟲的池塘需要物種平衡。"},{"en":"Chemicals may kill many organisms, while natural control can leave more balance.","zh":"化學品可能殺死許多生物，而天然防治可以留下更多平衡。"},{"en":"This phrase describes ecological stability.","zh":"這個短語描述生態穩定。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":20},{"front":"deal with","meaning":"處理；對付","examples":[{"en":"The ants deal with the bigger insect pests.","zh":"螞蟻對付較大型害蟲。"},{"en":"To deal with something means to handle, manage, or solve it.","zh":"deal with something 指處理、管理或解決某事。"},{"en":"A teacher must deal with noise before learning can continue.","zh":"老師必須先處理噪音，學習才能繼續。"},{"en":"Ants deal with pests by hunting and killing them.","zh":"螞蟻透過捕獵和殺死害蟲來對付牠們。"},{"en":"This phrase is general and useful for many kinds of problems.","zh":"這個短語很通用，適合多種問題。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":20},{"front":"predatory species","meaning":"捕食性物種","examples":[{"en":"Other predatory species control smaller pests.","zh":"其他捕食性物種控制較小害蟲。"},{"en":"Predatory species are animals or insects that hunt and eat other organisms.","zh":"predatory species 指捕獵並吃其他生物的動物或昆蟲。"},{"en":"Spiders are predatory species that catch flies and mosquitoes.","zh":"蜘蛛是捕食性物種，會捕捉蒼蠅和蚊子。"},{"en":"Predatory species can keep pest numbers lower in a natural system.","zh":"捕食性物種可以在自然系統中降低害蟲數量。"},{"en":"This phrase is used in ecology and pest control.","zh":"這個短語用於生態學和害蟲防治。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":20},{"front":"keep down the numbers of","meaning":"控制……的數量","examples":[{"en":"Other predators keep down the numbers of smaller pests.","zh":"其他捕食者控制較小害蟲的數量。"},{"en":"To keep down the numbers of something means to prevent its population from becoming too large.","zh":"keep down the numbers of something 指防止某物數量變得太多。"},{"en":"Regular cleaning can keep down the number of cockroaches in a kitchen.","zh":"定期清潔可以控制廚房中蟑螂的數量。"},{"en":"Predators keep pest numbers down by eating them.","zh":"捕食者透過吃掉害蟲來控制其數量。"},{"en":"This phrase means control, not necessarily eliminate.","zh":"這個短語意思是控制，而不一定是消滅。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":20},{"front":"scale insects","meaning":"介殼蟲","examples":[{"en":"Scale insects can damage fruit trees.","zh":"介殼蟲可以傷害果樹。"},{"en":"Scale insects are small sap-sucking insects often protected by a hard or waxy covering.","zh":"scale insects 是小型吸食樹液昆蟲，通常有硬殼或蠟質覆蓋保護。"},{"en":"A gardener may notice scale insects as tiny bumps on stems.","zh":"園丁可能在莖上看到像小凸點的介殼蟲。"},{"en":"Scale insects weaken plants by taking sap from them.","zh":"介殼蟲透過吸食樹液削弱植物。"},{"en":"This phrase names a group of plant pests.","zh":"這個短語指一類植物害蟲。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":20},{"front":"aphids","meaning":"蚜蟲","examples":[{"en":"Other predatory species control aphids.","zh":"其他捕食性物種控制蚜蟲。"},{"en":"Aphids are small insects that suck sap from plants.","zh":"aphids 是吸食植物汁液的小昆蟲。"},{"en":"Ladybirds often eat aphids in gardens.","zh":"瓢蟲常在花園中吃蚜蟲。"},{"en":"Aphids can multiply quickly and damage young shoots.","zh":"蚜蟲可以快速繁殖並傷害嫩芽。"},{"en":"This word names a common soft-bodied plant pest.","zh":"這個字指一種常見的軟體植物害蟲。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":20},{"front":"in the long run","meaning":"長遠來說","examples":[{"en":"In the long run, ants do less damage than chemicals.","zh":"長遠來說，螞蟻造成的損害比化學品少。"},{"en":"In the long run means over a long period, not immediately.","zh":"in the long run 指長時間來看，而不是立即。"},{"en":"Exercising regularly saves health costs in the long run.","zh":"定期運動長遠來說可以節省醫療成本。"},{"en":"A method may seem slow at first but become better over time.","zh":"一種方法起初可能看似慢，但隨時間變得更好。"},{"en":"This phrase encourages looking beyond short-term results.","zh":"這個短語鼓勵人們超越短期結果去看。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":20},{"front":"do a lot less damage than","meaning":"比……造成少得多的損害","examples":[{"en":"Ants do a lot less damage than chemicals.","zh":"螞蟻比化學品造成少得多的損害。"},{"en":"To do a lot less damage than something means to cause much less harm.","zh":"do a lot less damage than something 指造成的傷害少很多。"},{"en":"Taking the train may do less damage to the environment than driving alone.","zh":"乘火車可能比獨自駕車對環境造成較少損害。"},{"en":"Natural pest control may harm fewer species than broad chemical spraying.","zh":"天然害蟲防治可能比廣泛噴灑化學品傷害更少物種。"},{"en":"This phrase compares the seriousness of harm.","zh":"這個短語比較傷害的嚴重程度。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":21},{"front":"more effective than","meaning":"比……更有效","examples":[{"en":"Ants are more effective than excommunication.","zh":"螞蟻比逐出教會更有效。"},{"en":"More effective than means works better than another method.","zh":"more effective than 指比另一種方法更有效。"},{"en":"Clear feedback is more effective than vague praise for improving writing.","zh":"清楚回饋比空泛讚美更能有效改善寫作。"},{"en":"Practical action is more effective than symbolic action when crops are being destroyed.","zh":"當農作物被摧毀時，實際行動比象徵性行動更有效。"},{"en":"This phrase compares usefulness or results.","zh":"這個短語比較有用程度或結果。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":21},{"front":"excommunication","meaning":"逐出教會","examples":[{"en":"The passage jokes that ants are more effective than excommunication.","zh":"文章開玩笑說螞蟻比逐出教會更有效。"},{"en":"Excommunication is official removal from a religious community.","zh":"excommunication 指被正式逐出宗教群體。"},{"en":"In history, excommunication could be used as a serious religious punishment.","zh":"在歷史中，逐出教會可以作為嚴重宗教懲罰。"},{"en":"Excommunication cannot literally control insects, so the comparison is humorous.","zh":"逐出教會不能真的控制昆蟲，所以這個比較帶幽默感。"},{"en":"This word belongs to religion, not farming, which creates the joke.","zh":"這個字屬於宗教而非農業，因此產生笑點。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":21},{"front":"look at the following events","meaning":"查看以下事件","examples":[{"en":"Students should look at the following events and match them with dates.","zh":"學生應查看以下事件，並把它們與日期配對。"},{"en":"Look at the following events means read the listed events below.","zh":"look at the following events 指閱讀下方列出的事件。"},{"en":"In a history task, students look at events before arranging them on a timeline.","zh":"在歷史題中，學生會先查看事件，再把它們排列在時間線上。"},{"en":"Reading the events carefully helps students find the correct time references.","zh":"仔細閱讀事件有助學生找到正確時間提示。"},{"en":"This instruction tells students what information to examine first.","zh":"這個指示告訴學生應先查看哪些資訊。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":21},{"front":"list of dates","meaning":"日期列表","examples":[{"en":"The list of dates provides possible answers for the matching task.","zh":"日期列表提供配對題的可能答案。"},{"en":"A list of dates is a set of time options given in a question.","zh":"list of dates 指題目中提供的一組時間選項。"},{"en":"Students may compare each event with the list of dates.","zh":"學生可能把每個事件與日期列表作比較。"},{"en":"A date list helps organise historical information clearly.","zh":"日期列表有助清楚整理歷史資訊。"},{"en":"This phrase is common in timeline matching questions.","zh":"這個短語常見於時間線配對題。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":21},{"front":"match each event with","meaning":"將每個事件與……配對","examples":[{"en":"Students match each event with the correct time.","zh":"學生將每個事件與正確時間配對。"},{"en":"To match each event with something means to connect every event to the right answer.","zh":"match each event with something 指把每個事件連接到正確答案。"},{"en":"In a reading test, students may match discoveries with dates.","zh":"在閱讀測驗中，學生可能要把發現與日期配對。"},{"en":"Matching requires evidence from the passage, not guessing.","zh":"配對需要文章證據，而不是猜測。"},{"en":"This phrase describes a common exam task.","zh":"這個短語描述常見考試任務。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":21},{"front":"correct time","meaning":"正確時間","examples":[{"en":"Each event should be matched with the correct time.","zh":"每個事件都應與正確時間配對。"},{"en":"The correct time is the date or period that accurately matches an event.","zh":"correct time 指與事件準確相符的日期或時期。"},{"en":"Students should check paragraph clues to find the correct time.","zh":"學生應查看段落提示來找出正確時間。"},{"en":"Choosing the wrong time can change the meaning of historical development.","zh":"選錯時間可能改變歷史發展的意思。"},{"en":"This phrase focuses on accurate chronology.","zh":"這個短語集中於準確年代順序。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":21},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Students write the correct letter in the answer boxes.","zh":"學生在答案框中寫上正確字母。"},{"en":"To write the correct letter means to enter the option letter that matches the answer.","zh":"write the correct letter 指填入與答案相符的選項字母。"},{"en":"In matching questions, students must copy the correct letter carefully.","zh":"在配對題中，學生必須小心抄寫正確字母。"},{"en":"A right idea can still lose marks if the letter is copied wrongly.","zh":"即使想法正確，如果字母抄錯仍可能失分。"},{"en":"This phrase reminds students to follow the answer format.","zh":"這個短語提醒學生遵守答案格式。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":21},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"The answers should be written on the answer sheet.","zh":"答案應寫在答題紙上。"},{"en":"An answer sheet is the official paper or form where exam answers are recorded.","zh":"answer sheet 指記錄考試答案的正式紙張或表格。"},{"en":"Students should transfer answers to the answer sheet before time ends.","zh":"學生應在時間結束前把答案轉填到答題紙上。"},{"en":"Answers in the question booklet may not count if the answer sheet is blank.","zh":"如果答題紙空白，題簿上的答案可能不算。"},{"en":"This phrase is important for exam instructions.","zh":"這個短語對考試指示很重要。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":21},{"front":"earliest description of","meaning":"最早對……的描述","examples":[{"en":"The question asks for the earliest description of citrus ants being traded.","zh":"題目問最早對柑橘蟻被買賣的描述。"},{"en":"The earliest description of something is the first known account of it.","zh":"earliest description of something 指目前已知最早的記述。"},{"en":"Historians look for the earliest description of a practice to date its origin.","zh":"歷史學家尋找某做法的最早描述，以確定其起源時間。"},{"en":"An early description can show how long people have known about something.","zh":"早期描述可以顯示人們知道某事已有多久。"},{"en":"This phrase is useful for historical evidence.","zh":"這個短語適合用於歷史證據。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":21},{"front":"being traded in a marketplace","meaning":"在市場中被買賣","examples":[{"en":"Citrus ants were described as being traded in a marketplace.","zh":"柑橘蟻被描述為在市場中被買賣。"},{"en":"Being traded in a marketplace means being bought and sold in a market.","zh":"being traded in a marketplace 指在市場中被購買和出售。"},{"en":"Handmade baskets may be traded in a marketplace every weekend.","zh":"手工籃子可能每週末在市場中被買賣。"},{"en":"If ants were traded in markets, they had economic value.","zh":"如果螞蟻在市場中被買賣，就表示牠們有經濟價值。"},{"en":"This phrase shows that the item was part of commerce.","zh":"這個短語顯示該物品是商業活動的一部分。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":22},{"front":"travelled to China for research","meaning":"前往中國進行研究","examples":[{"en":"Swingle travelled to China for research on citrus disease.","zh":"Swingle 前往中國進行柑橘疾病研究。"},{"en":"Travelled to China for research means went to China to study a topic carefully.","zh":"travelled to China for research 指前往中國仔細研究某主題。"},{"en":"A scientist may travel abroad for research when local samples are not enough.","zh":"當本地樣本不足時，科學家可能前往海外進行研究。"},{"en":"Research trips allow people to observe problems directly.","zh":"研究旅程讓人直接觀察問題。"},{"en":"This phrase gives both the journey and its purpose.","zh":"這個短語同時交代旅程和目的。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":22},{"front":"first recorded Western use of","meaning":"西方首次有記錄使用……","examples":[{"en":"The question asks for the first recorded Western use of biological control.","zh":"題目問西方首次有記錄使用生物防治。"},{"en":"First recorded Western use of something means the earliest written Western example of using it.","zh":"first recorded Western use of something 指西方最早書面記錄使用某物的例子。"},{"en":"Historians may search for the first recorded use of a medical tool.","zh":"歷史學家可能尋找某醫療工具的首次有記錄使用。"},{"en":"A recorded first may not be the true first if older examples exist elsewhere.","zh":"有記錄的首次未必是真正首次，因為其他地方可能有更早例子。"},{"en":"This phrase focuses on documented history in the West.","zh":"這個短語集中於西方有文獻記錄的歷史。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":22},{"front":"one insect to control another","meaning":"用一種昆蟲控制另一種昆蟲","examples":[{"en":"Biological control may use one insect to control another.","zh":"生物防治可以用一種昆蟲控制另一種昆蟲。"},{"en":"One insect to control another means using a predator or parasite insect against a pest insect.","zh":"one insect to control another 指使用捕食或寄生昆蟲對付害蟲。"},{"en":"Farmers may use ladybirds to control aphids.","zh":"農民可能用瓢蟲控制蚜蟲。"},{"en":"This method works when the helpful insect reduces the harmful insect’s numbers.","zh":"當有益昆蟲減少有害昆蟲數量時，這種方法就有效。"},{"en":"The phrase explains the basic idea of biological control.","zh":"這個短語解釋生物防治的基本概念。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":22},{"front":"replacing citrus ants with pesticides","meaning":"以農藥取代柑橘蟻","examples":[{"en":"Some Chinese growers began replacing citrus ants with pesticides.","zh":"有些中國種植者開始以農藥取代柑橘蟻。"},{"en":"Replacing citrus ants with pesticides means stopping ant use and using chemical pest control instead.","zh":"replacing citrus ants with pesticides 指停止使用螞蟻，改用化學害蟲防治。"},{"en":"A farmer may replace hand watering with sprinklers to save time.","zh":"農民可能用灑水器取代手動澆水，以節省時間。"},{"en":"Replacement happens when people believe a new method is better or easier.","zh":"當人們相信新方法更好或更容易，就會出現取代。"},{"en":"This phrase describes the shift from biological to chemical control.","zh":"這個短語描述從生物防治轉向化學防治。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":22},{"front":"pesticides","meaning":"農藥","examples":[{"en":"Growers replaced citrus ants with pesticides.","zh":"種植者用農藥取代柑橘蟻。"},{"en":"Pesticides are chemicals used to kill or control pests.","zh":"pesticides 是用來殺死或控制害蟲的化學品。"},{"en":"Farmers may spray pesticides when insects attack crops.","zh":"當昆蟲侵害農作物時，農民可能噴灑農藥。"},{"en":"Overusing pesticides can lead to resistance and environmental damage.","zh":"過度使用農藥可以導致抗藥性和環境破壞。"},{"en":"This word is central in discussions of chemical pest control.","zh":"這個字在化學害蟲防治討論中很核心。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":22},{"front":"returned to","meaning":"回復到……","examples":[{"en":"Some growers returned to the traditional biological method.","zh":"有些種植者回復到傳統生物方法。"},{"en":"Returned to something means went back to using or doing it again.","zh":"returned to something 指重新回到使用或做某事。"},{"en":"A student may return to paper notes after finding apps distracting.","zh":"學生發現應用程式令人分心後，可能回復到紙本筆記。"},{"en":"People return to old methods when new methods fail.","zh":"當新方法失敗，人們會回復到舊方法。"},{"en":"This phrase describes going back after a change.","zh":"這個短語描述改變後回到原來做法。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":22},{"front":"traditional biological method","meaning":"傳統生物方法","examples":[{"en":"The traditional biological method used citrus ants.","zh":"傳統生物方法使用柑橘蟻。"},{"en":"A traditional biological method is an older natural way of controlling pests with living organisms.","zh":"traditional biological method 指用生物控制害蟲的較古老天然方法。"},{"en":"Farmers may use ducks in rice fields as a traditional biological method.","zh":"農民可能在稻田中使用鴨作為傳統生物方法。"},{"en":"Such methods can survive because they are practical and low-cost.","zh":"這類方法可以延續，因為它們實用且成本低。"},{"en":"This phrase contrasts old natural pest control with modern chemicals.","zh":"這個短語把古老天然害蟲防治與現代化學品作對比。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":22},{"front":"do the following statements agree with","meaning":"以下陳述是否與文章一致","examples":[{"en":"Students decide whether the statements agree with the passage.","zh":"學生判斷以下陳述是否與文章一致。"},{"en":"Do the following statements agree with means check if each statement matches the text.","zh":"do the following statements agree with 指檢查每項陳述是否與文本相符。"},{"en":"In reading exams, students should not answer from outside knowledge.","zh":"在閱讀考試中，學生不應根據外部知識作答。"},{"en":"A statement agrees with the passage only when the passage supports it clearly.","zh":"只有當文章清楚支持某陳述時，它才與文章一致。"},{"en":"This phrase introduces True, False, Not Given questions.","zh":"這個短語引出 True, False, Not Given 題。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":22},{"front":"information given in","meaning":"……中提供的資料","examples":[{"en":"The answers must match the information given in the passage.","zh":"答案必須符合篇章中提供的資料。"},{"en":"Information given in a text means details directly stated or supported there.","zh":"information given in a text 指文本中直接說明或支持的細節。"},{"en":"Students should answer according to the information given in the article.","zh":"學生應根據文章中提供的資料作答。"},{"en":"If information is not given, students should not assume it is true.","zh":"如果資料沒有提供，學生不應假設它是真的。"},{"en":"This phrase reminds readers to rely on the text.","zh":"這個短語提醒讀者依據文本。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":22},{"front":"if the statement agrees with","meaning":"如果陳述與……一致","examples":[{"en":"Write TRUE if the statement agrees with the information.","zh":"如果陳述與資料一致，寫 TRUE。"},{"en":"If the statement agrees with means if the statement matches what the text says.","zh":"if the statement agrees with 指如果陳述與文本所說相符。"},{"en":"Students write TRUE only when the passage clearly supports the statement.","zh":"只有當文章清楚支持該陳述時，學生才寫 TRUE。"},{"en":"A statement may sound logical but not agree with the text.","zh":"一項陳述可能聽起來合理，但不一定與文本一致。"},{"en":"This phrase explains the condition for choosing TRUE.","zh":"這個短語解釋選擇 TRUE 的條件。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":23},{"front":"if the statement contradicts","meaning":"如果陳述與……相矛盾","examples":[{"en":"Write FALSE if the statement contradicts the information.","zh":"如果陳述與資料相矛盾，寫 FALSE。"},{"en":"If the statement contradicts means if it says the opposite of what the text says.","zh":"if the statement contradicts 指如果它說出與文本相反的意思。"},{"en":"Students write FALSE when the passage clearly disagrees with the statement.","zh":"當文章清楚不支持並反對該陳述時，學生寫 FALSE。"},{"en":"A contradiction must be based on evidence, not personal feeling.","zh":"矛盾必須基於證據，而不是個人感覺。"},{"en":"This phrase explains the condition for choosing FALSE.","zh":"這個短語解釋選擇 FALSE 的條件。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":23},{"front":"there is no information on this","meaning":"沒有這方面的資料","examples":[{"en":"Write NOT GIVEN if there is no information on this.","zh":"如果沒有這方面的資料，寫 NOT GIVEN。"},{"en":"There is no information on this means the passage does not say enough about it.","zh":"there is no information on this 指文章沒有提供足夠相關資料。"},{"en":"If a text mentions a farmer but not his age, there is no information on his age.","zh":"如果文本提到一位農民但沒有提到他的年齡，就沒有關於年齡的資料。"},{"en":"Students should choose NOT GIVEN when the answer cannot be proved or disproved.","zh":"當答案不能被證明或推翻時，學生應選 NOT GIVEN。"},{"en":"This phrase prevents guessing beyond the passage.","zh":"這個短語防止學生超出文章猜測。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":23},{"front":"more citrus pests than","meaning":"比……有更多柑橘害蟲","examples":[{"en":"The statement asks whether China has more citrus pests than any other country.","zh":"該陳述問中國是否比任何其他國家有更多柑橘害蟲。"},{"en":"More citrus pests than another place means a larger number or variety of citrus pests.","zh":"more citrus pests than another place 指比另一地方有更多數量或種類的柑橘害蟲。"},{"en":"A warm region may have more crop pests than a cold region.","zh":"溫暖地區可能比寒冷地區有更多作物害蟲。"},{"en":"More pests create greater need for effective pest control.","zh":"更多害蟲會造成對有效害蟲防治的更大需要。"},{"en":"This phrase is used for comparison.","zh":"這個短語用於比較。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":23},{"front":"find an insect","meaning":"尋找一種昆蟲","examples":[{"en":"The statement asks whether Swingle went to China to find an insect.","zh":"該陳述問 Swingle 是否前往中國尋找一種昆蟲。"},{"en":"To find an insect means to search for and discover a particular insect.","zh":"find an insect 指搜尋並發現某種昆蟲。"},{"en":"A student may go into the garden to find an insect for a biology project.","zh":"學生可能到花園尋找一種昆蟲，用於生物專題。"},{"en":"In the passage, Swingle went to find resistant oranges, not an insect.","zh":"在文章中，Swingle 是去尋找抗病橙，而不是昆蟲。"},{"en":"This phrase is simple, but exact purpose matters in reading questions.","zh":"這個短語很簡單，但在閱讀題中準確目的很重要。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":23},{"front":"taken back to","meaning":"被帶回……","examples":[{"en":"The insect would have been taken back to the United States.","zh":"這種昆蟲本會被帶回美國。"},{"en":"Taken back to a place means brought back to that place.","zh":"taken back to a place 指被帶回某地。"},{"en":"A borrowed book should be taken back to the library.","zh":"借來的書應被帶回圖書館。"},{"en":"In research, samples may be taken back to a laboratory for testing.","zh":"在研究中，樣本可能被帶回實驗室測試。"},{"en":"This phrase describes returning or transporting something back.","zh":"這個短語描述返回或運送回去。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":23},{"front":"were impressed by","meaning":"對……印象深刻","examples":[{"en":"The statement asks whether Western biologists were impressed by Swingle’s discovery.","zh":"該陳述問西方生物學家是否對 Swingle 的發現印象深刻。"},{"en":"Were impressed by means felt admiration or strong interest because of something.","zh":"were impressed by 指因某事而感到欣賞或強烈興趣。"},{"en":"Parents were impressed by the student’s confident speech.","zh":"父母對學生自信的演講印象深刻。"},{"en":"People may not be impressed if they doubt the evidence.","zh":"如果人們懷疑證據，就未必會留下深刻印象。"},{"en":"This phrase describes a positive reaction.","zh":"這個短語描述正面反應。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":23},{"front":"increasingly expensive","meaning":"越來越昂貴","examples":[{"en":"Chinese farmers found that pesticides became increasingly expensive.","zh":"中國農民發現農藥變得越來越昂貴。"},{"en":"Increasingly expensive means becoming more and more costly.","zh":"increasingly expensive 指變得越來越高成本。"},{"en":"Private lessons can become increasingly expensive in popular exam seasons.","zh":"私人課堂在熱門考試季節可能變得越來越昂貴。"},{"en":"When something becomes increasingly expensive, people may search for cheaper alternatives.","zh":"當某物越來越昂貴，人們可能尋找較便宜替代方法。"},{"en":"This phrase describes a rising cost over time.","zh":"這個短語描述成本隨時間上升。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":23},{"front":"abandoned pesticides","meaning":"放棄農藥","examples":[{"en":"Some Chinese farmers abandoned pesticides and returned to ants.","zh":"有些中國農民放棄農藥並回復使用螞蟻。"},{"en":"Abandoned pesticides means stopped using chemical pest killers.","zh":"abandoned pesticides 指停止使用化學殺蟲劑。"},{"en":"A gardener may abandon pesticides after finding a safer natural method.","zh":"園丁找到較安全的天然方法後，可能放棄農藥。"},{"en":"Farmers abandon a method when it becomes costly or ineffective.","zh":"當一種方法變得昂貴或無效，農民會放棄它。"},{"en":"This phrase shows a move away from chemical control.","zh":"這個短語顯示遠離化學防治。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":23},{"front":"lost more leaves than","meaning":"比……失去更多葉","examples":[{"en":"The statement compares whether trees with ants lost more leaves than trees without ants.","zh":"該陳述比較有螞蟻的樹是否比沒有螞蟻的樹失去更多葉。"},{"en":"Lost more leaves than means had a greater number of leaves fall or be damaged.","zh":"lost more leaves than 指有更多葉掉落或受損。"},{"en":"A plant in the dark may lose more leaves than one near a window.","zh":"放在暗處的植物可能比靠窗植物失去更多葉。"},{"en":"Leaf loss matters because leaves help trees make food.","zh":"葉片損失很重要，因為葉幫助樹製造養分。"},{"en":"This phrase compares plant health between two groups.","zh":"這個短語比較兩組植物健康狀況。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":23},{"front":"as large as","meaning":"與……一樣大","examples":[{"en":"Ant-protected orchards can produce crops as large as chemically protected orchards.","zh":"受螞蟻保護的果園可以產出與受化學保護果園一樣大的作物。"},{"en":"As large as means equal in size or amount.","zh":"as large as 指大小或數量相等。"},{"en":"A small class can achieve results as strong as a large school with good teaching.","zh":"如果教學良好，小班也可以取得與大型學校一樣強的成果。"},{"en":"If crops are as large as before, farmers may trust the method.","zh":"如果收成與以前一樣大，農民可能信任該方法。"},{"en":"This phrase is used for equality in size, amount, or scale.","zh":"這個短語用於表示大小、數量或規模相等。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":24},{"front":"chemical pesticides","meaning":"化學農藥","examples":[{"en":"Some orchards are protected by chemical pesticides.","zh":"有些果園受化學農藥保護。"},{"en":"Chemical pesticides are man-made substances used to kill or control pests.","zh":"chemical pesticides 指用來殺死或控制害蟲的人造化學物質。"},{"en":"Farmers may use chemical pesticides when natural control is not enough.","zh":"當天然防治不足時，農民可能使用化學農藥。"},{"en":"Overuse of chemical pesticides can harm other species and create resistance.","zh":"過度使用化學農藥可以傷害其他物種並造成抗藥性。"},{"en":"This phrase contrasts with biological pest control.","zh":"這個短語與生物害蟲防治形成對比。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":24},{"front":"environmental damage","meaning":"環境破壞","examples":[{"en":"The statement asks whether citrus ants cause environmental damage.","zh":"該陳述問柑橘蟻是否造成環境破壞。"},{"en":"Environmental damage means harm to air, water, soil, plants, animals, or ecosystems.","zh":"environmental damage 指對空氣、水、泥土、植物、動物或生態系統的傷害。"},{"en":"Plastic waste can cause environmental damage when it enters rivers.","zh":"膠廢物進入河流時，可以造成環境破壞。"},{"en":"Farming methods are judged partly by how much environmental damage they cause.","zh":"農業方法會部分按其造成多少環境破壞來判斷。"},{"en":"This phrase is used when discussing harm to nature.","zh":"這個短語用於討論對自然的傷害。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":24},{"front":"cause considerable environmental damage","meaning":"造成相當大的環境破壞","examples":[{"en":"The statement asks whether citrus ants cause considerable environmental damage.","zh":"該陳述問柑橘蟻是否造成相當大的環境破壞。"},{"en":"To cause considerable environmental damage means to create serious harm to nature.","zh":"cause considerable environmental damage 指對自然造成嚴重傷害。"},{"en":"A factory leak can cause considerable environmental damage if chemicals enter a river.","zh":"如果化學品進入河流，工廠洩漏可以造成相當大的環境破壞。"},{"en":"Chemical pest control may cause environmental damage if it kills helpful species.","zh":"如果化學害蟲防治殺死有益物種，可能造成環境破壞。"},{"en":"This phrase describes serious ecological harm, not a small effect.","zh":"這個短語描述嚴重生態傷害，而不是小影響。"}],"source":"28 - The Ant and the Mandarin.pdf","sourcePage":24}],"ielts/reading/passage-2/Practice 29":[{"front":"children’s literature","meaning":"兒童文學","examples":[{"en":"The passage traces the development of children’s literature over several centuries.","zh":"文章追溯了兒童文學在幾個世紀中的發展。"},{"en":"Children’s literature means stories, poems, and books written for children or commonly read by children.","zh":"Children’s literature 指為兒童而寫，或常由兒童閱讀的故事、詩歌和書籍。"},{"en":"Fairy tales, picture books, nursery rhymes, and adventure stories can all belong to children’s literature.","zh":"童話、圖畫書、童謠和冒險故事都可以屬於兒童文學。"},{"en":"As children’s needs changed, children’s literature became more entertaining, child-centred, and realistic.","zh":"隨着兒童需要改變，兒童文學變得更具娛樂性、更以兒童為中心，也更貼近現實。"},{"en":"This phrase refers to literature for young readers, not simply books with children in them.","zh":"這個片語指面向年輕讀者的文學，而不只是有兒童角色的書。"}],"source":"29 - Children’s Literature.pdf","sourcePage":1},{"front":"be aimed at","meaning":"以……為對象","examples":[{"en":"Stories and poems aimed at children have a very long history.","zh":"以兒童為對象的故事和詩歌有非常悠久的歷史。"},{"en":"To be aimed at someone means to be designed for that person or group.","zh":"To be aimed at someone 指為某人或某群體而設計。"},{"en":"A beginner grammar book is aimed at students who need simple explanations.","zh":"初級文法書是以需要簡單解釋的學生為對象。"},{"en":"If a story is aimed at children, the language, characters, and themes are usually easier to follow.","zh":"如果故事以兒童為對象，語言、角色和主題通常較容易理解。"},{"en":"This phrase shows the intended audience of a book, lesson, product, or message.","zh":"這個片語顯示書本、課堂、產品或訊息的目標對象。"}],"source":"29 - Children’s Literature.pdf","sourcePage":1},{"front":"exceedingly long history","meaning":"極其悠久的歷史","examples":[{"en":"Stories and poems for children have an exceedingly long history.","zh":"兒童故事和詩歌有極其悠久的歷史。"},{"en":"An exceedingly long history means a history that is extremely long and goes far back in time.","zh":"Exceedingly long history 指歷史極長，並可追溯到很久以前。"},{"en":"Tea drinking has an exceedingly long history in many Asian cultures.","zh":"飲茶在許多亞洲文化中有極其悠久的歷史。"},{"en":"If a custom has an exceedingly long history, people may treat it as part of their cultural identity.","zh":"如果一項習俗有極其悠久的歷史，人們可能把它視為文化身份的一部分。"},{"en":"This phrase emphasises that something is not new at all.","zh":"這個片語強調某事完全不是新事物。"}],"source":"29 - Children’s Literature.pdf","sourcePage":1},{"front":"lullabies","meaning":"搖籃曲","examples":[{"en":"Lullabies were sung in Roman times.","zh":"搖籃曲在羅馬時代已被歌唱。"},{"en":"Lullabies are gentle songs sung to help babies or young children sleep.","zh":"Lullabies 是用來幫助嬰兒或幼童入睡的溫柔歌曲。"},{"en":"A parent may sing lullabies softly when a baby is crying at night.","zh":"當嬰兒晚上哭泣時，父母可能輕聲唱搖籃曲。"},{"en":"Because lullabies calm children, they often use slow rhythm and simple words.","zh":"因為搖籃曲能安撫孩子，它們通常使用緩慢節奏和簡單字詞。"},{"en":"This word refers to sleep songs for very young children.","zh":"這個詞指給非常年幼兒童聽的睡眠歌曲。"}],"source":"29 - Children’s Literature.pdf","sourcePage":1},{"front":"Roman times","meaning":"羅馬時代","examples":[{"en":"Lullabies were already sung in Roman times.","zh":"搖籃曲在羅馬時代已經有人唱。"},{"en":"Roman times means the historical period when ancient Rome was powerful and influential.","zh":"Roman times 指古羅馬強大且有影響力的歷史時期。"},{"en":"Some roads, laws, and buildings from Roman times still influence Europe today.","zh":"一些源自羅馬時代的道路、法律和建築至今仍影響歐洲。"},{"en":"If a practice existed in Roman times, it has survived for many centuries.","zh":"如果一種做法在羅馬時代已存在，它就延續了許多世紀。"},{"en":"This phrase helps place something in the ancient past.","zh":"這個片語幫助把某事定位於古代過去。"}],"source":"29 - Children’s Literature.pdf","sourcePage":1},{"front":"nursery games and rhymes","meaning":"兒童遊戲和童謠","examples":[{"en":"Some nursery games and rhymes are almost ancient.","zh":"一些兒童遊戲和童謠幾乎十分古老。"},{"en":"Nursery games and rhymes are simple games, chants, and short poems used with very young children.","zh":"Nursery games and rhymes 是與幼童一起使用的簡單遊戲、吟唱和短詩。"},{"en":"Children may learn counting through nursery games and rhymes at home or school.","zh":"兒童可能在家中或學校透過兒童遊戲和童謠學習數數。"},{"en":"Because they are easy to repeat, nursery rhymes can pass from one generation to the next.","zh":"因為童謠容易重複，它們可以一代傳一代。"},{"en":"This phrase refers to playful language and activities for young children.","zh":"這個片語指為幼童而設的遊戲式語言和活動。"}],"source":"29 - Children’s Literature.pdf","sourcePage":1},{"front":"almost as ancient","meaning":"幾乎同樣古老","examples":[{"en":"A few nursery games and rhymes are almost as ancient.","zh":"一些兒童遊戲和童謠幾乎同樣古老。"},{"en":"Almost as ancient means nearly as old as something from the very distant past.","zh":"Almost as ancient 指幾乎像遠古事物一樣古老。"},{"en":"Some family recipes feel almost as ancient as the festivals they are cooked for.","zh":"有些家庭食譜感覺幾乎與它們所屬的節日同樣古老。"},{"en":"If a rhyme is almost as ancient as Roman songs, it has lasted an extremely long time.","zh":"如果一首童謠幾乎與羅馬歌曲同樣古老，它就流傳了極長時間。"},{"en":"This phrase compares age and suggests something is very old.","zh":"這個片語比較年代，並暗示某事非常古老。"}],"source":"29 - Children’s Literature.pdf","sourcePage":1},{"front":"so far as…is concerned","meaning":"就……而言","examples":[{"en":"So far as written-down literature is concerned, children had few books before 1700.","zh":"就寫成文字的文學而言，1700年前兒童可讀的書很少。"},{"en":"So far as something is concerned means when we are talking about that particular thing.","zh":"So far as something is concerned 指當我們談論某特定事物時。"},{"en":"So far as homework is concerned, quality matters more than simply writing many pages.","zh":"就功課而言，質素比單純寫很多頁更重要。"},{"en":"If a writer says “so far as printed books are concerned”, they are limiting the discussion to printed books.","zh":"如果作者說 “so far as printed books are concerned”，他就是把討論限制在印刷書上。"},{"en":"This phrase narrows the topic before making a point.","zh":"這個片語在提出重點前收窄討論範圍。"}],"source":"29 - Children’s Literature.pdf","sourcePage":1},{"front":"written-down literature","meaning":"寫成文字的文學","examples":[{"en":"Written-down literature for children was limited before 1700.","zh":"1700年前，兒童的寫成文字的文學很有限。"},{"en":"Written-down literature means stories, poems, or texts recorded in writing rather than only spoken or sung.","zh":"Written-down literature 指以文字記錄，而不只是口述或歌唱的故事、詩歌或文本。"},{"en":"A folk tale becomes written-down literature when someone records it in a book.","zh":"當有人把民間故事記錄在書中，它就變成寫成文字的文學。"},{"en":"If a song is never written down, it may change as people pass it on orally.","zh":"如果歌曲從未被寫下，它在人們口耳相傳時可能會改變。"},{"en":"This phrase contrasts written texts with oral traditions.","zh":"這個片語把書面文本與口頭傳統作對比。"}],"source":"29 - Children’s Literature.pdf","sourcePage":1},{"front":"in print","meaning":"印刷出版的","examples":[{"en":"There were stories in print before 1700 that children often read.","zh":"1700年前已有一些印刷出版的故事，兒童常會閱讀。"},{"en":"In print means published in printed form, such as in books, pamphlets, or magazines.","zh":"In print 指以印刷形式出版，例如書籍、小冊子或雜誌。"},{"en":"A poem that appears in print can reach readers far beyond the writer’s town.","zh":"一首詩印刷出版後，可以接觸到遠超作者所在城鎮的讀者。"},{"en":"Once a story is in print, children can read the same version again and again.","zh":"一旦故事印刷出版，兒童可以一次又一次閱讀同一版本。"},{"en":"This phrase refers to printed publication, not handwriting or oral telling.","zh":"這個片語指印刷出版，而不是手寫或口述。"}],"source":"29 - Children’s Literature.pdf","sourcePage":1},{"front":"seize on","meaning":"抓住機會利用；熱切接受","examples":[{"en":"Children seized on stories whenever they had the chance.","zh":"兒童一有機會就熱切接受故事。"},{"en":"To seize on something means to eagerly take or use an opportunity, idea, or object.","zh":"To seize on something 指熱切抓住或利用某機會、想法或物件。"},{"en":"A student may seize on a helpful example because it finally makes grammar clear.","zh":"學生可能抓住一個有用例子，因為它終於令文法變清楚。"},{"en":"If children have few books, they may seize on any exciting story they can find.","zh":"如果兒童書本很少，他們可能熱切接受任何找到的刺激故事。"},{"en":"This phrase suggests quick, eager interest.","zh":"這個片語暗示快速而熱切的興趣。"}],"source":"29 - Children’s Literature.pdf","sourcePage":2},{"front":"translations of","meaning":"……的譯本","examples":[{"en":"Children read translations of Aesop’s fables.","zh":"兒童閱讀《伊索寓言》的譯本。"},{"en":"Translations of a text are versions changed from one language into another.","zh":"Translations of a text 是從一種語言轉換成另一種語言的版本。"},{"en":"Students may read translations of Japanese stories if they cannot read Japanese.","zh":"如果學生不懂日文，他們可能閱讀日本故事的譯本。"},{"en":"If a book is translated, it can reach readers who speak different languages.","zh":"如果一本書被翻譯，它可以接觸到說不同語言的讀者。"},{"en":"This phrase refers to versions of a work in another language.","zh":"這個片語指某作品的另一語言版本。"}],"source":"29 - Children’s Literature.pdf","sourcePage":2},{"front":"Aesop’s fables","meaning":"伊索寓言","examples":[{"en":"Aesop’s fables were read by children before children’s books became common.","zh":"在兒童書變得普遍之前，兒童已閱讀《伊索寓言》。"},{"en":"Aesop’s fables are short traditional stories, often with animals, that teach moral lessons.","zh":"Aesop’s fables 是短篇傳統故事，常以動物為角色，用來教導道德道理。"},{"en":"A child may learn from Aesop’s fables that honesty, patience, or wisdom matters.","zh":"兒童可能從《伊索寓言》中學到誠實、耐性或智慧的重要。"},{"en":"Because the stories are short and clear, they were easy for children to enjoy and remember.","zh":"因為故事短而清楚，兒童容易享受和記住它們。"},{"en":"This phrase names a famous collection of moral tales.","zh":"這個片語命名一套著名的道德故事集。"}],"source":"29 - Children’s Literature.pdf","sourcePage":2},{"front":"fairy-stories","meaning":"童話故事","examples":[{"en":"Fairy-stories were not originally aimed particularly at children.","zh":"童話故事原本並非特別以兒童為對象。"},{"en":"Fairy-stories are magical stories that often include fairies, spells, talking animals, or impossible events.","zh":"Fairy-stories 是包含仙子、魔法、會說話的動物或不可能事件的魔幻故事。"},{"en":"A fairy-story may begin with a poor child meeting a strange helper in the forest.","zh":"童話故事可能由一個貧窮孩子在森林中遇到神秘幫手開始。"},{"en":"If fairy-stories are rewritten for children, frightening or violent parts may be softened.","zh":"如果童話故事被改寫給兒童閱讀，恐怖或暴力部分可能被淡化。"},{"en":"This phrase refers to magical tales, not necessarily stories only for young children.","zh":"這個片語指魔幻故事，而不一定是只給幼童看的故事。"}],"source":"29 - Children’s Literature.pdf","sourcePage":2},{"front":"popular ballads and romances","meaning":"流行敘事歌謠和愛情傳奇","examples":[{"en":"Children sometimes read popular ballads and romances.","zh":"兒童有時閱讀流行敘事歌謠和愛情傳奇。"},{"en":"Popular ballads and romances are widely enjoyed songs or stories about adventure, love, heroes, or dramatic events.","zh":"Popular ballads and romances 是廣受歡迎、關於冒險、愛情、英雄或戲劇性事件的歌曲或故事。"},{"en":"Young readers may enjoy a romance because it has danger, emotion, and exciting characters.","zh":"年輕讀者可能喜歡愛情傳奇，因為它有危險、情感和刺激角色。"},{"en":"If children lack books written for them, they may turn to popular adult stories instead.","zh":"如果兒童缺乏為他們而寫的書，他們可能轉向流行成人故事。"},{"en":"This phrase refers to older popular entertainment, not modern children’s books.","zh":"這個片語指較早期的大眾娛樂，而不是現代兒童書。"}],"source":"29 - Children’s Literature.pdf","sourcePage":2},{"front":"in particular","meaning":"特別；尤其","examples":[{"en":"These stories were not aimed at young people in particular.","zh":"這些故事並非特別以年輕人為對象。"},{"en":"In particular means especially or more than others.","zh":"In particular 指特別或尤其。"},{"en":"A teacher may praise one student in particular because their essay improved greatly.","zh":"老師可能特別稱讚一名學生，因為他的作文大有進步。"},{"en":"If a book is not for children in particular, adults and young readers may both read it.","zh":"如果一本書並非特別為兒童而寫，成人和年輕讀者都可能閱讀。"},{"en":"This phrase singles out one group, person, or thing.","zh":"這個片語突出某一群體、人物或事物。"}],"source":"29 - Children’s Literature.pdf","sourcePage":2},{"front":"genuinely child-oriented literature","meaning":"真正以兒童為本的文學","examples":[{"en":"There was little genuinely child-oriented literature at this time.","zh":"當時真正以兒童為本的文學很少。"},{"en":"Genuinely child-oriented literature means books truly designed around children’s interests, language level, and experience.","zh":"Genuinely child-oriented literature 指真正圍繞兒童興趣、語言水平和經驗而設計的書。"},{"en":"A child-oriented story may use young characters, simple conflicts, and situations children understand.","zh":"以兒童為本的故事可能使用年輕角色、簡單衝突和兒童明白的情境。"},{"en":"If writers ignore children’s needs, a book may be readable by children but not genuinely child-oriented.","zh":"如果作者忽視兒童需要，一本書可能可由兒童閱讀，但不是真正以兒童為本。"},{"en":"This phrase emphasises literature made for children, not merely read by them.","zh":"這個片語強調為兒童而製作的文學，而不只是被兒童閱讀的文學。"}],"source":"29 - Children’s Literature.pdf","sourcePage":2},{"front":"instructional works","meaning":"教學作品","examples":[{"en":"Instructional works helped children with reading and general knowledge.","zh":"教學作品幫助兒童閱讀和學習常識。"},{"en":"Instructional works are books or texts designed to teach skills, facts, or moral lessons.","zh":"Instructional works 是為教授技能、事實或道德道理而設計的書或文本。"},{"en":"A spelling book or simple science reader can be an instructional work for children.","zh":"拼字書或簡單科學讀本可以是兒童教學作品。"},{"en":"If a book mainly teaches rather than entertains, it is more instructional than playful.","zh":"如果一本書主要教導而非娛樂，它就較偏教學而不是遊戲性。"},{"en":"This phrase refers to educational writing.","zh":"這個片語指教育性寫作。"}],"source":"29 - Children’s Literature.pdf","sourcePage":2},{"front":"general knowledge","meaning":"常識","examples":[{"en":"Some early books helped children with reading and general knowledge.","zh":"一些早期書籍幫助兒童閱讀和學習常識。"},{"en":"General knowledge means basic information about the world, society, nature, history, and daily life.","zh":"General knowledge 指關於世界、社會、自然、歷史和日常生活的基本資訊。"},{"en":"A children’s encyclopedia can build general knowledge through short explanations and pictures.","zh":"兒童百科全書可以透過短解釋和圖片建立常識。"},{"en":"If children gain general knowledge, they can understand school subjects more easily.","zh":"如果兒童增加常識，他們可以更容易理解學校科目。"},{"en":"This phrase refers to broad useful knowledge, not one specialist topic.","zh":"這個片語指廣泛而有用的知識，而不是某個專門題目。"}],"source":"29 - Children’s Literature.pdf","sourcePage":2},{"front":"the odd Puritanical tract","meaning":"少量清教徒小冊子","examples":[{"en":"Children might read the odd Puritanical tract as moral instruction.","zh":"兒童可能閱讀少量清教徒小冊子作為道德教育。"},{"en":"The odd Puritanical tract means an occasional strict religious booklet, especially one focused on moral behaviour.","zh":"The odd Puritanical tract 指偶爾出現的嚴格宗教小冊子，尤其著重道德行為。"},{"en":"A child in the past might receive a tract warning against lying or laziness.","zh":"過去的兒童可能收到一本警告不要說謊或懶惰的小冊子。"},{"en":"If reading material is mostly moral tracts, children may find it serious rather than entertaining.","zh":"如果閱讀材料主要是道德小冊子，兒童可能覺得它嚴肅而非有趣。"},{"en":"This phrase suggests a small number of strict moral writings.","zh":"這個片語暗示少量嚴格的道德文字。"}],"source":"29 - Children’s Literature.pdf","sourcePage":2},{"front":"as an aid to morality","meaning":"作為道德教育的輔助","examples":[{"en":"Some tracts were used as an aid to morality.","zh":"一些小冊子被用作道德教育的輔助。"},{"en":"As an aid to morality means as something that helps teach people right and wrong behaviour.","zh":"As an aid to morality 指作為幫助教導人們是非行為的工具。"},{"en":"A school story about honesty may be used as an aid to morality.","zh":"一個關於誠實的學校故事可能被用作道德教育的輔助。"},{"en":"If a book is used as moral teaching, entertainment may be less important than the lesson.","zh":"如果一本書被用作道德教育，娛樂可能不如教訓重要。"},{"en":"This phrase describes a tool for moral education.","zh":"這個片語描述道德教育的工具。"}],"source":"29 - Children’s Literature.pdf","sourcePage":3},{"front":"the only course for","meaning":"……唯一可行的方法","examples":[{"en":"The only course for keen child readers was to read adult literature.","zh":"對熱愛閱讀的兒童來說，唯一可行的方法是閱讀成人文學。"},{"en":"The only course for someone means the only practical option available to them.","zh":"The only course for someone 指某人唯一實際可行的選擇。"},{"en":"If the library is closed, the only course for students may be to use online materials.","zh":"如果圖書館關閉，學生唯一可行的方法可能是使用網上材料。"},{"en":"When children had few books of their own, reading adult books became their only course.","zh":"當兒童幾乎沒有自己的書，閱讀成人書就成為唯一可行的方法。"},{"en":"This phrase shows that there is no better alternative.","zh":"這個片語顯示沒有更好的替代方案。"}],"source":"29 - Children’s Literature.pdf","sourcePage":3},{"front":"keen child readers","meaning":"熱愛閱讀的兒童","examples":[{"en":"Keen child readers often had to read adult literature.","zh":"熱愛閱讀的兒童常不得不閱讀成人文學。"},{"en":"Keen child readers are children who are very interested in reading and actively look for books.","zh":"Keen child readers 是非常喜歡閱讀並主動尋找書籍的兒童。"},{"en":"A keen child reader may finish a library book in one evening and ask for another.","zh":"熱愛閱讀的兒童可能一晚讀完一本圖書館書，然後再要求另一本。"},{"en":"If children are keen readers but have few children’s books, they may read whatever is available.","zh":"如果兒童熱愛閱讀但兒童書很少，他們可能閱讀任何可取得的書。"},{"en":"This phrase describes children with a strong desire to read.","zh":"這個片語描述有強烈閱讀欲望的兒童。"}],"source":"29 - Children’s Literature.pdf","sourcePage":3},{"front":"adult literature","meaning":"成人文學","examples":[{"en":"Children often read adult literature before children’s books became common.","zh":"在兒童書變得普遍之前，兒童常閱讀成人文學。"},{"en":"Adult literature means books, poems, or stories mainly written for grown-up readers.","zh":"Adult literature 指主要為成年讀者而寫的書、詩歌或故事。"},{"en":"Adult literature may include complex emotions, mature themes, and difficult language.","zh":"成人文學可能包含複雜情感、成熟主題和困難語言。"},{"en":"If children read adult literature too early, they may enjoy the plot but miss deeper meanings.","zh":"如果兒童太早閱讀成人文學，他們可能享受情節，但錯過更深層意思。"},{"en":"This phrase contrasts writing for adults with writing for children.","zh":"這個片語把成人寫作與兒童寫作作對比。"}],"source":"29 - Children’s Literature.pdf","sourcePage":3},{"front":"still occurs today","meaning":"今日仍然發生","examples":[{"en":"This still occurs today with some adult thrillers and romances.","zh":"這種情況今日仍然發生於一些成人驚慄小說和愛情小說中。"},{"en":"Still occurs today means something continues to happen in the present.","zh":"Still occurs today 指某事在現在仍然發生。"},{"en":"Children borrowing books meant for older readers still occurs today in many libraries.","zh":"兒童借閱為較年長讀者而寫的書，在許多圖書館今日仍然發生。"},{"en":"If young readers want excitement, they may still choose adult books today.","zh":"如果年輕讀者想要刺激，他們今天仍可能選擇成人書。"},{"en":"This phrase connects a past pattern with modern life.","zh":"這個片語把過去模式與現代生活連接起來。"}],"source":"29 - Children’s Literature.pdf","sourcePage":3},{"front":"adult thrillers","meaning":"成人驚慄小說","examples":[{"en":"Some young readers still read adult thrillers.","zh":"一些年輕讀者今日仍閱讀成人驚慄小說。"},{"en":"Adult thrillers are suspenseful novels written for adults, often involving danger, crime, or mystery.","zh":"Adult thrillers 是為成人而寫、充滿懸疑的小說，常涉及危險、罪案或謎團。"},{"en":"A teenager may choose an adult thriller because the plot moves quickly and feels exciting.","zh":"青少年可能選擇成人驚慄小說，因為情節推進快而刺激。"},{"en":"Because adult thrillers may contain violence, they are not always suitable for younger readers.","zh":"因為成人驚慄小說可能包含暴力，它們不一定適合較年幼讀者。"},{"en":"This phrase refers to exciting adult fiction, not children’s adventure stories.","zh":"這個片語指刺激的成人小說，而不是兒童冒險故事。"}],"source":"29 - Children’s Literature.pdf","sourcePage":3},{"front":"exciting, graphic detail","meaning":"刺激而露骨的細節","examples":[{"en":"Adult books may include more exciting, graphic detail than children’s books.","zh":"成人書可能比兒童書包含更多刺激而露骨的細節。"},{"en":"Exciting, graphic detail means vivid and sometimes intense description of action, danger, violence, or emotion.","zh":"Exciting, graphic detail 指對動作、危險、暴力或情感作出生動而有時強烈的描述。"},{"en":"A crime novel may use graphic detail to describe a chase or injury.","zh":"罪案小說可能使用露骨細節描寫追逐或受傷。"},{"en":"If a book contains too much graphic detail, it may be unsuitable for young children.","zh":"如果一本書包含太多露骨細節，它可能不適合幼童。"},{"en":"This phrase contrasts vivid adult description with gentler children’s writing.","zh":"這個片語把成人作品中的生動描述與較溫和的兒童寫作作對比。"}],"source":"29 - Children’s Literature.pdf","sourcePage":3},{"front":"younger readers","meaning":"較年幼讀者","examples":[{"en":"Literature for younger readers usually contains less graphic detail.","zh":"給較年幼讀者的文學通常包含較少露骨細節。"},{"en":"Younger readers are children or young people who are still developing their reading skills and emotional understanding.","zh":"Younger readers 是仍在發展閱讀能力和情感理解的兒童或年輕人。"},{"en":"Books for younger readers often use shorter sentences and clearer plots.","zh":"給較年幼讀者的書通常使用較短句子和較清晰情節。"},{"en":"If a story is for younger readers, frightening scenes may be softened or explained simply.","zh":"如果故事是給較年幼讀者看的，恐怖場面可能被淡化或簡單解釋。"},{"en":"This phrase refers to the age and reading level of the audience.","zh":"這個片語指讀者的年齡和閱讀水平。"}],"source":"29 - Children’s Literature.pdf","sourcePage":3},{"front":"by the middle of","meaning":"到……中期","examples":[{"en":"By the middle of the 18th century, publishers began producing children’s books.","zh":"到18世紀中期，出版商開始出版兒童書。"},{"en":"By the middle of a period means at or before the central part of that period.","zh":"By the middle of a period 指到某段時期的中間部分或之前。"},{"en":"By the middle of the school year, students usually know their teachers’ expectations.","zh":"到學年中期，學生通常已知道老師的期望。"},{"en":"If a trend appears by the middle of a century, it has already started before that century ends.","zh":"如果某趨勢到一個世紀中期已出現，它就在該世紀結束前已開始。"},{"en":"This phrase gives an approximate historical time.","zh":"這個片語提供近似歷史時間。"}],"source":"29 - Children’s Literature.pdf","sourcePage":3},{"front":"eager child readers","meaning":"熱切的兒童讀者","examples":[{"en":"There were enough eager child readers for publishers to specialise.","zh":"當時有足夠多熱切的兒童讀者，讓出版商可以專門出版兒童書。"},{"en":"Eager child readers are children who are very keen and ready to read more books.","zh":"Eager child readers 是非常渴望並準備閱讀更多書的兒童。"},{"en":"A classroom with eager child readers may empty the book corner quickly.","zh":"有熱切兒童讀者的課室，圖書角的書可能很快被借光。"},{"en":"If there are many eager child readers, publishers can make money from children’s books.","zh":"如果有很多熱切的兒童讀者，出版商可以從兒童書中賺錢。"},{"en":"This phrase describes strong demand from young readers.","zh":"這個片語描述年輕讀者的強烈需求。"}],"source":"29 - Children’s Literature.pdf","sourcePage":3},{"front":"cater to this interest","meaning":"迎合這種興趣","examples":[{"en":"Parents were glad to cater to this interest in reading.","zh":"父母樂於迎合這種閱讀興趣。"},{"en":"To cater to this interest means to provide things that satisfy or support this interest.","zh":"To cater to this interest 指提供能滿足或支持這種興趣的東西。"},{"en":"A school may cater to students’ interest in science by starting a robotics club.","zh":"學校可能透過開設機械人學會來迎合學生對科學的興趣。"},{"en":"If children love stories, parents may cater to this interest by buying books or visiting libraries.","zh":"如果孩子喜愛故事，父母可能透過買書或去圖書館來迎合這種興趣。"},{"en":"This phrase describes meeting a need or desire.","zh":"這個片語描述滿足某種需要或欲望。"}],"source":"29 - Children’s Literature.pdf","sourcePage":4},{"front":"specialise in","meaning":"專門從事","examples":[{"en":"Publishers began to specialise in children’s books.","zh":"出版商開始專門出版兒童書。"},{"en":"To specialise in something means to focus on one particular area of work or knowledge.","zh":"To specialise in something 指專注於某個特定工作或知識範疇。"},{"en":"A bookshop may specialise in language-learning books for students.","zh":"書店可能專門售賣給學生用的語言學習書。"},{"en":"If a publisher specialises in children’s books, it can better understand young readers’ needs.","zh":"如果出版商專門出版兒童書，它可以更了解年輕讀者的需要。"},{"en":"This phrase shows a clear professional focus.","zh":"這個片語顯示清晰的專業焦點。"}],"source":"29 - Children’s Literature.pdf","sourcePage":4},{"front":"first aim","meaning":"首要目的","examples":[{"en":"The first aim of these books was pleasure rather than education.","zh":"這些書的首要目的是娛樂，而不是教育。"},{"en":"The first aim means the main or earliest purpose of an action, book, or plan.","zh":"First aim 指某行動、書本或計劃的主要或最早目的。"},{"en":"The first aim of a beginner lesson is to make students feel safe enough to speak.","zh":"初級課堂的首要目的是令學生感到安全，敢於開口。"},{"en":"If a book’s first aim is pleasure, it tries to entertain before it teaches.","zh":"如果一本書的首要目的是娛樂，它會先嘗試使人愉快，再考慮教導。"},{"en":"This phrase identifies the most important purpose.","zh":"這個片語指出最重要目的。"}],"source":"29 - Children’s Literature.pdf","sourcePage":4},{"front":"pleasure rather than education or morality","meaning":"娛樂而非教育或道德","examples":[{"en":"The new children’s books aimed at pleasure rather than education or morality.","zh":"新兒童書以娛樂而非教育或道德為目標。"},{"en":"Pleasure rather than education or morality means enjoyment was more important than teaching facts or moral lessons.","zh":"Pleasure rather than education or morality 指享受比教授知識或道德教訓更重要。"},{"en":"A comic book may be bought for pleasure rather than schoolwork.","zh":"漫畫書可能是為娛樂而買，而不是為學校功課而買。"},{"en":"If children read for pleasure, they may become more willing to read often.","zh":"如果兒童為娛樂而閱讀，他們可能更願意經常閱讀。"},{"en":"This phrase clearly contrasts entertainment with instruction.","zh":"這個片語清楚對比娛樂與教導。"}],"source":"29 - Children’s Literature.pdf","sourcePage":4},{"front":"London merchant","meaning":"倫敦商人","examples":[{"en":"Thomas Boreham was a London merchant.","zh":"Thomas Boreham是一名倫敦商人。"},{"en":"A London merchant is a trader or businessperson based in London.","zh":"London merchant 是以倫敦為基地的貿易商或商人。"},{"en":"A merchant may buy goods from one place and sell them in another for profit.","zh":"商人可能從一地購買貨物，再在另一地出售牟利。"},{"en":"If a merchant publishes a book, it may show that publishing was linked with business as well as literature.","zh":"如果商人出版一本書，這可能顯示出版既與文學有關，也與商業有關。"},{"en":"This phrase identifies a person by occupation and location.","zh":"這個片語透過職業和地點識別人物。"}],"source":"29 - Children’s Literature.pdf","sourcePage":4},{"front":"produce a book","meaning":"出版一本書","examples":[{"en":"Thomas Boreham produced Cajanus, The Swedish Giant in 1742.","zh":"Thomas Boreham在1742年出版了《瑞典巨人卡亞努斯》。"},{"en":"To produce a book means to create, publish, or bring a book into existence.","zh":"To produce a book 指創作、出版或使一本書面世。"},{"en":"A school may produce a book of students’ poems at the end of the year.","zh":"學校可能在學年末出版一本學生詩集。"},{"en":"If a publisher produces a successful children’s book, other publishers may copy the formula.","zh":"如果出版商出版一本成功的兒童書，其他出版商可能模仿其方程式。"},{"en":"This phrase describes making a book available to readers.","zh":"這個片語描述讓一本書可供讀者閱讀。"}],"source":"29 - Children’s Literature.pdf","sourcePage":4},{"front":"Cajanus, The Swedish Giant","meaning":"《瑞典巨人卡亞努斯》","examples":[{"en":"Cajanus, The Swedish Giant was produced by Thomas Boreham.","zh":"《瑞典巨人卡亞努斯》由Thomas Boreham出版。"},{"en":"Cajanus, The Swedish Giant was an early children’s book connected with the growing market for young readers.","zh":"《瑞典巨人卡亞努斯》是一本早期兒童書，與年輕讀者市場的增長有關。"},{"en":"A title about a giant could attract children because it promises wonder and curiosity.","zh":"關於巨人的書名可能吸引兒童，因為它帶來驚奇和好奇。"},{"en":"If such a book sold well, it would encourage publishers to produce more books for children.","zh":"如果這類書暢銷，它會鼓勵出版商製作更多兒童書。"},{"en":"This title is used as an example of early pleasure-focused children’s publishing.","zh":"這個書名被用作早期娛樂導向兒童出版的例子。"}],"source":"29 - Children’s Literature.pdf","sourcePage":4},{"front":"A Little Pretty Pocket Book","meaning":"《漂亮小口袋書》","examples":[{"en":"John Newbery published A Little Pretty Pocket Book in 1744.","zh":"John Newbery在1744年出版了《漂亮小口袋書》。"},{"en":"A Little Pretty Pocket Book was an influential early children’s book that mixed rhymes, stories, games, and a gift.","zh":"《漂亮小口袋書》是一本有影響力的早期兒童書，混合了童謠、故事、遊戲和禮物。"},{"en":"A child might enjoy such a book because it offered several small pleasures in one volume.","zh":"兒童可能喜歡這樣的書，因為它在一冊中提供多種小樂趣。"},{"en":"Its success helped show publishers that children’s books could be both enjoyable and profitable.","zh":"它的成功幫助出版商看見兒童書既可以有趣，也可以有利可圖。"},{"en":"This title is important because it helped shape later children’s annuals.","zh":"這個書名很重要，因為它幫助塑造後來的兒童年刊。"}],"source":"29 - Children’s Literature.pdf","sourcePage":4},{"front":"contents","meaning":"內容","examples":[{"en":"The book’s contents included rhymes, stories and children’s games.","zh":"這本書的內容包括童謠、故事和兒童遊戲。"},{"en":"Contents are the things included inside a book, box, course, or programme.","zh":"Contents 是一本書、盒子、課程或節目中包含的東西。"},{"en":"A lesson’s contents may include vocabulary, grammar practice, and a short quiz.","zh":"一堂課的內容可能包括詞彙、文法練習和小測。"},{"en":"If a book has varied contents, children may stay interested for longer.","zh":"如果一本書內容多樣，兒童可能更長時間保持興趣。"},{"en":"This word describes what something contains.","zh":"這個詞描述某物包含甚麼。"}],"source":"29 - Children’s Literature.pdf","sourcePage":4},{"front":"free gift","meaning":"免費禮物","examples":[{"en":"The book came with a free gift.","zh":"這本書附有免費禮物。"},{"en":"A free gift is an extra item given without extra payment when someone buys or receives something.","zh":"Free gift 是購買或收到某物時，不需額外付款而附送的額外物品。"},{"en":"A magazine may include a free gift to attract young readers.","zh":"雜誌可能附送免費禮物來吸引年輕讀者。"},{"en":"If a book comes with a toy or game, children may be more excited to own it.","zh":"如果一本書附有玩具或遊戲，兒童可能更興奮地擁有它。"},{"en":"This phrase describes a small bonus used to increase appeal.","zh":"這個片語描述用來增加吸引力的小附送品。"}],"source":"29 - Children’s Literature.pdf","sourcePage":4},{"front":"in many ways","meaning":"在很多方面","examples":[{"en":"In many ways, the book anticipated later children’s annuals.","zh":"在很多方面，這本書預示了後來的兒童年刊。"},{"en":"In many ways means in several different respects or from several points of view.","zh":"In many ways 指在幾個不同方面或從幾個角度來看。"},{"en":"In many ways, a school library is more than a place for books; it is also a quiet learning space.","zh":"在很多方面，學校圖書館不只是放書的地方，也是一個安靜學習空間。"},{"en":"If one early book resembles later books in contents and style, it anticipates them in many ways.","zh":"如果一本早期書在內容和風格上像後來的書，它就在很多方面預示它們。"},{"en":"This phrase shows that the comparison is broad, not based on one detail only.","zh":"這個片語顯示比較範圍較廣，不只是基於一個細節。"}],"source":"29 - Children’s Literature.pdf","sourcePage":5},{"front":"anticipate","meaning":"預示；先於……出現","examples":[{"en":"A Little Pretty Pocket Book anticipated the contents of children’s annuals.","zh":"《漂亮小口袋書》預示了兒童年刊的內容。"},{"en":"To anticipate something means to come before it and show features that later become common.","zh":"To anticipate something 指早於某事出現，並展示後來變得常見的特徵。"},{"en":"Early smartphones anticipated modern mobile life by combining calls, messages, and Internet access.","zh":"早期智能手機透過結合通話、訊息和上網，預示了現代流動生活。"},{"en":"If a book includes features later used by many others, it can be said to anticipate them.","zh":"如果一本書包含後來許多書使用的特徵，就可以說它預示了它們。"},{"en":"This verb means to foreshadow or come before a later development.","zh":"這個動詞指預示或先於後來發展出現。"}],"source":"29 - Children’s Literature.pdf","sourcePage":5},{"front":"lucky-dip contents","meaning":"像抽獎袋般多樣化的內容","examples":[{"en":"The book anticipated the lucky-dip contents of children’s annuals.","zh":"這本書預示了兒童年刊像抽獎袋般多樣化的內容。"},{"en":"Lucky-dip contents are mixed and varied items, so readers are not sure what kind of thing will come next.","zh":"Lucky-dip contents 是混合而多樣化的內容，讀者不確定下一項會是甚麼。"},{"en":"A children’s magazine with stories, jokes, puzzles, and stickers has lucky-dip contents.","zh":"一本包含故事、笑話、謎題和貼紙的兒童雜誌，就有像抽獎袋般多樣化的內容。"},{"en":"If contents are varied, children may enjoy the surprise of turning each page.","zh":"如果內容多樣，兒童可能享受翻頁時的驚喜。"},{"en":"This phrase suggests a playful mixture rather than one single type of material.","zh":"這個片語暗示遊戲式混合，而不是單一種類材料。"}],"source":"29 - Children’s Literature.pdf","sourcePage":5},{"front":"children’s annuals","meaning":"兒童年刊","examples":[{"en":"Children’s annuals later used a similar mixture of contents.","zh":"兒童年刊後來使用相似的混合內容。"},{"en":"Children’s annuals are books or magazines for children published once a year, often with stories, puzzles, games, and pictures.","zh":"Children’s annuals 是每年出版一次、給兒童閱讀的書或雜誌，常包含故事、謎題、遊戲和圖片。"},{"en":"A child may receive a children’s annual as a holiday gift.","zh":"兒童可能收到兒童年刊作為假日禮物。"},{"en":"Because annuals contain many short items, they can appeal to children with different interests.","zh":"因為年刊包含許多短項目，它們可以吸引不同興趣的兒童。"},{"en":"This phrase refers to yearly children’s publications.","zh":"這個片語指每年出版的兒童刊物。"}],"source":"29 - Children’s Literature.pdf","sourcePage":5},{"front":"a tribute to","meaning":"對……的肯定","examples":[{"en":"It is a tribute to Newbery’s flair that he found a winning formula.","zh":"他找到成功方程式，是對Newbery才華的肯定。"},{"en":"A tribute to someone’s ability is proof or praise showing that the ability is real.","zh":"A tribute to someone’s ability 是顯示某能力真實存在的證明或讚賞。"},{"en":"A full classroom is a tribute to a teacher’s ability to make lessons useful.","zh":"課室坐滿學生，是對老師能令課堂有用的能力的肯定。"},{"en":"If a book is copied quickly, it may be a tribute to the publisher’s successful idea.","zh":"如果一本書很快被模仿，這可能是對出版商成功想法的肯定。"},{"en":"This phrase praises the quality behind an achievement.","zh":"這個片語讚揚成就背後的質素。"}],"source":"29 - Children’s Literature.pdf","sourcePage":5},{"front":"flair","meaning":"才華；天分","examples":[{"en":"Newbery’s flair helped him create a successful children’s book.","zh":"Newbery的才華幫助他創作出一本成功的兒童書。"},{"en":"Flair means a natural talent for doing something in an attractive, skilful, or original way.","zh":"Flair 指以吸引、熟練或原創方式做某事的天生才能。"},{"en":"A teacher with flair can explain grammar through simple stories and lively examples.","zh":"有才華的老師可以透過簡單故事和生動例子解釋文法。"},{"en":"If a publisher has flair, they may understand what readers will enjoy before others do.","zh":"如果出版商有才華，他可能比別人更早明白讀者會喜歡甚麼。"},{"en":"This word describes talent with style and instinct.","zh":"這個詞描述帶有風格和直覺的才能。"}],"source":"29 - Children’s Literature.pdf","sourcePage":5},{"front":"hit upon","meaning":"偶然想出；找到","examples":[{"en":"Newbery hit upon a winning formula very quickly.","zh":"Newbery很快就找到成功方程式。"},{"en":"To hit upon an idea means to discover or think of it, often by chance or clever experimentation.","zh":"To hit upon an idea 指想出或發現一個想法，常帶有偶然或巧妙試驗的意味。"},{"en":"A student may hit upon a useful study method after trying several approaches.","zh":"學生嘗試幾種方法後，可能偶然找到有用的學習方法。"},{"en":"If a publisher hits upon a popular format, other publishers may soon copy it.","zh":"如果出版商找到受歡迎的形式，其他出版商可能很快模仿。"},{"en":"This phrase suggests finding a good solution.","zh":"這個片語暗示找到好解決方法。"}],"source":"29 - Children’s Literature.pdf","sourcePage":5},{"front":"winning formula","meaning":"成功方程式","examples":[{"en":"Newbery hit upon a winning formula for children’s books.","zh":"Newbery找到了兒童書的成功方程式。"},{"en":"A winning formula is a successful combination of features that works well.","zh":"Winning formula 是一組運作良好的成功特徵組合。"},{"en":"A restaurant may find a winning formula by offering good food, fair prices, and friendly service.","zh":"餐廳可能透過提供好食物、合理價格和友善服務找到成功方程式。"},{"en":"If children enjoy rhymes, stories, games, and gifts together, that mixture may become a winning formula.","zh":"如果兒童喜歡童謠、故事、遊戲和禮物的組合，那種混合可能成為成功方程式。"},{"en":"This phrase describes a repeatable recipe for success.","zh":"這個片語描述可重複使用的成功方法。"}],"source":"29 - Children’s Literature.pdf","sourcePage":5},{"front":"be pirated","meaning":"被盜版","examples":[{"en":"The book was pirated almost immediately in America.","zh":"這本書幾乎立即在美國被盜版。"},{"en":"To be pirated means to be copied and sold illegally without the creator’s permission.","zh":"To be pirated 指未經創作者許可而被非法複製和出售。"},{"en":"A popular textbook may be pirated if people photocopy and sell it cheaply.","zh":"如果有人影印並低價出售，受歡迎的教科書可能被盜版。"},{"en":"If a book is pirated quickly, it may show strong demand but also harms the original publisher.","zh":"如果一本書很快被盜版，這可能顯示需求強烈，但也傷害原出版商。"},{"en":"This phrase refers to illegal copying, not sea pirates.","zh":"這個片語指非法複製，而不是海盜。"}],"source":"29 - Children’s Literature.pdf","sourcePage":5},{"front":"pleasing levity","meaning":"令人愉快的輕鬆風格","examples":[{"en":"Such pleasing levity was not to last.","zh":"這種令人愉快的輕鬆風格不會持續下去。"},{"en":"Pleasing levity means an enjoyable lightness, humour, or lack of heavy seriousness.","zh":"Pleasing levity 指令人愉快的輕鬆、幽默或不過分嚴肅。"},{"en":"A teacher may add pleasing levity to a difficult lesson with a simple funny example.","zh":"老師可能透過簡單有趣例子，為困難課堂加入令人愉快的輕鬆感。"},{"en":"If children’s books become too moral and serious, pleasing levity may disappear.","zh":"如果兒童書變得太道德化和嚴肅，令人愉快的輕鬆風格可能消失。"},{"en":"This phrase describes light entertainment that feels pleasant.","zh":"這個片語描述令人愉快的輕鬆娛樂。"}],"source":"29 - Children’s Literature.pdf","sourcePage":5},{"front":"not to last","meaning":"不會持續下去","examples":[{"en":"The early pleasure-focused style was not to last.","zh":"早期以娛樂為主的風格不會持續下去。"},{"en":"Not to last means not going to continue for a long time.","zh":"Not to last 指不會長時間延續。"},{"en":"A student’s early excitement about a new notebook may not last without a study plan.","zh":"如果沒有學習計劃，學生對新筆記簿的最初興奮可能不會持續下去。"},{"en":"If critics attack a style strongly, its popularity may not last.","zh":"如果批評家強烈攻擊某風格，它的受歡迎程度可能不會持續。"},{"en":"This phrase suggests that something will soon change or disappear.","zh":"這個片語暗示某事很快會改變或消失。"}],"source":"29 - Children’s Literature.pdf","sourcePage":6},{"front":"influenced by","meaning":"受……影響","examples":[{"en":"Children’s literature was influenced by Rousseau’s ideas.","zh":"兒童文學受Rousseau思想影響。"},{"en":"To be influenced by something means to be affected or shaped by it.","zh":"To be influenced by something 指被某事影響或塑造。"},{"en":"A student’s writing may be influenced by the books they read most often.","zh":"學生的寫作可能受他最常閱讀的書影響。"},{"en":"If critics are influenced by a philosopher, their reviews may reflect his ideas.","zh":"如果批評家受某哲學家影響，他們的評論可能反映其思想。"},{"en":"This phrase shows that one idea, person, or event affects another.","zh":"這個片語顯示一個想法、人物或事件影響另一事物。"}],"source":"29 - Children’s Literature.pdf","sourcePage":6},{"front":"decree that","meaning":"宣稱；規定","examples":[{"en":"Rousseau decreed that most books for children were dangerous.","zh":"Rousseau宣稱大多數兒童書是危險的。"},{"en":"To decree that something is true means to state it with authority, as if making a rule or judgment.","zh":"To decree that something is true 指以權威口吻陳述某事，像是在制定規則或判斷。"},{"en":"A headteacher may decree that phones must stay in bags during lessons.","zh":"校長可能規定上課期間手機必須留在書包中。"},{"en":"If an influential thinker decrees that certain books are harmful, writers may change what they publish.","zh":"如果有影響力的思想家宣稱某些書有害，作者可能改變出版內容。"},{"en":"This phrase sounds stronger and more authoritative than simply “say”.","zh":"這個片語比 simply “say” 更強烈、更有權威感。"}],"source":"29 - Children’s Literature.pdf","sourcePage":6},{"front":"save Robinson Crusoe","meaning":"除《魯賓遜漂流記》外","examples":[{"en":"Rousseau rejected all children’s books save Robinson Crusoe.","zh":"Rousseau拒絕所有兒童書，除《魯賓遜漂流記》外。"},{"en":"Save Robinson Crusoe means except for Robinson Crusoe.","zh":"Save Robinson Crusoe 指除了《魯賓遜漂流記》之外。"},{"en":"The library was closed every day save Monday, so students could only borrow books then.","zh":"圖書館除了星期一外每天關閉，所以學生只能那天借書。"},{"en":"If someone rejects all books save one, that single book is treated as the only acceptable exception.","zh":"如果某人拒絕所有書，除一本外，那本書就被視為唯一可接受的例外。"},{"en":"In this use, “save” means “except”, not rescue.","zh":"在這個用法中，save 指「除了」，不是拯救。"}],"source":"29 - Children’s Literature.pdf","sourcePage":6},{"front":"dangerous diversion","meaning":"危險的消遣","examples":[{"en":"Rousseau saw most children’s books as a dangerous diversion.","zh":"Rousseau把大多數兒童書視為危險的消遣。"},{"en":"A dangerous diversion is something that distracts people from what they should do and may harm them.","zh":"Dangerous diversion 是令人分心並可能帶來傷害的東西。"},{"en":"A phone can become a dangerous diversion if students use it during every study session.","zh":"如果學生每次溫習都使用手機，手機可能成為危險的消遣。"},{"en":"If adults think stories distract children from moral learning, they may call them dangerous diversions.","zh":"如果成人認為故事使兒童偏離道德學習，他們可能稱其為危險的消遣。"},{"en":"This phrase combines distraction with moral or practical risk.","zh":"這個片語把分心與道德或實際風險結合起來。"}],"source":"29 - Children’s Literature.pdf","sourcePage":6},{"front":"contemporary critics","meaning":"當代批評家","examples":[{"en":"Contemporary critics wanted children’s literature to be instructive.","zh":"當代批評家希望兒童文學具有教育意義。"},{"en":"Contemporary critics are critics living and writing at the same time as the works or events being discussed.","zh":"Contemporary critics 是與所討論作品或事件同時代生活和寫作的批評家。"},{"en":"Contemporary critics of a new film may judge it differently from later historians.","zh":"一部新電影的當代批評家可能與後來的歷史學家作出不同評價。"},{"en":"If contemporary critics dislike playful books, publishers may produce more serious ones.","zh":"如果當代批評家不喜歡遊戲式書籍，出版商可能製作更多嚴肅作品。"},{"en":"This phrase refers to critics of that period, not modern critics today.","zh":"這個片語指該時期的批評家，而不是今天的現代批評家。"}],"source":"29 - Children’s Literature.pdf","sourcePage":6},{"front":"see to it that","meaning":"確保","examples":[{"en":"Critics saw to it that children’s literature became instructive.","zh":"批評家確保兒童文學變得有教育意義。"},{"en":"To see to it that something happens means to make sure it happens.","zh":"To see to it that something happens 指確保某事發生。"},{"en":"A teacher may see to it that every student receives the worksheet before class.","zh":"老師可能確保每位學生在上課前收到工作紙。"},{"en":"If critics pressure publishers, they may see to it that books follow moral standards.","zh":"如果批評家向出版商施壓，他們可能確保書籍遵循道德標準。"},{"en":"This phrase shows active effort to ensure a result.","zh":"這個片語顯示主動努力確保結果。"}],"source":"29 - Children’s Literature.pdf","sourcePage":6},{"front":"instructive and uplifting","meaning":"有教育意義並能提升心靈的","examples":[{"en":"Children’s literature was expected to be instructive and uplifting.","zh":"兒童文學被期望有教育意義並能提升心靈。"},{"en":"Instructive and uplifting means teaching useful lessons while making readers feel morally or emotionally better.","zh":"Instructive and uplifting 指教授有用道理，同時令讀者在道德或情感上感到更好。"},{"en":"A school story about kindness can be both instructive and uplifting.","zh":"關於善良的校園故事可以既有教育意義又能提升心靈。"},{"en":"If a book only frightens children without helping them understand life, critics may not call it uplifting.","zh":"如果一本書只嚇怕兒童而不幫助他們理解生活，批評家可能不會稱它能提升心靈。"},{"en":"This phrase describes literature that teaches and improves the reader.","zh":"這個片語描述能教導並提升讀者的文學。"}],"source":"29 - Children’s Literature.pdf","sourcePage":6},{"front":"prominent among","meaning":"在……之中特別突出","examples":[{"en":"Mrs Sarah Trimmer was prominent among such voices.","zh":"Sarah Trimmer夫人在這類聲音中特別突出。"},{"en":"To be prominent among a group means to be one of the most important, visible, or influential members of it.","zh":"To be prominent among a group 指在某群體中屬於最重要、最顯眼或最有影響力的成員之一。"},{"en":"A student may be prominent among classmates because they often lead discussions.","zh":"一名學生可能因常帶領討論而在同學中特別突出。"},{"en":"If a critic is prominent among reformers, their opinions may strongly shape public taste.","zh":"如果一位批評家在改革者中特別突出，他的意見可能強烈塑造公眾品味。"},{"en":"This phrase highlights someone’s importance within a group.","zh":"這個片語突顯某人在群體中的重要性。"}],"source":"29 - Children’s Literature.pdf","sourcePage":6},{"front":"The Guardian of Education","meaning":"《教育衛士》","examples":[{"en":"The Guardian of Education carried regular reviews of children’s books.","zh":"《教育衛士》刊登兒童書的定期評論。"},{"en":"The Guardian of Education was a publication connected with reviewing and judging educational and children’s reading materials.","zh":"The Guardian of Education 是與評論和評判教育及兒童讀物有關的刊物。"},{"en":"A magazine like this could influence parents by recommending or condemning books.","zh":"這類雜誌可以透過推薦或譴責書籍影響父母。"},{"en":"If a publication reviews books regularly, it can shape what families consider suitable.","zh":"如果刊物定期評論書籍，它可以塑造家庭認為合適的讀物。"},{"en":"This title is linked with early criticism of children’s literature.","zh":"這個名稱與早期兒童文學評論有關。"}],"source":"29 - Children’s Literature.pdf","sourcePage":6},{"front":"carry reviews","meaning":"刊登評論","examples":[{"en":"The magazine carried the first regular reviews of children’s books.","zh":"該雜誌刊登了最早的兒童書定期評論。"},{"en":"To carry reviews means to publish reviews in a newspaper, magazine, or website.","zh":"To carry reviews 指在報紙、雜誌或網站上刊登評論。"},{"en":"A school newsletter may carry reviews of books students recommend.","zh":"學校通訊可能刊登學生推薦書籍的評論。"},{"en":"If a magazine carries reviews, readers can decide which books are worth buying.","zh":"如果雜誌刊登評論，讀者可以判斷哪些書值得購買。"},{"en":"This phrase uses “carry” to mean “include and publish”.","zh":"這個片語用 “carry” 表示「包含並出版」。"}],"source":"29 - Children’s Literature.pdf","sourcePage":7},{"front":"regular reviews","meaning":"定期評論","examples":[{"en":"The magazine published regular reviews of children’s books.","zh":"該雜誌定期刊登兒童書評論。"},{"en":"Regular reviews are reviews published repeatedly at fixed or frequent intervals.","zh":"Regular reviews 是以固定或頻密間隔反覆刊登的評論。"},{"en":"A website may post regular reviews of new language-learning apps.","zh":"網站可能定期評論新的語言學習應用程式。"},{"en":"If parents read regular reviews, they can follow changes in children’s publishing.","zh":"如果父母閱讀定期評論，他們可以跟進兒童出版的變化。"},{"en":"This phrase describes repeated critical discussion, not a one-time comment.","zh":"這個片語描述反覆的批評討論，而不是一次性評論。"}],"source":"29 - Children’s Literature.pdf","sourcePage":7},{"front":"condemn something for","meaning":"因……而譴責","examples":[{"en":"Sarah Trimmer condemned fairy-tales for their violence.","zh":"Sarah Trimmer因童話故事中的暴力而譴責它們。"},{"en":"To condemn something for a reason means to criticise it strongly because of that reason.","zh":"To condemn something for a reason 指因某原因而強烈批評某事。"},{"en":"Parents may condemn a video game for encouraging cruel behaviour.","zh":"父母可能因電子遊戲鼓勵殘忍行為而譴責它。"},{"en":"If critics condemn a book for violence, publishers may remove or soften certain scenes.","zh":"如果批評家因暴力而譴責一本書，出版商可能刪除或淡化某些場面。"},{"en":"This phrase shows strong disapproval and gives the reason for it.","zh":"這個片語顯示強烈不認同，並給出原因。"}],"source":"29 - Children’s Literature.pdf","sourcePage":7},{"front":"violence and general absurdity","meaning":"暴力和整體荒謬","examples":[{"en":"She criticised fairy-tales for violence and general absurdity.","zh":"她批評童話故事有暴力和整體荒謬。"},{"en":"Violence and general absurdity means physical harm and overall foolishness or ridiculousness.","zh":"Violence and general absurdity 指身體傷害，以及整體上的愚蠢或荒唐。"},{"en":"A parent may dislike a cartoon because of its violence and general absurdity.","zh":"家長可能因卡通有暴力和整體荒謬而不喜歡它。"},{"en":"If a story seems violent and silly, moral critics may think it harms children’s judgment.","zh":"如果故事顯得暴力又愚蠢，道德批評家可能認為它損害兒童判斷力。"},{"en":"This phrase combines moral danger with lack of sense.","zh":"這個片語把道德危險與缺乏理性結合起來。"}],"source":"29 - Children’s Literature.pdf","sourcePage":7},{"front":"talking animals","meaning":"會說話的動物","examples":[{"en":"Her stories described talking animals.","zh":"她的故事描寫會說話的動物。"},{"en":"Talking animals are animal characters that speak and behave partly like humans.","zh":"Talking animals 是會說話並部分像人類般行動的動物角色。"},{"en":"A story about a talking rabbit may teach children about honesty or kindness.","zh":"關於會說話兔子的故事可能教兒童誠實或善良。"},{"en":"If animals talk in a story, children may find the lesson more enjoyable and easier to remember.","zh":"如果故事中的動物會說話，兒童可能覺得教訓更有趣、更容易記住。"},{"en":"This phrase refers to a common device in children’s stories and fables.","zh":"這個片語指兒童故事和寓言中的常見手法。"}],"source":"29 - Children’s Literature.pdf","sourcePage":7},{"front":"models of sense and decorum","meaning":"明智和得體行為的典範","examples":[{"en":"The talking animals were models of sense and decorum.","zh":"這些會說話的動物是明智和得體行為的典範。"},{"en":"Models of sense and decorum are examples of wise, reasonable, and proper behaviour.","zh":"Models of sense and decorum 是智慧、理性和得體行為的例子。"},{"en":"A polite student who listens carefully can be a model of decorum in class.","zh":"一位有禮且細心聆聽的學生，可以是課堂得體行為的典範。"},{"en":"If story characters behave sensibly, children may be encouraged to copy their behaviour.","zh":"如果故事角色行為明智，兒童可能被鼓勵模仿他們的行為。"},{"en":"This phrase describes characters used as good moral examples.","zh":"這個片語描述被用作良好道德榜樣的角色。"}],"source":"29 - Children’s Literature.pdf","sourcePage":7},{"front":"moral story","meaning":"道德故事","examples":[{"en":"The moral story for children was always threatened from within.","zh":"兒童道德故事一直從內部受到威脅。"},{"en":"A moral story is a story written to teach readers a lesson about right and wrong.","zh":"Moral story 是為教導讀者是非道理而寫的故事。"},{"en":"A story about a child who lies and then loses trust is a moral story.","zh":"一個關於孩子說謊後失去信任的故事，就是道德故事。"},{"en":"If children enjoy the adventure more than the lesson, the moral story may not work as adults expect.","zh":"如果兒童享受冒險多於教訓，道德故事可能不如成人預期般發揮作用。"},{"en":"This phrase refers to storytelling with a clear ethical purpose.","zh":"這個片語指具有明確倫理目的的故事。"}],"source":"29 - Children’s Literature.pdf","sourcePage":7},{"front":"be threatened from within","meaning":"從內部受到威脅","examples":[{"en":"The moral story was threatened from within by children’s enjoyment.","zh":"道德故事因兒童的娛樂感而從內部受到威脅。"},{"en":"To be threatened from within means to be weakened by something inside the system itself.","zh":"To be threatened from within 指被系統內部的某事削弱。"},{"en":"A school rule may be threatened from within if teachers apply it inconsistently.","zh":"如果老師執行不一致，校規可能從內部受到威脅。"},{"en":"If children find fun inside a strict moral story, its serious purpose may be weakened from within.","zh":"如果兒童在嚴肅道德故事中找到樂趣，它的嚴肅目的可能從內部被削弱。"},{"en":"This phrase describes an internal challenge, not an outside attack.","zh":"這個片語描述內部挑戰，而不是外部攻擊。"}],"source":"29 - Children’s Literature.pdf","sourcePage":7},{"front":"draw out entertainment from","meaning":"從……中找出娛樂","examples":[{"en":"Children could draw out entertainment from strict moral stories.","zh":"兒童可以從嚴格的道德故事中找出娛樂。"},{"en":"To draw out entertainment from something means to find or extract enjoyment from it, even if it was not mainly meant to be fun.","zh":"To draw out entertainment from something 指從某事中找出或提取樂趣，即使它本來不主要為娛樂而設。"},{"en":"Students may draw entertainment from a serious history lesson if the examples are vivid.","zh":"如果例子生動，學生可能從嚴肅歷史課中找到娛樂。"},{"en":"If readers focus on funny details, they can draw entertainment from even a moral tale.","zh":"如果讀者集中於有趣細節，他們甚至可以從道德故事中找到娛樂。"},{"en":"This phrase shows children’s active ability to find pleasure.","zh":"這個片語顯示兒童主動尋找樂趣的能力。"}],"source":"29 - Children’s Literature.pdf","sourcePage":7},{"front":"the sternest moralist","meaning":"最嚴厲的道德說教者","examples":[{"en":"Children could find fun even in the sternest moralist’s writing.","zh":"兒童甚至可以在最嚴厲的道德說教者的作品中找到樂趣。"},{"en":"The sternest moralist means the strictest person who focuses on teaching right and wrong behaviour.","zh":"The sternest moralist 指最嚴格、最著重教導是非行為的人。"},{"en":"A stern moralist may dislike jokes if they seem to distract from discipline.","zh":"嚴厲的道德說教者可能不喜歡笑話，因為它們似乎令人分心而不守紀律。"},{"en":"If children laugh at a strict story, even the sternest moralist cannot fully control their response.","zh":"如果兒童在嚴格故事中大笑，即使最嚴厲的道德說教者也不能完全控制他們的反應。"},{"en":"This phrase describes an extremely serious moral teacher or writer.","zh":"這個片語描述極嚴肅的道德教師或作者。"}],"source":"29 - Children’s Literature.pdf","sourcePage":7},{"front":"the greatest blow to","meaning":"對……的最大打擊","examples":[{"en":"The greatest blow to improving children’s books came from folklore.","zh":"對教化兒童書籍的最大打擊來自民間傳說。"},{"en":"The greatest blow to something is the strongest attack, setback, or challenge it receives.","zh":"Greatest blow to something 是某事受到的最強攻擊、挫折或挑戰。"},{"en":"Losing its main teacher was the greatest blow to the school’s music programme.","zh":"失去主要老師是學校音樂計劃的最大打擊。"},{"en":"If folklore made children prefer fantasy and fun, it became a blow to strictly moral books.","zh":"如果民間傳說令兒童更喜歡幻想和樂趣，它就成為嚴格道德書的打擊。"},{"en":"This phrase describes a serious challenge to an existing movement or idea.","zh":"這個片語描述對既有運動或想法的嚴重挑戰。"}],"source":"29 - Children’s Literature.pdf","sourcePage":8},{"front":"improving children’s book","meaning":"教化兒童的書籍","examples":[{"en":"The improving children’s book was challenged by interest in folklore.","zh":"教化兒童的書籍受到對民間傳說興趣的挑戰。"},{"en":"An improving children’s book is a book meant to improve a child’s morals, knowledge, or behaviour.","zh":"Improving children’s book 是旨在改善兒童道德、知識或行為的書。"},{"en":"A story that teaches obedience and honesty may be called an improving children’s book.","zh":"教導服從和誠實的故事可被稱為教化兒童的書籍。"},{"en":"If children prefer fairy stories, improving books may lose their influence.","zh":"如果兒童更喜歡童話故事，教化書可能失去影響力。"},{"en":"This phrase refers to morally or educationally improving books, not simply better-quality books.","zh":"這個片語指在道德或教育上改善兒童的書，而不只是質素更好的書。"}],"source":"29 - Children’s Literature.pdf","sourcePage":8},{"front":"unlikely source","meaning":"不大可能的來源","examples":[{"en":"The blow came from an unlikely source.","zh":"這個打擊來自不大可能的來源。"},{"en":"An unlikely source is a person, place, or thing that people would not expect to cause something.","zh":"Unlikely source 是人們不會預期會造成某事的人、地方或事物。"},{"en":"A quiet student can be an unlikely source of the best idea in a group project.","zh":"安靜的學生可能成為小組項目中最好想法的不大可能來源。"},{"en":"If serious children’s publishing changed because of playful folklore, the change came from an unlikely source.","zh":"如果嚴肅兒童出版因遊戲式民間傳說而改變，這種改變就來自不大可能的來源。"},{"en":"This phrase highlights surprise about where something comes from.","zh":"這個片語突顯某事來源令人意外。"}],"source":"29 - Children’s Literature.pdf","sourcePage":8},{"front":"interest in folklore","meaning":"對民間傳說的興趣","examples":[{"en":"Early-19th-century interest in folklore changed children’s literature.","zh":"19世紀初對民間傳說的興趣改變了兒童文學。"},{"en":"Interest in folklore means attention to traditional stories, songs, beliefs, and customs passed down among ordinary people.","zh":"Interest in folklore 指關注在普通人之間流傳的傳統故事、歌曲、信念和習俗。"},{"en":"A class may show interest in folklore by collecting grandparents’ old stories.","zh":"一個班級可能透過收集祖父母的舊故事來表現對民間傳說的興趣。"},{"en":"If interest in folklore grows, publishers may print more fairy tales and nursery rhymes.","zh":"如果對民間傳說的興趣增長，出版商可能印刷更多童話和童謠。"},{"en":"This phrase connects cultural tradition with literary change.","zh":"這個片語把文化傳統與文學變化連接起來。"}],"source":"29 - Children’s Literature.pdf","sourcePage":8},{"front":"nursery rhymes","meaning":"童謠","examples":[{"en":"Nursery rhymes became popular with young readers.","zh":"童謠在年輕讀者中變得受歡迎。"},{"en":"Nursery rhymes are short traditional poems or songs for young children.","zh":"Nursery rhymes 是給幼童的短篇傳統詩歌或歌曲。"},{"en":"Children may learn rhythm, sounds, and simple words through nursery rhymes.","zh":"兒童可能透過童謠學習節奏、聲音和簡單字詞。"},{"en":"Because nursery rhymes are easy to repeat, they often stay in memory for years.","zh":"因為童謠容易重複，它們常在記憶中停留多年。"},{"en":"This phrase refers to simple verse for very young children.","zh":"這個片語指給非常年幼兒童的簡單韻文。"}],"source":"29 - Children’s Literature.pdf","sourcePage":8},{"front":"folklore society","meaning":"民俗學會","examples":[{"en":"James Orchard Halliwell selected nursery rhymes for a folklore society.","zh":"James Orchard Halliwell為民俗學會挑選童謠。"},{"en":"A folklore society is a group that studies, collects, or preserves traditional stories, songs, customs, and beliefs.","zh":"Folklore society 是研究、收集或保存傳統故事、歌曲、習俗和信念的團體。"},{"en":"A folklore society may record village songs before older singers are gone.","zh":"民俗學會可能在年長歌者離世前記錄村莊歌曲。"},{"en":"If a folklore society publishes old rhymes, children may rediscover traditional material.","zh":"如果民俗學會出版舊童謠，兒童可能重新發現傳統材料。"},{"en":"This phrase refers to an organisation interested in folk culture.","zh":"這個片語指對民間文化感興趣的組織。"}],"source":"29 - Children’s Literature.pdf","sourcePage":8},{"front":"fairy stories","meaning":"童話故事","examples":[{"en":"The Grimm brothers’ fairy stories were translated into English.","zh":"格林兄弟的童話故事被翻譯成英文。"},{"en":"Fairy stories are magical stories with strange events, supernatural helpers, curses, or transformations.","zh":"Fairy stories 是包含奇異事件、超自然幫手、詛咒或變身的魔幻故事。"},{"en":"A fairy story may teach courage through a child facing a dragon or witch.","zh":"童話故事可能透過孩子面對龍或女巫來教導勇氣。"},{"en":"If fairy stories are translated, children in other countries can enjoy them too.","zh":"如果童話故事被翻譯，其他國家的兒童也可以欣賞它們。"},{"en":"This phrase refers to magical traditional tales.","zh":"這個片語指魔幻傳統故事。"}],"source":"29 - Children’s Literature.pdf","sourcePage":8},{"front":"scholarly","meaning":"學術型的；有學問的","examples":[{"en":"The scholarly Grimm brothers collected fairy stories.","zh":"學術型的格林兄弟收集童話故事。"},{"en":"Scholarly means serious, academic, and based on careful study.","zh":"Scholarly 指嚴肅、學術性，並基於仔細研究。"},{"en":"A scholarly article usually uses evidence, references, and careful argument.","zh":"學術文章通常使用證據、參考資料和謹慎論證。"},{"en":"If collectors are scholarly, they may preserve stories carefully rather than rewrite them casually.","zh":"如果收集者是學術型的，他們可能仔細保存故事，而不是隨意改寫。"},{"en":"This word describes learned and research-minded work.","zh":"這個詞描述有學問並重視研究的工作。"}],"source":"29 - Children’s Literature.pdf","sourcePage":8},{"front":"be translated into English","meaning":"被翻譯成英文","examples":[{"en":"The Grimm brothers’ fairy stories were swiftly translated into English.","zh":"格林兄弟的童話故事很快被翻譯成英文。"},{"en":"To be translated into English means to be changed from another language into English.","zh":"To be translated into English 指從另一種語言轉換成英文。"},{"en":"A Japanese picture book can be translated into English so more children can read it.","zh":"日本圖畫書可以被翻譯成英文，讓更多兒童閱讀。"},{"en":"If a story is translated into English quickly, it may show strong international interest.","zh":"如果故事很快被翻譯成英文，這可能顯示國際興趣強烈。"},{"en":"This phrase describes language transfer into English.","zh":"這個片語描述轉換成英文的語言轉移。"}],"source":"29 - Children’s Literature.pdf","sourcePage":8},{"front":"rocket to popularity","meaning":"迅速大受歡迎","examples":[{"en":"Nursery rhymes and fairy stories rocketed to popularity with the young.","zh":"童謠和童話故事在年輕人中迅速大受歡迎。"},{"en":"To rocket to popularity means to become popular very quickly.","zh":"To rocket to popularity 指非常快速地變得受歡迎。"},{"en":"A children’s song may rocket to popularity after many students share it online.","zh":"如果許多學生在網上分享，一首兒童歌曲可能迅速大受歡迎。"},{"en":"If a new edition sells out quickly, the story may have rocketed to popularity.","zh":"如果新版本很快售罄，故事可能已迅速大受歡迎。"},{"en":"This phrase suggests sudden and rapid success.","zh":"這個片語暗示突然且快速的成功。"}],"source":"29 - Children’s Literature.pdf","sourcePage":8},{"front":"with the young","meaning":"在年輕人之中","examples":[{"en":"The new collections became popular with the young.","zh":"新合集在年輕人之中變得受歡迎。"},{"en":"With the young means among children or young people.","zh":"With the young 指在兒童或年輕人之中。"},{"en":"Short video stories are popular with the young because they are quick and visual.","zh":"短片故事在年輕人之中受歡迎，因為它們快速而有畫面。"},{"en":"If a book becomes popular with the young, publishers may print more similar books.","zh":"如果一本書在年輕人之中受歡迎，出版商可能印更多相似書籍。"},{"en":"This phrase identifies young people as the group that likes something.","zh":"這個片語指出年輕人是喜歡某事的群體。"}],"source":"29 - Children’s Literature.pdf","sourcePage":9},{"front":"lead to","meaning":"導致","examples":[{"en":"Their popularity led to new editions.","zh":"它們的受歡迎程度導致新版本出現。"},{"en":"To lead to something means to cause it or make it happen.","zh":"To lead to something 指造成某事或令某事發生。"},{"en":"Good feedback can lead to better writing if students use it carefully.","zh":"如果學生仔細使用，好回饋可以導致更好的寫作。"},{"en":"If a book becomes popular, demand can lead to new editions and more sales.","zh":"如果一本書變得受歡迎，需求可以導致新版本和更多銷售。"},{"en":"This phrase connects a cause with a result.","zh":"這個片語連接原因與結果。"}],"source":"29 - Children’s Literature.pdf","sourcePage":9},{"front":"new editions","meaning":"新版本","examples":[{"en":"The books quickly led to new editions.","zh":"這些書很快帶來新版本。"},{"en":"New editions are newly printed or revised versions of a book.","zh":"New editions 是一本書的新印刷或修訂版本。"},{"en":"A textbook may have new editions when the syllabus changes.","zh":"當課程大綱改變，教科書可能有新版本。"},{"en":"If a children’s book sells well, publishers may produce new editions with more pictures.","zh":"如果兒童書暢銷，出版商可能製作加入更多圖片的新版本。"},{"en":"This phrase refers to later versions of a published work.","zh":"這個片語指出版作品的後來版本。"}],"source":"29 - Children’s Literature.pdf","sourcePage":9},{"front":"child-centred","meaning":"以兒童為中心的","examples":[{"en":"Each new edition became more child-centred than the last.","zh":"每個新版本都比上一版更以兒童為中心。"},{"en":"Child-centred means designed around children’s needs, interests, abilities, and experiences.","zh":"Child-centred 指圍繞兒童的需要、興趣、能力和經驗而設計。"},{"en":"A child-centred lesson lets students ask questions and learn through activities.","zh":"以兒童為中心的課堂讓學生提問並透過活動學習。"},{"en":"If a story becomes more child-centred, its characters and problems feel closer to children’s lives.","zh":"如果故事變得更以兒童為中心，它的角色和問題會更貼近兒童生活。"},{"en":"This word describes an approach that puts children first.","zh":"這個詞描述把兒童放在首位的方法。"}],"source":"29 - Children’s Literature.pdf","sourcePage":9},{"front":"from now on","meaning":"從此以後","examples":[{"en":"From now on, younger children could expect books written for them.","zh":"從此以後，較年幼兒童可以期待有為他們而寫的書。"},{"en":"From now on means starting from this point and continuing into the future.","zh":"From now on 指由這一刻開始並延續到未來。"},{"en":"From now on, students must write their names before answering the questions.","zh":"從此以後，學生必須先寫姓名再答題。"},{"en":"If children’s books became child-centred, from now on young readers had more suitable choices.","zh":"如果兒童書變得以兒童為中心，從此以後年輕讀者就有更多合適選擇。"},{"en":"This phrase marks a change that begins at a particular moment.","zh":"這個片語標示從某一刻開始的改變。"}],"source":"29 - Children’s Literature.pdf","sourcePage":9},{"front":"younger children","meaning":"較年幼兒童","examples":[{"en":"Younger children could expect stories for their own interests.","zh":"較年幼兒童可以期待有符合自己興趣的故事。"},{"en":"Younger children are children at an earlier stage of age, reading ability, and life experience.","zh":"Younger children 是年齡、閱讀能力和人生經驗較早階段的兒童。"},{"en":"Younger children often need simpler plots, clearer pictures, and familiar situations.","zh":"較年幼兒童通常需要較簡單情節、較清楚圖片和熟悉情境。"},{"en":"If books are written for younger children, they may avoid complex adult problems.","zh":"如果書是為較年幼兒童而寫，它們可能避免複雜成人問題。"},{"en":"This phrase refers to children who are not yet older or more mature readers.","zh":"這個片語指尚未成為較年長或較成熟讀者的兒童。"}],"source":"29 - Children’s Literature.pdf","sourcePage":9},{"front":"particular interest","meaning":"特定興趣","examples":[{"en":"Stories were written for children’s particular interest.","zh":"故事為兒童的特定興趣而寫。"},{"en":"Particular interest means a specific area, topic, or kind of story that someone especially likes.","zh":"Particular interest 指某人特別喜歡的特定範疇、題目或故事類型。"},{"en":"A child with a particular interest in animals may enjoy books about pets and wildlife.","zh":"對動物有特定興趣的兒童可能喜歡關於寵物和野生動物的書。"},{"en":"If writers understand children’s particular interests, stories can feel more personal and engaging.","zh":"如果作者了解兒童的特定興趣，故事會感覺更個人化和吸引。"},{"en":"This phrase focuses on specific preferences, not general liking.","zh":"這個片語著重具體偏好，而不是一般喜歡。"}],"source":"29 - Children’s Literature.pdf","sourcePage":9},{"front":"limited experience of life","meaning":"有限人生經驗","examples":[{"en":"Stories considered children’s limited experience of life.","zh":"故事考慮到兒童有限的人生經驗。"},{"en":"Limited experience of life means not yet having much knowledge of adult problems, society, or complex emotions.","zh":"Limited experience of life 指尚未對成人問題、社會或複雜情感有很多認識。"},{"en":"A young child may not understand divorce, war, or poverty without careful explanation.","zh":"年幼兒童如果沒有仔細解釋，可能不理解離婚、戰爭或貧窮。"},{"en":"If writers consider children’s limited experience of life, they explain difficult ideas more gently.","zh":"如果作者考慮兒童有限的人生經驗，他們會更溫和地解釋困難想法。"},{"en":"This phrase reminds writers that children do not see the world like adults.","zh":"這個片語提醒作者，兒童看世界的方式與成人不同。"}],"source":"29 - Children’s Literature.pdf","sourcePage":9},{"front":"kept well to the fore","meaning":"被放在十分重要的位置","examples":[{"en":"The needs of children were kept well to the fore.","zh":"兒童的需要被放在十分重要的位置。"},{"en":"To keep something well to the fore means to keep it very visible, important, and central.","zh":"To keep something well to the fore 指讓某事保持十分明顯、重要和核心。"},{"en":"A good school keeps student safety well to the fore when planning trips.","zh":"好學校在計劃旅行時，會把學生安全放在十分重要的位置。"},{"en":"If children’s needs are kept to the fore, books become easier and more enjoyable for them.","zh":"如果兒童需要被放在重要位置，書本會對他們更容易和更有趣。"},{"en":"This phrase shows that something is treated as a major priority.","zh":"這個片語顯示某事被視為主要優先事項。"}],"source":"29 - Children’s Literature.pdf","sourcePage":9},{"front":"determine the reading of","meaning":"決定……的閱讀內容","examples":[{"en":"Access to suitable characters determined the reading of older children.","zh":"接觸合適角色決定了較年長兒童的閱讀內容。"},{"en":"To determine the reading of someone means to strongly influence what they choose or are able to read.","zh":"To determine the reading of someone 指強烈影響某人選擇或能夠閱讀的內容。"},{"en":"A school library’s collection can determine the reading of students who cannot buy books.","zh":"對不能買書的學生來說，學校圖書館藏書可以決定他們的閱讀內容。"},{"en":"If older children find relatable characters, those characters may shape what books they choose.","zh":"如果較年長兒童找到能共鳴的角色，這些角色可能塑造他們選擇的書。"},{"en":"This phrase connects available material with reading choices.","zh":"這個片語把可取得材料與閱讀選擇連接起來。"}],"source":"29 - Children’s Literature.pdf","sourcePage":9},{"front":"older children","meaning":"較年長兒童","examples":[{"en":"Older children often preferred books with relatable characters.","zh":"較年長兒童常偏好有可共鳴角色的書。"},{"en":"Older children are children who have more reading ability, maturity, and life experience than younger children.","zh":"Older children 是比年幼兒童有更多閱讀能力、成熟度和人生經驗的兒童。"},{"en":"Older children may enjoy longer stories with friendship, danger, and personal choices.","zh":"較年長兒童可能喜歡包含友誼、危險和個人選擇的較長故事。"},{"en":"If books are too babyish, older children may turn to adult fiction instead.","zh":"如果書太幼稚，較年長兒童可能轉向成人小說。"},{"en":"This phrase refers to children who are moving closer to teenage or adult understanding.","zh":"這個片語指逐漸接近青少年或成人理解能力的兒童。"}],"source":"29 - Children’s Literature.pdf","sourcePage":10},{"front":"availability of","meaning":"……的可得性","examples":[{"en":"Reading was influenced by the availability of special children’s literature.","zh":"閱讀受專門兒童文學的可得性影響。"},{"en":"The availability of something means whether it can be found, accessed, or used.","zh":"Availability of something 指某物是否能被找到、接觸或使用。"},{"en":"The availability of library books can affect how much students read.","zh":"圖書館書籍的可得性可以影響學生閱讀量。"},{"en":"If children’s books are widely available, young readers have more suitable choices.","zh":"如果兒童書廣泛可得，年輕讀者就有更多合適選擇。"},{"en":"This phrase focuses on access, not only interest.","zh":"這個片語著重取得途徑，而不只是興趣。"}],"source":"29 - Children’s Literature.pdf","sourcePage":10},{"front":"as such","meaning":"本身；嚴格來說","examples":[{"en":"Special children’s literature as such was not always the deciding factor.","zh":"嚴格來說，專門兒童文學本身並不總是決定因素。"},{"en":"As such means considered strictly in that exact form or category.","zh":"As such 指嚴格按照該確切形式或類別來考慮。"},{"en":"A phone as such is not harmful; the problem is how long students use it.","zh":"手機本身並非有害；問題是學生使用多久。"},{"en":"If children did not need specially labelled books, children’s literature as such was not always essential.","zh":"如果兒童不需要特別標明的書，嚴格來說兒童文學本身未必總是必要。"},{"en":"This phrase helps separate the thing itself from related factors.","zh":"這個片語幫助把事物本身與相關因素分開。"}],"source":"29 - Children’s Literature.pdf","sourcePage":10},{"front":"access to","meaning":"接觸到；取得","examples":[{"en":"Older children’s reading depended on access to suitable books.","zh":"較年長兒童的閱讀取決於能否接觸到合適書籍。"},{"en":"Access to something means the ability or opportunity to use, reach, or obtain it.","zh":"Access to something 指使用、到達或取得某物的能力或機會。"},{"en":"Students with access to a quiet library may read more after school.","zh":"能接觸到安靜圖書館的學生，放學後可能閱讀更多。"},{"en":"If children lack access to good books, their reading choices become limited.","zh":"如果兒童缺乏取得好書的途徑，他們的閱讀選擇會受限制。"},{"en":"This phrase focuses on whether people can actually get what they need.","zh":"這個片語著重人們是否真的能取得所需東西。"}],"source":"29 - Children’s Literature.pdf","sourcePage":10},{"front":"contain characters","meaning":"包含角色","examples":[{"en":"Older children liked books that contained characters they could understand.","zh":"較年長兒童喜歡包含他們能理解的角色的書。"},{"en":"To contain characters means to include people, animals, or figures who take part in a story.","zh":"To contain characters 指包含參與故事的人物、動物或角色。"},{"en":"A school story may contain characters such as teachers, students, and parents.","zh":"校園故事可能包含老師、學生和家長等角色。"},{"en":"If a book contains characters close to children’s own lives, readers may care more about the plot.","zh":"如果一本書包含貼近兒童生活的角色，讀者可能更關心情節。"},{"en":"This phrase describes what kinds of story figures are included.","zh":"這個片語描述故事中包含甚麼類型的角色。"}],"source":"29 - Children’s Literature.pdf","sourcePage":10},{"front":"empathize with","meaning":"與……產生共鳴","examples":[{"en":"Children could more easily empathize with young people or animals.","zh":"兒童較容易與年輕人或動物產生共鳴。"},{"en":"To empathize with someone means to understand and share their feelings.","zh":"To empathize with someone 指理解並感受對方的情緒。"},{"en":"A child may empathize with a lonely character who has no friends at school.","zh":"兒童可能與在學校沒有朋友的孤獨角色產生共鳴。"},{"en":"If readers empathize with a character, they are more likely to care what happens next.","zh":"如果讀者與角色產生共鳴，他們更可能關心接下來發生甚麼。"},{"en":"This phrase describes emotional connection with another person or character.","zh":"這個片語描述與另一人或角色的情感連結。"}],"source":"29 - Children’s Literature.pdf","sourcePage":10},{"front":"make few demands on","meaning":"對……要求不高","examples":[{"en":"Action stories made few demands on adult maturity.","zh":"動作故事對成人成熟度要求不高。"},{"en":"To make few demands on someone means to require little ability, knowledge, time, or effort from them.","zh":"To make few demands on someone 指對某人的能力、知識、時間或努力要求很少。"},{"en":"A simple picture book makes few demands on a beginner reader.","zh":"簡單圖畫書對初學讀者要求不高。"},{"en":"If a story is mostly action, it may make few demands on deep adult understanding.","zh":"如果故事主要是動作，它可能對深層成人理解要求不高。"},{"en":"This phrase shows that something is easy to follow or not very demanding.","zh":"這個片語顯示某事容易跟上或要求不高。"}],"source":"29 - Children’s Literature.pdf","sourcePage":10},{"front":"adult maturity","meaning":"成人成熟度","examples":[{"en":"Some action stories did not require adult maturity.","zh":"一些動作故事不需要成人成熟度。"},{"en":"Adult maturity means the emotional understanding, judgment, and life experience usually associated with adults.","zh":"Adult maturity 指通常與成人相關的情感理解、判斷力和人生經驗。"},{"en":"A story about tax problems may require more adult maturity than a simple adventure.","zh":"關於稅務問題的故事，可能比簡單冒險故事需要更多成人成熟度。"},{"en":"If a book avoids complex moral choices, younger readers may enjoy it without adult maturity.","zh":"如果一本書避免複雜道德選擇，較年輕讀者可以不需成人成熟度也享受它。"},{"en":"This phrase refers to mature understanding, not simply being old.","zh":"這個片語指成熟理解，而不只是年紀大。"}],"source":"29 - Children’s Literature.pdf","sourcePage":10},{"front":"adult understanding","meaning":"成人理解能力","examples":[{"en":"Some books made few demands on adult understanding.","zh":"一些書對成人理解能力要求不高。"},{"en":"Adult understanding means the knowledge and insight needed to grasp mature ideas or complex life situations.","zh":"Adult understanding 指理解成熟想法或複雜人生情境所需的知識和洞察力。"},{"en":"A simple adventure story may not require adult understanding because the goals are clear.","zh":"簡單冒險故事可能不需要成人理解能力，因為目標很清楚。"},{"en":"If a novel deals with marriage, politics, or grief, it may need more adult understanding.","zh":"如果小說處理婚姻、政治或悲傷，它可能需要更多成人理解能力。"},{"en":"This phrase contrasts mature comprehension with a child’s simpler viewpoint.","zh":"這個片語把成熟理解與兒童較簡單的視角作對比。"}],"source":"29 - Children’s Literature.pdf","sourcePage":10},{"front":"final apotheosis","meaning":"最終極致","examples":[{"en":"The final apotheosis of literary childhood came in the late 1930s.","zh":"文學中的童年最終極致出現在1930年代後期。"},{"en":"Final apotheosis means the highest or most complete form of something at its final stage.","zh":"Final apotheosis 指某事在最後階段達到最高或最完整形式。"},{"en":"A school play may be the final apotheosis of months of drama practice.","zh":"學校劇目可能是數月戲劇練習的最終極致。"},{"en":"If children’s books became completely escapist and child-centred, that could be seen as an apotheosis of literary childhood.","zh":"如果兒童書變得完全逃避現實並以兒童為中心，那可被視為文學童年的極致。"},{"en":"This phrase sounds formal and means a peak or ultimate expression.","zh":"這個片語較正式，意思是高峰或終極表現。"}],"source":"29 - Children’s Literature.pdf","sourcePage":10},{"front":"literary childhood","meaning":"文學中的童年","examples":[{"en":"Literary childhood was increasingly protected from unpleasant reality.","zh":"文學中的童年越來越免受不愉快現實影響。"},{"en":"Literary childhood means the idea or image of childhood created and represented in books.","zh":"Literary childhood 指書本中創造和呈現的童年想法或形象。"},{"en":"In some stories, literary childhood is full of safety, friendship, and adventure.","zh":"在一些故事中，文學中的童年充滿安全、友誼和冒險。"},{"en":"If books hide war, poverty, and danger, they create a protected version of childhood.","zh":"如果書籍隱藏戰爭、貧窮和危險，它們就創造出受保護的童年版本。"},{"en":"This phrase refers to childhood as imagined in literature, not real childhood itself.","zh":"這個片語指文學中想像的童年，而不是真實童年本身。"}],"source":"29 - Children’s Literature.pdf","sourcePage":11},{"front":"be protected from","meaning":"免受……","examples":[{"en":"Literary childhood was protected from unpleasant reality.","zh":"文學中的童年免受不愉快現實影響。"},{"en":"To be protected from something means to be kept safe from it or shielded from its effects.","zh":"To be protected from something 指被保護而免受某事或其影響。"},{"en":"Children are protected from traffic by safe crossings and careful adults.","zh":"安全過路處和細心成人保護兒童免受交通危險。"},{"en":"If a story protects children from harsh reality, it may avoid war, death, or poverty.","zh":"如果故事保護兒童免受殘酷現實影響，它可能避免戰爭、死亡或貧窮。"},{"en":"This phrase shows that danger or difficulty is being kept away.","zh":"這個片語顯示危險或困難被隔開。"}],"source":"29 - Children’s Literature.pdf","sourcePage":11},{"front":"unpleasant reality","meaning":"不愉快的現實","examples":[{"en":"Escapist children’s books avoided unpleasant reality.","zh":"逃避現實式兒童書避開不愉快的現實。"},{"en":"Unpleasant reality means difficult, painful, or uncomfortable facts about life.","zh":"Unpleasant reality 指生活中困難、痛苦或令人不舒服的事實。"},{"en":"Illness, poverty, family conflict, and war can be unpleasant realities in a child’s world.","zh":"疾病、貧窮、家庭衝突和戰爭都可能是兒童世界中的不愉快現實。"},{"en":"If a book avoids unpleasant reality, it may feel safe but less honest.","zh":"如果一本書避開不愉快的現實，它可能感覺安全但不夠誠實。"},{"en":"This phrase contrasts real difficulty with comforting fantasy.","zh":"這個片語把真實困難與安慰性的幻想作對比。"}],"source":"29 - Children’s Literature.pdf","sourcePage":11},{"front":"child-centred bestsellers","meaning":"以兒童為中心的暢銷書","examples":[{"en":"Child-centred bestsellers appeared in the late 1930s.","zh":"以兒童為中心的暢銷書出現在1930年代後期。"},{"en":"Child-centred bestsellers are very popular books that strongly focus on children’s interests and viewpoint.","zh":"Child-centred bestsellers 是非常受歡迎，並強烈聚焦兒童興趣和視角的書。"},{"en":"A bestseller about children solving mysteries without adults may be child-centred.","zh":"一本關於兒童在沒有成人協助下解謎的暢銷書，可能是以兒童為中心的。"},{"en":"If many children buy or borrow the same adventure series, it can become a child-centred bestseller.","zh":"如果許多兒童購買或借閱同一套冒險系列，它可以成為以兒童為中心的暢銷書。"},{"en":"This phrase combines popularity with a focus on young readers.","zh":"這個片語把受歡迎程度與對年輕讀者的聚焦結合起來。"}],"source":"29 - Children’s Literature.pdf","sourcePage":11},{"front":"be intent on","meaning":"致力於；以……為目的","examples":[{"en":"These bestsellers were intent on entertainment.","zh":"這些暢銷書致力於娛樂。"},{"en":"To be intent on something means to be strongly focused on achieving it.","zh":"To be intent on something 指強烈專注於達成某事。"},{"en":"A student intent on improving pronunciation may practise aloud every day.","zh":"致力於改善發音的學生可能每天大聲練習。"},{"en":"If a book is intent on entertainment, it may avoid heavy lessons or serious problems.","zh":"如果一本書以娛樂為目的，它可能避免沉重教訓或嚴肅問題。"},{"en":"This phrase shows strong purpose or determination.","zh":"這個片語顯示強烈目的或決心。"}],"source":"29 - Children’s Literature.pdf","sourcePage":11},{"front":"escapist entertainment","meaning":"逃避現實式娛樂","examples":[{"en":"The books offered entertainment at its most escapist.","zh":"這些書提供最逃避現實式的娛樂。"},{"en":"Escapist entertainment helps people forget real-life problems by entering a safer or more exciting imaginary world.","zh":"Escapist entertainment 透過讓人進入更安全或更刺激的想像世界，幫助人忘記現實問題。"},{"en":"A fantasy film can provide escapist entertainment after a stressful exam week.","zh":"在壓力大的考試週後，奇幻電影可以提供逃避現實式娛樂。"},{"en":"If stories avoid war and poverty completely, they may become pure escapist entertainment.","zh":"如果故事完全避開戰爭和貧窮，它們可能變成純粹逃避現實式娛樂。"},{"en":"This phrase describes entertainment that moves away from reality.","zh":"這個片語描述遠離現實的娛樂。"}],"source":"29 - Children’s Literature.pdf","sourcePage":11},{"front":"novelists such as","meaning":"例如……的小說家","examples":[{"en":"Novelists such as Enid Blyton described children having adventures.","zh":"例如Enid Blyton的小說家描寫兒童經歷冒險。"},{"en":"Novelists such as someone means writers of novels, with that person given as an example.","zh":"Novelists such as someone 指小說作家，並以某人作為例子。"},{"en":"Novelists such as Dickens often created memorable child characters.","zh":"例如Dickens的小說家常創造令人難忘的兒童角色。"},{"en":"If a writer says “novelists such as Enid Blyton”, they are naming one example from a wider group.","zh":"如果作者說 “novelists such as Enid Blyton”，他是在較大群體中舉出一個例子。"},{"en":"This phrase introduces examples of authors.","zh":"這個片語引出作者例子。"}],"source":"29 - Children’s Literature.pdf","sourcePage":11},{"front":"unlikely adventures","meaning":"不大可能發生的冒險","examples":[{"en":"The children in these books had unlikely adventures.","zh":"這些書中的兒童經歷不大可能發生的冒險。"},{"en":"Unlikely adventures are exciting events that are not very probable in real life.","zh":"Unlikely adventures 是現實中不太可能發生的刺激事件。"},{"en":"Children finding hidden treasure under a school garden would be an unlikely adventure.","zh":"兒童在學校花園地下找到寶藏，就是不大可能發生的冒險。"},{"en":"If adventures are unlikely but safe, readers can enjoy excitement without real fear.","zh":"如果冒險不太可能但安全，讀者可以享受刺激而沒有真正恐懼。"},{"en":"This phrase describes imaginative events that feel thrilling but unrealistic.","zh":"這個片語描述令人興奮但不現實的想像事件。"}],"source":"29 - Children’s Literature.pdf","sourcePage":11},{"front":"secure in the knowledge that","meaning":"深知……而安心","examples":[{"en":"The characters were secure in the knowledge that nothing bad would happen.","zh":"角色深知不會有壞事發生而安心。"},{"en":"Secure in the knowledge that means feeling safe and confident because one believes something is true.","zh":"Secure in the knowledge that 指因相信某事為真而感到安全和有信心。"},{"en":"A child may sleep calmly, secure in the knowledge that a parent is nearby.","zh":"孩子深知父母在附近而安心，可以平靜入睡。"},{"en":"If readers are secure in the knowledge that heroes will survive, danger feels less frightening.","zh":"如果讀者深知英雄會生還而安心，危險就感覺較不恐怖。"},{"en":"This phrase describes confidence based on reassurance.","zh":"這個片語描述基於安心保證的信心。"}],"source":"29 - Children’s Literature.pdf","sourcePage":11},{"front":"in the end","meaning":"最終","examples":[{"en":"Nothing bad could ever happen to them in the end.","zh":"最終不會有任何壞事發生在他們身上。"},{"en":"In the end means finally, after everything has happened.","zh":"In the end 指最後，在所有事情發生之後。"},{"en":"The students were nervous before the play, but in the end everyone performed well.","zh":"學生在話劇前很緊張，但最終每個人都表現良好。"},{"en":"If a story promises safety in the end, readers expect problems to be solved.","zh":"如果故事承諾最終安全，讀者會期待問題被解決。"},{"en":"This phrase points to the final result.","zh":"這個片語指出最後結果。"}],"source":"29 - Children’s Literature.pdf","sourcePage":11},{"front":"break out","meaning":"爆發","examples":[{"en":"War broke out again during Enid Blyton’s greatest popularity.","zh":"在Enid Blyton最受歡迎期間，戰爭再次爆發。"},{"en":"To break out means to begin suddenly, especially a war, fire, disease, or conflict.","zh":"To break out 指突然開始，尤其是戰爭、火災、疾病或衝突。"},{"en":"A fight may break out in the playground if no teacher intervenes.","zh":"如果沒有老師介入，操場上可能爆發打鬥。"},{"en":"If war breaks out, daily life can change quickly and violently.","zh":"如果戰爭爆發，日常生活可能迅速而劇烈地改變。"},{"en":"This phrase describes the sudden start of something serious.","zh":"這個片語描述嚴重事件的突然開始。"}],"source":"29 - Children’s Literature.pdf","sourcePage":12},{"front":"fail to register","meaning":"未有顯現；未被察覺","examples":[{"en":"The war fails to register in Blyton’s fictional world.","zh":"戰爭在Blyton的虛構世界中未有顯現。"},{"en":"To fail to register means not to appear, be noticed, or have an effect in someone’s mind or a setting.","zh":"To fail to register 指沒有出現、沒有被注意到，或沒有在某人腦中或某背景中產生影響。"},{"en":"A teacher’s warning may fail to register if students are too excited before a trip.","zh":"如果學生在旅行前太興奮，老師的警告可能未被察覺。"},{"en":"If war fails to register in a story, the fictional world feels separate from real history.","zh":"如果戰爭在故事中未有顯現，虛構世界就感覺與真實歷史分離。"},{"en":"This phrase means something important is absent or unnoticed.","zh":"這個片語意思是重要事物缺席或未被注意。"}],"source":"29 - Children’s Literature.pdf","sourcePage":12},{"front":"self-enclosed world","meaning":"封閉自足的世界","examples":[{"en":"Enid Blyton’s young characters lived in a self-enclosed world.","zh":"Enid Blyton的年輕角色生活在封閉自足的世界。"},{"en":"A self-enclosed world is a fictional or social world that feels separate from outside reality.","zh":"Self-enclosed world 是一個感覺與外部現實分離的虛構或社會世界。"},{"en":"A boarding-school story may create a self-enclosed world with its own rules and friendships.","zh":"寄宿學校故事可能創造一個有自己規則和友誼的封閉自足世界。"},{"en":"If a story world is self-enclosed, real historical events may not affect it.","zh":"如果故事世界封閉自足，真實歷史事件可能不影響它。"},{"en":"This phrase describes a closed, protected setting.","zh":"這個片語描述封閉而受保護的背景。"}],"source":"29 - Children’s Literature.pdf","sourcePage":12},{"front":"reaction against","meaning":"對……的反彈","examples":[{"en":"Reaction against such dream-worlds was inevitable after World War II.","zh":"第二次世界大戰後，對這類夢幻世界的反彈不可避免。"},{"en":"A reaction against something is a strong response that rejects or opposes it.","zh":"Reaction against something 是拒絕或反對某事的強烈反應。"},{"en":"Students may show a reaction against boring drills by asking for more discussion.","zh":"學生可能透過要求更多討論，表現出對沉悶操練的反彈。"},{"en":"If children’s books ignore real suffering, later writers may react against that fantasy.","zh":"如果兒童書忽視真實痛苦，後來作者可能反彈並反對那種幻想。"},{"en":"This phrase describes a movement away from an earlier style or idea.","zh":"這個片語描述從早期風格或想法中轉離的運動。"}],"source":"29 - Children’s Literature.pdf","sourcePage":12},{"front":"dream-worlds","meaning":"夢幻世界","examples":[{"en":"Post-war writers reacted against such dream-worlds.","zh":"戰後作家反對這類夢幻世界。"},{"en":"Dream-worlds are imagined settings that feel safe, unreal, and separated from ordinary problems.","zh":"Dream-worlds 是感覺安全、不真實並與普通問題分離的想像背景。"},{"en":"A story where children always win and adults never worry can feel like a dream-world.","zh":"如果故事中兒童總是勝利而成人從不擔心，它就可能像夢幻世界。"},{"en":"If books offer only dream-worlds, readers may not meet real social difficulties in fiction.","zh":"如果書只提供夢幻世界，讀者可能不會在小說中接觸真實社會困難。"},{"en":"This phrase refers to comforting fantasy settings.","zh":"這個片語指令人安慰的幻想背景。"}],"source":"29 - Children’s Literature.pdf","sourcePage":12},{"front":"coincide with","meaning":"與……同時發生","examples":[{"en":"The reaction coincided with the growth of paperback sales.","zh":"這種反彈與平裝書銷售增長同時發生。"},{"en":"To coincide with something means to happen at the same time as it.","zh":"To coincide with something 指與某事在同一時間發生。"},{"en":"A school’s open day may coincide with the start of the new term.","zh":"學校開放日可能與新學期開始同時發生。"},{"en":"If a literary change coincides with cheaper books, more readers may be reached.","zh":"如果文學變化與較便宜書籍同時發生，就可能接觸到更多讀者。"},{"en":"This phrase shows that two events happen together in time.","zh":"這個片語顯示兩件事在時間上同時出現。"}],"source":"29 - Children’s Literature.pdf","sourcePage":12},{"front":"paperback sales","meaning":"平裝書銷售","examples":[{"en":"The growth of paperback sales changed children’s publishing.","zh":"平裝書銷售增長改變了兒童出版。"},{"en":"Paperback sales are the sales of books with soft covers rather than hard covers.","zh":"Paperback sales 是軟封面書籍，而不是硬封面書籍的銷售。"},{"en":"Paperback sales may rise when cheaper editions make books affordable for more families.","zh":"當較便宜版本令更多家庭負擔得起書籍，平裝書銷售可能上升。"},{"en":"If paperback sales grow, publishers can reach children outside wealthy households.","zh":"如果平裝書銷售增長，出版商可以接觸到富裕家庭以外的兒童。"},{"en":"This phrase connects book format with access and market growth.","zh":"這個片語把書籍形式與取得途徑和市場增長連接起來。"}],"source":"29 - Children’s Literature.pdf","sourcePage":12},{"front":"children’s libraries","meaning":"兒童圖書館","examples":[{"en":"Children’s libraries expanded after World War II.","zh":"兒童圖書館在第二次世界大戰後擴展。"},{"en":"Children’s libraries are library sections or institutions designed for young readers.","zh":"Children’s libraries 是為年輕讀者而設的圖書館部門或機構。"},{"en":"A children’s library may offer picture books, storytelling sessions, and reading clubs.","zh":"兒童圖書館可能提供圖畫書、講故事活動和閱讀會。"},{"en":"If children’s libraries expand, more children can borrow books without buying them.","zh":"如果兒童圖書館擴展，更多兒童不用買書也能借閱。"},{"en":"This phrase refers to public reading spaces for children.","zh":"這個片語指給兒童使用的公共閱讀空間。"}],"source":"29 - Children’s Literature.pdf","sourcePage":12},{"front":"moral and social concern","meaning":"道德和社會關懷","examples":[{"en":"A new spirit of moral and social concern influenced writers.","zh":"一種新的道德和社會關懷精神影響了作家。"},{"en":"Moral and social concern means interest in ethical behaviour and problems affecting society.","zh":"Moral and social concern 指對倫理行為和影響社會的問題感興趣。"},{"en":"A story about bullying shows moral and social concern because it asks how people treat one another.","zh":"關於欺凌的故事顯示道德和社會關懷，因為它詢問人們如何對待彼此。"},{"en":"If writers feel social concern, they may include poverty, prejudice, or family problems in children’s books.","zh":"如果作家有社會關懷，他們可能在兒童書中加入貧窮、偏見或家庭問題。"},{"en":"This phrase connects literature with responsibility toward society.","zh":"這個片語把文學與對社會的責任連接起來。"}],"source":"29 - Children’s Literature.pdf","sourcePage":12},{"front":"urged on by","meaning":"在……推動下","examples":[{"en":"Writers were urged on by committed publishers and progressive librarians.","zh":"作家在有使命感的出版商和進步圖書館員推動下前進。"},{"en":"To be urged on by someone means to be encouraged, pushed, or supported by them.","zh":"To be urged on by someone 指受到某人鼓勵、推動或支持。"},{"en":"A shy student may be urged on by friends to join a speech competition.","zh":"害羞學生可能在朋友推動下參加演講比賽。"},{"en":"If publishers urge writers on, writers may try bolder themes and settings.","zh":"如果出版商推動作家，作家可能嘗試更大膽的主題和背景。"},{"en":"This phrase shows encouragement that moves someone forward.","zh":"這個片語顯示推動某人前進的鼓勵。"}],"source":"29 - Children’s Literature.pdf","sourcePage":12},{"front":"committed publishers","meaning":"有使命感的出版商","examples":[{"en":"Committed publishers encouraged new kinds of children’s writing.","zh":"有使命感的出版商鼓勵新的兒童寫作種類。"},{"en":"Committed publishers are publishers who seriously believe in a purpose and work hard for it.","zh":"Committed publishers 是認真相信某目的並努力實踐的出版商。"},{"en":"A committed publisher may support difficult but important books even if sales are uncertain.","zh":"有使命感的出版商可能支持困難但重要的書，即使銷量不確定。"},{"en":"If publishers are committed to social themes, they may help writers discuss real problems.","zh":"如果出版商致力於社會主題，他們可能幫助作家討論真實問題。"},{"en":"This phrase describes publishers with dedication, not casual interest.","zh":"這個片語描述有投入感的出版商，而不是只有隨意興趣。"}],"source":"29 - Children’s Literature.pdf","sourcePage":13},{"front":"progressive librarians","meaning":"進步圖書館員","examples":[{"en":"Progressive librarians encouraged writers to explore new areas.","zh":"進步圖書館員鼓勵作家探索新範疇。"},{"en":"Progressive librarians are librarians open to new ideas, social change, and broader reading choices for children.","zh":"Progressive librarians 是對新想法、社會改變和更廣泛兒童閱讀選擇持開放態度的圖書館員。"},{"en":"A progressive librarian may recommend books about different families, cultures, and social problems.","zh":"進步圖書館員可能推薦關於不同家庭、文化和社會問題的書。"},{"en":"If librarians are progressive, they may challenge old ideas about what children should read.","zh":"如果圖書館員進步，他們可能挑戰兒童應閱讀甚麼的舊想法。"},{"en":"This phrase describes librarians who support change and inclusion.","zh":"這個片語描述支持改變和包容的圖書館員。"}],"source":"29 - Children’s Literature.pdf","sourcePage":13},{"front":"explore new areas of interest","meaning":"探索新的興趣範圍","examples":[{"en":"Writers began to explore new areas of interest.","zh":"作家開始探索新的興趣範圍。"},{"en":"To explore new areas of interest means to begin writing or thinking about new topics and concerns.","zh":"To explore new areas of interest 指開始書寫或思考新的題目和關注點。"},{"en":"A teacher may explore new areas of interest by adding environmental topics to English lessons.","zh":"老師可能透過把環境題目加入英文課，探索新的興趣範圍。"},{"en":"If writers explore social issues, children’s books may become more realistic.","zh":"如果作家探索社會議題，兒童書可能變得更貼近現實。"},{"en":"This phrase describes moving beyond familiar subjects.","zh":"這個片語描述超越熟悉題材。"}],"source":"29 - Children’s Literature.pdf","sourcePage":13},{"front":"shift the settings of","meaning":"轉移……的背景","examples":[{"en":"Writers shifted the settings of their plots from middle-class worlds.","zh":"作家把情節背景從中產世界轉移出去。"},{"en":"To shift the settings of plots means to move story backgrounds from one kind of place or society to another.","zh":"To shift the settings of plots 指把故事背景從一種地方或社會轉移到另一種。"},{"en":"A writer may shift a story’s setting from a private school to a crowded city estate.","zh":"作家可能把故事背景從私立學校轉移到擁擠城市屋邨。"},{"en":"If settings shift, readers may meet new kinds of characters and problems.","zh":"如果背景轉移，讀者可能遇到新的角色和問題。"},{"en":"This phrase describes a change in where stories take place.","zh":"這個片語描述故事發生地點的改變。"}],"source":"29 - Children’s Literature.pdf","sourcePage":13},{"front":"plots","meaning":"情節","examples":[{"en":"Writers changed the settings of their plots.","zh":"作家改變了情節的背景。"},{"en":"Plots are the main events and structure of stories.","zh":"Plots 是故事的主要事件和結構。"},{"en":"A mystery plot may begin with a missing object and end with the truth being discovered.","zh":"懸疑情節可能由失物開始，並以真相被發現結束。"},{"en":"If a plot moves from home to school to a strange town, the story becomes more active.","zh":"如果情節從家中移到學校，再到陌生城鎮，故事會變得更活躍。"},{"en":"This word refers to what happens in a story and how events are arranged.","zh":"這個詞指故事中發生甚麼，以及事件如何排列。"}],"source":"29 - Children’s Literature.pdf","sourcePage":13},{"front":"middle-class world","meaning":"中產世界","examples":[{"en":"Earlier children’s books were often set in a middle-class world.","zh":"較早期兒童書常以中產世界為背景。"},{"en":"A middle-class world is a setting based on comfortable families, stable homes, education, and respectable social habits.","zh":"Middle-class world 是以舒適家庭、穩定住屋、教育和體面社會習慣為基礎的背景。"},{"en":"A story about children in a large house with servants may show a middle-class world.","zh":"關於住在大屋並有僕人的兒童故事，可能呈現中產世界。"},{"en":"If all books show only middle-class worlds, poorer children may not see their lives reflected.","zh":"如果所有書只展示中產世界，較貧窮兒童可能看不到自己生活被反映。"},{"en":"This phrase describes a social setting, not just an income level.","zh":"這個片語描述社會背景，而不只是收入水平。"}],"source":"29 - Children’s Literature.pdf","sourcePage":13},{"front":"chiefly adult patrons","meaning":"主要的成人支持者","examples":[{"en":"Children’s literature had previously served chiefly adult patrons.","zh":"兒童文學以前主要服務成人支持者。"},{"en":"Chiefly adult patrons means mainly the adults who bought, approved, or supported the books.","zh":"Chiefly adult patrons 指主要購買、批准或支持書籍的成年人。"},{"en":"In the past, parents and teachers often acted as adult patrons of children’s reading.","zh":"過去，父母和老師常作為兒童閱讀的成人支持者。"},{"en":"If books serve adult patrons more than children, they may stress morality over enjoyment.","zh":"如果書籍服務成人支持者多於兒童，它們可能強調道德多於樂趣。"},{"en":"This phrase shows that adults controlled much of children’s literature.","zh":"這個片語顯示成人控制了很多兒童文學。"}],"source":"29 - Children’s Literature.pdf","sourcePage":13},{"front":"critical emphasis","meaning":"評論重點","examples":[{"en":"Critical emphasis during this development was divided.","zh":"在這個發展期間，評論重點出現分歧。"},{"en":"Critical emphasis means what critics focus on most when judging or discussing something.","zh":"Critical emphasis 指批評家在評價或討論某事時最著重的地方。"},{"en":"In reviewing a film, critical emphasis may fall on acting, story, or social message.","zh":"評論電影時，評論重點可能落在演技、故事或社會訊息上。"},{"en":"If critical emphasis changes, people may value different qualities in children’s books.","zh":"如果評論重點改變，人們可能重視兒童書中的不同質素。"},{"en":"This phrase describes the main focus of criticism.","zh":"這個片語描述批評的主要焦點。"}],"source":"29 - Children’s Literature.pdf","sourcePage":13},{"front":"be divided","meaning":"出現分歧","examples":[{"en":"Critical emphasis was divided between two concerns.","zh":"評論重點在兩種關注之間出現分歧。"},{"en":"To be divided means to be split between different choices, opinions, or directions.","zh":"To be divided 指在不同選擇、意見或方向之間分裂。"},{"en":"A class may be divided over whether homework should be done online or on paper.","zh":"一個班可能對功課應網上完成還是紙本完成出現分歧。"},{"en":"If critics are divided, they may praise a book’s style but question its social values.","zh":"如果批評家出現分歧，他們可能讚賞一本書的風格，但質疑其社會價值。"},{"en":"This phrase shows disagreement or separation between viewpoints.","zh":"這個片語顯示觀點之間的不一致或分離。"}],"source":"29 - Children’s Literature.pdf","sourcePage":13},{"front":"rid something of","meaning":"使……擺脫","examples":[{"en":"Some critics wanted to rid children’s books of social prejudice.","zh":"一些批評家希望使兒童書擺脫社會偏見。"},{"en":"To rid something of a problem means to remove that problem from it.","zh":"To rid something of a problem 指從某物中移除該問題。"},{"en":"A school may try to rid its playground of bullying by setting clear rules.","zh":"學校可能透過訂立清晰規則，嘗試使操場擺脫欺凌。"},{"en":"If children’s books are rid of prejudice, more readers can feel respected and included.","zh":"如果兒童書擺脫偏見，更多讀者可以感到被尊重和被包括。"},{"en":"This phrase describes removing something harmful or unwanted.","zh":"這個片語描述移除有害或不想要的東西。"}],"source":"29 - Children’s Literature.pdf","sourcePage":13},{"front":"social prejudice","meaning":"社會偏見","examples":[{"en":"Critics wanted to remove social prejudice from children’s books.","zh":"批評家希望從兒童書中移除社會偏見。"},{"en":"Social prejudice means unfair attitudes toward people because of class, race, gender, background, or other social differences.","zh":"Social prejudice 指因階級、種族、性別、背景或其他社會差異而對人有不公平態度。"},{"en":"A story shows social prejudice if poor characters are always treated as less worthy.","zh":"如果故事總把貧窮角色描寫成較不值得尊重，它就顯示社會偏見。"},{"en":"If books repeat social prejudice, children may learn unfair ideas without noticing.","zh":"如果書本重複社會偏見，兒童可能在不察覺下學到不公平想法。"},{"en":"This phrase refers to unfair social judgment.","zh":"這個片語指不公平的社會判斷。"}],"source":"29 - Children’s Literature.pdf","sourcePage":14},{"front":"exclusiveness","meaning":"排他性","examples":[{"en":"Some critics opposed exclusiveness in children’s books.","zh":"一些批評家反對兒童書中的排他性。"},{"en":"Exclusiveness means keeping certain people out or making only one group feel included.","zh":"Exclusiveness 指把某些人排除在外，或只令某一群體感到被包括。"},{"en":"A club shows exclusiveness if only wealthy students feel welcome there.","zh":"如果一個社團只令富裕學生感到受歡迎，它就顯示排他性。"},{"en":"If children’s books show only one social class, they may create a sense of exclusiveness.","zh":"如果兒童書只展示一個社會階級，它們可能造成排他感。"},{"en":"This word describes narrow inclusion and social exclusion.","zh":"這個詞描述狹窄包容和社會排除。"}],"source":"29 - Children’s Literature.pdf","sourcePage":14},{"front":"no longer found acceptable","meaning":"不再被認為可以接受","examples":[{"en":"Social prejudice was no longer found acceptable.","zh":"社會偏見不再被認為可以接受。"},{"en":"No longer found acceptable means people stopped thinking something was suitable, fair, or tolerable.","zh":"No longer found acceptable 指人們不再認為某事合適、公平或可容忍。"},{"en":"In many schools, laughing at a student’s accent is no longer found acceptable.","zh":"在許多學校，嘲笑學生口音不再被認為可以接受。"},{"en":"If society changes, old stereotypes in books may no longer be considered acceptable.","zh":"如果社會改變，書中的舊刻板印象可能不再被認為可以接受。"},{"en":"This phrase shows a shift in moral or social standards.","zh":"這個片語顯示道德或社會標準的轉變。"}],"source":"29 - Children’s Literature.pdf","sourcePage":14},{"front":"concentrate on","meaning":"集中於","examples":[{"en":"Other critics concentrated on the achievements of contemporary literature.","zh":"其他批評家集中於當代文學的成就。"},{"en":"To concentrate on something means to focus attention on it.","zh":"To concentrate on something 指把注意力集中在某事上。"},{"en":"A student should concentrate on the main idea before choosing a paragraph heading.","zh":"學生應先集中於主要意思，再選段落標題。"},{"en":"If critics concentrate on literary quality, they may discuss style, character, and structure.","zh":"如果批評家集中於文學質素，他們可能討論風格、角色和結構。"},{"en":"This phrase describes focused attention.","zh":"這個片語描述集中注意力。"}],"source":"29 - Children’s Literature.pdf","sourcePage":14},{"front":"positive achievements","meaning":"正面成就","examples":[{"en":"Some critics valued the positive achievements of contemporary children’s literature.","zh":"一些批評家重視當代兒童文學的正面成就。"},{"en":"Positive achievements are successful and valuable results or developments.","zh":"Positive achievements 是成功且有價值的結果或發展。"},{"en":"A school’s positive achievements may include better reading scores and happier students.","zh":"學校的正面成就可能包括閱讀分數提高和學生更快樂。"},{"en":"If children’s books become more inclusive and imaginative, critics may praise these achievements.","zh":"如果兒童書變得更包容和更有想像力，批評家可能讚揚這些成就。"},{"en":"This phrase focuses on what has been gained, not what is wrong.","zh":"這個片語著重已獲得的成果，而不是問題。"}],"source":"29 - Children’s Literature.pdf","sourcePage":14},{"front":"contemporary children’s literature","meaning":"當代兒童文學","examples":[{"en":"Contemporary children’s literature gained critical attention.","zh":"當代兒童文學獲得評論關注。"},{"en":"Contemporary children’s literature means children’s books written in the present period or recent times.","zh":"Contemporary children’s literature 指現時或近代寫成的兒童書。"},{"en":"Contemporary children’s literature may include stories about modern schools, families, technology, and social issues.","zh":"當代兒童文學可能包括關於現代學校、家庭、科技和社會議題的故事。"},{"en":"If contemporary books deal with real problems, adults may read them as well as children.","zh":"如果當代書籍處理真實問題，成人和兒童都可能閱讀它們。"},{"en":"This phrase refers to modern children’s writing.","zh":"這個片語指現代兒童寫作。"}],"source":"29 - Children’s Literature.pdf","sourcePage":14},{"front":"be recommended to","meaning":"被推薦給","examples":[{"en":"These works are now recommended to adult readers as well.","zh":"這些作品現在也被推薦給成人讀者。"},{"en":"To be recommended to someone means to be suggested as suitable or worth reading, using, or trying.","zh":"To be recommended to someone 指被建議為適合或值得閱讀、使用或嘗試。"},{"en":"A teacher may recommend a simple novel to students who want to build confidence.","zh":"老師可能向想建立信心的學生推薦一本簡單小說。"},{"en":"If children’s books are recommended to adults, they likely offer depth beyond childhood entertainment.","zh":"如果兒童書被推薦給成人，它們很可能有超越兒童娛樂的深度。"},{"en":"This phrase shows that someone thinks a work is valuable for a certain audience.","zh":"這個片語顯示某人認為某作品對特定讀者有價值。"}],"source":"29 - Children’s Literature.pdf","sourcePage":14},{"front":"adult as well as child readers","meaning":"成人以及兒童讀者","examples":[{"en":"Children’s books may appeal to adult as well as child readers.","zh":"兒童書可能吸引成人以及兒童讀者。"},{"en":"Adult as well as child readers means both grown-up readers and young readers.","zh":"Adult as well as child readers 指成年讀者和年輕讀者兩者。"},{"en":"A well-written picture book can move adult as well as child readers.","zh":"一本寫得好的圖畫書可以感動成人以及兒童讀者。"},{"en":"If a story has simple language but deep emotion, it may reach both age groups.","zh":"如果故事語言簡單但情感深刻，它可能接觸到兩個年齡群體。"},{"en":"This phrase emphasises that children’s literature can cross age boundaries.","zh":"這個片語強調兒童文學可以跨越年齡界線。"}],"source":"29 - Children’s Literature.pdf","sourcePage":14},{"front":"echo","meaning":"呼應","examples":[{"en":"This attitude echoes a 19th-century belief.","zh":"這種態度呼應了19世紀的一種信念。"},{"en":"To echo something means to repeat, resemble, or remind people of an earlier idea or sound.","zh":"To echo something 指重複、相似於或令人想起較早的想法或聲音。"},{"en":"A modern school rule may echo an older belief about discipline.","zh":"現代校規可能呼應較早關於紀律的信念。"},{"en":"If a critic says children’s books are for all ages, that view may echo earlier ideas about shared reading.","zh":"如果批評家說兒童書適合所有年齡，那種看法可能呼應早期關於共享閱讀的想法。"},{"en":"This verb shows similarity between present and past thinking.","zh":"這個動詞顯示現在與過去思想之間的相似。"}],"source":"29 - Children’s Literature.pdf","sourcePage":14},{"front":"shared by the generations","meaning":"由不同世代共享","examples":[{"en":"Children’s literature can be shared by the generations.","zh":"兒童文學可以由不同世代共享。"},{"en":"Shared by the generations means enjoyed or used by grandparents, parents, children, and younger people together.","zh":"Shared by the generations 指祖父母、父母、兒童和年輕人一起享受或使用。"},{"en":"A family story read at bedtime for decades can be shared by the generations.","zh":"一個連續數十年在睡前朗讀的家庭故事，可以由不同世代共享。"},{"en":"If a book speaks to both adults and children, it can connect different age groups.","zh":"如果一本書同時打動成人和兒童，它可以連接不同年齡群體。"},{"en":"This phrase describes literature that crosses generational boundaries.","zh":"這個片語描述跨越世代界線的文學。"}],"source":"29 - Children’s Literature.pdf","sourcePage":14},{"front":"rather than","meaning":"而不是","examples":[{"en":"Children’s literature can be shared rather than used as a barrier.","zh":"兒童文學可以被共享，而不是被用作屏障。"},{"en":"Rather than shows contrast and means instead of.","zh":"Rather than 表示對比，意思是「而不是」。"},{"en":"A teacher may explain a mistake gently rather than shame a student in front of the class.","zh":"老師可能溫和解釋錯誤，而不是在全班面前羞辱學生。"},{"en":"If books are shared rather than separated by age, families may read and discuss them together.","zh":"如果書籍被共享，而不是按年齡分隔，家庭可能一起閱讀和討論。"},{"en":"This phrase helps show one choice replacing another.","zh":"這個片語幫助顯示一個選擇取代另一個。"}],"source":"29 - Children’s Literature.pdf","sourcePage":15},{"front":"defensive barrier","meaning":"防衛性屏障","examples":[{"en":"Children’s literature should not be a defensive barrier between childhood and adulthood.","zh":"兒童文學不應成為童年與成年之間的防衛性屏障。"},{"en":"A defensive barrier is something used to protect or separate one group from another in a guarded way.","zh":"Defensive barrier 是用來以防衛方式保護或分隔一個群體與另一群體的東西。"},{"en":"Overprotective rules can become a defensive barrier between children and real-life learning.","zh":"過度保護的規則可能成為兒童與真實生活學習之間的防衛性屏障。"},{"en":"If children’s books hide all adult realities, they may become a barrier rather than a bridge.","zh":"如果兒童書隱藏所有成人現實，它們可能成為屏障，而不是橋樑。"},{"en":"This phrase suggests separation created out of fear or protection.","zh":"這個片語暗示出於恐懼或保護而造成的分隔。"}],"source":"29 - Children’s Literature.pdf","sourcePage":15},{"front":"necessary growth towards","meaning":"邁向……的必要成長","examples":[{"en":"Children need growth towards adult understanding.","zh":"兒童需要邁向成人理解能力的必要成長。"},{"en":"Necessary growth towards something means the important process of gradually developing in that direction.","zh":"Necessary growth towards something 指逐步朝某方向發展的重要過程。"},{"en":"Students need growth towards independent learning before university.","zh":"學生在入大學前需要邁向獨立學習的必要成長。"},{"en":"If children never meet difficult ideas in books, their growth towards adult understanding may be slower.","zh":"如果兒童從不在書中接觸困難想法，他們邁向成人理解能力的成長可能較慢。"},{"en":"This phrase describes gradual development toward maturity or ability.","zh":"這個片語描述朝成熟或能力逐步發展。"}],"source":"29 - Children’s Literature.pdf","sourcePage":15},{"front":"complete the table below","meaning":"完成以下表格","examples":[{"en":"Students complete the table below using words from the passage.","zh":"學生使用文章中的字詞完成以下表格。"},{"en":"To complete the table below means to fill in missing information in the table that follows the instruction.","zh":"To complete the table below 指填寫指示下方表格中的缺失資料。"},{"en":"In a reading test, students complete the table by locating exact details in the passage.","zh":"在閱讀測驗中，學生透過在文章中定位準確細節來完成表格。"},{"en":"If the table has dates and features, students must match the correct words to each space.","zh":"如果表格有日期和特點，學生必須把正確字詞配對到每個空格。"},{"en":"This phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"29 - Children’s Literature.pdf","sourcePage":15},{"front":"no more than two words","meaning":"不超過兩個詞","examples":[{"en":"Each answer should contain no more than two words.","zh":"每個答案應包含不超過兩個詞。"},{"en":"No more than two words means the answer may contain one word or two words only.","zh":"No more than two words 指答案只能包含一個或兩個詞。"},{"en":"If students write three words, the answer may be wrong even if the idea is correct.","zh":"如果學生寫三個詞，即使意思正確，答案也可能錯。"},{"en":"When this instruction appears, students should copy only the necessary words from the text.","zh":"當這個指示出現，學生應只從文本中抄寫必要字詞。"},{"en":"This phrase sets a strict word limit.","zh":"這個片語設定嚴格字數限制。"}],"source":"29 - Children’s Literature.pdf","sourcePage":15},{"front":"features","meaning":"特點","examples":[{"en":"The table asks students to identify features of children’s literature.","zh":"表格要求學生識別兒童文學的特點。"},{"en":"Features are important qualities, parts, or characteristics of something.","zh":"Features 是某事的重要質素、部分或特徵。"},{"en":"A phone’s features may include a camera, battery life, and screen size.","zh":"手機的特點可能包括相機、電池續航和螢幕大小。"},{"en":"If students identify features of a period, they can compare it with other periods more easily.","zh":"如果學生識別某時期的特點，他們可以更容易把它與其他時期比較。"},{"en":"This word helps describe what makes something recognisable.","zh":"這個詞幫助描述某事可被辨認的特徵。"}],"source":"29 - Children’s Literature.pdf","sourcePage":15},{"front":"not aimed specifically at","meaning":"並非專門針對","examples":[{"en":"Before 1700, many printed stories were not aimed specifically at children.","zh":"1700年前，許多印刷故事並非專門針對兒童。"},{"en":"Not aimed specifically at someone means not designed especially for that group.","zh":"Not aimed specifically at someone 指並非特別為某群體而設計。"},{"en":"A public notice is not aimed specifically at students if it is written for everyone in the community.","zh":"如果告示是寫給整個社區，它就並非專門針對學生。"},{"en":"If a story is not aimed specifically at children, its language and themes may be more adult.","zh":"如果故事並非專門針對兒童，它的語言和主題可能更成人化。"},{"en":"This phrase shows that the audience is broad or unclear.","zh":"這個片語顯示讀者對象較廣或不明確。"}],"source":"29 - Children’s Literature.pdf","sourcePage":15},{"front":"education and morality","meaning":"教育和道德","examples":[{"en":"Early child-oriented works often focused on education and morality.","zh":"早期以兒童為本的作品常集中於教育和道德。"},{"en":"Education and morality means learning knowledge or skills together with lessons about right and wrong behaviour.","zh":"Education and morality 指學習知識或技能，同時學習是非行為。"},{"en":"A children’s story about sharing can combine education and morality.","zh":"關於分享的兒童故事可以結合教育和道德。"},{"en":"If books focus only on morality, children may find them less entertaining.","zh":"如果書籍只集中於道德，兒童可能覺得它們較不有趣。"},{"en":"This phrase links teaching with ethical behaviour.","zh":"這個片語把教學與倫理行為連接起來。"}],"source":"29 - Children’s Literature.pdf","sourcePage":15},{"front":"collection of","meaning":"……的集合","examples":[{"en":"A Little Pretty Pocket Book contained a collection of rhymes and games.","zh":"《漂亮小口袋書》包含童謠和遊戲的集合。"},{"en":"A collection of things is a group of similar or related items gathered together.","zh":"Collection of things 是一組被收集在一起的相似或相關項目。"},{"en":"A teacher may give students a collection of short stories for holiday reading.","zh":"老師可能給學生一本文集，作假期閱讀。"},{"en":"If a book contains a collection of games, children can choose different activities.","zh":"如果一本書包含遊戲集合，兒童可以選擇不同活動。"},{"en":"This phrase describes several items brought together in one place.","zh":"這個片語描述幾個項目被放在同一處。"}],"source":"29 - Children’s Literature.pdf","sourcePage":15},{"front":"exported to","meaning":"出口到；傳到","examples":[{"en":"The book’s formula was quickly exported to America through piracy.","zh":"這本書的方程式很快透過盜版傳到美國。"},{"en":"To be exported to a place means to be sent, copied, or spread from one country or market to another.","zh":"To be exported to a place 指從一個國家或市場被送出、複製或傳播到另一處。"},{"en":"A successful teaching method may be exported to other schools.","zh":"成功的教學方法可能被傳到其他學校。"},{"en":"If a book formula is exported, publishers elsewhere may adapt it for their own readers.","zh":"如果書籍方程式被傳到外地，其他地方的出版商可能為自己的讀者改編它。"},{"en":"This phrase can describe goods, ideas, formats, or culture moving abroad.","zh":"這個片語可以描述商品、想法、形式或文化傳到海外。"}],"source":"29 - Children’s Literature.pdf","sourcePage":15},{"front":"growing interest in","meaning":"對……越來越感興趣","examples":[{"en":"Early-19th-century literature showed a growing interest in folklore.","zh":"19世紀初的文學顯示人們對民間傳說越來越感興趣。"},{"en":"Growing interest in something means more and more attention, curiosity, or enthusiasm about it.","zh":"Growing interest in something 指對某事的關注、好奇或熱情越來越多。"},{"en":"Schools may show growing interest in mental health by adding counselling services.","zh":"學校可能透過增加輔導服務，顯示對心理健康越來越感興趣。"},{"en":"If readers show growing interest in folklore, publishers may print more traditional tales.","zh":"如果讀者對民間傳說越來越感興趣，出版商可能印更多傳統故事。"},{"en":"This phrase describes interest increasing over time.","zh":"這個片語描述興趣隨時間增加。"}],"source":"29 - Children’s Literature.pdf","sourcePage":16},{"front":"risk-free adventures","meaning":"沒有真正危險的冒險","examples":[{"en":"Late-1930s stories often described risk-free adventures.","zh":"1930年代後期的故事常描寫沒有真正危險的冒險。"},{"en":"Risk-free adventures are exciting experiences in which characters seem safe and unlikely to suffer real harm.","zh":"Risk-free adventures 是角色看似安全且不大可能受到真正傷害的刺激經歷。"},{"en":"A children’s mystery where every danger is harmless can feel like a risk-free adventure.","zh":"如果兒童懸疑故事中的每個危險都無害，它就像沒有真正危險的冒險。"},{"en":"If readers know nothing bad will happen, the adventure feels exciting but safe.","zh":"如果讀者知道不會有壞事發生，冒險就感覺刺激但安全。"},{"en":"This phrase describes excitement without genuine danger.","zh":"這個片語描述沒有真正危險的刺激。"}],"source":"29 - Children’s Literature.pdf","sourcePage":16},{"front":"look at the following people","meaning":"查看以下人物","examples":[{"en":"Students look at the following people and match them with statements.","zh":"學生查看以下人物，並把他們與陳述配對。"},{"en":"Look at the following people means examine the list of names given below the instruction.","zh":"Look at the following people 指查看指示下方列出的姓名。"},{"en":"In a matching task, students should look at the following people before scanning the passage.","zh":"在配對題中，學生應先查看以下人物，再掃讀文章。"},{"en":"If students know each person’s role, they can match the statements more accurately.","zh":"如果學生知道每個人物的角色，他們可以更準確地配對陳述。"},{"en":"This phrase is a reading-test instruction.","zh":"這個片語是閱讀測驗指示。"}],"source":"29 - Children’s Literature.pdf","sourcePage":16},{"front":"list of statements","meaning":"陳述列表","examples":[{"en":"The task provides a list of statements about writers.","zh":"任務提供一份關於作家的陳述列表。"},{"en":"A list of statements is a set of sentences that students must judge, match, or complete.","zh":"List of statements 是一組學生必須判斷、配對或完成的句子。"},{"en":"A reading exercise may give a list of statements about different researchers.","zh":"閱讀練習可能提供一份關於不同研究人員的陳述列表。"},{"en":"If students compare the list with the passage carefully, they can avoid matching by keywords only.","zh":"如果學生仔細把列表與文章比較，他們可以避免只靠關鍵字配對。"},{"en":"This phrase refers to the answer options in a task.","zh":"這個片語指任務中的答案選項。"}],"source":"29 - Children’s Literature.pdf","sourcePage":16},{"front":"match each person with","meaning":"把每個人物與……配對","examples":[{"en":"Students match each person with the correct statement.","zh":"學生把每個人物與正確陳述配對。"},{"en":"To match each person with something means to connect every name to the right description or answer.","zh":"To match each person with something 指把每個姓名連接到正確描述或答案。"},{"en":"Students may match each scientist with the discovery they made.","zh":"學生可能把每位科學家與他們的發現配對。"},{"en":"If a passage mentions several writers, careful matching prevents confusing their ideas.","zh":"如果文章提到幾位作家，仔細配對可以避免混淆他們的想法。"},{"en":"This phrase describes a matching task.","zh":"這個片語描述配對任務。"}],"source":"29 - Children’s Literature.pdf","sourcePage":16},{"front":"correct statement","meaning":"正確陳述","examples":[{"en":"Each person should be matched with the correct statement.","zh":"每個人物應與正確陳述配對。"},{"en":"A correct statement is a sentence that accurately matches the information in the passage.","zh":"Correct statement 是準確符合文章資料的句子。"},{"en":"In a quiz, the correct statement must fit the evidence, not just sound familiar.","zh":"在小測中，正確陳述必須符合證據，而不只是聽起來熟悉。"},{"en":"If a statement describes the wrong writer, it is not the correct statement for that person.","zh":"如果陳述描述錯誤作家，它就不是該人物的正確陳述。"},{"en":"This phrase emphasises accuracy in matching or choosing answers.","zh":"這個片語強調配對或選答案時的準確性。"}],"source":"29 - Children’s Literature.pdf","sourcePage":16},{"front":"write criticism of","meaning":"撰寫對……的評論","examples":[{"en":"Mrs Sarah Trimmer wrote criticism of children’s literature.","zh":"Sarah Trimmer夫人撰寫對兒童文學的評論。"},{"en":"To write criticism of something means to produce judgments, reviews, or analysis about it.","zh":"To write criticism of something 指寫出對某事的判斷、評論或分析。"},{"en":"A student may write criticism of a film by discussing its message and acting.","zh":"學生可能透過討論電影訊息和演技，撰寫對電影的評論。"},{"en":"If a critic writes criticism of children’s books, parents may use it to choose suitable reading.","zh":"如果批評家撰寫對兒童書的評論，父母可能用它選擇合適讀物。"},{"en":"This phrase refers to evaluative writing, not simply negative comments.","zh":"這個片語指評價性寫作，而不只是負面批評。"}],"source":"29 - Children’s Literature.pdf","sourcePage":16},{"front":"exemplify","meaning":"作為……的例子","examples":[{"en":"Her talking animals exemplified sense and decorum.","zh":"她筆下會說話的動物作為明智和得體行為的例子。"},{"en":"To exemplify something means to be a clear example of it.","zh":"To exemplify something 指成為某事的清楚例子。"},{"en":"A student who listens carefully and helps classmates exemplifies good manners.","zh":"細心聆聽並幫助同學的學生，體現良好禮貌。"},{"en":"If a character consistently acts wisely, they can exemplify good judgment.","zh":"如果角色一貫行事明智，他們可以成為良好判斷力的例子。"},{"en":"This verb means to show a quality through a clear example.","zh":"這個動詞指透過清楚例子展示某種質素。"}],"source":"29 - Children’s Literature.pdf","sourcePage":16},{"front":"originally a merchant","meaning":"原本是一名商人","examples":[{"en":"Thomas Boreham was originally a merchant rather than a writer.","zh":"Thomas Boreham原本是一名商人，而不是作家。"},{"en":"Originally a merchant means first or initially working as a trader or businessperson.","zh":"Originally a merchant 指最初從事貿易或商業的人。"},{"en":"Someone originally a teacher may later become a writer of children’s books.","zh":"原本是老師的人，後來可能成為兒童書作家。"},{"en":"If a book producer was originally a merchant, commercial skill may have helped the publication succeed.","zh":"如果書籍製作者原本是一名商人，商業技巧可能幫助出版物成功。"},{"en":"This phrase contrasts someone’s earlier occupation with a later role.","zh":"這個片語把某人早期職業與後來角色作對比。"}],"source":"29 - Children’s Literature.pdf","sourcePage":16},{"front":"translate a book into English","meaning":"把一本書翻譯成英文","examples":[{"en":"The statement concerns whether someone translated a book into English.","zh":"這項陳述涉及是否有人把一本書翻譯成英文。"},{"en":"To translate a book into English means to change the whole book from another language into English.","zh":"To translate a book into English 指把整本書從另一種語言轉換成英文。"},{"en":"A publisher may translate a French picture book into English for British children.","zh":"出版商可能把法文圖畫書翻譯成英文，給英國兒童閱讀。"},{"en":"If a book is translated into English, it can reach a larger international audience.","zh":"如果一本書被翻譯成英文，它可以接觸更大的國際讀者群。"},{"en":"This phrase describes changing a book’s language, not rewriting its story completely.","zh":"這個片語描述改變書的語言，而不是完全重寫故事。"}],"source":"29 - Children’s Literature.pdf","sourcePage":16},{"front":"write in English","meaning":"以英文寫作","examples":[{"en":"The Brothers Grimm did not write in English originally.","zh":"格林兄弟原本並非以英文寫作。"},{"en":"To write in English means to use English as the language of writing.","zh":"To write in English 指使用英文作為寫作語言。"},{"en":"A student may think in Chinese but write in English during an IELTS task.","zh":"學生在IELTS任務中可能用中文思考，但以英文寫作。"},{"en":"If an author does not write in English, English readers may need a translation.","zh":"如果作者不以英文寫作，英文讀者可能需要譯本。"},{"en":"This phrase identifies the language used for writing.","zh":"這個片語指出寫作所用語言。"}],"source":"29 - Children’s Literature.pdf","sourcePage":17},{"front":"agree with the information given","meaning":"與所提供資料相符","examples":[{"en":"Students decide whether the statements agree with the information given.","zh":"學生判斷陳述是否與所提供資料相符。"},{"en":"To agree with the information given means to match what the passage says.","zh":"To agree with the information given 指與文章所說內容相符。"},{"en":"If the passage says a book was published in 1744, a statement giving the same date agrees with it.","zh":"如果文章說一本書於1744年出版，給出同一年份的陳述就與資料相符。"},{"en":"If a statement changes the meaning, it does not agree with the information even if some words are similar.","zh":"如果陳述改變意思，即使有些字相似，也不與資料相符。"},{"en":"This phrase is common in True/False/Not Given tasks.","zh":"這個片語常見於True/False/Not Given題型。"}],"source":"29 - Children’s Literature.pdf","sourcePage":17},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與文章資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the passage says.","zh":"To contradict the information 指說出與文章所說相反的內容。"},{"en":"If the passage says the book was popular, a statement saying it failed contradicts the information.","zh":"如果文章說這本書受歡迎，而陳述說它失敗，該陳述就與資料相矛盾。"},{"en":"When a statement contradicts the text, students should mark it false rather than not given.","zh":"當陳述與文本相矛盾，學生應標記為false，而不是not given。"},{"en":"This phrase describes direct conflict with the source.","zh":"這個片語描述與來源直接衝突。"}],"source":"29 - Children’s Literature.pdf","sourcePage":17},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"Write Not Given if there is no information on this.","zh":"如果沒有相關資料，就寫Not Given。"},{"en":"No information on this means the passage does not tell us whether the statement is true or false.","zh":"No information on this 指文章沒有告訴我們該陳述是真是假。"},{"en":"If a text names a writer but not their birthplace, there is no information on birthplace.","zh":"如果文本提到一位作家但沒有提及出生地，出生地方面就沒有相關資料。"},{"en":"Students should not guess from common knowledge when there is no information in the passage.","zh":"當文章沒有相關資料，學生不應根據常識猜測。"},{"en":"This phrase signals that the answer cannot be proved from the text.","zh":"這個片語表示答案不能從文本中證明。"}],"source":"29 - Children’s Literature.pdf","sourcePage":17},{"front":"begin reading books","meaning":"開始閱讀書籍","examples":[{"en":"The statement asks whether children began reading books only after 1700.","zh":"這項陳述詢問兒童是否只在1700年後才開始閱讀書籍。"},{"en":"To begin reading books means to start reading books as a new habit or activity.","zh":"To begin reading books 指開始把閱讀書籍作為新習慣或活動。"},{"en":"A child may begin reading books independently after learning basic sounds and words.","zh":"兒童學會基本聲音和字詞後，可能開始獨立閱讀書籍。"},{"en":"If children read printed stories before 1700, they did not begin reading books only after that date.","zh":"如果兒童在1700年前已閱讀印刷故事，他們就不是只在該日期後才開始閱讀書籍。"},{"en":"This phrase focuses on the start of reading activity.","zh":"這個片語著重閱讀活動的開始。"}],"source":"29 - Children’s Literature.pdf","sourcePage":17},{"front":"set good examples","meaning":"樹立好榜樣","examples":[{"en":"Sarah Trimmer believed children’s books should set good examples.","zh":"Sarah Trimmer認為兒童書應該樹立好榜樣。"},{"en":"To set good examples means to show behaviour that others should copy.","zh":"To set good examples 指展示值得別人模仿的行為。"},{"en":"Older students can set good examples by arriving on time and helping classmates.","zh":"高年級學生可以透過準時到達和幫助同學來樹立好榜樣。"},{"en":"If story characters behave kindly and honestly, they may set good examples for children.","zh":"如果故事角色善良而誠實，他們可能為兒童樹立好榜樣。"},{"en":"This phrase connects behaviour with moral teaching.","zh":"這個片語把行為與道德教導連接起來。"}],"source":"29 - Children’s Literature.pdf","sourcePage":17},{"front":"be concerned about","meaning":"關注；擔心","examples":[{"en":"The statement asks whether parents were concerned about violence.","zh":"這項陳述詢問父母是否擔心暴力。"},{"en":"To be concerned about something means to be worried or troubled by it.","zh":"To be concerned about something 指對某事感到擔心或不安。"},{"en":"Parents may be concerned about screen time if children sleep too late.","zh":"如果孩子太晚睡，父母可能擔心螢幕時間。"},{"en":"If adults are concerned about violence in books, they may ask publishers to change the content.","zh":"如果成人擔心書中的暴力，他們可能要求出版商改變內容。"},{"en":"This phrase describes worry about a possible problem.","zh":"這個片語描述對可能問題的憂慮。"}],"source":"29 - Children’s Literature.pdf","sourcePage":17},{"front":"violence in children’s books","meaning":"兒童書中的暴力","examples":[{"en":"Critics condemned violence in fairy-tales.","zh":"批評家譴責童話故事中的暴力。"},{"en":"Violence in children’s books means scenes or actions involving harm, fighting, cruelty, or danger in books for children.","zh":"Violence in children’s books 指兒童書中涉及傷害、打鬥、殘酷或危險的場面或行為。"},{"en":"A parent may object to violence in children’s books if it frightens young readers.","zh":"如果兒童書中的暴力嚇怕年輕讀者，父母可能反對。"},{"en":"If violence is shown without explanation, adults may worry that children will misunderstand it.","zh":"如果暴力沒有得到解釋，成人可能擔心兒童會誤解它。"},{"en":"This phrase refers to harmful or aggressive content in children’s reading.","zh":"這個片語指兒童閱讀中的有害或攻擊性內容。"}],"source":"29 - Children’s Literature.pdf","sourcePage":17},{"front":"change the direction of","meaning":"改變……的方向","examples":[{"en":"Interest in folklore changed the direction of children’s literature.","zh":"對民間傳說的興趣改變了兒童文學的方向。"},{"en":"To change the direction of something means to make it develop in a different way.","zh":"To change the direction of something 指令某事以不同方式發展。"},{"en":"A new teacher can change the direction of a class by making lessons more discussion-based.","zh":"新老師可以透過令課堂更重討論，改變一個班的方向。"},{"en":"If readers prefer fairy tales, publishers may change the direction of children’s books toward fantasy.","zh":"如果讀者偏好童話，出版商可能把兒童書方向改向幻想。"},{"en":"This phrase describes a shift in development or focus.","zh":"這個片語描述發展或焦點的轉變。"}],"source":"29 - Children’s Literature.pdf","sourcePage":17},{"front":"appeal to both children and adults","meaning":"吸引兒童和成人","examples":[{"en":"Children’s books may now appeal to both children and adults.","zh":"兒童書現在可能同時吸引兒童和成人。"},{"en":"To appeal to both children and adults means to interest and please readers from both age groups.","zh":"To appeal to both children and adults 指同時引起兩個年齡群體的興趣並令他們喜歡。"},{"en":"A picture book with simple words and deep emotion can appeal to both children and adults.","zh":"一本有簡單文字和深刻情感的圖畫書，可以同時吸引兒童和成人。"},{"en":"If a story has adventure for children and meaning for adults, it can reach a wider audience.","zh":"如果故事有給兒童的冒險和給成人的意義，它可以接觸更廣泛讀者。"},{"en":"This phrase shows that a book can cross age boundaries.","zh":"這個片語顯示一本書可以跨越年齡界線。"}],"source":"29 - Children’s Literature.pdf","sourcePage":17}],"ielts/reading/passage-2/Practice 30":[{"front":"second in line to the British throne","meaning":"英國王位第二繼承人","examples":[{"en":"Prince Albert Victor was second in line to the British throne.","zh":"Albert Victor 王子是英國王位第二繼承人。"},{"en":"Second in line to the British throne means the person is expected to inherit the throne after one other person.","zh":"second in line to the British throne 指某人排在另一人之後，有望繼承英國王位。"},{"en":"A prince may be second in line if his father is first in line before him.","zh":"如果父親排第一，王子就可能是第二繼承人。"},{"en":"Being second in line can bring public attention because the person is close to becoming monarch.","zh":"成為第二繼承人會帶來公眾關注，因為此人接近成為君主。"},{"en":"The phrase describes royal succession, not ordinary job promotion.","zh":"這個短語描述王位繼承，而不是普通工作晉升。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":1},{"front":"die from flu","meaning":"死於流感","examples":[{"en":"Prince Albert Victor died from flu in 1892.","zh":"Albert Victor 王子於1892年死於流感。"},{"en":"To die from flu means to die because influenza causes severe illness or complications.","zh":"die from flu 指因流感造成嚴重疾病或併發症而死亡。"},{"en":"An elderly patient may die from flu if the infection leads to pneumonia.","zh":"如果感染導致肺炎，年長病人可能死於流感。"},{"en":"Flu can be dangerous when the body is already weak or medical care is limited.","zh":"當身體本已虛弱或醫療照顧有限，流感可以很危險。"},{"en":"The phrase states the cause of death directly.","zh":"這個短語直接說明死因。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":1},{"front":"succumb to","meaning":"死於；不敵","examples":[{"en":"He had succumbed to the third wave of the Russian flu pandemic.","zh":"他死於俄羅斯流感大流行第三波。"},{"en":"To succumb to a disease means to die from it or be defeated by it.","zh":"succumb to 疾病，指死於該病或被該病擊倒。"},{"en":"A weak plant may succumb to cold weather if it is left outside all night.","zh":"如果植物整晚留在室外，脆弱植物可能不敵寒冷天氣。"},{"en":"People may succumb to illness when treatment fails or the body cannot fight anymore.","zh":"當治療失敗或身體不能再抵抗，人們可能不敵疾病。"},{"en":"The phrase is more formal than simply saying “die from.”","zh":"這個短語比 simply saying “die from” 更正式。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":1},{"front":"most lethal wave","meaning":"最致命的一波","examples":[{"en":"He succumbed to the third and most lethal wave of the pandemic.","zh":"他死於該大流行第三波，也是最致命的一波。"},{"en":"The most lethal wave is the stage of an outbreak that causes the most deaths.","zh":"most lethal wave 是疫情中造成最多死亡的階段。"},{"en":"In a severe epidemic, one wave may be mild while a later wave becomes more lethal.","zh":"在嚴重疫情中，一波可能較輕微，而較後一波變得更致命。"},{"en":"A more lethal wave can overwhelm hospitals and frighten the public.","zh":"更致命的一波可以令醫院不勝負荷，並令公眾恐懼。"},{"en":"The phrase focuses on death rate, not just how many people catch the disease.","zh":"這個短語重點在死亡率，而不只是感染人數。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":1},{"front":"Russian flu pandemic","meaning":"俄羅斯流感大流行","examples":[{"en":"The Russian flu pandemic swept across the world.","zh":"俄羅斯流感大流行席捲全球。"},{"en":"The Russian flu pandemic was a large international outbreak of influenza linked in the passage to Russia.","zh":"Russian flu pandemic 是文章中與俄羅斯相關的大規模國際流感爆發。"},{"en":"A pandemic affects many countries, unlike a small local outbreak.","zh":"大流行影響許多國家，不同於小型本地爆發。"},{"en":"Such a pandemic can disrupt travel, work, schools and public services.","zh":"這類大流行可以打亂交通、工作、學校和公共服務。"},{"en":"The phrase names the historical disease event discussed in the passage.","zh":"這個短語指出文章討論的歷史疾病事件。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":1},{"front":"sweep the world","meaning":"席捲全球","examples":[{"en":"The Russian flu pandemic was sweeping the world.","zh":"俄羅斯流感大流行正在席捲全球。"},{"en":"To sweep the world means to spread quickly across many countries or regions.","zh":"sweep the world 指快速傳遍許多國家或地區。"},{"en":"A popular song can sweep the world if people share it online everywhere.","zh":"如果人們在網上到處分享，一首流行歌可以席捲全球。"},{"en":"When a disease sweeps the world, many places face similar problems at nearly the same time.","zh":"當疾病席捲全球，許多地方幾乎同時面對相似問題。"},{"en":"The phrase suggests fast, wide and powerful spread.","zh":"這個短語暗示快速、廣泛而有力的傳播。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":1},{"front":"the nation was shocked","meaning":"全國震驚","examples":[{"en":"The nation was shocked by Prince Albert Victor’s death.","zh":"Albert Victor 王子的死亡令全國震驚。"},{"en":"The nation was shocked means people across the country felt sudden surprise and sadness.","zh":"the nation was shocked 指全國人民感到突然的驚訝和悲傷。"},{"en":"The nation may be shocked when a well-known leader dies unexpectedly.","zh":"當知名領袖突然去世，全國可能震驚。"},{"en":"Public shock often leads newspapers to publish many reports and reactions.","zh":"公眾震驚常令報章刊登大量報道和反應。"},{"en":"The phrase describes a strong shared emotional reaction.","zh":"這個短語描述強烈的共同情緒反應。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":1},{"front":"be relegated to","meaning":"被降為；被貶為","examples":[{"en":"Albert was relegated to a footnote in history.","zh":"Albert 被降為歷史註腳。"},{"en":"To be relegated to something means to be treated as less important than before.","zh":"be relegated to 某位置，指被視為比以前不重要。"},{"en":"A once-famous player may be relegated to a minor role after younger athletes arrive.","zh":"當年輕運動員出現，曾經有名的球員可能被降為次要角色。"},{"en":"When bigger events dominate memory, smaller figures can be relegated to the background.","zh":"當更重大事件主導記憶，較小人物可能被推到背景。"},{"en":"The phrase suggests loss of importance or status.","zh":"這個短語暗示重要性或地位下降。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":1},{"front":"a footnote in history","meaning":"歷史註腳","examples":[{"en":"Albert was relegated to a footnote in history.","zh":"Albert 被降為歷史註腳。"},{"en":"A footnote in history is a person or event remembered only as a minor detail.","zh":"a footnote in history 是只作為次要細節被記住的人或事件。"},{"en":"A small invention may become a footnote in history if a later invention changes everything.","zh":"如果後來的發明改變一切，小發明可能成為歷史註腳。"},{"en":"Important people can become historical footnotes when their lives are overshadowed by larger events.","zh":"當人生被更大事件掩蓋，重要人物也可能成為歷史註腳。"},{"en":"The phrase describes being remembered, but not as a central figure.","zh":"這個短語描述仍被記住，但不是核心人物。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":1},{"front":"go down with flu","meaning":"患上流感","examples":[{"en":"Louisa Carlill went down with flu three days later.","zh":"Louisa Carlill 三日後患上流感。"},{"en":"To go down with flu means to become ill with influenza.","zh":"go down with flu 指患上流感。"},{"en":"A teacher may go down with flu after several students in class become sick.","zh":"班上幾名學生生病後，老師可能患上流感。"},{"en":"If many workers go down with flu, a company may not have enough staff.","zh":"如果許多員工患上流感，公司可能人手不足。"},{"en":"The phrase is informal and focuses on becoming ill.","zh":"這個短語較口語，重點在開始生病。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":1},{"front":"inhale thrice daily","meaning":"每日吸入三次","examples":[{"en":"She had inhaled thrice daily from a carbolic smoke ball.","zh":"她每日三次從石炭酸煙球吸入粉末。"},{"en":"To inhale thrice daily means to breathe something in three times each day.","zh":"inhale thrice daily 指每日三次吸入某物。"},{"en":"A patient may be told to inhale medicine twice daily through an inhaler.","zh":"病人可能被指示每日兩次透過吸入器吸藥。"},{"en":"If instructions say thrice daily, missing doses may affect the claimed result.","zh":"如果說明寫明每日三次，漏用可能影響聲稱效果。"},{"en":"The phrase sounds old-fashioned because “thrice” is rarely used in modern speech.","zh":"這個短語聽起來較舊式，因為 thrice 在現代口語中較少用。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":2},{"front":"carbolic smoke ball","meaning":"石炭酸煙球","examples":[{"en":"Louisa Carlill used a carbolic smoke ball to prevent flu.","zh":"Louisa Carlill 使用石炭酸煙球來預防流感。"},{"en":"A carbolic smoke ball was a device sold as a flu-prevention product in the passage.","zh":"carbolic smoke ball 是文章中作為預防流感產品出售的裝置。"},{"en":"The user squeezed the ball and inhaled powder through the nose.","zh":"使用者擠壓球體，並透過鼻子吸入粉末。"},{"en":"Because the product made strong claims, it later became central to a legal case.","zh":"因為該產品作出強烈聲稱，它後來成為法律案件核心。"},{"en":"The phrase refers to a historical patent medicine, not a modern medical device.","zh":"這個短語指歷史上的專利成藥，而不是現代醫療器材。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":2},{"front":"preventive measure","meaning":"預防措施","examples":[{"en":"The carbolic smoke ball was sold as a preventive measure against flu.","zh":"石炭酸煙球被作為預防流感的措施出售。"},{"en":"A preventive measure is an action taken to stop a problem before it happens.","zh":"preventive measure 是在問題發生前採取的預防行動。"},{"en":"Washing hands is a simple preventive measure against spreading germs.","zh":"洗手是防止病菌傳播的簡單預防措施。"},{"en":"Good preventive measures can reduce illness, accidents or financial loss.","zh":"良好預防措施可以減少疾病、意外或金錢損失。"},{"en":"The phrase focuses on prevention rather than treatment after the problem appears.","zh":"這個短語重點在預防，而不是問題出現後治療。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":2},{"front":"be guaranteed to","meaning":"保證會","examples":[{"en":"The product was guaranteed to fend off flu.","zh":"該產品被保證會抵禦流感。"},{"en":"To be guaranteed to do something means the seller or speaker promises that it will happen.","zh":"be guaranteed to do something 指賣方或說話者承諾某事會發生。"},{"en":"A shop may say a waterproof bag is guaranteed to keep books dry.","zh":"商店可能說防水袋保證會令書本保持乾爽。"},{"en":"If a guarantee is false, customers may complain or take legal action.","zh":"如果保證不實，顧客可能投訴或採取法律行動。"},{"en":"The phrase suggests a strong promise, not a weak possibility.","zh":"這個短語暗示強烈承諾，而不是微弱可能性。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":2},{"front":"fend off flu","meaning":"抵禦流感","examples":[{"en":"The advert claimed the smoke ball could fend off flu.","zh":"廣告聲稱煙球可以抵禦流感。"},{"en":"To fend off flu means to protect oneself from catching influenza.","zh":"fend off flu 指保護自己免受流感感染。"},{"en":"Regular handwashing may help people fend off flu during winter.","zh":"冬天定期洗手可能幫助人抵禦流感。"},{"en":"If a product claims to fend off disease, the evidence behind it should be checked carefully.","zh":"如果產品聲稱能抵禦疾病，背後證據應仔細查核。"},{"en":"The phrase describes protection before infection.","zh":"這個短語描述感染前的保護。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":2},{"front":"believe the advert","meaning":"相信廣告","examples":[{"en":"Louisa Carlill believed the advert.","zh":"Louisa Carlill 相信廣告。"},{"en":"To believe the advert means to accept that the advertisement’s claims are true.","zh":"believe the advert 指接受廣告中的聲稱為真。"},{"en":"A shopper may believe an advert that says a cleaner removes all stains.","zh":"購物者可能相信聲稱清潔劑能去除所有污漬的廣告。"},{"en":"If people believe a misleading advert, they may spend money on a useless product.","zh":"如果人們相信誤導性廣告，他們可能花錢買無用產品。"},{"en":"The phrase describes trust in advertising claims.","zh":"這個短語描述對廣告聲稱的信任。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":2},{"front":"cough up","meaning":"被迫支付；掏錢","examples":[{"en":"The company promised to cough up £100 for any customer who fell ill.","zh":"公司承諾向任何生病的顧客支付100英鎊。"},{"en":"To cough up money means to pay money, often unwillingly or under pressure.","zh":"cough up money 指支付金錢，通常帶不情願或受壓意味。"},{"en":"A careless driver may have to cough up money for damaging another car.","zh":"粗心司機撞壞別人的車，可能要掏錢賠償。"},{"en":"If a company promises a reward, it may have to cough up when conditions are met.","zh":"如果公司承諾賞金，條件達成時可能要被迫支付。"},{"en":"The phrase is informal and suggests reluctant payment.","zh":"這個短語較口語，暗示不情願付款。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":2},{"front":"fall ill","meaning":"生病","examples":[{"en":"The company promised money to any customer who fell ill.","zh":"公司承諾向任何生病的顧客付款。"},{"en":"To fall ill means to become sick.","zh":"fall ill 指開始生病。"},{"en":"A student may fall ill after sitting beside classmates with flu.","zh":"學生坐在有流感的同學旁邊後，可能生病。"},{"en":"If many employees fall ill at once, work may be delayed.","zh":"如果許多員工同時生病，工作可能延誤。"},{"en":"The phrase focuses on the moment someone becomes unwell.","zh":"這個短語重點在某人變得不適的時刻。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":2},{"front":"recover","meaning":"康復","examples":[{"en":"Unlike Albert, Louisa recovered from flu.","zh":"與 Albert 不同，Louisa 從流感中康復。"},{"en":"To recover means to become healthy again after illness or injury.","zh":"recover 指在疾病或受傷後重新變得健康。"},{"en":"A child may recover from a cold after resting at home for a few days.","zh":"孩子在家休息幾天後，可能從感冒中康復。"},{"en":"Recovery can be slower if the illness leaves the body weak.","zh":"如果疾病令身體虛弱，康復可能較慢。"},{"en":"The word describes improvement after being unwell.","zh":"這個字描述生病後好轉。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":2},{"front":"claim one’s money","meaning":"索取某人的款項","examples":[{"en":"Louisa recovered and claimed her £100.","zh":"Louisa 康復後索取她的100英鎊。"},{"en":"To claim one’s money means to ask for money that one believes one has the right to receive.","zh":"claim one’s money 指要求取得自己認為有權收取的金錢。"},{"en":"A customer may claim her money back if a product never arrives.","zh":"如果產品從未送達，顧客可能要求退款。"},{"en":"A clear promise or receipt can help someone claim money successfully.","zh":"清楚承諾或收據可以幫助某人成功索款。"},{"en":"The phrase describes demanding payment that is believed to be owed.","zh":"這個短語描述要求支付被認為應得的款項。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":2},{"front":"set in train events","meaning":"引發一連串事件","examples":[{"en":"Louisa set in train events that would win her lasting fame.","zh":"Louisa 引發一連串事件，後來為她贏得持久名聲。"},{"en":"To set in train events means to start a series of actions or results.","zh":"set in train events 指開始一連串行動或結果。"},{"en":"One complaint from a customer can set in train events that lead to a company investigation.","zh":"一名顧客的投訴可以引發一連串事件，導致公司調查。"},{"en":"A small decision may begin a chain of consequences that nobody expected.","zh":"一個小決定可能開始一連串沒有人預料到的後果。"},{"en":"The phrase emphasises the beginning of a sequence.","zh":"這個短語強調一個序列的開始。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":3},{"front":"lasting fame","meaning":"持久名聲","examples":[{"en":"The case would win Louisa Carlill lasting fame.","zh":"這宗案件會為 Louisa Carlill 贏得持久名聲。"},{"en":"Lasting fame is public recognition that continues for a long time.","zh":"lasting fame 是持續很久的公眾認可。"},{"en":"An inventor may gain lasting fame if her idea changes daily life.","zh":"如果發明家的想法改變日常生活，她可能獲得持久名聲。"},{"en":"A court case can create lasting fame when later lawyers continue to study it.","zh":"當後來的律師繼續研究某宗案件，它可以帶來持久名聲。"},{"en":"The phrase describes fame that does not quickly disappear.","zh":"這個短語描述不會很快消失的名聲。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":3},{"front":"first reports of","meaning":"……的最早報道","examples":[{"en":"The first reports of a flu epidemic came from Russia.","zh":"流感疫情的最早報道來自俄羅斯。"},{"en":"The first reports of something are the earliest public accounts or news about it.","zh":"first reports of 某事，是關於它最早的公開描述或新聞。"},{"en":"The first reports of a fire may come from neighbours who see smoke.","zh":"火災的最早報道可能來自看見煙霧的鄰居。"},{"en":"Early reports can shape how people understand a crisis.","zh":"早期報道可以塑造人們如何理解危機。"},{"en":"The phrase points to the beginning of public awareness.","zh":"這個短語指公眾意識的開始。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":3},{"front":"flu epidemic","meaning":"流感疫情","examples":[{"en":"The first reports of a flu epidemic came from Russia.","zh":"流感疫情的最早報道來自俄羅斯。"},{"en":"A flu epidemic is a rapid spread of influenza among many people in a community or region.","zh":"flu epidemic 是流感在社區或地區中快速傳播，影響許多人。"},{"en":"A school may close classes if a flu epidemic affects many students.","zh":"如果流感疫情影響許多學生，學校可能停課。"},{"en":"An epidemic can place pressure on doctors, families and workplaces.","zh":"疫情可以為醫生、家庭和職場帶來壓力。"},{"en":"The phrase describes a serious outbreak, not one person’s illness.","zh":"這個短語描述嚴重爆發，而不是一個人生病。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":3},{"front":"by the end of","meaning":"到……結束時","examples":[{"en":"By the end of the year, the world was in the grip of a pandemic.","zh":"到該年結束時，世界已陷入大流行之中。"},{"en":"By the end of a period means before or at the final point of that period.","zh":"by the end of 某段時間，指在該時段最後一刻或之前。"},{"en":"By the end of the term, students should know all the key grammar rules.","zh":"到學期結束時，學生應知道所有關鍵文法規則。"},{"en":"The phrase shows when a change has already happened.","zh":"這個短語顯示某變化在何時已經發生。"},{"en":"It is useful for describing progress across time.","zh":"它適合用來描述隨時間出現的進展。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":3},{"front":"be in the grip of","meaning":"受……控制；陷入……之中","examples":[{"en":"The world was in the grip of the first truly global flu pandemic.","zh":"世界陷入第一次真正全球性流感大流行之中。"},{"en":"To be in the grip of something means to be strongly controlled or affected by it.","zh":"be in the grip of 某事，指被它強烈控制或影響。"},{"en":"A city may be in the grip of a heatwave when schools and offices struggle to operate.","zh":"當學校和辦公室難以運作，城市可能正受熱浪控制。"},{"en":"When a community is in the grip of fear, ordinary decisions become harder.","zh":"當社區陷入恐懼中，普通決定也變得更困難。"},{"en":"The phrase suggests powerful pressure that is difficult to escape.","zh":"這個短語暗示難以逃脫的強大壓力。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":3},{"front":"truly global pandemic","meaning":"真正全球性大流行病","examples":[{"en":"The world faced the first truly global flu pandemic.","zh":"世界面對第一次真正全球性流感大流行。"},{"en":"A truly global pandemic is a disease outbreak that reaches many parts of the world.","zh":"truly global pandemic 是傳到世界許多地方的疾病大爆發。"},{"en":"A local illness becomes global only when it spreads across countries and continents.","zh":"本地疾病只有在跨越國家和洲際傳播時，才會變成全球性。"},{"en":"A global pandemic can affect trade, travel, hospitals and public confidence.","zh":"全球大流行可以影響貿易、旅行、醫院和公眾信心。"},{"en":"The phrase stresses worldwide scale.","zh":"這個短語強調全球規模。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":3},{"front":"come in waves","meaning":"一波接一波出現","examples":[{"en":"The disease came in waves for the next four years.","zh":"這種疾病在接下來四年一波接一波出現。"},{"en":"To come in waves means to appear repeatedly in separate periods, with rises and falls between them.","zh":"come in waves 指分開時段反覆出現，中間有升有跌。"},{"en":"Customer complaints may come in waves after a company launches a faulty app.","zh":"公司推出有問題的應用程式後，顧客投訴可能一波接一波出現。"},{"en":"If an illness comes in waves, people may relax after one wave and then face another.","zh":"如果疾病一波接一波出現，人們可能在一波後放鬆，然後又面對另一波。"},{"en":"The phrase describes repeated surges, not one continuous event.","zh":"這個短語描述反覆高峰，而不是單一連續事件。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":3},{"front":"worse than the last","meaning":"比上一波更嚴重","examples":[{"en":"Each wave of the disease was worse than the last.","zh":"疾病每一波都比上一波更嚴重。"},{"en":"Worse than the last means each new stage is more serious than the previous one.","zh":"worse than the last 指每個新階段都比前一個更嚴重。"},{"en":"A student may feel each exam is worse than the last if the topics become harder.","zh":"如果題目變得更難，學生可能覺得每次考試都比上一次更難。"},{"en":"When each problem becomes worse than the previous one, fear and pressure grow.","zh":"當每個問題都比前一個更嚴重，恐懼和壓力會增加。"},{"en":"The phrase shows a worsening sequence.","zh":"這個短語顯示不斷惡化的次序。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":3},{"front":"come to a standstill","meaning":"停擺","examples":[{"en":"Whole cities came to a standstill during the pandemic.","zh":"整個城市在大流行期間停擺。"},{"en":"To come to a standstill means to stop moving or operating almost completely.","zh":"come to a standstill 指幾乎完全停止移動或運作。"},{"en":"Traffic may come to a standstill after a major road accident.","zh":"嚴重道路意外後，交通可能停擺。"},{"en":"If a city comes to a standstill, schools, shops and transport may stop functioning.","zh":"如果城市停擺，學校、商店和交通可能停止運作。"},{"en":"The phrase describes serious disruption.","zh":"這個短語描述嚴重中斷。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":3},{"front":"especially hard-hit","meaning":"受打擊尤其嚴重","examples":[{"en":"London was especially hard-hit by the flu.","zh":"倫敦受流感打擊尤其嚴重。"},{"en":"Especially hard-hit means affected more severely than many other places or groups.","zh":"especially hard-hit 指比許多其他地方或群體受影響更嚴重。"},{"en":"A coastal town may be especially hard-hit by a typhoon if many homes are near the sea.","zh":"如果許多房屋靠近海邊，沿海城鎮可能受颱風打擊尤其嚴重。"},{"en":"Hard-hit areas often need extra medical, financial or community support.","zh":"受重創地區通常需要額外醫療、財政或社區支援。"},{"en":"The phrase highlights unequal impact.","zh":"這個短語突出影響不平均。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":4},{"front":"reach its annual peak","meaning":"達到年度高峰","examples":[{"en":"Normal life stopped when the flu reached its annual peak.","zh":"當流感達到年度高峰，正常生活停止。"},{"en":"To reach its annual peak means to rise to the highest level in that year.","zh":"reach its annual peak 指上升到該年中的最高水平。"},{"en":"A shop may reach its annual sales peak during the Christmas season.","zh":"商店可能在聖誕季達到年度銷售高峰。"},{"en":"When illness reaches its peak, hospitals may face the greatest pressure.","zh":"當疾病達到高峰，醫院可能面對最大壓力。"},{"en":"The phrase describes the highest point within a year.","zh":"這個短語描述一年中的最高點。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":4},{"front":"grind to a halt","meaning":"逐漸停頓","examples":[{"en":"The postal service ground to a halt.","zh":"郵政服務逐漸停頓。"},{"en":"To grind to a halt means to slow down and then stop operating.","zh":"grind to a halt 指逐漸慢下來，然後停止運作。"},{"en":"A train system may grind to a halt if signals fail across the city.","zh":"如果全城訊號系統故障，鐵路系統可能逐漸停頓。"},{"en":"Services can grind to a halt when too many workers are absent.","zh":"當太多員工缺勤，服務可能逐漸停頓。"},{"en":"The phrase suggests a gradual but serious stoppage.","zh":"這個短語暗示逐步但嚴重的停頓。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":4},{"front":"courts stopped sitting","meaning":"法庭停止開庭","examples":[{"en":"Even courts stopped sitting for lack of judges.","zh":"甚至法庭也因缺乏法官而停止開庭。"},{"en":"Courts stopped sitting means courts stopped holding legal hearings or sessions.","zh":"courts stopped sitting 指法庭停止舉行聆訊或審訊。"},{"en":"A court may stop sitting if too many judges or lawyers are unavailable.","zh":"如果太多法官或律師未能出席，法庭可能停止開庭。"},{"en":"When courts stop sitting, cases are delayed and people wait longer for justice.","zh":"當法庭停止開庭，案件會延誤，人們要更久才等到公義。"},{"en":"The phrase describes interruption of legal proceedings.","zh":"這個短語描述法律程序中斷。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":4},{"front":"for lack of","meaning":"由於缺乏","examples":[{"en":"Courts stopped sitting for lack of judges.","zh":"法庭由於缺乏法官而停止開庭。"},{"en":"For lack of something means because there is not enough of it.","zh":"for lack of 某物，指因為該物不足。"},{"en":"A school trip may be cancelled for lack of parent volunteers.","zh":"學校旅行可能由於缺乏家長義工而取消。"},{"en":"Services can fail for lack of staff, money or equipment.","zh":"服務可能由於缺乏人手、金錢或設備而失敗。"},{"en":"The phrase gives a reason based on shortage.","zh":"這個短語給出基於短缺的原因。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":4},{"front":"at the height of","meaning":"在……高峰期","examples":[{"en":"At the height of the third wave, 200 people were buried every day at one cemetery.","zh":"在第三波高峰期，一個墓地每天埋葬200人。"},{"en":"At the height of something means during its most intense or extreme point.","zh":"at the height of 某事，指在其最強烈或最極端時刻。"},{"en":"At the height of a storm, people should stay indoors and avoid travel.","zh":"在暴風雨高峰期，人們應留在室內並避免出行。"},{"en":"The greatest pressure often occurs at the height of a crisis.","zh":"最大壓力通常出現在危機高峰期。"},{"en":"The phrase points to the peak moment of an event.","zh":"這個短語指事件的頂峰時刻。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":4},{"front":"previous epidemics","meaning":"以往疫情","examples":[{"en":"This flu was far more lethal than previous epidemics.","zh":"這次流感比以往疫情致命得多。"},{"en":"Previous epidemics are earlier outbreaks of disease before the one being discussed.","zh":"previous epidemics 是所討論疫情之前較早的疾病爆發。"},{"en":"Doctors may compare a new outbreak with previous epidemics to estimate danger.","zh":"醫生可能把新爆發與以往疫情比較，以估計危險。"},{"en":"If a disease is worse than previous epidemics, public fear may increase.","zh":"如果疾病比以往疫情更嚴重，公眾恐懼可能增加。"},{"en":"The phrase places a new outbreak in historical comparison.","zh":"這個短語把新疫情放入歷史比較中。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":4},{"front":"be left weak","meaning":"變得虛弱","examples":[{"en":"Those who recovered were left weak and depressed.","zh":"康復的人仍變得虛弱和抑鬱。"},{"en":"To be left weak means to remain physically weak after an illness or difficult event.","zh":"be left weak 指在疾病或困難事件後仍然身體虛弱。"},{"en":"A patient may be left weak after a serious operation and need weeks of rest.","zh":"病人在重大手術後可能變得虛弱，需要休息數星期。"},{"en":"Some diseases do not end when fever disappears because weakness can continue.","zh":"有些疾病不會在退燒時就結束，因為虛弱可以持續。"},{"en":"The phrase describes a lasting effect after recovery.","zh":"這個短語描述康復後仍留下的影響。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":4},{"front":"unfit for work","meaning":"不適合工作","examples":[{"en":"Many people were left weak and unfit for work.","zh":"許多人變得虛弱，不適合工作。"},{"en":"Unfit for work means not healthy or strong enough to do one’s job.","zh":"unfit for work 指健康或體力不足以工作。"},{"en":"A builder with a broken leg may be unfit for work until he can walk safely.","zh":"腿骨折的建築工人在能安全行走前可能不適合工作。"},{"en":"If many workers are unfit for work, businesses and services may slow down.","zh":"如果許多員工不適合工作，企業和服務可能放慢。"},{"en":"The phrase connects health with ability to work.","zh":"這個短語把健康與工作能力連繫起來。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":4},{"front":"repeated across the continent","meaning":"在整個歐洲大陸重複出現","examples":[{"en":"The same picture was repeated across the continent.","zh":"同樣景象在整個歐洲大陸重複出現。"},{"en":"Repeated across the continent means the same situation happened in many countries or regions of a continent.","zh":"repeated across the continent 指同一情況在一個大洲的許多國家或地區發生。"},{"en":"During a heatwave, power failures may be repeated across the continent.","zh":"在熱浪期間，停電可能在整個大陸重複出現。"},{"en":"When a pattern is repeated widely, it shows the problem is not local only.","zh":"當某模式廣泛重複，就顯示問題不只是本地問題。"},{"en":"The phrase emphasises broad geographical spread.","zh":"這個短語強調廣泛地理傳播。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":4},{"front":"accurate figures","meaning":"準確數字","examples":[{"en":"Accurate figures for the number of the sick and dead were rare.","zh":"關於病人和死者人數的準確數字很少。"},{"en":"Accurate figures are numbers that are correct and reliable.","zh":"accurate figures 是正確而可靠的數字。"},{"en":"A school needs accurate figures before deciding how many lunches to prepare.","zh":"學校在決定準備多少午餐前，需要準確數字。"},{"en":"Without accurate figures, people may underestimate or exaggerate a problem.","zh":"沒有準確數字，人們可能低估或誇大問題。"},{"en":"The phrase focuses on trustworthy numerical information.","zh":"這個短語重點在可信的數字資訊。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":5},{"front":"few and far between","meaning":"寥寥無幾","examples":[{"en":"Figures for the sick and dead were few and far between.","zh":"關於病人和死者的數字寥寥無幾。"},{"en":"Few and far between means rare and not often found.","zh":"few and far between 指罕見而不常找到。"},{"en":"Quiet study spaces are few and far between in a very crowded library.","zh":"在非常擁擠的圖書館中，安靜學習空間寥寥無幾。"},{"en":"If reliable reports are few and far between, people may rely on rumours.","zh":"如果可靠報告寥寥無幾，人們可能依賴謠言。"},{"en":"The phrase describes scarcity.","zh":"這個短語描述稀少。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":5},{"front":"report a huge upsurge in","meaning":"報告……大幅上升","examples":[{"en":"Paris, Berlin and Vienna reported a huge upsurge in deaths.","zh":"巴黎、柏林和維也納報告死亡人數大幅上升。"},{"en":"To report a huge upsurge in something means to announce a very large increase.","zh":"report a huge upsurge in 某事，指公布某事大幅增加。"},{"en":"A hospital may report a huge upsurge in emergency visits during a heatwave.","zh":"醫院可能在熱浪期間報告急症求診大幅上升。"},{"en":"A huge upsurge can show that a problem is spreading quickly.","zh":"大幅上升可以顯示問題正在快速擴散。"},{"en":"The phrase is often used with numbers, illness, crime or demand.","zh":"這個短語常與數字、疾病、罪案或需求一起使用。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":5},{"front":"take an intense interest in","meaning":"對……非常關注","examples":[{"en":"The newspapers took an intense interest in the disease.","zh":"報章對這種疾病非常關注。"},{"en":"To take an intense interest in something means to pay very close attention to it.","zh":"take an intense interest in 某事，指非常密切注意它。"},{"en":"Students may take an intense interest in a court case if it affects school rules.","zh":"如果某宗法庭案件影響校規，學生可能非常關注。"},{"en":"Media attention can grow when a subject affects both ordinary people and famous people.","zh":"當某題目影響普通人和名人，媒體關注可以增加。"},{"en":"The phrase describes strong curiosity or concern.","zh":"這個短語描述強烈好奇或關心。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":5},{"front":"the scale of","meaning":"……的規模","examples":[{"en":"The newspapers were interested in the scale of the pandemic.","zh":"報章關注大流行的規模。"},{"en":"The scale of something is its size, extent or seriousness.","zh":"the scale of 某事，是它的大小、範圍或嚴重程度。"},{"en":"A city must know the scale of flooding before sending rescue teams.","zh":"城市在派出救援隊前，必須知道水災規模。"},{"en":"Understanding scale helps people decide whether a problem needs local or national action.","zh":"理解規模幫助人判斷問題需要本地還是全國行動。"},{"en":"The phrase asks how big or serious something is.","zh":"這個短語問某事有多大或多嚴重。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":5},{"front":"carry off","meaning":"奪去……的生命","examples":[{"en":"Most epidemics carried off the poor and weak.","zh":"大多數疫情奪去窮人和弱者的生命。"},{"en":"To carry off someone means to cause that person’s death, especially through disease.","zh":"carry off 某人，指導致該人死亡，尤其是透過疾病。"},{"en":"A severe winter may carry off frail animals that cannot find food.","zh":"嚴冬可能奪去無法找到食物的虛弱動物的生命。"},{"en":"Epidemics often carry off people who are already vulnerable.","zh":"疫情常奪去本已脆弱者的生命。"},{"en":"The phrase is literary and means “kill.”","zh":"這個短語較文學化，意思是「殺死」。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":5},{"front":"old and frail","meaning":"年老體弱者","examples":[{"en":"Epidemics often killed the old and frail.","zh":"疫情常殺死年老體弱者。"},{"en":"The old and frail are elderly people whose bodies are weak or easily harmed.","zh":"the old and frail 是身體虛弱或容易受傷害的長者。"},{"en":"Care homes protect the old and frail by providing daily help and medical attention.","zh":"護老院透過提供日常協助和醫療照顧來保護年老體弱者。"},{"en":"Diseases can be more dangerous for the old and frail because recovery is harder.","zh":"疾病對年老體弱者可能更危險，因為康復較困難。"},{"en":"The phrase describes vulnerable elderly people.","zh":"這個短語描述脆弱的長者。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":5},{"front":"cut a swathe through","meaning":"大肆侵襲","examples":[{"en":"The flu cut a great swathe through the upper classes.","zh":"流感大肆侵襲上流階層。"},{"en":"To cut a swathe through a group means to affect or destroy many people within that group.","zh":"cut a swathe through 某群體，指影響或摧毀該群體中的許多人。"},{"en":"A serious computer virus can cut a swathe through small businesses if they lack protection.","zh":"如果缺乏防護，嚴重電腦病毒可以大肆侵襲小企業。"},{"en":"The phrase suggests damage spreading widely and forcefully.","zh":"這個短語暗示傷害廣泛而有力地擴散。"},{"en":"It is often used for disease, disaster or major disruption.","zh":"它常用於疾病、災害或重大中斷。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":5},{"front":"upper classes","meaning":"上流階層","examples":[{"en":"The flu affected the upper classes as well as the poor.","zh":"流感影響上流階層，也影響窮人。"},{"en":"The upper classes are people with high social status, wealth or inherited position.","zh":"upper classes 是社會地位、財富或世襲位置較高的人。"},{"en":"Expensive private schools were once mainly attended by children from the upper classes.","zh":"昂貴私校曾主要由上流階層子女就讀。"},{"en":"When disease reaches the upper classes, newspapers may pay more attention.","zh":"當疾病傳到上流階層，報章可能更關注。"},{"en":"The phrase describes social rank, not personal character.","zh":"這個短語描述社會階級，而不是個人性格。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":5},{"front":"deal death to","meaning":"使……喪命","examples":[{"en":"The disease dealt death to the rich and famous.","zh":"這種疾病使富人和名人喪命。"},{"en":"To deal death to people means to kill them or cause many deaths among them.","zh":"deal death to 人們，指殺死他們或在他們之中造成大量死亡。"},{"en":"A powerful earthquake can deal death to a city if buildings are unsafe.","zh":"如果建築不安全，強烈地震可以使城市中許多人喪命。"},{"en":"The phrase sounds dramatic and formal.","zh":"這個短語聽起來戲劇化且正式。"},{"en":"It emphasises the deadly effect of something.","zh":"它強調某事的致命影響。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":5},{"front":"the rich and famous","meaning":"富人和名人","examples":[{"en":"The flu killed many of the rich and famous.","zh":"流感殺死許多富人和名人。"},{"en":"The rich and famous are wealthy and well-known people.","zh":"the rich and famous 是富有且知名的人。"},{"en":"Magazines often report on the homes, marriages and illnesses of the rich and famous.","zh":"雜誌常報道富人和名人的住所、婚姻和疾病。"},{"en":"When the rich and famous are affected, public attention often increases.","zh":"當富人和名人受影響，公眾關注通常增加。"},{"en":"The phrase describes status and celebrity together.","zh":"這個短語同時描述財富地位和名氣。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":6},{"front":"newspaper-reading public","meaning":"閱報大眾","examples":[{"en":"The newspaper-reading public followed reports of celebrity victims.","zh":"閱報大眾追看名人受害者的報道。"},{"en":"The newspaper-reading public means ordinary people who regularly read newspapers.","zh":"newspaper-reading public 指定期閱讀報紙的普通大眾。"},{"en":"Before online news, the newspaper-reading public depended on printed reports for updates.","zh":"在網上新聞之前，閱報大眾依靠印刷報道取得最新消息。"},{"en":"Newspapers shaped public fear because readers saw new stories every day.","zh":"報章塑造公眾恐懼，因為讀者每天看見新故事。"},{"en":"The phrase describes a public audience reached through newspapers.","zh":"這個短語描述透過報紙接觸到的公眾受眾。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":6},{"front":"be fed a daily diet of","meaning":"每日被灌輸大量……","examples":[{"en":"The public was fed a daily diet of celebrity victims.","zh":"公眾每日被灌輸大量名人受害者的消息。"},{"en":"To be fed a daily diet of something means to receive the same kind of information repeatedly every day.","zh":"be fed a daily diet of 某事，指每天反覆接收同一類資訊。"},{"en":"Viewers may be fed a daily diet of bad news during a crisis.","zh":"在危機期間，觀眾可能每日被大量壞消息灌輸。"},{"en":"Repeated reports can shape people’s emotions and beliefs.","zh":"反覆報道可以塑造人的情緒和信念。"},{"en":"The phrase often suggests too much repetitive media content.","zh":"這個短語常暗示過多重複媒體內容。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":6},{"front":"celebrity victims","meaning":"名人受害者","examples":[{"en":"Newspapers reported daily on celebrity victims of the flu.","zh":"報章每日報道流感的名人受害者。"},{"en":"Celebrity victims are famous people harmed or killed by an event, illness or crime.","zh":"celebrity victims 是受事件、疾病或罪案傷害或殺死的名人。"},{"en":"The death of celebrity victims can make the public notice a danger more strongly.","zh":"名人受害者的死亡可以令公眾更強烈注意到危險。"},{"en":"Media focus on celebrities can sometimes hide the suffering of ordinary people.","zh":"媒體聚焦名人有時會掩蓋普通人的苦難。"},{"en":"The phrase combines fame with harm.","zh":"這個短語結合名氣和受害。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":6},{"front":"work one’s way through","meaning":"逐步蔓延至","examples":[{"en":"The flu worked its way through the Russian imperial family.","zh":"流感逐步蔓延至俄羅斯皇室。"},{"en":"To work one’s way through a group means to move gradually through it, affecting one person after another.","zh":"work one’s way through 某群體，指逐漸在其中移動，影響一個又一個人。"},{"en":"A rumour may work its way through a school before teachers hear about it.","zh":"謠言可能在老師得知前已逐步傳遍學校。"},{"en":"Disease can work its way through a family when people live closely together.","zh":"當人們住得很近，疾病可以逐步蔓延至一家人。"},{"en":"The phrase suggests gradual spread inside a group.","zh":"這個短語暗示在群體內逐漸傳播。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":6},{"front":"imperial family","meaning":"皇室","examples":[{"en":"The flu spread through the Russian imperial family.","zh":"流感在俄羅斯皇室中傳播。"},{"en":"An imperial family is the family of an emperor or empress.","zh":"imperial family 是皇帝或女皇的家族。"},{"en":"Members of an imperial family often live under public attention and formal rules.","zh":"皇室成員通常生活在公眾關注和正式規則之下。"},{"en":"Illness in an imperial family could become major news because of political importance.","zh":"皇室中有人生病可能成為重大新聞，因為有政治重要性。"},{"en":"The phrase refers to royal power connected with an empire.","zh":"這個短語指與帝國權力相關的王室。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":6},{"front":"royal palaces","meaning":"皇家宮殿","examples":[{"en":"The disease invaded the royal palaces of Europe.","zh":"疾病侵入歐洲的皇家宮殿。"},{"en":"Royal palaces are large official homes of kings, queens or royal families.","zh":"royal palaces 是國王、女王或皇室家族的大型官方住所。"},{"en":"Tourists may visit royal palaces to see rooms, gardens and historical objects.","zh":"遊客可能參觀皇家宮殿，觀看房間、花園和歷史物品。"},{"en":"If disease reaches royal palaces, it suggests even protected elites are not safe.","zh":"如果疾病到達皇家宮殿，這暗示即使受保護的精英也不安全。"},{"en":"The phrase refers to the grand residences of royalty.","zh":"這個短語指皇室的宏偉住所。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":6},{"front":"carry off","meaning":"奪去……的生命","examples":[{"en":"The flu carried off the Dowager Empress of Germany.","zh":"流感奪去德國皇太后的生命。"},{"en":"To carry off someone means to kill that person, especially through disease.","zh":"carry off 某人，指殺死該人，尤其是透過疾病。"},{"en":"A severe infection can carry off a weak patient within days.","zh":"嚴重感染可以在數日內奪去虛弱病人的生命。"},{"en":"The phrase makes death sound sudden and forceful.","zh":"這個短語令死亡聽起來突然且有力。"},{"en":"It is more literary than simply saying “killed.”","zh":"它比 simply saying “killed” 更文學化。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":6},{"front":"Dowager Empress","meaning":"皇太后","examples":[{"en":"The Dowager Empress of Germany died from the flu.","zh":"德國皇太后死於流感。"},{"en":"A Dowager Empress is the widow of an emperor or a former empress with senior royal status.","zh":"Dowager Empress 是皇帝遺孀，或具有高級皇室地位的前皇后。"},{"en":"A dowager queen or empress may still be respected after her husband’s death.","zh":"皇太后或王太后在丈夫死後仍可能受尊敬。"},{"en":"The death of a dowager empress would attract attention because of her rank.","zh":"皇太后死亡會因其地位而引起關注。"},{"en":"The phrase describes a high-ranking royal woman.","zh":"這個短語描述高級皇室女性。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":6},{"front":"none escaped","meaning":"無一逃過","examples":[{"en":"None escaped the attentions of the Russian flu.","zh":"無一逃過俄羅斯流感的侵襲。"},{"en":"None escaped means no person or group avoided being affected.","zh":"none escaped 指沒有任何人或群體避免受到影響。"},{"en":"In a small office, none escaped the noise when construction began next door.","zh":"當隔壁開始施工，小辦公室裏無人逃過噪音。"},{"en":"If none escape a problem, it affects every level of society.","zh":"如果無一逃過問題，它就影響社會每一層。"},{"en":"The phrase stresses total reach.","zh":"這個短語強調影響全面。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":6},{"front":"grow increasingly fearful","meaning":"變得越來越恐懼","examples":[{"en":"The public grew increasingly fearful during the pandemic.","zh":"公眾在大流行期間變得越來越恐懼。"},{"en":"To grow increasingly fearful means to become more and more afraid over time.","zh":"grow increasingly fearful 指隨時間變得越來越害怕。"},{"en":"Parents may grow increasingly fearful if school rumours are not explained clearly.","zh":"如果學校謠言沒有清楚解釋，家長可能變得越來越恐懼。"},{"en":"Repeated alarming news can make fear build gradually.","zh":"反覆令人不安的新聞可以令恐懼逐漸累積。"},{"en":"The phrase describes fear rising over time.","zh":"這個短語描述恐懼隨時間上升。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":7},{"front":"doom and gloom","meaning":"悲觀恐慌氣氛","examples":[{"en":"The press may have been overdoing the doom and gloom.","zh":"報章可能過度渲染悲觀恐慌氣氛。"},{"en":"Doom and gloom means a very negative mood full of fear and pessimism.","zh":"doom and gloom 指充滿恐懼和悲觀的非常負面氣氛。"},{"en":"News about falling exam results can create doom and gloom if no solutions are discussed.","zh":"如果不討論解決方法，關於考試成績下降的新聞可以造成悲觀恐慌氣氛。"},{"en":"Too much doom and gloom can make people panic instead of act calmly.","zh":"太多悲觀恐慌氣氛會令人恐慌，而不是冷靜行動。"},{"en":"The phrase often criticises overly negative reporting.","zh":"這個短語常批評過度負面的報道。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":7},{"front":"hysterical coverage","meaning":"歇斯底里的報道","examples":[{"en":"The newspapers’ hysterical coverage exposed a terrible fact.","zh":"報章歇斯底里的報道揭示了一個可怕事實。"},{"en":"Hysterical coverage is media reporting that is extremely emotional, alarming or exaggerated.","zh":"hysterical coverage 是極度情緒化、令人驚慌或誇張的媒體報道。"},{"en":"Hysterical coverage of a small crime can make a neighbourhood feel unsafe.","zh":"對小罪案歇斯底里的報道可以令社區感到不安全。"},{"en":"Such reporting may attract readers but also increase fear.","zh":"這類報道可能吸引讀者，但也會增加恐懼。"},{"en":"The phrase criticises media that loses balance.","zh":"這個短語批評失去平衡的媒體。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":7},{"front":"expose one terrible fact","meaning":"揭示一個可怕事實","examples":[{"en":"The coverage exposed one terrible fact about medicine.","zh":"該報道揭示了一個關於醫學的可怕事實。"},{"en":"To expose one terrible fact means to reveal one frightening truth that had been hidden or ignored.","zh":"expose one terrible fact 指揭示一個曾被隱藏或忽略的可怕真相。"},{"en":"A school report may expose one terrible fact: many students cannot read basic texts.","zh":"學校報告可能揭示一個可怕事實：許多學生不能閱讀基本文本。"},{"en":"Exposing a fact can force people to face a problem honestly.","zh":"揭示事實可以迫使人誠實面對問題。"},{"en":"The phrase suggests revelation of an uncomfortable truth.","zh":"這個短語暗示揭露令人不安的真相。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":7},{"front":"medical profession","meaning":"醫學界","examples":[{"en":"The medical profession had no answer to the disease.","zh":"醫學界對這種疾病束手無策。"},{"en":"The medical profession means doctors and other people formally trained to practise medicine.","zh":"medical profession 指醫生和其他受正式訓練行醫的人。"},{"en":"The medical profession may advise the public during an outbreak.","zh":"醫學界可能在疫情期間向公眾提出建議。"},{"en":"If the medical profession has no clear treatment, public anxiety can rise.","zh":"如果醫學界沒有明確治療方法，公眾焦慮可能上升。"},{"en":"The phrase refers to the healthcare field as a professional group.","zh":"這個短語指作為專業群體的醫療領域。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":7},{"front":"have no answer to","meaning":"對……束手無策","examples":[{"en":"Doctors had no answer to the disease.","zh":"醫生對這種疾病束手無策。"},{"en":"To have no answer to a problem means to have no effective solution or explanation.","zh":"have no answer to 某問題，指沒有有效解決方案或解釋。"},{"en":"A school may have no answer to bullying if it ignores repeated complaints.","zh":"如果學校忽視反覆投訴，可能對欺凌束手無策。"},{"en":"When experts have no answer, people may look for help elsewhere.","zh":"當專家束手無策，人們可能另尋幫助。"},{"en":"The phrase describes helplessness in facing a problem.","zh":"這個短語描述面對問題時的無力感。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":7},{"front":"no one could agree on","meaning":"沒有人能就……達成共識","examples":[{"en":"No one could agree on what caused the flu.","zh":"沒有人能就流感成因達成共識。"},{"en":"No one could agree on something means people could not reach a shared opinion about it.","zh":"no one could agree on 某事，指人們無法形成共同看法。"},{"en":"A team may not agree on the best design if everyone values different features.","zh":"如果每個人重視不同特點，團隊可能無法就最佳設計達成共識。"},{"en":"Without agreement, action can become confused or delayed.","zh":"沒有共識時，行動可能變得混亂或延誤。"},{"en":"The phrase describes lack of consensus.","zh":"這個短語描述缺乏共識。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":7},{"front":"micro-organisms","meaning":"微生物","examples":[{"en":"The theory that micro-organisms caused disease was gaining ground.","zh":"微生物導致疾病的理論正逐漸被接受。"},{"en":"Micro-organisms are tiny living things, such as bacteria or viruses, that are too small to see easily.","zh":"micro-organisms 是細菌或病毒等非常細小、不易看見的生物。"},{"en":"Washing hands helps remove some micro-organisms before they spread.","zh":"洗手有助在微生物傳播前移除其中一些。"},{"en":"Some micro-organisms cause disease, while others are harmless or useful.","zh":"有些微生物會致病，另一些則無害或有用。"},{"en":"The word refers to very small life forms.","zh":"這個字指非常細小的生命形式。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":7},{"front":"gain ground","meaning":"逐漸被接受","examples":[{"en":"The theory that micro-organisms caused disease was gaining ground.","zh":"微生物導致疾病的理論正逐漸被接受。"},{"en":"To gain ground means to become more accepted, popular or successful.","zh":"gain ground 指變得更被接受、更受歡迎或更成功。"},{"en":"Online learning gained ground when schools needed flexible ways to teach.","zh":"當學校需要靈活教學方式，網上學習逐漸被接受。"},{"en":"An idea gains ground when more people see evidence for it.","zh":"當更多人看到證據，某想法就會逐漸被接受。"},{"en":"The phrase describes gradual progress in acceptance.","zh":"這個短語描述接受程度逐步增加。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":7},{"front":"be responsible for","meaning":"對……負責；是……成因","examples":[{"en":"No one had identified an organism responsible for flu.","zh":"沒有人辨認出導致流感的生物。"},{"en":"To be responsible for something means to be the cause of it.","zh":"be responsible for 某事，指是該事的原因。"},{"en":"A faulty wire may be responsible for a power failure.","zh":"故障電線可能是停電的原因。"},{"en":"Finding what is responsible for a problem helps people choose the right solution.","zh":"找出問題成因有助人選擇正確解決方法。"},{"en":"The phrase can mean causing something, not only having a duty.","zh":"這個短語可以指造成某事，不只是有責任。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":7},{"front":"in the absence of","meaning":"在缺乏……的情況下","examples":[{"en":"In the absence of a germ, many people clung to older theories.","zh":"在缺乏病菌證據的情況下，許多人固守舊理論。"},{"en":"In the absence of something means when that thing is missing or unavailable.","zh":"in the absence of 某物，指當該物缺失或不可用時。"},{"en":"In the absence of clear instructions, students may guess what the teacher wants.","zh":"在缺乏清楚指示的情況下，學生可能猜測老師想要甚麼。"},{"en":"When evidence is absent, people may return to older beliefs.","zh":"當證據缺失，人們可能回到舊信念。"},{"en":"The phrase explains what happens when something important is lacking.","zh":"這個短語解釋重要東西缺乏時會發生甚麼。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":8},{"front":"cling to","meaning":"堅持；固守","examples":[{"en":"Many people clung to the old idea of bad airs.","zh":"許多人固守壞空氣這個舊想法。"},{"en":"To cling to an idea means to hold onto it strongly, even when others question it.","zh":"cling to 某想法，指即使別人質疑也強烈抓住它。"},{"en":"A student may cling to a wrong grammar rule because it once worked in one example.","zh":"學生可能固守一條錯誤文法規則，因為它曾在一個例子中有效。"},{"en":"People often cling to familiar beliefs when new evidence feels confusing.","zh":"當新證據令人困惑，人們常固守熟悉信念。"},{"en":"The phrase suggests stubborn attachment.","zh":"這個短語暗示頑固依附。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":8},{"front":"bad airs","meaning":"壞空氣；瘴氣","examples":[{"en":"Some people believed flu was caused by bad airs.","zh":"有些人相信流感由壞空氣造成。"},{"en":"Bad airs means unhealthy or polluted air believed to cause disease in older theories.","zh":"bad airs 指舊理論中被認為會致病的不健康或污染空氣。"},{"en":"Before modern germ theory, people often blamed bad airs for illness.","zh":"在現代細菌理論之前，人們常把疾病歸咎於壞空氣。"},{"en":"If people believe disease comes from bad air only, they may miss other causes.","zh":"如果人們相信疾病只來自壞空氣，可能錯過其他原因。"},{"en":"The phrase reflects an older medical explanation.","zh":"這個短語反映較舊的醫學解釋。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":8},{"front":"miasmas","meaning":"瘴氣","examples":[{"en":"Many people still believed in miasmas as a cause of disease.","zh":"許多人仍相信瘴氣是疾病成因。"},{"en":"Miasmas were harmful airs or vapours once believed to cause illness.","zh":"miasmas 是曾被認為會致病的有害空氣或蒸氣。"},{"en":"People once thought dirty streets produced miasmas that spread disease.","zh":"人們曾以為骯髒街道產生會傳播疾病的瘴氣。"},{"en":"The idea of miasmas declined as germ theory became stronger.","zh":"隨着細菌理論變強，瘴氣說逐漸衰落。"},{"en":"The word belongs to older medical thinking.","zh":"這個字屬於較舊的醫學思想。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":8},{"front":"be stirred by","meaning":"被……攪動","examples":[{"en":"Miasmas were thought to be stirred by physical forces.","zh":"瘴氣被認為會被物理力量攪動。"},{"en":"To be stirred by something means to be moved, disturbed or activated by it.","zh":"be stirred by 某物，指被它移動、擾動或激活。"},{"en":"Dust can be stirred by a strong wind in a dry street.","zh":"在乾燥街道上，灰塵可以被強風吹起。"},{"en":"If harmful air is believed to be stirred by weather, people may blame natural forces for illness.","zh":"如果有害空氣被認為由天氣攪動，人們可能把疾病歸咎於自然力量。"},{"en":"The phrase describes something being set in motion.","zh":"這個短語描述某物被帶動。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":8},{"front":"electrical phenomena","meaning":"電氣現象","examples":[{"en":"Some people blamed electrical phenomena in the upper atmosphere.","zh":"有些人把責任歸咎於高層大氣中的電氣現象。"},{"en":"Electrical phenomena are events involving electricity, such as lightning or electrical changes.","zh":"electrical phenomena 是涉及電的事件，例如閃電或電氣變化。"},{"en":"Lightning during a storm is a familiar electrical phenomenon.","zh":"暴風雨中的閃電是熟悉的電氣現象。"},{"en":"In the passage, such phenomena were wrongly used by some people to explain disease.","zh":"在文章中，有些人錯誤地用這些現象解釋疾病。"},{"en":"The phrase names physical events connected with electricity.","zh":"這個短語指出與電相關的物理事件。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":8},{"front":"upper atmosphere","meaning":"高層大氣","examples":[{"en":"Some theories involved electrical phenomena in the upper atmosphere.","zh":"有些理論涉及高層大氣中的電氣現象。"},{"en":"The upper atmosphere is the high layer of air far above the ground.","zh":"upper atmosphere 是遠離地面的高空空氣層。"},{"en":"Pilots and scientists study the upper atmosphere to understand weather and air movement.","zh":"飛行員和科學家研究高層大氣，以理解天氣和空氣流動。"},{"en":"Events high in the atmosphere were once used to explain mysterious diseases.","zh":"高空大氣中的事件曾被用來解釋神秘疾病。"},{"en":"The phrase refers to air far above ordinary breathing level.","zh":"這個短語指遠高於普通呼吸高度的空氣。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":8},{"front":"passing comet","meaning":"經過的彗星","examples":[{"en":"Some people even blamed a passing comet.","zh":"有些人甚至歸咎於一顆經過的彗星。"},{"en":"A passing comet is a comet moving through the sky near Earth’s view.","zh":"passing comet 是從天空中經過、在地球視野附近移動的彗星。"},{"en":"People in the past sometimes connected unusual sky events with disasters on Earth.","zh":"過去人們有時把異常天象與地上災難連繫起來。"},{"en":"Blaming a passing comet shows how little people understood the disease.","zh":"把責任歸咎於經過的彗星，顯示人們對疾病理解很少。"},{"en":"The phrase refers to a temporary astronomical event.","zh":"這個短語指暫時性的天文事件。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":8},{"front":"advise someone to","meaning":"建議某人去","examples":[{"en":"Doctors advised people to eat well and avoid crowds.","zh":"醫生建議人們吃得好並避開人群。"},{"en":"To advise someone to do something means to recommend that action.","zh":"advise someone to do something 指建議某人採取該行動。"},{"en":"A teacher may advise students to read the question twice before answering.","zh":"老師可能建議學生回答前先讀兩次題目。"},{"en":"Advice is useful when it gives clear action, not just vague worry.","zh":"建議在給出清楚行動時才有用，而不只是模糊擔憂。"},{"en":"The phrase introduces guidance from someone with knowledge or authority.","zh":"這個短語引出有知識或權威人士的指導。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":8},{"front":"unnecessary assemblies","meaning":"不必要的聚集","examples":[{"en":"Doctors advised people to avoid unnecessary assemblies.","zh":"醫生建議人們避免不必要的聚集。"},{"en":"Unnecessary assemblies are gatherings that are not essential.","zh":"unnecessary assemblies 是非必要的集會或聚集。"},{"en":"A school may cancel unnecessary assemblies during a flu outbreak.","zh":"學校可能在流感爆發期間取消不必要的集會。"},{"en":"Avoiding non-essential gatherings can reduce the chance of disease spreading.","zh":"避免非必要聚集可以降低疾病傳播機會。"},{"en":"The phrase is formal and often relates to public health advice.","zh":"這個短語較正式，常與公共衞生建議有關。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":8},{"front":"stuff cotton wool up","meaning":"把棉花塞進……","examples":[{"en":"Worried people were told to stuff cotton wool up their nostrils.","zh":"擔心的人被告知把棉花塞進鼻孔。"},{"en":"To stuff cotton wool up something means to push cotton wool into it tightly.","zh":"stuff cotton wool up 某處，指把棉花緊緊塞進去。"},{"en":"A child might stuff tissue up his nose to stop a nosebleed, though adults should guide him safely.","zh":"孩子可能把紙巾塞進鼻子止鼻血，但成人應安全指導。"},{"en":"In the passage, this advice shows how uncertain medical prevention was.","zh":"在文章中，這項建議顯示當時醫學預防多麼不確定。"},{"en":"The phrase describes a physical action, often awkward or uncomfortable.","zh":"這個短語描述身體動作，常顯得笨拙或不舒服。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":9},{"front":"nostrils","meaning":"鼻孔","examples":[{"en":"Some doctors advised people to put cotton wool in their nostrils.","zh":"有些醫生建議人們把棉花放進鼻孔。"},{"en":"Nostrils are the two openings of the nose.","zh":"nostrils 是鼻子的兩個開口。"},{"en":"A person breathes through the nostrils when the mouth is closed.","zh":"當嘴巴閉上，人會透過鼻孔呼吸。"},{"en":"Smoke, dust or strong smells can irritate the nostrils.","zh":"煙、灰塵或強烈氣味可以刺激鼻孔。"},{"en":"The word names a simple body part used in breathing.","zh":"這個字指出用於呼吸的簡單身體部位。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":9},{"front":"fall ill","meaning":"生病","examples":[{"en":"If people fell ill, they were told to rest and keep warm.","zh":"如果人們生病，他們被告知要休息和保暖。"},{"en":"To fall ill means to become sick.","zh":"fall ill 指開始生病。"},{"en":"A student who falls ill before an exam should tell the school as soon as possible.","zh":"考試前生病的學生應盡快告訴學校。"},{"en":"When people fall ill, rest and care may help prevent the illness from worsening.","zh":"當人們生病，休息和照顧可能有助防止病情惡化。"},{"en":"The phrase describes becoming unwell, not recovering.","zh":"這個短語描述變得不適，而不是康復。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":9},{"front":"nourishing diet","meaning":"有營養的飲食","examples":[{"en":"Patients were advised to eat a nourishing diet.","zh":"病人被建議吃有營養的飲食。"},{"en":"A nourishing diet is food that gives the body useful nutrients and energy.","zh":"nourishing diet 是能給身體有用營養和能量的食物。"},{"en":"Soup, eggs, vegetables and rice can form part of a nourishing diet after illness.","zh":"病後湯、雞蛋、蔬菜和米飯都可以是有營養飲食的一部分。"},{"en":"Good nutrition can support recovery, especially when the body is weak.","zh":"良好營養可以支持康復，尤其當身體虛弱時。"},{"en":"The phrase describes food that strengthens health.","zh":"這個短語描述能強健身體的食物。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":9},{"front":"farinaceous puddings","meaning":"澱粉質布甸","examples":[{"en":"Doctors recommended milk, eggs and farinaceous puddings.","zh":"醫生建議牛奶、雞蛋和澱粉質布甸。"},{"en":"Farinaceous puddings are soft foods made mainly from starchy ingredients such as flour or grain.","zh":"farinaceous puddings 是主要由麵粉或穀物等澱粉材料製成的軟食。"},{"en":"A sick patient may be given soft starchy food because it is easy to eat.","zh":"病人可能被給予柔軟澱粉食物，因為容易進食。"},{"en":"Such foods can provide energy when a person cannot manage a heavy meal.","zh":"當一個人不能吃重口味大餐，這類食物可以提供能量。"},{"en":"The phrase is old-fashioned and related to medical diet advice in the passage.","zh":"這個短語較舊式，與文章中的醫療飲食建議有關。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":9},{"front":"figure prominently among","meaning":"在……中佔重要位置","examples":[{"en":"Alcohol figured prominently among the prescriptions.","zh":"酒精在處方中佔重要位置。"},{"en":"To figure prominently among something means to appear as an important or noticeable part of it.","zh":"figure prominently among 某些事物，指作為重要或明顯部分出現。"},{"en":"Technology figures prominently among the tools used in modern classrooms.","zh":"科技在現代課室使用的工具中佔重要位置。"},{"en":"If one item figures prominently in advice, people may think it is especially important.","zh":"如果某項東西在建議中佔重要位置，人們可能認為它特別重要。"},{"en":"The phrase highlights a major presence within a group.","zh":"這個短語突出在一組事物中的主要存在。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":9},{"front":"prescriptions","meaning":"處方","examples":[{"en":"Alcohol appeared in many prescriptions for flu.","zh":"酒精出現在許多流感處方中。"},{"en":"Prescriptions are written medical instructions for treatment or medicine.","zh":"prescriptions 是關於治療或藥物的書面醫療指示。"},{"en":"A doctor may write prescriptions for antibiotics when a bacterial infection is confirmed.","zh":"當細菌感染被確認，醫生可能開抗生素處方。"},{"en":"Prescriptions tell patients what to take, how much and how often.","zh":"處方告訴病人服用甚麼、多少和多久一次。"},{"en":"The word refers to official medical directions.","zh":"這個字指官方醫療指示。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":9},{"front":"eminent doctor","meaning":"著名醫生","examples":[{"en":"One eminent English doctor suggested champagne.","zh":"一位著名英國醫生建議香檳。"},{"en":"An eminent doctor is a highly respected and well-known doctor.","zh":"eminent doctor 是備受尊敬且知名的醫生。"},{"en":"An eminent doctor may be invited to speak at medical conferences.","zh":"著名醫生可能受邀在醫學會議上發言。"},{"en":"People may trust advice more when it comes from an eminent doctor.","zh":"當建議來自著名醫生，人們可能更信任。"},{"en":"The phrase describes professional status and public respect.","zh":"這個短語描述專業地位和公眾尊敬。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":9},{"front":"concede","meaning":"承認","examples":[{"en":"He conceded that brandy had sometimes been helpful.","zh":"他承認白蘭地有時有幫助。"},{"en":"To concede means to admit something is true, often reluctantly.","zh":"concede 指承認某事為真，通常帶不情願意味。"},{"en":"A student may concede that her first answer was wrong after seeing the evidence.","zh":"學生看到證據後，可能承認自己的第一個答案錯了。"},{"en":"Conceding a point can make an argument more honest.","zh":"承認一點可以令論證更誠實。"},{"en":"The word often appears when someone accepts a limited truth.","zh":"這個字常在某人接受有限真相時出現。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":9},{"front":"considerable quantities","meaning":"大量","examples":[{"en":"Brandy was sometimes given in considerable quantities.","zh":"白蘭地有時會以大量給予。"},{"en":"Considerable quantities means large amounts.","zh":"considerable quantities 指大量。"},{"en":"A school kitchen may need considerable quantities of rice for a festival lunch.","zh":"學校廚房為節日午餐可能需要大量米飯。"},{"en":"Giving anything in large quantities can be risky if the effect is not understood.","zh":"如果效果不清楚，大量給予任何東西都可能有風險。"},{"en":"The phrase emphasises amount, not quality.","zh":"這個短語強調數量，而不是質素。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":9},{"front":"with manifest advantages","meaning":"有明顯好處","examples":[{"en":"Some doctors claimed brandy was given with manifest advantages.","zh":"有些醫生聲稱給予白蘭地有明顯好處。"},{"en":"With manifest advantages means with clear and obvious benefits.","zh":"with manifest advantages 指帶有清楚而明顯的好處。"},{"en":"A school may introduce smaller classes with manifest advantages for weaker students.","zh":"學校可能引入小班教學，對較弱學生有明顯好處。"},{"en":"If advantages are truly manifest, people can see the improvement quickly.","zh":"如果好處真的明顯，人們可以很快看見改善。"},{"en":"The phrase sounds formal and confident.","zh":"這個短語聽起來正式且有信心。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":10},{"front":"prescribe warm alcoholic drinks","meaning":"處方暖酒精飲品","examples":[{"en":"French doctors prescribed warm alcoholic drinks.","zh":"法國醫生處方暖酒精飲品。"},{"en":"To prescribe warm alcoholic drinks means to recommend them as a medical treatment.","zh":"prescribe warm alcoholic drinks 指把暖酒精飲品建議為醫療治療。"},{"en":"A doctor today would usually prescribe tested medicine rather than alcohol for illness.","zh":"今天醫生通常會為疾病處方經測試的藥物，而不是酒精。"},{"en":"Historical prescriptions show how medical advice can change over time.","zh":"歷史處方顯示醫療建議可以隨時間改變。"},{"en":"The phrase describes a treatment recommendation in the passage’s historical context.","zh":"這個短語描述文章歷史背景中的治療建議。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":10},{"front":"immediate results","meaning":"即時效果","examples":[{"en":"The prescription had immediate results in Paris.","zh":"該處方在巴黎產生即時效果。"},{"en":"Immediate results are effects that happen very quickly after an action.","zh":"immediate results 是行動後很快發生的效果。"},{"en":"A loud alarm has immediate results because people leave the building at once.","zh":"響亮警鐘有即時效果，因為人們立刻離開大樓。"},{"en":"Immediate results are not always the same as good or lasting results.","zh":"即時效果不一定等於良好或持久效果。"},{"en":"The phrase focuses on speed of effect.","zh":"這個短語重點在效果速度。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":10},{"front":"picked up on the streets","meaning":"在街上被帶走","examples":[{"en":"Many drunks picked up on the streets claimed to be following medical advice.","zh":"許多在街上被帶走的醉漢聲稱自己是在遵從醫療建議。"},{"en":"Picked up on the streets means found and taken away by authorities or helpers in public places.","zh":"picked up on the streets 指在公共地方被當局或幫助者發現並帶走。"},{"en":"Police may pick up a lost child on the streets and take him to a safe place.","zh":"警察可能在街上發現迷路小孩，並把他帶到安全地方。"},{"en":"In the passage, the phrase suggests drunk people were found outside and removed.","zh":"在文章中，這個短語暗示醉酒人士在外面被發現並帶走。"},{"en":"The phrase describes being discovered in public and taken away.","zh":"這個短語描述在公共地方被發現並帶走。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":10},{"front":"follow doctor’s orders","meaning":"遵從醫生指示","examples":[{"en":"The drunks claimed they were following doctor’s orders.","zh":"那些醉漢聲稱自己是在遵從醫生指示。"},{"en":"To follow doctor’s orders means to do exactly what a doctor has advised.","zh":"follow doctor’s orders 指完全按照醫生建議去做。"},{"en":"A patient follows doctor’s orders by taking medicine at the right time.","zh":"病人按時服藥，就是遵從醫生指示。"},{"en":"If people misunderstand medical advice, they may claim to follow orders while doing harm.","zh":"如果人們誤解醫療建議，他們可能聲稱遵從指示，卻造成傷害。"},{"en":"The phrase usually suggests obedience to medical instructions.","zh":"這個短語通常暗示服從醫療指示。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":10},{"front":"ease symptoms","meaning":"紓緩症狀","examples":[{"en":"Some doctors gave drugs to ease symptoms.","zh":"有些醫生給藥來紓緩症狀。"},{"en":"To ease symptoms means to reduce discomfort caused by illness without necessarily curing it.","zh":"ease symptoms 指減少疾病造成的不適，但不一定治癒疾病。"},{"en":"Cough medicine may ease symptoms so a patient can sleep better.","zh":"咳藥可能紓緩症狀，讓病人睡得更好。"},{"en":"Symptom relief can help people feel better while the body recovers.","zh":"症狀紓緩可以在身體康復期間令人感覺好些。"},{"en":"The phrase describes comfort, not always a complete cure.","zh":"這個短語描述舒緩，而不一定是完全治癒。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":10},{"front":"quinine for fever","meaning":"用奎寧治療發燒","examples":[{"en":"Some doctors gave quinine for fever.","zh":"有些醫生用奎寧治療發燒。"},{"en":"Quinine for fever means using quinine as a treatment intended to reduce fever.","zh":"quinine for fever 指使用奎寧作為降低發燒的治療。"},{"en":"A patient with a high temperature may be given medicine to bring the fever down.","zh":"高燒病人可能被給藥，以把體溫降下來。"},{"en":"Historical treatments sometimes used drugs for symptoms even when the disease cause was unclear.","zh":"歷史治療有時在病因不清楚時，用藥處理症狀。"},{"en":"The phrase names a medicine and the symptom it was meant to treat.","zh":"這個短語指出藥物和它要治療的症狀。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":10},{"front":"salicin for headache","meaning":"用水楊苷治療頭痛","examples":[{"en":"Some doctors gave salicin for headache.","zh":"有些醫生用水楊苷治療頭痛。"},{"en":"Salicin for headache means using salicin to relieve head pain.","zh":"salicin for headache 指使用水楊苷紓緩頭痛。"},{"en":"A student with a headache may take approved pain relief after checking the correct dose.","zh":"頭痛學生在確認正確劑量後，可能服用認可止痛藥。"},{"en":"Treating a headache can make rest easier, but it may not cure the illness behind it.","zh":"治療頭痛可以令休息更容易，但未必治癒背後疾病。"},{"en":"The phrase names a symptom-based treatment.","zh":"這個短語指出一種針對症狀的治療。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":10},{"front":"incessant cough","meaning":"持續不斷的咳嗽","examples":[{"en":"Heroin was used for an incessant cough.","zh":"海洛英曾被用於持續不斷的咳嗽。"},{"en":"An incessant cough is a cough that continues again and again without stopping.","zh":"incessant cough 是一次又一次持續、沒有停止的咳嗽。"},{"en":"A child with an incessant cough may be too tired to sleep properly.","zh":"有持續不斷咳嗽的孩子可能太疲倦，無法好好睡覺。"},{"en":"Continuous coughing can irritate the throat and exhaust the patient.","zh":"不斷咳嗽可以刺激喉嚨並令病人疲憊。"},{"en":"The phrase describes a persistent symptom.","zh":"這個短語描述持續症狀。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":10},{"front":"remotely resemble","meaning":"與……完全談不上相似","examples":[{"en":"Nothing in the pharmacy remotely resembled a cure.","zh":"藥房裏沒有任何東西與治癒方法談得上相似。"},{"en":"To remotely resemble something means to be even slightly similar to it, usually in a negative sentence.","zh":"remotely resemble 某物，指即使略為相似，通常用於否定句。"},{"en":"A rushed apology may not remotely resemble real responsibility.","zh":"草率道歉可能完全談不上真正負責。"},{"en":"If a treatment does not remotely resemble a cure, it may only reduce discomfort.","zh":"如果一種治療與治癒方法完全談不上相似，它可能只減少不適。"},{"en":"The phrase stresses that there is almost no similarity.","zh":"這個短語強調幾乎沒有相似之處。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":10},{"front":"look elsewhere for help","meaning":"另尋幫助","examples":[{"en":"People looked elsewhere for help when doctors had no cure.","zh":"當醫生沒有治療方法，人們另尋幫助。"},{"en":"To look elsewhere for help means to seek support from another source.","zh":"look elsewhere for help 指從另一個來源尋求支援。"},{"en":"If a school cannot answer a parent’s question, the parent may look elsewhere for advice.","zh":"如果學校不能回答家長問題，家長可能另尋建議。"},{"en":"People often look elsewhere when trusted authorities have no solution.","zh":"當受信任權威沒有解決方法，人們常另尋幫助。"},{"en":"The phrase describes turning away from one source toward another.","zh":"這個短語描述由一個來源轉向另一個來源。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":11},{"front":"cash in","meaning":"趁機牟利","examples":[{"en":"Medicine sellers hoped to cash in while the pandemic lasted.","zh":"藥物販賣者希望在大流行期間趁機牟利。"},{"en":"To cash in means to make money from an opportunity, often in a selfish way.","zh":"cash in 指從某機會中賺錢，常帶自私意味。"},{"en":"Some shops may cash in on panic by raising prices during a shortage.","zh":"在短缺期間，有些商店可能透過抬價趁恐慌牟利。"},{"en":"When fear is high, dishonest sellers may try to profit from it.","zh":"當恐懼很高，不誠實賣家可能試圖從中獲利。"},{"en":"The phrase often criticises opportunistic profit-making.","zh":"這個短語常批評投機牟利。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":11},{"front":"purveyors of patent medicines","meaning":"專利成藥販賣者","examples":[{"en":"Purveyors of patent medicines competed for public attention.","zh":"專利成藥販賣者爭奪公眾注意。"},{"en":"Purveyors of patent medicines were sellers of branded remedies often promoted with bold claims.","zh":"purveyors of patent medicines 是銷售品牌藥物的人，這些藥物常以大膽聲稱宣傳。"},{"en":"A seller of miracle pills may act like a purveyor of patent medicines if the claims are untested.","zh":"如果神奇藥丸的聲稱未經測試，賣家就像專利成藥販賣者。"},{"en":"Such sellers can profit when people are afraid and desperate for treatment.","zh":"當人們害怕並急切求醫，這類賣家可以牟利。"},{"en":"The phrase describes commercial sellers of supposed cures.","zh":"這個短語描述出售所謂療法的商業賣家。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":11},{"front":"compete for","meaning":"爭奪","examples":[{"en":"Patent medicine sellers competed for the public’s custom.","zh":"專利成藥賣家爭奪大眾生意。"},{"en":"To compete for something means to try to win it against others.","zh":"compete for 某物，指與他人競爭以取得它。"},{"en":"Restaurants compete for customers by offering better food, prices or service.","zh":"餐廳透過更好食物、價格或服務爭奪顧客。"},{"en":"Competition can lead to better products, but it can also lead to exaggerated claims.","zh":"競爭可以帶來更好產品，但也可以導致誇張聲稱。"},{"en":"The phrase describes rivalry for attention, money or support.","zh":"這個短語描述為注意力、金錢或支持而競爭。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":11},{"front":"public’s custom","meaning":"大眾的生意","examples":[{"en":"The sellers competed for the public’s custom.","zh":"賣家爭奪大眾的生意。"},{"en":"The public’s custom means business or purchases from ordinary customers.","zh":"public’s custom 指普通顧客的生意或購買。"},{"en":"Small shops depend on local custom to survive.","zh":"小店依靠本地顧客生意生存。"},{"en":"If many sellers want the public’s custom, advertising may become aggressive.","zh":"如果許多賣家想爭奪大眾生意，廣告可能變得進取。"},{"en":"The phrase refers to customers’ spending.","zh":"這個短語指顧客消費。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":11},{"front":"outrageous advertisements","meaning":"誇張荒謬的廣告","examples":[{"en":"Patent medicines were promoted with outrageous advertisements.","zh":"專利成藥以誇張荒謬的廣告推廣。"},{"en":"Outrageous advertisements are adverts that make shocking, extreme or unbelievable claims.","zh":"outrageous advertisements 是作出驚人、極端或難以置信聲稱的廣告。"},{"en":"An advert claiming one pill can cure every illness would be outrageous.","zh":"聲稱一粒藥可治百病的廣告會很荒謬。"},{"en":"Outrageous advertisements can mislead vulnerable consumers.","zh":"誇張荒謬的廣告可以誤導弱勢消費者。"},{"en":"The phrase criticises advertising that goes beyond reasonable truth.","zh":"這個短語批評超出合理真相的廣告。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":11},{"front":"hollow rubber ball","meaning":"空心橡膠球","examples":[{"en":"The carbolic smoke ball was a hollow rubber ball.","zh":"石炭酸煙球是一個空心橡膠球。"},{"en":"A hollow rubber ball is a rubber ball with empty space inside.","zh":"hollow rubber ball 是內部有空間的橡膠球。"},{"en":"A child’s squeeze toy may be a hollow rubber ball that changes shape when pressed.","zh":"孩子的擠壓玩具可能是按壓時會變形的空心橡膠球。"},{"en":"Because the smoke ball was hollow, it could hold powder inside.","zh":"因為煙球是空心的，它可以在內部盛載粉末。"},{"en":"The phrase describes the object’s material and structure.","zh":"這個短語描述物件的材料和結構。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":11},{"front":"five centimetres across","meaning":"直徑五厘米","examples":[{"en":"The smoke ball was five centimetres across.","zh":"煙球直徑五厘米。"},{"en":"Five centimetres across means its width or diameter was five centimetres.","zh":"five centimetres across 指其寬度或直徑為五厘米。"},{"en":"A small orange may be about five centimetres across.","zh":"小橙可能約直徑五厘米。"},{"en":"Giving the size helps readers imagine the object more clearly.","zh":"給出尺寸幫助讀者更清楚想像物件。"},{"en":"The phrase describes measurement from one side to the other.","zh":"這個短語描述從一邊到另一邊的量度。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":11},{"front":"nozzle covered by gauze","meaning":"由紗布覆蓋的噴嘴","examples":[{"en":"The ball had a nozzle covered by gauze.","zh":"這個球有一個由紗布覆蓋的噴嘴。"},{"en":"A nozzle covered by gauze is a small opening protected or filtered by thin cloth.","zh":"nozzle covered by gauze 是由薄布保護或過濾的小開口。"},{"en":"A spray bottle has a nozzle where liquid comes out.","zh":"噴霧瓶有讓液體噴出的噴嘴。"},{"en":"Gauze over a nozzle may stop larger particles from escaping too quickly.","zh":"噴嘴上的紗布可能阻止較大顆粒太快漏出。"},{"en":"The phrase describes part of a device and how it is covered.","zh":"這個短語描述裝置的一部分以及它如何被覆蓋。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":11},{"front":"be treated with","meaning":"經……處理","examples":[{"en":"The powder inside was treated with carbolic acid.","zh":"內部粉末經石炭酸處理。"},{"en":"To be treated with a substance means to have that substance applied to it.","zh":"be treated with 某物，指被塗上或加入該物處理。"},{"en":"Wood may be treated with chemicals to stop insects damaging it.","zh":"木材可能經化學物處理，以防昆蟲破壞。"},{"en":"Treating a material can change its smell, safety or function.","zh":"處理材料可以改變其氣味、安全性或功能。"},{"en":"The phrase describes applying a substance for a purpose.","zh":"這個短語描述為某目的加入或使用某物。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":11},{"front":"carbolic acid","meaning":"石炭酸","examples":[{"en":"The powder was treated with carbolic acid, or phenol.","zh":"該粉末經石炭酸，即酚，處理。"},{"en":"Carbolic acid is another name for phenol, a chemical historically used as a disinfectant.","zh":"carbolic acid 是 phenol 的另一名稱，是歷史上曾用作消毒劑的化學物。"},{"en":"A hospital once used strong disinfectants to clean surfaces and reduce infection risk.","zh":"醫院曾使用強力消毒劑清潔表面並降低感染風險。"},{"en":"Chemical names in old advertisements can make products sound scientific.","zh":"舊廣告中的化學名稱可以令產品聽起來科學。"},{"en":"The phrase names the chemical linked to the smoke ball.","zh":"這個短語指出與煙球相關的化學物。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":12},{"front":"phenol","meaning":"酚","examples":[{"en":"Carbolic acid is also known as phenol.","zh":"石炭酸也稱為酚。"},{"en":"Phenol is a chemical compound that has been used in disinfectants and industry.","zh":"phenol 是一種曾用於消毒劑和工業中的化合物。"},{"en":"A chemistry student may learn that one substance can have both a common name and a scientific name.","zh":"化學學生可能學到一種物質可以有通俗名稱和科學名稱。"},{"en":"Scientific terms can make a product sound more trustworthy to buyers.","zh":"科學術語可以令產品對買家聽起來更可信。"},{"en":"The word identifies the chemical also called carbolic acid.","zh":"這個字指出也稱為石炭酸的化學物。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":12},{"front":"clutch it close to","meaning":"把它緊握靠近……","examples":[{"en":"The user had to clutch the smoke ball close to the nose.","zh":"使用者必須把煙球緊握靠近鼻子。"},{"en":"To clutch something close to something means to hold it tightly near that place.","zh":"clutch something close to 某處，指把某物緊緊握住並靠近該處。"},{"en":"A child may clutch a toy close to her chest when she feels nervous.","zh":"孩子緊張時可能把玩具緊抱在胸前。"},{"en":"Holding the smoke ball close to the nose allowed the user to inhale the powder.","zh":"把煙球靠近鼻子，讓使用者能吸入粉末。"},{"en":"The phrase describes a tight hand action and position.","zh":"這個短語描述緊握動作和位置。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":12},{"front":"squeeze gently","meaning":"輕輕擠壓","examples":[{"en":"The user squeezed the smoke ball gently.","zh":"使用者輕輕擠壓煙球。"},{"en":"To squeeze gently means to press something softly with the hand.","zh":"squeeze gently 指用手輕柔地按壓某物。"},{"en":"A parent may squeeze a baby’s toy gently to make it squeak.","zh":"家長可能輕輕擠壓嬰兒玩具，令它發聲。"},{"en":"Squeezing too hard could release too much powder or damage the object.","zh":"擠得太大力可能釋放太多粉末或損壞物件。"},{"en":"The phrase describes a light controlled pressure.","zh":"這個短語描述輕而受控的壓力。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":12},{"front":"inhale deeply","meaning":"深深吸入","examples":[{"en":"The user inhaled deeply from the emerging cloud of powder.","zh":"使用者從冒出的粉末雲中深深吸入。"},{"en":"To inhale deeply means to breathe in a large amount of air or substance.","zh":"inhale deeply 指大量吸入空氣或物質。"},{"en":"A patient may inhale deeply before a doctor listens to the lungs.","zh":"醫生聽肺部前，病人可能要深深吸氣。"},{"en":"Deep inhalation brings material further into the breathing passages.","zh":"深吸會把物質帶入更深的呼吸道。"},{"en":"The phrase describes a strong inward breath.","zh":"這個短語描述強力向內吸氣。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":12},{"front":"emerging cloud","meaning":"冒出的煙霧","examples":[{"en":"The user inhaled from the emerging cloud of powder.","zh":"使用者從冒出的粉末煙霧中吸入。"},{"en":"An emerging cloud is a visible mass of dust, smoke or powder beginning to appear.","zh":"emerging cloud 是開始出現的可見塵、煙或粉末團。"},{"en":"A cloud of flour may emerge when a baker opens a full bag too quickly.","zh":"麵包師太快打開滿滿一袋麵粉時，可能冒出一團麵粉雲。"},{"en":"A powder cloud can irritate the nose or throat if breathed in.","zh":"如果吸入粉末雲，可能刺激鼻子或喉嚨。"},{"en":"The phrase describes something appearing and spreading in the air.","zh":"這個短語描述某物在空氣中出現並擴散。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":12},{"front":"pungent powder","meaning":"刺鼻粉末","examples":[{"en":"The smoke ball released pungent powder.","zh":"煙球釋放刺鼻粉末。"},{"en":"Pungent powder is powder with a strong, sharp smell or taste.","zh":"pungent powder 是有強烈、刺激氣味或味道的粉末。"},{"en":"Ground pepper can feel like pungent powder if it reaches the nose.","zh":"如果胡椒粉進入鼻子，可能感覺像刺鼻粉末。"},{"en":"A pungent substance may make people cough, sneeze or step back.","zh":"刺激性物質可能令人咳嗽、打噴嚏或後退。"},{"en":"The phrase describes a strong sensory effect.","zh":"這個短語描述強烈感官效果。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":12},{"front":"disinfect the mucous membranes","meaning":"消毒黏膜","examples":[{"en":"The company claimed the powder would disinfect the mucous membranes.","zh":"公司聲稱粉末會消毒黏膜。"},{"en":"To disinfect the mucous membranes means to kill germs on the moist inner surfaces of the nose or mouth.","zh":"disinfect the mucous membranes 指殺死鼻或口腔濕潤內表面的病菌。"},{"en":"A mouthwash may claim to disinfect parts of the mouth, though evidence matters.","zh":"漱口水可能聲稱能消毒口腔部分位置，但證據很重要。"},{"en":"Claims about disinfecting the body should be treated carefully because misuse can harm people.","zh":"關於消毒身體的聲稱應小心看待，因為誤用可以傷害人。"},{"en":"The phrase describes a claimed medical action.","zh":"這個短語描述一種聲稱的醫療作用。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":12},{"front":"mucous membranes","meaning":"黏膜","examples":[{"en":"The product supposedly disinfected the mucous membranes.","zh":"該產品據稱可消毒黏膜。"},{"en":"Mucous membranes are moist tissues lining parts of the body such as the nose and mouth.","zh":"mucous membranes 是覆蓋鼻子和口腔等身體部位的濕潤組織。"},{"en":"The nose has mucous membranes that can become irritated by smoke or dust.","zh":"鼻子有黏膜，可能受煙霧或灰塵刺激。"},{"en":"These membranes help protect the body but can also be sensitive.","zh":"這些黏膜幫助保護身體，但也可能很敏感。"},{"en":"The phrase names a biological surface inside the body.","zh":"這個短語指出身體內部的生物表面。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":12},{"front":"be related to","meaning":"與……有關","examples":[{"en":"The company claimed it could cure conditions related to taking cold.","zh":"公司聲稱它可以治癒與着涼有關的疾病。"},{"en":"To be related to something means to be connected with it in cause, topic or effect.","zh":"be related to 某事，指在原因、題目或影響上有連繫。"},{"en":"Poor sleep may be related to stress, late phone use or illness.","zh":"睡眠差可能與壓力、深夜用手機或疾病有關。"},{"en":"If two problems are related, solving one may help the other.","zh":"如果兩個問題有關，解決其中一個可能幫助另一個。"},{"en":"The phrase shows connection, not always direct cause.","zh":"這個短語顯示關聯，不一定是直接原因。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":12},{"front":"taking cold","meaning":"着涼","examples":[{"en":"The product claimed to cure diseases caused by taking cold.","zh":"該產品聲稱能治癒由着涼引起的疾病。"},{"en":"Taking cold is an old expression meaning becoming ill after exposure to cold air or weather.","zh":"taking cold 是舊式說法，意思是接觸冷空氣或天氣後生病。"},{"en":"A parent may worry that a child will take cold after walking home in wet clothes.","zh":"孩子穿着濕衣服走回家後，家長可能擔心他着涼。"},{"en":"The expression reflects older ideas about how illness begins.","zh":"這個說法反映較舊的疾病起因觀念。"},{"en":"The phrase is old-fashioned; people now more often say “catch a cold.”","zh":"這個短語較舊式；現代人更常說 “catch a cold”。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":13},{"front":"sales were steady","meaning":"銷量穩定","examples":[{"en":"Sales were steady at 300 smoke balls a month.","zh":"煙球銷量穩定在每月300個。"},{"en":"Sales were steady means the number sold stayed fairly stable over time.","zh":"sales were steady 指銷售數量隨時間保持相當穩定。"},{"en":"A café’s sales may be steady if the same customers visit every morning.","zh":"如果同一批顧客每天早上光顧，咖啡店銷量可能穩定。"},{"en":"Steady sales help a business plan stock and staffing more easily.","zh":"穩定銷量幫助企業更容易計劃存貨和人手。"},{"en":"The phrase describes stability, not rapid growth.","zh":"這個短語描述穩定，而不是快速增長。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":13},{"front":"skyrocket","meaning":"急升","examples":[{"en":"Sales skyrocketed to 1,500 in January 1891.","zh":"銷量在1891年1月急升至1,500個。"},{"en":"To skyrocket means to rise very quickly and sharply.","zh":"skyrocket 指非常快速而急劇上升。"},{"en":"Umbrella sales may skyrocket when heavy rain is forecast for a whole week.","zh":"如果預報整星期大雨，雨傘銷量可能急升。"},{"en":"Prices can skyrocket when demand rises suddenly and supply is limited.","zh":"當需求突然上升而供應有限，價格可以急升。"},{"en":"The word describes dramatic upward movement.","zh":"這個字描述劇烈向上移動。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":13},{"front":"exploit the public’s panic","meaning":"利用大眾恐慌","examples":[{"en":"The company was eager to exploit the public’s panic.","zh":"公司急於利用大眾恐慌。"},{"en":"To exploit the public’s panic means to take unfair advantage of people’s fear for gain.","zh":"exploit the public’s panic 指不公平地利用人們的恐懼來獲利。"},{"en":"A seller may exploit panic by raising mask prices during an outbreak.","zh":"賣家可能在疫情期間提高口罩價格，利用恐慌牟利。"},{"en":"When people are frightened, they may buy products without checking evidence.","zh":"當人們害怕時，可能不查證據就購買產品。"},{"en":"The phrase criticises profit-making from public fear.","zh":"這個短語批評從公眾恐懼中牟利。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":13},{"front":"mounting panic","meaning":"不斷加劇的恐慌","examples":[{"en":"The company exploited the public’s mounting panic.","zh":"公司利用公眾不斷加劇的恐慌。"},{"en":"Mounting panic is fear that is increasing over time.","zh":"mounting panic 是隨時間增加的恐懼。"},{"en":"Mounting panic may spread in a school if no one explains why several students are ill.","zh":"如果沒有人解釋為何幾名學生生病，學校中可能出現不斷加劇的恐慌。"},{"en":"As panic grows, people may make faster and less careful decisions.","zh":"隨着恐慌增加，人們可能作出更快但更不謹慎的決定。"},{"en":"The phrase describes fear building up.","zh":"這個短語描述恐懼累積。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":13},{"front":"extravagant claims","meaning":"誇張聲稱","examples":[{"en":"The company made increasingly extravagant claims.","zh":"公司作出越來越誇張的聲稱。"},{"en":"Extravagant claims are extreme or exaggerated statements that are difficult to believe.","zh":"extravagant claims 是極端或誇大的陳述，令人難以相信。"},{"en":"A tutor makes extravagant claims if he promises perfect exam results in one lesson.","zh":"如果導師承諾一堂課就能考滿分，就是作出誇張聲稱。"},{"en":"Such claims can attract attention but may mislead people.","zh":"這類聲稱可以吸引注意，但可能誤導人。"},{"en":"The phrase criticises claims that go beyond reasonable evidence.","zh":"這個短語批評超出合理證據的聲稱。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":13},{"front":"catch the eye of","meaning":"引起……注意","examples":[{"en":"The advert caught the eye of Louisa Carlill.","zh":"該廣告引起 Louisa Carlill 的注意。"},{"en":"To catch the eye of someone means to attract that person’s attention.","zh":"catch the eye of 某人，指吸引該人的注意。"},{"en":"A bright poster can catch the eye of students walking through a hallway.","zh":"鮮明海報可以引起走廊中學生的注意。"},{"en":"Advertisers use bold words and rewards to catch customers’ eyes.","zh":"廣告商使用醒目字眼和獎賞來引起顧客注意。"},{"en":"The phrase describes sudden attention.","zh":"這個短語描述突然注意到。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":13},{"front":"declare","meaning":"宣稱","examples":[{"en":"The advert declared that the smoke ball would cure many illnesses.","zh":"廣告宣稱煙球會治癒多種疾病。"},{"en":"To declare something means to state it clearly and publicly.","zh":"declare 某事，指清楚而公開地陳述它。"},{"en":"A school may declare that classes are cancelled during a typhoon.","zh":"學校可能宣布颱風期間停課。"},{"en":"A strong declaration can influence people if they trust the speaker.","zh":"如果人們信任說話者，強烈宣稱可以影響他們。"},{"en":"The word suggests an open and confident statement.","zh":"這個字暗示公開而有信心的陳述。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":13},{"front":"positively cure","meaning":"肯定治癒","examples":[{"en":"The advert claimed the smoke ball would positively cure influenza.","zh":"廣告聲稱煙球會肯定治癒流感。"},{"en":"Positively cure means definitely cure, with strong confidence in the result.","zh":"positively cure 指肯定治癒，對結果帶強烈信心。"},{"en":"A product claiming to positively cure all headaches should be viewed with caution.","zh":"聲稱能肯定治癒所有頭痛的產品應被小心看待。"},{"en":"Strong cure claims can mislead people if they are not supported by evidence.","zh":"如果沒有證據支持，強烈治癒聲稱可以誤導人。"},{"en":"The phrase sounds forceful and promotional.","zh":"這個短語聽起來有力且帶推銷性。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":13},{"front":"bronchitis","meaning":"支氣管炎","examples":[{"en":"The advert claimed the smoke ball could cure bronchitis.","zh":"廣告聲稱煙球可以治癒支氣管炎。"},{"en":"Bronchitis is inflammation of the airways that can cause coughing and breathing discomfort.","zh":"bronchitis 是氣道發炎，可造成咳嗽和呼吸不適。"},{"en":"A patient with bronchitis may need rest, fluids and medical advice.","zh":"支氣管炎病人可能需要休息、補充水分和醫療建議。"},{"en":"Claims to cure bronchitis should be checked against reliable medical evidence.","zh":"聲稱能治癒支氣管炎的說法應按可靠醫學證據查核。"},{"en":"The word names a respiratory condition.","zh":"這個字指出一種呼吸系統疾病。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":13},{"front":"hoarseness","meaning":"聲音沙啞","examples":[{"en":"The advert claimed the smoke ball could cure hoarseness.","zh":"廣告聲稱煙球可以治癒聲音沙啞。"},{"en":"Hoarseness is a rough, weak or changed voice.","zh":"hoarseness 是聲音粗啞、微弱或改變。"},{"en":"A teacher may develop hoarseness after speaking loudly all day.","zh":"老師整天大聲說話後，可能聲音沙啞。"},{"en":"Hoarseness can result from infection, voice strain or irritation.","zh":"聲音沙啞可以由感染、用聲過度或刺激造成。"},{"en":"The word describes a voice problem.","zh":"這個字描述聲音問題。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":14},{"front":"croup","meaning":"哮吼","examples":[{"en":"The advert listed croup among the diseases it could cure.","zh":"廣告把哮吼列為它可以治癒的疾病之一。"},{"en":"Croup is a childhood breathing illness often causing a harsh barking cough.","zh":"croup 是兒童呼吸疾病，常造成粗厲如犬吠的咳嗽。"},{"en":"Parents may worry when a young child develops a croup-like cough at night.","zh":"當幼兒晚上出現類似哮吼的咳嗽，家長可能擔心。"},{"en":"Because breathing can be affected, medical advice is important.","zh":"因為呼吸可能受影響，醫療建議很重要。"},{"en":"The word names a specific respiratory illness, especially in children.","zh":"這個字指出一種特定呼吸疾病，尤其見於兒童。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":14},{"front":"whooping cough","meaning":"百日咳","examples":[{"en":"The advert claimed the smoke ball could cure whooping cough.","zh":"廣告聲稱煙球可以治癒百日咳。"},{"en":"Whooping cough is a contagious disease that causes severe coughing fits.","zh":"whooping cough 是會造成嚴重咳嗽發作的傳染病。"},{"en":"A child with whooping cough may cough so hard that breathing becomes difficult.","zh":"患百日咳的孩子可能咳得很厲害，以致呼吸困難。"},{"en":"Preventing serious coughing diseases usually requires reliable medical care, not advertising claims.","zh":"預防嚴重咳嗽疾病通常需要可靠醫療，而不是廣告聲稱。"},{"en":"The phrase names a serious respiratory infection.","zh":"這個短語指出一種嚴重呼吸道感染。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":14},{"front":"find something compelling","meaning":"覺得……很有說服力","examples":[{"en":"Mrs Carlill found the reward promise compelling.","zh":"Carlill 夫人覺得賞金承諾很有說服力。"},{"en":"To find something compelling means to think it is very convincing or hard to ignore.","zh":"find something compelling 指覺得某事非常令人信服或難以忽視。"},{"en":"A student may find a scholarship offer compelling if it covers all tuition fees.","zh":"如果獎學金支付全部學費，學生可能覺得該提議很有吸引力。"},{"en":"Strong evidence or a valuable reward can make a claim feel compelling.","zh":"強有力證據或有價值獎賞可以令主張感覺很有說服力。"},{"en":"The phrase describes powerful persuasion.","zh":"這個短語描述強大說服力。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":14},{"front":"a £100 reward","meaning":"一百英鎊賞金","examples":[{"en":"The company promised a £100 reward to customers who got sick.","zh":"公司承諾向生病的顧客支付一百英鎊賞金。"},{"en":"A £100 reward is a promised payment of one hundred pounds for meeting a condition.","zh":"a £100 reward 是在符合某條件時承諾支付的一百英鎊。"},{"en":"A shop may offer a reward to anyone who returns a lost wallet.","zh":"商店可能向歸還遺失銀包的人提供賞金。"},{"en":"A reward can make an advertisement feel more serious to customers.","zh":"賞金可以令廣告對顧客而言感覺更認真。"},{"en":"The phrase refers to money offered as an incentive or promise.","zh":"這個短語指作為誘因或承諾提供的金錢。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":14},{"front":"be paid by","meaning":"由……支付","examples":[{"en":"A reward would be paid by the Carbolic Smoke Ball Company.","zh":"賞金將由 Carbolic Smoke Ball Company 支付。"},{"en":"To be paid by someone means that person or organisation provides the money.","zh":"be paid by 某人或機構，指由該人或機構提供金錢。"},{"en":"A refund may be paid by the shop if the product is faulty.","zh":"如果產品有問題，退款可能由商店支付。"},{"en":"Knowing who pays matters when a promise becomes a legal dispute.","zh":"當承諾變成法律爭議，知道由誰支付很重要。"},{"en":"The phrase identifies the payer.","zh":"這個短語指出付款者。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":14},{"front":"contract influenza","meaning":"感染流感","examples":[{"en":"The advert promised money to anyone who contracted influenza.","zh":"廣告承諾向任何感染流感的人支付金錢。"},{"en":"To contract influenza means to catch or become infected with flu.","zh":"contract influenza 指染上或感染流感。"},{"en":"A traveller may contract influenza after sitting near a sick passenger.","zh":"旅客坐在生病乘客附近後，可能感染流感。"},{"en":"If someone contracts influenza despite using a product, a prevention claim may be questioned.","zh":"如果某人使用產品後仍感染流感，預防聲稱可能被質疑。"},{"en":"The phrase is more formal than “catch flu.”","zh":"這個短語比 “catch flu” 更正式。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":14},{"front":"increasing epidemic","meaning":"日益嚴重的疫情","examples":[{"en":"The advert referred to the increasing epidemic of influenza.","zh":"廣告提到日益嚴重的流感疫情。"},{"en":"An increasing epidemic is an outbreak that is growing in size or seriousness.","zh":"increasing epidemic 是規模或嚴重程度正在增加的疫情。"},{"en":"A town may worry about an increasing epidemic when more schools report illness.","zh":"當更多學校報告疾病，城鎮可能擔心日益嚴重的疫情。"},{"en":"As an epidemic increases, people may become more willing to buy preventive products.","zh":"隨着疫情加劇，人們可能更願意購買預防產品。"},{"en":"The phrase describes a worsening outbreak.","zh":"這個短語描述正在惡化的疫情。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":14},{"front":"according to","meaning":"根據","examples":[{"en":"The smoke ball had to be used according to the printed directions.","zh":"煙球必須根據印刷說明使用。"},{"en":"According to means following what a rule, instruction or source says.","zh":"according to 指按照規則、指示或來源所說。"},{"en":"A student should answer according to the question instructions, not personal preference.","zh":"學生應根據題目指示回答，而不是按個人偏好。"},{"en":"If a product is not used according to directions, the seller may deny responsibility.","zh":"如果產品沒有根據說明使用，賣方可能否認責任。"},{"en":"The phrase links action to a stated rule.","zh":"這個短語把行動與明文規則連繫起來。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":14},{"front":"printed directions","meaning":"印刷說明","examples":[{"en":"Each ball came with printed directions.","zh":"每個煙球都附有印刷說明。"},{"en":"Printed directions are written instructions supplied on paper or packaging.","zh":"printed directions 是印在紙上或包裝上的書面指示。"},{"en":"A medicine bottle usually comes with printed directions about dosage.","zh":"藥瓶通常附有關於劑量的印刷說明。"},{"en":"Clear printed directions help customers use a product correctly.","zh":"清楚印刷說明幫助顧客正確使用產品。"},{"en":"The phrase refers to instructions that can be read and followed.","zh":"這個短語指可以閱讀和遵從的指示。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":14},{"front":"be supplied with","meaning":"隨……附上","examples":[{"en":"Directions were supplied with each smoke ball.","zh":"每個煙球都隨附使用說明。"},{"en":"To be supplied with something means to receive it together with the main item.","zh":"be supplied with 某物，指與主要物品一起收到該物。"},{"en":"A new phone may be supplied with a charging cable and user guide.","zh":"新手機可能隨附充電線和用戶指南。"},{"en":"Supplying instructions helps a seller show how the product should be used.","zh":"附上說明有助賣方顯示產品應如何使用。"},{"en":"The phrase describes something being provided.","zh":"這個短語描述某物被提供。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":15},{"front":"be deposited with","meaning":"存放於","examples":[{"en":"£1,000 was deposited with the Alliance Bank.","zh":"1,000英鎊存放於 Alliance Bank。"},{"en":"To be deposited with a bank means to be placed in that bank for safekeeping.","zh":"be deposited with 銀行，指把錢存放在該銀行保管。"},{"en":"A tenant’s deposit may be placed with an authorised scheme for protection.","zh":"租客按金可能存放於認可計劃中以受保護。"},{"en":"Depositing money can show that a promise is backed by real funds.","zh":"存放金錢可以顯示承諾有真實資金支持。"},{"en":"The phrase describes money being formally placed with an institution.","zh":"這個短語描述金錢被正式存放於機構。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":15},{"front":"show one’s sincerity","meaning":"顯示某人的誠意","examples":[{"en":"The deposit was meant to show the company’s sincerity.","zh":"該存款旨在顯示公司的誠意。"},{"en":"To show one’s sincerity means to prove that one is serious and honest.","zh":"show one’s sincerity 指證明某人認真而誠實。"},{"en":"A buyer may pay a small deposit to show sincerity before purchasing a flat.","zh":"買家在買樓前可能支付小額訂金以顯示誠意。"},{"en":"Actions often show sincerity better than words alone.","zh":"行動通常比單靠說話更能顯示誠意。"},{"en":"The phrase describes proof of genuine intention.","zh":"這個短語描述真誠意圖的證明。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":15},{"front":"in the matter","meaning":"在這件事上","examples":[{"en":"The company said the deposit showed its sincerity in the matter.","zh":"公司說該存款顯示它在這件事上的誠意。"},{"en":"In the matter means regarding the issue being discussed.","zh":"in the matter 指關於正在討論的事情。"},{"en":"A school may say it will be fair in the matter of student complaints.","zh":"學校可能說會在學生投訴這件事上保持公平。"},{"en":"The phrase links a statement to a particular issue.","zh":"這個短語把陳述連到特定議題。"},{"en":"It is formal and often appears in legal or official contexts.","zh":"它較正式，常見於法律或官方語境。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":15},{"front":"hurry off to","meaning":"匆忙去","examples":[{"en":"Mrs Carlill hurried off to buy a smoke ball.","zh":"Carlill 夫人匆忙去買煙球。"},{"en":"To hurry off to do something means to go quickly in order to do it.","zh":"hurry off to do something 指快速前往以做某事。"},{"en":"A student may hurry off to the library when she realises the book is almost due.","zh":"當學生發現書快到期，可能匆忙去圖書館。"},{"en":"People hurry off when they feel a chance may disappear.","zh":"當人們覺得機會可能消失，就會匆忙前往。"},{"en":"The phrase describes quick movement with purpose.","zh":"這個短語描述有目的的快速移動。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":15},{"front":"diligently dose oneself","meaning":"勤勉地按劑量使用","examples":[{"en":"She diligently dosed herself thrice daily.","zh":"她每日三次勤勉地按劑量使用。"},{"en":"To diligently dose oneself means to take or use medicine carefully and regularly as instructed.","zh":"diligently dose oneself 指按指示仔細而定期服用或使用藥物。"},{"en":"A patient may diligently dose herself with eye drops after surgery.","zh":"病人在手術後可能勤勉地按劑量使用眼藥水。"},{"en":"Careful use matters when a claim depends on following directions exactly.","zh":"當聲稱取決於完全遵從說明，仔細使用就很重要。"},{"en":"The phrase sounds formal and slightly old-fashioned.","zh":"這個短語聽起來正式且略舊式。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":15},{"front":"solicitor","meaning":"律師","examples":[{"en":"Mr Carlill happened to be a solicitor.","zh":"Carlill 先生碰巧是一名律師。"},{"en":"A solicitor is a lawyer who gives legal advice and prepares legal documents.","zh":"solicitor 是提供法律意見並準備法律文件的律師。"},{"en":"A tenant may ask a solicitor to check a rental contract before signing.","zh":"租客可能請律師在簽署前檢查租約。"},{"en":"Having a solicitor in the family could help someone understand legal rights.","zh":"家中有律師可以幫助人理解法律權利。"},{"en":"The word refers to a legal professional.","zh":"這個字指法律專業人士。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":15},{"front":"on the strength of","meaning":"基於；憑藉","examples":[{"en":"Mrs Carlill bought a smoke ball on the strength of the advert.","zh":"Carlill 夫人基於該廣告購買煙球。"},{"en":"On the strength of something means because of the trust, evidence or promise it provides.","zh":"on the strength of 某事，指因為它提供的信任、證據或承諾。"},{"en":"A student may join a course on the strength of a friend’s strong recommendation.","zh":"學生可能基於朋友強烈推薦而參加課程。"},{"en":"If people act on the strength of an advert, the advert has influenced their decision.","zh":"如果人們基於廣告而行動，該廣告已影響他們的決定。"},{"en":"The phrase shows the basis for an action.","zh":"這個短語顯示行動的根據。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":15},{"front":"to the letter","meaning":"一絲不苟地","examples":[{"en":"She followed the instructions to the letter.","zh":"她一絲不苟地遵從指示。"},{"en":"To follow instructions to the letter means to obey them exactly, without changing anything.","zh":"follow instructions to the letter 指完全照做，不作任何改動。"},{"en":"A student follows exam rules to the letter by writing only the allowed number of words.","zh":"學生只寫允許字數，就是一絲不苟地遵守考試規則。"},{"en":"Exact obedience can matter when small changes affect the result.","zh":"當小改動會影響結果，完全遵從就很重要。"},{"en":"The phrase stresses complete accuracy in following instructions.","zh":"這個短語強調跟隨指示的完全準確性。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":15},{"front":"as someone could confirm","meaning":"正如某人可證實","examples":[{"en":"Their doctor could confirm that she had flu.","zh":"他們的醫生可以證實她患上流感。"},{"en":"As someone could confirm means another person can verify that the statement is true.","zh":"as someone could confirm 指另一人可以證實該陳述為真。"},{"en":"The teacher could confirm that the student submitted the essay on time.","zh":"老師可以證實學生準時提交文章。"},{"en":"Confirmation from a trusted person can strengthen a claim.","zh":"來自可信人士的證實可以加強主張。"},{"en":"The phrase introduces supporting evidence from another person.","zh":"這個短語引出另一人提供的支持證據。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":15},{"front":"no reply","meaning":"沒有回覆","examples":[{"en":"There was no reply from the company.","zh":"公司沒有回覆。"},{"en":"No reply means no answer or response was received.","zh":"no reply 指沒有收到答案或回應。"},{"en":"A customer may become frustrated if there is no reply after several emails.","zh":"如果發出幾封電郵後仍沒有回覆，顧客可能感到沮喪。"},{"en":"Failure to reply can make a dispute more serious.","zh":"不回覆可以令爭議變得更嚴重。"},{"en":"The phrase describes silence after a request or complaint.","zh":"這個短語描述請求或投訴後的沉默。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":16},{"front":"not a sum to be sneezed at","meaning":"不是一筆可以輕視的錢","examples":[{"en":"£100 was not a sum to be sneezed at.","zh":"100英鎊不是一筆可以輕視的錢。"},{"en":"Not a sum to be sneezed at means the amount of money is significant and should be taken seriously.","zh":"not a sum to be sneezed at 指金額相當可觀，應認真看待。"},{"en":"A scholarship of £1,000 is not a sum to be sneezed at for a student.","zh":"對學生來說，1,000英鎊獎學金不是一筆可以輕視的錢。"},{"en":"When the amount is meaningful, people may be willing to fight for it.","zh":"當金額有意義，人們可能願意爭取。"},{"en":"The phrase is informal and means “not small or unimportant.”","zh":"這個短語較口語，意思是「不小或不重要」。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":16},{"front":"persist","meaning":"堅持下去","examples":[{"en":"Mr Carlill persisted in pursuing the claim.","zh":"Carlill 先生堅持追討申索。"},{"en":"To persist means to continue doing something despite difficulty or delay.","zh":"persist 指即使有困難或延誤仍繼續做某事。"},{"en":"A student who fails once may persist and improve through regular practice.","zh":"失敗一次的學生可能堅持下去，並透過定期練習進步。"},{"en":"Persistence can turn a complaint into a legal case if the person refuses to give up.","zh":"如果當事人拒絕放棄，堅持可以把投訴變成法律案件。"},{"en":"The word suggests steady determination.","zh":"這個字暗示穩定決心。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":16},{"front":"sue","meaning":"起訴","examples":[{"en":"Louisa recovered and sued the company.","zh":"Louisa 康復後起訴該公司。"},{"en":"To sue someone means to take legal action against them in court.","zh":"sue 某人，指在法庭對其採取法律行動。"},{"en":"A customer may sue a company if a dangerous product causes injury.","zh":"如果危險產品造成傷害，顧客可能起訴公司。"},{"en":"People usually sue when they believe a legal right has been broken.","zh":"人們通常在認為法律權利被侵犯時起訴。"},{"en":"The word describes starting a court case.","zh":"這個字描述開始法庭案件。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":16},{"front":"find in someone’s favour","meaning":"判某人勝訴","examples":[{"en":"Mr Justice Hawkins found in Mrs Carlill’s favour.","zh":"Hawkins 法官判 Carlill 夫人勝訴。"},{"en":"To find in someone’s favour means a judge or court decides that person has won the case.","zh":"find in someone’s favour 指法官或法庭裁定該人勝訴。"},{"en":"The court found in the tenant’s favour after the landlord kept the deposit unfairly.","zh":"業主不公平扣起按金後，法庭判租客勝訴。"},{"en":"A favourable judgment can require the other side to pay money or obey a promise.","zh":"有利判決可以要求另一方付款或履行承諾。"},{"en":"The phrase is legal and means the decision supports that person.","zh":"這個短語屬法律用語，意思是裁決支持該人。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":16},{"front":"main defence","meaning":"主要抗辯理由","examples":[{"en":"The company’s main defence was that adverts were mere puffery.","zh":"公司主要抗辯理由是廣告純粹誇大宣傳。"},{"en":"A main defence is the strongest or most important argument used to answer a legal claim.","zh":"main defence 是用來回應法律申索的最強或最重要論點。"},{"en":"In a school complaint, a teacher’s main defence may be that the rule was explained clearly.","zh":"在學校投訴中，老師的主要抗辯理由可能是規則已清楚解釋。"},{"en":"If the main defence fails, the case becomes much harder to win.","zh":"如果主要抗辯失敗，案件就更難勝訴。"},{"en":"The phrase identifies the central argument against a claim.","zh":"這個短語指出反對申索的核心論點。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":16},{"front":"mere puffery","meaning":"純粹誇大宣傳","examples":[{"en":"The company argued that the advert was mere puffery.","zh":"公司辯稱該廣告純粹是誇大宣傳。"},{"en":"Mere puffery is exaggerated advertising language not meant to be taken as a serious promise.","zh":"mere puffery 是不應被視為嚴肅承諾的誇張廣告語言。"},{"en":"A café saying it serves “the best coffee in the universe” may be using puffery.","zh":"咖啡店說自己供應「宇宙最好咖啡」，可能是在誇大宣傳。"},{"en":"The legal problem begins when exaggeration looks like a specific promise.","zh":"當誇張說法看似具體承諾，法律問題就開始。"},{"en":"The phrase describes promotional exaggeration.","zh":"這個短語描述推銷式誇張。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":16},{"front":"extravagant claims","meaning":"誇張聲稱","examples":[{"en":"The company said only an idiot would believe such extravagant claims.","zh":"公司說只有白痴才會相信這類誇張聲稱。"},{"en":"Extravagant claims are claims that sound extreme, excessive or unbelievable.","zh":"extravagant claims 是聽起來極端、過度或難以置信的聲稱。"},{"en":"A beauty product makes extravagant claims if it promises to remove all wrinkles overnight.","zh":"如果美容產品承諾一夜去除所有皺紋，就是作出誇張聲稱。"},{"en":"Sellers may later call claims extravagant to avoid responsibility.","zh":"賣家之後可能稱聲稱只是誇張，以逃避責任。"},{"en":"The phrase suggests the statement goes beyond reasonable belief.","zh":"這個短語暗示陳述超出合理相信範圍。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":16},{"front":"point out","meaning":"指出","examples":[{"en":"Judge Hawkins pointed out that adverts were aimed at the credulous.","zh":"Hawkins 法官指出廣告是針對輕信的人。"},{"en":"To point out something means to draw attention to a fact or detail.","zh":"point out 某事，指把注意力引向某個事實或細節。"},{"en":"A teacher may point out that a student has answered the wrong question.","zh":"老師可能指出學生回答錯了題目。"},{"en":"Pointing out a detail can change how people understand an argument.","zh":"指出一個細節可以改變人們如何理解論點。"},{"en":"The phrase describes making something clear to others.","zh":"這個短語描述向他人說清楚某事。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":16},{"front":"be aimed at","meaning":"針對","examples":[{"en":"Adverts were aimed at the credulous and weak.","zh":"廣告針對輕信而意志薄弱的人。"},{"en":"To be aimed at a group means to be designed to influence or reach that group.","zh":"be aimed at 某群體，指設計來影響或接觸該群體。"},{"en":"A children’s reading app is aimed at young learners and their parents.","zh":"兒童閱讀應用程式針對年幼學習者和他們的父母。"},{"en":"Advertising aimed at vulnerable people can raise ethical concerns.","zh":"針對弱勢人士的廣告可能引起道德問題。"},{"en":"The phrase identifies the target audience.","zh":"這個短語指出目標受眾。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":16},{"front":"wise and thoughtful","meaning":"明智而深思熟慮的人","examples":[{"en":"Adverts were not aimed at the wise and thoughtful.","zh":"廣告並非針對明智而深思熟慮的人。"},{"en":"Wise and thoughtful people think carefully before believing or acting.","zh":"wise and thoughtful people 會在相信或行動前仔細思考。"},{"en":"A wise and thoughtful customer checks reviews before buying an expensive product.","zh":"明智而深思熟慮的顧客在購買昂貴產品前會查看評價。"},{"en":"Careful thinking can protect people from misleading claims.","zh":"仔細思考可以保護人免受誤導性聲稱影響。"},{"en":"The phrase describes people who are cautious and reflective.","zh":"這個短語描述謹慎而會反思的人。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":17},{"front":"the credulous and weak","meaning":"輕信而意志薄弱的人","examples":[{"en":"Adverts were aimed at the credulous and weak.","zh":"廣告針對輕信而意志薄弱的人。"},{"en":"The credulous and weak are people who are easily persuaded or lack strength to resist pressure.","zh":"the credulous and weak 是容易被說服或缺乏抗壓能力的人。"},{"en":"Fraudsters often target the credulous and weak with emotional stories and fake urgency.","zh":"騙徒常用情緒化故事和假緊急情況針對輕信而意志薄弱的人。"},{"en":"Vulnerable consumers may believe claims that careful buyers would question.","zh":"弱勢消費者可能相信謹慎買家會質疑的聲稱。"},{"en":"The phrase describes people especially likely to be misled.","zh":"這個短語描述特別容易被誤導的人。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":17},{"front":"vendor","meaning":"賣方；商販","examples":[{"en":"A vendor who makes a promise may be held to it.","zh":"作出承諾的賣方可能被要求履行它。"},{"en":"A vendor is a person or company that sells goods or services.","zh":"vendor 是出售貨品或服務的人或公司。"},{"en":"A street vendor sells snacks to people passing by.","zh":"街頭小販向路人售賣小食。"},{"en":"If a vendor makes a clear promise, customers may expect it to be honoured.","zh":"如果賣方作出清楚承諾，顧客可能期待它被履行。"},{"en":"The word refers to the seller in a transaction.","zh":"這個字指交易中的賣方。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":17},{"front":"be held to one’s promise","meaning":"被要求履行承諾","examples":[{"en":"A vendor must not be surprised if he is held to his promise.","zh":"如果賣方被要求履行承諾，他不應感到驚訝。"},{"en":"To be held to one’s promise means to be required to do what one promised.","zh":"be held to one’s promise 指被要求做自己承諾過的事。"},{"en":"If a tutor promises a refund for cancelled lessons, parents may hold him to that promise.","zh":"如果導師承諾取消課堂會退款，家長可能要求他履行承諾。"},{"en":"Clear promises can create expectations and legal responsibility.","zh":"清楚承諾可以造成期望和法律責任。"},{"en":"The phrase describes being made accountable for one’s words.","zh":"這個短語描述要為自己的說話負責。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":17},{"front":"appeal","meaning":"上訴","examples":[{"en":"Carbolic appealed against the judgment.","zh":"Carbolic 對判決提出上訴。"},{"en":"To appeal against a judgment means to ask a higher court to review and change it.","zh":"appeal against a judgment 指要求較高級法院覆核並改變判決。"},{"en":"A student may appeal against an exam result if she believes marking was unfair.","zh":"如果學生認為評分不公平，可能對考試結果提出上訴。"},{"en":"An appeal can continue a legal dispute after the first decision.","zh":"上訴可以在第一次裁決後延續法律爭議。"},{"en":"The word describes challenging an official decision.","zh":"這個字描述挑戰官方決定。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":17},{"front":"Lord Justices","meaning":"上訴法院法官","examples":[{"en":"Three Lord Justices considered the case.","zh":"三名上訴法院法官審理該案。"},{"en":"Lord Justices are senior judges in an appeal court in the British legal system.","zh":"Lord Justices 是英國法律制度中上訴法院的高級法官。"},{"en":"A difficult legal question may be heard by several senior judges.","zh":"困難法律問題可能由幾名高級法官審理。"},{"en":"Senior judges review arguments and decide whether an earlier judgment should stand.","zh":"高級法官會審視論點，並決定早前判決是否應維持。"},{"en":"The phrase names high-ranking appeal judges.","zh":"這個短語指出高級上訴法官。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":17},{"front":"lines of defence","meaning":"多項抗辯理由","examples":[{"en":"Carbolic’s lawyers tried several lines of defence.","zh":"Carbolic 的律師嘗試多項抗辯理由。"},{"en":"Lines of defence are different arguments used to protect someone from a claim or accusation.","zh":"lines of defence 是用來保護某人免受申索或指控的不同論點。"},{"en":"A student accused of cheating may offer several lines of defence, such as misunderstanding the rules.","zh":"被指作弊的學生可能提出多項抗辯理由，例如誤解規則。"},{"en":"Lawyers use multiple defences because one argument may fail.","zh":"律師使用多個抗辯理由，因為一個論點可能失敗。"},{"en":"The phrase describes several possible protective arguments.","zh":"這個短語描述幾種可能的防禦論點。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":17},{"front":"come down to","meaning":"歸結為","examples":[{"en":"The case came down to a single matter.","zh":"案件歸結為單一問題。"},{"en":"To come down to something means the main issue finally becomes that one thing.","zh":"come down to 某事，指主要問題最終變成那一件事。"},{"en":"Choosing a school may come down to distance if two schools are equally good.","zh":"如果兩間學校同樣好，選校可能歸結為距離。"},{"en":"Complex disputes often come down to one central question.","zh":"複雜爭議常歸結為一個核心問題。"},{"en":"The phrase simplifies a problem to its core issue.","zh":"這個短語把問題簡化到核心。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":17},{"front":"single matter","meaning":"單一問題","examples":[{"en":"The case came down to a single matter.","zh":"案件歸結為單一問題。"},{"en":"A single matter is one issue or question being focused on.","zh":"single matter 是被集中處理的一個議題或問題。"},{"en":"A meeting may discuss many details but end with a single matter: who will pay.","zh":"會議可能討論許多細節，但最後落在單一問題：誰付款。"},{"en":"Focusing on a single matter can make a dispute easier to decide.","zh":"集中於單一問題可以令爭議較容易裁決。"},{"en":"The phrase points to one central issue.","zh":"這個短語指一個核心議題。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":17},{"front":"remedy","meaning":"療法；藥物","examples":[{"en":"The court did not focus on whether the remedy was useless.","zh":"法庭沒有集中於該療法是否無用。"},{"en":"A remedy is a treatment, medicine or solution intended to fix a problem.","zh":"remedy 是旨在解決問題的治療、藥物或方法。"},{"en":"Ginger tea may be used as a home remedy for a sore throat.","zh":"薑茶可被用作喉嚨痛的家庭療法。"},{"en":"A legal remedy can also mean what a court gives to correct a wrong.","zh":"法律上的 remedy 也可以指法院用來糾正錯誤的補救。"},{"en":"In this context, the word refers mainly to a supposed medical treatment.","zh":"在這個語境中，這個字主要指所謂醫療方法。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":17},{"front":"commit fraud","meaning":"干犯欺詐","examples":[{"en":"The issue was not whether Carbolic had committed fraud.","zh":"問題並不是 Carbolic 是否干犯欺詐。"},{"en":"To commit fraud means to deceive someone illegally for money or advantage.","zh":"commit fraud 指為金錢或利益非法欺騙他人。"},{"en":"A seller commits fraud if he knowingly sells fake medicine as a cure.","zh":"如果賣家明知是假藥卻當成療法出售，就是干犯欺詐。"},{"en":"Fraud can lead to lawsuits, fines or criminal punishment.","zh":"欺詐可以導致訴訟、罰款或刑事處罰。"},{"en":"The phrase describes dishonest and illegal deception.","zh":"這個短語描述不誠實且非法的欺騙。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":18},{"front":"constitute a contract","meaning":"構成合約","examples":[{"en":"The issue was whether the advert constituted a contract.","zh":"問題是該廣告是否構成合約。"},{"en":"To constitute a contract means to legally amount to a binding agreement.","zh":"constitute a contract 指在法律上成為具約束力的協議。"},{"en":"A clear written offer and acceptance may constitute a contract between buyer and seller.","zh":"清楚書面要約和接受可以構成買賣雙方之間的合約。"},{"en":"If an advertisement constitutes a contract, the seller may be legally bound by it.","zh":"如果廣告構成合約，賣方可能在法律上受它約束。"},{"en":"The phrase asks whether something has legal contractual force.","zh":"這個短語問某事是否具有合約法律效力。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":18},{"front":"agreement between two parties","meaning":"雙方協議","examples":[{"en":"A contract normally requires agreement between two parties.","zh":"合約通常需要雙方協議。"},{"en":"Agreement between two parties means both sides accept the same terms.","zh":"agreement between two parties 指雙方接受相同條款。"},{"en":"A landlord and tenant need agreement between two parties before a lease is signed.","zh":"業主和租客在簽租約前需要雙方協議。"},{"en":"Without agreement, one side may not be legally required to do anything.","zh":"沒有協議，一方可能在法律上無須做任何事。"},{"en":"The phrase describes mutual acceptance.","zh":"這個短語描述互相接受。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":18},{"front":"one-sided contract","meaning":"單方合約","examples":[{"en":"The judges decided that a contract could sometimes be one-sided.","zh":"法官裁定合約有時可以是單方的。"},{"en":"A one-sided contract can be a contract where one party makes an offer and the other accepts by performing an act.","zh":"one-sided contract 可以指一方作出要約，而另一方透過行動接受的合約。"},{"en":"A reward notice for returning a lost dog may create a one-sided agreement.","zh":"尋回失狗的賞金告示可能形成單方協議。"},{"en":"The person accepting may not need to promise in advance; action can be enough.","zh":"接受者未必需要事先承諾；行動可以已經足夠。"},{"en":"The phrase links to the idea of a unilateral contract.","zh":"這個短語與單方合約概念相關。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":18},{"front":"specific offer","meaning":"具體要約","examples":[{"en":"The advert made a very specific offer to purchasers.","zh":"該廣告向購買者作出非常具體的要約。"},{"en":"A specific offer is a clear proposal with definite terms.","zh":"specific offer 是有明確條款的清楚提議。"},{"en":"A shop makes a specific offer when it says customers get £20 back if delivery is late.","zh":"如果商店說送貨遲到顧客可取回20英鎊，就是作出具體要約。"},{"en":"Specific offers are easier to enforce because the conditions are clearer.","zh":"具體要約較容易執行，因為條件更清楚。"},{"en":"The phrase contrasts with vague advertising language.","zh":"這個短語與模糊廣告語言形成對比。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":18},{"front":"purchasers","meaning":"購買者","examples":[{"en":"The offer was made to purchasers of the smoke ball.","zh":"該要約是向煙球購買者作出的。"},{"en":"Purchasers are people who buy something.","zh":"purchasers 是購買某物的人。"},{"en":"Purchasers of a phone should receive a receipt and warranty information.","zh":"手機購買者應收到收據和保養資料。"},{"en":"If a promise is made to purchasers, only buyers may be able to claim it.","zh":"如果承諾是向購買者作出的，可能只有買家能申索。"},{"en":"The word is more formal than “buyers.”","zh":"這個字比 “buyers” 更正式。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":18},{"front":"as instructed","meaning":"按指示","examples":[{"en":"Mrs Carlill used the smoke ball as instructed.","zh":"Carlill 夫人按指示使用煙球。"},{"en":"As instructed means in the way the instructions required.","zh":"as instructed 指按照說明要求的方式。"},{"en":"A patient should take medicine as instructed to avoid using the wrong dose.","zh":"病人應按指示服藥，以避免用錯劑量。"},{"en":"Following instructions matters when responsibility depends on correct use.","zh":"當責任取決於正確使用，遵從指示就很重要。"},{"en":"The phrase describes exact obedience to directions.","zh":"這個短語描述完全按方向行事。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":18},{"front":"accept that offer","meaning":"接受該要約","examples":[{"en":"By using the smoke ball, Mrs Carlill had accepted the offer.","zh":"透過使用煙球，Carlill 夫人已接受該要約。"},{"en":"To accept that offer means to agree to the proposed terms, sometimes through action.","zh":"accept that offer 指同意所提出的條款，有時可透過行動完成。"},{"en":"A customer accepts a reward offer by returning the lost item described in the notice.","zh":"顧客按照告示歸還失物，就是接受賞金要約。"},{"en":"Acceptance can create legal responsibility when the offer is clear.","zh":"當要約清楚，接受可以產生法律責任。"},{"en":"The phrase describes agreement to a proposal.","zh":"這個短語描述同意某提議。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":18},{"front":"wriggle out of","meaning":"逃避；擺脫","examples":[{"en":"The company might have wriggled out of the promise without the deposit claim.","zh":"如果沒有存款聲稱，公司可能本可逃避該承諾。"},{"en":"To wriggle out of something means to escape a responsibility in a clever or dishonest way.","zh":"wriggle out of 某事，指以聰明或不誠實方式逃避責任。"},{"en":"A student may try to wriggle out of homework by claiming the instructions were unclear.","zh":"學生可能聲稱指示不清楚，試圖逃避功課。"},{"en":"Clear evidence makes it harder for someone to wriggle out of a promise.","zh":"清楚證據令某人更難逃避承諾。"},{"en":"The phrase suggests avoiding responsibility.","zh":"這個短語暗示逃避責任。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":18},{"front":"give buyers reason to believe","meaning":"令買家有理由相信","examples":[{"en":"The deposit gave buyers reason to believe the company meant what it said.","zh":"該存款令買家有理由相信公司說話算數。"},{"en":"To give buyers reason to believe something means to provide evidence that makes customers trust it.","zh":"give buyers reason to believe 某事，指提供令顧客信任的證據。"},{"en":"A clear refund policy gives buyers reason to believe a shop is serious about service.","zh":"清楚退款政策令買家有理由相信商店重視服務。"},{"en":"Evidence can turn an advertisement from empty words into a credible promise.","zh":"證據可以把廣告從空話變成可信承諾。"},{"en":"The phrase explains why buyers might reasonably trust a claim.","zh":"這個短語解釋為何買家可能合理地相信某聲稱。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":18},{"front":"mean what one says","meaning":"說話算數","examples":[{"en":"The company’s deposit suggested it meant what it said.","zh":"公司的存款暗示它說話算數。"},{"en":"To mean what one says means to be serious and sincere about one’s words.","zh":"mean what one says 指對自己說的話認真而真誠。"},{"en":"A teacher means what she says if she really gives extra help after promising it.","zh":"如果老師承諾後真的提供額外幫助，她就是說話算數。"},{"en":"Actions often prove whether people truly mean what they say.","zh":"行動常能證明人是否真的說話算數。"},{"en":"The phrase contrasts sincere promises with empty words.","zh":"這個短語把真誠承諾與空話作對比。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":19},{"front":"extravagant promises","meaning":"誇張承諾","examples":[{"en":"The company chose to make extravagant promises.","zh":"公司選擇作出誇張承諾。"},{"en":"Extravagant promises are very large or unrealistic promises that may be difficult to keep.","zh":"extravagant promises 是非常大或不切實際、可能難以履行的承諾。"},{"en":"A company makes extravagant promises if it says every customer will become rich in a week.","zh":"如果公司說每位顧客一星期內都會變富，就是作出誇張承諾。"},{"en":"Such promises can attract buyers but may create legal or ethical problems.","zh":"這類承諾可以吸引買家，但可能造成法律或道德問題。"},{"en":"The phrase warns that bold promises can have consequences.","zh":"這個短語提醒人大膽承諾會有後果。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":19},{"front":"be bound by","meaning":"受……約束","examples":[{"en":"The company was bound by its promise.","zh":"公司受其承諾約束。"},{"en":"To be bound by something means to be legally or morally required to follow it.","zh":"be bound by 某事，指在法律上或道德上必須遵守它。"},{"en":"A tenant is bound by a rental contract after signing it.","zh":"租客簽署租約後，就受租約約束。"},{"en":"When a company is bound by a promise, it cannot simply ignore it later.","zh":"當公司受承諾約束，它不能之後簡單忽視。"},{"en":"The phrase describes obligation.","zh":"這個短語描述義務。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":19},{"front":"pronounce","meaning":"宣判；正式說明","examples":[{"en":"Lord Justice Bowen pronounced that extravagant promises could still be binding.","zh":"Bowen 上訴法院法官正式說明，誇張承諾仍可以具約束力。"},{"en":"To pronounce in a legal context means to state or declare a decision formally.","zh":"pronounce 在法律語境中指正式陳述或宣布裁決。"},{"en":"A judge may pronounce that a contract is valid after hearing both sides.","zh":"法官聽取雙方後，可能宣判合約有效。"},{"en":"A formal pronouncement can settle how the law is understood.","zh":"正式宣判可以確定法律如何被理解。"},{"en":"The word suggests an official statement.","zh":"這個字暗示官方陳述。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":19},{"front":"establish the principle of","meaning":"確立……的原則","examples":[{"en":"The case established the principle of the unilateral contract.","zh":"該案確立了單方合約的原則。"},{"en":"To establish the principle of something means to make a legal or general rule accepted.","zh":"establish the principle of 某事，指令某法律或一般規則被接受。"},{"en":"A court case may establish the principle that clear promises can be enforceable.","zh":"一宗法庭案件可能確立清楚承諾可以被執行的原則。"},{"en":"Once a principle is established, later cases may refer to it.","zh":"一旦原則被確立，之後案件可能引用它。"},{"en":"The phrase describes creating an accepted rule.","zh":"這個短語描述創立被接受的規則。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":19},{"front":"unilateral contract","meaning":"單方合約","examples":[{"en":"The case established the principle of the unilateral contract.","zh":"該案確立了單方合約的原則。"},{"en":"A unilateral contract is a contract where one side promises something if another person performs a stated act.","zh":"unilateral contract 是一方承諾若另一人完成指定行動就給予某物的合約。"},{"en":"A reward notice for finding a lost pet can be a unilateral contract.","zh":"尋回失寵物的賞金告示可以是單方合約。"},{"en":"The person accepts the offer by doing the required action, not by signing first.","zh":"該人透過完成所需行動接受要約，而不是先簽署。"},{"en":"The phrase names an important contract-law concept.","zh":"這個短語指出重要合約法概念。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":19},{"front":"be frequently cited","meaning":"經常被引用","examples":[{"en":"The case is frequently cited today.","zh":"該案至今經常被引用。"},{"en":"To be frequently cited means to be often mentioned as authority or evidence.","zh":"be frequently cited 指常被提及作為權威或證據。"},{"en":"A famous study may be frequently cited by students writing research papers.","zh":"著名研究可能經常被寫研究論文的學生引用。"},{"en":"When a case is often cited, it remains important long after the original dispute.","zh":"當案件常被引用，它在原本爭議很久之後仍然重要。"},{"en":"The phrase describes repeated reference.","zh":"這個短語描述反覆引用。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":19},{"front":"do the following statements agree with","meaning":"以下陳述是否與……相符","examples":[{"en":"Students decide whether the statements agree with the information in the passage.","zh":"學生判斷陳述是否與文章中的資訊相符。"},{"en":"Do the following statements agree with asks whether each sentence matches the reading text.","zh":"do the following statements agree with 是問每句陳述是否配合閱讀文本。"},{"en":"In reading tests, students must check the passage carefully before choosing TRUE, FALSE or NOT GIVEN.","zh":"在閱讀測驗中，學生選 TRUE、FALSE 或 NOT GIVEN 前必須仔細查文。"},{"en":"A statement agrees only when the text supports it directly.","zh":"陳述只有在文本直接支持時才相符。"},{"en":"The phrase introduces a common IELTS-style question type.","zh":"這個短語引出常見 IELTS 式題型。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":19},{"front":"information given in","meaning":"……中提供的資料","examples":[{"en":"The answers must match the information given in the reading passage.","zh":"答案必須符合閱讀文章中提供的資料。"},{"en":"Information given in a text means facts or details actually stated there.","zh":"information given in 文本，指其中實際陳述的事實或細節。"},{"en":"Students should use information given in the article, not outside knowledge.","zh":"學生應使用文章中提供的資料，而不是外部知識。"},{"en":"If the text does not give the information, the answer may be NOT GIVEN.","zh":"如果文本沒有提供資料，答案可能是 NOT GIVEN。"},{"en":"The phrase reminds learners to rely on the passage.","zh":"這個短語提醒學習者依靠文章。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":19},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生在答題紙上寫答案。"},{"en":"An answer sheet is the official paper or form where exam answers are recorded.","zh":"answer sheet 是記錄考試答案的正式紙張或表格。"},{"en":"A student may lose marks if the correct answer is written only on the question paper.","zh":"如果正確答案只寫在題目卷上，學生可能失分。"},{"en":"Checking the answer sheet helps avoid missing questions.","zh":"檢查答題紙有助避免漏題。"},{"en":"The phrase refers to the final place for exam answers.","zh":"這個短語指考試答案的最終位置。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":19},{"front":"agree with the information","meaning":"與資料相符","examples":[{"en":"A true statement agrees with the information in the passage.","zh":"正確陳述與文章中的資料相符。"},{"en":"To agree with the information means to match what the text says.","zh":"agree with the information 指與文本所說內容相配。"},{"en":"If a passage says the shop opened in 1990, the statement “It opened in 1990” agrees with it.","zh":"如果文章說商店於1990年開業，「它於1990年開業」這句就與資料相符。"},{"en":"Matching the wording is less important than matching the meaning accurately.","zh":"配合字面措辭不如準確配合意思重要。"},{"en":"The phrase describes textual support.","zh":"這個短語描述文本支持。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":20},{"front":"contradict the information","meaning":"與資料矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與文章中的資料矛盾。"},{"en":"To contradict the information means to say the opposite of what the passage says.","zh":"contradict the information 指說出與文章內容相反的事情。"},{"en":"If the text says the company lost, a statement saying it won contradicts the information.","zh":"如果文本說公司敗訴，而陳述說它勝訴，就是與資料矛盾。"},{"en":"Contradiction is different from absence of information.","zh":"矛盾不同於沒有資料。"},{"en":"The phrase helps students separate FALSE from NOT GIVEN.","zh":"這個短語幫助學生區分 FALSE 和 NOT GIVEN。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":20},{"front":"no information on this","meaning":"沒有這方面的資料","examples":[{"en":"Write NOT GIVEN if there is no information on this.","zh":"如果沒有這方面的資料，就寫 NOT GIVEN。"},{"en":"No information on this means the passage does not tell readers about that point.","zh":"no information on this 指文章沒有告訴讀者該點。"},{"en":"If the passage never mentions the price, a statement about the price may be NOT GIVEN.","zh":"如果文章從未提到價格，關於價格的陳述可能是 NOT GIVEN。"},{"en":"Students should not guess from common sense when the text is silent.","zh":"當文本沒有說明時，學生不應憑常識猜測。"},{"en":"The phrase identifies missing textual evidence.","zh":"這個短語指出缺少文本證據。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":20},{"front":"rather than","meaning":"而不是","examples":[{"en":"The question asks whether cities, rather than rural areas, were badly affected.","zh":"題目問是否城市，而不是鄉村地區，受到嚴重影響。"},{"en":"Rather than means instead of, and it clearly contrasts two ideas.","zh":"rather than 指而不是，並清楚對比兩個想法。"},{"en":"A student should answer the question directly rather than write everything remembered from the passage.","zh":"學生應直接回答問題，而不是寫下從文章記得的一切。"},{"en":"This phrase helps separate the real focus from another possible focus.","zh":"這個短語幫助把真正焦點與另一可能焦點分開。"},{"en":"It is useful when one option is being compared with another.","zh":"當一個選項與另一個比較時，它很有用。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":20},{"front":"be badly affected by","meaning":"受到……嚴重影響","examples":[{"en":"Cities were badly affected by the influenza pandemic.","zh":"城市受到流感大流行嚴重影響。"},{"en":"To be badly affected by something means to suffer serious harm or disruption because of it.","zh":"be badly affected by 某事，指因它遭受嚴重傷害或中斷。"},{"en":"A coastal village may be badly affected by flooding after heavy rain.","zh":"大雨後，沿海村莊可能受到水浸嚴重影響。"},{"en":"Badly affected places often need extra support and time to recover.","zh":"受嚴重影響的地方通常需要額外支援和時間復原。"},{"en":"The phrase describes severe impact.","zh":"這個短語描述嚴重影響。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":20},{"front":"influenza pandemic","meaning":"流感大流行","examples":[{"en":"The reading passage describes an influenza pandemic.","zh":"閱讀文章描述一場流感大流行。"},{"en":"An influenza pandemic is a worldwide or very widespread outbreak of flu.","zh":"influenza pandemic 是全球或非常廣泛的流感爆發。"},{"en":"During an influenza pandemic, schools, workplaces and hospitals may all be affected.","zh":"在流感大流行期間，學校、職場和醫院都可能受影響。"},{"en":"Pandemics require public health responses because many people become ill across regions.","zh":"大流行需要公共衞生應對，因為許多地區都有大量人生病。"},{"en":"The phrase names a large-scale flu outbreak.","zh":"這個短語指出大規模流感爆發。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":20},{"front":"link between","meaning":"……之間的關聯","examples":[{"en":"The question asks about the link between microorganisms and disease.","zh":"題目問微生物與疾病之間的關聯。"},{"en":"A link between two things is a connection or relationship between them.","zh":"link between 兩件事，是它們之間的連繫或關係。"},{"en":"Doctors study the link between sleep and mental health.","zh":"醫生研究睡眠與心理健康之間的關聯。"},{"en":"Finding a link can help explain why a problem happens.","zh":"找到關聯可以幫助解釋問題為何發生。"},{"en":"The phrase describes connection, not always proof of direct cause.","zh":"這個短語描述連繫，不一定證明直接原因。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":20},{"front":"contain harmful ingredients","meaning":"含有有害成分","examples":[{"en":"The question asks whether influenza treatments contained harmful ingredients.","zh":"題目問流感治療是否含有有害成分。"},{"en":"To contain harmful ingredients means to include substances that may damage health.","zh":"contain harmful ingredients 指包含可能損害健康的物質。"},{"en":"A toy paint may contain harmful ingredients if it has unsafe chemicals.","zh":"如果玩具顏料含有不安全化學物，就可能含有有害成分。"},{"en":"Products with harmful ingredients can cause illness instead of solving a problem.","zh":"含有有害成分的產品可以造成疾病，而不是解決問題。"},{"en":"The phrase focuses on dangerous contents inside a product.","zh":"這個短語重點在產品內部的危險成分。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":20},{"front":"complete the diagram","meaning":"完成圖表","examples":[{"en":"Students complete the diagram using words from the passage.","zh":"學生使用文章中的字詞完成圖表。"},{"en":"Complete the diagram means fill in missing labels or words in a picture or chart.","zh":"complete the diagram 指在圖片或圖表中填入缺失標籤或字詞。"},{"en":"In a reading test, students may complete a diagram of a machine by finding terms in the text.","zh":"在閱讀測驗中，學生可能透過在文本中找詞來完成機器圖。"},{"en":"Diagram completion tests whether students can match descriptions with visual parts.","zh":"圖表填空測試學生能否把描述與視覺部分配對。"},{"en":"The phrase is an exam instruction.","zh":"這個短語是考試指示。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":20},{"front":"no more than two words","meaning":"不多於兩個字","examples":[{"en":"Students should choose no more than two words from the passage.","zh":"學生應從文章中選擇不多於兩個字。"},{"en":"No more than two words means the answer can contain one or two words, but not more.","zh":"no more than two words 指答案可以有一個或兩個英文詞，但不能更多。"},{"en":"“Carbolic acid” fits this instruction because it has two words.","zh":"“Carbolic acid” 符合這項指示，因為它有兩個英文詞。"},{"en":"If students write three words, the answer may be wrong even if the idea is correct.","zh":"如果學生寫三個詞，即使意思正確也可能錯。"},{"en":"The phrase gives a strict word limit.","zh":"這個短語給出嚴格字數限制。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":20},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must come from the passage.","zh":"答案必須來自文章。"},{"en":"From the passage means using information or exact wording found in the reading text.","zh":"from the passage 指使用閱讀文本中的資訊或原文措辭。"},{"en":"Students should not invent answers when the instruction says answers come from the passage.","zh":"當指示說答案來自文章，學生不應自創答案。"},{"en":"Copying the correct phrase matters in word-limit questions.","zh":"在字數限制題中，複製正確短語很重要。"},{"en":"The phrase tells candidates where the answer source is.","zh":"這個短語告訴考生答案來源在哪裏。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":21},{"front":"look at the following people","meaning":"查看以下人物","examples":[{"en":"Students look at the following people and match them with statements.","zh":"學生查看以下人物，並把他們與陳述配對。"},{"en":"Look at the following people means read the names listed below the instruction.","zh":"look at the following people 指閱讀指示下方列出的人名。"},{"en":"In a matching task, students first identify who each person is in the passage.","zh":"在配對題中，學生首先辨認每個人在文章中的身份。"},{"en":"Careful reading prevents students from confusing people with similar roles.","zh":"仔細閱讀可以防止學生混淆角色相似的人。"},{"en":"The phrase introduces a people-matching exercise.","zh":"這個短語引出人物配對練習。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":21},{"front":"list of statements","meaning":"陳述列表","examples":[{"en":"The task includes a list of statements.","zh":"該任務包括一個陳述列表。"},{"en":"A list of statements is a group of sentences that students must match or judge.","zh":"list of statements 是學生必須配對或判斷的一組句子。"},{"en":"A reading exercise may give a list of statements about different people in the article.","zh":"閱讀練習可能提供關於文章中不同人物的陳述列表。"},{"en":"Students should underline key words in each statement before searching the passage.","zh":"學生在搜尋文章前，應先劃出每句陳述中的關鍵字。"},{"en":"The phrase describes the answer options in a task.","zh":"這個短語描述任務中的答案選項。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":21},{"front":"match each person with","meaning":"將每個人物與……配對","examples":[{"en":"Students match each person with the correct statement.","zh":"學生將每個人物與正確陳述配對。"},{"en":"To match each person with something means to connect every named person to the right description.","zh":"match each person with 某事，指把每個具名人物連到正確描述。"},{"en":"In history class, students may match each leader with the reform he introduced.","zh":"在歷史課中，學生可能把每位領袖與他推行的改革配對。"},{"en":"Matching requires evidence from the text, not guessing by name alone.","zh":"配對需要文本證據，而不是單靠名字猜測。"},{"en":"The phrase describes a comparison-and-selection task.","zh":"這個短語描述比較和選擇任務。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":21},{"front":"correct statement","meaning":"正確陳述","examples":[{"en":"Students choose the correct statement for each person.","zh":"學生為每個人物選擇正確陳述。"},{"en":"A correct statement is the sentence that accurately matches the person or information in the text.","zh":"correct statement 是準確符合文本中人物或資訊的句子。"},{"en":"A student should choose the statement supported by the passage, not the one that sounds most likely.","zh":"學生應選擇文章支持的陳述，而不是聽起來最可能的陳述。"},{"en":"If two statements seem similar, small details decide which is correct.","zh":"如果兩句陳述看似相似，細節會決定哪句正確。"},{"en":"The phrase describes the right option in an exercise.","zh":"這個短語描述練習中的正確選項。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":21},{"front":"send a complaint","meaning":"發出投訴","examples":[{"en":"Mr Carlill sent a complaint to the company.","zh":"Carlill 先生向公司發出投訴。"},{"en":"To send a complaint means to formally tell an organisation that something is wrong.","zh":"send a complaint 指正式告訴機構某事有問題。"},{"en":"A customer may send a complaint if a product breaks after one day.","zh":"如果產品一天後壞掉，顧客可能發出投訴。"},{"en":"Complaints can start a dispute if the company refuses to reply.","zh":"如果公司拒絕回覆，投訴可以引發爭議。"},{"en":"The phrase describes beginning a formal objection.","zh":"這個短語描述開始正式反對。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":21},{"front":"receive no reply","meaning":"沒有收到回覆","examples":[{"en":"The complaint received no reply.","zh":"該投訴沒有收到回覆。"},{"en":"To receive no reply means to get no response after sending a message or request.","zh":"receive no reply 指發出訊息或請求後沒有得到回應。"},{"en":"A parent may receive no reply after emailing the school office several times.","zh":"家長多次電郵校務處後，可能沒有收到回覆。"},{"en":"No reply can make the sender feel ignored and more determined to act.","zh":"沒有回覆可以令發送者感到被忽視，並更決心行動。"},{"en":"The phrase describes unanswered communication.","zh":"這個短語描述未獲回應的溝通。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":21},{"front":"break the contract","meaning":"違反合約","examples":[{"en":"The company was found to have broken the contract.","zh":"公司被裁定違反合約。"},{"en":"To break the contract means to fail to do what a contract requires.","zh":"break the contract 指未能履行合約要求。"},{"en":"A tenant may break the contract by leaving without paying agreed rent.","zh":"租客沒有支付約定租金就離開，可能違反合約。"},{"en":"Breaking a contract can lead to payment, penalties or court action.","zh":"違反合約可以導致付款、罰款或法律行動。"},{"en":"The phrase describes violation of a legal agreement.","zh":"這個短語描述違反法律協議。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":21},{"front":"begin legal proceedings","meaning":"展開法律程序","examples":[{"en":"Mrs Carlill began legal proceedings against the company.","zh":"Carlill 夫人對公司展開法律程序。"},{"en":"To begin legal proceedings means to start a formal court process.","zh":"begin legal proceedings 指開始正式法庭程序。"},{"en":"A worker may begin legal proceedings if an employer refuses to pay wages.","zh":"如果僱主拒絕支付工資，員工可能展開法律程序。"},{"en":"Legal proceedings can be costly and slow, so people usually try other steps first.","zh":"法律程序可能昂貴且緩慢，所以人們通常先嘗試其他步驟。"},{"en":"The phrase describes starting a legal case.","zh":"這個短語描述開始法律案件。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":21},{"front":"intended audience","meaning":"目標受眾","examples":[{"en":"Judge Hawkins described the intended audience for advertisements.","zh":"Hawkins 法官描述廣告的目標受眾。"},{"en":"The intended audience is the group of people a message is designed to reach.","zh":"intended audience 是訊息設計來接觸的那一群人。"},{"en":"A children’s book has young readers as its intended audience.","zh":"兒童書的目標受眾是年幼讀者。"},{"en":"Knowing the intended audience helps explain the language and tone used.","zh":"知道目標受眾有助解釋所用語言和語氣。"},{"en":"The phrase describes who a message is aimed at.","zh":"這個短語描述訊息針對誰。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":21},{"front":"fraudulent","meaning":"欺詐性的","examples":[{"en":"The option asks whether advertisements were claimed to be fraudulent.","zh":"選項問廣告是否被聲稱為欺詐性的。"},{"en":"Fraudulent means dishonest and intended to deceive for money or advantage.","zh":"fraudulent 指不誠實並意圖為金錢或利益欺騙。"},{"en":"A fraudulent email may pretend to be from a bank to steal passwords.","zh":"欺詐性電郵可能假扮銀行以偷取密碼。"},{"en":"Fraudulent claims can damage trust and lead to legal punishment.","zh":"欺詐性聲稱可以破壞信任並導致法律懲罰。"},{"en":"The word describes deliberate deception.","zh":"這個字描述蓄意欺騙。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":22},{"front":"treat something as","meaning":"把……視為","examples":[{"en":"The court treated the advertisement as a type of contract.","zh":"法庭把該廣告視為一種合約。"},{"en":"To treat something as something else means to regard or handle it in that way.","zh":"treat something as 另一事物，指以該方式看待或處理它。"},{"en":"A teacher may treat a late draft as practice rather than final work.","zh":"老師可能把遲交草稿視為練習，而不是最終作品。"},{"en":"How people treat something affects what rules apply to it.","zh":"人們如何看待某事，會影響適用於它的規則。"},{"en":"The phrase describes classification by action or judgement.","zh":"這個短語描述透過行動或判斷作分類。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":22},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter, A, B, C or D.","zh":"學生選出正確字母 A、B、C 或 D。"},{"en":"Choose the correct letter means select the option letter that matches the right answer.","zh":"choose the correct letter 指選出與正確答案相符的選項字母。"},{"en":"In multiple-choice questions, students should read all options before choosing a letter.","zh":"在多項選擇題中，學生應讀完所有選項才選字母。"},{"en":"A small wording difference can make one letter correct and another wrong.","zh":"細微措辭差異可以令一個字母正確、另一個錯。"},{"en":"The phrase is a standard exam instruction.","zh":"這個短語是標準考試指示。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":22},{"front":"still frequently cited in court","meaning":"至今仍經常在法庭被引用","examples":[{"en":"Mrs Carlill’s case is still frequently cited in court.","zh":"Carlill 夫人的案件至今仍經常在法庭被引用。"},{"en":"Still frequently cited in court means judges or lawyers continue to mention it often in legal cases.","zh":"still frequently cited in court 指法官或律師在法律案件中仍經常提及它。"},{"en":"A landmark case may still be cited in court many years after the original dispute.","zh":"重要案例可能在原本爭議多年後仍在法庭被引用。"},{"en":"Frequent citation shows that the case remains important for legal reasoning.","zh":"經常引用顯示該案對法律推理仍然重要。"},{"en":"The phrase describes lasting legal influence.","zh":"這個短語描述持久法律影響。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":22},{"front":"untrustworthiness of advertisements","meaning":"廣告的不可信","examples":[{"en":"The option refers to the untrustworthiness of advertisements.","zh":"選項提到廣告的不可信。"},{"en":"Untrustworthiness of advertisements means the idea that adverts may not be reliable or honest.","zh":"untrustworthiness of advertisements 指廣告可能不可靠或不誠實這個想法。"},{"en":"A customer may worry about advertisement untrustworthiness after seeing many exaggerated claims.","zh":"顧客看見許多誇張聲稱後，可能擔心廣告不可信。"},{"en":"If adverts are untrustworthy, consumers need evidence before buying.","zh":"如果廣告不可信，消費者購買前需要證據。"},{"en":"The phrase describes doubt about advertising claims.","zh":"這個短語描述對廣告聲稱的懷疑。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":22},{"front":"validity of","meaning":"……的有效性","examples":[{"en":"The case established the validity of a unilateral contract.","zh":"該案確立了單方合約的有效性。"},{"en":"Validity of something means its legal, logical or official acceptability.","zh":"validity of 某事，指其法律、邏輯或官方上的可接受性。"},{"en":"A school may check the validity of a student’s medical certificate.","zh":"學校可能查核學生醫生證明的有效性。"},{"en":"Establishing validity can make an agreement enforceable.","zh":"確立有效性可以令協議可被執行。"},{"en":"The phrase asks whether something is recognised as proper or effective.","zh":"這個短語問某事是否被承認為合適或有效。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":22},{"front":"nature of a contract","meaning":"合約的性質","examples":[{"en":"The option says the case explained the nature of a contract.","zh":"選項說該案解釋了合約的性質。"},{"en":"The nature of a contract means the basic character or essential features of a contract.","zh":"nature of a contract 指合約的基本特性或必要特徵。"},{"en":"Law students study the nature of a contract by learning offer, acceptance and intention.","zh":"法律學生透過學習要約、接受和意圖來研究合約的性質。"},{"en":"Understanding the nature of a contract helps people know when promises become legally binding.","zh":"理解合約性質幫助人知道承諾何時變成具法律約束力。"},{"en":"The phrase asks what a contract really is.","zh":"這個短語問合約真正是甚麼。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":22},{"front":"defend the rights of consumers","meaning":"維護消費者權利","examples":[{"en":"The option says the case defended the rights of consumers.","zh":"選項說該案維護消費者權利。"},{"en":"To defend the rights of consumers means to protect buyers from unfair or dishonest treatment.","zh":"defend the rights of consumers 指保護買家免受不公平或不誠實對待。"},{"en":"Clear refund laws help defend the rights of consumers when products are faulty.","zh":"清楚退款法例有助在產品有問題時維護消費者權利。"},{"en":"Consumer rights matter because ordinary buyers often have less power than companies.","zh":"消費者權利重要，因為普通買家通常比公司權力小。"},{"en":"The phrase describes legal or social protection for customers.","zh":"這個短語描述對顧客的法律或社會保護。"}],"source":"30 - Mrs. Carlill and the Carbolic Smoke Ball.pdf","sourcePage":22}],"ielts/reading/passage-2/Practice 31":[{"front":"eco-resort management practices","meaning":"生態度假村管理做法","examples":[{"en":"The passage examines eco-resort management practices at Couran Cove Island Resort.","zh":"文章研究 Couran Cove Island Resort 的生態度假村管理做法。"},{"en":"Eco-resort management practices are the ways a resort runs its services while reducing harm to nature.","zh":"生態度假村管理做法是指度假村在營運服務時減少對自然傷害的方法。"},{"en":"A hotel uses eco-resort management practices when it saves water, reduces waste, and protects nearby wildlife.","zh":"酒店節約用水、減少廢物並保護附近野生生物時，就是在使用生態度假村管理做法。"},{"en":"Good eco-resort management practices can lower pollution and make tourism more sustainable.","zh":"良好的生態度假村管理做法可以降低污染，令旅遊更可持續。"},{"en":"These practices matter because a resort can damage the environment if it only focuses on comfort and profit.","zh":"這些做法很重要，因為如果度假村只重視舒適和利潤，就可能破壞環境。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":1},{"front":"ecotourism","meaning":"生態旅遊","examples":[{"en":"Ecotourism is often regarded as a form of nature-based tourism.","zh":"生態旅遊常被視為一種以自然為本的旅遊。"},{"en":"Ecotourism is tourism that focuses on nature, conservation, and responsible travel.","zh":"生態旅遊是著重自然、保育和負責任旅行的旅遊形式。"},{"en":"Visitors join ecotourism when they visit a rainforest with guides who explain wildlife and protect the area.","zh":"遊客跟隨導遊參觀雨林、了解野生生物並保護該地時，就是參與生態旅遊。"},{"en":"Ecotourism can support local communities if money goes into conservation and education.","zh":"如果收入用於保育和教育，生態旅遊可以支持本地社區。"},{"en":"It is different from ordinary tourism because the natural environment should not simply be used as scenery.","zh":"它不同於普通旅遊，因為自然環境不應只被當作風景使用。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":1},{"front":"be regarded as","meaning":"被視為","examples":[{"en":"Ecotourism is often regarded as a form of nature-based tourism.","zh":"生態旅遊常被視為一種以自然為本的旅遊。"},{"en":"To be regarded as something means to be seen, considered, or understood in that way.","zh":"be regarded as something 指被看作、認為或理解為某種事物。"},{"en":"A quiet student may be regarded as shy, even if they are simply careful before speaking.","zh":"安靜的學生可能被視為害羞，即使他只是說話前較謹慎。"},{"en":"When a place is regarded as important, people are more likely to protect it.","zh":"當一個地方被視為重要，人們就更可能保護它。"},{"en":"This phrase introduces how people view or classify something.","zh":"這個短語引入人們如何看待或分類某事。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":1},{"front":"nature-based tourism","meaning":"以自然為本的旅遊","examples":[{"en":"Ecotourism is a form of nature-based tourism.","zh":"生態旅遊是一種以自然為本的旅遊。"},{"en":"Nature-based tourism is tourism built around natural places, animals, plants, or landscapes.","zh":"以自然為本的旅遊是圍繞自然地方、動物、植物或地貌而建立的旅遊。"},{"en":"Whale watching, forest walks, and guided wetland visits are examples of nature-based tourism.","zh":"觀鯨、森林步行和濕地導賞都是以自然為本的旅遊例子。"},{"en":"Nature-based tourism can damage habitats if too many visitors arrive without controls.","zh":"如果太多遊客在沒有管制下到訪，以自然為本的旅遊可能破壞棲息地。"},{"en":"This phrase focuses on tourism where nature is the main attraction.","zh":"這個短語著重以自然作為主要吸引力的旅遊。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":1},{"front":"alternative form of tourism","meaning":"另一種旅遊形式","examples":[{"en":"Ecotourism has become an important alternative form of tourism.","zh":"生態旅遊已成為重要的另一種旅遊形式。"},{"en":"An alternative form of tourism is a different choice from ordinary mass tourism.","zh":"alternative form of tourism 指不同於普通大眾旅遊的另一選擇。"},{"en":"Staying with local families can be an alternative form of tourism to large hotel holidays.","zh":"與本地家庭同住可以是大型酒店度假的另一種旅遊形式。"},{"en":"Alternative tourism grows when travellers want experiences that feel smaller, greener, or more meaningful.","zh":"當旅客想要更小規模、更環保或更有意義的體驗，另類旅遊就會增長。"},{"en":"This phrase suggests another way to travel, not the usual package holiday.","zh":"這個短語表示另一種旅行方式，而不是常見套票假期。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":1},{"front":"in addition to","meaning":"除了……之外","examples":[{"en":"In addition to providing leisure, ecotourism should support conservation.","zh":"除了提供休閒之外，生態旅遊應支持保育。"},{"en":"In addition to means as well as or besides something already mentioned.","zh":"in addition to 指除了已提到的事情之外，也包括另一件事。"},{"en":"In addition to English lessons, a student may need daily listening practice.","zh":"除了英文課之外，學生可能需要每日聆聽練習。"},{"en":"This phrase adds another responsibility, benefit, or feature to the first one.","zh":"這個短語在第一項之外加入另一責任、好處或特色。"},{"en":"It is useful when showing that one thing has more than one purpose.","zh":"當要顯示一件事有多於一個目的時，這個短語很有用。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":1},{"front":"traditional resort-leisure product","meaning":"傳統度假村休閒產品","examples":[{"en":"Ecotourism resorts provide the traditional resort-leisure product.","zh":"生態旅遊度假村提供傳統度假村休閒產品。"},{"en":"A traditional resort-leisure product is the usual holiday experience of accommodation, relaxation, food, and activities.","zh":"traditional resort-leisure product 指住宿、放鬆、餐飲和活動等一般假期體驗。"},{"en":"A beach resort offers a traditional resort-leisure product when guests swim, eat, rest, and join activities.","zh":"海灘度假村讓客人游泳、用餐、休息和參加活動時，就是提供傳統度假村休閒產品。"},{"en":"Eco-resorts must provide leisure while also protecting the environment.","zh":"生態度假村必須提供休閒，同時保護環境。"},{"en":"This phrase describes the normal resort service that tourists expect.","zh":"這個短語描述遊客預期得到的一般度假村服務。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":1},{"front":"it has been argued that","meaning":"有人認為","examples":[{"en":"It has been argued that ecotourism management should focus on best practice.","zh":"有人認為生態旅遊管理應集中於最佳做法。"},{"en":"It has been argued that means some people have claimed or reasoned that something is true.","zh":"it has been argued that 指有人主張或推論某事為真。"},{"en":"It has been argued that smaller classes help weaker students receive more attention.","zh":"有人認為較小班級能幫助較弱學生獲得更多關注。"},{"en":"Writers use this phrase when presenting an opinion without naming every person who supports it.","zh":"作者想提出某種觀點，但不列出每位支持者時，會使用這個短語。"},{"en":"This phrase introduces a viewpoint, not necessarily an unquestionable fact.","zh":"這個短語引入觀點，而不一定是無可爭議的事實。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":1},{"front":"focus particularly on","meaning":"特別集中於……","examples":[{"en":"Ecotourism resort management should focus particularly on environmental management.","zh":"生態旅遊度假村管理應特別集中於環境管理。"},{"en":"To focus particularly on something means to give that thing special attention.","zh":"focus particularly on something 指對某事給予特別注意。"},{"en":"A teacher may focus particularly on pronunciation if students speak clearly but sound unnatural.","zh":"如果學生說得清楚但不自然，老師可能特別集中於發音。"},{"en":"Focusing particularly on one area helps people deal with the most important problem first.","zh":"特別集中於一個範疇，可以幫助人先處理最重要問題。"},{"en":"This phrase shows that one issue deserves more attention than others.","zh":"這個短語顯示某議題比其他議題更值得注意。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":1},{"front":"best-practice environmental management","meaning":"最佳環境管理做法","examples":[{"en":"Eco-resorts should focus on best-practice environmental management.","zh":"生態度假村應集中於最佳環境管理做法。"},{"en":"Best-practice environmental management means using the most effective known methods to protect the environment.","zh":"best-practice environmental management 指使用已知最有效的方法來保護環境。"},{"en":"A hotel follows best-practice environmental management when it saves energy, treats wastewater, and controls visitor damage.","zh":"酒店節能、處理污水並控制遊客破壞時，就是遵循最佳環境管理做法。"},{"en":"Such management can reduce pollution and protect natural resources for the future.","zh":"這種管理可以減少污染，並為未來保護自然資源。"},{"en":"This phrase means not just being “green”, but using proven high-standard methods.","zh":"這個短語不只是指「環保」，而是使用經證實的高標準方法。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":1},{"front":"educational and interpretive component","meaning":"教育及解說元素","examples":[{"en":"Ecotourism should include an educational and interpretive component.","zh":"生態旅遊應包括教育及解說元素。"},{"en":"An educational and interpretive component teaches visitors about the meaning and value of what they see.","zh":"educational and interpretive component 指教導遊客理解所見事物的意義和價值。"},{"en":"A nature trail has this component when signs explain plants, animals, and local history.","zh":"自然步道若有標誌解釋植物、動物和本地歷史，就有這種元素。"},{"en":"Interpretation can turn sightseeing into learning because visitors understand why a place matters.","zh":"解說可以把觀光變成學習，因為遊客會明白一個地方為何重要。"},{"en":"This phrase means the resort should educate guests, not only entertain them.","zh":"這個短語表示度假村應教育客人，而不只是娛樂他們。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":2},{"front":"contribute directly and indirectly to","meaning":"直接及間接促進……","examples":[{"en":"Ecotourism should contribute directly and indirectly to conservation.","zh":"生態旅遊應直接及間接促進保育。"},{"en":"To contribute directly and indirectly to something means to help it in obvious ways and also through less obvious effects.","zh":"contribute directly and indirectly to something 指以明顯方式和較不明顯的效果幫助某事。"},{"en":"A school garden can contribute directly to learning through lessons and indirectly by making students care about nature.","zh":"學校花園可以透過課堂直接促進學習，也可以透過令學生關心自然來間接促進學習。"},{"en":"Tourism contributes directly when it funds conservation and indirectly when it changes visitors’ attitudes.","zh":"旅遊在資助保育時直接促進保育，在改變遊客態度時則間接促進保育。"},{"en":"This phrase shows that support can happen in more than one way.","zh":"這個短語顯示支持可以以多於一種方式出現。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":2},{"front":"conservation of","meaning":"對……的保育","examples":[{"en":"Ecotourism should contribute to the conservation of the environment.","zh":"生態旅遊應促進對環境的保育。"},{"en":"Conservation of something means protecting it from damage, waste, or disappearance.","zh":"conservation of something 指保護某事物免受破壞、浪費或消失。"},{"en":"The conservation of old buildings can keep a neighbourhood’s history alive.","zh":"對舊建築的保育可以讓社區歷史延續。"},{"en":"Conservation work is needed when human activity threatens natural or cultural resources.","zh":"當人類活動威脅自然或文化資源，就需要保育工作。"},{"en":"This phrase focuses on protection and careful long-term care.","zh":"這個短語著重保護和長期細心照顧。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":2},{"front":"natural and cultural environment","meaning":"自然及文化環境","examples":[{"en":"Eco-resorts should protect the natural and cultural environment.","zh":"生態度假村應保護自然及文化環境。"},{"en":"The natural and cultural environment includes nature, wildlife, landscapes, traditions, history, and local ways of life.","zh":"natural and cultural environment 包括自然、野生生物、地貌、傳統、歷史和本地生活方式。"},{"en":"A village tour protects this environment when it respects both forests and local customs.","zh":"鄉村導賞若同時尊重森林和本地習俗，就是保護自然及文化環境。"},{"en":"Tourism can harm the natural and cultural environment if visitors damage habitats or disrespect traditions.","zh":"如果遊客破壞棲息地或不尊重傳統，旅遊可以傷害自然及文化環境。"},{"en":"This phrase reminds us that places are made of both nature and culture.","zh":"這個短語提醒我們，地方同時由自然和文化構成。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":2},{"front":"integrated resort","meaning":"綜合度假村","examples":[{"en":"Couran Cove Island Resort is a large, integrated resort.","zh":"Couran Cove Island Resort 是一個大型綜合度假村。"},{"en":"An integrated resort is a resort with several connected facilities and services in one place.","zh":"integrated resort 指在同一地方有多種互相連接設施和服務的度假村。"},{"en":"A large integrated resort may include accommodation, restaurants, transport, shops, and activities.","zh":"大型綜合度假村可能包括住宿、餐廳、交通、商店和活動。"},{"en":"Integration makes the guest experience easier because many needs are handled within the resort.","zh":"綜合式安排令住客體驗更方便，因為許多需要都在度假村內處理。"},{"en":"This phrase describes a complete resort system, not just a single hotel building.","zh":"這個短語描述完整度假村系統，而不只是單一酒店建築。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":2},{"front":"ecotourism-based resort","meaning":"以生態旅遊為本的度假村","examples":[{"en":"Couran Cove is an ecotourism-based resort in Queensland.","zh":"Couran Cove 是昆士蘭一個以生態旅遊為本的度假村。"},{"en":"An ecotourism-based resort is a resort planned around nature, conservation, and low-impact travel.","zh":"ecotourism-based resort 指圍繞自然、保育和低影響旅遊而規劃的度假村。"},{"en":"A lodge beside a national park can be ecotourism-based if it limits waste and teaches visitors about wildlife.","zh":"國家公園旁的小屋若限制廢物並教遊客認識野生生物，就可以是以生態旅遊為本的度假村。"},{"en":"Such a resort must balance guest comfort with environmental responsibility.","zh":"這類度假村必須平衡客人舒適與環境責任。"},{"en":"This phrase shows that ecology is central to the resort’s identity.","zh":"這個短語顯示生態是度假村身份的核心。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":2},{"front":"located south of","meaning":"位於……以南","examples":[{"en":"The resort is located south of Brisbane.","zh":"該度假村位於布里斯本以南。"},{"en":"Located south of a place means situated below it on a map, toward the south.","zh":"located south of a place 指在地圖上位於某地下面，即南方。"},{"en":"A school located south of the city centre may take longer to reach by bus.","zh":"位於市中心以南的學校，乘巴士可能要較長時間到達。"},{"en":"Location affects access because visitors need transport to get there.","zh":"位置會影響交通可達性，因為遊客需要交通工具前往。"},{"en":"This phrase gives a simple geographical position.","zh":"這個短語給出簡單地理位置。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":2},{"front":"the Gold Coast","meaning":"黃金海岸","examples":[{"en":"Couran Cove is on the Gold Coast in Queensland.","zh":"Couran Cove 位於昆士蘭的黃金海岸。"},{"en":"The Gold Coast is a coastal region in Queensland known for beaches and tourism.","zh":"Gold Coast 是昆士蘭一個以海灘和旅遊聞名的沿海地區。"},{"en":"Many visitors go to the Gold Coast for surfing, hotels, and family holidays.","zh":"許多遊客到黃金海岸滑浪、入住酒店和家庭度假。"},{"en":"A tourism region can attract investment because many travellers already know its name.","zh":"旅遊地區可以吸引投資，因為許多旅客已知道其名稱。"},{"en":"This phrase names a specific tourist area in Australia.","zh":"這個短語命名澳洲一個特定旅遊區。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":2},{"front":"Queensland","meaning":"昆士蘭","examples":[{"en":"The resort is located in Queensland, Australia.","zh":"該度假村位於澳洲昆士蘭。"},{"en":"Queensland is a state in north-eastern Australia.","zh":"Queensland 是澳洲東北部的一個州。"},{"en":"Tourists may visit Queensland for beaches, rainforests, reefs, and warm weather.","zh":"遊客可能因海灘、雨林、珊瑚礁和溫暖天氣而到訪昆士蘭。"},{"en":"The location in Queensland matters because climate and coastal tourism shape resort planning.","zh":"位於昆士蘭很重要，因為氣候和沿海旅遊會塑造度假村規劃。"},{"en":"This phrase names the Australian state where the resort is located.","zh":"這個短語命名該度假村所在的澳洲州份。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":2},{"front":"increasingly urbanised","meaning":"越來越城市化","examples":[{"en":"The world’s population is becoming increasingly urbanised.","zh":"世界人口正變得越來越城市化。"},{"en":"Increasingly urbanised means more and more people are living in towns and cities.","zh":"increasingly urbanised 指越來越多人住在城鎮和城市。"},{"en":"A country becomes increasingly urbanised when young people move from villages to city jobs.","zh":"當年輕人由鄉村搬到城市工作，國家就會越來越城市化。"},{"en":"Urbanisation can increase demand for quiet natural holidays because city life feels crowded.","zh":"城市化可以增加對寧靜自然假期的需求，因為城市生活感覺擠迫。"},{"en":"This phrase describes a gradual shift toward city living.","zh":"這個短語描述逐漸轉向城市生活。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":2},{"front":"demand has grown rapidly for","meaning":"對……的需求迅速增長","examples":[{"en":"Demand has grown rapidly for environmentally friendly tourist attractions.","zh":"對環保旅遊景點的需求迅速增長。"},{"en":"Demand has grown rapidly for something means many more people want it in a short time.","zh":"demand has grown rapidly for something 指很多人在短時間內更想要某事物。"},{"en":"Demand has grown rapidly for online lessons when students need flexible study options.","zh":"當學生需要彈性學習選項，對網上課堂的需求迅速增長。"},{"en":"Rapidly growing demand can encourage businesses to create new products and services.","zh":"快速增長的需求可以鼓勵企業創造新產品和服務。"},{"en":"This phrase shows a fast increase in public interest or need.","zh":"這個短語顯示公眾興趣或需要快速增加。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":3},{"front":"tourist attractions","meaning":"旅遊景點","examples":[{"en":"Environmentally friendly tourist attractions are in growing demand.","zh":"環保旅遊景點的需求正在增長。"},{"en":"Tourist attractions are places or activities that people visit for interest, enjoyment, or learning.","zh":"tourist attractions 指人們為興趣、享受或學習而到訪的地方或活動。"},{"en":"Museums, beaches, theme parks, and historic villages can all be tourist attractions.","zh":"博物館、海灘、主題公園和歷史村落都可以是旅遊景點。"},{"en":"Tourist attractions need good management because too many visitors can damage them.","zh":"旅遊景點需要良好管理，因為太多遊客可能破壞它們。"},{"en":"This phrase refers to things that draw visitors to a place.","zh":"這個短語指吸引遊客到某地的事物。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":3},{"front":"environmentally friendly","meaning":"環保的","examples":[{"en":"Tourists increasingly want environmentally friendly attractions.","zh":"遊客越來越想要環保的景點。"},{"en":"Environmentally friendly means causing little harm to the natural environment.","zh":"environmentally friendly 指對自然環境造成較少傷害。"},{"en":"A shop is more environmentally friendly when it reduces plastic bags and saves electricity.","zh":"商店減少膠袋並節省電力時，就更環保。"},{"en":"Environmentally friendly choices can reduce waste, pollution, and energy use.","zh":"環保選擇可以減少廢物、污染和能源使用。"},{"en":"This phrase describes actions or products that try to protect nature.","zh":"這個短語描述試圖保護自然的行動或產品。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":3},{"front":"serene","meaning":"寧靜的","examples":[{"en":"Many tourists look for places that are serene and natural.","zh":"許多遊客尋找寧靜而自然的地方。"},{"en":"Serene means calm, peaceful, and free from noise or stress.","zh":"serene 指平靜、安寧，沒有噪音或壓力。"},{"en":"A quiet garden beside a library can feel serene after a busy school day.","zh":"忙碌上學日後，圖書館旁的安靜花園可能令人感到寧靜。"},{"en":"Serene places help people relax because they are not crowded or chaotic.","zh":"寧靜地方令人放鬆，因為它們不擁擠、不混亂。"},{"en":"This word describes a peaceful atmosphere.","zh":"這個詞描述平和的氣氛。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":3},{"front":"offer unique amenities","meaning":"提供獨特設施","examples":[{"en":"The resort offers unique amenities to visitors.","zh":"該度假村為遊客提供獨特設施。"},{"en":"To offer unique amenities means to provide special facilities or services that visitors cannot easily find elsewhere.","zh":"offer unique amenities 指提供遊客在其他地方不容易找到的特別設施或服務。"},{"en":"A hotel may offer unique amenities such as guided night walks or solar-powered cabins.","zh":"酒店可能提供夜間導賞或太陽能小屋等獨特設施。"},{"en":"Unique amenities can make guests choose one resort over another.","zh":"獨特設施可以令客人選擇某一度假村，而不是另一間。"},{"en":"This phrase focuses on special features that improve the visitor experience.","zh":"這個短語著重改善遊客體驗的特別特色。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":3},{"front":"one such tourist attraction","meaning":"這類旅遊景點之一","examples":[{"en":"Couran Cove Resort is one such tourist attraction.","zh":"Couran Cove Resort 是這類旅遊景點之一。"},{"en":"One such tourist attraction means one example of the type of attraction just described.","zh":"one such tourist attraction 指剛描述那類景點中的一個例子。"},{"en":"If many students like quiet study places, the new library is one such place.","zh":"如果許多學生喜歡安靜溫習地方，新圖書館就是這類地方之一。"},{"en":"This phrase connects a specific example to a general category.","zh":"這個短語把具體例子連接到一般類別。"},{"en":"It helps writers move from general explanation to a concrete case.","zh":"它幫助作者由概括說明轉向具體個案。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":3},{"front":"South Stradbroke Island","meaning":"南斯特拉德布羅克島","examples":[{"en":"Couran Cove Resort is located on South Stradbroke Island.","zh":"Couran Cove Resort 位於南斯特拉德布羅克島。"},{"en":"South Stradbroke Island is the island where the resort is situated.","zh":"South Stradbroke Island 是該度假村所在的島嶼。"},{"en":"A resort on an island needs careful transport planning because visitors cannot simply drive there.","zh":"島上的度假村需要仔細交通規劃，因為遊客不能簡單地開車前往。"},{"en":"Island locations often make water, waste, and energy management more difficult.","zh":"島嶼位置常令用水、廢物和能源管理更困難。"},{"en":"This phrase names the specific island setting of the resort.","zh":"這個短語命名該度假村的具體島嶼環境。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":3},{"front":"occupy approximately","meaning":"佔地約……","examples":[{"en":"The resort occupies approximately 150 hectares.","zh":"該度假村佔地約 150 公頃。"},{"en":"To occupy approximately an area means to cover about that amount of land.","zh":"occupy approximately an area 指覆蓋大約某面積的土地。"},{"en":"A school campus may occupy approximately five hectares if it includes sports fields and buildings.","zh":"如果學校校園包括運動場和建築物，可能佔地約五公頃。"},{"en":"Approximate land size helps readers imagine how large a place is.","zh":"大約土地面積幫助讀者想像地方有多大。"},{"en":"This phrase gives an estimated area, not an exact measurement.","zh":"這個短語給出估計面積，而不是精確量度。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":3},{"front":"hectares","meaning":"公頃","examples":[{"en":"Couran Cove occupies approximately 150 hectares.","zh":"Couran Cove 佔地約 150 公頃。"},{"en":"Hectares are units used to measure large areas of land.","zh":"hectares 是用來量度大面積土地的單位。"},{"en":"A large farm may cover hundreds of hectares.","zh":"大型農場可能佔地數百公頃。"},{"en":"Using hectares helps describe resorts, parks, forests, and agricultural land clearly.","zh":"使用公頃可以清楚描述度假村、公園、森林和農地。"},{"en":"One hectare is 10,000 square metres.","zh":"一公頃等於一萬平方米。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":3},{"front":"be separated from","meaning":"與……分隔","examples":[{"en":"South Stradbroke Island is separated from the mainland by the Broadwater.","zh":"南斯特拉德布羅克島與本土由 Broadwater 分隔。"},{"en":"To be separated from something means to be divided from it by distance, water, walls, or another barrier.","zh":"be separated from something 指被距離、水域、牆壁或另一屏障分開。"},{"en":"A classroom may be separated from the hall by a glass wall.","zh":"課室可能由玻璃牆與禮堂分隔。"},{"en":"Islands separated from the mainland need boats or bridges for access.","zh":"與本土分隔的島嶼需要船或橋前往。"},{"en":"This phrase describes physical division between two places.","zh":"這個短語描述兩地之間的實體分隔。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":3},{"front":"the mainland","meaning":"大陸；本土","examples":[{"en":"The island is separated from the mainland by a stretch of sea.","zh":"該島與本土由一片海域分隔。"},{"en":"The mainland is the main large land area, as opposed to an island nearby.","zh":"mainland 指主要的大塊陸地，相對於附近島嶼。"},{"en":"Islanders may travel to the mainland for hospitals, schools, or larger shops.","zh":"島民可能到本土使用醫院、學校或較大型商店。"},{"en":"If an island depends on the mainland, transport interruptions can create problems.","zh":"如果島嶼依賴本土，交通中斷可以造成問題。"},{"en":"This phrase contrasts the main landmass with an island.","zh":"這個短語把主要陸地與島嶼作對比。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":4},{"front":"a stretch of sea","meaning":"一片海域","examples":[{"en":"The Broadwater is a stretch of sea three kilometres wide.","zh":"Broadwater 是一片三公里寬的海域。"},{"en":"A stretch of sea is an area or section of seawater between places.","zh":"stretch of sea 指兩地之間的一段或一片海水區域。"},{"en":"A ferry may cross a short stretch of sea between a town and an island.","zh":"渡輪可能橫越城鎮與島嶼之間的一小片海域。"},{"en":"Even a narrow stretch of sea can make transport more complicated.","zh":"即使狹窄海域也可以令交通更複雜。"},{"en":"This phrase describes a particular piece of sea, not the whole ocean.","zh":"這個短語描述某一片海，而不是整個海洋。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":4},{"front":"Aboriginal tribes","meaning":"原住民部落","examples":[{"en":"At least four Aboriginal tribes once lived on Stradbroke Island.","zh":"至少四個原住民部落曾住在 Stradbroke Island。"},{"en":"Aboriginal tribes are Indigenous groups with their own land, culture, language, and traditions.","zh":"Aboriginal tribes 指擁有自己土地、文化、語言和傳統的原住民群體。"},{"en":"A museum should describe Aboriginal tribes respectfully and avoid treating them as only part of the past.","zh":"博物館應尊重地描述原住民部落，避免只把他們當作過去的一部分。"},{"en":"When tourism uses Indigenous history, it should involve and respect Indigenous communities.","zh":"當旅遊使用原住民歷史時，應讓原住民社群參與並尊重他們。"},{"en":"This phrase refers to original peoples and their social groups.","zh":"這個短語指原本的民族及其社會群體。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":4},{"front":"live and hunt","meaning":"生活和狩獵","examples":[{"en":"Aboriginal tribes lived and hunted on Stradbroke Island.","zh":"原住民部落在 Stradbroke Island 生活和狩獵。"},{"en":"To live and hunt in a place means to make a home there and find food from the land or animals.","zh":"live and hunt in a place 指在某地居住，並從土地或動物中獲取食物。"},{"en":"Early communities often lived and hunted near rivers because water and animals were available.","zh":"早期社群常在河流附近生活和狩獵，因為那裡有水和動物。"},{"en":"Living and hunting in one area can create deep knowledge of local seasons and wildlife.","zh":"在一個地區生活和狩獵，可以形成對本地季節和野生生物的深厚知識。"},{"en":"This phrase describes a traditional way of life connected to land.","zh":"這個短語描述與土地相連的傳統生活方式。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":4},{"front":"regrettably","meaning":"令人遺憾的是","examples":[{"en":"Regrettably, most of the original islanders died from disease.","zh":"令人遺憾的是，大多數原本的島民死於疾病。"},{"en":"Regrettably means sadly or unfortunately.","zh":"regrettably 指可悲地或不幸地。"},{"en":"Regrettably, the school trip was cancelled because the storm made travel unsafe.","zh":"令人遺憾的是，由於風暴令旅程不安全，學校旅行被取消。"},{"en":"Writers use this word when reporting something unfortunate with sympathy.","zh":"作者報告不幸事情並帶有同情時，會使用這個詞。"},{"en":"This word signals that the information is sad or disappointing.","zh":"這個詞表示資料令人難過或失望。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":4},{"front":"original islanders","meaning":"原本的島民","examples":[{"en":"Most of the original islanders had been killed by disease.","zh":"大多數原本的島民死於疾病。"},{"en":"Original islanders are the people who lived on an island before later settlers or visitors arrived.","zh":"original islanders 指後來定居者或訪客到來前已住在島上的人。"},{"en":"A history lesson about an island should include the lives of the original islanders.","zh":"關於島嶼的歷史課應包括原本島民的生活。"},{"en":"Ignoring original islanders can make tourism stories incomplete and unfair.","zh":"忽視原本島民會令旅遊故事不完整且不公平。"},{"en":"This phrase refers to the earliest known local inhabitants of an island.","zh":"這個短語指島嶼最早為人所知的本地居民。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":4},{"front":"diseases such as","meaning":"例如……的疾病","examples":[{"en":"Diseases such as tuberculosis, smallpox and influenza killed many islanders.","zh":"肺結核、天花和流感等疾病殺死了許多島民。"},{"en":"Diseases such as means illnesses like the examples that follow.","zh":"diseases such as 指像後面例子那樣的疾病。"},{"en":"Schools may warn families about diseases such as flu and chickenpox during an outbreak.","zh":"爆發疫情期間，學校可能提醒家庭注意流感和水痘等疾病。"},{"en":"This phrase introduces examples without saying the list is complete.","zh":"這個短語引入例子，但不表示列表完整。"},{"en":"It is useful when giving several clear examples of a wider category.","zh":"當要給出較大類別中的幾個清楚例子時，這個短語很有用。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":4},{"front":"tuberculosis","meaning":"肺結核","examples":[{"en":"Tuberculosis was one of the diseases that affected the islanders.","zh":"肺結核是影響島民的疾病之一。"},{"en":"Tuberculosis is a serious infectious disease that mainly affects the lungs.","zh":"tuberculosis 是一種嚴重傳染病，主要影響肺部。"},{"en":"A doctor may test for tuberculosis if a patient has a long cough and weight loss.","zh":"如果病人長期咳嗽和體重下降，醫生可能檢查肺結核。"},{"en":"Infectious diseases can spread quickly when people have no immunity or medical support.","zh":"當人們沒有免疫力或醫療支援，傳染病可以快速傳播。"},{"en":"This word names a specific disease, often shortened to TB.","zh":"這個詞命名一種特定疾病，常縮寫為 TB。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":4},{"front":"smallpox","meaning":"天花","examples":[{"en":"Smallpox killed many original islanders.","zh":"天花殺死了許多原本的島民。"},{"en":"Smallpox was a dangerous infectious disease that caused fever and a severe skin rash.","zh":"smallpox 是一種危險傳染病，會引起發燒和嚴重皮疹。"},{"en":"In history lessons, smallpox is often discussed because it devastated many communities.","zh":"歷史課常討論天花，因為它摧毀了許多社群。"},{"en":"Diseases like smallpox were especially deadly when people had no previous exposure to them.","zh":"當人們以前從未接觸過某些疾病，像天花這類疾病尤其致命。"},{"en":"This word refers to a serious historical disease, not ordinary chickenpox.","zh":"這個詞指嚴重歷史疾病，而不是普通水痘。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":4},{"front":"influenza","meaning":"流感","examples":[{"en":"Influenza was among the diseases that affected the islanders.","zh":"流感是影響島民的疾病之一。"},{"en":"Influenza is a contagious illness often called flu.","zh":"influenza 是一種具傳染性的疾病，常稱為 flu。"},{"en":"A worker with influenza may need to stay home to avoid infecting colleagues.","zh":"患流感的員工可能需要留在家中，以免感染同事。"},{"en":"Flu can spread quickly in crowded places such as schools, offices, and transport.","zh":"流感可以在學校、辦公室和交通工具等擠迫地方迅速傳播。"},{"en":"This word is more formal than “flu”.","zh":"這個詞比 flu 更正式。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":4},{"front":"by the end of","meaning":"到……結束時","examples":[{"en":"Most original islanders had died by the end of the 19th century.","zh":"到十九世紀結束時，大多數原本島民已經死亡。"},{"en":"By the end of a period means before that period finished.","zh":"by the end of a period 指在該時期結束之前。"},{"en":"By the end of the school year, students should know how to write a basic essay.","zh":"到學年結束時，學生應懂得如何寫基本文章。"},{"en":"This phrase gives a deadline or final point in time.","zh":"這個短語給出限期或最終時間點。"},{"en":"It is often used to show what had happened before a period closed.","zh":"它常用於顯示某時期結束前已發生的事情。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":5},{"front":"be wrecked on","meaning":"在……失事","examples":[{"en":"The ship Cambus Wallace was wrecked on the island.","zh":"Cambus Wallace 號船在該島失事。"},{"en":"To be wrecked on a place means a ship was destroyed or badly damaged there.","zh":"be wrecked on a place 指船隻在某地被摧毀或嚴重損壞。"},{"en":"A fishing boat may be wrecked on rocks during a storm.","zh":"漁船可能在風暴期間撞上岩石失事。"},{"en":"A wrecked ship can create danger if fuel, chemicals, or cargo spill out.","zh":"失事船隻若漏出燃油、化學品或貨物，可以造成危險。"},{"en":"This phrase describes a serious ship accident at a location.","zh":"這個短語描述某地發生的嚴重船難。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":5},{"front":"carry dynamite","meaning":"載有炸藥","examples":[{"en":"The ship was carrying dynamite when it was wrecked.","zh":"該船失事時載有炸藥。"},{"en":"To carry dynamite means to transport explosive material.","zh":"carry dynamite 指運送爆炸物料。"},{"en":"A truck carrying dynamite must follow strict safety rules.","zh":"載有炸藥的貨車必須遵守嚴格安全規則。"},{"en":"If dynamite is damaged or ignited, it can cause a powerful explosion.","zh":"如果炸藥受損或被點燃，可以造成強烈爆炸。"},{"en":"This phrase describes dangerous cargo being transported.","zh":"這個短語描述正在運送危險貨物。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":5},{"front":"subsequent destruction","meaning":"隨後的毀壞","examples":[{"en":"The ship’s subsequent destruction caused a large crater.","zh":"該船隨後的毀壞造成一個大坑。"},{"en":"Subsequent destruction means damage or destruction that happened after an earlier event.","zh":"subsequent destruction 指在較早事件之後發生的破壞或毀壞。"},{"en":"After a kitchen fire, subsequent water damage from firefighting may also need repair.","zh":"廚房火災後，救火造成的後續水損也可能需要維修。"},{"en":"One accident can lead to later destruction if dangerous materials are involved.","zh":"如果涉及危險物料，一場事故可能導致之後的毀壞。"},{"en":"This phrase links an earlier incident with later damage.","zh":"這個短語把較早事件與後來損害連繫起來。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":5},{"front":"cause a large crater","meaning":"造成一個大坑","examples":[{"en":"The destruction caused a large crater in the sandhills.","zh":"這次毀壞在沙丘中造成一個大坑。"},{"en":"To cause a large crater means to create a big hole in the ground by impact or explosion.","zh":"cause a large crater 指因撞擊或爆炸在地面造成大洞。"},{"en":"A gas explosion can cause a large crater in a road.","zh":"氣體爆炸可以在道路上造成一個大坑。"},{"en":"A crater changes the landform because it removes or displaces earth and sand.","zh":"大坑會改變地貌，因為它移除或推開泥土和沙。"},{"en":"This phrase describes serious physical damage to the ground.","zh":"這個短語描述對地面的嚴重實體破壞。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":5},{"front":"sandhills","meaning":"沙丘","examples":[{"en":"The explosion damaged Stradbroke Island’s sandhills.","zh":"爆炸損壞了 Stradbroke Island 的沙丘。"},{"en":"Sandhills are hills or raised areas made mainly of sand.","zh":"sandhills 指主要由沙構成的山丘或高起地區。"},{"en":"Children may see sandhills near beaches where wind piles up sand.","zh":"孩子可能在海灘附近看到由風堆積沙形成的沙丘。"},{"en":"Sandhills can protect inland areas, but they are easily damaged by vehicles and construction.","zh":"沙丘可以保護內陸地區，但容易被車輛和建築工程破壞。"},{"en":"This word describes natural sandy landforms.","zh":"這個詞描述天然沙質地貌。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":5},{"front":"eventually","meaning":"最終","examples":[{"en":"Eventually, the ocean broke through the weakened landform.","zh":"最終，海洋衝破了受削弱的地貌。"},{"en":"Eventually means after some time or after a series of events.","zh":"eventually 指經過一段時間或一連串事件之後。"},{"en":"If a student practises every day, they will eventually speak more confidently.","zh":"如果學生每天練習，他最終會說得更有信心。"},{"en":"This word shows that something did not happen immediately, but happened later.","zh":"這個詞顯示某事不是立即發生，而是之後才發生。"},{"en":"It is useful when explaining a result that comes at the end of a process.","zh":"它適合用於解釋一個過程最後出現的結果。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":5},{"front":"break through","meaning":"衝破","examples":[{"en":"The ocean broke through the weakened landform.","zh":"海洋衝破了受削弱的地貌。"},{"en":"To break through means to force a way through a barrier or surface.","zh":"break through 指強行穿過屏障或表面。"},{"en":"Water may break through a weak wall during a flood.","zh":"洪水期間，水可能衝破薄弱牆壁。"},{"en":"When a barrier is weakened, pressure can build until something breaks through it.","zh":"當屏障被削弱，壓力可以累積，直到某物衝破它。"},{"en":"This phrase describes forceful movement through an obstacle.","zh":"這個短語描述強行穿過障礙物。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":5},{"front":"weakened landform","meaning":"受削弱的地貌","examples":[{"en":"The ocean broke through the weakened landform.","zh":"海洋衝破了受削弱的地貌。"},{"en":"A weakened landform is a natural land shape that has become easier to damage or erode.","zh":"weakened landform 指變得更容易受損或被侵蝕的天然地貌。"},{"en":"A sand dune becomes a weakened landform if plants are removed and vehicles drive over it.","zh":"如果植物被移除且車輛駛過，沙丘就會變成受削弱的地貌。"},{"en":"Once a landform is weakened, waves, wind, or rain can change it more quickly.","zh":"一旦地貌被削弱，海浪、風或雨可以更快改變它。"},{"en":"This phrase links physical damage with later environmental change.","zh":"這個短語把實體損害與之後的環境變化連繫起來。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":5},{"front":"naturally occurring sand islands","meaning":"天然形成的沙島","examples":[{"en":"Couran Cove is built on one of the world’s few naturally occurring sand islands.","zh":"Couran Cove 建於世界少數天然形成的沙島之一上。"},{"en":"Naturally occurring sand islands are islands formed by natural sand processes rather than by human construction.","zh":"naturally occurring sand islands 指由自然沙質過程形成，而不是由人類建造的島嶼。"},{"en":"A naturally occurring sand island may shift slowly as wind, waves, and currents move sand.","zh":"天然形成的沙島可能隨着風、海浪和洋流移動沙粒而慢慢變化。"},{"en":"Such islands can be fragile because sand is easier to erode than solid rock.","zh":"這類島嶼可能很脆弱，因為沙比堅硬岩石更容易被侵蝕。"},{"en":"This phrase describes rare island landforms created by nature.","zh":"這個短語描述由自然創造的罕見島嶼地貌。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":5},{"front":"support a wide range of","meaning":"支持多種……","examples":[{"en":"The island supports a wide range of plant communities.","zh":"該島支持多種植物群落。"},{"en":"To support a wide range of something means to provide conditions for many different types to live or exist.","zh":"support a wide range of something 指提供條件讓許多不同種類存在或生存。"},{"en":"A good library supports a wide range of learners by offering books, computers, and quiet rooms.","zh":"好圖書館透過提供書籍、電腦和安靜房間，支持多種學習者。"},{"en":"Diverse habitats can support a wide range of plants and animals.","zh":"多樣棲息地可以支持多種植物和動物。"},{"en":"This phrase highlights variety and the conditions that make it possible.","zh":"這個短語突出多樣性及令其可能存在的條件。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":6},{"front":"plant communities","meaning":"植物群落","examples":[{"en":"The island supports a wide range of plant communities.","zh":"該島支持多種植物群落。"},{"en":"Plant communities are groups of plant species that grow together in the same habitat.","zh":"plant communities 指在同一棲息地共同生長的植物物種群體。"},{"en":"A wetland plant community may include reeds, grasses, shrubs, and small trees.","zh":"濕地植物群落可能包括蘆葦、草、灌木和小樹。"},{"en":"Plant communities change when soil, water, light, or human activity changes.","zh":"當土壤、水、光或人類活動改變，植物群落也會改變。"},{"en":"This phrase refers to plants as an ecological group, not single plants alone.","zh":"這個短語指作為生態群體的植物，而不只是單株植物。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":6},{"front":"remaining remnants of","meaning":"……的殘存部分","examples":[{"en":"The island contains remaining remnants of rare rainforest.","zh":"該島包含罕見雨林的殘存部分。"},{"en":"Remaining remnants of something are the small parts still left after most of it has disappeared.","zh":"remaining remnants of something 指大部分消失後仍留下的小部分。"},{"en":"A city may have remaining remnants of old walls hidden between modern buildings.","zh":"城市可能在現代建築之間藏有舊城牆的殘存部分。"},{"en":"Remnants matter because they may be the last evidence of what once existed.","zh":"殘存部分很重要，因為它們可能是曾經存在事物的最後證據。"},{"en":"This phrase describes surviving pieces of something mostly lost.","zh":"這個短語描述大多已消失事物的倖存部分。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":6},{"front":"rare Livistona rainforest","meaning":"罕見的 Livistona 雨林","examples":[{"en":"The island contains rare Livistona rainforest.","zh":"該島包含罕見的 Livistona 雨林。"},{"en":"Rare Livistona rainforest is an uncommon type of rainforest associated with Livistona palms.","zh":"rare Livistona rainforest 指與 Livistona 棕櫚相關的不常見雨林類型。"},{"en":"A rare forest type should be protected because once destroyed, it may be difficult to restore.","zh":"罕見森林類型應被保護，因為一旦被破壞，可能難以恢復。"},{"en":"Rare ecosystems often contain species or conditions not found in ordinary forests.","zh":"罕見生態系統常包含普通森林沒有的物種或條件。"},{"en":"This phrase identifies a special rainforest community on the island.","zh":"這個短語指出島上一種特殊雨林群落。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":6},{"front":"mangrove and rainforest areas","meaning":"紅樹林和雨林地區","examples":[{"en":"Mangrove and rainforest areas were cleared for development.","zh":"紅樹林和雨林地區曾被清除作發展用途。"},{"en":"Mangrove and rainforest areas are habitats with coastal mangrove trees and dense tropical forest.","zh":"mangrove and rainforest areas 指有沿岸紅樹林和茂密熱帶森林的棲息地。"},{"en":"A coastal town may protect mangrove and rainforest areas because they support wildlife and reduce erosion.","zh":"沿海城鎮可能保護紅樹林和雨林地區，因為它們支持野生生物並減少侵蝕。"},{"en":"Clearing these areas can remove habitats and weaken natural protection from storms.","zh":"清除這些地區可以移除棲息地，並削弱對風暴的天然保護。"},{"en":"This phrase refers to two important natural habitats.","zh":"這個短語指兩種重要自然棲息地。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":6},{"front":"Melaleuca wetlands","meaning":"白千層濕地","examples":[{"en":"Melaleuca wetlands were cleared, drained or filled in Queensland.","zh":"昆士蘭的白千層濕地曾被清除、排水或填平。"},{"en":"Melaleuca wetlands are wetland areas where Melaleuca trees or related vegetation grow.","zh":"Melaleuca wetlands 指白千層樹或相關植被生長的濕地區域。"},{"en":"A wetland with paperbark trees may be part of a Melaleuca wetland ecosystem.","zh":"有紙皮樹的濕地可能屬於白千層濕地生態系統。"},{"en":"Draining wetlands can destroy habitat and reduce natural water storage.","zh":"排乾濕地可以破壞棲息地並減少天然儲水。"},{"en":"This phrase names a specific type of wetland habitat.","zh":"這個短語命名一種特定濕地棲息地。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":6},{"front":"be cleared, drained or filled","meaning":"被清除、排水或填平","examples":[{"en":"Many wetlands were cleared, drained or filled for development.","zh":"許多濕地曾為發展而被清除、排水或填平。"},{"en":"To be cleared, drained or filled means vegetation is removed, water is taken away, or land is covered with material.","zh":"be cleared, drained or filled 指植被被移除、水被排走，或土地被物料覆蓋。"},{"en":"A wet field may be drained and filled before builders construct houses.","zh":"建屋前，濕地可能被排水和填平。"},{"en":"These actions can destroy wetland habitats and change water movement.","zh":"這些行動可以破壞濕地棲息地並改變水流。"},{"en":"This phrase describes major human alteration of natural land.","zh":"這個短語描述人類對自然土地的重大改造。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":6},{"front":"residential development","meaning":"住宅發展","examples":[{"en":"Some wetland areas were cleared for residential development.","zh":"有些濕地地區曾被清除作住宅發展。"},{"en":"Residential development is building homes and housing areas.","zh":"residential development 指興建住宅和居住區。"},{"en":"A village may face residential development when farms are turned into apartment blocks.","zh":"當農田變成公寓大樓，村莊可能面對住宅發展。"},{"en":"Housing projects can provide homes but may also destroy habitats if badly planned.","zh":"住宅項目可以提供住房，但若規劃差劣，也可能破壞棲息地。"},{"en":"This phrase refers to development for people to live in.","zh":"這個短語指供人居住的發展。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":6},{"front":"industrial development","meaning":"工業發展","examples":[{"en":"Some areas were cleared for industrial development.","zh":"有些地區曾被清除作工業發展。"},{"en":"Industrial development is building factories, warehouses, ports, or other production facilities.","zh":"industrial development 指興建工廠、倉庫、港口或其他生產設施。"},{"en":"A town may support industrial development to create jobs.","zh":"城鎮可能支持工業發展以創造職位。"},{"en":"Industrial development can increase employment but may also create pollution if not controlled.","zh":"工業發展可以增加就業，但若不受控制，也可能造成污染。"},{"en":"This phrase refers to land use for industry and production.","zh":"這個短語指用於工業和生產的土地發展。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":6},{"front":"agricultural development","meaning":"農業發展","examples":[{"en":"Some land was cleared for agricultural development.","zh":"有些土地曾被清除作農業發展。"},{"en":"Agricultural development is changing land so it can be used for farming, crops, or livestock.","zh":"agricultural development 指改變土地，以便用於農耕、作物或畜牧。"},{"en":"A forest may be cleared for agricultural development if farmers need more fields.","zh":"如果農民需要更多田地，森林可能被清除作農業發展。"},{"en":"Agricultural development can increase food production but may damage ecosystems.","zh":"農業發展可以增加糧食生產，但也可能破壞生態系統。"},{"en":"This phrase refers to development for farming purposes.","zh":"這個短語指為農業目的而進行的發展。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":6},{"front":"urban development","meaning":"城市發展","examples":[{"en":"Wetlands were cleared for urban development.","zh":"濕地曾被清除作城市發展。"},{"en":"Urban development is the growth or construction of towns and cities.","zh":"urban development 指城鎮和城市的增長或建設。"},{"en":"New roads, apartments, offices, and shopping centres are part of urban development.","zh":"新道路、公寓、辦公室和商場都是城市發展的一部分。"},{"en":"Urban development can bring services and jobs but may reduce natural land.","zh":"城市發展可以帶來服務和職位，但可能減少天然土地。"},{"en":"This phrase describes city-related building and expansion.","zh":"這個短語描述與城市相關的建設和擴張。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":7},{"front":"first half of the 20th century","meaning":"20世紀上半葉","examples":[{"en":"Many wetlands were cleared during the first half of the 20th century.","zh":"許多濕地在 20 世紀上半葉被清除。"},{"en":"The first half of the 20th century means the years from 1901 to about 1950.","zh":"first half of the 20th century 指 1901 年至約 1950 年。"},{"en":"Many cities expanded quickly during the first half of the 20th century.","zh":"許多城市在 20 世紀上半葉快速擴展。"},{"en":"This phrase gives a historical period without listing every year.","zh":"這個短語給出歷史時期，而不列出每一年。"},{"en":"It is useful when discussing long-term social or environmental change.","zh":"它適合用於討論長期社會或環境變化。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":7},{"front":"farmers and graziers","meaning":"農民和牧民","examples":[{"en":"Farmers and graziers abandoned South Stradbroke Island in 1939.","zh":"農民和牧民在 1939 年放棄南斯特拉德布羅克島。"},{"en":"Farmers and graziers are people who grow crops or raise grazing animals such as cattle and sheep.","zh":"farmers and graziers 指種植作物或飼養牛羊等放牧動物的人。"},{"en":"Farmers and graziers need suitable soil, water, and pasture to make a living.","zh":"農民和牧民需要合適土壤、水源和牧草才能謀生。"},{"en":"If land cannot support crops or animals, farmers and graziers may leave it.","zh":"如果土地不能支持作物或牲畜，農民和牧民可能離開。"},{"en":"This phrase refers to agricultural workers using land for production.","zh":"這個短語指使用土地進行生產的農業工作者。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":7},{"front":"abandon","meaning":"放棄","examples":[{"en":"Farmers and graziers abandoned the island because farming was difficult.","zh":"農民和牧民因耕作困難而放棄該島。"},{"en":"To abandon something means to leave it behind or stop using it.","zh":"abandon something 指離開某物或停止使用它。"},{"en":"A shop owner may abandon a business plan if costs become too high.","zh":"如果成本變得太高，店主可能放棄商業計劃。"},{"en":"People abandon land when it no longer supports their work or survival.","zh":"當土地不再支持工作或生存，人們會放棄它。"},{"en":"This word suggests giving up because continuing is too difficult or not worthwhile.","zh":"這個詞表示因繼續太困難或不值得而放棄。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":7},{"front":"vegetation and soil conditions","meaning":"植被和土壤條件","examples":[{"en":"The island’s vegetation and soil conditions were unsuitable for agriculture.","zh":"該島的植被和土壤條件不適合農業。"},{"en":"Vegetation and soil conditions are the types of plants and soil quality found in an area.","zh":"vegetation and soil conditions 指某地的植物類型和土壤質素。"},{"en":"A farm needs good vegetation and soil conditions if crops are to grow well.","zh":"如果作物要生長良好，農場需要良好植被和土壤條件。"},{"en":"Poor soil or unsuitable plants can make farming difficult or impossible.","zh":"貧瘠土壤或不合適植物可以令耕作困難甚至不可能。"},{"en":"This phrase describes natural land features that affect land use.","zh":"這個短語描述影響土地用途的自然土地特徵。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":7},{"front":"be unsuitable for","meaning":"不適合……","examples":[{"en":"The soil conditions were unsuitable for agriculture.","zh":"土壤條件不適合農業。"},{"en":"To be unsuitable for something means not to be appropriate or useful for that purpose.","zh":"be unsuitable for something 指不適合或不能有效用於某目的。"},{"en":"A noisy room is unsuitable for an important listening exam.","zh":"嘈吵房間不適合重要聆聽考試。"},{"en":"If land is unsuitable for farming, crops may grow poorly or fail completely.","zh":"如果土地不適合耕作，作物可能生長不良或完全失收。"},{"en":"This phrase describes a mismatch between conditions and purpose.","zh":"這個短語描述條件與目的不匹配。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":7},{"front":"agriculture","meaning":"農業","examples":[{"en":"The island was unsuitable for agriculture.","zh":"該島不適合農業。"},{"en":"Agriculture is the work of growing crops and raising animals for food or other products.","zh":"agriculture 指種植作物和飼養動物，以生產食物或其他產品的工作。"},{"en":"A country with rich soil and enough rain may depend heavily on agriculture.","zh":"土壤肥沃且雨水充足的國家可能高度依賴農業。"},{"en":"Agriculture needs suitable land, water, labour, and knowledge.","zh":"農業需要合適土地、水源、勞力和知識。"},{"en":"This word refers to farming as an activity and industry.","zh":"這個詞指作為活動和產業的耕作。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":7},{"front":"sustainable practices","meaning":"可持續做法","examples":[{"en":"The passage describes the sustainable practices of Couran Cove Resort.","zh":"文章描述 Couran Cove Resort 的可持續做法。"},{"en":"Sustainable practices are ways of working that meet present needs without damaging future resources.","zh":"sustainable practices 指滿足現在需要而不破壞未來資源的工作方式。"},{"en":"A school uses sustainable practices when it saves paper, reduces electricity use, and recycles waste.","zh":"學校節省紙張、減少用電並回收廢物時，就是使用可持續做法。"},{"en":"Sustainable practices can lower costs and protect the environment over time.","zh":"可持續做法可以隨時間降低成本並保護環境。"},{"en":"This phrase refers to practical actions, not only environmental slogans.","zh":"這個短語指實際行動，而不只是環保口號。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":7},{"front":"offshore island","meaning":"離岸島嶼","examples":[{"en":"The resort is located on an offshore island.","zh":"該度假村位於離岸島嶼上。"},{"en":"An offshore island is an island near the coast but separated from the mainland by water.","zh":"offshore island 指靠近海岸但與本土由水分隔的島嶼。"},{"en":"A small offshore island may be reached only by ferry.","zh":"小型離岸島嶼可能只能乘渡輪到達。"},{"en":"Offshore islands often need careful planning for transport, waste, and emergency services.","zh":"離岸島嶼通常需要仔細規劃交通、廢物和緊急服務。"},{"en":"This phrase describes an island away from, but near, the coast.","zh":"這個短語描述離開海岸但仍接近海岸的島嶼。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":7},{"front":"accessible only by","meaning":"只能透過……到達","examples":[{"en":"The resort is accessible only by water transport.","zh":"該度假村只能透過水上交通到達。"},{"en":"Accessible only by something means people can reach the place only through that method.","zh":"accessible only by something 指人們只能透過某種方式到達該地。"},{"en":"A mountain village may be accessible only by a narrow road in winter.","zh":"冬天時，山村可能只能透過狹窄道路到達。"},{"en":"Limited access can make travel slower and emergency planning more important.","zh":"有限可達性可以令旅程較慢，並令緊急規劃更重要。"},{"en":"This phrase describes a restricted way of reaching a place.","zh":"這個短語描述到達某地的方式受限制。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":7},{"front":"water transport","meaning":"水上交通","examples":[{"en":"Visitors reach the resort by water transport.","zh":"遊客透過水上交通到達度假村。"},{"en":"Water transport is travel by boat, ferry, or other vessels across water.","zh":"water transport 指乘船、渡輪或其他船隻橫越水域的交通。"},{"en":"Island residents may depend on water transport for school, work, and shopping.","zh":"島民可能依賴水上交通上學、工作和購物。"},{"en":"If water transport stops because of bad weather, visitors may be unable to leave.","zh":"如果水上交通因惡劣天氣停止，遊客可能無法離開。"},{"en":"This phrase refers to transport that uses waterways rather than roads.","zh":"這個短語指使用水路而不是道路的交通。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":8},{"front":"hourly ferry service","meaning":"每小時一班的渡輪服務","examples":[{"en":"The resort provides an hourly ferry service.","zh":"度假村提供每小時一班的渡輪服務。"},{"en":"An hourly ferry service is a boat service that runs once every hour.","zh":"hourly ferry service 指每小時開出一次的船隻服務。"},{"en":"A student can plan a day trip more easily if the island has an hourly ferry service.","zh":"如果島上有每小時一班的渡輪服務，學生較容易規劃一日遊。"},{"en":"Regular ferries improve access because visitors do not have to wait all day.","zh":"定期渡輪改善交通可達性，因為遊客不用等一整天。"},{"en":"This phrase describes a frequent scheduled boat connection.","zh":"這個短語描述頻密而有時間表的船隻連接。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":8},{"front":"mainland marina","meaning":"本土遊艇碼頭","examples":[{"en":"The ferry travels between the mainland marina and the island.","zh":"渡輪往返本土遊艇碼頭和島嶼。"},{"en":"A mainland marina is a harbour area on the main land where boats are kept or boarded.","zh":"mainland marina 指位於本土、供船隻停泊或上船的港口區域。"},{"en":"Visitors may park their cars at the mainland marina before taking a ferry.","zh":"遊客乘渡輪前，可能把車停在本土遊艇碼頭。"},{"en":"A marina is important for island tourism because it connects land transport with water transport.","zh":"遊艇碼頭對島嶼旅遊很重要，因為它連接陸上交通和水上交通。"},{"en":"This phrase refers to the boat facility on the mainland side.","zh":"這個短語指本土一側的船隻設施。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":8},{"front":"transport options","meaning":"交通選項","examples":[{"en":"Transport options within the resort include walking trails and bicycles.","zh":"度假村內的交通選項包括步行徑和單車。"},{"en":"Transport options are the different ways people can move from one place to another.","zh":"transport options 指人們從一處到另一處的不同移動方式。"},{"en":"A university campus may offer transport options such as buses, bikes, and walking paths.","zh":"大學校園可能提供巴士、單車和步行路徑等交通選項。"},{"en":"More transport options can make a place easier to use and reduce dependence on cars.","zh":"更多交通選項可以令地方更方便使用，並減少對汽車依賴。"},{"en":"This phrase refers to available travel choices.","zh":"這個短語指可用的出行選擇。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":8},{"front":"walking trails","meaning":"步行徑","examples":[{"en":"Guests can use walking trails within the resort.","zh":"客人可以使用度假村內的步行徑。"},{"en":"Walking trails are paths designed for people to walk along, often through natural areas.","zh":"walking trails 指供人步行的路徑，通常穿過自然區域。"},{"en":"A park with clear walking trails helps visitors enjoy nature without damaging plants.","zh":"有清楚步行徑的公園可以幫助遊客享受自然，同時不破壞植物。"},{"en":"Walking trails can reduce the need for vehicles inside a resort.","zh":"步行徑可以減少度假村內對車輛的需要。"},{"en":"This phrase refers to planned footpaths for safe walking.","zh":"這個短語指為安全步行而規劃的行人路徑。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":8},{"front":"bicycle tracks","meaning":"單車徑","examples":[{"en":"The resort has bicycle tracks for visitors.","zh":"度假村有供遊客使用的單車徑。"},{"en":"Bicycle tracks are paths or lanes made for people riding bicycles.","zh":"bicycle tracks 指為騎單車者而設的路徑或車道。"},{"en":"A town with safe bicycle tracks encourages children to cycle to school.","zh":"有安全單車徑的城鎮會鼓勵孩子騎單車上學。"},{"en":"Bicycle tracks can reduce car use and make transport quieter and cleaner.","zh":"單車徑可以減少汽車使用，令交通更安靜和清潔。"},{"en":"This phrase refers to routes designed for bicycles.","zh":"這個短語指為單車設計的路線。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":8},{"front":"beach train","meaning":"海灘小火車","examples":[{"en":"The beach train is one transport option within the resort.","zh":"海灘小火車是度假村內的一種交通選項。"},{"en":"A beach train is a small train-like vehicle that carries guests around beach or resort areas.","zh":"beach train 指在海灘或度假村地區載客的小型火車式車輛。"},{"en":"Families may use a beach train when children are too tired to walk across a large resort.","zh":"當孩子太累，無法走完整個大型度假村時，家庭可能使用海灘小火車。"},{"en":"A shared beach train can reduce the number of private vehicles inside the resort.","zh":"共用海灘小火車可以減少度假村內私人車輛數量。"},{"en":"This phrase describes a visitor transport service, not a railway for long-distance travel.","zh":"這個短語描述遊客服務交通，而不是長途鐵路。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":8},{"front":"reception area","meaning":"接待處","examples":[{"en":"The reception area is a counter in the shop.","zh":"接待處是商店內的一個櫃台。"},{"en":"A reception area is the place where visitors check in, ask questions, or receive help.","zh":"reception area 指遊客登記入住、詢問問題或獲得協助的地方。"},{"en":"At a hotel, guests go to the reception area to collect room keys.","zh":"在酒店，客人到接待處領取房間鎖匙。"},{"en":"A clear reception area helps visitors know where to get information when they arrive.","zh":"清楚的接待處幫助遊客到達時知道去哪裡取得資訊。"},{"en":"This phrase refers to the first service point for guests.","zh":"這個短語指客人的第一個服務點。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":8},{"front":"consist of","meaning":"由……組成","examples":[{"en":"The accommodation consists of octagonal rooms called bures.","zh":"住宿由稱為 bures 的八角形房間組成。"},{"en":"To consist of something means to be made up of those parts.","zh":"consist of something 指由那些部分構成。"},{"en":"A simple lunch may consist of rice, vegetables, and soup.","zh":"簡單午餐可能由飯、蔬菜和湯組成。"},{"en":"Describing what something consists of helps readers understand its structure.","zh":"描述某物由甚麼組成，可以幫助讀者理解其結構。"},{"en":"This phrase is used to list the parts that form a whole.","zh":"這個短語用於列出構成整體的部分。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":8},{"front":"octagonal rooms","meaning":"八角形房間","examples":[{"en":"The accommodation consists of octagonal rooms.","zh":"住宿由八角形房間組成。"},{"en":"Octagonal rooms are rooms with eight sides or an eight-sided shape.","zh":"octagonal rooms 指有八邊或八角形形狀的房間。"},{"en":"An octagonal classroom may feel unusual because most rooms are square or rectangular.","zh":"八角形課室可能感覺不尋常，因為大多數房間是正方形或長方形。"},{"en":"Room shape can affect furniture arrangement and how spacious a room feels.","zh":"房間形狀可以影響家具擺放和空間感。"},{"en":"This phrase describes the physical shape of the rooms.","zh":"這個短語描述房間的實體形狀。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":8},{"front":"bures","meaning":"bures；小屋式客房","examples":[{"en":"The octagonal rooms at the resort are called bures.","zh":"度假村的八角形房間稱為 bures。"},{"en":"Bures are small hut-like guest rooms or cabins used for accommodation.","zh":"bures 指用作住宿的小屋式客房或小木屋。"},{"en":"A family may stay in a bure instead of a hotel tower if they want a quieter holiday.","zh":"如果家庭想要較安靜假期，可能入住小屋式客房，而不是酒店大樓。"},{"en":"Bures can make a resort feel more informal and closer to nature.","zh":"bures 可以令度假村感覺較輕鬆，並更接近自然。"},{"en":"This word names the resort’s small individual lodging units.","zh":"這個詞命名度假村的小型獨立住宿單位。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":9},{"front":"equipment is tired","meaning":"設備殘舊","examples":[{"en":"The equipment is tired and only just working in some cases.","zh":"設備殘舊，有些情況下僅僅能運作。"},{"en":"Equipment is tired means the machines or facilities are old, worn out, and not working well.","zh":"equipment is tired 指機器或設施老舊、磨損，運作不佳。"},{"en":"A classroom projector is tired if the image is dim and the buttons often fail.","zh":"如果課室投影機影像昏暗且按鈕常失靈，就是設備殘舊。"},{"en":"Tired equipment can frustrate guests because basic services feel unreliable.","zh":"殘舊設備會令客人感到沮喪，因為基本服務不可靠。"},{"en":"This phrase is informal and describes equipment that needs repair or replacement.","zh":"這個短語較口語，描述需要維修或更換的設備。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":9},{"front":"only just working","meaning":"僅僅能運作","examples":[{"en":"Some equipment is only just working.","zh":"有些設備僅僅能運作。"},{"en":"Only just working means functioning barely well enough, but close to failing.","zh":"only just working 指勉強能運作，但接近故障。"},{"en":"An old printer is only just working if it prints slowly and jams every few pages.","zh":"如果舊打印機打印很慢，且每幾頁就卡紙，就是僅僅能運作。"},{"en":"Equipment that is only just working can break down at inconvenient times.","zh":"僅僅能運作的設備可能在不方便的時候壞掉。"},{"en":"This phrase suggests weak performance, not reliable condition.","zh":"這個短語表示性能很弱，而不是狀態可靠。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":9},{"front":"ceiling fan","meaning":"天花風扇","examples":[{"en":"The ceiling fan worked only at high speed.","zh":"天花風扇只能以高速運作。"},{"en":"A ceiling fan is a fan fixed to the ceiling to move air around a room.","zh":"ceiling fan 指固定在天花板上、用來令房間空氣流動的風扇。"},{"en":"A ceiling fan can help a bedroom feel cooler without using much electricity.","zh":"天花風扇可以在不用太多電力的情況下令睡房較涼快。"},{"en":"If a ceiling fan has only one working speed, guests cannot adjust comfort properly.","zh":"如果天花風扇只有一個可用速度，客人就不能妥善調節舒適度。"},{"en":"This phrase refers to a fan above people’s heads.","zh":"這個短語指人頭頂上的風扇。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":9},{"front":"high speed","meaning":"高速","examples":[{"en":"The ceiling fan worked only at high speed.","zh":"天花風扇只能以高速運作。"},{"en":"High speed means a fast setting or fast movement.","zh":"high speed 指快速設定或快速移動。"},{"en":"A blender uses high speed when it needs to crush ice quickly.","zh":"攪拌機需要快速打碎冰時會使用高速。"},{"en":"High speed can be useful, but it may also be noisy or uncomfortable.","zh":"高速可以有用，但也可能嘈吵或令人不舒服。"},{"en":"This phrase describes a fast operating level.","zh":"這個短語描述快速運作水平。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":9},{"front":"hard but clean","meaning":"硬但乾淨","examples":[{"en":"The beds are hard but clean.","zh":"床硬但乾淨。"},{"en":"Hard but clean means uncomfortable in firmness but hygienic and not dirty.","zh":"hard but clean 指硬度令人不舒服，但衛生且不骯髒。"},{"en":"A hostel bed may be hard but clean, so guests accept it for a short stay.","zh":"青年旅舍的床可能硬但乾淨，所以客人短住時可以接受。"},{"en":"Cleanliness can partly compensate for discomfort, but it does not make the bed soft.","zh":"乾淨可以部分彌補不適，但不會令床變軟。"},{"en":"This phrase gives a mixed evaluation: one negative point and one positive point.","zh":"這個短語給出混合評價：一個缺點和一個優點。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":9},{"front":"air conditioner","meaning":"冷氣機","examples":[{"en":"Each room has an old air conditioner.","zh":"每間房都有一部舊冷氣機。"},{"en":"An air conditioner is a machine that cools and sometimes dries indoor air.","zh":"air conditioner 指冷卻並有時抽乾室內空氣的機器。"},{"en":"A classroom uses an air conditioner to keep students comfortable in hot weather.","zh":"課室在炎熱天氣使用冷氣機，令學生保持舒適。"},{"en":"Old air conditioners may use more energy than newer models.","zh":"舊冷氣機可能比新型號耗用更多能源。"},{"en":"This phrase refers to cooling equipment inside a room or building.","zh":"這個短語指房間或建築物內的冷卻設備。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":9},{"front":"small refrigerator","meaning":"小雪櫃","examples":[{"en":"Each room has a small refrigerator.","zh":"每間房都有一部小雪櫃。"},{"en":"A small refrigerator is a compact fridge used to keep food and drinks cold.","zh":"small refrigerator 指用來冷藏食物和飲品的小型冰箱。"},{"en":"A hotel room may have a small refrigerator for milk, fruit, and bottled water.","zh":"酒店房間可能有小雪櫃，用來放牛奶、水果和樽裝水。"},{"en":"A small refrigerator is convenient, but it still uses electricity.","zh":"小雪櫃很方便，但仍會耗電。"},{"en":"This phrase refers to a small cooling appliance for storage.","zh":"這個短語指小型冷藏電器。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":9},{"front":"very close together","meaning":"靠得很近","examples":[{"en":"The bures are very close together.","zh":"這些小屋式客房靠得很近。"},{"en":"Very close together means with little space between one thing and another.","zh":"very close together 指兩件事物之間空間很少。"},{"en":"Desks placed very close together can make a classroom feel crowded.","zh":"書桌靠得很近會令課室感覺擠迫。"},{"en":"Buildings that are very close together may reduce privacy and increase noise.","zh":"建築物靠得很近可能減少私隱並增加噪音。"},{"en":"This phrase describes short distance between objects or places.","zh":"這個短語描述物件或地方之間距離很短。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":9},{"front":"noise carries","meaning":"聲音傳得遠","examples":[{"en":"Noise carries at night between the bures.","zh":"晚上聲音會在小屋式客房之間傳得很遠。"},{"en":"Noise carries means sound travels farther or more clearly than expected.","zh":"noise carries 指聲音比預期傳得更遠或更清楚。"},{"en":"In a quiet apartment block, voices carry through thin walls.","zh":"在安靜公寓大樓中，說話聲會透過薄牆傳開。"},{"en":"Noise carries more at night because there is less background sound.","zh":"晚上聲音傳得更遠，因為背景聲音較少。"},{"en":"This phrase warns that other people may hear what you say or do.","zh":"這個短語提醒你其他人可能聽到你說甚麼或做甚麼。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":9},{"front":"be careful what you say and do","meaning":"小心自己的言行","examples":[{"en":"Guests should be careful what they say and do at night.","zh":"客人晚上應小心自己的言行。"},{"en":"To be careful what you say and do means to act and speak with caution because others may notice.","zh":"be careful what you say and do 指因別人可能注意到而謹慎說話和行動。"},{"en":"Students should be careful what they say and do online because posts can spread quickly.","zh":"學生應小心自己在網上的言行，因為貼文可以快速傳播。"},{"en":"If walls are thin, careless comments can be heard by neighbours.","zh":"如果牆很薄，粗心言論可能被鄰居聽到。"},{"en":"This phrase is a warning about privacy, manners, or consequences.","zh":"這個短語是關於私隱、禮貌或後果的提醒。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":10},{"front":"mosquito repellent","meaning":"驅蚊劑","examples":[{"en":"Mosquito repellent is sold on the island.","zh":"島上有售驅蚊劑。"},{"en":"Mosquito repellent is a spray, lotion, or product used to keep mosquitoes away.","zh":"mosquito repellent 指用來驅趕蚊子的噴霧、乳液或產品。"},{"en":"Campers often bring mosquito repellent when they sleep near lakes or forests.","zh":"露營者在湖邊或森林附近睡覺時，常帶備驅蚊劑。"},{"en":"Using repellent can reduce mosquito bites and make outdoor activities more comfortable.","zh":"使用驅蚊劑可以減少蚊叮，令戶外活動更舒服。"},{"en":"This phrase refers to protection against mosquitoes.","zh":"這個短語指防蚊用品。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":10},{"front":"as an ecotourism-based resort","meaning":"作為以生態旅遊為本的度假村","examples":[{"en":"As an ecotourism-based resort, Couran Cove focuses on sustainability.","zh":"作為以生態旅遊為本的度假村，Couran Cove 著重可持續性。"},{"en":"As an ecotourism-based resort means because the resort is built around ecotourism principles.","zh":"as an ecotourism-based resort 指因該度假村圍繞生態旅遊原則而建立。"},{"en":"As a school, an institution must care about learning, safety, and student development.","zh":"作為學校，機構必須關心學習、安全和學生發展。"},{"en":"This phrase explains that a role or identity creates certain responsibilities.","zh":"這個短語解釋某種角色或身份會帶來某些責任。"},{"en":"It shows why the resort should care about environmental performance.","zh":"它顯示為何度假村應重視環境表現。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":10},{"front":"planning and development","meaning":"規劃和發展","examples":[{"en":"Most planning and development has focused on the natural environment.","zh":"大部分規劃和發展都集中於自然環境。"},{"en":"Planning and development means designing, building, and organising how a place will be used.","zh":"planning and development 指設計、建設和組織某地如何被使用。"},{"en":"City planning and development decide where homes, roads, parks, and shops should go.","zh":"城市規劃和發展決定住宅、道路、公園和商店應設在哪裡。"},{"en":"Good planning can prevent problems before construction begins.","zh":"良好規劃可以在施工開始前防止問題。"},{"en":"This phrase covers both ideas on paper and actual building work.","zh":"這個短語涵蓋紙上構想和實際建設工作。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":10},{"front":"focus on the need to","meaning":"集中於……的需要","examples":[{"en":"Planning has focused on the need to coexist with the environment.","zh":"規劃集中於與環境共存的需要。"},{"en":"To focus on the need to do something means to pay attention to why that action is necessary.","zh":"focus on the need to do something 指注意為何某行動是必要的。"},{"en":"A school may focus on the need to reduce screen time if students are always tired.","zh":"如果學生總是疲倦，學校可能集中於減少螢幕時間的需要。"},{"en":"Focusing on a need helps planners set priorities and choose suitable actions.","zh":"集中於某種需要可以幫助規劃者設定優先事項並選擇合適行動。"},{"en":"This phrase connects attention with an important requirement.","zh":"這個短語把注意力與重要要求連繫起來。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":10},{"front":"coexist with","meaning":"與……共存","examples":[{"en":"The resort aims to coexist with the island’s fragile natural environment.","zh":"該度假村旨在與島上脆弱的自然環境共存。"},{"en":"To coexist with something means to live or operate together without destroying it.","zh":"coexist with something 指與某物共同存在或運作，而不摧毀它。"},{"en":"A farm can coexist with wildlife if it leaves trees, ponds, and safe nesting areas.","zh":"如果農場保留樹木、池塘和安全築巢區，就可以與野生生物共存。"},{"en":"Coexistence requires limits because human activity can easily damage natural systems.","zh":"共存需要限制，因為人類活動很容易破壞自然系統。"},{"en":"This phrase suggests balance rather than domination.","zh":"這個短語表示平衡，而不是支配。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":10},{"front":"fragile natural environment","meaning":"脆弱的自然環境","examples":[{"en":"South Stradbroke Island has a fragile natural environment.","zh":"南斯特拉德布羅克島有脆弱的自然環境。"},{"en":"A fragile natural environment is an ecosystem that can be easily damaged.","zh":"fragile natural environment 指容易受破壞的生態系統。"},{"en":"Coral reefs are fragile natural environments because small changes in temperature or pollution can harm them.","zh":"珊瑚礁是脆弱的自然環境，因為溫度或污染的小變化都可以傷害它們。"},{"en":"Fragile environments need careful visitor controls and low-impact development.","zh":"脆弱環境需要謹慎遊客管制和低影響發展。"},{"en":"This phrase warns that the area cannot absorb unlimited human pressure.","zh":"這個短語提醒該地區不能承受無限人類壓力。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":10},{"front":"achieve sustainable development","meaning":"實現可持續發展","examples":[{"en":"The resort aims to achieve sustainable development.","zh":"該度假村旨在實現可持續發展。"},{"en":"To achieve sustainable development means to grow or build in a way that protects future resources.","zh":"achieve sustainable development 指以保護未來資源的方式增長或建設。"},{"en":"A town achieves sustainable development when it adds homes while protecting parks and water supplies.","zh":"城鎮在增加住宅同時保護公園和水源時，就是實現可持續發展。"},{"en":"Sustainable development balances economic growth, social needs, and environmental protection.","zh":"可持續發展平衡經濟增長、社會需要和環境保護。"},{"en":"This phrase describes development that can continue without destroying its own foundations.","zh":"這個短語描述不破壞自身基礎而能延續的發展。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":10},{"front":"water and energy management","meaning":"水和能源管理","examples":[{"en":"The resort has policies for water and energy management.","zh":"該度假村有水和能源管理政策。"},{"en":"Water and energy management means controlling how water and power are obtained, used, saved, and monitored.","zh":"water and energy management 指控制水和電力如何取得、使用、節省和監察。"},{"en":"A school improves water and energy management by fixing leaks and turning off unused lights.","zh":"學校透過維修漏水和關掉不用的燈來改善水和能源管理。"},{"en":"Good management reduces waste and lowers environmental impact.","zh":"良好管理可以減少浪費並降低環境影響。"},{"en":"This phrase refers to organised control of two key resources.","zh":"這個短語指對兩種關鍵資源的有組織控制。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":10},{"front":"groundwater","meaning":"地下水","examples":[{"en":"South Stradbroke Island has groundwater at its centre.","zh":"南斯特拉德布羅克島中心有地下水。"},{"en":"Groundwater is water stored beneath the ground in soil or rock.","zh":"groundwater 指儲存在地下土壤或岩石中的水。"},{"en":"A village may pump groundwater from wells during dry months.","zh":"村莊可能在乾旱月份從水井抽取地下水。"},{"en":"Groundwater can be polluted if chemicals or waste seep into the soil.","zh":"如果化學品或廢物滲入土壤，地下水可能被污染。"},{"en":"This word refers to hidden water below the surface.","zh":"這個詞指地表以下的隱藏水源。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":10},{"front":"at its centre","meaning":"在其中心","examples":[{"en":"The island has groundwater at its centre.","zh":"該島在其中心有地下水。"},{"en":"At its centre means in the middle or central part of something.","zh":"at its centre 指在某物的中間或中心部分。"},{"en":"A town may have a public square at its centre.","zh":"城鎮可能在其中心有一個公共廣場。"},{"en":"The centre of an island can be important because water or vegetation may collect there.","zh":"島的中心可能很重要，因為水或植被可能在那裡聚集。"},{"en":"This phrase gives an internal location within a place or object.","zh":"這個短語給出地方或物件內部的位置。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":11},{"front":"above sea level","meaning":"海拔以上","examples":[{"en":"The groundwater reaches three metres above sea level.","zh":"地下水達到海拔以上三米。"},{"en":"Above sea level means higher than the average level of the sea.","zh":"above sea level 指高於平均海平面。"},{"en":"A mountain village may sit 800 metres above sea level.","zh":"山村可能位於海拔以上八百米。"},{"en":"Height above sea level affects temperature, flooding risk, and water movement.","zh":"海拔高度會影響溫度、水災風險和水流。"},{"en":"This phrase is used to measure elevation.","zh":"這個短語用於量度海拔高度。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":11},{"front":"be recharged by rainfall","meaning":"由降雨補充","examples":[{"en":"The freshwater supply is recharged by rainfall.","zh":"淡水供應由降雨補充。"},{"en":"To be recharged by rainfall means to be refilled when rainwater soaks into the ground.","zh":"be recharged by rainfall 指雨水滲入地下後重新補充水源。"},{"en":"A well can be recharged by rainfall after several wet weeks.","zh":"連續幾星期下雨後，水井可以由降雨補充。"},{"en":"If rainfall is low, groundwater may not be recharged quickly enough.","zh":"如果降雨少，地下水可能不能足夠快地得到補充。"},{"en":"This phrase describes natural refilling of water reserves.","zh":"這個短語描述水儲備的自然補充。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":11},{"front":"commonly known as","meaning":"通常稱為","examples":[{"en":"The water supply is commonly known as an unconfined freshwater aquifer.","zh":"這種水源通常稱為非承壓淡水含水層。"},{"en":"Commonly known as means usually called by a particular name.","zh":"commonly known as 指通常被稱為某個名稱。"},{"en":"Hong Kong’s Mass Transit Railway is commonly known as the MTR.","zh":"香港的地下鐵路通常稱為 MTR。"},{"en":"This phrase introduces a familiar or technical name for something.","zh":"這個短語引入某事物的常用名稱或專門名稱。"},{"en":"It helps readers connect an explanation with the name people use.","zh":"它幫助讀者把解釋與人們使用的名稱連繫起來。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":11},{"front":"unconfined freshwater aquifer","meaning":"非承壓淡水含水層","examples":[{"en":"The island’s water supply is an unconfined freshwater aquifer.","zh":"該島的水源是一個非承壓淡水含水層。"},{"en":"An unconfined freshwater aquifer is an underground store of fresh water not sealed under a solid confining layer.","zh":"unconfined freshwater aquifer 指沒有被堅固隔水層封住的地下淡水儲存層。"},{"en":"A shallow island aquifer may be recharged when rainwater filters down through sand.","zh":"淺層島嶼含水層可以在雨水穿過沙層滲下時得到補充。"},{"en":"Such aquifers are vulnerable because pollution can enter them from the surface.","zh":"這類含水層很脆弱，因為污染物可以從地表進入。"},{"en":"This phrase names a specific underground freshwater system.","zh":"這個短語命名一種特定地下淡水系統。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":11},{"front":"obtain water by","meaning":"透過……取得水","examples":[{"en":"The resort obtains its water by tapping the aquifer.","zh":"該度假村透過開採含水層取得水。"},{"en":"To obtain water by doing something means to get water through that method.","zh":"obtain water by doing something 指透過某種方法取得水。"},{"en":"A village may obtain water by collecting rain in tanks.","zh":"村莊可能透過水箱收集雨水取得水。"},{"en":"How a place obtains water affects cost, safety, and sustainability.","zh":"一個地方如何取得水會影響成本、安全和可持續性。"},{"en":"This phrase explains the method used to get water.","zh":"這個短語解釋取水的方法。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":11},{"front":"tap an aquifer","meaning":"開採含水層","examples":[{"en":"The resort taps the aquifer through a bore system.","zh":"度假村透過鑽孔取水系統開採含水層。"},{"en":"To tap an aquifer means to access underground water and draw it out for use.","zh":"tap an aquifer 指取得地下水並抽出使用。"},{"en":"A farm may tap an aquifer with a well during a dry season.","zh":"農場可能在旱季用水井開採含水層。"},{"en":"Tapping an aquifer too heavily can reduce the water supply over time.","zh":"過度開採含水層會隨時間減少水源。"},{"en":"This phrase describes using underground water resources.","zh":"這個短語描述使用地下水資源。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":11},{"front":"bore system","meaning":"鑽孔取水系統","examples":[{"en":"The resort uses a bore system to obtain groundwater.","zh":"度假村使用鑽孔取水系統取得地下水。"},{"en":"A bore system is a set of drilled holes and equipment used to draw water from underground.","zh":"bore system 指用來從地下抽水的一套鑽孔和設備。"},{"en":"A rural school may use a bore system if there is no town water supply.","zh":"如果沒有城市供水，鄉村學校可能使用鑽孔取水系統。"},{"en":"Bore systems need monitoring because overuse can lower groundwater levels.","zh":"鑽孔取水系統需要監察，因為過度使用可以降低地下水位。"},{"en":"This phrase refers to drilled groundwater access.","zh":"這個短語指透過鑽孔取得地下水。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":11},{"front":"threats to","meaning":"對……的威脅","examples":[{"en":"Threats to the island’s freshwater supply include pollution and overconsumption.","zh":"對該島淡水供應的威脅包括污染和過度消耗。"},{"en":"Threats to something are dangers that may harm or weaken it.","zh":"threats to something 指可能傷害或削弱某事物的危險。"},{"en":"Threats to a school’s safety may include broken gates and poor lighting.","zh":"對學校安全的威脅可能包括破損閘門和照明不足。"},{"en":"Identifying threats helps people prevent damage before it happens.","zh":"識別威脅可以幫助人們在損害發生前預防。"},{"en":"This phrase introduces risks that need management.","zh":"這個短語引入需要管理的風險。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":11},{"front":"freshwater supply","meaning":"淡水供應","examples":[{"en":"The island’s freshwater supply is vulnerable to pollution.","zh":"該島的淡水供應容易受污染影響。"},{"en":"A freshwater supply is the available water that is not salty and can be used for drinking, washing, or other needs.","zh":"freshwater supply 指可用於飲用、清洗或其他需要的非鹹水水源。"},{"en":"A small island may depend on rainfall for its freshwater supply.","zh":"小島可能依賴降雨作為淡水供應。"},{"en":"If freshwater supply is polluted, residents and guests may need imported water.","zh":"如果淡水供應被污染，居民和客人可能需要入口水。"},{"en":"This phrase refers to usable non-salt water.","zh":"這個短語指可用的非鹹水。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":11},{"front":"pollution and contamination","meaning":"污染和沾污","examples":[{"en":"Pollution and contamination threaten the freshwater supply.","zh":"污染和沾污威脅淡水供應。"},{"en":"Pollution and contamination mean harmful substances entering air, water, soil, or food.","zh":"pollution and contamination 指有害物質進入空氣、水、土壤或食物。"},{"en":"A leaking fuel tank can cause pollution and contamination in groundwater.","zh":"漏油油缸可以造成地下水污染和沾污。"},{"en":"Contaminated water may be unsafe to drink or use.","zh":"受污染的水可能不安全，不能飲用或使用。"},{"en":"This phrase describes environmental harm caused by unwanted substances.","zh":"這個短語描述由不需要的物質造成的環境傷害。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":12},{"front":"overconsumption","meaning":"過度消耗","examples":[{"en":"Overconsumption is a threat to the island’s freshwater supply.","zh":"過度消耗是對該島淡水供應的威脅。"},{"en":"Overconsumption means using too much of a resource.","zh":"overconsumption 指使用過多資源。"},{"en":"A family may reduce overconsumption by turning off lights and taking shorter showers.","zh":"家庭可以透過關燈和縮短淋浴時間來減少過度消耗。"},{"en":"Overconsumption can drain limited resources faster than nature can replace them.","zh":"過度消耗可以令有限資源被消耗得快過自然補充。"},{"en":"This word warns that too much use can create shortage.","zh":"這個詞提醒過度使用可以造成短缺。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":12},{"front":"minimise problems","meaning":"減少問題","examples":[{"en":"The resort takes steps to minimise water and pollution problems.","zh":"度假村採取措施減少用水和污染問題。"},{"en":"To minimise problems means to reduce them as much as possible.","zh":"minimise problems 指盡可能減少問題。"},{"en":"A teacher can minimise classroom problems by setting clear rules from the start.","zh":"老師可以從一開始設定清楚規則，以減少課室問題。"},{"en":"Early action can minimise problems before they become expensive or dangerous.","zh":"及早行動可以在問題變得昂貴或危險前減少它們。"},{"en":"This phrase means reducing harm, not necessarily removing every problem completely.","zh":"這個短語意思是減少傷害，而不一定完全消除所有問題。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":12},{"front":"all laundry is done","meaning":"所有洗衣工作都進行","examples":[{"en":"All laundry is done on the mainland.","zh":"所有洗衣工作都在本土進行。"},{"en":"All laundry is done means all washing of clothes, sheets, and towels is carried out.","zh":"all laundry is done 指所有衣物、床單和毛巾的清洗工作都被完成。"},{"en":"In a small hostel, all laundry may be done in a separate building to save space.","zh":"在小型旅舍中，所有洗衣工作可能在另一棟建築物進行，以節省空間。"},{"en":"Moving laundry off an island can reduce water use and pollution there.","zh":"把洗衣工作移離島嶼，可以減少當地用水和污染。"},{"en":"This phrase describes where washing work is completed.","zh":"這個短語描述清洗工作在哪裡完成。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":12},{"front":"place a heavy burden on","meaning":"對……造成沉重負擔","examples":[{"en":"Washing machines would place a heavy burden on the freshwater supply.","zh":"洗衣機會對淡水供應造成沉重負擔。"},{"en":"To place a heavy burden on something means to create serious pressure or demand on it.","zh":"place a heavy burden on something 指對某事物造成嚴重壓力或需求。"},{"en":"Too many patients can place a heavy burden on a small clinic.","zh":"太多病人可以對小診所造成沉重負擔。"},{"en":"Heavy demand on limited water can cause shortages and environmental stress.","zh":"對有限水源的巨大需求可以造成短缺和環境壓力。"},{"en":"This phrase shows that a system may struggle under too much pressure.","zh":"這個短語顯示系統在過大壓力下可能難以承受。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":12},{"front":"detergents","meaning":"洗衣劑；清潔劑","examples":[{"en":"Detergents contain high levels of phosphates.","zh":"清潔劑含有高含量磷酸鹽。"},{"en":"Detergents are cleaning products used to wash clothes, dishes, or surfaces.","zh":"detergents 指用來清洗衣物、碗碟或表面的清潔產品。"},{"en":"A family uses detergent when washing school uniforms in a washing machine.","zh":"家庭用洗衣機清洗校服時會使用洗衣劑。"},{"en":"Some detergents can pollute water if chemicals enter rivers or groundwater.","zh":"如果化學物質進入河流或地下水，有些清潔劑可以污染水源。"},{"en":"This word refers to cleaning substances, not just soap bars.","zh":"這個詞指清潔物質，而不只是肥皂。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":12},{"front":"high levels of","meaning":"高含量的……","examples":[{"en":"Detergents contain high levels of phosphates.","zh":"清潔劑含有高含量的磷酸鹽。"},{"en":"High levels of something means a large amount or concentration of it.","zh":"high levels of something 指某物的大量或高濃度。"},{"en":"High levels of sugar in drinks can be unhealthy if consumed every day.","zh":"飲品中高含量糖分若每日攝取，可能不健康。"},{"en":"High chemical levels in water can harm plants, animals, and people.","zh":"水中高含量化學物質可以傷害植物、動物和人類。"},{"en":"This phrase often warns that the amount may be excessive.","zh":"這個短語常提醒某含量可能過高。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":12},{"front":"phosphates","meaning":"磷酸鹽","examples":[{"en":"Phosphates are a major source of water pollution.","zh":"磷酸鹽是水污染的主要來源。"},{"en":"Phosphates are chemical compounds often found in fertilisers and some detergents.","zh":"phosphates 指常見於肥料和某些清潔劑中的化合物。"},{"en":"Too many phosphates in a pond can cause excessive algae growth.","zh":"池塘中太多磷酸鹽可以導致藻類過度生長。"},{"en":"Phosphate pollution can reduce water quality and harm aquatic life.","zh":"磷酸鹽污染可以降低水質並傷害水生生物。"},{"en":"This word refers to chemicals that can become pollutants in water.","zh":"這個詞指在水中可能成為污染物的化學物質。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":12},{"front":"major source of","meaning":"……的主要來源","examples":[{"en":"Phosphates are a major source of water pollution.","zh":"磷酸鹽是水污染的主要來源。"},{"en":"A major source of something is one of the main causes or suppliers of it.","zh":"major source of something 指某事物的主要原因或供應來源之一。"},{"en":"Cars are a major source of air pollution in many cities.","zh":"汽車是許多城市空氣污染的主要來源。"},{"en":"Identifying a major source helps people solve a problem more directly.","zh":"識別主要來源可以幫助人更直接解決問題。"},{"en":"This phrase points to an important cause.","zh":"這個短語指出重要原因。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":12},{"front":"LPG-powered generation","meaning":"石油氣發電","examples":[{"en":"The resort uses LPG-powered generation rather than diesel.","zh":"度假村使用石油氣發電，而不是柴油。"},{"en":"LPG-powered generation means producing electricity using liquefied petroleum gas.","zh":"LPG-powered generation 指使用液化石油氣發電。"},{"en":"A small island facility may use LPG-powered generation when grid electricity is unavailable.","zh":"當沒有電網供電，小島設施可能使用石油氣發電。"},{"en":"LPG generation may produce fewer emissions than some diesel systems.","zh":"石油氣發電可能比某些柴油系統產生較少排放。"},{"en":"This phrase describes the fuel source for electricity production.","zh":"這個短語描述發電所用的燃料來源。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":12},{"front":"rather than","meaning":"而不是","examples":[{"en":"The resort uses LPG-powered generation rather than a diesel plant.","zh":"度假村使用石油氣發電，而不是柴油發電廠。"},{"en":"Rather than means instead of, showing a clear contrast between two choices.","zh":"rather than 指「而不是」，顯示兩個選擇之間的清楚對比。"},{"en":"A student may revise in the morning rather than late at night if they concentrate better then.","zh":"如果學生早上較能集中，他可能在早上溫習，而不是深夜溫習。"},{"en":"This phrase helps separate the chosen option from the rejected option.","zh":"這個短語幫助把被選擇的選項與被拒絕的選項分開。"},{"en":"It is useful when explaining why one method is preferred over another.","zh":"當解釋為何偏好某一方法而不是另一方法時，這個短語很有用。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":13},{"front":"diesel plant","meaning":"柴油發電廠","examples":[{"en":"The resort avoids relying mainly on a diesel plant.","zh":"該度假村避免主要依賴柴油發電廠。"},{"en":"A diesel plant is a facility that generates electricity using diesel fuel.","zh":"diesel plant 指使用柴油燃料發電的設施。"},{"en":"A remote village may use a diesel plant if it is not connected to the power grid.","zh":"如果偏遠村莊未連接電網，可能使用柴油發電廠。"},{"en":"Diesel plants can be reliable but may produce noise and emissions.","zh":"柴油發電廠可以可靠，但可能產生噪音和排放。"},{"en":"This phrase refers to a diesel-powered electricity system.","zh":"這個短語指柴油供電系統。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":13},{"front":"supplemented by","meaning":"由……補充","examples":[{"en":"The LPG-powered generation is supplemented by a wind turbine.","zh":"石油氣發電由風力渦輪機補充。"},{"en":"Supplemented by something means supported or added to by another thing.","zh":"supplemented by something 指由另一事物支援或補充。"},{"en":"A student’s textbook learning can be supplemented by videos and practice exercises.","zh":"學生的教科書學習可以由影片和練習補充。"},{"en":"Supplementing one energy source with another can improve reliability or reduce emissions.","zh":"用另一能源補充原本能源，可以改善可靠性或減少排放。"},{"en":"This phrase means the second thing adds extra support, not replaces everything.","zh":"這個短語表示第二事物提供額外支援，而不是完全取代一切。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":13},{"front":"wind turbine","meaning":"風力渦輪機","examples":[{"en":"A wind turbine supplements the resort’s energy supply.","zh":"風力渦輪機補充度假村能源供應。"},{"en":"A wind turbine is a machine that uses wind to generate electricity.","zh":"wind turbine 指利用風力發電的機器。"},{"en":"A school may install a small wind turbine to teach students about renewable energy.","zh":"學校可能安裝小型風力渦輪機，教學生認識可再生能源。"},{"en":"Wind turbines produce more power when wind conditions are suitable.","zh":"當風力條件合適，風力渦輪機會產生更多電力。"},{"en":"This phrase refers to equipment that turns wind into electricity.","zh":"這個短語指把風轉化成電力的設備。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":13},{"front":"greenhouse-gas emissions","meaning":"溫室氣體排放","examples":[{"en":"This arrangement has reduced greenhouse-gas emissions.","zh":"這項安排已減少溫室氣體排放。"},{"en":"Greenhouse-gas emissions are gases released into the air that trap heat and contribute to climate change.","zh":"greenhouse-gas emissions 指釋放到空氣中、會困住熱量並促成氣候變化的氣體。"},{"en":"Cars, factories, and power stations can produce greenhouse-gas emissions.","zh":"汽車、工廠和發電站可以產生溫室氣體排放。"},{"en":"Reducing emissions can lower a business’s environmental impact.","zh":"減少排放可以降低企業的環境影響。"},{"en":"This phrase refers to climate-related air pollution.","zh":"這個短語指與氣候相關的空氣污染。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":13},{"front":"equivalent diesel generation","meaning":"同等柴油發電","examples":[{"en":"Emissions are lower than with equivalent diesel generation.","zh":"排放量比同等柴油發電較低。"},{"en":"Equivalent diesel generation means producing the same amount of electricity using diesel fuel.","zh":"equivalent diesel generation 指用柴油燃料產生相同電量。"},{"en":"A solar system may be compared with equivalent diesel generation to measure emissions savings.","zh":"太陽能系統可與同等柴油發電比較，以量度減排量。"},{"en":"Comparing equivalent systems makes the environmental difference clearer.","zh":"比較同等系統可以令環境差異更清楚。"},{"en":"This phrase sets up a fair comparison between energy methods.","zh":"這個短語建立能源方法之間的公平比較。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":13},{"front":"excess heat","meaning":"多餘熱力","examples":[{"en":"Excess heat recovered from the generator heats the swimming pool.","zh":"從發電機回收的多餘熱力用來加熱泳池。"},{"en":"Excess heat is extra heat produced by a machine or process that is not needed for its main function.","zh":"excess heat 指機器或過程產生、但主要功能不需要的額外熱力。"},{"en":"A bakery may use excess heat from ovens to warm another room.","zh":"麵包店可能利用焗爐的多餘熱力加暖另一個房間。"},{"en":"Reusing excess heat can save energy and reduce waste.","zh":"重用多餘熱力可以節省能源並減少浪費。"},{"en":"This phrase describes heat that would otherwise be lost.","zh":"這個短語描述原本會流失的熱力。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":13},{"front":"recovered from","meaning":"從……回收","examples":[{"en":"Excess heat is recovered from the generator.","zh":"多餘熱力從發電機回收。"},{"en":"To be recovered from something means to be captured or taken back from it for use.","zh":"recovered from something 指從某物中收集或取回以便使用。"},{"en":"Rainwater can be recovered from a roof and stored in a tank.","zh":"雨水可以從屋頂回收並儲存在水箱中。"},{"en":"Recovering useful resources reduces waste because fewer materials are thrown away.","zh":"回收有用資源可以減少浪費，因為較少材料被丟棄。"},{"en":"This phrase describes getting value from something that might otherwise be lost.","zh":"這個短語描述從原本可能流失的東西中取得價值。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":13},{"front":"solar-powered","meaning":"太陽能供電的","examples":[{"en":"Hot water in the eco-cabins is solar-powered.","zh":"生態小屋中的熱水由太陽能供應。"},{"en":"Solar-powered means using energy from sunlight.","zh":"solar-powered 指使用太陽光能源。"},{"en":"A solar-powered calculator works without ordinary batteries when there is enough light.","zh":"有足夠光線時，太陽能計算機不用普通電池也能運作。"},{"en":"Solar-powered systems can reduce electricity use from fossil fuels.","zh":"太陽能供電系統可以減少化石燃料電力使用。"},{"en":"This phrase describes technology powered by the sun.","zh":"這個短語描述由太陽供能的科技。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":13},{"front":"eco-cabins","meaning":"生態小屋","examples":[{"en":"Hot water in the eco-cabins is solar-powered.","zh":"生態小屋中的熱水由太陽能供應。"},{"en":"Eco-cabins are small accommodation units designed to have a lower environmental impact.","zh":"eco-cabins 指設計上環境影響較低的小型住宿單位。"},{"en":"An eco-cabin may use solar hot water, natural ventilation, and water-saving fittings.","zh":"生態小屋可能使用太陽能熱水、自然通風和節水裝置。"},{"en":"Eco-cabins can make visitors more aware of sustainable living choices.","zh":"生態小屋可以令遊客更意識到可持續生活選擇。"},{"en":"This phrase refers to environmentally designed guest cabins.","zh":"這個短語指環保設計的客用小屋。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":13},{"front":"water-efficient fittings","meaning":"節水裝置","examples":[{"en":"Water-efficient fittings are installed in showers and toilets.","zh":"節水裝置安裝在淋浴和廁所中。"},{"en":"Water-efficient fittings are devices designed to use less water while still working properly.","zh":"water-efficient fittings 指設計上使用較少水但仍正常運作的裝置。"},{"en":"A home can install water-efficient fittings such as low-flow shower heads and dual-flush toilets.","zh":"家庭可以安裝低流量花灑頭和雙掣沖廁等節水裝置。"},{"en":"These fittings reduce water use and lower pressure on limited supplies.","zh":"這些裝置可以減少用水，並降低有限水源壓力。"},{"en":"This phrase describes practical equipment for saving water.","zh":"這個短語描述用於節水的實用設備。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":14},{"front":"be installed in","meaning":"安裝在……","examples":[{"en":"Water-efficient fittings are installed in showers and toilets.","zh":"節水裝置安裝在淋浴和廁所中。"},{"en":"To be installed in a place means to be fixed or put there for use.","zh":"be installed in a place 指被固定或放置在某地供使用。"},{"en":"New lights may be installed in a classroom before the school year begins.","zh":"新燈可能在學年開始前安裝在課室中。"},{"en":"Installation changes a place because equipment becomes part of its daily operation.","zh":"安裝會改變一個地方，因為設備成為日常運作的一部分。"},{"en":"This phrase describes putting equipment into a specific location.","zh":"這個短語描述把設備放入特定位置。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":14},{"front":"appliances","meaning":"電器","examples":[{"en":"Not all the resort’s appliances are energy-efficient.","zh":"並非度假村所有電器都是節能的。"},{"en":"Appliances are electrical machines used in homes, hotels, or workplaces.","zh":"appliances 指在家庭、酒店或工作場所使用的電動機器。"},{"en":"Refrigerators, washing machines, air conditioners, and kettles are common appliances.","zh":"雪櫃、洗衣機、冷氣機和電熱水壺都是常見電器。"},{"en":"Old appliances can use more electricity than modern efficient models.","zh":"舊電器可能比現代高效型號耗用更多電力。"},{"en":"This word refers to useful machines, especially household or room equipment.","zh":"這個詞指有用機器，尤其是家居或房間設備。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":14},{"front":"energy-efficient","meaning":"節能的","examples":[{"en":"Some appliances at the resort are not energy-efficient.","zh":"度假村有些電器並不節能。"},{"en":"Energy-efficient means using less energy to do the same job.","zh":"energy-efficient 指用較少能源完成同一工作。"},{"en":"An energy-efficient fridge keeps food cold while using less electricity.","zh":"節能雪櫃用較少電力保持食物冷藏。"},{"en":"Energy-efficient appliances can lower bills and reduce emissions.","zh":"節能電器可以降低賬單並減少排放。"},{"en":"This phrase describes equipment that wastes less power.","zh":"這個短語描述較少浪費電力的設備。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":14},{"front":"be encouraged to","meaning":"被鼓勵去……","examples":[{"en":"Guests are encouraged to monitor their water and energy use.","zh":"客人被鼓勵監察自己的用水和用電。"},{"en":"To be encouraged to do something means to be gently urged or motivated to do it.","zh":"be encouraged to do something 指被溫和地勸導或推動去做某事。"},{"en":"Students are encouraged to ask questions when they do not understand a lesson.","zh":"學生在不明白課堂時會被鼓勵提問。"},{"en":"Encouragement can change behaviour without forcing people directly.","zh":"鼓勵可以在不直接強迫的情況下改變行為。"},{"en":"This phrase suggests positive guidance rather than strict command.","zh":"這個短語表示正面引導，而不是嚴格命令。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":14},{"front":"monitor their water and energy use","meaning":"監察自己的用水和用電","examples":[{"en":"Guests can monitor their water and energy use through the television system.","zh":"客人可以透過電視系統監察自己的用水和用電。"},{"en":"To monitor water and energy use means to check how much water and electricity are being used.","zh":"monitor water and energy use 指檢查用水和用電量。"},{"en":"A family can monitor energy use by reading the electricity meter each week.","zh":"家庭可以透過每星期查看電錶來監察用電。"},{"en":"Monitoring helps people notice waste and change habits.","zh":"監察幫助人注意浪費並改變習慣。"},{"en":"This phrase describes tracking resource use to encourage savings.","zh":"這個短語描述追蹤資源使用，以鼓勵節省。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":14},{"front":"in-house television system","meaning":"內部電視系統","examples":[{"en":"Guests monitor resource use through the in-house television system.","zh":"客人透過內部電視系統監察資源使用。"},{"en":"An in-house television system is a television network or service used inside a hotel or resort.","zh":"in-house television system 指酒店或度假村內部使用的電視網絡或服務。"},{"en":"A hotel may use an in-house television system to show menus, bills, and safety information.","zh":"酒店可能使用內部電視系統顯示餐牌、賬單和安全資訊。"},{"en":"Such a system can help guests receive information without visiting reception.","zh":"這類系統可以幫助客人在不用到接待處的情況下取得資訊。"},{"en":"This phrase refers to a private internal TV service.","zh":"這個短語指私人內部電視服務。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":14},{"front":"usage is low","meaning":"使用量低","examples":[{"en":"Guests whose usage is low are rewarded with prizes.","zh":"使用量低的客人會獲獎勵。"},{"en":"Usage is low means only a small amount of a resource is being used.","zh":"usage is low 指只使用少量資源。"},{"en":"A household’s electricity usage is low if lights and appliances are turned off when not needed.","zh":"如果燈和電器不用時都關掉，家庭用電量就低。"},{"en":"Low usage saves money and reduces pressure on limited resources.","zh":"低使用量可以節省金錢並減少有限資源壓力。"},{"en":"This phrase is often used for water, electricity, data, or fuel.","zh":"這個短語常用於水、電、數據或燃料。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":14},{"front":"be rewarded with prizes","meaning":"獲獎勵","examples":[{"en":"Guests with low usage are rewarded with prizes.","zh":"使用量低的客人會獲獎勵。"},{"en":"To be rewarded with prizes means to receive gifts or benefits for good behaviour or achievement.","zh":"be rewarded with prizes 指因良好行為或成就而收到禮物或好處。"},{"en":"Students may be rewarded with certificates for reading many books.","zh":"學生可能因閱讀很多書而獲頒證書獎勵。"},{"en":"Rewards can motivate people to repeat positive behaviour.","zh":"獎勵可以推動人們重複正面行為。"},{"en":"This phrase describes a system of incentives.","zh":"這個短語描述一套誘因制度。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":14},{"front":"free return trip","meaning":"免費來回旅程","examples":[{"en":"One prize is a free return trip to the resort.","zh":"其中一項獎品是到度假村的免費來回旅程。"},{"en":"A free return trip is a journey to a place and back again without paying for the travel or visit.","zh":"free return trip 指免費前往某地並返回的旅程或到訪。"},{"en":"A shop may offer a free return trip as a prize in a customer competition.","zh":"商店可能在顧客比賽中提供免費來回旅程作獎品。"},{"en":"Free return trips can encourage guests to come back.","zh":"免費來回旅程可以鼓勵客人再次到訪。"},{"en":"This phrase describes a reward involving travel both ways.","zh":"這個短語描述包括去程和回程的旅遊獎勵。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":14},{"front":"concluding remarks","meaning":"總結意見","examples":[{"en":"The concluding remarks evaluate the resort’s management practices.","zh":"總結意見評估該度假村的管理做法。"},{"en":"Concluding remarks are final comments that summarise or judge the main points.","zh":"concluding remarks 指總結或評價主要重點的最後評論。"},{"en":"A teacher’s concluding remarks at the end of a lesson may remind students what to revise.","zh":"老師在課堂結尾的總結意見可能提醒學生要溫習甚麼。"},{"en":"Good concluding remarks help readers understand the final judgement.","zh":"良好的總結意見幫助讀者理解最終判斷。"},{"en":"This phrase refers to the closing part of a discussion or report.","zh":"這個短語指討論或報告的結尾部分。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":15},{"front":"case study of","meaning":"……的個案研究","examples":[{"en":"The passage presents a case study of good management practice.","zh":"文章呈現一個良好管理做法的個案研究。"},{"en":"A case study of something is a detailed example used to understand a wider issue.","zh":"case study of something 指用來理解更廣泛議題的詳細例子。"},{"en":"A business class may use a case study of a small café to teach customer service.","zh":"商業課可能使用小咖啡店的個案研究來教授客戶服務。"},{"en":"Case studies help students see how ideas work in real situations.","zh":"個案研究幫助學生看見想法如何在真實情況中運作。"},{"en":"This phrase means one specific example is being examined closely.","zh":"這個短語表示正在仔細研究一個具體例子。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":15},{"front":"good management practice","meaning":"良好管理做法","examples":[{"en":"The resort is presented as a case study of good management practice.","zh":"該度假村被呈現為良好管理做法的個案研究。"},{"en":"Good management practice means effective and responsible ways of running an organisation.","zh":"good management practice 指有效且負責任地營運組織的方法。"},{"en":"A school shows good management practice when it communicates clearly and uses resources wisely.","zh":"學校清楚溝通並明智使用資源時，就是展示良好管理做法。"},{"en":"Good management can improve service quality while reducing waste and risk.","zh":"良好管理可以改善服務質素，同時減少浪費和風險。"},{"en":"This phrase describes practical standards for running something well.","zh":"這個短語描述妥善營運某事物的實用標準。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":15},{"front":"proactive approach to","meaning":"對……採取積極主動的方法","examples":[{"en":"The resort has taken a proactive approach to sustainable tourism.","zh":"該度假村對可持續旅遊採取積極主動的方法。"},{"en":"A proactive approach to something means taking action early instead of waiting for problems.","zh":"proactive approach to something 指及早行動，而不是等待問題出現。"},{"en":"A student takes a proactive approach to exams by revising before stress becomes serious.","zh":"學生在壓力變嚴重前溫習，就是對考試採取積極主動的方法。"},{"en":"Proactive management can prevent damage rather than only repair it later.","zh":"積極主動管理可以預防損害，而不是之後才修補。"},{"en":"This phrase describes active, forward-looking action.","zh":"這個短語描述主動且面向未來的行動。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":15},{"front":"sustainable tourism","meaning":"可持續旅遊","examples":[{"en":"Couran Cove is discussed as an example of sustainable tourism.","zh":"Couran Cove 被討論為可持續旅遊的例子。"},{"en":"Sustainable tourism is tourism that supports visitors, local communities, and the environment over the long term.","zh":"sustainable tourism 指長遠支持遊客、本地社區和環境的旅遊。"},{"en":"A walking tour led by local guides can be sustainable tourism if it protects culture and limits waste.","zh":"由本地導遊帶領的步行團，如果保護文化並限制廢物，就可以是可持續旅遊。"},{"en":"Sustainable tourism avoids using up the resources that attract tourists in the first place.","zh":"可持續旅遊避免耗盡最初吸引遊客的資源。"},{"en":"This phrase means tourism designed to last without causing serious damage.","zh":"這個短語指設計上能持續而不造成嚴重破壞的旅遊。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":15},{"front":"in three years of operation","meaning":"在營運三年內","examples":[{"en":"In three years of operation, the resort won many awards.","zh":"在營運三年內，該度假村贏得許多獎項。"},{"en":"In three years of operation means during the first three years that a business or service was running.","zh":"in three years of operation 指在企業或服務開始運作後的前三年期間。"},{"en":"In two years of operation, a new school may build a strong reputation.","zh":"在營運兩年內，新學校可能建立良好聲譽。"},{"en":"This phrase links achievements to a specific period of working activity.","zh":"這個短語把成就與特定營運時期連繫起來。"},{"en":"It helps show how quickly success or change happened.","zh":"它幫助顯示成功或改變發生得有多快。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":15},{"front":"international and national awards","meaning":"國際及全國獎項","examples":[{"en":"The resort won 23 international and national awards.","zh":"該度假村贏得 23 個國際及全國獎項。"},{"en":"International and national awards are prizes recognised overseas and within a country.","zh":"international and national awards 指在海外和國內獲認可的獎項。"},{"en":"A film that wins international and national awards may attract wider attention.","zh":"獲得國際及全國獎項的電影可能吸引更廣泛注意。"},{"en":"Awards can improve reputation because they suggest outside recognition.","zh":"獎項可以提升聲譽，因為它們表示外界認可。"},{"en":"This phrase describes honours from both global and domestic levels.","zh":"這個短語描述來自全球和國內層面的榮譽。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":15},{"front":"accommodation category","meaning":"住宿類別","examples":[{"en":"The resort won an award in the four-star accommodation category.","zh":"該度假村在四星級住宿類別中獲獎。"},{"en":"An accommodation category is a class or group used to judge places where guests stay.","zh":"accommodation category 指用來評審住宿地方的類別或組別。"},{"en":"Hotels may compete in different accommodation categories based on price, service, or star rating.","zh":"酒店可能按價格、服務或星級在不同住宿類別中競爭。"},{"en":"Categories make comparisons fairer because similar businesses are judged together.","zh":"類別令比較更公平，因為相似企業會被放在一起評審。"},{"en":"This phrase refers to a lodging classification.","zh":"這個短語指住宿分類。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":15},{"front":"embrace practices","meaning":"採納做法","examples":[{"en":"The resort has embraced contemporary environmental-management practices.","zh":"該度假村已採納當代環境管理做法。"},{"en":"To embrace practices means to accept and use particular methods willingly.","zh":"embrace practices 指願意接受並使用某些方法。"},{"en":"A school may embrace new teaching practices after seeing students learn better.","zh":"學校看到學生學得更好後，可能採納新教學做法。"},{"en":"When an organisation embraces a practice, it does more than mention it; it applies it.","zh":"當組織採納某做法，它不只是提到它，而是實際應用它。"},{"en":"This phrase suggests active acceptance and adoption.","zh":"這個短語表示主動接受和採用。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":15},{"front":"effectively implement","meaning":"有效實施","examples":[{"en":"The resort has effectively implemented environmental-management practices.","zh":"該度假村已有效實施環境管理做法。"},{"en":"To effectively implement something means to put a plan into action successfully.","zh":"effectively implement something 指成功把計劃付諸行動。"},{"en":"A school effectively implements a reading programme when teachers use it daily and students improve.","zh":"如果老師每天使用閱讀計劃且學生有進步，學校就是有效實施該計劃。"},{"en":"Implementation matters because a good idea has little value if it is not carried out well.","zh":"實施很重要，因為好想法若沒有好好執行，價值有限。"},{"en":"This phrase focuses on successful practical use.","zh":"這個短語著重成功的實際運用。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":15},{"front":"contemporary environmental-management practices","meaning":"當代環境管理做法","examples":[{"en":"The resort has implemented contemporary environmental-management practices.","zh":"該度假村已實施當代環境管理做法。"},{"en":"Contemporary environmental-management practices are modern methods for reducing environmental harm.","zh":"contemporary environmental-management practices 指減少環境傷害的現代方法。"},{"en":"A hotel uses contemporary environmental-management practices when it tracks energy use and treats wastewater.","zh":"酒店追蹤能源使用並處理污水時，就是使用當代環境管理做法。"},{"en":"Modern practices often depend on monitoring, clear policies, and efficient technology.","zh":"現代做法常依賴監察、清楚政策和高效科技。"},{"en":"This phrase means current professional methods for protecting the environment.","zh":"這個短語指目前專業的環境保護方法。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":16},{"front":"successful implementation of","meaning":"成功實施……","examples":[{"en":"Successful implementation of sustainability principles should bring long-term benefits.","zh":"成功實施可持續發展原則應帶來長遠好處。"},{"en":"Successful implementation of something means putting it into practice effectively.","zh":"successful implementation of something 指有效地把某事付諸實行。"},{"en":"Successful implementation of a school policy requires training, clear rules, and follow-up.","zh":"成功實施學校政策需要培訓、清楚規則和跟進。"},{"en":"If implementation succeeds, the idea produces real results rather than staying on paper.","zh":"如果實施成功，想法就會產生真實結果，而不是留在紙上。"},{"en":"This phrase focuses on making a plan work in practice.","zh":"這個短語著重令計劃在實際中奏效。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":16},{"front":"sustainability principles","meaning":"可持續發展原則","examples":[{"en":"Sustainability principles should promote long-term benefits.","zh":"可持續發展原則應促進長遠好處。"},{"en":"Sustainability principles are basic ideas for using resources responsibly and protecting future needs.","zh":"sustainability principles 指負責任使用資源並保護未來需要的基本理念。"},{"en":"A company follows sustainability principles when it reduces waste and treats workers fairly.","zh":"公司減少廢物並公平對待員工時，就是遵循可持續發展原則。"},{"en":"These principles guide decisions so short-term profit does not destroy long-term value.","zh":"這些原則引導決策，令短期利潤不會摧毀長遠價值。"},{"en":"This phrase refers to the core rules behind sustainable action.","zh":"這個短語指可持續行動背後的核心規則。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":16},{"front":"long-term social, economic and environmental benefits","meaning":"長遠社會、經濟和環境效益","examples":[{"en":"Sustainability should promote long-term social, economic and environmental benefits.","zh":"可持續發展應促進長遠社會、經濟和環境效益。"},{"en":"Long-term social, economic and environmental benefits are lasting gains for people, money, and nature.","zh":"long-term social, economic and environmental benefits 指對人、金錢和自然都有持久好處。"},{"en":"A community recycling project may create jobs, reduce waste, and teach residents new habits.","zh":"社區回收項目可能創造職位、減少廢物並教居民新習慣。"},{"en":"Sustainable planning is strongest when it helps society, the economy, and the environment together.","zh":"可持續規劃在同時幫助社會、經濟和環境時最有力。"},{"en":"This phrase describes benefits that last beyond immediate profit.","zh":"這個短語描述超越即時利潤的長遠好處。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":16},{"front":"safeguard and enhance","meaning":"保障並提升","examples":[{"en":"Sustainability should safeguard and enhance a tourism enterprise’s viability.","zh":"可持續發展應保障並提升旅遊企業的生存能力。"},{"en":"To safeguard and enhance something means to protect it and make it stronger.","zh":"safeguard and enhance something 指保護某事物並令它更強。"},{"en":"A school can safeguard and enhance student wellbeing by preventing bullying and improving counselling.","zh":"學校可以透過防止欺凌和改善輔導來保障並提升學生福祉。"},{"en":"Protection stops damage, while enhancement creates improvement.","zh":"保障是防止損害，提升則是創造改善。"},{"en":"This phrase combines defence with positive development.","zh":"這個短語結合防護和正面發展。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":16},{"front":"tourism enterprise","meaning":"旅遊企業","examples":[{"en":"A tourism enterprise must remain viable over time.","zh":"旅遊企業必須長期保持可行。"},{"en":"A tourism enterprise is a business or organisation that provides tourism services.","zh":"tourism enterprise 指提供旅遊服務的企業或組織。"},{"en":"Hotels, tour operators, ferry companies, and resorts can be tourism enterprises.","zh":"酒店、旅行團營辦商、渡輪公司和度假村都可以是旅遊企業。"},{"en":"A tourism enterprise needs visitors, income, staff, and resources to survive.","zh":"旅遊企業需要遊客、收入、員工和資源才能生存。"},{"en":"This phrase refers to a business in the tourism industry.","zh":"這個短語指旅遊業中的企業。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":16},{"front":"continued viability","meaning":"持續營運能力","examples":[{"en":"Sustainability should enhance the enterprise’s continued viability.","zh":"可持續發展應提升企業的持續營運能力。"},{"en":"Continued viability means the ability to keep operating successfully in the future.","zh":"continued viability 指未來繼續成功營運的能力。"},{"en":"A small shop’s continued viability depends on loyal customers and controlled costs.","zh":"小店的持續營運能力取決於忠實顧客和受控成本。"},{"en":"If a resort damages the environment it depends on, its continued viability may fall.","zh":"如果度假村破壞自己依賴的環境，其持續營運能力可能下降。"},{"en":"This phrase describes long-term ability to survive and function.","zh":"這個短語描述長期生存和運作能力。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":16},{"front":"conform to","meaning":"符合","examples":[{"en":"Couran Cove does not conform to the Resort Development Spectrum.","zh":"Couran Cove 並不符合度假村發展光譜。"},{"en":"To conform to something means to match, follow, or fit a standard, rule, or model.","zh":"conform to something 指符合、遵從或配合某標準、規則或模型。"},{"en":"A student’s essay must conform to the word limit if the exam gives one.","zh":"如果考試有字數限制，學生文章必須符合該限制。"},{"en":"If a real case does not conform to a model, the model may not fully explain it.","zh":"如果真實個案不符合模型，該模型可能不能完全解釋它。"},{"en":"This phrase describes whether something fits an expected pattern.","zh":"這個短語描述某事是否符合預期模式。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":16},{"front":"Resort Development Spectrum","meaning":"度假村發展光譜","examples":[{"en":"Prideaux proposed the Resort Development Spectrum.","zh":"Prideaux 提出了度假村發展光譜。"},{"en":"The Resort Development Spectrum is a model used to describe stages of resort development.","zh":"Resort Development Spectrum 是用來描述度假村發展階段的模型。"},{"en":"A tourism student may use the Resort Development Spectrum to compare small local resorts and large international resorts.","zh":"旅遊學生可能使用度假村發展光譜來比較小型本地度假村和大型國際度假村。"},{"en":"Models help organise complex tourism patterns, but real resorts may not fit perfectly.","zh":"模型有助整理複雜旅遊模式，但真實度假村未必完全符合。"},{"en":"This phrase names a specific framework for analysing resorts.","zh":"這個短語命名一個分析度假村的特定框架。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":16},{"front":"according to","meaning":"根據","examples":[{"en":"According to Prideaux, the resort should be in Phase 3.","zh":"根據 Prideaux，該度假村應屬於第三階段。"},{"en":"According to someone means based on what that person says, writes, or believes.","zh":"according to someone 指根據某人所說、所寫或所相信的內容。"},{"en":"According to the timetable, the next ferry leaves at 3 p.m.","zh":"根據時間表，下一班渡輪下午三時開出。"},{"en":"This phrase shows the source of information or judgement.","zh":"這個短語顯示資料或判斷來源。"},{"en":"It is useful when reporting another person’s view rather than your own.","zh":"當報告他人觀點而不是自己觀點時，這個短語很有用。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":16},{"front":"at least","meaning":"至少","examples":[{"en":"The resort should be at least in Phase 3 of the model.","zh":"該度假村至少應屬於該模型的第三階段。"},{"en":"At least means no lower, fewer, or less than a stated point.","zh":"at least 指不低於、不少於或不小於某個指定點。"},{"en":"Students should sleep at least seven hours before an important exam.","zh":"學生在重要考試前應至少睡七小時。"},{"en":"Saying “at least” gives a minimum level, not a maximum.","zh":"說 at least 是給出最低水平，而不是最高水平。"},{"en":"This phrase is often used when the real amount may be higher.","zh":"當實際數量可能更高時，常會使用這個短語。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":17},{"front":"national-tourism phase","meaning":"全國旅遊階段","examples":[{"en":"Phase 3 is the national-tourism phase.","zh":"第三階段是全國旅遊階段。"},{"en":"A national-tourism phase is a stage where a resort mainly attracts visitors from within the same country.","zh":"national-tourism phase 指度假村主要吸引同一國家內遊客的階段。"},{"en":"A beach town enters a national-tourism phase when people from many regions of the country visit it.","zh":"當全國多個地區的人都到訪某海灘城鎮，它就進入全國旅遊階段。"},{"en":"This phase usually shows wider recognition beyond the local area.","zh":"這個階段通常顯示其知名度已超出本地範圍。"},{"en":"This phrase describes a stage in tourism development.","zh":"這個短語描述旅遊發展中的一個階段。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":17},{"front":"hotel-style accommodation","meaning":"酒店式住宿","examples":[{"en":"Phase 3 describes a resort with hotel-style accommodation.","zh":"第三階段描述有酒店式住宿的度假村。"},{"en":"Hotel-style accommodation means guest rooms and services similar to those in a hotel.","zh":"hotel-style accommodation 指類似酒店的客房和服務。"},{"en":"A resort offers hotel-style accommodation when rooms have reception, cleaning, beds, and private bathrooms.","zh":"如果度假村有接待處、清潔服務、床和私人浴室，就是提供酒店式住宿。"},{"en":"This type of accommodation may feel more formal than camping or simple cabins.","zh":"這類住宿可能比露營或簡單小屋更正式。"},{"en":"This phrase describes the style of lodging expected in a developed resort.","zh":"這個短語描述成熟度假村預期具備的住宿風格。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":17},{"front":"tourist market","meaning":"旅遊客源市場","examples":[{"en":"The main tourist market in Phase 3 consists of interstate visitors.","zh":"第三階段的主要旅遊客源市場由跨州旅客組成。"},{"en":"A tourist market is the group of people a tourism business attracts or wants to attract.","zh":"tourist market 指旅遊企業吸引或想吸引的人群。"},{"en":"A theme park’s tourist market may include families with young children.","zh":"主題公園的旅遊客源市場可能包括有幼兒的家庭。"},{"en":"Knowing the tourist market helps businesses design prices, transport, and activities.","zh":"了解旅遊客源市場有助企業設計價格、交通和活動。"},{"en":"This phrase refers to the target or actual visitor group.","zh":"這個短語指目標或實際遊客群體。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":17},{"front":"consist principally of","meaning":"主要由……組成","examples":[{"en":"The main market consists principally of interstate visitors.","zh":"主要市場主要由跨州旅客組成。"},{"en":"To consist principally of something means to be made up mainly of that group or thing.","zh":"consist principally of something 指主要由某群體或事物組成。"},{"en":"A school club may consist principally of senior students if younger students rarely join.","zh":"如果低年級學生很少加入，學會可能主要由高年級學生組成。"},{"en":"Knowing what a market consists principally of helps managers plan suitable services.","zh":"了解市場主要由甚麼組成，有助管理者規劃合適服務。"},{"en":"This phrase means “mainly consists of”.","zh":"這個短語意思是「主要由……組成」。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":17},{"front":"interstate visitors","meaning":"跨州旅客","examples":[{"en":"Phase 3 resorts mainly attract interstate visitors.","zh":"第三階段度假村主要吸引跨州旅客。"},{"en":"Interstate visitors are tourists who travel from another state within the same country.","zh":"interstate visitors 指從同一國家內另一州份來的遊客。"},{"en":"A family from Victoria visiting Queensland would be interstate visitors in Queensland.","zh":"來自維多利亞州到昆士蘭旅遊的家庭，在昆士蘭就是跨州旅客。"},{"en":"Resorts attracting interstate visitors usually have wider appeal than purely local destinations.","zh":"吸引跨州旅客的度假村通常比純本地目的地更有吸引力。"},{"en":"This phrase refers to domestic tourists from other states.","zh":"這個短語指來自其他州份的國內遊客。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":17},{"front":"relatively few","meaning":"相對較少","examples":[{"en":"Relatively few interstate and international tourists visit the resort.","zh":"相對較少跨州和國際遊客到訪該度假村。"},{"en":"Relatively few means a small number compared with what might be expected or compared with another group.","zh":"relatively few 指與預期相比或與另一群體相比數量較少。"},{"en":"Relatively few students choose the early morning class if transport is inconvenient.","zh":"如果交通不方便，相對較少學生選擇清晨課堂。"},{"en":"This phrase is comparative, so the number feels low in relation to something else.","zh":"這個短語是比較性的，所以數量是相對某事而言偏低。"},{"en":"It does not always mean “almost none”; it means fewer than expected or fewer than others.","zh":"它不一定表示「幾乎沒有」，而是比預期或其他群體少。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":17},{"front":"international tourists","meaning":"國際遊客","examples":[{"en":"Relatively few international tourists visit Couran Cove.","zh":"相對較少國際遊客到訪 Couran Cove。"},{"en":"International tourists are visitors who travel from another country.","zh":"international tourists 指從另一個國家來的遊客。"},{"en":"A hotel near an airport may receive many international tourists.","zh":"機場附近酒店可能接待許多國際遊客。"},{"en":"International tourists may need clear transport information, language support, and suitable services.","zh":"國際遊客可能需要清楚交通資訊、語言支援和合適服務。"},{"en":"This phrase contrasts overseas visitors with local or domestic visitors.","zh":"這個短語把海外遊客與本地或國內遊客作對比。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":17},{"front":"principal markets","meaning":"主要市場","examples":[{"en":"The resort’s principal markets are local people and nearby residents.","zh":"該度假村的主要市場是本地人和附近居民。"},{"en":"Principal markets are the main groups of customers or visitors a business serves.","zh":"principal markets 指企業服務的主要顧客或遊客群體。"},{"en":"A small bakery’s principal market may be office workers nearby.","zh":"小麵包店的主要市場可能是附近上班族。"},{"en":"Knowing principal markets helps businesses decide advertising, prices, and services.","zh":"了解主要市場幫助企業決定宣傳、價格和服務。"},{"en":"This phrase identifies the most important customer groups.","zh":"這個短語指出最重要的顧客群。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":17},{"front":"local people","meaning":"本地人","examples":[{"en":"Local people are one of the resort’s principal markets.","zh":"本地人是該度假村的主要市場之一。"},{"en":"Local people are residents who live in or near the area being discussed.","zh":"local people 指住在所討論地區或附近的居民。"},{"en":"A museum may offer discounts to local people to encourage repeated visits.","zh":"博物館可能向本地人提供折扣，以鼓勵重複到訪。"},{"en":"Tourism businesses that depend on local people need services that fit everyday budgets.","zh":"依賴本地人的旅遊企業需要符合日常預算的服務。"},{"en":"This phrase refers to nearby residents, not tourists from far away.","zh":"這個短語指附近居民，而不是遠方遊客。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":17},{"front":"nearby towns","meaning":"附近城鎮","examples":[{"en":"Residents of nearby towns form part of the resort’s market.","zh":"附近城鎮的居民構成該度假村市場的一部分。"},{"en":"Nearby towns are towns located close to the place being discussed.","zh":"nearby towns 指位於所討論地方附近的城鎮。"},{"en":"A shopping centre may attract families from nearby towns every weekend.","zh":"購物中心可能每週末吸引附近城鎮的家庭。"},{"en":"Nearby towns can provide a steady visitor base because travel time is short.","zh":"附近城鎮可以提供穩定遊客基礎，因為交通時間短。"},{"en":"This phrase gives the local surrounding area.","zh":"這個短語給出本地周邊地區。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":18},{"front":"Gold Coast region","meaning":"黃金海岸地區","examples":[{"en":"The resort attracts residents of the Gold Coast region.","zh":"該度假村吸引黃金海岸地區的居民。"},{"en":"The Gold Coast region is the wider area around the Gold Coast in Queensland.","zh":"Gold Coast region 指昆士蘭黃金海岸周圍較廣泛地區。"},{"en":"Businesses in the Gold Coast region often serve both tourists and local residents.","zh":"黃金海岸地區的企業常同時服務遊客和本地居民。"},{"en":"A resort near a tourism region may draw day visitors as well as overnight guests.","zh":"位於旅遊區附近的度假村可能吸引即日來回遊客和過夜客。"},{"en":"This phrase refers to the broader local area around the Gold Coast.","zh":"這個短語指黃金海岸周邊較廣的本地地區。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":18},{"front":"carrying capacity","meaning":"承載力","examples":[{"en":"The carrying capacity of Couran Cove will eventually constrain growth.","zh":"Couran Cove 的承載力最終會限制增長。"},{"en":"Carrying capacity is the maximum number of people or activities an environment can support without serious damage.","zh":"carrying capacity 指環境在不受嚴重破壞下能承受的人數或活動上限。"},{"en":"A small beach has a carrying capacity because too many visitors can destroy dunes and create waste.","zh":"小海灘有承載力，因為太多遊客可以破壞沙丘並製造廢物。"},{"en":"If carrying capacity is exceeded, the place may lose the qualities that attract tourists.","zh":"如果超出承載力，該地方可能失去吸引遊客的特質。"},{"en":"This phrase is important in environmental and tourism planning.","zh":"這個短語在環境和旅遊規劃中很重要。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":18},{"front":"appear to concern","meaning":"似乎令……關注","examples":[{"en":"Carrying capacity does not appear to concern the resort’s management.","zh":"承載力似乎並未令度假村管理層關注。"},{"en":"Appear to concern means seem to worry or matter to someone.","zh":"appear to concern 指似乎令某人擔心或覺得重要。"},{"en":"Noise complaints do not appear to concern the landlord if repairs are never made.","zh":"如果業主從不維修，噪音投訴似乎沒有令他關注。"},{"en":"If a risk does not concern managers, they may fail to plan for it.","zh":"如果風險不令管理者關注，他們可能未能為它規劃。"},{"en":"This phrase suggests an impression, not always proven certainty.","zh":"這個短語表示一種印象，不一定是確定事實。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":18},{"front":"private commercial ecotourism enterprise","meaning":"私營商業生態旅遊企業","examples":[{"en":"Couran Cove is a private commercial ecotourism enterprise.","zh":"Couran Cove 是一家私營商業生態旅遊企業。"},{"en":"A private commercial ecotourism enterprise is a profit-making ecotourism business owned outside the government.","zh":"private commercial ecotourism enterprise 指由非政府擁有、以盈利為目的的生態旅遊企業。"},{"en":"A privately owned rainforest lodge can be a commercial ecotourism enterprise if guests pay for nature-based stays.","zh":"私人擁有的雨林旅舍若讓客人付費入住自然環境，就可以是商業生態旅遊企業。"},{"en":"Such businesses must balance profit with environmental responsibility.","zh":"這類企業必須平衡利潤和環境責任。"},{"en":"This phrase identifies both ownership, purpose, and tourism type.","zh":"這個短語同時指出所有權、目的和旅遊類型。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":18},{"front":"limiting visitor numbers","meaning":"限制遊客人數","examples":[{"en":"Limiting visitor numbers could minimise environmental damage.","zh":"限制遊客人數可以將環境損害減至最低。"},{"en":"Limiting visitor numbers means controlling how many people are allowed to visit.","zh":"limiting visitor numbers 指控制獲准到訪的人數。"},{"en":"A small cave may limit visitor numbers to protect fragile rock formations.","zh":"小洞穴可能限制遊客人數，以保護脆弱岩石結構。"},{"en":"Fewer visitors can reduce waste, noise, erosion, and pressure on facilities.","zh":"較少遊客可以減少廢物、噪音、侵蝕和設施壓力。"},{"en":"This phrase describes a management tool for protecting sensitive places.","zh":"這個短語描述保護敏感地方的管理工具。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":18},{"front":"minimise damage to","meaning":"將對……的損害減至最低","examples":[{"en":"Visitor controls can minimise damage to the natural environment.","zh":"遊客管制可以將對自然環境的損害減至最低。"},{"en":"To minimise damage to something means to reduce harm to it as much as possible.","zh":"minimise damage to something 指盡可能減少對某物的傷害。"},{"en":"A school can minimise damage to floors by asking students not to drag chairs.","zh":"學校要求學生不要拖椅，可以將對地板的損害減至最低。"},{"en":"In nature reserves, clear paths help minimise damage to plants and soil.","zh":"在自然保護區，清晰小徑有助將對植物和土壤的損害減至最低。"},{"en":"This phrase focuses on reducing harm, even if it cannot be removed completely.","zh":"這個短語著重減少傷害，即使不能完全消除。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":18},{"front":"binding constraint","meaning":"具約束力的限制","examples":[{"en":"Limiting visitor numbers is not a binding constraint.","zh":"限制遊客人數並不是具約束力的限制。"},{"en":"A binding constraint is a strict limit that actually controls what people can do.","zh":"binding constraint 指真正控制人們能做甚麼的嚴格限制。"},{"en":"A budget becomes a binding constraint when a school cannot buy anything beyond it.","zh":"當學校不能超出預算購買任何東西，預算就成為具約束力的限制。"},{"en":"If a rule is not binding, people may ignore it or treat it as optional.","zh":"如果規則不具約束力，人們可能忽視它或把它視為可選。"},{"en":"This phrase refers to a limit with real force.","zh":"這個短語指具有實際力量的限制。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":18},{"front":"nevertheless","meaning":"然而","examples":[{"en":"Nevertheless, carrying capacity will eventually constrain the resort’s growth.","zh":"然而，承載力最終會限制度假村增長。"},{"en":"Nevertheless means however or despite what has just been said.","zh":"nevertheless 指然而、儘管剛才說了某事仍然如此。"},{"en":"The journey was tiring; nevertheless, the students enjoyed the field trip.","zh":"旅程很累；然而，學生仍享受實地考察。"},{"en":"This word introduces a contrast or unexpected continuation.","zh":"這個詞引入對比或出乎意料的延續。"},{"en":"It helps writers show that one fact remains true despite another point.","zh":"它幫助作者顯示某事儘管有另一點仍然成立。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":18},{"front":"eventually constrain","meaning":"最終限制","examples":[{"en":"Carrying capacity will eventually constrain the resort’s growth.","zh":"承載力最終會限制度假村增長。"},{"en":"To eventually constrain something means to limit it after some time.","zh":"eventually constrain something 指經過一段時間後限制某事。"},{"en":"A small classroom will eventually constrain a school’s growth if more students apply.","zh":"如果更多學生申請，小課室最終會限制學校增長。"},{"en":"Limits may not matter at first, but they become important as demand increases.","zh":"限制起初可能不重要，但當需求增加就會變得重要。"},{"en":"This phrase links future growth with later restriction.","zh":"這個短語把未來增長與之後限制連繫起來。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":18},{"front":"future growth","meaning":"未來增長","examples":[{"en":"Environmental limits may restrict the resort’s future growth.","zh":"環境限制可能限制度假村的未來增長。"},{"en":"Future growth means expansion or development that may happen later.","zh":"future growth 指將來可能發生的擴展或發展。"},{"en":"A company’s future growth may depend on new customers and enough staff.","zh":"公司的未來增長可能取決於新顧客和足夠員工。"},{"en":"Planning for future growth helps organisations avoid problems before they expand.","zh":"為未來增長作規劃，可以幫助組織在擴展前避免問題。"},{"en":"This phrase refers to later development, not current size.","zh":"這個短語指之後的發展，而不是目前規模。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":19},{"front":"management strategy","meaning":"管理策略","examples":[{"en":"The management strategy should incorporate controls on visitor numbers.","zh":"管理策略應納入對遊客人數的控制。"},{"en":"A management strategy is a planned approach for running an organisation or activity.","zh":"management strategy 指營運組織或活動的計劃性方法。"},{"en":"A school’s management strategy may include staff training, clear communication, and safety rules.","zh":"學校的管理策略可能包括員工培訓、清楚溝通和安全規則。"},{"en":"A good strategy turns broad goals into practical decisions.","zh":"好策略會把大方向轉化為實際決定。"},{"en":"This phrase refers to a plan for managing people, resources, and risks.","zh":"這個短語指管理人員、資源和風險的計劃。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":19},{"front":"incorporate controls on","meaning":"納入對……的控制","examples":[{"en":"The strategy should incorporate controls on visitor numbers.","zh":"該策略應納入對遊客人數的控制。"},{"en":"To incorporate controls on something means to include rules or limits for managing it.","zh":"incorporate controls on something 指加入用來管理某事的規則或限制。"},{"en":"A school policy may incorporate controls on phone use during lessons.","zh":"學校政策可能納入對課堂手機使用的控制。"},{"en":"Controls help prevent problems before behaviour or numbers become unmanageable.","zh":"控制措施有助在行為或數量變得難以管理前預防問題。"},{"en":"This phrase means building management limits into a plan.","zh":"這個短語指把管理限制加入計劃中。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":19},{"front":"visitor numbers","meaning":"遊客人數","examples":[{"en":"The resort may need to control visitor numbers.","zh":"該度假村可能需要控制遊客人數。"},{"en":"Visitor numbers are the number of people who visit a place.","zh":"visitor numbers 指到訪某地的人數。"},{"en":"A museum tracks visitor numbers to decide how many staff are needed.","zh":"博物館追蹤遊客人數，以決定需要多少員工。"},{"en":"High visitor numbers can bring income but also create crowding and environmental pressure.","zh":"高遊客人數可以帶來收入，但也會造成擠迫和環境壓力。"},{"en":"This phrase is important when planning capacity and services.","zh":"這個短語在規劃承載力和服務時很重要。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":19},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Candidates choose the correct letter for each answer.","zh":"考生為每個答案選出正確字母。"},{"en":"To choose the correct letter means to select the option marked by the right letter.","zh":"choose the correct letter 指選出由正確字母標示的選項。"},{"en":"In multiple-choice questions, candidates should check whether the answer is A, B, C, or D.","zh":"在多項選擇題中，考生應檢查答案是 A、B、C 還是 D。"},{"en":"Copying the wrong letter can lose marks even if the idea is understood.","zh":"即使理解意思，抄錯字母也可能失分。"},{"en":"This phrase gives an exam-format instruction.","zh":"這個短語給出考試格式指示。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":19},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Candidates write the correct letter in the answer box.","zh":"考生在答案格中寫上正確字母。"},{"en":"To write the correct letter means to record the letter that matches the correct answer.","zh":"write the correct letter 指寫下與正確答案相配的字母。"},{"en":"A student may know the answer but lose marks by writing C instead of B.","zh":"學生可能知道答案，但因把 B 寫成 C 而失分。"},{"en":"Careful copying matters because answer boxes are marked by what is written there.","zh":"仔細抄寫很重要，因為答案格會根據寫下的內容評分。"},{"en":"This phrase focuses on how to record the answer.","zh":"這個短語著重如何記錄答案。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":19},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Candidates write their answers on their answer sheet.","zh":"考生在答題紙上寫下答案。"},{"en":"On your answer sheet means in the official place where exam answers must be written.","zh":"on your answer sheet 指在考試答案必須寫下的正式位置。"},{"en":"Students may work in the question booklet but must transfer final answers to the answer sheet.","zh":"學生可以在題本中作答，但必須把最終答案轉移到答題紙上。"},{"en":"If answers are not on the answer sheet, they may not be marked.","zh":"如果答案不在答題紙上，可能不會被評改。"},{"en":"This phrase gives a practical exam instruction.","zh":"這個短語給出實際考試指示。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":19},{"front":"become two islands","meaning":"變成兩個島","examples":[{"en":"The question asks how Stradbroke Island became two islands.","zh":"題目問 Stradbroke Island 如何變成兩個島。"},{"en":"To become two islands means one island was divided into two separate island parts.","zh":"become two islands 指一個島被分成兩個分開的島嶼部分。"},{"en":"A sandbar may become two islands if a storm cuts a channel through it.","zh":"如果風暴切出一條水道，沙洲可能變成兩個島。"},{"en":"Erosion or an explosion can weaken land until water separates it.","zh":"侵蝕或爆炸可以削弱土地，直到水把它分開。"},{"en":"This phrase describes a change in physical geography.","zh":"這個短語描述自然地理上的改變。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":19},{"front":"be deliberately destroyed","meaning":"被蓄意摧毀","examples":[{"en":"One option says the ship was deliberately destroyed.","zh":"一個選項說該船被蓄意摧毀。"},{"en":"To be deliberately destroyed means to be damaged or ruined on purpose.","zh":"be deliberately destroyed 指被故意破壞或毀掉。"},{"en":"Old files may be deliberately destroyed to protect private information.","zh":"舊文件可能被蓄意銷毀，以保護私人資料。"},{"en":"If something is deliberately destroyed, the damage is intentional, not accidental.","zh":"如果某物被蓄意摧毀，該損害就是有意造成，而不是意外。"},{"en":"This phrase contrasts planned destruction with chance damage.","zh":"這個短語把有計劃的破壞與偶然損害作對比。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":19},{"front":"divide the island","meaning":"分割島嶼","examples":[{"en":"The explosion helped divide the island into two.","zh":"爆炸幫助把島嶼分成兩部分。"},{"en":"To divide the island means to split one island into separate parts.","zh":"divide the island 指把一個島分成分開的部分。"},{"en":"A new channel can divide a piece of land if water cuts through it completely.","zh":"如果水完全切穿土地，新水道可以分割一塊土地。"},{"en":"Once an island is divided, transport and habitats may change.","zh":"一旦島嶼被分割，交通和棲息地可能改變。"},{"en":"This phrase describes physical separation of land.","zh":"這個短語描述土地的實體分離。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":19},{"front":"wrecked ship","meaning":"失事船隻","examples":[{"en":"Dynamite on a wrecked ship exploded.","zh":"失事船隻上的炸藥爆炸。"},{"en":"A wrecked ship is a ship that has been badly damaged or destroyed, often after an accident at sea.","zh":"wrecked ship 指嚴重受損或被摧毀的船，通常是在海上事故後。"},{"en":"A wrecked ship may leak fuel or cargo into the water.","zh":"失事船隻可能把燃油或貨物漏入水中。"},{"en":"Wrecked ships can become environmental hazards if dangerous materials are onboard.","zh":"如果船上有危險物料，失事船隻可以成為環境危害。"},{"en":"This phrase refers to a ship after a serious accident.","zh":"這個短語指嚴重事故後的船隻。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":20},{"front":"erode the weakened land","meaning":"侵蝕受削弱的土地","examples":[{"en":"The ocean eroded the weakened land.","zh":"海洋侵蝕受削弱的土地。"},{"en":"To erode weakened land means to wear away damaged land by water, wind, or waves.","zh":"erode weakened land 指水、風或海浪把受損土地逐漸磨走。"},{"en":"Rain can erode weakened soil after trees have been removed.","zh":"樹木被移除後，雨水可以侵蝕受削弱的土壤。"},{"en":"Once land is weakened, erosion can happen faster and change its shape.","zh":"一旦土地被削弱，侵蝕可以更快發生並改變其形狀。"},{"en":"This phrase describes gradual removal of already damaged land.","zh":"這個短語描述已受損土地被逐步移除。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":20},{"front":"volcano erupted","meaning":"火山爆發","examples":[{"en":"One option says a volcano erupted on the island.","zh":"一個選項說島上有火山爆發。"},{"en":"A volcano erupted means a volcano released lava, ash, gas, or rock.","zh":"volcano erupted 指火山釋放熔岩、火山灰、氣體或岩石。"},{"en":"When a volcano erupts near a town, people may need to evacuate quickly.","zh":"當火山在城鎮附近爆發，人們可能需要迅速撤離。"},{"en":"Eruptions can change landforms, but this option may not match the passage.","zh":"火山爆發可以改變地貌，但這個選項未必符合文章。"},{"en":"This phrase describes a volcanic event.","zh":"這個短語描述火山事件。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":20},{"front":"conserve freshwater","meaning":"節約淡水","examples":[{"en":"The resort does laundry on the mainland to conserve freshwater.","zh":"度假村在本土洗衣，以節約淡水。"},{"en":"To conserve freshwater means to save and protect supplies of non-salty water.","zh":"conserve freshwater 指節省並保護非鹹水水源。"},{"en":"A family conserves freshwater by fixing leaks and taking shorter showers.","zh":"家庭透過維修漏水和縮短淋浴時間來節約淡水。"},{"en":"On an island, conserving freshwater is important because supplies may be limited.","zh":"在島上，節約淡水很重要，因為水源可能有限。"},{"en":"This phrase describes careful use of usable water.","zh":"這個短語描述謹慎使用可用水源。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":20},{"front":"prevent pollution","meaning":"防止污染","examples":[{"en":"Laundry is done on the mainland to prevent pollution.","zh":"洗衣工作在本土進行，以防止污染。"},{"en":"To prevent pollution means to stop harmful substances from entering air, water, or soil.","zh":"prevent pollution 指阻止有害物質進入空氣、水或土壤。"},{"en":"A factory can prevent pollution by treating wastewater before releasing it.","zh":"工廠可以透過排放前處理污水來防止污染。"},{"en":"Preventing pollution is easier and safer than cleaning it up later.","zh":"防止污染比之後清理更容易也更安全。"},{"en":"This phrase describes stopping environmental harm before it occurs.","zh":"這個短語描述在環境傷害發生前阻止它。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":20},{"front":"avoid the cost of","meaning":"避免……的成本","examples":[{"en":"One option says the resort avoids the cost of installing washing machines.","zh":"一個選項說度假村避免安裝洗衣機的成本。"},{"en":"To avoid the cost of something means to not spend money on it.","zh":"avoid the cost of something 指不花錢在某事上。"},{"en":"A student may borrow textbooks to avoid the cost of buying new ones.","zh":"學生可能借用教科書，以避免購買新書的成本。"},{"en":"Avoiding a cost can save money, but it may not be the main reason for a decision.","zh":"避免成本可以省錢，但未必是決策的主要原因。"},{"en":"This phrase focuses on financial saving.","zh":"這個短語著重財務節省。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":20},{"front":"installing washing machines","meaning":"安裝洗衣機","examples":[{"en":"The resort avoids washing machines on the island.","zh":"度假村避免在島上使用洗衣機。"},{"en":"Installing washing machines means putting washing machines in place so they can be used.","zh":"installing washing machines 指把洗衣機放置並接駁好以便使用。"},{"en":"A hostel may delay installing washing machines if water supply is limited.","zh":"如果供水有限，旅舍可能延遲安裝洗衣機。"},{"en":"Washing machines need water, electricity, space, and drainage.","zh":"洗衣機需要水、電、空間和排水。"},{"en":"This phrase describes adding laundry equipment to a building or site.","zh":"這個短語描述在建築物或場地加入洗衣設備。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":20},{"front":"reduce phosphate levels","meaning":"降低磷酸鹽水平","examples":[{"en":"Laundry management helps reduce phosphate pollution.","zh":"洗衣管理有助減少磷酸鹽污染。"},{"en":"To reduce phosphate levels means to lower the amount of phosphates in water or waste.","zh":"reduce phosphate levels 指降低水或廢物中的磷酸鹽含量。"},{"en":"A town can reduce phosphate levels by using low-phosphate detergents.","zh":"城鎮可以透過使用低磷清潔劑來降低磷酸鹽水平。"},{"en":"Lower phosphate levels can reduce algae growth and improve water quality.","zh":"較低磷酸鹽水平可以減少藻類生長並改善水質。"},{"en":"This phrase describes cutting a specific pollutant.","zh":"這個短語描述減少一種特定污染物。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":20},{"front":"obtain most of its water","meaning":"取得大部分用水","examples":[{"en":"The question asks how the resort obtains most of its water.","zh":"題目問度假村如何取得大部分用水。"},{"en":"To obtain most of its water means to get the largest part of its water supply from a source.","zh":"obtain most of its water 指從某來源取得最大部分的供水。"},{"en":"A farm may obtain most of its water from a river during the dry season.","zh":"農場在旱季可能從河流取得大部分用水。"},{"en":"Knowing where most water comes from helps identify risks and limits.","zh":"知道大部分水來自哪裡，有助識別風險和限制。"},{"en":"This phrase asks about the main water source.","zh":"這個短語詢問主要水源。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":20},{"front":"desalinating seawater","meaning":"海水化淡","examples":[{"en":"One option refers to desalinating seawater.","zh":"一個選項提到海水化淡。"},{"en":"Desalinating seawater means removing salt from seawater so it can be used as fresh water.","zh":"desalinating seawater 指去除海水中的鹽，使其可作淡水使用。"},{"en":"A dry coastal city may consider desalinating seawater when reservoirs are low.","zh":"當水庫水位低，乾旱沿海城市可能考慮海水化淡。"},{"en":"Desalination can provide water but often uses a lot of energy.","zh":"海水化淡可以提供水，但通常耗用大量能源。"},{"en":"This phrase describes turning salty seawater into usable fresh water.","zh":"這個短語描述把鹹海水變成可用淡水。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":20},{"front":"collecting rainfall directly","meaning":"直接收集雨水","examples":[{"en":"One option refers to collecting rainfall directly.","zh":"一個選項提到直接收集雨水。"},{"en":"Collecting rainfall directly means catching rain as it falls, usually from roofs or open surfaces.","zh":"collecting rainfall directly 指雨落下時直接收集，通常從屋頂或開放表面收集。"},{"en":"A school can collect rainfall directly in tanks beside the playground.","zh":"學校可以在操場旁的水箱中直接收集雨水。"},{"en":"Direct rainfall collection works best when storage systems are ready before rain comes.","zh":"直接收集雨水在雨來之前已有儲存系統時最有效。"},{"en":"This phrase describes immediate rainwater capture.","zh":"這個短語描述即時雨水收集。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":21},{"front":"transporting water from the mainland","meaning":"從本土運水","examples":[{"en":"One option says water is transported from the mainland.","zh":"一個選項說水從本土運來。"},{"en":"Transporting water from the mainland means bringing water from the main land area to an island or separate place.","zh":"transporting water from the mainland 指把水從主要陸地運到島嶼或分隔地方。"},{"en":"A small island hotel may transport water from the mainland during a drought.","zh":"小島酒店可能在旱災期間從本土運水。"},{"en":"Transporting water can be expensive and less reliable than using a local source.","zh":"運水可能昂貴，且比使用本地水源較不可靠。"},{"en":"This phrase describes importing water from the main landmass.","zh":"這個短語描述從主要陸地入口水源。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":21},{"front":"boring into groundwater","meaning":"鑽探地下水","examples":[{"en":"The resort obtains water by boring into groundwater.","zh":"度假村透過鑽探地下水取得用水。"},{"en":"Boring into groundwater means drilling into the ground to reach underground water.","zh":"boring into groundwater 指鑽入地下以到達地下水。"},{"en":"A rural community may bore into groundwater when there is no river nearby.","zh":"如果附近沒有河流，鄉村社區可能鑽探地下水。"},{"en":"Drilling must be managed carefully because overuse can lower water levels.","zh":"鑽探必須小心管理，因為過度使用可以降低水位。"},{"en":"This phrase describes accessing groundwater through a drilled hole.","zh":"這個短語描述透過鑽孔取得地下水。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":21},{"front":"energy source","meaning":"能源來源","examples":[{"en":"The question asks what energy source heats water at the resort.","zh":"題目問甚麼能源來源為度假村加熱用水。"},{"en":"An energy source is something that provides power or heat.","zh":"energy source 指提供電力或熱力的東西。"},{"en":"Sunlight, gas, wind, coal, and batteries can all be energy sources.","zh":"陽光、氣體、風、煤和電池都可以是能源來源。"},{"en":"Choosing a cleaner energy source can reduce emissions.","zh":"選擇較清潔能源來源可以減少排放。"},{"en":"This phrase asks where the energy comes from.","zh":"這個短語詢問能源從哪裡來。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":21},{"front":"diesel-powered plant","meaning":"柴油發電廠","examples":[{"en":"The resort does not use a diesel-powered plant as its main system.","zh":"該度假村沒有把柴油發電廠作為主要系統。"},{"en":"A diesel-powered plant is an electricity-generation facility that runs on diesel fuel.","zh":"diesel-powered plant 指使用柴油燃料運作的發電設施。"},{"en":"A remote factory may use a diesel-powered plant when there is no grid connection.","zh":"當沒有電網連接，偏遠工廠可能使用柴油發電廠。"},{"en":"Diesel-powered plants can create emissions and noise.","zh":"柴油發電廠可以產生排放和噪音。"},{"en":"This phrase describes a power system using diesel.","zh":"這個短語描述使用柴油的電力系統。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":21},{"front":"future planning","meaning":"未來規劃","examples":[{"en":"The question asks what future planning should focus on.","zh":"題目問未來規劃應集中於甚麼。"},{"en":"Future planning is preparation for what an organisation or place will need later.","zh":"future planning 指為組織或地方日後需要作準備。"},{"en":"A school’s future planning may include new classrooms if student numbers are rising.","zh":"如果學生人數上升，學校的未來規劃可能包括新課室。"},{"en":"Good future planning prevents short-term decisions from creating long-term problems.","zh":"良好未來規劃可以防止短期決策造成長期問題。"},{"en":"This phrase refers to planning ahead, not only solving today’s issue.","zh":"這個短語指提前規劃，而不只是解決今天問題。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":21},{"front":"sustainable management","meaning":"可持續管理","examples":[{"en":"Future planning should focus on sustainable management.","zh":"未來規劃應集中於可持續管理。"},{"en":"Sustainable management means running an organisation in a way that protects resources and future viability.","zh":"sustainable management 指以保護資源和未來生存能力的方式營運組織。"},{"en":"A café practises sustainable management when it reduces waste and pays staff fairly.","zh":"咖啡店減少廢物並公平支付員工薪酬時，就是實行可持續管理。"},{"en":"Sustainable management balances daily operations with long-term responsibility.","zh":"可持續管理平衡日常營運與長遠責任。"},{"en":"This phrase describes management that can continue without causing serious harm.","zh":"這個短語描述不造成嚴重傷害而能持續的管理。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":21},{"front":"long-term development","meaning":"長遠發展","examples":[{"en":"Future planning should support long-term development.","zh":"未來規劃應支持長遠發展。"},{"en":"Long-term development is growth or improvement planned over many years.","zh":"long-term development 指跨越多年規劃的增長或改善。"},{"en":"A city supports long-term development by building transport that will still work in twenty years.","zh":"城市興建二十年後仍可使用的交通，就是支持長遠發展。"},{"en":"Short-term profit can harm long-term development if resources are used too quickly.","zh":"如果資源被過快使用，短期利潤可以傷害長遠發展。"},{"en":"This phrase focuses on lasting progress.","zh":"這個短語著重持久進步。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":21},{"front":"economic and environmental benefits","meaning":"經濟和環境效益","examples":[{"en":"Sustainability can bring economic and environmental benefits.","zh":"可持續發展可以帶來經濟和環境效益。"},{"en":"Economic and environmental benefits are advantages for money, business, nature, and resource protection.","zh":"economic and environmental benefits 指對金錢、商業、自然和資源保護有好處。"},{"en":"Saving electricity gives economic benefits through lower bills and environmental benefits through fewer emissions.","zh":"節省電力透過降低賬單帶來經濟效益，並透過減少排放帶來環境效益。"},{"en":"A good sustainability plan should help both the business and the environment.","zh":"良好可持續計劃應同時幫助企業和環境。"},{"en":"This phrase combines financial gains with ecological gains.","zh":"這個短語結合財務收益和生態收益。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":21},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Candidates complete the summary below using words from the passage.","zh":"考生使用文章中的字詞完成以下摘要。"},{"en":"To complete the summary below means to fill in missing words in the summary that follows.","zh":"complete the summary below 指填入下方摘要中的缺失字詞。"},{"en":"Students should read the whole summary before choosing answers from the passage.","zh":"學生應先閱讀整段摘要，再從文章中選答案。"},{"en":"Grammar and meaning both help decide which word fits each gap.","zh":"文法和意思都幫助判斷哪個字適合每個空格。"},{"en":"This phrase is a common reading-test instruction.","zh":"這個短語是常見閱讀測驗指示。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":21},{"front":"no more than two words","meaning":"不多於兩個詞","examples":[{"en":"Candidates should choose no more than two words from the passage.","zh":"考生應從文章中選擇不多於兩個詞。"},{"en":"No more than two words means one or two words, but not three or more.","zh":"no more than two words 指一個或兩個詞，但不是三個或更多。"},{"en":"If the limit is no more than two words, “walking trails” is allowed.","zh":"如果限制是不多於兩個詞，“walking trails” 是可以的。"},{"en":"Writing too many words can lose marks even if the idea is correct.","zh":"即使意思正確，寫太多詞也可能失分。"},{"en":"This phrase gives a strict answer-length rule.","zh":"這個短語給出嚴格答案長度規則。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":22},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must be taken from the passage.","zh":"答案必須從文章中選取。"},{"en":"From the passage means using words or information found in the reading text.","zh":"from the passage 指使用閱讀文章中的字詞或資料。"},{"en":"In completion tasks, students should copy the exact words from the passage when required.","zh":"在填充題中，如有要求，學生應從文章中抄錄原字。"},{"en":"Using outside knowledge can lead to wrong answers if the passage says something different.","zh":"如果文章說法不同，使用外部知識可能導致錯誤答案。"},{"en":"This phrase reminds candidates to rely on the text.","zh":"這個短語提醒考生依賴文本。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":22},{"front":"regular service","meaning":"定期服務","examples":[{"en":"Visitors reach the island on a regular ferry service.","zh":"遊客乘坐定期渡輪服務到達該島。"},{"en":"A regular service is a transport service that operates repeatedly according to a schedule.","zh":"regular service 指按照時間表反覆運作的交通服務。"},{"en":"A regular bus service helps students reach school on time every morning.","zh":"定期巴士服務幫助學生每天早上準時到校。"},{"en":"Regular transport makes a place easier to visit because people can plan ahead.","zh":"定期交通令地方較易到訪，因為人們可以提前計劃。"},{"en":"This phrase describes a reliable scheduled service.","zh":"這個短語描述可靠的有時間表服務。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":22},{"front":"provided by the resort","meaning":"由度假村提供","examples":[{"en":"The regular service is provided by the resort.","zh":"該定期服務由度假村提供。"},{"en":"Provided by the resort means the resort offers or operates the service.","zh":"provided by the resort 指該服務由度假村提供或營運。"},{"en":"Towels provided by the hotel should be returned before guests check out.","zh":"由酒店提供的毛巾應在客人退房前歸還。"},{"en":"When transport is provided by the resort, visitors do not need to arrange everything themselves.","zh":"當交通由度假村提供，遊客就不需要自己安排所有事情。"},{"en":"This phrase identifies who supplies the service.","zh":"這個短語指出誰提供服務。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":22},{"front":"tracks for bicycles","meaning":"單車徑","examples":[{"en":"Transport includes walking trails and tracks for bicycles.","zh":"交通包括步行徑和單車徑。"},{"en":"Tracks for bicycles are paths or routes designed for cycling.","zh":"tracks for bicycles 指為騎單車而設計的路徑或路線。"},{"en":"A park with tracks for bicycles keeps cyclists away from busy roads.","zh":"有單車徑的公園可以讓騎單車者遠離繁忙道路。"},{"en":"Bicycle tracks can make transport cleaner, quieter, and safer.","zh":"單車徑可以令交通更清潔、更安靜和更安全。"},{"en":"This phrase refers to cycling routes, not walking paths.","zh":"這個短語指單車路線，而不是步行路。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":22},{"front":"overhead fan","meaning":"頭頂風扇；天花風扇","examples":[{"en":"The overhead fan in the room worked only at high speed.","zh":"房間內的頭頂風扇只能以高速運作。"},{"en":"An overhead fan is a fan fixed above people, usually on the ceiling.","zh":"overhead fan 指固定在人們上方、通常在天花板上的風扇。"},{"en":"An overhead fan can move air around a classroom without using air conditioning.","zh":"頭頂風扇可以在不用冷氣的情況下令課室空氣流動。"},{"en":"If an overhead fan is old, it may be noisy or difficult to adjust.","zh":"如果頭頂風扇老舊，可能嘈吵或難以調節。"},{"en":"This phrase refers to a fan above the room, not a desk fan.","zh":"這個短語指房間上方的風扇，而不是座枱風扇。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":22},{"front":"old air conditioner","meaning":"舊冷氣機","examples":[{"en":"Each room has an old air conditioner.","zh":"每間房都有一部舊冷氣機。"},{"en":"An old air conditioner is an ageing cooling machine that may use more energy or work less well.","zh":"old air conditioner 指老化的冷卻機器，可能較耗電或運作較差。"},{"en":"A classroom with an old air conditioner may feel too cold or not cold enough.","zh":"有舊冷氣機的課室可能太冷或不夠冷。"},{"en":"Old cooling equipment can increase electricity use and maintenance problems.","zh":"老舊冷卻設備可以增加用電量和維修問題。"},{"en":"This phrase gives a detail about comfort and energy efficiency.","zh":"這個短語提供關於舒適度和能源效率的細節。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":22},{"front":"repellent for mosquitoes","meaning":"驅蚊劑","examples":[{"en":"Visitors can buy repellent for mosquitoes on the island.","zh":"遊客可以在島上購買驅蚊劑。"},{"en":"Repellent for mosquitoes is a product used to keep mosquitoes away from the body.","zh":"repellent for mosquitoes 指用來驅趕蚊子遠離身體的產品。"},{"en":"Campers apply repellent for mosquitoes before walking near wetlands at dusk.","zh":"露營者在黃昏走近濕地前會塗驅蚊劑。"},{"en":"Using repellent can reduce bites and lower discomfort during outdoor activities.","zh":"使用驅蚊劑可以減少蚊叮並降低戶外活動中的不適。"},{"en":"This phrase refers to mosquito protection.","zh":"這個短語指防蚊用品。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":22},{"front":"choose three letters","meaning":"選擇三個字母","examples":[{"en":"Candidates choose three letters from the options.","zh":"考生從選項中選擇三個字母。"},{"en":"Choose three letters means select exactly three answer options marked by letters.","zh":"choose three letters 指正好選出三個由字母標示的答案選項。"},{"en":"If a question says choose three letters, writing only two answers is incomplete.","zh":"如果題目說選擇三個字母，只寫兩個答案就是不完整。"},{"en":"Students should check the number required before writing their answers.","zh":"學生在寫答案前應檢查所需數量。"},{"en":"This phrase gives a precise multiple-answer instruction.","zh":"這個短語給出精確的多答案指示。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":22},{"front":"present situation","meaning":"現況","examples":[{"en":"The options describe the present situation at Couran Cove Island Resort.","zh":"選項描述 Couran Cove Island Resort 的現況。"},{"en":"Present situation means the current state or condition of something now.","zh":"present situation 指某事物現在的狀態或情況。"},{"en":"A school report may describe the present situation before suggesting improvements.","zh":"學校報告可能先描述現況，再提出改善。"},{"en":"Understanding the present situation helps people decide what needs to change.","zh":"理解現況幫助人們決定需要改變甚麼。"},{"en":"This phrase focuses on what is true now, not the past or future.","zh":"這個短語著重現在真實情況，而不是過去或未來。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":22},{"front":"adopt environmentally friendly practices","meaning":"採用環保做法","examples":[{"en":"The resort is adopting environmentally friendly practices.","zh":"該度假村正在採用環保做法。"},{"en":"To adopt environmentally friendly practices means to start using methods that reduce harm to nature.","zh":"adopt environmentally friendly practices 指開始使用減少對自然傷害的方法。"},{"en":"A restaurant adopts environmentally friendly practices when it reduces plastic and separates food waste.","zh":"餐廳減少塑膠並分類廚餘時，就是採用環保做法。"},{"en":"Such practices can lower pollution and improve public image.","zh":"這些做法可以降低污染並改善公眾形象。"},{"en":"This phrase describes choosing greener ways to operate.","zh":"這個短語描述選擇較環保的營運方式。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":23},{"front":"conform fully to","meaning":"完全符合","examples":[{"en":"The accommodation does not conform fully to Phase 3.","zh":"該住宿並不完全符合第三階段。"},{"en":"To conform fully to something means to match all parts of a standard, model, or rule.","zh":"conform fully to something 指完全符合某標準、模型或規則的所有部分。"},{"en":"A student’s essay may not conform fully to the task if it misses one required paragraph.","zh":"如果學生文章缺少一個要求段落，可能未完全符合任務。"},{"en":"Partial fit means something matches in some ways but not completely.","zh":"部分符合表示某事在某些方面相配，但不完整。"},{"en":"This phrase is used when judging how closely something follows a standard.","zh":"這個短語用於判斷某事有多接近標準。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":23},{"front":"improve accommodation standard","meaning":"改善住宿水平","examples":[{"en":"The resort should improve its accommodation standard.","zh":"該度假村應改善住宿水平。"},{"en":"To improve accommodation standard means to make guest rooms and lodging quality better.","zh":"improve accommodation standard 指提高客房和住宿質素。"},{"en":"A hostel can improve accommodation standard by replacing old beds and fixing broken fans.","zh":"旅舍可以透過更換舊床和維修壞風扇來改善住宿水平。"},{"en":"Better accommodation standards can increase comfort and guest satisfaction.","zh":"更好的住宿水平可以提高舒適度和客人滿意度。"},{"en":"This phrase focuses on improving where visitors stay.","zh":"這個短語著重改善遊客入住的地方。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":23},{"front":"facilities","meaning":"設施","examples":[{"en":"The resort’s facilities need improvement.","zh":"該度假村的設施需要改善。"},{"en":"Facilities are buildings, rooms, equipment, or services provided for people to use.","zh":"facilities 指供人使用的建築物、房間、設備或服務。"},{"en":"School facilities may include classrooms, toilets, sports fields, and libraries.","zh":"學校設施可能包括課室、廁所、運動場和圖書館。"},{"en":"Poor facilities can reduce comfort, safety, and satisfaction.","zh":"差劣設施可以降低舒適度、安全和滿意度。"},{"en":"This word refers to the practical things that support a place’s use.","zh":"這個詞指支撐某地使用的實用事物。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":23},{"front":"principal visitor group","meaning":"主要遊客群","examples":[{"en":"International tourists are not the resort’s principal visitor group.","zh":"國際遊客並不是該度假村的主要遊客群。"},{"en":"A principal visitor group is the main type of people who visit a place.","zh":"principal visitor group 指到訪某地的主要人群類型。"},{"en":"A children’s museum’s principal visitor group may be families with young children.","zh":"兒童博物館的主要遊客群可能是有幼兒的家庭。"},{"en":"Knowing the principal visitor group helps managers design suitable services and prices.","zh":"了解主要遊客群幫助管理者設計合適服務和價格。"},{"en":"This phrase identifies the most important visitor category.","zh":"這個短語指出最重要的遊客類別。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":23},{"front":"restrict future business expansion","meaning":"限制未來業務擴張","examples":[{"en":"Carrying capacity will restrict future business expansion.","zh":"承載力將限制未來業務擴張。"},{"en":"To restrict future business expansion means to limit how much a business can grow later.","zh":"restrict future business expansion 指限制企業日後能增長多少。"},{"en":"A small kitchen can restrict a restaurant’s future expansion if it cannot serve more customers.","zh":"如果小廚房不能服務更多顧客，它可能限制餐廳未來擴張。"},{"en":"Environmental limits can stop a resort from adding unlimited rooms or visitors.","zh":"環境限制可以阻止度假村無限增加房間或遊客。"},{"en":"This phrase links future growth with a practical limit.","zh":"這個短語把未來增長與實際限制連繫起來。"}],"source":"31 - Eco-Resort Management Practices.pdf","sourcePage":23}],"ielts/reading/passage-2/Practice 32":[{"front":"optimism and health","meaning":"樂觀與健康","examples":[{"en":"The passage explores the relationship between optimism and health.","zh":"文章探討樂觀與健康之間的關係。"},{"en":"Optimism and health refers to how a positive outlook may affect the body and mind.","zh":"optimism and health 指正面人生觀可能如何影響身體和心理。"},{"en":"A school counsellor may discuss optimism and health when teaching students how to cope with exam stress.","zh":"學校輔導員教學生應對考試壓力時，可能會討論樂觀與健康。"},{"en":"If optimism reduces stress, it may also support better sleep, stronger motivation, and healthier behaviour.","zh":"如果樂觀能減少壓力，它也可能支持更好睡眠、更強動力和更健康行為。"},{"en":"The phrase connects mental attitude with physical and emotional well-being.","zh":"這個短語把心理態度與身體及情緒健康連起來。"}],"source":"32 - Optimism and Health.pdf","sourcePage":1},{"front":"mindset is all","meaning":"心態決定一切","examples":[{"en":"The writer suggests that mindset is all when facing a difficult year.","zh":"作者暗示面對艱難一年時，心態決定一切。"},{"en":"Mindset is all means the way you think is the most important factor in a situation.","zh":"mindset is all 指你的思考方式是某情況中最重要的因素。"},{"en":"A student facing a hard exam may cope better if she believes improvement is possible.","zh":"面對困難考試的學生，如果相信自己可以進步，可能應對得更好。"},{"en":"When people see problems as manageable, they are more likely to keep trying.","zh":"當人們把問題視為可處理，他們更可能繼續嘗試。"},{"en":"The phrase stresses attitude as the key to how someone responds.","zh":"這個短語強調態度是人如何回應的關鍵。"}],"source":"32 - Optimism and Health.pdf","sourcePage":1},{"front":"set the template for","meaning":"為……定下模式","examples":[{"en":"How you start the year will set the template for the rest.","zh":"你如何開始這一年會為餘下部分定下模式。"},{"en":"To set the template for something means to create the pattern that later events may follow.","zh":"set the template for something 指建立之後事件可能跟隨的模式。"},{"en":"A teacher’s first lesson can set the template for a calm and organised term.","zh":"老師第一堂課可以為一個平靜而有組織的學期定下模式。"},{"en":"If the beginning is disciplined and hopeful, later behaviour may copy that pattern.","zh":"如果開始時有紀律又有希望，之後的行為可能會跟隨該模式。"},{"en":"The phrase suggests that early habits shape what comes afterwards.","zh":"這個短語暗示早期習慣塑造之後發展。"}],"source":"32 - Optimism and Health.pdf","sourcePage":1},{"front":"the rest","meaning":"餘下部分","examples":[{"en":"How you start the year may affect the rest of the year.","zh":"你如何開始這一年可能影響這一年餘下部分。"},{"en":"The rest means the remaining part of something after the first part has happened.","zh":"the rest 指某事開頭部分發生後剩下的部分。"},{"en":"If a student wastes the morning, she may still use the rest of the day well.","zh":"如果學生浪費了早上，她仍可以善用一天餘下部分。"},{"en":"A strong start can make the rest of a project easier to manage.","zh":"強而有力的開始可以令項目餘下部分更容易管理。"},{"en":"The phrase refers to what is left, not the beginning.","zh":"這個短語指剩下部分，而不是開頭。"}],"source":"32 - Optimism and Health.pdf","sourcePage":1},{"front":"scientifically backed","meaning":"有科學支持的","examples":[{"en":"Two scientifically backed character traits hold the key.","zh":"兩種有科學支持的性格特質掌握關鍵。"},{"en":"Scientifically backed means supported by research, studies, or evidence.","zh":"scientifically backed 指受到研究、實驗或證據支持。"},{"en":"A scientifically backed study method is more reliable than a random tip from social media.","zh":"有科學支持的學習方法比社交媒體上的隨機建議更可靠。"},{"en":"If advice is scientifically backed, people have more reason to trust and practise it.","zh":"如果建議有科學支持，人們就更有理由相信並實踐它。"},{"en":"The phrase separates evidence-based claims from simple opinion.","zh":"這個短語把以證據為基礎的聲稱與單純意見分開。"}],"source":"32 - Optimism and Health.pdf","sourcePage":1},{"front":"character traits","meaning":"性格特質","examples":[{"en":"Optimism and resilience are important character traits.","zh":"樂觀和抗逆力是重要性格特質。"},{"en":"Character traits are stable qualities in a person’s personality or behaviour.","zh":"character traits 指一個人性格或行為中較穩定的品質。"},{"en":"Patience, honesty, and courage are character traits that teachers often praise.","zh":"耐性、誠實和勇氣都是老師常稱讚的性格特質。"},{"en":"Strong character traits can affect how people deal with pressure and failure.","zh":"強大的性格特質可以影響人們如何處理壓力和失敗。"},{"en":"The phrase describes personal qualities, not temporary moods.","zh":"這個短語描述個人品質，而不是短暫心情。"}],"source":"32 - Optimism and Health.pdf","sourcePage":1},{"front":"hold the key","meaning":"掌握關鍵","examples":[{"en":"Optimism and resilience hold the key to coping with difficulty.","zh":"樂觀和抗逆力掌握應對困難的關鍵。"},{"en":"To hold the key means to be the most important factor in solving or understanding something.","zh":"hold the key 指是解決或理解某事的最重要因素。"},{"en":"Clear feedback may hold the key to improving a student’s writing.","zh":"清晰回饋可能掌握改善學生寫作的關鍵。"},{"en":"If resilience helps people recover, it may hold the key to surviving hard times.","zh":"如果抗逆力幫助人恢復，它可能掌握熬過艱難時期的關鍵。"},{"en":"The phrase points to the central solution or explanation.","zh":"這個短語指出核心解決方法或解釋。"}],"source":"32 - Optimism and Health.pdf","sourcePage":1},{"front":"optimism","meaning":"樂觀","examples":[{"en":"Optimism can help people respond better to stress.","zh":"樂觀可以幫助人們更好地回應壓力。"},{"en":"Optimism is the tendency to expect good outcomes or believe things can improve.","zh":"optimism 指傾向期待好結果，或相信情況可以改善。"},{"en":"A student shows optimism when she treats a failed test as a chance to study differently.","zh":"當學生把測驗失敗視為改變溫習方法的機會，她就是表現出樂觀。"},{"en":"Optimism can encourage people to keep trying instead of giving up too quickly.","zh":"樂觀可以鼓勵人們繼續嘗試，而不是太快放棄。"},{"en":"The word describes hopeful thinking, not ignoring every problem.","zh":"這個詞描述有希望的思考，而不是忽視所有問題。"}],"source":"32 - Optimism and Health.pdf","sourcePage":1},{"front":"resilience","meaning":"抗逆力；復原力","examples":[{"en":"Resilience helps people recover from setbacks.","zh":"抗逆力幫助人們從挫折中恢復。"},{"en":"Resilience is the ability to recover, adapt, and keep going after difficulty.","zh":"resilience 指在困難後恢復、適應並繼續前進的能力。"},{"en":"A student shows resilience when she fails an interview but prepares better for the next one.","zh":"學生面試失敗後為下一次準備得更好，就是表現出抗逆力。"},{"en":"Resilience can reduce the damage of failure because people learn and try again.","zh":"抗逆力可以減少失敗帶來的傷害，因為人們會學習並再次嘗試。"},{"en":"The word describes recovery strength, not never feeling upset.","zh":"這個詞描述恢復力量，而不是從不感到難過。"}],"source":"32 - Optimism and Health.pdf","sourcePage":1},{"front":"the prospect leaves you feeling","meaning":"這個前景令你感到……","examples":[{"en":"The prospect of the year may leave you feeling pessimistic.","zh":"這一年的前景可能令你感到悲觀。"},{"en":"The prospect leaves you feeling means the thought of a future situation makes you feel a certain way.","zh":"the prospect leaves you feeling 指想到未來某情況會令你產生某種感受。"},{"en":"The prospect of moving schools may leave a child feeling nervous.","zh":"轉校的前景可能令孩子感到緊張。"},{"en":"If the future looks difficult, it can leave people feeling worried before anything has happened.","zh":"如果未來看起來困難，它可以在事情發生前已令人感到擔心。"},{"en":"The phrase links an expected future with an emotional reaction.","zh":"這個短語把預期中的未來與情緒反應連起來。"}],"source":"32 - Optimism and Health.pdf","sourcePage":1},{"front":"pessimistically spineless","meaning":"悲觀得沒有骨氣；悲觀軟弱","examples":[{"en":"The difficult prospect may leave some people feeling pessimistically spineless.","zh":"困難前景可能令一些人感到悲觀得沒有骨氣。"},{"en":"Pessimistically spineless means so negative and discouraged that a person feels weak or unable to act.","zh":"pessimistically spineless 指負面和灰心得令一個人感到軟弱或無法行動。"},{"en":"A student may feel pessimistically spineless after several rejections if she believes trying again is pointless.","zh":"如果學生幾次被拒後相信再試也無用，她可能感到悲觀軟弱。"},{"en":"This feeling can stop people from taking useful action because they expect failure.","zh":"這種感覺可以阻止人們採取有用行動，因為他們預期會失敗。"},{"en":"The phrase is colourful and critical, suggesting defeat before the fight begins.","zh":"這個短語語氣生動並帶批評，暗示未戰先敗。"}],"source":"32 - Optimism and Health.pdf","sourcePage":1},{"front":"significantly boost","meaning":"顯著提升","examples":[{"en":"You can significantly boost optimism and resilience.","zh":"你可以顯著提升樂觀和抗逆力。"},{"en":"To significantly boost something means to increase it in a clear and important way.","zh":"significantly boost something 指以清楚而重要的方式增加某事。"},{"en":"Regular exercise can significantly boost a student’s energy during exam season.","zh":"定期運動可以在考試季顯著提升學生精力。"},{"en":"If practice increases resilience strongly, people may cope better with future stress.","zh":"如果練習能大幅增加抗逆力，人們日後可能更好應對壓力。"},{"en":"The phrase suggests a meaningful improvement, not a tiny change.","zh":"這個短語暗示有意義的改善，而不是微小變化。"}],"source":"32 - Optimism and Health.pdf","sourcePage":2},{"front":"these qualities","meaning":"這些特質","examples":[{"en":"People can boost these qualities through practice.","zh":"人們可以透過練習提升這些特質。"},{"en":"These qualities refers to the traits or abilities just mentioned.","zh":"these qualities 指剛才提到的特質或能力。"},{"en":"Confidence and patience are useful qualities, and students can develop these qualities over time.","zh":"信心和耐性都是有用特質，學生可以隨時間培養這些特質。"},{"en":"If people practise helpful habits, these qualities may become stronger and more natural.","zh":"如果人們練習有幫助的習慣，這些特質可能變得更強和更自然。"},{"en":"The phrase points back to earlier named characteristics.","zh":"這個短語指回早前提到的性格特徵。"}],"source":"32 - Optimism and Health.pdf","sourcePage":2},{"front":"faced with","meaning":"面對……","examples":[{"en":"Faced with a plummeting economy, optimism may seem unrealistic.","zh":"面對急速下滑的經濟，樂觀可能顯得不現實。"},{"en":"Faced with means having to deal with a difficult situation or problem.","zh":"faced with 指必須處理某個困難情況或問題。"},{"en":"Faced with a strict deadline, a student may make a clear timetable.","zh":"面對嚴格限期，學生可能制定清晰時間表。"},{"en":"When people are faced with crisis, their attitude affects whether they freeze or act.","zh":"當人們面對危機，態度會影響他們是停滯還是行動。"},{"en":"The phrase introduces the challenge someone must confront.","zh":"這個短語引入某人必須面對的挑戰。"}],"source":"32 - Optimism and Health.pdf","sourcePage":2},{"front":"plummeting economy","meaning":"急速下滑的經濟","examples":[{"en":"People faced 12 months of a plummeting economy.","zh":"人們面對十二個月急速下滑的經濟。"},{"en":"A plummeting economy is an economy that is falling very quickly and seriously.","zh":"plummeting economy 指非常快速而嚴重下跌的經濟。"},{"en":"Shops may close during a plummeting economy because customers spend less.","zh":"在急速下滑的經濟中，商店可能因顧客消費減少而倒閉。"},{"en":"If the economy plummets, unemployment and financial stress may rise.","zh":"如果經濟急跌，失業和財政壓力可能上升。"},{"en":"The phrase describes a sharp economic decline, not a small slowdown.","zh":"這個短語描述急劇經濟下降，而不是小幅放緩。"}],"source":"32 - Optimism and Health.pdf","sourcePage":2},{"front":"rising human distress","meaning":"日益增加的人類痛苦","examples":[{"en":"The year brought a plummeting economy and rising human distress.","zh":"這一年帶來急速下滑的經濟和日益增加的人類痛苦。"},{"en":"Rising human distress means increasing worry, suffering, pressure, or emotional pain among people.","zh":"rising human distress 指人們的憂慮、痛苦、壓力或情緒痛苦增加。"},{"en":"A community may face rising human distress after job losses and rent increases.","zh":"在失業和租金上升後，社區可能面對日益增加的人類痛苦。"},{"en":"When distress rises, more people may need counselling, financial help, or social support.","zh":"當痛苦增加，更多人可能需要輔導、財政援助或社會支援。"},{"en":"The phrase connects social crisis with people’s emotional suffering.","zh":"這個短語把社會危機與人的情緒痛苦連起來。"}],"source":"32 - Optimism and Health.pdf","sourcePage":2},{"front":"staunchly maintaining","meaning":"堅定維持","examples":[{"en":"Staunchly maintaining a rosy view may seem unrealistic.","zh":"堅定維持樂觀看法可能顯得不現實。"},{"en":"Staunchly maintaining something means firmly keeping a belief, position, or attitude.","zh":"staunchly maintaining something 指堅定保持某信念、立場或態度。"},{"en":"A teacher may staunchly maintain that every student can improve with the right support.","zh":"老師可能堅定維持每個學生都能在合適支援下進步的看法。"},{"en":"Firmly holding a positive view can help people act, but it may look unrealistic in crisis.","zh":"堅定保持正面看法可以幫助人行動，但在危機中可能看似不現實。"},{"en":"The phrase suggests strong and determined commitment.","zh":"這個短語暗示強而有力、堅決的投入。"}],"source":"32 - Optimism and Health.pdf","sourcePage":2},{"front":"rosy view","meaning":"樂觀看法","examples":[{"en":"An optimistic person may maintain a rosy view of the future.","zh":"樂觀的人可能維持對未來的樂觀看法。"},{"en":"A rosy view is an overly positive or hopeful way of seeing a situation.","zh":"rosy view 指對某情況過分正面或充滿希望的看法。"},{"en":"A student may have a rosy view of university life before experiencing deadlines and pressure.","zh":"學生在經歷限期和壓力前，可能對大學生活有樂觀看法。"},{"en":"A rosy view can encourage confidence, but it may ignore some real difficulties.","zh":"樂觀看法可以鼓勵信心，但也可能忽略一些真實困難。"},{"en":"The phrase often suggests optimism with a slightly unrealistic tone.","zh":"這個短語常暗示帶少許不現實色彩的樂觀。"}],"source":"32 - Optimism and Health.pdf","sourcePage":2},{"front":"deludedly Pollyannaish","meaning":"天真盲目地樂觀","examples":[{"en":"A rosy view may seem deludedly Pollyannaish during a crisis.","zh":"在危機中，樂觀看法可能顯得天真盲目地樂觀。"},{"en":"Deludedly Pollyannaish means blindly and unrealistically cheerful despite serious problems.","zh":"deludedly Pollyannaish 指即使有嚴重問題仍盲目而不現實地愉快。"},{"en":"A manager who says everything is perfect during mass layoffs may sound deludedly Pollyannaish.","zh":"大量裁員期間仍說一切完美的經理，可能聽起來天真盲目地樂觀。"},{"en":"When optimism ignores facts, people may stop trusting the person who expresses it.","zh":"當樂觀忽視事實，人們可能不再信任表達它的人。"},{"en":"The phrase criticises optimism that seems naïve rather than helpful.","zh":"這個短語批評看似天真而非有用的樂觀。"}],"source":"32 - Optimism and Health.pdf","sourcePage":2},{"front":"encounter the optimism paradox","meaning":"遇上樂觀悖論","examples":[{"en":"Here we encounter the optimism paradox.","zh":"在這裏，我們遇上樂觀悖論。"},{"en":"To encounter the optimism paradox means to meet the surprising idea that optimism can be both unrealistic and useful.","zh":"encounter the optimism paradox 指遇到樂觀既可能不現實又可能有用的驚人想法。"},{"en":"A student may encounter this paradox when hope helps her try again despite poor odds.","zh":"當希望幫助學生即使勝算低也再次嘗試時，她可能遇上這個悖論。"},{"en":"The paradox appears because seeing reality clearly is not always best for action.","zh":"這個悖論出現，是因為看清現實並不總是最有利於行動。"},{"en":"The phrase introduces a contradiction about the value of optimism.","zh":"這個短語引入關於樂觀價值的矛盾。"}],"source":"32 - Optimism and Health.pdf","sourcePage":2},{"front":"optimism paradox","meaning":"樂觀悖論","examples":[{"en":"The optimism paradox is that unrealistic thinking may be useful.","zh":"樂觀悖論是，不現實的想法可能有用。"},{"en":"The optimism paradox is the idea that a partly unrealistic positive belief can still improve effort and outcomes.","zh":"optimism paradox 指部分不現實的正面信念仍可改善努力和結果的想法。"},{"en":"A job seeker may believe she will succeed, and that belief keeps her applying after rejection.","zh":"求職者可能相信自己會成功，而這種信念令她在被拒後繼續申請。"},{"en":"If optimism keeps people active, it may help even when it is not perfectly accurate.","zh":"如果樂觀令人保持行動，即使它不完全準確，也可能有幫助。"},{"en":"The phrase describes the surprising benefit of hopeful thinking.","zh":"這個短語描述有希望思考的驚人好處。"}],"source":"32 - Optimism and Health.pdf","sourcePage":2},{"front":"emeritus professor","meaning":"榮休教授","examples":[{"en":"Brice Pitt is an emeritus professor of psychiatry.","zh":"Brice Pitt 是精神科榮休教授。"},{"en":"An emeritus professor is a retired professor who keeps an honorary academic title.","zh":"emeritus professor 指退休後仍保留榮譽學術職銜的教授。"},{"en":"A university may invite an emeritus professor to give a public lecture because of long experience.","zh":"大學可能邀請榮休教授因其長期經驗而舉行公開講座。"},{"en":"The title shows respect for past academic work even after retirement.","zh":"這個職銜顯示對退休後過往學術工作的尊重。"},{"en":"The phrase refers to senior academic status, not an active full-time post.","zh":"這個短語指資深學術身份，而不是全職現任職位。"}],"source":"32 - Optimism and Health.pdf","sourcePage":2},{"front":"psychiatry of old age","meaning":"老年精神科","examples":[{"en":"Brice Pitt specialises in the psychiatry of old age.","zh":"Brice Pitt 專門研究老年精神科。"},{"en":"Psychiatry of old age is the branch of medicine that studies and treats mental health in older adults.","zh":"psychiatry of old age 指研究和治療長者心理健康的醫學分支。"},{"en":"A doctor in this field may help elderly patients with depression, memory problems, or anxiety.","zh":"這個領域的醫生可能幫助有抑鬱、記憶問題或焦慮的長者病人。"},{"en":"As populations age, this field becomes more important for healthcare systems.","zh":"隨着人口老化，這個領域對醫療系統變得更重要。"},{"en":"The phrase refers to mental healthcare for older people.","zh":"這個短語指長者的精神健康照護。"}],"source":"32 - Optimism and Health.pdf","sourcePage":3},{"front":"see things as they really are","meaning":"看清事情的真實面貌","examples":[{"en":"Depressive people may see things as they really are.","zh":"抑鬱的人可能看清事情的真實面貌。"},{"en":"To see things as they really are means to view reality clearly without hopeful distortion.","zh":"see things as they really are 指不帶希望式扭曲地清楚看待現實。"},{"en":"A student may see her weak grammar as it really is after receiving detailed corrections.","zh":"學生收到詳細改正後，可能看清自己文法弱點的真實情況。"},{"en":"Clear realism can help planning, but too much bleak realism may reduce motivation.","zh":"清楚現實感可以幫助規劃，但過度灰暗的現實感可能降低動力。"},{"en":"The phrase contrasts accurate perception with optimistic interpretation.","zh":"這個短語把準確認知與樂觀詮釋作對比。"}],"source":"32 - Optimism and Health.pdf","sourcePage":3},{"front":"a disadvantage from","meaning":"從……角度來看是不利因素","examples":[{"en":"Seeing reality too clearly can be a disadvantage from an evolutionary point of view.","zh":"從演化角度來看，太清楚看見現實可能是不利因素。"},{"en":"A disadvantage from a particular point of view is something that creates weakness under that perspective.","zh":"disadvantage from a particular point of view 指從某角度看會造成弱點的事。"},{"en":"Spending too much time checking every detail can be a disadvantage from a productivity point of view.","zh":"從生產力角度看，花太多時間檢查每個細節可能是不利因素。"},{"en":"If realism stops people from trying, it may be a disadvantage for survival and progress.","zh":"如果現實感阻止人嘗試，它對生存和進步可能不利。"},{"en":"The phrase explains why something may be harmful in a specific framework.","zh":"這個短語解釋為何某事在特定框架中可能有害。"}],"source":"32 - Optimism and Health.pdf","sourcePage":3},{"front":"evolutionary point of view","meaning":"演化角度","examples":[{"en":"Optimism may be useful from an evolutionary point of view.","zh":"從演化角度看，樂觀可能有用。"},{"en":"An evolutionary point of view considers how a trait may help survival and reproduction over time.","zh":"evolutionary point of view 會考慮某特質如何隨時間幫助生存和繁殖。"},{"en":"From an evolutionary point of view, fear can be useful because it helps people avoid danger.","zh":"從演化角度看，恐懼可能有用，因為它幫助人避開危險。"},{"en":"If optimism keeps people trying after failure, it may have helped humans survive hardships.","zh":"如果樂觀令人在失敗後繼續嘗試，它可能曾幫助人類熬過困難。"},{"en":"The phrase looks at behaviour through long-term human survival.","zh":"這個短語從長期人類生存角度看行為。"}],"source":"32 - Optimism and Health.pdf","sourcePage":3},{"front":"evolutionary equipment","meaning":"演化裝備","examples":[{"en":"Optimism is described as a piece of evolutionary equipment.","zh":"樂觀被描述為一件演化裝備。"},{"en":"Evolutionary equipment means a trait or ability that helps humans survive or cope over time.","zh":"evolutionary equipment 指幫助人類長期生存或應對的特質或能力。"},{"en":"Fear, cooperation, and curiosity can be seen as evolutionary equipment in different situations.","zh":"恐懼、合作和好奇心在不同情況中都可被視為演化裝備。"},{"en":"If optimism helps people persist, it functions like mental equipment for survival.","zh":"如果樂觀幫助人堅持，它就像生存用的心理裝備。"},{"en":"The phrase is metaphorical and treats optimism as a useful human tool.","zh":"這個短語是比喻，把樂觀視為有用的人類工具。"}],"source":"32 - Optimism and Health.pdf","sourcePage":3},{"front":"carried us through","meaning":"幫助我們渡過","examples":[{"en":"Optimism carried humans through millennia of setbacks.","zh":"樂觀幫助人類渡過數千年的挫折。"},{"en":"To carry someone through difficulty means to help them survive or continue during hard times.","zh":"carry someone through difficulty 指幫助某人在艱難時期生存或繼續下去。"},{"en":"Family support may carry a student through a stressful exam year.","zh":"家庭支持可能幫助學生渡過壓力很大的考試年。"},{"en":"If optimism keeps people moving, it can carry them through repeated failures.","zh":"如果樂觀令人繼續前進，它可以幫助人渡過反覆失敗。"},{"en":"The phrase suggests support over a long and difficult period.","zh":"這個短語暗示在漫長困難時期中的支撐。"}],"source":"32 - Optimism and Health.pdf","sourcePage":3},{"front":"millennia of setbacks","meaning":"數千年的挫折","examples":[{"en":"Humans have faced millennia of setbacks.","zh":"人類面對過數千年的挫折。"},{"en":"Millennia of setbacks means thousands of years of difficulties, failures, and obstacles.","zh":"millennia of setbacks 指數千年來的困難、失敗和障礙。"},{"en":"Human history contains millennia of setbacks, including wars, disease, famine, and disasters.","zh":"人類歷史包含數千年的挫折，包括戰爭、疾病、饑荒和災難。"},{"en":"Long experience of setbacks may explain why traits like hope and resilience became valuable.","zh":"長期面對挫折可能解釋為何希望和抗逆力等特質變得有價值。"},{"en":"The phrase makes difficulty sound very long-lasting and historical.","zh":"這個短語令困難聽起來非常漫長和具歷史感。"}],"source":"32 - Optimism and Health.pdf","sourcePage":3},{"front":"have plenty to be happy about","meaning":"有很多值得開心的事","examples":[{"en":"Optimists have plenty to be happy about.","zh":"樂觀者有很多值得開心的事。"},{"en":"To have plenty to be happy about means to have many reasons to feel pleased or hopeful.","zh":"have plenty to be happy about 指有許多感到高興或有希望的理由。"},{"en":"A student who has improved steadily has plenty to be happy about, even before final results arrive.","zh":"穩步進步的學生，即使最終成績未到，也有很多值得開心的事。"},{"en":"If optimism improves health and success, optimists have real reasons for cheerfulness.","zh":"如果樂觀改善健康和成功，樂觀者就有真正值得高興的理由。"},{"en":"The phrase points to positive evidence, not empty happiness.","zh":"這個短語指出正面證據，而不是空洞快樂。"}],"source":"32 - Optimism and Health.pdf","sourcePage":3},{"front":"in other words","meaning":"換句話說","examples":[{"en":"In other words, optimism can improve the odds of success.","zh":"換句話說，樂觀可以提高成功機會。"},{"en":"In other words introduces the same idea again in a clearer or simpler way.","zh":"in other words 用更清楚或更簡單的方式重新表達同一想法。"},{"en":"This essay lacks examples; in other words, the argument is too abstract.","zh":"這篇作文缺乏例子；換句話說，論點太抽象。"},{"en":"Writers use the phrase to restate a point so readers understand it better.","zh":"作者使用這個短語重述觀點，讓讀者更好理解。"},{"en":"The phrase signals explanation, not a completely new idea.","zh":"這個短語表示解釋，而不是全新想法。"}],"source":"32 - Optimism and Health.pdf","sourcePage":3},{"front":"convince yourself that","meaning":"說服自己相信","examples":[{"en":"If you can convince yourself that things will get better, you may keep trying.","zh":"如果你能說服自己相信情況會好轉，你可能會繼續嘗試。"},{"en":"To convince yourself that something is true means to make yourself believe it.","zh":"convince yourself that something is true 指令自己相信某事是真的。"},{"en":"A nervous speaker may convince herself that one mistake will not ruin the whole presentation.","zh":"緊張的演講者可能說服自己相信一個錯誤不會毀掉整場簡報。"},{"en":"If people believe improvement is possible, they are more likely to take useful action.","zh":"如果人們相信改善是可能的，他們更可能採取有用行動。"},{"en":"The phrase describes self-persuasion that affects behaviour.","zh":"這個短語描述會影響行為的自我說服。"}],"source":"32 - Optimism and Health.pdf","sourcePage":3},{"front":"things will get better","meaning":"情況會好轉","examples":[{"en":"Optimists believe that things will get better.","zh":"樂觀者相信情況會好轉。"},{"en":"Things will get better means the situation will improve in the future.","zh":"things will get better 指情況將來會改善。"},{"en":"A student may tell herself that things will get better after she asks for help and starts revising.","zh":"學生可能告訴自己，只要求助並開始溫習，情況會好轉。"},{"en":"Believing improvement is possible can make people more willing to keep working.","zh":"相信改善是可能的，可以令人更願意繼續努力。"},{"en":"The phrase expresses hope about the future.","zh":"這個短語表達對未來的希望。"}],"source":"32 - Optimism and Health.pdf","sourcePage":3},{"front":"the odds of it happening","meaning":"事情發生的機會","examples":[{"en":"The odds of success may improve when people stay optimistic.","zh":"當人們保持樂觀，成功的機會可能提高。"},{"en":"The odds of it happening means the chance or probability that something will occur.","zh":"odds of it happening 指某事發生的機會或可能性。"},{"en":"The odds of passing an exam improve when a student studies regularly for several weeks.","zh":"如果學生連續幾星期定期溫習，通過考試的機會會提高。"},{"en":"If optimism keeps people trying, it can raise the odds of success.","zh":"如果樂觀令人繼續嘗試，它可以提高成功機會。"},{"en":"The phrase describes likelihood, not certainty.","zh":"這個短語描述可能性，而不是確定性。"}],"source":"32 - Optimism and Health.pdf","sourcePage":4},{"front":"keep on playing the game","meaning":"繼續參與；繼續堅持","examples":[{"en":"Optimists keep on playing the game when times get tough.","zh":"當日子變得艱難時，樂觀者會繼續堅持。"},{"en":"To keep on playing the game means to continue participating and trying despite difficulty.","zh":"keep on playing the game 指即使困難仍繼續參與和嘗試。"},{"en":"A job seeker keeps on playing the game when she applies again after several rejections.","zh":"求職者幾次被拒後仍再次申請，就是繼續參與這場遊戲。"},{"en":"Continuing to act gives people more chances than giving up completely.","zh":"繼續行動比完全放棄給人更多機會。"},{"en":"The phrase is metaphorical and means staying engaged.","zh":"這個短語是比喻，意思是保持投入。"}],"source":"32 - Optimism and Health.pdf","sourcePage":4},{"front":"in this light","meaning":"從這個角度看","examples":[{"en":"In this light, optimism is a way of explaining setbacks.","zh":"從這個角度看，樂觀是一種解釋挫折的方式。"},{"en":"In this light means from this point of view or with this understanding.","zh":"in this light 指從這個觀點或理解方式看。"},{"en":"A failed test can look useful in this light if it shows exactly what to practise.","zh":"如果測驗失敗清楚顯示要練習甚麼，從這個角度看它可能有用。"},{"en":"Changing the angle of interpretation can change how people feel and act.","zh":"改變詮釋角度可以改變人們的感受和行動。"},{"en":"The phrase introduces a new way to view the same situation.","zh":"這個短語引入看待同一情況的新方式。"}],"source":"32 - Optimism and Health.pdf","sourcePage":4},{"front":"a habitual way of","meaning":"一種慣常的……方式","examples":[{"en":"Optimism is a habitual way of explaining setbacks to yourself.","zh":"樂觀是一種慣常地向自己解釋挫折的方式。"},{"en":"A habitual way of doing something is a repeated pattern of thinking or behaviour.","zh":"habitual way of doing something 指重複出現的思考或行為模式。"},{"en":"Checking a timetable every Sunday can become a habitual way of preparing for the week.","zh":"每星期日檢查時間表可以成為準備一週的一種慣常方式。"},{"en":"If optimism becomes habitual, people may automatically look for lessons after failure.","zh":"如果樂觀成為習慣，人們可能會自動在失敗後尋找教訓。"},{"en":"The phrase describes a regular mental habit, not a one-time choice.","zh":"這個短語描述規律心理習慣，而不是一次性選擇。"}],"source":"32 - Optimism and Health.pdf","sourcePage":4},{"front":"explaining your setbacks to yourself","meaning":"向自己解釋挫折","examples":[{"en":"Optimism is a way of explaining your setbacks to yourself.","zh":"樂觀是一種向自己解釋挫折的方式。"},{"en":"Explaining your setbacks to yourself means telling yourself why difficulties happened and what they mean.","zh":"explaining your setbacks to yourself 指告訴自己困難為何發生以及它代表甚麼。"},{"en":"After failing a quiz, a student may tell herself she used the wrong method, not that she is stupid.","zh":"小測失敗後，學生可能告訴自己是方法錯了，而不是自己愚蠢。"},{"en":"The way people explain setbacks can affect whether they give up or improve.","zh":"人們解釋挫折的方式會影響他們放棄還是改善。"},{"en":"The phrase describes inner self-talk after failure.","zh":"這個短語描述失敗後的內在自我對話。"}],"source":"32 - Optimism and Health.pdf","sourcePage":4},{"front":"setbacks","meaning":"挫折","examples":[{"en":"Optimists explain setbacks differently from pessimists.","zh":"樂觀者解釋挫折的方式不同於悲觀者。"},{"en":"Setbacks are problems, failures, or delays that interrupt progress.","zh":"setbacks 指打斷進展的問題、失敗或延誤。"},{"en":"A student faces a setback when illness prevents her from attending lessons for a week.","zh":"當學生因病一星期不能上課，她就面對挫折。"},{"en":"Setbacks can slow progress, but they can also show what needs to change.","zh":"挫折可以放慢進展，但也可以顯示需要改變甚麼。"},{"en":"The word describes obstacles, not permanent defeat.","zh":"這個詞描述障礙，而不是永久失敗。"}],"source":"32 - Optimism and Health.pdf","sourcePage":4},{"front":"Learned Optimism","meaning":"《學會樂觀》","examples":[{"en":"Martin Seligman wrote a book called Learned Optimism.","zh":"Martin Seligman 寫了一本名為《學會樂觀》的書。"},{"en":"Learned Optimism refers to the idea that people can train themselves to think more hopefully.","zh":"Learned Optimism 指人們可以訓練自己更有希望地思考的想法。"},{"en":"A student practises learned optimism when she challenges the thought that one mistake means total failure.","zh":"當學生挑戰「一個錯誤代表完全失敗」的想法時，她就在練習學會樂觀。"},{"en":"If optimism can be learned, people are not trapped by their first reaction to difficulty.","zh":"如果樂觀可以學習，人們就不會被自己對困難的第一反應困住。"},{"en":"The phrase names both a book title and a teachable mental skill.","zh":"這個短語既是書名，也指一種可教的心理技能。"}],"source":"32 - Optimism and Health.pdf","sourcePage":4},{"front":"when times get tough","meaning":"當日子變得艱難時","examples":[{"en":"Optimists do better when times get tough.","zh":"當日子變得艱難時，樂觀者表現較好。"},{"en":"When times get tough means when life becomes difficult, stressful, or uncertain.","zh":"when times get tough 指生活變得困難、壓力大或不確定時。"},{"en":"Families may need to work together when times get tough and money is tight.","zh":"當日子變得艱難、金錢緊絀時，家庭可能需要一起合作。"},{"en":"Difficult periods test whether people can stay calm and keep acting.","zh":"困難時期會考驗人們能否保持冷靜並繼續行動。"},{"en":"The phrase describes challenging periods in life or society.","zh":"這個短語描述人生或社會中的挑戰時期。"}],"source":"32 - Optimism and Health.pdf","sourcePage":4},{"front":"do better than","meaning":"比……做得更好","examples":[{"en":"Optimists do better than pessimists in difficult times.","zh":"樂觀者在困難時期比悲觀者做得更好。"},{"en":"To do better than someone means to perform more successfully than that person or group.","zh":"do better than someone 指比某人或某群體表現更成功。"},{"en":"Students who revise regularly often do better than those who wait until the last night.","zh":"定期溫習的學生通常比等到最後一晚才溫習的人做得更好。"},{"en":"If optimism improves coping, optimists may recover more quickly than pessimists.","zh":"如果樂觀改善應對能力，樂觀者可能比悲觀者更快恢復。"},{"en":"The phrase compares performance or results.","zh":"這個短語比較表現或結果。"}],"source":"32 - Optimism and Health.pdf","sourcePage":4},{"front":"pessimists","meaning":"悲觀者","examples":[{"en":"Pessimists tend to respond less well to stress.","zh":"悲觀者往往對壓力反應較差。"},{"en":"Pessimists are people who usually expect bad outcomes or focus on what may go wrong.","zh":"pessimists 指通常預期壞結果或集中於可能出錯之處的人。"},{"en":"A pessimist may believe a difficult essay is hopeless before even starting it.","zh":"悲觀者可能在開始寫困難作文前已認為沒有希望。"},{"en":"If pessimists expect failure, they may try less or give up earlier.","zh":"如果悲觀者預期失敗，他們可能較少嘗試或較早放棄。"},{"en":"The word describes a negative outlook, not simply careful planning.","zh":"這個詞描述負面人生觀，而不只是謹慎計劃。"}],"source":"32 - Optimism and Health.pdf","sourcePage":4},{"front":"more successful at work","meaning":"在工作上更成功","examples":[{"en":"Optimists are often more successful at work.","zh":"樂觀者通常在工作上更成功。"},{"en":"More successful at work means achieving better results, progress, or recognition in a job.","zh":"more successful at work 指在工作中取得更好結果、進步或認可。"},{"en":"An employee may be more successful at work if she treats mistakes as chances to learn.","zh":"如果員工把錯誤視為學習機會，她可能在工作上更成功。"},{"en":"Optimism can support workplace success because it encourages persistence and problem-solving.","zh":"樂觀可以支持職場成功，因為它鼓勵堅持和解決問題。"},{"en":"The phrase refers to career performance, not only salary.","zh":"這個短語指事業表現，而不只是薪金。"}],"source":"32 - Optimism and Health.pdf","sourcePage":4},{"front":"respond better to stress","meaning":"對壓力反應較好","examples":[{"en":"Optimists respond better to stress than pessimists.","zh":"樂觀者對壓力的反應比悲觀者好。"},{"en":"To respond better to stress means to handle pressure in a healthier or more effective way.","zh":"respond better to stress 指以更健康或更有效方式處理壓力。"},{"en":"A student responds better to stress when she makes a plan instead of panicking.","zh":"當學生制定計劃而不是恐慌，她就是對壓力反應較好。"},{"en":"Good responses to stress can protect mood, health, and performance.","zh":"對壓力的良好反應可以保護心情、健康和表現。"},{"en":"The phrase focuses on reaction under pressure.","zh":"這個短語重點是壓力下的反應。"}],"source":"32 - Optimism and Health.pdf","sourcePage":5},{"front":"suffer fewer depressive episodes","meaning":"較少經歷抑鬱發作","examples":[{"en":"Optimists suffer fewer depressive episodes.","zh":"樂觀者較少經歷抑鬱發作。"},{"en":"To suffer fewer depressive episodes means to experience fewer periods of serious depression.","zh":"suffer fewer depressive episodes 指經歷較少段嚴重抑鬱時期。"},{"en":"A patient may suffer fewer depressive episodes after receiving therapy and social support.","zh":"病人接受治療和社會支援後，可能較少經歷抑鬱發作。"},{"en":"If optimism helps protect mood, it may reduce how often depressive periods occur.","zh":"如果樂觀有助保護心情，它可能減少抑鬱期出現的頻率。"},{"en":"The phrase describes reduced frequency of depressive illness or symptoms.","zh":"這個短語描述抑鬱疾病或症狀頻率降低。"}],"source":"32 - Optimism and Health.pdf","sourcePage":5},{"front":"depressive episodes","meaning":"抑鬱發作","examples":[{"en":"The research links optimism with fewer depressive episodes.","zh":"研究把樂觀與較少抑鬱發作聯繫起來。"},{"en":"Depressive episodes are periods when a person experiences significant depression symptoms.","zh":"depressive episodes 指一個人經歷明顯抑鬱症狀的時期。"},{"en":"A depressive episode may include low mood, loss of interest, tiredness, and hopelessness.","zh":"抑鬱發作可能包括情緒低落、失去興趣、疲倦和絕望感。"},{"en":"Fewer depressive episodes can mean better quality of life and more stable daily functioning.","zh":"較少抑鬱發作可以代表更好生活質素和更穩定日常功能。"},{"en":"The phrase refers to periods of depression, not one sad moment.","zh":"這個短語指抑鬱時期，而不是一刻傷心。"}],"source":"32 - Optimism and Health.pdf","sourcePage":5},{"front":"achieve more personal goals","meaning":"達成更多個人目標","examples":[{"en":"Optimists tend to achieve more personal goals.","zh":"樂觀者往往達成更多個人目標。"},{"en":"To achieve more personal goals means to reach more of the aims one sets for oneself.","zh":"achieve more personal goals 指實現更多自己為自己訂下的目標。"},{"en":"A student may achieve more personal goals if she believes effort can improve her results.","zh":"如果學生相信努力能改善結果，她可能達成更多個人目標。"},{"en":"Optimism can support goal achievement because people keep working after small failures.","zh":"樂觀可以支持目標達成，因為人們在小失敗後仍繼續努力。"},{"en":"The phrase focuses on self-chosen aims, not only public success.","zh":"這個短語重點是自己選擇的目標，而不只是公開成功。"}],"source":"32 - Optimism and Health.pdf","sourcePage":5},{"front":"studies also show that","meaning":"研究亦顯示","examples":[{"en":"Studies also show that belief can help with financial pressure.","zh":"研究亦顯示信念可以幫助應對財政壓力。"},{"en":"Studies also show that means additional research provides evidence for another point.","zh":"studies also show that 指額外研究為另一觀點提供證據。"},{"en":"Studies also show that regular sleep improves memory and attention.","zh":"研究亦顯示定期睡眠能改善記憶和注意力。"},{"en":"Using this phrase helps writers add supporting evidence rather than only personal opinion.","zh":"使用這個短語幫助作者加入支持證據，而不只是個人意見。"},{"en":"The phrase introduces another research-based finding.","zh":"這個短語引入另一個以研究為基礎的發現。"}],"source":"32 - Optimism and Health.pdf","sourcePage":5},{"front":"help with","meaning":"幫助應對……","examples":[{"en":"Belief can help with the financial pinch.","zh":"信念可以幫助應對財政壓力。"},{"en":"To help with something means to make a problem easier to manage.","zh":"help with something 指令某問題較容易處理。"},{"en":"A clear budget can help with saving money during a difficult month.","zh":"清晰預算可以幫助應對困難月份中的儲蓄問題。"},{"en":"If optimism reduces panic, it may help with practical financial decisions.","zh":"如果樂觀減少恐慌，它可能幫助人作出實際財務決定。"},{"en":"The phrase describes support or assistance in dealing with a situation.","zh":"這個短語描述處理情況時的支援或協助。"}],"source":"32 - Optimism and Health.pdf","sourcePage":5},{"front":"financial pinch","meaning":"財政壓力；手頭緊","examples":[{"en":"Optimism may help people deal with the financial pinch.","zh":"樂觀可能幫助人們應對財政壓力。"},{"en":"A financial pinch is a period of money pressure when people have less to spend.","zh":"financial pinch 指人們可花的錢減少、出現金錢壓力的時期。"},{"en":"A family may feel a financial pinch when rent rises and overtime work disappears.","zh":"當租金上升而加班工作消失，家庭可能感到手頭緊。"},{"en":"Financial pressure can force people to cut costs, delay purchases, or seek extra work.","zh":"財政壓力可以迫使人們削減開支、延遲購物或尋找額外工作。"},{"en":"The phrase is informal and refers to being short of money.","zh":"這個短語較口語，指缺錢。"}],"source":"32 - Optimism and Health.pdf","sourcePage":5},{"front":"social forecaster","meaning":"社會趨勢預測員","examples":[{"en":"Chad Wallens is a social forecaster at the Henley Centre.","zh":"Chad Wallens 是 Henley Centre 的社會趨勢預測員。"},{"en":"A social forecaster studies social trends and predicts how people may behave in the future.","zh":"social forecaster 指研究社會趨勢並預測人們未來可能如何行動的人。"},{"en":"A social forecaster may examine shopping habits, family choices, or attitudes to work.","zh":"社會趨勢預測員可能研究購物習慣、家庭選擇或工作態度。"},{"en":"Businesses and governments use such forecasts to prepare for changing public behaviour.","zh":"企業和政府使用這類預測來準備應對公眾行為變化。"},{"en":"The phrase refers to someone who predicts social change, not the weather.","zh":"這個短語指預測社會變化的人，不是天氣預報員。"}],"source":"32 - Optimism and Health.pdf","sourcePage":5},{"front":"surveyed","meaning":"調查","examples":[{"en":"Chad Wallens surveyed middle-class Britons’ beliefs about income.","zh":"Chad Wallens 調查了英國中產人士對收入的看法。"},{"en":"To survey people means to ask them questions in order to collect information.","zh":"survey people 指透過向人提問來收集資料。"},{"en":"A school may survey students about lunch choices before changing the menu.","zh":"學校可能在更改餐單前調查學生對午餐選擇的意見。"},{"en":"Surveys help researchers compare opinions across a group.","zh":"調查幫助研究人員比較一個群體中的意見。"},{"en":"The word describes systematic questioning, not casual chatting.","zh":"這個詞描述有系統提問，而不是隨便聊天。"}],"source":"32 - Optimism and Health.pdf","sourcePage":5},{"front":"middle-class Britons","meaning":"英國中產人士","examples":[{"en":"The survey examined middle-class Britons’ beliefs about income.","zh":"該調查研究英國中產人士對收入的看法。"},{"en":"Middle-class Britons are British people with a moderate or comfortable social and economic position.","zh":"middle-class Britons 指在社會和經濟上處於中等或較舒適位置的英國人。"},{"en":"Middle-class families may own homes, have stable jobs, and worry about school fees or mortgages.","zh":"中產家庭可能有物業、穩定工作，並擔心學費或按揭。"},{"en":"Studying one social group helps researchers see how attitudes vary by class.","zh":"研究一個社會群體幫助研究人員了解態度如何因階層而異。"},{"en":"The phrase identifies a specific social group in Britain.","zh":"這個短語指出英國的一個特定社會群體。"}],"source":"32 - Optimism and Health.pdf","sourcePage":5},{"front":"beliefs about income","meaning":"對收入的看法","examples":[{"en":"The study looked at people’s beliefs about income.","zh":"該研究考察人們對收入的看法。"},{"en":"Beliefs about income are ideas people have about how much money they earn or need.","zh":"beliefs about income 指人們對自己賺多少錢或需要多少錢的想法。"},{"en":"Two workers with similar salaries may have different beliefs about whether they are well paid.","zh":"兩位薪金相似的員工，對自己是否待遇好可能有不同看法。"},{"en":"These beliefs can affect spending, saving, stress, and happiness.","zh":"這些看法可以影響消費、儲蓄、壓力和快樂。"},{"en":"The phrase focuses on perception of money, not only the amount itself.","zh":"這個短語重點是對金錢的感知，而不只是金額本身。"}],"source":"32 - Optimism and Health.pdf","sourcePage":5},{"front":"feel wealthiest","meaning":"感覺最富有","examples":[{"en":"Some people feel wealthiest even without having much more money.","zh":"有些人即使沒有多很多錢，仍感覺最富有。"},{"en":"To feel wealthiest means to feel richest or most financially comfortable compared with others.","zh":"feel wealthiest 指相比其他人感到最富有或最有財政舒適感。"},{"en":"A family may feel wealthiest when their bills are manageable and they feel secure.","zh":"當家庭能應付帳單並感到安全時，可能感覺最富有。"},{"en":"Feeling wealthy may depend on attitude, expectations, and spending habits as well as income.","zh":"感覺富有可能取決於態度、期望和消費習慣，也取決於收入。"},{"en":"The phrase describes perceived wealth, not always actual wealth.","zh":"這個短語描述感知上的財富，不一定是實際財富。"}],"source":"32 - Optimism and Health.pdf","sourcePage":6},{"front":"feel poorest","meaning":"感覺最貧窮","examples":[{"en":"Some people feel poorest despite having similar amounts of money.","zh":"有些人即使有相似數量的金錢，仍感覺最貧窮。"},{"en":"To feel poorest means to feel least financially secure or least wealthy compared with others.","zh":"feel poorest 指相比其他人感到最沒有財政安全感或最不富有。"},{"en":"A student may feel poorest among friends if everyone else spends freely on weekends.","zh":"如果朋友週末都花錢很自由，學生可能在朋友之中感覺最貧窮。"},{"en":"Feeling poor can come from comparison, fear, or high expectations, not only low income.","zh":"感覺貧窮可以來自比較、恐懼或高期望，而不只是低收入。"},{"en":"The phrase describes subjective financial feeling.","zh":"這個短語描述主觀財務感受。"}],"source":"32 - Optimism and Health.pdf","sourcePage":6},{"front":"almost the same amount of money","meaning":"幾乎相同數量的金錢","examples":[{"en":"The two groups had almost the same amount of money.","zh":"兩組人有幾乎相同數量的金錢。"},{"en":"Almost the same amount of money means the sums were very similar, with only small differences.","zh":"almost the same amount of money 指金額非常相似，只有小差別。"},{"en":"Two classmates may spend almost the same amount of money on lunch but feel differently about the cost.","zh":"兩位同學午餐花幾乎相同數量的金錢，但對成本感受不同。"},{"en":"If money levels are similar but feelings differ, attitude may explain the difference.","zh":"如果金錢水平相似但感受不同，態度可能解釋差異。"},{"en":"The phrase highlights similarity in actual financial resources.","zh":"這個短語突出實際財務資源相似。"}],"source":"32 - Optimism and Health.pdf","sourcePage":6},{"front":"at their disposal","meaning":"可供支配","examples":[{"en":"The groups had similar amounts of money at their disposal.","zh":"這些組別有相似數量的金錢可供支配。"},{"en":"At their disposal means available for them to use.","zh":"at their disposal 指可供他們使用。"},{"en":"A student with a quiet room and laptop at her disposal can study more easily.","zh":"如果學生有安靜房間和手提電腦可供使用，她可以較容易學習。"},{"en":"Resources at a person’s disposal affect what choices they can realistically make.","zh":"一個人可支配的資源會影響他能實際作出甚麼選擇。"},{"en":"The phrase refers to what someone can access and use.","zh":"這個短語指某人可以接觸並使用的東西。"}],"source":"32 - Optimism and Health.pdf","sourcePage":6},{"front":"attitudes and behaviour patterns","meaning":"態度和行為模式","examples":[{"en":"Their attitudes and behaviour patterns were different.","zh":"他們的態度和行為模式不同。"},{"en":"Attitudes and behaviour patterns are the ways people think, feel, and repeatedly act.","zh":"attitudes and behaviour patterns 指人們思考、感受和重複行動的方式。"},{"en":"Two students may have different attitudes and behaviour patterns toward homework: one plans early, the other delays.","zh":"兩名學生對功課可能有不同態度和行為模式：一個早計劃，另一個拖延。"},{"en":"These patterns can affect whether people save money, seek help, or avoid problems.","zh":"這些模式可以影響人們是否儲蓄、求助或逃避問題。"},{"en":"The phrase connects inner outlook with repeated actions.","zh":"這個短語把內在看法與重複行動連起來。"}],"source":"32 - Optimism and Health.pdf","sourcePage":6},{"front":"different from one another","meaning":"彼此不同","examples":[{"en":"Their attitudes were different from one another.","zh":"他們的態度彼此不同。"},{"en":"Different from one another means not the same as each other.","zh":"different from one another 指彼此不相同。"},{"en":"Two siblings may be different from one another even if they grow up in the same home.","zh":"即使在同一個家庭長大，兩名兄弟姊妹也可能彼此不同。"},{"en":"Differences in attitude can create different choices and outcomes.","zh":"態度上的差異可以造成不同選擇和結果。"},{"en":"The phrase is used to compare members of the same group.","zh":"這個短語用於比較同一群體中的成員。"}],"source":"32 - Optimism and Health.pdf","sourcePage":6},{"front":"something else to be cheerful about","meaning":"另有值得高興的事","examples":[{"en":"Optimists have something else to be cheerful about.","zh":"樂觀者另有值得高興的事。"},{"en":"Something else to be cheerful about means another reason to feel happy or hopeful.","zh":"something else to be cheerful about 指另一個感到快樂或有希望的理由。"},{"en":"A student who passes an exam and improves her speaking has something else to be cheerful about.","zh":"通過考試又改善口語的學生，另有值得高興的事。"},{"en":"Extra positive evidence can strengthen optimism because it gives hope a concrete base.","zh":"額外正面證據可以加強樂觀，因為它給希望一個具體基礎。"},{"en":"The phrase adds another encouraging point.","zh":"這個短語加入另一個鼓舞人心的重點。"}],"source":"32 - Optimism and Health.pdf","sourcePage":6},{"front":"in general","meaning":"一般來說","examples":[{"en":"In general, optimists are more robust.","zh":"一般來說，樂觀者更強健。"},{"en":"In general means usually or in most cases.","zh":"in general 指通常或在大多數情況下。"},{"en":"In general, students learn better when examples are clear and practical.","zh":"一般來說，例子清楚實用時，學生學得更好。"},{"en":"The phrase allows exceptions while describing a broad pattern.","zh":"這個短語在描述廣泛模式時容許例外。"},{"en":"It is useful for making cautious general statements.","zh":"它適合用於作出謹慎的一般陳述。"}],"source":"32 - Optimism and Health.pdf","sourcePage":6},{"front":"more robust","meaning":"更強健；更有抵抗力","examples":[{"en":"Optimists are generally more robust.","zh":"樂觀者一般更強健。"},{"en":"More robust means stronger, healthier, or better able to withstand difficulty.","zh":"more robust 指更強壯、更健康或更能承受困難。"},{"en":"A student with good sleep and strong routines may be more robust during exam season.","zh":"有良好睡眠和穩定規律的學生，在考試季可能更有抵抗力。"},{"en":"Robust people may recover faster when stress or illness appears.","zh":"強健的人在壓力或疾病出現時可能恢復更快。"},{"en":"The phrase suggests resistance and strength.","zh":"這個短語暗示抵抗力和力量。"}],"source":"32 - Optimism and Health.pdf","sourcePage":6},{"front":"study of 660 volunteers","meaning":"一項涉及 660 名志願者的研究","examples":[{"en":"A study of 660 volunteers found a link between positive thinking and lifespan.","zh":"一項涉及660名志願者的研究發現正面思考與壽命之間有關聯。"},{"en":"A study of 660 volunteers means research involving 660 people who agreed to take part.","zh":"study of 660 volunteers 指涉及660名同意參與人士的研究。"},{"en":"A study of volunteers may ask people about habits, health, and attitudes over time.","zh":"志願者研究可能長期詢問人們的習慣、健康和態度。"},{"en":"A larger group can make findings more persuasive than a tiny sample.","zh":"較大群體可以令發現比極小樣本更有說服力。"},{"en":"The phrase identifies the size and type of research sample.","zh":"這個短語指出研究樣本的大小和類型。"}],"source":"32 - Optimism and Health.pdf","sourcePage":6},{"front":"thinking positively","meaning":"正面思考","examples":[{"en":"Thinking positively can add years to a person’s life.","zh":"正面思考可以為一個人的壽命增加多年。"},{"en":"Thinking positively means focusing on hope, possibility, and constructive explanations.","zh":"thinking positively 指集中於希望、可能性和建設性解釋。"},{"en":"A student thinks positively when she says, “I can improve if I practise this grammar point.”","zh":"當學生說「如果我練習這個文法點，我可以進步」時，她就是正面思考。"},{"en":"Positive thinking may reduce stress and encourage healthier choices.","zh":"正面思考可能減少壓力並鼓勵更健康選擇。"},{"en":"The phrase means helpful optimism, not pretending problems do not exist.","zh":"這個短語指有幫助的樂觀，而不是假裝問題不存在。"}],"source":"32 - Optimism and Health.pdf","sourcePage":6},{"front":"adds an average of","meaning":"平均增加……","examples":[{"en":"Thinking positively adds an average of seven years to your life.","zh":"正面思考平均為你的壽命增加七年。"},{"en":"Adds an average of means increases something by a typical amount across a group.","zh":"adds an average of 指在一個群體中以典型數量增加某事。"},{"en":"Regular reading may add an average of several points to students’ vocabulary scores.","zh":"定期閱讀可能平均為學生詞彙分數增加幾分。"},{"en":"An average increase does not mean every person gains exactly the same amount.","zh":"平均增加不代表每個人都得到完全相同數量。"},{"en":"The phrase reports a general statistical effect.","zh":"這個短語報告一般統計效果。"}],"source":"32 - Optimism and Health.pdf","sourcePage":7},{"front":"seven years to your life","meaning":"壽命增加七年","examples":[{"en":"Positive thinking may add seven years to your life.","zh":"正面思考可能令你的壽命增加七年。"},{"en":"Seven years to your life means seven additional years of lifespan.","zh":"seven years to your life 指額外七年的壽命。"},{"en":"A health habit that adds years to life is considered important because it affects long-term survival.","zh":"能增加壽命的健康習慣被視為重要，因為它影響長期存活。"},{"en":"If attitude is linked to lifespan, mental health may influence physical health more than expected.","zh":"如果態度與壽命有關，心理健康對身體健康的影響可能比預期大。"},{"en":"The phrase expresses a possible increase in longevity.","zh":"這個短語表達壽命可能增加。"}],"source":"32 - Optimism and Health.pdf","sourcePage":7},{"front":"identified a physical mechanism","meaning":"找出一種生理機制","examples":[{"en":"Research claims to have identified a physical mechanism behind optimism’s benefits.","zh":"研究聲稱已找出樂觀好處背後的一種生理機制。"},{"en":"To identify a physical mechanism means to find the biological process that explains an effect.","zh":"identify a physical mechanism 指找出解釋某效果的生物過程。"},{"en":"Doctors may identify a physical mechanism linking exercise with lower blood pressure.","zh":"醫生可能找出運動與降低血壓之間的生理機制。"},{"en":"Finding a mechanism makes a health claim stronger because it explains how the effect happens.","zh":"找到機制會令健康聲稱更有力，因為它解釋效果如何發生。"},{"en":"The phrase connects research findings with bodily processes.","zh":"這個短語把研究發現與身體過程連起來。"}],"source":"32 - Optimism and Health.pdf","sourcePage":7},{"front":"physical mechanism","meaning":"生理機制","examples":[{"en":"There may be a physical mechanism behind optimism’s health effects.","zh":"樂觀的健康效果背後可能有一種生理機制。"},{"en":"A physical mechanism is a bodily process that explains how something affects health.","zh":"physical mechanism 指解釋某事如何影響健康的身體過程。"},{"en":"A physical mechanism behind exercise benefits may involve stronger heart function.","zh":"運動好處背後的生理機制可能涉及更強心臟功能。"},{"en":"If optimism affects the immune system, that could be one physical mechanism.","zh":"如果樂觀影響免疫系統，那可能是一種生理機制。"},{"en":"The phrase refers to how the body produces an effect.","zh":"這個短語指身體如何產生某效果。"}],"source":"32 - Optimism and Health.pdf","sourcePage":7},{"front":"behind this","meaning":"在這背後","examples":[{"en":"Researchers tried to identify the mechanism behind this effect.","zh":"研究人員嘗試找出這一效果背後的機制。"},{"en":"Behind this means explaining the cause or process underneath the result just mentioned.","zh":"behind this 指解釋剛提到結果之下的原因或過程。"},{"en":"A teacher may ask what is behind a student’s sudden improvement.","zh":"老師可能詢問學生突然進步背後的原因。"},{"en":"Looking behind an effect helps people understand causes rather than only outcomes.","zh":"探究效果背後，有助人們理解原因，而不只是結果。"},{"en":"The phrase points to the explanation beneath a visible result.","zh":"這個短語指出可見結果下方的解釋。"}],"source":"32 - Optimism and Health.pdf","sourcePage":7},{"front":"Harvard Medical School","meaning":"哈佛醫學院","examples":[{"en":"A Harvard Medical School study examined optimism and lung function.","zh":"一項哈佛醫學院研究檢視樂觀和肺功能。"},{"en":"Harvard Medical School is a well-known medical school associated with medical research and training.","zh":"Harvard Medical School 是一所著名醫學院，與醫學研究和培訓有關。"},{"en":"A study from a medical school may carry weight because it is linked to specialist expertise.","zh":"來自醫學院的研究可能較有分量，因為它與專門知識有關。"},{"en":"Mentioning the institution helps readers judge the source of the research.","zh":"提到機構有助讀者判斷研究來源。"},{"en":"The phrase names the research institution involved.","zh":"這個短語命名參與研究的機構。"}],"source":"32 - Optimism and Health.pdf","sourcePage":7},{"front":"significantly better lung function","meaning":"明顯較好的肺功能","examples":[{"en":"Optimists have significantly better lung function.","zh":"樂觀者有明顯較好的肺功能。"},{"en":"Significantly better lung function means the lungs work noticeably and measurably better.","zh":"significantly better lung function 指肺部運作明顯並可量度地較好。"},{"en":"A patient with better lung function may climb stairs with less breathlessness.","zh":"肺功能較好的病人上樓梯時可能較少氣喘。"},{"en":"If attitude is linked to lung function, mental outlook may affect physical health.","zh":"如果態度與肺功能有關，心理看法可能影響身體健康。"},{"en":"The phrase describes a meaningful health difference, not a tiny one.","zh":"這個短語描述有意義的健康差異，而不是微小差別。"}],"source":"32 - Optimism and Health.pdf","sourcePage":7},{"front":"lung function","meaning":"肺功能","examples":[{"en":"The study linked optimism with better lung function.","zh":"該研究把樂觀與較好肺功能聯繫起來。"},{"en":"Lung function is how well the lungs take in oxygen and move air in and out.","zh":"lung function 指肺部吸收氧氣和進出空氣的能力。"},{"en":"Doctors may test lung function when a patient has asthma or long-term coughing.","zh":"當病人有哮喘或長期咳嗽，醫生可能測試肺功能。"},{"en":"Poor lung function can make exercise and daily tasks harder.","zh":"肺功能差可以令運動和日常任務更困難。"},{"en":"The phrase refers to the working ability of the lungs.","zh":"這個短語指肺部的運作能力。"}],"source":"32 - Optimism and Health.pdf","sourcePage":7},{"front":"lead author","meaning":"主要作者","examples":[{"en":"Dr. Rosalind Wright was the lead author of the study.","zh":"Rosalind Wright 博士是該研究的主要作者。"},{"en":"The lead author is the main researcher responsible for writing or directing a study.","zh":"lead author 指負責撰寫或主導研究的主要研究人員。"},{"en":"In a group project, the lead author may organise the report and combine everyone’s sections.","zh":"在小組項目中，主要作者可能組織報告並整合每個人的部分。"},{"en":"Naming the lead author helps readers know who led the research.","zh":"命名主要作者幫助讀者知道誰主導研究。"},{"en":"The phrase identifies the principal author of a study.","zh":"這個短語指出研究的主要作者。"}],"source":"32 - Optimism and Health.pdf","sourcePage":7},{"front":"somehow strengthens","meaning":"以某種方式增強","examples":[{"en":"Attitude somehow strengthens the immune system.","zh":"態度以某種方式增強免疫系統。"},{"en":"Somehow strengthens means improves or makes stronger, though the exact process may not be fully clear.","zh":"somehow strengthens 指改善或令某物更強，雖然確切過程未必完全清楚。"},{"en":"Regular encouragement somehow strengthens a nervous student’s confidence over time.","zh":"定期鼓勵會隨時間以某種方式增強緊張學生的信心。"},{"en":"If attitude affects stress hormones, it may strengthen health in indirect ways.","zh":"如果態度影響壓力荷爾蒙，它可能以間接方式增強健康。"},{"en":"The word somehow shows uncertainty about the exact mechanism.","zh":"somehow 這個詞顯示對確切機制仍有不確定。"}],"source":"32 - Optimism and Health.pdf","sourcePage":7},{"front":"immune system","meaning":"免疫系統","examples":[{"en":"A positive attitude may strengthen the immune system.","zh":"正面態度可能增強免疫系統。"},{"en":"The immune system is the body’s defence system against infections and disease.","zh":"immune system 指身體對抗感染和疾病的防衛系統。"},{"en":"Sleep, nutrition, and vaccination can help support the immune system.","zh":"睡眠、營養和疫苗接種可以幫助支持免疫系統。"},{"en":"If stress weakens immunity, a calmer outlook may indirectly protect health.","zh":"如果壓力削弱免疫力，較平靜的人生觀可能間接保護健康。"},{"en":"The phrase refers to the body’s protective biological system.","zh":"這個短語指身體的保護性生物系統。"}],"source":"32 - Optimism and Health.pdf","sourcePage":7},{"front":"preliminary studies","meaning":"初步研究","examples":[{"en":"Preliminary studies on heart patients suggest that outlook matters.","zh":"關於心臟病人的初步研究顯示人生觀很重要。"},{"en":"Preliminary studies are early studies that give first evidence but may need more confirmation.","zh":"preliminary studies 指提供初步證據、但可能需要更多確認的早期研究。"},{"en":"Preliminary studies may show a new teaching method looks useful before larger trials are done.","zh":"初步研究可能顯示一種新教學方法看似有用，之後才進行大型試驗。"},{"en":"Early findings can guide future research, but they should be interpreted cautiously.","zh":"早期發現可以引導未來研究，但應謹慎解讀。"},{"en":"The phrase signals that evidence is promising but not final.","zh":"這個短語表示證據有希望但不是最終定論。"}],"source":"32 - Optimism and Health.pdf","sourcePage":8},{"front":"heart patients","meaning":"心臟病人","examples":[{"en":"Preliminary studies looked at heart patients.","zh":"初步研究檢視了心臟病人。"},{"en":"Heart patients are people receiving care for heart disease or heart-related problems.","zh":"heart patients 指因心臟疾病或心臟相關問題接受照護的人。"},{"en":"Doctors may monitor heart patients after surgery to check recovery and risk.","zh":"醫生可能在手術後監察心臟病人，以檢查恢復和風險。"},{"en":"If outlook affects heart patients’ outcomes, psychological support may become part of treatment.","zh":"如果人生觀影響心臟病人結果，心理支援可能成為治療的一部分。"},{"en":"The phrase identifies a medical group with heart conditions.","zh":"這個短語指出有心臟問題的醫療群體。"}],"source":"32 - Optimism and Health.pdf","sourcePage":8},{"front":"by changing a person’s outlook","meaning":"透過改變一個人的看法","examples":[{"en":"By changing a person’s outlook, doctors may reduce mortality risk.","zh":"透過改變一個人的看法，醫生可能降低死亡風險。"},{"en":"By changing a person’s outlook means by helping someone see life or problems differently.","zh":"by changing a person’s outlook 指透過幫助某人以不同方式看待人生或問題。"},{"en":"A counsellor may help a student change her outlook from “I always fail” to “I can improve.”","zh":"輔導員可能幫助學生把看法由「我總是失敗」改成「我可以進步」。"},{"en":"A changed outlook can lead to calmer decisions, better habits, and more hope.","zh":"看法改變可以帶來較冷靜決定、更好習慣和更多希望。"},{"en":"The phrase describes attitude change as a possible route to better outcomes.","zh":"這個短語描述態度改變作為改善結果的可能途徑。"}],"source":"32 - Optimism and Health.pdf","sourcePage":8},{"front":"outlook","meaning":"看法；人生觀","examples":[{"en":"A person’s outlook may affect their health.","zh":"一個人的人生觀可能影響其健康。"},{"en":"Outlook is the way a person generally sees life, the future, or a situation.","zh":"outlook 指一個人通常如何看待人生、未來或某情況。"},{"en":"A student with a hopeful outlook may treat mistakes as part of learning.","zh":"有希望人生觀的學生可能把錯誤視為學習的一部分。"},{"en":"Outlook can affect mood, choices, relationships, and stress levels.","zh":"人生觀可以影響心情、選擇、關係和壓力水平。"},{"en":"The word describes a general attitude or worldview.","zh":"這個詞描述一般態度或世界觀。"}],"source":"32 - Optimism and Health.pdf","sourcePage":8},{"front":"reduce mortality risk","meaning":"降低死亡風險","examples":[{"en":"A changed outlook may reduce mortality risk.","zh":"改變後的人生觀可能降低死亡風險。"},{"en":"To reduce mortality risk means to lower the chance of dying from a condition or within a period.","zh":"reduce mortality risk 指降低因某病或在某時期內死亡的機會。"},{"en":"Quitting smoking can reduce mortality risk for people with heart disease.","zh":"戒煙可以降低心臟病患者的死亡風險。"},{"en":"If optimism improves health behaviour, it may reduce risk indirectly.","zh":"如果樂觀改善健康行為，它可能間接降低風險。"},{"en":"The phrase is medical and focuses on lowering death risk.","zh":"這個短語屬醫學用語，重點是降低死亡風險。"}],"source":"32 - Optimism and Health.pdf","sourcePage":8},{"front":"mortality risk","meaning":"死亡風險","examples":[{"en":"Positive thinking may reduce mortality risk.","zh":"正面思考可能降低死亡風險。"},{"en":"Mortality risk is the chance that a person may die within a given time or from a specific cause.","zh":"mortality risk 指一個人在特定時間內或因特定原因死亡的機會。"},{"en":"Doctors assess mortality risk when deciding how urgently a patient needs treatment.","zh":"醫生決定病人需要多緊急治療時，會評估死亡風險。"},{"en":"Lower mortality risk usually means better chances of survival.","zh":"較低死亡風險通常代表較高存活機會。"},{"en":"The phrase refers to risk of death, not general illness only.","zh":"這個短語指死亡風險，而不只是一般疾病。"}],"source":"32 - Optimism and Health.pdf","sourcePage":8},{"front":"tried to ascertain","meaning":"嘗試確定","examples":[{"en":"Few studies have tried to ascertain the proportion of optimists.","zh":"很少研究嘗試確定樂觀者的比例。"},{"en":"To try to ascertain something means to try to find it out accurately.","zh":"try to ascertain something 指嘗試準確找出某事。"},{"en":"A teacher may try to ascertain why many students missed the same question.","zh":"老師可能嘗試確定為何許多學生答錯同一題。"},{"en":"Accurate information helps researchers avoid guessing about a population.","zh":"準確資訊幫助研究人員避免對人口作猜測。"},{"en":"The phrase is formal and means trying to determine.","zh":"這個短語較正式，意思是嘗試判定。"}],"source":"32 - Optimism and Health.pdf","sourcePage":8},{"front":"proportion of optimists","meaning":"樂觀者的比例","examples":[{"en":"Few studies have measured the proportion of optimists in the world.","zh":"很少研究量度世界上樂觀者的比例。"},{"en":"The proportion of optimists is the share or percentage of people who see themselves as optimistic.","zh":"proportion of optimists 指把自己視為樂觀者的人所佔比例或百分比。"},{"en":"A survey may find that half a class are optimists and half are not.","zh":"調查可能發現一班中一半是樂觀者，另一半不是。"},{"en":"Measuring the proportion helps researchers compare groups, countries, or genders.","zh":"量度比例幫助研究人員比較群體、國家或性別。"},{"en":"The phrase focuses on how many people belong to the optimistic group.","zh":"這個短語重點是有多少人屬於樂觀者群體。"}],"source":"32 - Optimism and Health.pdf","sourcePage":8},{"front":"nationwide survey","meaning":"全國性調查","examples":[{"en":"A nationwide survey examined how many people counted themselves as optimists.","zh":"一項全國性調查檢視有多少人視自己為樂觀者。"},{"en":"A nationwide survey is a survey conducted across an entire country.","zh":"nationwide survey 指在整個國家範圍內進行的調查。"},{"en":"A nationwide survey may ask families about income, health, education, or housing.","zh":"全國性調查可能詢問家庭收入、健康、教育或住屋情況。"},{"en":"Because it covers many regions, it can show broader patterns than a local poll.","zh":"因為它涵蓋許多地區，它能顯示比本地民調更廣泛的模式。"},{"en":"The phrase refers to research at the country level.","zh":"這個短語指國家層面的研究。"}],"source":"32 - Optimism and Health.pdf","sourcePage":8},{"front":"conducted by","meaning":"由……進行","examples":[{"en":"The survey was conducted by the magazine Adweek.","zh":"該調查由《Adweek》雜誌進行。"},{"en":"Conducted by means carried out or organised by a person, group, or institution.","zh":"conducted by 指由某人、團體或機構執行或組織。"},{"en":"A school survey conducted by students may ask classmates about lunch choices.","zh":"由學生進行的學校調查可能詢問同學午餐選擇。"},{"en":"Knowing who conducted a study helps readers judge its source and reliability.","zh":"知道研究由誰進行，幫助讀者判斷來源和可靠性。"},{"en":"The phrase identifies the organisation behind the research.","zh":"這個短語指出研究背後的組織。"}],"source":"32 - Optimism and Health.pdf","sourcePage":8},{"front":"counted themselves as","meaning":"視自己為……","examples":[{"en":"About half the population counted themselves as optimists.","zh":"約一半人口視自己為樂觀者。"},{"en":"To count themselves as something means to consider or classify themselves as part of that group.","zh":"count themselves as something 指認為或把自己歸類為某群體一部分。"},{"en":"A student may count herself as a beginner even if she knows some grammar.","zh":"即使知道一些文法，學生可能仍視自己為初學者。"},{"en":"Self-classification can differ from how other people might describe the person.","zh":"自我分類可能不同於別人如何描述該人。"},{"en":"The phrase focuses on personal identification.","zh":"這個短語重點是個人身份認同。"}],"source":"32 - Optimism and Health.pdf","sourcePage":8},{"front":"slightly more apt than","meaning":"比……稍為更傾向","examples":[{"en":"Women were slightly more apt than men to see the sunny side.","zh":"女性比男性稍為更傾向看事情光明的一面。"},{"en":"Slightly more apt than means a little more likely or inclined than another group.","zh":"slightly more apt than 指比另一群體稍微更可能或更傾向。"},{"en":"Younger students may be slightly more apt than older students to use learning apps.","zh":"較年幼學生可能比年長學生稍為更傾向使用學習應用程式。"},{"en":"A small difference can still be noted in survey results.","zh":"小差異仍可以在調查結果中被指出。"},{"en":"The phrase expresses a modest tendency, not a huge gap.","zh":"這個短語表達輕微傾向，而不是巨大差距。"}],"source":"32 - Optimism and Health.pdf","sourcePage":9},{"front":"see the sunny side","meaning":"看事情光明的一面","examples":[{"en":"Women were slightly more likely to see the sunny side.","zh":"女性稍為更可能看事情光明的一面。"},{"en":"To see the sunny side means to focus on the hopeful or positive part of a situation.","zh":"see the sunny side 指集中於某情況中有希望或正面的部分。"},{"en":"A student sees the sunny side when she treats a difficult assignment as useful practice.","zh":"當學生把困難功課視為有用練習，她就是看事情光明的一面。"},{"en":"Seeing the positive side can make problems feel more manageable.","zh":"看見正面一面可以令問題感覺更可處理。"},{"en":"The phrase is informal and means looking for hope.","zh":"這個短語較口語，意思是尋找希望。"}],"source":"32 - Optimism and Health.pdf","sourcePage":9},{"front":"there is no guarantee that","meaning":"不能保證","examples":[{"en":"There is no guarantee that optimism will protect you from hardship.","zh":"不能保證樂觀會保護你免受困難。"},{"en":"There is no guarantee that means no one can promise a certain result will happen.","zh":"there is no guarantee that 指沒有人能保證某結果一定發生。"},{"en":"There is no guarantee that studying all night will produce a better exam result.","zh":"不能保證通宵溫習會帶來更好考試結果。"},{"en":"Even helpful habits cannot remove every risk or difficulty.","zh":"即使有用習慣也不能消除所有風險或困難。"},{"en":"The phrase warns against overconfidence.","zh":"這個短語提醒不要過度自信。"}],"source":"32 - Optimism and Health.pdf","sourcePage":9},{"front":"insulate you from","meaning":"使你免受……影響","examples":[{"en":"Optimism cannot fully insulate you from the crisis.","zh":"樂觀不能完全使你免受危機影響。"},{"en":"To insulate you from something means to protect you from its effects.","zh":"insulate you from something 指保護你免受其影響。"},{"en":"Savings can insulate a family from a sudden job loss for a short time.","zh":"儲蓄可以在短時間內保護家庭免受突然失業的影響。"},{"en":"Optimism may help coping, but it cannot block every real-world problem.","zh":"樂觀可能幫助應對，但不能阻擋所有現實問題。"},{"en":"The phrase describes protection or shielding.","zh":"這個短語描述保護或隔絕。"}],"source":"32 - Optimism and Health.pdf","sourcePage":9},{"front":"the crunch’s worst effects","meaning":"經濟困境最壞的影響","examples":[{"en":"Optimism may not protect everyone from the crunch’s worst effects.","zh":"樂觀未必能保護每個人免受經濟困境最壞的影響。"},{"en":"The crunch’s worst effects are the most serious harms caused by a financial or economic crisis.","zh":"crunch’s worst effects 指財政或經濟危機造成的最嚴重傷害。"},{"en":"A recession’s worst effects may include job loss, debt, eviction, and stress.","zh":"經濟衰退最壞的影響可能包括失業、債務、被迫搬遷和壓力。"},{"en":"Even optimistic people may need practical support when a crisis becomes severe.","zh":"即使樂觀的人，在危機變嚴重時也可能需要實際支援。"},{"en":"The phrase points to the harshest results of economic pressure.","zh":"這個短語指出經濟壓力最嚴酷的結果。"}],"source":"32 - Optimism and Health.pdf","sourcePage":9},{"front":"the best strategy","meaning":"最佳策略","examples":[{"en":"The best strategy is still to keep smiling.","zh":"最佳策略仍然是保持笑容。"},{"en":"The best strategy is the most useful plan or approach in a situation.","zh":"best strategy 指某情況中最有用的計劃或做法。"},{"en":"For a difficult exam, the best strategy may be to practise weak areas first.","zh":"面對困難考試，最佳策略可能是先練習弱項。"},{"en":"A good strategy helps people respond to problems instead of simply reacting emotionally.","zh":"好策略幫助人們回應問題，而不是只作情緒反應。"},{"en":"The phrase identifies the recommended way to act.","zh":"這個短語指出建議採取的行動方式。"}],"source":"32 - Optimism and Health.pdf","sourcePage":9},{"front":"keep smiling","meaning":"保持笑容","examples":[{"en":"The writer suggests that people should keep smiling.","zh":"作者建議人們應保持笑容。"},{"en":"To keep smiling means to remain cheerful or positive despite difficulty.","zh":"keep smiling 指即使面對困難仍保持開朗或正面。"},{"en":"A receptionist may keep smiling even when the queue is long and customers are impatient.","zh":"即使隊伍很長、顧客不耐煩，接待員仍可能保持笑容。"},{"en":"Keeping a friendly attitude can make stressful situations easier for oneself and others.","zh":"保持友善態度可以令自己和別人更容易處理壓力情況。"},{"en":"The phrase suggests emotional steadiness, not pretending nothing is wrong.","zh":"這個短語暗示情緒穩定，而不是假裝沒有問題。"}],"source":"32 - Optimism and Health.pdf","sourcePage":9},{"front":"thank your lucky stars","meaning":"慶幸自己運氣好","examples":[{"en":"People should keep smiling and thank their lucky stars.","zh":"人們應保持笑容，並慶幸自己運氣好。"},{"en":"To thank your lucky stars means to feel grateful that something fortunate has happened.","zh":"thank your lucky stars 指感激有幸發生了某件好事。"},{"en":"A student who narrowly catches the last bus may thank her lucky stars.","zh":"勉強趕上尾班車的學生可能會慶幸自己運氣好。"},{"en":"Gratitude can shift attention from what is missing to what has been protected.","zh":"感恩可以把注意力由欠缺之物轉向已被保住之物。"},{"en":"The phrase is informal and means count yourself lucky.","zh":"這個短語較口語，意思是覺得自己幸運。"}],"source":"32 - Optimism and Health.pdf","sourcePage":9},{"front":"adversity is character-forming","meaning":"逆境能塑造性格","examples":[{"en":"Adversity is character-forming if people practise resilience.","zh":"如果人們練習抗逆力，逆境能塑造性格。"},{"en":"Adversity is character-forming means difficult experiences can help build stronger personal qualities.","zh":"adversity is character-forming 指困難經驗可以幫助建立更強個人品質。"},{"en":"A student who learns from failure may become more patient and disciplined.","zh":"從失敗中學習的學生可能變得更有耐性和紀律。"},{"en":"Hardship can develop courage if people reflect, adapt, and keep going.","zh":"如果人們反思、適應並繼續前進，艱難可以培養勇氣。"},{"en":"The phrase suggests difficulty can shape character in a positive way.","zh":"這個短語暗示困難能以正面方式塑造性格。"}],"source":"32 - Optimism and Health.pdf","sourcePage":9},{"front":"so long as","meaning":"只要","examples":[{"en":"Adversity can be useful so long as you practise resilience.","zh":"只要你練習抗逆力，逆境可以有用。"},{"en":"So long as means provided that or if this condition is met.","zh":"so long as 指只要某條件被滿足。"},{"en":"A student can use online videos effectively so long as she also practises actively.","zh":"只要學生也主動練習，她就能有效使用網上影片。"},{"en":"The phrase shows that one result depends on a condition.","zh":"這個短語顯示一個結果取決於某條件。"},{"en":"It is similar to “as long as” in meaning.","zh":"它意思近似 as long as。"}],"source":"32 - Optimism and Health.pdf","sourcePage":9},{"front":"practise the skills of resilience","meaning":"練習抗逆力技巧","examples":[{"en":"People can practise the skills of resilience.","zh":"人們可以練習抗逆力技巧。"},{"en":"To practise the skills of resilience means to train habits that help recovery after difficulty.","zh":"practise the skills of resilience 指訓練有助困難後恢復的習慣。"},{"en":"A student practises resilience by asking for feedback after a poor essay instead of hiding it.","zh":"學生在作文表現差後尋求回饋而不是逃避，就是在練習抗逆力。"},{"en":"Repeated practice makes it easier to stay calm and try again after setbacks.","zh":"重複練習令人更容易在挫折後保持冷靜並再次嘗試。"},{"en":"The phrase treats resilience as something that can be trained.","zh":"這個短語把抗逆力視為可以訓練的東西。"}],"source":"32 - Optimism and Health.pdf","sourcePage":9},{"front":"research among","meaning":"對……的研究","examples":[{"en":"Research among tycoons and business leaders shows that success often follows failure.","zh":"對大亨和商界領袖的研究顯示，成功常跟在失敗之後。"},{"en":"Research among a group means study conducted with or about that group.","zh":"research among a group 指對某群體進行或關於某群體的研究。"},{"en":"Research among teenagers may examine how sleep affects school performance.","zh":"對青少年的研究可能檢視睡眠如何影響學校表現。"},{"en":"Studying a specific group helps researchers understand patterns within it.","zh":"研究特定群體幫助研究人員理解其中的模式。"},{"en":"The phrase identifies the people being studied.","zh":"這個短語指出被研究的人群。"}],"source":"32 - Optimism and Health.pdf","sourcePage":10},{"front":"tycoons","meaning":"大亨；商界巨頭","examples":[{"en":"Research among tycoons shows that success often involves failure.","zh":"對大亨的研究顯示，成功常涉及失敗。"},{"en":"Tycoons are very rich and powerful business people.","zh":"tycoons 指非常富有且有權勢的商界人士。"},{"en":"A technology tycoon may own several companies and influence an entire industry.","zh":"科技大亨可能擁有幾家公司，並影響整個行業。"},{"en":"Even tycoons may have experienced bankruptcies, mistakes, or public criticism before success.","zh":"即使是商界巨頭，也可能在成功前經歷破產、錯誤或公開批評。"},{"en":"The word refers to major business figures, not ordinary managers.","zh":"這個詞指重要商業人物，而不是普通經理。"}],"source":"32 - Optimism and Health.pdf","sourcePage":10},{"front":"business leaders","meaning":"商界領袖","examples":[{"en":"Business leaders often face failure before success.","zh":"商界領袖在成功前常面對失敗。"},{"en":"Business leaders are people who guide, manage, or make major decisions in companies.","zh":"business leaders 指在公司中領導、管理或作出重大決策的人。"},{"en":"A business leader may decide whether to hire staff, enter a new market, or close a product line.","zh":"商界領袖可能決定是否聘請員工、進入新市場或停止某產品線。"},{"en":"Strong leaders learn from failure because their decisions affect workers and customers.","zh":"強大領袖會從失敗中學習，因為其決策影響員工和顧客。"},{"en":"The phrase refers to senior figures in business.","zh":"這個短語指商界中的高級人物。"}],"source":"32 - Optimism and Health.pdf","sourcePage":10},{"front":"path to success","meaning":"成功之路","examples":[{"en":"The path to success is often littered with failure.","zh":"成功之路常充滿失敗。"},{"en":"The path to success is the process or journey through which someone becomes successful.","zh":"path to success 指某人變得成功的過程或旅程。"},{"en":"A student’s path to success may include failed mock exams and many rewritten essays.","zh":"學生的成功之路可能包括模擬考失敗和多次重寫作文。"},{"en":"If the path includes failure, people should treat mistakes as part of progress.","zh":"如果路途中包含失敗，人們應把錯誤視為進步的一部分。"},{"en":"The phrase describes success as a journey, not a single event.","zh":"這個短語把成功描述為旅程，而不是單一事件。"}],"source":"32 - Optimism and Health.pdf","sourcePage":10},{"front":"littered with failure","meaning":"充滿失敗","examples":[{"en":"The path to success is often littered with failure.","zh":"成功之路常充滿失敗。"},{"en":"Littered with failure means containing many failures along the way.","zh":"littered with failure 指一路上包含許多失敗。"},{"en":"A writer’s early career may be littered with rejected manuscripts.","zh":"作家早期事業可能充滿被拒絕的稿件。"},{"en":"Many failures can teach lessons that later make success possible.","zh":"許多失敗可以教會教訓，令之後成功成為可能。"},{"en":"The phrase makes failure sound frequent but not final.","zh":"這個短語令失敗聽起來頻繁但不是最終結局。"}],"source":"32 - Optimism and Health.pdf","sourcePage":10},{"front":"a record of","meaning":"……的紀錄","examples":[{"en":"Many successful people have a record of sackings and bankruptcies.","zh":"許多成功人士有被解僱和破產的紀錄。"},{"en":"A record of something is a history or list of events that happened to someone.","zh":"record of something 指某人曾經發生過的事件歷史或清單。"},{"en":"A student may have a record of late homework if she misses many deadlines.","zh":"如果學生多次錯過限期，她可能有遲交功課紀錄。"},{"en":"A record of past failure does not always prevent future success.","zh":"過去失敗紀錄不一定阻止未來成功。"},{"en":"The phrase refers to someone’s history, not only an official document.","zh":"這個短語指某人的經歷歷史，而不只是正式文件。"}],"source":"32 - Optimism and Health.pdf","sourcePage":10},{"front":"sackings","meaning":"被解僱","examples":[{"en":"Some business leaders have a record of sackings.","zh":"一些商界領袖有被解僱的紀錄。"},{"en":"Sackings are cases where people are dismissed or fired from their jobs.","zh":"sackings 指人們被解僱或被公司開除的個案。"},{"en":"A company may announce sackings when it closes a department.","zh":"公司關閉部門時可能宣布裁員解僱。"},{"en":"Being sacked can be painful, but some people use it as a chance to change direction.","zh":"被解僱可以很痛苦，但有些人把它用作改變方向的機會。"},{"en":"The word is British English and means job dismissals.","zh":"這個詞屬英式英語，意思是工作被解僱。"}],"source":"32 - Optimism and Health.pdf","sourcePage":10},{"front":"bankruptcies","meaning":"破產","examples":[{"en":"Some successful people have experienced bankruptcies.","zh":"一些成功人士曾經歷破產。"},{"en":"Bankruptcies are situations where people or businesses cannot pay their debts and are legally declared bankrupt.","zh":"bankruptcies 指個人或企業無法償還債務並在法律上被宣告破產的情況。"},{"en":"A small shop may face bankruptcy if sales fall and loans cannot be repaid.","zh":"如果銷售下降而貸款無法償還，小店可能面對破產。"},{"en":"Bankruptcy can be a severe failure, but some entrepreneurs later rebuild.","zh":"破產可以是嚴重失敗，但有些企業家之後會重建。"},{"en":"The word refers to serious financial collapse.","zh":"這個詞指嚴重財務崩潰。"}],"source":"32 - Optimism and Health.pdf","sourcePage":10},{"front":"blistering castigation","meaning":"嚴厲痛斥","examples":[{"en":"The path to success may include blistering castigation.","zh":"成功之路可能包括嚴厲痛斥。"},{"en":"Blistering castigation means extremely harsh criticism or severe verbal attack.","zh":"blistering castigation 指極其嚴厲的批評或猛烈言語攻擊。"},{"en":"A manager may face blistering castigation after a public product failure.","zh":"產品公開失敗後，經理可能面對嚴厲痛斥。"},{"en":"Severe criticism can either crush confidence or push resilient people to improve.","zh":"嚴重批評可以壓垮信心，也可以推動有抗逆力的人改善。"},{"en":"The phrase is formal and dramatic, much stronger than simple criticism.","zh":"這個短語較正式和戲劇化，比普通 criticism 強烈得多。"}],"source":"32 - Optimism and Health.pdf","sourcePage":10},{"front":"instead of","meaning":"而不是","examples":[{"en":"Resilient people learn from failure instead of giving up.","zh":"有抗逆力的人從失敗中學習，而不是放棄。"},{"en":"Instead of means in place of or rather than.","zh":"instead of 指取代或而不是。"},{"en":"A student may ask for feedback instead of hiding a bad essay.","zh":"學生可能尋求回饋，而不是把差作文藏起來。"},{"en":"Choosing action instead of avoidance can turn failure into learning.","zh":"選擇行動而不是逃避，可以把失敗變成學習。"},{"en":"The phrase clearly contrasts two possible behaviours.","zh":"這個短語清楚對比兩種可能行為。"}],"source":"32 - Optimism and Health.pdf","sourcePage":10},{"front":"curl into a foetal ball","meaning":"蜷縮成胎兒姿勢","examples":[{"en":"They do not curl into a foetal ball after failure.","zh":"他們不會在失敗後蜷縮成胎兒姿勢。"},{"en":"To curl into a foetal ball means to physically or emotionally withdraw in fear, shame, or defeat.","zh":"curl into a foetal ball 指因恐懼、羞恥或失敗感而身體或情緒上退縮。"},{"en":"After harsh criticism, a student may want to curl into a ball and avoid everyone.","zh":"受到嚴厲批評後，學生可能想蜷縮起來並避開所有人。"},{"en":"Resilience means not staying trapped in that helpless state.","zh":"抗逆力代表不會一直困在那種無助狀態中。"},{"en":"The phrase is vivid and describes retreat, not literal advice.","zh":"這個短語很生動，描述退縮，而不是字面建議。"}],"source":"32 - Optimism and Health.pdf","sourcePage":10},{"front":"beneath the coffee table","meaning":"在茶几下面","examples":[{"en":"The image of hiding beneath the coffee table suggests giving up.","zh":"躲在茶几下面的畫面暗示放棄。"},{"en":"Beneath the coffee table means under a low table, used here as an image of hiding.","zh":"beneath the coffee table 指在矮茶几下方，這裏用作躲藏的意象。"},{"en":"A frightened child may hide beneath a table during a loud storm.","zh":"害怕的孩子可能在雷暴聲很大時躲在桌子下面。"},{"en":"In the passage, the image suggests shrinking away from failure instead of facing it.","zh":"在文章中，這個畫面暗示從失敗中退縮，而不是面對它。"},{"en":"The phrase is part of a humorous picture of defeat.","zh":"這個短語是關於失敗的幽默畫面一部分。"}],"source":"32 - Optimism and Health.pdf","sourcePage":11},{"front":"resiliently pick themselves up","meaning":"堅強地重新振作","examples":[{"en":"Resilient people pick themselves up after setbacks.","zh":"有抗逆力的人在挫折後堅強地重新振作。"},{"en":"To resiliently pick themselves up means to recover and continue after being knocked down by difficulty.","zh":"resiliently pick themselves up 指被困難打倒後恢復並繼續前進。"},{"en":"A student resiliently picks herself up when she fails a test and starts a new study plan.","zh":"學生測驗失敗後開始新溫習計劃，就是堅強地重新振作。"},{"en":"Recovery after failure helps people move toward the next opportunity.","zh":"失敗後恢復幫助人走向下一個機會。"},{"en":"The phrase describes emotional recovery and renewed action.","zh":"這個短語描述情緒恢復和重新行動。"}],"source":"32 - Optimism and Health.pdf","sourcePage":11},{"front":"learn from their pratfalls","meaning":"從失誤中學習","examples":[{"en":"Successful people learn from their pratfalls.","zh":"成功人士從自己的失誤中學習。"},{"en":"To learn from their pratfalls means to gain lessons from embarrassing mistakes or failures.","zh":"learn from their pratfalls 指從令人尷尬的錯誤或失敗中吸取教訓。"},{"en":"A student who freezes during a speech may learn to practise with a timer next time.","zh":"演講時突然說不出話的學生，可能學會下次用計時器練習。"},{"en":"Learning from mistakes turns embarrassment into useful experience.","zh":"從錯誤中學習會把尷尬變成有用經驗。"},{"en":"The phrase is slightly humorous and treats failure as teachable.","zh":"這個短語略帶幽默，把失敗視為可學習的東西。"}],"source":"32 - Optimism and Health.pdf","sourcePage":11},{"front":"pratfalls","meaning":"失誤；出醜","examples":[{"en":"Resilient people learn from their pratfalls.","zh":"有抗逆力的人會從自己的失誤中學習。"},{"en":"Pratfalls are embarrassing mistakes, failures, or moments of looking foolish.","zh":"pratfalls 指令人尷尬的錯誤、失敗或出醜時刻。"},{"en":"A presenter’s microphone failure and confused reaction may become a public pratfall.","zh":"主持人的咪高峰失靈和慌亂反應，可能成為公開出醜事件。"},{"en":"Pratfalls can be painful, but they can also teach preparation and humility.","zh":"失誤可以令人痛苦，但也能教人準備和謙遜。"},{"en":"The word is informal and often has a comic tone.","zh":"這個詞較口語，常帶喜劇色彩。"}],"source":"32 - Optimism and Health.pdf","sourcePage":11},{"front":"march boldly towards","meaning":"大膽邁向……","examples":[{"en":"They march boldly towards the next opportunity.","zh":"他們大膽邁向下一個機會。"},{"en":"To march boldly towards something means to move toward it confidently and bravely.","zh":"march boldly towards something 指自信而勇敢地向某事前進。"},{"en":"After losing a debate, a student may march boldly towards the next competition with better preparation.","zh":"辯論比賽輸掉後，學生可能以更好準備大膽邁向下一場比賽。"},{"en":"Bold action after failure shows that fear has not stopped progress.","zh":"失敗後的大膽行動顯示恐懼沒有阻止進步。"},{"en":"The phrase sounds energetic and determined.","zh":"這個短語聽起來充滿活力和決心。"}],"source":"32 - Optimism and Health.pdf","sourcePage":11},{"front":"the next opportunity","meaning":"下一個機會","examples":[{"en":"Resilient people move towards the next opportunity.","zh":"有抗逆力的人會走向下一個機會。"},{"en":"The next opportunity is the next chance to try, improve, or succeed.","zh":"next opportunity 指下一次嘗試、改善或成功的機會。"},{"en":"A job seeker who fails one interview may prepare for the next opportunity.","zh":"求職者一次面試失敗後，可能為下一個機會作準備。"},{"en":"Seeing another chance ahead can reduce the emotional weight of one failure.","zh":"看見前方還有機會，可以減輕一次失敗的情緒重量。"},{"en":"The phrase shifts attention from past defeat to future action.","zh":"這個短語把注意力由過去失敗轉向未來行動。"}],"source":"32 - Optimism and Health.pdf","sourcePage":11},{"front":"defines resilience as","meaning":"將抗逆力定義為……","examples":[{"en":"The American Psychological Association defines resilience as the ability to adapt.","zh":"美國心理學會將抗逆力定義為適應能力。"},{"en":"Defines resilience as means gives an official or clear meaning for resilience.","zh":"defines resilience as 指為 resilience 給出正式或清晰的意思。"},{"en":"A textbook may define motivation as the force that makes people act.","zh":"教科書可能把動機定義為令人行動的力量。"},{"en":"Definitions help readers understand a term before discussing examples.","zh":"定義幫助讀者在討論例子前理解術語。"},{"en":"The phrase introduces an authoritative explanation.","zh":"這個短語引入權威解釋。"}],"source":"32 - Optimism and Health.pdf","sourcePage":11},{"front":"ability to adapt","meaning":"適應能力","examples":[{"en":"Resilience is the ability to adapt in difficult situations.","zh":"抗逆力是在困難情況中的適應能力。"},{"en":"Ability to adapt means the capacity to adjust to new, difficult, or changing conditions.","zh":"ability to adapt 指調整自己以應對新、困難或變化情況的能力。"},{"en":"A student shows the ability to adapt when she changes her study plan after a poor result.","zh":"學生在成績差後改變溫習計劃，就是展現適應能力。"},{"en":"Adaptation helps people continue functioning when life does not go as planned.","zh":"適應幫助人在生活不如計劃時仍繼續運作。"},{"en":"The phrase describes flexible adjustment under pressure.","zh":"這個短語描述壓力下的靈活調整。"}],"source":"32 - Optimism and Health.pdf","sourcePage":11},{"front":"in the face of","meaning":"面對……時","examples":[{"en":"Resilience is the ability to adapt in the face of adversity.","zh":"抗逆力是在面對逆境時適應的能力。"},{"en":"In the face of means when dealing with or confronted by something difficult.","zh":"in the face of 指在處理或面對某種困難時。"},{"en":"A nurse stays calm in the face of heavy workload and anxious patients.","zh":"護士在面對沉重工作量和焦慮病人時保持冷靜。"},{"en":"The phrase highlights the challenge against which someone must act.","zh":"這個短語突出某人必須行動時面對的挑戰。"},{"en":"It is often used with danger, difficulty, criticism, or adversity.","zh":"它常與危險、困難、批評或逆境一起使用。"}],"source":"32 - Optimism and Health.pdf","sourcePage":11},{"front":"adversity","meaning":"逆境","examples":[{"en":"Resilient people adapt in the face of adversity.","zh":"有抗逆力的人在面對逆境時會適應。"},{"en":"Adversity means serious difficulty, hardship, or misfortune.","zh":"adversity 指嚴重困難、艱辛或不幸。"},{"en":"A family may face adversity after illness, job loss, or financial pressure.","zh":"家庭可能在疾病、失業或財政壓力後面對逆境。"},{"en":"Adversity can damage confidence, but it can also teach coping skills.","zh":"逆境可以損害信心，但也可以教人應對技巧。"},{"en":"The word refers to difficult life conditions, not small inconvenience.","zh":"這個詞指困難人生處境，而不是小不便。"}],"source":"32 - Optimism and Health.pdf","sourcePage":11},{"front":"trauma or tragedy","meaning":"創傷或悲劇","examples":[{"en":"Resilience helps people cope with trauma or tragedy.","zh":"抗逆力幫助人們應對創傷或悲劇。"},{"en":"Trauma or tragedy means deeply painful experiences such as violence, loss, disaster, or serious accident.","zh":"trauma or tragedy 指暴力、失去親人、災難或嚴重意外等深刻痛苦經驗。"},{"en":"A community may need counselling after a tragedy such as a fatal fire.","zh":"社區在致命火災等悲劇後可能需要輔導。"},{"en":"Resilience does not erase pain, but it can help people continue living after trauma.","zh":"抗逆力不會抹走痛苦，但可以幫助人在創傷後繼續生活。"},{"en":"The phrase refers to severe emotional shocks.","zh":"這個短語指嚴重情緒衝擊。"}],"source":"32 - Optimism and Health.pdf","sourcePage":11},{"front":"go through difficulty and uncertainty","meaning":"經歷困難和不確定","examples":[{"en":"A resilient person may go through difficulty and uncertainty.","zh":"有抗逆力的人可能經歷困難和不確定。"},{"en":"To go through difficulty and uncertainty means to experience hard situations without knowing what will happen next.","zh":"go through difficulty and uncertainty 指經歷艱難情況，且不知道接下來會發生甚麼。"},{"en":"A family may go through difficulty and uncertainty while waiting for medical test results.","zh":"家庭在等待醫療檢查結果時，可能經歷困難和不確定。"},{"en":"Such periods can be stressful because people must act without full control.","zh":"這類時期可以很有壓力，因為人們必須在不能完全控制下行動。"},{"en":"The phrase describes living through hardship and unclear outcomes.","zh":"這個短語描述經歷艱辛和不清晰結果。"}],"source":"32 - Optimism and Health.pdf","sourcePage":12},{"front":"doggedly bounce back","meaning":"頑強地恢復過來","examples":[{"en":"A resilient person will doggedly bounce back.","zh":"有抗逆力的人會頑強地恢復過來。"},{"en":"To doggedly bounce back means to recover with stubborn determination after difficulty.","zh":"doggedly bounce back 指在困難後以頑強決心恢復。"},{"en":"A student doggedly bounces back when she keeps practising after repeated speaking mistakes.","zh":"學生反覆口語錯誤後仍繼續練習，就是頑強地恢復過來。"},{"en":"Determined recovery can turn failure into long-term progress.","zh":"有決心的恢復可以把失敗變成長期進步。"},{"en":"The phrase stresses persistence as well as recovery.","zh":"這個短語同時強調堅持和恢復。"}],"source":"32 - Optimism and Health.pdf","sourcePage":12},{"front":"bounce back","meaning":"重新振作；恢復過來","examples":[{"en":"Resilient people bounce back after setbacks.","zh":"有抗逆力的人在挫折後會重新振作。"},{"en":"To bounce back means to recover after difficulty, failure, or illness.","zh":"bounce back 指在困難、失敗或疾病後恢復。"},{"en":"A shop may bounce back after a quiet month if loyal customers return.","zh":"如果忠實顧客回來，小店可能在淡靜月份後恢復過來。"},{"en":"People who bounce back do not avoid pain; they recover and act again.","zh":"重新振作的人不是避開痛苦；他們會恢復並再次行動。"},{"en":"The phrase describes recovery after being knocked down.","zh":"這個短語描述被打倒後的恢復。"}],"source":"32 - Optimism and Health.pdf","sourcePage":12},{"front":"central traits required in","meaning":"建立……所需的核心特質","examples":[{"en":"Optimism is one of the central traits required in building resilience.","zh":"樂觀是建立抗逆力所需的核心特質之一。"},{"en":"Central traits required in something are the main qualities needed to develop it.","zh":"central traits required in something 指發展某事所需的主要品質。"},{"en":"Patience is one of the central traits required in learning a difficult language.","zh":"耐性是學習困難語言所需的核心特質之一。"},{"en":"Without key traits, a person may struggle to build the larger ability.","zh":"沒有關鍵特質，一個人可能難以建立更大的能力。"},{"en":"The phrase identifies qualities that are essential to a process.","zh":"這個短語指出某過程不可或缺的品質。"}],"source":"32 - Optimism and Health.pdf","sourcePage":12},{"front":"building resilience","meaning":"建立抗逆力","examples":[{"en":"Optimism helps in building resilience.","zh":"樂觀有助建立抗逆力。"},{"en":"Building resilience means developing the ability to recover from difficulty.","zh":"building resilience 指發展從困難中恢復的能力。"},{"en":"A school can support students in building resilience by teaching them how to handle mistakes.","zh":"學校可以透過教學生如何處理錯誤來支持他們建立抗逆力。"},{"en":"Resilience is built through practice, support, reflection, and repeated challenges.","zh":"抗逆力透過練習、支援、反思和反覆挑戰建立。"},{"en":"The phrase describes a gradual strengthening process.","zh":"這個短語描述逐漸增強的過程。"}],"source":"32 - Optimism and Health.pdf","sourcePage":12},{"front":"investigators","meaning":"研究人員","examples":[{"en":"Yale University investigators studied resilience.","zh":"耶魯大學研究人員研究抗逆力。"},{"en":"Investigators are researchers who examine a question carefully to discover evidence.","zh":"investigators 指仔細研究某問題以發現證據的研究人員。"},{"en":"Health investigators may study why one community has higher illness rates than another.","zh":"健康研究人員可能研究為何一個社區患病率比另一個高。"},{"en":"Investigators collect data so conclusions are based on evidence rather than guesswork.","zh":"研究人員收集數據，使結論基於證據而不是猜測。"},{"en":"The word refers to people carrying out research or inquiry.","zh":"這個詞指進行研究或調查的人。"}],"source":"32 - Optimism and Health.pdf","sourcePage":12},{"front":"Annual Review of Clinical Psychology","meaning":"《臨床心理學年鑑》","examples":[{"en":"The findings appeared in the Annual Review of Clinical Psychology.","zh":"這些發現刊登於《臨床心理學年鑑》。"},{"en":"The Annual Review of Clinical Psychology is an academic publication that reviews research in clinical psychology.","zh":"Annual Review of Clinical Psychology 是回顧臨床心理學研究的學術出版物。"},{"en":"A student may cite an academic review when writing about mental health research.","zh":"學生撰寫心理健康研究時，可能引用學術綜述。"},{"en":"Publication in a review journal can help researchers summarise what is known about a topic.","zh":"發表在綜述期刊可以幫助研究人員總結某主題已知內容。"},{"en":"The phrase names the source where findings were published.","zh":"這個短語命名發現刊登的來源。"}],"source":"32 - Optimism and Health.pdf","sourcePage":12},{"front":"hold on to","meaning":"保持；堅持","examples":[{"en":"Resilient people learn to hold on to their sense of humour.","zh":"有抗逆力的人學會保持幽默感。"},{"en":"To hold on to something means to keep it and not lose it during difficulty.","zh":"hold on to something 指在困難中保留某物而不失去它。"},{"en":"A student under stress may hold on to her morning routine to stay calm.","zh":"壓力下的學生可能堅持早晨規律以保持冷靜。"},{"en":"Holding on to helpful habits can protect people when life becomes unstable.","zh":"保持有幫助的習慣可以在人生變得不穩定時保護人。"},{"en":"The phrase describes keeping something valuable.","zh":"這個短語描述保留有價值的東西。"}],"source":"32 - Optimism and Health.pdf","sourcePage":12},{"front":"sense of humour","meaning":"幽默感","examples":[{"en":"A sense of humour can support resilience.","zh":"幽默感可以支持抗逆力。"},{"en":"A sense of humour is the ability to see or express what is funny, even in difficult situations.","zh":"sense of humour 指即使在困難情況中也能看見或表達有趣之處的能力。"},{"en":"A teacher with a sense of humour can reduce tension before a hard test.","zh":"有幽默感的老師可以在困難測驗前減少緊張。"},{"en":"Humour can help people step back from stress and think more flexibly.","zh":"幽默可以幫助人從壓力中退一步，並更靈活思考。"},{"en":"The phrase refers to emotional lightness, not making jokes at others’ expense.","zh":"這個短語指情緒上的輕鬆感，而不是以別人為代價開玩笑。"}],"source":"32 - Optimism and Health.pdf","sourcePage":12},{"front":"keep a flexible attitude","meaning":"保持靈活態度","examples":[{"en":"Humour helps people keep a flexible attitude.","zh":"幽默幫助人保持靈活態度。"},{"en":"To keep a flexible attitude means to remain willing to adjust thoughts, plans, or behaviour.","zh":"keep a flexible attitude 指保持願意調整想法、計劃或行為。"},{"en":"A student keeps a flexible attitude when she changes her study method after feedback.","zh":"學生收到回饋後改變學習方法，就是保持靈活態度。"},{"en":"Flexibility helps people adapt when life does not follow the original plan.","zh":"靈活性幫助人在生活不按原計劃發展時適應。"},{"en":"The phrase describes mental openness under changing conditions.","zh":"這個短語描述變化條件下的心理開放。"}],"source":"32 - Optimism and Health.pdf","sourcePage":12},{"front":"big changes of plan","meaning":"計劃上的重大改變","examples":[{"en":"Resilient people adapt when big changes of plan are needed.","zh":"當計劃上的重大改變有需要時，有抗逆力的人會適應。"},{"en":"Big changes of plan are major adjustments to what someone originally intended to do.","zh":"big changes of plan 指對原本打算做的事作出重大調整。"},{"en":"A family may need big changes of plan if a flight is cancelled before a holiday.","zh":"如果假期前航班取消，家庭可能需要計劃上的重大改變。"},{"en":"When circumstances change suddenly, refusing to adjust can create more stress.","zh":"當情況突然改變，拒絕調整可能造成更多壓力。"},{"en":"The phrase describes serious changes, not small edits.","zh":"這個短語描述重大改變，而不是小修改。"}],"source":"32 - Optimism and Health.pdf","sourcePage":12},{"front":"are warranted","meaning":"是有需要的；是合理的","examples":[{"en":"Big changes of plan may be warranted in difficult situations.","zh":"在困難情況中，計劃上的重大改變可能是有需要的。"},{"en":"Are warranted means are justified, reasonable, or necessary because of the situation.","zh":"are warranted 指因情況而合理、有正當理由或必要。"},{"en":"Extra lessons may be warranted if many students fail the same grammar test.","zh":"如果許多學生在同一文法測驗中不合格，額外課堂可能是合理的。"},{"en":"When risk is high, stronger action may be warranted to prevent worse harm.","zh":"當風險很高，較強行動可能有需要以防止更大傷害。"},{"en":"The phrase explains that an action is not excessive but appropriate.","zh":"這個短語解釋某行動不是過度，而是合適。"}],"source":"32 - Optimism and Health.pdf","sourcePage":13},{"front":"accept your lot","meaning":"接受自己的處境","examples":[{"en":"The ability to accept your lot plays an important role in resilience.","zh":"接受自己處境的能力在抗逆力中扮演重要角色。"},{"en":"To accept your lot means to accept your situation, especially when it cannot be changed immediately.","zh":"accept your lot 指接受自己的情況，尤其是當它不能立即改變時。"},{"en":"A student may accept her lot after being placed in a difficult class and decide to work steadily.","zh":"學生被安排到困難班級後，可能接受自己的處境並決定穩定努力。"},{"en":"Acceptance can reduce wasted anger and help people focus on useful action.","zh":"接受可以減少浪費在憤怒上的精力，幫助人集中於有用行動。"},{"en":"The phrase means accepting reality, not giving up completely.","zh":"這個短語指接受現實，而不是完全放棄。"}],"source":"32 - Optimism and Health.pdf","sourcePage":13},{"front":"with equanimity","meaning":"平靜地；泰然地","examples":[{"en":"Resilient people can accept their lot with equanimity.","zh":"有抗逆力的人能平靜地接受自己的處境。"},{"en":"With equanimity means calmly and steadily, especially under pressure or disappointment.","zh":"with equanimity 指平靜而穩定地，尤其在壓力或失望之下。"},{"en":"A student who receives a low grade with equanimity asks what to improve instead of panicking.","zh":"學生低分後泰然地詢問要改善甚麼，而不是恐慌。"},{"en":"Calm acceptance helps people think clearly after bad news.","zh":"平靜接受幫助人在壞消息後清楚思考。"},{"en":"The phrase describes emotional balance.","zh":"這個短語描述情緒平衡。"}],"source":"32 - Optimism and Health.pdf","sourcePage":13},{"front":"plays an important role","meaning":"扮演重要角色","examples":[{"en":"Equanimity plays an important role in resilience.","zh":"平靜在抗逆力中扮演重要角色。"},{"en":"Plays an important role means has a significant function or influence.","zh":"plays an important role 指有重要功能或影響。"},{"en":"Sleep plays an important role in memory and concentration.","zh":"睡眠在記憶和專注力中扮演重要角色。"},{"en":"If calmness helps people adapt, it plays an important role in recovery.","zh":"如果平靜幫助人適應，它就在恢復中扮演重要角色。"},{"en":"The phrase identifies something as meaningful within a larger process.","zh":"這個短語指出某事在較大過程中有重要意義。"}],"source":"32 - Optimism and Health.pdf","sourcePage":13},{"front":"sociologist","meaning":"社會學家","examples":[{"en":"Steven Stack is a sociologist who studied resilience.","zh":"Steven Stack 是一位研究抗逆力的社會學家。"},{"en":"A sociologist is a researcher who studies society, social behaviour, groups, and institutions.","zh":"sociologist 指研究社會、社會行為、群體和制度的研究人員。"},{"en":"A sociologist may study how family background affects education or health.","zh":"社會學家可能研究家庭背景如何影響教育或健康。"},{"en":"Sociology helps explain behaviour by looking at social conditions, not only individual choice.","zh":"社會學透過看社會條件來解釋行為，而不只是個人選擇。"},{"en":"The word refers to an expert in social life.","zh":"這個詞指社會生活方面的專家。"}],"source":"32 - Optimism and Health.pdf","sourcePage":13},{"front":"one of the best ways to","meaning":"……的最佳方法之一","examples":[{"en":"One of the best ways to acquire resilience is through adversity.","zh":"獲得抗逆力的最佳方法之一是透過逆境。"},{"en":"One of the best ways to do something means one of the most effective methods.","zh":"one of the best ways to do something 指最有效方法之一。"},{"en":"One of the best ways to improve speaking is to practise with real questions regularly.","zh":"改善口語的最佳方法之一，是定期用真實問題練習。"},{"en":"The phrase suggests a strong recommendation while allowing other methods too.","zh":"這個短語提出強烈建議，同時容許仍有其他方法。"},{"en":"It introduces an especially useful route to a goal.","zh":"它引入達成目標的一條特別有用途徑。"}],"source":"32 - Optimism and Health.pdf","sourcePage":13},{"front":"acquire resilience","meaning":"獲得抗逆力","examples":[{"en":"People may acquire resilience through difficult experiences.","zh":"人們可能透過困難經驗獲得抗逆力。"},{"en":"To acquire resilience means to gain or develop the ability to recover from hardship.","zh":"acquire resilience 指獲得或發展從困難中恢復的能力。"},{"en":"A student may acquire resilience after learning how to handle repeated criticism.","zh":"學生學會處理反覆批評後，可能獲得抗逆力。"},{"en":"Difficult experiences can teach coping skills if people reflect and adapt.","zh":"如果人們反思和適應，困難經驗可以教會應對技巧。"},{"en":"The phrase suggests resilience can be learned over time.","zh":"這個短語暗示抗逆力可以隨時間學會。"}],"source":"32 - Optimism and Health.pdf","sourcePage":13},{"front":"difficult childhood","meaning":"艱難童年","examples":[{"en":"A difficult childhood may help some people develop resilience.","zh":"艱難童年可能幫助一些人發展抗逆力。"},{"en":"A difficult childhood is an early life marked by hardship, conflict, poverty, illness, or insecurity.","zh":"difficult childhood 指早年生活中有艱辛、衝突、貧窮、疾病或不安全感。"},{"en":"A child who faces bullying or family stress may have a difficult childhood.","zh":"面對欺凌或家庭壓力的孩子可能有艱難童年。"},{"en":"Some difficulties can build coping skills, though they can also cause harm.","zh":"一些困難可以建立應對技巧，但也可能造成傷害。"},{"en":"The phrase describes early adversity, not simply strict parenting.","zh":"這個短語描述早期逆境，而不只是嚴格管教。"}],"source":"32 - Optimism and Health.pdf","sourcePage":13},{"front":"less likely to","meaning":"較不可能","examples":[{"en":"Short men are less likely to commit suicide, according to Stack.","zh":"根據 Stack 的說法，矮個子男性較不可能自殺。"},{"en":"Less likely to means having a lower chance of doing or experiencing something.","zh":"less likely to 指做某事或經歷某事的機會較低。"},{"en":"Students who sleep enough are less likely to fall asleep in class.","zh":"睡眠足夠的學生較不可能在課堂上睡着。"},{"en":"A lower likelihood does not mean something is impossible.","zh":"較低可能性不代表某事不可能發生。"},{"en":"The phrase compares probability between groups or situations.","zh":"這個短語比較群體或情況之間的概率。"}],"source":"32 - Optimism and Health.pdf","sourcePage":13},{"front":"commit suicide","meaning":"自殺","examples":[{"en":"Stack discussed factors linked to suicide risk.","zh":"Stack 討論了與自殺風險有關的因素。"},{"en":"To commit suicide means to intentionally end one’s own life.","zh":"commit suicide 指有意結束自己的生命。"},{"en":"A person thinking about suicide needs immediate support from trusted people or emergency services.","zh":"正在考慮自殺的人需要立即得到可信任人士或緊急服務支援。"},{"en":"Serious distress can increase risk, so signs of danger should never be ignored.","zh":"嚴重痛苦可以增加風險，因此危險跡象絕不應被忽視。"},{"en":"The phrase is sensitive and should be used carefully and respectfully.","zh":"這個短語很敏感，應小心而尊重地使用。"}],"source":"32 - Optimism and Health.pdf","sourcePage":13},{"front":"shorties","meaning":"矮個子的人","examples":[{"en":"Stack argues that shorties develop psychological defence skills.","zh":"Stack 認為矮個子的人會發展心理防衛技巧。"},{"en":"Shorties is an informal word for short people, often sounding casual or slightly mocking.","zh":"shorties 是指矮個子的非正式詞語，常帶隨便或略帶取笑語氣。"},{"en":"Calling classmates shorties can be rude if it makes them feel small or laughed at.","zh":"稱同學為 shorties 可能很無禮，如果這令他們感到被貶低或取笑。"},{"en":"In the passage, the word is used to discuss how short men may develop coping skills.","zh":"在文章中，這個詞用來討論矮個子男性如何發展應對技巧。"},{"en":"The phrase is not neutral and should be used carefully.","zh":"這個短語不是中性詞，應小心使用。"}],"source":"32 - Optimism and Health.pdf","sourcePage":13},{"front":"psychological defence skills","meaning":"心理防衛技巧","examples":[{"en":"Some people develop psychological defence skills through adversity.","zh":"有些人透過逆境發展心理防衛技巧。"},{"en":"Psychological defence skills are mental strategies that help people protect themselves from stress, criticism, or hurt.","zh":"psychological defence skills 指幫助人保護自己免受壓力、批評或傷害的心理策略。"},{"en":"A bullied student may develop defence skills such as humour, confidence, or calm replies.","zh":"被欺凌的學生可能發展幽默、自信或冷靜回應等防衛技巧。"},{"en":"These skills can reduce emotional damage and help people cope with future pressure.","zh":"這些技巧可以減少情緒傷害，並幫助人應對未來壓力。"},{"en":"The phrase refers to mental protection, not physical fighting.","zh":"這個短語指心理保護，而不是身體打鬥。"}],"source":"32 - Optimism and Health.pdf","sourcePage":14},{"front":"handle the bullies","meaning":"應付欺凌者","examples":[{"en":"Children may develop skills to handle the bullies.","zh":"兒童可能發展應付欺凌者的技巧。"},{"en":"To handle the bullies means to deal with people who intimidate, tease, or hurt others.","zh":"handle the bullies 指處理恐嚇、取笑或傷害他人的人。"},{"en":"A child may handle bullies by seeking help, staying calm, and refusing to react alone.","zh":"孩子可能透過求助、保持冷靜和不獨自反應來應付欺凌者。"},{"en":"Learning safe responses can reduce fear and improve confidence.","zh":"學會安全回應可以減少恐懼並提升信心。"},{"en":"The phrase describes coping with bullying behaviour.","zh":"這個短語描述應對欺凌行為。"}],"source":"32 - Optimism and Health.pdf","sourcePage":14},{"front":"mickey-taking","meaning":"取笑；嘲弄","examples":[{"en":"Short men may face bullies and mickey-taking.","zh":"矮個子男性可能面對欺凌者和取笑。"},{"en":"Mickey-taking means teasing, mocking, or making fun of someone.","zh":"mickey-taking 指取笑、嘲弄或拿某人開玩笑。"},{"en":"A student may suffer mickey-taking if classmates joke about his accent every day.","zh":"如果同學每天拿學生口音開玩笑，他可能遭受嘲弄。"},{"en":"Repeated teasing can become emotionally harmful even if others call it “just a joke.”","zh":"反覆取笑即使被稱為「只是玩笑」，也可以造成情緒傷害。"},{"en":"The phrase is informal British English for ridicule.","zh":"這個短語是英式非正式英語，意思是嘲笑。"}],"source":"32 - Optimism and Health.pdf","sourcePage":14},{"front":"lack of stature","meaning":"身高不足","examples":[{"en":"Their lack of stature may attract bullying.","zh":"他們身高不足可能招致欺凌。"},{"en":"Lack of stature means being short or lacking physical height; it can also mean lacking status in other contexts.","zh":"lack of stature 指身材矮小或身高不足；在其他語境也可指缺乏地位。"},{"en":"A child’s lack of height may make him a target for teasing in a cruel classroom.","zh":"在殘酷的課室中，孩子身高不足可能令他成為取笑目標。"},{"en":"If others mock someone’s body, the problem is their behaviour, not the person’s height.","zh":"如果別人嘲笑某人的身體，問題在於他們的行為，而不是那人的身高。"},{"en":"In this passage, the phrase refers mainly to physical shortness.","zh":"在本文中，這個短語主要指身材較矮。"}],"source":"32 - Optimism and Health.pdf","sourcePage":14},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, adversity-free youths may struggle with later setbacks.","zh":"相比之下，沒有經歷逆境的年輕人可能難以應對後來挫折。"},{"en":"By contrast means in comparison, showing a clear difference from the previous point.","zh":"by contrast 指相比之下，用來顯示與前一點的清楚差異。"},{"en":"Some students revise early; by contrast, others wait until the night before.","zh":"有些學生早早溫習；相比之下，另一些等到前一晚才開始。"},{"en":"The phrase helps writers compare two opposite patterns.","zh":"這個短語幫助作者比較兩種相反模式。"},{"en":"It signals that the next idea will differ from the last one.","zh":"它表示下一個想法將不同於上一個。"}],"source":"32 - Optimism and Health.pdf","sourcePage":14},{"front":"adversity-free youths","meaning":"沒經歷逆境的年輕人","examples":[{"en":"Adversity-free youths may be less prepared for setbacks.","zh":"沒經歷逆境的年輕人可能較少準備好面對挫折。"},{"en":"Adversity-free youths are young people who have faced little serious hardship.","zh":"adversity-free youths 指很少面對嚴重困難的年輕人。"},{"en":"A teenager with a very protected life may be less used to criticism or failure.","zh":"生活非常受保護的青少年，可能較不習慣批評或失敗。"},{"en":"Without early challenges, some people may have fewer chances to practise coping skills.","zh":"沒有早期挑戰，有些人可能較少機會練習應對技巧。"},{"en":"The phrase describes young people with little experience of difficulty.","zh":"這個短語描述很少經歷困難的年輕人。"}],"source":"32 - Optimism and Health.pdf","sourcePage":14},{"front":"get derailed by setbacks","meaning":"被挫折打亂人生方向","examples":[{"en":"People without adversity may get derailed by setbacks later on.","zh":"沒有經歷逆境的人後來可能被挫折打亂人生方向。"},{"en":"To get derailed by setbacks means to be thrown off course by difficulties or failures.","zh":"get derailed by setbacks 指被困難或失敗打亂原本方向。"},{"en":"A student may get derailed by one bad grade if she believes it ruins her future.","zh":"如果學生相信一次低分毀掉未來，她可能被該成績打亂方向。"},{"en":"Strong coping skills can prevent setbacks from completely stopping progress.","zh":"強應對技巧可以防止挫折完全停止進展。"},{"en":"The phrase compares life progress to a train leaving its track.","zh":"這個短語把人生進展比作火車離軌。"}],"source":"32 - Optimism and Health.pdf","sourcePage":14},{"front":"later on","meaning":"後來","examples":[{"en":"Some people struggle with setbacks later on.","zh":"有些人後來難以應對挫折。"},{"en":"Later on means at a future time or after some time has passed.","zh":"later on 指在未來某時候或一段時間之後。"},{"en":"A student who ignores grammar now may have problems later on in writing exams.","zh":"現在忽視文法的學生，後來可能在寫作考試中遇到問題。"},{"en":"Early habits can affect what happens later on.","zh":"早期習慣可以影響後來發生的事。"},{"en":"The phrase points to a later stage, not the present moment.","zh":"這個短語指較後階段，而不是當下。"}],"source":"32 - Optimism and Health.pdf","sourcePage":14},{"front":"inoculated against","meaning":"對……有免疫力","examples":[{"en":"Difficult experiences can leave people inoculated against future stress.","zh":"困難經驗可以令人對未來壓力有免疫力。"},{"en":"Inoculated against something means protected from it, as if given a mental vaccine.","zh":"inoculated against something 指受到保護，像打了心理疫苗一樣。"},{"en":"A student who has practised many mock interviews may feel inoculated against interview nerves.","zh":"練習過許多模擬面試的學生，可能對面試緊張有免疫力。"},{"en":"Past hardship can make future problems feel less shocking.","zh":"過去艱難經驗可以令未來問題感覺較不震撼。"},{"en":"The phrase is metaphorical and means made more resistant.","zh":"這個短語是比喻，意思是變得更有抵抗力。"}],"source":"32 - Optimism and Health.pdf","sourcePage":14},{"front":"aggro","meaning":"麻煩；衝突；挑釁","examples":[{"en":"People who faced childhood adversity may be inoculated against aggro.","zh":"曾面對童年逆境的人可能對麻煩和衝突有免疫力。"},{"en":"Aggro means trouble, aggression, conflict, or hostile behaviour.","zh":"aggro 指麻煩、攻擊性、衝突或敵意行為。"},{"en":"A student may avoid aggro by walking away from classmates who are trying to start a fight.","zh":"學生可能透過離開想挑起打架的同學來避開衝突。"},{"en":"People who have handled conflict before may stay calmer when aggro appears later.","zh":"曾處理過衝突的人，在之後遇上挑釁時可能更冷靜。"},{"en":"The word is informal British English.","zh":"這個詞是英式非正式英語。"}],"source":"32 - Optimism and Health.pdf","sourcePage":14},{"front":"handicapped by","meaning":"因……而處於不利","examples":[{"en":"If you are handicapped by a happy childhood, optimism can help.","zh":"如果你因快樂童年而處於不利，樂觀可以幫助你。"},{"en":"Handicapped by something means placed at a disadvantage because of it.","zh":"handicapped by something 指因某事而處於劣勢。"},{"en":"A student may be handicapped by poor internet access during online lessons.","zh":"網課期間，學生可能因網絡差而處於不利。"},{"en":"In the passage, the phrase is ironic because a happy childhood is usually seen as positive.","zh":"在文章中，這個短語帶諷刺意味，因為快樂童年通常被視為正面。"},{"en":"The phrase describes something that makes coping harder.","zh":"這個短語描述令應對變得更困難的因素。"}],"source":"32 - Optimism and Health.pdf","sourcePage":14},{"front":"having had a happy childhood","meaning":"曾有快樂童年","examples":[{"en":"Having had a happy childhood may leave some people less prepared for adversity.","zh":"曾有快樂童年可能令一些人較少準備好面對逆境。"},{"en":"Having had a happy childhood means having grown up with comfort, safety, and few serious hardships.","zh":"having had a happy childhood 指在舒適、安全和少有嚴重困難中長大。"},{"en":"A person with a happy childhood may not have practised dealing with repeated rejection.","zh":"有快樂童年的人可能未曾練習處理反覆拒絕。"},{"en":"If early life contained few challenges, later setbacks may feel more shocking.","zh":"如果早年生活少有挑戰，後來挫折可能感覺更震撼。"},{"en":"The phrase describes a past upbringing that affects later coping.","zh":"這個短語描述影響日後應對的過去成長背景。"}],"source":"32 - Optimism and Health.pdf","sourcePage":15},{"front":"proactive optimism","meaning":"主動樂觀","examples":[{"en":"Practising proactive optimism can help people become more resilient.","zh":"練習主動樂觀可以幫助人變得更有抗逆力。"},{"en":"Proactive optimism is hopeful thinking combined with active steps to improve a situation.","zh":"proactive optimism 指有希望的思考加上改善情況的主動步驟。"},{"en":"A student shows proactive optimism when she believes she can improve and books extra practice sessions.","zh":"學生相信自己可以進步並預約額外練習課，就是表現出主動樂觀。"},{"en":"Optimism becomes practical when it leads to planning, action, and learning.","zh":"當樂觀帶來計劃、行動和學習，它就變得實際。"},{"en":"The phrase means active hope, not passive wishing.","zh":"這個短語指主動的希望，而不是被動願望。"}],"source":"32 - Optimism and Health.pdf","sourcePage":15},{"front":"take more risks","meaning":"承擔更多風險","examples":[{"en":"Studies show that resilient people take more risks.","zh":"研究顯示有抗逆力的人承擔更多風險。"},{"en":"To take more risks means to try actions that may fail but may also bring opportunity.","zh":"take more risks 指嘗試可能失敗但也可能帶來機會的行動。"},{"en":"A student takes a risk when she joins a speech contest despite feeling nervous.","zh":"學生即使緊張仍參加演講比賽，就是承擔風險。"},{"en":"Taking controlled risks can teach people that failure is survivable.","zh":"承擔可控風險可以教人失敗是可以承受的。"},{"en":"The phrase does not mean being reckless; it means being willing to try.","zh":"這個短語不是指魯莽，而是願意嘗試。"}],"source":"32 - Optimism and Health.pdf","sourcePage":15},{"front":"court failure","meaning":"主動面對失敗","examples":[{"en":"Resilient people court failure and learn from it.","zh":"有抗逆力的人主動面對失敗並從中學習。"},{"en":"To court failure means to deliberately put yourself in situations where failure is possible.","zh":"court failure 指刻意把自己放在可能失敗的情況中。"},{"en":"A student courts failure by joining a hard competition, but she may learn quickly from it.","zh":"學生參加困難比賽就是主動面對失敗，但她可能從中快速學習。"},{"en":"Facing possible failure helps people become less afraid of it.","zh":"面對可能失敗可以幫助人較不害怕它。"},{"en":"The phrase suggests actively approaching risk, not wanting to fail.","zh":"這個短語暗示主動接近風險，而不是想要失敗。"}],"source":"32 - Optimism and Health.pdf","sourcePage":15},{"front":"learn not to fear it","meaning":"學會不害怕它","examples":[{"en":"Resilient people learn not to fear failure.","zh":"有抗逆力的人學會不害怕失敗。"},{"en":"To learn not to fear it means to gradually stop being afraid of something through experience.","zh":"learn not to fear it 指透過經驗逐漸不再害怕某事。"},{"en":"A student may learn not to fear public speaking after several short presentations.","zh":"學生完成幾次短簡報後，可能學會不害怕公開演說。"},{"en":"Repeated exposure can reduce fear because people discover they can recover.","zh":"反覆接觸可以減少恐懼，因為人們發現自己能恢復。"},{"en":"The phrase describes fear becoming smaller through practice.","zh":"這個短語描述恐懼透過練習變小。"}],"source":"32 - Optimism and Health.pdf","sourcePage":15},{"front":"despite being","meaning":"儘管是……","examples":[{"en":"Despite being thick-skinned, resilient people are open to others.","zh":"儘管臉皮厚、有抗壓力，有抗逆力的人仍對他人開放。"},{"en":"Despite being means although someone or something has a particular quality.","zh":"despite being 指雖然某人或某物具有某種特質。"},{"en":"Despite being tired, a teacher may still speak patiently to a worried student.","zh":"儘管疲倦，老師仍可能耐心地對焦慮學生說話。"},{"en":"The phrase introduces a contrast between two qualities or facts.","zh":"這個短語引入兩種特質或事實之間的對比。"},{"en":"It helps show that one trait does not prevent another.","zh":"它幫助顯示一個特質不會阻止另一個特質。"}],"source":"32 - Optimism and Health.pdf","sourcePage":15},{"front":"thick-skinned","meaning":"臉皮厚；抗壓力強","examples":[{"en":"Resilient types are thick-skinned but open to other people.","zh":"有抗逆力的人臉皮厚但對他人開放。"},{"en":"Thick-skinned means not easily upset by criticism, teasing, or rejection.","zh":"thick-skinned 指不容易被批評、取笑或拒絕弄得難過。"},{"en":"A performer needs to be thick-skinned because audiences may criticise every mistake.","zh":"表演者需要臉皮厚，因為觀眾可能批評每個錯誤。"},{"en":"Being thick-skinned can help people continue after negative feedback.","zh":"抗壓力強可以幫助人在負面回饋後繼續前進。"},{"en":"The phrase suggests emotional toughness, not lack of kindness.","zh":"這個短語暗示情緒堅韌，而不是缺乏善意。"}],"source":"32 - Optimism and Health.pdf","sourcePage":15},{"front":"resilient types","meaning":"有抗逆力的人","examples":[{"en":"Resilient types are more open than average to other people.","zh":"有抗逆力的人比一般人更對他人開放。"},{"en":"Resilient types are people who tend to recover well from setbacks.","zh":"resilient types 指傾向能從挫折中良好恢復的人。"},{"en":"In a team, resilient types may keep working calmly after a plan fails.","zh":"在團隊中，有抗逆力的人可能在計劃失敗後仍冷靜工作。"},{"en":"Their recovery habits can make them more willing to try again and connect with others.","zh":"他們的恢復習慣可以令他們更願意再次嘗試和與人連結。"},{"en":"The phrase informally refers to people with resilient personalities.","zh":"這個短語較口語地指有抗逆性格的人。"}],"source":"32 - Optimism and Health.pdf","sourcePage":15},{"front":"more open than average","meaning":"比一般人更開放","examples":[{"en":"Resilient people are more open than average to other people.","zh":"有抗逆力的人比一般人更對他人開放。"},{"en":"More open than average means more willing than most people to listen, connect, or accept new ideas.","zh":"more open than average 指比大多數人更願意聆聽、連結或接受新想法。"},{"en":"A student who asks classmates for honest feedback is more open than average.","zh":"會請同學給誠實回饋的學生，比一般人更開放。"},{"en":"Openness can help resilient people learn from others instead of shutting down.","zh":"開放可以幫助有抗逆力的人向他人學習，而不是封閉自己。"},{"en":"The phrase compares someone with the typical person.","zh":"這個短語把某人與典型人士作比較。"}],"source":"32 - Optimism and Health.pdf","sourcePage":15},{"front":"bouncing through knockbacks","meaning":"在挫折中反彈前進","examples":[{"en":"Bouncing through knockbacks is part of resilience.","zh":"在挫折中反彈前進是抗逆力的一部分。"},{"en":"Bouncing through knockbacks means recovering and continuing after disappointments or setbacks.","zh":"bouncing through knockbacks 指在失望或挫折後恢復並繼續前進。"},{"en":"A student bounces through knockbacks when she keeps applying after scholarship rejections.","zh":"學生在獎學金申請被拒後仍繼續申請，就是在挫折中反彈前進。"},{"en":"Each recovery teaches that a setback does not have to end the journey.","zh":"每次恢復都教人挫折不必結束旅程。"},{"en":"The phrase describes moving through difficulty with recovery energy.","zh":"這個短語描述帶着恢復力量穿越困難。"}],"source":"32 - Optimism and Health.pdf","sourcePage":15},{"front":"knockbacks","meaning":"挫折；打擊","examples":[{"en":"Resilient people recover from knockbacks.","zh":"有抗逆力的人會從挫折中恢復。"},{"en":"Knockbacks are setbacks, rejections, or disappointing events that slow progress.","zh":"knockbacks 指阻礙進展的挫折、拒絕或令人失望的事件。"},{"en":"A job rejection is a knockback, but it can also show what to improve.","zh":"求職被拒是一次打擊，但也可以顯示要改善甚麼。"},{"en":"Repeated knockbacks can hurt confidence unless people learn to recover from them.","zh":"反覆挫折可能傷害信心，除非人們學會從中恢復。"},{"en":"The word is informal and often used for practical disappointments.","zh":"這個詞較口語，常用於實際失望事件。"}],"source":"32 - Optimism and Health.pdf","sourcePage":15},{"front":"all part of the process","meaning":"全都是過程的一部分","examples":[{"en":"Failure is all part of the process of building resilience.","zh":"失敗全都是建立抗逆力過程的一部分。"},{"en":"All part of the process means a normal and expected part of how something develops.","zh":"all part of the process 指某事發展方式中正常而預期的一部分。"},{"en":"Making mistakes is all part of the process of learning a new language.","zh":"犯錯全都是學習新語言過程的一部分。"},{"en":"Seeing failure as part of the process reduces shame and encourages practice.","zh":"把失敗視為過程一部分，可以減少羞恥並鼓勵練習。"},{"en":"The phrase normalises difficulty within growth.","zh":"這個短語把成長中的困難正常化。"}],"source":"32 - Optimism and Health.pdf","sourcePage":16},{"front":"optimistic risk-taking","meaning":"樂觀地承擔風險","examples":[{"en":"Resilience involves optimistic risk-taking.","zh":"抗逆力涉及樂觀地承擔風險。"},{"en":"Optimistic risk-taking means taking chances with hope and confidence that something useful may result.","zh":"optimistic risk-taking 指帶着希望和信心承擔機會，認為可能會有有用結果。"},{"en":"A student shows optimistic risk-taking by entering a competition she might not win.","zh":"學生參加自己未必會勝出的比賽，就是樂觀地承擔風險。"},{"en":"Taking hopeful risks creates opportunities to learn, connect, and grow.","zh":"帶希望承擔風險可以創造學習、連結和成長機會。"},{"en":"The phrase describes brave action supported by positive expectation.","zh":"這個短語描述由正面期待支持的勇敢行動。"}],"source":"32 - Optimism and Health.pdf","sourcePage":16},{"front":"being confident that","meaning":"有信心相信","examples":[{"en":"Optimistic risk-taking involves being confident that people will like you.","zh":"樂觀地承擔風險涉及有信心相信人們會喜歡你。"},{"en":"Being confident that means believing with some assurance that something is true or will happen.","zh":"being confident that 指較有把握地相信某事是真的或會發生。"},{"en":"A student may speak up in class because she is confident that her teacher will listen respectfully.","zh":"學生可能在課堂上發言，因為她有信心相信老師會尊重地聆聽。"},{"en":"Confidence can make social risks feel safer and easier to take.","zh":"信心可以令社交風險感覺更安全、更容易承擔。"},{"en":"The phrase introduces a belief that supports action.","zh":"這個短語引入支持行動的信念。"}],"source":"32 - Optimism and Health.pdf","sourcePage":16},{"front":"people will like you","meaning":"人們會喜歡你","examples":[{"en":"Being warm to people assumes that people will like you.","zh":"對人親切假設人們會喜歡你。"},{"en":"People will like you means others will respond to you with friendliness or approval.","zh":"people will like you 指其他人會以友善或認可回應你。"},{"en":"A new student may smile first because she hopes classmates will like her.","zh":"新學生可能先微笑，因為她希望同學會喜歡她。"},{"en":"Believing others may like you can make social interaction less frightening.","zh":"相信別人可能喜歡你，可以令社交互動較不嚇人。"},{"en":"The phrase expresses a positive expectation about relationships.","zh":"這個短語表達對人際關係的正面期待。"}],"source":"32 - Optimism and Health.pdf","sourcePage":16},{"front":"being warm to people","meaning":"對人親切","examples":[{"en":"Simply smiling and being warm to people can help.","zh":"只是微笑和對人親切都可以有幫助。"},{"en":"Being warm to people means treating others with friendliness, kindness, and openness.","zh":"being warm to people 指以友善、善意和開放態度對待他人。"},{"en":"A receptionist is warm to people when she greets them patiently and politely.","zh":"接待員耐心有禮地問候訪客，就是對人親切。"},{"en":"Warm behaviour can make others more willing to respond positively.","zh":"親切行為可以令人更願意作出正面回應。"},{"en":"The phrase describes friendly social behaviour.","zh":"這個短語描述友善社交行為。"}],"source":"32 - Optimism and Health.pdf","sourcePage":16},{"front":"altruistic path to self-interest","meaning":"通往自利的利他之路","examples":[{"en":"Being kind can be an altruistic path to self-interest.","zh":"善待別人可以是通往自利的利他之路。"},{"en":"An altruistic path to self-interest is a way of helping others that also benefits yourself.","zh":"altruistic path to self-interest 指幫助他人同時也令自己受益的方式。"},{"en":"A student who shares notes helps classmates and may receive help later in return.","zh":"分享筆記的學生幫助同學，日後也可能得到回報式幫助。"},{"en":"Kindness can build trust, friendship, and support networks that help the giver too.","zh":"善意可以建立信任、友誼和支援網絡，而這些也幫助付出者。"},{"en":"The phrase links generosity with practical personal benefit.","zh":"這個短語把慷慨與實際個人利益連起來。"}],"source":"32 - Optimism and Health.pdf","sourcePage":16},{"front":"if it achieves nothing else","meaning":"即使沒有其他成效","examples":[{"en":"If it achieves nothing else, optimism may still strengthen character.","zh":"即使沒有其他成效，樂觀仍可能強化性格。"},{"en":"If it achieves nothing else means even if it has no other result.","zh":"if it achieves nothing else 指即使沒有其他結果。"},{"en":"If a failed project achieves nothing else, it may still teach teamwork.","zh":"如果失敗項目沒有其他成效，它仍可能教會團隊合作。"},{"en":"The phrase highlights one remaining benefit even when other hopes fail.","zh":"這個短語在其他希望落空時突出一個剩餘好處。"},{"en":"It is used to rescue value from a limited outcome.","zh":"它用來從有限結果中保留價值。"}],"source":"32 - Optimism and Health.pdf","sourcePage":16},{"front":"reinforce an age-old adage","meaning":"加強一句古老格言","examples":[{"en":"Hard times reinforce an age-old adage.","zh":"艱難時期加強一句古老格言。"},{"en":"To reinforce an age-old adage means to strengthen support for an old saying.","zh":"reinforce an age-old adage 指加強對一句古老說法的支持。"},{"en":"A difficult exam may reinforce the old adage that practice matters more than luck.","zh":"困難考試可能加強「練習比運氣重要」這句古老格言。"},{"en":"When real events prove a saying true, people believe it more strongly.","zh":"當真實事件證明一句話正確，人們會更強烈相信它。"},{"en":"The phrase connects experience with traditional wisdom.","zh":"這個短語把經驗與傳統智慧連起來。"}],"source":"32 - Optimism and Health.pdf","sourcePage":16},{"front":"age-old adage","meaning":"古老格言","examples":[{"en":"The writer ends with an age-old adage about hard times.","zh":"作者以一句關於艱難時期的古老格言作結。"},{"en":"An age-old adage is a very old saying that expresses common wisdom.","zh":"age-old adage 指一句非常古老、表達共同智慧的說法。"},{"en":"“Practice makes perfect” is an age-old adage many teachers repeat.","zh":"“Practice makes perfect” 是許多老師重複的古老格言。"},{"en":"Adages survive because people feel they describe real experience.","zh":"格言能流傳，是因為人們覺得它描述真實經驗。"},{"en":"The phrase refers to traditional wisdom in a short saying.","zh":"這個短語指一句短說法中的傳統智慧。"}],"source":"32 - Optimism and Health.pdf","sourcePage":16},{"front":"hard times","meaning":"艱難時期","examples":[{"en":"Hard times can bring out the best in people.","zh":"艱難時期可以激發出人最好的一面。"},{"en":"Hard times are periods of serious difficulty, pressure, or hardship.","zh":"hard times 指嚴重困難、壓力或艱辛的時期。"},{"en":"A family may face hard times after illness, unemployment, or rising costs.","zh":"家庭在疾病、失業或成本上升後可能面對艱難時期。"},{"en":"Hard times can reveal whether people are patient, generous, and resilient.","zh":"艱難時期可以顯示人們是否有耐性、慷慨和抗逆力。"},{"en":"The phrase describes difficult periods, not simply busy days.","zh":"這個短語描述困難時期，而不只是忙碌日子。"}],"source":"32 - Optimism and Health.pdf","sourcePage":16},{"front":"bring out the best in","meaning":"激發出……最好的一面","examples":[{"en":"Hard times can bring out the best in you.","zh":"艱難時期可以激發出你最好的一面。"},{"en":"To bring out the best in someone means to cause their strongest or most positive qualities to appear.","zh":"bring out the best in someone 指使某人最強或最正面的品質展現出來。"},{"en":"A supportive teacher can bring out the best in a shy student.","zh":"支持性的老師可以激發害羞學生最好的一面。"},{"en":"Challenges can bring out courage, creativity, and kindness when people respond well.","zh":"當人們回應得好，挑戰可以激發勇氣、創意和善意。"},{"en":"The phrase describes revealing hidden strengths.","zh":"這個短語描述揭示隱藏優點。"}],"source":"32 - Optimism and Health.pdf","sourcePage":16},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below with words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"To complete the summary below means to fill gaps in a short version of the text.","zh":"complete the summary below 指填補文本簡短版本中的空格。"},{"en":"Students should read the summary first, then find matching ideas in the passage.","zh":"學生應先閱讀摘要，然後在文章中尋找相符想法。"},{"en":"Summary completion tests meaning, grammar, and exact word choice.","zh":"摘要填空測試意思、文法和準確用字。"},{"en":"The phrase is a common reading-test instruction.","zh":"這個短語是常見閱讀測驗指示。"}],"source":"32 - Optimism and Health.pdf","sourcePage":17},{"front":"no more than two words","meaning":"不超過兩個詞","examples":[{"en":"Students should choose no more than two words from the passage.","zh":"學生應從文章中選擇不超過兩個詞。"},{"en":"No more than two words means the answer must contain one or two words only.","zh":"no more than two words 指答案只能包含一個或兩個詞。"},{"en":"If the answer is “immune system,” it fits because it has two words.","zh":"如果答案是 “immune system”，它符合要求，因為有兩個詞。"},{"en":"Writing three words can lose marks even if the idea is correct.","zh":"即使意思正確，寫三個詞也可能失分。"},{"en":"The phrase sets a strict answer-length rule.","zh":"這個短語設定嚴格答案長度規則。"}],"source":"32 - Optimism and Health.pdf","sourcePage":17},{"front":"average of seven years","meaning":"平均七年","examples":[{"en":"The Yale study found that optimism can add an average of seven years to life.","zh":"耶魯研究發現樂觀可以令壽命平均增加七年。"},{"en":"An average of seven years means a typical increase of seven years across the studied group.","zh":"average of seven years 指在受研究群體中典型增加七年。"},{"en":"A course may improve scores by an average of seven marks, though individuals differ.","zh":"一個課程可能令分數平均增加七分，雖然每個人不同。"},{"en":"Averages describe group patterns, not guaranteed results for every person.","zh":"平均數描述群體模式，而不是每個人的保證結果。"},{"en":"The phrase reports a statistical amount.","zh":"這個短語報告統計數量。"}],"source":"32 - Optimism and Health.pdf","sourcePage":17},{"front":"biological basis","meaning":"生物學基礎","examples":[{"en":"A Harvard study suggests a biological basis for optimism’s health benefits.","zh":"一項哈佛研究指出樂觀的健康好處有生物學基礎。"},{"en":"A biological basis is a bodily or physical explanation for an effect.","zh":"biological basis 指某效果的身體或生理解釋。"},{"en":"Scientists may look for a biological basis behind why sleep improves memory.","zh":"科學家可能尋找睡眠改善記憶背後的生物學基礎。"},{"en":"If optimism affects immunity or lung function, its benefits may have a biological basis.","zh":"如果樂觀影響免疫力或肺功能，其好處可能有生物學基礎。"},{"en":"The phrase connects behaviour or attitude with body processes.","zh":"這個短語把行為或態度與身體過程連起來。"}],"source":"32 - Optimism and Health.pdf","sourcePage":17},{"front":"further evidence","meaning":"進一步證據","examples":[{"en":"A study of heart patients was cited as further evidence.","zh":"一項心臟病人研究被引用作為進一步證據。"},{"en":"Further evidence means additional information that supports a claim.","zh":"further evidence 指支持某聲稱的額外資料。"},{"en":"A second practice test can provide further evidence that a student is improving.","zh":"第二次練習測驗可以提供學生正在進步的進一步證據。"},{"en":"More evidence makes an argument stronger and less dependent on one study.","zh":"更多證據令論點更強，較不依賴單一研究。"},{"en":"The phrase adds support beyond what has already been mentioned.","zh":"這個短語加入已提及內容以外的支持。"}],"source":"32 - Optimism and Health.pdf","sourcePage":17},{"front":"correct ending","meaning":"正確結尾","examples":[{"en":"Students complete each sentence with the correct ending.","zh":"學生用正確結尾完成每個句子。"},{"en":"A correct ending is the option that completes a sentence accurately and logically.","zh":"correct ending 指能準確和合邏輯地完成句子的選項。"},{"en":"In a reading test, students should check grammar and meaning before choosing the correct ending.","zh":"在閱讀測驗中，學生應在選正確結尾前檢查文法和意思。"},{"en":"The wrong ending may sound similar but change the writer’s meaning.","zh":"錯誤結尾可能聽起來相似，但改變作者意思。"},{"en":"The phrase refers to sentence-completion answer choices.","zh":"這個短語指句子完成題的答案選項。"}],"source":"32 - Optimism and Health.pdf","sourcePage":17},{"front":"material wealth","meaning":"物質財富","examples":[{"en":"Material wealth does not necessarily create happiness.","zh":"物質財富不一定帶來快樂。"},{"en":"Material wealth means money, property, possessions, and financial resources.","zh":"material wealth 指金錢、物業、財物和財政資源。"},{"en":"A person may have material wealth but still feel lonely or anxious.","zh":"一個人可能有物質財富，但仍感到孤獨或焦慮。"},{"en":"Wealth can reduce some problems, but it does not automatically create meaning or contentment.","zh":"財富可以減少一些問題，但不會自動創造意義或滿足。"},{"en":"The phrase refers to external financial resources, not emotional well-being.","zh":"這個短語指外在財政資源，而不是情緒幸福。"}],"source":"32 - Optimism and Health.pdf","sourcePage":17},{"front":"does not necessarily","meaning":"不一定","examples":[{"en":"Money does not necessarily create happiness.","zh":"金錢不一定帶來快樂。"},{"en":"Does not necessarily means does not always or does not automatically.","zh":"does not necessarily 指不總是或不會自動。"},{"en":"A high score does not necessarily mean a student understands every detail.","zh":"高分不一定代表學生理解每個細節。"},{"en":"The phrase warns readers not to assume one thing always causes another.","zh":"這個短語提醒讀者不要假設一件事總會造成另一件事。"},{"en":"It leaves room for exceptions and other factors.","zh":"它保留例外和其他因素的空間。"}],"source":"32 - Optimism and Health.pdf","sourcePage":17},{"front":"advantageous to","meaning":"對……有利","examples":[{"en":"Optimism may be advantageous to human evolution.","zh":"樂觀可能對人類演化有利。"},{"en":"Advantageous to something means helpful or beneficial for it.","zh":"advantageous to something 指對某事有幫助或有益。"},{"en":"Good public transport is advantageous to workers because it saves time and money.","zh":"良好公共交通對工人有利，因為它節省時間和金錢。"},{"en":"If optimism helps people persist, it may be advantageous to survival.","zh":"如果樂觀幫助人堅持，它可能對生存有利。"},{"en":"The phrase describes a benefit in a particular context.","zh":"這個短語描述某語境中的好處。"}],"source":"32 - Optimism and Health.pdf","sourcePage":17},{"front":"human evolution","meaning":"人類演化","examples":[{"en":"Optimism may have helped human evolution.","zh":"樂觀可能曾幫助人類演化。"},{"en":"Human evolution is the long process through which humans developed over many generations.","zh":"human evolution 指人類經過許多世代逐步發展的漫長過程。"},{"en":"Cooperation may have mattered in human evolution because groups survived better together.","zh":"合作在人類演化中可能重要，因為群體一起生存得更好。"},{"en":"If a trait helped humans handle danger and failure, it may have had evolutionary value.","zh":"如果某特質幫助人類處理危險和失敗，它可能有演化價值。"},{"en":"The phrase refers to long-term biological and behavioural development.","zh":"這個短語指長期生物和行為發展。"}],"source":"32 - Optimism and Health.pdf","sourcePage":17},{"front":"adversity fosters resilience","meaning":"逆境培養抗逆力","examples":[{"en":"Steven Stack reports that adversity fosters resilience.","zh":"Steven Stack 報告指逆境培養抗逆力。"},{"en":"Adversity fosters resilience means difficult experiences help develop the ability to recover.","zh":"adversity fosters resilience 指困難經驗幫助發展恢復能力。"},{"en":"A student who faces repeated setbacks may become stronger at handling disappointment.","zh":"面對反覆挫折的學生，可能變得更能處理失望。"},{"en":"Hardship can build coping skills when people learn from it rather than collapse under it.","zh":"當人們從艱難中學習而不是被壓垮，艱難可以建立應對技巧。"},{"en":"The phrase presents difficulty as a possible source of strength.","zh":"這個短語把困難呈現為力量的可能來源。"}],"source":"32 - Optimism and Health.pdf","sourcePage":17},{"front":"levels of optimism","meaning":"樂觀程度","examples":[{"en":"The Adweek survey found that levels of optimism vary by gender.","zh":"《Adweek》調查發現樂觀程度因性別而異。"},{"en":"Levels of optimism are degrees of hopefulness or positive expectation among people.","zh":"levels of optimism 指人們希望感或正面期待的程度。"},{"en":"A teacher may notice different levels of optimism among students before an exam.","zh":"老師可能在考試前注意到學生有不同樂觀程度。"},{"en":"Measuring optimism levels helps researchers compare groups.","zh":"量度樂觀程度幫助研究人員比較群體。"},{"en":"The phrase treats optimism as something that can vary in amount.","zh":"這個短語把樂觀視為有程度差異的東西。"}],"source":"32 - Optimism and Health.pdf","sourcePage":18},{"front":"vary by gender","meaning":"因性別而異","examples":[{"en":"Levels of optimism may vary by gender.","zh":"樂觀程度可能因性別而異。"},{"en":"Vary by gender means differ between men, women, or other gender groups.","zh":"vary by gender 指男性、女性或其他性別群體之間有所不同。"},{"en":"Survey answers may vary by gender if different groups report different experiences.","zh":"如果不同群體報告不同經驗，調查答案可能因性別而異。"},{"en":"When results vary by gender, researchers may ask what social or cultural factors explain the difference.","zh":"當結果因性別而異，研究人員可能詢問哪些社會或文化因素解釋差異。"},{"en":"The phrase describes group-based variation.","zh":"這個短語描述基於群體的變化。"}],"source":"32 - Optimism and Health.pdf","sourcePage":18},{"front":"supports flexibility","meaning":"支持靈活性","examples":[{"en":"A good sense of humour supports flexibility.","zh":"良好幽默感支持靈活性。"},{"en":"Supports flexibility means helps people stay open, adaptable, and able to change plans.","zh":"supports flexibility 指幫助人保持開放、適應和改變計劃的能力。"},{"en":"A teacher’s humour can support flexibility when a lesson does not go as planned.","zh":"當課堂不按計劃進行時，老師的幽默可以支持靈活性。"},{"en":"If people can laugh gently at problems, they may adjust more easily.","zh":"如果人們能溫和地笑看問題，他們可能更容易調整。"},{"en":"The phrase links one quality with the ability to adapt.","zh":"這個短語把一種品質與適應能力連起來。"}],"source":"32 - Optimism and Health.pdf","sourcePage":18},{"front":"equanimity under stress","meaning":"壓力下的平靜","examples":[{"en":"Equanimity under stress helps build resilience.","zh":"壓力下的平靜有助建立抗逆力。"},{"en":"Equanimity under stress means calmness and emotional balance when facing pressure.","zh":"equanimity under stress 指面對壓力時的冷靜和情緒平衡。"},{"en":"A student shows equanimity under stress when she reads exam instructions slowly instead of panicking.","zh":"學生在考試中慢慢閱讀指示而不是恐慌，就是表現出壓力下的平靜。"},{"en":"Staying calm under pressure helps people make better decisions.","zh":"壓力下保持冷靜幫助人作出更好決定。"},{"en":"The phrase describes steady emotions in difficult moments.","zh":"這個短語描述困難時刻中的穩定情緒。"}],"source":"32 - Optimism and Health.pdf","sourcePage":18},{"front":"an optimistic outlook","meaning":"樂觀的人生觀","examples":[{"en":"An optimistic outlook can become a habit.","zh":"樂觀的人生觀可以成為習慣。"},{"en":"An optimistic outlook is a general way of seeing life with hope and expectation of improvement.","zh":"optimistic outlook 指以希望和改善期待看待人生的一般方式。"},{"en":"A student with an optimistic outlook may believe a weak essay can become better with feedback.","zh":"有樂觀人生觀的學生可能相信弱作文可以透過回饋變好。"},{"en":"When optimism becomes habitual, people may recover faster from disappointment.","zh":"當樂觀成為習慣，人們可能更快從失望中恢復。"},{"en":"The phrase describes a hopeful worldview.","zh":"這個短語描述有希望的世界觀。"}],"source":"32 - Optimism and Health.pdf","sourcePage":18},{"front":"agree with the claims of","meaning":"與……的說法一致","examples":[{"en":"The statements should agree with the claims of the writer.","zh":"這些陳述應與作者的說法一致。"},{"en":"To agree with the claims of someone means to match what that person says or argues.","zh":"agree with the claims of someone 指與某人所說或主張相符。"},{"en":"In a reading test, an answer agrees with the writer only if the passage clearly supports it.","zh":"在閱讀測驗中，只有文章清楚支持時，答案才與作者一致。"},{"en":"Students must separate the writer’s claims from examples and other people’s opinions.","zh":"學生必須把作者說法與例子和其他人意見分開。"},{"en":"The phrase is used for checking whether a statement matches the text.","zh":"這個短語用於檢查陳述是否與文本相符。"}],"source":"32 - Optimism and Health.pdf","sourcePage":18},{"front":"views of the writer","meaning":"作者觀點","examples":[{"en":"Students decide whether the statements match the views of the writer.","zh":"學生判斷陳述是否符合作者觀點。"},{"en":"Views of the writer are the opinions, beliefs, or arguments expressed by the author.","zh":"views of the writer 指作者表達的意見、信念或論點。"},{"en":"A student should identify the writer’s view before deciding YES, NO, or NOT GIVEN.","zh":"學生在決定 YES、NO 或 NOT GIVEN 前，應辨認作者觀點。"},{"en":"Misreading the writer’s view can lead to choosing an answer that sounds reasonable but is wrong.","zh":"誤讀作者觀點可能導致選擇聽起來合理但錯誤的答案。"},{"en":"The phrase refers to what the author thinks.","zh":"這個短語指作者的想法。"}],"source":"32 - Optimism and Health.pdf","sourcePage":18},{"front":"contradicts the views of","meaning":"與……觀點矛盾","examples":[{"en":"A “NO” answer means the statement contradicts the views of the writer.","zh":"“NO” 答案表示該陳述與作者觀點矛盾。"},{"en":"Contradicts the views of someone means says the opposite of what that person believes or argues.","zh":"contradicts the views of someone 指說出與某人相信或主張相反的意思。"},{"en":"If a writer says optimism can help, a statement saying optimism is always useless contradicts the writer’s view.","zh":"如果作者說樂觀可以有幫助，而陳述說樂觀永遠無用，就是與作者觀點矛盾。"},{"en":"Students should choose NO only when the meaning clearly opposes the passage.","zh":"學生只有在意思明確反對文章時才應選 NO。"},{"en":"The phrase describes direct disagreement with the author’s opinion.","zh":"這個短語描述與作者意見直接不一致。"}],"source":"32 - Optimism and Health.pdf","sourcePage":18},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"Write NOT GIVEN if it is impossible to say what the writer thinks.","zh":"如果無法判斷作者怎樣想，就寫 NOT GIVEN。"},{"en":"Impossible to say means there is not enough information to decide.","zh":"impossible to say 指資料不足，不能作出判斷。"},{"en":"If a passage discusses optimism but not diet, it may be impossible to say what the writer thinks about diet.","zh":"如果文章討論樂觀但沒有討論飲食，就可能無法判斷作者對飲食的看法。"},{"en":"Students should not guess when the text gives no clear evidence.","zh":"當文本沒有清楚證據時，學生不應猜測。"},{"en":"The phrase warns against unsupported inference.","zh":"這個短語提醒不要作沒有支持的推論。"}],"source":"32 - Optimism and Health.pdf","sourcePage":18},{"front":"health benefits of optimism","meaning":"樂觀的健康好處","examples":[{"en":"The question asks about the health benefits of optimism.","zh":"題目詢問樂觀的健康好處。"},{"en":"Health benefits of optimism are positive effects optimism may have on physical or mental health.","zh":"health benefits of optimism 指樂觀可能對身體或心理健康產生的正面影響。"},{"en":"Optimism may support health by reducing stress and encouraging people to keep active.","zh":"樂觀可能透過減少壓力和鼓勵人保持活躍來支持健康。"},{"en":"If optimism is linked to better lung function or longer life, it may have measurable health benefits.","zh":"如果樂觀與較好肺功能或較長壽命有關，它可能有可量度的健康好處。"},{"en":"The phrase focuses on how a positive outlook may improve well-being.","zh":"這個短語重點是正面人生觀如何改善健康。"}],"source":"32 - Optimism and Health.pdf","sourcePage":18},{"front":"long been known","meaning":"早已為人所知","examples":[{"en":"The question asks whether these benefits have long been known.","zh":"題目問這些好處是否早已為人所知。"},{"en":"Long been known means known for a long time before the present discussion.","zh":"long been known 指在目前討論前已長時間為人知道。"},{"en":"The benefits of handwashing have long been known in public health.","zh":"洗手的好處在公共衛生中早已為人所知。"},{"en":"If something has not long been known, recent studies may still be changing understanding.","zh":"如果某事並非早已為人所知，近期研究可能仍在改變理解。"},{"en":"The phrase focuses on how old or established the knowledge is.","zh":"這個短語重點是知識有多早或多穩固。"}],"source":"32 - Optimism and Health.pdf","sourcePage":18},{"front":"better relationships with","meaning":"與……有較好關係","examples":[{"en":"The question asks whether optimists have better relationships with people.","zh":"題目問樂觀者是否與人有較好關係。"},{"en":"Better relationships with people means healthier, warmer, or more successful connections with others.","zh":"better relationships with people 指與他人有更健康、更溫暖或更成功的連繫。"},{"en":"A student may build better relationships with classmates by listening and speaking kindly.","zh":"學生可以透過聆聽和友善說話，與同學建立較好關係。"},{"en":"Optimism may improve relationships because people become more open and friendly.","zh":"樂觀可能改善人際關係，因為人們變得更開放和友善。"},{"en":"The phrase refers to social connection quality.","zh":"這個短語指社交連繫的質素。"}],"source":"32 - Optimism and Health.pdf","sourcePage":19},{"front":"unable to practise optimism","meaning":"無法練習樂觀","examples":[{"en":"The question asks whether people with happy childhoods are unable to practise optimism.","zh":"題目問有快樂童年的人是否無法練習樂觀。"},{"en":"Unable to practise optimism means not able to train or use optimistic thinking.","zh":"unable to practise optimism 指不能訓練或使用樂觀思考。"},{"en":"A student is not unable to practise optimism simply because she has never faced a major failure.","zh":"學生不會只是因為從未面對重大失敗就無法練習樂觀。"},{"en":"Even people with easy pasts can learn hopeful habits through conscious practice.","zh":"即使過去較順利的人，也可以透過有意識練習學會有希望的習慣。"},{"en":"The phrase tests whether a claim is too absolute.","zh":"這個短語測試某聲稱是否過於絕對。"}],"source":"32 - Optimism and Health.pdf","sourcePage":19},{"front":"both open and thick-skinned","meaning":"既開放又臉皮厚","examples":[{"en":"Resilient people are often both open and thick-skinned.","zh":"有抗逆力的人通常既開放又臉皮厚。"},{"en":"Both open and thick-skinned means willing to connect with others while not being easily hurt by criticism.","zh":"both open and thick-skinned 指願意與他人連結，同時不容易被批評傷害。"},{"en":"A confident student can listen to feedback openly and still not collapse when comments are harsh.","zh":"自信的學生可以開放地聆聽回饋，同時在評論嚴厲時不崩潰。"},{"en":"This combination helps people learn from others without becoming too fragile.","zh":"這種組合幫助人向他人學習，而不變得太脆弱。"},{"en":"The phrase joins warmth with emotional toughness.","zh":"這個短語把溫暖與情緒韌性連起來。"}],"source":"32 - Optimism and Health.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 33":[{"front":"early Roman periods","meaning":"羅馬時期早期","examples":[{"en":"Salt production continued in the early Roman periods.","zh":"製鹽活動延續至羅馬時期早期。"},{"en":"Early Roman periods refer to the first stages of Roman rule or influence in a region.","zh":"羅馬時期早期，是指某地受羅馬統治或影響的最初階段。"},{"en":"An early Roman site may contain local pottery together with Roman-style objects.","zh":"羅馬時期早期遺址可能同時含有本地陶器和羅馬風格物件。"},{"en":"If an activity continued into the early Roman periods, it may have remained economically useful.","zh":"如果一項活動延續至羅馬時期早期，它可能仍具有經濟用途。"},{"en":"This phrase marks a transition from the late Iron Age into Roman-era history.","zh":"這個短語標示由鐵器時代晚期進入羅馬時代的過渡。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":1},{"front":"recognised for some time","meaning":"已被認識了一段時間","examples":[{"en":"Salt production has been recognised for some time.","zh":"製鹽活動已被認識了一段時間。"},{"en":"Recognised for some time means known or accepted for a fairly long period.","zh":"已被認識了一段時間，是指已經被知道或接受了相當一段時間。"},{"en":"The value of regular reading has been recognised for some time by teachers.","zh":"定期閱讀的價值早已被老師認識了一段時間。"},{"en":"A subject may be recognised for some time but still not fully understood.","zh":"一個課題可能已被認識了一段時間，但仍未被完全理解。"},{"en":"This phrase separates earlier awareness from complete explanation.","zh":"這個短語把早期認識與完整解釋分開。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":1},{"front":"Thames estuary","meaning":"泰晤士河口","examples":[{"en":"Salt production is known in the Thames estuary.","zh":"泰晤士河口有製鹽活動的記錄。"},{"en":"The Thames estuary is the tidal area where the River Thames meets the sea.","zh":"泰晤士河口是泰晤士河與海洋相接的潮汐區域。"},{"en":"The Thames estuary has been important for trade, transport, fishing, and settlement.","zh":"泰晤士河口一直對貿易、交通、捕魚和聚落十分重要。"},{"en":"Archaeological remains in an estuary can be preserved in mud and tidal deposits.","zh":"河口中的考古遺存可以保存在淤泥和潮汐沉積物中。"},{"en":"This phrase names a major coastal area in southern England.","zh":"這個短語命名英格蘭南部一個重要沿海區域。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":1},{"front":"Solent","meaning":"索倫特海峽","examples":[{"en":"Salt production was known around the Solent.","zh":"索倫特海峽一帶有製鹽活動的記錄。"},{"en":"The Solent is the stretch of sea between the Isle of Wight and the south coast of England.","zh":"索倫特海峽是懷特島與英格蘭南岸之間的一段海域。"},{"en":"The Solent has sheltered waters that have long supported boats, trade, and coastal activity.","zh":"索倫特海峽有受保護水域，長久支持船隻、貿易和沿海活動。"},{"en":"Archaeological finds around the Solent can reveal how people used marine resources.","zh":"索倫特海峽一帶的考古發現可以揭示人們如何使用海洋資源。"},{"en":"This phrase identifies a specific coastal waterway in southern England.","zh":"這個短語指出英格蘭南部一條特定沿海水道。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":1},{"front":"Poole Harbour","meaning":"普爾港","examples":[{"en":"Salt production was recognised around Poole Harbour.","zh":"普爾港一帶的製鹽活動已被認識。"},{"en":"Poole Harbour is a large natural harbour on the south coast of England.","zh":"普爾港是英格蘭南岸一個大型天然海港。"},{"en":"A harbour like Poole Harbour can protect boats from rough open sea.","zh":"像普爾港這樣的海港可以保護船隻免受外海風浪影響。"},{"en":"Coastal industries may develop near harbours because transport and resources are easier to manage.","zh":"沿海工業可能在海港附近發展，因為交通和資源較容易管理。"},{"en":"This phrase names a specific harbour linked with coastal archaeology.","zh":"這個短語命名一個與沿海考古相關的特定海港。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":1},{"front":"reasons for the decline of","meaning":"……衰落的原因","examples":[{"en":"The reasons for the decline of salt production are less understood.","zh":"製鹽活動衰落的原因較少被理解。"},{"en":"Reasons for the decline of something are the causes that explain why it became weaker or less common.","zh":"某事衰落的原因，是解釋它為何變弱或變得較少見的成因。"},{"en":"A teacher may study the reasons for the decline of students’ reading habits.","zh":"老師可能研究學生閱讀習慣衰落的原因。"},{"en":"A decline can be caused by cost, competition, environmental change, or new technology.","zh":"衰落可以由成本、競爭、環境變化或新科技造成。"},{"en":"This phrase asks why something that once mattered became less important.","zh":"這個短語詢問曾經重要的事物為何變得較不重要。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":1},{"front":"later coastal salt working","meaning":"後期沿海製鹽活動","examples":[{"en":"Later coastal salt working is much less well understood.","zh":"後期沿海製鹽活動的理解遠遠不足。"},{"en":"Later coastal salt working means salt-making activity along the coast in more recent historical periods.","zh":"後期沿海製鹽活動，是指較後歷史時期在沿海進行的製鹽活動。"},{"en":"Later salt working may have used different tools, fuel, and production sites from earlier periods.","zh":"後期製鹽活動可能使用與早期不同的工具、燃料和生產地點。"},{"en":"If later coastal salt working is poorly understood, researchers need more surveys and records.","zh":"如果後期沿海製鹽活動理解不足，研究人員需要更多調查和紀錄。"},{"en":"This phrase refers to later stages of coastal salt production.","zh":"這個短語指沿海製鹽的較後階段。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":1},{"front":"raw materials","meaning":"原材料","examples":[{"en":"Industries were located along the coast because raw materials were available.","zh":"工業位於沿海，是因為原材料可取得。"},{"en":"Raw materials are basic natural substances used to make products or support production.","zh":"原材料是用來製造產品或支持生產的基本天然物質。"},{"en":"Wood, clay, stone, and metal ore can all be raw materials.","zh":"木材、黏土、石材和金屬礦石都可以是原材料。"},{"en":"Factories often develop near raw materials because transport costs are lower.","zh":"工廠常在原材料附近發展，因為運輸成本較低。"},{"en":"This phrase refers to the starting materials used before something is made.","zh":"這個短語指製造某物前使用的起始材料。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":1},{"front":"outcropped there","meaning":"在那裏露出地表","examples":[{"en":"Some raw materials outcropped along the coast.","zh":"有些原材料在沿海露出地表。"},{"en":"Outcropped there means appeared naturally at the surface of the ground in that place.","zh":"在那裏露出地表，是指在該地方自然出現在地面表層。"},{"en":"Coal may outcrop on a cliff face where rock layers are exposed.","zh":"煤層可能在岩層外露的懸崖面露出地表。"},{"en":"Materials that outcrop are easier to find and extract than those deep underground.","zh":"露出地表的材料比深埋地下的材料更容易發現和開採。"},{"en":"This phrase describes natural exposure of useful rock or mineral layers.","zh":"這個短語描述有用岩石或礦物層的自然外露。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":1},{"front":"ease of working and transport","meaning":"便於加工和運輸","examples":[{"en":"Coastal sites were useful for ease of working and transport.","zh":"沿海地點因便於加工和運輸而有用。"},{"en":"Ease of working and transport means production and movement of goods could be done more conveniently.","zh":"便於加工和運輸，是指生產和貨物移動可以更方便地進行。"},{"en":"A factory near a river may benefit from ease of transport by boat.","zh":"靠近河流的工廠可能受益於船運帶來的便利。"},{"en":"When materials are easy to work and move, industries can grow more efficiently.","zh":"當材料容易加工和運送，工業就能更有效率地發展。"},{"en":"This phrase explains why certain locations are attractive for industry.","zh":"這個短語解釋為何某些地點對工業有吸引力。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":1},{"front":"mineral resources","meaning":"礦物資源","examples":[{"en":"Mineral resources were exploited along the coast.","zh":"沿海礦物資源曾被開採。"},{"en":"Mineral resources are useful naturally occurring materials such as stone, coal, iron ore, salt, or clay.","zh":"礦物資源是天然存在且有用的材料，例如石材、煤、鐵礦石、鹽或黏土。"},{"en":"A region with rich mineral resources may develop mining and transport industries.","zh":"擁有豐富礦物資源的地區可能發展採礦和運輸業。"},{"en":"Mineral resources attract human activity because they can be used for building, fuel, and trade.","zh":"礦物資源吸引人類活動，因為它們可用於建築、燃料和貿易。"},{"en":"This phrase refers to valuable materials taken from the earth.","zh":"這個短語指從地下取得的有價值材料。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":1},{"front":"sand, gravel and stone","meaning":"沙、礫石和石材","examples":[{"en":"Sand, gravel and stone were exploited along the coast.","zh":"沙、礫石和石材曾在沿海被開採。"},{"en":"Sand, gravel and stone are common materials used for building, roads, drainage, and construction.","zh":"沙、礫石和石材是常用於建築、道路、排水和工程的材料。"},{"en":"A construction company may need sand, gravel and stone to build a new road.","zh":"建築公司可能需要沙、礫石和石材來建造新道路。"},{"en":"Coastal areas may supply these materials because waves and geology expose them naturally.","zh":"沿海地區可能供應這些材料，因為海浪和地質作用會自然暴露它們。"},{"en":"This phrase lists basic building materials.","zh":"這個短語列出基本建築材料。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":2},{"front":"coal and ironstone","meaning":"煤和鐵礦石","examples":[{"en":"Coal and ironstone were also coastal mineral resources.","zh":"煤和鐵礦石也是沿海礦物資源。"},{"en":"Coal and ironstone are mineral materials used historically for fuel and iron production.","zh":"煤和鐵礦石是歷史上用於燃料和煉鐵的礦物材料。"},{"en":"Coal provided heat for industry, while ironstone could be processed into iron.","zh":"煤為工業提供熱力，而鐵礦石可被加工成鐵。"},{"en":"Access to coal and ironstone could encourage workshops, transport routes, and coastal industry.","zh":"取得煤和鐵礦石會促進工坊、運輸路線和沿海工業。"},{"en":"This phrase names two resources important to industrial development.","zh":"這個短語命名兩種對工業發展重要的資源。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":2},{"front":"alum","meaning":"明礬","examples":[{"en":"Alum was one of the mineral resources exploited along the coast.","zh":"明礬是沿海被開採的礦物資源之一。"},{"en":"Alum is a mineral compound historically used in dyeing, tanning, and other industrial processes.","zh":"明礬是一種礦物化合物，歷史上用於染色、製革和其他工業過程。"},{"en":"Cloth producers once used alum to help dyes fix more strongly to fabric.","zh":"布料生產者曾使用明礬幫助染料更牢固地附着在布上。"},{"en":"Because alum had practical industrial uses, coastal deposits could become economically valuable.","zh":"因為明礬有實際工業用途，沿海礦藏可以變得有經濟價值。"},{"en":"This word refers to a specific mineral resource used in earlier industries.","zh":"這個詞指早期工業使用的一種特定礦物資源。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":2},{"front":"were exploited","meaning":"被開採；被利用","examples":[{"en":"Coastal mineral resources were exploited.","zh":"沿海礦物資源曾被開採。"},{"en":"Were exploited means were used, extracted, or taken advantage of for practical benefit.","zh":"被開採或被利用，是指被使用、提取或用來取得實際利益。"},{"en":"A forest may be exploited for timber if trees are cut and sold.","zh":"如果樹木被砍伐並出售，森林就可能被利用作木材來源。"},{"en":"Resource exploitation can create wealth, but it can also damage the environment.","zh":"資源開採可以創造財富，但也可能破壞環境。"},{"en":"In archaeology, this phrase often means people made practical use of natural resources.","zh":"在考古學中，這個短語通常指人們實際使用自然資源。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":2},{"front":"poorly documented","meaning":"記錄不足","examples":[{"en":"These industries are poorly documented.","zh":"這些工業記錄不足。"},{"en":"Poorly documented means there are few records, descriptions, or reliable pieces of evidence.","zh":"記錄不足，是指紀錄、描述或可靠證據很少。"},{"en":"A family business may be poorly documented if old receipts and letters were thrown away.","zh":"如果舊收據和信件被丟掉，一間家族企業可能記錄不足。"},{"en":"Poor documentation makes it harder for researchers to reconstruct what happened.","zh":"記錄不足會令研究人員更難重建發生過的事。"},{"en":"This phrase signals a lack of written or physical evidence.","zh":"這個短語表示缺乏書面或實體證據。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":2},{"front":"remains","meaning":"遺跡","examples":[{"en":"Their remains are sometimes extensive and striking.","zh":"它們的遺跡有時規模大而引人注目。"},{"en":"Remains are surviving parts, traces, or ruins left from the past.","zh":"遺跡是從過去保存下來的部分、痕跡或廢墟。"},{"en":"The remains of an old wall may show where a building once stood.","zh":"舊牆遺跡可能顯示一座建築曾經位於哪裡。"},{"en":"Archaeological remains matter because they preserve information that written records may miss.","zh":"考古遺跡很重要，因為它們保存書面紀錄可能遺漏的資訊。"},{"en":"This word refers to what is left after time, damage, or abandonment.","zh":"這個詞指時間、破壞或廢棄之後留下的東西。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":2},{"front":"extensive and striking","meaning":"規模大而引人注目","examples":[{"en":"Some industrial remains are extensive and striking.","zh":"有些工業遺跡規模大而引人注目。"},{"en":"Extensive and striking means large in scale and visually or intellectually impressive.","zh":"規模大而引人注目，是指範圍很大，而且在視覺或理解上令人印象深刻。"},{"en":"A ruined castle can be extensive and striking if its walls cover a large hilltop.","zh":"如果廢城堡的城牆覆蓋大片山頂，它就可能規模大而引人注目。"},{"en":"Large remains attract attention because they show major past effort and organisation.","zh":"大型遺跡會吸引注意，因為它們顯示過去投入了大量努力和組織。"},{"en":"This phrase combines size with strong impact.","zh":"這個短語結合規模與強烈影響。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":2},{"front":"some appreciation of","meaning":"對……的一些認識","examples":[{"en":"Recent work gives some appreciation of coastal archaeological remains.","zh":"近期工作讓人對沿海考古遺存有一些認識。"},{"en":"Some appreciation of something means a partial understanding or recognition of its value.","zh":"對某事的一些認識，是指部分理解或認可其價值。"},{"en":"A student gains some appreciation of history after visiting an old village.","zh":"學生參觀古村後，可能對歷史有一些認識。"},{"en":"Partial appreciation is useful, but it may still need deeper research.","zh":"初步認識有用，但仍可能需要更深入研究。"},{"en":"This phrase suggests early understanding rather than complete knowledge.","zh":"這個短語暗示早期理解，而不是完整知識。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":2},{"front":"variety and importance","meaning":"多樣性和重要性","examples":[{"en":"Recent work reveals the variety and importance of coastal remains.","zh":"近期工作揭示沿海遺存的多樣性和重要性。"},{"en":"Variety and importance means something has many types and also matters greatly.","zh":"多樣性和重要性，是指某事有許多種類，而且非常重要。"},{"en":"A school exhibition can show the variety and importance of students’ creative work.","zh":"學校展覽可以展示學生創意作品的多樣性和重要性。"},{"en":"Recognising both variety and importance prevents people from reducing a subject to one simple example.","zh":"同時認識多樣性和重要性，可以防止人們把課題簡化成單一例子。"},{"en":"This phrase stresses diversity together with significance.","zh":"這個短語同時強調多元與重要性。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":2},{"front":"archaeological remains","meaning":"考古遺存","examples":[{"en":"Archaeological remains are preserved in the coastal zone.","zh":"考古遺存保存於沿海地帶。"},{"en":"Archaeological remains are physical traces of past human life, such as tools, bones, buildings, or waste deposits.","zh":"考古遺存是過去人類生活的實體痕跡，例如工具、骨頭、建築或廢棄沉積物。"},{"en":"Old pottery pieces and wooden posts can be archaeological remains.","zh":"古陶片和木柱都可以是考古遺存。"},{"en":"These remains help researchers understand activities that were never written down.","zh":"這些遺存幫助研究人員理解從未被寫下來的活動。"},{"en":"This phrase refers to surviving material evidence from the past.","zh":"這個短語指從過去保存下來的物質證據。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":2},{"front":"preserved in","meaning":"保存於……","examples":[{"en":"Many remains are preserved in the coastal zone.","zh":"許多遺存保存於沿海地帶。"},{"en":"Preserved in a place means kept there in a condition that allows survival over time.","zh":"保存於某地，是指在那裡保持能長時間存留的狀態。"},{"en":"Old seeds may be preserved in dry soil for hundreds of years.","zh":"古老種子可能在乾燥泥土中保存數百年。"},{"en":"Waterlogged mud can preserve wood that would decay quickly in air.","zh":"積水淤泥可以保存木材，否則木材在空氣中會很快腐爛。"},{"en":"This phrase connects survival of evidence with its environment.","zh":"這個短語把證據存留與其環境連接起來。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":2},{"front":"albeit only in preliminary form","meaning":"雖然只是初步形式","examples":[{"en":"Some understanding has been gained, albeit only in preliminary form.","zh":"人們已獲得一些理解，雖然只是初步形式。"},{"en":"Albeit only in preliminary form means although it is only early and not yet complete.","zh":"雖然只是初步形式，是指雖然它只是早期成果，尚未完整。"},{"en":"The study gives useful results, albeit only in preliminary form, because more data is needed.","zh":"這項研究提供有用結果，雖然只是初步形式，因為仍需要更多數據。"},{"en":"Early findings can guide future work even if they are not final.","zh":"早期發現即使不是最終結論，也能指導未來工作。"},{"en":"This phrase adds caution to a positive statement.","zh":"這個短語為正面陳述加入謹慎語氣。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":3},{"front":"can thus be gained from","meaning":"因而可從……獲得","examples":[{"en":"Some understanding can thus be gained from recent work.","zh":"一些理解因而可從近期工作獲得。"},{"en":"Can thus be gained from means can therefore be obtained through that source or action.","zh":"因而可從某事獲得，是指因此可以透過該來源或行動取得。"},{"en":"Useful feedback can thus be gained from asking students which examples confused them.","zh":"透過詢問學生哪些例子令他們困惑，因而可獲得有用回饋。"},{"en":"When evidence is collected carefully, better understanding can be gained from it.","zh":"當證據被仔細收集，就能從中獲得更好理解。"},{"en":"This phrase connects a result with the method that produces it.","zh":"這個短語把結果與產生它的方法連接起來。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":3},{"front":"complexity of the problem","meaning":"問題的複雜性","examples":[{"en":"The complexity of the problem is also being realised.","zh":"問題的複雜性也正被意識到。"},{"en":"Complexity of the problem means the problem has many connected parts and is not simple to solve.","zh":"問題的複雜性，是指問題有許多互相關連的部分，並不容易解決。"},{"en":"A school may realise the complexity of student stress when sleep, exams, family pressure, and money all matter.","zh":"當睡眠、考試、家庭壓力和金錢都重要時，學校可能意識到學生壓力問題的複雜性。"},{"en":"Complex problems require careful planning because one solution may create another difficulty.","zh":"複雜問題需要仔細規劃，因為一個解決方法可能製造另一個困難。"},{"en":"This phrase warns that the issue cannot be handled in a simple way.","zh":"這個短語提醒我們，問題不能以簡單方式處理。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":3},{"front":"managing that resource","meaning":"管理該資源","examples":[{"en":"Managing coastal archaeological resources is complex.","zh":"管理沿海考古資源十分複雜。"},{"en":"Managing that resource means protecting, recording, studying, and making decisions about it responsibly.","zh":"管理該資源，是指負責任地保護、記錄、研究和作出相關決定。"},{"en":"A museum manages its collection by cataloguing objects and controlling storage conditions.","zh":"博物館透過為物件編目和控制保存環境來管理館藏。"},{"en":"Good management is needed when a resource is valuable but threatened by damage or development.","zh":"當資源有價值但受破壞或發展威脅，就需要良好管理。"},{"en":"This phrase focuses on responsible care and decision-making.","zh":"這個短語聚焦負責任照顧和決策。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":3},{"front":"arises not only from…but also from…","meaning":"不但源於……而且源於……","examples":[{"en":"The problem arises not only from scale but also from threats and organisations.","zh":"這個問題不但源於規模，也源於威脅和組織因素。"},{"en":"Arises not only from A but also from B means one problem has more than one source.","zh":"不但源於 A 而且源於 B，是指一個問題有多於一個來源。"},{"en":"Student stress arises not only from exams but also from sleep loss and family expectations.","zh":"學生壓力不但源於考試，而且源於睡眠不足和家庭期望。"},{"en":"This structure helps show that an issue is complex, with several causes working together.","zh":"這個結構有助顯示議題很複雜，有幾個成因共同作用。"},{"en":"It is useful when correcting an overly simple explanation.","zh":"當要修正過度簡化的解釋時，它很有用。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":3},{"front":"scale and variety","meaning":"規模和種類","examples":[{"en":"The scale and variety of remains make management difficult.","zh":"遺存的規模和種類令管理變得困難。"},{"en":"Scale and variety mean the amount is large and the types are diverse.","zh":"規模和種類，是指數量很大，而且類型多元。"},{"en":"A school library with thousands of books in many languages has both scale and variety.","zh":"擁有數千本多語書籍的學校圖書館，同時有規模和種類。"},{"en":"Large scale and wide variety can make recording, organising, and protecting items harder.","zh":"規模大且種類多會令記錄、整理和保護物件更困難。"},{"en":"This phrase explains difficulty caused by size and diversity together.","zh":"這個短語解釋由大小和多樣性共同造成的困難。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":3},{"front":"varied natural and human threats","meaning":"各種自然和人為威脅","examples":[{"en":"Coastal archaeology faces varied natural and human threats.","zh":"沿海考古面對各種自然和人為威脅。"},{"en":"Varied natural and human threats are many different dangers caused by nature and by people.","zh":"各種自然和人為威脅，是由自然和人類造成的多種不同危險。"},{"en":"A historic building may face natural threats from rain and human threats from redevelopment.","zh":"歷史建築可能面對來自雨水的自然威脅，以及來自重建的人為威脅。"},{"en":"Because threats vary, one protection method cannot solve every problem.","zh":"因為威脅各不相同，一種保護方法不能解決所有問題。"},{"en":"This phrase stresses that damage can come from several directions.","zh":"這個短語強調破壞可以來自多個方向。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":3},{"front":"complex web of organisations","meaning":"複雜的組織網絡","examples":[{"en":"A complex web of organisations has authority over the coastal zone.","zh":"一個複雜的組織網絡對沿海地帶有管轄權。"},{"en":"A complex web of organisations means many groups are connected and involved in overlapping ways.","zh":"複雜的組織網絡，是許多群體以重疊方式互相關連和參與。"},{"en":"A city project may involve a complex web of schools, councils, transport bodies, and charities.","zh":"城市項目可能涉及學校、市政機關、交通機構和慈善團體等複雜組織網絡。"},{"en":"When many organisations are involved, decisions can become slow and difficult to coordinate.","zh":"當許多組織參與，決策會變慢並難以協調。"},{"en":"This phrase describes complicated institutional relationships.","zh":"這個短語描述複雜的制度關係。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":3},{"front":"authority over","meaning":"對……有管轄權","examples":[{"en":"Several organisations have authority over the coastal zone.","zh":"幾個組織對沿海地帶有管轄權。"},{"en":"Authority over something means legal or official power to make decisions about it.","zh":"對某事有管轄權，是指對它有法律或官方決策權。"},{"en":"A school principal has authority over daily school rules.","zh":"校長對學校日常規則有管轄權。"},{"en":"When several bodies have authority over one area, responsibilities may overlap.","zh":"當幾個機構對同一範圍有管轄權，責任可能重疊。"},{"en":"This phrase identifies who has decision-making power.","zh":"這個短語指出誰有決策權。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":3},{"front":"interests in","meaning":"對……有利益關係","examples":[{"en":"Many organisations have interests in the coastal zone.","zh":"許多組織對沿海地帶有利益關係。"},{"en":"Interests in something means concerns, benefits, responsibilities, or goals connected with it.","zh":"對某事有利益關係，是指與它相關的關注、利益、責任或目標。"},{"en":"Parents, teachers, and students all have interests in school policy.","zh":"家長、老師和學生都對學校政策有利益關係。"},{"en":"Organisations with different interests may disagree about how a place should be used.","zh":"有不同利益關係的組織，可能不同意一個地方應如何使用。"},{"en":"This phrase describes why a group cares about an issue.","zh":"這個短語描述某群體為何關心某議題。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":3},{"front":"old dockland areas","meaning":"舊碼頭區","examples":[{"en":"Redevelopment of old dockland areas threatens archaeology.","zh":"舊碼頭區重建威脅考古。"},{"en":"Old dockland areas are former waterside industrial or shipping districts.","zh":"舊碼頭區是昔日水邊工業或航運區域。"},{"en":"A city may turn old dockland areas into flats, offices, cafés, and museums.","zh":"城市可能把舊碼頭區改造成住宅、辦公室、咖啡店和博物館。"},{"en":"Such redevelopment can disturb buried harbour structures, warehouses, and trade remains.","zh":"這類重建可以擾動被埋藏的港口結構、倉庫和貿易遺存。"},{"en":"This phrase links urban renewal with former maritime activity.","zh":"這個短語把城市更新與昔日海事活動連接起來。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":3},{"front":"increased importance of","meaning":"……重要性增加","examples":[{"en":"The increased importance of the coast for tourism creates pressure.","zh":"海岸對旅遊的重要性增加，造成壓力。"},{"en":"Increased importance of something means it has become more valuable, influential, or central.","zh":"某事的重要性增加，是指它變得更有價值、更有影響力或更核心。"},{"en":"The increased importance of online learning has changed how schools plan lessons.","zh":"網上學習重要性增加，改變了學校規劃課堂的方式。"},{"en":"When a place becomes more important economically, development pressure often rises.","zh":"當一個地方在經濟上更重要，發展壓力通常會上升。"},{"en":"This phrase describes a rise in value or attention.","zh":"這個短語描述價值或關注上升。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":4},{"front":"leisure and tourism industries","meaning":"休閒及旅遊業","examples":[{"en":"The coast is increasingly important for leisure and tourism industries.","zh":"海岸對休閒及旅遊業越來越重要。"},{"en":"Leisure and tourism industries are businesses connected with recreation, holidays, travel, hotels, attractions, and entertainment.","zh":"休閒及旅遊業是與娛樂、假期、旅行、酒店、景點和消遣相關的行業。"},{"en":"Beach resorts, tour companies, restaurants, and hotels belong to leisure and tourism industries.","zh":"海灘度假村、旅行社、餐廳和酒店都屬於休閒及旅遊業。"},{"en":"These industries can bring income but also increase pressure on fragile coastal sites.","zh":"這些行業可以帶來收入，但也會增加脆弱沿海遺址的壓力。"},{"en":"This phrase refers to economic activity built around relaxation and travel.","zh":"這個短語指圍繞休閒和旅行建立的經濟活動。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":4},{"front":"resulting in","meaning":"導致","examples":[{"en":"Tourism pressure is resulting in more facilities.","zh":"旅遊壓力正導致更多設施出現。"},{"en":"Resulting in means causing a particular result or outcome.","zh":"導致，是指造成某個結果或後果。"},{"en":"Heavy rain blocked the roads, resulting in long delays for students.","zh":"大雨阻塞道路，導致學生長時間延誤。"},{"en":"When demand increases, it can result in new buildings, services, and infrastructure.","zh":"當需求增加，它可以導致新建築、服務和基建出現。"},{"en":"This phrase links a cause with its consequence.","zh":"這個短語把原因與結果連接起來。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":4},{"front":"pressure for","meaning":"對……的壓力","examples":[{"en":"Tourism creates pressure for more coastal facilities.","zh":"旅遊對更多沿海設施造成需求壓力。"},{"en":"Pressure for something means strong demand or force pushing people to provide or do it.","zh":"對某事的壓力，是強烈需求或力量，推動人們提供或做某事。"},{"en":"Parents may create pressure for smaller classes if students are not receiving enough attention.","zh":"如果學生得不到足夠關注，家長可能形成對小班教學的壓力。"},{"en":"Pressure for development can grow when businesses expect more visitors or customers.","zh":"當企業預期更多遊客或顧客，發展壓力可能增加。"},{"en":"This phrase describes demand that pushes action.","zh":"這個短語描述推動行動的需求。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":4},{"front":"increased provision of","meaning":"增加提供……","examples":[{"en":"There is pressure for increased provision of marinas.","zh":"人們對增加提供遊艇碼頭有壓力。"},{"en":"Increased provision of something means more of it is being supplied or made available.","zh":"增加提供某物，是指供應或可用數量增加。"},{"en":"A town may need increased provision of buses when more students commute from far away.","zh":"當更多學生從遠處通學，城鎮可能需要增加提供巴士服務。"},{"en":"More provision can solve one problem but create another if land or resources are limited.","zh":"如果土地或資源有限，增加提供某物可能解決一個問題卻製造另一問題。"},{"en":"This phrase describes expanding supply.","zh":"這個短語描述供應擴大。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":4},{"front":"facilities such as","meaning":"例如……的設施","examples":[{"en":"Facilities such as marinas can threaten coastal archaeology.","zh":"例如遊艇碼頭的設施可以威脅沿海考古。"},{"en":"Facilities such as means examples of buildings, services, or structures of a certain type.","zh":"例如某物的設施，是指某一類建築、服務或結構的例子。"},{"en":"Schools need facilities such as libraries, laboratories, and sports halls.","zh":"學校需要圖書館、實驗室和體育館等設施。"},{"en":"New facilities can improve services, but they may also disturb land or heritage sites.","zh":"新設施可以改善服務，但也可能擾動土地或文化遺址。"},{"en":"This phrase introduces examples within a broader category.","zh":"這個短語引入較大類別中的例子。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":4},{"front":"marinas","meaning":"遊艇碼頭","examples":[{"en":"Marinas are leisure facilities along the coast.","zh":"遊艇碼頭是沿海休閒設施。"},{"en":"Marinas are places where private boats and yachts can be kept, serviced, or launched.","zh":"遊艇碼頭是私人船隻和遊艇可以停泊、維修或下水的地方。"},{"en":"A seaside town may build a marina to attract visitors who own boats.","zh":"海濱城鎮可能建造遊艇碼頭來吸引擁有船隻的遊客。"},{"en":"Marinas can bring tourism income, but construction may damage coastal deposits.","zh":"遊艇碼頭可以帶來旅遊收入，但建設可能損害沿海沉積層。"},{"en":"This word refers to modern boating facilities, not ancient ports.","zh":"這個詞指現代船艇設施，而不是古代港口。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":4},{"front":"larger size of ferries","meaning":"渡輪體積增大","examples":[{"en":"The larger size of ferries has caused more damage.","zh":"渡輪體積增大造成更多破壞。"},{"en":"Larger size of ferries means ferries have become bigger, heavier, or more powerful.","zh":"渡輪體積增大，是指渡輪變得更大、更重或動力更強。"},{"en":"A larger ferry can carry more passengers and vehicles across a busy route.","zh":"較大型渡輪可以在繁忙航線上運載更多乘客和車輛。"},{"en":"Bigger ferries may create stronger waves that disturb fragile coastal deposits.","zh":"更大型渡輪可能產生更強海浪，擾動脆弱沿海沉積層。"},{"en":"This phrase connects transport growth with environmental pressure.","zh":"這個短語把交通增長與環境壓力連接起來。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":4},{"front":"caused an increase in","meaning":"導致……增加","examples":[{"en":"Larger ferries have caused an increase in damage.","zh":"更大型渡輪導致破壞增加。"},{"en":"Caused an increase in something means made that thing happen more often or at a higher level.","zh":"導致某事增加，是指令該事更常發生或水平更高。"},{"en":"More cars have caused an increase in traffic noise near the school.","zh":"更多汽車導致學校附近交通噪音增加。"},{"en":"When a cause increases damage, managers must decide how to reduce or control it.","zh":"當某原因令破壞增加，管理者必須決定如何減少或控制它。"},{"en":"This phrase links a change directly to a rise in a result.","zh":"這個短語把變化直接連接到結果上升。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":4},{"front":"their wash","meaning":"船隻激起的浪","examples":[{"en":"Ferries can damage fragile deposits through their wash.","zh":"渡輪可以透過船隻激起的浪損害脆弱沉積層。"},{"en":"Their wash means the waves or disturbed water created behind moving boats or ferries.","zh":"船隻激起的浪，是移動中的船隻或渡輪後方產生的波浪或擾動水流。"},{"en":"A fast boat’s wash can rock smaller boats near a harbour wall.","zh":"快艇激起的浪可以令港口牆附近的小船搖晃。"},{"en":"Strong wash can erode banks, disturb mud, and expose buried remains.","zh":"強烈船浪可以侵蝕河岸、擾動淤泥並暴露被埋藏遺存。"},{"en":"This phrase describes the water movement caused by vessels.","zh":"這個短語描述船隻造成的水流動。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":4},{"front":"fragile deposits","meaning":"脆弱沉積層","examples":[{"en":"Fragile deposits in the intertidal zone are vulnerable.","zh":"潮間帶中的脆弱沉積層很容易受損。"},{"en":"Fragile deposits are delicate layers of soil, mud, sand, or archaeological material that can be easily damaged.","zh":"脆弱沉積層是容易被破壞的泥土、淤泥、沙或考古材料層。"},{"en":"Old wooden remains in wet mud may be part of fragile deposits.","zh":"濕泥中的古老木材遺存可能是脆弱沉積層的一部分。"},{"en":"Fragile deposits need careful protection because waves or construction can destroy them quickly.","zh":"脆弱沉積層需要仔細保護，因為海浪或建設可以很快摧毀它們。"},{"en":"This phrase refers to sensitive layers that preserve evidence.","zh":"這個短語指保存證據的敏感層位。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":4},{"front":"intertidal zone","meaning":"潮間帶","examples":[{"en":"Ferry wash can damage deposits in the intertidal zone.","zh":"渡輪激起的浪可以損害潮間帶中的沉積層。"},{"en":"The intertidal zone is the area between high tide and low tide.","zh":"潮間帶是高潮位與低潮位之間的區域。"},{"en":"Shellfish, seaweed, and mudflats are often found in the intertidal zone.","zh":"貝類、海藻和泥灘常見於潮間帶。"},{"en":"Archaeological remains there face both exposure to air and repeated covering by water.","zh":"那裡的考古遺存既會暴露於空氣中，又會反覆被水覆蓋。"},{"en":"This phrase describes a changing coastal area controlled by tides.","zh":"這個短語描述受潮汐控制的變化中沿海區域。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":5},{"front":"most significant natural threat","meaning":"最重大的自然威脅","examples":[{"en":"The predicted rise in sea level is the most significant natural threat.","zh":"預測中的海平面上升是最重大的自然威脅。"},{"en":"The most significant natural threat is the natural danger with the greatest likely impact.","zh":"最重大的自然威脅，是可能影響最大的自然危險。"},{"en":"In a forest village, wildfire may be the most significant natural threat.","zh":"在森林村莊中，山火可能是最重大的自然威脅。"},{"en":"Identifying the main natural threat helps planners decide what to protect first.","zh":"識別主要自然威脅有助規劃者決定先保護甚麼。"},{"en":"This phrase ranks one danger as more important than others.","zh":"這個短語把一項危險列為比其他危險更重要。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":5},{"front":"predicted rise in sea level","meaning":"預測中的海平面上升","examples":[{"en":"The predicted rise in sea level threatens coastal archaeology.","zh":"預測中的海平面上升威脅沿海考古。"},{"en":"Predicted rise in sea level means the expected future increase in the average height of the sea.","zh":"預測中的海平面上升，是指預期未來平均海面高度增加。"},{"en":"A predicted rise in sea level may lead governments to strengthen flood defences.","zh":"預測中的海平面上升可能令政府加強防洪設施。"},{"en":"Predictions matter because planners must act before the full rise has happened.","zh":"預測很重要，因為規劃者必須在完整上升發生前行動。"},{"en":"This phrase connects future climate risk with coastal planning.","zh":"這個短語把未來氣候風險與沿海規劃連接起來。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":5},{"front":"south and east of England","meaning":"英格蘭南部和東部","examples":[{"en":"The threat is especially important in the south and east of England.","zh":"這項威脅在英格蘭南部和東部尤其重要。"},{"en":"The south and east of England means the southern and eastern regions of England.","zh":"英格蘭南部和東部，是指英格蘭的南方和東方地區。"},{"en":"Low-lying areas in the south and east of England may be more exposed to sea-level change.","zh":"英格蘭南部和東部的低窪地區可能更容易受海平面變化影響。"},{"en":"Regional differences matter because coastal threats do not affect every place equally.","zh":"地區差異很重要，因為沿海威脅不會同等影響每個地方。"},{"en":"This phrase identifies the area where the risk is especially serious.","zh":"這個短語指出風險尤其嚴重的地區。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":5},{"front":"impact on archaeology","meaning":"對考古的影響","examples":[{"en":"The impact on archaeology is not easy to predict.","zh":"對考古的影響並不容易預測。"},{"en":"Impact on archaeology means the effect something has on archaeological sites, evidence, research, or preservation.","zh":"對考古的影響，是某事對考古遺址、證據、研究或保存造成的效果。"},{"en":"A new railway may have an impact on archaeology if it crosses an ancient settlement.","zh":"如果新鐵路穿過古代聚落，它可能對考古有影響。"},{"en":"Environmental change can affect archaeology by exposing, burying, or destroying remains.","zh":"環境變化可以透過暴露、掩埋或摧毀遺存來影響考古。"},{"en":"This phrase asks how archaeology itself will be changed or harmed.","zh":"這個短語詢問考古本身會如何被改變或傷害。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":5},{"front":"not easy to predict","meaning":"不容易預測","examples":[{"en":"The impact of sea-level rise is not easy to predict.","zh":"海平面上升的影響不容易預測。"},{"en":"Not easy to predict means difficult to know in advance.","zh":"不容易預測，是指很難預先知道。"},{"en":"The result of a new school policy is not easy to predict before students and teachers try it.","zh":"新學校政策在學生和老師試行前，其結果不容易預測。"},{"en":"Prediction becomes harder when many local factors are involved.","zh":"當涉及許多本地因素，預測會變得更困難。"},{"en":"This phrase shows uncertainty about future results.","zh":"這個短語顯示對未來結果的不確定。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":5},{"front":"likely to be highly localised","meaning":"很可能高度局部化","examples":[{"en":"The impact is likely to be highly localised.","zh":"影響很可能高度局部化。"},{"en":"Likely to be highly localised means expected to affect specific small areas rather than everywhere equally.","zh":"很可能高度局部化，是指預期只影響特定小區域，而不是平均影響各處。"},{"en":"Flooding after heavy rain may be highly localised if only low streets are affected.","zh":"暴雨後如果只有低窪街道受影響，水浸可能高度局部化。"},{"en":"Localised impact makes management difficult because each site needs its own assessment.","zh":"局部化影響令管理困難，因為每個遺址都需要個別評估。"},{"en":"This phrase stresses place-by-place variation.","zh":"這個短語強調因地而異。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":5},{"front":"at a scale much larger than","meaning":"規模遠大於……","examples":[{"en":"The threat will operate at a scale much larger than most sites.","zh":"這項威脅運作的規模將遠大於大多數遺址。"},{"en":"At a scale much larger than something means over a size or range far beyond it.","zh":"規模遠大於某事，是指範圍或大小遠超它。"},{"en":"A city-wide transport strike happens at a scale much larger than one school’s timetable problem.","zh":"全城交通罷工的規模遠大於一間學校的時間表問題。"},{"en":"Large-scale threats are hard to solve with small, site-by-site measures alone.","zh":"大規模威脅很難只靠逐個小地點措施解決。"},{"en":"This phrase compares the size of a problem with the size of what it affects.","zh":"這個短語比較問題規模與受影響對象規模。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":5},{"front":"protecting one site","meaning":"保護某一遺址","examples":[{"en":"Protecting one site may move the threat elsewhere.","zh":"保護某一遺址可能把威脅移到其他地方。"},{"en":"Protecting one site means taking action to defend a particular place from damage.","zh":"保護某一遺址，是指採取行動保護特定地點免受破壞。"},{"en":"A town may protect one beach by building a sea wall.","zh":"城鎮可能透過建造海堤來保護一個海灘。"},{"en":"Protection in one location can change waves or sediment and create problems nearby.","zh":"一個地點的保護措施會改變海浪或沉積物，並在附近造成問題。"},{"en":"This phrase shows that local solutions can have wider consequences.","zh":"這個短語顯示本地解決方案可以有更廣泛後果。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":5},{"front":"result in","meaning":"導致","examples":[{"en":"Protecting one site may result in moving the threat.","zh":"保護某一遺址可能導致威脅被轉移。"},{"en":"To result in something means to cause that outcome.","zh":"導致某事，是指造成該結果。"},{"en":"Poor drainage can result in flooding after heavy rain.","zh":"排水不良可以導致暴雨後水浸。"},{"en":"A protective action can result in unexpected damage if the wider system is not understood.","zh":"如果不了解更大系統，保護行動可能導致意外損害。"},{"en":"This phrase connects an action with its consequence.","zh":"這個短語把行動與後果連接起來。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":5},{"front":"transposing the threat","meaning":"轉移威脅","examples":[{"en":"Protecting one site may simply transpose the threat further along the coast.","zh":"保護某一遺址可能只是把威脅轉移到海岸更遠處。"},{"en":"Transposing the threat means moving the danger from one place to another instead of removing it.","zh":"轉移威脅，是指把危險從一處移到另一處，而不是消除它。"},{"en":"Building a wall in one street may transpose floodwater to a neighbouring street.","zh":"在一條街建牆可能把洪水轉移到鄰近街道。"},{"en":"Transposing a threat can make a solution unfair if another community suffers the damage.","zh":"如果另一個社區承受損害，轉移威脅會令解決方案變得不公平。"},{"en":"This phrase warns that protection may shift risk rather than solve it.","zh":"這個短語提醒我們，保護可能只是轉移風險，而不是解決風險。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":5},{"front":"further along the coast","meaning":"沿海岸更遠處","examples":[{"en":"The threat may move further along the coast.","zh":"威脅可能移到沿海岸更遠處。"},{"en":"Further along the coast means at another point farther away on the same coastline.","zh":"沿海岸更遠處，是指在同一海岸線上較遠的另一地點。"},{"en":"If one beach is protected, erosion may appear further along the coast near another village.","zh":"如果一個海灘受到保護，侵蝕可能出現在沿岸更遠處的另一村莊附近。"},{"en":"Coastal systems are connected, so changes in one place can affect places down the shore.","zh":"沿海系統互相連接，所以一地變化可以影響海岸下游地區。"},{"en":"This phrase describes movement or impact along a coastline.","zh":"這個短語描述沿海岸的移動或影響。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":6},{"front":"considered over","meaning":"在……範圍內考慮","examples":[{"en":"Management must be considered over a longer timescale.","zh":"管理必須在較長時間尺度內考慮。"},{"en":"Considered over a period means examined across that length of time, not only at one moment.","zh":"在某段時間範圍內考慮，是指跨越該時間長度來檢視，而不只是看某一刻。"},{"en":"A child’s progress should be considered over a school year, not just one test.","zh":"孩子的進步應在一個學年內考慮，而不是只看一次測驗。"},{"en":"Long-term problems need to be considered over many years because effects build slowly.","zh":"長期問題需要在多年內考慮，因為影響會慢慢累積。"},{"en":"This phrase describes the time frame used for judgement.","zh":"這個短語描述用來判斷的時間框架。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":6},{"front":"much longer timescale","meaning":"長得多的時間尺度","examples":[{"en":"Coastal archaeology requires management over a much longer timescale.","zh":"沿海考古需要在長得多的時間尺度上管理。"},{"en":"A much longer timescale means a far longer period than usual or than another comparison point.","zh":"長得多的時間尺度，是指比平常或比較對象長得多的時期。"},{"en":"Climate planning needs a much longer timescale than planning a weekend event.","zh":"氣候規劃需要比週末活動規劃長得多的時間尺度。"},{"en":"Archaeological resources may need protection across decades because erosion and development continue.","zh":"考古資源可能需要跨越數十年保護，因為侵蝕和發展會持續。"},{"en":"This phrase stresses long-term thinking.","zh":"這個短語強調長期思考。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":6},{"front":"wider geographical scale","meaning":"更廣闊的地理尺度","examples":[{"en":"Management must also consider a wider geographical scale.","zh":"管理也必須考慮更廣闊的地理尺度。"},{"en":"A wider geographical scale means a larger physical area must be considered.","zh":"更廣闊的地理尺度，是指必須考慮更大的實體區域。"},{"en":"A traffic problem near one school may need a wider geographical scale if nearby roads are also affected.","zh":"如果附近道路也受影響，一間學校附近的交通問題可能需要更廣闊的地理尺度。"},{"en":"Coastal management must consider connected beaches, estuaries, towns, and habitats.","zh":"沿海管理必須考慮互相連接的海灘、河口、城鎮和棲息地。"},{"en":"This phrase expands attention from one site to a broader area.","zh":"這個短語把注意力由單一遺址擴展到更大區域。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":6},{"front":"common in the case of","meaning":"在……情況下常見","examples":[{"en":"This approach is wider than is common in the case of dry land sites.","zh":"這種方法比旱地遺址情況下常見的方法更廣。"},{"en":"Common in the case of something means usual when dealing with that type of situation.","zh":"在某情況下常見，是指處理該類情況時通常會出現。"},{"en":"Written feedback is common in the case of essay assignments.","zh":"書面回饋在作文作業情況下很常見。"},{"en":"A method common for one type of site may not work well for coastal archaeology.","zh":"對某類遺址常見的方法，未必適合沿海考古。"},{"en":"This phrase compares what is usual in one situation with what is needed in another.","zh":"這個短語比較某情況中的通常做法與另一情況所需做法。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":6},{"front":"pose a serious challenge","meaning":"構成嚴峻挑戰","examples":[{"en":"This will pose a serious challenge for archaeologists.","zh":"這將對考古學家構成嚴峻挑戰。"},{"en":"To pose a serious challenge means to create a difficult problem that requires skill and effort.","zh":"構成嚴峻挑戰，是指造成需要技巧和努力處理的困難問題。"},{"en":"A sudden rise in student numbers can pose a serious challenge for a small school.","zh":"學生人數突然上升可以對小學校構成嚴峻挑戰。"},{"en":"Serious challenges require planning because quick fixes may not be enough.","zh":"嚴峻挑戰需要規劃，因為快速修補未必足夠。"},{"en":"This phrase describes a major difficulty ahead.","zh":"這個短語描述前方的重大困難。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":6},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students should choose the correct letter for each question.","zh":"學生應為每條問題選出正確字母。"},{"en":"To choose the correct letter means to select the answer option that matches the passage.","zh":"選出正確字母，是指選擇與篇章相符的答案選項。"},{"en":"In a multiple-choice task, students choose the correct letter rather than writing a full sentence.","zh":"在選擇題中，學生選出正確字母，而不是寫完整句子。"},{"en":"Careful reading helps students avoid choosing a letter only because it contains familiar words.","zh":"仔細閱讀幫助學生避免只因選項含有熟悉字眼就選該字母。"},{"en":"This phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":6},{"front":"write your answers in","meaning":"將答案寫在……","examples":[{"en":"Students should write their answers in the boxes.","zh":"學生應將答案寫在方格內。"},{"en":"Write your answers in means put the required answers in a specified place.","zh":"將答案寫在某處，是指把所需答案放在指定位置。"},{"en":"Candidates must write their answers in pencil on the answer sheet.","zh":"考生必須用鉛筆將答案寫在答題紙上。"},{"en":"Writing answers in the correct space helps examiners mark them clearly.","zh":"把答案寫在正確位置有助考官清楚評分。"},{"en":"This phrase tells students where their answers should go.","zh":"這個短語告訴學生答案應寫在哪裡。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":6},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"The answers should be written on the answer sheet.","zh":"答案應寫在答題紙上。"},{"en":"An answer sheet is the paper or digital form where candidates record their final answers.","zh":"答題紙是考生記錄最終答案的紙張或電子表格。"},{"en":"A student may lose marks if the answer is correct in the booklet but missing from the answer sheet.","zh":"如果答案在試題簿中正確但沒有寫在答題紙上，學生可能失分。"},{"en":"Answer sheets help markers check responses quickly and consistently.","zh":"答題紙幫助評分者快速且一致地檢查回應。"},{"en":"This phrase refers to the official place for exam answers.","zh":"這個短語指考試答案的正式位置。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":6},{"front":"caused public interest in","meaning":"引起公眾對……的興趣","examples":[{"en":"The question asks what caused public interest in coastal archaeology.","zh":"題目問甚麼引起公眾對沿海考古學的興趣。"},{"en":"Caused public interest in something means made ordinary people pay attention to it.","zh":"引起公眾對某事的興趣，是指令普通人注意它。"},{"en":"A documentary may cause public interest in food waste by showing how much is thrown away.","zh":"紀錄片展示大量食物被丟棄，可能引起公眾對食物浪費的興趣。"},{"en":"Public interest often grows when a topic connects with people’s safety, identity, or future.","zh":"當課題與人們的安全、身份或未來相關，公眾興趣通常會增加。"},{"en":"This phrase links a cause with wider public attention.","zh":"這個短語把原因與更廣泛公眾關注連接起來。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":6},{"front":"rapid development of","meaning":"……的快速發展","examples":[{"en":"The option refers to the rapid development of coastal archaeology.","zh":"該選項提到沿海考古學的快速發展。"},{"en":"Rapid development of something means quick growth, progress, or change in that field.","zh":"某事的快速發展，是指該領域迅速增長、進步或改變。"},{"en":"The rapid development of online learning changed how students attend lessons.","zh":"網上學習的快速發展改變了學生上課方式。"},{"en":"Rapid development can create excitement, but it may also leave gaps in planning.","zh":"快速發展可以令人興奮，但也可能留下規劃空白。"},{"en":"This phrase describes fast progress over a relatively short time.","zh":"這個短語描述在較短時間內出現的快速進步。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":6},{"front":"rising awareness of","meaning":"對……日益提高的意識","examples":[{"en":"Public interest grew with rising awareness of climate change.","zh":"公眾興趣隨着對氣候變化日益提高的意識而增加。"},{"en":"Rising awareness of something means more people are becoming conscious of it and its importance.","zh":"對某事日益提高的意識，是指更多人開始意識到它及其重要性。"},{"en":"Rising awareness of mental health has made schools discuss stress more openly.","zh":"對心理健康日益提高的意識令學校更公開討論壓力。"},{"en":"Awareness rises when research, media, and real-life events make a problem visible.","zh":"當研究、媒體和真實事件令問題可見，意識就會提高。"},{"en":"This phrase describes increasing public understanding.","zh":"這個短語描述公眾理解逐漸增加。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":7},{"front":"underwater forest","meaning":"水下森林","examples":[{"en":"The option refers to the discovery of an underwater forest.","zh":"該選項提到水下森林的發現。"},{"en":"An underwater forest is an ancient forest or group of tree remains now covered by water.","zh":"水下森林是現在被水覆蓋的古代森林或樹木遺存群。"},{"en":"An underwater forest may appear at low tide as dark tree stumps in mud.","zh":"水下森林可能在退潮時以泥中深色樹樁形式出現。"},{"en":"Such a discovery can show that land once existed where sea now covers the area.","zh":"這類發現可以顯示現在被海水覆蓋的地方曾是陸地。"},{"en":"This phrase is similar to submerged forests but uses simpler wording.","zh":"這個短語與 submerged forests 相似，但用詞較簡單。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":7},{"front":"systematic research conducted on","meaning":"對……進行的系統研究","examples":[{"en":"The option mentions systematic research conducted on coastal findings.","zh":"該選項提到對沿海發現進行的系統研究。"},{"en":"Systematic research conducted on something means organised study carried out carefully and methodically.","zh":"對某事進行的系統研究，是有組織、仔細且按方法進行的研究。"},{"en":"Systematic research conducted on student reading habits can reveal patterns that teachers miss.","zh":"對學生閱讀習慣進行的系統研究，可以揭示老師錯過的模式。"},{"en":"Systematic research is stronger than casual observation because it follows a clear method.","zh":"系統研究比隨意觀察更強，因為它遵循清晰方法。"},{"en":"This phrase describes formal investigation of a subject.","zh":"這個短語描述對課題的正式調查。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":7},{"front":"coastal archaeological findings","meaning":"沿海考古發現","examples":[{"en":"Coastal archaeological findings have attracted research interest.","zh":"沿海考古發現吸引了研究興趣。"},{"en":"Coastal archaeological findings are discoveries from coastal areas that help explain past human life.","zh":"沿海考古發現，是來自沿海地區並有助解釋過去人類生活的發現。"},{"en":"A fish weir, boat fragment, or buried land surface can be a coastal archaeological finding.","zh":"魚梁、船隻碎片或被埋藏地表都可以是沿海考古發現。"},{"en":"Such findings matter because they show how people used changing shorelines and marine resources.","zh":"這些發現很重要，因為它們顯示人們如何使用變化中的海岸線和海洋資源。"},{"en":"This phrase refers to discoveries made in coastal archaeology.","zh":"這個短語指沿海考古中的發現。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":7},{"front":"evidence of boats","meaning":"船隻證據","examples":[{"en":"The question asks what the passage says about the evidence of boats.","zh":"題目問篇章對船隻證據有何說法。"},{"en":"Evidence of boats means physical or recorded signs that boats existed or were used.","zh":"船隻證據是顯示船隻存在或被使用的實體或紀錄跡象。"},{"en":"Wooden planks, wrecks, landing places, and tool marks can provide evidence of boats.","zh":"木板、沉船、登岸地點和工具痕跡都可以提供船隻證據。"},{"en":"Boat evidence helps researchers understand travel, trade, fishing, and technology.","zh":"船隻證據幫助研究人員理解旅行、貿易、捕魚和技術。"},{"en":"This phrase focuses on traces that support claims about past boat use.","zh":"這個短語聚焦支持過去船隻使用說法的痕跡。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":7},{"front":"prehistoric boatbuilding technology","meaning":"史前造船技術","examples":[{"en":"The passage says our knowledge of prehistoric boatbuilding technology is limited.","zh":"篇章說我們對史前造船技術的認識有限。"},{"en":"Prehistoric boatbuilding technology means the methods and tools early people used to make boats before written history.","zh":"史前造船技術，是文字歷史以前早期人類用來製造船隻的方法和工具。"},{"en":"Sewn-plank boats provide clues about prehistoric boatbuilding technology.","zh":"縫合木板船提供了史前造船技術的線索。"},{"en":"Limited evidence makes it difficult to know exactly how early boats were built and repaired.","zh":"證據有限令人難以確切知道早期船隻如何建造和維修。"},{"en":"This phrase connects ancient craft skills with archaeological research.","zh":"這個短語把古代工藝技能與考古研究連接起來。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":7},{"front":"gap of one thousand years","meaning":"一千年的空白","examples":[{"en":"There is a gap of one thousand years in the boat record.","zh":"船隻記錄中有一千年的空白。"},{"en":"A gap of one thousand years means evidence is missing for a period lasting a millennium.","zh":"一千年的空白，是指有長達一千年的時期缺乏證據。"},{"en":"A family archive may have a gap of fifty years if no letters or photos survive.","zh":"如果沒有信件或照片保存，家族檔案可能有五十年的空白。"},{"en":"A long gap in records makes it hard to trace continuous development.","zh":"記錄中的長空白令人難以追蹤持續發展。"},{"en":"This phrase describes a major missing period in evidence.","zh":"這個短語描述證據中的重大缺失時期。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":7},{"front":"record of boat use","meaning":"船隻使用記錄","examples":[{"en":"The record of boat use has a long unexplained gap.","zh":"船隻使用記錄中有一段長而無法解釋的空白。"},{"en":"Record of boat use means the surviving evidence that shows when and how boats were used.","zh":"船隻使用記錄，是顯示船隻何時以及如何被使用的存留證據。"},{"en":"Old docks, wrecks, and written accounts can form part of the record of boat use.","zh":"舊碼頭、沉船和書面記載都可以構成船隻使用記錄的一部分。"},{"en":"If the record is incomplete, researchers cannot easily trace technological change.","zh":"如果記錄不完整，研究人員就難以追蹤技術變遷。"},{"en":"This phrase refers to evidence, not the actual use itself.","zh":"這個短語指證據，而不是使用行為本身。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":7},{"front":"first used for","meaning":"最初被用於……","examples":[{"en":"The option asks whether boats were first used for fishing.","zh":"該選項問船隻是否最初被用於捕魚。"},{"en":"First used for something means originally used for that purpose before other uses developed.","zh":"最初被用於某事，是指在其他用途發展前，原本用於該目的。"},{"en":"A school hall may have been first used for assemblies before becoming an exam room.","zh":"學校禮堂可能最初被用於早會，後來才成為考場。"},{"en":"Knowing the first use of an object helps explain why it was designed in a certain way.","zh":"知道物件最初用途，有助解釋它為何以某種方式設計。"},{"en":"This phrase asks about original purpose.","zh":"這個短語詢問原始用途。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":7},{"front":"discovered from the air","meaning":"從空中發現","examples":[{"en":"Some fisheries can be discovered from the air.","zh":"有些漁業設施可以從空中發現。"},{"en":"Discovered from the air means found by looking from above, often using aircraft, drones, or aerial photographs.","zh":"從空中發現，是指從上方觀察而找到，通常使用飛機、無人機或航拍照片。"},{"en":"Old field boundaries may be discovered from the air when crop marks appear in summer.","zh":"夏天作物痕跡出現時，舊田界可能從空中被發現。"},{"en":"Aerial views can reveal large patterns that are hard to see on the ground.","zh":"空中視角可以揭示地面上難以看見的大型圖案。"},{"en":"This phrase describes discovery through overhead observation.","zh":"這個短語描述透過高空觀察進行發現。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":7},{"front":"salt mines","meaning":"鹽礦","examples":[{"en":"The option refers to salt mines.","zh":"該選項提到鹽礦。"},{"en":"Salt mines are places where salt is extracted from underground deposits.","zh":"鹽礦是從地下礦藏開採鹽的地方。"},{"en":"Workers in a salt mine remove rock salt that can later be processed and sold.","zh":"鹽礦工人開採岩鹽，之後可以加工和出售。"},{"en":"Salt mines differ from coastal salt working, which often uses seawater or brine.","zh":"鹽礦不同於沿海製鹽，後者通常使用海水或鹽水。"},{"en":"This phrase refers to underground extraction rather than shoreline production.","zh":"這個短語指地下開採，而不是海岸生產。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":7},{"front":"Roman towns","meaning":"羅馬城鎮","examples":[{"en":"The option refers to Roman towns.","zh":"該選項提到羅馬城鎮。"},{"en":"Roman towns are settlements built, occupied, or strongly influenced during the Roman period.","zh":"羅馬城鎮是羅馬時期建造、居住或深受羅馬影響的聚落。"},{"en":"Roman towns may include roads, walls, baths, markets, and official buildings.","zh":"羅馬城鎮可能包括道路、城牆、浴場、市場和官方建築。"},{"en":"Studying Roman towns helps archaeologists understand trade, government, and daily life under Roman influence.","zh":"研究羅馬城鎮幫助考古學家理解羅馬影響下的貿易、政府和日常生活。"},{"en":"This phrase names urban settlements from the Roman era.","zh":"這個短語命名羅馬時代的城市聚落。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":8},{"front":"harbours","meaning":"海港","examples":[{"en":"The option refers to harbours.","zh":"該選項提到海港。"},{"en":"Harbours are sheltered coastal places where boats and ships can stay safely.","zh":"海港是船隻可以安全停泊的受保護沿海地點。"},{"en":"A harbour protects fishing boats from waves during bad weather.","zh":"惡劣天氣中，海港保護漁船免受海浪影響。"},{"en":"Harbours often attract trade because goods can be loaded and unloaded more easily there.","zh":"海港常吸引貿易，因為貨物可以較容易裝卸。"},{"en":"This word refers to safe waterside places for vessels.","zh":"這個詞指供船隻使用的安全水邊地點。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":8},{"front":"fisheries","meaning":"漁場；漁業設施","examples":[{"en":"Fish weirs and fisheries can sometimes be seen from aerial photographs.","zh":"魚梁和漁業設施有時可在航拍照片中看見。"},{"en":"Fisheries are places, activities, or industries connected with catching or managing fish.","zh":"漁場或漁業設施，是與捕魚或管理魚類資源相關的地方、活動或行業。"},{"en":"A coastal fishery may include boats, nets, traps, and places for processing fish.","zh":"沿海漁業可能包括船隻、漁網、魚籠和處理魚類的地方。"},{"en":"Fisheries can leave archaeological evidence when people build traps, weirs, or storage areas.","zh":"當人們建造魚籠、魚梁或儲存區時，漁業可以留下考古證據。"},{"en":"This phrase refers to organised use of fish resources.","zh":"這個短語指對魚類資源的有組織利用。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":8},{"front":"do the following statements agree with","meaning":"以下陳述是否與文章一致","examples":[{"en":"Students decide whether the statements agree with the passage.","zh":"學生判斷以下陳述是否與文章一致。"},{"en":"Do the following statements agree with something means check whether each statement matches the information in the text.","zh":"以下陳述是否與某物一致，是指檢查每項陳述是否符合文本資料。"},{"en":"In a reading test, students must not use outside knowledge when deciding whether statements agree with the passage.","zh":"在閱讀測驗中，學生判斷陳述是否與文章一致時，不應使用外部知識。"},{"en":"A statement agrees with the text only if the text clearly supports it.","zh":"只有當文本清楚支持陳述時，該陳述才與文本一致。"},{"en":"This phrase introduces TRUE/FALSE/NOT GIVEN style questions.","zh":"這個短語引入 TRUE/FALSE/NOT GIVEN 類型題目。"}],"source":"33 - Coastal Archaeology of Britain.pdf","sourcePage":8}],"ielts/reading/passage-2/Practice 34":[{"front":"activities for children","meaning":"兒童活動","examples":[{"en":"The passage discusses activities for children and their effect on health.","zh":"文章討論兒童活動及其對健康的影響。"},{"en":"Activities for children are things children do for play, learning, exercise, or social development.","zh":"activities for children 指兒童為遊玩、學習、運動或社交發展而做的事情。"},{"en":"Schools may organise activities for children such as sports, drama, art, and reading clubs.","zh":"學校可能安排運動、戲劇、藝術和閱讀學會等兒童活動。"},{"en":"Good activities for children can improve fitness, confidence, and friendships.","zh":"良好的兒童活動可以改善體能、信心和友誼。"},{"en":"This phrase is useful when discussing how children spend their time.","zh":"討論兒童如何花時間時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":1},{"front":"twenty-five years ago","meaning":"二十五年前","examples":[{"en":"Twenty-five years ago, children in London walked to school.","zh":"二十五年前，倫敦兒童步行上學。"},{"en":"Twenty-five years ago means twenty-five years before the present time or the time being discussed.","zh":"twenty-five years ago 指現在或所討論時間之前的二十五年。"},{"en":"Twenty-five years ago, many families had fewer electronic devices at home.","zh":"二十五年前，許多家庭家中電子設備較少。"},{"en":"Comparing now with twenty-five years ago helps show social change clearly.","zh":"把現在與二十五年前比較，有助清楚顯示社會變化。"},{"en":"This phrase is useful when describing changes over time.","zh":"描述隨時間出現的變化時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":1},{"front":"walked to school","meaning":"步行上學","examples":[{"en":"Children in London used to walk to school.","zh":"倫敦兒童以前步行上學。"},{"en":"Walked to school means went to school on foot rather than by car, bus, or train.","zh":"walked to school 指以步行方式上學，而不是乘車、巴士或火車。"},{"en":"A child who lives nearby may walk to school with friends every morning.","zh":"住得近的孩子可能每天早上和朋友一起步行上學。"},{"en":"Walking to school gives children light exercise before lessons begin.","zh":"步行上學讓兒童在上課前做輕量運動。"},{"en":"This phrase often contrasts with being driven to school.","zh":"這個短語常與被駕車送上學形成對比。"}],"source":"34 - Activities for Children.pdf","sourcePage":1},{"front":"playing fields","meaning":"運動場；遊樂場地","examples":[{"en":"Children played in parks and playing fields after school.","zh":"兒童放學後在公園和運動場玩耍。"},{"en":"Playing fields are open outdoor areas used for sports, games, and exercise.","zh":"playing fields 指用於運動、遊戲和鍛煉的戶外空地。"},{"en":"A school may use playing fields for football, running, and PE lessons.","zh":"學校可能使用運動場進行足球、跑步和體育課。"},{"en":"If playing fields disappear, children have fewer safe places to be active.","zh":"如果運動場消失，兒童就會有較少安全地方活動。"},{"en":"This phrase is common when discussing school sport and community space.","zh":"討論學校體育和社區空間時，這個短語很常見。"}],"source":"34 - Activities for Children.pdf","sourcePage":1},{"front":"at the weekend","meaning":"在週末","examples":[{"en":"Children played outdoors after school and at the weekend.","zh":"兒童放學後和週末在戶外玩耍。"},{"en":"At the weekend means on Saturday, Sunday, or both days.","zh":"at the weekend 指在星期六、星期日或兩天之中。"},{"en":"Families may go hiking at the weekend if the weather is good.","zh":"如果天氣好，家庭可能在週末去行山。"},{"en":"Weekend activities can give children more time for exercise and outdoor play.","zh":"週末活動可以給兒童更多時間做運動和戶外玩耍。"},{"en":"This phrase is common in everyday British English.","zh":"這個短語常見於日常英式英語。"}],"source":"34 - Activities for Children.pdf","sourcePage":1},{"front":"driven to school","meaning":"被駕車送上學","examples":[{"en":"Today many children are driven to school by their parents.","zh":"今天許多兒童由父母駕車送上學。"},{"en":"Driven to school means taken to school by car or another vehicle.","zh":"driven to school 指由汽車或其他車輛送往學校。"},{"en":"Some parents drive children to school because the route feels unsafe.","zh":"有些家長因為路線感覺不安全而駕車送子女上學。"},{"en":"Being driven to school may reduce the amount of walking children do each day.","zh":"被駕車送上學可能減少兒童每天步行的量。"},{"en":"This phrase contrasts with walking or cycling to school.","zh":"這個短語與步行或踩單車上學形成對比。"}],"source":"34 - Activities for Children.pdf","sourcePage":1},{"front":"anxious about safety","meaning":"擔心安全","examples":[{"en":"Parents are anxious about safety when their children travel alone.","zh":"當子女獨自出行時，家長擔心安全。"},{"en":"Anxious about safety means worried that someone may be hurt or face danger.","zh":"anxious about safety 指擔心某人可能受傷或遇到危險。"},{"en":"Parents may be anxious about safety when children cross busy roads alone.","zh":"當孩子獨自橫過繁忙馬路時，家長可能擔心安全。"},{"en":"Safety worries can lead parents to drive children instead of letting them walk.","zh":"安全憂慮可以令家長駕車送孩子，而不是讓他們步行。"},{"en":"This phrase is useful when explaining cautious behaviour caused by fear.","zh":"解釋由恐懼造成的謹慎行為時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":1},{"front":"spend hours glued to","meaning":"花數小時黏着……","examples":[{"en":"Many children spend hours glued to television screens.","zh":"許多兒童花數小時黏着電視螢幕。"},{"en":"To spend hours glued to something means to stay focused on it for a long time, often without moving much.","zh":"spend hours glued to something 指長時間專注於某物，通常很少活動。"},{"en":"A teenager may spend hours glued to a phone during the holidays.","zh":"青少年在假期可能花數小時黏着手機。"},{"en":"Spending too long glued to screens can reduce time for sleep, exercise, and social play.","zh":"長時間黏着螢幕可以減少睡眠、運動和社交遊戲時間。"},{"en":"This phrase is informal and often suggests unhealthy overuse.","zh":"這個短語較口語，常暗示不健康的過度使用。"}],"source":"34 - Activities for Children.pdf","sourcePage":1},{"front":"television screens","meaning":"電視螢幕","examples":[{"en":"Children spend hours glued to television screens or computer games.","zh":"兒童花很多小時黏着電視螢幕或電腦遊戲。"},{"en":"Television screens are screens on TV sets used for watching programmes, films, or videos.","zh":"television screens 指電視機上用來觀看節目、電影或影片的螢幕。"},{"en":"Families may gather around television screens to watch a sports final.","zh":"家庭可能圍着電視螢幕觀看體育決賽。"},{"en":"Too much time in front of television screens can replace active play.","zh":"太多時間在電視螢幕前，可以取代活躍玩耍。"},{"en":"This phrase is useful when discussing screen time and children’s habits.","zh":"討論螢幕時間和兒童習慣時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":1},{"front":"computer games","meaning":"電腦遊戲","examples":[{"en":"Children spend many hours playing computer games.","zh":"兒童花很多小時玩電腦遊戲。"},{"en":"Computer games are digital games played on computers, consoles, tablets, or phones.","zh":"computer games 指在電腦、遊戲機、平板或手機上玩的數碼遊戲。"},{"en":"Some children play computer games with friends after finishing homework.","zh":"有些孩子做完功課後和朋友一起玩電腦遊戲。"},{"en":"Computer games can be entertaining, but too much gaming may reduce physical activity.","zh":"電腦遊戲可以有娛樂性，但過度打機可能減少體能活動。"},{"en":"This phrase is common when discussing children’s leisure time.","zh":"討論兒童休閒時間時，這個短語很常見。"}],"source":"34 - Activities for Children.pdf","sourcePage":1},{"front":"meanwhile","meaning":"與此同時","examples":[{"en":"Meanwhile, community playing fields are being sold off.","zh":"與此同時，社區運動場正被出售。"},{"en":"Meanwhile means at the same time as another situation is happening.","zh":"meanwhile 指另一情況發生的同時。"},{"en":"Children are spending more time indoors; meanwhile, outdoor spaces are disappearing.","zh":"兒童花更多時間留在室內；與此同時，戶外空間正在消失。"},{"en":"This word helps show two related changes happening together.","zh":"這個詞幫助顯示兩個相關變化同時發生。"},{"en":"It is useful when linking parallel developments.","zh":"連接並行發展時，它很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":1},{"front":"community playing fields","meaning":"社區運動場","examples":[{"en":"Community playing fields are being sold off to property developers.","zh":"社區運動場正被出售予地產發展商。"},{"en":"Community playing fields are open sports spaces used by local residents, schools, or clubs.","zh":"community playing fields 指供本地居民、學校或球會使用的戶外運動空間。"},{"en":"Children may play football on community playing fields after school.","zh":"兒童放學後可能在社區運動場踢足球。"},{"en":"Losing community playing fields can reduce opportunities for safe outdoor exercise.","zh":"失去社區運動場可以減少安全戶外運動機會。"},{"en":"This phrase is useful when discussing public space and children’s health.","zh":"討論公共空間和兒童健康時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":2},{"front":"sold off to","meaning":"被出售予……","examples":[{"en":"Playing fields are being sold off to property developers.","zh":"運動場正被出售予地產發展商。"},{"en":"Sold off to someone means sold, often quickly or completely, to a buyer.","zh":"sold off to someone 指把某物出售給買家，常帶快速或完全出售意味。"},{"en":"A council may sell off old land to companies when it needs money.","zh":"議會需要資金時，可能把舊土地出售給公司。"},{"en":"When public land is sold off, local people may lose shared facilities.","zh":"當公共土地被出售，本地居民可能失去共享設施。"},{"en":"This phrase often suggests concern about losing something valuable.","zh":"這個短語常暗示對失去有價值東西的憂慮。"}],"source":"34 - Activities for Children.pdf","sourcePage":2},{"front":"property developers","meaning":"地產發展商","examples":[{"en":"Property developers are buying community playing fields.","zh":"地產發展商正在購買社區運動場。"},{"en":"Property developers are companies or people who build houses, shops, or offices on land.","zh":"property developers 指在土地上興建住宅、商店或辦公室的公司或人士。"},{"en":"Property developers may buy an old factory site and turn it into apartments.","zh":"地產發展商可能購買舊工廠地皮，並改建成住宅。"},{"en":"Development can create housing, but it may also remove open community spaces.","zh":"發展可以創造住屋，但也可能移除開放社區空間。"},{"en":"This phrase is common in discussions of land use and urban planning.","zh":"這個短語常見於土地使用和城市規劃討論。"}],"source":"34 - Activities for Children.pdf","sourcePage":2},{"front":"at an alarming rate","meaning":"以驚人速度","examples":[{"en":"Community playing fields are being sold off at an alarming rate.","zh":"社區運動場正以驚人速度被出售。"},{"en":"At an alarming rate means so quickly that people become worried.","zh":"at an alarming rate 指速度快到令人擔心。"},{"en":"If trees are cut down at an alarming rate, wildlife may lose habitat fast.","zh":"如果樹木以驚人速度被砍伐，野生動物可能快速失去棲息地。"},{"en":"Rapid loss can create problems before communities have time to respond.","zh":"快速流失可以在社區有時間回應前造成問題。"},{"en":"This phrase is useful when describing a worrying speed of change.","zh":"描述令人憂慮的變化速度時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":2},{"front":"change in lifestyle","meaning":"生活方式的轉變","examples":[{"en":"This change in lifestyle has meant greater restrictions on children.","zh":"這種生活方式的轉變意味兒童受到更多限制。"},{"en":"A change in lifestyle is a shift in how people live, travel, eat, work, or spend time.","zh":"change in lifestyle 指人們生活、出行、飲食、工作或花時間方式的改變。"},{"en":"Moving from a village to a city can create a major change in lifestyle.","zh":"從鄉村搬到城市可以造成重大生活方式轉變。"},{"en":"Lifestyle changes can affect health because daily habits shape the body over time.","zh":"生活方式轉變可以影響健康，因為日常習慣會隨時間塑造身體。"},{"en":"This phrase is useful when comparing old and new ways of living.","zh":"比較新舊生活方式時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":2},{"front":"greater restrictions on","meaning":"對……更多限制","examples":[{"en":"The change has meant greater restrictions on children.","zh":"這種轉變意味對兒童有更多限制。"},{"en":"Greater restrictions on someone means more limits on what they can do or where they can go.","zh":"greater restrictions on someone 指對某人能做甚麼或能去哪裏有更多限制。"},{"en":"Parents may place greater restrictions on screen time during exam season.","zh":"考試季節，家長可能對螢幕時間加上更多限制。"},{"en":"More restrictions can protect children, but they may also reduce freedom and activity.","zh":"更多限制可以保護兒童，但也可能減少自由和活動量。"},{"en":"This phrase is useful when discussing rules, limits, and safety.","zh":"討論規則、限制和安全時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":2},{"front":"Health and Exercise Sciences","meaning":"健康與運動科學","examples":[{"en":"Neil Armstrong is Professor of Health and Exercise Sciences.","zh":"Neil Armstrong 是健康與運動科學教授。"},{"en":"Health and Exercise Sciences is a field that studies health, fitness, physical activity, and the body’s response to exercise.","zh":"Health and Exercise Sciences 指研究健康、體能、體能活動和身體如何回應運動的領域。"},{"en":"A university course in Health and Exercise Sciences may include anatomy, sports training, and public health.","zh":"健康與運動科學的大學課程可能包括解剖學、運動訓練和公共健康。"},{"en":"This field helps explain how movement affects children’s growth and future health.","zh":"這個領域幫助解釋活動如何影響兒童成長和未來健康。"},{"en":"This phrase is formal and academic.","zh":"這個短語較正式，屬於學術用語。"}],"source":"34 - Activities for Children.pdf","sourcePage":2},{"front":"continue to be inactive","meaning":"繼續不活躍","examples":[{"en":"If children continue to be inactive, they will face health problems.","zh":"如果兒童繼續不活躍，他們將面對健康問題。"},{"en":"Continue to be inactive means keep doing too little physical movement over time.","zh":"continue to be inactive 指長時間保持太少身體活動。"},{"en":"A child may continue to be inactive if there are no safe parks nearby.","zh":"如果附近沒有安全公園，孩子可能繼續不活躍。"},{"en":"Long-term inactivity can weaken fitness and increase health risks.","zh":"長期不活躍可以削弱體能並增加健康風險。"},{"en":"This phrase is useful when warning about repeated lack of exercise.","zh":"警告反覆缺乏運動時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":2},{"front":"store up big problems","meaning":"為將來積累大問題","examples":[{"en":"Inactive children may be storing up big problems for the future.","zh":"不活躍的兒童可能正在為將來積累大問題。"},{"en":"To store up big problems means to create problems now that will become serious later.","zh":"store up big problems 指現在造成問題，而這些問題將來會變得嚴重。"},{"en":"Ignoring small homework gaps can store up big problems before final exams.","zh":"忽視小小功課漏洞可能在期末考前積累大問題。"},{"en":"Bad habits may seem harmless today but cause larger difficulties later.","zh":"壞習慣今天可能看似無害，但之後會造成更大困難。"},{"en":"This phrase is useful when warning about delayed consequences.","zh":"警告延遲後果時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":2},{"front":"for the future","meaning":"為將來","examples":[{"en":"Children may be storing up health problems for the future.","zh":"兒童可能正在為將來積累健康問題。"},{"en":"For the future means for a later time, especially long-term life or results.","zh":"for the future 指為較後時間，尤其是長期生活或結果。"},{"en":"Saving money now can help a family prepare for the future.","zh":"現在儲錢可以幫助家庭為將來作準備。"},{"en":"Choices made in childhood can affect health for the future.","zh":"童年時的選擇可以影響將來健康。"},{"en":"This phrase is useful when discussing long-term consequences.","zh":"討論長遠後果時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":2},{"front":"headed a research project","meaning":"領導一項研究項目","examples":[{"en":"Professor Armstrong headed a five-year research project.","zh":"Armstrong 教授領導了一項為期五年的研究項目。"},{"en":"Headed a research project means led and was responsible for a study.","zh":"headed a research project 指領導並負責一項研究。"},{"en":"A university professor may head a research project on student sleep patterns.","zh":"大學教授可能領導一項關於學生睡眠模式的研究項目。"},{"en":"A project leader decides the direction, methods, and team responsibilities.","zh":"項目負責人決定方向、方法和團隊責任。"},{"en":"This phrase is useful when identifying who led a study.","zh":"指出誰領導研究時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":2},{"front":"five-year research project","meaning":"為期五年的研究項目","examples":[{"en":"The professor headed a five-year research project into children’s fitness.","zh":"教授領導了一項為期五年的兒童體能研究項目。"},{"en":"A five-year research project is a study that lasts for five years.","zh":"five-year research project 指持續五年的研究。"},{"en":"A five-year research project can track how students’ habits change as they grow older.","zh":"為期五年的研究項目可以追蹤學生習慣如何隨年齡改變。"},{"en":"Long projects can reveal patterns that short studies may miss.","zh":"長期項目可以揭示短期研究可能錯過的模式。"},{"en":"This phrase is useful when describing serious long-term research.","zh":"描述嚴謹長期研究時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":3},{"front":"children’s fitness","meaning":"兒童體能","examples":[{"en":"The research project studied children’s fitness.","zh":"研究項目研究兒童體能。"},{"en":"Children’s fitness means children’s physical health, strength, stamina, and ability to be active.","zh":"children’s fitness 指兒童的身體健康、力量、耐力和活動能力。"},{"en":"PE teachers may test children’s fitness through running, jumping, and flexibility exercises.","zh":"體育老師可能透過跑步、跳躍和柔軟度練習測試兒童體能。"},{"en":"Better fitness can help children feel energetic and reduce future health risks.","zh":"較好體能可以幫助兒童感到有活力並減少未來健康風險。"},{"en":"This phrase is useful when discussing exercise and child health.","zh":"討論運動和兒童健康時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":3},{"front":"the results were alarming","meaning":"結果令人憂慮","examples":[{"en":"The results of the research project were alarming.","zh":"研究項目的結果令人憂慮。"},{"en":"The results were alarming means the findings were worrying or frightening.","zh":"results were alarming 指研究結果令人擔心或害怕。"},{"en":"If a school survey shows many children sleep only five hours, the results are alarming.","zh":"如果學校調查顯示許多孩子只睡五小時，結果就令人憂慮。"},{"en":"Alarming results often push experts to call for action.","zh":"令人憂慮的結果常促使專家呼籲行動。"},{"en":"This phrase is useful when research reveals a serious problem.","zh":"當研究揭示嚴重問題時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":3},{"front":"published in","meaning":"發表於","examples":[{"en":"The results were published in 1990.","zh":"結果發表於1990年。"},{"en":"Published in means made publicly available in a particular year, book, journal, or place.","zh":"published in 指在某一年、書籍、期刊或地方公開發表。"},{"en":"A scientific article may be published in a medical journal.","zh":"科學文章可能發表於醫學期刊。"},{"en":"Publication allows other people to read, check, and use the findings.","zh":"發表讓其他人閱讀、檢查和使用研究結果。"},{"en":"This phrase is common in academic and factual writing.","zh":"這個短語常見於學術和事實性寫作。"}],"source":"34 - Activities for Children.pdf","sourcePage":3},{"front":"monitored","meaning":"監測","examples":[{"en":"The survey monitored 700 children aged 11 to 16.","zh":"調查監測了700名11至16歲兒童。"},{"en":"Monitored means watched, measured, or recorded over time.","zh":"monitored 指隨時間觀察、測量或記錄。"},{"en":"A doctor may monitor a patient’s heart rate after treatment.","zh":"醫生可能在治療後監測病人的心率。"},{"en":"Monitoring helps researchers notice changes instead of relying on guesses.","zh":"監測幫助研究人員注意變化，而不是依靠猜測。"},{"en":"This word is useful in health, research, and safety contexts.","zh":"這個詞適用於健康、研究和安全語境。"}],"source":"34 - Activities for Children.pdf","sourcePage":3},{"front":"exceeded safe cholesterol levels","meaning":"超出安全膽固醇水平","examples":[{"en":"Many children exceeded safe cholesterol levels.","zh":"許多兒童超出安全膽固醇水平。"},{"en":"Exceeded safe cholesterol levels means had cholesterol readings higher than the recommended safe limit.","zh":"exceeded safe cholesterol levels 指膽固醇讀數高於建議安全上限。"},{"en":"A health check may show that an adult has exceeded safe cholesterol levels after years of poor diet.","zh":"健康檢查可能顯示成年人多年不良飲食後超出安全膽固醇水平。"},{"en":"High cholesterol can increase concern about future heart health.","zh":"高膽固醇可以增加對未來心臟健康的憂慮。"},{"en":"This phrase is useful when discussing medical risk levels.","zh":"討論醫療風險水平時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":3},{"front":"safe cholesterol levels","meaning":"安全膽固醇水平","examples":[{"en":"The American Heart Foundation set safe cholesterol levels for children.","zh":"美國心臟基金會為兒童訂定安全膽固醇水平。"},{"en":"Safe cholesterol levels are cholesterol amounts considered low enough not to create unnecessary health risk.","zh":"safe cholesterol levels 指被視為夠低、不會造成不必要健康風險的膽固醇水平。"},{"en":"A doctor may compare a child’s blood test with safe cholesterol levels.","zh":"醫生可能把兒童血液測試與安全膽固醇水平比較。"},{"en":"If levels are above the safe range, diet and exercise may need attention.","zh":"如果水平高於安全範圍，飲食和運動可能需要關注。"},{"en":"This phrase is common in health and medical screening.","zh":"這個短語常見於健康和醫療篩查。"}],"source":"34 - Activities for Children.pdf","sourcePage":3},{"front":"set for children by","meaning":"由……為兒童訂定","examples":[{"en":"Safe cholesterol levels were set for children by the American Heart Foundation.","zh":"安全膽固醇水平由美國心臟基金會為兒童訂定。"},{"en":"Set for children by means officially decided for children by a particular organisation or expert group.","zh":"set for children by 指由某機構或專家團體正式為兒童決定。"},{"en":"Reading targets may be set for students by the school.","zh":"閱讀目標可能由學校為學生訂定。"},{"en":"Standards set by experts help people judge whether results are safe or acceptable.","zh":"由專家訂定的標準幫助人們判斷結果是否安全或可接受。"},{"en":"This phrase is useful when describing who created a standard.","zh":"描述標準由誰制定時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":3},{"front":"American Heart Foundation","meaning":"美國心臟基金會","examples":[{"en":"The American Heart Foundation set safe cholesterol levels for children.","zh":"美國心臟基金會為兒童訂定安全膽固醇水平。"},{"en":"The American Heart Foundation is presented as a health organisation concerned with heart health.","zh":"American Heart Foundation 在文中指關注心臟健康的健康組織。"},{"en":"A heart-health organisation may publish advice about exercise, diet, and cholesterol.","zh":"心臟健康組織可能發布關於運動、飲食和膽固醇的建議。"},{"en":"Such organisations help the public understand risks linked to heart disease.","zh":"這類組織幫助公眾理解與心臟病相關的風險。"},{"en":"This phrase names the organisation used as the source of the cholesterol standard.","zh":"這個短語指出文中用作膽固醇標準來源的組織。"}],"source":"34 - Activities for Children.pdf","sourcePage":3},{"front":"the heart is a muscle","meaning":"心臟是一塊肌肉","examples":[{"en":"Professor Armstrong says the heart is a muscle.","zh":"Armstrong 教授說心臟是一塊肌肉。"},{"en":"The heart is a muscle means the heart is made of muscle tissue and needs activity to stay strong.","zh":"the heart is a muscle 指心臟由肌肉組織構成，需要活動保持強壯。"},{"en":"A PE teacher may explain that the heart is a muscle to encourage regular exercise.","zh":"體育老師可能解釋心臟是一塊肌肉，以鼓勵定期運動。"},{"en":"Like other muscles, the heart can become stronger when it is used properly.","zh":"像其他肌肉一樣，心臟在適當使用時可以變得更強。"},{"en":"This phrase helps children understand why movement matters for health.","zh":"這個短語幫助兒童理解為何活動對健康重要。"}],"source":"34 - Activities for Children.pdf","sourcePage":3},{"front":"needs exercise","meaning":"需要運動","examples":[{"en":"The heart needs exercise or it loses strength.","zh":"心臟需要運動，否則會失去力量。"},{"en":"Needs exercise means requires regular physical activity to stay healthy or strong.","zh":"needs exercise 指需要定期體能活動來保持健康或強壯。"},{"en":"A dog needs exercise every day, or it may become restless and overweight.","zh":"狗每天需要運動，否則可能變得焦躁和超重。"},{"en":"Without exercise, muscles can weaken over time.","zh":"沒有運動，肌肉會隨時間變弱。"},{"en":"This phrase is useful when explaining why movement is necessary.","zh":"解釋為何活動是必要時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":3},{"front":"loses its strength","meaning":"失去力量","examples":[{"en":"The heart loses its strength without exercise.","zh":"心臟沒有運動會失去力量。"},{"en":"Loses its strength means becomes weaker or less able to work well.","zh":"loses its strength 指變弱或較不能正常運作。"},{"en":"A person’s leg can lose its strength after weeks in bed.","zh":"一個人臥床數星期後，腿部可能失去力量。"},{"en":"Muscles weaken when they are not used regularly.","zh":"肌肉若沒有定期使用，就會變弱。"},{"en":"This phrase is useful when describing physical decline.","zh":"描述身體能力下降時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":4},{"front":"overweight","meaning":"超重","examples":[{"en":"The survey found that some boys and girls were overweight.","zh":"調查發現有些男孩和女孩超重。"},{"en":"Overweight means having more body weight than is considered healthy for one’s age, height, or body type.","zh":"overweight 指體重高於以年齡、身高或體型來看被視為健康的水平。"},{"en":"A doctor may discuss exercise and diet if a child is overweight.","zh":"如果兒童超重，醫生可能討論運動和飲食。"},{"en":"Being overweight can increase the risk of certain health problems over time.","zh":"超重可以隨時間增加某些健康問題的風險。"},{"en":"This word is common in health and fitness discussions.","zh":"這個詞常見於健康和體能討論。"}],"source":"34 - Activities for Children.pdf","sourcePage":4},{"front":"more disturbingly","meaning":"更令人不安的是","examples":[{"en":"More disturbingly, many children did very little exercise.","zh":"更令人不安的是，許多兒童做很少運動。"},{"en":"More disturbingly means even more worryingly than what was just mentioned.","zh":"more disturbingly 指比剛才提到的事情更加令人擔心。"},{"en":"The school had few sports lessons; more disturbingly, many students had no safe place to play after school.","zh":"學校體育課很少；更令人不安的是，許多學生放學後沒有安全地方玩耍。"},{"en":"This phrase introduces a point that is especially serious or upsetting.","zh":"這個短語引出特別嚴重或令人不安的一點。"},{"en":"It is useful when building from one concern to a bigger concern.","zh":"由一個擔憂引向更大擔憂時，它很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":4},{"front":"over a four-day period","meaning":"在四日期間","examples":[{"en":"The survey measured exercise over a four-day period.","zh":"調查在四日期間測量運動量。"},{"en":"Over a four-day period means during four days.","zh":"over a four-day period 指在四天之內。"},{"en":"A teacher may record students’ reading time over a four-day period.","zh":"老師可能在四日期間記錄學生閱讀時間。"},{"en":"Measuring behaviour across several days gives a clearer picture than one moment alone.","zh":"跨幾天測量行為，比只看一刻更能提供清楚圖像。"},{"en":"This phrase is useful when describing the time span of a study.","zh":"描述研究時間跨度時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":4},{"front":"the equivalent of","meaning":"相等於……的量","examples":[{"en":"Some children did less exercise than the equivalent of a brisk walk.","zh":"有些兒童做的運動少於相等於急步行的量。"},{"en":"The equivalent of something means the same amount, value, or effect as it.","zh":"equivalent of something 指與某物相同的數量、價值或效果。"},{"en":"Ten minutes of climbing stairs may be the equivalent of a short workout for some people.","zh":"對有些人來說，十分鐘爬樓梯可能相等於一次短運動。"},{"en":"Equivalents help readers understand numbers through familiar examples.","zh":"等量比較幫助讀者透過熟悉例子理解數字。"},{"en":"This phrase is useful when comparing amounts or effects.","zh":"比較數量或效果時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":4},{"front":"brisk 10-minute walk","meaning":"十分鐘急步行","examples":[{"en":"Some children did less exercise than a brisk 10-minute walk.","zh":"有些兒童做的運動少於十分鐘急步行。"},{"en":"A brisk 10-minute walk is a short walk done at a quick, energetic pace.","zh":"brisk 10-minute walk 指以快速而有活力的步速走十分鐘。"},{"en":"Walking quickly from home to the bus stop may be a brisk 10-minute walk.","zh":"從家快速走到巴士站可能是十分鐘急步行。"},{"en":"Even a brief brisk walk can raise the heart rate more than sitting still.","zh":"即使短暫急步行，也比靜坐更能提高心率。"},{"en":"This phrase gives a simple example of light physical activity.","zh":"這個短語提供輕量體能活動的簡單例子。"}],"source":"34 - Activities for Children.pdf","sourcePage":4},{"front":"high levels of cholesterol","meaning":"高膽固醇水平","examples":[{"en":"High levels of cholesterol may increase heart-disease risk.","zh":"高膽固醇水平可能增加心臟病風險。"},{"en":"High levels of cholesterol means too much cholesterol in the blood.","zh":"high levels of cholesterol 指血液中膽固醇過多。"},{"en":"A doctor may advise healthier eating if blood tests show high levels of cholesterol.","zh":"如果血液測試顯示高膽固醇，醫生可能建議更健康飲食。"},{"en":"High cholesterol can put extra strain on the heart and blood vessels over time.","zh":"高膽固醇會隨時間對心臟和血管造成額外負擔。"},{"en":"This phrase is common in health and medical screening.","zh":"這個短語常見於健康和醫療篩查。"}],"source":"34 - Activities for Children.pdf","sourcePage":4},{"front":"excess body fat","meaning":"過量體脂","examples":[{"en":"Excess body fat is linked to health risks.","zh":"過量體脂與健康風險有關。"},{"en":"Excess body fat means more fat stored in the body than is healthy.","zh":"excess body fat 指身體儲存超過健康水平的脂肪。"},{"en":"A child may gain excess body fat if diet is poor and activity is very low.","zh":"如果飲食差且活動量很低，兒童可能增加過量體脂。"},{"en":"Too much body fat can increase pressure on the heart, joints, and metabolism.","zh":"過多體脂可以增加心臟、關節和新陳代謝負擔。"},{"en":"This phrase is used when discussing weight and health.","zh":"討論體重和健康時，會使用這個短語。"}],"source":"34 - Activities for Children.pdf","sourcePage":4},{"front":"inactivity","meaning":"缺乏活動","examples":[{"en":"Inactivity is believed to increase the risk of heart disease.","zh":"缺乏活動被認為會增加心臟病風險。"},{"en":"Inactivity means doing too little physical movement or exercise.","zh":"inactivity 指身體活動或運動太少。"},{"en":"Sitting at a desk all day with no walking can lead to inactivity.","zh":"整天坐在書桌前而沒有步行，可能導致缺乏活動。"},{"en":"Inactivity can weaken fitness and make weight management harder.","zh":"缺乏活動可以削弱體能並令體重管理更困難。"},{"en":"This word is useful when discussing sedentary lifestyles.","zh":"討論久坐生活方式時，這個詞很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":4},{"front":"increase the risk of","meaning":"增加……的風險","examples":[{"en":"Inactivity can increase the risk of coronary heart disease.","zh":"缺乏活動可以增加冠心病風險。"},{"en":"To increase the risk of something means to make it more likely to happen.","zh":"increase the risk of something 指令某事更有可能發生。"},{"en":"Poor sleep can increase the risk of mistakes during exams.","zh":"睡眠不足可以增加考試中犯錯的風險。"},{"en":"Risk increases when unhealthy habits are repeated over time.","zh":"當不健康習慣反覆出現，風險會增加。"},{"en":"This phrase is common in health and safety writing.","zh":"這個短語常見於健康和安全寫作。"}],"source":"34 - Activities for Children.pdf","sourcePage":4},{"front":"coronary heart disease","meaning":"冠心病","examples":[{"en":"High cholesterol and inactivity may increase the risk of coronary heart disease.","zh":"高膽固醇和缺乏活動可能增加冠心病風險。"},{"en":"Coronary heart disease is a heart condition linked to problems in the blood vessels that supply the heart.","zh":"coronary heart disease 指與供應心臟的血管問題有關的心臟疾病。"},{"en":"Doctors may warn patients about coronary heart disease if they have high cholesterol and little exercise.","zh":"如果病人膽固醇高又少運動，醫生可能提醒他們注意冠心病。"},{"en":"Healthy habits can reduce some risk factors connected with heart disease.","zh":"健康習慣可以降低與心臟病相關的部分風險因素。"},{"en":"This phrase is a formal medical term.","zh":"這個短語是正式醫學術語。"}],"source":"34 - Activities for Children.pdf","sourcePage":4},{"front":"physical education","meaning":"體育教育","examples":[{"en":"Physical education is under pressure in the UK.","zh":"英國的體育教育正承受壓力。"},{"en":"Physical education is the school subject that teaches sport, exercise, movement, and fitness.","zh":"physical education 指教授運動、鍛煉、活動和體能的學校科目。"},{"en":"Students may learn football, swimming, gymnastics, or running in physical education.","zh":"學生可能在體育教育中學足球、游泳、體操或跑步。"},{"en":"PE helps children build fitness, coordination, teamwork, and confidence.","zh":"體育幫助兒童建立體能、協調、團隊合作和信心。"},{"en":"This phrase is often shortened to PE.","zh":"這個短語常縮寫為 PE。"}],"source":"34 - Activities for Children.pdf","sourcePage":5},{"front":"under pressure","meaning":"承受壓力","examples":[{"en":"Physical education is under pressure in many UK schools.","zh":"許多英國學校的體育教育正承受壓力。"},{"en":"Under pressure means facing stress, difficulty, or demands that make something harder to continue.","zh":"under pressure 指面對壓力、困難或要求，使某事更難維持。"},{"en":"Teachers may feel under pressure when the timetable is crowded and exams are near.","zh":"當時間表擠迫且考試臨近，老師可能感到承受壓力。"},{"en":"When a subject is under pressure, it may lose time, money, or attention.","zh":"當一個科目承受壓力，它可能失去時間、資金或關注。"},{"en":"This phrase is useful when describing strain on people or systems.","zh":"描述人或制度受壓時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":5},{"front":"devote little more than","meaning":"只投放略多於……","examples":[{"en":"Most schools devote little more than 100 minutes a week to PE.","zh":"大多數學校每週只投放略多於100分鐘於體育課。"},{"en":"Devote little more than means give only slightly more than a stated amount.","zh":"devote little more than 指只給予比某指定數量稍多一點。"},{"en":"A busy student may devote little more than ten minutes a day to reading.","zh":"忙碌學生每天可能只投放略多於十分鐘於閱讀。"},{"en":"If schools devote little time to PE, children may have fewer chances to exercise.","zh":"如果學校投放很少時間於體育，兒童運動機會可能較少。"},{"en":"This phrase often suggests the amount is too small.","zh":"這個短語常暗示數量太少。"}],"source":"34 - Activities for Children.pdf","sourcePage":5},{"front":"curriculum time","meaning":"課程時間","examples":[{"en":"Schools devote limited curriculum time to physical education.","zh":"學校投放有限課程時間於體育教育。"},{"en":"Curriculum time is the amount of school timetable time given to a subject.","zh":"curriculum time 指學校時間表分配給某科目的時間。"},{"en":"A school may increase curriculum time for English before public exams.","zh":"學校可能在公開考試前增加英文課程時間。"},{"en":"When curriculum time is limited, subjects must compete for space in the timetable.","zh":"當課程時間有限，各科必須爭奪時間表空間。"},{"en":"This phrase is useful in education policy and school planning.","zh":"這個短語適用於教育政策和學校規劃。"}],"source":"34 - Activities for Children.pdf","sourcePage":5},{"front":"a head start in","meaning":"在……方面有優勢","examples":[{"en":"Some European countries give children a head start in PE.","zh":"一些歐洲國家讓兒童在體育方面有優勢。"},{"en":"A head start in something means an early advantage that helps someone do better later.","zh":"head start in something 指早期優勢，有助某人日後表現更好。"},{"en":"Children who read at home may get a head start in vocabulary before school begins.","zh":"在家閱讀的孩子可能在入學前已在詞彙方面有優勢。"},{"en":"More PE time can give children a head start in fitness and healthy habits.","zh":"更多體育課時間可以讓兒童在體能和健康習慣方面有優勢。"},{"en":"This phrase is useful when discussing early advantages.","zh":"討論早期優勢時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":5},{"front":"primary and secondary schools","meaning":"小學及中學","examples":[{"en":"Some countries offer at least two hours of PE in primary and secondary schools.","zh":"一些國家在小學及中學提供至少兩小時體育課。"},{"en":"Primary and secondary schools are schools for younger children and older school-age students.","zh":"primary and secondary schools 指小學和中學階段的學校。"},{"en":"A country may introduce a health programme in both primary and secondary schools.","zh":"國家可能在小學及中學推行健康計劃。"},{"en":"Starting good exercise habits early and continuing them later can support long-term health.","zh":"早期建立良好運動習慣並在之後延續，可以支持長期健康。"},{"en":"This phrase is common in education systems.","zh":"這個短語常見於教育制度。"}],"source":"34 - Activities for Children.pdf","sourcePage":5},{"front":"findings from","meaning":"來自……的研究結果","examples":[{"en":"The findings from the European Union of Physical Education Associations prompted specialists to act.","zh":"來自歐洲體育教育協會聯盟的研究結果促使專家行動。"},{"en":"Findings from something are results or conclusions that come from a study, survey, or organisation.","zh":"findings from something 指來自研究、調查或機構的結果或結論。"},{"en":"Findings from a school survey may show that students want more outdoor activities.","zh":"學校調查結果可能顯示學生想要更多戶外活動。"},{"en":"Research findings can lead experts to recommend changes.","zh":"研究結果可以促使專家建議改變。"},{"en":"This phrase is common in reports and academic writing.","zh":"這個短語常見於報告和學術寫作。"}],"source":"34 - Activities for Children.pdf","sourcePage":5},{"front":"European Union of Physical Education Associations","meaning":"歐洲體育教育協會聯盟","examples":[{"en":"The European Union of Physical Education Associations compared PE time across countries.","zh":"歐洲體育教育協會聯盟比較了各國體育課時間。"},{"en":"The European Union of Physical Education Associations is presented as an organisation connected with PE across Europe.","zh":"European Union of Physical Education Associations 在文中指與歐洲體育教育相關的組織。"},{"en":"Such an organisation may collect data about how schools teach sport and exercise.","zh":"這類組織可能收集學校如何教授運動和鍛煉的數據。"},{"en":"Comparing countries helps experts see where PE provision is stronger or weaker.","zh":"比較不同國家幫助專家看出體育教育供應哪裏較強或較弱。"},{"en":"This phrase names the organisation behind the findings.","zh":"這個短語指出研究結果背後的組織。"}],"source":"34 - Activities for Children.pdf","sourcePage":5},{"front":"prompted specialists to","meaning":"促使專家去……","examples":[{"en":"The findings prompted specialists to call for daily PE.","zh":"研究結果促使專家呼籲每日體育課。"},{"en":"Prompted specialists to do something means made experts decide to take action or speak out.","zh":"prompted specialists to do something 指令專家決定採取行動或公開發聲。"},{"en":"Rising obesity figures may prompt doctors to recommend more school exercise.","zh":"肥胖數字上升可能促使醫生建議更多學校運動。"},{"en":"Strong evidence often prompts specialists to ask governments to change policy.","zh":"強而有力的證據常促使專家要求政府改變政策。"},{"en":"This phrase is useful when research causes expert response.","zh":"當研究引起專家回應時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":5},{"front":"children’s physiology","meaning":"兒童生理學","examples":[{"en":"Specialists in children’s physiology called for more physical education.","zh":"兒童生理學專家呼籲增加體育教育。"},{"en":"Children’s physiology is the study of how children’s bodies work and develop.","zh":"children’s physiology 指研究兒童身體如何運作和發展的學科。"},{"en":"A doctor studying children’s physiology may examine growth, hormones, heart health, and exercise.","zh":"研究兒童生理學的醫生可能檢視成長、荷爾蒙、心臟健康和運動。"},{"en":"Understanding children’s bodies helps adults design safe and useful activities.","zh":"理解兒童身體有助成人設計安全而有用的活動。"},{"en":"This phrase is formal and scientific.","zh":"這個短語較正式，屬於科學用語。"}],"source":"34 - Activities for Children.pdf","sourcePage":5},{"front":"call on governments to","meaning":"呼籲政府去……","examples":[{"en":"Specialists called on European governments to provide daily PE.","zh":"專家呼籲歐洲政府提供每日體育課。"},{"en":"To call on governments to do something means to publicly urge them to take action.","zh":"call on governments to do something 指公開敦促政府採取行動。"},{"en":"Doctors may call on governments to reduce sugar in school meals.","zh":"醫生可能呼籲政府減少學校餐膳中的糖分。"},{"en":"Public calls can pressure leaders to change laws, funding, or services.","zh":"公開呼籲可以向領導者施壓，促使改變法律、資金或服務。"},{"en":"This phrase is common in policy and advocacy.","zh":"這個短語常見於政策和倡議。"}],"source":"34 - Activities for Children.pdf","sourcePage":5},{"front":"youngsters","meaning":"年輕人；兒童","examples":[{"en":"Specialists wanted youngsters to have a daily PE programme.","zh":"專家希望年輕人有每日體育課程。"},{"en":"Youngsters means children or young people.","zh":"youngsters 指兒童或年輕人。"},{"en":"A community centre may organise summer sports for youngsters.","zh":"社區中心可能為兒童安排暑期運動。"},{"en":"Youngsters need safe spaces to move, play, and build confidence.","zh":"年輕人需要安全空間去活動、玩耍和建立信心。"},{"en":"This word is slightly informal and often used by adults.","zh":"這個詞稍微口語，常由成人使用。"}],"source":"34 - Activities for Children.pdf","sourcePage":6},{"front":"daily PE programme","meaning":"每日體育課程","examples":[{"en":"Experts called for a daily PE programme for youngsters.","zh":"專家呼籲為年輕人提供每日體育課程。"},{"en":"A daily PE programme is a physical education plan that happens every school day.","zh":"daily PE programme 指每個上課日進行的體育教育計劃。"},{"en":"A daily PE programme may include running, games, stretching, and team activities.","zh":"每日體育課程可能包括跑步、遊戲、伸展和團隊活動。"},{"en":"Daily exercise can help children build regular movement habits.","zh":"每日運動可以幫助兒童建立定期活動習慣。"},{"en":"This phrase is useful in school health policy.","zh":"這個短語適用於學校健康政策。"}],"source":"34 - Activities for Children.pdf","sourcePage":6},{"front":"ranks 13th out of","meaning":"在……中排名第十三","examples":[{"en":"The UK ranks 13th out of the 25 countries.","zh":"英國在25個國家中排名第十三。"},{"en":"Ranks 13th out of means is placed number 13 in a list of 25.","zh":"ranks 13th out of 指在25個之中排第13位。"},{"en":"A school may rank third out of twenty schools in a sports competition.","zh":"學校可能在二十間學校的運動比賽中排名第三。"},{"en":"Ranking helps compare performance across groups.","zh":"排名有助比較不同群體的表現。"},{"en":"This phrase is useful when reporting survey or competition results.","zh":"報告調查或比賽結果時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":6},{"front":"averaging under an hour a week","meaning":"平均每週少於一小時","examples":[{"en":"Ireland was bottom, averaging under an hour a week for PE.","zh":"愛爾蘭排最尾，體育課平均每週少於一小時。"},{"en":"Averaging under an hour a week means having less than one hour per week on average.","zh":"averaging under an hour a week 指平均每週少於一小時。"},{"en":"A student averaging under an hour a week of reading may struggle to build vocabulary.","zh":"每週平均閱讀少於一小時的學生可能難以建立詞彙。"},{"en":"Low weekly averages can show that an activity is not being given enough time.","zh":"低每週平均值可以顯示某活動未獲足夠時間。"},{"en":"This phrase is useful when describing average time.","zh":"描述平均時間時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":6},{"front":"received on average","meaning":"平均獲得","examples":[{"en":"British children received, on average, 106 minutes of PE a week.","zh":"英國兒童平均每週獲得106分鐘體育課。"},{"en":"Received on average means got a typical amount calculated across a group.","zh":"received on average 指按整體計算得到典型數量。"},{"en":"Students in one class may receive, on average, two hours of homework a week.","zh":"某班學生可能平均每週獲得兩小時功課。"},{"en":"Averages help compare groups, but they may hide differences between individuals.","zh":"平均數有助比較群體，但可能隱藏個體差異。"},{"en":"This phrase is useful when reporting statistics.","zh":"報告統計數據時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":6},{"front":"presented the findings","meaning":"發表研究結果","examples":[{"en":"Professor Armstrong presented the findings at the meeting.","zh":"Armstrong 教授在會議上發表研究結果。"},{"en":"Presented the findings means formally shared the results of research.","zh":"presented the findings 指正式分享研究結果。"},{"en":"A student may present the findings of a survey to the class.","zh":"學生可能向全班發表調查結果。"},{"en":"Presenting findings allows others to discuss, question, and use the results.","zh":"發表結果讓其他人討論、提問和使用研究結果。"},{"en":"This phrase is common in academic and professional settings.","zh":"這個短語常見於學術和專業場合。"}],"source":"34 - Activities for Children.pdf","sourcePage":6},{"front":"national curriculum","meaning":"國家課程","examples":[{"en":"The introduction of the national curriculum reduced PE time.","zh":"國家課程的引入減少了體育課時間。"},{"en":"A national curriculum is an official set of subjects and learning requirements for schools in a country.","zh":"national curriculum 指一個國家為學校訂定的官方科目和學習要求。"},{"en":"Teachers follow the national curriculum when planning what students must learn each year.","zh":"老師每年規劃學生必須學習的內容時，會跟從國家課程。"},{"en":"If the curriculum becomes crowded, some subjects may lose time.","zh":"如果課程變得擠迫，有些科目可能失去時間。"},{"en":"This phrase is common in education policy.","zh":"這個短語常見於教育政策。"}],"source":"34 - Activities for Children.pdf","sourcePage":6},{"front":"marked fall in","meaning":"明顯下降","examples":[{"en":"There had been a marked fall in the time devoted to PE.","zh":"投放於體育課的時間有明顯下降。"},{"en":"A marked fall in something is a clear and noticeable decrease.","zh":"marked fall in something 指清楚而明顯的下降。"},{"en":"A school may see a marked fall in attendance during heavy flu season.","zh":"在嚴重流感季節，學校出席率可能明顯下降。"},{"en":"A marked fall often signals that a problem needs attention.","zh":"明顯下降常顯示問題需要關注。"},{"en":"This phrase is useful when describing a significant decline.","zh":"描述顯著下跌時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":6},{"front":"time devoted to","meaning":"投放於……的時間","examples":[{"en":"There was a fall in the time devoted to PE in UK schools.","zh":"英國學校投放於體育課的時間有所下降。"},{"en":"Time devoted to something is the amount of time given to it.","zh":"time devoted to something 指分配給某事的時間。"},{"en":"A student may increase the time devoted to reading before an English exam.","zh":"學生可能在英文考試前增加投放於閱讀的時間。"},{"en":"If little time is devoted to a skill, progress may be slower.","zh":"如果投放於某技能的時間很少，進步可能較慢。"},{"en":"This phrase is useful when discussing priorities and schedules.","zh":"討論優先次序和時間安排時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":6},{"front":"a minority of pupils","meaning":"少數學生","examples":[{"en":"Only a minority of pupils got two hours of PE a week.","zh":"只有少數學生每週得到兩小時體育課。"},{"en":"A minority of pupils means less than half of the students.","zh":"minority of pupils 指少於一半的學生。"},{"en":"A minority of pupils may join the school swimming team.","zh":"少數學生可能加入學校游泳隊。"},{"en":"If only a minority receive enough PE, most children may miss important exercise opportunities.","zh":"如果只有少數學生得到足夠體育課，大多數兒童可能錯過重要運動機會。"},{"en":"This phrase is useful when comparing smaller and larger groups.","zh":"比較較小和較大群體時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":6},{"front":"former junior football international","meaning":"前青年足球國腳","examples":[{"en":"Professor Armstrong is a former junior football international.","zh":"Armstrong 教授是前青年足球國腳。"},{"en":"A former junior football international is someone who once played football for a national youth team.","zh":"former junior football international 指曾代表國家青年隊踢足球的人。"},{"en":"A former youth athlete may understand how sport builds discipline and teamwork.","zh":"前青年運動員可能理解運動如何建立紀律和團隊合作。"},{"en":"Armstrong’s sporting background helps explain why he cares strongly about children’s exercise.","zh":"Armstrong 的運動背景有助解釋他為何強烈關注兒童運動。"},{"en":"This phrase gives personal background and credibility.","zh":"這個短語提供個人背景和可信度。"}],"source":"34 - Activities for Children.pdf","sourcePage":6},{"front":"passionate advocate for","meaning":"……的熱心倡議者","examples":[{"en":"Professor Armstrong is a passionate advocate for sport.","zh":"Armstrong 教授是體育的熱心倡議者。"},{"en":"A passionate advocate for something is someone who strongly supports and argues for it.","zh":"passionate advocate for something 指強烈支持並為某事發聲的人。"},{"en":"A teacher may be a passionate advocate for reading if she believes books change lives.","zh":"如果老師相信書能改變人生，她可能是閱讀的熱心倡議者。"},{"en":"Passionate advocates can influence public discussion and policy.","zh":"熱心倡議者可以影響公共討論和政策。"},{"en":"This phrase is useful when describing strong support.","zh":"描述強烈支持時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":7},{"front":"poured millions into","meaning":"投入數以百萬計資金於……","examples":[{"en":"The Government has poured millions into sport in the community.","zh":"政府已投入數以百萬計資金於社區體育。"},{"en":"Poured millions into something means spent millions of pounds or dollars on it.","zh":"poured millions into something 指在某事上花費數以百萬計的金錢。"},{"en":"A city may pour millions into a new railway system.","zh":"城市可能投入數以百萬計資金於新鐵路系統。"},{"en":"Large spending can improve facilities, but it does not always solve the whole problem.","zh":"大量開支可以改善設施，但不一定解決整個問題。"},{"en":"This phrase suggests heavy investment.","zh":"這個短語暗示大量投資。"}],"source":"34 - Activities for Children.pdf","sourcePage":7},{"front":"beefing up","meaning":"加強","examples":[{"en":"The Government has spent money beefing up sport in the community.","zh":"政府花錢加強社區體育。"},{"en":"Beefing up means strengthening, increasing, or improving something.","zh":"beefing up 指加強、增加或改善某事。"},{"en":"A school may beef up security after parents raise safety concerns.","zh":"家長提出安全憂慮後，學校可能加強保安。"},{"en":"Beefing up community sport can create more places for children to be active.","zh":"加強社區體育可以創造更多地方讓兒童活動。"},{"en":"This phrase is informal and often used in news or policy discussion.","zh":"這個短語較口語，常用於新聞或政策討論。"}],"source":"34 - Activities for Children.pdf","sourcePage":7},{"front":"sport in the community","meaning":"社區體育","examples":[{"en":"The Government has invested in sport in the community.","zh":"政府已投資於社區體育。"},{"en":"Sport in the community means sports activities and facilities available to local residents outside elite competition.","zh":"sport in the community 指本地居民可參與的運動活動和設施，而非精英比賽。"},{"en":"Community sport may include local football clubs, swimming lessons, and weekend running groups.","zh":"社區體育可能包括本地足球會、游泳課和週末跑步小組。"},{"en":"Strong community sport can help children and adults stay active near home.","zh":"強大的社區體育可以幫助兒童和成人在家附近保持活躍。"},{"en":"This phrase is useful when discussing public health and local services.","zh":"討論公共健康和本地服務時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":7},{"front":"less commitment to","meaning":"對……投入較少","examples":[{"en":"There is less commitment to sport as part of the school curriculum.","zh":"學校課程中對體育的投入較少。"},{"en":"Less commitment to something means weaker support, effort, or priority given to it.","zh":"less commitment to something 指對某事的支持、努力或優先程度較弱。"},{"en":"A company shows less commitment to training if it cuts all staff workshops.","zh":"如果公司取消所有員工工作坊，就是對培訓投入較少。"},{"en":"Less commitment can lead to fewer resources and weaker results.","zh":"較少投入可以導致資源減少和成果較弱。"},{"en":"This phrase is useful when discussing priorities.","zh":"討論優先次序時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":7},{"front":"crammed school curriculum","meaning":"擠迫的學校課程","examples":[{"en":"Sport competes for space in the crammed school curriculum.","zh":"體育在擠迫的學校課程中爭奪空間。"},{"en":"A crammed school curriculum is a timetable or course plan filled with too many subjects or requirements.","zh":"crammed school curriculum 指充滿太多科目或要求的時間表或課程計劃。"},{"en":"Teachers may feel rushed when the curriculum is crammed with exam topics.","zh":"當課程擠滿考試題目，老師可能感到趕急。"},{"en":"A crowded curriculum can push practical subjects like PE to the side.","zh":"擁擠課程可以把體育等實用科目推到旁邊。"},{"en":"This phrase is useful when discussing pressure in education.","zh":"討論教育壓力時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":7},{"front":"acquire the necessary skills","meaning":"掌握必要技能","examples":[{"en":"Many children never acquire the necessary skills for team games.","zh":"許多兒童從未掌握團隊運動所需的必要技能。"},{"en":"To acquire the necessary skills means to learn the abilities needed to do something well.","zh":"acquire the necessary skills 指學會做好某事所需的能力。"},{"en":"A student must acquire the necessary skills before joining an advanced debate team.","zh":"學生加入高階辯論隊前，必須掌握必要技能。"},{"en":"Without basic skills, children may feel embarrassed and avoid sport.","zh":"沒有基本技能，兒童可能感到尷尬並避開運動。"},{"en":"This phrase is useful when discussing learning and readiness.","zh":"討論學習和準備程度時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":7},{"front":"thrive in team games","meaning":"在團隊運動中表現良好","examples":[{"en":"Children need skills to thrive in team games.","zh":"兒童需要技能，才能在團隊運動中表現良好。"},{"en":"To thrive in team games means to do well and enjoy success in sports played with others.","zh":"thrive in team games 指在與他人一起進行的運動中表現好並享受成功。"},{"en":"A child who can pass, communicate, and cooperate may thrive in team games.","zh":"能傳球、溝通和合作的孩子可能在團隊運動中表現良好。"},{"en":"If children lack these skills, team games may feel stressful rather than fun.","zh":"如果兒童缺乏這些技能，團隊運動可能變得有壓力而非有趣。"},{"en":"This phrase is useful when discussing confidence and sport participation.","zh":"討論信心和運動參與時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":7},{"front":"lose interest","meaning":"失去興趣","examples":[{"en":"Children may lose interest if they are not good at team games.","zh":"如果兒童不擅長團隊運動，他們可能失去興趣。"},{"en":"To lose interest means to stop caring about or wanting to continue something.","zh":"lose interest 指不再關心或不再想繼續某事。"},{"en":"A student may lose interest in reading if every book feels too difficult.","zh":"如果每本書都太難，學生可能對閱讀失去興趣。"},{"en":"Losing interest can lead children to stop trying and become less active.","zh":"失去興趣可以令兒童停止嘗試並變得較不活躍。"},{"en":"This phrase is useful when explaining why participation drops.","zh":"解釋參與度下降時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":7},{"front":"establish an inactive pattern of behaviour","meaning":"形成不活躍的行為模式","examples":[{"en":"Children may establish an inactive pattern of behaviour.","zh":"兒童可能形成不活躍的行為模式。"},{"en":"To establish an inactive pattern of behaviour means to develop a regular habit of doing little physical activity.","zh":"establish an inactive pattern of behaviour 指形成經常缺乏體能活動的習慣。"},{"en":"A child who always chooses screens over outdoor play may establish an inactive pattern.","zh":"總是選擇螢幕而不是戶外玩耍的孩子，可能形成不活躍模式。"},{"en":"Early inactive habits can continue into teenage years and adulthood.","zh":"早期不活躍習慣可以延續到青少年期和成年期。"},{"en":"This phrase is useful when discussing long-term lifestyle habits.","zh":"討論長期生活習慣時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":7},{"front":"coupled with","meaning":"加上；與……結合","examples":[{"en":"Inactivity coupled with a poor diet can lead to weight gain.","zh":"缺乏活動加上不良飲食可以導致體重增加。"},{"en":"Coupled with means combined with or together with.","zh":"coupled with 指與某物結合或加上某物。"},{"en":"Stress coupled with little sleep can make students feel exhausted.","zh":"壓力加上睡眠不足可以令學生感到筋疲力盡。"},{"en":"Two problems together can create a stronger effect than either one alone.","zh":"兩個問題結合，可以比單一問題造成更強影響。"},{"en":"This phrase is useful when explaining combined causes.","zh":"解釋複合原因時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":7},{"front":"poor diet","meaning":"不良飲食","examples":[{"en":"An inactive lifestyle and a poor diet can cause weight gain.","zh":"不活躍生活方式和不良飲食可以造成體重增加。"},{"en":"A poor diet is an unhealthy eating pattern with too much sugar, fat, or processed food and too few nutrients.","zh":"poor diet 指不健康的飲食模式，含太多糖、脂肪或加工食品，而營養太少。"},{"en":"A child who often eats crisps and sugary drinks may have a poor diet.","zh":"經常吃薯片和含糖飲品的孩子可能有不良飲食。"},{"en":"Poor diet can reduce energy and increase long-term health risks.","zh":"不良飲食可以降低精力並增加長期健康風險。"},{"en":"This phrase is common in health and nutrition discussions.","zh":"這個短語常見於健康和營養討論。"}],"source":"34 - Activities for Children.pdf","sourcePage":8},{"front":"lead inevitably to","meaning":"不可避免地導致","examples":[{"en":"A poor diet and inactivity will lead inevitably to weight gain.","zh":"不良飲食和缺乏活動將不可避免地導致體重增加。"},{"en":"Lead inevitably to means cause a result that is very difficult or impossible to avoid.","zh":"lead inevitably to 指導致一個非常難以或不可能避免的結果。"},{"en":"Ignoring a leaking roof will lead inevitably to more expensive repairs.","zh":"忽視漏水屋頂將不可避免地導致更昂貴維修。"},{"en":"When causes are repeated for long enough, the result becomes predictable.","zh":"當原因重複足夠長時間，結果就變得可預測。"},{"en":"This phrase is strong and shows an unavoidable consequence.","zh":"這個短語語氣強，顯示不可避免後果。"}],"source":"34 - Activities for Children.pdf","sourcePage":8},{"front":"weight gain","meaning":"體重增加","examples":[{"en":"Inactive behaviour can lead to weight gain.","zh":"不活躍行為可以導致體重增加。"},{"en":"Weight gain means an increase in body weight.","zh":"weight gain 指體重上升。"},{"en":"A person may experience weight gain after months of little movement and high-calorie snacks.","zh":"一個人幾個月少活動又吃高熱量零食後，可能出現體重增加。"},{"en":"Weight gain can affect confidence, fitness, and long-term health.","zh":"體重增加可以影響信心、體能和長期健康。"},{"en":"This phrase is common in health and lifestyle discussion.","zh":"這個短語常見於健康和生活方式討論。"}],"source":"34 - Activities for Children.pdf","sourcePage":8},{"front":"give up all sport","meaning":"放棄所有運動","examples":[{"en":"Many British children give up all sport when they leave school.","zh":"許多英國兒童離校後放棄所有運動。"},{"en":"To give up all sport means to stop participating in every kind of sport.","zh":"give up all sport 指停止參與任何種類的運動。"},{"en":"A teenager may give up all sport if school teams feel too competitive.","zh":"如果校隊感覺競爭太強，青少年可能放棄所有運動。"},{"en":"Giving up sport can reduce regular exercise and social contact.","zh":"放棄運動可以減少定期鍛煉和社交接觸。"},{"en":"This phrase is useful when discussing loss of participation.","zh":"討論參與度流失時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":8},{"front":"compared with","meaning":"與……相比","examples":[{"en":"Seventy per cent of British children give up sport, compared with 20 per cent of French teenagers.","zh":"百分之七十英國兒童放棄運動，與百分之二十法國青少年相比。"},{"en":"Compared with means judged beside another figure, group, or situation.","zh":"compared with 指與另一數字、群體或情況並列判斷。"},{"en":"British children may receive less PE compared with children in some other countries.","zh":"與某些其他國家兒童相比，英國兒童可能接受較少體育課。"},{"en":"Comparison helps readers understand whether a number is high or low.","zh":"比較幫助讀者理解一個數字是高還是低。"},{"en":"This phrase is useful when presenting contrasts.","zh":"呈現對比時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":8},{"front":"French teenagers","meaning":"法國青少年","examples":[{"en":"Only 20 per cent of French teenagers give up sport after school.","zh":"只有百分之二十法國青少年離校後放棄運動。"},{"en":"French teenagers are young people from France, usually aged around 13 to 19.","zh":"French teenagers 指來自法國的年輕人，通常約13至19歲。"},{"en":"Researchers may compare French teenagers with British teenagers to study exercise habits.","zh":"研究人員可能比較法國青少年和英國青少年的運動習慣。"},{"en":"Comparing teenagers from different countries can reveal how school systems affect sport participation.","zh":"比較不同國家的青少年可以揭示學校制度如何影響運動參與。"},{"en":"This phrase is useful when discussing youth in a national context.","zh":"在國家背景中討論青年時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":8},{"front":"far too great an emphasis on","meaning":"過分強調……","examples":[{"en":"Armstrong believes there is far too great an emphasis on team games.","zh":"Armstrong 認為對團隊運動有過分強調。"},{"en":"Far too great an emphasis on something means too much importance is placed on it.","zh":"far too great an emphasis on something 指把太多重要性放在某事上。"},{"en":"A school may put far too great an emphasis on exam scores and ignore confidence.","zh":"學校可能過分強調考試分數，而忽略信心。"},{"en":"Overemphasis on one activity can make students who dislike it feel excluded.","zh":"過分強調單一活動可以令不喜歡它的學生感到被排除。"},{"en":"This phrase is useful when criticising imbalance.","zh":"批評不平衡時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":8},{"front":"team games","meaning":"團隊運動","examples":[{"en":"Schools may place too much emphasis on team games.","zh":"學校可能過分強調團隊運動。"},{"en":"Team games are sports or games played by groups against other groups.","zh":"team games 指由隊伍對隊伍進行的運動或遊戲。"},{"en":"Football, basketball, and volleyball are common team games.","zh":"足球、籃球和排球都是常見團隊運動。"},{"en":"Team games can teach cooperation, but not every child enjoys them or feels skilled at them.","zh":"團隊運動可以教合作，但不是每個孩子都喜歡或擅長。"},{"en":"This phrase is useful when discussing school sport.","zh":"討論學校體育時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":8},{"front":"balance it between","meaning":"在……之間取得平衡","examples":[{"en":"Schools should balance PE time between different kinds of activities.","zh":"學校應在不同類型活動之間平衡體育課時間。"},{"en":"To balance it between things means to divide attention, time, or resources fairly among them.","zh":"balance it between things 指在幾件事之間公平分配注意力、時間或資源。"},{"en":"A student should balance study time between reading, writing, listening, and speaking.","zh":"學生應在閱讀、寫作、聆聽和說話之間平衡學習時間。"},{"en":"Balance prevents one activity from pushing out all the others.","zh":"平衡可以防止一項活動排擠所有其他活動。"},{"en":"This phrase is useful when discussing fair distribution.","zh":"討論公平分配時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":8},{"front":"individual and pair activities","meaning":"個人及雙人活動","examples":[{"en":"PE should include individual and pair activities.","zh":"體育課應包括個人及雙人活動。"},{"en":"Individual and pair activities are exercises done alone or with one partner.","zh":"individual and pair activities 指獨自或與一名夥伴進行的運動。"},{"en":"Running is an individual activity, while badminton doubles can be a pair activity.","zh":"跑步是個人活動，而羽毛球雙打可以是雙人活動。"},{"en":"These activities help children who may not enjoy large team games.","zh":"這些活動幫助未必喜歡大型團隊運動的兒童。"},{"en":"This phrase is useful when widening the idea of sport.","zh":"擴闊運動概念時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":8},{"front":"aerobics","meaning":"帶氧運動","examples":[{"en":"Aerobics can be included as an individual activity.","zh":"帶氧運動可以被包括為個人活動。"},{"en":"Aerobics is exercise that uses rhythmic movement to improve heart and lung fitness.","zh":"aerobics 指透過有節奏動作改善心肺體能的運動。"},{"en":"A class may do aerobics with music to make exercise feel more enjoyable.","zh":"課堂可能配合音樂做帶氧運動，令運動更有趣。"},{"en":"Aerobics can raise the heart rate without needing a competitive team game.","zh":"帶氧運動不需要競爭性團隊運動，也可以提高心率。"},{"en":"This word is common in fitness and PE contexts.","zh":"這個詞常見於健身和體育語境。"}],"source":"34 - Activities for Children.pdf","sourcePage":8},{"front":"badminton","meaning":"羽毛球","examples":[{"en":"Badminton can be included as a pair activity.","zh":"羽毛球可以被包括為雙人活動。"},{"en":"Badminton is a racket sport in which players hit a shuttlecock over a net.","zh":"badminton 指球員用球拍把羽毛球打過網的運動。"},{"en":"Two friends may play badminton after school for exercise and fun.","zh":"兩位朋友可能放學後打羽毛球，既運動又有趣。"},{"en":"Badminton can help children improve coordination, speed, and reaction time.","zh":"羽毛球可以幫助兒童改善協調、速度和反應時間。"},{"en":"This word is useful when giving examples of partner or small-group sports.","zh":"提供雙人或小組運動例子時，這個詞很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":9},{"front":"as well as","meaning":"以及","examples":[{"en":"Children should try individual activities as well as team sports.","zh":"兒童應嘗試個人活動以及團隊運動。"},{"en":"As well as means in addition to.","zh":"as well as 指以及；除了某物之外還有。"},{"en":"A healthy lifestyle needs enough sleep as well as exercise.","zh":"健康生活方式需要足夠睡眠以及運動。"},{"en":"This phrase adds another important item without replacing the first one.","zh":"這個短語加入另一個重要項目，而不是取代第一個。"},{"en":"It is useful when showing that both things matter.","zh":"顯示兩件事都重要時，它很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":9},{"front":"take part in","meaning":"參與","examples":[{"en":"Children need opportunities to take part in many sports.","zh":"兒童需要機會參與許多運動。"},{"en":"To take part in something means to participate in it.","zh":"take part in something 指參與某事。"},{"en":"A shy child may take part in a dance class if friends join too.","zh":"如果朋友也加入，害羞孩子可能參與舞蹈班。"},{"en":"Taking part helps children build skills through real practice.","zh":"參與幫助兒童透過真實練習建立技能。"},{"en":"This phrase is common in school and community activities.","zh":"這個短語常見於學校和社區活動。"}],"source":"34 - Activities for Children.pdf","sourcePage":9},{"front":"wide variety of","meaning":"種類繁多的","examples":[{"en":"Children need to take part in a wide variety of sports.","zh":"兒童需要參與種類繁多的運動。"},{"en":"A wide variety of something means many different types of it.","zh":"wide variety of something 指許多不同種類的某物。"},{"en":"A library with a wide variety of books can interest many kinds of readers.","zh":"有種類繁多書籍的圖書館可以吸引很多類型讀者。"},{"en":"Variety helps children find an activity they enjoy and can continue.","zh":"多樣性幫助兒童找到自己喜歡並能持續的活動。"},{"en":"This phrase is useful when emphasising range and choice.","zh":"強調範圍和選擇時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":9},{"front":"individual, partner and team sports","meaning":"個人、雙人及團隊運動","examples":[{"en":"Children should experience individual, partner and team sports.","zh":"兒童應體驗個人、雙人及團隊運動。"},{"en":"Individual, partner and team sports are activities done alone, with one partner, or in a group.","zh":"individual, partner and team sports 指獨自、與一名夥伴或以團隊進行的活動。"},{"en":"Running, badminton, and football show individual, partner, and team sports.","zh":"跑步、羽毛球和足球分別展示個人、雙人及團隊運動。"},{"en":"Offering all three types gives children more chances to find something suitable.","zh":"提供三種類型讓兒童有更多機會找到合適活動。"},{"en":"This phrase is useful when promoting balanced PE.","zh":"推廣平衡體育課時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":9},{"front":"the good news","meaning":"好消息是","examples":[{"en":"The good news is that some activity groups have responded creatively.","zh":"好消息是，一些活動團體已作出有創意的回應。"},{"en":"The good news is a phrase used to introduce a positive point after problems have been discussed.","zh":"the good news 用來在討論問題後引出正面一點。"},{"en":"The good news is that children can become fitter with small daily changes.","zh":"好消息是，兒童可以透過小小日常改變變得更健康。"},{"en":"Positive news can give readers hope and show that solutions exist.","zh":"正面消息可以給讀者希望，並顯示解決方法存在。"},{"en":"This phrase is useful when shifting from problem to solution.","zh":"從問題轉向解決方案時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":9},{"front":"children’s activity groups","meaning":"兒童活動團體","examples":[{"en":"Children’s activity groups have responded positively and creatively.","zh":"兒童活動團體作出了積極而有創意的回應。"},{"en":"Children’s activity groups are organisations or classes that arrange physical, social, or learning activities for children.","zh":"children’s activity groups 指為兒童安排體能、社交或學習活動的組織或課堂。"},{"en":"A children’s activity group may run dance, swimming, or holiday sports sessions.","zh":"兒童活動團體可能舉辦舞蹈、游泳或假期運動課。"},{"en":"Such groups can help children stay active outside school.","zh":"這些團體可以幫助兒童在校外保持活躍。"},{"en":"This phrase is useful when discussing community support for children.","zh":"討論社區如何支援兒童時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":9},{"front":"responded positively and creatively","meaning":"積極而有創意地回應","examples":[{"en":"Some groups have responded positively and creatively to children’s inactivity.","zh":"一些團體對兒童缺乏活動作出積極而有創意的回應。"},{"en":"Responded positively and creatively means reacted in a helpful, hopeful, and imaginative way.","zh":"responded positively and creatively 指以有幫助、有希望和富想像力的方式回應。"},{"en":"A school may respond positively and creatively to bullying by creating peer-support groups.","zh":"學校可能透過建立同伴支援小組，積極而有創意地回應欺凌問題。"},{"en":"Creative responses can turn a problem into a chance for better activities.","zh":"有創意的回應可以把問題變成改善活動的機會。"},{"en":"This phrase is useful when describing constructive action.","zh":"描述建設性行動時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":9},{"front":"striking a disco pose","meaning":"擺出 disco 舞姿","examples":[{"en":"Gloria Thomas shouted while striking a disco pose.","zh":"Gloria Thomas 一邊大喊，一邊擺出 disco 舞姿。"},{"en":"Striking a disco pose means making a dramatic dance-style body position like someone in a disco.","zh":"striking a disco pose 指擺出像 disco 舞者般誇張的身體姿勢。"},{"en":"A child may laugh while striking a disco pose during a dance game.","zh":"孩子在跳舞遊戲中擺出 disco 舞姿時可能會大笑。"},{"en":"Funny poses can make exercise feel like play rather than training.","zh":"搞笑姿勢可以令運動感覺像遊戲，而不是訓練。"},{"en":"This phrase is vivid and describes playful movement.","zh":"這個短語很生動，描述玩味動作。"}],"source":"34 - Activities for Children.pdf","sourcePage":9},{"front":"astride","meaning":"跨坐在……上","examples":[{"en":"The children adopted poses astride their space hoppers.","zh":"兒童跨坐在彈跳球上擺出姿勢。"},{"en":"Astride means sitting or standing with one leg on each side of something.","zh":"astride 指雙腿分放在某物兩側坐着或站着。"},{"en":"A child may sit astride a bicycle before learning to ride it.","zh":"孩子學踩單車前可能跨坐在單車上。"},{"en":"Sitting astride a bouncing toy helps children balance and move.","zh":"跨坐在彈跳玩具上有助兒童平衡和活動。"},{"en":"This word is useful when describing body position.","zh":"描述身體位置時，這個詞很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":9},{"front":"mini-space hopper","meaning":"小型彈跳球","examples":[{"en":"Gloria Thomas used a mini-space hopper during the activity.","zh":"Gloria Thomas 在活動中使用小型彈跳球。"},{"en":"A mini-space hopper is a small inflatable bouncing toy that children sit on and jump with.","zh":"mini-space hopper 指兒童坐在上面彈跳的小型充氣玩具。"},{"en":"A toddler may use a mini-space hopper in an indoor exercise class.","zh":"幼童可能在室內運動課中使用小型彈跳球。"},{"en":"Bouncing toys can turn exercise into a game for young children.","zh":"彈跳玩具可以把運動變成兒童遊戲。"},{"en":"This phrase names a playful piece of children’s exercise equipment.","zh":"這個短語指一種有趣的兒童運動器材。"}],"source":"34 - Activities for Children.pdf","sourcePage":9},{"front":"echoes","meaning":"跟着喊；附和","examples":[{"en":"A flock of toddlers echoes Gloria Thomas’s command.","zh":"一群幼童跟着 Gloria Thomas 的指令喊。"},{"en":"Echoes means repeats the same words or sounds after someone else.","zh":"echoes 指在別人之後重複相同說話或聲音。"},{"en":"Children may echo a teacher’s chant during a music lesson.","zh":"兒童可能在音樂課中跟着老師的口號喊。"},{"en":"Repeating commands can help young children follow instructions and join the activity.","zh":"重複指令可以幫助幼童跟隨指示並參與活動。"},{"en":"This word is useful when describing imitation or repeated sound.","zh":"描述模仿或重複聲音時，這個詞很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":10},{"front":"flock of toddlers","meaning":"一群幼童","examples":[{"en":"A flock of toddlers copied the teacher’s actions.","zh":"一群幼童模仿老師的動作。"},{"en":"A flock of toddlers means a group of very young children.","zh":"flock of toddlers 指一群很年幼的孩子。"},{"en":"A nursery teacher may guide a flock of toddlers across the playground.","zh":"幼兒園老師可能帶着一群幼童穿過操場。"},{"en":"Using flock makes the group sound lively, busy, and a little chaotic.","zh":"使用 flock 令群體聽起來活潑、忙亂和有點混亂。"},{"en":"This phrase is informal and visual.","zh":"這個短語較口語，而且畫面感強。"}],"source":"34 - Activities for Children.pdf","sourcePage":10},{"front":"adopting outrageous poses","meaning":"擺出誇張姿勢","examples":[{"en":"The toddlers were adopting outrageous poses on their space hoppers.","zh":"幼童在彈跳球上擺出誇張姿勢。"},{"en":"Adopting outrageous poses means taking funny, exaggerated, or silly body positions.","zh":"adopting outrageous poses 指擺出搞笑、誇張或傻氣的身體姿勢。"},{"en":"Children may adopt outrageous poses during a dance warm-up.","zh":"兒童可能在舞蹈熱身中擺出誇張姿勢。"},{"en":"Silly poses can make shy children relax and enjoy movement.","zh":"傻氣姿勢可以令害羞兒童放鬆並享受活動。"},{"en":"This phrase is useful when describing playful physical expression.","zh":"描述玩味身體表達時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":10},{"front":"spoof shriek","meaning":"搞笑模仿式尖叫","examples":[{"en":"The children gave a spoof, fan-crazed shriek.","zh":"兒童發出搞笑模仿式、粉絲狂熱般的尖叫。"},{"en":"A spoof shriek is a pretend or comic scream made to imitate something dramatically.","zh":"spoof shriek 指假裝或搞笑地模仿某種誇張尖叫。"},{"en":"Children may give a spoof shriek when pretending to be excited fans.","zh":"兒童假裝成興奮粉絲時，可能發出搞笑模仿式尖叫。"},{"en":"Playful shouting can make exercise feel theatrical and fun.","zh":"玩味叫喊可以令運動感覺像表演一樣有趣。"},{"en":"This phrase is humorous and describes mock excitement.","zh":"這個短語帶幽默感，描述模仿式興奮。"}],"source":"34 - Activities for Children.pdf","sourcePage":10},{"front":"fan-crazed","meaning":"粉絲狂熱般的","examples":[{"en":"The children gave a fan-crazed shriek.","zh":"兒童發出粉絲狂熱般的尖叫。"},{"en":"Fan-crazed means wildly excited like fans seeing a favourite star.","zh":"fan-crazed 指像粉絲看到最喜愛明星般極度興奮。"},{"en":"Students may give a fan-crazed cheer when a famous singer visits school.","zh":"當著名歌手到訪學校，學生可能發出粉絲狂熱般的歡呼。"},{"en":"This expression makes the children’s excitement sound exaggerated and funny.","zh":"這個表達令兒童的興奮聽起來誇張而有趣。"},{"en":"It is useful for describing playful enthusiasm.","zh":"它適合描述玩味的熱情。"}],"source":"34 - Activities for Children.pdf","sourcePage":10},{"front":"wild and chaotic","meaning":"狂野而混亂的","examples":[{"en":"The hopper race was wild and chaotic.","zh":"彈跳球比賽狂野而混亂。"},{"en":"Wild and chaotic means noisy, uncontrolled, energetic, and disorganised.","zh":"wild and chaotic 指嘈吵、難以控制、充滿活力且沒有秩序。"},{"en":"A children’s birthday party may become wild and chaotic after everyone eats cake.","zh":"兒童生日會在大家吃完蛋糕後可能變得狂野而混亂。"},{"en":"Chaotic activity can still be healthy if children are moving and enjoying themselves safely.","zh":"如果兒童安全地活動並享受其中，混亂活動仍可以健康。"},{"en":"This phrase is useful when describing lively disorder.","zh":"描述充滿活力的混亂時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":10},{"front":"hopper race","meaning":"彈跳球比賽","examples":[{"en":"The children joined a hopper race across the studio floor.","zh":"兒童參加在工作室地板上進行的彈跳球比賽。"},{"en":"A hopper race is a race in which children bounce forward on space hoppers.","zh":"hopper race 指兒童坐在彈跳球上向前彈的比賽。"},{"en":"A playgroup may hold a hopper race to make exercise fun for young children.","zh":"遊戲小組可能舉辦彈跳球比賽，令幼童覺得運動有趣。"},{"en":"Racing on hoppers develops balance, energy, and laughter at the same time.","zh":"在彈跳球上比賽可以同時發展平衡、體力和歡笑。"},{"en":"This phrase names a playful children’s activity.","zh":"這個短語指一種玩味兒童活動。"}],"source":"34 - Activities for Children.pdf","sourcePage":10},{"front":"studio floor","meaning":"工作室地板","examples":[{"en":"The children raced across the studio floor.","zh":"兒童在工作室地板上比賽。"},{"en":"Studio floor means the floor area inside a room used for dance, exercise, recording, or performance.","zh":"studio floor 指舞蹈、運動、錄影或表演房間內的地板區域。"},{"en":"A dance teacher may ask students to sit on the studio floor before warm-up.","zh":"舞蹈老師可能要求學生在熱身前坐在工作室地板上。"},{"en":"A safe open floor gives children space to move freely.","zh":"安全開放的地板給兒童自由活動空間。"},{"en":"This phrase is useful when describing indoor activity spaces.","zh":"描述室內活動空間時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":10},{"front":"commands are issued","meaning":"指令被發出","examples":[{"en":"Commands are issued during the children’s activity.","zh":"兒童活動期間，指令被發出。"},{"en":"Commands are issued means instructions are given clearly, often by a leader or teacher.","zh":"commands are issued 指由領袖或老師清楚給出指示。"},{"en":"In a PE class, commands are issued so children know when to run, stop, or jump.","zh":"在體育課中，指令被發出，讓兒童知道何時跑、停或跳。"},{"en":"Clear commands help keep energetic activities organised and safe.","zh":"清楚指令幫助充滿活力的活動保持有序和安全。"},{"en":"This phrase is formal and often passive.","zh":"這個短語較正式，常用被動語態。"}],"source":"34 - Activities for Children.pdf","sourcePage":10},{"front":"greeted with","meaning":"受到……回應","examples":[{"en":"The commands are greeted with unrestrained glee.","zh":"這些指令受到毫不掩飾的歡喜回應。"},{"en":"Greeted with means received or responded to in a particular way.","zh":"greeted with 指以某種方式被接受或回應。"},{"en":"The teacher’s announcement of a game was greeted with cheers.","zh":"老師宣布玩遊戲時，可能受到歡呼回應。"},{"en":"A response can show whether people are excited, disappointed, or confused.","zh":"回應可以顯示人們是興奮、失望還是困惑。"},{"en":"This phrase is useful when describing reactions.","zh":"描述反應時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":10},{"front":"unrestrained glee","meaning":"毫不掩飾的歡喜","examples":[{"en":"The children greeted the commands with unrestrained glee.","zh":"兒童以毫不掩飾的歡喜回應指令。"},{"en":"Unrestrained glee means open, uncontrolled happiness and excitement.","zh":"unrestrained glee 指毫不壓抑的快樂和興奮。"},{"en":"Children may show unrestrained glee when a surprise playground trip is announced.","zh":"當宣布驚喜遊樂場活動時，兒童可能表現出毫不掩飾的歡喜。"},{"en":"Such joy can make physical activity feel natural and enjoyable.","zh":"這種快樂可以令體能活動感覺自然又愉快。"},{"en":"This phrase is expressive and positive.","zh":"這個短語富表現力，而且正面。"}],"source":"34 - Activities for Children.pdf","sourcePage":10},{"front":"the sight of","meaning":"……的景象","examples":[{"en":"The sight of bouncing children brings tears to the eyes.","zh":"兒童彈跳的景象令人眼泛淚光。"},{"en":"The sight of something means the image or scene of seeing it.","zh":"sight of something 指看見某物時的畫面或景象。"},{"en":"The sight of children playing outside can make a neighbourhood feel alive.","zh":"兒童在戶外玩耍的景象可以令社區感覺有生命力。"},{"en":"A strong visual scene can create emotion immediately.","zh":"強烈視覺場面可以立即引起情感。"},{"en":"This phrase is useful when describing what someone sees.","zh":"描述某人所見時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":11},{"front":"bouncing seven-year-olds","meaning":"彈跳中的七歲兒童","examples":[{"en":"The sight of bouncing seven-year-olds was very funny.","zh":"彈跳中的七歲兒童的景象非常有趣。"},{"en":"Bouncing seven-year-olds are seven-year-old children jumping up and down energetically.","zh":"bouncing seven-year-olds 指充滿活力上下彈跳的七歲兒童。"},{"en":"A group of bouncing seven-year-olds can turn a fitness class into a comedy scene.","zh":"一群彈跳中的七歲兒童可以把健體課變成喜劇場面。"},{"en":"Bouncing movement raises energy and makes exercise feel playful.","zh":"彈跳動作提升活力，令運動感覺像遊戲。"},{"en":"This phrase creates a lively image of active children.","zh":"這個短語創造出活躍兒童的生動畫面。"}],"source":"34 - Activities for Children.pdf","sourcePage":11},{"front":"launch into orbit","meaning":"發射進入軌道","examples":[{"en":"The children seemed about to launch into orbit with every bounce.","zh":"兒童每跳一下都似乎快要發射進入軌道。"},{"en":"Launch into orbit means shoot upward like a rocket into space, used here humorously.","zh":"launch into orbit 指像火箭一樣向上射入太空，這裏是幽默用法。"},{"en":"A child jumping very high on a trampoline may look ready to launch into orbit.","zh":"孩子在彈床上跳得很高時，可能看起來快要發射進入軌道。"},{"en":"Exaggeration makes the scene sound funny and energetic.","zh":"誇張說法令場面聽起來有趣又有活力。"},{"en":"This phrase is a playful metaphor, not a literal action.","zh":"這個短語是玩味比喻，不是字面動作。"}],"source":"34 - Activities for Children.pdf","sourcePage":11},{"front":"with every bounce","meaning":"每跳一下","examples":[{"en":"The children seemed to fly higher with every bounce.","zh":"兒童每跳一下似乎都飛得更高。"},{"en":"With every bounce means each time they bounced.","zh":"with every bounce 指每一次彈跳時。"},{"en":"A child on a trampoline may laugh louder with every bounce.","zh":"彈床上的孩子可能每跳一下都笑得更大聲。"},{"en":"Repeated movement can build excitement and rhythm.","zh":"重複動作可以建立興奮感和節奏。"},{"en":"This phrase is useful when describing repeated actions.","zh":"描述重複行動時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":11},{"front":"brings tears to the eyes","meaning":"令人眼泛淚光","examples":[{"en":"The scene brings tears to the eyes because it is so funny.","zh":"這個場面因為太好笑而令人眼泛淚光。"},{"en":"Brings tears to the eyes means makes someone cry or nearly cry, often from strong emotion or laughter.","zh":"brings tears to the eyes 指令某人哭或幾乎哭，常因強烈情感或大笑。"},{"en":"A moving speech can bring tears to the eyes of the audience.","zh":"感人的演講可以令觀眾眼泛淚光。"},{"en":"Something very funny can also bring tears to the eyes because people laugh so hard.","zh":"非常好笑的事情也可以因令人笑得太厲害而眼泛淚光。"},{"en":"This phrase describes a strong emotional reaction.","zh":"這個短語描述強烈情緒反應。"}],"source":"34 - Activities for Children.pdf","sourcePage":11},{"front":"uncoordinated","meaning":"動作不協調的","examples":[{"en":"The children were uncoordinated, loud and excited.","zh":"兒童動作不協調、吵鬧而興奮。"},{"en":"Uncoordinated means not moving body parts smoothly or in an organised way.","zh":"uncoordinated 指身體部位動作不順暢或不協調。"},{"en":"A young child may look uncoordinated when first learning to skip.","zh":"幼童初學跳繩時可能看起來動作不協調。"},{"en":"Coordination often improves with practice, balance, and repeated movement.","zh":"協調能力常透過練習、平衡和重複動作而改善。"},{"en":"This word is useful when describing physical movement.","zh":"描述身體動作時，這個詞很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":11},{"front":"raw comedy","meaning":"原始自然的喜劇效果","examples":[{"en":"Children can provide raw comedy when they are active and excited.","zh":"兒童活躍而興奮時，可以帶來原始自然的喜劇效果。"},{"en":"Raw comedy means natural, unplanned humour that comes from real behaviour.","zh":"raw comedy 指來自真實行為、自然且未經計劃的幽默。"},{"en":"Toddlers dancing seriously to music can create raw comedy without trying.","zh":"幼童認真跟着音樂跳舞，即使沒有刻意搞笑，也可以產生自然喜劇效果。"},{"en":"Uncontrolled movement and honest reactions can be funnier than planned jokes.","zh":"不受控制的動作和真實反應，可以比安排好的笑話更好笑。"},{"en":"This phrase is useful when humour feels spontaneous.","zh":"當幽默感覺自然 spontaneous 時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":11},{"front":"cardiovascular exercise","meaning":"心血管運動","examples":[{"en":"Any cardiovascular exercise is a good option.","zh":"任何心血管運動都是好選擇。"},{"en":"Cardiovascular exercise is exercise that raises the heart rate and trains the heart and lungs.","zh":"cardiovascular exercise 指令心率上升並鍛煉心臟和肺部的運動。"},{"en":"Running, swimming, cycling, and fast walking are forms of cardiovascular exercise.","zh":"跑步、游泳、踩單車和快步行都是心血管運動。"},{"en":"Regular cardiovascular exercise can improve stamina and support heart health.","zh":"定期心血管運動可以改善耐力並支持心臟健康。"},{"en":"This phrase is common in fitness and health advice.","zh":"這個短語常見於健身和健康建議。"}],"source":"34 - Activities for Children.pdf","sourcePage":11},{"front":"good option","meaning":"好選擇","examples":[{"en":"Walking, swimming and running are good exercise options.","zh":"步行、游泳和跑步都是好的運動選擇。"},{"en":"A good option is a sensible or useful choice.","zh":"good option 指合理或有用的選擇。"},{"en":"Taking the stairs can be a good option for adding movement to a busy day.","zh":"走樓梯可以是在忙碌一天中增加活動量的好選擇。"},{"en":"Good options are easier to maintain when they fit daily life.","zh":"當好選擇配合日常生活，它們較容易維持。"},{"en":"This phrase is useful when suggesting practical choices.","zh":"提出實用選擇時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":11},{"front":"not necessarily","meaning":"不一定","examples":[{"en":"Exercise does not necessarily have to be high intensity.","zh":"運動不一定要高強度。"},{"en":"Not necessarily means not always or not in every case.","zh":"not necessarily 指不總是或並非每種情況都如此。"},{"en":"A good lesson does not necessarily need expensive technology.","zh":"好課堂不一定需要昂貴科技。"},{"en":"This phrase prevents people from making too broad a rule.","zh":"這個短語防止人作出過於廣泛的規則。"},{"en":"It is useful when correcting a common assumption.","zh":"糾正常見假設時，它很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":11},{"front":"high intensity","meaning":"高強度","examples":[{"en":"Exercise does not have to be high intensity to be useful.","zh":"運動不必高強度才有用。"},{"en":"High intensity means requiring strong effort and making the body work hard.","zh":"high intensity 指需要強烈努力，令身體辛苦工作的程度。"},{"en":"Sprinting is high intensity, while gentle walking is lower intensity.","zh":"短跑是高強度，而輕鬆步行則較低強度。"},{"en":"Not every child needs high-intensity exercise to become more active.","zh":"不是每個孩子都需要高強度運動才能變得更活躍。"},{"en":"This phrase is useful when comparing exercise difficulty.","zh":"比較運動難度時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":11},{"front":"gets your heart rate up","meaning":"令心率上升","examples":[{"en":"Exercise can be anything that gets your heart rate up.","zh":"運動可以是任何令心率上升的事情。"},{"en":"Gets your heart rate up means makes your heart beat faster.","zh":"gets your heart rate up 指令心臟跳得更快。"},{"en":"Dancing to fast music can get your heart rate up without feeling like formal exercise.","zh":"隨快歌跳舞可以令心率上升，而不感覺像正式運動。"},{"en":"Raising the heart rate helps train the cardiovascular system.","zh":"提高心率有助訓練心血管系統。"},{"en":"This phrase is common in everyday fitness advice.","zh":"這個短語常見於日常健身建議。"}],"source":"34 - Activities for Children.pdf","sourcePage":12},{"front":"walking the dog","meaning":"遛狗","examples":[{"en":"Walking the dog can be a form of exercise.","zh":"遛狗可以是一種運動。"},{"en":"Walking the dog means taking a dog outside for a walk.","zh":"walking the dog 指帶狗出外散步。"},{"en":"A parent may walk the dog with a child after dinner.","zh":"家長可能晚飯後和孩子一起遛狗。"},{"en":"Everyday tasks like walking the dog can add movement without needing a gym.","zh":"遛狗等日常任務可以增加活動量，而不需要健身室。"},{"en":"This phrase is useful when showing simple daily exercise.","zh":"展示簡單日常運動時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":12},{"front":"swimming, running, skipping and hiking","meaning":"游泳、跑步、跳繩和行山","examples":[{"en":"Swimming, running, skipping and hiking can all raise your heart rate.","zh":"游泳、跑步、跳繩和行山都可以令心率上升。"},{"en":"Swimming, running, skipping and hiking are physical activities that train the body in different ways.","zh":"swimming, running, skipping and hiking 是以不同方式鍛煉身體的體能活動。"},{"en":"A family may choose swimming in summer and hiking in cooler weather.","zh":"家庭可能在夏天選擇游泳，在較涼天氣選擇行山。"},{"en":"Offering varied activities helps children find exercise they enjoy.","zh":"提供多樣活動有助兒童找到自己喜歡的運動。"},{"en":"This phrase lists accessible examples of active movement.","zh":"這個短語列出容易理解的活躍活動例子。"}],"source":"34 - Activities for Children.pdf","sourcePage":12},{"front":"grocery store","meaning":"雜貨店；食品雜貨店","examples":[{"en":"Even walking through the grocery store can be exercise.","zh":"即使在雜貨店中走動也可以是運動。"},{"en":"A grocery store is a shop that sells food and daily household items.","zh":"grocery store 指售賣食物和日常家居用品的商店。"},{"en":"A family may walk around a grocery store while buying vegetables, milk, and bread.","zh":"家庭可能在雜貨店中走動，購買蔬菜、牛奶和麵包。"},{"en":"Everyday walking in shops can add small amounts of movement to daily life.","zh":"在商店中的日常步行可以為生活加入少量活動。"},{"en":"This phrase is common in American English; British English often says supermarket or shop.","zh":"這個短語常見於美式英語；英式英語常說 supermarket 或 shop。"}],"source":"34 - Activities for Children.pdf","sourcePage":12},{"front":"Fit Kids class","meaning":"Fit Kids 課堂","examples":[{"en":"The children do not know that they are at a Fit Kids class.","zh":"兒童不知道自己正在 Fit Kids 課堂中。"},{"en":"A Fit Kids class is an exercise class designed to make fitness fun for children.","zh":"Fit Kids class 指設計來令兒童覺得健身有趣的運動課。"},{"en":"A Fit Kids class may use games, music, and toys instead of formal drills.","zh":"Fit Kids 課堂可能使用遊戲、音樂和玩具，而不是正式操練。"},{"en":"If children enjoy the class, they may exercise without feeling forced.","zh":"如果兒童享受課堂，他們可能在不覺得被迫的情況下運動。"},{"en":"This phrase names the children’s fitness programme in the passage.","zh":"這個短語指文章中的兒童健體課程。"}],"source":"34 - Activities for Children.pdf","sourcePage":12},{"front":"a disguise for","meaning":"……的掩飾","examples":[{"en":"The fun is a disguise for a serious exercise plan.","zh":"這份樂趣是認真運動計劃的掩飾。"},{"en":"A disguise for something is an outward appearance that hides the real purpose.","zh":"disguise for something 指隱藏真正目的的外在形式。"},{"en":"A vocabulary game can be a disguise for serious spelling practice.","zh":"詞彙遊戲可以是認真拼寫練習的掩飾。"},{"en":"When exercise is disguised as play, children may join more willingly.","zh":"當運動被包裝成遊戲，兒童可能更願意參與。"},{"en":"This phrase is useful when something serious is hidden inside something fun.","zh":"當嚴肅事情藏在有趣事情之中時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":12},{"front":"serious exercise plan","meaning":"認真的運動計劃","examples":[{"en":"The fun activity hides a serious exercise plan.","zh":"有趣活動隱藏了一個認真的運動計劃。"},{"en":"A serious exercise plan is a planned programme designed to improve fitness, not just entertain.","zh":"serious exercise plan 指旨在改善體能、而不只是娛樂的有計劃課程。"},{"en":"A children’s class may look like play but follow a serious exercise plan underneath.","zh":"兒童課堂表面像遊戲，但底下可能跟隨認真的運動計劃。"},{"en":"Careful planning makes sure children move enough and use different body skills.","zh":"仔細規劃確保兒童有足夠活動量並使用不同身體技能。"},{"en":"This phrase contrasts fun appearance with real fitness purpose.","zh":"這個短語把有趣外表與真正健體目的作對比。"}],"source":"34 - Activities for Children.pdf","sourcePage":12},{"front":"covertly","meaning":"暗中地","examples":[{"en":"The children are covertly taken through an exercise plan.","zh":"兒童被暗中帶着完成一個運動計劃。"},{"en":"Covertly means secretly or in a way that is not obvious.","zh":"covertly 指秘密地或以不明顯方式。"},{"en":"A teacher may covertly practise grammar through a speaking game.","zh":"老師可能透過說話遊戲暗中練習文法。"},{"en":"When learning is hidden inside play, students may feel less pressure.","zh":"當學習藏在遊戲中，學生可能感到較少壓力。"},{"en":"This word is useful when the real purpose is not immediately visible.","zh":"當真正目的不立即可見時，這個詞很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":12},{"front":"being taken through","meaning":"被帶着完成……","examples":[{"en":"The children are being taken through a serious exercise plan.","zh":"兒童正被帶着完成一個認真的運動計劃。"},{"en":"Being taken through something means being guided step by step through it.","zh":"being taken through something 指被逐步帶領完成某事。"},{"en":"A teacher may take students through an essay plan before they start writing.","zh":"老師可能在學生開始寫作前，帶着他們完成文章計劃。"},{"en":"Step-by-step guidance helps learners follow a process without feeling lost.","zh":"逐步指引幫助學習者跟隨過程而不感到迷失。"},{"en":"This phrase is useful when someone is guided through an activity.","zh":"當某人被引導完成活動時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":12},{"front":"trains parents to","meaning":"培訓家長去……","examples":[{"en":"Fit Kids trains parents to run fitness classes for children.","zh":"Fit Kids 培訓家長去為兒童舉辦健體課。"},{"en":"Trains parents to do something means teaches parents the skills needed to do it.","zh":"trains parents to do something 指教家長做某事所需技能。"},{"en":"A school may train parents to support children’s reading at home.","zh":"學校可能培訓家長在家支援兒童閱讀。"},{"en":"Training parents can extend learning or fitness beyond the classroom.","zh":"培訓家長可以把學習或健體延伸到課室以外。"},{"en":"This phrase is useful when adults are taught to support children.","zh":"當成人被教導如何支援兒童時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":12},{"front":"fitness classes","meaning":"健體課程","examples":[{"en":"Parents learn to run fitness classes for children.","zh":"家長學習為兒童舉辦健體課程。"},{"en":"Fitness classes are organised sessions that teach exercise and physical activity.","zh":"fitness classes 指教授運動和體能活動的有組織課堂。"},{"en":"A community centre may offer fitness classes for children, adults, or older people.","zh":"社區中心可能為兒童、成人或長者提供健體課程。"},{"en":"Regular classes can create routine and make exercise easier to continue.","zh":"定期課程可以建立規律，令運動更容易持續。"},{"en":"This phrase is common in health and exercise contexts.","zh":"這個短語常見於健康和運動語境。"}],"source":"34 - Activities for Children.pdf","sourcePage":12},{"front":"company director","meaning":"公司董事","examples":[{"en":"Gillian Gale is the company director of Fit Kids.","zh":"Gillian Gale 是 Fit Kids 的公司董事。"},{"en":"A company director is a senior person responsible for managing or leading a company.","zh":"company director 指負責管理或領導公司的高層人士。"},{"en":"A company director may decide strategy, budgets, and staff training.","zh":"公司董事可能決定策略、預算和員工培訓。"},{"en":"Directors shape how a programme grows and how it presents itself to the public.","zh":"董事會塑造計劃如何發展以及如何面向公眾。"},{"en":"This phrase is common in business contexts.","zh":"這個短語常見於商業語境。"}],"source":"34 - Activities for Children.pdf","sourcePage":13},{"front":"prevention survey","meaning":"預防研究調查","examples":[{"en":"A prevention survey found that parents’ fitness affects children.","zh":"一項預防研究調查發現家長體能會影響兒童。"},{"en":"A prevention survey is a study designed to identify risks and ways to prevent problems.","zh":"prevention survey 指旨在找出風險和預防問題方法的研究。"},{"en":"A school may run a prevention survey to understand bullying before it gets worse.","zh":"學校可能進行預防研究調查，以在欺凌惡化前了解問題。"},{"en":"Prevention research helps people act early instead of waiting for serious harm.","zh":"預防研究幫助人們及早行動，而不是等到嚴重傷害出現。"},{"en":"This phrase is useful in public health and safety planning.","zh":"這個短語適用於公共健康和安全規劃。"}],"source":"34 - Activities for Children.pdf","sourcePage":13},{"front":"keep in shape","meaning":"保持體形；保持健康","examples":[{"en":"Children whose parents keep in shape are more likely to be healthy.","zh":"家長保持健康的兒童較有可能健康。"},{"en":"To keep in shape means to stay physically fit and healthy.","zh":"keep in shape 指保持身體健康和體能良好。"},{"en":"A parent may keep in shape by walking daily and eating balanced meals.","zh":"家長可能透過每天步行和均衡飲食保持健康。"},{"en":"When parents keep fit, children may copy their active habits.","zh":"當家長保持體能，兒童可能模仿他們的活躍習慣。"},{"en":"This phrase is common in everyday fitness talk.","zh":"這個短語常見於日常健身用語。"}],"source":"34 - Activities for Children.pdf","sourcePage":13},{"front":"maintain healthy body weights","meaning":"維持健康體重","examples":[{"en":"Children are more likely to maintain healthy body weights if their parents are active.","zh":"如果家長活躍，兒童較有可能維持健康體重。"},{"en":"To maintain healthy body weights means to keep body weight within a healthy range.","zh":"maintain healthy body weights 指把體重保持在健康範圍內。"},{"en":"Families may maintain healthy body weights through regular meals and daily movement.","zh":"家庭可以透過定時進食和每日活動維持健康體重。"},{"en":"Active parents can model habits that help children avoid unhealthy weight gain.","zh":"活躍家長可以示範有助兒童避免不健康增重的習慣。"},{"en":"This phrase is common in health and nutrition discussions.","zh":"這個短語常見於健康和營養討論。"}],"source":"34 - Activities for Children.pdf","sourcePage":13},{"front":"nutritional consultant","meaning":"營養顧問","examples":[{"en":"Elizabeth Ward is a Boston nutritional consultant.","zh":"Elizabeth Ward 是波士頓營養顧問。"},{"en":"A nutritional consultant is an expert who advises people about food, diet, and healthy eating.","zh":"nutritional consultant 指就食物、飲食和健康進食提供建議的專家。"},{"en":"A family may ask a nutritional consultant how to prepare balanced meals for children.","zh":"家庭可能請營養顧問教他們如何為兒童準備均衡餐。"},{"en":"Nutrition advice can help prevent health problems linked to poor diet.","zh":"營養建議可以幫助預防與不良飲食相關的健康問題。"},{"en":"This phrase is common in health and diet contexts.","zh":"這個短語常見於健康和飲食語境。"}],"source":"34 - Activities for Children.pdf","sourcePage":13},{"front":"set a good example","meaning":"樹立好榜樣","examples":[{"en":"Parents should set a good example for their children.","zh":"家長應為子女樹立好榜樣。"},{"en":"To set a good example means to behave in a way others can copy positively.","zh":"set a good example 指以值得他人正面模仿的方式行事。"},{"en":"A parent sets a good example by walking short distances instead of always driving.","zh":"家長短途步行而不是總是開車，就是樹立好榜樣。"},{"en":"Children often learn habits by watching adults more than by listening to advice.","zh":"兒童常透過觀察成人學習習慣，而不只是聽建議。"},{"en":"This phrase is useful when discussing role models.","zh":"討論榜樣時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":13},{"front":"get your nutritional house in order","meaning":"先整頓自己的營養習慣","examples":[{"en":"Parents should get their nutritional house in order first.","zh":"家長應先整頓自己的營養習慣。"},{"en":"To get your nutritional house in order means to improve and organise your own eating habits before advising others.","zh":"get your nutritional house in order 指在建議別人之前，先改善和整理自己的飲食習慣。"},{"en":"A parent who wants a child to eat vegetables should first improve the food kept at home.","zh":"想孩子吃蔬菜的家長，應先改善家中存放的食物。"},{"en":"Children may follow healthy eating more easily when parents practise it themselves.","zh":"當家長自己實踐健康飲食，兒童可能更容易跟隨。"},{"en":"This phrase is metaphorical and means fix your own nutrition first.","zh":"這個短語是比喻，意思是先處理好自己的營養問題。"}],"source":"34 - Activities for Children.pdf","sourcePage":13},{"front":"expended 800 calories a day","meaning":"每日消耗800卡路里","examples":[{"en":"Children once expended 800 calories a day through chores.","zh":"兒童以前透過家務每日消耗800卡路里。"},{"en":"Expended 800 calories a day means used about 800 units of energy each day through activity.","zh":"expended 800 calories a day 指每天透過活動使用約800卡路里能量。"},{"en":"A farmer may expend many calories a day by lifting, walking, and carrying tools.","zh":"農夫可能透過搬抬、步行和拿工具，每天消耗許多卡路里。"},{"en":"Daily physical work can burn energy without formal exercise.","zh":"每日體力工作可以在沒有正式運動下燃燒能量。"},{"en":"This phrase is useful when discussing energy use.","zh":"討論能量消耗時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":13},{"front":"carrying water","meaning":"挑水；搬水","examples":[{"en":"Children once expended calories by walking and carrying water.","zh":"兒童以前透過步行和搬水消耗卡路里。"},{"en":"Carrying water means transporting water by hand, bucket, or container.","zh":"carrying water 指用手、水桶或容器運送水。"},{"en":"In some villages, children may help the family by carrying water from a well.","zh":"在一些村莊，兒童可能透過從井中搬水來幫助家庭。"},{"en":"Carrying heavy items can use energy and strengthen the body.","zh":"搬重物可以消耗能量並強化身體。"},{"en":"This phrase describes a physical chore.","zh":"這個短語描述一種體力家務。"}],"source":"34 - Activities for Children.pdf","sourcePage":13},{"front":"doing other chores","meaning":"做其他家務","examples":[{"en":"Children used to expend energy by doing other chores.","zh":"兒童以前透過做其他家務消耗能量。"},{"en":"Doing other chores means performing other household tasks such as cleaning, washing, or carrying things.","zh":"doing other chores 指做其他家務，例如清潔、洗東西或搬物件。"},{"en":"A child may help at home by doing chores like sweeping the floor or feeding pets.","zh":"孩子可能透過掃地或餵寵物等家務幫忙家中。"},{"en":"Chores can add movement to daily life even if they are not called exercise.","zh":"家務可以為日常生活增加活動量，即使它不被稱為運動。"},{"en":"This phrase is useful when discussing ordinary physical activity.","zh":"討論普通體能活動時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":13},{"front":"pediatric endocrinologist","meaning":"兒科內分泌科醫生","examples":[{"en":"Fima Lifshitz is a pediatric endocrinologist in Santa Barbara.","zh":"Fima Lifshitz 是聖巴巴拉的兒科內分泌科醫生。"},{"en":"A pediatric endocrinologist is a doctor who treats children’s hormone and growth-related conditions.","zh":"pediatric endocrinologist 指治療兒童荷爾蒙和生長相關問題的醫生。"},{"en":"A child with unusual growth or weight problems may see a pediatric endocrinologist.","zh":"有異常成長或體重問題的孩子可能看兒科內分泌科醫生。"},{"en":"Hormones can affect growth, metabolism, and body weight.","zh":"荷爾蒙可以影響成長、新陳代謝和體重。"},{"en":"This phrase is a formal medical job title.","zh":"這個短語是正式醫學職銜。"}],"source":"34 - Activities for Children.pdf","sourcePage":13},{"front":"obese families","meaning":"肥胖家庭","examples":[{"en":"Children in obese families may expend fewer calories through activity.","zh":"肥胖家庭中的兒童可能透過活動消耗較少卡路里。"},{"en":"Obese families are families in which several members have obesity or serious weight problems.","zh":"obese families 指多名成員有肥胖或嚴重體重問題的家庭。"},{"en":"A doctor may discuss diet and movement patterns with obese families.","zh":"醫生可能與肥胖家庭討論飲食和活動模式。"},{"en":"Family habits can influence how active children are each day.","zh":"家庭習慣可以影響兒童每天有多活躍。"},{"en":"This phrase should be used carefully and respectfully in health contexts.","zh":"在健康語境中使用這個短語時，應小心而尊重。"}],"source":"34 - Activities for Children.pdf","sourcePage":14},{"front":"physical activity","meaning":"體能活動","examples":[{"en":"Children in obese families may expend only 200 calories a day in physical activity.","zh":"肥胖家庭中的兒童每天可能只透過體能活動消耗200卡路里。"},{"en":"Physical activity is any body movement that uses energy.","zh":"physical activity 指任何使用能量的身體活動。"},{"en":"Walking, climbing stairs, dancing, and playing outside are forms of physical activity.","zh":"步行、爬樓梯、跳舞和戶外玩耍都是體能活動。"},{"en":"More daily physical activity can help improve fitness and weight management.","zh":"更多日常體能活動可以幫助改善體能和體重管理。"},{"en":"This phrase is broader than formal sport or exercise.","zh":"這個短語比正式運動或鍛煉更廣。"}],"source":"34 - Activities for Children.pdf","sourcePage":14},{"front":"incorporate more movement into","meaning":"將更多活動加入……","examples":[{"en":"Families should incorporate more movement into daily life.","zh":"家庭應將更多活動加入日常生活。"},{"en":"To incorporate more movement into something means to add more physical activity to it naturally.","zh":"incorporate more movement into something 指自然地把更多體能活動加入某事。"},{"en":"A family can incorporate more movement into weekends by walking to the market.","zh":"家庭可以透過步行去市場，把更多活動加入週末。"},{"en":"Small changes can increase activity without requiring a formal exercise class.","zh":"小改變可以增加活動量，而不需要正式運動課。"},{"en":"This phrase is useful when discussing practical lifestyle changes.","zh":"討論實用生活方式改變時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":14},{"front":"family life","meaning":"家庭生活","examples":[{"en":"Parents can build more movement into family life.","zh":"家長可以把更多活動加入家庭生活。"},{"en":"Family life means the daily routines, relationships, and activities shared by a family.","zh":"family life 指家庭共享的日常規律、關係和活動。"},{"en":"Family life may include meals, chores, homework, shopping, and weekend outings.","zh":"家庭生活可能包括用餐、家務、功課、購物和週末外出。"},{"en":"If movement becomes part of family life, children may see exercise as normal.","zh":"如果活動成為家庭生活一部分，兒童可能視運動為正常。"},{"en":"This phrase is useful when discussing habits at home.","zh":"討論家中習慣時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":14},{"front":"park farther from","meaning":"泊車泊得離……較遠","examples":[{"en":"Parents can park farther from shops to increase walking.","zh":"家長可以把車泊得離商店較遠，以增加步行。"},{"en":"To park farther from somewhere means to leave the car at a greater distance from the destination.","zh":"park farther from somewhere 指把車停在離目的地較遠的位置。"},{"en":"A family may park farther from the supermarket to add a short walk.","zh":"家庭可能把車泊得離超市較遠，以加入一段短步行。"},{"en":"Small walking opportunities can increase daily movement over time.","zh":"小小步行機會可以隨時間增加每日活動量。"},{"en":"This phrase is useful when suggesting simple exercise habits.","zh":"建議簡單運動習慣時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":14},{"front":"at the mall","meaning":"在商場","examples":[{"en":"Families can walk more when visiting shops at the mall.","zh":"家庭到商場購物時可以走更多路。"},{"en":"At the mall means in or around a shopping centre.","zh":"at the mall 指在商場內或附近。"},{"en":"A parent may choose to walk around at the mall instead of taking lifts between floors.","zh":"家長可能選擇在商場中多走路，而不是在樓層之間乘升降機。"},{"en":"Shopping trips can become chances for light physical activity.","zh":"購物行程可以變成輕量體能活動機會。"},{"en":"This phrase is common in American English for shopping centre contexts.","zh":"這個短語常見於美式英語的商場語境。"}],"source":"34 - Activities for Children.pdf","sourcePage":14},{"front":"take the stairs instead of","meaning":"走樓梯而不是……","examples":[{"en":"Families can take the stairs instead of the lift.","zh":"家庭可以走樓梯而不是乘升降機。"},{"en":"To take the stairs instead of something means to use stairs rather than another option such as a lift or escalator.","zh":"take the stairs instead of something 指使用樓梯，而不是升降機或扶手電梯等其他選項。"},{"en":"Office workers may take the stairs instead of the lift for one or two floors.","zh":"辦公室員工可能走一兩層樓梯而不是乘升降機。"},{"en":"Choosing stairs adds movement to daily routines without special equipment.","zh":"選擇樓梯可以不需特別器材就把活動加入日常。"},{"en":"This phrase is useful when comparing a healthier choice with an easier one.","zh":"比較較健康選擇與較方便選擇時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":14},{"front":"the lift","meaning":"升降機","examples":[{"en":"Taking the stairs instead of the lift increases daily movement.","zh":"走樓梯而不是乘升降機可以增加每日活動量。"},{"en":"The lift is the British English word for an elevator.","zh":"lift 是英式英語中 elevator 的說法。"},{"en":"In a shopping centre, families may choose stairs instead of the lift to walk more.","zh":"在商場中，家庭可能選擇走樓梯而不是乘升降機，以多走路。"},{"en":"Avoiding the lift for short distances can add simple exercise to the day.","zh":"短距離避免乘升降機，可以為一天加入簡單運動。"},{"en":"This phrase is useful in everyday transport inside buildings.","zh":"這個短語適用於建築物內的日常交通。"}],"source":"34 - Activities for Children.pdf","sourcePage":14},{"front":"nearby friends’ houses","meaning":"附近朋友的家","examples":[{"en":"Families can walk to nearby friends’ houses instead of driving.","zh":"家庭可以步行到附近朋友的家，而不是駕車。"},{"en":"Nearby friends’ houses are the homes of friends who live close enough to reach easily.","zh":"nearby friends’ houses 指住得近、容易到達的朋友住所。"},{"en":"A child may walk to a nearby friend’s house for a play date.","zh":"孩子可能步行到附近朋友的家玩耍。"},{"en":"Walking short distances helps families add movement without changing the whole day.","zh":"步行短距離幫助家庭增加活動，而不必改變整天安排。"},{"en":"This phrase is useful when giving examples of local walking trips.","zh":"提供本地步行行程例子時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":14},{"front":"instead of driving","meaning":"而不是駕車","examples":[{"en":"Families can walk short distances instead of driving.","zh":"家庭可以短距離步行，而不是駕車。"},{"en":"Instead of driving means choosing not to use a car and doing another action instead.","zh":"instead of driving 指選擇不用汽車，而改做另一行動。"},{"en":"A family may walk to the park instead of driving there.","zh":"家庭可能步行到公園，而不是駕車前往。"},{"en":"Walking instead of driving can increase exercise and reduce traffic pollution.","zh":"步行而不是駕車可以增加運動並減少交通污染。"},{"en":"This phrase is useful when contrasting a healthier choice with car use.","zh":"對比較健康選擇與用車時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":14},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"Students decide which paragraph contains the following information.","zh":"學生判斷哪一段包含以下資料。"},{"en":"Which paragraph contains asks students to find the paragraph where a detail appears.","zh":"which paragraph contains 指要求學生找出某細節出現在哪一段。"},{"en":"In a reading test, students scan the passage to see which paragraph contains a specific idea.","zh":"在閱讀測驗中，學生掃讀文章，找出哪一段包含特定想法。"},{"en":"A paragraph may contain the answer even if it uses different words from the question.","zh":"即使段落使用與題目不同的字眼，也可能包含答案。"},{"en":"This phrase is common in information-location tasks.","zh":"這個短語常見於資料定位題。"}],"source":"34 - Activities for Children.pdf","sourcePage":14},{"front":"following information","meaning":"以下資料","examples":[{"en":"The task asks students to locate the following information.","zh":"任務要求學生定位以下資料。"},{"en":"Following information means the details listed after the instruction.","zh":"following information 指指示後列出的細節。"},{"en":"Students should read the following information before scanning the passage.","zh":"學生應在掃讀文章前先閱讀以下資料。"},{"en":"Understanding what must be found helps students avoid random searching.","zh":"理解需要找甚麼，有助學生避免隨機搜尋。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"34 - Activities for Children.pdf","sourcePage":15},{"front":"changes in children’s health and living conditions","meaning":"兒童健康和生活條件的變化","examples":[{"en":"The passage describes changes in children’s health and living conditions.","zh":"文章描述兒童健康和生活條件的變化。"},{"en":"Changes in children’s health and living conditions are shifts in their physical well-being and daily environment.","zh":"changes in children’s health and living conditions 指兒童身體健康和日常環境的改變。"},{"en":"More screen time and fewer playing fields are examples of changes in living conditions.","zh":"更多螢幕時間和較少運動場都是生活條件變化的例子。"},{"en":"Such changes can affect exercise levels, weight, and future health.","zh":"這些變化可以影響運動量、體重和未來健康。"},{"en":"This phrase is useful when summarising broad social change.","zh":"概括廣泛社會變化時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":15},{"front":"health organisation","meaning":"健康組織","examples":[{"en":"A health organisation set safe cholesterol levels for children.","zh":"一個健康組織為兒童訂定安全膽固醇水平。"},{"en":"A health organisation is a group that works on medical, public health, or wellness issues.","zh":"health organisation 指處理醫療、公共健康或身心健康議題的團體。"},{"en":"A health organisation may publish advice about diet, exercise, and disease prevention.","zh":"健康組織可能發布關於飲食、運動和疾病預防的建議。"},{"en":"Expert organisations help people understand safe standards and risks.","zh":"專家組織幫助人們理解安全標準和風險。"},{"en":"This phrase is useful when identifying a source of health guidance.","zh":"指出健康指引來源時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":15},{"front":"monitoring of physical activity","meaning":"監測體能活動","examples":[{"en":"The survey involved monitoring children’s physical activity.","zh":"調查涉及監測兒童的體能活動。"},{"en":"Monitoring of physical activity means measuring or recording how much movement people do.","zh":"monitoring of physical activity 指測量或記錄人們做了多少身體活動。"},{"en":"A fitness watch can help with monitoring physical activity during the day.","zh":"健身手錶可以幫助監測一天中的體能活動。"},{"en":"Monitoring allows researchers to compare real behaviour with recommended exercise levels.","zh":"監測讓研究人員比較真實行為與建議運動水平。"},{"en":"This phrase is useful in health research.","zh":"這個短語適用於健康研究。"}],"source":"34 - Activities for Children.pdf","sourcePage":15},{"front":"comparison of exercise time","meaning":"運動時間的比較","examples":[{"en":"The passage gives a comparison of exercise time in different countries.","zh":"文章提供不同國家運動時間的比較。"},{"en":"A comparison of exercise time shows how much time different groups spend being active.","zh":"comparison of exercise time 指顯示不同群體花多少時間活動的比較。"},{"en":"A school may make a comparison of exercise time between boys and girls.","zh":"學校可能比較男生和女生的運動時間。"},{"en":"Comparisons can reveal whether one group is receiving less activity than another.","zh":"比較可以揭示某群體是否比另一群體獲得較少活動。"},{"en":"This phrase is useful when discussing statistics and health habits.","zh":"討論統計和健康習慣時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":15},{"front":"other countries","meaning":"其他國家","examples":[{"en":"The UK is compared with other countries in PE time.","zh":"英國在體育課時間上與其他國家比較。"},{"en":"Other countries means countries different from the one being discussed.","zh":"other countries 指不同於正在討論國家的國家。"},{"en":"Students may compare their school system with other countries to understand different approaches.","zh":"學生可能把自己的學校制度與其他國家比較，以理解不同做法。"},{"en":"Looking at other countries can show whether a problem is local or widespread.","zh":"查看其他國家可以顯示問題是本地性還是廣泛存在。"},{"en":"This phrase is useful in international comparison.","zh":"這個短語適用於國際比較。"}],"source":"34 - Activities for Children.pdf","sourcePage":15},{"front":"inappropriate approach to","meaning":"對……不恰當的做法","examples":[{"en":"The passage criticises an inappropriate approach to school sport.","zh":"文章批評對學校體育不恰當的做法。"},{"en":"An inappropriate approach to something is a method that does not suit the situation or people involved.","zh":"inappropriate approach to something 指不適合該情況或相關人士的方法。"},{"en":"Giving only competitive games may be an inappropriate approach to PE for shy children.","zh":"對害羞兒童來說，只安排競爭性遊戲可能是不恰當的體育做法。"},{"en":"The wrong approach can make students lose interest instead of becoming healthier.","zh":"錯誤方法可以令學生失去興趣，而不是變得更健康。"},{"en":"This phrase is useful when criticising a method.","zh":"批評方法時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":15},{"front":"school sport","meaning":"學校體育","examples":[{"en":"Schools may put too much emphasis on team games in school sport.","zh":"學校可能在學校體育中過分強調團隊運動。"},{"en":"School sport means organised physical activities and sports offered in school.","zh":"school sport 指學校提供的有組織體能活動和運動。"},{"en":"School sport may include PE lessons, sports teams, and inter-school competitions.","zh":"學校體育可能包括體育課、校隊和校際比賽。"},{"en":"Good school sport should help many children enjoy movement, not only the strongest players.","zh":"良好的學校體育應幫助許多兒童享受活動，而不只是最強的運動員。"},{"en":"This phrase is common in education and health discussion.","zh":"這個短語常見於教育和健康討論。"}],"source":"34 - Activities for Children.pdf","sourcePage":15},{"front":"agree with the information given","meaning":"與所給資料相符","examples":[{"en":"Students decide whether the statements agree with the information given.","zh":"學生判斷陳述是否與所給資料相符。"},{"en":"Agree with the information given means match what the passage says or supports.","zh":"agree with the information given 指符合文章所說或支持的內容。"},{"en":"A statement agrees with the information only if the text provides evidence for it.","zh":"只有文章提供證據支持，陳述才與資料相符。"},{"en":"Students should compare meaning, not just repeated words.","zh":"學生應比較意思，而不只是重複字眼。"},{"en":"This phrase is common in TRUE, FALSE, NOT GIVEN questions.","zh":"這個短語常見於 TRUE, FALSE, NOT GIVEN 題。"}],"source":"34 - Activities for Children.pdf","sourcePage":15},{"front":"statement agrees with","meaning":"陳述與……相符","examples":[{"en":"Students write TRUE if the statement agrees with the information.","zh":"如果陳述與資料相符，學生寫 TRUE。"},{"en":"Statement agrees with means the sentence matches the facts or ideas in the passage.","zh":"statement agrees with 指句子符合文章中的事實或想法。"},{"en":"If the passage says children are less active and the statement says the same, the statement agrees with it.","zh":"如果文章說兒童較不活躍，而陳述說同樣內容，該陳述就與文章相符。"},{"en":"Students must check the passage before deciding TRUE.","zh":"學生決定 TRUE 前必須查閱文章。"},{"en":"This phrase is part of reading-test instructions.","zh":"這個短語是閱讀測驗指示的一部分。"}],"source":"34 - Activities for Children.pdf","sourcePage":15},{"front":"contradicts the information","meaning":"與資料矛盾","examples":[{"en":"Students write FALSE if the statement contradicts the information.","zh":"如果陳述與資料矛盾，學生寫 FALSE。"},{"en":"Contradicts the information means says the opposite of what the passage says.","zh":"contradicts the information 指說出與文章相反的內容。"},{"en":"If the passage says PE time fell and a statement says it increased, the statement contradicts the information.","zh":"如果文章說體育課時間下降，而陳述說增加，就與資料矛盾。"},{"en":"A contradiction is different from missing information because the text clearly disagrees.","zh":"矛盾不同於沒有資料，因為文本清楚不同意。"},{"en":"This phrase helps students identify FALSE answers.","zh":"這個短語幫助學生辨認 FALSE 答案。"}],"source":"34 - Activities for Children.pdf","sourcePage":15},{"front":"no information on this","meaning":"沒有這方面的資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有這方面的資料，學生寫 NOT GIVEN。"},{"en":"No information on this means the passage does not say whether the statement is true or false.","zh":"no information on this 指文章沒有說明該陳述是真還是假。"},{"en":"If the passage discusses exercise but not children’s favourite sports, there is no information on that.","zh":"如果文章討論運動但沒有談兒童最喜歡的運動，就沒有這方面的資料。"},{"en":"Students should not use outside knowledge when the text gives no evidence.","zh":"當文本沒有證據時，學生不應使用外部知識。"},{"en":"This phrase is essential for NOT GIVEN questions.","zh":"這個短語對 NOT GIVEN 題很重要。"}],"source":"34 - Activities for Children.pdf","sourcePage":16},{"front":"according to","meaning":"根據……","examples":[{"en":"Students judge the statement according to information in the passage.","zh":"學生根據文章資料判斷陳述。"},{"en":"According to means based on a source, rule, or piece of information.","zh":"according to 指基於某來源、規則或資料。"},{"en":"According to the timetable, the PE lesson starts after lunch.","zh":"根據時間表，體育課在午飯後開始。"},{"en":"This phrase tells readers where the answer or judgement should come from.","zh":"這個短語告訴讀者答案或判斷應來自哪裏。"},{"en":"It is common in exams, reports, and explanations.","zh":"它常見於考試、報告和解釋。"}],"source":"34 - Activities for Children.pdf","sourcePage":16},{"front":"have higher cholesterol levels than","meaning":"膽固醇水平比……高","examples":[{"en":"The statement asks whether boys have higher cholesterol levels than girls.","zh":"這個陳述問男孩的膽固醇水平是否比女孩高。"},{"en":"Have higher cholesterol levels than means have more cholesterol in the blood compared with another group.","zh":"have higher cholesterol levels than 指與另一群體相比，血液中膽固醇較多。"},{"en":"Adults with poor diets may have higher cholesterol levels than those who eat balanced meals.","zh":"飲食差的成年人可能比飲食均衡的人膽固醇水平更高。"},{"en":"Comparing levels helps doctors or researchers identify which group may face greater risk.","zh":"比較水平幫助醫生或研究人員找出哪個群體可能風險較高。"},{"en":"This phrase is useful in health comparisons.","zh":"這個短語適用於健康比較。"}],"source":"34 - Activities for Children.pdf","sourcePage":16},{"front":"generally do less exercise than","meaning":"一般比……做較少運動","examples":[{"en":"British children generally do less exercise than children in some other countries.","zh":"英國兒童一般比某些其他國家的兒童做較少運動。"},{"en":"Generally do less exercise than means usually have a lower amount of physical activity compared with another group.","zh":"generally do less exercise than 指通常比另一群體有較少體能活動。"},{"en":"Office workers may generally do less exercise than people with outdoor jobs.","zh":"辦公室員工一般可能比戶外工作者做較少運動。"},{"en":"Less exercise can affect fitness if the pattern continues over time.","zh":"如果這種模式持續，較少運動會影響體能。"},{"en":"This phrase is useful when comparing activity levels.","zh":"比較活動水平時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":16},{"front":"increasingly popular","meaning":"越來越受歡迎","examples":[{"en":"The statement asks whether skipping is becoming increasingly popular in UK schools.","zh":"這個陳述問跳繩是否在英國學校越來越受歡迎。"},{"en":"Increasingly popular means becoming more liked or more widely used over time.","zh":"increasingly popular 指隨時間變得更受喜愛或更廣泛使用。"},{"en":"Online learning became increasingly popular when students needed to study from home.","zh":"當學生需要在家學習時，網上學習變得越來越受歡迎。"},{"en":"When an activity becomes more popular, more people join or talk about it.","zh":"當一項活動越來越受歡迎，更多人會加入或談論它。"},{"en":"This phrase is useful when describing a growing trend.","zh":"描述增長趨勢時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":16},{"front":"parents’ first task","meaning":"家長的首要任務","examples":[{"en":"The statement refers to parents’ first task in helping children.","zh":"這個陳述提到家長幫助子女時的首要任務。"},{"en":"Parents’ first task means the first thing parents should do in a situation.","zh":"parents’ first task 指家長在某情況下應先做的第一件事。"},{"en":"Parents’ first task in building good sleep habits may be setting a regular bedtime.","zh":"家長建立良好睡眠習慣的首要任務可能是設定固定睡覺時間。"},{"en":"Starting with the right first task can make later changes easier.","zh":"從正確首要任務開始，可以令之後改變更容易。"},{"en":"This phrase is useful when discussing priorities for parents.","zh":"討論家長優先事項時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":16},{"front":"encourage their children to","meaning":"鼓勵子女去……","examples":[{"en":"Parents may encourage their children to maintain a healthy body weight.","zh":"家長可能鼓勵子女維持健康體重。"},{"en":"To encourage their children to do something means to support or persuade children to do it.","zh":"encourage their children to do something 指支持或勸導子女做某事。"},{"en":"Parents can encourage their children to walk more by walking with them.","zh":"家長可以透過與子女一起步行，鼓勵子女多走路。"},{"en":"Encouragement works better when adults model the behaviour themselves.","zh":"當成人自己示範該行為，鼓勵通常更有效。"},{"en":"This phrase is useful when discussing parental influence.","zh":"討論家長影響時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":16},{"front":"maintain a healthy body weight","meaning":"維持健康體重","examples":[{"en":"Parents can help children maintain a healthy body weight.","zh":"家長可以幫助兒童維持健康體重。"},{"en":"To maintain a healthy body weight means to keep weight within a healthy range for one’s body.","zh":"maintain a healthy body weight 指把體重保持在適合自己身體的健康範圍。"},{"en":"Children can maintain a healthy body weight through movement, sleep, and balanced meals.","zh":"兒童可以透過活動、睡眠和均衡飲食維持健康體重。"},{"en":"Healthy habits are easier to keep when the whole family follows them.","zh":"當全家一起遵循健康習慣，這些習慣較容易維持。"},{"en":"This phrase is common in nutrition and health education.","zh":"這個短語常見於營養和健康教育。"}],"source":"34 - Activities for Children.pdf","sourcePage":16},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter from the answer options.","zh":"學生從答案選項中選出正確字母。"},{"en":"Choose the correct letter means select the option letter that matches the answer.","zh":"choose the correct letter 指選出與答案相符的選項字母。"},{"en":"In a multiple-choice question, students may choose A, B, C, or D.","zh":"在多項選擇題中，學生可能選 A、B、C 或 D。"},{"en":"Understanding the text is not enough if the wrong letter is written.","zh":"如果寫錯字母，即使理解文本也不夠。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"34 - Activities for Children.pdf","sourcePage":16},{"front":"what concerns","meaning":"令……擔心的是甚麼","examples":[{"en":"The question asks what concerns Professor Neil Armstrong.","zh":"題目問令 Neil Armstrong 教授擔心的是甚麼。"},{"en":"What concerns someone means what worries or troubles that person.","zh":"what concerns someone 指令某人擔心或困擾的是甚麼。"},{"en":"A teacher may ask what concerns parents most about online learning.","zh":"老師可能問家長最擔心網上學習的甚麼。"},{"en":"Identifying the concern helps readers understand the main problem.","zh":"找出擔憂有助讀者理解主要問題。"},{"en":"This phrase is useful in comprehension questions and discussion.","zh":"這個短語適用於理解題和討論。"}],"source":"34 - Activities for Children.pdf","sourcePage":16},{"front":"harms children’s academic performance","meaning":"損害兒童學業表現","examples":[{"en":"The option says watching television harms children’s academic performance.","zh":"這個選項說看電視損害兒童學業表現。"},{"en":"Harms children’s academic performance means damages how well children do in schoolwork or exams.","zh":"harms children’s academic performance 指損害兒童在功課或考試中的表現。"},{"en":"Too little sleep can harm children’s academic performance by reducing concentration.","zh":"睡眠不足可以透過降低專注力損害兒童學業表現。"},{"en":"If a habit affects learning time or focus, it may damage school results.","zh":"如果習慣影響學習時間或專注，它可能損害學校成績。"},{"en":"This phrase is useful when discussing education outcomes.","zh":"討論教育成果時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":16},{"front":"academic performance","meaning":"學業表現","examples":[{"en":"Too much screen time may affect academic performance.","zh":"太多螢幕時間可能影響學業表現。"},{"en":"Academic performance means how well a student does in school subjects, tests, homework, or learning tasks.","zh":"academic performance 指學生在學科、測驗、功課或學習任務中的表現。"},{"en":"Teachers may look at academic performance through marks, essays, and class participation.","zh":"老師可能透過分數、文章和課堂參與查看學業表現。"},{"en":"Health, sleep, motivation, and study habits can all affect academic performance.","zh":"健康、睡眠、動機和學習習慣都可以影響學業表現。"},{"en":"This phrase is common in education.","zh":"這個短語常見於教育。"}],"source":"34 - Activities for Children.pdf","sourcePage":17},{"front":"less time to spend with","meaning":"較少時間陪伴……","examples":[{"en":"The option says parents have less time to spend with their children.","zh":"這個選項說家長有較少時間陪伴子女。"},{"en":"Less time to spend with someone means fewer hours available to be with that person.","zh":"less time to spend with someone 指可與某人相處的時間較少。"},{"en":"A busy parent may have less time to spend with children during weekdays.","zh":"忙碌家長在平日可能有較少時間陪伴子女。"},{"en":"Less family time can reduce shared exercise, conversation, and support.","zh":"較少家庭時間可以減少共同運動、對話和支援。"},{"en":"This phrase is useful when discussing work-life balance.","zh":"討論工作與生活平衡時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":17},{"front":"future health","meaning":"未來健康","examples":[{"en":"Professor Armstrong is concerned about children’s future health.","zh":"Armstrong 教授關注兒童的未來健康。"},{"en":"Future health means a person’s health later in life.","zh":"future health 指一個人日後的健康。"},{"en":"Childhood exercise habits can affect future health in adulthood.","zh":"童年的運動習慣可以影響成年後的未來健康。"},{"en":"Small unhealthy habits now may create larger health problems later.","zh":"現在的小小不健康習慣，之後可能造成較大健康問題。"},{"en":"This phrase is useful when discussing long-term consequences.","zh":"討論長遠後果時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":17},{"front":"increasing pace of","meaning":"……步伐加快","examples":[{"en":"The option refers to the increasing pace of property development.","zh":"這個選項提到物業發展步伐加快。"},{"en":"Increasing pace of something means the speed of it is becoming faster.","zh":"increasing pace of something 指某事速度變得更快。"},{"en":"The increasing pace of city building may reduce green space.","zh":"城市建設步伐加快可能減少綠色空間。"},{"en":"Faster development can create pressure before communities can plan properly.","zh":"更快發展可以在社區妥善規劃前造成壓力。"},{"en":"This phrase is useful when describing accelerating change.","zh":"描述加速變化時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":17},{"front":"property development","meaning":"物業發展；地產發展","examples":[{"en":"Community playing fields may be sold for property development.","zh":"社區運動場可能被出售作物業發展。"},{"en":"Property development means building or improving land for houses, shops, offices, or other property uses.","zh":"property development 指為住宅、商店、辦公室或其他物業用途而建設或改善土地。"},{"en":"An old car park may be cleared for property development.","zh":"舊停車場可能被清拆作地產發展。"},{"en":"Development can bring housing and business, but it may reduce public open space.","zh":"發展可以帶來住屋和商業，但可能減少公共開放空間。"},{"en":"This phrase is common in urban planning and land-use discussion.","zh":"這個短語常見於城市規劃和土地使用討論。"}],"source":"34 - Activities for Children.pdf","sourcePage":17},{"front":"make a point","meaning":"提出一點","examples":[{"en":"Armstrong makes a point about children’s need for exercise.","zh":"Armstrong 提出關於兒童需要運動的一點。"},{"en":"To make a point means to express an important idea or argument.","zh":"make a point 指表達一個重要想法或論點。"},{"en":"A teacher may make a point about sleeping early before exams.","zh":"老師可能提出考試前早睡的重要一點。"},{"en":"A clear point helps listeners understand why the topic matters.","zh":"清楚重點幫助聽眾理解主題為何重要。"},{"en":"This phrase is useful in speaking, writing, and argument.","zh":"這個短語適用於說話、寫作和論證。"}],"source":"34 - Activities for Children.pdf","sourcePage":17},{"front":"be more active","meaning":"更活躍","examples":[{"en":"Children should be more active to exercise the heart.","zh":"兒童應更活躍，以鍛煉心臟。"},{"en":"To be more active means to move more and spend less time sitting still.","zh":"be more active 指更多活動，較少靜坐。"},{"en":"A child can be more active by walking to school, playing outside, or joining a dance class.","zh":"兒童可以透過步行上學、戶外玩耍或參加舞蹈班變得更活躍。"},{"en":"More activity helps the body use energy and build fitness.","zh":"更多活動幫助身體使用能量並建立體能。"},{"en":"This phrase is useful in health advice.","zh":"這個短語適用於健康建議。"}],"source":"34 - Activities for Children.pdf","sourcePage":17},{"front":"exercise the heart","meaning":"鍛煉心臟","examples":[{"en":"Children should be active to exercise the heart.","zh":"兒童應該活躍，以鍛煉心臟。"},{"en":"To exercise the heart means to make the heart work harder through physical activity so it stays strong.","zh":"exercise the heart 指透過體能活動令心臟更努力工作，使它保持強壯。"},{"en":"Running, swimming, and fast walking can exercise the heart.","zh":"跑步、游泳和快步行都可以鍛煉心臟。"},{"en":"The heart becomes stronger when it is regularly challenged safely.","zh":"心臟在安全且定期受到挑戰時會變得更強。"},{"en":"This phrase explains why movement matters for cardiovascular health.","zh":"這個短語解釋為何活動對心血管健康重要。"}],"source":"34 - Activities for Children.pdf","sourcePage":17},{"front":"in a better situation than","meaning":"處境比……好","examples":[{"en":"The option suggests girls are in a better situation than boys.","zh":"這個選項暗示女孩處境比男孩好。"},{"en":"In a better situation than means having more favourable conditions or fewer problems than another group.","zh":"in a better situation than 指比另一群體有更有利條件或較少問題。"},{"en":"Students with safe parks nearby may be in a better situation than those without outdoor space.","zh":"附近有安全公園的學生，處境可能比沒有戶外空間的學生好。"},{"en":"Comparing situations helps identify which group may need more support.","zh":"比較處境有助找出哪個群體可能需要更多支援。"},{"en":"This phrase is useful when discussing relative advantage.","zh":"討論相對優勢時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":17},{"front":"cure many diseases","meaning":"治癒多種疾病","examples":[{"en":"The option says exercise can cure many diseases.","zh":"這個選項說運動可以治癒多種疾病。"},{"en":"To cure many diseases means to make many illnesses go away completely.","zh":"cure many diseases 指令許多疾病完全消失。"},{"en":"Medicine can cure some infections, but not every condition has a simple cure.","zh":"藥物可以治癒某些感染，但不是每種狀況都有簡單治癒方法。"},{"en":"Exercise can reduce some risks, but it should not be described as curing every disease.","zh":"運動可以降低某些風險，但不應被描述為治癒所有疾病。"},{"en":"This phrase is useful when distinguishing treatment, prevention, and cure.","zh":"區分治療、預防和治癒時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":17},{"front":"aim of","meaning":"……的目的","examples":[{"en":"The question asks about the aim of Fit Kids training.","zh":"題目問 Fit Kids 培訓的目的。"},{"en":"The aim of something is its purpose or goal.","zh":"aim of something 指某事的目的或目標。"},{"en":"The aim of a reading lesson may be to help students find main ideas faster.","zh":"閱讀課的目的可能是幫助學生更快找出主旨。"},{"en":"Knowing the aim helps people judge whether an activity is successful.","zh":"知道目的有助人判斷活動是否成功。"},{"en":"This phrase is useful in questions about purpose.","zh":"這個短語適用於目的題。"}],"source":"34 - Activities for Children.pdf","sourcePage":17},{"front":"make a profit","meaning":"賺取利潤","examples":[{"en":"The option says the aim is to make a profit.","zh":"這個選項說目的在於賺取利潤。"},{"en":"To make a profit means to earn more money than is spent.","zh":"make a profit 指賺到比支出更多的金錢。"},{"en":"A small shop makes a profit if sales are higher than rent, wages, and stock costs.","zh":"如果小店銷售額高於租金、工資和存貨成本，就能賺取利潤。"},{"en":"Profit can help a business continue, but it may not be the main aim of every programme.","zh":"利潤可以幫助企業持續，但未必是每個計劃的主要目的。"},{"en":"This phrase is common in business contexts.","zh":"這個短語常見於商業語境。"}],"source":"34 - Activities for Children.pdf","sourcePage":18},{"front":"running several sessions","meaning":"舉辦多節課堂","examples":[{"en":"The option refers to running several exercise sessions.","zh":"這個選項提到舉辦多節運動課堂。"},{"en":"Running several sessions means organising and leading several classes, meetings, or activities.","zh":"running several sessions 指組織並帶領幾節課、會議或活動。"},{"en":"A sports coach may be responsible for running several sessions each week.","zh":"運動教練可能負責每週舉辦多節課堂。"},{"en":"More sessions can give children repeated chances to practise and improve.","zh":"更多課節可以給兒童反覆練習和進步的機會。"},{"en":"This phrase is useful when describing organised activities.","zh":"描述有組織活動時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":18},{"front":"focus on only one activity","meaning":"只集中於一項活動","examples":[{"en":"The option says the programme focuses on only one activity for each child.","zh":"這個選項說該課程為每名兒童只集中於一項活動。"},{"en":"To focus on only one activity means to give attention to one activity and exclude others.","zh":"focus on only one activity 指只把注意力放在一項活動上，排除其他活動。"},{"en":"A child may lose interest if PE focuses on only one activity all term.","zh":"如果體育課整個學期只集中於一項活動，孩子可能失去興趣。"},{"en":"Offering only one activity can reduce choice and exclude children with different strengths.","zh":"只提供一項活動可以減少選擇，並排除有不同強項的兒童。"},{"en":"This phrase is useful when criticising narrow programmes.","zh":"批評狹窄課程時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":18},{"front":"teach parents how to organise","meaning":"教家長如何組織","examples":[{"en":"Fit Kids teaches parents how to organise fitness activities.","zh":"Fit Kids 教家長如何組織健體活動。"},{"en":"To teach parents how to organise something means to show them how to plan and run it.","zh":"teach parents how to organise something 指教家長如何規劃和舉辦某事。"},{"en":"A school may teach parents how to organise reading games at home.","zh":"學校可能教家長如何在家中組織閱讀遊戲。"},{"en":"When parents learn how to organise activities, support continues outside class.","zh":"當家長學會如何組織活動，支援就能延續到課堂以外。"},{"en":"This phrase is useful when adults are trained to help children.","zh":"當成人接受培訓去幫助兒童時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":18},{"front":"organise fitness activities","meaning":"組織健體活動","examples":[{"en":"Parents can learn to organise fitness activities for children.","zh":"家長可以學習為兒童組織健體活動。"},{"en":"To organise fitness activities means to plan and arrange exercises or movement-based games.","zh":"organise fitness activities 指規劃和安排運動或以活動為本的遊戲。"},{"en":"A parent may organise fitness activities such as skipping, dancing, and ball games.","zh":"家長可能組織跳繩、跳舞和球類遊戲等健體活動。"},{"en":"Well-organised activities make exercise safer and more enjoyable for children.","zh":"組織良好的活動令兒童運動更安全、更愉快。"},{"en":"This phrase is useful when discussing practical ways to promote movement.","zh":"討論推動活動量的實用方法時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":18},{"front":"promote team sport as","meaning":"將團隊運動推廣為……","examples":[{"en":"The option says the programme promotes team sport as the best exercise.","zh":"這個選項說該課程將團隊運動推廣為最佳運動。"},{"en":"To promote team sport as something means to present it as that thing and encourage people to choose it.","zh":"promote team sport as something 指把團隊運動呈現為某事，並鼓勵人選擇它。"},{"en":"A school may promote swimming as a safe lifelong exercise.","zh":"學校可能把游泳推廣為安全的終身運動。"},{"en":"Promoting one kind of sport too strongly may ignore children who prefer other activities.","zh":"過度推廣一種運動可能忽略喜歡其他活動的兒童。"},{"en":"This phrase is useful when discussing how programmes recommend activities.","zh":"討論課程如何推薦活動時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":18},{"front":"best form of exercise","meaning":"最佳運動形式","examples":[{"en":"The option describes team sport as the best form of exercise.","zh":"這個選項把團隊運動描述為最佳運動形式。"},{"en":"The best form of exercise means the most suitable or effective kind of physical activity.","zh":"best form of exercise 指最合適或最有效的體能活動種類。"},{"en":"For one child, the best form of exercise may be swimming; for another, it may be dancing.","zh":"對一名孩子來說，最佳運動形式可能是游泳；對另一個孩子則可能是跳舞。"},{"en":"The best exercise is often the one a person can enjoy and continue safely.","zh":"最好的運動通常是人能享受並安全持續的運動。"},{"en":"This phrase is useful when comparing exercise choices.","zh":"比較運動選擇時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":18},{"front":"suggest at the end of","meaning":"在……結尾建議","examples":[{"en":"The question asks what Lifshitz suggests at the end of the passage.","zh":"題目問 Lifshitz 在文章結尾建議甚麼。"},{"en":"Suggest at the end of something means give advice or an idea in the final part.","zh":"suggest at the end of something 指在最後部分提出建議或想法。"},{"en":"An author may suggest at the end of an article that families make small daily changes.","zh":"作者可能在文章結尾建議家庭作出小小日常改變。"},{"en":"The ending often contains recommendations after the problem has been explained.","zh":"結尾通常在問題被解釋後包含建議。"},{"en":"This phrase is useful in reading comprehension questions.","zh":"這個短語適用於閱讀理解題。"}],"source":"34 - Activities for Children.pdf","sourcePage":18},{"front":"create more opportunities for","meaning":"創造更多……機會","examples":[{"en":"Lifshitz suggests creating more opportunities for physical activity.","zh":"Lifshitz 建議創造更多體能活動機會。"},{"en":"To create more opportunities for something means to make more chances for it to happen.","zh":"create more opportunities for something 指製造更多機會讓某事發生。"},{"en":"Schools can create more opportunities for exercise by opening playgrounds after class.","zh":"學校可以透過放學後開放操場，創造更多運動機會。"},{"en":"More opportunities make healthy behaviour easier to repeat.","zh":"更多機會令健康行為更容易重複。"},{"en":"This phrase is useful when discussing practical solutions.","zh":"討論實用解決方案時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":18},{"front":"save time","meaning":"節省時間","examples":[{"en":"The option says people should take the lift to save time.","zh":"這個選項說人們應乘升降機以節省時間。"},{"en":"To save time means to use less time than another method would require.","zh":"save time 指比另一方法使用較少時間。"},{"en":"Taking a bus may save time compared with walking across town.","zh":"與步行穿過城市相比，乘巴士可能節省時間。"},{"en":"Saving time can be useful, but it may reduce opportunities for movement.","zh":"節省時間可以有用，但可能減少活動機會。"},{"en":"This phrase is useful when comparing convenience and health.","zh":"比較方便和健康時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":18},{"front":"expend more than","meaning":"消耗超過……","examples":[{"en":"The option says children should expend more than 200 calories every day.","zh":"這個選項說兒童每天應消耗超過200卡路里。"},{"en":"Expend more than means use a greater amount of energy, money, or effort than a stated number.","zh":"expend more than 指使用比指定數字更多的能量、金錢或努力。"},{"en":"A runner may expend more than 300 calories during a long training session.","zh":"跑步者在長時間訓練中可能消耗超過300卡路里。"},{"en":"More energy expenditure usually requires more movement or harder activity.","zh":"更多能量消耗通常需要更多活動或更高強度活動。"},{"en":"This phrase is useful when discussing energy use.","zh":"討論能量使用時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":18},{"front":"always walk rather than drive","meaning":"總是步行而不是駕車","examples":[{"en":"The option says people should always walk rather than drive.","zh":"這個選項說人們應總是步行而不是駕車。"},{"en":"Always walk rather than drive means choose walking every time instead of using a car.","zh":"always walk rather than drive 指每次都選擇步行，而不用汽車。"},{"en":"A family might walk rather than drive for short trips, but not necessarily for long journeys.","zh":"家庭短途可能步行而不是駕車，但長途未必如此。"},{"en":"The word always makes the advice very strict and may not fit every situation.","zh":"always 令建議非常絕對，可能不適合每種情況。"},{"en":"This phrase is useful when judging whether an option is too absolute.","zh":"判斷選項是否過於絕對時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":19},{"front":"main idea of the passage","meaning":"文章主旨","examples":[{"en":"The question asks for the main idea of the passage.","zh":"題目要求找出文章主旨。"},{"en":"The main idea of the passage is the most important message or overall point of the text.","zh":"main idea of the passage 指文章最重要訊息或整體重點。"},{"en":"Students should identify the main idea before focusing on small details.","zh":"學生應先找出主旨，再聚焦小細節。"},{"en":"Understanding the main idea helps readers answer summary and title questions.","zh":"理解主旨幫助讀者回答摘要和標題題。"},{"en":"This phrase is common in reading comprehension.","zh":"這個短語常見於閱讀理解。"}],"source":"34 - Activities for Children.pdf","sourcePage":19},{"front":"overweight children","meaning":"超重兒童","examples":[{"en":"Overweight children may face future health risks.","zh":"超重兒童可能面對未來健康風險。"},{"en":"Overweight children are children whose body weight is above a healthy range for their age and body size.","zh":"overweight children 指體重高於其年齡和體型健康範圍的兒童。"},{"en":"Doctors may advise overweight children to increase activity and improve eating habits.","zh":"醫生可能建議超重兒童增加活動並改善飲食習慣。"},{"en":"Extra weight in childhood can sometimes continue into adulthood if habits do not change.","zh":"如果習慣不改變，童年時的額外體重有時會延續到成年。"},{"en":"This phrase is common in child health discussions.","zh":"這個短語常見於兒童健康討論。"}],"source":"34 - Activities for Children.pdf","sourcePage":19},{"front":"face future health risks","meaning":"面對未來健康風險","examples":[{"en":"Inactive children may face future health risks.","zh":"不活躍兒童可能面對未來健康風險。"},{"en":"To face future health risks means to be likely to have health problems later in life.","zh":"face future health risks 指日後較可能出現健康問題。"},{"en":"Children who rarely move may face future health risks linked to weight and heart fitness.","zh":"很少活動的兒童可能面對與體重和心臟體能有關的未來健康風險。"},{"en":"Early prevention can reduce risks before they become serious.","zh":"早期預防可以在風險變嚴重前減低它們。"},{"en":"This phrase is useful when discussing long-term health consequences.","zh":"討論長遠健康後果時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":19},{"front":"appropriate forms of exercise","meaning":"合適的運動形式","examples":[{"en":"Children need appropriate forms of exercise.","zh":"兒童需要合適的運動形式。"},{"en":"Appropriate forms of exercise are types of physical activity suitable for a person’s age, ability, interests, and health.","zh":"appropriate forms of exercise 指適合某人年齡、能力、興趣和健康狀況的體能活動類型。"},{"en":"For young children, games and dancing may be more appropriate forms of exercise than strict training.","zh":"對幼童來說，遊戲和跳舞可能比嚴格訓練更合適。"},{"en":"Suitable exercise makes children more likely to join and continue.","zh":"合適運動令兒童較可能參與並持續。"},{"en":"This phrase is useful when discussing personalised or balanced fitness.","zh":"討論個人化或平衡健體時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":19},{"front":"wrong approach to","meaning":"對……採取錯誤方法","examples":[{"en":"The option says the government has taken the wrong approach to children’s activity.","zh":"這個選項說政府對兒童活動採取錯誤方法。"},{"en":"A wrong approach to something is a method that does not solve the problem well.","zh":"wrong approach to something 指不能有效解決問題的方法。"},{"en":"Giving children more lectures about fitness may be the wrong approach if they need safe places to play.","zh":"如果兒童需要安全地方玩耍，只給他們更多健康講座可能是錯誤方法。"},{"en":"The wrong approach can waste money and fail to change behaviour.","zh":"錯誤方法可以浪費金錢並未能改變行為。"},{"en":"This phrase is useful when criticising policy or planning.","zh":"批評政策或規劃時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":19},{"front":"play the most important role","meaning":"扮演最重要角色","examples":[{"en":"The option says parents play the most important role in children’s activity.","zh":"這個選項說家長在兒童活動中扮演最重要角色。"},{"en":"To play the most important role means to be the main factor or have the greatest influence.","zh":"play the most important role 指成為主要因素或有最大影響力。"},{"en":"Parents may play the most important role in children’s eating habits because they choose food at home.","zh":"家長可能在兒童飲食習慣中扮演最重要角色，因為他們選擇家中食物。"},{"en":"When adults model active behaviour, children may follow more naturally.","zh":"當成人示範活躍行為，兒童可能更自然跟隨。"},{"en":"This phrase is useful when identifying the strongest influence.","zh":"指出最強影響因素時，這個短語很有用。"}],"source":"34 - Activities for Children.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 35":[{"front":"Life-Casting and Art","meaning":"生活鑄模與藝術","examples":[{"en":"The passage Life-Casting and Art explores whether plaster moulds can be considered art.","zh":"文章《生活鑄模與藝術》探討石膏模是否可以被視為藝術。"},{"en":"Life-Casting and Art is about the question of whether moulds taken directly from real bodies or objects can be viewed as artistic works.","zh":"Life-Casting and Art 是關於直接從真實身體或物件製成的鑄模是否可被視為藝術作品的問題。"},{"en":"In an art lesson, students may discuss Life-Casting and Art to decide whether copying real life can still involve creativity.","zh":"在藝術課中，學生可能討論《生活鑄模與藝術》，以判斷複製真實生活是否仍可涉及創意。"},{"en":"If an object was first made for science but later admired in a gallery, Life-Casting and Art becomes a useful topic.","zh":"如果一件物件最初為科學而製作，但後來在畫廊中被欣賞，Life-Casting and Art 就成為有用主題。"},{"en":"The title suggests a debate between technical copying and artistic value.","zh":"這個標題暗示技術性複製與藝術價值之間的辯論。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":1},{"front":"explore the questions posed by","meaning":"探討由……提出的問題","examples":[{"en":"Julian Barnes explores the questions posed by an exhibition of life-casts.","zh":"Julian Barnes 探討由一個生活鑄模展覽提出的問題。"},{"en":"Explore the questions posed by means examine the issues or doubts raised by something.","zh":"explore the questions posed by 指檢視某事引起的議題或疑問。"},{"en":"A teacher may explore the questions posed by online learning, such as fairness and attention.","zh":"老師可能探討由網上學習提出的問題，例如公平性和專注力。"},{"en":"If an exhibition challenges old ideas, critics may explore the questions it raises about art.","zh":"如果展覽挑戰舊觀念，評論家可能探討它對藝術提出的問題。"},{"en":"The phrase is useful when one event makes people think about bigger issues.","zh":"這個片語適合用於某事件令人思考更大議題時。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":1},{"front":"Life-Casts","meaning":"《生活鑄模》展覽","examples":[{"en":"Life-Casts was an exhibition of plaster moulds of living people and objects.","zh":"《生活鑄模》是一個展示活人和物件石膏模的展覽。"},{"en":"Life-Casts refers to a show displaying casts made directly from real people or real objects.","zh":"Life-Casts 指一個展示直接從真人或真實物件製成鑄模的展覽。"},{"en":"A museum visitor might expect Life-Casts to include hands, faces, bodies, or everyday objects captured in plaster.","zh":"博物館參觀者可能預期《生活鑄模》包括以石膏捕捉的手、臉、身體或日常物件。"},{"en":"Because the works were copied from life, the exhibition raises questions about realism and creativity.","zh":"因為這些作品直接從生活複製而來，該展覽引出關於寫實和創意的問題。"},{"en":"The name points to objects made by casting life directly rather than imagining it freely.","zh":"這個名稱指直接鑄造生活，而不是自由想像生活的物件。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":1},{"front":"an exhibition of","meaning":"……的展覽","examples":[{"en":"Life-Casts was an exhibition of plaster moulds.","zh":"《生活鑄模》是一個石膏模的展覽。"},{"en":"An exhibition of something is a public display of that type of object or work.","zh":"an exhibition of something 指公開展示某類物件或作品的展覽。"},{"en":"A school may hold an exhibition of student paintings at the end of the year.","zh":"學校可能在年終舉辦學生畫作的展覽。"},{"en":"If a museum holds an exhibition of old tools, visitors can see how people worked in the past.","zh":"如果博物館舉辦舊工具展覽，訪客可以看見過去人們如何工作。"},{"en":"The phrase tells us what kind of items are being shown.","zh":"這個片語告訴我們正在展示的是哪一類物品。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":1},{"front":"plaster moulds","meaning":"石膏模","examples":[{"en":"The exhibition displayed plaster moulds of living people and objects.","zh":"展覽展示了活人和物件的石膏模。"},{"en":"Plaster moulds are shaped forms made with plaster, often by taking an impression from a real object or body.","zh":"plaster moulds 指用石膏製成的形狀，通常是從真實物件或身體取得印模。"},{"en":"A dentist may use a plaster mould to show the shape of a patient’s teeth.","zh":"牙醫可能使用石膏模顯示病人牙齒的形狀。"},{"en":"If plaster is poured over or around something, it can harden and preserve its shape.","zh":"如果石膏倒在某物上或其周圍，它會變硬並保存其形狀。"},{"en":"The phrase refers to a physical copy, not a painted or imagined image.","zh":"這個片語指實體複製品，而不是繪畫或想像圖像。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":1},{"front":"living people and objects","meaning":"活人和物件","examples":[{"en":"The moulds were made from living people and objects.","zh":"這些模是由活人和物件製成的。"},{"en":"Living people and objects means real bodies or real things used directly as the source for a cast.","zh":"living people and objects 指真人身體或真實物件被直接用作鑄模來源。"},{"en":"An artist might make casts from a person’s hand, a chair, or a piece of clothing.","zh":"藝術家可能從人的手、椅子或衣物製作鑄模。"},{"en":"If a mould is made from a living person, safety and comfort become important.","zh":"如果鑄模從活人身上製作，安全和舒適就變得重要。"},{"en":"The phrase stresses that the casts came from real life, not from imagination.","zh":"這個片語強調鑄模來自真實生活，而不是想像。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":1},{"front":"originally used for","meaning":"原本用於","examples":[{"en":"The moulds were originally used for scientific purposes.","zh":"這些模原本用於科學用途。"},{"en":"Originally used for means first used for a particular purpose before later uses appeared.","zh":"originally used for 指在後來用途出現前，最初被用於某特定目的。"},{"en":"A classroom building may have been originally used for offices before the school moved in.","zh":"一棟課室大樓在學校搬入前可能原本用於辦公室。"},{"en":"If an object is originally used for science, later viewers may still reinterpret it as art.","zh":"如果物件原本用於科學，後來的觀眾仍可能把它重新詮釋為藝術。"},{"en":"The phrase points to the first function of something.","zh":"這個片語指出某物最初的功能。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":1},{"front":"scientific purposes","meaning":"科學用途","examples":[{"en":"The life-casts were originally used for scientific purposes.","zh":"生活鑄模原本用於科學用途。"},{"en":"Scientific purposes are uses connected with research, measurement, observation, or study.","zh":"scientific purposes 指與研究、量度、觀察或學習有關的用途。"},{"en":"A hospital may collect samples for scientific purposes, such as testing a new treatment.","zh":"醫院可能為科學用途收集樣本，例如測試新療法。"},{"en":"If a cast is used for scientific purposes, accuracy may matter more than beauty.","zh":"如果鑄模用於科學用途，準確性可能比美感更重要。"},{"en":"The phrase contrasts research use with artistic or decorative use.","zh":"這個片語把研究用途與藝術或裝飾用途作對比。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":1},{"front":"change over time","meaning":"隨時間改變","examples":[{"en":"Art changes over time, and our idea of art changes too.","zh":"藝術會隨時間改變，而我們對藝術的看法也會改變。"},{"en":"Change over time means become different gradually as years or periods pass.","zh":"change over time 指隨着年份或時期過去而逐漸變得不同。"},{"en":"A student’s handwriting may change over time as they practise more.","zh":"學生的字跡可能隨着更多練習而隨時間改變。"},{"en":"If society changes, people’s judgement of old objects may change over time as well.","zh":"如果社會改變，人們對舊物件的判斷也可能隨時間改變。"},{"en":"The phrase describes gradual historical or personal development.","zh":"這個片語描述逐漸的歷史或個人發展。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":1},{"front":"our idea of what art is","meaning":"我們對藝術是甚麼的看法","examples":[{"en":"Our idea of what art is changes over time.","zh":"我們對藝術是甚麼的看法會隨時間改變。"},{"en":"Our idea of what art is means our understanding of what should count as art.","zh":"our idea of what art is 指我們對甚麼應被算作藝術的理解。"},{"en":"A child may think art is only painting, but later include film, design, and photography.","zh":"孩子可能以為藝術只是繪畫，但後來把電影、設計和攝影也包括進去。"},{"en":"If new movements challenge old rules, our idea of art may expand.","zh":"如果新運動挑戰舊規則，我們對藝術的看法可能擴闊。"},{"en":"The phrase refers to a changing definition, not one fixed answer.","zh":"這個片語指正在改變的定義，而不是固定答案。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":1},{"front":"objects originally intended for","meaning":"原本旨在用於……的物件","examples":[{"en":"Objects originally intended for ritual purposes may later be seen as art.","zh":"原本旨在用於儀式用途的物件，後來可能被視為藝術。"},{"en":"Objects originally intended for a purpose are things first made to serve that purpose.","zh":"objects originally intended for a purpose 指最初為服務某用途而製作的物件。"},{"en":"A bowl originally intended for cooking may later be displayed in a museum for its design.","zh":"原本用於烹飪的碗，後來可能因其設計而在博物館展出。"},{"en":"If an object’s old function disappears, later people may judge it by beauty or craftsmanship.","zh":"如果物件的舊功能消失，後來的人可能按美感或工藝來評價它。"},{"en":"The phrase separates first purpose from later interpretation.","zh":"這個片語把最初用途與後來詮釋分開。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":2},{"front":"devotional purposes","meaning":"宗教崇拜用途","examples":[{"en":"Some objects were originally intended for devotional purposes.","zh":"有些物件原本旨在用於宗教崇拜用途。"},{"en":"Devotional purposes are religious uses connected with worship, prayer, or spiritual respect.","zh":"devotional purposes 指與崇拜、祈禱或精神敬意有關的宗教用途。"},{"en":"A small statue in a temple may be made for devotional purposes rather than decoration.","zh":"寺廟中的小雕像可能是為宗教崇拜用途而製作，而不是作裝飾。"},{"en":"If later viewers do not share the original belief, they may still admire the object as art.","zh":"如果後來的觀眾不共享原本信仰，仍可能把該物件作為藝術欣賞。"},{"en":"The phrase points to religious devotion as the object’s original function.","zh":"這個片語指出宗教虔敬是物件的原本功能。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":2},{"front":"ritualistic purposes","meaning":"儀式用途","examples":[{"en":"Some objects were originally intended for ritualistic purposes.","zh":"有些物件原本旨在用於儀式用途。"},{"en":"Ritualistic purposes are uses connected with formal ceremonies or repeated traditional actions.","zh":"ritualistic purposes 指與正式儀式或反覆傳統行動有關的用途。"},{"en":"A mask may be made for ritualistic purposes in a village ceremony.","zh":"面具可能是為村落儀式用途而製作的。"},{"en":"If a ritual object enters a museum, viewers may focus on its shape rather than its ceremony.","zh":"如果儀式物件進入博物館，觀眾可能集中於其形狀，而不是其儀式。"},{"en":"The phrase describes ceremonial function.","zh":"這個片語描述儀式功能。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":2},{"front":"recreational purposes","meaning":"娛樂用途","examples":[{"en":"Some objects were originally intended for recreational purposes.","zh":"有些物件原本旨在用於娛樂用途。"},{"en":"Recreational purposes are uses connected with enjoyment, leisure, play, or entertainment.","zh":"recreational purposes 指與享受、休閒、遊戲或娛樂有關的用途。"},{"en":"A toy boat is made for recreational purposes, not for serious transport.","zh":"玩具船是為娛樂用途而製作，不是為正式運輸。"},{"en":"If a playful object survives for centuries, later people may study it as cultural art.","zh":"如果遊樂性物件保存數百年，後來的人可能把它作為文化藝術研究。"},{"en":"The phrase points to pleasure or leisure as the original use.","zh":"這個片語指出快樂或休閒是原本用途。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":2},{"front":"be recategorised as","meaning":"被重新歸類為","examples":[{"en":"Objects may be recategorised as art by later civilisations.","zh":"物件可能被後來的文明重新歸類為藝術。"},{"en":"Be recategorised as means be placed into a new category or judged as something different.","zh":"be recategorised as 指被放入新類別，或被判斷為不同的東西。"},{"en":"Old factory tools may be recategorised as design objects in a museum.","zh":"舊工廠工具可能在博物館中被重新歸類為設計物件。"},{"en":"If society’s values change, objects once seen as craft may be recategorised as art.","zh":"如果社會價值改變，曾被視為工藝的物件可能被重新歸類為藝術。"},{"en":"The phrase describes a change in classification.","zh":"這個片語描述分類上的改變。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":2},{"front":"later civilisations","meaning":"後來的文明","examples":[{"en":"Later civilisations may view old objects as art.","zh":"後來的文明可能把古老物件視為藝術。"},{"en":"Later civilisations are societies that come after earlier cultures in history.","zh":"later civilisations 指歷史上在較早文化之後出現的社會。"},{"en":"Later civilisations may study ancient tools to understand how people lived.","zh":"後來的文明可能研究古代工具，以了解人們如何生活。"},{"en":"If later civilisations lose the original context of an object, they may interpret it differently.","zh":"如果後來的文明失去物件原本背景，就可能以不同方式詮釋它。"},{"en":"The phrase contrasts later viewers with the people who first made or used the object.","zh":"這個片語把後來的觀者與最初製作或使用物件的人作對比。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":2},{"front":"no longer respond to","meaning":"不再對……有反應；不再認同","examples":[{"en":"Later civilisations may no longer respond to the original purposes of objects.","zh":"後來的文明可能不再對物件原本用途有反應。"},{"en":"No longer respond to means stop feeling, understanding, or reacting to something as people once did.","zh":"no longer respond to 指不再像以前的人那樣感受、理解或回應某事。"},{"en":"Modern students may no longer respond to old teaching methods if they feel distant from daily life.","zh":"如果舊教學方法與日常生活距離太遠，現代學生可能不再對它有反應。"},{"en":"If people no longer respond to a ritual meaning, they may notice the object’s beauty instead.","zh":"如果人們不再對儀式意義有反應，可能轉而注意物件的美。"},{"en":"The phrase describes a loss of original emotional or cultural connection.","zh":"這個片語描述原本情感或文化連結的喪失。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":2},{"front":"these purposes","meaning":"這些用途","examples":[{"en":"Some later civilisations no longer respond to these purposes.","zh":"一些後來的文明不再對這些用途有反應。"},{"en":"These purposes refers to the uses already mentioned, such as ritual, devotional, or recreational uses.","zh":"these purposes 指前面已提到的用途，例如儀式、宗教崇拜或娛樂用途。"},{"en":"If a school changes its rules, students may ask whether these purposes are still useful.","zh":"如果學校改變規則，學生可能問這些用途是否仍有用。"},{"en":"When old purposes fade, objects may gain new meanings.","zh":"當舊用途淡去，物件可能獲得新意義。"},{"en":"The phrase points back to functions discussed earlier.","zh":"這個片語回指前面討論過的功能。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":2},{"front":"techniques and crafts","meaning":"技術和工藝","examples":[{"en":"Techniques and crafts once judged inartistic may later be reassessed.","zh":"曾被判定為非藝術的技術和工藝，後來可能被重新評估。"},{"en":"Techniques and crafts are practical methods and skilled handmade activities.","zh":"techniques and crafts 指實用方法和需要技巧的手工活動。"},{"en":"Pottery, weaving, printing, and casting are examples of crafts that require technique.","zh":"陶藝、編織、印刷和鑄模都是需要技術的工藝例子。"},{"en":"If people later admire the skill involved, old crafts may become valued as art.","zh":"如果後來的人欣賞其中技巧，舊工藝可能被視為藝術。"},{"en":"The phrase joins the method with the skilled work produced by it.","zh":"這個片語把方法與由此產生的技藝工作連接起來。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":2},{"front":"be judged inartistic","meaning":"被判定為非藝術的","examples":[{"en":"Some crafts would have been judged inartistic at the time.","zh":"有些工藝在當時本會被判定為非藝術的。"},{"en":"Be judged inartistic means be considered not to belong to real art.","zh":"be judged inartistic 指被認為不屬於真正藝術。"},{"en":"Early photography was sometimes judged inartistic because people saw it as mechanical copying.","zh":"早期攝影有時被判定為非藝術，因為人們視它為機械複製。"},{"en":"If a craft is judged inartistic, its maker may not receive the status of an artist.","zh":"如果一種工藝被判定為非藝術，其製作者可能得不到藝術家地位。"},{"en":"The phrase reflects a negative judgement about artistic value.","zh":"這個片語反映對藝術價值的負面判斷。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":2},{"front":"at the time they were used","meaning":"在它們被使用的當時","examples":[{"en":"Life-casting was not considered artistic at the time it was used.","zh":"生活鑄模在被使用的當時並不被視為藝術。"},{"en":"At the time they were used means during the period when those objects or methods were actually in use.","zh":"at the time they were used 指那些物件或方法實際被使用的時期。"},{"en":"Old medical tools may not have seemed beautiful at the time they were used.","zh":"舊醫療工具在被使用的當時可能不被視為美麗。"},{"en":"If people later admire an object, that does not mean it was admired when first used.","zh":"如果後來的人欣賞某物，並不代表它最初被使用時也受欣賞。"},{"en":"The phrase separates original context from later judgement.","zh":"這個片語把原本背景與後來判斷分開。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":3},{"front":"be reassessed","meaning":"被重新評估","examples":[{"en":"Old techniques and crafts can be reassessed over time.","zh":"舊技術和工藝可以隨時間被重新評估。"},{"en":"Be reassessed means be judged again, often with a new attitude or new evidence.","zh":"be reassessed 指再次被判斷，通常帶着新態度或新證據。"},{"en":"A student’s old essay may be reassessed after the teacher notices a misunderstanding in the marking.","zh":"如果老師發現批改時有誤解，學生的舊文章可能被重新評估。"},{"en":"If society changes, objects once dismissed may be reassessed as valuable.","zh":"如果社會改變，曾被忽視的物件可能被重新評估為有價值。"},{"en":"The phrase describes a second look or new evaluation.","zh":"這個片語描述重新審視或新評價。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":3},{"front":"an interesting example of","meaning":"……的一個有趣例子","examples":[{"en":"Life-casting is an interesting example of a craft being reassessed.","zh":"生活鑄模是工藝被重新評估的一個有趣例子。"},{"en":"An interesting example of something is a case that helps explain or illustrate an idea clearly.","zh":"an interesting example of 指能清楚解釋或說明某想法的案例。"},{"en":"A school turning an old factory into a library is an interesting example of reuse.","zh":"學校把舊工廠改造成圖書館，是重新利用的一個有趣例子。"},{"en":"If life-casting was once technical but later viewed as art, it illustrates changing values.","zh":"如果生活鑄模曾是技術工作但後來被視為藝術，它就說明價值觀改變。"},{"en":"The phrase introduces a case worth studying.","zh":"這個片語引出值得研究的案例。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":3},{"front":"involve making","meaning":"涉及製作","examples":[{"en":"Life-casting involved making a plaster mould of a living person or thing.","zh":"生活鑄模涉及製作活人或活物的石膏模。"},{"en":"Involve making means include the action or process of creating something.","zh":"involve making 指包括創造某物的行動或過程。"},{"en":"A science project may involve making a model of the solar system.","zh":"科學項目可能涉及製作太陽系模型。"},{"en":"If a craft involves making a mould, technical skill and preparation are needed.","zh":"如果工藝涉及製作模具，就需要技術和準備。"},{"en":"The phrase explains what an activity includes.","zh":"這個片語解釋一項活動包括甚麼。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":3},{"front":"a living person or thing","meaning":"活人或活物","examples":[{"en":"Life-casting involved making a mould of a living person or thing.","zh":"生活鑄模涉及製作活人或活物的模。"},{"en":"A living person or thing means a real living body, animal, plant, or object from life rather than imagination.","zh":"a living person or thing 指真實的活體、動物、植物或生活中的物件，而不是想像出來的東西。"},{"en":"An artist might cast a living person’s hand to preserve its exact shape.","zh":"藝術家可能鑄造活人的手，以保存其準確形狀。"},{"en":"If the subject is living, the casting process must avoid harm or discomfort.","zh":"如果對象是活的，鑄模過程必須避免傷害或不適。"},{"en":"The phrase stresses direct contact with real life.","zh":"這個片語強調與真實生活直接接觸。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":3},{"front":"complex, technical work","meaning":"複雜而技術性高的工作","examples":[{"en":"Life-casting was complex, technical work.","zh":"生活鑄模是複雜而技術性高的工作。"},{"en":"Complex, technical work is work that is difficult and requires special practical knowledge or skill.","zh":"complex, technical work 指困難且需要特殊實用知識或技巧的工作。"},{"en":"Repairing a hospital scanner is complex, technical work because mistakes can affect patients.","zh":"維修醫院掃描器是複雜而技術性高的工作，因為錯誤可能影響病人。"},{"en":"If life-casting required careful materials and timing, it was more than simple copying.","zh":"如果生活鑄模需要小心處理材料和時間，它就不只是簡單複製。"},{"en":"The phrase stresses skill and difficulty.","zh":"這個片語強調技巧和難度。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":3},{"front":"Benjamin Robert Haydon","meaning":"Benjamin Robert Haydon","examples":[{"en":"Benjamin Robert Haydon nearly killed his model with plaster.","zh":"Benjamin Robert Haydon 差點用石膏殺死他的模特兒。"},{"en":"Benjamin Robert Haydon was an artist mentioned as an example of the dangers of life-casting.","zh":"Benjamin Robert Haydon 是文章中用來說明生活鑄模危險性的藝術家例子。"},{"en":"A teacher may mention Benjamin Robert Haydon to show that old artistic techniques could be risky.","zh":"老師可能提到 Benjamin Robert Haydon，以顯示舊藝術技術可能有風險。"},{"en":"If too much plaster is used carelessly, the casting process can become dangerous.","zh":"如果粗心使用過多石膏，鑄模過程可能變得危險。"},{"en":"The name is used in the passage to make the technical risk concrete.","zh":"這個名字在文章中用來具體呈現技術風險。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":3},{"front":"pour plaster over","meaning":"把石膏倒在……上","examples":[{"en":"Haydon poured 250 litres of plaster over his human model.","zh":"Haydon 把250公升石膏倒在他的人體模特兒身上。"},{"en":"Pour plaster over means cover someone or something by letting liquid plaster flow over it.","zh":"pour plaster over 指讓液態石膏流到某人或某物上，把它覆蓋。"},{"en":"A craft worker may pour plaster over a small object to make a mould.","zh":"工藝師可能把石膏倒在小物件上來製作模具。"},{"en":"If plaster is poured over a person carelessly, it may trap heat, block breathing, or cause danger.","zh":"如果粗心把石膏倒在人體上，可能困住熱力、阻礙呼吸或造成危險。"},{"en":"The phrase describes a physical casting action.","zh":"這個片語描述實際鑄模動作。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":3},{"front":"human model","meaning":"人體模特兒","examples":[{"en":"Haydon nearly killed his human model during life-casting.","zh":"Haydon 在生活鑄模期間幾乎殺死他的人體模特兒。"},{"en":"A human model is a person who poses or is used as the subject for an artwork or cast.","zh":"human model 指為藝術品或鑄模擺姿勢或作為對象的人。"},{"en":"In a drawing class, a human model may sit still while students practise sketching.","zh":"在素描課中，人體模特兒可能保持不動，讓學生練習素描。"},{"en":"If a human model is covered in casting material, safety must be carefully managed.","zh":"如果人體模特兒被鑄模材料覆蓋，安全必須被小心管理。"},{"en":"The phrase refers to a real person, not a plastic mannequin.","zh":"這個片語指真人，而不是塑膠人偶。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":3},{"front":"nearly kill someone","meaning":"幾乎殺死某人","examples":[{"en":"The plaster nearly killed Haydon’s human model.","zh":"石膏幾乎殺死 Haydon 的人體模特兒。"},{"en":"Nearly kill someone means almost cause someone to die.","zh":"nearly kill someone 指差點導致某人死亡。"},{"en":"A serious allergic reaction can nearly kill someone if treatment is delayed.","zh":"如果治療延誤，嚴重過敏反應可以幾乎殺死某人。"},{"en":"If a technique nearly kills a model, it shows the process can be dangerous.","zh":"如果某技術幾乎殺死模特兒，就顯示該過程可能危險。"},{"en":"The phrase is strong and describes a life-threatening situation.","zh":"這個片語語氣強烈，描述危及生命的情況。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":3},{"front":"at the time","meaning":"當時","examples":[{"en":"At the time, the casts were used for medical research.","zh":"當時，這些鑄模被用於醫學研究。"},{"en":"At the time means during the particular period being discussed.","zh":"at the time 指在正在討論的特定時期。"},{"en":"At the time, mobile phones were rare, so students used public telephones.","zh":"當時，手機很罕見，所以學生使用公共電話。"},{"en":"If an object had a practical use at the time, later artistic value may not have been considered.","zh":"如果物件在當時有實用用途，後來的藝術價值可能未被考慮。"},{"en":"The phrase fixes a statement in its historical context.","zh":"這個片語把陳述固定在歷史背景中。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":4},{"front":"be used for medical research","meaning":"被用於醫學研究","examples":[{"en":"The casts were used for medical research.","zh":"這些鑄模被用於醫學研究。"},{"en":"Be used for medical research means be used to study health, bodies, disease, or treatment.","zh":"be used for medical research 指被用來研究健康、身體、疾病或治療。"},{"en":"Blood samples may be used for medical research into new medicines.","zh":"血液樣本可能被用於新藥的醫學研究。"},{"en":"If life-casts were used for medical research, accuracy was probably very important.","zh":"如果生活鑄模被用於醫學研究，準確性很可能非常重要。"},{"en":"The phrase describes a scientific purpose connected with medicine.","zh":"這個片語描述與醫學有關的科學用途。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":4},{"front":"consequently","meaning":"因此","examples":[{"en":"Consequently, life-casting was considered inferior to sculpture.","zh":"因此，生活鑄模被視為不如雕塑。"},{"en":"Consequently means as a result of what has just been stated.","zh":"consequently 指作為剛才所述情況的結果。"},{"en":"The road was flooded; consequently, the school bus arrived late.","zh":"道路被水淹；因此校巴遲到。"},{"en":"If life-casting was seen as medical rather than creative, people consequently valued it less as art.","zh":"如果生活鑄模被視為醫學而非創作，人們因此較不把它視為藝術。"},{"en":"The word introduces a logical result.","zh":"這個詞引出邏輯結果。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":4},{"front":"in the nineteenth century","meaning":"在十九世紀","examples":[{"en":"In the nineteenth century, life-casting was considered inferior to sculpture.","zh":"在十九世紀，生活鑄模被視為不如雕塑。"},{"en":"In the nineteenth century means during the years from 1801 to 1900.","zh":"in the nineteenth century 指在1801年至1900年間。"},{"en":"In the nineteenth century, photography began to challenge older ideas about visual art.","zh":"在十九世紀，攝影開始挑戰關於視覺藝術的舊觀念。"},{"en":"If an attitude belonged to the nineteenth century, modern viewers may judge differently now.","zh":"如果某態度屬於十九世紀，現代觀眾現在可能有不同判斷。"},{"en":"The phrase places an idea or event in a historical period.","zh":"這個片語把想法或事件放在歷史時期中。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":4},{"front":"be considered inferior to","meaning":"被視為不如……","examples":[{"en":"Life-casting was considered inferior to sculpture.","zh":"生活鑄模被視為不如雕塑。"},{"en":"Be considered inferior to means be judged as lower in quality, value, or status than something else.","zh":"be considered inferior to 指被判斷為在質素、價值或地位上低於某物。"},{"en":"Online lessons should not automatically be considered inferior to classroom lessons.","zh":"網上課堂不應自動被視為不如面授課堂。"},{"en":"If a craft is considered inferior, its makers may receive less respect.","zh":"如果一種工藝被視為較低等，其製作者可能得到較少尊重。"},{"en":"The phrase shows a hierarchy or negative comparison.","zh":"這個片語顯示等級或負面比較。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":4},{"front":"in the same way that","meaning":"就像……一樣","examples":[{"en":"Life-casting was considered inferior to sculpture in the same way that photography was considered inferior to painting.","zh":"生活鑄模被視為不如雕塑，就像攝影被視為不如繪畫一樣。"},{"en":"In the same way that means similarly to how another thing happens or is judged.","zh":"in the same way that 指與另一件事發生或被判斷的方式相似。"},{"en":"Some people once doubted online learning in the same way that they doubted television as education.","zh":"有些人曾懷疑網上學習，就像他們懷疑電視作為教育一樣。"},{"en":"If two new techniques are both dismissed as shortcuts, they are being judged in a similar way.","zh":"如果兩種新技術都被貶為捷徑，它們就是以相似方式被評價。"},{"en":"The phrase creates a comparison between two situations.","zh":"這個片語在兩種情況之間建立比較。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":4},{"front":"a lesser art than","meaning":"比……較低等的藝術","examples":[{"en":"Photography was thought to be a lesser art than painting.","zh":"攝影曾被認為是比繪畫較低等的藝術。"},{"en":"A lesser art than something means an art form judged as lower in status or value.","zh":"a lesser art than something 指被判斷為地位或價值低於另一藝術形式。"},{"en":"Some people once treated comic books as a lesser art than novels.","zh":"有些人曾把漫畫書視為比小說較低等的藝術。"},{"en":"If an art form is seen as merely mechanical, critics may call it lesser.","zh":"如果某藝術形式被視為只是機械性，評論家可能稱它較低等。"},{"en":"The phrase reveals an unequal ranking between art forms.","zh":"這個片語揭示藝術形式之間的不平等排序。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":4},{"front":"be viewed as","meaning":"被視為","examples":[{"en":"Life-casting and photography were viewed as shortcuts by the senior arts.","zh":"生活鑄模和攝影被較高等的藝術門類視為捷徑。"},{"en":"Be viewed as means be seen, judged, or interpreted in a particular way.","zh":"be viewed as 指被以某種方式看待、判斷或詮釋。"},{"en":"A quiet student may be viewed as unfriendly even if they are only shy.","zh":"安靜學生可能被視為不友善，即使他只是害羞。"},{"en":"If a technique is viewed as a shortcut, people may underestimate the skill behind it.","zh":"如果一種技術被視為捷徑，人們可能低估其背後技巧。"},{"en":"The phrase focuses on perception rather than fact alone.","zh":"這個片語集中於看法，而不只是事實。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":4},{"front":"unacceptable shortcuts","meaning":"不能接受的捷徑","examples":[{"en":"Life-casting and photography were viewed as unacceptable shortcuts.","zh":"生活鑄模和攝影被視為不能接受的捷徑。"},{"en":"Unacceptable shortcuts are quick methods judged as unfair, lazy, or lacking proper skill.","zh":"unacceptable shortcuts 指被判斷為不公平、懶惰或缺乏真正技巧的快速方法。"},{"en":"Copying homework from the internet is an unacceptable shortcut because it avoids real learning.","zh":"從網上抄功課是不能接受的捷徑，因為它避開真正學習。"},{"en":"If critics see a method as an unacceptable shortcut, they may refuse to call it art.","zh":"如果評論家把某方法視為不能接受的捷徑，他們可能拒絕稱它為藝術。"},{"en":"The phrase suggests speed is being criticised, not praised.","zh":"這個片語暗示速度被批評，而不是被讚賞。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":4},{"front":"the senior arts","meaning":"較高等的藝術門類","examples":[{"en":"The senior arts looked down on life-casting and photography.","zh":"較高等的藝術門類看不起生活鑄模和攝影。"},{"en":"The senior arts are art forms traditionally treated as higher in status, such as painting or sculpture.","zh":"the senior arts 指傳統上被視為地位較高的藝術形式，例如繪畫或雕塑。"},{"en":"In the past, painting may have been treated as one of the senior arts above craftwork.","zh":"在過去，繪畫可能被視為高於工藝的一種較高等藝術。"},{"en":"If senior arts protect their status, they may dismiss newer forms as inferior.","zh":"如果較高等藝術保護自身地位，可能把新形式貶為低等。"},{"en":"The phrase reflects an old hierarchy in the art world.","zh":"這個片語反映藝術界中的舊有等級。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":4},{"front":"virtues of speed and realism","meaning":"速度和寫實性的優點","examples":[{"en":"The virtues of speed and realism also implied limitations.","zh":"速度和寫實性的優點也暗示了局限。"},{"en":"Virtues of speed and realism means the advantages of being quick and very true to life.","zh":"virtues of speed and realism 指快速和非常貼近真實的優勢。"},{"en":"Digital notes have the virtue of speed because students can search them quickly.","zh":"數碼筆記有速度上的優點，因為學生可以快速搜尋。"},{"en":"If realism is too exact, critics may say there is little room for imagination.","zh":"如果寫實性太精確，評論家可能說幾乎沒有想像空間。"},{"en":"The phrase shows that strengths can also create weaknesses.","zh":"這個片語顯示優點也可以造成弱點。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":5},{"front":"unwavering realism","meaning":"毫不動搖的寫實性","examples":[{"en":"Life-casting was valued for its unwavering realism.","zh":"生活鑄模因其毫不動搖的寫實性而受到重視。"},{"en":"Unwavering realism means complete and consistent faithfulness to real appearance.","zh":"unwavering realism 指完全且持續忠於真實外觀。"},{"en":"A medical model may need unwavering realism so students can study body structures accurately.","zh":"醫學模型可能需要毫不動搖的寫實性，讓學生準確研究身體結構。"},{"en":"If an artwork has unwavering realism, it may look exact but less imaginative to some viewers.","zh":"如果藝術品具有毫不動搖的寫實性，它可能看似精確，但對某些觀眾來說較缺乏想像。"},{"en":"The phrase praises accuracy but may also hint at limitation.","zh":"這個片語讚賞準確性，但也可能暗示局限。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":5},{"front":"imply limitations","meaning":"暗示局限","examples":[{"en":"The virtues of life-casting also implied its limitations.","zh":"生活鑄模的優點也暗示了其局限。"},{"en":"Imply limitations means suggest hidden weaknesses or boundaries.","zh":"imply limitations 指暗示隱藏的弱點或界限。"},{"en":"A fast translation app may imply limitations because it can miss tone and context.","zh":"快速翻譯應用程式可能暗示局限，因為它可能錯過語氣和語境。"},{"en":"If a technique copies reality perfectly, it may imply limited space for personal invention.","zh":"如果一種技術完美複製現實，就可能暗示個人創作空間有限。"},{"en":"The phrase shows that a strength can quietly point to a weakness.","zh":"這個片語顯示優點可以悄悄指向弱點。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":5},{"front":"leave little or no room for","meaning":"幾乎沒有留下……的空間","examples":[{"en":"Life-casting left little or no room for the imagination.","zh":"生活鑄模幾乎沒有留下想像力的空間。"},{"en":"Leave little or no room for means allow almost no space or opportunity for something.","zh":"leave little or no room for 指幾乎不容許某事存在或發生。"},{"en":"A timetable packed with lessons leaves little room for rest.","zh":"塞滿課堂的時間表幾乎沒有留下休息空間。"},{"en":"If a process copies reality exactly, critics may think it leaves little room for creativity.","zh":"如果一個過程精確複製現實，評論家可能認為它幾乎沒有留下創意空間。"},{"en":"The phrase shows that something is being squeezed out.","zh":"這個片語顯示某事被排擠出去。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":5},{"front":"the imagination","meaning":"想像力","examples":[{"en":"Critics believed life-casting left little room for the imagination.","zh":"評論家認為生活鑄模幾乎沒有留下想像力的空間。"},{"en":"The imagination is the ability to form ideas, images, or possibilities beyond what is directly seen.","zh":"the imagination 指形成超越直接所見的想法、圖像或可能性的能力。"},{"en":"Children use the imagination when a cardboard box becomes a castle in their game.","zh":"孩子把紙箱當成城堡玩耍時，就是在使用想像力。"},{"en":"If an artwork tells viewers everything too exactly, it may give the imagination less work to do.","zh":"如果藝術品把一切說得太精確，可能讓想像力較少發揮。"},{"en":"The phrase is central to debates about creativity.","zh":"這個片語是創意辯論中的核心概念。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":5},{"front":"an insult to","meaning":"對……的侮辱","examples":[{"en":"For many, life-casting was an insult to the sculptor’s creative genius.","zh":"對許多人而言，生活鑄模是對雕塑家創作天才的侮辱。"},{"en":"An insult to means something that offends or disrespects a person, idea, or value.","zh":"an insult to 指冒犯或不尊重某人、理念或價值的事情。"},{"en":"Calling a careful student lazy can feel like an insult to their effort.","zh":"稱一個認真學生懶惰，可能像是對其努力的侮辱。"},{"en":"If artists value imagination, a mechanical copy may seem like an insult to creativity.","zh":"如果藝術家重視想像力，機械複製可能看似對創意的侮辱。"},{"en":"The phrase expresses strong disapproval or offence.","zh":"這個片語表達強烈不滿或冒犯感。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":5},{"front":"creative genius","meaning":"創作天才","examples":[{"en":"Some people thought life-casting insulted the sculptor’s creative genius.","zh":"有些人認為生活鑄模侮辱了雕塑家的創作天才。"},{"en":"Creative genius means exceptional artistic imagination and original ability.","zh":"creative genius 指非凡的藝術想像力和原創能力。"},{"en":"A composer’s creative genius may appear in music that sounds unlike anything before it.","zh":"作曲家的創作天才可能出現在前所未有的音樂中。"},{"en":"If a process seems too automatic, critics may think it does not require creative genius.","zh":"如果某過程看似太自動化，評論家可能認為它不需要創作天才。"},{"en":"The phrase praises high-level originality.","zh":"這個片語讚賞高層次原創性。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":5},{"front":"an infamous lawsuit","meaning":"一宗臭名昭著的訴訟","examples":[{"en":"An infamous lawsuit in 1834 involved a mould of Napoleon’s face.","zh":"1834年一宗臭名昭著的訴訟涉及拿破崙面部的模。"},{"en":"An infamous lawsuit is a legal case that became well known for negative or controversial reasons.","zh":"an infamous lawsuit 指因負面或具爭議原因而聞名的法律案件。"},{"en":"A company may face an infamous lawsuit if it sells unsafe products to children.","zh":"如果公司向兒童銷售不安全產品，可能面對一宗臭名昭著的訴訟。"},{"en":"If a lawsuit decides whether a maker owns an image, it can affect how society values the work.","zh":"如果訴訟裁定製作者是否擁有影像，它可以影響社會如何評價該作品。"},{"en":"The phrase introduces a notorious legal example.","zh":"這個片語引出惡名昭彰的法律例子。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":5},{"front":"moulder","meaning":"製模工匠","examples":[{"en":"The moulder made a mask of the dying French emperor Napoleon.","zh":"製模工匠製作了垂死的法國皇帝拿破崙的面具。"},{"en":"A moulder is a craftsperson who makes moulds or casts.","zh":"moulder 指製作模具或鑄模的工匠。"},{"en":"A moulder may prepare plaster carefully so it captures the exact shape of an object.","zh":"製模工匠可能小心準備石膏，以捕捉物件的準確形狀。"},{"en":"If a moulder is not treated as an artist, they may have fewer rights over the final image.","zh":"如果製模工匠不被視為藝術家，他們對最終影像可能擁有較少權利。"},{"en":"The word refers to skilled technical labour.","zh":"這個詞指具技巧的技術勞動。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":5},{"front":"the dying French emperor Napoleon","meaning":"垂死的法國皇帝拿破崙","examples":[{"en":"The moulder made a mask of the dying French emperor Napoleon.","zh":"製模工匠製作了垂死的法國皇帝拿破崙的面具。"},{"en":"The dying French emperor Napoleon means Napoleon when he was near death.","zh":"the dying French emperor Napoleon 指接近死亡時的拿破崙。"},{"en":"A historian may study portraits of a dying ruler to understand how power and mortality were represented.","zh":"歷史學家可能研究垂死統治者的肖像，以理解權力和死亡如何被呈現。"},{"en":"If a cast is taken from a dying person, it can preserve a final physical likeness.","zh":"如果鑄模從垂死者身上取得，它可以保存最後的身體相貌。"},{"en":"The phrase gives historical and emotional weight to the object.","zh":"這個片語賦予物件歷史和情感重量。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":5},{"front":"be reproduced and sold","meaning":"被複製和出售","examples":[{"en":"The mask was reproduced and sold without the moulder’s permission.","zh":"面具未經製模工匠許可被複製和出售。"},{"en":"Be reproduced and sold means be copied and then offered for money.","zh":"be reproduced and sold 指被複製，然後作金錢交易。"},{"en":"A photograph may be reproduced and sold as posters if the owner gives permission.","zh":"如果擁有人批准，照片可以被複製並作為海報出售。"},{"en":"If a maker’s work is reproduced without permission, ownership becomes a legal issue.","zh":"如果製作者的作品未經許可被複製，擁有權就成為法律問題。"},{"en":"The phrase connects copying with commercial use.","zh":"這個片語把複製與商業用途連接起來。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":6},{"front":"without his permission","meaning":"未經他許可","examples":[{"en":"The mask was sold without his permission.","zh":"面具未經他許可被出售。"},{"en":"Without his permission means without his agreement or approval.","zh":"without his permission 指沒有得到他的同意或批准。"},{"en":"A student should not post a classmate’s photo online without their permission.","zh":"學生不應未經同學許可把其照片放上網。"},{"en":"If someone sells a maker’s work without permission, the maker may feel their rights were ignored.","zh":"如果有人未經許可出售製作者的作品，製作者可能覺得自己的權利被忽視。"},{"en":"The phrase marks an action as unauthorised.","zh":"這個片語標示某行動未經授權。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":6},{"front":"be judged to have no rights to","meaning":"被判定對……沒有權利","examples":[{"en":"The moulder was judged to have no rights to the image.","zh":"製模工匠被判定對該影像沒有權利。"},{"en":"Be judged to have no rights to means be legally or officially decided not to own or control something.","zh":"be judged to have no rights to 指在法律或官方上被裁定不擁有或不能控制某物。"},{"en":"A worker may be judged to have no rights to a company logo they helped print.","zh":"工人可能被判定對自己協助印製的公司標誌沒有權利。"},{"en":"If the court says a craftsperson has no rights, the work may not be treated as original art.","zh":"如果法庭說工匠沒有權利，該作品可能不被視為原創藝術。"},{"en":"The phrase connects legal judgement with ownership.","zh":"這個片語把法律判決與擁有權連接起來。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":6},{"front":"rights to the image","meaning":"對該影像的權利","examples":[{"en":"The moulder had no rights to the image he had made.","zh":"製模工匠對自己製作的影像沒有權利。"},{"en":"Rights to the image means legal control over how an image can be copied, sold, or used.","zh":"rights to the image 指對影像如何被複製、出售或使用的法律控制權。"},{"en":"A photographer may keep rights to the image even after printing it for a client.","zh":"攝影師即使為客戶印出照片，仍可能保留對該影像的權利。"},{"en":"If a person has no rights to an image, others may reproduce it without paying them.","zh":"如果某人對影像沒有權利，其他人可能不付款也能複製它。"},{"en":"The phrase belongs to ownership and copyright-like issues.","zh":"這個片語屬於擁有權和類似版權的問題。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":6},{"front":"in other words","meaning":"換句話說","examples":[{"en":"In other words, he was held not to be an artist.","zh":"換句話說，他被裁定不是藝術家。"},{"en":"In other words means saying the same idea again in a clearer or simpler way.","zh":"in other words 指用更清楚或更簡單的方式再次說明同一想法。"},{"en":"The class was understaffed; in other words, there were not enough teachers for the students.","zh":"班級人手不足；換句話說，學生太多而老師不夠。"},{"en":"If a legal decision denies artistic rights, in other words, it may deny artistic status.","zh":"如果法律判決否定藝術權利，換句話說，它可能否定藝術地位。"},{"en":"The phrase helps explain or restate a point.","zh":"這個片語幫助解釋或重述觀點。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":6},{"front":"be held not to be","meaning":"被明確裁定不是","examples":[{"en":"The moulder was specifically held not to be an artist.","zh":"製模工匠被明確裁定不是藝術家。"},{"en":"Be held not to be means be officially judged or considered not to be something.","zh":"be held not to be 指被官方判定或認為不是某身份。"},{"en":"A temporary worker may be held not to be a full employee under certain rules.","zh":"在某些規則下，臨時工可能被裁定不是正式員工。"},{"en":"If a moulder is held not to be an artist, his work may receive less legal protection.","zh":"如果製模工匠被裁定不是藝術家，其作品可能得到較少法律保護。"},{"en":"The phrase is formal and often appears in legal discussion.","zh":"這個片語較正式，常出現在法律討論中。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":6},{"front":"this judgement reflects","meaning":"這項判決反映","examples":[{"en":"This judgement reflects the view of the nineteenth-century art world.","zh":"這項判決反映了十九世紀藝術界的看法。"},{"en":"This judgement reflects means this decision shows or represents a wider attitude.","zh":"this judgement reflects 指這個決定顯示或代表更廣泛的態度。"},{"en":"A school’s strict uniform rule may reflect its belief in discipline.","zh":"學校嚴格校服規則可能反映其對紀律的信念。"},{"en":"If a court denies a moulder artistic rights, the judgement reflects how society ranked crafts.","zh":"如果法庭否定製模工匠的藝術權利，該判決反映社會如何排序工藝。"},{"en":"The phrase links one decision to a broader belief.","zh":"這個片語把單一決定與更廣泛信念連接起來。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":6},{"front":"established members of","meaning":"……中具地位的成員","examples":[{"en":"The judgement reflected the view of established members of the art world.","zh":"這項判決反映了藝術界中具地位成員的看法。"},{"en":"Established members of a group are respected or powerful people already accepted within that group.","zh":"established members of a group 指已在某群體內被接受且受尊重或有權力的人。"},{"en":"Established members of a school committee may influence which rules are changed.","zh":"學校委員會中具地位的成員可能影響哪些規則會被改變。"},{"en":"If established members reject a new art form, it may take years to gain respect.","zh":"如果具地位的成員拒絕新藝術形式，它可能需要多年才獲尊重。"},{"en":"The phrase points to people with recognised status.","zh":"這個片語指出具有公認地位的人。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":6},{"front":"the nineteenth-century art world","meaning":"十九世紀藝術界","examples":[{"en":"Life-casting was rejected by much of the nineteenth-century art world.","zh":"生活鑄模被十九世紀藝術界大部分人拒絕。"},{"en":"The nineteenth-century art world means the artists, critics, institutions, and values connected with art during the 1800s.","zh":"the nineteenth-century art world 指1800年代與藝術有關的藝術家、評論家、機構和價值觀。"},{"en":"The nineteenth-century art world often treated painting and sculpture as high art.","zh":"十九世紀藝術界常把繪畫和雕塑視為高等藝術。"},{"en":"If that art world valued imagination over mechanical accuracy, life-casting would seem inferior.","zh":"如果當時藝術界重視想像多於機械準確，生活鑄模就會顯得低等。"},{"en":"The phrase refers to both people and attitudes in a historical period.","zh":"這個片語指某歷史時期中的人物和態度。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":6},{"front":"happens fast but","meaning":"發生得很快，但……","examples":[{"en":"Rodin said life-casting happens fast but does not make art.","zh":"Rodin 說生活鑄模發生得很快，但並不能產生藝術。"},{"en":"Happens fast but means occurs quickly, although that speed may not produce the desired value.","zh":"happens fast but 指某事發生迅速，但這種速度未必產生所需價值。"},{"en":"A student can copy an answer fast but still not understand the method.","zh":"學生可以很快抄下答案，但仍不理解方法。"},{"en":"If a process happens quickly, critics may think it lacks labour or imagination.","zh":"如果過程很快完成，評論家可能認為它缺乏勞動或想像。"},{"en":"The phrase introduces contrast between speed and quality.","zh":"這個片語引出速度與質素之間的對比。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":6},{"front":"lead Art away from","meaning":"令藝術偏離……","examples":[{"en":"Some feared that too much nature would lead Art away from the Ideal.","zh":"有些人害怕過多自然會令藝術偏離理想美。"},{"en":"Lead Art away from means cause art to move away from a valued principle or direction.","zh":"lead Art away from 指令藝術偏離某種被重視的原則或方向。"},{"en":"Some teachers fear that exam drilling can lead education away from curiosity.","zh":"有些老師害怕考試操練會令教育偏離好奇心。"},{"en":"If artists copy nature too exactly, traditionalists may think art is moving away from ideal beauty.","zh":"如果藝術家過度精確複製自然，傳統主義者可能認為藝術正偏離理想美。"},{"en":"The phrase describes a feared change in direction.","zh":"這個片語描述令人擔心的方向改變。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":7},{"front":"its proper course","meaning":"其正確方向","examples":[{"en":"Some feared that life-casting would lead art away from its proper course.","zh":"有些人害怕生活鑄模會令藝術偏離其正確方向。"},{"en":"Its proper course means the direction something is believed to be meant to follow.","zh":"its proper course 指某事被認為應該遵循的方向。"},{"en":"Parents may worry that too much screen time leads study away from its proper course.","zh":"家長可能擔心太多螢幕時間令學習偏離其正確方向。"},{"en":"If people believe art should pursue ideals, exact copying may seem like a wrong path.","zh":"如果人們相信藝術應追求理想，精確複製可能看似錯誤道路。"},{"en":"The phrase suggests a correct or traditional direction.","zh":"這個片語暗示正確或傳統方向。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":7},{"front":"the Ideal","meaning":"理想美","examples":[{"en":"Some artists believed art should follow the Ideal rather than nature.","zh":"有些藝術家認為藝術應追隨理想美，而不是自然。"},{"en":"The Ideal means a perfect or elevated form of beauty, not ordinary reality exactly as it appears.","zh":"the Ideal 指完美或崇高的美，而不是普通現實的精確外觀。"},{"en":"A portrait painter may smooth flaws because they are aiming for the Ideal, not exact realism.","zh":"肖像畫家可能修飾瑕疵，因為他追求的是理想美，而不是完全寫實。"},{"en":"If art follows the Ideal, it may improve or reshape nature rather than copy it.","zh":"如果藝術追隨理想美，它可能改善或重塑自然，而不是複製自然。"},{"en":"The phrase belongs to traditional ideas about beauty and art.","zh":"這個片語屬於關於美和藝術的傳統觀念。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":7},{"front":"future developments in","meaning":"……的未來發展","examples":[{"en":"Gauguin worried about future developments in photography.","zh":"Gauguin 擔心攝影的未來發展。"},{"en":"Future developments in something are changes, improvements, or new forms that may appear later.","zh":"future developments in something 指某領域日後可能出現的變化、改進或新形式。"},{"en":"Teachers often discuss future developments in artificial intelligence and education.","zh":"老師常討論人工智能和教育的未來發展。"},{"en":"If photography becomes more advanced, painters may need to rethink their role.","zh":"如果攝影變得更先進，畫家可能需要重新思考自己的角色。"},{"en":"The phrase points to possible changes ahead.","zh":"這個片語指向未來可能的變化。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":7},{"front":"photography","meaning":"攝影","examples":[{"en":"Photography forced painting to reassess its role.","zh":"攝影迫使繪畫重新評估其角色。"},{"en":"Photography is the art or process of making images with a camera.","zh":"photography 指使用相機製作影像的藝術或過程。"},{"en":"Students use photography to record school events, family life, and street scenes.","zh":"學生用攝影記錄學校活動、家庭生活和街景。"},{"en":"If photography can capture reality quickly, painting may focus more on imagination or interpretation.","zh":"如果攝影能快速捕捉現實，繪畫可能更集中於想像或詮釋。"},{"en":"The word can refer to both a technique and an art form.","zh":"這個詞可指技術，也可指藝術形式。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":7},{"front":"if ever","meaning":"如果有一天","examples":[{"en":"If ever photography went into colour, painters might face new challenges.","zh":"如果有一天攝影變成彩色，畫家可能面對新挑戰。"},{"en":"If ever means if at any time in the future something happens.","zh":"if ever 指如果某事在未來任何時候發生。"},{"en":"If ever the school moves online again, teachers will need better digital materials.","zh":"如果有一天學校再次轉到網上，老師將需要更好的數碼教材。"},{"en":"If ever a new technology copies a skill perfectly, old professions may feel threatened.","zh":"如果有一天新科技能完美複製某種技能，舊職業可能感到受威脅。"},{"en":"The phrase introduces a possible but uncertain future condition.","zh":"這個片語引出可能但不確定的未來條件。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":7},{"front":"go into colour","meaning":"變成彩色","examples":[{"en":"Gauguin wondered what would happen if photography went into colour.","zh":"Gauguin 想知道如果攝影變成彩色會發生甚麼。"},{"en":"Go into colour means change from black-and-white images to colour images.","zh":"go into colour 指從黑白影像變成彩色影像。"},{"en":"Old television changed viewers’ experience when it went into colour.","zh":"舊電視變成彩色時改變了觀眾體驗。"},{"en":"If photography went into colour, it would become even closer to natural appearance.","zh":"如果攝影變成彩色，它會更接近自然外觀。"},{"en":"The phrase describes a technological shift in visual media.","zh":"這個片語描述視覺媒介的技術轉變。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":7},{"front":"labour away at","meaning":"辛苦地做","examples":[{"en":"Gauguin asked why a painter would labour away at a likeness.","zh":"Gauguin 問畫家為何要辛苦地畫一幅肖像。"},{"en":"Labour away at means work hard and for a long time on something.","zh":"labour away at 指長時間努力做某事。"},{"en":"A student may labour away at an essay for hours to make each paragraph clear.","zh":"學生可能花數小時辛苦地寫文章，以令每段清晰。"},{"en":"If a camera can capture likeness quickly, painters may question why they should labour over exact copying.","zh":"如果相機能快速捕捉相貌，畫家可能質疑為何要辛苦地精確複製。"},{"en":"The phrase suggests effort, time, and sometimes frustration.","zh":"這個片語暗示努力、時間，有時也暗示挫折。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":7},{"front":"a likeness","meaning":"肖像；逼真相似的描繪","examples":[{"en":"A painter might labour away at a likeness with a brush.","zh":"畫家可能用畫筆辛苦地畫一幅逼真肖像。"},{"en":"A likeness is an image that looks like the person or thing it represents.","zh":"a likeness 指看起來像其所代表的人或物的影像。"},{"en":"A passport photo must be a clear likeness of the person applying.","zh":"護照照片必須是申請人的清晰肖像。"},{"en":"If a portrait is a good likeness, friends can recognise the sitter easily.","zh":"如果肖像很逼真，朋友可以容易認出畫中人。"},{"en":"The phrase focuses on accurate visual resemblance.","zh":"這個片語集中於準確的視覺相似。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":7},{"front":"a brush made from squirrel-tail","meaning":"松鼠尾毛製成的畫筆","examples":[{"en":"Gauguin referred to a brush made from squirrel-tail.","zh":"Gauguin 提到一支由松鼠尾毛製成的畫筆。"},{"en":"A brush made from squirrel-tail is a painter’s brush using fine squirrel hair.","zh":"a brush made from squirrel-tail 指使用細軟松鼠毛製成的畫筆。"},{"en":"Traditional artists may choose special brushes because different hairs make different marks.","zh":"傳統藝術家可能選擇特殊畫筆，因為不同毛質會產生不同筆觸。"},{"en":"If a painter uses a delicate squirrel-tail brush, the work may require patience and control.","zh":"如果畫家使用精細的松鼠尾毛畫筆，作品可能需要耐心和控制。"},{"en":"The phrase highlights traditional manual technique.","zh":"這個片語突出傳統手工技術。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":7},{"front":"prove robust","meaning":"證明具有韌性","examples":[{"en":"Painting has proved robust despite the rise of photography.","zh":"儘管攝影興起，繪畫已證明具有韌性。"},{"en":"Prove robust means show itself to be strong, durable, or able to survive challenges.","zh":"prove robust 指顯示自己強韌、耐用或能承受挑戰。"},{"en":"A school’s online system proved robust when thousands of students logged in at once.","zh":"當數千名學生同時登入時，學校網上系統證明具有韌性。"},{"en":"If painting survives after photography appears, it proves it has lasting value beyond realism.","zh":"如果繪畫在攝影出現後仍生存，就證明它有超越寫實的持久價值。"},{"en":"The phrase describes strength tested by difficulty.","zh":"這個片語描述經困難考驗的強度。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":8},{"front":"reassess narrative","meaning":"重新評估敘事方式","examples":[{"en":"The novel had to reassess narrative after the arrival of cinema.","zh":"電影出現後，小說不得不重新評估敘事方式。"},{"en":"Reassess narrative means rethink how stories are told.","zh":"reassess narrative 指重新思考故事如何被講述。"},{"en":"Teachers may reassess narrative methods when students respond better to personal stories than timelines.","zh":"當學生對個人故事比時間線反應更好時，老師可能重新評估敘事方法。"},{"en":"If cinema tells visual stories powerfully, novels may explore inner thoughts instead.","zh":"如果電影能有力地講述視覺故事，小說可能轉而探索內心思想。"},{"en":"The phrase describes rethinking storytelling methods.","zh":"這個片語描述重新思考講故事的方法。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":8},{"front":"the arrival of","meaning":"……的出現","examples":[{"en":"The novel changed after the arrival of the cinema.","zh":"電影出現後，小說改變了。"},{"en":"The arrival of something means the appearance or introduction of something new.","zh":"the arrival of something 指新事物的出現或引入。"},{"en":"The arrival of smartphones changed how students communicate and study.","zh":"智能手機的出現改變了學生溝通和學習方式。"},{"en":"If a new medium arrives, older forms may need to adjust.","zh":"如果新媒介出現，較舊形式可能需要調整。"},{"en":"The phrase marks the point when something enters history or daily life.","zh":"這個片語標示某物進入歷史或日常生活的時刻。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":8},{"front":"the cinema","meaning":"電影","examples":[{"en":"The arrival of the cinema forced the novel to reassess narrative.","zh":"電影的出現迫使小說重新評估敘事方式。"},{"en":"The cinema means film as an art form, industry, or public viewing experience.","zh":"the cinema 指作為藝術形式、產業或公共觀看體驗的電影。"},{"en":"Many people go to the cinema to watch films on a large screen with an audience.","zh":"許多人去戲院與觀眾一起在大銀幕看電影。"},{"en":"If cinema can show action directly, novels may focus more on memory, voice, or thought.","zh":"如果電影能直接展示動作，小說可能更集中於記憶、聲音或思想。"},{"en":"The phrase refers to film culture as well as the place where films are shown.","zh":"這個片語既指電影文化，也指放映電影的地方。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":8},{"front":"the gap between","meaning":"……之間的差距","examples":[{"en":"The gap between the senior and junior arts was narrower than traditionalists implied.","zh":"高等與低等藝術之間的差距比傳統主義者暗示的更小。"},{"en":"The gap between two things is the difference or distance separating them.","zh":"the gap between two things 指分隔兩者的差異或距離。"},{"en":"Extra tutoring can reduce the gap between strong and weak students.","zh":"額外補習可以縮小強弱學生之間的差距。"},{"en":"If the gap between high art and craft is small, old rankings may be unfair.","zh":"如果高等藝術與工藝之間的差距很小，舊有排序可能不公平。"},{"en":"The phrase is used to compare difference in status, quality, or distance.","zh":"這個片語用於比較地位、質素或距離上的差異。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":8},{"front":"senior and junior arts","meaning":"高等與低等藝術","examples":[{"en":"The distinction between senior and junior arts was not as clear as traditionalists claimed.","zh":"高等與低等藝術之間的區分並不像傳統主義者聲稱的那麼清楚。"},{"en":"Senior and junior arts means supposedly higher and lower forms of art.","zh":"senior and junior arts 指所謂較高等和較低等的藝術形式。"},{"en":"Some people once treated painting as a senior art and craftwork as a junior art.","zh":"有些人曾把繪畫視為高等藝術，把工藝視為低等藝術。"},{"en":"If both forms require skill and imagination, the division may be too simple.","zh":"如果兩種形式都需要技巧和想像，這種劃分可能過於簡單。"},{"en":"The phrase reflects an old artistic hierarchy.","zh":"這個片語反映舊有藝術等級。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":8},{"front":"narrower than","meaning":"比……狹窄","examples":[{"en":"The gap was narrower than the traditionalists implied.","zh":"這個差距比傳統主義者暗示的更狹窄。"},{"en":"Narrower than means smaller in width, difference, or degree than something else.","zh":"narrower than 指在寬度、差異或程度上比另一事物更小。"},{"en":"The gap between two exam scores may be narrower than students expected.","zh":"兩個考試分數之間的差距可能比學生預期更小。"},{"en":"If the difference between craft and art is narrower than claimed, reassessment becomes reasonable.","zh":"如果工藝與藝術之間的差異比聲稱的更小，重新評估就合理。"},{"en":"The phrase makes a comparison showing less difference.","zh":"這個片語作出顯示較少差異的比較。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":8},{"front":"traditionalists","meaning":"傳統主義者","examples":[{"en":"Traditionalists implied that there was a wide gap between different arts.","zh":"傳統主義者暗示不同藝術之間有很大差距。"},{"en":"Traditionalists are people who prefer established customs, rules, or older ways of thinking.","zh":"traditionalists 指偏好既有習俗、規則或舊思維方式的人。"},{"en":"Traditionalists in education may prefer textbooks and exams over experimental learning.","zh":"教育上的傳統主義者可能偏好教科書和考試，而不是實驗式學習。"},{"en":"If traditionalists defend old categories, they may resist new art forms.","zh":"如果傳統主義者捍衛舊分類，可能抗拒新藝術形式。"},{"en":"The word often contrasts older values with change.","zh":"這個詞常把舊價值與改變作對比。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":8},{"front":"imply","meaning":"暗示","examples":[{"en":"The traditionalists implied that life-casting was a lesser craft.","zh":"傳統主義者暗示生活鑄模是一種較低等的工藝。"},{"en":"Imply means suggest something indirectly without saying it openly.","zh":"imply 指間接暗示某事，而不是明說。"},{"en":"If a teacher says an essay needs “more care”, they may imply that it was rushed.","zh":"如果老師說文章需要「更細心」，可能暗示它寫得倉促。"},{"en":"If critics call a technique a shortcut, they may imply it lacks real artistry.","zh":"如果評論家稱一種技術為捷徑，可能暗示它缺乏真正藝術性。"},{"en":"The word points to meaning beneath the surface.","zh":"這個詞指表面之下的意思。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":8},{"front":"technical back-up","meaning":"技術支援","examples":[{"en":"Painters have always used technical back-up.","zh":"畫家一直都使用技術支援。"},{"en":"Technical back-up means practical support, tools, or assistance that helps someone complete skilled work.","zh":"technical back-up 指幫助某人完成技術工作所需的實用支援、工具或協助。"},{"en":"A teacher may need technical back-up when using projectors and online platforms.","zh":"老師使用投影機和網上平台時可能需要技術支援。"},{"en":"If painters rely on assistants or devices, art is not created by imagination alone.","zh":"如果畫家依賴助手或設備，藝術就不是只靠想像創造。"},{"en":"The phrase shows that practical help can support creative work.","zh":"這個片語顯示實用協助可以支援創作。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":8},{"front":"studio assistants","meaning":"畫室助手","examples":[{"en":"Painters often used studio assistants to help with their work.","zh":"畫家常使用畫室助手協助其工作。"},{"en":"Studio assistants are helpers who work in an artist’s studio, often preparing materials or completing routine tasks.","zh":"studio assistants 指在藝術家畫室工作的助手，通常負責準備材料或完成例行任務。"},{"en":"A photographer may use studio assistants to set lights, move equipment, and organise props.","zh":"攝影師可能使用畫室助手設燈、搬設備和整理道具。"},{"en":"If artists use assistants, the final work may still carry the artist’s main idea.","zh":"如果藝術家使用助手，最終作品仍可能承載藝術家的主要構想。"},{"en":"The phrase highlights teamwork behind individual artworks.","zh":"這個片語突出個人藝術品背後的團隊工作。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":9},{"front":"the boring bits","meaning":"乏味的部分","examples":[{"en":"Studio assistants helped painters do the boring bits.","zh":"畫室助手幫畫家做乏味的部分。"},{"en":"The boring bits are the dull, repetitive, or less creative parts of a task.","zh":"the boring bits 指任務中沉悶、重複或較不具創意的部分。"},{"en":"In a school project, formatting references may be one of the boring bits.","zh":"在學校項目中，格式化參考資料可能是乏味部分之一。"},{"en":"If assistants handle the boring bits, the main artist can focus on design and meaning.","zh":"如果助手處理乏味部分，主要藝術家就能集中於設計和意義。"},{"en":"The phrase is informal and refers to routine work.","zh":"這個片語較口語，指例行工作。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":9},{"front":"apparently lesser crafts","meaning":"表面上較低等的工藝","examples":[{"en":"Apparently lesser crafts may involve great skill and thought.","zh":"表面上較低等的工藝可能涉及高超技巧和思考。"},{"en":"Apparently lesser crafts are crafts that seem lower in status but may actually be demanding and valuable.","zh":"apparently lesser crafts 指看似地位較低，但實際可能要求很高且有價值的工藝。"},{"en":"Embroidery may look like a simple hobby, but it can require planning, patience, and precision.","zh":"刺繡可能看似簡單嗜好，但它可以需要規劃、耐性和精準度。"},{"en":"If a craft appears lesser only because of tradition, later viewers may reassess it.","zh":"如果工藝只是因傳統而顯得低等，後來觀眾可能重新評估它。"},{"en":"The phrase questions surface-level judgement.","zh":"這個片語質疑表面判斷。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":9},{"front":"involve great skill","meaning":"涉及高超技巧","examples":[{"en":"Lesser crafts can involve great skill, thought and preparation.","zh":"較低等的工藝可能涉及高超技巧、思考和準備。"},{"en":"Involve great skill means require a high level of ability and careful control.","zh":"involve great skill 指需要高水平能力和仔細控制。"},{"en":"Making a wedding cake can involve great skill because it needs structure, decoration, and timing.","zh":"製作婚禮蛋糕可能涉及高超技巧，因為它需要結構、裝飾和時間掌握。"},{"en":"If life-casting involves great skill, calling it a mere shortcut becomes unfair.","zh":"如果生活鑄模涉及高超技巧，把它稱為純粹捷徑就不公平。"},{"en":"The phrase stresses the difficulty behind an activity.","zh":"這個片語強調活動背後的難度。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":9},{"front":"depending on how we define it","meaning":"視乎我們如何定義它","examples":[{"en":"Lesser crafts may involve imagination, depending on how we define it.","zh":"較低等的工藝可能涉及想像力，視乎我們如何定義它。"},{"en":"Depending on how we define it means the answer changes according to the meaning we give to a word or idea.","zh":"depending on how we define it 指答案會根據我們如何界定某詞或概念而改變。"},{"en":"A game may count as learning, depending on how we define learning.","zh":"一個遊戲是否算學習，視乎我們如何定義學習。"},{"en":"If imagination includes choice and arrangement, crafts may involve imagination too.","zh":"如果想像力包括選擇和佈置，工藝也可能涉及想像力。"},{"en":"The phrase shows that definitions affect judgement.","zh":"這個片語顯示定義會影響判斷。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":9},{"front":"Time changes our view","meaning":"時間改變我們的看法","examples":[{"en":"Time changes our view of art in another way.","zh":"時間以另一種方式改變我們對藝術的看法。"},{"en":"Time changes our view means our judgement changes as years pass and new ideas appear.","zh":"Time changes our view 指隨着年月過去和新想法出現，我們的判斷會改變。"},{"en":"Time changes our view of old school rules when society becomes more open.","zh":"當社會變得更開放，時間會改變我們對舊校規的看法。"},{"en":"If later generations see an object differently, time has changed its meaning.","zh":"如果後代以不同方式看待物件，時間就改變了其意義。"},{"en":"The phrase stresses historical change in interpretation.","zh":"這個片語強調詮釋上的歷史變化。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":9},{"front":"each new movement","meaning":"每一個新運動","examples":[{"en":"Each new movement implies a reassessment of previous art.","zh":"每一個新運動都意味着對以往藝術的重新評估。"},{"en":"Each new movement means every new artistic, cultural, or intellectual movement.","zh":"each new movement 指每一個新的藝術、文化或思想運動。"},{"en":"Each new movement in education makes teachers rethink older classroom methods.","zh":"教育中的每一個新運動都令老師重新思考舊課堂方法。"},{"en":"If a new art movement appears, older works may be seen in a new light.","zh":"如果新藝術運動出現，舊作品可能以新角度被看待。"},{"en":"The phrase points to repeated waves of change.","zh":"這個片語指反覆出現的一波波變化。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":9},{"front":"imply a reassessment of","meaning":"意味着對……重新評估","examples":[{"en":"Each new movement implies a reassessment of what has gone before.","zh":"每一個新運動都意味着對以往出現過的東西重新評估。"},{"en":"Imply a reassessment of means suggest that something should be judged again.","zh":"imply a reassessment of 指暗示某事應被重新判斷。"},{"en":"A new teaching method may imply a reassessment of older exam-focused lessons.","zh":"新教學方法可能意味着對舊有考試導向課堂重新評估。"},{"en":"If new art values everyday objects, older crafts may need to be reconsidered.","zh":"如果新藝術重視日常物件，舊工藝可能需要被重新考慮。"},{"en":"The phrase links new developments with fresh judgement of the past.","zh":"這個片語把新發展與對過去的新判斷連接起來。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":9},{"front":"what has gone before","meaning":"以往出現過的東西","examples":[{"en":"New art changes how we view what has gone before.","zh":"新藝術改變我們如何看待以往出現過的東西。"},{"en":"What has gone before means earlier works, events, ideas, or traditions.","zh":"what has gone before 指較早的作品、事件、思想或傳統。"},{"en":"A new school policy may make teachers rethink what has gone before in classroom practice.","zh":"新校政可能令老師重新思考課堂實踐中以往出現過的東西。"},{"en":"If current art changes our standards, past art may appear different too.","zh":"如果當代藝術改變我們的標準，過去藝術也可能顯得不同。"},{"en":"The phrase refers to the past in a broad way.","zh":"這個片語以廣泛方式指過去。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":9},{"front":"alter what was done before","meaning":"改變我們對以往作品的理解","examples":[{"en":"What is done now alters what was done before.","zh":"現在所做的事會改變我們對以往作品的理解。"},{"en":"Alter what was done before means change how earlier work or action is understood.","zh":"alter what was done before 指改變人們如何理解較早的作品或行動。"},{"en":"A new discovery can alter what was done before by giving old experiments new meaning.","zh":"新發現可以透過賦予舊實驗新意義，改變我們對過去工作的理解。"},{"en":"If modern art values copying differently, it can alter how we view old casts.","zh":"如果現代藝術以不同方式重視複製，它就能改變我們如何看待舊鑄模。"},{"en":"The phrase does not mean changing the past itself, but changing our interpretation of it.","zh":"這個片語不是指改變過去本身，而是改變我們對過去的詮釋。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":9},{"front":"in some cases","meaning":"在某些情況下","examples":[{"en":"In some cases, this reassessment is merely self-serving.","zh":"在某些情況下，這種重新評估純粹為自己服務。"},{"en":"In some cases means in certain situations, but not all situations.","zh":"in some cases 指在某些情況中，但不是所有情況。"},{"en":"In some cases, students improve quickly after changing their study method.","zh":"在某些情況下，學生改變學習方法後進步很快。"},{"en":"If a phrase begins with “in some cases”, the writer is limiting the claim.","zh":"如果一句話以 in some cases 開頭，作者就是限制該主張。"},{"en":"The phrase prevents a statement from sounding universal.","zh":"這個片語避免陳述聽起來像普遍真理。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":10},{"front":"merely self-serving","meaning":"純粹為自己服務的","examples":[{"en":"Some new art uses old art in a merely self-serving way.","zh":"有些新藝術以純粹為自己服務的方式使用舊藝術。"},{"en":"Merely self-serving means done only to benefit oneself or justify one’s own position.","zh":"merely self-serving 指只為令自己得益或為自己立場辯護。"},{"en":"A student’s apology may sound merely self-serving if it is only meant to avoid punishment.","zh":"如果學生道歉只是為避免懲罰，可能聽起來純粹為自己服務。"},{"en":"If new artists claim all past art leads to them, the claim may serve their own importance.","zh":"如果新藝術家聲稱所有過去藝術都導向自己，該主張可能是在服務自己的重要性。"},{"en":"The phrase is negative and suggests selfish motivation.","zh":"這個片語帶負面意思，暗示自私動機。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":10},{"front":"justify itself","meaning":"為自己辯護；證明自己合理","examples":[{"en":"New art may use old art to justify itself.","zh":"新藝術可能利用舊藝術為自己辯護。"},{"en":"Justify itself means prove that it is reasonable, valuable, or necessary.","zh":"justify itself 指證明自己合理、有價值或有必要。"},{"en":"A school rule must justify itself by clearly helping students learn or stay safe.","zh":"校規必須透過清楚幫助學生學習或保持安全來證明自己合理。"},{"en":"If a new movement uses past examples to support its value, it is trying to justify itself.","zh":"如果新運動使用過去例子支持自身價值，它就是在嘗試為自己辯護。"},{"en":"The phrase describes defending one’s own legitimacy.","zh":"這個片語描述捍衛自身正當性。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":10},{"front":"point to","meaning":"指向","examples":[{"en":"New art may claim that earlier art points to itself.","zh":"新藝術可能聲稱較早藝術指向自己。"},{"en":"Point to means indicate, suggest, or direct attention toward something.","zh":"point to 指指出、暗示或把注意力引向某事。"},{"en":"A teacher may point to a sentence in the passage to prove an answer.","zh":"老師可能指向文章中的一句話來證明答案。"},{"en":"If earlier art seems to point to later art, people may see history as a connected path.","zh":"如果較早藝術看似指向後來藝術，人們可能把歷史視為相連道路。"},{"en":"The phrase can be literal or figurative.","zh":"這個片語可以是字面，也可以是比喻。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":10},{"front":"the culmination of","meaning":"……的頂點；集大成","examples":[{"en":"New artists may see themselves as the culmination of all that has gone before.","zh":"新藝術家可能把自己視為以往一切的集大成。"},{"en":"The culmination of something is its highest point or final result after a long process.","zh":"the culmination of something 指漫長過程後的最高點或最終成果。"},{"en":"Graduation can be the culmination of years of study and practice.","zh":"畢業可以是多年學習和練習的成果頂點。"},{"en":"If artists call themselves the culmination of history, they suggest previous art led to them.","zh":"如果藝術家稱自己為歷史的頂點，就是暗示過去藝術導向他們。"},{"en":"The phrase often sounds grand and self-important.","zh":"這個片語常聽起來宏大而自我重要。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":10},{"front":"re-alerting the sensibility","meaning":"重新喚醒感受力","examples":[{"en":"Reassessment is usually a matter of re-alerting the sensibility.","zh":"重新評估通常是重新喚醒感受力的問題。"},{"en":"Re-alerting the sensibility means making people’s awareness, taste, or sensitivity awake again.","zh":"re-alerting the sensibility 指令人的意識、品味或敏感度再次被喚醒。"},{"en":"A powerful film can re-alert viewers’ sensibility to poverty they had stopped noticing.","zh":"有力電影可以重新喚醒觀眾對他們已不再注意的貧窮的感受力。"},{"en":"If new art helps us notice old works freshly, it reawakens our ability to respond.","zh":"如果新藝術幫助我們以新鮮方式注意舊作品，它就重新喚醒我們的回應能力。"},{"en":"The phrase describes renewed sensitivity rather than new information only.","zh":"這個片語描述重新出現的敏感度，而不只是新資訊。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":10},{"front":"remind us not to","meaning":"提醒我們不要……","examples":[{"en":"New art reminds us not to take things for granted.","zh":"新藝術提醒我們不要把事情視為理所當然。"},{"en":"Remind us not to means make us remember that we should avoid doing something.","zh":"remind us not to 指令我們記得應避免做某事。"},{"en":"A fire drill reminds students not to ignore safety rules.","zh":"消防演習提醒學生不要忽視安全規則。"},{"en":"If new art surprises us, it can remind us not to judge old objects too quickly.","zh":"如果新藝術令我們驚訝，它可以提醒我們不要太快判斷舊物件。"},{"en":"The phrase introduces a warning or lesson.","zh":"這個片語引出警告或教訓。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":10},{"front":"take things for granted","meaning":"視事情為理所當然","examples":[{"en":"New art reminds us not to take things for granted.","zh":"新藝術提醒我們不要視事情為理所當然。"},{"en":"Take things for granted means assume something is normal, obvious, or guaranteed without thinking carefully about it.","zh":"take things for granted 指不仔細思考就假定某事正常、明顯或必然存在。"},{"en":"Students may take clean classrooms for granted until they help the janitors for a day.","zh":"學生可能把乾淨課室視為理所當然，直到他們幫清潔工一天。"},{"en":"If we take old categories for granted, we may miss the value of unfamiliar objects.","zh":"如果我們把舊分類視為理所當然，可能錯過陌生物件的價值。"},{"en":"The phrase warns against careless acceptance.","zh":"這個片語提醒人不要粗心接受。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":10},{"front":"take, for example","meaning":"以……為例","examples":[{"en":"Take, for example, the cast of the hand of a giant from a circus.","zh":"以一個馬戲團巨人的手部鑄模為例。"},{"en":"Take, for example means consider this example to understand the point.","zh":"take, for example 指考慮這個例子來理解觀點。"},{"en":"Take, for example, a student who improves after changing only one study habit.","zh":"以一名只改變一個學習習慣後進步的學生為例。"},{"en":"If a writer says “take, for example”, the next case should illustrate the argument.","zh":"如果作者說 take, for example，下一個案例應說明論點。"},{"en":"The phrase introduces a concrete example.","zh":"這個片語引出具體例子。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":10},{"front":"the cast of the hand","meaning":"手部鑄模","examples":[{"en":"The cast of the hand of a giant would now sit happily in a gallery.","zh":"一個巨人的手部鑄模如今可以很自然地出現在畫廊中。"},{"en":"The cast of the hand is a moulded copy of a hand.","zh":"the cast of the hand 指一隻手的鑄模複製品。"},{"en":"A museum might display the cast of a famous pianist’s hand to show its shape and size.","zh":"博物館可能展示著名鋼琴家的手部鑄模，以顯示其形狀和大小。"},{"en":"If a hand cast is unusual or expressive, viewers may respond to it like art.","zh":"如果手部鑄模不尋常或富表現力，觀眾可能像回應藝術一樣回應它。"},{"en":"The phrase refers to a physical reproduction of a hand.","zh":"這個片語指手的實體複製品。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":10},{"front":"a giant from a circus","meaning":"馬戲團巨人","examples":[{"en":"The cast shows the hand of a giant from a circus.","zh":"這個鑄模展示了一位馬戲團巨人的手。"},{"en":"A giant from a circus means an unusually large person who performed or was displayed in a circus.","zh":"a giant from a circus 指在馬戲團表演或被展示、身形異常巨大的人。"},{"en":"Old circus posters sometimes advertised people with unusual bodies as attractions.","zh":"舊馬戲團海報有時把身體不尋常的人宣傳為吸引點。"},{"en":"If a cast shows a circus giant’s hand, its size may immediately surprise viewers.","zh":"如果鑄模展示馬戲團巨人的手，其大小可能立即令觀眾驚訝。"},{"en":"The phrase gives the object a human and historical background.","zh":"這個片語給物件人性和歷史背景。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":11},{"front":"anonymous artist","meaning":"佚名藝術家","examples":[{"en":"The cast was made by an anonymous artist around 1889.","zh":"這個鑄模約於1889年由一位佚名藝術家製作。"},{"en":"An anonymous artist is an artist whose name is unknown or not recorded.","zh":"anonymous artist 指姓名不詳或未被記錄的藝術家。"},{"en":"Many old religious objects were made by anonymous artists whose skills still impress viewers.","zh":"許多舊宗教物件由佚名藝術家製作，其技巧仍令觀眾印象深刻。"},{"en":"If the maker is anonymous, viewers may focus more on the object than the person behind it.","zh":"如果製作者佚名，觀眾可能更集中於物件本身，而不是背後的人。"},{"en":"The phrase separates artistic value from fame or name recognition.","zh":"這個片語把藝術價值與名氣或姓名辨識分開。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":11},{"front":"sit happily in","meaning":"很自然地出現在……","examples":[{"en":"The cast would now sit happily in any commercial or public gallery.","zh":"這個鑄模如今會很自然地出現在任何商業或公共畫廊中。"},{"en":"Sit happily in means fit naturally and comfortably in a particular place or context.","zh":"sit happily in 指自然、合適而不突兀地出現在某地方或語境中。"},{"en":"A student’s poster could sit happily in a school exhibition if it is clear and thoughtful.","zh":"如果學生海報清晰又有思想，就可以很自然地出現在學校展覽中。"},{"en":"If a former scientific object now sits happily in a gallery, its category has changed.","zh":"如果原本的科學物件如今自然出現在畫廊中，其類別已經改變。"},{"en":"The phrase suggests that something no longer feels out of place.","zh":"這個片語暗示某物不再顯得不合適。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":11},{"front":"commercial or public gallery","meaning":"商業或公共畫廊","examples":[{"en":"The cast could now be shown in a commercial or public gallery.","zh":"這個鑄模如今可以在商業或公共畫廊展出。"},{"en":"A commercial or public gallery is a space where artworks are displayed for sale or for public viewing.","zh":"commercial or public gallery 指展示藝術品作出售或供公眾觀看的空間。"},{"en":"A young artist may first show work in a small commercial gallery before entering a public museum.","zh":"年輕藝術家可能先在小型商業畫廊展出作品，再進入公共博物館。"},{"en":"If a cast appears in either type of gallery, viewers are invited to treat it as art.","zh":"如果鑄模出現在任一類畫廊，觀眾就被邀請把它視為藝術。"},{"en":"The phrase covers both market-based and publicly funded art spaces.","zh":"這個片語涵蓋以市場為基礎和由公眾資助的藝術空間。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":11},{"front":"the most significant impact","meaning":"最重要的影響","examples":[{"en":"The most significant impact of the piece is on the eye.","zh":"這件作品最重要的影響是在視覺上。"},{"en":"The most significant impact means the strongest or most important effect.","zh":"the most significant impact 指最強或最重要的效果。"},{"en":"The most significant impact of a clear diagram may be that students understand the topic faster.","zh":"清晰圖表最重要的影響可能是學生更快理解主題。"},{"en":"If an object first affects the eye, its visual force may matter before its history.","zh":"如果物件首先影響眼睛，其視覺力量可能先於其歷史而重要。"},{"en":"The phrase identifies the main effect among several possible effects.","zh":"這個片語指出多個可能效果中的主要效果。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":11},{"front":"on the eye","meaning":"在視覺上","examples":[{"en":"The most significant impact of the cast is on the eye.","zh":"這個鑄模最重要的影響是在視覺上。"},{"en":"On the eye means affecting the viewer visually.","zh":"on the eye 指在視覺上影響觀眾。"},{"en":"Bright colours in a poster have an immediate effect on the eye.","zh":"海報中的鮮色會立即對眼睛產生影響。"},{"en":"If a sculpture is unusually large, its first impact may be on the eye before the mind interprets it.","zh":"如果雕塑異常巨大，其第一個影響可能是視覺上的，然後思想才開始詮釋。"},{"en":"The phrase focuses on visual response.","zh":"這個片語集中於視覺反應。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":11},{"front":"the contradiction between","meaning":"……之間的矛盾","examples":[{"en":"The piece shows a contradiction between unexpected size and verisimilitude.","zh":"這件作品顯示出乎意料的大小與逼真感之間的矛盾。"},{"en":"The contradiction between two things is the tension created when they seem not to fit together.","zh":"the contradiction between two things 指兩件事看似不相容而產生的張力。"},{"en":"A luxury shop in a poor neighbourhood may create a contradiction between wealth and hardship.","zh":"貧困社區中的豪華商店可能造成財富與困苦之間的矛盾。"},{"en":"If a cast is both huge and realistic, viewers may feel surprise because the two qualities clash.","zh":"如果鑄模既巨大又逼真，觀眾可能因兩種特質衝突而感到驚訝。"},{"en":"The phrase highlights opposing features within one object.","zh":"這個片語突出一件物件內部的對立特徵。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":11},{"front":"unexpected size","meaning":"出乎意料的大小","examples":[{"en":"The hand’s unexpected size attracts the viewer’s attention.","zh":"這隻手出乎意料的大小吸引觀眾注意。"},{"en":"Unexpected size means a size that surprises people because it is much larger or smaller than expected.","zh":"unexpected size 指因遠大於或遠小於預期而令人驚訝的尺寸。"},{"en":"A tiny phone beside a huge old computer creates surprise through unexpected size.","zh":"一部小手機放在巨大舊電腦旁，會透過出乎意料的大小造成驚訝。"},{"en":"If a hand cast is much larger than normal, viewers immediately notice it.","zh":"如果手部鑄模比正常大得多，觀眾會立即注意到。"},{"en":"The phrase describes surprise caused by scale.","zh":"這個片語描述由比例大小造成的驚訝。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":11},{"front":"verisimilitude","meaning":"逼真感","examples":[{"en":"The cast’s verisimilitude makes the giant’s hand seem real.","zh":"這個鑄模的逼真感令巨人的手看似真實。"},{"en":"Verisimilitude means the quality of seeming true, real, or lifelike.","zh":"verisimilitude 指看似真實、可信或栩栩如生的特質。"},{"en":"A film has verisimilitude when its characters speak and behave like real people.","zh":"當電影角色說話和行為像真人一樣，電影就有逼真感。"},{"en":"If a cast has strong verisimilitude, viewers may feel they are looking at the actual hand.","zh":"如果鑄模有強烈逼真感，觀眾可能覺得自己正在看真正的手。"},{"en":"The word is formal and often used in art and literature.","zh":"這個詞較正式，常用於藝術和文學。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":11},{"front":"the human element kicks in","meaning":"人性元素開始發揮作用","examples":[{"en":"After seeing the hand’s size, the human element kicks in.","zh":"看見手的大小後，人性元素開始發揮作用。"},{"en":"The human element kicks in means emotional or personal human response begins to matter.","zh":"the human element kicks in 指情感或個人化的人類反應開始變得重要。"},{"en":"A report may seem like numbers at first, but the human element kicks in when we hear a family’s story.","zh":"報告起初可能只是數字，但當我們聽到一家人的故事時，人性元素就開始發揮作用。"},{"en":"If viewers realise the huge hand belonged to a real person, sympathy and curiosity may begin.","zh":"如果觀眾意識到巨大的手屬於真人，同情和好奇可能開始出現。"},{"en":"The phrase marks the moment feeling enters judgement.","zh":"這個片語標示情感進入判斷的一刻。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":11},{"front":"dirt-encrusted","meaning":"佈滿污垢的","examples":[{"en":"The nails are dirt-encrusted in the cast of the giant’s hand.","zh":"在巨人的手部鑄模中，指甲佈滿污垢。"},{"en":"Dirt-encrusted means covered with a hard or visible layer of dirt.","zh":"dirt-encrusted 指被一層硬化或明顯的污垢覆蓋。"},{"en":"A gardener’s boots may be dirt-encrusted after working in wet soil.","zh":"園丁在濕泥中工作後，靴子可能佈滿污垢。"},{"en":"If nails are dirt-encrusted, the cast suggests labour, body, and real human life.","zh":"如果指甲佈滿污垢，鑄模就暗示勞動、身體和真實人類生活。"},{"en":"The word gives a strong physical detail.","zh":"這個詞提供強烈的身體細節。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":12},{"front":"decorative addition","meaning":"裝飾性添加","examples":[{"en":"The dirt may be the caster’s decorative addition.","zh":"污垢可能是鑄模者的裝飾性添加。"},{"en":"A decorative addition is an extra detail added to improve appearance or effect.","zh":"decorative addition 指為改善外觀或效果而加入的額外細節。"},{"en":"A student may add a border to a poster as a decorative addition.","zh":"學生可能在海報上加邊框作為裝飾性添加。"},{"en":"If dirt was added deliberately, the caster made a visual choice, not just a mechanical copy.","zh":"如果污垢是刻意加上，鑄模者就作出了視覺選擇，而不只是機械複製。"},{"en":"The phrase shows that arrangement and intention may be involved.","zh":"這個片語顯示可能涉及安排和意圖。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":12},{"front":"fingertips extend far beyond","meaning":"指尖遠遠伸出","examples":[{"en":"The fingertips extend far beyond the nails.","zh":"指尖遠遠伸出指甲之外。"},{"en":"Fingertips extend far beyond means the ends of the fingers reach much farther than another part, such as the nails.","zh":"fingertips extend far beyond 指手指末端比另一部分，例如指甲，伸得遠得多。"},{"en":"In a drawing, long fingertips extending beyond the nails may make a hand look strange or delicate.","zh":"在繪畫中，遠遠伸出指甲外的長指尖可能令手看起來奇怪或纖細。"},{"en":"If the fingertips extend beyond the nails unusually, viewers notice the body’s difference.","zh":"如果指尖異常地伸出指甲之外，觀眾會注意到身體差異。"},{"en":"The phrase describes a visible physical proportion.","zh":"這個片語描述可見的身體比例。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":12},{"front":"take in","meaning":"注意到；理解","examples":[{"en":"The viewer then takes in the element of choice and arrangement.","zh":"觀眾接着注意到選擇和佈置的元素。"},{"en":"Take in means notice, understand, or absorb information gradually.","zh":"take in 指逐漸注意、理解或吸收資訊。"},{"en":"Students may need a few minutes to take in a complicated diagram.","zh":"學生可能需要幾分鐘才能理解複雜圖表。"},{"en":"If viewers take in small details, they may realise the object involved artistic decisions.","zh":"如果觀眾注意到細節，可能意識到物件涉及藝術決定。"},{"en":"The phrase describes careful noticing or understanding.","zh":"這個片語描述仔細注意或理解。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":12},{"front":"the element of choice","meaning":"選擇的元素","examples":[{"en":"The cast includes an element of choice, arrangement and art.","zh":"這個鑄模包含選擇、佈置和藝術的元素。"},{"en":"The element of choice means a part of the work that shows someone selected or decided something deliberately.","zh":"the element of choice 指作品中顯示某人曾有意選擇或決定的部分。"},{"en":"A photograph includes an element of choice because the photographer chooses angle and timing.","zh":"攝影包含選擇的元素，因為攝影師選擇角度和時間。"},{"en":"If a cast includes choice, it is not purely automatic copying.","zh":"如果鑄模包含選擇，它就不只是純粹自動複製。"},{"en":"The phrase points to human decision-making inside the work.","zh":"這個片語指出作品中的人為決策。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":12},{"front":"arrangement","meaning":"佈置；安排","examples":[{"en":"The sleeve-end gives the item balance and variation.","zh":"袖口為該物件帶來平衡感和變化。"},{"en":"Arrangement means the way parts of something are placed or organised.","zh":"arrangement 指某物各部分被放置或組織的方式。"},{"en":"A flower arrangement looks better when colours, height, and empty space are planned.","zh":"如果花藝佈置中的顏色、高度和留白經過規劃，就會更好看。"},{"en":"If the sleeve-end is included carefully, the cast may feel balanced rather than accidental.","zh":"如果袖口被仔細包括在內，鑄模可能感覺平衡，而不是偶然。"},{"en":"The word shows that visual organisation can create artistic effect.","zh":"這個詞顯示視覺組織可以創造藝術效果。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":12},{"front":"if you like","meaning":"可以說；如果你願意這樣說","examples":[{"en":"There is an element of choice, arrangement and art, if you like.","zh":"可以說，當中有選擇、佈置和藝術的元素。"},{"en":"If you like means if you want to describe it that way or accept that wording.","zh":"if you like 指如果你願意以那種方式描述或接受那種說法。"},{"en":"This school corner is a tiny library, if you like, because students borrow books from it every day.","zh":"這個學校角落可以說是一個小圖書館，因為學生每天從那裡借書。"},{"en":"If a writer says “if you like”, they are offering a possible way to frame the idea.","zh":"如果作者說 if you like，就是提供一種可能的理解方式。"},{"en":"The phrase softens a description and invites agreement.","zh":"這個片語緩和描述並邀請認同。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":12},{"front":"neat, pleated, buttoned sleeve-end","meaning":"整齊、有褶、有鈕扣的袖口","examples":[{"en":"The neat, pleated, buttoned sleeve-end gives the item balance.","zh":"整齊、有褶、有鈕扣的袖口為該物件帶來平衡。"},{"en":"A neat, pleated, buttoned sleeve-end is a tidy end of a sleeve with folds and buttons.","zh":"neat, pleated, buttoned sleeve-end 指整潔、有褶痕和鈕扣的袖子末端。"},{"en":"A costume designer may use a neat sleeve-end to make clothing look formal and controlled.","zh":"服裝設計師可能使用整齊袖口，使衣服看起來正式而受控。"},{"en":"If the sleeve-end is included in the cast, the object gains texture and visual order.","zh":"如果袖口被包括在鑄模中，物件就獲得質感和視覺秩序。"},{"en":"The phrase gives precise detail about clothing and presentation.","zh":"這個片語提供關於衣物和呈現方式的精確細節。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":12},{"front":"balance and variation of texture","meaning":"平衡感和質感變化","examples":[{"en":"The sleeve-end gives the item balance and variation of texture.","zh":"袖口為該物件帶來平衡感和質感變化。"},{"en":"Balance and variation of texture means visual stability plus differences in surface feel or appearance.","zh":"balance and variation of texture 指視覺穩定感加上表面感覺或外觀的差異。"},{"en":"A poster may use balance and texture variation by placing smooth photos beside rough handwriting.","zh":"海報可以把平滑照片放在粗糙手寫字旁，形成平衡感和質感變化。"},{"en":"If a cast includes both skin and cloth, the different textures make it more visually interesting.","zh":"如果鑄模同時包括皮膚和布料，不同質感會令它在視覺上更有趣。"},{"en":"The phrase explains how small details can improve composition.","zh":"這個片語解釋小細節如何改善構圖。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":12},{"front":"a moulded hand","meaning":"鑄模手","examples":[{"en":"This is just a moulded hand, yet it suggests the whole person.","zh":"這只是一隻鑄模手，卻暗示整個人。"},{"en":"A moulded hand is a hand shape reproduced by casting material such as plaster.","zh":"a moulded hand 指用石膏等鑄造材料複製出來的手部形狀。"},{"en":"A museum might display a moulded hand to show the body of a person who is no longer alive.","zh":"博物館可能展示鑄模手，以顯示一位已不在人世者的身體。"},{"en":"If a moulded hand suggests personality or history, it becomes more than a simple copy.","zh":"如果鑄模手暗示性格或歷史，它就不只是簡單複製品。"},{"en":"The phrase refers to a cast body part.","zh":"這個片語指被鑄造出來的身體部位。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":12},{"front":"stand utterly for","meaning":"完全代表","examples":[{"en":"The part stands utterly for the whole.","zh":"部分完全代表整體。"},{"en":"Stand utterly for means completely represent something larger.","zh":"stand utterly for 指完全代表更大的事物。"},{"en":"A single school badge can stand for the history and identity of the whole school.","zh":"一枚校徽可以代表整間學校的歷史和身份。"},{"en":"If one hand suggests an entire person, the part is representing the whole body and life.","zh":"如果一隻手暗示整個人，該部分就是代表整個身體和人生。"},{"en":"The phrase describes powerful symbolic representation.","zh":"這個片語描述強而有力的象徵代表。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":13},{"front":"the whole","meaning":"整體","examples":[{"en":"The moulded hand stands for the whole person.","zh":"鑄模手代表整個人。"},{"en":"The whole means the complete person, object, or idea rather than only one part.","zh":"the whole 指完整的人、物件或概念，而不只是其中一部分。"},{"en":"A single family photograph can remind someone of the whole childhood.","zh":"一張家庭照片可以令人想起整個童年。"},{"en":"If one part suggests the whole, viewers mentally complete what is missing.","zh":"如果一部分暗示整體，觀眾會在心中補完整缺失部分。"},{"en":"The phrase contrasts complete meaning with partial detail.","zh":"這個片語把完整意義與局部細節作對比。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":13},{"front":"remind us slyly","meaning":"巧妙地提醒我們","examples":[{"en":"The cast reminds us slyly of the full-size original.","zh":"這個鑄模巧妙地提醒我們原本真人大小的對象。"},{"en":"Remind us slyly means quietly or cleverly make us think of something without stating it directly.","zh":"remind us slyly 指不直接說明，而是悄悄或巧妙地令我們想起某事。"},{"en":"A small smell of food can slyly remind someone of childhood without any explanation.","zh":"一點食物氣味可以不用解釋就巧妙地令人想起童年。"},{"en":"If a hand cast hints at the full person, it reminds viewers indirectly and cleverly.","zh":"如果手部鑄模暗示完整人物，它就是間接而巧妙地提醒觀眾。"},{"en":"The phrase suggests subtle, intelligent prompting.","zh":"這個片語暗示微妙而聰明的提示。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":13},{"front":"poignantly","meaning":"令人感傷地","examples":[{"en":"The cast reminds us poignantly of the full-size original.","zh":"這個鑄模令人感傷地提醒我們原本真人大小的對象。"},{"en":"Poignantly means in a way that causes deep feeling, often sadness or tenderness.","zh":"poignantly 指以引起深刻感受的方式，通常帶悲傷或溫柔情感。"},{"en":"A child’s empty school desk can poignantly remind classmates of someone who has moved away.","zh":"孩子的空課桌可以令人感傷地提醒同學一位已搬走的人。"},{"en":"If an object suggests a real absent person, it may affect viewers emotionally.","zh":"如果物件暗示一個真實但缺席的人，它可能在情感上影響觀眾。"},{"en":"The word adds emotional depth to a description.","zh":"這個詞為描述加入情感深度。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":13},{"front":"full-size original","meaning":"原本真人大小的對象","examples":[{"en":"The cast reminds us of the full-size original person.","zh":"這個鑄模提醒我們原本真人大小的人。"},{"en":"Full-size original means the real person or object at its actual size before being copied.","zh":"full-size original 指被複製前實際大小的真人或物件。"},{"en":"A toy model of a train is much smaller than the full-size original.","zh":"玩具火車模型比原本實物小得多。"},{"en":"If a cast is life-size, viewers may imagine the full-size original standing before them.","zh":"如果鑄模是真人大小，觀眾可能想像原本對象站在面前。"},{"en":"The phrase contrasts the copy with the real source.","zh":"這個片語把複製品與真實來源作對比。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":13},{"front":"tediously repeated questions","meaning":"乏味地反覆提出的問題","examples":[{"en":"Whether something is art is one of the old, tediously repeated questions.","zh":"某物是否是藝術，是那些古老而乏味地反覆提出的問題之一。"},{"en":"Tediously repeated questions are questions asked so often that they become boring or tiring.","zh":"tediously repeated questions 指因太常被問而變得沉悶或令人疲累的問題。"},{"en":"“Will this be in the exam?” can become a tediously repeated question in class.","zh":"「這會考嗎？」可以成為課堂中乏味地反覆提出的問題。"},{"en":"If a debate returns again and again without a final answer, it may feel tedious.","zh":"如果辯論一次又一次回來卻沒有最終答案，就可能令人感到厭煩。"},{"en":"The phrase shows impatience with an overused question.","zh":"這個片語顯示對過度使用問題的不耐煩。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":13},{"front":"respond that","meaning":"回應說","examples":[{"en":"Artists have often responded that their work is art because they are artists.","zh":"藝術家常回應說，他們的作品是藝術，因為他們是藝術家。"},{"en":"Respond that means answer by saying a particular statement.","zh":"respond that 指以某特定陳述作回答。"},{"en":"When asked why he was late, the student responded that the bus had broken down.","zh":"被問到為何遲到時，學生回應說巴士壞了。"},{"en":"If artists respond that their identity makes the work art, they are using status as an argument.","zh":"如果藝術家回應說其身份令作品成為藝術，他們就是把身份用作論據。"},{"en":"The phrase introduces someone’s answer or explanation.","zh":"這個片語引出某人的回答或解釋。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":13},{"front":"what doesn’t work for literature","meaning":"對文學不適用的東西","examples":[{"en":"What does not work for literature works much better for art.","zh":"對文學不適用的東西，對藝術卻更有效。"},{"en":"What doesn’t work for literature means an argument or method that is ineffective when applied to literature.","zh":"what doesn’t work for literature 指用於文學時無效的論點或方法。"},{"en":"Saying “this is good because I wrote it” does not work well for literature.","zh":"說「這很好，因為是我寫的」對文學並不太適用。"},{"en":"If authorship cannot prove a novel’s value, readers still need to judge the text itself.","zh":"如果作者身份不能證明小說價值，讀者仍需要判斷文本本身。"},{"en":"The phrase contrasts how different art forms are evaluated.","zh":"這個片語比較不同藝術形式如何被評價。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":13},{"front":"work much better for","meaning":"對……更有效","examples":[{"en":"The argument works much better for art than for literature.","zh":"這個論點對藝術比對文學更有效。"},{"en":"Work much better for means be more effective or convincing in one area than another.","zh":"work much better for 指在某一領域比另一領域更有效或更有說服力。"},{"en":"Visual examples work much better for young learners than long abstract explanations.","zh":"對年幼學習者來說，視覺例子比長篇抽象解釋更有效。"},{"en":"If an argument suits gallery art better than novels, it may depend on visual context.","zh":"如果一個論點較適合畫廊藝術而不是小說，它可能依賴視覺語境。"},{"en":"The phrase compares usefulness across situations.","zh":"這個片語比較在不同情況中的有用程度。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":13},{"front":"works of art","meaning":"藝術作品","examples":[{"en":"Works of art can float free of their creators’ intentions.","zh":"藝術作品可以擺脫創作者的意圖。"},{"en":"Works of art are objects, images, performances, or creations valued as art.","zh":"works of art 指被視為藝術的物件、影像、表演或創作。"},{"en":"Paintings, sculptures, films, and installations can all be works of art.","zh":"繪畫、雕塑、電影和裝置都可以是藝術作品。"},{"en":"If works of art survive long after their makers, new viewers may find new meanings in them.","zh":"如果藝術作品在創作者之後長久保存，新觀眾可能在其中找到新意義。"},{"en":"The phrase refers to artistic creations rather than ordinary objects only.","zh":"這個片語指藝術創作，而不只是普通物件。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":13},{"front":"float free of","meaning":"擺脫；不再受……束縛","examples":[{"en":"Works of art float free of their creators’ intentions.","zh":"藝術作品可以擺脫創作者的意圖。"},{"en":"Float free of means become independent from something that once controlled or defined it.","zh":"float free of 指變得獨立於曾控制或定義它的事物。"},{"en":"A song can float free of its original purpose when later generations use it for new causes.","zh":"一首歌在後代把它用於新理念時，可以擺脫其原本用途。"},{"en":"If an artwork floats free of intention, viewers can create meanings the artist never planned.","zh":"如果藝術品擺脫原意，觀眾可以創造藝術家從未計劃的意思。"},{"en":"The phrase suggests release from original control.","zh":"這個片語暗示從原本控制中釋放。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":14},{"front":"creators’ intentions","meaning":"創作者的意圖","examples":[{"en":"Art can become independent of its creators’ intentions.","zh":"藝術可以變得獨立於創作者的意圖。"},{"en":"Creators’ intentions are what makers originally meant, planned, or wanted their work to do.","zh":"creators’ intentions 指創作者原本想表達、計劃或希望作品做到的事情。"},{"en":"A writer may intend a story to be funny, but readers may find it sad.","zh":"作家可能想讓故事有趣，但讀者可能覺得它悲傷。"},{"en":"If viewers respond differently from the artist’s plan, the work has moved beyond intention.","zh":"如果觀眾的反應不同於藝術家的計劃，作品就已超越意圖。"},{"en":"The phrase focuses on the maker’s original purpose.","zh":"這個片語集中於創作者的原本目的。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":14},{"front":"over time","meaning":"隨着時間過去","examples":[{"en":"Over time, the reader becomes more powerful.","zh":"隨着時間過去，讀者變得更有力量。"},{"en":"Over time means gradually as time passes.","zh":"over time 指隨時間逐漸地。"},{"en":"Over time, regular reading can make a student’s vocabulary much stronger.","zh":"隨着時間過去，定期閱讀可以令學生詞彙量強很多。"},{"en":"If meanings change over time, later viewers may control interpretation more than the original maker.","zh":"如果意義隨時間改變，後來觀眾可能比原作者更能控制詮釋。"},{"en":"The phrase describes gradual development.","zh":"這個片語描述逐漸發展。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":14},{"front":"the reader","meaning":"讀者；觀者","examples":[{"en":"Over time, the reader or viewer becomes more powerful.","zh":"隨着時間過去，讀者或觀者變得更有力量。"},{"en":"The reader is the person who reads a text and interprets its meaning.","zh":"the reader 指閱讀文本並詮釋其意思的人。"},{"en":"A reader may understand a poem differently after experiencing loss or love.","zh":"讀者經歷失去或愛之後，可能以不同方式理解一首詩。"},{"en":"If the reader brings new experiences, an old text can gain new meaning.","zh":"如果讀者帶來新經驗，舊文本可以獲得新意義。"},{"en":"The phrase can stand for the audience’s role in interpretation.","zh":"這個片語可以代表觀眾在詮釋中的角色。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":14},{"front":"medieval altarpiece","meaning":"中世紀祭壇畫","examples":[{"en":"Few of us can look at a medieval altarpiece as its painter intended.","zh":"我們很少人能如畫家原本所意圖那樣看中世紀祭壇畫。"},{"en":"A medieval altarpiece is a religious artwork placed behind or above an altar in the Middle Ages.","zh":"medieval altarpiece 指中世紀放在祭壇後方或上方的宗教藝術品。"},{"en":"A museum may display a medieval altarpiece as art, even though it was first made for worship.","zh":"博物館可能把中世紀祭壇畫作為藝術展出，即使它最初為崇拜而製作。"},{"en":"If modern viewers do not share medieval beliefs, they cannot see it exactly as original worshippers did.","zh":"如果現代觀眾不共享中世紀信仰，就不能完全像原本崇拜者那樣觀看它。"},{"en":"The phrase gives an example of old religious art with changed meaning.","zh":"這個片語提供舊宗教藝術意義改變的例子。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":14},{"front":"as its painter intended","meaning":"如畫家原本所意圖的那樣","examples":[{"en":"We cannot see a medieval altarpiece exactly as its painter intended.","zh":"我們不能完全如畫家原本所意圖的那樣觀看中世紀祭壇畫。"},{"en":"As its painter intended means in the way the painter originally wanted viewers to see or understand it.","zh":"as its painter intended 指以畫家原本希望觀眾觀看或理解它的方式。"},{"en":"A song used in an advertisement may no longer be heard as its composer intended.","zh":"一首被用於廣告的歌曲，可能不再如作曲家原本所意圖那樣被聽見。"},{"en":"If culture changes, original intention may become difficult to recover.","zh":"如果文化改變，原本意圖可能變得難以追回。"},{"en":"The phrase connects viewing with the maker’s original purpose.","zh":"這個片語把觀看與創作者原本目的連接起來。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":14},{"front":"aesthetically know too much","meaning":"在美學上知道得太多","examples":[{"en":"Modern viewers believe too little and aesthetically know too much.","zh":"現代觀眾相信得太少，卻在美學上知道得太多。"},{"en":"Aesthetically know too much means have so much art knowledge that one cannot respond in the original simple way.","zh":"aesthetically know too much 指擁有太多藝術知識，以致無法以原本簡單方式回應。"},{"en":"A film critic may aesthetically know too much to watch a children’s cartoon innocently.","zh":"影評人可能在美學上知道得太多，難以天真地觀看兒童動畫。"},{"en":"If viewers know many art movements, they may analyse instead of worshipping or believing.","zh":"如果觀眾知道很多藝術運動，他們可能會分析，而不是崇拜或相信。"},{"en":"The phrase suggests that knowledge can change emotional response.","zh":"這個片語暗示知識可以改變情感反應。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":14},{"front":"recreate","meaning":"重新創造；重新理解","examples":[{"en":"We recreate older works and find new pleasures in them.","zh":"我們重新理解較舊作品，並在其中找到新的欣賞樂趣。"},{"en":"Recreate means create again in the mind, interpretation, or experience.","zh":"recreate 指在思想、詮釋或體驗中再次創造。"},{"en":"A director may recreate an old story by setting it in a modern city.","zh":"導演可能把舊故事放在現代城市中重新創造。"},{"en":"If viewers bring new values to old art, they mentally recreate its meaning.","zh":"如果觀眾把新價值帶入舊藝術，就在心中重新創造其意義。"},{"en":"The word can mean physically remake something or reinterpret it imaginatively.","zh":"這個詞可以指實際重製，也可以指想像式重新詮釋。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":14},{"front":"new fields of pleasure","meaning":"新的欣賞樂趣","examples":[{"en":"Viewers find new fields of pleasure in old artworks.","zh":"觀眾在舊藝術品中找到新的欣賞樂趣。"},{"en":"New fields of pleasure means new ways or areas of enjoyment and appreciation.","zh":"new fields of pleasure 指新的享受和欣賞方式或領域。"},{"en":"A student may find new pleasure in poetry after learning how rhythm works.","zh":"學生學會節奏如何運作後，可能在詩歌中找到新的樂趣。"},{"en":"If old objects are viewed differently, they can open fresh areas of interest.","zh":"如果舊物件被以不同方式觀看，它們可以開啟新的興趣領域。"},{"en":"The phrase suggests that appreciation can expand over time.","zh":"這個片語暗示欣賞可以隨時間擴展。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":14},{"front":"lack of artistic intention","meaning":"缺乏藝術意圖","examples":[{"en":"The lack of artistic intention in some craftsmen is now irrelevant.","zh":"一些工匠缺乏藝術意圖，如今已不相關。"},{"en":"Lack of artistic intention means the maker did not originally aim to create art.","zh":"lack of artistic intention 指製作者原本並沒有打算創造藝術。"},{"en":"A worker who designs a useful chair may lack artistic intention, but the chair can still be admired later.","zh":"設計實用椅子的工人可能缺乏藝術意圖，但椅子後來仍可被欣賞。"},{"en":"If viewers respond strongly to an object, original intention may matter less.","zh":"如果觀眾對物件有強烈反應，原本意圖可能較不重要。"},{"en":"The phrase separates the maker’s purpose from the object’s later value.","zh":"這個片語把製作者目的與物件後來價值分開。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":14},{"front":"forgotten craftsmen","meaning":"被遺忘的工匠","examples":[{"en":"Forgotten craftsmen made and decorated life-casts in the nineteenth century.","zh":"被遺忘的工匠在十九世紀製作和裝飾生活鑄模。"},{"en":"Forgotten craftsmen are skilled makers whose names or reputations have not survived.","zh":"forgotten craftsmen 指姓名或聲譽沒有流傳下來的熟練製作者。"},{"en":"Many old buildings were shaped by forgotten craftsmen who carved doors, tiles, and windows.","zh":"許多舊建築由雕刻門、瓦片和窗戶的被遺忘工匠塑造。"},{"en":"If craftsmen are forgotten, their objects may still remain and affect viewers.","zh":"如果工匠被遺忘，其物件仍可能保存並影響觀眾。"},{"en":"The phrase honours skill even when the maker’s identity is lost.","zh":"這個片語即使在製作者身份消失時，也尊重其技巧。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":15},{"front":"brush oil onto flesh","meaning":"把油塗在皮膚上","examples":[{"en":"Some craftsmen brushed oil onto flesh before making casts.","zh":"有些工匠在製作鑄模前把油塗在皮膚上。"},{"en":"Brush oil onto flesh means apply oil to skin with a brush.","zh":"brush oil onto flesh 指用刷子把油塗在皮膚上。"},{"en":"A therapist may brush oil onto skin before a massage to reduce friction.","zh":"治療師可能在按摩前把油塗在皮膚上，以減少摩擦。"},{"en":"If oil is brushed onto flesh before casting, plaster may separate more safely from the body.","zh":"如果在鑄模前把油塗在皮膚上，石膏可能較安全地與身體分離。"},{"en":"The phrase describes a practical preparation step.","zh":"這個片語描述實用準備步驟。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":15},{"front":"mould, cast and decorate","meaning":"製模、鑄造和裝飾","examples":[{"en":"The craftsmen moulded, cast and decorated objects.","zh":"工匠製模、鑄造和裝飾物件。"},{"en":"Mould, cast and decorate means shape a form, produce a copy, and add visual finishing details.","zh":"mould, cast and decorate 指塑造模具、製作複製品並加入視覺修飾細節。"},{"en":"In an art workshop, students may mould clay, cast it in plaster, and decorate the final piece.","zh":"在藝術工作坊中，學生可能製作泥模、用石膏鑄造，再裝飾成品。"},{"en":"If craftsmen do all three steps, their work involves both technique and visual judgement.","zh":"如果工匠完成三個步驟，其工作就涉及技術和視覺判斷。"},{"en":"The phrase lists the main actions in making finished casts.","zh":"這個片語列出製作完成鑄模的主要動作。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":15},{"front":"become irrelevant","meaning":"變得不相關","examples":[{"en":"The original lack of artistic intention has become irrelevant.","zh":"原本缺乏藝術意圖已變得不相關。"},{"en":"Become irrelevant means stop mattering or stop being important to the judgement.","zh":"become irrelevant 指不再重要，或不再影響判斷。"},{"en":"A student’s old mistake becomes irrelevant if the final project is corrected and strong.","zh":"如果最終項目已被改正並且出色，學生過去的錯誤就變得不相關。"},{"en":"If viewers now respond to an object as art, the maker’s original intention may no longer decide its value.","zh":"如果觀眾如今把物件當作藝術回應，製作者原本意圖可能不再決定其價值。"},{"en":"The phrase describes a loss of importance.","zh":"這個片語描述重要性喪失。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":15},{"front":"what counts is","meaning":"重要的是","examples":[{"en":"What counts is the surviving object and our response to it.","zh":"重要的是留存下來的物件和我們對它的反應。"},{"en":"What counts is means what really matters is.","zh":"what counts is 指真正重要的是。"},{"en":"In a speaking test, what counts is clear communication, not a perfect accent.","zh":"在口試中，重要的是清楚溝通，而不是完美口音。"},{"en":"If art survives and moves viewers, the original purpose may matter less.","zh":"如果藝術保存下來並打動觀眾，原本用途可能較不重要。"},{"en":"The phrase focuses attention on the most important factor.","zh":"這個片語把注意力集中於最重要因素。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":15},{"front":"the surviving object","meaning":"留存下來的物件","examples":[{"en":"The surviving object matters more than the maker’s intention.","zh":"留存下來的物件比製作者的意圖更重要。"},{"en":"The surviving object is the physical thing that remains after time has passed.","zh":"the surviving object 指時間過去後仍然存在的實體物件。"},{"en":"A broken bowl from an ancient village may be the surviving object historians study.","zh":"古村落中破碎的碗可能是歷史學家研究的留存物件。"},{"en":"If the maker’s name is lost, the surviving object may become the main evidence.","zh":"如果製作者名字遺失，留存下來的物件可能成為主要證據。"},{"en":"The phrase focuses on what still exists.","zh":"這個片語集中於仍然存在的東西。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":15},{"front":"our response to it","meaning":"我們對它的反應","examples":[{"en":"The importance of the object lies in our response to it.","zh":"物件的重要性在於我們對它的反應。"},{"en":"Our response to it means how we react, feel, think, or interpret when we see it.","zh":"our response to it 指我們看見它時如何反應、感受、思考或詮釋。"},{"en":"A simple photo may matter because of our response to it, especially if it recalls family memory.","zh":"一張簡單照片可能因我們對它的反應而重要，尤其如果它喚起家庭記憶。"},{"en":"If viewers are moved by an object, their response becomes part of its artistic value.","zh":"如果觀眾被物件打動，他們的反應就成為其藝術價值的一部分。"},{"en":"The phrase places importance on the audience.","zh":"這個片語把重要性放在觀眾身上。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":15},{"front":"interest the eye","meaning":"吸引視覺","examples":[{"en":"A work of art should interest the eye.","zh":"藝術作品應該吸引視覺。"},{"en":"Interest the eye means attract visual attention or make people want to look longer.","zh":"interest the eye 指吸引視覺注意，或令人想看久一點。"},{"en":"A poster with strong contrast and clear shapes can interest the eye quickly.","zh":"具有強烈對比和清晰形狀的海報可以迅速吸引視覺。"},{"en":"If an object does not interest the eye, viewers may pass it without noticing.","zh":"如果物件不吸引視覺，觀眾可能不注意就走過。"},{"en":"The phrase focuses on visual appeal.","zh":"這個片語集中於視覺吸引力。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":15},{"front":"excite the brain","meaning":"刺激大腦","examples":[{"en":"A work of art may excite the brain.","zh":"藝術作品可能刺激大腦。"},{"en":"Excite the brain means stimulate thought, curiosity, or intellectual interest.","zh":"excite the brain 指刺激思考、好奇心或智性興趣。"},{"en":"A puzzle can excite the brain because it makes students search for patterns.","zh":"謎題可以刺激大腦，因為它令學生尋找模式。"},{"en":"If an artwork raises questions, it may excite the brain as well as please the eye.","zh":"如果藝術品提出問題，它可能既愉悅眼睛，又刺激大腦。"},{"en":"The phrase describes mental stimulation.","zh":"這個片語描述思想上的刺激。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":15},{"front":"move the mind to reflection","meaning":"使人思考","examples":[{"en":"Art can move the mind to reflection.","zh":"藝術可以使人思考。"},{"en":"Move the mind to reflection means make someone think deeply and quietly about something.","zh":"move the mind to reflection 指令某人深沉而安靜地思考某事。"},{"en":"A film about old age may move the mind to reflection about family and time.","zh":"關於老年的電影可能令人思考家庭和時間。"},{"en":"If an artwork stays in your thoughts after you leave, it has moved you to reflection.","zh":"如果藝術品在你離開後仍留在腦海，它就已使你思考。"},{"en":"The phrase describes thoughtful response rather than quick entertainment.","zh":"這個片語描述有思想的反應，而不是快速娛樂。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":15},{"front":"involve the heart","meaning":"牽動情感","examples":[{"en":"A work of art can involve the heart.","zh":"藝術作品可以牽動情感。"},{"en":"Involve the heart means engage emotion, sympathy, or feeling.","zh":"involve the heart 指引發情感、同情或感受。"},{"en":"A song about home can involve the heart if listeners miss their families.","zh":"如果聽眾思念家人，一首關於家的歌可以牽動情感。"},{"en":"If an artwork makes viewers feel tenderness or grief, it involves the heart.","zh":"如果藝術品令觀眾感到溫柔或悲傷，它就牽動情感。"},{"en":"The phrase adds emotional response to visual and intellectual response.","zh":"這個片語在視覺和智性反應之外加入情感反應。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":16},{"front":"to use the old dichotomy","meaning":"用舊有二分法來說","examples":[{"en":"To use the old dichotomy, it may be beautiful but not deeply true.","zh":"用舊有二分法來說，它可能美麗，但在深層意義上不真實。"},{"en":"To use the old dichotomy means to apply an old two-part division or contrast.","zh":"to use the old dichotomy 指套用舊有的兩分法或對比。"},{"en":"To use the old dichotomy, a lesson may be useful but not inspiring.","zh":"用舊有二分法來說，一堂課可能有用但不啟發人。"},{"en":"If a critic divides art into beauty and truth, they are using a traditional contrast.","zh":"如果評論家把藝術分成美與真，就是在使用傳統對比。"},{"en":"The phrase introduces an old way of classifying ideas into two sides.","zh":"這個片語引入把思想分成兩邊的舊分類方式。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":16},{"front":"be true to any significant depth","meaning":"在深層意義上真實","examples":[{"en":"The object may be beautiful but rarely true to any significant depth.","zh":"該物件可能美麗，但很少在任何深層意義上真實。"},{"en":"Be true to any significant depth means express deep truth, not just surface beauty.","zh":"be true to any significant depth 指表達深層真實，而不只是表面美。"},{"en":"A speech may sound elegant but not be true in any deep way if it avoids real problems.","zh":"如果演講避開真正問題，它可能聽起來優雅，但在深層意義上並不真實。"},{"en":"If an artwork only looks attractive, it may not make viewers understand life more deeply.","zh":"如果藝術品只看起來吸引，它未必令觀眾更深入理解人生。"},{"en":"The phrase judges depth of meaning.","zh":"這個片語評價意義的深度。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":16},{"front":"constant pleasures of art","meaning":"藝術持續帶來的樂趣","examples":[{"en":"One of the constant pleasures of art is its ability to surprise us.","zh":"藝術持續帶來的樂趣之一，是它能夠令我們驚訝。"},{"en":"Constant pleasures of art are lasting forms of enjoyment that art repeatedly gives people.","zh":"constant pleasures of art 指藝術反覆帶給人們的持久享受。"},{"en":"One constant pleasure of reading is finding a sentence that says exactly what we feel.","zh":"閱讀持續帶來的樂趣之一，是找到一句正好說出我們感受的句子。"},{"en":"If art can still surprise viewers after centuries, its pleasure is not temporary.","zh":"如果藝術在數百年後仍能令觀眾驚訝，它的樂趣就不是短暫的。"},{"en":"The phrase points to joys that remain across time.","zh":"這個片語指出跨越時間仍存在的喜悅。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":16},{"front":"come at us from an unexpected angle","meaning":"從意想不到的角度觸動我們","examples":[{"en":"Art can come at us from an unexpected angle.","zh":"藝術可以從意想不到的角度觸動我們。"},{"en":"Come at us from an unexpected angle means affect us in a surprising way or from a viewpoint we did not expect.","zh":"come at us from an unexpected angle 指以令人意外的方式或從我們沒預期的角度影響我們。"},{"en":"A simple children’s story can come at adults from an unexpected angle when it reveals a serious truth.","zh":"當簡單兒童故事揭示嚴肅真相時，它可以從意想不到的角度觸動成年人。"},{"en":"If an old cast suddenly feels moving, art has approached us unexpectedly.","zh":"如果舊鑄模突然令人感動，藝術就是出其不意地接近我們。"},{"en":"The phrase describes surprise in how meaning reaches us.","zh":"這個片語描述意義如何令人意外地抵達我們。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":16},{"front":"stop us short in wonder","meaning":"令我們驚訝得停下來","examples":[{"en":"Art can stop us short in wonder.","zh":"藝術可以令我們驚訝得停下來。"},{"en":"Stop us short in wonder means make us suddenly pause because we are surprised or amazed.","zh":"stop us short in wonder 指因驚訝或讚嘆而令我們突然停下。"},{"en":"A beautiful sunset can stop people short in wonder on their way home.","zh":"美麗日落可以令回家路上的人驚訝得停下來。"},{"en":"If an artwork makes viewers pause and look again, it has interrupted ordinary attention.","zh":"如果藝術品令觀眾停下再看，它就打斷了日常注意力。"},{"en":"The phrase describes sudden astonished stillness.","zh":"這個片語描述因驚嘆而突然靜止。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":16},{"front":"Reading Passage 2","meaning":"閱讀文章二","examples":[{"en":"Reading Passage 2 has six paragraphs labelled A to F.","zh":"閱讀文章二有六段，標記為 A 至 F。"},{"en":"Reading Passage 2 means the second reading text in an exam or exercise.","zh":"Reading Passage 2 指考試或練習中的第二篇閱讀文本。"},{"en":"Students should check the paragraph labels carefully before answering questions about Reading Passage 2.","zh":"學生回答關於閱讀文章二的題目前，應小心查看段落標記。"},{"en":"If the passage has paragraphs A to F, answers may require locating information by paragraph.","zh":"如果文章有 A 至 F 段，答案可能需要按段落定位資料。"},{"en":"The phrase is an exam-text label, not part of the article’s argument.","zh":"這個片語是考試文本標籤，而不是文章論點的一部分。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":16},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"Students decide which paragraph contains each piece of information.","zh":"學生判斷哪一段包含每項資料。"},{"en":"Which paragraph contains asks where a particular detail appears in the passage.","zh":"which paragraph contains 詢問某個特定細節出現在文章哪一段。"},{"en":"In IELTS reading, students scan for names, dates, or key phrases to find which paragraph contains the answer.","zh":"在 IELTS 閱讀中，學生掃讀姓名、日期或關鍵短語，以找出哪一段包含答案。"},{"en":"If a paragraph contains the information, the answer should be its letter, not the full sentence.","zh":"如果某段包含該資料，答案應是其字母，而不是完整句子。"},{"en":"The phrase belongs to information-location questions.","zh":"這個片語屬於資料定位題。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":16},{"front":"the following information","meaning":"以下資料","examples":[{"en":"The task asks students to locate the following information.","zh":"任務要求學生定位以下資料。"},{"en":"The following information means the details listed immediately after the instruction.","zh":"the following information 指指示後面立即列出的細節。"},{"en":"A worksheet may ask students to find the following information: date, place, and speaker.","zh":"工作紙可能要求學生找出以下資料：日期、地點和講者。"},{"en":"If students know what information to locate, they can scan the passage more efficiently.","zh":"如果學生知道要定位甚麼資料，就能更有效地掃讀文章。"},{"en":"The phrase introduces a list of details to find.","zh":"這個片語引出要尋找的細節列表。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":16},{"front":"an example of","meaning":"……的一個例子","examples":[{"en":"The question asks for an example of a craftsman’s unsuccessful claim.","zh":"題目要求找出一個工匠失敗申索的例子。"},{"en":"An example of means a specific case that shows a general idea.","zh":"an example of 指顯示某個一般概念的具體案例。"},{"en":"A teacher may ask for an example of teamwork from students’ daily life.","zh":"老師可能要求學生從日常生活中舉出團隊合作的一個例子。"},{"en":"If a question asks for an example, students should find a concrete case in the passage.","zh":"如果題目要求例子，學生應在文章中找具體案例。"},{"en":"The phrase introduces evidence that illustrates a point.","zh":"這個片語引出說明觀點的證據。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":16},{"front":"unsuccessful claim to ownership","meaning":"對擁有權的失敗申索","examples":[{"en":"The moulder made an unsuccessful claim to ownership of his work.","zh":"製模工匠對自己作品的擁有權提出失敗申索。"},{"en":"An unsuccessful claim to ownership is an attempt to prove that one owns something, but the attempt fails.","zh":"unsuccessful claim to ownership 指試圖證明自己擁有某物，但該嘗試失敗。"},{"en":"A photographer may make an unsuccessful claim to ownership if they signed away the image rights.","zh":"如果攝影師已簽走影像權利，可能對擁有權提出失敗申索。"},{"en":"If a court rejects the claim, the maker cannot control copying or sale of the work.","zh":"如果法庭拒絕該申索，製作者就不能控制作品的複製或出售。"},{"en":"The phrase combines legal ownership with failure.","zh":"這個片語結合法律擁有權和失敗。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":17},{"front":"ownership of his work","meaning":"對自己作品的擁有權","examples":[{"en":"The craftsman claimed ownership of his work.","zh":"工匠聲稱擁有自己作品的權利。"},{"en":"Ownership of his work means the legal or moral right to control the work he made.","zh":"ownership of his work 指對自己製作的作品具有法律或道德上的控制權。"},{"en":"A designer may keep ownership of his work unless a contract gives it to the company.","zh":"設計師可能保留自己作品的擁有權，除非合約把它交給公司。"},{"en":"If ownership is denied, others may profit from the work without the maker’s control.","zh":"如果擁有權被否定，其他人可能在製作者無法控制下從作品獲利。"},{"en":"The phrase refers to control over one’s creation.","zh":"這個片語指對自己創作的控制權。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":17},{"front":"trends in art","meaning":"藝術趨勢","examples":[{"en":"Trends in art can change attitudes to earlier work.","zh":"藝術趨勢可以改變人們對較早期作品的態度。"},{"en":"Trends in art are popular directions, styles, or ideas that influence artistic practice at a certain time.","zh":"trends in art 指某時期影響藝術實踐的流行方向、風格或理念。"},{"en":"Minimalism was a trend in art that made people notice simplicity and space.","zh":"極簡主義是一種藝術趨勢，令人注意簡潔和空間。"},{"en":"If new trends value everyday objects, older practical objects may be appreciated differently.","zh":"如果新趨勢重視日常物件，較舊的實用物件可能被不同地欣賞。"},{"en":"The phrase describes changing patterns in artistic taste.","zh":"這個片語描述藝術品味中的變化模式。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":17},{"front":"change attitudes to","meaning":"改變對……的態度","examples":[{"en":"New movements can change attitudes to earlier work.","zh":"新運動可以改變人們對較早期作品的態度。"},{"en":"Change attitudes to means alter how people feel about or judge something.","zh":"change attitudes to 指改變人們如何感受或評價某事。"},{"en":"A strong documentary can change attitudes to homelessness by showing real personal stories.","zh":"有力紀錄片可以透過展示真實個人故事，改變人們對無家者的態度。"},{"en":"If a new art movement praises craft, people may judge old craft objects more positively.","zh":"如果新藝術運動讚賞工藝，人們可能更正面地評價舊工藝物件。"},{"en":"The phrase describes a shift in opinion.","zh":"這個片語描述意見上的轉變。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":17},{"front":"earlier work","meaning":"較早期的作品","examples":[{"en":"New art can make people look differently at earlier work.","zh":"新藝術可以令人以不同方式看待較早期的作品。"},{"en":"Earlier work means work created before the present work or before a later period.","zh":"earlier work 指在目前作品或後來時期之前創作的作品。"},{"en":"A writer’s earlier work may seem simple after readers know their later novels.","zh":"讀者知道作家的後期小說後，其較早期作品可能顯得簡單。"},{"en":"If new art changes standards, earlier work may gain new importance.","zh":"如果新藝術改變標準，較早期作品可能獲得新重要性。"},{"en":"The phrase compares past creations with later ones.","zh":"這個片語把過去創作與後來作品作比較。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":17},{"front":"original function","meaning":"原本功能","examples":[{"en":"The question asks about the original function of a particular type of art.","zh":"題目詢問某一類藝術的原本功能。"},{"en":"Original function means the first practical, religious, scientific, or social purpose of something.","zh":"original function 指某物最初的實用、宗教、科學或社會用途。"},{"en":"The original function of a school hall may be assembly, though it later becomes an exam room.","zh":"學校禮堂的原本功能可能是集會，雖然後來變成考場。"},{"en":"If an object’s original function was medical, later artistic use shows changing interpretation.","zh":"如果物件的原本功能是醫學，後來的藝術用途就顯示詮釋改變。"},{"en":"The phrase asks what something was first meant to do.","zh":"這個片語詢問某物最初被設計來做甚麼。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":17},{"front":"a particular type of art","meaning":"某一類藝術","examples":[{"en":"Life-casting is discussed as a particular type of art.","zh":"生活鑄模被作為某一類藝術討論。"},{"en":"A particular type of art means one specific form or category of artistic practice.","zh":"a particular type of art 指某一種特定形式或類別的藝術實踐。"},{"en":"Photography is a particular type of art that uses cameras and light.","zh":"攝影是一類使用相機和光線的藝術。"},{"en":"If a question names a particular art type, students should focus on that form only.","zh":"如果題目點名某一類藝術，學生應只集中於該形式。"},{"en":"The phrase narrows discussion from art in general to one form.","zh":"這個片語把討論從一般藝術收窄到某一形式。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":17},{"front":"ways of assessing whether","meaning":"評估是否……的方法","examples":[{"en":"The passage suggests ways of assessing whether an object is art.","zh":"文章提出評估某物件是否是藝術的方法。"},{"en":"Ways of assessing whether means methods for judging if something is true or belongs to a category.","zh":"ways of assessing whether 指判斷某事是否為真或是否屬於某類別的方法。"},{"en":"Teachers use different ways of assessing whether students understand, such as quizzes and discussion.","zh":"老師使用不同方法評估學生是否理解，例如小測和討論。"},{"en":"If we assess whether an object is art, we may look at skill, intention, response, and effect.","zh":"如果我們評估物件是否是藝術，可能看技巧、意圖、反應和效果。"},{"en":"The phrase introduces criteria for judgement.","zh":"這個片語引入判斷標準。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":17},{"front":"whether or not","meaning":"是否","examples":[{"en":"The question asks whether or not an object is art.","zh":"題目問一件物件是否是藝術。"},{"en":"Whether or not means if something is true or not true.","zh":"whether or not 指某事是真是假、是否成立。"},{"en":"A teacher may ask whether or not students need more practice before the exam.","zh":"老師可能問學生在考試前是否需要更多練習。"},{"en":"If people disagree whether or not something is art, they may be using different definitions.","zh":"如果人們對某物是否是藝術有分歧，他們可能使用不同定義。"},{"en":"The phrase presents two possibilities.","zh":"這個片語提出兩種可能性。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":17},{"front":"deal with","meaning":"處理","examples":[{"en":"The question asks how artists deal with less interesting aspects of their work.","zh":"題目問藝術家如何處理其工作中較乏味的方面。"},{"en":"Deal with means handle, manage, or respond to a task or problem.","zh":"deal with 指處理、管理或回應任務或問題。"},{"en":"Students deal with difficult vocabulary by using context and word families.","zh":"學生透過使用語境和詞族來處理困難詞彙。"},{"en":"If artists use assistants, that may be one way to deal with routine tasks.","zh":"如果藝術家使用助手，那可能是處理例行任務的一種方法。"},{"en":"The phrase focuses on practical handling.","zh":"這個片語集中於實際處理。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":17},{"front":"less interesting aspects","meaning":"較乏味的方面","examples":[{"en":"Artists often use assistants for the less interesting aspects of their work.","zh":"藝術家常使用助手處理工作中較乏味的方面。"},{"en":"Less interesting aspects are the parts of a task that feel dull, repetitive, or less creative.","zh":"less interesting aspects 指任務中較沉悶、重複或較不具創意的部分。"},{"en":"In a group project, formatting slides may be one of the less interesting aspects.","zh":"在小組項目中，格式化簡報可能是較乏味的方面之一。"},{"en":"If assistants handle these parts, the main artist can focus on composition and meaning.","zh":"如果助手處理這些部分，主要藝術家就能集中於構圖和意義。"},{"en":"The phrase does not mean unimportant; it means less engaging.","zh":"這個片語不是指不重要，而是指較不吸引人。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":18},{"front":"agree with the claims of","meaning":"與……的主張相符","examples":[{"en":"Students decide whether statements agree with the claims of the writer.","zh":"學生判斷陳述是否與作者的主張相符。"},{"en":"Agree with the claims of means match what someone argues or believes.","zh":"agree with the claims of 指與某人主張或相信的內容一致。"},{"en":"In reading exams, students check whether a statement agrees with the writer’s view, not their own opinion.","zh":"在閱讀考試中，學生檢查陳述是否同意作者觀點，而不是自己的看法。"},{"en":"If a statement changes the writer’s meaning, it does not agree with the claim.","zh":"如果陳述改變作者意思，就不與該主張相符。"},{"en":"The phrase is common in YES/NO/NOT GIVEN questions.","zh":"這個片語常見於 YES/NO/NOT GIVEN 題。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":18},{"front":"the claims of the writer","meaning":"作者的主張","examples":[{"en":"The task asks about the claims of the writer.","zh":"任務詢問作者的主張。"},{"en":"The claims of the writer are the views, arguments, or statements the writer presents as true.","zh":"the claims of the writer 指作者提出並視為真實的觀點、論點或陳述。"},{"en":"Students should underline sentences that show the writer’s claims before choosing YES or NO.","zh":"學生在選 YES 或 NO 前，應劃下顯示作者主張的句子。"},{"en":"If the passage only reports someone else’s view, that may not be the writer’s own claim.","zh":"如果文章只是報告別人的看法，那未必是作者自己的主張。"},{"en":"The phrase focuses on the writer’s position.","zh":"這個片語集中於作者立場。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":18},{"front":"if the statement agrees with","meaning":"如果陳述同意……","examples":[{"en":"Write YES if the statement agrees with the writer’s views.","zh":"如果陳述同意作者觀點，則寫 YES。"},{"en":"If the statement agrees with means if the statement has the same meaning as the source claim.","zh":"if the statement agrees with 指如果陳述與來源主張意思相同。"},{"en":"Students should choose YES only if the statement agrees with the passage exactly in meaning.","zh":"只有當陳述在意思上與文章完全一致時，學生才應選 YES。"},{"en":"If one small word changes the meaning, the statement may no longer agree.","zh":"如果一個小詞改變意思，陳述可能不再相符。"},{"en":"The phrase gives a condition for choosing an answer.","zh":"這個片語給出選答案的條件。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":18},{"front":"contradicts the views of","meaning":"與……的觀點相矛盾","examples":[{"en":"Write NO if the statement contradicts the views of the writer.","zh":"如果陳述與作者觀點相矛盾，則寫 NO。"},{"en":"Contradicts the views of means says the opposite of what someone believes or argues.","zh":"contradicts the views of 指說出與某人相信或主張相反的內容。"},{"en":"If a passage says life-casting can be art, a statement saying it can never be art contradicts the writer.","zh":"如果文章說生活鑄模可以是藝術，而陳述說它永遠不可能是藝術，就與作者觀點矛盾。"},{"en":"Students should choose NO only when the passage clearly shows the opposite meaning.","zh":"只有當文章清楚顯示相反意思時，學生才應選 NO。"},{"en":"The phrase describes direct conflict with a stated view.","zh":"這個片語描述與既定觀點的直接衝突。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":18},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"Write NOT GIVEN if it is impossible to say what the writer thinks.","zh":"如果無法判斷作者想法，則寫 NOT GIVEN。"},{"en":"Impossible to say means the information is not clear or not provided.","zh":"impossible to say 指資料不清楚或沒有提供。"},{"en":"If a passage mentions a museum but not its ticket price, the price is impossible to say from the text.","zh":"如果文章提到博物館但沒有提票價，就無法從文本判斷票價。"},{"en":"In reading tests, students should not guess when it is impossible to say from the passage.","zh":"在閱讀測驗中，如果無法從文章判斷，學生不應猜測。"},{"en":"The phrase marks lack of evidence.","zh":"這個片語標示缺乏證據。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":18},{"front":"admire the speed and realism of","meaning":"欣賞……的速度和寫實性","examples":[{"en":"The question asks whether sculptors admired the speed and realism of life-casting.","zh":"題目問雕塑家是否欣賞生活鑄模的速度和寫實性。"},{"en":"Admire the speed and realism of means respect how quickly and accurately something represents life.","zh":"admire the speed and realism of 指欣賞某物快速而準確呈現生活的能力。"},{"en":"Some teachers admire the speed and accuracy of digital marking, but still worry about judgement.","zh":"有些老師欣賞數碼批改的速度和準確性，但仍擔心判斷力問題。"},{"en":"If sculptors did not admire life-casting, they may have seen its speed as a weakness.","zh":"如果雕塑家不欣賞生活鑄模，他們可能把其速度視為弱點。"},{"en":"The phrase combines praise for efficiency and exactness.","zh":"這個片語結合對效率和精確性的讚賞。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":18},{"front":"improve if","meaning":"如果……便會改善","examples":[{"en":"The question asks whether life-casting would improve if the process were slower.","zh":"題目問如果過程較慢，生活鑄模是否會改善。"},{"en":"Improve if means become better under a certain condition.","zh":"improve if 指在某條件下變得更好。"},{"en":"A student’s writing may improve if they plan before starting each essay.","zh":"如果學生每次寫文章前先計劃，寫作可能會改善。"},{"en":"If speed is the problem, slowing the process might seem like a possible improvement.","zh":"如果速度是問題，放慢過程可能看似一種可能改善。"},{"en":"The phrase connects a condition with a possible better result.","zh":"這個片語把條件與可能更好結果連接起來。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":18},{"front":"decline with the development of","meaning":"隨着……的發展而衰落","examples":[{"en":"The question asks whether painting declined with the development of colour photography.","zh":"題目問繪畫是否隨着彩色攝影的發展而衰落。"},{"en":"Decline with the development of means become weaker or less important as something new grows.","zh":"decline with the development of 指隨着新事物發展而變弱或變得較不重要。"},{"en":"Letter writing declined with the development of instant messaging.","zh":"書信寫作隨着即時通訊的發展而衰落。"},{"en":"If painting did not decline after photography improved, it proved stronger than critics feared.","zh":"如果攝影改進後繪畫沒有衰落，就證明它比批評者擔心的更強。"},{"en":"The phrase links one thing’s weakening with another thing’s rise.","zh":"這個片語把一件事的減弱與另一件事的興起連接起來。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":18},{"front":"colour photography","meaning":"彩色攝影","examples":[{"en":"Gauguin worried about the future development of colour photography.","zh":"Gauguin 擔心彩色攝影的未來發展。"},{"en":"Colour photography is photography that records or produces images in colour rather than black and white.","zh":"colour photography 指記錄或製作彩色而非黑白影像的攝影。"},{"en":"Colour photography changed family albums because people could preserve clothes, rooms, and landscapes more vividly.","zh":"彩色攝影改變了家庭相冊，因為人們可以更生動地保存衣服、房間和風景。"},{"en":"If colour photography becomes realistic, painters may need to offer something beyond accurate colour.","zh":"如果彩色攝影變得逼真，畫家可能需要提供超越準確色彩的東西。"},{"en":"The phrase refers to a major technological advance in images.","zh":"這個片語指影像方面的重要技術進步。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":18},{"front":"require more skill than","meaning":"比……需要更多技巧","examples":[{"en":"The question asks whether life-casting requires more skill than sculpture.","zh":"題目問生活鑄模是否比雕塑需要更多技巧。"},{"en":"Require more skill than means need a higher level of ability than something else.","zh":"require more skill than 指比另一件事需要更高水平能力。"},{"en":"Repairing a watch may require more skill than changing a battery.","zh":"修理手錶可能比更換電池需要更多技巧。"},{"en":"If life-casting requires careful timing and materials, it may be more skilled than critics assumed.","zh":"如果生活鑄模需要仔細掌握時間和材料，它可能比批評者假設的更有技巧。"},{"en":"The phrase compares difficulty and technical ability.","zh":"這個片語比較難度和技術能力。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":19},{"front":"encourage someone to","meaning":"鼓勵某人去","examples":[{"en":"New art encourages us to look at earlier work in a fresh way.","zh":"新藝術鼓勵我們以新鮮角度看待較早期作品。"},{"en":"Encourage someone to means make someone more willing or likely to do something.","zh":"encourage someone to 指令某人更願意或更可能做某事。"},{"en":"A kind teacher can encourage shy students to speak in class.","zh":"善良老師可以鼓勵害羞學生在課堂發言。"},{"en":"If new art encourages fresh viewing, older work may gain new value.","zh":"如果新藝術鼓勵新鮮觀看，舊作品可能獲得新價值。"},{"en":"The phrase links support or influence with action.","zh":"這個片語把支持或影響與行動連接起來。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":19},{"front":"in a fresh way","meaning":"以新鮮角度","examples":[{"en":"New art can make us look at earlier work in a fresh way.","zh":"新藝術可以令我們以新鮮角度看待較早期作品。"},{"en":"In a fresh way means from a new, lively, or different perspective.","zh":"in a fresh way 指從新的、有活力的或不同的角度。"},{"en":"A student may understand grammar in a fresh way after seeing it in a real conversation.","zh":"學生在真實對話中看到文法後，可能以新鮮角度理解它。"},{"en":"If we look at old casts in a fresh way, they may seem artistic rather than merely technical.","zh":"如果我們以新鮮角度看舊鑄模，它們可能顯得藝術，而不只是技術性。"},{"en":"The phrase describes renewed perception.","zh":"這個片語描述重新出現的感知方式。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":19},{"front":"intended meaning","meaning":"原本意義","examples":[{"en":"The intended meaning of a work of art can get lost over time.","zh":"藝術作品的原本意義可能隨時間流失。"},{"en":"Intended meaning is the meaning the creator originally wanted the work to have.","zh":"intended meaning 指創作者原本希望作品具有的意思。"},{"en":"A joke’s intended meaning may be missed if the listener does not understand the culture.","zh":"如果聽者不理解文化，笑話的原本意義可能被錯過。"},{"en":"If centuries pass, viewers may no longer know the original religious or social meaning.","zh":"如果過了數百年，觀眾可能不再知道原本宗教或社會意義。"},{"en":"The phrase focuses on original purpose in communication.","zh":"這個片語集中於溝通中的原本目的。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":19},{"front":"get lost over time","meaning":"隨時間流失","examples":[{"en":"The intended meaning of art can get lost over time.","zh":"藝術的原本意義可能隨時間流失。"},{"en":"Get lost over time means gradually disappear from memory or understanding as years pass.","zh":"get lost over time 指隨年月過去，逐漸從記憶或理解中消失。"},{"en":"Family stories can get lost over time if no one writes them down.","zh":"如果沒有人寫下來，家庭故事可能隨時間流失。"},{"en":"If a ritual is no longer practised, its meaning may gradually get lost.","zh":"如果儀式不再被實踐，其意義可能逐漸流失。"},{"en":"The phrase describes slow disappearance of knowledge or meaning.","zh":"這個片語描述知識或意義的慢慢消失。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":19},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter from the options.","zh":"學生從選項中選出正確字母。"},{"en":"Choose the correct letter means select the answer option marked by the right letter.","zh":"choose the correct letter 指選擇由正確字母標示的答案選項。"},{"en":"In a multiple-choice question, students may choose A, B, C, or D after checking the passage.","zh":"在多項選擇題中，學生查看文章後可能選 A、B、C 或 D。"},{"en":"If the idea is correct but the letter is copied wrongly, the answer may be marked wrong.","zh":"如果意思正確但字母抄錯，答案可能被判錯。"},{"en":"The phrase is a standard exam instruction.","zh":"這個片語是標準考試指示。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":19},{"front":"the most noticeable contrast","meaning":"最明顯的對比","examples":[{"en":"The most noticeable contrast in the cast is between size and realism.","zh":"這個鑄模中最明顯的對比，是大小與寫實感之間的對比。"},{"en":"The most noticeable contrast means the difference that is easiest to see or feel.","zh":"the most noticeable contrast 指最容易看見或感受到的差異。"},{"en":"In a photo, the most noticeable contrast may be between a bright child and a dark background.","zh":"在照片中，最明顯的對比可能是明亮孩子與黑暗背景之間的對比。"},{"en":"If a huge hand looks completely real, the contrast between size and realism becomes striking.","zh":"如果巨大的手看起來完全真實，大小與寫實感之間的對比就變得突出。"},{"en":"The phrase identifies the clearest difference.","zh":"這個片語指出最清楚的差異。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":19},{"front":"the cast of the giant’s hand","meaning":"巨人手部鑄模","examples":[{"en":"The cast of the giant’s hand creates a powerful visual effect.","zh":"巨人手部鑄模產生強大的視覺效果。"},{"en":"The cast of the giant’s hand is a plaster copy of the unusually large hand of a circus giant.","zh":"the cast of the giant’s hand 指一位馬戲團巨人異常巨大手部的石膏複製品。"},{"en":"A gallery visitor might first notice the cast of the giant’s hand because of its shocking scale.","zh":"畫廊訪客可能首先因其驚人的比例而注意巨人手部鑄模。"},{"en":"If the cast feels both real and impossible, it can make viewers pause.","zh":"如果鑄模感覺既真實又不可能，它可以令觀眾停下。"},{"en":"The phrase refers to the key example used to discuss art and response.","zh":"這個片語指用來討論藝術與反應的關鍵例子。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":19},{"front":"dirt and decoration","meaning":"污垢與裝飾","examples":[{"en":"The question mentions a contrast between dirt and decoration.","zh":"題目提到污垢與裝飾之間的對比。"},{"en":"Dirt and decoration refers to the difference between rough, dirty detail and deliberate visual embellishment.","zh":"dirt and decoration 指粗糙骯髒細節與刻意視覺修飾之間的差異。"},{"en":"A costume may combine dirt and decoration to show both poverty and ceremony.","zh":"服裝可能結合污垢與裝飾，以顯示貧困和儀式感。"},{"en":"If dirt is added deliberately, it may become part of artistic decoration rather than simple mess.","zh":"如果污垢是刻意加入，它可能成為藝術裝飾的一部分，而不只是髒亂。"},{"en":"The phrase highlights a visual and interpretive contrast.","zh":"這個片語突出視覺和詮釋上的對比。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":19},{"front":"size and realism","meaning":"大小與寫實感","examples":[{"en":"The cast shows a striking contrast between size and realism.","zh":"這個鑄模顯示大小與寫實感之間的強烈對比。"},{"en":"Size and realism refers to how large something is and how true to life it appears.","zh":"size and realism 指某物有多大，以及它看起來有多貼近真實。"},{"en":"A giant model of a human eye can surprise visitors through size and realism.","zh":"巨型人眼模型可以透過大小和寫實感令訪客驚訝。"},{"en":"If an object is huge but realistic, viewers may feel both belief and disbelief.","zh":"如果物件巨大但逼真，觀眾可能同時感到相信與不相信。"},{"en":"The phrase names the two qualities being compared.","zh":"這個片語指出正在比較的兩種特質。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":19},{"front":"choice and arrangement","meaning":"選擇與佈置","examples":[{"en":"The artist’s choice and arrangement affect how the cast is viewed.","zh":"藝術家的選擇與佈置影響鑄模如何被觀看。"},{"en":"Choice and arrangement means what the maker selects and how the parts are placed together.","zh":"choice and arrangement 指製作者選擇甚麼，以及各部分如何放在一起。"},{"en":"A photographer’s choice and arrangement of people in a group photo can change its mood.","zh":"攝影師在團體照中對人物的選擇與佈置可以改變照片氣氛。"},{"en":"If a cast includes a sleeve-end, that choice and arrangement may create balance.","zh":"如果鑄模包括袖口，這種選擇與佈置可能創造平衡。"},{"en":"The phrase points to artistic decision-making.","zh":"這個片語指出藝術決策。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":20},{"front":"balance and texture","meaning":"平衡感和質感","examples":[{"en":"The sleeve-end gives the cast balance and texture.","zh":"袖口為鑄模帶來平衡感和質感。"},{"en":"Balance and texture means visual stability plus interesting surface differences.","zh":"balance and texture 指視覺穩定感加上有趣的表面差異。"},{"en":"A classroom display may need balance and texture so it does not look flat or crowded.","zh":"課室展示可能需要平衡感和質感，才不會顯得平板或擁擠。"},{"en":"If cloth texture contrasts with skin texture, the cast becomes visually richer.","zh":"如果布料質感與皮膚質感形成對比，鑄模在視覺上就更豐富。"},{"en":"The phrase describes two qualities that can improve visual effect.","zh":"這個片語描述能改善視覺效果的兩種特質。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":20},{"front":"according to the writer","meaning":"根據作者所說","examples":[{"en":"According to the writer, our response to an object matters most.","zh":"根據作者所說，我們對物件的反應最重要。"},{"en":"According to the writer means based on what the writer says or argues.","zh":"according to the writer 指根據作者所說或所主張。"},{"en":"According to the writer, students should focus on evidence rather than guesswork.","zh":"根據作者所說，學生應集中於證據，而不是猜測。"},{"en":"If a question asks according to the writer, the answer must match the writer’s view, not your opinion.","zh":"如果題目問 according to the writer，答案必須符合作者觀點，而不是你的意見。"},{"en":"The phrase identifies the source of the claim.","zh":"這個片語指出主張來源。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":20},{"front":"any artistic object","meaning":"任何藝術物件","examples":[{"en":"The question asks about the importance of any artistic object.","zh":"題目詢問任何藝術物件的重要性。"},{"en":"Any artistic object means any object that may be viewed or judged as art.","zh":"any artistic object 指任何可能被視為或判斷為藝術的物件。"},{"en":"A painting, sculpture, photograph, or cast can be an artistic object if viewers respond to it that way.","zh":"如果觀眾以藝術方式回應，繪畫、雕塑、照片或鑄模都可以是藝術物件。"},{"en":"If any artistic object survives its original context, later viewers may give it new meaning.","zh":"如果任何藝術物件脫離原本背景後仍保存，後來觀眾可能賦予它新意義。"},{"en":"The phrase is broad and includes many possible art forms.","zh":"這個片語很廣泛，包括許多可能藝術形式。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":20},{"front":"lie in","meaning":"在於","examples":[{"en":"The importance of an artistic object lies in the way we respond to it.","zh":"藝術物件的重要性在於我們如何回應它。"},{"en":"Lie in means be found in or depend mainly on something.","zh":"lie in 指存在於或主要取決於某事。"},{"en":"The value of a good lesson lies in what students understand afterwards.","zh":"好課堂的價值在於學生之後理解了甚麼。"},{"en":"If art’s importance lies in response, the viewer becomes central to meaning.","zh":"如果藝術的重要性在於反應，觀者就成為意義的核心。"},{"en":"The phrase identifies where the key value or reason is located.","zh":"這個片語指出關鍵價值或原因所在。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":20},{"front":"the artist’s intentions","meaning":"藝術家的意圖","examples":[{"en":"The writer argues that art can move beyond the artist’s intentions.","zh":"作者主張藝術可以超越藝術家的意圖。"},{"en":"The artist’s intentions are what the artist originally meant, planned, or wanted the work to express.","zh":"the artist’s intentions 指藝術家原本想表達、計劃或希望作品呈現的內容。"},{"en":"A painter may intend a picture to be cheerful, but viewers may find it lonely.","zh":"畫家可能打算令畫作愉快，但觀眾可能覺得它孤獨。"},{"en":"If audience response changes over time, the artist’s intentions may no longer control the work.","zh":"如果觀眾反應隨時間改變，藝術家的意圖可能不再控制作品。"},{"en":"The phrase focuses on the maker’s original purpose.","zh":"這個片語集中於創作者的原本目的。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":20},{"front":"the artist’s beliefs","meaning":"藝術家的信念","examples":[{"en":"The question asks whether importance lies in the artist’s beliefs.","zh":"題目問重要性是否在於藝術家的信念。"},{"en":"The artist’s beliefs are the ideas, values, or opinions held by the artist.","zh":"the artist’s beliefs 指藝術家持有的思想、價值或意見。"},{"en":"An artist’s beliefs about nature may shape the colours and subjects they choose.","zh":"藝術家對自然的信念可能塑造他們選擇的顏色和題材。"},{"en":"If viewers do not know the artist’s beliefs, they may still respond strongly to the artwork.","zh":"如果觀眾不知道藝術家的信念，仍可能對藝術品有強烈反應。"},{"en":"The phrase refers to personal convictions behind creation.","zh":"這個片語指創作背後的個人信念。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":20},{"front":"relevance to modern life","meaning":"與現代生活的相關性","examples":[{"en":"The question asks whether artistic importance lies in relevance to modern life.","zh":"題目問藝術重要性是否在於與現代生活的相關性。"},{"en":"Relevance to modern life means connection with the concerns, habits, or problems of people today.","zh":"relevance to modern life 指與當代人的關注、習慣或問題的連結。"},{"en":"A museum display has relevance to modern life if it helps visitors understand current social issues.","zh":"如果博物館展示幫助訪客理解當前社會問題，它就與現代生活有相關性。"},{"en":"If an old object still raises questions today, it may feel relevant even without modern materials.","zh":"如果舊物件今天仍提出問題，它即使沒有現代材料也可能顯得相關。"},{"en":"The phrase judges how connected something is to the present.","zh":"這個片語判斷某物與現在有多連接。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":20},{"front":"the way we respond to it","meaning":"我們對它的反應","examples":[{"en":"The importance of art lies in the way we respond to it.","zh":"藝術的重要性在於我們對它的反應。"},{"en":"The way we respond to it means how we think, feel, look, question, or react when facing it.","zh":"the way we respond to it 指我們面對它時如何思考、感受、觀看、提問或反應。"},{"en":"A simple object can become meaningful because of the way we respond to it.","zh":"一件簡單物件可以因我們對它的反應而變得有意義。"},{"en":"If viewers pause, think, and feel moved, their response helps create artistic value.","zh":"如果觀眾停下、思考並被感動，其反應就幫助創造藝術價值。"},{"en":"The phrase places the viewer’s reaction at the centre.","zh":"這個片語把觀者反應放在核心位置。"}],"source":"35 - Life-Casting and Art.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 36":[{"front":"the bridge that swayed","meaning":"搖晃的橋","examples":[{"en":"The passage explains why the bridge that swayed became famous.","zh":"文章解釋為何那座搖晃的橋變得有名。"},{"en":"The bridge that swayed means the bridge that moved from side to side instead of staying still.","zh":"「the bridge that swayed」指那座左右移動、而不是保持穩定的橋。"},{"en":"A bridge that swayed would frighten pedestrians because walking across it would feel unstable.","zh":"搖晃的橋會令行人害怕，因為走過時會感到不穩。"},{"en":"If a bridge sways too much, engineers must find out whether people, wind, or structure caused it.","zh":"如果橋搖晃得太厲害，工程師必須找出是人群、風還是結構造成。"},{"en":"The phrase focuses on the unusual movement that made the bridge famous.","zh":"這個短語集中於令橋成名的不尋常移動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":1},{"front":"London Millennium footbridge","meaning":"倫敦千禧行人橋","examples":[{"en":"The London Millennium footbridge was opened in June 2000.","zh":"倫敦千禧行人橋於2000年6月開放。"},{"en":"The London Millennium footbridge is a pedestrian bridge built in London to mark the millennium.","zh":"「London Millennium footbridge」是倫敦一座為紀念千禧年而建的行人橋。"},{"en":"Tourists may cross the London Millennium footbridge when walking between famous riverside sites.","zh":"遊客在著名河畔景點之間步行時，可能會橫過倫敦千禧行人橋。"},{"en":"Because the bridge moved unexpectedly after opening, it attracted public and engineering attention.","zh":"因為該橋開放後意外移動，它引起公眾和工程界關注。"},{"en":"The phrase names the specific bridge discussed in the passage.","zh":"這個短語指出文章討論的特定橋樑。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":1},{"front":"sway alarmingly","meaning":"令人驚慌地搖晃","examples":[{"en":"When the bridge was opened, it swayed alarmingly.","zh":"當橋開放時，它令人驚慌地搖晃。"},{"en":"To sway alarmingly means to move from side to side in a way that makes people worried or frightened.","zh":"「sway alarmingly」意思是以令人擔心或害怕的方式左右搖晃。"},{"en":"A tall shelf may sway alarmingly during an earthquake.","zh":"地震期間，高書架可能令人驚慌地搖晃。"},{"en":"If a bridge sways alarmingly, people may stop walking and hold the railings.","zh":"如果橋令人驚慌地搖晃，人們可能停止步行並抓住欄杆。"},{"en":"The phrase suggests movement that feels unsafe, not gentle movement.","zh":"這個短語暗示令人覺得不安全的移動，而不是輕微擺動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":1},{"front":"generate huge public interest","meaning":"引起大眾極大關注","examples":[{"en":"The bridge’s movement generated huge public interest.","zh":"該橋的移動引起大眾極大關注。"},{"en":"To generate huge public interest means to attract a very large amount of attention from ordinary people and the media.","zh":"「generate huge public interest」意思是吸引普通市民和媒體大量關注。"},{"en":"A new school policy may generate huge public interest if it affects many families.","zh":"如果新校政影響許多家庭，它可能引起大眾極大關注。"},{"en":"If a public structure fails in a visible way, it can quickly generate public interest.","zh":"如果公共建築以明顯方式出問題，它可以迅速引起公眾關注。"},{"en":"The phrase describes widespread attention caused by an event.","zh":"這個短語描述由事件造成的廣泛注意。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":1},{"front":"become known as","meaning":"被稱為","examples":[{"en":"The bridge became known as London’s wobbly bridge.","zh":"這座橋被稱為倫敦的搖搖晃晃的橋。"},{"en":"To become known as something means to receive a name or reputation over time.","zh":"「become known as」某物，意思是隨時間得到某個名稱或名聲。"},{"en":"A teacher who explains grammar clearly may become known as the best grammar teacher in school.","zh":"一位清楚解釋文法的老師可能被稱為學校最好的文法老師。"},{"en":"If people repeatedly use a nickname, a place can become known by that name.","zh":"如果人們反覆使用某個綽號，一個地方可以被該名稱稱呼。"},{"en":"The phrase describes how a reputation or nickname develops.","zh":"這個短語描述名聲或綽號如何形成。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":1},{"front":"wobbly bridge","meaning":"搖搖晃晃的橋","examples":[{"en":"The bridge became known as London’s wobbly bridge.","zh":"這座橋被稱為倫敦的搖搖晃晃的橋。"},{"en":"A wobbly bridge is a bridge that shakes or moves in an unsteady way.","zh":"「wobbly bridge」是以不穩方式震動或移動的橋。"},{"en":"Children may feel nervous on a wobbly bridge in a playground.","zh":"孩子在遊樂場的搖晃小橋上可能感到緊張。"},{"en":"If a bridge feels wobbly, pedestrians may slow down or hold the handrail.","zh":"如果橋感覺搖晃，行人可能放慢腳步或抓住扶手。"},{"en":"The phrase is informal and makes the bridge sound unstable.","zh":"這個短語較口語，令人覺得橋不穩定。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":1},{"front":"the first new bridge across","meaning":"橫跨……的第一條新橋","examples":[{"en":"The Millennium Bridge is the first new bridge across the River Thames since Tower Bridge.","zh":"千禧橋是自倫敦塔橋以來第一條橫跨泰晤士河的新橋。"},{"en":"The first new bridge across a river means the first newly built bridge spanning that river within a stated period.","zh":"「the first new bridge across」某河，意思是在指定時期內第一條新建並跨越該河的橋。"},{"en":"A city may celebrate the first new bridge across its harbour in decades.","zh":"城市可能慶祝數十年來第一條橫跨海港的新橋。"},{"en":"If a bridge is the first new crossing for many years, people may pay special attention to it.","zh":"如果一座橋是多年來第一條新通道，人們可能特別關注它。"},{"en":"The phrase highlights historical importance and location.","zh":"這個短語突出歷史重要性和位置。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":1},{"front":"River Thames","meaning":"泰晤士河","examples":[{"en":"The Millennium Bridge crosses the River Thames in London.","zh":"千禧橋橫跨倫敦的泰晤士河。"},{"en":"The River Thames is the major river flowing through London.","zh":"「River Thames」是流經倫敦的主要河流。"},{"en":"Tourists often walk along the River Thames to see bridges, galleries, and historic buildings.","zh":"遊客常沿着泰晤士河步行，觀看橋樑、美術館和歷史建築。"},{"en":"Because many famous sites stand beside the River Thames, bridges across it become important routes.","zh":"因為許多著名景點位於泰晤士河旁，橫跨它的橋樑成為重要路線。"},{"en":"The phrase names the river crossed by the bridge.","zh":"這個短語指出該橋橫跨的河流。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":1},{"front":"Tower Bridge","meaning":"倫敦塔橋","examples":[{"en":"Tower Bridge opened in 1894.","zh":"倫敦塔橋於1894年開放。"},{"en":"Tower Bridge is a famous bridge in London near the Tower of London.","zh":"「Tower Bridge」是倫敦一座位於倫敦塔附近的著名橋樑。"},{"en":"Visitors often take photos of Tower Bridge because of its two towers and historic design.","zh":"遊客常拍攝倫敦塔橋，因為它有兩座塔和歷史設計。"},{"en":"Since Tower Bridge opened long before the Millennium Bridge, the new footbridge attracted attention.","zh":"由於倫敦塔橋比千禧橋早很久開放，新行人橋因此受到關注。"},{"en":"The phrase gives a historical comparison point.","zh":"這個短語提供歷史比較點。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":1},{"front":"be designed for pedestrians only","meaning":"專為行人設計","examples":[{"en":"The Millennium Bridge was designed for pedestrians only.","zh":"千禧橋專為行人設計。"},{"en":"To be designed for pedestrians only means to be built for people walking, not for cars or buses.","zh":"「be designed for pedestrians only」意思是為步行的人而建，不供汽車或巴士使用。"},{"en":"A footpath in a park may be designed for pedestrians only to keep walkers safe.","zh":"公園小徑可能專為行人設計，以保障步行者安全。"},{"en":"If a bridge is pedestrian-only, engineers must study how crowds walk across it.","zh":"如果橋只供行人使用，工程師必須研究人群如何走過。"},{"en":"The phrase identifies the intended users of a structure.","zh":"這個短語指出建築物的預定使用者。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":1},{"front":"link A with B","meaning":"連接A與B","examples":[{"en":"The bridge links the City of London with the Tate Modern art gallery.","zh":"這座橋連接倫敦金融城與泰特現代美術館。"},{"en":"To link A with B means to connect one place, thing, or idea with another.","zh":"「link A with B」意思是把一個地方、事物或想法與另一個連接起來。"},{"en":"A footbridge may link a school with a nearby sports ground.","zh":"行人天橋可以連接學校與附近運動場。"},{"en":"If a bridge links two busy areas, many people may use it every day.","zh":"如果橋連接兩個繁忙地區，許多人可能每天使用它。"},{"en":"The phrase describes connection between two points.","zh":"這個短語描述兩點之間的連接。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":1},{"front":"the City of London","meaning":"倫敦金融城","examples":[{"en":"The bridge links the City of London with Bankside.","zh":"這座橋連接倫敦金融城與班克塞德。"},{"en":"The City of London is the historic financial district of London.","zh":"「the City of London」是倫敦歷史悠久的金融區。"},{"en":"Many office workers travel into the City of London on weekdays.","zh":"許多辦公室員工在平日到倫敦金融城上班。"},{"en":"If a bridge connects the City of London to cultural sites, it helps business and leisure areas meet.","zh":"如果橋把倫敦金融城與文化景點連接起來，它就幫助商業和休閒區相連。"},{"en":"The phrase names one side of the bridge’s route.","zh":"這個短語指出橋樑路線的一邊。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":2},{"front":"St Paul’s Cathedral","meaning":"聖保羅大教堂","examples":[{"en":"The bridge is near St Paul’s Cathedral.","zh":"這座橋位於聖保羅大教堂附近。"},{"en":"St Paul’s Cathedral is a famous church and landmark in London.","zh":"「St Paul’s Cathedral」是倫敦一座著名教堂和地標。"},{"en":"Tourists may visit St Paul’s Cathedral before walking across the Millennium Bridge.","zh":"遊客可能先參觀聖保羅大教堂，再走過千禧橋。"},{"en":"Because the cathedral is a major landmark, the bridge’s location became more prominent.","zh":"因為該教堂是主要地標，這座橋的位置變得更突出。"},{"en":"The phrase names a historic building near the bridge.","zh":"這個短語指出橋附近的一座歷史建築。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":2},{"front":"Tate Modern art gallery","meaning":"泰特現代美術館","examples":[{"en":"The bridge links St Paul’s Cathedral with the Tate Modern art gallery.","zh":"這座橋連接聖保羅大教堂與泰特現代美術館。"},{"en":"The Tate Modern art gallery is a major modern art museum in London.","zh":"「Tate Modern art gallery」是倫敦一座主要現代藝術博物館。"},{"en":"Students may visit the Tate Modern art gallery to study paintings, sculpture, and installations.","zh":"學生可能參觀泰特現代美術館，研究繪畫、雕塑和裝置藝術。"},{"en":"If a bridge leads directly to a famous gallery, it becomes useful for tourists and residents.","zh":"如果橋直接通往著名美術館，它就對遊客和居民都有用。"},{"en":"The phrase names a cultural destination connected by the bridge.","zh":"這個短語指出由橋連接的文化目的地。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":2},{"front":"Bankside","meaning":"班克塞德","examples":[{"en":"The Tate Modern art gallery is on Bankside.","zh":"泰特現代美術館位於班克塞德。"},{"en":"Bankside is an area on the south bank of the River Thames in London.","zh":"「Bankside」是倫敦泰晤士河南岸的一個地區。"},{"en":"A visitor may walk along Bankside to see theatres, galleries, and riverside views.","zh":"遊客可能沿班克塞德步行，觀看劇院、美術館和河畔景色。"},{"en":"Because Bankside has cultural attractions, a footbridge to it can attract many pedestrians.","zh":"因為班克塞德有文化景點，通往它的行人橋可以吸引許多行人。"},{"en":"The phrase names the area on one side of the bridge.","zh":"這個短語指出橋一邊的地區。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":2},{"front":"initially opened","meaning":"最初開放","examples":[{"en":"The bridge initially opened on Saturday 10 June 2000.","zh":"這座橋最初於2000年6月10日星期六開放。"},{"en":"Initially opened means first opened to users or the public.","zh":"「initially opened」意思是首次向使用者或公眾開放。"},{"en":"A new library may initially open with limited hours before full service begins.","zh":"新圖書館可能最初以有限開放時間運作，之後才提供全面服務。"},{"en":"If problems appear soon after a bridge initially opens, engineers may close it again.","zh":"如果橋最初開放後不久出現問題，工程師可能再次關閉它。"},{"en":"The phrase marks the first opening, not later reopening.","zh":"這個短語標示首次開放，而不是後來重開。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":2},{"front":"opening ceremony","meaning":"開幕禮","examples":[{"en":"A crowd assembled for the opening ceremony.","zh":"一群人聚集參加開幕禮。"},{"en":"An opening ceremony is a formal event held to celebrate the start or first use of something.","zh":"「opening ceremony」是為慶祝某物開始或首次使用而舉行的正式活動。"},{"en":"A school may hold an opening ceremony for a new sports hall.","zh":"學校可能為新體育館舉行開幕禮。"},{"en":"If a problem happens during an opening ceremony, the event can become memorable for the wrong reason.","zh":"如果問題在開幕禮期間發生，活動可能因不好的原因而令人難忘。"},{"en":"The phrase describes a public celebration of a new facility.","zh":"這個短語描述新設施的公開慶祝活動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":2},{"front":"a crowd of over","meaning":"超過……的一群人","examples":[{"en":"A crowd of over 1,000 people had assembled on the bridge.","zh":"超過1,000人的人群已聚集在橋上。"},{"en":"A crowd of over a number means more than that number of people gathered together.","zh":"「a crowd of over」某數字，意思是超過該數量的人聚集在一起。"},{"en":"A crowd of over 500 students waited outside the school hall after the concert.","zh":"音樂會後，超過500名學生在學校禮堂外等候。"},{"en":"If a crowd of over 1,000 people walks on one bridge, the structure receives heavy pedestrian loading.","zh":"如果超過1,000人的人群在同一座橋上行走，結構會承受大量行人負荷。"},{"en":"The phrase emphasises that the group was large.","zh":"這個短語強調人群很大。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":2},{"front":"assemble on","meaning":"聚集在……上","examples":[{"en":"People had assembled on the south half of the bridge.","zh":"人們已聚集在橋的南半部。"},{"en":"To assemble on a place means to gather together there.","zh":"「assemble on」某地，意思是在那裡聚集起來。"},{"en":"Students may assemble on the playground before a fire drill.","zh":"學生可能在消防演習前聚集在操場上。"},{"en":"If many people assemble on one section of a bridge, movement and loading may increase.","zh":"如果許多人聚集在橋的一個部分，移動和負荷可能增加。"},{"en":"The phrase describes people gathering at a location.","zh":"這個短語描述人們在某地集合。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":2},{"front":"south half of the bridge","meaning":"橋的南半部","examples":[{"en":"A crowd gathered on the south half of the bridge.","zh":"人群聚集在橋的南半部。"},{"en":"The south half of the bridge means the half of the bridge on or toward the southern side.","zh":"「south half of the bridge」指橋上位於或朝向南方的一半。"},{"en":"Workers may close the south half of a road while repairing water pipes.","zh":"工人修理水管時，可能封閉道路的南半部。"},{"en":"If one half of a bridge is crowded, that section may move differently from the rest.","zh":"如果橋的一半擠滿人，該部分可能與其他部分有不同移動。"},{"en":"The phrase gives a precise location on the bridge.","zh":"這個短語提供橋上的精確位置。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":2},{"front":"with a band in front","meaning":"前面有一隊樂隊","examples":[{"en":"The crowd walked with a band in front.","zh":"人群前面有一隊樂隊一起步行。"},{"en":"With a band in front means a music group was leading the people at the front.","zh":"「with a band in front」意思是有一隊音樂隊在前方帶領人群。"},{"en":"At a school parade, students may walk with a band in front playing drums.","zh":"在學校巡遊中，學生可能前面有一隊敲鼓樂隊帶領。"},{"en":"If a band leads a crowd, people may naturally follow its rhythm.","zh":"如果樂隊帶領人群，人們可能自然跟隨其節奏。"},{"en":"The phrase describes the arrangement of a moving crowd.","zh":"這個短語描述移動人群的排列。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":2},{"front":"walk across","meaning":"橫過；走過","examples":[{"en":"The crowd started to walk across the bridge.","zh":"人群開始走過這座橋。"},{"en":"To walk across something means to go from one side to the other on foot.","zh":"「walk across」某物，意思是步行從一邊去到另一邊。"},{"en":"Students walk across the playground to reach the science lab.","zh":"學生橫過操場去科學實驗室。"},{"en":"If many people walk across a bridge at the same time, their steps can affect the structure.","zh":"如果許多人同時走過橋樑，他們的腳步可以影響結構。"},{"en":"The phrase describes crossing by walking.","zh":"這個短語描述以步行方式橫過。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":2},{"front":"unexpectedly pronounced","meaning":"出乎意料地明顯","examples":[{"en":"There was an unexpectedly pronounced lateral movement of the bridge deck.","zh":"橋面出現出乎意料地明顯的橫向移動。"},{"en":"Unexpectedly pronounced means surprisingly strong, clear, or noticeable.","zh":"「unexpectedly pronounced」意思是出人意料地強烈、清楚或明顯。"},{"en":"A student may show unexpectedly pronounced improvement after changing study habits.","zh":"學生改變學習習慣後，可能有出乎意料地明顯的進步。"},{"en":"If bridge movement is unexpectedly pronounced, engineers must investigate immediately.","zh":"如果橋樑移動出乎意料地明顯，工程師必須立即調查。"},{"en":"The phrase describes something stronger than people expected.","zh":"這個短語描述比人們預期更強的情況。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":3},{"front":"lateral movement","meaning":"橫向移動","examples":[{"en":"The bridge deck had an unexpectedly pronounced lateral movement.","zh":"橋面有出乎意料地明顯的橫向移動。"},{"en":"Lateral movement means movement from side to side.","zh":"「lateral movement」意思是左右方向的移動。"},{"en":"A train passenger may feel lateral movement when the carriage turns sharply.","zh":"當車廂急轉彎時，火車乘客可能感到橫向移動。"},{"en":"If many pedestrians push sideways, lateral movement of a bridge can increase.","zh":"如果許多行人向側面施力，橋的橫向移動可以增加。"},{"en":"The phrase describes sideways movement rather than up-and-down movement.","zh":"這個短語描述左右移動，而不是上下移動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":3},{"front":"bridge deck","meaning":"橋面","examples":[{"en":"The bridge deck began to move sideways.","zh":"橋面開始左右移動。"},{"en":"The bridge deck is the surface of a bridge that people or vehicles travel on.","zh":"「bridge deck」是人或車在橋上行走或行駛的表面。"},{"en":"Workers may repair the bridge deck if cracks appear on the walking surface.","zh":"如果行走表面出現裂縫，工人可能修理橋面。"},{"en":"If the bridge deck moves sideways, pedestrians may feel the movement directly under their feet.","zh":"如果橋面左右移動，行人會直接在腳下感到該移動。"},{"en":"The phrase names the main floor-like part of a bridge.","zh":"這個短語指出橋上像地板的主要部分。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":3},{"front":"be on the route of","meaning":"位於……路線上","examples":[{"en":"The bridge was on the route of a major charity walk.","zh":"這座橋位於大型慈善步行活動的路線上。"},{"en":"To be on the route of an event means to lie along the planned path for that event.","zh":"「be on the route of」某活動，意思是位於該活動的計劃路徑上。"},{"en":"A café may be on the route of a marathon and become crowded with spectators.","zh":"咖啡店可能位於馬拉松路線上，並擠滿觀眾。"},{"en":"If a bridge is on a charity walk route, many walkers may cross it in a short time.","zh":"如果橋位於慈善步行路線上，許多步行者可能在短時間內橫過它。"},{"en":"The phrase connects a location with a planned journey.","zh":"這個短語把地點與計劃路程連繫起來。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":3},{"front":"major charity walk","meaning":"大型慈善步行活動","examples":[{"en":"The bridge was on the route of a major charity walk.","zh":"這座橋位於大型慈善步行活動的路線上。"},{"en":"A major charity walk is a large walking event organised to raise money or awareness for a cause.","zh":"「major charity walk」是為某個公益目的籌款或提高關注而舉辦的大型步行活動。"},{"en":"A school may join a charity walk to raise money for a hospital.","zh":"學校可能參加慈善步行，為醫院籌款。"},{"en":"If a major charity walk uses a bridge, the bridge may receive a sudden crowd load.","zh":"如果大型慈善步行活動使用一座橋，該橋可能突然承受人群負荷。"},{"en":"The phrase describes a large public fundraising event.","zh":"這個短語描述大型公開籌款活動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":3},{"front":"pedestrian","meaning":"行人","examples":[{"en":"One pedestrian later recounted what happened.","zh":"一名行人後來憶述發生了甚麼。"},{"en":"A pedestrian is a person who is walking, especially near roads or public spaces.","zh":"「pedestrian」是步行的人，尤其是在道路或公共空間附近。"},{"en":"Drivers must slow down when pedestrians are crossing the road.","zh":"當行人過馬路時，司機必須減速。"},{"en":"If a bridge is for pedestrians only, it is built for walkers rather than vehicles.","zh":"如果橋只供行人使用，它就是為步行者而不是車輛建造。"},{"en":"The word refers to a person on foot.","zh":"這個詞指步行的人。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":3},{"front":"recount","meaning":"敘述；憶述","examples":[{"en":"One pedestrian later recounted the experience.","zh":"一名行人後來憶述該經歷。"},{"en":"To recount something means to tell or describe what happened.","zh":"「recount」某事，意思是講述或描述發生了甚麼。"},{"en":"A student may recount a school trip by explaining where the class went and what they saw.","zh":"學生可能透過解釋班級去了哪裡和看見甚麼來敘述學校旅行。"},{"en":"If witnesses recount the same event clearly, investigators can understand it better.","zh":"如果證人清楚憶述同一事件，調查人員可以更好理解它。"},{"en":"The phrase is more formal than “tell”.","zh":"這個詞比 “tell” 更正式。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":3},{"front":"sway sideways","meaning":"左右搖晃","examples":[{"en":"The bridge began to sway sideways.","zh":"這座橋開始左右搖晃。"},{"en":"To sway sideways means to move left and right repeatedly.","zh":"「sway sideways」意思是反覆向左和向右移動。"},{"en":"A bus may sway sideways when it turns a corner too quickly.","zh":"巴士轉彎太快時可能左右搖晃。"},{"en":"If a bridge sways sideways, people may widen their stance to stay balanced.","zh":"如果橋左右搖晃，人們可能把雙腳分開以保持平衡。"},{"en":"The phrase describes side-to-side motion.","zh":"這個短語描述左右方向的動作。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":3},{"front":"from one moment to the next","meaning":"突然間","examples":[{"en":"From one moment to the next, the wobble intensified.","zh":"突然間，搖晃加劇了。"},{"en":"From one moment to the next means suddenly or within a very short time.","zh":"「from one moment to the next」意思是突然或在很短時間內。"},{"en":"From one moment to the next, a quiet classroom can become noisy when the bell rings.","zh":"鐘聲一響，安靜課室可以突然間變得嘈雜。"},{"en":"If movement worsens suddenly, people may not have time to react calmly.","zh":"如果移動突然惡化，人們可能沒有時間冷靜反應。"},{"en":"The phrase stresses a rapid change.","zh":"這個短語強調快速變化。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":3},{"front":"large groups of people","meaning":"大群人","examples":[{"en":"Large groups of people were crossing the bridge.","zh":"大群人正在橫過這座橋。"},{"en":"Large groups of people means many people gathered or moving together.","zh":"「large groups of people」意思是許多人聚集或一起移動。"},{"en":"Large groups of people often queue outside a stadium before a concert.","zh":"音樂會前，大群人常在體育場外排隊。"},{"en":"If large groups cross a bridge together, their combined movement can affect it.","zh":"如果大群人一起過橋，他們的合併移動可以影響橋樑。"},{"en":"The phrase emphasises crowd size.","zh":"這個短語強調人群規模。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":3},{"front":"wobble intensified","meaning":"搖晃加劇","examples":[{"en":"The wobble intensified when large groups crossed the bridge.","zh":"當大群人橫過橋時，搖晃加劇。"},{"en":"Wobble intensified means the shaking became stronger or more noticeable.","zh":"「wobble intensified」意思是搖晃變得更強或更明顯。"},{"en":"A table’s wobble may intensify when someone places a heavy box on one corner.","zh":"當有人把重箱放在桌角，桌子的搖晃可能加劇。"},{"en":"If more people step in rhythm, the bridge’s wobble may grow stronger.","zh":"如果更多人以同一節奏踏步，橋的搖晃可能變強。"},{"en":"The phrase describes worsening instability.","zh":"這個短語描述不穩定情況惡化。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":3},{"front":"retain balance","meaning":"保持平衡","examples":[{"en":"Everyone had to stop walking to retain balance.","zh":"每個人都必須停止步行以保持平衡。"},{"en":"To retain balance means to keep steady and avoid falling.","zh":"「retain balance」意思是保持穩定並避免跌倒。"},{"en":"A child learning to ride a bicycle must move carefully to retain balance.","zh":"學踩單車的孩子必須小心移動以保持平衡。"},{"en":"If the floor moves, people may stop walking to keep their balance.","zh":"如果地面移動，人們可能停止步行以保持平衡。"},{"en":"The phrase focuses on staying stable.","zh":"這個短語集中於保持穩定。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":4},{"front":"hold onto the handrails","meaning":"抓住扶手","examples":[{"en":"Some people had to hold onto the handrails for support.","zh":"有些人必須抓住扶手以作支撐。"},{"en":"To hold onto the handrails means to grip the railings with one’s hands.","zh":"「hold onto the handrails」意思是用手握住欄杆或扶手。"},{"en":"Older passengers may hold onto the handrails when a bus stops suddenly.","zh":"當巴士突然停下，年長乘客可能抓住扶手。"},{"en":"If a bridge moves unexpectedly, holding the handrails can help prevent falling.","zh":"如果橋意外移動，抓住扶手可以幫助避免跌倒。"},{"en":"The phrase describes using a fixed object for safety.","zh":"這個短語描述為安全而使用固定物件。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":4},{"front":"for support","meaning":"以作支撐","examples":[{"en":"People held onto the handrails for support.","zh":"人們抓住扶手以作支撐。"},{"en":"For support means in order to stay steady, safe, or helped.","zh":"「for support」意思是為了保持穩定、安全或得到幫助。"},{"en":"A patient may hold a walking stick for support after an injury.","zh":"病人受傷後可能拿着拐杖以作支撐。"},{"en":"If the ground is unstable, people look for something solid for support.","zh":"如果地面不穩，人們會尋找堅固物件作支撐。"},{"en":"The phrase explains the purpose of holding or using something.","zh":"這個短語解釋握住或使用某物的目的。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":4},{"front":"limit the number of people","meaning":"限制人數","examples":[{"en":"Officials decided to limit the number of people on the bridge.","zh":"官員決定限制橋上的人數。"},{"en":"To limit the number of people means to allow only a certain amount of people in a place.","zh":"「limit the number of people」意思是只容許一定數量的人在某地。"},{"en":"A lift limits the number of people to prevent overloading.","zh":"升降機會限制人數，以防超載。"},{"en":"If a bridge becomes crowded, limiting people can reduce movement and risk.","zh":"如果橋變得擠迫，限制人數可以減少移動和風險。"},{"en":"The phrase describes crowd control.","zh":"這個短語描述人群控制。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":4},{"front":"be dubbed","meaning":"被稱為","examples":[{"en":"The bridge was dubbed the wobbly bridge by the media.","zh":"這座橋被媒體稱為搖搖晃晃的橋。"},{"en":"To be dubbed something means to be given a nickname or label.","zh":"「be dubbed」某物，意思是被給予綽號或標籤。"},{"en":"A very strict teacher may be dubbed “the homework king” by students.","zh":"很嚴格的老師可能被學生稱為「功課王」。"},{"en":"If the media dub a project with a catchy name, the public may remember it easily.","zh":"如果媒體給項目一個易記名稱，公眾可能很容易記住它。"},{"en":"The phrase is often used for informal names created by others.","zh":"這個短語常用於別人創造的非正式名稱。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":4},{"front":"high-profile failure","meaning":"高調失敗","examples":[{"en":"The media declared the bridge another high-profile project failure.","zh":"媒體宣稱這座橋是另一個高調失敗的項目。"},{"en":"A high-profile failure is a public and widely noticed failure.","zh":"「high-profile failure」是公開且廣受注意的失敗。"},{"en":"A school’s new computer system may become a high-profile failure if it crashes on exam day.","zh":"如果學校新電腦系統在考試日當機，它可能成為高調失敗。"},{"en":"If an expensive public project fails publicly, trust in planners may fall.","zh":"如果昂貴公共項目公開失敗，人們對規劃者的信任可能下降。"},{"en":"The phrase describes failure under strong public attention.","zh":"這個短語描述在高度公眾關注下的失敗。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":4},{"front":"British Millennium Project","meaning":"英國千禧項目","examples":[{"en":"The bridge was seen as a British Millennium Project.","zh":"這座橋被視為英國千禧項目。"},{"en":"A British Millennium Project was a major UK project linked to celebrations of the year 2000.","zh":"「British Millennium Project」是與2000年慶祝活動相關的英國大型項目。"},{"en":"Public buildings built for a national celebration may carry symbolic meaning.","zh":"為國家慶祝而建的公共建築可能具有象徵意義。"},{"en":"If a Millennium Project fails publicly, the embarrassment can feel national rather than local.","zh":"如果千禧項目公開失敗，尷尬可能感覺像全國性而不是地方性。"},{"en":"The phrase connects the bridge with a wider public programme.","zh":"這個短語把橋與更廣泛的公共計劃連繫起來。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":4},{"front":"in order to","meaning":"為了","examples":[{"en":"The bridge was closed in order to investigate the problem.","zh":"這座橋被關閉，為了調查問題。"},{"en":"In order to means for the purpose of doing something.","zh":"「in order to」意思是為了做某事。"},{"en":"Students may revise early in order to feel calmer before exams.","zh":"學生可能提早溫習，為了在考試前更冷靜。"},{"en":"If engineers close a bridge in order to investigate, safety is the main reason.","zh":"如果工程師關閉橋樑為了調查，安全就是主要原因。"},{"en":"The phrase introduces purpose.","zh":"這個短語引出目的。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":4},{"front":"fully investigate and resolve","meaning":"全面調查並解決","examples":[{"en":"Engineers needed to fully investigate and resolve the issue.","zh":"工程師需要全面調查並解決該問題。"},{"en":"To fully investigate and resolve a problem means to examine it completely and then fix it.","zh":"「fully investigate and resolve」問題，意思是徹底檢查它並修正它。"},{"en":"A school should fully investigate and resolve a bullying complaint before students feel safe again.","zh":"學校應全面調查並解決欺凌投訴，學生才會再次感到安全。"},{"en":"If engineers only guess the cause, they may fail to resolve the real problem.","zh":"如果工程師只猜測原因，他們可能無法解決真正問題。"},{"en":"The phrase combines finding the cause with solving it.","zh":"這個短語結合找出原因和解決問題。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":4},{"front":"the decision was taken to","meaning":"作出……的決定","examples":[{"en":"The decision was taken to close the bridge on 12 June 2000.","zh":"當局於2000年6月12日作出關閉橋樑的決定。"},{"en":"The decision was taken to do something means people officially decided to do it.","zh":"「the decision was taken to」做某事，意思是人們正式決定做它。"},{"en":"The decision was taken to cancel sports day because of heavy rain.","zh":"由於大雨，學校作出取消運動會的決定。"},{"en":"If public safety is uncertain, officials may decide to close a facility.","zh":"如果公共安全不確定，官員可能決定關閉設施。"},{"en":"The phrase is formal and often used in reports.","zh":"這個短語較正式，常用於報告。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":4},{"front":"leading member of","meaning":"……的主要成員","examples":[{"en":"Arup was the leading member of the committee.","zh":"Arup 是該委員會的主要成員。"},{"en":"A leading member of a group is one of its most important or influential members.","zh":"「leading member of」某組織，是其中最重要或最有影響力的成員之一。"},{"en":"A leading member of a school committee may guide decisions about new facilities.","zh":"學校委員會的主要成員可能指導新設施的決策。"},{"en":"If a leading member is responsible for a project, people expect clear action from them.","zh":"如果主要成員負責項目，人們會期望他們採取清楚行動。"},{"en":"The phrase identifies a person or organisation with major responsibility.","zh":"這個短語指出具有重大責任的人或組織。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":4},{"front":"in charge of","meaning":"負責","examples":[{"en":"Arup was in charge of the construction of the bridge.","zh":"Arup 負責這座橋的建造。"},{"en":"To be in charge of something means to be responsible for managing it.","zh":"「in charge of」某事，意思是負責管理它。"},{"en":"A class monitor may be in charge of collecting homework.","zh":"班長可能負責收功課。"},{"en":"If a company is in charge of construction, it must answer questions when problems appear.","zh":"如果公司負責建造，問題出現時它必須回答疑問。"},{"en":"The phrase describes responsibility and control.","zh":"這個短語描述責任和管理權。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":5},{"front":"construction of the bridge","meaning":"橋樑建造","examples":[{"en":"Arup was involved in the construction of the bridge.","zh":"Arup 參與了橋樑建造。"},{"en":"Construction of the bridge means the process of building the bridge.","zh":"「construction of the bridge」意思是建造橋樑的過程。"},{"en":"The construction of a school hall may take months of planning and site work.","zh":"學校禮堂的建造可能需要數月規劃和地盤工程。"},{"en":"If bridge construction is complex, engineers must consider weight, movement, and safety.","zh":"如果橋樑建造很複雜，工程師必須考慮重量、移動和安全。"},{"en":"The phrase refers to the building process.","zh":"這個短語指建築過程。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":5},{"front":"tackle the issue head on","meaning":"正面處理問題","examples":[{"en":"Arup decided to tackle the issue head on.","zh":"Arup 決定正面處理問題。"},{"en":"To tackle an issue head on means to face and deal with a problem directly.","zh":"「tackle the issue head on」意思是直接面對並處理問題。"},{"en":"A student should tackle weak grammar head on by finding patterns in mistakes.","zh":"學生應透過找出錯誤模式來正面處理文法弱點。"},{"en":"If a company tackles a public problem directly, it may regain trust.","zh":"如果公司直接處理公共問題，它可能重新獲得信任。"},{"en":"The phrase suggests honest and active problem-solving.","zh":"這個短語暗示誠實而主動地解決問題。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":5},{"front":"undertake a fast-track research project","meaning":"開展快速研究項目","examples":[{"en":"Arup undertook a fast-track research project.","zh":"Arup 開展了快速研究項目。"},{"en":"To undertake a fast-track research project means to begin urgent research designed to produce results quickly.","zh":"「undertake a fast-track research project」意思是開始緊急研究，目的是快速得出結果。"},{"en":"A hospital may undertake a fast-track study when a new disease appears.","zh":"當新疾病出現，醫院可能開展快速研究。"},{"en":"If safety depends on quick answers, researchers may speed up the investigation.","zh":"如果安全取決於快速答案，研究人員可能加快調查。"},{"en":"The phrase describes urgent, accelerated research work.","zh":"這個短語描述緊急且加速的研究工作。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":5},{"front":"seek the cause and the cure","meaning":"尋找成因和解決方法","examples":[{"en":"The engineers tried to seek the cause and the cure.","zh":"工程師試圖尋找成因和解決方法。"},{"en":"To seek the cause and the cure means to look for both the reason for a problem and the way to fix it.","zh":"「seek the cause and the cure」意思是尋找問題的原因和修正方法。"},{"en":"A doctor seeks the cause and the cure when a patient has repeated headaches.","zh":"當病人反覆頭痛，醫生會尋找成因和治療方法。"},{"en":"If engineers know the cause but not the cure, the bridge still cannot reopen safely.","zh":"如果工程師知道成因但不知道解決方法，橋仍不能安全重開。"},{"en":"The phrase links diagnosis with solution.","zh":"這個短語把診斷與解決方案連繫起來。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":5},{"front":"embarrassed engineers","meaning":"尷尬的工程師","examples":[{"en":"The embarrassed engineers examined videotape from the opening day.","zh":"尷尬的工程師檢查了開放當日的錄影帶。"},{"en":"Embarrassed engineers are engineers who feel awkward or ashamed because a project has gone wrong publicly.","zh":"「embarrassed engineers」是因項目公開出錯而感到尷尬或難堪的工程師。"},{"en":"Embarrassed teachers may review a test if many students misunderstand the same question.","zh":"如果許多學生誤解同一條題目，尷尬的老師可能檢視測驗。"},{"en":"If a famous bridge fails on opening day, the engineers responsible may feel embarrassed.","zh":"如果著名橋樑在開放日出問題，負責工程師可能感到尷尬。"},{"en":"The phrase describes professional discomfort after a visible failure.","zh":"這個短語描述明顯失敗後的專業不安。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":5},{"front":"videotape recorded that day","meaning":"當日錄下的錄影帶","examples":[{"en":"The engineers found videotape recorded that day.","zh":"工程師找到當日錄下的錄影帶。"},{"en":"Videotape recorded that day means video footage filmed on the same day as the event.","zh":"「videotape recorded that day」意思是在事件同一天拍攝的錄像。"},{"en":"A school may check video recorded that day to understand a playground accident.","zh":"學校可能查看當日錄下的影片，以了解操場意外。"},{"en":"If engineers study footage from the opening day, they can measure what actually happened.","zh":"如果工程師研究開放當日的片段，他們可以量度實際發生的情況。"},{"en":"The phrase identifies visual evidence from a specific day.","zh":"這個短語指出來自特定日子的視覺證據。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":5},{"front":"centre span","meaning":"中央橋跨","examples":[{"en":"The centre span was swaying about three inches sideways every second.","zh":"中央橋跨每秒左右搖晃約三吋。"},{"en":"The centre span is the middle section of a bridge between supports.","zh":"「centre span」是橋樑支撐點之間的中間部分。"},{"en":"Inspectors may focus on the centre span because it often carries heavy load.","zh":"檢查員可能集中檢查中央橋跨，因為它常承受重負荷。"},{"en":"If the centre span sways more than expected, pedestrians may feel the bridge move strongly.","zh":"如果中央橋跨搖晃超出預期，行人可能強烈感到橋在移動。"},{"en":"The phrase names the central bridge section.","zh":"這個短語指出橋樑中央部分。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":5},{"front":"south span","meaning":"南面橋跨","examples":[{"en":"The south span swayed two inches every 1.25 seconds.","zh":"南面橋跨每1.25秒搖晃兩吋。"},{"en":"The south span is the southern section of a bridge between supports.","zh":"「south span」是橋樑支撐點之間的南面部分。"},{"en":"Engineers may compare the south span with the centre span to see which part moves more.","zh":"工程師可能比較南面橋跨和中央橋跨，看哪部分移動較多。"},{"en":"If different spans sway at different rates, the bridge’s movement pattern is complex.","zh":"如果不同橋跨以不同速度搖晃，橋的移動模式就很複雜。"},{"en":"The phrase identifies one specific section of the bridge.","zh":"這個短語指出橋的一個特定部分。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":5},{"front":"significant wind","meaning":"頗強的風","examples":[{"en":"There was a significant wind blowing on the opening days.","zh":"開放日有頗強的風吹着。"},{"en":"Significant wind means wind strong enough to be noticed or considered important.","zh":"「significant wind」是強到值得注意或需要考慮的風。"},{"en":"A school sports day may be affected by significant wind if tents and banners move.","zh":"如果帳篷和橫額被風吹動，學校運動會可能受頗強的風影響。"},{"en":"If significant wind blows against a bridge, engineers may first suspect it caused vibration.","zh":"如果頗強的風吹向橋樑，工程師最初可能懷疑它造成震動。"},{"en":"The phrase describes wind that may influence an event.","zh":"這個短語描述可能影響事件的風。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":5},{"front":"be decorated with","meaning":"以……裝飾","examples":[{"en":"The bridge had been decorated with large flags.","zh":"這座橋以大型旗幟裝飾。"},{"en":"To be decorated with something means to have objects added to make a place look special or festive.","zh":"「be decorated with」某物，意思是加入物件令某地看起來特別或有節日氣氛。"},{"en":"A classroom may be decorated with posters before open day.","zh":"開放日前，課室可能以海報裝飾。"},{"en":"If a bridge is decorated with large flags, wind may push against them.","zh":"如果橋以大型旗幟裝飾，風可能吹向它們並施加力量。"},{"en":"The phrase describes adding visual items for celebration or display.","zh":"這個短語描述為慶祝或展示而加入視覺物件。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":5},{"front":"flags and banners","meaning":"旗幟和橫額","examples":[{"en":"The bridge had been decorated with large flags and banners.","zh":"這座橋以大型旗幟和橫額裝飾。"},{"en":"Flags and banners are pieces of cloth or material used for display, celebration, or messages.","zh":"「flags and banners」是用於展示、慶祝或傳遞訊息的布或材料。"},{"en":"A school fair may use flags and banners to guide visitors.","zh":"學校嘉年華可能使用旗幟和橫額引導訪客。"},{"en":"If flags and banners are large, wind can pull on them strongly.","zh":"如果旗幟和橫額很大，風可以強力拉動它們。"},{"en":"The phrase names decorative items often used at public events.","zh":"這個短語指出公共活動常用的裝飾物。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":6},{"front":"exert excessive force on","meaning":"對……施加過大力量","examples":[{"en":"Engineers first thought winds might be exerting excessive force on the flags.","zh":"工程師最初認為風可能對旗幟施加過大力量。"},{"en":"To exert excessive force on something means to push or pull it with too much force.","zh":"「exert excessive force on」某物，意思是對它推或拉得太用力。"},{"en":"A child may break a pencil by exerting excessive force on it.","zh":"孩子可能因對鉛筆施加過大力量而把它折斷。"},{"en":"If wind exerts excessive force on banners, the structure holding them may move.","zh":"如果風對橫額施加過大力量，支撐它們的結構可能移動。"},{"en":"The phrase describes applying too much physical pressure.","zh":"這個短語描述施加過多物理壓力。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":6},{"front":"wind buffeting","meaning":"強風吹襲","examples":[{"en":"Wind buffeting had not contributed significantly to the bridge’s vibration.","zh":"強風吹襲並沒有對橋樑震動造成重大影響。"},{"en":"Wind buffeting means repeated strong blows or shaking caused by wind.","zh":"「wind buffeting」指由風造成的反覆強力衝擊或搖動。"},{"en":"A cyclist may feel wind buffeting when a large truck passes nearby.","zh":"當大型貨車在附近駛過，單車手可能感到強風吹襲。"},{"en":"If wind buffeting is weak, engineers must look for another cause of vibration.","zh":"如果強風吹襲影響不大，工程師必須尋找震動的另一成因。"},{"en":"The phrase describes irregular pressure from wind.","zh":"這個短語描述風造成的不規則壓力。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":6},{"front":"contribute significantly to","meaning":"對……有重大影響","examples":[{"en":"Wind buffeting had not contributed significantly to the vibration.","zh":"強風吹襲並沒有對震動有重大影響。"},{"en":"To contribute significantly to something means to be an important cause or influence.","zh":"「contribute significantly to」某事，意思是成為重要原因或影響因素。"},{"en":"Lack of sleep can contribute significantly to poor concentration.","zh":"睡眠不足可以對專注力差有重大影響。"},{"en":"If wind did not contribute significantly, pedestrian movement may be the main cause.","zh":"如果風沒有重大影響，行人移動可能是主要原因。"},{"en":"The phrase describes an important contribution, not a minor one.","zh":"這個短語描述重要貢獻，而不是小影響。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":6},{"front":"vibration of the bridge","meaning":"橋樑震動","examples":[{"en":"Engineers studied the vibration of the bridge.","zh":"工程師研究橋樑震動。"},{"en":"Vibration of the bridge means repeated shaking or movement of the bridge structure.","zh":"「vibration of the bridge」意思是橋樑結構反覆震動或移動。"},{"en":"Passengers may feel vibration in a bus when it drives over a rough road.","zh":"巴士駛過崎嶇道路時，乘客可能感到震動。"},{"en":"If bridge vibration becomes strong, walking can feel unsafe.","zh":"如果橋樑震動變強，行走可能感覺不安全。"},{"en":"The phrase describes repeated physical movement in the bridge.","zh":"這個短語描述橋中的重複物理移動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":6},{"front":"measurements were made","meaning":"進行量度","examples":[{"en":"Measurements were made in university laboratories.","zh":"大學實驗室中進行了量度。"},{"en":"Measurements were made means researchers recorded quantities such as force, speed, or movement.","zh":"「measurements were made」意思是研究人員記錄力量、速度或移動等數值。"},{"en":"Measurements are made when a nurse checks a patient’s temperature and blood pressure.","zh":"當護士檢查病人體溫和血壓時，就是在進行量度。"},{"en":"If measurements are accurate, engineers can compare real movement with theory.","zh":"如果量度準確，工程師可以把實際移動與理論比較。"},{"en":"The phrase describes collecting numerical data.","zh":"這個短語描述收集數據。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":6},{"front":"university laboratories","meaning":"大學實驗室","examples":[{"en":"The effects of walking were measured in university laboratories.","zh":"人們步行的影響在大學實驗室中被量度。"},{"en":"University laboratories are research rooms in universities where tests and measurements are carried out.","zh":"「university laboratories」是大學內進行測試和量度的研究房間。"},{"en":"Engineering students may test materials in university laboratories.","zh":"工程學生可能在大學實驗室中測試材料。"},{"en":"If bridge behaviour is studied in laboratories, engineers can control conditions carefully.","zh":"如果橋樑行為在實驗室中研究，工程師可以仔細控制條件。"},{"en":"The phrase names formal research settings.","zh":"這個短語指出正式研究場所。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":6},{"front":"effects of people walking","meaning":"人們步行的影響","examples":[{"en":"Researchers measured the effects of people walking on swaying platforms.","zh":"研究人員量度人們在搖晃平台上步行的影響。"},{"en":"Effects of people walking means the changes caused by pedestrians’ steps and body movements.","zh":"「effects of people walking」指行人的腳步和身體動作造成的變化。"},{"en":"Shop owners may notice the effects of people walking on old wooden floors.","zh":"店主可能注意到人們步行對舊木地板的影響。"},{"en":"If walking creates sideways force, it can affect a flexible bridge.","zh":"如果步行產生橫向力量，它可以影響柔性橋樑。"},{"en":"The phrase focuses on how human movement affects a structure.","zh":"這個短語集中於人類移動如何影響結構。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":6},{"front":"swaying platforms","meaning":"搖晃平台","examples":[{"en":"People were tested while walking on swaying platforms.","zh":"人們在搖晃平台上步行時接受測試。"},{"en":"Swaying platforms are surfaces that move from side to side during a test.","zh":"「swaying platforms」是在測試期間左右移動的表面。"},{"en":"A balance-training machine may use a swaying platform to test stability.","zh":"平衡訓練機可能使用搖晃平台測試穩定性。"},{"en":"If people walk on a swaying platform, researchers can see how they adjust their steps.","zh":"如果人們在搖晃平台上行走，研究人員可以看到他們如何調整步伐。"},{"en":"The phrase describes a moving test surface.","zh":"這個短語描述移動測試表面。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":6},{"front":"large-scale experiments","meaning":"大規模實驗","examples":[{"en":"Large-scale experiments with crowds of pedestrians were conducted on the bridge.","zh":"大規模人群行人實驗在橋上進行。"},{"en":"Large-scale experiments are tests involving many people, objects, or conditions.","zh":"「large-scale experiments」是涉及許多人、物件或條件的測試。"},{"en":"A city may run a large-scale experiment before changing its traffic system.","zh":"城市在改變交通系統前，可能進行大規模實驗。"},{"en":"If a problem involves crowds, small tests may not show the full effect.","zh":"如果問題涉及人群，小型測試可能顯示不出完整影響。"},{"en":"The phrase describes experiments carried out on a big scale.","zh":"這個短語描述以大規模進行的實驗。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":6},{"front":"crowds of pedestrians","meaning":"人群；大批行人","examples":[{"en":"Researchers conducted experiments with crowds of pedestrians.","zh":"研究人員以大批行人進行實驗。"},{"en":"Crowds of pedestrians are large groups of people walking in the same area.","zh":"「crowds of pedestrians」是在同一區域步行的大群人。"},{"en":"Crowds of pedestrians often gather outside train stations during rush hour.","zh":"繁忙時間，大批行人常聚集在火車站外。"},{"en":"If crowds of pedestrians move together, their combined force can become important.","zh":"如果大批行人一起移動，他們的合力可能變得重要。"},{"en":"The phrase describes many walkers together.","zh":"這個短語描述許多步行者聚在一起。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":6},{"front":"be conducted on","meaning":"在……上進行","examples":[{"en":"Experiments were conducted on the bridge itself.","zh":"實驗在橋本身上進行。"},{"en":"To be conducted on a place means to be carried out there.","zh":"「be conducted on」某地，意思是在那裡進行。"},{"en":"A safety drill may be conducted on the school playground.","zh":"安全演習可能在學校操場上進行。"},{"en":"If experiments are conducted on the actual bridge, results may reflect real conditions better.","zh":"如果實驗在實際橋樑上進行，結果可能更能反映真實情況。"},{"en":"The phrase identifies where research happens.","zh":"這個短語指出研究發生的位置。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":7},{"front":"new understanding","meaning":"新理解","examples":[{"en":"A new understanding of the bridge movement was developed.","zh":"人們對橋樑移動形成了新理解。"},{"en":"New understanding means a clearer or different explanation gained after study.","zh":"「new understanding」意思是研究後得到更清楚或不同的解釋。"},{"en":"A teacher may gain a new understanding of a student after speaking with the family.","zh":"老師與家庭交談後，可能對學生有新理解。"},{"en":"If experiments reveal the cause of movement, engineers gain a new understanding of the problem.","zh":"如果實驗揭示移動成因，工程師就對問題有新理解。"},{"en":"The phrase describes improved knowledge.","zh":"這個短語描述知識改善。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":7},{"front":"unexpected motion","meaning":"意想不到的移動","examples":[{"en":"The unexpected motion was caused by a natural human reaction.","zh":"意想不到的移動是由人類自然反應造成的。"},{"en":"Unexpected motion means movement that people did not predict or plan for.","zh":"「unexpected motion」意思是人們沒有預測或計劃到的移動。"},{"en":"Passengers may be startled by unexpected motion when a lift stops suddenly.","zh":"當升降機突然停下，乘客可能被意想不到的移動嚇到。"},{"en":"If a structure moves unexpectedly, designers must check why their model missed it.","zh":"如果結構意外移動，設計者必須檢查為何模型沒有預測到。"},{"en":"The phrase describes surprising physical movement.","zh":"這個短語描述令人驚訝的物理移動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":7},{"front":"the result of","meaning":"……的結果","examples":[{"en":"The bridge’s movement was the result of a natural human reaction.","zh":"橋樑移動是人類自然反應的結果。"},{"en":"The result of something means the effect or outcome caused by it.","zh":"「the result of」某事，意思是由它造成的效果或結果。"},{"en":"A low test score may be the result of poor sleep and little revision.","zh":"低測驗分數可能是睡眠不足和少溫習的結果。"},{"en":"If bridge movement is the result of walking patterns, engineers must study pedestrians as well as steel.","zh":"如果橋樑移動是步行模式的結果，工程師必須研究行人以及鋼材。"},{"en":"The phrase links cause and effect.","zh":"這個短語連繫原因與結果。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":7},{"front":"natural human reaction","meaning":"人類自然反應","examples":[{"en":"The bridge moved because of a natural human reaction to lateral movement.","zh":"這座橋因人類對橫向移動的自然反應而移動。"},{"en":"A natural human reaction is an automatic response people make without planning it.","zh":"「natural human reaction」是人們不經計劃而自動作出的反應。"},{"en":"Holding a railing when a bus turns sharply is a natural human reaction.","zh":"巴士急轉彎時抓住扶手是人類自然反應。"},{"en":"If the ground moves, people naturally adjust their bodies to stay balanced.","zh":"如果地面移動，人們自然會調整身體以保持平衡。"},{"en":"The phrase explains behaviour that happens instinctively.","zh":"這個短語解釋本能發生的行為。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":7},{"front":"suspension bridge","meaning":"懸索橋","examples":[{"en":"A suspension bridge has a tendency to sway.","zh":"懸索橋有搖晃的傾向。"},{"en":"A suspension bridge is a bridge supported by cables hanging from towers.","zh":"「suspension bridge」是由懸掛在橋塔上的纜索支撐的橋。"},{"en":"A long suspension bridge may move slightly in wind or under traffic.","zh":"長懸索橋在風中或交通負荷下可能輕微移動。"},{"en":"Because suspension bridges are flexible, engineers must consider movement carefully.","zh":"因為懸索橋具彈性，工程師必須仔細考慮移動。"},{"en":"The phrase names a bridge type known for flexibility.","zh":"這個短語指出一種以柔性聞名的橋樑類型。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":7},{"front":"have a tendency to","meaning":"有……的傾向","examples":[{"en":"A suspension bridge has a tendency to sway when troops march over it.","zh":"當軍隊步操經過時，懸索橋有搖晃的傾向。"},{"en":"To have a tendency to do something means to be likely to do it.","zh":"「have a tendency to」做某事，意思是較可能做某事。"},{"en":"A tired student may have a tendency to make careless spelling mistakes.","zh":"疲倦學生可能有犯粗心串字錯誤的傾向。"},{"en":"If a bridge has a tendency to sway, designers must plan ways to control movement.","zh":"如果橋有搖晃傾向，設計者必須計劃控制移動的方法。"},{"en":"The phrase describes likelihood, not certainty.","zh":"這個短語描述可能性，而不是必然。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":7},{"front":"troops march over","meaning":"軍隊步操經過","examples":[{"en":"Troops may cause a bridge to sway when they march over it.","zh":"軍隊步操經過橋時，可能令橋搖晃。"},{"en":"Troops march over a bridge when soldiers walk across it in organised steps.","zh":"「troops march over」一座橋，意思是士兵以整齊步伐走過它。"},{"en":"Soldiers may march over a parade ground during a ceremony.","zh":"士兵可能在典禮中步操經過操場。"},{"en":"If troops march in rhythm over a flexible bridge, their steps can create repeated force.","zh":"如果軍隊以節奏步操經過柔性橋樑，他們的腳步可以產生重複力量。"},{"en":"The phrase describes soldiers crossing by marching.","zh":"這個短語描述士兵以步操方式橫過。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":7},{"front":"in lockstep","meaning":"齊步","examples":[{"en":"Troops can make a bridge sway when they march in lockstep.","zh":"當軍隊齊步前進時，可能令橋搖晃。"},{"en":"In lockstep means moving with exactly the same rhythm or timing.","zh":"「in lockstep」意思是以完全相同的節奏或時間移動。"},{"en":"Dancers move in lockstep when every foot lands at the same time.","zh":"當每隻腳同時落地時，舞者就是齊步移動。"},{"en":"If many people walk in lockstep, their forces may add together.","zh":"如果許多人齊步行走，他們的力量可能加起來。"},{"en":"The phrase describes highly synchronised movement.","zh":"這個短語描述高度同步的移動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":7},{"front":"be required to","meaning":"被要求","examples":[{"en":"Troops are required to break step on suspension bridges.","zh":"軍隊被要求在懸索橋上亂步前進。"},{"en":"To be required to do something means to be officially told or expected to do it.","zh":"「be required to」做某事，意思是被正式告知或預期要做它。"},{"en":"Students are required to wear safety glasses in the laboratory.","zh":"學生被要求在實驗室佩戴安全眼鏡。"},{"en":"If a rule is made for safety, people must follow it even if it feels inconvenient.","zh":"如果規則是為了安全而制定，即使不方便，人們也必須遵守。"},{"en":"The phrase describes obligation.","zh":"這個短語描述義務。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":7},{"front":"break step","meaning":"亂步；不齊步","examples":[{"en":"Troops are required to break step when crossing a suspension bridge.","zh":"軍隊橫過懸索橋時被要求亂步前進。"},{"en":"To break step means to stop marching in the same rhythm as others.","zh":"「break step」意思是停止與其他人以相同節奏步操。"},{"en":"A teacher may ask students to break step when crossing a small wooden bridge on a camp trip.","zh":"露營旅行中，老師可能要求學生過小木橋時不要齊步。"},{"en":"If soldiers break step, their combined force is less likely to make a bridge sway.","zh":"如果士兵亂步，他們的合力較不可能令橋搖晃。"},{"en":"The phrase is the opposite of marching in lockstep.","zh":"這個短語與齊步前進相反。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":7},{"front":"compensate and stabilise ourselves","meaning":"作出補償並穩定自己","examples":[{"en":"People compensate and stabilise themselves on a swaying surface.","zh":"人們在搖晃表面上會作出補償並穩定自己。"},{"en":"To compensate and stabilise ourselves means to adjust our bodies to stay balanced and steady.","zh":"「compensate and stabilise ourselves」意思是調整身體以保持平衡和穩定。"},{"en":"Passengers on a moving bus compensate and stabilise themselves by widening their stance.","zh":"巴士移動時，乘客透過分開雙腳作出補償並穩定自己。"},{"en":"If a floor moves sideways, people shift weight to avoid falling.","zh":"如果地面左右移動，人們會轉移重心以避免跌倒。"},{"en":"The phrase describes automatic balance correction.","zh":"這個短語描述自動的平衡修正。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":8},{"front":"spread one’s legs further apart","meaning":"把雙腳分得更開","examples":[{"en":"People spread their legs further apart on a swaying surface.","zh":"人們在搖晃表面上會把雙腳分得更開。"},{"en":"To spread one’s legs further apart means to place the feet wider apart for balance.","zh":"「spread one’s legs further apart」意思是把雙腳放得更寬以保持平衡。"},{"en":"A child may spread his legs further apart when standing on a skateboard.","zh":"孩子站在滑板上時，可能把雙腳分得更開。"},{"en":"If a surface is unstable, a wider stance can make the body steadier.","zh":"如果表面不穩，較寬站姿可以令身體更穩定。"},{"en":"The phrase describes a physical action used to keep balance.","zh":"這個短語描述用來保持平衡的身體動作。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":8},{"front":"lateral push","meaning":"橫向推力","examples":[{"en":"Spreading the legs further apart increases the lateral push.","zh":"把雙腳分得更開會增加橫向推力。"},{"en":"Lateral push means sideways force applied to something.","zh":"「lateral push」意思是施加於某物的側向力量。"},{"en":"A person pushing a door from the side creates a lateral push.","zh":"一個人從側面推門會產生橫向推力。"},{"en":"If many pedestrians create lateral push together, a bridge may start moving sideways.","zh":"如果許多行人一起產生橫向推力，橋可能開始左右移動。"},{"en":"The phrase describes force in a side-to-side direction.","zh":"這個短語描述左右方向的力量。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":8},{"front":"change the way you walk","meaning":"改變走路方式","examples":[{"en":"People change the way they walk to match the bridge’s movement.","zh":"人們改變走路方式來配合橋的移動。"},{"en":"To change the way you walk means to adjust your steps, rhythm, or body position.","zh":"「change the way you walk」意思是調整步伐、節奏或身體姿勢。"},{"en":"A person may change the way they walk on an icy pavement.","zh":"人在結冰行人路上可能改變走路方式。"},{"en":"If a bridge sways, pedestrians may unconsciously change their walking pattern.","zh":"如果橋搖晃，行人可能無意識地改變步行模式。"},{"en":"The phrase describes adapting movement to conditions.","zh":"這個短語描述因應環境調整移動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":8},{"front":"match what the bridge is doing","meaning":"配合橋的動作","examples":[{"en":"Pedestrians may match what the bridge is doing.","zh":"行人可能配合橋的動作。"},{"en":"To match what the bridge is doing means to move in rhythm with the bridge’s movement.","zh":"「match what the bridge is doing」意思是以與橋移動相同的節奏移動。"},{"en":"A person on a boat may move with the waves to avoid losing balance.","zh":"船上的人可能隨波浪移動，以避免失去平衡。"},{"en":"If pedestrians match the bridge’s sway, their steps may strengthen the movement.","zh":"如果行人配合橋的搖晃，他們的腳步可能加強該移動。"},{"en":"The phrase describes synchronising with a moving surface.","zh":"這個短語描述與移動表面同步。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":8},{"front":"unconscious tendency","meaning":"無意識傾向","examples":[{"en":"Pedestrians have an unconscious tendency to match their footsteps to the sway.","zh":"行人有無意識傾向，會使步伐配合橋的搖晃。"},{"en":"An unconscious tendency is a habit or reaction people do without realising it.","zh":"「unconscious tendency」是人們沒有意識到而作出的習慣或反應。"},{"en":"A nervous student may have an unconscious tendency to tap a pen during exams.","zh":"緊張學生在考試中可能有無意識地敲筆的傾向。"},{"en":"If many people react unconsciously in the same way, their combined effect can be large.","zh":"如果許多人無意識地以同一方式反應，其合併效果可以很大。"},{"en":"The phrase describes automatic behaviour rather than deliberate choice.","zh":"這個短語描述自動行為，而不是刻意選擇。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":8},{"front":"match one’s footsteps to","meaning":"使步伐配合……","examples":[{"en":"People may match their footsteps to the sway of the bridge.","zh":"人們可能使步伐配合橋的搖晃。"},{"en":"To match one’s footsteps to something means to adjust walking rhythm to fit it.","zh":"「match one’s footsteps to」某物，意思是調整步行節奏以配合它。"},{"en":"Dancers match their footsteps to the music during a performance.","zh":"舞者在表演中使步伐配合音樂。"},{"en":"If walkers match their footsteps to a bridge’s sway, the movement may become stronger.","zh":"如果步行者使步伐配合橋的搖晃，移動可能變得更強。"},{"en":"The phrase describes coordinating steps with a rhythm.","zh":"這個短語描述把步伐與節奏協調。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":8},{"front":"thereby exacerbating it","meaning":"從而使其惡化","examples":[{"en":"People match the sway, thereby exacerbating it.","zh":"人們配合搖晃，從而使其惡化。"},{"en":"Thereby exacerbating it means making the problem worse as a result of that action.","zh":"「thereby exacerbating it」意思是由於該行動而令問題變差。"},{"en":"A student may sleep late before an exam, thereby exacerbating tiredness the next day.","zh":"學生考試前熬夜，從而加劇第二天的疲倦。"},{"en":"If pedestrians adjust to the sway in the same rhythm, they may worsen the bridge movement.","zh":"如果行人以相同節奏調整來配合搖晃，他們可能令橋樑移動惡化。"},{"en":"The phrase links an action with a negative result.","zh":"這個短語把行動與負面結果連繫起來。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":8},{"front":"rolling ship’s deck","meaning":"搖晃的船甲板","examples":[{"en":"Walking on the bridge was compared to walking on a rolling ship’s deck.","zh":"在橋上行走被比作在搖晃的船甲板上行走。"},{"en":"A rolling ship’s deck is the floor of a ship moving up, down, or sideways with the waves.","zh":"「rolling ship’s deck」是隨波浪上下或左右移動的船上地面。"},{"en":"People on a rolling ship’s deck may widen their stance to avoid falling.","zh":"在搖晃船甲板上的人可能把雙腳分開以避免跌倒。"},{"en":"If a bridge moves like a ship’s deck, pedestrians naturally adjust their steps.","zh":"如果橋像船甲板般移動，行人自然會調整步伐。"},{"en":"The phrase gives a familiar image of an unstable walking surface.","zh":"這個短語提供不穩定行走表面的熟悉圖像。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":8},{"front":"compensate for","meaning":"彌補；抵消","examples":[{"en":"People move one way and then the other to compensate for the roll.","zh":"人們向一邊再向另一邊移動，以抵消搖晃。"},{"en":"To compensate for something means to adjust or make up for a problem or imbalance.","zh":"「compensate for」某事，意思是調整或彌補問題或不平衡。"},{"en":"A student with weak spelling may compensate for it by proofreading carefully.","zh":"串字較弱的學生可能透過仔細校對來彌補。"},{"en":"If the floor moves left, the body may shift right to compensate.","zh":"如果地面向左移動，身體可能向右轉移以抵消。"},{"en":"The phrase describes correcting or balancing an effect.","zh":"這個短語描述修正或平衡某效果。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":8},{"front":"natural frequency","meaning":"自然頻率","examples":[{"en":"People’s walking does not have to match the bridge’s natural frequency exactly.","zh":"人們的步行不必完全配合橋的自然頻率。"},{"en":"Natural frequency is the rate at which an object naturally tends to vibrate.","zh":"「natural frequency」是物件自然傾向震動的速率。"},{"en":"A ruler held over a desk edge has a natural frequency when it is flicked.","zh":"伸出桌邊的間尺被彈動時，有自己的自然頻率。"},{"en":"If repeated forces match a structure’s natural frequency, movement may increase.","zh":"如果重複力量配合結構的自然頻率，移動可能增加。"},{"en":"The phrase is an engineering term about vibration behaviour.","zh":"這個短語是關於震動行為的工程術語。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":8},{"front":"resonance","meaning":"共振","examples":[{"en":"The interaction is not simply resonance.","zh":"這種互動並不只是共振。"},{"en":"Resonance is a strong vibration that happens when repeated force matches a system’s natural frequency.","zh":"「resonance」是當重複力量配合系統自然頻率時發生的強烈震動。"},{"en":"A glass may vibrate if sound waves match its natural frequency.","zh":"如果聲波配合玻璃杯的自然頻率，玻璃杯可能震動。"},{"en":"If resonance occurs in a bridge, small repeated forces can create large movement.","zh":"如果橋發生共振，小的重複力量可以造成大幅移動。"},{"en":"The phrase here warns that the bridge problem was more complex than simple resonance.","zh":"在這裡，這個短語提醒我們橋的問題比簡單共振更複雜。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":9},{"front":"the interaction is more subtle","meaning":"互動更微妙","examples":[{"en":"The interaction between people and the bridge is more subtle.","zh":"人與橋之間的互動更微妙。"},{"en":"The interaction is more subtle means the relationship is more complex and less obvious than it first seems.","zh":"「the interaction is more subtle」意思是關係比最初看來更複雜、不那麼明顯。"},{"en":"The interaction between sleep and mood is more subtle than simply “more sleep means happier”.","zh":"睡眠與情緒之間的互動比「睡得多就更快樂」更微妙。"},{"en":"If people and a bridge affect each other, the cause is not just one simple force.","zh":"如果人與橋互相影響，成因就不只是一個簡單力量。"},{"en":"The phrase highlights complexity.","zh":"這個短語突出複雜性。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":9},{"front":"in one’s own manner","meaning":"以自己的方式","examples":[{"en":"People adjust the way they walk in their own manner.","zh":"人們以自己的方式調整走路方式。"},{"en":"In one’s own manner means in one’s own personal way.","zh":"「in one’s own manner」意思是以個人自己的方式。"},{"en":"Each student takes notes in their own manner, using lists, diagrams, or colours.","zh":"每位學生以自己的方式記筆記，例如使用清單、圖表或顏色。"},{"en":"If everyone adjusts in their own manner, the group pattern may still become synchronised.","zh":"如果每個人以自己的方式調整，群體模式仍可能變得同步。"},{"en":"The phrase describes individual style or method.","zh":"這個短語描述個人風格或方法。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":9},{"front":"total sideways push","meaning":"總橫向推力","examples":[{"en":"The total sideways push can overcome the bridge’s ability to absorb it.","zh":"總橫向推力可以超過橋樑吸收它的能力。"},{"en":"Total sideways push means the combined side-to-side force produced by many people or objects.","zh":"「total sideways push」是許多人或物件產生的合併左右方向力量。"},{"en":"A crowd leaning against a barrier creates a total sideways push.","zh":"人群靠在欄杆上會產生總橫向推力。"},{"en":"If the total sideways push is too strong, a structure may move more than expected.","zh":"如果總橫向推力太強，結構可能比預期移動更多。"},{"en":"The phrase describes combined lateral force.","zh":"這個短語描述合併橫向力量。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":9},{"front":"overcome the bridge’s ability to","meaning":"超過橋樑……的能力","examples":[{"en":"The push can overcome the bridge’s ability to absorb movement.","zh":"推力可以超過橋樑吸收移動的能力。"},{"en":"To overcome the bridge’s ability to do something means to exceed what the bridge can safely handle.","zh":"「overcome the bridge’s ability to」做某事，意思是超出橋可以安全承受的能力。"},{"en":"Too many books can overcome a shelf’s ability to hold weight.","zh":"太多書可以超過書架承重的能力。"},{"en":"If forces overcome a bridge’s ability to absorb movement, visible swaying may occur.","zh":"如果力量超過橋吸收移動的能力，明顯搖晃可能出現。"},{"en":"The phrase describes a force becoming stronger than a structure’s capacity.","zh":"這個短語描述力量強過結構容量。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":9},{"front":"absorb it","meaning":"吸收它；承受它","examples":[{"en":"The bridge could not absorb the total sideways push.","zh":"這座橋不能吸收總橫向推力。"},{"en":"To absorb it means to take in or reduce the force or movement without reacting too strongly.","zh":"「absorb it」意思是吸收或減少力量或移動，而不作出過強反應。"},{"en":"A good running shoe absorbs impact when a runner’s foot hits the ground.","zh":"好跑鞋在跑手腳落地時吸收衝擊。"},{"en":"If a bridge cannot absorb sideways force, the movement may grow larger.","zh":"如果橋不能吸收橫向力，移動可能變得更大。"},{"en":"The phrase describes a structure’s ability to reduce force.","zh":"這個短語描述結構減少力量的能力。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":9},{"front":"become excessive","meaning":"變得過度","examples":[{"en":"The movement becomes excessive when too many people are on the bridge.","zh":"當橋上有太多人時，移動變得過度。"},{"en":"To become excessive means to become too much or too strong.","zh":"「become excessive」意思是變得太多或太強。"},{"en":"Homework becomes excessive when students cannot sleep because of it.","zh":"當學生因功課不能睡覺，功課量就變得過度。"},{"en":"If bridge movement becomes excessive, pedestrians may feel unsafe.","zh":"如果橋樑移動變得過度，行人可能感到不安全。"},{"en":"The phrase describes a quantity or force passing a safe limit.","zh":"這個短語描述數量或力量超過安全限度。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":9},{"front":"have difficulty walking","meaning":"行走有困難","examples":[{"en":"People began to have difficulty walking on the bridge.","zh":"人們開始在橋上行走有困難。"},{"en":"To have difficulty walking means to find it hard to walk normally or safely.","zh":"「have difficulty walking」意思是難以正常或安全地步行。"},{"en":"A person may have difficulty walking after twisting an ankle.","zh":"扭傷腳踝後，一個人可能行走有困難。"},{"en":"If a surface is moving, people may struggle to place their feet steadily.","zh":"如果表面正在移動，人們可能難以穩定落腳。"},{"en":"The phrase describes a practical problem with movement.","zh":"這個短語描述移動上的實際問題。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":9},{"front":"hold on to the rails","meaning":"抓住欄杆","examples":[{"en":"Pedestrians had to hold on to the rails.","zh":"行人必須抓住欄杆。"},{"en":"To hold on to the rails means to grip the side railings for balance or safety.","zh":"「hold on to the rails」意思是抓住旁邊欄杆以保持平衡或安全。"},{"en":"Passengers hold on to the rails when a train starts moving.","zh":"火車開始移動時，乘客會抓住欄杆。"},{"en":"If a bridge sways, holding the rails can help people keep upright.","zh":"如果橋搖晃，抓住欄杆可以幫助人保持站穩。"},{"en":"The phrase describes using railings as support.","zh":"這個短語描述用欄杆作支撐。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":9},{"front":"earthquake-resistant","meaning":"抗震的","examples":[{"en":"Professor Fujino Yozo studied the earthquake-resistant Toda Bridge.","zh":"藤野陽三教授研究了抗震的戶田橋。"},{"en":"Earthquake-resistant means designed to survive or reduce damage during earthquakes.","zh":"「earthquake-resistant」意思是被設計成能在地震中承受或減少損壞。"},{"en":"New school buildings in earthquake zones may be built with earthquake-resistant structures.","zh":"地震區的新校舍可能採用抗震結構建造。"},{"en":"If a bridge is earthquake-resistant, it may still move under certain walking forces.","zh":"如果橋是抗震的，它仍可能在某些步行力量下移動。"},{"en":"The phrase describes protection against earthquake damage.","zh":"這個短語描述對地震損害的防護。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":9},{"front":"Toda Bridge","meaning":"戶田橋","examples":[{"en":"Professor Fujino Yozo studied the Toda Bridge in Japan.","zh":"藤野陽三教授研究了日本的戶田橋。"},{"en":"Toda Bridge is a bridge in Japan studied for vibration caused by pedestrians.","zh":"「Toda Bridge」是日本一座曾因行人引起震動而被研究的橋。"},{"en":"Engineering students may compare Toda Bridge with the Millennium Bridge to study similar movement.","zh":"工程學生可能比較戶田橋與千禧橋，以研究相似移動。"},{"en":"If a bridge case is studied earlier, later engineers can learn from it.","zh":"如果橋樑案例較早被研究，後來工程師可以向它學習。"},{"en":"The phrase names another bridge relevant to the same phenomenon.","zh":"這個短語指出與同一現象相關的另一座橋。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":9},{"front":"horizontal forces","meaning":"水平力","examples":[{"en":"Horizontal forces caused by walking could produce vibration.","zh":"步行造成的水平力可以產生震動。"},{"en":"Horizontal forces are forces acting sideways rather than upward or downward.","zh":"「horizontal forces」是向側面作用，而不是向上或向下的力量。"},{"en":"A strong side wind creates horizontal force on a tall sign.","zh":"強側風會對高招牌產生水平力。"},{"en":"If footsteps create horizontal forces, a flexible bridge may sway sideways.","zh":"如果腳步產生水平力，柔性橋可能左右搖晃。"},{"en":"The phrase describes side-direction physical forces.","zh":"這個短語描述側向物理力量。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":10},{"front":"excessive dynamic lateral vibration","meaning":"過度動態橫向震動","examples":[{"en":"Walking, running or jumping could cause excessive dynamic lateral vibration.","zh":"步行、跑步或跳躍可以造成過度動態橫向震動。"},{"en":"Excessive dynamic lateral vibration means too much changing side-to-side shaking.","zh":"「excessive dynamic lateral vibration」意思是過多、不斷變化的左右震動。"},{"en":"A gym floor may vibrate when many students jump at the same time.","zh":"當許多學生同時跳躍時，體育館地板可能震動。"},{"en":"If side-to-side vibration becomes excessive, people may feel unable to walk safely.","zh":"如果左右震動變得過度，人們可能覺得無法安全步行。"},{"en":"The phrase describes strong moving sideways vibration in a structure.","zh":"這個短語描述結構中強烈的動態橫向震動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":10},{"front":"as the structure began moving","meaning":"當結構開始移動時","examples":[{"en":"As the structure began moving, pedestrians adjusted their gait.","zh":"當結構開始移動時，行人調整步態。"},{"en":"As the structure began moving means when the bridge or platform started to move.","zh":"「as the structure began moving」意思是當橋或平台開始移動時。"},{"en":"As the bus began moving, passengers reached for the handrails.","zh":"當巴士開始移動時，乘客伸手抓住扶手。"},{"en":"If a structure starts moving, people naturally change their body position.","zh":"如果結構開始移動，人們自然會改變身體姿勢。"},{"en":"The phrase gives the moment that triggers a reaction.","zh":"這個短語提供觸發反應的時刻。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":10},{"front":"adjust one’s gait","meaning":"調整步態","examples":[{"en":"Pedestrians adjusted their gait to the same rhythm as the bridge.","zh":"行人把步態調整至與橋相同的節奏。"},{"en":"To adjust one’s gait means to change the way one walks.","zh":"「adjust one’s gait」意思是改變走路方式。"},{"en":"A runner may adjust her gait after a knee injury.","zh":"跑手膝蓋受傷後，可能調整步態。"},{"en":"If pedestrians adjust their gait to match a bridge, their steps may reinforce its movement.","zh":"如果行人調整步態來配合橋，他們的腳步可能加強橋的移動。"},{"en":"The phrase describes changing walking pattern.","zh":"這個短語描述改變步行模式。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":10},{"front":"lateral rhythm","meaning":"橫向節奏","examples":[{"en":"Pedestrians adjusted their gait to the same lateral rhythm as the bridge.","zh":"行人把步態調整至與橋相同的橫向節奏。"},{"en":"Lateral rhythm means a repeated side-to-side movement pattern.","zh":"「lateral rhythm」是重複的左右移動模式。"},{"en":"Dancers may follow a lateral rhythm when they step left and right with the music.","zh":"舞者隨音樂左右踏步時，可能跟隨橫向節奏。"},{"en":"If pedestrians share the bridge’s lateral rhythm, the bridge may sway more strongly.","zh":"如果行人共享橋的橫向節奏，橋可能搖晃得更強。"},{"en":"The phrase describes rhythm in sideways movement.","zh":"這個短語描述左右移動中的節奏。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":10},{"front":"magnify the motion","meaning":"放大動作","examples":[{"en":"The adjusted footsteps magnified the motion.","zh":"調整後的腳步放大了動作。"},{"en":"To magnify the motion means to make the movement larger or stronger.","zh":"「magnify the motion」意思是令移動變得更大或更強。"},{"en":"A small push at the right time can magnify the motion of a swing.","zh":"在正確時間輕推一下，可以放大鞦韆的動作。"},{"en":"If footsteps keep matching a bridge’s sway, they can increase the movement.","zh":"如果腳步一直配合橋的搖晃，它們可以增加移動。"},{"en":"The phrase describes making movement more noticeable.","zh":"這個短語描述令動作更明顯。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":10},{"front":"stand up in a small boat","meaning":"在小船上站起來","examples":[{"en":"Four people standing up in a small boat can magnify movement.","zh":"四個人在小船上站起來可以放大移動。"},{"en":"To stand up in a small boat means to rise from sitting while on a small, unstable boat.","zh":"「stand up in a small boat」意思是在細小、不穩的小船上由坐下變成站立。"},{"en":"A teacher may warn students not to stand up in a small boat during a field trip.","zh":"老師可能提醒學生在實地考察中不要在小船上站起來。"},{"en":"If several people stand together in a boat, their movement can make it rock more.","zh":"如果幾個人在船上一起站起來，他們的移動可以令船搖得更厲害。"},{"en":"The phrase gives a simple example of people increasing instability.","zh":"這個短語提供人們增加不穩定性的簡單例子。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":10},{"front":"lock into the same rhythm","meaning":"鎖定同一節奏","examples":[{"en":"More pedestrians locked into the same rhythm.","zh":"更多行人鎖定同一節奏。"},{"en":"To lock into the same rhythm means to begin moving in a shared repeated pattern.","zh":"「lock into the same rhythm」意思是開始以共同的重複模式移動。"},{"en":"A class clapping along to a song may lock into the same rhythm.","zh":"全班隨歌曲拍手時，可能鎖定同一節奏。"},{"en":"If many pedestrians lock into the same rhythm, their combined force can grow.","zh":"如果許多行人鎖定同一節奏，他們的合力可以增強。"},{"en":"The phrase describes accidental synchronisation.","zh":"這個短語描述意外同步。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":10},{"front":"increasing oscillation","meaning":"不斷增加的振盪","examples":[{"en":"The increasing oscillation led to dramatic swaying.","zh":"不斷增加的振盪導致劇烈搖晃。"},{"en":"Increasing oscillation means back-and-forth movement becoming larger or stronger.","zh":"「increasing oscillation」是來回移動變得更大或更強。"},{"en":"A swing shows increasing oscillation when each push makes it travel higher.","zh":"當每次推動都令鞦韆盪得更高，鞦韆就顯示不斷增加的振盪。"},{"en":"If oscillation keeps increasing, a structure can become uncomfortable or unsafe to use.","zh":"如果振盪不斷增加，結構可能變得不舒服或不安全。"},{"en":"The phrase describes growing repeated movement.","zh":"這個短語描述不斷增大的重複移動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":10},{"front":"dramatic swaying","meaning":"劇烈搖晃","examples":[{"en":"The dramatic swaying was captured on film.","zh":"劇烈搖晃被拍攝下來。"},{"en":"Dramatic swaying means strong, noticeable, and possibly frightening side-to-side movement.","zh":"「dramatic swaying」意思是強烈、明顯且可能令人害怕的左右搖晃。"},{"en":"Trees showed dramatic swaying during the storm.","zh":"風暴期間，樹木出現劇烈搖晃。"},{"en":"If dramatic swaying is filmed, the public can see why people felt alarmed.","zh":"如果劇烈搖晃被拍下，公眾可以看到人們為何感到驚慌。"},{"en":"The phrase describes movement that is visually striking.","zh":"這個短語描述視覺上震撼的移動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":10},{"front":"be captured on film","meaning":"被拍攝下來","examples":[{"en":"The swaying was captured on film.","zh":"搖晃被拍攝下來。"},{"en":"To be captured on film means to be recorded by a camera.","zh":"「be captured on film」意思是被相機或攝影機記錄下來。"},{"en":"A school performance may be captured on film so parents can watch it later.","zh":"學校表演可能被拍攝下來，讓家長之後觀看。"},{"en":"If an engineering problem is captured on film, investigators can replay and measure it.","zh":"如果工程問題被拍下，調查人員可以重播和量度它。"},{"en":"The phrase describes visual recording.","zh":"這個短語描述影像記錄。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":10},{"front":"stop walking altogether","meaning":"完全停止步行","examples":[{"en":"People stopped walking altogether because they could not stay upright.","zh":"人們因不能保持站直而完全停止步行。"},{"en":"To stop walking altogether means to completely stop moving forward on foot.","zh":"「stop walking altogether」意思是完全停止向前步行。"},{"en":"Hikers may stop walking altogether if the path becomes too slippery.","zh":"如果路徑變得太滑，遠足者可能完全停止步行。"},{"en":"If a bridge sways too much, people may stop walking to avoid falling.","zh":"如果橋搖晃太多，人們可能停止步行以避免跌倒。"},{"en":"The phrase stresses a complete stop, not just slowing down.","zh":"這個短語強調完全停止，而不只是放慢。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":11},{"front":"keep upright","meaning":"保持站直","examples":[{"en":"Some pedestrians could not even keep upright.","zh":"有些行人甚至不能保持站直。"},{"en":"To keep upright means to stay standing without falling over.","zh":"「keep upright」意思是保持站立而不跌倒。"},{"en":"A toddler learning to walk struggles to keep upright at first.","zh":"剛學走路的幼兒起初難以保持站直。"},{"en":"If the ground moves strongly, even healthy adults may find it hard to stand straight.","zh":"如果地面強烈移動，即使健康成年人也可能難以站直。"},{"en":"The phrase focuses on staying vertical and balanced.","zh":"這個短語集中於保持垂直和平衡。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":11},{"front":"design a method of","meaning":"設計……的方法","examples":[{"en":"Engineers needed to design a method of reducing the movements.","zh":"工程師需要設計減少移動的方法。"},{"en":"To design a method of doing something means to create a planned way to achieve it.","zh":"「design a method of」做某事，意思是創造一套有計劃的方式來達成它。"},{"en":"A teacher may design a method of helping weak writers organise paragraphs.","zh":"老師可能設計一種幫助寫作較弱學生組織段落的方法。"},{"en":"If engineers design the right method, bridge movement can be controlled.","zh":"如果工程師設計出正確方法，橋樑移動可以被控制。"},{"en":"The phrase describes creating a practical solution.","zh":"這個短語描述創造實際解決方案。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":11},{"front":"reducing the movements","meaning":"減少移動","examples":[{"en":"The research programme aimed at reducing the movements.","zh":"該研究計劃旨在減少移動。"},{"en":"Reducing the movements means making the movements smaller, weaker, or less noticeable.","zh":"「reducing the movements」意思是令移動變小、變弱或較不明顯。"},{"en":"A doctor may suggest exercises for reducing painful movements in an injured knee.","zh":"醫生可能建議運動來減少受傷膝蓋的疼痛動作。"},{"en":"If dampers reduce bridge movements, pedestrians can walk more comfortably.","zh":"如果阻尼器減少橋樑移動，行人可以更舒適地行走。"},{"en":"The phrase focuses on controlling motion.","zh":"這個短語集中於控制動作。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":11},{"front":"immediate research programme","meaning":"即時研究計劃","examples":[{"en":"An immediate research programme was launched.","zh":"一項即時研究計劃展開了。"},{"en":"An immediate research programme is a study started quickly because the problem is urgent.","zh":"「immediate research programme」是因問題緊急而迅速開始的研究。"},{"en":"A hospital may start an immediate research programme when many patients show the same new symptom.","zh":"當許多病人出現相同新症狀，醫院可能展開即時研究計劃。"},{"en":"If a bridge closes suddenly, immediate research is needed before it can reopen.","zh":"如果橋突然關閉，它重開前需要即時研究。"},{"en":"The phrase describes urgent organised investigation.","zh":"這個短語描述緊急而有組織的調查。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":11},{"front":"be launched by","meaning":"由……展開","examples":[{"en":"The research programme was launched by Arup.","zh":"該研究計劃由 Arup 展開。"},{"en":"To be launched by someone means to be started or introduced by that person or organisation.","zh":"「be launched by」某人，意思是由該人或組織開始或推出。"},{"en":"A reading campaign may be launched by a school library.","zh":"閱讀活動可能由學校圖書館展開。"},{"en":"If a programme is launched by the project designer, it shows responsibility for solving the issue.","zh":"如果計劃由項目設計方展開，這顯示其解決問題的責任。"},{"en":"The phrase identifies who started an action.","zh":"這個短語指出行動由誰開始。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":11},{"front":"engineering designer","meaning":"工程設計方","examples":[{"en":"Arup was the bridge’s engineering designer.","zh":"Arup 是該橋的工程設計方。"},{"en":"An engineering designer is the person or company responsible for the technical design of a structure.","zh":"「engineering designer」是負責結構技術設計的人或公司。"},{"en":"An engineering designer may calculate loads, movement, materials, and safety limits.","zh":"工程設計方可能計算負荷、移動、材料和安全限制。"},{"en":"If a structure behaves unexpectedly, the engineering designer helps investigate and improve it.","zh":"如果結構表現出乎意料，工程設計方會協助調查和改良。"},{"en":"The phrase names the technical design role.","zh":"這個短語指出技術設計角色。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":11},{"front":"force exerted by","meaning":"由……施加的力","examples":[{"en":"The force exerted by pedestrians had to be quantified.","zh":"由行人施加的力必須被量化。"},{"en":"Force exerted by someone means the physical push, pull, or pressure they apply.","zh":"「force exerted by」某人，意思是他施加的物理推力、拉力或壓力。"},{"en":"The force exerted by a runner’s foot can affect the surface of a track.","zh":"跑手腳部施加的力可以影響跑道表面。"},{"en":"If engineers measure the force exerted by walkers, they can model bridge movement.","zh":"如果工程師量度步行者施加的力，他們可以模擬橋樑移動。"},{"en":"The phrase identifies the source of a force.","zh":"這個短語指出力量來源。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":11},{"front":"be quantified","meaning":"被量化","examples":[{"en":"The force exerted by pedestrians had to be quantified.","zh":"行人施加的力必須被量化。"},{"en":"To be quantified means to be measured and expressed in numbers.","zh":"「be quantified」意思是被量度並以數字表達。"},{"en":"A teacher may quantify improvement by comparing test scores before and after practice.","zh":"老師可能透過比較練習前後的測驗分數來量化進步。"},{"en":"If pedestrian force is quantified, engineers can use it in calculations.","zh":"如果行人力量被量化，工程師就可以把它用於計算。"},{"en":"The phrase describes turning an observation into measurable data.","zh":"這個短語描述把觀察轉化為可量度數據。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":11},{"front":"be related to","meaning":"與……聯繫起來","examples":[{"en":"The force had to be related to the motion of the bridge.","zh":"該力量必須與橋樑移動聯繫起來。"},{"en":"To be related to something means to be connected with it.","zh":"「be related to」某事，意思是與它有關聯。"},{"en":"A student’s tiredness may be related to sleeping too late.","zh":"學生疲倦可能與太夜睡覺有關。"},{"en":"If pedestrian force is related to bridge motion, one may influence the other.","zh":"如果行人力量與橋樑移動有關，一方可能影響另一方。"},{"en":"The phrase describes a connection between two things.","zh":"這個短語描述兩件事之間的關聯。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":11},{"front":"motion of the bridge","meaning":"橋樑移動","examples":[{"en":"The engineers studied the motion of the bridge.","zh":"工程師研究橋樑移動。"},{"en":"Motion of the bridge means the way the bridge moves, including direction, size, and rhythm.","zh":"「motion of the bridge」指橋如何移動，包括方向、幅度和節奏。"},{"en":"Engineers may use sensors to record the motion of a building during strong wind.","zh":"工程師可能使用感應器記錄建築物在強風中的移動。"},{"en":"If the bridge’s motion is understood, a safer design fix can be chosen.","zh":"如果理解橋樑移動，就可以選擇更安全的設計修正方案。"},{"en":"The phrase refers to movement of the structure.","zh":"這個短語指結構的移動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":11},{"front":"existing literature","meaning":"現有文獻","examples":[{"en":"Some descriptions of the phenomenon existed in the literature.","zh":"現有文獻中已有對該現象的一些描述。"},{"en":"Existing literature means research papers, books, or reports already written on a topic.","zh":"「existing literature」指某題目已有的研究論文、書籍或報告。"},{"en":"A student writing an essay checks the existing literature before making a claim.","zh":"學生寫文章前會查看現有文獻，再提出主張。"},{"en":"If existing literature describes a problem but lacks numbers, more research is needed.","zh":"如果現有文獻描述問題但缺乏數字，就需要更多研究。"},{"en":"The phrase refers to previous written research.","zh":"這個短語指先前的書面研究。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":12},{"front":"quantitative analytical way","meaning":"定量分析方法","examples":[{"en":"There was no quantitative analytical way to design against this effect.","zh":"當時沒有定量分析方法來設計橋樑以抵禦這種影響。"},{"en":"A quantitative analytical way is a method using numbers and calculations to understand a problem.","zh":"「quantitative analytical way」是使用數字和計算來理解問題的方法。"},{"en":"A school may use a quantitative method to analyse attendance data.","zh":"學校可能使用定量方法分析出席數據。"},{"en":"If engineers lack a quantitative method, they cannot design only by calculation.","zh":"如果工程師缺乏定量方法，他們不能只靠計算來設計。"},{"en":"The phrase describes a numerical approach to analysis.","zh":"這個短語描述數字化分析方法。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":12},{"front":"design the bridge against","meaning":"設計橋樑以抵禦……","examples":[{"en":"Engineers needed a way to design the bridge against this effect.","zh":"工程師需要一種方法來設計橋樑以抵禦這種影響。"},{"en":"To design the bridge against an effect means to design it so that the effect is resisted or controlled.","zh":"「design the bridge against」某影響，意思是設計橋樑使該影響被抵禦或控制。"},{"en":"Architects design buildings against strong wind in typhoon-prone cities.","zh":"在易受颱風影響的城市，建築師設計建築物以抵禦強風。"},{"en":"If a bridge must resist sideways movement, designers need specific engineering methods.","zh":"如果橋必須抵禦左右移動，設計者需要具體工程方法。"},{"en":"The phrase describes designing for protection against a known problem.","zh":"這個短語描述針對已知問題作防護設計。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":12},{"front":"receive support from","meaning":"得到……支持","examples":[{"en":"The efforts received support from universities and research organisations.","zh":"這些努力得到大學和研究機構支持。"},{"en":"To receive support from someone means to get help, resources, advice, or cooperation from them.","zh":"「receive support from」某人，意思是得到他們的幫助、資源、建議或合作。"},{"en":"A school project may receive support from parents and local businesses.","zh":"學校項目可能得到家長和本地企業支持。"},{"en":"If a complex investigation receives expert support, it can progress faster.","zh":"如果複雜調查得到專家支持，它可以更快推進。"},{"en":"The phrase describes help coming from outside or partner groups.","zh":"這個短語描述來自外部或合作群體的幫助。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":12},{"front":"research organisations","meaning":"研究機構","examples":[{"en":"Several research organisations supported the investigation.","zh":"幾個研究機構支持該調查。"},{"en":"Research organisations are groups that carry out studies and collect evidence.","zh":"「research organisations」是進行研究並收集證據的組織。"},{"en":"A health research organisation may study how exercise affects older people.","zh":"健康研究機構可能研究運動如何影響長者。"},{"en":"If research organisations join an engineering problem, they can provide methods and data.","zh":"如果研究機構參與工程問題，它們可以提供方法和數據。"},{"en":"The phrase names expert groups focused on investigation.","zh":"這個短語指出專注於調查的專家組織。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":12},{"front":"tests at the University of Southampton","meaning":"南安普敦大學的測試","examples":[{"en":"Tests at the University of Southampton involved walking on the spot.","zh":"南安普敦大學的測試涉及原地踏步。"},{"en":"Tests at the University of Southampton were experiments carried out at that university.","zh":"「tests at the University of Southampton」是在該大學進行的實驗。"},{"en":"A university may run tests on walking behaviour to help solve an engineering problem.","zh":"大學可能進行步行行為測試，以協助解決工程問題。"},{"en":"If one test studies walking on the spot, it may reveal balance reactions but not full walking behaviour.","zh":"如果測試研究原地踏步，它可能揭示平衡反應，但不是完整步行行為。"},{"en":"The phrase identifies where a particular experiment took place.","zh":"這個短語指出特定實驗發生的位置。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":12},{"front":"walking on the spot","meaning":"原地踏步","examples":[{"en":"The Southampton test involved a person walking on the spot.","zh":"南安普敦的測試涉及一個人原地踏步。"},{"en":"Walking on the spot means lifting and lowering the feet without moving forward.","zh":"「walking on the spot」意思是抬起和放下雙腳，但不向前移動。"},{"en":"A fitness teacher may ask students to walk on the spot as a warm-up.","zh":"健身老師可能要求學生原地踏步作熱身。"},{"en":"If a test uses walking on the spot, it may not fully copy real forward walking.","zh":"如果測試使用原地踏步，它未必完全複製真實向前步行。"},{"en":"The phrase describes movement without travelling.","zh":"這個短語描述沒有前進的移動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":12},{"front":"shake table","meaning":"振動台","examples":[{"en":"The person walked on the spot on a small shake table.","zh":"該人在一個小型振動台上原地踏步。"},{"en":"A shake table is a platform that can be moved or vibrated for testing.","zh":"「shake table」是可以移動或震動以進行測試的平台。"},{"en":"Engineers use shake tables to test how models behave during earthquakes.","zh":"工程師使用振動台測試模型在地震中如何表現。"},{"en":"If a person walks on a shake table, researchers can control the platform’s movement.","zh":"如果人在振動台上步行，研究人員可以控制平台移動。"},{"en":"The phrase names a laboratory testing device.","zh":"這個短語指出一種實驗室測試裝置。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":12},{"front":"Imperial College","meaning":"帝國理工學院","examples":[{"en":"Imperial College conducted tests on a specially built platform.","zh":"帝國理工學院在特別建造的平台上進行測試。"},{"en":"Imperial College is a university in London known for science and engineering.","zh":"「Imperial College」是倫敦一所以科學和工程聞名的大學。"},{"en":"Researchers at Imperial College may test materials, structures, and human movement.","zh":"帝國理工學院的研究人員可能測試材料、結構和人體移動。"},{"en":"If Imperial College conducted tests, the investigation gained academic engineering support.","zh":"如果帝國理工學院進行測試，該調查就獲得學術工程支援。"},{"en":"The phrase names the institution responsible for one set of experiments.","zh":"這個短語指出負責其中一組實驗的機構。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":12},{"front":"specially built platform","meaning":"特別建造的平台","examples":[{"en":"The Imperial College tests used a specially built platform.","zh":"帝國理工學院的測試使用特別建造的平台。"},{"en":"A specially built platform is a surface constructed for a particular test or purpose.","zh":"「specially built platform」是為特定測試或目的而建造的表面。"},{"en":"A science museum may use a specially built platform to demonstrate balance.","zh":"科學博物館可能使用特別建造的平台示範平衡。"},{"en":"If a platform is specially built, researchers can control its size, movement, and safety.","zh":"如果平台是特別建造的，研究人員可以控制其大小、移動和安全。"},{"en":"The phrase describes equipment made for a specific experiment.","zh":"這個短語描述為特定實驗製作的設備。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":12},{"front":"be driven laterally","meaning":"被橫向推動","examples":[{"en":"The platform could be driven laterally at different frequencies.","zh":"該平台可以在不同頻率下被橫向推動。"},{"en":"To be driven laterally means to be mechanically moved from side to side.","zh":"「be driven laterally」意思是被機械方式左右移動。"},{"en":"A test seat may be driven laterally to study how passengers react to sudden turns.","zh":"測試座椅可能被橫向推動，以研究乘客如何反應於突然轉彎。"},{"en":"If a platform is driven sideways, researchers can test walking responses to lateral motion.","zh":"如果平台被左右推動，研究人員可以測試對橫向移動的步行反應。"},{"en":"The phrase describes controlled side-to-side movement.","zh":"這個短語描述受控制的左右移動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":12},{"front":"frequencies and amplitudes","meaning":"頻率和振幅","examples":[{"en":"The platform moved at different frequencies and amplitudes.","zh":"該平台以不同頻率和振幅移動。"},{"en":"Frequencies and amplitudes are measurements of how often something moves and how large the movement is.","zh":"「frequencies and amplitudes」是量度某物移動多頻繁以及移動幅度多大的數值。"},{"en":"A sound wave has frequency and amplitude, which affect pitch and loudness.","zh":"聲波有頻率和振幅，影響音高和音量。"},{"en":"If a platform changes frequency and amplitude, researchers can test different movement conditions.","zh":"如果平台改變頻率和振幅，研究人員可以測試不同移動條件。"},{"en":"The phrase gives technical measurements of vibration.","zh":"這個短語提供震動的技術量度。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":13},{"front":"have limitations","meaning":"有局限","examples":[{"en":"These tests have their own limitations.","zh":"這些測試有其自身局限。"},{"en":"To have limitations means to have weaknesses or things that cannot be fully done.","zh":"「have limitations」意思是有弱點或無法完全做到的事情。"},{"en":"Online lessons have limitations if students lack quiet space or stable internet.","zh":"如果學生缺乏安靜空間或穩定網絡，網課就有局限。"},{"en":"If tests have limitations, their results must be used carefully.","zh":"如果測試有局限，其結果必須小心使用。"},{"en":"The phrase reminds us that evidence may be useful but incomplete.","zh":"這個短語提醒我們證據可能有用但不完整。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":13},{"front":"not long enough","meaning":"不夠長","examples":[{"en":"The Imperial College test platform was not long enough.","zh":"帝國理工學院的測試平台不夠長。"},{"en":"Not long enough means too short for the intended purpose.","zh":"「not long enough」意思是對預定目的而言太短。"},{"en":"A ruler is not long enough if it cannot measure the whole desk.","zh":"如果間尺不能量度整張書桌，它就不夠長。"},{"en":"If a walking platform is not long enough, researchers can observe only a few steps.","zh":"如果步行平台不夠長，研究人員只能觀察幾步。"},{"en":"The phrase describes insufficient length.","zh":"這個短語描述長度不足。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":13},{"front":"only seven or eight steps","meaning":"只有七八步","examples":[{"en":"Only seven or eight steps could be measured at one time.","zh":"每次只能量度七八步。"},{"en":"Only seven or eight steps means no more than a small number of walking steps.","zh":"「only seven or eight steps」意思是最多只有少量步行步數。"},{"en":"A short hallway may allow only seven or eight steps before a person reaches the door.","zh":"短走廊可能只容許人走七八步便到門口。"},{"en":"If only a few steps can be measured, long-distance walking patterns may not appear.","zh":"如果只能量度少數步，長距離步行模式可能不會出現。"},{"en":"The phrase highlights a data limitation.","zh":"這個短語突出數據局限。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":13},{"front":"accurately replicate","meaning":"準確複製","examples":[{"en":"The walking-on-the-spot test did not accurately replicate forward walking.","zh":"原地踏步測試未能準確複製向前步行。"},{"en":"To accurately replicate something means to copy it closely and correctly.","zh":"「accurately replicate」某事，意思是接近且正確地複製它。"},{"en":"A science experiment should accurately replicate real classroom conditions if it studies learning.","zh":"如果科學實驗研究學習，它應準確複製真實課室條件。"},{"en":"If a test does not replicate real walking, its results may not fully explain bridge behaviour.","zh":"如果測試不能複製真實步行，其結果可能無法完全解釋橋樑行為。"},{"en":"The phrase describes faithful reproduction of a real situation.","zh":"這個短語描述忠實重現真實情況。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":13},{"front":"forward walking","meaning":"向前步行","examples":[{"en":"Walking on the spot did not reproduce forward walking.","zh":"原地踏步並沒有重現向前步行。"},{"en":"Forward walking means walking ahead from one place to another.","zh":"「forward walking」意思是從一地向前走到另一地。"},{"en":"A treadmill partly copies forward walking, but the ground does not move past like a real path.","zh":"跑步機部分模仿向前步行，但地面不像真實路徑般在身旁經過。"},{"en":"If pedestrians move forward across a bridge, their behaviour may differ from walking in place.","zh":"如果行人在橋上向前步行，其行為可能不同於原地踏步。"},{"en":"The phrase contrasts with walking on the spot.","zh":"這個短語與原地踏步形成對比。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":13},{"front":"investigate any influence of","meaning":"研究……的任何影響","examples":[{"en":"Neither test could investigate any influence of other people.","zh":"兩個測試都不能研究其他人的任何影響。"},{"en":"To investigate any influence of something means to study whether it affects the result.","zh":"「investigate any influence of」某事，意思是研究它是否影響結果。"},{"en":"A teacher may investigate the influence of group work on students’ confidence.","zh":"老師可能研究小組活動對學生信心的任何影響。"},{"en":"If a test uses only one person, it cannot show how crowds affect behaviour.","zh":"如果測試只使用一個人，它不能顯示人群如何影響行為。"},{"en":"The phrase describes studying possible effects.","zh":"這個短語描述研究可能影響。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":13},{"front":"behaviour of the individual tested","meaning":"受測個人的行為","examples":[{"en":"The tests could not examine the behaviour of the individual tested in a crowd.","zh":"測試不能檢查受測個人在群眾中的行為。"},{"en":"Behaviour of the individual tested means how the person taking part in the test acts or responds.","zh":"「behaviour of the individual tested」指參與測試的人如何行動或反應。"},{"en":"A driving test observes the behaviour of the individual tested under traffic conditions.","zh":"駕駛考試會觀察受測個人在交通情況下的行為。"},{"en":"If a person behaves differently in a crowd, a solo test may miss that effect.","zh":"如果一個人在群眾中行為不同，單人測試可能忽略該影響。"},{"en":"The phrase focuses on one participant’s actions.","zh":"這個短語集中於單一參加者的行動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":13},{"front":"laboratory tests","meaning":"實驗室測試","examples":[{"en":"The results of the laboratory tests helped the engineers.","zh":"實驗室測試的結果幫助了工程師。"},{"en":"Laboratory tests are controlled experiments carried out in a lab.","zh":"「laboratory tests」是在實驗室進行的受控制實驗。"},{"en":"Doctors use laboratory tests to check blood, urine, or tissue samples.","zh":"醫生使用實驗室測試檢查血液、尿液或組織樣本。"},{"en":"If laboratory tests produce useful data, engineers can improve the design model.","zh":"如果實驗室測試產生有用數據，工程師可以改良設計模型。"},{"en":"The phrase describes controlled testing, not field observation.","zh":"這個短語描述受控制測試，而不是實地觀察。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":13},{"front":"provide information","meaning":"提供資料","examples":[{"en":"The laboratory tests provided useful information.","zh":"實驗室測試提供了有用資料。"},{"en":"To provide information means to give facts, data, or details that help understanding.","zh":"「provide information」意思是給予有助理解的事實、數據或細節。"},{"en":"A school notice provides information about exam dates and room numbers.","zh":"學校通告提供關於考試日期和課室號碼的資料。"},{"en":"If tests provide information about force and movement, engineers can make better decisions.","zh":"如果測試提供有關力量和移動的資料，工程師可以作出更好決定。"},{"en":"The phrase describes giving useful knowledge.","zh":"這個短語描述提供有用知識。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":13},{"front":"initial design of a retrofit","meaning":"改裝工程的初步設計","examples":[{"en":"The tests enabled the initial design of a retrofit to be progressed.","zh":"這些測試使改裝工程的初步設計得以推進。"},{"en":"Initial design of a retrofit means the first plan for modifying an existing structure to improve it.","zh":"「initial design of a retrofit」指為改善現有結構而作出的第一個改裝計劃。"},{"en":"A school may prepare an initial retrofit design before adding air-conditioning to old classrooms.","zh":"學校在為舊課室加裝冷氣前，可能準備改裝工程初步設計。"},{"en":"If test data are useful, the first repair plan can move forward.","zh":"如果測試數據有用，第一個維修方案就可以推進。"},{"en":"The phrase refers to an early improvement plan for something already built.","zh":"這個短語指已建成物件的早期改善計劃。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":13},{"front":"be progressed","meaning":"得以推進","examples":[{"en":"The design of the retrofit was progressed after the tests.","zh":"測試後，改裝設計得以推進。"},{"en":"To be progressed means to be moved forward or developed further.","zh":"「be progressed」意思是被推動向前或進一步發展。"},{"en":"A student’s essay plan can be progressed after the teacher gives feedback.","zh":"老師給予回饋後，學生的作文計劃可以得以推進。"},{"en":"If research answers key questions, an engineering solution can be progressed.","zh":"如果研究回答關鍵問題，工程解決方案可以推進。"},{"en":"The phrase describes development continuing to the next stage.","zh":"這個短語描述發展繼續進入下一階段。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":14},{"front":"unless","meaning":"除非","examples":[{"en":"Unless the usage of the bridge was restricted, other solutions were needed.","zh":"除非橋的使用受到限制，否則需要其他解決方法。"},{"en":"Unless means except if or if not.","zh":"「unless」意思是除非或如果不。"},{"en":"Students cannot enter the lab unless they wear safety glasses.","zh":"除非學生佩戴安全眼鏡，否則不能進入實驗室。"},{"en":"Unless bridge use is restricted, engineers must find a way to control movement safely.","zh":"除非限制橋的使用，否則工程師必須找到安全控制移動的方法。"},{"en":"The word introduces a condition.","zh":"這個詞引入條件。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":14},{"front":"greatly restricted","meaning":"大幅限制","examples":[{"en":"The usage of the bridge could not be greatly restricted.","zh":"這座橋的使用不能被大幅限制。"},{"en":"Greatly restricted means limited very strongly.","zh":"「greatly restricted」意思是被非常嚴格地限制。"},{"en":"A library’s opening hours are greatly restricted if it opens only two hours a day.","zh":"如果圖書館每天只開放兩小時，其開放時間就是被大幅限制。"},{"en":"If bridge access is greatly restricted, the bridge becomes less useful to the public.","zh":"如果橋樑通行被大幅限制，它對公眾就變得較不有用。"},{"en":"The phrase describes a severe limit.","zh":"這個短語描述嚴重限制。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":14},{"front":"generic options","meaning":"一般性選項","examples":[{"en":"Only two generic options were considered feasible.","zh":"只有兩個一般性選項被認為可行。"},{"en":"Generic options are broad general choices rather than detailed specific designs.","zh":"「generic options」是廣泛的一般選擇，而不是詳細具體設計。"},{"en":"A school choosing between “renovate” and “build new” is considering generic options.","zh":"學校在「翻新」和「新建」之間選擇，就是在考慮一般性選項。"},{"en":"If only two broad solutions are feasible, engineers must compare their costs and effects.","zh":"如果只有兩種廣泛方案可行，工程師必須比較其成本和效果。"},{"en":"The phrase describes general solution categories.","zh":"這個短語描述一般解決方案類別。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":14},{"front":"improve its performance","meaning":"改善其表現","examples":[{"en":"The options were designed to improve the bridge’s performance.","zh":"這些選項旨在改善橋的表現。"},{"en":"To improve its performance means to make it work better, more safely, or more effectively.","zh":"「improve its performance」意思是令它運作得更好、更安全或更有效。"},{"en":"A student can improve essay performance by using clearer paragraph structure.","zh":"學生可以透過使用更清晰段落結構來改善作文表現。"},{"en":"If a bridge’s performance improves, it can carry pedestrians with less uncomfortable movement.","zh":"如果橋樑表現改善，它可以讓行人通過時較少不適移動。"},{"en":"The phrase describes making function better.","zh":"這個短語描述改善功能。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":14},{"front":"be considered feasible","meaning":"被認為可行","examples":[{"en":"Two options were considered feasible.","zh":"兩個選項被認為可行。"},{"en":"To be considered feasible means to be judged possible and practical.","zh":"「be considered feasible」意思是被判斷為可能且實際可行。"},{"en":"A school trip plan is feasible if transport, budget, and safety can be arranged.","zh":"如果交通、預算和安全都能安排，學校旅行計劃就是可行的。"},{"en":"If an engineering option is feasible, it can realistically be built or applied.","zh":"如果工程選項可行，它就能實際建造或應用。"},{"en":"The phrase describes practical possibility.","zh":"這個短語描述實際可能性。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":14},{"front":"increase the stiffness of","meaning":"增加……的剛度","examples":[{"en":"One option was to increase the stiffness of the bridge.","zh":"一個選項是增加橋的剛度。"},{"en":"To increase the stiffness of something means to make it less flexible and harder to bend or move.","zh":"「increase the stiffness of」某物，意思是令它較不柔軟，較難彎曲或移動。"},{"en":"A carpenter may increase the stiffness of a shelf by adding a support bracket.","zh":"木匠可能透過加支架來增加架子的剛度。"},{"en":"If a bridge is made stiffer, it may move less under pedestrian forces.","zh":"如果橋變得更剛硬，它在行人力量下可能移動較少。"},{"en":"The phrase describes strengthening resistance to movement.","zh":"這個短語描述加強對移動的抵抗。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":14},{"front":"lateral natural frequencies","meaning":"橫向自然頻率","examples":[{"en":"The engineers wanted to move all lateral natural frequencies out of range.","zh":"工程師希望把所有橫向自然頻率移出範圍。"},{"en":"Lateral natural frequencies are the natural side-to-side vibration rates of a structure.","zh":"「lateral natural frequencies」是結構自然左右震動的速率。"},{"en":"Engineers study natural frequencies so buildings do not vibrate dangerously in wind.","zh":"工程師研究自然頻率，使建築物不會在風中危險震動。"},{"en":"If lateral natural frequencies match pedestrian forces, sideways swaying may increase.","zh":"如果橫向自然頻率配合行人力量，左右搖晃可能增加。"},{"en":"The phrase is a technical term about sideways vibration.","zh":"這個短語是關於橫向震動的技術術語。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":14},{"front":"out of the range","meaning":"超出範圍","examples":[{"en":"The frequencies had to be moved out of the range excited by footfall forces.","zh":"頻率必須被移到由踏步力激發的範圍之外。"},{"en":"Out of the range means outside the set of values where something can happen or have an effect.","zh":"「out of the range」意思是在某事能發生或產生影響的一組數值之外。"},{"en":"A phone may be out of the range of Wi-Fi if it is too far from the router.","zh":"如果電話離路由器太遠，它可能超出 Wi-Fi 範圍。"},{"en":"If bridge frequencies are moved out of the risky range, pedestrian steps are less likely to excite them.","zh":"如果橋的頻率被移出風險範圍，行人腳步較不可能激發它們。"},{"en":"The phrase describes moving beyond a dangerous or relevant limit.","zh":"這個短語描述移出危險或相關限制。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":14},{"front":"be excited by","meaning":"被……激發","examples":[{"en":"The bridge’s frequencies could be excited by lateral footfall forces.","zh":"橋的頻率可能被橫向踏步力激發。"},{"en":"To be excited by a force means to be set into vibration by that force.","zh":"「be excited by」某力量，意思是被該力量引發震動。"},{"en":"A drum surface is excited by a stick when it begins to vibrate and make sound.","zh":"鼓面被鼓棍敲擊後開始震動並發聲，就是被激發。"},{"en":"If a bridge frequency is excited by footsteps, the movement may grow stronger.","zh":"如果橋的頻率被腳步激發，移動可能變得更強。"},{"en":"The phrase is technical and refers to triggering vibration.","zh":"這個短語是技術用語，指觸發震動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":14},{"front":"lateral footfall forces","meaning":"橫向踏步力","examples":[{"en":"Pedestrians created lateral footfall forces.","zh":"行人產生橫向踏步力。"},{"en":"Lateral footfall forces are sideways forces produced when people step while walking.","zh":"「lateral footfall forces」是人們步行落腳時產生的側向力量。"},{"en":"A person stepping sideways on a platform creates lateral footfall force.","zh":"一個人在平台上側向踏步會產生橫向踏步力。"},{"en":"If many walkers create lateral footfall forces together, a bridge may sway.","zh":"如果許多步行者一起產生橫向踏步力，橋可能搖晃。"},{"en":"The phrase describes sideways force from footsteps.","zh":"這個短語描述來自腳步的側向力量。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":14},{"front":"increase the damping of","meaning":"增加……的阻尼","examples":[{"en":"The second option was to increase the damping of the bridge.","zh":"第二個選項是增加橋的阻尼。"},{"en":"To increase the damping of something means to increase its ability to reduce vibration.","zh":"「increase the damping of」某物，意思是提高其減少震動的能力。"},{"en":"A car’s shock absorbers increase damping so passengers feel fewer bumps.","zh":"汽車避震器增加阻尼，使乘客較少感到顛簸。"},{"en":"If bridge damping is increased, swaying can die down more quickly.","zh":"如果橋樑阻尼增加，搖晃可以更快減弱。"},{"en":"The phrase describes adding resistance to vibration.","zh":"這個短語描述增加對震動的阻力。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":15},{"front":"resonant response","meaning":"共振反應","examples":[{"en":"Increasing damping could reduce the resonant response.","zh":"增加阻尼可以減少共振反應。"},{"en":"Resonant response is strong movement caused when repeated force matches a structure’s natural vibration.","zh":"「resonant response」是當重複力量配合結構自然震動時造成的強烈移動。"},{"en":"A playground swing shows resonant response when each push arrives at the right time.","zh":"當每次推動都在正確時間到達，遊樂場鞦韆就顯示共振反應。"},{"en":"If damping is increased, resonant response becomes weaker and safer.","zh":"如果增加阻尼，共振反應會變弱並更安全。"},{"en":"The phrase describes vibration growing because timing matches.","zh":"這個短語描述因時間配合而增長的震動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":15},{"front":"choose four letters","meaning":"選擇四個字母","examples":[{"en":"Students choose four letters from the list.","zh":"學生從清單中選擇四個字母。"},{"en":"Choose four letters means select exactly four option letters as answers.","zh":"「choose four letters」意思是準確選出四個選項字母作答案。"},{"en":"In a reading task, students may choose four letters that match the passage evidence.","zh":"在閱讀題中，學生可能選擇四個符合文章證據的字母。"},{"en":"If the instruction says four, choosing three or five may lose marks.","zh":"如果指示說四個，選三個或五個都可能失分。"},{"en":"The phrase is an exam instruction about answer number.","zh":"這個短語是關於答案數量的考試指示。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":15},{"front":"open to the public","meaning":"向公眾開放","examples":[{"en":"The question asks what could be seen when the bridge opened to the public.","zh":"問題問這座橋向公眾開放時可以看到甚麼。"},{"en":"Open to the public means available for ordinary people to enter or use.","zh":"「open to the public」意思是普通人可以進入或使用。"},{"en":"A museum is open to the public when anyone can buy a ticket and visit.","zh":"當任何人都可以買票參觀時，博物館就是向公眾開放。"},{"en":"If a bridge opens to the public, large numbers of people may use it immediately.","zh":"如果橋向公眾開放，大量人可能立即使用它。"},{"en":"The phrase describes public access.","zh":"這個短語描述公眾使用權。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":15},{"front":"move vertically","meaning":"垂直移動","examples":[{"en":"The option says the bridge moved vertically.","zh":"該選項說橋垂直移動。"},{"en":"To move vertically means to move up and down.","zh":"「move vertically」意思是上下移動。"},{"en":"A lift moves vertically between floors.","zh":"升降機在樓層之間垂直移動。"},{"en":"If a bridge moves vertically, people feel rising and falling rather than side-to-side swaying.","zh":"如果橋垂直移動，人們會感到上升和下降，而不是左右搖晃。"},{"en":"The phrase contrasts with lateral movement.","zh":"這個短語與橫向移動形成對比。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":15},{"front":"sway from side to side","meaning":"左右搖晃","examples":[{"en":"The bridge swayed from side to side.","zh":"這座橋左右搖晃。"},{"en":"To sway from side to side means to move repeatedly left and right.","zh":"「sway from side to side」意思是反覆向左和向右移動。"},{"en":"A tree may sway from side to side in strong wind.","zh":"樹木在強風中可能左右搖晃。"},{"en":"If a bridge sways from side to side, pedestrians may change their steps to keep balance.","zh":"如果橋左右搖晃，行人可能改變步伐以保持平衡。"},{"en":"The phrase describes lateral movement in simple words.","zh":"這個短語以簡單字眼描述橫向移動。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":15},{"front":"violently throughout","meaning":"全程劇烈地","examples":[{"en":"The option says the bridge swayed violently throughout the opening ceremony.","zh":"該選項說橋在整個開幕禮全程劇烈地搖晃。"},{"en":"Violently throughout means strongly and continuously during the whole event.","zh":"「violently throughout」意思是在整個事件期間強烈而持續地。"},{"en":"A tent may shake violently throughout a storm if it is poorly secured.","zh":"如果帳篷固定不良，它可能在整場風暴中全程劇烈地搖動。"},{"en":"If something happens throughout a ceremony, it lasts from beginning to end.","zh":"如果某事在整個典禮期間發生，它就從開始持續到結束。"},{"en":"The phrase combines intensity with duration.","zh":"這個短語結合強度與持續時間。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":15},{"front":"keep one’s balance","meaning":"保持平衡","examples":[{"en":"It was difficult for pedestrians to keep their balance.","zh":"行人很難保持平衡。"},{"en":"To keep one’s balance means to stay steady and avoid falling.","zh":"「keep one’s balance」意思是保持穩定並避免跌倒。"},{"en":"A skater must keep her balance on ice.","zh":"溜冰者必須在冰上保持平衡。"},{"en":"If the surface moves suddenly, people may hold railings to keep balance.","zh":"如果表面突然移動，人們可能抓住欄杆來保持平衡。"},{"en":"The phrase describes physical stability.","zh":"這個短語描述身體穩定。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":15},{"front":"synchronised steps","meaning":"同步步伐","examples":[{"en":"The option refers to pedestrians walking in synchronised steps.","zh":"該選項指行人以同步步伐行走。"},{"en":"Synchronised steps are steps taken at the same time and rhythm by different people.","zh":"「synchronised steps」是不同人以相同時間和節奏踏出的步伐。"},{"en":"Soldiers in a parade often move with synchronised steps.","zh":"巡遊中的士兵常以同步步伐移動。"},{"en":"If many walkers use synchronised steps on a bridge, their forces may combine.","zh":"如果許多步行者在橋上使用同步步伐，他們的力量可能合併。"},{"en":"The phrase describes coordinated walking.","zh":"這個短語描述協調步行。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":15},{"front":"lengthen one’s footsteps","meaning":"拉長步伐","examples":[{"en":"The option says pedestrians lengthened their footsteps.","zh":"該選項說行人拉長步伐。"},{"en":"To lengthen one’s footsteps means to take longer steps than usual.","zh":"「lengthen one’s footsteps」意思是踏出比平常更長的步伐。"},{"en":"A runner may lengthen her footsteps near the finish line.","zh":"跑手接近終點時可能拉長步伐。"},{"en":"If people lengthen their footsteps, their walking rhythm and force may change.","zh":"如果人們拉長步伐，他們的步行節奏和力量可能改變。"},{"en":"The phrase describes changing step size.","zh":"這個短語描述改變步幅。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":15},{"front":"march across","meaning":"步操橫過","examples":[{"en":"A music band marched across the bridge.","zh":"一隊樂隊步操橫過橋。"},{"en":"To march across means to walk from one side to another in a steady, organised rhythm.","zh":"「march across」意思是以穩定、有組織的節奏從一邊走到另一邊。"},{"en":"Students may march across the playground during a school parade.","zh":"學生可能在學校巡遊中步操橫過操場。"},{"en":"If a group marches across a flexible bridge, their rhythm may matter.","zh":"如果一群人步操橫過柔性橋樑，他們的節奏可能很重要。"},{"en":"The phrase describes rhythmic crossing.","zh":"這個短語描述有節奏地橫過。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":15},{"front":"swaying rhythm","meaning":"搖晃節奏","examples":[{"en":"The swaying rhythm varied between different sections of the bridge.","zh":"橋的不同部分之間搖晃節奏不同。"},{"en":"Swaying rhythm means the repeated pattern or timing of side-to-side movement.","zh":"「swaying rhythm」是左右移動的重複模式或時間節奏。"},{"en":"A boat has a swaying rhythm when waves move it regularly.","zh":"當波浪有規律地移動小船，小船就有搖晃節奏。"},{"en":"If bridge sections have different swaying rhythms, engineers must study each section separately.","zh":"如果橋的不同部分有不同搖晃節奏，工程師必須分別研究每部分。"},{"en":"The phrase describes the timing pattern of movement.","zh":"這個短語描述移動的時間模式。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":16},{"front":"different sections of","meaning":"……的不同部分","examples":[{"en":"The bridge moved differently in different sections.","zh":"這座橋在不同部分有不同移動方式。"},{"en":"Different sections of something are separate parts within the whole.","zh":"「different sections of」某物，是整體中的不同部分。"},{"en":"A supermarket has different sections for fruit, bread, drinks, and frozen food.","zh":"超級市場有水果、麵包、飲品和冷凍食品等不同部分。"},{"en":"If different sections of a bridge move differently, one repair method may not fit all parts.","zh":"如果橋的不同部分移動方式不同，一種維修方法未必適合所有部分。"},{"en":"The phrase divides a whole object into parts.","zh":"這個短語把整體分成部分。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":16},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the summary that follows.","zh":"「complete the summary below」意思是填寫下方摘要中的空缺字詞。"},{"en":"In a reading test, students complete a summary by finding exact words in the text.","zh":"在閱讀測驗中，學生透過在文本中找準確字詞完成摘要。"},{"en":"If the summary uses passage words, students must check grammar and word limits.","zh":"如果摘要使用文章字詞，學生必須檢查文法和字數限制。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":16},{"front":"no more than two words","meaning":"不多於兩個字","examples":[{"en":"Students should choose no more than two words from the passage.","zh":"學生應從文章中選擇不多於兩個字。"},{"en":"No more than two words means one or two words only, not three or more.","zh":"「no more than two words」意思是只可一個或兩個字，不可三個或更多。"},{"en":"If the answer is “natural frequency”, it fits a two-word limit.","zh":"如果答案是 “natural frequency”，它符合兩字限制。"},{"en":"If students write extra words, the answer may be wrong even when the idea is correct.","zh":"如果學生寫多了字，即使意思正確，答案也可能錯。"},{"en":"The phrase sets a strict word limit.","zh":"這個短語設定嚴格字數限制。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":16},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must come from the passage.","zh":"答案必須來自文章。"},{"en":"From the passage means using words or information directly from the text.","zh":"「from the passage」意思是使用直接來自文本的字詞或資料。"},{"en":"In reading exams, students should not invent answers from general knowledge.","zh":"在閱讀考試中，學生不應用常識創作答案。"},{"en":"If answers must come from the passage, students should copy wording carefully.","zh":"如果答案必須來自文章，學生應小心抄寫用詞。"},{"en":"The phrase tells students to rely on the source text.","zh":"這個短語告訴學生依賴來源文本。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":16},{"front":"understand why","meaning":"理解為何","examples":[{"en":"Engineers studied the video to understand why the bridge swayed.","zh":"工程師研究影片以理解為何橋會搖晃。"},{"en":"To understand why means to know the reason or cause behind something.","zh":"「understand why」意思是知道某事背後的原因或成因。"},{"en":"A teacher may talk to a student to understand why homework is often late.","zh":"老師可能與學生交談，以理解為何功課常常遲交。"},{"en":"If engineers understand why a bridge moves, they can design a better solution.","zh":"如果工程師理解為何橋會移動，他們就能設計更好的解決方案。"},{"en":"The phrase focuses on finding the cause.","zh":"這個短語集中於找出原因。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":16},{"front":"force of wind","meaning":"風力","examples":[{"en":"At first, engineers thought the force of wind might have caused the movement.","zh":"起初，工程師認為風力可能造成該移動。"},{"en":"Force of wind means the physical push created by moving air.","zh":"「force of wind」意思是流動空氣產生的物理推力。"},{"en":"The force of wind can knock over signs during a storm.","zh":"風暴期間，風力可以吹倒招牌。"},{"en":"If flags are large, the force of wind on them can be strong.","zh":"如果旗幟很大，作用在它們上的風力可以很強。"},{"en":"The phrase describes wind as a physical cause.","zh":"這個短語把風描述為物理原因。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":16},{"front":"new explanations emerged","meaning":"新解釋出現","examples":[{"en":"New explanations emerged after tests on walking surfaces.","zh":"在步行表面測試後，新解釋出現。"},{"en":"New explanations emerged means new ways of understanding the problem appeared.","zh":"「new explanations emerged」意思是理解問題的新方式出現。"},{"en":"New explanations emerged after doctors compared many patients’ symptoms.","zh":"醫生比較許多病人的症狀後，新解釋出現。"},{"en":"If tests reveal unexpected results, earlier assumptions may be replaced by new explanations.","zh":"如果測試揭示意外結果，早期假設可能被新解釋取代。"},{"en":"The phrase describes understanding developing after evidence appears.","zh":"這個短語描述證據出現後理解有所發展。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":16},{"front":"moving floor","meaning":"移動的地面","examples":[{"en":"People spread their legs to maintain balance on a moving floor.","zh":"人們在移動的地面上把雙腳分開以維持平衡。"},{"en":"A moving floor is a surface underfoot that shifts or moves while people stand or walk on it.","zh":"「moving floor」是人在站立或行走時腳下會移動的表面。"},{"en":"A ship’s deck can feel like a moving floor during rough weather.","zh":"在惡劣天氣中，船甲板可能感覺像移動的地面。"},{"en":"If the floor moves sideways, people may widen their stance to stay stable.","zh":"如果地面左右移動，人們可能把站姿放寬以保持穩定。"},{"en":"The phrase describes an unstable walking surface.","zh":"這個短語描述不穩定的行走表面。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":16},{"front":"maintain balance","meaning":"維持平衡","examples":[{"en":"People adjust their walking to maintain balance.","zh":"人們調整步行方式以維持平衡。"},{"en":"To maintain balance means to keep the body steady and avoid falling.","zh":"「maintain balance」意思是保持身體穩定並避免跌倒。"},{"en":"A cyclist must maintain balance while turning a corner.","zh":"單車手轉彎時必須維持平衡。"},{"en":"If a surface is unstable, people change their steps to maintain balance.","zh":"如果表面不穩，人們會改變步伐以維持平衡。"},{"en":"The phrase describes keeping stability during movement.","zh":"這個短語描述移動時保持穩定。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":16},{"front":"unconsciously adjust","meaning":"無意識地調整","examples":[{"en":"Pedestrians may unconsciously adjust their footsteps.","zh":"行人可能無意識地調整步伐。"},{"en":"To unconsciously adjust means to change something automatically without realising it.","zh":"「unconsciously adjust」意思是在沒有意識到的情況下自動改變某事。"},{"en":"A student may unconsciously adjust posture when a chair feels uncomfortable.","zh":"當椅子不舒服時，學生可能無意識地調整姿勢。"},{"en":"If pedestrians unconsciously adjust their steps to bridge movement, their behaviour may affect the bridge.","zh":"如果行人無意識地調整步伐來配合橋樑移動，他們的行為可能影響橋。"},{"en":"The phrase describes automatic adaptation.","zh":"這個短語描述自動適應。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":16},{"front":"match a bridge’s sway","meaning":"配合橋的搖晃","examples":[{"en":"Pedestrians adjust their footsteps to match a bridge’s sway.","zh":"行人調整步伐以配合橋的搖晃。"},{"en":"To match a bridge’s sway means to move in time with the bridge’s side-to-side movement.","zh":"「match a bridge’s sway」意思是按橋左右搖晃的節奏移動。"},{"en":"A person on a moving boat may match the boat’s motion to avoid losing balance.","zh":"小船上的人可能配合船的移動，以避免失去平衡。"},{"en":"If many walkers match a bridge’s sway, their steps can make the movement worse.","zh":"如果許多步行者配合橋的搖晃，他們的腳步可以令移動惡化。"},{"en":"The phrase describes synchronising with the bridge’s motion.","zh":"這個短語描述與橋樑動作同步。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":17},{"front":"walking, running and jumping","meaning":"步行、跑步和跳躍","examples":[{"en":"Walking, running and jumping can cause lateral forces.","zh":"步行、跑步和跳躍可以造成橫向力量。"},{"en":"Walking, running and jumping are human movements that place repeated forces on a surface.","zh":"「walking, running and jumping」是對表面施加重複力量的人體動作。"},{"en":"A gym floor must withstand walking, running and jumping during sports lessons.","zh":"體育館地板必須承受體育課中的步行、跑步和跳躍。"},{"en":"If many people move this way on a flexible structure, vibration may increase.","zh":"如果許多人在柔性結構上這樣移動，震動可能增加。"},{"en":"The phrase groups common body movements that can affect structures.","zh":"這個短語把可以影響結構的常見身體動作歸為一組。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":17},{"front":"no longer stand upright","meaning":"不再能站穩","examples":[{"en":"Pedestrians may no longer be able to stand upright.","zh":"行人可能不再能站穩。"},{"en":"To no longer stand upright means to stop being able to remain standing straight.","zh":"「no longer stand upright」意思是不再能保持直立站着。"},{"en":"A person on a slippery bus floor may no longer stand upright without holding a rail.","zh":"在濕滑巴士地板上，人不抓住扶手可能不再能站穩。"},{"en":"If bridge swaying becomes too strong, standing safely can become impossible.","zh":"如果橋搖晃變得太強，安全站立可能變得不可能。"},{"en":"The phrase describes losing physical stability.","zh":"這個短語描述失去身體穩定。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":17},{"front":"complete the table below","meaning":"完成下列表格","examples":[{"en":"Students complete the table below using words from the passage.","zh":"學生使用文章中的字詞完成下列表格。"},{"en":"Complete the table below means fill in the missing spaces in the table that follows.","zh":"「complete the table below」意思是填寫下方表格中的空格。"},{"en":"In reading exams, students may complete a table with names, methods, and limitations.","zh":"在閱讀考試中，學生可能用名稱、方法和局限完成表格。"},{"en":"If a table answer must come from the passage, students should copy the wording accurately.","zh":"如果表格答案必須來自文章，學生應準確抄寫用詞。"},{"en":"The phrase is a common instruction for table-completion questions.","zh":"這個短語是表格填充題的常見指示。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":17},{"front":"test conducted by","meaning":"由……進行的測試","examples":[{"en":"The table asks who the test was conducted by.","zh":"表格問該測試由誰進行。"},{"en":"Test conducted by means the person, university, or organisation that carried out the test.","zh":"「test conducted by」指進行測試的人、大學或組織。"},{"en":"A science report may list each test conducted by different student groups.","zh":"科學報告可能列出由不同學生小組進行的每項測試。"},{"en":"If students know who conducted a test, they can match results to the correct institution.","zh":"如果學生知道測試由誰進行，就能把結果配對到正確機構。"},{"en":"The phrase identifies the test organiser.","zh":"這個短語指出測試組織者。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":17},{"front":"limitation","meaning":"局限","examples":[{"en":"The table lists the limitation of each test.","zh":"表格列出每項測試的局限。"},{"en":"A limitation is a weakness or restriction that makes something less complete or less useful.","zh":"「limitation」是令某事較不完整或較不有用的弱點或限制。"},{"en":"A survey has a limitation if only ten people answer it.","zh":"如果只有十個人回答，調查就有局限。"},{"en":"If an experiment has limitations, its findings should be interpreted carefully.","zh":"如果實驗有局限，其發現應謹慎解讀。"},{"en":"The word points to what a method cannot fully do.","zh":"這個詞指出某方法不能完全做到的地方。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":17},{"front":"insufficient data collection","meaning":"數據收集不足","examples":[{"en":"One limitation was insufficient data collection.","zh":"一項局限是數據收集不足。"},{"en":"Insufficient data collection means not enough information was gathered to answer the question fully.","zh":"「insufficient data collection」意思是收集到的資料不足以完整回答問題。"},{"en":"A school survey has insufficient data collection if only one class responds.","zh":"如果只有一班回應，學校調查就有數據收集不足的問題。"},{"en":"If data collection is insufficient, conclusions may be weak or incomplete.","zh":"如果數據收集不足，結論可能薄弱或不完整。"},{"en":"The phrase describes a research weakness caused by too little evidence.","zh":"這個短語描述由證據太少造成的研究弱點。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":17},{"front":"reproduce real forward walking","meaning":"重現真實向前步行","examples":[{"en":"One test did not reproduce real forward walking.","zh":"一項測試未能重現真實向前步行。"},{"en":"To reproduce real forward walking means to copy the way people actually walk ahead in normal conditions.","zh":"「reproduce real forward walking」意思是複製人們在正常條件下實際向前步行的方式。"},{"en":"A treadmill test may not fully reproduce real forward walking outdoors.","zh":"跑步機測試未必能完全重現戶外真實向前步行。"},{"en":"If a test fails to reproduce real walking, it may miss important body movements.","zh":"如果測試未能重現真實步行，它可能錯過重要身體動作。"},{"en":"The phrase describes accurately copying normal walking behaviour.","zh":"這個短語描述準確複製正常步行行為。"}],"source":"36 - THE BRIDGE THAT SWAYED.pdf","sourcePage":17}],"ielts/reading/passage-2/Practice 37":[{"front":"storytelling","meaning":"講故事；敘事","examples":[{"en":"Storytelling has developed from prehistoric caves to modern cinemas.","zh":"講故事從史前洞穴發展到現代戲院。"},{"en":"Storytelling means the art of telling events, characters and emotions in a way that holds people’s attention.","zh":"講故事是以吸引人注意的方式講述事件、人物和情感的藝術。"},{"en":"A teacher uses storytelling when she explains history through the life of one ordinary family.","zh":"老師透過一個普通家庭的人生來解釋歷史時，就是在講故事。"},{"en":"Good storytelling can make listeners want to know what happens next.","zh":"好的敘事可以令聽眾想知道接下來會發生甚麼。"},{"en":"The phrase refers to the whole act of shaping and sharing a story, not just reading words aloud.","zh":"這個短語指塑造和分享故事的整個行為，而不只是大聲讀字。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":1},{"front":"prehistoric caves","meaning":"史前洞穴","examples":[{"en":"The title connects prehistoric caves with modern cinemas.","zh":"標題把史前洞穴與現代戲院連繫起來。"},{"en":"Prehistoric caves are caves from the time before written history.","zh":"史前洞穴是文字歷史出現以前時期的洞穴。"},{"en":"People may imagine prehistoric caves as places where early humans painted animals on walls.","zh":"人們可能把史前洞穴想像成早期人類在牆上畫動物的地方。"},{"en":"If storytelling began in prehistoric caves, it suggests that humans told stories long before books existed.","zh":"如果講故事始於史前洞穴，這表示人類在書本出現很久以前已經講故事。"},{"en":"The phrase gives a very ancient setting for human culture.","zh":"這個短語給出一個非常古老的人類文化背景。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":1},{"front":"modern cinemas","meaning":"現代戲院","examples":[{"en":"Modern cinemas are today’s major places for storytelling.","zh":"現代戲院是今日講故事的重要場所。"},{"en":"Modern cinemas are buildings where people watch films on large screens with sound.","zh":"現代戲院是人們在大銀幕上觀看有聲電影的建築物。"},{"en":"Families may go to modern cinemas to enjoy action films, comedies or animated stories.","zh":"家庭可能到現代戲院欣賞動作片、喜劇或動畫故事。"},{"en":"If cinemas attract large audiences, film becomes a powerful form of public storytelling.","zh":"如果戲院吸引大量觀眾，電影就成為有力的大眾敘事形式。"},{"en":"The phrase contrasts today’s film spaces with older forms of storytelling.","zh":"這個短語把今日的電影空間與較古老的講故事形式作對比。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":1},{"front":"it was told","meaning":"它被講述","examples":[{"en":"The first story was probably told to people around a fire.","zh":"第一個故事可能是講給圍在火堆旁的人聽的。"},{"en":"It was told means the story was spoken or narrated to an audience.","zh":"“It was told” 指故事被說出或講述給觀眾聽。"},{"en":"A family story may be told again every New Year so children remember their grandparents.","zh":"家庭故事可能每年新年再被講述一次，讓孩子記得祖父母。"},{"en":"If a story is told well, people may remember it even without writing it down.","zh":"如果故事講得好，即使沒有寫下來，人們也可能記住它。"},{"en":"The phrase focuses on the act of speaking a story to others.","zh":"這個短語強調把故事說給他人聽的行為。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":1},{"front":"crouched around a fire","meaning":"蹲在火堆旁","examples":[{"en":"People may have crouched around a fire to hear a story.","zh":"人們可能蹲在火堆旁聽故事。"},{"en":"To crouch around a fire means to sit or bend low near a fire, often for warmth or attention.","zh":"“Crouch around a fire” 指在火堆附近低身坐着或蹲着，通常為了取暖或集中注意。"},{"en":"Campers may crouch around a fire at night while someone tells a frightening story.","zh":"露營者晚上可能蹲在火堆旁，聽某人講恐怖故事。"},{"en":"If people crouch around a fire, the small circle can make the story feel intimate and dramatic.","zh":"如果人們蹲在火堆旁，這個小圈子可以令故事感覺親密而有戲劇性。"},{"en":"The phrase creates an image of early humans listening closely together.","zh":"這個短語營造早期人類聚在一起專心聆聽的畫面。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":1},{"front":"a tale of adventure","meaning":"冒險故事","examples":[{"en":"The first fireside story was probably a tale of adventure.","zh":"第一個爐邊故事可能是一個冒險故事。"},{"en":"A tale of adventure is a story about danger, journeys, courage or exciting events.","zh":"冒險故事是關於危險、旅程、勇氣或刺激事件的故事。"},{"en":"A child may enjoy a tale of adventure about explorers crossing a jungle.","zh":"孩子可能喜歡關於探險家穿越叢林的冒險故事。"},{"en":"If a story includes risk and discovery, it can easily become a tale of adventure.","zh":"如果故事包含風險和發現，它很容易成為冒險故事。"},{"en":"The phrase describes an exciting story rather than an ordinary report.","zh":"這個短語描述刺激的故事，而不是普通報告。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":1},{"front":"close encounter with death","meaning":"與死亡擦身而過的經歷","examples":[{"en":"The tale may have related a close encounter with death.","zh":"這個故事可能講述一次與死亡擦身而過的經歷。"},{"en":"A close encounter with death is a situation where someone almost dies but survives.","zh":"與死亡擦身而過的經歷，是某人差點死亡但最後生還的情況。"},{"en":"A driver may describe a close encounter with death after narrowly avoiding a crash.","zh":"司機險些撞車後，可能描述一次與死亡擦身而過的經歷。"},{"en":"If a story includes a close encounter with death, listeners usually feel tension and relief.","zh":"如果故事包含與死亡擦身而過的經歷，聽眾通常會感到緊張和鬆一口氣。"},{"en":"The phrase describes danger that comes very near but does not finally kill someone.","zh":"這個短語描述危險非常接近，但最終沒有奪去性命。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":1},{"front":"mortal danger","meaning":"致命危險","examples":[{"en":"The story may have described an escape from mortal danger.","zh":"這個故事可能描述一次逃離致命危險的經歷。"},{"en":"Mortal danger means danger that can cause death.","zh":"致命危險指可能導致死亡的危險。"},{"en":"A swimmer caught in a strong current may be in mortal danger.","zh":"被強勁水流捲住的泳客可能處於致命危險之中。"},{"en":"If a character escapes mortal danger, the audience may feel shocked, excited and relieved.","zh":"如果角色逃離致命危險，觀眾可能感到震驚、緊張和鬆一口氣。"},{"en":"The phrase is stronger than ordinary danger because life is at risk.","zh":"這個短語比普通危險更強，因為生命受到威脅。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":1},{"front":"out of the ordinary","meaning":"不尋常的事","examples":[{"en":"The story may have described something out of the ordinary.","zh":"這個故事可能描述某件不尋常的事。"},{"en":"Out of the ordinary means unusual, special or different from normal experience.","zh":"“Out of the ordinary” 指不普通、特別或不同於正常經驗。"},{"en":"Seeing snow in a usually hot city would be something out of the ordinary.","zh":"在通常炎熱的城市看見下雪，就是不尋常的事。"},{"en":"If an event is out of the ordinary, people are more likely to tell others about it.","zh":"如果事件不尋常，人們更可能把它告訴別人。"},{"en":"The phrase explains why an experience may become a story.","zh":"這個短語解釋為何某段經歷可能成為故事。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":1},{"front":"whatever its thread","meaning":"無論故事主線是甚麼","examples":[{"en":"Whatever its thread, the story had a prime purpose.","zh":"無論故事主線是甚麼，這個故事都有一個主要目的。"},{"en":"Whatever its thread means whatever the main line or direction of the story was.","zh":"“Whatever its thread” 指無論故事的主要線索或方向是甚麼。"},{"en":"Whatever its thread, a good classroom example should still teach the target phrase clearly.","zh":"無論例句主線是甚麼，好的課堂例子仍應清楚教出目標短語。"},{"en":"If a story’s thread changes, the audience still needs a reason to keep listening.","zh":"如果故事主線改變，觀眾仍需要一個理由繼續聽下去。"},{"en":"The phrase refers to the main path of a story while allowing different possible plots.","zh":"這個短語指故事的主要路徑，同時容許不同情節。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":1},{"front":"weaving of this story","meaning":"編織這個故事","examples":[{"en":"The weaving of this story was done with a clear purpose.","zh":"編織這個故事是帶着清楚目的進行的。"},{"en":"The weaving of a story means the careful shaping and connecting of its events, characters and details.","zh":"編織故事指仔細塑造並連接故事中的事件、人物和細節。"},{"en":"A writer weaves a story when she links a child’s memory, a family secret and a final discovery.","zh":"作家把孩子的記憶、家庭秘密和最後發現連繫起來時，就是在編織故事。"},{"en":"If the weaving of a story is weak, the audience may feel the events do not fit together.","zh":"如果故事編織得弱，觀眾可能覺得事件不夠連貫。"},{"en":"The phrase compares storytelling to making cloth from connected threads.","zh":"這個短語把講故事比作由相連線索織成布。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":1},{"front":"prime purpose","meaning":"主要目的","examples":[{"en":"The prime purpose was to keep listeners interested.","zh":"主要目的是讓聽眾保持興趣。"},{"en":"The prime purpose of something is its main and most important aim.","zh":"某事的主要目的是其最重要的目標。"},{"en":"The prime purpose of a fire alarm is to warn people quickly before danger spreads.","zh":"火警鐘的主要目的是在危險蔓延前迅速警告人們。"},{"en":"If a story’s prime purpose is to hold attention, every scene should make listeners curious.","zh":"如果故事的主要目的是吸引注意，每一幕都應令聽眾好奇。"},{"en":"The phrase highlights the chief reason for doing something.","zh":"這個短語突出做某事的首要原因。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":2},{"front":"be kept listening","meaning":"被吸引着繼續聽","examples":[{"en":"The listeners had to be kept listening.","zh":"聽眾必須被吸引着繼續聽。"},{"en":"To be kept listening means to remain interested enough to continue hearing the story.","zh":"“Be kept listening” 指保持足夠興趣而繼續聆聽故事。"},{"en":"A teacher keeps students listening by asking a question before revealing the answer.","zh":"老師先提出問題再揭示答案，可以讓學生繼續聽。"},{"en":"If listeners are not kept listening, even an important message may be forgotten.","zh":"如果聽眾沒有被吸引着繼續聽，即使重要訊息也可能被忘記。"},{"en":"The phrase focuses on maintaining attention over time.","zh":"這個短語強調隨時間維持注意力。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":2},{"front":"fall asleep","meaning":"睡着","examples":[{"en":"The listeners must not fall asleep.","zh":"聽眾一定不能睡着。"},{"en":"To fall asleep means to begin sleeping, often because one is tired or bored.","zh":"“Fall asleep” 指開始入睡，通常因疲倦或沉悶。"},{"en":"A student may fall asleep in class if the lesson is too late and too dull.","zh":"如果課堂太晚又太沉悶，學生可能在課堂上睡着。"},{"en":"If a storyteller is boring, the audience may lose attention or even fall asleep.","zh":"如果講故事的人沉悶，觀眾可能失去注意力，甚至睡着。"},{"en":"The phrase can describe literal sleep or a loss of interest.","zh":"這個短語可以描述真正入睡，也可以暗示失去興趣。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":2},{"front":"as the story went on","meaning":"隨着故事發展","examples":[{"en":"As the story went on, the audience’s interest had to be sustained.","zh":"隨着故事發展，觀眾的興趣必須被維持。"},{"en":"As the story went on means while the story continued and moved forward.","zh":"“As the story went on” 指故事繼續並向前推進時。"},{"en":"As the lesson went on, the teacher added examples to keep students focused.","zh":"隨着課堂進行，老師加入例子讓學生保持專注。"},{"en":"If a story becomes weaker as it goes on, listeners may stop caring before the ending.","zh":"如果故事隨着發展變弱，聽眾可能在結局前已不再在乎。"},{"en":"The phrase describes what happens during the continuing progress of a story.","zh":"這個短語描述故事持續推進期間發生的事。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":2},{"front":"audience’s interest","meaning":"觀眾的興趣","examples":[{"en":"The audience’s interest had to be sustained.","zh":"觀眾的興趣必須被維持。"},{"en":"The audience’s interest is the attention and curiosity felt by people watching or listening.","zh":"觀眾的興趣是觀看或聆聽的人所感到的注意力和好奇心。"},{"en":"A speaker can keep the audience’s interest by using real examples and clear questions.","zh":"演講者可以透過真實例子和清晰問題維持觀眾的興趣。"},{"en":"If the audience’s interest disappears, they may stop listening even before the main point arrives.","zh":"如果觀眾的興趣消失，他們可能在重點出現前已停止聆聽。"},{"en":"The phrase refers to the mental attention of viewers or listeners.","zh":"這個短語指觀眾或聽眾的心理注意力。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":2},{"front":"be sustained by","meaning":"由……維持","examples":[{"en":"The audience’s interest was sustained by one question.","zh":"觀眾的興趣由一個問題維持。"},{"en":"To be sustained by something means to be kept going or maintained by it.","zh":"“Be sustained by” 某事指由它保持或維持下去。"},{"en":"A student’s motivation may be sustained by small improvements each week.","zh":"學生的動力可能由每週的小進步維持。"},{"en":"If curiosity is sustained by one question, the audience keeps waiting for the answer.","zh":"如果好奇心由一個問題維持，觀眾就會一直等待答案。"},{"en":"The phrase shows what keeps something alive or continuing.","zh":"這個短語顯示甚麼令某事保持或延續。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":2},{"front":"above all","meaning":"最重要的是","examples":[{"en":"One question mattered above all: what happens next?","zh":"有一個問題最重要：接下來會發生甚麼？"},{"en":"Above all means more than anything else or most importantly.","zh":"“Above all” 指比任何其他事情更重要，或最重要的是。"},{"en":"In an emergency, above all, people must stay calm and follow safety instructions.","zh":"在緊急情況下，最重要的是人們必須保持冷靜並遵守安全指示。"},{"en":"If a story wants to hold attention, above all it must create curiosity.","zh":"如果故事想吸引注意，最重要的是必須製造好奇心。"},{"en":"The phrase introduces the most important point.","zh":"這個短語引出最重要的一點。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":2},{"front":"What happens next?","meaning":"接下來會發生甚麼？","examples":[{"en":"A good story makes the audience ask, “What happens next?”","zh":"好故事會令觀眾問：「接下來會發生甚麼？」"},{"en":"“What happens next?” is the question that keeps people curious about the next event in a story.","zh":"“What happens next?” 是讓人對故事下一件事保持好奇的問題。"},{"en":"A mystery film works well when every scene makes viewers wonder what happens next.","zh":"如果每一幕都令觀眾想知道接下來會發生甚麼，懸疑片就很成功。"},{"en":"If the audience stops asking this question, the story may feel predictable or dull.","zh":"如果觀眾不再問這個問題，故事可能變得可預測或沉悶。"},{"en":"The phrase captures suspense and forward movement in storytelling.","zh":"這個短語捕捉了敘事中的懸念和推進感。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":2},{"front":"fireside stories","meaning":"爐邊故事","examples":[{"en":"The first fireside stories in human history can never be known.","zh":"人類歷史上最早的爐邊故事永遠無法得知。"},{"en":"Fireside stories are stories told around a fire, often in a small group.","zh":"爐邊故事是圍着火堆講述的故事，通常在小群體中進行。"},{"en":"Families may tell fireside stories during camping trips after dinner.","zh":"家庭可能在露營晚飯後講爐邊故事。"},{"en":"If stories are told by firelight, the setting can make them feel warmer or more mysterious.","zh":"如果故事在火光下講述，場景可以令它們感覺更溫暖或更神秘。"},{"en":"The phrase suggests oral storytelling before books and screens.","zh":"這個短語暗示書本和螢幕以前的口述故事。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":2},{"front":"human history","meaning":"人類歷史","examples":[{"en":"The first fireside stories in human history were not written down.","zh":"人類歷史上最早的爐邊故事沒有被寫下來。"},{"en":"Human history means the whole past of human life, society and culture.","zh":"人類歷史指人類生活、社會和文化的整個過去。"},{"en":"Farming, writing and cities are major developments in human history.","zh":"農業、文字和城市都是人類歷史中的重大發展。"},{"en":"If something belongs to early human history, direct evidence may be limited.","zh":"如果某事屬於早期人類歷史，直接證據可能有限。"},{"en":"The phrase gives a very broad historical frame.","zh":"這個短語提供非常廣闊的歷史框架。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":2},{"front":"can never be known","meaning":"永遠無法得知","examples":[{"en":"The first fireside stories can never be known.","zh":"最早的爐邊故事永遠無法得知。"},{"en":"Can never be known means it is impossible for people to find out the truth with certainty.","zh":"“Can never be known” 指人們不可能確定找出真相。"},{"en":"What one ancient child first said to another may never be known.","zh":"一個古代孩子最先對另一個孩子說了甚麼，可能永遠無法得知。"},{"en":"If no record survives, historians may guess, but the exact answer can never be known.","zh":"如果沒有紀錄保存下來，歷史學家可以推測，但準確答案永遠無法得知。"},{"en":"The phrase shows a permanent limit on knowledge.","zh":"這個短語顯示知識上的永久限制。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":2},{"front":"be kept in the heads of","meaning":"被記在……腦海中","examples":[{"en":"The stories were kept in the heads of those who told them.","zh":"這些故事被記在講述者的腦海中。"},{"en":"To be kept in the heads of people means to be remembered rather than written down.","zh":"“Be kept in the heads of” 某些人指被記住，而不是被寫下。"},{"en":"A grandmother’s recipe may be kept in her head instead of in a cookbook.","zh":"祖母的食譜可能記在她腦海中，而不是在食譜書中。"},{"en":"If stories are kept in people’s heads, memory becomes the storage system.","zh":"如果故事被記在人的腦海中，記憶就成為儲存系統。"},{"en":"The phrase describes oral memory as a way of preserving information.","zh":"這個短語描述口頭記憶作為保存資料的方法。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":3},{"front":"method of storage","meaning":"儲存方法","examples":[{"en":"This method of storage is not necessarily inefficient.","zh":"這種儲存方法不一定低效。"},{"en":"A method of storage is a way of keeping information, objects or materials for later use.","zh":"儲存方法是保存資訊、物件或材料以供日後使用的方式。"},{"en":"A phone is a method of storage for photos, messages and contacts.","zh":"手機是儲存照片、訊息和聯絡人的方法。"},{"en":"If memory stores thousands of lines accurately, it can be an effective method of storage.","zh":"如果記憶能準確儲存數以千計行文字，它就可以是有效的儲存方法。"},{"en":"The phrase explains how something is preserved.","zh":"這個短語解釋某事如何被保存。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":3},{"front":"not necessarily inefficient","meaning":"不一定低效","examples":[{"en":"Oral memory is not necessarily inefficient.","zh":"口頭記憶不一定低效。"},{"en":"Not necessarily inefficient means not always slow, weak or wasteful.","zh":"“Not necessarily inefficient” 指不一定慢、弱或浪費。"},{"en":"Handwritten notes are not necessarily inefficient if they help students remember better.","zh":"如果手寫筆記幫助學生記得更好，它們不一定低效。"},{"en":"If an old method works well in practice, it is not necessarily inferior to a modern one.","zh":"如果舊方法在實際上有效，它不一定比現代方法差。"},{"en":"The phrase challenges an easy negative assumption.","zh":"這個短語挑戰容易出現的負面假設。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":3},{"front":"documented oral traditions","meaning":"有記錄的口述傳統","examples":[{"en":"Documented oral traditions show the power of memory.","zh":"有記錄的口述傳統顯示記憶的力量。"},{"en":"Documented oral traditions are spoken storytelling practices that have been recorded or studied.","zh":"有記錄的口述傳統是已被記錄或研究的口頭敘事做法。"},{"en":"Researchers may document oral traditions by recording elders telling community histories.","zh":"研究人員可能透過錄下長者講述社區歷史來記錄口述傳統。"},{"en":"If oral traditions are documented, people can see how accurately stories were preserved.","zh":"如果口述傳統有記錄，人們就能看見故事保存得有多準確。"},{"en":"The phrase connects spoken culture with written or recorded evidence.","zh":"這個短語把口頭文化與書面或錄音證據連繫起來。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":3},{"front":"specialised storytellers","meaning":"專門講故事的人","examples":[{"en":"Specialised storytellers can recite thousands of lines from memory.","zh":"專門講故事的人可以憑記憶背誦數以千計的行文。"},{"en":"Specialised storytellers are people trained or known for telling stories as a particular skill.","zh":"專門講故事的人，是受過訓練或以講故事為特定技能的人。"},{"en":"In some communities, specialised storytellers preserve history, family names and myths.","zh":"在一些社群中，專門講故事的人保存歷史、家族名字和神話。"},{"en":"If a storyteller is specialised, listeners may expect accuracy, rhythm and dramatic skill.","zh":"如果講故事者是專門的，聽眾可能期待準確、節奏和戲劇技巧。"},{"en":"The phrase describes storytelling as a learned role, not just casual talking.","zh":"這個短語把講故事描述為一種學習而來的角色，而不只是隨意說話。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":3},{"front":"recite from memory","meaning":"憑記憶背誦","examples":[{"en":"Some storytellers can recite from memory thousands of lines.","zh":"有些講故事的人可以憑記憶背誦數以千計的行文。"},{"en":"To recite from memory means to speak words aloud without reading them.","zh":"“Recite from memory” 指不用閱讀文本而大聲說出文字。"},{"en":"A student may recite a poem from memory during a school performance.","zh":"學生可能在學校表演中憑記憶背誦一首詩。"},{"en":"If someone can recite a long story from memory, they have practised it many times.","zh":"如果某人能憑記憶背誦長故事，他必定練習過很多次。"},{"en":"The phrase focuses on accurate spoken recall.","zh":"這個短語強調準確的口頭回憶。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":3},{"front":"literally thousands of lines","meaning":"真正數以千計的行文","examples":[{"en":"Storytellers can recite literally thousands of lines.","zh":"講故事的人可以背誦真正數以千計的行文。"},{"en":"Literally thousands of lines means really thousands of lines, not just “many” in a loose sense.","zh":"“Literally thousands of lines” 指真的有數以千計行，而不只是籠統地說「很多」。"},{"en":"A student writing a thesis may read literally thousands of lines of notes.","zh":"寫論文的學生可能閱讀真正數以千計行筆記。"},{"en":"If performers remember literally thousands of lines, their memory skill is remarkable.","zh":"如果表演者記得真正數以千計行文字，其記憶能力就非常驚人。"},{"en":"The phrase stresses that the number is genuinely very large.","zh":"這個短語強調數量確實非常大。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":3},{"front":"in verse or prose","meaning":"以詩體或散文形式","examples":[{"en":"They can recite stories in verse or prose.","zh":"他們可以以詩體或散文形式背誦故事。"},{"en":"In verse or prose means in poetic lines or in ordinary written language.","zh":"“In verse or prose” 指以詩歌行文或普通書面語形式。"},{"en":"A story can be told in verse like a poem or in prose like a novel.","zh":"故事可以像詩一樣以詩體講述，也可以像小說一樣以散文講述。"},{"en":"If storytellers know both verse and prose, they can use different rhythms and styles.","zh":"如果講故事的人懂得詩體和散文，就能使用不同節奏和風格。"},{"en":"The phrase contrasts two major forms of writing and speech.","zh":"這個短語對比兩種主要寫作和說話形式。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":3},{"front":"verbatim","meaning":"逐字地","examples":[{"en":"Some oral storytellers can repeat stories verbatim.","zh":"有些口述講故事者可以逐字重複故事。"},{"en":"Verbatim means using exactly the same words as the original.","zh":"“Verbatim” 指使用與原文完全相同的字詞。"},{"en":"A witness may be asked to repeat a sentence verbatim during an investigation.","zh":"證人在調查中可能被要求逐字重複一句話。"},{"en":"If a storyteller repeats a tale verbatim, the wording is preserved very accurately.","zh":"如果講故事者逐字重複故事，措辭就保存得非常準確。"},{"en":"The word stresses word-for-word accuracy.","zh":"這個詞強調一字不差的準確性。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":3},{"front":"word for word","meaning":"一字不差地","examples":[{"en":"Verbatim means word for word.","zh":"Verbatim 的意思是一字不差地。"},{"en":"Word for word means exactly as written or spoken, without changing the wording.","zh":"“Word for word” 指完全按照寫出或說出的字句，不改變措辭。"},{"en":"A student should not copy an article word for word unless quotation is allowed.","zh":"除非允許引用，學生不應一字不差地抄襲文章。"},{"en":"If instructions must be followed word for word, small changes may cause mistakes.","zh":"如果指示必須一字不差地跟從，小改動也可能造成錯誤。"},{"en":"The phrase explains exact repetition.","zh":"這個短語解釋精確重複。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":3},{"front":"be rightly considered","meaning":"被正確地視為","examples":[{"en":"Memory is rightly considered an art in itself.","zh":"記憶被正確地視為本身就是一門藝術。"},{"en":"To be rightly considered something means people are correct to regard it in that way.","zh":"“Be rightly considered” 某物指人們這樣看待它是正確的。"},{"en":"Good listening is rightly considered an important part of communication.","zh":"良好聆聽被正確地視為溝通的重要部分。"},{"en":"If a skill requires training and judgement, it may be rightly considered an art.","zh":"如果一項技能需要訓練和判斷，它可以被正確地視為一門藝術。"},{"en":"The phrase shows that a judgement is reasonable and deserved.","zh":"這個短語顯示某判斷合理且應得。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":3},{"front":"an art in itself","meaning":"本身就是一門藝術","examples":[{"en":"Memory can be considered an art in itself.","zh":"記憶可以被視為本身就是一門藝術。"},{"en":"An art in itself means something is valuable and skilful on its own, not only as a tool for another task.","zh":"“An art in itself” 指某事本身有價值和技巧，而不只是另一任務的工具。"},{"en":"Clear handwriting can be an art in itself when each letter is carefully shaped.","zh":"如果每個字母都仔細塑造，清晰書法本身也可以是一門藝術。"},{"en":"If memory is an art in itself, remembering a story is not just mechanical storage.","zh":"如果記憶本身就是一門藝術，記住故事就不只是機械式儲存。"},{"en":"The phrase gives respect to a skill as an independent craft.","zh":"這個短語把一項技能作為獨立工藝來尊重。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":4},{"front":"primary purpose of","meaning":"……的主要目的","examples":[{"en":"The primary purpose of making symbols is to create reminders.","zh":"製作符號的主要目的是創造提示。"},{"en":"The primary purpose of something is its main function or reason for existing.","zh":"某事的主要目的是其主要功能或存在原因。"},{"en":"The primary purpose of a timetable is to help people organise time.","zh":"時間表的主要目的是幫助人組織時間。"},{"en":"If a symbol’s primary purpose is memory, it does not need to tell the whole story by itself.","zh":"如果符號的主要目的是記憶，它不需要單獨講完整個故事。"},{"en":"The phrase identifies the chief aim before other possible uses.","zh":"這個短語先指出主要目標，再談其他可能用途。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":4},{"front":"making symbols","meaning":"製作符號","examples":[{"en":"Making symbols helps people remember information.","zh":"製作符號幫助人們記住資料。"},{"en":"Making symbols means creating signs, marks or images that stand for ideas or memories.","zh":"製作符號指創造代表想法或記憶的標誌、記號或圖像。"},{"en":"A student may make symbols in the margin to mark important points in a textbook.","zh":"學生可能在課本頁邊製作符號來標記重點。"},{"en":"If symbols are clear, they can remind people of information without using many words.","zh":"如果符號清楚，它們可以不用很多文字也提醒人們資料。"},{"en":"The phrase describes turning meaning into visible signs.","zh":"這個短語描述把意義變成可見記號。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":4},{"front":"system of reminders","meaning":"提示系統","examples":[{"en":"Symbols can form a system of reminders.","zh":"符號可以形成一套提示系統。"},{"en":"A system of reminders is an organised set of signs or cues that help people remember things.","zh":"提示系統是一組有組織的標誌或線索，幫助人記住事情。"},{"en":"A student may use colours, stars and arrows as a system of reminders in revision notes.","zh":"學生可能在溫習筆記中使用顏色、星號和箭嘴作為提示系統。"},{"en":"If reminders are organised, they can guide memory step by step.","zh":"如果提示有組織，它們可以逐步引導記憶。"},{"en":"The phrase describes memory support made from connected cues.","zh":"這個短語描述由相連線索組成的記憶支援。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":4},{"front":"mnemonic cues","meaning":"記憶提示","examples":[{"en":"Mnemonic cues help us recall information.","zh":"記憶提示幫助我們回想資料。"},{"en":"Mnemonic cues are memory aids that help people remember facts, steps or words.","zh":"記憶提示是幫助人記住事實、步驟或詞語的記憶輔助。"},{"en":"A student may use the first letters of a list as mnemonic cues before an exam.","zh":"學生可能在考試前使用列表首字母作為記憶提示。"},{"en":"If a cue reminds someone of the next part, a long speech becomes easier to remember.","zh":"如果提示能提醒某人下一部分，長演講就更容易記住。"},{"en":"The phrase refers to clues designed to support memory.","zh":"這個短語指為支援記憶而設計的線索。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":4},{"front":"assist someone to","meaning":"幫助某人去……","examples":[{"en":"Signs assist us to recall certain information.","zh":"標誌幫助我們回想某些資料。"},{"en":"To assist someone to do something means to help them do it.","zh":"“Assist someone to” 做某事指幫助某人完成該事。"},{"en":"A checklist can assist students to remember what to bring for a school trip.","zh":"清單可以幫助學生記得學校旅行要帶甚麼。"},{"en":"If visual signs assist memory, people do not have to rely only on words.","zh":"如果視覺標誌幫助記憶，人們就不必只依靠文字。"},{"en":"The phrase is a formal way to say “help someone to.”","zh":"這個短語是 “help someone to” 的較正式說法。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":4},{"front":"recall information","meaning":"回想資料","examples":[{"en":"Symbols help us recall information in the mind’s eye.","zh":"符號幫助我們在腦海中回想資料。"},{"en":"To recall information means to bring facts, images or memories back into your mind.","zh":"“Recall information” 指把事實、圖像或記憶帶回腦中。"},{"en":"A smell from the kitchen may help someone recall information about childhood meals.","zh":"廚房傳來的氣味可能幫助某人回想童年飯菜的資料。"},{"en":"If students review often, they can recall information more quickly in exams.","zh":"如果學生經常溫習，就能在考試中更快回想資料。"},{"en":"The phrase describes remembering something that has been stored in the mind.","zh":"這個短語描述記起已儲存在腦中的東西。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":4},{"front":"mind’s eye","meaning":"腦海；心目中","examples":[{"en":"Mnemonic cues help us recall information in the mind’s eye.","zh":"記憶提示幫助我們在腦海中回想資料。"},{"en":"The mind’s eye is the ability to imagine or see pictures mentally.","zh":"“Mind’s eye” 是在心裏想像或看見畫面的能力。"},{"en":"When reading a novel, students may see the setting in their mind’s eye.","zh":"閱讀小說時，學生可能在腦海中看見場景。"},{"en":"If a symbol creates a strong mental image, the mind’s eye helps memory work better.","zh":"如果符號創造強烈心理圖像，腦海中的畫面就能幫助記憶更好運作。"},{"en":"The phrase refers to inner imagination rather than physical sight.","zh":"這個短語指內在想像，而不是實際視覺。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":4},{"front":"Polynesian communities","meaning":"波利尼西亞社群","examples":[{"en":"Some Polynesian communities used memory sticks for storytelling.","zh":"一些波利尼西亞社群使用記憶棒來講故事。"},{"en":"Polynesian communities are groups of people from Polynesia, a region of islands in the Pacific.","zh":"波利尼西亞社群是來自太平洋島嶼地區波利尼西亞的人群。"},{"en":"A community may preserve stories through songs, objects and repeated public recitations.","zh":"社群可能透過歌曲、物件和反覆公開背誦保存故事。"},{"en":"If Polynesian communities used memory sticks, their storytelling had practical memory tools.","zh":"如果波利尼西亞社群使用記憶棒，他們的敘事就有實用記憶工具。"},{"en":"The phrase identifies cultural groups connected with a particular island region.","zh":"這個短語指出與特定島嶼地區相關的文化群體。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":4},{"front":"notched memory stick","meaning":"有刻痕的記憶棒","examples":[{"en":"A notched memory stick may guide a storyteller.","zh":"有刻痕的記憶棒可以引導講故事者。"},{"en":"A notched memory stick is a stick with cuts or marks used as reminders.","zh":"有刻痕的記憶棒是帶有切痕或記號、用作提示的棒。"},{"en":"A child might make notches on a ruler to remember steps in a game.","zh":"孩子可能在尺上刻痕，以記住遊戲步驟。"},{"en":"If each notch represents a part of the story, the stick helps the storyteller keep the order.","zh":"如果每個刻痕代表故事的一部分，記憶棒就幫助講故事者保持次序。"},{"en":"The phrase describes a simple physical tool for memory.","zh":"這個短語描述用於記憶的簡單實物工具。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":4},{"front":"guide a storyteller through","meaning":"引導講故事者完成……","examples":[{"en":"The stick can guide a storyteller through stages of recitation.","zh":"這根棒可以引導講故事者完成背誦的各個階段。"},{"en":"To guide a storyteller through something means to help them move through each part in order.","zh":"“Guide a storyteller through” 某事指幫助講故事者按次序完成每一部分。"},{"en":"A slide outline can guide a speaker through a long presentation.","zh":"投影片大綱可以引導演講者完成長匯報。"},{"en":"If a tool guides the storyteller through the story, it reduces the chance of forgetting a section.","zh":"如果工具引導講故事者完成故事，就能減少忘記某部分的機會。"},{"en":"The phrase describes support during a step-by-step performance.","zh":"這個短語描述逐步表演期間的支援。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":4},{"front":"successive stages of","meaning":"連續階段的……","examples":[{"en":"The stick helps with successive stages of recitation.","zh":"這根棒幫助完成背誦的連續階段。"},{"en":"Successive stages of something are steps that follow one after another in order.","zh":"“Successive stages of” 某事指按次序一個接一個出現的步驟。"},{"en":"A science experiment may have successive stages of planning, testing and recording results.","zh":"科學實驗可能有規劃、測試和記錄結果等連續階段。"},{"en":"If a story has successive stages, the storyteller must remember the order clearly.","zh":"如果故事有連續階段，講故事者必須清楚記住次序。"},{"en":"The phrase emphasises sequence and progression.","zh":"這個短語強調次序和推進。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":5},{"front":"recitation","meaning":"背誦；朗誦","examples":[{"en":"The memory stick guides the storyteller through recitation.","zh":"記憶棒引導講故事者完成背誦。"},{"en":"Recitation is the act of speaking a poem, story or text aloud from memory.","zh":"背誦或朗誦是憑記憶大聲說出詩、故事或文本的行為。"},{"en":"Students may practise recitation before a poetry competition.","zh":"學生可能在詩歌比賽前練習朗誦。"},{"en":"If recitation is long, memory cues can help the speaker avoid mistakes.","zh":"如果背誦內容很長，記憶提示可以幫助說話者避免錯誤。"},{"en":"The word refers to spoken performance based on memory.","zh":"這個詞指基於記憶的口頭表演。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":5},{"front":"in other parts of the world","meaning":"在世界其他地方","examples":[{"en":"In other parts of the world, storytelling helped create writing systems.","zh":"在世界其他地方，講故事幫助創造文字系統。"},{"en":"In other parts of the world means in different places beyond the one already discussed.","zh":"“In other parts of the world” 指在剛討論地區以外的不同地方。"},{"en":"In other parts of the world, students may start school at a different age.","zh":"在世界其他地方，學生可能在不同年齡開始上學。"},{"en":"If a practice appears in other parts of the world, it may be a widespread human pattern.","zh":"如果某種做法出現在世界其他地方，它可能是廣泛的人類模式。"},{"en":"The phrase broadens the discussion to more regions.","zh":"這個短語把討論擴展到更多地區。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":5},{"front":"historically resulted in","meaning":"在歷史上導致","examples":[{"en":"Storytelling historically resulted in the development of writing systems.","zh":"講故事在歷史上導致文字系統的發展。"},{"en":"Historically resulted in means caused or helped cause something in the course of history.","zh":"“Historically resulted in” 指在歷史過程中造成或促成某事。"},{"en":"The need to trade historically resulted in better counting systems.","zh":"貿易需要在歷史上促成了更好的計數系統。"},{"en":"If storytelling historically resulted in writing, then stories helped push communication forward.","zh":"如果講故事在歷史上導致文字出現，那故事就推動了溝通向前發展。"},{"en":"The phrase connects a past practice with a later historical development.","zh":"這個短語把過去做法與後來歷史發展連繫起來。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":5},{"front":"development of writing systems","meaning":"文字系統的發展","examples":[{"en":"Storytelling contributed to the development of writing systems.","zh":"講故事促成了文字系統的發展。"},{"en":"The development of writing systems means the process by which people created organised ways to record language.","zh":"文字系統的發展指人們創造有組織方法來記錄語言的過程。"},{"en":"The development of writing systems allowed laws, stories and trade records to be preserved.","zh":"文字系統的發展使法律、故事和貿易記錄得以保存。"},{"en":"If stories needed to be saved accurately, writing systems became more useful.","zh":"如果故事需要準確保存，文字系統就變得更有用。"},{"en":"The phrase refers to the growth of written communication.","zh":"這個短語指書面溝通的成長。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":5},{"front":"invention of writing systems","meaning":"文字系統的發明","examples":[{"en":"Storytelling may even have led to the invention of writing systems.","zh":"講故事甚至可能導致文字系統的發明。"},{"en":"The invention of writing systems means the creation of organised marks that represent spoken language.","zh":"文字系統的發明指創造代表口語的有組織記號。"},{"en":"The invention of writing systems changed how people stored laws, myths and accounts.","zh":"文字系統的發明改變了人們儲存法律、神話和帳目的方式。"},{"en":"If a society wants to preserve long stories, it may need written symbols.","zh":"如果社會想保存長故事，就可能需要書面符號。"},{"en":"The phrase points to the beginning of writing as a human technology.","zh":"這個短語指文字作為人類科技的開端。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":5},{"front":"arrival of literacy","meaning":"讀寫能力的出現","examples":[{"en":"One theory explains the arrival of literacy in ancient Greece.","zh":"有一種理論解釋古希臘讀寫能力的出現。"},{"en":"The arrival of literacy means the point when reading and writing became present or important in a society.","zh":"讀寫能力的出現指閱讀和書寫在某社會中開始存在或變得重要的時刻。"},{"en":"The arrival of literacy in a village can change education, trade and record keeping.","zh":"讀寫能力在村莊出現，可以改變教育、貿易和記錄保存。"},{"en":"If literacy arrives because stories need preserving, culture helps drive writing.","zh":"如果讀寫能力因故事需要保存而出現，文化就推動了文字。"},{"en":"The phrase describes the emergence of reading and writing ability.","zh":"這個短語描述閱讀和書寫能力的興起。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":5},{"front":"ancient Greece","meaning":"古希臘","examples":[{"en":"The arrival of literacy in ancient Greece may be linked to epic tales.","zh":"古希臘讀寫能力的出現可能與史詩故事有關。"},{"en":"Ancient Greece refers to the Greek-speaking civilisation of the ancient Mediterranean world.","zh":"古希臘指古代地中海世界中說希臘語的文明。"},{"en":"Students study ancient Greece to learn about philosophy, theatre, politics and myths.","zh":"學生研究古希臘，以了解哲學、戲劇、政治和神話。"},{"en":"If literacy spread in ancient Greece, it helped preserve poems and dramatic works.","zh":"如果讀寫能力在古希臘傳播，它就幫助保存詩歌和戲劇作品。"},{"en":"The phrase gives a historical and cultural setting.","zh":"這個短語給出歷史和文化背景。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":5},{"front":"epic tales","meaning":"史詩故事","examples":[{"en":"The epic tales about Troy and Odysseus were enchanting to hear.","zh":"關於特洛伊和奧德修斯的史詩故事聽起來令人入迷。"},{"en":"Epic tales are long, grand stories about heroes, journeys, war or destiny.","zh":"史詩故事是關於英雄、旅程、戰爭或命運的宏大長篇故事。"},{"en":"A culture may preserve epic tales because they explain bravery, identity and shared memory.","zh":"一種文化可能保存史詩故事，因為它們解釋勇氣、身份和共同記憶。"},{"en":"If an epic tale is exciting and meaningful, people may want it written down for future generations.","zh":"如果史詩故事刺激又有意義，人們可能希望把它寫下來留給後代。"},{"en":"The phrase describes large-scale heroic stories.","zh":"這個短語描述大規模的英雄故事。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":5},{"front":"Trojan War","meaning":"特洛伊戰爭","examples":[{"en":"The epic tales included stories about the Trojan War.","zh":"史詩故事包括關於特洛伊戰爭的故事。"},{"en":"The Trojan War is the legendary war connected with Troy in ancient Greek stories.","zh":"特洛伊戰爭是古希臘故事中與特洛伊相關的傳奇戰爭。"},{"en":"Students may meet the Trojan War when reading myths about Achilles, Hector and Helen.","zh":"學生閱讀關於阿基里斯、赫克托爾和海倫的神話時，可能接觸到特洛伊戰爭。"},{"en":"If a story refers to the Trojan War, it often carries themes of honour, conflict and loss.","zh":"如果故事提到特洛伊戰爭，通常帶有榮譽、衝突和失落的主題。"},{"en":"The phrase names a famous legendary war from Greek tradition.","zh":"這個短語指希臘傳統中的著名傳奇戰爭。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":5},{"front":"wanderings of Odysseus","meaning":"奧德修斯的漂泊旅程","examples":[{"en":"The Greeks preserved tales about the wanderings of Odysseus.","zh":"希臘人保存了關於奧德修斯漂泊旅程的故事。"},{"en":"The wanderings of Odysseus are the long journeys and adventures of Odysseus after the Trojan War.","zh":"奧德修斯的漂泊旅程，是他在特洛伊戰爭後的漫長旅途和冒險。"},{"en":"A story about a sailor trying to return home after many obstacles is like a tale of wanderings.","zh":"關於水手經歷許多障礙後努力回家的故事，就像漂泊旅程。"},{"en":"If a hero’s wanderings are long and difficult, the audience can follow many tests of character.","zh":"如果英雄的漂泊旅程漫長而艱難，觀眾就能跟隨許多性格考驗。"},{"en":"The phrase refers to a journey full of movement, danger and delay.","zh":"這個短語指充滿移動、危險和延誤的旅程。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":5},{"front":"be traditionally attributed to","meaning":"傳統上歸功於……","examples":[{"en":"The epic tales were traditionally attributed to Homer.","zh":"這些史詩故事傳統上歸功於荷馬。"},{"en":"To be traditionally attributed to someone means people have long believed that person created or wrote it.","zh":"“Be traditionally attributed to” 某人指人們長期相信該人創作或寫下它。"},{"en":"A folk song may be traditionally attributed to one poet even if proof is uncertain.","zh":"一首民歌可能傳統上歸功於某位詩人，即使證據不確定。"},{"en":"If a work is traditionally attributed to Homer, later generations connect it with his name.","zh":"如果作品傳統上歸功於荷馬，後代就把它與他的名字連繫起來。"},{"en":"The phrase shows historical belief about authorship, not always definite proof.","zh":"這個短語顯示關於作者身份的歷史信念，不一定是確定證據。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":6},{"front":"enchanting to hear","meaning":"聽起來令人入迷","examples":[{"en":"The stories were so enchanting to hear that they had to be preserved.","zh":"這些故事聽起來如此令人入迷，以致必須被保存。"},{"en":"Enchanting to hear means so beautiful, exciting or magical in sound that people enjoy listening.","zh":"“Enchanting to hear” 指聲音美麗、刺激或有魔力，使人喜歡聽。"},{"en":"A grandmother’s voice may be enchanting to hear when she tells old family legends.","zh":"祖母講述古老家庭傳說時，她的聲音可能聽起來令人入迷。"},{"en":"If a story is enchanting to hear, listeners may want it repeated and remembered.","zh":"如果故事聽起來令人入迷，聽眾可能希望它被重複和記住。"},{"en":"The phrase describes strong listening pleasure.","zh":"這個短語描述強烈的聆聽愉悅感。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":6},{"front":"have to be preserved","meaning":"必須被保存","examples":[{"en":"The Greeks felt that the stories had to be preserved.","zh":"希臘人覺得這些故事必須被保存。"},{"en":"To have to be preserved means to need protection so something is not lost.","zh":"“Have to be preserved” 指需要受到保護，以免某物失傳。"},{"en":"Old letters may have to be preserved because they show family history.","zh":"舊信件可能必須被保存，因為它們顯示家庭歷史。"},{"en":"If a story matters deeply to a culture, people may feel it has to be preserved.","zh":"如果故事對文化非常重要，人們可能覺得它必須被保存。"},{"en":"The phrase expresses necessity, not casual interest.","zh":"這個短語表達必要性，而不是隨意興趣。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":6},{"front":"borrow an alphabet from","meaning":"從……借用字母系統","examples":[{"en":"The Greeks borrowed an alphabet from their neighbours.","zh":"希臘人從鄰人那裡借用了字母系統。"},{"en":"To borrow an alphabet from another people means to adopt their writing symbols and adapt them for one’s own language.","zh":"“Borrow an alphabet from” 另一民族指採用其書寫符號，並改造以配合自己的語言。"},{"en":"A language may borrow letters from another alphabet when it needs a writing system.","zh":"當一種語言需要文字系統時，可能從另一套字母借用字母。"},{"en":"If a society borrows an alphabet, it can record speech without inventing every symbol from the beginning.","zh":"如果社會借用字母系統，就能記錄語音，而不用從零開始發明每個符號。"},{"en":"The phrase describes cultural and practical transfer of writing.","zh":"這個短語描述文字上的文化和實用轉移。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":6},{"front":"eastern Mediterranean","meaning":"東地中海","examples":[{"en":"The Phoenicians lived in the eastern Mediterranean.","zh":"腓尼基人居住在東地中海。"},{"en":"The eastern Mediterranean is the eastern part of the Mediterranean region, around lands and seas near the Middle East.","zh":"東地中海是地中海地區東部，位於中東附近的土地和海域一帶。"},{"en":"Ancient traders in the eastern Mediterranean connected islands, ports and coastal cities.","zh":"古代東地中海商人連接島嶼、港口和沿海城市。"},{"en":"If an alphabet spread through the eastern Mediterranean, trade and contact may have helped it travel.","zh":"如果字母系統在東地中海傳播，貿易和接觸可能幫助它流傳。"},{"en":"The phrase gives a geographical setting.","zh":"這個短語給出地理背景。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":6},{"front":"Phoenicians","meaning":"腓尼基人","examples":[{"en":"The Greeks borrowed an alphabet from the Phoenicians.","zh":"希臘人從腓尼基人那裡借用了字母系統。"},{"en":"The Phoenicians were an ancient people known for trade, seafaring and an influential alphabet.","zh":"腓尼基人是古代民族，以貿易、航海和有影響力的字母系統聞名。"},{"en":"Students may learn about the Phoenicians when studying how alphabets spread.","zh":"學生研究字母系統如何傳播時，可能會學到腓尼基人。"},{"en":"If the Greeks borrowed from the Phoenicians, writing developed through contact between cultures.","zh":"如果希臘人向腓尼基人借用，文字發展就是透過文化接觸而來。"},{"en":"The word identifies an important ancient Mediterranean people.","zh":"這個詞指出一個重要的古代地中海民族。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":6},{"front":"custom of recording stories","meaning":"記錄故事的習俗","examples":[{"en":"The custom of recording stories can be traced around the world.","zh":"記錄故事的習俗可在世界各地追溯到。"},{"en":"The custom of recording stories is the practice of writing or marking stories so they can be preserved.","zh":"記錄故事的習俗是把故事寫下或標記下來，以便保存的做法。"},{"en":"A family may develop a custom of recording stories by keeping grandparents’ memories in a notebook.","zh":"家庭可能透過把祖父母的回憶寫在筆記簿中，形成記錄故事的習俗。"},{"en":"If stories are recorded, they can travel beyond the original storyteller.","zh":"如果故事被記錄，它們就能傳到原本講故事者以外的地方。"},{"en":"The phrase describes a repeated cultural practice.","zh":"這個短語描述重複出現的文化做法。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":6},{"front":"parchment","meaning":"羊皮紙","examples":[{"en":"Stories were recorded on parchment and other materials.","zh":"故事被記錄在羊皮紙和其他材料上。"},{"en":"Parchment is a writing material made from prepared animal skin.","zh":"羊皮紙是由處理過的動物皮製成的書寫材料。"},{"en":"Before paper was common, important documents were sometimes written on parchment.","zh":"在紙張普及前，重要文件有時寫在羊皮紙上。"},{"en":"If stories are written on parchment, they may survive longer than spoken words alone.","zh":"如果故事寫在羊皮紙上，它們可能比單靠口頭傳述保存得更久。"},{"en":"The word refers to an old material for writing.","zh":"這個詞指古老的書寫材料。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":6},{"front":"be traced in","meaning":"可在……中追溯到","examples":[{"en":"The custom can be traced in many manifestations.","zh":"這種習俗可在多種表現形式中追溯到。"},{"en":"To be traced in something means to be found or followed through examples of it.","zh":"“Be traced in” 某事指可透過其例子被找到或追蹤。"},{"en":"The influence of old trade routes can be traced in city names and market streets.","zh":"古代貿易路線的影響可在城市名稱和市場街道中追溯到。"},{"en":"If a practice is traced in many places, it may have deep historical roots.","zh":"如果一種做法可在許多地方追溯到，它可能有深厚歷史根源。"},{"en":"The phrase shows where evidence of something can be found.","zh":"這個短語顯示某事的證據可在哪裡找到。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":6},{"front":"many manifestations","meaning":"多種表現形式","examples":[{"en":"Story recording appears in many manifestations around the world.","zh":"故事記錄在世界各地以多種表現形式出現。"},{"en":"Many manifestations means many different forms or examples of the same basic idea.","zh":"多種表現形式指同一基本概念的許多不同形式或例子。"},{"en":"School pride can appear in many manifestations, such as songs, badges and sports days.","zh":"學校自豪感可以有多種表現形式，例如校歌、徽章和運動日。"},{"en":"If storytelling appears in many manifestations, cultures have found different ways to preserve it.","zh":"如果講故事以多種表現形式出現，各文化就找到不同方法保存它。"},{"en":"The phrase highlights variety in outward form.","zh":"這個短語突出外在形式的多樣性。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":6},{"front":"priestly papyrus archive","meaning":"祭司紙草文獻檔案","examples":[{"en":"Ancient Egypt had a priestly papyrus archive.","zh":"古埃及有祭司紙草文獻檔案。"},{"en":"A priestly papyrus archive is a collection of written records on papyrus kept by priests.","zh":"祭司紙草文獻檔案是由祭司保存、寫在紙草上的文獻集合。"},{"en":"A temple archive may store prayers, myths, accounts and official records.","zh":"神廟檔案可能儲存祈禱文、神話、帳目和官方記錄。"},{"en":"If priests kept archives, religious institutions helped preserve stories and knowledge.","zh":"如果祭司保存檔案，宗教機構就幫助保存故事和知識。"},{"en":"The phrase describes an organised ancient collection of texts.","zh":"這個短語描述古代有組織的文本收藏。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":6},{"front":"ancient Egypt","meaning":"古埃及","examples":[{"en":"Ancient Egypt preserved stories in papyrus archives.","zh":"古埃及在紙草文獻檔案中保存故事。"},{"en":"Ancient Egypt was an early civilisation along the Nile, known for writing, temples and pyramids.","zh":"古埃及是尼羅河沿岸的早期文明，以文字、神廟和金字塔聞名。"},{"en":"Students may study ancient Egypt through mummies, hieroglyphs and myths.","zh":"學生可能透過木乃伊、象形文字和神話研究古埃及。"},{"en":"If stories were preserved in ancient Egypt, writing was already serving cultural memory.","zh":"如果故事在古埃及被保存，文字就已經服務於文化記憶。"},{"en":"The phrase gives a historical civilisation as the setting.","zh":"這個短語給出一個歷史文明作背景。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":7},{"front":"birch-bark scrolls","meaning":"樺樹皮卷軸","examples":[{"en":"The Ojibway Indians used birch-bark scrolls.","zh":"奧吉布瓦印第安人使用樺樹皮卷軸。"},{"en":"Birch-bark scrolls are rolled sheets made from birch bark and used for recording information.","zh":"樺樹皮卷軸是由樺樹皮製成、捲起來用作記錄資料的薄片。"},{"en":"A community may use natural materials like bark when paper is not available.","zh":"當紙張不可得時，社群可能使用樹皮等天然材料。"},{"en":"If stories are written on birch-bark scrolls, local materials become tools of memory.","zh":"如果故事寫在樺樹皮卷軸上，本地材料就成為記憶工具。"},{"en":"The phrase describes an organic writing surface.","zh":"這個短語描述一種有機書寫表面。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":7},{"front":"North American Ojibway Indians","meaning":"北美奧吉布瓦印第安人","examples":[{"en":"The North American Ojibway Indians recorded their creation myth.","zh":"北美奧吉布瓦印第安人記錄了他們的創世神話。"},{"en":"The North American Ojibway Indians are an Indigenous people of North America with their own traditions and stories.","zh":"北美奧吉布瓦印第安人是北美原住民族之一，有自己的傳統和故事。"},{"en":"Indigenous communities may preserve history through songs, ceremonies and written records.","zh":"原住民社群可能透過歌曲、儀式和書面記錄保存歷史。"},{"en":"If the Ojibway recorded a creation myth, they were protecting an important cultural story.","zh":"如果奧吉布瓦人記錄創世神話，他們就是在保護重要文化故事。"},{"en":"The phrase identifies a specific Indigenous group.","zh":"這個短語指出一個特定原住民族群。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":7},{"front":"set down","meaning":"寫下；記錄","examples":[{"en":"The Ojibway Indians set down their creation myth on scrolls.","zh":"奧吉布瓦印第安人把他們的創世神話寫在卷軸上。"},{"en":"To set down a story means to write it or record it in a fixed form.","zh":"“Set down” 一個故事指把它寫下或以固定形式記錄。"},{"en":"A student may set down interview notes immediately so important details are not forgotten.","zh":"學生可能立即寫下面試筆記，以免忘記重要細節。"},{"en":"If a story is set down, it can be passed on beyond the memory of one person.","zh":"如果故事被記錄下來，它就能超越一個人的記憶而傳承。"},{"en":"The phrase is a formal way to say “write down.”","zh":"這個短語是 “write down” 的較正式說法。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":7},{"front":"creation myth","meaning":"創世神話","examples":[{"en":"The Ojibway Indians recorded their creation myth.","zh":"奧吉布瓦印第安人記錄了他們的創世神話。"},{"en":"A creation myth is a traditional story explaining how the world, people or a community began.","zh":"創世神話是解釋世界、人類或社群如何開始的傳統故事。"},{"en":"Many cultures have creation myths that connect nature, gods and human origins.","zh":"許多文化都有把自然、神明和人類起源連繫起來的創世神話。"},{"en":"If a creation myth is recorded, a community preserves one of its deepest explanations of existence.","zh":"如果創世神話被記錄，社群就保存了其對存在最深層的解釋之一。"},{"en":"The phrase refers to a sacred or cultural origin story.","zh":"這個短語指神聖或文化上的起源故事。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":7},{"front":"well-tried and universal practice","meaning":"久經考驗而普遍的做法","examples":[{"en":"Recording stories is a well-tried and universal practice.","zh":"記錄故事是一種久經考驗而普遍的做法。"},{"en":"A well-tried and universal practice is a method used successfully for a long time in many places.","zh":"久經考驗而普遍的做法，是在許多地方長期成功使用的方法。"},{"en":"Taking notes is a well-tried practice for students because it helps memory and revision.","zh":"記筆記對學生來說是久經考驗的做法，因為它幫助記憶和溫習。"},{"en":"If many cultures record stories, the practice is not unusual but widely tested.","zh":"如果許多文化都記錄故事，這種做法就不是罕見，而是經廣泛驗證。"},{"en":"The phrase stresses both long experience and broad use.","zh":"這個短語同時強調長期經驗和廣泛使用。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":7},{"front":"to this day","meaning":"直到今日","examples":[{"en":"To this day, storytime is often associated with words on paper.","zh":"直到今日，故事時間仍常與紙上的文字聯繫起來。"},{"en":"To this day means even now, after a long period of time.","zh":"“To this day” 指即使到了現在，經過很長時間後仍然如此。"},{"en":"To this day, some families still keep handwritten recipe books.","zh":"直到今日，一些家庭仍保存手寫食譜書。"},{"en":"If a custom continues to this day, it has survived many changes.","zh":"如果習俗延續至今，它就經歷了許多變化仍然存在。"},{"en":"The phrase links the past with the present.","zh":"這個短語把過去與現在連繫起來。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":7},{"front":"be associated with","meaning":"與……聯繫起來","examples":[{"en":"Storytime is often associated with words on paper.","zh":"故事時間常與紙上的文字聯繫起來。"},{"en":"To be associated with something means to be connected with it in people’s minds.","zh":"“Be associated with” 某事指在人們心中與它有連繫。"},{"en":"Exams are often associated with stress, revision and late nights.","zh":"考試常與壓力、溫習和熬夜聯繫起來。"},{"en":"If storytime is associated with books, people may forget that films also tell stories.","zh":"如果故事時間與書本聯繫起來，人們可能忘記電影也在講故事。"},{"en":"The phrase describes a mental or cultural connection.","zh":"這個短語描述心理或文化上的連繫。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":7},{"front":"words on paper","meaning":"紙上的文字","examples":[{"en":"Many people associate storytime with words on paper.","zh":"許多人把故事時間與紙上的文字聯繫起來。"},{"en":"Words on paper means written language printed or written on physical pages.","zh":"紙上的文字指印刷或寫在實體頁面上的書面語言。"},{"en":"A child may first meet stories through words on paper in picture books.","zh":"孩子可能最初透過圖畫書中紙上的文字接觸故事。"},{"en":"If people think only of words on paper, they may overlook oral and visual storytelling.","zh":"如果人們只想到紙上的文字，可能忽視口述和視覺敘事。"},{"en":"The phrase contrasts written stories with spoken or filmed stories.","zh":"這個短語把書面故事與口述或電影故事作對比。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":7},{"front":"formal practice of","meaning":"……的正式做法","examples":[{"en":"The formal practice of narrating aloud may seem old-fashioned.","zh":"大聲講述故事的正式做法可能看似過時。"},{"en":"The formal practice of something means an organised or traditional way of doing it.","zh":"某事的正式做法指有組織或傳統的做法。"},{"en":"The formal practice of debating teaches students to speak in a structured way.","zh":"辯論的正式做法教學生以有結構方式說話。"},{"en":"If a formal practice seems old-fashioned, people may still use it in ceremonies or classrooms.","zh":"如果正式做法看似過時，人們仍可能在儀式或課堂中使用它。"},{"en":"The phrase describes a recognised method, not casual behaviour.","zh":"這個短語描述受承認的方法，而不是隨意行為。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":7},{"front":"narrating a story aloud","meaning":"大聲講述故事","examples":[{"en":"Narrating a story aloud seems to have given way to print.","zh":"大聲講述故事似乎已被印刷品取代。"},{"en":"Narrating a story aloud means telling a story by speaking it so others can hear.","zh":"“Narrating a story aloud” 指透過說話講故事，讓他人聽見。"},{"en":"A parent narrates a story aloud when reading bedtime stories to a child.","zh":"父母睡前讀故事給孩子聽時，就是在大聲講述故事。"},{"en":"If stories are narrated aloud, voice, rhythm and expression become important.","zh":"如果故事被大聲講述，聲音、節奏和表情就變得重要。"},{"en":"The phrase describes spoken storytelling.","zh":"這個短語描述口頭講故事。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":7},{"front":"give way to","meaning":"被……取代","examples":[{"en":"Oral storytelling seems to have given way to newspapers and novels.","zh":"口頭講故事似乎已被報紙和小說取代。"},{"en":"To give way to something means to be replaced by it or become less important than it.","zh":"“Give way to” 某物指被它取代，或變得不如它重要。"},{"en":"Handwritten letters have largely given way to email and text messages.","zh":"手寫信件大多已被電郵和短訊取代。"},{"en":"If one storytelling method gives way to another, people’s habits of receiving stories change.","zh":"如果一種講故事方法被另一種取代，人們接收故事的習慣就會改變。"},{"en":"The phrase describes replacement or decline in importance.","zh":"這個短語描述取代或重要性下降。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":8},{"front":"comic strips","meaning":"漫畫連環圖","examples":[{"en":"Comic strips are one written form of storytelling.","zh":"漫畫連環圖是一種書面敘事形式。"},{"en":"Comic strips are short sequences of drawings and words that tell a story.","zh":"漫畫連環圖是由圖畫和文字組成、用來講故事的短篇連續畫格。"},{"en":"A newspaper may include comic strips that make readers laugh in a few panels.","zh":"報紙可能刊登幾格就令讀者發笑的漫畫連環圖。"},{"en":"If pictures and dialogue work together, comic strips can tell stories quickly.","zh":"如果圖畫和對白互相配合，漫畫連環圖可以快速講故事。"},{"en":"The phrase refers to visual storytelling on a page.","zh":"這個短語指紙面上的視覺敘事。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":8},{"front":"this is not the case","meaning":"情況並非如此","examples":[{"en":"The writer says this is not the case.","zh":"作者說情況並非如此。"},{"en":"This is not the case means the previous idea is not true.","zh":"“This is not the case” 指前面那個想法並不正確。"},{"en":"Some people think teenagers never read, but this is not the case in schools with strong libraries.","zh":"有些人以為青少年從不閱讀，但在圖書館強大的學校中，情況並非如此。"},{"en":"If evidence shows a belief is wrong, a writer may say this is not the case.","zh":"如果證據顯示某信念錯誤，作者可能說情況並非如此。"},{"en":"The phrase corrects a mistaken assumption.","zh":"這個短語用來糾正錯誤假設。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":8},{"front":"statistically","meaning":"從統計上看","examples":[{"en":"Statistically, most humans may not rely on written stories.","zh":"從統計上看，大多數人可能不依賴書面故事。"},{"en":"Statistically means according to numbers, data or measured patterns.","zh":"“Statistically” 指根據數字、數據或量度到的模式。"},{"en":"Statistically, students who sleep enough often concentrate better in class.","zh":"從統計上看，睡眠充足的學生通常在課堂上更能集中。"},{"en":"If a claim is made statistically, it should be based on figures rather than one personal example.","zh":"如果某說法是從統計上看，就應基於數字，而不是一個個人例子。"},{"en":"The word signals a data-based point.","zh":"這個詞表示基於數據的觀點。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":8},{"front":"rely upon","meaning":"依賴","examples":[{"en":"Most people may not rely upon the written word for stories.","zh":"大多數人可能不依賴書面文字來接觸故事。"},{"en":"To rely upon something means to depend on it for help, information or support.","zh":"“Rely upon” 某事指依靠它獲得幫助、資訊或支持。"},{"en":"Students may rely upon a dictionary when learning difficult vocabulary.","zh":"學生學習困難詞彙時，可能依賴字典。"},{"en":"If people do not rely upon books for stories, they may receive stories from film, speech or song.","zh":"如果人們不依賴書本接觸故事，他們可能從電影、說話或歌曲中接收故事。"},{"en":"The phrase is a formal version of “rely on.”","zh":"這個短語是 “rely on” 的正式版本。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":8},{"front":"written word","meaning":"書面文字","examples":[{"en":"The written word is not the only source of stories.","zh":"書面文字不是故事的唯一來源。"},{"en":"The written word means language that is written or printed rather than spoken.","zh":"書面文字指寫出或印出的語言，而不是口語。"},{"en":"Laws, novels and newspapers all depend heavily on the written word.","zh":"法律、小說和報紙都很依賴書面文字。"},{"en":"If people focus only on the written word, they may miss oral storytelling and cinema.","zh":"如果人們只集中於書面文字，可能錯過口述故事和電影。"},{"en":"The phrase contrasts writing with speech, images and performance.","zh":"這個短語把文字與說話、影像和表演作對比。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":8},{"front":"get access to","meaning":"接觸到；取得","examples":[{"en":"People get access to stories in many ways.","zh":"人們以許多方式接觸到故事。"},{"en":"To get access to something means to be able to reach, use or experience it.","zh":"“Get access to” 某事指能夠接觸、使用或經歷它。"},{"en":"Students get access to online lessons when they have a device and internet connection.","zh":"當學生有裝置和網絡連接時，就能接觸到網上課堂。"},{"en":"If people get access to stories through films, they do not need to read printed books to enjoy narratives.","zh":"如果人們透過電影接觸故事，就不需要閱讀印刷書本也能享受敘事。"},{"en":"The phrase focuses on the way people can reach something.","zh":"這個短語強調人們如何接觸某物。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":8},{"front":"alternative source","meaning":"替代來源","examples":[{"en":"The writer asks what the alternative source of stories is.","zh":"作者問故事的替代來源是甚麼。"},{"en":"An alternative source is another place, method or origin from which something can come.","zh":"替代來源是某物可以來自的另一個地方、方法或起源。"},{"en":"If the school library is closed, students may use online databases as an alternative source of information.","zh":"如果學校圖書館關閉，學生可以使用網上資料庫作為替代資料來源。"},{"en":"If books are not the main source of stories, cinema may be an alternative source.","zh":"如果書本不是故事的主要來源，電影可能是替代來源。"},{"en":"The phrase suggests another option besides the usual one.","zh":"這個短語暗示除了常見選項以外的另一選擇。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":8},{"front":"latest offering","meaning":"最新作品","examples":[{"en":"Each year, billions watch the latest offering from film industries.","zh":"每年，數十億人觀看電影業的最新作品。"},{"en":"The latest offering is the newest product, film or work released by a company or creator.","zh":"最新作品是公司或創作者推出的最新產品、電影或作品。"},{"en":"Fans may queue to watch a studio’s latest offering on the first weekend.","zh":"影迷可能在首個週末排隊觀看片廠的最新作品。"},{"en":"If the latest offering is exciting, it can attract both loyal fans and new audiences.","zh":"如果最新作品令人興奮，它可以吸引忠實粉絲和新觀眾。"},{"en":"The phrase often refers to a newly released creative product.","zh":"這個短語常指新推出的創意作品。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":8},{"front":"Hollywood, Bollywood and beyond","meaning":"荷里活、寶萊塢及其他地方","examples":[{"en":"Many people watch films from Hollywood, Bollywood and beyond.","zh":"許多人觀看來自荷里活、寶萊塢及其他地方的電影。"},{"en":"Hollywood, Bollywood and beyond means major film industries in the United States, India and many other places.","zh":"“Hollywood, Bollywood and beyond” 指美國、印度以及許多其他地方的主要電影業。"},{"en":"A film festival may show movies from Hollywood, Bollywood and beyond to attract diverse audiences.","zh":"電影節可能放映來自荷里活、寶萊塢及其他地方的電影，以吸引多元觀眾。"},{"en":"If stories come from many film centres, cinema becomes a global storytelling medium.","zh":"如果故事來自許多電影中心，電影就成為全球講故事媒介。"},{"en":"The phrase expands the examples beyond two famous film industries.","zh":"這個短語把例子擴展到兩個著名電影業以外。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":8},{"front":"supreme storyteller","meaning":"今日最重要的講故事媒介","examples":[{"en":"The supreme storyteller of today is cinema.","zh":"今日最重要的講故事媒介是電影。"},{"en":"A supreme storyteller is the most powerful or dominant medium for telling stories.","zh":"今日最重要的講故事媒介，是最有力或最主導的敘事媒介。"},{"en":"In a classroom, a teacher with vivid examples can become the supreme storyteller for a difficult topic.","zh":"在課室中，如果老師例子生動，就可以成為某個困難題目的最重要講故事者。"},{"en":"If cinema reaches billions, it may become the supreme storyteller of modern life.","zh":"如果電影接觸到數十億人，它可能成為現代生活中最重要的講故事媒介。"},{"en":"The phrase praises the strongest storyteller in a particular period.","zh":"這個短語稱讚某一時期最強大的敘事者。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":8},{"front":"as distinct from","meaning":"與……不同","examples":[{"en":"The movies, as distinct from still photography, are a modern phenomenon.","zh":"電影與靜態攝影不同，是一種現代現象。"},{"en":"As distinct from means different from or separate from something else.","zh":"“As distinct from” 指與某事不同或分開。"},{"en":"Speaking, as distinct from writing, depends heavily on voice and timing.","zh":"說話與寫作不同，很依賴聲音和時機。"},{"en":"If movies are discussed as distinct from photography, movement becomes the key difference.","zh":"如果把電影與攝影區分開來討論，動態就成為關鍵差異。"},{"en":"The phrase clearly separates two related things.","zh":"這個短語清楚分開兩個相關事物。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":9},{"front":"still photography","meaning":"靜態攝影","examples":[{"en":"Movies are different from still photography.","zh":"電影與靜態攝影不同。"},{"en":"Still photography is the art or process of taking unmoving images.","zh":"靜態攝影是拍攝不動影像的藝術或過程。"},{"en":"A wedding photographer uses still photography to capture moments in single pictures.","zh":"婚禮攝影師使用靜態攝影，以單張照片捕捉時刻。"},{"en":"If still photography freezes one moment, film creates storytelling through movement and sequence.","zh":"如果靜態攝影定格一刻，電影則透過動態和次序創造敘事。"},{"en":"The phrase contrasts single images with moving images.","zh":"這個短語把單一影像與動態影像作對比。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":9},{"front":"modern phenomenon","meaning":"現代現象","examples":[{"en":"The movies seem to be an essentially modern phenomenon.","zh":"電影似乎本質上是一種現代現象。"},{"en":"A modern phenomenon is something that belongs mainly to recent times.","zh":"現代現象是主要屬於近代的事物。"},{"en":"Social media is a modern phenomenon that has changed how students communicate.","zh":"社交媒體是一種現代現象，改變了學生溝通方式。"},{"en":"If cinema seems modern, people may forget its roots in older visual storytelling.","zh":"如果電影看似現代，人們可能忘記它源自更古老的視覺敘事。"},{"en":"The phrase describes something associated with contemporary life.","zh":"這個短語描述與當代生活相關的事物。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":9},{"front":"this is an illusion","meaning":"這是一種錯覺","examples":[{"en":"The idea that film is purely modern is an illusion.","zh":"電影純粹現代這個想法是一種錯覺。"},{"en":"This is an illusion means the idea seems true but is actually misleading or false.","zh":"“This is an illusion” 指某想法看似正確，但實際上具誤導性或錯誤。"},{"en":"A quiet classroom may seem easy to teach, but this can be an illusion if students are confused.","zh":"安靜課室可能看似容易教，但如果學生其實很困惑，這可能是一種錯覺。"},{"en":"If film looks completely new but uses ancient storytelling patterns, its pure modernity is an illusion.","zh":"如果電影看似全新，但使用古老敘事模式，其純粹現代性就是錯覺。"},{"en":"The phrase challenges an appearance that hides a deeper truth.","zh":"這個短語挑戰掩蓋更深真相的表象。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":9},{"front":"be indebted to","meaning":"受惠於；承襲自","examples":[{"en":"The medium of film is indebted to old precedents.","zh":"電影這種媒介承襲自古老先例。"},{"en":"To be indebted to something means to owe part of one’s development or success to it.","zh":"“Be indebted to” 某事指部分發展或成功有賴於它。"},{"en":"Modern pop music is often indebted to older folk, jazz or classical traditions.","zh":"現代流行音樂常受惠於較古老的民歌、爵士或古典傳統。"},{"en":"If film is indebted to earlier image sequences, it did not appear from nowhere.","zh":"如果電影承襲自早期連續影像，它就不是憑空出現。"},{"en":"The phrase shows historical influence and inheritance.","zh":"這個短語顯示歷史影響和承傳。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":9},{"front":"old precedents","meaning":"古老先例","examples":[{"en":"Film uses old precedents of arranging sequences of images.","zh":"電影使用排列連續影像的古老先例。"},{"en":"Old precedents are earlier examples or practices that later people can follow or develop.","zh":"古老先例是後來的人可以跟隨或發展的較早例子或做法。"},{"en":"Online lessons have old precedents in radio education and television courses.","zh":"網上課堂在廣播教育和電視課程中有古老先例。"},{"en":"If a new art form has old precedents, its roots are older than it first appears.","zh":"如果新藝術形式有古老先例，其根源就比表面看起來更古老。"},{"en":"The phrase points to earlier models behind a later practice.","zh":"這個短語指後來做法背後的早期模式。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":9},{"front":"sequences of images","meaning":"連續影像","examples":[{"en":"Film builds on the arrangement of sequences of images.","zh":"電影建基於連續影像的排列。"},{"en":"Sequences of images are groups of pictures shown in order to create movement or meaning.","zh":"連續影像是一組按次序展示、用來創造動態或意義的圖像。"},{"en":"A comic strip uses a sequence of images to show what happens from one panel to the next.","zh":"漫畫連環圖使用連續影像，顯示一格到下一格發生甚麼。"},{"en":"If images are arranged in sequence, viewers can follow action and change over time.","zh":"如果影像按次序排列，觀眾就能跟隨行動和隨時間出現的變化。"},{"en":"The phrase is central to visual storytelling.","zh":"這個短語是視覺敘事的核心。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":9},{"front":"account of","meaning":"對……的描述","examples":[{"en":"Any account of visual storytelling must begin with a basic recognition.","zh":"任何對視覺敘事的描述都必須由一個基本認識開始。"},{"en":"An account of something is an explanation, description or discussion of it.","zh":"“An account of” 某事是對它的解釋、描述或討論。"},{"en":"A history book may give an account of how cities grew around rivers.","zh":"歷史書可能描述城市如何在河流附近發展。"},{"en":"If an account of storytelling ignores ancient examples, it may feel incomplete.","zh":"如果對講故事的描述忽略古代例子，就可能顯得不完整。"},{"en":"The phrase introduces a way of explaining a topic.","zh":"這個短語引出解釋某題目的方式。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":9},{"front":"visual storytelling","meaning":"視覺敘事","examples":[{"en":"Visual storytelling has ancient roots.","zh":"視覺敘事有古老根源。"},{"en":"Visual storytelling means telling stories through images, movement, symbols or scenes.","zh":"視覺敘事指透過影像、動作、符號或場景講故事。"},{"en":"A picture book uses visual storytelling when children can follow the plot from illustrations.","zh":"當孩子能從插圖跟隨情節時，圖畫書就是在使用視覺敘事。"},{"en":"If a film shows fear through shadows rather than dialogue, it is using visual storytelling.","zh":"如果電影透過陰影而不是對白展示恐懼，就是在使用視覺敘事。"},{"en":"The phrase focuses on stories told by seeing, not only by reading or listening.","zh":"這個短語強調透過觀看講故事，而不只是閱讀或聆聽。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":9},{"front":"begin with the recognition that","meaning":"要由認識到……開始","examples":[{"en":"Any account must begin with the recognition that storytelling is ancient.","zh":"任何描述都要由認識到講故事很古老開始。"},{"en":"To begin with the recognition that something is true means to start by accepting that important fact.","zh":"“Begin with the recognition that” 某事為真，指先接受該重要事實作為起點。"},{"en":"A discussion of learning should begin with the recognition that students have different needs.","zh":"討論學習時，應由認識到學生有不同需要開始。"},{"en":"If we begin with the recognition that stories are ancient, cinema looks less like a sudden invention.","zh":"如果我們由認識到故事很古老開始，電影就較不像突然出現的發明。"},{"en":"The phrase introduces the first idea needed for understanding.","zh":"這個短語引出理解某事所需的第一個想法。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":9},{"front":"beat with","meaning":"隨着……跳動","examples":[{"en":"All storytelling beats with an atavistic pulse.","zh":"所有講故事都隨着返祖式脈搏跳動。"},{"en":"To beat with something means to have a rhythm, energy or feeling driven by it.","zh":"“Beat with” 某物指帶有由它推動的節奏、能量或感覺。"},{"en":"A school festival may beat with the excitement of drums, dance and cheering students.","zh":"學校節日可能隨着鼓聲、舞蹈和學生歡呼的興奮感跳動。"},{"en":"If storytelling beats with ancient human needs, it connects modern audiences with older instincts.","zh":"如果講故事隨着古老人類需要跳動，它就把現代觀眾與更古老本能連繫起來。"},{"en":"The phrase is metaphorical and suggests inner rhythm or life.","zh":"這個短語是比喻用法，暗示內在節奏或生命力。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":9},{"front":"deeply atavistic pulse","meaning":"深層返祖式脈搏","examples":[{"en":"Storytelling beats with a deeply atavistic pulse.","zh":"講故事隨着深層返祖式脈搏跳動。"},{"en":"A deeply atavistic pulse means a powerful feeling that comes from very ancient human instincts.","zh":"深層返祖式脈搏指來自非常古老人類本能的強烈感覺。"},{"en":"Fear of darkness may feel atavistic because it is linked to old survival needs.","zh":"對黑暗的恐懼可能帶有返祖性，因為它與古老生存需要相關。"},{"en":"If storytelling has an atavistic pulse, people respond to stories because of something deeply human.","zh":"如果講故事有返祖式脈搏，人們回應故事就是因為某種深層人性。"},{"en":"The phrase suggests that storytelling reaches far back into human nature.","zh":"這個短語暗示講故事深入到人類本性的遠古層面。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":10},{"front":"rely upon","meaning":"依靠；依賴","examples":[{"en":"A good story relies upon formal patterns.","zh":"好故事依靠正式模式。"},{"en":"To rely upon something means to depend on it in order to work well.","zh":"“Rely upon” 某事指依賴它才能良好運作。"},{"en":"A clear essay relies upon structure, examples and logical links.","zh":"清晰文章依靠結構、例子和邏輯連接。"},{"en":"If a story relies upon plot and character, it needs more than beautiful language.","zh":"如果故事依靠情節和人物，它需要的不只是美麗語言。"},{"en":"The phrase is a formal way to say “depend on.”","zh":"這個短語是 “depend on” 的正式說法。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":10},{"front":"formal patterns of","meaning":"……的正式模式","examples":[{"en":"A good story relies upon formal patterns of plot and characterisation.","zh":"好故事依靠情節和人物塑造的正式模式。"},{"en":"Formal patterns of something are recognised structures or repeated ways in which it is organised.","zh":"某事的正式模式是被認可的結構或反覆出現的組織方式。"},{"en":"A debate has formal patterns of opening statements, arguments and replies.","zh":"辯論有開場陳述、論點和回應等正式模式。"},{"en":"If stories use formal patterns, audiences can follow conflict, change and resolution more easily.","zh":"如果故事使用正式模式，觀眾就更容易跟隨衝突、變化和解決。"},{"en":"The phrase describes organised structures behind creative work.","zh":"這個短語描述創作作品背後的有組織結構。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":10},{"front":"plot and characterisation","meaning":"情節和人物塑造","examples":[{"en":"Good stories depend on plot and characterisation.","zh":"好故事依賴情節和人物塑造。"},{"en":"Plot and characterisation mean what happens in a story and how the people in it are created.","zh":"情節和人物塑造指故事中發生甚麼，以及故事中的人物如何被塑造。"},{"en":"A mystery needs a strong plot, while a family drama needs rich characterisation.","zh":"懸疑故事需要強情節，而家庭劇需要豐富人物塑造。"},{"en":"If plot is weak, events feel random; if characterisation is weak, people feel flat.","zh":"如果情節薄弱，事件會感覺隨機；如果人物塑造薄弱，人物會顯得平面。"},{"en":"The phrase names two central building blocks of storytelling.","zh":"這個短語指出講故事的兩個核心組件。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":10},{"front":"be embedded in","meaning":"深植於……","examples":[{"en":"These patterns are embedded in the practice of storytelling.","zh":"這些模式深植於講故事的實踐中。"},{"en":"To be embedded in something means to be deeply built into it.","zh":"“Be embedded in” 某事指深深內建於其中。"},{"en":"Respect for elders may be embedded in a family’s daily habits and language.","zh":"尊重長者可能深植於家庭日常習慣和語言中。"},{"en":"If patterns are embedded in storytelling, writers use them even when they seem modern.","zh":"如果模式深植於講故事中，作家即使看似現代也會使用它們。"},{"en":"The phrase describes something deeply fixed inside a system or practice.","zh":"這個短語描述某事深深固定在系統或做法之內。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":10},{"front":"over many generations","meaning":"經過許多世代","examples":[{"en":"Storytelling patterns developed over many generations.","zh":"講故事模式經過許多世代發展。"},{"en":"Over many generations means across a long period involving parents, children and descendants.","zh":"“Over many generations” 指跨越包括父母、子女和後代的很長時期。"},{"en":"A family recipe may change over many generations as each cook adds something small.","zh":"家庭食譜可能經過許多世代改變，因為每位廚師都加入一點東西。"},{"en":"If a tradition develops over many generations, it becomes deeply connected to culture.","zh":"如果傳統經過許多世代發展，它就變得與文化深深相連。"},{"en":"The phrase emphasises long historical development.","zh":"這個短語強調漫長歷史發展。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":10},{"front":"aspiring screenwriters","meaning":"有志成為編劇的人","examples":[{"en":"Aspiring screenwriters can learn from Aristotle.","zh":"有志成為編劇的人可以向亞里士多德學習。"},{"en":"Aspiring screenwriters are people who hope or plan to write scripts for films or television.","zh":"有志成為編劇的人，是希望或計劃為電影或電視寫劇本的人。"},{"en":"An aspiring screenwriter may practise by turning a short story into a film scene.","zh":"有志成為編劇的人可能透過把短篇故事改寫成電影場景來練習。"},{"en":"If aspiring screenwriters study old storytelling principles, they can improve modern scripts.","zh":"如果有志成為編劇的人研究古老敘事原則，就能改善現代劇本。"},{"en":"The phrase refers to people who want to become screenwriters.","zh":"這個短語指想成為編劇的人。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":10},{"front":"look no further than","meaning":"只需參考……","examples":[{"en":"Screenwriters need look no further than Aristotle for advice.","zh":"編劇只需參考亞里士多德就能得到建議。"},{"en":"Look no further than means the best or clearest source is the one being named.","zh":"“Look no further than” 指最合適或最清楚的來源就是被提到的那個。"},{"en":"If students want a simple example of courage, they need look no further than a classmate who admits a mistake.","zh":"如果學生想找勇氣的簡單例子，只需看看一位承認錯誤的同學。"},{"en":"If writers need storytelling principles, Aristotle may already offer enough guidance.","zh":"如果作家需要敘事原則，亞里士多德可能已提供足夠指引。"},{"en":"The phrase points confidently to a suitable source or example.","zh":"這個短語自信地指出合適來源或例子。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":10},{"front":"essential advice","meaning":"重要建議","examples":[{"en":"Aristotle offers essential advice on storytelling.","zh":"亞里士多德提供關於講故事的重要建議。"},{"en":"Essential advice is guidance that is very important and necessary to understand or succeed.","zh":"重要建議是對理解或成功非常重要且必要的指引。"},{"en":"Before an exam, a teacher’s essential advice may be to read the question carefully.","zh":"考試前，老師的重要建議可能是仔細閱讀題目。"},{"en":"If advice is essential, ignoring it may lead to avoidable mistakes.","zh":"如果建議很重要，忽視它可能導致可避免的錯誤。"},{"en":"The phrase refers to core guidance, not minor tips.","zh":"這個短語指核心指引，而不是小提示。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":10},{"front":"philosopher","meaning":"哲學家","examples":[{"en":"Aristotle was a Greek philosopher.","zh":"亞里士多德是一位希臘哲學家。"},{"en":"A philosopher is a thinker who studies questions about knowledge, truth, ethics and human life.","zh":"哲學家是研究知識、真理、倫理和人生問題的思想家。"},{"en":"A philosopher may ask what makes a good life or a fair society.","zh":"哲學家可能問甚麼構成良好人生或公平社會。"},{"en":"If a philosopher writes about storytelling, he may analyse stories through reason and structure.","zh":"如果哲學家寫關於講故事的內容，他可能透過理性和結構分析故事。"},{"en":"The word refers to a person who studies deep ideas carefully.","zh":"這個詞指仔細研究深層思想的人。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":10},{"front":"lecture notes","meaning":"講課筆記","examples":[{"en":"Aristotle left incomplete lecture notes on storytelling.","zh":"亞里士多德留下了關於講故事的不完整講課筆記。"},{"en":"Lecture notes are written points used for teaching, study or remembering a lecture.","zh":"講課筆記是用於教學、學習或記住講座內容的書面要點。"},{"en":"Students often take lecture notes so they can review key ideas later.","zh":"學生常做講課筆記，以便日後溫習重點。"},{"en":"If lecture notes are incomplete, readers may need to infer the missing explanations.","zh":"如果講課筆記不完整，讀者可能需要推斷缺失的解釋。"},{"en":"The phrase refers to teaching notes rather than a polished book.","zh":"這個短語指教學筆記，而不是打磨完成的書。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":10},{"front":"various literary and dramatic modes","meaning":"各種文學和戲劇形式","examples":[{"en":"Aristotle discussed storytelling in various literary and dramatic modes.","zh":"亞里士多德討論各種文學和戲劇形式中的講故事。"},{"en":"Various literary and dramatic modes are different forms of writing and performance, such as poetry, tragedy and comedy.","zh":"各種文學和戲劇形式，是不同的寫作和表演形式，例如詩歌、悲劇和喜劇。"},{"en":"A literature course may compare various modes to show how stories change across forms.","zh":"文學課可能比較各種形式，以顯示故事如何在不同形式中改變。"},{"en":"If a thinker studies many modes, his ideas may apply beyond one type of story.","zh":"如果思想家研究許多形式，其想法可能不只適用於一種故事。"},{"en":"The phrase describes a range of artistic forms.","zh":"這個短語描述一系列藝術形式。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":11},{"front":"slim volume","meaning":"薄薄一冊","examples":[{"en":"The Poetics is a slim volume of lecture notes.","zh":"《詩學》是薄薄一冊講課筆記。"},{"en":"A slim volume is a short or thin book.","zh":"薄薄一冊指短小或很薄的書。"},{"en":"A slim volume can still be influential if its ideas are powerful.","zh":"如果思想有力，薄薄一冊書仍可以很有影響力。"},{"en":"If a book is slim, students may expect it to be short, but not necessarily easy.","zh":"如果一本書很薄，學生可能以為它短，但不一定容易。"},{"en":"The phrase describes physical length, not intellectual importance.","zh":"這個短語描述實體篇幅，而不是思想重要性。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":11},{"front":"the Poetics","meaning":"《詩學》","examples":[{"en":"Aristotle’s book on storytelling is known as the Poetics.","zh":"亞里士多德關於講故事的書被稱為《詩學》。"},{"en":"The Poetics is Aristotle’s work discussing poetry, drama and principles of storytelling.","zh":"《詩學》是亞里士多德討論詩歌、戲劇和敘事原則的作品。"},{"en":"Film students may still read the Poetics to understand plot, character and tragedy.","zh":"電影學生今天仍可能閱讀《詩學》，以理解情節、人物和悲劇。"},{"en":"If an ancient text is still studied today, its ideas have long-lasting value.","zh":"如果古代文本今天仍被研究，其思想就有持久價值。"},{"en":"The phrase names a classic work on literary theory.","zh":"這個短語指一部文學理論經典作品。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":11},{"front":"envisage","meaning":"想像到","examples":[{"en":"Aristotle could not have envisaged modern multiplex cinemas.","zh":"亞里士多德不可能想像到現代多廳戲院。"},{"en":"To envisage something means to imagine or picture it in the future.","zh":"“Envisage” 某事指想像或構想未來的它。"},{"en":"A school planner may envisage classrooms where students use both books and digital tools.","zh":"學校規劃者可能想像到學生同時使用書本和數碼工具的課室。"},{"en":"If ancient thinkers could not envisage cinema, modern film still developed beyond their world.","zh":"如果古代思想家無法想像電影，現代電影仍是在其世界之外發展出來。"},{"en":"The word means mentally imagine something that is not present yet.","zh":"這個詞指在腦中想像尚未出現的事物。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":11},{"front":"popcorn-fuelled actuality","meaning":"由爆谷陪伴的現實情景","examples":[{"en":"Aristotle could not have imagined the popcorn-fuelled actuality of modern cinema.","zh":"亞里士多德不可能想像到現代戲院由爆谷陪伴的現實情景。"},{"en":"Popcorn-fuelled actuality means the real modern cinema experience, humorously described through popcorn-eating audiences.","zh":"“Popcorn-fuelled actuality” 指現代戲院的真實體驗，以觀眾吃爆谷的方式幽默描述。"},{"en":"A football match may have a snack-filled actuality that old rule-makers never imagined.","zh":"足球比賽也可能有充滿小食的現實情景，是古代規則制定者想不到的。"},{"en":"If modern cinema is popcorn-fuelled, it is not only art but also a social entertainment experience.","zh":"如果現代戲院由爆谷陪伴，它就不只是藝術，也是社交娛樂體驗。"},{"en":"The phrase playfully describes how cinema is actually experienced today.","zh":"這個短語以玩味方式描述今日人們實際如何體驗電影。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":11},{"front":"multiplex cinema","meaning":"多廳戲院","examples":[{"en":"A multiplex cinema attracts large modern audiences.","zh":"多廳戲院吸引大量現代觀眾。"},{"en":"A multiplex cinema is a cinema with several screens showing different films at the same time.","zh":"多廳戲院是有幾個銀幕、同時放映不同電影的戲院。"},{"en":"Families may choose a multiplex cinema because different age groups can watch different films.","zh":"家庭可能選擇多廳戲院，因為不同年齡組可以看不同電影。"},{"en":"If a cinema has many screens, it can attract more viewers and offer more choices.","zh":"如果戲院有多個銀幕，就能吸引更多觀眾並提供更多選擇。"},{"en":"The phrase describes a modern multi-screen film venue.","zh":"這個短語描述現代多銀幕電影場所。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":11},{"front":"prescient about","meaning":"對……有先見之明","examples":[{"en":"Aristotle was almost prescient about the key elements of popular stories.","zh":"亞里士多德幾乎對流行故事的關鍵元素有先見之明。"},{"en":"To be prescient about something means to understand or predict it before it becomes obvious.","zh":"“Be prescient about” 某事指在它變得明顯之前已理解或預見它。"},{"en":"A teacher may be prescient about technology if she prepares students for digital skills early.","zh":"如果老師早早幫學生準備數碼技能，她可能對科技有先見之明。"},{"en":"If Aristotle’s ideas still explain cinema, he seems strangely prescient about modern storytelling.","zh":"如果亞里士多德的想法今天仍能解釋電影，他就似乎對現代敘事有奇特先見之明。"},{"en":"The phrase describes insight that appears ahead of its time.","zh":"這個短語描述超越時代的洞察力。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":11},{"front":"key elements","meaning":"關鍵元素","examples":[{"en":"Aristotle understood the key elements required to attract crowds.","zh":"亞里士多德理解吸引群眾所需的關鍵元素。"},{"en":"Key elements are the most important parts needed for something to work.","zh":"關鍵元素是某事成功運作所需的最重要部分。"},{"en":"Clear goals, practice and feedback are key elements of effective learning.","zh":"清晰目標、練習和回饋是有效學習的關鍵元素。"},{"en":"If a story lacks key elements such as conflict and character, audiences may lose interest.","zh":"如果故事缺少衝突和人物等關鍵元素，觀眾可能失去興趣。"},{"en":"The phrase identifies the core parts, not minor details.","zh":"這個短語指出核心部分，而不是小細節。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":11},{"front":"get the crowds flocking to","meaning":"令群眾蜂擁到……","examples":[{"en":"Good stories get the crowds flocking to cinemas.","zh":"好故事令群眾蜂擁到戲院。"},{"en":"To get the crowds flocking to a place means to attract many people there quickly and eagerly.","zh":"“Get the crowds flocking to” 某地指吸引許多人迅速而熱切地前往。"},{"en":"A famous singer can get the crowds flocking to a shopping mall performance.","zh":"著名歌手可以令群眾蜂擁到商場表演。"},{"en":"If a film creates strong excitement, it can get audiences rushing to cinemas.","zh":"如果電影製造強烈興奮感，就能令觀眾湧到戲院。"},{"en":"The phrase describes strong public attraction.","zh":"這個短語描述強大的公眾吸引力。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":11},{"front":"cultural hub","meaning":"文化中心","examples":[{"en":"The multiplex cinema is a modern cultural hub.","zh":"多廳戲院是一個現代文化中心。"},{"en":"A cultural hub is a place where people gather for art, entertainment, ideas or shared experiences.","zh":"文化中心是人們為藝術、娛樂、思想或共同體驗而聚集的地方。"},{"en":"A public library can be a cultural hub if it hosts talks, exhibitions and reading clubs.","zh":"如果公共圖書館舉辦講座、展覽和讀書會，它可以成為文化中心。"},{"en":"If a cinema becomes a cultural hub, it offers more than films; it offers community experience.","zh":"如果戲院成為文化中心，它提供的不只是電影，而是社群體驗。"},{"en":"The phrase describes a centre of cultural activity.","zh":"這個短語描述文化活動的中心。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":11},{"front":"analyse the process","meaning":"分析過程","examples":[{"en":"Aristotle analysed the storytelling process with cool rationalism.","zh":"亞里士多德以冷靜理性分析講故事的過程。"},{"en":"To analyse the process means to examine the steps or parts of how something works.","zh":"“Analyse the process” 指檢視某事如何運作的步驟或部分。"},{"en":"A coach may analyse the process of losing a match to find where the team made mistakes.","zh":"教練可能分析輸掉比賽的過程，以找出隊伍在哪裡犯錯。"},{"en":"If writers analyse storytelling, they can see why certain scenes create strong emotions.","zh":"如果作家分析敘事，就能看見為何某些場景產生強烈情緒。"},{"en":"The phrase describes careful step-by-step examination.","zh":"這個短語描述仔細逐步檢視。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":11},{"front":"cool rationalism","meaning":"冷靜理性","examples":[{"en":"He analysed storytelling with cool rationalism.","zh":"他以冷靜理性分析講故事。"},{"en":"Cool rationalism means calm, logical thinking without being carried away by emotion.","zh":"冷靜理性指不被情緒帶走的平靜、合邏輯思考。"},{"en":"A doctor needs cool rationalism when choosing treatment during an emergency.","zh":"醫生在緊急情況下選擇治療方法時，需要冷靜理性。"},{"en":"If storytelling is analysed with cool rationalism, feelings are studied through structure and cause.","zh":"如果講故事以冷靜理性分析，情感就透過結構和原因被研究。"},{"en":"The phrase describes calm reasoning applied to an emotional subject.","zh":"這個短語描述把平靜推理應用於情感題目。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":12},{"front":"enchant us","meaning":"令我們着迷","examples":[{"en":"A story enchants us when we lose awareness of reality.","zh":"當我們失去對現實的意識時，故事就令我們着迷。"},{"en":"To enchant us means to hold our attention so strongly that we feel delighted or absorbed.","zh":"“Enchant us” 指強烈吸引我們的注意，使我們感到愉快或沉浸。"},{"en":"A children’s story may enchant us with simple language and magical images.","zh":"兒童故事可能以簡單語言和魔法圖像令我們着迷。"},{"en":"If a film enchants us, we may forget the cinema seat and feel inside the story.","zh":"如果電影令我們着迷，我們可能忘記戲院座位，感覺自己在故事裏。"},{"en":"The phrase describes deep imaginative attraction.","zh":"這個短語描述深層想像吸引力。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":12},{"front":"lose the sense of","meaning":"失去對……的感覺","examples":[{"en":"When a story enchants us, we lose the sense of where we are.","zh":"當故事令我們着迷時，我們會失去對自己身在何處的感覺。"},{"en":"To lose the sense of something means to stop being aware of it.","zh":"“Lose the sense of” 某事指不再意識到它。"},{"en":"A student deeply focused on drawing may lose the sense of time.","zh":"深深專注畫畫的學生可能失去對時間的感覺。"},{"en":"If a story is powerful, readers may lose the sense of the room around them.","zh":"如果故事有力，讀者可能失去對周圍房間的感覺。"},{"en":"The phrase describes attention moving away from ordinary awareness.","zh":"這個短語描述注意力離開平常意識。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":12},{"front":"be drawn into","meaning":"被吸引進入","examples":[{"en":"We are drawn into the story so thoroughly that we forget reality.","zh":"我們被如此徹底地吸引進入故事，以致忘記現實。"},{"en":"To be drawn into something means to become strongly involved or absorbed in it.","zh":"“Be drawn into” 某事指強烈投入或沉浸其中。"},{"en":"A student may be drawn into a novel and keep reading past midnight.","zh":"學生可能被小說吸引進入其中，讀到午夜後仍不停。"},{"en":"If viewers are drawn into a film, they care about the characters as if they were real.","zh":"如果觀眾被電影吸引進入其中，他們會像人物真實存在一樣在乎他們。"},{"en":"The phrase describes being pulled mentally or emotionally into an experience.","zh":"這個短語描述在心理或情感上被拉進某種體驗。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":12},{"front":"so thoroughly that","meaning":"如此徹底以致","examples":[{"en":"We are drawn into the story so thoroughly that we forget it is fiction.","zh":"我們被如此徹底地吸引進入故事，以致忘記它是虛構的。"},{"en":"So thoroughly that means to such a complete degree that a clear result follows.","zh":"“So thoroughly that” 指程度如此完整，以致帶來清楚結果。"},{"en":"A student revised so thoroughly that the exam questions felt familiar.","zh":"學生溫習得如此徹底，以致考試題目感覺很熟悉。"},{"en":"If viewers enter a story so thoroughly, they may react as if events are real.","zh":"如果觀眾如此徹底進入故事，他們可能像事件真實發生一樣反應。"},{"en":"The phrase links intensity with a result.","zh":"這個短語把強度與結果連繫起來。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":12},{"front":"suspension of disbelief","meaning":"暫時擱置懷疑","examples":[{"en":"Aristotle described this as the suspension of disbelief.","zh":"亞里士多德把這描述為暫時擱置懷疑。"},{"en":"Suspension of disbelief is the temporary acceptance of a fictional story as if it were real.","zh":"暫時擱置懷疑是暫時把虛構故事當作真實接受。"},{"en":"Viewers practise suspension of disbelief when they worry about a superhero even though they know the character is invented.","zh":"觀眾明知超級英雄是被創造出來的，仍為他擔心時，就是在暫時擱置懷疑。"},{"en":"If a film breaks this suspension, the audience suddenly remembers it is only acting.","zh":"如果電影打破這種暫時擱置，觀眾會突然記起這只是演戲。"},{"en":"The phrase explains how fiction can feel emotionally real.","zh":"這個短語解釋虛構如何感覺在情感上真實。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":12},{"front":"know the feeling","meaning":"知道這種感覺","examples":[{"en":"We know the feeling of being captivated by a story.","zh":"我們知道被故事迷住的那種感覺。"},{"en":"To know the feeling means to have experienced that emotion or situation personally.","zh":"“Know the feeling” 指親身經歷過那種情緒或情況。"},{"en":"Anyone who has waited nervously for exam results knows the feeling of suspense.","zh":"等待考試結果時感到緊張的人，都知道懸念那種感覺。"},{"en":"If readers know the feeling, the writer can connect theory to lived experience.","zh":"如果讀者知道這種感覺，作者就能把理論與生活經驗連繫起來。"},{"en":"The phrase appeals to a shared human experience.","zh":"這個短語訴諸共同的人類經驗。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":12},{"front":"stay in our seats","meaning":"留在座位上","examples":[{"en":"We may stay in our seats as the credits roll by.","zh":"片尾字幕滾動時，我們可能仍留在座位上。"},{"en":"To stay in our seats means to remain sitting rather than leaving immediately.","zh":"“Stay in our seats” 指繼續坐着，而不是立即離開。"},{"en":"After a moving school performance, parents may stay in their seats for a few quiet seconds.","zh":"感人的學校表演後，家長可能安靜地留在座位上幾秒。"},{"en":"If a film affects viewers deeply, they may stay seated after it ends.","zh":"如果電影深深影響觀眾，他們可能在結束後仍坐着。"},{"en":"The phrase shows the emotional after-effect of a powerful story.","zh":"這個短語顯示強大故事帶來的情感餘波。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":12},{"front":"stunned with grief","meaning":"因悲傷而震撼","examples":[{"en":"An audience may be stunned with grief after a powerful film.","zh":"觀眾可能在看完有力電影後因悲傷而震撼。"},{"en":"Stunned with grief means shocked and almost unable to react because of deep sadness.","zh":"“Stunned with grief” 指因深切悲傷而震驚，幾乎無法反應。"},{"en":"A family may be stunned with grief after receiving terrible news.","zh":"家庭收到噩耗後，可能因悲傷而震撼。"},{"en":"If a tragedy is emotionally powerful, viewers may feel silent and stunned afterward.","zh":"如果悲劇在情感上很有力，觀眾之後可能沉默而震撼。"},{"en":"The phrase describes overwhelming sadness and shock together.","zh":"這個短語描述壓倒性的悲傷和震驚同時出現。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":12},{"front":"credits roll by","meaning":"片尾字幕滾動","examples":[{"en":"The credits roll by at the end of a film.","zh":"電影結尾時，片尾字幕滾動。"},{"en":"Credits roll by means the list of people who made the film moves across the screen.","zh":"“Credits roll by” 指製作電影人員名單在螢幕上移動。"},{"en":"Some viewers leave when the credits roll by, while others stay for extra scenes.","zh":"有些觀眾在片尾字幕滾動時離開，另一些則留下等額外片段。"},{"en":"If people remain silent as the credits roll by, the film may have affected them deeply.","zh":"如果片尾字幕滾動時人們仍沉默坐着，電影可能深深影響了他們。"},{"en":"The phrase describes a familiar moment after a movie ends.","zh":"這個短語描述電影結束後熟悉的一刻。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":12},{"front":"feel nervous about","meaning":"對……感到緊張","examples":[{"en":"Viewers may feel nervous about taking a shower after a horror film.","zh":"觀眾看完恐怖片後，可能對洗澡感到緊張。"},{"en":"To feel nervous about something means to feel worried, tense or afraid before doing it.","zh":"“Feel nervous about” 某事指在做它之前感到擔心、緊張或害怕。"},{"en":"A student may feel nervous about speaking English in front of classmates.","zh":"學生可能對在同學面前說英語感到緊張。"},{"en":"If a horror film is vivid, viewers may feel nervous about ordinary actions afterward.","zh":"如果恐怖片很生動，觀眾之後可能對普通行動感到緊張。"},{"en":"The phrase describes anxiety connected to a specific action or situation.","zh":"這個短語描述與特定行動或情況相關的焦慮。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":12},{"front":"vivid evocation of horror","meaning":"對恐怖的生動呈現","examples":[{"en":"A film can provide a vivid evocation of horror.","zh":"電影可以提供對恐怖的生動呈現。"},{"en":"A vivid evocation of horror is a strong and detailed creation of fear in the audience’s mind.","zh":"對恐怖的生動呈現，是在觀眾腦中強烈而細緻地創造恐懼。"},{"en":"A dark hallway, slow footsteps and silence can create a vivid evocation of horror.","zh":"黑暗走廊、緩慢腳步聲和寂靜可以創造對恐怖的生動呈現。"},{"en":"If horror is evoked vividly, viewers may keep feeling afraid after the film ends.","zh":"如果恐怖被生動喚起，觀眾可能在電影結束後仍感到害怕。"},{"en":"The phrase describes powerful artistic presentation of fear.","zh":"這個短語描述對恐懼的有力藝術呈現。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":13},{"front":"be caught in","meaning":"被困於……","examples":[{"en":"We have been caught in the storyteller’s web.","zh":"我們被困於講故事者編織的網中。"},{"en":"To be caught in something means to be trapped or strongly held by it.","zh":"“Be caught in” 某事指被它困住或強烈抓住。"},{"en":"A student may be caught in a difficult argument between two close friends.","zh":"學生可能被困於兩位好友之間的困難爭執中。"},{"en":"If viewers are caught in a story, they find it hard to step back emotionally.","zh":"如果觀眾被故事困住，就很難在情感上抽離。"},{"en":"The phrase can be literal or metaphorical, but it suggests being held.","zh":"這個短語可以是字面或比喻，但暗示被抓住。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":13},{"front":"be captivated in","meaning":"被……迷住","examples":[{"en":"Audiences can be captivated in the storyteller’s web.","zh":"觀眾可以被講故事者編織的網迷住。"},{"en":"To be captivated in something means to be held by its charm, interest or emotional power.","zh":"“Be captivated in” 某事指被其魅力、趣味或情感力量抓住。"},{"en":"Children may be captivated in a puppet show when the characters feel alive.","zh":"當角色感覺像活起來時，孩子可能被木偶戲迷住。"},{"en":"If an audience is captivated, they stop noticing distractions around them.","zh":"如果觀眾被迷住，就會停止注意周圍干擾。"},{"en":"The phrase describes deep attraction inside an experience.","zh":"這個短語描述在某種體驗中的深層吸引。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":13},{"front":"storyteller’s web","meaning":"講故事者編織的網","examples":[{"en":"A good story traps us in the storyteller’s web.","zh":"好故事把我們困在講故事者編織的網中。"},{"en":"A storyteller’s web is a metaphor for the connected details that hold the audience’s attention.","zh":"講故事者編織的網是一個比喻，指抓住觀眾注意力的相連細節。"},{"en":"A novelist builds a storyteller’s web through mystery, emotion and unanswered questions.","zh":"小說家透過謎團、情感和未解問題建立講故事者的網。"},{"en":"If the web is strong, readers keep turning pages because every detail feels connected.","zh":"如果這張網很強，讀者會一直翻頁，因為每個細節都感覺相連。"},{"en":"The phrase imagines storytelling as something that catches and holds us.","zh":"這個短語把講故事想像成能捕捉並抓住我們的東西。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":13},{"front":"for a while","meaning":"有一段時間","examples":[{"en":"We may believe the story really happened for a while.","zh":"我們可能有一段時間相信故事真的發生過。"},{"en":"For a while means for a short or limited period of time.","zh":"“For a while” 指一段短暫或有限時間。"},{"en":"A child may believe in a magic trick for a while before learning how it works.","zh":"孩子可能有一段時間相信魔術，直到知道它如何運作。"},{"en":"If a story is convincing, viewers may forget reality for a while.","zh":"如果故事令人信服，觀眾可能有一段時間忘記現實。"},{"en":"The phrase describes temporary duration.","zh":"這個短語描述暫時的持續時間。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":13},{"front":"witness","meaning":"見證","examples":[{"en":"Aristotle must often have witnessed the suspension of disbelief.","zh":"亞里士多德一定經常見證暫時擱置懷疑的情況。"},{"en":"To witness something means to see it happen or experience it directly.","zh":"“Witness” 某事指看見它發生或直接經歷它。"},{"en":"A teacher may witness a shy student gaining confidence over several months.","zh":"老師可能見證害羞學生在數月間建立信心。"},{"en":"If Aristotle watched audiences react to theatre, he could witness how stories changed emotions.","zh":"如果亞里士多德觀看觀眾對戲劇的反應，他就能見證故事如何改變情緒。"},{"en":"The word focuses on direct observation.","zh":"這個詞強調直接觀察。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":13},{"front":"civic ritual","meaning":"公民儀式","examples":[{"en":"Theatre developed as a primary form of civic ritual.","zh":"戲劇發展成為公民儀式的一種主要形式。"},{"en":"A civic ritual is a public ceremony or repeated practice that belongs to community life.","zh":"公民儀式是屬於社區生活的公共典禮或重複做法。"},{"en":"A city’s annual memorial service can be a civic ritual that brings residents together.","zh":"城市每年的紀念儀式可以是把居民凝聚起來的公民儀式。"},{"en":"If theatre was a civic ritual, watching plays was part of public identity, not just entertainment.","zh":"如果戲劇是公民儀式，觀看戲劇就是公共身份的一部分，而不只是娛樂。"},{"en":"The phrase connects performance with shared social life.","zh":"這個短語把表演與共同社會生活連繫起來。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":13},{"front":"recreation","meaning":"消遣","examples":[{"en":"Theatre was also a form of recreation.","zh":"戲劇也是一種消遣。"},{"en":"Recreation means enjoyable activity done for rest, relaxation or pleasure.","zh":"消遣指為休息、放鬆或樂趣而做的愉快活動。"},{"en":"Playing football after school is recreation for many students.","zh":"放學後踢足球對許多學生來說是消遣。"},{"en":"If theatre is recreation, audiences attend it to enjoy themselves as well as to think.","zh":"如果戲劇是消遣，觀眾去看它就是為了享受，也為了思考。"},{"en":"The word refers to leisure, not work or duty only.","zh":"這個詞指休閒，而不只是工作或責任。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":13},{"front":"theatrical types of storytelling","meaning":"戲劇敘事類型","examples":[{"en":"Tragedy and comedy were theatrical types of storytelling.","zh":"悲劇和喜劇是戲劇敘事類型。"},{"en":"Theatrical types of storytelling are story forms performed on stage for an audience.","zh":"戲劇敘事類型是在舞台上為觀眾表演的故事形式。"},{"en":"A school play may use theatrical storytelling through dialogue, movement and stage design.","zh":"學校戲劇可能透過對白、動作和舞台設計使用戲劇敘事。"},{"en":"If a story is theatrical, actors and performance shape how the audience receives it.","zh":"如果故事是戲劇性的，演員和表演會塑造觀眾如何接收它。"},{"en":"The phrase refers to storytelling through drama.","zh":"這個短語指透過戲劇進行講故事。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":13},{"front":"tragedy and comedy","meaning":"悲劇和喜劇","examples":[{"en":"Tragedy and comedy affected audiences in different ways.","zh":"悲劇和喜劇以不同方式影響觀眾。"},{"en":"Tragedy and comedy are two major story types, one often serious and sad, the other often humorous.","zh":"悲劇和喜劇是兩種主要故事類型，一種通常嚴肅悲傷，另一種通常幽默。"},{"en":"A tragedy may make viewers cry, while a comedy may make them laugh at human mistakes.","zh":"悲劇可能令觀眾哭，而喜劇可能令他們笑看人類錯誤。"},{"en":"If a theatre offers both tragedy and comedy, it can move audiences through sorrow and laughter.","zh":"如果劇院同時提供悲劇和喜劇，就能透過悲傷和笑聲打動觀眾。"},{"en":"The phrase names two classic dramatic categories.","zh":"這個短語指出兩種經典戲劇類別。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":13},{"front":"lose themselves in","meaning":"沉浸於……","examples":[{"en":"Athenian audiences lost themselves in sadness and laughter.","zh":"雅典觀眾沉浸於悲傷和笑聲之中。"},{"en":"To lose themselves in something means to become deeply absorbed in an emotion or experience.","zh":"“Lose themselves in” 某事指深深沉浸於某種情緒或體驗。"},{"en":"Children may lose themselves in a game and forget the time.","zh":"孩子可能沉浸於遊戲中，忘記時間。"},{"en":"If audiences lose themselves in a play, the performance has captured their attention fully.","zh":"如果觀眾沉浸於戲劇中，表演就已完全抓住他們的注意。"},{"en":"The phrase describes deep emotional or imaginative immersion.","zh":"這個短語描述深層情感或想像沉浸。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":13},{"front":"respectively","meaning":"分別地","examples":[{"en":"Tragedy and comedy caused sadness and laughter respectively.","zh":"悲劇和喜劇分別帶來悲傷和笑聲。"},{"en":"Respectively means in the same order as the things just mentioned.","zh":"“Respectively” 指按照剛提到事物的相同次序。"},{"en":"Tom and May scored 80 and 90 respectively, meaning Tom scored 80 and May scored 90.","zh":"Tom 和 May 分別取得80和90分，意思是 Tom 得80分，May 得90分。"},{"en":"If tragedy and comedy create sadness and laughter respectively, the first emotion matches the first story type.","zh":"如果悲劇和喜劇分別帶來悲傷和笑聲，第一種情緒就對應第一種故事類型。"},{"en":"The word helps match two lists accurately.","zh":"這個詞幫助準確配對兩個列表。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":14},{"front":"particularly potent","meaning":"特別有力","examples":[{"en":"Tragedy was particularly potent in its emotional effect.","zh":"悲劇在情感效果上特別有力。"},{"en":"Particularly potent means especially powerful or effective.","zh":"“Particularly potent” 指尤其強大或有效。"},{"en":"A simple apology can be particularly potent when it is sincere and specific.","zh":"如果道歉真誠而具體，簡單道歉可以特別有力。"},{"en":"If tragedy is potent, it can stir emotions more deeply than lighter stories.","zh":"如果悲劇有力，它就能比輕鬆故事更深地觸動情緒。"},{"en":"The phrase emphasises unusually strong impact.","zh":"這個短語強調異常強烈的影響。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":14},{"front":"capacity to","meaning":"……的能力","examples":[{"en":"Tragedy has the capacity to enlist and purge emotions.","zh":"悲劇有能力調動並淨化情緒。"},{"en":"Capacity to do something means the ability or power to do it.","zh":"“Capacity to” 做某事指做該事的能力或力量。"},{"en":"A good teacher has the capacity to make difficult ideas feel manageable.","zh":"好老師有能力令困難概念感覺可以處理。"},{"en":"If tragedy has the capacity to affect emotions, it can change how audiences feel during and after the play.","zh":"如果悲劇有能力影響情緒，它就能改變觀眾在劇中和劇後的感受。"},{"en":"The phrase focuses on ability or potential.","zh":"這個短語強調能力或潛力。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":14},{"front":"enlist the emotions","meaning":"調動情緒","examples":[{"en":"Tragedy can enlist the emotions of the audience.","zh":"悲劇可以調動觀眾的情緒。"},{"en":"To enlist the emotions means to draw feelings into active involvement.","zh":"“Enlist the emotions” 指把情感拉入積極參與。"},{"en":"A charity video may enlist the emotions of viewers by showing one real family’s struggle.","zh":"慈善影片可能透過展示一個真實家庭的掙扎來調動觀眾情緒。"},{"en":"If a story enlists emotions, the audience does not just understand events; they feel them.","zh":"如果故事調動情緒，觀眾就不只是理解事件，而是感受事件。"},{"en":"The phrase describes emotionally engaging people.","zh":"這個短語描述讓人情感投入。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":14},{"front":"purge the emotions","meaning":"淨化情緒","examples":[{"en":"Tragedy can purge the emotions of those watching.","zh":"悲劇可以淨化觀眾的情緒。"},{"en":"To purge the emotions means to release or cleanse strong feelings through an intense experience.","zh":"“Purge the emotions” 指透過強烈體驗釋放或清理強烈情感。"},{"en":"Some people cry during a sad film and feel calmer afterwards.","zh":"有些人看悲傷電影時哭泣，之後感到較平靜。"},{"en":"If tragedy purges emotions, pain on stage may help audiences process their own feelings.","zh":"如果悲劇淨化情緒，舞台上的痛苦可能幫助觀眾處理自己的感受。"},{"en":"The phrase describes emotional release, not simply sadness.","zh":"這個短語描述情感釋放，而不只是悲傷。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":14},{"front":"watch the story unfold","meaning":"看着故事展開","examples":[{"en":"Audiences watch the story unfold on the stage.","zh":"觀眾看着故事在舞台上展開。"},{"en":"To watch the story unfold means to see events develop step by step.","zh":"“Watch the story unfold” 指看見事件一步步發展。"},{"en":"Viewers watch a mystery unfold as each clue is discovered.","zh":"觀眾隨着每條線索被發現，看着懸疑故事展開。"},{"en":"If a story unfolds slowly, the audience learns information at the same time as the characters.","zh":"如果故事慢慢展開，觀眾就與角色同時得知資料。"},{"en":"The phrase describes gradual development in a story.","zh":"這個短語描述故事中的逐步發展。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":14},{"front":"identify factors","meaning":"識別因素","examples":[{"en":"Aristotle tried to identify factors in the storyteller’s art.","zh":"亞里士多德嘗試識別講故事藝術中的因素。"},{"en":"To identify factors means to find the elements or causes that affect a result.","zh":"“Identify factors” 指找出影響結果的元素或原因。"},{"en":"A teacher may identify factors behind poor exam results, such as weak vocabulary or careless timing.","zh":"老師可能識別考試成績差背後的因素，例如詞彙弱或時間安排粗心。"},{"en":"If Aristotle identified storytelling factors, he was looking for what makes stories work.","zh":"如果亞里士多德識別敘事因素，他就是在尋找故事有效的原因。"},{"en":"The phrase describes analysing causes or important parts.","zh":"這個短語描述分析原因或重要部分。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":14},{"front":"storyteller’s art","meaning":"講故事的藝術","examples":[{"en":"Aristotle studied the storyteller’s art.","zh":"亞里士多德研究講故事的藝術。"},{"en":"The storyteller’s art is the skill of shaping events, characters and language into a compelling story.","zh":"講故事的藝術，是把事件、人物和語言塑造成吸引人故事的技巧。"},{"en":"A parent uses the storyteller’s art when turning a normal day into an exciting bedtime story.","zh":"父母把普通一天變成刺激睡前故事時，就是在運用講故事的藝術。"},{"en":"If the storyteller’s art is strong, even a simple plot can feel powerful.","zh":"如果講故事的藝術強，即使簡單情節也可以感覺有力。"},{"en":"The phrase treats storytelling as a skilled craft.","zh":"這個短語把講故事視為有技巧的工藝。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":14},{"front":"bring about","meaning":"帶來；造成","examples":[{"en":"Certain techniques bring about audience engagement.","zh":"某些技巧會帶來觀眾投入感。"},{"en":"To bring about something means to cause it to happen.","zh":"“Bring about” 某事指造成它發生。"},{"en":"Clear rules can bring about better behaviour in a classroom.","zh":"清晰規則可以帶來更好的課室行為。"},{"en":"If a story technique brings about engagement, it makes audiences care and pay attention.","zh":"如果敘事技巧帶來投入感，它就令觀眾在乎並專注。"},{"en":"The phrase links an action or method with its result.","zh":"這個短語把行動或方法與結果連繫起來。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":14},{"front":"engagement","meaning":"投入感；參與感","examples":[{"en":"Aristotle studied how stories create engagement.","zh":"亞里士多德研究故事如何創造投入感。"},{"en":"Engagement means active attention, interest and emotional involvement.","zh":"投入感指主動注意、興趣和情感參與。"},{"en":"A teacher can increase engagement by asking students to solve a real problem.","zh":"老師可以透過要求學生解決真實問題來增加投入感。"},{"en":"If a film creates engagement, viewers care about what happens to the characters.","zh":"如果電影創造投入感，觀眾會在乎角色發生甚麼。"},{"en":"The word describes more than watching; it means being mentally involved.","zh":"這個詞描述的不只是觀看，而是心理上的參與。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":14},{"front":"obvious sample for analysis","meaning":"明顯的分析樣本","examples":[{"en":"Greek tragedy was an obvious sample for analysis.","zh":"希臘悲劇是明顯的分析樣本。"},{"en":"An obvious sample for analysis is a clear example chosen for close study.","zh":"明顯的分析樣本，是被選來仔細研究的清楚例子。"},{"en":"A teacher may use a strong student essay as an obvious sample for analysing good structure.","zh":"老師可能使用一篇強學生作文作為分析良好結構的明顯樣本。"},{"en":"If Greek tragedy clearly shows emotional effects, it is a natural choice for analysis.","zh":"如果希臘悲劇清楚顯示情感效果，它就是自然的分析選擇。"},{"en":"The phrase describes an example that is easy to justify studying.","zh":"這個短語描述很容易解釋為何值得研究的例子。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":14},{"front":"Classical Greek tragedy","meaning":"古典希臘悲劇","examples":[{"en":"Aristotle analysed masterpieces of Classical Greek tragedy.","zh":"亞里士多德分析古典希臘悲劇的傑作。"},{"en":"Classical Greek tragedy refers to serious ancient Greek plays about suffering, fate and moral conflict.","zh":"古典希臘悲劇指關於痛苦、命運和道德衝突的古希臘嚴肅戲劇。"},{"en":"Students may study Classical Greek tragedy to understand how old drama shaped later theatre.","zh":"學生可能研究古典希臘悲劇，以理解古老戲劇如何塑造後來劇場。"},{"en":"If a tragedy belongs to the classical Greek tradition, it often examines human weakness and fate.","zh":"如果悲劇屬於古典希臘傳統，它通常檢視人類弱點和命運。"},{"en":"The phrase identifies a major ancient dramatic form.","zh":"這個短語指出一種重要古代戲劇形式。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":15},{"front":"literary landmarks","meaning":"文學里程碑","examples":[{"en":"The Iliad and The Odyssey were already considered literary landmarks.","zh":"《伊利亞特》和《奧德賽》早已被視為文學里程碑。"},{"en":"Literary landmarks are works that are extremely important in the history of literature.","zh":"文學里程碑是在文學史上極其重要的作品。"},{"en":"A novel may become a literary landmark if later writers and readers keep returning to it.","zh":"如果後來的作家和讀者不斷回到某本小說，它可能成為文學里程碑。"},{"en":"If a work is a literary landmark, it becomes a standard for judging other works.","zh":"如果作品是文學里程碑，它就成為衡量其他作品的標準。"},{"en":"The phrase describes books or stories with lasting cultural importance.","zh":"這個短語描述具有持久文化重要性的書或故事。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":15},{"front":"be measured by","meaning":"以……衡量","examples":[{"en":"Other stories were measured by Homer’s stories.","zh":"其他故事以荷馬的故事衡量。"},{"en":"To be measured by something means to be judged against it as a standard.","zh":"“Be measured by” 某事指以它作為標準來評價。"},{"en":"A new phone may be measured by the battery life and camera quality of leading models.","zh":"新手機可能以領先型號的電池壽命和相機質素來衡量。"},{"en":"If stories are measured by Homer, his works set the level others try to reach.","zh":"如果故事以荷馬衡量，他的作品就設定了其他作品努力達到的水平。"},{"en":"The phrase describes comparison with a benchmark.","zh":"這個短語描述與標準作比較。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":15},{"front":"narrative art","meaning":"敘事藝術","examples":[{"en":"Aristotle examined the secret of Homer’s narrative art.","zh":"亞里士多德檢視荷馬敘事藝術的秘密。"},{"en":"Narrative art is the skill of telling stories effectively through structure, language and character.","zh":"敘事藝術是透過結構、語言和人物有效講故事的技巧。"},{"en":"A filmmaker’s narrative art may appear in how she reveals a secret slowly.","zh":"電影製作人的敘事藝術可能體現在她如何慢慢揭示秘密。"},{"en":"If narrative art is strong, audiences care even before they know the ending.","zh":"如果敘事藝術強，觀眾即使未知道結局也會在乎。"},{"en":"The phrase treats storytelling as a crafted artistic skill.","zh":"這個短語把講故事視為精心製作的藝術技能。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":15},{"front":"not hard to find","meaning":"不難找到","examples":[{"en":"The secret of Homer’s narrative art was not hard to find.","zh":"荷馬敘事藝術的秘密不難找到。"},{"en":"Not hard to find means easy or fairly simple to identify.","zh":"“Not hard to find” 指容易或相當容易識別。"},{"en":"The reason for the student’s tiredness was not hard to find: he had slept only three hours.","zh":"學生疲倦的原因不難找到：他只睡了三小時。"},{"en":"If the strongest feature of a story is obvious, its secret is not hard to find.","zh":"如果故事最強的特點很明顯，其秘密就不難找到。"},{"en":"The phrase suggests the answer is clear once you look carefully.","zh":"這個短語暗示只要仔細看，答案就很清楚。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":15},{"front":"credible heroes","meaning":"可信的英雄","examples":[{"en":"Homer created credible heroes.","zh":"荷馬創造了可信的英雄。"},{"en":"Credible heroes are heroic characters who feel believable because they have human qualities.","zh":"可信的英雄是因具有人性特質而感覺真實可信的英雄人物。"},{"en":"A superhero becomes more credible when he feels fear, makes mistakes and learns from them.","zh":"當超級英雄會害怕、犯錯並從中學習時，他就變得更可信。"},{"en":"If heroes are too perfect, audiences may admire them but not fully believe them.","zh":"如果英雄太完美，觀眾可能欣賞他們，但不會完全相信他們。"},{"en":"The phrase describes heroes who are impressive but still believable.","zh":"這個短語描述令人敬佩但仍可信的英雄。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":15},{"front":"belong to the past","meaning":"屬於過去","examples":[{"en":"Homer’s heroes belonged to the past.","zh":"荷馬的英雄屬於過去。"},{"en":"To belong to the past means to come from an earlier time rather than the present.","zh":"“Belong to the past” 指來自較早時代，而不是現在。"},{"en":"Old farming tools may belong to the past, but they can still teach us how people lived.","zh":"舊農具可能屬於過去，但仍能教我們人們如何生活。"},{"en":"If heroes belong to the past, they may feel legendary, distant and culturally important.","zh":"如果英雄屬於過去，他們可能感覺傳奇、遙遠且具文化重要性。"},{"en":"The phrase places people or objects in history.","zh":"這個短語把人物或物件放在歷史中。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":15},{"front":"mighty and magnificent","meaning":"強大而壯麗","examples":[{"en":"Homer’s heroes were mighty and magnificent.","zh":"荷馬的英雄強大而壯麗。"},{"en":"Mighty and magnificent means powerful, impressive and grand.","zh":"“Mighty and magnificent” 指有力量、令人印象深刻而宏偉。"},{"en":"A mighty and magnificent mountain can make hikers feel small and amazed.","zh":"強大而壯麗的高山可以令登山者感到渺小和驚嘆。"},{"en":"If heroes are mighty and magnificent, audiences may admire their strength and greatness.","zh":"如果英雄強大而壯麗，觀眾可能欣賞其力量和偉大。"},{"en":"The phrase gives a grand, heroic description.","zh":"這個短語給出宏大的英雄式描述。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":15},{"front":"in the end","meaning":"到最後","examples":[{"en":"In the end, the heroes were not fantasy figures.","zh":"到最後，這些英雄並不是幻想人物。"},{"en":"In the end means finally, after considering everything.","zh":"“In the end” 指最終，在考慮一切之後。"},{"en":"The project seemed difficult, but in the end the group finished it on time.","zh":"項目看似困難，但到最後小組準時完成。"},{"en":"If a character first appears larger than life but feels human in the end, the audience may connect more deeply.","zh":"如果角色起初看似超越常人，但到最後感覺有人性，觀眾可能更深地連繫。"},{"en":"The phrase introduces a final judgement or result.","zh":"這個短語引出最終判斷或結果。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":15},{"front":"fantasy figures","meaning":"幻想人物","examples":[{"en":"Homer’s heroes were not merely fantasy figures.","zh":"荷馬的英雄不只是幻想人物。"},{"en":"Fantasy figures are imaginary characters who may not feel realistic or human.","zh":"幻想人物是想像中的角色，可能不太真實或不太有人性。"},{"en":"A dragon can be a fantasy figure, while a flawed hero can feel more human.","zh":"龍可以是幻想人物，而有缺點的英雄可以感覺更有人性。"},{"en":"If characters are only fantasy figures, audiences may enjoy them but not truly care about them.","zh":"如果角色只是幻想人物，觀眾可能享受他們，但不會真正關心他們。"},{"en":"The phrase contrasts imagined beings with believable characters.","zh":"這個短語把想像人物與可信人物作對比。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":15},{"front":"make someone sulk","meaning":"令某人鬧情緒","examples":[{"en":"Homer made his heroes sulk, bicker, cheat and cry.","zh":"荷馬令他的英雄鬧情緒、爭吵、欺騙和哭泣。"},{"en":"To make someone sulk means to show that person being silent, resentful or bad-tempered after disappointment.","zh":"“Make someone sulk” 指展示某人失望後沉默、怨氣或脾氣不好。"},{"en":"A child may sulk after losing a game instead of speaking honestly about feeling upset.","zh":"孩子輸掉遊戲後可能鬧情緒，而不是誠實說出自己不開心。"},{"en":"If a hero sulks, the audience sees weakness rather than perfect nobility.","zh":"如果英雄鬧情緒，觀眾就看見弱點，而不是完美高貴。"},{"en":"The phrase helps make a character more human.","zh":"這個短語幫助令角色更有人性。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":15},{"front":"bicker","meaning":"爭吵","examples":[{"en":"Homer’s heroes sometimes bickered with each other.","zh":"荷馬的英雄有時彼此爭吵。"},{"en":"To bicker means to argue about small things in a petty or repeated way.","zh":"“Bicker” 指為小事瑣碎或反覆爭吵。"},{"en":"Siblings may bicker over who gets the bigger piece of cake.","zh":"兄弟姊妹可能為誰得到較大塊蛋糕而爭吵。"},{"en":"If heroes bicker, they feel more like real people with pride and irritation.","zh":"如果英雄會爭吵，他們就更像有自尊和煩躁情緒的真人。"},{"en":"The word describes small, often annoying arguments.","zh":"這個詞描述細小而常令人厭煩的爭論。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":16},{"front":"in short","meaning":"簡而言之","examples":[{"en":"In short, they were characters.","zh":"簡而言之，他們是人物。"},{"en":"In short means briefly stated or to summarise the main point.","zh":"“In short” 指簡短地說，或概括主要意思。"},{"en":"The lesson was difficult, noisy and confusing; in short, it needed better planning.","zh":"這堂課困難、嘈雜又混亂；簡而言之，它需要更好規劃。"},{"en":"If a writer says “in short,” they are reducing a longer argument to its key meaning.","zh":"如果作者說 “in short”，就是把較長論點濃縮成核心意思。"},{"en":"The phrase introduces a concise conclusion.","zh":"這個短語引出簡潔結論。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":16},{"front":"protagonists","meaning":"主角","examples":[{"en":"The heroes were protagonists of stories audiences cared about.","zh":"這些英雄是觀眾在乎的故事主角。"},{"en":"Protagonists are the main characters in stories, plays or films.","zh":"主角是故事、戲劇或電影中的主要人物。"},{"en":"In a school drama, the protagonist may be a student trying to solve a family problem.","zh":"在學校戲劇中，主角可能是一名嘗試解決家庭問題的學生。"},{"en":"If protagonists are interesting, audiences want to follow their choices and struggles.","zh":"如果主角有趣，觀眾會想跟隨他們的選擇和掙扎。"},{"en":"The word refers to central story characters.","zh":"這個詞指故事中的中心人物。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":16},{"front":"care about","meaning":"關心；在乎","examples":[{"en":"Audiences cared about Homer’s protagonists.","zh":"觀眾在乎荷馬的主角。"},{"en":"To care about someone means to feel interested in what happens to them and emotionally concerned for them.","zh":"“Care about” 某人指對其命運感興趣，並在情感上關心他。"},{"en":"Viewers care about a character when they worry whether she will succeed or fail.","zh":"當觀眾擔心角色會成功還是失敗時，他們就是在乎該角色。"},{"en":"If audiences do not care about the protagonist, even an exciting plot may feel empty.","zh":"如果觀眾不在乎主角，即使情節刺激也可能感覺空洞。"},{"en":"The phrase describes emotional investment.","zh":"這個短語描述情感投入。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":16},{"front":"human side","meaning":"人性化一面","examples":[{"en":"A hero who shows a human side is intrinsically dramatic.","zh":"展現人性化一面的英雄本質上具戲劇性。"},{"en":"A human side is the part of a person or character that shows ordinary feelings, weakness or vulnerability.","zh":"人性化一面是一個人或角色展現普通情感、弱點或脆弱的部分。"},{"en":"A strict teacher shows a human side when she admits she was nervous on her first day.","zh":"嚴格老師承認自己第一天也緊張時，就展現人性化一面。"},{"en":"If a hero shows a human side, audiences may connect with them more deeply.","zh":"如果英雄展現人性化一面，觀眾可能更深地與他連繫。"},{"en":"The phrase makes a character feel real rather than perfect.","zh":"這個短語令角色感覺真實，而不是完美。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":16},{"front":"flaw or weakness","meaning":"缺點或弱點","examples":[{"en":"A good hero may show some flaw or weakness.","zh":"好英雄可能展現某些缺點或弱點。"},{"en":"A flaw or weakness is an imperfection, limitation or vulnerable point in a person or character.","zh":"缺點或弱點是一個人或角色的不完美、限制或脆弱之處。"},{"en":"A clever student’s weakness may be impatience when working in a group.","zh":"聰明學生的弱點可能是在小組合作時缺乏耐性。"},{"en":"If a hero has a flaw, the story can show growth, failure or inner conflict.","zh":"如果英雄有缺點，故事就能展示成長、失敗或內心衝突。"},{"en":"The phrase helps make characters believable and dramatic.","zh":"這個短語幫助令人物可信且有戲劇性。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":16},{"front":"mortals are prone to","meaning":"凡人容易有……","examples":[{"en":"Mortals are prone to flaws and weaknesses.","zh":"凡人容易有缺點和弱點。"},{"en":"Mortals are prone to something means ordinary humans are likely to experience it.","zh":"“Mortals are prone to” 某事指普通人類很可能經歷它。"},{"en":"Students are prone to careless mistakes when they rush through a test.","zh":"學生匆忙完成測驗時，容易犯粗心錯誤。"},{"en":"If mortals are prone to weakness, believable heroes should not be completely perfect.","zh":"如果凡人容易有弱點，可信英雄就不應完全完美。"},{"en":"The phrase stresses ordinary human vulnerability.","zh":"這個短語強調普通人類的脆弱性。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":16},{"front":"intrinsically dramatic","meaning":"本質上具戲劇性","examples":[{"en":"A flawed hero is intrinsically dramatic.","zh":"有缺陷的英雄本質上具戲劇性。"},{"en":"Intrinsically dramatic means dramatic by its very nature, not because of extra decoration.","zh":"“Intrinsically dramatic” 指本身性質就有戲劇性，而不是靠額外裝飾。"},{"en":"A family secret is intrinsically dramatic because it creates tension before anyone speaks loudly.","zh":"家庭秘密本質上具戲劇性，因為它在任何人大聲說話前已製造張力。"},{"en":"If a hero is both great and weak, inner conflict becomes naturally dramatic.","zh":"如果英雄既偉大又脆弱，內心衝突自然變得有戲劇性。"},{"en":"The phrase describes drama built into the situation itself.","zh":"這個短語描述情況本身內含的戲劇性。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":16},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"Students must identify which paragraph contains the information.","zh":"學生必須識別哪一段包含該資料。"},{"en":"Which paragraph contains means which section of the passage includes the stated detail.","zh":"“Which paragraph contains” 指文章哪一部分包括所述細節。"},{"en":"In reading exams, students scan for names, dates or key words to find which paragraph contains an answer.","zh":"在閱讀考試中，學生掃讀姓名、日期或關鍵詞，以找出哪一段包含答案。"},{"en":"If the paragraph contains the detail, students should check the surrounding sentence before choosing it.","zh":"如果某段包含該細節，學生應先檢查前後句再選擇。"},{"en":"The phrase is used in paragraph-information matching tasks.","zh":"這個短語用於段落資料配對題。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":16},{"front":"mistaken belief","meaning":"錯誤看法","examples":[{"en":"The task asks about a mistaken belief about how people obtain stories today.","zh":"題目問一個關於今日人們如何取得故事的錯誤看法。"},{"en":"A mistaken belief is an idea that someone thinks is true but is actually wrong.","zh":"錯誤看法是某人以為正確但實際上錯誤的想法。"},{"en":"The belief that all good students study all night is a mistaken belief.","zh":"認為所有好學生都通宵讀書，是一種錯誤看法。"},{"en":"If a passage corrects a mistaken belief, students should notice the contrast words.","zh":"如果文章糾正錯誤看法，學生應留意對比詞。"},{"en":"The phrase describes an incorrect assumption.","zh":"這個短語描述不正確的假設。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":16},{"front":"obtain stories","meaning":"取得故事；接觸故事","examples":[{"en":"People obtain stories from cinema as well as books.","zh":"人們從電影以及書本中取得故事。"},{"en":"To obtain stories means to get access to stories or receive them from a source.","zh":"“Obtain stories” 指接觸到故事，或從某來源接收故事。"},{"en":"Children obtain stories from parents, teachers, cartoons and library books.","zh":"孩子從父母、老師、卡通和圖書館書本中接觸故事。"},{"en":"If people obtain stories from films, they are still experiencing storytelling without printed pages.","zh":"如果人們從電影取得故事，他們即使沒有印刷頁面也仍在體驗敘事。"},{"en":"The phrase focuses on how people receive stories.","zh":"這個短語強調人們如何接收故事。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":16},{"front":"classification of stories","meaning":"故事分類","examples":[{"en":"The passage mentions the classification of stories into tragedy and comedy.","zh":"文章提到把故事分為悲劇和喜劇的故事分類。"},{"en":"Classification of stories means sorting stories into types or categories.","zh":"故事分類指把故事分成類型或類別。"},{"en":"A teacher may ask students to classify stories as adventure, mystery, comedy or tragedy.","zh":"老師可能要求學生把故事分類為冒險、懸疑、喜劇或悲劇。"},{"en":"If stories are classified, readers can compare how different types affect audiences.","zh":"如果故事被分類，讀者就能比較不同類型如何影響觀眾。"},{"en":"The phrase refers to organising stories by shared features.","zh":"這個短語指按共同特徵組織故事。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":17},{"front":"fundamental purpose","meaning":"根本目的","examples":[{"en":"The fundamental purpose of storytelling is to keep people listening.","zh":"講故事的根本目的是讓人繼續聽。"},{"en":"A fundamental purpose is the deepest or most basic reason for doing something.","zh":"根本目的是做某事最深層或最基本的原因。"},{"en":"The fundamental purpose of school rules is to help people learn safely together.","zh":"校規的根本目的是幫助人們安全地一起學習。"},{"en":"If storytelling fails to keep people listening, it fails at a basic level.","zh":"如果講故事不能讓人繼續聽，它就在基本層面失敗。"},{"en":"The phrase identifies the core purpose beneath other aims.","zh":"這個短語指出其他目標之下的核心目的。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":17},{"front":"reciting stories without assistance","meaning":"在沒有輔助下背誦故事","examples":[{"en":"Some storytellers can recite stories without assistance.","zh":"有些講故事的人可以在沒有輔助下背誦故事。"},{"en":"Reciting stories without assistance means speaking stories from memory without notes, books or tools.","zh":"在沒有輔助下背誦故事，指不用筆記、書本或工具而憑記憶講出故事。"},{"en":"A student recites without assistance when she performs a poem without looking at the page.","zh":"學生不看頁面表演詩歌時，就是在沒有輔助下背誦。"},{"en":"If a storyteller can recite without help, memory has replaced written storage.","zh":"如果講故事者可以無輔助背誦，記憶就取代了書面儲存。"},{"en":"The phrase highlights independent recall.","zh":"這個短語突出獨立回憶能力。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":17},{"front":"make story characters appealing","meaning":"令故事人物吸引","examples":[{"en":"Homer showed how to make story characters appealing.","zh":"荷馬展示如何令故事人物吸引。"},{"en":"To make story characters appealing means to create characters that audiences like, understand or care about.","zh":"“Make story characters appealing” 指創造令觀眾喜歡、理解或在乎的人物。"},{"en":"A writer can make characters appealing by giving them goals, fears and weaknesses.","zh":"作家可以透過給人物目標、恐懼和弱點令他們吸引。"},{"en":"If characters are appealing, readers continue because they want to know what happens to them.","zh":"如果人物吸引，讀者會繼續閱讀，因為想知道他們會發生甚麼。"},{"en":"The phrase focuses on making fictional people attractive to an audience.","zh":"這個短語強調令虛構人物對觀眾有吸引力。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":17},{"front":"classify each group according to","meaning":"按照……為每組分類","examples":[{"en":"Students classify each group according to its storytelling method.","zh":"學生按照每組的講故事方法為其分類。"},{"en":"To classify each group according to something means to sort groups based on that feature.","zh":"“Classify each group according to” 某特徵指根據該特徵把各組分類。"},{"en":"A teacher may classify students according to reading level so they receive suitable books.","zh":"老師可能按照閱讀程度為學生分類，使他們得到合適書本。"},{"en":"If groups use different storytelling methods, classification helps compare them clearly.","zh":"如果不同群體使用不同講故事方法，分類有助清楚比較。"},{"en":"The phrase describes sorting by a chosen standard.","zh":"這個短語描述按選定標準分類。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":17},{"front":"adopt a writing system","meaning":"採用文字系統","examples":[{"en":"The Greeks adopted a writing system from another country.","zh":"希臘人從另一個國家採用文字系統。"},{"en":"To adopt a writing system means to start using a set of symbols for recording language.","zh":"“Adopt a writing system” 指開始使用一套符號來記錄語言。"},{"en":"A community may adopt a writing system so its stories, laws and songs can be preserved.","zh":"社群可能採用文字系統，使其故事、法律和歌曲能被保存。"},{"en":"If people adopt a writing system from neighbours, cultural contact shapes literacy.","zh":"如果人們從鄰人那裡採用文字系統，文化接觸就塑造讀寫能力。"},{"en":"The phrase describes taking up a method of writing.","zh":"這個短語描述採納書寫方法。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":17},{"front":"organic materials","meaning":"有機材料","examples":[{"en":"Some groups used organic materials to record stories.","zh":"一些群體使用有機材料記錄故事。"},{"en":"Organic materials are natural materials from plants or animals.","zh":"有機材料是來自植物或動物的天然材料。"},{"en":"Paper, bark, leather and cloth are organic materials that can carry writing or marks.","zh":"紙、樹皮、皮革和布都是可以承載文字或記號的有機材料。"},{"en":"If stories are written on organic materials, they may be portable but also fragile.","zh":"如果故事寫在有機材料上，它們可能容易攜帶，但也較脆弱。"},{"en":"The phrase contrasts natural materials with stone, metal or digital storage.","zh":"這個短語把天然材料與石、金屬或數碼儲存作對比。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":17},{"front":"record stories","meaning":"記錄故事","examples":[{"en":"The Ojibway used birch-bark scrolls to record stories.","zh":"奧吉布瓦人使用樺樹皮卷軸記錄故事。"},{"en":"To record stories means to preserve them in writing, symbols, images or sound.","zh":"“Record stories” 指用文字、符號、圖像或聲音保存故事。"},{"en":"A family may record stories by interviewing older relatives and saving the audio.","zh":"家庭可能透過訪問年長親人並保存錄音來記錄故事。"},{"en":"If stories are recorded, they can survive even after the original storyteller is gone.","zh":"如果故事被記錄，即使原本講故事的人離世，它們仍能保存。"},{"en":"The phrase describes preserving narratives for later use.","zh":"這個短語描述為日後使用而保存敘事。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":17},{"front":"tools to assist in","meaning":"協助……的工具","examples":[{"en":"Polynesians used tools to assist in telling stories.","zh":"波利尼西亞人使用協助講故事的工具。"},{"en":"Tools to assist in something are objects or methods that help people do a task more easily.","zh":"協助某事的工具，是幫助人更容易完成任務的物件或方法。"},{"en":"Flashcards are tools to assist in remembering vocabulary.","zh":"單詞卡是協助記住詞彙的工具。"},{"en":"If storytellers use tools to assist memory, long recitations become more manageable.","zh":"如果講故事者使用協助記憶的工具，長篇背誦就變得較容易處理。"},{"en":"The phrase focuses on practical support for an activity.","zh":"這個短語強調活動中的實際支援。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":17},{"front":"complete the sentences below","meaning":"完成以下句子","examples":[{"en":"Students complete the sentences below with one word from the passage.","zh":"學生用文章中的一個詞完成以下句子。"},{"en":"Complete the sentences below means fill in the missing words in the sentences that follow the instruction.","zh":"“Complete the sentences below” 指填寫指示後方句子的缺漏詞語。"},{"en":"Students should read the whole sentence before choosing a word from the passage.","zh":"學生應先讀完整句，再從文章選詞。"},{"en":"If the grammar before the blank requires a noun, that clue can guide the answer.","zh":"如果空格前的文法需要名詞，該線索可以引導答案。"},{"en":"The phrase is a common reading-test instruction.","zh":"這個短語是常見閱讀測驗指示。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":17},{"front":"one word only","meaning":"只用一個詞","examples":[{"en":"Each answer should contain one word only.","zh":"每個答案只應包含一個詞。"},{"en":"One word only means the answer must be exactly one word, not a phrase.","zh":"“One word only” 指答案必須正正是一個詞，而不是短語。"},{"en":"If the answer is “tragedy,” writing “Greek tragedy” would break a one-word-only rule.","zh":"如果答案是 “tragedy”，寫 “Greek tragedy” 就違反只用一詞的規則。"},{"en":"Students should copy the word carefully because extra words can make the answer wrong.","zh":"學生應仔細抄寫該詞，因為額外詞語可以令答案錯誤。"},{"en":"The phrase gives a strict exam word limit.","zh":"這個短語給出嚴格考試字數限制。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":17},{"front":"art of storytelling","meaning":"講故事的藝術","examples":[{"en":"Aristotle wrote about the art of storytelling.","zh":"亞里士多德寫過關於講故事的藝術。"},{"en":"The art of storytelling is the skill of shaping a story so it captures attention and emotion.","zh":"講故事的藝術，是塑造故事以捕捉注意力和情感的技巧。"},{"en":"A teacher uses the art of storytelling when turning a dry fact into a memorable example.","zh":"老師把枯燥事實變成令人記得的例子時，就是在使用講故事的藝術。"},{"en":"If the art of storytelling is strong, even an old story can feel fresh.","zh":"如果講故事的藝術強，即使舊故事也可以感覺新鮮。"},{"en":"The phrase treats storytelling as a craft that can be studied and improved.","zh":"這個短語把講故事視為可以研究和改善的工藝。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":18},{"front":"powerful type of story","meaning":"有感染力的故事類型","examples":[{"en":"Aristotle thought tragedy was a powerful type of story.","zh":"亞里士多德認為悲劇是一種有感染力的故事類型。"},{"en":"A powerful type of story is a story form that strongly affects people’s thoughts or emotions.","zh":"有感染力的故事類型，是能強烈影響人們思想或情緒的故事形式。"},{"en":"A survival story can be powerful because it makes readers think about fear and courage.","zh":"生存故事可以很有感染力，因為它令人思考恐懼和勇氣。"},{"en":"If tragedy is powerful, it can move audiences through sadness and recognition.","zh":"如果悲劇有感染力，它可以透過悲傷和認同打動觀眾。"},{"en":"The phrase describes a story category with strong impact.","zh":"這個短語描述具有強大影響力的故事類別。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":18},{"front":"moving an audience","meaning":"打動觀眾","examples":[{"en":"Tragedy was powerful for moving an audience.","zh":"悲劇因能打動觀眾而有力量。"},{"en":"Moving an audience means making viewers or listeners feel strong emotions.","zh":"打動觀眾指令觀看者或聆聽者產生強烈情緒。"},{"en":"A graduation speech may move an audience by recalling students’ struggles and growth.","zh":"畢業演講可能透過回顧學生的掙扎和成長來打動觀眾。"},{"en":"If a story moves an audience, people may leave feeling changed or thoughtful.","zh":"如果故事打動觀眾，人們離開時可能感覺被改變或有所思考。"},{"en":"The phrase focuses on emotional effect.","zh":"這個短語強調情感效果。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":18},{"front":"view something as","meaning":"把……視為","examples":[{"en":"Aristotle viewed Homer’s works as literary landmarks.","zh":"亞里士多德把荷馬作品視為文學里程碑。"},{"en":"To view something as something means to regard or consider it in that way.","zh":"“View something as” 某物指以某種方式看待或認為它。"},{"en":"A teacher may view mistakes as useful evidence of what students need to practise.","zh":"老師可能把錯誤視為學生需要練習甚麼的有用證據。"},{"en":"If a work is viewed as a landmark, people treat it as especially important.","zh":"如果作品被視為里程碑，人們就會把它看得特別重要。"},{"en":"The phrase describes judgement or interpretation.","zh":"這個短語描述判斷或詮釋。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":18},{"front":"appealing heroes","meaning":"吸引人的英雄","examples":[{"en":"Aristotle believed appealing heroes should have human weaknesses.","zh":"亞里士多德認為吸引人的英雄應有人性弱點。"},{"en":"Appealing heroes are heroes that audiences like, understand and care about.","zh":"吸引人的英雄是觀眾喜歡、理解並在乎的英雄。"},{"en":"A brave firefighter who also fears failure can be an appealing hero.","zh":"一位勇敢但也害怕失敗的消防員，可以是吸引人的英雄。"},{"en":"If heroes have human weaknesses, they may become more appealing because they feel real.","zh":"如果英雄有人性弱點，他們可能變得更吸引，因為感覺真實。"},{"en":"The phrase describes heroes who attract emotional interest.","zh":"這個短語描述能吸引情感興趣的英雄。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":18},{"front":"have some weakness","meaning":"有一些弱點","examples":[{"en":"An appealing hero should have some weakness.","zh":"吸引人的英雄應有一些弱點。"},{"en":"To have some weakness means to have an imperfection, fear or limitation.","zh":"“Have some weakness” 指有不完美、恐懼或限制。"},{"en":"A confident student may still have some weakness in listening or pronunciation.","zh":"自信的學生仍可能在聆聽或發音上有一些弱點。"},{"en":"If a hero has some weakness, the story can show struggle, choice and growth.","zh":"如果英雄有一些弱點，故事就能展示掙扎、選擇和成長。"},{"en":"The phrase makes a character more believable than a perfect figure.","zh":"這個短語令角色比完美人物更可信。"}],"source":"37 - Storytelling, From Prehistoric Craves To Modern Cinemas.pdf","sourcePage":18}],"ielts/reading/passage-2/Practice 38":[{"front":"the Tasmanian tiger","meaning":"塔斯曼尼亞虎","examples":[{"en":"The Tasmanian tiger looked like a dog with black stripes on its back.","zh":"塔斯曼尼亞虎看起來像一隻背上有黑色條紋的狗。"},{"en":"The Tasmanian tiger was a meat-eating marsupial from Tasmania that is believed to be extinct.","zh":"Tasmanian tiger 是一種來自塔斯曼尼亞、被認為已經滅絕的肉食性有袋動物。"},{"en":"A museum display may show the Tasmanian tiger beside wolves and dogs to explain how similar it looked.","zh":"博物館展覽可能把塔斯曼尼亞虎放在狼和狗旁邊展示，以解釋牠外貌有多相似。"},{"en":"Because the Tasmanian tiger disappeared recently, many people still hope it may have survived somewhere.","zh":"因為塔斯曼尼亞虎是近代才消失的，許多人仍希望牠可能在某處存活。"},{"en":"This name is common, but the animal is also known scientifically as the thylacine.","zh":"這個名稱很常見，但這種動物的學名也叫 thylacine。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":1},{"front":"black stripes on its back","meaning":"背上的黑色條紋","examples":[{"en":"The Tasmanian tiger had black stripes on its back.","zh":"塔斯曼尼亞虎背上有黑色條紋。"},{"en":"Black stripes on its back means dark lines running across the animal’s back.","zh":"black stripes on its back 指動物背部上的深色線條。"},{"en":"A child drawing a zebra may add black stripes on its back and sides.","zh":"孩子畫斑馬時，可能會在牠背部和身側加上黑色條紋。"},{"en":"These stripes helped make the Tasmanian tiger look different from an ordinary dog.","zh":"這些條紋令塔斯曼尼亞虎看起來不同於普通狗。"},{"en":"This phrase describes a visible marking on an animal’s body.","zh":"這個片語描述動物身體上的可見標記。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":1},{"front":"largest known carnivorous marsupial","meaning":"已知最大的肉食性有袋動物","examples":[{"en":"The thylacine was the largest known carnivorous marsupial of modern times.","zh":"袋狼是近代已知最大的肉食性有袋動物。"},{"en":"The largest known carnivorous marsupial means the biggest recorded meat-eating animal that carried young in a pouch.","zh":"largest known carnivorous marsupial 指有記錄中最大的、吃肉並用育兒袋養育幼崽的動物。"},{"en":"A science teacher may compare the thylacine with kangaroos to show that both were marsupials, though one ate meat.","zh":"科學老師可能把袋狼與袋鼠比較，以顯示兩者都是有袋動物，只是其中一種吃肉。"},{"en":"Because it was large and carnivorous, the thylacine attracted strong interest from zoologists.","zh":"因為牠體型大且吃肉，袋狼引起動物學家的強烈興趣。"},{"en":"This phrase describes both the animal’s size, diet, and biological group.","zh":"這個片語同時描述動物的體型、食性和生物分類。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":1},{"front":"modern times","meaning":"近代","examples":[{"en":"The thylacine was the largest known carnivorous marsupial of modern times.","zh":"袋狼是近代已知最大的肉食性有袋動物。"},{"en":"Modern times means the recent historical period, especially compared with ancient or prehistoric times.","zh":"modern times 指較近的歷史時期，尤其是與古代或史前時代相比。"},{"en":"In modern times, people can record animal sightings with phones and digital cameras.","zh":"在近代，人們可以用手機和數碼相機記錄動物目擊。"},{"en":"If an animal disappeared in modern times, there may still be photographs, films, and written records of it.","zh":"如果一種動物在近代消失，可能仍有照片、影片和文字記錄。"},{"en":"This phrase contrasts recent history with the distant past.","zh":"這個片語把較近歷史與遙遠過去作對比。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":1},{"front":"despite its fame for","meaning":"儘管因……而聞名","examples":[{"en":"Despite its fame for being fabled, the animal is still poorly understood.","zh":"儘管這種動物因富有傳奇色彩而聞名，人們仍然很不了解牠。"},{"en":"Despite its fame for something means although it is well known for that reason.","zh":"despite its fame for something 指雖然某物因某原因而廣為人知。"},{"en":"Despite its fame for luxury shopping, a city may also have many poor neighbourhoods.","zh":"儘管一個城市因奢華購物而聞名，它也可能有許多貧困社區。"},{"en":"If an animal is famous but rarely studied alive, people may still understand it poorly.","zh":"如果一種動物很有名但很少被活體研究，人們仍可能很不了解牠。"},{"en":"This phrase introduces a contrast between reputation and reality.","zh":"這個片語引入名聲與現實之間的對比。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":1},{"front":"one of the most fabled animals","meaning":"最具傳奇色彩的動物之一","examples":[{"en":"The Tasmanian tiger is one of the most fabled animals in the world.","zh":"塔斯曼尼亞虎是世界上最具傳奇色彩的動物之一。"},{"en":"One of the most fabled animals means an animal surrounded by many stories, mystery, and legend.","zh":"one of the most fabled animals 指被許多故事、神秘感和傳說圍繞的動物之一。"},{"en":"The Loch Ness monster is often treated as a fabled creature because many stories surround it.","zh":"尼斯湖水怪常被視為傳奇生物，因為圍繞它有許多故事。"},{"en":"If an animal is fabled, reported sightings may continue even after scientists call it extinct.","zh":"如果一種動物具傳奇色彩，即使科學家稱牠已滅絕，目擊報告仍可能繼續出現。"},{"en":"This phrase suggests that the animal lives strongly in public imagination.","zh":"這個片語暗示該動物在人們想像中仍非常鮮活。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":1},{"front":"least understood","meaning":"最少被了解的","examples":[{"en":"It is one of the least understood of Tasmania’s native animals.","zh":"牠是塔斯曼尼亞本地動物中最少被了解的之一。"},{"en":"Least understood means known or explained less well than most others.","zh":"least understood 指相比大多數其他事物，較少被認識或解釋清楚。"},{"en":"A rare disease may be one of the least understood conditions if doctors have little data about it.","zh":"如果醫生對某種罕見疾病資料很少，它可能是最少被了解的病症之一。"},{"en":"If an animal becomes extinct before scientists study it properly, many details remain unknown.","zh":"如果動物在科學家充分研究前已滅絕，許多細節便仍然未知。"},{"en":"This phrase highlights a lack of knowledge.","zh":"這個片語突出知識上的不足。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":1},{"front":"native animals","meaning":"本地動物","examples":[{"en":"The thylacine was one of Tasmania’s native animals.","zh":"袋狼是塔斯曼尼亞的本地動物之一。"},{"en":"Native animals are animals that naturally belong to a particular place.","zh":"native animals 是自然屬於某個地方的動物。"},{"en":"Koalas are native animals of Australia, while pandas are native animals of China.","zh":"樹熊是澳洲的本地動物，而熊貓是中國的本地動物。"},{"en":"If native animals lose habitat, the local ecosystem may change.","zh":"如果本地動物失去棲息地，本地生態系統可能改變。"},{"en":"This phrase contrasts local species with introduced species.","zh":"這個片語把本地物種與外來物種作對比。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":1},{"front":"scientific name","meaning":"學名","examples":[{"en":"The scientific name for the Tasmanian tiger is thylacine.","zh":"塔斯曼尼亞虎的學名是 thylacine。"},{"en":"A scientific name is the formal name used by scientists to identify a species accurately.","zh":"scientific name 是科學家用來準確識別物種的正式名稱。"},{"en":"A biology textbook may use scientific names so students do not confuse similar animals.","zh":"生物教科書可能使用學名，以免學生混淆相似動物。"},{"en":"If an animal has many common names, its scientific name avoids misunderstanding.","zh":"如果一種動物有許多俗名，其學名可以避免誤解。"},{"en":"This phrase refers to a precise name used in science.","zh":"這個片語指科學中使用的精確名稱。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":1},{"front":"believed to have become extinct","meaning":"被認為已經滅絕","examples":[{"en":"The thylacine is believed to have become extinct in the 20th century.","zh":"袋狼被認為已在20世紀滅絕。"},{"en":"Believed to have become extinct means people think the species has died out, though uncertainty may remain.","zh":"believed to have become extinct 指人們認為該物種已經消失，雖然仍可能有不確定性。"},{"en":"A plant may be believed to have become extinct if no one has found it for many decades.","zh":"如果某植物數十年無人發現，它可能被認為已經滅絕。"},{"en":"If an animal is believed extinct, conservationists may still investigate credible sightings.","zh":"如果動物被認為已滅絕，保育人士仍可能調查可信目擊報告。"},{"en":"This phrase shows a widely accepted belief rather than direct proof in every case.","zh":"這個片語顯示廣泛接受的看法，而不一定每個情況都有直接證明。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":1},{"front":"become extinct","meaning":"滅絕","examples":[{"en":"The thylacine became extinct in the 20th century.","zh":"袋狼在20世紀滅絕。"},{"en":"To become extinct means a species dies out completely, with no living members left.","zh":"become extinct 指一個物種完全消失，沒有任何活着的成員。"},{"en":"Dinosaurs became extinct long before humans appeared.","zh":"恐龍在人類出現很久以前已經滅絕。"},{"en":"Habitat loss, hunting, and disease can cause a species to become extinct.","zh":"棲息地喪失、狩獵和疾病都可能導致物種滅絕。"},{"en":"This phrase describes the final disappearance of a species.","zh":"這個片語描述物種的最終消失。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":1},{"front":"fossils of","meaning":"……的化石","examples":[{"en":"Fossils of thylacines have been found in several parts of Australia.","zh":"袋狼的化石已在澳洲幾個地區被發現。"},{"en":"Fossils of something are preserved remains or traces of that organism from the past.","zh":"fossils of something 是某種生物過去留下並被保存的遺骸或痕跡。"},{"en":"Fossils of fish can show that a dry area was once covered by water.","zh":"魚的化石可以顯示乾旱地區曾經被水覆蓋。"},{"en":"If fossils of an animal are found in many places, scientists can infer it was once widespread.","zh":"如果某動物的化石在許多地方被發現，科學家可以推斷牠曾廣泛分布。"},{"en":"This phrase refers to physical evidence of ancient life.","zh":"這個片語指古代生命的實體證據。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":2},{"front":"dating from","meaning":"可追溯至……","examples":[{"en":"Fossils dating from about 12 million years ago have been dug up.","zh":"可追溯至約一千二百萬年前的化石已被挖掘出來。"},{"en":"Dating from means coming from or belonging to a particular time in the past.","zh":"dating from 指來自或屬於過去某個特定時間。"},{"en":"A coin dating from the Qing dynasty may be valuable to historians.","zh":"一枚可追溯至清朝的硬幣，對歷史學家可能很有價值。"},{"en":"If fossils date from millions of years ago, they show that the species has a long history.","zh":"如果化石可追溯至數百萬年前，它們顯示該物種歷史悠久。"},{"en":"This phrase is used to identify the age or period of an object.","zh":"這個片語用來指出物件的年代或時期。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":2},{"front":"dug up","meaning":"被挖掘出來","examples":[{"en":"Fossils of thylacines have been dug up in Victoria and other states.","zh":"袋狼化石已在維多利亞州和其他州被挖掘出來。"},{"en":"Dug up means found and removed from the ground by digging.","zh":"dug up 指透過挖掘從地下找到並取出。"},{"en":"Workers dug up old pipes while repairing the road.","zh":"工人修路時挖出了舊水管。"},{"en":"If archaeologists dig up bones carefully, they can preserve important evidence.","zh":"如果考古學家小心挖出骨骼，就能保存重要證據。"},{"en":"This phrase describes discovering something buried underground.","zh":"這個片語描述發現埋在地下的東西。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":2},{"front":"various places","meaning":"多個地方","examples":[{"en":"Thylacine fossils have been dug up at various places in Australia.","zh":"袋狼化石已在澳洲多個地方被挖掘出來。"},{"en":"Various places means several different locations.","zh":"various places 指幾個不同地點。"},{"en":"A school trip may take students to various places, such as a museum, a park, and a library.","zh":"學校旅行可能帶學生到多個地方，例如博物館、公園和圖書館。"},{"en":"If evidence appears in various places, the pattern becomes more convincing.","zh":"如果證據出現在多個地方，該模式會更有說服力。"},{"en":"This phrase shows that something is not limited to one location.","zh":"這個片語顯示某事不限於一個地點。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":2},{"front":"Victoria","meaning":"維多利亞州","examples":[{"en":"Fossils of thylacines have been found in Victoria.","zh":"袋狼化石已在維多利亞州被發現。"},{"en":"Victoria is a state in south-eastern Australia.","zh":"Victoria 是澳洲東南部的一個州。"},{"en":"A tourist visiting Victoria may go to Melbourne, beaches, and national parks.","zh":"到訪維多利亞州的遊客可能去墨爾本、海灘和國家公園。"},{"en":"If thylacine fossils are found in Victoria, the animal once lived beyond Tasmania.","zh":"如果袋狼化石在維多利亞州被發現，這種動物曾生活在塔斯曼尼亞以外。"},{"en":"This word names a specific Australian state.","zh":"這個詞指出澳洲一個特定州份。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":2},{"front":"South Australia","meaning":"南澳州","examples":[{"en":"Thylacine fossils have been discovered in South Australia.","zh":"袋狼化石已在南澳州被發現。"},{"en":"South Australia is an Australian state known for dry regions, coastlines, and Adelaide.","zh":"South Australia 是澳洲的一個州，以乾旱地區、海岸線和阿德萊德聞名。"},{"en":"A family travelling through South Australia may see deserts, vineyards, and beaches.","zh":"穿越南澳州旅行的家庭可能看到沙漠、葡萄園和海灘。"},{"en":"Fossils in South Australia help show that thylacines once had a wide mainland range.","zh":"南澳州的化石有助顯示袋狼曾在澳洲大陸廣泛分布。"},{"en":"This phrase names another Australian state where evidence was found.","zh":"這個片語指出另一個發現證據的澳洲州份。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":2},{"front":"Western Australia","meaning":"西澳州","examples":[{"en":"Thylacine fossils have been dug up in Western Australia.","zh":"袋狼化石已在西澳州被挖掘出來。"},{"en":"Western Australia is Australia’s largest state, covering much of the country’s west.","zh":"Western Australia 是澳洲面積最大的州，覆蓋該國西部大部分地區。"},{"en":"A mining company in Western Australia may work in very remote areas.","zh":"西澳州的礦業公司可能在非常偏遠地區工作。"},{"en":"If fossils are found as far west as Western Australia, the species’ past range was broad.","zh":"如果化石遠至西澳州也被發現，該物種過去的分布範圍很廣。"},{"en":"This phrase names a large Australian state in the west.","zh":"這個片語指出澳洲西部的大型州份。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":2},{"front":"widespread in","meaning":"廣泛分布於……","examples":[{"en":"Thylacines were widespread in Australia 7,000 years ago.","zh":"袋狼在七千年前廣泛分布於澳洲。"},{"en":"Widespread in a place means found across many parts of that place.","zh":"widespread in a place 指在某地許多部分都可見。"},{"en":"Smartphones are widespread in many cities because they are used for payment, transport, and communication.","zh":"智能手機在許多城市廣泛普及，因為它們用於付款、交通和溝通。"},{"en":"If an animal is widespread, it probably survives in different habitats.","zh":"如果動物廣泛分布，它很可能能在不同棲息地生存。"},{"en":"This phrase describes broad distribution.","zh":"這個片語描述廣闊分布。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":2},{"front":"extinct on the continent","meaning":"在大陸上滅絕","examples":[{"en":"Thylacines have probably been extinct on the continent for 2,000 years.","zh":"袋狼很可能已在大陸上滅絕二千年。"},{"en":"Extinct on the continent means no longer living on the mainland, even if it may have survived elsewhere.","zh":"extinct on the continent 指在大陸上不再存在，即使可能在其他地方仍存活。"},{"en":"An animal may disappear from a continent but remain on nearby islands.","zh":"一種動物可能從大陸消失，但仍留存在附近島嶼。"},{"en":"If thylacines were extinct on the continent, mainland Australia no longer had living populations.","zh":"如果袋狼在大陸上滅絕，澳洲大陸便不再有活着的種群。"},{"en":"This phrase separates mainland extinction from total species extinction.","zh":"這個片語區分大陸滅絕與整個物種滅絕。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":2},{"front":"introduction of dingoes","meaning":"野狗的引入","examples":[{"en":"Their disappearance may be linked to the introduction of dingoes.","zh":"袋狼的消失可能與野狗的引入有關。"},{"en":"The introduction of dingoes means dingoes were brought or arrived into an area where they had not lived before.","zh":"introduction of dingoes 指澳洲野狗被帶入或進入以前未生活的地區。"},{"en":"The introduction of a new predator can change the balance of an ecosystem.","zh":"新掠食者的引入可以改變生態系統平衡。"},{"en":"If dingoes competed with thylacines for food, their arrival may have helped cause decline.","zh":"如果野狗與袋狼競爭食物，牠們的到來可能促成袋狼下降。"},{"en":"This phrase describes a new species entering a region.","zh":"這個片語描述新物種進入某地區。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":2},{"front":"dingoes","meaning":"澳洲野狗","examples":[{"en":"Dingoes were introduced to Australia around 8,000 years ago.","zh":"澳洲野狗約在八千年前被引入澳洲。"},{"en":"Dingoes are wild dogs found in Australia.","zh":"dingoes 是澳洲的野生犬類。"},{"en":"A farmer may worry about dingoes attacking sheep or young livestock.","zh":"農民可能擔心澳洲野狗攻擊綿羊或幼小牲畜。"},{"en":"If dingoes compete with native predators, they can affect local animal populations.","zh":"如果澳洲野狗與本地掠食者競爭，牠們可以影響本地動物數量。"},{"en":"This word refers to Australia’s wild dog.","zh":"這個詞指澳洲的野生犬。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":2},{"front":"because of disease","meaning":"由於疾病","examples":[{"en":"Because of disease, thylacine numbers may have been declining in Tasmania.","zh":"由於疾病，塔斯曼尼亞的袋狼數量可能一直下降。"},{"en":"Because of disease means illness may be the reason for something happening.","zh":"because of disease 指疾病可能是某事發生的原因。"},{"en":"A school may close for several days because of disease spreading among students.","zh":"由於疾病在學生之間傳播，學校可能停課幾天。"},{"en":"If many animals catch a disease, their population may fall quickly.","zh":"如果許多動物感染疾病，其數量可能迅速下降。"},{"en":"This phrase introduces illness as a cause.","zh":"這個片語引入疾病作為原因。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":3},{"front":"thylacine numbers","meaning":"袋狼數量","examples":[{"en":"Thylacine numbers may have been declining before European settlement.","zh":"在歐洲人定居前，袋狼數量可能已經下降。"},{"en":"Thylacine numbers means the size of the thylacine population.","zh":"thylacine numbers 指袋狼種群的數量。"},{"en":"Conservationists track animal numbers to see whether a species is recovering or disappearing.","zh":"保育人士追蹤動物數量，以了解物種正在恢復還是消失。"},{"en":"If thylacine numbers were already falling, later hunting or settlement could make the decline worse.","zh":"如果袋狼數量已經下降，後來的狩獵或定居可能令下降更嚴重。"},{"en":"This phrase refers to how many thylacines existed.","zh":"這個片語指有多少袋狼存在。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":3},{"front":"declining in Tasmania","meaning":"在塔斯曼尼亞下降","examples":[{"en":"Thylacine numbers may have been declining in Tasmania.","zh":"袋狼數量可能在塔斯曼尼亞下降。"},{"en":"Declining in Tasmania means becoming fewer within Tasmania.","zh":"declining in Tasmania 指在塔斯曼尼亞境內變得越來越少。"},{"en":"If bird numbers are declining in a city, there may be fewer trees, insects, or nesting places.","zh":"如果城市中的鳥類數量下降，可能是因為樹木、昆蟲或築巢地減少。"},{"en":"A population declining in one region may still survive in another, but it becomes more vulnerable locally.","zh":"一個種群在某地區下降，可能仍在其他地方生存，但在當地會更脆弱。"},{"en":"This phrase describes a regional fall in numbers.","zh":"這個片語描述某地區內數量下降。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":3},{"front":"European settlement","meaning":"歐洲人定居","examples":[{"en":"The decline was accelerated around the time of European settlement.","zh":"這種下降在歐洲人定居前後加速。"},{"en":"European settlement means the arrival and establishment of European communities in a place.","zh":"European settlement 指歐洲社群到達並在某地建立定居點。"},{"en":"European settlement changed many landscapes through farming, towns, roads, and hunting.","zh":"歐洲人定居透過農業、城鎮、道路和狩獵改變許多景觀。"},{"en":"If settlement brings new animals, diseases, or hunting pressure, native species may decline.","zh":"如果定居帶來新動物、疾病或狩獵壓力，本地物種可能下降。"},{"en":"This phrase refers to a historical process of colonisation and permanent residence.","zh":"這個片語指殖民和永久居住的歷史過程。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":3},{"front":"accelerated by","meaning":"由……加速","examples":[{"en":"The decline was certainly accelerated by the new arrivals.","zh":"這種下降肯定由新來者加速。"},{"en":"Accelerated by means made faster by something.","zh":"accelerated by 指由某事令過程變得更快。"},{"en":"A student’s progress may be accelerated by daily practice and clear feedback.","zh":"學生的進步可能由每日練習和清晰回饋加速。"},{"en":"If hunting increased after settlers arrived, the animal’s decline could be accelerated.","zh":"如果定居者到來後狩獵增加，動物下降可能被加速。"},{"en":"This phrase shows what caused a process to speed up.","zh":"這個片語顯示甚麼令某個過程加快。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":3},{"front":"the new arrivals","meaning":"新來者","examples":[{"en":"The new arrivals accelerated the decline of thylacines.","zh":"新來者加速了袋狼的下降。"},{"en":"The new arrivals means people or animals that have recently come to a place.","zh":"new arrivals 指最近來到某地的人或動物。"},{"en":"In a classroom, new arrivals may need help understanding rules and routines.","zh":"在課室中，新來者可能需要幫助理解規則和日常安排。"},{"en":"If new arrivals bring hunting, farms, or disease, native animals may be affected.","zh":"如果新來者帶來狩獵、農場或疾病，本地動物可能受影響。"},{"en":"This phrase identifies newcomers in a particular setting.","zh":"這個片語指出特定環境中的新來者。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":3},{"front":"last known","meaning":"最後一隻已知的","examples":[{"en":"The last known Tasmanian tiger died in Hobart Zoo in 1936.","zh":"最後一隻已知的塔斯曼尼亞虎於1936年死於荷伯特動物園。"},{"en":"Last known means the final one that people have officially recorded or confirmed.","zh":"last known 指人們正式記錄或確認的最後一個。"},{"en":"The last known copy of an old photograph may be kept in a museum archive.","zh":"一張舊照片的最後一份已知副本可能被保存在博物館檔案中。"},{"en":"If the last known animal dies, scientists may classify the species as extinct later.","zh":"如果最後一隻已知動物死亡，科學家之後可能把該物種歸類為滅絕。"},{"en":"This phrase leaves room for uncertainty because unknown individuals may still have existed.","zh":"這個片語保留不確定性，因為未知個體可能仍曾存在。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":3},{"front":"Hobart Zoo","meaning":"荷伯特動物園","examples":[{"en":"The last known Tasmanian tiger died in Hobart Zoo.","zh":"最後一隻已知塔斯曼尼亞虎死於荷伯特動物園。"},{"en":"Hobart Zoo was a zoo in Hobart, Tasmania, where the last known thylacine was kept.","zh":"Hobart Zoo 是位於塔斯曼尼亞荷伯特的動物園，最後一隻已知袋狼曾被圈養在那裡。"},{"en":"A visitor to Hobart may learn about the old zoo through local history displays.","zh":"到訪荷伯特的人可能透過本地歷史展覽了解舊動物園。"},{"en":"Because the last known thylacine died there, Hobart Zoo became central to the animal’s story.","zh":"因為最後一隻已知袋狼死於那裡，荷伯特動物園成為牠故事中的核心地點。"},{"en":"This phrase names the place linked to the final confirmed captive thylacine.","zh":"這個片語指出與最後一隻經確認圈養袋狼相關的地方。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":3},{"front":"officially classified as","meaning":"被正式歸類為……","examples":[{"en":"The animal is officially classified as extinct.","zh":"這種動物被正式歸類為滅絕。"},{"en":"Officially classified as means formally placed into a category by an authority or recognised system.","zh":"officially classified as 指由權威機構或認可系統正式放入某一類別。"},{"en":"A building may be officially classified as unsafe after engineers inspect it.","zh":"工程師檢查後，一座建築物可能被正式歸類為不安全。"},{"en":"If an animal is officially classified as extinct, conservation agencies treat it as no longer surviving.","zh":"如果動物被正式歸類為滅絕，保育機構會把牠視為不再存活。"},{"en":"This phrase describes formal recognition, not just public opinion.","zh":"這個片語描述正式認定，而不是只指公眾看法。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":3},{"front":"technically","meaning":"嚴格來說","examples":[{"en":"Technically, extinction means there has been no official sighting for 50 years.","zh":"嚴格來說，滅絕意味已經50年沒有正式目擊紀錄。"},{"en":"Technically means according to the exact rule, definition, or official meaning.","zh":"technically 指根據確切規則、定義或官方意思。"},{"en":"Technically, a student is late if they arrive one minute after the bell.","zh":"嚴格來說，如果學生在鐘聲後一分鐘到達，就是遲到。"},{"en":"If people speak technically, they may focus on strict definitions rather than everyday impressions.","zh":"如果人們嚴格來說地表達，他們可能聚焦於嚴格定義，而不是日常印象。"},{"en":"This word introduces a precise or rule-based explanation.","zh":"這個詞引入精確或基於規則的解釋。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":3},{"front":"officially sighted","meaning":"被正式目擊","examples":[{"en":"The animal has not been officially sighted for 50 years.","zh":"這種動物已有50年沒有被正式目擊。"},{"en":"Officially sighted means seen and recorded in a way accepted by authorities or experts.","zh":"officially sighted 指以受當局或專家接受的方式被看見和記錄。"},{"en":"A rare bird may be officially sighted when trained observers photograph and report it.","zh":"當受訓觀察者拍照並報告時，罕見鳥類可能被正式目擊。"},{"en":"If an animal is not officially sighted for decades, scientists may doubt that it still exists.","zh":"如果動物數十年沒有被正式目擊，科學家可能懷疑牠是否仍存在。"},{"en":"This phrase separates confirmed sightings from rumours.","zh":"這個片語把確認目擊與傳聞區分開來。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":3},{"front":"in the wild","meaning":"在野外","examples":[{"en":"The thylacine has not been officially sighted in the wild for decades.","zh":"袋狼已有數十年沒有在野外被正式目擊。"},{"en":"In the wild means living freely in nature, not kept by humans.","zh":"in the wild 指在自然環境中自由生活，而不是由人類圈養。"},{"en":"A tiger in the wild must hunt, avoid danger, and find shelter by itself.","zh":"野外老虎必須自己狩獵、避開危險和尋找庇護。"},{"en":"If an animal survives in the wild, it may be very hard to observe directly.","zh":"如果動物在野外存活，直接觀察牠可能非常困難。"},{"en":"This phrase contrasts natural living with captivity.","zh":"這個片語把自然生活與圈養作對比。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":4},{"front":"in captivity","meaning":"在圈養環境中","examples":[{"en":"The thylacine has not been seen in captivity for 50 years.","zh":"袋狼已有50年沒有在圈養環境中被看見。"},{"en":"In captivity means kept by humans in a zoo, enclosure, or controlled environment.","zh":"in captivity 指由人類飼養在動物園、圍欄或受控制環境中。"},{"en":"A panda in captivity may receive regular food, medical care, and protection.","zh":"圈養中的熊貓可能得到定期食物、醫療照顧和保護。"},{"en":"If no animal remains in captivity, researchers cannot easily study its behaviour directly.","zh":"如果沒有動物留在圈養環境中，研究人員就難以直接研究其行為。"},{"en":"This phrase contrasts human-controlled conditions with life in the wild.","zh":"這個片語把人類控制的環境與野外生活作對比。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":4},{"front":"unsubstantiated sightings","meaning":"未經證實的目擊報告","examples":[{"en":"There are still unsubstantiated sightings of the thylacine.","zh":"仍然有未經證實的袋狼目擊報告。"},{"en":"Unsubstantiated sightings are reports of seeing something without strong evidence to prove them.","zh":"unsubstantiated sightings 是聲稱看到某物，但沒有有力證據證明的報告。"},{"en":"A person may report an unusual animal in a park, but without photos it remains an unsubstantiated sighting.","zh":"一個人可能報告在公園看到不尋常動物，但沒有照片便仍屬未經證實的目擊。"},{"en":"If sightings are unsubstantiated, scientists usually treat them with caution.","zh":"如果目擊報告未經證實，科學家通常會謹慎看待。"},{"en":"This phrase describes claims that have not been confirmed.","zh":"這個片語描述尚未被確認的聲稱。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":4},{"front":"study of animals","meaning":"動物研究","examples":[{"en":"Hans Naarding’s study of animals had taken him around the world.","zh":"Hans Naarding 的動物研究使他走遍世界。"},{"en":"Study of animals means research into animal behaviour, habitats, bodies, or populations.","zh":"study of animals 指對動物行為、棲息地、身體或種群的研究。"},{"en":"A student interested in the study of animals may visit wetlands, zoos, and museums.","zh":"對動物研究有興趣的學生可能參觀濕地、動物園和博物館。"},{"en":"If someone studies animals professionally, they may become skilled at identifying unusual species.","zh":"如果某人專業研究動物，他可能擅長識別不尋常物種。"},{"en":"This phrase refers to learning about animals through observation and research.","zh":"這個片語指透過觀察和研究了解動物。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":4},{"front":"had taken him around the world","meaning":"使他走遍世界","examples":[{"en":"His study of animals had taken him around the world.","zh":"他的動物研究使他走遍世界。"},{"en":"Had taken him around the world means his work or interest caused him to travel to many countries.","zh":"had taken him around the world 指他的工作或興趣令他到許多國家旅行。"},{"en":"A journalist’s career may take her around the world to report on wars, elections, and disasters.","zh":"記者的職業可能使她走遍世界，報道戰爭、選舉和災難。"},{"en":"If research takes someone around the world, they gain wide experience with different places and species.","zh":"如果研究使某人走遍世界，他會獲得對不同地方和物種的廣泛經驗。"},{"en":"This phrase links a career or activity with extensive travel.","zh":"這個片語把職業或活動與廣泛旅行連接起來。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":4},{"front":"conducting a survey of","meaning":"正在進行……的調查","examples":[{"en":"Naarding was conducting a survey of an endangered migratory bird.","zh":"Naarding 正在進行一種瀕危候鳥的調查。"},{"en":"Conducting a survey of something means systematically collecting information about it.","zh":"conducting a survey of something 指有系統地收集關於某事的資料。"},{"en":"A school may conduct a survey of students’ reading habits before buying new books.","zh":"學校在購買新書前可能進行學生閱讀習慣調查。"},{"en":"If scientists conduct a survey of birds, they may count them, record locations, and note behaviour.","zh":"如果科學家進行鳥類調查，他們可能點算數量、記錄位置並注意行為。"},{"en":"This phrase describes organised data collection.","zh":"這個片語描述有組織的資料收集。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":4},{"front":"endangered migratory bird","meaning":"瀕危候鳥","examples":[{"en":"Naarding was surveying a species of endangered migratory bird.","zh":"Naarding 正在調查一種瀕危候鳥。"},{"en":"An endangered migratory bird is a bird at risk of extinction that travels seasonally between places.","zh":"endangered migratory bird 是有滅絕風險並會按季節在不同地方遷徙的鳥。"},{"en":"A wetland may protect endangered migratory birds that stop there during long journeys.","zh":"濕地可以保護長途遷徙途中停留的瀕危候鳥。"},{"en":"If wetlands shrink, endangered migratory birds may lose resting and feeding places.","zh":"如果濕地縮小，瀕危候鳥可能失去休息和覓食地。"},{"en":"This phrase combines conservation status with seasonal movement.","zh":"這個片語結合保育狀況與季節性移動。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":4},{"front":"regarded as","meaning":"被視為……","examples":[{"en":"Naarding’s sighting is regarded as highly credible.","zh":"Naarding 的目擊被視為高度可信。"},{"en":"Regarded as means considered or judged to be something.","zh":"regarded as 指被認為或判斷為某種情況。"},{"en":"A teacher may be regarded as strict but fair if students trust her marking.","zh":"如果學生信任老師的評分，她可能被視為嚴格但公平。"},{"en":"If a witness is experienced and careful, their report may be regarded as more reliable.","zh":"如果目擊者有經驗又謹慎，其報告可能被視為較可靠。"},{"en":"This phrase shows how people evaluate someone or something.","zh":"這個片語顯示人們如何評價某人或某事。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":4},{"front":"most credible recorded sighting","meaning":"最可信的有記錄目擊","examples":[{"en":"His sighting is regarded as the most credible recorded sighting of a thylacine.","zh":"他的目擊被視為最可信的有記錄袋狼目擊。"},{"en":"The most credible recorded sighting is the most believable officially noted report of seeing something.","zh":"most credible recorded sighting 指最可信、並被正式記錄下來的目擊報告。"},{"en":"A clear photo from an expert observer may become the most credible recorded sighting of a rare bird.","zh":"由專家觀察者拍下的清晰照片，可能成為某罕見鳥類最可信的有記錄目擊。"},{"en":"If a sighting is credible and recorded, researchers are more likely to investigate it seriously.","zh":"如果目擊可信且有記錄，研究人員較可能認真調查。"},{"en":"This phrase combines reliability with documented evidence.","zh":"這個片語結合可靠性與有文件記錄的證據。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":4},{"front":"recorded sighting","meaning":"有記錄的目擊","examples":[{"en":"The account became a recorded sighting of the thylacine.","zh":"這個描述成為一次有記錄的袋狼目擊。"},{"en":"A recorded sighting is a report of seeing something that has been written down, filmed, photographed, or officially noted.","zh":"recorded sighting 是被寫下、拍攝、拍照或正式記下的目擊報告。"},{"en":"A birdwatcher’s dated photograph can become a recorded sighting of a rare bird.","zh":"觀鳥者有日期的照片可以成為罕見鳥類的有記錄目擊。"},{"en":"If a sighting is recorded, later researchers can compare details and judge its reliability.","zh":"如果目擊有記錄，後來研究人員可以比較細節並判斷其可靠性。"},{"en":"This phrase refers to a sighting preserved as evidence.","zh":"這個片語指被保存為證據的目擊。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":4},{"front":"take up the story","meaning":"接着講述故事","examples":[{"en":"Naarding takes up the story by describing his night work.","zh":"Naarding 接着講述故事，描述他的夜間工作。"},{"en":"To take up the story means to continue telling it from a certain point.","zh":"take up the story 指從某一點繼續講述故事。"},{"en":"After the teacher explains the background, a student may take up the story and describe what happened next.","zh":"老師解釋背景後，學生可能接着講述故事，描述之後發生甚麼。"},{"en":"If a witness takes up the story, listeners hear the event from that person’s viewpoint.","zh":"如果目擊者接着講述故事，聽眾會從那個人的角度聽到事件。"},{"en":"This phrase is used when someone continues a narrative.","zh":"這個片語用於某人繼續敘述時。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":4},{"front":"in the habit of","meaning":"習慣於……","examples":[{"en":"He was in the habit of shining a spotlight around.","zh":"他習慣於四處照射聚光燈。"},{"en":"To be in the habit of doing something means to do it regularly or routinely.","zh":"be in the habit of doing something 指經常或按習慣做某事。"},{"en":"A student may be in the habit of checking homework before going to bed.","zh":"學生可能習慣於睡前檢查功課。"},{"en":"If someone is in the habit of observing carefully, they may notice unusual things quickly.","zh":"如果某人習慣仔細觀察，就可能很快注意到不尋常事物。"},{"en":"This phrase describes a repeated personal routine.","zh":"這個片語描述重複的個人習慣。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":5},{"front":"intermittently","meaning":"間歇地","examples":[{"en":"He was intermittently shining a spotlight around.","zh":"他間歇地四處照射聚光燈。"},{"en":"Intermittently means happening from time to time, with pauses in between.","zh":"intermittently 指不時發生，中間有停頓。"},{"en":"During a storm, the lights may flicker intermittently.","zh":"暴風雨期間，燈光可能間歇地閃爍。"},{"en":"If someone checks an area intermittently, they do not watch it continuously but return to it again and again.","zh":"如果某人間歇地查看某區域，他不是連續觀看，而是一再回去查看。"},{"en":"This word describes repeated but not constant action.","zh":"這個詞描述重複但非持續的動作。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":5},{"front":"shining a spotlight","meaning":"照射聚光燈","examples":[{"en":"Naarding was shining a spotlight around at night.","zh":"Naarding 夜間四處照射聚光燈。"},{"en":"Shining a spotlight means directing a strong beam of light onto an area or object.","zh":"shining a spotlight 指把強光束照向某個區域或物件。"},{"en":"A security guard may shine a spotlight into a dark car park.","zh":"保安員可能把聚光燈照進黑暗的停車場。"},{"en":"If a spotlight falls on an animal, its shape and markings may become visible.","zh":"如果聚光燈照到動物，其形狀和斑紋可能變得可見。"},{"en":"This phrase describes using bright light to see in darkness.","zh":"這個片語描述用強光在黑暗中看清事物。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":5},{"front":"the beam fell on","meaning":"光束照到……","examples":[{"en":"The beam fell on an animal in front of the vehicle.","zh":"光束照到車輛前方的一隻動物。"},{"en":"The beam fell on something means the light shone onto it.","zh":"the beam fell on something 指光線照到某物上。"},{"en":"The flashlight beam fell on a lost key under the sofa.","zh":"手電筒光束照到梳化底下遺失的鑰匙。"},{"en":"If a light beam falls on an animal at night, the observer may suddenly see it clearly.","zh":"如果夜間光束照到動物，觀察者可能突然看清牠。"},{"en":"This phrase describes light landing on a surface or object.","zh":"這個片語描述光線落在表面或物件上。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":5},{"front":"in front of the vehicle","meaning":"在車輛前方","examples":[{"en":"The animal appeared in front of the vehicle.","zh":"那隻動物出現在車輛前方。"},{"en":"In front of the vehicle means directly ahead of the car, truck, or other vehicle.","zh":"in front of the vehicle 指在汽車、貨車或其他車輛正前方。"},{"en":"A driver must stop if a child runs in front of the vehicle.","zh":"如果孩子跑到車輛前方，司機必須停車。"},{"en":"If an animal appears in front of the vehicle at night, the driver may have only seconds to react.","zh":"如果動物夜間出現在車輛前方，司機可能只有幾秒反應。"},{"en":"This phrase describes location relative to a vehicle.","zh":"這個片語描述相對於車輛的位置。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":5},{"front":"less than 10 metres away","meaning":"不足十米遠","examples":[{"en":"The animal was less than 10 metres away from Naarding.","zh":"那隻動物距離 Naarding 不足十米遠。"},{"en":"Less than 10 metres away means closer than a distance of ten metres.","zh":"less than 10 metres away 指距離少於十米。"},{"en":"A teacher standing less than 10 metres away can usually hear a student speaking normally.","zh":"站在不足十米遠的老師通常能聽到學生正常說話。"},{"en":"If an animal is less than 10 metres away, its markings may be visible without binoculars.","zh":"如果動物距離不足十米遠，不用望遠鏡也可能看到牠的斑紋。"},{"en":"This phrase gives a short and specific distance.","zh":"這個片語給出短而具體的距離。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":5},{"front":"risking movement by","meaning":"冒着因……而驚動對方的風險","examples":[{"en":"Naarding avoided risking movement by grabbing for a camera.","zh":"Naarding 避免冒着因伸手拿相機而驚動對方的風險。"},{"en":"Risking movement by doing something means taking the chance that an action will cause movement and disturb the situation.","zh":"risking movement by doing something 指某個動作可能造成移動並打擾當前情況。"},{"en":"A photographer may avoid risking movement by staying still near a shy bird.","zh":"攝影師在害羞鳥類附近可能保持不動，以免冒着移動而驚動牠的風險。"},{"en":"If a witness reaches suddenly for a camera, the animal may run away before being photographed.","zh":"如果目擊者突然伸手拿相機，動物可能在被拍下前逃走。"},{"en":"This phrase shows caution when movement could ruin an observation.","zh":"這個片語顯示在移動可能破壞觀察時的謹慎。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":5},{"front":"grabbing for a camera","meaning":"伸手拿相機","examples":[{"en":"He did not want to scare the animal by grabbing for a camera.","zh":"他不想因伸手拿相機而嚇跑那隻動物。"},{"en":"Grabbing for a camera means quickly reaching out to take a camera.","zh":"grabbing for a camera 指快速伸手去拿相機。"},{"en":"A tourist may miss a bird shot by grabbing for a camera too suddenly.","zh":"遊客可能因太突然伸手拿相機而錯過拍鳥的機會。"},{"en":"If movement is sudden, a shy animal may flee before the person can take a photo.","zh":"如果動作突然，害羞動物可能在人拍照前逃走。"},{"en":"This phrase describes a quick physical attempt to get a camera.","zh":"這個片語描述快速用手去取相機的動作。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":5},{"front":"register very carefully","meaning":"非常仔細地記下","examples":[{"en":"He decided to register very carefully what he was seeing.","zh":"他決定非常仔細地記下自己正在看到的東西。"},{"en":"To register very carefully means to observe, notice, and mentally record details with great attention.","zh":"register very carefully 指以高度注意力觀察、留意並在腦中記下細節。"},{"en":"A doctor must register very carefully a patient’s symptoms before making a diagnosis.","zh":"醫生在作診斷前，必須非常仔細地記下病人症狀。"},{"en":"If a witness cannot take a photo, carefully registering details becomes especially important.","zh":"如果目擊者不能拍照，非常仔細地記下細節便尤其重要。"},{"en":"This phrase describes deliberate and focused observation.","zh":"這個片語描述有意識而專注的觀察。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":5},{"front":"about the size of","meaning":"大約……大小","examples":[{"en":"The animal was about the size of a small shepherd dog.","zh":"那隻動物大約是一隻小牧羊犬的大小。"},{"en":"About the size of means roughly the same size as something familiar.","zh":"about the size of 指大小大約與某個熟悉事物相同。"},{"en":"The classroom projector was about the size of a small suitcase.","zh":"課室投影機大約是一個小行李箱的大小。"},{"en":"If a witness compares an animal to a dog, listeners can imagine its approximate body size.","zh":"如果目擊者把動物與狗比較，聽者就能想像牠大概的體型。"},{"en":"This phrase gives an easy size comparison.","zh":"這個片語提供容易理解的大小比較。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":5},{"front":"shepherd dog","meaning":"牧羊犬","examples":[{"en":"The animal was about the size of a small shepherd dog.","zh":"那隻動物大約是一隻小牧羊犬的大小。"},{"en":"A shepherd dog is a dog traditionally used to help manage sheep or other livestock.","zh":"shepherd dog 是傳統上用來協助管理羊或其他牲畜的狗。"},{"en":"A shepherd dog may run around a field to guide sheep toward the gate.","zh":"牧羊犬可能在田野四周奔跑，把羊引向閘門。"},{"en":"If an unknown animal is compared with a shepherd dog, the comparison suggests a medium-sized body.","zh":"如果未知動物被拿來與牧羊犬比較，這個比較暗示牠有中等體型。"},{"en":"This phrase names a familiar working dog.","zh":"這個片語指出一種熟悉的工作犬。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":5},{"front":"in prime condition","meaning":"狀態極佳","examples":[{"en":"The animal appeared to be a healthy male in prime condition.","zh":"那隻動物看來是一隻狀態極佳的健康雄性。"},{"en":"In prime condition means in excellent health, strength, or physical state.","zh":"in prime condition 指健康、力量或身體狀態極佳。"},{"en":"An athlete in prime condition can train hard without tiring quickly.","zh":"狀態極佳的運動員能進行高強度訓練而不易疲倦。"},{"en":"If an animal looks in prime condition, it may be well fed and physically strong.","zh":"如果動物看起來狀態極佳，牠可能吃得好並且身體強壯。"},{"en":"This phrase describes very good condition, not merely survival.","zh":"這個片語描述非常良好狀態，而不只是存活。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":6},{"front":"set it apart from","meaning":"使它與……區分開","examples":[{"en":"Its hindquarters and tail set it apart from a dog.","zh":"牠的後軀和尾巴使牠與狗區分開。"},{"en":"To set something apart from something else means to make it clearly different.","zh":"set something apart from something else 指令某物明顯不同於另一物。"},{"en":"A school’s strong student support may set it apart from other schools.","zh":"學校強大的學生支援可能使它與其他學校區分開。"},{"en":"If an animal has an unusual tail shape, that feature may separate it from similar animals.","zh":"如果動物有不尋常尾巴形狀，這個特徵可能把它與相似動物分開。"},{"en":"This phrase highlights a distinguishing feature.","zh":"這個片語突出區分特徵。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":6},{"front":"slightly sloping hindquarter","meaning":"略為傾斜的後軀","examples":[{"en":"The animal had a slightly sloping hindquarter.","zh":"那隻動物有略為傾斜的後軀。"},{"en":"A slightly sloping hindquarter means the rear part of the animal’s body angled downward a little.","zh":"slightly sloping hindquarter 指動物身體後半部分稍微向下傾斜。"},{"en":"A vet may notice a slightly sloping hindquarter when examining a dog’s posture.","zh":"獸醫檢查狗的姿勢時，可能注意到略為傾斜的後軀。"},{"en":"If the hindquarter slopes differently from a dog’s, it can help identify the animal.","zh":"如果後軀傾斜方式不同於狗，就可以幫助識別該動物。"},{"en":"This phrase describes a specific body shape feature.","zh":"這個片語描述一個具體身體形態特徵。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":6},{"front":"fairly thick tail","meaning":"相當粗壯的尾巴","examples":[{"en":"The animal had a fairly thick tail.","zh":"那隻動物有相當粗壯的尾巴。"},{"en":"A fairly thick tail means a tail that is quite broad or solid, though not extremely thick.","zh":"fairly thick tail 指尾巴相當寬或結實，但未至於極端粗大。"},{"en":"A fox has a fairly thick tail compared with many small dogs.","zh":"與許多小狗相比，狐狸有相當粗壯的尾巴。"},{"en":"If a tail is thick and stiff-looking, it may help distinguish one species from another.","zh":"如果尾巴粗壯且看似堅硬，它可能幫助區分不同物種。"},{"en":"This phrase describes the size and shape of an animal’s tail.","zh":"這個片語描述動物尾巴的大小和形狀。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":6},{"front":"forming a straight continuation of","meaning":"形成……的筆直延續","examples":[{"en":"The tail formed a straight continuation of the animal’s backline.","zh":"那條尾巴形成動物背部線條的筆直延續。"},{"en":"Forming a straight continuation of something means extending from it in one straight line.","zh":"forming a straight continuation of something 指從某物延伸出去並形成一條直線。"},{"en":"A well-designed handle may form a straight continuation of a tool’s body.","zh":"設計良好的把手可能形成工具主體的筆直延續。"},{"en":"If an animal’s tail continues the backline directly, its outline differs from many dogs.","zh":"如果動物尾巴直接延續背部線條，其輪廓便不同於許多狗。"},{"en":"This phrase describes how one body part connects smoothly with another.","zh":"這個片語描述一個身體部位如何順暢連接另一部位。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":6},{"front":"backline of the animal","meaning":"動物的背部線條","examples":[{"en":"The tail continued the backline of the animal.","zh":"尾巴延續了動物的背部線條。"},{"en":"The backline of the animal is the visible line formed by the animal’s back from shoulders to tail.","zh":"backline of the animal 是從肩部到尾巴形成的可見背部線條。"},{"en":"A horse judge may look at the backline of the animal to assess posture and shape.","zh":"馬匹評審可能觀察動物的背部線條，以評估姿勢和體形。"},{"en":"If the tail follows the backline, the body may look long and straight.","zh":"如果尾巴跟隨背部線條，身體可能看起來修長而筆直。"},{"en":"This phrase describes an animal’s outline from the side.","zh":"這個片語描述從側面看到的動物輪廓。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":6},{"front":"distinct stripes","meaning":"清晰條紋","examples":[{"en":"The animal had 12 distinct stripes on its back.","zh":"那隻動物背上有12條清晰條紋。"},{"en":"Distinct stripes are clear, separate lines that can be easily seen.","zh":"distinct stripes 是清楚、分開並容易看見的線條。"},{"en":"A school sports shirt may have distinct stripes in two strong colours.","zh":"學校運動衫可能有兩種鮮明顏色的清晰條紋。"},{"en":"If an animal has distinct stripes, witnesses can describe it more reliably.","zh":"如果動物有清晰條紋，目擊者可以更可靠地描述牠。"},{"en":"This phrase describes markings that are not faint or unclear.","zh":"這個片語描述不模糊、不淡的斑紋。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":6},{"front":"continuing onto","meaning":"延伸到……","examples":[{"en":"The stripes continued onto the animal’s butt.","zh":"條紋延伸到那隻動物的臀部。"},{"en":"Continuing onto something means extending from one area onto another area.","zh":"continuing onto something 指從一個區域延伸到另一個區域。"},{"en":"The paint pattern on the wall continued onto the ceiling.","zh":"牆上的油漆圖案延伸到天花板。"},{"en":"If stripes continue onto another body part, they help describe the animal’s full marking pattern.","zh":"如果條紋延伸到另一個身體部位，它們有助描述動物完整斑紋模式。"},{"en":"This phrase shows that a feature does not stop at one place.","zh":"這個片語顯示某特徵不止於一處。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":6},{"front":"knew perfectly well","meaning":"非常清楚知道","examples":[{"en":"Naarding knew perfectly well what he was seeing.","zh":"Naarding 非常清楚知道自己正在看甚麼。"},{"en":"Knew perfectly well means understood clearly and without doubt.","zh":"knew perfectly well 指清楚且毫無疑問地明白。"},{"en":"A student who copied homework knew perfectly well that it was against the rules.","zh":"抄功課的學生非常清楚知道這是違反規則的。"},{"en":"If an experienced animal observer knows perfectly well what they saw, the report may seem more credible.","zh":"如果有經驗的動物觀察者非常清楚自己看到甚麼，報告可能顯得更可信。"},{"en":"This phrase stresses certainty and awareness.","zh":"這個片語強調確定和清醒意識。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":6},{"front":"reached for","meaning":"伸手去拿……","examples":[{"en":"As soon as he reached for the camera, the animal disappeared.","zh":"他一伸手去拿相機，那隻動物便消失了。"},{"en":"Reached for means stretched out a hand to take or touch something.","zh":"reached for 指伸手去拿或觸碰某物。"},{"en":"A student reached for a pen when the teacher began dictating notes.","zh":"老師開始口述筆記時，學生伸手去拿筆。"},{"en":"If a person reaches for a camera too quickly, a shy animal may run away.","zh":"如果人太快伸手去拿相機，害羞動物可能逃走。"},{"en":"This phrase describes a physical movement toward an object.","zh":"這個片語描述朝物件作出的身體動作。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":6},{"front":"disappeared into","meaning":"消失於……之中","examples":[{"en":"The animal disappeared into the tea-tree undergrowth and scrub.","zh":"那隻動物消失於茶樹下層灌木和灌木叢之中。"},{"en":"Disappeared into means went into a place and could no longer be seen.","zh":"disappeared into 指進入某地後不再被看見。"},{"en":"A cat may disappear into a narrow alley when someone approaches.","zh":"當有人接近時，貓可能消失於狹窄小巷之中。"},{"en":"If an animal disappears into thick plants, it becomes difficult to follow or photograph.","zh":"如果動物消失於茂密植物之中，就很難追蹤或拍攝。"},{"en":"This phrase describes moving out of sight into a place.","zh":"這個片語描述移入某處並離開視線。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":6},{"front":"tea-tree undergrowth","meaning":"茶樹下層灌木","examples":[{"en":"The animal disappeared into the tea-tree undergrowth.","zh":"那隻動物消失於茶樹下層灌木之中。"},{"en":"Tea-tree undergrowth is low, dense plant growth under or among tea-tree vegetation.","zh":"tea-tree undergrowth 指茶樹植被下方或之間低矮而茂密的植物。"},{"en":"A bushwalker may find it hard to walk through tea-tree undergrowth after rain.","zh":"雨後，叢林步行者可能覺得很難穿過茶樹下層灌木。"},{"en":"If an animal enters undergrowth, the plants can hide it quickly.","zh":"如果動物進入下層灌木，植物可以很快把牠藏起來。"},{"en":"This phrase describes thick low vegetation in a natural area.","zh":"這個片語描述自然地區中茂密的低矮植被。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":7},{"front":"scrub","meaning":"灌木叢","examples":[{"en":"The animal disappeared into the undergrowth and scrub.","zh":"那隻動物消失於下層植被和灌木叢之中。"},{"en":"Scrub is low, thick vegetation made up of bushes and small trees.","zh":"scrub 是由灌木和小樹組成的低矮茂密植被。"},{"en":"Hikers may scratch their legs when walking through dry scrub.","zh":"行山者穿過乾燥灌木叢時，腳可能被刮傷。"},{"en":"Scrub can provide cover for animals that want to hide from people.","zh":"灌木叢可以為想避開人類的動物提供掩護。"},{"en":"This word describes rough, bushy vegetation.","zh":"這個詞描述粗糙、灌木密布的植被。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":7},{"front":"National Parks","meaning":"國家公園管理部門","examples":[{"en":"The director of Tasmania’s National Parks kept the sighting secret.","zh":"塔斯曼尼亞國家公園管理部門的主管把這次目擊保密。"},{"en":"National Parks refers to the authority or protected areas managed for conservation and public use.","zh":"National Parks 可指為保育和公共使用而管理保護區的機構或地方。"},{"en":"National Parks staff may maintain walking tracks and protect native animals.","zh":"國家公園職員可能維護步道並保護本地動物。"},{"en":"If National Parks receives a rare animal report, it may decide whether to investigate or keep the area quiet.","zh":"如果國家公園管理部門收到罕見動物報告，它可能決定是否調查或保持該區安靜。"},{"en":"This phrase can refer to a management body, not just the parks themselves.","zh":"這個片語可指管理機構，而不只是公園本身。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":7},{"front":"in his wisdom","meaning":"他自認明智地","examples":[{"en":"Peter Morrow decided in his wisdom to keep the sighting secret.","zh":"Peter Morrow 他自認明智地決定把這次目擊保密。"},{"en":"In his wisdom can mean he decided what he thought was wise, often with a slightly ironic tone.","zh":"in his wisdom 可指他作出自己認為明智的決定，常帶少許諷刺語氣。"},{"en":"The principal, in his wisdom, cancelled sports day just before the rain stopped.","zh":"校長他自認明智地在雨停前剛取消了運動會。"},{"en":"If someone says “in his wisdom”, they may be gently questioning the decision.","zh":"如果有人說 “in his wisdom”，他可能是在婉轉質疑該決定。"},{"en":"This phrase often suggests the speaker is not fully approving.","zh":"這個片語常暗示說話者並非完全認同。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":7},{"front":"keep…secret","meaning":"將……保密","examples":[{"en":"The director decided to keep Naarding’s sighting secret.","zh":"主管決定將 Naarding 的目擊保密。"},{"en":"To keep something secret means to avoid telling others about it.","zh":"keep something secret 指避免把某事告訴其他人。"},{"en":"A student may keep a birthday surprise secret until the party begins.","zh":"學生可能把生日驚喜保密，直到派對開始。"},{"en":"If officials keep a rare animal sighting secret, they may be trying to protect the area from crowds.","zh":"如果官員將罕見動物目擊保密，他們可能想保護該區免受人群滋擾。"},{"en":"This phrase describes deliberately hiding information.","zh":"這個片語描述刻意隱藏資訊。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":7},{"front":"news finally broke","meaning":"消息終於傳出","examples":[{"en":"When the news finally broke, there was pandemonium.","zh":"當消息終於傳出時，出現一片混亂。"},{"en":"News finally broke means information became public after being hidden or unknown.","zh":"news finally broke 指資訊在被隱藏或未知一段時間後公開。"},{"en":"When the exam date finally broke, students immediately began planning revision.","zh":"當考試日期終於傳出時，學生立即開始規劃溫習。"},{"en":"If news about a rare animal breaks, journalists and searchers may rush to the area.","zh":"如果罕見動物的消息傳出，記者和搜索者可能趕到該區。"},{"en":"This phrase describes delayed information becoming public.","zh":"這個片語描述延遲公開的資訊終於曝光。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":7},{"front":"accompanied by pandemonium","meaning":"伴隨一片混亂","examples":[{"en":"The news was accompanied by pandemonium.","zh":"這則消息伴隨一片混亂。"},{"en":"Accompanied by pandemonium means happening together with noisy confusion and disorder.","zh":"accompanied by pandemonium 指某事發生時同時出現喧鬧混亂和失序。"},{"en":"The sale announcement was accompanied by pandemonium as shoppers rushed into the store.","zh":"減價消息公布時，顧客衝入店內，伴隨一片混亂。"},{"en":"If a rare sighting becomes public, excitement and confusion may follow immediately.","zh":"如果罕見目擊公開，興奮和混亂可能立即跟隨。"},{"en":"This phrase shows that an event created chaos around it.","zh":"這個片語顯示某事件引發周圍混亂。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":7},{"front":"pandemonium","meaning":"大混亂；喧鬧","examples":[{"en":"The announcement of the sighting caused pandemonium.","zh":"目擊消息公布造成大混亂。"},{"en":"Pandemonium means loud confusion, chaos, and uncontrolled excitement.","zh":"pandemonium 指喧鬧混亂、混亂局面和失控興奮。"},{"en":"There was pandemonium in the classroom when a bird flew in through the window.","zh":"當一隻鳥從窗戶飛進課室時，課室一片喧鬧混亂。"},{"en":"If too many reporters arrive at once, a quiet research site can become chaotic.","zh":"如果太多記者同時到達，安靜研究地點可能變得混亂。"},{"en":"This word describes a scene where people are noisy and hard to control.","zh":"這個詞描述人群嘈雜且難以控制的場面。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":7},{"front":"besieged by","meaning":"被……包圍","examples":[{"en":"Naarding was besieged by television crews.","zh":"Naarding 被電視攝製隊包圍。"},{"en":"To be besieged by people means to be surrounded or overwhelmed by many of them.","zh":"be besieged by people 指被許多人包圍或壓倒。"},{"en":"A singer may be besieged by fans after a concert.","zh":"歌手演唱會後可能被粉絲包圍。"},{"en":"If a witness is besieged by reporters, it may become difficult for them to speak calmly.","zh":"如果目擊者被記者包圍，他可能難以冷靜說話。"},{"en":"This phrase describes intense pressure from many people seeking attention or answers.","zh":"這個片語描述許多人索取注意或答案所造成的強烈壓力。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":7},{"front":"television crews","meaning":"電視攝製隊","examples":[{"en":"Television crews from several countries contacted Naarding.","zh":"來自幾個國家的電視攝製隊聯絡了 Naarding。"},{"en":"Television crews are groups of people who record, report, and broadcast television programmes or news.","zh":"television crews 是錄製、報道和播放電視節目或新聞的人員團隊。"},{"en":"A television crew may include a reporter, camera operator, sound technician, and producer.","zh":"電視攝製隊可能包括記者、攝影師、收音技師和監製。"},{"en":"If television crews arrive at a small town, local people may feel sudden media pressure.","zh":"如果電視攝製隊到達小鎮，當地人可能突然感到媒體壓力。"},{"en":"This phrase refers to teams that make television coverage.","zh":"這個片語指製作電視報道的團隊。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":7},{"front":"broadcasting live","meaning":"現場直播","examples":[{"en":"Some television crews were broadcasting live from Japan.","zh":"一些電視攝製隊正從日本現場直播。"},{"en":"Broadcasting live means sending video or audio to viewers at the same time as events happen.","zh":"broadcasting live 指在事件發生同時向觀眾傳送影片或聲音。"},{"en":"A news channel may broadcast live from outside a courthouse.","zh":"新聞頻道可能在法院外現場直播。"},{"en":"If a programme is broadcast live, mistakes or surprises cannot easily be edited out.","zh":"如果節目現場直播，錯誤或驚喜就不容易剪走。"},{"en":"This phrase describes real-time media coverage.","zh":"這個片語描述即時媒體報道。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":7},{"front":"search parties","meaning":"搜索隊","examples":[{"en":"Government and private search parties combed the region.","zh":"政府和私人搜索隊仔細搜索該地區。"},{"en":"Search parties are groups of people organised to look for someone or something missing.","zh":"search parties 是組織起來尋找失蹤的人或物的團隊。"},{"en":"After a child gets lost in a park, volunteers may form search parties.","zh":"孩子在公園走失後，義工可能組成搜索隊。"},{"en":"If search parties cover a wide area, they may find tracks, objects, or other clues.","zh":"如果搜索隊覆蓋廣闊地區，可能找到足跡、物件或其他線索。"},{"en":"This phrase describes organised searching by groups.","zh":"這個片語描述由團體進行的有組織搜索。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":8},{"front":"combed the region","meaning":"仔細搜索該地區","examples":[{"en":"Search parties combed the region for signs of the thylacine.","zh":"搜索隊仔細搜索該地區，尋找袋狼的跡象。"},{"en":"To comb a region means to search it very carefully and thoroughly.","zh":"comb a region 指非常仔細而徹底地搜索某地區。"},{"en":"Police combed the area after a child’s bicycle was found near the river.","zh":"孩子的單車在河邊被發現後，警方仔細搜索該區。"},{"en":"If searchers comb a region, they examine tracks, bushes, paths, and possible hiding places.","zh":"如果搜索者仔細搜索一個地區，他們會檢查足跡、灌木、路徑和可能藏身處。"},{"en":"This phrase suggests a detailed and systematic search.","zh":"這個片語暗示詳細而有系統的搜索。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":8},{"front":"further sightings","meaning":"進一步目擊","examples":[{"en":"No further sightings were made after the search.","zh":"搜索後沒有進一步目擊。"},{"en":"Further sightings means additional reports of seeing the animal after an earlier sighting.","zh":"further sightings 指在較早目擊之後，再次看到該動物的報告。"},{"en":"If a rare bird is seen once but there are no further sightings, experts may remain cautious.","zh":"如果罕見鳥類只被看到一次，之後沒有進一步目擊，專家可能仍然謹慎。"},{"en":"Further sightings can support an original report if they occur in the same area.","zh":"如果進一步目擊發生在同一地區，它們可以支持原本報告。"},{"en":"This phrase refers to later sightings beyond the first one.","zh":"這個片語指第一次之後的後續目擊。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":8},{"front":"escaped to its lair","meaning":"逃回巢穴","examples":[{"en":"The tiger had escaped to its lair again.","zh":"那隻虎又逃回牠的巢穴。"},{"en":"Escaped to its lair means went back to its hidden den or resting place.","zh":"escaped to its lair 指回到隱蔽的巢穴或休息處。"},{"en":"A fox may escape to its lair when hikers approach too closely.","zh":"當行山者太接近時，狐狸可能逃回巢穴。"},{"en":"If an animal returns to its lair, searchers may lose track of it quickly.","zh":"如果動物回到巢穴，搜索者可能很快失去牠的蹤跡。"},{"en":"This phrase gives an image of an animal hiding in a secret place.","zh":"這個片語給人動物藏身於秘密地方的畫面。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":8},{"front":"lair","meaning":"獸穴；藏身處","examples":[{"en":"Many people imagine the thylacine hiding in its lair.","zh":"許多人想像袋狼躲在牠的獸穴中。"},{"en":"A lair is a wild animal’s hidden resting place or den.","zh":"lair 是野生動物隱蔽的休息地或巢穴。"},{"en":"A wolf may return to its lair after hunting at night.","zh":"狼夜間狩獵後可能回到獸穴。"},{"en":"If an animal has a hidden lair, it may avoid humans for a long time.","zh":"如果動物有隱蔽藏身處，它可能長時間避開人類。"},{"en":"This word suggests secrecy, shelter, and wildness.","zh":"這個詞暗示秘密、庇護和野性。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":8},{"front":"insist exists only in","meaning":"堅稱只存在於……","examples":[{"en":"Some insist that its lair exists only in our imagination.","zh":"有些人堅稱牠的巢穴只存在於我們的想像中。"},{"en":"To insist something exists only in imagination means to strongly claim it is not real.","zh":"insist something exists only in imagination 指強烈聲稱某事並不真實。"},{"en":"Some people insist that perfect school life exists only in advertisements.","zh":"有些人堅稱完美校園生活只存在於廣告中。"},{"en":"If experts say a species is extinct, they may argue that hopes of finding it exist only in imagination.","zh":"如果專家說某物種已滅絕，他們可能認為找到牠的希望只存在於想像中。"},{"en":"This phrase strongly contrasts belief with reality.","zh":"這個片語強烈對比信念與現實。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":8},{"front":"staged something of a comeback","meaning":"某程度上重新受到關注","examples":[{"en":"The thylacine has staged something of a comeback in Australian mythology.","zh":"袋狼在澳洲神話中某程度上重新受到關注。"},{"en":"To stage something of a comeback means to become more noticed or popular again, though not completely as before.","zh":"staged something of a comeback 指再次變得較受注意或受歡迎，但未必完全回到從前。"},{"en":"Vinyl records have staged something of a comeback among music lovers.","zh":"黑膠唱片在音樂愛好者中某程度上重新流行。"},{"en":"If stories and sightings keep appearing, an extinct animal may return to public attention.","zh":"如果故事和目擊報告不斷出現，已滅絕動物可能重回公眾注意。"},{"en":"This phrase describes partial renewed interest or popularity.","zh":"這個片語描述某種部分恢復的興趣或受歡迎程度。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":8},{"front":"Australian mythology","meaning":"澳洲神話","examples":[{"en":"The thylacine has become part of Australian mythology.","zh":"袋狼已成為澳洲神話的一部分。"},{"en":"Australian mythology means the stories, legends, and symbolic ideas connected with Australia.","zh":"Australian mythology 指與澳洲相關的故事、傳說和象徵性想法。"},{"en":"A mysterious animal may enter local mythology when people keep telling stories about it.","zh":"如果人們不斷講述某神秘動物的故事，牠可能進入本地神話。"},{"en":"If the thylacine becomes part of mythology, it is remembered through belief and imagination as well as science.","zh":"如果袋狼成為神話的一部分，牠就不只透過科學，也透過信念和想像被記住。"},{"en":"This phrase refers to cultural storytelling, not only ancient myths.","zh":"這個片語指文化敘事，而不只是古代神話。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":8},{"front":"claimed sightings","meaning":"聲稱目擊個案","examples":[{"en":"There have been more than 4,000 claimed sightings of the thylacine.","zh":"袋狼已有超過四千宗聲稱目擊個案。"},{"en":"Claimed sightings are reports in which people say they have seen something, whether or not it is proven.","zh":"claimed sightings 是人們聲稱自己看見某物的報告，不論是否已被證實。"},{"en":"A claimed sighting of a rare bird may need a photograph before experts accept it.","zh":"罕見鳥類的聲稱目擊個案可能需要照片，專家才會接受。"},{"en":"If claimed sightings are numerous but unverified, they create public interest but not scientific certainty.","zh":"如果聲稱目擊很多但未經核實，它們會引起公眾興趣，但不構成科學確定性。"},{"en":"This phrase describes reported sightings that still require evaluation.","zh":"這個片語描述仍需評估的目擊報告。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":8},{"front":"supposedly died out","meaning":"據稱已滅絕","examples":[{"en":"The beast supposedly died out decades ago.","zh":"這種野獸據稱已在數十年前滅絕。"},{"en":"Supposedly died out means people generally say or believe it became extinct, but doubt may remain.","zh":"supposedly died out 指人們一般說或相信牠已滅絕，但仍可能有懷疑。"},{"en":"A plant supposedly died out years ago may be rediscovered in a remote valley.","zh":"一種據稱多年前已滅絕的植物，可能在偏遠山谷被重新發現。"},{"en":"If an animal supposedly died out but sightings continue, debate may persist.","zh":"如果動物據稱已滅絕但目擊仍持續，爭論可能延續。"},{"en":"This phrase shows reported extinction with a hint of uncertainty.","zh":"這個片語顯示被報稱的滅絕，同時帶有一點不確定性。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":8},{"front":"reported to authorities","meaning":"向當局報告","examples":[{"en":"The number of claims reported to authorities averages 150 a year.","zh":"向當局報告的聲稱目擊個案平均每年150宗。"},{"en":"Reported to authorities means officially told to government offices, police, park staff, or other responsible bodies.","zh":"reported to authorities 指正式告知政府部門、警方、公園職員或其他負責機構。"},{"en":"A lost passport should be reported to authorities as soon as possible.","zh":"遺失護照應盡快向當局報告。"},{"en":"If sightings are reported to authorities, officials may record them and decide whether to investigate.","zh":"如果目擊被向當局報告，官員可能記錄並決定是否調查。"},{"en":"This phrase describes formal reporting to responsible organisations.","zh":"這個片語描述向負責組織作出正式報告。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":8},{"front":"averages 150 a year","meaning":"平均每年 150 宗","examples":[{"en":"The number of reported sightings now averages 150 a year.","zh":"報稱目擊個案現在平均每年150宗。"},{"en":"Averages 150 a year means the typical yearly number is about 150.","zh":"averages 150 a year 指典型每年數量約為150。"},{"en":"A busy clinic may average 150 patients a day during flu season.","zh":"流感季節期間，繁忙診所可能平均每天接待150名病人。"},{"en":"If reports average 150 a year, the subject remains active in public attention.","zh":"如果報告平均每年150宗，這個主題仍然活躍於公眾關注中。"},{"en":"This phrase describes a repeated average over time.","zh":"這個片語描述隨時間反覆出現的平均數。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":9},{"front":"associate professor of zoology","meaning":"動物學副教授","examples":[{"en":"Randolph Rose is an associate professor of zoology.","zh":"Randolph Rose 是一名動物學副教授。"},{"en":"An associate professor of zoology is a university academic who teaches and researches animal biology at a senior level.","zh":"associate professor of zoology 是在大學中以高級職級教授和研究動物生物學的學者。"},{"en":"An associate professor of zoology may study animal behaviour, evolution, or conservation.","zh":"動物學副教授可能研究動物行為、進化或保育。"},{"en":"If such a professor comments on thylacines, their view carries scientific experience.","zh":"如果這樣的教授評論袋狼，其看法帶有科學經驗。"},{"en":"This phrase identifies both academic rank and subject field.","zh":"這個片語同時指出學術職級和學科領域。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":9},{"front":"University of Tasmania","meaning":"塔斯曼尼亞大學","examples":[{"en":"Randolph Rose works at the University of Tasmania.","zh":"Randolph Rose 在塔斯曼尼亞大學工作。"},{"en":"The University of Tasmania is a university in the Australian state of Tasmania.","zh":"University of Tasmania 是位於澳洲塔斯曼尼亞州的大學。"},{"en":"A student interested in marine science or local wildlife may study at the University of Tasmania.","zh":"對海洋科學或本地野生動物有興趣的學生，可能在塔斯曼尼亞大學讀書。"},{"en":"Because the thylacine was native to Tasmania, local university experts may be especially interested in it.","zh":"因為袋狼是塔斯曼尼亞本地動物，本地大學專家可能對牠特別感興趣。"},{"en":"This phrase names the academic institution linked to the speaker.","zh":"這個片語指出與發言者相關的學術機構。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":9},{"front":"dreams of seeing","meaning":"夢想見到","examples":[{"en":"Rose has said he dreams of seeing a thylacine.","zh":"Rose 曾說他夢想見到一隻袋狼。"},{"en":"To dream of seeing something means to strongly hope one day to see it.","zh":"dream of seeing something 指強烈希望有一天能看見某物。"},{"en":"A young astronomer may dream of seeing a rare comet through a telescope.","zh":"年輕天文學家可能夢想透過望遠鏡看到罕見彗星。"},{"en":"If someone dreams of seeing an extinct animal, the hope may remain even when evidence is weak.","zh":"如果某人夢想見到已滅絕動物，即使證據薄弱，這份希望仍可能存在。"},{"en":"This phrase expresses a personal wish or longing.","zh":"這個片語表達個人願望或渴望。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":9},{"front":"in Tasmanian academia","meaning":"在塔斯曼尼亞學術界","examples":[{"en":"Rose spent 35 years in Tasmanian academia.","zh":"Rose 在塔斯曼尼亞學術界度過了35年。"},{"en":"In Tasmanian academia means within universities and scholarly life in Tasmania.","zh":"in Tasmanian academia 指在塔斯曼尼亞的大學和學術生活之中。"},{"en":"A researcher in local academia may teach students, publish papers, and attend conferences.","zh":"本地學術界的研究人員可能教學生、發表論文和參加會議。"},{"en":"If someone spends decades in Tasmanian academia, they may know local scientific debates well.","zh":"如果某人在塔斯曼尼亞學術界工作數十年，他可能很熟悉本地科學爭論。"},{"en":"This phrase refers to the academic community of Tasmania.","zh":"這個片語指塔斯曼尼亞的學術社群。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":9},{"front":"fielded countless reports","meaning":"處理過無數報告","examples":[{"en":"Rose has fielded countless reports of thylacine sightings.","zh":"Rose 處理過無數袋狼目擊報告。"},{"en":"To field countless reports means to receive, handle, and respond to many reports.","zh":"field countless reports 指接收、處理並回應大量報告。"},{"en":"A school office may field countless calls from parents after a timetable change.","zh":"時間表改動後，學校辦公室可能處理無數家長來電。"},{"en":"If a scientist fields many sighting reports, they must judge which ones deserve attention.","zh":"如果科學家處理許多目擊報告，就必須判斷哪些值得注意。"},{"en":"This phrase describes dealing with a large number of enquiries or claims.","zh":"這個片語描述處理大量查詢或聲稱。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":9},{"front":"convinced that","meaning":"確信","examples":[{"en":"Rose is convinced that his dream will go unfulfilled.","zh":"Rose 確信他的夢想將不會實現。"},{"en":"Convinced that means strongly believing that something is true.","zh":"convinced that 指強烈相信某事是真的。"},{"en":"A teacher may be convinced that a student can improve after seeing steady progress.","zh":"老師看到學生穩定進步後，可能確信學生能改善。"},{"en":"If an expert is convinced an animal is gone, they may see new reports with scepticism.","zh":"如果專家確信一種動物已消失，他們可能以懷疑態度看待新報告。"},{"en":"This phrase shows strong belief or certainty.","zh":"這個片語顯示強烈信念或確定性。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":9},{"front":"go unfulfilled","meaning":"未能實現","examples":[{"en":"His dream of seeing a thylacine will probably go unfulfilled.","zh":"他見到袋狼的夢想很可能未能實現。"},{"en":"To go unfulfilled means not to happen or not to be achieved.","zh":"go unfulfilled 指沒有發生或未被達成。"},{"en":"A student’s dream of studying abroad may go unfulfilled if they cannot afford the fees.","zh":"如果學生負擔不起學費，出國留學的夢想可能未能實現。"},{"en":"If the thylacine is truly extinct, hopes of seeing one alive will remain unrealised.","zh":"如果袋狼真的已滅絕，看到活體的希望將仍然無法實現。"},{"en":"This phrase describes a wish that is not realised.","zh":"這個片語描述未能成真的願望。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":9},{"front":"consensus among conservationists","meaning":"保育人士之間的共識","examples":[{"en":"The consensus among conservationists is that small populations face extinction.","zh":"保育人士之間的共識是，小種群會面臨滅絕。"},{"en":"Consensus among conservationists means the general agreement shared by people who work to protect wildlife.","zh":"consensus among conservationists 指保護野生動物的人所共有的一般共識。"},{"en":"There is often consensus among doctors that sleep is important for health.","zh":"醫生之間常有共識，認為睡眠對健康很重要。"},{"en":"If conservationists agree that small populations are at risk, they may call for urgent protection.","zh":"如果保育人士一致認為小種群有風險，他們可能要求緊急保護。"},{"en":"This phrase describes a shared expert view.","zh":"這個片語描述共享的專家看法。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":9},{"front":"population base","meaning":"種群基礎數量","examples":[{"en":"An animal with a population base of less than 1,000 may face extinction.","zh":"種群基礎數量少於一千的動物可能面臨滅絕。"},{"en":"Population base means the number of individuals available to maintain a species or group.","zh":"population base 指可用來維持物種或群體的個體數量。"},{"en":"A small town with a shrinking population base may struggle to keep schools open.","zh":"人口基礎縮小的小鎮可能難以維持學校運作。"},{"en":"If an animal’s population base is too small, breeding and survival become harder.","zh":"如果動物的種群基礎數量太小，繁殖和生存會變得更困難。"},{"en":"This phrase focuses on the starting number needed for long-term survival.","zh":"這個片語聚焦於長期生存所需的起始數量。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":9},{"front":"headed for extinction","meaning":"走向滅絕","examples":[{"en":"A species with too few animals is usually headed for extinction.","zh":"動物數量太少的物種通常正走向滅絕。"},{"en":"Headed for extinction means likely to become extinct if nothing changes.","zh":"headed for extinction 指如果沒有改變，就很可能滅絕。"},{"en":"A local shop with no customers may be headed for closure.","zh":"沒有顧客的本地小店可能正走向結業。"},{"en":"If a species has too few breeding animals, it may be headed for extinction within decades.","zh":"如果物種有太少可繁殖動物，它可能在數十年內走向滅絕。"},{"en":"This phrase describes a dangerous future direction.","zh":"這個片語描述危險的未來走向。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":9},{"front":"within 60 years","meaning":"在 60 年內","examples":[{"en":"Such an animal may be headed for extinction within 60 years.","zh":"這樣的動物可能在60年內走向滅絕。"},{"en":"Within 60 years means before 60 years have passed.","zh":"within 60 years 指在60年過去之前。"},{"en":"A building may need major repairs within 60 years if it is poorly maintained.","zh":"如果建築保養不善，可能在60年內需要大型維修。"},{"en":"If a species is at risk within 60 years, conservation action cannot wait forever.","zh":"如果物種在60年內有風險，保育行動就不能無限期拖延。"},{"en":"This phrase gives a time limit for a possible outcome.","zh":"這個片語給出可能結果的時間限制。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":10},{"front":"that we know of","meaning":"據我們所知","examples":[{"en":"Sixty years ago, there was only one thylacine that we know of.","zh":"據我們所知，六十年前只有一隻袋狼。"},{"en":"That we know of means based on the information available to us.","zh":"that we know of 指根據我們可得到的資料。"},{"en":"There are no students absent today, that we know of.","zh":"據我們所知，今天沒有學生缺席。"},{"en":"If there was only one animal that people knew of, others may still have existed unseen.","zh":"如果人們只知道有一隻動物，其他個體仍可能未被看見。"},{"en":"This phrase shows caution because knowledge may be incomplete.","zh":"這個片語顯示謹慎，因為知識可能不完整。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":10},{"front":"curator of zoology","meaning":"動物學館長","examples":[{"en":"Dr. David Pemberton is curator of zoology at the Tasmanian Museum and Art Gallery.","zh":"David Pemberton 博士是塔斯曼尼亞博物館暨美術館的動物學館長。"},{"en":"A curator of zoology is a museum specialist responsible for animal collections and related research.","zh":"curator of zoology 是負責動物收藏和相關研究的博物館專家。"},{"en":"A curator of zoology may preserve specimens, organise exhibitions, and answer scientific questions.","zh":"動物學館長可能保存標本、組織展覽和回答科學問題。"},{"en":"If a curator studies thylacines, they may use museum specimens and historical records.","zh":"如果館長研究袋狼，他們可能使用博物館標本和歷史記錄。"},{"en":"This phrase identifies a museum role connected with animals.","zh":"這個片語指出與動物相關的博物館職位。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":10},{"front":"Tasmanian Museum and Art Gallery","meaning":"塔斯曼尼亞博物館暨美術館","examples":[{"en":"Pemberton works at the Tasmanian Museum and Art Gallery.","zh":"Pemberton 在塔斯曼尼亞博物館暨美術館工作。"},{"en":"The Tasmanian Museum and Art Gallery is an institution in Tasmania that holds cultural, artistic, and scientific collections.","zh":"Tasmanian Museum and Art Gallery 是塔斯曼尼亞的一所機構，收藏文化、藝術和科學藏品。"},{"en":"A visitor may see animal specimens, paintings, and historical objects at the Tasmanian Museum and Art Gallery.","zh":"遊客可能在塔斯曼尼亞博物館暨美術館看到動物標本、繪畫和歷史物件。"},{"en":"Because museums preserve evidence, they help researchers study extinct animals.","zh":"因為博物館保存證據，它們幫助研究人員研究已滅絕動物。"},{"en":"This phrase names the institution linked with Pemberton’s work.","zh":"這個片語指出與 Pemberton 工作相關的機構。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":10},{"front":"PhD thesis","meaning":"博士論文","examples":[{"en":"Pemberton’s PhD thesis was on the thylacine.","zh":"Pemberton 的博士論文是關於袋狼的。"},{"en":"A PhD thesis is a long piece of original research written to earn a doctoral degree.","zh":"PhD thesis 是為取得博士學位而撰寫的長篇原創研究。"},{"en":"A student writing a PhD thesis may spend years collecting data and analysing evidence.","zh":"撰寫博士論文的學生可能花多年收集數據和分析證據。"},{"en":"If someone’s thesis is on the thylacine, they have studied the animal in depth.","zh":"如果某人的論文關於袋狼，他便深入研究過這種動物。"},{"en":"This phrase refers to advanced university research.","zh":"這個片語指高階大學研究。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":10},{"front":"despite scientific thinking","meaning":"儘管科學界認為","examples":[{"en":"Despite scientific thinking, some small populations may survive.","zh":"儘管科學界認為如此，一些小種群仍可能存活。"},{"en":"Despite scientific thinking means although scientific opinion or theory suggests something different.","zh":"despite scientific thinking 指雖然科學意見或理論暗示不同結果。"},{"en":"Despite scientific thinking at the time, doctors later found that some treatments were ineffective.","zh":"儘管當時科學界認為某些治療有效，醫生後來發現它們其實無效。"},{"en":"If a small population survives against expectations, it may challenge existing scientific assumptions.","zh":"如果小種群超出預期地存活，它可能挑戰現有科學假設。"},{"en":"This phrase introduces a contrast with accepted scientific views.","zh":"這個片語引入與既有科學看法的對比。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":10},{"front":"required to sustain a population","meaning":"維持種群所需","examples":[{"en":"Some scientists think 500 animals are required to sustain a population.","zh":"一些科學家認為維持一個種群需要500隻動物。"},{"en":"Required to sustain a population means needed to keep a group alive and breeding over time.","zh":"required to sustain a population 指維持群體長期生存和繁殖所需要的。"},{"en":"A school needs enough students each year to sustain a music programme.","zh":"學校每年需要足夠學生來維持音樂課程。"},{"en":"If too few animals remain, the population may not have enough genetic diversity to continue.","zh":"如果剩下的動物太少，種群可能沒有足夠遺傳多樣性延續。"},{"en":"This phrase describes the minimum support needed for survival.","zh":"這個片語描述生存所需的最低支持。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":10},{"front":"sustain a population","meaning":"維持一個種群","examples":[{"en":"A minimum number of animals may be needed to sustain a population.","zh":"可能需要最低數量的動物來維持一個種群。"},{"en":"To sustain a population means to keep it alive, breeding, and stable over time.","zh":"sustain a population 指令種群長期存活、繁殖並保持穩定。"},{"en":"A village needs enough young families to sustain its school and services.","zh":"村莊需要足夠年輕家庭來維持學校和服務。"},{"en":"If a species cannot sustain its population, its numbers will continue to fall.","zh":"如果物種不能維持其種群，數量會繼續下降。"},{"en":"This phrase focuses on long-term survival of a group.","zh":"這個片語聚焦於群體的長期生存。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":10},{"front":"Florida panther","meaning":"佛羅里達美洲獅","examples":[{"en":"The Florida panther survives with a very small population.","zh":"佛羅里達美洲獅以非常小的種群存活。"},{"en":"The Florida panther is a rare big cat found in Florida, USA.","zh":"Florida panther 是生活在美國佛羅里達州的罕見大型貓科動物。"},{"en":"Wildlife documentaries may use the Florida panther as an example of an endangered animal.","zh":"野生動物紀錄片可能用佛羅里達美洲獅作為瀕危動物的例子。"},{"en":"If a Florida panther population becomes too small, inbreeding can become a serious problem.","zh":"如果佛羅里達美洲獅種群變得太小，近親繁殖可能成為嚴重問題。"},{"en":"This phrase names a real species used as a survival example.","zh":"這個片語指出一種被用作生存例子的真實物種。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":10},{"front":"down to a dozen or so animals","meaning":"減至約十多隻動物","examples":[{"en":"The Florida panther is down to a dozen or so animals.","zh":"佛羅里達美洲獅已減至約十多隻動物。"},{"en":"Down to a dozen or so animals means reduced to only about twelve animals.","zh":"down to a dozen or so animals 指減少到大約十二隻動物。"},{"en":"A club may be down to a dozen or so members after many people move away.","zh":"如果許多人搬走，社團可能減至約十多名成員。"},{"en":"If a species is down to so few animals, every death can matter greatly.","zh":"如果一個物種只剩這麼少動物，每一次死亡都可能非常重要。"},{"en":"This phrase describes an extremely small remaining number.","zh":"這個片語描述極少的剩餘數量。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":10},{"front":"inbreeding problems","meaning":"近親繁殖問題","examples":[{"en":"The Florida panther has some inbreeding problems.","zh":"佛羅里達美洲獅有一些近親繁殖問題。"},{"en":"Inbreeding problems are health or genetic problems caused when closely related animals breed.","zh":"inbreeding problems 是近親動物繁殖所造成的健康或遺傳問題。"},{"en":"A small animal population may develop inbreeding problems if there are too few unrelated mates.","zh":"如果可配對的非親緣個體太少，小型動物種群可能出現近親繁殖問題。"},{"en":"Inbreeding can make offspring weaker or more likely to inherit harmful traits.","zh":"近親繁殖可能令後代更弱，或更容易遺傳有害特徵。"},{"en":"This phrase explains one danger of very small populations.","zh":"這個片語解釋非常小種群的一種危險。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":10},{"front":"still ticking along","meaning":"仍勉強維持下去","examples":[{"en":"The Florida panther is still ticking along despite its small numbers.","zh":"佛羅里達美洲獅儘管數量很少，仍勉強維持下去。"},{"en":"Still ticking along means still continuing to exist or function, though not strongly.","zh":"still ticking along 指仍然繼續存在或運作，但狀態不強。"},{"en":"An old family car may be still ticking along after many repairs.","zh":"舊家庭車經過多次維修後可能仍勉強維持運作。"},{"en":"If a species is still ticking along, it survives but may remain vulnerable.","zh":"如果一個物種仍勉強維持下去，它雖然存活，但可能仍脆弱。"},{"en":"This phrase suggests weak but continuing survival.","zh":"這個片語暗示微弱但持續的生存。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":11},{"front":"take a punt","meaning":"大膽估計","examples":[{"en":"Pemberton says he will take a punt about surviving thylacines.","zh":"Pemberton 說他會對倖存袋狼作出大膽估計。"},{"en":"To take a punt means to make a guess or take a chance when the answer is uncertain.","zh":"take a punt 指在答案不確定時作出猜測或冒一次險。"},{"en":"A student may take a punt on a multiple-choice answer when they cannot eliminate all options.","zh":"當學生不能排除所有選項時，可能在多項選擇題中大膽估計。"},{"en":"If evidence is incomplete, even experts may only make a cautious guess.","zh":"如果證據不完整，即使專家也可能只能謹慎猜測。"},{"en":"This phrase is informal and suggests uncertainty.","zh":"這個片語較口語，暗示不確定性。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":11},{"front":"in the scrub","meaning":"在灌木叢中","examples":[{"en":"If a thylacine is found in the scrub, others may exist nearby.","zh":"如果在灌木叢中發現一隻袋狼，附近可能還有其他袋狼存在。"},{"en":"In the scrub means in an area of low, thick bushes and rough vegetation.","zh":"in the scrub 指在低矮茂密的灌木和粗糙植被區域中。"},{"en":"A hiker may hear animals moving in the scrub beside a track.","zh":"行山者可能聽到小徑旁灌木叢中有動物移動。"},{"en":"If a rare animal hides in the scrub, it may avoid being seen for years.","zh":"如果罕見動物躲在灌木叢中，它可能多年不被看見。"},{"en":"This phrase describes a bushy natural habitat.","zh":"這個片語描述灌木密布的自然棲息地。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":11},{"front":"notoriously elusive","meaning":"出名難以尋獲","examples":[{"en":"Animals can be notoriously elusive.","zh":"動物可以出名難以尋獲。"},{"en":"Notoriously elusive means famous for being very difficult to find, see, or catch.","zh":"notoriously elusive 指因非常難找、難見或難捕而出名。"},{"en":"A shy student may be notoriously elusive when group photos are taken.","zh":"害羞學生拍大合照時可能出名難以找到。"},{"en":"If an animal is nocturnal and lives in dense forest, it may be notoriously elusive.","zh":"如果動物夜行並生活在茂密森林中，牠可能出名難以尋獲。"},{"en":"This phrase stresses how hard something is to locate.","zh":"這個片語強調某物有多難定位。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":11},{"front":"the strange fish known as","meaning":"被稱為……的奇異魚類","examples":[{"en":"The strange fish known as the coelacanth was thought to be extinct.","zh":"被稱為腔棘魚的奇異魚類曾被認為已經滅絕。"},{"en":"The strange fish known as introduces an unusual fish by its name.","zh":"the strange fish known as 用來以名稱引入一種不尋常魚類。"},{"en":"A teacher may describe the strange fish known as the coelacanth to show that rediscoveries can happen.","zh":"老師可能描述被稱為腔棘魚的奇異魚類，以顯示重新發現是可能的。"},{"en":"If a strange animal is poorly known, people may misunderstand its importance.","zh":"如果一種奇異動物鮮為人知，人們可能誤解其重要性。"},{"en":"This phrase introduces a named unusual creature.","zh":"這個片語引入一種有名稱的不尋常生物。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":11},{"front":"coelacanth","meaning":"腔棘魚","examples":[{"en":"The coelacanth was rediscovered after being thought extinct.","zh":"腔棘魚在被認為已滅絕後重新被發現。"},{"en":"The coelacanth is a rare ancient-looking fish once believed to have died out long ago.","zh":"coelacanth 是一種罕見、外貌古老的魚，曾被認為早已滅絕。"},{"en":"A science class may use the coelacanth as an example of a species rediscovered after presumed extinction.","zh":"科學課可能用腔棘魚作為在被假定滅絕後重新發現的物種例子。"},{"en":"If the coelacanth survived unnoticed, people may wonder whether other elusive animals could also remain hidden.","zh":"如果腔棘魚能未被察覺地存活，人們可能會想其他難尋動物是否也可能仍隱藏着。"},{"en":"This word names a famous “living fossil” fish.","zh":"這個詞指出著名的「活化石」魚。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":11},{"front":"proto-legs","meaning":"原始腿狀構造","examples":[{"en":"The coelacanth has features described as proto-legs.","zh":"腔棘魚具有被描述為原始腿狀構造的特徵。"},{"en":"Proto-legs are primitive leg-like structures that are not fully developed legs.","zh":"proto-legs 是原始的腿狀結構，但並不是完全發展的腿。"},{"en":"A biology diagram may show proto-legs to explain how fins and limbs are related.","zh":"生物圖表可能展示原始腿狀構造，以解釋鰭和四肢的關係。"},{"en":"If a fish has proto-legs, scientists may study it to understand evolution from water to land.","zh":"如果魚有原始腿狀構造，科學家可能研究牠以理解從水生到陸生的進化。"},{"en":"This phrase describes early or simple versions of legs.","zh":"這個片語描述早期或簡單版本的腿。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":11},{"front":"was thought to have died out","meaning":"被認為已經滅絕","examples":[{"en":"The coelacanth was thought to have died out with the dinosaurs.","zh":"腔棘魚曾被認為已與恐龍一起滅絕。"},{"en":"Was thought to have died out means people believed it had become extinct.","zh":"was thought to have died out 指人們相信它已經滅絕。"},{"en":"A bird may be thought to have died out if no one records it for many years.","zh":"如果某種鳥多年沒有被記錄，人們可能認為牠已經滅絕。"},{"en":"If a species thought extinct is rediscovered, scientists must revise their records.","zh":"如果被認為已滅絕的物種被重新發現，科學家必須修訂記錄。"},{"en":"This phrase shows past belief about extinction.","zh":"這個片語顯示過去關於滅絕的看法。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":11},{"front":"along with","meaning":"與……一起","examples":[{"en":"The coelacanth was thought to have died out along with the dinosaurs.","zh":"腔棘魚曾被認為與恐龍一起滅絕。"},{"en":"Along with means together with someone or something else.","zh":"along with 指與某人或某物一起。"},{"en":"A student may bring a notebook along with a laptop to class.","zh":"學生上課時可能帶手提電腦和筆記簿一起來。"},{"en":"If one species disappeared along with many others, scientists may link them to the same event.","zh":"如果一個物種與許多其他物種一起消失，科學家可能把它們連繫到同一事件。"},{"en":"This phrase shows that things happen or exist together.","zh":"這個片語顯示事物一起發生或存在。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":11},{"front":"a specimen was dragged to the surface","meaning":"一個標本被拖上海面","examples":[{"en":"A coelacanth specimen was dragged to the surface in 1938.","zh":"一個腔棘魚標本於1938年被拖上海面。"},{"en":"A specimen was dragged to the surface means one example of the animal was pulled up from underwater.","zh":"a specimen was dragged to the surface 指一個動物樣本從水下被拉上來。"},{"en":"Fishermen may drag a net to the surface and find an unexpected fish inside.","zh":"漁民可能把漁網拖上海面，發現裡面有一條意想不到的魚。"},{"en":"If a specimen is brought to the surface, scientists can examine it directly.","zh":"如果標本被帶上海面，科學家可以直接檢查它。"},{"en":"This phrase describes an animal being physically pulled up from water.","zh":"這個片語描述動物被實際從水中拉上來。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":11},{"front":"shark net","meaning":"捕鯊網","examples":[{"en":"The specimen was caught in a shark net.","zh":"該標本被捕鯊網捕獲。"},{"en":"A shark net is a strong net used to catch or block sharks.","zh":"shark net 是用來捕捉或阻隔鯊魚的堅固網。"},{"en":"A beach may use shark nets to reduce the chance of sharks swimming close to swimmers.","zh":"海灘可能使用捕鯊網，以減少鯊魚游近泳客的機會。"},{"en":"If a rare fish is caught in a shark net, it may be discovered by accident.","zh":"如果罕見魚類被捕鯊網捕獲，它可能是偶然被發現的。"},{"en":"This phrase refers to a fishing or safety net connected with sharks.","zh":"這個片語指與鯊魚相關的捕魚或安全網。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":11},{"front":"off the south-east coast of","meaning":"在……東南海岸對開","examples":[{"en":"The specimen was found off the south-east coast of South Africa.","zh":"該標本在南非東南海岸對開被發現。"},{"en":"Off the south-east coast of a place means in the sea near that area of land.","zh":"off the south-east coast of a place 指在該地東南海岸附近的海上。"},{"en":"A fishing boat may work off the coast of a small island.","zh":"漁船可能在小島海岸對開工作。"},{"en":"If a fish is found off a coast, its habitat may be in nearby deep water.","zh":"如果魚在某海岸對開被發現，其棲息地可能在附近深水區。"},{"en":"This phrase describes a location in the sea near land.","zh":"這個片語描述陸地附近海上的位置。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":12},{"front":"wildlife biologist","meaning":"野生動物生物學家","examples":[{"en":"Nick Mooney is a wildlife biologist.","zh":"Nick Mooney 是一名野生動物生物學家。"},{"en":"A wildlife biologist is a scientist who studies wild animals and their habitats.","zh":"wildlife biologist 是研究野生動物及其棲息地的科學家。"},{"en":"A wildlife biologist may track birds, study forests, or advise on conservation plans.","zh":"野生動物生物學家可能追蹤鳥類、研究森林或就保育計劃提供建議。"},{"en":"If a wildlife biologist investigates sightings, they look for evidence rather than rumours alone.","zh":"如果野生動物生物學家調查目擊個案，他們會尋找證據，而不只聽傳聞。"},{"en":"This phrase names a scientist who works with wild species.","zh":"這個片語指研究野生物種的科學家。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":12},{"front":"unenviable task","meaning":"不令人羨慕的任務","examples":[{"en":"Mooney has the unenviable task of investigating thylacine sightings.","zh":"Mooney 有一項不令人羨慕的任務，就是調查袋狼目擊個案。"},{"en":"An unenviable task is a difficult or unpleasant job that most people would not want.","zh":"unenviable task 是大多數人不想做的困難或不愉快工作。"},{"en":"A teacher may have the unenviable task of telling students a trip has been cancelled.","zh":"老師可能有一項不令人羨慕的任務，就是告訴學生旅行取消了。"},{"en":"If every report creates anger or disappointment, investigating sightings becomes unenviable.","zh":"如果每份報告都引起憤怒或失望，調查目擊便成為不令人羨慕的任務。"},{"en":"This phrase describes a responsibility that is hard rather than desirable.","zh":"這個片語描述艱難而非令人嚮往的責任。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":12},{"front":"investigating all sightings","meaning":"調查所有目擊個案","examples":[{"en":"Mooney investigates all reported sightings of the tiger.","zh":"Mooney 調查所有報稱的塔斯曼尼亞虎目擊個案。"},{"en":"Investigating all sightings means examining every report that someone has seen the animal.","zh":"investigating all sightings 指檢查每一個有人聲稱看見該動物的報告。"},{"en":"Police may investigate all sightings of a missing child in a neighbourhood.","zh":"警方可能調查社區中所有失蹤孩子目擊報告。"},{"en":"If every sighting is investigated, false reports can be separated from stronger evidence.","zh":"如果每個目擊個案都被調查，就能把虛假報告與較有力證據分開。"},{"en":"This phrase describes systematic checking of reports.","zh":"這個片語描述有系統地核查報告。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":12},{"front":"totalling 4,000","meaning":"總數達 4,000","examples":[{"en":"The sightings have totalled 4,000 since the mid-1980s.","zh":"自1980年代中期以來，目擊個案總數達4,000。"},{"en":"Totalling 4,000 means adding up to 4,000 in all.","zh":"totalling 4,000 指合計達到4,000。"},{"en":"A school may receive applications totalling 4,000 over several years.","zh":"一所學校多年來收到的申請可能總數達4,000。"},{"en":"If sightings total 4,000, the number is large enough to attract public attention.","zh":"如果目擊個案總數達4,000，這個數字大到足以引起公眾關注。"},{"en":"This phrase gives the combined total.","zh":"這個片語給出合計總數。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":12},{"front":"since the mid-1980s","meaning":"自 1980 年代中期以來","examples":[{"en":"Mooney has investigated sightings since the mid-1980s.","zh":"Mooney 自1980年代中期以來一直調查目擊個案。"},{"en":"Since the mid-1980s means from around the middle of the 1980s until now or until a later stated time.","zh":"since the mid-1980s 指從1980年代中期左右開始，一直到現在或後來提及的時間。"},{"en":"A shop that has operated since the mid-1980s has served several generations of customers.","zh":"自1980年代中期以來營業的店舖，已服務幾代顧客。"},{"en":"If reports have continued since the mid-1980s, the issue has lasted for decades.","zh":"如果報告自1980年代中期以來持續出現，這個問題已延續數十年。"},{"en":"This phrase marks a starting period in recent history.","zh":"這個片語標示近代歷史中的起始時期。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":12},{"front":"averaging about","meaning":"平均約為","examples":[{"en":"The reports average about 150 a year.","zh":"這些報告平均約為每年150宗。"},{"en":"Averaging about means having a typical or mean number close to a stated amount.","zh":"averaging about 指典型數量或平均數接近某個數字。"},{"en":"A tutor may teach lessons averaging about six hours a day during exam season.","zh":"在考試季，導師每天授課時間可能平均約為六小時。"},{"en":"If reports average about 150 a year, they arrive regularly rather than rarely.","zh":"如果報告平均約為每年150宗，它們是定期出現，而不是罕見。"},{"en":"This phrase describes an approximate average.","zh":"這個片語描述大約平均數。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":12},{"front":"consulted about","meaning":"就……被諮詢","examples":[{"en":"Mooney was consulted about the authenticity of the photographs.","zh":"Mooney 就照片真確性被諮詢。"},{"en":"To be consulted about something means to be asked for expert advice or opinion on it.","zh":"be consulted about something 指就某事被徵詢專家建議或意見。"},{"en":"A doctor may be consulted about unusual test results.","zh":"醫生可能就不尋常的檢查結果被諮詢。"},{"en":"If an expert is consulted about photos, they may check whether the evidence is genuine.","zh":"如果專家就照片被諮詢，他們可能檢查證據是否真實。"},{"en":"This phrase describes asking someone knowledgeable for judgement.","zh":"這個片語描述向有知識的人徵求判斷。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":12},{"front":"authenticity of","meaning":"……的真確性","examples":[{"en":"Mooney was asked about the authenticity of digital photographic images.","zh":"Mooney 被問及數碼照片影像的真確性。"},{"en":"Authenticity of something means whether it is real, genuine, and not fake.","zh":"authenticity of something 指某物是否真實、真確而非偽造。"},{"en":"A museum checks the authenticity of a painting before buying it.","zh":"博物館在購買畫作前會檢查其真確性。"},{"en":"If the authenticity of photos is doubtful, the sighting cannot be treated as proof.","zh":"如果照片的真確性可疑，該目擊就不能被視為證據。"},{"en":"This phrase focuses on whether evidence is genuine.","zh":"這個片語聚焦於證據是否真實。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":12},{"front":"digital photographic images","meaning":"數碼照片影像","examples":[{"en":"A German tourist submitted digital photographic images.","zh":"一名德國遊客提交了數碼照片影像。"},{"en":"Digital photographic images are photos stored or produced in electronic form.","zh":"digital photographic images 是以電子形式儲存或製作的照片。"},{"en":"A student may submit digital photographic images for a science project on plants.","zh":"學生可能為植物科學專題提交數碼照片影像。"},{"en":"If digital images are edited, experts may need to check their authenticity.","zh":"如果數碼影像被修改，專家可能需要檢查其真確性。"},{"en":"This phrase refers to photographs in digital format.","zh":"這個片語指數碼格式的照片。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":12},{"front":"purportedly taken by","meaning":"據稱由……拍攝","examples":[{"en":"The images were purportedly taken by a German tourist.","zh":"這些影像據稱由一名德國遊客拍攝。"},{"en":"Purportedly taken by means claimed to have been taken by someone, though this may need confirmation.","zh":"purportedly taken by 指聲稱由某人拍攝，但可能仍需確認。"},{"en":"A video purportedly taken by a witness may still need expert checking.","zh":"據稱由目擊者拍攝的影片，仍可能需要專家檢查。"},{"en":"If photos are only purportedly taken by someone, investigators must verify the source.","zh":"如果照片只是據稱由某人拍攝，調查人員必須核實來源。"},{"en":"This phrase signals that the claim has not been fully proven.","zh":"這個片語表示該聲稱尚未完全證實。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":12},{"front":"German tourist","meaning":"德國遊客","examples":[{"en":"A German tourist reportedly photographed the animal during a bushwalk.","zh":"據報一名德國遊客在叢林步行期間拍下該動物。"},{"en":"A German tourist is a visitor from Germany travelling for leisure or exploration.","zh":"German tourist 是來自德國、為休閒或探索而旅行的訪客。"},{"en":"A German tourist in Tasmania may visit forests, coastlines, and wildlife parks.","zh":"在塔斯曼尼亞的德國遊客可能參觀森林、海岸線和野生動物公園。"},{"en":"If a tourist photographs an unusual animal, experts may need to check the location and image details.","zh":"如果遊客拍下不尋常動物，專家可能需要檢查地點和影像細節。"},{"en":"This phrase identifies the nationality and role of the visitor.","zh":"這個片語指出訪客的國籍和身份。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":13},{"front":"recent bushwalk","meaning":"最近一次叢林步行","examples":[{"en":"The photographs were reportedly taken during a recent bushwalk.","zh":"據報這些照片是在最近一次叢林步行期間拍攝的。"},{"en":"A recent bushwalk is a walk through natural bushland that happened not long ago.","zh":"recent bushwalk 是不久前在自然灌木林地進行的步行。"},{"en":"A family may take a bushwalk on the weekend to enjoy birds, trees, and quiet tracks.","zh":"家庭可能在週末進行叢林步行，欣賞鳥類、樹木和安靜小徑。"},{"en":"If photos were taken on a recent bushwalk, investigators may still be able to inspect the location.","zh":"如果照片是在最近一次叢林步行中拍攝，調查人員可能仍能檢查該地點。"},{"en":"This phrase describes a recent walk in natural vegetation.","zh":"這個片語描述近期在自然植被中的步行。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":13},{"front":"in the state","meaning":"在該州","examples":[{"en":"The tourist was bushwalking in the state.","zh":"該遊客在該州進行叢林步行。"},{"en":"In the state means within that state or regional area.","zh":"in the state 指在該州或該地區範圍內。"},{"en":"A student studying in the state may still travel home during holidays.","zh":"在該州讀書的學生假期仍可能回家。"},{"en":"If a sighting occurs in the state, local wildlife experts may be asked to investigate.","zh":"如果目擊發生在該州，本地野生動物專家可能被要求調查。"},{"en":"This phrase refers to location inside a named state.","zh":"這個片語指位於某個已提及州份之內。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":13},{"front":"at face value","meaning":"表面看來","examples":[{"en":"At face value, the account and photographs seemed convincing.","zh":"表面看來，這個描述和照片似乎有說服力。"},{"en":"At face value means based only on how something first appears, without deeper checking.","zh":"at face value 指只根據某事最初表面呈現來判斷，而未深入檢查。"},{"en":"At face value, an advertisement may seem like a great deal.","zh":"表面看來，一則廣告可能像是非常划算的優惠。"},{"en":"If evidence looks convincing at face value, experts may still examine it carefully.","zh":"如果證據表面看來有說服力，專家仍可能仔細檢查。"},{"en":"This phrase warns that first impressions may not be enough.","zh":"這個片語提醒第一印象可能不足夠。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":13},{"front":"submitted as proof","meaning":"作為證據提交","examples":[{"en":"The photographs were submitted as proof of the sighting.","zh":"這些照片作為目擊證據提交。"},{"en":"Submitted as proof means given to others as evidence supporting a claim.","zh":"submitted as proof 指把某物交給他人作為支持某主張的證據。"},{"en":"A student may submit a doctor’s note as proof of illness.","zh":"學生可能提交醫生紙作為生病證明。"},{"en":"If photos are submitted as proof, their quality and authenticity matter greatly.","zh":"如果照片作為證據提交，其質素和真確性非常重要。"},{"en":"This phrase describes evidence being formally offered.","zh":"這個片語描述正式提供證據。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":13},{"front":"amount to","meaning":"等同於；構成","examples":[{"en":"The report and photographs amount to a convincing case.","zh":"報告和照片構成一個有說服力的個案。"},{"en":"Amount to means add up to or be equivalent to a certain result or judgement.","zh":"amount to 指加起來等同於某結果或判斷。"},{"en":"Several missed deadlines may amount to a serious work problem.","zh":"幾次錯過截止日期可能構成嚴重工作問題。"},{"en":"If a clear account and good photos fit together, they may amount to strong evidence.","zh":"如果清楚描述和高質照片互相配合，它們可能構成有力證據。"},{"en":"This phrase shows that separate things combine into one conclusion.","zh":"這個片語顯示分開的事物合起來形成一個結論。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":13},{"front":"convincing cases","meaning":"有說服力的個案","examples":[{"en":"Mooney considered it one of the most convincing cases he had seen.","zh":"Mooney 認為這是他見過最有說服力的個案之一。"},{"en":"Convincing cases are reports or arguments strong enough to seem believable.","zh":"convincing cases 是強到令人覺得可信的報告或論點。"},{"en":"A clear medical record and repeated symptoms can make a convincing case for further tests.","zh":"清楚醫療記錄和反覆症狀可以構成進一步檢查的有說服力個案。"},{"en":"If a sighting case has photos, dates, location, and a reliable witness, it becomes more convincing.","zh":"如果目擊個案有照片、日期、地點和可靠目擊者，它會變得更有說服力。"},{"en":"This phrase describes evidence that is hard to dismiss.","zh":"這個片語描述難以輕易否定的證據。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":13},{"front":"species’ survival","meaning":"物種存活","examples":[{"en":"The case may support the possibility of the species’ survival.","zh":"這個個案可能支持該物種仍然存活的可能性。"},{"en":"Species’ survival means the continued existence of a species.","zh":"species’ survival 指一個物種的持續存在。"},{"en":"Clean rivers can be important for a fish species’ survival.","zh":"清潔河流對某魚類物種存活可能很重要。"},{"en":"If even a few individuals remain, a species’ survival may still be possible but fragile.","zh":"如果即使只剩少數個體，物種存活仍可能存在，但很脆弱。"},{"en":"This phrase focuses on whether a species continues to live.","zh":"這個片語聚焦於物種是否繼續生存。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":13},{"front":"seen it all","meaning":"見盡各種情況","examples":[{"en":"Mooney has seen it all in reports of thylacine sightings.","zh":"Mooney 在袋狼目擊報告中見盡各種情況。"},{"en":"Seen it all means experienced many different situations, including strange or difficult ones.","zh":"seen it all 指經歷過許多不同情況，包括奇怪或困難的情況。"},{"en":"A school nurse who has worked for thirty years has seen it all, from small cuts to panic attacks.","zh":"工作三十年的校護見盡各種情況，從小傷口到恐慌發作都有。"},{"en":"If someone has seen it all, they may be calm and sceptical when new claims appear.","zh":"如果某人見盡各種情況，當新聲稱出現時，他可能較冷靜和懷疑。"},{"en":"This phrase suggests wide experience.","zh":"這個片語暗示廣泛經驗。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":13},{"front":"hoaxes","meaning":"惡作劇；騙局","examples":[{"en":"Mooney has seen mistakes, hoaxes and plausible accounts.","zh":"Mooney 見過錯誤、惡作劇和貌似可信的描述。"},{"en":"Hoaxes are deliberate tricks or false claims meant to deceive people.","zh":"hoaxes 是故意欺騙別人的惡作劇或虛假聲稱。"},{"en":"A fake photo of a rare animal can become a hoax if someone presents it as real.","zh":"如果有人把罕見動物的假照片當成真實呈現，它就可能成為騙局。"},{"en":"Hoaxes waste experts’ time and make genuine reports harder to trust.","zh":"惡作劇會浪費專家時間，並令真正報告更難被信任。"},{"en":"This word refers to intentional deception, not honest mistakes.","zh":"這個詞指故意欺騙，而不是誠實錯誤。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":13},{"front":"illusions","meaning":"錯覺","examples":[{"en":"Some reported sightings may be illusions.","zh":"一些報稱目擊可能是錯覺。"},{"en":"Illusions are things that appear real but are caused by mistaken perception.","zh":"illusions 是看似真實但由感知錯誤造成的事物。"},{"en":"In fog, a tree branch may create the illusion of a person standing nearby.","zh":"在霧中，樹枝可能造成附近站着一個人的錯覺。"},{"en":"If light, fear, and distance affect perception, witnesses may sincerely report illusions.","zh":"如果光線、恐懼和距離影響感知，目擊者可能真誠地報告錯覺。"},{"en":"This word describes false appearances, not deliberate lies.","zh":"這個詞描述錯誤表象，而不是故意說謊。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":13},{"front":"plausible accounts","meaning":"貌似可信的描述","examples":[{"en":"Some people give plausible accounts of thylacine sightings.","zh":"有些人提供貌似可信的袋狼目擊描述。"},{"en":"Plausible accounts are descriptions that seem reasonable and possible.","zh":"plausible accounts 是看起來合理且可能發生的描述。"},{"en":"A student may give a plausible account of why homework was late if the explanation fits the facts.","zh":"如果解釋符合事實，學生可能給出一個貌似可信的遲交功課原因。"},{"en":"If an account is plausible, experts may investigate it even without final proof.","zh":"如果描述貌似可信，即使沒有最終證據，專家也可能調查。"},{"en":"This phrase describes reports that sound believable.","zh":"這個片語描述聽起來可信的報告。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":14},{"front":"hoaxers aside","meaning":"撇開惡作劇者不談","examples":[{"en":"Hoaxers aside, many witnesses believe they saw a thylacine.","zh":"撇開惡作劇者不談，許多目擊者相信自己看見了袋狼。"},{"en":"Hoaxers aside means not counting people who deliberately make false claims.","zh":"hoaxers aside 指不計算故意作出虛假聲稱的人。"},{"en":"Cheaters aside, most students tried to answer the test honestly.","zh":"撇開作弊者不談，大多數學生都誠實地嘗試回答測驗。"},{"en":"If hoaxers are excluded, some reports may still come from sincere witnesses.","zh":"如果排除惡作劇者，有些報告仍可能來自真誠目擊者。"},{"en":"This phrase separates dishonest people from the rest of the group.","zh":"這個片語把不誠實的人與其餘群體分開。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":14},{"front":"end up believing","meaning":"最終相信","examples":[{"en":"Most people who report sightings end up believing they saw a thylacine.","zh":"大多數報告目擊的人最終相信自己看見了袋狼。"},{"en":"To end up believing something means to finally become convinced of it.","zh":"end up believing something 指最後變得相信某事。"},{"en":"A student may end up believing a rumour if many classmates repeat it.","zh":"如果許多同學重複謠言，學生可能最終相信它。"},{"en":"If a witness keeps retelling an uncertain event, they may become more certain over time.","zh":"如果目擊者不斷重述不確定事件，他們可能隨時間變得更確定。"},{"en":"This phrase describes how belief develops as a final result.","zh":"這個片語描述信念如何作為最終結果形成。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":14},{"front":"believable to the point that","meaning":"可信到……的程度","examples":[{"en":"Some witnesses are believable to the point that they could pass a lie-detector test.","zh":"有些目擊者可信到可能通過測謊測試的程度。"},{"en":"Believable to the point that means so convincing that a strong result or consequence seems possible.","zh":"believable to the point that 指可信到某種強烈結果或後果似乎可能發生。"},{"en":"A student’s explanation may be believable to the point that the teacher accepts it without punishment.","zh":"學生的解釋可能可信到老師不作懲罰便接受的程度。"},{"en":"If witnesses sincerely believe their story, they may sound convincing even if they are mistaken.","zh":"如果目擊者真誠相信自己的故事，即使他們錯了，也可能聽起來很有說服力。"},{"en":"This phrase describes a very high level of apparent credibility.","zh":"這個片語描述非常高的表面可信度。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":14},{"front":"pass a lie-detector test","meaning":"通過測謊測試","examples":[{"en":"Some witnesses could probably pass a lie-detector test.","zh":"有些目擊者大概可以通過測謊測試。"},{"en":"To pass a lie-detector test means to be judged as telling the truth by a machine that measures stress responses.","zh":"pass a lie-detector test 指被一部測量壓力反應的機器判定為說真話。"},{"en":"A person may pass a lie-detector test if they truly believe what they are saying.","zh":"如果一個人真心相信自己所說的，他可能通過測謊測試。"},{"en":"Passing such a test does not always prove that the event really happened.","zh":"通過這種測試不一定證明事件真的發生。"},{"en":"This phrase focuses on perceived honesty, not necessarily factual accuracy.","zh":"這個片語聚焦於被認為誠實，而不一定是事實準確。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":14},{"front":"according to","meaning":"根據……","examples":[{"en":"According to Mooney, many witnesses sincerely believe their reports.","zh":"根據 Mooney 所說，許多目擊者真誠相信自己的報告。"},{"en":"According to means based on what someone says or what a source states.","zh":"according to 指根據某人所說或某來源所述。"},{"en":"According to the timetable, the next bus arrives at 8:30.","zh":"根據時間表，下一班巴士8:30到達。"},{"en":"If a claim is according to an expert, readers may treat it as more reliable.","zh":"如果某主張根據專家所說，讀者可能視其為較可靠。"},{"en":"This phrase introduces a source of information.","zh":"這個片語引入資訊來源。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":14},{"front":"tabled a creditable report","meaning":"提交可信報告","examples":[{"en":"Some people have tabled a creditable report before becoming obsessed.","zh":"有些人在變得沉迷之前曾提交可信報告。"},{"en":"To table a creditable report means to formally present a report that seems believable.","zh":"table a creditable report 指正式提交一份看似可信的報告。"},{"en":"A committee member may table a creditable report about safety problems in a school building.","zh":"委員會成員可能提交一份關於校舍安全問題的可信報告。"},{"en":"If a person first submits a reasonable report, their later obsession may be easier to understand.","zh":"如果一個人最初提交合理報告，他後來的沉迷可能較容易理解。"},{"en":"This phrase describes presenting a report that deserves consideration.","zh":"這個片語描述提交一份值得考慮的報告。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":14},{"front":"creditable report","meaning":"可信的報告","examples":[{"en":"A creditable report may still lead to obsession.","zh":"可信的報告仍可能導致沉迷。"},{"en":"A creditable report is a report that seems trustworthy and deserves serious attention.","zh":"creditable report 是看起來可信並值得認真注意的報告。"},{"en":"A detailed accident report with names, times, and photos may be creditable.","zh":"有姓名、時間和照片的詳細事故報告可能是可信的。"},{"en":"If a report is creditable, officials may investigate even if they remain cautious.","zh":"如果報告可信，官員可能調查，即使仍保持謹慎。"},{"en":"This phrase describes a report that is not easily dismissed.","zh":"這個片語描述不容易被否定的報告。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":14},{"front":"utterly obsessed","meaning":"完全沉迷","examples":[{"en":"Some witnesses become utterly obsessed with finding thylacines.","zh":"有些目擊者變得完全沉迷於尋找袋狼。"},{"en":"Utterly obsessed means completely unable to stop thinking about something.","zh":"utterly obsessed 指完全無法停止想着某事。"},{"en":"A student may become utterly obsessed with exam rankings and forget to rest.","zh":"學生可能完全沉迷於考試排名而忘記休息。"},{"en":"If a person is utterly obsessed, the interest can damage money, family, and health.","zh":"如果一個人完全沉迷，這種興趣可以損害金錢、家庭和健康。"},{"en":"This phrase describes extreme and unhealthy fixation.","zh":"這個片語描述極端且不健康的執着。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":14},{"front":"registered 99 sightings","meaning":"登記了 99 次目擊","examples":[{"en":"One Tasmanian has registered 99 thylacine sightings.","zh":"一名塔斯曼尼亞人登記了99次袋狼目擊。"},{"en":"Registered 99 sightings means officially recorded 99 reports of seeing the animal.","zh":"registered 99 sightings 指正式記錄了99次看見該動物的報告。"},{"en":"A birdwatcher may register several sightings of a rare species on a wildlife database.","zh":"觀鳥者可能在野生動物資料庫中登記幾次罕見物種目擊。"},{"en":"If one person registers many sightings, experts may question whether belief is affecting interpretation.","zh":"如果一個人登記許多次目擊，專家可能質疑信念是否影響詮釋。"},{"en":"This phrase describes repeated formal reporting.","zh":"這個片語描述反覆正式報告。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":14},{"front":"to date","meaning":"至今","examples":[{"en":"One person has registered 99 sightings to date.","zh":"一個人至今登記了99次目擊。"},{"en":"To date means up to the present time or up to the time being discussed.","zh":"to date 指直到現在或直到正在討論的時間為止。"},{"en":"To date, the school has received 200 applications.","zh":"至今，學校已收到200份申請。"},{"en":"If reports continue to date, the subject is still active rather than only historical.","zh":"如果報告至今仍繼續，這個主題就仍然活躍，而不只是歷史。"},{"en":"This phrase marks the total so far.","zh":"這個片語標示到目前為止的總數。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":14},{"front":"bankrupted by the obsession","meaning":"因沉迷而破產","examples":[{"en":"Some individuals have been bankrupted by the obsession.","zh":"有些人因沉迷而破產。"},{"en":"Bankrupted by the obsession means losing all or most money because of an unhealthy fixation.","zh":"bankrupted by the obsession 指因不健康執着而失去全部或大部分金錢。"},{"en":"A person may be bankrupted by gambling if they cannot stop chasing losses.","zh":"如果某人無法停止追輸，可能因賭博而破產。"},{"en":"If someone spends all their savings on searches, obsession can become financially destructive.","zh":"如果有人把所有積蓄花在搜索上，沉迷可能造成財務毀滅。"},{"en":"This phrase shows a severe consequence of fixation.","zh":"這個片語顯示執着的嚴重後果。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":15},{"front":"families destroyed","meaning":"家庭被摧毀","examples":[{"en":"Mooney has seen families destroyed by the obsession.","zh":"Mooney 見過家庭因這種沉迷而被摧毀。"},{"en":"Families destroyed means family relationships were seriously damaged or broken apart.","zh":"families destroyed 指家庭關係被嚴重破壞或拆散。"},{"en":"Heavy debt can leave families destroyed if trust and stability collapse.","zh":"如果信任和穩定崩潰，沉重債務可能令家庭被摧毀。"},{"en":"If obsession takes all time and money, family members may suffer deeply.","zh":"如果沉迷奪走所有時間和金錢，家庭成員可能深受其害。"},{"en":"This phrase describes serious emotional and social damage.","zh":"這個片語描述嚴重的情感和社會傷害。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":15},{"front":"blind optimism","meaning":"盲目樂觀","examples":[{"en":"Mooney describes the belief as blind optimism.","zh":"Mooney 把這種信念描述為盲目樂觀。"},{"en":"Blind optimism means hopeful belief that ignores evidence or risk.","zh":"blind optimism 指忽視證據或風險的樂觀信念。"},{"en":"A student shows blind optimism if they expect top marks without studying.","zh":"如果學生不溫習卻期待高分，就是盲目樂觀。"},{"en":"If people want an extinct animal to survive, blind optimism may make weak evidence seem strong.","zh":"如果人們希望已滅絕動物仍存活，盲目樂觀可能令薄弱證據看似有力。"},{"en":"This phrase criticises hope that is not balanced by reason.","zh":"這個片語批評缺乏理性平衡的希望。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":15},{"front":"rather than","meaning":"而不是","examples":[{"en":"It is blind optimism rather than healthy scepticism.","zh":"這是盲目樂觀，而不是健康的懷疑態度。"},{"en":"Rather than means instead of one thing, another thing is true or preferred.","zh":"rather than 指不是某事，而是另一事成立或較被選擇。"},{"en":"The problem may be poor planning rather than laziness.","zh":"問題可能是計劃差，而不是懶惰。"},{"en":"If a belief is based on hope rather than evidence, it may lead to wrong conclusions.","zh":"如果信念建基於希望而不是證據，它可能導致錯誤結論。"},{"en":"This phrase clearly separates two possible explanations.","zh":"這個片語清楚分開兩種可能解釋。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":15},{"front":"cynicism","meaning":"憤世嫉俗；懷疑態度","examples":[{"en":"Mooney contrasts blind optimism with cynicism.","zh":"Mooney 把盲目樂觀與憤世嫉俗作對比。"},{"en":"Cynicism is a distrustful attitude that expects people or claims to be false, selfish, or foolish.","zh":"cynicism 是一種不信任態度，預期人或主張是假的、自私的或愚蠢的。"},{"en":"A student may show cynicism if they assume every school rule is made for control, not learning.","zh":"如果學生假設每條校規都是為了控制而不是學習，他可能表現出憤世嫉俗。"},{"en":"Too much cynicism can make people reject sincere reports too quickly.","zh":"太多憤世嫉俗可能令人太快否定真誠報告。"},{"en":"This word describes harsh doubt, often stronger than healthy scepticism.","zh":"這個詞描述嚴苛懷疑，通常比健康懷疑更強。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":15},{"front":"crosses the road","meaning":"橫過馬路","examples":[{"en":"If something crosses the road, some people assume it is a thylacine.","zh":"如果有東西橫過馬路，有些人就假設那是袋狼。"},{"en":"Crosses the road means moves from one side of the road to the other.","zh":"crosses the road 指從馬路一邊移到另一邊。"},{"en":"A driver slows down when a dog crosses the road.","zh":"當狗橫過馬路時，司機會減速。"},{"en":"If people expect to see a thylacine, any animal crossing the road may be misidentified.","zh":"如果人們期待看到袋狼，任何橫過馬路的動物都可能被誤認。"},{"en":"This phrase describes a simple movement across a road.","zh":"這個片語描述穿越馬路的簡單移動。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":15},{"front":"a bit like","meaning":"有點像","examples":[{"en":"Mooney compares the belief to a gold prospector’s blind faith.","zh":"Mooney 把這種信念比作探金者的盲目信念。"},{"en":"A bit like means somewhat similar to, but not exactly the same as.","zh":"a bit like 指有些相似，但不完全相同。"},{"en":"Learning a language is a bit like training a muscle because progress comes from repeated practice.","zh":"學語言有點像訓練肌肉，因為進步來自反覆練習。"},{"en":"If a belief is a bit like gambling, hope may remain even when evidence is weak.","zh":"如果一種信念有點像賭博，即使證據薄弱，希望仍可能存在。"},{"en":"This phrase introduces an informal comparison.","zh":"這個片語引入較口語的比較。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":15},{"front":"gold prospector","meaning":"探金者","examples":[{"en":"A gold prospector may have blind faith that gold is there.","zh":"探金者可能盲目相信黃金就在那裡。"},{"en":"A gold prospector is a person who searches for gold, often in rivers, rocks, or old mining areas.","zh":"gold prospector 是尋找黃金的人，常在河流、岩石或舊礦區中搜尋。"},{"en":"A gold prospector may spend weeks digging without finding anything valuable.","zh":"探金者可能挖掘數星期也找不到有價值的東西。"},{"en":"If prospectors believe strongly enough, they may continue searching despite little evidence.","zh":"如果探金者信念夠強，即使證據很少也可能繼續尋找。"},{"en":"This phrase describes someone seeking hidden treasure or minerals.","zh":"這個片語描述尋找隱藏財寶或礦物的人。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":15},{"front":"blind faith","meaning":"盲目信念","examples":[{"en":"The belief resembles a gold prospector’s blind faith.","zh":"這種信念類似探金者的盲目信念。"},{"en":"Blind faith is strong belief without enough evidence or questioning.","zh":"blind faith 是缺乏足夠證據或質疑的強烈信念。"},{"en":"A person has blind faith in a diet if they ignore medical advice and believe it cures everything.","zh":"如果某人忽視醫療建議，卻相信某種飲食能治好一切，就是對它有盲目信念。"},{"en":"Blind faith can keep people going, but it can also lead them to waste time and money.","zh":"盲目信念可以讓人堅持下去，但也可能令他們浪費時間和金錢。"},{"en":"This phrase criticises belief that refuses to examine evidence.","zh":"這個片語批評拒絕檢視證據的信念。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":15},{"front":"has got to be there","meaning":"一定在那裏","examples":[{"en":"The prospector believes that the treasure has got to be there.","zh":"探金者相信寶藏一定在那裏。"},{"en":"Has got to be there means must be there, usually expressing strong belief rather than proof.","zh":"has got to be there 指一定在那裡，通常表達強烈信念而非證據。"},{"en":"A student searching for a lost phone may say, “It has got to be here somewhere.”","zh":"學生尋找遺失手機時可能說：「它一定在這裡某處。」"},{"en":"If people feel certain without evidence, they may keep searching long after reason suggests stopping.","zh":"如果人們在沒有證據下感到確定，可能在理性建議停止後仍繼續尋找。"},{"en":"This phrase expresses stubborn certainty.","zh":"這個片語表達固執的確定感。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":15},{"front":"treats all reports at face value","meaning":"按表面可信程度看待所有報告","examples":[{"en":"Mooney treats all reports at face value.","zh":"Mooney 按表面可信程度看待所有報告。"},{"en":"To treat all reports at face value means to listen to them initially as they are presented, without immediately mocking or rejecting them.","zh":"treat all reports at face value 指先按報告呈現的樣子聆聽，而不是立即嘲笑或否定。"},{"en":"A teacher may treat a student’s complaint at face value before checking both sides.","zh":"老師可能先按表面可信程度看待學生投訴，再查核雙方說法。"},{"en":"If experts treat reports respectfully, witnesses may feel safe giving details.","zh":"如果專家尊重地看待報告，目擊者可能更願意提供細節。"},{"en":"This phrase describes taking claims seriously at first, even before verification.","zh":"這個片語描述在核實前先認真看待聲稱。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":15},{"front":"embarrass people","meaning":"令別人尷尬","examples":[{"en":"Mooney never tries to embarrass people who report sightings.","zh":"Mooney 從不嘗試令報告目擊的人尷尬。"},{"en":"To embarrass people means to make them feel ashamed, foolish, or uncomfortable in front of others.","zh":"embarrass people 指令人在他人面前感到羞愧、愚蠢或不自在。"},{"en":"A teacher should not embarrass a student for giving a wrong answer.","zh":"老師不應因學生答錯而令他尷尬。"},{"en":"If witnesses fear embarrassment, they may stop reporting useful information.","zh":"如果目擊者害怕尷尬，他們可能不再報告有用資訊。"},{"en":"This phrase describes causing social discomfort or shame.","zh":"這個片語描述造成社交不適或羞恥。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":16},{"front":"make fools of them","meaning":"令他們出醜","examples":[{"en":"Mooney does not try to make fools of witnesses.","zh":"Mooney 不會嘗試令目擊者出醜。"},{"en":"To make fools of people means to make them look stupid or ridiculous.","zh":"make fools of people 指令某人看起來愚蠢或荒唐。"},{"en":"A manager should correct mistakes privately rather than make fools of staff in a meeting.","zh":"經理應私下糾正錯誤，而不是在會議中令員工出醜。"},{"en":"If investigators make fools of witnesses, sincere people may refuse to speak again.","zh":"如果調查人員令目擊者出醜，真誠的人可能不再發言。"},{"en":"This phrase describes humiliating someone.","zh":"這個片語描述羞辱某人。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":16},{"front":"pack the car","meaning":"收拾車輛準備出發","examples":[{"en":"Mooney does not pack the car immediately after every report.","zh":"Mooney 不會在每份報告後立即收拾車輛準備出發。"},{"en":"To pack the car means to load the car with things needed for a trip or investigation.","zh":"pack the car 指把旅行或調查所需物品放進車內。"},{"en":"A family may pack the car with food, jackets, and tents before camping.","zh":"家庭露營前可能把食物、外套和帳篷放進車裡。"},{"en":"If an expert packed the car after every weak report, they would waste much time and fuel.","zh":"如果專家在每份薄弱報告後都收拾車輛出發，會浪費很多時間和汽油。"},{"en":"This phrase describes preparing to leave by car.","zh":"這個片語描述為駕車離開作準備。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":16},{"front":"taken as ridicule","meaning":"被理解為嘲笑","examples":[{"en":"His delay can be taken as ridicule by some callers.","zh":"他的延遲可能被一些來電者理解為嘲笑。"},{"en":"Taken as ridicule means interpreted as mockery or disrespect.","zh":"taken as ridicule 指被解讀為嘲弄或不尊重。"},{"en":"A teacher’s smile may be taken as ridicule if a nervous student already feels embarrassed.","zh":"如果緊張學生已感到尷尬，老師的微笑可能被理解為嘲笑。"},{"en":"If people are emotionally invested, even a cautious delay may feel like an insult.","zh":"如果人們情感投入很深，即使謹慎延遲也可能感覺像侮辱。"},{"en":"This phrase describes how an action is understood negatively by others.","zh":"這個片語描述某行動如何被他人負面理解。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":16},{"front":"obsessive characters","meaning":"着迷成癡的人","examples":[{"en":"Obsessive characters may become angry when Mooney does not act immediately.","zh":"着迷成癡的人在 Mooney 沒有立即行動時可能變得憤怒。"},{"en":"Obsessive characters are people strongly fixated on something in an unhealthy or excessive way.","zh":"obsessive characters 是以不健康或過度方式強烈執着於某事的人。"},{"en":"An obsessive character may check exam rankings every hour and ignore sleep.","zh":"着迷成癡的人可能每小時查看考試排名，並忽略睡眠。"},{"en":"If people become obsessive, they may react badly when others do not share their urgency.","zh":"如果人們變得着迷成癡，當別人不分享其急切感時，可能反應很差。"},{"en":"This phrase describes people dominated by a fixed idea.","zh":"這個片語描述被固定想法支配的人。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":16},{"front":"get irate","meaning":"變得憤怒","examples":[{"en":"Some obsessive callers get irate when Mooney does not investigate immediately.","zh":"一些着迷的來電者在 Mooney 沒有立即調查時變得憤怒。"},{"en":"To get irate means to become very angry.","zh":"get irate 指變得非常憤怒。"},{"en":"A customer may get irate if a delivery is delayed and no one explains why.","zh":"如果送貨延遲又沒有人解釋原因，顧客可能變得憤怒。"},{"en":"If people feel ignored, they may become angry even when the delay is reasonable.","zh":"如果人們覺得被忽視，即使延遲合理，也可能變得生氣。"},{"en":"This phrase describes a sudden rise in anger.","zh":"這個片語描述怒氣突然上升。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":16},{"front":"someone in my position","meaning":"像我這個職位的人","examples":[{"en":"Mooney says people expect someone in his position to go out immediately.","zh":"Mooney 說人們期望像他這個職位的人立即出發。"},{"en":"Someone in my position means a person with my job, responsibility, or situation.","zh":"someone in my position 指擁有我這份工作、責任或處境的人。"},{"en":"A teacher might say, “Someone in my position must treat every student fairly.”","zh":"老師可能說：「像我這個職位的人必須公平對待每位學生。」"},{"en":"If people expect action from someone in an official position, pressure can become intense.","zh":"如果人們期望官方職位上的人採取行動，壓力可能變得很大。"},{"en":"This phrase refers to the duties attached to a role.","zh":"這個片語指某角色所附帶的職責。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":16},{"front":"out there","meaning":"在外面；仍存在","examples":[{"en":"Some witnesses believe the thylacine is out there.","zh":"一些目擊者相信袋狼仍在外面存在。"},{"en":"Out there means existing somewhere in the world, though not yet found or confirmed.","zh":"out there 指存在於世界某處，雖然尚未被找到或確認。"},{"en":"A job seeker may believe the right opportunity is out there.","zh":"求職者可能相信合適機會仍在某處。"},{"en":"If people believe an animal is out there, they may keep searching despite limited evidence.","zh":"如果人們相信某動物仍存在，他們可能在證據有限下繼續搜索。"},{"en":"This phrase suggests hope that something exists somewhere.","zh":"這個片語暗示希望某物存在於某處。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":16},{"front":"the highlight of","meaning":"……的高峰；最精彩部分","examples":[{"en":"Naarding’s sighting was the highlight of his life of animal spotting.","zh":"Naarding 的目擊是他觀察動物生涯的高峰。"},{"en":"The highlight of something is the most exciting, important, or memorable part of it.","zh":"highlight of something 是某事中最令人興奮、最重要或最難忘的部分。"},{"en":"Winning the school debate was the highlight of her final year.","zh":"贏得校際辯論是她最後一年的最精彩部分。"},{"en":"If a wildlife expert sees an animal thought extinct, it may become the highlight of their career.","zh":"如果野生動物專家看見被認為已滅絕的動物，那可能成為其職業生涯高峰。"},{"en":"This phrase describes the best or most memorable moment.","zh":"這個片語描述最好或最難忘的時刻。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":16},{"front":"animal spotting","meaning":"觀察動物","examples":[{"en":"Naarding described his career as a life of animal spotting.","zh":"Naarding 把自己的職業生涯描述為觀察動物的一生。"},{"en":"Animal spotting means looking for, observing, and identifying animals, often in nature.","zh":"animal spotting 指尋找、觀察和識別動物，通常在自然環境中進行。"},{"en":"A family may go animal spotting in a wetland and record birds in a notebook.","zh":"家庭可能到濕地觀察動物，並在筆記簿記錄鳥類。"},{"en":"If someone spends years animal spotting, they may become skilled at noticing small movement or markings.","zh":"如果某人多年觀察動物，可能變得擅長注意細微動作或斑紋。"},{"en":"This phrase describes careful observation of animals.","zh":"這個片語描述對動物的仔細觀察。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":16},{"front":"remains bemused by","meaning":"仍對……感到困惑","examples":[{"en":"Naarding remains bemused by the time and money spent on tiger searches.","zh":"Naarding 仍對花在尋找塔斯曼尼亞虎上的時間和金錢感到困惑。"},{"en":"Remains bemused by means continues to feel puzzled or slightly confused by something.","zh":"remains bemused by 指繼續對某事感到困惑或略為不解。"},{"en":"A teacher may remain bemused by students who study all night but refuse to sleep earlier.","zh":"老師可能仍對那些通宵溫習卻拒絕早睡的學生感到困惑。"},{"en":"If someone thinks money could be used better elsewhere, they may be puzzled by expensive searches.","zh":"如果某人認為金錢可更好地用在別處，他可能對昂貴搜索感到困惑。"},{"en":"This phrase describes continuing mild confusion.","zh":"這個片語描述持續的輕微困惑。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":16},{"front":"waste on","meaning":"浪費在……上","examples":[{"en":"He is bemused by the resources people waste on tiger searches.","zh":"他對人們浪費在尋找塔斯曼尼亞虎上的資源感到困惑。"},{"en":"To waste resources on something means to spend time, money, or effort on it without enough benefit.","zh":"waste resources on something 指把時間、金錢或精力花在回報不足的事情上。"},{"en":"A school should not waste money on unused equipment when students need textbooks.","zh":"當學生需要教科書時，學校不應把錢浪費在沒人使用的設備上。"},{"en":"If searches rarely produce evidence, critics may say the resources are wasted.","zh":"如果搜索很少產生證據，批評者可能說資源被浪費了。"},{"en":"This phrase describes inefficient or unwise use of resources.","zh":"這個片語描述低效或不明智地使用資源。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":17},{"front":"tiger searches","meaning":"尋找塔斯曼尼亞虎的行動","examples":[{"en":"Naarding questions the value of tiger searches.","zh":"Naarding 質疑尋找塔斯曼尼亞虎行動的價值。"},{"en":"Tiger searches are organised attempts to find the Tasmanian tiger.","zh":"tiger searches 是有組織地嘗試尋找塔斯曼尼亞虎的行動。"},{"en":"Volunteers may join tiger searches in remote forests after a reported sighting.","zh":"有目擊報告後，義工可能加入偏遠森林中的尋找塔斯曼尼亞虎行動。"},{"en":"If tiger searches use money that could protect living species, some people may criticise them.","zh":"如果這些搜索使用本可保護現存物種的金錢，有些人可能批評它們。"},{"en":"This phrase refers specifically to efforts to find the thylacine.","zh":"這個片語專指尋找袋狼的努力。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":17},{"front":"better applied to","meaning":"更應用於……","examples":[{"en":"Resources would be better applied to saving other animals.","zh":"資源更應用於拯救其他動物。"},{"en":"Better applied to something means used more wisely or effectively for that purpose.","zh":"better applied to something 指把資源更明智或更有效地用於某目的。"},{"en":"A school’s budget may be better applied to teacher training than to expensive decorations.","zh":"學校預算可能更應用於教師培訓，而不是昂貴裝飾。"},{"en":"If one conservation project has little chance of success, money may be better applied elsewhere.","zh":"如果某保育項目成功機會很低，金錢可能更適合用於其他地方。"},{"en":"This phrase compares where resources should be used.","zh":"這個片語比較資源應該用在哪裡。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":17},{"front":"Tasmanian devil","meaning":"塔斯曼尼亞惡魔","examples":[{"en":"Naarding thinks resources should help save the Tasmanian devil.","zh":"Naarding 認為資源應幫助拯救塔斯曼尼亞惡魔。"},{"en":"The Tasmanian devil is a carnivorous marsupial native to Tasmania.","zh":"Tasmanian devil 是塔斯曼尼亞本地的一種肉食性有袋動物。"},{"en":"A wildlife park may teach visitors about the Tasmanian devil and threats to its survival.","zh":"野生動物園可能教遊客認識塔斯曼尼亞惡魔及其生存威脅。"},{"en":"If the Tasmanian devil is endangered, conservation funds may help protect its remaining population.","zh":"如果塔斯曼尼亞惡魔瀕危，保育資金可能幫助保護其剩餘種群。"},{"en":"This phrase names a living Tasmanian animal needing protection.","zh":"這個片語指出一種需要保護的現存塔斯曼尼亞動物。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":17},{"front":"migratory bird populations","meaning":"候鳥種群","examples":[{"en":"Resources could help migratory bird populations.","zh":"資源可以幫助候鳥種群。"},{"en":"Migratory bird populations are groups of birds that travel seasonally between regions.","zh":"migratory bird populations 是會按季節在不同地區之間遷徙的鳥類群體。"},{"en":"Wetlands support migratory bird populations by giving them food and resting places.","zh":"濕地透過提供食物和休息地支援候鳥種群。"},{"en":"If wetlands shrink, migratory bird populations may fall because long journeys become harder.","zh":"如果濕地縮小，候鳥種群可能下降，因為長途旅程變得更困難。"},{"en":"This phrase refers to the number and health of travelling bird groups.","zh":"這個片語指遷徙鳥類群體的數量和健康狀況。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":17},{"front":"declining as a result of","meaning":"因……而下降","examples":[{"en":"Migratory bird populations are declining as a result of shrinking wetlands.","zh":"候鳥種群因不斷縮減的濕地而下降。"},{"en":"Declining as a result of means decreasing because of a particular cause.","zh":"declining as a result of 指因某個特定原因而減少。"},{"en":"A student’s grades may decline as a result of poor sleep and missed lessons.","zh":"學生成績可能因睡眠不足和缺課而下降。"},{"en":"If habitats disappear, animal populations can decline as a result.","zh":"如果棲息地消失，動物種群可能因此下降。"},{"en":"This phrase connects a fall with its cause.","zh":"這個片語把下降與原因連接起來。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":17},{"front":"shrinking wetlands","meaning":"不斷縮減的濕地","examples":[{"en":"Bird populations are affected by shrinking wetlands across Australia.","zh":"候鳥種群受澳洲各地不斷縮減的濕地影響。"},{"en":"Shrinking wetlands are wetland areas that are becoming smaller over time.","zh":"shrinking wetlands 是隨時間變得越來越小的濕地區域。"},{"en":"A city may lose wildlife if shrinking wetlands are replaced by roads and housing.","zh":"如果不斷縮減的濕地被道路和房屋取代，城市可能失去野生動物。"},{"en":"If wetlands shrink, birds may lose feeding, breeding, and resting places.","zh":"如果濕地縮小，鳥類可能失去覓食、繁殖和休息地。"},{"en":"This phrase describes habitat loss in wet areas.","zh":"這個片語描述濕地中的棲息地流失。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":17},{"front":"across Australia","meaning":"遍及澳洲","examples":[{"en":"Shrinking wetlands affect bird populations across Australia.","zh":"不斷縮減的濕地影響遍及澳洲的鳥類種群。"},{"en":"Across Australia means throughout many parts of Australia.","zh":"across Australia 指遍及澳洲許多地區。"},{"en":"A heatwave across Australia can affect farms, schools, and hospitals.","zh":"遍及澳洲的熱浪可以影響農場、學校和醫院。"},{"en":"If a problem occurs across Australia, it is not limited to one town or state.","zh":"如果問題遍及澳洲，它就不限於一個城鎮或州份。"},{"en":"This phrase describes wide national spread.","zh":"這個片語描述全國範圍的廣泛分布。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":17},{"front":"still be out there","meaning":"仍可能存在於野外","examples":[{"en":"The thylacine could still be out there.","zh":"袋狼仍可能存在於野外。"},{"en":"Still be out there means may still exist somewhere, though it has not been confirmed.","zh":"still be out there 指可能仍存在於某處，雖然尚未被確認。"},{"en":"A missing key could still be out there in the playground if no one has searched carefully.","zh":"如果沒有人仔細搜索，遺失的鑰匙仍可能在操場某處。"},{"en":"If an animal could still be out there, people may continue searching remote habitats.","zh":"如果動物仍可能存在於野外，人們可能繼續搜索偏遠棲息地。"},{"en":"This phrase expresses uncertain hope of survival or discovery.","zh":"這個片語表達對存活或發現的不確定希望。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":17},{"front":"surviving thylacines","meaning":"倖存的袋狼","examples":[{"en":"The discovery of surviving thylacines would raise difficult questions.","zh":"發現倖存的袋狼會提出困難問題。"},{"en":"Surviving thylacines are thylacines that are still alive despite being believed extinct.","zh":"surviving thylacines 是儘管被認為已滅絕但仍活着的袋狼。"},{"en":"If surviving thylacines were found, scientists would need to protect them immediately.","zh":"如果發現倖存的袋狼，科學家需要立即保護牠們。"},{"en":"A tiny surviving population would face risks from disturbance, disease, and inbreeding.","zh":"一個極小的倖存種群會面臨干擾、疾病和近親繁殖風險。"},{"en":"This phrase refers to possible living members of the species.","zh":"這個片語指該物種可能仍活着的成員。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":17},{"front":"rather pointless","meaning":"頗無意義","examples":[{"en":"Naarding says discovering surviving thylacines would be rather pointless.","zh":"Naarding 說發現倖存袋狼會頗無意義。"},{"en":"Rather pointless means fairly useless or lacking a meaningful purpose.","zh":"rather pointless 指相當無用或缺乏有意義的目的。"},{"en":"It is rather pointless to buy a gym card if you never plan to exercise.","zh":"如果你從不打算運動，買健身會籍就頗無意義。"},{"en":"If people cannot protect a rediscovered animal, finding it may not help much.","zh":"如果人們不能保護重新發現的動物，找到牠可能幫助不大。"},{"en":"This phrase expresses mild criticism of an action’s usefulness.","zh":"這個片語對行動的用途作出溫和批評。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":17},{"front":"save a species from extinction","meaning":"拯救物種免於滅絕","examples":[{"en":"People may not know how to save a species from extinction.","zh":"人們可能不知道如何拯救物種免於滅絕。"},{"en":"To save a species from extinction means to stop it from dying out completely.","zh":"save a species from extinction 指阻止一個物種完全消失。"},{"en":"Conservationists may save a species from extinction by protecting habitat and supporting breeding.","zh":"保育人士可能透過保護棲息地和支援繁殖來拯救物種免於滅絕。"},{"en":"If too few animals remain, saving the species becomes much harder.","zh":"如果剩下的動物太少，拯救該物種會變得困難得多。"},{"en":"This phrase describes the goal of preventing total disappearance.","zh":"這個片語描述防止完全消失的目標。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":18},{"front":"better off","meaning":"情況更好","examples":[{"en":"If thylacines still exist, they are better off where they are.","zh":"如果袋狼仍存在，牠們留在原地情況更好。"},{"en":"Better off means in a better or safer situation.","zh":"better off 指處於更好或更安全的情況。"},{"en":"A child may be better off studying in a quiet room than beside a television.","zh":"孩子在安靜房間溫習，可能比坐在電視旁情況更好。"},{"en":"If rare animals are left alone in a hidden habitat, they may be safer than if crowds find them.","zh":"如果罕見動物被留在隱蔽棲息地中，牠們可能比被人群發現更安全。"},{"en":"This phrase compares which situation is more beneficial.","zh":"這個片語比較哪種情況更有利。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":18},{"front":"right where they are","meaning":"就在原地","examples":[{"en":"Naarding believes surviving thylacines should stay right where they are.","zh":"Naarding 認為倖存袋狼應留在原地。"},{"en":"Right where they are means exactly in their current place or situation.","zh":"right where they are 指正正在目前所在的地方或情況中。"},{"en":"A fragile old vase may be safer right where it is than being moved across the room.","zh":"脆弱舊花瓶留在原地，可能比被搬到房間另一邊更安全。"},{"en":"If rare animals are disturbed, their survival may become less secure.","zh":"如果罕見動物被打擾，其生存可能變得較不安全。"},{"en":"This phrase stresses not moving or disturbing something.","zh":"這個片語強調不要移動或打擾某物。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":18},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below with words from the passage.","zh":"學生使用篇章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing information in the short text that follows.","zh":"complete the summary below 指填寫下面短文中缺少的資料。"},{"en":"In reading tests, students should complete the summary below using only supported words from the passage.","zh":"在閱讀測驗中，學生應使用篇章支持的字詞完成以下摘要。"},{"en":"If the grammar does not fit the gap, the answer may be wrong even if the meaning is close.","zh":"如果文法不符合空格，即使意思接近，答案也可能錯。"},{"en":"This phrase is a common instruction in summary-completion tasks.","zh":"這個片語是摘要填充題中的常見指示。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":18},{"front":"no more than two words","meaning":"不超過兩個詞","examples":[{"en":"Students should choose no more than two words from the passage.","zh":"學生應從篇章中選擇不超過兩個詞。"},{"en":"No more than two words means the answer must contain one or two words only.","zh":"no more than two words 指答案只能包含一個或兩個英文詞。"},{"en":"If the correct answer is “Hobart Zoo”, writing “the Hobart Zoo” may exceed the limit.","zh":"如果正確答案是 “Hobart Zoo”，寫 “the Hobart Zoo” 可能超出限制。"},{"en":"Students should count the words carefully before writing the final answer.","zh":"學生寫最終答案前應仔細數字數。"},{"en":"This phrase sets a strict word limit.","zh":"這個片語設定嚴格字數限制。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":18},{"front":"resembled a dog","meaning":"像狗","examples":[{"en":"The Tasmanian tiger resembled a dog with stripes.","zh":"塔斯曼尼亞虎像一隻有條紋的狗。"},{"en":"Resembled a dog means looked similar to a dog.","zh":"resembled a dog 指外貌與狗相似。"},{"en":"A fox may resemble a small dog from a distance.","zh":"從遠處看，狐狸可能像一隻小狗。"},{"en":"If an extinct animal resembled a familiar animal, witnesses may describe it using that comparison.","zh":"如果已滅絕動物像熟悉動物，目擊者可能用這種比較來描述牠。"},{"en":"This phrase describes visual similarity.","zh":"這個片語描述外觀相似。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":18},{"front":"on its coat","meaning":"在牠的皮毛上","examples":[{"en":"The question refers to stripes on the animal’s coat.","zh":"題目指動物皮毛上的條紋。"},{"en":"On its coat means on the animal’s fur or outer body covering.","zh":"on its coat 指在動物的毛皮或外層身體覆蓋物上。"},{"en":"A cat may have patches of orange and white on its coat.","zh":"貓的皮毛上可能有橙色和白色斑塊。"},{"en":"If markings appear on an animal’s coat, they can help identify the species.","zh":"如果動物皮毛上有斑紋，它們可以幫助識別物種。"},{"en":"This phrase describes visible features on fur or body covering.","zh":"這個片語描述毛皮或身體覆蓋物上的可見特徵。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":18},{"front":"as early as","meaning":"早在……","examples":[{"en":"Fossils show that thylacines existed as early as millions of years ago.","zh":"化石顯示袋狼早在數百萬年前已經存在。"},{"en":"As early as means at a surprisingly early time or date.","zh":"as early as 指在令人意外地早的時間或日期。"},{"en":"Some children begin reading as early as age three.","zh":"有些孩子早在三歲便開始閱讀。"},{"en":"If fossils date back as early as millions of years ago, the species has deep evolutionary roots.","zh":"如果化石早在數百萬年前已存在，該物種就有深厚進化根源。"},{"en":"This phrase emphasises how far back something goes.","zh":"這個片語強調某事可追溯得多早。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":18},{"front":"once lived throughout","meaning":"曾遍布……","examples":[{"en":"Thylacines once lived throughout Australia.","zh":"袋狼曾遍布澳洲。"},{"en":"Once lived throughout means formerly existed across many parts of a whole area.","zh":"once lived throughout 指過去曾存在於整個地區的許多部分。"},{"en":"Wolves once lived throughout many parts of Europe before human pressure reduced them.","zh":"狼在受到人類壓力減少前，曾遍布歐洲許多地方。"},{"en":"If an animal once lived throughout a continent, fossils may appear in several regions.","zh":"如果動物曾遍布一個大陸，化石可能出現在幾個地區。"},{"en":"This phrase describes broad past distribution.","zh":"這個片語描述過去的廣泛分布。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":18},{"front":"disappearing from the mainland","meaning":"從大陸消失","examples":[{"en":"Thylacines disappeared from the mainland long ago.","zh":"袋狼很久以前已從大陸消失。"},{"en":"Disappearing from the mainland means no longer living on the main landmass.","zh":"disappearing from the mainland 指不再生活在主要陸地上。"},{"en":"An animal may disappear from the mainland but survive on islands with fewer predators.","zh":"一種動物可能從大陸消失，但在掠食者較少的島嶼上存活。"},{"en":"If thylacines disappeared from the mainland, Australia’s island populations became more important.","zh":"如果袋狼從大陸消失，澳洲島嶼上的種群便變得更重要。"},{"en":"This phrase describes regional disappearance from a continent or main land area.","zh":"這個片語描述從大陸或主要陸地區域消失。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":18},{"front":"soon after the arrival of","meaning":"在……到來後不久","examples":[{"en":"The decline accelerated soon after the arrival of settlers.","zh":"在定居者到來後不久，下降速度加快。"},{"en":"Soon after the arrival of means a short time after someone or something came.","zh":"soon after the arrival of 指某人或某物到來後不久。"},{"en":"Soon after the arrival of new students, the school held an orientation day.","zh":"在新生到來後不久，學校舉辦了迎新日。"},{"en":"If decline began soon after settlers arrived, researchers may look for links to hunting or habitat change.","zh":"如果下降在定居者到來後不久開始，研究人員可能尋找與狩獵或棲息地變化的關聯。"},{"en":"This phrase connects timing with a possible cause.","zh":"這個片語把時間與可能原因連接起來。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":18},{"front":"began to decline more rapidly","meaning":"開始更快速下降","examples":[{"en":"The Tasmanian population began to decline more rapidly.","zh":"塔斯曼尼亞的種群開始更快速下降。"},{"en":"Began to decline more rapidly means started decreasing faster than before.","zh":"began to decline more rapidly 指開始比以前更快地減少。"},{"en":"A student’s marks may begin to decline more rapidly if they stop attending lessons.","zh":"如果學生停止上課，成績可能開始更快速下降。"},{"en":"If a population declines more rapidly, a new threat may have appeared.","zh":"如果種群更快速下降，可能出現了新的威脅。"},{"en":"This phrase describes an acceleration in decrease.","zh":"這個片語描述下降加速。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":19},{"front":"match each statement with","meaning":"把每項陳述與……配對","examples":[{"en":"Students match each statement with the correct person.","zh":"學生把每項陳述與正確人物配對。"},{"en":"To match each statement with someone means to connect every statement to the person who said, did, or believed it.","zh":"match each statement with someone 指把每項陳述連接到說過、做過或相信該內容的人。"},{"en":"In a reading task, students may match each statement with the expert mentioned in the passage.","zh":"在閱讀題中，學生可能把每項陳述與文章中提到的專家配對。"},{"en":"If several people discuss the same topic, students must read carefully before matching.","zh":"如果幾個人討論同一主題，學生配對前必須仔細閱讀。"},{"en":"This phrase is common in matching questions.","zh":"這個片語常見於配對題。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":19},{"front":"correct person","meaning":"正確人物","examples":[{"en":"The task asks students to choose the correct person.","zh":"任務要求學生選擇正確人物。"},{"en":"The correct person is the individual whose opinion, action, or statement matches the question.","zh":"correct person 是其意見、行動或說法與題目相符的人。"},{"en":"If a question mentions the coelacanth, students should choose the person who used that example.","zh":"如果題目提到腔棘魚，學生應選擇使用該例子的人。"},{"en":"Choosing the correct person requires matching meaning, not just recognising names.","zh":"選擇正確人物需要配對意思，而不只是認出名字。"},{"en":"This phrase identifies the right person among several options.","zh":"這個片語指出幾個選項中的正確人物。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":19},{"front":"you may use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"Students may use any letter more than once.","zh":"學生可重複使用任何字母。"},{"en":"You may use any letter more than once means the same answer option can be repeated.","zh":"you may use any letter more than once 指同一答案選項可以重複使用。"},{"en":"In a matching task, one person may be the answer to two different statements.","zh":"在配對題中，一個人可能是兩項不同陳述的答案。"},{"en":"If students wrongly eliminate a letter after using it once, they may miss the correct answer.","zh":"如果學生使用一次後錯誤排除某字母，可能會錯過正確答案。"},{"en":"This instruction prevents false one-to-one matching.","zh":"這個指示避免錯誤地以為每個選項只能用一次。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":19},{"front":"attracted international interest","meaning":"引起國際關注","examples":[{"en":"Naarding’s report attracted international interest.","zh":"Naarding 的報告引起國際關注。"},{"en":"Attracted international interest means drew attention from people or media in many countries.","zh":"attracted international interest 指吸引多個國家的人或媒體注意。"},{"en":"A student invention may attract international interest if it solves a common problem cheaply.","zh":"如果學生發明能廉價解決常見問題，可能引起國際關注。"},{"en":"If a possible extinct-animal sighting attracts global attention, reporters may contact the witness quickly.","zh":"如果可能的已滅絕動物目擊引起全球關注，記者可能很快聯絡目擊者。"},{"en":"This phrase describes attention beyond one country.","zh":"這個片語描述超越一個國家的注意。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":19},{"front":"eyewitness reports","meaning":"目擊者報告","examples":[{"en":"Many eyewitness reports of thylacines may be unreliable.","zh":"許多袋狼目擊者報告可能不可靠。"},{"en":"Eyewitness reports are accounts given by people who say they personally saw an event or object.","zh":"eyewitness reports 是由聲稱親眼看到事件或物件的人提供的描述。"},{"en":"Police may compare eyewitness reports after a traffic accident.","zh":"交通意外後，警方可能比較目擊者報告。"},{"en":"If witnesses are excited, tired, or far away, their reports may contain mistakes.","zh":"如果目擊者興奮、疲倦或距離很遠，他們的報告可能包含錯誤。"},{"en":"This phrase refers to first-person observations.","zh":"這個片語指第一身觀察報告。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":19},{"front":"minimum number of animals","meaning":"最低動物數量","examples":[{"en":"A species may not always need a minimum number of animals to survive.","zh":"一個物種不一定總需要最低動物數量才能存活。"},{"en":"Minimum number of animals means the smallest number thought necessary for a population to continue.","zh":"minimum number of animals 指被認為維持種群延續所需的最少動物數量。"},{"en":"A breeding programme may require a minimum number of animals to avoid inbreeding.","zh":"繁殖計劃可能需要最低動物數量，以避免近親繁殖。"},{"en":"If the number falls below the minimum, the population may become unstable.","zh":"如果數量低於最低水平，種群可能變得不穩定。"},{"en":"This phrase refers to a lower survival threshold.","zh":"這個片語指生存的最低門檻。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":19},{"front":"no hope of finding","meaning":"沒有希望找到……","examples":[{"en":"Some experts believe there is no hope of finding a surviving thylacine.","zh":"一些專家認為沒有希望找到倖存袋狼。"},{"en":"No hope of finding means there is almost no chance of discovering something.","zh":"no hope of finding 指幾乎沒有機會發現某物。"},{"en":"If a lost ring fell into the sea years ago, there may be no hope of finding it.","zh":"如果遺失戒指多年前掉進海裡，可能沒有希望找到它。"},{"en":"If all evidence suggests extinction, experts may say there is no hope of finding the animal alive.","zh":"如果所有證據都顯示已滅絕，專家可能說沒有希望找到活着的動物。"},{"en":"This phrase expresses strong pessimism about discovery.","zh":"這個片語表達對發現某物的強烈悲觀。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":19},{"front":"left undisturbed","meaning":"不應被打擾","examples":[{"en":"If thylacines remain, they should be left undisturbed.","zh":"如果袋狼仍存在，牠們不應被打擾。"},{"en":"Left undisturbed means not touched, moved, chased, or interfered with.","zh":"left undisturbed 指不被觸碰、移動、追趕或干涉。"},{"en":"A bird’s nest should be left undisturbed so the parents return safely.","zh":"鳥巢應不被打擾，好讓親鳥安全回來。"},{"en":"If rare animals are disturbed by crowds, their survival may be threatened.","zh":"如果罕見動物被人群打擾，其生存可能受威脅。"},{"en":"This phrase describes protecting something by not interfering.","zh":"這個片語描述透過不干涉來保護某物。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":19},{"front":"interpretation of evidence","meaning":"對證據的詮釋","examples":[{"en":"The interpretation of evidence can be affected by beliefs.","zh":"對證據的詮釋可能受信念影響。"},{"en":"Interpretation of evidence means the way people understand and explain facts, signs, or data.","zh":"interpretation of evidence 指人們理解和解釋事實、跡象或數據的方式。"},{"en":"A teacher’s interpretation of exam results may change after learning that students were sick.","zh":"老師知道學生生病後，對考試結果的詮釋可能改變。"},{"en":"If people already believe an animal exists, they may interpret unclear tracks as proof.","zh":"如果人們已相信某動物存在，可能把模糊足跡詮釋為證據。"},{"en":"This phrase shows that evidence still needs human judgement.","zh":"這個片語顯示證據仍需要人的判斷。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":19},{"front":"affected by","meaning":"受……影響","examples":[{"en":"People’s interpretation can be affected by their beliefs.","zh":"人們的詮釋可能受其信念影響。"},{"en":"Affected by means influenced or changed by something.","zh":"affected by 指被某事影響或改變。"},{"en":"A student’s concentration may be affected by noise from the corridor.","zh":"學生專注力可能受走廊噪音影響。"},{"en":"If belief affects observation, people may see what they expect to see.","zh":"如果信念影響觀察，人們可能看見自己預期會看見的東西。"},{"en":"This phrase describes influence from a factor.","zh":"這個片語描述某因素帶來的影響。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":19},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter for each answer.","zh":"學生為每個答案選出正確字母。"},{"en":"Choose the correct letter means select the answer option marked by the right letter.","zh":"choose the correct letter 指選擇由正確字母標示的答案選項。"},{"en":"In multiple-choice questions, students should choose the correct letter, not copy the whole sentence.","zh":"在多項選擇題中，學生應選出正確字母，而不是抄寫整句。"},{"en":"If students know the answer but write the wrong letter, they may lose marks.","zh":"如果學生知道答案但寫錯字母，可能會失分。"},{"en":"This phrase reminds candidates to use the required answer format.","zh":"這個片語提醒考生使用指定答案格式。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":20},{"front":"resulted in","meaning":"導致","examples":[{"en":"Naarding’s sighting resulted in widespread interest.","zh":"Naarding 的目擊導致廣泛關注。"},{"en":"Resulted in means caused something to happen.","zh":"resulted in 指造成某事發生。"},{"en":"Heavy rain resulted in traffic delays across the city.","zh":"大雨導致全城交通延誤。"},{"en":"If a credible sighting is reported, it can result in searches, media attention, and debate.","zh":"如果可信目擊被報告，它可以導致搜索、媒體關注和爭論。"},{"en":"This phrase links a cause with an effect.","zh":"這個片語把原因與結果連接起來。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":20},{"front":"cooperative efforts","meaning":"合作努力","examples":[{"en":"The option mentions cooperative efforts to protect the thylacine.","zh":"該選項提到保護袋狼的合作努力。"},{"en":"Cooperative efforts are actions done together by different people, groups, or organisations.","zh":"cooperative efforts 是由不同人士、團體或機構一起進行的行動。"},{"en":"Schools and parents can make cooperative efforts to improve students’ reading habits.","zh":"學校和家長可以合作努力改善學生閱讀習慣。"},{"en":"If conservation requires land protection, research, and funding, cooperative efforts become necessary.","zh":"如果保育需要土地保護、研究和資金，合作努力便變得必要。"},{"en":"This phrase describes teamwork toward a shared goal.","zh":"這個片語描述朝共同目標進行的團隊合作。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":20},{"front":"widespread interest in","meaning":"對……的廣泛興趣","examples":[{"en":"The sighting created widespread interest in finding a living thylacine.","zh":"這次目擊引起對尋找活着袋狼的廣泛興趣。"},{"en":"Widespread interest in something means many people are curious about or concerned with it.","zh":"widespread interest in something 指許多人對某事感到好奇或關注。"},{"en":"A new vaccine may create widespread interest in a health issue.","zh":"新疫苗可能引起人們對某健康議題的廣泛興趣。"},{"en":"If a sighting seems credible, it can create widespread interest in renewed searches.","zh":"如果目擊看似可信，它可以引起人們對重新搜索的廣泛興趣。"},{"en":"This phrase describes attention shared by many people.","zh":"這個片語描述許多人共同的注意。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":20},{"front":"living thylacine","meaning":"活着的袋狼","examples":[{"en":"Many people hoped to find a living thylacine.","zh":"許多人希望找到一隻活着的袋狼。"},{"en":"A living thylacine would be a thylacine still alive today.","zh":"living thylacine 指今天仍活着的袋狼。"},{"en":"A photograph of a living thylacine would be extraordinary evidence if proven genuine.","zh":"如果被證實為真，一張活着袋狼的照片會是非凡證據。"},{"en":"If a living thylacine were found, scientists would face urgent conservation decisions.","zh":"如果發現活着的袋狼，科學家會面對緊急保育決定。"},{"en":"This phrase contrasts a live animal with fossils, stories, or museum specimens.","zh":"這個片語把活體動物與化石、故事或博物館標本作對比。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":20},{"front":"reported sightings worldwide","meaning":"全球報稱目擊個案","examples":[{"en":"The option refers to reported sightings worldwide.","zh":"該選項指全球報稱目擊個案。"},{"en":"Reported sightings worldwide means claims of seeing something from many parts of the world.","zh":"reported sightings worldwide 指來自世界各地、聲稱看見某物的報告。"},{"en":"A famous comet may have reported sightings worldwide when it appears in the night sky.","zh":"當著名彗星出現在夜空時，可能有全球報稱目擊。"},{"en":"If sightings are worldwide, experts must check whether the species could realistically live in those places.","zh":"如果目擊遍及全球，專家必須檢查該物種是否可能實際生活在那些地方。"},{"en":"This phrase describes globally reported observations.","zh":"這個片語描述全球範圍的報稱觀察。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":20},{"front":"increased popularity","meaning":"受歡迎程度上升","examples":[{"en":"The option mentions increased popularity of the thylacine.","zh":"該選項提到袋狼受歡迎程度上升。"},{"en":"Increased popularity means becoming more liked, known, or discussed by people.","zh":"increased popularity 指變得更受喜愛、更廣為人知或更常被討論。"},{"en":"A film can lead to increased popularity of the book it was based on.","zh":"電影可以令其改編來源書籍受歡迎程度上升。"},{"en":"If an animal becomes part of national mythology, its popularity may increase even after extinction.","zh":"如果動物成為國家神話的一部分，即使滅絕後，其受歡迎程度也可能上升。"},{"en":"This phrase describes rising public interest or approval.","zh":"這個片語描述公眾興趣或認同上升。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":20},{"front":"illustrates that","meaning":"說明","examples":[{"en":"The example of the coelacanth illustrates that extinction claims can be wrong.","zh":"腔棘魚的例子說明關於滅絕的說法可能是錯的。"},{"en":"Illustrates that means shows or explains a point clearly through an example.","zh":"illustrates that 指透過例子清楚顯示或解釋某個重點。"},{"en":"A teacher may use a failed project to illustrate that planning matters.","zh":"老師可能用失敗專題來說明計劃很重要。"},{"en":"If one extinct-looking species was rediscovered, it illustrates that certainty can sometimes be mistaken.","zh":"如果一種看似已滅絕的物種被重新發現，這說明確定判斷有時可能錯誤。"},{"en":"This phrase introduces the lesson shown by an example.","zh":"這個片語引入例子所顯示的教訓。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":20},{"front":"difficult to find in the wild","meaning":"在野外難以尋獲","examples":[{"en":"Some animals are difficult to find in the wild.","zh":"有些動物在野外難以尋獲。"},{"en":"Difficult to find in the wild means hard to locate in natural habitats.","zh":"difficult to find in the wild 指在自然棲息地中難以定位或找到。"},{"en":"A small nocturnal animal may be difficult to find in the wild because it hides during the day.","zh":"小型夜行動物可能在野外難以尋獲，因為牠白天躲藏。"},{"en":"If an animal lives in dense forest, absence of sightings may not prove absence of the animal.","zh":"如果動物生活在茂密森林中，缺乏目擊不一定證明牠不存在。"},{"en":"This phrase describes the challenge of observing wild species.","zh":"這個片語描述觀察野生物種的挑戰。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":20},{"front":"claims that a species is extinct","meaning":"關於某物種已滅絕的說法","examples":[{"en":"Claims that a species is extinct can sometimes be mistaken.","zh":"關於某物種已滅絕的說法有時可能錯誤。"},{"en":"Claims that a species is extinct are statements saying that no living members of the species remain.","zh":"claims that a species is extinct 是指聲稱該物種已沒有任何活着成員的說法。"},{"en":"A claim that a plant is extinct may be challenged if new specimens are found.","zh":"如果發現新標本，關於某植物已滅絕的說法可能被挑戰。"},{"en":"If experts make extinction claims with limited evidence, later discoveries may overturn them.","zh":"如果專家在證據有限下作出滅絕聲稱，後來發現可能推翻它們。"},{"en":"This phrase refers to statements about total species disappearance.","zh":"這個片語指關於物種完全消失的說法。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":20},{"front":"given some credence","meaning":"給予一定可信度","examples":[{"en":"Reports of sightings should be given some credence.","zh":"目擊報告應被給予一定可信度。"},{"en":"Given some credence means treated as somewhat believable or worth considering.","zh":"given some credence 指被視為有一定可信性或值得考慮。"},{"en":"A student’s complaint should be given some credence if several classmates report the same problem.","zh":"如果幾位同學報告同一問題，學生的投訴應被給予一定可信度。"},{"en":"If a witness is experienced, their report may deserve some attention even without perfect proof.","zh":"如果目擊者有經驗，即使沒有完美證據，其報告也可能值得一定注意。"},{"en":"This phrase means not fully accepting a claim, but not dismissing it immediately.","zh":"這個片語指不是完全接受主張，但也不是立即否定。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":20},{"front":"even when","meaning":"即使","examples":[{"en":"Reports may deserve consideration even when they are untrue.","zh":"即使報告不真實，它們也可能值得考慮。"},{"en":"Even when means despite the fact that something happens or is true.","zh":"even when 指即使某事發生或屬實。"},{"en":"A student should be treated politely even when their answer is wrong.","zh":"即使學生答錯，也應被禮貌對待。"},{"en":"Even when a report turns out false, investigating it may teach experts something about public belief.","zh":"即使報告最後證明是假的，調查它也可能讓專家了解公眾信念。"},{"en":"This phrase introduces a surprising contrast.","zh":"這個片語引入令人意外的對比。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":21},{"front":"acted upon immediately","meaning":"立即採取行動處理","examples":[{"en":"The option suggests that reports should be acted upon immediately.","zh":"該選項暗示報告應被立即採取行動處理。"},{"en":"Acted upon immediately means responded to or handled without delay.","zh":"acted upon immediately 指不延誤地回應或處理。"},{"en":"A fire alarm should be acted upon immediately because waiting can be dangerous.","zh":"火警鐘應被立即處理，因為等待可能危險。"},{"en":"If every weak sighting report is acted upon immediately, resources may be wasted.","zh":"如果每個薄弱目擊報告都被立即採取行動處理，資源可能被浪費。"},{"en":"This phrase describes quick action after receiving information.","zh":"這個片語描述收到資訊後迅速行動。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":21},{"front":"equally untrustworthy","meaning":"同樣不可信","examples":[{"en":"The option suggests that all reports are equally untrustworthy.","zh":"該選項暗示所有報告都同樣不可信。"},{"en":"Equally untrustworthy means all are unreliable to the same degree.","zh":"equally untrustworthy 指全部都以同樣程度不可靠。"},{"en":"Not all online reviews are equally untrustworthy; some include photos and detailed experience.","zh":"並非所有網上評論都同樣不可信；有些包含照片和詳細經驗。"},{"en":"If some witnesses are experts and others are hoaxers, their reports should not be treated the same.","zh":"如果有些目擊者是專家，有些是惡作劇者，其報告不應被同等看待。"},{"en":"This phrase compares the reliability of several things.","zh":"這個片語比較幾件事物的可靠性。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":21},{"front":"carefully investigated","meaning":"仔細調查","examples":[{"en":"Reports of sightings should be questioned and carefully investigated.","zh":"目擊報告應被質疑並仔細調查。"},{"en":"Carefully investigated means examined in detail before a conclusion is made.","zh":"carefully investigated 指在得出結論前被詳細檢查。"},{"en":"A serious complaint at school should be carefully investigated before anyone is blamed.","zh":"學校中的嚴重投訴應在責怪任何人前被仔細調查。"},{"en":"If a sighting is carefully investigated, experts may check photos, location, timing, and witness background.","zh":"如果目擊被仔細調查，專家可能檢查照片、地點、時間和目擊者背景。"},{"en":"This phrase describes cautious and thorough examination.","zh":"這個片語描述謹慎而徹底的檢查。"}],"source":"38 - Tasmanian Tiger.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 39":[{"front":"wealth in a cold climate","meaning":"寒冷氣候中的財富","examples":[{"en":"The passage discusses wealth in a cold climate.","zh":"文章討論寒冷氣候中的財富。"},{"en":"Wealth in a cold climate means the idea that colder regions may become richer because the environment supports health, farming, or work.","zh":"Wealth in a cold climate 指寒冷地區可能因環境有利於健康、農業或工作而變得較富裕這一想法。"},{"en":"A country with cold winters may have fewer crop-damaging insects than a tropical country.","zh":"有寒冷冬天的國家，可能比熱帶國家有較少破壞農作物的昆蟲。"},{"en":"If cold weather reduces disease and protects crops, it may help a society build wealth over time.","zh":"如果寒冷天氣減少疾病並保護農作物，它可能幫助社會隨時間累積財富。"},{"en":"This phrase connects climate with economic success, but it does not mean cold alone creates wealth.","zh":"這個片語把氣候與經濟成功連接起來，但不代表單靠寒冷就能創造財富。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":1},{"front":"latitude","meaning":"緯度","examples":[{"en":"Latitude is crucial to a nation’s economic strength.","zh":"緯度對一個國家的經濟實力至關重要。"},{"en":"Latitude is the distance of a place north or south of the equator, measured in degrees.","zh":"Latitude 是一個地方距離赤道南北的距離，以度數量度。"},{"en":"Finland has a high latitude, while Singapore is much closer to the equator.","zh":"芬蘭緯度高，而新加坡則更接近赤道。"},{"en":"Latitude can affect climate, and climate may influence farming, disease, and work patterns.","zh":"緯度可以影響氣候，而氣候可能影響農業、疾病和工作模式。"},{"en":"This word is often used when discussing geography, climate, and national development.","zh":"這個詞常用於討論地理、氣候和國家發展。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":1},{"front":"be crucial to","meaning":"對……至關重要","examples":[{"en":"Latitude is crucial to a nation’s economic strength.","zh":"緯度對一個國家的經濟實力至關重要。"},{"en":"To be crucial to something means to be extremely important for it.","zh":"To be crucial to something 指對某事極其重要。"},{"en":"Good sleep is crucial to a student’s concentration during exams.","zh":"良好睡眠對學生考試期間的專注力至關重要。"},{"en":"If transport is crucial to a business, poor roads can damage its growth.","zh":"如果交通對企業至關重要，惡劣道路可能損害其增長。"},{"en":"This phrase shows that one factor strongly affects the success of another.","zh":"這個片語顯示一個因素強烈影響另一事物的成功。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":1},{"front":"economic strength","meaning":"經濟實力","examples":[{"en":"Climate may influence a nation’s economic strength.","zh":"氣候可能影響一個國家的經濟實力。"},{"en":"Economic strength means how powerful, productive, and wealthy an economy is.","zh":"Economic strength 指一個經濟體有多強大、多具生產力和多富裕。"},{"en":"A country with strong industries, good jobs, and stable income has economic strength.","zh":"擁有強大工業、良好工作和穩定收入的國家具有經濟實力。"},{"en":"If farming improves and disease falls, a country’s economic strength may increase.","zh":"如果農業改善而疾病減少，一個國家的經濟實力可能增加。"},{"en":"This phrase describes national wealth and productive capacity, not military power.","zh":"這個片語描述國家財富和生產能力，而不是軍事力量。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":1},{"front":"inspiration struck","meaning":"靈感突然出現","examples":[{"en":"Dr William Masters was reading a book when inspiration struck.","zh":"William Masters博士正在讀書時，靈感突然出現。"},{"en":"Inspiration struck means a good idea suddenly appeared in someone’s mind.","zh":"Inspiration struck 指一個好想法突然出現在某人腦海中。"},{"en":"A student may be stuck on an essay, and then inspiration strikes during a walk home.","zh":"學生可能寫作文時卡住，然後在步行回家時突然有靈感。"},{"en":"When inspiration strikes, a person may suddenly see a new way to solve a problem.","zh":"當靈感突然出現，一個人可能突然看見解決問題的新方法。"},{"en":"This phrase describes a sudden creative or intellectual moment.","zh":"這個片語描述突然出現的創意或思考時刻。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":1},{"front":"anecdote about","meaning":"關於……的軼事","examples":[{"en":"There was an anecdote about the great yellow fever epidemic.","zh":"有一則關於大規模黃熱病疫情的軼事。"},{"en":"An anecdote about something is a short story or example connected with that topic.","zh":"Anecdote about something 是與某主題相關的短故事或例子。"},{"en":"A teacher may tell an anecdote about a former student to explain why revision matters.","zh":"老師可能講一則關於舊學生的軼事，以解釋溫習為何重要。"},{"en":"If an anecdote is memorable, it can make a difficult idea easier to understand.","zh":"如果軼事令人印象深刻，它可以令困難想法更容易理解。"},{"en":"This phrase refers to a small story used to illustrate a bigger point.","zh":"這個片語指用來說明更大重點的小故事。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":1},{"front":"yellow fever epidemic","meaning":"黃熱病疫情","examples":[{"en":"A yellow fever epidemic hit Philadelphia in 1793.","zh":"1793年，一場黃熱病疫情襲擊費城。"},{"en":"A yellow fever epidemic is a large outbreak of yellow fever, a serious mosquito-borne disease.","zh":"Yellow fever epidemic 是黃熱病的大規模爆發；黃熱病是一種由蚊子傳播的嚴重疾病。"},{"en":"A city with many mosquitoes and poor disease control may fear a yellow fever epidemic.","zh":"如果城市有很多蚊子且疾病控制差，可能擔心出現黃熱病疫情。"},{"en":"If an epidemic spreads quickly, hospitals and families can be overwhelmed.","zh":"如果疫情迅速傳播，醫院和家庭可能不勝負荷。"},{"en":"This phrase describes a serious public-health crisis caused by yellow fever.","zh":"這個片語描述由黃熱病造成的嚴重公共健康危機。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":1},{"front":"hit Philadelphia","meaning":"襲擊費城","examples":[{"en":"The epidemic hit Philadelphia in 1793.","zh":"這場疫情在1793年襲擊費城。"},{"en":"To hit Philadelphia means to affect or strike the city of Philadelphia suddenly or seriously.","zh":"To hit Philadelphia 指突然或嚴重影響費城。"},{"en":"A storm may hit a coastal town and damage homes overnight.","zh":"風暴可能一夜之間襲擊沿海小鎮並損壞房屋。"},{"en":"If a disease hits a city, daily life may stop and many people may become ill.","zh":"如果疾病襲擊城市，日常生活可能停頓，許多人可能患病。"},{"en":"This phrase uses “hit” to show strong negative impact.","zh":"這個片語用 “hit” 表示強烈負面影響。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":1},{"front":"decimate the city","meaning":"重創城市","examples":[{"en":"The epidemic decimated the city until the first frost came.","zh":"疫情一直重創城市，直到初霜來臨。"},{"en":"To decimate the city means to kill many people or cause severe damage across the city.","zh":"To decimate the city 指在城市中造成大量死亡或嚴重破壞。"},{"en":"A major flood can decimate a town by destroying homes, shops, and roads.","zh":"大洪水可以摧毀房屋、商店和道路，重創一個城鎮。"},{"en":"If disease decimates a city, workers, families, and public services all suffer.","zh":"如果疾病重創城市，工人、家庭和公共服務都會受苦。"},{"en":"This phrase describes extreme damage, not a small problem.","zh":"這個片語描述極嚴重的破壞，而不是小問題。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":1},{"front":"first frost","meaning":"初霜","examples":[{"en":"The epidemic ended when the first frost came.","zh":"當初霜來臨時，疫情結束了。"},{"en":"The first frost is the first time in a season when temperatures drop low enough to freeze moisture on the ground.","zh":"First frost 是一個季節中氣溫首次低到足以令地面水分結霜的時候。"},{"en":"Farmers may protect young plants before the first frost arrives.","zh":"農夫可能在初霜到來前保護幼苗。"},{"en":"If the first frost kills mosquitoes, some diseases may stop spreading.","zh":"如果初霜殺死蚊子，一些疾病可能停止傳播。"},{"en":"This phrase marks the beginning of truly cold weather.","zh":"這個片語標誌真正寒冷天氣的開始。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":1},{"front":"inclement weather","meaning":"惡劣天氣","examples":[{"en":"The inclement weather froze out the insects.","zh":"惡劣天氣凍死了那些昆蟲。"},{"en":"Inclement weather means unpleasant, severe, or harsh weather, such as cold, storms, or heavy rain.","zh":"Inclement weather 指令人不適、嚴重或惡劣的天氣，例如寒冷、暴風或大雨。"},{"en":"A school trip may be cancelled because of inclement weather.","zh":"學校旅行可能因惡劣天氣而取消。"},{"en":"If inclement weather damages roads, transport can become slow or dangerous.","zh":"如果惡劣天氣損壞道路，交通可能變得緩慢或危險。"},{"en":"This phrase is often used formally to describe bad weather.","zh":"這個片語常較正式地用來描述壞天氣。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":2},{"front":"freeze out","meaning":"凍死；迫使……消失","examples":[{"en":"The frost froze out the disease-carrying insects.","zh":"霜凍凍死了傳播疾病的昆蟲。"},{"en":"To freeze out insects means to kill them or force them to disappear through cold weather.","zh":"To freeze out insects 指透過寒冷天氣殺死昆蟲或迫使它們消失。"},{"en":"A cold winter can freeze out pests that would otherwise damage garden plants.","zh":"寒冷冬天可以凍死害蟲，否則它們會破壞園中植物。"},{"en":"If frost freezes out mosquitoes, mosquito-borne disease may decline.","zh":"如果霜凍凍死蚊子，蚊傳疾病可能減少。"},{"en":"This phrase shows cold weather removing a harmful living thing.","zh":"這個片語顯示寒冷天氣移除有害生物。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":2},{"front":"allow someone to recover","meaning":"使……得以復原","examples":[{"en":"The frost allowed Philadelphia to recover.","zh":"霜凍使費城得以復原。"},{"en":"To allow someone to recover means to make it possible for a person, place, or group to return to a healthier or better state.","zh":"To allow someone to recover 指使人、地方或群體能夠回到較健康或較好的狀態。"},{"en":"A quiet weekend may allow a tired student to recover after exams.","zh":"安靜的週末可以讓疲倦學生在考試後復原。"},{"en":"If disease stops spreading, a city can recover socially and economically.","zh":"如果疾病停止傳播，城市可以在社會和經濟上復原。"},{"en":"This phrase shows that one condition creates space for healing or improvement.","zh":"這個片語顯示某條件為恢復或改善創造空間。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":2},{"front":"the key to","meaning":"……的關鍵","examples":[{"en":"Weather could be the key to a city’s fortunes.","zh":"天氣可能是城市命運的關鍵。"},{"en":"The key to something is the most important factor that helps explain or solve it.","zh":"The key to something 是幫助解釋或解決某事的最重要因素。"},{"en":"Practice is the key to improving pronunciation.","zh":"練習是改善發音的關鍵。"},{"en":"If clean water is the key to better health, investment should focus on water systems.","zh":"如果清潔食水是改善健康的關鍵，投資應集中於供水系統。"},{"en":"This phrase points to the central explanation or solution.","zh":"這個片語指出核心解釋或解決方法。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":2},{"front":"city’s fortunes","meaning":"城市的命運","examples":[{"en":"Masters wondered whether weather affected a city’s fortunes.","zh":"Masters想知道天氣是否影響城市的命運。"},{"en":"A city’s fortunes are its success, failure, wealth, health, or general condition over time.","zh":"City’s fortunes 指一座城市隨時間的成功、失敗、財富、健康或整體狀況。"},{"en":"A new railway can improve a city’s fortunes by bringing jobs and visitors.","zh":"新鐵路可以帶來工作和旅客，改善城市的命運。"},{"en":"If disease closes markets and reduces workers, a city’s fortunes may decline.","zh":"如果疾病令市場關閉並減少工人，城市的命運可能轉差。"},{"en":"This phrase describes the changing fate of a city.","zh":"這個片語描述城市不斷變化的命運。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":2},{"front":"historical fortunes of nations","meaning":"國家的歷史命運","examples":[{"en":"Climate may influence the historical fortunes of nations.","zh":"氣候可能影響國家的歷史命運。"},{"en":"The historical fortunes of nations are the long-term success, failure, wealth, and power of countries over history.","zh":"Historical fortunes of nations 指國家在歷史長河中的長期成功、失敗、財富和力量。"},{"en":"Wars, trade routes, disease, and climate can all shape the historical fortunes of nations.","zh":"戰爭、貿易路線、疾病和氣候都可以塑造國家的歷史命運。"},{"en":"If a country gains good ports and strong farming, its historical fortunes may improve.","zh":"如果一個國家擁有良好港口和強大農業，它的歷史命運可能改善。"},{"en":"This phrase looks at national development across long periods.","zh":"這個片語從長時段看國家發展。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":2},{"front":"lie at the heart of","meaning":"位於……的核心","examples":[{"en":"Frost may lie at the heart of an economic mystery.","zh":"霜凍可能位於一個經濟謎團的核心。"},{"en":"To lie at the heart of something means to be central to it or to be one of its deepest causes.","zh":"To lie at the heart of something 指位於某事核心，或是其最深層原因之一。"},{"en":"Lack of sleep may lie at the heart of a student’s poor concentration.","zh":"睡眠不足可能位於學生專注力差的核心。"},{"en":"If unfair pay lies at the heart of worker anger, small gifts will not solve the problem.","zh":"如果不公平薪酬位於工人憤怒的核心，小禮物不能解決問題。"},{"en":"This phrase points to a deep central cause.","zh":"這個片語指出深層核心原因。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":2},{"front":"enduring economic mysteries","meaning":"長久存在的經濟謎團","examples":[{"en":"One enduring economic mystery is why wealthy nations are often cold.","zh":"其中一個長久存在的經濟謎團是為何富裕國家常位於寒冷地區。"},{"en":"Enduring economic mysteries are important economic questions that remain difficult to explain for a long time.","zh":"Enduring economic mysteries 是長時間仍難以解釋的重要經濟問題。"},{"en":"Why some regions stay poor despite resources can be an enduring economic mystery.","zh":"為何一些地區有資源卻仍然貧窮，可以是一個長久存在的經濟謎團。"},{"en":"If a question remains unsolved for decades, researchers keep testing new explanations.","zh":"如果問題數十年仍未解決，研究人員會繼續測試新解釋。"},{"en":"This phrase describes long-lasting puzzles about money, wealth, and development.","zh":"這個片語描述關於金錢、財富和發展的長期謎題。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":2},{"front":"wealthy, industrialised nations","meaning":"富裕工業化國家","examples":[{"en":"Most wealthy, industrialised nations are found above 40 degrees latitude.","zh":"大多數富裕工業化國家位於40度緯度以上。"},{"en":"Wealthy, industrialised nations are rich countries with developed factories, services, technology, and infrastructure.","zh":"Wealthy, industrialised nations 是擁有發達工廠、服務業、科技和基礎設施的富裕國家。"},{"en":"A wealthy, industrialised nation usually has strong transport, hospitals, schools, and businesses.","zh":"富裕工業化國家通常有強大的交通、醫院、學校和企業。"},{"en":"If a nation industrialises and builds wealth, living standards may rise for many citizens.","zh":"如果一個國家工業化並累積財富，許多公民的生活水平可能上升。"},{"en":"This phrase describes countries that are both economically rich and highly developed.","zh":"這個片語描述既富裕又高度發展的國家。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":2},{"front":"be found at latitudes above","meaning":"位於……以上的緯度","examples":[{"en":"Wealthy nations are often found at latitudes above 40 degrees.","zh":"富裕國家常位於40度以上的緯度。"},{"en":"To be found at latitudes above a number means to be located north or south of that latitude line.","zh":"To be found at latitudes above a number 指位於該緯度線以北或以南較高緯度地區。"},{"en":"Many cold countries are found at latitudes above the tropical zones.","zh":"許多寒冷國家位於熱帶地區以上的緯度。"},{"en":"If rich nations are often found at higher latitudes, researchers may ask whether climate matters.","zh":"如果富裕國家常位於較高緯度，研究人員可能會問氣候是否重要。"},{"en":"This phrase describes geographical location by latitude.","zh":"這個片語用緯度描述地理位置。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":2},{"front":"a piece of the puzzle","meaning":"謎題的一部分","examples":[{"en":"Masters thinks he has found a piece of the puzzle.","zh":"Masters認為他找到謎題的一部分。"},{"en":"A piece of the puzzle is one part of a larger explanation that helps make the whole problem clearer.","zh":"A piece of the puzzle 是較大解釋中的一部分，有助令整個問題更清楚。"},{"en":"A student’s sleep diary may provide a piece of the puzzle in explaining poor exam results.","zh":"學生的睡眠日記可能提供解釋考試成績差這個謎題的一部分。"},{"en":"If one clue fits with others, it can help complete the puzzle.","zh":"如果一條線索與其他線索吻合，它可以幫助完成謎題。"},{"en":"This phrase means one useful part of a bigger answer, not the whole answer.","zh":"這個片語指較大答案中的有用部分，而不是完整答案。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":3},{"front":"agricultural economist","meaning":"農業經濟學家","examples":[{"en":"Masters is an agricultural economist from Purdue University.","zh":"Masters是普渡大學的農業經濟學家。"},{"en":"An agricultural economist studies how farming, food production, land, markets, and policy affect economies.","zh":"Agricultural economist 研究農業、食物生產、土地、市場和政策如何影響經濟。"},{"en":"An agricultural economist may examine why rice prices rise after a drought.","zh":"農業經濟學家可能研究乾旱後米價為何上升。"},{"en":"If farmers lack irrigation, an agricultural economist can study how that affects income.","zh":"如果農民缺乏灌溉，農業經濟學家可以研究這如何影響收入。"},{"en":"This phrase describes an economist who focuses on agriculture and rural production.","zh":"這個片語描述專注於農業和農村生產的經濟學家。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":3},{"front":"annual frosts","meaning":"每年霜凍","examples":[{"en":"Annual frosts are among the factors that distinguish rich nations from poor ones.","zh":"每年霜凍是區分富裕國家與貧窮國家的因素之一。"},{"en":"Annual frosts are frosts that happen each year, usually during cold seasons.","zh":"Annual frosts 是每年發生的霜凍，通常出現在寒冷季節。"},{"en":"Farmers in cold regions may expect annual frosts and plan planting around them.","zh":"寒冷地區的農民可能預期每年霜凍，並圍繞它安排種植。"},{"en":"If annual frosts kill pests, they can help protect crops before the next growing season.","zh":"如果每年霜凍殺死害蟲，它們可以在下一個生長季前幫助保護農作物。"},{"en":"This phrase links repeated cold weather with farming and health conditions.","zh":"這個片語把反覆出現的寒冷天氣與農業和健康條件連接起來。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":3},{"front":"distinguish A from B","meaning":"區分 A 和 B","examples":[{"en":"Annual frosts may distinguish rich nations from poor ones.","zh":"每年霜凍可能區分富裕國家和貧窮國家。"},{"en":"To distinguish A from B means to show the difference between two things or groups.","zh":"To distinguish A from B 指顯示兩件事或兩個群體之間的差異。"},{"en":"Good evidence helps distinguish a strong argument from a weak one.","zh":"好證據幫助區分強論點和弱論點。"},{"en":"If one feature appears in rich countries but not poor ones, researchers may ask whether it distinguishes them.","zh":"如果某特徵出現在富裕國家而非貧窮國家，研究人員可能會問它是否區分兩者。"},{"en":"This phrase is useful when comparing two categories.","zh":"這個片語適合用於比較兩個類別。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":3},{"front":"speculate that","meaning":"推測","examples":[{"en":"The researchers speculate that cold snaps have two main benefits.","zh":"研究人員推測寒潮有兩個主要好處。"},{"en":"To speculate that something is true means to suggest it as a possible explanation without full proof.","zh":"To speculate that something is true 指在未有完整證明下，把某事作為可能解釋提出。"},{"en":"Doctors may speculate that a patient’s tiredness is caused by stress before tests confirm it.","zh":"在檢查確認前，醫生可能推測病人疲倦是由壓力造成。"},{"en":"If evidence is incomplete, researchers speculate carefully rather than state certainty.","zh":"如果證據不完整，研究人員會謹慎推測，而不是宣稱確定。"},{"en":"This phrase introduces a possible idea, not a final conclusion.","zh":"這個片語引出可能想法，而不是最終結論。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":3},{"front":"cold snaps","meaning":"寒潮；短暫寒冷天氣","examples":[{"en":"Cold snaps may help farmers by killing pests.","zh":"寒潮可能透過殺死害蟲幫助農民。"},{"en":"Cold snaps are short periods of unusually cold weather.","zh":"Cold snaps 是短時間異常寒冷的天氣。"},{"en":"A sudden cold snap can make students wear winter coats earlier than expected.","zh":"突然寒潮可以令學生比預期更早穿上冬天外套。"},{"en":"If a cold snap kills insects, it may reduce crop damage in spring.","zh":"如果寒潮殺死昆蟲，它可能減少春季農作物損害。"},{"en":"This phrase describes brief cold weather, not a whole cold climate.","zh":"這個片語描述短暫寒冷天氣，而不是整個寒冷氣候。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":3},{"front":"otherwise destroy crops","meaning":"否則會破壞農作物","examples":[{"en":"Frost freezes pests that would otherwise destroy crops.","zh":"霜凍凍死否則會破壞農作物的害蟲。"},{"en":"Otherwise destroy crops means damage or ruin crops if nothing stops them.","zh":"Otherwise destroy crops 指如果沒有東西阻止，就會損壞或毀掉農作物。"},{"en":"Farmers may spray plants to stop insects that would otherwise destroy crops.","zh":"農民可能噴灑植物，以阻止否則會破壞農作物的昆蟲。"},{"en":"If pests are not controlled, they can eat leaves, spread disease, and reduce harvests.","zh":"如果害蟲不受控制，它們可以吃掉葉子、傳播疾病並減少收成。"},{"en":"This phrase shows what would happen without protection.","zh":"這個片語顯示沒有保護時會發生甚麼。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":3},{"front":"carry disease","meaning":"傳播疾病","examples":[{"en":"Mosquitoes are organisms that carry disease.","zh":"蚊子是會傳播疾病的生物。"},{"en":"To carry disease means to transport germs or infections from one person, animal, or place to another.","zh":"To carry disease 指把細菌或感染從一個人、動物或地方帶到另一個。"},{"en":"Mosquitoes can carry disease from infected people to healthy people.","zh":"蚊子可以把疾病從受感染的人傳播給健康的人。"},{"en":"If insects that carry disease are reduced, fewer people may become ill.","zh":"如果傳播疾病的昆蟲減少，較少人可能生病。"},{"en":"This phrase describes disease transmission, not simply being dirty.","zh":"這個片語描述疾病傳播，而不只是骯髒。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":3},{"front":"agricultural abundance","meaning":"農業豐收","examples":[{"en":"The result of limited frost may be agricultural abundance.","zh":"有限度霜凍的結果可能是農業豐收。"},{"en":"Agricultural abundance means a large and healthy supply of crops or food from farming.","zh":"Agricultural abundance 指農業帶來大量而健康的農作物或食物供應。"},{"en":"A region with good soil and enough water may enjoy agricultural abundance.","zh":"擁有良好土壤和足夠水源的地區可能享有農業豐收。"},{"en":"If pests are controlled and crops grow well, agricultural abundance can support population growth.","zh":"如果害蟲受控且農作物生長良好，農業豐收可以支持人口增長。"},{"en":"This phrase describes plenty in farming, not general wealth alone.","zh":"這個片語描述農業上的豐足，而不只是一般財富。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":3},{"front":"big workforce","meaning":"龐大勞動力","examples":[{"en":"Healthier conditions can help create a big workforce.","zh":"較健康的環境可以幫助形成龐大勞動力。"},{"en":"A big workforce is a large number of people who are able to work.","zh":"Big workforce 是大量能夠工作的人。"},{"en":"A growing city may provide a big workforce for factories, shops, and public services.","zh":"不斷增長的城市可能為工廠、商店和公共服務提供龐大勞動力。"},{"en":"If fewer people are sick, more adults can work and the workforce becomes larger.","zh":"如果較少人生病，更多成年人可以工作，勞動力就會變得更大。"},{"en":"This phrase connects population health with available labour.","zh":"這個片語把人口健康與可用勞動力連接起來。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":3},{"front":"sets of information","meaning":"兩組資料","examples":[{"en":"The academics took two sets of information.","zh":"學者們採用了兩組資料。"},{"en":"Sets of information are groups of data or facts collected for comparison or study.","zh":"Sets of information 是為比較或研究而收集的資料或事實組合。"},{"en":"A teacher may compare two sets of information: homework scores and exam results.","zh":"老師可能比較兩組資料：功課分數和考試成績。"},{"en":"If two sets of information show the same pattern, researchers may see a possible link.","zh":"如果兩組資料顯示相同模式，研究人員可能看見可能關聯。"},{"en":"This phrase is useful for discussing data and evidence.","zh":"這個片語適合用於討論數據和證據。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":4},{"front":"average income","meaning":"平均收入","examples":[{"en":"The researchers compared average income with climate data.","zh":"研究人員把平均收入與氣候數據作比較。"},{"en":"Average income is the typical amount of money people earn in a group, region, or country.","zh":"Average income 是一個群體、地區或國家中人們賺取的典型金額。"},{"en":"A city with higher average income may have more spending power.","zh":"平均收入較高的城市可能有更強消費力。"},{"en":"If average income rises, families may afford better housing, food, and education.","zh":"如果平均收入上升，家庭可能負擔得起更好的住屋、食物和教育。"},{"en":"This phrase describes a typical earning level, not the income of every person.","zh":"這個片語描述典型收入水平，而不是每個人的收入。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":4},{"front":"climate data","meaning":"氣候數據","examples":[{"en":"The study used climate data from the University of East Anglia.","zh":"研究使用了東英吉利大學的氣候數據。"},{"en":"Climate data are records about weather patterns over time, such as temperature, rainfall, frost, and humidity.","zh":"Climate data 是關於長期天氣模式的記錄，例如溫度、降雨、霜凍和濕度。"},{"en":"Farmers may use climate data to decide which crops are safest to plant.","zh":"農民可能使用氣候數據來決定種植哪些作物最安全。"},{"en":"If climate data show regular droughts, governments may invest in irrigation.","zh":"如果氣候數據顯示定期乾旱，政府可能投資灌溉。"},{"en":"This phrase refers to measured information about long-term weather conditions.","zh":"這個片語指關於長期天氣條件的量度資料。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":4},{"front":"curious tally between","meaning":"……之間奇妙的一致","examples":[{"en":"They found a curious tally between income and climate.","zh":"他們發現收入與氣候之間有奇妙的一致。"},{"en":"A curious tally between two things is a surprising match or pattern that appears when they are compared.","zh":"Curious tally between two things 是兩者比較時出現的令人驚訝的吻合或模式。"},{"en":"A teacher may notice a curious tally between poor sleep and low test scores.","zh":"老師可能注意到睡眠差與測驗分數低之間有奇妙的一致。"},{"en":"If two patterns match closely, researchers may investigate whether one affects the other.","zh":"如果兩種模式非常吻合，研究人員可能調查一方是否影響另一方。"},{"en":"This phrase suggests an interesting connection, but not automatic proof.","zh":"這個片語暗示有趣關聯，但不自動等於證明。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":4},{"front":"uniformly rich","meaning":"一律富裕","examples":[{"en":"Countries with frequent frost are uniformly rich.","zh":"經常有霜凍的國家一律富裕。"},{"en":"Uniformly rich means rich in every case or almost every case within a group.","zh":"Uniformly rich 指在某群體中每個或幾乎每個情況都富裕。"},{"en":"If all schools in one district are well-funded, they may be described as uniformly rich in resources.","zh":"如果某區所有學校資源充足，它們可被描述為資源上一律富裕。"},{"en":"When a group is uniformly rich, researchers ask what common factor they share.","zh":"當一個群體一律富裕，研究人員會問它們共享甚麼共同因素。"},{"en":"This phrase stresses consistency across a whole group.","zh":"這個片語強調整個群體的一致性。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":4},{"front":"impoverished","meaning":"貧困的","examples":[{"en":"Countries with fewer frosty days are often impoverished.","zh":"霜凍日較少的國家往往貧困。"},{"en":"Impoverished means very poor or lacking money, resources, and opportunities.","zh":"Impoverished 指非常貧窮，缺乏金錢、資源和機會。"},{"en":"An impoverished family may struggle to pay for food, rent, and school materials.","zh":"貧困家庭可能難以支付食物、租金和學校用品。"},{"en":"If a region remains impoverished, health, education, and jobs may all suffer.","zh":"如果一個地區持續貧困，健康、教育和工作都可能受損。"},{"en":"This word describes serious poverty, not just being less rich.","zh":"這個詞描述嚴重貧窮，而不只是較不富裕。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":4},{"front":"minimum time needed to","meaning":"做……所需的最少時間","examples":[{"en":"Five days could be the minimum time needed to kill soil pests.","zh":"五天可能是殺死土壤害蟲所需的最少時間。"},{"en":"The minimum time needed to do something is the shortest amount of time required for it to happen.","zh":"Minimum time needed to do something 是某事發生所需的最短時間。"},{"en":"Ten minutes may be the minimum time needed to walk from home to the station.","zh":"十分鐘可能是從家步行到車站所需的最少時間。"},{"en":"If frost lasts less than the minimum time needed, pests may survive.","zh":"如果霜凍持續時間少於所需的最少時間，害蟲可能存活。"},{"en":"This phrase gives the lowest time requirement for a result.","zh":"這個片語提供達成結果的最低時間要求。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":4},{"front":"have something to do with","meaning":"與……有關","examples":[{"en":"Climate may have something to do with economic growth.","zh":"氣候可能與經濟增長有關。"},{"en":"To have something to do with something means to be connected with it in some way.","zh":"To have something to do with something 指以某種方式與某事有關。"},{"en":"A student’s tiredness may have something to do with staying up late.","zh":"學生疲倦可能與熬夜有關。"},{"en":"If farming success has something to do with frost, climate should be part of the explanation.","zh":"如果農業成功與霜凍有關，氣候就應成為解釋的一部分。"},{"en":"This phrase suggests a possible connection without saying it is the only cause.","zh":"這個片語暗示可能關聯，而不是說它是唯一原因。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":4},{"front":"limited frosts","meaning":"有限度的霜凍","examples":[{"en":"Limited frosts bring huge benefits to farmers.","zh":"有限度的霜凍為農民帶來巨大好處。"},{"en":"Limited frosts are moderate or occasional frosts that are enough to help without causing severe damage.","zh":"Limited frosts 是適度或偶爾出現的霜凍，足以有幫助但不造成嚴重破壞。"},{"en":"A light frost may kill pests but not destroy strong winter crops.","zh":"輕微霜凍可能殺死害蟲，但不摧毀強壯的冬季作物。"},{"en":"If frost is too severe, it can damage plants; if it is limited, it may help farming.","zh":"如果霜凍太嚴重，它會破壞植物；如果霜凍有限度，它可能幫助農業。"},{"en":"This phrase suggests useful cold in the right amount.","zh":"這個片語暗示適量寒冷是有用的。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":4},{"front":"huge benefits","meaning":"巨大好處","examples":[{"en":"Limited frosts bring huge benefits to farmers.","zh":"有限度的霜凍為農民帶來巨大好處。"},{"en":"Huge benefits are very large advantages or helpful results.","zh":"Huge benefits 是非常大的優勢或有利結果。"},{"en":"A free school bus can bring huge benefits to families who live far away.","zh":"免費校巴可以為住得遠的家庭帶來巨大好處。"},{"en":"If pests are killed naturally, farmers may gain huge benefits through better harvests.","zh":"如果害蟲被自然殺死，農民可能透過更好收成獲得巨大好處。"},{"en":"This phrase stresses that the advantage is significant, not minor.","zh":"這個片語強調好處重大，而不是微小。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":4},{"front":"render something inactive","meaning":"使……失去活動能力","examples":[{"en":"The chills kill insects or render them inactive.","zh":"寒冷會殺死昆蟲或使它們失去活動能力。"},{"en":"To render something inactive means to make it unable to move, work, or cause harm.","zh":"To render something inactive 指使某物不能移動、運作或造成傷害。"},{"en":"Cold temperatures can render some germs inactive for a period of time.","zh":"低溫可以使某些細菌在一段時間內失去活動能力。"},{"en":"If a machine’s battery dies, it may be rendered inactive until it is charged.","zh":"如果機器電池耗盡，它可能在充電前失去運作能力。"},{"en":"This phrase means something still exists but can no longer function normally.","zh":"這個片語意思是某物仍存在，但不能正常發揮功能。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":5},{"front":"break-up of plant and animal material","meaning":"動植物物質分解","examples":[{"en":"Cold weather slows the break-up of plant and animal material.","zh":"寒冷天氣減慢動植物物質分解。"},{"en":"The break-up of plant and animal material is the process by which dead plants and animals decompose into smaller parts.","zh":"Break-up of plant and animal material 是死亡植物和動物分解成較小部分的過程。"},{"en":"Fallen leaves go through break-up when they slowly turn into soil nutrients.","zh":"落葉慢慢變成土壤養分時，就是經歷分解。"},{"en":"If break-up is slower, organic material may remain in the soil for longer.","zh":"如果分解較慢，有機物質可能在土壤中停留更久。"},{"en":"This phrase describes natural decomposition, not physical breaking by hand.","zh":"這個片語描述自然分解，而不是用手物理拆碎。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":5},{"front":"allow something to become richer","meaning":"使……變得更肥沃","examples":[{"en":"Cold weather allows the soil to become richer.","zh":"寒冷天氣使土壤變得更肥沃。"},{"en":"To allow something to become richer means to create conditions that increase its quality, value, or nutrients.","zh":"To allow something to become richer 指創造條件，增加某物的質素、價值或養分。"},{"en":"Compost allows garden soil to become richer by adding organic matter.","zh":"堆肥透過加入有機物質，使花園土壤變得更肥沃。"},{"en":"If soil becomes richer, crops may grow stronger and produce better harvests.","zh":"如果土壤變得更肥沃，農作物可能長得更強壯並帶來更好收成。"},{"en":"This phrase often describes gradual improvement caused by supportive conditions.","zh":"這個片語常描述由有利條件造成的漸進改善。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":5},{"front":"build-up of moisture","meaning":"水分積聚","examples":[{"en":"Frosts ensure a build-up of moisture in the ground.","zh":"霜凍確保地下水分積聚。"},{"en":"A build-up of moisture is an increase or accumulation of water in a place.","zh":"Build-up of moisture 是某處水分增加或累積。"},{"en":"A build-up of moisture on windows can happen when warm air meets cold glass.","zh":"當暖空氣遇上冷玻璃，窗上可能出現水分積聚。"},{"en":"If moisture builds up in soil, plants may depend less on sudden rainfall.","zh":"如果土壤中水分積聚，植物可能較少依賴突然降雨。"},{"en":"This phrase describes water gradually collecting over time.","zh":"這個片語描述水分隨時間逐漸聚集。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":5},{"front":"reduce dependence on","meaning":"減少對……的依賴","examples":[{"en":"Frosts reduce dependence on seasonal rains.","zh":"霜凍減少對季節性雨水的依賴。"},{"en":"To reduce dependence on something means to need it less than before.","zh":"To reduce dependence on something 指比以前較少需要某事。"},{"en":"A family can reduce dependence on taxis by moving closer to a train station.","zh":"家庭搬近火車站後，可以減少對的士的依賴。"},{"en":"If irrigation is built, farmers may reduce dependence on uncertain rainfall.","zh":"如果建成灌溉系統，農民可能減少對不穩定降雨的依賴。"},{"en":"This phrase describes becoming less reliant on one source or method.","zh":"這個片語描述對某一來源或方法較少依賴。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":5},{"front":"seasonal rains","meaning":"季節性雨水","examples":[{"en":"Farmers may depend less on seasonal rains after frosts.","zh":"霜凍後，農民可能較少依賴季節性雨水。"},{"en":"Seasonal rains are rains that normally come during a particular season each year.","zh":"Seasonal rains 是每年通常在特定季節來臨的雨水。"},{"en":"Some farmers plant crops when seasonal rains begin.","zh":"一些農民在季節性雨水開始時種植農作物。"},{"en":"If seasonal rains fail, crops may die unless irrigation or stored moisture helps.","zh":"如果季節性雨水失效，除非有灌溉或儲存水分幫助，農作物可能死亡。"},{"en":"This phrase describes predictable yearly rainfall patterns.","zh":"這個片語描述可預測的年度降雨模式。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":5},{"front":"cold equals rich argument","meaning":"寒冷等於富裕的論點","examples":[{"en":"There are exceptions to the cold equals rich argument.","zh":"寒冷等於富裕的論點有例外。"},{"en":"The cold equals rich argument is the claim that colder countries tend to be wealthier.","zh":"Cold equals rich argument 是指較寒冷國家往往較富裕的主張。"},{"en":"A teacher may present the cold equals rich argument when discussing climate and development.","zh":"老師討論氣候與發展時，可能提出寒冷等於富裕的論點。"},{"en":"If tropical places become rich through trade, they challenge the cold equals rich argument.","zh":"如果熱帶地區透過貿易變得富裕，它們就挑戰寒冷等於富裕的論點。"},{"en":"This phrase names a simple argument that needs careful qualification.","zh":"這個片語命名一個需要仔細補充的簡化論點。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":5},{"front":"well-heeled tropical places","meaning":"富裕的熱帶地區","examples":[{"en":"Hong Kong and Singapore are well-heeled tropical places.","zh":"香港和新加坡是富裕的熱帶地區。"},{"en":"Well-heeled tropical places are wealthy areas located in warm tropical regions.","zh":"Well-heeled tropical places 是位於溫暖熱帶地區的富裕地方。"},{"en":"A port city can be well-heeled because trade brings jobs and investment.","zh":"港口城市可能因貿易帶來工作和投資而變得富裕。"},{"en":"If a tropical place has strong finance and transport, it may become rich despite the climate.","zh":"如果熱帶地區有強大金融和交通，它可能儘管氣候炎熱仍變得富裕。"},{"en":"This phrase shows that tropical regions are not always poor.","zh":"這個片語顯示熱帶地區並不總是貧窮。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":5},{"front":"superior trading positions","meaning":"優越貿易地位","examples":[{"en":"Some tropical places are rich because of superior trading positions.","zh":"一些熱帶地方因優越貿易地位而富裕。"},{"en":"Superior trading positions are geographical or economic advantages that make trade easier and more profitable.","zh":"Superior trading positions 是令貿易更容易和更有利可圖的地理或經濟優勢。"},{"en":"A city beside a busy harbour may have a superior trading position.","zh":"位於繁忙港口旁的城市可能有優越貿易地位。"},{"en":"If goods can move easily through a place, trade can bring jobs and wealth.","zh":"如果貨物能輕易通過某地，貿易可以帶來工作和財富。"},{"en":"This phrase explains how location can support economic success.","zh":"這個片語解釋位置如何支持經濟成功。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":5},{"front":"likewise","meaning":"同樣地","examples":[{"en":"Likewise, not all European countries are wealthy.","zh":"同樣地，並非所有歐洲國家都富裕。"},{"en":"Likewise means similarly or in the same way.","zh":"Likewise 指相似地或以同樣方式。"},{"en":"Some students need more reading practice; likewise, others need more speaking practice.","zh":"有些學生需要更多閱讀練習；同樣地，其他學生需要更多口語練習。"},{"en":"If one exception weakens a simple rule, another exception can likewise make the rule less certain.","zh":"如果一個例外削弱簡單規則，另一個例外同樣可以令規則不那麼確定。"},{"en":"This word connects two similar points.","zh":"這個詞連接兩個相似重點。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":5},{"front":"former communist countries","meaning":"前共產主義國家","examples":[{"en":"Some former communist countries are not wealthy.","zh":"一些前共產主義國家並不富裕。"},{"en":"Former communist countries are countries that once had communist political and economic systems.","zh":"Former communist countries 是曾經有共產主義政治和經濟制度的國家。"},{"en":"A former communist country may still be affected by past planning, state ownership, or political control.","zh":"前共產主義國家可能仍受過去的計劃經濟、國有制或政治控制影響。"},{"en":"If institutions were damaged for decades, economic recovery may be slow.","zh":"如果制度受損數十年，經濟復原可能緩慢。"},{"en":"This phrase connects political history with present economic conditions.","zh":"這個片語把政治歷史與現今經濟狀況連接起來。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":6},{"front":"economic potential","meaning":"經濟潛力","examples":[{"en":"Economic potential can be crushed by politics.","zh":"經濟潛力可以被政治摧毀。"},{"en":"Economic potential is the ability of a country, region, or business to grow and become more productive or wealthy.","zh":"Economic potential 是國家、地區或企業增長並變得更具生產力或富裕的能力。"},{"en":"A town near a port may have economic potential because goods can be traded easily.","zh":"靠近港口的城鎮可能有經濟潛力，因為貨物可以容易交易。"},{"en":"If poor laws discourage investment, economic potential may remain unused.","zh":"如果惡劣法律阻礙投資，經濟潛力可能無法發揮。"},{"en":"This phrase describes possible future wealth, not guaranteed success.","zh":"這個片語描述未來可能的財富，而不是保證成功。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":6},{"front":"be crushed by","meaning":"被……摧毀","examples":[{"en":"In some countries, economic potential was crushed by politics.","zh":"在一些國家，經濟潛力被政治摧毀。"},{"en":"To be crushed by something means to be seriously damaged or destroyed by it.","zh":"To be crushed by something 指被某事嚴重損害或摧毀。"},{"en":"A small business may be crushed by sudden rent increases.","zh":"小企業可能被突然加租摧毀。"},{"en":"If corruption crushes investment, people may lose jobs and opportunities.","zh":"如果貪污摧毀投資，人們可能失去工作和機會。"},{"en":"This phrase describes powerful negative pressure destroying something valuable.","zh":"這個片語描述強大負面壓力摧毀有價值的事物。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":6},{"front":"overriding factor","meaning":"最主要因素","examples":[{"en":"Climate will never be the overriding factor.","zh":"氣候永遠不會是最主要因素。"},{"en":"An overriding factor is the most important factor that has more influence than others.","zh":"Overriding factor 是比其他因素更有影響力的最重要因素。"},{"en":"In choosing a school, safety may be the overriding factor for parents.","zh":"父母選學校時，安全可能是最主要因素。"},{"en":"If climate is not the overriding factor, politics, trade, and institutions must also be considered.","zh":"如果氣候不是最主要因素，政治、貿易和制度也必須被考慮。"},{"en":"This phrase identifies the factor that dominates a decision or explanation.","zh":"這個片語指出支配決定或解釋的因素。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":6},{"front":"be attributable to","meaning":"可歸因於……","examples":[{"en":"The wealth of nations cannot be attributable to just one factor.","zh":"國家的財富不能只歸因於一個因素。"},{"en":"To be attributable to something means to be caused by or explained by it.","zh":"To be attributable to something 指由某事造成或可由某事解釋。"},{"en":"A student’s progress may be attributable to regular practice and better sleep.","zh":"學生的進步可能歸因於定期練習和更好睡眠。"},{"en":"If economic growth is attributable to many causes, a single-factor explanation is too simple.","zh":"如果經濟增長可歸因於許多原因，單一因素解釋就過於簡單。"},{"en":"This phrase is used when explaining causes.","zh":"這個片語用於解釋原因。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":6},{"front":"combine with","meaning":"與……結合","examples":[{"en":"Climate combines with other factors to shape wealth.","zh":"氣候與其他因素結合，塑造財富。"},{"en":"To combine with something means to work together with it.","zh":"To combine with something 指與某事共同作用。"},{"en":"Clear teaching combines with practice to help students improve.","zh":"清晰教學與練習結合，幫助學生進步。"},{"en":"If good climate combines with strong institutions, a country may develop more successfully.","zh":"如果良好氣候與強大制度結合，一個國家可能更成功地發展。"},{"en":"This phrase shows that two or more factors act together.","zh":"這個片語顯示兩個或更多因素一起發揮作用。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":6},{"front":"presence of institutions","meaning":"制度的存在","examples":[{"en":"The presence of institutions may influence national wealth.","zh":"制度的存在可能影響國家財富。"},{"en":"The presence of institutions means that organised systems, laws, courts, schools, or government bodies exist.","zh":"Presence of institutions 指有組織的制度、法律、法院、學校或政府機構存在。"},{"en":"The presence of courts can help businesses trust contracts.","zh":"法院的存在可以幫助企業信任合約。"},{"en":"If institutions are present and fair, people may invest and trade more confidently.","zh":"如果制度存在且公平，人們可能更有信心投資和交易。"},{"en":"This phrase describes the existence of formal systems that organise society.","zh":"這個片語描述組織社會的正式系統存在。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":6},{"front":"access to trading routes","meaning":"使用貿易路線的機會","examples":[{"en":"Access to trading routes can help a country prosper.","zh":"使用貿易路線的機會可以幫助一個國家繁榮。"},{"en":"Access to trading routes means the ability to use paths, ports, roads, rivers, or seas for trade.","zh":"Access to trading routes 指使用道路、港口、道路、河流或海洋進行貿易的能力。"},{"en":"A town near a major port has better access to trading routes than an isolated mountain village.","zh":"靠近主要港口的城鎮，比偏僻山村有更好的貿易路線使用機會。"},{"en":"If businesses can reach buyers easily, trade may grow and incomes may rise.","zh":"如果企業能輕易接觸買家，貿易可能增長，收入可能上升。"},{"en":"This phrase connects geography with economic opportunity.","zh":"這個片語把地理與經濟機會連接起來。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":6},{"front":"determine whether","meaning":"決定是否","examples":[{"en":"Several factors determine whether a country will do well.","zh":"幾個因素決定一個國家是否會發展順利。"},{"en":"To determine whether something happens means to decide or strongly influence if it happens.","zh":"To determine whether something happens 指決定或強烈影響某事是否發生。"},{"en":"Sleep, preparation, and confidence may determine whether a student performs well in an interview.","zh":"睡眠、準備和信心可能決定學生在面試中是否表現良好。"},{"en":"If transport and laws are weak, they may determine whether a business can grow.","zh":"如果交通和法律薄弱，它們可能決定企業是否能成長。"},{"en":"This phrase is used when one factor affects an outcome.","zh":"這個片語用於某因素影響結果的情況。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":6},{"front":"do well","meaning":"表現良好；發展順利","examples":[{"en":"Climate may help determine whether a country will do well.","zh":"氣候可能幫助決定一個國家是否會發展順利。"},{"en":"To do well means to succeed, improve, or perform strongly.","zh":"To do well 指成功、改善或表現強勁。"},{"en":"A student can do well if they practise regularly and ask for feedback.","zh":"如果學生定期練習並尋求回饋，他可以表現良好。"},{"en":"If a country has healthy workers and strong trade, it may do well economically.","zh":"如果一個國家有健康工人和強大貿易，它可能在經濟上發展順利。"},{"en":"This phrase describes success in a simple, general way.","zh":"這個片語以簡單、概括方式描述成功。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":6},{"front":"traditionally","meaning":"傳統上","examples":[{"en":"Traditionally, economists thought institutions had the biggest effect.","zh":"傳統上，經濟學家認為制度有最大影響。"},{"en":"Traditionally means according to what people commonly believed or did in the past.","zh":"Traditionally 指按照過去人們通常相信或做的方式。"},{"en":"Traditionally, many families ate together on important festival days.","zh":"傳統上，許多家庭在重要節日一起吃飯。"},{"en":"If economists traditionally focused on institutions, a climate explanation may seem new.","zh":"如果經濟學家傳統上集中於制度，氣候解釋可能顯得新穎。"},{"en":"This word contrasts older thinking with newer ideas.","zh":"這個詞把舊思維與新想法作對比。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":7},{"front":"have the biggest effect on","meaning":"對……有最大影響","examples":[{"en":"Economists thought institutions had the biggest effect on the economy.","zh":"經濟學家認為制度對經濟有最大影響。"},{"en":"To have the biggest effect on something means to influence it more than any other factor.","zh":"To have the biggest effect on something 指比任何其他因素更影響某事。"},{"en":"Sleep may have the biggest effect on a student’s morning concentration.","zh":"睡眠可能對學生早上的專注力有最大影響。"},{"en":"If laws have the biggest effect on business confidence, reforming laws becomes important.","zh":"如果法律對商業信心有最大影響，改革法律就變得重要。"},{"en":"This phrase identifies the strongest influence.","zh":"這個片語指出最強影響。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":7},{"front":"bring order to","meaning":"為……帶來秩序","examples":[{"en":"Institutions bring order to a country.","zh":"制度為一個國家帶來秩序。"},{"en":"To bring order to something means to make it organised, stable, and predictable.","zh":"To bring order to something 指令某事變得有組織、穩定和可預測。"},{"en":"Clear classroom rules bring order to group work.","zh":"清晰課室規則為小組活動帶來秩序。"},{"en":"If courts and laws bring order to business, people can trade with more trust.","zh":"如果法院和法律為商業帶來秩序，人們便可以更有信任地交易。"},{"en":"This phrase describes reducing confusion and creating structure.","zh":"這個片語描述減少混亂並建立結構。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":7},{"front":"property rights","meaning":"財產權","examples":[{"en":"Laws and property rights help create economic order.","zh":"法律和財產權幫助創造經濟秩序。"},{"en":"Property rights are legal rights to own, use, sell, or protect land, buildings, goods, or ideas.","zh":"Property rights 是擁有、使用、出售或保護土地、建築、貨物或想法的法律權利。"},{"en":"A farmer needs property rights to feel safe investing in better land.","zh":"農民需要財產權，才會安心投資改善土地。"},{"en":"If property rights are weak, people may fear losing what they build or buy.","zh":"如果財產權薄弱，人們可能害怕失去自己建造或購買的東西。"},{"en":"This phrase connects law with ownership and economic confidence.","zh":"這個片語把法律與所有權和經濟信心連接起來。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":7},{"front":"so the thinking went","meaning":"當時的想法是","examples":[{"en":"With order, so the thinking went, came affluence.","zh":"當時的想法是，有了秩序，就會有富裕。"},{"en":"So the thinking went means this was the common belief or reasoning at the time.","zh":"So the thinking went 指這是當時常見的信念或推理。"},{"en":"If children had more homework, so the thinking went, they would learn more.","zh":"當時的想法是，如果孩子有更多功課，他們就會學得更多。"},{"en":"Writers use this phrase to describe an idea without fully accepting it.","zh":"作者使用這個片語來描述一種想法，而不一定完全接受它。"},{"en":"This phrase signals a reported line of reasoning, not necessarily the writer’s own view.","zh":"這個片語標示被轉述的推理，而不一定是作者自己的看法。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":7},{"front":"affluence","meaning":"富裕","examples":[{"en":"Economists believed that order brought affluence.","zh":"經濟學家相信秩序帶來富裕。"},{"en":"Affluence means wealth, comfort, and a high standard of living.","zh":"Affluence 指財富、舒適和高生活水平。"},{"en":"A family with affluence can afford good housing, healthcare, and education.","zh":"富裕家庭能負擔良好住屋、醫療和教育。"},{"en":"If a city gains jobs and trade, affluence may spread among more residents.","zh":"如果城市獲得工作和貿易，富裕可能擴展到更多居民。"},{"en":"This word describes prosperity, not just having enough to survive.","zh":"這個詞描述繁榮，而不只是足以生存。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":7},{"front":"get around","meaning":"克服；繞過","examples":[{"en":"Some problems cannot be solved even by strong institutions.","zh":"有些問題即使有強大制度也無法解決。"},{"en":"To get around a problem means to find a way to avoid or overcome it.","zh":"To get around a problem 指找到方法避開或克服問題。"},{"en":"A student may get around a broken printer by submitting homework online.","zh":"學生可能透過網上提交功課來繞過打印機壞了的問題。"},{"en":"If heat and disease are serious, institutions alone may not get around the problem.","zh":"如果炎熱和疾病嚴重，單靠制度未必能克服問題。"},{"en":"This phrase describes finding a practical way past an obstacle.","zh":"這個片語描述找到實際方法越過障礙。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":7},{"front":"accumulation of wealth","meaning":"財富累積","examples":[{"en":"The accumulation of wealth is helped by a favourable environment.","zh":"有利環境有助財富累積。"},{"en":"The accumulation of wealth means the gradual building up of money, assets, and economic resources.","zh":"Accumulation of wealth 指金錢、資產和經濟資源逐步建立起來。"},{"en":"A family’s accumulation of wealth may come from saving, education, and steady work.","zh":"家庭的財富累積可能來自儲蓄、教育和穩定工作。"},{"en":"If farming produces surplus food, it can support the accumulation of wealth.","zh":"如果農業產生剩餘食物，它可以支持財富累積。"},{"en":"This phrase describes wealth growing over time, not appearing suddenly.","zh":"這個片語描述財富隨時間增長，而不是突然出現。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":7},{"front":"improvement in governing institutions","meaning":"管治制度改善","examples":[{"en":"Improvement in governing institutions may follow economic growth.","zh":"管治制度改善可能跟隨經濟增長而來。"},{"en":"Improvement in governing institutions means government systems, courts, laws, or public bodies become better and fairer.","zh":"Improvement in governing institutions 指政府制度、法院、法律或公共機構變得更好和更公平。"},{"en":"A city may see improvement in governing institutions when permits become faster and less corrupt.","zh":"當許可程序變得更快且較少貪污，城市可能出現管治制度改善。"},{"en":"If wealth grows, governments may collect more taxes and improve public services.","zh":"如果財富增長，政府可能收取更多稅款並改善公共服務。"},{"en":"This phrase connects better governance with economic development.","zh":"這個片語把更好管治與經濟發展連接起來。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":7},{"front":"favourable environment","meaning":"有利環境","examples":[{"en":"A favourable environment can help wealth and institutions develop.","zh":"有利環境可以幫助財富和制度發展。"},{"en":"A favourable environment is a set of conditions that makes success easier.","zh":"Favourable environment 是一組令成功更容易的條件。"},{"en":"A quiet home and supportive parents create a favourable environment for study.","zh":"安靜家庭和支持子女的父母為學習創造有利環境。"},{"en":"If soil, health, and transport are good, farmers and businesses may develop faster.","zh":"如果土壤、健康和交通良好，農民和企業可能發展得更快。"},{"en":"This phrase describes helpful surroundings or conditions.","zh":"這個片語描述有幫助的周圍環境或條件。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":7},{"front":"beyond economic help","meaning":"無法透過經濟援助改善","examples":[{"en":"Masters does not think tropical countries are beyond economic help.","zh":"Masters不認為熱帶國家無法透過經濟援助改善。"},{"en":"Beyond economic help means too damaged or poor to be improved by economic support.","zh":"Beyond economic help 指受損或貧窮到無法透過經濟支援改善。"},{"en":"A struggling village is not beyond economic help if it receives clean water, training, and roads.","zh":"如果獲得清潔食水、培訓和道路，困難村莊並非無法透過經濟援助改善。"},{"en":"If the right aid targets disease and farming, poor regions may still improve.","zh":"如果正確援助針對疾病和農業，貧窮地區仍可能改善。"},{"en":"This phrase is often used to reject hopeless thinking.","zh":"這個片語常用來否定絕望想法。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":8},{"front":"destined to remain penniless","meaning":"注定一貧如洗","examples":[{"en":"Tropical countries are not destined to remain penniless.","zh":"熱帶國家並非注定一貧如洗。"},{"en":"Destined to remain penniless means certain to stay extremely poor forever.","zh":"Destined to remain penniless 指註定永遠極度貧窮。"},{"en":"A student from a poor family is not destined to remain poor if education and support are available.","zh":"如果有教育和支援，來自貧窮家庭的學生並非注定貧窮。"},{"en":"If technology improves farming and health, a country’s future can change.","zh":"如果科技改善農業和健康，一個國家的未來可以改變。"},{"en":"This phrase rejects the idea that poverty is unavoidable.","zh":"這個片語否定貧窮不可避免的想法。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":8},{"front":"foreign aid","meaning":"外援","examples":[{"en":"Richer countries should change the way foreign aid is given.","zh":"較富裕國家應改變提供外援的方式。"},{"en":"Foreign aid is help, money, food, medicine, or expertise given by one country to another.","zh":"Foreign aid 是一個國家向另一個國家提供的幫助、金錢、食物、藥物或專業知識。"},{"en":"After a flood, foreign aid may include clean water, tents, and medical teams.","zh":"水災後，外援可能包括清潔食水、帳篷和醫療隊。"},{"en":"If foreign aid is used badly, it may not solve the real causes of poverty.","zh":"如果外援使用不當，它可能無法解決貧窮的真正原因。"},{"en":"This phrase describes international support for countries in need.","zh":"這個片語描述對有需要國家的國際支援。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":8},{"front":"be geared towards","meaning":"以……為目標","examples":[{"en":"Aid is often geared towards improving governance.","zh":"援助通常以改善管治為目標。"},{"en":"To be geared towards something means to be designed or directed for that purpose.","zh":"To be geared towards something 指為某目的而設計或導向。"},{"en":"A course geared towards beginners uses simple language and clear examples.","zh":"以初學者為目標的課程會使用簡單語言和清楚例子。"},{"en":"If aid is geared towards health, money may go to vaccines and clinics.","zh":"如果援助以健康為目標，資金可能用於疫苗和診所。"},{"en":"This phrase describes the main aim or direction of a plan.","zh":"這個片語描述計劃的主要目標或方向。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":8},{"front":"improving governance","meaning":"改善管治","examples":[{"en":"Some aid is designed for improving governance.","zh":"一些援助是為改善管治而設計。"},{"en":"Improving governance means making government systems more honest, effective, fair, and organised.","zh":"Improving governance 指令政府制度更誠實、有效、公平和有組織。"},{"en":"A city improves governance when public money is tracked clearly and decisions are explained.","zh":"當公共資金被清楚追蹤且決策得到解釋，城市就在改善管治。"},{"en":"If governance improves, citizens may trust public institutions more.","zh":"如果管治改善，市民可能更信任公共制度。"},{"en":"This phrase focuses on better government management and accountability.","zh":"這個片語著重更好的政府管理和問責。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":8},{"front":"combat disease","meaning":"對抗疾病","examples":[{"en":"Aid should be used to improve agriculture and combat disease.","zh":"援助應用於改善農業和對抗疾病。"},{"en":"To combat disease means to fight disease and reduce its spread or harm.","zh":"To combat disease 指對抗疾病並減少其傳播或傷害。"},{"en":"Vaccination programmes combat disease by protecting people before they become sick.","zh":"疫苗接種計劃透過在人們生病前保護他們來對抗疾病。"},{"en":"If malaria is reduced, families may work and study more regularly.","zh":"如果瘧疾減少，家庭可能更穩定地工作和學習。"},{"en":"This phrase describes active efforts to control health problems.","zh":"這個片語描述控制健康問題的主動努力。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":8},{"front":"cite one example","meaning":"舉出一個例子","examples":[{"en":"Masters cites one example from India.","zh":"Masters舉出一個來自印度的例子。"},{"en":"To cite one example means to mention one specific case as evidence or illustration.","zh":"To cite one example 指提及一個具體個案作為證據或說明。"},{"en":"A teacher may cite one example from a student essay to show a grammar problem.","zh":"老師可能從學生作文中舉出一個例子來展示文法問題。"},{"en":"If a writer cites an example, readers can see how the idea works in real life.","zh":"如果作者舉例，讀者可以看見想法如何在現實中運作。"},{"en":"This phrase introduces a concrete supporting case.","zh":"這個片語引出具體支持例子。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":8},{"front":"be provided with","meaning":"獲提供……","examples":[{"en":"Some regions in India have been provided with irrigation.","zh":"印度一些地區獲提供灌溉。"},{"en":"To be provided with something means to receive it or be given access to it.","zh":"To be provided with something 指收到某物或獲得使用某物的機會。"},{"en":"Students may be provided with tablets for online learning.","zh":"學生可能獲提供平板電腦以進行網上學習。"},{"en":"If farmers are provided with irrigation, they can grow crops even when rain is unreliable.","zh":"如果農民獲提供灌溉，即使降雨不穩定，他們也可以種植農作物。"},{"en":"This phrase describes receiving a useful resource or service.","zh":"這個片語描述獲得有用資源或服務。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":8},{"front":"irrigation","meaning":"灌溉","examples":[{"en":"Irrigation has improved agricultural productivity in parts of India.","zh":"灌溉改善了印度部分地區的農業生產力。"},{"en":"Irrigation is the supply of water to land or crops through channels, pipes, or other systems.","zh":"Irrigation 是透過水渠、水管或其他系統向土地或農作物供水。"},{"en":"Farmers use irrigation when rainfall is too low or too uncertain.","zh":"當降雨太少或太不穩定，農民會使用灌溉。"},{"en":"If irrigation works well, crops can grow during dry periods.","zh":"如果灌溉運作良好，農作物可以在乾旱時期生長。"},{"en":"This word is central to farming in areas with unreliable rain.","zh":"這個詞對降雨不穩定地區的農業非常重要。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":8},{"front":"agricultural productivity","meaning":"農業生產力","examples":[{"en":"Agricultural productivity has gone up in irrigated regions.","zh":"灌溉地區的農業生產力上升了。"},{"en":"Agricultural productivity is the amount of food or crops produced from land, labour, and resources.","zh":"Agricultural productivity 是土地、勞動力和資源能生產多少食物或農作物。"},{"en":"Better seeds and irrigation can raise agricultural productivity.","zh":"更好的種子和灌溉可以提高農業生產力。"},{"en":"If agricultural productivity rises, farmers may earn more and food may become cheaper.","zh":"如果農業生產力上升，農民可能賺更多，食物也可能變便宜。"},{"en":"This phrase measures how efficiently farming produces output.","zh":"這個片語衡量農業生產產出的效率。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":8},{"front":"improvement in health","meaning":"健康改善","examples":[{"en":"Irrigation was linked to an improvement in health.","zh":"灌溉與健康改善有關。"},{"en":"An improvement in health means people become healthier or suffer less disease.","zh":"Improvement in health 指人們變得更健康或較少受疾病困擾。"},{"en":"Clean drinking water can lead to an improvement in health among children.","zh":"清潔飲用水可以令兒童健康改善。"},{"en":"If farming improves food supply, people’s nutrition and health may improve.","zh":"如果農業改善食物供應，人們的營養和健康可能改善。"},{"en":"This phrase describes better physical well-being in a person or community.","zh":"這個片語描述個人或社區身體狀況變好。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":9},{"front":"supply vaccines against","meaning":"提供針對……的疫苗","examples":[{"en":"Richer countries could supply vaccines against tropical diseases.","zh":"較富裕國家可以提供針對熱帶疾病的疫苗。"},{"en":"To supply vaccines against a disease means to provide injections or medicines that protect people from that disease.","zh":"To supply vaccines against a disease 指提供保護人們免受該疾病感染的注射或藥物。"},{"en":"Health centres may supply vaccines against flu before winter begins.","zh":"健康中心可能在冬天開始前提供針對流感的疫苗。"},{"en":"If vaccines are supplied widely, fewer people may become seriously ill.","zh":"如果疫苗被廣泛提供，較少人可能患重病。"},{"en":"This phrase describes providing preventive medical protection.","zh":"這個片語描述提供預防性醫療保護。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":9},{"front":"tropical diseases","meaning":"熱帶疾病","examples":[{"en":"Vaccines against tropical diseases could help break poverty.","zh":"針對熱帶疾病的疫苗可以幫助打破貧窮。"},{"en":"Tropical diseases are illnesses that are common in hot, humid regions near the tropics.","zh":"Tropical diseases 是常見於靠近熱帶、炎熱潮濕地區的疾病。"},{"en":"Malaria is often discussed as a tropical disease because it spreads through mosquitoes in warm areas.","zh":"瘧疾常被討論為熱帶疾病，因為它在溫暖地區透過蚊子傳播。"},{"en":"If tropical diseases reduce workers’ health, they can weaken economic growth.","zh":"如果熱帶疾病削弱工人健康，它們可以削弱經濟增長。"},{"en":"This phrase connects climate, health, and development.","zh":"這個片語連接氣候、健康和發展。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":9},{"front":"crop varieties","meaning":"農作物品種","examples":[{"en":"New crop varieties could grow better in the tropics.","zh":"新農作物品種可以在熱帶地區生長得更好。"},{"en":"Crop varieties are different types of the same crop, often bred for particular climates, soils, or diseases.","zh":"Crop varieties 是同一種作物的不同類型，通常為特定氣候、土壤或疾病而培育。"},{"en":"A farmer may choose a rice variety that grows well with less water.","zh":"農民可能選擇在較少水分下也能生長良好的稻米品種。"},{"en":"If crop varieties resist heat and pests, harvests may improve.","zh":"如果農作物品種能抵抗高溫和害蟲，收成可能改善。"},{"en":"This phrase describes plant types selected for farming needs.","zh":"這個片語描述因應農業需要而選擇的植物類型。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":9},{"front":"break the poverty cycle","meaning":"打破貧窮循環","examples":[{"en":"Technology and vaccines could break the poverty cycle.","zh":"科技和疫苗可以打破貧窮循環。"},{"en":"To break the poverty cycle means to stop poverty from passing from one generation or problem to the next.","zh":"To break the poverty cycle 指阻止貧窮從一代或一個問題延續到下一代或下一個問題。"},{"en":"Education can break the poverty cycle when children gain skills for better jobs.","zh":"當兒童獲得更好工作所需技能，教育可以打破貧窮循環。"},{"en":"If disease keeps adults from working, healthcare may help break the cycle.","zh":"如果疾病令成年人無法工作，醫療保健可能幫助打破循環。"},{"en":"This phrase describes ending repeated poverty, not giving temporary relief only.","zh":"這個片語描述終結反覆貧窮，而不只是提供短期救濟。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":9},{"front":"apply oneself to","meaning":"致力研究","examples":[{"en":"Other minds have applied themselves to the split between poor and rich nations.","zh":"其他學者也致力研究貧窮國家與富裕國家之間的分化。"},{"en":"To apply oneself to a problem means to study or work on it seriously.","zh":"To apply oneself to a problem 指認真研究或處理某問題。"},{"en":"A student who applies herself to maths practises regularly and checks mistakes carefully.","zh":"致力學數學的學生會定期練習並仔細檢查錯誤。"},{"en":"If researchers apply themselves to poverty, they may test many different explanations.","zh":"如果研究人員致力研究貧窮，他們可能測試許多不同解釋。"},{"en":"This phrase shows focused effort and serious attention.","zh":"這個片語顯示集中努力和認真注意。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":9},{"front":"split between","meaning":"……之間的分化","examples":[{"en":"Researchers have studied the split between poor and rich nations.","zh":"研究人員研究了貧窮國家與富裕國家之間的分化。"},{"en":"The split between two groups is the division or gap that separates them.","zh":"Split between two groups 是分隔兩個群體的分化或差距。"},{"en":"The split between high-income and low-income families can affect children’s education.","zh":"高收入和低收入家庭之間的分化可以影響兒童教育。"},{"en":"If the split between rich and poor nations grows, global inequality becomes worse.","zh":"如果富國與窮國之間的分化擴大，全球不平等會惡化。"},{"en":"This phrase describes a clear difference between two sides.","zh":"這個片語描述兩方之間的清楚差異。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":9},{"front":"cite reasons for","meaning":"列舉……的原因","examples":[{"en":"Researchers cite several reasons for temperate nations being richer.","zh":"研究人員列舉溫帶國家較富裕的幾個原因。"},{"en":"To cite reasons for something means to give explanations or evidence for it.","zh":"To cite reasons for something 指給出某事的解釋或證據。"},{"en":"A teacher may cite reasons for a student’s progress, such as practice and feedback.","zh":"老師可能列舉學生進步的原因，例如練習和回饋。"},{"en":"If economists cite several reasons for wealth, they avoid a single-cause explanation.","zh":"如果經濟學家列舉財富的幾個原因，他們就避免單一原因解釋。"},{"en":"This phrase introduces supporting explanations.","zh":"這個片語引出支持性解釋。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":9},{"front":"anthropological reasons","meaning":"人類學原因","examples":[{"en":"Some researchers cite anthropological reasons for national wealth.","zh":"一些研究人員列舉國家財富的人類學原因。"},{"en":"Anthropological reasons are explanations based on human cultures, societies, customs, and ways of living.","zh":"Anthropological reasons 是基於人類文化、社會、習俗和生活方式的解釋。"},{"en":"A researcher may use anthropological reasons to explain why communities organise work differently.","zh":"研究人員可能用人類學原因解釋為何社區以不同方式組織工作。"},{"en":"If culture shapes trust or cooperation, it may affect economic development.","zh":"如果文化塑造信任或合作，它可能影響經濟發展。"},{"en":"This phrase connects human social life with a larger outcome.","zh":"這個片語把人類社會生活與更大結果連接起來。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":9},{"front":"zoological reasons","meaning":"動物學原因","examples":[{"en":"Some explanations include zoological reasons.","zh":"一些解釋包括動物學原因。"},{"en":"Zoological reasons are explanations related to animals, animal behaviour, or animal availability.","zh":"Zoological reasons 是與動物、動物行為或可用動物有關的解釋。"},{"en":"The presence of horses or cattle can be a zoological reason for easier transport and farming.","zh":"馬或牛的存在可以是令交通和農業更容易的動物學原因。"},{"en":"If a region lacks useful domesticated animals, economic development may be affected.","zh":"如果一個地區缺乏有用的馴養動物，經濟發展可能受影響。"},{"en":"This phrase connects animals with human development.","zh":"這個片語把動物與人類發展連接起來。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":9},{"front":"temperate nations","meaning":"溫帶國家","examples":[{"en":"Temperate nations are often more affluent.","zh":"溫帶國家往往較富裕。"},{"en":"Temperate nations are countries in moderate climate zones, not extremely hot or extremely cold.","zh":"Temperate nations 是位於溫和氣候帶的國家，不是極熱或極冷。"},{"en":"France and Germany are examples of countries in temperate regions.","zh":"法國和德國是溫帶地區國家的例子。"},{"en":"If temperate climates support farming and reduce some diseases, nations there may gain advantages.","zh":"如果溫帶氣候支持農業並減少某些疾病，當地國家可能獲得優勢。"},{"en":"This phrase describes countries by climate zone.","zh":"這個片語以氣候帶描述國家。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":10},{"front":"the most affluent","meaning":"最富裕的","examples":[{"en":"Temperate nations are often the most affluent.","zh":"溫帶國家往往是最富裕的。"},{"en":"The most affluent means the richest or most prosperous compared with others.","zh":"The most affluent 指與其他相比最富有或最繁榮。"},{"en":"The most affluent families in a city can usually afford better housing and private services.","zh":"城市中最富裕的家庭通常能負擔更好住屋和私人服務。"},{"en":"If a region becomes the most affluent, it may attract more businesses and skilled workers.","zh":"如果一個地區變成最富裕，它可能吸引更多企業和熟練工人。"},{"en":"This phrase identifies the highest level of wealth in a comparison.","zh":"這個片語指出比較中的最高財富水平。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":10},{"front":"full of spirit","meaning":"充滿精神；勇氣十足","examples":[{"en":"Aristotle said people in cold climates are full of spirit.","zh":"亞里士多德說寒冷氣候中的人充滿精神。"},{"en":"Full of spirit means energetic, brave, determined, or lively.","zh":"Full of spirit 指有活力、勇敢、堅定或生氣勃勃。"},{"en":"A class full of spirit keeps trying even after difficult practice.","zh":"充滿精神的班級即使練習困難仍會繼續努力。"},{"en":"If workers are full of spirit, they may face hardship with more confidence.","zh":"如果工人勇氣十足，他們可能更有信心面對困難。"},{"en":"This phrase describes energy and courage, not physical strength only.","zh":"這個片語描述活力和勇氣，而不只是體力。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":10},{"front":"be broadly aligned","meaning":"大致呈……排列","examples":[{"en":"Eurasia is broadly aligned east-west.","zh":"歐亞大陸大致呈東西向排列。"},{"en":"To be broadly aligned means to be arranged mostly in a particular direction or pattern.","zh":"To be broadly aligned 指大致按照某個方向或模式排列。"},{"en":"Desks in a classroom may be broadly aligned in rows facing the board.","zh":"課室中的書桌可能大致排成面向黑板的行列。"},{"en":"If a continent is aligned east-west, similar climates may stretch across wide areas.","zh":"如果大陸呈東西向排列，相似氣候可能橫跨廣闊地區。"},{"en":"This phrase describes general arrangement, not perfect straightness.","zh":"這個片語描述大致排列，而不是完全筆直。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":10},{"front":"east-west","meaning":"東西向","examples":[{"en":"Eurasia is broadly aligned east-west.","zh":"歐亞大陸大致呈東西向排列。"},{"en":"East-west means running or arranged from east to west.","zh":"East-west 指從東向西延伸或排列。"},{"en":"A long road may run east-west across a city.","zh":"一條長路可能東西向橫穿城市。"},{"en":"If crops move east-west, they may stay within similar climates.","zh":"如果農作物東西向傳播，它們可能保持在相似氣候中。"},{"en":"This phrase describes direction across longitude rather than from north to south.","zh":"這個片語描述橫向方向，而不是南北方向。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":10},{"front":"north-south","meaning":"南北向","examples":[{"en":"Africa and the Americas are aligned north-south.","zh":"非洲和美洲呈南北向排列。"},{"en":"North-south means running or arranged from north to south.","zh":"North-south 指從北向南延伸或排列。"},{"en":"A mountain range may run north-south along a country’s border.","zh":"山脈可能沿國界南北向延伸。"},{"en":"If crops move north-south, they may cross very different climate zones.","zh":"如果農作物南北向傳播，它們可能跨越非常不同的氣候帶。"},{"en":"This phrase describes vertical geographical direction.","zh":"這個片語描述垂直的地理方向。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":10},{"front":"spread quickly across latitudes","meaning":"沿緯度快速傳播","examples":[{"en":"Crops can spread quickly across latitudes in Europe.","zh":"農作物可以在歐洲沿緯度快速傳播。"},{"en":"To spread quickly across latitudes means to move fast across places with similar distance from the equator.","zh":"To spread quickly across latitudes 指在與赤道距離相似的地方之間快速移動。"},{"en":"A crop suited to one temperate region may spread quickly across similar latitudes.","zh":"適合某溫帶地區的作物可能沿相似緯度快速傳播。"},{"en":"If climate stays similar, farmers in nearby latitudes can adopt the same crops more easily.","zh":"如果氣候保持相似，附近緯度的農民更容易採用同一農作物。"},{"en":"This phrase links crop movement with climate similarity.","zh":"這個片語把農作物傳播與氣候相似性連接起來。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":10},{"front":"similar climates","meaning":"相似氣候","examples":[{"en":"Crops spread more easily where climates are similar.","zh":"氣候相似的地方，農作物更容易傳播。"},{"en":"Similar climates are places with alike temperatures, rainfall, seasons, and growing conditions.","zh":"Similar climates 是溫度、降雨、季節和生長條件相近的地方。"},{"en":"A plant from one cool wet region may grow well in another area with similar climate.","zh":"來自寒冷潮濕地區的植物，可能在另一個相似氣候地區生長良好。"},{"en":"If climates are similar, farmers can transfer crops and techniques more successfully.","zh":"如果氣候相似，農民可以更成功地轉移作物和技術。"},{"en":"This phrase explains why geography affects agriculture.","zh":"這個片語解釋為何地理影響農業。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":10},{"front":"domesticated crops","meaning":"馴化農作物","examples":[{"en":"Einkorn wheat was one of the first domesticated crops.","zh":"一粒小麥是最早的馴化農作物之一。"},{"en":"Domesticated crops are plants that humans have selected and grown for food over many generations.","zh":"Domesticated crops 是人類經過許多代選育和種植作為食物的植物。"},{"en":"Rice, wheat, and maize are domesticated crops used by millions of people.","zh":"稻米、小麥和粟米都是數百萬人使用的馴化農作物。"},{"en":"If crops are domesticated, they often become easier to grow and harvest.","zh":"如果農作物被馴化，它們通常變得更容易種植和收割。"},{"en":"This phrase connects farming with long-term human selection.","zh":"這個片語把農業與人類長期選育連接起來。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":10},{"front":"einkorn wheat","meaning":"一粒小麥","examples":[{"en":"Einkorn wheat spread quickly from the Middle East into Europe.","zh":"一粒小麥從中東迅速傳入歐洲。"},{"en":"Einkorn wheat is an ancient type of wheat that was among the earliest crops domesticated by humans.","zh":"Einkorn wheat 是一種古老小麥，是人類最早馴化的農作物之一。"},{"en":"Archaeologists study einkorn wheat to understand early farming.","zh":"考古學家研究一粒小麥，以理解早期農業。"},{"en":"If einkorn wheat could grow in similar climates, it could spread across regions more easily.","zh":"如果一粒小麥能在相似氣候中生長，它就能更容易跨地區傳播。"},{"en":"This phrase names a specific early crop important in agricultural history.","zh":"這個片語命名農業歷史中重要的特定早期作物。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":10},{"front":"the Middle East","meaning":"中東","examples":[{"en":"Einkorn wheat spread from the Middle East into Europe.","zh":"一粒小麥從中東傳入歐洲。"},{"en":"The Middle East is a region that includes countries in western Asia and nearby areas, historically important for early farming and trade.","zh":"The Middle East 是包括西亞及附近地區的區域，在早期農業和貿易史上很重要。"},{"en":"Many ancient trade routes passed through the Middle East.","zh":"許多古代貿易路線經過中東。"},{"en":"If a crop began in the Middle East, it could spread to nearby regions through migration and trade.","zh":"如果一種農作物起源於中東，它可以透過遷徙和貿易傳到附近地區。"},{"en":"This phrase refers to a major historical and geographical region.","zh":"這個片語指一個重要歷史和地理區域。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":11},{"front":"take twice as long","meaning":"花兩倍時間","examples":[{"en":"Corn took twice as long to spread from Mexico to the eastern United States.","zh":"粟米從墨西哥傳到美國東部花了兩倍時間。"},{"en":"To take twice as long means to require double the time.","zh":"To take twice as long 指需要雙倍時間。"},{"en":"Walking may take twice as long as taking the bus.","zh":"步行可能比乘巴士花兩倍時間。"},{"en":"If crops cross very different climates, they may take twice as long to adapt and spread.","zh":"如果農作物跨越非常不同的氣候，它們可能花兩倍時間適應和傳播。"},{"en":"This phrase compares the time needed for two processes.","zh":"這個片語比較兩個過程所需時間。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":11},{"front":"easy movement along","meaning":"沿……輕易移動","examples":[{"en":"Easy movement along similar latitudes helped spread crops and technology.","zh":"沿相似緯度輕易移動有助農作物和技術傳播。"},{"en":"Easy movement along a route means people, goods, crops, or ideas can travel through it without major difficulty.","zh":"Easy movement along a route 指人、貨物、農作物或想法能在路線上沒有重大困難地移動。"},{"en":"Easy movement along a railway line helps workers reach jobs faster.","zh":"沿鐵路線輕易移動幫助工人更快到達工作地點。"},{"en":"If movement along similar latitudes is easy, crops can spread without facing extreme climate changes.","zh":"如果沿相似緯度移動容易，農作物就能在不面對極端氣候變化下傳播。"},{"en":"This phrase connects geography with movement and diffusion.","zh":"這個片語把地理與移動和擴散連接起來。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":11},{"front":"dissemination of technology","meaning":"技術傳播","examples":[{"en":"Similar latitudes enabled faster dissemination of technology.","zh":"相似緯度使技術傳播更快。"},{"en":"Dissemination of technology means the spread of tools, methods, and technical knowledge to more places or people.","zh":"Dissemination of technology 指工具、方法和技術知識傳播到更多地方或人群。"},{"en":"The Internet speeds up dissemination of technology by sharing instructions online.","zh":"互聯網透過網上分享指示加快技術傳播。"},{"en":"If technology spreads quickly, communities can copy useful methods sooner.","zh":"如果技術迅速傳播，社區可以更快複製有用方法。"},{"en":"This phrase describes technology moving from one place or group to another.","zh":"這個片語描述技術從一個地方或群體傳到另一個。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":11},{"front":"boast domesticated livestock","meaning":"擁有馴養牲畜","examples":[{"en":"The region also boasted domesticated livestock.","zh":"該地區也擁有馴養牲畜。"},{"en":"To boast domesticated livestock means to have useful farm animals that humans have bred and managed.","zh":"To boast domesticated livestock 指擁有人類培育和管理的有用農場動物。"},{"en":"A village may boast cattle, sheep, and goats that provide food and labour.","zh":"村莊可能擁有牛、羊和山羊，提供食物和勞力。"},{"en":"If a region has domesticated livestock, farming and transport may become easier.","zh":"如果一個地區有馴養牲畜，農業和交通可能變得更容易。"},{"en":"This phrase means the region had an important advantage, not that it was showing off.","zh":"這個片語意思是該地區擁有重要優勢，而不是炫耀。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":11},{"front":"motive power","meaning":"動力","examples":[{"en":"Livestock could provide meat, wool and motive power.","zh":"牲畜可以提供肉、羊毛和動力。"},{"en":"Motive power is the force that moves machines, vehicles, or tools.","zh":"Motive power 是推動機器、車輛或工具的力量。"},{"en":"Before engines, oxen and horses provided motive power for ploughs and carts.","zh":"在引擎出現前，牛和馬為犁和車提供動力。"},{"en":"If animals provide motive power, farmers can move heavier loads and cultivate more land.","zh":"如果動物提供動力，農民可以搬運更重貨物並耕作更多土地。"},{"en":"This phrase describes energy used to create movement.","zh":"這個片語描述用來產生移動的能量。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":11},{"front":"blessed with","meaning":"享有……","examples":[{"en":"Eurasia was blessed with natural advantages.","zh":"歐亞大陸享有天然優勢。"},{"en":"To be blessed with something means to have a valuable advantage or good condition.","zh":"To be blessed with something 指擁有有價值的優勢或良好條件。"},{"en":"A school blessed with experienced teachers can support students more effectively.","zh":"享有經驗豐富老師的學校可以更有效支援學生。"},{"en":"If a country is blessed with good soil and rivers, farming may be easier.","zh":"如果一個國家享有良好土壤和河流，農業可能更容易。"},{"en":"This phrase means fortunate to have something helpful.","zh":"這個片語意思是幸運地擁有有幫助的東西。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":11},{"front":"natural advantages","meaning":"天然優勢","examples":[{"en":"Natural advantages helped Eurasia develop economically.","zh":"天然優勢幫助歐亞大陸在經濟上發展。"},{"en":"Natural advantages are helpful features of geography, climate, plants, animals, or resources.","zh":"Natural advantages 是地理、氣候、植物、動物或資源中的有利特徵。"},{"en":"A harbour is a natural advantage for a city that wants to trade.","zh":"對想進行貿易的城市來說，港口是一項天然優勢。"},{"en":"If a region has fertile soil and useful animals, its natural advantages may support growth.","zh":"如果地區有肥沃土壤和有用動物，其天然優勢可能支持增長。"},{"en":"This phrase describes benefits provided by nature.","zh":"這個片語描述大自然提供的好處。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":11},{"front":"be bound to","meaning":"必然會……","examples":[{"en":"Eurasia was bound to take off economically.","zh":"歐亞大陸必然會經濟起飛。"},{"en":"To be bound to do something means to be very likely or almost certain to do it.","zh":"To be bound to do something 指非常可能或幾乎一定會做某事。"},{"en":"A student who practises speaking every day is bound to improve.","zh":"每天練習口語的學生必然會進步。"},{"en":"If a region has many advantages, people may think it is bound to grow.","zh":"如果一個地區有許多優勢，人們可能認為它必然會增長。"},{"en":"This phrase expresses strong expectation.","zh":"這個片語表達強烈預期。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":11},{"front":"take off economically","meaning":"經濟起飛","examples":[{"en":"Eurasia was likely to take off economically.","zh":"歐亞大陸可能會經濟起飛。"},{"en":"To take off economically means to begin growing quickly in wealth, trade, and production.","zh":"To take off economically 指在財富、貿易和生產方面開始快速增長。"},{"en":"A town may take off economically after a new port or railway opens.","zh":"新港口或鐵路開通後，城鎮可能經濟起飛。"},{"en":"If businesses invest and jobs increase, an economy can take off.","zh":"如果企業投資且工作增加，經濟可以起飛。"},{"en":"This phrase describes rapid economic growth after conditions become favourable.","zh":"這個片語描述條件變得有利後的快速經濟增長。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":11},{"front":"striking correlations","meaning":"顯著相關性","examples":[{"en":"Economists have pointed out striking correlations between geography and wealth.","zh":"經濟學家指出地理與財富之間有顯著相關性。"},{"en":"Striking correlations are clear and surprising patterns in which two things seem to change together.","zh":"Striking correlations 是兩件事似乎一起變化的清晰且令人驚訝的模式。"},{"en":"A teacher may notice a striking correlation between attendance and exam results.","zh":"老師可能注意到出席率和考試成績之間有顯著相關性。"},{"en":"If countries with certain climates are often richer, that is a striking correlation worth studying.","zh":"如果某些氣候的國家往往較富裕，那就是值得研究的顯著相關性。"},{"en":"This phrase suggests a strong pattern, but not automatic proof of cause.","zh":"這個片語暗示強烈模式，但不自動證明因果。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":12},{"front":"geographical location","meaning":"地理位置","examples":[{"en":"Geographical location may be related to national wealth.","zh":"地理位置可能與國家財富有關。"},{"en":"Geographical location is where a place is situated on the earth.","zh":"Geographical location 是一個地方在地球上的位置。"},{"en":"A city beside the sea may have a useful geographical location for trade.","zh":"臨海城市可能有利於貿易的地理位置。"},{"en":"If a country’s location blocks access to markets, economic growth may be harder.","zh":"如果一個國家的位置阻礙接觸市場，經濟增長可能更困難。"},{"en":"This phrase connects place on the map with practical advantages or limits.","zh":"這個片語把地圖上的位置與實際優勢或限制連接起來。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":12},{"front":"north and south of the equator","meaning":"赤道南北","examples":[{"en":"Tropical countries lie between 23.45 degrees north and south of the equator.","zh":"熱帶國家位於赤道南北23.45度之間。"},{"en":"North and south of the equator means above and below the imaginary line around the middle of the earth.","zh":"North and south of the equator 指位於環繞地球中部的假想線上下。"},{"en":"Countries near the equator often have warmer climates all year.","zh":"靠近赤道的國家通常全年氣候較暖。"},{"en":"If a region lies close to the equator, it may face different diseases and farming conditions.","zh":"如果一個地區靠近赤道，它可能面對不同疾病和農業條件。"},{"en":"This phrase helps describe global location by relation to the equator.","zh":"這個片語幫助用與赤道的關係描述全球位置。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":12},{"front":"favour the temperate-zone economies","meaning":"有利於溫帶經濟體","examples":[{"en":"Development seems to favour the temperate-zone economies.","zh":"發展似乎有利於溫帶經濟體。"},{"en":"To favour the temperate-zone economies means to give economic advantages to countries in moderate climate regions.","zh":"To favour the temperate-zone economies 指為溫和氣候地區的國家提供經濟優勢。"},{"en":"A policy may favour city businesses if it gives them better transport links.","zh":"如果政策給城市企業更好交通連接，它可能有利於城市企業。"},{"en":"If climate, crops, and disease patterns favour temperate zones, those economies may grow faster.","zh":"如果氣候、農作物和疾病模式有利於溫帶，這些經濟體可能增長更快。"},{"en":"This phrase suggests one group has conditions that help it more than others.","zh":"這個片語暗示某群體有比其他群體更有幫助的條件。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":12},{"front":"Northern Hemisphere","meaning":"北半球","examples":[{"en":"Many rich countries are in the Northern Hemisphere.","zh":"許多富裕國家位於北半球。"},{"en":"The Northern Hemisphere is the half of the earth north of the equator.","zh":"Northern Hemisphere 是赤道以北的地球半球。"},{"en":"Europe, North America, and much of Asia are in the Northern Hemisphere.","zh":"歐洲、北美和亞洲大部分地區都位於北半球。"},{"en":"If many wealthy countries lie there, researchers may examine geography and climate.","zh":"如果許多富裕國家位於那裡，研究人員可能檢視地理和氣候。"},{"en":"This phrase describes a large half of the globe.","zh":"這個片語描述地球的一大半。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":12},{"front":"avoid socialism","meaning":"避免社會主義","examples":[{"en":"Some successful economies avoided socialism.","zh":"一些成功經濟體避免了社會主義。"},{"en":"To avoid socialism means not to adopt a socialist political or economic system.","zh":"To avoid socialism 指不採用社會主義政治或經濟制度。"},{"en":"A country may avoid socialism and instead rely more on private businesses and markets.","zh":"一個國家可能避免社會主義，轉而更依賴私人企業和市場。"},{"en":"If political systems differ, economic outcomes may differ even in similar climates.","zh":"如果政治制度不同，即使氣候相似，經濟結果也可能不同。"},{"en":"This phrase connects political choice with economic development.","zh":"這個片語把政治選擇與經濟發展連接起來。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":12},{"front":"ravages of war","meaning":"戰爭蹂躪","examples":[{"en":"War can damage a country’s development.","zh":"戰爭可以破壞一個國家的發展。"},{"en":"The ravages of war are the severe destruction, suffering, and long-term damage caused by war.","zh":"Ravages of war 是戰爭造成的嚴重破壞、痛苦和長期傷害。"},{"en":"A city may take decades to recover from the ravages of war.","zh":"城市可能需要數十年才能從戰爭蹂躪中復原。"},{"en":"If factories, roads, and schools are destroyed, economic growth slows.","zh":"如果工廠、道路和學校被摧毀，經濟增長會放慢。"},{"en":"This phrase stresses war’s destructive effects on society.","zh":"這個片語強調戰爭對社會的破壞性影響。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":12},{"front":"caution against","meaning":"警惕不要……","examples":[{"en":"Masters cautions against geographical determinism.","zh":"Masters警惕不要接受地理決定論。"},{"en":"To caution against something means to warn people not to accept or do it too easily.","zh":"To caution against something 指警告人們不要太輕易接受或做某事。"},{"en":"Doctors caution against taking medicine without reading instructions.","zh":"醫生警惕人們不要在未讀指示下服藥。"},{"en":"If a theory is too simple, researchers may caution against relying on it completely.","zh":"如果理論過於簡單，研究人員可能警惕不要完全依賴它。"},{"en":"This phrase introduces a warning.","zh":"這個片語引出警告。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":12},{"front":"geographical determinism","meaning":"地理決定論","examples":[{"en":"Geographical determinism claims that geography determines economic fate.","zh":"地理決定論聲稱地理決定經濟命運。"},{"en":"Geographical determinism is the belief that geography alone decides how societies develop.","zh":"Geographical determinism 是相信單靠地理就決定社會如何發展的想法。"},{"en":"Saying a tropical country must always be poor would be a form of geographical determinism.","zh":"說熱帶國家必然永遠貧窮，就是一種地理決定論。"},{"en":"If people accept geographical determinism, they may ignore politics, technology, and policy choices.","zh":"如果人們接受地理決定論，可能忽視政治、科技和政策選擇。"},{"en":"This phrase names an overly fixed view of geography’s power.","zh":"這個片語命名一種過分固定地看待地理力量的觀點。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":12},{"front":"beyond hope","meaning":"沒有希望","examples":[{"en":"Masters rejects the idea that tropical countries are beyond hope.","zh":"Masters否定熱帶國家沒有希望這一想法。"},{"en":"Beyond hope means impossible to improve or save.","zh":"Beyond hope 指不可能改善或拯救。"},{"en":"A weak student is not beyond hope if teaching becomes clearer and practice is regular.","zh":"如果教學更清楚且練習定期，能力弱的學生並非沒有希望。"},{"en":"If disease and farming problems can be treated, poor regions are not beyond hope.","zh":"如果疾病和農業問題可以處理，貧窮地區並非沒有希望。"},{"en":"This phrase rejects complete pessimism.","zh":"這個片語否定完全悲觀。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":12},{"front":"scientific and technological research","meaning":"科學和技術研究","examples":[{"en":"Scientific and technological research can improve health and agriculture.","zh":"科學和技術研究可以改善健康和農業。"},{"en":"Scientific and technological research is systematic study that develops knowledge, tools, methods, or inventions.","zh":"Scientific and technological research 是發展知識、工具、方法或發明的系統性研究。"},{"en":"Research into drought-resistant crops can help farmers in dry regions.","zh":"對抗旱農作物的研究可以幫助乾旱地區的農民。"},{"en":"If research produces better vaccines, disease may fall and productivity may rise.","zh":"如果研究產生更好疫苗，疾病可能減少，生產力可能上升。"},{"en":"This phrase connects knowledge creation with practical solutions.","zh":"這個片語把知識創造與實際解決方法連接起來。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":13},{"front":"write off","meaning":"放棄；認為……無望","examples":[{"en":"We should not write off tropical countries.","zh":"我們不應認為熱帶國家無望。"},{"en":"To write off a person or place means to decide too quickly that they cannot succeed or improve.","zh":"To write off a person or place 指過早認定他們不能成功或改善。"},{"en":"A teacher should not write off a quiet student who needs more time to speak.","zh":"老師不應放棄需要更多時間開口的安靜學生。"},{"en":"If investors write off a poor region, they may miss its future potential.","zh":"如果投資者認為貧窮地區無望，他們可能錯過其未來潛力。"},{"en":"This phrase warns against giving up on someone or something too soon.","zh":"這個片語提醒人不要太早放棄某人或某事。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":13},{"front":"air conditioning","meaning":"冷氣","examples":[{"en":"Without air conditioning, Singapore would not be rich.","zh":"沒有冷氣，新加坡就不會富裕。"},{"en":"Air conditioning is a system that cools and often dries the air inside buildings or vehicles.","zh":"Air conditioning 是冷卻並通常降低建築物或車輛內空氣濕度的系統。"},{"en":"Offices in hot cities often need air conditioning so workers can concentrate.","zh":"炎熱城市中的辦公室常需要冷氣，讓員工能專心。"},{"en":"If heat reduces productivity, air conditioning can make work and business easier.","zh":"如果高溫降低生產力，冷氣可以令工作和商業更容易。"},{"en":"This phrase shows how technology can reduce the limits of climate.","zh":"這個片語顯示科技如何減少氣候限制。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":13},{"front":"choose the most suitable heading","meaning":"選出最合適的小標題","examples":[{"en":"Students must choose the most suitable heading for each paragraph.","zh":"學生必須為每段選出最合適的小標題。"},{"en":"To choose the most suitable heading means to select the title that best summarises the paragraph’s main idea.","zh":"To choose the most suitable heading 指選出最能概括段落主要意思的標題。"},{"en":"In a reading test, students should choose the heading after understanding the whole paragraph.","zh":"在閱讀測驗中，學生應在理解整段後才選標題。"},{"en":"If a heading matches only one small detail, it is probably not the most suitable one.","zh":"如果標題只配合一個小細節，它很可能不是最合適的小標題。"},{"en":"This phrase describes a common paragraph-matching task.","zh":"這個片語描述常見的段落配對題。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":13},{"front":"positive correlation","meaning":"正相關","examples":[{"en":"The passage discusses a positive correlation between climate and wealth.","zh":"文章討論氣候與財富之間的正相關。"},{"en":"A positive correlation means that two things tend to increase or appear together.","zh":"Positive correlation 指兩件事往往一起增加或一起出現。"},{"en":"There may be a positive correlation between regular reading and vocabulary growth.","zh":"定期閱讀與詞彙增長之間可能有正相關。"},{"en":"If frost and wealth appear together often, researchers may see a positive correlation.","zh":"如果霜凍和財富常一起出現，研究人員可能看見正相關。"},{"en":"This phrase shows a pattern, but it does not by itself prove cause.","zh":"這個片語顯示一種模式，但本身不能證明因果。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":13},{"front":"factors other than","meaning":"除……以外的因素","examples":[{"en":"The passage considers factors other than climate.","zh":"文章考慮除氣候以外的因素。"},{"en":"Factors other than something are additional causes or influences apart from that one.","zh":"Factors other than something 是除了該因素之外的其他原因或影響。"},{"en":"A student’s result may depend on factors other than intelligence, such as sleep and practice.","zh":"學生成績可能取決於智力以外的因素，例如睡眠和練習。"},{"en":"If wealth depends on factors other than climate, politics and trade must also be studied.","zh":"如果財富取決於氣候以外的因素，政治和貿易也必須被研究。"},{"en":"This phrase helps avoid an overly simple explanation.","zh":"這個片語幫助避免過分簡化的解釋。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":13},{"front":"benefit people and crops","meaning":"有利於人和農作物","examples":[{"en":"Low temperatures may benefit people and crops.","zh":"低溫可能有利於人和農作物。"},{"en":"To benefit people and crops means to help both human health and plant growth.","zh":"To benefit people and crops 指同時幫助人類健康和植物生長。"},{"en":"Clean water can benefit people and crops by supporting health and irrigation.","zh":"清潔食水可以透過支持健康和灌溉，有利於人和農作物。"},{"en":"If frost kills pests and disease-carrying insects, it may benefit farmers and communities.","zh":"如果霜凍殺死害蟲和傳播疾病的昆蟲，它可能有利於農民和社區。"},{"en":"This phrase shows that one condition can help both society and agriculture.","zh":"這個片語顯示一個條件可以同時幫助社會和農業。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":13},{"front":"traditional view","meaning":"傳統觀點","examples":[{"en":"The traditional view emphasised the importance of institutions.","zh":"傳統觀點強調制度的重要性。"},{"en":"A traditional view is an older or commonly accepted way of understanding an issue.","zh":"Traditional view 是較舊或被普遍接受的理解某議題的方式。"},{"en":"The traditional view of learning often focused on textbooks and exams.","zh":"對學習的傳統觀點常集中於教科書和考試。"},{"en":"If new evidence appears, a traditional view may need to be revised.","zh":"如果新證據出現，傳統觀點可能需要修訂。"},{"en":"This phrase contrasts established thinking with newer explanations.","zh":"這個片語把既有思維與較新的解釋作對比。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":13},{"front":"best way to use foreign aid","meaning":"使用外援的最佳方法","examples":[{"en":"The passage suggests the best way to use foreign aid.","zh":"文章提出使用外援的最佳方法。"},{"en":"The best way to use foreign aid means the most effective method of spending or directing international support.","zh":"Best way to use foreign aid 指花費或引導國際支援的最有效方法。"},{"en":"The best way to use foreign aid after floods may be to provide clean water first.","zh":"水災後使用外援的最佳方法可能是先提供清潔食水。"},{"en":"If aid targets disease and farming, it may create longer-term benefits.","zh":"如果援助針對疾病和農業，它可能創造較長遠好處。"},{"en":"This phrase focuses on using help wisely, not simply giving more money.","zh":"這個片語著重明智使用援助，而不只是給更多錢。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":13},{"front":"complications and exceptions","meaning":"複雜情況和例外","examples":[{"en":"The argument includes complications and exceptions.","zh":"這個論點包括複雜情況和例外。"},{"en":"Complications and exceptions are details that make a simple argument less complete or less certain.","zh":"Complications and exceptions 是令簡單論點不那麼完整或不那麼確定的細節。"},{"en":"A rule about study habits may have complications and exceptions because students learn differently.","zh":"關於學習習慣的規則可能有複雜情況和例外，因為學生學習方式不同。"},{"en":"If Singapore is rich despite being tropical, it is an exception to a climate argument.","zh":"如果新加坡身處熱帶卻富裕，它就是氣候論點的例外。"},{"en":"This phrase shows that real life is more complex than a simple rule.","zh":"這個片語顯示現實生活比簡單規則更複雜。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":13},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"To complete the summary below means to fill in missing words in the summary that follows the instruction.","zh":"To complete the summary below 指填寫指示下方摘要中的缺失字詞。"},{"en":"Students should read the whole summary before choosing answers.","zh":"學生應先閱讀整個摘要，再選擇答案。"},{"en":"If the grammar around a blank needs a noun, the answer should fit that grammar.","zh":"如果空格周圍文法需要名詞，答案應符合該文法。"},{"en":"This phrase is a common reading-test instruction.","zh":"這個片語是常見閱讀測驗指示。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":14},{"front":"no more than two words","meaning":"不超過兩個詞","examples":[{"en":"Each answer should contain no more than two words.","zh":"每個答案應包含不超過兩個詞。"},{"en":"No more than two words means the answer may have one or two words only.","zh":"No more than two words 指答案只能有一個或兩個詞。"},{"en":"If the correct idea needs three words, students must find a shorter wording from the passage.","zh":"如果正確意思需要三個詞，學生必須從文章中找較短用字。"},{"en":"If students write too many words, the answer may be marked wrong even if the meaning is close.","zh":"如果學生寫太多詞，即使意思接近，答案也可能被判錯。"},{"en":"This phrase sets a strict word limit in exam answers.","zh":"這個片語為考試答案設定嚴格字數限制。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":14},{"front":"hundreds of years ago","meaning":"數百年前","examples":[{"en":"A yellow fever epidemic struck an American city hundreds of years ago.","zh":"數百年前，一場黃熱病疫情襲擊一座美國城市。"},{"en":"Hundreds of years ago means several centuries before the present.","zh":"Hundreds of years ago 指距今幾個世紀以前。"},{"en":"Hundreds of years ago, people travelled long distances without cars or trains.","zh":"數百年前，人們沒有汽車或火車也要長途旅行。"},{"en":"If an event happened hundreds of years ago, historians rely on records and written accounts.","zh":"如果事件發生在數百年前，歷史學家依賴記錄和文字敘述。"},{"en":"This phrase gives a general historical time, not an exact date.","zh":"這個片語提供概括歷史時間，而不是精確日期。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":14},{"front":"prosperous country","meaning":"繁榮國家","examples":[{"en":"Finland is described as a small but prosperous country.","zh":"芬蘭被描述為一個小而繁榮的國家。"},{"en":"A prosperous country is a country that is wealthy, successful, and economically healthy.","zh":"Prosperous country 是富裕、成功且經濟健康的國家。"},{"en":"A prosperous country can usually provide better schools, hospitals, and public services.","zh":"繁榮國家通常可以提供更好的學校、醫院和公共服務。"},{"en":"If trade grows and jobs increase, a country may become more prosperous.","zh":"如果貿易增長且工作增加，一個國家可能變得更繁榮。"},{"en":"This phrase describes national success and material well-being.","zh":"這個片語描述國家成功和物質福祉。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":14},{"front":"long-term prosperity","meaning":"長遠繁榮","examples":[{"en":"A country needs better institutions to achieve long-term prosperity.","zh":"一個國家需要更好的制度來達致長遠繁榮。"},{"en":"Long-term prosperity means wealth and success that continue for many years.","zh":"Long-term prosperity 指持續許多年的財富和成功。"},{"en":"A family builds long-term prosperity by saving, learning skills, and avoiding debt.","zh":"家庭透過儲蓄、學習技能和避免債務建立長遠繁榮。"},{"en":"If a country protects health, education, and fair laws, prosperity may last longer.","zh":"如果一個國家保護健康、教育和公平法律，繁榮可能持續更久。"},{"en":"This phrase describes durable success, not a short boom.","zh":"這個片語描述持久成功，而不是短暫繁榮。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":14},{"front":"climatic conditions","meaning":"氣候條件","examples":[{"en":"Similar climatic conditions helped crops spread across Eurasia.","zh":"相似氣候條件幫助農作物在歐亞大陸傳播。"},{"en":"Climatic conditions are the temperature, rainfall, seasons, humidity, and other climate features of a place.","zh":"Climatic conditions 是一個地方的溫度、降雨、季節、濕度和其他氣候特徵。"},{"en":"Farmers choose crops according to local climatic conditions.","zh":"農民根據當地氣候條件選擇農作物。"},{"en":"If climatic conditions are similar, crops may grow successfully in a new region.","zh":"如果氣候條件相似，農作物可能在新地區成功生長。"},{"en":"This phrase describes the climate factors that affect life and farming.","zh":"這個片語描述影響生活和農業的氣候因素。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":14},{"front":"technological advances","meaning":"技術進步","examples":[{"en":"A tropical country can become rich through technological advances.","zh":"熱帶國家可以透過技術進步變得富裕。"},{"en":"Technological advances are improvements in tools, machines, methods, or scientific knowledge.","zh":"Technological advances 是工具、機器、方法或科學知識方面的改善。"},{"en":"Mobile banking is a technological advance that can help people without local banks.","zh":"流動銀行是一項技術進步，可以幫助沒有本地銀行的人。"},{"en":"If technology reduces heat, disease, or farming problems, poorer regions may grow faster.","zh":"如果科技減少高溫、疾病或農業問題，較貧窮地區可能增長更快。"},{"en":"This phrase describes progress through better technology.","zh":"這個片語描述透過更好科技帶來的進步。"}],"source":"39 - Wealth in A Cold Climate.pdf","sourcePage":14}],"ielts/reading/passage-2/Practice 40":[{"front":"from a novice to an expert","meaning":"由初學者到專家","examples":[{"en":"The passage explains how a learner develops from a novice to an expert.","zh":"文章解釋學習者如何由初學者發展成專家。"},{"en":"From a novice to an expert means moving from a beginner level to a highly skilled level.","zh":"from a novice to an expert 指由初學者水平進步到高度熟練水平。"},{"en":"A piano student may move from a novice to an expert after years of lessons, practice and performances.","zh":"鋼琴學生經過多年上課、練習和演出後，可能由初學者變成專家。"},{"en":"This development usually requires guidance at first and independent judgement later.","zh":"這種發展通常一開始需要指導，之後需要獨立判斷。"},{"en":"The phrase describes a long learning journey, not a quick improvement.","zh":"這個短語描述漫長學習旅程，而不是快速進步。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":1},{"front":"expertise","meaning":"專業知識；專門技能","examples":[{"en":"Expertise is commitment coupled with creativity.","zh":"專業知識是投入加上創意。"},{"en":"Expertise is deep knowledge and skill in a particular area.","zh":"expertise 是某個特定範疇中的深厚知識和技能。"},{"en":"A doctor develops expertise after treating many patients and studying difficult cases.","zh":"醫生在治療許多病人並研究困難個案後，會發展出專業知識。"},{"en":"Expertise helps people notice patterns that beginners usually miss.","zh":"專業知識幫助人注意到初學者通常錯過的模式。"},{"en":"The word suggests proven ability, not just interest in a topic.","zh":"這個字暗示經證明的能力，而不只是對題目有興趣。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":1},{"front":"commitment coupled with creativity","meaning":"投入加上創意","examples":[{"en":"Expertise is commitment coupled with creativity.","zh":"專業知識是投入加上創意。"},{"en":"Commitment coupled with creativity means steady effort joined with the ability to produce new ideas.","zh":"commitment coupled with creativity 指穩定努力配合產生新想法的能力。"},{"en":"A teacher shows commitment coupled with creativity when she keeps improving lessons for weaker students.","zh":"老師持續改進課堂以幫助較弱學生時，就是展現投入加上創意。"},{"en":"Commitment gives the learner time to practise, while creativity helps the learner solve new problems.","zh":"投入給學習者時間練習，而創意幫助學習者解決新問題。"},{"en":"The phrase shows that hard work alone is not enough for real expertise.","zh":"這個短語顯示單靠努力並不足以形成真正專業。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":1},{"front":"specifically","meaning":"具體而言","examples":[{"en":"Specifically, expertise requires time, energy and resources.","zh":"具體而言，專業知識需要時間、精力和資源。"},{"en":"Specifically means more exactly or in more detail.","zh":"specifically 指更準確地或更詳細地說。"},{"en":"A teacher may say, “Improve your writing,” and then explain specifically which grammar mistakes to fix.","zh":"老師可能先說「改善你的寫作」，然後具體說明要改哪些文法錯誤。"},{"en":"Using “specifically” helps readers see that a general idea is becoming more precise.","zh":"使用 specifically 幫助讀者看見一般想法正變得更精確。"},{"en":"The word introduces clearer details rather than another broad statement.","zh":"這個字引出更清楚的細節，而不是另一個籠統說法。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":1},{"front":"commitment of time, energy and resources","meaning":"投入時間、精力和資源","examples":[{"en":"Expertise requires the commitment of time, energy and resources.","zh":"專業知識需要投入時間、精力和資源。"},{"en":"Commitment of time, energy and resources means giving real effort, attention and support to something over time.","zh":"commitment of time, energy and resources 指長期把真正努力、注意力和支援投入某事。"},{"en":"A student preparing for medical school must commit time, energy and resources to study and practice.","zh":"準備讀醫科的學生必須投入時間、精力和資源去學習和練習。"},{"en":"Without this commitment, progress usually stays shallow and inconsistent.","zh":"沒有這種投入，進步通常會停留在表面且不穩定。"},{"en":"The phrase shows that serious learning has a cost.","zh":"這個短語顯示認真學習是有成本的。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":1},{"front":"relatively narrow field of study","meaning":"相對狹窄的研究領域","examples":[{"en":"An expert usually works in a relatively narrow field of study.","zh":"專家通常在相對狹窄的研究領域中工作。"},{"en":"A relatively narrow field of study is a specialised area rather than a very broad subject.","zh":"relatively narrow field of study 是專門範疇，而不是非常廣泛的學科。"},{"en":"A scientist may study one type of cancer instead of all human diseases.","zh":"科學家可能研究一種癌症，而不是所有人類疾病。"},{"en":"A narrow focus allows the expert to collect many cases and understand details deeply.","zh":"狹窄焦點讓專家收集大量個案並深入理解細節。"},{"en":"The phrase suggests specialisation, not limited intelligence.","zh":"這個短語暗示專門化，而不是智力有限。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":1},{"front":"creative energy","meaning":"創造力；創意能量","examples":[{"en":"Experts need creative energy to generate new knowledge.","zh":"專家需要創意能量來產生新知識。"},{"en":"Creative energy is the mental power used to imagine, design or discover something new.","zh":"creative energy 是用來想像、設計或發現新事物的心理力量。"},{"en":"A designer uses creative energy when turning a simple room into a useful learning space.","zh":"設計師把普通房間變成有用學習空間時，就是使用創造力。"},{"en":"Without creative energy, an expert may repeat old ideas without improving them.","zh":"沒有創造力，專家可能只重複舊想法而不改進它們。"},{"en":"The phrase connects expertise with invention and fresh thinking.","zh":"這個短語把專業與創新和新思考連繫起來。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":1},{"front":"generate new knowledge","meaning":"產生新知識","examples":[{"en":"Experts generate new knowledge in their field.","zh":"專家在其領域中產生新知識。"},{"en":"To generate new knowledge means to create fresh understanding, ideas or findings.","zh":"generate new knowledge 指創造新的理解、想法或發現。"},{"en":"A teacher may generate new knowledge by testing which examples help beginners learn fastest.","zh":"老師可以透過測試哪些例子最能幫助初學者快速學習來產生新知識。"},{"en":"New knowledge often comes from comparing many cases and asking better questions.","zh":"新知識常來自比較大量個案並提出更好的問題。"},{"en":"The phrase describes creating knowledge, not simply memorising existing information.","zh":"這個短語描述創造知識，而不是只記住現有資訊。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":1},{"front":"in that field","meaning":"在該領域中","examples":[{"en":"Expertise requires new knowledge in that field.","zh":"專業知識需要在該領域中產生新知識。"},{"en":"In that field means inside the particular area of study, work or skill being discussed.","zh":"in that field 指在所討論的特定研究、工作或技能範疇之內。"},{"en":"A lawyer may be excellent in family law but not in every field of law.","zh":"律師可能在家庭法方面很出色，但不是在所有法律領域都出色。"},{"en":"Experts are strongest when the problem stays in the field they know deeply.","zh":"當問題留在專家深知的領域中，專家最強。"},{"en":"The phrase limits the statement to a specific domain.","zh":"這個短語把陳述限制在特定範疇內。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":1},{"front":"considerable amount of time","meaning":"相當長的時間","examples":[{"en":"It takes a considerable amount of time to become an expert.","zh":"成為專家需要相當長的時間。"},{"en":"A considerable amount of time means a large or significant period, not just a few days.","zh":"considerable amount of time 指一段很長或相當重要的時間，而不是幾天。"},{"en":"Learning to write strong essays takes a considerable amount of time and feedback.","zh":"學會寫高質文章需要相當長時間和回饋。"},{"en":"Because expertise builds slowly, rushing the process often leads to weak understanding.","zh":"因為專業能力慢慢建立，急於求成通常導致理解薄弱。"},{"en":"The phrase reminds learners that deep skill requires patience.","zh":"這個短語提醒學習者，深層技能需要耐性。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":1},{"front":"regular exposure to","meaning":"定期接觸……","examples":[{"en":"Becoming an expert requires regular exposure to many cases.","zh":"成為專家需要定期接觸許多個案。"},{"en":"Regular exposure to something means meeting or experiencing it repeatedly over time.","zh":"regular exposure to 某事，指長期反覆接觸或經歷它。"},{"en":"A language learner needs regular exposure to natural English through reading and listening.","zh":"語言學習者需要透過閱讀和聆聽定期接觸自然英語。"},{"en":"Repeated exposure helps the brain notice patterns that one example cannot show.","zh":"反覆接觸幫助大腦注意到單一例子不能顯示的模式。"},{"en":"The phrase stresses repeated contact, not a single experience.","zh":"這個短語強調重複接觸，而不是一次經驗。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":2},{"front":"a large number of cases","meaning":"大量個案","examples":[{"en":"An expert needs exposure to a large number of cases.","zh":"專家需要接觸大量個案。"},{"en":"A large number of cases means many examples, problems or situations of the same general type.","zh":"a large number of cases 指許多同一大類的例子、問題或情況。"},{"en":"A doctor learns faster after seeing a large number of patients with similar symptoms.","zh":"醫生見過大量有相似症狀的病人後，會學得更快。"},{"en":"Many cases help the learner separate normal patterns from unusual exceptions.","zh":"大量個案幫助學習者分辨正常模式和不尋常例外。"},{"en":"The phrase explains why experience matters in expertise.","zh":"這個短語解釋為何經驗對專業能力重要。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":2},{"front":"enter a field of study","meaning":"進入某個研究領域","examples":[{"en":"An individual enters a field of study as a novice.","zh":"一個人以初學者身份進入某個研究領域。"},{"en":"To enter a field of study means to begin learning or working in a particular academic or professional area.","zh":"enter a field of study 指開始學習或從事某個特定學術或專業範疇。"},{"en":"A student may enter the field of psychology after taking an introductory course.","zh":"學生修讀入門課程後，可能進入心理學領域。"},{"en":"When someone enters a new field, they usually need basic rules and examples first.","zh":"當某人進入新領域時，通常首先需要基本規則和例子。"},{"en":"The phrase describes the beginning of a learning path.","zh":"這個短語描述學習道路的開始。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":2},{"front":"novice","meaning":"初學者","examples":[{"en":"A novice needs guidance and practice.","zh":"初學者需要指導和練習。"},{"en":"A novice is a beginner who has little experience in a skill or subject.","zh":"novice 是在某技能或學科中經驗很少的初學者。"},{"en":"A novice driver may need help judging distance and speed.","zh":"初學駕駛者可能需要幫助判斷距離和速度。"},{"en":"Novices often depend on clear rules because they cannot yet recognise deeper patterns.","zh":"初學者常依靠清楚規則，因為他們尚未能辨認更深層模式。"},{"en":"The word describes an early stage of learning, not a lack of potential.","zh":"這個字描述學習早期階段，而不是缺乏潛力。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":2},{"front":"guiding principles and rules","meaning":"指導原則和規則","examples":[{"en":"The novice needs to learn the guiding principles and rules of a task.","zh":"初學者需要學習某項任務的指導原則和規則。"},{"en":"Guiding principles and rules are basic ideas and instructions that help someone act correctly.","zh":"guiding principles and rules 是幫助人正確行動的基本想法和指示。"},{"en":"A new cashier learns rules for payments, refunds and customer service.","zh":"新收銀員會學習付款、退款和顧客服務的規則。"},{"en":"These rules reduce confusion before the learner has enough experience to judge alone.","zh":"在學習者有足夠經驗自行判斷前，這些規則能減少混亂。"},{"en":"The phrase refers to the foundation that beginners use to start safely.","zh":"這個短語指初學者安全開始時使用的基礎。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":2},{"front":"a given task","meaning":"某項指定任務","examples":[{"en":"The novice learns rules in order to perform a given task.","zh":"初學者學習規則，以執行某項指定任務。"},{"en":"A given task is a specific job or activity that someone is expected to complete.","zh":"a given task 是某人被期望完成的特定工作或活動。"},{"en":"A student may learn a formula in order to solve a given maths problem.","zh":"學生可能學習公式，以解決某道指定數學題。"},{"en":"Understanding the task clearly prevents beginners from using the wrong method.","zh":"清楚理解任務可以防止初學者使用錯誤方法。"},{"en":"The phrase points to one particular task, not every possible task.","zh":"這個短語指某一項特定任務，而不是所有可能任務。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":2},{"front":"in order to perform","meaning":"為了執行……","examples":[{"en":"The novice learns the rules in order to perform the task.","zh":"初學者學習規則，為了執行該任務。"},{"en":"In order to perform means for the purpose of doing or completing something.","zh":"in order to perform 指為了做或完成某事。"},{"en":"A nurse learns safety procedures in order to perform patient care correctly.","zh":"護士學習安全程序，是為了正確執行病人護理。"},{"en":"Clear preparation helps beginners perform a task with fewer errors.","zh":"清楚準備幫助初學者以較少錯誤完成任務。"},{"en":"The phrase shows the purpose behind learning or preparation.","zh":"這個短語顯示學習或準備背後的目的。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":2},{"front":"concurrently","meaning":"同時","examples":[{"en":"Concurrently, the novice needs to be exposed to specific cases.","zh":"同時，初學者需要接觸具體個案。"},{"en":"Concurrently means at the same time as another process or activity.","zh":"concurrently 指與另一個過程或活動同時發生。"},{"en":"A student may learn grammar rules and concurrently practise them in speaking.","zh":"學生可以學文法規則，同時在口語中練習它們。"},{"en":"Learning theory and examples together helps beginners connect rules with real situations.","zh":"同時學理論和例子幫助初學者把規則與真實情況連繫起來。"},{"en":"The word shows that two things happen side by side.","zh":"這個字顯示兩件事並行發生。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":2},{"front":"be exposed to","meaning":"接觸到……","examples":[{"en":"The novice needs to be exposed to specific cases.","zh":"初學者需要接觸到具體個案。"},{"en":"To be exposed to something means to come into contact with it and learn from it.","zh":"be exposed to 某事，指接觸到它並從中學習。"},{"en":"Children exposed to different books often develop stronger vocabulary.","zh":"接觸到不同書本的孩子通常會發展出更強詞彙。"},{"en":"Exposure helps learners move beyond rules and see how ideas work in real life.","zh":"接觸幫助學習者超越規則，看見想法在現實中如何運作。"},{"en":"The phrase describes contact that can shape understanding.","zh":"這個短語描述能塑造理解的接觸。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":2},{"front":"specific cases","meaning":"具體個案","examples":[{"en":"Specific cases help test the boundaries of general principles.","zh":"具體個案幫助測試一般原則的界限。"},{"en":"Specific cases are particular examples that show how a rule works in real situations.","zh":"specific cases 是顯示規則在真實情況中如何運作的特定例子。"},{"en":"A law student studies specific cases to understand how judges apply legal principles.","zh":"法律學生研究具體案例，以理解法官如何應用法律原則。"},{"en":"Specific cases can reveal exceptions that a general rule does not explain clearly.","zh":"具體個案可以揭示一般規則不能清楚解釋的例外。"},{"en":"The phrase means concrete examples, not abstract theory.","zh":"這個短語指具體例子，而不是抽象理論。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":2},{"front":"instances","meaning":"實例","examples":[{"en":"Instances are specific examples that test the rules.","zh":"實例是測試規則的具體例子。"},{"en":"Instances are individual examples or occurrences of a larger pattern.","zh":"instances 是較大模式中的個別例子或出現情況。"},{"en":"A teacher may collect instances of common spelling mistakes from students’ essays.","zh":"老師可能從學生作文中收集常見拼字錯誤的實例。"},{"en":"Many instances help learners see whether a rule works often or only sometimes.","zh":"許多實例幫助學習者看見規則是經常有效，還是只在某些時候有效。"},{"en":"The word is useful when discussing examples inside a broader idea.","zh":"這個字適合用來討論較大想法中的例子。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":3},{"front":"test the boundaries of","meaning":"測試……的界限","examples":[{"en":"Specific cases test the boundaries of such principles.","zh":"具體個案測試這些原則的界限。"},{"en":"To test the boundaries of something means to check where its limits are.","zh":"test the boundaries of 某事，指檢查它的限制在哪裏。"},{"en":"A difficult grammar question can test the boundaries of a rule students thought was simple.","zh":"困難文法題可以測試學生以為簡單的規則的界限。"},{"en":"Testing boundaries helps learners see when a principle works and when it fails.","zh":"測試界限幫助學習者看見原則何時有效、何時失效。"},{"en":"The phrase describes exploring limits, not rejecting the rule completely.","zh":"這個短語描述探索限制，而不是完全否定規則。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":3},{"front":"generally","meaning":"一般而言","examples":[{"en":"Generally, a novice will find a mentor.","zh":"一般而言，初學者會找到導師。"},{"en":"Generally means usually or in most cases, though not always.","zh":"generally 指通常或在大多數情況下，但不是永遠如此。"},{"en":"Generally, students learn faster when examples are clear and practice is regular.","zh":"一般而言，當例子清楚且練習定期，學生會學得更快。"},{"en":"The word allows a speaker to describe a common pattern without claiming it is universal.","zh":"這個字讓說話者描述常見模式，而不聲稱它普遍適用。"},{"en":"Generally is useful when there may be exceptions.","zh":"當可能有例外時，generally 很有用。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":3},{"front":"find a mentor","meaning":"找到導師","examples":[{"en":"A novice will usually find a mentor.","zh":"初學者通常會找到導師。"},{"en":"To find a mentor means to get guidance from someone more experienced.","zh":"find a mentor 指從更有經驗的人那裏得到指導。"},{"en":"A new teacher may find a mentor who helps with lesson planning and classroom management.","zh":"新老師可能找到一位導師，幫助備課和管理課室。"},{"en":"A mentor can shorten the learning process by warning beginners about common mistakes.","zh":"導師可以提醒初學者常見錯誤，從而縮短學習過程。"},{"en":"The phrase describes seeking support, not copying someone blindly.","zh":"這個短語描述尋求支援，而不是盲目模仿某人。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":3},{"front":"guide someone through","meaning":"引導某人完成……","examples":[{"en":"A mentor guides the novice through the learning process.","zh":"導師引導初學者完成學習過程。"},{"en":"To guide someone through something means to help them move step by step through a difficult process.","zh":"guide someone through 某事，指一步一步幫助某人完成困難過程。"},{"en":"A nurse may guide a patient through the steps of taking new medicine safely.","zh":"護士可能引導病人安全服用新藥的步驟。"},{"en":"Guidance reduces confusion because the learner knows what to do next.","zh":"指導能減少混亂，因為學習者知道下一步要做甚麼。"},{"en":"The phrase suggests steady support from beginning to end.","zh":"這個短語暗示從開始到結束的穩定支援。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":3},{"front":"process of acquiring new knowledge","meaning":"獲取新知識的過程","examples":[{"en":"The mentor helps with the process of acquiring new knowledge.","zh":"導師幫助學習者完成獲取新知識的過程。"},{"en":"The process of acquiring new knowledge is the gradual act of learning, testing and understanding new information.","zh":"process of acquiring new knowledge 是逐步學習、測試和理解新資訊的過程。"},{"en":"A student acquires new knowledge by reading, asking questions and correcting mistakes.","zh":"學生透過閱讀、提問和改正錯誤來獲取新知識。"},{"en":"This process takes time because facts must become usable understanding.","zh":"這個過程需要時間，因為事實必須變成可使用的理解。"},{"en":"The phrase describes learning as development, not simple storage.","zh":"這個短語把學習描述為發展，而不是簡單儲存。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":3},{"front":"fairly simple example","meaning":"相當簡單的例子","examples":[{"en":"A fairly simple example is someone learning to play chess.","zh":"一個相當簡單的例子是某人學習下國際象棋。"},{"en":"A fairly simple example is an example that is easy enough to understand but still useful.","zh":"fairly simple example 是容易理解但仍有用的例子。"},{"en":"A teacher may use shopping as a fairly simple example to explain supply and demand.","zh":"老師可能用購物作為相當簡單的例子來解釋供求。"},{"en":"Simple examples help beginners grasp an idea before facing complex cases.","zh":"簡單例子幫助初學者在面對複雜個案前掌握概念。"},{"en":"The phrase introduces a clear example without making the topic too difficult.","zh":"這個短語引出清楚例子，而不令題目太難。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":3},{"front":"chess player","meaning":"國際象棋棋手","examples":[{"en":"The novice chess player seeks a mentor.","zh":"初學國際象棋棋手尋求導師。"},{"en":"A chess player is someone who plays the board game chess.","zh":"chess player 是下國際象棋這種棋盤遊戲的人。"},{"en":"A beginner chess player must learn how each piece moves before planning attacks.","zh":"初學棋手在計劃攻擊前，必須學會每隻棋如何移動。"},{"en":"Strong chess players recognise patterns after seeing many games.","zh":"強棋手在看過許多棋局後會辨認模式。"},{"en":"The phrase can refer to anyone from a beginner to a professional competitor.","zh":"這個短語可以指初學者，也可以指專業參賽者。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":3},{"front":"seek a mentor","meaning":"尋求導師","examples":[{"en":"The novice chess player seeks a mentor to teach her the game.","zh":"初學國際象棋棋手尋求導師教她這個遊戲。"},{"en":"To seek a mentor means to look for an experienced person who can guide learning.","zh":"seek a mentor 指尋找能指導學習的有經驗人士。"},{"en":"A young designer may seek a mentor to review her portfolio and give honest advice.","zh":"年輕設計師可能尋求導師審視作品集並給誠實建議。"},{"en":"Seeking a mentor can prevent beginners from repeating avoidable mistakes.","zh":"尋求導師可以防止初學者重複可避免的錯誤。"},{"en":"The phrase suggests active effort to find guidance.","zh":"這個短語暗示主動尋找指導。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":3},{"front":"object of the game","meaning":"遊戲目標","examples":[{"en":"The mentor teaches the object of the game.","zh":"導師教授遊戲目標。"},{"en":"The object of the game is the main aim or goal players try to achieve.","zh":"object of the game 是玩家嘗試達成的主要目標。"},{"en":"In chess, the object of the game is to put the opponent’s king in checkmate.","zh":"在國際象棋中，遊戲目標是將死對方的王。"},{"en":"Knowing the object helps beginners understand why each move matters.","zh":"知道目標幫助初學者理解每一步為何重要。"},{"en":"The phrase explains what winning means in a game.","zh":"這個短語解釋遊戲中勝利的意思。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":3},{"front":"the names of the pieces","meaning":"棋子的名稱","examples":[{"en":"The novice learns the names of the pieces.","zh":"初學者學習棋子的名稱。"},{"en":"The names of the pieces are the labels used for each chess unit, such as king, queen and knight.","zh":"the names of the pieces 是每隻國際象棋棋子的名稱，例如王、后和馬。"},{"en":"A child learning chess first learns the names of the pieces before using them in a game.","zh":"學下棋的孩子先學棋子的名稱，然後才在棋局中使用它們。"},{"en":"Naming the pieces correctly helps players follow instructions and discuss moves.","zh":"正確說出棋子名稱幫助玩家跟隨指示和討論走法。"},{"en":"The phrase refers to basic vocabulary needed before deeper strategy.","zh":"這個短語指深入策略前所需的基本詞彙。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":4},{"front":"function of each piece","meaning":"每隻棋子的功能","examples":[{"en":"The mentor explains the function of each piece.","zh":"導師解釋每隻棋子的功能。"},{"en":"The function of each piece is what each chess piece can do and how it moves.","zh":"function of each piece 是每隻棋能做甚麼以及如何移動。"},{"en":"A beginner must learn that a bishop moves diagonally and a rook moves in straight lines.","zh":"初學者必須學會象斜線移動，而車直線移動。"},{"en":"Understanding function prevents players from using pieces illegally or weakly.","zh":"理解功能可以防止玩家非法或薄弱地使用棋子。"},{"en":"The phrase describes purpose and use, not only names.","zh":"這個短語描述目的和用途，而不只是名稱。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":4},{"front":"necessary conditions for","meaning":"……的必要條件","examples":[{"en":"The player learns the necessary conditions for winning or losing.","zh":"玩家學習贏或輸的必要條件。"},{"en":"Necessary conditions for something are the requirements that must exist for it to happen.","zh":"necessary conditions for 某事，是該事發生必須存在的要求。"},{"en":"A student learns the necessary conditions for passing an exam, such as answering enough questions correctly.","zh":"學生會學習通過考試的必要條件，例如答對足夠題目。"},{"en":"Knowing these conditions helps learners focus on what truly matters.","zh":"知道這些條件幫助學習者集中於真正重要的事情。"},{"en":"The phrase refers to required factors, not optional extras.","zh":"這個短語指必要因素，而不是額外選項。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":4},{"front":"winning or losing the game","meaning":"贏或輸掉比賽","examples":[{"en":"The novice learns the conditions for winning or losing the game.","zh":"初學者學習贏或輸掉比賽的條件。"},{"en":"Winning or losing the game means reaching a result where one player succeeds and the other fails.","zh":"winning or losing the game 指達到一方成功、另一方失敗的結果。"},{"en":"In chess, a player may lose the game by being checkmated or running out of time.","zh":"在國際象棋中，玩家可能因被將死或時間用完而輸掉比賽。"},{"en":"Understanding victory and defeat helps beginners judge whether a move is useful.","zh":"理解勝敗幫助初學者判斷一步棋是否有用。"},{"en":"The phrase describes the final result of competition.","zh":"這個短語描述競爭的最終結果。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":4},{"front":"in time","meaning":"隨着時間","examples":[{"en":"In time, the novice begins to recognise patterns.","zh":"隨着時間，初學者開始辨認模式。"},{"en":"In time means after a period has passed, usually gradually.","zh":"in time 指一段時間過去後，通常是逐漸地。"},{"en":"In time, a shy student may become comfortable speaking in class.","zh":"隨着時間，害羞學生可能變得習慣在課堂發言。"},{"en":"Some abilities cannot be rushed because they develop through repeated experience.","zh":"有些能力不能催促，因為它們透過反覆經驗發展。"},{"en":"The phrase suggests gradual change rather than immediate success.","zh":"這個短語暗示逐步改變，而不是即時成功。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":4},{"front":"with much practice","meaning":"經過大量練習","examples":[{"en":"With much practice, the novice becomes a journeyman.","zh":"經過大量練習，初學者變成熟練學習者。"},{"en":"With much practice means after repeated effort and training over time.","zh":"with much practice 指經過長時間反覆努力和訓練。"},{"en":"A swimmer improves with much practice, especially when a coach corrects technique.","zh":"游泳者經過大量練習會進步，尤其當教練糾正技巧時。"},{"en":"Practice turns rules into habits and helps learners react more quickly.","zh":"練習把規則變成習慣，幫助學習者反應更快。"},{"en":"The phrase shows that progress depends on repeated action.","zh":"這個短語顯示進步取決於反覆行動。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":4},{"front":"recognise patterns of behaviour","meaning":"辨認行為模式","examples":[{"en":"The novice begins to recognise patterns of behaviour within cases.","zh":"初學者開始在個案之內辨認行為模式。"},{"en":"To recognise patterns of behaviour means to notice repeated ways that people or things act.","zh":"recognise patterns of behaviour 指注意到人或事物反覆出現的行動方式。"},{"en":"A teacher may recognise patterns of behaviour in students who become quiet before tests.","zh":"老師可能辨認到學生考試前變得沉默的行為模式。"},{"en":"Recognising patterns helps people predict what may happen next.","zh":"辨認模式幫助人預測接下來可能發生甚麼。"},{"en":"The phrase describes seeing repeated behaviour, not just one isolated action.","zh":"這個短語描述看見重複行為，而不是單一孤立行動。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":4},{"front":"within cases","meaning":"在個案之內","examples":[{"en":"The learner first finds patterns within cases.","zh":"學習者首先在個案之內找到模式。"},{"en":"Within cases means inside individual examples or situations.","zh":"within cases 指在個別例子或情況之內。"},{"en":"A doctor may notice patterns within a patient’s history before comparing it with other patients.","zh":"醫生可能先注意病人病歷中的模式，再與其他病人比較。"},{"en":"Looking within one case helps learners understand its internal details.","zh":"觀察單一個案之內的內容，幫助學習者理解其內部細節。"},{"en":"The phrase contrasts patterns inside one case with patterns across many cases.","zh":"這個短語把單一個案內的模式與多個個案之間的模式作對比。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":4},{"front":"journeyman","meaning":"熟練學習者；中級學徒","examples":[{"en":"With practice, the novice becomes a journeyman.","zh":"經過練習，初學者變成熟練學習者。"},{"en":"A journeyman is a learner who is no longer a beginner but not yet an expert.","zh":"journeyman 是不再是初學者但尚未成為專家的人。"},{"en":"A journeyman cook can follow recipes well and handle common kitchen problems.","zh":"中級廚師能很好地跟隨食譜並處理常見廚房問題。"},{"en":"Journeymen still need guidance when cases become complex or unusual.","zh":"熟練學習者在個案變得複雜或不尋常時仍需要指導。"},{"en":"The word describes an intermediate stage of skilled learning.","zh":"這個字描述技能學習的中間階段。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":4},{"front":"increasingly complex cases","meaning":"越來越複雜的個案","examples":[{"en":"The journeyman is exposed to increasingly complex cases.","zh":"熟練學習者接觸越來越複雜的個案。"},{"en":"Increasingly complex cases are examples or problems that become more difficult over time.","zh":"increasingly complex cases 是隨時間變得更困難的例子或問題。"},{"en":"A trainee nurse may first handle simple cases and later face increasingly complex cases.","zh":"見習護士可能先處理簡單個案，之後面對越來越複雜的個案。"},{"en":"More complex cases push learners to connect several rules at once.","zh":"較複雜個案推動學習者同時連繫幾條規則。"},{"en":"The phrase shows gradual movement from easy practice to harder judgement.","zh":"這個短語顯示由容易練習逐步走向更困難判斷。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":4},{"front":"not only…but also…","meaning":"不但……而且……","examples":[{"en":"The journeyman finds patterns not only within cases but also between cases.","zh":"熟練學習者不但在個案之內，也在不同個案之間找到模式。"},{"en":"Not only…but also… connects two points and shows that both are true.","zh":"not only…but also… 連接兩點，並顯示兩者都是真的。"},{"en":"Good reading practice improves not only vocabulary but also confidence.","zh":"良好閱讀練習不但改善詞彙，而且提升信心。"},{"en":"This structure helps writers add a second important idea clearly.","zh":"這個結構幫助寫作者清楚加入第二個重要想法。"},{"en":"The phrase is useful when the second point extends the first.","zh":"當第二點延伸第一點時，這個短語很有用。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":5},{"front":"between cases","meaning":"在不同個案之間","examples":[{"en":"The journeyman recognises patterns between cases.","zh":"熟練學習者在不同個案之間辨認模式。"},{"en":"Between cases means across different examples, situations or problems.","zh":"between cases 指橫跨不同例子、情況或問題。"},{"en":"A doctor recognises links between cases when several patients show similar symptoms.","zh":"當幾名病人出現相似症狀時，醫生會在不同個案之間辨認聯繫。"},{"en":"Seeing patterns between cases helps learners move beyond single examples.","zh":"看見不同個案之間的模式幫助學習者超越單一例子。"},{"en":"The phrase describes comparison across cases, not analysis of one case only.","zh":"這個短語描述跨個案比較，而不只是分析一個個案。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":5},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, the journeyman learns that patterns repeat over time.","zh":"更重要的是，熟練學習者學會模式會隨時間重複出現。"},{"en":"More importantly introduces a point that matters more than the previous one.","zh":"more importantly 引出比前一點更重要的觀點。"},{"en":"A school may have new computers; more importantly, teachers know how to use them well.","zh":"學校可能有新電腦；更重要的是，老師知道如何好好使用它們。"},{"en":"This phrase helps writers signal that the next idea deserves special attention.","zh":"這個短語幫助寫作者表示下一個想法值得特別注意。"},{"en":"It is used to rank ideas by importance.","zh":"它用來按重要性排列想法。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":5},{"front":"repeat themselves over time","meaning":"隨時間重複出現","examples":[{"en":"The patterns often repeat themselves over time.","zh":"這些模式常隨時間重複出現。"},{"en":"To repeat themselves over time means to appear again and again across different moments.","zh":"repeat themselves over time 指在不同時間一次又一次出現。"},{"en":"A teacher may notice that the same grammar mistakes repeat themselves over time.","zh":"老師可能注意到相同文法錯誤隨時間重複出現。"},{"en":"Repeated patterns help experts make better predictions.","zh":"重複模式幫助專家作出更好預測。"},{"en":"The phrase describes recurrence, not a one-time event.","zh":"這個短語描述反覆出現，而不是一次性事件。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":5},{"front":"maintain regular contact with","meaning":"與……保持定期聯繫","examples":[{"en":"The journeyman still maintains regular contact with a mentor.","zh":"熟練學習者仍與導師保持定期聯繫。"},{"en":"To maintain regular contact with someone means to keep communicating with that person often.","zh":"maintain regular contact with 某人，指經常與該人保持溝通。"},{"en":"A new employee may maintain regular contact with a manager during the first month.","zh":"新員工在第一個月可能與經理保持定期聯繫。"},{"en":"Regular contact allows problems to be solved before they become serious.","zh":"定期聯繫讓問題在變嚴重前得到解決。"},{"en":"The phrase suggests ongoing support, not a single meeting.","zh":"這個短語暗示持續支援，而不是一次會面。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":5},{"front":"solve specific problems","meaning":"解決具體問題","examples":[{"en":"The mentor helps the journeyman solve specific problems.","zh":"導師幫助熟練學習者解決具體問題。"},{"en":"To solve specific problems means to deal with particular difficulties rather than general issues.","zh":"solve specific problems 指處理特定困難，而不是一般問題。"},{"en":"A maths tutor helps a student solve specific problems she keeps getting wrong.","zh":"數學導師幫助學生解決她一直做錯的具體題目。"},{"en":"Specific problem-solving builds confidence because the learner sees clear progress.","zh":"具體解難建立信心，因為學習者看見清楚進步。"},{"en":"The phrase focuses on practical answers to real cases.","zh":"這個短語重點在真實個案的實際答案。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":5},{"front":"complex strategies","meaning":"複雜策略","examples":[{"en":"The journeyman learns more complex strategies.","zh":"熟練學習者學習更複雜的策略。"},{"en":"Complex strategies are planned methods involving several steps, choices or possible outcomes.","zh":"complex strategies 是涉及多個步驟、選擇或可能結果的計劃方法。"},{"en":"A chess player learns complex strategies when simple attacks are no longer enough.","zh":"當簡單攻擊不再足夠，棋手會學習複雜策略。"},{"en":"Complex strategies require understanding patterns and predicting reactions.","zh":"複雜策略需要理解模式並預測反應。"},{"en":"The phrase describes advanced planning, not a single simple action.","zh":"這個短語描述進階計劃，而不是單一簡單行動。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":5},{"front":"opening moves","meaning":"開局走法","examples":[{"en":"The chess player begins to learn patterns of opening moves.","zh":"棋手開始學習開局走法的模式。"},{"en":"Opening moves are the first moves made at the beginning of a chess game.","zh":"opening moves 是國際象棋開局時所下的最初幾步。"},{"en":"A beginner may memorise opening moves to avoid losing control early.","zh":"初學者可能記住開局走法，以避免一開始失去控制。"},{"en":"Strong opening moves can create space and protect important pieces.","zh":"強開局可以創造空間並保護重要棋子。"},{"en":"The phrase refers to early actions that shape what happens later.","zh":"這個短語指塑造之後發展的早期行動。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":5},{"front":"offensive and defensive game-playing","meaning":"進攻和防守玩法","examples":[{"en":"The player learns offensive and defensive game-playing.","zh":"玩家學習進攻和防守玩法。"},{"en":"Offensive and defensive game-playing means learning how to attack and how to protect oneself during a game.","zh":"offensive and defensive game-playing 指學習如何進攻以及如何在遊戲中保護自己。"},{"en":"A football team needs both offensive and defensive play to score goals and stop opponents.","zh":"足球隊需要進攻和防守玩法，既要入球，也要阻止對手。"},{"en":"In chess, attack without defence can leave the king exposed.","zh":"在國際象棋中，只進攻而不防守會令王暴露。"},{"en":"The phrase shows that good play requires balance.","zh":"這個短語顯示良好玩法需要平衡。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":5},{"front":"patterns of victory and defeat","meaning":"勝敗模式","examples":[{"en":"The player learns patterns of victory and defeat.","zh":"玩家學習勝敗模式。"},{"en":"Patterns of victory and defeat are repeated ways in which players win or lose.","zh":"patterns of victory and defeat 是玩家贏或輸時反覆出現的方式。"},{"en":"A coach studies patterns of victory and defeat after watching several matches.","zh":"教練觀看幾場比賽後，會研究勝敗模式。"},{"en":"Recognising these patterns helps players avoid old mistakes and repeat successful choices.","zh":"辨認這些模式幫助玩家避免舊錯誤並重複成功選擇。"},{"en":"The phrase connects past results with future improvement.","zh":"這個短語把過去結果與未來改善連繫起來。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":5},{"front":"make and test hypotheses","meaning":"提出並測試假設","examples":[{"en":"The journeyman starts to make and test hypotheses about future behaviour.","zh":"熟練學習者開始對未來行為提出並測試假設。"},{"en":"To make and test hypotheses means to form possible explanations and check whether they are correct.","zh":"make and test hypotheses 指形成可能解釋，並檢查它們是否正確。"},{"en":"A science student may predict that plants grow faster in sunlight and then test the idea.","zh":"科學學生可能預測植物在陽光下長得更快，然後測試這個想法。"},{"en":"Testing hypotheses helps learners move from guessing to evidence-based thinking.","zh":"測試假設幫助學習者由猜測走向有證據的思考。"},{"en":"The phrase describes active investigation.","zh":"這個短語描述主動調查。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":6},{"front":"future behaviour","meaning":"未來行為","examples":[{"en":"The learner makes hypotheses about future behaviour.","zh":"學習者對未來行為提出假設。"},{"en":"Future behaviour means how a person, system or situation may act later.","zh":"future behaviour 指一個人、系統或情況之後可能如何行動。"},{"en":"A teacher may predict future behaviour when a student always studies hard before tests.","zh":"當學生每次測驗前都努力溫習，老師可能預測其未來行為。"},{"en":"Past patterns can help people guess future behaviour, but predictions may still be wrong.","zh":"過去模式可以幫助人猜測未來行為，但預測仍可能錯。"},{"en":"The phrase focuses on what may happen next.","zh":"這個短語重點在接下來可能發生甚麼。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":6},{"front":"based on past experiences","meaning":"基於過往經驗","examples":[{"en":"The hypotheses are based on past experiences.","zh":"這些假設基於過往經驗。"},{"en":"Based on past experiences means using earlier events as evidence for a present judgement.","zh":"based on past experiences 指使用早前事件作為當前判斷的證據。"},{"en":"A driver slows down on a wet road based on past experiences with slippery surfaces.","zh":"司機基於過往濕滑路面的經驗，在濕路上減速。"},{"en":"Past experience can guide decisions, but new situations may still surprise people.","zh":"過往經驗可以指導決定，但新情況仍可能令人意外。"},{"en":"The phrase links memory with prediction.","zh":"這個短語把記憶與預測連繫起來。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":6},{"front":"begin the next transition","meaning":"開始下一個轉變","examples":[{"en":"The journeyman begins the next transition toward expertise.","zh":"熟練學習者開始邁向專業的下一個轉變。"},{"en":"To begin the next transition means to start moving into a new stage of development.","zh":"begin the next transition 指開始進入新的發展階段。"},{"en":"A student begins the next transition when she stops copying examples and starts creating her own arguments.","zh":"當學生不再抄例子，而開始創造自己的論點，她就開始下一個轉變。"},{"en":"Transitions often happen gradually after enough practice and feedback.","zh":"轉變通常在足夠練習和回饋後逐漸發生。"},{"en":"The phrase describes the start of a new learning phase.","zh":"這個短語描述新學習階段的開始。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":6},{"front":"creatively generate knowledge","meaning":"創造性地產生知識","examples":[{"en":"An expert creatively generates knowledge.","zh":"專家創造性地產生知識。"},{"en":"To creatively generate knowledge means to produce new understanding through original thinking.","zh":"creatively generate knowledge 指透過原創思考產生新理解。"},{"en":"A researcher creatively generates knowledge when she designs a new way to test an old question.","zh":"研究人員設計新方法測試舊問題時，就是創造性地產生知識。"},{"en":"Creativity helps experts go beyond repeating what others already know.","zh":"創意幫助專家超越重複他人已知的內容。"},{"en":"The phrase describes original contribution, not routine learning.","zh":"這個短語描述原創貢獻，而不是例行學習。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":6},{"front":"rather than simply","meaning":"而不是只是……","examples":[{"en":"The expert generates knowledge rather than simply matching patterns.","zh":"專家產生知識，而不是只是配對模式。"},{"en":"Rather than simply means instead of only doing the basic or obvious action.","zh":"rather than simply 指不只是做基本或明顯行動，而是做另一件事。"},{"en":"A good tutor explains why an answer works rather than simply giving the answer.","zh":"好導師會解釋答案為何有效，而不是只是給答案。"},{"en":"This phrase contrasts deeper work with a shallow action.","zh":"這個短語把更深層工作與表面行動作對比。"},{"en":"It helps show that the second action is not enough by itself.","zh":"它幫助顯示第二個行動本身並不足夠。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":6},{"front":"matching superficial patterns","meaning":"配對表面模式","examples":[{"en":"A novice may simply match superficial patterns.","zh":"初學者可能只是配對表面模式。"},{"en":"Matching superficial patterns means noticing surface similarities without understanding deeper reasons.","zh":"matching superficial patterns 指注意表面相似，而不理解更深原因。"},{"en":"A student may copy sentence structures without understanding the grammar behind them.","zh":"學生可能抄句式，卻不理解背後文法。"},{"en":"Superficial matching can produce correct answers sometimes, but it fails with new problems.","zh":"表面配對有時可以產生正確答案，但面對新問題會失效。"},{"en":"The phrase warns against learning only by surface appearance.","zh":"這個短語提醒人不要只按表面外觀學習。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":6},{"front":"superficial patterns","meaning":"表面模式","examples":[{"en":"Experts go beyond superficial patterns.","zh":"專家超越表面模式。"},{"en":"Superficial patterns are surface-level similarities that may not show real meaning.","zh":"superficial patterns 是表層相似之處，未必顯示真正意思。"},{"en":"A beginner may think two essays are similar because both use the same first sentence.","zh":"初學者可能因兩篇文章用同一句開頭，就以為它們相似。"},{"en":"Experts look beneath superficial patterns to find deeper structure and purpose.","zh":"專家會看穿表面模式，尋找更深結構和目的。"},{"en":"The phrase describes appearance-level patterns, not true understanding.","zh":"這個短語描述外觀層面的模式，而不是真正理解。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":6},{"front":"at this point","meaning":"到這個階段","examples":[{"en":"At this point, the learner becomes confident in her knowledge.","zh":"到這個階段，學習者對自己的知識變得有信心。"},{"en":"At this point means at this stage in a process or argument.","zh":"at this point 指在過程或論述中的這個階段。"},{"en":"At this point in the lesson, students should know the basic rule and start practising.","zh":"到課堂這個階段，學生應已知道基本規則並開始練習。"},{"en":"The phrase helps readers follow the order of development.","zh":"這個短語幫助讀者跟隨發展次序。"},{"en":"It usually refers back to what has already happened.","zh":"它通常指回已經發生的事情。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":6},{"front":"be confident in","meaning":"對……有信心","examples":[{"en":"The expert is confident in her knowledge.","zh":"專家對自己的知識有信心。"},{"en":"To be confident in something means to trust one’s ability or understanding in that area.","zh":"be confident in 某事，指相信自己在該方面的能力或理解。"},{"en":"A student becomes confident in speaking after answering many questions successfully.","zh":"學生成功回答許多問題後，會對口語有信心。"},{"en":"Confidence grows when experience repeatedly confirms that judgement is reliable.","zh":"當經驗反覆確認判斷可靠，信心就會增長。"},{"en":"The phrase describes trust based on ability, not blind arrogance.","zh":"這個短語描述基於能力的信任，而不是盲目自大。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":6},{"front":"no longer needs","meaning":"不再需要","examples":[{"en":"The expert no longer needs a mentor as a guide.","zh":"專家不再需要導師作為引導者。"},{"en":"No longer needs means used to need something before but does not need it now.","zh":"no longer needs 指以前需要某物，但現在不需要。"},{"en":"A child may no longer need help tying shoes after practising every morning.","zh":"孩子每天早上練習後，可能不再需要別人幫忙綁鞋帶。"},{"en":"When learners gain independence, they may still ask advice but do not depend on constant guidance.","zh":"當學習者獲得獨立性，他們仍可能尋求建議，但不再依賴持續指導。"},{"en":"The phrase marks a change from dependence to independence.","zh":"這個短語標示由依賴轉向獨立的變化。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":7},{"front":"become responsible for","meaning":"對……負責","examples":[{"en":"The expert becomes responsible for her own knowledge.","zh":"專家變得對自己的知識負責。"},{"en":"To become responsible for something means to take charge of it and accept the consequences.","zh":"become responsible for 某事，指掌管它並接受後果。"},{"en":"A senior nurse becomes responsible for checking that junior staff follow safety rules.","zh":"高級護士要負責檢查初級員工是否遵守安全規則。"},{"en":"Experts must judge when their knowledge is enough and when more evidence is needed.","zh":"專家必須判斷自己的知識何時足夠，以及何時需要更多證據。"},{"en":"The phrase shows ownership and accountability.","zh":"這個短語顯示擁有權和責任承擔。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":7},{"front":"competing against experts","meaning":"與專家比賽","examples":[{"en":"The chess player begins competing against experts.","zh":"棋手開始與專家比賽。"},{"en":"Competing against experts means playing or working against people with advanced skill.","zh":"competing against experts 指與具有高階技能的人比賽或較量。"},{"en":"A young debater may improve quickly after competing against experienced speakers.","zh":"年輕辯論員與有經驗的演講者比賽後，可能快速進步。"},{"en":"Competition with experts exposes weaknesses that easy practice may hide.","zh":"與專家比賽會暴露簡單練習可能掩蓋的弱點。"},{"en":"The phrase describes a challenging test of ability.","zh":"這個短語描述對能力的高難度測試。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":7},{"front":"make predictions based on","meaning":"根據……作出預測","examples":[{"en":"The player makes predictions based on patterns.","zh":"玩家根據模式作出預測。"},{"en":"To make predictions based on something means to use evidence or patterns to guess what may happen next.","zh":"make predictions based on 某事，指用證據或模式猜測接下來可能發生甚麼。"},{"en":"A teacher predicts exam performance based on homework habits and practice results.","zh":"老師根據功課習慣和練習結果預測考試表現。"},{"en":"Predictions are stronger when they are based on repeated evidence, not one event.","zh":"當預測基於重複證據，而不是單一事件時，它會更有力。"},{"en":"The phrase connects forecasting with a source of evidence.","zh":"這個短語把預測與證據來源連繫起來。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":7},{"front":"test predictions against","meaning":"將預測與……對照測試","examples":[{"en":"The player tests those predictions against actual behaviour.","zh":"玩家將那些預測與實際行為對照測試。"},{"en":"To test predictions against something means to compare guesses with real results.","zh":"test predictions against 某事，指把猜測與真實結果比較。"},{"en":"A weather app tests predictions against the temperature that actually happens.","zh":"天氣應用程式會將預測與實際出現的氣溫對照測試。"},{"en":"Comparing predictions with reality helps people improve future judgement.","zh":"把預測與現實比較，有助人們改善未來判斷。"},{"en":"The phrase describes checking ideas against evidence.","zh":"這個短語描述用證據檢查想法。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":7},{"front":"actual behaviour","meaning":"實際行為","examples":[{"en":"The player compares predictions with actual behaviour.","zh":"玩家把預測與實際行為比較。"},{"en":"Actual behaviour is what people or things really do, not what someone expected.","zh":"actual behaviour 是人或事物真正做的事情，而不是某人預期的事情。"},{"en":"A teacher may compare a student’s promised study plan with actual behaviour during the week.","zh":"老師可能把學生承諾的溫習計劃與一星期中的實際行為比較。"},{"en":"If actual behaviour differs from predictions, the model or assumption may need correction.","zh":"如果實際行為與預測不同，模型或假設可能需要修正。"},{"en":"The phrase contrasts reality with expectation.","zh":"這個短語把現實與期望作對比。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":7},{"front":"deeper understanding of","meaning":"對……更深入的理解","examples":[{"en":"The expert develops a deeper understanding of the game.","zh":"專家對遊戲形成更深入的理解。"},{"en":"A deeper understanding of something means knowing not only facts but also causes, patterns and meaning.","zh":"deeper understanding of 某事，指不只知道事實，還理解原因、模式和意義。"},{"en":"A student gains a deeper understanding of history when she connects events with people’s lives.","zh":"學生把事件與人的生活連繫起來時，會對歷史有更深入理解。"},{"en":"Deeper understanding helps people adapt when familiar examples change.","zh":"更深入理解幫助人在熟悉例子改變時作出調整。"},{"en":"The phrase describes insight beyond surface memory.","zh":"這個短語描述超越表面記憶的洞察。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":7},{"front":"create her own case","meaning":"創造自己的個案","examples":[{"en":"The expert creates her own case.","zh":"專家創造自己的個案。"},{"en":"To create her own case means to produce a new example, problem or situation instead of only studying existing ones.","zh":"create her own case 指創造新的例子、問題或情況，而不只是研究現有個案。"},{"en":"An advanced law student may create her own case scenario to test a legal principle.","zh":"高階法律學生可能創造自己的案例情境來測試法律原則。"},{"en":"Creating a case shows that the learner can use knowledge independently.","zh":"創造個案顯示學習者能獨立運用知識。"},{"en":"The phrase marks a move from receiving examples to producing them.","zh":"這個短語標示由接收例子轉向創造例子。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":7},{"front":"rather than relying on","meaning":"而不是依賴……","examples":[{"en":"The expert creates her own case rather than relying on others.","zh":"專家創造自己的個案，而不是依賴他人。"},{"en":"Rather than relying on means instead of depending on someone or something.","zh":"rather than relying on 指不依靠某人或某物，而是做另一件事。"},{"en":"A confident writer builds her own argument rather than relying on memorised essays.","zh":"有信心的寫作者會建立自己的論點，而不是依賴背誦文章。"},{"en":"This phrase contrasts independence with dependence.","zh":"這個短語把獨立與依賴作對比。"},{"en":"It shows that the second action is being replaced by a stronger one.","zh":"它顯示第二個行動被更強的行動取代。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":7},{"front":"cases of others","meaning":"他人的個案","examples":[{"en":"The expert no longer relies only on the cases of others.","zh":"專家不再只依賴他人的個案。"},{"en":"Cases of others are examples, experiences or problems created or encountered by other people.","zh":"cases of others 是由其他人創造或遇到的例子、經驗或問題。"},{"en":"A trainee doctor first learns from cases of others before handling patients independently.","zh":"見習醫生在獨立處理病人前，先從他人的個案中學習。"},{"en":"Relying only on others’ cases can limit original thinking.","zh":"只依賴他人的個案可能限制原創思考。"},{"en":"The phrase contrasts borrowed experience with one’s own experience.","zh":"這個短語把借來的經驗與自己的經驗作對比。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":7},{"front":"the power of expertise","meaning":"專業知識的力量","examples":[{"en":"The passage then explains the power of expertise.","zh":"文章接着解釋專業知識的力量。"},{"en":"The power of expertise means the special advantages that deep knowledge and skill provide.","zh":"the power of expertise 指深厚知識和技能所帶來的特殊優勢。"},{"en":"A mechanic’s expertise helps him find an engine problem faster than a beginner can.","zh":"機械師的專業知識幫助他比初學者更快找出引擎問題。"},{"en":"Expertise gives people stronger memory, better judgement and clearer attention in their field.","zh":"專業知識讓人在其領域中有更強記憶、更好判斷和更清楚注意力。"},{"en":"The phrase focuses on what expertise allows someone to do.","zh":"這個短語重點在專業能讓人做到甚麼。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":8},{"front":"perceive meaningful patterns","meaning":"察覺有意義的模式","examples":[{"en":"An expert perceives meaningful patterns better than non-experts.","zh":"專家比非專家更能察覺有意義的模式。"},{"en":"To perceive meaningful patterns means to notice important repeated structures or relationships.","zh":"perceive meaningful patterns 指注意到重要的重複結構或關係。"},{"en":"A doctor may perceive a meaningful pattern in symptoms that seem unrelated to a patient.","zh":"醫生可能在病人覺得無關的症狀中察覺有意義的模式。"},{"en":"Seeing meaningful patterns helps experts choose the right action faster.","zh":"看見有意義的模式幫助專家更快選擇正確行動。"},{"en":"The phrase describes understanding significance, not just seeing repetition.","zh":"這個短語描述理解重要性，而不只是看見重複。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":8},{"front":"in her domain","meaning":"在其專門領域中","examples":[{"en":"An expert works within her domain.","zh":"專家在其專門領域中工作。"},{"en":"In her domain means inside the expert’s own area of knowledge or skill.","zh":"in her domain 指在專家自己的知識或技能範疇之內。"},{"en":"A chef may be an expert in her domain but still need help with computer repairs.","zh":"廚師可能在自己的領域中是專家，但仍需要別人幫忙修電腦。"},{"en":"Experts perform best when a problem belongs to the domain they know well.","zh":"當問題屬於專家熟悉的領域時，專家表現最好。"},{"en":"The phrase limits expertise to a particular field.","zh":"這個短語把專業能力限制在特定領域。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":8},{"front":"non-experts","meaning":"非專家","examples":[{"en":"Experts perceive patterns better than non-experts.","zh":"專家比非專家更能察覺模式。"},{"en":"Non-experts are people who do not have deep knowledge or skill in a particular field.","zh":"non-experts 是在某特定領域沒有深厚知識或技能的人。"},{"en":"A non-expert may see only random lines on a medical scan.","zh":"非專家可能在醫學掃描圖上只看見隨機線條。"},{"en":"Non-experts often need clearer explanations because they lack background knowledge.","zh":"非專家通常需要更清楚解釋，因為他們缺乏背景知識。"},{"en":"The word identifies people outside the specialist group.","zh":"這個字指出專門群體以外的人。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":8},{"front":"random or disconnected data points","meaning":"隨機或互不相連的數據點","examples":[{"en":"A novice may perceive random or disconnected data points.","zh":"初學者可能察覺到隨機或互不相連的數據點。"},{"en":"Random or disconnected data points are pieces of information that seem unrelated or without pattern.","zh":"random or disconnected data points 是看似無關或沒有模式的資訊片段。"},{"en":"A beginner looking at sales numbers may see only separate figures, not a trend.","zh":"初學者看銷售數字時，可能只看見分散數字，而不是趨勢。"},{"en":"Without organised knowledge, useful patterns can look like unrelated facts.","zh":"沒有組織好的知識，有用模式可能看似互不相關的事實。"},{"en":"The phrase describes information that has not yet been connected meaningfully.","zh":"這個短語描述尚未被有意義地連接的資訊。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":8},{"front":"connect regular patterns","meaning":"連繫規律模式","examples":[{"en":"An expert connects regular patterns within and between cases.","zh":"專家連繫個案之內和個案之間的規律模式。"},{"en":"To connect regular patterns means to link repeated features across examples.","zh":"connect regular patterns 指把不同例子中的重複特徵連起來。"},{"en":"A teacher connects patterns when she notices the same grammar problem in several essays.","zh":"老師在幾篇作文中注意到同一文法問題時，就是在連繫模式。"},{"en":"Connecting patterns helps experts explain causes rather than only describe events.","zh":"連繫模式幫助專家解釋原因，而不只是描述事件。"},{"en":"The phrase shows active organisation of information.","zh":"這個短語顯示主動組織資訊。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":8},{"front":"identify patterns","meaning":"辨認模式","examples":[{"en":"The ability to identify patterns develops through experience.","zh":"辨認模式的能力透過經驗發展。"},{"en":"To identify patterns means to notice repeated forms, behaviours or relationships.","zh":"identify patterns 指注意到重複的形式、行為或關係。"},{"en":"A nurse may identify patterns in a patient’s pain after recording symptoms for several days.","zh":"護士記錄病人幾天症狀後，可能辨認出疼痛模式。"},{"en":"Pattern identification helps people make better decisions with less guesswork.","zh":"辨認模式幫助人以較少猜測作出更好決定。"},{"en":"The phrase describes recognising structure in information.","zh":"這個短語描述在資訊中辨認結構。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":8},{"front":"innate perceptual skill","meaning":"天生感知能力","examples":[{"en":"This ability is not an innate perceptual skill.","zh":"這種能力不是天生感知能力。"},{"en":"An innate perceptual skill is a natural ability to notice things without training.","zh":"innate perceptual skill 是不經訓練也能注意事物的天生能力。"},{"en":"A child may seem naturally observant, but expert perception usually needs practice.","zh":"孩子可能看似天生觀察力強，但專家式感知通常需要練習。"},{"en":"If pattern recognition is not innate, learners can improve it through exposure and feedback.","zh":"如果模式辨認不是天生的，學習者可以透過接觸和回饋改善它。"},{"en":"The phrase contrasts natural ability with learned ability.","zh":"這個短語把天生能力與習得能力作對比。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":8},{"front":"rather it reflects","meaning":"而是反映","examples":[{"en":"Rather, it reflects the organisation of knowledge.","zh":"相反，它反映知識的組織方式。"},{"en":"Rather it reflects means instead, it shows or is caused by something else.","zh":"rather it reflects 指相反地，它顯示或源自另一件事。"},{"en":"A student’s good essay may not reflect talent alone; rather, it reflects careful planning.","zh":"學生的好文章未必只反映天賦；而是反映仔細計劃。"},{"en":"This phrase corrects a previous idea and gives a better explanation.","zh":"這個短語修正前一個想法，並給出更好解釋。"},{"en":"It is useful when shifting from a wrong cause to a more accurate one.","zh":"當由錯誤原因轉向更準確原因時，它很有用。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":8},{"front":"organisation of knowledge","meaning":"知識的組織方式","examples":[{"en":"Expert pattern recognition reflects the organisation of knowledge.","zh":"專家模式辨認反映知識的組織方式。"},{"en":"Organisation of knowledge means how information is arranged, connected and stored in the mind.","zh":"organisation of knowledge 指資訊在頭腦中如何被安排、連接和儲存。"},{"en":"A student with good organisation of knowledge can link vocabulary, grammar and examples.","zh":"知識組織良好的學生能把詞彙、文法和例子連起來。"},{"en":"Well-organised knowledge helps experts recall relevant information quickly.","zh":"組織良好的知識幫助專家快速回想相關資訊。"},{"en":"The phrase explains why experts see meaning where beginners see separate facts.","zh":"這個短語解釋為何專家在初學者只看見分散事實的地方看見意義。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":8},{"front":"exposure to and experience with","meaning":"接觸並經歷……","examples":[{"en":"Expertise develops after exposure to and experience with many cases.","zh":"專業知識在接觸並經歷許多個案後發展。"},{"en":"Exposure to and experience with something means both seeing it and actively dealing with it.","zh":"exposure to and experience with 某事，指既看見它，也實際處理它。"},{"en":"A trainee teacher gains skill through exposure to and experience with different classroom problems.","zh":"見習老師透過接觸並經歷不同課室問題來提升技能。"},{"en":"Seeing cases is useful, but handling them builds stronger judgement.","zh":"看見個案有用，但處理個案能建立更強判斷。"},{"en":"The phrase combines observation with practical involvement.","zh":"這個短語結合觀察與實際參與。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":9},{"front":"thousands of cases","meaning":"數以千計的個案","examples":[{"en":"Experts learn from thousands of cases.","zh":"專家從數以千計的個案中學習。"},{"en":"Thousands of cases means a very large number of examples or problems.","zh":"thousands of cases 指非常大量的例子或問題。"},{"en":"A radiologist becomes skilled after reviewing thousands of medical images.","zh":"放射科醫生在檢視數以千計的醫學影像後變得熟練。"},{"en":"Large experience helps experts separate rare cases from common ones.","zh":"大量經驗幫助專家分辨罕見個案和常見個案。"},{"en":"The phrase stresses the scale of experience needed for expertise.","zh":"這個短語強調專業能力所需的經驗規模。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":9},{"front":"deeper understanding of their domains","meaning":"對其領域更深入的理解","examples":[{"en":"Experts have a deeper understanding of their domains than novices do.","zh":"專家比初學者對其領域有更深入的理解。"},{"en":"A deeper understanding of their domains means experts know the structure, patterns and limits of their own fields.","zh":"deeper understanding of their domains 指專家了解自己領域的結構、模式和限制。"},{"en":"An experienced teacher understands not only grammar rules but also why students misunderstand them.","zh":"有經驗的老師不只理解文法規則，也理解學生為何誤解它們。"},{"en":"Deeper understanding helps experts choose suitable methods for different cases.","zh":"更深入理解幫助專家為不同個案選擇合適方法。"},{"en":"The phrase compares expert insight with beginner knowledge.","zh":"這個短語比較專家洞察與初學者知識。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":9},{"front":"utilise higher-order principles","meaning":"運用高層次原則","examples":[{"en":"Experts utilise higher-order principles to solve problems.","zh":"專家運用高層次原則來解決問題。"},{"en":"To utilise higher-order principles means to use deeper, more general rules rather than surface features.","zh":"utilise higher-order principles 指使用更深層、更概括的規則，而不是表面特徵。"},{"en":"A maths expert solves a new problem by using underlying logic, not just memorised formulas.","zh":"數學專家透過使用底層邏輯，而不是只背公式，來解決新問題。"},{"en":"Higher-order principles help experts handle unfamiliar cases more flexibly.","zh":"高層次原則幫助專家更靈活處理不熟悉個案。"},{"en":"The phrase describes advanced use of knowledge.","zh":"這個短語描述知識的進階運用。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":9},{"front":"higher-order principles","meaning":"高層次原則","examples":[{"en":"Experts solve problems with higher-order principles.","zh":"專家用高層次原則解決問題。"},{"en":"Higher-order principles are deeper rules that organise many smaller facts or examples.","zh":"higher-order principles 是組織許多小事實或例子的更深層規則。"},{"en":"In writing, coherence is a higher-order principle because it shapes the whole essay.","zh":"在寫作中，連貫性是高層次原則，因為它塑造整篇文章。"},{"en":"These principles help learners understand why many smaller rules exist.","zh":"這些原則幫助學習者理解許多小規則為何存在。"},{"en":"The phrase refers to big guiding ideas, not minor details.","zh":"這個短語指大的指導思想，而不是細小細節。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":9},{"front":"group objects together by","meaning":"按照……把物件分類","examples":[{"en":"A novice might group objects together by colour or size.","zh":"初學者可能按照顏色或大小把物件分類。"},{"en":"To group objects together by something means to classify items using that feature.","zh":"group objects together by 某特徵，指用該特徵把物件分類。"},{"en":"A child may group toys together by shape before understanding their functions.","zh":"孩子可能先按形狀把玩具分類，才理解它們的功能。"},{"en":"Beginners often use visible features because they are easy to notice.","zh":"初學者常用可見特徵，因為它們容易注意到。"},{"en":"The phrase describes a method of classification.","zh":"這個短語描述分類方法。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":9},{"front":"according to","meaning":"根據","examples":[{"en":"An expert groups objects according to function or utility.","zh":"專家根據功能或用途把物件分類。"},{"en":"According to means based on a particular rule, feature or source.","zh":"according to 指基於某一規則、特徵或來源。"},{"en":"A librarian arranges books according to subject so readers can find them easily.","zh":"圖書館員根據主題排列書本，讓讀者容易找到。"},{"en":"Choosing a classification rule changes how people understand the items.","zh":"選擇分類規則會改變人們如何理解物件。"},{"en":"The phrase introduces the basis for ordering or judging something.","zh":"這個短語引出排序或判斷某事的基礎。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":9},{"front":"function or utility","meaning":"功能或用途","examples":[{"en":"Experts classify objects by function or utility.","zh":"專家按功能或用途將物件分類。"},{"en":"Function or utility means what something does or how it can be used.","zh":"function or utility 指某物做甚麼或可以如何使用。"},{"en":"A chef groups kitchen tools by function, such as cutting, mixing or measuring.","zh":"廚師按功能把廚具分類，例如切割、混合或量度。"},{"en":"Classifying by use helps experts solve problems more efficiently.","zh":"按用途分類幫助專家更有效地解決問題。"},{"en":"The phrase focuses on purpose, not surface appearance.","zh":"這個短語重點在目的，而不是表面外觀。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":9},{"front":"comprehend the meaning of data","meaning":"理解數據的意義","examples":[{"en":"Experts comprehend the meaning of data better than novices.","zh":"專家比初學者更能理解數據的意義。"},{"en":"To comprehend the meaning of data means to understand what information really shows.","zh":"comprehend the meaning of data 指理解資訊真正顯示甚麼。"},{"en":"A doctor understands blood-test data by linking numbers to symptoms and history.","zh":"醫生透過把數字與症狀和病史連起來理解驗血數據。"},{"en":"Data alone is not enough if people cannot interpret its meaning correctly.","zh":"如果人們不能正確解讀其意義，單有數據並不足夠。"},{"en":"The phrase describes understanding significance, not just reading figures.","zh":"這個短語描述理解重要性，而不只是閱讀數字。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":9},{"front":"weigh variables","meaning":"衡量變數","examples":[{"en":"Experts weigh variables with different criteria.","zh":"專家用不同標準衡量變數。"},{"en":"To weigh variables means to judge how important different factors are.","zh":"weigh variables 指判斷不同因素有多重要。"},{"en":"A teacher weighs variables such as effort, accuracy and improvement when giving feedback.","zh":"老師給回饋時會衡量努力、準確度和進步等變數。"},{"en":"Weighing variables helps people avoid treating every detail as equally important.","zh":"衡量變數幫助人避免把每個細節都看得同樣重要。"},{"en":"The phrase describes careful judgement among competing factors.","zh":"這個短語描述在互相競爭的因素之間作仔細判斷。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":9},{"front":"different criteria","meaning":"不同標準","examples":[{"en":"Experts use different criteria within their domains.","zh":"專家在其領域內使用不同標準。"},{"en":"Different criteria are different standards used to judge or compare things.","zh":"different criteria 是用來判斷或比較事物的不同標準。"},{"en":"A school may choose students for awards using criteria such as effort, progress and kindness.","zh":"學校可能用努力、進步和善良等標準來選出得獎學生。"},{"en":"Changing the criteria can change which answer or person seems best.","zh":"改變標準可以改變哪個答案或哪個人看起來最好。"},{"en":"The phrase refers to the standards behind a judgement.","zh":"這個短語指判斷背後的標準。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":10},{"front":"recognise variables","meaning":"辨認變數","examples":[{"en":"Experts recognise variables that strongly influence a problem.","zh":"專家辨認會強烈影響問題的變數。"},{"en":"To recognise variables means to identify factors that can change a result.","zh":"recognise variables 指辨認可以改變結果的因素。"},{"en":"A doctor recognises variables such as age, diet and exercise when assessing health.","zh":"醫生評估健康時會辨認年齡、飲食和運動等變數。"},{"en":"Recognising key variables helps people focus on causes rather than distractions.","zh":"辨認關鍵變數幫助人集中於原因，而不是干擾項。"},{"en":"The phrase describes noticing factors that matter.","zh":"這個短語描述注意到重要因素。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":10},{"front":"largest influence on","meaning":"對……有最大影響","examples":[{"en":"Some variables have the largest influence on a particular problem.","zh":"有些變數對某個特定問題有最大影響。"},{"en":"Largest influence on something means the strongest effect on that result or situation.","zh":"largest influence on 某事，指對該結果或情況有最強影響。"},{"en":"Sleep may have the largest influence on a student’s concentration during morning lessons.","zh":"睡眠可能對學生早上課堂專注力有最大影響。"},{"en":"Knowing the strongest influence helps people choose where to act first.","zh":"知道最強影響因素幫助人選擇先在哪裏行動。"},{"en":"The phrase identifies the factor that matters most.","zh":"這個短語指出最重要的因素。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":10},{"front":"focus their attention on","meaning":"將注意力集中於……","examples":[{"en":"Experts focus their attention on the most important variables.","zh":"專家將注意力集中於最重要的變數。"},{"en":"To focus their attention on something means to concentrate mental effort on it.","zh":"focus their attention on 某事，指把心理努力集中於它。"},{"en":"A student should focus attention on repeated grammar mistakes rather than every tiny imperfection.","zh":"學生應把注意力集中於重複出現的文法錯誤，而不是每個小瑕疵。"},{"en":"Focusing on important factors saves time and reduces confusion.","zh":"集中於重要因素能節省時間並減少混亂。"},{"en":"The phrase describes selective concentration.","zh":"這個短語描述選擇性集中。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":10},{"front":"domain-specific memory","meaning":"領域專屬記憶","examples":[{"en":"Experts have better domain-specific memory than novices.","zh":"專家比初學者有更好的領域專屬記憶。"},{"en":"Domain-specific memory is memory that works especially well inside a particular field.","zh":"domain-specific memory 是在某特定領域中特別有效的記憶。"},{"en":"A chess expert remembers board positions better than random objects on a table.","zh":"國際象棋專家記棋盤位置，比記桌上隨機物件更好。"},{"en":"This memory improves because knowledge is organised around meaningful patterns.","zh":"這種記憶會改善，因為知識圍繞有意義模式組織起來。"},{"en":"The phrase shows that expert memory is strongest in the expert’s own area.","zh":"這個短語顯示專家記憶在其自身領域中最強。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":10},{"front":"short-term and long-term memory","meaning":"短期和長期記憶","examples":[{"en":"Experts have better short-term and long-term memory in their domains.","zh":"專家在其領域中有更好的短期和長期記憶。"},{"en":"Short-term and long-term memory are memory for immediate information and memory stored over time.","zh":"short-term and long-term memory 是對即時資訊的記憶，以及長時間儲存的記憶。"},{"en":"A language learner uses short-term memory to repeat a sentence and long-term memory to remember vocabulary later.","zh":"語言學習者用短期記憶重複句子，用長期記憶之後記住詞彙。"},{"en":"Experts improve both kinds of memory because repeated practice links details together.","zh":"專家改善兩種記憶，因為反覆練習把細節連繫起來。"},{"en":"The phrase covers immediate recall and lasting knowledge.","zh":"這個短語涵蓋即時回想和持久知識。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":10},{"front":"moreover","meaning":"此外","examples":[{"en":"Moreover, experts perform tasks faster than novices.","zh":"此外，專家比初學者更快完成任務。"},{"en":"Moreover means in addition, and it introduces another supporting point.","zh":"moreover 指此外，並引出另一個支持觀點。"},{"en":"The school has good teachers; moreover, it offers strong after-school support.","zh":"學校有好老師；此外，它提供強大的課後支援。"},{"en":"This word helps writers add information that strengthens the same argument.","zh":"這個字幫助寫作者加入強化同一論點的資訊。"},{"en":"It is more formal than simply saying “also.”","zh":"它比 simply saying “also” 更正式。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":10},{"front":"perform tasks faster than","meaning":"比……更快完成任務","examples":[{"en":"Experts perform tasks in their domains faster than novices.","zh":"專家在其領域中比初學者更快完成任務。"},{"en":"To perform tasks faster than someone means to complete work more quickly than that person.","zh":"perform tasks faster than 某人，指比該人更快完成工作。"},{"en":"An experienced cashier serves customers faster than a new employee.","zh":"有經驗的收銀員比新員工更快服務顧客。"},{"en":"Experts work faster because they recognise what matters and ignore irrelevant details.","zh":"專家工作更快，因為他們辨認重要事項並忽略無關細節。"},{"en":"The phrase compares speed of task completion.","zh":"這個短語比較完成任務的速度。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":10},{"front":"commit fewer errors","meaning":"犯較少錯誤","examples":[{"en":"Experts commit fewer errors while solving problems.","zh":"專家在解決問題時犯較少錯誤。"},{"en":"To commit fewer errors means to make fewer mistakes.","zh":"commit fewer errors 指犯更少錯誤。"},{"en":"A trained driver commits fewer errors in heavy traffic than a beginner.","zh":"受過訓練的司機在繁忙交通中比初學者犯較少錯誤。"},{"en":"Fewer errors occur when knowledge is organised and decisions are checked.","zh":"當知識有組織且決定經檢查，錯誤會較少出現。"},{"en":"The phrase describes accuracy gained through experience.","zh":"這個短語描述透過經驗得到的準確性。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":10},{"front":"problem solving","meaning":"解難","examples":[{"en":"Experts commit fewer errors during problem solving.","zh":"專家在解難過程中犯較少錯誤。"},{"en":"Problem solving is the process of understanding a difficulty and finding a workable answer.","zh":"problem solving 是理解困難並找出可行答案的過程。"},{"en":"A student uses problem solving when deciding why a science experiment failed.","zh":"學生判斷科學實驗為何失敗時，就是在解難。"},{"en":"Good problem solving often begins with defining the problem clearly.","zh":"良好解難通常由清楚界定問題開始。"},{"en":"The phrase describes more than finding an answer; it includes understanding the situation.","zh":"這個短語描述的不只是找答案；它也包括理解情況。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":10},{"front":"go about solving problems","meaning":"以……方式解決問題","examples":[{"en":"Experts go about solving problems differently than novices.","zh":"專家解決問題的方式與初學者不同。"},{"en":"To go about solving problems means to approach or handle problems in a particular way.","zh":"go about solving problems 指以某種方式處理或應對問題。"},{"en":"A beginner may guess immediately, while an expert first asks what information is missing.","zh":"初學者可能立即猜測，而專家先問缺少甚麼資訊。"},{"en":"The way people approach a problem can affect both speed and accuracy.","zh":"人們處理問題的方式會影響速度和準確度。"},{"en":"The phrase describes method, not just final answer.","zh":"這個短語描述方法，而不只是最終答案。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":11},{"front":"spend more time thinking about","meaning":"花更多時間思考……","examples":[{"en":"Experts spend more time thinking about a problem at the beginning.","zh":"專家在開始時花更多時間思考問題。"},{"en":"To spend more time thinking about something means to give it longer careful attention.","zh":"spend more time thinking about 某事，指給它更長時間的仔細注意。"},{"en":"A good writer spends more time thinking about the question before starting the essay.","zh":"好寫作者在開始寫文章前，會花更多時間思考題目。"},{"en":"Thinking first can prevent wasted effort on the wrong solution.","zh":"先思考可以避免把努力浪費在錯誤解方上。"},{"en":"The phrase highlights careful preparation before action.","zh":"這個短語突出行動前的仔細準備。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":11},{"front":"fully understand","meaning":"完全理解","examples":[{"en":"Experts try to fully understand a problem before solving it.","zh":"專家在解決問題前嘗試完全理解它。"},{"en":"To fully understand something means to know its details, causes and limits clearly.","zh":"fully understand 某事，指清楚知道其細節、原因和限制。"},{"en":"A doctor must fully understand a patient’s symptoms before choosing treatment.","zh":"醫生在選擇治療前，必須完全理解病人的症狀。"},{"en":"Without full understanding, people may solve the wrong problem.","zh":"沒有完全理解，人們可能解決錯誤問題。"},{"en":"The phrase stresses depth of understanding before action.","zh":"這個短語強調行動前的深層理解。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":11},{"front":"at the beginning of a task","meaning":"在任務開始時","examples":[{"en":"Experts think deeply at the beginning of a task.","zh":"專家在任務開始時深入思考。"},{"en":"At the beginning of a task means during the first stage before most work is done.","zh":"at the beginning of a task 指在大部分工作完成前的第一階段。"},{"en":"A student should read the question carefully at the beginning of a writing task.","zh":"學生在寫作任務開始時應仔細閱讀題目。"},{"en":"Good decisions early can save time and prevent mistakes later.","zh":"早期作出好決定可以節省時間並防止之後犯錯。"},{"en":"The phrase points to the planning stage.","zh":"這個短語指計劃階段。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":11},{"front":"seek to find","meaning":"試圖尋找","examples":[{"en":"Novices immediately seek to find a solution.","zh":"初學者會立即試圖尋找解決方案。"},{"en":"To seek to find something means to try to look for it actively.","zh":"seek to find 某物，指主動嘗試尋找它。"},{"en":"A student may seek to find the answer before fully reading the question.","zh":"學生可能在未完全讀懂題目前就試圖尋找答案。"},{"en":"Searching too quickly can lead to shallow or incorrect solutions.","zh":"太快尋找答案可能導致表面或錯誤解方。"},{"en":"The phrase describes active searching, often with urgency.","zh":"這個短語描述主動尋找，常帶有急切感。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":11},{"front":"use previous cases as context","meaning":"以過往個案作為背景","examples":[{"en":"Experts use previous cases as context for new problems.","zh":"專家以過往個案作為新問題的背景。"},{"en":"To use previous cases as context means to understand a new problem by comparing it with earlier examples.","zh":"use previous cases as context 指透過與早前例子比較來理解新問題。"},{"en":"A teacher may use previous student essays as context when judging a new writing mistake.","zh":"老師判斷新的寫作錯誤時，可能以過往學生文章作為背景。"},{"en":"Past cases help experts see what is normal, unusual or missing.","zh":"過往個案幫助專家看見甚麼是正常、不尋常或缺失的。"},{"en":"The phrase shows how experience guides new judgement.","zh":"這個短語顯示經驗如何指導新判斷。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":11},{"front":"create mental models","meaning":"建立心智模型","examples":[{"en":"Experts create mental models to solve problems.","zh":"專家建立心智模型來解決問題。"},{"en":"To create mental models means to build internal pictures or frameworks for understanding how something works.","zh":"create mental models 指建立內在圖像或框架，以理解某事如何運作。"},{"en":"A driver creates a mental model of traffic flow when choosing the fastest route.","zh":"司機選擇最快路線時，會建立交通流動的心智模型。"},{"en":"Mental models help people predict results before acting.","zh":"心智模型幫助人在行動前預測結果。"},{"en":"The phrase describes thinking tools inside the mind.","zh":"這個短語描述頭腦中的思考工具。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":11},{"front":"given problems","meaning":"指定問題","examples":[{"en":"Experts use mental models to solve given problems.","zh":"專家使用心智模型來解決指定問題。"},{"en":"Given problems are specific problems presented or assigned to someone.","zh":"given problems 是被提供或分配給某人的特定問題。"},{"en":"In an exam, students must solve the given problems, not invent different ones.","zh":"在考試中，學生必須解決指定問題，而不是自創不同問題。"},{"en":"A clear model helps experts apply knowledge to the problem in front of them.","zh":"清晰模型幫助專家把知識應用到眼前問題上。"},{"en":"The phrase refers to particular problems already provided.","zh":"這個短語指已提供的特定問題。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":11},{"front":"better at self-monitoring","meaning":"較善於自我監察","examples":[{"en":"Experts are better at self-monitoring than novices.","zh":"專家比初學者更善於自我監察。"},{"en":"Self-monitoring is the ability to check one’s own thinking, progress and mistakes.","zh":"self-monitoring 是檢查自己思考、進度和錯誤的能力。"},{"en":"A good writer self-monitors by rereading paragraphs and asking whether the argument is clear.","zh":"好寫作者會透過重讀段落並問論點是否清楚來自我監察。"},{"en":"Better self-monitoring helps experts catch errors before they become serious.","zh":"更好的自我監察幫助專家在錯誤變嚴重前發現它們。"},{"en":"The phrase describes watching one’s own performance carefully.","zh":"這個短語描述仔細觀察自己的表現。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":11},{"front":"be aware of instances where","meaning":"意識到……的情況","examples":[{"en":"Experts are aware of instances where they have made mistakes.","zh":"專家意識到自己曾犯錯的情況。"},{"en":"To be aware of instances where something happened means to recognise particular examples of it.","zh":"be aware of instances where 某事發生，指辨認該事情的具體例子。"},{"en":"A teacher may be aware of instances where students misunderstood the same instruction.","zh":"老師可能意識到學生誤解同一指示的情況。"},{"en":"Awareness of past mistakes helps people avoid repeating them.","zh":"對過往錯誤有意識能幫助人避免重複它們。"},{"en":"The phrase connects recognition with specific examples.","zh":"這個短語把辨認與具體例子連繫起來。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":11},{"front":"commit errors","meaning":"犯錯","examples":[{"en":"Experts notice when they have committed errors.","zh":"專家注意到自己何時犯錯。"},{"en":"To commit errors means to make mistakes.","zh":"commit errors 指犯錯誤。"},{"en":"A careful accountant checks calculations to see whether she has committed errors.","zh":"細心會計師會檢查計算，以看看自己是否犯錯。"},{"en":"Noticing errors quickly allows people to correct them before damage spreads.","zh":"快速注意錯誤讓人能在傷害擴大前改正。"},{"en":"The phrase is a formal way to say “make mistakes.”","zh":"這個短語是 “make mistakes” 的正式說法。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":12},{"front":"fail to understand","meaning":"未能理解","examples":[{"en":"Experts recognise when they have failed to understand a problem.","zh":"專家察覺自己何時未能理解問題。"},{"en":"To fail to understand means not to grasp the meaning, cause or structure of something.","zh":"fail to understand 指沒有掌握某事的意思、原因或結構。"},{"en":"A student may fail to understand a question if she only reads the first line.","zh":"如果學生只讀第一行，她可能未能理解題目。"},{"en":"Recognising misunderstanding is important because it prevents false confidence.","zh":"察覺誤解很重要，因為它防止錯誤自信。"},{"en":"The phrase describes a gap in understanding, not simple carelessness.","zh":"這個短語描述理解上的缺口，而不只是粗心。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":12},{"front":"check their solution","meaning":"檢查自己的解決方案","examples":[{"en":"Experts check their solution more often than novices.","zh":"專家比初學者更常檢查自己的解決方案。"},{"en":"To check their solution means to review an answer or method to see whether it is correct.","zh":"check their solution 指檢視答案或方法是否正確。"},{"en":"A maths student checks her solution by putting the answer back into the equation.","zh":"數學學生會把答案代回方程式，以檢查自己的解決方案。"},{"en":"Checking helps people catch hidden mistakes before submitting work.","zh":"檢查幫助人在提交工作前發現隱藏錯誤。"},{"en":"The phrase describes verification after problem-solving.","zh":"這個短語描述解難後的驗證。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":12},{"front":"recognise when","meaning":"察覺到何時……","examples":[{"en":"Experts recognise when they are missing information.","zh":"專家察覺到何時缺少資料。"},{"en":"To recognise when something happens means to notice the moment or situation in which it is true.","zh":"recognise when 某事發生，指注意到該事情成立的時刻或情況。"},{"en":"A good driver recognises when the road is too wet to drive quickly.","zh":"好司機會察覺到路面何時太濕，不適合開快車。"},{"en":"Recognising when action is needed prevents small problems from growing.","zh":"察覺何時需要行動，可以防止小問題擴大。"},{"en":"The phrase focuses on timely awareness.","zh":"這個短語重點在及時意識。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":12},{"front":"missing information","meaning":"缺少資料","examples":[{"en":"Experts recognise when they are missing information necessary for solving a problem.","zh":"專家察覺何時缺少解決問題所必需的資料。"},{"en":"Missing information is information that is needed but not yet available.","zh":"missing information 是需要但尚未取得的資訊。"},{"en":"A doctor may delay a decision because blood-test results are missing information.","zh":"醫生可能因驗血結果仍是缺少資料，而延遲決定。"},{"en":"If important information is missing, any answer may be unreliable.","zh":"如果重要資料缺失，任何答案都可能不可靠。"},{"en":"The phrase describes a gap that must be filled before confident judgement.","zh":"這個短語描述在有信心判斷前必須填補的缺口。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":12},{"front":"necessary for solving","meaning":"解決……所必需的","examples":[{"en":"Some information is necessary for solving a problem.","zh":"有些資料是解決問題所必需的。"},{"en":"Necessary for solving means required in order to find a correct solution.","zh":"necessary for solving 指為找出正確解決方案所必需。"},{"en":"A student needs the question data because it is necessary for solving the maths problem.","zh":"學生需要題目數據，因為它是解決數學題所必需的。"},{"en":"Without necessary information, even an expert may hesitate.","zh":"沒有必要資料，即使專家也可能猶豫。"},{"en":"The phrase identifies what must be present before a solution is possible.","zh":"這個短語指出解決方案可能出現前必須具備的東西。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":12},{"front":"limits of their domain knowledge","meaning":"其領域知識的限制","examples":[{"en":"Experts are aware of the limits of their domain knowledge.","zh":"專家意識到其領域知識的限制。"},{"en":"The limits of their domain knowledge are the boundaries of what experts know in their field.","zh":"limits of their domain knowledge 是專家在其領域中所知內容的界限。"},{"en":"A heart specialist may know when a skin problem falls outside her expertise.","zh":"心臟專科醫生可能知道某皮膚問題超出她的專業範圍。"},{"en":"Knowing limits prevents experts from giving overconfident advice.","zh":"知道限制可以防止專家給出過度自信的建議。"},{"en":"The phrase shows intellectual humility inside expertise.","zh":"這個短語顯示專業中的知識謙遜。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":12},{"front":"apply heuristics","meaning":"應用啟發式法則","examples":[{"en":"Experts apply their domain’s heuristics to unfamiliar problems.","zh":"專家將其領域的啟發式法則應用於不熟悉的問題。"},{"en":"To apply heuristics means to use practical rules of thumb to reach a likely solution.","zh":"apply heuristics 指使用實用經驗法則來找出可能解決方案。"},{"en":"A doctor may use heuristics to decide which symptoms need urgent attention first.","zh":"醫生可能用啟發式法則判斷哪些症狀首先需要緊急處理。"},{"en":"Heuristics save time, but they must be checked when a case is unusual.","zh":"啟發式法則能節省時間，但遇到不尋常個案時必須檢查。"},{"en":"The phrase describes practical judgement, not a guaranteed formula.","zh":"這個短語描述實用判斷，而不是保證有效的公式。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":12},{"front":"domain’s heuristics","meaning":"該領域的啟發式法則","examples":[{"en":"Experts use their domain’s heuristics to solve problems.","zh":"專家使用其領域的啟發式法則來解決問題。"},{"en":"A domain’s heuristics are practical shortcuts or rules commonly used in a specific field.","zh":"domain’s heuristics 是某特定領域中常用的實用捷徑或規則。"},{"en":"A mechanic’s heuristics may help him guess which engine part is most likely faulty.","zh":"機械師的啟發式法則可能幫助他猜測哪個引擎部件最可能有問題。"},{"en":"These rules work best when they are based on long experience.","zh":"這些規則在基於長期經驗時最有效。"},{"en":"The phrase refers to field-specific practical judgement.","zh":"這個短語指領域專屬的實用判斷。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":12},{"front":"fall outside of","meaning":"超出……範圍","examples":[{"en":"Some problems fall outside of the expert’s experience base.","zh":"有些問題超出專家的經驗基礎。"},{"en":"To fall outside of something means to be beyond its range or limits.","zh":"fall outside of 某事，指超出其範圍或限制。"},{"en":"A legal question may fall outside of a teacher’s knowledge, even if the teacher is very experienced.","zh":"法律問題可能超出老師的知識範圍，即使老師很有經驗。"},{"en":"When a problem falls outside known experience, experts must be cautious.","zh":"當問題超出已知經驗，專家必須謹慎。"},{"en":"The phrase describes being beyond a boundary.","zh":"這個短語描述超越界限。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":12},{"front":"experience base","meaning":"經驗基礎","examples":[{"en":"Experts may face problems outside their experience base.","zh":"專家可能面對超出其經驗基礎的問題。"},{"en":"An experience base is the collection of past cases, examples and situations someone has learned from.","zh":"experience base 是某人從中學習的過往個案、例子和情況的集合。"},{"en":"A nurse’s experience base grows after years of working with different patients.","zh":"護士多年與不同病人工作後，經驗基礎會增長。"},{"en":"A broad experience base helps people handle new problems more confidently.","zh":"廣闊經驗基礎幫助人更有信心處理新問題。"},{"en":"The phrase refers to knowledge built from real experience.","zh":"這個短語指由真實經驗建立的知識。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":13},{"front":"the paradox of expertise","meaning":"專業知識的矛盾","examples":[{"en":"The passage discusses the paradox of expertise.","zh":"文章討論專業知識的矛盾。"},{"en":"The paradox of expertise is the surprising idea that expert strengths can also create weaknesses.","zh":"the paradox of expertise 是指專家的優勢也可能造成弱點這個令人意外的想法。"},{"en":"An expert may solve familiar problems quickly but struggle when old patterns mislead her.","zh":"專家可能快速解決熟悉問題，但當舊模式誤導她時會遇到困難。"},{"en":"This paradox shows that deep knowledge does not guarantee perfect judgement.","zh":"這個矛盾顯示深厚知識不保證完美判斷。"},{"en":"The phrase describes a contradiction inside expertise itself.","zh":"這個短語描述專業本身內部的矛盾。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":13},{"front":"strengths of expertise","meaning":"專業知識的優勢","examples":[{"en":"The strengths of expertise can also become weaknesses.","zh":"專業知識的優勢也可以變成弱點。"},{"en":"Strengths of expertise are the advantages that come from deep knowledge and experience.","zh":"strengths of expertise 是來自深厚知識和經驗的優點。"},{"en":"Fast pattern recognition is one strength of expertise in medicine, chess or teaching.","zh":"快速辨認模式是醫學、國際象棋或教學中專業知識的優勢之一。"},{"en":"The same strength can become a weakness if experts trust patterns too quickly.","zh":"如果專家太快相信模式，同一優勢可能變成弱點。"},{"en":"The phrase points to expert advantages that need careful control.","zh":"這個短語指出需要小心控制的專家優勢。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":13},{"front":"one would expect","meaning":"人們會預期","examples":[{"en":"One would expect experts to be good forecasters.","zh":"人們會預期專家是優秀預測者。"},{"en":"One would expect means most people would naturally think something should be true.","zh":"one would expect 指大多數人自然會認為某事應該是真的。"},{"en":"One would expect a trained chef to cook better than a beginner.","zh":"人們會預期受過訓練的廚師比初學者煮得更好。"},{"en":"This phrase often introduces an assumption that may later be questioned.","zh":"這個短語常引出之後可能被質疑的假設。"},{"en":"It shows what seems logical before evidence is considered.","zh":"它顯示在考慮證據前看似合理的想法。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":13},{"front":"good forecasters","meaning":"優秀預測者","examples":[{"en":"Experts are not always good forecasters.","zh":"專家並不總是優秀預測者。"},{"en":"Good forecasters are people who predict future events accurately.","zh":"good forecasters 是能準確預測未來事件的人。"},{"en":"A weather forecaster is good if tomorrow’s weather often matches the prediction.","zh":"如果明天天氣常與預測相符，天氣預報員就是優秀預測者。"},{"en":"Forecasting is difficult because the future can change in unexpected ways.","zh":"預測很困難，因為未來可以以意想不到的方式改變。"},{"en":"The phrase describes prediction skill, not general intelligence.","zh":"這個短語描述預測能力，而不是整體智力。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":13},{"front":"not particularly good at","meaning":"並不特別擅長……","examples":[{"en":"Experts are not particularly good at making predictions about the future.","zh":"專家並不特別擅長對未來作出預測。"},{"en":"Not particularly good at something means not especially skilled in that activity.","zh":"not particularly good at 某事，指在該活動上並不是特別熟練。"},{"en":"A strong writer may be not particularly good at public speaking.","zh":"寫作很強的人可能並不特別擅長公開演說。"},{"en":"This phrase softens criticism while still showing a weakness.","zh":"這個短語在顯示弱點的同時，也令批評較溫和。"},{"en":"It means the person may be average or limited in that area.","zh":"它表示該人在該方面可能只是普通或有限。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":13},{"front":"predictions about the future","meaning":"對未來的預測","examples":[{"en":"Experts may struggle with predictions about the future.","zh":"專家可能在對未來的預測上遇到困難。"},{"en":"Predictions about the future are guesses or forecasts about what will happen later.","zh":"predictions about the future 是關於之後會發生甚麼的猜測或預測。"},{"en":"A business owner makes predictions about future sales before hiring more staff.","zh":"企業主在聘請更多員工前，會對未來銷售作出預測。"},{"en":"Future predictions can fail when new information appears or conditions change.","zh":"當新資訊出現或情況改變，未來預測可能失敗。"},{"en":"The phrase refers to forward-looking judgement.","zh":"這個短語指面向未來的判斷。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":13},{"front":"since the 1930s","meaning":"自1930年代以來","examples":[{"en":"Since the 1930s, researchers have tested experts’ forecasting ability.","zh":"自1930年代以來，研究人員一直測試專家的預測能力。"},{"en":"Since the 1930s means from the decade between 1930 and 1939 until now or a later time.","zh":"since the 1930s 指從1930至1939年那個十年開始，直到現在或之後某時間。"},{"en":"Since the 1930s, many schools have changed how they teach reading.","zh":"自1930年代以來，許多學校已改變教授閱讀的方式。"},{"en":"The phrase shows that the research has a long history.","zh":"這個短語顯示該研究有很長歷史。"},{"en":"It places an issue in a historical time frame.","zh":"它把議題放入歷史時間框架。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":13},{"front":"ability to make forecasts","meaning":"作出預測的能力","examples":[{"en":"Researchers tested experts’ ability to make forecasts.","zh":"研究人員測試專家作出預測的能力。"},{"en":"Ability to make forecasts is the skill of predicting future results or events.","zh":"ability to make forecasts 是預測未來結果或事件的技能。"},{"en":"A shop manager needs the ability to forecast demand before ordering products.","zh":"商店經理在訂貨前需要預測需求的能力。"},{"en":"Forecasting ability improves when people use evidence and check past predictions.","zh":"當人們使用證據並檢查過往預測，預測能力會提升。"},{"en":"The phrase refers to prediction skill.","zh":"這個短語指預測技能。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":13},{"front":"be tested against","meaning":"與……比較測試","examples":[{"en":"The performance of experts has been tested against actuarial tables.","zh":"專家的表現曾與精算表比較測試。"},{"en":"To be tested against something means to be compared with it to judge accuracy or strength.","zh":"be tested against 某物，指與它比較，以判斷準確度或強度。"},{"en":"A new teaching method can be tested against the old method using exam results.","zh":"新教學方法可以用考試結果與舊方法比較測試。"},{"en":"Comparison helps show whether one method is truly better than another.","zh":"比較有助顯示一種方法是否真的比另一種更好。"},{"en":"The phrase describes evaluation through direct comparison.","zh":"這個短語描述透過直接比較進行評估。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":13},{"front":"actuarial tables","meaning":"精算表","examples":[{"en":"Actuarial tables can predict outcomes as well as experts.","zh":"精算表可以像專家一樣好地預測結果。"},{"en":"Actuarial tables are statistical tables used to estimate risks or future outcomes.","zh":"actuarial tables 是用來估計風險或未來結果的統計表。"},{"en":"Insurance companies use actuarial tables to estimate life expectancy and costs.","zh":"保險公司使用精算表來估計壽命和成本。"},{"en":"These tables rely on patterns in large amounts of data rather than personal judgement.","zh":"這些表依靠大量數據中的模式，而不是個人判斷。"},{"en":"The phrase refers to formal statistical tools for prediction.","zh":"這個短語指用於預測的正式統計工具。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":14},{"front":"determine if","meaning":"判斷是否","examples":[{"en":"Researchers wanted to determine if experts were better than models.","zh":"研究人員想判斷專家是否比模型更好。"},{"en":"To determine if something is true means to find out whether it is true.","zh":"determine if 某事為真，指查明它是否為真。"},{"en":"A doctor may run tests to determine if a patient has an infection.","zh":"醫生可能進行測試，以判斷病人是否感染。"},{"en":"Determining the answer requires evidence, not just opinion.","zh":"判斷答案需要證據，而不只是意見。"},{"en":"The phrase introduces investigation of a yes-or-no question.","zh":"這個短語引出對是非問題的調查。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":14},{"front":"statistical models","meaning":"統計模型","examples":[{"en":"Simple statistical models can outperform experts.","zh":"簡單統計模型可以勝過專家。"},{"en":"Statistical models are mathematical tools that use data to estimate or predict outcomes.","zh":"statistical models 是使用數據估計或預測結果的數學工具。"},{"en":"A school may use a statistical model to predict which students need extra support.","zh":"學校可能使用統計模型來預測哪些學生需要額外支援。"},{"en":"Models can be useful because they apply the same rules consistently.","zh":"模型有用，因為它們一致地應用同一套規則。"},{"en":"The phrase refers to data-based prediction systems.","zh":"這個短語指以數據為基礎的預測系統。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":14},{"front":"seventy years later","meaning":"七十年後","examples":[{"en":"Seventy years later, the answer was clear.","zh":"七十年後，答案變得清楚。"},{"en":"Seventy years later means after a period of seventy years had passed.","zh":"seventy years later 指七十年過去之後。"},{"en":"A building built in 1950 may need major repairs seventy years later.","zh":"一座1950年建成的建築，在七十年後可能需要大規模維修。"},{"en":"The phrase shows that the conclusion came after a long period of research or time.","zh":"這個短語顯示結論是在長時間研究或時間過去後得出。"},{"en":"It helps readers understand the scale of the time gap.","zh":"它幫助讀者理解時間差距的規模。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":14},{"front":"experiments in different domains","meaning":"不同領域的實驗","examples":[{"en":"Researchers conducted experiments in different domains.","zh":"研究人員在不同領域進行實驗。"},{"en":"Experiments in different domains are studies carried out across several fields or areas.","zh":"experiments in different domains 是在幾個領域或範疇中進行的研究。"},{"en":"Researchers may test decision-making in medicine, business and education.","zh":"研究人員可能在醫學、商業和教育中測試決策。"},{"en":"Testing across domains helps show whether a finding is general or field-specific.","zh":"跨領域測試有助顯示某發現是普遍，還是只限於某領域。"},{"en":"The phrase describes research beyond one single area.","zh":"這個短語描述超出單一領域的研究。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":14},{"front":"be supplied with","meaning":"獲提供……","examples":[{"en":"If experts are supplied with equal data, they may not outperform models.","zh":"如果專家獲提供同等數據，他們未必勝過模型。"},{"en":"To be supplied with something means to be given it for use.","zh":"be supplied with 某物，指獲給予該物以供使用。"},{"en":"Students supplied with clear examples can complete the exercise more confidently.","zh":"獲提供清楚例子的學生可以更有信心完成練習。"},{"en":"When both sides receive the same information, comparison becomes fairer.","zh":"當雙方收到相同資訊時，比較會更公平。"},{"en":"The phrase focuses on what information or materials are provided.","zh":"這個短語重點在提供了甚麼資訊或材料。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":14},{"front":"equal amount of data","meaning":"同等數量的數據","examples":[{"en":"Experts and statistical models may receive an equal amount of data.","zh":"專家和統計模型可能收到同等數量的數據。"},{"en":"An equal amount of data means the same quantity of information.","zh":"equal amount of data 指相同數量的資訊。"},{"en":"In a fair test, two groups should receive an equal amount of information before answering.","zh":"在公平測試中，兩組人在回答前應收到同等數量的資訊。"},{"en":"Equal data helps researchers compare expert judgement with model judgement fairly.","zh":"同等數據幫助研究人員公平比較專家判斷和模型判斷。"},{"en":"The phrase stresses fairness in comparison.","zh":"這個短語強調比較中的公平性。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":14},{"front":"particular case","meaning":"特定個案","examples":[{"en":"The prediction concerns a particular case.","zh":"該預測涉及一個特定個案。"},{"en":"A particular case is one specific example, person or situation being considered.","zh":"particular case 是正在考慮的一個具體例子、人物或情況。"},{"en":"A doctor may discuss a particular case during a hospital meeting.","zh":"醫生可能在醫院會議中討論某個特定個案。"},{"en":"Details of a particular case can change which prediction seems most reasonable.","zh":"特定個案的細節可以改變哪個預測看似最合理。"},{"en":"The phrase narrows attention from general patterns to one example.","zh":"這個短語把注意力從一般模式收窄到一個例子。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":14},{"front":"as good as or better than","meaning":"與……一樣好或更好","examples":[{"en":"An actuarial table can be as good as or better than an expert.","zh":"精算表可以與專家一樣好或更好。"},{"en":"As good as or better than means equal to or superior to something else.","zh":"as good as or better than 指與另一事物相等或比它更好。"},{"en":"A free online dictionary may be as good as or better than a cheap printed one for quick checks.","zh":"免費網上字典在快速查核時，可能與便宜紙本字典一樣好或更好。"},{"en":"This phrase compares performance without assuming one side must win.","zh":"這個短語比較表現，而不假設其中一方必然勝出。"},{"en":"It allows for equality and advantage at the same time.","zh":"它同時容許相等和優勢兩種情況。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":14},{"front":"making calls about the future","meaning":"對未來作判斷","examples":[{"en":"Experts and models make calls about the future.","zh":"專家和模型對未來作判斷。"},{"en":"Making calls about the future means making judgements or predictions about what will happen later.","zh":"making calls about the future 指對之後會發生甚麼作出判斷或預測。"},{"en":"A school principal makes calls about future enrolment before hiring teachers.","zh":"校長在聘請老師前，會對未來收生情況作判斷。"},{"en":"Calls about the future can be uncertain because conditions may change.","zh":"對未來的判斷可能不確定，因為情況可能改變。"},{"en":"The phrase is informal and means making predictive judgements.","zh":"這個短語較口語，意思是作出預測性判斷。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":14},{"front":"specific case information","meaning":"具體個案資料","examples":[{"en":"An expert may receive more specific case information.","zh":"專家可能收到更多具體個案資料。"},{"en":"Specific case information is detailed information about one particular case.","zh":"specific case information 是關於某個特定個案的詳細資訊。"},{"en":"A doctor needs specific case information such as age, symptoms and medical history.","zh":"醫生需要年齡、症狀和病史等具體個案資料。"},{"en":"Extra case details can improve judgement if they are relevant and reliable.","zh":"如果額外個案細節相關且可靠，它們可以改善判斷。"},{"en":"The phrase refers to concrete details about a single situation.","zh":"這個短語指關於單一情況的具體細節。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":15},{"front":"be available to","meaning":"可供……使用","examples":[{"en":"Some case information is not available to the statistical model.","zh":"有些個案資料不可供統計模型使用。"},{"en":"To be available to someone means that person or system can access or use it.","zh":"be available to 某人，指該人或系統可以取得或使用它。"},{"en":"Library computers are available to students during opening hours.","zh":"圖書館電腦在開放時間可供學生使用。"},{"en":"If key information is not available, a model may make a weaker prediction.","zh":"如果關鍵資訊不可用，模型可能作出較弱預測。"},{"en":"The phrase describes access to information, tools or resources.","zh":"這個短語描述對資訊、工具或資源的使用權。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":15},{"front":"tend to outperform","meaning":"往往勝過","examples":[{"en":"Experts do not tend to outperform actuarial tables.","zh":"專家並不往往勝過精算表。"},{"en":"To tend to outperform means to usually do better than another person or method.","zh":"tend to outperform 指通常比另一人或方法表現更好。"},{"en":"Students who practise regularly tend to outperform those who only study the night before.","zh":"定期練習的學生往往勝過只在前一晚溫習的學生。"},{"en":"If one method does not tend to outperform another, it is not usually better.","zh":"如果一種方法並不往往勝過另一種，它通常不是更好。"},{"en":"The phrase describes a general performance pattern.","zh":"這個短語描述一般表現模式。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":15},{"front":"differ when trying to explain","meaning":"在試圖解釋時意見不同","examples":[{"en":"Theorists and researchers differ when trying to explain expert forecasting.","zh":"理論家和研究人員在試圖解釋專家預測時意見不同。"},{"en":"To differ when trying to explain something means to disagree about the reason behind it.","zh":"differ when trying to explain 某事，指對其背後原因有不同看法。"},{"en":"Teachers may differ when trying to explain why a class performed badly.","zh":"老師在試圖解釋為何一班表現差時，可能意見不同。"},{"en":"Different explanations can lead to different solutions.","zh":"不同解釋可以導致不同解決方法。"},{"en":"The phrase describes disagreement in interpretation.","zh":"這個短語描述詮釋上的分歧。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":15},{"front":"less accurate forecasters","meaning":"較不準確的預測者","examples":[{"en":"Experts are often less accurate forecasters than statistical models.","zh":"專家常是比統計模型較不準確的預測者。"},{"en":"Less accurate forecasters are people or methods whose predictions are correct less often.","zh":"less accurate forecasters 是預測較少正確的人或方法。"},{"en":"A person who guesses the weather without data is usually a less accurate forecaster than a weather model.","zh":"不使用數據猜天氣的人，通常比天氣模型是較不準確的預測者。"},{"en":"Less accurate forecasting can lead to poor planning and wrong decisions.","zh":"較不準確的預測可能導致差劣計劃和錯誤決定。"},{"en":"The phrase compares prediction accuracy.","zh":"這個短語比較預測準確度。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":15},{"front":"argue that","meaning":"主張；認為","examples":[{"en":"Some researchers argue that experts are inconsistent.","zh":"一些研究人員認為專家前後不一致。"},{"en":"To argue that something is true means to present reasons supporting that view.","zh":"argue that 某事為真，指提出理由支持該看法。"},{"en":"A student may argue that homework should be shorter because sleep affects learning.","zh":"學生可能主張功課應較短，因為睡眠影響學習。"},{"en":"An argument is stronger when evidence supports the claim.","zh":"當證據支持主張，論點會更強。"},{"en":"The phrase introduces a reasoned opinion, not just a feeling.","zh":"這個短語引出有理由的意見，而不只是感覺。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":15},{"front":"like all humans","meaning":"像所有人一樣","examples":[{"en":"Experts, like all humans, may be inconsistent.","zh":"專家像所有人一樣，可能前後不一致。"},{"en":"Like all humans means the statement applies to experts because they are human too.","zh":"like all humans 指該陳述也適用於專家，因為他們也是人。"},{"en":"Teachers, like all humans, can feel tired and make mistakes.","zh":"老師像所有人一樣，也會疲倦和犯錯。"},{"en":"This phrase reminds readers that expert status does not remove ordinary human limits.","zh":"這個短語提醒讀者，專家身份並不消除普通人類限制。"},{"en":"It places experts inside a wider human group.","zh":"它把專家放在更廣泛的人類群體之內。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":15},{"front":"be inconsistent when","meaning":"在……時前後不一致","examples":[{"en":"Experts may be inconsistent when using mental models.","zh":"專家在使用心智模型時可能前後不一致。"},{"en":"To be inconsistent when doing something means not to act in the same way each time.","zh":"be inconsistent when 做某事，指每次行動方式不一樣。"},{"en":"A student is inconsistent when she uses a grammar rule correctly in one essay but wrongly in another.","zh":"學生在一篇文章中正確使用文法規則，但在另一篇中用錯，就是前後不一致。"},{"en":"Inconsistency can make predictions unreliable.","zh":"前後不一致可以令預測不可靠。"},{"en":"The phrase describes changing behaviour or judgement across similar situations.","zh":"這個短語描述在相似情況中行為或判斷改變。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":15},{"front":"mental models","meaning":"心智模型","examples":[{"en":"Experts use mental models to make predictions.","zh":"專家使用心智模型來作出預測。"},{"en":"Mental models are internal frameworks that help people understand and predict how something works.","zh":"mental models 是幫助人理解和預測某事如何運作的內在框架。"},{"en":"A driver uses a mental model of traffic to choose which lane to take.","zh":"司機用交通的心智模型來選擇哪條行車線。"},{"en":"Mental models are useful, but they can mislead people if the situation changes.","zh":"心智模型有用，但如果情況改變，它們也可能誤導人。"},{"en":"The phrase describes thinking structures inside the mind.","zh":"這個短語描述頭腦中的思考結構。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":15},{"front":"in the following month","meaning":"在下一個月","examples":[{"en":"An expert may use a different model in the following month.","zh":"專家可能在下一個月使用不同模型。"},{"en":"In the following month means during the next month after the time mentioned.","zh":"in the following month 指在所提及時間之後的下一個月。"},{"en":"A student may finish one course in June and start a new one in the following month.","zh":"學生可能在六月完成一個課程，並在下一個月開始新課程。"},{"en":"The phrase helps show a change across time.","zh":"這個短語幫助顯示隨時間出現的變化。"},{"en":"It refers to the next month, not any later month.","zh":"它指下一個月，而不是任何更後的月份。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":15},{"front":"precisely the same","meaning":"完全相同的","examples":[{"en":"The same case and data set may be used.","zh":"可能使用完全相同的個案和數據集。"},{"en":"Precisely the same means exactly the same, with no meaningful difference.","zh":"precisely the same 指完全一樣，沒有有意義的差異。"},{"en":"Two students may receive precisely the same question but give different answers.","zh":"兩名學生可能收到完全相同的問題，但給出不同答案。"},{"en":"If the information is precisely the same, different results suggest judgement has changed.","zh":"如果資訊完全相同，而結果不同，這暗示判斷已改變。"},{"en":"The phrase stresses exact sameness.","zh":"這個短語強調精確相同。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":16},{"front":"data set","meaning":"數據集","examples":[{"en":"The same data set can lead to different expert predictions.","zh":"同一數據集可以導致不同專家預測。"},{"en":"A data set is a collection of information used for analysis or decision-making.","zh":"data set 是用於分析或決策的一組資訊。"},{"en":"A school may use a data set of attendance and marks to identify students needing support.","zh":"學校可能使用出席率和成績的數據集來辨認需要支援的學生。"},{"en":"A data set must be interpreted carefully because numbers alone do not explain everything.","zh":"數據集必須仔細解讀，因為單靠數字不能解釋一切。"},{"en":"The phrase refers to organised information for study.","zh":"這個短語指用於研究的有組織資訊。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":16},{"front":"in both instances","meaning":"在兩種情況中","examples":[{"en":"The same data are used in both instances.","zh":"在兩種情況中都使用相同數據。"},{"en":"In both instances means in both cases or situations being discussed.","zh":"in both instances 指在所討論的兩個個案或情況中。"},{"en":"A student may make the same spelling mistake in both instances of a writing task.","zh":"學生可能在兩種寫作任務情況中犯同一拼字錯誤。"},{"en":"If the result differs in both instances despite the same data, something else must have changed.","zh":"如果在相同數據下兩種情況結果不同，那一定有其他事情改變。"},{"en":"The phrase compares two situations together.","zh":"這個短語把兩種情況一起比較。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":16},{"front":"point to","meaning":"指向；歸因於","examples":[{"en":"Some researchers point to human biases.","zh":"一些研究人員把原因指向人類偏見。"},{"en":"To point to something means to identify it as a possible cause or explanation.","zh":"point to 某事，指把它指出為可能原因或解釋。"},{"en":"Falling test scores may point to poor sleep rather than weak ability.","zh":"測驗分數下降可能指向睡眠差，而不是能力弱。"},{"en":"Evidence can point to a problem even before people fully understand it.","zh":"證據可以在人們完全理解前已指向某問題。"},{"en":"The phrase means “suggest as the explanation.”","zh":"這個短語意思是「指出為解釋」。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":16},{"front":"human biases","meaning":"人類偏見","examples":[{"en":"Human biases may explain unreliable expert predictions.","zh":"人類偏見可能解釋不可靠的專家預測。"},{"en":"Human biases are unfair or unconscious tendencies that affect judgement.","zh":"human biases 是影響判斷的不公平或無意識傾向。"},{"en":"A teacher may have a bias if she expects quiet students to be weaker without evidence.","zh":"如果老師沒有證據就預期安靜學生較弱，她可能有偏見。"},{"en":"Biases can make people interpret the same data differently.","zh":"偏見可以令人以不同方式解讀同一數據。"},{"en":"The phrase describes mental distortions that can affect decisions.","zh":"這個短語描述會影響決策的心理扭曲。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":16},{"front":"unreliable expert predictions","meaning":"不可靠的專家預測","examples":[{"en":"Researchers try to explain unreliable expert predictions.","zh":"研究人員嘗試解釋不可靠的專家預測。"},{"en":"Unreliable expert predictions are expert forecasts that cannot be trusted consistently.","zh":"unreliable expert predictions 是不能持續信任的專家預測。"},{"en":"A financial expert may make unreliable predictions if personal bias affects market judgement.","zh":"如果個人偏見影響市場判斷，金融專家可能作出不可靠預測。"},{"en":"Unreliable predictions can lead people to make poor plans.","zh":"不可靠預測可以令人作出差劣計劃。"},{"en":"The phrase shows that expert opinion is not always dependable.","zh":"這個短語顯示專家意見並不總是可靠。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":16},{"front":"cognitive aspects of forecasting","meaning":"預測的認知層面","examples":[{"en":"Researchers have studied the cognitive aspects of forecasting.","zh":"研究人員已研究預測的認知層面。"},{"en":"Cognitive aspects of forecasting are the thinking processes involved in making predictions.","zh":"cognitive aspects of forecasting 是作出預測時涉及的思考過程。"},{"en":"Researchers may study how memory, bias and attention affect weather or business forecasts.","zh":"研究人員可能研究記憶、偏見和注意力如何影響天氣或商業預測。"},{"en":"Understanding these mental processes helps explain why predictions fail.","zh":"理解這些心理過程有助解釋預測為何失敗。"},{"en":"The phrase connects forecasting with how the mind works.","zh":"這個短語把預測與頭腦如何運作連繫起來。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":16},{"front":"despite such efforts","meaning":"儘管有這些努力","examples":[{"en":"Despite such efforts, little consensus exists.","zh":"儘管有這些努力，仍然幾乎沒有共識。"},{"en":"Despite such efforts means although people have tried hard in those ways.","zh":"despite such efforts 指雖然人們已用那些方式努力嘗試。"},{"en":"Despite such efforts, the school still could not reduce exam anxiety completely.","zh":"儘管有這些努力，學校仍不能完全減少考試焦慮。"},{"en":"The phrase introduces a disappointing result after serious attempts.","zh":"這個短語在認真嘗試後引出令人失望的結果。"},{"en":"It highlights contrast between effort and outcome.","zh":"它突出努力與結果之間的對比。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":16},{"front":"literature shows","meaning":"文獻顯示","examples":[{"en":"The literature shows little consensus about human bias.","zh":"文獻顯示關於人類偏見幾乎沒有共識。"},{"en":"Literature shows means published research or academic writing indicates something.","zh":"literature shows 指已發表研究或學術文章顯示某事。"},{"en":"The literature shows that sleep affects memory and concentration.","zh":"文獻顯示睡眠影響記憶和專注力。"},{"en":"Referring to the literature makes a claim sound research-based rather than personal.","zh":"引用文獻會令主張聽起來基於研究，而不是個人想法。"},{"en":"The phrase is common in academic discussion.","zh":"這個短語常見於學術討論。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":16},{"front":"little consensus regarding","meaning":"對……幾乎沒有共識","examples":[{"en":"There is little consensus regarding the causes of human bias.","zh":"對人類偏見的成因幾乎沒有共識。"},{"en":"Little consensus regarding something means people largely disagree or have not reached agreement about it.","zh":"little consensus regarding 某事，指人們大多意見不同或尚未達成一致。"},{"en":"There may be little consensus regarding the best way to grade creative writing.","zh":"對評分創意寫作的最佳方式，可能幾乎沒有共識。"},{"en":"When consensus is limited, researchers continue to test different explanations.","zh":"當共識有限，研究人員會繼續測試不同解釋。"},{"en":"The phrase describes lack of agreement on a topic.","zh":"這個短語描述對某主題缺乏一致看法。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":16},{"front":"causes or manifestations","meaning":"成因或表現形式","examples":[{"en":"Researchers disagree about the causes or manifestations of human bias.","zh":"研究人員對人類偏見的成因或表現形式意見不同。"},{"en":"Causes or manifestations are the reasons something happens and the ways it appears.","zh":"causes or manifestations 是某事發生的原因以及它出現的方式。"},{"en":"Doctors may study the causes or manifestations of stress, such as workload and poor sleep.","zh":"醫生可能研究壓力的成因或表現形式，例如工作量和睡眠差。"},{"en":"Understanding causes helps prevention, while understanding manifestations helps recognition.","zh":"理解成因有助預防，而理解表現形式有助辨認。"},{"en":"The phrase covers both origin and outward signs.","zh":"這個短語涵蓋來源和外在跡象。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":17},{"front":"complete the flow-chart below","meaning":"完成以下流程圖","examples":[{"en":"Candidates complete the flow-chart below using words from the passage.","zh":"考生使用文章中的字詞完成以下流程圖。"},{"en":"Complete the flow-chart below means fill in missing words in the diagram that follows.","zh":"complete the flow-chart below 指在下方流程圖中填入缺失字詞。"},{"en":"In a reading test, students complete a flow-chart by locating stages and key terms in the text.","zh":"在閱讀測驗中，學生透過在文章中定位階段和關鍵詞完成流程圖。"},{"en":"If the answer must come from the passage, students should copy the exact wording.","zh":"如果答案必須來自文章，學生應複製原文用字。"},{"en":"The phrase is an instruction for a sequence-based gap-fill task.","zh":"這個短語是關於順序的填空題指示。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":17},{"front":"no more than three words","meaning":"不多於三個詞","examples":[{"en":"Candidates should choose no more than three words from the passage.","zh":"考生應從文章中選擇不多於三個詞。"},{"en":"No more than three words means the answer can contain one, two or three words, but not four.","zh":"no more than three words 指答案可以有一個、兩個或三個詞，但不能有四個。"},{"en":"“Guiding principles” fits this rule because it has two words.","zh":"“Guiding principles” 符合這條規則，因為它有兩個詞。"},{"en":"If students write extra words, the answer may be marked wrong.","zh":"如果學生寫額外字詞，答案可能被判錯。"},{"en":"The phrase gives a strict word limit.","zh":"這個短語給出嚴格字數限制。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":17},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must be taken from the passage.","zh":"答案必須從文章中取得。"},{"en":"From the passage means using the exact information or wording in the reading text.","zh":"from the passage 指使用閱讀文本中的確切資訊或字詞。"},{"en":"In IELTS reading, students should not use outside knowledge when answers must come from the passage.","zh":"在 IELTS 閱讀中，當答案必須來自文章時，學生不應使用外部知識。"},{"en":"This rule prevents students from writing a correct idea in the wrong wording.","zh":"這條規則防止學生用錯誤措辭寫出正確想法。"},{"en":"The phrase reminds candidates to depend on textual evidence.","zh":"這個短語提醒考生依靠文本證據。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":17},{"front":"for each answer","meaning":"每個答案","examples":[{"en":"Candidates write words from the passage for each answer.","zh":"考生每個答案都要寫文章中的字詞。"},{"en":"For each answer means for every blank, question or required response.","zh":"for each answer 指對每個空格、問題或所需回應而言。"},{"en":"A teacher may ask students to give one reason for each answer in a grammar exercise.","zh":"老師可能要求學生在文法練習中為每個答案給一個理由。"},{"en":"If each answer has a separate limit, students must check every blank carefully.","zh":"如果每個答案都有獨立限制，學生必須仔細檢查每個空格。"},{"en":"The phrase applies an instruction to all answers individually.","zh":"這個短語把指示逐一應用到所有答案。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":17},{"front":"stage","meaning":"階段","examples":[{"en":"The flow-chart shows each stage from novice to expert.","zh":"流程圖顯示由初學者到專家的每個階段。"},{"en":"A stage is one step or period in a longer process.","zh":"stage 是較長過程中的一步或一段時期。"},{"en":"A child learning to read moves through stages such as recognising letters and reading sentences.","zh":"孩子學閱讀會經歷辨認字母和閱讀句子等階段。"},{"en":"Understanding stages helps learners see what comes before and after.","zh":"理解階段幫助學習者看見前後次序。"},{"en":"The word describes part of a sequence.","zh":"這個字描述順序中的一部分。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":17},{"front":"characteristics","meaning":"特徵","examples":[{"en":"The flow-chart summarises the characteristics of each stage.","zh":"流程圖總結每個階段的特徵。"},{"en":"Characteristics are the main features that describe what something is like.","zh":"characteristics 是描述某物是怎樣的主要特點。"},{"en":"A good school may have characteristics such as clear rules, supportive teachers and safe classrooms.","zh":"好學校可能有清楚規則、支持學生的老師和安全課室等特徵。"},{"en":"Knowing characteristics helps students distinguish one stage from another.","zh":"知道特徵幫助學生區分一個階段和另一個階段。"},{"en":"The word refers to identifying features.","zh":"這個字指識別性特點。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":17},{"front":"perform a given task","meaning":"執行某項指定任務","examples":[{"en":"A novice needs rules to perform a given task.","zh":"初學者需要規則來執行某項指定任務。"},{"en":"To perform a given task means to carry out a specific activity that has been assigned.","zh":"perform a given task 指執行被指定的特定活動。"},{"en":"A new cashier learns steps to perform a given task such as processing a refund.","zh":"新收銀員學習步驟，以執行處理退款等指定任務。"},{"en":"Clear rules help beginners complete the task with fewer mistakes.","zh":"清楚規則幫助初學者以較少錯誤完成任務。"},{"en":"The phrase focuses on doing one specific job correctly.","zh":"這個短語重點在正確完成某一項具體工作。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":17},{"front":"guided through learning","meaning":"在學習過程中受引導","examples":[{"en":"A novice is guided through learning by a mentor.","zh":"初學者在學習過程中由導師引導。"},{"en":"Guided through learning means helped step by step while acquiring new knowledge or skill.","zh":"guided through learning 指在獲取新知識或技能時，一步一步得到幫助。"},{"en":"A beginner driver is guided through learning by an instructor sitting beside her.","zh":"初學駕駛者由坐在旁邊的教練引導學習。"},{"en":"Guidance helps beginners know what to practise and what mistakes to avoid.","zh":"指導幫助初學者知道要練甚麼，以及要避免哪些錯誤。"},{"en":"The phrase describes supported learning rather than learning alone.","zh":"這個短語描述有支援的學習，而不是獨自學習。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":17},{"front":"identify patterns","meaning":"辨認模式","examples":[{"en":"A journeyman begins to identify patterns within and between cases.","zh":"熟練學習者開始在個案之內和個案之間辨認模式。"},{"en":"To identify patterns means to notice repeated features or relationships across examples.","zh":"identify patterns 指注意到例子中的重複特徵或關係。"},{"en":"A trainee teacher may identify patterns in students’ common writing mistakes.","zh":"見習老師可能辨認學生常見寫作錯誤中的模式。"},{"en":"Seeing patterns helps learners predict problems and choose better methods.","zh":"看見模式幫助學習者預測問題並選擇更好方法。"},{"en":"The phrase describes the move from isolated facts to organised understanding.","zh":"這個短語描述由孤立事實走向有組織理解。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":17},{"front":"difficult problems","meaning":"困難問題","examples":[{"en":"A journeyman contacts a mentor when facing difficult problems.","zh":"熟練學習者面對困難問題時會聯絡導師。"},{"en":"Difficult problems are problems that cannot be solved easily with basic rules.","zh":"difficult problems 是不能用基本規則輕易解決的問題。"},{"en":"A student may ask a tutor for help with difficult problems in algebra.","zh":"學生可能向導師尋求代數困難問題的幫助。"},{"en":"Difficult problems force learners to combine knowledge from several areas.","zh":"困難問題迫使學習者結合幾個範疇的知識。"},{"en":"The phrase refers to challenges that require deeper thinking.","zh":"這個短語指需要更深入思考的挑戰。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":18},{"front":"perform tasks independently","meaning":"獨立執行任務","examples":[{"en":"An expert performs tasks independently without a mentor.","zh":"專家在沒有導師的情況下獨立執行任務。"},{"en":"To perform tasks independently means to complete work without needing constant guidance.","zh":"perform tasks independently 指不需要持續指導也能完成工作。"},{"en":"A senior nurse can perform tasks independently after years of supervised practice.","zh":"高級護士經過多年受監督練習後，可以獨立執行任務。"},{"en":"Independent performance shows that rules and judgement have become internalised.","zh":"獨立表現顯示規則和判斷已內化。"},{"en":"The phrase marks a mature stage of skill.","zh":"這個短語標示技能成熟階段。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":18},{"front":"agree with the information given","meaning":"與所給資料一致","examples":[{"en":"Candidates decide whether statements agree with the information given.","zh":"考生判斷陳述是否與所給資料一致。"},{"en":"Agree with the information given means match what the passage says.","zh":"agree with the information given 指與文章所說內容相符。"},{"en":"In a reading test, an answer agrees with the text only if the text directly supports it.","zh":"在閱讀測驗中，答案只有在文本直接支持時才與文章一致。"},{"en":"If a statement sounds reasonable but is not supported, it may not be correct.","zh":"如果陳述聽起來合理但沒有支持，它未必正確。"},{"en":"The phrase reminds students to judge by evidence, not opinion.","zh":"這個短語提醒學生按證據判斷，而不是按意見。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":18},{"front":"in Reading Passage 2","meaning":"在閱讀文章二中","examples":[{"en":"The statements are based on Reading Passage 2.","zh":"這些陳述基於閱讀文章二。"},{"en":"In Reading Passage 2 means inside the second reading text of the test.","zh":"in Reading Passage 2 指在測驗第二篇閱讀文章之內。"},{"en":"Students should use information in Reading Passage 2, not another article.","zh":"學生應使用閱讀文章二中的資訊，而不是另一篇文章。"},{"en":"This phrase tells candidates where to look for evidence.","zh":"這個短語告訴考生在哪裏尋找證據。"},{"en":"It limits the source of the answer.","zh":"它限制答案來源。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":18},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Candidates write their answers on their answer sheet.","zh":"考生在答題紙上寫答案。"},{"en":"On your answer sheet means in the official place where exam answers must be recorded.","zh":"on your answer sheet 指在考試答案必須記錄的正式位置。"},{"en":"A student may know the answer but lose marks if it is not written on the answer sheet.","zh":"學生可能知道答案，但如果沒有寫在答題紙上，可能失分。"},{"en":"Exam instructions often separate work done on the question paper from final answers.","zh":"考試指示常把題目卷上的草稿與最終答案分開。"},{"en":"The phrase reminds candidates where the answer must appear.","zh":"這個短語提醒考生答案必須出現在哪裏。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":18},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與文章中的資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"contradict the information 指說出與文本內容相反的事情。"},{"en":"If the passage says experts need mentors early on, a statement saying they never need mentors contradicts it.","zh":"如果文章說專家早期需要導師，而陳述說他們從不需要導師，該陳述就與資料矛盾。"},{"en":"Contradiction shows that the statement is false, not merely missing.","zh":"矛盾顯示陳述是錯的，而不只是沒有提及。"},{"en":"The phrase describes direct disagreement with the source.","zh":"這個短語描述與來源直接不一致。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":18},{"front":"there is no information on this","meaning":"文中沒有這方面的資料","examples":[{"en":"The answer is not given if there is no information on this.","zh":"如果文中沒有這方面的資料，答案就是 not given。"},{"en":"There is no information on this means the passage does not say anything about that point.","zh":"there is no information on this 指文章沒有說到該點。"},{"en":"If a text explains expert learning but never mentions age, age-related claims may be not given.","zh":"如果文本解釋專家學習但從未提及年齡，與年齡有關的說法可能是 not given。"},{"en":"Students should not use common sense to fill missing information in this question type.","zh":"學生在這類題型中不應用常識填補缺失資料。"},{"en":"The phrase identifies absence of evidence in the passage.","zh":"這個短語指出文章中缺乏證據。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":18},{"front":"use the same system to","meaning":"使用相同系統去……","examples":[{"en":"The question asks whether novices and experts use the same system to classify objects.","zh":"題目問初學者和專家是否使用相同系統去分類物件。"},{"en":"Use the same system to do something means apply the same method or rules for that action.","zh":"use the same system to do something 指用相同方法或規則去做某事。"},{"en":"Two teachers may use the same system to mark essays if they follow one shared rubric.","zh":"如果兩名老師跟隨同一評分準則，他們可能使用相同系統去改文章。"},{"en":"If beginners and experts use different systems, their classifications may look very different.","zh":"如果初學者和專家使用不同系統，他們的分類可能看起來很不同。"},{"en":"The phrase focuses on whether the method is shared.","zh":"這個短語重點在方法是否共享。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":18},{"front":"classify objects","meaning":"將物件分類","examples":[{"en":"Novices and experts classify objects in different ways.","zh":"初學者和專家以不同方式將物件分類。"},{"en":"To classify objects means to sort items into groups according to chosen features.","zh":"classify objects 指根據選定特徵把物件分組。"},{"en":"Children may classify objects by colour, while scientists may classify them by function.","zh":"孩子可能按顏色將物件分類，而科學家可能按功能分類。"},{"en":"Classification reveals what features a person thinks are important.","zh":"分類方式揭示一個人認為哪些特徵重要。"},{"en":"The phrase describes organising items into categories.","zh":"這個短語描述把物件組織成類別。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":18},{"front":"be focused on","meaning":"集中於……","examples":[{"en":"The question asks whether a novice’s training is focused on memory skills.","zh":"題目問初學者的訓練是否集中於記憶技巧。"},{"en":"To be focused on something means to give most attention to that thing.","zh":"be focused on 某事，指把大部分注意力放在該事上。"},{"en":"A beginner course may be focused on basic grammar before essay writing begins.","zh":"初級課程可能在開始寫文章前集中於基本文法。"},{"en":"If training is focused only on memory, learners may not develop judgement.","zh":"如果訓練只集中於記憶，學習者可能不能發展判斷力。"},{"en":"The phrase describes the main centre of attention.","zh":"這個短語描述主要注意中心。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":18},{"front":"memory skills","meaning":"記憶技巧","examples":[{"en":"Domain-specific memory is stronger in experts.","zh":"專家的領域專屬記憶較強。"},{"en":"Memory skills are abilities used to store, recall and organise information.","zh":"memory skills 是用來儲存、回想和組織資訊的能力。"},{"en":"A student improves memory skills by reviewing vocabulary regularly and using examples.","zh":"學生透過定期溫習詞彙和使用例子來改善記憶技巧。"},{"en":"Strong memory skills help learners retrieve information quickly when solving problems.","zh":"強記憶技巧幫助學習者在解決問題時快速提取資訊。"},{"en":"The phrase refers to remembering effectively, not only memorising blindly.","zh":"這個短語指有效記憶，而不只是盲目背誦。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":19},{"front":"in their own fields","meaning":"在自己的領域中","examples":[{"en":"Experts solve problems efficiently in their own fields.","zh":"專家在自己的領域中有效解決問題。"},{"en":"In their own fields means inside the areas where they have special training and experience.","zh":"in their own fields 指在他們有專門訓練和經驗的範疇內。"},{"en":"A dentist is expert in her own field but may not know how to repair a car.","zh":"牙醫在自己的領域中是專家，但未必知道如何修車。"},{"en":"Expertise works best when the problem belongs to the expert’s field.","zh":"當問題屬於專家的領域，專業能力最有效。"},{"en":"The phrase limits the claim to the expert’s special area.","zh":"這個短語把主張限制在專家的專門範疇。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":19},{"front":"more efficiently than","meaning":"比……更有效率","examples":[{"en":"Experts solve problems more efficiently than novices.","zh":"專家比初學者更有效率地解決問題。"},{"en":"More efficiently than means using less time, effort or waste than someone else.","zh":"more efficiently than 指比另一人使用更少時間、努力或浪費。"},{"en":"An experienced cook prepares dinner more efficiently than a beginner because she knows the order of steps.","zh":"有經驗的廚師比初學者更有效率地準備晚餐，因為她知道步驟次序。"},{"en":"Efficiency improves when people know what details matter most.","zh":"當人們知道哪些細節最重要，效率會提升。"},{"en":"The phrase compares how well resources are used.","zh":"這個短語比較資源使用得有多好。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":19},{"front":"when faced with","meaning":"當面對……時","examples":[{"en":"When faced with a problem, novices often seek solutions quickly.","zh":"當面對問題時，初學者常快速尋找解決方案。"},{"en":"When faced with something means when someone has to deal with that situation.","zh":"when faced with 某事，指當某人必須處理該情況時。"},{"en":"When faced with a difficult question, a student should read it twice before answering.","zh":"當面對困難題目時，學生應先讀兩次再回答。"},{"en":"The phrase introduces the situation that triggers someone’s response.","zh":"這個短語引出引發某人反應的情況。"},{"en":"It is useful for explaining behaviour under pressure.","zh":"它適合用來解釋壓力下的行為。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":19},{"front":"try to solve it immediately","meaning":"嘗試立即解決它","examples":[{"en":"A novice may try to solve a problem immediately.","zh":"初學者可能嘗試立即解決問題。"},{"en":"To try to solve it immediately means to look for an answer at once without much preparation.","zh":"try to solve it immediately 指在沒有充分準備下立刻尋找答案。"},{"en":"A student may rush to answer a reading question before understanding the paragraph.","zh":"學生可能在理解段落前就急着回答閱讀題。"},{"en":"Acting too quickly can lead to wrong solutions if the problem is not understood.","zh":"如果問題未被理解，太快行動可能導致錯誤解方。"},{"en":"The phrase describes quick action that may be premature.","zh":"這個短語描述可能過早的快速行動。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":19},{"front":"recognise their own mistakes and limits","meaning":"辨認自己的錯誤和限制","examples":[{"en":"Experts are better at recognising their own mistakes and limits.","zh":"專家較善於辨認自己的錯誤和限制。"},{"en":"To recognise their own mistakes and limits means to notice errors and know where their knowledge stops.","zh":"recognise their own mistakes and limits 指注意錯誤並知道自己知識在哪裏停止。"},{"en":"A good teacher admits when she needs to check a grammar point before answering.","zh":"好老師在回答前需要查核文法點時會承認。"},{"en":"Recognising limits helps people ask for evidence or expert help when needed.","zh":"辨認限制幫助人在需要時尋求證據或專家協助。"},{"en":"The phrase describes self-awareness, not weakness.","zh":"這個短語描述自我覺察，而不是弱點。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":19},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Candidates complete the summary below using words from the passage.","zh":"考生使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the short text that follows.","zh":"complete the summary below 指在下方短文中填入缺失字詞。"},{"en":"Students should read around each blank to decide what grammar and meaning are needed.","zh":"學生應閱讀每個空格前後內容，以判斷需要甚麼文法和意思。"},{"en":"Summary completion tests both understanding and accurate word choice.","zh":"摘要填空同時測試理解和準確選詞。"},{"en":"The phrase is a common reading-test instruction.","zh":"這個短語是常見閱讀測驗指示。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":19},{"front":"no more than two words","meaning":"不多於兩個詞","examples":[{"en":"Candidates should choose no more than two words from the passage.","zh":"考生應從文章中選擇不多於兩個詞。"},{"en":"No more than two words means the answer can contain one or two words, but not three.","zh":"no more than two words 指答案可以有一個或兩個詞，但不能有三個。"},{"en":"“Mental models” fits this rule because it contains two words.","zh":"“Mental models” 符合這條規則，因為它包含兩個詞。"},{"en":"Extra words can make an answer wrong even if the key idea is present.","zh":"即使有關鍵意思，額外字詞也可能令答案錯。"},{"en":"The phrase gives a strict answer-length limit.","zh":"這個短語給出嚴格答案長度限制。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":19},{"front":"solve problems effectively","meaning":"有效解決問題","examples":[{"en":"Experts solve problems effectively within their domains.","zh":"專家在其領域內有效解決問題。"},{"en":"To solve problems effectively means to find answers that work well and avoid unnecessary mistakes.","zh":"solve problems effectively 指找出有效答案並避免不必要錯誤。"},{"en":"A mechanic solves engine problems effectively when he identifies the real cause quickly.","zh":"機械師快速找出真正原因時，就是有效解決引擎問題。"},{"en":"Effective problem-solving saves time and prevents repeated failure.","zh":"有效解難節省時間並防止重複失敗。"},{"en":"The phrase describes successful, practical solving rather than random guessing.","zh":"這個短語描述成功而實際的解決，而不是隨機猜測。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":19},{"front":"within their domains","meaning":"在其領域內","examples":[{"en":"Experts are strongest within their domains.","zh":"專家在其領域內最強。"},{"en":"Within their domains means inside the fields where experts have special knowledge and experience.","zh":"within their domains 指在專家有專門知識和經驗的領域之內。"},{"en":"A chess expert is strongest within chess, not necessarily in business forecasting.","zh":"國際象棋專家在棋藝領域內最強，不一定在商業預測中最強。"},{"en":"Domain limits explain why experts may fail outside familiar areas.","zh":"領域限制解釋為何專家可能在熟悉範圍外失敗。"},{"en":"The phrase reminds readers that expertise has boundaries.","zh":"這個短語提醒讀者專業能力有界限。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":19},{"front":"work against them","meaning":"對他們造成反作用","examples":[{"en":"The strengths of expertise can work against experts.","zh":"專業知識的優勢可以對專家造成反作用。"},{"en":"To work against someone means to become a disadvantage or create difficulty for them.","zh":"work against someone 指變成對某人不利或為某人造成困難。"},{"en":"A student’s confidence can work against her if it stops her from checking answers.","zh":"如果信心令學生停止檢查答案，信心可以對她造成反作用。"},{"en":"Expert habits can work against experts when new problems do not fit old patterns.","zh":"當新問題不符合舊模式，專家習慣可能對專家造成反作用。"},{"en":"The phrase shows that a strength can turn into a weakness.","zh":"這個短語顯示優勢可以轉化為弱點。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":20},{"front":"studies show that","meaning":"研究顯示","examples":[{"en":"Studies show that experts may be poor forecasters.","zh":"研究顯示專家可能是不佳預測者。"},{"en":"Studies show that means research evidence indicates something.","zh":"studies show that 指研究證據顯示某事。"},{"en":"Studies show that regular sleep can improve memory and concentration.","zh":"研究顯示定期睡眠可以改善記憶和專注力。"},{"en":"This phrase supports a claim with research rather than personal opinion.","zh":"這個短語用研究而非個人意見支持主張。"},{"en":"It is useful in academic writing when evidence matters.","zh":"當證據重要時，它適合用於學術寫作。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":20},{"front":"attribute the problem to","meaning":"將問題歸因於……","examples":[{"en":"Some researchers attribute the problem to human biases.","zh":"一些研究人員將問題歸因於人類偏見。"},{"en":"To attribute the problem to something means to say that thing is the cause.","zh":"attribute the problem to 某事，指說該事是原因。"},{"en":"A teacher may attribute poor results to lack of practice rather than low ability.","zh":"老師可能把差成績歸因於缺乏練習，而不是能力低。"},{"en":"Identifying the cause affects what solution people choose.","zh":"找出原因會影響人們選擇甚麼解決方法。"},{"en":"The phrase describes explaining where a problem comes from.","zh":"這個短語描述解釋問題來自哪裏。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":20},{"front":"causes or manifestations of","meaning":"……的成因或表現形式","examples":[{"en":"Researchers disagree about the causes or manifestations of bias.","zh":"研究人員對偏見的成因或表現形式意見不同。"},{"en":"Causes or manifestations of something are its reasons and the ways it appears.","zh":"causes or manifestations of 某事，是它的原因以及它出現的方式。"},{"en":"A doctor may study the causes or manifestations of anxiety, such as stress and poor sleep.","zh":"醫生可能研究焦慮的成因或表現形式，例如壓力和睡眠差。"},{"en":"Knowing causes helps prevent a problem, while knowing manifestations helps recognise it.","zh":"知道成因有助預防問題，而知道表現形式有助辨認它。"},{"en":"The phrase covers both origin and visible signs.","zh":"這個短語涵蓋來源和可見跡象。"}],"source":"40 - From A Novice to An Expert.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 41":[{"front":"Antarctica—In from the Cold?","meaning":"南極洲：走出寒冷印象？","examples":[{"en":"The passage Antarctica—In from the Cold? discusses how our understanding of Antarctica has changed.","zh":"文章《南極洲：走出寒冷印象？》討論我們對南極洲的理解如何改變。"},{"en":"“Antarctica—In from the Cold?” suggests that Antarctica is no longer seen only as a frozen, distant place.","zh":"“Antarctica—In from the Cold?” 暗示南極洲不再只被視為冰冷而遙遠的地方。"},{"en":"A museum exhibition called “Dinosaurs—Back to Life?” might show how new science changes old ideas about dinosaurs.","zh":"一個名為「恐龍：重回生命？」的博物館展覽，可能展示新科學如何改變人們對恐龍的舊觀念。"},{"en":"The question mark suggests that the writer is inviting readers to reconsider an old image.","zh":"問號表示作者在邀請讀者重新思考舊有形象。"},{"en":"This title points to a change in perception, not a physical escape from cold weather.","zh":"這個標題指出看法上的改變，而不是實際從寒冷天氣中逃出來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":1},{"front":"a little over a century ago","meaning":"一個多世紀前","examples":[{"en":"A little over a century ago, explorers battled against Antarctica’s extreme conditions.","zh":"一個多世紀前，探險家與南極洲的極端環境搏鬥。"},{"en":"A little over a century ago means slightly more than one hundred years ago.","zh":"a little over a century ago 指稍多於一百年前。"},{"en":"A little over a century ago, many families still travelled long distances by ship rather than by plane.","zh":"一個多世紀前，許多家庭仍乘船長途旅行，而不是乘飛機。"},{"en":"This phrase helps readers place an event in the fairly distant past.","zh":"這個短語幫助讀者把事件放在相當久遠的過去。"},{"en":"It is less exact than giving a year, but it still gives a clear historical period.","zh":"它不像年份那樣精確，但仍給出清楚的歷史時期。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":1},{"front":"men of the ilk of","meaning":"像……這類人物","examples":[{"en":"Men of the ilk of Scott, Shackleton and Mawson explored Antarctica.","zh":"像 Scott、Shackleton 和 Mawson 這類人物曾探索南極洲。"},{"en":"Men of the ilk of someone means men of the same type, character, or reputation as that person.","zh":"men of the ilk of someone 指與某人同類型、同品格或同名聲的人。"},{"en":"A school may honour teachers of the ilk of its founder, who were brave, patient, and deeply committed.","zh":"學校可能表揚像創校人這類勇敢、有耐性且非常投入的老師。"},{"en":"This phrase is often used when naming impressive examples of a wider group.","zh":"這個短語常用於列舉某個更大群體中的傑出例子。"},{"en":"It sounds formal and slightly old-fashioned, so it suits historical writing.","zh":"它聽起來正式且略帶舊式，因此適合歷史寫作。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":1},{"front":"battle against","meaning":"與……搏鬥；對抗","examples":[{"en":"Early explorers battled against Antarctica’s blizzards, cold and deprivation.","zh":"早期探險家與南極洲的暴風雪、寒冷和匱乏搏鬥。"},{"en":"To battle against something means to struggle hard against a difficult force, problem, or condition.","zh":"battle against something 指努力對抗困難力量、問題或環境。"},{"en":"Doctors may battle against a disease when they work day and night to save patients.","zh":"醫生日以繼夜拯救病人時，可能是在與疾病搏鬥。"},{"en":"If students battle against tiredness, they try to keep studying even when they feel exhausted.","zh":"如果學生與疲倦搏鬥，他們即使筋疲力盡仍努力溫習。"},{"en":"This phrase suggests effort, danger, and resistance.","zh":"這個短語帶有努力、危險和抗爭的意思。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":1},{"front":"blizzards, cold and deprivation","meaning":"暴風雪、寒冷和匱乏","examples":[{"en":"Explorers faced blizzards, cold and deprivation in Antarctica.","zh":"探險家在南極洲面對暴風雪、寒冷和匱乏。"},{"en":"Blizzards, cold and deprivation are severe snowstorms, freezing temperatures, and lack of basic needs.","zh":"blizzards, cold and deprivation 指嚴重暴雪、冰冷氣溫，以及基本需要不足。"},{"en":"A mountain rescue team may face cold and deprivation if food, shelter, and warmth are limited.","zh":"如果食物、庇護和保暖有限，山區救援隊可能面對寒冷和匱乏。"},{"en":"Such conditions can make travel dangerous because people lose energy and body heat quickly.","zh":"這類環境會令旅程危險，因為人會快速失去能量和體溫。"},{"en":"This phrase describes extreme hardship, not ordinary bad weather.","zh":"這個短語描述極端艱辛，而不是普通壞天氣。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":1},{"front":"in the name of","meaning":"以……的名義","examples":[{"en":"They explored Antarctica in the name of Empire.","zh":"他們以帝國的名義探索南極洲。"},{"en":"In the name of something means for the stated purpose, honour, or authority of that thing.","zh":"in the name of something 指以某事物所聲稱的目的、榮譽或權威為名。"},{"en":"A charity may collect donations in the name of helping homeless families.","zh":"慈善機構可能以幫助無家者家庭的名義籌款。"},{"en":"People sometimes take great risks in the name of science, national pride, or duty.","zh":"人們有時以科學、民族自豪或責任的名義冒很大風險。"},{"en":"This phrase explains the cause or ideal used to justify an action.","zh":"這個短語解釋用來合理化行動的原因或理想。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":1},{"front":"an age of heroic deeds","meaning":"英雄壯舉的年代","examples":[{"en":"The explorers lived in an age of heroic deeds.","zh":"這些探險家生活在英雄壯舉的年代。"},{"en":"An age of heroic deeds is a period when brave and difficult actions are admired.","zh":"age of heroic deeds 指英勇而艱難行動受到敬仰的時期。"},{"en":"A country may describe wartime rescue missions as part of an age of heroic deeds.","zh":"一個國家可能把戰時救援任務描述為英雄壯舉年代的一部分。"},{"en":"Such language makes people focus on courage, sacrifice, and honour.","zh":"這類語言令人集中於勇氣、犧牲和榮譽。"},{"en":"This phrase sounds grand and historical rather than casual.","zh":"這個短語聽起來宏大而有歷史感，不是日常口語。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":1},{"front":"create an image of","meaning":"塑造……的形象","examples":[{"en":"They created an image of Antarctica that lasted for decades.","zh":"他們塑造了一個延續數十年的南極洲形象。"},{"en":"To create an image of something means to shape how people imagine or understand it.","zh":"create an image of something 指塑造人們如何想像或理解某事物。"},{"en":"A school website can create an image of the school as friendly, modern, and caring.","zh":"學校網站可以塑造學校友善、現代和關愛的形象。"},{"en":"Repeated stories and pictures can create an image that lasts even after reality changes.","zh":"反覆出現的故事和圖片可以塑造一種即使現實改變後仍延續的形象。"},{"en":"This phrase refers to public perception, not only a literal picture.","zh":"這個短語指公眾印象，而不只是字面上的圖片。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":1},{"front":"last well into","meaning":"一直延續至……很久","examples":[{"en":"The old image of Antarctica lasted well into the 20th century.","zh":"南極洲的舊形象一直延續至二十世紀很久。"},{"en":"To last well into a period means to continue for a long time after that period has begun.","zh":"last well into a period 指在某時期開始後仍持續很長時間。"},{"en":"A school tradition that began in the 1800s may last well into the modern age.","zh":"始於十九世紀的學校傳統，可能一直延續至現代很久。"},{"en":"If an idea lasts well into a new century, it remains influential for longer than expected.","zh":"如果一個想法一直延續至新世紀很久，它的影響比預期更長。"},{"en":"This phrase emphasises continuation over a long period.","zh":"這個短語強調長時間的延續。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":1},{"front":"remoteness, hardship, bleakness and isolation","meaning":"偏遠、艱辛、荒涼和孤立","examples":[{"en":"Antarctica was associated with remoteness, hardship, bleakness and isolation.","zh":"南極洲曾與偏遠、艱辛、荒涼和孤立聯繫起來。"},{"en":"Remoteness, hardship, bleakness and isolation describe being far away, difficult to survive in, empty-looking, and cut off from others.","zh":"remoteness, hardship, bleakness and isolation 描述地方遙遠、難以生存、看似空曠荒涼，並與他人隔絕。"},{"en":"A remote mountain village in winter may feel full of hardship and isolation if roads are blocked.","zh":"如果道路被封，冬季偏遠山村可能充滿艱辛和孤立感。"},{"en":"These qualities can make a place seem frightening, lonely, and unsuitable for ordinary life.","zh":"這些特質可以令一個地方顯得可怕、孤單，並不適合日常生活。"},{"en":"This phrase creates a harsh and lonely image.","zh":"這個短語塑造出嚴酷而孤寂的形象。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":1},{"front":"the province of","meaning":"……的專屬領域","examples":[{"en":"Antarctica was seen as the province of only the most courageous men.","zh":"南極洲曾被視為只有最勇敢男性的專屬領域。"},{"en":"The province of a group means an area, activity, or field thought to belong mainly to that group.","zh":"province of a group 指被認為主要屬於某群體的地方、活動或領域。"},{"en":"Advanced surgery was once seen as the province of highly specialised doctors only.","zh":"進階外科手術曾被視為只有高度專門醫生的領域。"},{"en":"When something is seen as the province of experts, ordinary people may feel excluded.","zh":"當某事被視為專家專屬領域，普通人可能感到被排除在外。"},{"en":"This phrase means “the special domain of”.","zh":"這個短語意思是「某群體的特殊領域」。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":2},{"front":"the most courageous of men","meaning":"最勇敢的人","examples":[{"en":"The continent was thought to be suitable only for the most courageous of men.","zh":"人們曾認為這片大陸只適合最勇敢的人。"},{"en":"The most courageous of men means men with exceptional bravery.","zh":"most courageous of men 指具備非凡勇氣的男性。"},{"en":"A dangerous rescue in a burning building may require the most courageous of firefighters.","zh":"在燃燒建築中進行危險救援，可能需要最勇敢的消防員。"},{"en":"This phrase suggests that only unusually brave people can face the challenge.","zh":"這個短語表示只有異常勇敢的人才能面對挑戰。"},{"en":"It has an old-fashioned tone because it focuses on male heroism.","zh":"它帶有舊式語氣，因為它集中於男性英雄主義。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":2},{"front":"be removed from everyday reality","meaning":"遠離日常現實","examples":[{"en":"Antarctica was imagined as a place removed from everyday reality.","zh":"南極洲曾被想像成一個遠離日常現實的地方。"},{"en":"To be removed from everyday reality means to feel far away from normal daily life.","zh":"be removed from everyday reality 指感覺遠離正常日常生活。"},{"en":"A luxury hotel on a private island may feel removed from everyday reality.","zh":"私人島上的豪華酒店可能令人感到遠離日常現實。"},{"en":"When a place is extremely remote and difficult, people may imagine it as almost unreal.","zh":"當一個地方極端偏遠且艱難，人們可能把它想像得幾乎不真實。"},{"en":"This phrase describes psychological distance, not just physical distance.","zh":"這個短語描述心理距離，而不只是實際距離。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":2},{"front":"no apparent value to","meaning":"對……沒有明顯價值","examples":[{"en":"Antarctica was seen as a place with no apparent value to anyone.","zh":"南極洲曾被視為一個對任何人都沒有明顯價值的地方。"},{"en":"No apparent value to someone means no clear or obvious usefulness for that person or group.","zh":"no apparent value to someone 指對某人或某群體沒有清楚或明顯用途。"},{"en":"An old machine may seem to have no apparent value to a student until a teacher explains its history.","zh":"一部舊機器對學生可能看似沒有明顯價值，直到老師解釋其歷史。"},{"en":"Something can appear useless when people do not yet understand its hidden importance.","zh":"當人們尚未理解隱藏重要性，某事物可能看起來無用。"},{"en":"This phrase means “seemingly not useful”, not “definitely worthless”.","zh":"這個短語意思是「看似沒有用」，而不是「肯定毫無價值」。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":2},{"front":"enter the 21st century","meaning":"進入二十一世紀","examples":[{"en":"As we enter the 21st century, our perception of Antarctica has changed.","zh":"隨着我們進入二十一世紀，我們對南極洲的看法已經改變。"},{"en":"To enter the 21st century means to move into the period beginning in the year 2001.","zh":"enter the 21st century 指進入由 2001 年開始的時期。"},{"en":"As schools entered the 21st century, computers became more common in classrooms.","zh":"隨着學校進入二十一世紀，電腦在課室中變得更常見。"},{"en":"This phrase often introduces modern changes in thinking, technology, or society.","zh":"這個短語常引入思想、科技或社會方面的現代變化。"},{"en":"It contrasts older views with newer ones.","zh":"它把舊觀點與新觀點作對比。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":2},{"front":"our perception of","meaning":"我們對……的看法","examples":[{"en":"Our perception of Antarctica has changed.","zh":"我們對南極洲的看法已經改變。"},{"en":"Our perception of something is the way we see, understand, or think about it.","zh":"our perception of something 指我們如何看待、理解或思考某事物。"},{"en":"A student’s perception of exams may change after learning better study methods.","zh":"學生學會更好的溫習方法後，對考試的看法可能改變。"},{"en":"New information can change perception because people notice importance they missed before.","zh":"新資料可以改變看法，因為人們會注意到以前忽略的重要性。"},{"en":"This phrase focuses on viewpoint rather than the object itself.","zh":"這個短語著重觀點，而不是事物本身。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":2},{"front":"physically no closer","meaning":"在地理上並沒有更接近","examples":[{"en":"Antarctica is physically no closer than before.","zh":"南極洲在地理上並沒有比以前更接近。"},{"en":"Physically no closer means the actual distance has not become shorter.","zh":"physically no closer 指實際距離沒有變短。"},{"en":"A friend living overseas may feel emotionally closer through video calls, though physically no closer.","zh":"住在海外的朋友可能因視像通話而感覺情感上更親近，雖然地理上並沒有更接近。"},{"en":"Technology can change our sense of distance without changing real geography.","zh":"科技可以改變我們對距離的感覺，但不改變真實地理。"},{"en":"This phrase separates physical distance from mental or social closeness.","zh":"這個短語把實際距離與心理或社交親近感分開。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":2},{"front":"probably no warmer","meaning":"很可能並沒有更暖","examples":[{"en":"Antarctica is probably no warmer than before.","zh":"南極洲很可能並沒有比以前更暖。"},{"en":"Probably no warmer means likely not warmer, though the speaker leaves some room for uncertainty.","zh":"probably no warmer 指很可能沒有更暖，但說話者仍留有一些不確定性。"},{"en":"A room may be probably no warmer after opening a window on a cold day.","zh":"在寒冷日子打開窗後，房間很可能並沒有更暖。"},{"en":"This phrase shows cautious judgement rather than complete certainty.","zh":"這個短語顯示謹慎判斷，而不是完全肯定。"},{"en":"It is useful when comparing present conditions with past conditions.","zh":"它適合用於比較現在與過去的情況。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":2},{"front":"spending time there","meaning":"在那裏逗留","examples":[{"en":"Spending time there still demands great dedication.","zh":"在那裏逗留仍需要很大的奉獻精神。"},{"en":"Spending time there means staying or living in that place for a period.","zh":"spending time there 指在某地停留或生活一段時間。"},{"en":"Spending time in a hospital ward can teach medical students how patients really feel.","zh":"在醫院病房逗留可以教醫科學生了解病人真正感受。"},{"en":"In difficult places, simply spending time there can require preparation and mental strength.","zh":"在艱難地方，單是在那裏逗留也可能需要準備和心理力量。"},{"en":"This phrase is broader than visiting briefly.","zh":"這個短語比短暫到訪更廣泛。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":2},{"front":"demand a dedication","meaning":"需要一種奉獻精神","examples":[{"en":"Spending time in Antarctica still demands a dedication not seen in ordinary life.","zh":"在南極洲逗留仍需要一種日常生活中不常見的奉獻精神。"},{"en":"To demand a dedication means to require strong commitment, effort, and willingness to sacrifice comfort.","zh":"demand a dedication 指需要強烈投入、努力，以及犧牲舒適的意願。"},{"en":"Training for a medical career demands dedication because students work long hours for many years.","zh":"醫學職業訓練需要奉獻精神，因為學生多年來要長時間工作。"},{"en":"Harsh conditions demand dedication because people must keep going when life is uncomfortable.","zh":"嚴酷環境需要奉獻精神，因為人們在生活不舒服時仍要堅持。"},{"en":"This phrase shows that ordinary effort is not enough.","zh":"這個短語顯示普通努力並不足夠。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":2},{"front":"ordinary life","meaning":"日常生活","examples":[{"en":"Life in Antarctica demands dedication not seen in ordinary life.","zh":"南極洲生活需要日常生活中不常見的奉獻精神。"},{"en":"Ordinary life means normal daily life, with familiar routines, comforts, and problems.","zh":"ordinary life 指正常日常生活，包括熟悉的習慣、舒適和問題。"},{"en":"In ordinary life, most people do not need to worry about survival in extreme cold.","zh":"在日常生活中，大多數人不需要擔心在極寒中生存。"},{"en":"Comparing Antarctica with ordinary life highlights how unusual the conditions are.","zh":"把南極洲與日常生活比較，可以突出當地環境有多不尋常。"},{"en":"This phrase refers to everyday experience rather than adventure or crisis.","zh":"這個短語指日常經驗，而不是冒險或危機。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":3},{"front":"surrounding ocean","meaning":"周邊海洋","examples":[{"en":"The continent and its surrounding ocean are central to the Earth System.","zh":"這片大陸及其周邊海洋對地球系統至關重要。"},{"en":"A surrounding ocean is the ocean around a landmass.","zh":"surrounding ocean 指圍繞某陸地的海洋。"},{"en":"Islands depend heavily on their surrounding ocean for food, transport, and weather patterns.","zh":"島嶼高度依賴其周邊海洋來獲取食物、交通和天氣模式。"},{"en":"The ocean around a continent can affect temperature, winds, and marine life.","zh":"大陸周邊海洋可以影響溫度、風和海洋生物。"},{"en":"This phrase links land with the water around it.","zh":"這個短語把陸地與其周圍水域連繫起來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":3},{"front":"increasingly seen to be","meaning":"越來越被視為","examples":[{"en":"Antarctica is increasingly seen to be an integral part of Planet Earth.","zh":"南極洲越來越被視為地球不可或缺的一部分。"},{"en":"Increasingly seen to be means more and more people now understand or regard something in a particular way.","zh":"increasingly seen to be 指越來越多人以某種方式理解或看待某事物。"},{"en":"Sleep is increasingly seen to be essential for learning, not just rest.","zh":"睡眠越來越被視為學習所必需，而不只是休息。"},{"en":"New research can make an old topic increasingly seen to be important.","zh":"新研究可以令舊議題越來越被視為重要。"},{"en":"This phrase shows a gradual change in public or scientific understanding.","zh":"這個短語顯示公眾或科學理解逐漸改變。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":3},{"front":"an integral part of","meaning":"……不可或缺的一部分","examples":[{"en":"Antarctica is an integral part of Planet Earth.","zh":"南極洲是地球不可或缺的一部分。"},{"en":"An integral part of something is a necessary part that helps the whole system work.","zh":"integral part of something 指幫助整個系統運作的必要部分。"},{"en":"Clean water is an integral part of public health.","zh":"清潔食水是公共健康不可或缺的一部分。"},{"en":"If an integral part is damaged, the whole system may be affected.","zh":"如果不可或缺的部分受損，整個系統可能受影響。"},{"en":"This phrase means “essential part”, not just “nearby part”.","zh":"這個短語意思是「必要部分」，而不只是「附近部分」。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":3},{"front":"Planet Earth","meaning":"地球","examples":[{"en":"Antarctica is now seen as an important part of Planet Earth.","zh":"南極洲現在被視為地球的重要部分。"},{"en":"Planet Earth means the Earth considered as one whole planet and living system.","zh":"Planet Earth 指把地球視為一整個行星和生命系統。"},{"en":"A science lesson about Planet Earth may include oceans, forests, deserts, ice, and atmosphere.","zh":"關於地球的科學課可能包括海洋、森林、沙漠、冰和大氣。"},{"en":"Thinking about Planet Earth as a whole helps people see connections between distant places.","zh":"把地球視為一個整體，可以幫助人看見遙遠地方之間的連繫。"},{"en":"This phrase sounds broader and more global than simply “the Earth”.","zh":"這個短語比簡單說 “the Earth” 更有整體和全球意味。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":3},{"front":"a key component in","meaning":"……中的關鍵組成部分","examples":[{"en":"Antarctica is a key component in the Earth System.","zh":"南極洲是地球系統中的關鍵組成部分。"},{"en":"A key component in something is an important part that strongly affects how the whole system works.","zh":"key component in something 指強烈影響整個系統如何運作的重要部分。"},{"en":"Teachers are a key component in a successful school system.","zh":"老師是成功學校制度中的關鍵組成部分。"},{"en":"If a key component fails, the whole system may become weaker.","zh":"如果關鍵組成部分失效，整個系統可能變弱。"},{"en":"This phrase is useful when explaining complex systems.","zh":"這個短語適合用於解釋複雜系統。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":3},{"front":"the Earth System","meaning":"地球系統","examples":[{"en":"Antarctica plays a central role in the Earth System.","zh":"南極洲在地球系統中扮演核心角色。"},{"en":"The Earth System means the connected system of land, ocean, ice, atmosphere, climate, and life on Earth.","zh":"Earth System 指地球上的土地、海洋、冰、大氣、氣候和生命所構成的互聯系統。"},{"en":"A change in the ocean can affect the Earth System by changing weather and ecosystems.","zh":"海洋變化可以透過改變天氣和生態系統來影響地球系統。"},{"en":"Studying the Earth System helps scientists understand links between distant regions.","zh":"研究地球系統幫助科學家理解遙遠地區之間的連繫。"},{"en":"This phrase treats Earth as an interconnected whole.","zh":"這個短語把地球視為互相連接的整體。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":3},{"front":"a little smaller these days","meaning":"如今似乎小了一點","examples":[{"en":"The world seems a little smaller these days because of media and travel.","zh":"由於媒體和旅遊，世界如今似乎小了一點。"},{"en":"A little smaller these days means the world feels more connected and less distant than before.","zh":"a little smaller these days 指世界感覺比以前更互相連接、不那麼遙遠。"},{"en":"Because of video calls, overseas relatives may feel a little closer these days.","zh":"由於視像通話，海外親戚如今可能感覺近了一點。"},{"en":"Travel, television, and the internet can make distant places feel more familiar.","zh":"旅遊、電視和互聯網可以令遙遠地方感覺更熟悉。"},{"en":"This phrase describes a change in experience, not the actual size of Earth.","zh":"這個短語描述經驗上的改變，而不是地球實際大小。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":3},{"front":"be shrunk by","meaning":"被……縮小","examples":[{"en":"The world has been shrunk by TV and tourism.","zh":"世界被電視和旅遊縮小了。"},{"en":"To be shrunk by something means to be made to feel smaller or less distant because of it.","zh":"be shrunk by something 指因某事而令人感覺變小或不再遙遠。"},{"en":"The distance between friends can be shrunk by daily messages and video calls.","zh":"每日訊息和視像通話可以縮短朋友之間的距離感。"},{"en":"Media can shrink the world by showing people places they have never visited.","zh":"媒體可以透過展示人們從未到訪的地方來縮小世界感。"},{"en":"This phrase is metaphorical, not about actual physical shrinking.","zh":"這個短語是比喻，不是實際物理縮小。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":3},{"front":"occupy a central spot","meaning":"佔據中心位置","examples":[{"en":"Antarctica may occupy a central spot on Earth’s mantle.","zh":"南極洲可能佔據地幔上的中心位置。"},{"en":"To occupy a central spot means to be located in an important or central position.","zh":"occupy a central spot 指位於重要或中心位置。"},{"en":"The library occupies a central spot on campus, so students pass it every day.","zh":"圖書館佔據校園中心位置，所以學生每天都會經過。"},{"en":"A central position can make a place more important in a system.","zh":"中心位置可以令一個地方在系統中更重要。"},{"en":"This phrase can refer to physical location or symbolic importance.","zh":"這個短語可以指實際位置，也可以指象徵重要性。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":3},{"front":"Earth’s mantle","meaning":"地幔","examples":[{"en":"Antarctica occupies a central spot on Earth’s mantle.","zh":"南極洲佔據地幔上的中心位置。"},{"en":"Earth’s mantle is the thick layer of rock beneath the Earth’s crust.","zh":"Earth’s mantle 指地殼下方厚厚的岩石層。"},{"en":"A geography class may study Earth’s mantle when learning about volcanoes and plate movement.","zh":"地理課學習火山和板塊運動時，可能會研究地幔。"},{"en":"Movements deep in the mantle can affect the surface over very long periods.","zh":"地幔深處的運動可以在非常長時間內影響地表。"},{"en":"This phrase refers to a deep layer of the planet, not the land surface.","zh":"這個短語指地球深層，而不是陸地表面。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":4},{"front":"scientific research","meaning":"科學研究","examples":[{"en":"Scientific research has revealed Antarctica’s global importance.","zh":"科學研究揭示了南極洲的全球重要性。"},{"en":"Scientific research is careful study based on evidence, observation, and testing.","zh":"scientific research 指基於證據、觀察和測試的仔細研究。"},{"en":"Scientific research can help doctors know which treatment works best.","zh":"科學研究可以幫助醫生知道哪種治療最有效。"},{"en":"Good research can change public understanding by replacing old assumptions with evidence.","zh":"良好研究可以用證據取代舊假設，從而改變公眾理解。"},{"en":"This phrase refers to systematic investigation, not casual opinion.","zh":"這個短語指有系統的調查，而不是隨便意見。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":4},{"front":"during the past half century","meaning":"在過去半個世紀","examples":[{"en":"Research during the past half century has changed our view of Antarctica.","zh":"在過去半個世紀的研究改變了我們對南極洲的看法。"},{"en":"During the past half century means over the last fifty years.","zh":"during the past half century 指在過去五十年間。"},{"en":"During the past half century, computers have changed how students write and learn.","zh":"在過去半個世紀，電腦改變了學生寫作和學習的方式。"},{"en":"Long-term research can reveal patterns that short studies miss.","zh":"長期研究可以揭示短期研究錯過的模式。"},{"en":"This phrase gives a broad recent historical time frame.","zh":"這個短語給出一個較近期但寬闊的歷史時間範圍。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":4},{"front":"reveal that","meaning":"顯示；揭示","examples":[{"en":"Scientific research has revealed that Antarctica influences climate.","zh":"科學研究顯示南極洲會影響氣候。"},{"en":"To reveal that means to show or make known something that was not clearly understood before.","zh":"reveal that 指顯示或使人知道以前未被清楚理解的事情。"},{"en":"A blood test may reveal that tiredness is caused by low iron.","zh":"驗血可能顯示疲倦由缺鐵造成。"},{"en":"New evidence can reveal that an old explanation was incomplete.","zh":"新證據可以揭示舊解釋並不完整。"},{"en":"This phrase introduces a discovery or important finding.","zh":"這個短語引入發現或重要研究結果。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":4},{"front":"Antarctica’s great mass","meaning":"南極洲巨大的質量","examples":[{"en":"Antarctica’s great mass influences climate and ocean circulation.","zh":"南極洲巨大的質量影響氣候和海洋環流。"},{"en":"Antarctica’s great mass means its enormous amount of land and ice.","zh":"Antarctica’s great mass 指其巨大的陸地和冰量。"},{"en":"A large mountain range can affect weather because its great mass changes wind movement.","zh":"大型山脈可以影響天氣，因為其巨大體量改變風的流動。"},{"en":"A huge mass of ice can influence temperature and sea-level systems.","zh":"巨大冰體可以影響溫度和海平面系統。"},{"en":"This phrase points to Antarctica’s physical size and weight.","zh":"這個短語指出南極洲的實體大小和重量。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":4},{"front":"low temperature","meaning":"低溫","examples":[{"en":"Antarctica’s low temperature affects climate and ocean circulation.","zh":"南極洲的低溫影響氣候和海洋環流。"},{"en":"Low temperature means a cold condition or a low level of heat.","zh":"low temperature 指寒冷狀態或熱量水平低。"},{"en":"Low temperature in a fridge keeps food fresh for longer.","zh":"冰箱中的低溫可以令食物保持新鮮更久。"},{"en":"In polar regions, low temperature helps ice remain frozen for long periods.","zh":"在極地地區，低溫幫助冰長時間保持冰凍。"},{"en":"This phrase describes coldness as a measurable condition.","zh":"這個短語把寒冷描述為可量度的狀態。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":4},{"front":"exert a major influence on","meaning":"對……產生重大影響","examples":[{"en":"Antarctica exerts a major influence on climate and ocean circulation.","zh":"南極洲對氣候和海洋環流產生重大影響。"},{"en":"To exert a major influence on something means to strongly affect how it works or changes.","zh":"exert a major influence on something 指強烈影響某事如何運作或改變。"},{"en":"Parents can exert a major influence on children’s reading habits by reading with them daily.","zh":"父母每天與孩子閱讀，可以對孩子的閱讀習慣產生重大影響。"},{"en":"A powerful current can exert a major influence on weather patterns far away.","zh":"強大的洋流可以對遠方天氣模式產生重大影響。"},{"en":"This phrase is formal and means “strongly affect”.","zh":"這個短語較正式，意思是「強烈影響」。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":4},{"front":"climate and ocean circulation","meaning":"氣候和海洋環流","examples":[{"en":"Antarctica affects climate and ocean circulation around the world.","zh":"南極洲影響全球氣候和海洋環流。"},{"en":"Climate and ocean circulation mean long-term weather patterns and the movement of seawater around the planet.","zh":"climate and ocean circulation 指長期天氣模式和海水在全球的流動。"},{"en":"A change in ocean circulation can affect rainfall, storms, and marine life.","zh":"海洋環流變化可以影響降雨、風暴和海洋生物。"},{"en":"Climate and ocean circulation are connected because oceans store and move heat.","zh":"氣候和海洋環流相互連接，因為海洋會儲存和轉移熱量。"},{"en":"This phrase links the atmosphere with the global ocean system.","zh":"這個短語把大氣與全球海洋系統連繫起來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":4},{"front":"all over the globe","meaning":"遍及全球","examples":[{"en":"These factors influence the lives of millions of people all over the globe.","zh":"這些因素影響遍及全球數百萬人的生活。"},{"en":"All over the globe means in many places around the world.","zh":"all over the globe 指在世界各地許多地方。"},{"en":"A popular song can be heard all over the globe when it spreads online.","zh":"一首流行歌曲在網上傳播後，可以在全球各地被聽到。"},{"en":"A change in climate can affect food, water, and jobs all over the globe.","zh":"氣候變化可以影響全球各地的食物、水和工作。"},{"en":"This phrase emphasises worldwide reach.","zh":"這個短語強調全球範圍。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":4},{"front":"was not always cold","meaning":"並非一直寒冷","examples":[{"en":"Antarctica was not always cold.","zh":"南極洲並非一直寒冷。"},{"en":"Was not always cold means it was warmer at some time in the past.","zh":"was not always cold 指在過去某些時期曾較溫暖。"},{"en":"A city that is now dry was not always dry if ancient lakes once covered the area.","zh":"如果古代湖泊曾覆蓋某地，現在乾燥的城市並非一直乾燥。"},{"en":"This phrase reminds readers that environments can change greatly over geological time.","zh":"這個短語提醒讀者，環境可以在地質時間中大幅改變。"},{"en":"It challenges the idea that Antarctica has always looked the same.","zh":"它挑戰南極洲一直都是同一模樣的想法。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":4},{"front":"the slow break-up of","meaning":"……的緩慢分裂","examples":[{"en":"The slow break-up of Gondwana changed Antarctica’s climate.","zh":"岡瓦納的緩慢分裂改變了南極洲的氣候。"},{"en":"The slow break-up of something means its gradual separation into smaller parts.","zh":"slow break-up of something 指某物逐漸分離成較小部分。"},{"en":"The slow break-up of an old company may happen as departments become independent businesses.","zh":"一間舊公司的緩慢分裂，可能隨着部門成為獨立企業而發生。"},{"en":"When a large landmass breaks up, ocean and wind patterns can change.","zh":"當大型陸塊分裂，海洋和風的模式可能改變。"},{"en":"This phrase emphasises gradual separation, not sudden destruction.","zh":"這個短語強調逐漸分離，而不是突然毀滅。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":5},{"front":"the supercontinent Gondwana","meaning":"岡瓦納超大陸","examples":[{"en":"The supercontinent Gondwana gradually broke up.","zh":"岡瓦納超大陸逐漸分裂。"},{"en":"The supercontinent Gondwana was a huge ancient landmass made up of continents that later separated.","zh":"supercontinent Gondwana 指一塊巨大的古代陸塊，由後來分離的大陸組成。"},{"en":"A geography teacher may use maps to show how Gondwana once connected lands now far apart.","zh":"地理老師可能用地圖展示岡瓦納曾如何連接現在相隔遙遠的陸地。"},{"en":"Its break-up changed oceans, climates, and the positions of continents.","zh":"它的分裂改變了海洋、氣候和大陸位置。"},{"en":"This phrase refers to an ancient geological landmass.","zh":"這個短語指古代地質陸塊。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":5},{"front":"northward movements of","meaning":"……向北移動","examples":[{"en":"The northward movements of other continents created space around Antarctica.","zh":"其他大陸向北移動，在南極洲周圍創造了空間。"},{"en":"Northward movements of something are movements towards the north.","zh":"northward movements of something 指某物朝北方移動。"},{"en":"The northward movement of warm air can raise temperatures in a colder region.","zh":"暖空氣向北移動可以提高較冷地區的氣溫。"},{"en":"When continents move northward, they can open ocean space behind them.","zh":"當大陸向北移動，它們可以在後方打開海洋空間。"},{"en":"This phrase describes direction of movement.","zh":"這個短語描述移動方向。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":5},{"front":"eventually created enough space","meaning":"最終創造足夠空間","examples":[{"en":"The movement of continents eventually created enough space around Antarctica.","zh":"大陸移動最終在南極洲周圍創造了足夠空間。"},{"en":"Eventually created enough space means finally produced sufficient room after a long process.","zh":"eventually created enough space 指經過長時間過程後終於產生足夠空間。"},{"en":"Moving old shelves eventually created enough space for a classroom reading corner.","zh":"移走舊書架最終創造足夠空間，讓課室設閱讀角。"},{"en":"Gradual changes can eventually create conditions for something new to develop.","zh":"逐漸變化最終可以創造新事物發展的條件。"},{"en":"This phrase links a long process with a later result.","zh":"這個短語把長期過程與後來結果連繫起來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":5},{"front":"the development of","meaning":"……的形成；發展","examples":[{"en":"This space allowed the development of the Antarctic Circumpolar Current.","zh":"這個空間容許南極繞極流形成。"},{"en":"The development of something means its formation, growth, or gradual coming into existence.","zh":"development of something 指某物的形成、成長或逐漸出現。"},{"en":"The development of a new school programme may take months of planning and testing.","zh":"新學校計劃的發展可能需要數月規劃和測試。"},{"en":"Certain conditions must exist before a complex system can develop.","zh":"複雜系統發展前，必須先存在某些條件。"},{"en":"This phrase focuses on how something forms over time.","zh":"這個短語著重某事如何隨時間形成。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":5},{"front":"Antarctic Circumpolar Current","meaning":"南極繞極流","examples":[{"en":"The Antarctic Circumpolar Current flows around Antarctica.","zh":"南極繞極流環繞南極洲流動。"},{"en":"The Antarctic Circumpolar Current is a powerful ocean current that circles Antarctica.","zh":"Antarctic Circumpolar Current 指環繞南極洲的一股強大洋流。"},{"en":"A geography lesson may compare this current with other major ocean currents.","zh":"地理課可能把這股洋流與其他主要洋流比較。"},{"en":"Because it circles Antarctica, it helps separate Antarctic waters from warmer waters farther north.","zh":"因為它環繞南極洲，所以幫助把南極水域與更北方較暖水域分隔。"},{"en":"This phrase names a major current in the Southern Ocean.","zh":"這個短語命名南冰洋中的一股主要洋流。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":5},{"front":"flow from west to east","meaning":"由西向東流動","examples":[{"en":"The Antarctic Circumpolar Current flowed from west to east.","zh":"南極繞極流由西向東流動。"},{"en":"To flow from west to east means to move in an eastward direction.","zh":"flow from west to east 指朝東方移動。"},{"en":"A river on a map may flow from west to east before entering the sea.","zh":"地圖上的一條河可能在入海前由西向東流動。"},{"en":"Wind direction can influence the direction in which water flows.","zh":"風向可以影響水流方向。"},{"en":"This phrase describes the movement direction of air or water.","zh":"這個短語描述空氣或水的移動方向。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":5},{"front":"under the influence of","meaning":"在……影響下","examples":[{"en":"The current flowed under the influence of the prevailing westerly winds.","zh":"這股洋流在盛行西風影響下流動。"},{"en":"Under the influence of something means affected or guided by that force or factor.","zh":"under the influence of something 指受某力量或因素影響或引導。"},{"en":"Students may change their study habits under the influence of a strict but helpful teacher.","zh":"學生可能在嚴格但有幫助的老師影響下改變學習習慣。"},{"en":"Ocean currents can move differently under the influence of winds and temperature.","zh":"洋流在風和溫度影響下可能以不同方式移動。"},{"en":"This phrase shows what causes or shapes an action.","zh":"這個短語顯示甚麼造成或塑造某行動。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":5},{"front":"prevailing westerly winds","meaning":"盛行西風","examples":[{"en":"The Antarctic Circumpolar Current is driven by prevailing westerly winds.","zh":"南極繞極流由盛行西風推動。"},{"en":"Prevailing westerly winds are common winds that usually blow from the west.","zh":"prevailing westerly winds 指通常從西方吹來的常見風。"},{"en":"Sailors study prevailing winds before planning a long sea journey.","zh":"水手計劃長途航行前會研究盛行風。"},{"en":"Regular winds can shape ocean currents because they push surface water repeatedly.","zh":"規律風向可以塑造洋流，因為它反覆推動表層海水。"},{"en":"This phrase describes dominant wind patterns.","zh":"這個短語描述主要風向模式。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":5},{"front":"vegetation perished","meaning":"植被消亡","examples":[{"en":"Antarctica cooled and its vegetation perished.","zh":"南極洲變冷，其植被消亡。"},{"en":"Vegetation perished means plants died and disappeared from an area.","zh":"vegetation perished 指植物死亡並從某地消失。"},{"en":"A garden’s vegetation may perish if it receives no water for weeks.","zh":"如果花園幾星期沒有水，植被可能枯死。"},{"en":"When climate becomes too cold or dry, plants may no longer survive.","zh":"當氣候變得太冷或太乾，植物可能無法再存活。"},{"en":"This phrase describes the loss of plant life.","zh":"這個短語描述植物生命的消失。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":5},{"front":"glaciation began","meaning":"冰川作用開始","examples":[{"en":"Glaciation began after Antarctica cooled.","zh":"南極洲變冷後，冰川作用開始。"},{"en":"Glaciation began means ice sheets and glaciers started to form and spread.","zh":"glaciation began 指冰蓋和冰川開始形成並擴展。"},{"en":"In a cold mountain region, glaciation may begin when snow remains year after year.","zh":"在寒冷山區，當積雪年復一年不融化，冰川作用可能開始。"},{"en":"Once glaciation begins, ice can reshape valleys, rocks, and landscapes.","zh":"一旦冰川作用開始，冰可以重塑山谷、岩石和地貌。"},{"en":"This phrase describes the start of large-scale ice formation.","zh":"這個短語描述大規模冰形成的開始。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":6},{"front":"take on its present-day appearance","meaning":"呈現現今面貌","examples":[{"en":"The continent took on its present-day appearance after glaciation began.","zh":"冰川作用開始後，這片大陸呈現現今面貌。"},{"en":"To take on its present-day appearance means to begin looking like it does today.","zh":"take on its present-day appearance 指開始變得像今天所見的樣子。"},{"en":"A city may take on its present-day appearance after decades of rebuilding and new roads.","zh":"城市經過數十年重建和新道路建設後，可能呈現現今面貌。"},{"en":"Long natural processes can slowly give a landscape its modern form.","zh":"長期自然過程可以慢慢賦予地貌現代形態。"},{"en":"This phrase connects past change with the shape we see now.","zh":"這個短語把過去變化與我們現在看到的形狀連繫起來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":6},{"front":"overlie the bedrock","meaning":"覆蓋在基岩之上","examples":[{"en":"Ice overlies the bedrock in Antarctica.","zh":"在南極洲，冰覆蓋在基岩之上。"},{"en":"To overlie the bedrock means to lie on top of the solid rock beneath.","zh":"overlie the bedrock 指位於下方堅硬岩石之上。"},{"en":"Soil may overlie bedrock on a hillside, with tree roots growing in the upper layer.","zh":"山坡上泥土可能覆蓋在基岩之上，樹根在上層生長。"},{"en":"If ice overlies bedrock for long periods, it can press on and shape the land below.","zh":"如果冰長期覆蓋在基岩之上，它可以壓迫並塑造下方土地。"},{"en":"This phrase describes one layer covering another.","zh":"這個短語描述一層覆蓋另一層。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":6},{"front":"bedrock","meaning":"基岩","examples":[{"en":"The Antarctic ice overlies the bedrock.","zh":"南極冰層覆蓋在基岩之上。"},{"en":"Bedrock is the solid rock beneath soil, ice, or loose surface material.","zh":"bedrock 指泥土、冰或鬆散表層物質下方的堅硬岩石。"},{"en":"Builders may need to reach bedrock before constructing a very tall building.","zh":"建築高樓前，建築工人可能需要到達基岩。"},{"en":"Bedrock provides a stable base, but it can be hidden under many layers.","zh":"基岩提供穩定基礎，但可能被多層物質覆蓋。"},{"en":"This word refers to the hard foundation rock beneath the surface.","zh":"這個詞指地表下的堅硬基礎岩石。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":6},{"front":"up to 4 km thick","meaning":"厚達4公里","examples":[{"en":"The ice that covers Antarctica is up to 4 km thick.","zh":"覆蓋南極洲的冰厚達 4 公里。"},{"en":"Up to 4 km thick means as thick as four kilometres at its maximum.","zh":"up to 4 km thick 指最厚可達四公里。"},{"en":"A snow layer up to one metre thick can block roads after a heavy storm.","zh":"大風雪後，厚達一米的積雪可以堵塞道路。"},{"en":"Great thickness adds weight and affects the land beneath it.","zh":"巨大厚度會增加重量並影響下方土地。"},{"en":"This phrase gives the maximum measured thickness.","zh":"這個短語給出最大量度厚度。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":6},{"front":"surface temperatures","meaning":"地表溫度","examples":[{"en":"Surface temperatures as low as −89.2°C have been recorded.","zh":"已記錄到低至攝氏零下 89.2 度的地表溫度。"},{"en":"Surface temperatures are temperatures measured at or near the ground or surface level.","zh":"surface temperatures 指在地面或表層附近量度的溫度。"},{"en":"Road surface temperatures can fall below air temperature on a clear winter night.","zh":"在晴朗冬夜，路面地表溫度可能低於氣溫。"},{"en":"Surface temperatures matter because they affect ice, soil, roads, and living conditions.","zh":"地表溫度重要，因為它影響冰、土壤、道路和生活條件。"},{"en":"This phrase refers to temperature at the surface, not deep underground.","zh":"這個短語指表面溫度，而不是深地下溫度。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":6},{"front":"as low as","meaning":"低至","examples":[{"en":"Temperatures as low as −89.2°C have been recorded in Antarctica.","zh":"南極洲已記錄到低至攝氏零下 89.2 度的溫度。"},{"en":"As low as means reaching a very low level, number, or temperature.","zh":"as low as 指達到非常低的水平、數字或溫度。"},{"en":"During a sale, some books may cost as low as ten dollars.","zh":"減價期間，有些書可能低至十美元。"},{"en":"In weather reports, “as low as” highlights the extreme lower limit.","zh":"在天氣報告中，as low as 突出極端低點。"},{"en":"This phrase gives a minimum or extreme low point.","zh":"這個短語給出最低或極低水平。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":6},{"front":"be recorded","meaning":"被記錄","examples":[{"en":"Extremely low temperatures have been recorded in Antarctica.","zh":"南極洲已記錄到極低溫度。"},{"en":"To be recorded means to be measured, written down, or officially noted.","zh":"be recorded 指被量度、寫下或正式記載。"},{"en":"A student’s attendance is recorded each morning by the class teacher.","zh":"班主任每天早上記錄學生出席情況。"},{"en":"Recorded data can be checked later and compared with other years.","zh":"已記錄數據之後可以被查核，並與其他年份比較。"},{"en":"This phrase shows that information is documented, not just guessed.","zh":"這個短語顯示資料已被記錄，而不是猜測。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":6},{"front":"icy blast","meaning":"冰冷強風","examples":[{"en":"The icy blast howls over the ice cap and out to sea.","zh":"冰冷強風呼嘯吹過冰帽並吹向大海。"},{"en":"An icy blast is a very cold, strong rush of wind.","zh":"icy blast 指非常寒冷而強烈的一股風。"},{"en":"An icy blast from an open door can make a warm classroom suddenly feel cold.","zh":"從開着的門吹進來的冰冷強風，可以令溫暖課室突然變冷。"},{"en":"Strong cold wind can remove warmth from the body very quickly.","zh":"強烈寒風可以很快帶走身體熱量。"},{"en":"This phrase describes a sudden, harsh cold wind.","zh":"這個短語描述突然且嚴酷的冷風。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":6},{"front":"howl over","meaning":"呼嘯吹過","examples":[{"en":"The katabatic wind howls over the ice cap.","zh":"下坡風呼嘯吹過冰帽。"},{"en":"To howl over a place means to blow across it with a loud, wild sound.","zh":"howl over a place 指以響亮而狂野的聲音吹過某地。"},{"en":"At night, strong wind may howl over the rooftops and keep people awake.","zh":"夜晚強風可能呼嘯吹過屋頂，令人睡不着。"},{"en":"Howling wind suggests both strength and noise.","zh":"呼嘯的風暗示力量和聲音都很強。"},{"en":"This phrase creates a dramatic image of powerful wind moving across a surface.","zh":"這個短語塑造強風掠過表面的戲劇性畫面。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":6},{"front":"ice cap","meaning":"冰帽","examples":[{"en":"The wind blows over the Antarctic ice cap.","zh":"風吹過南極冰帽。"},{"en":"An ice cap is a large area of ice covering land, usually smaller than a full ice sheet.","zh":"ice cap 指覆蓋陸地的大面積冰，通常比完整冰蓋小。"},{"en":"A geography class may study how an ice cap stores fresh water.","zh":"地理課可能研究冰帽如何儲存淡水。"},{"en":"If an ice cap melts, it can affect rivers, sea level, and ecosystems.","zh":"如果冰帽融化，它可以影響河流、海平面和生態系統。"},{"en":"This phrase refers to a large land-based ice cover.","zh":"這個短語指大面積陸地冰覆蓋。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":7},{"front":"the so-called","meaning":"所謂的","examples":[{"en":"The icy blast is the so-called katabatic wind.","zh":"這股冰冷強風就是所謂的下坡風。"},{"en":"The so-called means the thing is known by a particular name.","zh":"so-called 指某事物以某個名稱為人所知。"},{"en":"The so-called “silent reading time” may not be silent if students keep whispering.","zh":"所謂的「安靜閱讀時間」如果學生一直耳語，可能並不安靜。"},{"en":"Sometimes this phrase simply introduces a technical name; sometimes it suggests doubt.","zh":"這個短語有時只是引入專門名稱，有時帶有懷疑意味。"},{"en":"In scientific writing, it often means “what is known as”.","zh":"在科學寫作中，它常表示「所稱的」。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":7},{"front":"katabatic wind","meaning":"下坡風；下降風","examples":[{"en":"The katabatic wind can reach 300 km/h.","zh":"下坡風可以達到每小時 300 公里。"},{"en":"A katabatic wind is a cold, dense wind that flows downhill from high ice or mountains.","zh":"katabatic wind 指從高處冰面或山區向下流動的寒冷密集空氣。"},{"en":"A strong katabatic wind can make outdoor work dangerous in polar areas.","zh":"強烈下坡風可以令極地戶外工作變得危險。"},{"en":"Because cold air is heavy, it can slide down slopes quickly and powerfully.","zh":"因為冷空氣較重，它可以快速而有力地沿斜坡下滑。"},{"en":"This phrase names a specific type of downward cold wind.","zh":"這個短語命名一種特定的下行寒風。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":7},{"front":"reach 300 km/h","meaning":"達到每小時300公里","examples":[{"en":"The katabatic wind can reach 300 km/h.","zh":"下坡風可以達到每小時 300 公里。"},{"en":"To reach 300 km/h means to get to a speed of 300 kilometres per hour.","zh":"reach 300 km/h 指速度達到每小時三百公里。"},{"en":"A racing car may reach very high speeds on a professional track.","zh":"賽車在專業賽道上可能達到很高速度。"},{"en":"When wind reaches such speeds, it can damage equipment and threaten lives.","zh":"當風速達到這種水平，它可以損壞設備並威脅生命。"},{"en":"This phrase gives the maximum or possible speed.","zh":"這個短語給出最高或可能速度。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":7},{"front":"wind-chill effects","meaning":"風寒效應","examples":[{"en":"The katabatic wind creates fearsome wind-chill effects.","zh":"下坡風造成可怕的風寒效應。"},{"en":"Wind-chill effects are the way wind makes the air feel colder than the actual temperature.","zh":"wind-chill effects 指風令人感覺比實際氣溫更冷的現象。"},{"en":"A winter day at 5°C can feel much colder if strong wind creates wind chill.","zh":"如果強風造成風寒，攝氏 5 度的冬日也可能感覺冷得多。"},{"en":"Wind chill increases danger because the body loses heat faster.","zh":"風寒會增加危險，因為身體失去熱量更快。"},{"en":"This phrase explains why cold wind can feel worse than the thermometer shows.","zh":"這個短語解釋為何冷風會比溫度計顯示更難受。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":7},{"front":"extreme environment","meaning":"極端環境","examples":[{"en":"Powerful global forces come out of this extreme environment.","zh":"強大的全球力量來自這個極端環境。"},{"en":"An extreme environment is a place with very harsh conditions, such as severe cold, heat, dryness, or danger.","zh":"extreme environment 指條件非常嚴酷的地方，例如極寒、酷熱、乾旱或危險。"},{"en":"A desert is an extreme environment because water is scarce and temperatures can be high.","zh":"沙漠是極端環境，因為水源稀少且溫度可能很高。"},{"en":"Extreme environments test people, animals, equipment, and scientific ideas.","zh":"極端環境會考驗人類、動物、設備和科學想法。"},{"en":"This phrase describes conditions far outside normal comfort.","zh":"這個短語描述遠超正常舒適範圍的環境。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":7},{"front":"powerful forces","meaning":"強大力量","examples":[{"en":"Powerful forces from Antarctica reverberate around the world.","zh":"來自南極洲的強大力量在世界各地產生影響。"},{"en":"Powerful forces are strong natural or social influences that can create major effects.","zh":"powerful forces 指能造成重大影響的強烈自然或社會力量。"},{"en":"Public opinion can become a powerful force when many citizens demand change.","zh":"當許多市民要求改變，公眾意見可以成為強大力量。"},{"en":"In nature, powerful forces such as wind and currents can shape distant weather.","zh":"在自然界中，風和洋流等強大力量可以塑造遠方天氣。"},{"en":"This phrase describes strength that produces important consequences.","zh":"這個短語描述能產生重要後果的力量。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":7},{"front":"reverberate around the world","meaning":"在世界各地產生影響","examples":[{"en":"Forces from Antarctica reverberate around the world.","zh":"來自南極洲的力量在世界各地產生影響。"},{"en":"To reverberate around the world means to have effects that spread widely across the globe.","zh":"reverberate around the world 指影響廣泛傳遍全球。"},{"en":"A major economic crisis can reverberate around the world by affecting jobs and prices in many countries.","zh":"重大經濟危機可以透過影響多國職位和物價，在世界各地產生影響。"},{"en":"When one region influences climate systems, its effects can reach distant places.","zh":"當某地區影響氣候系統，其效果可以到達遙遠地方。"},{"en":"This phrase suggests wide, continuing impact.","zh":"這個短語表示廣泛且持續的影響。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":7},{"front":"the Earth’s rotation","meaning":"地球自轉","examples":[{"en":"The Earth’s rotation helps create weather patterns around Antarctica.","zh":"地球自轉有助形成南極洲周圍的天氣模式。"},{"en":"The Earth’s rotation is the spinning of the Earth around its axis.","zh":"Earth’s rotation 指地球圍繞自身軸線旋轉。"},{"en":"A science teacher may use a globe to show the Earth’s rotation and day-night cycles.","zh":"科學老師可能用地球儀展示地球自轉和晝夜循環。"},{"en":"Rotation affects winds and ocean movement because the planet is constantly turning.","zh":"自轉影響風和海水流動，因為地球一直在轉動。"},{"en":"This phrase refers to the Earth’s spinning motion.","zh":"這個短語指地球的旋轉運動。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":7},{"front":"coupled with","meaning":"與……結合","examples":[{"en":"The Earth’s rotation, coupled with low-pressure cells, creates a pattern.","zh":"地球自轉與低壓氣旋結合，形成一種模式。"},{"en":"Coupled with means combined with another factor.","zh":"coupled with 指與另一因素結合。"},{"en":"Poor sleep, coupled with exam stress, can make concentration very difficult.","zh":"睡眠不足與考試壓力結合，可以令集中注意非常困難。"},{"en":"Two factors together can create a stronger effect than either one alone.","zh":"兩個因素合起來可以比單一因素產生更強效果。"},{"en":"This phrase links causes that work together.","zh":"這個短語連接共同作用的原因。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":7},{"front":"the formation of","meaning":"……的形成","examples":[{"en":"The formation of low-pressure cells affects the Southern Ocean.","zh":"低壓氣旋的形成影響南冰洋。"},{"en":"The formation of something means the process by which it comes into being.","zh":"formation of something 指某物形成或出現的過程。"},{"en":"The formation of a student club may begin with a few classmates sharing the same interest.","zh":"學生學會的形成可能始於幾位同學有相同興趣。"},{"en":"When weather systems form, they can influence wind, rain, and sea conditions.","zh":"當天氣系統形成，它們可以影響風、雨和海況。"},{"en":"This phrase focuses on how something begins to exist.","zh":"這個短語著重某物如何開始存在。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":8},{"front":"low-pressure cells","meaning":"低壓氣旋","examples":[{"en":"Low-pressure cells form off the Antarctic coast.","zh":"低壓氣旋在南極洲海岸外形成。"},{"en":"Low-pressure cells are weather systems where air pressure is lower than in surrounding areas.","zh":"low-pressure cells 指氣壓低於周邊地區的天氣系統。"},{"en":"A low-pressure system can bring wind, clouds, and rain to a city.","zh":"低壓系統可以為城市帶來風、雲和雨。"},{"en":"Low pressure can help create storms because air rises and weather becomes unstable.","zh":"低壓可以幫助形成風暴，因為空氣上升，天氣變得不穩定。"},{"en":"This phrase refers to a type of atmospheric system.","zh":"這個短語指一種大氣系統。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":8},{"front":"off the Antarctic coast","meaning":"在南極洲海岸外","examples":[{"en":"Low-pressure cells form off the Antarctic coast.","zh":"低壓氣旋在南極洲海岸外形成。"},{"en":"Off the Antarctic coast means in the ocean near the edge of Antarctica.","zh":"off the Antarctic coast 指在南極洲邊緣附近的海洋中。"},{"en":"Fishing boats may work off the coast of a country but not land on its shore.","zh":"漁船可能在某國海岸外作業，但不登上岸。"},{"en":"Weather systems forming off a coast can affect both the sea and nearby land.","zh":"在海岸外形成的天氣系統可以影響海洋和附近陸地。"},{"en":"This phrase gives a location just outside the coastline.","zh":"這個短語給出海岸線外的位置。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":8},{"front":"give astronauts a view of","meaning":"讓太空人看到……的景象","examples":[{"en":"The pattern would give astronauts a spectacular view of Antarctica.","zh":"這種模式會讓太空人看到壯觀的南極洲景象。"},{"en":"To give someone a view of something means to allow them to see it clearly.","zh":"give someone a view of something 指讓某人清楚看到某物。"},{"en":"A hilltop can give visitors a view of the whole town.","zh":"山頂可以讓訪客看到整個城鎮的景象。"},{"en":"A higher viewpoint can reveal patterns that are hard to see from the ground.","zh":"較高視角可以揭示地面難以看見的模式。"},{"en":"This phrase connects position with what can be seen.","zh":"這個短語把位置與可見景象連繫起來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":8},{"front":"as beautiful as it is awesome","meaning":"既美麗又令人敬畏","examples":[{"en":"The view of Antarctica is as beautiful as it is awesome.","zh":"南極洲景象既美麗又令人敬畏。"},{"en":"As beautiful as it is awesome means equally beautiful and awe-inspiring.","zh":"as beautiful as it is awesome 指同樣美麗和令人敬畏。"},{"en":"A clear night sky above a desert can be as beautiful as it is awesome.","zh":"沙漠上方清朗的夜空可以既美麗又令人敬畏。"},{"en":"This phrase shows that something can be attractive and overwhelming at the same time.","zh":"這個短語顯示某事物可以同時吸引人和令人震撼。"},{"en":"It is used for sights that create admiration and respect.","zh":"它用於令人讚嘆和敬畏的景象。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":8},{"front":"spin away to","meaning":"旋轉着移向","examples":[{"en":"The low-pressure cells spin away to the northeast.","zh":"低壓氣旋旋轉着移向東北方。"},{"en":"To spin away to a place means to rotate while moving away in that direction.","zh":"spin away to a place 指一邊旋轉一邊朝某方向移走。"},{"en":"A small toy top may spin away across the floor after a child pushes it.","zh":"孩子推動後，小陀螺可能旋轉着滑過地板。"},{"en":"Weather systems can move while rotating, so their path and shape both matter.","zh":"天氣系統可以一邊旋轉一邊移動，所以路徑和形狀都重要。"},{"en":"This phrase describes turning movement combined with travel.","zh":"這個短語描述旋轉和移動結合。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":8},{"front":"grow and deepen","meaning":"增強並加深","examples":[{"en":"The cells grow and deepen over the Southern Ocean.","zh":"這些氣旋在南冰洋上增強並加深。"},{"en":"To grow and deepen means to become larger and stronger in pressure or intensity.","zh":"grow and deepen 指在壓力或強度上變得更大、更強。"},{"en":"A disagreement can grow and deepen if nobody listens or apologises.","zh":"如果沒有人聆聽或道歉，分歧可能會加深並擴大。"},{"en":"In weather, a deepening low-pressure system can become more powerful.","zh":"在天氣中，加深的低壓系統可以變得更強。"},{"en":"This phrase describes a system becoming stronger over time.","zh":"這個短語描述系統隨時間變強。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":8},{"front":"whip up","meaning":"激起；掀起","examples":[{"en":"The cells whip up the Southern Ocean into mountainous seas.","zh":"這些氣旋在南冰洋掀起巨浪滔天的海面。"},{"en":"To whip up something means to stir it violently or make it more active and intense.","zh":"whip up something 指猛烈攪動某物，或令其更活躍、更強烈。"},{"en":"Strong wind can whip up dust on a dry football field.","zh":"強風可以在乾燥足球場上揚起塵土。"},{"en":"In the ocean, storms can whip up waves and make sailing dangerous.","zh":"在海洋中，風暴可以掀起巨浪，令航行危險。"},{"en":"This phrase suggests energetic and forceful movement.","zh":"這個短語帶有有力且劇烈動作的意思。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":8},{"front":"the Southern Ocean","meaning":"南冰洋","examples":[{"en":"The Southern Ocean is strongly influenced by Antarctic weather systems.","zh":"南冰洋受到南極天氣系統強烈影響。"},{"en":"The Southern Ocean is the ocean surrounding Antarctica.","zh":"Southern Ocean 指環繞南極洲的海洋。"},{"en":"Ships crossing the Southern Ocean may face rough seas and powerful winds.","zh":"橫越南冰洋的船隻可能面對洶湧海面和強風。"},{"en":"Because it surrounds Antarctica, it links Antarctic processes with other oceans.","zh":"因為它環繞南極洲，所以把南極過程與其他海洋連繫起來。"},{"en":"This phrase names the ocean region around Antarctica.","zh":"這個短語命名南極洲周圍的海洋區域。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":8},{"front":"mountainous seas","meaning":"巨浪滔天的海面","examples":[{"en":"Low-pressure cells whip up mountainous seas in the Southern Ocean.","zh":"低壓氣旋在南冰洋掀起巨浪滔天的海面。"},{"en":"Mountainous seas are extremely high, rough waves that look as large as hills or mountains.","zh":"mountainous seas 指極高而洶湧、看起來像山丘或山脈般的海浪。"},{"en":"A fishing boat may stay in harbour when forecasts warn of mountainous seas.","zh":"當天氣預報警告有巨浪，漁船可能留在港內。"},{"en":"Such seas are dangerous because waves can overwhelm ships and crews.","zh":"這類海況很危險，因為巨浪可以壓倒船隻和船員。"},{"en":"This phrase creates an image of very rough ocean conditions.","zh":"這個短語塑造非常惡劣海況的畫面。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":8},{"front":"be respected by","meaning":"受到……敬畏","examples":[{"en":"The mountainous seas are respected by mariners.","zh":"這些巨浪滔天的海面受到海員敬畏。"},{"en":"To be respected by someone means to be treated with serious caution because of power or danger.","zh":"be respected by someone 指因力量或危險而被某人嚴肅謹慎對待。"},{"en":"Experienced hikers respect sudden mountain weather because it can change quickly.","zh":"有經驗的遠足者敬畏突變山區天氣，因為它可以快速改變。"},{"en":"Dangerous natural forces are respected when people prepare carefully before facing them.","zh":"當人們在面對自然力量前仔細準備，就是對危險自然力量表示敬畏。"},{"en":"This phrase can mean “feared and taken seriously”, not only admired.","zh":"這個短語可以表示「害怕並認真對待」，不只是欣賞。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":9},{"front":"mariners","meaning":"海員；航海者","examples":[{"en":"Mariners respect the dangerous seas around Antarctica.","zh":"海員敬畏南極洲周圍危險的海域。"},{"en":"Mariners are people who sail, work, or travel on the sea.","zh":"mariners 指在海上航行、工作或旅行的人。"},{"en":"Mariners must understand weather, waves, navigation, and safety rules.","zh":"海員必須理解天氣、海浪、航海和安全規則。"},{"en":"Experienced mariners avoid taking unnecessary risks in stormy waters.","zh":"有經驗的海員會避免在暴風海域冒不必要風險。"},{"en":"This word is more formal than “sailors”.","zh":"這個詞比 sailors 更正式。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":9},{"front":"recent work is showing that","meaning":"近期研究正在顯示","examples":[{"en":"Recent work is showing that ocean temperature may predict Australian rainfall.","zh":"近期研究正在顯示，海洋溫度可能預測澳洲降雨量。"},{"en":"Recent work is showing that means new research is beginning to provide evidence for an idea.","zh":"recent work is showing that 指新研究開始為某想法提供證據。"},{"en":"Recent work is showing that sleep quality can affect students’ memory more than expected.","zh":"近期研究正在顯示，睡眠質素對學生記憶的影響可能比預期更大。"},{"en":"This phrase suggests a developing finding rather than a final conclusion.","zh":"這個短語表示正在發展中的發現，而不是最終結論。"},{"en":"It is often used when science is still advancing.","zh":"它常用於科學仍在進展時。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":9},{"front":"ocean temperature","meaning":"海洋溫度","examples":[{"en":"Ocean temperature may help predict rainfall in Australia.","zh":"海洋溫度可能有助預測澳洲降雨量。"},{"en":"Ocean temperature is the temperature of seawater at or below the surface.","zh":"ocean temperature 指海水在表面或表面以下的溫度。"},{"en":"Warm ocean temperature can affect storms, fish movement, and coastal weather.","zh":"溫暖海洋溫度可以影響風暴、魚群移動和沿岸天氣。"},{"en":"Scientists measure ocean temperature because the sea stores and moves heat.","zh":"科學家量度海洋溫度，因為海洋會儲存和轉移熱量。"},{"en":"This phrase refers to the warmth or coldness of seawater.","zh":"這個短語指海水的冷暖程度。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":9},{"front":"a better predictor of","meaning":"……的較佳預測指標","examples":[{"en":"Ocean temperature may be a better predictor of rainfall than pressure difference.","zh":"海洋溫度可能比氣壓差更能預測降雨量。"},{"en":"A better predictor of something is a factor that forecasts it more accurately.","zh":"better predictor of something 指能更準確預測某事的因素。"},{"en":"Regular attendance may be a better predictor of exam success than last-minute revision.","zh":"穩定出席可能比臨急抱佛腳更能預測考試成功。"},{"en":"Better predictors help people make earlier and wiser decisions.","zh":"較佳預測指標幫助人更早和更明智地作決定。"},{"en":"This phrase compares how useful two signals are for forecasting.","zh":"這個短語比較兩個信號在預測方面有多有用。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":9},{"front":"rainfall in Australia","meaning":"澳洲降雨量","examples":[{"en":"Ocean temperature can help predict rainfall in Australia.","zh":"海洋溫度可以幫助預測澳洲降雨量。"},{"en":"Rainfall in Australia means the amount and pattern of rain falling across Australia.","zh":"rainfall in Australia 指澳洲各地降雨的數量和模式。"},{"en":"Farmers watch rainfall in Australia carefully because dry years can affect crops and animals.","zh":"農民仔細留意澳洲降雨量，因為乾旱年份可以影響農作物和牲畜。"},{"en":"Poor rainfall can reduce pasture, water supply, and farm income.","zh":"降雨不足可以減少牧草、水源和農場收入。"},{"en":"This phrase refers to rain levels in a specific country.","zh":"這個短語指某個特定國家的降雨水平。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":9},{"front":"pressure difference between","meaning":"……之間的氣壓差","examples":[{"en":"The Southern Oscillation Index uses the pressure difference between Darwin and Tahiti.","zh":"南方濤動指數使用達爾文與大溪地之間的氣壓差。"},{"en":"Pressure difference between two places means the difference in air pressure measured at those places.","zh":"pressure difference between two places 指在兩地量度到的氣壓差異。"},{"en":"Weather forecasters may compare pressure differences between cities to understand wind movement.","zh":"天氣預報員可能比較城市之間的氣壓差，以理解風的移動。"},{"en":"Air tends to move from higher pressure toward lower pressure, creating wind.","zh":"空氣傾向由高壓流向低壓，形成風。"},{"en":"This phrase identifies a measured contrast in atmospheric pressure.","zh":"這個短語指出大氣壓力中的量度差異。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":9},{"front":"Southern Oscillation Index","meaning":"南方濤動指數","examples":[{"en":"The Southern Oscillation Index is based on air pressure differences.","zh":"南方濤動指數以氣壓差為基礎。"},{"en":"The Southern Oscillation Index is a climate index that uses pressure differences to help describe large-scale climate patterns.","zh":"Southern Oscillation Index 是一種氣候指數，使用氣壓差來幫助描述大規模氣候模式。"},{"en":"Farmers may hear about the Southern Oscillation Index when checking seasonal rainfall forecasts.","zh":"農民查看季節性降雨預測時，可能聽到南方濤動指數。"},{"en":"Such an index can help connect distant ocean-atmosphere changes with local weather risk.","zh":"這類指數可以幫助把遙遠海洋大氣變化與本地天氣風險連繫起來。"},{"en":"This phrase names a technical climate indicator.","zh":"這個短語命名一個專門氣候指標。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":9},{"front":"more accurate predictions","meaning":"更準確的預測","examples":[{"en":"More accurate predictions help graziers avoid overstocking.","zh":"更準確的預測幫助牧場經營者避免過度放牧。"},{"en":"More accurate predictions are forecasts that are closer to what actually happens.","zh":"more accurate predictions 指更接近實際發生情況的預測。"},{"en":"More accurate bus arrival predictions help students decide whether to wait or walk.","zh":"更準確的巴士到站預測幫助學生決定等車還是步行。"},{"en":"Better predictions reduce waste because people can plan using more reliable information.","zh":"更好的預測可以減少浪費，因為人們能根據更可靠資訊作計劃。"},{"en":"This phrase describes improved forecasting quality.","zh":"這個短語描述預報質素提升。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":9},{"front":"graziers","meaning":"牧場經營者","examples":[{"en":"Graziers in northern Queensland can use rainfall predictions.","zh":"昆士蘭北部的牧場經營者可以使用降雨預測。"},{"en":"Graziers are people who raise animals on grassland, especially cattle or sheep.","zh":"graziers 指在草地上飼養牲畜的人，尤其是牛或羊。"},{"en":"A grazier may move animals to another field when pasture becomes too dry.","zh":"當牧草變得太乾，牧場經營者可能把牲畜移到另一塊田。"},{"en":"Graziers depend on rainfall because grass growth affects how many animals they can keep.","zh":"牧場經營者依賴降雨，因為草生長會影響他們能飼養多少牲畜。"},{"en":"This word refers to livestock farmers who use grazing land.","zh":"這個詞指使用放牧土地的畜牧農民。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":9},{"front":"northern Queensland","meaning":"昆士蘭北部","examples":[{"en":"Graziers in northern Queensland need accurate rainfall forecasts.","zh":"昆士蘭北部的牧場經營者需要準確降雨預報。"},{"en":"Northern Queensland is the northern part of the Australian state of Queensland.","zh":"northern Queensland 指澳洲昆士蘭州的北部。"},{"en":"A farmer in northern Queensland may plan stock numbers around expected rainfall.","zh":"昆士蘭北部的農民可能根據預期降雨量規劃牲畜數量。"},{"en":"Regional weather matters because one part of a country can be much wetter or drier than another.","zh":"地區天氣很重要，因為一個國家的某部分可以比另一部分潮濕或乾燥得多。"},{"en":"This phrase gives a specific farming region in Australia.","zh":"這個短語給出澳洲一個特定農牧地區。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":10},{"front":"avoid overstocking","meaning":"避免過度放牧","examples":[{"en":"Graziers can avoid overstocking when rainfall will be poor.","zh":"當降雨量不足時，牧場經營者可以避免過度放牧。"},{"en":"To avoid overstocking means to prevent keeping too many animals on the available land.","zh":"avoid overstocking 指避免在可用土地上飼養太多牲畜。"},{"en":"A farm can avoid overstocking by selling some cattle before a dry season.","zh":"農場可以在旱季前出售部分牛隻，以避免過度放牧。"},{"en":"Overstocking can damage grassland because too many animals eat the pasture too quickly.","zh":"過度放牧會損害草地，因為太多牲畜太快吃掉牧草。"},{"en":"This phrase describes careful control of livestock numbers.","zh":"這個短語描述謹慎控制牲畜數量。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":10},{"front":"when rainfall will be poor","meaning":"當降雨量不足時","examples":[{"en":"Farmers can reduce stock when rainfall will be poor.","zh":"當降雨量不足時，農民可以減少牲畜。"},{"en":"When rainfall will be poor means when little rain is expected in the future.","zh":"when rainfall will be poor 指預期未來降雨很少時。"},{"en":"If rainfall will be poor, a gardener may plant drought-resistant flowers.","zh":"如果降雨量將不足，園丁可能種植耐旱花卉。"},{"en":"Low expected rainfall can force farmers to reduce animals, water use, and planting.","zh":"預期低降雨可以迫使農民減少牲畜、用水和種植。"},{"en":"This phrase is used when planning ahead for dry conditions.","zh":"這個短語用於為乾旱情況提前規劃。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":10},{"front":"limit their losses","meaning":"減少損失","examples":[{"en":"Accurate forecasts help graziers limit their losses.","zh":"準確預報幫助牧場經營者減少損失。"},{"en":"To limit their losses means to reduce the amount of money, resources, or animals they lose.","zh":"limit their losses 指減少他們失去的金錢、資源或牲畜數量。"},{"en":"A shop may limit its losses by reducing orders before a slow sales season.","zh":"商店可能在銷售淡季前減少訂貨，以減少損失。"},{"en":"Early warnings help people act before damage becomes too expensive.","zh":"早期警告幫助人們在損害變得太昂貴前行動。"},{"en":"This phrase means reducing harm, not avoiding all harm completely.","zh":"這個短語意思是減少傷害，而不是完全避免所有傷害。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":10},{"front":"pasture degradation","meaning":"牧場退化","examples":[{"en":"Overstocking can cause serious pasture degradation.","zh":"過度放牧可以造成嚴重牧場退化。"},{"en":"Pasture degradation means grassland becomes damaged, less productive, or less able to support animals.","zh":"pasture degradation 指草地受損、產量下降，或較不能支撐牲畜。"},{"en":"A field can suffer pasture degradation if too many animals graze there for too long.","zh":"如果太多牲畜長時間在同一塊地放牧，該地可能出現牧場退化。"},{"en":"Damaged pasture may produce less grass and expose soil to erosion.","zh":"受損牧場可能產草量下降，並令泥土暴露於侵蝕之中。"},{"en":"This phrase describes the decline of grazing land.","zh":"這個短語描述放牧土地衰退。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":10},{"front":"take decades to repair","meaning":"需要數十年修復","examples":[{"en":"Serious pasture degradation may take decades to repair.","zh":"嚴重牧場退化可能需要數十年修復。"},{"en":"To take decades to repair means to need many tens of years to recover or be fixed.","zh":"take decades to repair 指需要很多個十年才能恢復或修好。"},{"en":"A polluted river may take decades to repair if chemicals remain in the mud.","zh":"如果化學物質留在泥中，受污染河流可能需要數十年修復。"},{"en":"Damage that takes decades to repair should be prevented before it becomes severe.","zh":"需要數十年修復的損害，應在變得嚴重前預防。"},{"en":"This phrase stresses that recovery is very slow.","zh":"這個短語強調復原非常緩慢。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":10},{"front":"prototype forecasting system","meaning":"原型預報系統","examples":[{"en":"CSIRO is developing a prototype forecasting system.","zh":"CSIRO 正在開發原型預報系統。"},{"en":"A prototype forecasting system is an early test version of a system that predicts future conditions.","zh":"prototype forecasting system 指用來預測未來情況的早期測試版本系統。"},{"en":"A transport department may test a prototype forecasting system for traffic jams.","zh":"交通部門可能測試交通擠塞的原型預報系統。"},{"en":"Prototypes allow scientists to improve a system before it is widely used.","zh":"原型讓科學家在系統廣泛使用前改進它。"},{"en":"This phrase means a trial prediction tool, not a finished product.","zh":"這個短語指試驗性預測工具，而不是完成品。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":10},{"front":"confidently predict","meaning":"有信心地預測","examples":[{"en":"Scientists can confidently predict improvements in forecasting ability.","zh":"科學家可以有信心地預測預報能力會改善。"},{"en":"To confidently predict something means to say it is likely to happen with strong evidence or belief.","zh":"confidently predict something 指基於強證據或信念，說某事很可能發生。"},{"en":"A teacher may confidently predict improvement if a student practises carefully every day.","zh":"如果學生每天仔細練習，老師可能有信心地預測他會進步。"},{"en":"Confidence in prediction grows when there is clear data and repeated success.","zh":"當有清楚數據和反覆成功，預測信心會增加。"},{"en":"This phrase shows strong but still future-looking judgement.","zh":"這個短語顯示強烈但仍面向未來的判斷。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":10},{"front":"enhance and extend","meaning":"加強並擴展","examples":[{"en":"Greater knowledge will enhance and extend our predictive ability.","zh":"更多知識會加強並擴展我們的預測能力。"},{"en":"To enhance and extend something means to improve it and make it reach further.","zh":"enhance and extend something 指改善某事並令其延伸得更遠。"},{"en":"A new library system can enhance and extend students’ access to books.","zh":"新圖書館系統可以加強並擴展學生取得書籍的機會。"},{"en":"Better tools may improve quality while also increasing the range of what people can do.","zh":"更好的工具可以提升質素，同時增加人們能做的範圍。"},{"en":"This phrase combines improvement with expansion.","zh":"這個短語結合改善與擴展。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":10},{"front":"predictive ability","meaning":"預測能力","examples":[{"en":"Research on Antarctica may improve our predictive ability.","zh":"關於南極洲的研究可能改善我們的預測能力。"},{"en":"Predictive ability is the power to forecast what is likely to happen.","zh":"predictive ability 指預測可能發生事情的能力。"},{"en":"A weather app has good predictive ability if it warns people before heavy rain arrives.","zh":"如果天氣應用程式能在大雨來臨前警告人們，它就有良好預測能力。"},{"en":"Better predictive ability helps farmers, governments, and families prepare earlier.","zh":"更好的預測能力幫助農民、政府和家庭更早作準備。"},{"en":"This phrase describes forecasting skill.","zh":"這個短語描述預報技能。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":10},{"front":"ocean’s surface temperature","meaning":"海洋表面溫度","examples":[{"en":"The ocean’s surface temperature results from several interacting factors.","zh":"海洋表面溫度由幾個互相作用的因素造成。"},{"en":"The ocean’s surface temperature is the temperature of the upper layer of seawater.","zh":"ocean’s surface temperature 指海水上層的溫度。"},{"en":"Swimmers notice surface temperature because it affects how warm the water feels.","zh":"游泳者會留意海洋表面溫度，因為它影響水感覺有多暖。"},{"en":"Surface temperature changes when sunlight, wind, deep water, and ice interact.","zh":"當陽光、風、深水和冰互相作用，表面溫度就會改變。"},{"en":"This phrase refers to the temperature at the top of the ocean.","zh":"這個短語指海洋頂層的溫度。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":11},{"front":"result from","meaning":"由……造成","examples":[{"en":"The ocean’s surface temperature results from the interplay between water, air and ice.","zh":"海洋表面溫度由水、空氣和冰之間的相互作用造成。"},{"en":"To result from something means to be caused by it.","zh":"result from something 指由某事造成。"},{"en":"A headache may result from lack of sleep, stress, or dehydration.","zh":"頭痛可能由睡眠不足、壓力或缺水造成。"},{"en":"Understanding what a problem results from helps people choose the right solution.","zh":"理解問題由甚麼造成，有助人們選擇正確解決方法。"},{"en":"This phrase links an outcome with its cause.","zh":"這個短語把結果與原因連繫起來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":11},{"front":"the interplay between","meaning":"……之間的相互作用","examples":[{"en":"The surface temperature results from the interplay between deep-water temperature, air temperature and ice.","zh":"表面溫度由深水溫度、氣溫和冰之間的相互作用造成。"},{"en":"The interplay between things is the way they interact and affect one another.","zh":"interplay between things 指事物互相作用和互相影響的方式。"},{"en":"A student’s progress may depend on the interplay between effort, sleep, teaching, and confidence.","zh":"學生進步可能取決於努力、睡眠、教學和信心之間的相互作用。"},{"en":"When several factors interact, the final result may be hard to predict from one factor alone.","zh":"當幾個因素互相作用，最終結果可能難以只從一個因素預測。"},{"en":"This phrase is useful for explaining complex systems.","zh":"這個短語適合解釋複雜系統。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":11},{"front":"deep-water temperature","meaning":"深水溫度","examples":[{"en":"Deep-water temperature helps determine ocean surface temperature.","zh":"深水溫度有助決定海洋表面溫度。"},{"en":"Deep-water temperature is the temperature of water far below the ocean surface.","zh":"deep-water temperature 指海洋表面以下很深處的水溫。"},{"en":"Scientists measure deep-water temperature to understand how heat moves through the ocean.","zh":"科學家量度深水溫度，以理解熱量如何穿過海洋移動。"},{"en":"If deep water rises, it can change the temperature near the surface.","zh":"如果深水上升，它可以改變表面附近溫度。"},{"en":"This phrase refers to temperature below the visible top layer of the sea.","zh":"這個短語指海面可見表層以下的溫度。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":11},{"front":"sea ice forms","meaning":"海冰形成","examples":[{"en":"Each winter, millions of square kilometres of sea ice forms.","zh":"每年冬天，數百萬平方公里的海冰形成。"},{"en":"Sea ice forms when seawater freezes at the ocean surface.","zh":"sea ice forms 指海水在海洋表面結冰。"},{"en":"Sea ice may form near a polar coast when temperatures fall for many days.","zh":"當氣溫連續多日下降，海冰可能在極地海岸附近形成。"},{"en":"As sea ice forms, it changes the movement of heat, salt, and water.","zh":"隨着海冰形成，它會改變熱量、鹽分和水的移動。"},{"en":"This phrase describes the creation of frozen seawater.","zh":"這個短語描述冰凍海水的形成。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":11},{"front":"lock up huge quantities of heat","meaning":"鎖住大量熱量","examples":[{"en":"Sea ice locks up huge quantities of heat close to the continent.","zh":"海冰在靠近大陸的地方鎖住大量熱量。"},{"en":"To lock up huge quantities of heat means to trap or store a large amount of heat.","zh":"lock up huge quantities of heat 指困住或儲存大量熱量。"},{"en":"Thick walls can lock up heat in a house and keep rooms warm after sunset.","zh":"厚牆可以在屋內鎖住熱量，讓房間在日落後仍保持溫暖。"},{"en":"When heat is locked up, it is not released quickly into the surrounding environment.","zh":"當熱量被鎖住，它不會很快釋放到周圍環境。"},{"en":"This phrase describes heat being stored rather than freely moving.","zh":"這個短語描述熱量被儲存，而不是自由流動。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":11},{"front":"huge quantities of","meaning":"大量的……","examples":[{"en":"Sea ice locks up huge quantities of heat.","zh":"海冰鎖住大量熱量。"},{"en":"Huge quantities of something means very large amounts of it.","zh":"huge quantities of something 指非常大量的某物。"},{"en":"A school cafeteria may prepare huge quantities of food before a sports day.","zh":"學校飯堂可能在運動會前準備大量食物。"},{"en":"When huge quantities of water or heat move, they can affect large systems.","zh":"當大量水或熱量移動，它們可以影響大型系統。"},{"en":"This phrase emphasises scale and amount.","zh":"這個短語強調規模和數量。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":11},{"front":"close to the continent","meaning":"靠近大陸","examples":[{"en":"Sea ice forms close to Antarctica.","zh":"海冰在靠近南極洲的地方形成。"},{"en":"Close to the continent means near the landmass rather than far out at sea.","zh":"close to the continent 指靠近大陸陸塊，而不是遠離海岸。"},{"en":"Fishing boats close to the coast may return quickly if the weather worsens.","zh":"靠近海岸的漁船如果天氣轉差，可以較快返回。"},{"en":"Ice forming near a continent can strongly affect coastal waters.","zh":"在大陸附近形成的冰可以強烈影響沿岸水域。"},{"en":"This phrase gives a location near land.","zh":"這個短語給出靠近陸地的位置。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":11},{"front":"start to unravel","meaning":"開始拆解；逐步弄清","examples":[{"en":"Scientists are starting to unravel the influence of sea ice.","zh":"科學家正開始逐步弄清海冰的影響。"},{"en":"To start to unravel something means to begin understanding a complicated problem or mystery.","zh":"start to unravel something 指開始理解複雜問題或謎團。"},{"en":"A doctor may start to unravel a patient’s illness after comparing symptoms and test results.","zh":"醫生比較症狀和檢查結果後，可能開始弄清病人的疾病。"},{"en":"Complex questions are unravelled step by step as evidence accumulates.","zh":"隨着證據累積，複雜問題會一步步被拆解。"},{"en":"This phrase suggests gradual explanation of something difficult.","zh":"這個短語表示逐步解釋困難事情。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":11},{"front":"the influence of sea ice on","meaning":"海冰對……的影響","examples":[{"en":"Researchers study the influence of sea ice on weather.","zh":"研究人員研究海冰對天氣的影響。"},{"en":"The influence of sea ice on something means the effect sea ice has on it.","zh":"influence of sea ice on something 指海冰對某事物產生的影響。"},{"en":"Scientists may study the influence of trees on city temperature.","zh":"科學家可能研究樹木對城市氣溫的影響。"},{"en":"Sea ice can influence weather by changing heat exchange between ocean and air.","zh":"海冰可以透過改變海洋與空氣之間的熱量交換來影響天氣。"},{"en":"This phrase connects one factor with its effect on another system.","zh":"這個短語把一個因素與其對另一系統的影響連繫起來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":11},{"front":"the weather that is experienced","meaning":"……所經歷的天氣","examples":[{"en":"Sea ice affects the weather that is experienced in southern Australia.","zh":"海冰影響澳洲南部所經歷的天氣。"},{"en":"The weather that is experienced means the actual weather people feel or observe in a place.","zh":"weather that is experienced 指某地人們實際感受或觀察到的天氣。"},{"en":"The weather experienced by commuters matters more to them than distant weather statistics.","zh":"對通勤者來說，他們實際經歷的天氣比遙遠天氣統計更重要。"},{"en":"If a climate factor changes, people may experience different rain, heat, or wind.","zh":"如果氣候因素改變，人們可能經歷不同雨量、熱度或風。"},{"en":"This phrase focuses on real local weather conditions.","zh":"這個短語著重真實本地天氣情況。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":12},{"front":"southern Australia","meaning":"澳洲南部","examples":[{"en":"Sea ice may influence weather in southern Australia.","zh":"海冰可能影響澳洲南部的天氣。"},{"en":"Southern Australia means the southern part of Australia.","zh":"southern Australia 指澳洲南部地區。"},{"en":"Farmers in southern Australia may watch seasonal forecasts before planting crops.","zh":"澳洲南部的農民可能在種植作物前查看季節預報。"},{"en":"Weather in southern Australia can be affected by ocean and atmospheric conditions nearby and far away.","zh":"澳洲南部天氣可以受附近和遠方的海洋及大氣條件影響。"},{"en":"This phrase gives a broad regional location.","zh":"這個短語給出廣泛地區位置。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":12},{"front":"in another way","meaning":"以另一種方式","examples":[{"en":"In another way, sea ice affects ecosystems far beyond Antarctica.","zh":"以另一種方式，海冰影響遠超南極洲的生態系統。"},{"en":"In another way means from a different angle or through a different effect.","zh":"in another way 指從另一角度或透過另一種影響。"},{"en":"Exercise helps health directly; in another way, it also improves mood and confidence.","zh":"運動直接幫助健康；以另一種方式，它也改善心情和信心。"},{"en":"This phrase introduces a second method or aspect of influence.","zh":"這個短語引入第二種影響方式或層面。"},{"en":"It helps writers organise multiple effects of one thing.","zh":"它幫助作者組織同一事物的多種影響。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":12},{"front":"the extent of sea ice","meaning":"海冰範圍","examples":[{"en":"The extent of sea ice influences animal food chains.","zh":"海冰範圍影響動物食物鏈。"},{"en":"The extent of sea ice means how large an area the sea ice covers.","zh":"extent of sea ice 指海冰覆蓋的面積有多大。"},{"en":"Scientists compare the extent of sea ice from year to year using maps and satellite data.","zh":"科學家使用地圖和衛星數據比較每年的海冰範圍。"},{"en":"A larger or smaller ice extent can affect animals that depend on icy habitats.","zh":"海冰範圍較大或較小，可以影響依賴冰上棲息地的動物。"},{"en":"This phrase focuses on area covered, not thickness alone.","zh":"這個短語著重覆蓋面積，而不只是厚度。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":12},{"front":"exert an influence far beyond","meaning":"對遠超……的地方產生影響","examples":[{"en":"The extent of sea ice exerts an influence far beyond Antarctica.","zh":"海冰範圍對遠超南極洲的地方產生影響。"},{"en":"To exert an influence far beyond a place means to affect areas much farther away than that place.","zh":"exert an influence far beyond a place 指影響遠遠超出某地的區域。"},{"en":"A major port can exert an influence far beyond its city by shaping trade across a whole region.","zh":"主要港口可以透過塑造整個地區的貿易，對遠超其城市的地方產生影響。"},{"en":"Environmental changes in one region can influence animals, weather, and economies elsewhere.","zh":"一個地區的環境變化可以影響其他地方的動物、天氣和經濟。"},{"en":"This phrase stresses wide-reaching impact.","zh":"這個短語強調影響範圍廣泛。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":12},{"front":"Antarctic krill","meaning":"南極磷蝦","examples":[{"en":"Antarctic krill breed well when sea ice is extensive.","zh":"當海冰範圍廣泛，南極磷蝦繁殖良好。"},{"en":"Antarctic krill are small marine animals that live in Antarctic waters and form a major food source.","zh":"Antarctic krill 指生活在南極水域的小型海洋動物，並構成主要食物來源。"},{"en":"Whales and penguins depend on Antarctic krill because they are abundant and nutritious.","zh":"鯨魚和企鵝依賴南極磷蝦，因為牠們數量多且有營養。"},{"en":"If krill numbers fall, many animals higher in the food chain may struggle.","zh":"如果磷蝦數量下降，食物鏈較高層的許多動物可能難以生存。"},{"en":"This phrase names a key species in Antarctic ecosystems.","zh":"這個短語命名南極生態系統中的關鍵物種。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":12},{"front":"shrimp-like crustaceans","meaning":"像蝦的小型甲殼類動物","examples":[{"en":"Krill are small shrimp-like crustaceans.","zh":"磷蝦是像蝦的小型甲殼類動物。"},{"en":"Shrimp-like crustaceans are small animals with hard outer shells that look similar to shrimp.","zh":"shrimp-like crustaceans 指有硬外殼、外形像蝦的小動物。"},{"en":"A child may recognise a shrimp-like animal because of its small body and many legs.","zh":"孩子可能因小身體和多隻腳而認出像蝦的動物。"},{"en":"Crustaceans are important in food chains because many fish and birds eat them.","zh":"甲殼類動物在食物鏈中很重要，因為許多魚和鳥都會吃牠們。"},{"en":"This phrase explains what krill look like and what type of animal they are.","zh":"這個短語解釋磷蝦長甚麼樣子，以及屬於哪類動物。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":12},{"front":"staple diet for","meaning":"……的主食","examples":[{"en":"Krill are the staple diet for whales, penguins and many fish.","zh":"磷蝦是鯨魚、企鵝和許多魚類的主食。"},{"en":"A staple diet for an animal is the main food it regularly eats.","zh":"staple diet for an animal 指某動物經常吃的主要食物。"},{"en":"Rice is a staple diet for many people in parts of Asia.","zh":"米飯是亞洲部分地區許多人的主食。"},{"en":"If a staple diet disappears, animals may fail to grow, migrate, or reproduce normally.","zh":"如果主食消失，動物可能無法正常成長、遷徙或繁殖。"},{"en":"This phrase identifies the main food source.","zh":"這個短語指出主要食物來源。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":12},{"front":"baleen whales","meaning":"鬚鯨","examples":[{"en":"Baleen whales depend on Antarctic krill for food.","zh":"鬚鯨依賴南極磷蝦作食物。"},{"en":"Baleen whales are whales that filter small animals from seawater instead of using teeth to catch large prey.","zh":"baleen whales 指用鬚板從海水中過濾小動物，而不是用牙齒捕捉大型獵物的鯨魚。"},{"en":"A documentary may show baleen whales opening their mouths to take in huge amounts of water and krill.","zh":"紀錄片可能展示鬚鯨張開口吸入大量海水和磷蝦。"},{"en":"Because they depend on tiny prey, changes in krill numbers can affect them strongly.","zh":"因為牠們依賴微小獵物，磷蝦數量變化可以強烈影響牠們。"},{"en":"This phrase names a group of filter-feeding whales.","zh":"這個短語命名一類濾食性鯨魚。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":12},{"front":"flighted seabirds","meaning":"會飛的海鳥","examples":[{"en":"Flighted seabirds feed on Antarctic krill.","zh":"會飛的海鳥以南極磷蝦為食。"},{"en":"Flighted seabirds are sea birds that can fly, unlike birds such as penguins.","zh":"flighted seabirds 指能飛的海鳥，不同於企鵝等鳥類。"},{"en":"Albatrosses and petrels are examples of flighted seabirds.","zh":"信天翁和海燕是會飛海鳥的例子。"},{"en":"If krill become scarce, flighted seabirds may need to travel farther for food.","zh":"如果磷蝦變少，會飛的海鳥可能需要飛更遠覓食。"},{"en":"This phrase distinguishes flying seabirds from non-flying ones.","zh":"這個短語把能飛海鳥與不能飛海鳥區分開。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":12},{"front":"breed well","meaning":"繁殖良好","examples":[{"en":"Krill breed well in years when sea ice is extensive.","zh":"在海冰範圍廣泛的年份，磷蝦繁殖良好。"},{"en":"To breed well means to reproduce successfully and produce many young.","zh":"breed well 指成功繁殖並產生許多後代。"},{"en":"Mosquitoes breed well in warm water that is left standing for days.","zh":"蚊子在放置多日的暖水中繁殖良好。"},{"en":"Animals breed well when food, shelter, and environmental conditions are favourable.","zh":"當食物、庇護和環境條件有利，動物會繁殖良好。"},{"en":"This phrase describes successful reproduction.","zh":"這個短語描述成功繁殖。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":13},{"front":"sea ice is extensive","meaning":"海冰範圍廣泛","examples":[{"en":"Krill breed well when sea ice is extensive.","zh":"當海冰範圍廣泛，磷蝦繁殖良好。"},{"en":"Sea ice is extensive means sea ice covers a large area.","zh":"sea ice is extensive 指海冰覆蓋大面積。"},{"en":"When snow cover is extensive, schools may close roads and cancel outdoor events.","zh":"當積雪範圍廣泛，學校可能封路並取消戶外活動。"},{"en":"Extensive sea ice can provide conditions that help some Antarctic species reproduce.","zh":"廣泛海冰可以提供有助某些南極物種繁殖的條件。"},{"en":"This phrase describes wide coverage, not necessarily thick ice.","zh":"這個短語描述覆蓋範圍廣，而不一定指冰很厚。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":13},{"front":"migrate between the hemispheres","meaning":"在兩個半球之間遷徙","examples":[{"en":"Many baleen whales and seabirds migrate between the hemispheres.","zh":"許多鬚鯨和海鳥在兩個半球之間遷徙。"},{"en":"To migrate between the hemispheres means to travel seasonally between the Northern and Southern Hemispheres.","zh":"migrate between the hemispheres 指在北半球和南半球之間季節性移動。"},{"en":"Some birds migrate between warm and cold regions to find food and suitable breeding areas.","zh":"有些鳥類在溫暖和寒冷地區之間遷徙，以尋找食物和合適繁殖地。"},{"en":"Long migrations depend on reliable food sources along the way.","zh":"長途遷徙依賴沿途可靠食物來源。"},{"en":"This phrase describes large-scale movement across half the planet.","zh":"這個短語描述跨越半個地球的大規模移動。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":13},{"front":"be less abundant","meaning":"較少；不豐富","examples":[{"en":"When krill are less abundant, whales and seabirds do not thrive.","zh":"當磷蝦較少時，鯨魚和海鳥不會繁盛。"},{"en":"To be less abundant means to exist in smaller numbers or amounts than before.","zh":"be less abundant 指數量或份量比以前少。"},{"en":"If library seats are less abundant during exam season, students arrive earlier to get one.","zh":"如果考試季節圖書館座位較少，學生會更早到達搶位。"},{"en":"When food becomes less abundant, animals may compete more fiercely.","zh":"當食物變得較少，動物可能競爭更激烈。"},{"en":"This phrase describes reduced availability.","zh":"這個短語描述可用數量減少。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":13},{"front":"thrive","meaning":"茁壯成長；繁盛","examples":[{"en":"Animals do not thrive when their food is scarce.","zh":"當食物稀少時，動物不會繁盛。"},{"en":"To thrive means to grow, develop, or live successfully.","zh":"thrive 指成功成長、發展或生活。"},{"en":"A child may thrive in a school where teachers give clear support and encouragement.","zh":"孩子在老師給予清楚支援和鼓勵的學校中可能茁壯成長。"},{"en":"Plants thrive when they receive enough light, water, and nutrients.","zh":"植物在獲得足夠光、水和養分時會茁壯成長。"},{"en":"This word means doing very well, not merely surviving.","zh":"這個詞意思是發展得很好，而不只是生存。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":13},{"front":"the circulatory system of","meaning":"……的循環系統","examples":[{"en":"The circulatory system of the world’s oceans is like a huge conveyor belt.","zh":"全球海洋的循環系統像一條巨大輸送帶。"},{"en":"The circulatory system of something is the way materials move around inside a connected system.","zh":"circulatory system of something 指物質在相互連接的系統內移動的方式。"},{"en":"Roads and railways can act like the circulatory system of a city by moving people and goods.","zh":"道路和鐵路可以像城市的循環系統一樣運送人和貨物。"},{"en":"If a circulatory system slows, distant parts of the system may receive less supply.","zh":"如果循環系統變慢，系統中遙遠部分可能獲得較少供應。"},{"en":"This phrase uses the body’s blood system as a metaphor.","zh":"這個短語用人體血液系統作比喻。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":13},{"front":"the world’s oceans","meaning":"全球海洋","examples":[{"en":"The world’s oceans are connected by global circulation.","zh":"全球海洋由全球環流連接。"},{"en":"The world’s oceans means all the major oceans on Earth considered together.","zh":"world’s oceans 指把地球上所有主要海洋合起來看。"},{"en":"Plastic waste can spread through the world’s oceans if it enters currents.","zh":"如果塑膠廢物進入洋流，就可以在全球海洋中擴散。"},{"en":"Because the oceans are connected, a change in one region can affect another.","zh":"因為海洋互相連接，一個地區的變化可以影響另一個地區。"},{"en":"This phrase treats the oceans as one global system.","zh":"這個短語把海洋視為一個全球系統。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":13},{"front":"conveyor belt","meaning":"輸送帶","examples":[{"en":"The ocean’s circulatory system is like a huge conveyor belt.","zh":"海洋循環系統像一條巨大輸送帶。"},{"en":"A conveyor belt is a moving band that carries objects from one place to another.","zh":"conveyor belt 指把物件從一處運到另一處的移動帶。"},{"en":"In a supermarket, a conveyor belt moves groceries toward the cashier.","zh":"在超級市場，輸送帶把貨品送向收銀員。"},{"en":"The metaphor helps explain how ocean circulation carries water and nutrients around the planet.","zh":"這個比喻幫助解釋海洋環流如何把水和養分運送到全球。"},{"en":"This phrase suggests steady movement and transport.","zh":"這個短語表示穩定移動和運送。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":13},{"front":"dissolved minerals and nutrients","meaning":"已溶解的礦物質和養分","examples":[{"en":"Ocean circulation moves dissolved minerals and nutrients.","zh":"海洋環流移動已溶解的礦物質和養分。"},{"en":"Dissolved minerals and nutrients are useful substances mixed into water that support life.","zh":"dissolved minerals and nutrients 指混入水中、支持生命的有用物質。"},{"en":"Plants in an aquarium need dissolved nutrients to grow well.","zh":"水族箱中的植物需要已溶解養分才能生長良好。"},{"en":"When ocean currents move nutrients upward, marine life near the surface can increase.","zh":"當洋流把養分向上移動，表層附近海洋生物可以增加。"},{"en":"This phrase refers to substances carried invisibly in water.","zh":"這個短語指在水中看不見地被運送的物質。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":13},{"front":"from one hemisphere to the other","meaning":"從一個半球到另一個半球","examples":[{"en":"Ocean circulation moves water from one hemisphere to the other.","zh":"海洋環流把水從一個半球移到另一個半球。"},{"en":"From one hemisphere to the other means from one half of the Earth to the opposite half.","zh":"from one hemisphere to the other 指從地球一半移到另一半。"},{"en":"Birds may migrate from one hemisphere to the other as seasons change.","zh":"鳥類可能隨季節變化從一個半球遷徙到另一個半球。"},{"en":"Movement between hemispheres can connect climates and ecosystems far apart.","zh":"半球之間的移動可以連接相距遙遠的氣候和生態系統。"},{"en":"This phrase describes very large-scale global movement.","zh":"這個短語描述非常大規模的全球移動。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":13},{"front":"abyssal depths","meaning":"深海深處","examples":[{"en":"Ocean circulation moves nutrients from the ocean’s abyssal depths to the surface.","zh":"海洋環流把養分從海洋深海深處移到表面。"},{"en":"Abyssal depths are extremely deep parts of the ocean.","zh":"abyssal depths 指海洋中極深的部分。"},{"en":"Deep-sea creatures live in abyssal depths where sunlight does not reach.","zh":"深海生物生活在陽光到達不了的深海深處。"},{"en":"Nutrients from deep water can support surface life when currents bring them upward.","zh":"當洋流把深水帶上來，深水中的養分可以支持表層生命。"},{"en":"This phrase describes the dark, deep ocean.","zh":"這個短語描述黑暗而深邃的海洋。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":14},{"front":"the longest current in the world","meaning":"世界最長洋流","examples":[{"en":"The ACC is the longest current in the world.","zh":"南極繞極流是世界最長洋流。"},{"en":"The longest current in the world means no other ocean current extends farther in length.","zh":"longest current in the world 指沒有其他洋流在長度上更長。"},{"en":"A river described as the longest in a country is being compared with all other rivers there.","zh":"被描述為全國最長的河流，是與該國所有其他河流比較。"},{"en":"Great length matters because a current can connect distant ocean regions.","zh":"長度重要，因為洋流可以連接遙遠海域。"},{"en":"This phrase gives a record-like comparison.","zh":"這個短語給出類似紀錄的比較。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":14},{"front":"have the largest flow","meaning":"流量最大","examples":[{"en":"The ACC has the largest flow of any current.","zh":"南極繞極流在所有洋流中流量最大。"},{"en":"To have the largest flow means to move the greatest amount of water compared with others.","zh":"have the largest flow 指與其他相比移動最多水量。"},{"en":"A main drain may have the largest flow after heavy rain because many smaller drains feed into it.","zh":"大雨後，主排水渠可能因許多小渠流入而流量最大。"},{"en":"Large flow can give a current great influence over ocean circulation.","zh":"大流量可以令洋流對海洋環流產生巨大影響。"},{"en":"This phrase compares volume of moving water.","zh":"這個短語比較移動水量。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":14},{"front":"deep flows","meaning":"深層水流","examples":[{"en":"The ACC joins the deep flows of the Atlantic, Indian and Pacific Oceans.","zh":"南極繞極流連接大西洋、印度洋和太平洋的深層水流。"},{"en":"Deep flows are movements of water far below the ocean surface.","zh":"deep flows 指海洋表面以下很深處的水流運動。"},{"en":"Scientists use instruments to measure deep flows that ships cannot see from above.","zh":"科學家使用儀器量度船隻從上方看不見的深層水流。"},{"en":"Deep flows carry heat, oxygen, and nutrients through the ocean system.","zh":"深層水流在海洋系統中運送熱量、氧氣和養分。"},{"en":"This phrase refers to underwater movement, not surface waves.","zh":"這個短語指水下流動，而不是表面波浪。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":14},{"front":"be joined to form","meaning":"被連接起來形成","examples":[{"en":"The deep flows are joined to form part of global circulation.","zh":"深層水流被連接起來，形成全球環流的一部分。"},{"en":"To be joined to form something means separate parts are connected and together create a larger system.","zh":"be joined to form something 指不同部分被連接，並共同創造更大系統。"},{"en":"Small paths may be joined to form a longer walking trail through a park.","zh":"小路可以被連接起來，形成穿過公園的較長步道。"},{"en":"When separate flows join, they can create a continuous route for water and nutrients.","zh":"當分開的水流連接，它們可以為水和養分形成連續路線。"},{"en":"This phrase describes parts combining into a whole.","zh":"這個短語描述部分結合成整體。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":14},{"front":"a single global thermohaline circulation","meaning":"單一全球溫鹽環流","examples":[{"en":"The oceans form a single global thermohaline circulation.","zh":"海洋形成單一全球溫鹽環流。"},{"en":"A single global thermohaline circulation is a worldwide ocean circulation driven by differences in temperature and salinity.","zh":"single global thermohaline circulation 指由溫度和鹽度差異推動的全球海洋環流。"},{"en":"A science teacher may compare thermohaline circulation to a slow global conveyor belt.","zh":"科學老師可能把溫鹽環流比作緩慢的全球輸送帶。"},{"en":"Changes in heat or salt can alter how this circulation moves water around the planet.","zh":"熱量或鹽分變化可以改變這個環流如何在全球移動水。"},{"en":"This phrase names a large connected ocean system.","zh":"這個短語命名一個大型互連海洋系統。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":14},{"front":"howling katabatic winds","meaning":"呼嘯的下坡風","examples":[{"en":"Howling katabatic winds scour ice from the sea’s surface.","zh":"呼嘯的下坡風把海面上的冰刮走。"},{"en":"Howling katabatic winds are loud, powerful downhill winds blowing from cold high areas.","zh":"howling katabatic winds 指從寒冷高地向下吹、聲音響亮且力量強大的風。"},{"en":"Workers in polar stations may stay indoors when howling winds make movement dangerous.","zh":"當呼嘯強風令移動危險，極地站工作人員可能留在室內。"},{"en":"Such winds can push sea ice away and expose open water.","zh":"這類風可以把海冰推走，露出開放水面。"},{"en":"This phrase combines sound, force, and cold downhill movement.","zh":"這個短語結合聲音、力量和寒冷下坡流動。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":14},{"front":"scour the ice off","meaning":"把冰刮走","examples":[{"en":"The winds scour the ice off patches of the sea’s surface.","zh":"這些風把一片片海面上的冰刮走。"},{"en":"To scour the ice off means to scrape, clear, or force ice away from a surface.","zh":"scour the ice off 指把冰從表面刮走、清除或強行移開。"},{"en":"Strong wind can scour snow off a road and pile it against a wall.","zh":"強風可以把道路上的雪刮走，並堆到牆邊。"},{"en":"When ice is scoured off seawater, open patches can appear.","zh":"當海冰被刮走，開放水面區域可以出現。"},{"en":"This phrase describes forceful removal by wind or water.","zh":"這個短語描述由風或水造成的強力移除。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":14},{"front":"patches of the sea’s surface","meaning":"一片片海面","examples":[{"en":"Winds clear patches of the sea’s surface.","zh":"風清除一片片海面。"},{"en":"Patches of the sea’s surface are separate small areas on top of the ocean.","zh":"patches of the sea’s surface 指海洋表面上一塊塊分開的小區域。"},{"en":"From a plane, passengers may see patches of sunlight on the sea’s surface.","zh":"從飛機上，乘客可能看到海面上一片片陽光。"},{"en":"Wind can clear some patches while leaving nearby areas covered with ice.","zh":"風可以清除某些區域，同時附近地方仍被冰覆蓋。"},{"en":"This phrase describes parts of the ocean surface, not the whole ocean.","zh":"這個短語描述海洋表面的部分，而不是整個海洋。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":14},{"front":"ice-locked lagoons","meaning":"被冰封住的潟湖","examples":[{"en":"The winds leave large ice-locked lagoons called polynyas.","zh":"這些風留下被稱為冰間湖的大型冰封潟湖。"},{"en":"Ice-locked lagoons are areas of water enclosed or surrounded by ice.","zh":"ice-locked lagoons 指被冰包圍或封住的水域。"},{"en":"A lake trapped behind frozen edges may look like an ice-locked lagoon in winter.","zh":"冬天被冰邊困住的湖泊，可能看起來像被冰封住的潟湖。"},{"en":"Such water areas matter because new ice can form there repeatedly.","zh":"這類水域很重要，因為新冰可以在那裡反覆形成。"},{"en":"This phrase describes water spaces held within ice.","zh":"這個短語描述被冰包圍的水域。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":14},{"front":"polynyas","meaning":"冰間湖；冰穴水域","examples":[{"en":"Polynyas are large ice-locked lagoons in Antarctic waters.","zh":"冰間湖是南極水域中大型被冰封住的潟湖。"},{"en":"Polynyas are open or partly open water areas within sea ice.","zh":"polynyas 指海冰中開放或部分開放的水域。"},{"en":"Scientists study polynyas because they can be places where new sea ice forms quickly.","zh":"科學家研究冰間湖，因為它們可以是新海冰快速形成的地方。"},{"en":"Polynyas can affect salt, heat, and ocean circulation near Antarctica.","zh":"冰間湖可以影響南極洲附近的鹽分、熱量和海洋環流。"},{"en":"This word names a special polar water feature.","zh":"這個詞命名一種特殊極地水域特徵。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":15},{"front":"fresh sea ice forms","meaning":"新海冰形成","examples":[{"en":"Fresh sea ice forms in polynyas.","zh":"新海冰在冰間湖中形成。"},{"en":"Fresh sea ice forms means new sea ice begins to freeze and appear.","zh":"fresh sea ice forms 指新的海冰開始結冰並出現。"},{"en":"Fresh ice may form on a pond overnight when temperatures fall below freezing.","zh":"當氣溫跌至冰點以下，池塘上可能一夜之間形成新冰。"},{"en":"When new sea ice forms, salt is left behind in the surrounding water.","zh":"當新海冰形成，鹽分會留在周圍水中。"},{"en":"This phrase describes the creation of new ice, not old ice drifting in.","zh":"這個短語描述新冰形成，而不是舊冰漂入。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":15},{"front":"be continuously stripped away","meaning":"不斷被剝離","examples":[{"en":"Fresh sea ice is continuously stripped away by the wind.","zh":"新海冰不斷被風剝離。"},{"en":"To be continuously stripped away means to be removed again and again without stopping for long.","zh":"be continuously stripped away 指一次又一次被移除，中間幾乎不停。"},{"en":"Paint on an old gate may be stripped away by wind and rain over many years.","zh":"舊閘門上的油漆可能多年來被風雨不斷剝落。"},{"en":"If new ice is stripped away repeatedly, open water can freeze again and again.","zh":"如果新冰反覆被剝離，開放水面就可以一次又一次結冰。"},{"en":"This phrase describes repeated removal from a surface.","zh":"這個短語描述表面物質反覆被移除。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":15},{"front":"be blown up to","meaning":"被吹送多達","examples":[{"en":"Sea ice may be blown up to 90 km in a single day.","zh":"海冰可能在一天內被吹送多達 90 公里。"},{"en":"To be blown up to a distance means to be moved by wind as far as that distance.","zh":"be blown up to a distance 指被風吹送到最遠某個距離。"},{"en":"Light plastic rubbish may be blown up to several streets away on a windy day.","zh":"在大風日子，輕膠垃圾可能被吹到幾條街外。"},{"en":"Strong wind can move floating ice quickly across the sea surface.","zh":"強風可以把漂浮冰快速移過海面。"},{"en":"This phrase gives the maximum distance something can be carried by wind.","zh":"這個短語給出某物被風吹送的最大距離。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":15},{"front":"in a single day","meaning":"在一天內","examples":[{"en":"Sea ice can be blown 90 km in a single day.","zh":"海冰可以在一天內被吹送 90 公里。"},{"en":"In a single day means within one day only.","zh":"in a single day 指只在一天之內。"},{"en":"A student can finish a short project in a single day if the instructions are clear.","zh":"如果指示清楚，學生可以在一天內完成短項目。"},{"en":"When something moves far in a single day, the process is unusually fast.","zh":"當某物在一天內移動很遠，這個過程就異常快速。"},{"en":"This phrase emphasises a short time period.","zh":"這個短語強調很短的時間。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":15},{"front":"fresh water freezes into ice","meaning":"只有淡水會結冰","examples":[{"en":"Only fresh water freezes into ice.","zh":"只有淡水會結冰。"},{"en":"Fresh water freezes into ice means water without much salt becomes solid when it is cold enough.","zh":"fresh water freezes into ice 指鹽分不多的水在足夠寒冷時變成固體。"},{"en":"Water in a freezer tray freezes into ice cubes overnight.","zh":"冰格中的水會一夜之間凍成冰粒。"},{"en":"When sea ice forms, much of the salt remains in the liquid water below.","zh":"當海冰形成，大部分鹽分仍留在下方液態水中。"},{"en":"This phrase explains the link between freezing and salt separation.","zh":"這個短語解釋結冰與鹽分分離之間的關係。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":15},{"front":"increasingly salty and dense","meaning":"越來越鹹和稠密","examples":[{"en":"The remaining water becomes increasingly salty and dense.","zh":"剩下的水變得越來越鹹和稠密。"},{"en":"Increasingly salty and dense means becoming saltier and heavier for its volume over time.","zh":"increasingly salty and dense 指隨時間變得鹽分更高，且同體積下更重。"},{"en":"Soup becomes saltier if water boils away but salt stays behind.","zh":"如果水煮走但鹽留下，湯會變得更鹹。"},{"en":"Saltier, denser water tends to sink below lighter water.","zh":"更鹹、更稠密的水傾向下沉到較輕的水下方。"},{"en":"This phrase explains why Antarctic water can move downward.","zh":"這個短語解釋南極水為何會向下移動。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":15},{"front":"sink until","meaning":"下沉直至","examples":[{"en":"The dense water sinks until it spills over the continental shelf.","zh":"稠密的水下沉直至溢過大陸架。"},{"en":"Sink until means move downward and continue until a particular point or event happens.","zh":"sink until 指向下移動並持續到某個點或事件發生。"},{"en":"A stone sinks until it reaches the bottom of a pond.","zh":"石頭下沉直至到達池塘底部。"},{"en":"Dense water keeps sinking because it is heavier than the water around it.","zh":"稠密水會繼續下沉，因為它比周圍水更重。"},{"en":"This phrase links downward movement with a stopping point or next action.","zh":"這個短語把向下移動與停止點或下一個動作連繫起來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":15},{"front":"spill over","meaning":"溢過；流越","examples":[{"en":"Dense water spills over the continental shelf.","zh":"稠密水溢過大陸架。"},{"en":"To spill over means to flow over an edge or boundary.","zh":"spill over 指流過邊緣或界線。"},{"en":"Water may spill over the edge of a full cup if someone bumps the table.","zh":"如果有人撞到桌子，滿杯水可能溢過杯邊。"},{"en":"In the ocean, dense water can spill over a shelf and move into deeper areas.","zh":"在海洋中，稠密水可以流越大陸架並進入更深水域。"},{"en":"This phrase describes overflow or movement beyond an edge.","zh":"這個短語描述溢出或越過邊緣的移動。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":15},{"front":"continental shelf","meaning":"大陸架","examples":[{"en":"Cold salty water spills over the continental shelf.","zh":"寒冷鹹水溢過大陸架。"},{"en":"A continental shelf is the shallow underwater edge of a continent before the sea floor drops deeper.","zh":"continental shelf 指大陸邊緣較淺的水下區域，之後海床會下降到更深處。"},{"en":"Fishing often happens over continental shelves because marine life can be abundant there.","zh":"漁業常在大陸架上進行，因為那裡海洋生物可能很豐富。"},{"en":"When dense water moves beyond the shelf, it can enter deeper ocean circulation.","zh":"當稠密水越過大陸架，它可以進入更深層海洋環流。"},{"en":"This phrase refers to the submerged edge of a continent.","zh":"這個短語指大陸的水下邊緣。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":15},{"front":"carry more oxygen than","meaning":"比……帶有更多氧氣","examples":[{"en":"Cold water carries more oxygen than warm water.","zh":"冷水比暖水帶有更多氧氣。"},{"en":"To carry more oxygen than something means to contain or transport a greater amount of oxygen.","zh":"carry more oxygen than something 指含有或運送比某物更多的氧氣。"},{"en":"Cold streams can carry more oxygen than warm ponds, which helps some fish survive.","zh":"冷溪流可以比暖池塘帶有更多氧氣，這有助某些魚類生存。"},{"en":"Oxygen-rich water supports marine life when it rises or circulates.","zh":"富氧水上升或循環時，可以支持海洋生命。"},{"en":"This phrase compares how much oxygen different waters can hold.","zh":"這個短語比較不同水體能含有多少氧氣。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":16},{"front":"well into","meaning":"深入至","examples":[{"en":"Cold water rises well into the Northern Hemisphere.","zh":"冷水上升並深入至北半球。"},{"en":"Well into a place means far inside or deep into that area.","zh":"well into a place 指深入或遠遠進入某區域。"},{"en":"A long traffic jam may stretch well into the next town.","zh":"長長的交通擠塞可能延伸到下一個城鎮深處。"},{"en":"When a water mass moves well into another hemisphere, its influence travels far.","zh":"當水團深入另一半球，它的影響會傳得很遠。"},{"en":"This phrase emphasises depth or distance into a region.","zh":"這個短語強調進入某區域的深度或距離。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":16},{"front":"reoxygenate and revitalise","meaning":"重新充氧並恢復活力","examples":[{"en":"Cold water reoxygenates and revitalises the ocean.","zh":"冷水為海洋重新充氧並恢復活力。"},{"en":"To reoxygenate and revitalise something means to add oxygen again and bring back energy or life.","zh":"reoxygenate and revitalise something 指重新加入氧氣，並帶回能量或生命力。"},{"en":"Opening windows can reoxygenate a stuffy classroom and make students feel more alert.","zh":"打開窗戶可以為悶焗課室重新充氧，令學生更精神。"},{"en":"Oxygen-rich water can support biological activity in parts of the ocean.","zh":"富氧水可以支持海洋部分地區的生物活動。"},{"en":"This phrase connects oxygen renewal with restored life and productivity.","zh":"這個短語把氧氣更新與生命力和生產力恢復連繫起來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":16},{"front":"biological productivity","meaning":"生物生產力","examples":[{"en":"The northern oceans’ biological productivity depends partly on Antarctica.","zh":"北方海洋的生物生產力部分取決於南極洲。"},{"en":"Biological productivity is the amount of living growth produced in an ecosystem.","zh":"biological productivity 指生態系統中產生的生命增長量。"},{"en":"A pond with many plants and small animals has high biological productivity.","zh":"有許多植物和小動物的池塘具有高生物生產力。"},{"en":"Nutrients and oxygen can increase biological productivity by supporting more life.","zh":"養分和氧氣可以透過支持更多生命來增加生物生產力。"},{"en":"This phrase refers to how much life a system can produce and support.","zh":"這個短語指系統能產生和支持多少生命。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":16},{"front":"owe much to","meaning":"很大程度上歸功於；有賴於","examples":[{"en":"The state of the northern oceans owes much to what happens in Antarctica.","zh":"北方海洋的狀態很大程度上有賴於南極洲發生的事情。"},{"en":"To owe much to something means to depend greatly on it or be strongly shaped by it.","zh":"owe much to something 指很大程度上依賴某事，或被某事強烈塑造。"},{"en":"A student’s confidence may owe much to a patient teacher who gives useful feedback.","zh":"學生的信心可能很大程度上歸功於一位有耐性的老師給予有用回饋。"},{"en":"If one system owes much to another, changes in the second system can affect the first.","zh":"如果一個系統很大程度上有賴於另一個系統，第二個系統的變化可以影響第一個。"},{"en":"This phrase means “be strongly influenced by” or “depend on”.","zh":"這個短語意思是「受到強烈影響」或「依賴」。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":16},{"front":"what happens in","meaning":"在……發生的事情","examples":[{"en":"The northern oceans owe much to what happens in the Antarctic.","zh":"北方海洋很大程度上有賴於南極發生的事情。"},{"en":"What happens in a place means the events, processes, or changes occurring there.","zh":"what happens in a place 指在某地發生的事件、過程或變化。"},{"en":"What happens in a school classroom can affect a child’s confidence at home.","zh":"在學校課室發生的事情可以影響孩子在家的信心。"},{"en":"Events in one place can matter elsewhere when systems are connected.","zh":"當系統互相連接，一地發生的事件可以影響其他地方。"},{"en":"This phrase points to local processes that have wider effects.","zh":"這個短語指出具有更廣泛影響的本地過程。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":16},{"front":"Reading Passage 2","meaning":"閱讀文章二","examples":[{"en":"Reading Passage 2 has six paragraphs labelled A to F.","zh":"閱讀文章二有六段，標記為 A 至 F。"},{"en":"Reading Passage 2 means the second reading text in a test or exercise.","zh":"Reading Passage 2 指測驗或練習中的第二篇閱讀文章。"},{"en":"Students should check the paragraph letters before answering questions on Reading Passage 2.","zh":"學生回答閱讀文章二的題目前，應檢查段落字母。"},{"en":"Knowing which passage is being used prevents answers from being taken from the wrong text.","zh":"知道正在使用哪篇文章，可以避免從錯誤文本中取答案。"},{"en":"This phrase identifies a specific reading section.","zh":"這個短語指出特定閱讀部分。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":16},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"Students decide which paragraph contains each piece of information.","zh":"學生判斷哪一段包含每項資料。"},{"en":"Which paragraph contains means students must identify the paragraph where certain information appears.","zh":"which paragraph contains 指學生必須找出某資料出現在哪一段。"},{"en":"In a reading test, students scan names, dates, and key ideas to find which paragraph contains the answer.","zh":"在閱讀測驗中，學生掃讀人名、日期和關鍵概念，以找出哪段包含答案。"},{"en":"This task checks location skills as well as understanding.","zh":"這類題目測試定位能力和理解能力。"},{"en":"This phrase is common in matching-information questions.","zh":"這個短語常見於資料配對題。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":16},{"front":"the following information","meaning":"以下資料","examples":[{"en":"The task asks students to locate the following information.","zh":"題目要求學生定位以下資料。"},{"en":"The following information means the details listed after the instruction.","zh":"following information 指指示後列出的資料細節。"},{"en":"Students should read the following information carefully before scanning the passage.","zh":"學生在掃讀文章前，應仔細閱讀以下資料。"},{"en":"Misreading one detail can send students to the wrong paragraph.","zh":"誤讀一個細節可能令學生找錯段落。"},{"en":"This phrase introduces information that must be found in the text.","zh":"這個短語引入必須在文本中找到的資料。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":16},{"front":"an example of research used to","meaning":"用作……的研究例子","examples":[{"en":"The question asks for an example of research used to develop a forecasting system.","zh":"題目要求找出用作開發預報系統的研究例子。"},{"en":"An example of research used to do something is a specific study or finding applied for that purpose.","zh":"example of research used to do something 指為某目的而應用的具體研究或發現。"},{"en":"Research on sleep may be used to design a better school timetable.","zh":"關於睡眠的研究可能被用來設計更好的學校時間表。"},{"en":"When research is used practically, it moves from theory into real decision-making.","zh":"當研究被實際使用，它就由理論進入真正決策。"},{"en":"This phrase asks students to find a concrete application of research.","zh":"這個短語要求學生找出研究的具體應用。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":16},{"front":"agricultural weather-forecasting system","meaning":"農業天氣預報系統","examples":[{"en":"The research helps develop an agricultural weather-forecasting system.","zh":"這項研究有助開發農業天氣預報系統。"},{"en":"An agricultural weather-forecasting system predicts weather conditions useful for farming.","zh":"agricultural weather-forecasting system 指預測對農業有用的天氣情況的系統。"},{"en":"Farmers may use such a system to decide when to plant, water, or reduce livestock.","zh":"農民可能使用這類系統決定何時種植、灌溉或減少牲畜。"},{"en":"Better farm forecasts can reduce losses caused by drought, storms, or poor rainfall.","zh":"更好的農業預報可以減少旱災、風暴或降雨不足造成的損失。"},{"en":"This phrase links weather prediction with agricultural planning.","zh":"這個短語把天氣預測與農業規劃連繫起來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":17},{"front":"an explanation of how","meaning":"關於……如何發生的解釋","examples":[{"en":"The paragraph gives an explanation of how sea ice revitalises oceans.","zh":"該段給出海冰如何令海洋恢復活力的解釋。"},{"en":"An explanation of how something happens tells the process or mechanism behind it.","zh":"explanation of how something happens 指說明某事背後的過程或機制。"},{"en":"A teacher may give an explanation of how photosynthesis helps plants make food.","zh":"老師可能解釋光合作用如何幫助植物製造食物。"},{"en":"Process explanations help students understand causes, steps, and results.","zh":"過程解釋幫助學生理解原因、步驟和結果。"},{"en":"This phrase asks for more than a simple fact; it asks for the method.","zh":"這個短語要求的不只是簡單事實，而是方法。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":17},{"front":"revitalise the world’s oceans","meaning":"令全球海洋恢復活力","examples":[{"en":"Antarctic sea ice helps revitalise the world’s oceans.","zh":"南極海冰有助令全球海洋恢復活力。"},{"en":"To revitalise the world’s oceans means to restore energy, oxygen, nutrients, or life to global ocean systems.","zh":"revitalise the world’s oceans 指為全球海洋系統恢復能量、氧氣、養分或生命力。"},{"en":"Cleaning a polluted river can revitalise it by bringing back fish and plants.","zh":"清理受污染河流可以透過帶回魚類和植物令它恢復活力。"},{"en":"Oxygen-rich water can revitalise marine ecosystems by supporting more biological activity.","zh":"富氧水可以透過支持更多生物活動令海洋生態系統恢復活力。"},{"en":"This phrase suggests restoring life and productivity.","zh":"這個短語表示恢復生命力和生產力。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":17},{"front":"a description of a food chain","meaning":"食物鏈的描述","examples":[{"en":"The passage includes a description of a food chain involving krill.","zh":"文章包括一段涉及磷蝦的食物鏈描述。"},{"en":"A description of a food chain explains which organisms eat which others in an ecosystem.","zh":"description of a food chain 指解釋生態系統中哪些生物吃哪些生物。"},{"en":"A simple food chain may show grass being eaten by rabbits and rabbits being eaten by foxes.","zh":"簡單食物鏈可能顯示草被兔子吃，兔子被狐狸吃。"},{"en":"Food-chain descriptions help students see how one species affects many others.","zh":"食物鏈描述幫助學生看見一個物種如何影響許多其他物種。"},{"en":"This phrase asks for an explanation of feeding relationships.","zh":"這個短語要求解釋進食關係。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":17},{"front":"affect animals’ survival patterns","meaning":"影響動物的生存模式","examples":[{"en":"The food chain affects animals’ survival patterns.","zh":"食物鏈影響動物的生存模式。"},{"en":"To affect animals’ survival patterns means to change how animals live, reproduce, migrate, or die.","zh":"affect animals’ survival patterns 指改變動物如何生活、繁殖、遷徙或死亡。"},{"en":"If fish disappear from a lake, birds that eat them may change their survival patterns.","zh":"如果湖中魚類消失，以魚為食的鳥類可能改變生存模式。"},{"en":"Food supply affects survival because animals need enough energy to breed and move.","zh":"食物供應影響生存，因為動物需要足夠能量來繁殖和移動。"},{"en":"This phrase links food chains with animal success or decline.","zh":"這個短語把食物鏈與動物成功或衰退連繫起來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":17},{"front":"a reference to","meaning":"提及","examples":[{"en":"The question asks for a reference to an extreme temperature and a powerful wind.","zh":"題目要求找出對極端溫度和強勁寒風的提及。"},{"en":"A reference to something is a mention of it in speech or writing.","zh":"reference to something 指在說話或文字中提到某事。"},{"en":"A passage may include a reference to a scientist without giving a full biography.","zh":"文章可能提及一位科學家，但沒有提供完整傳記。"},{"en":"In reading tasks, students locate references by scanning for key words or related meanings.","zh":"在閱讀題中，學生透過掃讀關鍵詞或相關意思定位提及之處。"},{"en":"This phrase asks students to find where something is mentioned.","zh":"這個短語要求學生找出某事在哪裡被提到。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":17},{"front":"extreme temperature","meaning":"極端溫度","examples":[{"en":"The passage refers to an extreme temperature recorded in Antarctica.","zh":"文章提到南極洲記錄到的極端溫度。"},{"en":"Extreme temperature means a temperature that is unusually high or low.","zh":"extreme temperature 指異常高或異常低的溫度。"},{"en":"A heatwave can bring extreme temperatures that make outdoor work dangerous.","zh":"熱浪可以帶來極端高溫，令戶外工作危險。"},{"en":"Extreme cold can damage equipment and threaten human health.","zh":"極端寒冷可以損壞設備並威脅人類健康。"},{"en":"This phrase describes temperature far outside normal conditions.","zh":"這個短語描述遠超正常條件的溫度。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":17},{"front":"powerful cold wind","meaning":"強勁寒風","examples":[{"en":"The passage refers to a powerful cold wind in Antarctica.","zh":"文章提到南極洲的強勁寒風。"},{"en":"A powerful cold wind is a strong wind that carries very low temperatures.","zh":"powerful cold wind 指帶有極低溫度的強風。"},{"en":"A powerful cold wind can make waiting for a bus feel painful in winter.","zh":"冬天等巴士時，強勁寒風可以令人感到痛苦。"},{"en":"Strong cold winds increase danger because they remove body heat quickly.","zh":"強勁寒風會增加危險，因為它迅速帶走身體熱量。"},{"en":"This phrase describes both force and coldness.","zh":"這個短語同時描述力量和寒冷。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":17},{"front":"former view of","meaning":"對……的昔日看法","examples":[{"en":"The first paragraph describes the former view of Antarctica.","zh":"第一段描述對南極洲的昔日看法。"},{"en":"Former view of something means the way people used to think about it.","zh":"former view of something 指人們過去如何看待某事。"},{"en":"The former view of online learning was that it was only a backup option.","zh":"對網上學習的昔日看法是它只是一種後備選項。"},{"en":"Former views can change when new evidence or new experience appears.","zh":"當新證據或新經驗出現，昔日看法可以改變。"},{"en":"This phrase contrasts past opinion with current understanding.","zh":"這個短語把過去意見與現在理解作對比。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":17},{"front":"forgotten and insignificant continent","meaning":"被遺忘且無足輕重的大陸","examples":[{"en":"Antarctica was once viewed as a forgotten and insignificant continent.","zh":"南極洲曾被視為被遺忘且無足輕重的大陸。"},{"en":"A forgotten and insignificant continent is a landmass people think is unimportant and rarely consider.","zh":"forgotten and insignificant continent 指人們認為不重要且很少考慮的大陸。"},{"en":"A small rural town may feel forgotten and insignificant if government services never reach it.","zh":"如果政府服務從不到達，小鄉鎮可能感到被遺忘且無足輕重。"},{"en":"New research can show that a place once ignored is actually very important.","zh":"新研究可以顯示曾被忽視的地方其實非常重要。"},{"en":"This phrase describes a dismissive old view.","zh":"這個短語描述一種輕視性的舊看法。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":17},{"front":"match each statement with","meaning":"將每項陳述與……配對","examples":[{"en":"Students match each statement with the correct factor.","zh":"學生將每項陳述與正確因素配對。"},{"en":"To match each statement with something means to connect every statement to the right answer or category.","zh":"match each statement with something 指把每個陳述連接到正確答案或類別。"},{"en":"In a vocabulary task, students match each word with its meaning.","zh":"在詞彙題中，學生把每個單字與其意思配對。"},{"en":"Matching requires careful comparison, not guessing from one repeated word.","zh":"配對需要仔細比較，而不是靠一個重複字猜測。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":18},{"front":"correct factor","meaning":"正確因素","examples":[{"en":"The task asks students to choose the correct factor from the list.","zh":"題目要求學生從列表中選出正確因素。"},{"en":"The correct factor is the right cause, influence, or item that matches the statement.","zh":"correct factor 指與陳述相配的正確原因、影響或項目。"},{"en":"In a science question, the correct factor may be temperature, pressure, or light.","zh":"在科學題中，正確因素可能是溫度、壓力或光。"},{"en":"Choosing the correct factor requires understanding what causes the result.","zh":"選出正確因素需要理解甚麼造成結果。"},{"en":"This phrase identifies the answer category in a matching task.","zh":"這個短語指出配對題中的答案類別。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":18},{"front":"enormous size","meaning":"巨大面積；龐大規模","examples":[{"en":"Antarctica’s enormous size influences the climate.","zh":"南極洲的巨大面積影響氣候。"},{"en":"Enormous size means extremely great physical size or scale.","zh":"enormous size 指極大的實體大小或規模。"},{"en":"A school with an enormous size may need several entrances and many administrators.","zh":"規模龐大的學校可能需要多個入口和許多行政人員。"},{"en":"Something very large can affect systems around it simply because of its scale.","zh":"非常巨大的事物單靠其規模就可以影響周圍系統。"},{"en":"This phrase emphasises great magnitude.","zh":"這個短語強調巨大程度。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":18},{"front":"influence the climate","meaning":"影響氣候","examples":[{"en":"Antarctica’s mass and temperature influence the climate.","zh":"南極洲的質量和溫度影響氣候。"},{"en":"To influence the climate means to affect long-term weather patterns.","zh":"influence the climate 指影響長期天氣模式。"},{"en":"Large forests can influence the climate by storing carbon and releasing moisture.","zh":"大型森林可以透過儲存碳和釋放水分來影響氣候。"},{"en":"If a region influences climate, changes there may affect rainfall and temperature elsewhere.","zh":"如果一個地區影響氣候，那裡的變化可能影響其他地方的降雨和溫度。"},{"en":"This phrase describes an effect on large-scale weather systems.","zh":"這個短語描述對大規模天氣系統的影響。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":18},{"front":"circulate under the influence of","meaning":"在……影響下環流","examples":[{"en":"The ACC circulates under the influence of westerly winds.","zh":"南極繞極流在西風影響下環流。"},{"en":"To circulate under the influence of something means to move around because that force affects its movement.","zh":"circulate under the influence of something 指因某力量影響其移動而循環流動。"},{"en":"Air in a classroom may circulate under the influence of fans and open windows.","zh":"課室中的空氣可能在風扇和開窗影響下循環。"},{"en":"If wind controls water movement, changes in wind can affect the circulation pattern.","zh":"如果風控制水的移動，風的變化可以影響環流模式。"},{"en":"This phrase links movement with an external driving force.","zh":"這個短語把移動與外部推動力連繫起來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":18},{"front":"winds blowing from the west","meaning":"從西方吹來的風","examples":[{"en":"The current is influenced by winds blowing from the west.","zh":"這股洋流受從西方吹來的風影響。"},{"en":"Winds blowing from the west are winds that come from the west and move eastward.","zh":"winds blowing from the west 指從西方而來並向東移動的風。"},{"en":"Sailors may adjust their route if strong winds blowing from the west push the boat off course.","zh":"如果從西方吹來的強風把船推離航線，水手可能調整路線。"},{"en":"Wind direction matters because it can shape waves, currents, and weather.","zh":"風向很重要，因為它可以塑造海浪、洋流和天氣。"},{"en":"This phrase explains the direction from which wind comes.","zh":"這個短語解釋風從哪個方向來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":18},{"front":"an index based on","meaning":"基於……的指數","examples":[{"en":"The Southern Oscillation Index is based on air pressure.","zh":"南方濤動指數是基於氣壓的指數。"},{"en":"An index based on something is a measurement system built from that factor.","zh":"index based on something 指由某因素建立的量度系統。"},{"en":"A school performance index may be based on attendance, exam results, and student progress.","zh":"學校表現指數可能基於出席率、考試成績和學生進步。"},{"en":"The chosen basis affects what the index can show and what it may miss.","zh":"所選基礎會影響該指數能顯示甚麼和可能遺漏甚麼。"},{"en":"This phrase explains what data a measurement uses.","zh":"這個短語解釋某量度使用甚麼數據。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":18},{"front":"air pressure","meaning":"氣壓","examples":[{"en":"The index uses air pressure differences between Darwin and Tahiti.","zh":"該指數使用達爾文與大溪地之間的氣壓差。"},{"en":"Air pressure is the weight or force of air pressing on the Earth’s surface.","zh":"air pressure 指空氣壓在地球表面的重量或力量。"},{"en":"Weather maps often show air pressure to help predict wind and storms.","zh":"天氣圖常顯示氣壓，以幫助預測風和風暴。"},{"en":"Differences in air pressure can create wind and influence rainfall.","zh":"氣壓差可以形成風並影響降雨。"},{"en":"This phrase refers to a measurable atmospheric condition.","zh":"這個短語指可量度的大氣條件。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":18},{"front":"help predict","meaning":"有助預測","examples":[{"en":"Ocean temperature can help predict rainfall in Australia.","zh":"海洋溫度可以有助預測澳洲降雨量。"},{"en":"To help predict something means to provide information that makes a future event easier to forecast.","zh":"help predict something 指提供資訊，使未來事件較容易預測。"},{"en":"Past exam scores can help predict which students may need extra support.","zh":"過往考試成績可以有助預測哪些學生可能需要額外支援。"},{"en":"A useful signal does not guarantee perfect prediction, but it improves planning.","zh":"有用信號不保證完美預測，但能改善規劃。"},{"en":"This phrase means to support forecasting.","zh":"這個短語意思是支援預報。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":18},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter for each question.","zh":"學生為每題選出正確字母。"},{"en":"To choose the correct letter means to select the answer option marked by the right letter.","zh":"choose the correct letter 指選出由正確字母標示的答案選項。"},{"en":"In multiple-choice questions, students should check whether the answer is A, B, C, or D.","zh":"在多項選擇題中，學生應檢查答案是 A、B、C 還是 D。"},{"en":"Copying the wrong letter can lose marks even when the student understands the answer.","zh":"即使學生理解答案，抄錯字母也可能失分。"},{"en":"This phrase gives an exam-format instruction.","zh":"這個短語給出考試格式指示。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":18},{"front":"the writer intends to","meaning":"作者意圖","examples":[{"en":"The question asks what the writer intends to do in paragraph B.","zh":"題目問作者在 B 段意圖做甚麼。"},{"en":"The writer intends to means the writer’s purpose is to do something.","zh":"writer intends to 指作者的目的在於做某事。"},{"en":"In an article, the writer may intend to warn readers rather than simply entertain them.","zh":"在文章中，作者可能意圖警告讀者，而不只是娛樂他們。"},{"en":"Understanding intention helps students choose answers about purpose and tone.","zh":"理解意圖幫助學生選擇關於目的和語氣的答案。"},{"en":"This phrase focuses on why the writer includes a paragraph or detail.","zh":"這個短語著重作者為何加入某段或某細節。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":19},{"front":"a central topic in","meaning":"……中的中心話題","examples":[{"en":"The question asks whether Antarctica has become a central topic in media discussions.","zh":"題目問南極洲是否已成為媒體討論中的中心話題。"},{"en":"A central topic in a discussion is one of the main subjects people talk about.","zh":"central topic in a discussion 指人們討論的主要主題之一。"},{"en":"Mental health has become a central topic in many school meetings.","zh":"精神健康已成為許多學校會議中的中心話題。"},{"en":"A topic becomes central when it appears repeatedly and affects many decisions.","zh":"當一個議題反覆出現並影響許多決策，它就會成為中心話題。"},{"en":"This phrase means a main focus, not a side issue.","zh":"這個短語意思是主要焦點，而不是旁枝議題。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":19},{"front":"global warming","meaning":"全球暖化","examples":[{"en":"Antarctica is often discussed in relation to global warming.","zh":"南極洲常被放在全球暖化的關係中討論。"},{"en":"Global warming is the long-term rise in Earth’s average temperature.","zh":"global warming 指地球平均溫度長期上升。"},{"en":"Students may study global warming by looking at ice melt, heatwaves, and sea-level rise.","zh":"學生可能透過研究融冰、熱浪和海平面上升來學習全球暖化。"},{"en":"Global warming can affect weather, ecosystems, agriculture, and coastal cities.","zh":"全球暖化可以影響天氣、生態系統、農業和沿岸城市。"},{"en":"This phrase refers to a major climate change process.","zh":"這個短語指主要氣候變化過程。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":19},{"front":"vast sea ice","meaning":"廣闊海冰","examples":[{"en":"The question refers to Antarctica’s vast sea ice.","zh":"題目提到南極洲的廣闊海冰。"},{"en":"Vast sea ice means sea ice covering an extremely large area.","zh":"vast sea ice 指覆蓋極大面積的海冰。"},{"en":"Satellite images can show vast sea ice spreading across polar waters.","zh":"衛星影像可以顯示廣闊海冰在極地水域擴展。"},{"en":"Large sea-ice areas can affect heat exchange, wildlife, and ocean circulation.","zh":"大面積海冰可以影響熱量交換、野生生物和海洋環流。"},{"en":"This phrase emphasises the great area covered by frozen seawater.","zh":"這個短語強調冰凍海水覆蓋的巨大範圍。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":19},{"front":"supply food to","meaning":"為……供應食物","examples":[{"en":"The question asks whether sea ice supplies food to living things.","zh":"題目問海冰是否為生物供應食物。"},{"en":"To supply food to living things means to provide them with something they can eat.","zh":"supply food to living things 指為生物提供可吃的東西。"},{"en":"School gardens can supply food to the canteen if vegetables are grown there.","zh":"如果學校花園種植蔬菜，就可以為飯堂供應食物。"},{"en":"In ecosystems, one species may supply food to many others.","zh":"在生態系統中，一個物種可以為許多其他物種供應食物。"},{"en":"This phrase describes the source of nutrition.","zh":"這個短語描述營養來源。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":19},{"front":"emphasise the significance of","meaning":"強調……的重要性","examples":[{"en":"The paragraph emphasises the significance of Antarctica to global systems.","zh":"該段強調南極洲對全球系統的重要性。"},{"en":"To emphasise the significance of something means to stress why it is important.","zh":"emphasise the significance of something 指強調某事為何重要。"},{"en":"A teacher may emphasise the significance of sleep before exams.","zh":"老師可能強調考試前睡眠的重要性。"},{"en":"Writers emphasise significance when readers might otherwise ignore an important point.","zh":"當讀者可能忽略重要點，作者就會強調其重要性。"},{"en":"This phrase means to highlight importance.","zh":"這個短語意思是突出重要性。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":19},{"front":"global climate and ocean currents","meaning":"全球氣候和洋流","examples":[{"en":"Antarctica is significant to global climate and ocean currents.","zh":"南極洲對全球氣候和洋流很重要。"},{"en":"Global climate and ocean currents mean worldwide weather patterns and the movement of seawater.","zh":"global climate and ocean currents 指全球天氣模式和海水流動。"},{"en":"Changes in ocean currents can affect global climate by moving heat around the planet.","zh":"洋流變化可以透過在地球上轉移熱量來影響全球氣候。"},{"en":"These systems connect distant regions, so one area can influence another.","zh":"這些系統連接遙遠地區，因此一個地區可以影響另一個地區。"},{"en":"This phrase links atmosphere and ocean movement at a global scale.","zh":"這個短語把大氣和海洋運動在全球尺度上連繫起來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":19},{"front":"geographical position","meaning":"地理位置","examples":[{"en":"The question mentions Antarctica’s geographical position.","zh":"題目提到南極洲的地理位置。"},{"en":"Geographical position means where a place is located on Earth.","zh":"geographical position 指某地在地球上的位置。"},{"en":"A city’s geographical position near a river can help trade but increase flood risk.","zh":"城市靠近河流的地理位置可以有利貿易，但增加水災風險。"},{"en":"Position matters because location affects climate, transport, and contact with other places.","zh":"位置很重要，因為地點影響氣候、交通和與其他地方的接觸。"},{"en":"This phrase refers to physical location.","zh":"這個短語指實體位置。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":19},{"front":"monitor the temperature of","meaning":"監測……的溫度","examples":[{"en":"Farmers may monitor the temperature of the Southern Ocean.","zh":"農民可能監測南冰洋的溫度。"},{"en":"To monitor the temperature of something means to measure and watch its temperature over time.","zh":"monitor the temperature of something 指隨時間量度並觀察某物溫度。"},{"en":"A nurse monitors the temperature of a patient to see whether a fever is rising.","zh":"護士監測病人體溫，以了解發燒是否加劇。"},{"en":"Monitoring helps people notice changes before they become serious.","zh":"監測幫助人們在變化變得嚴重前注意到它。"},{"en":"This phrase describes repeated checking, not one single measurement.","zh":"這個短語描述反覆檢查，而不是單次量度。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":19},{"front":"reduce economic losses","meaning":"減少經濟損失","examples":[{"en":"Accurate rainfall forecasts can help farmers reduce economic losses.","zh":"準確降雨預報可以幫助農民減少經濟損失。"},{"en":"To reduce economic losses means to lower the amount of money lost.","zh":"reduce economic losses 指降低損失的金錢數量。"},{"en":"A shop can reduce economic losses by ordering fewer goods before a quiet season.","zh":"商店可以在淡季前減少訂貨，以減少經濟損失。"},{"en":"Early warning helps businesses avoid waste and prepare for difficult conditions.","zh":"早期警告幫助企業避免浪費並為困難情況作準備。"},{"en":"This phrase describes cutting financial harm.","zh":"這個短語描述減少財務損害。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":19},{"front":"damaged grassland","meaning":"受損草地","examples":[{"en":"The question mentions damaged grassland after overgrazing.","zh":"題目提到過度放牧後的受損草地。"},{"en":"Damaged grassland is land where grass and soil have been harmed and cannot support animals well.","zh":"damaged grassland 指草和泥土受損、不能好好支持動物的土地。"},{"en":"A park can become damaged grassland if too many people walk across it every day.","zh":"如果太多人每天踩過公園草地，它可能變成受損草地。"},{"en":"Overgrazing damages grassland because plants are eaten faster than they can regrow.","zh":"過度放牧會損害草地，因為植物被吃掉的速度快過重新生長。"},{"en":"This phrase refers to weakened pasture or grassy land.","zh":"這個短語指變弱的牧場或草地。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":20},{"front":"recover after overgrazing","meaning":"在過度放牧後恢復","examples":[{"en":"Grassland may take decades to recover after overgrazing.","zh":"草地在過度放牧後可能需要數十年恢復。"},{"en":"To recover after overgrazing means to grow back and become healthy again after too many animals have eaten the grass.","zh":"recover after overgrazing 指太多動物吃掉草後，草地重新生長並恢復健康。"},{"en":"A field may recover slowly after overgrazing if rain returns and animals are moved elsewhere.","zh":"如果降雨恢復且牲畜被移到其他地方，田地可能在過度放牧後慢慢恢復。"},{"en":"Recovery can be slow because roots, soil, and plant cover may all be damaged.","zh":"復原可能很慢，因為根部、土壤和植物覆蓋都可能受損。"},{"en":"This phrase describes ecological repair after excessive grazing.","zh":"這個短語描述過度放牧後的生態修復。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":20},{"front":"prevent livestock from dying","meaning":"防止牲畜死亡","examples":[{"en":"The question asks whether monitoring ocean temperature prevents livestock from dying.","zh":"題目問監測海洋溫度是否防止牲畜死亡。"},{"en":"To prevent livestock from dying means to stop farm animals from dying.","zh":"prevent livestock from dying 指阻止農場動物死亡。"},{"en":"Farmers may store extra feed to prevent livestock from dying during drought.","zh":"農民可能儲存額外飼料，以在旱災期間防止牲畜死亡。"},{"en":"Good forecasts can help protect animals by guiding decisions before conditions worsen.","zh":"良好預報可以在情況惡化前引導決策，幫助保護動物。"},{"en":"This phrase focuses on avoiding animal deaths.","zh":"這個短語著重避免動物死亡。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":20},{"front":"whale and seabird numbers","meaning":"鯨魚和海鳥數量","examples":[{"en":"Whale and seabird numbers may decline when krill are less abundant.","zh":"當磷蝦較少時，鯨魚和海鳥數量可能下降。"},{"en":"Whale and seabird numbers means the population size of whales and seabirds.","zh":"whale and seabird numbers 指鯨魚和海鳥的種群數量。"},{"en":"Scientists may count whale and seabird numbers to check whether an ecosystem is healthy.","zh":"科學家可能統計鯨魚和海鳥數量，以檢查生態系統是否健康。"},{"en":"If a main food source decreases, animal numbers may fall over time.","zh":"如果主要食物來源減少，動物數量可能隨時間下降。"},{"en":"This phrase refers to population levels of animal groups.","zh":"這個短語指動物群體的數量水平。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":20},{"front":"decline","meaning":"下降","examples":[{"en":"Animal numbers may decline if food becomes scarce.","zh":"如果食物變得稀少，動物數量可能下降。"},{"en":"To decline means to decrease or become lower.","zh":"decline 指減少或變低。"},{"en":"A student’s marks may decline if they stop revising and sleep poorly.","zh":"如果學生停止溫習並睡得差，成績可能下降。"},{"en":"Numbers often decline when resources, health, or support become weaker.","zh":"當資源、健康或支援變弱，數量常會下降。"},{"en":"This word describes a downward trend.","zh":"這個詞描述向下趨勢。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":20},{"front":"killer-whale activity","meaning":"虎鯨活動","examples":[{"en":"The question mentions killer-whale activity around Antarctica.","zh":"題目提到南極洲周圍的虎鯨活動。"},{"en":"Killer-whale activity means the behaviour, movement, or hunting of killer whales in an area.","zh":"killer-whale activity 指虎鯨在某區域的行為、移動或捕食活動。"},{"en":"Scientists may record killer-whale activity by tracking where the animals swim and feed.","zh":"科學家可能透過追蹤虎鯨游動和覓食地點來記錄虎鯨活動。"},{"en":"Changes in prey or sea ice can affect where marine predators are active.","zh":"獵物或海冰變化可以影響海洋捕食者在哪裡活動。"},{"en":"This phrase refers to what killer whales do, not just how many exist.","zh":"這個短語指虎鯨做甚麼，而不只是數量多少。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":20},{"front":"correlate with","meaning":"與……相關","examples":[{"en":"The question asks whether seabird migration correlates with ocean salinity.","zh":"題目問海鳥遷徙是否與海水鹽度相關。"},{"en":"To correlate with something means to show a relationship or pattern connected with it.","zh":"correlate with something 指與某事顯示出關係或模式。"},{"en":"Exam performance may correlate with attendance if students who attend more usually score higher.","zh":"如果出席率較高的學生通常得分較高，考試表現可能與出席率相關。"},{"en":"Correlation does not always prove that one thing causes the other.","zh":"相關不一定證明一件事造成另一件事。"},{"en":"This phrase describes a measurable relationship between two factors.","zh":"這個短語描述兩個因素之間可量度的關係。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":20},{"front":"ocean salinity","meaning":"海水鹽度","examples":[{"en":"Ocean salinity increases when fresh water freezes into ice.","zh":"當淡水結成冰，海水鹽度會增加。"},{"en":"Ocean salinity is the amount of salt dissolved in seawater.","zh":"ocean salinity 指海水中溶解鹽分的含量。"},{"en":"A science class may test salinity by comparing fresh water with seawater.","zh":"科學課可能透過比較淡水和海水來測試鹽度。"},{"en":"Higher salinity can make water denser and affect whether it sinks or rises.","zh":"較高鹽度可以令水更稠密，並影響它下沉還是上升。"},{"en":"This phrase refers to salt concentration in the ocean.","zh":"這個短語指海洋中的鹽分濃度。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":20},{"front":"reduced sea ice","meaning":"減少了的海冰","examples":[{"en":"Reduced sea ice can make krill less productive.","zh":"減少了的海冰可以令磷蝦生產力下降。"},{"en":"Reduced sea ice means a smaller area or amount of sea ice than before.","zh":"reduced sea ice 指海冰面積或數量比以前少。"},{"en":"Reduced snow cover on a mountain can affect water supply in spring.","zh":"山上的積雪覆蓋減少可以影響春季供水。"},{"en":"If sea ice is reduced, animals that depend on icy conditions may struggle.","zh":"如果海冰減少，依賴冰上環境的動物可能難以生存。"},{"en":"This phrase describes a decline in sea-ice extent or amount.","zh":"這個短語描述海冰範圍或數量下降。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":20},{"front":"food source","meaning":"食物來源","examples":[{"en":"Krill are an important food source for whales and seabirds.","zh":"磷蝦是鯨魚和海鳥的重要食物來源。"},{"en":"A food source is something that provides food for a person, animal, or community.","zh":"food source 指為人、動物或社群提供食物的東西。"},{"en":"Rice is a major food source for many families in Asia.","zh":"米飯是亞洲許多家庭的主要食物來源。"},{"en":"If a food source disappears, animals may migrate, starve, or fail to reproduce.","zh":"如果食物來源消失，動物可能遷徙、挨餓或無法繁殖。"},{"en":"This phrase identifies where nutrition comes from.","zh":"這個短語指出營養從哪裡來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":20},{"front":"fail to reproduce","meaning":"未能繁殖","examples":[{"en":"The question asks whether seals fail to reproduce.","zh":"題目問海豹是否未能繁殖。"},{"en":"To fail to reproduce means to be unable to produce young successfully.","zh":"fail to reproduce 指無法成功產生後代。"},{"en":"Birds may fail to reproduce if there is not enough food for chicks.","zh":"如果沒有足夠食物餵養雛鳥，鳥類可能未能繁殖。"},{"en":"Failure to reproduce can cause animal populations to decline over time.","zh":"未能繁殖可以令動物種群隨時間下降。"},{"en":"This phrase describes unsuccessful breeding.","zh":"這個短語描述繁殖不成功。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":21},{"front":"ultimate effect","meaning":"最終影響","examples":[{"en":"The question asks about the ultimate effect of katabatic winds.","zh":"題目問下坡風的最終影響。"},{"en":"The ultimate effect is the final or most important result after a chain of events.","zh":"ultimate effect 指一連串事件後的最終或最重要結果。"},{"en":"The ultimate effect of poor sleep may be lower concentration and weaker exam results.","zh":"睡眠不足的最終影響可能是專注力下降和考試成績較弱。"},{"en":"Looking for the ultimate effect means following causes to their final outcome.","zh":"尋找最終影響意味着追蹤原因直到最後結果。"},{"en":"This phrase asks what something eventually leads to.","zh":"這個短語詢問某事最終導致甚麼。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":21},{"front":"increase the speed of","meaning":"增加……的速度","examples":[{"en":"The question asks whether winds increase the speed of the ocean current.","zh":"題目問風是否增加洋流速度。"},{"en":"To increase the speed of something means to make it move faster.","zh":"increase the speed of something 指令某物移動得更快。"},{"en":"A driver increases the speed of a car by pressing the accelerator.","zh":"司機按油門會增加汽車速度。"},{"en":"Stronger wind can increase the speed of surface water movement.","zh":"更強的風可以增加表層水移動速度。"},{"en":"This phrase describes making movement quicker.","zh":"這個短語描述令移動加快。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":21},{"front":"increase the salinity of","meaning":"增加……的鹽度","examples":[{"en":"Katabatic winds indirectly increase the salinity of surface water.","zh":"下坡風間接增加表層水的鹽度。"},{"en":"To increase the salinity of water means to make it contain more salt.","zh":"increase the salinity of water 指令水含有更多鹽分。"},{"en":"Evaporation can increase the salinity of a small pond if water leaves but salt remains.","zh":"如果水分蒸發但鹽留下，蒸發可以增加小池塘的鹽度。"},{"en":"Higher salinity can make water denser and more likely to sink.","zh":"較高鹽度可以令水更稠密，並更可能下沉。"},{"en":"This phrase describes raising salt concentration.","zh":"這個短語描述提高鹽分濃度。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":21},{"front":"surface water","meaning":"表層水","examples":[{"en":"The remaining surface water becomes saltier and denser.","zh":"剩餘的表層水變得更鹹和更稠密。"},{"en":"Surface water is water at the top layer of a sea, lake, river, or other body of water.","zh":"surface water 指海、湖、河或其他水體最上層的水。"},{"en":"Oil floating on surface water can be seen before it mixes or spreads.","zh":"漂浮在表層水上的油在混合或擴散前可以被看見。"},{"en":"Surface water changes quickly because it touches air, wind, and sunlight.","zh":"表層水變化很快，因為它接觸空氣、風和陽光。"},{"en":"This phrase refers to water near the top, not deep water.","zh":"這個短語指靠近頂層的水，而不是深水。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":21},{"front":"carry fresh ice into","meaning":"將新冰帶進……","examples":[{"en":"The question asks whether winds carry fresh ice into the oceans.","zh":"題目問風是否將新冰帶進海洋。"},{"en":"To carry fresh ice into a place means to move newly formed ice there.","zh":"carry fresh ice into a place 指把新形成的冰移到那裡。"},{"en":"Strong wind can carry loose snow into a doorway and block the entrance.","zh":"強風可以把鬆散雪吹進門口並堵塞入口。"},{"en":"In polar seas, wind can move new ice across the water surface.","zh":"在極地海域，風可以把新冰移過水面。"},{"en":"This phrase describes transport by wind or flow.","zh":"這個短語描述由風或水流造成的運送。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":21},{"front":"beyond the continental shelf","meaning":"越過大陸架","examples":[{"en":"Dense Antarctic water moves beyond the continental shelf.","zh":"稠密的南極水越過大陸架。"},{"en":"Beyond the continental shelf means past the shallow underwater edge of a continent into deeper ocean.","zh":"beyond the continental shelf 指越過大陸較淺的水下邊緣，進入更深海洋。"},{"en":"Fishing boats may stay on the shelf while research ships travel beyond the continental shelf.","zh":"漁船可能留在大陸架上，而研究船則航行越過大陸架。"},{"en":"Water moving beyond the shelf can enter deeper ocean circulation.","zh":"越過大陸架的水可以進入更深層海洋環流。"},{"en":"This phrase describes movement from shallow edge to deeper sea.","zh":"這個短語描述由淺邊緣移向深海。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":21},{"front":"an increase in","meaning":"……的增加","examples":[{"en":"An increase in salinity and density causes Antarctic water to sink.","zh":"鹽度和密度的增加導致南極水下沉。"},{"en":"An increase in something means a rise or growth in its amount, level, or degree.","zh":"increase in something 指某事物的數量、水平或程度上升。"},{"en":"An increase in homework may reduce students’ free time.","zh":"功課增加可能減少學生自由時間。"},{"en":"When one factor increases, it can cause other changes in a system.","zh":"當一個因素增加，它可以引起系統中的其他變化。"},{"en":"This phrase introduces something becoming greater.","zh":"這個短語引入某事變得更大。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":21},{"front":"salinity and density","meaning":"鹽度和密度","examples":[{"en":"Higher salinity and density make Antarctic water sink.","zh":"較高的鹽度和密度令南極水下沉。"},{"en":"Salinity and density mean the saltiness of water and how heavy it is for its volume.","zh":"salinity and density 指水的鹹度，以及同體積下有多重。"},{"en":"Science students may compare salinity and density by adding salt to fresh water.","zh":"科學學生可能透過向淡水加鹽來比較鹽度和密度。"},{"en":"When water becomes saltier and denser, it tends to move downward.","zh":"當水變得更鹹、更稠密，它傾向向下移動。"},{"en":"This phrase links salt concentration with physical heaviness.","zh":"這個短語把鹽分濃度與物理重量連繫起來。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":21},{"front":"due to global warming","meaning":"由於全球暖化","examples":[{"en":"The question asks whether rising temperature due to global warming causes the movement.","zh":"題目問由於全球暖化造成的氣溫上升是否導致該移動。"},{"en":"Due to global warming means caused by the long-term rise in Earth’s average temperature.","zh":"due to global warming 指由地球平均溫度長期上升造成。"},{"en":"Some coastal risks may increase due to global warming and sea-level rise.","zh":"一些沿岸風險可能由於全球暖化和海平面上升而增加。"},{"en":"When a change is due to global warming, it is linked to broader climate change.","zh":"當某變化由於全球暖化，它就與更廣泛的氣候變化相關。"},{"en":"This phrase identifies global warming as the cause.","zh":"這個短語指出全球暖化是原因。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":21},{"front":"melting of fresh ice","meaning":"新冰融化","examples":[{"en":"The question mentions the melting of fresh ice into the ocean.","zh":"題目提到新冰融化進入海洋。"},{"en":"Melting of fresh ice means fresh ice turning into liquid water.","zh":"melting of fresh ice 指新冰變成液態水。"},{"en":"The melting of ice cubes in a drink makes the drink colder and more watery.","zh":"飲品中的冰粒融化會令飲品更冷且水分更多。"},{"en":"When fresh ice melts into seawater, it can affect salinity near the surface.","zh":"當新冰融入海水，它可以影響表面附近的鹽度。"},{"en":"This phrase describes ice changing from solid to liquid.","zh":"這個短語描述冰由固體變成液體。"}],"source":"41 - Antarctica – in from the cold?.pdf","sourcePage":22}],"ielts/reading/passage-2/Practice 42":[{"front":"saving the British bitterns","meaning":"拯救英國麻鳽","examples":[{"en":"The passage describes the work involved in saving the British bitterns.","zh":"文章描述拯救英國麻鳽所涉及的工作。"},{"en":"Saving the British bitterns means protecting this bird species in the UK so its population can recover.","zh":"saving the British bitterns 指在英國保護這種鳥類，使其種群可以恢復。"},{"en":"Conservationists may save a rare bird by restoring wetlands, protecting nests, and monitoring numbers.","zh":"保育人士可能透過修復濕地、保護巢穴和監察數量來拯救稀有鳥類。"},{"en":"If the habitat improves, saving the British bitterns becomes more realistic because the birds have places to breed and feed.","zh":"如果棲息地改善，拯救英國麻鳽會更現實，因為鳥類有地方繁殖和覓食。"},{"en":"The phrase refers to a conservation effort, not simply rescuing one injured bird.","zh":"這個短語指保育工作，而不只是救一隻受傷的鳥。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":1},{"front":"breeding bitterns","meaning":"在英國繁殖的麻鳽","examples":[{"en":"Breeding bitterns became extinct in the UK by 1886.","zh":"在英國繁殖的麻鳽到1886年已經滅絕。"},{"en":"Breeding bitterns are bitterns that nest and produce young in a particular place.","zh":"breeding bitterns 指在某地築巢並繁殖後代的麻鳽。"},{"en":"A wetland may support breeding birds if it has safe nesting sites and enough food.","zh":"如果濕地有安全巢址和足夠食物，它可能支持繁殖鳥類。"},{"en":"If breeding bitterns disappear, the species may still visit the area but no longer raise young there.","zh":"如果繁殖麻鳽消失，該物種可能仍會到訪該區，但不再在那裏育幼。"},{"en":"The phrase focuses on reproduction, not just the presence of adult birds.","zh":"這個短語重點是繁殖，而不只是成年鳥出現。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":1},{"front":"become extinct","meaning":"滅絕","examples":[{"en":"Breeding bitterns became extinct in the UK by 1886.","zh":"在英國繁殖的麻鳽到1886年已經滅絕。"},{"en":"To become extinct means to die out completely in a place or worldwide.","zh":"become extinct 指在某地或全球完全消失。"},{"en":"A local plant may become extinct if its only habitat is destroyed by building work.","zh":"如果某本地植物唯一的棲息地被建築工程破壞，它可能滅絕。"},{"en":"When a species becomes extinct in one country, conservationists may try to bring it back from nearby populations.","zh":"當一個物種在某國滅絕，保育人士可能嘗試從附近種群把它帶回。"},{"en":"The phrase describes total disappearance, not a small decline.","zh":"這個短語描述完全消失，而不是小幅下降。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":1},{"front":"following recolonisation","meaning":"在重新定居之後","examples":[{"en":"Following recolonisation early in the 20th century, bittern numbers rose again.","zh":"在20世紀初重新定居之後，麻鳽數量再次上升。"},{"en":"Following recolonisation means after a species returns to live and breed in an area where it had disappeared.","zh":"following recolonisation 指某物種返回曾經消失的地區生活和繁殖之後。"},{"en":"Following recolonisation by wild birds, a restored wetland may become important again.","zh":"在野鳥重新定居之後，修復濕地可能再次變得重要。"},{"en":"If animals recolonise a habitat, their numbers may rise if conditions remain suitable.","zh":"如果動物重新定居某棲息地，而條件保持合適，牠們的數量可能上升。"},{"en":"The phrase describes what happens after a species comes back to an area.","zh":"這個短語描述物種回到某地之後發生的情況。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":1},{"front":"rise to a peak of","meaning":"上升至……的高峰","examples":[{"en":"The number of booming males rose to a peak of about 70 in the 1950s.","zh":"鳴叫雄鳥數量在1950年代上升至約70隻的高峰。"},{"en":"To rise to a peak of a number means to increase until reaching the highest point at that number.","zh":"rise to a peak of a number 指上升至某數字作為最高點。"},{"en":"A school club may rise to a peak of 80 members before exam season reduces attendance.","zh":"學校學會可能上升至80名會員的高峰，之後考試季令出席減少。"},{"en":"When a population rises to a peak, later figures may fall if conditions worsen.","zh":"當種群上升至高峰，如果環境惡化，之後數字可能下降。"},{"en":"The phrase describes the highest level reached after growth.","zh":"這個短語描述增長後達到的最高水平。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":1},{"front":"booming males","meaning":"鳴叫雄鳥","examples":[{"en":"There were about 70 booming males in the 1950s.","zh":"1950年代約有70隻鳴叫雄鳥。"},{"en":"Booming males are male bitterns identified by their deep booming calls during the breeding season.","zh":"booming males 指在繁殖季節以低沉鳴叫聲被辨認出的雄性麻鳽。"},{"en":"Birdwatchers may count booming males by listening carefully at dawn in reed beds.","zh":"觀鳥者可能在清晨於蘆葦地仔細聆聽，以點算鳴叫雄鳥。"},{"en":"Because male bitterns are hard to see, their calls help researchers estimate numbers.","zh":"因為雄性麻鳽很難看見，牠們的叫聲幫助研究人員估算數量。"},{"en":"The phrase refers to calling male birds, not males making ordinary noise.","zh":"這個短語指正在鳴叫的雄鳥，而不是普通發聲的雄鳥。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":1},{"front":"fall to fewer than","meaning":"下降至少於","examples":[{"en":"The number of booming males fell to fewer than 20 by the 1990s.","zh":"到1990年代，鳴叫雄鳥數量下降至少於20隻。"},{"en":"To fall to fewer than a number means to decrease until the total is below that number.","zh":"fall to fewer than a number 指下降至總數低於某數字。"},{"en":"A class may fall to fewer than ten students if many families move away.","zh":"如果許多家庭搬走，一班學生可能下降至少於十人。"},{"en":"If a bird population falls to fewer than 20 males, conservation action becomes urgent.","zh":"如果鳥類種群下降至少於20隻雄鳥，保育行動就變得迫切。"},{"en":"The phrase signals a serious drop below a clear threshold.","zh":"這個短語表示跌破清楚門檻的嚴重下降。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":1},{"front":"be in trouble","meaning":"處於困境","examples":[{"en":"By the late 1980s, it was clear that the bittern was in trouble.","zh":"到1980年代末，麻鳽明顯處於困境。"},{"en":"To be in trouble means to be facing serious difficulty or danger.","zh":"be in trouble 指正面對嚴重困難或危險。"},{"en":"A small shop may be in trouble if sales fall and rent keeps rising.","zh":"如果銷售下降而租金持續上升，小店可能處於困境。"},{"en":"When a species is in trouble, scientists need to find out why before it declines further.","zh":"當物種處於困境，科學家需要在它進一步下降前找出原因。"},{"en":"The phrase suggests a problem that needs action.","zh":"這個短語暗示需要採取行動的問題。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":1},{"front":"little information was available","meaning":"可用資料很少","examples":[{"en":"Little information was available on which to base recovery measures.","zh":"可用來制定復育措施的資料很少。"},{"en":"Little information was available means researchers had very few useful facts or data.","zh":"little information was available 指研究人員只有很少有用事實或數據。"},{"en":"A teacher may struggle to help a student if little information is available about the student’s difficulties.","zh":"如果關於學生困難的資料很少，老師可能很難幫助該學生。"},{"en":"Without enough information, conservation plans may be based on guesses rather than evidence.","zh":"沒有足夠資料，保育計劃可能基於猜測而不是證據。"},{"en":"The phrase explains why the first step was research.","zh":"這個短語解釋為何第一步是研究。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":1},{"front":"recovery measures","meaning":"復育措施","examples":[{"en":"Researchers needed information to base recovery measures on.","zh":"研究人員需要資料來制定復育措施。"},{"en":"Recovery measures are actions taken to help a declining species or system improve again.","zh":"recovery measures 指幫助正在下降的物種或系統再次改善的行動。"},{"en":"A school may introduce recovery measures after exam results fall, such as extra tutorials and feedback.","zh":"考試成績下降後，學校可能推出復原措施，例如額外導修和回饋。"},{"en":"For bitterns, recovery measures could include reed-bed management and better water control.","zh":"對麻鳽而言，復育措施可以包括蘆葦地管理和更好水位控制。"},{"en":"The phrase refers to practical steps designed to reverse decline.","zh":"這個短語指旨在逆轉下降的實際步驟。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":1},{"front":"cryptic plumage","meaning":"保護色羽毛","examples":[{"en":"Bitterns have cryptic plumage and a shy nature.","zh":"麻鳽有保護色羽毛和害羞警覺的習性。"},{"en":"Cryptic plumage is feather colouring that helps a bird blend into its surroundings.","zh":"cryptic plumage 指幫助鳥類融入周圍環境的羽毛顏色。"},{"en":"A bird with brown striped feathers may be hard to see among reeds because of cryptic plumage.","zh":"有棕色條紋羽毛的鳥，可能因保護色而在蘆葦中很難看見。"},{"en":"Camouflage makes monitoring harder because researchers cannot easily spot the bird by sight.","zh":"偽裝令監察更困難，因為研究人員不能輕易用視覺發現牠。"},{"en":"The phrase describes protective colouring, not bright display feathers.","zh":"這個短語描述保護色，而不是鮮艷展示羽毛。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":1},{"front":"shy nature","meaning":"害羞警覺的習性","examples":[{"en":"Bitterns have cryptic plumage and a shy nature.","zh":"麻鳽有保護色羽毛和害羞警覺的習性。"},{"en":"A shy nature means an animal tends to avoid people and remain hidden.","zh":"shy nature 指動物傾向避開人類並保持隱藏。"},{"en":"A shy cat may hide under the sofa when visitors arrive.","zh":"害羞的貓在訪客到來時可能躲在梳化下。"},{"en":"Because bitterns are shy, researchers often rely on sound rather than direct sightings.","zh":"因為麻鳽害羞警覺，研究人員常依靠聲音而不是直接目擊。"},{"en":"The phrase describes behaviour that makes the bird difficult to observe.","zh":"這個短語描述令鳥類難以觀察的行為。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":2},{"front":"remain hidden within","meaning":"隱藏在……之中","examples":[{"en":"Bitterns usually remain hidden within reed-bed vegetation.","zh":"麻鳽通常隱藏在蘆葦地植被之中。"},{"en":"To remain hidden within something means to stay inside it where others cannot easily see you.","zh":"remain hidden within something 指留在某物內部，使別人不容易看見。"},{"en":"A small animal may remain hidden within long grass when people walk nearby.","zh":"當人們走近時，小動物可能隱藏在長草中。"},{"en":"If a bird remains hidden, counting it by sight becomes unreliable.","zh":"如果鳥類保持隱藏，用肉眼點算就變得不可靠。"},{"en":"The phrase describes staying concealed inside a habitat.","zh":"這個短語描述在棲息地內保持隱蔽。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":2},{"front":"reed-bed vegetation","meaning":"蘆葦地植被","examples":[{"en":"Bitterns usually remain hidden within reed-bed vegetation.","zh":"麻鳽通常隱藏在蘆葦地植被之中。"},{"en":"Reed-bed vegetation is the plant growth, especially reeds, found in wetland reed beds.","zh":"reed-bed vegetation 指濕地蘆葦地中的植物生長，尤其是蘆葦。"},{"en":"A wetland with thick reed-bed vegetation can provide cover for nesting birds.","zh":"有濃密蘆葦地植被的濕地可以為築巢鳥類提供遮蔽。"},{"en":"If reed-bed vegetation dries out or becomes too dense, it may no longer suit bitterns.","zh":"如果蘆葦地植被乾涸或過於密集，它可能不再適合麻鳽。"},{"en":"The phrase refers to the plant structure of a reed habitat.","zh":"這個短語指蘆葦棲息地的植物結構。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":2},{"front":"first challenge","meaning":"首個挑戰","examples":[{"en":"The first challenge was to develop standard methods for monitoring bitterns.","zh":"首個挑戰是制定監察麻鳽的標準方法。"},{"en":"The first challenge is the first major problem that must be solved before further work can succeed.","zh":"first challenge 指在後續工作成功前必須先解決的第一個重大問題。"},{"en":"In a school project, the first challenge may be collecting reliable information.","zh":"在學校項目中，首個挑戰可能是收集可靠資料。"},{"en":"If researchers cannot count the birds, they cannot know whether conservation is working.","zh":"如果研究人員不能點算鳥類，就不能知道保育是否有效。"},{"en":"The phrase introduces the first practical obstacle.","zh":"這個短語引入第一個實際障礙。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":2},{"front":"develop standard methods for","meaning":"制定……的標準方法","examples":[{"en":"The researchers developed standard methods for monitoring bittern numbers.","zh":"研究人員制定了監察麻鳽數量的標準方法。"},{"en":"To develop standard methods for something means to create agreed ways of doing it consistently.","zh":"develop standard methods for something 指建立一致並獲認可的做法。"},{"en":"A school may develop standard methods for marking essays so teachers grade fairly.","zh":"學校可能制定批改作文的標準方法，使老師評分公平。"},{"en":"Standard methods make results easier to compare between years and places.","zh":"標準方法令不同年份和地點的結果更容易比較。"},{"en":"The phrase focuses on creating reliable procedures.","zh":"這個短語重點是建立可靠程序。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":2},{"front":"monitor their numbers","meaning":"監察其數量","examples":[{"en":"The researchers needed a way to monitor their numbers.","zh":"研究人員需要一種方法來監察牠們的數量。"},{"en":"To monitor their numbers means to regularly check how many individuals there are.","zh":"monitor their numbers 指定期檢查有多少個體。"},{"en":"A teacher may monitor student numbers in a club to know whether interest is rising.","zh":"老師可能監察學會學生數量，以知道興趣是否上升。"},{"en":"If bird numbers fall, monitoring can warn conservationists before the decline becomes severe.","zh":"如果鳥類數量下降，監察可以在下降變嚴重前警告保育人士。"},{"en":"The phrase describes repeated counting or tracking.","zh":"這個短語描述重複點算或追蹤。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":2},{"front":"most distinctive feature","meaning":"最鮮明特徵","examples":[{"en":"The boom of the male bittern is its most distinctive feature during the breeding season.","zh":"雄性麻鳽的鳴叫是牠在繁殖季節最鮮明的特徵。"},{"en":"The most distinctive feature is the clearest or most recognisable characteristic.","zh":"most distinctive feature 指最清楚或最容易辨認的特徵。"},{"en":"A school building’s most distinctive feature may be its red clock tower.","zh":"一座校舍最鮮明特徵可能是紅色鐘樓。"},{"en":"A distinctive call helps researchers identify a bird even when it remains hidden.","zh":"鮮明叫聲幫助研究人員在鳥類隱藏時仍能辨認牠。"},{"en":"The phrase points to what makes something stand out.","zh":"這個短語指出令某物突出的特點。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":2},{"front":"breeding season","meaning":"繁殖季節","examples":[{"en":"The male bittern’s boom is distinctive during the breeding season.","zh":"雄性麻鳽的鳴叫在繁殖季節十分鮮明。"},{"en":"Breeding season is the time of year when animals mate, nest, and raise young.","zh":"breeding season 指動物交配、築巢和育幼的一年中特定時期。"},{"en":"A nature reserve may limit visitors during the breeding season to protect nests.","zh":"自然保護區可能在繁殖季節限制訪客，以保護巢穴。"},{"en":"During breeding season, bird behaviour and calls often become easier to notice.","zh":"在繁殖季節，鳥類行為和叫聲通常更容易被注意。"},{"en":"The phrase refers to the reproductive period of animals.","zh":"這個短語指動物繁殖時期。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":2},{"front":"sound pattern unique to","meaning":"每個個體獨有的聲音模式","examples":[{"en":"The researchers counted males from the sound pattern unique to each individual.","zh":"研究人員根據每個個體獨有的聲音模式點算雄鳥。"},{"en":"A sound pattern unique to an animal is a call style that identifies that individual.","zh":"sound pattern unique to an animal 指能識別該個體的叫聲風格。"},{"en":"A teacher may recognise a student’s voice because its sound pattern is familiar and unique.","zh":"老師可能因學生聲音模式熟悉而獨特，認出該學生的聲音。"},{"en":"If each male has a different call pattern, researchers can avoid counting the same bird twice.","zh":"如果每隻雄鳥有不同叫聲模式，研究人員就能避免重複點算同一隻鳥。"},{"en":"The phrase describes identification by sound.","zh":"這個短語描述透過聲音識別。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":2},{"front":"individual","meaning":"個體","examples":[{"en":"Each individual male had a unique sound pattern.","zh":"每個雄性個體都有獨特聲音模式。"},{"en":"An individual is one separate member of a group or species.","zh":"individual 指群體或物種中的單一成員。"},{"en":"In a class, each individual student may learn at a different speed.","zh":"在一班中，每個學生個體可能以不同速度學習。"},{"en":"Studying individuals helps researchers avoid treating all animals as identical.","zh":"研究個體幫助研究人員避免把所有動物視為完全相同。"},{"en":"The word focuses on one member, not the whole group.","zh":"這個詞重點是一個成員，而不是整個群體。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":2},{"front":"much more certain","meaning":"準確得多","examples":[{"en":"This method makes the number of booming males much more certain.","zh":"這種方法令鳴叫雄鳥數量準確得多。"},{"en":"Much more certain means far more reliable or less doubtful.","zh":"much more certain 指可靠得多或疑問少得多。"},{"en":"A teacher becomes much more certain about a student’s level after seeing several essays, not just one.","zh":"老師看過幾篇作文後，會比只看一篇更準確判斷學生水平。"},{"en":"If each bird can be identified by call, the population estimate becomes more accurate.","zh":"如果每隻鳥都能靠叫聲辨認，種群估算就會更準確。"},{"en":"The phrase shows a clear improvement in confidence.","zh":"這個短語顯示信心明顯提高。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":2},{"front":"estimate local survival","meaning":"估算本地存活率","examples":[{"en":"The method enables researchers to estimate local survival from one year to the next.","zh":"這種方法使研究人員能估算逐年本地存活率。"},{"en":"To estimate local survival means to calculate roughly how many individuals remain alive in the same area.","zh":"estimate local survival 指大約計算有多少個體仍在同一地區存活。"},{"en":"A wildlife team may estimate local survival by checking whether tagged animals return each year.","zh":"野生動物團隊可能透過檢查標記動物每年是否回來，估算本地存活率。"},{"en":"Survival estimates help show whether a habitat is safe enough for a species.","zh":"存活率估算有助顯示棲息地對某物種是否足夠安全。"},{"en":"The phrase describes a population measure based on repeated monitoring.","zh":"這個短語描述基於重複監察的人口量度。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":3},{"front":"direct understanding of","meaning":"對……的直接理解","examples":[{"en":"The first direct understanding of the habitat needs came from comparisons of reed beds.","zh":"對棲息地需要的首次直接理解來自蘆葦地比較。"},{"en":"A direct understanding of something is knowledge gained from clear evidence rather than guesswork.","zh":"direct understanding of something 指從清楚證據而非猜測中獲得的知識。"},{"en":"A teacher gains direct understanding of students’ problems by reading their actual essays.","zh":"老師透過閱讀學生實際作文，直接理解學生問題。"},{"en":"Direct evidence helps managers choose actions that match the species’ real needs.","zh":"直接證據幫助管理者選擇符合物種真正需要的行動。"},{"en":"The phrase stresses evidence-based understanding.","zh":"這個短語強調以證據為基礎的理解。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":3},{"front":"habitat needs","meaning":"棲息地需要","examples":[{"en":"Researchers studied the habitat needs of breeding bitterns.","zh":"研究人員研究繁殖麻鳽的棲息地需要。"},{"en":"Habitat needs are the conditions a species requires to live, feed, nest, and reproduce.","zh":"habitat needs 指某物種生活、覓食、築巢和繁殖所需的環境條件。"},{"en":"Frogs may have habitat needs such as clean ponds, insects, and safe damp places.","zh":"青蛙的棲息地需要可能包括乾淨池塘、昆蟲和安全潮濕地方。"},{"en":"If habitat needs are not met, a species may leave an area or fail to breed.","zh":"如果棲息地需要未被滿足，物種可能離開某地或無法繁殖。"},{"en":"The phrase explains what an animal needs from its environment.","zh":"這個短語解釋動物從環境中需要甚麼。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":3},{"front":"comparisons of","meaning":"對……的比較","examples":[{"en":"The research used comparisons of reed beds that had lost or retained bitterns.","zh":"研究使用了對失去或留住麻鳽的蘆葦地的比較。"},{"en":"Comparisons of things examine how they are similar or different.","zh":"comparisons of things 指檢視事物之間有何相似或不同。"},{"en":"A teacher may use comparisons of two essays to show why one is clearer.","zh":"老師可能比較兩篇作文，以顯示為何其中一篇更清楚。"},{"en":"Comparing successful and unsuccessful sites can reveal which habitat features matter.","zh":"比較成功和不成功的地點可以揭示哪些棲息地特徵重要。"},{"en":"The phrase describes learning through contrast.","zh":"這個短語描述透過對比學習。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":3},{"front":"reed bed sites","meaning":"蘆葦地點","examples":[{"en":"Researchers compared different reed bed sites.","zh":"研究人員比較不同蘆葦地點。"},{"en":"Reed bed sites are wetland places where reeds grow and wildlife may live.","zh":"reed bed sites 指蘆葦生長、野生動物可能生活的濕地地點。"},{"en":"A reserve may manage several reed bed sites for birds, fish, and insects.","zh":"保護區可能管理幾個蘆葦地點，以支援鳥類、魚類和昆蟲。"},{"en":"Some reed bed sites support breeding bitterns, while others may become too dry.","zh":"有些蘆葦地點支持繁殖麻鳽，另一些可能變得太乾。"},{"en":"The phrase refers to specific reed habitats being studied or managed.","zh":"這個短語指正在被研究或管理的特定蘆葦棲息地。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":3},{"front":"retain birds","meaning":"留住鳥類","examples":[{"en":"Some reed beds had retained their booming birds.","zh":"一些蘆葦地留住了牠們的鳴叫鳥類。"},{"en":"To retain birds means to keep birds in an area instead of losing them.","zh":"retain birds 指把鳥類留在某區域，而不是失去牠們。"},{"en":"A park may retain birds by protecting trees, water, and quiet nesting places.","zh":"公園可能透過保護樹木、水源和安靜巢址來留住鳥類。"},{"en":"If a habitat retains birds, it probably still provides the conditions they need.","zh":"如果棲息地能留住鳥類，它很可能仍提供牠們需要的條件。"},{"en":"The phrase focuses on keeping a population present.","zh":"這個短語重點是保持種群存在。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":3},{"front":"natural process of succession","meaning":"自然演替過程","examples":[{"en":"The natural process of succession had been slowed through management.","zh":"自然演替過程已透過管理被減慢。"},{"en":"The natural process of succession is the gradual change of habitat as plants grow, die, and replace one another.","zh":"natural process of succession 指植物生長、死亡和互相取代時，棲息地逐漸改變的過程。"},{"en":"A pond may slowly become marsh and then woodland through natural succession.","zh":"池塘可能透過自然演替慢慢變成沼澤，再變成林地。"},{"en":"If succession dries out reed beds, bittern habitat may decline unless managers intervene.","zh":"如果演替令蘆葦地乾涸，除非管理者介入，麻鳽棲息地可能下降。"},{"en":"The phrase describes natural habitat change over time.","zh":"這個短語描述棲息地隨時間自然改變。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":3},{"front":"drying out","meaning":"乾涸","examples":[{"en":"The drying out of reed beds was a major problem.","zh":"蘆葦地乾涸是一個重大問題。"},{"en":"Drying out means losing water and becoming too dry.","zh":"drying out 指失去水分並變得太乾。"},{"en":"A garden pond may dry out during a long hot summer.","zh":"花園池塘可能在漫長炎熱夏天乾涸。"},{"en":"If reed beds dry out, they may no longer provide wet feeding areas for bitterns.","zh":"如果蘆葦地乾涸，它們可能不再為麻鳽提供潮濕覓食區。"},{"en":"The phrase describes a loss of moisture that can damage habitat.","zh":"這個短語描述可能損害棲息地的水分流失。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":3},{"front":"be slowed through management","meaning":"透過管理被減慢","examples":[{"en":"The drying out process had been slowed through management.","zh":"乾涸過程已透過管理被減慢。"},{"en":"To be slowed through management means to be made slower by deliberate human action.","zh":"be slowed through management 指透過刻意的人為行動而變慢。"},{"en":"Soil erosion can be slowed through management if farmers plant grass along slopes.","zh":"如果農夫在斜坡種草，土壤侵蝕可以透過管理被減慢。"},{"en":"Slowing habitat change gives wildlife more suitable conditions for longer.","zh":"減慢棲息地變化可以讓野生動物更長時間擁有合適條件。"},{"en":"The phrase describes active intervention to reduce a natural process.","zh":"這個短語描述主動介入以降低自然過程速度。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":3},{"front":"based on this work","meaning":"基於這項工作","examples":[{"en":"Based on this work, broad recommendations were made.","zh":"基於這項工作，研究人員提出了廣泛建議。"},{"en":"Based on this work means using the findings or evidence from this research as the foundation.","zh":"based on this work 指使用這項研究的發現或證據作為基礎。"},{"en":"Based on a school survey, teachers may change the homework timetable.","zh":"基於學校調查，老師可能改變功課時間表。"},{"en":"Decisions are stronger when they are based on research rather than habit.","zh":"決策基於研究而不是習慣時會更有力。"},{"en":"The phrase links earlier study with later action.","zh":"這個短語把早前研究與之後行動連起來。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":3},{"front":"broad recommendations","meaning":"廣泛建議","examples":[{"en":"Broad recommendations on managing reed beds were made.","zh":"關於管理蘆葦地的廣泛建議被提出。"},{"en":"Broad recommendations are general pieces of advice that guide action but may not give every detail.","zh":"broad recommendations 指引導行動的一般建議，但未必提供所有細節。"},{"en":"A doctor may give broad recommendations such as sleep more, exercise regularly, and eat less sugar.","zh":"醫生可能提出廣泛建議，例如多睡、定期運動和少吃糖。"},{"en":"Broad advice helps many sites begin improvement before detailed plans are ready.","zh":"廣泛建議幫助許多地點在詳細計劃準備好前開始改善。"},{"en":"The phrase describes general guidance, not precise step-by-step instructions.","zh":"這個短語描述一般指引，而不是精確逐步指示。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":3},{"front":"manage and rehabilitate","meaning":"管理和修復","examples":[{"en":"The recommendations explained how to manage and rehabilitate reed beds.","zh":"建議解釋如何管理和修復蘆葦地。"},{"en":"To manage and rehabilitate a habitat means to look after it and restore it to a healthier condition.","zh":"manage and rehabilitate a habitat 指照顧棲息地並把它恢復至較健康狀態。"},{"en":"A city may manage and rehabilitate a polluted park by cleaning water and replanting trees.","zh":"城市可能透過清潔水源和重新種樹來管理和修復受污染公園。"},{"en":"Rehabilitation can help damaged reed beds become useful again for wildlife.","zh":"修復可以幫助受損蘆葦地再次對野生動物有用。"},{"en":"The phrase combines daily care with long-term restoration.","zh":"這個短語結合日常照顧與長期復原。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":4},{"front":"funding was provided through","meaning":"資金由……提供","examples":[{"en":"Funding was provided through the EU LIFE Fund.","zh":"資金由歐盟 LIFE 基金提供。"},{"en":"Funding was provided through something means money came from that source or programme.","zh":"funding was provided through something 指資金來自某來源或計劃。"},{"en":"A school garden may be built if funding is provided through a community grant.","zh":"如果資金由社區資助提供，學校花園可能得以建立。"},{"en":"Conservation projects often need outside funding because habitat work is expensive.","zh":"保育項目常需要外部資金，因為棲息地工作成本高。"},{"en":"The phrase identifies the financial source behind the work.","zh":"這個短語指出工作背後的資金來源。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":4},{"front":"EU LIFE Fund","meaning":"歐盟LIFE基金","examples":[{"en":"The EU LIFE Fund supported the management of 13 sites.","zh":"歐盟 LIFE 基金支持了13個地點的管理。"},{"en":"The EU LIFE Fund is a European funding programme that supports environmental and conservation projects.","zh":"EU LIFE Fund 是支持環境和保育項目的歐洲資助計劃。"},{"en":"A wetland project may use EU LIFE Fund money to restore water levels and protect wildlife.","zh":"濕地項目可能使用歐盟 LIFE 基金資金來恢復水位和保護野生動物。"},{"en":"Funding from such a programme can turn research recommendations into real habitat work.","zh":"來自這類計劃的資金可以把研究建議變成實際棲息地工作。"},{"en":"The phrase names the source of support for the conservation project.","zh":"這個短語命名保育項目的支援來源。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":4},{"front":"core breeding range","meaning":"核心繁殖範圍","examples":[{"en":"The project managed 13 sites within the core breeding range.","zh":"該項目管理核心繁殖範圍內的13個地點。"},{"en":"The core breeding range is the main area where a species breeds most regularly or successfully.","zh":"core breeding range 指某物種最常或最成功繁殖的主要區域。"},{"en":"A bird reserve inside the core breeding range may be especially important for nesting success.","zh":"位於核心繁殖範圍內的鳥類保護區，可能對築巢成功尤其重要。"},{"en":"Protecting core areas first can help a declining population recover faster.","zh":"先保護核心區域可以幫助下降中的種群更快恢復。"},{"en":"The phrase identifies the central breeding area, not every place the species visits.","zh":"這個短語指出核心繁殖區，而不是物種到訪的所有地方。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":4},{"front":"led by","meaning":"由……領導","examples":[{"en":"The project was led by the RSPB.","zh":"該項目由 RSPB 領導。"},{"en":"Led by means organised, directed, or guided by a person or organisation.","zh":"led by 指由某人或某組織組織、指揮或引導。"},{"en":"A school clean-up project may be led by the student council.","zh":"學校清潔項目可能由學生會領導。"},{"en":"Strong leadership can coordinate different groups and keep a project moving.","zh":"有力領導可以協調不同群體並令項目持續推進。"},{"en":"The phrase identifies who was in charge.","zh":"這個短語指出誰負責。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":4},{"front":"involve many organisations","meaning":"涉及許多組織","examples":[{"en":"The project involved many other organisations.","zh":"該項目涉及許多其他組織。"},{"en":"To involve many organisations means to include several groups working together.","zh":"involve many organisations 指包括幾個團體一起工作。"},{"en":"A community health campaign may involve schools, clinics, charities, and local shops.","zh":"社區健康宣傳可能涉及學校、診所、慈善團體和本地商店。"},{"en":"Large conservation projects often need many organisations because land, money, science, and management all matter.","zh":"大型保育項目常需要許多組織，因為土地、資金、科學和管理都重要。"},{"en":"The phrase stresses cooperation across groups.","zh":"這個短語強調跨團體合作。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":4},{"front":"refine recommendations","meaning":"改進建議","examples":[{"en":"The researchers refined their recommendations through further study.","zh":"研究人員透過進一步研究改進建議。"},{"en":"To refine recommendations means to improve advice by making it more accurate or detailed.","zh":"refine recommendations 指透過令建議更準確或更詳細來改良它們。"},{"en":"A teacher may refine study advice after seeing which exercises actually help students.","zh":"老師看見哪些練習真正幫到學生後，可能改進學習建議。"},{"en":"Further data can turn broad guidance into precise habitat instructions.","zh":"進一步數據可以把廣泛指引變成精確棲息地指示。"},{"en":"The phrase describes improving advice through evidence.","zh":"這個短語描述透過證據改善建議。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":4},{"front":"fine-scale, quantitative habitat prescriptions","meaning":"精細而量化的棲息地指引","examples":[{"en":"The researchers provided fine-scale, quantitative habitat prescriptions.","zh":"研究人員提供精細而量化的棲息地指引。"},{"en":"Fine-scale, quantitative habitat prescriptions are detailed habitat-management instructions using measurable numbers.","zh":"fine-scale, quantitative habitat prescriptions 指使用可量度數字的詳細棲息地管理指示。"},{"en":"A reserve plan may state exactly how much open water and reed edge a bird needs.","zh":"保護區計劃可能準確列明鳥類需要多少開闊水面和蘆葦邊緣。"},{"en":"Quantitative guidance helps managers know what to create instead of guessing.","zh":"量化指引幫助管理者知道應創造甚麼，而不是猜測。"},{"en":"The phrase describes precise, evidence-based habitat instructions.","zh":"這個短語描述精確、以證據為基礎的棲息地指示。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":4},{"front":"preferred feeding habitat","meaning":"偏好的覓食棲息地","examples":[{"en":"The study examined the bitterns’ preferred feeding habitat.","zh":"該研究檢視麻鳽偏好的覓食棲息地。"},{"en":"Preferred feeding habitat is the type of place an animal most often chooses for finding food.","zh":"preferred feeding habitat 指動物最常選擇用來尋找食物的地方類型。"},{"en":"A heron may prefer shallow water because fish are easier to catch there.","zh":"蒼鷺可能偏好淺水，因為魚較容易在那裏捕捉。"},{"en":"Knowing preferred feeding habitat helps managers create places where birds can feed successfully.","zh":"了解偏好的覓食棲息地幫助管理者創造鳥類能成功覓食的地方。"},{"en":"The phrase focuses on food-related habitat choice.","zh":"這個短語重點是與食物有關的棲息地選擇。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":4},{"front":"radio-track","meaning":"以無線電追蹤","examples":[{"en":"The researchers radio-tracked male bitterns on two reserves.","zh":"研究人員在兩個保護區以無線電追蹤雄性麻鳽。"},{"en":"To radio-track an animal means to follow its movements using a radio transmitter.","zh":"radio-track an animal 指使用無線電發射器追蹤動物移動。"},{"en":"Scientists may radio-track turtles to learn where they travel after release.","zh":"科學家可能以無線電追蹤海龜，以了解牠們放生後去哪裏。"},{"en":"Radio-tracking helps reveal where hidden animals feed, rest, and nest.","zh":"無線電追蹤幫助揭示隱蔽動物在哪裏覓食、休息和築巢。"},{"en":"The phrase describes a scientific method for following wildlife.","zh":"這個短語描述追蹤野生動物的科學方法。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":4},{"front":"reserves","meaning":"保護區","examples":[{"en":"The researchers studied bitterns on the Minsmere and Leighton Moss reserves.","zh":"研究人員在 Minsmere 和 Leighton Moss 保護區研究麻鳽。"},{"en":"Reserves are protected areas managed for wildlife, habitats, or conservation.","zh":"reserves 指為野生動物、棲息地或保育而管理的保護地區。"},{"en":"A nature reserve may have paths for visitors but closed areas for nesting birds.","zh":"自然保護區可能有遊客步道，但也有為築巢鳥類而關閉的區域。"},{"en":"Reserves can provide safer places where rare species can recover.","zh":"保護區可以提供較安全地方，讓稀有物種恢復。"},{"en":"The phrase refers to protected conservation sites.","zh":"這個短語指受保護的保育地點。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":4},{"front":"clear preferences for","meaning":"對……有明顯偏好","examples":[{"en":"The study showed clear preferences for feeding in wetter reed bed margins.","zh":"該研究顯示麻鳽對在較濕蘆葦地邊緣覓食有明顯偏好。"},{"en":"Clear preferences for something are obvious choices or favoured options shown by behaviour.","zh":"clear preferences for something 指行為顯示出明顯選擇或偏好。"},{"en":"A student may show a clear preference for visual notes if she always draws diagrams when studying.","zh":"如果學生溫習時總畫圖，她可能對視覺筆記有明顯偏好。"},{"en":"If bitterns feed more often in wet margins, managers can create more of that habitat.","zh":"如果麻鳽更常在潮濕邊緣覓食，管理者可以創造更多這類棲息地。"},{"en":"The phrase shows that the pattern is noticeable, not random.","zh":"這個短語顯示模式明顯，而不是隨機。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":5},{"front":"wetter reed bed margins","meaning":"較濕的蘆葦地邊緣","examples":[{"en":"Bitterns preferred feeding in wetter reed bed margins.","zh":"麻鳽偏好在較濕的蘆葦地邊緣覓食。"},{"en":"Wetter reed bed margins are the moister edges of reed beds where water and reeds meet.","zh":"wetter reed bed margins 指水和蘆葦交界處較潮濕的蘆葦地邊緣。"},{"en":"Birds may find fish and insects near wet reed edges because the area supports aquatic life.","zh":"鳥類可能在濕蘆葦邊緣找到魚和昆蟲，因為該區支持水生生物。"},{"en":"If margins become too dry, bitterns may lose important feeding places.","zh":"如果邊緣變得太乾，麻鳽可能失去重要覓食地。"},{"en":"The phrase describes a specific wet edge habitat.","zh":"這個短語描述特定的潮濕邊緣棲息地。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":5},{"front":"open pools","meaning":"開闊水池","examples":[{"en":"Bitterns often fed near larger open pools.","zh":"麻鳽常在較大的開闊水池附近覓食。"},{"en":"Open pools are areas of visible open water within or near vegetation.","zh":"open pools 指植被中或附近可見的開闊水面區域。"},{"en":"A wetland with open pools may attract birds that feed on fish or insects.","zh":"有開闊水池的濕地可能吸引以魚或昆蟲為食的鳥類。"},{"en":"Open water can provide access to prey that dense vegetation may hide.","zh":"開闊水面可以提供獵物，而濃密植被可能把獵物藏起來。"},{"en":"The phrase refers to clear water areas, not swimming pools.","zh":"這個短語指清楚水面區域，而不是游泳池。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":5},{"front":"average home range sizes","meaning":"平均活動範圍大小","examples":[{"en":"The average home range sizes of the male bitterns were about 20 hectares.","zh":"雄性麻鳽的平均活動範圍大小約為20公頃。"},{"en":"Average home range sizes are the typical areas animals use for feeding, resting, and daily movement.","zh":"average home range sizes 指動物用於覓食、休息和日常移動的典型區域大小。"},{"en":"A fox’s home range may include gardens, fields, and quiet paths where it searches for food.","zh":"狐狸的活動範圍可能包括花園、田地和牠尋找食物的安靜小路。"},{"en":"Knowing home range size helps managers decide how large a suitable habitat should be.","zh":"知道活動範圍大小幫助管理者決定合適棲息地應有多大。"},{"en":"The phrase describes the usual space an animal needs.","zh":"這個短語描述動物通常需要的空間。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":5},{"front":"provide a good indication of","meaning":"清楚顯示","examples":[{"en":"The data provided a good indication of the reed bed area needed.","zh":"數據清楚顯示所需蘆葦地面積。"},{"en":"To provide a good indication of something means to give a useful sign or estimate of it.","zh":"provide a good indication of something 指提供有用跡象或估算。"},{"en":"A student’s practice essay can provide a good indication of what grammar she still needs.","zh":"學生的練習作文可以清楚顯示她仍需要哪些文法。"},{"en":"If tracking data show a bird uses 20 hectares, managers can estimate habitat size more confidently.","zh":"如果追蹤數據顯示一隻鳥使用20公頃，管理者就能更有信心估算棲息地大小。"},{"en":"The phrase describes evidence that guides judgement.","zh":"這個短語描述引導判斷的證據。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":5},{"front":"create habitat for","meaning":"為……創造棲息地","examples":[{"en":"The findings helped managers create habitat for this species.","zh":"這些發現幫助管理者為這個物種創造棲息地。"},{"en":"To create habitat for a species means to make or restore places where it can live successfully.","zh":"create habitat for a species 指建立或修復某物種能成功生活的地方。"},{"en":"A school garden can create habitat for butterflies by planting native flowers.","zh":"學校花園可以透過種植本地花卉為蝴蝶創造棲息地。"},{"en":"If suitable habitat is created, animals may return, feed, and breed there.","zh":"如果合適棲息地被創造，動物可能回來覓食和繁殖。"},{"en":"The phrase focuses on building the environmental conditions a species needs.","zh":"這個短語重點是建立物種所需的環境條件。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":5},{"front":"undertake all the incubation","meaning":"承擔全部孵卵工作","examples":[{"en":"Female bitterns undertake all the incubation.","zh":"雌性麻鳽承擔全部孵卵工作。"},{"en":"To undertake all the incubation means to take full responsibility for keeping eggs warm until they hatch.","zh":"undertake all the incubation 指完全負責保持蛋溫暖直到孵化。"},{"en":"In some bird species, one parent undertakes most of the incubation while the other searches for food.","zh":"在一些鳥類中，一方親鳥承擔大部分孵卵工作，另一方尋找食物。"},{"en":"If females incubate alone, nesting habitat must protect them for long periods.","zh":"如果雌鳥獨自孵卵，築巢棲息地必須長時間保護牠。"},{"en":"The phrase describes the full egg-warming duty during breeding.","zh":"這個短語描述繁殖期間完整的孵蛋責任。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":5},{"front":"care of the young","meaning":"照顧幼鳥","examples":[{"en":"Female bitterns undertake all the care of the young.","zh":"雌性麻鳽承擔全部照顧幼鳥的工作。"},{"en":"Care of the young means feeding, protecting, and looking after chicks or offspring.","zh":"care of the young 指餵養、保護和照顧雛鳥或後代。"},{"en":"A parent bird may bring food to the nest as part of care of the young.","zh":"親鳥把食物帶回巢中，就是照顧幼鳥的一部分。"},{"en":"If young birds need much care, the adult must have safe nesting habitat and enough food nearby.","zh":"如果幼鳥需要大量照顧，成鳥必須有安全巢址和附近足夠食物。"},{"en":"The phrase refers to parental duties after eggs hatch.","zh":"這個短語指蛋孵化後的親代責任。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":5},{"front":"over the course of","meaning":"在……期間","examples":[{"en":"Over the course of the research, the team located 87 nests.","zh":"在研究期間，團隊找到了87個巢穴。"},{"en":"Over the course of something means during the whole period of that activity or process.","zh":"over the course of something 指在某活動或過程的整段期間。"},{"en":"Over the course of a school year, a teacher may collect many examples of student progress.","zh":"在一個學年期間，老師可能收集許多學生進步例子。"},{"en":"Long research periods allow teams to gather more reliable data.","zh":"較長研究期讓團隊收集更可靠數據。"},{"en":"The phrase describes what happens throughout a period.","zh":"這個短語描述整段期間發生的事。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":5},{"front":"locate nests","meaning":"找到巢穴","examples":[{"en":"The researchers located 87 bittern nests.","zh":"研究人員找到87個麻鳽巢穴。"},{"en":"To locate nests means to find the exact places where birds have built nests.","zh":"locate nests 指找出鳥類築巢的確切位置。"},{"en":"Wildlife workers may locate nests before cutting grass so chicks are not harmed.","zh":"野生動物工作者可能在割草前找到巢穴，以免傷害雛鳥。"},{"en":"Finding nests helps researchers study breeding success and habitat choice.","zh":"找到巢穴幫助研究人員研究繁殖成功和棲息地選擇。"},{"en":"The phrase describes careful searching for nesting sites.","zh":"這個短語描述仔細尋找築巢地點。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":5},{"front":"continuous vegetation","meaning":"連續植被","examples":[{"en":"Female bitterns preferred to nest in areas of continuous vegetation.","zh":"雌性麻鳽偏好在連續植被區築巢。"},{"en":"Continuous vegetation is plant cover that is unbroken and connected across an area.","zh":"continuous vegetation 指在某區域內不中斷、相連的植物覆蓋。"},{"en":"Small animals may hide better in continuous vegetation than in scattered plants.","zh":"小動物在連續植被中比在零散植物中更容易隱藏。"},{"en":"Continuous cover can protect nests from predators, people, and weather.","zh":"連續覆蓋可以保護巢穴免受捕食者、人類和天氣影響。"},{"en":"The phrase describes dense, connected plant habitat.","zh":"這個短語描述濃密相連的植物棲息地。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":5},{"front":"well into the reed bed","meaning":"深入蘆葦地內","examples":[{"en":"The nests were located well into the reed bed.","zh":"巢穴位於深入蘆葦地內的位置。"},{"en":"Well into the reed bed means far inside the reed area, not near the outer edge.","zh":"well into the reed bed 指在蘆葦區深處，而不是靠近外緣。"},{"en":"A shy animal may hide well into a forest where people rarely walk.","zh":"害羞動物可能躲在森林深處，人們很少走到那裏。"},{"en":"Nesting deep inside reeds can give birds more protection from disturbance.","zh":"在蘆葦深處築巢可以給鳥類更多保護，避免干擾。"},{"en":"The phrase describes a position deep within a habitat.","zh":"這個短語描述棲息地深處的位置。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":6},{"front":"during the driest part of","meaning":"在……最乾燥的時段","examples":[{"en":"Water was still present during the driest part of the breeding season.","zh":"在繁殖季節最乾燥的時段，水仍然存在。"},{"en":"During the driest part of a period means in the time when water levels are lowest.","zh":"during the driest part of a period 指在水位最低的時段。"},{"en":"A pond that still holds water during the driest part of summer is valuable for wildlife.","zh":"如果池塘在夏天最乾燥的時段仍有水，它對野生動物很有價值。"},{"en":"If water remains during dry weeks, chicks and feeding adults may survive better.","zh":"如果乾旱周期間仍有水，雛鳥和覓食成鳥可能更容易存活。"},{"en":"The phrase focuses on conditions at the most water-stressed time.","zh":"這個短語重點是最缺水時的環境條件。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":6},{"front":"habitat prescriptions","meaning":"棲息地管理指引","examples":[{"en":"The habitat prescriptions developed from the research were successful.","zh":"由研究發展而成的棲息地管理指引很成功。"},{"en":"Habitat prescriptions are detailed instructions for creating or managing suitable habitat.","zh":"habitat prescriptions 指創造或管理合適棲息地的詳細指示。"},{"en":"A reserve plan may include habitat prescriptions such as keeping water at a set depth.","zh":"保護區計劃可能包括棲息地指引，例如把水位保持在某深度。"},{"en":"Clear prescriptions help land managers turn scientific findings into practical work.","zh":"清晰指引幫助土地管理者把科學發現轉化為實際工作。"},{"en":"The phrase means management guidance, not medical medicine.","zh":"這個短語指管理指引，不是醫療處方。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":6},{"front":"developed from this research","meaning":"由這項研究發展而成","examples":[{"en":"The recommendations were developed from this research.","zh":"這些建議由這項研究發展而成。"},{"en":"Developed from this research means created using the findings of the study.","zh":"developed from this research 指使用該研究的發現創造出來。"},{"en":"A school’s new reading programme may be developed from classroom research on weak skills.","zh":"學校的新閱讀計劃可能由關於弱項技能的課室研究發展而成。"},{"en":"When advice is developed from research, it is more likely to match real problems.","zh":"當建議由研究發展而成，它更可能符合真實問題。"},{"en":"The phrase links scientific evidence with practical recommendations.","zh":"這個短語把科學證據與實際建議連起來。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":6},{"front":"be spectacular","meaning":"非常出色；令人矚目","examples":[{"en":"The success of the habitat prescriptions was spectacular.","zh":"棲息地管理指引的成功非常出色。"},{"en":"Spectacular means extremely impressive or remarkable.","zh":"spectacular 指極其令人印象深刻或值得注意。"},{"en":"A student’s improvement can be spectacular if she moves from failing to top of the class.","zh":"如果學生由不合格進步到全班最高，她的進步可以說非常出色。"},{"en":"If bird numbers rise strongly after management, the result may be called spectacular.","zh":"如果鳥類數量在管理後大幅上升，結果可稱為令人矚目。"},{"en":"The word highlights success that is much greater than ordinary improvement.","zh":"這個詞突出遠超普通改善的成功。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":6},{"front":"for instance","meaning":"例如","examples":[{"en":"For instance, booming bittern numbers increased at Minsmere.","zh":"例如，Minsmere 的鳴叫麻鳽數量增加了。"},{"en":"For instance means for example.","zh":"for instance 指例如。"},{"en":"Good study habits help students improve; for instance, reviewing mistakes each week builds accuracy.","zh":"良好學習習慣幫助學生進步；例如，每週檢討錯誤可以建立準確度。"},{"en":"Writers use this phrase to introduce a specific example that supports a general point.","zh":"作者使用這個短語來引入支持一般觀點的具體例子。"},{"en":"The phrase makes an explanation more concrete.","zh":"這個短語令解釋更具體。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":6},{"front":"gradually increase from…to…","meaning":"由……逐漸增加至……","examples":[{"en":"Booming bittern numbers gradually increased from one to ten.","zh":"鳴叫麻鳽數量由一隻逐漸增加至十隻。"},{"en":"To gradually increase from A to B means to rise slowly from one number to another.","zh":"gradually increase from A to B 指由一個數字慢慢上升至另一個數字。"},{"en":"A student’s reading score may gradually increase from 55 to 75 after months of practice.","zh":"經過數月練習，學生閱讀分數可能由55分逐漸增加至75分。"},{"en":"Gradual increase suggests improvement over time rather than sudden change.","zh":"逐漸增加暗示隨時間改善，而不是突然變化。"},{"en":"The phrase is useful for describing slow numerical growth.","zh":"這個短語適合描述緩慢的數字增長。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":6},{"front":"reed bed lowering","meaning":"降低蘆葦地面","examples":[{"en":"Reed bed lowering was used to halt the drying out process.","zh":"降低蘆葦地面被用來停止乾涸過程。"},{"en":"Reed bed lowering is a management technique that lowers parts of a reed bed to improve wet conditions.","zh":"reed bed lowering 指降低蘆葦地部分地面，以改善潮濕環境的管理技術。"},{"en":"Wetland managers may lower ground levels so water can remain in reed areas for longer.","zh":"濕地管理者可能降低地面水平，使水更長時間留在蘆葦區。"},{"en":"Lowering reed beds can help prevent them from becoming too dry for bitterns.","zh":"降低蘆葦地面可以幫助防止它們變得太乾而不適合麻鳽。"},{"en":"The phrase describes a physical habitat-management action.","zh":"這個短語描述實體棲息地管理行動。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":6},{"front":"management technique","meaning":"管理技術","examples":[{"en":"Reed bed lowering was a management technique.","zh":"降低蘆葦地面是一種管理技術。"},{"en":"A management technique is a planned method used to control, improve, or maintain something.","zh":"management technique 指用來控制、改善或維持某事的計劃方法。"},{"en":"A teacher may use seating plans as a management technique to reduce classroom noise.","zh":"老師可能使用座位安排作為管理技術，以減少課室噪音。"},{"en":"In conservation, management techniques can change water levels, vegetation, or visitor access.","zh":"在保育中，管理技術可以改變水位、植被或訪客進入方式。"},{"en":"The phrase refers to a practical method, not just an idea.","zh":"這個短語指實際方法，而不只是想法。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":6},{"front":"halt the drying out process","meaning":"停止乾涸過程","examples":[{"en":"The technique was designed to halt the drying out process.","zh":"這項技術旨在停止乾涸過程。"},{"en":"To halt the drying out process means to stop an area from continuing to lose water.","zh":"halt the drying out process 指阻止某地繼續失去水分。"},{"en":"A gardener may add mulch to halt the drying out process in soil during hot weather.","zh":"園丁可能在炎熱天氣中加覆蓋物，以停止土壤乾涸過程。"},{"en":"If reed beds stop drying out, they can remain suitable for wetland birds.","zh":"如果蘆葦地停止乾涸，它們可以保持適合濕地鳥類。"},{"en":"The phrase describes stopping a harmful loss of moisture.","zh":"這個短語描述停止有害水分流失。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":6},{"front":"low point","meaning":"低點","examples":[{"en":"The number of booming males reached a low point in 1997.","zh":"鳴叫雄鳥數量在1997年達到低點。"},{"en":"A low point is the lowest level in a period or trend.","zh":"low point 指某時期或趨勢中的最低水平。"},{"en":"A student’s confidence may reach a low point after several failed tests.","zh":"學生連續幾次測驗不合格後，信心可能達到低點。"},{"en":"Identifying the low point helps show when recovery began.","zh":"找出低點有助顯示恢復何時開始。"},{"en":"The phrase marks the worst or lowest stage.","zh":"這個短語標示最差或最低階段。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":6},{"front":"respond to","meaning":"對……作出反應","examples":[{"en":"Bittern numbers responded to the habitat management work.","zh":"麻鳽數量對棲息地管理工作作出反應。"},{"en":"To respond to something means to change or react because of it.","zh":"respond to something 指因某事而改變或反應。"},{"en":"Students may respond to clear feedback by making fewer mistakes in the next essay.","zh":"學生可能因清晰回饋而在下一篇作文中犯較少錯誤。"},{"en":"If bird numbers increase after habitat work, the population has responded positively.","zh":"如果鳥類數量在棲息地工作後增加，種群就是作出正面反應。"},{"en":"The phrase connects an action with a reaction.","zh":"這個短語把行動與反應連起來。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":7},{"front":"habitat management work","meaning":"棲息地管理工作","examples":[{"en":"Habitat management work helped bittern numbers increase.","zh":"棲息地管理工作幫助麻鳽數量增加。"},{"en":"Habitat management work is practical work done to improve or maintain places where wildlife lives.","zh":"habitat management work 指改善或維持野生動物生活地點的實際工作。"},{"en":"Volunteers may do habitat management work by clearing invasive plants and restoring ponds.","zh":"義工可能透過清除入侵植物和修復池塘來進行棲息地管理工作。"},{"en":"Good management can make a damaged area suitable again for feeding and breeding.","zh":"良好管理可以令受損地區再次適合覓食和繁殖。"},{"en":"The phrase refers to hands-on conservation action.","zh":"這個短語指實地保育行動。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":7},{"front":"final phase of research","meaning":"研究的最後階段","examples":[{"en":"The final phase of research focused on chicks.","zh":"研究的最後階段集中於幼鳥。"},{"en":"The final phase of research is the last stage of a study programme.","zh":"final phase of research 指研究計劃的最後一個階段。"},{"en":"In the final phase of a school project, students may present their findings to the class.","zh":"在學校項目的最後階段，學生可能向全班展示研究結果。"},{"en":"A final research phase often answers questions left unresolved by earlier stages.","zh":"最後研究階段通常回答早期階段仍未解決的問題。"},{"en":"The phrase marks the closing part of a research process.","zh":"這個短語標示研究過程的結尾部分。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":7},{"front":"diet, survival and dispersal","meaning":"飲食、存活和擴散","examples":[{"en":"The final phase involved understanding the diet, survival and dispersal of chicks.","zh":"最後階段涉及理解幼鳥的飲食、存活和擴散。"},{"en":"Diet, survival and dispersal refer to what chicks eat, whether they live, and where they move after leaving the nest.","zh":"diet, survival and dispersal 指幼鳥吃甚麼、是否存活，以及離巢後移到哪裏。"},{"en":"A wildlife team may study diet by examining food remains near nests.","zh":"野生動物團隊可能透過檢查巢附近食物殘餘來研究飲食。"},{"en":"Understanding survival and dispersal helps managers know whether young birds can join the wider population.","zh":"理解存活和擴散幫助管理者知道幼鳥能否加入更廣泛種群。"},{"en":"The phrase groups three key questions about young animals.","zh":"這個短語集合關於幼年動物的三個關鍵問題。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":7},{"front":"fit radio tags to","meaning":"為……裝上無線電標籤","examples":[{"en":"The researchers fitted small radio tags to young bittern chicks.","zh":"研究人員為幼麻鳽裝上小型無線電標籤。"},{"en":"To fit radio tags to animals means to attach small tracking devices to them.","zh":"fit radio tags to animals 指把小型追蹤裝置附在動物身上。"},{"en":"Scientists may fit radio tags to young turtles before releasing them into the sea.","zh":"科學家可能在放生幼海龜前為牠們裝上無線電標籤。"},{"en":"Tags allow researchers to follow animals that would otherwise be hard to find.","zh":"標籤讓研究人員追蹤原本難以找到的動物。"},{"en":"The phrase describes attaching tracking equipment for research.","zh":"這個短語描述為研究而安裝追蹤設備。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":7},{"front":"radio tags","meaning":"無線電標籤","examples":[{"en":"Small radio tags were fitted to young bittern chicks.","zh":"小型無線電標籤被裝在幼麻鳽身上。"},{"en":"Radio tags are small devices that send signals so researchers can track an animal’s location.","zh":"radio tags 指發出訊號、讓研究人員追蹤動物位置的小型裝置。"},{"en":"A radio tag on a wild bird can help scientists find it after it leaves the nest.","zh":"野鳥身上的無線電標籤可以幫助科學家在牠離巢後找到牠。"},{"en":"Without radio tags, young birds may disappear into dense habitat and become impossible to follow.","zh":"沒有無線電標籤，幼鳥可能消失在濃密棲息地中而無法追蹤。"},{"en":"The phrase refers to tracking equipment used in wildlife research.","zh":"這個短語指野生動物研究中的追蹤設備。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":7},{"front":"determine their fate","meaning":"確定牠們的命運","examples":[{"en":"The tags helped determine the chicks’ fate.","zh":"這些標籤幫助確定幼鳥的命運。"},{"en":"To determine their fate means to find out what eventually happened to them.","zh":"determine their fate 指找出牠們最終發生了甚麼事。"},{"en":"A teacher may check old records to determine the fate of a school project after its funding ended.","zh":"老師可能查看舊記錄，以確定學校項目資金結束後的命運。"},{"en":"Tracking chicks can show whether they survived, died, or moved elsewhere.","zh":"追蹤幼鳥可以顯示牠們是存活、死亡還是移到別處。"},{"en":"The phrase focuses on discovering the final outcome.","zh":"這個短語重點是找出最終結果。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":7},{"front":"through to fledging and beyond","meaning":"直到離巢及之後","examples":[{"en":"The researchers followed chicks through to fledging and beyond.","zh":"研究人員追蹤幼鳥直到離巢及之後。"},{"en":"Through to fledging and beyond means from an earlier stage until the chicks leave the nest and after that.","zh":"through to fledging and beyond 指從較早階段一直到幼鳥離巢，並包括之後。"},{"en":"A teacher may support students through to graduation and beyond by helping them plan careers.","zh":"老師可能支援學生直到畢業及之後，幫助他們規劃事業。"},{"en":"Following chicks beyond fledging shows whether they survive after leaving the nest.","zh":"追蹤幼鳥離巢之後，可以顯示牠們離巢後是否存活。"},{"en":"The phrase describes tracking a process past an important milestone.","zh":"這個短語描述追蹤一個過程越過重要里程碑。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":7},{"front":"survive to fledging","meaning":"存活至離巢","examples":[{"en":"Many chicks did not survive to fledging.","zh":"許多幼鳥未能存活至離巢。"},{"en":"To survive to fledging means to live until the stage when a young bird can leave the nest.","zh":"survive to fledging 指活到幼鳥能離開巢穴的階段。"},{"en":"Young birds need enough food and protection if they are to survive to fledging.","zh":"幼鳥需要足夠食物和保護，才能存活至離巢。"},{"en":"If many chicks fail to reach fledging, the population may struggle to grow.","zh":"如果許多幼鳥未能到達離巢階段，種群可能難以增長。"},{"en":"The phrase measures early survival before independence.","zh":"這個短語量度獨立前的早期存活。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":7},{"front":"starvation","meaning":"饑餓","examples":[{"en":"Starvation was the most likely reason for their demise.","zh":"饑餓是牠們死亡最可能的原因。"},{"en":"Starvation means death or serious weakness caused by not having enough food.","zh":"starvation 指因沒有足夠食物而死亡或嚴重虛弱。"},{"en":"A young animal may suffer starvation if its parents cannot find enough prey.","zh":"如果親鳥找不到足夠獵物，幼小動物可能遭受饑餓。"},{"en":"If chicks die from starvation, improving food supply becomes a conservation priority.","zh":"如果幼鳥死於饑餓，改善食物供應就成為保育優先事項。"},{"en":"The word points to food shortage as the cause of death.","zh":"這個詞指出食物不足是死因。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":7},{"front":"most likely reason for","meaning":"……最可能的原因","examples":[{"en":"Starvation was the most likely reason for chick deaths.","zh":"饑餓是幼鳥死亡最可能的原因。"},{"en":"The most likely reason for something is the cause that seems most probable based on evidence.","zh":"most likely reason for something 指根據證據看來最可能的原因。"},{"en":"If a student is late after a train breakdown, transport delay is the most likely reason.","zh":"如果學生在火車故障後遲到，交通延誤就是最可能的原因。"},{"en":"Identifying the most likely reason helps people choose the right solution.","zh":"找出最可能原因幫助人們選擇正確解決方法。"},{"en":"The phrase expresses probability, not absolute certainty.","zh":"這個短語表達可能性，而不是絕對確定。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":7},{"front":"demise","meaning":"死亡","examples":[{"en":"Starvation was the most likely reason for the chicks’ demise.","zh":"饑餓是幼鳥死亡最可能的原因。"},{"en":"Demise means death, ending, or disappearance.","zh":"demise 指死亡、結束或消失。"},{"en":"The demise of a small shop may follow years of falling sales and rising rent.","zh":"小店在多年銷售下降和租金上升後可能走向結束。"},{"en":"In wildlife research, a chick’s demise means it did not survive.","zh":"在野生動物研究中，幼鳥的 demise 指牠沒有存活。"},{"en":"The word is formal and often sounds more serious than death.","zh":"這個詞較正式，通常比 death 聽起來更嚴肅。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":8},{"front":"fish prey","meaning":"魚類獵物","examples":[{"en":"The fish prey fed to chicks came mainly from the reed edge.","zh":"餵給幼鳥的魚類獵物主要來自蘆葦邊緣。"},{"en":"Fish prey are fish that are hunted and eaten by another animal.","zh":"fish prey 指被另一種動物捕食和食用的魚。"},{"en":"A heron’s fish prey may include small fish found in shallow water.","zh":"蒼鷺的魚類獵物可能包括淺水中的小魚。"},{"en":"If fish prey are scarce, chicks may not receive enough food to survive.","zh":"如果魚類獵物稀少，幼鳥可能得不到足夠食物存活。"},{"en":"The phrase refers to food animals, not fish kept as pets.","zh":"這個短語指作為食物的動物，而不是寵物魚。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":8},{"front":"be dominated by","meaning":"以……為主","examples":[{"en":"The fish prey was dominated by species that entered the reed edge.","zh":"魚類獵物以進入蘆葦邊緣的物種為主。"},{"en":"To be dominated by something means to consist mainly of that thing or be strongly controlled by it.","zh":"be dominated by something 指主要由某事物構成或受到其強烈控制。"},{"en":"A school timetable may be dominated by exam preparation in the final month.","zh":"學校時間表在最後一個月可能以考試準備為主。"},{"en":"If the chicks’ diet is dominated by certain fish, protecting those fish becomes important.","zh":"如果幼鳥飲食以某些魚類為主，保護那些魚就變得重要。"},{"en":"The phrase shows what makes up the largest or strongest part.","zh":"這個短語顯示最大或最強部分是甚麼。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":8},{"front":"penetrate into","meaning":"進入；滲入","examples":[{"en":"Some fish species penetrated into the reed edge.","zh":"一些魚類物種進入蘆葦邊緣。"},{"en":"To penetrate into a place means to enter or move into it, often through a boundary.","zh":"penetrate into a place 指進入或移入某地，通常穿過邊界。"},{"en":"Rainwater may penetrate into soil after several hours of steady rain.","zh":"持續下雨幾小時後，雨水可能滲入土壤。"},{"en":"If fish can penetrate into reed edges, bitterns may find more prey close to nests.","zh":"如果魚能進入蘆葦邊緣，麻鳽可能在巢附近找到更多獵物。"},{"en":"The phrase describes movement into an area.","zh":"這個短語描述進入某區域的移動。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":8},{"front":"reed edge","meaning":"蘆葦邊緣","examples":[{"en":"Many fish prey species were found near the reed edge.","zh":"許多魚類獵物物種在蘆葦邊緣附近被發現。"},{"en":"The reed edge is the boundary area where reeds meet open water or another habitat.","zh":"reed edge 指蘆葦與開闊水面或其他棲息地相接的邊界區。"},{"en":"Birds may hunt at the reed edge because prey can move between cover and water.","zh":"鳥類可能在蘆葦邊緣捕獵，因為獵物可以在遮蔽和水域之間移動。"},{"en":"A healthy reed edge can support fish, insects, and feeding birds.","zh":"健康的蘆葦邊緣可以支持魚類、昆蟲和覓食鳥類。"},{"en":"The phrase refers to the margin of reed habitat.","zh":"這個短語指蘆葦棲息地的邊緣。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":8},{"front":"important element of","meaning":"……的重要元素","examples":[{"en":"An important element of recent studies was the development of recommendations.","zh":"近期研究的一個重要元素是制定建議。"},{"en":"An important element of something is a key part of it.","zh":"important element of something 指某事中的關鍵部分。"},{"en":"Regular feedback is an important element of effective writing lessons.","zh":"定期回饋是有效寫作課的重要元素。"},{"en":"If recommendations are a key element of research, the study is designed to guide real action.","zh":"如果建議是研究的關鍵元素，該研究就是為了引導實際行動。"},{"en":"The phrase highlights one major component within a larger project.","zh":"這個短語突出大型項目中的一個主要組成部分。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":8},{"front":"water conditions","meaning":"水域條件","examples":[{"en":"The studies produced recommendations on habitat and water conditions.","zh":"研究提出了關於棲息地和水域條件的建議。"},{"en":"Water conditions are the water levels, depth, quality, and movement in a habitat.","zh":"water conditions 指棲息地中的水位、深度、水質和流動情況。"},{"en":"A pond’s water conditions affect whether fish, frogs, and insects can live there.","zh":"池塘的水域條件影響魚、青蛙和昆蟲能否生活。"},{"en":"If water conditions are wrong, reed beds may dry out or fail to support prey.","zh":"如果水域條件不合適，蘆葦地可能乾涸或無法支持獵物。"},{"en":"The phrase refers to the watery environment animals depend on.","zh":"這個短語指動物依賴的水環境。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":8},{"front":"promote healthy native fish populations","meaning":"促進健康的本地魚類種群","examples":[{"en":"The recommendations aimed to promote healthy native fish populations.","zh":"這些建議旨在促進健康的本地魚類種群。"},{"en":"To promote healthy native fish populations means to help local fish species grow and remain stable.","zh":"promote healthy native fish populations 指幫助本地魚類物種增長並保持穩定。"},{"en":"A river project may promote native fish by improving water quality and removing barriers.","zh":"河流項目可能透過改善水質和移除障礙來促進本地魚類。"},{"en":"Healthy fish populations provide food for birds and show that wetland conditions are good.","zh":"健康魚類種群為鳥類提供食物，也顯示濕地條件良好。"},{"en":"The phrase links habitat management with food supply.","zh":"這個短語把棲息地管理與食物供應連起來。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":8},{"front":"native fish populations","meaning":"本地魚類種群","examples":[{"en":"Healthy native fish populations are important for bittern chicks.","zh":"健康的本地魚類種群對麻鳽幼鳥很重要。"},{"en":"Native fish populations are groups of fish species that naturally belong to a local area.","zh":"native fish populations 指自然屬於本地地區的魚類物種群體。"},{"en":"A pond with native fish may support birds better than one dominated by introduced species.","zh":"有本地魚類的池塘，可能比以外來物種為主的池塘更能支持鳥類。"},{"en":"If native fish populations decline, chicks that depend on fish may starve.","zh":"如果本地魚類種群下降，依賴魚類的幼鳥可能挨餓。"},{"en":"The phrase refers to local fish communities, not imported aquarium fish.","zh":"這個短語指本地魚類群落，而不是進口水族魚。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":8},{"front":"once independent","meaning":"一旦獨立","examples":[{"en":"Once independent, young bitterns sought out new sites.","zh":"一旦獨立，幼麻鳽便尋找新地點。"},{"en":"Once independent means after young animals can live without direct parental care.","zh":"once independent 指幼小動物能不再依賴親代直接照顧之後。"},{"en":"Once independent, a young bird may leave its birth area to find its own territory.","zh":"一旦獨立，幼鳥可能離開出生地尋找自己的領域。"},{"en":"Independence changes conservation needs because young animals begin moving across the landscape.","zh":"獨立會改變保育需要，因為幼小動物開始在地景中移動。"},{"en":"The phrase marks the stage after dependence on parents ends.","zh":"這個短語標示依賴父母結束後的階段。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":8},{"front":"radio-tagged young bitterns","meaning":"裝有無線電標籤的幼麻鳽","examples":[{"en":"Radio-tagged young bitterns were found to seek out new sites.","zh":"研究發現裝有無線電標籤的幼麻鳽會尋找新地點。"},{"en":"Radio-tagged young bitterns are juvenile bitterns fitted with tracking devices.","zh":"radio-tagged young bitterns 指裝有追蹤裝置的幼年麻鳽。"},{"en":"Scientists can follow radio-tagged birds after they leave hidden reed beds.","zh":"科學家可以在裝有無線電標籤的鳥離開隱蔽蘆葦地後繼續追蹤牠們。"},{"en":"Tracking young bitterns reveals whether they explore, survive, and settle elsewhere.","zh":"追蹤幼麻鳽揭示牠們是否探索、存活並在別處定居。"},{"en":"The phrase describes young birds being monitored by technology.","zh":"這個短語描述透過科技被監察的幼鳥。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":8},{"front":"seek out new sites","meaning":"尋找新地點","examples":[{"en":"Young bitterns seek out new sites during their first winter.","zh":"幼麻鳽在第一個冬季尋找新地點。"},{"en":"To seek out new sites means to actively look for new places to live, feed, or breed.","zh":"seek out new sites 指主動尋找新的生活、覓食或繁殖地點。"},{"en":"A student may seek out new study spaces if the library is too crowded.","zh":"如果圖書館太擠迫，學生可能尋找新的溫習地點。"},{"en":"If young birds seek new sites, conservationists need suitable habitats beyond the original area.","zh":"如果幼鳥尋找新地點，保育人士需要在原本地區以外提供合適棲息地。"},{"en":"The phrase suggests active searching, not accidental arrival.","zh":"這個短語暗示主動搜尋，而不是偶然到達。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":9},{"front":"first winter","meaning":"第一個冬季","examples":[{"en":"Young bitterns explore new sites during their first winter.","zh":"幼麻鳽在第一個冬季探索新地點。"},{"en":"First winter is the first winter season in an animal’s life.","zh":"first winter 指動物生命中的第一個冬季。"},{"en":"A young bird’s first winter can be difficult because food is scarcer and weather is colder.","zh":"幼鳥的第一個冬季可能很困難，因為食物較少而天氣較冷。"},{"en":"Survival during the first winter can strongly affect future population growth.","zh":"第一個冬季的存活可以強烈影響未來種群增長。"},{"en":"The phrase marks an important early-life period.","zh":"這個短語標示重要的早期生命階段。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":9},{"front":"a proportion of","meaning":"一部分","examples":[{"en":"A proportion of the young bitterns would remain on new sites.","zh":"一部分幼麻鳽會留在新地點。"},{"en":"A proportion of a group means some part or percentage of that group.","zh":"a proportion of a group 指該群體中的某一部分或百分比。"},{"en":"A proportion of students may prefer online lessons, while others prefer classrooms.","zh":"一部分學生可能偏好網上課，另一些則偏好課室。"},{"en":"If a proportion of young birds settle in new places, the population can spread.","zh":"如果一部分幼鳥在新地方定居，種群就可以擴散。"},{"en":"The phrase indicates part of a group, not necessarily most of it.","zh":"這個短語表示群體的一部分，不一定是大多數。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":9},{"front":"remain on new sites","meaning":"留在新地點","examples":[{"en":"Some young bitterns would remain on new sites to breed.","zh":"一些幼麻鳽會留在新地點繁殖。"},{"en":"To remain on new sites means to stay in newly discovered or newly occupied places.","zh":"remain on new sites 指留在新發現或新佔用的地方。"},{"en":"A family may remain in a new neighbourhood if schools and transport are suitable.","zh":"如果學校和交通合適，家庭可能留在新社區。"},{"en":"If young birds remain at new sites, conservation areas can develop into breeding locations.","zh":"如果幼鳥留在新地點，保育區可以發展成繁殖地。"},{"en":"The phrase describes staying rather than just visiting.","zh":"這個短語描述留下來，而不只是到訪。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":9},{"front":"if the conditions were suitable","meaning":"如果條件合適","examples":[{"en":"Young bitterns would breed if the conditions were suitable.","zh":"如果條件合適，幼麻鳽會繁殖。"},{"en":"If the conditions were suitable means if the environment had what was needed.","zh":"if the conditions were suitable 指如果環境具備所需條件。"},{"en":"A school sports day can continue if the weather conditions are suitable.","zh":"如果天氣條件合適，學校運動會可以繼續。"},{"en":"For birds, suitable conditions may include water, food, cover, and safe nesting places.","zh":"對鳥類而言，合適條件可能包括水、食物、遮蔽和安全巢址。"},{"en":"The phrase introduces the requirement for success.","zh":"這個短語引入成功所需條件。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":9},{"front":"LIFE-funded project","meaning":"LIFE基金資助項目","examples":[{"en":"A second LIFE-funded project aimed to provide suitable sites.","zh":"第二個 LIFE 基金資助項目旨在提供合適地點。"},{"en":"A LIFE-funded project is a conservation project supported by the EU LIFE Fund.","zh":"LIFE-funded project 指由歐盟 LIFE 基金支持的保育項目。"},{"en":"A LIFE-funded project may restore wetlands, build water controls, and monitor wildlife.","zh":"LIFE 基金資助項目可能修復濕地、建造水位控制設施和監察野生動物。"},{"en":"Funding makes large habitat work possible when local resources are not enough.","zh":"當本地資源不足，資金可以令大型棲息地工作成為可能。"},{"en":"The phrase identifies both the project and its financial support source.","zh":"這個短語同時指出項目及其資金來源。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":9},{"front":"aim to provide","meaning":"旨在提供","examples":[{"en":"The project aims to provide suitable sites in new areas.","zh":"該項目旨在於新區域提供合適地點。"},{"en":"To aim to provide something means to have the goal of making it available.","zh":"aim to provide something 指以提供某物為目標。"},{"en":"A school programme may aim to provide free tutoring for weaker students.","zh":"學校計劃可能旨在為較弱學生提供免費補習。"},{"en":"If a project provides new habitats, young birds have more places to settle.","zh":"如果項目提供新棲息地，幼鳥就有更多地方定居。"},{"en":"The phrase states the intended purpose of an action.","zh":"這個短語說明行動的目的。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":9},{"front":"suitable sites","meaning":"合適地點","examples":[{"en":"The project aims to provide suitable sites for bitterns.","zh":"該項目旨在為麻鳽提供合適地點。"},{"en":"Suitable sites are places with the right conditions for a species or activity.","zh":"suitable sites 指具備某物種或活動所需條件的地方。"},{"en":"A school garden needs a suitable site with sunlight, water access, and safe paths.","zh":"學校花園需要有陽光、水源和安全道路的合適地點。"},{"en":"For bitterns, suitable sites must provide wet reed beds, food, and cover.","zh":"對麻鳽而言，合適地點必須提供潮濕蘆葦地、食物和遮蔽。"},{"en":"The phrase refers to places that meet practical needs.","zh":"這個短語指符合實際需要的地方。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":9},{"front":"network of 19 sites","meaning":"由19個地點組成的網絡","examples":[{"en":"A network of 19 sites will support the bittern population.","zh":"由19個地點組成的網絡將支持麻鳽種群。"},{"en":"A network of 19 sites is a connected group of nineteen places working together for one purpose.","zh":"network of 19 sites 指十九個為同一目的合作的相連地點群。"},{"en":"A city may create a network of clinics so residents can get care near home.","zh":"城市可能建立診所網絡，讓居民能在家附近得到照顧。"},{"en":"A network of habitats reduces risk because the species is not dependent on one place.","zh":"棲息地網絡降低風險，因為物種不依賴單一地方。"},{"en":"The phrase stresses multiple linked locations, not one reserve alone.","zh":"這個短語強調多個相連地點，而不只是單一保護區。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":9},{"front":"partnership project","meaning":"合作項目","examples":[{"en":"The network was developed through a partnership project.","zh":"該網絡透過合作項目發展而成。"},{"en":"A partnership project is work done jointly by several organisations or groups.","zh":"partnership project 指由幾個組織或團體共同完成的工作。"},{"en":"A school and a local museum may run a partnership project on local history.","zh":"學校和本地博物館可能舉辦關於本地歷史的合作項目。"},{"en":"Partnerships allow different groups to share land, expertise, money, and labour.","zh":"合作讓不同團體分享土地、專業知識、資金和人力。"},{"en":"The phrase describes cooperation, not one organisation acting alone.","zh":"這個短語描述合作，而不是單一組織獨自行動。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":9},{"front":"secure a sustainable population","meaning":"確保可持續種群","examples":[{"en":"The project will secure a more sustainable UK bittern population.","zh":"該項目將確保英國麻鳽種群更可持續。"},{"en":"To secure a sustainable population means to make sure a species can survive and reproduce over the long term.","zh":"secure a sustainable population 指確保某物種能長期存活和繁殖。"},{"en":"A fishery may secure a sustainable population by limiting catches and protecting breeding areas.","zh":"漁業可能透過限制捕撈和保護繁殖區來確保可持續種群。"},{"en":"A wider, healthier population is less likely to disappear after one local disaster.","zh":"更廣泛、更健康的種群較不容易因一次本地災害而消失。"},{"en":"The phrase focuses on long-term survival, not a short-term increase only.","zh":"這個短語重點是長期存活，而不只是短期增加。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":9},{"front":"successful breeding outside","meaning":"在……以外成功繁殖","examples":[{"en":"The project encourages successful breeding outside the core area.","zh":"該項目鼓勵在核心區域以外成功繁殖。"},{"en":"Successful breeding outside a place means animals reproduce well beyond their usual main breeding area.","zh":"successful breeding outside a place 指動物在其通常主要繁殖區之外順利繁殖。"},{"en":"A rare bird population becomes safer if breeding succeeds outside one original reserve.","zh":"如果稀有鳥類能在一個原有保護區以外成功繁殖，種群會更安全。"},{"en":"Breeding outside the core area spreads risk and helps the species expand.","zh":"在核心區以外繁殖可以分散風險並幫助物種擴展。"},{"en":"The phrase describes reproduction in new or additional locations.","zh":"這個短語描述在新地點或額外地點繁殖。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":10},{"front":"less vulnerable to","meaning":"較不易受……影響","examples":[{"en":"A wider population is less vulnerable to chance events.","zh":"更廣泛分布的種群較不易受偶發事件影響。"},{"en":"Less vulnerable to something means less likely to be harmed by it.","zh":"less vulnerable to something 指較不容易受某事傷害。"},{"en":"A student with savings is less vulnerable to sudden transport costs.","zh":"有儲蓄的學生較不易受突然交通費影響。"},{"en":"If birds live at many sites, one flood or disease outbreak will cause less damage to the whole population.","zh":"如果鳥類生活在許多地點，一次洪水或疾病爆發對整個種群造成的傷害會較少。"},{"en":"The phrase describes reduced risk.","zh":"這個短語描述風險降低。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":10},{"front":"chance events","meaning":"偶發事件","examples":[{"en":"The project reduces the risk from chance events.","zh":"該項目降低偶發事件帶來的風險。"},{"en":"Chance events are unpredictable happenings that occur by accident or luck.","zh":"chance events 指因偶然或運氣而發生、難以預測的事件。"},{"en":"A sudden storm during an outdoor exam would be a chance event.","zh":"戶外考試期間突然出現暴風雨，就是偶發事件。"},{"en":"If a species lives in only one site, one chance event can destroy much of the population.","zh":"如果物種只生活在一個地點，一次偶發事件就可能摧毀大部分種群。"},{"en":"The phrase refers to random events that cannot be fully controlled.","zh":"這個短語指無法完全控制的隨機事件。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":10},{"front":"sea level rise","meaning":"海平面上升","examples":[{"en":"The bittern population is vulnerable to sea level rise.","zh":"麻鳽種群容易受海平面上升影響。"},{"en":"Sea level rise is the increase in average ocean height over time.","zh":"sea level rise 指平均海洋高度隨時間增加。"},{"en":"Coastal wetlands may be flooded more often because of sea level rise.","zh":"沿海濕地可能因海平面上升而更常被淹浸。"},{"en":"If sea levels rise, low-lying reed beds may become too salty or too deeply flooded.","zh":"如果海平面上升，低窪蘆葦地可能變得太鹹或被淹得太深。"},{"en":"The phrase describes a long-term environmental threat.","zh":"這個短語描述長期環境威脅。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":10},{"front":"by 2004","meaning":"到2004年","examples":[{"en":"By 2004, the number of booming male bitterns had increased to 55.","zh":"到2004年，鳴叫雄性麻鳽數量已增加至55隻。"},{"en":"By 2004 means before or at the time the year 2004 was reached.","zh":"by 2004 指在2004年到來之前或到該年時。"},{"en":"By 2004, a school might have introduced computers into most classrooms.","zh":"到2004年，學校可能已在大多數課室引入電腦。"},{"en":"This phrase helps show progress up to a specific point in time.","zh":"這個短語幫助顯示直到特定時間點的進展。"},{"en":"It marks a deadline or time boundary for the result.","zh":"它標示結果的期限或時間界線。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":10},{"front":"undertake management","meaning":"進行管理","examples":[{"en":"The increase happened mostly on sites undertaking management.","zh":"增長主要發生在進行管理的地點。"},{"en":"To undertake management means to carry out planned work to control or improve a place.","zh":"undertake management 指進行有計劃的工作，以控制或改善某地。"},{"en":"A park undertaking management may cut invasive plants and repair paths.","zh":"進行管理的公園可能清除入侵植物和修補小路。"},{"en":"If managed sites show better results, management is likely helping the species recover.","zh":"如果受管理地點顯示較好結果，管理很可能正在幫助物種恢復。"},{"en":"The phrase describes active conservation work at a site.","zh":"這個短語描述某地的主動保育工作。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":10},{"front":"advice derived from","meaning":"來自……的建議","examples":[{"en":"The management was based on advice derived from research.","zh":"管理基於來自研究的建議。"},{"en":"Advice derived from research is guidance developed from study results and evidence.","zh":"advice derived from research 指由研究結果和證據發展而成的指引。"},{"en":"A teacher may use advice derived from reading research to help weak readers.","zh":"老師可能使用來自閱讀研究的建議來幫助閱讀較弱學生。"},{"en":"Evidence-based advice is usually more reliable than advice based only on tradition.","zh":"以證據為基礎的建議通常比只基於傳統的建議更可靠。"},{"en":"The phrase shows that practical action came from scientific findings.","zh":"這個短語顯示實際行動來自科學發現。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":10},{"front":"at the core of","meaning":"是……的核心","examples":[{"en":"Science has been at the core of the bittern story.","zh":"科學一直是麻鳽故事的核心。"},{"en":"At the core of something means at its central or most important part.","zh":"at the core of something 指位於某事最中心或最重要部分。"},{"en":"Trust is at the core of a good teacher-student relationship.","zh":"信任是良好師生關係的核心。"},{"en":"If science is at the core of a conservation project, decisions are guided by evidence.","zh":"如果科學是保育項目的核心，決策就由證據引導。"},{"en":"The phrase identifies what is central to success.","zh":"這個短語指出成功的中心因素。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":10},{"front":"achieve success through","meaning":"透過……取得成功","examples":[{"en":"Success was achieved through trust, hard work and dedication.","zh":"成功是透過信任、努力和奉獻取得的。"},{"en":"To achieve success through something means to succeed because of those actions or qualities.","zh":"achieve success through something 指因某些行動或品質而成功。"},{"en":"A student may achieve success through regular practice and honest feedback.","zh":"學生可能透過定期練習和誠實回饋取得成功。"},{"en":"Conservation success often requires science, cooperation, and practical effort over many years.","zh":"保育成功通常需要多年科學、合作和實際努力。"},{"en":"The phrase links success with the reasons behind it.","zh":"這個短語把成功與背後原因連起來。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":10},{"front":"trust, hard work and dedication","meaning":"信任、努力和奉獻","examples":[{"en":"The project depended on trust, hard work and dedication.","zh":"該項目依靠信任、努力和奉獻。"},{"en":"Trust, hard work and dedication are qualities that help people cooperate and keep working toward a difficult goal.","zh":"trust, hard work and dedication 指幫助人們合作並持續朝困難目標努力的品質。"},{"en":"A school team needs trust, hard work and dedication to prepare a successful performance.","zh":"學校團隊需要信任、努力和奉獻，才能準備成功表演。"},{"en":"Without these qualities, long conservation projects may fail when problems appear.","zh":"沒有這些品質，長期保育項目遇到問題時可能失敗。"},{"en":"The phrase groups the human qualities behind success.","zh":"這個短語集合成功背後的人為品質。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":10},{"front":"wardens","meaning":"保護區管理員","examples":[{"en":"Wardens helped implement management at the sites.","zh":"保護區管理員協助在各地點實施管理。"},{"en":"Wardens are people who look after and manage protected areas, reserves, or public sites.","zh":"wardens 指照顧和管理保護區、自然保留地或公共地點的人。"},{"en":"A nature reserve warden may check paths, protect nests, and guide visitors.","zh":"自然保護區管理員可能檢查小路、保護巢穴和引導遊客。"},{"en":"Wardens are important because they turn conservation plans into daily action.","zh":"管理員很重要，因為他們把保育計劃轉化為日常行動。"},{"en":"The word refers to site managers or guardians.","zh":"這個詞指場地管理員或守護者。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":10},{"front":"implement management","meaning":"實施管理措施","examples":[{"en":"Managers, owners and wardens implemented management measures.","zh":"管理者、擁有人和保護區管理員實施了管理措施。"},{"en":"To implement management means to put planned management actions into practice.","zh":"implement management 指把計劃好的管理行動付諸實行。"},{"en":"A school implements classroom management when teachers apply rules consistently.","zh":"當老師一致執行規則時，學校就是在實施課室管理。"},{"en":"Conservation plans only work when people on the ground actually implement them.","zh":"保育計劃只有在現場人員真正實施時才有效。"},{"en":"The phrase describes action, not just planning.","zh":"這個短語描述行動，而不只是計劃。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":11},{"front":"drastic management","meaning":"大幅度管理措施","examples":[{"en":"Some sites implemented very drastic management.","zh":"一些地點實施了非常大幅度的管理措施。"},{"en":"Drastic management means strong, large-scale action that changes a site significantly.","zh":"drastic management 指強力、大規模並明顯改變地點的行動。"},{"en":"A park may need drastic management if invasive plants have taken over most of it.","zh":"如果入侵植物佔據公園大部分地方，公園可能需要大幅度管理。"},{"en":"Drastic action can be necessary when slow changes are not enough to save a habitat.","zh":"當緩慢改變不足以拯救棲息地，大幅行動可能必要。"},{"en":"The phrase suggests major intervention, not minor maintenance.","zh":"這個短語暗示重大介入，而不是小型維修。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":11},{"front":"secure the future of","meaning":"確保……的未來","examples":[{"en":"The project aimed to secure the future of this wetland species.","zh":"該項目旨在確保這個濕地物種的未來。"},{"en":"To secure the future of a species means to make its long-term survival more certain.","zh":"secure the future of a species 指令某物種長期存活更有保障。"},{"en":"A city may secure the future of old buildings by repairing them and finding new uses.","zh":"城市可能透過修復舊建築並尋找新用途來確保其未來。"},{"en":"If habitats are protected and populations recover, a species has a safer future.","zh":"如果棲息地受保護而種群恢復，物種未來就更安全。"},{"en":"The phrase focuses on long-term protection.","zh":"這個短語重點是長期保護。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":11},{"front":"wetland species","meaning":"濕地物種","examples":[{"en":"The bittern is a wetland species.","zh":"麻鳽是一種濕地物種。"},{"en":"A wetland species is a plant or animal that depends on wet habitats such as marshes, reed beds, or ponds.","zh":"wetland species 指依賴沼澤、蘆葦地或池塘等潮濕棲息地的植物或動物。"},{"en":"Frogs, dragonflies, and some water birds are wetland species.","zh":"青蛙、蜻蜓和一些水鳥都是濕地物種。"},{"en":"If wetlands disappear, wetland species lose the places they need to feed and breed.","zh":"如果濕地消失，濕地物種會失去覓食和繁殖所需地方。"},{"en":"The phrase identifies a species by its habitat type.","zh":"這個短語按棲息地類型識別物種。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":11},{"front":"constructed bunds","meaning":"人工堤壆","examples":[{"en":"Constructed bunds now help control the water level.","zh":"人工堤壆現在幫助控制水位。"},{"en":"Constructed bunds are man-made banks or barriers built to hold or control water.","zh":"constructed bunds 指人工建造、用來保留或控制水的堤岸或屏障。"},{"en":"Farmers may build bunds around fields to prevent water from draining away too quickly.","zh":"農夫可能在田地周圍建堤壆，以防水太快流走。"},{"en":"In wetlands, bunds can keep water at the level needed by reeds and wildlife.","zh":"在濕地中，堤壆可以把水保持在蘆葦和野生動物需要的水平。"},{"en":"The phrase refers to artificial earth or wall structures for water control.","zh":"這個短語指用於水位控制的人工土堤或牆狀結構。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":11},{"front":"major sluices","meaning":"主要水閘","examples":[{"en":"Five major sluices now control water levels.","zh":"五個主要水閘現在控制水位。"},{"en":"Major sluices are large water-control gates that regulate how water enters or leaves an area.","zh":"major sluices 指大型水位控制閘門，用來調節水進出某區域。"},{"en":"A wetland manager may open a sluice after heavy rain to prevent flooding.","zh":"大雨後，濕地管理者可能打開水閘以防 flooding。"},{"en":"Sluices help maintain water conditions needed by reed beds and wildlife.","zh":"水閘幫助維持蘆葦地和野生動物所需水域條件。"},{"en":"The phrase refers to important water-management structures.","zh":"這個短語指重要的水管理結構。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":11},{"front":"control the water level","meaning":"控制水位","examples":[{"en":"The bunds and sluices control the water level over 82 hectares.","zh":"堤壆和水閘控制82公頃範圍的水位。"},{"en":"To control the water level means to manage how high or low the water is.","zh":"control the water level 指管理水有多高或多低。"},{"en":"A farmer may control the water level in rice fields by opening and closing channels.","zh":"農夫可能透過開關水道控制稻田水位。"},{"en":"Proper water control can prevent reed beds from drying out or flooding too deeply.","zh":"妥善水位控制可以防止蘆葦地乾涸或淹得太深。"},{"en":"The phrase describes managing water height for habitat needs.","zh":"這個短語描述為棲息地需要管理水高。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":11},{"front":"come under control","meaning":"納入控制範圍","examples":[{"en":"A further 50 hectares came under control later.","zh":"另外50公頃後來納入控制範圍。"},{"en":"To come under control means to become managed or regulated by a system or authority.","zh":"come under control 指變成由某制度或權力管理或規管。"},{"en":"A noisy classroom may come under control when clear rules are applied consistently.","zh":"當清晰規則被一致執行，嘈吵課室可能受控。"},{"en":"When more land comes under water-level control, managers can improve a larger habitat area.","zh":"當更多土地納入水位控制，管理者可以改善更大棲息地範圍。"},{"en":"The phrase describes becoming manageable.","zh":"這個短語描述變得可管理。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":11},{"front":"reed establishment","meaning":"蘆葦建立","examples":[{"en":"Reed establishment used natural regeneration and planted seedlings.","zh":"蘆葦建立使用自然再生和已種植幼苗。"},{"en":"Reed establishment is the process of creating or encouraging reed growth in an area.","zh":"reed establishment 指在某區域創造或促進蘆葦生長的過程。"},{"en":"A wetland project may support reed establishment by planting young reeds and protecting them from grazing.","zh":"濕地項目可能透過種植幼蘆葦並保護它們免受放牧影響來支持蘆葦建立。"},{"en":"Once reeds establish, they can provide cover and nesting habitat for wetland birds.","zh":"一旦蘆葦建立，它們可以為濕地鳥類提供遮蔽和築巢棲息地。"},{"en":"The phrase refers to getting reed vegetation started successfully.","zh":"這個短語指成功開始蘆葦植被。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":11},{"front":"natural regeneration","meaning":"自然再生","examples":[{"en":"Reed establishment has principally used natural regeneration.","zh":"蘆葦建立主要使用自然再生。"},{"en":"Natural regeneration is the process by which plants regrow by themselves without heavy planting.","zh":"natural regeneration 指植物在沒有大量種植下自行重新生長的過程。"},{"en":"A woodland may recover through natural regeneration if young trees grow from seeds already in the soil.","zh":"如果幼樹從土壤中的種子長出，林地可能透過自然再生恢復。"},{"en":"Natural regeneration can be cheaper and better adapted to local conditions than full replanting.","zh":"自然再生可能比全面重新種植更便宜，也更適應本地條件。"},{"en":"The phrase describes recovery through natural growth.","zh":"這個短語描述透過自然生長恢復。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":11},{"front":"planted seedlings","meaning":"已種植的幼苗","examples":[{"en":"Planted seedlings helped create small core areas.","zh":"已種植的幼苗幫助創造小型核心區域。"},{"en":"Planted seedlings are young plants placed in the ground by people.","zh":"planted seedlings 指由人種入地裏的年幼植物。"},{"en":"A school garden may begin with planted seedlings of herbs and vegetables.","zh":"學校花園可能由已種植的香草和蔬菜幼苗開始。"},{"en":"Seedlings can help start vegetation where natural regrowth is too slow.","zh":"在自然再生太慢的地方，幼苗可以幫助開始植被生長。"},{"en":"The phrase refers to young plants used in restoration.","zh":"這個短語指修復中使用的年幼植物。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":11},{"front":"core areas","meaning":"核心區域","examples":[{"en":"Small core areas will expand into larger reed areas.","zh":"小型核心區域將擴展成更大的蘆葦區。"},{"en":"Core areas are central starting zones from which a habitat or project can grow outward.","zh":"core areas 指棲息地或項目可以向外發展的中心起始區。"},{"en":"A school may create a small reading corner as a core area for a future library space.","zh":"學校可能建立小型閱讀角，作為未來圖書館空間的核心區域。"},{"en":"Once core reed areas are established, they can spread and connect into larger habitat.","zh":"一旦核心蘆葦區建立，它們可以擴散並連接成更大棲息地。"},{"en":"The phrase describes the starting centres of development.","zh":"這個短語描述發展的起始中心。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":12},{"front":"in time","meaning":"過一段時間後","examples":[{"en":"The core areas will in time expand to create a bigger reed area.","zh":"核心區域過一段時間後會擴展，形成更大的蘆葦區。"},{"en":"In time means after a period has passed, not immediately.","zh":"in time 指經過一段時間後，而不是立即。"},{"en":"A nervous speaker may become confident in time with practice and support.","zh":"緊張的演講者在練習和支援下，過一段時間後可能變得自信。"},{"en":"Habitat restoration often works slowly because plants need time to grow and spread.","zh":"棲息地修復通常慢慢見效，因為植物需要時間生長和擴散。"},{"en":"The phrase stresses gradual future development.","zh":"這個短語強調逐漸的未來發展。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":12},{"front":"reed cover","meaning":"蘆葦覆蓋","examples":[{"en":"Reed cover is now extensive.","zh":"蘆葦覆蓋現在很廣泛。"},{"en":"Reed cover is the area of land or water covered by reeds.","zh":"reed cover 指被蘆葦覆蓋的土地或水域面積。"},{"en":"A wetland with thick reed cover may provide shelter for shy birds.","zh":"有濃密蘆葦覆蓋的濕地可能為害羞鳥類提供遮蔽。"},{"en":"More reed cover can increase nesting habitat, but it must be managed with suitable water conditions.","zh":"更多蘆葦覆蓋可以增加築巢棲息地，但必須配合合適水域條件管理。"},{"en":"The phrase describes how much of a site is covered by reeds.","zh":"這個短語描述某地有多少範圍被蘆葦覆蓋。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":12},{"front":"extensive","meaning":"廣泛的","examples":[{"en":"The reed cover at the site is extensive.","zh":"該地點的蘆葦覆蓋很廣泛。"},{"en":"Extensive means covering a large area or including a large amount.","zh":"extensive 指覆蓋大範圍或包含大量。"},{"en":"A school with extensive sports facilities may have fields, courts, and a swimming pool.","zh":"有廣泛運動設施的學校可能有球場、場地和游泳池。"},{"en":"Extensive reed cover can create more habitat for birds that need dense vegetation.","zh":"廣泛蘆葦覆蓋可以為需要濃密植被的鳥類創造更多棲息地。"},{"en":"The word suggests large scale, not a small patch.","zh":"這個詞暗示大規模，而不是小片區域。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":12},{"front":"ditches","meaning":"水溝","examples":[{"en":"More than three kilometres of new ditches have been formed.","zh":"超過三公里的新水溝已經形成。"},{"en":"Ditches are narrow channels dug in the ground to carry or hold water.","zh":"ditches 指挖在地面、用來輸送或保存水的狹窄渠道。"},{"en":"Farmers may use ditches to drain fields after heavy rain.","zh":"大雨後，農夫可能用水溝排走田地積水。"},{"en":"In wetlands, ditches can help manage water movement and create feeding edges.","zh":"在濕地中，水溝可以幫助管理水流並創造覓食邊緣。"},{"en":"The word refers to water channels, not ordinary paths.","zh":"這個詞指水道，而不是普通小路。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":12},{"front":"be re-profiled","meaning":"被重新整形","examples":[{"en":"Existing ditches have been re-profiled.","zh":"現有水溝已被重新整形。"},{"en":"To be re-profiled means to have the shape or slope changed for a new purpose.","zh":"be re-profiled 指形狀或斜度被改變，以符合新目的。"},{"en":"A road may be re-profiled so rainwater drains away more safely.","zh":"道路可能被重新整形，使雨水更安全排走。"},{"en":"Re-profiling ditches can improve water flow and make wetland edges more useful for wildlife.","zh":"重新整形水溝可以改善水流，並令濕地邊緣對野生動物更有用。"},{"en":"The phrase describes reshaping an existing feature.","zh":"這個短語描述把現有地貌重新塑形。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":12},{"front":"old meander","meaning":"舊河曲","examples":[{"en":"Old meander features have been cleaned out.","zh":"舊河曲特徵已被清理。"},{"en":"An old meander is a former bend or curve in a river or water channel.","zh":"old meander 指河流或水道過去的彎曲部分。"},{"en":"A map may show an old meander where a river once curved before changing course.","zh":"地圖可能顯示舊河曲，即河流改道前曾經彎曲的地方。"},{"en":"Cleaning old meanders can restore water features and improve wetland structure.","zh":"清理舊河曲可以恢復水域特徵並改善濕地結構。"},{"en":"The phrase refers to an old curved watercourse feature.","zh":"這個短語指舊有彎曲水道地貌。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":12},{"front":"former estuarine features","meaning":"前河口地貌","examples":[{"en":"The old meander was a former estuarine feature.","zh":"舊河曲是一種前河口地貌。"},{"en":"Former estuarine features are land or water features that once belonged to an estuary environment.","zh":"former estuarine features 指曾經屬於河口環境的土地或水域地貌。"},{"en":"An old tidal channel may be a former estuarine feature if the coast has changed.","zh":"如果海岸已改變，舊潮汐水道可能是前河口地貌。"},{"en":"Restoring such features can help recreate wetland conditions.","zh":"修復這類地貌可以幫助重建濕地條件。"},{"en":"The phrase describes historical landscape features linked to river mouths and tides.","zh":"這個短語描述與河口和潮汐有關的歷史地景特徵。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":12},{"front":"be cleaned out","meaning":"被清理","examples":[{"en":"Old meander features have been cleaned out.","zh":"舊河曲特徵已被清理。"},{"en":"To be cleaned out means to have unwanted material removed from inside.","zh":"be cleaned out 指內部不需要的物質被移除。"},{"en":"A blocked drain may be cleaned out so water can flow again.","zh":"堵塞水渠可能被清理，使水能再次流動。"},{"en":"Cleaning out old channels can improve water movement through a wetland.","zh":"清理舊水道可以改善濕地中的水流。"},{"en":"The phrase describes removing silt, plants, or debris from a feature.","zh":"這個短語描述從某地貌中移除淤泥、植物或碎屑。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":12},{"front":"winter regularly","meaning":"定期在當地過冬","examples":[{"en":"Bitterns now winter regularly at the site.","zh":"麻鳽現在定期在該地點過冬。"},{"en":"To winter regularly at a site means to spend the winter there repeatedly or every year.","zh":"winter regularly at a site 指重複或每年在某地過冬。"},{"en":"Some birds winter regularly in warmer coastal wetlands.","zh":"一些鳥類定期在較暖的沿海濕地過冬。"},{"en":"If bitterns winter regularly at a reserve, the site is useful outside the breeding season too.","zh":"如果麻鳽定期在保護區過冬，該地點在繁殖季以外也有用。"},{"en":"The phrase describes repeated seasonal use.","zh":"這個短語描述重複的季節性使用。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":12},{"front":"indication that","meaning":"有跡象顯示","examples":[{"en":"There is some indication that bitterns remain longer into spring.","zh":"有一些跡象顯示麻鳽留到春季更後期。"},{"en":"An indication that something is true is a sign or piece of evidence suggesting it.","zh":"indication that something is true 指暗示某事為真的跡象或證據。"},{"en":"A student’s improved homework may be an indication that tutoring is helping.","zh":"學生功課改善可能是補習有幫助的跡象。"},{"en":"Early signs are useful, but they may need more evidence before firm conclusions are made.","zh":"早期跡象有用，但在作出堅定結論前可能需要更多證據。"},{"en":"The phrase introduces a cautious observation.","zh":"這個短語引入謹慎觀察。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":12},{"front":"remain longer into spring","meaning":"留到春季更後期","examples":[{"en":"Bitterns may remain longer into spring.","zh":"麻鳽可能留到春季更後期。"},{"en":"To remain longer into spring means to stay at a site later in the spring season than before.","zh":"remain longer into spring 指比以前更晚留在某地進入春季。"},{"en":"Migrating birds may remain longer into spring if food and shelter improve.","zh":"如果食物和遮蔽改善，候鳥可能留到春季更後期。"},{"en":"Staying longer may suggest that the habitat is becoming more suitable.","zh":"停留更久可能暗示棲息地變得更合適。"},{"en":"The phrase describes extended seasonal presence.","zh":"這個短語描述延長的季節性出現。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":13},{"front":"breeding has yet to occur","meaning":"尚未發生繁殖","examples":[{"en":"Breeding has yet to occur at the site.","zh":"該地點尚未發生繁殖。"},{"en":"Breeding has yet to occur means breeding has not happened so far, though it may happen later.","zh":"breeding has yet to occur 指繁殖到目前為止尚未發生，但日後可能發生。"},{"en":"A new school club has yet to win a competition, but it may improve next year.","zh":"新學會尚未贏得比賽，但明年可能進步。"},{"en":"If birds visit but do not breed, the habitat may still need further improvement.","zh":"如果鳥類到訪但不繁殖，棲息地可能仍需要進一步改善。"},{"en":"The phrase expresses that something expected has not happened yet.","zh":"這個短語表示某件預期的事尚未發生。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":13},{"front":"booming male was present","meaning":"有鳴叫雄鳥出現","examples":[{"en":"A booming male was present in spring 2004.","zh":"2004年春季有一隻鳴叫雄鳥出現。"},{"en":"A booming male was present means a calling male bittern was detected at the site.","zh":"booming male was present 指在該地點偵測到一隻鳴叫雄性麻鳽。"},{"en":"If a singing male bird is present in spring, it may suggest possible breeding activity.","zh":"如果春季有鳴唱雄鳥出現，可能暗示有繁殖活動。"},{"en":"The presence of one booming male can be an early sign that habitat conditions are improving.","zh":"一隻鳴叫雄鳥的出現可以是棲息地條件改善的早期跡象。"},{"en":"The phrase records an observation of a male bird during the breeding period.","zh":"這個短語記錄繁殖期內對雄鳥的觀察。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":13},{"front":"wildfowl species","meaning":"野禽物種","examples":[{"en":"Several wildfowl species breed at the site.","zh":"幾種野禽物種在該地點繁殖。"},{"en":"Wildfowl species are water birds such as ducks, geese, and swans.","zh":"wildfowl species 指鴨、鵝和天鵝等水鳥物種。"},{"en":"A lake may attract wildfowl species if it has open water and safe nesting edges.","zh":"如果湖泊有開闊水面和安全築巢邊緣，它可能吸引野禽物種。"},{"en":"If several wildfowl species breed at a site, the wetland is supporting more than one kind of bird.","zh":"如果幾種野禽物種在某地繁殖，該濕地就支持不止一種鳥類。"},{"en":"The phrase refers to groups of waterfowl species.","zh":"這個短語指水禽物種群。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":13},{"front":"reed-bed passerines","meaning":"蘆葦地雀形目鳥類","examples":[{"en":"Many reed-bed passerines breed there.","zh":"許多蘆葦地雀形目鳥類在那裏繁殖。"},{"en":"Reed-bed passerines are small perching birds that live or breed in reed-bed habitats.","zh":"reed-bed passerines 指生活或繁殖於蘆葦地棲息地的小型棲鳥。"},{"en":"Warblers and buntings can be reed-bed passerines when they nest among reeds.","zh":"鶯類和鵐類在蘆葦中築巢時，可以屬於蘆葦地雀形目鳥類。"},{"en":"A healthy reed bed may support these small birds as well as larger wetland species.","zh":"健康蘆葦地可以支持這些小鳥，也能支持較大型濕地物種。"},{"en":"The phrase refers to songbird-like birds associated with reeds.","zh":"這個短語指與蘆葦有關的鳴禽類鳥。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":13},{"front":"reed buntings","meaning":"蘆鵐","examples":[{"en":"Reed buntings are among the reed-bed birds at the site.","zh":"蘆鵐是該地點蘆葦地鳥類之一。"},{"en":"Reed buntings are small birds often found in reed beds and wet grassland.","zh":"reed buntings 指常見於蘆葦地和濕草地的小型鳥類。"},{"en":"A birdwatcher may see reed buntings perched on reed stems near a marsh.","zh":"觀鳥者可能看見蘆鵐停在沼澤附近的蘆葦莖上。"},{"en":"Their presence can show that the site supports smaller reed-bed bird life.","zh":"牠們的出現可以顯示該地點支持較小型蘆葦地鳥類。"},{"en":"The phrase names one bird species associated with reed habitats.","zh":"這個短語命名一種與蘆葦棲息地有關的鳥類。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":13},{"front":"sedge and grasshopper warblers","meaning":"莎草鶯和草蜢鶯","examples":[{"en":"Sedge and grasshopper warblers breed at the site.","zh":"莎草鶯和草蜢鶯在該地點繁殖。"},{"en":"Sedge and grasshopper warblers are small songbirds associated with wetland or grassy habitats.","zh":"sedge and grasshopper warblers 指與濕地或草地棲息地有關的小型鳴禽。"},{"en":"Birdwatchers may identify warblers by their songs because they are often hard to see.","zh":"觀鳥者可能透過歌聲辨認鶯類，因為牠們常很難看見。"},{"en":"If these warblers breed at a site, the vegetation may be suitable for small nesting birds.","zh":"如果這些鶯類在某地繁殖，植被可能適合小型築巢鳥類。"},{"en":"The phrase names two bird species that benefit from reed-bed habitat.","zh":"這個短語命名兩種受益於蘆葦地棲息地的鳥類。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":13},{"front":"wintering shoveler","meaning":"越冬琵嘴鴨","examples":[{"en":"Numbers of wintering shoveler have increased.","zh":"越冬琵嘴鴨數量已經增加。"},{"en":"Wintering shoveler are shoveler ducks that spend the winter at a site.","zh":"wintering shoveler 指在某地過冬的琵嘴鴨。"},{"en":"A wetland with safe open water may attract wintering ducks during cold months.","zh":"有安全開闊水面的濕地，可能在寒冷月份吸引越冬鴨類。"},{"en":"If wintering shoveler numbers increase, the site may be improving as winter habitat.","zh":"如果越冬琵嘴鴨數量增加，該地點可能正作為冬季棲息地改善。"},{"en":"The phrase refers to seasonal winter use by a duck species.","zh":"這個短語指某鴨類物種的季節性越冬使用。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":13},{"front":"support a nationally important population","meaning":"支持具全國重要性的種群","examples":[{"en":"The site supports a nationally important wintering population.","zh":"該地點支持一個具全國重要性的越冬種群。"},{"en":"To support a nationally important population means to hold enough individuals to matter at the country level.","zh":"support a nationally important population 指承載足夠多個體，使其在國家層面重要。"},{"en":"A wetland may support a nationally important bird population if many of that species gather there each winter.","zh":"如果某物種每年冬天大量聚集在濕地，該濕地可能支持具全國重要性的鳥類種群。"},{"en":"Such sites often deserve stronger protection because their loss would affect the whole country’s conservation status.","zh":"這類地點通常值得更強保護，因為失去它會影響整個國家的保育狀況。"},{"en":"The phrase describes a population significant beyond the local area.","zh":"這個短語描述重要性超越本地的種群。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":13},{"front":"Malltraeth Reserve","meaning":"Malltraeth 保護區","examples":[{"en":"Malltraeth Reserve is part of the UK network of key sites.","zh":"Malltraeth 保護區是英國重要地點網絡的一部分。"},{"en":"Malltraeth Reserve is a protected site mentioned as part of the bittern conservation network.","zh":"Malltraeth Reserve 指文中提及、屬於麻鳽保育網絡的受保護地點。"},{"en":"A reserve like Malltraeth may manage water, reeds, and wildlife to support wetland species.","zh":"像 Malltraeth 這樣的保護區可能管理水、蘆葦和野生動物，以支持濕地物種。"},{"en":"Including reserves in a network helps spread conservation benefits across different places.","zh":"把保護區納入網絡有助把保育效益擴展至不同地方。"},{"en":"The phrase names a specific conservation site.","zh":"這個短語命名一個特定保育地點。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":13},{"front":"key sites","meaning":"重要地點","examples":[{"en":"The reserve is part of a network of key sites.","zh":"該保護區是重要地點網絡的一部分。"},{"en":"Key sites are especially important places for conservation, breeding, feeding, or survival.","zh":"key sites 指對保育、繁殖、覓食或存活特別重要的地方。"},{"en":"A beach may be a key site for turtles if many females lay eggs there.","zh":"如果許多雌性海龜在某海灘產卵，該海灘可能是重要地點。"},{"en":"Protecting key sites can have a large effect on the survival of a species.","zh":"保護重要地點可以對物種存活產生重大影響。"},{"en":"The phrase identifies places that matter most.","zh":"這個短語指出最重要的地方。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":13},{"front":"water vole","meaning":"水䶄","examples":[{"en":"Malltraeth Reserve is a key site for the water vole.","zh":"Malltraeth 保護區是水䶄的重要地點。"},{"en":"A water vole is a small semi-aquatic mammal that lives near rivers, ditches, and wetlands.","zh":"water vole 指生活在河流、水溝和濕地附近的小型半水生哺乳動物。"},{"en":"A water vole may dig burrows along soft riverbanks and feed on plants.","zh":"水䶄可能沿柔軟河岸挖洞，並以植物為食。"},{"en":"Healthy wetland edges can support water voles as well as birds.","zh":"健康濕地邊緣可以支持水䶄，也可以支持鳥類。"},{"en":"The phrase names a mammal that benefits from wetland conservation.","zh":"這個短語命名一種受益於濕地保育的哺乳動物。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":14},{"front":"priority species","meaning":"優先保育物種","examples":[{"en":"The water vole is a UK priority species.","zh":"水䶄是英國優先保育物種。"},{"en":"A priority species is a species selected as especially important for conservation action.","zh":"priority species 指被選為特別需要保育行動的物種。"},{"en":"A rare frog may become a priority species if its habitat is disappearing quickly.","zh":"如果稀有青蛙的棲息地迅速消失，它可能成為優先保育物種。"},{"en":"Priority status can help attract funding, monitoring, and habitat protection.","zh":"優先地位可以幫助吸引資金、監測和棲息地保護。"},{"en":"The phrase means the species is high on the conservation list.","zh":"這個短語表示該物種在保育清單上很重要。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":14},{"front":"monitoring transects","meaning":"監測樣線","examples":[{"en":"Twelve monitoring transects have been established.","zh":"十二條監測樣線已經建立。"},{"en":"Monitoring transects are fixed survey lines used to record plants, animals, or habitat features.","zh":"monitoring transects 指用來記錄植物、動物或棲息地特徵的固定調查路線。"},{"en":"Scientists may walk the same transect each month to count butterflies.","zh":"科學家可能每月走同一條樣線來點算蝴蝶。"},{"en":"Transects make monitoring consistent because observers check the same route each time.","zh":"樣線令監測保持一致，因為觀察者每次檢查同一路線。"},{"en":"The phrase refers to a structured survey method.","zh":"這個短語指有結構的調查方法。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":14},{"front":"be established","meaning":"被建立","examples":[{"en":"Twelve monitoring transects have been established.","zh":"十二條監測樣線已被建立。"},{"en":"To be established means to be set up, created, or formally put in place.","zh":"be established 指被設立、創建或正式安排。"},{"en":"A school may establish a reading club after many students request it.","zh":"許多學生要求後，學校可能建立閱讀學會。"},{"en":"Once monitoring routes are established, long-term data can be collected consistently.","zh":"一旦監測路線被建立，長期數據就能一致地收集。"},{"en":"The phrase describes something being created for regular use.","zh":"這個短語描述某物被創造作定期使用。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":14},{"front":"otters and brown hares","meaning":"水獺和棕野兔","examples":[{"en":"Otters and brown hares occur at the site.","zh":"水獺和棕野兔出現在該地點。"},{"en":"Otters and brown hares are mammals that may benefit from suitable wetland and grassland habitats.","zh":"otters and brown hares 指可能受益於合適濕地和草地棲息地的哺乳動物。"},{"en":"An otter may use rivers and ditches, while a brown hare may use open grassland nearby.","zh":"水獺可能使用河流和水溝，而棕野兔可能使用附近開闊草地。"},{"en":"Their presence shows that habitat work can support more than the target bird species.","zh":"牠們的出現顯示棲息地工作可以支持不只目標鳥類。"},{"en":"The phrase names two mammals found at the site.","zh":"這個短語命名在該地點發現的兩種哺乳動物。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":14},{"front":"rare plant pillwort","meaning":"稀有植物 Pillwort","examples":[{"en":"The rare plant pillwort occurs at the site.","zh":"稀有植物 Pillwort 出現在該地點。"},{"en":"The rare plant pillwort is an uncommon wetland plant mentioned as part of the site’s biodiversity.","zh":"rare plant pillwort 指文中作為該地點生物多樣性一部分提及的少見濕地植物。"},{"en":"A reserve may protect rare plants by controlling water levels and reducing disturbance.","zh":"保護區可能透過控制水位和減少干擾來保護稀有植物。"},{"en":"If rare plants occur at a site, habitat management may benefit vegetation as well as animals.","zh":"如果稀有植物出現在某地，棲息地管理可能同時有益於植被和動物。"},{"en":"The phrase names a rare plant species found there.","zh":"這個短語命名在該地點發現的一種稀有植物。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":14},{"front":"choose the correct heading","meaning":"選擇正確標題","examples":[{"en":"Students choose the correct heading for each paragraph.","zh":"學生為每段選擇正確標題。"},{"en":"To choose the correct heading means to select the title that best matches a paragraph’s main idea.","zh":"choose the correct heading 指選擇最符合段落主旨的標題。"},{"en":"In a reading test, students should read the whole paragraph before choosing the heading.","zh":"在閱讀測驗中，學生應讀完整段後才選標題。"},{"en":"A correct heading captures the main point, not just one small detail.","zh":"正確標題捕捉主要意思，而不是單一小細節。"},{"en":"The phrase is an exam instruction about identifying main ideas.","zh":"這個短語是關於辨認主旨的考試指示。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":14},{"front":"list of headings","meaning":"標題列表","examples":[{"en":"The list of headings gives possible paragraph titles.","zh":"標題列表提供可能的段落標題。"},{"en":"A list of headings is a set of title options used in a matching task.","zh":"list of headings 指配對題中使用的一組標題選項。"},{"en":"Students should compare all headings before choosing one for a paragraph.","zh":"學生應比較所有標題，再為段落選一個。"},{"en":"Similar headings can confuse students if they rely only on repeated words.","zh":"如果學生只依靠重複字，相似標題可能令人混淆。"},{"en":"The phrase refers to answer choices for paragraph-title questions.","zh":"這個短語指段落標題題的答案選項。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":14},{"front":"write the correct number","meaning":"寫出正確編號","examples":[{"en":"Students write the correct number in the answer boxes.","zh":"學生在答案格中寫出正確編號。"},{"en":"Write the correct number means put the number of the chosen option as the answer.","zh":"write the correct number 指把所選選項的編號寫作答案。"},{"en":"If heading iii is correct, students should write iii rather than copying the full heading.","zh":"如果標題 iii 正確，學生應寫 iii，而不是抄完整標題。"},{"en":"Writing the correct number clearly helps markers read the answer accurately.","zh":"清楚寫出正確編號有助評卷者準確閱讀答案。"},{"en":"The phrase is a standard instruction in matching questions.","zh":"這個短語是配對題中的標準指示。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":14},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生把答案寫在答題紙上。"},{"en":"An answer sheet is the official paper or form where candidates record final answers.","zh":"answer sheet 指考生記錄最終答案的正式紙張或表格。"},{"en":"A student may lose marks if she writes the answer in the question booklet but not on the answer sheet.","zh":"如果學生把答案寫在試題冊而不是答題紙上，可能會失分。"},{"en":"Clear answers on the answer sheet make marking easier and safer.","zh":"答題紙上的清楚答案令評分更容易、更安全。"},{"en":"The phrase refers to the place where final exam answers must go.","zh":"這個短語指最終考試答案必須寫上的地方。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":14},{"front":"research findings about","meaning":"關於……的研究結果","examples":[{"en":"One heading refers to research findings about habitat.","zh":"其中一個標題指關於棲息地的研究結果。"},{"en":"Research findings about something are results or conclusions discovered through study.","zh":"research findings about something 指透過研究發現的結果或結論。"},{"en":"Research findings about sleep may show that students remember more after enough rest.","zh":"關於睡眠的研究結果可能顯示學生休息足夠後記得更多。"},{"en":"Findings about habitat can guide practical conservation decisions.","zh":"關於棲息地的發現可以引導實際保育決策。"},{"en":"The phrase connects scientific study with what was learned.","zh":"這個短語把科學研究與所得知識連起來。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":14},{"front":"resulting management decisions","meaning":"由此產生的管理決定","examples":[{"en":"The heading links research findings with resulting management decisions.","zh":"該標題把研究結果與由此產生的管理決定連起來。"},{"en":"Resulting management decisions are choices made because of earlier findings or evidence.","zh":"resulting management decisions 指因早前發現或證據而作出的選擇。"},{"en":"A school survey may lead to resulting management decisions such as changing lunch times.","zh":"學校調查可能導致由此產生的管理決定，例如改變午餐時間。"},{"en":"If research shows birds need wet reed edges, managers may decide to raise water levels.","zh":"如果研究顯示鳥類需要潮濕蘆葦邊緣，管理者可能決定提高水位。"},{"en":"The phrase shows how evidence leads to action.","zh":"這個短語顯示證據如何導致行動。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":15},{"front":"fluctuations in","meaning":"……的波動","examples":[{"en":"The passage describes fluctuations in bittern numbers.","zh":"文章描述麻鳽數量的波動。"},{"en":"Fluctuations in something are rises and falls over time.","zh":"fluctuations in something 指某事隨時間上升和下降。"},{"en":"A shop may see fluctuations in sales during holidays and exam periods.","zh":"商店在假期和考試期間可能見到銷售波動。"},{"en":"Tracking fluctuations helps people understand whether a trend is stable, rising, or declining.","zh":"追蹤波動幫助人們理解趨勢是穩定、上升還是下降。"},{"en":"The phrase describes changes that move up and down.","zh":"這個短語描述上下變化。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":15},{"front":"protect young bitterns","meaning":"保護幼麻鳽","examples":[{"en":"One heading concerns protecting young bitterns.","zh":"其中一個標題關於保護幼麻鳽。"},{"en":"To protect young bitterns means to reduce risks to chicks and juveniles so they can survive.","zh":"protect young bitterns 指減少雛鳥和幼鳥面對的風險，使牠們能存活。"},{"en":"Conservationists may protect young birds by ensuring enough food and safe nesting areas.","zh":"保育人士可能透過確保足夠食物和安全巢區來保護幼鳥。"},{"en":"If young bitterns survive, the future breeding population becomes stronger.","zh":"如果幼麻鳽存活，未來繁殖種群會更強。"},{"en":"The phrase focuses on the safety and survival of young birds.","zh":"這個短語重點是幼鳥的安全和存活。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":15},{"front":"international cooperation","meaning":"國際合作","examples":[{"en":"International cooperation helped the conservation project succeed.","zh":"國際合作幫助保育項目成功。"},{"en":"International cooperation means countries or organisations from different countries working together.","zh":"international cooperation 指不同國家的國家或組織共同工作。"},{"en":"A wildlife project may use international cooperation to share funding, research, and expertise.","zh":"野生動物項目可能透過國際合作分享資金、研究和專業知識。"},{"en":"Some species need international cooperation because their habitats or migration routes cross borders.","zh":"有些物種需要國際合作，因為牠們的棲息地或遷徙路線跨越國界。"},{"en":"The phrase describes teamwork beyond one country.","zh":"這個短語描述超越單一國家的合作。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":15},{"front":"method for counting","meaning":"點算……的方法","examples":[{"en":"The researchers developed a method for counting bitterns.","zh":"研究人員制定了一種點算麻鳽的方法。"},{"en":"A method for counting something is a systematic way to find out how many there are.","zh":"method for counting something 指系統地找出數量的方法。"},{"en":"A teacher may use a sign-in sheet as a method for counting students at a workshop.","zh":"老師可能用簽到表作為點算工作坊學生的方法。"},{"en":"A good counting method prevents double-counting and missed individuals.","zh":"良好點算方法可以防止重複點算和漏算個體。"},{"en":"The phrase focuses on reliable measurement.","zh":"這個短語重點是可靠量度。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":15},{"front":"importance of food","meaning":"食物的重要性","examples":[{"en":"The passage discusses the importance of food for bittern chicks.","zh":"文章討論食物對麻鳽幼鳥的重要性。"},{"en":"The importance of food means the crucial role food plays in survival, growth, or health.","zh":"importance of food 指食物在存活、生長或健康中的關鍵作用。"},{"en":"A school lunch programme shows the importance of food for students’ concentration.","zh":"學校午餐計劃顯示食物對學生專注力的重要性。"},{"en":"If chicks cannot get enough fish, they may starve before fledging.","zh":"如果幼鳥得不到足夠魚類，牠們可能在離巢前餓死。"},{"en":"The phrase explains why diet is central to survival.","zh":"這個短語解釋為何飲食對存活很核心。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":15},{"front":"successful results","meaning":"成功成果","examples":[{"en":"Research produced successful results for bittern conservation.","zh":"研究為麻鳽保育產生成功成果。"},{"en":"Successful results are positive outcomes that show an action or plan has worked.","zh":"successful results 指顯示某行動或計劃有效的正面結果。"},{"en":"A new reading programme has successful results if students read faster and understand more.","zh":"如果學生讀得更快、理解更多，新閱讀計劃就有成功成果。"},{"en":"In conservation, successful results may include more breeding birds and healthier habitat.","zh":"在保育中，成功成果可能包括更多繁殖鳥類和更健康棲息地。"},{"en":"The phrase describes evidence of improvement.","zh":"這個短語描述改善的證據。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":15},{"front":"reed-bed habitat","meaning":"蘆葦地棲息地","examples":[{"en":"The research investigated reed-bed habitat.","zh":"研究調查了蘆葦地棲息地。"},{"en":"Reed-bed habitat is wetland habitat dominated by reeds and used by species such as bitterns.","zh":"reed-bed habitat 指以蘆葦為主、被麻鳽等物種使用的濕地棲息地。"},{"en":"Reed-bed habitat can provide cover, nesting places, and feeding edges for birds.","zh":"蘆葦地棲息地可以為鳥類提供遮蔽、築巢地點和覓食邊緣。"},{"en":"If reed beds dry out or disappear, species that depend on them may decline.","zh":"如果蘆葦地乾涸或消失，依賴它們的物種可能下降。"},{"en":"The phrase describes a specific type of wetland environment.","zh":"這個短語描述特定類型的濕地環境。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":15},{"front":"wintering bitterns","meaning":"越冬麻鳽","examples":[{"en":"The reserve now supports wintering bitterns.","zh":"該保護區現在支持越冬麻鳽。"},{"en":"Wintering bitterns are bitterns that spend the winter at a particular site.","zh":"wintering bitterns 指在某特定地點過冬的麻鳽。"},{"en":"A wetland may support wintering birds if it offers food and shelter during cold months.","zh":"如果濕地在寒冷月份提供食物和遮蔽，它可能支持越冬鳥類。"},{"en":"Wintering bitterns show that a site is useful outside the breeding season.","zh":"越冬麻鳽顯示某地在繁殖季以外也有用。"},{"en":"The phrase refers to seasonal winter presence.","zh":"這個短語指季節性的冬季出現。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":15},{"front":"answer the questions below","meaning":"回答以下問題","examples":[{"en":"Students answer the questions below using words from the passage.","zh":"學生使用文章中的字詞回答以下問題。"},{"en":"Answer the questions below means respond to the listed questions that follow the instruction.","zh":"answer the questions below 指回答指示下方列出的問題。"},{"en":"In a reading exam, students should answer the questions below only after locating evidence in the text.","zh":"在閱讀考試中，學生應先在文本中定位證據，再回答以下問題。"},{"en":"This instruction tells candidates what task to complete next.","zh":"這個指示告訴考生接下來要完成甚麼任務。"},{"en":"The phrase is a standard exam direction.","zh":"這個短語是標準考試指示。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":15},{"front":"no more than three words and/or a number","meaning":"不多於三個字及／或一個數字","examples":[{"en":"Students should use no more than three words and/or a number.","zh":"學生應使用不多於三個字及／或一個數字。"},{"en":"No more than three words and/or a number means the answer can include up to three words plus a number if needed.","zh":"no more than three words and/or a number 指答案可包含最多三個詞，並可按需要加上一個數字。"},{"en":"If the answer is “55 males,” it fits because it uses a number and one word.","zh":"如果答案是 “55 males”，它符合要求，因為使用一個數字和一個詞。"},{"en":"Students lose marks if they write too many words even when the information is correct.","zh":"即使資料正確，學生寫太多詞也會失分。"},{"en":"The phrase sets a strict answer-length rule.","zh":"這個短語設定嚴格答案長度規則。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":15},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must come from the passage.","zh":"答案必須來自文章。"},{"en":"From the passage means using words or information found in the reading text.","zh":"from the passage 指使用閱讀文本中的字詞或資料。"},{"en":"Students should not use outside knowledge if the answer must come from the passage.","zh":"如果答案必須來自文章，學生不應使用外部知識。"},{"en":"This instruction keeps answers tied to evidence in the text.","zh":"這個指示讓答案緊扣文本證據。"},{"en":"The phrase tells learners where the answer source must be.","zh":"這個短語告訴學習者答案來源必須在哪裏。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":16},{"front":"reach its peak","meaning":"達到高峰","examples":[{"en":"The question asks when the number of breeding bitterns reached its peak.","zh":"題目問繁殖麻鳽數量何時達到高峰。"},{"en":"To reach its peak means to arrive at the highest point or maximum level.","zh":"reach its peak 指到達最高點或最大水平。"},{"en":"A school club may reach its peak membership before graduation season.","zh":"學校學會可能在畢業季前達到會員數高峰。"},{"en":"After a population reaches its peak, later decline can signal a new problem.","zh":"人口達到高峰後，如果之後下降，可能代表新問題出現。"},{"en":"The phrase describes the highest stage of a trend.","zh":"這個短語描述趨勢中的最高階段。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":16},{"front":"be described","meaning":"被描述","examples":[{"en":"The question asks how the bittern’s nature is described.","zh":"題目問麻鳽的習性如何被描述。"},{"en":"To be described means to be presented or explained in words.","zh":"be described 指用文字呈現或解釋。"},{"en":"A student may be described as hardworking if she revises every day.","zh":"如果學生每天溫習，她可能被描述為勤力。"},{"en":"How something is described can reveal the key feature the writer wants readers to notice.","zh":"某事如何被描述可以揭示作者希望讀者注意的關鍵特徵。"},{"en":"The phrase focuses on wording used in the text.","zh":"這個短語重點是文本中使用的措辭。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":16},{"front":"main cause of death","meaning":"主要死因","examples":[{"en":"The question asks for the main cause of death among bittern chicks.","zh":"題目問麻鳽幼鳥的主要死因。"},{"en":"The main cause of death is the most important or most common reason why individuals die.","zh":"main cause of death 指個體死亡最重要或最常見的原因。"},{"en":"In a hospital report, infection may be listed as the main cause of death for a group of patients.","zh":"在醫院報告中，感染可能被列為某組病人的主要死因。"},{"en":"Finding the main cause of death helps conservationists decide what problem to fix first.","zh":"找出主要死因幫助保育人士決定先解決哪個問題。"},{"en":"The phrase asks for the leading reason, not every possible reason.","zh":"這個短語詢問首要原因，而不是所有可能原因。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":16},{"front":"main food","meaning":"主要食物","examples":[{"en":"The question asks for the main food of bittern chicks.","zh":"題目問麻鳽幼鳥的主要食物。"},{"en":"Main food means the food type eaten most often or relied on most.","zh":"main food 指最常吃或最依賴的食物類型。"},{"en":"Rice may be the main food for some families because they eat it almost every day.","zh":"米飯可能是一些家庭的主要食物，因為他們幾乎每天吃。"},{"en":"If fish are the main food for chicks, healthy fish populations become essential.","zh":"如果魚是幼鳥的主要食物，健康魚類種群就變得必要。"},{"en":"The phrase asks what an animal mainly eats.","zh":"這個短語詢問動物主要吃甚麼。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":16},{"front":"stable bittern population","meaning":"穩定麻鳽種群","examples":[{"en":"The project aims to secure a stable bittern population.","zh":"該項目旨在確保穩定麻鳽種群。"},{"en":"A stable bittern population is a bittern population that can remain steady and survive over time.","zh":"stable bittern population 指能隨時間保持穩定並存活的麻鳽種群。"},{"en":"A school has stable enrolment when student numbers do not rise or fall sharply each year.","zh":"如果學生人數每年不劇烈上升或下降，學校就有穩定收生。"},{"en":"A stable population needs enough breeding sites, food, and young birds surviving.","zh":"穩定種群需要足夠繁殖地、食物和存活幼鳥。"},{"en":"The phrase describes long-term security rather than one good year.","zh":"這個短語描述長期安全，而不是某一年表現好。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":16},{"front":"besides bitterns and rare vegetation","meaning":"除了麻鳽和稀有植被之外","examples":[{"en":"The question asks which mammals benefit besides bitterns and rare vegetation.","zh":"題目問除了麻鳽和稀有植被之外，哪些哺乳動物受益。"},{"en":"Besides bitterns and rare vegetation means in addition to bitterns and uncommon plant life.","zh":"besides bitterns and rare vegetation 指除麻鳽和少見植物生命之外。"},{"en":"A wetland project may help frogs and insects besides birds and plants.","zh":"濕地項目除了幫助鳥類和植物，也可能幫助青蛙和昆蟲。"},{"en":"Conservation work often benefits many species beyond the original target.","zh":"保育工作通常令原本目標以外的許多物種受益。"},{"en":"The phrase asks for extra beneficiaries, not the main focus alone.","zh":"這個短語詢問額外受益者，而不只是主要焦點。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":16},{"front":"main purpose of","meaning":"……的主要目的","examples":[{"en":"The question asks about the main purpose of the passage.","zh":"題目詢問文章的主要目的。"},{"en":"The main purpose of a text is the central reason why it was written.","zh":"main purpose of a text 指文本被寫出來的核心原因。"},{"en":"The main purpose of a school notice may be to tell parents about a timetable change.","zh":"學校通告的主要目的可能是告知家長時間表改動。"},{"en":"Identifying the main purpose helps readers avoid focusing only on small details.","zh":"找出主要目的幫助讀者避免只集中於小細節。"},{"en":"The phrase asks for the writer’s overall aim.","zh":"這個短語詢問作者整體目標。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":16},{"front":"main characteristics","meaning":"主要特徵","examples":[{"en":"One option refers to the main characteristics of the bittern.","zh":"一個選項提到麻鳽的主要特徵。"},{"en":"Main characteristics are the most important features that describe something.","zh":"main characteristics 指描述某事物的最重要特點。"},{"en":"The main characteristics of a good essay include clear structure, relevant examples, and accurate language.","zh":"好作文的主要特徵包括清晰結構、相關例子和準確語言。"},{"en":"Knowing a species’ main characteristics helps readers recognise it and understand its needs.","zh":"了解物種主要特徵幫助讀者辨認牠並理解其需要。"},{"en":"The phrase asks about key features, not minor details.","zh":"這個短語詢問關鍵特點，而不是小細節。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":16},{"front":"protect an endangered species","meaning":"保護瀕危物種","examples":[{"en":"The passage shows how cooperation can protect an endangered species.","zh":"文章顯示合作如何保護瀕危物種。"},{"en":"To protect an endangered species means to help a species at risk of extinction survive and recover.","zh":"protect an endangered species 指幫助有滅絕風險的物種存活和恢復。"},{"en":"A community may protect an endangered frog by keeping ponds clean and stopping pollution.","zh":"社區可能透過保持池塘清潔和阻止污染來保護瀕危青蛙。"},{"en":"Protecting endangered species often requires habitat work, research, funding, and public support.","zh":"保護瀕危物種通常需要棲息地工作、研究、資金和公眾支持。"},{"en":"The phrase describes conservation action for species in danger.","zh":"這個短語描述為危險物種進行的保育行動。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":16},{"front":"obtaining information about","meaning":"取得關於……的資料","examples":[{"en":"One option mentions the difficulty of obtaining information about habitat and diet.","zh":"一個選項提到取得關於棲息地和飲食資料的困難。"},{"en":"Obtaining information about something means getting facts or data about it.","zh":"obtaining information about something 指取得關於某事的事實或數據。"},{"en":"A teacher may have difficulty obtaining information about why a student keeps missing class.","zh":"老師可能難以取得關於學生為何不斷缺課的資料。"},{"en":"If animals are secretive, obtaining information about their feeding and nesting habits is difficult.","zh":"如果動物很隱蔽，取得關於牠們覓食和築巢習性的資料就很困難。"},{"en":"The phrase focuses on the process of collecting useful evidence.","zh":"這個短語重點是收集有用證據的過程。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":16},{"front":"save wetlands and reed beds","meaning":"拯救濕地和蘆葦地","examples":[{"en":"One option refers to saving wetlands and reed beds in the UK.","zh":"一個選項提到拯救英國的濕地和蘆葦地。"},{"en":"To save wetlands and reed beds means to protect or restore these habitats so they do not disappear or degrade.","zh":"save wetlands and reed beds 指保護或修復這些棲息地，使它們不會消失或退化。"},{"en":"Volunteers may help save a wetland by removing rubbish and planting native reeds.","zh":"義工可能透過清理垃圾和種植本地蘆葦來幫助拯救濕地。"},{"en":"Saving wetlands benefits birds, fish, insects, plants, and sometimes nearby communities.","zh":"拯救濕地有益於鳥類、魚類、昆蟲、植物，有時也有益於附近社區。"},{"en":"The phrase describes habitat conservation, not only protection of one species.","zh":"這個短語描述棲息地保育，而不只是保護單一物種。"}],"source":"42 - Saving the British Bitterns.pdf","sourcePage":17}],"ielts/reading/passage-2/Practice 43":[{"front":"corporate social responsibility","meaning":"企業社會責任","examples":[{"en":"Corporate social responsibility has become a priority for business leaders worldwide.","zh":"企業社會責任已成為全球商界領袖的優先事項。"},{"en":"Corporate social responsibility means a company’s effort to act responsibly toward society, employees, communities, and the environment.","zh":"企業社會責任是指公司努力對社會、員工、社區和環境負責。"},{"en":"A supermarket shows corporate social responsibility when it reduces food waste and donates safe surplus food to charities.","zh":"超市減少食物浪費並把安全剩餘食物捐給慈善機構，就是展示企業社會責任。"},{"en":"Strong corporate social responsibility can improve trust because customers see that a company cares about more than profit.","zh":"強而有力的企業社會責任可以改善信任，因為顧客看見公司關心的不只是利潤。"},{"en":"Corporate social responsibility is weakest when it is only a public-relations slogan and not part of real business decisions.","zh":"當企業社會責任只是公關口號，而不是實際商業決策的一部分時，它最薄弱。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":1},{"front":"broadly speaking","meaning":"概括而言","examples":[{"en":"Broadly speaking, proponents of CSR have used four arguments.","zh":"概括而言，企業社會責任的支持者使用了四個理據。"},{"en":"Broadly speaking means speaking in a general way without focusing on every small detail.","zh":"概括而言，是指以一般方式說明，而不集中於每個細節。"},{"en":"Broadly speaking, students improve when they practise regularly and receive clear feedback.","zh":"概括而言，學生在定期練習並得到清晰回饋時會進步。"},{"en":"This phrase helps introduce a general summary before giving specific points.","zh":"這個短語有助在給出具體重點前引入總結。"},{"en":"Broadly speaking is useful when the full situation is complex but the writer wants to show the main pattern.","zh":"當完整情況很複雜，但作者想展示主要模式時，概括而言很有用。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":1},{"front":"proponents of","meaning":"……的支持者","examples":[{"en":"Proponents of corporate social responsibility use several arguments.","zh":"企業社會責任的支持者使用幾個理據。"},{"en":"Proponents of something are people who support it and argue that it should be accepted or used.","zh":"某事的支持者，是支持它並主張它應被接受或使用的人。"},{"en":"Proponents of school uniforms say they reduce social pressure among students.","zh":"校服的支持者說校服能減少學生之間的社交壓力。"},{"en":"Proponents often present benefits, evidence, or moral reasons to persuade others.","zh":"支持者通常提出好處、證據或道德原因來說服別人。"},{"en":"This phrase refers to supporters, not opponents.","zh":"這個短語指支持者，而不是反對者。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":1},{"front":"make their case","meaning":"提出理據；證明自己的主張","examples":[{"en":"Proponents of CSR have used four arguments to make their case.","zh":"企業社會責任的支持者使用四個理據來證明自己的主張。"},{"en":"To make their case means to present reasons and evidence to support their argument.","zh":"提出理據，是指提出原因和證據來支持自己的論點。"},{"en":"A student can make their case in an essay by giving examples, explanations, and counterarguments.","zh":"學生可以在文章中透過例子、解釋和反駁來證明自己的主張。"},{"en":"People make their case more convincingly when they connect claims with clear evidence.","zh":"當人們把主張與清楚證據連接起來，他們的理據會更有說服力。"},{"en":"This phrase describes arguing for a position in a structured way.","zh":"這個短語描述以有結構方式支持某立場。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":1},{"front":"moral obligation","meaning":"道德責任","examples":[{"en":"Moral obligation is one argument used to support CSR.","zh":"道德責任是用來支持企業社會責任的一個理據。"},{"en":"Moral obligation means a duty to do what is right because it is ethically necessary.","zh":"道德責任是因倫理上必要而有責任做正確的事。"},{"en":"A school has a moral obligation to protect students from bullying.","zh":"學校有道德責任保護學生免受欺凌。"},{"en":"Companies may feel a moral obligation to reduce harm when their activities affect local communities.","zh":"當公司活動影響本地社區時，公司可能有道德責任減少傷害。"},{"en":"This phrase focuses on right and wrong, not only law or profit.","zh":"這個短語聚焦是非對錯，而不只是法律或利潤。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":1},{"front":"sustainability","meaning":"可持續性","examples":[{"en":"Sustainability emphasises environmental and community stewardship.","zh":"可持續性強調環境及社區管理責任。"},{"en":"Sustainability means meeting present needs without damaging the ability of future people to meet theirs.","zh":"可持續性是指滿足當前需要，同時不損害未來人們滿足其需要的能力。"},{"en":"A family practises sustainability when it saves electricity, reduces waste, and avoids buying more than it needs.","zh":"家庭節省電力、減少浪費並避免購買超過需要的東西，就是實踐可持續性。"},{"en":"Businesses pursue sustainability because careless resource use can harm communities and future operations.","zh":"企業追求可持續性，因為粗心使用資源會傷害社區和未來營運。"},{"en":"Sustainability is about long-term balance, not short-term convenience alone.","zh":"可持續性關乎長期平衡，而不只是短期方便。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":1},{"front":"licence to operate","meaning":"營運許可","examples":[{"en":"The notion of a licence to operate arises from the need for permission.","zh":"營運許可的概念源自對許可的需要。"},{"en":"A licence to operate is the acceptance or permission a company needs from society, regulators, and stakeholders to keep doing business.","zh":"營運許可是公司需要從社會、監管者和持份者獲得的接受或許可，以繼續經營。"},{"en":"A factory may lose its licence to operate socially if local residents no longer trust it after repeated pollution.","zh":"如果工廠反覆污染後本地居民不再信任它，它可能失去社會層面的營運許可。"},{"en":"Companies protect their licence to operate by listening to communities and meeting legal standards.","zh":"公司透過聆聽社區並符合法律標準來保護其營運許可。"},{"en":"This phrase refers not only to formal law, but also to public approval.","zh":"這個短語不只指正式法律，也指公眾認可。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":1},{"front":"reputation","meaning":"聲譽","examples":[{"en":"Reputation provides a separate justification for CSR initiatives.","zh":"聲譽為企業社會責任措施提供另一項理據。"},{"en":"Reputation is the general opinion people have about a person, company, or organisation.","zh":"聲譽是人們對個人、公司或組織的一般看法。"},{"en":"A restaurant with a reputation for cleanliness attracts customers more easily.","zh":"以乾淨聞名的餐廳較容易吸引顧客。"},{"en":"A company’s reputation can be damaged quickly if it treats workers unfairly.","zh":"如果公司不公平對待員工，其聲譽可以很快受損。"},{"en":"This word refers to how others judge trustworthiness, quality, and character.","zh":"這個詞指別人如何判斷可信度、質素和品格。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":1},{"front":"have a duty to","meaning":"有責任去……","examples":[{"en":"Companies have a duty to be good citizens.","zh":"公司有責任成為良好公民。"},{"en":"To have a duty to do something means to have a responsibility or obligation to do it.","zh":"有責任做某事，是指有責任或義務去做它。"},{"en":"Parents have a duty to keep young children safe.","zh":"父母有責任保護年幼孩子安全。"},{"en":"Businesses have a duty to follow safety rules because their decisions affect workers and customers.","zh":"企業有責任遵守安全規則，因為其決定會影響員工和顧客。"},{"en":"This phrase suggests responsibility that should not be ignored.","zh":"這個短語暗示不應被忽視的責任。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":1},{"front":"good citizens","meaning":"良好公民","examples":[{"en":"The moral argument says companies should be good citizens.","zh":"道德論點認為公司應該成為良好公民。"},{"en":"Good citizens are people or organisations that act responsibly and contribute positively to society.","zh":"良好公民是負責任行事並為社會作出正面貢獻的人或組織。"},{"en":"A good citizen follows the law, respects neighbours, and helps keep the community safe.","zh":"良好公民會守法、尊重鄰居並幫助維持社區安全。"},{"en":"Companies act like good citizens when they pay fair wages and reduce unnecessary harm.","zh":"公司支付公平工資並減少不必要傷害時，就像良好公民一樣行事。"},{"en":"This phrase applies civic responsibility to businesses, not only individuals.","zh":"這個短語把公民責任應用於企業，而不只是個人。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":1},{"front":"do the right thing","meaning":"做正確的事","examples":[{"en":"Companies are expected to do the right thing.","zh":"公司被期望做正確的事。"},{"en":"To do the right thing means to act ethically, fairly, or responsibly.","zh":"做正確的事，是指以合乎道德、公平或負責任的方式行動。"},{"en":"A student does the right thing when they return a lost wallet to the school office.","zh":"學生把遺失的錢包交回校務處，就是做正確的事。"},{"en":"A company may lose trust if it chooses profit instead of doing the right thing.","zh":"如果公司選擇利潤而不是做正確的事，就可能失去信任。"},{"en":"This phrase is simple, but it carries a strong moral meaning.","zh":"這個短語很簡單，但帶有強烈道德含義。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":1},{"front":"be prominent in","meaning":"在……中突出","examples":[{"en":"The moral argument is prominent in the mission of Business for Social Responsibility.","zh":"道德論點在 Business for Social Responsibility 的使命中很突出。"},{"en":"To be prominent in something means to be clearly important or noticeable within it.","zh":"在某事中突出，是指在其中明顯重要或容易注意到。"},{"en":"Student welfare is prominent in the school’s new development plan.","zh":"學生福祉在學校的新發展計劃中很突出。"},{"en":"When an idea is prominent in a mission statement, it shapes the organisation’s identity.","zh":"當一個理念在使命宣言中突出，它會塑造組織身份。"},{"en":"This phrase describes something that stands out as important.","zh":"這個短語描述某事作為重要內容而突出。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":2},{"front":"mission of","meaning":"……的使命","examples":[{"en":"The moral argument is part of the mission of Business for Social Responsibility.","zh":"道德論點是 Business for Social Responsibility 使命的一部分。"},{"en":"The mission of an organisation is its main purpose or reason for existing.","zh":"一個組織的使命是其主要目的或存在理由。"},{"en":"The mission of a hospital is to protect health and provide care to patients.","zh":"醫院的使命是保護健康並為病人提供照護。"},{"en":"A clear mission helps employees decide what choices fit the organisation’s values.","zh":"清晰使命幫助員工判斷哪些選擇符合組織價值。"},{"en":"This phrase points to the guiding purpose behind an organisation.","zh":"這個短語指出組織背後的指導目的。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":2},{"front":"Business for Social Responsibility","meaning":"商業社會責任組織","examples":[{"en":"Business for Social Responsibility is a leading non-profit CSR business association.","zh":"Business for Social Responsibility 是一個主要非牟利企業社會責任商業協會。"},{"en":"Business for Social Responsibility is an organisation that promotes responsible business practices.","zh":"Business for Social Responsibility 是推動負責任商業做法的組織。"},{"en":"A company may join Business for Social Responsibility to learn how to improve labour and environmental standards.","zh":"公司可能加入 Business for Social Responsibility，以學習如何改善勞工和環境標準。"},{"en":"Organisations like this help businesses turn broad CSR ideas into practical policies.","zh":"這類組織幫助企業把廣泛企業社會責任理念轉化成實際政策。"},{"en":"This phrase names a specific association connected with CSR.","zh":"這個短語命名一個與企業社會責任相關的特定協會。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":2},{"front":"leading non-profit association","meaning":"主要非牟利協會","examples":[{"en":"Business for Social Responsibility is a leading non-profit business association.","zh":"Business for Social Responsibility 是一個主要非牟利商業協會。"},{"en":"A leading non-profit association is an important organisation that does not mainly exist to make profit.","zh":"主要非牟利協會，是一個重要且主要目的不是賺取利潤的組織。"},{"en":"A leading non-profit association may provide training, research, and guidance to schools or companies.","zh":"主要非牟利協會可能為學校或公司提供培訓、研究和指引。"},{"en":"Because it is non-profit, its mission is usually social or professional rather than commercial ownership gain.","zh":"因為它是非牟利，其使命通常是社會或專業目的，而不是商業擁有人收益。"},{"en":"This phrase combines importance with a non-profit purpose.","zh":"這個短語結合重要性與非牟利目的。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":2},{"front":"achieve commercial success","meaning":"取得商業成功","examples":[{"en":"Members are asked to achieve commercial success ethically.","zh":"成員被要求以合乎道德方式取得商業成功。"},{"en":"To achieve commercial success means to perform well financially in the market.","zh":"取得商業成功，是指在市場上有良好財務表現。"},{"en":"A small bakery can achieve commercial success by selling good products and treating customers well.","zh":"小型麵包店可以透過售賣好產品並善待顧客來取得商業成功。"},{"en":"Commercial success becomes more sustainable when it is built on trust, quality, and fair practice.","zh":"當商業成功建立在信任、質素和公平做法上，它會更可持續。"},{"en":"This phrase focuses on business success, not moral success alone.","zh":"這個短語聚焦商業上的成功，而不只是道德上的成功。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":2},{"front":"in ways that honour","meaning":"以尊重……的方式","examples":[{"en":"Companies should succeed in ways that honour ethical values.","zh":"公司應以尊重道德價值的方式取得成功。"},{"en":"In ways that honour something means using methods that respect and support it.","zh":"以尊重某事的方式，是指使用尊重並支持它的方法。"},{"en":"A school can raise money in ways that honour students’ dignity by avoiding public embarrassment.","zh":"學校可以用尊重學生尊嚴的方式籌款，例如避免公開令人尷尬。"},{"en":"Companies honour values when they refuse dishonest methods even if those methods bring quick profit.","zh":"公司拒絕不誠實方法時，就是在尊重價值，即使那些方法能帶來快速利潤。"},{"en":"This phrase connects success with respect for principles.","zh":"這個短語把成功與尊重原則連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":2},{"front":"ethical values","meaning":"道德價值","examples":[{"en":"CSR asks companies to honour ethical values.","zh":"企業社會責任要求公司尊重道德價值。"},{"en":"Ethical values are beliefs about what is right, fair, honest, and responsible.","zh":"道德價值是關於甚麼是正確、公平、誠實和負責任的信念。"},{"en":"A doctor’s ethical values include protecting patient privacy and giving safe care.","zh":"醫生的道德價值包括保護病人私隱和提供安全護理。"},{"en":"A company guided by ethical values will avoid cheating customers or exploiting workers.","zh":"受道德價值引導的公司會避免欺騙顧客或剝削員工。"},{"en":"This phrase refers to moral principles that guide behaviour.","zh":"這個短語指引導行為的道德原則。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":2},{"front":"respect people, communities, and the natural environment","meaning":"尊重人、社區和自然環境","examples":[{"en":"Companies should respect people, communities, and the natural environment.","zh":"公司應尊重人、社區和自然環境。"},{"en":"To respect people, communities, and the natural environment means to avoid harming them and to consider their needs.","zh":"尊重人、社區和自然環境，是指避免傷害它們並考慮其需要。"},{"en":"A construction company shows respect when it protects workers, consults residents, and reduces dust and waste.","zh":"建築公司保護工人、諮詢居民並減少塵埃和廢物時，就是展示尊重。"},{"en":"Respecting these groups can prevent conflict, pollution, and loss of trust.","zh":"尊重這些群體可以防止衝突、污染和失去信任。"},{"en":"This phrase summarises the human, social, and environmental sides of responsible business.","zh":"這個短語概括負責任企業的人文、社會和環境面向。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":2},{"front":"environmental and community stewardship","meaning":"環境及社區管理責任","examples":[{"en":"Sustainability emphasises environmental and community stewardship.","zh":"可持續性強調環境及社區管理責任。"},{"en":"Environmental and community stewardship means responsible care for nature and the people living in a community.","zh":"環境及社區管理責任，是指對自然和社區居民作出負責任照顧。"},{"en":"A factory practises stewardship when it reduces water pollution and supports local health programmes.","zh":"工廠減少水污染並支持本地健康計劃時，就是實踐管理責任。"},{"en":"Good stewardship protects resources because careless use can damage both business and society.","zh":"良好管理責任能保護資源，因為粗心使用會損害企業和社會。"},{"en":"This phrase suggests looking after shared places and people, not merely using them.","zh":"這個短語暗示照顧共同地方和人，而不只是使用它們。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":2},{"front":"definition of","meaning":"……的定義","examples":[{"en":"An excellent definition of sustainability was developed in the 1980s.","zh":"可持續性的一個出色定義在二十世紀八十年代被提出。"},{"en":"A definition of something is a clear explanation of what it means.","zh":"某事的定義，是對其意思的清楚解釋。"},{"en":"A teacher may ask students to write a definition of democracy before discussing elections.","zh":"老師可能在討論選舉前要求學生寫出民主的定義。"},{"en":"Good definitions help people use important terms in the same way.","zh":"好定義幫助人們以相同方式使用重要術語。"},{"en":"This phrase introduces the meaning of a concept.","zh":"這個短語引入一個概念的意思。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":2},{"front":"be developed by","meaning":"由……提出","examples":[{"en":"The definition of sustainability was developed by Gro Harlem Brundtland.","zh":"可持續性的定義由 Gro Harlem Brundtland 提出。"},{"en":"To be developed by someone means to be created, shaped, or improved by that person or group.","zh":"由某人提出或發展，是指由該人或群體創造、塑造或改善。"},{"en":"A new reading programme may be developed by teachers who understand students’ needs.","zh":"新閱讀計劃可能由了解學生需要的老師提出。"},{"en":"When an idea is developed by respected experts, people may take it more seriously.","zh":"當理念由受尊重的專家提出，人們可能更認真看待它。"},{"en":"This phrase identifies who created or shaped something.","zh":"這個短語指出誰創造或塑造某事。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":2},{"front":"Norwegian prime minister","meaning":"挪威首相","examples":[{"en":"Gro Harlem Brundtland was a Norwegian prime minister.","zh":"Gro Harlem Brundtland 曾是挪威首相。"},{"en":"A Norwegian prime minister is the head of government of Norway.","zh":"挪威首相是挪威政府首腦。"},{"en":"A prime minister may influence national policy on health, education, and the environment.","zh":"首相可能影響健康、教育和環境方面的國家政策。"},{"en":"When a former prime minister contributes to sustainability debates, political experience can shape the discussion.","zh":"當前首相參與可持續性討論時，政治經驗會塑造討論。"},{"en":"This phrase identifies a political role connected with Norway.","zh":"這個短語指出與挪威相關的政治角色。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":3},{"front":"World Business Council for Sustainable Development","meaning":"世界企業永續發展委員會","examples":[{"en":"The definition was used by the World Business Council for Sustainable Development.","zh":"該定義被世界企業永續發展委員會使用。"},{"en":"The World Business Council for Sustainable Development is an organisation connected with business action on sustainability.","zh":"世界企業永續發展委員會是一個與企業可持續行動相關的組織。"},{"en":"A company may use guidance from the World Business Council for Sustainable Development when setting environmental goals.","zh":"公司設定環境目標時，可能使用世界企業永續發展委員會的指引。"},{"en":"Such organisations help businesses translate sustainability ideas into practical standards.","zh":"這類組織幫助企業把可持續性理念轉化成實際標準。"},{"en":"This phrase names a global body linked to sustainable business.","zh":"這個短語命名一個與可持續企業相關的全球機構。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":3},{"front":"meet the needs of","meaning":"滿足……的需要","examples":[{"en":"Sustainability means meeting the needs of the present.","zh":"可持續性意味着滿足當代需要。"},{"en":"To meet the needs of someone means to provide what they require.","zh":"滿足某人的需要，是指提供他們所需的東西。"},{"en":"A school can meet the needs of new students by offering language support and clear guidance.","zh":"學校可以透過提供語言支援和清晰指引來滿足新學生需要。"},{"en":"Businesses meet customers’ needs when products solve real problems safely and fairly.","zh":"當產品安全且公平地解決真實問題，企業就滿足顧客需要。"},{"en":"This phrase focuses on satisfying real requirements, not just creating desire.","zh":"這個短語聚焦滿足真實需求，而不只是創造欲望。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":3},{"front":"the present","meaning":"當代；現在","examples":[{"en":"Sustainability considers the needs of the present.","zh":"可持續性考慮當代需要。"},{"en":"The present means the current time, not the past or future.","zh":"當代或現在，是指目前時間，而不是過去或未來。"},{"en":"A family budget must cover the present while still saving for later.","zh":"家庭預算必須照顧現在，同時仍為將來儲蓄。"},{"en":"If leaders think only about the present, they may ignore costs passed to future generations.","zh":"如果領袖只考慮現在，就可能忽視轉嫁給未來世代的成本。"},{"en":"This phrase is often used in contrast with the future.","zh":"這個短語常與未來作對比。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":3},{"front":"without compromising","meaning":"在不損害……的情況下","examples":[{"en":"Sustainability meets present needs without compromising future generations.","zh":"可持續性是在不損害未來世代的情況下滿足當前需要。"},{"en":"Without compromising something means without weakening, damaging, or giving it up.","zh":"在不損害某事的情況下，是指不削弱、破壞或放棄它。"},{"en":"A student can work part-time without compromising exam preparation if the hours are limited.","zh":"如果工時有限，學生可以兼職而不損害考試準備。"},{"en":"A company should grow without compromising worker safety or environmental quality.","zh":"公司應在不損害員工安全或環境質素的情況下成長。"},{"en":"This phrase shows that one goal should not be achieved by damaging another.","zh":"這個短語顯示一個目標不應靠破壞另一目標來達成。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":3},{"front":"ability of future generations","meaning":"未來世代的能力","examples":[{"en":"Sustainability protects the ability of future generations to meet their needs.","zh":"可持續性保護未來世代滿足其需要的能力。"},{"en":"The ability of future generations means the capacity of people in the future to live, work, and obtain what they need.","zh":"未來世代的能力，是指未來人們生活、工作和取得所需之物的能力。"},{"en":"Saving clean water protects the ability of future generations to farm, drink, and stay healthy.","zh":"保存清潔食水能保護未來世代耕作、飲水和保持健康的能力。"},{"en":"If today’s society uses resources carelessly, future generations may have fewer choices.","zh":"如果今日社會粗心使用資源，未來世代可能有較少選擇。"},{"en":"This phrase focuses on responsibility to people who are not yet born or grown.","zh":"這個短語聚焦對尚未出生或尚未成長的人所負的責任。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":3},{"front":"account for","meaning":"對……作出交代；考慮","examples":[{"en":"Governments and companies must account for the social consequences of their actions.","zh":"政府和公司必須對其行動的社會後果作出交代。"},{"en":"To account for something means to consider, explain, or take responsibility for it.","zh":"考慮或交代某事，是指把它納入考量、解釋它或為它負責。"},{"en":"A school timetable must account for students who need extra travel time.","zh":"學校時間表必須考慮需要額外交通時間的學生。"},{"en":"Companies account for social consequences when they measure pollution, labour conditions, and community effects.","zh":"當公司量度污染、勞工條件和社區影響時，就是考慮社會後果。"},{"en":"This phrase asks decision-makers not to ignore important results of their actions.","zh":"這個短語要求決策者不要忽視其行動的重要結果。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":3},{"front":"social consequences","meaning":"社會後果","examples":[{"en":"Companies must consider the social consequences of their actions.","zh":"公司必須考慮其行動的社會後果。"},{"en":"Social consequences are the effects that actions have on people, communities, and society.","zh":"社會後果是行動對人、社區和社會造成的影響。"},{"en":"Closing a factory may have social consequences such as job loss and family stress.","zh":"關閉工廠可能有失業和家庭壓力等社會後果。"},{"en":"Responsible leaders think about social consequences before making decisions that affect many people.","zh":"負責任的領袖在作出影響很多人的決定前，會思考社會後果。"},{"en":"This phrase focuses on human and community impact.","zh":"這個短語聚焦人和社區的影響。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":3},{"front":"become a priority for","meaning":"成為……的優先事項","examples":[{"en":"CSR has become a priority for business leaders worldwide.","zh":"企業社會責任已成為全球商界領袖的優先事項。"},{"en":"To become a priority for someone means to become one of the most important things they focus on.","zh":"成為某人的優先事項，是指成為他們最重要關注之一。"},{"en":"Mental health has become a priority for many schools after students reported high stress.","zh":"學生報告高壓力後，心理健康已成為許多學校的優先事項。"},{"en":"When something becomes a priority, leaders usually spend more time, money, and attention on it.","zh":"當某事成為優先事項，領袖通常會投入更多時間、金錢和注意力。"},{"en":"This phrase shows a change in importance.","zh":"這個短語顯示重要性的變化。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":3},{"front":"business leaders worldwide","meaning":"全球商界領袖","examples":[{"en":"CSR has become important to business leaders worldwide.","zh":"企業社會責任已對全球商界領袖變得重要。"},{"en":"Business leaders worldwide are senior people who guide companies across different countries and markets.","zh":"全球商界領袖，是在不同國家和市場中指導公司的高層人士。"},{"en":"Business leaders worldwide may discuss climate risk, supply chains, and worker welfare at global conferences.","zh":"全球商界領袖可能在全球會議上討論氣候風險、供應鏈和員工福祉。"},{"en":"When leaders across the world focus on the same issue, it becomes a major business trend.","zh":"當世界各地領袖都關注同一議題，它就成為主要商業趨勢。"},{"en":"This phrase suggests global importance, not just local concern.","zh":"這個短語暗示全球重要性，而不只是本地關注。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":3},{"front":"well-run business","meaning":"營運良好的企業","examples":[{"en":"A well-run business can have a greater social impact.","zh":"營運良好的企業可以有更大的社會影響。"},{"en":"A well-run business is a company managed efficiently, responsibly, and with clear goals.","zh":"營運良好的企業，是被有效率、負責任且有清晰目標地管理的公司。"},{"en":"A well-run café keeps good accounts, trains staff, and serves customers consistently.","zh":"營運良好的咖啡店會保持良好帳目、培訓員工並穩定服務顧客。"},{"en":"Well-run businesses can support society because they have stable resources and organised systems.","zh":"營運良好的企業能支持社會，因為它們有穩定資源和有組織系統。"},{"en":"This phrase refers to management quality, not just company size.","zh":"這個短語指管理質素，而不只是公司規模。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":3},{"front":"apply resources and expertise to","meaning":"把資源和專業知識應用於……","examples":[{"en":"A business can apply its resources and expertise to social problems.","zh":"企業可以把其資源和專業知識應用於社會問題。"},{"en":"To apply resources and expertise to something means to use money, skills, knowledge, and people to deal with it.","zh":"把資源和專業知識應用於某事，是指使用金錢、技能、知識和人手來處理它。"},{"en":"A technology company can apply resources and expertise to help schools build digital classrooms.","zh":"科技公司可以把資源和專業知識應用於幫助學校建立數碼課室。"},{"en":"When companies use what they already know well, their help can be more effective.","zh":"當公司使用自己本來擅長的東西，其幫助會更有效。"},{"en":"This phrase connects business strengths with problem-solving.","zh":"這個短語把企業強項與解決問題連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":4},{"front":"extensive resources","meaning":"豐富資源","examples":[{"en":"A company may apply its extensive resources to social problems.","zh":"公司可以把其豐富資源應用於社會問題。"},{"en":"Extensive resources are large amounts of money, people, equipment, knowledge, or networks.","zh":"豐富資源是大量金錢、人手、設備、知識或網絡。"},{"en":"A large hospital has extensive resources compared with a small clinic.","zh":"與小診所相比，大型醫院擁有豐富資源。"},{"en":"Organisations with extensive resources can respond faster to complex problems.","zh":"擁有豐富資源的組織能更快回應複雜問題。"},{"en":"This phrase emphasises the size and range of what is available.","zh":"這個短語強調可用資源的規模和範圍。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":4},{"front":"have a stake in","meaning":"在……有利害關係","examples":[{"en":"A business can help with social problems in which it has a stake.","zh":"企業可以幫助處理自己有利害關係的社會問題。"},{"en":"To have a stake in something means to be affected by it or have an interest in its outcome.","zh":"在某事有利害關係，是指會受其影響，或對其結果有利益關注。"},{"en":"Parents have a stake in school policy because it affects their children’s daily lives.","zh":"家長在學校政策上有利害關係，因為它影響孩子日常生活。"},{"en":"A company has a stake in local education if it needs skilled workers from the community.","zh":"如果公司需要來自社區的熟練工人，它就在本地教育上有利害關係。"},{"en":"This phrase shows that the issue matters directly to someone.","zh":"這個短語顯示某議題對某人有直接重要性。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":4},{"front":"greater impact than","meaning":"比……有更大影響","examples":[{"en":"A company may have a greater impact than any other organisation.","zh":"公司可能比任何其他組織有更大影響。"},{"en":"Greater impact than means a stronger effect compared with someone or something else.","zh":"比某事有更大影響，是指與其他人或事相比有更強效果。"},{"en":"A clear school policy may have a greater impact than a one-day lecture.","zh":"清晰學校政策可能比一天講座有更大影響。"},{"en":"A company with money, staff, and expertise can sometimes create greater impact than a small charity.","zh":"擁有金錢、人手和專業知識的公司，有時能比小型慈善機構創造更大影響。"},{"en":"This phrase compares the size or strength of effects.","zh":"這個短語比較影響的大小或強度。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":4},{"front":"notion of","meaning":"……的概念","examples":[{"en":"The notion of a licence to operate arises from stakeholder permission.","zh":"營運許可的概念源自持份者許可。"},{"en":"The notion of something is the idea or concept of it.","zh":"某事的概念，是指它的想法或觀念。"},{"en":"The notion of lifelong learning means people continue learning beyond school.","zh":"終身學習的概念，是指人們在離開學校後仍繼續學習。"},{"en":"A notion becomes useful when it helps people understand a complicated situation.","zh":"當一個概念幫助人們理解複雜情況時，它就變得有用。"},{"en":"This phrase introduces an abstract idea.","zh":"這個短語引入抽象想法。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":4},{"front":"arise because","meaning":"因……而產生","examples":[{"en":"The notion arises because every company needs permission to operate.","zh":"這個概念因每間公司都需要營運許可而產生。"},{"en":"Arise because means happen or develop as a result of a reason.","zh":"因某原因而產生，是指因某個原因而發生或發展。"},{"en":"Conflict may arise because team members do not understand their roles.","zh":"衝突可能因團隊成員不了解自己的角色而產生。"},{"en":"Business problems can arise because companies ignore the people affected by their decisions.","zh":"當公司忽視受其決定影響的人，商業問題就可能產生。"},{"en":"This phrase connects the origin of something with its cause.","zh":"這個短語把某事的起源與原因連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":4},{"front":"tacit or explicit permission","meaning":"默許或明確許可","examples":[{"en":"Companies need tacit or explicit permission from stakeholders.","zh":"公司需要持份者的默許或明確許可。"},{"en":"Tacit or explicit permission means approval that is either unspoken and implied, or clearly stated.","zh":"默許或明確許可，是指不說出口但被暗示的批准，或清楚說明的批准。"},{"en":"A teacher may have tacit permission to rearrange desks if no one objects, but explicit permission is written approval.","zh":"如果沒有人反對，老師可能有默許去重新安排桌椅，但明確許可是書面批准。"},{"en":"Companies need permission because communities, governments, and customers can limit their operations.","zh":"公司需要許可，因為社區、政府和顧客可以限制其營運。"},{"en":"This phrase contrasts silent acceptance with formal approval.","zh":"這個短語對比沉默接受與正式批准。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":4},{"front":"numerous other stakeholders","meaning":"眾多其他持份者","examples":[{"en":"Companies need support from governments, communities and numerous other stakeholders.","zh":"公司需要政府、社區和眾多其他持份者的支持。"},{"en":"Numerous other stakeholders are many additional people or groups affected by or interested in a company’s actions.","zh":"眾多其他持份者，是許多受公司行動影響或對其有興趣的人或群體。"},{"en":"A new shopping centre may concern numerous stakeholders, including residents, shop owners, drivers, and workers.","zh":"新購物中心可能涉及眾多持份者，包括居民、店主、司機和工人。"},{"en":"Companies must listen to stakeholders because ignoring them can create opposition and delay.","zh":"公司必須聆聽持份者，因為忽視他們會造成反對和延誤。"},{"en":"This phrase stresses that business decisions affect many groups.","zh":"這個短語強調商業決策會影響很多群體。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":4},{"front":"separate justification","meaning":"另一項理據","examples":[{"en":"Reputation provides a separate justification for CSR initiatives.","zh":"聲譽為企業社會責任措施提供另一項理據。"},{"en":"A separate justification is an additional reason that supports an action independently.","zh":"另一項理據，是獨立支持某行動的額外原因。"},{"en":"A school may have one reason to reduce homework for health and a separate justification for improving family time.","zh":"學校減少功課可能有健康原因，也有改善家庭時間的另一項理據。"},{"en":"Separate justifications can make an argument stronger because it does not depend on only one point.","zh":"多項理據可以令論點更強，因為它不只依靠一點。"},{"en":"This phrase means another supporting reason, not a repeated one.","zh":"這個短語表示另一個支持理由，而不是重複理由。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":4},{"front":"CSR initiatives","meaning":"企業社會責任措施","examples":[{"en":"CSR initiatives can improve a company’s image.","zh":"企業社會責任措施可以改善公司形象。"},{"en":"CSR initiatives are specific actions or programmes a company uses to act responsibly toward society.","zh":"企業社會責任措施，是公司用來對社會負責的具體行動或計劃。"},{"en":"A company may launch CSR initiatives such as recycling schemes, scholarship funds, or worker-safety training.","zh":"公司可能推出回收計劃、獎學金基金或員工安全培訓等企業社會責任措施。"},{"en":"CSR initiatives work best when they solve real problems rather than simply advertise goodness.","zh":"當企業社會責任措施解決真實問題，而不只是宣傳善意時，效果最好。"},{"en":"This phrase refers to practical CSR actions, not just general beliefs.","zh":"這個短語指實際企業社會責任行動，而不只是一般信念。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":4},{"front":"improve a company’s image","meaning":"改善公司形象","examples":[{"en":"CSR initiatives can improve a company’s image.","zh":"企業社會責任措施可以改善公司形象。"},{"en":"To improve a company’s image means to make the public view the company more positively.","zh":"改善公司形象，是指令公眾對公司有更正面的看法。"},{"en":"A transport company may improve its image by apologising for delays and offering better service.","zh":"交通公司可以透過為延誤道歉並提供更好服務來改善形象。"},{"en":"A better image can attract customers, employees, and investors.","zh":"更好形象可以吸引顧客、員工和投資者。"},{"en":"This phrase concerns public perception, not necessarily real performance alone.","zh":"這個短語關乎公眾觀感，而不一定只是實際表現。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":4},{"front":"strengthen its brand","meaning":"強化品牌","examples":[{"en":"CSR can strengthen a company’s brand.","zh":"企業社會責任可以強化公司品牌。"},{"en":"To strengthen a brand means to make people recognise, trust, and value it more.","zh":"強化品牌，是指令人們更認識、信任並重視該品牌。"},{"en":"A café can strengthen its brand by consistently serving good coffee and treating staff well.","zh":"咖啡店可以透過穩定提供好咖啡並善待員工來強化品牌。"},{"en":"Strong brands are easier to remember and can keep customers loyal.","zh":"強大品牌較容易被記住，並能令顧客保持忠誠。"},{"en":"This phrase connects reputation with business identity.","zh":"這個短語把聲譽與商業身份連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":5},{"front":"boost morale","meaning":"提升士氣","examples":[{"en":"CSR initiatives can boost morale among employees.","zh":"企業社會責任措施可以提升員工士氣。"},{"en":"To boost morale means to raise people’s confidence, motivation, and positive feeling.","zh":"提升士氣，是指提高人們的信心、動力和正面情緒。"},{"en":"A manager can boost morale by thanking staff after a difficult project.","zh":"經理可以在困難項目後感謝員工來提升士氣。"},{"en":"Employees may feel more motivated when they believe their company contributes to society.","zh":"當員工相信公司為社會作出貢獻，他們可能更有動力。"},{"en":"This phrase describes improving emotional energy in a group.","zh":"這個短語描述改善群體中的情緒能量。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":5},{"front":"raise the value of","meaning":"提高……的價值","examples":[{"en":"CSR initiatives may raise the value of a company’s shares.","zh":"企業社會責任措施可能提高公司股票價值。"},{"en":"To raise the value of something means to increase how much it is worth.","zh":"提高某物的價值，是指增加它值多少。"},{"en":"Renovating a flat can raise the value of the property before it is sold.","zh":"出售單位前翻新可以提高物業價值。"},{"en":"A company’s share value may rise if investors believe it is trusted and well managed.","zh":"如果投資者相信公司受信任且管理良好，其股價可能上升。"},{"en":"This phrase describes an increase in worth or market price.","zh":"這個短語描述價值或市場價格上升。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":5},{"front":"advance CSR","meaning":"推動企業社會責任","examples":[{"en":"To advance CSR, we need to understand business and society together.","zh":"要推動企業社會責任，我們需要一併理解企業和社會。"},{"en":"To advance CSR means to improve, develop, or promote corporate social responsibility.","zh":"推動企業社會責任，是指改善、發展或促進企業社會責任。"},{"en":"A university can advance CSR by teaching future managers how business decisions affect communities.","zh":"大學可以透過教未來管理者理解商業決策如何影響社區來推動企業社會責任。"},{"en":"CSR advances when companies connect social benefit with real business practice.","zh":"當公司把社會利益與真實商業做法連接起來，企業社會責任就會進步。"},{"en":"This phrase focuses on moving CSR from idea to stronger action.","zh":"這個短語聚焦把企業社會責任由理念推向更強行動。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":5},{"front":"root something in","meaning":"把……植根於","examples":[{"en":"CSR must be rooted in an understanding of the corporation and society.","zh":"企業社會責任必須植根於對企業和社會的理解。"},{"en":"To root something in an idea means to base it firmly on that idea.","zh":"把某事植根於某理念，是指把它牢固建立在該理念上。"},{"en":"A school policy should be rooted in students’ real needs, not just tradition.","zh":"學校政策應植根於學生真實需要，而不只是傳統。"},{"en":"CSR rooted in business reality is more likely to last than CSR based only on publicity.","zh":"植根於商業現實的企業社會責任，比只基於宣傳的企業社會責任更可能持久。"},{"en":"This phrase shows the foundation behind an action or belief.","zh":"這個短語顯示行動或信念背後的基礎。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":5},{"front":"broad understanding of","meaning":"對……的廣泛理解","examples":[{"en":"CSR requires a broad understanding of the relationship between business and society.","zh":"企業社會責任需要對企業與社會之間關係的廣泛理解。"},{"en":"A broad understanding of something means a wide and balanced knowledge of its different parts.","zh":"對某事的廣泛理解，是指對其不同部分有寬廣而平衡的認識。"},{"en":"Teachers need a broad understanding of students’ lives before judging performance.","zh":"老師在判斷學生表現前，需要對學生生活有廣泛理解。"},{"en":"Broad understanding helps leaders avoid narrow decisions that solve one problem but create another.","zh":"廣泛理解幫助領袖避免作出只解決一個問題卻製造另一個問題的狹隘決定。"},{"en":"This phrase suggests seeing the whole picture.","zh":"這個短語暗示看見全局。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":5},{"front":"interrelationship between","meaning":"……之間的相互關係","examples":[{"en":"The passage discusses the interrelationship between a corporation and society.","zh":"篇章討論企業與社會之間的相互關係。"},{"en":"The interrelationship between two things is the way they influence and depend on each other.","zh":"兩者之間的相互關係，是指它們如何互相影響和依賴。"},{"en":"The interrelationship between sleep and learning means poor sleep can reduce memory, while better learning habits can improve sleep routines.","zh":"睡眠與學習之間的相互關係，是指睡眠差會降低記憶，而較好學習習慣也能改善睡眠規律。"},{"en":"Business and society affect each other because companies need healthy communities and communities need jobs.","zh":"企業和社會互相影響，因為公司需要健康社區，而社區需要工作。"},{"en":"This phrase focuses on two-way connection, not one-way influence.","zh":"這個短語聚焦雙向連繫，而不是單向影響。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":5},{"front":"healthy society","meaning":"健康社會","examples":[{"en":"Successful corporations need a healthy society.","zh":"成功企業需要健康社會。"},{"en":"A healthy society is a society with educated people, safe communities, fair rules, and basic services.","zh":"健康社會是有受教育人民、安全社區、公平規則和基本服務的社會。"},{"en":"A healthy society supports businesses because workers can learn, travel, and live safely.","zh":"健康社會支持企業，因為員工可以學習、出行和安全生活。"},{"en":"If society becomes unstable, companies may lose customers, staff, and trust.","zh":"如果社會變得不穩定，公司可能失去顧客、員工和信任。"},{"en":"This phrase means social health in a broad sense, not only medical health.","zh":"這個短語指廣義上的社會健康，而不只是醫療健康。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":5},{"front":"productive workforce","meaning":"有生產力的勞動力","examples":[{"en":"Education and health care are essential to a productive workforce.","zh":"教育和醫療保健對有生產力的勞動力不可或缺。"},{"en":"A productive workforce is a group of workers who can work effectively, safely, and efficiently.","zh":"有生產力的勞動力，是能有效、安全且高效工作的工人群體。"},{"en":"A company benefits from a productive workforce when staff are trained, healthy, and motivated.","zh":"當員工受過培訓、健康且有動力，公司就能受益於有生產力的勞動力。"},{"en":"Poor education or poor health can reduce productivity because workers cannot perform at their best.","zh":"教育不足或健康欠佳會降低生產力，因為工人無法發揮最佳表現。"},{"en":"This phrase connects worker ability with economic output.","zh":"這個短語把工人能力與經濟產出連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":5},{"front":"equal opportunity","meaning":"平等機會","examples":[{"en":"Equal opportunity is essential to a productive workforce.","zh":"平等機會對有生產力的勞動力不可或缺。"},{"en":"Equal opportunity means giving people fair chances regardless of background, gender, race, or social status.","zh":"平等機會是指不論背景、性別、種族或社會地位，都給予人公平機會。"},{"en":"A school supports equal opportunity when poor students can access the same learning resources as rich students.","zh":"當貧困學生能取得與富裕學生相同的學習資源，學校就是支持平等機會。"},{"en":"Equal opportunity helps businesses find talent that might otherwise be overlooked.","zh":"平等機會幫助企業發現原本可能被忽略的人才。"},{"en":"This phrase focuses on fair access, not identical outcomes.","zh":"這個短語聚焦公平取得機會，而不是完全相同結果。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":5},{"front":"safe products","meaning":"安全產品","examples":[{"en":"Safe products attract customers and reduce costs.","zh":"安全產品吸引顧客並降低成本。"},{"en":"Safe products are goods that do not create unreasonable danger when used properly.","zh":"安全產品是正確使用時不會造成不合理危險的商品。"},{"en":"A toy company must make safe products so children do not choke on small parts.","zh":"玩具公司必須製造安全產品，令孩子不會被細小零件噎住。"},{"en":"Unsafe products can cause injuries, complaints, recalls, and legal costs.","zh":"不安全產品會造成受傷、投訴、回收和法律成本。"},{"en":"This phrase connects product quality with customer protection.","zh":"這個短語把產品質素與顧客保護連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":5},{"front":"working conditions","meaning":"工作環境","examples":[{"en":"Safe working conditions lower the internal costs of accidents.","zh":"安全工作環境降低事故的內部成本。"},{"en":"Working conditions are the environment, rules, hours, pay, and safety standards workers experience.","zh":"工作環境是工人經歷的環境、規則、工時、薪酬和安全標準。"},{"en":"A clean kitchen with proper equipment creates better working conditions for restaurant staff.","zh":"乾淨廚房和合適設備能為餐廳員工創造更好工作環境。"},{"en":"Poor working conditions can lead to injuries, low morale, and high staff turnover.","zh":"差劣工作環境會導致受傷、士氣低落和高員工流失率。"},{"en":"This phrase describes what daily work is physically and socially like.","zh":"這個短語描述日常工作在實體和社會層面是怎樣的。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":6},{"front":"not only…but…","meaning":"不但……而且……","examples":[{"en":"Safe products not only attract customers but lower internal costs.","zh":"安全產品不但吸引顧客，而且降低內部成本。"},{"en":"Not only…but… is used to show that two benefits, facts, or results are both true.","zh":"不但……而且……用來顯示兩個好處、事實或結果都是真實的。"},{"en":"Regular reading not only improves vocabulary but also builds confidence in writing.","zh":"定期閱讀不但改善詞彙，而且建立寫作信心。"},{"en":"This structure strengthens an argument by adding a second important point.","zh":"這個結構透過加入第二個重要重點來加強論點。"},{"en":"It is useful when one action creates more than one positive result.","zh":"當一項行動產生多於一個正面結果時，它很有用。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":6},{"front":"lower the internal costs of","meaning":"降低……的內部成本","examples":[{"en":"Safe working conditions lower the internal costs of accidents.","zh":"安全工作環境降低事故的內部成本。"},{"en":"To lower the internal costs of something means to reduce costs that the organisation itself must bear.","zh":"降低某事的內部成本，是指減少組織自身必須承擔的成本。"},{"en":"Better staff training can lower the internal costs of customer complaints.","zh":"更好的員工培訓可以降低顧客投訴的內部成本。"},{"en":"Preventing accidents saves money because companies avoid medical costs, delays, and repairs.","zh":"預防事故能節省金錢，因為公司避免醫療費、延誤和維修費。"},{"en":"This phrase connects prevention with reduced business expenses.","zh":"這個短語把預防與減少企業開支連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":6},{"front":"efficient utilisation of","meaning":"有效利用……","examples":[{"en":"Efficient utilisation of land and energy makes business more productive.","zh":"有效利用土地和能源令企業更具生產力。"},{"en":"Efficient utilisation of something means using it well without unnecessary waste.","zh":"有效利用某物，是指好好使用它而不造成不必要浪費。"},{"en":"A school improves efficient utilisation of classrooms by scheduling different groups at different times.","zh":"學校透過安排不同群組在不同時間使用課室，改善課室有效利用。"},{"en":"Efficient resource use lowers costs and reduces environmental pressure.","zh":"有效使用資源能降低成本並減少環境壓力。"},{"en":"This phrase describes careful and productive use of resources.","zh":"這個短語描述謹慎且具生產力地使用資源。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":6},{"front":"natural resources","meaning":"自然資源","examples":[{"en":"Businesses depend on land, water, energy and other natural resources.","zh":"企業依賴土地、水、能源和其他自然資源。"},{"en":"Natural resources are materials or conditions from nature that people use, such as water, soil, forests, and minerals.","zh":"自然資源是人們使用的自然材料或條件，例如水、泥土、森林和礦物。"},{"en":"Farmers depend on natural resources like clean water and fertile land.","zh":"農民依賴清潔水源和肥沃土地等自然資源。"},{"en":"If natural resources are damaged, businesses may face higher costs and supply problems.","zh":"如果自然資源受損，企業可能面對更高成本和供應問題。"},{"en":"This phrase refers to nature’s useful assets.","zh":"這個短語指自然界的有用資產。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":6},{"front":"good government","meaning":"良好管治","examples":[{"en":"Good government is essential for efficiency and innovation.","zh":"良好管治對效率和創新不可或缺。"},{"en":"Good government means effective, honest, fair, and stable public administration.","zh":"良好管治是有效、誠實、公平且穩定的公共管理。"},{"en":"Good government provides clear rules so businesses and citizens know what to expect.","zh":"良好管治提供清晰規則，讓企業和市民知道可預期甚麼。"},{"en":"Without good government, corruption and uncertainty can discourage investment.","zh":"沒有良好管治，貪污和不確定性會阻礙投資。"},{"en":"This phrase connects public leadership with social and economic health.","zh":"這個短語把公共領導與社會及經濟健康連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":6},{"front":"rule of law","meaning":"法治","examples":[{"en":"The rule of law supports business efficiency.","zh":"法治支持企業效率。"},{"en":"The rule of law means laws are clear, fairly applied, and followed by everyone, including powerful people.","zh":"法治是指法律清晰、公平執行，並由所有人遵守，包括有權勢的人。"},{"en":"Businesses need the rule of law so contracts can be enforced reliably.","zh":"企業需要法治，因為合約能可靠地被執行。"},{"en":"When the rule of law is weak, companies may fear unfair treatment or corruption.","zh":"當法治薄弱，公司可能害怕不公平對待或貪污。"},{"en":"This phrase refers to legal fairness and predictability.","zh":"這個短語指法律公平和可預測性。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":6},{"front":"property rights","meaning":"財產權","examples":[{"en":"Property rights are essential for innovation.","zh":"財產權對創新不可或缺。"},{"en":"Property rights are legal rights to own, use, sell, or protect property or ideas.","zh":"財產權是擁有、使用、出售或保護財產或想法的法律權利。"},{"en":"A writer depends on property rights to protect a book from being copied without permission.","zh":"作者依靠財產權保護書籍免被未經許可複製。"},{"en":"Strong property rights encourage innovation because creators know their work can be protected.","zh":"強大財產權鼓勵創新，因為創作者知道其作品可受保護。"},{"en":"This phrase covers ownership and legal protection.","zh":"這個短語涵蓋擁有權和法律保護。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":6},{"front":"regulatory standards","meaning":"監管標準","examples":[{"en":"Strong regulatory standards protect consumers and companies.","zh":"強大的監管標準保護消費者和公司。"},{"en":"Regulatory standards are official rules that set minimum requirements for safety, quality, fairness, or behaviour.","zh":"監管標準是對安全、質素、公平或行為設定最低要求的官方規則。"},{"en":"Food safety standards tell restaurants how to store and prepare ingredients safely.","zh":"食物安全標準告訴餐廳如何安全儲存和準備食材。"},{"en":"Good regulatory standards prevent irresponsible companies from gaining unfair advantage.","zh":"良好監管標準防止不負責任公司取得不公平優勢。"},{"en":"This phrase refers to rules that shape how industries operate.","zh":"這個短語指塑造行業運作方式的規則。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":6},{"front":"protect A from B","meaning":"保護 A 免受 B","examples":[{"en":"Regulatory standards protect consumers from exploitation.","zh":"監管標準保護消費者免受剝削。"},{"en":"To protect A from B means to keep A safe from harm, danger, or unfair treatment caused by B.","zh":"保護 A 免受 B，是指使 A 免受由 B 造成的傷害、危險或不公平對待。"},{"en":"Seat belts protect passengers from serious injury during accidents.","zh":"安全帶保護乘客免受意外中的嚴重傷害。"},{"en":"Minimum wage laws protect workers from extremely low pay.","zh":"最低工資法保護工人免受極低薪酬。"},{"en":"This phrase clearly shows who is protected and what danger is being prevented.","zh":"這個短語清楚顯示誰受保護，以及正在防止甚麼危險。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":6},{"front":"competitive companies","meaning":"有競爭力的公司","examples":[{"en":"Strong regulations protect competitive companies from exploitation.","zh":"強大規管保護有競爭力的公司免受剝削。"},{"en":"Competitive companies are firms that can succeed by offering good products, fair prices, or better service.","zh":"有競爭力的公司，是能透過好產品、公平價格或更好服務取得成功的企業。"},{"en":"A competitive company may win customers because it is efficient and trustworthy.","zh":"有競爭力的公司可能因高效和可信而贏得顧客。"},{"en":"Fair rules protect competitive companies from rivals that cut costs by cheating or exploiting workers.","zh":"公平規則保護有競爭力的公司，免受透過作弊或剝削員工削減成本的競爭對手影響。"},{"en":"This phrase refers to businesses that compete well in the market.","zh":"這個短語指在市場中有良好競爭能力的企業。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":6},{"front":"exploitation","meaning":"剝削","examples":[{"en":"Consumers and companies need protection from exploitation.","zh":"消費者和公司需要保護以免受剝削。"},{"en":"Exploitation means using people unfairly for profit, advantage, or benefit.","zh":"剝削是為了利潤、優勢或利益而不公平地利用人。"},{"en":"Workers face exploitation when they are paid very little and forced to work unsafe hours.","zh":"當工人薪酬極低並被迫在不安全工時工作，他們就面對剝削。"},{"en":"Strong laws can reduce exploitation by setting clear rights and penalties.","zh":"強大法律可以透過設定清晰權利和罰則來減少剝削。"},{"en":"This word describes unfair use of power.","zh":"這個詞描述不公平地使用權力。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":7},{"front":"ultimately","meaning":"最終","examples":[{"en":"Ultimately, a healthy society creates expanding demand for business.","zh":"最終，健康社會為企業創造不斷擴大的需求。"},{"en":"Ultimately means in the end or after considering the final result.","zh":"最終，是指到最後或考慮最終結果後。"},{"en":"A student may try many methods, but ultimately regular practice matters most.","zh":"學生可能嘗試很多方法，但最終定期練習最重要。"},{"en":"This word helps move from short-term details to the final conclusion.","zh":"這個詞幫助由短期細節轉到最後結論。"},{"en":"It often introduces the deeper or long-term outcome.","zh":"它常引入較深層或長期結果。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":7},{"front":"expanding demand","meaning":"不斷擴大的需求","examples":[{"en":"A healthy society creates expanding demand for business.","zh":"健康社會為企業創造不斷擴大的需求。"},{"en":"Expanding demand means increasing need or desire for products and services.","zh":"不斷擴大的需求，是指對產品和服務的需要或欲望增加。"},{"en":"When more people can afford education, there is expanding demand for books, tutors, and learning apps.","zh":"當更多人負擔得起教育，就會對書籍、導師和學習應用程式有不斷擴大的需求。"},{"en":"Businesses grow when demand expands because more customers are able to buy.","zh":"當需求擴大，企業會成長，因為更多顧客有能力購買。"},{"en":"This phrase describes a market becoming larger over time.","zh":"這個短語描述市場隨時間變大。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":7},{"front":"human needs are met","meaning":"人類需要得到滿足","examples":[{"en":"Business demand grows as more human needs are met.","zh":"隨着更多人類需要得到滿足，商業需求會增長。"},{"en":"Human needs are met when people have access to essentials such as food, health, safety, education, and dignity.","zh":"當人們能取得食物、健康、安全、教育和尊嚴等基本要素時，人類需要就得到滿足。"},{"en":"When a town gains clean water and reliable transport, more human needs are met.","zh":"當城鎮獲得清潔食水和可靠交通，更多人類需要就得到滿足。"},{"en":"As basic needs are met, people may seek better housing, education, and services.","zh":"隨着基本需要得到滿足，人們可能追求更好住屋、教育和服務。"},{"en":"This phrase connects social progress with new forms of demand.","zh":"這個短語把社會進步與新需求形式連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":7},{"front":"aspirations grow","meaning":"願望提升","examples":[{"en":"Demand expands as human aspirations grow.","zh":"隨着人類願望提升，需求會擴大。"},{"en":"Aspirations grow means people’s hopes, ambitions, or expectations become higher.","zh":"願望提升，是指人們的希望、抱負或期望變得更高。"},{"en":"A student’s aspirations may grow after meeting someone from a career they admire.","zh":"學生遇到自己欣賞職業中的人士後，願望可能提升。"},{"en":"When aspirations grow, people often seek better education, products, and opportunities.","zh":"當願望提升，人們通常會尋求更好教育、產品和機會。"},{"en":"This phrase describes rising hopes for a better life.","zh":"這個短語描述對更好生活的希望上升。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":7},{"front":"pursue its ends","meaning":"追求其目標","examples":[{"en":"A business that pursues its ends at society’s expense will suffer.","zh":"一間以犧牲社會為代價追求其目標的企業將會受損。"},{"en":"To pursue its ends means to try to achieve its own goals or purposes.","zh":"追求其目標，是指嘗試達成自己的目標或目的。"},{"en":"A student may pursue their ends by studying hard, but not by cheating classmates.","zh":"學生可以透過努力學習追求目標，但不應透過欺騙同學。"},{"en":"If a company pursues profit while ignoring social harm, its success may not last.","zh":"如果公司追求利潤而忽視社會傷害，其成功可能不會持久。"},{"en":"This phrase focuses on goal-seeking behaviour.","zh":"這個短語聚焦追求目標的行為。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":7},{"front":"at the expense of","meaning":"以犧牲……為代價","examples":[{"en":"No company should pursue profit at the expense of society.","zh":"沒有公司應以犧牲社會為代價追求利潤。"},{"en":"At the expense of something means by harming, sacrificing, or neglecting it.","zh":"以犧牲某事為代價，是指透過傷害、犧牲或忽視它來取得某事。"},{"en":"A student should not improve exam scores at the expense of sleep and health.","zh":"學生不應以犧牲睡眠和健康為代價提高考試分數。"},{"en":"Profit gained at the expense of safety can lead to accidents and lawsuits.","zh":"以犧牲安全為代價取得的利潤，可能導致意外和訴訟。"},{"en":"This phrase shows that one gain creates another loss.","zh":"這個短語顯示一項收益造成另一項損失。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":7},{"front":"find its success to be illusory","meaning":"發現其成功只是幻象","examples":[{"en":"A company may find its success to be illusory and temporary.","zh":"公司可能發現其成功只是幻象且短暫。"},{"en":"To find its success to be illusory means to realise that what looked like success was not real or lasting.","zh":"發現其成功只是幻象，是指意識到看似成功的東西並不真實或不能持久。"},{"en":"A shop may find its success illusory if early sales came only from one short-lived discount.","zh":"如果店舖早期銷售只來自一次短暫折扣，它可能發現成功只是幻象。"},{"en":"Success built on harming others can disappear when customers, regulators, or workers react.","zh":"建立在傷害他人上的成功，會在顧客、監管者或員工反應時消失。"},{"en":"This phrase warns that apparent success may hide weakness.","zh":"這個短語警告表面成功可能隱藏弱點。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":7},{"front":"ultimately temporary","meaning":"最終只是短暫的","examples":[{"en":"Success built at society’s expense is ultimately temporary.","zh":"建立在犧牲社會之上的成功最終只是短暫的。"},{"en":"Ultimately temporary means not lasting in the end, even if it seems successful at first.","zh":"最終只是短暫的，是指到最後不能持久，即使起初看似成功。"},{"en":"A student’s high marks from copying homework are ultimately temporary because real skill has not improved.","zh":"學生靠抄功課取得的高分最終只是短暫的，因為真正技能沒有提升。"},{"en":"Short-term gains may disappear when hidden costs become visible.","zh":"當隱藏成本變得可見，短期收益可能消失。"},{"en":"This phrase stresses that weak success cannot last.","zh":"這個短語強調薄弱成功無法持久。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":7},{"front":"at the same time","meaning":"與此同時","examples":[{"en":"At the same time, a healthy society needs successful companies.","zh":"與此同時，健康社會需要成功公司。"},{"en":"At the same time means meanwhile, or while another point is also true.","zh":"與此同時，是指同時，或另一個重點也成立。"},{"en":"A student needs rest; at the same time, they still need regular practice.","zh":"學生需要休息；與此同時，他們仍需要定期練習。"},{"en":"This phrase helps balance two sides of an argument.","zh":"這個短語幫助平衡論點的兩面。"},{"en":"It is useful when two ideas seem different but both matter.","zh":"當兩個想法看似不同但都重要時，它很有用。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":7},{"front":"social program","meaning":"社會計劃","examples":[{"en":"No social program can rival the business sector.","zh":"沒有社會計劃能與商界匹敵。"},{"en":"A social program is an organised effort to improve people’s welfare, education, health, housing, or opportunities.","zh":"社會計劃是有組織地改善人們福祉、教育、健康、住房或機會的努力。"},{"en":"A city may create a social program to help unemployed young people find training.","zh":"城市可能建立社會計劃，幫助失業青年尋找培訓。"},{"en":"Social programs can help society, but they may not create jobs on the scale of business.","zh":"社會計劃可以幫助社會，但未必能以商界規模創造工作。"},{"en":"This phrase refers to planned social support, often by government or charities.","zh":"這個短語指有計劃的社會支援，通常由政府或慈善機構推行。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":7},{"front":"rival the business sector","meaning":"可與商界匹敵","examples":[{"en":"No social program can rival the business sector in creating jobs.","zh":"沒有社會計劃能在創造工作方面與商界匹敵。"},{"en":"To rival the business sector means to match or compete with companies in scale, effect, or power.","zh":"可與商界匹敵，是指在規模、效果或力量上能與公司相當或競爭。"},{"en":"A small club cannot rival the school system in educating children across a whole city.","zh":"小型學會不能在全城教育孩子方面與學校系統匹敵。"},{"en":"The business sector creates many jobs because companies produce goods, services, wages, and investment.","zh":"商界創造很多工作，因為公司生產商品、服務、薪酬和投資。"},{"en":"This phrase compares one institution’s capacity with business capacity.","zh":"這個短語比較一個機構與商界的能力。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":8},{"front":"when it comes to","meaning":"在……方面","examples":[{"en":"Businesses are powerful when it comes to creating jobs and wealth.","zh":"在創造工作和財富方面，企業很有力量。"},{"en":"When it comes to something means regarding or in the area of that thing.","zh":"在某事方面，是指關於該事或在該領域中。"},{"en":"When it comes to pronunciation, daily listening practice is very important.","zh":"在發音方面，每日聆聽練習非常重要。"},{"en":"This phrase narrows the discussion to one specific topic or ability.","zh":"這個短語把討論收窄到一個特定主題或能力。"},{"en":"It is useful when comparing strengths in different areas.","zh":"它適合用於比較不同領域的強項。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":8},{"front":"standards of living","meaning":"生活水平","examples":[{"en":"Business can improve standards of living over time.","zh":"企業可以隨時間改善生活水平。"},{"en":"Standards of living are the level of comfort, income, health, services, and material well-being people enjoy.","zh":"生活水平是人們享有的舒適程度、收入、健康、服務和物質福祉水平。"},{"en":"Better public transport can improve standards of living by reducing travel time.","zh":"更好的公共交通可以透過減少交通時間來改善生活水平。"},{"en":"When jobs and wages rise, standards of living may improve for many families.","zh":"當工作和工資增加，許多家庭的生活水平可能改善。"},{"en":"This phrase describes quality of life in practical economic terms.","zh":"這個短語以實際經濟角度描述生活質素。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":8},{"front":"social conditions","meaning":"社會狀況","examples":[{"en":"Successful companies can improve social conditions over time.","zh":"成功公司可以隨時間改善社會狀況。"},{"en":"Social conditions are the circumstances people live in, including jobs, safety, education, health, and equality.","zh":"社會狀況是人們生活的情況，包括工作、安全、教育、健康和平等。"},{"en":"Poor housing and unsafe streets are examples of difficult social conditions.","zh":"差劣住屋和不安全街道是困難社會狀況的例子。"},{"en":"Companies can improve social conditions by creating stable jobs and supporting local services.","zh":"公司可以透過創造穩定工作和支持本地服務來改善社會狀況。"},{"en":"This phrase describes the environment in which society functions.","zh":"這個短語描述社會運作的環境。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":8},{"front":"impact on society","meaning":"對社會的影響","examples":[{"en":"A company’s impact on society changes over time.","zh":"公司對社會的影響會隨時間改變。"},{"en":"Impact on society means the effect something has on people, communities, institutions, and daily life.","zh":"對社會的影響，是某事對人、社區、制度和日常生活造成的效果。"},{"en":"A new railway can have a strong impact on society by changing where people live and work.","zh":"新鐵路可以透過改變人們居住和工作的地方而對社會有重大影響。"},{"en":"A company’s impact on society may become clearer only after many years.","zh":"公司對社會的影響可能要多年後才變得清楚。"},{"en":"This phrase asks what difference an action makes beyond the company itself.","zh":"這個短語問一項行動對公司以外造成甚麼差異。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":8},{"front":"evolve","meaning":"演變；發展","examples":[{"en":"Social standards evolve as science progresses.","zh":"社會標準會隨着科學進步而演變。"},{"en":"To evolve means to develop or change gradually over time.","zh":"演變或發展，是指隨時間逐漸發展或改變。"},{"en":"Teaching methods evolve when teachers learn more about how students remember information.","zh":"當老師更了解學生如何記憶資訊，教學方法就會演變。"},{"en":"Social expectations evolve as new evidence, values, and technologies appear.","zh":"隨着新證據、價值和科技出現，社會期望會演變。"},{"en":"This word describes gradual development, not sudden replacement.","zh":"這個詞描述逐漸發展，而不是突然取代。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":8},{"front":"science progresses","meaning":"科學進步","examples":[{"en":"A company’s responsibilities change as science progresses.","zh":"隨着科學進步，公司責任會改變。"},{"en":"Science progresses means scientific knowledge improves through research and new evidence.","zh":"科學進步是指科學知識透過研究和新證據而改善。"},{"en":"Medical advice changes as science progresses and doctors learn more about diseases.","zh":"隨着科學進步，醫療建議會改變，因為醫生更了解疾病。"},{"en":"When science progresses, companies may discover that old materials or practices are unsafe.","zh":"當科學進步，公司可能發現舊材料或做法並不安全。"},{"en":"This phrase connects new knowledge with changing responsibility.","zh":"這個短語把新知識與責任變化連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":8},{"front":"asbestos","meaning":"石棉","examples":[{"en":"Asbestos is now understood as a serious health risk.","zh":"石棉現在被理解為嚴重健康風險。"},{"en":"Asbestos is a fibrous building material once widely used for insulation and fire resistance.","zh":"石棉是一種纖維狀建築材料，曾廣泛用於隔熱和防火。"},{"en":"Old buildings may contain asbestos in ceilings, pipes, or walls.","zh":"舊建築可能在天花板、管道或牆壁中含有石棉。"},{"en":"Asbestos became dangerous because tiny fibres can damage lungs when breathed in.","zh":"石棉變得危險，是因為微小纖維被吸入時會損害肺部。"},{"en":"This word is often used as an example of a material once accepted but later recognised as harmful.","zh":"這個詞常被用作曾被接受但後來被認定有害的材料例子。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":8},{"front":"serious health risk","meaning":"嚴重健康風險","examples":[{"en":"Asbestos is now considered a serious health risk.","zh":"石棉現在被視為嚴重健康風險。"},{"en":"A serious health risk is something that can cause major illness, injury, or death.","zh":"嚴重健康風險，是可能造成重大疾病、傷害或死亡的事物。"},{"en":"Drinking polluted water can be a serious health risk for children and elderly people.","zh":"飲用受污染食水對兒童和長者可能是嚴重健康風險。"},{"en":"When a product becomes a serious health risk, companies may face recalls and lawsuits.","zh":"當產品變成嚴重健康風險，公司可能面對回收和訴訟。"},{"en":"This phrase signals danger that should not be treated lightly.","zh":"這個短語表示不應輕視的危險。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":8},{"front":"given the scientific knowledge","meaning":"鑑於當時的科學知識","examples":[{"en":"Asbestos was thought to be safe given the scientific knowledge then available.","zh":"鑑於當時可用的科學知識，石棉曾被認為安全。"},{"en":"Given the scientific knowledge means considering what scientists knew at that time.","zh":"鑑於當時的科學知識，是指考慮科學家在那時所知道的內容。"},{"en":"Given the medical knowledge then available, some old treatments seemed reasonable but are no longer used.","zh":"鑑於當時可用的醫學知識，有些舊治療方法看似合理，但現在已不再使用。"},{"en":"New evidence can change what seems safe or acceptable.","zh":"新證據可以改變某事看起來是否安全或可接受。"},{"en":"This phrase helps judge past decisions in light of past knowledge.","zh":"這個短語幫助根據過去知識判斷過去決定。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":8},{"front":"evidence of its risks","meaning":"其風險的證據","examples":[{"en":"Evidence of its risks gradually mounted.","zh":"其風險的證據逐漸增加。"},{"en":"Evidence of its risks means information showing that something may be harmful or dangerous.","zh":"其風險的證據，是顯示某物可能有害或危險的資訊。"},{"en":"If several patients become ill after using a product, that may be evidence of its risks.","zh":"如果幾名病人使用某產品後生病，那可能是其風險的證據。"},{"en":"Companies should respond when evidence of risk becomes stronger, not wait for disaster.","zh":"當風險證據變得更強，公司應作出回應，而不是等待災難。"},{"en":"This phrase points to proof that danger exists.","zh":"這個短語指出危險存在的證明。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":8},{"front":"gradually mounted","meaning":"逐漸增加","examples":[{"en":"Evidence of asbestos risk gradually mounted over decades.","zh":"石棉風險的證據在數十年間逐漸增加。"},{"en":"Gradually mounted means slowly increased or became stronger over time.","zh":"逐漸增加，是指隨時間慢慢增加或變強。"},{"en":"Complaints about a noisy road gradually mounted as more families moved nearby.","zh":"隨着更多家庭搬到附近，關於嘈雜道路的投訴逐漸增加。"},{"en":"When evidence gradually mounts, ignoring it becomes harder to justify.","zh":"當證據逐漸增加，忽視它就越來越難合理化。"},{"en":"This phrase describes slow accumulation.","zh":"這個短語描述慢慢累積。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":9},{"front":"be held liable for","meaning":"對……負法律責任","examples":[{"en":"Companies were later held liable for the harm asbestos caused.","zh":"公司後來被判對石棉造成的傷害負法律責任。"},{"en":"To be held liable for something means to be legally responsible for it.","zh":"對某事負法律責任，是指在法律上要為它負責。"},{"en":"A bus company may be held liable for injuries if poor maintenance caused an accident.","zh":"如果維修不善造成意外，巴士公司可能要對傷者負法律責任。"},{"en":"Companies can face large costs when courts hold them liable for preventable harm.","zh":"當法院判定公司要為可避免傷害負責，公司可能面對巨額成本。"},{"en":"This phrase is legal and focuses on responsibility for damage.","zh":"這個短語屬法律用語，聚焦對損害的責任。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":9},{"front":"harm it could cause","meaning":"它可能造成的傷害","examples":[{"en":"Companies were held liable for the harm asbestos could cause.","zh":"公司被判對石棉可能造成的傷害負責。"},{"en":"Harm it could cause means the damage or injury something was capable of producing.","zh":"它可能造成的傷害，是指某物有能力造成的損害或傷害。"},{"en":"A school must consider the harm broken playground equipment could cause.","zh":"學校必須考慮損壞遊樂場設備可能造成的傷害。"},{"en":"Ignoring possible harm can lead to injuries and legal responsibility.","zh":"忽視可能傷害會導致受傷和法律責任。"},{"en":"This phrase focuses on potential danger, not only harm that has already happened.","zh":"這個短語聚焦潛在危險，而不只是已經發生的傷害。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":9},{"front":"fail to anticipate","meaning":"未能預見","examples":[{"en":"Many firms failed to anticipate the consequences of research.","zh":"許多公司未能預見研究帶來的後果。"},{"en":"To fail to anticipate something means not to predict or prepare for it before it happens.","zh":"未能預見某事，是指在它發生前沒有預測或準備。"},{"en":"A restaurant may fail to anticipate a lunch rush and run out of staff.","zh":"餐廳可能未能預見午餐人潮，結果人手不足。"},{"en":"Companies that fail to anticipate future risks may face sudden costs later.","zh":"未能預見未來風險的公司，之後可能面對突然成本。"},{"en":"This phrase describes a failure of foresight.","zh":"這個短語描述缺乏前瞻。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":9},{"front":"evolving body of research","meaning":"不斷發展的研究成果","examples":[{"en":"Companies ignored an evolving body of research about asbestos.","zh":"公司忽視了關於石棉的不斷發展的研究成果。"},{"en":"An evolving body of research is a growing and changing collection of studies and evidence.","zh":"不斷發展的研究成果，是一套正在增長和改變的研究與證據。"},{"en":"Doctors follow an evolving body of research when advice about a disease changes.","zh":"當疾病建議改變，醫生會跟隨不斷發展的研究成果。"},{"en":"Businesses should monitor research because new findings can change what is considered safe.","zh":"企業應監察研究，因為新發現會改變甚麼被視為安全。"},{"en":"This phrase suggests knowledge developing over time.","zh":"這個短語暗示知識隨時間發展。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":9},{"front":"be bankrupted by","meaning":"因……而破產","examples":[{"en":"Many firms were bankrupted by the results.","zh":"許多公司因這些結果而破產。"},{"en":"To be bankrupted by something means to lose so much money because of it that the business cannot continue.","zh":"因某事而破產，是指因它損失太多金錢，以致企業無法繼續。"},{"en":"A small shop may be bankrupted by a long closure after a fire.","zh":"小店可能因火災後長期停業而破產。"},{"en":"Legal claims and compensation can bankrupt firms if the costs are enormous.","zh":"如果成本巨大，法律索償和賠償可以令公司破產。"},{"en":"This phrase describes financial collapse caused by a specific event or problem.","zh":"這個短語描述由特定事件或問題造成的財務崩潰。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":9},{"front":"be content to","meaning":"滿足於……","examples":[{"en":"Companies can no longer be content to monitor obvious impacts only.","zh":"公司不能再滿足於只監察明顯影響。"},{"en":"To be content to do something means to be satisfied with doing only that much.","zh":"滿足於做某事，是指只做到那個程度就感到足夠。"},{"en":"A student should not be content to memorise answers without understanding the method.","zh":"學生不應滿足於背答案而不理解方法。"},{"en":"Companies that are content to check only obvious risks may miss future dangers.","zh":"滿足於只檢查明顯風險的公司，可能錯過未來危險。"},{"en":"This phrase often suggests that a limited approach is no longer enough.","zh":"這個短語常暗示有限做法已經不足夠。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":9},{"front":"obvious social impacts","meaning":"明顯社會影響","examples":[{"en":"Companies must look beyond obvious social impacts.","zh":"公司必須超越明顯社會影響去看問題。"},{"en":"Obvious social impacts are effects on people or communities that are easy to see immediately.","zh":"明顯社會影響，是對人或社區造成並容易立即看見的效果。"},{"en":"A factory’s noise and traffic are obvious social impacts for nearby residents.","zh":"工廠的噪音和交通是附近居民可見的明顯社會影響。"},{"en":"Less obvious impacts may appear later, such as long-term health or employment effects.","zh":"較不明顯的影響可能之後才出現，例如長期健康或就業影響。"},{"en":"This phrase contrasts visible effects with hidden or future effects.","zh":"這個短語把可見效果與隱藏或未來效果作對比。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":9},{"front":"careful process for identifying","meaning":"識別……的謹慎流程","examples":[{"en":"Firms need a careful process for identifying future social effects.","zh":"公司需要一套識別未來社會影響的謹慎流程。"},{"en":"A careful process for identifying something is a planned method for finding it accurately.","zh":"識別某事的謹慎流程，是準確找出它的有計劃方法。"},{"en":"A hospital needs a careful process for identifying patients who may be at risk of infection.","zh":"醫院需要一套謹慎流程來識別可能有感染風險的病人。"},{"en":"Careful processes reduce mistakes because decisions are not based on guesswork alone.","zh":"謹慎流程能減少錯誤，因為決策不只依靠猜測。"},{"en":"This phrase stresses systematic detection.","zh":"這個短語強調系統化識別。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":9},{"front":"social effects of tomorrow","meaning":"未來的社會影響","examples":[{"en":"Companies must identify the evolving social effects of tomorrow.","zh":"公司必須識別不斷演變的未來社會影響。"},{"en":"Social effects of tomorrow are future impacts that today’s decisions may have on society.","zh":"未來的社會影響，是今日決定日後可能對社會造成的影響。"},{"en":"A new technology company should think about the social effects of tomorrow, such as privacy and job changes.","zh":"新科技公司應思考未來社會影響，例如私隱和工作變化。"},{"en":"Anticipating future effects helps companies avoid repeating mistakes like asbestos.","zh":"預見未來影響有助公司避免重複石棉般的錯誤。"},{"en":"This phrase focuses on responsibilities that may become clear later.","zh":"這個短語聚焦日後才可能變清楚的責任。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":9},{"front":"risk their very survival","meaning":"危及自身生存","examples":[{"en":"Firms may risk their very survival if they ignore future effects.","zh":"如果公司忽視未來影響，可能危及自身生存。"},{"en":"To risk their very survival means to put their continued existence in danger.","zh":"危及自身生存，是指令自己能否繼續存在陷入危險。"},{"en":"A small business may risk its survival if it ignores customer safety complaints.","zh":"如果小企業忽視顧客安全投訴，就可能危及自身生存。"},{"en":"Companies can collapse when legal, financial, or reputational damage becomes too large.","zh":"當法律、財務或聲譽損害變得太大，公司可能倒閉。"},{"en":"This phrase gives a very strong warning about serious danger.","zh":"這個短語對嚴重危險發出強烈警告。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":9},{"front":"solve all of society’s problems","meaning":"解決社會所有問題","examples":[{"en":"No business can solve all of society’s problems.","zh":"沒有企業能解決社會所有問題。"},{"en":"To solve all of society’s problems means to fix every major issue affecting people and communities.","zh":"解決社會所有問題，是指修正影響人和社區的每一個重大議題。"},{"en":"A hospital can improve health care, but it cannot solve all problems related to poverty and housing alone.","zh":"醫院可以改善醫療服務，但不能獨自解決所有與貧窮和住屋相關的問題。"},{"en":"Expecting one company to solve every social issue is unrealistic and inefficient.","zh":"期望一間公司解決每個社會議題並不現實，也沒有效率。"},{"en":"This phrase sets a limit on what business can responsibly do.","zh":"這個短語為企業能負責任地做甚麼設定限制。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":10},{"front":"bear the cost of","meaning":"承擔……的成本","examples":[{"en":"No business can bear the cost of solving every social problem.","zh":"沒有企業能承擔解決每個社會問題的成本。"},{"en":"To bear the cost of something means to pay for it or accept its financial burden.","zh":"承擔某事的成本，是指支付它或接受其財務負擔。"},{"en":"A family may not be able to bear the cost of private medical treatment without insurance.","zh":"沒有保險的家庭可能無法承擔私人醫療費用。"},{"en":"If one company bears too many social costs alone, it may weaken its business.","zh":"如果一間公司獨自承擔太多社會成本，就可能削弱其業務。"},{"en":"This phrase focuses on who pays for an action or problem.","zh":"這個短語聚焦誰為行動或問題付費。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":10},{"front":"select issues","meaning":"選擇議題","examples":[{"en":"Each company must select issues that fit its business.","zh":"每間公司都必須選擇符合其業務的議題。"},{"en":"To select issues means to choose specific problems to focus on.","zh":"選擇議題，是指選出要集中處理的特定問題。"},{"en":"A school council may select issues such as lunch quality, bullying, and classroom noise.","zh":"學生會可能選擇午餐質素、欺凌和課室噪音等議題。"},{"en":"Selecting issues helps organisations avoid spreading their effort too thinly.","zh":"選擇議題幫助組織避免把努力分散得太薄。"},{"en":"This phrase emphasises choice and focus.","zh":"這個短語強調選擇和焦點。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":10},{"front":"intersect with","meaning":"與……交叉；與……相關","examples":[{"en":"Companies should focus on issues that intersect with their business.","zh":"公司應聚焦於與其業務相關的議題。"},{"en":"To intersect with something means to connect with or overlap with it.","zh":"與某事交叉或相關，是指與它連接或重疊。"},{"en":"A food company’s work intersects with nutrition, farming, and public health.","zh":"食品公司的工作與營養、農業和公共健康交叉。"},{"en":"CSR is stronger when social issues intersect with what the company actually does.","zh":"當社會議題與公司實際業務相關，企業社會責任會更強。"},{"en":"This phrase shows a meaningful connection between two areas.","zh":"這個短語顯示兩個範疇之間有意義的連繫。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":10},{"front":"particular business","meaning":"特定業務","examples":[{"en":"Each company should choose issues linked to its particular business.","zh":"每間公司都應選擇與其特定業務相關的議題。"},{"en":"A particular business means the specific type of company, industry, or operation being discussed.","zh":"特定業務，是指正在討論的具體公司類型、行業或營運方式。"},{"en":"A logistics company’s particular business involves transport, warehouses, fuel, and delivery workers.","zh":"物流公司的特定業務涉及運輸、倉庫、燃料和送貨員。"},{"en":"CSR should fit the particular business because different companies affect society in different ways.","zh":"企業社會責任應配合特定業務，因為不同公司以不同方式影響社會。"},{"en":"This phrase focuses on the company’s own field, not business in general.","zh":"這個短語聚焦公司自身範疇，而不是一般商業。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":10},{"front":"social agendas","meaning":"社會議程","examples":[{"en":"Other social agendas are best left to other organisations.","zh":"其他社會議程最好留給其他組織處理。"},{"en":"Social agendas are sets of social goals, causes, or issues that groups want to address.","zh":"社會議程是一組群體希望處理的社會目標、理念或議題。"},{"en":"A charity may have a social agenda focused on homelessness and mental health.","zh":"慈善機構可能有集中於無家者和心理健康的社會議程。"},{"en":"Companies should not take on every social agenda if another organisation is better suited.","zh":"如果另一個組織更合適，公司不應承擔每個社會議程。"},{"en":"This phrase refers to planned social priorities.","zh":"這個短語指有計劃的社會優先事項。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":10},{"front":"be best left to","meaning":"最好留給……處理","examples":[{"en":"Some issues are best left to NGOs or government institutions.","zh":"有些議題最好留給非政府組織或政府機構處理。"},{"en":"To be best left to someone means that person or group is more suitable to handle it.","zh":"最好留給某人處理，是指該人或群體更適合處理它。"},{"en":"Complex medical decisions are best left to trained doctors, not random online advice.","zh":"複雜醫療決定最好留給受訓醫生，而不是隨機網上建議。"},{"en":"A company should leave some issues to experts when it lacks knowledge or authority.","zh":"當公司缺乏知識或權力，有些議題應留給專家處理。"},{"en":"This phrase shows appropriate division of responsibility.","zh":"這個短語顯示責任的合適分工。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":10},{"front":"be better positioned to","meaning":"更適合去……","examples":[{"en":"Some organisations are better positioned to address certain problems.","zh":"有些組織更適合處理某些問題。"},{"en":"To be better positioned to do something means to have better resources, knowledge, authority, or opportunity to do it.","zh":"更適合做某事，是指擁有更好的資源、知識、權力或機會去做它。"},{"en":"A local clinic is better positioned to understand neighbourhood health needs than a distant office.","zh":"與遠方辦公室相比，本地診所更適合理解社區健康需要。"},{"en":"Organisations with direct experience can address problems more effectively.","zh":"有直接經驗的組織能更有效處理問題。"},{"en":"This phrase explains why one group is more suitable than another.","zh":"這個短語解釋為何某群體比另一群體更合適。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":10},{"front":"address them","meaning":"處理它們","examples":[{"en":"Other institutions may be better positioned to address social problems.","zh":"其他機構可能更適合處理社會問題。"},{"en":"To address them means to deal with, discuss, or try to solve those problems.","zh":"處理它們，是指應對、討論或嘗試解決那些問題。"},{"en":"If students complain about bullying, the school must address the problem quickly.","zh":"如果學生投訴欺凌，學校必須迅速處理問題。"},{"en":"Problems worsen when institutions know about them but do not address them.","zh":"當機構知道問題卻不處理，問題會惡化。"},{"en":"This phrase focuses on taking action, not merely noticing an issue.","zh":"這個短語聚焦採取行動，而不只是注意到議題。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":10},{"front":"essential test","meaning":"核心測試","examples":[{"en":"The essential test for CSR is whether it creates shared value.","zh":"企業社會責任的核心測試是它是否創造共享價值。"},{"en":"An essential test is the most important standard used to judge something.","zh":"核心測試是用來判斷某事的最重要標準。"},{"en":"The essential test for a study plan is whether it actually helps students remember and apply knowledge.","zh":"學習計劃的核心測試，是它是否真正幫助學生記住並應用知識。"},{"en":"A clear test prevents organisations from choosing actions only because they sound impressive.","zh":"清晰測試防止組織只因行動聽起來令人印象深刻而選擇它。"},{"en":"This phrase identifies the key question that decides value.","zh":"這個短語指出決定價值的關鍵問題。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":10},{"front":"guide CSR","meaning":"指導企業社會責任","examples":[{"en":"A clear test should guide CSR decisions.","zh":"清晰測試應指導企業社會責任決策。"},{"en":"To guide CSR means to direct how companies choose and manage responsible business actions.","zh":"指導企業社會責任，是指引導公司如何選擇和管理負責任商業行動。"},{"en":"Clear principles can guide CSR so a company supports causes linked to its real impact.","zh":"清晰原則可以指導企業社會責任，使公司支持與其真實影響相關的理念。"},{"en":"Without guidance, CSR can become scattered, symbolic, or ineffective.","zh":"沒有指引，企業社會責任可能變得分散、象徵化或無效。"},{"en":"This phrase focuses on giving direction to CSR choices.","zh":"這個短語聚焦為企業社會責任選擇提供方向。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":10},{"front":"whether a cause is worthy","meaning":"某個理念是否值得支持","examples":[{"en":"The question is not simply whether a cause is worthy.","zh":"問題並不單是某個理念是否值得支持。"},{"en":"Whether a cause is worthy means whether a social issue deserves support because it is important or good.","zh":"某個理念是否值得支持，是指某個社會議題是否因重要或有益而值得支援。"},{"en":"Helping children read is a worthy cause, but not every company is equally suited to support it.","zh":"幫助孩子閱讀是一個值得支持的理念，但不是每間公司都同樣適合支援它。"},{"en":"CSR decisions need more than worthiness; they also need fit, impact, and shared value.","zh":"企業社會責任決定需要的不只是值得支持，還需要配合度、影響和共享價值。"},{"en":"This phrase separates moral attractiveness from strategic suitability.","zh":"這個短語把道德吸引力與策略合適性分開。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":11},{"front":"present an opportunity to","meaning":"提供機會去……","examples":[{"en":"A CSR issue should present an opportunity to create shared value.","zh":"企業社會責任議題應提供創造共享價值的機會。"},{"en":"To present an opportunity to do something means to offer a chance to achieve it.","zh":"提供機會去做某事，是指提供達成它的機會。"},{"en":"A school competition may present an opportunity for quiet students to show leadership.","zh":"學校比賽可能為安靜學生提供展示領導能力的機會。"},{"en":"A social issue presents an opportunity when solving it also strengthens the company’s capabilities.","zh":"當解決社會議題也能加強公司能力時，該議題就提供機會。"},{"en":"This phrase points to a useful opening for action.","zh":"這個短語指出有用的行動契機。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":11},{"front":"create shared value","meaning":"創造共享價值","examples":[{"en":"CSR should create shared value for business and society.","zh":"企業社會責任應為企業和社會創造共享價值。"},{"en":"To create shared value means to produce benefits for both a company and the wider community.","zh":"創造共享價值，是指為公司和更廣泛社區同時產生好處。"},{"en":"A food company creates shared value when it supports local farmers and gains fresher supplies.","zh":"食品公司支持本地農民並獲得更新鮮供應時，就是創造共享價值。"},{"en":"Shared value is stronger than charity alone because business success and social progress support each other.","zh":"共享價值比單純慈善更強，因為企業成功和社會進步互相支持。"},{"en":"This phrase is central to strategic CSR.","zh":"這個短語是策略性企業社會責任的核心。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":11},{"front":"meaningful benefit","meaning":"有意義的好處","examples":[{"en":"Shared value creates a meaningful benefit for society.","zh":"共享價值為社會創造有意義的好處。"},{"en":"A meaningful benefit is a real and important improvement, not a small symbolic gesture.","zh":"有意義的好處是真實且重要的改善，而不是小型象徵姿態。"},{"en":"Free skills training can be a meaningful benefit if it helps unemployed people find stable work.","zh":"如果免費技能培訓幫助失業人士找到穩定工作，它就是有意義的好處。"},{"en":"Benefits are meaningful when they change people’s lives or solve a real problem.","zh":"當好處改變人們生活或解決真實問題，它就是有意義的。"},{"en":"This phrase stresses substance rather than appearance.","zh":"這個短語強調實質，而不是外觀。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":11},{"front":"valuable to the business","meaning":"對企業有價值","examples":[{"en":"A social benefit should also be valuable to the business.","zh":"社會利益也應對企業有價值。"},{"en":"Valuable to the business means useful for the company’s goals, operations, reputation, or long-term success.","zh":"對企業有價值，是指對公司的目標、營運、聲譽或長期成功有用。"},{"en":"Training local workers is valuable to the business if it helps the company hire skilled staff.","zh":"如果培訓本地工人能幫助公司聘請熟練員工，它就對企業有價值。"},{"en":"CSR lasts longer when it benefits society and is also valuable to the business.","zh":"當企業社會責任既有益社會又對企業有價值，它會更持久。"},{"en":"This phrase connects social action with business relevance.","zh":"這個短語把社會行動與商業相關性連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":11},{"front":"particular set of","meaning":"特定一組……","examples":[{"en":"Each company can identify a particular set of societal problems.","zh":"每間公司都可以識別一組特定社會問題。"},{"en":"A particular set of something means a specific group chosen from a larger number of possibilities.","zh":"特定一組某物，是從較多可能性中選出的具體群組。"},{"en":"A teacher may focus on a particular set of grammar mistakes before an exam.","zh":"老師可能在考試前集中處理特定一組文法錯誤。"},{"en":"Choosing a particular set of issues helps a company concentrate resources where it can make a difference.","zh":"選擇特定一組議題有助公司把資源集中在能產生差異的地方。"},{"en":"This phrase stresses selection and specificity.","zh":"這個短語強調選擇和具體性。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":11},{"front":"societal problems","meaning":"社會問題","examples":[{"en":"Companies should focus on societal problems they can help solve.","zh":"公司應聚焦於它們能幫助解決的社會問題。"},{"en":"Societal problems are issues affecting many people across society, such as poor education, pollution, or unemployment.","zh":"社會問題是影響社會中許多人的議題，例如教育不足、污染或失業。"},{"en":"A city facing youth unemployment is dealing with a societal problem, not just individual failure.","zh":"面對青年失業的城市，是在處理社會問題，而不只是個人失敗。"},{"en":"Businesses can help solve societal problems when their skills match the issue.","zh":"當企業技能與議題相配，企業可以幫助解決社會問題。"},{"en":"This phrase refers to broad social issues.","zh":"這個短語指廣泛社會議題。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":11},{"front":"be equipped to","meaning":"有能力去……","examples":[{"en":"A company should solve problems it is best equipped to address.","zh":"公司應解決它最有能力處理的問題。"},{"en":"To be equipped to do something means to have the tools, skills, knowledge, or resources needed for it.","zh":"有能力做某事，是指擁有所需工具、技能、知識或資源。"},{"en":"A hospital is equipped to treat injuries, while a school is equipped to teach children.","zh":"醫院有能力治療傷病，而學校有能力教導兒童。"},{"en":"Companies should choose CSR issues they are equipped to handle well.","zh":"公司應選擇自己有能力處理好的企業社會責任議題。"},{"en":"This phrase focuses on real capacity, not just good intentions.","zh":"這個短語聚焦真實能力，而不只是善意。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":11},{"front":"resolve","meaning":"解決","examples":[{"en":"Companies can help resolve selected social problems.","zh":"公司可以幫助解決選定的社會問題。"},{"en":"To resolve a problem means to solve it or reduce it in a clear and effective way.","zh":"解決問題，是指以清楚有效方式處理或減少它。"},{"en":"A teacher may resolve a classroom conflict by listening to both students and setting fair rules.","zh":"老師可以透過聆聽兩名學生並設定公平規則來解決課室衝突。"},{"en":"Problems are resolved more effectively when people address causes, not only symptoms.","zh":"當人們處理原因而不只是表面症狀，問題會更有效被解決。"},{"en":"This verb suggests bringing a problem toward a workable solution.","zh":"這個動詞暗示把問題推向可行方案。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":11},{"front":"competitive benefit","meaning":"競爭優勢","examples":[{"en":"CSR can produce competitive benefit for a company.","zh":"企業社會責任可以為公司產生競爭優勢。"},{"en":"Competitive benefit is an advantage that helps a company perform better than rivals.","zh":"競爭優勢是幫助公司比競爭對手表現更好的優勢。"},{"en":"A company gains competitive benefit when strong training gives it more skilled workers than competitors.","zh":"當強大培訓令公司擁有比對手更熟練的員工，它就獲得競爭優勢。"},{"en":"CSR creates competitive benefit when social action improves supply, trust, or innovation.","zh":"當社會行動改善供應、信任或創新，企業社會責任就會創造競爭優勢。"},{"en":"This phrase connects responsible behaviour with market advantage.","zh":"這個短語把負責任行為與市場優勢連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":11},{"front":"corporate citizenship initiatives","meaning":"企業公民措施","examples":[{"en":"The best corporate citizenship initiatives involve more than donations.","zh":"最佳企業公民措施不只是捐款。"},{"en":"Corporate citizenship initiatives are actions through which companies act as responsible members of society.","zh":"企業公民措施，是公司作為負責任社會成員而採取的行動。"},{"en":"A company may run corporate citizenship initiatives such as school mentoring, health campaigns, or environmental clean-ups.","zh":"公司可能推行學校指導、健康宣傳或環境清潔等企業公民措施。"},{"en":"These initiatives are stronger when employees contribute time and expertise, not only money.","zh":"當員工貢獻時間和專業知識，而不只是金錢，這些措施會更強。"},{"en":"This phrase treats companies as social citizens with responsibilities.","zh":"這個短語把公司視為有責任的社會公民。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":11},{"front":"far more than","meaning":"遠不止……","examples":[{"en":"Good CSR involves far more than writing a cheque.","zh":"良好企業社會責任遠不止開支票捐款。"},{"en":"Far more than means much more than one simple action or amount.","zh":"遠不止，是指遠多於一個簡單行動或數量。"},{"en":"Good teaching involves far more than giving students worksheets.","zh":"良好教學遠不止給學生工作紙。"},{"en":"CSR that is far more than donation requires planning, measurement, and genuine involvement.","zh":"遠不止捐款的企業社會責任需要規劃、量度和真實參與。"},{"en":"This phrase emphasises that the real task is broader and deeper.","zh":"這個短語強調真正任務更廣泛、更深入。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":12},{"front":"write a cheque","meaning":"開支票捐款","examples":[{"en":"Corporate citizenship should involve more than writing a cheque.","zh":"企業公民行動應不只是開支票捐款。"},{"en":"To write a cheque means to donate or pay money, often without direct involvement.","zh":"開支票捐款，是指捐出或支付金錢，通常沒有直接參與。"},{"en":"A company can write a cheque to a charity, but that alone may not solve the problem.","zh":"公司可以開支票給慈善機構，但單靠這樣未必能解決問題。"},{"en":"Social impact is deeper when companies also offer skills, volunteers, and long-term support.","zh":"當公司也提供技能、義工和長期支援，社會影響會更深。"},{"en":"This phrase is often used to criticise shallow charity.","zh":"這個短語常用來批評膚淺慈善。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":12},{"front":"specify clear, measurable goals","meaning":"訂明清晰可量度的目標","examples":[{"en":"Good initiatives specify clear, measurable goals.","zh":"良好措施訂明清晰可量度的目標。"},{"en":"To specify clear, measurable goals means to state exact aims that can be checked with evidence.","zh":"訂明清晰可量度的目標，是指說明可用證據檢查的精確目標。"},{"en":"A reading programme may specify a measurable goal: every student reads ten books by June.","zh":"閱讀計劃可以訂明一個可量度目標：每名學生六月前閱讀十本書。"},{"en":"Measurable goals help organisations know whether their efforts are working.","zh":"可量度目標幫助組織知道努力是否有效。"},{"en":"This phrase connects planning with accountability.","zh":"這個短語把規劃與問責連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":12},{"front":"track results over time","meaning":"長期追蹤成效","examples":[{"en":"Effective programmes track results over time.","zh":"有效計劃會長期追蹤成效。"},{"en":"To track results over time means to measure progress repeatedly across a period.","zh":"長期追蹤成效，是指在一段時間內反覆量度進展。"},{"en":"A teacher may track students’ vocabulary scores over time to see whether practice works.","zh":"老師可能長期追蹤學生詞彙分數，以了解練習是否有效。"},{"en":"Tracking results prevents organisations from assuming success without evidence.","zh":"追蹤成效能防止組織在沒有證據下假設成功。"},{"en":"This phrase describes long-term monitoring.","zh":"這個短語描述長期監測。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":12},{"front":"adopt underperforming public high schools","meaning":"支援表現欠佳的公立高中","examples":[{"en":"General Electric adopted underperforming public high schools.","zh":"General Electric 支援表現欠佳的公立高中。"},{"en":"To adopt underperforming public high schools means to support struggling government-funded secondary schools over time.","zh":"支援表現欠佳的公立高中，是指長期支持有困難的政府資助中學。"},{"en":"A company might adopt an underperforming school by funding tutoring, equipment, and mentoring.","zh":"公司可能透過資助補習、設備和指導來支援表現欠佳的學校。"},{"en":"Adoption creates responsibility because the company commits to helping improvement, not only giving one-time aid.","zh":"支援會創造責任，因為公司承諾幫助改善，而不只是一次性援助。"},{"en":"This phrase describes long-term support for schools that are not performing well.","zh":"這個短語描述對表現不佳學校的長期支援。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":12},{"front":"major U.S. facilities","meaning":"主要美國設施","examples":[{"en":"The schools were near several of GE’s major U.S. facilities.","zh":"這些學校位於 GE 幾個主要美國設施附近。"},{"en":"Major U.S. facilities are important buildings, factories, offices, or sites a company operates in the United States.","zh":"主要美國設施，是公司在美國營運的重要建築、工廠、辦公室或地點。"},{"en":"A company may support schools near its major facilities because many employees live nearby.","zh":"公司可能支持其主要設施附近的學校，因為許多員工住在附近。"},{"en":"Linking CSR to local facilities helps a company strengthen community relationships where it operates.","zh":"把企業社會責任與本地設施連接，有助公司在營運地加強社區關係。"},{"en":"This phrase refers to significant company sites in the United States.","zh":"這個短語指公司在美國的重要地點。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":12},{"front":"contribute between","meaning":"捐出介乎……之間","examples":[{"en":"The company contributes between $250,000 and $1 million to each school.","zh":"公司向每間學校捐出介乎 25 萬至 100 萬美元。"},{"en":"To contribute between two amounts means to give an amount within that stated range.","zh":"捐出介乎兩個金額之間，是指提供在該範圍內的金額。"},{"en":"A charity may contribute between $5,000 and $10,000 to each community centre.","zh":"慈善機構可能向每個社區中心捐出介乎 5,000 至 10,000 美元。"},{"en":"Stating a range helps readers understand the scale without giving one fixed figure.","zh":"說明範圍有助讀者理解規模，而不需給出單一固定數字。"},{"en":"This phrase is used when contributions vary by case.","zh":"當捐助因個案而異時，會使用這個短語。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":12},{"front":"over a five-year period","meaning":"在五年期間","examples":[{"en":"GE contributes money over a five-year period.","zh":"GE 在五年期間捐助金錢。"},{"en":"Over a five-year period means during five years, not all at once.","zh":"在五年期間，是指在五年內進行，而不是一次完成。"},{"en":"A school improvement plan may provide funding over a five-year period.","zh":"學校改善計劃可能在五年期間提供資金。"},{"en":"Long-term funding allows programmes to plan, test, and improve gradually.","zh":"長期資助讓計劃能逐步規劃、測試和改善。"},{"en":"This phrase describes support spread across time.","zh":"這個短語描述分散於時間中的支援。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":12},{"front":"in-kind donations","meaning":"實物捐贈","examples":[{"en":"The company makes in-kind donations as well.","zh":"公司也作出實物捐贈。"},{"en":"In-kind donations are gifts of goods, services, equipment, or expertise instead of cash.","zh":"實物捐贈是捐出物品、服務、設備或專業知識，而不是現金。"},{"en":"A computer company may give in-kind donations by providing laptops to a school.","zh":"電腦公司可以透過向學校提供手提電腦來作實物捐贈。"},{"en":"In-kind donations can be valuable when the recipient needs practical tools more than money.","zh":"當受助者需要實用工具多於金錢，實物捐贈可以很有價值。"},{"en":"This phrase contrasts non-cash support with financial donations.","zh":"這個短語把非現金支援與金錢捐助作對比。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":12},{"front":"take an active role","meaning":"積極參與","examples":[{"en":"GE managers and employees take an active role in the schools.","zh":"GE 經理和員工積極參與學校事務。"},{"en":"To take an active role means to participate directly and seriously, not just watch or donate.","zh":"積極參與，是指直接而認真地參與，而不只是旁觀或捐款。"},{"en":"Parents take an active role in education when they read with children and attend school meetings.","zh":"家長與孩子閱讀並出席學校會議時，就是積極參與教育。"},{"en":"Active involvement often creates stronger results than distant financial support alone.","zh":"積極參與通常比單純遠距離資金支援產生更強效果。"},{"en":"This phrase emphasises participation and responsibility.","zh":"這個短語強調參與和責任。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":12},{"front":"school administrators","meaning":"學校行政人員","examples":[{"en":"Employees worked with school administrators to assess needs.","zh":"員工與學校行政人員合作評估需要。"},{"en":"School administrators are staff who manage school operations, planning, records, and services.","zh":"學校行政人員是管理學校營運、規劃、紀錄和服務的職員。"},{"en":"A principal and office manager may be school administrators.","zh":"校長和校務主任可能都是學校行政人員。"},{"en":"Working with administrators helps outside partners understand what a school actually needs.","zh":"與行政人員合作有助外部伙伴理解學校真正需要甚麼。"},{"en":"This phrase refers to people who help run the school.","zh":"這個短語指協助營運學校的人。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":12},{"front":"assess needs","meaning":"評估需要","examples":[{"en":"GE employees helped assess needs in the schools.","zh":"GE 員工幫助評估學校需要。"},{"en":"To assess needs means to examine what people or organisations require before deciding how to help.","zh":"評估需要，是指在決定如何幫助前，檢查人或組織需要甚麼。"},{"en":"A nurse may assess a patient’s needs before planning treatment.","zh":"護士可能在規劃治療前評估病人需要。"},{"en":"Assessing needs prevents wasted support because help is matched to real problems.","zh":"評估需要可以防止支援浪費，因為幫助會配合真實問題。"},{"en":"This phrase describes careful diagnosis before action.","zh":"這個短語描述行動前的仔細診斷。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":13},{"front":"mentor or tutor students","meaning":"指導或輔導學生","examples":[{"en":"GE employees mentor or tutor students.","zh":"GE 員工指導或輔導學生。"},{"en":"To mentor or tutor students means to guide them personally or teach them specific academic skills.","zh":"指導或輔導學生，是指親自引導他們，或教授特定學科技能。"},{"en":"An older student may mentor a younger student by giving study advice and encouragement.","zh":"高年級學生可以透過提供學習建議和鼓勵來指導低年級學生。"},{"en":"Tutoring helps when students need direct support in subjects such as maths or reading.","zh":"當學生需要數學或閱讀等科目的直接支援時，輔導會有幫助。"},{"en":"This phrase combines personal guidance with learning help.","zh":"這個短語結合個人指導與學習幫助。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":13},{"front":"independent study","meaning":"獨立研究","examples":[{"en":"An independent study examined ten schools in the programme.","zh":"一項獨立研究考察了該計劃中的十間學校。"},{"en":"An independent study is research carried out by people who are not directly controlled by the organisation being studied.","zh":"獨立研究是由不受被研究組織直接控制的人進行的研究。"},{"en":"A hospital may ask for an independent study to check whether a new treatment programme works.","zh":"醫院可能要求進行獨立研究，以檢查新治療計劃是否有效。"},{"en":"Independent studies can increase trust because results seem less biased.","zh":"獨立研究可以增加信任，因為結果看起來較少偏見。"},{"en":"This phrase refers to outside or neutral evaluation.","zh":"這個短語指外部或中立評估。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":13},{"front":"significant improvement","meaning":"顯著改善","examples":[{"en":"Nearly all schools showed significant improvement.","zh":"幾乎所有學校都顯示顯著改善。"},{"en":"Significant improvement means clear and important progress, not a tiny change.","zh":"顯著改善，是指清楚而重要的進步，而不是微小變化。"},{"en":"A student shows significant improvement when their writing becomes clearer and more accurate across several essays.","zh":"如果學生在幾篇文章中寫得更清楚且更準確，就是顯示顯著改善。"},{"en":"Programmes are easier to justify when they produce significant improvement in measurable results.","zh":"當計劃在可量度結果上產生顯著改善，它就更容易被合理化。"},{"en":"This phrase describes progress that is noticeable and meaningful.","zh":"這個短語描述明顯且有意義的進展。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":13},{"front":"graduation rate","meaning":"畢業率","examples":[{"en":"The graduation rate doubled in several schools.","zh":"幾間學校的畢業率翻倍。"},{"en":"Graduation rate is the percentage of students who successfully complete a school programme.","zh":"畢業率是成功完成學校課程的學生百分比。"},{"en":"A school with a high graduation rate helps more students move on to work or further study.","zh":"畢業率高的學校幫助更多學生進入工作或繼續升學。"},{"en":"Improving graduation rates can show that students are staying in school and finishing successfully.","zh":"改善畢業率可以顯示學生留在學校並成功完成學業。"},{"en":"This phrase is a measurable education outcome.","zh":"這個短語是一項可量度的教育成果。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":13},{"front":"worst-performing schools","meaning":"表現最差的學校","examples":[{"en":"The graduation rate improved in four of the five worst-performing schools.","zh":"五間表現最差的學校中，有四間畢業率有所改善。"},{"en":"Worst-performing schools are schools with the weakest results compared with others.","zh":"表現最差的學校，是與其他學校相比結果最弱的學校。"},{"en":"A district may give extra support to its worst-performing schools before judging teachers or students.","zh":"地區可能先向表現最差的學校提供額外支援，再評價老師或學生。"},{"en":"Improving weak schools can reduce inequality because struggling students receive more help.","zh":"改善弱校可以減少不平等，因為有困難學生得到更多幫助。"},{"en":"This phrase compares schools by performance level.","zh":"這個短語按表現水平比較學校。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":13},{"front":"effective corporate citizenship","meaning":"有效企業公民行動","examples":[{"en":"Effective corporate citizenship creates goodwill.","zh":"有效企業公民行動建立好感。"},{"en":"Effective corporate citizenship means a company acts responsibly in ways that create real social value.","zh":"有效企業公民行動，是公司以創造真實社會價值的方式負責任行事。"},{"en":"A bank shows effective corporate citizenship when it offers financial education to vulnerable families.","zh":"銀行向弱勢家庭提供理財教育時，就是展示有效企業公民行動。"},{"en":"Corporate citizenship is effective when communities can see practical benefits.","zh":"當社區能看見實際好處，企業公民行動就是有效的。"},{"en":"This phrase refers to responsible business action that actually works.","zh":"這個短語指真正有效的負責任商業行動。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":13},{"front":"create goodwill","meaning":"建立好感；善意","examples":[{"en":"CSR initiatives can create goodwill.","zh":"企業社會責任措施可以建立好感。"},{"en":"To create goodwill means to build friendly feelings, trust, and positive relationships.","zh":"建立好感，是指建立友善感覺、信任和正面關係。"},{"en":"A shop creates goodwill when it handles complaints honestly and politely.","zh":"店舖誠實而有禮地處理投訴時，就是建立好感。"},{"en":"Goodwill can make communities more willing to support a company during difficult times.","zh":"好感可以令社區在困難時期更願意支持公司。"},{"en":"This phrase describes building positive social feeling.","zh":"這個短語描述建立正面社會感覺。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":13},{"front":"improve relations with","meaning":"改善與……的關係","examples":[{"en":"CSR can improve relations with local governments.","zh":"企業社會責任可以改善與地方政府的關係。"},{"en":"To improve relations with someone means to make the relationship more cooperative, respectful, or trusting.","zh":"改善與某人的關係，是指令關係更合作、更尊重或更可信。"},{"en":"A school can improve relations with parents by communicating clearly and listening to concerns.","zh":"學校可以透過清楚溝通和聆聽關注來改善與家長的關係。"},{"en":"Better relations reduce conflict and make joint problem-solving easier.","zh":"更好關係能減少衝突，令共同解決問題更容易。"},{"en":"This phrase describes strengthening relationships between groups.","zh":"這個短語描述加強群體之間的關係。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":13},{"front":"local governments","meaning":"地方政府","examples":[{"en":"Effective initiatives improve relations with local governments.","zh":"有效措施改善與地方政府的關係。"},{"en":"Local governments are public authorities that manage cities, towns, districts, or regions.","zh":"地方政府是管理城市、城鎮、地區或區域的公共機關。"},{"en":"A company may work with local governments on transport, waste, or job-training projects.","zh":"公司可能與地方政府合作處理交通、廢物或職業培訓項目。"},{"en":"Good relations with local governments help companies understand local rules and community priorities.","zh":"與地方政府有良好關係，有助公司理解本地規則和社區優先事項。"},{"en":"This phrase refers to government at the community or regional level.","zh":"這個短語指社區或區域層面的政府。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":13},{"front":"constituencies","meaning":"相關群體；支持群體","examples":[{"en":"Companies must maintain relationships with important constituencies.","zh":"公司必須維持與重要相關群體的關係。"},{"en":"Constituencies are groups of people whose support, needs, or opinions matter to an organisation.","zh":"相關群體，是其支持、需要或意見對組織重要的人群。"},{"en":"A school’s constituencies include students, parents, teachers, alumni, and local residents.","zh":"學校的相關群體包括學生、家長、老師、校友和本地居民。"},{"en":"Companies lose influence when important constituencies feel ignored or harmed.","zh":"當重要相關群體感到被忽視或受傷害，公司會失去影響力。"},{"en":"This phrase refers to key groups connected to an institution.","zh":"這個短語指與機構相關的關鍵群體。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":13},{"front":"what’s more","meaning":"此外","examples":[{"en":"What’s more, GE’s employees feel great pride in their participation.","zh":"此外，GE 員工對自己的參與感到非常自豪。"},{"en":"What’s more means in addition, especially when adding another important point.","zh":"此外，是指另外，尤其用於加入另一個重要重點。"},{"en":"The new library is larger; what’s more, it stays open later for students.","zh":"新圖書館更大；此外，它為學生開放到更晚。"},{"en":"This phrase adds extra support to an argument.","zh":"這個短語為論點加入額外支持。"},{"en":"It often introduces a benefit that makes the previous point stronger.","zh":"它常引入令前一點更強的好處。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":14},{"front":"feel great pride in","meaning":"對……感到非常自豪","examples":[{"en":"Employees feel great pride in their participation.","zh":"員工對自己的參與感到非常自豪。"},{"en":"To feel great pride in something means to feel very pleased and honoured by being connected with it.","zh":"對某事感到非常自豪，是指因與它相關而感到非常高興和光榮。"},{"en":"A student may feel great pride in representing the school at a debate competition.","zh":"學生代表學校參加辯論比賽時，可能感到非常自豪。"},{"en":"Pride can increase motivation because people believe their work matters.","zh":"自豪感可以提高動力，因為人們相信自己的工作有意義。"},{"en":"This phrase describes strong positive emotion toward an achievement or role.","zh":"這個短語描述對成就或角色的強烈正面情緒。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":14},{"front":"participation","meaning":"參與","examples":[{"en":"GE employees take pride in their participation.","zh":"GE 員工對自己的參與感到自豪。"},{"en":"Participation means taking part in an activity, programme, or decision.","zh":"參與是指加入活動、計劃或決定。"},{"en":"Student participation in class increases when teachers ask clear and friendly questions.","zh":"當老師提出清楚而友善的問題，學生課堂參與會增加。"},{"en":"Participation creates ownership because people feel they are part of the result.","zh":"參與會創造主人翁感，因為人們覺得自己是成果的一部分。"},{"en":"This word focuses on involvement, not just observation.","zh":"這個詞聚焦投入，而不只是觀察。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":14},{"front":"inherently limited","meaning":"本質上有限","examples":[{"en":"The effect of the programme is inherently limited.","zh":"該計劃的效果本質上有限。"},{"en":"Inherently limited means limited by its basic nature, not just by poor management.","zh":"本質上有限，是指限制來自其基本性質，而不只是管理不善。"},{"en":"A one-hour workshop is inherently limited because it cannot replace months of practice.","zh":"一小時工作坊本質上有限，因為它不能取代數月練習。"},{"en":"Even a good programme may be limited if its design affects only a small area.","zh":"即使是好計劃，如果設計只影響小範圍，也可能有限。"},{"en":"This phrase explains that the limitation comes from what the thing is.","zh":"這個短語解釋限制來自事物本身。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":14},{"front":"no matter how beneficial","meaning":"不論多有益","examples":[{"en":"No matter how beneficial the programme is, it remains incidental.","zh":"不論該計劃多有益，它仍然只是附帶的。"},{"en":"No matter how beneficial means even if something is very useful or positive.","zh":"不論多有益，是指即使某事非常有用或正面。"},{"en":"No matter how beneficial exercise is, too much without rest can still cause injury.","zh":"不論運動多有益，過量而不休息仍會造成受傷。"},{"en":"This phrase introduces a contrast between a good quality and an important limitation.","zh":"這個短語引入好處與重要限制之間的對比。"},{"en":"It helps show that benefit alone does not solve every concern.","zh":"它幫助顯示有益本身並不能解決每個問題。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":14},{"front":"remain incidental to","meaning":"對……而言只是附帶的","examples":[{"en":"The programme remains incidental to GE’s business.","zh":"該計劃對 GE 的業務而言仍只是附帶的。"},{"en":"To remain incidental to something means to stay secondary or not central to it.","zh":"對某事而言只是附帶的，是指仍然是次要或非核心。"},{"en":"A school concert may be enjoyable but remain incidental to the school’s main teaching mission.","zh":"學校音樂會可能令人愉快，但對學校主要教學使命而言仍只是附帶的。"},{"en":"A CSR programme can do good but still have little connection to the company’s core business.","zh":"企業社會責任計劃可以做好事，但仍與公司核心業務關係不大。"},{"en":"This phrase describes something helpful but not strategically central.","zh":"這個短語描述有幫助但非策略核心的事物。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":14},{"front":"direct effect on","meaning":"對……的直接影響","examples":[{"en":"The programme has only a modest direct effect on recruiting.","zh":"該計劃對招聘只有有限直接影響。"},{"en":"A direct effect on something is an immediate or clear influence on it.","zh":"對某事的直接影響，是對它有即時或清楚的影響。"},{"en":"A higher salary may have a direct effect on staff recruitment.","zh":"較高薪酬可能對員工招聘有直接影響。"},{"en":"Some CSR actions improve reputation but have little direct effect on sales or hiring.","zh":"有些企業社會責任行動改善聲譽，但對銷售或招聘直接影響很小。"},{"en":"This phrase distinguishes clear impact from indirect or distant impact.","zh":"這個短語區分清楚影響與間接或遙遠影響。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":14},{"front":"recruiting and retention","meaning":"招聘和留任","examples":[{"en":"The programme has a modest effect on recruiting and retention.","zh":"該計劃對招聘和留任有有限影響。"},{"en":"Recruiting and retention mean hiring new employees and keeping existing employees.","zh":"招聘和留任，是指聘請新員工和留住現有員工。"},{"en":"A company improves recruiting and retention when workers trust its culture and see career opportunities.","zh":"當員工信任公司文化並看見職業機會，公司就能改善招聘和留任。"},{"en":"Poor management hurts retention because good employees may leave.","zh":"管理不善會傷害留任，因為好員工可能離開。"},{"en":"This phrase covers both bringing people in and keeping them.","zh":"這個短語涵蓋吸引人加入和留住人。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":14},{"front":"shared-value opportunity","meaning":"共享價值機會","examples":[{"en":"Microsoft’s partnership is a shared-value opportunity.","zh":"Microsoft 的伙伴合作是一個共享價值機會。"},{"en":"A shared-value opportunity is a chance to create benefits for both society and the company.","zh":"共享價值機會，是同時為社會和公司創造好處的機會。"},{"en":"A hospital partnership with nursing schools can be a shared-value opportunity if it trains staff and improves care.","zh":"醫院與護理學校合作，如果能培訓員工並改善護理，就可以是共享價值機會。"},{"en":"These opportunities are powerful because social progress supports business success.","zh":"這些機會很有力，因為社會進步支持商業成功。"},{"en":"This phrase describes CSR that fits strategy.","zh":"這個短語描述符合策略的企業社會責任。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":14},{"front":"arise from","meaning":"源自","examples":[{"en":"The shared-value opportunity arises from investments in context.","zh":"共享價值機會源自對營運環境的投資。"},{"en":"To arise from something means to come from it or be caused by it.","zh":"源自某事，是指來自它或由它造成。"},{"en":"A student’s confidence may arise from repeated practice and kind feedback.","zh":"學生信心可能源自反覆練習和友善回饋。"},{"en":"Business opportunities can arise from social problems that a company is able to help solve.","zh":"商業機會可以源自公司有能力幫助解決的社會問題。"},{"en":"This phrase identifies the source of an outcome.","zh":"這個短語指出結果來源。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":14},{"front":"investments in context","meaning":"對營運環境的投資","examples":[{"en":"Microsoft’s programme arose from investments in context.","zh":"Microsoft 的計劃源自對營運環境的投資。"},{"en":"Investments in context are efforts to improve the social or economic environment in which a company operates.","zh":"對營運環境的投資，是改善公司營運所在社會或經濟環境的努力。"},{"en":"A logistics company invests in context when it supports safer roads and driver training.","zh":"物流公司支持更安全道路和司機培訓時，就是投資營運環境。"},{"en":"These investments help business because a healthier environment makes operations easier.","zh":"這些投資幫助企業，因為更健康環境令營運更容易。"},{"en":"This phrase links social conditions with business success.","zh":"這個短語把社會條件與商業成功連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":14},{"front":"shortage of","meaning":"……短缺","examples":[{"en":"The shortage of information technology workers limits Microsoft’s growth.","zh":"資訊科技人員短缺限制 Microsoft 的增長。"},{"en":"A shortage of something means there is not enough of it to meet demand.","zh":"某物短缺，是指數量不足以滿足需求。"},{"en":"A school may face a shortage of teachers if many staff leave at the same time.","zh":"如果許多員工同時離職，學校可能面對教師短缺。"},{"en":"Shortages can slow growth because organisations cannot find the people or materials they need.","zh":"短缺會拖慢增長，因為組織找不到所需人手或材料。"},{"en":"This phrase describes insufficient supply.","zh":"這個短語描述供應不足。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":15},{"front":"information technology workers","meaning":"資訊科技人員","examples":[{"en":"There is a shortage of information technology workers.","zh":"資訊科技人員短缺。"},{"en":"Information technology workers are people who work with computers, networks, software, data, or technical systems.","zh":"資訊科技人員，是從事電腦、網絡、軟件、數據或技術系統工作的人。"},{"en":"A hospital needs information technology workers to maintain patient-record systems.","zh":"醫院需要資訊科技人員維護病人紀錄系統。"},{"en":"When IT workers are scarce, companies may struggle to build and support digital products.","zh":"當資訊科技人員稀缺，公司可能難以建立和支援數碼產品。"},{"en":"This phrase refers to skilled workers in technology roles.","zh":"這個短語指科技職位中的熟練工作者。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":15},{"front":"significant constraint on","meaning":"對……的重大限制","examples":[{"en":"The worker shortage is a significant constraint on Microsoft’s growth.","zh":"工人短缺是 Microsoft 增長的重大限制。"},{"en":"A significant constraint on something is an important factor that limits it.","zh":"對某事的重大限制，是限制它的重要因素。"},{"en":"Lack of classroom space can be a significant constraint on a school’s expansion.","zh":"課室空間不足可以是學校擴展的重大限制。"},{"en":"Constraints slow progress because they block what an organisation wants to do.","zh":"限制會拖慢進展，因為它們阻礙組織想做的事。"},{"en":"This phrase describes a major limiting factor.","zh":"這個短語描述主要限制因素。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":15},{"front":"unfilled IT positions","meaning":"未填補的 IT 職位","examples":[{"en":"There are more than 450,000 unfilled IT positions in the United States.","zh":"美國有超過 45 萬個未填補的 IT 職位。"},{"en":"Unfilled IT positions are technology jobs that employers want to fill but have not yet filled.","zh":"未填補的 IT 職位，是僱主想聘人但尚未填補的科技工作。"},{"en":"A company with many unfilled IT positions may delay software projects.","zh":"有很多未填補 IT 職位的公司可能延遲軟件項目。"},{"en":"Unfilled positions often show a mismatch between available skills and labour-market demand.","zh":"未填補職位通常顯示可用技能與勞動市場需求不配合。"},{"en":"This phrase refers to job vacancies in information technology.","zh":"這個短語指資訊科技職位空缺。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":15},{"front":"community colleges","meaning":"社區學院","examples":[{"en":"Community colleges could be a major solution to the skills shortage.","zh":"社區學院可以是技能短缺的主要解決方法。"},{"en":"Community colleges are local colleges that offer affordable education, training, and two-year programmes.","zh":"社區學院是提供可負擔教育、培訓和兩年制課程的本地學院。"},{"en":"A working adult may attend a community college to learn computer skills at night.","zh":"在職成年人可能晚上到社區學院學習電腦技能。"},{"en":"Community colleges can help local employers by training students for practical jobs.","zh":"社區學院可以透過為實用工作培訓學生來幫助本地僱主。"},{"en":"This phrase refers to accessible post-secondary education institutions.","zh":"這個短語指容易接觸的專上教育機構。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":15},{"front":"enrolment","meaning":"註冊學生人數","examples":[{"en":"Community colleges have an enrolment of 11.6 million students.","zh":"社區學院有 1,160 萬名註冊學生。"},{"en":"Enrolment is the number of students officially registered in a school or programme.","zh":"註冊學生人數是正式登記在學校或課程中的學生數目。"},{"en":"A language course with high enrolment may need more teachers and classrooms.","zh":"註冊學生人數高的語言課程可能需要更多老師和課室。"},{"en":"Enrolment figures help institutions plan staffing, funding, and facilities.","zh":"註冊人數幫助機構規劃人手、資金和設施。"},{"en":"This word refers to registered student numbers.","zh":"這個詞指已登記的學生數量。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":15},{"front":"undergraduates","meaning":"大學生","examples":[{"en":"Community college students represent 45% of all U.S. undergraduates.","zh":"社區學院學生佔所有美國大學生的 45%。"},{"en":"Undergraduates are students studying for their first college or university degree.","zh":"大學生是正在攻讀第一個大專或大學學位的學生。"},{"en":"Many undergraduates balance classes with part-time work.","zh":"許多大學生需要在上課和兼職之間取得平衡。"},{"en":"Supporting undergraduates can improve the future workforce because they are preparing for careers.","zh":"支持大學生可以改善未來勞動力，因為他們正在為職業作準備。"},{"en":"This word refers to students before postgraduate study.","zh":"這個詞指研究生階段以前的學生。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":15},{"front":"major solution","meaning":"主要解決方法","examples":[{"en":"Community colleges could be a major solution to the IT worker shortage.","zh":"社區學院可以是 IT 人員短缺的主要解決方法。"},{"en":"A major solution is an important way to solve a serious problem.","zh":"主要解決方法，是解決嚴重問題的重要方式。"},{"en":"Better public transport can be a major solution to traffic congestion in crowded cities.","zh":"更好的公共交通可以是擁擠城市交通堵塞的主要解決方法。"},{"en":"A major solution works because it addresses a large part of the problem.","zh":"主要解決方法有效，是因為它處理問題很大一部分。"},{"en":"This phrase suggests an answer with real scale and importance.","zh":"這個短語暗示具有實際規模和重要性的答案。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":15},{"front":"face special challenges","meaning":"面對特殊挑戰","examples":[{"en":"Microsoft recognises that community colleges face special challenges.","zh":"Microsoft 意識到社區學院面對特殊挑戰。"},{"en":"To face special challenges means to deal with difficulties that are particular or unusual.","zh":"面對特殊挑戰，是指處理特定或不尋常的困難。"},{"en":"Students from low-income families may face special challenges such as long travel times and limited internet access.","zh":"低收入家庭學生可能面對特殊挑戰，例如交通時間長和互聯網有限。"},{"en":"Recognising special challenges helps organisations design more useful support.","zh":"認識特殊挑戰有助組織設計更有用支援。"},{"en":"This phrase points to difficulties that need targeted solutions.","zh":"這個短語指出需要針對性解決方法的困難。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":15},{"front":"IT curricula","meaning":"資訊科技課程","examples":[{"en":"IT curricula are not standardised in community colleges.","zh":"社區學院中的資訊科技課程並未標準化。"},{"en":"IT curricula are the planned courses, topics, and learning goals for information technology education.","zh":"資訊科技課程，是資訊科技教育中的課程、課題和學習目標。"},{"en":"An IT curriculum may include coding, databases, cybersecurity, and networking.","zh":"資訊科技課程可能包括編程、數據庫、網絡安全和網絡技術。"},{"en":"If IT curricula differ widely, employers may not know what skills graduates have.","zh":"如果資訊科技課程差異很大，僱主可能不知道畢業生具備甚麼技能。"},{"en":"This phrase refers to what students are taught in IT programmes.","zh":"這個短語指學生在資訊科技課程中學甚麼。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":15},{"front":"be standardised","meaning":"被標準化","examples":[{"en":"IT curricula are not standardised.","zh":"資訊科技課程並未被標準化。"},{"en":"To be standardised means to follow the same agreed structure, rules, or requirements.","zh":"被標準化，是指遵循相同的協定結構、規則或要求。"},{"en":"Exam instructions are standardised so all candidates receive the same task.","zh":"考試指示被標準化，使所有考生收到相同任務。"},{"en":"Standardised curricula make it easier to compare students’ skills across schools.","zh":"標準化課程令比較不同學校學生技能更容易。"},{"en":"This phrase describes making things consistent.","zh":"這個短語描述令事物一致。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":15},{"front":"outdated","meaning":"過時的","examples":[{"en":"Technology used in classrooms is often outdated.","zh":"課室中使用的科技常常過時。"},{"en":"Outdated means old and no longer suitable for current needs or standards.","zh":"過時的，是指舊而不再適合當前需要或標準。"},{"en":"An outdated computer may be too slow to run modern learning software.","zh":"過時電腦可能太慢，無法運行現代學習軟件。"},{"en":"Outdated equipment can make students learn skills that employers no longer need.","zh":"過時設備會令學生學到僱主不再需要的技能。"},{"en":"This word describes something left behind by current development.","zh":"這個詞描述被當前發展拋離的東西。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":16},{"front":"systematic professional development programmes","meaning":"系統化專業發展計劃","examples":[{"en":"Colleges lack systematic professional development programmes.","zh":"學院缺乏系統化專業發展計劃。"},{"en":"Systematic professional development programmes are organised training plans that help staff improve their skills over time.","zh":"系統化專業發展計劃，是幫助員工隨時間改善技能的有組織培訓計劃。"},{"en":"A school may run systematic professional development programmes on teaching methods and digital tools.","zh":"學校可能舉辦關於教學方法和數碼工具的系統化專業發展計劃。"},{"en":"Without systematic training, teachers may struggle to keep up with new technology.","zh":"沒有系統化培訓，老師可能難以跟上新科技。"},{"en":"This phrase describes planned, ongoing staff development.","zh":"這個短語描述有計劃、持續的員工發展。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":16},{"front":"keep faculty up to date","meaning":"讓教師掌握最新知識","examples":[{"en":"Professional development programmes keep faculty up to date.","zh":"專業發展計劃讓教師掌握最新知識。"},{"en":"To keep faculty up to date means to help teachers or college staff stay informed about current knowledge and methods.","zh":"讓教師掌握最新知識，是指幫助教師或學院職員了解當前知識和方法。"},{"en":"Training workshops keep faculty up to date on new classroom technology.","zh":"培訓工作坊讓教師掌握新課室科技。"},{"en":"If faculty are not up to date, students may learn outdated skills.","zh":"如果教師未能掌握最新知識，學生可能學到過時技能。"},{"en":"This phrase focuses on maintaining current professional knowledge.","zh":"這個短語聚焦維持當前專業知識。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":16},{"front":"five-year initiative","meaning":"五年計劃","examples":[{"en":"Microsoft launched a $50 million five-year initiative.","zh":"Microsoft 推出一項 5,000 萬美元的五年計劃。"},{"en":"A five-year initiative is a planned project or programme lasting five years.","zh":"五年計劃是持續五年的有計劃項目或方案。"},{"en":"A city may start a five-year initiative to improve public housing.","zh":"城市可能啟動五年計劃來改善公共房屋。"},{"en":"Long initiatives allow organisations to set goals, test actions, and measure results.","zh":"長期計劃讓組織設定目標、測試行動並量度成果。"},{"en":"This phrase describes a time-limited but long-term programme.","zh":"這個短語描述有時限但長期的計劃。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":16},{"front":"be aimed at","meaning":"旨在解決……","examples":[{"en":"The initiative was aimed at all three problems.","zh":"該計劃旨在解決全部三個問題。"},{"en":"To be aimed at something means to be designed to deal with it or achieve it.","zh":"旨在某事，是指被設計來處理它或達成它。"},{"en":"A reading campaign aimed at young children may use picture books and storytelling.","zh":"針對幼童的閱讀活動可能使用圖畫書和講故事。"},{"en":"Programmes are more effective when they are clearly aimed at specific problems.","zh":"當計劃清楚針對具體問題，它們會更有效。"},{"en":"This phrase describes purpose and target.","zh":"這個短語描述目的和目標。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":16},{"front":"contributing money and products","meaning":"捐助金錢和產品","examples":[{"en":"Microsoft contributed money and products to colleges.","zh":"Microsoft 向學院捐助金錢和產品。"},{"en":"Contributing money and products means giving both financial support and useful goods or tools.","zh":"捐助金錢和產品，是指同時提供財務支援和有用物品或工具。"},{"en":"A company may contribute money and products by donating funds and computers to a school.","zh":"公司可以透過向學校捐款和捐電腦來捐助金錢和產品。"},{"en":"Combining cash with products can help organisations meet both budget and equipment needs.","zh":"結合現金和產品可以幫助組織同時滿足預算和設備需要。"},{"en":"This phrase describes mixed financial and material support.","zh":"這個短語描述財務和物資混合支援。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":16},{"front":"employee volunteers","meaning":"員工義工","examples":[{"en":"Microsoft sent employee volunteers to colleges.","zh":"Microsoft 派員工義工到學院。"},{"en":"Employee volunteers are company staff who give time and skills to help a social project.","zh":"員工義工是公司職員付出時間和技能來幫助社會項目。"},{"en":"Employee volunteers may tutor students, clean parks, or teach digital skills.","zh":"員工義工可能輔導學生、清潔公園或教授數碼技能。"},{"en":"Volunteers can make CSR more personal because employees participate directly.","zh":"義工能令企業社會責任更個人化，因為員工直接參與。"},{"en":"This phrase refers to workers serving as volunteers through their company.","zh":"這個短語指透過公司參與義工服務的員工。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":16},{"front":"curriculum development","meaning":"課程發展","examples":[{"en":"Employee volunteers contributed to curriculum development.","zh":"員工義工參與課程發展。"},{"en":"Curriculum development is the process of designing or improving what students learn in a course.","zh":"課程發展是設計或改善學生在課程中學習內容的過程。"},{"en":"Teachers do curriculum development when they update lessons to include new skills.","zh":"老師更新課堂以加入新技能時，就是在進行課程發展。"},{"en":"Strong curriculum development helps students learn knowledge that matches real-world needs.","zh":"良好課程發展幫助學生學到符合現實需要的知識。"},{"en":"This phrase refers to building or revising educational content.","zh":"這個短語指建立或修訂教育內容。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":16},{"front":"faculty development institutes","meaning":"教師發展學院","examples":[{"en":"Microsoft helped create faculty development institutes.","zh":"Microsoft 幫助建立教師發展學院。"},{"en":"Faculty development institutes are organised centres or programmes that train teachers and college staff.","zh":"教師發展學院是培訓教師和學院職員的有組織中心或計劃。"},{"en":"A faculty development institute may teach lecturers how to update IT courses.","zh":"教師發展學院可能教講師如何更新資訊科技課程。"},{"en":"Such institutes help education stay current when technology changes quickly.","zh":"當科技快速變化，這類學院幫助教育保持最新。"},{"en":"This phrase refers to formal structures for improving teaching staff.","zh":"這個短語指改善教學人員的正式架構。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":16},{"front":"achieve results","meaning":"取得成果","examples":[{"en":"Microsoft has achieved results that benefited communities.","zh":"Microsoft 已取得有益社區的成果。"},{"en":"To achieve results means to produce clear outcomes or improvements.","zh":"取得成果，是指產生清楚結果或改善。"},{"en":"A study plan achieves results when students’ marks and confidence both improve.","zh":"當學生分數和信心都有改善，學習計劃就是取得成果。"},{"en":"Programmes need to achieve results because good intentions alone are not enough.","zh":"計劃需要取得成果，因為單靠善意並不足夠。"},{"en":"This phrase focuses on practical outcomes.","zh":"這個短語聚焦實際結果。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":16},{"front":"potentially significant impact","meaning":"潛在重大影響","examples":[{"en":"The programme may have a potentially significant impact on Microsoft.","zh":"該計劃可能對 Microsoft 有潛在重大影響。"},{"en":"Potentially significant impact means an effect that could become important or large.","zh":"潛在重大影響，是可能變得重要或巨大的影響。"},{"en":"A new bus route may have a potentially significant impact on small shops if it brings more customers.","zh":"如果新巴士路線帶來更多顧客，它可能對小店有潛在重大影響。"},{"en":"Potential impact matters because leaders must plan before the full effect appears.","zh":"潛在影響很重要，因為領袖必須在完整效果出現前規劃。"},{"en":"This phrase describes possible major influence, not guaranteed results.","zh":"這個短語描述可能的重大影響，而不是保證結果。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":16},{"front":"at the heart of","meaning":"……的核心","examples":[{"en":"At the heart of any strategy is a unique value proposition.","zh":"任何策略的核心都是獨特價值主張。"},{"en":"At the heart of something means at its central or most important part.","zh":"某事的核心，是指其中心或最重要部分。"},{"en":"At the heart of good teaching is understanding what students actually need.","zh":"良好教學的核心是理解學生真正需要甚麼。"},{"en":"If something is at the heart of a strategy, other decisions should support it.","zh":"如果某事位於策略核心，其他決定應支持它。"},{"en":"This phrase identifies the core idea.","zh":"這個短語指出核心理念。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":17},{"front":"unique value proposition","meaning":"獨特價值主張","examples":[{"en":"A strategy needs a unique value proposition.","zh":"策略需要獨特價值主張。"},{"en":"A unique value proposition is the special promise of value a company offers to its chosen customers.","zh":"獨特價值主張是公司向選定顧客提供的特殊價值承諾。"},{"en":"A tutoring centre’s unique value proposition may be personalised feedback within 24 hours.","zh":"補習中心的獨特價值主張可能是 24 小時內提供個人化回饋。"},{"en":"A clear value proposition helps customers understand why they should choose one company over another.","zh":"清晰價值主張幫助顧客理解為何應選擇一間公司而不是另一間。"},{"en":"This phrase explains what makes a business offer different and valuable.","zh":"這個短語解釋商業提案有何不同且有價值。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":17},{"front":"set of needs","meaning":"一組需要","examples":[{"en":"A value proposition is a set of needs a company can meet.","zh":"價值主張是公司能滿足的一組需要。"},{"en":"A set of needs means a group of related requirements or wants.","zh":"一組需要，是一系列相關要求或需求。"},{"en":"New parents may have a set of needs including childcare, medical advice, and affordable products.","zh":"新手父母可能有一組需要，包括托兒、醫療建議和可負擔產品。"},{"en":"Companies succeed when they understand a real set of customer needs clearly.","zh":"當公司清楚理解一組真實顧客需要，就能成功。"},{"en":"This phrase groups several needs together.","zh":"這個短語把幾項需要放在一起。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":17},{"front":"chosen customers","meaning":"選定顧客","examples":[{"en":"A company meets needs for its chosen customers.","zh":"公司滿足其選定顧客的需要。"},{"en":"Chosen customers are the specific group of customers a company decides to serve.","zh":"選定顧客是公司決定服務的特定顧客群。"},{"en":"A budget airline’s chosen customers may be travellers who care most about low prices.","zh":"廉航的選定顧客可能是最重視低價的旅客。"},{"en":"Knowing chosen customers helps a company design products, prices, and services more clearly.","zh":"了解選定顧客有助公司更清楚設計產品、價格和服務。"},{"en":"This phrase focuses on target customers, not everyone in the market.","zh":"這個短語聚焦目標顧客，而不是市場中所有人。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":17},{"front":"strategic CSR","meaning":"策略性企業社會責任","examples":[{"en":"The most strategic CSR adds a social dimension to the company’s value proposition.","zh":"最具策略性的企業社會責任為公司的價值主張加入社會層面。"},{"en":"Strategic CSR is corporate social responsibility that supports both social progress and the company’s core strategy.","zh":"策略性企業社會責任，是同時支持社會進步和公司核心策略的企業社會責任。"},{"en":"A food company uses strategic CSR when it improves farmer livelihoods and secures better ingredients.","zh":"食品公司改善農民生計並獲得更好食材時，就是使用策略性企業社會責任。"},{"en":"Strategic CSR lasts because it is connected to how the business competes and operates.","zh":"策略性企業社會責任能持久，因為它與企業如何競爭和營運相關。"},{"en":"This phrase contrasts deep CSR with one-off charity.","zh":"這個短語把深層企業社會責任與一次性慈善作對比。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":17},{"front":"add a social dimension to","meaning":"為……加入社會層面","examples":[{"en":"A company can add a social dimension to its value proposition.","zh":"公司可以為其價值主張加入社會層面。"},{"en":"To add a social dimension to something means to include social benefit as part of it.","zh":"為某事加入社會層面，是指把社會好處納入其中。"},{"en":"A bank adds a social dimension to its services when it helps low-income families manage money safely.","zh":"銀行幫助低收入家庭安全管理金錢時，就是為服務加入社會層面。"},{"en":"Adding a social dimension can make a product more meaningful to customers and communities.","zh":"加入社會層面可以令產品對顧客和社區更有意義。"},{"en":"This phrase connects business value with social value.","zh":"這個短語把商業價值與社會價值連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":17},{"front":"integral to","meaning":"對……不可或缺","examples":[{"en":"Social impact can become integral to the overall strategy.","zh":"社會影響可以成為整體策略不可或缺的一部分。"},{"en":"Integral to something means essential and built into it, not added as an extra.","zh":"對某事不可或缺，是指必不可少並內建其中，而不是額外添加。"},{"en":"Regular feedback is integral to effective language learning.","zh":"定期回饋對有效語言學習不可或缺。"},{"en":"CSR is stronger when social impact is integral to operations rather than separate from them.","zh":"當社會影響對營運不可或缺，而不是與營運分離，企業社會責任就更強。"},{"en":"This phrase describes something necessary to the whole system.","zh":"這個短語描述對整個系統必要的東西。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":17},{"front":"overall strategy","meaning":"整體策略","examples":[{"en":"Strategic CSR makes social impact part of the overall strategy.","zh":"策略性企業社會責任令社會影響成為整體策略的一部分。"},{"en":"Overall strategy is the broad plan that guides an organisation’s main decisions and direction.","zh":"整體策略是指導組織主要決策和方向的廣泛計劃。"},{"en":"A school’s overall strategy may focus on reading, wellbeing, and teacher training.","zh":"學校的整體策略可能集中於閱讀、福祉和教師培訓。"},{"en":"When CSR fits the overall strategy, it influences everyday decisions instead of sitting on the side.","zh":"當企業社會責任符合整體策略，它就會影響日常決定，而不是放在旁邊。"},{"en":"This phrase refers to the big plan, not one small action.","zh":"這個短語指大方向計劃，而不是一個小行動。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":17},{"front":"consider","meaning":"以……為例","examples":[{"en":"Consider Whole Foods Market as an example of strategic CSR.","zh":"以 Whole Foods Market 為策略性企業社會責任的例子。"},{"en":"Consider means think about or examine something as an example or possibility.","zh":"以某事為例，是指思考或檢視某事作為例子或可能性。"},{"en":"Consider the library system if you want to understand how public services support learning.","zh":"如果你想理解公共服務如何支持學習，可以以圖書館系統為例。"},{"en":"Writers use this word to invite readers to look closely at a case.","zh":"作者使用這個詞邀請讀者仔細看一個個案。"},{"en":"This verb often introduces evidence or illustration.","zh":"這個動詞常引入證據或例子。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":17},{"front":"organic, natural, and healthy food products","meaning":"有機、天然及健康食品","examples":[{"en":"Whole Foods sells organic, natural, and healthy food products.","zh":"Whole Foods 銷售有機、天然及健康食品。"},{"en":"Organic, natural, and healthy food products are foods marketed as cleaner, less processed, or better for wellbeing.","zh":"有機、天然及健康食品，是被定位為較潔淨、較少加工或較有益健康的食物。"},{"en":"A shop may sell organic vegetables, natural snacks, and healthy meal options.","zh":"店舖可能售賣有機蔬菜、天然小食和健康餐飲選項。"},{"en":"These products appeal to customers who care about diet, farming, and environmental effects.","zh":"這些產品吸引關心飲食、農業和環境影響的顧客。"},{"en":"This phrase describes a product category linked to health-conscious consumers.","zh":"這個短語描述與健康意識消費者相關的產品類別。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":17},{"front":"be passionate about","meaning":"對……充滿熱情","examples":[{"en":"Whole Foods serves customers who are passionate about food and the environment.","zh":"Whole Foods 服務對食物和環境充滿熱情的顧客。"},{"en":"To be passionate about something means to care about it deeply and enthusiastically.","zh":"對某事充滿熱情，是指深切且熱烈地關心它。"},{"en":"A student passionate about music may practise every day without being forced.","zh":"對音樂充滿熱情的學生可能每天練習，而不需要被迫。"},{"en":"Companies can build loyalty when they understand what their customers are passionate about.","zh":"當公司理解顧客對甚麼充滿熱情，就能建立忠誠。"},{"en":"This phrase describes strong interest and emotional commitment.","zh":"這個短語描述強烈興趣和情感投入。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":17},{"front":"sourcing","meaning":"採購","examples":[{"en":"The company’s sourcing emphasises purchases from local farmers.","zh":"該公司的採購強調向本地農民購買。"},{"en":"Sourcing is the process of finding and choosing suppliers for products or materials.","zh":"採購是尋找和選擇產品或材料供應商的過程。"},{"en":"A restaurant’s sourcing may focus on fresh vegetables from nearby farms.","zh":"餐廳的採購可能集中於附近農場的新鮮蔬菜。"},{"en":"Responsible sourcing can reduce environmental harm and support local communities.","zh":"負責任採購可以減少環境傷害並支持本地社區。"},{"en":"This word refers to where goods come from and how they are obtained.","zh":"這個詞指貨品來自哪裡以及如何取得。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":18},{"front":"local farmers","meaning":"本地農民","examples":[{"en":"Whole Foods buys from local farmers through each store’s procurement process.","zh":"Whole Foods 透過每間店的採購流程向本地農民購買。"},{"en":"Local farmers are farmers who grow food near the area where it is sold or used.","zh":"本地農民是在食物銷售或使用地區附近種植食物的農民。"},{"en":"A market supports local farmers when it sells vegetables grown in nearby villages.","zh":"街市售賣附近村莊種植的蔬菜時，就是支持本地農民。"},{"en":"Buying from local farmers can reduce transport distance and keep money in the community.","zh":"向本地農民購買可以減少運輸距離，並把金錢留在社區。"},{"en":"This phrase connects food supply with place and community.","zh":"這個短語把食物供應與地方和社區連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":18},{"front":"procurement process","meaning":"採購流程","examples":[{"en":"Each store has a procurement process for buying food.","zh":"每間店都有購買食物的採購流程。"},{"en":"A procurement process is the organised method a company uses to buy goods or services.","zh":"採購流程是公司用來購買貨品或服務的有組織方法。"},{"en":"A school’s procurement process may require comparing prices before buying new computers.","zh":"學校的採購流程可能要求在購買新電腦前比較價格。"},{"en":"A clear procurement process helps prevent waste, poor quality, and unfair supplier choices.","zh":"清晰採購流程有助防止浪費、質素差和不公平供應商選擇。"},{"en":"This phrase describes formal buying procedures.","zh":"這個短語描述正式購買程序。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":18},{"front":"screen out","meaning":"篩走；剔除","examples":[{"en":"Buyers screen out foods containing unhealthy ingredients.","zh":"採購人員篩走含有不健康成分的食物。"},{"en":"To screen out something means to remove or reject it after checking.","zh":"篩走某物，是指檢查後移除或拒絕它。"},{"en":"A teacher may screen out unsuitable websites before giving students a research list.","zh":"老師可能在給學生研究清單前篩走不合適網站。"},{"en":"Screening out unsafe products protects customers before goods reach the shelves.","zh":"在貨品上架前篩走不安全產品，可以保護顧客。"},{"en":"This phrase describes filtering by standards.","zh":"這個短語描述按標準過濾。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":18},{"front":"common ingredients","meaning":"常見成分","examples":[{"en":"Whole Foods screens out nearly 100 common ingredients.","zh":"Whole Foods 篩走近 100 種常見成分。"},{"en":"Common ingredients are substances often used in many foods or products.","zh":"常見成分是許多食物或產品中經常使用的物質。"},{"en":"Sugar, salt, flour, and cooking oil are common ingredients in many kitchens.","zh":"糖、鹽、麵粉和食油是許多廚房中的常見成分。"},{"en":"A company may reject common ingredients if it believes they are unhealthy or harmful.","zh":"如果公司認為常見成分不健康或有害，可能拒絕使用它們。"},{"en":"This phrase refers to frequently used components.","zh":"這個短語指常用組成部分。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":18},{"front":"environmentally damaging","meaning":"破壞環境的","examples":[{"en":"The company avoids ingredients it considers environmentally damaging.","zh":"該公司避免使用它認為破壞環境的成分。"},{"en":"Environmentally damaging means harmful to nature, ecosystems, or natural resources.","zh":"破壞環境的，是指對自然、生態系統或自然資源有害。"},{"en":"A cleaning chemical may be environmentally damaging if it poisons rivers after use.","zh":"如果清潔化學品使用後毒害河流，它可能是破壞環境的。"},{"en":"Avoiding damaging materials can reduce pollution and protect wildlife.","zh":"避免使用有害材料可以減少污染並保護野生動物。"},{"en":"This phrase describes harm to the environment, not only to people.","zh":"這個短語描述對環境的傷害，而不只是對人的傷害。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":18},{"front":"apply to","meaning":"適用於","examples":[{"en":"The same standards apply to products made internally.","zh":"相同標準適用於內部製造的產品。"},{"en":"To apply to something means to be relevant to it or be used for it.","zh":"適用於某事，是指與它相關或用於它。"},{"en":"School safety rules apply to students, teachers, and visitors.","zh":"學校安全規則適用於學生、老師和訪客。"},{"en":"If standards apply to all products, companies cannot avoid responsibility by changing where items are made.","zh":"如果標準適用於所有產品，公司就不能透過改變製造地點來逃避責任。"},{"en":"This phrase shows where a rule or standard is used.","zh":"這個短語顯示規則或標準用在哪裡。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":18},{"front":"made internally","meaning":"內部製造的","examples":[{"en":"The standards apply to products made internally.","zh":"這些標準適用於內部製造的產品。"},{"en":"Made internally means produced inside the company rather than bought from outside suppliers.","zh":"內部製造的，是指由公司內部生產，而不是從外部供應商購買。"},{"en":"A bakery’s cakes made internally may follow the shop’s own quality rules.","zh":"麵包店內部製造的蛋糕可能遵循店舖自己的品質規則。"},{"en":"Internal production still needs standards because a company is responsible for what it sells.","zh":"內部生產仍需要標準，因為公司要對自己銷售的東西負責。"},{"en":"This phrase contrasts in-house production with external sourcing.","zh":"這個短語把內部生產與外部採購作對比。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":18},{"front":"commitment to","meaning":"對……的承諾","examples":[{"en":"Whole Foods’ commitment to environmentally friendly practices extends widely.","zh":"Whole Foods 對環保做法的承諾延伸很廣。"},{"en":"Commitment to something means serious, continuing support for it.","zh":"對某事的承諾，是對它認真且持續的支持。"},{"en":"A school shows commitment to reading when it gives students daily library time.","zh":"學校每天給學生圖書館時間，就是展示對閱讀的承諾。"},{"en":"Commitment is shown through repeated action, not only words.","zh":"承諾透過反覆行動顯示，而不只是說話。"},{"en":"This phrase describes dedication to a principle or goal.","zh":"這個短語描述對原則或目標的投入。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":18},{"front":"environmentally friendly operating practices","meaning":"環保營運做法","examples":[{"en":"The company uses environmentally friendly operating practices.","zh":"該公司使用環保營運做法。"},{"en":"Environmentally friendly operating practices are business methods that reduce harm to nature during daily operations.","zh":"環保營運做法，是在日常營運中減少對自然傷害的商業方法。"},{"en":"A shop uses environmentally friendly operating practices when it saves energy and reduces plastic packaging.","zh":"商店節省能源並減少塑膠包裝時，就是使用環保營運做法。"},{"en":"Such practices can lower waste, improve reputation, and reduce long-term costs.","zh":"這些做法可以減少浪費、改善聲譽並降低長期成本。"},{"en":"This phrase refers to how a company runs, not only what it sells.","zh":"這個短語指公司如何營運，而不只是銷售甚麼。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":18},{"front":"extend well beyond","meaning":"遠遠超出……","examples":[{"en":"Whole Foods’ commitment extends well beyond sourcing.","zh":"Whole Foods 的承諾遠遠超出採購。"},{"en":"To extend well beyond something means to go much further than that area or limit.","zh":"遠遠超出某事，是指範圍遠比該領域或限制更廣。"},{"en":"Good student support extends well beyond exam preparation to include confidence and mental health.","zh":"良好學生支援遠遠超出考試準備，還包括信心和心理健康。"},{"en":"A company’s environmental work is stronger when it extends beyond purchasing into transport, waste, and energy use.","zh":"當公司環境工作超越採購並進入運輸、廢物和能源使用，它就更強。"},{"en":"This phrase shows that the scope is much wider than one part.","zh":"這個短語顯示範圍遠比一部分更廣。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":18},{"front":"virgin raw materials","meaning":"原生原材料","examples":[{"en":"Stores are constructed using a minimum of virgin raw materials.","zh":"店舖建造時使用最少原生原材料。"},{"en":"Virgin raw materials are new natural materials that have not been used or recycled before.","zh":"原生原材料是未曾使用或回收過的新天然材料。"},{"en":"A notebook made from recycled paper uses fewer virgin raw materials.","zh":"由再造紙製成的筆記簿使用較少原生原材料。"},{"en":"Reducing virgin raw materials can protect forests, minerals, and other natural resources.","zh":"減少原生原材料可以保護森林、礦物和其他自然資源。"},{"en":"This phrase contrasts new materials with reused or recycled materials.","zh":"這個短語把新材料與再用或回收材料作對比。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":19},{"front":"renewable wind energy credits","meaning":"可再生風能憑證","examples":[{"en":"The company purchased renewable wind energy credits.","zh":"該公司購買了可再生風能憑證。"},{"en":"Renewable wind energy credits are certificates showing that electricity has been generated from wind power.","zh":"可再生風能憑證是顯示電力由風力發電產生的證書。"},{"en":"A company may buy renewable wind energy credits to support clean electricity production.","zh":"公司可能購買可再生風能憑證來支持清潔電力生產。"},{"en":"These credits can help offset electricity use by funding renewable power.","zh":"這些憑證可以透過資助可再生電力來抵銷用電。"},{"en":"This phrase connects corporate energy use with clean-energy support.","zh":"這個短語把企業能源使用與清潔能源支持連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":19},{"front":"electricity use","meaning":"用電量","examples":[{"en":"The credits equal 100% of the company’s electricity use.","zh":"這些憑證等於該公司 100% 的用電量。"},{"en":"Electricity use is the amount of electrical power consumed by a person, building, or company.","zh":"用電量是個人、建築物或公司消耗的電力數量。"},{"en":"A school’s electricity use rises when air conditioners run all day.","zh":"當冷氣整天運行，學校用電量會上升。"},{"en":"Reducing electricity use can lower bills and reduce environmental impact.","zh":"減少用電量可以降低帳單並減少環境影響。"},{"en":"This phrase measures energy consumption.","zh":"這個短語量度能源消耗。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":19},{"front":"Fortune 500 company","meaning":"財富 500 強公司","examples":[{"en":"Whole Foods was the only Fortune 500 company to offset all electricity use.","zh":"Whole Foods 是唯一抵銷全部用電量的財富 500 強公司。"},{"en":"A Fortune 500 company is one of the 500 largest U.S. companies ranked by revenue in Fortune magazine.","zh":"財富 500 強公司是《財富》雜誌按收入排名的美國 500 間最大公司之一。"},{"en":"A Fortune 500 company usually has large operations, many employees, and strong public visibility.","zh":"財富 500 強公司通常有大型營運、許多員工和高公眾能見度。"},{"en":"When a Fortune 500 company changes its practices, other companies may notice and follow.","zh":"當財富 500 強公司改變做法，其他公司可能注意並跟隨。"},{"en":"This phrase signals a large and influential business.","zh":"這個短語表示大型且有影響力的企業。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":19},{"front":"offset its electricity consumption","meaning":"抵銷其用電量","examples":[{"en":"The company offsets its electricity consumption entirely.","zh":"該公司完全抵銷其用電量。"},{"en":"To offset electricity consumption means to balance electricity use by supporting renewable energy or reducing equivalent emissions.","zh":"抵銷用電量，是指透過支持可再生能源或減少等量排放來平衡用電。"},{"en":"A school may offset its electricity consumption by buying solar power credits.","zh":"學校可以透過購買太陽能電力憑證來抵銷用電量。"},{"en":"Offsetting does not always mean using no electricity; it means balancing its impact in another way.","zh":"抵銷不一定代表完全不用電；它表示以另一方式平衡其影響。"},{"en":"This phrase connects energy use with compensation or balancing action.","zh":"這個短語把能源使用與補償或平衡行動連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":19},{"front":"spoiled produce","meaning":"腐壞農產品","examples":[{"en":"Spoiled produce is sent to regional centres for composting.","zh":"腐壞農產品被送往區域中心堆肥。"},{"en":"Spoiled produce is fruit, vegetables, or other fresh food that has gone bad and cannot be sold.","zh":"腐壞農產品是已變壞並不能出售的水果、蔬菜或其他新鮮食物。"},{"en":"A supermarket may remove spoiled produce from shelves before customers buy it.","zh":"超市可能在顧客購買前把腐壞農產品從貨架移走。"},{"en":"Sending spoiled produce for composting reduces waste and creates useful soil material.","zh":"把腐壞農產品送去堆肥能減少浪費並製造有用土壤材料。"},{"en":"This phrase refers to fresh food that is no longer fit for sale or eating.","zh":"這個短語指不再適合出售或食用的新鮮食物。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":19},{"front":"biodegradable waste","meaning":"可生物降解廢物","examples":[{"en":"Biodegradable waste is trucked to regional centres.","zh":"可生物降解廢物被貨車運送到區域中心。"},{"en":"Biodegradable waste is waste that can naturally break down through bacteria, fungi, or other living processes.","zh":"可生物降解廢物是能透過細菌、真菌或其他生命過程自然分解的廢物。"},{"en":"Fruit peels, paper napkins, and garden leaves can be biodegradable waste.","zh":"果皮、紙巾和花園落葉都可以是可生物降解廢物。"},{"en":"Composting biodegradable waste reduces landfill pressure and returns nutrients to soil.","zh":"堆肥可生物降解廢物能減少堆填區壓力並把養分還給泥土。"},{"en":"This phrase refers to waste that nature can decompose.","zh":"這個短語指自然可以分解的廢物。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":19},{"front":"be trucked to","meaning":"被貨車運送到……","examples":[{"en":"Waste is trucked to regional centres for composting.","zh":"廢物被貨車運送到區域中心堆肥。"},{"en":"To be trucked to a place means to be transported there by truck.","zh":"被貨車運送到某地，是指由貨車運到那裡。"},{"en":"School supplies may be trucked to rural areas before the new term starts.","zh":"新學期開始前，學校用品可能被貨車運送到鄉郊地區。"},{"en":"Trucking waste to processing centres can reduce what goes directly to landfill.","zh":"把廢物用貨車運到處理中心，可以減少直接進入堆填區的量。"},{"en":"This phrase describes transport by road vehicle.","zh":"這個短語描述以道路車輛運輸。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":19},{"front":"regional centres","meaning":"區域中心","examples":[{"en":"Spoiled produce is taken to regional centres.","zh":"腐壞農產品被帶到區域中心。"},{"en":"Regional centres are facilities or locations serving a wider area within a region.","zh":"區域中心是服務某一區域較大範圍的設施或地點。"},{"en":"A recycling company may send waste from several shops to one regional centre.","zh":"回收公司可能把幾間店舖的廢物送到一個區域中心。"},{"en":"Regional centres make processing more efficient because materials from many places are gathered together.","zh":"區域中心令處理更有效率，因為來自多地的材料被集中在一起。"},{"en":"This phrase refers to central facilities for a particular area.","zh":"這個短語指某區域的中心設施。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":19},{"front":"composting","meaning":"堆肥","examples":[{"en":"Biodegradable waste is sent for composting.","zh":"可生物降解廢物被送去堆肥。"},{"en":"Composting is the process of turning organic waste into soil-like material for plants.","zh":"堆肥是把有機廢物變成類似泥土、可供植物使用材料的過程。"},{"en":"A family can do composting with vegetable peels, leaves, and coffee grounds.","zh":"家庭可以用菜皮、落葉和咖啡渣進行堆肥。"},{"en":"Composting reduces waste and creates nutrients for gardens and farms.","zh":"堆肥能減少廢物並為花園和農場製造養分。"},{"en":"This word describes a natural recycling process.","zh":"這個詞描述自然回收過程。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":19},{"front":"be converted to run on","meaning":"被改裝成以……運行","examples":[{"en":"Whole Foods’ vehicles are being converted to run on biofuels.","zh":"Whole Foods 的車輛正被改裝成以生物燃料運行。"},{"en":"To be converted to run on something means to be changed so that it can use a different fuel or power source.","zh":"被改裝成以某物運行，是指被改變以使用不同燃料或能源。"},{"en":"A bus may be converted to run on electricity instead of diesel.","zh":"巴士可能被改裝成以電力而非柴油運行。"},{"en":"Converting vehicles can reduce pollution if the new fuel is cleaner.","zh":"如果新燃料較清潔，改裝車輛可以減少污染。"},{"en":"This phrase describes changing how a machine is powered.","zh":"這個短語描述改變機器的供能方式。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":19},{"front":"biofuels","meaning":"生物燃料","examples":[{"en":"Whole Foods is converting its vehicles to run on biofuels.","zh":"Whole Foods 正把其車輛改裝成使用生物燃料。"},{"en":"Biofuels are fuels made from biological materials such as plants, waste oil, or organic matter.","zh":"生物燃料是由植物、廢食油或有機物等生物材料製成的燃料。"},{"en":"Some buses use biofuels made from used cooking oil.","zh":"有些巴士使用由廢食油製成的生物燃料。"},{"en":"Biofuels can reduce dependence on fossil fuels, though their benefits depend on how they are produced.","zh":"生物燃料可以減少對化石燃料的依賴，但其好處取決於生產方式。"},{"en":"This word refers to fuel from living or once-living materials.","zh":"這個詞指來自生物或曾經有生命材料的燃料。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":20},{"front":"cleaning products","meaning":"清潔用品","examples":[{"en":"The cleaning products used in its stores are environmentally friendly.","zh":"其店舖使用的清潔用品是環保的。"},{"en":"Cleaning products are substances used to wash, disinfect, or remove dirt.","zh":"清潔用品是用來清洗、消毒或去除污垢的物質。"},{"en":"A school uses cleaning products to keep classrooms, toilets, and kitchens safe.","zh":"學校使用清潔用品保持課室、廁所和廚房安全。"},{"en":"Harsh cleaning products can harm health or water systems if used carelessly.","zh":"如果粗心使用，強烈清潔用品會傷害健康或水系統。"},{"en":"This phrase refers to practical products used for hygiene and cleanliness.","zh":"這個短語指用於衛生和清潔的實用產品。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":20},{"front":"through its philanthropy","meaning":"透過其慈善工作","examples":[{"en":"Through its philanthropy, the company created the Animal Compassion Foundation.","zh":"該公司透過其慈善工作成立了動物關懷基金會。"},{"en":"Through its philanthropy means by using its charitable giving, support, or social-benefit work.","zh":"透過其慈善工作，是指使用其慈善捐助、支援或社會公益工作。"},{"en":"A company may help poor students through its philanthropy by funding scholarships.","zh":"公司可以透過其慈善工作資助獎學金，幫助貧困學生。"},{"en":"Philanthropy can create social value when it supports causes with real needs.","zh":"當慈善工作支持有真實需要的理念，它可以創造社會價值。"},{"en":"This phrase explains the charitable route through which an action happens.","zh":"這個短語解釋行動透過哪條慈善途徑發生。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":20},{"front":"Animal Compassion Foundation","meaning":"動物關懷基金會","examples":[{"en":"The Animal Compassion Foundation promotes humane farming methods.","zh":"動物關懷基金會推動人道農業方法。"},{"en":"The Animal Compassion Foundation is a foundation connected with improving the treatment of farm animals.","zh":"動物關懷基金會是一個與改善農場動物待遇相關的基金會。"},{"en":"A foundation like this may fund research into better living conditions for chickens, pigs, or cattle.","zh":"這類基金會可能資助研究雞、豬或牛的更好生活環境。"},{"en":"It supports CSR by connecting food retail with animal welfare standards.","zh":"它透過把食品零售與動物福利標準連接起來支持企業社會責任。"},{"en":"This phrase names a specific organisation created for animal welfare.","zh":"這個短語命名一個為動物福利而設的特定組織。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":20},{"front":"humane ways of raising farm animals","meaning":"更人道的飼養農場動物方式","examples":[{"en":"The foundation develops more humane ways of raising farm animals.","zh":"該基金會發展更人道的飼養農場動物方式。"},{"en":"Humane ways of raising farm animals are methods that reduce suffering and treat animals with care.","zh":"更人道的飼養農場動物方式，是減少痛苦並細心對待動物的方法。"},{"en":"Giving animals enough space, clean water, and proper food can be part of humane farming.","zh":"給動物足夠空間、清潔食水和合適食物，可以是人道飼養的一部分。"},{"en":"Humane methods matter because food production can harm animals if profit is the only concern.","zh":"人道方法很重要，因為如果利潤是唯一考慮，食品生產會傷害動物。"},{"en":"This phrase connects farming with animal welfare.","zh":"這個短語把農業與動物福利連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":20},{"front":"in short","meaning":"簡而言之","examples":[{"en":"In short, nearly every aspect of the value chain supports the strategy.","zh":"簡而言之，價值鏈的幾乎每一方面都支持該策略。"},{"en":"In short means briefly or to summarise the main point.","zh":"簡而言之，是指簡短地說或總結主要重點。"},{"en":"In short, the project failed because it had no clear goal and no budget.","zh":"簡而言之，該項目失敗是因為沒有清晰目標和預算。"},{"en":"This phrase helps close a detailed explanation with a simple conclusion.","zh":"這個短語幫助以簡單結論結束詳細解釋。"},{"en":"It signals that the writer is reducing many details to one key idea.","zh":"它表示作者正把許多細節縮減成一個關鍵想法。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":20},{"front":"every aspect of","meaning":"……的每一方面","examples":[{"en":"Nearly every aspect of the value chain reinforces the social dimension.","zh":"價值鏈的幾乎每一方面都加強社會層面。"},{"en":"Every aspect of something means all or almost all parts of it.","zh":"某事的每一方面，是指它的所有或幾乎所有部分。"},{"en":"A good school improvement plan considers every aspect of student life, from lessons to wellbeing.","zh":"良好學校改善計劃會考慮學生生活的每一方面，從課堂到福祉。"},{"en":"When every aspect of a business supports one goal, the strategy feels consistent.","zh":"當企業每一方面都支持同一目標，策略就感覺一致。"},{"en":"This phrase stresses completeness across many parts.","zh":"這個短語強調多個部分中的完整性。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":20},{"front":"value chain","meaning":"價值鏈","examples":[{"en":"Whole Foods’ value chain reinforces its social values.","zh":"Whole Foods 的價值鏈加強其社會價值。"},{"en":"A value chain is the full series of activities that create, produce, deliver, and support a product or service.","zh":"價值鏈是創造、生產、交付和支援產品或服務的完整活動系列。"},{"en":"A restaurant’s value chain includes sourcing ingredients, cooking food, serving customers, and handling waste.","zh":"餐廳的價值鏈包括採購食材、烹調食物、服務顧客和處理廢物。"},{"en":"CSR is stronger when the value chain itself supports the company’s social goals.","zh":"當價值鏈本身支持公司的社會目標，企業社會責任會更強。"},{"en":"This phrase helps analyse where value and impact are created.","zh":"這個短語幫助分析價值和影響在哪裡被創造。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":20},{"front":"reinforce","meaning":"加強","examples":[{"en":"The company’s practices reinforce the social dimensions of its strategy.","zh":"公司的做法加強其策略的社會層面。"},{"en":"To reinforce something means to strengthen it or support it more firmly.","zh":"加強某事，是指使它更強或更穩固地支持它。"},{"en":"Extra reading practice can reinforce vocabulary learned in class.","zh":"額外閱讀練習可以加強課堂上學到的詞彙。"},{"en":"Business practices reinforce CSR when daily operations match social promises.","zh":"當日常營運配合社會承諾，商業做法就會加強企業社會責任。"},{"en":"This verb describes making something stronger and more consistent.","zh":"這個動詞描述令某事更強和更一致。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":20},{"front":"distinguish A from B","meaning":"使 A 有別於 B","examples":[{"en":"Whole Foods’ CSR approach distinguishes it from its competitors.","zh":"Whole Foods 的企業社會責任方法使它有別於競爭對手。"},{"en":"To distinguish A from B means to make A clearly different from B.","zh":"使 A 有別於 B，是指令 A 與 B 清楚不同。"},{"en":"Personal feedback can distinguish one tutoring centre from another.","zh":"個人化回饋可以使一間補習中心有別於另一間。"},{"en":"A company stands out when its practices distinguish it from similar businesses.","zh":"當公司的做法使其有別於類似企業，它就會突出。"},{"en":"This phrase focuses on difference and identity.","zh":"這個短語聚焦差異和身份。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":20},{"front":"competitors","meaning":"競爭對手","examples":[{"en":"Whole Foods distinguishes itself from its competitors through CSR.","zh":"Whole Foods 透過企業社會責任使自己有別於競爭對手。"},{"en":"Competitors are other businesses that sell similar products or services to the same customers.","zh":"競爭對手是向相同顧客銷售類似產品或服務的其他企業。"},{"en":"Two cafés on the same street are competitors if they try to attract the same lunch crowd.","zh":"同一條街上的兩間咖啡店如果都想吸引同一批午餐顧客，就是競爭對手。"},{"en":"Companies study competitors to understand how they can offer something better or different.","zh":"公司研究競爭對手，以了解自己如何提供更好或不同的東西。"},{"en":"This word refers to rivals in the market.","zh":"這個詞指市場中的對手。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":20},{"front":"choose the correct heading","meaning":"選出正確小標題","examples":[{"en":"Students must choose the correct heading for each paragraph.","zh":"學生必須為每段選出正確小標題。"},{"en":"To choose the correct heading means to select the title that best summarises a paragraph.","zh":"選出正確小標題，是指選擇最能概括段落的標題。"},{"en":"In IELTS reading, students choose headings by identifying the main idea, not just matching words.","zh":"在 IELTS 閱讀中，學生透過識別主旨選標題，而不是只配對字眼。"},{"en":"Choosing the wrong heading often happens when students focus on one detail instead of the whole paragraph.","zh":"當學生只集中於一個細節而不是整段時，常會選錯標題。"},{"en":"This phrase is a common reading-test instruction.","zh":"這個短語是常見閱讀測驗指示。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":21},{"front":"list of headings","meaning":"小標題列表","examples":[{"en":"The list of headings gives possible paragraph summaries.","zh":"小標題列表給出可能的段落摘要。"},{"en":"A list of headings is a set of possible titles for paragraphs or sections.","zh":"小標題列表是一組可作為段落或章節標題的選項。"},{"en":"Students may compare each paragraph with the list of headings before choosing an answer.","zh":"學生可能先把每段與小標題列表比較，再選答案。"},{"en":"The list can include distractors that sound relevant but do not match the main idea.","zh":"列表可能包括聽起來相關但不符合主旨的干擾項。"},{"en":"This phrase refers to answer choices in a heading-matching task.","zh":"這個短語指標題配對題中的答案選項。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":21},{"front":"help a business expand","meaning":"幫助企業擴展","examples":[{"en":"One heading asks how CSR can help a business expand.","zh":"一個小標題問企業社會責任如何幫助企業擴展。"},{"en":"To help a business expand means to support its growth into more customers, markets, products, or locations.","zh":"幫助企業擴展，是指支持它在顧客、市場、產品或地點方面增長。"},{"en":"Better staff training can help a business expand because it prepares workers for more demand.","zh":"更好員工培訓可以幫助企業擴展，因為它讓員工準備好應對更多需求。"},{"en":"CSR can help expansion when it builds trust and improves the business environment.","zh":"當企業社會責任建立信任並改善營商環境，它可以幫助擴展。"},{"en":"This phrase connects support with business growth.","zh":"這個短語把支援與企業增長連接起來。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":21},{"front":"throughout many aspects of","meaning":"貫穿……的許多方面","examples":[{"en":"CSR can appear throughout many aspects of a company’s operations.","zh":"企業社會責任可以貫穿公司營運的許多方面。"},{"en":"Throughout many aspects of something means across many different parts of it.","zh":"貫穿某事的許多方面，是指橫跨其許多不同部分。"},{"en":"Technology can improve learning throughout many aspects of school life, from homework to feedback.","zh":"科技可以貫穿學校生活許多方面改善學習，從功課到回饋。"},{"en":"When CSR appears across many operations, it becomes part of the company’s identity.","zh":"當企業社會責任出現在許多營運環節，它就成為公司身份的一部分。"},{"en":"This phrase stresses wide coverage rather than one isolated action.","zh":"這個短語強調廣泛覆蓋，而不是孤立行動。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":21},{"front":"company’s operations","meaning":"公司營運","examples":[{"en":"Whole Foods applies CSR across its company’s operations.","zh":"Whole Foods 把企業社會責任應用於其公司營運之中。"},{"en":"A company’s operations are the daily activities needed to run the business.","zh":"公司營運是經營企業所需的日常活動。"},{"en":"A delivery company’s operations include receiving orders, managing warehouses, and transporting goods.","zh":"速遞公司的營運包括接收訂單、管理倉庫和運輸貨物。"},{"en":"CSR affects operations when it changes sourcing, energy use, waste, and employee practices.","zh":"當企業社會責任改變採購、能源使用、廢物和員工做法，它就影響營運。"},{"en":"This phrase refers to how a business actually works day to day.","zh":"這個短語指企業日常實際如何運作。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":21},{"front":"direct financial gain","meaning":"直接財務收益","examples":[{"en":"Some CSR initiatives produce little direct financial gain.","zh":"有些企業社會責任措施產生很少直接財務收益。"},{"en":"Direct financial gain is clear money-related benefit, such as higher sales, lower costs, or increased profit.","zh":"直接財務收益是清楚與金錢相關的好處，例如銷售增加、成本降低或利潤提高。"},{"en":"A company may sponsor a community event even if it brings little direct financial gain.","zh":"公司可能贊助社區活動，即使它帶來很少直接財務收益。"},{"en":"Some actions create goodwill or social value before they create measurable profit.","zh":"有些行動在創造可量度利潤前，先建立好感或社會價值。"},{"en":"This phrase separates immediate money benefit from broader value.","zh":"這個短語把即時金錢好處與更廣泛價值分開。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":21},{"front":"government inaction","meaning":"政府不作為","examples":[{"en":"One heading refers to government inaction on social issues.","zh":"一個小標題提到政府在社會議題上的不作為。"},{"en":"Government inaction means the government does not take enough action to deal with a problem.","zh":"政府不作為，是指政府沒有採取足夠行動處理問題。"},{"en":"Residents may complain about government inaction if dangerous roads are ignored for years.","zh":"如果危險道路多年被忽視，居民可能投訴政府不作為。"},{"en":"When governments fail to act, businesses or charities may feel pressure to help.","zh":"當政府未能行動，企業或慈善機構可能感到壓力去幫忙。"},{"en":"This phrase describes absence of public action.","zh":"這個短語描述公共行動缺失。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":21},{"front":"motivate companies to","meaning":"推動公司去……","examples":[{"en":"Several drivers motivate companies to address CSR.","zh":"幾項驅動因素推動公司處理企業社會責任。"},{"en":"To motivate companies to do something means to give them reasons or pressure to act.","zh":"推動公司做某事，是指給予它們行動的理由或壓力。"},{"en":"Customer complaints may motivate companies to improve product safety.","zh":"顧客投訴可能推動公司改善產品安全。"},{"en":"Companies are motivated when action can protect reputation, reduce risk, or create value.","zh":"當行動能保護聲譽、降低風險或創造價值，公司就會受推動。"},{"en":"This phrase explains what pushes businesses toward action.","zh":"這個短語解釋甚麼促使企業行動。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":21},{"front":"address CSR","meaning":"處理企業社會責任","examples":[{"en":"Companies address CSR for moral, social and reputational reasons.","zh":"公司因道德、社會和聲譽原因處理企業社會責任。"},{"en":"To address CSR means to deal with corporate social responsibility through policies, actions, or programmes.","zh":"處理企業社會責任，是指透過政策、行動或計劃應對企業社會責任。"},{"en":"A company addresses CSR when it improves worker safety and reduces waste.","zh":"公司改善員工安全並減少浪費時，就是在處理企業社會責任。"},{"en":"Addressing CSR can prevent reputational damage and create stronger community relationships.","zh":"處理企業社會責任可以防止聲譽損害，並建立更強社區關係。"},{"en":"This phrase focuses on taking CSR seriously in practice.","zh":"這個短語聚焦在實踐中認真對待企業社會責任。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":21},{"front":"future outcomes","meaning":"未來後果","examples":[{"en":"The asbestos example shows that businesses are responsible for future outcomes.","zh":"石棉例子顯示企業要為未來後果負責。"},{"en":"Future outcomes are results or consequences that will appear later.","zh":"未來後果是之後才會出現的結果或影響。"},{"en":"A school that cuts reading lessons may not see future outcomes until students struggle in higher grades.","zh":"削減閱讀課的學校，可能直到學生在高年級吃力時才看見未來後果。"},{"en":"Companies must consider future outcomes because today’s choices can create tomorrow’s risks.","zh":"公司必須考慮未來後果，因為今日選擇會創造明日風險。"},{"en":"This phrase focuses on later consequences.","zh":"這個短語聚焦之後的後果。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":21},{"front":"be selective","meaning":"有選擇性","examples":[{"en":"Companies applying CSR should be selective about social issues.","zh":"實施企業社會責任的公司應對社會議題有選擇性。"},{"en":"To be selective means to choose carefully rather than accept everything.","zh":"有選擇性，是指仔細選擇，而不是接受所有東西。"},{"en":"A student should be selective about online sources when writing a research essay.","zh":"學生寫研究文章時，應對網上資料來源有選擇性。"},{"en":"Being selective helps companies focus on issues they can genuinely influence.","zh":"有選擇性幫助公司聚焦於真正能影響的議題。"},{"en":"This phrase describes careful choice and prioritisation.","zh":"這個短語描述謹慎選擇和優先排序。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":21},{"front":"benefit one another","meaning":"互相受益","examples":[{"en":"Business and society benefit one another.","zh":"企業和社會互相受益。"},{"en":"To benefit one another means two sides both help each other.","zh":"互相受益，是指雙方都幫助對方。"},{"en":"Schools and families benefit one another when teachers share guidance and parents support learning at home.","zh":"當老師分享指引，而家長在家支持學習，學校和家庭就互相受益。"},{"en":"Business benefits society by creating jobs, while society benefits business by providing educated workers and stable markets.","zh":"企業透過創造工作令社會受益，而社會透過提供受教育員工和穩定市場令企業受益。"},{"en":"This phrase describes mutual advantage.","zh":"這個短語描述互惠。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":22},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用篇章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill missing words in the short text that follows.","zh":"完成以下摘要，是指填寫接下來短文中的缺失字詞。"},{"en":"In a reading test, students complete a summary by finding exact information in the passage.","zh":"在閱讀測驗中，學生透過在篇章中找出準確資料完成摘要。"},{"en":"This task checks whether students understand the main ideas and key details.","zh":"這項任務檢查學生是否理解主旨和關鍵細節。"},{"en":"The phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":22},{"front":"no more than two words","meaning":"不超過兩個詞","examples":[{"en":"Each answer should contain no more than two words.","zh":"每個答案應不超過兩個詞。"},{"en":"No more than two words means the answer can have one or two words, but not three.","zh":"不超過兩個詞，是指答案可以有一個或兩個詞，但不能有三個。"},{"en":"If the instruction says no more than two words, “social consequences” is acceptable but “serious social consequences” is not.","zh":"如果指示說不超過兩個詞，“social consequences” 可以，但 “serious social consequences” 不可以。"},{"en":"Word limits force students to copy only the necessary words from the passage.","zh":"字數限制迫使學生只從篇章抄寫必要字詞。"},{"en":"This phrase gives a strict answer-length rule.","zh":"這個短語給出嚴格答案長度規則。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":22},{"front":"implementing CSR","meaning":"實施企業社會責任","examples":[{"en":"Implementing CSR requires understanding business and society together.","zh":"實施企業社會責任需要同時理解企業和社會。"},{"en":"Implementing CSR means putting corporate social responsibility into real policies and actions.","zh":"實施企業社會責任，是把企業社會責任轉化成真實政策和行動。"},{"en":"A company implements CSR when it changes purchasing rules, trains staff, and measures social impact.","zh":"公司改變採購規則、培訓員工並量度社會影響時，就是實施企業社會責任。"},{"en":"Implementation matters because CSR ideas have little value if they never affect behaviour.","zh":"實施很重要，因為企業社會責任理念如果從不影響行為，就價值不大。"},{"en":"This phrase focuses on turning CSR principles into practice.","zh":"這個短語聚焦把企業社會責任原則變成實踐。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":22},{"front":"interdependence between","meaning":"……之間的相互依賴","examples":[{"en":"CSR requires understanding the interdependence between business and society.","zh":"企業社會責任需要理解企業與社會之間的相互依賴。"},{"en":"Interdependence between two things means they rely on and affect each other.","zh":"兩者之間的相互依賴，是指它們互相依靠並互相影響。"},{"en":"The interdependence between teachers and students means both sides shape classroom success.","zh":"老師和學生之間的相互依賴，是指雙方都塑造課堂成功。"},{"en":"Business and society are interdependent because companies need healthy communities and communities need jobs.","zh":"企業和社會相互依賴，因為公司需要健康社區，而社區需要工作。"},{"en":"This phrase describes mutual dependence.","zh":"這個短語描述互相依靠。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":22},{"front":"imposed by","meaning":"由……施加","examples":[{"en":"Regulations imposed by governments and companies protect consumers.","zh":"由政府和公司施加的規例保護消費者。"},{"en":"Imposed by someone means officially set or forced by that person or authority.","zh":"由某人施加，是指由該人或權力機構正式設定或強制執行。"},{"en":"Rules imposed by a school may require students to wear safety glasses in science labs.","zh":"學校施加的規則可能要求學生在科學實驗室佩戴安全眼鏡。"},{"en":"Regulations are imposed to prevent harm, create order, or protect rights.","zh":"規例被施加，是為了防止傷害、建立秩序或保護權利。"},{"en":"This phrase identifies who creates or enforces a rule.","zh":"這個短語指出誰創造或執行規則。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":22},{"front":"unfair treatment","meaning":"不公平對待","examples":[{"en":"Regulations protect consumers from unfair treatment.","zh":"規例保護消費者免受不公平對待。"},{"en":"Unfair treatment means treating people in a way that is unjust, dishonest, or unequal.","zh":"不公平對待，是指以不公正、不誠實或不平等方式對待人。"},{"en":"A worker faces unfair treatment if they are paid less for the same work without a valid reason.","zh":"如果工人做相同工作卻無正當理由薪酬較低，就是面對不公平對待。"},{"en":"Rules can reduce unfair treatment by setting clear rights and penalties.","zh":"規則可以透過設定清晰權利和罰則來減少不公平對待。"},{"en":"This phrase describes behaviour that violates fairness.","zh":"這個短語描述違反公平的行為。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":22},{"front":"safety standards","meaning":"安全標準","examples":[{"en":"Improving safety standards can reduce accident costs.","zh":"改善安全標準可以減少事故成本。"},{"en":"Safety standards are rules or requirements designed to prevent harm and accidents.","zh":"安全標準是為防止傷害和意外而設的規則或要求。"},{"en":"A restaurant follows safety standards when it stores food at the correct temperature.","zh":"餐廳把食物儲存在正確溫度，就是遵守安全標準。"},{"en":"Strong safety standards protect workers and customers while reducing legal and medical costs.","zh":"強大安全標準保護員工和顧客，同時減少法律和醫療成本。"},{"en":"This phrase refers to agreed levels of safety.","zh":"這個短語指協定的安全水平。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":22},{"front":"growing pool of","meaning":"不斷增長的……","examples":[{"en":"A healthy society creates a growing pool of human needs.","zh":"健康社會創造不斷增長的人類需要。"},{"en":"A growing pool of something means an increasing supply, number, or group of it.","zh":"不斷增長的一池或一群某物，是指其供應、數量或群體正在增加。"},{"en":"A city with better education creates a growing pool of skilled workers.","zh":"教育更好的城市會創造不斷增長的熟練工人群體。"},{"en":"As people’s needs and aspirations grow, businesses may find more opportunities to serve them.","zh":"隨着人們需要和願望提升，企業可能找到更多服務機會。"},{"en":"This phrase describes an expanding source or group.","zh":"這個短語描述正在擴大的來源或群體。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":22},{"front":"look at the following opinions or deeds","meaning":"查看以下觀點或行為","examples":[{"en":"Students look at the following opinions or deeds and match them with companies.","zh":"學生查看以下觀點或行為，並把它們與公司配對。"},{"en":"Look at the following opinions or deeds means read the listed views or actions carefully.","zh":"查看以下觀點或行為，是指仔細閱讀列出的看法或行動。"},{"en":"In a reading task, students may look at opinions or deeds before locating who said or did them.","zh":"在閱讀題中，學生可能先查看觀點或行為，再定位誰說過或做過。"},{"en":"Careful reading prevents students from matching an action with the wrong company.","zh":"仔細閱讀能防止學生把行動配對到錯誤公司。"},{"en":"This phrase is an exam instruction for matching information.","zh":"這個短語是資料配對題的考試指示。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":22},{"front":"match each opinion with","meaning":"把每項觀點與……配對","examples":[{"en":"Students match each opinion with the correct company.","zh":"學生把每項觀點與正確公司配對。"},{"en":"To match each opinion with something means to connect every view to the correct person, group, or source.","zh":"把每項觀點與某物配對，是指把每個看法連接到正確人物、群體或來源。"},{"en":"Students may match each opinion with the speaker who expressed it in an interview.","zh":"學生可能把每項觀點與訪問中表達該看法的講者配對。"},{"en":"Matching requires understanding meaning, not simply repeating similar words.","zh":"配對需要理解意思，而不是只重複相似字眼。"},{"en":"This phrase describes a classification task.","zh":"這個短語描述分類任務。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":22},{"front":"correct company","meaning":"正確公司","examples":[{"en":"The task asks students to choose the correct company.","zh":"題目要求學生選擇正確公司。"},{"en":"The correct company is the company that matches the information in the passage.","zh":"正確公司是與篇章資料相符的公司。"},{"en":"If a statement describes Microsoft’s college programme, Microsoft is the correct company.","zh":"如果陳述描述 Microsoft 的學院計劃，Microsoft 就是正確公司。"},{"en":"Students must use evidence from the text to choose the correct company.","zh":"學生必須使用文本證據來選擇正確公司。"},{"en":"This phrase refers to the right answer in a company-matching question.","zh":"這個短語指公司配對題中的正確答案。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":23},{"front":"may use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"Students may use any letter more than once.","zh":"學生可重複使用任何字母。"},{"en":"May use any letter more than once means the same answer option can be selected for several items.","zh":"可重複使用任何字母，是指同一答案選項可以用於幾個項目。"},{"en":"In a matching task, one paragraph letter may be used more than once if it contains several pieces of information.","zh":"在配對題中，如果一個段落包含幾項資料，同一段落字母可被重複使用。"},{"en":"This instruction prevents students from assuming each option can be used only once.","zh":"這項指示防止學生假設每個選項只能用一次。"},{"en":"This phrase is important for avoiding artificial answer limits.","zh":"這個短語對避免人為答案限制很重要。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":23},{"front":"disposal of waste","meaning":"廢物處理","examples":[{"en":"The disposal of waste is part of Whole Foods’ CSR practice.","zh":"廢物處理是 Whole Foods 企業社會責任做法的一部分。"},{"en":"Disposal of waste means how rubbish, unwanted materials, or by-products are removed or treated.","zh":"廢物處理是指垃圾、不需要材料或副產品如何被移走或處理。"},{"en":"A restaurant needs safe disposal of waste so food scraps do not attract pests.","zh":"餐廳需要安全廢物處理，使食物殘渣不會吸引害蟲。"},{"en":"Responsible waste disposal can reduce pollution and support recycling or composting.","zh":"負責任廢物處理可以減少污染並支持回收或堆肥。"},{"en":"This phrase focuses on what happens to unwanted materials after use.","zh":"這個短語聚焦使用後不需要材料會如何處理。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":23},{"front":"purchases goods","meaning":"採購貨品","examples":[{"en":"The question asks about the way the company purchases goods.","zh":"題目問公司採購貨品的方式。"},{"en":"Purchases goods means buys products, materials, or supplies.","zh":"採購貨品，是指購買產品、材料或供應品。"},{"en":"A school purchases goods such as textbooks, computers, and cleaning products.","zh":"學校採購教科書、電腦和清潔用品等貨品。"},{"en":"How a company purchases goods affects suppliers, product quality, and environmental impact.","zh":"公司如何採購貨品會影響供應商、產品質素和環境影響。"},{"en":"This phrase describes buying as part of business operations.","zh":"這個短語描述作為商業營運一部分的購買。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":23},{"front":"helping underperforming schools","meaning":"幫助表現欠佳的學校","examples":[{"en":"General Electric helped underperforming schools.","zh":"General Electric 幫助表現欠佳的學校。"},{"en":"Helping underperforming schools means supporting schools whose results are weaker than expected.","zh":"幫助表現欠佳的學校，是支持成績或表現低於預期的學校。"},{"en":"A company may help underperforming schools by offering tutors, equipment, and mentoring.","zh":"公司可以透過提供導師、設備和指導來幫助表現欠佳的學校。"},{"en":"Such help can improve graduation rates and student confidence over time.","zh":"這類幫助可以隨時間改善畢業率和學生信心。"},{"en":"This phrase describes targeted support for struggling schools.","zh":"這個短語描述對有困難學校的針對性支援。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":23},{"front":"up-to-date information","meaning":"最新資料","examples":[{"en":"Microsoft helped ensure that people had up-to-date information.","zh":"Microsoft 幫助確保人們擁有最新資料。"},{"en":"Up-to-date information is current information that reflects the latest knowledge or changes.","zh":"最新資料是反映最新知識或變化的當前資訊。"},{"en":"Doctors need up-to-date information before giving advice about new treatments.","zh":"醫生在提供新治療建議前需要最新資料。"},{"en":"Outdated information can lead to poor decisions, especially in fast-changing fields like technology.","zh":"過時資料會導致差劣決定，尤其在科技等快速變化領域。"},{"en":"This phrase describes information that has not fallen behind current developments.","zh":"這個短語描述沒有落後於當前發展的資料。"}],"source":"43 - Corporate Social Responsibility .pdf","sourcePage":23}],"ielts/reading/passage-2/Practice 44":[{"front":"IQ test","meaning":"智商測驗","examples":[{"en":"The title asks whether an IQ test can prove creativity.","zh":"標題問智商測驗是否能證明創意。"},{"en":"An IQ test is a test designed to measure certain kinds of intelligence, such as reasoning and problem-solving.","zh":"IQ test 指用來測量某些智力能力的測驗，例如推理和解難能力。"},{"en":"A school psychologist may use an IQ test to understand a student’s learning needs.","zh":"學校心理學家可能使用智商測驗來了解學生的學習需要。"},{"en":"An IQ test can show some mental abilities, but it cannot measure every human strength.","zh":"智商測驗可以顯示某些心智能力，但不能衡量人類所有長處。"},{"en":"This phrase is useful when discussing intelligence, education, and ability testing.","zh":"討論智力、教育和能力測試時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":1},{"front":"creativity","meaning":"創意；創造力","examples":[{"en":"Everyone has some creativity, though some people have much more than others.","zh":"每個人都有一些創意，雖然有些人比其他人多得多。"},{"en":"Creativity is the ability to produce new, original, or useful ideas.","zh":"creativity 指產生新穎、原創或有用想法的能力。"},{"en":"A student shows creativity when she finds a new way to explain a difficult grammar point.","zh":"學生找到新方法解釋困難文法點時，就是展現創意。"},{"en":"Creativity can turn ordinary materials, such as paper and tape, into a useful classroom activity.","zh":"創意可以把紙和膠紙等普通材料變成有用的課堂活動。"},{"en":"This word is used in art, science, business, education, and problem-solving.","zh":"這個詞可用於藝術、科學、商業、教育和解難。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":1},{"front":"depends on","meaning":"取決於；依賴","examples":[{"en":"The development of humans depends on creativity.","zh":"人類的發展取決於創意。"},{"en":"Depends on means needs something or is strongly affected by it.","zh":"depends on 指需要某物，或強烈受某物影響。"},{"en":"A student’s progress depends on practice, feedback, and enough sleep.","zh":"學生進步取決於練習、回饋和足夠睡眠。"},{"en":"If a plan depends on one person only, it may fail when that person is absent.","zh":"如果計劃只依賴一個人，當那人缺席時可能失敗。"},{"en":"This phrase is useful when showing that one thing relies on another.","zh":"顯示一件事依賴另一件事時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":1},{"front":"an elusive creature","meaning":"捉摸不定的東西","examples":[{"en":"Creativity is described as an elusive creature.","zh":"創意被描述為一種捉摸不定的東西。"},{"en":"An elusive creature is something difficult to catch, define, or understand clearly.","zh":"elusive creature 指難以捕捉、定義或清楚理解的東西。"},{"en":"Happiness can feel like an elusive creature when people chase it too directly.","zh":"當人們太直接追求快樂時，快樂可能像捉摸不定的東西。"},{"en":"If something is elusive, researchers may struggle to measure it with simple tests.","zh":"如果某物捉摸不定，研究人員可能難以用簡單測驗衡量它。"},{"en":"This phrase uses a metaphor to show that creativity is hard to pin down.","zh":"這個短語用比喻顯示創意難以準確掌握。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":1},{"front":"what do we mean by","meaning":"我們所指的是甚麼","examples":[{"en":"What do we mean by creativity?","zh":"我們所指的 creativity 是甚麼？"},{"en":"What do we mean by asks for the exact meaning of a word, idea, or phrase.","zh":"what do we mean by 用來詢問某個詞、想法或短語的確切意思。"},{"en":"A teacher may ask, “What do we mean by fairness?” before a class discussion.","zh":"老師可能在課堂討論前問：「我們所指的公平是甚麼？」"},{"en":"Asking this question prevents people from arguing while using the same word differently.","zh":"問這個問題可以避免人們用同一個詞但意思不同而爭論。"},{"en":"This phrase is useful when a concept is abstract or unclear.","zh":"當概念抽象或不清楚時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":1},{"front":"what is going on in","meaning":"……正在發生甚麼事","examples":[{"en":"What is going on in our brains when ideas form?","zh":"當意念形成時，我們大腦中正在發生甚麼事？"},{"en":"What is going on in means what is happening inside a place, system, or situation.","zh":"what is going on in 指某個地方、系統或情況內正在發生甚麼。"},{"en":"A doctor may ask what is going on in the body when a patient feels dizzy.","zh":"病人感到頭暈時，醫生可能問身體內正在發生甚麼事。"},{"en":"This phrase helps people look beneath the surface and ask about hidden processes.","zh":"這個短語幫助人們看表面以下，詢問隱藏過程。"},{"en":"It is useful when discussing the brain, emotions, machines, or organisations.","zh":"討論大腦、情緒、機器或組織時，它很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":1},{"front":"ideas form","meaning":"意念形成","examples":[{"en":"Scientists study what happens in the brain when ideas form.","zh":"科學家研究意念形成時大腦中發生甚麼事。"},{"en":"Ideas form when thoughts, memories, and information connect into a new possibility.","zh":"ideas form 指想法、記憶和資訊連接成新的可能性。"},{"en":"A student may feel ideas form after reading examples and discussing them with classmates.","zh":"學生閱讀例子並與同學討論後，可能感到意念形成。"},{"en":"Ideas often form slowly when the brain has time to compare and combine information.","zh":"當大腦有時間比較和組合資訊，意念常會慢慢形成。"},{"en":"This phrase describes the beginning of thinking or creativity.","zh":"這個短語描述思考或創意的開始。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":1},{"front":"neuroscientists","meaning":"神經科學家","examples":[{"en":"The passage asks writers and neuroscientists to explain creativity.","zh":"文章請作家和神經科學家解釋創意。"},{"en":"Neuroscientists are scientists who study the brain and nervous system.","zh":"neuroscientists 指研究大腦和神經系統的科學家。"},{"en":"Neuroscientists may scan people’s brains while they solve problems or listen to music.","zh":"神經科學家可能在人們解題或聽音樂時掃描他們的大腦。"},{"en":"Their research can help explain how memory, emotion, and attention work.","zh":"他們的研究可以幫助解釋記憶、情緒和注意力如何運作。"},{"en":"This word is common in brain science and psychology.","zh":"這個詞常見於腦科學和心理學。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":1},{"front":"pop stars and AI gurus","meaning":"流行歌星和人工智能專家","examples":[{"en":"The writers interviewed pop stars and AI gurus about creativity.","zh":"作者訪問了流行歌星和人工智能專家，談論創意。"},{"en":"Pop stars and AI gurus are famous music performers and well-known experts in artificial intelligence.","zh":"pop stars and AI gurus 指著名流行音樂表演者和知名人工智能專家。"},{"en":"A magazine may interview pop stars and AI gurus to compare artistic and technological creativity.","zh":"雜誌可能訪問流行歌星和人工智能專家，以比較藝術和科技創意。"},{"en":"Hearing from different fields can show that creativity appears in many forms.","zh":"聽取不同領域的意見，可以顯示創意有多種形式。"},{"en":"This phrase combines popular culture with advanced technology.","zh":"這個短語結合流行文化與先進科技。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":1},{"front":"deconstruct the creative process","meaning":"解構創作過程","examples":[{"en":"The experts try to deconstruct the creative process.","zh":"專家嘗試解構創作過程。"},{"en":"To deconstruct the creative process means to break it into parts and explain how each part works.","zh":"deconstruct the creative process 指把創作過程拆成不同部分，並解釋每部分如何運作。"},{"en":"A writing teacher may deconstruct the creative process by showing how ideas become outlines and drafts.","zh":"寫作老師可能透過展示想法如何變成大綱和草稿來解構創作過程。"},{"en":"Breaking a process into parts makes a mysterious skill easier to understand.","zh":"把過程拆開可以令神秘技能更容易理解。"},{"en":"This phrase is useful when analysing art, writing, design, or problem-solving.","zh":"分析藝術、寫作、設計或解難時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":1},{"front":"ignite the spark within","meaning":"點燃內在的火花","examples":[{"en":"The passage explores how we can ignite the spark within.","zh":"文章探討我們如何點燃內在的火花。"},{"en":"To ignite the spark within means to awaken someone’s hidden energy, interest, or creativity.","zh":"ignite the spark within 指喚醒某人內在的能量、興趣或創意。"},{"en":"A good teacher can ignite the spark within a shy student by praising one strong idea.","zh":"好老師可以透過稱讚一個好想法，點燃害羞學生內在的火花。"},{"en":"Inspiration can grow when people feel safe enough to try something new.","zh":"當人們感到安全，可以嘗試新事物，靈感就可能增長。"},{"en":"This phrase is metaphorical and positive.","zh":"這個短語是比喻性和正面的。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":1},{"front":"be seen as","meaning":"被視為","examples":[{"en":"In the early 1970s, creativity was still seen as a type of intelligence.","zh":"在1970年代初，創意仍被視為一種智力。"},{"en":"To be seen as something means to be regarded or understood in that way.","zh":"be seen as something 指被認為或理解為某事物。"},{"en":"A quiet student may be seen as lazy, even when she is actually anxious.","zh":"安靜學生可能被視為懶惰，即使她其實是焦慮。"},{"en":"How something is seen can affect how people study, teach, or judge it.","zh":"某物被如何看待，會影響人們如何研究、教授或評價它。"},{"en":"This phrase is useful when describing public or expert perception.","zh":"描述公眾或專家看法時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":2},{"front":"a type of intelligence","meaning":"一種智力","examples":[{"en":"Creativity was once treated as a type of intelligence.","zh":"創意曾經被視為一種智力。"},{"en":"A type of intelligence is one form of mental ability.","zh":"type of intelligence 指心智能力的一種形式。"},{"en":"Problem-solving, language ability, and spatial reasoning can be treated as different types of intelligence.","zh":"解難能力、語言能力和空間推理可以被視為不同種類的智力。"},{"en":"Seeing creativity as intelligence makes researchers more likely to test it.","zh":"把創意視為智力，會令研究人員更可能測試它。"},{"en":"This phrase is useful when classifying mental abilities.","zh":"分類心智能力時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":2},{"front":"more subtle tests of","meaning":"更細緻的……測驗","examples":[{"en":"Researchers developed more subtle tests of IQ and creative skills.","zh":"研究人員發展出更細緻的智商和創意技能測驗。"},{"en":"More subtle tests of something are tests that measure it in a more careful or detailed way.","zh":"more subtle tests of something 指以更仔細或更細緻方式衡量某事的測驗。"},{"en":"A teacher may use more subtle tests of speaking ability than simply asking students to read aloud.","zh":"老師可能使用比單純朗讀更細緻的口語能力測驗。"},{"en":"Subtle tests can reveal differences that simple tests miss.","zh":"細緻測驗可以揭示簡單測驗錯過的差異。"},{"en":"This phrase is useful when measurement needs to be more precise.","zh":"當測量需要更精準時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":2},{"front":"creative skills","meaning":"創意技能","examples":[{"en":"New tests were designed to measure creative skills.","zh":"新測驗被設計來衡量創意技能。"},{"en":"Creative skills are abilities used to produce original ideas, solutions, designs, or performances.","zh":"creative skills 指用來產生原創想法、方案、設計或表演的能力。"},{"en":"A student uses creative skills when turning a boring topic into an interesting presentation.","zh":"學生把沉悶題目變成有趣匯報時，就是使用創意技能。"},{"en":"Creative skills can improve when people practise combining ideas in new ways.","zh":"當人們練習以新方式組合想法，創意技能可以改善。"},{"en":"This phrase is useful in education, art, business, and innovation.","zh":"這個短語適用於教育、藝術、商業和創新。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":2},{"front":"creativity testing","meaning":"創意測試","examples":[{"en":"Paul Torrance is described as the father of creativity testing.","zh":"Paul Torrance 被描述為創意測試之父。"},{"en":"Creativity testing means using tasks or tests to measure creative ability.","zh":"creativity testing 指使用任務或測驗來衡量創造能力。"},{"en":"A creativity test may ask students to think of many unusual uses for a paper clip.","zh":"創意測試可能要求學生想出萬字夾的許多不尋常用途。"},{"en":"Testing creativity is difficult because original ideas are harder to score than correct answers.","zh":"測試創意很困難，因為原創想法比正確答案更難評分。"},{"en":"This phrase is common in psychology and education research.","zh":"這個短語常見於心理學和教育研究。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":2},{"front":"it became clear that","meaning":"……變得明顯","examples":[{"en":"It became clear that the link between IQ and creativity was not simple.","zh":"智商與創意之間的關係並不簡單，這一點變得明顯。"},{"en":"It became clear that means people gradually realised something was true.","zh":"it became clear that 指人們逐漸意識到某事是真的。"},{"en":"After several complaints, it became clear that the timetable was too crowded.","zh":"經過幾次投訴後，時間表太擠迫這一點變得明顯。"},{"en":"Evidence can make a hidden problem obvious over time.","zh":"證據可以令隱藏問題隨時間變得明顯。"},{"en":"This phrase is useful when understanding changes from uncertain to clear.","zh":"描述理解由不確定變清楚時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":2},{"front":"the link was not so simple","meaning":"兩者的關係並不簡單","examples":[{"en":"Researchers found that the link was not so simple.","zh":"研究人員發現兩者的關係並不簡單。"},{"en":"The link was not so simple means the relationship between two things was more complicated than expected.","zh":"the link was not so simple 指兩件事之間的關係比預期更複雜。"},{"en":"A teacher may find that the link between homework time and exam marks is not so simple.","zh":"老師可能發現功課時間與考試分數之間的關係並不簡單。"},{"en":"Some relationships have several causes, limits, and exceptions.","zh":"有些關係有多個原因、限制和例外。"},{"en":"This phrase is useful when rejecting an oversimplified explanation.","zh":"拒絕過度簡化的解釋時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":2},{"front":"in terms of","meaning":"就……而言","examples":[{"en":"Creative people are intelligent, at least in terms of IQ tests.","zh":"創意人士是聰明的，至少就智商測驗而言。"},{"en":"In terms of means when judged by a particular aspect or measure.","zh":"in terms of 指從某一方面或衡量標準來看。"},{"en":"In terms of price, the bus is cheaper than a taxi.","zh":"就價格而言，巴士比的士便宜。"},{"en":"This phrase limits the statement to one angle, not every possible angle.","zh":"這個短語把說法限制在某一角度，而不是所有角度。"},{"en":"It is useful when comparing performance, cost, quality, or ability.","zh":"比較表現、成本、質素或能力時，它很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":2},{"front":"average or slightly above average","meaning":"平均或略高於平均","examples":[{"en":"Their IQ scores are often only average or slightly above average.","zh":"他們的智商分數往往只是平均或略高於平均。"},{"en":"Average or slightly above average means normal or just a little higher than normal.","zh":"average or slightly above average 指正常水平或只比正常水平高一點。"},{"en":"A student may have average or slightly above average marks but still write very original stories.","zh":"學生分數可能平均或略高於平均，但仍能寫出非常原創的故事。"},{"en":"This phrase shows that being exceptional in one area does not require top scores in every area.","zh":"這個短語顯示某方面出色，不一定需要每方面都最高分。"},{"en":"It is useful when describing moderate performance.","zh":"描述中等表現時，它很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":2},{"front":"depends on the discipline","meaning":"取決於學科；因範疇而異","examples":[{"en":"The relationship between IQ and creativity depends on the discipline.","zh":"智商與創意之間的關係取決於學科。"},{"en":"Depends on the discipline means changes according to the subject or field being discussed.","zh":"depends on the discipline 指會因所討論的學科或領域而改變。"},{"en":"The amount of reading needed at university depends on the discipline.","zh":"大學所需閱讀量因學科而異。"},{"en":"A skill may matter greatly in science but less in music or design.","zh":"某項技能在科學中可能很重要，但在音樂或設計中較不重要。"},{"en":"This phrase is useful when a rule is not the same across all fields.","zh":"當規則不是所有領域都一樣時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":2},{"front":"beyond a certain level","meaning":"超過某個水平之後","examples":[{"en":"Beyond a certain level, IQ does not help boost creativity.","zh":"超過某個水平之後，智商無助於提升創意。"},{"en":"Beyond a certain level means after reaching a particular point or amount.","zh":"beyond a certain level 指達到某一點或數量之後。"},{"en":"Beyond a certain level, more study hours may not help if the student is exhausted.","zh":"超過某個水平之後，如果學生已筋疲力盡，更多學習時間未必有幫助。"},{"en":"Some benefits stop increasing after a basic requirement is met.","zh":"有些好處在基本要求達到後就不再增加。"},{"en":"This phrase is useful when describing limits or thresholds.","zh":"描述限制或門檻時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":2},{"front":"boost creativity","meaning":"提升創意","examples":[{"en":"IQ does not always help boost creativity.","zh":"智商並不總是有助提升創意。"},{"en":"To boost creativity means to increase or strengthen creative thinking.","zh":"boost creativity 指增加或強化創意思維。"},{"en":"A teacher can boost creativity by giving students open-ended questions.","zh":"老師可以透過給學生開放式問題來提升創意。"},{"en":"Too much fear of mistakes can reduce creativity instead of boosting it.","zh":"過度害怕犯錯可能會減少創意，而不是提升創意。"},{"en":"This phrase is useful when discussing ways to encourage original ideas.","zh":"討論鼓勵原創想法的方法時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":3},{"front":"necessary but not sufficient","meaning":"必要但不足夠","examples":[{"en":"IQ is necessary but not sufficient to make someone creative.","zh":"智商對令某人有創意是必要但不足夠的。"},{"en":"Necessary but not sufficient means needed, but not enough by itself.","zh":"necessary but not sufficient 指需要它，但單靠它並不足夠。"},{"en":"Money is necessary but not sufficient to build a good school; good teachers are needed too.","zh":"金錢對建立好學校是必要但不足夠的；好老師也需要。"},{"en":"A condition can be important without being the whole explanation.","zh":"某條件可以重要，但不是完整解釋。"},{"en":"This phrase is useful when explaining why one factor alone cannot produce a result.","zh":"解釋為何單一因素不能產生結果時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":3},{"front":"make someone creative","meaning":"令某人有創意","examples":[{"en":"High intelligence alone does not make someone creative.","zh":"單靠高智力不會令某人有創意。"},{"en":"To make someone creative means to cause or help that person become able to produce original ideas.","zh":"make someone creative 指令或幫助某人能產生原創想法。"},{"en":"A supportive classroom can help make students more creative by allowing safe experimentation.","zh":"支持性的課室可以透過容許安全嘗試，幫助令學生更有創意。"},{"en":"Intelligence, motivation, freedom, and practice may all contribute to creativity.","zh":"智力、動機、自由和練習都可能有助創意。"},{"en":"This phrase is useful when discussing what causes creative ability.","zh":"討論甚麼造成創造能力時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":3},{"front":"the actual process","meaning":"實際過程","examples":[{"en":"Researchers found it difficult to study the actual process of creativity.","zh":"研究人員發現研究創意的實際過程很困難。"},{"en":"The actual process is the real sequence of actions or mental steps behind something.","zh":"actual process 指某事背後真實的一連串行動或心理步驟。"},{"en":"A teacher may want to see the actual process of how a student solves a maths problem, not only the answer.","zh":"老師可能想看學生解數學題的實際過程，而不只是答案。"},{"en":"Studying the process can reveal mistakes or strategies that final results hide.","zh":"研究過程可以揭示最終結果隱藏的錯誤或策略。"},{"en":"This phrase is useful when focusing on how something happens.","zh":"聚焦某事如何發生時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":3},{"front":"early attempts to","meaning":"早期嘗試去……","examples":[{"en":"Most early attempts to study creativity focused on personality.","zh":"大多數早期研究創意的嘗試都集中於性格。"},{"en":"Early attempts to do something are the first efforts made to achieve or understand it.","zh":"early attempts to do something 指為達成或理解某事而作出的最初努力。"},{"en":"Early attempts to learn English may feel awkward, but they build confidence over time.","zh":"早期學習英文的嘗試可能感覺尷尬，但會隨時間建立信心。"},{"en":"First attempts often reveal what methods work and what needs improvement.","zh":"初次嘗試常揭示哪些方法有效、哪些需要改善。"},{"en":"This phrase is useful when describing the beginning of research or learning.","zh":"描述研究或學習的開始時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":3},{"front":"concentrate on personality","meaning":"集中研究性格","examples":[{"en":"Early studies of creativity tended to concentrate on personality.","zh":"早期創意研究往往集中研究性格。"},{"en":"To concentrate on personality means to focus mainly on people’s character, habits, or emotional traits.","zh":"concentrate on personality 指主要聚焦人的性格、習慣或情緒特質。"},{"en":"A career adviser may concentrate on personality when helping students choose suitable work.","zh":"職業顧問幫學生選擇合適工作時，可能集中看性格。"},{"en":"Focusing only on personality may miss the role of training, environment, or support.","zh":"只聚焦性格可能會錯過訓練、環境或支援的作用。"},{"en":"This phrase is useful when describing the main focus of a study.","zh":"描述研究主要焦點時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":3},{"front":"creativity specialist","meaning":"創意研究專家","examples":[{"en":"Mark Runco is a creativity specialist at California State University, Fullerton.","zh":"Mark Runco 是加州州立大學富勒頓分校的創意研究專家。"},{"en":"A creativity specialist is an expert who studies creative thinking and creative behaviour.","zh":"creativity specialist 指研究創意思維和創意行為的專家。"},{"en":"A company may invite a creativity specialist to help teams generate better ideas.","zh":"公司可能邀請創意研究專家幫助團隊產生更好想法。"},{"en":"Specialists can explain a topic more deeply because they study it for many years.","zh":"專家因多年研究一個主題，所以能更深入解釋。"},{"en":"This phrase is useful when identifying an expert in creativity research.","zh":"指出創意研究方面的專家時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":3},{"front":"the creative personality","meaning":"創意型性格","examples":[{"en":"Researchers tried to describe the creative personality.","zh":"研究人員嘗試描述創意型性格。"},{"en":"The creative personality means the pattern of traits often found in creative people.","zh":"creative personality 指創意人士常有的一組性格特徵。"},{"en":"A creative personality may enjoy unusual ideas, open questions, and independent work.","zh":"創意型性格的人可能喜歡不尋常想法、開放式問題和獨立工作。"},{"en":"Studying personality can help explain why some people keep exploring when others give up.","zh":"研究性格可以幫助解釋為何有些人繼續探索，而其他人放棄。"},{"en":"This phrase is useful when discussing character traits linked to creativity.","zh":"討論與創意相關的性格特徵時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":3},{"front":"tend to place a high value on","meaning":"往往高度重視……","examples":[{"en":"Creative people tend to place a high value on aesthetic qualities.","zh":"創意人士往往高度重視美學特質。"},{"en":"To place a high value on something means to consider it very important.","zh":"place a high value on something 指認為某事非常重要。"},{"en":"A school may place a high value on kindness as well as exam results.","zh":"學校可能高度重視善良以及考試成績。"},{"en":"What people value strongly often shapes how they spend time and make choices.","zh":"人們重視甚麼，常會塑造他們如何花時間和作選擇。"},{"en":"This phrase is useful when describing priorities.","zh":"描述優先事項時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":3},{"front":"aesthetic qualities","meaning":"美學特質","examples":[{"en":"The creative personality values aesthetic qualities.","zh":"創意型性格重視美學特質。"},{"en":"Aesthetic qualities are qualities related to beauty, style, form, colour, sound, or artistic effect.","zh":"aesthetic qualities 指與美感、風格、形式、顏色、聲音或藝術效果相關的特質。"},{"en":"A designer considers aesthetic qualities when choosing fonts, colours, and layout.","zh":"設計師選擇字體、顏色和版面時，會考慧美學特質。"},{"en":"Valuing aesthetics can make people notice details that others ignore.","zh":"重視美感可以令人注意到其他人忽略的細節。"},{"en":"This phrase is useful in art, design, music, writing, and architecture.","zh":"這個短語適用於藝術、設計、音樂、寫作和建築。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":3},{"front":"broad interests","meaning":"廣泛興趣","examples":[{"en":"Creative people often have broad interests.","zh":"創意人士常有廣泛興趣。"},{"en":"Broad interests are interests in many different subjects or activities.","zh":"broad interests 指對許多不同科目或活動有興趣。"},{"en":"A student with broad interests may enjoy biology, music, history, and cooking.","zh":"有廣泛興趣的學生可能喜歡生物、音樂、歷史和烹飪。"},{"en":"Having broad interests gives people more ideas to combine in unusual ways.","zh":"擁有廣泛興趣讓人有更多想法可以不尋常地組合。"},{"en":"This phrase is useful when describing intellectual curiosity.","zh":"描述求知好奇心時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":3},{"front":"resources to draw on","meaning":"可借鑑的資源","examples":[{"en":"Broad interests give creative people many resources to draw on.","zh":"廣泛興趣給予創意人士許多可借鑑的資源。"},{"en":"Resources to draw on are ideas, experiences, skills, or knowledge that someone can use.","zh":"resources to draw on 指某人可以使用的想法、經驗、技能或知識。"},{"en":"A writer who reads widely has many stories and styles to draw on.","zh":"廣泛閱讀的作家有許多故事和風格可以借鑑。"},{"en":"More resources can help people solve problems from different angles.","zh":"更多資源可以幫助人從不同角度解決問題。"},{"en":"This phrase is useful when explaining where ideas come from.","zh":"解釋想法來源時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":4},{"front":"recombine into novel solutions","meaning":"重新組合成新穎方案","examples":[{"en":"Creative people recombine knowledge into novel solutions.","zh":"創意人士把知識重新組合成新穎方案。"},{"en":"To recombine into novel solutions means to put existing ideas together in new ways to solve problems.","zh":"recombine into novel solutions 指把已有想法以新方式組合來解決問題。"},{"en":"A teacher may recombine games and grammar drills into a more enjoyable lesson.","zh":"老師可能把遊戲和文法操練重新組合成更有趣的課堂。"},{"en":"New solutions often appear when old materials are arranged differently.","zh":"當舊材料被不同方式排列，新方案常會出現。"},{"en":"This phrase is useful when creativity comes from combining existing knowledge.","zh":"當創意來自組合已有知識時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":4},{"front":"novel solutions","meaning":"新穎方案","examples":[{"en":"Creativity can involve turning old knowledge into novel solutions.","zh":"創意可以涉及把舊知識變成新穎方案。"},{"en":"Novel solutions are new and original ways to solve problems.","zh":"novel solutions 指新的、原創的解決問題方法。"},{"en":"A small shop may find novel solutions, such as taking orders through messaging apps.","zh":"小店可能找到新穎方案，例如透過通訊應用程式接單。"},{"en":"Novel solutions can appear when people question the usual way of doing things.","zh":"當人們質疑慣常做法，新穎方案可能出現。"},{"en":"This phrase is useful in business, science, design, and daily problem-solving.","zh":"這個短語適用於商業、科學、設計和日常解難。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":4},{"front":"an attraction to complexity","meaning":"對複雜性的吸引；喜歡複雜事物","examples":[{"en":"Creative people often have an attraction to complexity.","zh":"創意人士常對複雜性有吸引。"},{"en":"An attraction to complexity means liking complicated problems, patterns, or ideas.","zh":"attraction to complexity 指喜歡複雜問題、模式或想法。"},{"en":"A student with an attraction to complexity may enjoy puzzles with many possible answers.","zh":"喜歡複雜事物的學生可能享受有許多可能答案的謎題。"},{"en":"This attraction can help people stay interested when a problem is messy or difficult.","zh":"這種吸引力可以幫助人在問題混亂或困難時仍保持興趣。"},{"en":"This phrase is useful when describing curiosity about complicated things.","zh":"描述對複雜事物的好奇時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":4},{"front":"ability to handle conflict","meaning":"處理衝突的能力","examples":[{"en":"Creative people may have an ability to handle conflict.","zh":"創意人士可能有處理衝突的能力。"},{"en":"Ability to handle conflict means being able to deal with disagreement, tension, or opposing ideas calmly.","zh":"ability to handle conflict 指能冷靜處理分歧、緊張或相反想法。"},{"en":"A team leader needs the ability to handle conflict when members disagree about a plan.","zh":"當成員對計劃有分歧時，團隊負責人需要處理衝突的能力。"},{"en":"Handling conflict well can turn different opinions into better decisions.","zh":"好好處理衝突可以把不同意見變成更好決定。"},{"en":"This phrase is useful in work, family, and creative collaboration.","zh":"這個短語適用於工作、家庭和創意合作。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":4},{"front":"highly self-motivated","meaning":"高度自我推動","examples":[{"en":"Creative people are often highly self-motivated.","zh":"創意人士常常高度自我推動。"},{"en":"Highly self-motivated means driven by one’s own interest and goals without needing constant pressure from others.","zh":"highly self-motivated 指由自己的興趣和目標推動，而不需要別人不斷施壓。"},{"en":"A highly self-motivated student practises speaking even when no homework is assigned.","zh":"高度自我推動的學生即使沒有功課，也會練習說話。"},{"en":"Self-motivation helps people continue working when progress is slow.","zh":"自我推動幫助人在進展緩慢時仍繼續努力。"},{"en":"This phrase is useful when describing independent effort.","zh":"描述獨立努力時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":4},{"front":"a little obsessive","meaning":"有點執着","examples":[{"en":"Creative people may even be a little obsessive.","zh":"創意人士甚至可能有點執着。"},{"en":"A little obsessive means slightly too focused on one idea, task, or problem.","zh":"a little obsessive 指對一個想法、任務或問題稍微過度專注。"},{"en":"A student may become a little obsessive about perfecting a presentation slide.","zh":"學生可能對完善一張匯報投影片有點執着。"},{"en":"Strong focus can help creative work, but too much obsession may cause stress.","zh":"強烈專注可以幫助創作，但過度執着可能造成壓力。"},{"en":"This phrase describes intensity, usually with a mild warning.","zh":"這個短語描述強烈程度，通常帶輕微提醒。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":4},{"front":"become irritated","meaning":"變得煩躁","examples":[{"en":"Less creative people may become irritated when they cannot solve a problem quickly.","zh":"較少創意的人如果不能快速解決問題，可能變得煩躁。"},{"en":"To become irritated means to start feeling annoyed or impatient.","zh":"become irritated 指開始感到惱怒或不耐煩。"},{"en":"A student may become irritated if the internet stops during an online lesson.","zh":"如果網上課堂期間網絡中斷，學生可能變得煩躁。"},{"en":"Irritation can make people give up before they find a better solution.","zh":"煩躁可以令人在找到更好方案前就放棄。"},{"en":"This phrase is useful when describing emotional reactions to difficulty.","zh":"描述對困難的情緒反應時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":4},{"front":"fit all the pieces together","meaning":"把所有部分拼合起來","examples":[{"en":"Some people become irritated if they cannot fit all the pieces together immediately.","zh":"如果不能立即把所有部分拼合起來，有些人會變得煩躁。"},{"en":"To fit all the pieces together means to connect separate facts or ideas into a complete understanding.","zh":"fit all the pieces together 指把分散事實或想法連接成完整理解。"},{"en":"A detective tries to fit all the pieces together before solving a case.","zh":"偵探在破案前嘗試把所有線索拼合起來。"},{"en":"Creative work often takes time because the pieces do not connect immediately.","zh":"創作常需要時間，因為各部分不會立即連接。"},{"en":"This phrase is useful when discussing puzzles, research, and problem-solving.","zh":"討論謎題、研究和解難時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":4},{"front":"be tolerant of confusion","meaning":"能容忍混亂","examples":[{"en":"Creative people tend to be tolerant of confusion.","zh":"創意人士往往能容忍混亂。"},{"en":"To be tolerant of confusion means to stay calm when things are unclear or not yet organised.","zh":"be tolerant of confusion 指在事情不清楚或尚未整理好時仍保持冷靜。"},{"en":"A good researcher is tolerant of confusion during the early stage of a project.","zh":"好研究者在項目初期能容忍混亂。"},{"en":"Tolerating confusion gives the mind time to explore different possibilities.","zh":"容忍混亂讓大腦有時間探索不同可能性。"},{"en":"This phrase is useful when creativity requires patience with uncertainty.","zh":"當創意需要耐心面對不確定時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":4},{"front":"Creativity comes to those who wait","meaning":"創意會來到願意等待的人身上","examples":[{"en":"Creativity comes to those who wait.","zh":"創意會來到願意等待的人身上。"},{"en":"Creativity comes to those who wait means creative ideas often appear after patience, time, and mental space.","zh":"Creativity comes to those who wait 指創意常在耐性、時間和心理空間之後出現。"},{"en":"A writer may get a better ending after leaving the story alone for a day.","zh":"作家把故事放下一天後，可能得到更好的結局。"},{"en":"Waiting can allow hidden connections to form without forcing an answer too quickly.","zh":"等待可以讓隱藏連繫形成，而不是太快強迫答案出現。"},{"en":"This phrase reminds learners that creativity may need time, not just effort.","zh":"這個短語提醒學習者，創意可能需要時間，而不只是努力。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":4},{"front":"in a bit of a fog","meaning":"在有點迷糊的狀態中","examples":[{"en":"Creative people may be happy to wait in a bit of a fog.","zh":"創意人士可能樂於在有點迷糊的狀態中等待。"},{"en":"In a bit of a fog means in a slightly confused or unclear mental state.","zh":"in a bit of a fog 指處於稍微困惑或不清楚的心理狀態。"},{"en":"A student may feel in a bit of a fog when starting a difficult essay.","zh":"學生開始寫困難文章時，可能感到有點迷糊。"},{"en":"Some confusion can be useful if it gives the mind room to explore.","zh":"如果混亂給大腦探索空間，某些迷糊可能有用。"},{"en":"This phrase is informal and describes mild uncertainty.","zh":"這個短語較口語，描述輕微不確定。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":5},{"front":"a price to pay for","meaning":"為……付出的代價","examples":[{"en":"There may be a price to pay for having a creative personality.","zh":"擁有創意型性格可能需要付出代價。"},{"en":"A price to pay for something means a negative cost or consequence that comes with it.","zh":"price to pay for something 指某事帶來的負面成本或後果。"},{"en":"There may be a price to pay for working too many hours, such as tiredness or stress.","zh":"工作太多小時可能要付出代價，例如疲倦或壓力。"},{"en":"Some strengths bring difficulties as well as benefits.","zh":"有些長處既帶來好處，也帶來困難。"},{"en":"This phrase is useful when discussing trade-offs.","zh":"討論取捨時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":5},{"front":"a link has been made between","meaning":"……之間一直被認為有關聯","examples":[{"en":"For centuries, a link has been made between creativity and mental illness.","zh":"幾個世紀以來，人們一直認為創意與精神疾病之間有關聯。"},{"en":"A link has been made between two things means people have suggested or noticed a connection between them.","zh":"a link has been made between two things 指人們提出或注意到兩者之間有連繫。"},{"en":"Researchers have made a link between sleep quality and classroom attention.","zh":"研究人員指出睡眠質素與課堂注意力之間有關聯。"},{"en":"A link suggests a relationship, but it does not always prove direct cause.","zh":"關聯暗示關係，但不一定證明直接因果。"},{"en":"This phrase is useful when discussing research connections.","zh":"討論研究中的連繫時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":5},{"front":"mental illness","meaning":"精神疾病","examples":[{"en":"Researchers have explored the link between creativity and mental illness.","zh":"研究人員探討創意與精神疾病之間的關聯。"},{"en":"Mental illness refers to health conditions that affect mood, thinking, behaviour, or daily functioning.","zh":"mental illness 指影響情緒、思考、行為或日常功能的健康狀況。"},{"en":"A person with mental illness may need support from doctors, family, or counsellors.","zh":"患有精神疾病的人可能需要醫生、家人或輔導員支援。"},{"en":"Talking carefully about mental illness helps reduce shame and misunderstanding.","zh":"謹慎談論精神疾病有助減少羞恥和誤解。"},{"en":"This phrase is common in health, psychology, and social discussions.","zh":"這個短語常見於健康、心理學和社會討論。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":5},{"front":"established artists","meaning":"已成名藝術家；已站穩地位的藝術家","examples":[{"en":"Established artists are more likely to have mood disorders.","zh":"已成名藝術家較有可能有情緒障礙。"},{"en":"Established artists are artists who are already recognised, successful, or respected in their field.","zh":"established artists 指在其領域已被認可、成功或受尊重的藝術家。"},{"en":"An established artist may have exhibitions, awards, and regular audiences.","zh":"已成名藝術家可能有展覽、獎項和固定觀眾。"},{"en":"Public success can bring pressure as well as recognition.","zh":"公眾成功既帶來認可，也可能帶來壓力。"},{"en":"This phrase distinguishes experienced recognised artists from beginners.","zh":"這個短語區分有經驗且受認可的藝術家與初學者。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":5},{"front":"significantly more likely to","meaning":"明顯較有可能……","examples":[{"en":"Established artists are significantly more likely to have mood disorders.","zh":"已成名藝術家明顯較有可能有情緒障礙。"},{"en":"Significantly more likely to means having a much higher chance than another group.","zh":"significantly more likely to 指比另一群體有高得多的機會。"},{"en":"Students who revise regularly are significantly more likely to remember vocabulary in the exam.","zh":"定期溫習的學生明顯較有可能在考試中記得詞彙。"},{"en":"A significant difference suggests the pattern is not small or accidental.","zh":"顯著差異暗示該模式不是微小或偶然的。"},{"en":"This phrase is common in research and statistics.","zh":"這個短語常見於研究和統計。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":5},{"front":"mood disorders","meaning":"情緒障礙","examples":[{"en":"Some established artists suffer from mood disorders.","zh":"有些已成名藝術家患有情緒障礙。"},{"en":"Mood disorders are mental health conditions that strongly affect emotional state.","zh":"mood disorders 指強烈影響情緒狀態的心理健康狀況。"},{"en":"Depression and bipolar disorder are often discussed as mood disorders.","zh":"抑鬱症和躁鬱症常被視為情緒障礙。"},{"en":"Mood disorders can affect sleep, motivation, relationships, and work.","zh":"情緒障礙可以影響睡眠、動機、人際關係和工作。"},{"en":"This phrase is common in psychology and medical contexts.","zh":"這個短語常見於心理學和醫學語境。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":5},{"front":"a change of mood state","meaning":"情緒狀態的轉變","examples":[{"en":"A change of mood state may trigger a creative event.","zh":"情緒狀態的轉變可能觸發創意事件。"},{"en":"A change of mood state means a shift from one emotional condition to another.","zh":"change of mood state 指從一種情緒狀況轉到另一種。"},{"en":"A person may think differently after moving from stress to calmness.","zh":"一個人由壓力轉為平靜後，可能以不同方式思考。"},{"en":"Mood shifts can change attention, memory, and the kinds of ideas that appear.","zh":"情緒轉變可以改變注意力、記憶和出現的想法類型。"},{"en":"This phrase is useful when discussing emotion and thinking.","zh":"討論情緒和思考時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":5},{"front":"the key to triggering","meaning":"觸發……的關鍵","examples":[{"en":"A change of mood state might be the key to triggering creativity.","zh":"情緒狀態的轉變可能是觸發創意的關鍵。"},{"en":"The key to triggering something is the main factor that starts it.","zh":"key to triggering something 指啟動某事的主要因素。"},{"en":"A clear problem may be the key to triggering a useful class discussion.","zh":"清楚問題可能是觸發有用課堂討論的關鍵。"},{"en":"If researchers find the trigger, they can better understand when creativity appears.","zh":"如果研究人員找到觸發因素，就能更好理解創意何時出現。"},{"en":"This phrase is useful when identifying the main cause of an event.","zh":"指出事件主要原因時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":5},{"front":"rather than","meaning":"而不是","examples":[{"en":"A change of mood may matter rather than the negative mood itself.","zh":"重要的可能是情緒轉變，而不是負面情緒本身。"},{"en":"Rather than means instead of, or more accurately not this but that.","zh":"rather than 指而不是，或更準確地說不是這個而是那個。"},{"en":"The problem may be poor planning rather than lack of effort.","zh":"問題可能是計劃差，而不是缺乏努力。"},{"en":"This phrase helps separate the real cause from a mistaken one.","zh":"這個短語幫助區分真正原因和錯誤原因。"},{"en":"It is useful when making a clear contrast.","zh":"作清楚對比時，它很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":5},{"front":"channel this thought style into","meaning":"將這種思維方式引導成……","examples":[{"en":"Intelligence can help channel this thought style into great creativity.","zh":"智力可以幫助將這種思維方式引導成偉大創意。"},{"en":"To channel this thought style into something means to direct a way of thinking toward a useful result.","zh":"channel this thought style into something 指把某種思維方式引向有用結果。"},{"en":"A teacher can channel a talkative student’s energy into debate practice.","zh":"老師可以把愛說話學生的能量引導成辯論練習。"},{"en":"Without guidance, a strong mental style may become scattered instead of productive.","zh":"如果沒有指引，強烈的心理風格可能變得散亂，而不是有產出。"},{"en":"This phrase is useful when describing how raw ability becomes useful output.","zh":"描述原始能力如何變成有用成果時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":5},{"front":"emotional problems","meaning":"情緒問題","examples":[{"en":"Creative thinking can become harmful when combined with emotional problems.","zh":"當創意思維與情緒問題結合時，可能變得有害。"},{"en":"Emotional problems are difficulties involving feelings, mood, stress, or emotional control.","zh":"emotional problems 指與感受、情緒、壓力或情緒控制有關的困難。"},{"en":"A student with emotional problems may need support before academic advice can help.","zh":"有情緒問題的學生可能需要支援，然後學業建議才有幫助。"},{"en":"Emotional problems can make ordinary challenges feel much harder.","zh":"情緒問題可以令普通挑戰感覺困難得多。"},{"en":"This phrase is common in health, counselling, and education.","zh":"這個短語常見於健康、輔導和教育。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":6},{"front":"lateral thinking","meaning":"橫向思維","examples":[{"en":"Lateral thinking can contribute to creativity.","zh":"橫向思維可以有助於創意。"},{"en":"Lateral thinking means solving problems by approaching them from an unusual or indirect angle.","zh":"lateral thinking 指從不尋常或間接角度解決問題。"},{"en":"A student uses lateral thinking when she turns a vocabulary game into a memory exercise.","zh":"學生把詞彙遊戲變成記憶練習時，就是使用橫向思維。"},{"en":"Looking sideways at a problem can reveal solutions that direct logic misses.","zh":"從側面看問題，可以揭示直接邏輯錯過的方案。"},{"en":"This phrase is useful when discussing original problem-solving.","zh":"討論原創解難時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":6},{"front":"divergent thinking","meaning":"發散思維","examples":[{"en":"Divergent thinking can lead to original ideas.","zh":"發散思維可以帶來原創想法。"},{"en":"Divergent thinking means generating many different possible answers instead of one fixed answer.","zh":"divergent thinking 指產生許多不同可能答案，而不是一個固定答案。"},{"en":"A teacher encourages divergent thinking by asking students to list ten uses for a bottle.","zh":"老師要求學生列出膠樽十種用途，就是鼓勵發散思維。"},{"en":"Many options give creative people more material to choose from.","zh":"許多選項給創意人士更多材料可供選擇。"},{"en":"This phrase is central to creativity research.","zh":"這個短語是創意研究的核心。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":6},{"front":"open thinking","meaning":"開放式思維","examples":[{"en":"Open thinking can be useful when people explore new possibilities.","zh":"當人們探索新可能性時，開放式思維可能有用。"},{"en":"Open thinking means being willing to consider different ideas before judging them.","zh":"open thinking 指在判斷之前願意考慮不同想法。"},{"en":"A team uses open thinking when members listen to unusual suggestions without laughing.","zh":"團隊成員聆聽不尋常建議而不嘲笑時，就是使用開放式思維。"},{"en":"Open thinking can create more options before people choose the best one.","zh":"開放式思維可以在人們選擇最佳方案前創造更多選項。"},{"en":"This phrase is useful when discussing brainstorming and exploration.","zh":"討論腦力激盪和探索時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":6},{"front":"lead to mental illness","meaning":"導致精神疾病","examples":[{"en":"Some forms of thinking may lead to mental illness when combined with emotional problems.","zh":"某些思維形式與情緒問題結合時，可能導致精神疾病。"},{"en":"To lead to mental illness means to contribute to serious difficulties in mood, thought, or behaviour.","zh":"lead to mental illness 指促成情緒、思考或行為上的嚴重困難。"},{"en":"Long-term stress may lead to mental health problems if a person has no support.","zh":"如果一個人沒有支援，長期壓力可能導致心理健康問題。"},{"en":"A risk factor does not guarantee illness, but it can increase vulnerability.","zh":"風險因素不保證疾病一定出現，但會增加脆弱性。"},{"en":"This phrase should be used carefully because mental illness has many causes.","zh":"使用這個短語時應小心，因為精神疾病有許多原因。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":6},{"front":"identify a mechanism","meaning":"找出一個機制","examples":[{"en":"Jordan Peterson believes he has identified a mechanism.","zh":"Jordan Peterson 認為他已找出一個機制。"},{"en":"To identify a mechanism means to find the process or system that explains how something happens.","zh":"identify a mechanism 指找到解釋某事如何發生的過程或系統。"},{"en":"A doctor may identify a mechanism that explains why a medicine causes sleepiness.","zh":"醫生可能找出一個機制，解釋為何某藥物令人昏睡。"},{"en":"Finding a mechanism helps move from description to explanation.","zh":"找出機制有助從描述走向解釋。"},{"en":"This phrase is common in science and research.","zh":"這個短語常見於科學和研究。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":6},{"front":"be open to incoming stimuli","meaning":"對傳入刺激較開放","examples":[{"en":"The brains of creative people may be more open to incoming stimuli.","zh":"創意人士的大腦可能對傳入刺激較開放。"},{"en":"To be open to incoming stimuli means to allow more sights, sounds, ideas, or signals into attention.","zh":"be open to incoming stimuli 指讓更多視覺、聲音、想法或訊號進入注意力。"},{"en":"A tired student may be too open to classroom noise and find it hard to focus.","zh":"疲倦學生可能對課室噪音過度開放，因而難以集中。"},{"en":"Being open to more stimuli can provide more material for new ideas, but it may also create overload.","zh":"對更多刺激開放可以提供更多創意材料，但也可能造成過載。"},{"en":"This phrase is useful when discussing attention and perception.","zh":"討論注意力和感知時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":6},{"front":"feed a mass of information into","meaning":"將大量資料輸入……","examples":[{"en":"Our senses feed a mass of information into our brains.","zh":"我們的感官將大量資料輸入大腦。"},{"en":"To feed a mass of information into something means to send a large amount of data into it.","zh":"feed a mass of information into something 指把大量數據送入某系統。"},{"en":"News apps can feed a mass of information into people’s phones every morning.","zh":"新聞應用程式每天早上可以將大量資料輸入人們的手機。"},{"en":"Too much information can overwhelm a system if it cannot filter properly.","zh":"如果系統不能適當過濾，太多資料可能令它不勝負荷。"},{"en":"This phrase is useful when describing information flow.","zh":"描述資訊流動時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":6},{"front":"block or ignore","meaning":"阻隔或忽略","examples":[{"en":"The brain has to block or ignore most incoming information.","zh":"大腦必須阻隔或忽略大部分傳入資訊。"},{"en":"To block or ignore information means to stop it from entering attention or choose not to focus on it.","zh":"block or ignore information 指阻止資訊進入注意力，或選擇不專注於它。"},{"en":"Students may block or ignore background chatter when concentrating on homework.","zh":"學生做功課時可能阻隔或忽略背景聊天聲。"},{"en":"Filtering information helps people avoid becoming overwhelmed.","zh":"過濾資訊幫助人避免被壓垮。"},{"en":"This phrase is useful when discussing attention, focus, and distraction.","zh":"討論注意力、專注和分心時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":6},{"front":"save someone from being snowed under","meaning":"免得某人被大量事情壓垮","examples":[{"en":"The brain blocks information to save us from being snowed under.","zh":"大腦阻隔資訊，免得我們被大量資訊壓垮。"},{"en":"To save someone from being snowed under means to prevent them from being overwhelmed by too much work or information.","zh":"save someone from being snowed under 指防止某人被太多工作或資訊壓垮。"},{"en":"A clear checklist can save students from being snowed under before exams.","zh":"清楚清單可以免得學生在考試前被大量事情壓垮。"},{"en":"Filtering tasks helps people focus on what matters first.","zh":"過濾任務幫助人先專注重要事項。"},{"en":"This phrase is informal and describes protection from overload.","zh":"這個短語較口語，描述避免過載。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":6},{"front":"latent inhibition","meaning":"潛在抑制","examples":[{"en":"Peterson calls this filtering process latent inhibition.","zh":"Peterson 把這個過濾過程稱為潛在抑制。"},{"en":"Latent inhibition is a mental filtering process that helps the brain ignore familiar or irrelevant stimuli.","zh":"latent inhibition 指幫助大腦忽略熟悉或不相關刺激的心理過濾過程。"},{"en":"A student with strong filtering may stop noticing the hum of an air conditioner.","zh":"過濾能力強的學生可能不再注意冷氣機嗡嗡聲。"},{"en":"Lower filtering may allow more unusual details to enter awareness.","zh":"較低過濾可能讓更多不尋常細節進入意識。"},{"en":"This phrase is technical and belongs to psychology and neuroscience.","zh":"這個短語較技術性，屬於心理學和神經科學。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":6},{"front":"a reasonably high IQ","meaning":"相當高的智商","examples":[{"en":"People with a reasonably high IQ may handle more incoming information.","zh":"智商相當高的人可能能處理更多傳入資訊。"},{"en":"A reasonably high IQ means an intelligence-test score that is fairly high, though not necessarily exceptional.","zh":"reasonably high IQ 指智商測驗分數相當高，但不一定極端出眾。"},{"en":"A student with a reasonably high IQ may solve logical puzzles quickly.","zh":"智商相當高的學生可能很快解決邏輯謎題。"},{"en":"Higher reasoning ability may help people organise complex information better.","zh":"較高推理能力可能幫助人更好整理複雜資訊。"},{"en":"This phrase describes moderate-to-high measured intelligence.","zh":"這個短語描述中高程度的測量智力。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":7},{"front":"working memory","meaning":"工作記憶","examples":[{"en":"A good working memory helps people juggle more data.","zh":"良好工作記憶幫助人同時處理更多數據。"},{"en":"Working memory is the mental ability to hold and use information for a short time.","zh":"working memory 指短時間保持並使用資訊的心智能力。"},{"en":"A student uses working memory when remembering a question while planning an answer.","zh":"學生記住問題同時規劃答案時，就是使用工作記憶。"},{"en":"Strong working memory helps people compare ideas without losing track.","zh":"強工作記憶幫助人比較想法而不失去脈絡。"},{"en":"This phrase is common in psychology and learning science.","zh":"這個短語常見於心理學和學習科學。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":7},{"front":"juggle more of the data","meaning":"同時處理更多數據","examples":[{"en":"Creative people may be able to juggle more of the data.","zh":"創意人士可能能同時處理更多數據。"},{"en":"To juggle more of the data means to handle several pieces of information at the same time.","zh":"juggle more of the data 指同時處理幾項資訊。"},{"en":"A project manager must juggle deadlines, budgets, staff, and customer needs.","zh":"項目經理必須同時處理期限、預算、人手和客戶需要。"},{"en":"Handling more information can help people notice unusual connections.","zh":"處理更多資訊可以幫助人注意到不尋常連繫。"},{"en":"This phrase is useful when describing mental multitasking.","zh":"描述心理上的多工處理時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":7},{"front":"be open to more possibilities","meaning":"對更多可能性持開放態度","examples":[{"en":"People with less latent inhibition may be open to more possibilities.","zh":"潛在抑制較低的人可能對更多可能性持開放態度。"},{"en":"To be open to more possibilities means to consider more options or interpretations.","zh":"be open to more possibilities 指願意考慮更多選項或解釋。"},{"en":"A designer who is open to more possibilities may test several layouts before choosing one.","zh":"對更多可能性開放的設計師可能在選擇前測試幾種版面。"},{"en":"Openness can produce original ideas because people do not reject unusual options too quickly.","zh":"開放態度可以產生原創想法，因為人們不會太快拒絕不尋常選項。"},{"en":"This phrase is useful when discussing imagination and flexibility.","zh":"討論想像力和靈活性時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":7},{"front":"the downside of","meaning":"……的壞處；不利一面","examples":[{"en":"The downside of extremely low latent inhibition may be confusion.","zh":"極低潛在抑制的壞處可能是混亂。"},{"en":"The downside of something is its negative side or disadvantage.","zh":"downside of something 指某事的負面一面或缺點。"},{"en":"The downside of studying late is that students may feel tired the next day.","zh":"深夜溫習的壞處是學生第二天可能疲倦。"},{"en":"Every strength may have a downside if it becomes too extreme.","zh":"每種長處若變得太極端，都可能有壞處。"},{"en":"This phrase is useful when presenting a balanced view.","zh":"提出平衡觀點時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":7},{"front":"extremely low latent inhibition","meaning":"極低的潛在抑制","examples":[{"en":"Extremely low latent inhibition may create a confused thought style.","zh":"極低的潛在抑制可能造成混亂的思維方式。"},{"en":"Extremely low latent inhibition means very weak filtering of incoming information.","zh":"extremely low latent inhibition 指對傳入資訊的過濾非常弱。"},{"en":"A person with very low filtering may notice too many sounds, sights, and details at once.","zh":"過濾很弱的人可能同時注意到太多聲音、景象和細節。"},{"en":"Too little filtering can produce many ideas but also mental overload.","zh":"太少過濾可以產生許多想法，但也可能造成心理過載。"},{"en":"This phrase is technical and describes an extreme attention pattern.","zh":"這個短語較技術性，描述極端注意力模式。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":7},{"front":"a confused thought style","meaning":"混亂的思維方式","examples":[{"en":"A confused thought style may predispose people to mental illness.","zh":"混亂的思維方式可能令某些人較容易患上精神疾病。"},{"en":"A confused thought style is a way of thinking that is disorganised, unclear, or hard to control.","zh":"confused thought style 指混亂、不清楚或難以控制的思考方式。"},{"en":"A student under stress may write in a confused thought style, jumping between unrelated points.","zh":"壓力下的學生可能以混亂思維方式寫作，在不相關的點之間跳來跳去。"},{"en":"Confused thinking can make decisions harder and increase emotional pressure.","zh":"混亂思考可以令決策更困難並增加情緒壓力。"},{"en":"This phrase is useful when discussing mental organisation.","zh":"討論心理組織時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":7},{"front":"predispose someone to","meaning":"使某人較容易患上……","examples":[{"en":"Extremely low latent inhibition may predispose people to mental illness.","zh":"極低潛在抑制可能使人較容易患上精神疾病。"},{"en":"To predispose someone to something means to make them more likely to experience it.","zh":"predispose someone to something 指令某人較有可能經歷某事。"},{"en":"Lack of sleep may predispose students to poor concentration.","zh":"睡眠不足可能使學生較容易專注力差。"},{"en":"A predisposition increases risk, but it does not guarantee the result.","zh":"predisposition 會增加風險，但不保證結果一定發生。"},{"en":"This phrase is common in health and psychology.","zh":"這個短語常見於健康和心理學。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":7},{"front":"a prerequisite for creativity","meaning":"創意的先決條件","examples":[{"en":"Mental illness is not a prerequisite for creativity.","zh":"精神疾病不是創意的先決條件。"},{"en":"A prerequisite for creativity is something that must exist before creativity can happen.","zh":"prerequisite for creativity 指創意出現前必須存在的條件。"},{"en":"A university may require basic English as a prerequisite for an advanced writing course.","zh":"大學可能要求基本英語作為高階寫作課程的先決條件。"},{"en":"Saying something is not a prerequisite means creativity can happen without it.","zh":"說某物不是先決條件，意思是沒有它也可以有創意。"},{"en":"This phrase is useful when discussing necessary conditions.","zh":"討論必要條件時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":7},{"front":"cognitive traits","meaning":"認知特徵","examples":[{"en":"Mental illness and creativity may share some cognitive traits.","zh":"精神疾病和創意可能共享某些認知特徵。"},{"en":"Cognitive traits are features of thinking, attention, memory, or mental processing.","zh":"cognitive traits 指思考、注意力、記憶或心理處理方面的特徵。"},{"en":"A strong memory and quick pattern recognition are cognitive traits useful for learning.","zh":"強記憶和快速辨認模式是對學習有用的認知特徵。"},{"en":"Shared cognitive traits can explain why two conditions appear related without being identical.","zh":"共同認知特徵可以解釋為何兩種情況看似相關但並不相同。"},{"en":"This phrase is common in psychology and brain science.","zh":"這個短語常見於心理學和腦科學。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":7},{"front":"the creative act itself","meaning":"創作行為本身","examples":[{"en":"Researchers also studied the creative act itself.","zh":"研究人員也研究創作行為本身。"},{"en":"The creative act itself means the actual moment or process of producing something original.","zh":"creative act itself 指產生原創事物的實際時刻或過程。"},{"en":"A music teacher may study the creative act itself by watching how students compose melodies.","zh":"音樂老師可能透過觀察學生如何作曲來研究創作行為本身。"},{"en":"Focusing on the act itself helps researchers see what happens during creation, not only before or after it.","zh":"聚焦行為本身幫助研究人員看見創作期間發生甚麼，而不只是前後。"},{"en":"This phrase is useful when analysing the process of making new ideas.","zh":"分析新想法如何產生時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":7},{"front":"the creative brain at work","meaning":"正在運作的創意大腦","examples":[{"en":"Martindale studied the creative brain at work.","zh":"Martindale 研究正在運作的創意大腦。"},{"en":"The creative brain at work means the brain while it is actively producing creative ideas.","zh":"creative brain at work 指大腦正在積極產生創意想法時的狀態。"},{"en":"Researchers may scan the creative brain at work while artists draw or writers invent stories.","zh":"研究人員可能在藝術家繪畫或作家構思故事時掃描正在運作的創意大腦。"},{"en":"Studying the brain during activity can reveal patterns not visible during rest.","zh":"研究活動中的大腦可以揭示休息時看不到的模式。"},{"en":"This phrase is useful when discussing creativity and neuroscience.","zh":"討論創意和神經科學時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":8},{"front":"a network of scalp electrodes","meaning":"一組頭皮電極網絡","examples":[{"en":"Martindale used a network of scalp electrodes to measure brain activity.","zh":"Martindale 使用一組頭皮電極網絡來測量大腦活動。"},{"en":"A network of scalp electrodes is a set of small sensors placed on the head to record electrical brain signals.","zh":"network of scalp electrodes 指放在頭皮上的一組小感應器，用來記錄大腦電訊號。"},{"en":"In a lab, participants may wear scalp electrodes while solving memory tasks.","zh":"在實驗室中，參加者可能戴上頭皮電極完成記憶任務。"},{"en":"These electrodes help researchers observe brain activity without surgery.","zh":"這些電極幫助研究人員不經手術觀察大腦活動。"},{"en":"This phrase is technical and belongs to neuroscience experiments.","zh":"這個短語較技術性，屬於神經科學實驗。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":8},{"front":"record an electroencephalogram","meaning":"記錄腦電圖","examples":[{"en":"The electrodes helped him record an electroencephalogram.","zh":"這些電極幫助他記錄腦電圖。"},{"en":"To record an electroencephalogram means to measure and write down the brain’s electrical activity.","zh":"record an electroencephalogram 指測量並記錄大腦的電活動。"},{"en":"A hospital may record an electroencephalogram to study unusual brain activity.","zh":"醫院可能記錄腦電圖來研究異常大腦活動。"},{"en":"Recording brain waves helps researchers connect mental states with brain patterns.","zh":"記錄腦波幫助研究人員把心理狀態與大腦模式連接起來。"},{"en":"This phrase is technical and often shortened to record an EEG.","zh":"這個短語較技術性，常縮寫為 record an EEG。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":8},{"front":"the pattern of brain waves","meaning":"腦波模式","examples":[{"en":"An electroencephalogram records the pattern of brain waves.","zh":"腦電圖記錄腦波模式。"},{"en":"The pattern of brain waves means the organised electrical rhythms produced by the brain.","zh":"pattern of brain waves 指大腦產生的有組織電節奏。"},{"en":"Different brain-wave patterns may appear during sleep, relaxation, or intense focus.","zh":"睡眠、放鬆或高度專注時可能出現不同腦波模式。"},{"en":"Changes in brain-wave patterns can suggest changes in mental state.","zh":"腦波模式改變可以暗示心理狀態改變。"},{"en":"This phrase is common in neuroscience and sleep research.","zh":"這個短語常見於神經科學和睡眠研究。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":8},{"front":"make up stories","meaning":"編故事","examples":[{"en":"Participants made up stories during the experiment.","zh":"參加者在實驗期間編故事。"},{"en":"To make up stories means to invent stories from imagination.","zh":"make up stories 指用想像力創作故事。"},{"en":"Children may make up stories about animals that talk and go to school.","zh":"孩子可能編關於會說話並上學的動物的故事。"},{"en":"Making up stories can show how people combine memory, imagination, and language.","zh":"編故事可以顯示人如何組合記憶、想像和語言。"},{"en":"This phrase is useful in creativity, writing, and classroom activities.","zh":"這個短語適用於創意、寫作和課堂活動。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":8},{"front":"inspiration and elaboration","meaning":"靈感與發展","examples":[{"en":"Creativity has two stages: inspiration and elaboration.","zh":"創意有兩個階段：靈感與發展。"},{"en":"Inspiration and elaboration mean first getting an idea and then developing it in detail.","zh":"inspiration and elaboration 指先得到想法，然後詳細發展它。"},{"en":"A student may get inspiration for an essay on the bus, then use elaboration at home to build paragraphs.","zh":"學生可能在巴士上得到文章靈感，然後在家中發展成段落。"},{"en":"A creative idea often needs both a spark and careful development.","zh":"創意想法通常需要火花，也需要仔細發展。"},{"en":"This phrase is useful when describing stages of creative work.","zh":"描述創作工作的階段時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":8},{"front":"be characterised by","meaning":"以……為特徵","examples":[{"en":"Each stage is characterised by a different state of mind.","zh":"每個階段以不同心理狀態為特徵。"},{"en":"To be characterised by something means to have it as a typical or defining feature.","zh":"be characterised by something 指以某物作為典型或定義性特徵。"},{"en":"A good classroom is characterised by clear rules and active participation.","zh":"好課室以清楚規則和積極參與為特徵。"},{"en":"Identifying key features helps people understand how one stage differs from another.","zh":"找出關鍵特徵幫助人理解一個階段如何不同於另一個階段。"},{"en":"This phrase is common in formal description and analysis.","zh":"這個短語常見於正式描述和分析。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":8},{"front":"states of mind","meaning":"心理狀態","examples":[{"en":"The two stages involve very different states of mind.","zh":"兩個階段涉及非常不同的心理狀態。"},{"en":"States of mind are mental or emotional conditions at a particular time.","zh":"states of mind 指某一時刻的心理或情緒狀況。"},{"en":"A calm state of mind helps students think clearly during exams.","zh":"平靜的心理狀態幫助學生在考試中清楚思考。"},{"en":"Different tasks may require different mental states, such as relaxation or focus.","zh":"不同任務可能需要不同心理狀態，例如放鬆或專注。"},{"en":"This phrase is useful when discussing emotion, attention, and thinking.","zh":"討論情緒、注意力和思考時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":8},{"front":"dream up","meaning":"構想出；想出","examples":[{"en":"Participants were quiet while they tried to dream up stories.","zh":"參加者嘗試構想故事時很安靜。"},{"en":"To dream up something means to imagine or invent it, often creatively.","zh":"dream up something 指想像或創造某物，通常帶創意。"},{"en":"Students may dream up a new game for vocabulary practice.","zh":"學生可能構想出新的詞彙練習遊戲。"},{"en":"Dreaming up ideas usually requires space to explore rather than immediate judgement.","zh":"構想想法通常需要探索空間，而不是立即被評判。"},{"en":"This phrase is informal and creative.","zh":"這個短語較口語，帶有創意意味。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":8},{"front":"surprisingly quiet","meaning":"出乎意料地安靜","examples":[{"en":"Their brains were surprisingly quiet during the inspiration stage.","zh":"在靈感階段，他們的大腦出乎意料地安靜。"},{"en":"Surprisingly quiet means quieter or less active than expected.","zh":"surprisingly quiet 指比預期更安靜或活動更少。"},{"en":"A normally noisy classroom may be surprisingly quiet before an important exam.","zh":"平時嘈吵的課室在重要考試前可能出乎意料地安靜。"},{"en":"A quiet state may allow hidden mental connections to form.","zh":"安靜狀態可能讓隱藏的心理連繫形成。"},{"en":"This phrase shows contrast between expectation and reality.","zh":"這個短語顯示預期與現實之間的對比。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":8},{"front":"dominant activity","meaning":"主導活動","examples":[{"en":"The dominant activity in the brain was alpha waves.","zh":"大腦中的主導活動是阿爾法波。"},{"en":"Dominant activity means the main or most noticeable activity in a system.","zh":"dominant activity 指一個系統中主要或最明顯的活動。"},{"en":"During a busy lunch hour, the dominant activity in a café is serving customers.","zh":"在繁忙午餐時段，咖啡店的主導活動是服務顧客。"},{"en":"Identifying the dominant activity helps researchers know what is happening most strongly.","zh":"找出主導活動幫助研究人員知道甚麼最強烈地發生。"},{"en":"This phrase is useful in science, business, and observation.","zh":"這個短語適用於科學、商業和觀察。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":8},{"front":"alpha waves","meaning":"阿爾法波","examples":[{"en":"Alpha waves appeared while the participants were dreaming up stories.","zh":"當參加者構想故事時，阿爾法波出現。"},{"en":"Alpha waves are brain-wave patterns often linked with relaxed wakefulness.","zh":"alpha waves 指常與放鬆清醒狀態有關的腦波模式。"},{"en":"A person resting quietly with closed eyes may show more alpha waves.","zh":"一個人閉眼安靜休息時，可能顯示更多阿爾法波。"},{"en":"Alpha waves can suggest that the brain is calm rather than highly alert.","zh":"阿爾法波可以暗示大腦處於平靜而非高度警覺狀態。"},{"en":"This phrase is technical and common in brain-wave research.","zh":"這個短語較技術性，常見於腦波研究。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":9},{"front":"cortical arousal","meaning":"大腦皮層覺醒","examples":[{"en":"Alpha waves indicate a low level of cortical arousal.","zh":"阿爾法波顯示低水平大腦皮層覺醒。"},{"en":"Cortical arousal means the level of activity or alertness in the brain’s outer layer.","zh":"cortical arousal 指大腦外層的活動或警覺水平。"},{"en":"Strong focus during a difficult task may involve higher cortical arousal.","zh":"完成困難任務時的高度專注可能涉及較高大腦皮層覺醒。"},{"en":"Changes in arousal can show whether the brain is relaxed or working hard.","zh":"覺醒水平改變可以顯示大腦是放鬆還是努力工作。"},{"en":"This phrase is technical and belongs to neuroscience.","zh":"這個短語較技術性，屬於神經科學。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":9},{"front":"a relaxed state","meaning":"放鬆狀態","examples":[{"en":"The brain seemed to be in a relaxed state.","zh":"大腦似乎處於放鬆狀態。"},{"en":"A relaxed state is a calm condition with lower tension or pressure.","zh":"relaxed state 指較少緊張或壓力的平靜狀況。"},{"en":"A student may enter a relaxed state after slow breathing before a speaking test.","zh":"學生在口語測驗前慢慢呼吸後，可能進入放鬆狀態。"},{"en":"Relaxation can make it easier for ideas to appear without force.","zh":"放鬆可以令想法較容易自然出現。"},{"en":"This phrase is useful when discussing body, mind, and performance.","zh":"討論身體、心理和表現時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":9},{"front":"the conscious mind","meaning":"意識思維","examples":[{"en":"The conscious mind was quiet during the inspiration stage.","zh":"在靈感階段，意識思維很安靜。"},{"en":"The conscious mind is the part of the mind involved in active awareness and deliberate thinking.","zh":"conscious mind 指參與主動意識和刻意思考的心理部分。"},{"en":"When solving a maths problem step by step, a student uses the conscious mind.","zh":"學生一步步解數學題時，就是使用意識思維。"},{"en":"If the conscious mind becomes quiet, unconscious connections may have more space to develop.","zh":"如果意識思維變得安靜，無意識連繫可能有更多空間發展。"},{"en":"This phrase is useful when comparing deliberate thought with hidden mental processes.","zh":"比較刻意思考與隱藏心理過程時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":9},{"front":"make connections behind the scenes","meaning":"在背後建立聯繫","examples":[{"en":"The brain was making connections behind the scenes.","zh":"大腦正在背後建立聯繫。"},{"en":"To make connections behind the scenes means to link ideas quietly without obvious conscious effort.","zh":"make connections behind the scenes 指在沒有明顯刻意努力下靜靜連接想法。"},{"en":"A student may suddenly understand a lesson because her brain was making connections overnight.","zh":"學生可能突然理解一課，因為大腦一夜之間在背後建立聯繫。"},{"en":"Hidden connections can appear later as a new idea or solution.","zh":"隱藏連繫之後可以以新想法或解決方案出現。"},{"en":"This phrase is metaphorical and useful for explaining unconscious thinking.","zh":"這個短語是比喻性，適合解釋無意識思考。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":9},{"front":"stages of sleep","meaning":"睡眠階段","examples":[{"en":"The brain activity was similar to activity in some stages of sleep.","zh":"這種大腦活動與某些睡眠階段的活動相似。"},{"en":"Stages of sleep are different phases the brain and body pass through while sleeping.","zh":"stages of sleep 指睡眠期間大腦和身體經過的不同階段。"},{"en":"Deep sleep and dreaming sleep are different stages of sleep.","zh":"深層睡眠和做夢睡眠是不同睡眠階段。"},{"en":"Different stages can show different brain-wave patterns.","zh":"不同階段可以顯示不同腦波模式。"},{"en":"This phrase is common in sleep science and neuroscience.","zh":"這個短語常見於睡眠科學和神經科學。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":9},{"front":"sleep and relaxation","meaning":"睡眠和放鬆","examples":[{"en":"Sleep and relaxation can help people be creative.","zh":"睡眠和放鬆可以幫助人有創意。"},{"en":"Sleep and relaxation are states that allow the body and mind to rest.","zh":"sleep and relaxation 指讓身體和大腦休息的狀態。"},{"en":"A student may solve a writing problem after a walk, a shower, or a good night’s sleep.","zh":"學生可能在散步、洗澡或好好睡一晚後解決寫作問題。"},{"en":"Rest can reduce pressure and allow hidden ideas to connect.","zh":"休息可以減少壓力，並讓隱藏想法連接起來。"},{"en":"This phrase is useful when discussing recovery, creativity, and mental performance.","zh":"討論恢復、創意和心理表現時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":9},{"front":"alpha wave activity dropped off","meaning":"阿爾法波活動下降","examples":[{"en":"Alpha wave activity dropped off when people worked on their stories.","zh":"當人們發展故事時，阿爾法波活動下降。"},{"en":"Alpha wave activity dropped off means the amount of alpha-wave brain activity decreased.","zh":"alpha wave activity dropped off 指阿爾法波大腦活動量減少。"},{"en":"A student’s relaxation may drop off when the exam paper is placed on the desk.","zh":"當試卷放在桌上時，學生的放鬆程度可能下降。"},{"en":"A decrease in alpha waves may suggest the brain has become more active and alert.","zh":"阿爾法波減少可能暗示大腦變得更活躍和警覺。"},{"en":"This phrase is useful when describing a measurable decline.","zh":"描述可測量下降時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":9},{"front":"increased cortical arousal","meaning":"大腦皮層覺醒增加","examples":[{"en":"The busier brain showed increased cortical arousal.","zh":"較忙碌的大腦顯示大腦皮層覺醒增加。"},{"en":"Increased cortical arousal means higher activity or alertness in the brain’s outer layer.","zh":"increased cortical arousal 指大腦外層活動或警覺水平提高。"},{"en":"A difficult puzzle may produce increased cortical arousal because the brain must work harder.","zh":"困難謎題可能產生較高大腦皮層覺醒，因為大腦必須更努力工作。"},{"en":"Higher arousal can appear when people analyse, organise, or develop ideas.","zh":"當人們分析、組織或發展想法時，較高覺醒可能出現。"},{"en":"This phrase is technical and used in neuroscience.","zh":"這個短語較技術性，用於神經科學。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":9},{"front":"organised thinking","meaning":"有組織的思考","examples":[{"en":"The development stage involved more organised thinking.","zh":"發展階段涉及更多有組織的思考。"},{"en":"Organised thinking means clear, structured, and purposeful thinking.","zh":"organised thinking 指清楚、有結構和有目的的思考。"},{"en":"A student uses organised thinking when turning notes into a logical essay plan.","zh":"學生把筆記變成有邏輯的文章計劃時，就是使用有組織的思考。"},{"en":"Organised thinking helps raw ideas become something understandable and useful.","zh":"有組織的思考幫助原始想法變成可理解和有用的東西。"},{"en":"This phrase is useful when discussing planning and development.","zh":"討論計劃和發展時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":9},{"front":"strikingly","meaning":"引人注目的是","examples":[{"en":"Strikingly, the most creative people showed the biggest change in brain activity.","zh":"引人注目的是，最有創意的人顯示出最大的大腦活動變化。"},{"en":"Strikingly means in a way that is very noticeable or surprising.","zh":"strikingly 指以非常明顯或令人驚訝的方式。"},{"en":"Strikingly, the quietest student gave the most confident presentation.","zh":"引人注目的是，最安靜的學生作出了最自信的匯報。"},{"en":"This word signals that the next point deserves special attention.","zh":"這個詞表示下一點值得特別注意。"},{"en":"It is useful when introducing an impressive contrast or result.","zh":"引入令人印象深刻的對比或結果時，它很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":9},{"front":"the biggest difference in","meaning":"……中最大的差異","examples":[{"en":"The most creative participants showed the biggest difference in brain activity.","zh":"最有創意的參加者在大腦活動中顯示最大差異。"},{"en":"The biggest difference in something means the largest change or contrast found in that area.","zh":"biggest difference in something 指在某方面發現的最大變化或對比。"},{"en":"A teacher may see the biggest difference in writing quality after students learn paragraph structure.","zh":"老師可能在學生學會段落結構後，看見寫作質素中的最大差異。"},{"en":"Large differences can help researchers identify what matters most.","zh":"大差異可以幫助研究人員找出最重要因素。"},{"en":"This phrase is useful when comparing results.","zh":"比較結果時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":10},{"front":"creative storylines","meaning":"有創意的故事情節","examples":[{"en":"Those participants produced the most creative storylines.","zh":"那些參加者創作出最有創意的故事情節。"},{"en":"Creative storylines are original and interesting plots or sequences of events in stories.","zh":"creative storylines 指故事中原創而有趣的情節或事件發展。"},{"en":"A film with creative storylines may surprise viewers without confusing them.","zh":"有創意的故事情節可以令觀眾驚喜而不混亂。"},{"en":"Strong storylines turn ideas into events that audiences can follow.","zh":"強故事情節把想法變成觀眾能跟隨的事件。"},{"en":"This phrase is useful in writing, film, and storytelling.","zh":"這個短語適用於寫作、電影和敘事。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":10},{"front":"background brain activity","meaning":"背景腦活動","examples":[{"en":"Nothing in their background brain activity marked them as creative.","zh":"他們的背景腦活動中沒有任何東西顯示他們有創意。"},{"en":"Background brain activity is the brain’s normal activity when a person is not doing the main task being studied.","zh":"background brain activity 指人在未進行主要研究任務時的大腦正常活動。"},{"en":"Researchers may compare background brain activity with brain activity during problem-solving.","zh":"研究人員可能比較背景腦活動與解難時的大腦活動。"},{"en":"If background activity shows nothing special, creativity may depend more on flexible changes during tasks.","zh":"如果背景活動沒有顯示特別之處，創意可能更取決於任務期間的靈活變化。"},{"en":"This phrase is technical and useful in brain research.","zh":"這個短語較技術性，適用於腦部研究。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":10},{"front":"mark someone as","meaning":"顯示某人是……","examples":[{"en":"Background brain activity did not mark someone as creative or uncreative.","zh":"背景腦活動沒有顯示某人是有創意或沒有創意的。"},{"en":"To mark someone as something means to show or identify them as that type of person.","zh":"mark someone as something 指顯示或識別某人屬於某類人。"},{"en":"One low test score should not mark a student as lazy.","zh":"一次低測驗分數不應顯示學生就是懶惰。"},{"en":"Labels can be misleading if they are based on too little evidence.","zh":"如果標籤基於太少證據，可能會誤導。"},{"en":"This phrase is useful when discussing signs, labels, and judgement.","zh":"討論跡象、標籤和判斷時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":10},{"front":"shift gear","meaning":"轉換思維模式","examples":[{"en":"The less creative person may find it hard to shift gear.","zh":"較少創意的人可能覺得難以轉換思維模式。"},{"en":"To shift gear means to change approach, mood, or way of thinking.","zh":"shift gear 指改變方法、心情或思考方式。"},{"en":"A student must shift gear when moving from brainstorming to writing a final essay.","zh":"學生從腦力激盪轉到寫終稿時，必須轉換思維模式。"},{"en":"People who cannot shift gear may stay stuck in one type of thinking.","zh":"不能轉換思維模式的人可能困在單一思考方式中。"},{"en":"This phrase is informal and useful for mental flexibility.","zh":"這個短語較口語，適合描述思維靈活性。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":10},{"front":"different kinds of thinking","meaning":"不同類型的思考","examples":[{"en":"Creativity requires different kinds of thinking.","zh":"創意需要不同類型的思考。"},{"en":"Different kinds of thinking are different mental approaches, such as imagining, analysing, judging, or organising.","zh":"different kinds of thinking 指不同心理方法，例如想像、分析、判斷或組織。"},{"en":"A group project may need different kinds of thinking: one person creates ideas, another checks details.","zh":"小組項目可能需要不同類型的思考：一人創造想法，另一人檢查細節。"},{"en":"Creativity improves when people can switch between open exploration and careful evaluation.","zh":"當人們能在開放探索和仔細評估之間切換，創意會改善。"},{"en":"This phrase is useful when explaining why creativity is not one single skill.","zh":"解釋創意不是單一技能時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":10},{"front":"move between these states intuitively","meaning":"憑直覺在這些狀態之間切換","examples":[{"en":"Very creative people move between these states intuitively.","zh":"非常有創意的人憑直覺在這些狀態之間切換。"},{"en":"To move between these states intuitively means to switch naturally between mental states without deliberate instruction.","zh":"move between these states intuitively 指不用刻意指令，自然地在心理狀態之間轉換。"},{"en":"A skilled speaker may move intuitively between humour and seriousness during a talk.","zh":"熟練演講者可能在演講中憑直覺在幽默和嚴肅之間切換。"},{"en":"Intuitive switching helps people adapt to what a task needs at each moment.","zh":"直覺切換幫助人適應任務每一刻的需要。"},{"en":"This phrase is useful when describing automatic mental flexibility.","zh":"描述自動心理靈活性時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":10},{"front":"mental flexibility","meaning":"思維靈活性","examples":[{"en":"Creativity seems to depend on mental flexibility.","zh":"創意似乎取決於思維靈活性。"},{"en":"Mental flexibility is the ability to change thinking style or approach when needed.","zh":"mental flexibility 指在需要時改變思考方式或方法的能力。"},{"en":"A student shows mental flexibility when she tries a new method after the first one fails.","zh":"學生在第一個方法失敗後嘗試新方法，就是展現思維靈活性。"},{"en":"Flexible thinking helps people avoid getting trapped by one idea.","zh":"靈活思考幫助人避免被單一想法困住。"},{"en":"This phrase is useful in creativity, learning, and problem-solving.","zh":"這個短語適用於創意、學習和解難。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":10},{"front":"a two-step process","meaning":"兩步驟過程","examples":[{"en":"Creativity may not be a simple two-step process.","zh":"創意可能不是簡單的兩步驟過程。"},{"en":"A two-step process is a process with two clear stages.","zh":"two-step process 指有兩個清楚階段的過程。"},{"en":"Logging into an account may be a two-step process if it requires a password and a code.","zh":"如果登入帳戶需要密碼和驗證碼，它可能是兩步驟過程。"},{"en":"Some real processes are more complex than neat two-step models suggest.","zh":"有些真實過程比整齊的兩步模型所暗示的更複雜。"},{"en":"This phrase is useful when simplifying or questioning a process.","zh":"簡化或質疑一個過程時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":10},{"front":"toggle between two states","meaning":"在兩種狀態之間切換","examples":[{"en":"Creativity may involve toggling between two states.","zh":"創意可能涉及在兩種狀態之間切換。"},{"en":"To toggle between two states means to switch back and forth between two conditions or modes.","zh":"toggle between two states 指在兩種條件或模式之間來回轉換。"},{"en":"A student may toggle between planning and writing while preparing an essay.","zh":"學生準備文章時，可能在規劃和寫作之間切換。"},{"en":"Switching between modes can help people generate ideas and then improve them.","zh":"在模式之間切換可以幫助人產生想法，然後改善它們。"},{"en":"This phrase is useful when discussing repeated mental switching.","zh":"討論重複心理切換時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":10},{"front":"communication between the sides of the brain","meaning":"大腦兩側之間的溝通","examples":[{"en":"Communication between the sides of the brain is also important.","zh":"大腦兩側之間的溝通也很重要。"},{"en":"Communication between the sides of the brain means information passing between the left and right hemispheres.","zh":"communication between the sides of the brain 指資訊在左右腦半球之間傳遞。"},{"en":"Some tasks may require both language processing and visual imagination to work together.","zh":"有些任務可能需要語言處理和視覺想像共同運作。"},{"en":"Better communication between brain areas may support complex thinking.","zh":"大腦區域之間更好的溝通可能支援複雜思考。"},{"en":"This phrase is technical and useful in neuroscience discussions.","zh":"這個短語較技術性，適用於神經科學討論。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":10},{"front":"another aspect of creativity","meaning":"創意的另一個方面","examples":[{"en":"Howard-Jones found another aspect of creativity.","zh":"Howard-Jones 發現創意的另一個方面。"},{"en":"Another aspect of creativity means one more part or feature of creative thinking.","zh":"another aspect of creativity 指創意思維的另一部分或特徵。"},{"en":"Motivation is another aspect of learning beyond memory and attention.","zh":"動機是記憶和注意力以外，學習的另一個方面。"},{"en":"Looking at different aspects gives a fuller understanding of a complex topic.","zh":"查看不同方面可以更完整理解複雜主題。"},{"en":"This phrase is useful when adding a new angle to an explanation.","zh":"為解釋加入新角度時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":11},{"front":"make up a story based on","meaning":"根據……編故事","examples":[{"en":"Participants had to make up a story based on three words.","zh":"參加者必須根據三個詞語編故事。"},{"en":"To make up a story based on something means to invent a story using it as the starting point.","zh":"make up a story based on something 指以某物作起點創作故事。"},{"en":"A teacher may ask students to make up a story based on a picture.","zh":"老師可能要求學生根據一幅圖片編故事。"},{"en":"A fixed starting point can challenge creativity because writers must connect given elements.","zh":"固定起點可以挑戰創意，因為作者必須連接指定元素。"},{"en":"This phrase is useful in writing tasks and creativity tests.","zh":"這個短語適用於寫作任務和創意測試。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":11},{"front":"scan someone’s brain","meaning":"掃描某人的大腦","examples":[{"en":"Researchers scanned people’s brains while they performed the task.","zh":"研究人員在人們完成任務時掃描他們的大腦。"},{"en":"To scan someone’s brain means to use medical imaging to observe brain structure or activity.","zh":"scan someone’s brain 指使用醫學影像觀察大腦結構或活動。"},{"en":"Doctors may scan a patient’s brain after a serious head injury.","zh":"醫生可能在病人嚴重頭部受傷後掃描其大腦。"},{"en":"Brain scans can help researchers see which areas become active during a task.","zh":"腦掃描可以幫助研究人員看見哪些區域在任務期間變得活躍。"},{"en":"This phrase is common in medicine and neuroscience.","zh":"這個短語常見於醫學和神經科學。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":11},{"front":"functional magnetic resonance imaging","meaning":"功能性磁力共振成像","examples":[{"en":"Howard-Jones scanned their brains using functional magnetic resonance imaging.","zh":"Howard-Jones 使用功能性磁力共振成像掃描他們的大腦。"},{"en":"Functional magnetic resonance imaging, or fMRI, is a scanning method that shows changes in brain activity.","zh":"functional magnetic resonance imaging，即 fMRI，是顯示大腦活動變化的掃描方法。"},{"en":"Researchers may use fMRI to study which brain areas respond during language tasks.","zh":"研究人員可能使用 fMRI 研究哪些腦區在語言任務中有反應。"},{"en":"This method helps connect mental tasks with active brain regions.","zh":"這種方法幫助把心理任務與活躍腦區連接起來。"},{"en":"This phrase is technical and common in neuroscience research.","zh":"這個短語較技術性，常見於神經科學研究。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":11},{"front":"in one trial","meaning":"在一次試驗中","examples":[{"en":"In one trial, people were asked not to try too hard.","zh":"在一次試驗中，人們被要求不要太刻意用力。"},{"en":"In one trial means during one test or round of an experiment.","zh":"in one trial 指在一項實驗的一次測試或回合中。"},{"en":"In one trial, students used paper notes; in another, they used tablets.","zh":"在一次試驗中，學生使用紙本筆記；在另一次中，他們使用平板電腦。"},{"en":"Comparing trials helps researchers see how changing one instruction affects results.","zh":"比較不同試驗有助研究人員看出改變一個指示如何影響結果。"},{"en":"This phrase is useful in experimental descriptions.","zh":"這個短語適用於實驗描述。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":11},{"front":"try too hard","meaning":"太過用力；過分刻意","examples":[{"en":"Participants were told not to try too hard in the first trial.","zh":"在第一次試驗中，參加者被告知不要太過用力。"},{"en":"To try too hard means to put in so much deliberate effort that the result may become forced or unnatural.","zh":"try too hard 指投入太多刻意努力，以致結果可能變得勉強或不自然。"},{"en":"A speaker may sound nervous if she tries too hard to use difficult vocabulary.","zh":"如果演講者太過刻意使用困難詞彙，可能聽起來緊張。"},{"en":"Sometimes relaxed effort produces better creative results than pressure.","zh":"有時放鬆努力比壓力更能產生好的創意結果。"},{"en":"This phrase is useful when effort becomes excessive.","zh":"當努力變得過度時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":11},{"front":"the most obvious story","meaning":"最明顯的故事","examples":[{"en":"Participants reported the most obvious story suggested by the words.","zh":"參加者說出由這些詞語提示的最明顯故事。"},{"en":"The most obvious story is the story that comes to mind first and requires the least imagination.","zh":"most obvious story 指最先想到、最不需要想像力的故事。"},{"en":"If the words are “dog, park, ball,” the most obvious story may be about a dog playing fetch.","zh":"如果詞語是 dog, park, ball，最明顯的故事可能是狗在玩拋接球。"},{"en":"Obvious ideas are easy to find, but they may not be the most creative.","zh":"明顯想法容易找到，但未必最有創意。"},{"en":"This phrase is useful when contrasting predictable ideas with inventive ones.","zh":"對比可預測想法和創新想法時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":11},{"front":"be inventive","meaning":"有創意；發揮創意","examples":[{"en":"In another trial, they were asked to be inventive.","zh":"在另一項試驗中，他們被要求發揮創意。"},{"en":"To be inventive means to produce new, clever, or original ideas.","zh":"be inventive 指產生新的、聰明的或原創的想法。"},{"en":"A student can be inventive by turning recycled boxes into a science model.","zh":"學生把回收紙盒變成科學模型，就是發揮創意。"},{"en":"Being inventive often means moving beyond the first obvious answer.","zh":"有創意往往意味着超越第一個明顯答案。"},{"en":"This phrase is useful in creative tasks, problem-solving, and design.","zh":"這個短語適用於創作任務、解難和設計。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":11},{"front":"vary the words","meaning":"改變詞語","examples":[{"en":"Howard-Jones varied the words to change the difficulty of the task.","zh":"Howard-Jones 改變詞語，以改變任務難度。"},{"en":"To vary the words means to change the words used.","zh":"vary the words 指改變所使用的詞語。"},{"en":"A teacher may vary the words in a dictation to test different spelling patterns.","zh":"老師可能改變聽寫詞語，以測試不同拼寫模式。"},{"en":"Changing the words can make a task easier, harder, or more creative.","zh":"改變詞語可以令任務更容易、更困難或更有創意。"},{"en":"This phrase is useful when describing controlled changes in an experiment or lesson.","zh":"描述實驗或課堂中的受控變化時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":11},{"front":"link the words","meaning":"把詞語聯繫起來","examples":[{"en":"Some sets of words were harder to link than others.","zh":"有些詞組比其他詞組更難聯繫起來。"},{"en":"To link the words means to connect them into a meaningful idea, sentence, or story.","zh":"link the words 指把詞語連接成有意思的想法、句子或故事。"},{"en":"A student may link the words “rain,” “bus,” and “late” into a story about missing school.","zh":"學生可能把 rain、bus 和 late 聯繫成關於錯過上學的故事。"},{"en":"Words that seem unrelated require more creative effort to connect.","zh":"看似無關的詞語需要更多創意努力去連接。"},{"en":"This phrase is useful in vocabulary games and creativity tasks.","zh":"這個短語適用於詞彙遊戲和創意任務。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":11},{"front":"come up with","meaning":"想出","examples":[{"en":"People came up with more creative tales when they tried harder.","zh":"當人們更努力時，他們想出更有創意的故事。"},{"en":"To come up with something means to think of or produce an idea, answer, or plan.","zh":"come up with something 指想到或產生想法、答案或計劃。"},{"en":"A team may come up with a new timetable after students complain about long breaks.","zh":"學生投訴休息時間太長後，團隊可能想出新時間表。"},{"en":"People often come up with better ideas when they understand the problem clearly.","zh":"當人們清楚理解問題，常會想出更好想法。"},{"en":"This phrase is common in speaking, writing, and problem-solving.","zh":"這個短語常見於說話、寫作和解難。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":11},{"front":"a prefrontal brain region","meaning":"前額葉腦區","examples":[{"en":"More activity appeared in a particular prefrontal brain region.","zh":"某個特定前額葉腦區出現更多活動。"},{"en":"A prefrontal brain region is an area near the front of the brain involved in planning, control, and decision-making.","zh":"prefrontal brain region 指大腦前部附近涉及計劃、控制和決策的區域。"},{"en":"Researchers may study prefrontal regions when people make difficult choices.","zh":"當人們作困難選擇時，研究人員可能研究前額葉區域。"},{"en":"Activity in this area may increase when a person evaluates or selects ideas.","zh":"當人評估或選擇想法時，這個區域的活動可能增加。"},{"en":"This phrase is technical and belongs to neuroscience.","zh":"這個短語較技術性，屬於神經科學。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":12},{"front":"on the right-hand side","meaning":"在右側","examples":[{"en":"The active brain region was on the right-hand side.","zh":"活躍腦區位於右側。"},{"en":"On the right-hand side means located on the right side of something.","zh":"on the right-hand side 指位於某物右邊。"},{"en":"In a classroom, the clock may be on the right-hand side of the board.","zh":"在課室中，時鐘可能在白板右側。"},{"en":"Location details help readers understand exactly where something was found.","zh":"位置細節幫助讀者清楚理解某物在哪裏被發現。"},{"en":"This phrase is useful for describing position.","zh":"描述位置時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":12},{"front":"monitor for conflict","meaning":"監察衝突","examples":[{"en":"This brain region may help monitor for conflict.","zh":"這個腦區可能幫助監察衝突。"},{"en":"To monitor for conflict means to watch for tension, mismatch, or competing possibilities.","zh":"monitor for conflict 指留意緊張、不一致或互相競爭的可能性。"},{"en":"A teacher may monitor for conflict during group work so arguments do not grow.","zh":"老師可能在小組活動期間監察衝突，以免爭執擴大。"},{"en":"In thinking, monitoring conflict helps people notice when ideas do not fit well together.","zh":"在思考中，監察衝突幫助人注意到想法之間不太配合。"},{"en":"This phrase is useful in psychology, teamwork, and decision-making.","zh":"這個短語適用於心理學、團隊合作和決策。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":12},{"front":"filter out","meaning":"過濾掉","examples":[{"en":"The brain can filter out unhelpful ways of combining words.","zh":"大腦可以過濾掉無助的詞語組合方式。"},{"en":"To filter out something means to remove or block what is unwanted or not useful.","zh":"filter out something 指移除或阻隔不需要或無用的東西。"},{"en":"A student may filter out noisy messages and focus only on exam instructions.","zh":"學生可能過濾掉嘈雜訊息，只專注考試指示。"},{"en":"Filtering out weak options helps people choose better ideas.","zh":"過濾掉薄弱選項幫助人選擇更好想法。"},{"en":"This phrase is useful when discussing selection and attention.","zh":"討論選擇和注意力時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":12},{"front":"unhelpful ways of combining","meaning":"無助的組合方式","examples":[{"en":"Creative thinking requires filtering out unhelpful ways of combining ideas.","zh":"創意思考需要過濾掉無助的想法組合方式。"},{"en":"Unhelpful ways of combining are combinations that do not make sense or do not serve the goal.","zh":"unhelpful ways of combining 指沒有意思或無助於目標的組合。"},{"en":"In a story task, linking “doctor” and “moon” randomly may be unhelpful unless the writer creates a reason.","zh":"在故事任務中，隨便把 doctor 和 moon 連起來可能無助，除非作者創造原因。"},{"en":"Removing weak combinations allows stronger connections to stand out.","zh":"移除薄弱組合可以讓更強連繫突顯出來。"},{"en":"This phrase is useful when evaluating ideas during creativity.","zh":"在創意過程中評估想法時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":12},{"front":"pull out desirable connections","meaning":"提取有用的聯繫","examples":[{"en":"The brain helps us pull out desirable connections.","zh":"大腦幫助我們提取有用的聯繫。"},{"en":"To pull out desirable connections means to identify useful or attractive links among many possibilities.","zh":"pull out desirable connections 指在許多可能性中找出有用或吸引人的連繫。"},{"en":"A teacher helps students pull out desirable connections between history and modern life.","zh":"老師幫助學生提取歷史與現代生活之間的有用聯繫。"},{"en":"Finding the right connections turns scattered ideas into a meaningful plan.","zh":"找到正確連繫可以把零散想法變成有意義的計劃。"},{"en":"This phrase is useful when discussing selection within creative thinking.","zh":"討論創意思維中的選擇時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":12},{"front":"when we are stretched","meaning":"當我們受到挑戰時","examples":[{"en":"The task becomes more creative when we are stretched.","zh":"當我們受到挑戰時，任務會變得更有創意。"},{"en":"When we are stretched means when we are challenged beyond what is easy or familiar.","zh":"when we are stretched 指當我們被挑戰到超出容易或熟悉範圍時。"},{"en":"Students may produce better ideas when they are stretched by a difficult but fair question.","zh":"當學生受到困難但公平的問題挑戰時，可能產生更好想法。"},{"en":"Challenge can push people to search beyond obvious answers.","zh":"挑戰可以推動人尋找明顯答案以外的東西。"},{"en":"This phrase is useful when discussing productive difficulty.","zh":"討論有益難度時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":12},{"front":"produce many options","meaning":"產生很多選項","examples":[{"en":"The story-making task can produce many options.","zh":"編故事任務可以產生很多選項。"},{"en":"To produce many options means to create several possible choices or answers.","zh":"produce many options 指創造幾個可能選擇或答案。"},{"en":"A class brainstorming session can produce many options for a charity project.","zh":"課堂腦力激盪可以為慈善項目產生很多選項。"},{"en":"Having many options gives people more material to evaluate and improve.","zh":"擁有很多選項給人更多材料去評估和改善。"},{"en":"This phrase is useful in brainstorming and planning.","zh":"這個短語適用於腦力激盪和規劃。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":12},{"front":"assess options","meaning":"評估選項","examples":[{"en":"Creative people need to assess options before choosing the best idea.","zh":"創意人士在選擇最佳想法前需要評估選項。"},{"en":"To assess options means to judge possible choices carefully.","zh":"assess options 指仔細判斷可能選擇。"},{"en":"A family may assess options before deciding which school a child should attend.","zh":"家庭在決定孩子入讀哪間學校前，可能評估選項。"},{"en":"Assessment helps people avoid choosing the first idea too quickly.","zh":"評估幫助人避免太快選擇第一個想法。"},{"en":"This phrase is useful in decision-making and creative work.","zh":"這個短語適用於決策和創意工作。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":12},{"front":"a conscious process of","meaning":"……的有意識過程","examples":[{"en":"Part of creativity is a conscious process of evaluating ideas.","zh":"創意的一部分是評估想法的有意識過程。"},{"en":"A conscious process of something is a deliberate mental activity that a person is aware of.","zh":"conscious process of something 指人有意識地進行的刻意心理活動。"},{"en":"Checking an essay for grammar is a conscious process of improving writing.","zh":"檢查文章文法是改善寫作的有意識過程。"},{"en":"Conscious effort helps turn raw ideas into polished work.","zh":"有意識努力幫助把原始想法變成成熟作品。"},{"en":"This phrase is useful when contrasting deliberate thinking with unconscious inspiration.","zh":"對比刻意思考與無意識靈感時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":12},{"front":"evaluating and analysing ideas","meaning":"評估和分析想法","examples":[{"en":"Creativity involves evaluating and analysing ideas.","zh":"創意涉及評估和分析想法。"},{"en":"Evaluating and analysing ideas means judging ideas and examining how they work.","zh":"evaluating and analysing ideas 指判斷想法並檢視它們如何運作。"},{"en":"A student evaluates and analyses ideas when deciding which example best supports an essay point.","zh":"學生決定哪個例子最能支持文章觀點時，就是在評估和分析想法。"},{"en":"Analysis helps people improve ideas instead of accepting every thought immediately.","zh":"分析幫助人改善想法，而不是立即接受每個念頭。"},{"en":"This phrase is useful when creativity requires judgement, not only imagination.","zh":"當創意需要判斷而不只是想像時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":12},{"front":"the more…, the more…","meaning":"越……就越……","examples":[{"en":"The more we try and are stretched, the more creative our minds can be.","zh":"我們越努力並受到挑戰，大腦就越能有創意。"},{"en":"The more…, the more… shows that when one thing increases, another thing also increases.","zh":"the more…, the more… 顯示一件事增加時，另一件事也增加。"},{"en":"The more students read, the more vocabulary they usually learn.","zh":"學生讀得越多，通常學到的詞彙就越多。"},{"en":"This structure helps show a direct relationship between two changes.","zh":"這個結構幫助顯示兩種變化之間的直接關係。"},{"en":"It is useful for explaining growth, effort, and results.","zh":"解釋成長、努力和結果時，它很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":13},{"front":"need not always be","meaning":"不一定總是……","examples":[{"en":"Creativity need not always be a solitary experience.","zh":"創意不一定總是孤獨的經驗。"},{"en":"Need not always be means does not have to be true in every case.","zh":"need not always be 指不必在每種情況下都如此。"},{"en":"Studying need not always be boring if students use games and real examples.","zh":"如果學生使用遊戲和真實例子，學習不一定總是沉悶。"},{"en":"This phrase softens an assumption by showing there are exceptions.","zh":"這個短語透過指出例外來軟化一個假設。"},{"en":"It is useful when correcting a fixed belief.","zh":"糾正固定信念時，它很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":13},{"front":"a solitary, tortured affair","meaning":"孤獨而痛苦的事情","examples":[{"en":"Creativity need not always be a solitary, tortured affair.","zh":"創意不一定總是孤獨而痛苦的事情。"},{"en":"A solitary, tortured affair is an experience that is lonely, painful, and emotionally difficult.","zh":"solitary, tortured affair 指孤單、痛苦且情緒上困難的經歷。"},{"en":"Some people imagine writers working alone for months in a solitary, tortured affair.","zh":"有些人想像作家獨自工作數月，經歷孤獨而痛苦的創作。"},{"en":"Creative work can also happen through teamwork, joy, and support.","zh":"創意工作也可以透過團隊合作、快樂和支援發生。"},{"en":"This phrase is dramatic and challenges the stereotype of the suffering artist.","zh":"這個短語語氣戲劇化，挑戰受苦藝術家的刻板印象。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":13},{"front":"a slight association between","meaning":"……之間有輕微關聯","examples":[{"en":"There is a slight association between solitary writing and negative moods.","zh":"孤獨寫作和負面情緒之間有輕微關聯。"},{"en":"A slight association between two things means a weak connection between them.","zh":"slight association between two things 指兩者之間有弱連繫。"},{"en":"A study may find a slight association between late screen use and poorer sleep.","zh":"研究可能發現深夜使用屏幕與較差睡眠之間有輕微關聯。"},{"en":"A slight association suggests a pattern, but it may not be strong enough to explain everything.","zh":"輕微關聯暗示有模式，但可能不足以解釋一切。"},{"en":"This phrase is common in cautious research writing.","zh":"這個短語常見於謹慎研究寫作。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":13},{"front":"negative moods","meaning":"負面情緒","examples":[{"en":"Solitary writing may be associated with negative moods.","zh":"孤獨寫作可能與負面情緒有關。"},{"en":"Negative moods are unpleasant emotional states such as sadness, anger, anxiety, or frustration.","zh":"negative moods 指不愉快的情緒狀態，例如悲傷、憤怒、焦慮或挫敗。"},{"en":"A student in a negative mood may find it harder to start homework.","zh":"處於負面情緒的學生可能更難開始做功課。"},{"en":"Negative moods can affect attention, motivation, and how people judge their work.","zh":"負面情緒可以影響注意力、動機和人們如何評價自己的作品。"},{"en":"This phrase is useful in psychology and everyday emotional discussion.","zh":"這個短語適用於心理學和日常情緒討論。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":13},{"front":"emotional disturbances","meaning":"情緒困擾","examples":[{"en":"Some creative work may be linked to emotional disturbances.","zh":"有些創意工作可能與情緒困擾有關。"},{"en":"Emotional disturbances are serious disruptions in mood, feeling, or emotional stability.","zh":"emotional disturbances 指情緒、感受或情緒穩定性方面的嚴重干擾。"},{"en":"A person facing emotional disturbances may struggle to sleep, focus, or maintain routines.","zh":"面對情緒困擾的人可能難以睡眠、集中或維持日常規律。"},{"en":"Emotional disturbance can affect creativity either by disrupting work or changing thought patterns.","zh":"情緒困擾可以透過打亂工作或改變思維模式影響創意。"},{"en":"This phrase is formal and often used in psychology or health contexts.","zh":"這個短語較正式，常用於心理學或健康語境。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":13},{"front":"scientific creativity","meaning":"科學創意","examples":[{"en":"Scientific creativity often occurs when people feel positive.","zh":"科學創意常在人感到正面時出現。"},{"en":"Scientific creativity is the ability to develop original ideas, methods, or explanations in science.","zh":"scientific creativity 指在科學中發展原創想法、方法或解釋的能力。"},{"en":"A researcher shows scientific creativity when designing a new experiment to test an old question.","zh":"研究人員設計新實驗來測試舊問題時，就是展現科學創意。"},{"en":"Positive moods may help scientists explore possibilities more freely.","zh":"正面情緒可能幫助科學家更自由探索可能性。"},{"en":"This phrase is useful when creativity appears in research rather than art.","zh":"當創意出現在研究而不是藝術中時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":13},{"front":"workplace creativity","meaning":"職場創意","examples":[{"en":"Workplace creativity is more likely when people are positive.","zh":"當人們情緒正面時，職場創意更可能出現。"},{"en":"Workplace creativity means original problem-solving and useful new ideas in a job setting.","zh":"workplace creativity 指工作環境中的原創解難和有用新想法。"},{"en":"A receptionist shows workplace creativity by redesigning a sign-in process to reduce waiting time.","zh":"接待員重新設計登記流程以減少等候時間，就是展現職場創意。"},{"en":"Positive workplace conditions can make employees more willing to suggest improvements.","zh":"正面的職場環境可以令員工更願意提出改善建議。"},{"en":"This phrase is useful in business, management, and organisational studies.","zh":"這個短語適用於商業、管理和組織研究。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":13},{"front":"be more likely to occur","meaning":"較有可能發生","examples":[{"en":"Creativity is more likely to occur when people are positive and buoyant.","zh":"當人們正面而充滿活力時，創意較有可能發生。"},{"en":"To be more likely to occur means to have a higher chance of happening.","zh":"be more likely to occur 指發生機會較高。"},{"en":"Class discussion is more likely to occur when students feel safe from ridicule.","zh":"當學生不怕被嘲笑時，課堂討論較有可能發生。"},{"en":"Good conditions can increase the chance that a desired behaviour appears.","zh":"良好條件可以增加理想行為出現的機會。"},{"en":"This phrase is useful when explaining probability and conditions.","zh":"解釋可能性和條件時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":13},{"front":"positive and buoyant","meaning":"正面而充滿活力","examples":[{"en":"People may be more creative when they feel positive and buoyant.","zh":"當人們感到正面而充滿活力時，可能更有創意。"},{"en":"Positive and buoyant means cheerful, hopeful, energetic, and emotionally light.","zh":"positive and buoyant 指愉快、有希望、有能量且情緒輕盈。"},{"en":"A team feels positive and buoyant after receiving encouraging feedback from customers.","zh":"團隊收到顧客鼓勵回饋後，會感到正面而充滿活力。"},{"en":"Good moods can make people more willing to try unusual ideas.","zh":"好情緒可以令人更願意嘗試不尋常想法。"},{"en":"This phrase is useful when describing an upbeat emotional state.","zh":"描述積極情緒狀態時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":13},{"front":"a decade-long study","meaning":"長達十年的研究","examples":[{"en":"Amabile conducted a decade-long study of real businesses.","zh":"Amabile 進行了一項長達十年的真實企業研究。"},{"en":"A decade-long study is research that lasts for ten years.","zh":"decade-long study 指持續十年的研究。"},{"en":"A decade-long study of students could show how early habits affect later careers.","zh":"長達十年的學生研究可以顯示早期習慣如何影響後來職業。"},{"en":"Long studies can reveal patterns that short experiments may miss.","zh":"長期研究可以揭示短期實驗可能錯過的模式。"},{"en":"This phrase is useful when describing serious long-term research.","zh":"描述嚴謹長期研究時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":13},{"front":"relate positively to","meaning":"與……呈正相關","examples":[{"en":"Positive moods relate positively to creativity in organisations.","zh":"正面情緒與組織中的創意呈正相關。"},{"en":"To relate positively to something means to be connected with it in a favourable or increasing way.","zh":"relate positively to something 指與某事有正面或同步增加的關係。"},{"en":"Regular feedback may relate positively to student confidence.","zh":"定期回饋可能與學生信心呈正相關。"},{"en":"A positive relationship suggests that as one factor improves, the other may improve too.","zh":"正相關暗示一個因素改善時，另一個因素也可能改善。"},{"en":"This phrase is common in research and statistics.","zh":"這個短語常見於研究和統計。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":14},{"front":"a simple linear relationship","meaning":"簡單的線性關係","examples":[{"en":"The relationship between mood and creativity is a simple linear relationship.","zh":"情緒與創意之間的關係是簡單的線性關係。"},{"en":"A simple linear relationship means one factor changes in a steady direction as another changes.","zh":"simple linear relationship 指一個因素隨另一因素改變而穩定同向變化。"},{"en":"In a simple linear relationship, more practice may lead to better typing speed.","zh":"在簡單線性關係中，更多練習可能帶來更快打字速度。"},{"en":"Some real relationships are not linear because many factors interact.","zh":"有些真實關係並非線性，因為許多因素互相作用。"},{"en":"This phrase is common in research, graphs, and statistics.","zh":"這個短語常見於研究、圖表和統計。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":14},{"front":"creative thought","meaning":"創意思維","examples":[{"en":"Creative thought can improve people’s moods.","zh":"創意思維可以改善人的情緒。"},{"en":"Creative thought means thinking that produces new, original, or imaginative ideas.","zh":"creative thought 指產生新穎、原創或富想像力想法的思考。"},{"en":"A student uses creative thought when inventing a new ending for a story.","zh":"學生為故事創作新結局時，就是使用創意思維。"},{"en":"Creative thought can feel rewarding because it gives people a sense of discovery.","zh":"創意思維可以令人感到有回報，因為它帶來發現感。"},{"en":"This phrase is useful when discussing mental creativity rather than final products.","zh":"討論心理創意而非最終作品時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":14},{"front":"improve people’s moods","meaning":"改善人的情緒","examples":[{"en":"Creative thought may improve people’s moods.","zh":"創意思維可能改善人的情緒。"},{"en":"To improve people’s moods means to make them feel better, more positive, or less stressed.","zh":"improve people’s moods 指令人感覺更好、更正面或較少壓力。"},{"en":"A funny classroom activity can improve students’ moods before a difficult lesson.","zh":"有趣課堂活動可以在困難課節前改善學生情緒。"},{"en":"When people feel they have made progress, their mood often improves.","zh":"當人們感到有進展，情緒通常會改善。"},{"en":"This phrase is useful when discussing emotional effects.","zh":"討論情緒效果時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":14},{"front":"the process is circular","meaning":"這個過程是循環的","examples":[{"en":"The relationship between mood and creativity suggests that the process is circular.","zh":"情緒與創意之間的關係暗示這個過程是循環的。"},{"en":"The process is circular means two things influence each other repeatedly instead of moving in one straight direction.","zh":"process is circular 指兩件事反覆互相影響，而不是單向直線發展。"},{"en":"Confidence and practice can be circular: practice builds confidence, and confidence encourages more practice.","zh":"信心和練習可以是循環的：練習建立信心，信心鼓勵更多練習。"},{"en":"Circular processes can become stronger over time, for better or worse.","zh":"循環過程可以隨時間變得更強，無論好壞。"},{"en":"This phrase is useful when cause and effect feed back into each other.","zh":"當因果互相回饋時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":14},{"front":"time pressures","meaning":"時間壓力","examples":[{"en":"Time pressures do not boost workplace creativity.","zh":"時間壓力不會提升職場創意。"},{"en":"Time pressures are stress or limits caused by not having enough time.","zh":"time pressures 指因時間不足而造成的壓力或限制。"},{"en":"Students feel time pressures when three assignments are due on the same day.","zh":"當三份作業同一天截止時，學生會感到時間壓力。"},{"en":"Too much time pressure can make people choose safe ideas instead of original ones.","zh":"過多時間壓力可能令人選擇安全想法，而不是原創想法。"},{"en":"This phrase is useful when discussing stress, deadlines, and performance.","zh":"討論壓力、期限和表現時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":14},{"front":"financial pressures","meaning":"財政壓力","examples":[{"en":"Financial pressures do not improve creative work.","zh":"財政壓力不會改善創意工作。"},{"en":"Financial pressures are worries or demands caused by money problems.","zh":"financial pressures 指由金錢問題造成的憂慮或要求。"},{"en":"A small business faces financial pressures when rent rises and sales fall.","zh":"當租金上升而銷售下降，小企業會面對財政壓力。"},{"en":"Money worries can make people focus on survival rather than experimentation.","zh":"金錢憂慮可以令人專注於生存，而不是實驗。"},{"en":"This phrase is useful when discussing stress caused by costs or income.","zh":"討論成本或收入造成的壓力時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":14},{"front":"hard-earned bonus schemes","meaning":"辛苦賺取的獎金制度","examples":[{"en":"Hard-earned bonus schemes do not boost workplace creativity.","zh":"辛苦賺取的獎金制度不會提升職場創意。"},{"en":"Hard-earned bonus schemes are reward systems where people receive extra money after difficult work.","zh":"hard-earned bonus schemes 指人們完成艱難工作後獲得額外金錢的獎勵制度。"},{"en":"A company may offer a hard-earned bonus scheme for employees who meet sales targets.","zh":"公司可能為達到銷售目標的員工提供獎金制度。"},{"en":"Bonuses can motivate some tasks, but they may not create deep creative interest.","zh":"獎金可以推動某些任務，但未必創造深層創意興趣。"},{"en":"This phrase is useful when discussing money-based motivation.","zh":"討論金錢動機時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":14},{"front":"internal motivation","meaning":"內在動機","examples":[{"en":"Internal motivation produces the best work.","zh":"內在動機產生最佳成果。"},{"en":"Internal motivation is the drive that comes from personal interest, values, or satisfaction.","zh":"internal motivation 指來自個人興趣、價值觀或滿足感的推動力。"},{"en":"A student with internal motivation reads extra books because she genuinely enjoys learning.","zh":"有內在動機的學生會閱讀額外書籍，因為她真正享受學習。"},{"en":"Work driven from within can be more careful, persistent, and original.","zh":"由內心推動的工作可以更仔細、更持久和更原創。"},{"en":"This phrase contrasts with pressure, rewards, or punishment from outside.","zh":"這個短語與外在壓力、獎勵或懲罰形成對比。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":14},{"front":"coercion","meaning":"強迫；強制","examples":[{"en":"Internal motivation, not coercion, produces the best work.","zh":"產生最佳成果的是內在動機，而不是強迫。"},{"en":"Coercion means forcing someone to do something through pressure, threats, or control.","zh":"coercion 指透過壓力、威脅或控制迫使某人做某事。"},{"en":"A student may finish homework under coercion, but she may not learn deeply.","zh":"學生可能在強迫下完成功課，但未必深入學習。"},{"en":"Coercion can reduce creativity because people focus on avoiding punishment.","zh":"強迫可以降低創意，因為人們專注於避免懲罰。"},{"en":"This word is useful when contrasting freedom with force.","zh":"對比自由與強制時，這個詞很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":14},{"front":"produce the best work","meaning":"產生最佳成果","examples":[{"en":"Internal motivation can produce the best work.","zh":"內在動機可以產生最佳成果。"},{"en":"To produce the best work means to create the highest-quality result.","zh":"produce the best work 指創造最高質素的成果。"},{"en":"A writer may produce the best work when she cares deeply about the topic.","zh":"作家深深關心題材時，可能產生最佳作品。"},{"en":"Quality often improves when people feel ownership and interest in the task.","zh":"當人們對任務有擁有感和興趣，質素常會提升。"},{"en":"This phrase is useful when discussing performance and motivation.","zh":"討論表現和動機時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":14},{"front":"often forgotten aspect","meaning":"常被忽略的一面","examples":[{"en":"Another often forgotten aspect of creativity is social.","zh":"創意另一個常被忽略的一面是社交性。"},{"en":"An often forgotten aspect is an important part that people commonly overlook.","zh":"often forgotten aspect 指人們常忽視的重要部分。"},{"en":"Sleep is an often forgotten aspect of exam preparation.","zh":"睡眠是考試準備中常被忽略的一面。"},{"en":"When people overlook one aspect, their explanation becomes incomplete.","zh":"當人們忽略某一方面，解釋就變得不完整。"},{"en":"This phrase is useful when adding a neglected point.","zh":"加入被忽視的重點時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":15},{"front":"strong social networks","meaning":"強大的社交網絡","examples":[{"en":"Creative people need strong social networks.","zh":"創意人士需要強大的社交網絡。"},{"en":"Strong social networks are reliable connections with people who can offer support, ideas, or opportunities.","zh":"strong social networks 指能提供支援、想法或機會的可靠人際連繫。"},{"en":"A young artist may build strong social networks through workshops and local exhibitions.","zh":"年輕藝術家可能透過工作坊和本地展覽建立強大社交網絡。"},{"en":"Supportive networks help people continue when creative work feels uncertain.","zh":"支持性網絡幫助人在創作感到不確定時繼續。"},{"en":"This phrase is useful when discussing relationships and success.","zh":"討論關係和成功時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":15},{"front":"trusting relationships","meaning":"互信關係","examples":[{"en":"Creative people need trusting relationships.","zh":"創意人士需要互信關係。"},{"en":"Trusting relationships are relationships in which people feel safe, respected, and believed in.","zh":"trusting relationships 指人們感到安全、受尊重和被信任的關係。"},{"en":"A student is more willing to share unusual ideas in a trusting relationship with a teacher.","zh":"學生與老師有互信關係時，更願意分享不尋常想法。"},{"en":"Trust reduces fear of judgement and makes experimentation easier.","zh":"信任減少對評判的恐懼，令實驗更容易。"},{"en":"This phrase is useful when discussing emotional support and collaboration.","zh":"討論情感支援和合作時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":15},{"front":"active neural networks","meaning":"活躍的神經網絡","examples":[{"en":"Creativity needs social networks, not just active neural networks.","zh":"創意需要社交網絡，而不只是活躍的神經網絡。"},{"en":"Active neural networks are groups of connected brain cells that are working together.","zh":"active neural networks 指正在共同運作的一組相連腦細胞。"},{"en":"Brain researchers may study active neural networks during memory or language tasks.","zh":"腦研究人員可能在記憶或語言任務期間研究活躍神經網絡。"},{"en":"Creativity may need both brain activity and supportive human relationships.","zh":"創意可能同時需要大腦活動和支持性人際關係。"},{"en":"This phrase is technical and belongs to neuroscience.","zh":"這個短語較技術性，屬於神經科學。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":15},{"front":"vital characteristic","meaning":"重要特徵","examples":[{"en":"One vital characteristic of a creative person is social support.","zh":"創意人士的一個重要特徵是社會支持。"},{"en":"A vital characteristic is an extremely important feature.","zh":"vital characteristic 指極其重要的特徵。"},{"en":"Reliability is a vital characteristic of a good nurse.","zh":"可靠是好護士的重要特徵。"},{"en":"Identifying vital characteristics helps people understand what really matters.","zh":"找出重要特徵幫助人理解真正重要的是甚麼。"},{"en":"This phrase is useful when naming an essential quality.","zh":"指出必要品質時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":15},{"front":"a highly creative person","meaning":"高度有創意的人","examples":[{"en":"A highly creative person needs at least one supportive person.","zh":"高度有創意的人需要至少一位支持他的人。"},{"en":"A highly creative person is someone who often produces original, useful, or imaginative ideas.","zh":"highly creative person 指常產生原創、有用或富想像力想法的人。"},{"en":"A highly creative student may design a new way to revise vocabulary for the whole class.","zh":"高度有創意的學生可能為全班設計新的詞彙溫習方法。"},{"en":"Creative people still need emotional support, even when their ideas are strong.","zh":"即使想法很強，創意人士仍需要情感支援。"},{"en":"This phrase describes a person with an unusually strong creative ability.","zh":"這個短語描述創意能力異常強的人。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":15},{"front":"at least one other person","meaning":"至少另一個人","examples":[{"en":"A creative person needs at least one other person who believes in them.","zh":"創意人士需要至少另一個相信他的人。"},{"en":"At least one other person means one or more additional people.","zh":"at least one other person 指一個或多於一個額外的人。"},{"en":"A student preparing for a competition may need at least one other person to practise with.","zh":"準備比賽的學生可能需要至少另一個人一起練習。"},{"en":"Having even one supporter can help someone continue during doubt.","zh":"即使只有一位支持者，也可以幫助人在懷疑時繼續。"},{"en":"This phrase sets a minimum number.","zh":"這個短語設定最低數量。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":15},{"front":"completely nuts","meaning":"完全瘋了","examples":[{"en":"A creative person needs someone who does not think they are completely nuts.","zh":"創意人士需要有人不認為他們完全瘋了。"},{"en":"Completely nuts is an informal way to say totally crazy or unreasonable.","zh":"completely nuts 是非常口語的說法，意思是完全瘋狂或不合理。"},{"en":"A new business idea may sound completely nuts until someone explains the plan clearly.","zh":"新商業想法在有人清楚解釋計劃前，可能聽起來完全瘋了。"},{"en":"If people fear being judged as completely nuts, they may hide original ideas.","zh":"如果人們害怕被評為完全瘋了，可能會隱藏原創想法。"},{"en":"This phrase is very informal and should be used carefully.","zh":"這個短語非常口語，應小心使用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":15},{"front":"agree with the information","meaning":"與資料一致","examples":[{"en":"Students decide whether each statement agrees with the information in the passage.","zh":"學生判斷每個陳述是否與文章資料一致。"},{"en":"To agree with the information means to match what the text says.","zh":"agree with the information 指符合文本所說內容。"},{"en":"In a reading test, a statement agrees with the information only if the passage supports it.","zh":"在閱讀測驗中，只有文章支持某陳述，它才與資料一致。"},{"en":"Students should compare meaning, not just repeated words.","zh":"學生應比較意思，而不只是重複字眼。"},{"en":"This phrase is common in TRUE, FALSE, NOT GIVEN tasks.","zh":"這個短語常見於 TRUE, FALSE, NOT GIVEN 題。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":15},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"Write FALSE if the statement contradicts the information.","zh":"如果陳述與資料相矛盾，就寫 FALSE。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"contradict the information 指說出與文本相反的意思。"},{"en":"If the passage says creativity is not guaranteed by IQ, a statement saying IQ guarantees creativity contradicts it.","zh":"如果文章說智商不保證創意，而陳述說智商保證創意，就與文章矛盾。"},{"en":"A contradiction is different from missing information because the text directly disagrees.","zh":"矛盾不同於沒有資料，因為文本直接不同意。"},{"en":"This phrase helps students identify FALSE answers.","zh":"這個短語幫助學生辨認 FALSE 答案。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":15},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"Write NOT GIVEN if there is no information on this.","zh":"如果沒有相關資料，就寫 NOT GIVEN。"},{"en":"No information on this means the passage does not say whether the statement is true or false.","zh":"no information on this 指文章沒有說明該陳述是真還是假。"},{"en":"If a passage discusses creativity but not a person’s childhood, there is no information on that childhood.","zh":"如果文章討論創意但沒有談某人的童年，就沒有相關資料。"},{"en":"Students should not use outside knowledge when the text gives no evidence.","zh":"當文本沒有證據時，學生不應使用外部知識。"},{"en":"This phrase is essential for NOT GIVEN questions.","zh":"這個短語對 NOT GIVEN 題很重要。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":15},{"front":"write your answers in boxes","meaning":"在方格內作答","examples":[{"en":"Candidates write their answers in boxes on the answer sheet.","zh":"考生在答題紙上的方格內作答。"},{"en":"Write your answers in boxes means put each answer inside the numbered spaces provided.","zh":"write your answers in boxes 指把每個答案寫在提供的編號空格內。"},{"en":"In an exam, students may lose marks if they write answers in the wrong place.","zh":"在考試中，如果學生把答案寫錯位置，可能失分。"},{"en":"Following answer-sheet instructions helps markers read answers clearly.","zh":"跟從答題紙指示幫助評卷員清楚閱讀答案。"},{"en":"This phrase is common in formal exam instructions.","zh":"這個短語常見於正式考試指示。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":16},{"front":"a high IQ","meaning":"高智商","examples":[{"en":"The question asks whether a high IQ guarantees creativity.","zh":"題目問高智商是否保證創意。"},{"en":"A high IQ means a high score on an intelligence test.","zh":"high IQ 指智力測驗中的高分。"},{"en":"A student with a high IQ may solve logic problems quickly.","zh":"高智商學生可能很快解決邏輯問題。"},{"en":"A high IQ can help with some tasks, but it may not create motivation or imagination by itself.","zh":"高智商可以幫助某些任務，但本身未必創造動機或想像力。"},{"en":"This phrase is useful when discussing intelligence and ability.","zh":"討論智力和能力時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":16},{"front":"guarantee greater creativity","meaning":"保證更高創意","examples":[{"en":"The statement asks whether a high IQ can guarantee greater creativity.","zh":"這個陳述問高智商是否能保證更高創意。"},{"en":"To guarantee greater creativity means to ensure a higher level of creative ability.","zh":"guarantee greater creativity 指確保更高水平的創造能力。"},{"en":"Buying expensive art materials does not guarantee greater creativity in a student.","zh":"購買昂貴美術材料不會保證學生有更高創意。"},{"en":"Creativity depends on many factors, so one factor rarely guarantees it.","zh":"創意取決於許多因素，所以單一因素很少能保證它。"},{"en":"This phrase is useful when questioning cause and effect.","zh":"質疑因果關係時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":16},{"front":"an average IQ score","meaning":"平均智商分數","examples":[{"en":"The question compares a high IQ with an average IQ score.","zh":"題目比較高智商與平均智商分數。"},{"en":"An average IQ score is a score near the normal middle range on an IQ test.","zh":"average IQ score 指智商測驗中接近正常中間範圍的分數。"},{"en":"A person with an average IQ score may still be talented in music, design, or communication.","zh":"有平均智商分數的人仍可能在音樂、設計或溝通方面有天分。"},{"en":"Average test scores do not mean average potential in every area.","zh":"平均測驗分數不代表每方面潛力都普通。"},{"en":"This phrase is useful when comparing measured intelligence levels.","zh":"比較測量智力水平時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":16},{"front":"a competitive society","meaning":"競爭激烈的社會","examples":[{"en":"The question mentions abilities in a competitive society.","zh":"題目提到競爭激烈社會中的能力。"},{"en":"A competitive society is a society where people often compete for jobs, grades, status, or opportunities.","zh":"competitive society 指人們常為工作、成績、地位或機會競爭的社會。"},{"en":"Students may feel pressure in a competitive society because many people chase the same places.","zh":"在競爭激烈的社會中，學生可能感到壓力，因為許多人追逐同一批名額。"},{"en":"Competition can encourage effort, but too much pressure may reduce well-being.","zh":"競爭可以鼓勵努力，但過多壓力可能降低身心健康。"},{"en":"This phrase is useful when discussing modern education and work.","zh":"討論現代教育和工作時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":16},{"front":"language proficiency","meaning":"語言能力","examples":[{"en":"The statement refers to language proficiency and other abilities.","zh":"這個陳述提到語言能力和其他能力。"},{"en":"Language proficiency means the ability to use a language well in speaking, listening, reading, or writing.","zh":"language proficiency 指在說、聽、讀或寫方面良好使用一種語言的能力。"},{"en":"A job may require high English language proficiency for writing emails and talking to clients.","zh":"一份工作可能要求高英語能力，用於寫電郵和與客戶交談。"},{"en":"Proficiency improves through practice, feedback, and real use.","zh":"語言能力透過練習、回饋和真實使用而改善。"},{"en":"This phrase is common in education, work, and immigration contexts.","zh":"這個短語常見於教育、工作和移民語境。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":16},{"front":"combine a wider range of","meaning":"結合更廣泛的……","examples":[{"en":"Creative people can combine a wider range of resources and knowledge.","zh":"創意人士可以結合更廣泛的資源和知識。"},{"en":"To combine a wider range of things means to bring together more varied materials, ideas, or experiences.","zh":"combine a wider range of things 指把更多樣的材料、想法或經驗結合起來。"},{"en":"A chef may combine a wider range of ingredients to create a new dish.","zh":"廚師可能結合更廣泛的食材來創造新菜式。"},{"en":"Wider combinations can lead to more original results.","zh":"更廣泛的組合可以帶來更原創的結果。"},{"en":"This phrase is useful when explaining how creativity uses variety.","zh":"解釋創意如何使用多樣性時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":16},{"front":"develop novel approaches","meaning":"發展新穎方法","examples":[{"en":"Creative people use resources and knowledge to develop novel approaches.","zh":"創意人士使用資源和知識來發展新穎方法。"},{"en":"To develop novel approaches means to create new ways of dealing with problems or tasks.","zh":"develop novel approaches 指創造處理問題或任務的新方式。"},{"en":"A school may develop novel approaches to help shy students practise speaking.","zh":"學校可能發展新穎方法，幫助害羞學生練習說話。"},{"en":"New approaches often appear when existing methods no longer work well.","zh":"當現有方法不再有效，新方法常會出現。"},{"en":"This phrase is useful in education, business, science, and design.","zh":"這個短語適用於教育、商業、科學和設計。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":16},{"front":"does not necessarily suffer from","meaning":"不一定患有……","examples":[{"en":"A creative person does not necessarily suffer from mental illness.","zh":"有創意的人不一定患有精神疾病。"},{"en":"Does not necessarily suffer from means does not always or automatically have that condition.","zh":"does not necessarily suffer from 指不總是或不自動有某種狀況。"},{"en":"A quiet student does not necessarily suffer from low confidence.","zh":"安靜學生不一定患有低自信。"},{"en":"This phrase prevents people from making an unfair generalisation.","zh":"這個短語防止人作出不公平概括。"},{"en":"It is useful when correcting stereotypes.","zh":"糾正刻板印象時，它很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":16},{"front":"match people with opinions","meaning":"將人物與觀點配對","examples":[{"en":"Students match people with opinions or actions in the question.","zh":"學生在題目中將人物與觀點或行動配對。"},{"en":"To match people with opinions means to connect each person to the view they expressed.","zh":"match people with opinions 指把每個人與其表達的看法連接起來。"},{"en":"In a reading task, students may match researchers with their findings.","zh":"在閱讀題中，學生可能把研究人員與其發現配對。"},{"en":"Careful matching requires locating evidence, not guessing from names.","zh":"仔細配對需要定位證據，而不是憑名字猜測。"},{"en":"This phrase is common in comprehension exercises.","zh":"這個短語常見於理解練習。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":16},{"front":"appropriate letters","meaning":"適當字母","examples":[{"en":"Candidates write the appropriate letters in the boxes.","zh":"考生在方格內寫下適當字母。"},{"en":"Appropriate letters are the correct option letters that match the answers.","zh":"appropriate letters 指與答案相符的正確選項字母。"},{"en":"If option B matches the researcher’s view, B is the appropriate letter.","zh":"如果 B 選項符合研究者觀點，B 就是適當字母。"},{"en":"Writing the wrong letter can lose marks even when the idea is understood.","zh":"即使理解意思，寫錯字母也可能失分。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":16},{"front":"opinions or actions below","meaning":"以下觀點或行動","examples":[{"en":"The question asks students to match people with the opinions or actions below.","zh":"題目要求學生把人物與以下觀點或行動配對。"},{"en":"Opinions or actions below are the views or behaviours listed after the instruction.","zh":"opinions or actions below 指指示後列出的看法或行為。"},{"en":"Students should read the opinions or actions below before returning to the passage.","zh":"學生應先閱讀以下觀點或行動，再回到文章。"},{"en":"Understanding each option helps prevent careless matching.","zh":"理解每個選項有助避免粗心配對。"},{"en":"This phrase is useful in matching questions.","zh":"這個短語適用於配對題。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":17},{"front":"trigger creative thinking","meaning":"觸發創意思考","examples":[{"en":"A change in mood may trigger creative thinking.","zh":"情緒轉變可能觸發創意思考。"},{"en":"To trigger creative thinking means to start or activate original thought.","zh":"trigger creative thinking 指啟動或激發原創思考。"},{"en":"A surprising photo can trigger creative thinking in a writing class.","zh":"一張令人驚訝的照片可以在寫作課中觸發創意思考。"},{"en":"Triggers can help ideas appear when the mind was previously stuck.","zh":"觸發因素可以在大腦原本卡住時幫助想法出現。"},{"en":"This phrase is useful when discussing causes of inspiration.","zh":"討論靈感來源時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":17},{"front":"interpersonal relationships","meaning":"人際關係","examples":[{"en":"Strong interpersonal relationships can support creativity.","zh":"強大的人際關係可以支持創意。"},{"en":"Interpersonal relationships are relationships between people.","zh":"interpersonal relationships 指人與人之間的關係。"},{"en":"A student’s interpersonal relationships with classmates can affect group-project success.","zh":"學生與同學的人際關係可以影響小組項目成功。"},{"en":"Good relationships create trust, feedback, and emotional safety.","zh":"良好關係創造信任、回饋和情感安全。"},{"en":"This phrase is useful in psychology, education, and workplace discussion.","zh":"這個短語適用於心理學、教育和職場討論。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":17},{"front":"contribute to creativity","meaning":"有助於創意","examples":[{"en":"Trust and social support can contribute to creativity.","zh":"信任和社會支持可以有助於創意。"},{"en":"To contribute to creativity means to help creativity develop or appear.","zh":"contribute to creativity 指幫助創意發展或出現。"},{"en":"A quiet workspace can contribute to creativity by reducing distraction.","zh":"安靜工作空間可以透過減少分心而有助於創意。"},{"en":"Many small factors together can support creative performance.","zh":"許多小因素可以共同支持創意表現。"},{"en":"This phrase is useful when explaining what helps originality.","zh":"解釋甚麼幫助原創性時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":17},{"front":"move easily between","meaning":"輕鬆在……之間切換","examples":[{"en":"Creative thinkers may move easily between different kinds of thinking.","zh":"創意思考者可能輕鬆在不同類型的思考之間切換。"},{"en":"To move easily between things means to switch smoothly from one to another.","zh":"move easily between things 指順暢地由一件事切換到另一件事。"},{"en":"A good teacher can move easily between explanation, examples, and questions.","zh":"好老師可以輕鬆在解釋、例子和提問之間切換。"},{"en":"Smooth switching helps people adapt to changing task demands.","zh":"順暢切換幫助人適應不斷變化的任務要求。"},{"en":"This phrase is useful when describing flexibility.","zh":"描述靈活性時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":17},{"front":"assessing and processing ideas","meaning":"評估和處理想法","examples":[{"en":"Creative thinking can improve when people practise assessing and processing ideas.","zh":"當人們練習評估和處理想法時，創意思考可以改善。"},{"en":"Assessing and processing ideas means judging ideas and working through them carefully.","zh":"assessing and processing ideas 指判斷想法並仔細處理它們。"},{"en":"A student assesses and processes ideas when choosing which argument belongs in an essay.","zh":"學生選擇哪些論點應放入文章時，就是在評估和處理想法。"},{"en":"Careful processing turns rough thoughts into clearer, stronger work.","zh":"仔細處理可以把粗略想法變成更清楚、更有力的作品。"},{"en":"This phrase is useful when creativity involves evaluation as well as imagination.","zh":"當創意涉及評估以及想像時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":17},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Candidates complete the summary below using words from the passage.","zh":"考生使用文章中的詞語完成以下摘要。"},{"en":"Complete the summary below means fill in the missing parts of the short text that follows.","zh":"complete the summary below 指填寫下方短文中缺少的部分。"},{"en":"Students may complete the summary below after scanning for key words in the passage.","zh":"學生可能在掃讀文章找關鍵詞後完成以下摘要。"},{"en":"Summary completion tests both understanding and accurate word choice.","zh":"摘要填空同時測試理解和準確選詞。"},{"en":"This phrase is common in IELTS-style reading tasks.","zh":"這個短語常見於 IELTS 類閱讀題。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":17},{"front":"NO MORE THAN THREE WORDS","meaning":"不超過三個詞","examples":[{"en":"Candidates choose no more than three words from the passage.","zh":"考生從文章中選擇不超過三個詞。"},{"en":"NO MORE THAN THREE WORDS means the answer must contain one, two, or three words only.","zh":"NO MORE THAN THREE WORDS 指答案只能包含一個、兩個或三個詞。"},{"en":"If the answer is “alpha waves,” it follows the rule because it has two words.","zh":"如果答案是 alpha waves，它有兩個詞，所以符合規則。"},{"en":"Writing four words can lose marks even if the meaning is correct.","zh":"即使意思正確，寫四個詞也可能失分。"},{"en":"This instruction controls answer length in reading tests.","zh":"這項指示控制閱讀測驗中的答案長度。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":17},{"front":"record patterns of brain waves","meaning":"記錄腦波模式","examples":[{"en":"Martindale recorded patterns of brain waves while people made up stories.","zh":"Martindale 在人們編故事時記錄腦波模式。"},{"en":"To record patterns of brain waves means to measure and save information about the brain’s electrical rhythms.","zh":"record patterns of brain waves 指測量並保存大腦電節奏的資訊。"},{"en":"A sleep lab may record patterns of brain waves while a person is sleeping.","zh":"睡眠實驗室可能在人睡覺時記錄腦波模式。"},{"en":"Recorded patterns help researchers compare different mental states.","zh":"被記錄的模式幫助研究人員比較不同心理狀態。"},{"en":"This phrase is useful in neuroscience and psychology experiments.","zh":"這個短語適用於神經科學和心理學實驗。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":17},{"front":"identify two stages of creativity","meaning":"找出創意的兩個階段","examples":[{"en":"The study helped identify two stages of creativity.","zh":"研究幫助找出創意的兩個階段。"},{"en":"To identify two stages of creativity means to recognise two separate phases in the creative process.","zh":"identify two stages of creativity 指辨認創作過程中的兩個分開階段。"},{"en":"A writing teacher may identify two stages of essay writing: planning and drafting.","zh":"寫作老師可能找出文章寫作的兩個階段：規劃和起草。"},{"en":"Naming stages helps people understand what happens before a final product appears.","zh":"命名階段幫助人理解最終作品出現前發生甚麼。"},{"en":"This phrase is useful when analysing a process step by step.","zh":"逐步分析過程時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":17},{"front":"participants began developing","meaning":"參加者開始發展……","examples":[{"en":"The participants began developing their stories after the inspiration stage.","zh":"參加者在靈感階段後開始發展他們的故事。"},{"en":"Participants began developing means the people in the study started expanding, organising, or improving their ideas.","zh":"participants began developing 指研究中的人開始擴展、組織或改善他們的想法。"},{"en":"Students began developing their project after choosing a topic and collecting examples.","zh":"學生選好題目並收集例子後，開始發展他們的項目。"},{"en":"Development turns an initial idea into something more complete.","zh":"發展會把初步想法變成更完整的作品。"},{"en":"This phrase is useful when describing movement from idea to fuller work.","zh":"描述由想法走向完整作品時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":17},{"front":"greater cortical arousal","meaning":"較高的大腦皮層覺醒","examples":[{"en":"The brain became busier and showed greater cortical arousal.","zh":"大腦變得更忙碌，並顯示較高的大腦皮層覺醒。"},{"en":"Greater cortical arousal means a higher level of activity or alertness in the brain’s cortex.","zh":"greater cortical arousal 指大腦皮層中較高水平的活動或警覺。"},{"en":"A difficult exam question may produce greater cortical arousal than a simple memory question.","zh":"困難考題可能比簡單記憶題產生較高的大腦皮層覺醒。"},{"en":"More arousal can suggest that the brain is working harder to organise or evaluate information.","zh":"較高覺醒可以暗示大腦正在更努力組織或評估資訊。"},{"en":"This phrase is technical and common in neuroscience.","zh":"這個短語較技術性，常見於神經科學。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":18},{"front":"produced the most creative storylines","meaning":"創作出最有創意的故事情節","examples":[{"en":"The people with the greatest change in brain activity produced the most creative storylines.","zh":"大腦活動變化最大的人創作出最有創意的故事情節。"},{"en":"Produced the most creative storylines means created the most original and interesting story plots.","zh":"produced the most creative storylines 指創作出最原創和有趣的故事情節。"},{"en":"A student who connects three ordinary words in an unexpected way may produce a very creative storyline.","zh":"學生以意想不到的方式連接三個普通詞語時，可能創作出非常有創意的故事情節。"},{"en":"Creative storylines often appear when imagination is followed by careful development.","zh":"有創意的故事情節常在想像之後經仔細發展而出現。"},{"en":"This phrase is useful when judging the creative quality of written or spoken stories.","zh":"評估書面或口頭故事的創意質素時，這個短語很有用。"}],"source":"44 - Does An IQ Test Prove Creativity?.pdf","sourcePage":18}],"ielts/reading/passage-2/Practice 45":[{"front":"leaf-cutting ants","meaning":"切葉蟻","examples":[{"en":"Leaf-cutting ants cultivate fungus gardens using fresh vegetation.","zh":"切葉蟻利用新鮮植物培植真菌園。"},{"en":"Leaf-cutting ants are ants that cut pieces of leaves and use them to grow fungus for food.","zh":"leaf-cutting ants 指會切下葉片，並用葉片培植真菌作食物的螞蟻。"},{"en":"A documentary may show leaf-cutting ants carrying green leaf pieces like tiny farmers.","zh":"紀錄片可能展示切葉蟻像小農夫一樣搬運綠色葉片。"},{"en":"Because leaf-cutting ants depend on fungus, they must keep their gardens clean and healthy.","zh":"因為切葉蟻依賴真菌，所以牠們必須保持菌園清潔和健康。"},{"en":"The phrase refers to the ants’ farming behaviour, not simply to ants that eat leaves.","zh":"這個片語指螞蟻的農耕行為，而不只是吃葉子的螞蟻。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":1},{"front":"ant agriculture","meaning":"螞蟻的農耕行為","examples":[{"en":"Ant agriculture has been extensively studied over the years.","zh":"螞蟻的農耕行為多年來已被廣泛研究。"},{"en":"Ant agriculture means the farming-like behaviour of ants, especially when they grow fungus as food.","zh":"ant agriculture 指螞蟻類似農耕的行為，尤其是牠們培植真菌作食物。"},{"en":"Students may compare ant agriculture with human farming to understand cooperation in nature.","zh":"學生可能把螞蟻的農耕行為與人類農業比較，以理解自然界中的合作。"},{"en":"If ants cultivate, protect, and harvest fungus, their behaviour can be described as agriculture.","zh":"如果螞蟻培植、保護並收成真菌，牠們的行為就可被描述為農耕。"},{"en":"The phrase shows that farming is not only a human activity.","zh":"這個片語顯示農耕不只是人類活動。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":1},{"front":"have been extensively studied","meaning":"已被廣泛研究","examples":[{"en":"The ants and their agriculture have been extensively studied over the years.","zh":"這些螞蟻及其農耕行為多年來已被廣泛研究。"},{"en":"Have been extensively studied means have been researched carefully and in great detail.","zh":"have been extensively studied 指已被仔細而詳細地研究。"},{"en":"The effects of sleep on memory have been extensively studied by psychologists.","zh":"睡眠對記憶的影響已被心理學家廣泛研究。"},{"en":"If a topic has been extensively studied, scientists usually have many papers and data about it.","zh":"如果某主題已被廣泛研究，科學家通常有許多論文和數據。"},{"en":"The phrase suggests a large body of research, not just one small study.","zh":"這個片語暗示大量研究，而不只是一項小型研究。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":1},{"front":"recent research has uncovered","meaning":"最新研究揭示了","examples":[{"en":"Recent research has uncovered intriguing new findings about the fungus.","zh":"最新研究揭示了關於真菌的引人入勝的新發現。"},{"en":"Recent research has uncovered means new studies have discovered or revealed something previously unknown.","zh":"recent research has uncovered 指新研究發現或揭示了以前未知的事情。"},{"en":"Recent research has uncovered links between poor sleep and weaker concentration.","zh":"最新研究揭示了睡眠不足與專注力較弱之間的關係。"},{"en":"If research uncovers a hidden problem, scientists may need to rethink older beliefs.","zh":"如果研究揭示隱藏問題，科學家可能需要重新思考舊有看法。"},{"en":"The phrase is often used when new evidence changes understanding.","zh":"這個片語常用於新證據改變理解時。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":1},{"front":"intriguing new findings","meaning":"引人入勝的新發現","examples":[{"en":"The study uncovered intriguing new findings about how the ants cultivate fungus.","zh":"該研究揭示了螞蟻如何培植真菌的引人入勝的新發現。"},{"en":"Intriguing new findings are new discoveries that are interesting and make people want to know more.","zh":"intriguing new findings 指有趣並令人想了解更多的新發現。"},{"en":"A school science project may produce intriguing new findings about how plants grow under different lights.","zh":"學校科學項目可能產生關於植物如何在不同燈光下生長的引人入勝的新發現。"},{"en":"If findings are intriguing, they may lead to further research and new questions.","zh":"如果發現引人入勝，它們可能帶來進一步研究和新問題。"},{"en":"The phrase suggests discovery plus curiosity.","zh":"這個片語暗示發現加上好奇心。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":1},{"front":"cultivate fungus","meaning":"培植真菌","examples":[{"en":"The ants cultivate fungus and protect it from dangerous pathogens.","zh":"螞蟻培植真菌，並保護它免受危險病原體侵害。"},{"en":"Cultivate fungus means grow and care for fungus deliberately, like farming it.","zh":"cultivate fungus 指刻意培養和照料真菌，像耕種一樣。"},{"en":"In a laboratory, scientists may cultivate fungus in dishes to study how it grows.","zh":"在實驗室中，科學家可能在培養皿中培植真菌，以研究其生長。"},{"en":"If ants cultivate fungus, they must provide food, space, and protection for it.","zh":"如果螞蟻培植真菌，就必須為它提供食物、空間和保護。"},{"en":"The phrase describes active growing, not accidental mould appearing.","zh":"這個片語描述主動培養，而不是霉菌偶然出現。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":1},{"front":"domesticate a fungus","meaning":"馴化真菌","examples":[{"en":"Scientists are interested in how the ants domesticated a fungus.","zh":"科學家對螞蟻如何馴化真菌感興趣。"},{"en":"Domesticate a fungus means adapt a wild fungus for regular use and cultivation.","zh":"domesticate a fungus 指把野生真菌改變成可定期使用和培植的品種。"},{"en":"Humans domesticated plants such as wheat by selecting useful traits over generations.","zh":"人類透過世代選擇有用特徵，馴化了小麥等植物。"},{"en":"If ants domesticate a fungus, the fungus may become dependent on the ants’ care.","zh":"如果螞蟻馴化真菌，該真菌可能變得依賴螞蟻照顧。"},{"en":"The phrase shows long-term control and use of another living thing.","zh":"這個片語顯示對另一種生物的長期控制和使用。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":1},{"front":"protect something from pathogens","meaning":"保護……免受病原體侵害","examples":[{"en":"The ants protect the fungus from pathogens in their nests.","zh":"螞蟻在巢中保護真菌免受病原體侵害。"},{"en":"Protect something from pathogens means keep it safe from disease-causing organisms.","zh":"protect something from pathogens 指使某物免受致病生物侵害。"},{"en":"Washing hands helps protect patients from pathogens in hospitals.","zh":"洗手有助在醫院保護病人免受病原體侵害。"},{"en":"If fungus is not protected from pathogens, disease can spread through the garden.","zh":"如果真菌沒有受到保護免受病原體侵害，疾病可以在菌園中擴散。"},{"en":"The phrase is common in biology, health, and farming contexts.","zh":"這個片語常見於生物、健康和農業情境。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":1},{"front":"fungus farms","meaning":"真菌農場","examples":[{"en":"The fungus farms were once thought to be free of pathogens.","zh":"真菌農場曾被認為沒有病原體。"},{"en":"Fungus farms are places where fungus is deliberately grown as a food source.","zh":"fungus farms 指刻意培植真菌作為食物來源的地方。"},{"en":"Leaf-cutting ants maintain fungus farms inside their underground nests.","zh":"切葉蟻在地下巢穴中維持真菌農場。"},{"en":"If fungus farms become infected, the ants may lose their main food source.","zh":"如果真菌農場受到感染，螞蟻可能失去主要食物來源。"},{"en":"The phrase compares the ants’ fungus gardens to human farms.","zh":"這個片語把螞蟻的菌園比作人類農場。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":1},{"front":"keep something free of pathogens","meaning":"使……不受病原體污染","examples":[{"en":"The ants were thought to keep their fungus farms free of pathogens.","zh":"螞蟻曾被認為能使其真菌農場不受病原體污染。"},{"en":"Keep something free of pathogens means prevent disease-causing organisms from entering or growing there.","zh":"keep something free of pathogens 指防止致病生物進入或在其中生長。"},{"en":"Hospitals clean equipment carefully to keep treatment rooms free of pathogens.","zh":"醫院仔細清潔設備，以使治療室不受病原體污染。"},{"en":"If ants keep a garden free of pathogens, the fungus can grow safely.","zh":"如果螞蟻使菌園不受病原體污染，真菌就能安全生長。"},{"en":"The phrase suggests active prevention and cleanliness.","zh":"這個片語暗示主動預防和清潔。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":1},{"front":"turn out to be","meaning":"結果是；原來是","examples":[{"en":"The fungus farms turn out to be vulnerable to a devastating mould.","zh":"真菌農場結果原來容易受到破壞力極強的霉菌侵害。"},{"en":"Turn out to be means are discovered later to be a certain way.","zh":"turn out to be 指後來被發現其實是某種情況。"},{"en":"The easy homework turned out to be difficult when students tried to explain their answers.","zh":"看似容易的功課在學生嘗試解釋答案時，原來很難。"},{"en":"If a safe-looking system turns out to be vulnerable, old assumptions must change.","zh":"如果看似安全的系統原來很脆弱，舊假設就必須改變。"},{"en":"The phrase often introduces a surprising result.","zh":"這個片語常引出令人意外的結果。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":2},{"front":"be vulnerable to","meaning":"容易受到……侵害","examples":[{"en":"The fungus farms are vulnerable to a devastating mould.","zh":"真菌農場容易受到破壞力極強的霉菌侵害。"},{"en":"Be vulnerable to means be easily harmed, attacked, or damaged by something.","zh":"be vulnerable to 指容易被某事傷害、攻擊或破壞。"},{"en":"Young children are vulnerable to heat if they play outside without water.","zh":"幼兒如果在戶外玩耍但沒有水，就容易受高溫影響。"},{"en":"If a crop has little genetic diversity, it may be vulnerable to disease.","zh":"如果作物缺乏基因多樣性，可能容易受疾病侵害。"},{"en":"The phrase highlights weakness or risk.","zh":"這個片語突出弱點或風險。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":2},{"front":"devastating mould","meaning":"破壞力極強的霉菌","examples":[{"en":"A devastating mould can attack the ants’ fungus farms.","zh":"破壞力極強的霉菌可以攻擊螞蟻的真菌農場。"},{"en":"Devastating mould is mould that can cause severe damage or destruction.","zh":"devastating mould 指能造成嚴重損害或破壞的霉菌。"},{"en":"Mould in a damp house can become serious if it damages walls and health.","zh":"潮濕房屋中的霉菌如果損害牆壁和健康，就可能變得嚴重。"},{"en":"If a devastating mould spreads through a fungus garden, the ants may lose their food.","zh":"如果破壞力極強的霉菌在菌園中擴散，螞蟻可能失去食物。"},{"en":"The phrase describes a highly destructive fungal threat.","zh":"這個片語描述破壞性很高的真菌威脅。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":2},{"front":"found nowhere else but in","meaning":"只在……找到","examples":[{"en":"The mould is found nowhere else but in ants’ nests.","zh":"這種霉菌只在螞蟻巢中找到。"},{"en":"Found nowhere else but in means found only in one particular place and not anywhere else.","zh":"found nowhere else but in 指只在某特定地方找到，其他地方沒有。"},{"en":"A rare plant may be found nowhere else but on one small island.","zh":"稀有植物可能只在一個小島上找到。"},{"en":"If an organism is found only in ant nests, it may have evolved with those ants.","zh":"如果某生物只在螞蟻巢中找到，它可能與那些螞蟻共同演化。"},{"en":"The phrase strongly limits where something exists.","zh":"這個片語強烈限制某物存在的位置。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":2},{"front":"keep something in check","meaning":"控制住……","examples":[{"en":"The ants keep the mould in check with the help of bacteria.","zh":"螞蟻在細菌幫助下控制住霉菌。"},{"en":"Keep something in check means control it so it does not grow, spread, or become dangerous.","zh":"keep something in check 指控制某物，使其不會生長、擴散或變得危險。"},{"en":"Regular exercise can help keep stress in check before exams.","zh":"定期運動可以幫助在考試前控制壓力。"},{"en":"If ants fail to keep mould in check, the fungus garden may be destroyed.","zh":"如果螞蟻未能控制住霉菌，真菌園可能被摧毀。"},{"en":"The phrase suggests control rather than complete removal.","zh":"這個片語暗示控制，而不是完全清除。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":2},{"front":"make a discovery","meaning":"有所發現","examples":[{"en":"The ants made a discovery that would impress any pharmaceutical laboratory.","zh":"螞蟻有所發現，而這發現會令任何製藥實驗室印象深刻。"},{"en":"Make a discovery means find out something new or previously unknown.","zh":"make a discovery 指發現新的或以前未知的事情。"},{"en":"A student may make a discovery during a science project when an experiment behaves unexpectedly.","zh":"當實驗出現意外結果時，學生可能在科學項目中有所發現。"},{"en":"If scientists make a discovery, it can change how people understand a problem.","zh":"如果科學家有所發現，它可以改變人們如何理解問題。"},{"en":"The phrase is used for important new findings.","zh":"這個片語用於重要的新發現。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":2},{"front":"do credit to","meaning":"令……也感到自豪","examples":[{"en":"The ants made a discovery that would do credit to any pharmaceutical laboratory.","zh":"螞蟻有所發現，而這發現會令任何製藥實驗室也感到自豪。"},{"en":"Do credit to means be good enough to make someone or something proud.","zh":"do credit to 指好到足以令某人或某事感到自豪。"},{"en":"A student’s careful research project would do credit to a university class.","zh":"學生仔細完成的研究項目，足以令大學課堂也感到自豪。"},{"en":"If ants solve a disease problem well, their method could do credit to human science.","zh":"如果螞蟻能很好地解決疾病問題，其方法甚至可令人類科學感到自豪。"},{"en":"The phrase praises the quality of an achievement.","zh":"這個片語讚賞成就的質素。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":2},{"front":"pharmaceutical laboratory","meaning":"製藥實驗室","examples":[{"en":"The ants’ strategy would do credit to any pharmaceutical laboratory.","zh":"螞蟻的策略會令任何製藥實驗室也感到自豪。"},{"en":"A pharmaceutical laboratory is a place where medicines and drug-related substances are studied or developed.","zh":"pharmaceutical laboratory 指研究或開發藥物及相關物質的地方。"},{"en":"A pharmaceutical laboratory may test whether a chemical can kill harmful bacteria.","zh":"製藥實驗室可能測試某化學物能否殺死有害細菌。"},{"en":"If ants use bacteria to control disease, their strategy resembles medical research.","zh":"如果螞蟻利用細菌控制疾病，牠們的策略就類似醫學研究。"},{"en":"The phrase belongs to medicine and drug development.","zh":"這個片語屬於醫學和藥物開發範疇。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":2},{"front":"a marvel of nature","meaning":"大自然的奇觀","examples":[{"en":"Leaf-cutting ants and their fungus farms are a marvel of nature.","zh":"切葉蟻和牠們的真菌農場是大自然的奇觀。"},{"en":"A marvel of nature is something in the natural world that is amazing and impressive.","zh":"a marvel of nature 指自然界中令人驚嘆而印象深刻的事物。"},{"en":"A coral reef can be called a marvel of nature because it supports so many species.","zh":"珊瑚礁因支持大量物種，可以被稱為大自然的奇觀。"},{"en":"If a tiny insect manages farming, disease control, and cooperation, people may call it a marvel.","zh":"如果小昆蟲能做到農耕、疾病控制和合作，人們可能稱之為奇觀。"},{"en":"The phrase expresses wonder at natural complexity.","zh":"這個片語表達對自然複雜性的驚嘆。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":2},{"front":"the best known example of","meaning":"最著名的……例子","examples":[{"en":"The ant-fungus relationship is perhaps the best known example of symbiosis.","zh":"螞蟻與真菌的關係或許是共生關係最著名的例子。"},{"en":"The best known example of something is the example most people recognise or mention first.","zh":"the best known example of 指大多數人最認得或最先提到的例子。"},{"en":"The moon landing is one of the best known examples of human space exploration.","zh":"登月是人類太空探索最著名的例子之一。"},{"en":"If an example is famous and clear, teachers often use it to explain a concept.","zh":"如果例子有名又清楚，老師常用它來解釋概念。"},{"en":"The phrase points to a widely recognised case.","zh":"這個片語指出廣為人知的案例。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":2},{"front":"symbiosis","meaning":"共生關係","examples":[{"en":"Symbiosis means the mutual dependence of two species.","zh":"共生關係指兩個物種的相互依賴。"},{"en":"Symbiosis is a close relationship between different species, often helping one or both survive.","zh":"symbiosis 指不同物種之間的密切關係，通常幫助其中一方或雙方生存。"},{"en":"Bees and flowers show symbiosis because bees get food while flowers get pollinated.","zh":"蜜蜂和花展現共生關係，因為蜜蜂獲得食物，而花得到授粉。"},{"en":"If two organisms depend on each other, damage to one may harm the other.","zh":"如果兩種生物互相依賴，其中一方受損可能傷害另一方。"},{"en":"The word is important in ecology.","zh":"這個詞在生態學中很重要。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":3},{"front":"mutual dependence","meaning":"相互依賴","examples":[{"en":"The passage describes the mutual dependence of ants and fungus.","zh":"文章描述螞蟻和真菌的相互依賴。"},{"en":"Mutual dependence means two sides need each other.","zh":"mutual dependence 指雙方都需要彼此。"},{"en":"A school and parents may have mutual dependence because both support children’s learning.","zh":"學校和家長可能相互依賴，因為雙方都支持孩子學習。"},{"en":"If ants need fungus for food and fungus needs ants for care, the dependence is mutual.","zh":"如果螞蟻需要真菌作食物，而真菌需要螞蟻照顧，這種依賴就是相互的。"},{"en":"The phrase stresses that support goes both ways.","zh":"這個片語強調支持是雙向的。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":3},{"front":"two species","meaning":"兩個物種","examples":[{"en":"Symbiosis involves the mutual dependence of two species.","zh":"共生關係涉及兩個物種的相互依賴。"},{"en":"Two species means two different kinds of living organisms.","zh":"two species 指兩種不同的生物。"},{"en":"Cats and dogs are two species, even though both can live with humans.","zh":"貓和狗是兩個物種，雖然兩者都能與人類共同生活。"},{"en":"If two species interact closely, their survival may become connected.","zh":"如果兩個物種密切互動，牠們的生存可能變得相關。"},{"en":"The phrase is basic in biology and classification.","zh":"這個片語是生物學和分類中的基本概念。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":3},{"front":"the ants’ achievement","meaning":"螞蟻的成就","examples":[{"en":"The ants’ achievement is remarkable because it allows them to eat toxic leaves.","zh":"螞蟻的成就非常驚人，因為它讓牠們能吃有毒葉子。"},{"en":"The ants’ achievement means the impressive thing the ants have managed to do.","zh":"the ants’ achievement 指螞蟻成功做到的令人印象深刻的事情。"},{"en":"A student’s achievement may be finishing a difficult book in English for the first time.","zh":"學生的成就可能是第一次讀完整本英文難書。"},{"en":"If ants turn poisonous plant material into usable food, their achievement is biologically impressive.","zh":"如果螞蟻把有毒植物材料變成可用食物，其成就在生物學上令人印象深刻。"},{"en":"The phrase highlights success produced by behaviour or adaptation.","zh":"這個片語突出由行為或適應帶來的成功。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":3},{"front":"major breakthroughs in animal evolution","meaning":"動物演化上的重大突破","examples":[{"en":"Edward O. Wilson called this one of the major breakthroughs in animal evolution.","zh":"Edward O. Wilson 稱這是動物演化上的重大突破之一。"},{"en":"Major breakthroughs in animal evolution are important developments that greatly change how animals live or survive.","zh":"major breakthroughs in animal evolution 指大大改變動物生活或生存方式的重要發展。"},{"en":"Flight in birds was a major breakthrough because it opened new ways to travel and feed.","zh":"鳥類飛行是一項重大突破，因為它開啟新的移動和覓食方式。"},{"en":"If fungus farming allowed ants to use toxic leaves, it became a major evolutionary advantage.","zh":"如果真菌農耕讓螞蟻利用有毒葉子，它就成為重大演化優勢。"},{"en":"The phrase describes large, important steps in biological history.","zh":"這個片語描述生物歷史上的重大步伐。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":3},{"front":"courtesy of","meaning":"多得；歸功於","examples":[{"en":"The ants can eat toxic leaves, courtesy of the fungus’s digestive powers.","zh":"多得真菌的消化能力，螞蟻可以吃有毒葉子。"},{"en":"Courtesy of means because of the help, effect, or contribution of someone or something.","zh":"courtesy of 指因某人或某事的幫助、作用或貢獻。"},{"en":"Students learned the news quickly, courtesy of the school’s messaging app.","zh":"多得學校通訊應用程式，學生很快知道消息。"},{"en":"If ants can use toxic leaves courtesy of fungus, the fungus provides the key ability.","zh":"如果螞蟻能多得真菌而利用有毒葉子，真菌就提供了關鍵能力。"},{"en":"The phrase often gives credit to the source of a benefit.","zh":"這個片語常把好處歸功於來源。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":3},{"front":"digestive powers","meaning":"消化能力","examples":[{"en":"The fungus’s digestive powers allow the ants to process toxic leaves.","zh":"真菌的消化能力讓螞蟻處理有毒葉子。"},{"en":"Digestive powers are abilities to break down food or substances into usable parts.","zh":"digestive powers 指把食物或物質分解成可用部分的能力。"},{"en":"The stomach’s digestive powers help people turn food into energy.","zh":"胃的消化能力幫助人把食物轉化為能量。"},{"en":"If fungus has strong digestive powers, it can process plant chemicals that ants cannot handle alone.","zh":"如果真菌有強大消化能力，就能處理螞蟻單靠自己無法應付的植物化學物。"},{"en":"The phrase refers to biological ability to break down material.","zh":"這個片語指分解物質的生物能力。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":3},{"front":"otherwise poisoned harvest","meaning":"本來有毒的收成；食物來源","examples":[{"en":"The fungus helps the ants use an otherwise poisoned harvest from tropical forests.","zh":"真菌幫助螞蟻利用來自熱帶森林、本來有毒的收成。"},{"en":"An otherwise poisoned harvest is plant material that would be poisonous without some special help.","zh":"otherwise poisoned harvest 指如果沒有特殊幫助，本來會有毒的植物材料。"},{"en":"Bitter plants may be useless as food unless cooking removes harmful chemicals.","zh":"苦味植物除非經烹煮去除有害化學物，否則可能無法作食物。"},{"en":"If fungus digests toxic leaves, the ants can turn dangerous material into food.","zh":"如果真菌消化有毒葉子，螞蟻就能把危險材料變成食物。"},{"en":"The phrase contrasts danger before treatment with usefulness after treatment.","zh":"這個片語對比處理前的危險和處理後的有用。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":3},{"front":"tropical forests","meaning":"熱帶森林","examples":[{"en":"The ants harvest leaves from tropical forests.","zh":"螞蟻從熱帶森林收集葉子。"},{"en":"Tropical forests are warm, often wet forests found near the equator.","zh":"tropical forests 指位於赤道附近、溫暖且通常潮濕的森林。"},{"en":"Tropical forests contain many plants, insects, birds, and other animals.","zh":"熱帶森林包含許多植物、昆蟲、鳥類和其他動物。"},{"en":"If ants live in tropical forests, they may encounter many leaves full of defensive chemicals.","zh":"如果螞蟻生活在熱帶森林中，可能遇到許多充滿防禦化學物的葉子。"},{"en":"The phrase describes a rich warm forest environment.","zh":"這個片語描述豐富而溫暖的森林環境。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":3},{"front":"leaves are laden with","meaning":"葉子充滿……","examples":[{"en":"The leaves are laden with chemicals that can sicken browsers.","zh":"葉子充滿可令食葉動物生病的化學物質。"},{"en":"Leaves are laden with means the leaves contain a large amount of something.","zh":"leaves are laden with 指葉子含有大量某物。"},{"en":"A school bag laden with books can become too heavy for a child.","zh":"裝滿書本的書包可能對孩子來說太重。"},{"en":"If leaves are laden with toxins, animals that eat them may become sick.","zh":"如果葉子充滿毒素，吃下它們的動物可能生病。"},{"en":"The phrase suggests heavy or rich content.","zh":"這個片語暗示含量很高或負載很重。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":3},{"front":"terpenoids","meaning":"萜類化合物","examples":[{"en":"Tropical leaves are laden with terpenoids and other chemicals.","zh":"熱帶葉子充滿萜類化合物和其他化學物。"},{"en":"Terpenoids are plant chemicals that can affect smell, taste, defence, or toxicity.","zh":"terpenoids 指可影響氣味、味道、防禦或毒性的植物化學物。"},{"en":"Some plant smells come from chemical compounds related to terpenoids.","zh":"有些植物氣味來自與萜類化合物相關的化學成分。"},{"en":"If leaves contain terpenoids, they may be less attractive or more harmful to browsers.","zh":"如果葉子含有萜類化合物，可能較不吸引食葉動物或對牠們更有害。"},{"en":"The word is a technical term from plant chemistry.","zh":"這個詞是植物化學中的技術術語。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":4},{"front":"alkaloids","meaning":"生物鹼","examples":[{"en":"The leaves contain alkaloids that can make browsers sick.","zh":"葉子含有可令食葉動物生病的生物鹼。"},{"en":"Alkaloids are natural plant chemicals, many of which can affect animals’ bodies strongly.","zh":"alkaloids 指天然植物化學物，其中許多能強烈影響動物身體。"},{"en":"Caffeine is a familiar alkaloid found in coffee and tea.","zh":"咖啡因是咖啡和茶中常見的生物鹼。"},{"en":"If leaves contain harmful alkaloids, animals may avoid eating them.","zh":"如果葉子含有有害生物鹼，動物可能避免吃它們。"},{"en":"The word is technical and often appears in biology or chemistry.","zh":"這個詞屬技術用語，常見於生物或化學。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":4},{"front":"chemicals designed to","meaning":"旨在……的化學物質","examples":[{"en":"The leaves contain chemicals designed to sicken browsers.","zh":"葉子含有旨在令食葉動物生病的化學物質。"},{"en":"Chemicals designed to means chemicals whose effect is to cause a particular result.","zh":"chemicals designed to 指作用是造成某特定結果的化學物質。"},{"en":"Cleaning products contain chemicals designed to kill germs.","zh":"清潔用品含有旨在殺死細菌的化學物質。"},{"en":"If plants contain chemicals designed to harm browsers, the chemicals act as defence.","zh":"如果植物含有旨在傷害食葉動物的化學物，它們就起防禦作用。"},{"en":"The phrase explains the function of a chemical.","zh":"這個片語解釋化學物的功能。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":4},{"front":"sicken browsers","meaning":"令食葉動物生病","examples":[{"en":"Certain plant chemicals are designed to sicken browsers.","zh":"某些植物化學物質旨在令食葉動物生病。"},{"en":"Sicken browsers means make leaf-eating animals ill.","zh":"sicken browsers 指令吃葉子的動物生病。"},{"en":"A plant may sicken insects that eat its leaves by producing bitter chemicals.","zh":"植物可能透過產生苦味化學物，令吃其葉子的昆蟲生病。"},{"en":"If leaves sicken browsers, fewer animals will continue eating that plant.","zh":"如果葉子令食葉動物生病，較少動物會繼續吃那種植物。"},{"en":"The phrase describes a plant defence against animals that feed on leaves.","zh":"這個片語描述植物對食葉動物的防禦。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":4},{"front":"fungus growing","meaning":"真菌培植","examples":[{"en":"Fungus growing seems to have originated only once in evolution.","zh":"真菌培植似乎在演化過程中只起源過一次。"},{"en":"Fungus growing means the practice or ability of cultivating fungus.","zh":"fungus growing 指培植真菌的做法或能力。"},{"en":"Mushroom farms are human examples of fungus growing for food.","zh":"蘑菇農場是人類為食物進行真菌培植的例子。"},{"en":"If fungus growing began only once among these ants, all later farming ants may share one origin.","zh":"如果這些螞蟻中的真菌培植只起源一次，後來所有農耕螞蟻可能有共同來源。"},{"en":"The phrase refers to cultivation, not random fungal growth.","zh":"這個片語指培植，而不是隨機的真菌生長。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":4},{"front":"originate only once","meaning":"只起源過一次","examples":[{"en":"Fungus growing seems to have originated only once in evolution.","zh":"真菌培植似乎在演化中只起源過一次。"},{"en":"Originate only once means begin from a single original event rather than many separate beginnings.","zh":"originate only once 指源自單一原始事件，而不是多次獨立開始。"},{"en":"A school tradition may originate only once but continue for many generations.","zh":"學校傳統可能只起源過一次，卻延續許多代。"},{"en":"If a behaviour originates only once, related groups may have inherited it from one ancestor.","zh":"如果某行為只起源過一次，相關類群可能從同一祖先繼承它。"},{"en":"The phrase focuses on a single starting point.","zh":"這個片語集中於單一起點。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":4},{"front":"in evolution","meaning":"在演化過程中","examples":[{"en":"This farming behaviour appears to have developed only once in evolution.","zh":"這種農耕行為似乎在演化過程中只發展過一次。"},{"en":"In evolution means in the long process by which living things change over generations.","zh":"in evolution 指在生物跨世代改變的漫長過程中。"},{"en":"Flight appeared at different times in evolution among insects, birds, and bats.","zh":"飛行在演化過程中於昆蟲、鳥類和蝙蝠中不同時間出現。"},{"en":"If a trait develops in evolution, it may help organisms survive or reproduce.","zh":"如果某特徵在演化中發展出來，它可能幫助生物生存或繁殖。"},{"en":"The phrase places a feature within biological history.","zh":"這個片語把某特徵放在生物歷史中理解。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":4},{"front":"gardening ants","meaning":"從事真菌園藝的螞蟻","examples":[{"en":"All gardening ants belong to a single tribe.","zh":"所有從事真菌園藝的螞蟻都屬於同一族群。"},{"en":"Gardening ants are ants that cultivate fungus gardens.","zh":"gardening ants 指會培植真菌園的螞蟻。"},{"en":"In class, students may call these insects gardening ants because they farm fungus like tiny gardeners.","zh":"在課堂中，學生可能稱這些昆蟲為園藝螞蟻，因為牠們像小園丁一樣種真菌。"},{"en":"If ants grow and care for fungus, the word gardening highlights their active cultivation.","zh":"如果螞蟻種植並照顧真菌，gardening 這個詞就突出牠們的主動培植。"},{"en":"The phrase is a simple way to describe fungus-farming ants.","zh":"這個片語是描述真菌農耕螞蟻的簡單說法。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":4},{"front":"belong to a single tribe","meaning":"屬於同一族群","examples":[{"en":"All gardening ants belong to a single tribe.","zh":"所有從事真菌園藝的螞蟻都屬於同一族群。"},{"en":"Belong to a single tribe means are classified within one related biological group.","zh":"belong to a single tribe 指被分類在一個相關生物群體之內。"},{"en":"Several school clubs may belong to a single student association.","zh":"幾個學校學會可能屬於同一學生組織。"},{"en":"If all gardening ants belong to one tribe, they may share a common evolutionary origin.","zh":"如果所有真菌園藝螞蟻都屬於同一族群，牠們可能有共同演化來源。"},{"en":"The phrase describes membership in one group.","zh":"這個片語描述屬於同一群體。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":4},{"front":"descendants of","meaning":"……的後代","examples":[{"en":"The attine ants are descendants of the first fungus farmer.","zh":"Attini 蟻是首個真菌農夫的後代。"},{"en":"Descendants of means later generations that come from an earlier ancestor.","zh":"descendants of 指來自較早祖先的後代。"},{"en":"Many modern families are descendants of migrants who moved generations ago.","zh":"許多現代家庭是幾代前移民的後代。"},{"en":"If ants are descendants of one early fungus farmer, their farming behaviour may share one origin.","zh":"如果螞蟻是某個早期真菌農夫的後代，其農耕行為可能有同一來源。"},{"en":"The phrase links present members to earlier ancestors.","zh":"這個片語把現今成員與早期祖先連接起來。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":4},{"front":"the first fungus farmer","meaning":"首個真菌農夫","examples":[{"en":"The gardening ants are descendants of the first fungus farmer.","zh":"從事真菌園藝的螞蟻是首個真菌農夫的後代。"},{"en":"The first fungus farmer means the earliest ancestor that began cultivating fungus.","zh":"the first fungus farmer 指最早開始培植真菌的祖先。"},{"en":"A family may remember the first shopkeeper who began a business tradition.","zh":"家族可能記得首位開展生意傳統的店主。"},{"en":"If one early ant began fungus farming, later species may have inherited the behaviour.","zh":"如果一隻早期螞蟻開始真菌農耕，後來物種可能繼承該行為。"},{"en":"The phrase gives a vivid farming image to an evolutionary ancestor.","zh":"這個片語用生動農耕形象描述演化祖先。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":5},{"front":"known species of","meaning":"已知的……物種","examples":[{"en":"There are more than 200 known species of attine ants.","zh":"已知的 Attini 蟻物種超過200種。"},{"en":"Known species of means species that scientists have identified and described.","zh":"known species of 指科學家已識別並描述的物種。"},{"en":"There are many known species of butterflies, but new ones may still be discovered.","zh":"已知的蝴蝶物種有很多，但仍可能發現新品種。"},{"en":"If the number of known species rises, research has expanded classification.","zh":"如果已知物種數量上升，研究就擴展了分類。"},{"en":"The phrase refers to scientifically recognised species.","zh":"這個片語指科學上已確認的物種。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":5},{"front":"attine ant tribe","meaning":"Attini 蟻族；切葉蟻族群","examples":[{"en":"There are more than 200 known species in the attine ant tribe.","zh":"Attini 蟻族中有超過200種已知物種。"},{"en":"The attine ant tribe is a biological group of ants known for fungus farming.","zh":"attine ant tribe 指以真菌農耕聞名的一個螞蟻生物族群。"},{"en":"Biology students may study the attine ant tribe as an example of insect agriculture.","zh":"生物學生可能研究 Attini 蟻族，作為昆蟲農業的例子。"},{"en":"If many species belong to the tribe, their farming methods can be compared.","zh":"如果許多物種屬於這族群，就可以比較牠們的農耕方法。"},{"en":"The phrase names the ant group central to this passage.","zh":"這個片語指文章中的核心螞蟻群體。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":5},{"front":"be divided into","meaning":"被分為","examples":[{"en":"The attine ant tribe is divided into 12 genera.","zh":"Attini 蟻族被分為12個屬。"},{"en":"Be divided into means be separated or classified into smaller groups.","zh":"be divided into 指被分成或分類成較小群組。"},{"en":"A class may be divided into groups for a project.","zh":"班級可能被分為小組完成項目。"},{"en":"If a tribe is divided into genera, scientists can organise related species more clearly.","zh":"如果一個族群被分為不同屬，科學家就能更清楚組織相關物種。"},{"en":"The phrase is useful for classification and organisation.","zh":"這個片語適合用於分類和組織。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":5},{"front":"genera","meaning":"屬；生物分類中的屬","examples":[{"en":"The attine ants are divided into 12 groups, or genera.","zh":"Attini 蟻被分為12個群組，即12個屬。"},{"en":"Genera are biological classification groups above species and below family.","zh":"genera 指生物分類中高於物種、低於科的分類群。"},{"en":"In biology, cats and lions belong to different species but related genera within the cat family.","zh":"在生物學中，家貓和獅子屬於不同物種，但在貓科中屬於相關的屬。"},{"en":"If scientists identify genera, they can show which species are closely related.","zh":"如果科學家識別不同屬，就能顯示哪些物種關係密切。"},{"en":"The word is the plural of genus.","zh":"這個詞是 genus 的眾數。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":5},{"front":"fresh vegetation","meaning":"新鮮植物","examples":[{"en":"The leaf-cutters use fresh vegetation to feed their fungus.","zh":"切葉蟻使用新鮮植物餵養其真菌。"},{"en":"Fresh vegetation means newly cut or living plant material such as leaves and stems.","zh":"fresh vegetation 指新近切下或仍有生命力的植物材料，例如葉子和莖。"},{"en":"Gardeners may collect fresh vegetation to feed compost bins.","zh":"園丁可能收集新鮮植物來餵養堆肥箱。"},{"en":"If ants bring fresh vegetation to their gardens, the fungus receives new material to grow on.","zh":"如果螞蟻把新鮮植物帶到菌園，真菌就得到新材料生長。"},{"en":"The phrase contrasts fresh plant matter with dead leaves or waste.","zh":"這個片語把新鮮植物材料與枯葉或廢物作對比。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":5},{"front":"lower attines","meaning":"較低等的 Attini 蟻群","examples":[{"en":"The lower attines have smaller nests and more primitive techniques.","zh":"較低等的 Attini 蟻群有較小巢穴和較原始技術。"},{"en":"Lower attines are less advanced fungus-farming ants compared with leaf-cutters.","zh":"lower attines 指與切葉蟻相比，較不進階的真菌農耕螞蟻。"},{"en":"A biology chart may compare lower attines with leaf-cutting ants to show different farming methods.","zh":"生物圖表可能比較較低等 Attini 蟻群和切葉蟻，以展示不同農耕方法。"},{"en":"If lower attines use simpler materials, their fungus gardens may differ from leaf-cutters’ gardens.","zh":"如果較低等 Attini 蟻群使用較簡單材料，其菌園可能與切葉蟻的菌園不同。"},{"en":"The phrase refers to a subgroup of attine ants.","zh":"這個片語指 Attini 蟻中的一個亞群。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":5},{"front":"more primitive techniques","meaning":"較原始的技術","examples":[{"en":"The lower attines use more primitive techniques than leaf-cutters.","zh":"較低等 Attini 蟻群使用比切葉蟻較原始的技術。"},{"en":"More primitive techniques are simpler or less developed methods.","zh":"more primitive techniques 指較簡單或較不發達的方法。"},{"en":"A small workshop may use more primitive techniques when it has no modern machines.","zh":"小型工場沒有現代機器時，可能使用較原始的技術。"},{"en":"If ants use more primitive techniques, their farming may be less specialised.","zh":"如果螞蟻使用較原始技術，其農耕可能較不專門。"},{"en":"The phrase compares levels of development.","zh":"這個片語比較發展程度。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":5},{"front":"feed their gardens with","meaning":"用……餵養其菌園","examples":[{"en":"The lower attines feed their gardens with detritus.","zh":"較低等 Attini 蟻群用有機碎屑餵養其菌園。"},{"en":"Feed their gardens with means provide a garden with material that helps it grow.","zh":"feed their gardens with 指為菌園提供有助生長的材料。"},{"en":"Gardeners feed their plants with compost and water.","zh":"園丁用堆肥和水餵養植物。"},{"en":"If ants feed fungus gardens with dead material, the fungus uses it as food.","zh":"如果螞蟻用死去材料餵養真菌園，真菌就把它用作食物。"},{"en":"The phrase treats the garden as something that needs nourishment.","zh":"這個片語把菌園視為需要滋養的東西。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":5},{"front":"detritus","meaning":"有機碎屑","examples":[{"en":"The lower attines feed their gardens with detritus such as dead leaves.","zh":"較低等 Attini 蟻群用枯葉等有機碎屑餵養其菌園。"},{"en":"Detritus is dead organic material, such as fallen leaves, dead insects, or waste.","zh":"detritus 指死去的有機材料，例如落葉、死昆蟲或廢物。"},{"en":"Compost piles contain detritus that slowly breaks down into rich soil.","zh":"堆肥堆包含會慢慢分解成肥沃泥土的有機碎屑。"},{"en":"If ants use detritus, they rely on old organic matter rather than fresh leaves.","zh":"如果螞蟻使用有機碎屑，牠們依賴舊有機物，而不是新鮮葉子。"},{"en":"The word is common in ecology.","zh":"這個詞常見於生態學。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":5},{"front":"dead leaves, insects and faeces","meaning":"枯葉、昆蟲和糞便","examples":[{"en":"The lower attines use dead leaves, insects and faeces in their gardens.","zh":"較低等 Attini 蟻群在其菌園中使用枯葉、昆蟲和糞便。"},{"en":"Dead leaves, insects and faeces are examples of organic waste materials.","zh":"dead leaves, insects and faeces 是有機廢物材料的例子。"},{"en":"Compost can include dead leaves and other natural waste, though not all waste is safe to use.","zh":"堆肥可以包括枯葉和其他天然廢物，但並非所有廢物都適合使用。"},{"en":"If ants use these materials, their fungus gardens are fed by decomposing matter.","zh":"如果螞蟻使用這些材料，其真菌園就是由分解中的物質餵養。"},{"en":"The phrase lists the kinds of detritus used by lower attines.","zh":"這個片語列出較低等 Attini 蟻群使用的有機碎屑種類。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":6},{"front":"be descended from","meaning":"源自……","examples":[{"en":"The leaf-cutters’ fungus was descended from a single strain.","zh":"切葉蟻的真菌源自單一菌株。"},{"en":"Be descended from means come from an earlier ancestor, source, or original form.","zh":"be descended from 指來自較早的祖先、來源或原始形式。"},{"en":"Many modern languages are descended from older languages.","zh":"許多現代語言源自較古老的語言。"},{"en":"If a fungus is descended from one strain, its later forms may be genetically similar.","zh":"如果真菌源自一個菌株，其後來形態可能在基因上相似。"},{"en":"The phrase explains origin and ancestry.","zh":"這個片語解釋來源和祖先。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":6},{"front":"a single strain","meaning":"單一菌株","examples":[{"en":"The leaf-cutters’ fungus came from a single strain.","zh":"切葉蟻的真菌來自單一菌株。"},{"en":"A single strain is one particular genetic variety of an organism.","zh":"a single strain 指某生物的一個特定基因品種。"},{"en":"A laboratory may grow a single strain of bacteria to keep results consistent.","zh":"實驗室可能培養單一菌株的細菌，以保持結果一致。"},{"en":"If crops all come from a single strain, disease may spread through them easily.","zh":"如果作物全都來自單一菌株，疾病可能很容易在其中擴散。"},{"en":"The phrase highlights genetic uniformity.","zh":"這個片語突出基因一致性。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":6},{"front":"be propagated clonally","meaning":"以克隆方式繁殖","examples":[{"en":"The fungus was propagated clonally for millions of years.","zh":"這種真菌數百萬年來以克隆方式繁殖。"},{"en":"Be propagated clonally means be reproduced by making genetically identical copies.","zh":"be propagated clonally 指透過製造基因相同的複製體來繁殖。"},{"en":"Gardeners can propagate some plants clonally by taking cuttings.","zh":"園丁可以透過插枝以克隆方式繁殖某些植物。"},{"en":"If a fungus is propagated clonally, it may remain genetically similar over long periods.","zh":"如果真菌以克隆方式繁殖，它可能在長時間內保持基因相似。"},{"en":"The phrase describes reproduction without mixing different genetic lines.","zh":"這個片語描述沒有混合不同基因系的繁殖。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":6},{"front":"by budding","meaning":"透過出芽繁殖","examples":[{"en":"The fungus was propagated clonally, or simply by budding.","zh":"這種真菌以克隆方式繁殖，或簡單來說透過出芽繁殖。"},{"en":"By budding means by forming a small new growth that separates or develops into a new organism.","zh":"by budding 指形成一個小的新生部分，然後分離或發展成新個體。"},{"en":"Yeast can reproduce by budding in simple biology experiments.","zh":"酵母可以在簡單生物實驗中透過出芽繁殖。"},{"en":"If a fungus grows by budding, new individuals can be genetically identical to the original.","zh":"如果真菌透過出芽繁殖，新個體可與原本個體基因相同。"},{"en":"The phrase describes one method of clonal reproduction.","zh":"這個片語描述克隆繁殖的一種方法。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":6},{"front":"for at least 23 million years","meaning":"至少二千三百萬年以來","examples":[{"en":"The fungus was propagated clonally for at least 23 million years.","zh":"這種真菌至少二千三百萬年以來以克隆方式繁殖。"},{"en":"For at least 23 million years means for no less than 23 million years.","zh":"for at least 23 million years 指不少於二千三百萬年的時間。"},{"en":"Some animal groups have existed for at least millions of years, according to fossil evidence.","zh":"根據化石證據，有些動物類群已存在至少數百萬年。"},{"en":"If a relationship lasts for at least 23 million years, it is extremely stable in evolutionary terms.","zh":"如果一種關係至少持續二千三百萬年，以演化角度而言極其穩定。"},{"en":"The phrase gives a minimum length of time.","zh":"這個片語給出最低時間長度。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":6},{"front":"use different varieties of","meaning":"使用不同品種的……","examples":[{"en":"The lower attine ants use different varieties of the fungus.","zh":"較低等 Attini 蟻使用不同品種的真菌。"},{"en":"Use different varieties of means use several types rather than only one.","zh":"use different varieties of 指使用幾種類型，而不是只用一種。"},{"en":"A restaurant may use different varieties of rice for different dishes.","zh":"餐廳可能為不同菜式使用不同品種的米。"},{"en":"If ants use different fungus varieties, disease may not destroy every garden in the same way.","zh":"如果螞蟻使用不同真菌品種，疾病未必以同一方式摧毀每個菌園。"},{"en":"The phrase highlights diversity.","zh":"這個片語突出多樣性。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":6},{"front":"a quite separate species","meaning":"完全不同的物種","examples":[{"en":"One group of ants used a quite separate species of fungus.","zh":"一群螞蟻使用一種完全不同的真菌物種。"},{"en":"A quite separate species means a completely different biological species.","zh":"a quite separate species 指完全不同的生物物種。"},{"en":"Cats and rabbits are quite separate species, even though both can be pets.","zh":"貓和兔是完全不同的物種，雖然兩者都可以是寵物。"},{"en":"If ants use a separate fungus species, their farming system may work differently.","zh":"如果螞蟻使用不同真菌物種，其農耕系統可能運作不同。"},{"en":"The phrase stresses clear biological difference.","zh":"這個片語強調清楚的生物差異。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":6},{"front":"a pure strain of fungus","meaning":"純種真菌菌株","examples":[{"en":"The leaf-cutters grow a pure strain of fungus.","zh":"切葉蟻培植純種真菌菌株。"},{"en":"A pure strain of fungus is a fungus type with little genetic mixing or variation.","zh":"a pure strain of fungus 指基因混合或變異很少的真菌類型。"},{"en":"Laboratories sometimes keep a pure strain of fungus so experiments stay consistent.","zh":"實驗室有時保存純種真菌菌株，以保持實驗一致。"},{"en":"If ants grow a pure strain, the crop may be efficient but vulnerable to disease.","zh":"如果螞蟻培植純種菌株，作物可能高效，但容易受疾病侵害。"},{"en":"The phrase highlights genetic uniformity in the fungus.","zh":"這個片語突出真菌中的基因一致性。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":6},{"front":"resemble monocultures","meaning":"類似單一栽培","examples":[{"en":"The pure strain of fungus resembled monocultures of human crops.","zh":"純種真菌菌株類似人類農作物的單一栽培。"},{"en":"Resemble monocultures means look or function like systems where one crop type is grown alone.","zh":"resemble monocultures 指看起來或運作上像只種一種作物的系統。"},{"en":"A classroom using only one teaching method may resemble a monoculture because there is little variety.","zh":"只使用一種教學方法的課室可能類似單一栽培，因為缺少變化。"},{"en":"If fungus gardens resemble monocultures, one disease may threaten many gardens at once.","zh":"如果真菌園類似單一栽培，一種疾病可能同時威脅許多菌園。"},{"en":"The phrase compares biological farming systems.","zh":"這個片語比較不同生物農耕系統。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":6},{"front":"monocultures","meaning":"單一栽培；單一作物栽培","examples":[{"en":"Monocultures can be productive but vulnerable to disease.","zh":"單一栽培可以產量高，但容易受疾病侵害。"},{"en":"Monocultures are farming systems in which only one crop variety is grown over a large area.","zh":"monocultures 指在大片地方只種植一種作物品種的農業系統。"},{"en":"A field planted only with one type of corn is a monoculture.","zh":"只種一種玉米的田地就是單一栽培。"},{"en":"If a disease attacks that crop, a monoculture may suffer heavy losses.","zh":"如果疾病攻擊那種作物，單一栽培可能遭受嚴重損失。"},{"en":"The word suggests efficiency but also risk.","zh":"這個詞暗示效率，也暗示風險。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":7},{"front":"human crops","meaning":"人類農作物","examples":[{"en":"The fungus reminded Mr Currie of monocultures of various human crops.","zh":"這種真菌令 Currie 先生想起各種人類農作物的單一栽培。"},{"en":"Human crops are plants grown by people for food, materials, or other uses.","zh":"human crops 指人類為食物、材料或其他用途而種植的植物。"},{"en":"Rice, wheat, potatoes, and corn are common human crops.","zh":"米、小麥、馬鈴薯和玉米都是常見人類農作物。"},{"en":"If human crops lack diversity, farmers may worry about disease spreading quickly.","zh":"如果人類農作物缺乏多樣性，農民可能擔心疾病迅速擴散。"},{"en":"The phrase contrasts human farming with ant farming.","zh":"這個片語把人類農耕與螞蟻農耕作對比。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":7},{"front":"productive for a while","meaning":"在一段時間內產量很高","examples":[{"en":"Monocultures can be very productive for a while.","zh":"單一栽培可以在一段時間內產量很高。"},{"en":"Productive for a while means producing a lot for a limited period before problems may appear.","zh":"productive for a while 指在有限時間內產出很多，但之後可能出現問題。"},{"en":"A student may be productive for a while when drinking too much coffee, but later become exhausted.","zh":"學生喝太多咖啡時可能一段時間內很有效率，但之後變得疲累。"},{"en":"If a crop system is productive for a while, farmers may not notice hidden risks at first.","zh":"如果作物系統在一段時間內產量高，農民起初可能看不到隱藏風險。"},{"en":"The phrase suggests short-term success that may not last.","zh":"這個片語暗示短期成功未必持久。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":7},{"front":"succumb to","meaning":"屈服於；受……擊潰","examples":[{"en":"Some monocultures eventually succumb to disastrous pathogens.","zh":"有些單一栽培最終受災難性病原體擊潰。"},{"en":"Succumb to means be defeated by disease, pressure, temptation, or difficulty.","zh":"succumb to 指被疾病、壓力、誘惑或困難打敗。"},{"en":"A tired student may succumb to sleep while studying late at night.","zh":"疲倦學生深夜溫習時可能抵不住睡意。"},{"en":"If crops succumb to a pathogen, they become damaged or die.","zh":"如果作物受病原體擊潰，就會受損或死亡。"},{"en":"The phrase suggests losing after resistance.","zh":"這個片語暗示抵抗後失敗。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":7},{"front":"disastrous pathogen","meaning":"災難性的病原體","examples":[{"en":"A disastrous pathogen can destroy a genetically uniform crop.","zh":"災難性的病原體可以摧毀基因一致的作物。"},{"en":"A disastrous pathogen is a disease-causing organism that creates severe damage.","zh":"disastrous pathogen 指造成嚴重損害的致病生物。"},{"en":"A new virus can become disastrous if it spreads quickly through crowded places.","zh":"如果新病毒在擁擠地方快速傳播，就可能變成災難性病原體。"},{"en":"If a pathogen attacks genetically similar crops, it may destroy many plants at once.","zh":"如果病原體攻擊基因相似的作物，可能一次過摧毀很多植物。"},{"en":"The phrase describes a very harmful biological threat.","zh":"這個片語描述非常有害的生物威脅。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":7},{"front":"the Irish potato blight","meaning":"愛爾蘭馬鈴薯疫病","examples":[{"en":"The Irish potato blight is an example of a disastrous crop disease.","zh":"愛爾蘭馬鈴薯疫病是災難性作物疾病的一個例子。"},{"en":"The Irish potato blight was a severe potato disease associated with crop failure in Ireland.","zh":"the Irish potato blight 指與愛爾蘭農作物失收有關的嚴重馬鈴薯病害。"},{"en":"History teachers may mention the Irish potato blight when discussing famine and agriculture.","zh":"歷史老師討論饑荒和農業時，可能提到愛爾蘭馬鈴薯疫病。"},{"en":"If a population depends heavily on one crop, a disease like potato blight can become catastrophic.","zh":"如果人口嚴重依賴一種作物，像馬鈴薯疫病這樣的疾病可能變成災難。"},{"en":"The phrase is used as a classic warning about crop vulnerability.","zh":"這個片語常作為作物脆弱性的經典警示。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":7},{"front":"lack genetic diversity","meaning":"缺乏基因多樣性","examples":[{"en":"Monocultures lack genetic diversity.","zh":"單一栽培缺乏基因多樣性。"},{"en":"Lack genetic diversity means have too little variety in genes across a population or crop.","zh":"lack genetic diversity 指一個族群或作物中的基因變化太少。"},{"en":"A class with students from only one background may lack diversity of experience.","zh":"如果班中學生只來自一種背景，可能缺乏經驗多樣性。"},{"en":"If crops lack genetic diversity, one disease may harm them all in the same way.","zh":"如果作物缺乏基因多樣性，一種疾病可能以同一方式傷害全部作物。"},{"en":"The phrase highlights a biological weakness.","zh":"這個片語突出一種生物弱點。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":7},{"front":"respond to changing environmental threats","meaning":"應對不斷變化的環境威脅","examples":[{"en":"Monocultures lack the genetic diversity to respond to changing environmental threats.","zh":"單一栽培缺乏基因多樣性，無法應對不斷變化的環境威脅。"},{"en":"Respond to changing environmental threats means adjust to new dangers in the environment.","zh":"respond to changing environmental threats 指適應環境中新出現的危險。"},{"en":"Cities respond to changing environmental threats by improving drainage and heat protection.","zh":"城市透過改善排水和防熱措施來應對不斷變化的環境威脅。"},{"en":"If crops cannot respond to new pests or diseases, harvests may fail.","zh":"如果作物不能應對新害蟲或疾病，收成可能失敗。"},{"en":"The phrase links adaptation with survival under change.","zh":"這個片語把適應與變化下的生存連接起來。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":7},{"front":"sitting ducks for","meaning":"容易成為……的目標","examples":[{"en":"Monocultures are sitting ducks for parasites.","zh":"單一栽培容易成為寄生物的目標。"},{"en":"Sitting ducks for means easy targets for attack or harm.","zh":"sitting ducks for 指很容易被攻擊或傷害的目標。"},{"en":"Students who never back up their files are sitting ducks for computer problems.","zh":"從不備份檔案的學生，很容易成為電腦問題的受害者。"},{"en":"If crops are genetically identical, parasites may attack them easily.","zh":"如果作物基因相同，寄生物可能很容易攻擊它們。"},{"en":"The phrase is informal and strongly suggests vulnerability.","zh":"這個片語較口語，強烈暗示脆弱。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":7},{"front":"parasites","meaning":"寄生物","examples":[{"en":"Mr Currie suspected that there had to be a parasite in the ant-fungus system.","zh":"Currie 先生懷疑螞蟻與真菌系統中必定有寄生物。"},{"en":"Parasites are organisms that live on or in another organism and take resources from it.","zh":"parasites 指生活在另一生物身上或體內，並從中取得資源的生物。"},{"en":"Fleas are parasites because they feed on the blood of animals.","zh":"跳蚤是寄生物，因為牠們吸食動物的血。"},{"en":"If a parasite enters a fungus garden, it may use the fungus while harming the ants’ food supply.","zh":"如果寄生物進入真菌園，可能利用真菌並傷害螞蟻的食物供應。"},{"en":"The word describes a living thing that benefits at another’s expense.","zh":"這個詞描述以犧牲另一方為代價而受益的生物。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":7},{"front":"the ant-fungus system","meaning":"螞蟻與真菌系統","examples":[{"en":"Mr Currie believed there had to be a parasite in the ant-fungus system.","zh":"Currie 先生認為螞蟻與真菌系統中必定有寄生物。"},{"en":"The ant-fungus system is the relationship and working arrangement between ants and the fungus they cultivate.","zh":"the ant-fungus system 指螞蟻與牠們培植的真菌之間的關係和運作安排。"},{"en":"A teacher may use the ant-fungus system to explain cooperation and dependence in nature.","zh":"老師可能使用螞蟻與真菌系統來解釋自然界中的合作和依賴。"},{"en":"If one part of the system is attacked, the whole arrangement can become unstable.","zh":"如果系統其中一部分受到攻擊，整個安排可能變得不穩定。"},{"en":"The phrase refers to the ants, fungus, and their connected roles.","zh":"這個片語指螞蟻、真菌以及牠們相連的角色。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":8},{"front":"a century of ant research","meaning":"一個世紀的螞蟻研究","examples":[{"en":"A century of ant research offered no support for the idea.","zh":"一個世紀的螞蟻研究並不支持這個想法。"},{"en":"A century of ant research means about one hundred years of scientific study on ants.","zh":"a century of ant research 指大約一百年關於螞蟻的科學研究。"},{"en":"A century of medical research can change how doctors understand disease.","zh":"一個世紀的醫學研究可以改變醫生對疾病的理解。"},{"en":"If one hundred years of research offers no support, a new idea may seem unlikely at first.","zh":"如果一百年研究都不支持某想法，新觀點起初可能顯得不太可能。"},{"en":"The phrase stresses a long research history.","zh":"這個片語強調漫長研究歷史。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":8},{"front":"offer no support for","meaning":"不支持……","examples":[{"en":"The textbooks offered no support for Mr Currie’s idea.","zh":"教科書不支持 Currie 先生的想法。"},{"en":"Offer no support for means provide no evidence or backing for a claim.","zh":"offer no support for 指沒有提供證據或支持某主張。"},{"en":"The survey offered no support for the belief that students dislike reading.","zh":"調查不支持學生不喜歡閱讀這個看法。"},{"en":"If evidence offers no support for an idea, scientists may reject or question it.","zh":"如果證據不支持某想法，科學家可能拒絕或質疑它。"},{"en":"The phrase is used when data does not confirm a claim.","zh":"這個片語用於數據不能確認主張時。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":8},{"front":"scrupulously weed their gardens","meaning":"小心徹底地清除菌園中的雜物","examples":[{"en":"Leaf-cutter ants scrupulously weed their gardens of foreign organisms.","zh":"切葉蟻小心徹底地清除菌園中的外來生物。"},{"en":"Scrupulously weed their gardens means remove unwanted organisms from their gardens very carefully.","zh":"scrupulously weed their gardens 指非常仔細地從菌園中移除不想要的生物。"},{"en":"A gardener may carefully weed a vegetable patch so the crops get enough space and nutrients.","zh":"園丁可能仔細清除菜園雜草，讓作物有足夠空間和養分。"},{"en":"If ants weed their fungus gardens well, harmful organisms have fewer chances to spread.","zh":"如果螞蟻好好清理真菌園，有害生物就較少機會擴散。"},{"en":"The phrase emphasises thorough and careful cleaning.","zh":"這個片語強調徹底而小心的清潔。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":8},{"front":"foreign organisms","meaning":"外來生物","examples":[{"en":"The ants remove foreign organisms from their fungus gardens.","zh":"螞蟻從其真菌園中移除外來生物。"},{"en":"Foreign organisms are living things that do not belong in a particular place or system.","zh":"foreign organisms 指不屬於某特定地方或系統的生物。"},{"en":"A hospital must prevent foreign organisms from entering sterile equipment.","zh":"醫院必須防止外來生物進入無菌設備。"},{"en":"If foreign organisms enter a fungus garden, they may compete with or damage the crop.","zh":"如果外來生物進入真菌園，可能與作物競爭或傷害作物。"},{"en":"The phrase means outsiders in a biological system.","zh":"這個片語指生物系統中的外來者。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":8},{"front":"a hidden interloper","meaning":"隱藏的入侵者","examples":[{"en":"Mr Currie tried to find a hidden interloper in the gardens.","zh":"Currie 先生嘗試在菌園中尋找隱藏的入侵者。"},{"en":"A hidden interloper is an unwanted outsider that is present but not easily noticed.","zh":"a hidden interloper 指存在但不容易被注意到的不受歡迎外來者。"},{"en":"A hidden computer virus can be an interloper inside a school network.","zh":"隱藏電腦病毒可以是學校網絡中的入侵者。"},{"en":"If a hidden interloper grows unnoticed, it may cause damage before anyone reacts.","zh":"如果隱藏的入侵者在沒被察覺下生長，可能在任何人反應前造成損害。"},{"en":"The phrase suggests secret intrusion.","zh":"這個片語暗示秘密入侵。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":8},{"front":"far from free of infection","meaning":"遠非沒有感染","examples":[{"en":"The attine-ant gardens were far from free of infection.","zh":"Attini 蟻的菌園遠非沒有感染。"},{"en":"Far from free of infection means definitely infected or not clean from disease at all.","zh":"far from free of infection 指絕對不是沒有感染，或完全不是沒有疾病。"},{"en":"A kitchen that looks clean may still be far from free of bacteria if surfaces are not washed properly.","zh":"如果表面沒有正確清洗，看似乾淨的廚房仍可能遠非沒有細菌。"},{"en":"If fungus gardens are far from infection-free, ants must constantly control disease.","zh":"如果真菌園遠非沒有感染，螞蟻就必須持續控制疾病。"},{"en":"The phrase strongly rejects the idea of being clean or safe.","zh":"這個片語強烈否定乾淨或安全的想法。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":8},{"front":"issue of a scientific journal","meaning":"科學期刊的一期","examples":[{"en":"The findings appeared in an issue of a scientific journal.","zh":"這些發現刊登在科學期刊的一期中。"},{"en":"An issue of a scientific journal is one published edition of a research magazine.","zh":"issue of a scientific journal 指研究期刊出版的一期。"},{"en":"A student may find an article in an issue of a medical journal online.","zh":"學生可能在網上找到某一期醫學期刊中的文章。"},{"en":"If findings appear in a scientific journal, they are being shared with the research community.","zh":"如果發現刊登在科學期刊中，它們就是被分享給研究社群。"},{"en":"The phrase refers to formal academic publication.","zh":"這個片語指正式學術出版。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":8},{"front":"report isolating","meaning":"報告已分離出","examples":[{"en":"The researchers reported isolating several alien organisms.","zh":"研究人員報告已分離出幾種外來生物。"},{"en":"Report isolating means state that scientists successfully separated something for study.","zh":"report isolating 指說明科學家已成功把某物分離出來研究。"},{"en":"A laboratory may report isolating a new bacterium from a water sample.","zh":"實驗室可能報告已從水樣中分離出一種新細菌。"},{"en":"If researchers isolate an organism, they can examine it more clearly.","zh":"如果研究人員分離出生物，就能更清楚檢查它。"},{"en":"The phrase is common in scientific writing.","zh":"這個片語常見於科學寫作。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":8},{"front":"alien organisms","meaning":"外來生物","examples":[{"en":"The researchers isolated several alien organisms from the gardens.","zh":"研究人員從菌園中分離出幾種外來生物。"},{"en":"Alien organisms are organisms that do not naturally belong in a particular place or system.","zh":"alien organisms 指不自然屬於某特定地方或系統的生物。"},{"en":"Alien organisms in a lake may disturb native fish and plants.","zh":"湖泊中的外來生物可能擾亂本地魚類和植物。"},{"en":"If alien organisms enter a fungus garden, they may compete with the cultivated fungus.","zh":"如果外來生物進入真菌園，可能與培植真菌競爭。"},{"en":"The phrase means biological outsiders, not space aliens.","zh":"這個片語指生物外來者，而不是太空外星人。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":8},{"front":"parasitic moulds","meaning":"寄生霉菌","examples":[{"en":"The scientists found a family of parasitic moulds called Escovopsis.","zh":"科學家發現一個名為 Escovopsis 的寄生霉菌家族。"},{"en":"Parasitic moulds are moulds that live off another organism and harm it.","zh":"parasitic moulds 指依靠另一生物生存並傷害它的霉菌。"},{"en":"Parasitic fungi can damage plants by taking nutrients from them.","zh":"寄生真菌可以透過吸收植物養分來損害植物。"},{"en":"If parasitic moulds attack a fungus garden, the garden may collapse.","zh":"如果寄生霉菌攻擊真菌園，菌園可能崩潰。"},{"en":"The phrase combines fungal growth with parasitic behaviour.","zh":"這個片語結合真菌生長和寄生行為。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":9},{"front":"called Escovopsis","meaning":"名為 Escovopsis","examples":[{"en":"The moulds were called Escovopsis.","zh":"這些霉菌名為 Escovopsis。"},{"en":"Called Escovopsis means given the scientific name Escovopsis.","zh":"called Escovopsis 指被賦予 Escovopsis 這個科學名稱。"},{"en":"A newly identified species may be called by a Latin scientific name.","zh":"新識別的物種可能以拉丁科學名稱命名。"},{"en":"If a pathogen is called Escovopsis, scientists can discuss it precisely across studies.","zh":"如果病原體名為 Escovopsis，科學家就能在研究中精確討論它。"},{"en":"The phrase introduces the name of the organism.","zh":"這個片語引出生物的名稱。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":9},{"front":"a highly virulent pathogen","meaning":"毒性極強的病原體","examples":[{"en":"Escovopsis turns out to be a highly virulent pathogen.","zh":"Escovopsis 結果是毒性極強的病原體。"},{"en":"A highly virulent pathogen is a disease-causing organism that is extremely harmful and aggressive.","zh":"a highly virulent pathogen 指極其有害且攻擊性強的致病生物。"},{"en":"Doctors become concerned when a highly virulent pathogen spreads quickly in a hospital.","zh":"當毒性極強的病原體在醫院中快速傳播，醫生會非常擔心。"},{"en":"If a pathogen is highly virulent, it can damage its host rapidly.","zh":"如果病原體毒性極強，就能迅速損害宿主。"},{"en":"The phrase describes a very dangerous disease agent.","zh":"這個片語描述非常危險的致病因子。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":9},{"front":"devastate a fungus garden","meaning":"摧毀真菌園","examples":[{"en":"Escovopsis can devastate a fungus garden in a couple of days.","zh":"Escovopsis 可以在幾天內摧毀真菌園。"},{"en":"Devastate a fungus garden means damage or destroy the fungus garden severely.","zh":"devastate a fungus garden 指嚴重破壞或摧毀真菌園。"},{"en":"A flood can devastate a vegetable garden by washing away soil and plants.","zh":"水災可以沖走泥土和植物，摧毀菜園。"},{"en":"If a mould devastates the fungus garden, the ants may lose their food supply.","zh":"如果霉菌摧毀真菌園，螞蟻可能失去食物供應。"},{"en":"The phrase describes rapid and serious destruction.","zh":"這個片語描述快速而嚴重的破壞。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":9},{"front":"in a couple of days","meaning":"在幾天內","examples":[{"en":"The pathogen can devastate a fungus garden in a couple of days.","zh":"這種病原體可以在幾天內摧毀真菌園。"},{"en":"In a couple of days means within two or a few days.","zh":"in a couple of days 指在兩三天或幾天內。"},{"en":"A student can finish a short project in a couple of days if the plan is clear.","zh":"如果計劃清楚，學生可以在幾天內完成短項目。"},{"en":"If disease spreads in a couple of days, the damage can become serious very quickly.","zh":"如果疾病在幾天內擴散，損害可能很快變得嚴重。"},{"en":"The phrase suggests a short period of time.","zh":"這個片語暗示很短的時間。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":9},{"front":"bloom like a white cloud","meaning":"像白雲般大量生長","examples":[{"en":"The mould blooms like a white cloud over the garden.","zh":"霉菌像白雲般在菌園上大量生長。"},{"en":"Bloom like a white cloud means grow quickly and visibly into a white mass.","zh":"bloom like a white cloud 指快速而明顯地長成白色一團。"},{"en":"Mould on old bread may spread like a soft white patch.","zh":"舊麵包上的霉菌可能像柔軟白斑般擴散。"},{"en":"If mould blooms over a garden, it can cover the crop and block normal growth.","zh":"如果霉菌在菌園上大量生長，就能覆蓋作物並阻礙正常生長。"},{"en":"The phrase creates a visual image of rapid fungal spread.","zh":"這個片語形成真菌快速擴散的視覺畫面。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":9},{"front":"dimly visible underneath","meaning":"在下面隱約可見","examples":[{"en":"The fungus garden is dimly visible underneath the mould.","zh":"真菌園在霉菌下面隱約可見。"},{"en":"Dimly visible underneath means only faintly seen below another covering.","zh":"dimly visible underneath 指在另一層覆蓋物下只模糊看得見。"},{"en":"A road marking may be dimly visible underneath snow after a storm.","zh":"暴風雪後，道路標記可能在雪下面隱約可見。"},{"en":"If the garden is only dimly visible, the mould has covered most of it.","zh":"如果菌園只隱約可見，霉菌已覆蓋其大部分。"},{"en":"The phrase describes something partly hidden.","zh":"這個片語描述某物部分被遮住。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":9},{"front":"be enveloped","meaning":"被包圍；被覆蓋","examples":[{"en":"The whole garden is enveloped by the mould.","zh":"整個菌園被霉菌覆蓋。"},{"en":"Be enveloped means be completely covered or surrounded by something.","zh":"be enveloped 指被某物完全覆蓋或包圍。"},{"en":"The city was enveloped by fog in the early morning.","zh":"清晨時城市被霧包圍。"},{"en":"If a fungus garden is enveloped by mould, the crop beneath may be unable to survive.","zh":"如果真菌園被霉菌覆蓋，下面的作物可能無法生存。"},{"en":"The phrase suggests total covering.","zh":"這個片語暗示完全覆蓋。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":9},{"front":"ants associated with the garden","meaning":"與該菌園有關的螞蟻","examples":[{"en":"The ants associated with the garden may starve to death.","zh":"與該菌園有關的螞蟻可能餓死。"},{"en":"Ants associated with the garden are the ants connected with or dependent on that particular fungus garden.","zh":"ants associated with the garden 指與該特定真菌園有關或依賴它的螞蟻。"},{"en":"Students associated with a project are the ones who work on it or benefit from it.","zh":"與某項目有關的學生，就是參與或受益於該項目的學生。"},{"en":"If a fungus garden dies, the ants connected with it may lose their food source.","zh":"如果真菌園死亡，與它有關的螞蟻可能失去食物來源。"},{"en":"The phrase identifies the ants linked to a specific garden.","zh":"這個片語指出與特定菌園相連的螞蟻。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":9},{"front":"starve to death","meaning":"餓死","examples":[{"en":"The ants may starve to death when the garden is destroyed.","zh":"當菌園被摧毀時，螞蟻可能餓死。"},{"en":"Starve to death means die because there is not enough food.","zh":"starve to death 指因沒有足夠食物而死亡。"},{"en":"Animals can starve to death if drought removes their food sources for too long.","zh":"如果乾旱長時間消除動物食物來源，牠們可能餓死。"},{"en":"If ants depend completely on their fungus, losing it can lead to starvation.","zh":"如果螞蟻完全依賴真菌，失去真菌可能導致飢餓死亡。"},{"en":"The phrase describes death from hunger.","zh":"這個片語描述因飢餓而死亡。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":9},{"front":"seem to give up","meaning":"似乎放棄","examples":[{"en":"The ants just seem to give up when the garden is enveloped.","zh":"當菌園被覆蓋時，螞蟻似乎就放棄了。"},{"en":"Seem to give up means appear to stop trying or resisting.","zh":"seem to give up 指看起來停止努力或抵抗。"},{"en":"A student may seem to give up when a task feels impossible without help.","zh":"當任務在沒有幫助下顯得不可能時，學生可能似乎放棄。"},{"en":"If ants stop defending a garden covered by mould, the infection may already be beyond control.","zh":"如果螞蟻停止保衛被霉菌覆蓋的菌園，感染可能已失控。"},{"en":"The phrase describes appearance, not necessarily certain intention.","zh":"這個片語描述外在表現，而不一定是確定意圖。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":10},{"front":"rescue their larvae","meaning":"救出牠們的幼蟲","examples":[{"en":"Some ants survive because they have rescued their larvae.","zh":"有些螞蟻因救出牠們的幼蟲而存活。"},{"en":"Rescue their larvae means save their young immature ants from danger.","zh":"rescue their larvae 指把未成熟的幼蟻從危險中救出。"},{"en":"Parents rescue children from danger by moving them away from unsafe places.","zh":"父母透過把孩子帶離危險地方來救他們。"},{"en":"If ants rescue larvae before a garden collapses, the colony may survive and rebuild.","zh":"如果螞蟻在菌園崩潰前救出幼蟲，群落可能存活並重建。"},{"en":"The phrase focuses on protecting the next generation.","zh":"這個片語集中於保護下一代。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":10},{"front":"deadly mould","meaning":"致命霉菌","examples":[{"en":"The deadly mould then turns greenish-brown.","zh":"這種致命霉菌隨後變成綠褐色。"},{"en":"Deadly mould is mould that can kill or destroy living things that depend on what it attacks.","zh":"deadly mould 指能殺死或摧毀依賴其攻擊對象的生物的霉菌。"},{"en":"Farmers fear deadly mould when it spreads through stored grain.","zh":"當致命霉菌在儲存穀物中擴散，農民會擔心。"},{"en":"If deadly mould destroys a fungus garden, the ants may lose their food and die.","zh":"如果致命霉菌摧毀真菌園，螞蟻可能失去食物並死亡。"},{"en":"The phrase stresses the mould’s severe danger.","zh":"這個片語強調霉菌的嚴重危險。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":10},{"front":"turn greenish-brown","meaning":"變成綠褐色","examples":[{"en":"The mould turns greenish-brown as it forms spores.","zh":"霉菌形成孢子時變成綠褐色。"},{"en":"Turn greenish-brown means change colour to a mixture of green and brown.","zh":"turn greenish-brown 指顏色變成綠色和棕色混合。"},{"en":"Leaves may turn greenish-brown when they begin to rot.","zh":"葉子開始腐爛時可能變成綠褐色。"},{"en":"If mould changes colour, it may be entering a new stage of growth.","zh":"如果霉菌變色，可能正在進入新的生長階段。"},{"en":"The phrase describes a visible colour change.","zh":"這個片語描述可見的顏色變化。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":10},{"front":"spore-forming stage","meaning":"形成孢子的階段","examples":[{"en":"The mould enters its spore-forming stage.","zh":"霉菌進入形成孢子的階段。"},{"en":"A spore-forming stage is the period when a fungus produces spores for reproduction or spread.","zh":"spore-forming stage 指真菌產生孢子以繁殖或擴散的時期。"},{"en":"In biology class, students may learn that mushrooms release spores to reproduce.","zh":"在生物課中，學生可能學到蘑菇釋放孢子來繁殖。"},{"en":"If mould reaches a spore-forming stage, it may spread to new places more easily.","zh":"如果霉菌到達形成孢子的階段，可能更容易擴散到新地方。"},{"en":"The phrase describes a reproductive phase.","zh":"這個片語描述繁殖階段。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":10},{"front":"evidently","meaning":"顯然","examples":[{"en":"Evidently, the ants usually manage to keep Escovopsis under control.","zh":"顯然，螞蟻通常能設法控制住 Escovopsis。"},{"en":"Evidently means clearly or according to the evidence available.","zh":"evidently 指清楚地或根據現有證據而言。"},{"en":"Evidently, the class practised hard because everyone improved in the test.","zh":"顯然，全班努力練習了，因為每個人在測驗中都有進步。"},{"en":"If a disease rarely destroys gardens, the ants evidently have some control method.","zh":"如果疾病很少摧毀菌園，螞蟻顯然有某種控制方法。"},{"en":"The word introduces a conclusion based on visible evidence.","zh":"這個詞引出基於可見證據的結論。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":10},{"front":"manage to keep something under control","meaning":"設法控制住……","examples":[{"en":"The ants usually manage to keep Escovopsis under control.","zh":"螞蟻通常設法控制住 Escovopsis。"},{"en":"Manage to keep something under control means succeed in preventing it from becoming too serious.","zh":"manage to keep something under control 指成功防止某事變得太嚴重。"},{"en":"A teacher may manage to keep a noisy class under control with clear rules.","zh":"老師可能透過清晰規則設法控制住吵鬧班級。"},{"en":"If ants keep Escovopsis under control, the mould remains present but not disastrous.","zh":"如果螞蟻控制住 Escovopsis，霉菌仍可能存在，但不至於造成災難。"},{"en":"The phrase suggests successful control despite difficulty.","zh":"這個片語暗示儘管困難仍成功控制。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":10},{"front":"a lapse in control","meaning":"控制上的疏漏","examples":[{"en":"Escovopsis can burst forth after any lapse in control.","zh":"在任何控制上的疏漏後，Escovopsis 都可能突然大量出現。"},{"en":"A lapse in control is a temporary failure to control something properly.","zh":"a lapse in control 指暫時未能妥善控制某事。"},{"en":"A lapse in classroom control can lead to noise and confusion.","zh":"課室控制上的疏漏可能導致嘈吵和混亂。"},{"en":"If ants stop controlling mould even briefly, the pathogen may spread quickly.","zh":"如果螞蟻即使短暫停止控制霉菌，病原體也可能迅速擴散。"},{"en":"The phrase describes a short break in effective management.","zh":"這個片語描述有效管理中的短暫中斷。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":10},{"front":"be removed","meaning":"被移走","examples":[{"en":"If the ants are removed, Escovopsis will quickly burst forth.","zh":"如果螞蟻被移走，Escovopsis 會迅速大量出現。"},{"en":"Be removed means be taken away from a place or situation.","zh":"be removed 指被從某地方或情況中拿走。"},{"en":"If a teacher is removed from a noisy room, students may stop following the rules.","zh":"如果老師被帶離吵鬧課室，學生可能停止遵守規則。"},{"en":"If ants are removed from the garden, their disease-control work stops.","zh":"如果螞蟻被從菌園移走，牠們的疾病控制工作就停止。"},{"en":"The phrase describes taking something out of a system.","zh":"這個片語描述把某物從系統中移除。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":10},{"front":"burst forth","meaning":"突然大量出現","examples":[{"en":"Escovopsis will quickly burst forth if control breaks down.","zh":"如果控制崩潰，Escovopsis 會迅速突然大量出現。"},{"en":"Burst forth means suddenly appear, grow, or spread strongly.","zh":"burst forth 指突然強烈地出現、生長或擴散。"},{"en":"Weeds may burst forth after heavy rain if no one clears the garden.","zh":"大雨後，如果沒有人清理花園，雜草可能突然大量出現。"},{"en":"If a pathogen bursts forth, damage can happen faster than expected.","zh":"如果病原體突然大量出現，損害可能比預期更快發生。"},{"en":"The phrase suggests sudden uncontrolled growth.","zh":"這個片語暗示突然失控地生長。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":10},{"front":"start off free of","meaning":"起初沒有……","examples":[{"en":"New leaf-cutter gardens start off free of Escovopsis.","zh":"新的切葉蟻菌園起初沒有 Escovopsis。"},{"en":"Start off free of means begin without something harmful or unwanted.","zh":"start off free of 指開始時沒有某種有害或不想要的東西。"},{"en":"A new computer may start off free of viruses if it is carefully protected.","zh":"如果新電腦被仔細保護，起初可能沒有病毒。"},{"en":"If a garden starts free of disease, infection must arrive later from another source.","zh":"如果菌園起初沒有疾病，感染必定後來從其他來源進入。"},{"en":"The phrase describes the initial clean condition.","zh":"這個片語描述最初的乾淨狀態。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":11},{"front":"within two years","meaning":"在兩年內","examples":[{"en":"Within two years, some leaf-cutter gardens become infected.","zh":"在兩年內，一些切葉蟻菌園受到感染。"},{"en":"Within two years means before two years have passed.","zh":"within two years 指在兩年過去之前。"},{"en":"A student may become fluent within two years if they practise speaking every day.","zh":"如果學生每天練習口語，可能在兩年內變得流利。"},{"en":"If infection appears within two years, the disease spreads over a relatively short period.","zh":"如果感染在兩年內出現，疾病就在相對短時間內擴散。"},{"en":"The phrase sets a time limit.","zh":"這個片語設定時間限制。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":11},{"front":"some 60 percent","meaning":"約百分之六十","examples":[{"en":"Some 60 percent of the gardens become infected within two years.","zh":"約百分之六十的菌園在兩年內受到感染。"},{"en":"Some 60 percent means about 60 percent, not necessarily exactly.","zh":"some 60 percent 指約百分之六十，不一定完全精確。"},{"en":"Some 60 percent of students may choose online revision if it is convenient.","zh":"如果網上溫習方便，約百分之六十的學生可能選擇它。"},{"en":"If around 60 percent become infected, the problem is common rather than rare.","zh":"如果約六成受到感染，問題就是常見而不是罕見。"},{"en":"The phrase gives an approximate percentage.","zh":"這個片語給出大約百分比。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":11},{"front":"become infected","meaning":"受到感染","examples":[{"en":"Many leaf-cutter gardens become infected within two years.","zh":"許多切葉蟻菌園在兩年內受到感染。"},{"en":"Become infected means begin to contain disease-causing organisms.","zh":"become infected 指開始含有致病生物。"},{"en":"A small cut can become infected if it is not cleaned properly.","zh":"小傷口如果沒有正確清潔，可能受到感染。"},{"en":"If a fungus garden becomes infected, the ants must act quickly to protect their crop.","zh":"如果真菌園受到感染，螞蟻必須迅速行動保護作物。"},{"en":"The phrase marks the start of disease presence.","zh":"這個片語標示疾病開始存在。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":11},{"front":"bring a new level of understanding to","meaning":"為……帶來新的理解層次","examples":[{"en":"The discovery brings a new level of understanding to ant evolution.","zh":"這項發現為螞蟻演化帶來新的理解層次。"},{"en":"Bring a new level of understanding to means make people understand a topic more deeply than before.","zh":"bring a new level of understanding to 指令人們比以前更深入理解某主題。"},{"en":"A patient’s diary can bring a new level of understanding to a doctor’s diagnosis.","zh":"病人日記可以為醫生診斷帶來新的理解層次。"},{"en":"If a discovery reveals hidden parasites, it can change how scientists explain evolution.","zh":"如果發現揭示隱藏寄生物，它可以改變科學家如何解釋演化。"},{"en":"The phrase describes deeper insight.","zh":"這個片語描述更深入的洞見。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":11},{"front":"evolutionary biologists","meaning":"演化生物學家","examples":[{"en":"Evolutionary biologists study the role of parasites in evolution.","zh":"演化生物學家研究寄生物在演化中的角色。"},{"en":"Evolutionary biologists are scientists who study how living things change over generations.","zh":"evolutionary biologists 指研究生物如何跨世代改變的科學家。"},{"en":"Evolutionary biologists may compare fossils, genes, and behaviour to understand species history.","zh":"演化生物學家可能比較化石、基因和行為，以理解物種歷史。"},{"en":"If parasites shape survival, evolutionary biologists must include them in their explanations.","zh":"如果寄生物塑造生存，演化生物學家就必須把它們納入解釋。"},{"en":"The phrase names a scientific profession.","zh":"這個片語指一種科學職業。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":11},{"front":"increasingly aware of","meaning":"越來越意識到","examples":[{"en":"Evolutionary biologists have become increasingly aware of parasites.","zh":"演化生物學家越來越意識到寄生物的重要性。"},{"en":"Increasingly aware of means gradually more conscious or knowledgeable about something.","zh":"increasingly aware of 指對某事逐漸更有意識或更了解。"},{"en":"Students become increasingly aware of grammar mistakes when teachers explain patterns clearly.","zh":"當老師清楚解釋模式，學生會越來越意識到文法錯誤。"},{"en":"If scientists become increasingly aware of a factor, research questions may change.","zh":"如果科學家越來越意識到某因素，研究問題可能改變。"},{"en":"The phrase shows growing understanding over time.","zh":"這個片語顯示理解隨時間增長。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":11},{"front":"driving forces in evolution","meaning":"演化的推動力","examples":[{"en":"Parasites can act as driving forces in evolution.","zh":"寄生物可以作為演化的推動力。"},{"en":"Driving forces in evolution are factors that strongly push species to change over time.","zh":"driving forces in evolution 指強烈推動物種隨時間改變的因素。"},{"en":"Climate change can be a driving force when animals must adapt or die.","zh":"當動物必須適應或死亡時，氣候變化可以成為推動力。"},{"en":"If parasites pressure hosts constantly, they may drive new defences and behaviours.","zh":"如果寄生物持續對宿主施壓，可能推動新的防禦和行為。"},{"en":"The phrase describes powerful causes of evolutionary change.","zh":"這個片語描述演化改變的強大原因。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":11},{"front":"a possible reason to explain why","meaning":"可用來解釋為何……的可能原因","examples":[{"en":"There is now a possible reason to explain why the lower attines change fungi.","zh":"現在有一個可用來解釋為何較低等 Attini 蟻更換真菌的可能原因。"},{"en":"A possible reason to explain why means a likely explanation for something, though not necessarily the only one.","zh":"a possible reason to explain why 指某事的可能解釋，但不一定是唯一原因。"},{"en":"Lack of sleep is a possible reason to explain why a student’s marks suddenly fall.","zh":"睡眠不足可能是用來解釋學生分數突然下降的原因。"},{"en":"If new evidence appears, it may provide a possible reason for behaviour that once seemed strange.","zh":"如果新證據出現，它可能提供某種曾經奇怪行為的可能原因。"},{"en":"The phrase introduces a cautious explanation.","zh":"這個片語引出謹慎解釋。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":11},{"front":"keep changing the variety of","meaning":"不斷更換……的品種","examples":[{"en":"The lower attines keep changing the variety of fungus in their gardens.","zh":"較低等 Attini 蟻不斷更換菌園中的真菌品種。"},{"en":"Keep changing the variety of means repeatedly replace one type with another.","zh":"keep changing the variety of 指反覆以一種類型取代另一種類型。"},{"en":"A café may keep changing the variety of cakes to attract regular customers.","zh":"咖啡店可能不斷更換蛋糕品種，以吸引常客。"},{"en":"If ants keep changing fungus varieties, parasites may have a harder time adapting.","zh":"如果螞蟻不斷更換真菌品種，寄生物可能較難適應。"},{"en":"The phrase suggests repeated adjustment.","zh":"這個片語暗示反覆調整。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":11},{"front":"domesticating new ones","meaning":"馴化新的品種","examples":[{"en":"The ants occasionally protect themselves by domesticating new fungi.","zh":"螞蟻偶爾透過馴化新的真菌來保護自己。"},{"en":"Domesticating new ones means adapting new varieties or species for regular use and cultivation.","zh":"domesticating new ones 指把新品種或新物種改造成可定期使用和培植的對象。"},{"en":"Farmers may try domesticating new crop varieties when old ones fail in dry weather.","zh":"當舊作物在乾燥天氣中失敗時，農民可能嘗試馴化新品種。"},{"en":"If ants domesticate new fungi, they may escape parasites that specialise in older strains.","zh":"如果螞蟻馴化新真菌，可能逃過專門攻擊舊菌株的寄生物。"},{"en":"The phrase describes creating a new managed resource.","zh":"這個片語描述創造新的受管理資源。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":12},{"front":"stay one step ahead of","meaning":"領先……一步","examples":[{"en":"The ants change fungi to stay one step ahead of Escovopsis.","zh":"螞蟻更換真菌，以領先 Escovopsis 一步。"},{"en":"Stay one step ahead of means remain slightly ahead of a threat or competitor.","zh":"stay one step ahead of 指比威脅或競爭者稍微領先。"},{"en":"Students can stay one step ahead of deadlines by starting assignments early.","zh":"學生可以透過早開始功課來領先截止日期一步。"},{"en":"If parasites adapt quickly, hosts must change strategies to stay ahead.","zh":"如果寄生物快速適應，宿主就必須改變策略以保持領先。"},{"en":"The phrase suggests active prevention before problems catch up.","zh":"這個片語暗示問題追上前的主動預防。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":12},{"front":"relentless Escovopsis","meaning":"持續不斷的 Escovopsis","examples":[{"en":"The ants must stay one step ahead of the relentless Escovopsis.","zh":"螞蟻必須領先持續不斷的 Escovopsis 一步。"},{"en":"Relentless Escovopsis means Escovopsis that keeps attacking or returning without stopping.","zh":"relentless Escovopsis 指不停攻擊或反覆回來的 Escovopsis。"},{"en":"Relentless exam pressure can exhaust students if they never rest.","zh":"如果學生從不休息，持續不斷的考試壓力可以令他們筋疲力盡。"},{"en":"If a pathogen is relentless, occasional control may not be enough.","zh":"如果病原體持續不斷，偶爾控制可能不足夠。"},{"en":"The phrase stresses persistence and danger.","zh":"這個片語強調持續性和危險。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":12},{"front":"in general","meaning":"一般來說","examples":[{"en":"In general, leaf-cutters have fewer alien moulds in their gardens.","zh":"一般來說，切葉蟻菌園中的外來霉菌較少。"},{"en":"In general means usually or when speaking about the overall pattern.","zh":"in general 指通常而言，或談整體模式時。"},{"en":"In general, students learn better when examples are clear and concrete.","zh":"一般來說，當例子清晰具體時，學生學得更好。"},{"en":"If a statement begins with “in general”, exceptions may still exist.","zh":"如果陳述以 in general 開始，仍可能有例外。"},{"en":"The phrase introduces a broad trend.","zh":"這個片語引出廣泛趨勢。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":12},{"front":"alien moulds","meaning":"外來霉菌","examples":[{"en":"Leaf-cutters have fewer alien moulds than lower attines.","zh":"切葉蟻的外來霉菌比低等 Attini 蟻少。"},{"en":"Alien moulds are moulds that do not belong in a particular fungus garden.","zh":"alien moulds 指不屬於某特定真菌園的霉菌。"},{"en":"A food factory must prevent alien moulds from growing on stored ingredients.","zh":"食品工廠必須防止外來霉菌在儲存食材上生長。"},{"en":"If alien moulds enter a garden, they may compete with or infect the cultivated fungus.","zh":"如果外來霉菌進入菌園，可能與培植真菌競爭或感染它。"},{"en":"The phrase describes unwanted fungal outsiders.","zh":"這個片語描述不受歡迎的真菌外來者。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":12},{"front":"Escovopsis infections","meaning":"Escovopsis 感染","examples":[{"en":"Leaf-cutters have more Escovopsis infections than lower attines.","zh":"切葉蟻的 Escovopsis 感染比低等 Attini 蟻更多。"},{"en":"Escovopsis infections are cases where the fungus garden is infected by Escovopsis mould.","zh":"Escovopsis infections 指真菌園受到 Escovopsis 霉菌感染的個案。"},{"en":"Doctors count infections to understand how often a disease appears in a community.","zh":"醫生統計感染個案，以了解疾病在社區出現的頻率。"},{"en":"If leaf-cutters have more Escovopsis infections, their pure fungus crop may carry a special risk.","zh":"如果切葉蟻有更多 Escovopsis 感染，其純種真菌作物可能帶有特殊風險。"},{"en":"The phrase refers to disease events caused by Escovopsis.","zh":"這個片語指由 Escovopsis 造成的疾病事件。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":12},{"front":"the price they pay for","meaning":"……所付出的代價","examples":[{"en":"A higher risk of Escovopsis is the price they pay for cultivating one fungus variety.","zh":"Escovopsis 的較高風險是牠們培植單一真菌品種所付出的代價。"},{"en":"The price they pay for means the negative cost or disadvantage that comes with a benefit.","zh":"the price they pay for 指伴隨好處而來的負面成本或缺點。"},{"en":"Less sleep may be the price students pay for leaving homework until midnight.","zh":"睡眠減少可能是學生把功課留到午夜才做所付出的代價。"},{"en":"If ants gain efficient farming but face disease risk, that risk is the price of specialisation.","zh":"如果螞蟻獲得高效農耕但面對疾病風險，該風險就是專門化的代價。"},{"en":"The phrase highlights a trade-off.","zh":"這個片語突出取捨。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":12},{"front":"cultivating a pure variety","meaning":"培植純種品種","examples":[{"en":"The ants face higher risks when cultivating a pure variety of fungus.","zh":"螞蟻在培植純種真菌品種時面對較高風險。"},{"en":"Cultivating a pure variety means growing one genetically uniform type.","zh":"cultivating a pure variety 指種植一種基因一致的類型。"},{"en":"Farmers cultivating a pure variety of crop may get consistent harvests but higher disease risk.","zh":"農民培植純種作物品種時，可能得到穩定收成，但疾病風險較高。"},{"en":"If ants cultivate a pure fungus variety, parasites may adapt to it more easily.","zh":"如果螞蟻培植純種真菌，寄生物可能更容易適應它。"},{"en":"The phrase connects uniform cultivation with both efficiency and vulnerability.","zh":"這個片語把一致栽培與效率和脆弱性連接起來。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":12},{"front":"a higher risk from","meaning":"來自……的較高風險","examples":[{"en":"Leaf-cutters face a higher risk from Escovopsis.","zh":"切葉蟻面對來自 Escovopsis 的較高風險。"},{"en":"A higher risk from something means a greater chance of being harmed by it.","zh":"a higher risk from 指受到某物傷害的機會較高。"},{"en":"Elderly people may face a higher risk from heatwaves during summer.","zh":"長者在夏天可能面對來自熱浪的較高風險。"},{"en":"If one fungus strain is grown everywhere, ants may face a higher risk from specialised parasites.","zh":"如果到處都種同一菌株，螞蟻可能面對來自專門寄生物的較高風險。"},{"en":"The phrase compares levels of danger.","zh":"這個片語比較危險程度。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":12},{"front":"have little alternative","meaning":"幾乎沒有其他選擇","examples":[{"en":"The leaf-cutters may have little alternative.","zh":"切葉蟻可能幾乎沒有其他選擇。"},{"en":"Have little alternative means have few other realistic choices.","zh":"have little alternative 指幾乎沒有其他現實可行的選擇。"},{"en":"If buses stop running, students may have little alternative but to walk home.","zh":"如果巴士停駛，學生可能幾乎沒有其他選擇，只能步行回家。"},{"en":"If leaf-cutters need a special fungus, they may not be able to switch crops easily.","zh":"如果切葉蟻需要特殊真菌，牠們可能不能輕易轉換作物。"},{"en":"The phrase suggests limited options.","zh":"這個片語暗示選項有限。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":12},{"front":"a special variety of fungus","meaning":"特別品種的真菌","examples":[{"en":"The leaf-cutters cultivate a special variety of fungus.","zh":"切葉蟻培植一種特別品種的真菌。"},{"en":"A special variety of fungus is a particular type of fungus with unusual or useful features.","zh":"a special variety of fungus 指具有不尋常或有用特徵的特定真菌類型。"},{"en":"A farmer may choose a special variety of rice that grows well in wet fields.","zh":"農民可能選擇在濕田中生長良好的特別米種。"},{"en":"If the fungus produces food structures for ants, it is especially useful to them.","zh":"如果真菌為螞蟻產生可食用結構，它對牠們就特別有用。"},{"en":"The phrase points to a specific useful type.","zh":"這個片語指出特定而有用的類型。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":13},{"front":"unlike those grown by","meaning":"不同於……所培植的","examples":[{"en":"The fungus produces tips unlike those grown by the lower attines.","zh":"這種真菌產生的端部不同於較低等 Attini 蟻所培植的真菌。"},{"en":"Unlike those grown by means different from the ones cultivated by another group.","zh":"unlike those grown by 指不同於另一群體所培植的那些。"},{"en":"The tomatoes grown in the greenhouse are unlike those grown outdoors because they are sweeter.","zh":"溫室中種植的番茄不同於戶外種植的，因為它們更甜。"},{"en":"If leaf-cutters grow a different fungus, its benefits and risks may also differ.","zh":"如果切葉蟻培植不同真菌，其好處和風險也可能不同。"},{"en":"The phrase creates a clear comparison.","zh":"這個片語形成清晰比較。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":13},{"front":"nutritious swollen tips","meaning":"有營養的膨大端部","examples":[{"en":"The special fungus produces nutritious swollen tips for the ants to eat.","zh":"這種特殊真菌為螞蟻產生有營養的膨大端部。"},{"en":"Nutritious swollen tips are enlarged fungus parts rich in food value.","zh":"nutritious swollen tips 指富有食物價值的膨大真菌部分。"},{"en":"Some plants grow swollen roots that store nutrients, such as carrots and sweet potatoes.","zh":"有些植物長出儲存養分的膨大根部，例如紅蘿蔔和番薯。"},{"en":"If fungus produces nutritious tips, ants may depend strongly on that particular fungus.","zh":"如果真菌產生有營養的端部，螞蟻可能強烈依賴該特定真菌。"},{"en":"The phrase describes a food structure produced by the fungus.","zh":"這個片語描述真菌產生的食物結構。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":13},{"front":"a third partner","meaning":"第三個伙伴","examples":[{"en":"The discovery of a third partner changes our view of the ant-fungus symbiosis.","zh":"第三個伙伴的發現改變了我們對螞蟻與真菌共生關係的看法。"},{"en":"A third partner means an additional participant in a relationship that was thought to involve only two sides.","zh":"a third partner 指在原本被認為只涉及兩方的關係中加入的另一參與者。"},{"en":"A school and parents may rely on a third partner, such as a community centre, to support students.","zh":"學校和家長可能依賴第三個伙伴，例如社區中心，來支援學生。"},{"en":"If bacteria are a third partner, the ant-fungus relationship is more complex than expected.","zh":"如果細菌是第三個伙伴，螞蟻與真菌關係就比預期更複雜。"},{"en":"The phrase adds another member to a system.","zh":"這個片語為系統加入另一成員。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":13},{"front":"ant-fungus symbiosis","meaning":"螞蟻與真菌的共生關係","examples":[{"en":"The bacterium is part of the ant-fungus symbiosis.","zh":"這種細菌是螞蟻與真菌共生關係的一部分。"},{"en":"Ant-fungus symbiosis is the mutually dependent relationship between ants and the fungus they cultivate.","zh":"ant-fungus symbiosis 指螞蟻與其培植真菌之間相互依賴的關係。"},{"en":"Teachers may use ant-fungus symbiosis to explain how two species can help each other.","zh":"老師可能用螞蟻與真菌的共生關係來解釋兩個物種如何互相幫助。"},{"en":"If bacteria are involved, the symbiosis may include disease control as well as food production.","zh":"如果細菌也參與其中，這種共生可能包括疾病控制以及食物生產。"},{"en":"The phrase describes a biological partnership.","zh":"這個片語描述生物伙伴關係。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":13},{"front":"raise the question of how","meaning":"引出……如何做到的問題","examples":[{"en":"The discovery raises the question of how ants control Escovopsis.","zh":"這項發現引出螞蟻如何控制 Escovopsis 的問題。"},{"en":"Raise the question of how means make people ask by what method something happens.","zh":"raise the question of how 指令人們問某事是透過甚麼方法發生。"},{"en":"A sudden rise in exam scores raises the question of how students changed their study habits.","zh":"考試成績突然上升會引出學生如何改變學習習慣的問題。"},{"en":"If ants keep a dangerous mould under control, scientists naturally ask how they do it.","zh":"如果螞蟻能控制危險霉菌，科學家自然會問牠們如何做到。"},{"en":"The phrase introduces a new problem for investigation.","zh":"這個片語引出新的調查問題。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":13},{"front":"dangerous interloper","meaning":"危險的入侵者","examples":[{"en":"Escovopsis is a dangerous interloper in the fungus garden.","zh":"Escovopsis 是真菌園中的危險入侵者。"},{"en":"A dangerous interloper is an unwanted outsider that can cause harm.","zh":"dangerous interloper 指能造成傷害的不受歡迎外來者。"},{"en":"A hacker can be a dangerous interloper in a school computer system.","zh":"黑客可以是學校電腦系統中的危險入侵者。"},{"en":"If a dangerous interloper enters a protected system, it may damage what people or animals depend on.","zh":"如果危險入侵者進入受保護系統，可能損害人或動物依賴的東西。"},{"en":"The phrase suggests both intrusion and threat.","zh":"這個片語同時暗示入侵和威脅。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":13},{"front":"amazingly enough","meaning":"令人驚訝的是","examples":[{"en":"Amazingly enough, Mr Currie provided the answer.","zh":"令人驚訝的是，Currie 先生提供了答案。"},{"en":"Amazingly enough means surprisingly or in a way that causes wonder.","zh":"amazingly enough 指令人驚訝地，或以令人讚嘆的方式。"},{"en":"Amazingly enough, the lost homework was found inside the student’s music folder.","zh":"令人驚訝的是，遺失的功課在學生的音樂文件夾中找到。"},{"en":"If an answer comes from a small observation, the discovery may feel amazing.","zh":"如果答案來自一項小觀察，該發現可能令人驚訝。"},{"en":"The phrase signals surprise before giving information.","zh":"這個片語在提供資訊前表示驚訝。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":13},{"front":"refer to","meaning":"指的是","examples":[{"en":"Dr Mueller was referring to the insects’ body surface.","zh":"Mueller 博士指的是昆蟲的身體表面。"},{"en":"Refer to means mean, mention, or point to something specific.","zh":"refer to 指表示、提及或指向某個特定事物。"},{"en":"When a teacher says “this rule”, they may refer to the grammar rule on the board.","zh":"當老師說 “this rule” 時，可能指黑板上的文法規則。"},{"en":"If a word refers to a body part, students should identify the exact part in context.","zh":"如果某詞指身體部位，學生應根據語境識別確切部位。"},{"en":"The phrase connects language with its intended meaning.","zh":"這個片語把語言與其 intended 意思連接起來。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":13},{"front":"body surface","meaning":"身體表面","examples":[{"en":"The cuticle is the insects’ body surface.","zh":"表皮是昆蟲的身體表面。"},{"en":"Body surface means the outside layer or outer part of a body.","zh":"body surface 指身體的外層或外部部分。"},{"en":"Doctors check the body surface for rashes, cuts, or swelling.","zh":"醫生檢查身體表面是否有皮疹、傷口或腫脹。"},{"en":"If bacteria live on an ant’s body surface, they may be carried wherever the ant goes.","zh":"如果細菌生活在螞蟻身體表面，就可能被螞蟻帶到各處。"},{"en":"The phrase refers to the outside of the body.","zh":"這個片語指身體外部。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":13},{"front":"cuticle","meaning":"表皮；角質層","examples":[{"en":"Scientists found bacteria on the ants’ cuticle.","zh":"科學家在螞蟻的表皮上發現細菌。"},{"en":"A cuticle is the outer protective layer of an insect’s body.","zh":"cuticle 指昆蟲身體外部的保護層。"},{"en":"Insects’ cuticle can help prevent water loss and physical damage.","zh":"昆蟲表皮可以幫助防止水分流失和身體損傷。"},{"en":"If useful bacteria live on the cuticle, the insect’s body surface becomes part of its defence system.","zh":"如果有用細菌生活在表皮上，昆蟲身體表面就成為防禦系統的一部分。"},{"en":"The word is technical and common in insect biology.","zh":"這個詞屬技術用語，常見於昆蟲生物學。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":14},{"front":"cuticular wax","meaning":"表皮蠟質","examples":[{"en":"People once thought the whitish growth was cuticular wax.","zh":"人們曾以為這種白色生長物是表皮蠟質。"},{"en":"Cuticular wax is a waxy substance on the outer surface of some insects or plants.","zh":"cuticular wax 指某些昆蟲或植物外表面的蠟質物質。"},{"en":"Plant leaves may have cuticular wax that helps reduce water loss.","zh":"植物葉子可能有表皮蠟質，有助減少水分流失。"},{"en":"If a whitish surface is mistaken for wax, scientists may miss living bacteria beneath the appearance.","zh":"如果白色表面被誤認為蠟質，科學家可能會錯過外觀下的活細菌。"},{"en":"The phrase refers to a protective surface coating.","zh":"這個片語指保護性的表面塗層。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":14},{"front":"put something under a microscope","meaning":"把……放在顯微鏡下觀察","examples":[{"en":"Mr Currie put the growth under a microscope.","zh":"Currie 先生把這種生長物放在顯微鏡下觀察。"},{"en":"Put something under a microscope means examine it closely using a microscope.","zh":"put something under a microscope 指用顯微鏡仔細檢查某物。"},{"en":"Students put onion skin under a microscope to see plant cells.","zh":"學生把洋蔥皮放在顯微鏡下觀察，以看見植物細胞。"},{"en":"If scientists put a strange growth under a microscope, they may discover what it really is.","zh":"如果科學家把奇怪生長物放在顯微鏡下觀察，可能發現它真正是甚麼。"},{"en":"The phrase means careful scientific inspection.","zh":"這個片語指仔細的科學檢查。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":14},{"front":"inert wax","meaning":"惰性蠟質","examples":[{"en":"The growth was not inert wax.","zh":"這種生長物不是惰性蠟質。"},{"en":"Inert wax is wax that is not alive and does not react biologically.","zh":"inert wax 指沒有生命且不作出生物反應的蠟質。"},{"en":"A plastic coating may look like a living growth but be inert material.","zh":"塑膠塗層可能看起來像活的生長物，但其實是惰性材料。"},{"en":"If the growth is not inert wax but living bacteria, it may have an active role.","zh":"如果該生長物不是惰性蠟質，而是活細菌，它可能有主動作用。"},{"en":"The phrase contrasts lifeless coating with living organisms.","zh":"這個片語把無生命塗層與活生物作對比。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":14},{"front":"be alive","meaning":"是活的","examples":[{"en":"Mr Currie discovered that the whitish growth was alive.","zh":"Currie 先生發現這種白色生長物是活的。"},{"en":"Be alive means be living, growing, or biologically active.","zh":"be alive 指有生命、正在生長或有生物活性。"},{"en":"Seeds may look dry, but some are still alive and can grow when watered.","zh":"種子可能看起來乾燥，但有些仍是活的，澆水後可以生長。"},{"en":"If a white coating is alive, it may reproduce, spread, or produce chemicals.","zh":"如果白色塗層是活的，它可能繁殖、擴散或產生化學物。"},{"en":"The phrase distinguishes living matter from dead or inert material.","zh":"這個片語區分活物與死亡或惰性材料。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":14},{"front":"a specialised patch","meaning":"特化區域","examples":[{"en":"The ants have a specialised patch on their cuticle.","zh":"螞蟻在表皮上有一個特化區域。"},{"en":"A specialised patch is a particular area adapted for a special function.","zh":"a specialised patch 指適應某種特殊功能的特定區域。"},{"en":"A smartphone may have a special sensor area used only for fingerprint scanning.","zh":"智能手機可能有一個專門用於指紋掃描的感應區。"},{"en":"If ants have a patch for bacteria, that area may help maintain the helpful microbes.","zh":"如果螞蟻有一個用來容納細菌的區域，該區可能幫助維持有益微生物。"},{"en":"The phrase describes a small body area with a specific role.","zh":"這個片語描述具有特定作用的小型身體區域。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":14},{"front":"harbour a bacterium","meaning":"藏有；容納一種細菌","examples":[{"en":"The specialised patch harbours a particular kind of bacterium.","zh":"這個特化區域容納一種特定細菌。"},{"en":"Harbour a bacterium means contain, shelter, or provide a place for a bacterium to live.","zh":"harbour a bacterium 指包含、庇護或提供地方讓細菌生活。"},{"en":"A dirty sponge can harbour bacteria if it stays wet for too long.","zh":"如果髒海綿長時間潮濕，就可能藏有細菌。"},{"en":"If an ant harbours useful bacteria, its body can carry natural protection.","zh":"如果螞蟻容納有益細菌，其身體就能攜帶天然保護。"},{"en":"The phrase describes hosting bacteria.","zh":"這個片語描述宿主容納細菌。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":14},{"front":"a particular kind of bacterium","meaning":"某一種特定細菌","examples":[{"en":"The ants carry a particular kind of bacterium on their cuticle.","zh":"螞蟻在表皮上攜帶某一種特定細菌。"},{"en":"A particular kind of bacterium means one specific type of bacterium.","zh":"a particular kind of bacterium 指某一種具體的細菌。"},{"en":"Doctors may identify a particular kind of bacterium before choosing an antibiotic.","zh":"醫生可能先識別某一種特定細菌，然後選擇抗生素。"},{"en":"If one bacterium kills Escovopsis, scientists need to know exactly which kind it is.","zh":"如果一種細菌能殺死 Escovopsis，科學家需要知道它確切是哪一種。"},{"en":"The phrase emphasises specificity.","zh":"這個片語強調特定性。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":14},{"front":"be well known to","meaning":"為……所熟知","examples":[{"en":"The bacterium is well known to the pharmaceutical industry.","zh":"這種細菌為製藥業所熟知。"},{"en":"Be well known to means be familiar to a particular group of people.","zh":"be well known to 指為某特定群體所熟悉。"},{"en":"This software is well known to teachers who prepare online lessons.","zh":"這款軟件為準備網上課堂的老師所熟知。"},{"en":"If a bacterium is well known to drug companies, it may have medical importance.","zh":"如果某種細菌為藥廠所熟知，它可能有醫學重要性。"},{"en":"The phrase identifies who recognises something.","zh":"這個片語指出誰認識某事物。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":14},{"front":"the source of antibiotics","meaning":"抗生素的來源","examples":[{"en":"The bacterium is the source of many antibiotics used in medicine.","zh":"這種細菌是醫學上使用的許多抗生素的來源。"},{"en":"The source of antibiotics means the origin from which antibiotic substances are obtained.","zh":"the source of antibiotics 指抗生素物質取得的來源。"},{"en":"Some medicines come from natural sources such as plants, fungi, or bacteria.","zh":"有些藥物來自植物、真菌或細菌等天然來源。"},{"en":"If a bacterium produces antibiotics, it can help kill or slow harmful microbes.","zh":"如果細菌產生抗生素，就能幫助殺死或減慢有害微生物。"},{"en":"The phrase connects a living organism with medicine.","zh":"這個片語把生物與醫學連接起來。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":14},{"front":"antibiotics used in medicine","meaning":"醫學上使用的抗生素","examples":[{"en":"Streptomyces is the source of many antibiotics used in medicine.","zh":"鏈黴菌是醫學上使用的許多抗生素的來源。"},{"en":"Antibiotics used in medicine are drugs that treat bacterial infections in people or animals.","zh":"antibiotics used in medicine 指用於治療人或動物細菌感染的藥物。"},{"en":"Doctors prescribe antibiotics for some bacterial infections, but not for ordinary viral colds.","zh":"醫生會為某些細菌感染處方抗生素，但不會為普通病毒性感冒處方。"},{"en":"If antibiotics are overused, bacteria may become resistant to them.","zh":"如果抗生素被過度使用，細菌可能對它們產生耐藥性。"},{"en":"The phrase refers to medically useful antibacterial drugs.","zh":"這個片語指醫學上有用的抗菌藥物。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":15},{"front":"isolate a species of","meaning":"分離出一種……","examples":[{"en":"The researchers isolated a species of Streptomyces bacterium.","zh":"研究人員分離出一種鏈黴菌。"},{"en":"Isolate a species of means separate one species from a mixed sample so it can be studied.","zh":"isolate a species of 指從混合樣本中分離出一個物種，以便研究。"},{"en":"A lab may isolate a species of bacteria from soil to test its effects.","zh":"實驗室可能從泥土中分離出一種細菌，以測試其作用。"},{"en":"If scientists isolate one species, they can identify its role more clearly.","zh":"如果科學家分離出一個物種，就能更清楚識別其角色。"},{"en":"The phrase describes a key step in biological research.","zh":"這個片語描述生物研究中的關鍵步驟。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":15},{"front":"Streptomyces bacterium","meaning":"鏈黴菌","examples":[{"en":"The ants carry a Streptomyces bacterium on their cuticle.","zh":"螞蟻在表皮上攜帶鏈黴菌。"},{"en":"Streptomyces bacterium is a type of bacterium famous for producing antibiotic substances.","zh":"Streptomyces bacterium 指一類以產生抗生素物質聞名的細菌。"},{"en":"Scientists often study Streptomyces bacteria because they can make medically useful chemicals.","zh":"科學家常研究鏈黴菌，因為它們能製造醫學上有用的化學物。"},{"en":"If ants carry Streptomyces, they may be using natural antibiotics to protect their fungus.","zh":"如果螞蟻攜帶鏈黴菌，牠們可能正在使用天然抗生素保護真菌。"},{"en":"The phrase names the helpful bacterium in the passage.","zh":"這個片語指文章中的有益細菌。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":15},{"front":"ordinary laboratory fungi","meaning":"普通實驗室真菌","examples":[{"en":"Streptomyces does not have much effect on ordinary laboratory fungi.","zh":"鏈黴菌對普通實驗室真菌沒有太大影響。"},{"en":"Ordinary laboratory fungi are common fungi grown or tested in laboratory conditions.","zh":"ordinary laboratory fungi 指在實驗室條件中培養或測試的常見真菌。"},{"en":"Students may grow ordinary laboratory fungi on agar plates during a biology lesson.","zh":"學生可能在生物課中於瓊脂培養皿培養普通實驗室真菌。"},{"en":"If a bacterium affects Escovopsis but not ordinary laboratory fungi, its action may be specific.","zh":"如果一種細菌影響 Escovopsis 但不影響普通實驗室真菌，其作用可能有特異性。"},{"en":"The phrase contrasts general test fungi with the target pathogen.","zh":"這個片語把一般測試真菌與目標病原體作對比。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":15},{"front":"a potent poisoner of","meaning":"對……有強大毒殺作用的物質","examples":[{"en":"Streptomyces is a potent poisoner of Escovopsis.","zh":"鏈黴菌對 Escovopsis 有強大毒殺作用。"},{"en":"A potent poisoner of something is something that strongly kills or harms that target.","zh":"a potent poisoner of 指能強力殺死或傷害某目標的東西。"},{"en":"A strong disinfectant can be a potent killer of bacteria on hospital surfaces.","zh":"強力消毒劑可以強烈殺死醫院表面的細菌。"},{"en":"If Streptomyces poisons Escovopsis powerfully, it can help protect the ants’ garden.","zh":"如果鏈黴菌能強力毒殺 Escovopsis，就能幫助保護螞蟻菌園。"},{"en":"The phrase stresses strong harmful action against a specific organism.","zh":"這個片語強調對特定生物的強烈傷害作用。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":15},{"front":"inhibit its growth","meaning":"抑制其生長","examples":[{"en":"The bacterium inhibits the growth of Escovopsis.","zh":"這種細菌抑制 Escovopsis 的生長。"},{"en":"Inhibit its growth means slow down or stop it from growing.","zh":"inhibit its growth 指減慢或阻止其生長。"},{"en":"Refrigeration can inhibit the growth of bacteria in food.","zh":"冷藏可以抑制食物中細菌的生長。"},{"en":"If bacteria inhibit mould growth, the fungus garden has a better chance of surviving.","zh":"如果細菌抑制霉菌生長，真菌園就有較高機會存活。"},{"en":"The phrase describes limiting biological growth.","zh":"這個片語描述限制生物生長。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":15},{"front":"suppress spore formation","meaning":"抑制孢子形成","examples":[{"en":"The bacterium suppresses spore formation in Escovopsis.","zh":"這種細菌抑制 Escovopsis 的孢子形成。"},{"en":"Suppress spore formation means prevent or reduce the production of spores.","zh":"suppress spore formation 指防止或減少孢子的產生。"},{"en":"Good ventilation can suppress mould growth in a damp room.","zh":"良好通風可以抑制潮濕房間中的霉菌生長。"},{"en":"If spores are not formed, the mould may spread less easily.","zh":"如果孢子沒有形成，霉菌可能較不容易擴散。"},{"en":"The phrase describes blocking a reproductive stage.","zh":"這個片語描述阻止繁殖階段。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":15},{"front":"stimulate growth","meaning":"促進生長","examples":[{"en":"The bacterium stimulates the growth of the ants’ mushroom fungus.","zh":"這種細菌促進螞蟻蘑菇真菌的生長。"},{"en":"Stimulate growth means encourage something to grow faster or better.","zh":"stimulate growth 指鼓勵某物更快或更好地生長。"},{"en":"Sunlight and water can stimulate plant growth in a garden.","zh":"陽光和水可以促進花園中植物生長。"},{"en":"If bacteria stimulate useful fungus, they help the ants’ food source become stronger.","zh":"如果細菌促進有用真菌生長，就幫助螞蟻食物來源變得更強。"},{"en":"The phrase describes positive encouragement of growth.","zh":"這個片語描述對生長的正面促進。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":15},{"front":"virgin queens","meaning":"未交配蟻后","examples":[{"en":"The bacterium is carried by virgin queens when they leave the nest.","zh":"未交配蟻后離巢時會攜帶這種細菌。"},{"en":"Virgin queens are young queen ants that have not yet mated.","zh":"virgin queens 指尚未交配的年輕蟻后。"},{"en":"In an ant colony, a queen’s role is important because she can start or maintain a colony.","zh":"在蟻群中，蟻后的角色重要，因為她可以建立或維持群落。"},{"en":"If virgin queens carry bacteria away, new nests can begin with disease-control helpers.","zh":"如果未交配蟻后把細菌帶走，新巢就能一開始擁有疾病控制幫手。"},{"en":"The phrase refers to a reproductive stage in ant life.","zh":"這個片語指螞蟻生命中的繁殖階段。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":15},{"front":"establish new nests","meaning":"建立新巢","examples":[{"en":"Virgin queens carry the bacterium when they leave to establish new nests.","zh":"未交配蟻后離開建立新巢時會攜帶這種細菌。"},{"en":"Establish new nests means create and start new ant colonies or homes.","zh":"establish new nests 指創建並開始新的蟻群或巢穴。"},{"en":"Birds establish new nests when they find safe places to raise young.","zh":"鳥類找到安全地方養育幼鳥時會建立新巢。"},{"en":"If queen ants establish new nests with bacteria, the new colony may have protection from the start.","zh":"如果蟻后帶着細菌建立新巢，新群落可能一開始就有保護。"},{"en":"The phrase describes founding a new living community.","zh":"這個片語描述建立新的生活群體。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":15},{"front":"take no responsibility for","meaning":"不負責……","examples":[{"en":"Male ants take no responsibility for nest-making or gardening.","zh":"雄蟻不負責築巢或照料菌園。"},{"en":"Take no responsibility for means not be responsible for doing or managing something.","zh":"take no responsibility for 指不負責做或管理某事。"},{"en":"A student who takes no responsibility for group work may leave all tasks to classmates.","zh":"不負責小組工作的學生可能把所有任務留給同學。"},{"en":"If male ants take no responsibility for gardening, the work is done by other ants.","zh":"如果雄蟻不負責照料菌園，這些工作就由其他螞蟻完成。"},{"en":"The phrase describes absence of duty.","zh":"這個片語描述沒有責任。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":16},{"front":"nest-making or gardening","meaning":"築巢或照料菌園","examples":[{"en":"Male ants do not take responsibility for nest-making or gardening.","zh":"雄蟻不負責築巢或照料菌園。"},{"en":"Nest-making or gardening means building nests or caring for fungus gardens.","zh":"nest-making or gardening 指建造巢穴或照料真菌園。"},{"en":"In human life, housework and gardening are practical tasks needed to maintain a home.","zh":"在人類生活中，家務和園藝是維持家庭所需的實際任務。"},{"en":"If certain ants do not do nest-making or gardening, their role in the colony is different.","zh":"如果某些螞蟻不做築巢或照料菌園的工作，其群落角色就不同。"},{"en":"The phrase lists two colony-maintenance tasks.","zh":"這個片語列出兩項維持群落的任務。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":16},{"front":"part of their symbiosis","meaning":"其共生關係的一部分","examples":[{"en":"The bacterium may have been part of their symbiosis for millions of years.","zh":"這種細菌可能數百萬年來一直是其共生關係的一部分。"},{"en":"Part of their symbiosis means one component of the close relationship between the organisms.","zh":"part of their symbiosis 指這些生物密切關係中的一個組成部分。"},{"en":"In a school project, regular communication may be part of successful teamwork.","zh":"在學校項目中，定期溝通可能是成功團隊合作的一部分。"},{"en":"If bacteria are part of the symbiosis, the ants and fungus relationship includes a third organism.","zh":"如果細菌是共生關係的一部分，螞蟻與真菌關係就包括第三種生物。"},{"en":"The phrase shows membership in a cooperative system.","zh":"這個片語顯示某物屬於合作系統。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":16},{"front":"for almost as long as","meaning":"幾乎與……一樣久","examples":[{"en":"The bacterium may have been present for almost as long as the mould.","zh":"這種細菌存在的時間可能幾乎與霉菌一樣久。"},{"en":"For almost as long as means for nearly the same length of time as something else.","zh":"for almost as long as 指持續時間幾乎與另一事物相同。"},{"en":"A school tradition may have existed for almost as long as the school itself.","zh":"學校傳統可能存在得幾乎與學校本身一樣久。"},{"en":"If bacteria and mould have existed together for nearly the same period, their relationship may be ancient.","zh":"如果細菌和霉菌共同存在了幾乎相同時間，牠們的關係可能很古老。"},{"en":"The phrase compares duration.","zh":"這個片語比較時間長度。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":16},{"front":"an ant equivalent of","meaning":"相當於……的螞蟻版本","examples":[{"en":"An ant equivalent of Alexander Fleming discovered antibiotics long ago.","zh":"相當於 Alexander Fleming 的螞蟻版本很久以前就發現了抗生素。"},{"en":"An ant equivalent of means an ant version of a person, role, or achievement.","zh":"an ant equivalent of 指某人物、角色或成就的螞蟻版本。"},{"en":"A school may call a helpful student the class equivalent of a librarian if they organise all the books.","zh":"如果一名學生整理所有書本，學校可能稱他為班中的圖書館員版本。"},{"en":"If ants found antibiotic use before humans, the comparison makes their achievement feel impressive.","zh":"如果螞蟻在人類之前發現抗生素使用，這種比較令其成就顯得驚人。"},{"en":"The phrase uses analogy to compare ants with humans.","zh":"這個片語用類比把螞蟻與人類作比較。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":16},{"front":"discover antibiotics","meaning":"發現抗生素","examples":[{"en":"The ants may have discovered antibiotics millions of years before people did.","zh":"螞蟻可能比人類早數百萬年發現抗生素。"},{"en":"Discover antibiotics means find or begin using substances that fight harmful microbes.","zh":"discover antibiotics 指發現或開始使用能對抗有害微生物的物質。"},{"en":"Scientists discovered antibiotics that changed the treatment of bacterial infections.","zh":"科學家發現抗生素，改變了細菌感染的治療。"},{"en":"If ants discovered antibiotic use naturally, their farming system is more advanced than expected.","zh":"如果螞蟻自然發現抗生素使用，其農耕系統就比預期更先進。"},{"en":"The phrase links discovery with disease control.","zh":"這個片語把發現與疾病控制連接起來。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":16},{"front":"millions of years before people did","meaning":"比人類早幾百萬年","examples":[{"en":"The ants used antibiotics millions of years before people did.","zh":"螞蟻比人類早幾百萬年使用抗生素。"},{"en":"Millions of years before people did means far earlier than humans achieved the same thing.","zh":"millions of years before people did 指遠早於人類做到同一件事。"},{"en":"Plants used chemical defences millions of years before people made pesticides.","zh":"植物比人類製造農藥早幾百萬年使用化學防禦。"},{"en":"If ants used antibiotics before humans, natural evolution solved the problem first.","zh":"如果螞蟻在人類之前使用抗生素，自然演化就先解決了問題。"},{"en":"The phrase emphasises a huge time advantage.","zh":"這個片語強調巨大的時間優勢。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":16},{"front":"accomplish two feats","meaning":"完成兩項壯舉","examples":[{"en":"The ants are accomplishing two feats beyond human technology.","zh":"螞蟻正在完成兩項超出人類科技能力的壯舉。"},{"en":"Accomplish two feats means successfully do two difficult and impressive things.","zh":"accomplish two feats 指成功完成兩件困難而令人印象深刻的事情。"},{"en":"A student who wins a science prize and teaches younger classmates accomplishes two impressive feats.","zh":"學生贏得科學獎並教導低年級同學，就是完成兩項令人印象深刻的壯舉。"},{"en":"If ants farm a crop and control disease, both achievements are remarkable.","zh":"如果螞蟻既種植作物又控制疾病，兩項成就都很驚人。"},{"en":"The phrase highlights double achievement.","zh":"這個片語突出雙重成就。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":16},{"front":"beyond the powers of human technology","meaning":"超出人類科技能力範圍","examples":[{"en":"The ants perform tasks beyond the powers of human technology.","zh":"螞蟻完成超出人類科技能力範圍的任務。"},{"en":"Beyond the powers of human technology means not yet possible for human technology to do well.","zh":"beyond the powers of human technology 指目前人類科技仍未能妥善做到。"},{"en":"Perfectly predicting every earthquake is beyond the powers of current human technology.","zh":"完美預測每一次地震仍超出現今人類科技能力範圍。"},{"en":"If ants manage a disease-free monoculture naturally, humans may still struggle to copy it.","zh":"如果螞蟻能自然管理沒有災難的單一栽培，人類可能仍難以複製。"},{"en":"The phrase emphasises limits of human ability.","zh":"這個片語強調人類能力的限制。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":16},{"front":"grow a monocultural crop","meaning":"種植單一作物","examples":[{"en":"The leaf-cutters grow a monocultural crop year after year.","zh":"切葉蟻年復一年種植單一作物。"},{"en":"Grow a monocultural crop means cultivate one uniform crop type repeatedly.","zh":"grow a monocultural crop 指反覆培植一種一致的作物類型。"},{"en":"A farm that plants only one variety of wheat grows a monocultural crop.","zh":"只種一種小麥品種的農場，就是種植單一作物。"},{"en":"If ants grow one fungus crop repeatedly, disease control becomes especially important.","zh":"如果螞蟻反覆種植一種真菌作物，疾病控制就特別重要。"},{"en":"The phrase links farming efficiency with vulnerability.","zh":"這個片語把農耕效率與脆弱性連接起來。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":16},{"front":"year after year","meaning":"年復一年","examples":[{"en":"The ants grow the same crop year after year without disaster.","zh":"螞蟻年復一年種植同一作物而沒有造成災難。"},{"en":"Year after year means every year repeatedly over a long period.","zh":"year after year 指多年來每年反覆如此。"},{"en":"A teacher may improve the same course year after year by listening to student feedback.","zh":"老師可能透過聆聽學生回饋，年復一年改善同一課程。"},{"en":"If ants farm the same fungus year after year, their system must be stable.","zh":"如果螞蟻年復一年種植同一真菌，其系統必須穩定。"},{"en":"The phrase stresses repeated long-term action.","zh":"這個片語強調長期反覆行動。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":17},{"front":"without disaster","meaning":"沒有造成災難","examples":[{"en":"The ants grow the crop year after year without disaster.","zh":"螞蟻年復一年種植該作物而沒有造成災難。"},{"en":"Without disaster means without serious failure, collapse, or destruction.","zh":"without disaster 指沒有嚴重失敗、崩潰或破壞。"},{"en":"A school trip can run without disaster if teachers plan transport, food, and safety carefully.","zh":"如果老師仔細規劃交通、食物和安全，學校旅行可以順利進行而沒有災難。"},{"en":"If monoculture continues without disaster, disease must be controlled effectively.","zh":"如果單一栽培能持續而沒有災難，疾病必須被有效控制。"},{"en":"The phrase highlights avoided catastrophe.","zh":"這個片語突出災難被避免。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":17},{"front":"wisely and prudently","meaning":"明智而審慎地","examples":[{"en":"The ants use an antibiotic wisely and prudently.","zh":"螞蟻明智而審慎地使用抗生素。"},{"en":"Wisely and prudently means in a careful, sensible, and responsible way.","zh":"wisely and prudently 指以小心、理性和負責任的方式。"},{"en":"A family spends money wisely and prudently when it saves before buying luxuries.","zh":"家庭先儲蓄再購買奢侈品，就是明智而審慎地花錢。"},{"en":"If antibiotics are used wisely, resistance is less likely to develop quickly.","zh":"如果抗生素被明智使用，耐藥性就較不容易迅速形成。"},{"en":"The phrase praises careful judgement.","zh":"這個片語讚賞謹慎判斷。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":17},{"front":"provoke antibiotic resistance","meaning":"引發抗生素耐藥性","examples":[{"en":"The ants do not appear to provoke antibiotic resistance.","zh":"螞蟻似乎沒有引發抗生素耐藥性。"},{"en":"Provoke antibiotic resistance means cause microbes to evolve so antibiotics stop working well.","zh":"provoke antibiotic resistance 指導致微生物演化到抗生素不再有效。"},{"en":"Overusing antibiotics in people can provoke antibiotic resistance in bacteria.","zh":"人類過度使用抗生素可以引發細菌的抗生素耐藥性。"},{"en":"If ants avoid resistance while using antibiotics, their method is unusually effective.","zh":"如果螞蟻使用抗生素卻避免耐藥性，其方法就異常有效。"},{"en":"The phrase describes a serious medical and biological problem.","zh":"這個片語描述嚴重的醫學和生物問題。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":17},{"front":"antibiotic resistance","meaning":"抗生素耐藥性","examples":[{"en":"Human use of antibiotics can provoke antibiotic resistance.","zh":"人類使用抗生素可能引發抗生素耐藥性。"},{"en":"Antibiotic resistance is the ability of bacteria to survive medicines that once killed them.","zh":"antibiotic resistance 指細菌能在原本能殺死它們的藥物下存活。"},{"en":"Doctors warn patients to finish prescribed antibiotics to reduce resistance risk.","zh":"醫生提醒病人完成處方抗生素，以降低耐藥風險。"},{"en":"If antibiotic resistance spreads, common infections can become harder to treat.","zh":"如果抗生素耐藥性擴散，常見感染可能變得更難治療。"},{"en":"The phrase is important in public health.","zh":"這個片語在公共健康中很重要。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":17},{"front":"target pathogen","meaning":"目標病原體","examples":[{"en":"Escovopsis is the target pathogen of the ants’ antibiotic strategy.","zh":"Escovopsis 是螞蟻抗生素策略的目標病原體。"},{"en":"Target pathogen means the specific disease-causing organism that a treatment or defence aims to attack.","zh":"target pathogen 指治療或防禦旨在攻擊的特定致病生物。"},{"en":"A medicine may be designed for one target pathogen rather than every kind of germ.","zh":"藥物可能針對一種目標病原體，而不是所有病菌。"},{"en":"If ants’ bacteria affect Escovopsis specifically, Escovopsis is the target pathogen.","zh":"如果螞蟻的細菌專門影響 Escovopsis，Escovopsis 就是目標病原體。"},{"en":"The phrase identifies what the defence is aimed at.","zh":"這個片語指出防禦針對甚麼。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":17},{"front":"match one group with another","meaning":"將一組與另一組配對","examples":[{"en":"Students have to match the ant groups with the activities or features.","zh":"學生必須把螞蟻群體與活動或特徵配對。"},{"en":"Match one group with another means connect each item in one set to the correct item in another set.","zh":"match one group with another 指把一組中的每項與另一組中的正確項目連接。"},{"en":"In a vocabulary exercise, students match words with their meanings.","zh":"在詞彙練習中，學生把單詞與其意思配對。"},{"en":"If students match groups wrongly, they may confuse which ants use which methods.","zh":"如果學生配對錯誤，可能混淆哪些螞蟻使用哪些方法。"},{"en":"The phrase describes a common exam task.","zh":"這個片語描述常見考試任務。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":17},{"front":"activities or features","meaning":"活動或特徵","examples":[{"en":"The question asks about the activities or features of different ant groups.","zh":"題目詢問不同螞蟻群體的活動或特徵。"},{"en":"Activities or features means what the groups do or what characteristics they have.","zh":"activities or features 指這些群體做甚麼或具備甚麼特性。"},{"en":"A school form may ask about a club’s activities or features before students join.","zh":"學校表格可能在學生加入前詢問學會的活動或特徵。"},{"en":"If students identify activities and features correctly, they can distinguish the ant groups.","zh":"如果學生正確識別活動和特徵，就能分辨螞蟻群體。"},{"en":"The phrase covers actions and characteristics.","zh":"這個片語涵蓋行動和特性。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":17},{"front":"use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"The instructions say that students may use any letter more than once.","zh":"指示說學生可重複使用任何字母。"},{"en":"Use any letter more than once means the same answer option can be chosen for multiple questions.","zh":"use any letter more than once 指同一答案選項可以用於多條題目。"},{"en":"In matching tasks, one heading may fit two paragraphs, so students may use the same letter twice.","zh":"在配對題中，一個標題可能適合兩段，所以學生可以同一字母用兩次。"},{"en":"If students assume each letter can be used only once, they may choose wrong answers.","zh":"如果學生以為每個字母只能用一次，可能選錯答案。"},{"en":"The phrase gives an important exam-rule reminder.","zh":"這個片語給出重要考試規則提醒。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":17},{"front":"toxic leaves","meaning":"有毒葉子","examples":[{"en":"Some ants can use toxic leaves to feed their fungus.","zh":"有些螞蟻可以使用有毒葉子餵養其真菌。"},{"en":"Toxic leaves are leaves containing chemicals that can poison or sicken animals.","zh":"toxic leaves 指含有可毒害或令動物生病的化學物的葉子。"},{"en":"Children should not eat unknown garden leaves because some may be toxic.","zh":"孩子不應吃未知花園葉子，因為有些可能有毒。"},{"en":"If ants use toxic leaves safely, the fungus must help process the harmful chemicals.","zh":"如果螞蟻能安全使用有毒葉子，真菌必須幫助處理有害化學物。"},{"en":"The phrase describes dangerous plant material.","zh":"這個片語描述危險植物材料。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":17},{"front":"feed their fungus","meaning":"餵養其真菌","examples":[{"en":"The ants use plant material to feed their fungus.","zh":"螞蟻使用植物材料餵養其真菌。"},{"en":"Feed their fungus means provide material that the fungus can grow on or use as food.","zh":"feed their fungus 指提供真菌可生長或作為食物的材料。"},{"en":"Gardeners feed plants with compost, while ants feed fungus with leaves.","zh":"園丁用堆肥餵養植物，而螞蟻用葉子餵養真菌。"},{"en":"If ants do not feed their fungus, the garden will weaken and the colony may lose food.","zh":"如果螞蟻不餵養真菌，菌園會變弱，群落可能失去食物。"},{"en":"The phrase shows that the ants actively care for their crop.","zh":"這個片語顯示螞蟻主動照顧作物。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":18},{"front":"build small nests","meaning":"建造小型巢穴","examples":[{"en":"Some ant groups build small nests and use primitive techniques.","zh":"有些螞蟻群體建造小型巢穴並使用原始技術。"},{"en":"Build small nests means construct small homes or colony spaces.","zh":"build small nests 指建造小型居所或群落空間。"},{"en":"Birds build small nests with twigs, leaves, and soft materials.","zh":"鳥類用小枝、葉子和柔軟材料建造小型巢穴。"},{"en":"If ants build small nests, their colonies may be smaller or less complex than leaf-cutter colonies.","zh":"如果螞蟻建造小型巢穴，其群落可能比切葉蟻群落更小或較不複雜。"},{"en":"The phrase describes nest construction and size.","zh":"這個片語描述巢穴建造和大小。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":18},{"front":"cultivate different fungus varieties","meaning":"培植不同真菌品種","examples":[{"en":"Lower attines cultivate different fungus varieties.","zh":"較低等 Attini 蟻培植不同真菌品種。"},{"en":"Cultivate different fungus varieties means grow several types of fungus rather than one single type.","zh":"cultivate different fungus varieties 指培植幾種類型的真菌，而不是單一類型。"},{"en":"A farmer may cultivate different crop varieties to reduce the risk of disease.","zh":"農民可能培植不同作物品種，以降低疾病風險。"},{"en":"If ants cultivate different fungi, parasites may find it harder to attack every garden.","zh":"如果螞蟻培植不同真菌，寄生物可能更難攻擊每個菌園。"},{"en":"The phrase highlights diversity in farming.","zh":"這個片語突出農耕中的多樣性。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":18},{"front":"dead vegetation","meaning":"枯死植物","examples":[{"en":"Some ants use dead vegetation to feed their fungus.","zh":"有些螞蟻使用枯死植物餵養其真菌。"},{"en":"Dead vegetation means plant material that is no longer alive, such as fallen leaves or dry stems.","zh":"dead vegetation 指不再有生命的植物材料，例如落葉或乾莖。"},{"en":"Gardeners collect dead vegetation to make compost.","zh":"園丁收集枯死植物製作堆肥。"},{"en":"If ants use dead vegetation, their farming material differs from fresh leaf-cutting ants’ material.","zh":"如果螞蟻使用枯死植物，其農耕材料就不同於使用新鮮葉子的切葉蟻。"},{"en":"The phrase refers to old plant matter.","zh":"這個片語指舊植物材料。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":18},{"front":"a single fungus strain","meaning":"單一真菌菌株","examples":[{"en":"Leaf-cutters cultivate a single fungus strain rather than several varieties.","zh":"切葉蟻培植單一真菌菌株，而不是多個品種。"},{"en":"A single fungus strain is one specific genetic type of fungus.","zh":"a single fungus strain 指一種特定基因類型的真菌。"},{"en":"A lab may study a single fungus strain so results are easier to compare.","zh":"實驗室可能研究單一真菌菌株，讓結果更容易比較。"},{"en":"If ants depend on one strain, their crop may be productive but vulnerable.","zh":"如果螞蟻依賴單一菌株，其作物可能高產但脆弱。"},{"en":"The phrase points to genetic uniformity.","zh":"這個片語指出基因一致性。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":18},{"front":"rather than several varieties","meaning":"而不是多個品種","examples":[{"en":"The ants cultivate a single fungus strain rather than several varieties.","zh":"螞蟻培植單一真菌菌株，而不是多個品種。"},{"en":"Rather than several varieties means instead of growing multiple different types.","zh":"rather than several varieties 指不是培植多種不同類型，而是另一選擇。"},{"en":"A café may sell one signature cake rather than several varieties to keep quality consistent.","zh":"咖啡店可能出售一款招牌蛋糕，而不是多個品種，以保持質素一致。"},{"en":"If ants choose one fungus strain rather than several, they gain uniformity but lose diversity.","zh":"如果螞蟻選擇一種真菌菌株而不是多個品種，就得到一致性但失去多樣性。"},{"en":"The phrase clearly shows contrast.","zh":"這個片語清楚顯示對比。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":18},{"front":"a highly dangerous parasite","meaning":"極危險的寄生物","examples":[{"en":"Escovopsis is a highly dangerous parasite in fungus gardens.","zh":"Escovopsis 是真菌園中極危險的寄生物。"},{"en":"A highly dangerous parasite is a parasite that can cause serious harm or destruction.","zh":"a highly dangerous parasite 指可造成嚴重傷害或破壞的寄生物。"},{"en":"A parasite that kills crops quickly would be highly dangerous to farmers.","zh":"快速殺死作物的寄生物對農民而言會非常危險。"},{"en":"If Escovopsis destroys fungus gardens, it threatens the ants’ survival.","zh":"如果 Escovopsis 摧毀真菌園，就威脅螞蟻的生存。"},{"en":"The phrase stresses both parasitic behaviour and serious risk.","zh":"這個片語同時強調寄生行為和嚴重風險。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":18},{"front":"combat Escovopsis","meaning":"對抗 Escovopsis","examples":[{"en":"The ants use a special strategy to combat Escovopsis.","zh":"螞蟻使用特殊策略對抗 Escovopsis。"},{"en":"Combat Escovopsis means fight against or control the Escovopsis mould.","zh":"combat Escovopsis 指對抗或控制 Escovopsis 霉菌。"},{"en":"Doctors combat infections by using suitable medicines and hygiene rules.","zh":"醫生透過合適藥物和衛生規則對抗感染。"},{"en":"If ants combat Escovopsis successfully, their fungus gardens can survive.","zh":"如果螞蟻成功對抗 Escovopsis，其真菌園就能生存。"},{"en":"The phrase describes active defence against a pathogen.","zh":"這個片語描述對病原體的主動防禦。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":18},{"front":"contains the following information","meaning":"包含以下資料","examples":[{"en":"Each paragraph contains different information about the ants and their fungus.","zh":"每段包含關於螞蟻及其真菌的不同資料。"},{"en":"Contains the following information means includes the details listed in the question.","zh":"contains the following information 指包括題目列出的細節。"},{"en":"A school notice contains information about dates, fees, and required documents.","zh":"學校通告包含日期、費用和所需文件等資料。"},{"en":"If a paragraph contains the required information, students should match it with the correct item.","zh":"如果段落包含所需資料，學生應把它與正確項目配對。"},{"en":"The phrase is common in reading-location questions.","zh":"這個片語常見於閱讀定位題。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":18},{"front":"dangerous consequences","meaning":"危險後果","examples":[{"en":"The passage describes the dangerous consequences of Escovopsis.","zh":"文章描述 Escovopsis 的危險後果。"},{"en":"Dangerous consequences are harmful results that follow from a problem or action.","zh":"dangerous consequences 指由問題或行動帶來的有害結果。"},{"en":"Ignoring fire alarms can have dangerous consequences in a school building.","zh":"忽視火警鐘在學校建築中可能帶來危險後果。"},{"en":"If Escovopsis spreads, the dangerous consequences include garden collapse and starvation.","zh":"如果 Escovopsis 擴散，危險後果包括菌園崩潰和飢餓。"},{"en":"The phrase focuses on serious negative results.","zh":"這個片語集中於嚴重負面結果。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":18},{"front":"the risk of cultivating","meaning":"培植……的風險","examples":[{"en":"The question asks about the risk of cultivating a single fungus strain.","zh":"題目詢問培植單一真菌菌株的風險。"},{"en":"The risk of cultivating means the possible danger created by growing something.","zh":"the risk of cultivating 指種植或培植某物所造成的可能危險。"},{"en":"Farmers consider the risk of cultivating one crop when disease is common.","zh":"當疾病常見時，農民會考慮培植單一作物的風險。"},{"en":"If cultivation reduces diversity, the risk of disease may increase.","zh":"如果培植降低多樣性，疾病風險可能上升。"},{"en":"The phrase connects farming with possible harm.","zh":"這個片語把農耕與可能傷害連接起來。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":19},{"front":"a comparison of","meaning":"……之間的比較","examples":[{"en":"The passage includes a comparison of nests and feeding materials.","zh":"文章包括巢穴和餵養材料之間的比較。"},{"en":"A comparison of means an explanation of similarities and differences between things.","zh":"a comparison of 指解釋事物之間的相似點和差異。"},{"en":"A teacher may ask for a comparison of city life and village life.","zh":"老師可能要求學生比較城市生活和鄉村生活。"},{"en":"If a passage compares materials, students should notice both categories and contrasts.","zh":"如果文章比較材料，學生應注意兩個類別和對比。"},{"en":"The phrase introduces a contrast-based analysis.","zh":"這個片語引出基於對比的分析。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":19},{"front":"materials used to feed","meaning":"用來餵養……的材料","examples":[{"en":"The passage compares the materials used to feed fungus gardens.","zh":"文章比較用來餵養真菌園的材料。"},{"en":"Materials used to feed means substances provided as food or growth material.","zh":"materials used to feed 指作為食物或生長材料提供的物質。"},{"en":"Compost and water are materials used to feed plants in a garden.","zh":"堆肥和水是花園中用來餵養植物的材料。"},{"en":"If ants use different feeding materials, their fungus gardens may develop differently.","zh":"如果螞蟻使用不同餵養材料，其真菌園可能發展不同。"},{"en":"The phrase focuses on what is supplied for growth.","zh":"這個片語集中於為生長提供甚麼。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":19},{"front":"precede comparable human discoveries","meaning":"早於人類相類似的發現","examples":[{"en":"The ants’ achievements preceded comparable human discoveries.","zh":"螞蟻的成就早於人類相類似的發現。"},{"en":"Precede comparable human discoveries means happen earlier than similar discoveries made by humans.","zh":"precede comparable human discoveries 指發生時間早於人類作出的相似發現。"},{"en":"Nature often precedes human technology when animals solve problems before engineers copy them.","zh":"當動物在人類工程師模仿之前已解決問題時，自然常早於人類科技。"},{"en":"If ants used antibiotics before humans, their discovery preceded ours by millions of years.","zh":"如果螞蟻在人類之前使用抗生素，其發現就比我們早幾百萬年。"},{"en":"The phrase compares timing between natural and human innovation.","zh":"這個片語比較自然創新和人類創新的時間。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":19},{"front":"an advantage of cultivating new varieties","meaning":"培植新品種的好處","examples":[{"en":"The passage explains an advantage of cultivating new fungus varieties.","zh":"文章解釋培植新真菌品種的好處。"},{"en":"An advantage of cultivating new varieties is a benefit gained by growing different or newly domesticated types.","zh":"an advantage of cultivating new varieties 指培植不同或新馴化品種所得到的好處。"},{"en":"Farmers may gain an advantage from new crop varieties if they resist disease better.","zh":"如果新品種作物更能抗病，農民就可能從中獲得好處。"},{"en":"If ants cultivate new fungi, they may stay ahead of parasites adapted to old strains.","zh":"如果螞蟻培植新真菌，可能領先已適應舊菌株的寄生物一步。"},{"en":"The phrase focuses on the benefit of variety and change.","zh":"這個片語集中於多樣性和改變的好處。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":19},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students must choose the correct letter from the answer options.","zh":"學生必須從答案選項中選出正確字母。"},{"en":"Choose the correct letter means select the option letter that matches the correct answer.","zh":"choose the correct letter 指選出與正確答案相符的選項字母。"},{"en":"In a reading test, students should choose the letter only after checking the passage.","zh":"在閱讀測驗中，學生應查看文章後才選字母。"},{"en":"If the answer idea is right but the wrong letter is written, the mark may be lost.","zh":"如果答案意思正確但字母寫錯，可能失分。"},{"en":"The phrase is a standard exam instruction.","zh":"這個片語是標準考試指示。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":19},{"front":"indicate about","meaning":"顯示關於……","examples":[{"en":"The question asks what the passage indicates about Currie’s view.","zh":"題目問文章顯示了關於 Currie 觀點的甚麼。"},{"en":"Indicate about means show or suggest information concerning a topic.","zh":"indicate about 指顯示或暗示關於某主題的資料。"},{"en":"A teacher’s comments may indicate something about a student’s progress.","zh":"老師的評語可能顯示關於學生進度的一些事情。"},{"en":"If a passage indicates a view, students should look for evidence rather than guess.","zh":"如果文章顯示某觀點，學生應尋找證據，而不是猜測。"},{"en":"The phrase asks what the text shows.","zh":"這個片語詢問文本顯示甚麼。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":19},{"front":"rejection of the claim that","meaning":"拒絕接受……的說法","examples":[{"en":"The question concerns Currie’s rejection of the claim that ants keep gardens parasite-free.","zh":"題目關於 Currie 拒絕接受螞蟻能使菌園沒有寄生物的說法。"},{"en":"Rejection of the claim that means refusal to accept a stated idea as true.","zh":"rejection of the claim that 指拒絕接受某個陳述為真。"},{"en":"A scientist’s rejection of a claim should be based on evidence, not personal dislike.","zh":"科學家拒絕某主張應基於證據，而不是個人不喜歡。"},{"en":"If new data shows parasites are present, rejecting the old claim becomes reasonable.","zh":"如果新數據顯示寄生物存在，拒絕舊說法就變得合理。"},{"en":"The phrase describes disagreement with a specific statement.","zh":"這個片語描述對特定陳述的不同意。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":19},{"front":"keep their gardens free of parasites","meaning":"使其菌園沒有寄生物","examples":[{"en":"Some researchers claimed that ants keep their gardens free of parasites.","zh":"有些研究人員聲稱螞蟻能使其菌園沒有寄生物。"},{"en":"Keep their gardens free of parasites means prevent parasitic organisms from living in the gardens.","zh":"keep their gardens free of parasites 指防止寄生生物生活在菌園中。"},{"en":"Gardeners remove pests to keep vegetables free of insects and disease.","zh":"園丁移除害蟲，以使蔬菜免受昆蟲和疾病侵害。"},{"en":"If ants truly kept gardens parasite-free, scientists would not expect to find Escovopsis there.","zh":"如果螞蟻真的能使菌園沒有寄生物，科學家就不會預期在那裡找到 Escovopsis。"},{"en":"The phrase describes complete parasite prevention.","zh":"這個片語描述完全防止寄生物。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":19},{"front":"be later confirmed","meaning":"後來得到證實","examples":[{"en":"Currie’s view was later confirmed by further evidence.","zh":"Currie 的觀點後來由進一步證據證實。"},{"en":"Be later confirmed means be shown to be correct by evidence found afterwards.","zh":"be later confirmed 指之後被發現的證據顯示為正確。"},{"en":"A student’s guess may be later confirmed when the teacher explains the answer.","zh":"學生的猜測可能在老師解釋答案時後來得到證實。"},{"en":"If a scientific idea is later confirmed, it becomes more convincing.","zh":"如果科學想法後來得到證實，它就變得更有說服力。"},{"en":"The phrase describes support that arrives after the original claim.","zh":"這個片語描述原本主張之後得到支持。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":19},{"front":"initial study","meaning":"初步研究","examples":[{"en":"An initial study may not provide enough evidence.","zh":"初步研究可能沒有提供足夠證據。"},{"en":"An initial study is the first study or early investigation into a topic.","zh":"initial study 指對某主題進行的第一項研究或早期調查。"},{"en":"An initial study of a new teaching method may involve only one class.","zh":"關於新教學方法的初步研究可能只涉及一班學生。"},{"en":"If an initial study is small, further research is needed before strong conclusions.","zh":"如果初步研究規模小，在作出強結論前需要進一步研究。"},{"en":"The phrase refers to early-stage research.","zh":"這個片語指早期階段研究。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":20},{"front":"sufficient evidence","meaning":"充分證據","examples":[{"en":"The scientists needed sufficient evidence to support the claim.","zh":"科學家需要充分證據來支持該主張。"},{"en":"Sufficient evidence means enough proof to make a claim believable or acceptable.","zh":"sufficient evidence 指足以令主張可信或可接受的證據。"},{"en":"A teacher needs sufficient evidence before accusing a student of cheating.","zh":"老師在指控學生作弊前需要充分證據。"},{"en":"If there is not sufficient evidence, a conclusion should remain cautious.","zh":"如果沒有充分證據，結論就應保持謹慎。"},{"en":"The phrase focuses on enough support for a judgement.","zh":"這個片語集中於判斷是否有足夠支持。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":20},{"front":"provide no details","meaning":"沒有提供細節","examples":[{"en":"The passage may provide no details about a particular issue.","zh":"文章可能沒有提供關於某個議題的細節。"},{"en":"Provide no details means give no specific information about something.","zh":"provide no details 指沒有給出某事的具體資料。"},{"en":"A school notice that only says “trip soon” provides no details about time or place.","zh":"如果學校通告只說「很快旅行」，卻沒有提供時間或地點細節。"},{"en":"If a passage provides no details, students should not invent information.","zh":"如果文章沒有提供細節，學生不應自行創作資料。"},{"en":"The phrase is useful for NOT GIVEN-style reading questions.","zh":"這個片語適合用於 NOT GIVEN 類閱讀題。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":20},{"front":"be later disproved","meaning":"後來被推翻","examples":[{"en":"A scientific view can be later disproved by new evidence.","zh":"科學觀點可以被新證據後來推翻。"},{"en":"Be later disproved means be shown to be false by evidence found afterwards.","zh":"be later disproved 指被之後發現的證據顯示為錯誤。"},{"en":"A rumour may be later disproved when security footage is checked.","zh":"謠言可能在保安錄像被查看後被推翻。"},{"en":"If new research disproves an old claim, textbooks may need to change.","zh":"如果新研究推翻舊主張，教科書可能需要修改。"},{"en":"The phrase describes correction through later evidence.","zh":"這個片語描述透過後來證據作出修正。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":20},{"front":"under a microscope","meaning":"在顯微鏡下","examples":[{"en":"Scientists examined the ants’ cuticles under a microscope.","zh":"科學家在顯微鏡下檢查螞蟻表皮。"},{"en":"Under a microscope means using a microscope to see very small details.","zh":"under a microscope 指使用顯微鏡觀察非常細小的細節。"},{"en":"Students look at cells under a microscope in biology class.","zh":"學生在生物課中在顯微鏡下觀察細胞。"},{"en":"If something is too small to see clearly, scientists put it under a microscope.","zh":"如果某物太小而看不清，科學家會把它放在顯微鏡下。"},{"en":"The phrase describes close scientific observation.","zh":"這個片語描述仔細的科學觀察。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":20},{"front":"a substance useful to humans","meaning":"對人類有用的物質","examples":[{"en":"The scientists found a substance useful to humans on the ants’ cuticles.","zh":"科學家在螞蟻表皮上發現對人類有用的物質。"},{"en":"A substance useful to humans is a material or chemical that can help people in some way.","zh":"a substance useful to humans 指能以某種方式幫助人的材料或化學物。"},{"en":"Penicillin is a substance useful to humans because it can treat bacterial infections.","zh":"青霉素是對人類有用的物質，因為它可以治療細菌感染。"},{"en":"If ants carry a useful antibiotic-producing bacterium, humans may study it for medicine.","zh":"如果螞蟻攜帶能產生有用抗生素的細菌，人類可能研究它作醫學用途。"},{"en":"The phrase connects natural discovery with human benefit.","zh":"這個片語把自然發現與人類好處連接起來。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":20},{"front":"suppress fungal growth","meaning":"抑制真菌生長","examples":[{"en":"The bacterium can suppress fungal growth.","zh":"這種細菌可以抑制真菌生長。"},{"en":"Suppress fungal growth means slow down or stop fungus from growing.","zh":"suppress fungal growth 指減慢或阻止真菌生長。"},{"en":"Keeping food dry can suppress fungal growth on bread and fruit.","zh":"保持食物乾爽可以抑制麵包和水果上的真菌生長。"},{"en":"If bacteria suppress fungal growth, they may protect the ants’ crop from disease.","zh":"如果細菌抑制真菌生長，它們可能保護螞蟻作物免受疾病侵害。"},{"en":"The phrase describes controlling fungus rather than removing it instantly.","zh":"這個片語描述控制真菌，而不是立即清除它。"}],"source":"45 - Leaf-Cutting Ants and Fungus.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 46":[{"front":"the development of plastics","meaning":"塑膠的發展","examples":[{"en":"The development of plastics changed modern manufacturing.","zh":"塑膠的發展改變了現代製造業。"},{"en":"The development of plastics means the process by which plastic materials were invented, improved, and widely used.","zh":"「the development of plastics」指塑膠材料被發明、改良並廣泛使用的過程。"},{"en":"A science lesson on the development of plastics may begin with rubber, celluloid, and Bakelite.","zh":"關於塑膠發展的科學課可能由橡膠、賽璐珞和電木開始。"},{"en":"As plastics developed, factories could make cheaper, lighter, and more durable products.","zh":"隨着塑膠發展，工廠能製造更便宜、更輕、更耐用的產品。"},{"en":"The phrase focuses on a historical process, not just one plastic object.","zh":"這個短語集中於歷史過程，而不只是某件塑膠物品。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":1},{"front":"first commercially produced","meaning":"首次作商業化生產","examples":[{"en":"Rubber was first commercially produced in Europe during the nineteenth century.","zh":"橡膠在十九世紀期間首次在歐洲作商業化生產。"},{"en":"First commercially produced means first made and sold as a product for business use.","zh":"「first commercially produced」意思是首次被製造並作為商品出售作商業用途。"},{"en":"A new material may be invented in a laboratory years before it is commercially produced.","zh":"新材料可能在實驗室發明多年後才作商業化生產。"},{"en":"When a product is first commercially produced, factories, buyers, and markets begin to matter.","zh":"當產品首次作商業化生產時，工廠、買家和市場開始變得重要。"},{"en":"The phrase marks the beginning of large-scale business use.","zh":"這個短語標誌大規模商業使用的開始。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":1},{"front":"during the nineteenth century","meaning":"在十九世紀期間","examples":[{"en":"Rubber became an important commodity during the nineteenth century.","zh":"橡膠在十九世紀期間成為重要商品。"},{"en":"During the nineteenth century means in the period from 1801 to 1900.","zh":"「during the nineteenth century」意思是在1801年至1900年期間。"},{"en":"Many railways expanded during the nineteenth century.","zh":"許多鐵路在十九世紀期間擴展。"},{"en":"If a material became popular during the nineteenth century, it belonged to a time of rapid industrial change.","zh":"如果一種材料在十九世紀期間變得流行，它就屬於工業快速變化的時期。"},{"en":"The phrase gives a historical time period.","zh":"這個短語提供歷史時期。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":1},{"front":"rapidly became","meaning":"迅速變成","examples":[{"en":"Rubber rapidly became a very important commodity.","zh":"橡膠迅速變成非常重要的商品。"},{"en":"Rapidly became means changed into a new state quickly.","zh":"「rapidly became」意思是很快變成新的狀態。"},{"en":"A small online shop may rapidly become popular if many customers recommend it.","zh":"如果很多顧客推薦，小型網店可能迅速變得受歡迎。"},{"en":"When transport and electricity grew, rubber quickly became more valuable.","zh":"當交通運輸和電力發展，橡膠很快變得更有價值。"},{"en":"The phrase stresses speed of change.","zh":"這個短語強調變化速度。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":1},{"front":"a very important commodity","meaning":"非常重要的商品","examples":[{"en":"Rubber rapidly became a very important commodity in Europe.","zh":"橡膠在歐洲迅速成為非常重要的商品。"},{"en":"A very important commodity is a valuable material or product that is bought and sold widely.","zh":"「a very important commodity」是被廣泛買賣且有價值的材料或產品。"},{"en":"Rice is a very important commodity in many Asian economies.","zh":"稻米在許多亞洲經濟體中是非常重要的商品。"},{"en":"If factories need a material for many products, it can become an important commodity.","zh":"如果工廠需要某材料製造許多產品，它可以成為重要商品。"},{"en":"The phrase describes economic value and wide demand.","zh":"這個短語描述經濟價值和廣泛需求。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":1},{"front":"particularly in the fields of","meaning":"尤其在……範疇","examples":[{"en":"Rubber was important, particularly in the fields of transportation and electricity.","zh":"橡膠很重要，尤其在交通運輸和電力範疇。"},{"en":"Particularly in the fields of means especially in certain areas of work, study, or industry.","zh":"「particularly in the fields of」意思是尤其在某些工作、研究或產業範疇。"},{"en":"English is useful, particularly in the fields of tourism and international business.","zh":"英語很有用，尤其在旅遊和國際商業範疇。"},{"en":"If a material solves problems in key industries, it may become valuable there first.","zh":"如果一種材料能解決關鍵產業中的問題，它可能先在那些範疇變得有價值。"},{"en":"The phrase narrows a general point to specific fields.","zh":"這個短語把一般觀點收窄到特定範疇。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":1},{"front":"transportation and electricity","meaning":"交通運輸和電力","examples":[{"en":"Rubber was widely used in transportation and electricity.","zh":"橡膠廣泛用於交通運輸和電力。"},{"en":"Transportation and electricity refer to moving people or goods and supplying electrical power.","zh":"「transportation and electricity」指移動人或貨物，以及供應電力。"},{"en":"A city depends on transportation and electricity to keep schools, shops, and hospitals running.","zh":"城市依賴交通運輸和電力，讓學校、商店和醫院運作。"},{"en":"Rubber helped transport by supporting tyres and helped electricity by acting as insulation.","zh":"橡膠透過支援輪胎幫助交通，也透過作為絕緣材料幫助電力。"},{"en":"The phrase names two major modern industries.","zh":"這個短語指出兩個主要現代產業。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":1},{"front":"synthetic materials","meaning":"合成材料","examples":[{"en":"Plastics are synthetic materials that replaced natural rubber in many uses.","zh":"塑膠是合成材料，在許多用途上取代了天然橡膠。"},{"en":"Synthetic materials are materials made by chemical processes rather than taken directly from nature.","zh":"「synthetic materials」是透過化學過程製成，而不是直接取自自然的材料。"},{"en":"Polyester is a synthetic material often used in clothing.","zh":"聚酯是一種常用於衣物的合成材料。"},{"en":"If synthetic materials are cheaper or easier to shape, they may replace natural materials.","zh":"如果合成材料更便宜或更容易塑形，它們可能取代天然材料。"},{"en":"The phrase contrasts manufactured materials with natural ones.","zh":"這個短語把人造材料與天然材料作對比。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":1},{"front":"superseded natural rubber","meaning":"取代天然橡膠","examples":[{"en":"New synthetic materials superseded natural rubber in most applications.","zh":"新合成材料在大多數用途上取代了天然橡膠。"},{"en":"Superseded natural rubber means replaced natural rubber because the newer material became more useful or common.","zh":"「superseded natural rubber」意思是因新材料更有用或更常見而取代天然橡膠。"},{"en":"Digital cameras superseded film cameras for most everyday photography.","zh":"數碼相機在大多數日常攝影中取代了菲林相機。"},{"en":"If a new material performs better, it can supersede an older one in factories.","zh":"如果新材料表現更好，它可以在工廠中取代舊材料。"},{"en":"The phrase describes replacement by a newer alternative.","zh":"這個短語描述被較新的替代品取代。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":1},{"front":"in all but a few applications","meaning":"除少數用途外幾乎所有用途","examples":[{"en":"Plastics superseded natural rubber in all but a few applications.","zh":"除少數用途外，塑膠幾乎在所有用途上取代了天然橡膠。"},{"en":"In all but a few applications means in almost every use, except for a small number.","zh":"「in all but a few applications」意思是在幾乎每一種用途上，只有少數例外。"},{"en":"Online forms have replaced paper forms in all but a few school procedures.","zh":"除少數學校程序外，網上表格幾乎取代了紙本表格。"},{"en":"If a material is useful in nearly every setting, older materials may survive only in special cases.","zh":"如果一種材料在幾乎所有情境中有用，舊材料可能只在特殊情況中保留下來。"},{"en":"The phrase means “almost everywhere, with a few exceptions”.","zh":"這個短語意思是「幾乎到處都是，只有少數例外」。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":1},{"front":"a polymer","meaning":"聚合物","examples":[{"en":"Rubber is a polymer.","zh":"橡膠是一種聚合物。"},{"en":"A polymer is a large molecule made from many smaller repeated units.","zh":"「a polymer」是由許多較小重複單元組成的大分子。"},{"en":"Plastic bags, nylon, and rubber all involve polymers.","zh":"膠袋、尼龍和橡膠都涉及聚合物。"},{"en":"When small units join together repeatedly, they can form a polymer with new properties.","zh":"當小單元反覆連接，它們可以形成具有新特性的聚合物。"},{"en":"The word is central to understanding plastics.","zh":"這個詞是理解塑膠的核心。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":1},{"front":"a compound containing","meaning":"含有……的化合物","examples":[{"en":"A polymer is a compound containing large molecules.","zh":"聚合物是一種含有大分子的化合物。"},{"en":"A compound containing something is a substance that has that thing as part of its structure.","zh":"「a compound containing」某物，是結構中具有該物質的化合物。"},{"en":"Water is a compound containing hydrogen and oxygen.","zh":"水是含有氫和氧的化合物。"},{"en":"If a compound contains large molecules, its physical properties may differ from smaller substances.","zh":"如果化合物含有大分子，其物理特性可能不同於較小物質。"},{"en":"The phrase describes chemical composition.","zh":"這個短語描述化學組成。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":2},{"front":"large molecules","meaning":"大分子","examples":[{"en":"Polymers contain large molecules formed from smaller units.","zh":"聚合物含有由較小單元形成的大分子。"},{"en":"Large molecules are molecules made of many atoms joined together.","zh":"「large molecules」是由許多原子連接而成的分子。"},{"en":"Proteins in food are large molecules that the body breaks down during digestion.","zh":"食物中的蛋白質是大分子，身體會在消化時分解它們。"},{"en":"If molecules are large and chain-like, the material may become strong or flexible.","zh":"如果分子很大且呈鏈狀，材料可能變得堅固或有彈性。"},{"en":"The phrase describes molecular size.","zh":"這個短語描述分子大小。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":2},{"front":"formed by the bonding of","meaning":"由……結合而成","examples":[{"en":"Large molecules are formed by the bonding of many smaller units.","zh":"大分子由許多較小單元結合而成。"},{"en":"Formed by the bonding of means created when parts join together chemically.","zh":"「formed by the bonding of」意思是當部分以化學方式連接時形成。"},{"en":"A chain is formed by the linking of many small metal rings.","zh":"鏈條由許多細小金屬環連接而成。"},{"en":"When small chemical units bond repeatedly, a much larger molecule can result.","zh":"當小化學單元反覆結合，就可以形成更大的分子。"},{"en":"The phrase explains how a larger structure is created.","zh":"這個短語解釋較大結構如何形成。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":2},{"front":"smaller, simpler units","meaning":"較小、較簡單的單元","examples":[{"en":"A polymer is made from many smaller, simpler units.","zh":"聚合物由許多較小、較簡單的單元製成。"},{"en":"Smaller, simpler units are basic parts that join together to form something larger.","zh":"「smaller, simpler units」是連接起來形成較大物體的基本部分。"},{"en":"A sentence is made from smaller, simpler units such as words and phrases.","zh":"句子由詞語和短語等較小、較簡單的單元組成。"},{"en":"If small units repeat many times, they can create a complex material.","zh":"如果小單元重複很多次，它們可以形成複雜材料。"},{"en":"The phrase describes building blocks.","zh":"這個短語描述基本構成單位。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":2},{"front":"repeated over and over again","meaning":"反覆重複","examples":[{"en":"The same small units are repeated over and over again.","zh":"相同的小單元反覆重複。"},{"en":"Repeated over and over again means done or appearing many times in the same pattern.","zh":"「repeated over and over again」意思是以同一模式多次進行或出現。"},{"en":"A song becomes easy to remember when the chorus is repeated over and over again.","zh":"當副歌反覆重複，歌曲就容易記住。"},{"en":"In polymers, repeated units form long chains with useful properties.","zh":"在聚合物中，重複單元形成具有有用特性的長鏈。"},{"en":"The phrase stresses repetition.","zh":"這個短語強調重複。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":2},{"front":"bonding principle","meaning":"結合原理","examples":[{"en":"The same bonding principle underlies the creation of many plastics.","zh":"相同的結合原理是許多塑膠產生的基礎。"},{"en":"A bonding principle is the basic idea of how smaller units join together.","zh":"「bonding principle」是較小單元如何連接起來的基本概念。"},{"en":"In class, students may learn the bonding principle by building models with connecting blocks.","zh":"在課堂上，學生可能透過用積木連接模型來學習結合原理。"},{"en":"If the bonding principle changes, the final material may have different properties.","zh":"如果結合原理改變，最終材料可能有不同特性。"},{"en":"The phrase describes the chemical logic behind polymer formation.","zh":"這個短語描述聚合物形成背後的化學邏輯。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":2},{"front":"polymerisation","meaning":"聚合作用；聚合反應","examples":[{"en":"Polymerisation underlies the creation of a huge range of plastics.","zh":"聚合作用是各式各樣塑膠產生的基礎。"},{"en":"Polymerisation is the chemical process in which small molecules join to form polymers.","zh":"「polymerisation」是小分子連接形成聚合物的化學過程。"},{"en":"A chemistry teacher may compare polymerisation to linking many paper clips into a long chain.","zh":"化學老師可能把聚合作用比作把許多萬字夾連成長鏈。"},{"en":"When polymerisation is controlled, manufacturers can create plastics with different properties.","zh":"當聚合反應受到控制，製造商可以創造具有不同特性的塑膠。"},{"en":"The word names the key process behind many plastics.","zh":"這個詞指出許多塑膠背後的關鍵過程。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":2},{"front":"underlies the creation of","meaning":"是……產生的基礎","examples":[{"en":"Polymerisation underlies the creation of many modern plastics.","zh":"聚合作用是許多現代塑膠產生的基礎。"},{"en":"To underlie the creation of something means to be the basic process or principle behind it.","zh":"「underlies the creation of」某物，意思是成為其背後的基本過程或原理。"},{"en":"Clear planning underlies the creation of a successful school event.","zh":"清晰規劃是成功學校活動產生的基礎。"},{"en":"If polymerisation underlies plastic production, understanding it helps explain many plastic types.","zh":"如果聚合作用是塑膠生產的基礎，理解它有助解釋許多塑膠類型。"},{"en":"The phrase points to the foundation of how something is made.","zh":"這個短語指出某物如何製成的基礎。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":2},{"front":"a huge range of","meaning":"各式各樣的","examples":[{"en":"The chemical industry created a huge range of plastics.","zh":"化學工業創造了各式各樣的塑膠。"},{"en":"A huge range of something means many different types of it.","zh":"「a huge range of」某物，意思是很多不同種類的它。"},{"en":"A supermarket sells a huge range of snacks, drinks, and household products.","zh":"超級市場出售各式各樣的小食、飲品和家居用品。"},{"en":"If a material can be changed easily, manufacturers can create many versions of it.","zh":"如果材料容易改變，製造商可以創造許多版本。"},{"en":"The phrase emphasises variety.","zh":"這個短語強調多樣性。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":2},{"front":"the chemical industry","meaning":"化學工業","examples":[{"en":"The chemical industry developed many kinds of plastic.","zh":"化學工業發展出許多種類的塑膠。"},{"en":"The chemical industry is the business sector that produces chemicals and chemical-based materials.","zh":"「the chemical industry」是生產化學品和化學基礎材料的商業部門。"},{"en":"The chemical industry makes products used in medicine, farming, cleaning, and manufacturing.","zh":"化學工業製造用於醫藥、農業、清潔和製造業的產品。"},{"en":"When the chemical industry finds a new process, many new materials may follow.","zh":"當化學工業找到新過程，許多新材料可能隨之出現。"},{"en":"The phrase refers to factories, companies, and research linked to chemicals.","zh":"這個短語指與化學品相關的工廠、公司和研究。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":2},{"front":"as a result of","meaning":"由於；作為……的結果","examples":[{"en":"The first plastic was developed as a result of a competition.","zh":"第一種塑膠是由於一場比賽而發展出來的。"},{"en":"As a result of means because of or caused by something.","zh":"「as a result of」意思是由於或作為某事的結果。"},{"en":"The school closed early as a result of the typhoon warning.","zh":"由於颱風警告，學校提早關閉。"},{"en":"If a competition offers a useful prize, inventors may create new solutions as a result.","zh":"如果比賽提供有用獎金，發明家可能因此創造新解決方案。"},{"en":"The phrase links a cause with its outcome.","zh":"這個短語把原因與結果連繫起來。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":2},{"front":"was offered to anybody who could","meaning":"提供給任何能夠……的人","examples":[{"en":"A prize was offered to anybody who could replace ivory.","zh":"獎項提供給任何能夠取代象牙的人。"},{"en":"Was offered to anybody who could means was made available to any person able to do a particular task.","zh":"「was offered to anybody who could」意思是提供給任何能完成特定任務的人。"},{"en":"A scholarship was offered to anybody who could design a useful recycling project.","zh":"獎學金提供給任何能設計有用回收項目的人。"},{"en":"If a reward is open to anybody who can solve a problem, many inventors may try.","zh":"如果獎賞向任何能解決問題的人開放，許多發明家可能會嘗試。"},{"en":"The phrase describes an open challenge.","zh":"這個短語描述公開挑戰。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":3},{"front":"replace ivory","meaning":"取代象牙","examples":[{"en":"The competition asked inventors to replace ivory with another material.","zh":"比賽要求發明家用另一種材料取代象牙。"},{"en":"To replace ivory means to use another material instead of ivory.","zh":"「replace ivory」意思是使用另一種材料代替象牙。"},{"en":"A restaurant may replace plastic straws with paper ones to reduce waste.","zh":"餐廳可能用紙飲管取代塑膠飲管以減少廢物。"},{"en":"If ivory supplies decline, manufacturers need a substitute material.","zh":"如果象牙供應下降，製造商需要替代材料。"},{"en":"The phrase describes finding an alternative to ivory.","zh":"這個短語描述尋找象牙的替代品。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":3},{"front":"supplies of which were declining","meaning":"……的供應正在減少","examples":[{"en":"Ivory was used less because supplies of it were declining.","zh":"由於象牙供應正在減少，象牙使用減少。"},{"en":"Supplies of which were declining means the available amount of that material was becoming smaller.","zh":"「supplies of which were declining」意思是該材料可用數量正在變少。"},{"en":"A café may change its menu if supplies of fresh fruit are declining.","zh":"如果新鮮水果供應減少，咖啡店可能改變餐牌。"},{"en":"When supplies decline, prices may rise and alternatives become attractive.","zh":"當供應減少，價格可能上升，替代品就變得吸引。"},{"en":"The phrase explains why people searched for a replacement.","zh":"這個短語解釋人們為何尋找替代品。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":3},{"front":"equally good as","meaning":"與……同樣好","examples":[{"en":"The new material had to be equally good as ivory.","zh":"新材料必須與象牙同樣好。"},{"en":"Equally good as means having the same quality or usefulness as something else.","zh":"「equally good as」意思是與另一物有相同質素或用途。"},{"en":"A cheaper notebook can be equally good as an expensive one if the paper is strong.","zh":"如果紙張堅韌，較便宜的筆記本可以與昂貴筆記本同樣好。"},{"en":"If a substitute is not equally good, manufacturers may not accept it.","zh":"如果替代品不夠好，製造商可能不接受它。"},{"en":"The phrase compares quality directly.","zh":"這個短語直接比較質素。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":3},{"front":"a material for making","meaning":"用作製造……的材料","examples":[{"en":"Ivory was used as a material for making billiard balls.","zh":"象牙被用作製造桌球用球的材料。"},{"en":"A material for making something is a substance used to produce that object.","zh":"「a material for making」某物，是用來生產該物件的物質。"},{"en":"Wood is a common material for making desks and chairs.","zh":"木材是製造書桌和椅子的常見材料。"},{"en":"If the usual material becomes rare, manufacturers must find another one.","zh":"如果常用材料變得稀少，製造商必須尋找另一種。"},{"en":"The phrase connects raw material with the product made from it.","zh":"這個短語把原材料與由它製成的產品連繫起來。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":3},{"front":"billiard balls","meaning":"桌球用球","examples":[{"en":"The competition required a new material for making billiard balls.","zh":"該比賽要求一種用來製造桌球用球的新材料。"},{"en":"Billiard balls are hard balls used in billiards or pool games.","zh":"「billiard balls」是用於桌球或美式桌球遊戲的硬球。"},{"en":"A sports club may replace damaged billiard balls before a tournament.","zh":"體育會可能在比賽前更換受損桌球用球。"},{"en":"If billiard balls need to be smooth and strong, the material must be carefully chosen.","zh":"如果桌球用球需要光滑而堅硬，材料就必須仔細選擇。"},{"en":"The phrase names the product that first encouraged the search for plastic.","zh":"這個短語指出最初促使人們尋找塑膠的產品。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":3},{"front":"the prize was won by","meaning":"獎項由……贏得","examples":[{"en":"The prize was won by John Wesley Hyatt.","zh":"獎項由 John Wesley Hyatt 贏得。"},{"en":"The prize was won by someone means that person succeeded in the competition.","zh":"「the prize was won by」某人，意思是該人在比賽中勝出。"},{"en":"The school science prize was won by a student who built a water-saving device.","zh":"學校科學獎由一名製作節水裝置的學生贏得。"},{"en":"If a prize is won by an inventor, their solution may become famous.","zh":"如果獎項由發明家贏得，他的解決方案可能成名。"},{"en":"The phrase identifies the winner.","zh":"這個短語指出勝出者。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":3},{"front":"a material called celluloid","meaning":"一種名為賽璐珞的材料","examples":[{"en":"John Wesley Hyatt won the prize with a material called celluloid.","zh":"John Wesley Hyatt 憑一種名為賽璐珞的材料贏得獎項。"},{"en":"A material called celluloid means a substance named celluloid.","zh":"「a material called celluloid」意思是一種名為 celluloid 的物質。"},{"en":"A student may present a project using a material called bioplastic.","zh":"學生可能展示使用一種名為生物塑膠的材料的項目。"},{"en":"If a new material solves an old problem, its name can become historically important.","zh":"如果新材料解決舊問題，它的名字可能變得具有歷史重要性。"},{"en":"The phrase introduces the name of a material.","zh":"這個短語引入材料名稱。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":3},{"front":"celluloid","meaning":"賽璐珞","examples":[{"en":"Celluloid was the first plastic.","zh":"賽璐珞是第一種塑膠。"},{"en":"Celluloid is an early plastic made from cellulose and other chemicals.","zh":"「celluloid」是一種由纖維素和其他化學物質製成的早期塑膠。"},{"en":"Old photographic film and spectacle frames were once made with celluloid.","zh":"舊攝影菲林和眼鏡框曾經用賽璐珞製成。"},{"en":"Because celluloid could be softened by heat, it could be shaped into many products.","zh":"因為賽璐珞可以受熱軟化，它能被塑造成許多產品。"},{"en":"The word names the first major plastic material in the passage.","zh":"這個詞指出文章中的第一種主要塑膠材料。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":3},{"front":"was made by dissolving","meaning":"通過溶解……製成","examples":[{"en":"Celluloid was made by dissolving cellulose in a solution.","zh":"賽璐珞通過把纖維素溶解在溶液中製成。"},{"en":"Was made by dissolving means was produced by mixing something into a liquid until it spread through it.","zh":"「was made by dissolving」意思是透過把某物混入液體直至溶入其中來製成。"},{"en":"Lemon tea can be made by dissolving sugar in hot water.","zh":"檸檬茶可以透過把糖溶解在熱水中製成。"},{"en":"When cellulose was dissolved in chemicals, it could be turned into a new material.","zh":"當纖維素被溶解於化學物質中，它可以被轉化成新材料。"},{"en":"The phrase describes a production method.","zh":"這個短語描述生產方法。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":3},{"front":"cellulose","meaning":"纖維素","examples":[{"en":"Cellulose is a carbohydrate derived from plants.","zh":"纖維素是源自植物的碳水化合物。"},{"en":"Cellulose is a natural substance found in plant cell walls.","zh":"「cellulose」是存在於植物細胞壁中的天然物質。"},{"en":"Paper contains cellulose because it is made from plant fibres.","zh":"紙含有纖維素，因為它由植物纖維製成。"},{"en":"If cellulose is chemically treated, it can be used to make materials such as celluloid.","zh":"如果纖維素經化學處理，它可以用來製造賽璐珞等材料。"},{"en":"The word names a plant-based starting material.","zh":"這個詞指出一種植物來源的起始材料。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":3},{"front":"a carbohydrate derived from plants","meaning":"源自植物的碳水化合物","examples":[{"en":"Cellulose is a carbohydrate derived from plants.","zh":"纖維素是源自植物的碳水化合物。"},{"en":"A carbohydrate derived from plants is a plant-based chemical made of carbon, hydrogen, and oxygen.","zh":"「a carbohydrate derived from plants」是由碳、氫和氧組成的植物來源化學物。"},{"en":"Starch is another carbohydrate derived from plants.","zh":"澱粉也是另一種源自植物的碳水化合物。"},{"en":"If a material comes from plants, it may still be transformed by chemical processes.","zh":"如果材料來自植物，它仍可以透過化學過程被轉化。"},{"en":"The phrase describes the origin and type of cellulose.","zh":"這個短語描述纖維素的來源和類型。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":4},{"front":"in a solution of","meaning":"在……溶液中","examples":[{"en":"Cellulose was dissolved in a solution of camphor and ethanol.","zh":"纖維素被溶解在樟腦和乙醇溶液中。"},{"en":"In a solution of means in a liquid mixture containing certain substances.","zh":"「in a solution of」意思是在含有某些物質的液體混合物中。"},{"en":"A contact lens may be stored in a solution of cleaning chemicals and water.","zh":"隱形眼鏡可能存放在清潔化學品和水的溶液中。"},{"en":"If a substance dissolves in a solution, it spreads evenly through the liquid.","zh":"如果某物溶於溶液中，它會均勻分散於液體中。"},{"en":"The phrase describes the liquid used in a chemical process.","zh":"這個短語描述化學過程中使用的液體。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":4},{"front":"camphor","meaning":"樟腦","examples":[{"en":"Camphor was dissolved in ethanol to help make celluloid.","zh":"樟腦溶於乙醇，以幫助製造賽璐珞。"},{"en":"Camphor is a strong-smelling substance often obtained from certain trees or made synthetically.","zh":"「camphor」是一種氣味強烈的物質，常取自某些樹木或人工合成。"},{"en":"Some traditional products use camphor because of its sharp smell.","zh":"有些傳統產品因樟腦的刺鼻氣味而使用它。"},{"en":"In celluloid production, camphor helped modify the cellulose mixture.","zh":"在賽璐珞生產中，樟腦有助改變纖維素混合物。"},{"en":"The word names one chemical ingredient in celluloid.","zh":"這個詞指出賽璐珞中的一種化學成分。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":4},{"front":"dissolved in ethanol","meaning":"溶於乙醇","examples":[{"en":"Camphor was dissolved in ethanol.","zh":"樟腦溶於乙醇。"},{"en":"Dissolved in ethanol means mixed into ethanol until it became part of the liquid solution.","zh":"「dissolved in ethanol」意思是混入乙醇中，直到成為液體溶液的一部分。"},{"en":"Some laboratory samples are dissolved in alcohol before testing.","zh":"有些實驗室樣本在測試前會溶於酒精。"},{"en":"If a substance dissolves in ethanol, it can be combined more evenly with other chemicals.","zh":"如果物質溶於乙醇，它可以更均勻地與其他化學品結合。"},{"en":"The phrase describes a chemical mixing step.","zh":"這個短語描述化學混合步驟。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":4},{"front":"rapidly found uses in","meaning":"很快在……方面有用途","examples":[{"en":"Celluloid rapidly found uses in the manufacture of many products.","zh":"賽璐珞很快在許多產品製造方面有用途。"},{"en":"Rapidly found uses in means quickly began to be used for particular purposes.","zh":"「rapidly found uses in」意思是很快開始被用於特定目的。"},{"en":"Smartphones rapidly found uses in banking, learning, and transport.","zh":"智能電話很快在銀行、學習和交通方面有用途。"},{"en":"If a material is easy to shape, factories may quickly find uses for it.","zh":"如果材料容易塑形，工廠可能很快找到其用途。"},{"en":"The phrase shows quick practical adoption.","zh":"這個短語顯示快速實際採用。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":4},{"front":"the manufacture of products","meaning":"產品製造","examples":[{"en":"Celluloid was used in the manufacture of several products.","zh":"賽璐珞被用於幾種產品製造。"},{"en":"The manufacture of products means the process of making goods in factories or workshops.","zh":"「the manufacture of products」指在工廠或工場製造商品的過程。"},{"en":"The manufacture of furniture requires wood, tools, labour, and design.","zh":"家具製造需要木材、工具、勞力和設計。"},{"en":"If a material is useful in manufacturing, it may become commercially important.","zh":"如果材料在製造中有用，它可能變得有商業重要性。"},{"en":"The phrase focuses on production, not just design.","zh":"這個短語集中於生產，而不只是設計。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":4},{"front":"knife handles","meaning":"刀柄","examples":[{"en":"Celluloid was used to make knife handles.","zh":"賽璐珞被用來製造刀柄。"},{"en":"Knife handles are the parts of knives that people hold.","zh":"「knife handles」是人們握住刀子的部分。"},{"en":"A good knife handle should be strong, comfortable, and safe to grip.","zh":"好刀柄應堅固、舒適並容易安全握住。"},{"en":"If a material can be shaped and polished, it may be suitable for handles.","zh":"如果材料可以塑形和拋光，它可能適合製作手柄。"},{"en":"The phrase names one everyday product part made from early plastic.","zh":"這個短語指出早期塑膠製成的一種日常產品部分。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":4},{"front":"detachable collars and cuffs","meaning":"可拆式衣領和袖口","examples":[{"en":"Celluloid was used to make detachable collars and cuffs.","zh":"賽璐珞被用來製造可拆式衣領和袖口。"},{"en":"Detachable collars and cuffs are shirt parts that can be removed and attached again.","zh":"「detachable collars and cuffs」是可以拆下再裝回的恤衫部分。"},{"en":"In the past, detachable collars helped people keep shirts looking clean for longer.","zh":"過去，可拆式衣領幫助人們讓恤衫看起來更長時間保持乾淨。"},{"en":"If clothing parts are detachable, they can be washed or replaced separately.","zh":"如果衣物部分可拆，它們可以分開清洗或更換。"},{"en":"The phrase describes removable clothing accessories.","zh":"這個短語描述可移除的衣物配件。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":4},{"front":"spectacle frames","meaning":"眼鏡框","examples":[{"en":"Celluloid was used to make spectacle frames.","zh":"賽璐珞被用來製造眼鏡框。"},{"en":"Spectacle frames are the parts of glasses that hold the lenses and sit on the face.","zh":"「spectacle frames」是眼鏡中固定鏡片並戴在臉上的部分。"},{"en":"A student may choose lighter spectacle frames for everyday comfort.","zh":"學生可能選擇較輕的眼鏡框，以便日常佩戴更舒服。"},{"en":"If a material is light and shapeable, it can be useful for spectacle frames.","zh":"如果材料輕而可塑形，它可以用於眼鏡框。"},{"en":"The phrase names a common personal item.","zh":"這個短語指出常見個人物品。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":4},{"front":"photographic film","meaning":"攝影菲林","examples":[{"en":"Celluloid became important in the production of photographic film.","zh":"賽璐珞在攝影菲林生產中變得重要。"},{"en":"Photographic film is a light-sensitive material used to record images in cameras.","zh":"「photographic film」是用於相機記錄影像的感光材料。"},{"en":"Before digital cameras, families often used photographic film to take holiday pictures.","zh":"在數碼相機之前，家庭常使用攝影菲林拍旅行照片。"},{"en":"If film is flexible and transparent, it can pass through a camera and capture images.","zh":"如果菲林柔韌而透明，它可以穿過相機並捕捉影像。"},{"en":"The phrase refers to the material that helped early photography and cinema.","zh":"這個短語指幫助早期攝影和電影的材料。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":4},{"front":"the film industry","meaning":"電影業","examples":[{"en":"The film industry could not have developed in the same way without celluloid.","zh":"沒有賽璐珞，電影業不可能以同樣方式發展。"},{"en":"The film industry is the business of making, distributing, and showing films.","zh":"「the film industry」是製作、發行和放映電影的行業。"},{"en":"The film industry includes directors, actors, cinemas, studios, and technicians.","zh":"電影業包括導演、演員、戲院、片廠和技術人員。"},{"en":"If celluloid had not existed, early cinema technology would have developed differently.","zh":"如果賽璐珞不存在，早期電影技術會以不同方式發展。"},{"en":"The phrase refers to cinema as a whole industry.","zh":"這個短語指整個電影產業。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":4},{"front":"got off the ground","meaning":"起步；開始發展","examples":[{"en":"Without celluloid, the film industry could never have got off the ground.","zh":"沒有賽璐珞，電影業可能永遠無法起步。"},{"en":"To get off the ground means to begin successfully.","zh":"「get off the ground」意思是成功開始。"},{"en":"A school club may not get off the ground if no teacher agrees to supervise it.","zh":"如果沒有老師同意監督，學校社團可能無法開始發展。"},{"en":"If a new industry lacks the right material, it may fail before it starts.","zh":"如果新產業缺乏合適材料，它可能在開始前已失敗。"},{"en":"The phrase describes the successful beginning of a project or activity.","zh":"這個短語描述項目或活動成功開始。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":5},{"front":"at the end of the 19th century","meaning":"在十九世紀末","examples":[{"en":"The film industry began to develop at the end of the 19th century.","zh":"電影業在十九世紀末開始發展。"},{"en":"At the end of the 19th century means in the late 1800s.","zh":"「at the end of the 19th century」意思是在1800年代末期。"},{"en":"Many modern cities expanded at the end of the 19th century.","zh":"許多現代城市在十九世紀末擴展。"},{"en":"If an invention appeared at the end of a century, it may shape the next one.","zh":"如果一項發明在一個世紀末出現，它可能塑造下一個世紀。"},{"en":"The phrase gives a historical time point.","zh":"這個短語提供歷史時間點。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":5},{"front":"repeatedly softened and reshaped","meaning":"反覆軟化並重新塑形","examples":[{"en":"Celluloid can be repeatedly softened and reshaped by heat.","zh":"賽璐珞可以透過加熱反覆軟化並重新塑形。"},{"en":"Repeatedly softened and reshaped means made soft and formed into new shapes many times.","zh":"「repeatedly softened and reshaped」意思是多次被弄軟並形成新形狀。"},{"en":"Wax can be repeatedly softened and reshaped when warmed.","zh":"蠟加熱後可以反覆軟化並重新塑形。"},{"en":"If a plastic can be softened again, manufacturers can reform it into different objects.","zh":"如果塑膠可以再次軟化，製造商就能把它重新塑造成不同物件。"},{"en":"The phrase describes a key feature of thermoplastics.","zh":"這個短語描述熱塑性塑膠的關鍵特徵。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":5},{"front":"by heat","meaning":"透過加熱","examples":[{"en":"Celluloid can be softened and reshaped by heat.","zh":"賽璐珞可以透過加熱軟化並重新塑形。"},{"en":"By heat means using heat as the method or cause.","zh":"「by heat」意思是以熱力作為方法或原因。"},{"en":"Butter can be softened by heat when it is placed near a warm pan.","zh":"牛油放在熱鍋附近時可以透過加熱軟化。"},{"en":"If a material changes by heat, temperature can control its shape.","zh":"如果材料會透過加熱改變，溫度就可以控制其形狀。"},{"en":"The phrase explains the method used to produce a change.","zh":"這個短語解釋產生變化的方法。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":5},{"front":"is known as","meaning":"被稱為","examples":[{"en":"Celluloid is known as a thermoplastic.","zh":"賽璐珞被稱為熱塑性塑膠。"},{"en":"Is known as means is called by a particular name.","zh":"「is known as」意思是被某個名稱稱呼。"},{"en":"Hong Kong is known as a busy international city.","zh":"香港被稱為繁忙的國際城市。"},{"en":"If a material is known as a thermoplastic, it has properties linked to heat shaping.","zh":"如果一種材料被稱為熱塑性塑膠，它具有與受熱塑形相關的特性。"},{"en":"The phrase introduces a name or label.","zh":"這個短語引入名稱或標籤。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":5},{"front":"a thermoplastic","meaning":"熱塑性塑膠","examples":[{"en":"Celluloid is known as a thermoplastic.","zh":"賽璐珞被稱為熱塑性塑膠。"},{"en":"A thermoplastic is a plastic that can be softened by heat and reshaped.","zh":"「a thermoplastic」是一種可透過加熱軟化並重新塑形的塑膠。"},{"en":"Many plastic containers are made from thermoplastics that can be moulded in factories.","zh":"許多塑膠容器由可在工廠模塑的熱塑性塑膠製成。"},{"en":"If a thermoplastic is heated, it can become soft enough to form a new shape.","zh":"如果熱塑性塑膠被加熱，它可以變得足夠柔軟以形成新形狀。"},{"en":"The phrase contrasts with thermosets, which cannot be reshaped after setting.","zh":"這個短語與凝固後不能再塑形的熱固性塑膠形成對比。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":5},{"front":"a Belgian chemist","meaning":"比利時化學家","examples":[{"en":"Leo Baekeland was a Belgian chemist working in the USA.","zh":"Leo Baekeland 是一位在美國工作的比利時化學家。"},{"en":"A Belgian chemist is a scientist from Belgium who studies chemicals.","zh":"「a Belgian chemist」是來自比利時、研究化學物質的科學家。"},{"en":"A chemist may develop new materials, medicines, or industrial processes.","zh":"化學家可能研發新材料、藥物或工業過程。"},{"en":"If a chemist invents a new plastic, manufacturing methods may change.","zh":"如果化學家發明新塑膠，製造方法可能改變。"},{"en":"The phrase identifies Baekeland’s nationality and profession.","zh":"這個短語指出 Baekeland 的國籍和職業。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":5},{"front":"invented a different kind of plastic","meaning":"發明另一種塑膠","examples":[{"en":"Leo Baekeland invented a different kind of plastic in 1907.","zh":"Leo Baekeland 在1907年發明另一種塑膠。"},{"en":"Invented a different kind of plastic means created a new plastic with different properties.","zh":"「invented a different kind of plastic」意思是創造一種具有不同特性的新塑膠。"},{"en":"A company may invent a different kind of packaging that breaks down more easily.","zh":"公司可能發明另一種更容易分解的包裝材料。"},{"en":"If a new plastic behaves differently under heat, it can be used in new ways.","zh":"如果新塑膠在受熱時有不同行為，它可以有新用途。"},{"en":"The phrase marks a new stage in plastic development.","zh":"這個短語標誌塑膠發展的新階段。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":5},{"front":"react together","meaning":"一起發生反應","examples":[{"en":"Phenol and formaldehyde react together to form Bakelite.","zh":"酚和甲醛一起發生反應，形成電木。"},{"en":"React together means two or more substances chemically interact and produce something new.","zh":"「react together」意思是兩種或以上物質發生化學互動並產生新物質。"},{"en":"Vinegar and baking soda react together and produce bubbles.","zh":"醋和梳打粉一起發生反應並產生氣泡。"},{"en":"When chemicals react together under the right conditions, a new material can form.","zh":"當化學物質在適當條件下一起反應，新材料可以形成。"},{"en":"The phrase describes chemical interaction.","zh":"這個短語描述化學互動。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":5},{"front":"phenol and formaldehyde","meaning":"酚和甲醛","examples":[{"en":"Baekeland caused phenol and formaldehyde to react together.","zh":"Baekeland 使酚和甲醛一起發生反應。"},{"en":"Phenol and formaldehyde are chemicals that were used to make Bakelite.","zh":"「phenol and formaldehyde」是用來製造電木的化學物質。"},{"en":"A chemistry textbook may list phenol and formaldehyde as starting substances in a reaction.","zh":"化學課本可能把酚和甲醛列為反應中的起始物質。"},{"en":"When these chemicals react, they can form a hard plastic material.","zh":"當這些化學物質發生反應，它們可以形成硬質塑膠材料。"},{"en":"The phrase names the chemicals behind Bakelite.","zh":"這個短語指出電木背後的化學物質。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":5},{"front":"Bakelite","meaning":"電木；酚醛塑膠","examples":[{"en":"Bakelite was the first of the thermosets.","zh":"電木是首種熱固性塑膠。"},{"en":"Bakelite is an early hard plastic that sets permanently after being moulded.","zh":"「Bakelite」是一種早期硬質塑膠，模塑後會永久凝固。"},{"en":"Old radios, switches, and household handles were often made from Bakelite.","zh":"舊收音機、電掣和家居手柄常用電木製成。"},{"en":"Because Bakelite resisted heat and electricity, it became useful in electrical products.","zh":"因為電木耐熱並能絕緣，它在電氣產品中變得有用。"},{"en":"The word names a major early thermosetting plastic.","zh":"這個詞指出一種重要的早期熱固性塑膠。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":5},{"front":"the first of the thermosets","meaning":"首種熱固性塑膠","examples":[{"en":"Bakelite was the first of the thermosets.","zh":"電木是首種熱固性塑膠。"},{"en":"The first of the thermosets means the earliest plastic in the group that sets permanently when heated and moulded.","zh":"「the first of the thermosets」指最早一種受熱和模塑後永久凝固的塑膠。"},{"en":"A textbook may introduce Bakelite as the first example of thermosetting plastics.","zh":"課本可能把電木介紹為熱固性塑膠的第一個例子。"},{"en":"If a plastic sets permanently, it cannot be reshaped like a thermoplastic.","zh":"如果塑膠永久凝固，它就不能像熱塑性塑膠般重新塑形。"},{"en":"The phrase identifies Bakelite’s place in plastic history.","zh":"這個短語指出電木在塑膠歷史中的位置。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":6},{"front":"can be cast and moulded","meaning":"可澆鑄和模塑","examples":[{"en":"Thermosets can be cast and moulded while hot.","zh":"熱固性塑膠可以趁熱澆鑄和模塑。"},{"en":"Can be cast and moulded means can be poured or shaped into a form.","zh":"「can be cast and moulded」意思是可以被倒入模具或塑造成某形狀。"},{"en":"Metal can be cast into a mould to make a statue.","zh":"金屬可以被澆鑄進模具以製造雕像。"},{"en":"If hot plastic can be moulded, factories can shape it into switches or handles.","zh":"如果熱塑膠可以被模塑，工廠可以把它塑造成電掣或手柄。"},{"en":"The phrase describes a manufacturing process.","zh":"這個短語描述製造過程。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":6},{"front":"while hot","meaning":"趁熱時","examples":[{"en":"Thermosets can be moulded while hot.","zh":"熱固性塑膠可以趁熱時模塑。"},{"en":"While hot means during the time when the material is still hot.","zh":"「while hot」意思是在材料仍然熱的期間。"},{"en":"Bread is easier to slice badly while hot because it is still soft.","zh":"麵包趁熱時仍然柔軟，較容易切得不好。"},{"en":"If thermosets are shaped while hot, they harden into that shape afterward.","zh":"如果熱固性塑膠趁熱塑形，它們之後會硬化成該形狀。"},{"en":"The phrase gives the timing of the shaping process.","zh":"這個短語提供塑形過程的時間。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":6},{"front":"cannot be softened by heat","meaning":"不能通過加熱軟化","examples":[{"en":"Bakelite cannot be softened by heat once it has set.","zh":"電木一旦凝固後，不能通過加熱軟化。"},{"en":"Cannot be softened by heat means heat does not make the material flexible again.","zh":"「cannot be softened by heat」意思是熱力不能令材料再次變柔軟。"},{"en":"A baked clay pot cannot be softened by heat in the same way as wax.","zh":"燒製過的陶壺不能像蠟一樣通過加熱軟化。"},{"en":"If a plastic cannot soften again, it keeps its shape under moderate heat.","zh":"如果塑膠不能再次軟化，它在中等熱度下會保持形狀。"},{"en":"The phrase explains a key difference between thermosets and thermoplastics.","zh":"這個短語解釋熱固性塑膠與熱塑性塑膠之間的關鍵差異。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":6},{"front":"once they have set","meaning":"一旦凝固後","examples":[{"en":"Thermosets cannot be reshaped once they have set.","zh":"熱固性塑膠一旦凝固後，不能重新塑形。"},{"en":"Once they have set means after they have hardened into a fixed form.","zh":"「once they have set」意思是它們硬化成固定形態之後。"},{"en":"Jelly cannot be easily poured into a new shape once it has set.","zh":"啫喱一旦凝固後，就不容易倒入新形狀。"},{"en":"If a thermoset has set, heating it again will not return it to a soft state.","zh":"如果熱固性塑膠已凝固，再次加熱也不會令它回到柔軟狀態。"},{"en":"The phrase marks the point after which reshaping is no longer possible.","zh":"這個短語標示之後不能再塑形的時間點。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":6},{"front":"a good insulator","meaning":"良好的絕緣體","examples":[{"en":"Bakelite was a good insulator.","zh":"電木是良好的絕緣體。"},{"en":"A good insulator is a material that does not easily allow heat or electricity to pass through.","zh":"「a good insulator」是不容易讓熱或電通過的材料。"},{"en":"Rubber around an electrical wire acts as a good insulator.","zh":"電線外的橡膠發揮良好絕緣體的作用。"},{"en":"If a material is a good insulator, it can make electrical products safer.","zh":"如果材料是良好的絕緣體，它可以令電氣產品更安全。"},{"en":"The phrase explains why Bakelite was useful in switches and electrical parts.","zh":"這個短語解釋為何電木適用於電掣和電氣零件。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":6},{"front":"resistant to water","meaning":"防水；耐水","examples":[{"en":"Bakelite was resistant to water, acids and moderate heat.","zh":"電木耐水、耐酸和耐中等熱度。"},{"en":"Resistant to water means not easily damaged or affected by water.","zh":"「resistant to water」意思是不容易被水損壞或影響。"},{"en":"A waterproof watch is resistant to water when worn in the rain.","zh":"防水手錶在雨中佩戴時能耐水。"},{"en":"If a material resists water, it can last longer in kitchens and bathrooms.","zh":"如果材料耐水，它可以在廚房和浴室中更耐用。"},{"en":"The phrase describes durability against moisture.","zh":"這個短語描述對水分的耐久性。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":6},{"front":"resistant to acids","meaning":"耐酸","examples":[{"en":"Bakelite was resistant to acids.","zh":"電木耐酸。"},{"en":"Resistant to acids means not easily damaged by acidic substances.","zh":"「resistant to acids」意思是不容易被酸性物質損壞。"},{"en":"A laboratory table may need a surface resistant to acids.","zh":"實驗室桌面可能需要耐酸表面。"},{"en":"If a material resists acids, it can be useful in chemical environments.","zh":"如果材料耐酸，它可以在化學環境中有用。"},{"en":"The phrase describes chemical durability.","zh":"這個短語描述化學耐久性。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":6},{"front":"moderate heat","meaning":"中等熱度","examples":[{"en":"Bakelite was resistant to moderate heat.","zh":"電木耐中等熱度。"},{"en":"Moderate heat means a medium level of heat, not extremely high temperature.","zh":"「moderate heat」意思是中等程度的熱，而不是極高溫度。"},{"en":"A plastic handle should survive moderate heat from a warm pan.","zh":"塑膠手柄應能承受熱鍋帶來的中等熱度。"},{"en":"If a material resists moderate heat, it can be used near electrical parts or cooking tools.","zh":"如果材料耐中等熱度，它可以用於電氣零件或煮食工具附近。"},{"en":"The phrase describes heat that is noticeable but not extreme.","zh":"這個短語描述明顯但不極端的熱。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":6},{"front":"with these properties","meaning":"憑藉這些特性","examples":[{"en":"With these properties, Bakelite was soon used in electrical products.","zh":"憑藉這些特性，電木很快被用於電氣產品。"},{"en":"With these properties means because it had these qualities or features.","zh":"「with these properties」意思是因為它具有這些品質或特徵。"},{"en":"With its light weight and strength, aluminium is useful in aircraft.","zh":"憑藉其輕巧和堅固，鋁可用於飛機。"},{"en":"If a material is strong, waterproof, and insulating, those properties make it commercially useful.","zh":"如果材料堅固、防水又絕緣，這些特性會令它具有商業用途。"},{"en":"The phrase links features with practical use.","zh":"這個短語把特徵與實際用途連繫起來。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":6},{"front":"was soon being used in","meaning":"很快被用於","examples":[{"en":"Bakelite was soon being used in the manufacture of switches.","zh":"電木很快被用於電掣製造。"},{"en":"Was soon being used in means quickly started to be used for a particular purpose.","zh":"「was soon being used in」意思是很快開始被用於特定目的。"},{"en":"A new app was soon being used in schools after teachers found it helpful.","zh":"老師發現新應用程式有用後，它很快被用於學校。"},{"en":"If a material solves safety problems, factories may adopt it quickly.","zh":"如果材料解決安全問題，工廠可能很快採用它。"},{"en":"The phrase describes rapid adoption in production.","zh":"這個短語描述在生產中的快速採用。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":6},{"front":"switches","meaning":"電掣；開關","examples":[{"en":"Bakelite was used in the manufacture of switches.","zh":"電木被用於製造電掣。"},{"en":"Switches are devices used to turn electrical power on or off.","zh":"「switches」是用來開啟或關閉電力的裝置。"},{"en":"A classroom light switch lets students turn the lights on before a lesson.","zh":"課室燈掣讓學生在上課前開燈。"},{"en":"If a switch is made of insulating material, it can be safer to touch.","zh":"如果開關由絕緣材料製成，觸摸時可以更安全。"},{"en":"The word names a common electrical component.","zh":"這個詞指出常見電氣零件。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":7},{"front":"household items","meaning":"家居用品","examples":[{"en":"Bakelite was used to make household items such as knife handles.","zh":"電木被用來製造刀柄等家居用品。"},{"en":"Household items are objects used in the home.","zh":"「household items」是在家中使用的物件。"},{"en":"Cups, switches, bowls, and handles are common household items.","zh":"杯、電掣、碗和手柄都是常見家居用品。"},{"en":"If a plastic is strong and heat-resistant, it can be useful for household items.","zh":"如果塑膠堅固且耐熱，它可以用於家居用品。"},{"en":"The phrase refers to everyday objects used by families.","zh":"這個短語指家庭使用的日常物件。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":7},{"front":"electrical components","meaning":"電氣零件","examples":[{"en":"Bakelite was used to make electrical components for cars.","zh":"電木被用來製造汽車電氣零件。"},{"en":"Electrical components are parts that help carry, control, or protect electricity in a device.","zh":"「electrical components」是幫助在裝置中傳送、控制或保護電力的零件。"},{"en":"A phone charger contains several small electrical components.","zh":"電話充電器含有幾個細小電氣零件。"},{"en":"If components are exposed to heat or current, safe materials are essential.","zh":"如果零件接觸熱力或電流，安全材料十分重要。"},{"en":"The phrase names parts used in electrical systems.","zh":"這個短語指出電力系統中的部件。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":7},{"front":"car components","meaning":"汽車零件","examples":[{"en":"Bakelite was used in car components.","zh":"電木被用於汽車零件。"},{"en":"Car components are parts used to build or operate a car.","zh":"「car components」是用來製造或操作汽車的部件。"},{"en":"Mirrors, switches, handles, and engine parts are car components.","zh":"鏡子、開關、手柄和引擎部件都是汽車零件。"},{"en":"If a material resists heat and electricity, it may be useful in car components.","zh":"如果材料耐熱並絕緣，它可能適用於汽車零件。"},{"en":"The phrase describes vehicle parts.","zh":"這個短語描述車輛部件。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":7},{"front":"began looking for","meaning":"開始尋找","examples":[{"en":"Chemists began looking for other small molecules.","zh":"化學家開始尋找其他小分子。"},{"en":"Began looking for means started searching for something.","zh":"「began looking for」意思是開始搜尋某物。"},{"en":"A student began looking for a quieter place to study after the library became crowded.","zh":"圖書館變得擠迫後，學生開始尋找較安靜的溫習地方。"},{"en":"If scientists find one useful material, they may begin looking for similar materials.","zh":"如果科學家找到一種有用材料，他們可能開始尋找類似材料。"},{"en":"The phrase marks the start of a search.","zh":"這個短語標誌搜尋的開始。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":7},{"front":"small molecules","meaning":"小分子","examples":[{"en":"Chemists looked for small molecules that could be joined together.","zh":"化學家尋找可以連接起來的小分子。"},{"en":"Small molecules are simple chemical units made of relatively few atoms.","zh":"「small molecules」是由相對少數原子組成的簡單化學單元。"},{"en":"Water and oxygen are examples of small molecules.","zh":"水和氧都是小分子的例子。"},{"en":"If small molecules can link together, they may form large polymers.","zh":"如果小分子可以連接起來，它們可能形成大聚合物。"},{"en":"The phrase describes the basic units used to build larger materials.","zh":"這個短語描述用來建構較大材料的基本單元。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":7},{"front":"be strung together","meaning":"被串連起來","examples":[{"en":"Small molecules could be strung together to make polymers.","zh":"小分子可以被串連起來製成聚合物。"},{"en":"To be strung together means to be linked in a chain or sequence.","zh":"「be strung together」意思是被連成鏈或序列。"},{"en":"Beads are strung together to make a necklace.","zh":"珠子被串連起來製成項鏈。"},{"en":"If small molecules are strung together, they can form a long polymer chain.","zh":"如果小分子被串連起來，它們可以形成長聚合物鏈。"},{"en":"The phrase gives a simple image of molecules joining.","zh":"這個短語提供分子連接的簡單圖像。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":7},{"front":"under heat and pressure","meaning":"在高溫和壓力下","examples":[{"en":"Ethylene would polymerise under heat and pressure.","zh":"乙烯會在高溫和壓力下聚合。"},{"en":"Under heat and pressure means when heat and force are applied.","zh":"「under heat and pressure」意思是在施加熱力和壓力時。"},{"en":"Some foods change texture under heat and pressure in a pressure cooker.","zh":"有些食物在壓力煲中的高溫和壓力下會改變質感。"},{"en":"If chemicals react under heat and pressure, new materials may form.","zh":"如果化學物質在高溫和壓力下反應，新材料可能形成。"},{"en":"The phrase describes conditions needed for a process.","zh":"這個短語描述某過程所需條件。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":7},{"front":"polymerise","meaning":"聚合","examples":[{"en":"Ethylene would polymerise under heat and pressure.","zh":"乙烯會在高溫和壓力下聚合。"},{"en":"To polymerise means for small molecules to join together and form a polymer.","zh":"「polymerise」意思是小分子連接起來形成聚合物。"},{"en":"In a chemistry experiment, students may learn how molecules polymerise into long chains.","zh":"在化學實驗中，學生可能學習分子如何聚合成長鏈。"},{"en":"When ethylene polymerises, it becomes polythene.","zh":"當乙烯聚合時，它會變成聚乙烯。"},{"en":"The word describes the action of forming polymers.","zh":"這個詞描述形成聚合物的動作。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":7},{"front":"to form a thermoplastic","meaning":"形成熱塑性塑膠","examples":[{"en":"Ethylene polymerised to form a thermoplastic called polythene.","zh":"乙烯聚合形成一種名為聚乙烯的熱塑性塑膠。"},{"en":"To form a thermoplastic means to create a plastic that can soften when heated and be reshaped.","zh":"「to form a thermoplastic」意思是創造一種受熱可軟化並重新塑形的塑膠。"},{"en":"Small molecules can join to form a useful plastic material.","zh":"小分子可以連接形成有用的塑膠材料。"},{"en":"If the product is a thermoplastic, factories can mould it into bottles or bags.","zh":"如果產物是熱塑性塑膠，工廠可以把它模塑成瓶或袋。"},{"en":"The phrase describes the result of a chemical process.","zh":"這個短語描述化學過程的結果。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":7},{"front":"polythene","meaning":"聚乙烯","examples":[{"en":"British chemists discovered polythene in the 1930s.","zh":"英國化學家在1930年代發現聚乙烯。"},{"en":"Polythene is a common thermoplastic used to make bags, bottles, and packaging.","zh":"「polythene」是一種常見熱塑性塑膠，用於製造袋、瓶和包裝。"},{"en":"Many supermarket bags are made from polythene.","zh":"許多超級市場膠袋由聚乙烯製成。"},{"en":"Because polythene is light and waterproof, it became useful for everyday containers.","zh":"因為聚乙烯輕巧且防水，它成為日常容器的有用材料。"},{"en":"The word names one of the most widely used plastics.","zh":"這個詞指出最廣泛使用的塑膠之一。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":7},{"front":"polypropylene","meaning":"聚丙烯","examples":[{"en":"Polypropylene followed in the 1950s.","zh":"聚丙烯在1950年代隨後出現。"},{"en":"Polypropylene is a plastic related to polythene and used in many everyday products.","zh":"「polypropylene」是一種與聚乙烯相關、用於許多日常產品的塑膠。"},{"en":"Food containers, bottle caps, and packaging may be made from polypropylene.","zh":"食物容器、瓶蓋和包裝可能由聚丙烯製成。"},{"en":"If a plastic is strong and light, manufacturers can use it in many product designs.","zh":"如果塑膠堅固而輕巧，製造商可以把它用於許多產品設計。"},{"en":"The word names another important plastic developed after polythene.","zh":"這個詞指出聚乙烯之後發展出的另一種重要塑膠。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":8},{"front":"were used to make","meaning":"被用來製造","examples":[{"en":"Polythene and polypropylene were used to make bottles, pipes and plastic bags.","zh":"聚乙烯和聚丙烯被用來製造瓶、管和膠袋。"},{"en":"Were used to make means were the materials used for producing something.","zh":"「were used to make」意思是被用作生產某物的材料。"},{"en":"Recycled paper was used to make notebooks for students.","zh":"再造紙被用來製造學生筆記本。"},{"en":"If a material is cheap and easy to shape, it may be used to make many products.","zh":"如果材料便宜又容易塑形，它可能被用來製造許多產品。"},{"en":"The phrase connects material with finished goods.","zh":"這個短語把材料與製成品連繫起來。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":8},{"front":"plastic bags","meaning":"膠袋","examples":[{"en":"Polythene and polypropylene were used to make plastic bags.","zh":"聚乙烯和聚丙烯被用來製造膠袋。"},{"en":"Plastic bags are lightweight bags made from plastic materials.","zh":"「plastic bags」是由塑膠材料製成的輕便袋。"},{"en":"Shoppers may reuse plastic bags to reduce waste.","zh":"購物者可能重用膠袋以減少廢物。"},{"en":"Because plastic bags are light and cheap, they became very common.","zh":"因為膠袋輕巧且便宜，它們變得非常常見。"},{"en":"The phrase names a familiar everyday plastic product.","zh":"這個短語指出熟悉的日常塑膠產品。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":8},{"front":"the starting material","meaning":"起始材料","examples":[{"en":"A small change in the starting material produced PVC.","zh":"起始材料中的一個小變化產生了聚氯乙烯。"},{"en":"The starting material is the original substance used at the beginning of a chemical process.","zh":"「the starting material」是化學過程開始時使用的原始物質。"},{"en":"Flour is the starting material for making bread dough.","zh":"麵粉是製作麵包麵糰的起始材料。"},{"en":"If the starting material changes, the final product may also change.","zh":"如果起始材料改變，最終產品也可能改變。"},{"en":"The phrase identifies what a process begins with.","zh":"這個短語指出過程從甚麼開始。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":8},{"front":"replacing a hydrogen atom with a chlorine atom","meaning":"以氯原子取代氫原子","examples":[{"en":"Replacing a hydrogen atom with a chlorine atom produced PVC.","zh":"以氯原子取代氫原子產生了聚氯乙烯。"},{"en":"Replacing a hydrogen atom with a chlorine atom means taking out hydrogen and putting chlorine in its place.","zh":"「replacing a hydrogen atom with a chlorine atom」意思是移除氫，並把氯放在其位置。"},{"en":"Changing one ingredient in a recipe can create a very different taste.","zh":"改變食譜中的一種材料可以產生非常不同的味道。"},{"en":"In chemistry, a small atomic change can produce a material with new properties.","zh":"在化學中，一個小的原子變化可以產生具有新特性的材料。"},{"en":"The phrase describes the chemical change that led to PVC.","zh":"這個短語描述導致聚氯乙烯出現的化學變化。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":8},{"front":"a hydrogen atom","meaning":"氫原子","examples":[{"en":"A hydrogen atom in ethylene was replaced with a chlorine atom.","zh":"乙烯中的一個氫原子被氯原子取代。"},{"en":"A hydrogen atom is the smallest unit of the chemical element hydrogen.","zh":"「a hydrogen atom」是化學元素氫的最小單位。"},{"en":"Water contains hydrogen atoms and oxygen atoms.","zh":"水含有氫原子和氧原子。"},{"en":"If one hydrogen atom is replaced, a molecule may become a different substance.","zh":"如果一個氫原子被取代，分子可能變成不同物質。"},{"en":"The phrase names a basic chemical unit.","zh":"這個短語指出基本化學單位。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":8},{"front":"a chlorine atom","meaning":"氯原子","examples":[{"en":"A chlorine atom replaced a hydrogen atom in ethylene.","zh":"一個氯原子取代了乙烯中的一個氫原子。"},{"en":"A chlorine atom is the smallest unit of the chemical element chlorine.","zh":"「a chlorine atom」是化學元素氯的最小單位。"},{"en":"Some cleaning products contain chlorine compounds.","zh":"有些清潔產品含有氯化合物。"},{"en":"If chlorine is added to a molecule, the material’s properties may change.","zh":"如果氯加入分子中，材料特性可能改變。"},{"en":"The phrase names the atom added in the formation of PVC.","zh":"這個短語指出形成聚氯乙烯時加入的原子。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":8},{"front":"produced PVC","meaning":"產生聚氯乙烯","examples":[{"en":"A small change in ethylene produced PVC.","zh":"乙烯中的一個小變化產生了聚氯乙烯。"},{"en":"Produced PVC means created polyvinyl chloride through a chemical change.","zh":"「produced PVC」意思是透過化學變化創造聚氯乙烯。"},{"en":"A small change in a recipe can produce a new type of bread.","zh":"食譜中的小變化可以產生新種類的麵包。"},{"en":"If one atom is replaced in the starting material, a different plastic may result.","zh":"如果起始材料中的一個原子被取代，可能會產生不同塑膠。"},{"en":"The phrase describes the result of a chemical modification.","zh":"這個短語描述化學改變的結果。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":8},{"front":"polyvinyl chloride","meaning":"聚氯乙烯","examples":[{"en":"PVC stands for polyvinyl chloride.","zh":"PVC 代表 polyvinyl chloride。"},{"en":"Polyvinyl chloride is the full name of PVC, a plastic used in pipes, drains, and many products.","zh":"「polyvinyl chloride」是 PVC 的完整名稱，是用於管道、排水渠和許多產品的塑膠。"},{"en":"A builder may use polyvinyl chloride pipes for drainage.","zh":"建築工人可能使用聚氯乙烯管作排水。"},{"en":"Because it can be hard or flexible, PVC has many uses.","zh":"因為它可以堅硬或柔軟，PVC 有許多用途。"},{"en":"The phrase gives the formal chemical name of PVC.","zh":"這個短語提供 PVC 的正式化學名稱。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":8},{"front":"a hard, fireproof plastic","meaning":"堅硬、防火的塑膠","examples":[{"en":"PVC is a hard, fireproof plastic.","zh":"PVC 是一種堅硬、防火的塑膠。"},{"en":"A hard, fireproof plastic is a stiff plastic that resists burning.","zh":"「a hard, fireproof plastic」是堅硬且抗燃燒的塑膠。"},{"en":"Building materials may need to be fireproof for safety reasons.","zh":"建築材料可能因安全原因需要防火。"},{"en":"If a plastic is hard and fireproof, it can be useful in drains or construction.","zh":"如果塑膠堅硬又防火，它可用於排水渠或建築。"},{"en":"The phrase describes two important properties of rigid PVC.","zh":"這個短語描述硬質 PVC 的兩項重要特性。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":8},{"front":"suitable for","meaning":"適合用於","examples":[{"en":"PVC is suitable for drains and gutters.","zh":"PVC 適合用於排水渠和雨水槽。"},{"en":"Suitable for means appropriate or useful for a particular purpose.","zh":"「suitable for」意思是適合或有用於特定目的。"},{"en":"A quiet classroom is suitable for an exam.","zh":"安靜課室適合用於考試。"},{"en":"If a material is waterproof and strong, it may be suitable for outdoor pipes.","zh":"如果材料防水且堅固，它可能適合用於戶外管道。"},{"en":"The phrase connects a quality with a use.","zh":"這個短語把特質與用途連繫起來。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":8},{"front":"drains and gutters","meaning":"排水渠和雨水槽","examples":[{"en":"Rigid PVC is suitable for drains and gutters.","zh":"硬質 PVC 適合用於排水渠和雨水槽。"},{"en":"Drains and gutters are channels or pipes that carry away water.","zh":"「drains and gutters」是排走水的渠道或管道。"},{"en":"After heavy rain, drains and gutters help prevent flooding around buildings.","zh":"大雨後，排水渠和雨水槽有助防止建築物周圍水浸。"},{"en":"If these channels are made of strong plastic, they can resist water and weather.","zh":"如果這些渠道由堅固塑膠製成，它們可以抵禦水和天氣。"},{"en":"The phrase names parts of a water-removal system.","zh":"這個短語指出排水系統的部分。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":9},{"front":"by adding certain chemicals","meaning":"透過加入某些化學物質","examples":[{"en":"A soft form of PVC can be produced by adding certain chemicals.","zh":"軟質 PVC 可以透過加入某些化學物質製成。"},{"en":"By adding certain chemicals means through putting specific substances into the material.","zh":"「by adding certain chemicals」意思是透過把特定物質加入材料中。"},{"en":"A cook changes soup flavour by adding certain spices.","zh":"廚師透過加入某些香料改變湯的味道。"},{"en":"If chemicals are added to PVC, the plastic can become softer and more flexible.","zh":"如果化學物質被加入 PVC，塑膠可以變得更柔軟和有彈性。"},{"en":"The phrase describes a method of changing material properties.","zh":"這個短語描述改變材料特性的方法。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":9},{"front":"a soft form of PVC","meaning":"軟質聚氯乙烯","examples":[{"en":"A soft form of PVC can be used as a substitute for rubber.","zh":"軟質聚氯乙烯可以用作橡膠替代品。"},{"en":"A soft form of PVC is flexible PVC made by adding chemicals to change its texture.","zh":"「a soft form of PVC」是透過加入化學物質改變質感而成的柔韌 PVC。"},{"en":"Flexible plastic tubing may be made from a soft form of PVC.","zh":"柔性塑膠管可能由軟質 PVC 製成。"},{"en":"If PVC becomes soft, it can be used where hard plastic would not bend enough.","zh":"如果 PVC 變得柔軟，它可以用於硬塑膠不夠彎曲的地方。"},{"en":"The phrase contrasts flexible PVC with rigid PVC.","zh":"這個短語把柔性 PVC 與硬質 PVC 作對比。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":9},{"front":"a substitute for rubber","meaning":"橡膠的替代品","examples":[{"en":"Soft PVC was suitable as a substitute for rubber.","zh":"軟質 PVC 適合作為橡膠的替代品。"},{"en":"A substitute for rubber is a material used instead of rubber.","zh":"「a substitute for rubber」是用來代替橡膠的材料。"},{"en":"A bakery may use oil as a substitute for butter in some recipes.","zh":"麵包店在某些食譜中可能用油作為牛油的替代品。"},{"en":"If natural rubber is expensive or scarce, manufacturers may look for substitutes.","zh":"如果天然橡膠昂貴或稀少，製造商可能尋找替代品。"},{"en":"The phrase describes an alternative material.","zh":"這個短語描述替代材料。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":9},{"front":"waterproof clothing","meaning":"防水衣物","examples":[{"en":"Soft PVC was used in items such as waterproof clothing.","zh":"軟質 PVC 被用於防水衣物等物品。"},{"en":"Waterproof clothing is clothing that stops water from passing through.","zh":"「waterproof clothing」是阻止水穿透的衣物。"},{"en":"A raincoat is waterproof clothing that helps students stay dry on the way to school.","zh":"雨衣是防水衣物，幫助學生上學途中保持乾爽。"},{"en":"If clothing is made from soft PVC, it can be flexible and water-resistant.","zh":"如果衣物由軟質 PVC 製成，它可以柔韌且防水。"},{"en":"The phrase names a practical use of flexible plastic.","zh":"這個短語指出柔性塑膠的一種實際用途。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":9},{"front":"a closely related plastic","meaning":"關係密切的塑膠","examples":[{"en":"Teflon was a closely related plastic.","zh":"特氟龍是一種關係密切的塑膠。"},{"en":"A closely related plastic is a plastic with a chemical structure or origin similar to another one.","zh":"「a closely related plastic」是化學結構或來源與另一種塑膠相似的塑膠。"},{"en":"Two phone models may be closely related if they use the same design and parts.","zh":"如果兩款電話使用相同設計和零件，它們可能關係密切。"},{"en":"If plastics are closely related, a small chemical difference may still change their properties.","zh":"如果塑膠關係密切，小小化學差異仍可能改變其特性。"},{"en":"The phrase describes similarity within a material family.","zh":"這個短語描述材料家族內的相似性。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":9},{"front":"Teflon","meaning":"特氟龍","examples":[{"en":"Teflon is also known as PTFE.","zh":"特氟龍也稱為 PTFE。"},{"en":"Teflon is a plastic famous for its very low friction and non-stick surface.","zh":"「Teflon」是一種以極低摩擦和易潔表面聞名的塑膠。"},{"en":"Many non-stick frying pans are coated with Teflon.","zh":"許多易潔煎鑊塗有特氟龍。"},{"en":"Because Teflon reduces sticking, it is useful in pans, bearings, and rollers.","zh":"因為特氟龍減少黏附，它可用於煎鑊、軸承和滾軸。"},{"en":"The word is a familiar trade name for PTFE.","zh":"這個詞是 PTFE 的常見商品名稱。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":9},{"front":"PTFE","meaning":"聚四氟乙烯","examples":[{"en":"PTFE stands for polytetrafluoroethylene.","zh":"PTFE 代表聚四氟乙烯。"},{"en":"PTFE is the chemical name for the plastic commonly known as Teflon.","zh":"「PTFE」是通常稱為特氟龍的塑膠的化學名稱。"},{"en":"Engineers may choose PTFE when they need a low-friction material.","zh":"工程師需要低摩擦材料時，可能選擇 PTFE。"},{"en":"If a surface is coated with PTFE, food or moving parts may stick less easily.","zh":"如果表面塗有 PTFE，食物或活動零件可能較不容易黏住。"},{"en":"The abbreviation names a specialist plastic.","zh":"這個縮寫指出一種專門塑膠。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":9},{"front":"a very low coefficient of friction","meaning":"非常低的摩擦系數","examples":[{"en":"Teflon had a very low coefficient of friction.","zh":"特氟龍有非常低的摩擦系數。"},{"en":"A very low coefficient of friction means surfaces slide against it very easily.","zh":"「a very low coefficient of friction」意思是表面很容易在它上面滑動。"},{"en":"Ice has low friction, so shoes can slip on it.","zh":"冰的摩擦低，所以鞋子在上面可能滑倒。"},{"en":"If a material has low friction, moving parts wear less and food sticks less.","zh":"如果材料摩擦低，活動零件磨損較少，食物也較不易黏住。"},{"en":"The phrase explains why Teflon is useful for non-stick and moving surfaces.","zh":"這個短語解釋為何特氟龍適用於易潔和活動表面。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":9},{"front":"making it ideal for","meaning":"使其非常適合","examples":[{"en":"Teflon had low friction, making it ideal for non-stick pans.","zh":"特氟龍摩擦低，使其非常適合用於易潔煎鑊。"},{"en":"Making it ideal for means causing it to be very suitable for a purpose.","zh":"「making it ideal for」意思是令它非常適合某用途。"},{"en":"The school is near the bus stop, making it ideal for students who travel alone.","zh":"學校靠近巴士站，使其非常適合獨自上學的學生。"},{"en":"If a material has low friction, that property makes it ideal for sliding surfaces.","zh":"如果材料摩擦低，這種特性令它非常適合滑動表面。"},{"en":"The phrase links a feature with an excellent use.","zh":"這個短語把特徵與理想用途連繫起來。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":9},{"front":"bearings","meaning":"軸承","examples":[{"en":"Teflon was ideal for bearings.","zh":"特氟龍非常適合用於軸承。"},{"en":"Bearings are machine parts that help other parts move smoothly with less friction.","zh":"「bearings」是幫助其他零件以較少摩擦順暢移動的機械部件。"},{"en":"A bicycle wheel uses bearings so it can spin easily.","zh":"單車車輪使用軸承，因此可以輕鬆轉動。"},{"en":"If bearings have low-friction surfaces, machines can run more smoothly.","zh":"如果軸承有低摩擦表面，機器可以運行得更順暢。"},{"en":"The word names a mechanical part used in movement.","zh":"這個詞指出用於運動的機械零件。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":9},{"front":"rollers","meaning":"滾軸","examples":[{"en":"Teflon was ideal for rollers.","zh":"特氟龍非常適合用於滾軸。"},{"en":"Rollers are round parts that turn to move, press, or support materials.","zh":"「rollers」是轉動以移動、壓平或支撐材料的圓形部件。"},{"en":"A printer uses rollers to move paper through the machine.","zh":"打印機使用滾軸把紙張送過機器。"},{"en":"If rollers have low friction, materials can pass over them more smoothly.","zh":"如果滾軸摩擦低，材料可以更順暢地通過。"},{"en":"The word names a rotating mechanical part.","zh":"這個詞指出旋轉機械部件。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":10},{"front":"non-stick frying pans","meaning":"易潔煎鑊","examples":[{"en":"Teflon is used in non-stick frying pans.","zh":"特氟龍用於易潔煎鑊。"},{"en":"Non-stick frying pans are pans with surfaces that stop food from sticking easily.","zh":"「non-stick frying pans」是表面可防止食物容易黏住的煎鑊。"},{"en":"A cook may use a non-stick frying pan to make eggs with less oil.","zh":"廚師可能用易潔煎鑊以較少油煎蛋。"},{"en":"If food does not stick, cleaning the pan becomes easier.","zh":"如果食物不黏住，清潔煎鑊會更容易。"},{"en":"The phrase names a common kitchen use of Teflon.","zh":"這個短語指出特氟龍的一種常見廚房用途。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":10},{"front":"polystyrene","meaning":"聚苯乙烯","examples":[{"en":"Polystyrene was developed during the 1930s in Germany.","zh":"聚苯乙烯在1930年代於德國發展出來。"},{"en":"Polystyrene is a plastic that can be clear and rigid or expanded into foam.","zh":"「polystyrene」是一種可以是透明硬質，也可以發泡成泡沫的塑膠。"},{"en":"Some food containers and packaging are made from polystyrene.","zh":"有些食物容器和包裝由聚苯乙烯製成。"},{"en":"If polystyrene is expanded, it becomes light foam useful for protection and insulation.","zh":"如果聚苯乙烯被發泡，它會變成有助保護和隔熱的輕質泡沫。"},{"en":"The word names a widely used plastic material.","zh":"這個詞指出一種廣泛使用的塑膠材料。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":10},{"front":"a clear, glass-like material","meaning":"透明、似玻璃的材料","examples":[{"en":"Polystyrene was a clear, glass-like material.","zh":"聚苯乙烯是一種透明、似玻璃的材料。"},{"en":"A clear, glass-like material is transparent and looks similar to glass.","zh":"「a clear, glass-like material」是透明並看起來像玻璃的材料。"},{"en":"A plastic display box may use a clear, glass-like material to show the object inside.","zh":"塑膠展示盒可能使用透明、似玻璃的材料來展示內部物件。"},{"en":"If a material looks like glass but is lighter, it can be useful in household products.","zh":"如果材料看起來像玻璃但較輕，它可以用於家居產品。"},{"en":"The phrase describes appearance and transparency.","zh":"這個短語描述外觀和透明度。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":10},{"front":"food containers","meaning":"食物容器","examples":[{"en":"Polystyrene was used in food containers.","zh":"聚苯乙烯被用於食物容器。"},{"en":"Food containers are boxes, cups, or trays used to hold food.","zh":"「food containers」是用來盛載食物的盒、杯或托盤。"},{"en":"A student may bring lunch to school in a reusable food container.","zh":"學生可能用可重用食物容器帶午餐回校。"},{"en":"If a container is light and cheap, restaurants may use it for takeaway meals.","zh":"如果容器輕巧又便宜，餐廳可能用它盛載外賣。"},{"en":"The phrase names an everyday packaging product.","zh":"這個短語指出日常包裝產品。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":10},{"front":"domestic appliances","meaning":"家用電器","examples":[{"en":"Polystyrene was used in domestic appliances and toys.","zh":"聚苯乙烯被用於家用電器和玩具。"},{"en":"Domestic appliances are machines used in the home, such as fridges, washing machines, or kettles.","zh":"「domestic appliances」是在家中使用的機器，例如雪櫃、洗衣機或電水壺。"},{"en":"A family may replace old domestic appliances to save electricity.","zh":"家庭可能更換舊家用電器以節省電力。"},{"en":"If plastic is light and mouldable, it can be used in appliance parts.","zh":"如果塑膠輕巧且可模塑，它可以用於電器零件。"},{"en":"The phrase refers to household machines.","zh":"這個短語指家用機器。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":10},{"front":"expanded polystyrene","meaning":"發泡聚苯乙烯","examples":[{"en":"Expanded polystyrene is a white, rigid foam.","zh":"發泡聚苯乙烯是一種白色硬質泡沫。"},{"en":"Expanded polystyrene is polystyrene made into a light foam full of tiny air spaces.","zh":"「expanded polystyrene」是製成輕質泡沫、含有許多微小空氣空間的聚苯乙烯。"},{"en":"Fragile electronics are often packed in expanded polystyrene for protection.","zh":"易碎電子產品常用發泡聚苯乙烯包裝以作保護。"},{"en":"Because it traps air, expanded polystyrene can protect products and reduce heat transfer.","zh":"因為它困住空氣，發泡聚苯乙烯可以保護產品並減少熱傳遞。"},{"en":"The phrase names the foam form of polystyrene.","zh":"這個短語指出聚苯乙烯的泡沫形式。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":10},{"front":"a white, rigid foam","meaning":"白色硬質泡沫","examples":[{"en":"Expanded polystyrene was a white, rigid foam.","zh":"發泡聚苯乙烯是一種白色硬質泡沫。"},{"en":"A white, rigid foam is a pale, stiff, lightweight material full of air pockets.","zh":"「a white, rigid foam」是淺色、堅硬、輕巧並充滿氣泡空間的材料。"},{"en":"A takeaway box may be made from a white foam that keeps food warm.","zh":"外賣盒可能由能保溫的白色泡沫製成。"},{"en":"If foam is rigid, it can protect objects from knocks during transport.","zh":"如果泡沫是硬質的，它可以在運輸中保護物件免受撞擊。"},{"en":"The phrase describes the appearance and texture of expanded polystyrene.","zh":"這個短語描述發泡聚苯乙烯的外觀和質感。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":10},{"front":"widely used in","meaning":"廣泛用於","examples":[{"en":"Expanded polystyrene was widely used in packaging and insulation.","zh":"發泡聚苯乙烯廣泛用於包裝和隔熱。"},{"en":"Widely used in means commonly used in many places or situations.","zh":"「widely used in」意思是在許多地方或情況中常被使用。"},{"en":"Tablets are widely used in schools for reading and homework.","zh":"平板電腦廣泛用於學校閱讀和做功課。"},{"en":"If a material is cheap and useful, it can be widely used across industries.","zh":"如果材料便宜又有用，它可以在各行各業廣泛使用。"},{"en":"The phrase stresses common use.","zh":"這個短語強調普遍使用。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":10},{"front":"packaging and insulation","meaning":"包裝和隔熱","examples":[{"en":"Expanded polystyrene was used in packaging and insulation.","zh":"發泡聚苯乙烯被用於包裝和隔熱。"},{"en":"Packaging and insulation mean protecting products and reducing heat transfer.","zh":"「packaging and insulation」意思是保護產品和減少熱傳遞。"},{"en":"A delivery company uses packaging to protect goods during transport.","zh":"速遞公司使用包裝來保護運輸中的貨物。"},{"en":"If a material insulates well, it can keep hot things hot and cold things cold.","zh":"如果材料隔熱良好，它可以保熱或保冷。"},{"en":"The phrase names two important uses of foam plastic.","zh":"這個短語指出泡沫塑膠的兩項重要用途。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":10},{"front":"polyurethanes","meaning":"聚氨酯","examples":[{"en":"Polyurethanes were also developed in Germany.","zh":"聚氨酯也在德國發展出來。"},{"en":"Polyurethanes are plastics used in foams, coatings, adhesives, and insulation materials.","zh":"「polyurethanes」是用於泡沫、塗層、黏合劑和隔熱材料的塑膠。"},{"en":"A sofa cushion may contain polyurethane foam.","zh":"沙發墊可能含有聚氨酯泡沫。"},{"en":"Because polyurethanes can be flexible or rigid, they have many uses.","zh":"因為聚氨酯可以柔軟或堅硬，它有許多用途。"},{"en":"The word names a family of useful synthetic materials.","zh":"這個詞指出一類有用的合成材料。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":10},{"front":"found uses as","meaning":"用作……","examples":[{"en":"Polyurethanes found uses as adhesives and coatings.","zh":"聚氨酯被用作黏合劑和塗層。"},{"en":"Found uses as means began to be used in the role of something.","zh":"「found uses as」意思是開始被用作某種角色。"},{"en":"Old school tablets may find uses as reading devices after newer computers arrive.","zh":"新電腦到來後，舊學校平板可能被用作閱讀裝置。"},{"en":"If a material sticks well or covers surfaces well, it may find uses as glue or coating.","zh":"如果材料黏附力好或能良好覆蓋表面，它可能被用作膠水或塗層。"},{"en":"The phrase describes practical applications being discovered.","zh":"這個短語描述實際用途被發現。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":11},{"front":"adhesives","meaning":"黏合劑","examples":[{"en":"Polyurethanes found uses as adhesives.","zh":"聚氨酯被用作黏合劑。"},{"en":"Adhesives are substances that stick materials together.","zh":"「adhesives」是把材料黏在一起的物質。"},{"en":"Glue used in a classroom art project is a simple adhesive.","zh":"課堂美術作品中使用的膠水是一種簡單黏合劑。"},{"en":"If an adhesive is strong, it can join wood, plastic, or metal parts securely.","zh":"如果黏合劑很強，它可以牢固連接木材、塑膠或金屬部件。"},{"en":"The word names materials used for sticking.","zh":"這個詞指出用於黏合的材料。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":11},{"front":"coatings","meaning":"塗層","examples":[{"en":"Polyurethanes found uses as coatings.","zh":"聚氨酯被用作塗層。"},{"en":"Coatings are layers put on a surface to protect it or change its appearance.","zh":"「coatings」是塗在表面上以保護或改變外觀的層。"},{"en":"A wooden table may have a clear coating to protect it from water.","zh":"木桌可能有透明塗層，以防止受水損壞。"},{"en":"If a coating resists scratches, the product may last longer.","zh":"如果塗層抗刮，產品可能更耐用。"},{"en":"The word refers to protective or decorative surface layers.","zh":"這個詞指保護性或裝飾性表面層。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":11},{"front":"in the form of rigid foams","meaning":"以硬質泡沫形式","examples":[{"en":"Polyurethanes were used as insulation in the form of rigid foams.","zh":"聚氨酯以硬質泡沫形式被用作隔熱材料。"},{"en":"In the form of rigid foams means appearing or being made as stiff foam materials.","zh":"「in the form of rigid foams」意思是以堅硬泡沫材料的形式出現或製成。"},{"en":"A mattress may use material in the form of soft foam.","zh":"床褥可能使用柔軟泡沫形式的材料。"},{"en":"If insulation is in rigid foam form, it can fit into walls or panels.","zh":"如果隔熱材料以硬質泡沫形式存在，它可以安裝在牆壁或板材中。"},{"en":"The phrase describes the physical form of a material.","zh":"這個短語描述材料的物理形態。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":11},{"front":"insulation materials","meaning":"隔熱材料","examples":[{"en":"Rigid foams were used as insulation materials.","zh":"硬質泡沫被用作隔熱材料。"},{"en":"Insulation materials are materials that reduce heat, sound, or electricity passing through.","zh":"「insulation materials」是減少熱、聲音或電流通過的材料。"},{"en":"Homes use insulation materials in walls to stay warmer in winter.","zh":"家居在牆壁中使用隔熱材料，以便冬天更保暖。"},{"en":"If insulation is effective, less energy is needed for heating or cooling.","zh":"如果隔熱有效，供暖或製冷所需能源會較少。"},{"en":"The phrase names materials used to block transfer.","zh":"這個短語指出用來阻隔傳遞的材料。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":11},{"front":"derived from crude oil","meaning":"源自原油的","examples":[{"en":"Many plastics are produced from chemicals derived from crude oil.","zh":"許多塑膠由源自原油的化學物質製成。"},{"en":"Derived from crude oil means obtained from or made using substances from crude oil.","zh":"「derived from crude oil」意思是取自或使用來自原油的物質製成。"},{"en":"Petrol and many chemical products are derived from crude oil.","zh":"汽油和許多化學產品都源自原油。"},{"en":"If plastics depend on oil-derived chemicals, oil supply affects plastic production.","zh":"如果塑膠依賴源自原油的化學物質，原油供應會影響塑膠生產。"},{"en":"The phrase identifies crude oil as a source material.","zh":"這個短語指出原油作為來源材料。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":11},{"front":"crude oil","meaning":"原油","examples":[{"en":"Crude oil contains carbon and hydrogen.","zh":"原油含有碳和氫。"},{"en":"Crude oil is natural oil taken from underground and refined into fuels and chemicals.","zh":"「crude oil」是從地下取得並被提煉成燃料和化學品的天然石油。"},{"en":"Refineries process crude oil into petrol, diesel, and chemical feedstocks.","zh":"煉油廠把原油加工成汽油、柴油和化學原料。"},{"en":"Because crude oil contains useful elements, it became important for plastic production.","zh":"因為原油含有有用元素，它成為塑膠生產的重要材料。"},{"en":"The phrase names a major raw material for the chemical industry.","zh":"這個短語指出化學工業的主要原材料。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":11},{"front":"contains exactly the same elements","meaning":"含有完全相同的元素","examples":[{"en":"Crude oil contains exactly the same elements as many plastics.","zh":"原油含有與許多塑膠完全相同的元素。"},{"en":"Contains exactly the same elements means has the same basic chemical elements.","zh":"「contains exactly the same elements」意思是具有相同的基本化學元素。"},{"en":"Two recipes may contain the same ingredients but produce different dishes.","zh":"兩個食譜可能含有相同材料，但製成不同菜式。"},{"en":"If crude oil and plastics share elements, chemical conversion becomes possible.","zh":"如果原油和塑膠共享相同元素，化學轉化就成為可能。"},{"en":"The phrase compares basic composition.","zh":"這個短語比較基本組成。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":11},{"front":"carbon and hydrogen","meaning":"碳和氫","examples":[{"en":"Many plastics contain carbon and hydrogen.","zh":"許多塑膠含有碳和氫。"},{"en":"Carbon and hydrogen are chemical elements found in many organic substances.","zh":"「carbon and hydrogen」是存在於許多有機物質中的化學元素。"},{"en":"Fuels, plastics, and living tissues often contain carbon and hydrogen.","zh":"燃料、塑膠和生物組織常含有碳和氫。"},{"en":"If a material contains carbon and hydrogen, it may be part of organic chemistry.","zh":"如果材料含有碳和氫，它可能屬於有機化學範圍。"},{"en":"The phrase names two key elements in many plastics.","zh":"這個短語指出許多塑膠中的兩種關鍵元素。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":11},{"front":"man-made fibres","meaning":"人造纖維","examples":[{"en":"Nylon was the first of the man-made fibres.","zh":"尼龍是首種人造纖維。"},{"en":"Man-made fibres are fibres produced artificially rather than taken directly from plants or animals.","zh":"「man-made fibres」是人工製造，而不是直接取自植物或動物的纖維。"},{"en":"Polyester and nylon are common man-made fibres used in clothing.","zh":"聚酯和尼龍是常用於衣物的人造纖維。"},{"en":"If fibres are man-made, their strength and texture can be designed for specific uses.","zh":"如果纖維是人造的，其強度和質感可以為特定用途設計。"},{"en":"The phrase contrasts synthetic fibres with natural fibres.","zh":"這個短語把合成纖維與天然纖維作對比。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":11},{"front":"nylon","meaning":"尼龍","examples":[{"en":"Nylon was created in the 1930s.","zh":"尼龍在1930年代被創造出來。"},{"en":"Nylon is a strong synthetic fibre used in clothing, ropes, stockings, and parachutes.","zh":"「nylon」是一種強韌合成纖維，用於衣物、繩索、絲襪和降落傘。"},{"en":"A backpack strap may be made of nylon because it is strong and light.","zh":"背包帶可能由尼龍製成，因為它堅韌又輕。"},{"en":"When nylon replaced silk in stockings, clothing manufacturing changed.","zh":"當尼龍在絲襪中取代絲綢，服裝製造就改變了。"},{"en":"The word names the first major man-made fibre in the passage.","zh":"這個詞指出文章中的第一種主要人造纖維。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":11},{"front":"its inventor","meaning":"其發明者","examples":[{"en":"Its inventor was a chemist called Wallace Carothers.","zh":"其發明者是一位名叫 Wallace Carothers 的化學家。"},{"en":"Its inventor means the person who created or developed it first.","zh":"「its inventor」指最先創造或發展它的人。"},{"en":"The inventor of a useful app may become famous if many people use it.","zh":"如果一個有用應用程式被很多人使用，其發明者可能成名。"},{"en":"If a material changes an industry, people often remember its inventor.","zh":"如果材料改變一個產業，人們常記得其發明者。"},{"en":"The phrase identifies the creator of something.","zh":"這個短語指出某物的創造者。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":12},{"front":"under the right conditions","meaning":"在適當條件下","examples":[{"en":"Under the right conditions, two chemicals formed a polymer.","zh":"在適當條件下，兩種化學物質形成聚合物。"},{"en":"Under the right conditions means when the necessary situation, temperature, pressure, or materials are present.","zh":"「under the right conditions」意思是在具備必要情況、溫度、壓力或材料時。"},{"en":"Seeds grow well under the right conditions of water, light, and soil.","zh":"種子在有水、光和土壤的適當條件下生長良好。"},{"en":"If chemicals are not under the right conditions, the desired reaction may not happen.","zh":"如果化學物質不在適當條件下，所需反應可能不會發生。"},{"en":"The phrase explains that success depends on suitable circumstances.","zh":"這個短語解釋成功取決於合適環境。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":12},{"front":"hexamethylenediamine and adipic acid","meaning":"六亞甲基二胺和己二酸","examples":[{"en":"Hexamethylenediamine and adipic acid can form a polymer.","zh":"六亞甲基二胺和己二酸可以形成聚合物。"},{"en":"Hexamethylenediamine and adipic acid are two chemicals used to make nylon.","zh":"「hexamethylenediamine and adipic acid」是兩種用來製造尼龍的化學物質。"},{"en":"A chemistry teacher may use their names to show that synthetic fibres come from specific chemicals.","zh":"化學老師可能用它們的名稱來展示合成纖維來自特定化學物質。"},{"en":"When these two chemicals join properly, they form the polymer used for nylon.","zh":"當這兩種化學物質適當結合，它們形成用於尼龍的聚合物。"},{"en":"The phrase names the starting chemicals in nylon production.","zh":"這個短語指出尼龍生產中的起始化學物質。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":12},{"front":"form a polymer","meaning":"形成聚合物","examples":[{"en":"The two chemicals would form a polymer.","zh":"這兩種化學物質會形成聚合物。"},{"en":"To form a polymer means to join together into a large chain-like molecule.","zh":"「form a polymer」意思是連接成大型鏈狀分子。"},{"en":"Small beads can form a bracelet when they are linked on a string.","zh":"小珠子串在線上時可以形成手鏈。"},{"en":"If chemicals form a polymer, the result may be a useful plastic or fibre.","zh":"如果化學物質形成聚合物，結果可能是有用的塑膠或纖維。"},{"en":"The phrase describes the creation of a large material molecule.","zh":"這個短語描述大型材料分子的形成。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":12},{"front":"be pumped out through holes","meaning":"從孔中擠出","examples":[{"en":"The polymer could be pumped out through holes.","zh":"聚合物可以從孔中擠出。"},{"en":"To be pumped out through holes means to be forced through small openings.","zh":"「be pumped out through holes」意思是被壓迫通過小開口。"},{"en":"Icing can be pumped out through a small nozzle to decorate a cake.","zh":"糖霜可以從小嘴擠出來裝飾蛋糕。"},{"en":"If liquid polymer is forced through tiny holes, it can form thin threads.","zh":"如果液態聚合物被迫通過微小孔洞，它可以形成細線。"},{"en":"The phrase describes how nylon fibres were shaped.","zh":"這個短語描述尼龍纖維如何成形。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":12},{"front":"stretched to form","meaning":"拉伸成……","examples":[{"en":"The material was stretched to form long glossy threads.","zh":"該材料被拉伸成長而有光澤的線。"},{"en":"Stretched to form means pulled out so that it becomes a particular shape.","zh":"「stretched to form」意思是被拉長以形成特定形狀。"},{"en":"Dough can be stretched to form a thin pizza base.","zh":"麵糰可以被拉伸成薄薄的薄餅底。"},{"en":"If polymer threads are stretched, they can become longer, thinner, and stronger.","zh":"如果聚合物線被拉伸，它們可以變得更長、更細和更強。"},{"en":"The phrase describes shaping by pulling.","zh":"這個短語描述透過拉扯塑形。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":12},{"front":"long glossy threads","meaning":"長而有光澤的線","examples":[{"en":"Nylon could be stretched to form long glossy threads.","zh":"尼龍可以被拉伸成長而有光澤的線。"},{"en":"Long glossy threads are long, shiny strands of fibre.","zh":"「long glossy threads」是長而閃亮的纖維絲。"},{"en":"Silk is known for long glossy threads that feel smooth and bright.","zh":"絲綢以長而有光澤、觸感順滑明亮的線聞名。"},{"en":"If synthetic threads look glossy, they can be woven into attractive fabrics.","zh":"如果合成線看起來有光澤，它們可以織成吸引人的布料。"},{"en":"The phrase describes the appearance of nylon fibres.","zh":"這個短語描述尼龍纖維的外觀。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":12},{"front":"woven like silk","meaning":"像絲綢一樣織成","examples":[{"en":"Nylon threads could be woven like silk.","zh":"尼龍線可以像絲綢一樣織成布料。"},{"en":"Woven like silk means made into fabric in a way similar to silk threads.","zh":"「woven like silk」意思是以類似絲線的方式織成布料。"},{"en":"Cotton threads can be woven into shirts and bedsheets.","zh":"棉線可以被織成恤衫和床單。"},{"en":"If nylon can be woven like silk, it can replace silk in some clothing.","zh":"如果尼龍可以像絲綢一樣織成布，它可以在某些衣物中取代絲綢。"},{"en":"The phrase compares nylon’s use with a familiar natural fibre.","zh":"這個短語把尼龍的用途與熟悉的天然纖維作比較。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":12},{"front":"parachutes","meaning":"降落傘","examples":[{"en":"Nylon was first used to make parachutes.","zh":"尼龍最初被用來製造降落傘。"},{"en":"Parachutes are large fabric devices that slow a person or object falling through the air.","zh":"「parachutes」是大型布製裝置，用來減慢人或物在空中下墜。"},{"en":"Emergency teams may use parachutes to drop supplies into remote areas.","zh":"緊急救援隊可能使用降落傘把物資投放到偏遠地區。"},{"en":"If parachute fabric is strong and light, it can open safely in the air.","zh":"如果降落傘布料堅韌又輕，它可以在空中安全打開。"},{"en":"The word names an early military use of nylon.","zh":"這個詞指出尼龍的早期軍事用途。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":12},{"front":"the US armed forces","meaning":"美國武裝部隊","examples":[{"en":"Nylon was used for the US armed forces in World War II.","zh":"尼龍在第二次世界大戰中被美國武裝部隊使用。"},{"en":"The US armed forces are the military services of the United States.","zh":"「the US armed forces」是美國的軍事部隊。"},{"en":"The US armed forces need strong materials for uniforms, ropes, tents, and parachutes.","zh":"美國武裝部隊需要堅韌材料製造制服、繩索、帳篷和降落傘。"},{"en":"If a material is useful in war, production may increase quickly.","zh":"如果材料在戰爭中有用，產量可能迅速增加。"},{"en":"The phrase identifies the military users of nylon.","zh":"這個短語指出尼龍的軍事使用者。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":12},{"front":"World War II","meaning":"第二次世界大戰","examples":[{"en":"Nylon was first used during World War II.","zh":"尼龍最初在第二次世界大戰期間被使用。"},{"en":"World War II was the global war fought from 1939 to 1945.","zh":"「World War II」是1939年至1945年間發生的全球戰爭。"},{"en":"Many technologies and materials developed quickly during World War II.","zh":"許多科技和材料在第二次世界大戰期間快速發展。"},{"en":"Because armies needed strong fibres, nylon became important during the war.","zh":"因為軍隊需要堅韌纖維，尼龍在戰爭期間變得重要。"},{"en":"The phrase gives the historical context for nylon’s early use.","zh":"這個短語提供尼龍早期用途的歷史背景。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":12},{"front":"the post-war years","meaning":"戰後年代","examples":[{"en":"Nylon replaced silk in the post-war years.","zh":"尼龍在戰後年代取代絲綢。"},{"en":"The post-war years are the years after a war has ended.","zh":"「the post-war years」是戰爭結束後的年月。"},{"en":"Many families rebuilt homes and businesses in the post-war years.","zh":"許多家庭在戰後年代重建家園和生意。"},{"en":"After World War II, materials developed for military use entered civilian markets.","zh":"第二次世界大戰後，為軍事用途發展的材料進入民用市場。"},{"en":"The phrase marks the period after wartime.","zh":"這個短語標示戰時之後的時期。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":13},{"front":"completely replaced silk","meaning":"完全取代絲綢","examples":[{"en":"Nylon completely replaced silk in the manufacture of stockings.","zh":"尼龍在絲襪製造中完全取代絲綢。"},{"en":"Completely replaced silk means took over silk’s role entirely in a particular use.","zh":"「completely replaced silk」意思是在某用途上完全接替絲綢的角色。"},{"en":"Emails have completely replaced paper memos in many offices.","zh":"電郵在許多辦公室已完全取代紙本備忘錄。"},{"en":"If nylon was cheaper and stronger, manufacturers had reason to stop using silk.","zh":"如果尼龍更便宜且更堅韌，製造商就有理由停止使用絲綢。"},{"en":"The phrase describes total replacement.","zh":"這個短語描述完全替代。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":13},{"front":"in the manufacture of stockings","meaning":"在絲襪製造中","examples":[{"en":"Nylon was used in the manufacture of stockings.","zh":"尼龍被用於絲襪製造中。"},{"en":"In the manufacture of stockings means in the process of making close-fitting leg coverings.","zh":"「in the manufacture of stockings」意思是在製造貼腿襪類衣物的過程中。"},{"en":"A factory may use fine fibres in the manufacture of stockings.","zh":"工廠可能在絲襪製造中使用幼細纖維。"},{"en":"If nylon threads are strong and glossy, they are suitable for stockings.","zh":"如果尼龍線堅韌而有光澤，它們適合用於絲襪。"},{"en":"The phrase describes a specific clothing-production use.","zh":"這個短語描述一種特定服裝生產用途。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":13},{"front":"subsequently","meaning":"隨後","examples":[{"en":"Subsequently, many other synthetic fibres joined nylon.","zh":"隨後，許多其他合成纖維加入尼龍的行列。"},{"en":"Subsequently means after that or later.","zh":"「subsequently」意思是之後或後來。"},{"en":"The school tested a new timetable and subsequently introduced it to all classes.","zh":"學校測試新時間表，隨後把它推行到所有班級。"},{"en":"If one invention succeeds, related inventions may subsequently appear.","zh":"如果一項發明成功，相關發明可能隨後出現。"},{"en":"The word shows sequence in time.","zh":"這個詞顯示時間順序。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":13},{"front":"synthetic fibres","meaning":"合成纖維","examples":[{"en":"Many synthetic fibres joined nylon after the war.","zh":"戰後，許多合成纖維加入尼龍的行列。"},{"en":"Synthetic fibres are artificial fibres made by chemical processes.","zh":"「synthetic fibres」是透過化學過程製成的人造纖維。"},{"en":"Sports shirts often use synthetic fibres because they dry quickly.","zh":"運動恤常使用合成纖維，因為它們快乾。"},{"en":"If fibres are synthetic, manufacturers can design them to be strong, light, or elastic.","zh":"如果纖維是合成的，製造商可以把它們設計成堅韌、輕巧或有彈性。"},{"en":"The phrase contrasts with natural fibres such as cotton and wool.","zh":"這個短語與棉和羊毛等天然纖維形成對比。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":13},{"front":"garments","meaning":"衣物；服裝","examples":[{"en":"Most garments are made of a blend of natural and man-made fibres.","zh":"大多數衣物由天然和人造纖維混合製成。"},{"en":"Garments are pieces of clothing.","zh":"「garments」是衣服或服裝單件。"},{"en":"Shirts, coats, dresses, and trousers are all garments.","zh":"恤衫、外套、連身裙和褲子都是衣物。"},{"en":"If garments use blended fibres, they may be easier to wash and wear.","zh":"如果服裝使用混合纖維，它們可能更容易清洗和穿着。"},{"en":"The word is more formal than “clothes”.","zh":"這個詞比 “clothes” 更正式。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":13},{"front":"a blend of natural fibres","meaning":"天然纖維混合物","examples":[{"en":"Many garments are made of a blend of natural fibres and man-made fibres.","zh":"許多衣物由天然纖維和人造纖維的混合物製成。"},{"en":"A blend of natural fibres is a mixture containing fibres from plants or animals.","zh":"「a blend of natural fibres」是含有來自植物或動物纖維的混合物。"},{"en":"A sweater may use a blend of wool and cotton for comfort and strength.","zh":"毛衣可能使用羊毛和棉的混合物，以增加舒適度和強度。"},{"en":"If natural fibres are blended with synthetic ones, the fabric may become easier to care for.","zh":"如果天然纖維與合成纖維混合，布料可能變得更容易打理。"},{"en":"The phrase describes a mixed fabric composition.","zh":"這個短語描述混合布料成分。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":13},{"front":"cotton and wool","meaning":"棉和羊毛","examples":[{"en":"Cotton and wool are natural fibres.","zh":"棉和羊毛是天然纖維。"},{"en":"Cotton and wool are fibres from plants and animals used to make clothing.","zh":"「cotton and wool」是來自植物和動物、用來製衣的纖維。"},{"en":"A T-shirt may be made from cotton, while a winter coat may contain wool.","zh":"T 恤可能由棉製成，而冬天外套可能含有羊毛。"},{"en":"If cotton and wool are blended with synthetic fibres, the fabric may gain new qualities.","zh":"如果棉和羊毛與合成纖維混合，布料可能獲得新特性。"},{"en":"The phrase names two common natural fibres.","zh":"這個短語指出兩種常見天然纖維。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":13},{"front":"make fabrics easier to look after","meaning":"令布料更容易打理","examples":[{"en":"Man-made fibres make fabrics easier to look after.","zh":"人造纖維令布料更容易打理。"},{"en":"To make fabrics easier to look after means to make cloth easier to wash, dry, iron, or maintain.","zh":"「make fabrics easier to look after」意思是令布料更容易清洗、晾乾、熨燙或保養。"},{"en":"A school uniform that dries quickly is easier for families to look after.","zh":"快乾校服對家庭來說更容易打理。"},{"en":"If synthetic fibres wrinkle less, people spend less time ironing them.","zh":"如果合成纖維較少起皺，人們就花較少時間熨它們。"},{"en":"The phrase describes practical convenience in clothing care.","zh":"這個短語描述衣物護理上的實際便利。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":13},{"front":"the great strength of","meaning":"……的最大優點","examples":[{"en":"The great strength of plastic is its indestructibility.","zh":"塑膠的最大優點是其難以破壞的特性。"},{"en":"The great strength of something means its biggest advantage or strongest quality.","zh":"「the great strength of」某物，意思是它最大的優勢或最強特質。"},{"en":"The great strength of a good teacher is the ability to explain difficult ideas simply.","zh":"好老師的最大優點是能簡單解釋困難概念。"},{"en":"If plastic’s strength is durability, it is useful for long-lasting products.","zh":"如果塑膠的優點是耐用，它就適合製造持久產品。"},{"en":"The phrase introduces a major positive feature.","zh":"這個短語引出主要正面特徵。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":13},{"front":"indestructibility","meaning":"難以破壞的特性","examples":[{"en":"The great strength of plastic is its indestructibility.","zh":"塑膠的最大優點是其難以破壞的特性。"},{"en":"Indestructibility means the quality of being very difficult or almost impossible to destroy.","zh":"「indestructibility」意思是非常難或幾乎不可能被破壞的特性。"},{"en":"A metal lunchbox may be valued for its near indestructibility.","zh":"金屬飯盒可能因接近難以破壞而受重視。"},{"en":"If a material does not break down, it can last long but also create waste problems.","zh":"如果材料不會分解，它可以持久，但也會造成廢物問題。"},{"en":"The word describes durability that can be both useful and problematic.","zh":"這個詞描述既有用又可能有問題的耐久性。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":13},{"front":"something of a drawback","meaning":"某程度上的缺點","examples":[{"en":"This useful quality is also something of a drawback.","zh":"這種有用特性也在某程度上是缺點。"},{"en":"Something of a drawback means a disadvantage to some degree.","zh":"「something of a drawback」意思是在某程度上是不利之處。"},{"en":"A phone with a huge screen is useful, but it is something of a drawback when it does not fit in a pocket.","zh":"大屏幕電話很有用，但當它放不入口袋時，就某程度上是缺點。"},{"en":"If plastic lasts too long, its durability becomes an environmental problem.","zh":"如果塑膠持續太久，其耐用性會變成環境問題。"},{"en":"The phrase shows that a strength can also be a weakness.","zh":"這個短語顯示優點也可以是弱點。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":14},{"front":"all over the world","meaning":"世界各地","examples":[{"en":"Beaches all over the world are littered with plastic bottles.","zh":"世界各地的海灘都滿佈塑膠瓶垃圾。"},{"en":"All over the world means in many places across the whole world.","zh":"「all over the world」意思是在全球許多地方。"},{"en":"Students all over the world use the internet for learning.","zh":"世界各地的學生都使用互聯網學習。"},{"en":"If plastic waste appears all over the world, the problem is global.","zh":"如果塑膠廢物出現在世界各地，問題就是全球性的。"},{"en":"The phrase stresses wide geographical spread.","zh":"這個短語強調地理範圍廣泛。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":14},{"front":"the remotest islands","meaning":"最偏遠的島嶼","examples":[{"en":"Plastic bottles are found even on the remotest islands.","zh":"即使在最偏遠的島嶼上，也能找到塑膠瓶。"},{"en":"The remotest islands are islands that are very far from towns, cities, or busy routes.","zh":"「the remotest islands」是離城鎮、城市或繁忙路線非常遠的島嶼。"},{"en":"Researchers may travel by boat for days to reach the remotest islands.","zh":"研究人員可能乘船數天才到達最偏遠的島嶼。"},{"en":"If plastic reaches remote islands, ocean pollution has spread very widely.","zh":"如果塑膠到達偏遠島嶼，海洋污染就已擴散得非常廣。"},{"en":"The phrase highlights how far waste can travel.","zh":"這個短語突出廢物可以傳播得多遠。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":14},{"front":"are littered with","meaning":"滿佈……垃圾","examples":[{"en":"Beaches are littered with plastic bottles.","zh":"海灘滿佈塑膠瓶垃圾。"},{"en":"Are littered with means are covered with many pieces of rubbish or unwanted objects.","zh":"「are littered with」意思是滿佈許多垃圾或不需要的物件。"},{"en":"After a festival, a park may be littered with paper cups and food boxes.","zh":"節日過後，公園可能滿佈紙杯和食物盒垃圾。"},{"en":"If beaches are littered with plastic, animals and visitors may be harmed.","zh":"如果海灘滿佈塑膠垃圾，動物和遊客可能受害。"},{"en":"The phrase describes an untidy place full of waste.","zh":"這個短語描述充滿廢物、凌亂的地方。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":14},{"front":"nothing can destroy","meaning":"沒有東西能摧毀","examples":[{"en":"The passage describes plastic bottles as items that nothing can destroy.","zh":"文章把塑膠瓶描述為沒有東西能摧毀的物品。"},{"en":"Nothing can destroy something means no natural force or ordinary process can break it down easily.","zh":"「nothing can destroy」某物，意思是沒有自然力量或普通過程能容易分解它。"},{"en":"A rumour may feel like something nothing can destroy if people keep repeating it.","zh":"如果人們一直重複謠言，它可能感覺像沒有東西能摧毀。"},{"en":"If plastic waste cannot be destroyed easily, it remains in the environment for a long time.","zh":"如果塑膠廢物不能輕易被摧毀，它會長時間留在環境中。"},{"en":"The phrase exaggerates durability to highlight a problem.","zh":"這個短語誇張地描述耐久性，以突出問題。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":14},{"front":"Nor is it very easy to","meaning":"……也不太容易","examples":[{"en":"Nor is it very easy to recycle plastics.","zh":"回收塑膠也不太容易。"},{"en":"Nor is it very easy to means it is also not very easy to do something.","zh":"「Nor is it very easy to」意思是做某事也不太容易。"},{"en":"The room is not cheap to rent, nor is it very easy to reach by bus.","zh":"這個房間租金不便宜，坐巴士到達也不太容易。"},{"en":"If plastic is hard to destroy and not easy to recycle, waste becomes a bigger problem.","zh":"如果塑膠難以摧毀，也不易回收，廢物問題就更大。"},{"en":"The phrase adds a second negative point.","zh":"這個短語加入第二個負面重點。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":14},{"front":"recycle plastics","meaning":"回收塑膠","examples":[{"en":"It is not very easy to recycle plastics.","zh":"回收塑膠並不太容易。"},{"en":"To recycle plastics means to process used plastic so it can be made into new products.","zh":"「recycle plastics」意思是處理用過的塑膠，使其能製成新產品。"},{"en":"A school may collect bottles to recycle plastics after sports day.","zh":"學校可能在運動會後收集膠樽來回收塑膠。"},{"en":"If different plastics are mixed, recycling becomes more difficult.","zh":"如果不同塑膠混在一起，回收會變得更困難。"},{"en":"The phrase describes turning plastic waste into reusable material.","zh":"這個短語描述把塑膠廢物變成可再用材料。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":14},{"front":"different types of plastic","meaning":"不同種類的塑膠","examples":[{"en":"Different types of plastic often require different treatments.","zh":"不同種類的塑膠通常需要不同處理方法。"},{"en":"Different types of plastic are plastic materials with different chemical structures and properties.","zh":"「different types of plastic」是具有不同化學結構和特性的塑膠材料。"},{"en":"A recycling centre may separate bottles, bags, and foam because they are different plastics.","zh":"回收中心可能分開瓶、袋和泡沫，因為它們是不同塑膠。"},{"en":"If plastics need different treatments, mixing them can slow recycling.","zh":"如果塑膠需要不同處理方法，把它們混在一起會拖慢回收。"},{"en":"The phrase stresses that plastic is not one single material.","zh":"這個短語強調塑膠不是單一材料。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":14},{"front":"call for different treatments","meaning":"需要不同處理方法","examples":[{"en":"Different types of plastic call for different treatments.","zh":"不同種類的塑膠需要不同處理方法。"},{"en":"Call for different treatments means require different ways of handling or processing.","zh":"「call for different treatments」意思是需要不同處理或加工方式。"},{"en":"Different students’ mistakes call for different types of feedback.","zh":"不同學生的錯誤需要不同類型的回饋。"},{"en":"If plastics melt at different temperatures, they cannot all be recycled in the same way.","zh":"如果塑膠熔點不同，它們不能全都以同一方式回收。"},{"en":"The phrase explains why one solution may not fit all cases.","zh":"這個短語解釋為何一種方案未必適合所有情況。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":14},{"front":"biodegradable","meaning":"可生物降解的","examples":[{"en":"Plastics can be made biodegradable by adding starch.","zh":"塑膠可以透過加入澱粉變成可生物降解。"},{"en":"Biodegradable means able to break down naturally through bacteria or other living organisms.","zh":"「biodegradable」意思是能透過細菌或其他生物自然分解。"},{"en":"Some food packaging is biodegradable and breaks down faster than ordinary plastic.","zh":"有些食物包裝可生物降解，比分普通塑膠分解得更快。"},{"en":"If a material is biodegradable, it may create less long-term waste.","zh":"如果材料可生物降解，它可能造成較少長期廢物。"},{"en":"The word describes a material that can decompose biologically.","zh":"這個詞描述能被生物分解的材料。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":14},{"front":"by incorporating into their structure","meaning":"透過把……加入其結構中","examples":[{"en":"Plastics can be made biodegradable by incorporating starch into their structure.","zh":"塑膠可以透過把澱粉加入其結構中而變成可生物降解。"},{"en":"By incorporating into their structure means by adding something into the material’s internal makeup.","zh":"「by incorporating into their structure」意思是把某物加入材料的內部組成之中。"},{"en":"A teacher can improve a lesson by incorporating games into its structure.","zh":"老師可以透過把遊戲加入課堂結構中來改善課堂。"},{"en":"If starch is built into plastic, bacteria can attack it and help the plastic break apart.","zh":"如果澱粉被建入塑膠中，細菌可以攻擊它並幫助塑膠分解。"},{"en":"The phrase describes adding something as part of the whole structure.","zh":"這個短語描述把某物作為整體結構的一部分加入。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":14},{"front":"a material such as starch","meaning":"澱粉等材料","examples":[{"en":"A material such as starch can help plastic break down.","zh":"澱粉等材料可以幫助塑膠分解。"},{"en":"A material such as starch means starch or another similar substance.","zh":"「a material such as starch」意思是澱粉或其他類似物質。"},{"en":"A food label may mention a material such as starch as a thickener.","zh":"食物標籤可能提到澱粉等材料作為增稠劑。"},{"en":"If starch is added to plastic, bacteria may attack the starch and weaken the plastic.","zh":"如果澱粉加入塑膠，細菌可能分解澱粉並削弱塑膠。"},{"en":"The phrase gives an example rather than a complete list.","zh":"這個短語提供例子，而不是完整清單。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":15},{"front":"attacked by bacteria","meaning":"受細菌分解","examples":[{"en":"Starch is attacked by bacteria.","zh":"澱粉受細菌分解。"},{"en":"Attacked by bacteria means broken down or acted on by bacteria.","zh":"「attacked by bacteria」意思是被細菌分解或作用。"},{"en":"Food left too long in a warm room can be attacked by bacteria.","zh":"食物在溫暖房間放太久可能受細菌分解。"},{"en":"If bacteria attack starch inside plastic, the plastic structure may weaken.","zh":"如果細菌分解塑膠內的澱粉，塑膠結構可能變弱。"},{"en":"The phrase describes biological breakdown.","zh":"這個短語描述生物分解。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":15},{"front":"causes the plastic to fall apart","meaning":"使塑膠分解","examples":[{"en":"Bacteria attack the starch and cause the plastic to fall apart.","zh":"細菌分解澱粉，並使塑膠分解。"},{"en":"Causes the plastic to fall apart means makes the plastic break into pieces or lose structure.","zh":"「causes the plastic to fall apart」意思是令塑膠破碎或失去結構。"},{"en":"Water can cause cheap cardboard to fall apart.","zh":"水可以令便宜紙板散開。"},{"en":"If bacteria break down part of the plastic, the whole material may weaken and separate.","zh":"如果細菌分解塑膠的一部分，整個材料可能變弱並分離。"},{"en":"The phrase describes the result of degradation.","zh":"這個短語描述降解的結果。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":15},{"front":"fall apart","meaning":"分解；散開","examples":[{"en":"The plastic falls apart after bacteria attack the starch.","zh":"細菌分解澱粉後，塑膠會分解。"},{"en":"To fall apart means to break into pieces or lose structure.","zh":"「fall apart」意思是破成碎片或失去結構。"},{"en":"An old book may fall apart if its pages are loose and dry.","zh":"如果舊書頁鬆脫又乾燥，它可能散開。"},{"en":"If biodegradable plastic falls apart, it no longer remains as one solid object.","zh":"如果可生物降解塑膠分解，它就不再保持為一個完整固體。"},{"en":"The phrase describes physical breakdown.","zh":"這個短語描述物理分解。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":15},{"front":"gradually decay in sunlight","meaning":"在陽光下逐漸分解","examples":[{"en":"Some materials gradually decay in sunlight.","zh":"有些材料在陽光下逐漸分解。"},{"en":"Gradually decay in sunlight means slowly break down when exposed to sunlight.","zh":"「gradually decay in sunlight」意思是在暴露於陽光時慢慢分解。"},{"en":"A plastic chair left outdoors may gradually fade and weaken in sunlight.","zh":"塑膠椅長期放在戶外，可能在陽光下逐漸褪色和變弱。"},{"en":"If a bottle decays too early, it may fail before it is used.","zh":"如果瓶子太早分解，它可能在使用前失效。"},{"en":"The phrase describes slow breakdown caused by light.","zh":"這個短語描述由光造成的緩慢分解。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":15},{"front":"stored in the dark","meaning":"存放於黑暗處","examples":[{"en":"Bottles made of such materials have to be stored in the dark.","zh":"由這些材料製成的瓶子必須存放於黑暗處。"},{"en":"Stored in the dark means kept away from light.","zh":"「stored in the dark」意思是存放在遠離光線的地方。"},{"en":"Some medicines must be stored in the dark so light does not damage them.","zh":"有些藥物必須存放於黑暗處，以免光線破壞它們。"},{"en":"If light makes a material decay, dark storage can delay breakdown.","zh":"如果光會令材料分解，黑暗儲存可以延遲分解。"},{"en":"The phrase describes a special storage condition.","zh":"這個短語描述特殊存放條件。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":15},{"front":"to ensure that","meaning":"確保","examples":[{"en":"The bottles are stored in the dark to ensure that they do not disintegrate too early.","zh":"這些瓶子存放於黑暗處，以確保它們不會太早分解。"},{"en":"To ensure that means to make certain that something happens or does not happen.","zh":"「to ensure that」意思是確保某事會或不會發生。"},{"en":"Students should check their answers to ensure that no question is missed.","zh":"學生應檢查答案，以確保沒有漏答問題。"},{"en":"If a product must last until use, storage rules help ensure that it remains safe.","zh":"如果產品必須維持到使用時，儲存規則有助確保它保持安全。"},{"en":"The phrase introduces the purpose of an action.","zh":"這個短語引出行動目的。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":15},{"front":"disintegrate before they have been used","meaning":"在使用前分解","examples":[{"en":"The bottles must not disintegrate before they have been used.","zh":"這些瓶子不能在使用前分解。"},{"en":"Disintegrate before they have been used means break down too early, before serving their purpose.","zh":"「disintegrate before they have been used」意思是在發揮用途前太早分解。"},{"en":"A paper bag should not fall apart before groceries reach home.","zh":"紙袋不應在雜貨到家前散開。"},{"en":"If biodegradable packaging breaks down too soon, it becomes useless.","zh":"如果可生物降解包裝太早分解，它就變得沒有用。"},{"en":"The phrase describes premature breakdown.","zh":"這個短語描述過早分解。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":15},{"front":"complete the table below","meaning":"完成下表","examples":[{"en":"Students complete the table below with information from the passage.","zh":"學生用文章中的資料完成下表。"},{"en":"Complete the table below means fill in the missing spaces in the table that follows.","zh":"「complete the table below」意思是填寫下方表格中的空格。"},{"en":"In a reading test, students may complete a table with names, dates, and uses.","zh":"在閱讀測驗中，學生可能用名稱、日期和用途完成表格。"},{"en":"If the table is incomplete, students must scan the passage for exact details.","zh":"如果表格不完整，學生必須掃讀文章尋找準確細節。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":15},{"front":"choose no more than three words","meaning":"選擇不多於三個字","examples":[{"en":"Students should choose no more than three words from the passage.","zh":"學生應從文章中選擇不多於三個字。"},{"en":"Choose no more than three words means write one, two, or three words only.","zh":"「choose no more than three words」意思是只寫一、二或三個字。"},{"en":"If the answer is “photographic film”, it fits a three-word limit.","zh":"如果答案是 “photographic film”，它符合三字限制。"},{"en":"If students write four words, the answer may be wrong even if the idea is correct.","zh":"如果學生寫四個字，即使意思正確，答案也可能錯。"},{"en":"The phrase sets a strict word limit.","zh":"這個短語設定嚴格字數限制。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":15},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must come from the passage.","zh":"答案必須來自文章。"},{"en":"From the passage means using words or information directly from the text.","zh":"「from the passage」意思是使用直接來自文本的字詞或資料。"},{"en":"In reading exams, students should not invent answers from their own knowledge.","zh":"在閱讀考試中，學生不應用自己的知識創作答案。"},{"en":"If answers must come from the passage, spelling and wording should follow the text closely.","zh":"如果答案必須來自文章，拼寫和用詞應盡量跟隨文本。"},{"en":"The phrase tells students to rely on the source.","zh":"這個短語告訴學生依賴來源。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":15},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生在答題紙上寫下答案。"},{"en":"An answer sheet is the official paper or form where exam answers are recorded.","zh":"「answer sheet」是記錄考試答案的正式紙張或表格。"},{"en":"A student may lose marks if answers are written only on the question paper.","zh":"如果答案只寫在試題紙上，學生可能失分。"},{"en":"If the answer sheet is not completed clearly, correct answers may not be marked.","zh":"如果答題紙沒有清楚填寫，正確答案可能不被評分。"},{"en":"The phrase names the place where answers must be written.","zh":"這個短語指出答案必須書寫的位置。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":16},{"front":"name of plastic","meaning":"塑膠名稱","examples":[{"en":"The table includes the name of plastic.","zh":"表格包括塑膠名稱。"},{"en":"Name of plastic means the specific name given to a plastic material.","zh":"「name of plastic」意思是某種塑膠材料的特定名稱。"},{"en":"In a science table, students may write “PVC” or “nylon” as the name of plastic.","zh":"在科學表格中，學生可能寫 “PVC” 或 “nylon” 作塑膠名稱。"},{"en":"If students confuse the plastic name with its use, the table answer may be wrong.","zh":"如果學生把塑膠名稱與用途混淆，表格答案可能錯。"},{"en":"The phrase identifies what material is being named.","zh":"這個短語指出正在命名的是甚麼材料。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":16},{"front":"date of invention","meaning":"發明日期","examples":[{"en":"The table asks for the date of invention.","zh":"表格要求填寫發明日期。"},{"en":"Date of invention means the year or time when something was invented.","zh":"「date of invention」意思是某物被發明的年份或時間。"},{"en":"A history worksheet may ask for the date of invention of the telephone.","zh":"歷史工作紙可能要求填寫電話的發明日期。"},{"en":"If a table asks for a date, students should look for years such as 1907 or the 1930s.","zh":"如果表格要求日期，學生應尋找1907或1930年代等年份。"},{"en":"The phrase focuses on when an invention first appeared.","zh":"這個短語集中於發明首次出現的時間。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":16},{"front":"country of origin","meaning":"原產國；來源國家","examples":[{"en":"The country of origin is listed for each plastic.","zh":"每種塑膠都列出原產國。"},{"en":"Country of origin means the country where something first came from or was developed.","zh":"「country of origin」意思是某物最初來自或被發展出來的國家。"},{"en":"A food label may show the country of origin of fruit or meat.","zh":"食物標籤可能顯示水果或肉類的原產國。"},{"en":"If a plastic was developed in Germany, Germany is its country of origin in the table.","zh":"如果一種塑膠在德國發展出來，德國就是表格中的來源國家。"},{"en":"The phrase identifies geographical source.","zh":"這個短語指出地理來源。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":16},{"front":"common use","meaning":"常見用途","examples":[{"en":"The table shows a common use of each plastic.","zh":"表格顯示每種塑膠的常見用途。"},{"en":"Common use means a frequent or typical way something is used.","zh":"「common use」意思是某物常見或典型的使用方式。"},{"en":"A common use of paper is printing worksheets and notices.","zh":"紙張的常見用途是打印工作紙和通告。"},{"en":"If a plastic is listed with a common use, students should find an everyday product made from it.","zh":"如果塑膠列有常見用途，學生應找出由它製成的日常產品。"},{"en":"The phrase focuses on practical application.","zh":"這個短語集中於實際應用。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":16},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"Students decide whether the following statements agree with the passage.","zh":"學生判斷以下陳述是否與文章一致。"},{"en":"Do the following statements agree with means students must judge if the statements match the text.","zh":"「do the following statements agree with」意思是學生必須判斷陳述是否符合文本。"},{"en":"In reading tests, students should check each statement against exact evidence.","zh":"在閱讀測驗中，學生應把每句陳述與準確證據核對。"},{"en":"If a statement adds information not in the passage, it may not agree with the text.","zh":"如果陳述加入文章沒有的資料，它可能不與文本一致。"},{"en":"The phrase introduces a TRUE/FALSE/NOT GIVEN task.","zh":"這個短語引入 TRUE/FALSE/NOT GIVEN 題型。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":16},{"front":"agree with the information given","meaning":"與所提供資料一致","examples":[{"en":"A statement may agree with the information given in the passage.","zh":"陳述可能與文章所提供資料一致。"},{"en":"Agree with the information given means match what the text says.","zh":"「agree with the information given」意思是符合文本所說。"},{"en":"If a passage says Bakelite cannot be softened by heat, the same statement agrees with the information.","zh":"如果文章說電木不能通過加熱軟化，相同陳述就與資料一致。"},{"en":"Students should choose TRUE only when the passage clearly supports the statement.","zh":"只有當文章清楚支持陳述時，學生才應選 TRUE。"},{"en":"The phrase reminds learners to use textual evidence.","zh":"這個短語提醒學習者使用文本證據。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":16},{"front":"contradicts the information","meaning":"與資料相矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與文章資料相矛盾。"},{"en":"Contradicts the information means says the opposite of what the text says.","zh":"「contradicts the information」意思是說出與文本所說相反的內容。"},{"en":"If the passage says nylon was created in the 1930s, saying it was created in 1907 contradicts the information.","zh":"如果文章說尼龍在1930年代被創造，說它在1907年被創造就與資料矛盾。"},{"en":"When a statement contradicts the text, students should choose FALSE.","zh":"當陳述與文本矛盾時，學生應選 FALSE。"},{"en":"The phrase describes a clear conflict with the passage.","zh":"這個短語描述與文章的清楚衝突。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":16},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"Not Given means that there is no information on this in the passage.","zh":"NOT GIVEN 意思是文章中沒有相關資料。"},{"en":"No information on this means the text does not say whether the idea is true or false.","zh":"「no information on this」意思是文本沒有說該想法是真還是假。"},{"en":"If a passage never mentions the price of a plastic, there is no information on this.","zh":"如果文章從未提到某塑膠的價格，就沒有相關資料。"},{"en":"Students should not use outside knowledge when the passage gives no evidence.","zh":"當文章沒有證據時，學生不應使用外部知識。"},{"en":"The phrase is essential for NOT GIVEN answers.","zh":"這個短語對 NOT GIVEN 答案很重要。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":16},{"front":"chemical structure","meaning":"化學結構","examples":[{"en":"The question asks about the chemical structure of plastic and rubber.","zh":"問題問塑膠和橡膠的化學結構。"},{"en":"Chemical structure means the way atoms and molecules are arranged in a substance.","zh":"「chemical structure」是原子和分子在物質中的排列方式。"},{"en":"A chemistry diagram can show the chemical structure of water.","zh":"化學圖可以顯示水的化學結構。"},{"en":"If two materials have similar structures, they may share some properties.","zh":"如果兩種材料有相似結構，它們可能共享一些特性。"},{"en":"The phrase focuses on internal molecular arrangement.","zh":"這個短語集中於內部分子排列。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":16},{"front":"very different from","meaning":"與……非常不同","examples":[{"en":"The question asks whether plastic is very different from rubber.","zh":"問題問塑膠是否與橡膠非常不同。"},{"en":"Very different from means unlike something in an important way.","zh":"「very different from」意思是在重要方面不像某物。"},{"en":"Online learning can be very different from learning in a classroom.","zh":"網上學習可以與課室學習非常不同。"},{"en":"If plastic and rubber share polymer principles, they may not be completely different chemically.","zh":"如果塑膠和橡膠共享聚合物原理，它們在化學上未必完全不同。"},{"en":"The phrase highlights strong contrast.","zh":"這個短語強調強烈對比。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":16},{"front":"react to heat","meaning":"對熱作出反應","examples":[{"en":"The question compares how Celluloid and Bakelite react to heat.","zh":"問題比較賽璐珞和電木如何對熱作出反應。"},{"en":"React to heat means change or behave in a particular way when heated.","zh":"「react to heat」意思是在受熱時以特定方式改變或表現。"},{"en":"Butter and chocolate react to heat by melting.","zh":"牛油和朱古力對熱作出反應時會融化。"},{"en":"If one plastic softens when heated and another does not, they react to heat differently.","zh":"如果一種塑膠受熱會軟化，而另一種不會，它們對熱的反應就不同。"},{"en":"The phrase describes behaviour under temperature change.","zh":"這個短語描述在溫度變化下的行為。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":17},{"front":"in the same way","meaning":"以相同方式","examples":[{"en":"Celluloid and Bakelite do not behave in the same way when heated.","zh":"賽璐珞和電木受熱時並不以相同方式表現。"},{"en":"In the same way means using the same method or showing the same behaviour.","zh":"「in the same way」意思是使用相同方法或顯示相同行為。"},{"en":"Two students may solve a maths problem in the same way.","zh":"兩名學生可能以相同方式解數學題。"},{"en":"If two plastics react differently to heat, they cannot be processed in the same way.","zh":"如果兩種塑膠對熱反應不同，它們就不能以相同方式加工。"},{"en":"The phrase compares similarity of action or behaviour.","zh":"這個短語比較行動或行為上的相似性。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":17},{"front":"combining different types of plastic","meaning":"混合不同種類的塑膠","examples":[{"en":"Combining different types of plastic can make recycling more difficult.","zh":"混合不同種類的塑膠可以令回收更困難。"},{"en":"Combining different types of plastic means mixing plastics with different properties or chemical structures.","zh":"「combining different types of plastic」意思是混合具有不同特性或化學結構的塑膠。"},{"en":"A recycling bin may ask people not to combine food waste with plastic bottles.","zh":"回收箱可能要求人們不要把廚餘與膠樽混在一起。"},{"en":"If different plastics are mixed, they may need separate treatments but become hard to sort.","zh":"如果不同塑膠混合，它們可能需要分開處理，但會變得難以分類。"},{"en":"The phrase explains one reason recycling can be complicated.","zh":"這個短語解釋回收可能複雜的一個原因。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":17},{"front":"make recycling more difficult","meaning":"令回收更困難","examples":[{"en":"Combining plastics can make recycling more difficult.","zh":"混合塑膠可以令回收更困難。"},{"en":"To make recycling more difficult means to create obstacles in turning waste into reusable material.","zh":"「make recycling more difficult」意思是為把廢物變成可再用材料製造障礙。"},{"en":"Food left inside containers can make recycling more difficult.","zh":"容器內留下食物可以令回收更困難。"},{"en":"If plastics cannot be separated easily, recycling takes more time and money.","zh":"如果塑膠不能容易分開，回收就需要更多時間和金錢。"},{"en":"The phrase describes an action that complicates waste processing.","zh":"這個短語描述令廢物處理更複雜的行動。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":17},{"front":"adding starch to plastic","meaning":"在塑膠中加入澱粉","examples":[{"en":"Adding starch to plastic can make it biodegradable.","zh":"在塑膠中加入澱粉可以令它可生物降解。"},{"en":"Adding starch to plastic means putting starch into the plastic’s structure or mixture.","zh":"「adding starch to plastic」意思是把澱粉加入塑膠的結構或混合物中。"},{"en":"A manufacturer may add starch to packaging to help it break down after use.","zh":"製造商可能在包裝中加入澱粉，以幫助它使用後分解。"},{"en":"If bacteria attack the starch, the plastic may weaken and fall apart.","zh":"如果細菌分解澱粉，塑膠可能變弱並分解。"},{"en":"The phrase describes one method for making plastic less permanent.","zh":"這個短語描述令塑膠不那麼永久的一種方法。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":17},{"front":"make it more durable","meaning":"令它更耐用","examples":[{"en":"The question asks whether adding starch to plastic can make it more durable.","zh":"問題問在塑膠中加入澱粉是否可以令它更耐用。"},{"en":"To make it more durable means to make it last longer and resist damage better.","zh":"「make it more durable」意思是令它更持久並更能抵抗損壞。"},{"en":"A phone case can make a phone more durable by protecting it from drops.","zh":"電話殼可以透過防摔令電話更耐用。"},{"en":"Adding starch is meant to help plastic break down, not make it last longer.","zh":"加入澱粉的目的是幫助塑膠分解，而不是令它更持久。"},{"en":"The phrase describes increasing strength or lifespan.","zh":"這個短語描述增加強度或使用壽命。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":17},{"front":"stored under special conditions","meaning":"在特殊條件下存放","examples":[{"en":"Some plastic containers have to be stored under special conditions.","zh":"有些塑膠容器必須在特殊條件下存放。"},{"en":"Stored under special conditions means kept in a particular environment to prevent damage or early change.","zh":"「stored under special conditions」意思是保存在特定環境中，以防損壞或過早變化。"},{"en":"Some medicines must be stored under special conditions, such as cool temperature and darkness.","zh":"有些藥物必須在低溫和黑暗等特殊條件下存放。"},{"en":"If sunlight makes a bottle disintegrate too early, it must be stored carefully.","zh":"如果陽光令瓶子太早分解，它就必須小心存放。"},{"en":"The phrase describes storage rules needed to protect a product.","zh":"這個短語描述保護產品所需的存放規則。"}],"source":"46 - The Development of Plastics.pdf","sourcePage":17}],"ielts/reading/passage-2/Practice 47":[{"front":"the history of the pencil","meaning":"鉛筆的歷史","examples":[{"en":"The history of the pencil began with the discovery of graphite.","zh":"鉛筆的歷史始於石墨的發現。"},{"en":"The history of the pencil explains how a simple writing tool developed from raw graphite into the modern pencil.","zh":"鉛筆的歷史解釋一種簡單書寫工具如何由原始石墨發展成現代鉛筆。"},{"en":"A museum display may show the history of the pencil through old graphite sticks, wooden casings and factory-made pencils.","zh":"博物館展覽可能透過舊石墨棒、木殼和工廠製造的鉛筆展示鉛筆的歷史。"},{"en":"Studying the history of the pencil helps students see how everyday objects often come from long processes of invention.","zh":"研究鉛筆的歷史幫助學生明白，日常物品往往來自漫長的發明過程。"},{"en":"The phrase refers to the development of pencils over time, not just one inventor or one date.","zh":"這個短語指鉛筆隨時間的發展，而不只是某一位發明者或某一個日期。"}],"source":"47 - The History of Pencil.pdf","sourcePage":1},{"front":"began with","meaning":"由……開始","examples":[{"en":"The story of the pencil began with a lightning strike.","zh":"鉛筆的故事由一次雷擊開始。"},{"en":"Began with means started from a particular event, action or situation.","zh":"“Began with” 指由某個特定事件、行動或情況開始。"},{"en":"The school project began with one student asking why so much food was wasted at lunch.","zh":"學校項目由一名學生問為何午餐浪費這麼多食物開始。"},{"en":"If a story began with an accident, that accident becomes the starting point of later events.","zh":"如果一個故事由意外開始，該意外就成為後來事件的起點。"},{"en":"The phrase helps explain the first cause or first step in a process.","zh":"這個短語幫助解釋一個過程的第一個原因或第一步。"}],"source":"47 - The History of Pencil.pdf","sourcePage":1},{"front":"a lightning strike","meaning":"雷擊","examples":[{"en":"The story of the pencil began with a lightning strike.","zh":"鉛筆的故事由一次雷擊開始。"},{"en":"A lightning strike is the moment when lightning hits a place, object or person.","zh":"雷擊是閃電擊中某地方、物件或人的一刻。"},{"en":"A lightning strike can damage a tree, a building or electrical equipment during a storm.","zh":"在暴風雨期間，雷擊可以損壞樹木、建築物或電力設備。"},{"en":"If a lightning strike exposes something underground, people may discover materials they had not noticed before.","zh":"如果雷擊暴露地下的東西，人們可能發現以前沒有注意到的材料。"},{"en":"The phrase describes a sudden natural event caused by electricity in the sky.","zh":"這個短語描述由天空中的電引起的突然自然事件。"}],"source":"47 - The History of Pencil.pdf","sourcePage":1},{"front":"graphite","meaning":"石墨","examples":[{"en":"Graphite is the principal material used to make pencils.","zh":"石墨是用來製造鉛筆的主要材料。"},{"en":"Graphite is a soft black form of carbon that can leave dark marks on paper.","zh":"石墨是一種柔軟的黑色碳，可在紙上留下深色痕跡。"},{"en":"Students use graphite every time they write with an ordinary pencil.","zh":"學生每次用普通鉛筆書寫時，都在使用石墨。"},{"en":"Because graphite marks can be erased, pencils are useful for sketching, calculation and drafts.","zh":"因為石墨痕跡可以擦掉，鉛筆適合素描、計算和草稿。"},{"en":"The word refers to the writing material inside a pencil, even though people often call it “lead.”","zh":"這個詞指鉛筆內的書寫材料，雖然人們常稱它為「鉛」。"}],"source":"47 - The History of Pencil.pdf","sourcePage":1},{"front":"the principal material","meaning":"主要材料","examples":[{"en":"Graphite is the principal material used to make pencils.","zh":"石墨是用來製造鉛筆的主要材料。"},{"en":"The principal material is the main substance used to make something.","zh":"主要材料是用來製造某物的主要物質。"},{"en":"Flour is the principal material in many kinds of bread.","zh":"麵粉是許多麵包的主要材料。"},{"en":"If the principal material changes, the quality and use of a product may also change.","zh":"如果主要材料改變，產品的質素和用途也可能改變。"},{"en":"The phrase identifies the most important material, not every small ingredient.","zh":"這個短語指出最重要的材料，而不是每一種小成分。"}],"source":"47 - The History of Pencil.pdf","sourcePage":1},{"front":"be used to make","meaning":"被用來製造","examples":[{"en":"Graphite is used to make the core of a pencil.","zh":"石墨被用來製造鉛筆芯。"},{"en":"To be used to make something means to serve as a material or tool for producing it.","zh":"“Be used to make” 某物指作為材料或工具來製造它。"},{"en":"Wood is used to make tables, chairs and pencils.","zh":"木材被用來製造桌子、椅子和鉛筆。"},{"en":"If a material is easy to shape, it may be used to make many everyday products.","zh":"如果材料容易塑形，就可能被用來製造許多日常產品。"},{"en":"The phrase explains the purpose of a material.","zh":"這個短語解釋材料的用途。"}],"source":"47 - The History of Pencil.pdf","sourcePage":1},{"front":"be discovered at","meaning":"在……被發現","examples":[{"en":"Graphite was discovered at Borrowdale in England in 1564.","zh":"石墨於1564年在英格蘭 Borrowdale 被發現。"},{"en":"To be discovered at a place means to be found there for the first time or recognised there as important.","zh":"“Be discovered at” 某地指在該地首次被發現，或在該地被認出其重要性。"},{"en":"A new fossil may be discovered at a construction site after workers dig into the ground.","zh":"工人在建築地盤掘地後，可能在那裡發現新化石。"},{"en":"If a valuable mineral is discovered at a location, that place may become economically important.","zh":"如果貴重礦物在某地被發現，該地可能變得具有經濟重要性。"},{"en":"The phrase gives the place where a discovery happened.","zh":"這個短語給出發現發生的地點。"}],"source":"47 - The History of Pencil.pdf","sourcePage":1},{"front":"strike a local tree","meaning":"擊中一棵本地樹木","examples":[{"en":"Lightning struck a local tree during a storm.","zh":"暴風雨期間，閃電擊中一棵本地樹木。"},{"en":"To strike a local tree means for lightning or another force to hit a tree in the area.","zh":"“Strike a local tree” 指閃電或另一種力量擊中該地區的一棵樹。"},{"en":"During heavy rain, lightning may strike a local tree and split its trunk.","zh":"大雨期間，閃電可能擊中一棵本地樹木並劈開樹幹。"},{"en":"If lightning strikes a tree, the ground around its roots may be disturbed or exposed.","zh":"如果閃電擊中樹木，樹根周圍的泥土可能被擾動或暴露。"},{"en":"The phrase describes a sudden impact on a nearby tree.","zh":"這個短語描述對附近樹木的突然撞擊。"}],"source":"47 - The History of Pencil.pdf","sourcePage":1},{"front":"during a storm","meaning":"在暴風雨期間","examples":[{"en":"Lightning struck a local tree during a storm.","zh":"暴風雨期間，閃電擊中一棵本地樹木。"},{"en":"During a storm means while strong wind, rain, thunder or lightning is happening.","zh":"“During a storm” 指強風、大雨、雷聲或閃電發生的時候。"},{"en":"People should avoid standing under tall trees during a storm.","zh":"在暴風雨期間，人們應避免站在高樹下。"},{"en":"If something happens during a storm, weather conditions may be part of the cause.","zh":"如果某事在暴風雨期間發生，天氣狀況可能是原因之一。"},{"en":"The phrase gives the time and weather setting of an event.","zh":"這個短語給出事件的時間和天氣背景。"}],"source":"47 - The History of Pencil.pdf","sourcePage":1},{"front":"a local tree","meaning":"一棵本地樹木","examples":[{"en":"Lightning struck a local tree during a storm.","zh":"暴風雨期間，閃電擊中一棵本地樹木。"},{"en":"A local tree is a tree growing in the nearby area or community.","zh":"本地樹木是在附近地區或社區生長的樹。"},{"en":"Children may recognise a local tree because they pass it every day on the way to school.","zh":"孩子可能認得一棵本地樹木，因為他們每天上學途中都經過它。"},{"en":"If a local tree is damaged, people nearby may notice the change quickly.","zh":"如果一棵本地樹木受損，附近的人可能很快注意到變化。"},{"en":"The phrase places the tree in a familiar local setting.","zh":"這個短語把樹木放在熟悉的本地環境中。"}],"source":"47 - The History of Pencil.pdf","sourcePage":1},{"front":"the black substance","meaning":"黑色物質","examples":[{"en":"Local people found that the black substance differed from ash.","zh":"當地人發現這種黑色物質與灰燼不同。"},{"en":"The black substance means the dark material that people found near the tree roots.","zh":"黑色物質指人們在樹根附近發現的深色材料。"},{"en":"If children find a black substance on the floor, they may first think it is dirt or ash.","zh":"如果孩子在地上發現黑色物質，可能先以為它是泥或灰。"},{"en":"When a black substance leaves marks, people may become curious about what it is.","zh":"當黑色物質會留下痕跡，人們可能會好奇它是甚麼。"},{"en":"The phrase identifies an unknown dark material before its name is explained.","zh":"這個短語在解釋名稱前，先指出一種未知的深色材料。"}],"source":"47 - The History of Pencil.pdf","sourcePage":1},{"front":"at the roots of","meaning":"在……的根部","examples":[{"en":"The black substance was found at the roots of the tree.","zh":"這種黑色物質在樹的根部被發現。"},{"en":"At the roots of something means near the underground part that holds and feeds a plant.","zh":"“At the roots of” 某植物指在支撐和供養植物的地下部分附近。"},{"en":"Gardeners may find insects at the roots of a plant when they pull it from the soil.","zh":"園丁把植物從泥土中拔出時，可能在其根部發現昆蟲。"},{"en":"If a material is found at the roots of a tree, digging or damage may have exposed it.","zh":"如果材料在樹根部被發現，挖掘或損壞可能已把它暴露出來。"},{"en":"The phrase gives the exact position near the base of a plant.","zh":"這個短語給出靠近植物底部的準確位置。"}],"source":"47 - The History of Pencil.pdf","sourcePage":2},{"front":"differ from","meaning":"與……不同","examples":[{"en":"The black substance differed from the ash of burnt wood.","zh":"這種黑色物質與燒焦木材的灰燼不同。"},{"en":"To differ from something means to be unlike it in one or more ways.","zh":"“Differ from” 某物指在一個或多個方面與它不一樣。"},{"en":"A pencil differs from a pen because its marks can usually be erased.","zh":"鉛筆與原子筆不同，因為鉛筆痕跡通常可以擦掉。"},{"en":"If two materials differ in weight and texture, people can tell they are not the same.","zh":"如果兩種材料在重量和質地上不同，人們就能判斷它們不是同一物質。"},{"en":"The phrase is useful for comparing differences.","zh":"這個短語適合用來比較差異。"}],"source":"47 - The History of Pencil.pdf","sourcePage":2},{"front":"the ash of burnt wood","meaning":"燒焦木材的灰燼","examples":[{"en":"The substance differed from the ash of burnt wood.","zh":"這種物質與燒焦木材的灰燼不同。"},{"en":"The ash of burnt wood is the soft grey or black powder left after wood has burned.","zh":"燒焦木材的灰燼是木材燃燒後留下的柔軟灰色或黑色粉末。"},{"en":"After a campfire, the ash of burnt wood may remain in the fire pit.","zh":"營火過後，燒焦木材的灰燼可能留在火坑中。"},{"en":"If a black material is heavier or smoother than ash, people may suspect it is something else.","zh":"如果黑色材料比灰燼更重或更光滑，人們可能懷疑它是其他物質。"},{"en":"The phrase describes the remains of burned wood.","zh":"這個短語描述木材燃燒後的殘留物。"}],"source":"47 - The History of Pencil.pdf","sourcePage":2},{"front":"be soft and leave marks","meaning":"質地柔軟並留下痕跡","examples":[{"en":"The substance was soft and left marks everywhere.","zh":"這種物質質地柔軟，並到處留下痕跡。"},{"en":"To be soft and leave marks means to have a texture that rubs off easily onto surfaces.","zh":"“Be soft and leave marks” 指質地容易磨落到表面上。"},{"en":"Chalk is soft and leaves marks on a blackboard when a teacher writes with it.","zh":"粉筆質地柔軟，老師用它書寫時會在黑板上留下痕跡。"},{"en":"If a material leaves marks everywhere, people may need to wrap or contain it before using it.","zh":"如果材料到處留下痕跡，人們可能需要先把它包起或固定才使用。"},{"en":"The phrase explains why graphite needed some kind of casing.","zh":"這個短語解釋為何石墨需要某種外殼。"}],"source":"47 - The History of Pencil.pdf","sourcePage":2},{"front":"leave marks everywhere","meaning":"到處留下痕跡","examples":[{"en":"The soft substance left marks everywhere.","zh":"這種柔軟物質到處留下痕跡。"},{"en":"To leave marks everywhere means to make visible stains or lines on many surfaces.","zh":"“Leave marks everywhere” 指在許多表面留下可見污漬或線條。"},{"en":"A wet umbrella may leave marks everywhere if it drips across the classroom floor.","zh":"如果濕雨傘滴水穿過課室地板，可能到處留下痕跡。"},{"en":"If graphite leaves marks everywhere, it is useful for writing but messy to hold.","zh":"如果石墨到處留下痕跡，它適合書寫，但拿在手上很容易弄污。"},{"en":"The phrase shows both usefulness and inconvenience.","zh":"這個短語同時顯示用途和不便。"}],"source":"47 - The History of Pencil.pdf","sourcePage":2},{"front":"chemistry was still in its infancy","meaning":"化學仍處於起步階段","examples":[{"en":"Chemistry was still in its infancy when graphite was discovered.","zh":"石墨被發現時，化學仍處於起步階段。"},{"en":"If chemistry was still in its infancy, the science was still young and not fully developed.","zh":"如果化學仍處於起步階段，這門科學仍然年輕，尚未完全發展。"},{"en":"In the early days of medicine, many treatments were used when medical science was still in its infancy.","zh":"在醫學早期，許多療法是在醫學仍處於起步階段時使用的。"},{"en":"When a field is in its infancy, people may misunderstand new materials or causes.","zh":"當一個領域處於起步階段，人們可能誤解新材料或原因。"},{"en":"The phrase explains why people confused graphite with lead.","zh":"這個短語解釋為何人們把石墨誤認為鉛。"}],"source":"47 - The History of Pencil.pdf","sourcePage":2},{"front":"be in its infancy","meaning":"仍處於初期階段","examples":[{"en":"Chemistry was still in its infancy at that time.","zh":"當時，化學仍處於初期階段。"},{"en":"To be in its infancy means to be at an early stage of development.","zh":"“Be in its infancy” 指處於發展的早期階段。"},{"en":"Online shopping was in its infancy when only a few people trusted internet payments.","zh":"當只有少數人信任網上付款時，網上購物仍處於初期階段。"},{"en":"If a technology is in its infancy, many problems have not yet been solved.","zh":"如果一項科技處於初期階段，許多問題仍未解決。"},{"en":"The phrase describes something new and not yet mature.","zh":"這個短語描述某事新近出現且尚未成熟。"}],"source":"47 - The History of Pencil.pdf","sourcePage":2},{"front":"mistake something for something","meaning":"誤以為……是……","examples":[{"en":"People mistook the substance for lead.","zh":"人們誤以為這種物質是鉛。"},{"en":"To mistake something for something else means to wrongly believe it is another thing.","zh":"“Mistake something for something else” 指錯誤地以為某物是另一物。"},{"en":"A child may mistake salt for sugar if both are kept in similar jars.","zh":"如果鹽和糖放在相似罐子裏，孩子可能誤以為鹽是糖。"},{"en":"If two materials look alike, people can easily mistake one for the other.","zh":"如果兩種材料看起來相似，人們很容易把其中一種誤認為另一種。"},{"en":"The phrase describes incorrect identification.","zh":"這個短語描述錯誤識別。"}],"source":"47 - The History of Pencil.pdf","sourcePage":2},{"front":"equally black","meaning":"同樣是黑色","examples":[{"en":"Lead is equally black but much heavier than graphite.","zh":"鉛同樣是黑色，但比石墨重得多。"},{"en":"Equally black means black to the same degree or in the same visible way.","zh":"“Equally black” 指黑色程度相同，或外觀上同樣黑。"},{"en":"Two school shoes may be equally black, but one pair may be much more comfortable.","zh":"兩雙校鞋可能同樣是黑色，但其中一雙可能舒服得多。"},{"en":"If two substances are equally black, people may confuse them by appearance alone.","zh":"如果兩種物質同樣是黑色，人們可能只憑外觀就把它們混淆。"},{"en":"The phrase compares colour similarity while allowing other differences.","zh":"這個短語比較顏色相似，同時容許其他差異存在。"}],"source":"47 - The History of Pencil.pdf","sourcePage":2},{"front":"much heavier","meaning":"重得多","examples":[{"en":"Lead is much heavier than graphite.","zh":"鉛比石墨重得多。"},{"en":"Much heavier means far greater in weight.","zh":"“Much heavier” 指重量大得多。"},{"en":"A metal water bottle is much heavier than a plastic one when both are full.","zh":"當金屬水樽和塑膠水樽都裝滿水時，金屬水樽重得多。"},{"en":"If one material is much heavier, carrying it or shaping it may require more effort.","zh":"如果一種材料重得多，搬運或塑形它可能需要更多力氣。"},{"en":"The phrase makes a strong weight comparison.","zh":"這個短語作出強烈重量比較。"}],"source":"47 - The History of Pencil.pdf","sourcePage":2},{"front":"mark their sheep for ownership","meaning":"為了標示擁有權而標記羊隻","examples":[{"en":"Local people used graphite to mark their sheep for ownership.","zh":"當地人使用石墨標記羊隻，以標示擁有權。"},{"en":"To mark animals for ownership means to put a sign on them so others know who owns them.","zh":"為動物標示擁有權而作標記，指在牠們身上留下記號，讓別人知道牠們屬於誰。"},{"en":"Farmers may mark tools, bags or animals so they do not get mixed up with others’.","zh":"農民可能標記工具、袋子或動物，避免與別人的東西混淆。"},{"en":"If sheep wander between farms, ownership marks help people return them to the right owner.","zh":"如果羊隻在農場之間走失，擁有權標記可幫助人們把牠們交還正確主人。"},{"en":"The phrase explains an early practical use of graphite.","zh":"這個短語解釋石墨早期的一種實際用途。"}],"source":"47 - The History of Pencil.pdf","sourcePage":2},{"front":"ownership and counting","meaning":"擁有權和點算","examples":[{"en":"Graphite was used for ownership and counting.","zh":"石墨被用於標示擁有權和點算。"},{"en":"Ownership and counting means showing who something belongs to and keeping track of numbers.","zh":"擁有權和點算指顯示某物屬於誰，並記錄數量。"},{"en":"A teacher may use labels and a checklist for ownership and counting of classroom books.","zh":"老師可能用標籤和清單來處理課室書本的擁有權和點算。"},{"en":"If farmers mark animals, they can prove ownership and count their flock more easily.","zh":"如果農民標記動物，就能更容易證明擁有權並點算羊群。"},{"en":"The phrase shows two practical reasons for making marks.","zh":"這個短語顯示作標記的兩個實際原因。"}],"source":"47 - The History of Pencil.pdf","sourcePage":3},{"front":"a major source of","meaning":"……的主要來源","examples":[{"en":"Britain became a major source of mined graphite.","zh":"英國成為開採石墨的主要來源。"},{"en":"A major source of something is an important place or supply from which it comes.","zh":"某物的主要來源，是它的重要產地或供應來源。"},{"en":"A library can be a major source of information for students doing research.","zh":"圖書館可以是學生做研究時的主要資料來源。"},{"en":"If a country becomes a major source of a mineral, other countries may depend on its supply.","zh":"如果一個國家成為某種礦物的主要來源，其他國家可能依賴其供應。"},{"en":"The phrase identifies an important provider.","zh":"這個短語指出重要供應者。"}],"source":"47 - The History of Pencil.pdf","sourcePage":3},{"front":"mined graphite","meaning":"開採得來的石墨","examples":[{"en":"Britain became a major source of mined graphite.","zh":"英國成為開採得來的石墨的主要來源。"},{"en":"Mined graphite is graphite taken from the earth through mining.","zh":"開採得來的石墨是透過採礦從地下取得的石墨。"},{"en":"Mined coal, mined copper and mined graphite all come from underground deposits.","zh":"開採得來的煤、銅和石墨都來自地下礦床。"},{"en":"If mined graphite is pure, it can be valuable for pencils and other uses.","zh":"如果開採得來的石墨很純淨，就可能對鉛筆和其他用途有價值。"},{"en":"The phrase distinguishes natural extracted graphite from manufactured materials.","zh":"這個短語把天然開採的石墨與人造材料區分開來。"}],"source":"47 - The History of Pencil.pdf","sourcePage":3},{"front":"be invented elsewhere","meaning":"在其他地方被發明","examples":[{"en":"The first pencil was invented elsewhere.","zh":"第一支鉛筆是在其他地方被發明的。"},{"en":"To be invented elsewhere means to be created in another place, not in the place just mentioned.","zh":"“Be invented elsewhere” 指在剛才提及地點以外的另一地方被創造。"},{"en":"A product may use local materials but be invented elsewhere by people in another country.","zh":"一件產品可能使用本地材料，但由另一個國家的人在其他地方發明。"},{"en":"If graphite came from Britain but the pencil was invented elsewhere, the material and the invention have different origins.","zh":"如果石墨來自英國，但鉛筆在其他地方被發明，材料和發明就有不同來源。"},{"en":"The phrase corrects a possible misunderstanding about location.","zh":"這個短語糾正關於地點的可能誤解。"}],"source":"47 - The History of Pencil.pdf","sourcePage":3},{"front":"require some form of","meaning":"需要某種形式的……","examples":[{"en":"Because graphite is soft, it requires some form of casing.","zh":"由於石墨柔軟，它需要某種形式的外殼。"},{"en":"To require some form of something means to need a type of support, protection or solution.","zh":"“Require some form of” 某物指需要某種類型的支援、保護或解決方法。"},{"en":"A fragile phone screen requires some form of protection, such as a case or cover.","zh":"脆弱的手機螢幕需要某種形式的保護，例如手機殼或保護貼。"},{"en":"If a material is messy to hold, it may require some form of wrapper before everyday use.","zh":"如果材料拿在手上容易弄污，就可能需要某種形式的包裹物才適合日常使用。"},{"en":"The phrase shows a need without naming one exact method.","zh":"這個短語顯示需要，但不指定一種確切方法。"}],"source":"47 - The History of Pencil.pdf","sourcePage":3},{"front":"casing","meaning":"外殼；保護套","examples":[{"en":"Graphite requires some form of casing.","zh":"石墨需要某種形式的外殼。"},{"en":"Casing is an outer covering that holds, protects or contains something inside.","zh":"外殼是固定、保護或包住內部物件的外層。"},{"en":"A phone casing protects the phone from scratches and drops.","zh":"手機保護殼保護手機免受刮花和摔跌。"},{"en":"If graphite has a casing, people can hold it without making their hands too dirty.","zh":"如果石墨有外殼，人們就可以拿着它，而不會把手弄得太髒。"},{"en":"The word refers to an outer protective layer.","zh":"這個詞指外部保護層。"}],"source":"47 - The History of Pencil.pdf","sourcePage":3},{"front":"graphite sticks","meaning":"石墨棒","examples":[{"en":"Graphite sticks were initially wrapped in string or sheepskin.","zh":"石墨棒最初被包裹在繩子或羊皮裏。"},{"en":"Graphite sticks are narrow pieces of graphite shaped so they can be held and used for marking.","zh":"石墨棒是被塑造成可拿着並用來作標記的細長石墨。"},{"en":"Before wooden pencils, people might use graphite sticks like simple drawing tools.","zh":"在木殼鉛筆之前，人們可能像使用簡單繪圖工具一樣使用石墨棒。"},{"en":"If graphite sticks are unwrapped, they can easily dirty the user’s hands.","zh":"如果石墨棒沒有包裹，就很容易弄污使用者的手。"},{"en":"The phrase describes an early form of pencil material.","zh":"這個短語描述鉛筆材料的早期形式。"}],"source":"47 - The History of Pencil.pdf","sourcePage":3},{"front":"initially wrapped in","meaning":"最初被包裹在……裏","examples":[{"en":"Graphite sticks were initially wrapped in string or sheepskin.","zh":"石墨棒最初被包裹在繩子或羊皮裏。"},{"en":"Initially wrapped in means covered with something at the beginning or in the earliest stage.","zh":"“Initially wrapped in” 指在開始或最早階段被某物包住。"},{"en":"A gift may be initially wrapped in paper before being placed in a box.","zh":"禮物可能最初被包在紙裏，然後放進盒子。"},{"en":"If a tool is initially wrapped in simple material, later designs may improve the covering.","zh":"如果工具最初被簡單材料包裹，後來設計可能改善其外層。"},{"en":"The phrase describes the first protective method used.","zh":"這個短語描述最初使用的保護方法。"}],"source":"47 - The History of Pencil.pdf","sourcePage":3},{"front":"string or sheepskin","meaning":"繩子或羊皮","examples":[{"en":"Graphite sticks were wrapped in string or sheepskin.","zh":"石墨棒被包裹在繩子或羊皮裏。"},{"en":"String or sheepskin refers to simple materials used to cover or hold early graphite sticks.","zh":"繩子或羊皮指用來包住或固定早期石墨棒的簡單材料。"},{"en":"A farmer might use string to tie tools together or animal skin to protect a handle.","zh":"農民可能用繩子把工具綁在一起，或用動物皮保護手柄。"},{"en":"If string or sheepskin wraps graphite, the user can grip it more easily.","zh":"如果繩子或羊皮包住石墨，使用者就更容易握住它。"},{"en":"The phrase shows that early pencil casings were simple and practical.","zh":"這個短語顯示早期鉛筆外殼簡單而實用。"}],"source":"47 - The History of Pencil.pdf","sourcePage":3},{"front":"for stability","meaning":"為了穩定","examples":[{"en":"Graphite sticks were wrapped in string or sheepskin for stability.","zh":"石墨棒被包裹在繩子或羊皮裏，以增加穩定性。"},{"en":"For stability means in order to make something steadier, stronger or easier to control.","zh":"“For stability” 指為了令某物更穩、更堅固或更容易控制。"},{"en":"A wobbly table may need an extra piece of wood for stability.","zh":"搖晃的桌子可能需要一塊額外木板來增加穩定性。"},{"en":"If graphite is wrapped for stability, it is less likely to break or slip in the hand.","zh":"如果石墨為了穩定而被包起，它就較不容易折斷或在手中滑動。"},{"en":"The phrase explains the purpose of support.","zh":"這個短語解釋支撐的目的。"}],"source":"47 - The History of Pencil.pdf","sourcePage":3},{"front":"what may have been","meaning":"可能是……","examples":[{"en":"These objects may have been the world’s first pencils.","zh":"這些物件可能是世界上最早的鉛筆。"},{"en":"What may have been means something was possibly true, but we are not completely certain.","zh":"“What may have been” 指某事可能是真的，但我們並不完全確定。"},{"en":"A broken old bowl may have been part of a family’s kitchen many generations ago.","zh":"一隻破舊碗可能是幾代以前某家庭廚房的一部分。"},{"en":"If evidence is incomplete, historians use careful phrases like “may have been.”","zh":"如果證據不完整，歷史學家會使用 “may have been” 這類謹慎短語。"},{"en":"The phrase shows possibility rather than definite fact.","zh":"這個短語表示可能性，而不是確定事實。"}],"source":"47 - The History of Pencil.pdf","sourcePage":3},{"front":"the world’s first pencils","meaning":"世界上最早的鉛筆","examples":[{"en":"The wrapped graphite sticks may have been the world’s first pencils.","zh":"這些包裹起來的石墨棒可能是世界上最早的鉛筆。"},{"en":"The world’s first pencils means the earliest pencil-like tools known or believed to have existed.","zh":"世界上最早的鉛筆指已知或被認為存在過的最早類鉛筆工具。"},{"en":"A history book may compare the world’s first pencils with the pencils students use today.","zh":"歷史書可能比較世界上最早的鉛筆與今天學生使用的鉛筆。"},{"en":"If early graphite sticks could write and be held, they may count as the first pencils.","zh":"如果早期石墨棒能書寫並可握持，就可能算作最早的鉛筆。"},{"en":"The phrase points to the earliest stage of pencil development.","zh":"這個短語指向鉛筆發展的最早階段。"}],"source":"47 - The History of Pencil.pdf","sourcePage":4},{"front":"produce the first plans for","meaning":"製作……的最早設計圖","examples":[{"en":"An Italian couple probably produced the first plans for the modern pencil.","zh":"一對意大利夫婦可能製作了現代鉛筆的最早設計圖。"},{"en":"To produce the first plans for something means to create the earliest design or method for making it.","zh":"“Produce the first plans for” 某物指創造製作它的最早設計或方法。"},{"en":"An engineer may produce the first plans for a new bridge before builders start work.","zh":"工程師可能在建築工人開工前，製作新橋的最早設計圖。"},{"en":"If someone produces the first plans, later makers can improve and copy the basic idea.","zh":"如果某人製作最早設計圖，後來的製造者就可以改良和複製基本概念。"},{"en":"The phrase refers to early design work, not mass production.","zh":"這個短語指早期設計工作，而不是大量生產。"}],"source":"47 - The History of Pencil.pdf","sourcePage":4},{"front":"the modern wood-cased carpenter’s pencil","meaning":"現代木殼木匠鉛筆","examples":[{"en":"The couple designed the modern wood-cased carpenter’s pencil.","zh":"這對夫婦設計了現代木殼木匠鉛筆。"},{"en":"A modern wood-cased carpenter’s pencil is a pencil with a wooden covering, often shaped for practical work.","zh":"現代木殼木匠鉛筆是有木製外殼的鉛筆，通常為實際工作而成形。"},{"en":"A carpenter may use a flat pencil because it does not roll away easily on a workbench.","zh":"木匠可能使用扁平鉛筆，因為它不容易在工作枱上滾走。"},{"en":"If graphite is placed inside wood, the pencil becomes cleaner and easier to hold.","zh":"如果石墨放進木頭裏，鉛筆就變得更乾淨和更易握持。"},{"en":"The phrase describes a practical pencil design made for workers.","zh":"這個短語描述為工人而設的實用鉛筆設計。"}],"source":"47 - The History of Pencil.pdf","sourcePage":4},{"front":"wood-cased","meaning":"木殼的","examples":[{"en":"The pencil was a wood-cased writing tool.","zh":"這支鉛筆是一種木殼書寫工具。"},{"en":"Wood-cased means covered or enclosed in wood.","zh":"“Wood-cased” 指被木材包住或封住。"},{"en":"A wood-cased pencil is easier to hold than a bare stick of graphite.","zh":"木殼鉛筆比裸露石墨棒更容易握住。"},{"en":"If a writing tool is wood-cased, the wood protects the core and keeps hands cleaner.","zh":"如果書寫工具是木殼的，木材會保護筆芯並保持雙手較乾淨。"},{"en":"The phrase describes the outer material of the tool.","zh":"這個短語描述工具的外層材料。"}],"source":"47 - The History of Pencil.pdf","sourcePage":4},{"front":"carpenter’s pencil","meaning":"木匠鉛筆","examples":[{"en":"The early version was probably a carpenter’s pencil.","zh":"早期版本可能是一支木匠鉛筆。"},{"en":"A carpenter’s pencil is a pencil designed for builders or carpenters to mark wood and other materials.","zh":"木匠鉛筆是為建築工人或木匠標記木材和其他材料而設計的鉛筆。"},{"en":"A carpenter’s pencil is often flat so it will not roll off a work surface.","zh":"木匠鉛筆通常是扁平的，因此不會從工作面滾走。"},{"en":"If workers need to mark rough wood, a normal school pencil may break too easily.","zh":"如果工人需要標記粗糙木材，普通學生鉛筆可能太容易折斷。"},{"en":"The phrase refers to a practical work tool, not only a classroom pencil.","zh":"這個短語指實用工作工具，而不只是課室鉛筆。"}],"source":"47 - The History of Pencil.pdf","sourcePage":4},{"front":"flat, oval and compact","meaning":"扁平、橢圓而小巧","examples":[{"en":"The Italian version was flat, oval and compact.","zh":"意大利版本是扁平、橢圓而小巧的。"},{"en":"Flat, oval and compact means low, rounded in shape and small enough to handle easily.","zh":"“Flat, oval and compact” 指低平、形狀圓橢，而且細小到容易使用。"},{"en":"A compact pencil case fits easily into a school bag without taking much space.","zh":"小巧筆袋可以容易放進書包，而不佔太多空間。"},{"en":"If a pencil is flat and oval, it may be easier to grip and less likely to roll away.","zh":"如果鉛筆扁平而橢圓，可能更容易握住，也較不會滾走。"},{"en":"The phrase describes shape and size in a practical way.","zh":"這個短語以實用方式描述形狀和大小。"}],"source":"47 - The History of Pencil.pdf","sourcePage":4},{"front":"hollow out","meaning":"挖空","examples":[{"en":"The pencil was made by hollowing out a stick of juniper wood.","zh":"這支鉛筆是透過挖空一條杜松木製成的。"},{"en":"To hollow out something means to remove material from the inside so a space is created.","zh":"“Hollow out” 某物指移除內部材料，造成一個空間。"},{"en":"Children may hollow out a pumpkin before placing a candle inside it.","zh":"孩子可能先挖空南瓜，再把蠟燭放進去。"},{"en":"If wood is hollowed out, graphite can be placed inside the empty space.","zh":"如果木頭被挖空，石墨就可以放進空出來的位置。"},{"en":"The phrase describes making an inner space by removing material.","zh":"這個短語描述透過移除材料來製造內部空間。"}],"source":"47 - The History of Pencil.pdf","sourcePage":4},{"front":"a stick of juniper wood","meaning":"一條杜松木","examples":[{"en":"The pencil was made from a stick of juniper wood.","zh":"這支鉛筆由一條杜松木製成。"},{"en":"A stick of juniper wood is a narrow piece of wood from a juniper tree.","zh":"一條杜松木是來自杜松樹的一段細長木材。"},{"en":"A craftsperson may carve a stick of wood into a handle, toy or simple tool.","zh":"工匠可能把一條木材雕成手柄、玩具或簡單工具。"},{"en":"If a stick of wood can be hollowed out, it can hold another material inside.","zh":"如果一條木材可以被挖空，它就可以在內部容納另一種材料。"},{"en":"The phrase identifies the specific wooden material used.","zh":"這個短語指出所使用的特定木材。"}],"source":"47 - The History of Pencil.pdf","sourcePage":4},{"front":"soon afterwards","meaning":"不久之後","examples":[{"en":"Soon afterwards, German craftspeople developed a superior technique.","zh":"不久之後，德國工匠發展出更優良的技術。"},{"en":"Soon afterwards means a short time after the previous event.","zh":"“Soon afterwards” 指前一事件之後不久。"},{"en":"The teacher explained the rule, and soon afterwards students began using it correctly.","zh":"老師解釋規則後不久，學生開始正確使用它。"},{"en":"If one invention appears, improvements may follow soon afterwards.","zh":"如果一項發明出現，改良可能不久之後跟隨。"},{"en":"The phrase shows that the next event happened quickly after the first.","zh":"這個短語顯示下一事件在第一件事後很快發生。"}],"source":"47 - The History of Pencil.pdf","sourcePage":4},{"front":"craftspeople","meaning":"工匠；手工藝人","examples":[{"en":"German craftspeople developed a superior technique for making pencils.","zh":"德國工匠發展出更優良的鉛筆製作技術。"},{"en":"Craftspeople are skilled workers who make things carefully by hand or with specialist tools.","zh":"工匠是用手或專門工具仔細製作物件的熟練工作者。"},{"en":"Craftspeople may produce furniture, pottery, jewellery or musical instruments.","zh":"工匠可能製作家具、陶器、首飾或樂器。"},{"en":"If craftspeople improve a technique, the product may become stronger, cleaner or easier to use.","zh":"如果工匠改良技術，產品可能變得更堅固、更乾淨或更易使用。"},{"en":"The word emphasises skill and practical making.","zh":"這個詞強調技術和實際製作。"}],"source":"47 - The History of Pencil.pdf","sourcePage":4},{"front":"develop a superior technique","meaning":"發展出更優良的技術","examples":[{"en":"German craftspeople developed a superior technique for making pencils.","zh":"德國工匠發展出更優良的鉛筆製作技術。"},{"en":"To develop a superior technique means to create a better method than the one used before.","zh":"“Develop a superior technique” 指創造比以前更好的方法。"},{"en":"A bakery may develop a superior technique for keeping bread soft for longer.","zh":"麵包店可能發展出更優良的技術，使麵包保持柔軟更久。"},{"en":"If a superior technique saves time and reduces waste, other makers may copy it.","zh":"如果更優良的技術節省時間並減少浪費，其他製造者可能模仿它。"},{"en":"The phrase describes improvement in method.","zh":"這個短語描述方法上的改良。"}],"source":"47 - The History of Pencil.pdf","sourcePage":4},{"front":"a superior technique","meaning":"更優良的技術","examples":[{"en":"The German method was a superior technique.","zh":"德國方法是一種更優良的技術。"},{"en":"A superior technique is a method that works better than another method.","zh":"更優良的技術是比另一種方法效果更好的方法。"},{"en":"A teacher may use a superior technique for vocabulary learning by combining examples, translation and review.","zh":"老師可能透過結合例句、翻譯和溫習，使用更優良的詞彙學習技術。"},{"en":"If a technique produces cleaner pencils more reliably, it is superior in practice.","zh":"如果一項技術能更可靠地製造更乾淨的鉛筆，它在實際上就是更優良。"},{"en":"The phrase compares quality between methods.","zh":"這個短語比較不同方法之間的質素。"}],"source":"47 - The History of Pencil.pdf","sourcePage":5},{"front":"carve two wooden halves","meaning":"雕出兩半木材","examples":[{"en":"They carved two wooden halves to hold the graphite.","zh":"他們雕出兩半木材來固定石墨。"},{"en":"To carve two wooden halves means to shape two matching pieces of wood by cutting them.","zh":"“Carve two wooden halves” 指透過切削塑造兩塊相配的木材。"},{"en":"A craftsperson may carve two wooden halves of a box before fitting them together.","zh":"工匠可能先雕出盒子的兩半木材，再把它們合起來。"},{"en":"If graphite is placed between two wooden halves, it can be held firmly inside the pencil.","zh":"如果石墨放在兩半木材之間，就能牢固固定在鉛筆內。"},{"en":"The phrase describes an important step in making a wooden pencil.","zh":"這個短語描述製作木鉛筆的重要步驟。"}],"source":"47 - The History of Pencil.pdf","sourcePage":5},{"front":"insert a graphite stick","meaning":"插入一條石墨棒","examples":[{"en":"The craftspeople inserted a graphite stick between the wooden halves.","zh":"工匠把一條石墨棒插入兩半木材之間。"},{"en":"To insert a graphite stick means to put a piece of graphite into a prepared space.","zh":"“Insert a graphite stick” 指把一段石墨放進準備好的空間。"},{"en":"A worker may insert a battery into a toy before closing the cover.","zh":"工人可能先把電池插入玩具，再關上蓋子。"},{"en":"If the graphite stick is inserted properly, the pencil core stays centred and stable.","zh":"如果石墨棒被正確插入，鉛筆芯就會保持置中和穩定。"},{"en":"The phrase describes placing the writing core inside the pencil.","zh":"這個短語描述把書寫芯放進鉛筆內。"}],"source":"47 - The History of Pencil.pdf","sourcePage":5},{"front":"glue the halves together","meaning":"把兩半黏合在一起","examples":[{"en":"They glued the halves together after inserting the graphite.","zh":"插入石墨後，他們把兩半黏合在一起。"},{"en":"To glue the halves together means to join two matching pieces using glue.","zh":"“Glue the halves together” 指用膠水把兩塊相配部分接合。"},{"en":"A student may glue two pieces of card together to make a stronger project cover.","zh":"學生可能把兩張卡紙黏合在一起，製作更堅固的項目封面。"},{"en":"If the wooden halves are glued tightly, the graphite will not fall out easily.","zh":"如果兩半木材緊密黏合，石墨就不容易掉出來。"},{"en":"The phrase describes the joining step in pencil construction.","zh":"這個短語描述鉛筆結構中的接合步驟。"}],"source":"47 - The History of Pencil.pdf","sourcePage":5},{"front":"essentially the same method","meaning":"基本上相同的方法","examples":[{"en":"The technique is essentially the same method used today.","zh":"這項技術基本上與今天使用的方法相同。"},{"en":"Essentially the same method means basically the same way, even if small details have changed.","zh":"“Essentially the same method” 指基本上同一方法，即使小細節已改變。"},{"en":"Modern classrooms may use tablets, but the basic method of explaining and practising is essentially the same.","zh":"現代課室可能使用平板電腦，但解釋和練習的基本方法大致相同。"},{"en":"If a technique remains essentially the same for centuries, the original design was highly practical.","zh":"如果一項技術數百年來基本上相同，原本設計就非常實用。"},{"en":"The phrase highlights continuity despite later improvements.","zh":"這個短語強調即使後來有改良，核心仍然延續。"}],"source":"47 - The History of Pencil.pdf","sourcePage":5},{"front":"be used today","meaning":"沿用至今","examples":[{"en":"The same basic method is still used today.","zh":"同一基本方法仍沿用至今。"},{"en":"To be used today means to continue being used in the present time.","zh":"“Be used today” 指在現在仍被使用。"},{"en":"Many old cooking methods are still used today because they are simple and effective.","zh":"許多舊烹飪方法仍沿用至今，因為它們簡單而有效。"},{"en":"If a method is still used today, it has remained useful despite new technology.","zh":"如果一種方法至今仍被使用，即使有新科技，它仍保持實用。"},{"en":"The phrase shows survival and continued practical value.","zh":"這個短語顯示留存和持續實際價值。"}],"source":"47 - The History of Pencil.pdf","sourcePage":5},{"front":"spread widely","meaning":"廣泛流傳","examples":[{"en":"News of these early pencils spread widely.","zh":"這些早期鉛筆的消息廣泛流傳。"},{"en":"To spread widely means to become known or used by many people in many places.","zh":"“Spread widely” 指在許多地方被許多人知道或使用。"},{"en":"A useful study app can spread widely when students recommend it to friends.","zh":"如果學生向朋友推薦，有用的學習應用程式可以廣泛流傳。"},{"en":"If news of a good invention spreads widely, demand for it may grow quickly.","zh":"如果好發明的消息廣泛流傳，對它的需求可能迅速增長。"},{"en":"The phrase describes broad movement of information or use.","zh":"這個短語描述資訊或使用範圍的廣泛擴散。"}],"source":"47 - The History of Pencil.pdf","sourcePage":5},{"front":"attract artists","meaning":"吸引藝術家","examples":[{"en":"These early pencils attracted artists throughout the known world.","zh":"這些早期鉛筆吸引了遍及當時已知世界的藝術家。"},{"en":"To attract artists means to interest people who create drawings, paintings or other visual works.","zh":"“Attract artists” 指引起創作繪畫、畫作或其他視覺作品的人興趣。"},{"en":"A new art tool may attract artists if it allows fine lines and easy correction.","zh":"如果新藝術工具能畫出幼細線條並容易修改，可能吸引藝術家。"},{"en":"If pencils attract artists, they may become important not only for writing but also for drawing.","zh":"如果鉛筆吸引藝術家，它們就不只對書寫重要，也對繪畫重要。"},{"en":"The phrase shows that a tool appeals to creative users.","zh":"這個短語顯示工具對創意使用者有吸引力。"}],"source":"47 - The History of Pencil.pdf","sourcePage":5},{"front":"throughout the known world","meaning":"遍及當時已知的世界","examples":[{"en":"The news spread throughout the known world.","zh":"這個消息遍及當時已知的世界。"},{"en":"Throughout the known world means across the places known to the people of that time.","zh":"“Throughout the known world” 指遍及當時人們所知道的地方。"},{"en":"Before modern maps, “the known world” depended on what travellers and traders had reached.","zh":"在現代地圖之前，「已知世界」取決於旅人和商人到達過哪些地方。"},{"en":"If an invention spreads throughout the known world, it becomes famous across many regions.","zh":"如果一項發明遍及當時已知的世界，它就會在許多地區變得有名。"},{"en":"The phrase gives a historical sense of wide reach.","zh":"這個短語帶有歷史感，表示傳播範圍廣。"}],"source":"47 - The History of Pencil.pdf","sourcePage":5},{"front":"graphite core","meaning":"石墨芯","examples":[{"en":"A pencil’s graphite core is still called its lead.","zh":"鉛筆的石墨芯仍然被稱為鉛芯。"},{"en":"A graphite core is the central writing part of a pencil made mainly from graphite.","zh":"石墨芯是鉛筆中央的書寫部分，主要由石墨製成。"},{"en":"When a pencil breaks, students often say the lead broke, but the core is usually graphite.","zh":"鉛筆折斷時，學生常說鉛芯斷了，但筆芯通常是石墨。"},{"en":"If the graphite core is soft, the pencil makes darker marks on paper.","zh":"如果石墨芯較軟，鉛筆會在紙上留下較深痕跡。"},{"en":"The phrase refers to the inside writing material of a pencil.","zh":"這個短語指鉛筆內部的書寫材料。"}],"source":"47 - The History of Pencil.pdf","sourcePage":5},{"front":"be still called","meaning":"仍然被稱為","examples":[{"en":"A pencil’s graphite core is still called its lead.","zh":"鉛筆的石墨芯仍然被稱為鉛芯。"},{"en":"To be still called something means people continue to use an old name for it.","zh":"“Be still called” 某物指人們繼續使用舊名稱稱呼它。"},{"en":"A phone may still be called a “mobile” even when it is really a powerful computer.","zh":"手機即使其實是功能強大的電腦，仍然可能被稱為 “mobile”。"},{"en":"If a name remains after the material changes, language keeps a trace of history.","zh":"如果材料改變後名稱仍然保留，語言就保存了歷史痕跡。"},{"en":"The phrase shows that everyday words can preserve old misunderstandings.","zh":"這個短語顯示日常詞語可以保留舊誤解。"}],"source":"47 - The History of Pencil.pdf","sourcePage":5},{"front":"contain no lead","meaning":"不含鉛","examples":[{"en":"Modern pencils contain no lead.","zh":"現代鉛筆不含鉛。"},{"en":"To contain no lead means to have no lead metal inside.","zh":"“Contain no lead” 指內部沒有鉛這種金屬。"},{"en":"A parent may check whether a toy contains no lead before giving it to a child.","zh":"家長可能在把玩具交給孩子前，檢查它是否不含鉛。"},{"en":"If pencils contain no lead, the word “lead” is only a traditional name for the core.","zh":"如果鉛筆不含鉛，“lead” 這個詞就只是筆芯的傳統名稱。"},{"en":"The phrase corrects the common belief that pencils are made with lead.","zh":"這個短語糾正常見的鉛筆由鉛製成的想法。"}],"source":"47 - The History of Pencil.pdf","sourcePage":6},{"front":"a mixture of","meaning":"……的混合物","examples":[{"en":"The lead is actually a mixture of graphite and clay powders.","zh":"鉛芯實際上是石墨和黏土粉末的混合物。"},{"en":"A mixture of things is a combination of two or more materials or elements.","zh":"某些東西的混合物是兩種或以上材料或元素的結合。"},{"en":"Cake batter is a mixture of flour, eggs, sugar and butter.","zh":"蛋糕麵糊是麵粉、雞蛋、糖和牛油的混合物。"},{"en":"If a pencil core is a mixture of graphite and clay, changing the amount of clay changes its hardness.","zh":"如果鉛筆芯是石墨和黏土的混合物，改變黏土份量就會改變硬度。"},{"en":"The phrase explains what something is made from.","zh":"這個短語解釋某物由甚麼組成。"}],"source":"47 - The History of Pencil.pdf","sourcePage":6},{"front":"finely ground graphite","meaning":"磨得很幼細的石墨","examples":[{"en":"The pencil core contains finely ground graphite.","zh":"鉛筆芯含有磨得很幼細的石墨。"},{"en":"Finely ground graphite is graphite crushed into very small particles or powder.","zh":"磨得很幼細的石墨是被壓碎成非常細小顆粒或粉末的石墨。"},{"en":"Coffee tastes different when beans are finely ground rather than roughly broken.","zh":"咖啡豆磨得很幼細和粗略打碎時，味道會不同。"},{"en":"If graphite is finely ground, it can mix more smoothly with clay powder.","zh":"如果石墨磨得很幼細，就能更順滑地與黏土粉末混合。"},{"en":"The phrase describes the texture and preparation of graphite.","zh":"這個短語描述石墨的質地和處理方式。"}],"source":"47 - The History of Pencil.pdf","sourcePage":6},{"front":"clay powders","meaning":"黏土粉末","examples":[{"en":"The core is made from graphite and clay powders.","zh":"筆芯由石墨和黏土粉末製成。"},{"en":"Clay powders are fine dry particles made from clay.","zh":"黏土粉末是由黏土製成的幼細乾粉粒。"},{"en":"Artists may mix clay powder with water to shape pottery or models.","zh":"藝術家可能把黏土粉末與水混合，用來塑造陶器或模型。"},{"en":"If more clay powder is added to a pencil core, the core usually becomes harder.","zh":"如果鉛筆芯加入更多黏土粉末，筆芯通常會變得更硬。"},{"en":"The phrase refers to powdered clay used as part of a mixture.","zh":"這個短語指作為混合物一部分使用的粉狀黏土。"}],"source":"47 - The History of Pencil.pdf","sourcePage":6},{"front":"the amount of clay added","meaning":"所加入黏土的份量","examples":[{"en":"The amount of clay added determines the pencil’s hardness.","zh":"所加入黏土的份量決定鉛筆的硬度。"},{"en":"The amount of clay added means how much clay is put into the graphite mixture.","zh":"所加入黏土的份量指放進石墨混合物中的黏土有多少。"},{"en":"In cooking, the amount of salt added can change the taste of a dish.","zh":"在烹飪中，所加入鹽的份量可以改變菜式味道。"},{"en":"If more clay is added to a pencil core, the pencil usually becomes harder and lighter in mark.","zh":"如果鉛筆芯加入更多黏土，鉛筆通常會更硬，筆跡也較淺。"},{"en":"The phrase focuses on quantity and its effect.","zh":"這個短語強調數量及其影響。"}],"source":"47 - The History of Pencil.pdf","sourcePage":6},{"front":"determine the pencil’s hardness","meaning":"決定鉛筆的硬度","examples":[{"en":"The amount of clay determines the pencil’s hardness.","zh":"黏土的份量決定鉛筆的硬度。"},{"en":"To determine the pencil’s hardness means to decide how hard or soft the pencil core will be.","zh":"“Determine the pencil’s hardness” 指決定鉛筆芯會有多硬或多軟。"},{"en":"A recipe’s water amount can determine whether dough becomes soft or firm.","zh":"食譜中的水量可以決定麵團變得柔軟還是結實。"},{"en":"If clay determines hardness, manufacturers can create different pencil grades by adjusting the mixture.","zh":"如果黏土決定硬度，製造商就能透過調整混合物製造不同鉛筆等級。"},{"en":"The phrase connects a cause with a physical quality.","zh":"這個短語把原因與物理特性連繫起來。"}],"source":"47 - The History of Pencil.pdf","sourcePage":6},{"front":"the time spent grinding","meaning":"花在研磨上的時間","examples":[{"en":"The time spent grinding the mixture determines the lead’s quality.","zh":"花在研磨混合物上的時間決定鉛芯的質素。"},{"en":"The time spent grinding means how long the material is crushed and smoothed.","zh":"花在研磨上的時間指材料被壓碎和磨滑多久。"},{"en":"The time spent practising pronunciation can affect how natural a speaker sounds.","zh":"花在練習發音上的時間可以影響說話者聽起來是否自然。"},{"en":"If a mixture is ground longer, it may become smoother and more consistent.","zh":"如果混合物研磨更久，可能變得更順滑和更一致。"},{"en":"The phrase links time and effort with final quality.","zh":"這個短語把時間和努力與最終質素連繫起來。"}],"source":"47 - The History of Pencil.pdf","sourcePage":6},{"front":"determine the lead’s quality","meaning":"決定鉛芯的質素","examples":[{"en":"The time spent grinding determines the lead’s quality.","zh":"花在研磨上的時間決定鉛芯的質素。"},{"en":"To determine the lead’s quality means to affect how smooth, reliable and useful the pencil core is.","zh":"“Determine the lead’s quality” 指影響鉛筆芯有多順滑、可靠和有用。"},{"en":"The quality of a cake may be determined by how carefully the ingredients are mixed.","zh":"蛋糕質素可能由材料混合得有多仔細決定。"},{"en":"If grinding is rushed, the pencil lead may feel rough or uneven.","zh":"如果研磨過程倉促，鉛芯可能感覺粗糙或不均勻。"},{"en":"The phrase explains what controls the final standard of the core.","zh":"這個短語解釋甚麼控制筆芯的最終標準。"}],"source":"47 - The History of Pencil.pdf","sourcePage":6},{"front":"the harder the core becomes","meaning":"筆芯就變得越硬","examples":[{"en":"The more clay that is added, the harder the core becomes.","zh":"加入越多黏土，筆芯就變得越硬。"},{"en":"The harder the core becomes means the pencil’s centre becomes less soft and produces lighter marks.","zh":"“The harder the core becomes” 指鉛筆中央部分變得較不柔軟，並留下較淺痕跡。"},{"en":"The more water freezes, the harder the ice becomes.","zh":"水結冰越多，冰就變得越硬。"},{"en":"If more clay is added, the core becomes harder and may be better for fine, light lines.","zh":"如果加入更多黏土，筆芯會變得更硬，可能更適合幼細淺色線條。"},{"en":"The phrase shows a direct relationship between amount and hardness.","zh":"這個短語顯示份量與硬度之間的直接關係。"}],"source":"47 - The History of Pencil.pdf","sourcePage":6},{"front":"be graded using","meaning":"使用……來分級","examples":[{"en":"Many pencils are graded using the European system.","zh":"許多鉛筆使用歐洲制度來分級。"},{"en":"To be graded using a system means to be classified according to that set of labels or rules.","zh":"“Be graded using” 某制度指根據該套標籤或規則分類。"},{"en":"Students may be graded using letters, numbers or percentages.","zh":"學生可能使用字母、數字或百分比分級。"},{"en":"If pencils are graded using H and B, buyers can choose hardness and darkness more easily.","zh":"如果鉛筆使用 H 和 B 來分級，買家就更容易選擇硬度和深淺。"},{"en":"The phrase explains the system used for classification.","zh":"這個短語解釋用甚麼制度分類。"}],"source":"47 - The History of Pencil.pdf","sourcePage":6},{"front":"the European system","meaning":"歐洲分級制度","examples":[{"en":"Many pencils are graded using the European system.","zh":"許多鉛筆使用歐洲分級制度。"},{"en":"The European system is a pencil grading system that uses letters such as H and B.","zh":"歐洲分級制度是一種使用 H 和 B 等字母的鉛筆等級制度。"},{"en":"Art students often learn the European system so they can choose suitable pencils for shading.","zh":"美術學生常學習歐洲分級制度，以便選擇適合陰影處理的鉛筆。"},{"en":"If a pencil is marked 2B or 2H, the European system tells users its softness or hardness.","zh":"如果鉛筆標示為 2B 或 2H，歐洲分級制度會告訴使用者其軟硬程度。"},{"en":"The phrase refers to a standard way of naming pencil grades.","zh":"這個短語指命名鉛筆等級的標準方法。"}],"source":"47 - The History of Pencil.pdf","sourcePage":6},{"front":"naming system","meaning":"命名制度","examples":[{"en":"This naming system uses B for black and H for hard.","zh":"這套命名制度使用 B 代表黑，H 代表硬。"},{"en":"A naming system is a set of rules for giving names or labels to things.","zh":"命名制度是一套為事物命名或貼標籤的規則。"},{"en":"A school may use a naming system for classrooms, such as A101, A102 and A103.","zh":"學校可能使用課室命名制度，例如 A101、A102 和 A103。"},{"en":"If a naming system is clear, users can understand a product’s type without long explanations.","zh":"如果命名制度清晰，使用者不用長篇解釋也能理解產品類型。"},{"en":"The phrase describes how labels are organised.","zh":"這個短語描述標籤如何被組織。"}],"source":"47 - The History of Pencil.pdf","sourcePage":7},{"front":"a pencil’s grade","meaning":"鉛筆的等級","examples":[{"en":"A pencil’s grade may be described by a sequence of letters.","zh":"鉛筆的等級可以由一連串字母描述。"},{"en":"A pencil’s grade is the label that shows how hard, soft, dark or light the pencil is.","zh":"鉛筆的等級是顯示鉛筆有多硬、多軟、多深或多淺的標籤。"},{"en":"An artist may choose a pencil’s grade depending on whether they need dark shading or fine lines.","zh":"藝術家可能根據是否需要深色陰影或幼細線條來選擇鉛筆等級。"},{"en":"If the grade is wrong for the task, the pencil may mark too lightly or too darkly.","zh":"如果等級不適合任務，鉛筆可能畫得太淺或太深。"},{"en":"The phrase refers to the classification of a pencil’s core.","zh":"這個短語指鉛筆芯的分類。"}],"source":"47 - The History of Pencil.pdf","sourcePage":7},{"front":"be described by","meaning":"由……描述","examples":[{"en":"A pencil’s grade may be described by a sequence of Hs or Bs.","zh":"鉛筆的等級可以由一連串 H 或 B 描述。"},{"en":"To be described by something means to be explained or represented using it.","zh":"“Be described by” 某物指使用它來解釋或表示某事。"},{"en":"A student’s result may be described by a letter grade such as A or B.","zh":"學生成績可能由 A 或 B 這類字母等級描述。"},{"en":"If pencil hardness is described by letters, users can compare pencils quickly.","zh":"如果鉛筆硬度由字母描述，使用者就能快速比較鉛筆。"},{"en":"The phrase shows the form used to express information.","zh":"這個短語顯示用甚麼形式表達資料。"}],"source":"47 - The History of Pencil.pdf","sourcePage":7},{"front":"a sequence of","meaning":"一連串的……","examples":[{"en":"The grade may be described by a sequence of Hs or Bs.","zh":"等級可以由一連串 H 或 B 描述。"},{"en":"A sequence of things is a set of items arranged in order.","zh":"一連串事物是按次序排列的一組項目。"},{"en":"A password may contain a sequence of numbers that must be typed correctly.","zh":"密碼可能包含一連串數字，必須正確輸入。"},{"en":"If a pencil grade has a sequence of Bs, each extra B usually suggests a softer lead.","zh":"如果鉛筆等級有一連串 B，每多一個 B 通常表示鉛芯更軟。"},{"en":"The phrase describes ordered items, not random objects.","zh":"這個短語描述有次序的項目，而不是隨機物件。"}],"source":"47 - The History of Pencil.pdf","sourcePage":7},{"front":"progressively softer leads","meaning":"逐漸較軟的鉛芯","examples":[{"en":"BB and BBB represent progressively softer leads.","zh":"BB 和 BBB 代表逐漸較軟的鉛芯。"},{"en":"Progressively softer leads are pencil cores that become softer step by step as the grade changes.","zh":"逐漸較軟的鉛芯，是隨着等級變化而一步步變軟的鉛筆芯。"},{"en":"An artist may move from HB to B to 2B when they need progressively softer leads for darker shading.","zh":"當藝術家需要逐漸較軟的鉛芯來畫更深陰影，可能由 HB 轉到 B 再到 2B。"},{"en":"If leads become progressively softer, they usually make darker marks and wear down faster.","zh":"如果鉛芯逐漸較軟，通常會留下更深痕跡，也磨損得更快。"},{"en":"The phrase describes a gradual increase in softness.","zh":"這個短語描述軟度逐步增加。"}],"source":"47 - The History of Pencil.pdf","sourcePage":7},{"front":"progressively harder leads","meaning":"逐漸較硬的鉛芯","examples":[{"en":"HH and HHH represent progressively harder leads.","zh":"HH 和 HHH 代表逐漸較硬的鉛芯。"},{"en":"Progressively harder leads are pencil cores that become harder step by step as the grade changes.","zh":"逐漸較硬的鉛芯，是隨着等級變化而一步步變硬的鉛筆芯。"},{"en":"A technical drawing student may choose progressively harder leads for precise, light lines.","zh":"技術繪圖學生可能選擇逐漸較硬的鉛芯來畫精準淺線。"},{"en":"If leads become progressively harder, they usually leave lighter marks and hold a sharper point longer.","zh":"如果鉛芯逐漸較硬，通常留下較淺痕跡，並能較久保持尖端。"},{"en":"The phrase describes a gradual increase in hardness.","zh":"這個短語描述硬度逐步增加。"}],"source":"47 - The History of Pencil.pdf","sourcePage":7},{"front":"the standard writing pencil","meaning":"標準書寫鉛筆","examples":[{"en":"The standard writing pencil is graded HB.","zh":"標準書寫鉛筆被評為 HB 等級。"},{"en":"The standard writing pencil is the common pencil used for ordinary writing tasks.","zh":"標準書寫鉛筆是用於普通書寫任務的常見鉛筆。"},{"en":"Students often use a standard writing pencil for notes, exercises and exams.","zh":"學生常用標準書寫鉛筆寫筆記、做練習和考試。"},{"en":"If a pencil is standard, it is usually balanced between hardness and darkness.","zh":"如果鉛筆是標準的，它通常在硬度和深淺之間取得平衡。"},{"en":"The phrase refers to a normal everyday pencil rather than a specialist art pencil.","zh":"這個短語指普通日常鉛筆，而不是專門美術鉛筆。"}],"source":"47 - The History of Pencil.pdf","sourcePage":7},{"front":"be graded HB","meaning":"被評為 HB 等級","examples":[{"en":"The standard writing pencil is graded HB.","zh":"標準書寫鉛筆被評為 HB 等級。"},{"en":"To be graded HB means to be classified as medium-hard and suitable for general writing.","zh":"“Be graded HB” 指被分類為中等硬度，適合一般書寫。"},{"en":"A school may ask students to bring pencils graded HB for multiple-choice answer sheets.","zh":"學校可能要求學生帶 HB 等級鉛筆來填寫選擇題答題紙。"},{"en":"If a pencil is graded HB, it is usually neither very dark nor very hard.","zh":"如果鉛筆被評為 HB 等級，它通常既不非常深，也不非常硬。"},{"en":"The phrase identifies a common pencil grade.","zh":"這個短語指出一種常見鉛筆等級。"}],"source":"47 - The History of Pencil.pdf","sourcePage":7},{"front":"whole pieces of","meaning":"整塊的……","examples":[{"en":"In England, pencils continued to be made from whole pieces of sawn graphite.","zh":"在英格蘭，鉛筆繼續由整塊鋸切成形的石墨製成。"},{"en":"Whole pieces of something are complete pieces, not powder or small mixed fragments.","zh":"整塊的某物是完整塊狀，而不是粉末或細碎混合物。"},{"en":"A chef may use whole pieces of fruit instead of juice to give a dessert texture.","zh":"廚師可能使用整塊水果，而不是果汁，為甜品增加口感。"},{"en":"If pencils use whole pieces of graphite, the material must be pure and strong enough to cut.","zh":"如果鉛筆使用整塊石墨，材料就必須足夠純淨和堅固，可供切割。"},{"en":"The phrase contrasts solid pieces with processed mixtures.","zh":"這個短語把固體完整塊與加工混合物作對比。"}],"source":"47 - The History of Pencil.pdf","sourcePage":7},{"front":"sawn graphite","meaning":"鋸切成形的石墨","examples":[{"en":"English pencils were made from whole pieces of sawn graphite.","zh":"英格蘭鉛筆由整塊鋸切成形的石墨製成。"},{"en":"Sawn graphite is graphite that has been cut into pieces with a saw.","zh":"鋸切成形的石墨是用鋸切成塊狀的石墨。"},{"en":"A carpenter may use sawn wood pieces when building a shelf.","zh":"木匠製作書架時可能使用鋸切成形的木材。"},{"en":"If graphite can be sawn into sticks, it is suitable for early pencil production.","zh":"如果石墨可以被鋸成棒狀，就適合早期鉛筆生產。"},{"en":"The phrase describes graphite prepared by cutting rather than grinding.","zh":"這個短語描述透過切割而非研磨處理的石墨。"}],"source":"47 - The History of Pencil.pdf","sourcePage":7},{"front":"mass production","meaning":"大規模生產","examples":[{"en":"With mass production, pencils became dramatically more popular.","zh":"隨着大規模生產，鉛筆受歡迎程度大幅提高。"},{"en":"Mass production is the making of large numbers of identical products, usually in factories.","zh":"大規模生產是在工廠中大量製造相同產品。"},{"en":"Mass production can make school supplies cheaper because many items are produced at once.","zh":"大規模生產可以令學校用品更便宜，因為許多物品一次過被製造。"},{"en":"If pencils are mass-produced, more students, workers and artists can afford them.","zh":"如果鉛筆被大規模生產，更多學生、工人和藝術家都能負擔得起。"},{"en":"The phrase connects large-scale manufacturing with wider public use.","zh":"這個短語把大規模製造與更廣泛大眾使用連繫起來。"}],"source":"47 - The History of Pencil.pdf","sourcePage":7},{"front":"dramatically more popular","meaning":"受歡迎程度大幅提高","examples":[{"en":"Pencils became dramatically more popular in many countries.","zh":"鉛筆在許多國家受歡迎程度大幅提高。"},{"en":"Dramatically more popular means much more widely liked or used than before.","zh":"“Dramatically more popular” 指比以前受歡迎或被使用得多。"},{"en":"A learning app may become dramatically more popular after teachers recommend it.","zh":"學習應用程式在老師推薦後，受歡迎程度可能大幅提高。"},{"en":"If prices fall and supply increases, a product can become dramatically more popular.","zh":"如果價格下降而供應增加，產品受歡迎程度可以大幅提高。"},{"en":"The phrase stresses a large rise in popularity.","zh":"這個短語強調受歡迎程度大幅上升。"}],"source":"47 - The History of Pencil.pdf","sourcePage":8},{"front":"with each passing decade","meaning":"每過十年；隨着年代推移","examples":[{"en":"Pencils became more popular with each passing decade.","zh":"每過十年，鉛筆變得更受歡迎。"},{"en":"With each passing decade means as every ten-year period went by.","zh":"“With each passing decade” 指隨着每一個十年過去。"},{"en":"With each passing decade, computers became smaller, faster and cheaper.","zh":"隨着年代推移，電腦變得更小、更快和更便宜。"},{"en":"If a tool becomes more useful with each decade, it may spread into more parts of daily life.","zh":"如果工具每過十年變得更有用，它可能擴展到日常生活更多部分。"},{"en":"The phrase describes gradual change over long periods.","zh":"這個短語描述長時間內的逐漸變化。"}],"source":"47 - The History of Pencil.pdf","sourcePage":8},{"front":"as demand rose","meaning":"隨着需求上升","examples":[{"en":"As demand rose, so did the appetite for graphite.","zh":"隨着需求上升，對石墨的需求也上升。"},{"en":"As demand rose means while more people wanted or needed a product.","zh":"“As demand rose” 指當更多人想要或需要某產品時。"},{"en":"As demand for online lessons rose, more teachers began offering video classes.","zh":"隨着網上課堂需求上升，更多老師開始提供視像課程。"},{"en":"If demand rises quickly, suppliers may need more materials and workers.","zh":"如果需求快速上升，供應商可能需要更多材料和工人。"},{"en":"The phrase links increasing need with another result.","zh":"這個短語把需求增加與另一結果連繫起來。"}],"source":"47 - The History of Pencil.pdf","sourcePage":8},{"front":"the appetite for graphite","meaning":"對石墨的需求","examples":[{"en":"The appetite for graphite rose as pencils became more popular.","zh":"隨着鉛筆變得更受歡迎，對石墨的需求上升。"},{"en":"The appetite for graphite means the demand or desire for more graphite.","zh":"對石墨的需求指想要或需要更多石墨。"},{"en":"A growing appetite for smartphones can increase demand for electronic parts.","zh":"對智能手機日益增加的需求，可以提高對電子零件的需求。"},{"en":"If pencils sell in larger numbers, the appetite for graphite naturally increases.","zh":"如果鉛筆銷量增加，對石墨的需求自然上升。"},{"en":"The phrase uses “appetite” metaphorically to mean demand.","zh":"這個短語把 “appetite” 比喻為需求。"}],"source":"47 - The History of Pencil.pdf","sourcePage":8},{"front":"according to","meaning":"根據","examples":[{"en":"According to the United States Geological Survey, production reached 1,100,000 tonnes.","zh":"根據美國地質調查局，產量達到1,100,000公噸。"},{"en":"According to means based on information from a particular person, organisation or source.","zh":"“According to” 指根據某人、機構或來源的資料。"},{"en":"According to the school notice, the library will close early on Friday.","zh":"根據學校通告，圖書館星期五會提早關閉。"},{"en":"If a statistic is given according to an official report, readers can identify the source.","zh":"如果統計數字根據官方報告給出，讀者就能識別來源。"},{"en":"The phrase introduces where information comes from.","zh":"這個短語引出資料來源。"}],"source":"47 - The History of Pencil.pdf","sourcePage":8},{"front":"the United States Geological Survey","meaning":"美國地質調查局","examples":[{"en":"The United States Geological Survey reported global graphite production.","zh":"美國地質調查局報告了全球石墨產量。"},{"en":"The United States Geological Survey is an American scientific agency that studies natural resources, land and geology.","zh":"美國地質調查局是研究天然資源、土地和地質的美國科學機構。"},{"en":"Students may use data from the United States Geological Survey when researching minerals or earthquakes.","zh":"學生研究礦物或地震時，可能使用美國地質調查局的資料。"},{"en":"If such an agency reports production figures, the data sounds official and scientific.","zh":"如果這類機構報告產量數字，資料聽起來就正式且科學。"},{"en":"The phrase names the organisation providing the information.","zh":"這個短語指出提供資料的機構。"}],"source":"47 - The History of Pencil.pdf","sourcePage":8},{"front":"global production of","meaning":"……的全球產量","examples":[{"en":"Global production of natural graphite totalled 1,100,000 tonnes in 2012.","zh":"2012年，天然石墨的全球產量總計達1,100,000公噸。"},{"en":"Global production of something means the total amount made or extracted around the world.","zh":"某物的全球產量指世界各地製造或開採的總量。"},{"en":"Global production of rice affects food prices in many countries.","zh":"稻米的全球產量影響許多國家的食物價格。"},{"en":"If global production rises, supply may become more stable or prices may change.","zh":"如果全球產量上升，供應可能變得更穩定，價格也可能改變。"},{"en":"The phrase gives a worldwide production figure.","zh":"這個短語給出全球生產數字。"}],"source":"47 - The History of Pencil.pdf","sourcePage":8},{"front":"natural graphite","meaning":"天然石墨","examples":[{"en":"Natural graphite was produced in large quantities around the world.","zh":"天然石墨在世界各地大量生產。"},{"en":"Natural graphite is graphite found in the earth rather than made artificially.","zh":"天然石墨是在地下找到，而不是人工製造的石墨。"},{"en":"Natural stone, natural rubber and natural graphite all come from natural sources.","zh":"天然石材、天然橡膠和天然石墨都來自天然來源。"},{"en":"If natural graphite is in demand, mining areas may become economically important.","zh":"如果天然石墨需求高，採礦地區可能變得具有經濟重要性。"},{"en":"The phrase contrasts mined material with synthetic material.","zh":"這個短語把開採材料與合成材料作對比。"}],"source":"47 - The History of Pencil.pdf","sourcePage":8},{"front":"totalled 1,100,000 tonnes","meaning":"總計達 1,100,000 公噸","examples":[{"en":"Global production of natural graphite totalled 1,100,000 tonnes.","zh":"天然石墨的全球產量總計達1,100,000公噸。"},{"en":"Totalled 1,100,000 tonnes means added up to 1,100,000 tonnes in all.","zh":"“Totalled 1,100,000 tonnes” 指全部加起來達1,100,000公噸。"},{"en":"The donations totalled $10,000 after students, parents and teachers contributed.","zh":"在學生、家長和老師捐款後，捐款總計達10,000美元。"},{"en":"If production totals a large number, the material is being used or supplied on a major scale.","zh":"如果產量總計達很大數字，該材料就是以大規模被使用或供應。"},{"en":"The phrase reports a final combined amount.","zh":"這個短語報告最終合計數量。"}],"source":"47 - The History of Pencil.pdf","sourcePage":8},{"front":"major producers","meaning":"主要生產國","examples":[{"en":"The major producers included China, India, Brazil, North Korea and Canada.","zh":"主要生產國包括中國、印度、巴西、北韓和加拿大。"},{"en":"Major producers are countries or companies that produce large amounts of a product or material.","zh":"主要生產國或生產者，是生產大量某產品或材料的國家或公司。"},{"en":"Major producers of rice can influence food supply in many regions.","zh":"稻米主要生產國可以影響許多地區的食物供應。"},{"en":"If a country is a major producer of graphite, changes there may affect global supply.","zh":"如果一個國家是石墨主要生產國，當地變化可能影響全球供應。"},{"en":"The phrase identifies the most important suppliers.","zh":"這個短語指出最重要的供應者。"}],"source":"47 - The History of Pencil.pdf","sourcePage":8},{"front":"in contrast to","meaning":"與……相反；相比之下","examples":[{"en":"In contrast to its familiar use in pencils, graphite was also used by the military.","zh":"與石墨在鉛筆中的常見用途相比，它也被軍方使用。"},{"en":"In contrast to means compared with something different or opposite.","zh":"“In contrast to” 指與不同或相反的事物相比。"},{"en":"In contrast to pens, pencils can usually be erased.","zh":"與原子筆相比，鉛筆通常可以擦掉。"},{"en":"If one use is familiar but another is surprising, “in contrast to” helps show the difference.","zh":"如果一種用途很熟悉但另一種用途令人驚訝，“in contrast to” 可幫助顯示差異。"},{"en":"The phrase introduces a comparison between two unlike ideas.","zh":"這個短語引出兩個不同想法之間的比較。"}],"source":"47 - The History of Pencil.pdf","sourcePage":8},{"front":"its familiar use in pencils","meaning":"它在鉛筆中的常見用途","examples":[{"en":"Graphite is best known for its familiar use in pencils.","zh":"石墨最為人熟知的是它在鉛筆中的常見用途。"},{"en":"Its familiar use in pencils means the common and well-known way graphite is used in pencil cores.","zh":"它在鉛筆中的常見用途，指石墨用於鉛筆芯這種普遍而為人熟知的用途。"},{"en":"Most students know graphite through its familiar use in pencils before learning about its industrial uses.","zh":"大多數學生在了解石墨的工業用途前，先透過它在鉛筆中的常見用途認識它。"},{"en":"If a material has a familiar use, people may forget it can have other purposes too.","zh":"如果材料有一種常見用途，人們可能忘記它也可以有其他用途。"},{"en":"The phrase points to the everyday use people recognise most easily.","zh":"這個短語指人們最容易認出的日常用途。"}],"source":"47 - The History of Pencil.pdf","sourcePage":9},{"front":"be widely employed by","meaning":"被……廣泛使用","examples":[{"en":"Graphite was widely employed by the military.","zh":"石墨被軍方廣泛使用。"},{"en":"To be widely employed by someone means to be used often by that group or organisation.","zh":"“Be widely employed by” 某人或組織指被該群體經常使用。"},{"en":"Tablets are widely employed by schools that use digital textbooks.","zh":"使用數碼教科書的學校廣泛使用平板電腦。"},{"en":"If a material is widely employed by the military, it probably has practical strategic value.","zh":"如果材料被軍方廣泛使用，它很可能具有實際戰略價值。"},{"en":"The phrase means “widely used,” often in a formal context.","zh":"這個短語意思是「被廣泛使用」，常見於較正式語境。"}],"source":"47 - The History of Pencil.pdf","sourcePage":9},{"front":"the military","meaning":"軍方；軍事部門","examples":[{"en":"Graphite was widely employed by the military.","zh":"石墨被軍方廣泛使用。"},{"en":"The military means the armed forces of a country, including the army, navy and air force.","zh":"軍方指一個國家的武裝部隊，包括陸軍、海軍和空軍。"},{"en":"The military may use special vehicles, equipment and materials during war.","zh":"軍方在戰爭期間可能使用特殊車輛、設備和材料。"},{"en":"If a material becomes important to the military, governments may control its supply.","zh":"如果材料對軍方變得重要，政府可能控制其供應。"},{"en":"The phrase refers to national defence forces.","zh":"這個短語指國防武裝力量。"}],"source":"47 - The History of Pencil.pdf","sourcePage":9},{"front":"during the reign of","meaning":"在……統治期間","examples":[{"en":"Graphite was used during the reign of Elizabeth I.","zh":"石墨在伊利沙伯一世統治期間被使用。"},{"en":"During the reign of a ruler means during the period when that ruler was king or queen.","zh":"“During the reign of” 某統治者指在該人作為國王或女王統治的時期。"},{"en":"Many buildings were constructed during the reign of a powerful emperor.","zh":"許多建築在一位強大皇帝統治期間建成。"},{"en":"If an invention was used during a ruler’s reign, it belongs to that historical period.","zh":"如果一項發明在某統治者統治期間使用，它就屬於該歷史時期。"},{"en":"The phrase gives a time period through a monarch’s rule.","zh":"這個短語透過君主統治給出時間時期。"}],"source":"47 - The History of Pencil.pdf","sourcePage":9},{"front":"refractory lining","meaning":"耐火襯裏","examples":[{"en":"Borrowdale graphite was used as a refractory lining for cannonball moulds.","zh":"Borrowdale 石墨被用作炮彈模具的耐火襯裏。"},{"en":"Refractory lining is a heat-resistant inner layer used to protect a mould, furnace or container.","zh":"耐火襯裏是保護模具、熔爐或容器的耐熱內層。"},{"en":"A kiln needs refractory lining so its inside can withstand very high temperatures.","zh":"窯爐需要耐火襯裏，使其內部能承受極高溫度。"},{"en":"If graphite works as a refractory lining, it helps the mould survive heat during production.","zh":"如果石墨能作為耐火襯裏，就能幫助模具在生產期間抵受高溫。"},{"en":"The phrase describes a protective layer for high-temperature work.","zh":"這個短語描述高溫工作中的保護層。"}],"source":"47 - The History of Pencil.pdf","sourcePage":9},{"front":"cannonball moulds","meaning":"炮彈模具","examples":[{"en":"Graphite was used as a lining for cannonball moulds.","zh":"石墨被用作炮彈模具的襯裏。"},{"en":"Cannonball moulds are shaped containers used to form round cannonballs.","zh":"炮彈模具是用來製造圓形炮彈的成形容器。"},{"en":"A mould for chocolate or metal gives the final product its shape.","zh":"朱古力或金屬模具會給最終產品形狀。"},{"en":"If cannonball moulds produce smoother balls, those balls may travel farther and more accurately.","zh":"如果炮彈模具製造出更平滑的炮彈，炮彈可能飛得更遠和更準確。"},{"en":"The phrase refers to equipment used in making ammunition.","zh":"這個短語指製造彈藥時使用的設備。"}],"source":"47 - The History of Pencil.pdf","sourcePage":9},{"front":"rounder, smoother balls","meaning":"更圓、更平滑的炮彈","examples":[{"en":"The moulds produced rounder, smoother balls.","zh":"這些模具製造出更圓、更平滑的炮彈。"},{"en":"Rounder, smoother balls are balls with a more even shape and surface.","zh":"更圓、更平滑的炮彈是形狀和表面更均勻的球體。"},{"en":"A smoother football rolls more predictably across the ground.","zh":"更平滑的足球在地面上滾動時更可預測。"},{"en":"If cannonballs are rounder and smoother, they may fly farther and more steadily.","zh":"如果炮彈更圓、更平滑，就可能飛得更遠、更穩定。"},{"en":"The phrase describes improved shape and surface quality.","zh":"這個短語描述形狀和表面質素的改善。"}],"source":"47 - The History of Pencil.pdf","sourcePage":9},{"front":"be fired farther","meaning":"可射得更遠","examples":[{"en":"The smoother balls could be fired farther.","zh":"更平滑的炮彈可射得更遠。"},{"en":"To be fired farther means to be shot a longer distance from a weapon.","zh":"“Be fired farther” 指從武器發射後飛行更長距離。"},{"en":"A ball with a smoother surface may travel farther when thrown or kicked.","zh":"表面更平滑的球被投擲或踢出時，可能飛得更遠。"},{"en":"If cannonballs can be fired farther, a navy can attack targets from a safer distance.","zh":"如果炮彈可射得更遠，海軍就能從較安全距離攻擊目標。"},{"en":"The phrase links design improvement with greater range.","zh":"這個短語把設計改善與更遠射程連繫起來。"}],"source":"47 - The History of Pencil.pdf","sourcePage":9},{"front":"thereby strengthening","meaning":"從而加強","examples":[{"en":"The new cannonballs could be fired farther, thereby strengthening the English navy.","zh":"新炮彈可射得更遠，從而加強英格蘭海軍。"},{"en":"Thereby strengthening means making something stronger as a result of the previous action.","zh":"“Thereby strengthening” 指因前一行動的結果而令某事更強。"},{"en":"A school may improve teacher training, thereby strengthening classroom quality.","zh":"學校可能改善教師培訓，從而加強課堂質素。"},{"en":"If better materials improve weapons, they may thereby strengthen a military force.","zh":"如果更好材料改善武器，它們可能從而加強軍事力量。"},{"en":"The phrase shows the result of an earlier improvement.","zh":"這個短語顯示早前改善帶來的結果。"}],"source":"47 - The History of Pencil.pdf","sourcePage":9},{"front":"the English navy","meaning":"英格蘭海軍","examples":[{"en":"The use of graphite helped strengthen the English navy.","zh":"石墨的使用幫助加強英格蘭海軍。"},{"en":"The English navy was England’s naval military force.","zh":"英格蘭海軍是英格蘭的海上軍事力量。"},{"en":"A navy protects sea routes, ships and coastlines during war or conflict.","zh":"海軍在戰爭或衝突期間保護海路、船隻和海岸線。"},{"en":"If better cannonballs strengthened the English navy, graphite had military importance beyond pencils.","zh":"如果更好的炮彈加強英格蘭海軍，石墨就有鉛筆以外的軍事重要性。"},{"en":"The phrase refers to a historical naval force.","zh":"這個短語指歷史上的海軍力量。"}],"source":"47 - The History of Pencil.pdf","sourcePage":9},{"front":"this particular graphite deposit","meaning":"這個特定的石墨礦床","examples":[{"en":"This particular graphite deposit was extremely pure and soft.","zh":"這個特定的石墨礦床極為純淨而柔軟。"},{"en":"This particular graphite deposit means this specific natural concentration of graphite in the ground.","zh":"這個特定的石墨礦床，指地下這一處特定的天然石墨集中地。"},{"en":"A particular gold deposit may become famous if the metal there is unusually pure.","zh":"如果某個金礦床的金屬異常純淨，它可能變得有名。"},{"en":"If one deposit has special qualities, it may be more valuable than ordinary deposits.","zh":"如果一個礦床有特殊品質，它可能比普通礦床更有價值。"},{"en":"The phrase points to one specific source of graphite.","zh":"這個短語指向一個特定石墨來源。"}],"source":"47 - The History of Pencil.pdf","sourcePage":9},{"front":"extremely pure and soft","meaning":"極為純淨而柔軟","examples":[{"en":"The Borrowdale graphite was extremely pure and soft.","zh":"Borrowdale 石墨極為純淨而柔軟。"},{"en":"Extremely pure and soft means containing very few impurities and having a gentle, easily marked texture.","zh":"“Extremely pure and soft” 指雜質非常少，而且質地柔和、容易留下痕跡。"},{"en":"Very pure clay can be useful for fine pottery because it behaves predictably.","zh":"非常純淨的黏土可用於精細陶器，因為它表現較可預測。"},{"en":"If graphite is extremely pure and soft, it can be broken, shaped and used for marking more easily.","zh":"如果石墨極為純淨而柔軟，就更容易被折斷、塑形和用作標記。"},{"en":"The phrase describes two qualities that made the deposit valuable.","zh":"這個短語描述令礦床有價值的兩個特質。"}],"source":"47 - The History of Pencil.pdf","sourcePage":10},{"front":"be broken into sticks","meaning":"被折成棒狀","examples":[{"en":"The graphite could easily be broken into sticks.","zh":"這種石墨很容易被折成棒狀。"},{"en":"To be broken into sticks means to be separated into long, narrow pieces.","zh":"“Be broken into sticks” 指被分成細長條狀。"},{"en":"A bar of chalk can be broken into sticks for several students to use.","zh":"一條粉筆可以被折成幾支，供幾名學生使用。"},{"en":"If graphite can be broken into sticks, it becomes easier to hold and use for writing.","zh":"如果石墨可以被折成棒狀，就更容易握住並用來書寫。"},{"en":"The phrase describes shaping a material into practical pieces.","zh":"這個短語描述把材料變成實用形狀。"}],"source":"47 - The History of Pencil.pdf","sourcePage":10},{"front":"because of its military importance","meaning":"由於其軍事重要性","examples":[{"en":"Because of its military importance, the Crown strictly controlled the mine.","zh":"由於其軍事重要性，英國王室嚴格控制該礦場。"},{"en":"Because of its military importance means because it was valuable for defence or warfare.","zh":"“Because of its military importance” 指因它對防衛或戰爭有價值。"},{"en":"A government may protect a factory because of its military importance during wartime.","zh":"戰時政府可能由於某工廠的軍事重要性而保護它。"},{"en":"If a material helps weapons work better, its military importance may lead to strict control.","zh":"如果材料幫助武器更有效運作，其軍事重要性可能導致嚴格控制。"},{"en":"The phrase explains a reason connected with war and national defence.","zh":"這個短語解釋與戰爭和國防相關的原因。"}],"source":"47 - The History of Pencil.pdf","sourcePage":10},{"front":"the Crown","meaning":"英國王室；王權","examples":[{"en":"The Crown strictly controlled this unique mine and its output.","zh":"英國王室嚴格控制這個獨特礦場及其產量。"},{"en":"The Crown means the monarchy or royal authority of Britain.","zh":"“The Crown” 指英國君主制度或王室權力。"},{"en":"In historical writing, the Crown may refer to decisions made by the king, queen or royal government.","zh":"在歷史寫作中，the Crown 可能指由國王、女王或王室政府作出的決定。"},{"en":"If the Crown controls a resource, it treats that resource as important to state power.","zh":"如果英國王室控制某資源，就是把該資源視為對國家權力重要。"},{"en":"The phrase is formal and often appears in British historical contexts.","zh":"這個短語較正式，常出現在英國歷史語境中。"}],"source":"47 - The History of Pencil.pdf","sourcePage":10},{"front":"strictly controlled","meaning":"嚴格控制","examples":[{"en":"The Crown strictly controlled the mine and its output.","zh":"英國王室嚴格控制該礦場及其產量。"},{"en":"Strictly controlled means managed with tight rules and limited freedom.","zh":"“Strictly controlled” 指以嚴格規則管理，並限制自由。"},{"en":"A school may strictly control access to exam papers before the test.","zh":"學校可能在考試前嚴格控制試卷接觸權限。"},{"en":"If a mine is strictly controlled, workers and buyers cannot freely take or sell its material.","zh":"如果礦場被嚴格控制，工人和買家就不能自由取走或出售其材料。"},{"en":"The phrase suggests strong supervision and restriction.","zh":"這個短語暗示強力監管和限制。"}],"source":"47 - The History of Pencil.pdf","sourcePage":10},{"front":"this unique mine","meaning":"這個獨特的礦場","examples":[{"en":"The Crown strictly controlled this unique mine.","zh":"英國王室嚴格控制這個獨特的礦場。"},{"en":"This unique mine means this special mine that had qualities not found in ordinary mines.","zh":"這個獨特的礦場指這個具有普通礦場沒有的特質的特殊礦場。"},{"en":"A unique mine may be valuable because its minerals are purer or easier to extract.","zh":"獨特的礦場可能因礦物更純或更易開採而有價值。"},{"en":"If a mine is unique, a government may protect it more carefully.","zh":"如果礦場獨特，政府可能更仔細地保護它。"},{"en":"The phrase highlights the special nature of one mining site.","zh":"這個短語突出某一採礦地點的特殊性。"}],"source":"47 - The History of Pencil.pdf","sourcePage":10},{"front":"its output","meaning":"其產量","examples":[{"en":"The Crown controlled the mine and its output.","zh":"英國王室控制該礦場及其產量。"},{"en":"Its output means the amount of material produced or taken from it.","zh":"其產量指由它生產或開採出來的材料數量。"},{"en":"A factory’s output may increase when new machines are installed.","zh":"當新機器安裝後，工廠的產量可能增加。"},{"en":"If a government controls a mine’s output, it can decide how much material enters the market.","zh":"如果政府控制礦場產量，就能決定多少材料進入市場。"},{"en":"The phrase refers to production quantity.","zh":"這個短語指生產數量。"}],"source":"47 - The History of Pencil.pdf","sourcePage":10},{"front":"the claim that","meaning":"……的說法","examples":[{"en":"The claim that the United States spent $1,000 developing a space pencil is fiction.","zh":"美國花1,000美元研發太空鉛筆的說法是虛構的。"},{"en":"The claim that introduces a statement someone says is true, whether or not it is actually true.","zh":"“The claim that” 引出某人聲稱為真的陳述，不論它實際上是否正確。"},{"en":"The claim that all students learn best at night is easy to question.","zh":"所有學生晚上學得最好的說法很容易被質疑。"},{"en":"If a claim sounds surprising, readers should check whether evidence supports it.","zh":"如果一個說法聽起來令人驚訝，讀者應檢查是否有證據支持。"},{"en":"The phrase introduces an idea that may need proof.","zh":"這個短語引出可能需要證明的想法。"}],"source":"47 - The History of Pencil.pdf","sourcePage":10},{"front":"spend money developing","meaning":"花錢研發","examples":[{"en":"The United States did not spend $1,000 developing a zero-gravity pencil before using pencils in space.","zh":"美國並沒有在太空使用鉛筆前花1,000美元研發零重力鉛筆。"},{"en":"To spend money developing something means to use funds to research, design or improve it.","zh":"“Spend money developing” 某物指使用資金研究、設計或改良它。"},{"en":"A company may spend money developing a new app before it earns any profit.","zh":"公司可能在賺取任何利潤前，花錢研發新應用程式。"},{"en":"If a government spends money developing technology, people may ask whether the cost is justified.","zh":"如果政府花錢研發科技，人們可能問成本是否合理。"},{"en":"The phrase links financial cost with invention or improvement.","zh":"這個短語把財務成本與發明或改良連繫起來。"}],"source":"47 - The History of Pencil.pdf","sourcePage":10},{"front":"zero-gravity pencil","meaning":"零重力鉛筆","examples":[{"en":"The zero-gravity pencil was invented after pencils had already been used in space.","zh":"零重力鉛筆是在鉛筆已經被用於太空之後才發明的。"},{"en":"A zero-gravity pencil is a writing tool designed to work where there is little or no gravity.","zh":"零重力鉛筆是在幾乎沒有重力的環境中也能使用的書寫工具。"},{"en":"Astronauts need reliable writing tools because ordinary materials can break or float away in space.","zh":"太空人需要可靠書寫工具，因為普通材料在太空中可能斷裂或飄走。"},{"en":"If a pencil is designed for zero gravity, it must reduce risks from broken pieces and floating fragments.","zh":"如果鉛筆為零重力環境而設，就必須減少斷裂碎片和飄浮碎片的風險。"},{"en":"The phrase refers to a pencil made for space conditions.","zh":"這個短語指為太空環境製作的鉛筆。"}],"source":"47 - The History of Pencil.pdf","sourcePage":10},{"front":"be fiction","meaning":"是虛構的","examples":[{"en":"The story about the $1,000 pencil is fiction.","zh":"關於1,000美元鉛筆的故事是虛構的。"},{"en":"To be fiction means to be invented or not true.","zh":"“Be fiction” 指被編造或不真實。"},{"en":"A rumour about a school closing may be fiction if no official notice supports it.","zh":"如果沒有官方通告支持，關於學校關閉的傳聞可能是虛構的。"},{"en":"If a popular story is fiction, people may repeat it because it sounds interesting, not because it is accurate.","zh":"如果流行故事是虛構的，人們可能因它有趣而重複它，而不是因為它準確。"},{"en":"The phrase separates a false story from fact.","zh":"這個短語把虛假故事與事實分開。"}],"source":"47 - The History of Pencil.pdf","sourcePage":10},{"front":"Russian astronauts","meaning":"俄羅斯太空人","examples":[{"en":"Russian astronauts are widely known to have used grease pencils.","zh":"俄羅斯太空人廣為人知曾經使用油性鉛筆。"},{"en":"Russian astronauts are space travellers from Russia or the former Soviet space programme.","zh":"俄羅斯太空人是來自俄羅斯或前蘇聯太空計劃的太空旅行者。"},{"en":"Astronauts need tools that work safely in small spacecraft and unusual conditions.","zh":"太空人需要能在狹小太空船和特殊環境中安全使用的工具。"},{"en":"If Russian astronauts used grease pencils, they chose a writing tool that avoided some breakage problems.","zh":"如果俄羅斯太空人使用油性鉛筆，他們選擇的是避免某些斷裂問題的書寫工具。"},{"en":"The phrase identifies a group of space travellers by nationality.","zh":"這個短語按國籍指出一群太空旅行者。"}],"source":"47 - The History of Pencil.pdf","sourcePage":11},{"front":"be widely known to have","meaning":"廣為人知曾經……","examples":[{"en":"Russian astronauts are widely known to have used grease pencils.","zh":"俄羅斯太空人廣為人知曾經使用油性鉛筆。"},{"en":"To be widely known to have done something means many people know or believe that it happened.","zh":"“Be widely known to have” 做過某事指許多人知道或相信該事發生過。"},{"en":"The library is widely known to have helped many students prepare for exams.","zh":"圖書館廣為人知曾經幫助許多學生準備考試。"},{"en":"If an event is widely known, it is not a hidden or private detail.","zh":"如果一件事廣為人知，它就不是隱藏或私人細節。"},{"en":"The phrase introduces a fact or belief familiar to many people.","zh":"這個短語引出許多人熟悉的事實或看法。"}],"source":"47 - The History of Pencil.pdf","sourcePage":11},{"front":"grease pencils","meaning":"油性鉛筆","examples":[{"en":"Russian astronauts used grease pencils in space.","zh":"俄羅斯太空人在太空使用油性鉛筆。"},{"en":"Grease pencils are writing tools with waxy or oily cores that can mark smooth surfaces.","zh":"油性鉛筆是有蠟質或油性筆芯、可在光滑表面作標記的書寫工具。"},{"en":"A shop worker may use a grease pencil to write prices on glass or plastic.","zh":"店員可能使用油性鉛筆在玻璃或塑膠上寫價格。"},{"en":"Because grease pencils do not have brittle graphite tips, they may avoid some breakage problems.","zh":"由於油性鉛筆沒有易碎的石墨尖端，它們可能避免某些斷裂問題。"},{"en":"The phrase refers to a special kind of wax-like pencil.","zh":"這個短語指一種特殊的蠟質鉛筆。"}],"source":"47 - The History of Pencil.pdf","sourcePage":11},{"front":"present a breakage problem","meaning":"造成斷裂問題","examples":[{"en":"Grease pencils did not present a breakage problem.","zh":"油性鉛筆沒有造成斷裂問題。"},{"en":"To present a breakage problem means to create a risk that parts may break off.","zh":"“Present a breakage problem” 指造成部件可能折斷的風險。"},{"en":"Thin glass cups present a breakage problem in a busy school canteen.","zh":"薄玻璃杯在繁忙學校飯堂中會造成斷裂問題。"},{"en":"If a writing tool presents a breakage problem in space, small pieces may float into equipment.","zh":"如果書寫工具在太空造成斷裂問題，小碎片可能飄入設備。"},{"en":"The phrase identifies a practical safety risk.","zh":"這個短語指出實際安全風險。"}],"source":"47 - The History of Pencil.pdf","sourcePage":11},{"front":"American counterparts","meaning":"美國方面的相應人員","examples":[{"en":"Their American counterparts also used pencils in space.","zh":"他們的美國方面相應人員也在太空使用鉛筆。"},{"en":"American counterparts are people in the United States who have the same role as another group being discussed.","zh":"美國方面的相應人員，是在美國擔任與所討論另一群體相同角色的人。"},{"en":"British teachers may compare classroom methods with their American counterparts.","zh":"英國老師可能把課堂方法與美國同行比較。"},{"en":"If Russian astronauts used one tool and their American counterparts used another, the two groups made different choices.","zh":"如果俄羅斯太空人使用一種工具，而美國方面相應人員使用另一種，兩組人就作出了不同選擇。"},{"en":"The phrase compares people with equivalent roles in different countries.","zh":"這個短語比較不同國家中角色相等的人。"}],"source":"47 - The History of Pencil.pdf","sourcePage":11},{"front":"before a true zero-gravity pencil was invented","meaning":"在真正的零重力鉛筆被發明之前","examples":[{"en":"American astronauts used pencils before a true zero-gravity pencil was invented.","zh":"美國太空人在真正的零重力鉛筆被發明之前使用鉛筆。"},{"en":"Before a true zero-gravity pencil was invented means during the period before a pencil specially designed for space existed.","zh":"“Before a true zero-gravity pencil was invented” 指在專為太空設計的鉛筆存在之前的時期。"},{"en":"Before online maps were invented, travellers relied on paper maps and road signs.","zh":"在網上地圖被發明之前，旅客依靠紙本地圖和路牌。"},{"en":"If astronauts used ordinary pencils before a special version existed, early solutions were practical but imperfect.","zh":"如果太空人在特殊版本存在前使用普通鉛筆，早期解決方法就是實用但不完美。"},{"en":"The phrase sets a time before a later invention.","zh":"這個短語設定後來發明之前的時間。"}],"source":"47 - The History of Pencil.pdf","sourcePage":11},{"front":"favour mechanical pencils","meaning":"偏好自動鉛筆","examples":[{"en":"The Americans favoured mechanical pencils.","zh":"美國人偏好自動鉛筆。"},{"en":"To favour mechanical pencils means to prefer them over other writing tools.","zh":"“Favour mechanical pencils” 指比其他書寫工具更喜歡自動鉛筆。"},{"en":"A student may favour mechanical pencils because they do not need sharpening.","zh":"學生可能偏好自動鉛筆，因為它們不需要削尖。"},{"en":"If astronauts favoured mechanical pencils, they valued their fine and clear lines.","zh":"如果太空人偏好自動鉛筆，他們重視其幼細而清晰的線條。"},{"en":"The phrase shows preference for one type of pencil.","zh":"這個短語顯示對某類鉛筆的偏好。"}],"source":"47 - The History of Pencil.pdf","sourcePage":11},{"front":"mechanical pencils","meaning":"自動鉛筆","examples":[{"en":"Mechanical pencils produced finer, clearer lines.","zh":"自動鉛筆能畫出更幼細、更清晰的線條。"},{"en":"Mechanical pencils are pencils with replaceable thin leads that are pushed forward by a mechanism.","zh":"自動鉛筆是配有可替換幼鉛芯，並透過機械裝置推出鉛芯的鉛筆。"},{"en":"Many students use mechanical pencils because they stay sharp without sharpening.","zh":"許多學生使用自動鉛筆，因為它們不用削也能保持尖細。"},{"en":"If the lead in a mechanical pencil is too thin, it may break under pressure.","zh":"如果自動鉛筆的鉛芯太幼，在壓力下可能折斷。"},{"en":"The phrase refers to a pencil with an internal lead-feeding system.","zh":"這個短語指有內部送芯系統的鉛筆。"}],"source":"47 - The History of Pencil.pdf","sourcePage":11},{"front":"finer, clearer lines","meaning":"更幼細、更清晰的線條","examples":[{"en":"Mechanical pencils produced finer, clearer lines than grease pencils.","zh":"自動鉛筆比油性鉛筆畫出更幼細、更清晰的線條。"},{"en":"Finer, clearer lines are thinner and easier-to-see marks.","zh":"更幼細、更清晰的線條，是更薄且更容易看見的痕跡。"},{"en":"An architect may need finer, clearer lines when drawing a detailed floor plan.","zh":"建築師繪製詳細平面圖時，可能需要更幼細、更清晰的線條。"},{"en":"If a pencil makes finer, clearer lines, notes and diagrams may be easier to read.","zh":"如果鉛筆畫出更幼細、更清晰的線條，筆記和圖表可能更易讀。"},{"en":"The phrase describes improved line quality.","zh":"這個短語描述線條質素改善。"}],"source":"47 - The History of Pencil.pdf","sourcePage":11},{"front":"smudged lines","meaning":"模糊的線條","examples":[{"en":"Grease pencils left smudged lines.","zh":"油性鉛筆留下模糊的線條。"},{"en":"Smudged lines are marks that look blurred, smeared or unclear.","zh":"模糊的線條是看起來不清、被抹開或不明晰的痕跡。"},{"en":"A left-handed student may get smudged lines if the ink does not dry quickly.","zh":"如果墨水不快乾，左撇子學生可能寫出模糊的線條。"},{"en":"If writing leaves smudged lines, the reader may find the notes harder to read.","zh":"如果書寫留下模糊線條，讀者可能覺得筆記較難閱讀。"},{"en":"The phrase describes messy or unclear marks.","zh":"這個短語描述凌亂或不清晰的痕跡。"}],"source":"47 - The History of Pencil.pdf","sourcePage":11},{"front":"the lead tips","meaning":"鉛芯尖端","examples":[{"en":"The lead tips of mechanical pencils broke frequently.","zh":"自動鉛筆的鉛芯尖端經常折斷。"},{"en":"The lead tips are the narrow writing points at the end of pencil leads.","zh":"鉛芯尖端是鉛芯末端用來書寫的細小尖點。"},{"en":"A student may break the lead tip by pressing too hard during a test.","zh":"學生在測驗中用力太大，可能折斷鉛芯尖端。"},{"en":"If lead tips break in space, tiny fragments may become dangerous.","zh":"如果鉛芯尖端在太空折斷，微小碎片可能變得危險。"},{"en":"The phrase refers to the fragile pointed end used for writing.","zh":"這個短語指用來書寫的脆弱尖端。"}],"source":"47 - The History of Pencil.pdf","sourcePage":11},{"front":"break frequently","meaning":"經常折斷","examples":[{"en":"The lead tips of mechanical pencils broke frequently.","zh":"自動鉛筆的鉛芯尖端經常折斷。"},{"en":"To break frequently means to break often or again and again.","zh":"“Break frequently” 指經常或反覆折斷。"},{"en":"Cheap headphones may break frequently if the wires are weak.","zh":"如果電線脆弱，廉價耳機可能經常壞掉。"},{"en":"If pencil tips break frequently, writing becomes slower and more frustrating.","zh":"如果鉛筆尖端經常折斷，書寫會變得更慢和更令人沮喪。"},{"en":"The phrase describes repeated breakage.","zh":"這個短語描述反覆斷裂。"}],"source":"47 - The History of Pencil.pdf","sourcePage":12},{"front":"a fragment of graphite","meaning":"一小塊石墨碎片","examples":[{"en":"A fragment of graphite could float around a space capsule.","zh":"一小塊石墨碎片可能在太空艙中四處飄浮。"},{"en":"A fragment of graphite is a small broken piece of graphite.","zh":"一小塊石墨碎片是折斷出來的細小石墨。"},{"en":"A broken pencil tip may leave a tiny fragment of graphite on the desk.","zh":"折斷的鉛筆尖可能在書桌上留下一小塊石墨碎片。"},{"en":"If a fragment of graphite floats in a spacecraft, it may enter eyes or equipment.","zh":"如果一小塊石墨碎片在太空船中飄浮，它可能進入眼睛或設備。"},{"en":"The phrase describes a small piece that has broken away.","zh":"這個短語描述斷裂出來的小塊。"}],"source":"47 - The History of Pencil.pdf","sourcePage":12},{"front":"float around","meaning":"四處飄浮","examples":[{"en":"A fragment of graphite could float around a space capsule.","zh":"一小塊石墨碎片可能在太空艙中四處飄浮。"},{"en":"To float around means to move freely in the air or liquid without staying in one fixed place.","zh":"“Float around” 指在空氣或液體中自由移動，不固定在一個地方。"},{"en":"Dust may float around a classroom when windows are opened after cleaning.","zh":"清潔後打開窗戶時，灰塵可能在課室中四處飄浮。"},{"en":"In space, small objects can float around because there is very little gravity.","zh":"在太空中，小物件可以四處飄浮，因為重力很小。"},{"en":"The phrase describes uncontrolled movement through an area.","zh":"這個短語描述在某區域中不受控制地移動。"}],"source":"47 - The History of Pencil.pdf","sourcePage":12},{"front":"a space capsule","meaning":"太空艙","examples":[{"en":"A fragment of graphite could float around a space capsule.","zh":"一小塊石墨碎片可能在太空艙中四處飄浮。"},{"en":"A space capsule is a small spacecraft or compartment used to carry astronauts.","zh":"太空艙是用來運載太空人的小型太空船或艙室。"},{"en":"Astronauts inside a space capsule must keep tools and objects secure.","zh":"太空艙內的太空人必須固定工具和物件。"},{"en":"If a small fragment floats around a capsule, it can become a safety risk.","zh":"如果小碎片在太空艙中飄浮，就可能成為安全風險。"},{"en":"The phrase refers to the enclosed vehicle or cabin used in space travel.","zh":"這個短語指太空旅行中使用的封閉飛行器或艙室。"}],"source":"47 - The History of Pencil.pdf","sourcePage":12},{"front":"enter someone’s eye","meaning":"進入某人的眼睛","examples":[{"en":"A graphite fragment could enter someone’s eye.","zh":"石墨碎片可能進入某人的眼睛。"},{"en":"To enter someone’s eye means to get into the eye, often accidentally and dangerously.","zh":"“Enter someone’s eye” 指進入眼睛，通常是意外且危險的。"},{"en":"Dust can enter someone’s eye on a windy day and cause pain.","zh":"大風天，灰塵可以進入某人的眼睛並造成疼痛。"},{"en":"If a sharp or dirty fragment enters the eye, it may injure the person.","zh":"如果尖銳或骯髒碎片進入眼睛，可能弄傷該人。"},{"en":"The phrase describes a physical safety hazard.","zh":"這個短語描述身體安全危害。"}],"source":"47 - The History of Pencil.pdf","sourcePage":12},{"front":"find its way into","meaning":"進入；落入","examples":[{"en":"A fragment could find its way into machinery or electronics.","zh":"碎片可能進入機械或電子設備。"},{"en":"To find its way into something means to accidentally or gradually get inside it.","zh":"“Find its way into” 某物指意外或逐漸進入其中。"},{"en":"Sand can find its way into a camera if it is used on a beach.","zh":"如果相機在海灘使用，沙粒可能進入相機。"},{"en":"If graphite finds its way into electronics, it may damage circuits because it conducts electricity.","zh":"如果石墨進入電子設備，可能因其導電而損壞電路。"},{"en":"The phrase often suggests something entering where it should not be.","zh":"這個短語常暗示某物進入不應進入的地方。"}],"source":"47 - The History of Pencil.pdf","sourcePage":12},{"front":"machinery or electronics","meaning":"機械或電子設備","examples":[{"en":"Graphite could damage machinery or electronics.","zh":"石墨可能損壞機械或電子設備。"},{"en":"Machinery or electronics means mechanical equipment or electronic devices and systems.","zh":"機械或電子設備指機械裝置或電子裝置及系統。"},{"en":"Dust inside machinery or electronics can make a computer or printer stop working.","zh":"機械或電子設備內的灰塵可以令電腦或打印機停止運作。"},{"en":"If tiny fragments enter machinery or electronics, repairs may be difficult or dangerous.","zh":"如果微小碎片進入機械或電子設備，維修可能困難或危險。"},{"en":"The phrase covers both moving machine parts and electrical systems.","zh":"這個短語同時涵蓋活動機械部件和電力系統。"}],"source":"47 - The History of Pencil.pdf","sourcePage":12},{"front":"cause a short circuit","meaning":"造成短路","examples":[{"en":"A graphite fragment could cause a short circuit.","zh":"石墨碎片可能造成短路。"},{"en":"To cause a short circuit means to create an unintended electrical path that can damage a device.","zh":"“Cause a short circuit” 指造成非預期電流路徑，可能損壞設備。"},{"en":"Water inside a phone may cause a short circuit and stop it from turning on.","zh":"手機進水可能造成短路，使它無法開機。"},{"en":"If graphite touches the wrong electronic parts, it may cause electrical failure.","zh":"如果石墨接觸錯誤電子部件，可能造成電力故障。"},{"en":"The phrase explains one danger of loose conductive material.","zh":"這個短語解釋鬆散導電材料的一種危險。"}],"source":"47 - The History of Pencil.pdf","sourcePage":12},{"front":"short circuit","meaning":"短路","examples":[{"en":"A fragment of graphite could cause a short circuit.","zh":"一小塊石墨碎片可能造成短路。"},{"en":"A short circuit is an electrical problem where current follows the wrong path.","zh":"短路是電流沿錯誤路徑流動的電力問題。"},{"en":"A damaged wire can create a short circuit and make a lamp stop working.","zh":"損壞的電線可以造成短路，使燈停止運作。"},{"en":"If a short circuit happens in a spacecraft, equipment may fail at a dangerous moment.","zh":"如果太空船內發生短路，設備可能在危險時刻失靈。"},{"en":"The phrase refers to a fault in an electrical system.","zh":"這個短語指電力系統中的故障。"}],"source":"47 - The History of Pencil.pdf","sourcePage":12},{"front":"other problems","meaning":"其他問題","examples":[{"en":"The fragment could cause a short circuit or other problems.","zh":"碎片可能造成短路或其他問題。"},{"en":"Other problems means additional difficulties or dangers besides the one already mentioned.","zh":"其他問題指除了已提及問題之外的額外困難或危險。"},{"en":"A leaking roof can cause wet floors, damaged books and other problems in a classroom.","zh":"漏水屋頂可以在課室造成地板濕滑、書本損壞和其他問題。"},{"en":"If a tiny object floats in a spacecraft, it may cause eye injuries, equipment damage or other problems.","zh":"如果微小物件在太空船中飄浮，可能造成眼部受傷、設備損壞或其他問題。"},{"en":"The phrase keeps the list open when not every problem is named.","zh":"這個短語在沒有逐一列出所有問題時保持列表開放。"}],"source":"47 - The History of Pencil.pdf","sourcePage":12},{"front":"continue using","meaning":"繼續使用","examples":[{"en":"The Americans continued using mechanical pencils for many years.","zh":"美國人多年來繼續使用自動鉛筆。"},{"en":"To continue using something means to keep using it over time.","zh":"“Continue using” 某物指隨時間持續使用它。"},{"en":"Students may continue using paper notebooks even after tablets become available.","zh":"即使有平板電腦可用，學生仍可能繼續使用紙本筆記簿。"},{"en":"If a tool still works well enough, people may continue using it despite known disadvantages.","zh":"如果工具仍然足夠好用，即使有已知缺點，人們也可能繼續使用它。"},{"en":"The phrase shows that an action did not stop.","zh":"這個短語顯示行動沒有停止。"}],"source":"47 - The History of Pencil.pdf","sourcePage":12},{"front":"for many years","meaning":"多年來","examples":[{"en":"They continued using mechanical pencils for many years.","zh":"他們多年來繼續使用自動鉛筆。"},{"en":"For many years means over a long period of time.","zh":"“For many years” 指經過很長一段時間。"},{"en":"A family may live in the same flat for many years before moving.","zh":"一個家庭可能多年來住在同一個單位，然後才搬家。"},{"en":"If people use a tool for many years, it probably remains practical enough for their needs.","zh":"如果人們多年來使用某工具，它很可能仍足夠符合其需要。"},{"en":"The phrase emphasises duration.","zh":"這個短語強調持續時間。"}],"source":"47 - The History of Pencil.pdf","sourcePage":13},{"front":"against the backdrop of","meaning":"在……的背景下","examples":[{"en":"Against the backdrop of a digitised world, the pencil’s prospects may seem bleak.","zh":"在數碼化世界的背景下，鉛筆的前景可能看似暗淡。"},{"en":"Against the backdrop of something means in the context of that wider situation.","zh":"“Against the backdrop of” 某事指在該更大情況的背景中。"},{"en":"Against the backdrop of rising rents, many young people delay moving out.","zh":"在租金上升的背景下，許多年輕人延遲搬出去住。"},{"en":"If pencils are discussed against the backdrop of digital technology, their future may look uncertain.","zh":"如果在數碼科技背景下討論鉛筆，其未來可能看似不確定。"},{"en":"The phrase gives the larger setting for an idea or problem.","zh":"這個短語給出想法或問題的更大背景。"}],"source":"47 - The History of Pencil.pdf","sourcePage":13},{"front":"a digitised world","meaning":"數碼化世界","examples":[{"en":"Pencils still survive in a digitised world.","zh":"鉛筆在數碼化世界中仍然生存。"},{"en":"A digitised world is a world where information, work and communication are increasingly handled by digital technology.","zh":"數碼化世界是資訊、工作和溝通越來越由數碼科技處理的世界。"},{"en":"In a digitised world, students may type notes, submit homework online and read e-books.","zh":"在數碼化世界中，學生可能打字記筆記、網上交功課和閱讀電子書。"},{"en":"If an old tool survives in a digitised world, it still offers something useful that screens do not replace.","zh":"如果舊工具在數碼化世界中仍然存在，它仍提供螢幕不能取代的有用之處。"},{"en":"The phrase describes modern life shaped by digital systems.","zh":"這個短語描述由數碼系統塑造的現代生活。"}],"source":"47 - The History of Pencil.pdf","sourcePage":13},{"front":"the pencil’s prospects","meaning":"鉛筆的前景","examples":[{"en":"The pencil’s prospects may seem bleak in a digitised world.","zh":"在數碼化世界中，鉛筆的前景可能看似暗淡。"},{"en":"The pencil’s prospects means the pencil’s future chances of survival, use or success.","zh":"鉛筆的前景指鉛筆未來生存、使用或成功的機會。"},{"en":"A company’s prospects may improve if demand for its products rises.","zh":"如果產品需求上升，公司的前景可能改善。"},{"en":"If fewer people write by hand, the pencil’s prospects may appear weaker.","zh":"如果較少人手寫，鉛筆的前景可能看起來較弱。"},{"en":"The phrase asks what is likely to happen to pencils in the future.","zh":"這個短語詢問鉛筆未來可能如何。"}],"source":"47 - The History of Pencil.pdf","sourcePage":13},{"front":"may seem bleak","meaning":"可能看似暗淡","examples":[{"en":"The pencil’s prospects may seem bleak.","zh":"鉛筆的前景可能看似暗淡。"},{"en":"May seem bleak means may appear hopeless, weak or unlikely to succeed.","zh":"“May seem bleak” 指可能看起來沒有希望、薄弱或不太可能成功。"},{"en":"A student’s exam result may seem bleak after a poor mock test, but improvement is still possible.","zh":"學生模擬試成績差後，考試前景可能看似暗淡，但仍可改善。"},{"en":"If digital tools replace handwriting in many places, the future of pencils may seem bleak.","zh":"如果數碼工具在許多地方取代手寫，鉛筆的未來可能看似暗淡。"},{"en":"The phrase describes a negative appearance, not always the final reality.","zh":"這個短語描述負面表象，但不一定是最終現實。"}],"source":"47 - The History of Pencil.pdf","sourcePage":13},{"front":"in reality","meaning":"事實上","examples":[{"en":"In reality, pencils are still widely used.","zh":"事實上，鉛筆仍被廣泛使用。"},{"en":"In reality means in the actual situation, not just according to appearance or expectation.","zh":"“In reality” 指在實際情況中，而不只是根據表象或預期。"},{"en":"The job may look easy, but in reality it requires patience and planning.","zh":"這份工作可能看起來容易，但事實上需要耐性和規劃。"},{"en":"If pencils seem outdated, in reality they may still be useful in many settings.","zh":"如果鉛筆看似過時，事實上它們可能在許多場合仍然有用。"},{"en":"The phrase corrects a possible false impression.","zh":"這個短語糾正可能的錯誤印象。"}],"source":"47 - The History of Pencil.pdf","sourcePage":13},{"front":"be used so widely","meaning":"被如此廣泛使用","examples":[{"en":"Pencils are now used so widely that they can be found everywhere.","zh":"鉛筆現在被如此廣泛使用，以致隨處可見。"},{"en":"To be used so widely means to be used by many people in many places.","zh":"“Be used so widely” 指被許多地方的許多人使用。"},{"en":"Smartphones are used so widely that many shops expect customers to pay digitally.","zh":"智能手機被如此廣泛使用，以致許多商店預期顧客以數碼方式付款。"},{"en":"If pencils are used so widely, they remain important despite computers and tablets.","zh":"如果鉛筆被如此廣泛使用，即使有電腦和平板，它們仍然重要。"},{"en":"The phrase emphasises very broad use.","zh":"這個短語強調非常廣泛的使用。"}],"source":"47 - The History of Pencil.pdf","sourcePage":13},{"front":"be found everywhere","meaning":"隨處可見","examples":[{"en":"Pencils can be found everywhere.","zh":"鉛筆隨處可見。"},{"en":"To be found everywhere means to exist or appear in many ordinary places.","zh":"“Be found everywhere” 指在許多普通地方存在或出現。"},{"en":"Hand sanitiser can be found everywhere in hospitals, schools and shopping centres.","zh":"消毒搓手液在醫院、學校和商場中隨處可見。"},{"en":"If a tool can be found everywhere, it is cheap, useful and familiar to many people.","zh":"如果工具隨處可見，它就是便宜、有用且許多人熟悉。"},{"en":"The phrase describes something very common.","zh":"這個短語描述非常常見的事物。"}],"source":"47 - The History of Pencil.pdf","sourcePage":13},{"front":"including classrooms, meeting rooms and art studios","meaning":"包括課室、會議室和藝術工作室","examples":[{"en":"Pencils can be found in classrooms, meeting rooms and art studios.","zh":"鉛筆可以在課室、會議室和藝術工作室找到。"},{"en":"Including classrooms, meeting rooms and art studios gives examples of places where pencils are commonly used.","zh":"“Including classrooms, meeting rooms and art studios” 給出鉛筆常被使用的地方例子。"},{"en":"A simple tool can be useful in schools, offices and creative spaces.","zh":"簡單工具可以在學校、辦公室和創意空間中有用。"},{"en":"If pencils appear in these different places, their use is not limited to one group of people.","zh":"如果鉛筆出現在這些不同地方，它們的用途就不限於某一群人。"},{"en":"The phrase shows that pencils remain practical across many settings.","zh":"這個短語顯示鉛筆在許多場合仍然實用。"}],"source":"47 - The History of Pencil.pdf","sourcePage":13},{"front":"a broad range of people","meaning":"廣泛不同類型的人","examples":[{"en":"A broad range of people will probably continue using pencils.","zh":"廣泛不同類型的人很可能會繼續使用鉛筆。"},{"en":"A broad range of people means many different kinds of people.","zh":"“A broad range of people” 指許多不同類型的人。"},{"en":"A broad range of people use public libraries, including children, workers and retired adults.","zh":"廣泛不同類型的人使用公共圖書館，包括兒童、工人和退休人士。"},{"en":"If a broad range of people use a tool, it serves many different needs.","zh":"如果廣泛不同類型的人使用某工具，它就服務許多不同需要。"},{"en":"The phrase emphasises variety among users.","zh":"這個短語強調使用者的多樣性。"}],"source":"47 - The History of Pencil.pdf","sourcePage":13},{"front":"probably continue using","meaning":"很可能會繼續使用","examples":[{"en":"A broad range of people will probably continue using pencils.","zh":"廣泛不同類型的人很可能會繼續使用鉛筆。"},{"en":"Probably continue using means likely to keep using something in the future.","zh":"“Probably continue using” 指未來很可能繼續使用某物。"},{"en":"Students will probably continue using notebooks because handwriting helps some people remember better.","zh":"學生很可能會繼續使用筆記簿，因為手寫幫助一些人記得更好。"},{"en":"If a tool remains cheap and convenient, people will probably continue using it.","zh":"如果工具仍然便宜又方便，人們很可能會繼續使用它。"},{"en":"The phrase predicts continued use without claiming absolute certainty.","zh":"這個短語預測持續使用，但不是絕對肯定。"}],"source":"47 - The History of Pencil.pdf","sourcePage":13},{"front":"students for mathematics","meaning":"學生用於數學","examples":[{"en":"Students use pencils for mathematics.","zh":"學生用鉛筆做數學。"},{"en":"Students for mathematics means students use pencils when doing maths work such as calculations and diagrams.","zh":"“Students for mathematics” 指學生在做計算和圖形等數學工作時使用鉛筆。"},{"en":"A student may prefer a pencil for mathematics because mistakes can be erased easily.","zh":"學生可能偏好用鉛筆做數學，因為錯誤可以容易擦掉。"},{"en":"If maths work involves trial and correction, a pencil is more convenient than a pen.","zh":"如果數學涉及嘗試和修正，鉛筆比原子筆更方便。"},{"en":"The phrase gives one practical user and purpose for pencils.","zh":"這個短語給出鉛筆的一種實際使用者和用途。"}],"source":"47 - The History of Pencil.pdf","sourcePage":14},{"front":"artists for sketching","meaning":"藝術家用於素描","examples":[{"en":"Artists use pencils for sketching.","zh":"藝術家用鉛筆素描。"},{"en":"Artists for sketching means artists use pencils to make quick drawings or rough outlines.","zh":"“Artists for sketching” 指藝術家使用鉛筆畫快速圖畫或粗略輪廓。"},{"en":"An artist may sketch a face lightly before adding paint or ink.","zh":"藝術家可能先輕輕素描一張臉，然後才加上顏料或墨水。"},{"en":"If a drawing is only an early idea, pencil sketching allows easy changes.","zh":"如果圖畫只是早期想法，鉛筆素描讓修改變得容易。"},{"en":"The phrase gives a creative use of pencils.","zh":"這個短語給出鉛筆的創意用途。"}],"source":"47 - The History of Pencil.pdf","sourcePage":14},{"front":"record orders","meaning":"記錄訂單","examples":[{"en":"Waiters and waitresses use pencils to record orders.","zh":"男侍應和女侍應使用鉛筆記錄訂單。"},{"en":"To record orders means to write down what customers have asked to buy or eat.","zh":"“Record orders” 指寫下顧客要求購買或食用的東西。"},{"en":"A waiter may record orders quickly during a busy lunch hour.","zh":"侍應可能在繁忙午餐時間快速記錄訂單。"},{"en":"If orders are recorded clearly, the kitchen is less likely to make mistakes.","zh":"如果訂單記錄清楚，廚房較不容易出錯。"},{"en":"The phrase describes writing information for service and business.","zh":"這個短語描述為服務和生意而記下資料。"}],"source":"47 - The History of Pencil.pdf","sourcePage":14},{"front":"make-up artists","meaning":"化妝師","examples":[{"en":"Make-up artists use pencils for applying cosmetics.","zh":"化妝師使用鉛筆塗抹化妝品。"},{"en":"Make-up artists are people who apply cosmetics professionally for beauty, film, theatre or events.","zh":"化妝師是為美容、電影、劇場或活動專業塗抹化妝品的人。"},{"en":"A make-up artist may use an eyebrow pencil to shape a client’s brows.","zh":"化妝師可能使用眉筆為客人塑造眉形。"},{"en":"If make-up artists need precise lines, pencil-like tools are especially useful.","zh":"如果化妝師需要精準線條，類似鉛筆的工具就特別有用。"},{"en":"The phrase refers to professionals who work with cosmetics.","zh":"這個短語指從事化妝品工作的專業人士。"}],"source":"47 - The History of Pencil.pdf","sourcePage":14},{"front":"applying cosmetics","meaning":"塗抹化妝品","examples":[{"en":"Make-up artists use pencils for applying cosmetics.","zh":"化妝師使用鉛筆塗抹化妝品。"},{"en":"Applying cosmetics means putting make-up products on the face or body.","zh":"“Applying cosmetics” 指把化妝產品塗在臉上或身體上。"},{"en":"A performer may need help applying cosmetics before going on stage.","zh":"表演者上台前可能需要幫忙塗抹化妝品。"},{"en":"If cosmetics are applied carefully, they can change shape, colour and expression.","zh":"如果化妝品被仔細塗抹，它們可以改變形狀、顏色和表情。"},{"en":"The phrase describes the action of putting on make-up.","zh":"這個短語描述化妝的動作。"}],"source":"47 - The History of Pencil.pdf","sourcePage":14},{"front":"architects","meaning":"建築師","examples":[{"en":"Architects use pencils for producing blueprints.","zh":"建築師使用鉛筆繪製藍圖。"},{"en":"Architects are professionals who design buildings and plan how spaces should be used.","zh":"建築師是設計建築物並規劃空間如何使用的專業人士。"},{"en":"An architect may draw a house plan before builders begin construction.","zh":"建築師可能在建築工人開工前繪製房屋平面圖。"},{"en":"If architects make early sketches in pencil, they can revise the design more easily.","zh":"如果建築師用鉛筆畫早期草圖，就可以更容易修改設計。"},{"en":"The word refers to building designers.","zh":"這個詞指建築設計師。"}],"source":"47 - The History of Pencil.pdf","sourcePage":14},{"front":"producing blueprints","meaning":"繪製藍圖","examples":[{"en":"Architects use pencils for producing blueprints.","zh":"建築師使用鉛筆繪製藍圖。"},{"en":"Producing blueprints means creating detailed technical plans for a building or structure.","zh":"“Producing blueprints” 指為建築物或結構創造詳細技術圖則。"},{"en":"Before a school hall is built, architects may produce blueprints showing walls, doors and measurements.","zh":"在學校禮堂建成前，建築師可能繪製顯示牆壁、門和尺寸的藍圖。"},{"en":"If blueprints are clear, builders can understand exactly what to construct.","zh":"如果藍圖清晰，建築工人就能準確理解要建造甚麼。"},{"en":"The phrase describes making formal design plans.","zh":"這個短語描述製作正式設計圖則。"}],"source":"47 - The History of Pencil.pdf","sourcePage":14},{"front":"the possibilities seem limitless","meaning":"可能性似乎無限","examples":[{"en":"The possibilities for using pencils seem limitless.","zh":"使用鉛筆的可能性似乎無限。"},{"en":"The possibilities seem limitless means there appear to be countless possible uses or opportunities.","zh":"“The possibilities seem limitless” 指可能用途或機會看來多得數不完。"},{"en":"When students learn to use the internet wisely, the possibilities for research seem limitless.","zh":"當學生學會明智使用互聯網，研究的可能性似乎無限。"},{"en":"If a simple tool can serve students, artists, waiters and architects, its uses may seem endless.","zh":"如果簡單工具能服務學生、藝術家、侍應和建築師，其用途可能看似無窮。"},{"en":"The phrase expresses a very wide range of potential uses.","zh":"這個短語表達非常廣泛的潛在用途。"}],"source":"47 - The History of Pencil.pdf","sourcePage":14},{"front":"complete the sentences below","meaning":"完成以下句子","examples":[{"en":"Students complete the sentences below by choosing words from the passage.","zh":"學生透過從文章選詞完成以下句子。"},{"en":"Complete the sentences below means fill in the missing words in the sentences printed after the instruction.","zh":"“Complete the sentences below” 指填寫指示後方句子中的缺漏詞語。"},{"en":"In a reading test, students should read the whole sentence before choosing an answer.","zh":"在閱讀測驗中，學生應先讀完整句，再選答案。"},{"en":"If the sentence has a grammar clue, it can help students find the correct word.","zh":"如果句子有文法線索，它可以幫助學生找出正確詞語。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"47 - The History of Pencil.pdf","sourcePage":14},{"front":"choose one word only","meaning":"只選一個字","examples":[{"en":"Students must choose one word only from the passage.","zh":"學生必須只從文章選一個字。"},{"en":"Choose one word only means the answer must be exactly one word, not two or more.","zh":"“Choose one word only” 指答案必須正正是一個字，而不是兩個或以上。"},{"en":"If the correct answer is “graphite,” writing “black graphite” would break the rule.","zh":"如果正確答案是 “graphite”，寫 “black graphite” 就會違反規則。"},{"en":"Students should copy one word carefully because spelling mistakes may lose marks.","zh":"學生應仔細抄寫一個字，因為串字錯誤可能失分。"},{"en":"The phrase gives a strict answer limit.","zh":"這個短語給出嚴格答案限制。"}],"source":"47 - The History of Pencil.pdf","sourcePage":14},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers should come from the passage.","zh":"答案應來自文章。"},{"en":"From the passage means using information or exact words found in the reading text.","zh":"“From the passage” 指使用閱讀文本中的資料或準確詞語。"},{"en":"Students should not use outside knowledge when the answer must come from the passage.","zh":"當答案必須來自文章時，學生不應使用外部知識。"},{"en":"If the passage uses “graphite,” an answer like “carbon” may not be accepted even if related.","zh":"如果文章使用 “graphite”，即使 “carbon” 相關，也未必被接受。"},{"en":"The phrase reminds students to rely on the text.","zh":"這個短語提醒學生依賴文本。"}],"source":"47 - The History of Pencil.pdf","sourcePage":14},{"front":"write your answers in boxes","meaning":"把答案寫在方格內","examples":[{"en":"Students write their answers in boxes on the answer sheet.","zh":"學生把答案寫在答題紙上的方格內。"},{"en":"Write your answers in boxes means place each answer in the numbered spaces provided.","zh":"“Write your answers in boxes” 指把每個答案寫在提供的編號空格內。"},{"en":"In exams, students should write clearly in the answer boxes so markers can read their answers.","zh":"在考試中，學生應在答案方格內清楚書寫，讓評卷員能讀到答案。"},{"en":"If an answer is written outside the box, it may be missed or marked incorrectly.","zh":"如果答案寫在方格外，可能被漏看或錯誤評分。"},{"en":"The phrase gives a practical instruction about where to write.","zh":"這個短語給出關於寫在哪裡的實際指示。"}],"source":"47 - The History of Pencil.pdf","sourcePage":15},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生把答案寫在答題紙上。"},{"en":"An answer sheet is the paper or digital form where students record final answers.","zh":"答題紙是學生記錄最終答案的紙張或電子表格。"},{"en":"A student may solve questions in the booklet but copy final answers onto the answer sheet.","zh":"學生可能先在題目冊中解題，再把最終答案抄到答題紙上。"},{"en":"If the answer sheet is filled in carelessly, correct work may still lose marks.","zh":"如果答題紙填寫粗心，即使解答正確也可能失分。"},{"en":"The phrase refers to the official place for exam answers.","zh":"這個短語指考試答案的正式位置。"}],"source":"47 - The History of Pencil.pdf","sourcePage":15},{"front":"be found beneath","meaning":"在……下面被發現","examples":[{"en":"Graphite was found beneath a tree at Borrowdale.","zh":"石墨在 Borrowdale 的一棵樹下被發現。"},{"en":"To be found beneath something means to be discovered under it.","zh":"“Be found beneath” 某物指在它下面被發現。"},{"en":"Coins may be found beneath an old floor during renovation.","zh":"裝修期間，硬幣可能在舊地板下面被發現。"},{"en":"If a substance is found beneath a tree, the roots or soil may have hidden it before.","zh":"如果某種物質在樹下被發現，樹根或泥土以前可能把它隱藏起來。"},{"en":"The phrase gives a location below another object.","zh":"這個短語給出另一物件下方的位置。"}],"source":"47 - The History of Pencil.pdf","sourcePage":15},{"front":"messy to use","meaning":"使用時容易弄污","examples":[{"en":"Graphite was messy to use because it was soft.","zh":"石墨因為柔軟，所以使用時容易弄污。"},{"en":"Messy to use means likely to make hands, clothes or surfaces dirty during use.","zh":"“Messy to use” 指使用時容易弄髒雙手、衣服或表面。"},{"en":"Wet paint is messy to use if students do not cover the table first.","zh":"如果學生沒有先覆蓋桌面，濕顏料使用時容易弄污。"},{"en":"If graphite is messy to use, people need a casing or wrapper to hold it neatly.","zh":"如果石墨使用時容易弄污，人們就需要外殼或包裹物來整潔地握住它。"},{"en":"The phrase describes an inconvenient practical problem.","zh":"這個短語描述不方便的實際問題。"}],"source":"47 - The History of Pencil.pdf","sourcePage":15},{"front":"early users","meaning":"早期使用者","examples":[{"en":"Early users employed graphite to mark sheep.","zh":"早期使用者使用石墨標記羊隻。"},{"en":"Early users are the first people who used a new material, tool or invention.","zh":"早期使用者是最先使用新材料、工具或發明的人。"},{"en":"Early users of mobile phones often paid high prices and accepted limited functions.","zh":"手機早期使用者通常支付高價並接受有限功能。"},{"en":"If early users find a practical purpose, an invention may spread more quickly.","zh":"如果早期使用者找到實際用途，發明可能更快傳播。"},{"en":"The phrase refers to people at the beginning of a product’s use.","zh":"這個短語指產品使用初期的人。"}],"source":"47 - The History of Pencil.pdf","sourcePage":15},{"front":"employ something to","meaning":"使用……去","examples":[{"en":"Early users employed graphite to mark sheep.","zh":"早期使用者使用石墨去標記羊隻。"},{"en":"To employ something to do a task means to use it for that purpose.","zh":"“Employ something to” 做某事指使用某物來達到該目的。"},{"en":"A teacher may employ pictures to explain difficult vocabulary.","zh":"老師可能使用圖片去解釋困難詞彙。"},{"en":"If people employ a material to mark animals, the material must leave visible marks.","zh":"如果人們使用某材料去標記動物，該材料必須留下可見痕跡。"},{"en":"The phrase is a formal way to say “use something to.”","zh":"這個短語是 “use something to” 的正式說法。"}],"source":"47 - The History of Pencil.pdf","sourcePage":15},{"front":"consist of","meaning":"由……組成","examples":[{"en":"The first pencil consisted of graphite wrapped in string or animal skin.","zh":"第一支鉛筆由包在繩子或動物皮中的石墨組成。"},{"en":"To consist of something means to be made up of those parts or materials.","zh":"“Consist of” 某些部分指由那些部分或材料組成。"},{"en":"A simple lunch may consist of rice, vegetables and soup.","zh":"簡單午餐可能由米飯、蔬菜和湯組成。"},{"en":"If an early pencil consisted of graphite and wrapping, it was much simpler than a modern pencil.","zh":"如果早期鉛筆由石墨和包裹物組成，它就比現代鉛筆簡單得多。"},{"en":"The phrase explains the parts that form something.","zh":"這個短語解釋構成某物的部分。"}],"source":"47 - The History of Pencil.pdf","sourcePage":15},{"front":"animal skin","meaning":"動物皮","examples":[{"en":"The first pencil used graphite wrapped in string or animal skin.","zh":"第一支鉛筆使用包在繩子或動物皮中的石墨。"},{"en":"Animal skin means the hide or skin of an animal used as a material.","zh":"動物皮指作為材料使用的動物外皮。"},{"en":"Before modern plastics, people often used animal skin for bags, clothing or covers.","zh":"在現代塑膠出現前，人們常用動物皮製作袋、衣物或保護套。"},{"en":"If graphite is wrapped in animal skin, it becomes easier to hold without dirtying the hand.","zh":"如果石墨包在動物皮中，就更容易握住而不弄污手。"},{"en":"The phrase refers to a natural covering material.","zh":"這個短語指天然覆蓋材料。"}],"source":"47 - The History of Pencil.pdf","sourcePage":15},{"front":"be added to make something harder","meaning":"被加入以令……更硬","examples":[{"en":"Clay was added to make the pencil core harder.","zh":"黏土被加入以令鉛筆芯更硬。"},{"en":"To be added to make something harder means to be put into a mixture so the final material becomes less soft.","zh":"“Be added to make something harder” 指被放進混合物中，使最終材料較不柔軟。"},{"en":"Extra flour may be added to make dough firmer when it is too wet.","zh":"如果麵團太濕，可能加入額外麵粉以令它更結實。"},{"en":"If clay is added to graphite, the pencil core can become harder and lighter in mark.","zh":"如果黏土加入石墨中，鉛筆芯可以變得更硬，筆跡也較淺。"},{"en":"The phrase shows how one material changes another material’s quality.","zh":"這個短語顯示一種材料如何改變另一種材料的特性。"}],"source":"47 - The History of Pencil.pdf","sourcePage":15},{"front":"prefer something for","meaning":"較喜歡用……來","examples":[{"en":"Russian astronauts preferred grease pencils for writing in space.","zh":"俄羅斯太空人較喜歡用油性鉛筆在太空書寫。"},{"en":"To prefer something for a task means to choose it because it works better for that purpose.","zh":"“Prefer something for” 某任務指因它更適合該用途而選擇它。"},{"en":"Some students prefer pencils for maths because they can erase mistakes.","zh":"一些學生較喜歡用鉛筆做數學，因為可以擦掉錯誤。"},{"en":"If grease pencils do not break easily, astronauts may prefer them for space writing.","zh":"如果油性鉛筆不容易折斷，太空人可能較喜歡用它們在太空書寫。"},{"en":"The phrase connects preference with a specific use.","zh":"這個短語把偏好與特定用途連繫起來。"}],"source":"47 - The History of Pencil.pdf","sourcePage":15},{"front":"writing in space","meaning":"在太空書寫","examples":[{"en":"Astronauts needed reliable tools for writing in space.","zh":"太空人需要可靠工具在太空書寫。"},{"en":"Writing in space means recording words or numbers in a spacecraft where gravity is very weak.","zh":"在太空書寫指在重力很弱的太空船中記錄文字或數字。"},{"en":"Astronauts may need writing tools in space to record observations, instructions or calculations.","zh":"太空人可能需要在太空書寫，以記錄觀察、指示或計算。"},{"en":"If a writing tool breaks in space, floating pieces can create safety risks.","zh":"如果書寫工具在太空中斷裂，飄浮碎片可以造成安全風險。"},{"en":"The phrase describes a normal task made difficult by space conditions.","zh":"這個短語描述一項因太空環境而變困難的普通任務。"}],"source":"47 - The History of Pencil.pdf","sourcePage":15},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"Students decide whether the following statements agree with the information in the passage.","zh":"學生判斷以下陳述是否與文章資料一致。"},{"en":"Do the following statements agree with means decide whether each statement matches what the text says.","zh":"“Do the following statements agree with” 指判斷每項陳述是否與文本所說內容相符。"},{"en":"In reading tests, students should check exact wording before deciding whether statements agree with the passage.","zh":"在閱讀測驗中，學生應先檢查準確措辭，再判斷陳述是否與文章一致。"},{"en":"If a statement changes one important detail, it may no longer agree with the text.","zh":"如果陳述改變了一個重要細節，就可能不再與文本一致。"},{"en":"The phrase introduces a TRUE/FALSE/NOT GIVEN style task.","zh":"這個短語引出 TRUE/FALSE/NOT GIVEN 類題目。"}],"source":"47 - The History of Pencil.pdf","sourcePage":16},{"front":"agree with the information","meaning":"與資料一致","examples":[{"en":"The statement may agree with the information in the passage.","zh":"該陳述可能與文章資料一致。"},{"en":"To agree with the information means to match what the passage says.","zh":"“Agree with the information” 指與文章所說內容相符。"},{"en":"If the passage says graphite was found beneath a tree, the same statement agrees with the information.","zh":"如果文章說石墨在一棵樹下被發現，相同陳述就與資料一致。"},{"en":"Students should choose TRUE only when the whole statement matches the text.","zh":"只有當整項陳述與文本相符時，學生才應選 TRUE。"},{"en":"The phrase is used when checking accuracy against a reading passage.","zh":"這個短語用於對照閱讀文章檢查準確性。"}],"source":"47 - The History of Pencil.pdf","sourcePage":16},{"front":"information given in","meaning":"在……中提供的資料","examples":[{"en":"The answer depends on the information given in the reading passage.","zh":"答案取決於閱讀文章中提供的資料。"},{"en":"Information given in a text means the facts or details actually stated there.","zh":"在文本中提供的資料，是實際在那裡說明的事實或細節。"},{"en":"Students should base their answers on information given in the article, not on memory from other lessons.","zh":"學生應根據文章中提供的資料作答，而不是依靠其他課堂記憶。"},{"en":"If information is not given in the passage, the answer may be NOT GIVEN.","zh":"如果資料沒有在文章中提供，答案可能是 NOT GIVEN。"},{"en":"The phrase reminds learners to use only the source text.","zh":"這個短語提醒學習者只使用來源文本。"}],"source":"47 - The History of Pencil.pdf","sourcePage":16},{"front":"contradict the information","meaning":"與資料矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與文章資料矛盾。"},{"en":"To contradict the information means to say the opposite of what the passage says.","zh":"“Contradict the information” 指說出與文章內容相反的意思。"},{"en":"If the text says pencils contain no lead, a statement saying they contain lead contradicts it.","zh":"如果文本說鉛筆不含鉛，而陳述說它們含鉛，就是與資料矛盾。"},{"en":"A small opposite detail can make the whole statement false.","zh":"一個相反的小細節可以令整項陳述錯誤。"},{"en":"The phrase helps students identify FALSE answers.","zh":"這個短語幫助學生識別 FALSE 答案。"}],"source":"47 - The History of Pencil.pdf","sourcePage":16},{"front":"there is no information on this","meaning":"沒有關於這方面的資料","examples":[{"en":"Students write NOT GIVEN when there is no information on this.","zh":"當沒有關於這方面的資料時，學生寫 NOT GIVEN。"},{"en":"There is no information on this means the passage does not say whether the statement is true or false.","zh":"“There is no information on this” 指文章沒有說明該陳述是真還是假。"},{"en":"If the text explains pencil history but not the inventor’s favourite food, there is no information on that detail.","zh":"如果文本解釋鉛筆歷史，但沒有提到發明者最喜歡的食物，這方面就沒有資料。"},{"en":"Students should not guess from general knowledge when the passage gives no information.","zh":"當文章沒有資料時，學生不應根據常識猜測。"},{"en":"The phrase signals a NOT GIVEN answer.","zh":"這個短語表示 NOT GIVEN 答案。"}],"source":"47 - The History of Pencil.pdf","sourcePage":16},{"front":"the first country in the world to","meaning":"世界上第一個……的國家","examples":[{"en":"Italy was probably the first country in the world to make pencils.","zh":"意大利可能是世界上第一個製造鉛筆的國家。"},{"en":"The first country in the world to do something means the earliest country known to have done it.","zh":"“The first country in the world to” 做某事指已知最早做該事的國家。"},{"en":"A country may be the first in the world to introduce a new transport law.","zh":"一個國家可能是世界上第一個引入新交通法的國家。"},{"en":"If evidence says “probably,” the claim is likely but not completely certain.","zh":"如果證據使用 “probably”，該說法就是可能正確，但不完全確定。"},{"en":"The phrase identifies historical priority among countries.","zh":"這個短語指出國家之間的歷史先後位置。"}],"source":"47 - The History of Pencil.pdf","sourcePage":16},{"front":"several kinds of wood","meaning":"幾種木材","examples":[{"en":"The statement says that German craftspeople used several kinds of wood.","zh":"該陳述說德國工匠使用了幾種木材。"},{"en":"Several kinds of wood means more than one type of wood.","zh":"幾種木材指不止一種類型的木材。"},{"en":"A furniture maker may use several kinds of wood for tables, shelves and doors.","zh":"家具製造商可能使用幾種木材製作桌子、書架和門。"},{"en":"If a passage mentions only one type of wood, a statement about several kinds may not be supported.","zh":"如果文章只提到一種木材，關於幾種木材的陳述可能沒有支持。"},{"en":"The phrase focuses on variety of material.","zh":"這個短語強調材料種類。"}],"source":"47 - The History of Pencil.pdf","sourcePage":16},{"front":"make something harder and sharper","meaning":"令……更硬更尖","examples":[{"en":"The question asks whether graphite makes a pencil harder and sharper.","zh":"題目問石墨是否令鉛筆更硬更尖。"},{"en":"To make something harder and sharper means to increase its hardness and create a finer point.","zh":"“Make something harder and sharper” 指增加其硬度並形成更尖細的尖端。"},{"en":"Freezing soft clay can make it harder, but it will not necessarily make it sharper.","zh":"冷凍柔軟黏土可以令它更硬，但不一定令它更尖。"},{"en":"If clay, not graphite, makes a pencil core harder, students must read the passage carefully.","zh":"如果令鉛筆芯更硬的是黏土而不是石墨，學生就必須仔細閱讀文章。"},{"en":"The phrase links material change with physical qualities.","zh":"這個短語把材料改變與物理特性連繫起來。"}],"source":"47 - The History of Pencil.pdf","sourcePage":16},{"front":"no longer produced","meaning":"不再生產","examples":[{"en":"The statement says that pencils are no longer produced in Britain.","zh":"該陳述說鉛筆在英國不再生產。"},{"en":"No longer produced means not made anymore in a particular place or by a particular company.","zh":"“No longer produced” 指在某地方或由某公司不再製造。"},{"en":"A toy may be no longer produced if children stop buying it.","zh":"如果孩子停止購買某玩具，它可能不再生產。"},{"en":"If a product is no longer produced, old examples may become rare or valuable.","zh":"如果產品不再生產，舊款可能變得稀有或有價值。"},{"en":"The phrase describes the end of manufacturing.","zh":"這個短語描述製造的結束。"}],"source":"47 - The History of Pencil.pdf","sourcePage":16},{"front":"be unlikely to be used","meaning":"不大可能被使用","examples":[{"en":"The statement says that pencils are unlikely to be used in the future.","zh":"該陳述說鉛筆未來不大可能被使用。"},{"en":"To be unlikely to be used means probably not going to be used later.","zh":"“Be unlikely to be used” 指日後很可能不會被使用。"},{"en":"A broken printer is unlikely to be used if repairs cost more than a new one.","zh":"如果維修費比買新打印機更貴，壞打印機就不大可能被使用。"},{"en":"If a tool is still cheap, simple and useful, it is not necessarily unlikely to be used in the future.","zh":"如果工具仍然便宜、簡單而有用，它未必不大可能在未來被使用。"},{"en":"The phrase expresses low probability of future use.","zh":"這個短語表達未來使用機會低。"}],"source":"47 - The History of Pencil.pdf","sourcePage":16}],"ielts/reading/passage-2/Practice 48":[{"front":"concentrate on","meaning":"專注於……","examples":[{"en":"Many people find it difficult to concentrate on one task when several devices are nearby.","zh":"當附近有幾部電子裝置時，許多人覺得很難專注於一項任務。"},{"en":"To concentrate on something means to give it your full attention.","zh":"concentrate on something 指把全部注意力放在某事上。"},{"en":"A student may concentrate on reading better if the phone is kept in another room.","zh":"如果手機放在另一個房間，學生可能更能專注於閱讀。"},{"en":"If people cannot concentrate on a task, they may make more mistakes and take longer to finish.","zh":"如果人們不能專注於任務，可能會犯更多錯並花更長時間完成。"},{"en":"This phrase is useful when talking about focus, study, work, or attention.","zh":"這個片語常用於談論集中精神、學習、工作或注意力。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":1},{"front":"read while listening to music","meaning":"一邊聽音樂一邊閱讀","examples":[{"en":"Some students read while listening to music.","zh":"有些學生一邊聽音樂一邊閱讀。"},{"en":"To read while listening to music means to do reading and music listening at the same time.","zh":"read while listening to music 指同時進行閱讀和聽音樂。"},{"en":"A student may read while listening to soft music because it makes the room feel calmer.","zh":"學生可能一邊聽輕柔音樂一邊閱讀，因為這令房間感覺較平靜。"},{"en":"If the music has lyrics, reading while listening to music may make it harder to understand the text.","zh":"如果音樂有歌詞，一邊聽音樂一邊閱讀可能令理解文本更困難。"},{"en":"This phrase describes a common example of multitasking.","zh":"這個片語描述一心多用的常見例子。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":1},{"front":"watch television while doing homework","meaning":"一邊做功課一邊看電視","examples":[{"en":"Some students watch television while doing homework.","zh":"有些學生一邊做功課一邊看電視。"},{"en":"To watch television while doing homework means to try to follow a programme and finish schoolwork at the same time.","zh":"watch television while doing homework 指嘗試同時看節目和完成功課。"},{"en":"A child may watch television while doing homework if the family TV is on in the living room.","zh":"如果客廳電視開着，孩子可能一邊做功課一邊看電視。"},{"en":"If a programme is interesting, it may pull attention away from the homework.","zh":"如果節目很吸引，它可能把注意力從功課上拉走。"},{"en":"This phrase shows how entertainment can interfere with study.","zh":"這個片語顯示娛樂如何干擾學習。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":1},{"front":"multitaskers","meaning":"一心多用的人","examples":[{"en":"People with these habits are called multitaskers.","zh":"有這些習慣的人被稱為一心多用的人。"},{"en":"Multitaskers are people who try to do several tasks at the same time.","zh":"multitaskers 是嘗試同時做幾項任務的人。"},{"en":"A multitasker may answer messages, watch videos, and eat lunch while working.","zh":"一心多用的人可能一邊工作，一邊回訊息、看影片和吃午餐。"},{"en":"If multitaskers keep switching attention, their work may become slower or less accurate.","zh":"如果一心多用的人不斷切換注意力，他們的工作可能變慢或較不準確。"},{"en":"This word describes a habit of dividing attention between activities.","zh":"這個詞描述在多項活動之間分散注意力的習慣。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":1},{"front":"appear to","meaning":"似乎；看來","examples":[{"en":"Multitaskers appear to complete two tasks at once.","zh":"一心多用的人似乎能同時完成兩項任務。"},{"en":"Appear to means seem to do something, even if the reality may be different.","zh":"appear to 指看起來似乎做某事，即使實際情況可能不同。"},{"en":"A quiet student may appear to understand the lesson, but they may still need help.","zh":"安靜的學生可能看似明白課堂，但仍可能需要幫助。"},{"en":"If someone appears to work quickly while checking messages, they may actually be switching between tasks.","zh":"如果某人一邊查看訊息一邊看似快速工作，他可能其實在任務之間切換。"},{"en":"This phrase is useful when something looks true but is not certain.","zh":"這個片語適用於某事看起來是真的，但未必確定的情況。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":1},{"front":"complete two tasks at once","meaning":"同時完成兩項任務","examples":[{"en":"Multitaskers appear to complete two tasks at once.","zh":"一心多用的人似乎能同時完成兩項任務。"},{"en":"To complete two tasks at once means to finish two activities at the same time.","zh":"complete two tasks at once 指在同一時間完成兩項活動。"},{"en":"A worker may try to complete two tasks at once by joining a meeting while writing emails.","zh":"員工可能一邊開會一邊寫電郵，嘗試同時完成兩項任務。"},{"en":"If both tasks need attention, trying to complete them together may reduce quality.","zh":"如果兩項任務都需要注意力，嘗試一起完成可能降低質素。"},{"en":"This phrase often describes the appearance of multitasking rather than true simultaneous focus.","zh":"這個片語常描述一心多用的表面情況，而不一定是真正同時專注。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":1},{"front":"divide their attention","meaning":"分散注意力","examples":[{"en":"People divide their attention when they try to do several things at the same time.","zh":"當人們嘗試同時做幾件事時，他們會分散注意力。"},{"en":"To divide attention means to split focus between two or more things.","zh":"divide attention 指把專注力分到兩件或更多事情上。"},{"en":"A driver divides attention dangerously if they look at a phone while watching the road.","zh":"如果司機一邊看路一邊看手機，就是危險地分散注意力。"},{"en":"When attention is divided, people may miss important details.","zh":"當注意力被分散，人們可能錯過重要細節。"},{"en":"This phrase explains why multitasking can reduce accuracy.","zh":"這個片語解釋為何一心多用可能降低準確度。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":1},{"front":"a psychology researcher","meaning":"心理學研究員","examples":[{"en":"Thomas Lehman is a psychology researcher.","zh":"Thomas Lehman 是一名心理學研究員。"},{"en":"A psychology researcher is someone who studies human thoughts, feelings, behaviour, or mental processes.","zh":"psychology researcher 是研究人類思想、情感、行為或心理過程的人。"},{"en":"A psychology researcher may study why students lose focus during online lessons.","zh":"心理學研究員可能研究學生為何在網課中失去專注。"},{"en":"If researchers understand attention, they can explain why multitasking feels easier than it really is.","zh":"如果研究人員理解注意力，就能解釋為何一心多用感覺比實際容易。"},{"en":"This phrase names a person who investigates how the mind works.","zh":"這個片語指研究心智如何運作的人。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":1},{"front":"argue that","meaning":"認為；主張","examples":[{"en":"Thomas Lehman argues that people never truly do several things simultaneously.","zh":"Thomas Lehman 主張人們從來不是真正同時做幾件事。"},{"en":"To argue that means to state a view and support it with reasons or evidence.","zh":"argue that 指提出一個看法，並用理由或證據支持它。"},{"en":"A teacher may argue that reading examples helps students remember vocabulary better.","zh":"老師可能認為閱讀例句能幫助學生更好記住詞彙。"},{"en":"If researchers argue that multitasking is really task-switching, they need experiments to support the claim.","zh":"如果研究人員主張一心多用其實是任務切換，他們需要實驗支持這說法。"},{"en":"This phrase introduces an opinion or conclusion in discussion.","zh":"這個片語引入討論中的意見或結論。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":1},{"front":"never truly","meaning":"從來不是真正地","examples":[{"en":"People never truly do several things simultaneously.","zh":"人們從來不是真正同時做幾件事。"},{"en":"Never truly means not really or not in the full sense, even if it seems that way.","zh":"never truly 指並非真正地或並非完整意義上如此，即使看起來像。"},{"en":"A student who copies model answers never truly learns how to write independently.","zh":"只抄範文的學生從來不是真正學會獨立寫作。"},{"en":"If the brain switches rapidly between tasks, it may never truly focus on both at the same time.","zh":"如果大腦在任務之間快速切換，它可能從來不是真正同時專注於兩者。"},{"en":"This phrase challenges an appearance by pointing to the deeper reality.","zh":"這個片語透過指出深層現實來挑戰表面現象。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":1},{"front":"do several things simultaneously","meaning":"同時做幾件事","examples":[{"en":"People never truly do several things simultaneously.","zh":"人們從來不是真正同時做幾件事。"},{"en":"To do several things simultaneously means to perform several activities at exactly the same time.","zh":"do several things simultaneously 指在完全同一時間進行幾項活動。"},{"en":"A receptionist may seem to do several things simultaneously when answering calls and greeting visitors.","zh":"接待員接電話又接待訪客時，可能看似同時做幾件事。"},{"en":"If each task needs thinking, doing them simultaneously may actually mean switching rapidly between them.","zh":"如果每項任務都需要思考，同時做它們可能其實是快速切換。"},{"en":"This phrase describes the central idea behind multitasking.","zh":"這個片語描述一心多用背後的核心概念。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":1},{"front":"focus on only one task at a time","meaning":"一次只專注於一項任務","examples":[{"en":"The brain can focus on only one task at a time.","zh":"大腦一次只專注於一項任務。"},{"en":"To focus on only one task at a time means to give full attention to one activity before moving to another.","zh":"focus on only one task at a time 指先把全部注意力放在一項活動上，再轉到另一項。"},{"en":"A student may write more clearly if they focus on only one paragraph at a time.","zh":"如果學生一次只專注於一段，他可能寫得更清楚。"},{"en":"If people try to focus on several demanding tasks, attention may jump between them.","zh":"如果人們嘗試同時專注於幾項高要求任務，注意力可能在它們之間跳動。"},{"en":"This phrase describes single-task attention.","zh":"這個片語描述單一任務專注。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":2},{"front":"cause someone to ignore","meaning":"導致某人忽略……","examples":[{"en":"Reading a book can cause the listener to ignore some of the song’s words.","zh":"閱讀一本書可能導致聽者忽略歌曲中的一些歌詞。"},{"en":"To cause someone to ignore something means to make them fail to notice or pay attention to it.","zh":"cause someone to ignore something 指令某人沒有注意或留意某事。"},{"en":"A loud game can cause a child to ignore a parent calling from another room.","zh":"嘈吵的遊戲可能導致孩子忽略父母從另一房間呼叫。"},{"en":"If one task takes too much attention, it can cause people to miss information from another task.","zh":"如果一項任務佔用太多注意力，它可以令人錯過另一項任務中的資訊。"},{"en":"This phrase shows how one activity blocks attention to another.","zh":"這個片語顯示一項活動如何阻礙人注意另一項活動。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":2},{"front":"less aware of their surroundings","meaning":"對身邊環境較不察覺","examples":[{"en":"Listening to music makes people less aware of their surroundings.","zh":"聽音樂會令人對身邊環境較不察覺。"},{"en":"Less aware of their surroundings means noticing less of what is happening nearby.","zh":"less aware of their surroundings 指較少注意附近正在發生的事情。"},{"en":"A person wearing headphones may be less aware of cars, cyclists, or people calling them.","zh":"戴耳機的人可能較不察覺汽車、單車或有人叫他。"},{"en":"If people are less aware of their surroundings, accidents or misunderstandings can happen more easily.","zh":"如果人們對身邊環境較不察覺，意外或誤會可能更容易發生。"},{"en":"This phrase is often used when attention is pulled away from the environment.","zh":"當注意力被環境以外的東西拉走時，常使用這個片語。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":2},{"front":"respond properly","meaning":"適當回應","examples":[{"en":"Some friends do not respond properly when they are distracted.","zh":"有些朋友分心時不會適當回應。"},{"en":"To respond properly means to answer or react in a suitable and attentive way.","zh":"respond properly 指以合適並專注的方式回答或作出反應。"},{"en":"A student may not respond properly to a teacher’s question if they are checking their phone.","zh":"如果學生正在看手機，可能不會適當回應老師的問題。"},{"en":"If people do not respond properly, others may feel ignored or disrespected.","zh":"如果人們沒有適當回應，別人可能覺得被忽視或不受尊重。"},{"en":"This phrase describes an appropriate reaction to a situation or person.","zh":"這個片語描述對某情況或某人的合適反應。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":2},{"front":"read a text on a smartphone","meaning":"在智能手機上讀短訊","examples":[{"en":"A person may fail to hear us because they are reading a text on a smartphone.","zh":"一個人可能因為正在智能手機上讀短訊而聽不到我們說話。"},{"en":"To read a text on a smartphone means to look at a written message on a mobile phone.","zh":"read a text on a smartphone 指在手機上查看文字訊息。"},{"en":"A passenger may read a text on a smartphone while waiting for a bus.","zh":"乘客等巴士時可能在智能手機上讀短訊。"},{"en":"If someone reads a message during a conversation, they may miss what the speaker says.","zh":"如果某人在談話期間看訊息，可能錯過說話者所說的內容。"},{"en":"This phrase describes a common phone-related distraction.","zh":"這個片語描述常見的手機相關分心情況。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":2},{"front":"call this phenomenon","meaning":"將這種現象稱為……","examples":[{"en":"Lehman calls this phenomenon email voice.","zh":"Lehman 將這種現象稱為 email voice。"},{"en":"To call this phenomenon something means to give a name to a behaviour or situation.","zh":"call this phenomenon something 指為某種行為或情況命名。"},{"en":"A teacher may call this phenomenon exam panic when students forget easy answers under pressure.","zh":"當學生在壓力下忘記簡單答案時，老師可能將這種現象稱為考試恐慌。"},{"en":"Naming a phenomenon helps people notice and discuss it more clearly.","zh":"為現象命名有助人們更清楚注意和討論它。"},{"en":"This phrase is useful when introducing a term for an observed pattern.","zh":"這個片語適合用於引入某個觀察到的模式的術語。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":2},{"front":"email voice","meaning":"「電郵聲」現象","examples":[{"en":"Email voice describes the way people fail to notice their surroundings while reading messages.","zh":"email voice 描述人們閱讀訊息時沒有注意身邊環境的情況。"},{"en":"Email voice is a term for the distracted tone people use when half-listening while reading email or messages.","zh":"email voice 是指人們一邊讀電郵或訊息、一邊半聽別人說話時使用的分心語氣。"},{"en":"A friend may answer “yeah” in an email voice while still staring at their phone.","zh":"朋友可能一邊盯着手機，一邊用「電郵聲」回答「嗯」。"},{"en":"If someone uses email voice, they may sound present but not truly be listening.","zh":"如果某人使用「電郵聲」，他聽起來在場，但其實沒有真正聆聽。"},{"en":"This phrase shows how digital distraction can affect conversation.","zh":"這個片語顯示數碼分心如何影響對話。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":2},{"front":"spin-offs","meaning":"衍生科技；衍生產品","examples":[{"en":"Computers and their spin-offs, such as smartphones, have changed everyday communication.","zh":"電腦及其衍生科技，例如智能手機，已改變日常溝通。"},{"en":"Spin-offs are new products, ideas, or technologies that develop from an earlier one.","zh":"spin-offs 是由較早事物發展出來的新產品、想法或科技。"},{"en":"A popular school project may lead to spin-offs such as clubs, workshops, and competitions.","zh":"受歡迎的學校項目可能帶來社團、工作坊和比賽等衍生活動。"},{"en":"If one invention creates many spin-offs, its influence spreads into daily life.","zh":"如果一項發明創造許多衍生產品，其影響會擴散到日常生活。"},{"en":"This word describes things that grow out of an original source.","zh":"這個詞描述由原始來源發展出來的事物。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":2},{"front":"personal device","meaning":"個人裝置","examples":[{"en":"Most people now own a personal device such as a smartphone or laptop.","zh":"現在大多數人都擁有智能手機或手提電腦等個人裝置。"},{"en":"A personal device is an electronic tool used mainly by one person for communication, work, or entertainment.","zh":"personal device 是主要由一個人用於溝通、工作或娛樂的電子工具。"},{"en":"A student may use a personal device to check homework, read notes, and message classmates.","zh":"學生可能使用個人裝置查看功課、閱讀筆記和傳訊息給同學。"},{"en":"If personal devices are always nearby, they can make distraction easier.","zh":"如果個人裝置總是在身邊，它們會令分心更容易發生。"},{"en":"This phrase usually refers to phones, tablets, laptops, or similar digital tools.","zh":"這個片語通常指手機、平板電腦、手提電腦或類似數碼工具。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":2},{"front":"digital information","meaning":"數碼資料","examples":[{"en":"People frequently read, watch or listen to digital information.","zh":"人們經常閱讀、觀看或聆聽數碼資料。"},{"en":"Digital information is information stored, shown, or shared through electronic devices.","zh":"digital information 是透過電子裝置儲存、展示或分享的資料。"},{"en":"Online articles, videos, podcasts, emails, and messages are forms of digital information.","zh":"網上文章、影片、播客、電郵和訊息都是數碼資料形式。"},{"en":"Because digital information arrives constantly, people may feel pressure to check devices often.","zh":"因為數碼資料不斷出現，人們可能感到需要經常查看裝置。"},{"en":"This phrase refers to information in electronic rather than paper form.","zh":"這個片語指電子形式而非紙本形式的資料。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":2},{"front":"increase the prevalence of","meaning":"提高……的普遍程度","examples":[{"en":"Personal devices increase the prevalence of multitasking in everyday life.","zh":"個人裝置提高了一心多用在日常生活中的普遍程度。"},{"en":"To increase the prevalence of something means to make it more common.","zh":"increase the prevalence of something 指令某事變得更常見。"},{"en":"Online shopping has increased the prevalence of home delivery in many cities.","zh":"網上購物提高了許多城市家居送貨的普遍程度。"},{"en":"If phones are always nearby, they increase the chance that people will switch between tasks.","zh":"如果手機總是在附近，它們會增加人們在任務之間切換的機會。"},{"en":"This phrase is useful when describing how a habit spreads.","zh":"這個片語適合描述某種習慣如何擴散。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":2},{"front":"the prevalence of multitasking","meaning":"一心多用的普遍程度","examples":[{"en":"The prevalence of multitasking has increased in everyday life.","zh":"一心多用在日常生活中的普遍程度已經增加。"},{"en":"The prevalence of multitasking means how common multitasking is among people.","zh":"prevalence of multitasking 指一心多用在人群中有多常見。"},{"en":"Teachers may notice the prevalence of multitasking when students check phones during study time.","zh":"當學生在溫習時間查看手機時，老師可能注意到一心多用的普遍程度。"},{"en":"If many jobs require emails, calls, and meetings, multitasking becomes more common at work.","zh":"如果許多工作需要處理電郵、電話和會議，一心多用在職場中會變得更常見。"},{"en":"This phrase focuses on how widespread the behaviour is.","zh":"這個片語聚焦於該行為有多普遍。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":3},{"front":"in everyday life","meaning":"在日常生活中","examples":[{"en":"Multitasking is now common in everyday life.","zh":"一心多用現在在日常生活中很常見。"},{"en":"In everyday life means in ordinary daily situations rather than special events.","zh":"in everyday life 指在普通日常情況中，而不是特殊事件中。"},{"en":"In everyday life, people often check messages while eating, walking, or waiting.","zh":"在日常生活中，人們常在吃飯、走路或等候時查看訊息。"},{"en":"If a habit appears in everyday life, it can shape attention without people noticing.","zh":"如果一個習慣出現在日常生活中，它可以在人們不察覺下塑造注意力。"},{"en":"This phrase connects an idea to normal routines.","zh":"這個片語把想法與日常習慣連接起來。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":3},{"front":"stop by","meaning":"順道過來；到訪","examples":[{"en":"Colleagues may stop by to speak to someone at work.","zh":"同事可能順道過來與某人在工作時交談。"},{"en":"To stop by means to visit briefly, often without a long appointment.","zh":"stop by 指短暫到訪，通常沒有長時間預約。"},{"en":"A friend may stop by your desk to ask a quick question before lunch.","zh":"朋友可能在午飯前順道到你的桌前問一個簡短問題。"},{"en":"If people stop by often, they can interrupt work even when they are being friendly.","zh":"如果人們經常順道過來，即使出於友善，也可能打斷工作。"},{"en":"This phrase suggests a short, casual visit.","zh":"這個片語暗示短暫而隨意的到訪。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":3},{"front":"stop by at any time","meaning":"隨時順道過來","examples":[{"en":"At work, colleagues may stop by at any time to speak to someone.","zh":"在工作中，同事可能隨時順道過來與某人說話。"},{"en":"To stop by at any time means to visit whenever one wants, without a fixed schedule.","zh":"stop by at any time 指沒有固定時間、想來便來地短暫到訪。"},{"en":"In an open office, coworkers may stop by at any time with small questions.","zh":"在開放式辦公室中，同事可能隨時順道過來問小問題。"},{"en":"If people can stop by at any time, workers may find it hard to protect deep-focus time.","zh":"如果人們可以隨時順道過來，員工可能難以保護深度專注時間。"},{"en":"This phrase describes unpredictable casual interruptions.","zh":"這個片語描述不可預測的隨意打擾。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":3},{"front":"professional meetings","meaning":"專業會議；工作會議","examples":[{"en":"People often use mobile phones during professional meetings.","zh":"人們常在工作會議期間使用手機。"},{"en":"Professional meetings are work-related meetings held for business, planning, discussion, or decision-making.","zh":"professional meetings 是與工作、業務、計劃、討論或決策有關的會議。"},{"en":"A professional meeting may involve managers, clients, teachers, or medical staff.","zh":"工作會議可能涉及經理、客戶、教師或醫護人員。"},{"en":"If phones are used during professional meetings, participants may miss important decisions.","zh":"如果在工作會議期間使用手機，參加者可能錯過重要決定。"},{"en":"This phrase refers to formal workplace discussions.","zh":"這個片語指正式職場討論。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":3},{"front":"participants","meaning":"參加者","examples":[{"en":"Participants in meetings should normally listen to one another.","zh":"會議參加者通常應該聆聽彼此。"},{"en":"Participants are people who take part in an activity, event, meeting, or study.","zh":"participants 是參與活動、事件、會議或研究的人。"},{"en":"Participants in a workshop may ask questions and practise new skills.","zh":"工作坊參加者可能提問並練習新技能。"},{"en":"If participants are distracted, the meeting becomes less useful for everyone.","zh":"如果參加者分心，會議對所有人都會較不有用。"},{"en":"This word focuses on people involved in an activity.","zh":"這個詞聚焦於參與活動的人。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":3},{"front":"focus on and listen to one another","meaning":"專注並聆聽彼此","examples":[{"en":"Participants normally focus on and listen to one another during meetings.","zh":"參加者在會議中通常會專注並聆聽彼此。"},{"en":"To focus on and listen to one another means to pay attention to what each person is saying.","zh":"focus on and listen to one another 指留心每個人正在說的內容。"},{"en":"In a group discussion, students should focus on and listen to one another before replying.","zh":"在小組討論中，學生回應前應專注並聆聽彼此。"},{"en":"If people do not listen to one another, meetings can become confusing and repetitive.","zh":"如果人們不聆聽彼此，會議可能變得混亂和重複。"},{"en":"This phrase describes respectful attention in communication.","zh":"這個片語描述溝通中的尊重式注意。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":3},{"front":"increasingly likely to","meaning":"越來越可能","examples":[{"en":"People are increasingly likely to use phones during meetings.","zh":"人們越來越可能在會議期間使用手機。"},{"en":"Increasingly likely to means becoming more and more likely to do something.","zh":"increasingly likely to 指做某事的可能性越來越高。"},{"en":"Students are increasingly likely to use online dictionaries when writing essays.","zh":"學生寫文章時越來越可能使用網上字典。"},{"en":"If devices become smaller and more convenient, people are more likely to use them in many situations.","zh":"如果裝置變得更小和更方便，人們更可能在許多情況下使用它們。"},{"en":"This phrase describes a growing tendency.","zh":"這個片語描述日益增長的傾向。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":3},{"front":"keep a mobile phone in their lap","meaning":"把手機放在大腿上","examples":[{"en":"Some participants keep a mobile phone in their lap during meetings.","zh":"一些參加者在會議期間把手機放在大腿上。"},{"en":"To keep a mobile phone in their lap means to place the phone on the upper legs while sitting.","zh":"keep a mobile phone in their lap 指坐着時把手機放在大腿上。"},{"en":"A student may keep a phone in their lap during class to check messages secretly.","zh":"學生可能在課堂中把手機放在大腿上，偷偷查看訊息。"},{"en":"If a phone is hidden in someone’s lap, they may look attentive while actually reading messages.","zh":"如果手機藏在某人大腿上，他可能看似專心，其實正在讀訊息。"},{"en":"This phrase describes a discreet way of using a phone.","zh":"這個片語描述低調使用手機的方式。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":3},{"front":"communicate silently with","meaning":"與……靜靜地溝通","examples":[{"en":"Participants may communicate silently with others during a meeting.","zh":"參加者可能在會議期間與其他人靜靜地溝通。"},{"en":"To communicate silently with someone means to exchange messages without speaking aloud.","zh":"communicate silently with someone 指不出聲地交換訊息。"},{"en":"Students may communicate silently with classmates by texting under the desk.","zh":"學生可能在桌下傳訊息，與同學靜靜地溝通。"},{"en":"If people communicate silently during a meeting, they may stop following the main discussion.","zh":"如果人們在會議中靜靜地溝通，他們可能停止跟上主要討論。"},{"en":"This phrase often refers to messaging while pretending to listen.","zh":"這個片語常指一邊假裝聆聽一邊傳訊息。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":3},{"front":"inventions such as","meaning":"……等發明","examples":[{"en":"Inventions such as the cordless phone have increased multitasking.","zh":"無線電話等發明增加了一心多用。"},{"en":"Inventions such as means examples of new tools or devices like the one mentioned.","zh":"inventions such as 指像所提及例子那樣的新工具或裝置。"},{"en":"Inventions such as washing machines have reduced the time needed for housework.","zh":"洗衣機等發明減少了做家務所需的時間。"},{"en":"If inventions make communication portable, people can talk while doing other tasks.","zh":"如果發明令溝通變得可攜，人們可以一邊說話一邊做其他任務。"},{"en":"This phrase introduces examples from a wider group.","zh":"這個片語引入較大類別中的例子。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":3},{"front":"cordless phone","meaning":"無線電話","examples":[{"en":"The cordless phone allows people to talk while doing other tasks.","zh":"無線電話讓人們一邊說話一邊做其他任務。"},{"en":"A cordless phone is a landline phone that can be carried around nearby without a cord connecting the handset to the base.","zh":"cordless phone 是可在附近攜帶、不需要話筒用電線連接底座的固定電話。"},{"en":"A parent may use a cordless phone while cooking in the kitchen.","zh":"家長可能一邊在廚房煮飯，一邊使用無線電話。"},{"en":"Because cordless phones allow movement, they made it easier to talk and do chores at the same time.","zh":"因為無線電話容許移動，它令一邊說話一邊做家務變得更容易。"},{"en":"This phrase refers to an older portable phone technology.","zh":"這個片語指較舊的可攜電話科技。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":4},{"front":"wall-mounted telephone","meaning":"掛牆式電話","examples":[{"en":"When a wall-mounted telephone rang, the person had to stop their work.","zh":"當掛牆式電話響起時，那人必須停下工作。"},{"en":"A wall-mounted telephone is a phone fixed to a wall, usually in one place in a home or office.","zh":"wall-mounted telephone 是固定在牆上的電話，通常位於家中或辦公室某一處。"},{"en":"In older kitchens, a wall-mounted telephone was often placed near the doorway.","zh":"在舊式廚房中，掛牆式電話常放在門口附近。"},{"en":"If the phone is fixed to the wall, people must go to it instead of carrying it around.","zh":"如果電話固定在牆上，人們必須走到電話旁，而不能拿着它四處走。"},{"en":"This phrase contrasts old fixed phones with portable devices.","zh":"這個片語把舊式固定電話與可攜裝置作對比。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":4},{"front":"stop what someone is doing","meaning":"停下某人正在做的事","examples":[{"en":"A person had to stop what they were doing to answer the phone.","zh":"一個人必須停下正在做的事去接電話。"},{"en":"To stop what someone is doing means to pause or interrupt their current activity.","zh":"stop what someone is doing 指暫停或中斷某人目前的活動。"},{"en":"A teacher may stop what she is doing when a student gets injured.","zh":"當學生受傷時，老師可能停下正在做的事。"},{"en":"If people must stop their work to answer a call, the call becomes a clear interruption.","zh":"如果人們必須停下工作去接電話，電話就成為明顯干擾。"},{"en":"This phrase describes breaking away from the current task.","zh":"這個片語描述離開當前任務。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":4},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"Modern technology, by contrast, allows us to continue daily tasks while communicating.","zh":"相比之下，現代科技讓我們在溝通的同時繼續日常工作。"},{"en":"By contrast introduces a difference from the previous point.","zh":"by contrast 引入與前一點不同的情況。"},{"en":"Older phones kept people in one place; by contrast, mobile phones let people move around.","zh":"舊式電話把人固定在一個地方；相比之下，手機讓人四處走動。"},{"en":"If one method interrupts work and another allows multitasking, the contrast is important.","zh":"如果一種方法中斷工作，而另一種容許一心多用，這種對比很重要。"},{"en":"This phrase helps compare two different situations clearly.","zh":"這個片語幫助清楚比較兩種不同情況。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":4},{"front":"continue daily tasks","meaning":"繼續日常工作","examples":[{"en":"Modern technology allows us to continue our daily tasks while communicating.","zh":"現代科技讓我們在溝通時繼續日常工作。"},{"en":"To continue daily tasks means to keep doing ordinary everyday activities.","zh":"continue daily tasks 指繼續進行普通日常活動。"},{"en":"A parent may continue daily tasks like cooking or cleaning while talking on a headset.","zh":"家長可能一邊用耳機通話，一邊繼續煮飯或清潔等日常工作。"},{"en":"If technology allows tasks to continue during communication, multitasking becomes easier.","zh":"如果科技讓人們在溝通期間繼續任務，一心多用就變得更容易。"},{"en":"This phrase describes keeping normal activities going.","zh":"這個片語描述保持日常活動繼續進行。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":4},{"front":"while communicating","meaning":"在溝通的同時","examples":[{"en":"People can continue daily tasks while communicating.","zh":"人們可以在溝通的同時繼續日常工作。"},{"en":"While communicating means during the time when people are speaking, messaging, or exchanging information.","zh":"while communicating 指在人們說話、傳訊息或交換資訊的期間。"},{"en":"A worker may walk to the station while communicating with a colleague by phone.","zh":"員工可能一邊走到車站，一邊用電話與同事溝通。"},{"en":"If people do other tasks while communicating, they may miss part of the message.","zh":"如果人們在溝通的同時做其他任務，可能錯過部分訊息。"},{"en":"This phrase connects communication with another simultaneous activity.","zh":"這個片語把溝通與另一項同時進行的活動連接起來。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":4},{"front":"an expert at","meaning":"……的專家","examples":[{"en":"Earl Miller is an expert at the Massachusetts Institute of Technology.","zh":"Earl Miller 是麻省理工學院的專家。"},{"en":"An expert at an institution is a person with deep knowledge who works or teaches there.","zh":"expert at an institution 指在某機構工作或教學，並擁有深厚知識的人。"},{"en":"A hospital may have an expert at heart surgery who trains younger doctors.","zh":"醫院可能有一位心臟手術專家，負責培訓年輕醫生。"},{"en":"If an expert studies attention, their research can help explain common work habits.","zh":"如果專家研究注意力，其研究可以幫助解釋常見工作習慣。"},{"en":"This phrase identifies someone as a specialist connected with a place or field.","zh":"這個片語指出某人是與某地方或領域相關的專家。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":4},{"front":"prefrontal cortex","meaning":"前額葉皮層","examples":[{"en":"The prefrontal cortex helps control attention while a person multitasks.","zh":"前額葉皮層幫助人在一心多用時控制注意力。"},{"en":"The prefrontal cortex is the front part of the brain involved in planning, attention, decision-making, and self-control.","zh":"prefrontal cortex 是大腦前部，涉及計劃、注意力、決策和自我控制。"},{"en":"When a student chooses to ignore a phone and finish homework, the prefrontal cortex is involved.","zh":"當學生選擇忽略手機並完成功課時，前額葉皮層會參與其中。"},{"en":"If this brain area manages attention, it helps explain why multitasking has limits.","zh":"如果這個腦區管理注意力，它就幫助解釋為何一心多用有其限制。"},{"en":"This phrase refers to a brain region important for control and focus.","zh":"這個片語指對控制和專注很重要的腦部區域。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":4},{"front":"control attention","meaning":"控制注意力","examples":[{"en":"The prefrontal cortex helps control attention while a person multitasks.","zh":"前額葉皮層幫助人在一心多用時控制注意力。"},{"en":"To control attention means to direct focus toward one thing and away from others.","zh":"control attention 指把專注力引向一件事，並從其他事物移開。"},{"en":"A teacher controls students’ attention by asking a clear question before showing a diagram.","zh":"老師在展示圖表前提出清楚問題，以控制學生注意力。"},{"en":"If people cannot control attention, messages, noises, and thoughts may pull them away from work.","zh":"如果人們不能控制注意力，訊息、噪音和想法可能把他們從工作中拉走。"},{"en":"This phrase describes managing focus.","zh":"這個片語描述管理專注力。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":4},{"front":"the size of this cortex","meaning":"這個皮層的大小","examples":[{"en":"The size of this cortex varies between species.","zh":"這個皮層的大小因物種而異。"},{"en":"The size of this cortex means how large that part of the brain is.","zh":"size of this cortex 指大腦該部分有多大。"},{"en":"Scientists may compare the size of this cortex in different animals to study behaviour.","zh":"科學家可能比較不同動物這個皮層的大小，以研究行為。"},{"en":"If one species has a larger prefrontal cortex, researchers may ask whether it supports more flexible attention.","zh":"如果某一物種有較大的前額葉皮層，研究人員可能問它是否支援更靈活的注意力。"},{"en":"This phrase connects brain structure with possible mental ability.","zh":"這個片語把腦部結構與可能的心智能力連接起來。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":4},{"front":"vary between species","meaning":"因物種而異","examples":[{"en":"The size of this cortex varies between species.","zh":"這個皮層的大小因物種而異。"},{"en":"To vary between species means to be different in different kinds of animals or organisms.","zh":"vary between species 指在不同種類的動物或生物之間有所不同。"},{"en":"Lifespan varies between species: a mouse lives far fewer years than a turtle.","zh":"壽命因物種而異：老鼠壽命遠短於烏龜。"},{"en":"If brain size varies between species, behaviour and ability may also differ.","zh":"如果腦部大小因物種而異，行為和能力也可能不同。"},{"en":"This phrase describes biological differences across species.","zh":"這個片語描述跨物種的生物差異。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":4},{"front":"constitute about one-third of","meaning":"佔約……的三分之一","examples":[{"en":"The prefrontal cortex constitutes about one-third of the human brain.","zh":"前額葉皮層佔人腦約三分之一。"},{"en":"To constitute about one-third of something means to make up roughly one part out of three.","zh":"constitute about one-third of something 指大約組成三分之一。"},{"en":"If rent constitutes about one-third of a worker’s salary, housing is a major expense.","zh":"如果租金佔員工薪金約三分之一，住房就是主要開支。"},{"en":"When a brain area forms a large share of the brain, it may play an important role.","zh":"當某個腦區佔大腦很大比例，它可能扮演重要角色。"},{"en":"This phrase describes approximate proportion.","zh":"這個片語描述大約比例。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":5},{"front":"compared with","meaning":"與……相比","examples":[{"en":"The prefrontal cortex is larger in humans compared with dogs and monkeys.","zh":"與狗和猴子相比，人類的前額葉皮層較大。"},{"en":"Compared with means judged beside another thing to show difference or similarity.","zh":"compared with 指與另一事物並列判斷，以顯示差異或相似。"},{"en":"Compared with handwritten notes, digital notes are easier to search.","zh":"與手寫筆記相比，電子筆記較容易搜尋。"},{"en":"If human brain areas are larger compared with other animals, researchers may study how this affects behaviour.","zh":"如果人類腦區相比其他動物較大，研究人員可能研究這如何影響行為。"},{"en":"This phrase sets up a clear comparison.","zh":"這個片語建立清楚比較。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":5},{"front":"greater size","meaning":"較大的體積","examples":[{"en":"Its greater size in humans may enable better multitasking.","zh":"它在人類身上較大的體積可能使一心多用更好。"},{"en":"Greater size means a larger amount, area, or volume than another thing.","zh":"greater size 指相比另一事物有較大的數量、面積或體積。"},{"en":"A classroom with greater size can hold more students and wider desks.","zh":"體積較大的課室可以容納更多學生和更寬的桌子。"},{"en":"If a brain region has greater size, scientists may investigate whether it supports more complex functions.","zh":"如果某腦區體積較大，科學家可能研究它是否支援更複雜功能。"},{"en":"This phrase describes a comparative increase in size.","zh":"這個片語描述大小上的比較增加。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":5},{"front":"enable more flexible and accurate multitasking","meaning":"使一心多用更靈活和準確","examples":[{"en":"The greater size of the cortex may enable more flexible and accurate multitasking.","zh":"皮層較大的體積可能使一心多用更靈活和準確。"},{"en":"To enable more flexible and accurate multitasking means to make it possible to switch between tasks with better control and fewer mistakes.","zh":"enable more flexible and accurate multitasking 指令人能以更好控制和較少錯誤在任務之間切換。"},{"en":"A well-organised calendar can enable more flexible and accurate work planning.","zh":"安排良好的日曆可以使工作規劃更靈活和準確。"},{"en":"If the brain controls attention better, people may manage competing tasks more smoothly.","zh":"如果大腦更好地控制注意力，人們可能更順暢地管理互相競爭的任務。"},{"en":"This phrase describes a possible benefit of stronger attention control.","zh":"這個片語描述較強注意力控制可能帶來的好處。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":5},{"front":"determine whether","meaning":"確定是否","examples":[{"en":"Miller wanted to determine whether the cortex processed two tasks simultaneously.","zh":"Miller 想確定該皮層是否同時處理兩項任務。"},{"en":"To determine whether means to find out if something is true or not.","zh":"determine whether 指查明某事是否屬實。"},{"en":"A doctor may run tests to determine whether a patient has an infection.","zh":"醫生可能進行測試，以確定病人是否有感染。"},{"en":"If researchers want to determine whether multitasking is real, they need measurable evidence.","zh":"如果研究人員想確定一心多用是否真實存在，就需要可量度證據。"},{"en":"This phrase introduces a question that investigation tries to answer.","zh":"這個片語引入調查想回答的問題。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":5},{"front":"process information from","meaning":"處理來自……的資料","examples":[{"en":"The cortex may process information from two tasks.","zh":"皮層可能處理來自兩項任務的資料。"},{"en":"To process information from something means to receive, interpret, and use information from that source.","zh":"process information from something 指接收、理解並使用來自某來源的資料。"},{"en":"A student processes information from a chart by noticing numbers, labels, and trends.","zh":"學生透過注意數字、標籤和趨勢來處理來自圖表的資料。"},{"en":"If the brain processes information from one task at a time, true multitasking becomes doubtful.","zh":"如果大腦一次只處理一項任務的資料，真正一心多用就變得可疑。"},{"en":"This phrase describes how the mind handles input.","zh":"這個片語描述心智如何處理輸入資訊。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":5},{"front":"present participants with","meaning":"向參加者展示……","examples":[{"en":"Miller presented participants with visual stimuli.","zh":"Miller 向參加者展示視覺刺激。"},{"en":"To present participants with something means to show or give something to people taking part in a study.","zh":"present participants with something 指向研究參加者展示或提供某物。"},{"en":"A teacher may present students with a short passage before asking comprehension questions.","zh":"老師可能先向學生展示一篇短文，再提問理解題。"},{"en":"If researchers present participants with controlled tasks, results are easier to compare.","zh":"如果研究人員向參加者展示受控制的任務，結果會較容易比較。"},{"en":"This phrase is common in descriptions of experiments.","zh":"這個片語常見於實驗描述。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":5},{"front":"visual stimuli","meaning":"視覺刺激","examples":[{"en":"The experiment used visual stimuli to mimic multitasking.","zh":"實驗使用視覺刺激來模擬一心多用。"},{"en":"Visual stimuli are things people see that trigger a response from the eyes or brain.","zh":"visual stimuli 是人們看見並觸發眼睛或大腦反應的東西。"},{"en":"Flashing lights, colours, letters, and images can be visual stimuli in an experiment.","zh":"閃燈、顏色、字母和圖像都可以是實驗中的視覺刺激。"},{"en":"If visual stimuli appear quickly, participants must focus and respond accurately.","zh":"如果視覺刺激快速出現，參加者必須專注並準確回應。"},{"en":"This phrase refers to information presented through sight.","zh":"這個片語指透過視覺呈現的資訊。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":5},{"front":"in a way that mimicked","meaning":"以模擬……的方式","examples":[{"en":"The stimuli were shown in a way that mimicked multitasking.","zh":"這些刺激以模擬一心多用的方式展示。"},{"en":"In a way that mimicked something means in a manner designed to imitate it.","zh":"in a way that mimicked something 指以設計來模仿某事的方式。"},{"en":"A classroom game may be designed in a way that mimics real-life shopping.","zh":"課堂遊戲可能以模擬真實購物的方式設計。"},{"en":"If an experiment mimics multitasking, it tries to recreate the mental pressure of doing several tasks.","zh":"如果實驗模擬一心多用，它會嘗試重現同時做幾項任務的心理壓力。"},{"en":"This phrase describes imitation for study or practice.","zh":"這個片語描述為研究或練習而作出的模仿。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":5},{"front":"attach sensors to","meaning":"將感應器貼在……","examples":[{"en":"Researchers attached sensors to the participants’ heads.","zh":"研究人員將感應器貼在參加者頭上。"},{"en":"To attach sensors to something means to fix measuring devices onto it.","zh":"attach sensors to something 指把測量裝置固定在某物上。"},{"en":"Doctors may attach sensors to a patient’s chest to record heart activity.","zh":"醫生可能將感應器貼在病人胸口，以記錄心臟活動。"},{"en":"If sensors are attached properly, they can collect accurate information from the body.","zh":"如果感應器正確貼上，它們就能從身體收集準確資料。"},{"en":"This phrase describes setting up equipment for measurement.","zh":"這個片語描述為測量設置設備。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":5},{"front":"record electrical patterns","meaning":"記錄電活動模式","examples":[{"en":"The sensors recorded the brain’s electrical patterns.","zh":"感應器記錄大腦的電活動模式。"},{"en":"To record electrical patterns means to measure and save changes in electrical activity.","zh":"record electrical patterns 指量度並保存電活動的變化。"},{"en":"A heart monitor records electrical patterns to help doctors check heartbeat rhythm.","zh":"心臟監測器記錄電活動模式，以幫助醫生檢查心跳節奏。"},{"en":"If brain electrical patterns change during a task, researchers can see which areas are active.","zh":"如果大腦電活動模式在任務期間改變，研究人員可以看到哪些區域活躍。"},{"en":"This phrase describes collecting biological signals.","zh":"這個片語描述收集生物訊號。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":5},{"front":"neurons","meaning":"神經元","examples":[{"en":"Neurons process information in the brain.","zh":"神經元在大腦中處理資料。"},{"en":"Neurons are nerve cells that send and receive signals in the brain and nervous system.","zh":"neurons 是在大腦和神經系統中傳送及接收訊號的神經細胞。"},{"en":"When a student reads a word, neurons help recognise letters and meaning.","zh":"當學生閱讀一個詞時，神經元幫助識別字母和意思。"},{"en":"If neurons in one area become active, that area may be involved in the task.","zh":"如果某一區域的神經元變得活躍，該區域可能參與該任務。"},{"en":"This word refers to the brain’s basic signal-processing cells.","zh":"這個詞指大腦中基本的訊號處理細胞。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":6},{"front":"actually processing","meaning":"實際上正在處理","examples":[{"en":"The sensors showed whether neurons were actually processing two different tasks.","zh":"感應器顯示神經元是否實際上正在處理兩項不同任務。"},{"en":"Actually processing means really handling information, not just appearing to do so.","zh":"actually processing 指真正處理資訊，而不只是看起來如此。"},{"en":"A student may look at a page without actually processing the meaning of the words.","zh":"學生可能看着頁面，但實際上沒有處理文字意思。"},{"en":"If the brain is not actually processing two tasks at once, multitasking may be an illusion.","zh":"如果大腦實際上不是同時處理兩項任務，一心多用可能是一種錯覺。"},{"en":"This phrase separates real mental work from outward appearance.","zh":"這個片語把真正心理工作與外在表現區分開來。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":6},{"front":"become active in","meaning":"在……變得活躍","examples":[{"en":"Neurons became active in only one area at a time.","zh":"神經元一次只在一個區域變得活躍。"},{"en":"To become active in an area means to start showing measurable activity there.","zh":"become active in an area 指在某處開始顯示可量度的活動。"},{"en":"During exercise, certain muscles become active in the legs and core.","zh":"運動期間，某些肌肉會在腿部和核心位置變得活躍。"},{"en":"If brain cells become active in one area only, that may show attention is limited.","zh":"如果腦細胞只在一個區域變得活躍，這可能顯示注意力有限。"},{"en":"This phrase describes where activity starts or appears.","zh":"這個片語描述活動在哪裡開始或出現。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":6},{"front":"only one area at a time","meaning":"一次只有一個區域","examples":[{"en":"Neurons became active in only one area at a time.","zh":"神經元一次只有一個區域變得活躍。"},{"en":"Only one area at a time means just one region is active during each moment.","zh":"only one area at a time 指每一刻只有一個區域活躍。"},{"en":"A security camera can show only one area at a time if it is pointed in one direction.","zh":"如果保安攝影機只朝一個方向，它一次只能顯示一個區域。"},{"en":"If the brain focuses on only one area at a time, two demanding tasks may compete for attention.","zh":"如果大腦一次只專注一個區域，兩項高要求任務可能爭奪注意力。"},{"en":"This phrase stresses a limit on simultaneous activity.","zh":"這個片語強調同時活動的限制。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":6},{"front":"in a similar experiment","meaning":"在一項類似實驗中","examples":[{"en":"David Meyer studied young adults in a similar experiment.","zh":"David Meyer 在一項類似實驗中研究年輕成年人。"},{"en":"In a similar experiment means in another study with a comparable method or purpose.","zh":"in a similar experiment 指在另一項方法或目的相近的研究中。"},{"en":"In a similar experiment, another class may test whether music affects reading speed.","zh":"在一項類似實驗中，另一班可能測試音樂是否影響閱讀速度。"},{"en":"If similar experiments produce similar results, the conclusion becomes more reliable.","zh":"如果類似實驗得出相似結果，結論會更可靠。"},{"en":"This phrase links one study with another related study.","zh":"這個片語把一項研究與另一項相關研究連接起來。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":6},{"front":"young adults","meaning":"年輕成年人","examples":[{"en":"Meyer studied young adults in a similar experiment.","zh":"Meyer 在一項類似實驗中研究年輕成年人。"},{"en":"Young adults are people in the early stage of adulthood, often from late teens to twenties.","zh":"young adults 是處於成年早期的人，通常指十多歲後期至二十多歲的人。"},{"en":"Universities often study young adults because many students fall into this age group.","zh":"大學常研究年輕成年人，因為許多學生屬於這個年齡組別。"},{"en":"If young adults still lose efficiency while multitasking, the effect is not only a problem of old age.","zh":"如果年輕成年人一心多用時仍失去效率，這種影響就不只是老年人的問題。"},{"en":"This phrase refers to an age group between teenagers and older adults.","zh":"這個片語指青少年與較年長成年人之間的年齡群體。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":6},{"front":"instruct someone to","meaning":"指示某人去……","examples":[{"en":"He instructed the participants to solve mathematics problems.","zh":"他指示參加者去解數學題。"},{"en":"To instruct someone to do something means to tell them clearly what to do.","zh":"instruct someone to do something 指清楚告訴某人要做甚麼。"},{"en":"A teacher may instruct students to close their books before a quiz begins.","zh":"老師可能在小測開始前指示學生合上書本。"},{"en":"If participants receive clear instructions, the experiment becomes easier to control.","zh":"如果參加者得到清楚指示，實驗會較容易控制。"},{"en":"This phrase describes giving formal or direct guidance.","zh":"這個片語描述給予正式或直接指引。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":6},{"front":"solve mathematics problems","meaning":"解數學題","examples":[{"en":"Participants solved mathematics problems while classifying words.","zh":"參加者一邊分類詞語，一邊解數學題。"},{"en":"To solve mathematics problems means to work out answers to questions involving numbers, formulas, or logic.","zh":"solve mathematics problems 指計算涉及數字、公式或邏輯問題的答案。"},{"en":"A student may solve mathematics problems by writing each step clearly.","zh":"學生可能透過清楚寫下每一步來解數學題。"},{"en":"If people solve maths problems while doing another task, their thinking may slow down.","zh":"如果人們一邊解數學題一邊做另一項任務，思考可能會變慢。"},{"en":"This phrase describes a mental task that usually needs focused attention.","zh":"這個片語描述通常需要集中注意力的心智任務。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":6},{"front":"classify something into categories","meaning":"將……分類","examples":[{"en":"Participants classified simple words into categories.","zh":"參加者將簡單詞語分類。"},{"en":"To classify something into categories means to sort items into groups based on shared features.","zh":"classify something into categories 指根據共同特徵把項目分成不同組別。"},{"en":"A child may classify animals into categories such as birds, fish, and mammals.","zh":"孩子可能把動物分類為鳥類、魚類和哺乳類。"},{"en":"If people classify words while solving maths problems, both tasks compete for mental resources.","zh":"如果人們一邊分類詞語一邊解數學題，兩項任務會爭奪心理資源。"},{"en":"This phrase describes organising information into groups.","zh":"這個片語描述把資訊整理成不同類別。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":6},{"front":"switch between tasks","meaning":"在任務之間切換","examples":[{"en":"People are actually switching between tasks when they think they are multitasking.","zh":"當人們以為自己在一心多用時，其實是在任務之間切換。"},{"en":"To switch between tasks means to move attention from one task to another repeatedly.","zh":"switch between tasks 指反覆把注意力從一項任務轉到另一項。"},{"en":"A worker may switch between tasks by answering emails, checking a report, and returning to a call.","zh":"員工可能透過回電郵、查看報告，再回到電話來在任務之間切換。"},{"en":"Each switch can waste time because the brain must restart the next task.","zh":"每次切換都可能浪費時間，因為大腦必須重新啟動下一項任務。"},{"en":"This phrase explains why multitasking can feel busy but inefficient.","zh":"這個片語解釋為何一心多用感覺忙碌但效率低。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":6},{"front":"attempt both tasks simultaneously","meaning":"嘗試同時處理兩項任務","examples":[{"en":"The participants attempted both tasks simultaneously.","zh":"參加者嘗試同時處理兩項任務。"},{"en":"To attempt both tasks simultaneously means to try to do two tasks at the same time.","zh":"attempt both tasks simultaneously 指嘗試在同一時間做兩項任務。"},{"en":"A student may attempt both tasks simultaneously by taking notes while replying to a message.","zh":"學生可能一邊做筆記一邊回訊息，嘗試同時處理兩項任務。"},{"en":"If both tasks need thought, attempting them together may increase errors.","zh":"如果兩項任務都需要思考，同時嘗試處理可能增加錯誤。"},{"en":"This phrase describes trying to multitask, whether or not it works well.","zh":"這個片語描述嘗試一心多用，不論效果好壞。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":6},{"front":"eventually complete","meaning":"最終完成","examples":[{"en":"The participants eventually completed both tasks.","zh":"參加者最終完成了兩項任務。"},{"en":"To eventually complete something means to finish it after some time, delay, or effort.","zh":"eventually complete something 指經過一段時間、延誤或努力後完成某事。"},{"en":"A student may eventually complete a difficult essay after rewriting it several times.","zh":"學生可能重寫幾次後最終完成一篇困難文章。"},{"en":"If people switch between tasks, they may eventually complete them, but more slowly.","zh":"如果人們在任務之間切換，他們可能最終完成任務，但速度較慢。"},{"en":"This phrase focuses on finishing, not necessarily finishing efficiently.","zh":"這個片語聚焦於完成，而不一定是高效完成。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":7},{"front":"take longer overall than","meaning":"整體需時比……更長","examples":[{"en":"The work took longer overall than it would have with one task.","zh":"這項工作整體需時比只做一項任務更長。"},{"en":"To take longer overall than something means to require more total time.","zh":"take longer overall than something 指總共需要更多時間。"},{"en":"Cooking two dishes at once may take longer overall than cooking one carefully first.","zh":"同時煮兩道菜，整體需時可能比先仔細煮一道更長。"},{"en":"If switching wastes time, multitasking may take longer overall than doing tasks separately.","zh":"如果切換浪費時間，一心多用整體需時可能比分開做任務更長。"},{"en":"This phrase compares total time needed.","zh":"這個片語比較總所需時間。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":7},{"front":"sacrifice efficiency","meaning":"犧牲效率","examples":[{"en":"People sacrifice efficiency when they multitask.","zh":"人們一心多用時會犧牲效率。"},{"en":"To sacrifice efficiency means to lose speed, quality, or smoothness in order to do something else.","zh":"sacrifice efficiency 指為了做其他事而失去速度、質素或流暢度。"},{"en":"A student may sacrifice efficiency by checking social media every few minutes while studying.","zh":"學生溫習時每隔幾分鐘查看社交媒體，可能犧牲效率。"},{"en":"If people divide attention, they may finish less work in the same amount of time.","zh":"如果人們分散注意力，他們可能在相同時間內完成較少工作。"},{"en":"This phrase shows a cost of multitasking.","zh":"這個片語顯示一心多用的代價。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":7},{"front":"research subjects","meaning":"研究對象","examples":[{"en":"Gloria Mark used office workers as her research subjects.","zh":"Gloria Mark 使用辦公室員工作為研究對象。"},{"en":"Research subjects are people, animals, or cases studied in research.","zh":"research subjects 是研究中被研究的人、動物或個案。"},{"en":"In a reading study, students may be the research subjects.","zh":"在閱讀研究中，學生可能是研究對象。"},{"en":"If office workers are research subjects, the findings may relate closely to workplace habits.","zh":"如果辦公室員工是研究對象，研究結果可能與職場習慣密切相關。"},{"en":"This phrase names the people or cases being investigated.","zh":"這個片語指出正在被調查的人或個案。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":7},{"front":"constantly multitasking","meaning":"不斷一心多用","examples":[{"en":"She found that office workers were constantly multitasking.","zh":"她發現辦公室員工不斷一心多用。"},{"en":"Constantly multitasking means repeatedly switching between tasks throughout the day.","zh":"constantly multitasking 指整天反覆在任務之間切換。"},{"en":"A worker may be constantly multitasking if calls, emails, messages, and reports all compete for attention.","zh":"如果電話、電郵、訊息和報告都爭奪注意力，員工可能不斷一心多用。"},{"en":"If people multitask constantly, they may feel busy but make slower progress.","zh":"如果人們不斷一心多用，他們可能感到忙碌，但進度較慢。"},{"en":"This phrase describes multitasking as a continuous habit.","zh":"這個片語描述一心多用作為持續習慣。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":7},{"front":"on average","meaning":"平均而言","examples":[{"en":"On average, workers were interrupted about every 11 minutes.","zh":"平均而言，員工大約每11分鐘就被打斷。"},{"en":"On average means generally, when all cases are considered together.","zh":"on average 指整體考慮所有個案時，一般而言。"},{"en":"On average, students who sleep well make fewer careless mistakes.","zh":"平均而言，睡眠充足的學生較少犯粗心錯誤。"},{"en":"If interruptions happen every 11 minutes on average, long focus periods become rare.","zh":"如果平均每11分鐘就有一次打斷，長時間專注便變得罕見。"},{"en":"This phrase describes a general pattern, not every single case.","zh":"這個片語描述一般模式，而不是每一個個案。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":7},{"front":"be interrupted about every","meaning":"大約每……就被打斷","examples":[{"en":"Workers were interrupted about every 11 minutes.","zh":"員工大約每11分鐘就被打斷。"},{"en":"To be interrupted about every certain period means to be stopped or disturbed roughly at that repeated interval.","zh":"be interrupted about every certain period 指大約以某個重複間隔被停止或干擾。"},{"en":"A teacher may be interrupted about every few minutes if students keep asking unrelated questions.","zh":"如果學生不斷問無關問題，老師可能大約每幾分鐘就被打斷。"},{"en":"If workers are interrupted often, they may need extra time to restart each task.","zh":"如果員工經常被打斷，他們可能需要額外時間重新開始每項任務。"},{"en":"This phrase describes frequent repeated disruption.","zh":"這個片語描述頻繁而重複的干擾。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":7},{"front":"do different jobs at once","meaning":"同時做不同工作","examples":[{"en":"Doing different jobs at once may save time.","zh":"同時做不同工作可能節省時間。"},{"en":"To do different jobs at once means to work on several different tasks in the same period.","zh":"do different jobs at once 指在同一段時間處理幾項不同任務。"},{"en":"A parent may try to cook dinner, check homework, and answer a call at once.","zh":"家長可能嘗試同時煮晚餐、檢查功課和接電話。"},{"en":"If the jobs are simple, doing them together may work; if they are complex, mistakes may increase.","zh":"如果工作簡單，一起做可能可行；如果工作複雜，錯誤可能增加。"},{"en":"This phrase describes practical multitasking in daily life.","zh":"這個片語描述日常生活中的實際一心多用。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":7},{"front":"does not necessarily","meaning":"未必；不一定","examples":[{"en":"Being faster does not necessarily make people more efficient.","zh":"速度較快未必令人更有效率。"},{"en":"Does not necessarily means is not always true or does not automatically happen.","zh":"does not necessarily 指不一定總是真的，或不會自動發生。"},{"en":"A higher price does not necessarily mean better quality.","zh":"價格較高不一定代表質素較好。"},{"en":"If people finish quickly but make many mistakes, speed does not necessarily equal efficiency.","zh":"如果人們很快完成但犯很多錯，速度不一定等於效率。"},{"en":"This phrase warns against assuming a simple connection.","zh":"這個片語提醒不要假設簡單關聯。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":7},{"front":"make people more efficient","meaning":"令人更有效率","examples":[{"en":"Being faster does not necessarily make people more efficient.","zh":"速度較快未必令人更有效率。"},{"en":"To make people more efficient means to help them produce better results with less wasted time or effort.","zh":"make people more efficient 指幫助人們用較少浪費的時間或精力產出更好結果。"},{"en":"A clear checklist can make workers more efficient by reducing repeated questions.","zh":"清晰清單可以透過減少重複問題令人更有效率。"},{"en":"If a tool saves time but creates more errors, it may not make people more efficient.","zh":"如果工具節省時間但造成更多錯誤，它未必令人更有效率。"},{"en":"This phrase focuses on useful productivity, not speed alone.","zh":"這個片語聚焦於有用的生產力，而不只是速度。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":7},{"front":"be as likely to...as...","meaning":"……的可能性與……一樣高","examples":[{"en":"People are as likely to interrupt themselves as they are to be interrupted by outside sources.","zh":"人們自行中斷工作的可能性與被外來因素打斷的可能性一樣高。"},{"en":"Be as likely to do one thing as another means the two possibilities have about the same chance.","zh":"be as likely to do one thing as another 指兩種可能性的機會大致相同。"},{"en":"A student may be as likely to lose focus from their own thoughts as from classroom noise.","zh":"學生被自己想法分心的可能性，可能與被課室噪音分心一樣高。"},{"en":"If self-interruption is as common as outside interruption, people need to manage their own habits too.","zh":"如果自我中斷與外來打斷一樣常見，人們也需要管理自己的習慣。"},{"en":"This phrase compares two equal or similar probabilities.","zh":"這個片語比較兩種相等或相近的可能性。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":7},{"front":"interrupt themselves","meaning":"自行中斷工作","examples":[{"en":"People are as likely to interrupt themselves as they are to be interrupted by others.","zh":"人們自行中斷工作的可能性與被別人打斷一樣高。"},{"en":"To interrupt themselves means to stop their own work without someone else causing it.","zh":"interrupt themselves 指在沒有其他人造成干擾下停止自己的工作。"},{"en":"A student may interrupt themselves by checking a message during revision.","zh":"學生可能在溫習期間查看訊息而自行中斷工作。"},{"en":"If people interrupt themselves often, they may blame the workplace while ignoring their own habits.","zh":"如果人們經常自行中斷工作，他們可能責怪工作環境，卻忽視自己的習慣。"},{"en":"This phrase describes self-created distraction.","zh":"這個片語描述自己造成的分心。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":8},{"front":"outside sources","meaning":"外來因素；外來來源","examples":[{"en":"People may be interrupted by outside sources.","zh":"人們可能被外來因素打斷。"},{"en":"Outside sources are external causes of interruption, such as calls, visitors, alerts, or noises.","zh":"outside sources 是外部干擾來源，例如電話、訪客、提示聲或噪音。"},{"en":"A student may be distracted by outside sources like traffic, siblings, and phone notifications.","zh":"學生可能被交通、兄弟姊妹和手機通知等外來因素分心。"},{"en":"If outside sources are controlled, workers may concentrate for longer periods.","zh":"如果外來因素受到控制，員工可能能專注更長時間。"},{"en":"This phrase contrasts external interruptions with self-distraction.","zh":"這個片語把外部干擾與自我分心作對比。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":8},{"front":"for no apparent reason","meaning":"無明顯原因","examples":[{"en":"An employee may stop for no apparent reason to check a website.","zh":"員工可能無明顯原因停下來查看網站。"},{"en":"For no apparent reason means without an obvious or clear reason.","zh":"for no apparent reason 指沒有明顯或清楚原因。"},{"en":"A computer may suddenly shut down for no apparent reason during a lesson.","zh":"電腦可能在課堂中無明顯原因突然關機。"},{"en":"If people check websites for no apparent reason, the habit may come from boredom or anxiety.","zh":"如果人們無明顯原因查看網站，這習慣可能來自沉悶或焦慮。"},{"en":"This phrase describes behaviour that seems unexplained from the outside.","zh":"這個片語描述從外面看似無法解釋的行為。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":8},{"front":"concentrate for more than","meaning":"專注超過……","examples":[{"en":"Employees felt distressed if they concentrated for more than 20 minutes.","zh":"如果員工專注超過20分鐘，他們會感到不安。"},{"en":"To concentrate for more than a period means to stay focused longer than that amount of time.","zh":"concentrate for more than a period 指專注時間長於該段時間。"},{"en":"A child may find it hard to concentrate for more than fifteen minutes without a break.","zh":"孩子可能覺得不休息便專注超過十五分鐘很困難。"},{"en":"If people are used to constant interruptions, concentrating for longer periods may feel uncomfortable.","zh":"如果人們習慣不斷被打斷，長時間專注可能感覺不舒服。"},{"en":"This phrase describes the length of sustained attention.","zh":"這個片語描述持續注意力的長度。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":8},{"front":"feel distressed","meaning":"感到苦惱；不安","examples":[{"en":"Employees felt distressed after concentrating for a long period.","zh":"員工在長時間專注後感到不安。"},{"en":"To feel distressed means to feel worried, upset, tense, or uncomfortable.","zh":"feel distressed 指感到擔心、沮喪、緊張或不舒服。"},{"en":"A student may feel distressed when too many deadlines arrive in the same week.","zh":"當同一星期有太多截止日期時，學生可能感到苦惱。"},{"en":"If people feel distressed during quiet focus, they may seek distraction to reduce discomfort.","zh":"如果人們在安靜專注時感到不安，可能會尋找分心事物來減低不適。"},{"en":"This phrase describes emotional unease.","zh":"這個片語描述情緒上的不安。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":8},{"front":"a short attention span","meaning":"注意力持續時間短","examples":[{"en":"The average person may have a short attention span.","zh":"普通人可能注意力持續時間短。"},{"en":"A short attention span means a limited ability to stay focused for a long time.","zh":"short attention span 指長時間保持專注的能力有限。"},{"en":"A child with a short attention span may switch from homework to toys after a few minutes.","zh":"注意力持續時間短的孩子可能幾分鐘後就從功課轉到玩具。"},{"en":"If media becomes shorter and faster, people may become used to brief attention periods.","zh":"如果媒體變得更短更快，人們可能習慣短暫注意。"},{"en":"This phrase describes difficulty maintaining focus.","zh":"這個片語描述難以維持專注。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":8},{"front":"be responsible","meaning":"是成因；需負責","examples":[{"en":"Some people argue that new technology is responsible.","zh":"有些人認為新科技是成因。"},{"en":"To be responsible means to be the cause of something or to have responsibility for it.","zh":"be responsible 指是某事的原因，或對某事負有責任。"},{"en":"Poor lighting may be responsible for students feeling tired while reading.","zh":"光線不足可能是學生閱讀時感到疲倦的原因。"},{"en":"If phones cause constant distraction, technology may be partly responsible for shorter attention spans.","zh":"如果手機造成持續分心，科技可能對較短注意力持續時間負有部分責任。"},{"en":"This phrase can identify a cause or assign blame.","zh":"這個片語可指出原因或歸咎責任。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":8},{"front":"always at hand","meaning":"隨手可用；近在手邊","examples":[{"en":"Mobile phones and computers are always at hand.","zh":"手機和電腦總是隨手可用。"},{"en":"Always at hand means always nearby and easy to reach.","zh":"always at hand 指總是在附近，並且容易拿到。"},{"en":"A notebook at hand helps a student write down ideas before forgetting them.","zh":"隨手可用的筆記簿幫助學生在忘記前寫下想法。"},{"en":"If distracting devices are always at hand, checking them becomes almost automatic.","zh":"如果令人分心的裝置總是近在手邊，查看它們幾乎會變成自動反應。"},{"en":"This phrase describes easy immediate access.","zh":"這個片語描述即時而容易取得。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":8},{"front":"run out of distractions","meaning":"不愁沒有令人分心的事物","examples":[{"en":"People never run out of distractions.","zh":"人們永遠不愁沒有令人分心的事物。"},{"en":"To run out of distractions means to have no more things available to distract attention.","zh":"run out of distractions 指沒有更多可以分散注意力的東西。"},{"en":"A student with games, messages, videos, and snacks nearby may never run out of distractions.","zh":"如果學生身邊有遊戲、訊息、影片和零食，他可能永遠不愁沒有令人分心的事物。"},{"en":"If distractions are endless, people may avoid difficult work without meaning to.","zh":"如果分心事物無窮無盡，人們可能無意中逃避困難工作。"},{"en":"This phrase suggests there is always another thing competing for attention.","zh":"這個片語暗示總有另一件事在爭奪注意力。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":8},{"front":"media formats","meaning":"媒體形式","examples":[{"en":"Media formats such as advertisements and news articles are becoming shorter.","zh":"廣告和新聞文章等媒體形式正變得更短。"},{"en":"Media formats are the forms in which information or entertainment is presented.","zh":"media formats 是資訊或娛樂被呈現的形式。"},{"en":"Videos, podcasts, posters, news articles, and social media posts are media formats.","zh":"影片、播客、海報、新聞文章和社交媒體帖文都是媒體形式。"},{"en":"If media formats become shorter, people may get used to quick bursts of information.","zh":"如果媒體形式變得更短，人們可能習慣快速而短促的資訊。"},{"en":"This phrase describes types of media presentation.","zh":"這個片語描述媒體呈現的類型。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":8},{"front":"be accustomed to","meaning":"習慣於……","examples":[{"en":"People are accustomed to attending to information only briefly.","zh":"人們習慣於只短暫地留意資料。"},{"en":"To be accustomed to something means to be used to it because it happens often.","zh":"be accustomed to something 指因為某事經常發生而習慣它。"},{"en":"Students are accustomed to checking messages quickly between lessons.","zh":"學生習慣於課與課之間快速查看訊息。"},{"en":"If people are accustomed to short information, long reading may feel difficult.","zh":"如果人們習慣短資訊，長篇閱讀可能感覺困難。"},{"en":"This phrase describes a habit formed through repeated experience.","zh":"這個片語描述透過反覆經驗形成的習慣。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":8},{"front":"attend to information only briefly","meaning":"只短暫地留意資料","examples":[{"en":"People are accustomed to attending to information only briefly.","zh":"人們習慣於只短暫地留意資料。"},{"en":"To attend to information only briefly means to pay attention to it for a short time only.","zh":"attend to information only briefly 指只用短時間注意某些資料。"},{"en":"A person scrolling through headlines may attend to each story only briefly.","zh":"滑動瀏覽標題的人可能只短暫地留意每則新聞。"},{"en":"If people attend to information only briefly, they may understand less deeply.","zh":"如果人們只短暫地留意資料，他們可能理解得較不深入。"},{"en":"This phrase describes shallow or short attention to information.","zh":"這個片語描述對資訊的短暫或表層注意。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":9},{"front":"focusing on a single task","meaning":"專注於單一任務","examples":[{"en":"Focusing on a single task is the most efficient way for the brain to work.","zh":"專注於單一任務是大腦運作最有效率的方法。"},{"en":"Focusing on a single task means giving attention to one activity only.","zh":"focusing on a single task 指只把注意力放在一項活動上。"},{"en":"A student may learn vocabulary faster by focusing on one word list before opening another.","zh":"學生可能先專注於一份詞彙表，再打開另一份，這樣學得更快。"},{"en":"If people focus on one task, they avoid the time cost of switching.","zh":"如果人們專注於一項任務，就能避免切換帶來的時間成本。"},{"en":"This phrase contrasts single-task work with multitasking.","zh":"這個片語把單一任務工作與一心多用作對比。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":9},{"front":"the most efficient way for","meaning":"對……來說最有效率的方法","examples":[{"en":"Focusing on one task is the most efficient way for the brain to work.","zh":"專注於一項任務是對大腦來說最有效率的方法。"},{"en":"The most efficient way for something means the method that uses the least wasted time or effort for that purpose.","zh":"most efficient way for something 指就某目的而言浪費最少時間或精力的方法。"},{"en":"Planning before writing is often the most efficient way for students to finish an essay clearly.","zh":"寫作前先規劃，通常是學生清楚完成文章最有效率的方法。"},{"en":"If one method reduces mistakes and saves time, it may be the most efficient way.","zh":"如果某方法減少錯誤並節省時間，它可能是最有效率的方法。"},{"en":"This phrase identifies the best method in terms of efficiency.","zh":"這個片語指出以效率而言最佳的方法。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":9},{"front":"not always practical","meaning":"並非總是切實可行","examples":[{"en":"This approach is not always practical.","zh":"這種方法並非總是切實可行。"},{"en":"Not always practical means not suitable or possible in every real-life situation.","zh":"not always practical 指不是在每個現實情況中都合適或可行。"},{"en":"Studying in complete silence is helpful, but it is not always practical at home.","zh":"在完全安靜中溫習很有幫助，但在家中並非總是切實可行。"},{"en":"If workers must answer urgent calls, single-tasking may not always be possible.","zh":"如果員工必須接聽緊急電話，單一任務工作未必總是可行。"},{"en":"This phrase recognises that a good idea may face real limits.","zh":"這個片語承認好想法可能面對現實限制。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":9},{"front":"feel more comfortable and efficient","meaning":"感到更舒適和有效率","examples":[{"en":"People naturally feel more comfortable and efficient in varied environments.","zh":"人們在多變環境中自然感到更舒適和有效率。"},{"en":"To feel more comfortable and efficient means to feel more at ease and more productive.","zh":"feel more comfortable and efficient 指感到更自在並更有生產力。"},{"en":"Some students feel more comfortable and efficient when they study with a short checklist.","zh":"有些學生使用短清單溫習時，會感到更舒適和有效率。"},{"en":"If an environment matches people’s habits, they may feel productive even when they are switching tasks.","zh":"如果環境符合人們的習慣，即使他們在切換任務，也可能感到有生產力。"},{"en":"This phrase combines emotional comfort with a sense of productivity.","zh":"這個片語結合情緒舒適和生產力感。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":9},{"front":"environments that offer","meaning":"提供……的環境","examples":[{"en":"People feel comfortable in environments that offer a variety of tasks.","zh":"人們在提供多種任務的環境中感到舒適。"},{"en":"Environments that offer something are places or settings that provide that feature or opportunity.","zh":"environments that offer something 指提供某種特徵或機會的地方或環境。"},{"en":"A school library offers quiet desks, books, computers, and study rooms.","zh":"學校圖書館提供安靜書桌、書本、電腦和溫習室。"},{"en":"If an office offers many possible tasks, workers may switch between them frequently.","zh":"如果辦公室提供許多可能任務，員工可能頻繁在它們之間切換。"},{"en":"This phrase describes what a setting makes available.","zh":"這個片語描述某環境提供甚麼。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":9},{"front":"a variety of tasks","meaning":"多種任務","examples":[{"en":"Some environments offer a variety of tasks.","zh":"一些環境提供多種任務。"},{"en":"A variety of tasks means several different kinds of work or activities.","zh":"variety of tasks 指幾種不同種類的工作或活動。"},{"en":"A teacher’s day includes a variety of tasks, such as teaching, marking, meeting parents, and planning lessons.","zh":"老師一天包括多種任務，例如教書、改卷、見家長和備課。"},{"en":"If people have a variety of tasks nearby, they may switch before finishing one.","zh":"如果人們身邊有多種任務，他們可能在完成一項前就切換。"},{"en":"This phrase describes diversity in activities.","zh":"這個片語描述活動上的多樣性。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":9},{"front":"external interruptions","meaning":"外來干擾","examples":[{"en":"External interruptions can reduce workplace efficiency.","zh":"外來干擾可以降低工作效率。"},{"en":"External interruptions are disruptions caused by other people, alerts, noise, or events outside the person’s own mind.","zh":"external interruptions 是由其他人、提示聲、噪音或外部事件造成的干擾。"},{"en":"A phone call during writing is an external interruption.","zh":"寫作期間來電就是外來干擾。"},{"en":"If external interruptions happen too often, workers may lose focus and repeat work.","zh":"如果外來干擾太頻繁，員工可能失去專注並重複工作。"},{"en":"This phrase contrasts outside disturbance with self-distraction.","zh":"這個片語把外部打擾與自我分心作對比。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":9},{"front":"self-distraction","meaning":"自我分心","examples":[{"en":"Self-distraction can cause losses of efficiency.","zh":"自我分心可以造成效率損失。"},{"en":"Self-distraction means distracting yourself without an outside interruption.","zh":"self-distraction 指在沒有外部打擾下自己令自己分心。"},{"en":"A student practises self-distraction when they open a video app during revision for no clear reason.","zh":"學生溫習時無明顯原因打開影片應用程式，就是自我分心。"},{"en":"If people distract themselves often, quiet workplaces alone will not solve the problem.","zh":"如果人們經常自我分心，單靠安靜工作場所不能解決問題。"},{"en":"This phrase describes distraction created by one’s own choices or habits.","zh":"這個片語描述由自己的選擇或習慣造成的分心。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":9},{"front":"cause substantial losses of","meaning":"造成……的重大損失","examples":[{"en":"Multitasking can cause substantial losses of workplace efficiency.","zh":"一心多用可以造成工作效率的重大損失。"},{"en":"To cause substantial losses of something means to create large reductions in it.","zh":"cause substantial losses of something 指造成某物大幅減少。"},{"en":"Poor planning can cause substantial losses of time during a school project.","zh":"計劃差劣可以在學校專題中造成大量時間損失。"},{"en":"If workers are interrupted constantly, a company may lose many productive hours.","zh":"如果員工不斷被打斷，公司可能失去許多有生產力的工時。"},{"en":"This phrase describes a serious negative effect.","zh":"這個片語描述嚴重負面影響。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":9},{"front":"workplace efficiency","meaning":"工作效率；工作場所效率","examples":[{"en":"External interruptions can reduce workplace efficiency.","zh":"外來干擾可以降低工作效率。"},{"en":"Workplace efficiency means how well time, effort, and resources are used at work.","zh":"workplace efficiency 指工作中時間、精力和資源使用得有多好。"},{"en":"Clear roles and fewer unnecessary meetings can improve workplace efficiency.","zh":"清晰角色和較少不必要會議可以提高工作效率。"},{"en":"If employees spend too much time switching tasks, workplace efficiency may fall.","zh":"如果員工花太多時間切換任務，工作效率可能下降。"},{"en":"This phrase focuses on productivity in a work setting.","zh":"這個片語聚焦於工作環境中的生產力。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":9},{"front":"need not involve","meaning":"不必涉及","examples":[{"en":"Improvements need not involve dramatic changes.","zh":"改善不必涉及大幅改變。"},{"en":"Need not involve means do not have to include or require something.","zh":"need not involve 指不需要包括或要求某事。"},{"en":"Better study habits need not involve expensive courses; small daily routines may help.","zh":"更好的學習習慣不必涉及昂貴課程；每日小習慣可能有幫助。"},{"en":"If a problem can be reduced by simple rules, solutions need not involve major reform.","zh":"如果問題可以透過簡單規則減少，解決方法不必涉及重大改革。"},{"en":"This phrase shows that something can be done without a particular feature.","zh":"這個片語顯示某事可以不包含某特定元素而完成。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":10},{"front":"dramatic changes","meaning":"大幅改變","examples":[{"en":"Improvements need not involve dramatic changes.","zh":"改善不必涉及大幅改變。"},{"en":"Dramatic changes are large, obvious, or sudden changes.","zh":"dramatic changes 是大型、明顯或突然的改變。"},{"en":"A school can improve homework routines without dramatic changes to the whole timetable.","zh":"學校可以改善功課安排，而不需要對整個時間表作大幅改變。"},{"en":"If small adjustments work, dramatic changes may be unnecessary and disruptive.","zh":"如果小調整有效，大幅改變可能不必要且造成干擾。"},{"en":"This phrase describes major changes, not minor improvements.","zh":"這個片語描述重大改變，而不是小改善。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":10},{"front":"no one is suggesting","meaning":"沒有人建議","examples":[{"en":"No one is suggesting banning email.","zh":"沒有人建議禁用電郵。"},{"en":"No one is suggesting means the writer is rejecting an extreme interpretation of the argument.","zh":"no one is suggesting 指作者在否定對論點的極端理解。"},{"en":"No one is suggesting that students should never use phones; the point is to use them wisely.","zh":"沒有人建議學生永遠不應使用手機；重點是明智使用。"},{"en":"If a writer says this, they usually want to sound reasonable rather than extreme.","zh":"如果作者這樣說，通常想顯得合理而不是極端。"},{"en":"This phrase clarifies what the argument is not saying.","zh":"這個片語澄清論點並不是在說甚麼。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":10},{"front":"ban email","meaning":"禁用電郵","examples":[{"en":"No one is suggesting banning email.","zh":"沒有人建議禁用電郵。"},{"en":"To ban email means to forbid people from using email.","zh":"ban email 指禁止人們使用電郵。"},{"en":"A company would create serious communication problems if it tried to ban email completely.","zh":"如果公司嘗試完全禁用電郵，會造成嚴重溝通問題。"},{"en":"If email causes distraction, a better solution may be to limit checking times rather than ban it.","zh":"如果電郵造成分心，較好的解決方法可能是限制查看時間，而不是禁用它。"},{"en":"This phrase describes a strict prohibition of email use.","zh":"這個片語描述對電郵使用的嚴格禁止。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":10},{"front":"perform only one task","meaning":"只執行一項任務","examples":[{"en":"No one is suggesting making employees perform only one task.","zh":"沒有人建議讓員工只執行一項任務。"},{"en":"To perform only one task means to do just one activity and nothing else.","zh":"perform only one task 指只做一項活動而不做其他事。"},{"en":"A cashier may perform only one task during training before handling customers alone.","zh":"收銀員在培訓期間可能先只執行一項任務，再獨立服務顧客。"},{"en":"In real offices, employees often cannot perform only one task because urgent issues appear.","zh":"在真實辦公室中，員工常不能只執行一項任務，因為緊急事情會出現。"},{"en":"This phrase describes strict single-task work.","zh":"這個片語描述嚴格的單一任務工作。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":10},{"front":"common activities such as","meaning":"……等常見活動","examples":[{"en":"Common activities such as group meetings could be more efficient.","zh":"小組會議等常見活動可以更有效率。"},{"en":"Common activities such as introduces ordinary examples of a wider category.","zh":"common activities such as 用來引入某一較大類別中的普通例子。"},{"en":"Common activities such as shopping, cooking, and commuting can all be affected by technology.","zh":"購物、煮飯和通勤等常見活動都可能受科技影響。"},{"en":"If common activities are improved, many people benefit because they happen often.","zh":"如果常見活動得到改善，許多人會受益，因為它們經常發生。"},{"en":"This phrase introduces familiar examples.","zh":"這個片語引入熟悉例子。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":10},{"front":"group meetings","meaning":"小組會議；團體會議","examples":[{"en":"Group meetings would be more efficient if mobile phones were prohibited.","zh":"如果手機被禁止，小組會議會更有效率。"},{"en":"Group meetings are discussions where several people gather to share ideas, make decisions, or coordinate work.","zh":"group meetings 是幾個人聚集起來分享想法、作決定或協調工作的討論。"},{"en":"Students may hold group meetings to plan a presentation.","zh":"學生可能舉行小組會議來規劃匯報。"},{"en":"If phones distract participants, group meetings can become longer and less useful.","zh":"如果手機分散參加者注意力，小組會議可能變得更長且較不有用。"},{"en":"This phrase refers to meetings involving more than two people.","zh":"這個片語指涉及多於兩人的會議。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":10},{"front":"a frequent distraction","meaning":"常見的干擾","examples":[{"en":"Mobile phones are a frequent distraction.","zh":"手機是常見的干擾。"},{"en":"A frequent distraction is something that often pulls attention away from the main task.","zh":"frequent distraction 是經常把注意力從主要任務拉走的事物。"},{"en":"Notifications can be a frequent distraction when a student is trying to revise.","zh":"當學生嘗試溫習時，通知可以是常見干擾。"},{"en":"If a distraction happens often, it can seriously reduce concentration over a whole day.","zh":"如果干擾經常發生，它可以在整天中嚴重降低專注力。"},{"en":"This phrase describes a common source of lost focus.","zh":"這個片語描述常見的失焦來源。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":10},{"front":"be prohibited","meaning":"被禁止","examples":[{"en":"Mobile phones should be prohibited during some meetings.","zh":"在一些會議期間，手機應被禁止。"},{"en":"To be prohibited means to be officially not allowed.","zh":"be prohibited 指被正式禁止。"},{"en":"Smoking is prohibited in many public buildings.","zh":"許多公共建築物禁止吸煙。"},{"en":"If phones are prohibited during meetings, participants may listen more carefully.","zh":"如果手機在會議期間被禁止，參加者可能更仔細聆聽。"},{"en":"This phrase describes a rule that bans an action or object.","zh":"這個片語描述禁止某行動或物品的規則。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":10},{"front":"apply similar methods","meaning":"採用類似方法","examples":[{"en":"Individuals can apply similar methods to prevent self-distraction.","zh":"個人可以採用類似方法來防止自我分心。"},{"en":"To apply similar methods means to use comparable strategies in another situation.","zh":"apply similar methods 指在另一情況中使用相近策略。"},{"en":"A student who studies well at school can apply similar methods at home.","zh":"在學校溫習得好的學生，可以在家採用類似方法。"},{"en":"If phone bans help meetings, people may use similar rules for their own work time.","zh":"如果手機禁令幫助會議，人們可能為自己的工作時間使用類似規則。"},{"en":"This phrase describes transferring a useful approach.","zh":"這個片語描述轉用有用方法。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":10},{"front":"prevent self-distraction","meaning":"防止自我分心","examples":[{"en":"Individuals can apply methods to prevent self-distraction.","zh":"個人可以採用方法防止自我分心。"},{"en":"To prevent self-distraction means to stop yourself from pulling your own attention away.","zh":"prevent self-distraction 指阻止自己把自己的注意力拉走。"},{"en":"A student can prevent self-distraction by turning off notifications before studying.","zh":"學生可以在溫習前關閉通知，以防止自我分心。"},{"en":"If people plan when to check messages, they may interrupt themselves less often.","zh":"如果人們規劃何時查看訊息，他們可能較少自行中斷工作。"},{"en":"This phrase describes controlling one’s own attention habits.","zh":"這個片語描述控制自己的注意力習慣。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":10},{"front":"instead of","meaning":"不要……而……","examples":[{"en":"Instead of checking every email, employees could dedicate the first hour to one job.","zh":"員工不要查看每封電郵，而可以把一天的第一個小時用於一項工作。"},{"en":"Instead of means choosing one action in place of another.","zh":"instead of 指選擇一項行動來取代另一項。"},{"en":"Instead of watching videos after school, a student may finish homework first.","zh":"學生放學後可以先完成功課，而不是看影片。"},{"en":"If workers write a report first instead of checking email, they may protect focused time.","zh":"如果員工先寫報告而不是查看電郵，他們可能保護專注時間。"},{"en":"This phrase clearly shows contrast between two choices.","zh":"這個片語清楚展示兩個選擇之間的對比。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":11},{"front":"immediately checking every email","meaning":"立即查看每封電郵","examples":[{"en":"Employees may start the day by immediately checking every email.","zh":"員工可能以立即查看每封電郵開始一天。"},{"en":"Immediately checking every email means reading each email right away without delay.","zh":"immediately checking every email 指不延遲地馬上閱讀每一封電郵。"},{"en":"A worker who opens the inbox before planning the day may spend an hour responding to small messages.","zh":"在計劃一天前先打開收件箱的員工，可能花一小時回覆小訊息。"},{"en":"If employees check every email immediately, urgent-looking messages may control their schedule.","zh":"如果員工立即查看每封電郵，看似緊急的訊息可能控制他們的時間表。"},{"en":"This phrase describes a reactive work habit.","zh":"這個片語描述被動反應式工作習慣。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":11},{"front":"dedicate the first hour of the day to","meaning":"把一天的第一個小時用於……","examples":[{"en":"They could dedicate the first hour of the day to one job.","zh":"他們可以把一天的第一個小時用於一項工作。"},{"en":"To dedicate the first hour of the day to something means to reserve that first hour only for that purpose.","zh":"dedicate the first hour of the day to something 指把一天開始的第一小時只留給某目的。"},{"en":"A student may dedicate the first hour of the day to reading before checking social media.","zh":"學生可能先把一天的第一個小時用於閱讀，然後才查看社交媒體。"},{"en":"If people protect the first hour, they may finish important work before interruptions begin.","zh":"如果人們保護第一個小時，他們可能在干擾開始前完成重要工作。"},{"en":"This phrase describes deliberately setting aside focused time.","zh":"這個片語描述有意識地預留專注時間。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":11},{"front":"timing oneself","meaning":"為自己計時","examples":[{"en":"Timing oneself is a useful way to reduce distraction.","zh":"為自己計時是減少分心的有用方法。"},{"en":"Timing oneself means using a clock or timer to measure how long one works on a task.","zh":"timing oneself 指使用時鐘或計時器量度自己在某任務上工作多久。"},{"en":"A student may time themselves for twenty minutes to finish a reading exercise.","zh":"學生可能為自己計時二十分鐘，以完成一篇閱讀練習。"},{"en":"If people time themselves, they may notice how often they stop before the timer ends.","zh":"如果人們為自己計時，可能會注意到自己在計時結束前停下多少次。"},{"en":"This phrase describes a self-management method.","zh":"這個片語描述自我管理方法。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":11},{"front":"reduce distraction","meaning":"減少分心","examples":[{"en":"Timing oneself is a useful way to reduce distraction.","zh":"為自己計時是減少分心的有用方法。"},{"en":"To reduce distraction means to make interruptions or attention loss happen less often.","zh":"reduce distraction 指令干擾或注意力流失較少發生。"},{"en":"Turning off notifications can reduce distraction during study time.","zh":"關閉通知可以在溫習時間減少分心。"},{"en":"If distractions are reduced, people may work longer without losing focus.","zh":"如果分心減少，人們可能能更長時間工作而不失焦。"},{"en":"This phrase describes making attention easier to maintain.","zh":"這個片語描述令注意力更容易維持。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":11},{"front":"complete tasks efficiently","meaning":"高效完成任務","examples":[{"en":"People can complete tasks efficiently one by one.","zh":"人們可以逐一高效完成任務。"},{"en":"To complete tasks efficiently means to finish work with little wasted time, effort, or error.","zh":"complete tasks efficiently 指以很少浪費時間、精力或錯誤的方式完成工作。"},{"en":"A student can complete tasks efficiently by listing them and starting with the most important one.","zh":"學生可以列出任務並先做最重要的一項，以高效完成任務。"},{"en":"If people work carefully one task at a time, they may finish faster overall.","zh":"如果人們一次仔細處理一項任務，整體可能完成得更快。"},{"en":"This phrase focuses on both completion and good use of resources.","zh":"這個片語聚焦於完成任務以及良好使用資源。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":11},{"front":"one by one","meaning":"逐一","examples":[{"en":"People can complete tasks efficiently one by one.","zh":"人們可以逐一高效完成任務。"},{"en":"One by one means separately and in order, not all at the same time.","zh":"one by one 指分開並按次序進行，而不是同時全部處理。"},{"en":"A teacher may check students’ essays one by one to give careful feedback.","zh":"老師可能逐一檢查學生文章，以給予仔細回饋。"},{"en":"If tasks are done one by one, attention is less likely to be divided.","zh":"如果任務逐一完成，注意力較不容易被分散。"},{"en":"This phrase describes a step-by-step sequence.","zh":"這個片語描述一步一步的次序。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":11},{"front":"slow down through multitasking","meaning":"因一心多用而拖慢進度","examples":[{"en":"People may slow down through multitasking.","zh":"人們可能因一心多用而拖慢進度。"},{"en":"To slow down through multitasking means to become less quick because one is switching between tasks.","zh":"slow down through multitasking 指因在任務之間切換而變得較慢。"},{"en":"A student may slow down through multitasking if they answer messages while writing an essay.","zh":"如果學生一邊寫文章一邊回訊息，可能因一心多用而拖慢進度。"},{"en":"If every switch costs time, multitasking can make simple work take longer.","zh":"如果每次切換都花時間，一心多用可以令簡單工作花更久。"},{"en":"This phrase describes a hidden cost of doing many things at once.","zh":"這個片語描述同時做很多事的隱藏成本。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":11},{"front":"contains the following information","meaning":"包含以下資料","examples":[{"en":"The question asks which paragraph contains the following information.","zh":"題目問哪一段包含以下資料。"},{"en":"Contains the following information means includes the specific details listed in the question.","zh":"contains the following information 指包括題目列出的特定細節。"},{"en":"In a reading test, a paragraph may contain the information even if it uses different words.","zh":"在閱讀測驗中，即使段落使用不同字眼，也可能包含該資料。"},{"en":"If students search for meaning rather than only keywords, they can locate the answer more accurately.","zh":"如果學生搜尋意思而不只是關鍵字，就能更準確定位答案。"},{"en":"This phrase is a common instruction in information-matching questions.","zh":"這個片語是資訊配對題中的常見指示。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":11},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Students should write the correct letter on their answer sheet.","zh":"學生應在答題紙上寫上正確字母。"},{"en":"To write the correct letter means to record the letter that matches the right answer.","zh":"write the correct letter 指記下與正確答案相符的字母。"},{"en":"If paragraph C contains the answer, students should write C, not the whole paragraph.","zh":"如果 C 段包含答案，學生應寫 C，而不是整段內容。"},{"en":"If students understand the answer but write the wrong letter, they may lose marks.","zh":"如果學生理解答案但寫錯字母，可能會失分。"},{"en":"This phrase reminds candidates to follow the required answer format.","zh":"這個片語提醒考生遵守指定答案格式。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":11},{"front":"a domestic situation","meaning":"家居情境","examples":[{"en":"The question asks about a domestic situation that does not require multitasking.","zh":"題目問一個不需要一心多用的家居情境。"},{"en":"A domestic situation is a situation connected with home or family life.","zh":"domestic situation 是與家庭或家居生活有關的情況。"},{"en":"Cooking dinner while children do homework is a common domestic situation.","zh":"一邊煮晚餐一邊讓孩子做功課，是常見家居情境。"},{"en":"If a domestic situation is simple, it may not require dividing attention.","zh":"如果家居情境很簡單，它可能不需要分散注意力。"},{"en":"This phrase contrasts home settings with workplace or public settings.","zh":"這個片語把家庭環境與工作或公共環境作對比。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":11},{"front":"require multitasking","meaning":"需要一心多用","examples":[{"en":"A domestic situation may not require multitasking.","zh":"家居情境可能不需要一心多用。"},{"en":"To require multitasking means to need a person to handle several tasks at the same time.","zh":"require multitasking 指需要某人同時處理幾項任務。"},{"en":"Caring for a baby while cooking may require multitasking.","zh":"一邊煮飯一邊照顧嬰兒可能需要一心多用。"},{"en":"If a task can be done alone and quietly, it may not require multitasking.","zh":"如果任務可以單獨安靜完成，它可能不需要一心多用。"},{"en":"This phrase describes whether several demands must be managed together.","zh":"這個片語描述是否必須同時管理幾種需求。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":12},{"front":"a possible explanation for","meaning":"……的可能解釋","examples":[{"en":"The question asks for a possible explanation for why people multitask.","zh":"題目要求找出人們一心多用的可能解釋。"},{"en":"A possible explanation for something is a reason that may help account for it.","zh":"possible explanation for something 是可能有助解釋某事的原因。"},{"en":"A possible explanation for poor exam results may be lack of sleep, not lack of ability.","zh":"成績差的可能解釋可能是睡眠不足，而不是能力不足。"},{"en":"If people multitask often, one possible explanation is that devices are always nearby.","zh":"如果人們經常一心多用，一個可能解釋是裝置總在身邊。"},{"en":"This phrase introduces a suggested cause, not a certain answer.","zh":"這個片語引入建議原因，而不是確定答案。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":12},{"front":"manage multitasking at work","meaning":"在工作中管理一心多用","examples":[{"en":"The passage describes a practical method for managing multitasking at work.","zh":"文章描述一種在工作中管理一心多用的實際方法。"},{"en":"To manage multitasking at work means to control how and when several work tasks compete for attention.","zh":"manage multitasking at work 指控制幾項工作任務如何及何時爭奪注意力。"},{"en":"A worker may manage multitasking by checking email only at set times.","zh":"員工可以透過只在固定時間查看電郵，在工作中管理一心多用。"},{"en":"If multitasking is managed well, employees may feel less scattered and finish important work sooner.","zh":"如果一心多用管理得好，員工可能較不分散，並更快完成重要工作。"},{"en":"This phrase focuses on controlling workplace distraction rather than eliminating every task.","zh":"這個片語聚焦於控制職場分心，而不是消除每一項任務。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":12},{"front":"a connection between","meaning":"……之間的關聯","examples":[{"en":"The question asks about a connection between cortex size and multitasking.","zh":"題目問皮層大小與一心多用之間的關聯。"},{"en":"A connection between two things is a relationship or link between them.","zh":"connection between two things 指兩件事之間的關係或連繫。"},{"en":"A teacher may notice a connection between regular reading and better writing.","zh":"老師可能注意到定期閱讀與較好寫作之間的關聯。"},{"en":"If brain structure and multitasking ability are connected, one may help explain the other.","zh":"如果腦部結構與一心多用能力有關，其中一方可能有助解釋另一方。"},{"en":"This phrase asks how two things may be related.","zh":"這個片語詢問兩件事可能如何相關。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":12},{"front":"prefrontal-cortex size","meaning":"前額葉皮層大小","examples":[{"en":"The question mentions prefrontal-cortex size and multitasking.","zh":"題目提到前額葉皮層大小與一心多用。"},{"en":"Prefrontal-cortex size means how large the prefrontal cortex is.","zh":"prefrontal-cortex size 指前額葉皮層有多大。"},{"en":"Scientists may compare prefrontal-cortex size across species to study attention control.","zh":"科學家可能比較不同物種的前額葉皮層大小，以研究注意力控制。"},{"en":"If this brain region is larger, it may support more flexible planning and task management.","zh":"如果這個腦區較大，它可能支援更靈活的計劃和任務管理。"},{"en":"This phrase connects a brain measurement with behaviour.","zh":"這個片語把腦部量度與行為連接起來。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":12},{"front":"evidence that","meaning":"證明……的證據","examples":[{"en":"The passage provides evidence that doing two tasks together takes longer.","zh":"文章提供證明同時做兩項任務需時更長的證據。"},{"en":"Evidence that means information or results showing that something is likely true.","zh":"evidence that 指顯示某事很可能屬實的資料或結果。"},{"en":"A teacher may use test scores as evidence that extra practice helped the class.","zh":"老師可能使用測驗分數作為額外練習幫助全班的證據。"},{"en":"If experiments show slower completion times, they provide evidence against efficient multitasking.","zh":"如果實驗顯示完成時間較慢，它們就提供反對高效一心多用的證據。"},{"en":"This phrase introduces proof or support for a claim.","zh":"這個片語引入支持某主張的證據。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":12},{"front":"doing two tasks together","meaning":"同時做兩項任務","examples":[{"en":"Doing two tasks together can take longer than doing them separately.","zh":"同時做兩項任務可能比分開做更花時間。"},{"en":"Doing two tasks together means working on two activities during the same period.","zh":"doing two tasks together 指在同一段時間處理兩項活動。"},{"en":"A student may try doing two tasks together by memorising words while watching a video.","zh":"學生可能一邊看影片一邊背詞，嘗試同時做兩項任務。"},{"en":"If both tasks require concentration, doing them together may slow the student down.","zh":"如果兩項任務都需要專注，同時做它們可能令學生變慢。"},{"en":"This phrase describes multitasking in simple terms.","zh":"這個片語用簡單方式描述一心多用。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":12},{"front":"doing them separately","meaning":"分開做","examples":[{"en":"Doing two tasks together can take longer than doing them separately.","zh":"同時做兩項任務可能比分開做更花時間。"},{"en":"Doing them separately means completing each task one after another instead of at the same time.","zh":"doing them separately 指一項接一項完成任務，而不是同時處理。"},{"en":"A student may finish reading first and then reply to messages, doing the tasks separately.","zh":"學生可能先完成閱讀，再回覆訊息，把任務分開做。"},{"en":"If tasks are done separately, the brain does not need to switch attention as often.","zh":"如果任務分開做，大腦就不需要那麼頻繁切換注意力。"},{"en":"This phrase contrasts sequential work with multitasking.","zh":"這個片語把順序工作與一心多用作對比。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":12},{"front":"match each statement with","meaning":"將每項陳述與……配對","examples":[{"en":"Students match each statement with the correct scientist.","zh":"學生將每項陳述與正確的科學家配對。"},{"en":"To match each statement with something means to connect every statement to the correct answer choice.","zh":"match each statement with something 指把每項陳述連接到正確答案選項。"},{"en":"In a reading exercise, students may match each statement with the paragraph that supports it.","zh":"在閱讀練習中，學生可能把每項陳述與支持它的段落配對。"},{"en":"If two scientists have similar ideas, students must read carefully before matching.","zh":"如果兩位科學家的想法相似，學生配對前必須仔細閱讀。"},{"en":"This phrase is common in matching questions.","zh":"這個片語常見於配對題。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":12},{"front":"the correct scientist","meaning":"正確的科學家","examples":[{"en":"Students match each statement with the correct scientist.","zh":"學生將每項陳述與正確的科學家配對。"},{"en":"The correct scientist is the researcher whose view, experiment, or finding matches the statement.","zh":"correct scientist 是其看法、實驗或發現與陳述相符的研究人員。"},{"en":"If a statement mentions office interruptions, students should choose the scientist who studied office workers.","zh":"如果陳述提到辦公室干擾，學生應選研究辦公室員工的科學家。"},{"en":"Choosing the correct scientist requires matching ideas, not just names.","zh":"選出正確科學家需要配對想法，而不只是名字。"},{"en":"This phrase refers to the right person among several researchers.","zh":"這個片語指幾位研究人員中的正確人物。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":12},{"front":"may use any letter more than once","meaning":"可以使用任何字母多於一次","examples":[{"en":"Students may use any letter more than once.","zh":"學生可以使用任何字母多於一次。"},{"en":"May use any letter more than once means the same answer option can be repeated.","zh":"may use any letter more than once 指同一答案選項可以重複使用。"},{"en":"In matching questions, paragraph B may answer two different statements.","zh":"在配對題中，B 段可能回答兩項不同陳述。"},{"en":"If students wrongly assume each letter is used only once, they may reject the right answer.","zh":"如果學生錯誤假設每個字母只能使用一次，可能排除正確答案。"},{"en":"This instruction prevents unnecessary elimination of options.","zh":"這個指示防止不必要地排除選項。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":12},{"front":"when faced with","meaning":"面對……時","examples":[{"en":"When faced with several visual stimuli, a person can concentrate on only one.","zh":"面對幾個視覺刺激時，一個人只能專注於其中一個。"},{"en":"When faced with something means when someone has to deal with that situation.","zh":"when faced with something 指當某人必須處理某情況時。"},{"en":"When faced with a difficult question, a student should underline the keywords first.","zh":"面對困難問題時，學生應先劃下關鍵字。"},{"en":"If the brain is faced with several signals at once, it may select only one to process deeply.","zh":"如果大腦同時面對幾個訊號，它可能只選一個深入處理。"},{"en":"This phrase introduces a situation or challenge.","zh":"這個片語引入情況或挑戰。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":13},{"front":"faster but less effective","meaning":"較快但效果較差","examples":[{"en":"Doing two things together may be faster but less effective.","zh":"同時做兩件事可能較快但效果較差。"},{"en":"Faster but less effective means quicker in appearance but producing poorer results.","zh":"faster but less effective 指表面上較快，但產生較差結果。"},{"en":"A student may finish homework faster but less effectively if they copy answers without understanding.","zh":"如果學生不理解便抄答案，可能較快完成功課但效果較差。"},{"en":"If multitasking saves a little time but increases mistakes, the overall result may be worse.","zh":"如果一心多用節省少量時間卻增加錯誤，整體結果可能更差。"},{"en":"This phrase contrasts speed with quality.","zh":"這個片語對比速度與質素。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":13},{"front":"causes of multitasking","meaning":"一心多用的成因","examples":[{"en":"The causes of multitasking may lie in the environment.","zh":"一心多用的成因可能在於環境。"},{"en":"Causes of multitasking are the reasons people start switching between tasks.","zh":"causes of multitasking 是人們開始在任務之間切換的原因。"},{"en":"Phone alerts, open office noise, and easy Internet access can be causes of multitasking.","zh":"手機提示、開放式辦公室噪音和容易上網都可以是一心多用的成因。"},{"en":"If the causes are environmental, changing the environment may improve focus.","zh":"如果成因在環境，改變環境可能改善專注。"},{"en":"This phrase asks why multitasking happens.","zh":"這個片語詢問一心多用為何發生。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":13},{"front":"lie in the environment","meaning":"在於環境","examples":[{"en":"The causes of multitasking may lie in the environment.","zh":"一心多用的成因可能在於環境。"},{"en":"To lie in the environment means to be found in the surrounding conditions rather than inside one person alone.","zh":"lie in the environment 指原因存在於周圍條件中，而不只是在某個人內在。"},{"en":"A student’s distraction may lie in the environment if the study room is noisy and full of devices.","zh":"如果溫習室嘈吵又充滿裝置，學生分心的原因可能在於環境。"},{"en":"If the problem lies in the environment, personal willpower may not be enough.","zh":"如果問題在於環境，單靠個人意志力可能不足夠。"},{"en":"This phrase identifies the source of a problem as the surroundings.","zh":"這個片語指出問題來源是周圍環境。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":13},{"front":"small workplace changes","meaning":"工作場所的小改變","examples":[{"en":"Small workplace changes can improve efficiency.","zh":"工作場所的小改變可以提高效率。"},{"en":"Small workplace changes are minor adjustments to routines, rules, layout, or communication at work.","zh":"small workplace changes 是對工作中的習慣、規則、布局或溝通作出的細小調整。"},{"en":"A company may make small workplace changes by creating quiet hours for focused work.","zh":"公司可以透過設立安靜工作時段來作出工作場所的小改變。"},{"en":"If small changes reduce interruptions, workers may complete important tasks faster.","zh":"如果小改變減少干擾，員工可能更快完成重要任務。"},{"en":"This phrase shows that improvement does not always require major reform.","zh":"這個片語顯示改善不一定需要重大改革。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":13},{"front":"improve efficiency","meaning":"提高效率","examples":[{"en":"Small workplace changes can improve efficiency.","zh":"工作場所的小改變可以提高效率。"},{"en":"To improve efficiency means to make work faster, smoother, or less wasteful.","zh":"improve efficiency 指令工作更快、更順暢或較少浪費。"},{"en":"A student can improve efficiency by preparing books and stationery before studying.","zh":"學生可以在溫習前準備好書本和文具，以提高效率。"},{"en":"If meetings have clear rules and fewer distractions, they may finish sooner.","zh":"如果會議有清楚規則和較少干擾，可能更快完成。"},{"en":"This phrase focuses on better use of time and effort.","zh":"這個片語聚焦於更好使用時間和精力。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":13},{"front":"complete the sentences below","meaning":"完成以下句子","examples":[{"en":"Students complete the sentences below using words from the passage.","zh":"學生使用篇章中的字詞完成以下句子。"},{"en":"Complete the sentences below means fill in the missing words in the following sentences.","zh":"complete the sentences below 指填寫下面句子中缺少的字詞。"},{"en":"In reading exams, students should complete the sentences below with exact words from the text if required.","zh":"在閱讀考試中，如果題目要求，學生應用文本中的確切字詞完成以下句子。"},{"en":"If the grammar does not fit, the chosen answer may be wrong even if the idea is close.","zh":"如果文法不合適，即使意思接近，所選答案也可能錯。"},{"en":"This phrase is a common completion-task instruction.","zh":"這個片語是常見填充題指示。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":13},{"front":"choose no more than two words","meaning":"選擇不多於兩個詞","examples":[{"en":"Students choose no more than two words from the passage.","zh":"學生從篇章中選擇不多於兩個詞。"},{"en":"Choose no more than two words means the answer must contain one or two words only.","zh":"choose no more than two words 指答案只能包含一個或兩個英文詞。"},{"en":"If the correct answer is “email voice”, writing “the email voice” may exceed the limit.","zh":"如果正確答案是 “email voice”，寫 “the email voice” 可能超出限制。"},{"en":"Students should count words carefully before writing the answer.","zh":"學生寫答案前應仔細數字數。"},{"en":"This phrase sets a strict word limit.","zh":"這個片語設定嚴格字數限制。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":13},{"front":"the term for","meaning":"……的術語","examples":[{"en":"The question asks for the term for this situation.","zh":"題目問這種情況的術語。"},{"en":"The term for something means the word or phrase used to name it.","zh":"term for something 指用來命名某事物的詞或片語。"},{"en":"The term for learning at home through online lessons is distance learning.","zh":"透過網課在家學習的術語是 distance learning。"},{"en":"If students know the term, they can answer the question with the exact wording.","zh":"如果學生知道該術語，就能用確切措辭回答問題。"},{"en":"This phrase asks for a name, not a long explanation.","zh":"這個片語要求名稱，而不是長篇解釋。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":13},{"front":"a situation in which","meaning":"一種……的情況","examples":[{"en":"The term describes a situation in which someone cannot focus on their surroundings.","zh":"這個術語描述一種某人無法留意身邊環境的情況。"},{"en":"A situation in which means a case or condition where something happens.","zh":"situation in which 指某事發生的個案或條件。"},{"en":"A teacher may describe a situation in which students cannot hear instructions because the room is noisy.","zh":"老師可能描述一種學生因課室嘈吵而聽不到指示的情況。"},{"en":"If a question uses this phrase, students should identify the exact condition being described.","zh":"如果題目使用這個片語，學生應識別正在描述的確切條件。"},{"en":"This phrase introduces a specific type of situation.","zh":"這個片語引入特定類型的情況。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":13},{"front":"focus on their surroundings","meaning":"留意身邊環境","examples":[{"en":"A distracted person cannot focus on their surroundings.","zh":"分心的人無法留意身邊環境。"},{"en":"To focus on their surroundings means to pay attention to what is happening nearby.","zh":"focus on their surroundings 指留意附近正在發生的事情。"},{"en":"A pedestrian should focus on their surroundings before crossing a road.","zh":"行人過馬路前應留意身邊環境。"},{"en":"If someone is absorbed in a phone, they may not hear a friend speaking beside them.","zh":"如果某人沉浸在手機中，可能聽不到旁邊朋友說話。"},{"en":"This phrase describes awareness of the immediate environment.","zh":"這個片語描述對周圍即時環境的察覺。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":13},{"front":"one practical way to","meaning":"……的一個實際方法","examples":[{"en":"One practical way to reduce multitasking is to prohibit mobile phones.","zh":"減少一心多用的一個實際方法是禁止使用手機。"},{"en":"One practical way to do something means one realistic method that can help achieve it.","zh":"one practical way to do something 指一個能幫助達成某事的現實方法。"},{"en":"One practical way to improve vocabulary is to review five useful phrases every day.","zh":"改善詞彙的一個實際方法是每天複習五個有用片語。"},{"en":"If a solution is practical, people can actually use it in daily life or work.","zh":"如果解決方法實際，人們可以真正在日常生活或工作中使用它。"},{"en":"This phrase introduces a realistic action rather than only an idea.","zh":"這個片語引入現實行動，而不只是想法。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":14},{"front":"prohibit mobile phones during","meaning":"在……期間禁止使用手機","examples":[{"en":"One practical way to reduce multitasking is to prohibit mobile phones during group meetings.","zh":"減少一心多用的一個實際方法是在小組會議期間禁止使用手機。"},{"en":"To prohibit mobile phones during something means to ban phone use while that activity is happening.","zh":"prohibit mobile phones during something 指在某活動進行期間禁止使用手機。"},{"en":"A school may prohibit mobile phones during exams to prevent cheating and distraction.","zh":"學校可能在考試期間禁止使用手機，以防止作弊和分心。"},{"en":"If phones are prohibited during meetings, participants may listen and contribute more fully.","zh":"如果會議期間禁止使用手機，參加者可能更充分地聆聽和貢獻。"},{"en":"This phrase describes a rule limiting phone use in a specific situation.","zh":"這個片語描述在特定情況中限制手機使用的規則。"}],"source":"48 - How Well Do We Concentrate?.pdf","sourcePage":14}],"ielts/reading/passage-2/Practice 49":[{"front":"shortly before his death","meaning":"在他去世前不久","examples":[{"en":"Shortly before his death, Marlon Brando was working on instructional videos about acting.","zh":"在他去世前不久，馬龍白蘭度正在製作關於演技的教學影片。"},{"en":"Shortly before his death means a short time before someone died.","zh":"shortly before his death 指某人去世前的一小段時間。"},{"en":"Shortly before his death, the old teacher wrote letters to his former students.","zh":"在那位老教師去世前不久，他寫信給以前的學生。"},{"en":"Important words spoken shortly before a person’s death may later be remembered carefully.","zh":"一個人在去世前不久說的重要說話，後來可能被仔細記住。"},{"en":"This phrase is used when the timing is close to the end of someone’s life.","zh":"這個短語用於表示時間接近某人生命的終點。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":1},{"front":"a series of","meaning":"一系列","examples":[{"en":"Brando was working on a series of instructional videos about acting.","zh":"白蘭度正在製作一系列關於演技的教學影片。"},{"en":"A series of things means several connected things of the same kind.","zh":"a series of things 指幾個同類而互相關連的事物。"},{"en":"A teacher may prepare a series of lessons before an exam.","zh":"老師可能在考試前準備一系列課堂。"},{"en":"A series of small mistakes can lead to one big problem.","zh":"一系列小錯誤可以導致一個大問題。"},{"en":"This phrase is useful when events, videos, books, or actions come one after another.","zh":"這個短語適合用於事件、影片、書籍或行動一個接一個出現時。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":1},{"front":"instructional videos","meaning":"教學影片","examples":[{"en":"Marlon Brando made instructional videos about the craft of acting.","zh":"馬龍白蘭度製作了關於演技的教學影片。"},{"en":"Instructional videos are videos that teach people how to do something.","zh":"instructional videos 是教人如何做某事的影片。"},{"en":"Students may watch instructional videos to learn how to solve maths problems.","zh":"學生可能觀看教學影片來學習如何解數學題。"},{"en":"Good instructional videos break difficult skills into clear steps.","zh":"好的教學影片會把困難技能拆成清楚步驟。"},{"en":"Watching instructional videos is helpful, but learners still need practice.","zh":"觀看教學影片有幫助，但學習者仍需要練習。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":1},{"front":"Lying for a Living","meaning":"以說謊謀生","examples":[{"en":"Brando called his acting videos Lying for a Living.","zh":"白蘭度把他的演技影片稱為《以說謊謀生》。"},{"en":"Lying for a Living is a title suggesting that actors make a career from pretending.","zh":"Lying for a Living 這個標題暗示演員以假裝作為職業。"},{"en":"A comedian might jokingly call advertising “selling dreams for a living”.","zh":"喜劇演員可能開玩笑把廣告稱為「以出售夢想謀生」。"},{"en":"The title works because acting involves saying things that are not literally true.","zh":"這個標題有效，是因為演戲涉及說出不完全真實的話。"},{"en":"This phrase sounds humorous because it connects performance with dishonesty.","zh":"這個短語帶幽默感，因為它把表演與不誠實連在一起。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":1},{"front":"surviving footage","meaning":"保存下來的片段","examples":[{"en":"In the surviving footage, Brando gives advice to Hollywood stars.","zh":"在保存下來的片段中，白蘭度向荷里活明星提供建議。"},{"en":"Surviving footage means film or video material that still exists after time has passed.","zh":"surviving footage 指經過時間後仍然存在的電影或影片材料。"},{"en":"A museum may show surviving footage of an old city before it was rebuilt.","zh":"博物館可能播放一座舊城市重建前保存下來的片段。"},{"en":"Surviving footage can become valuable when most recordings from that period have been lost.","zh":"當某時期大部分錄像已遺失，保存下來的片段會變得很有價值。"},{"en":"This phrase is often used for old recordings that have been preserved.","zh":"這個短語常用於仍被保存的舊錄像。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":1},{"front":"can be seen doing something","meaning":"可見某人正在做某事","examples":[{"en":"Brando can be seen dispensing advice about acting.","zh":"片中可見白蘭度正在提供關於演技的建議。"},{"en":"Can be seen doing something means someone is visible in a photo or video while doing that action.","zh":"can be seen doing something 指在照片或影片中可見某人正在做該動作。"},{"en":"In the video, the teacher can be seen helping a student with pronunciation.","zh":"在影片中，可見老師正在幫學生改善發音。"},{"en":"If a person can be seen breaking a rule on camera, the evidence becomes harder to deny.","zh":"如果鏡頭可見某人正在違反規則，證據就較難否認。"},{"en":"This phrase is common when describing what appears in footage.","zh":"這個短語常用於描述影片中出現的畫面。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":1},{"front":"dispense advice","meaning":"提供意見；給予建議","examples":[{"en":"Brando dispensed advice about his craft to a group of actors.","zh":"白蘭度向一群演員提供關於自己技藝的建議。"},{"en":"To dispense advice means to give advice, often in a confident or experienced way.","zh":"dispense advice 指給予建議，通常帶有自信或經驗。"},{"en":"A senior nurse may dispense advice to new staff on how to speak to patients.","zh":"資深護士可能向新員工提供如何與病人說話的建議。"},{"en":"Good advice can help beginners avoid mistakes before they happen.","zh":"好建議可以幫助初學者在錯誤發生前避免它。"},{"en":"This phrase can sound slightly formal or slightly humorous, depending on context.","zh":"這個短語視乎語境，可以聽起來稍正式或稍帶幽默。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":1},{"front":"gnomic advice","meaning":"深奧難明的建議","examples":[{"en":"Brando gave gnomic advice about his craft to other actors.","zh":"白蘭度向其他演員給出關於其技藝的深奧難明建議。"},{"en":"Gnomic advice is short, mysterious advice that sounds wise but may be hard to understand.","zh":"gnomic advice 是簡短、神秘、聽起來有智慧但可能難明的建議。"},{"en":"A coach might give gnomic advice like “trust the silence” before a performance.","zh":"教練在表演前可能給出「相信沉默」這類深奧難明的建議。"},{"en":"Gnomic advice can inspire people, but it may also confuse beginners.","zh":"深奧難明的建議可以啟發人，但也可能令初學者困惑。"},{"en":"This phrase is used when advice sounds deep but not fully clear.","zh":"這個短語用於形容聽起來深刻但不完全清楚的建議。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":1},{"front":"his craft","meaning":"他的技藝；他的專業","examples":[{"en":"Brando spoke about his craft to a group of Hollywood stars.","zh":"白蘭度向一群荷里活明星談論他的技藝。"},{"en":"His craft means his skill, art, or professional practice.","zh":"his craft 指他的技能、藝術或專業實踐。"},{"en":"A chef improves his craft by testing ingredients and learning from mistakes.","zh":"廚師透過測試食材和從錯誤中學習來改善自己的技藝。"},{"en":"Someone who respects his craft keeps practising even after becoming successful.","zh":"尊重自己專業的人即使成功後仍會繼續練習。"},{"en":"This phrase is often used for skilled work such as acting, writing, music, or design.","zh":"這個短語常用於演戲、寫作、音樂或設計等技術性工作。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":1},{"front":"enthusiastic, if somewhat bemused","meaning":"熱情投入，雖然有點困惑","examples":[{"en":"The actors were enthusiastic, if somewhat bemused, by Brando’s advice.","zh":"演員們對白蘭度的建議熱情投入，雖然有點困惑。"},{"en":"Enthusiastic, if somewhat bemused means interested and excited, although a little confused.","zh":"enthusiastic, if somewhat bemused 指感興趣而興奮，但有點不明所以。"},{"en":"Students may be enthusiastic, if somewhat bemused, when a teacher uses a strange new game.","zh":"當老師使用奇怪的新遊戲時，學生可能熱情投入，雖然有點困惑。"},{"en":"Unusual advice can make people eager to listen but unsure what it really means.","zh":"不尋常的建議可以令人想聽下去，但不確定真正意思。"},{"en":"This phrase shows a mixed reaction: positive energy with some confusion.","zh":"這個短語顯示混合反應：正面投入但帶點困惑。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":1},{"front":"Hollywood stars","meaning":"荷里活明星","examples":[{"en":"The footage shows Brando speaking to several Hollywood stars.","zh":"片段顯示白蘭度正在與幾位荷里活明星說話。"},{"en":"Hollywood stars are famous actors or actresses associated with the American film industry.","zh":"Hollywood stars 指與美國電影業相關的著名男女演員。"},{"en":"Hollywood stars often appear at film premieres, interviews, and award ceremonies.","zh":"荷里活明星常出現在電影首映、訪問和頒獎禮上。"},{"en":"When Hollywood stars support a project, it may attract more public attention.","zh":"當荷里活明星支持某個項目時，它可能吸引更多公眾注意。"},{"en":"This phrase suggests celebrity, fame, and mainstream cinema.","zh":"這個短語暗示名人、聲望和主流電影。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":2},{"front":"recruit people at random","meaning":"隨機招募人","examples":[{"en":"Brando recruited people at random from the streets of Los Angeles.","zh":"白蘭度從洛杉磯街頭隨機招募人。"},{"en":"To recruit people at random means to choose people without a fixed plan or careful selection.","zh":"recruit people at random 指沒有固定計劃或仔細篩選地選人。"},{"en":"A survey team may recruit people at random outside a train station.","zh":"調查隊可能在火車站外隨機招募路人。"},{"en":"Random recruitment can make results more varied, but it may also be harder to control.","zh":"隨機招募可以令結果更多樣，但也可能較難控制。"},{"en":"This phrase shows that people were chosen unexpectedly rather than professionally selected.","zh":"這個短語顯示人是意外地被選中，而不是經專業挑選。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":2},{"front":"from the streets of","meaning":"從……的街頭","examples":[{"en":"Brando recruited people from the streets of Los Angeles.","zh":"白蘭度從洛杉磯的街頭招募人。"},{"en":"From the streets of a place means from ordinary public areas in that city or neighbourhood.","zh":"from the streets of 某地，意思是從該城市或社區的普通公共地方。"},{"en":"A photographer may capture daily life from the streets of Hong Kong.","zh":"攝影師可能捕捉香港街頭的日常生活。"},{"en":"Recruiting people from the streets can bring in ordinary voices rather than trained professionals.","zh":"從街頭招募人可以帶來普通人的聲音，而不是受過訓練的專業人士。"},{"en":"This phrase often creates a sense of real city life.","zh":"這個短語常營造真實城市生活的感覺。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":2},{"front":"persuade someone to","meaning":"說服某人去","examples":[{"en":"Brando persuaded strangers to improvise in front of the camera.","zh":"白蘭度說服陌生人在鏡頭前即興表演。"},{"en":"To persuade someone to do something means to convince them to do it.","zh":"persuade someone to do something 指說服某人去做某事。"},{"en":"A teacher may persuade shy students to speak by giving them simple questions first.","zh":"老師可能先給害羞學生簡單問題，說服他們開口說話。"},{"en":"People are easier to persuade when they trust the person asking them.","zh":"當人們信任提出要求的人時，他們較容易被說服。"},{"en":"This phrase involves changing someone’s willingness through words or encouragement.","zh":"這個短語涉及透過說話或鼓勵改變某人的意願。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":2},{"front":"improvise","meaning":"即興表演","examples":[{"en":"Brando persuaded people to improvise during the filming.","zh":"白蘭度說服人們在拍攝期間即興表演。"},{"en":"To improvise means to perform, speak, or act without a fixed script or full preparation.","zh":"improvise 指在沒有固定劇本或完整準備下表演、說話或行動。"},{"en":"A student may improvise an answer when the teacher asks an unexpected question.","zh":"當老師問意想不到的問題時，學生可能即興作答。"},{"en":"Actors improvise well when they listen carefully and respond naturally.","zh":"演員若能仔細聆聽並自然回應，就能即興表演得好。"},{"en":"Improvising can be creative, but it also requires confidence and quick thinking.","zh":"即興可以很有創意，但也需要自信和快速思考。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":2},{"front":"be said to include","meaning":"據說包括","examples":[{"en":"The footage is said to include a memorable improvised scene.","zh":"據說該片段包括一場令人難忘的即興場面。"},{"en":"Be said to include means people report or believe that something contains a particular part.","zh":"be said to include 指據報或據信某物包含某部分。"},{"en":"The new course is said to include writing practice, speaking drills, and mock exams.","zh":"據說新課程包括寫作練習、說話操練和模擬考試。"},{"en":"This phrase is useful when the writer does not directly confirm every detail.","zh":"當作者沒有直接確認每個細節時，這個短語很有用。"},{"en":"It often introduces information based on reports rather than personal observation.","zh":"它常用來引出基於報道而非親身觀察的資訊。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":2},{"front":"a memorable scene","meaning":"令人難忘的一幕","examples":[{"en":"The footage includes a memorable scene with unusual performers.","zh":"該片段包括一幕由不尋常表演者演出的令人難忘場面。"},{"en":"A memorable scene is a part of a film, play, or event that people easily remember.","zh":"a memorable scene 指電影、劇場或事件中令人容易記住的一部分。"},{"en":"A graduation ceremony may have a memorable scene when all students sing together.","zh":"畢業禮上所有學生一起唱歌時，可能出現令人難忘的一幕。"},{"en":"Strong emotion, surprise, or humour can make a scene memorable.","zh":"強烈情感、驚喜或幽默可以令一幕變得難忘。"},{"en":"This phrase is used for moments that stay in people’s minds.","zh":"這個短語用於留在人們腦海中的時刻。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":2},{"front":"feature","meaning":"以……為特色；由……演出","examples":[{"en":"The scene features several people improvising together.","zh":"這一幕由幾個人一起即興演出。"},{"en":"To feature someone or something means to include them as an important part.","zh":"feature 某人或某物，意思是把其作為重要部分包括在內。"},{"en":"The school concert featured students from every year group.","zh":"學校音樂會由每個年級的學生演出。"},{"en":"A film that features local streets can feel more realistic to local viewers.","zh":"一部以本地街道為特色的電影，對本地觀眾來說可能更真實。"},{"en":"This verb is useful when describing what appears prominently in a show, article, or event.","zh":"這個動詞適合描述節目、文章或活動中突出出現的內容。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":2},{"front":"If you can…, you can…","meaning":"如果你能……，你就能……","examples":[{"en":"If you can lie, you can act.","zh":"如果你能說謊，你就能演戲。"},{"en":"If you can…, you can… is a pattern showing that one ability makes another ability possible.","zh":"If you can…, you can… 是表示一種能力令另一種能力成為可能的句式。"},{"en":"If you can explain an idea simply, you can teach it more effectively.","zh":"如果你能簡單解釋一個概念，你就能更有效地教它。"},{"en":"If you can stay calm under pressure, you can handle difficult interviews.","zh":"如果你能在壓力下保持冷靜，你就能應付困難面試。"},{"en":"This structure links a basic skill to a larger skill.","zh":"這個句式把基本技能連接到更大的能力。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":2},{"front":"be good at lying","meaning":"擅長說謊","examples":[{"en":"Brando claimed that he was good at lying.","zh":"白蘭度聲稱自己擅長說謊。"},{"en":"To be good at lying means to be skilled at saying untrue things convincingly.","zh":"be good at lying 指擅長令人信服地說出不真實的話。"},{"en":"A child who hides broken toys may become good at lying to avoid punishment.","zh":"一個為逃避懲罰而隱瞞壞玩具的孩子，可能變得擅長說謊。"},{"en":"Being good at lying can damage trust when people discover the truth.","zh":"擅長說謊一旦被人發現真相，會破壞信任。"},{"en":"This phrase describes skill in deception, not moral goodness.","zh":"這個短語描述欺騙技巧，而不是道德上的好。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":2},{"front":"be fabulous at","meaning":"非常擅長","examples":[{"en":"Brando said that he was fabulous at lying.","zh":"白蘭度說自己非常擅長說謊。"},{"en":"To be fabulous at something means to be extremely good at it.","zh":"be fabulous at something 指在某事上極其出色。"},{"en":"My grandmother is fabulous at making simple food taste special.","zh":"我的祖母非常擅長把簡單食物做得特別好吃。"},{"en":"Someone who is fabulous at public speaking can make difficult ideas feel clear.","zh":"非常擅長公開演說的人，可以令困難概念變得清楚。"},{"en":"This phrase is informal and enthusiastic.","zh":"這個短語較口語，語氣熱情。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":3},{"front":"observe that","meaning":"觀察到；指出","examples":[{"en":"Brando was not the first person to observe that artists and liars are closely connected.","zh":"白蘭度不是第一個指出藝術家與說謊者關係密切的人。"},{"en":"To observe that means to notice and point out something.","zh":"observe that 指注意到並指出某事。"},{"en":"A teacher may observe that students write better when they plan first.","zh":"老師可能觀察到學生先規劃時寫作較好。"},{"en":"When people observe a pattern, they may begin to form an argument.","zh":"當人們觀察到一個模式時，可能開始形成論點。"},{"en":"This phrase is often used when someone makes a thoughtful comment about reality.","zh":"這個短語常用於某人對現實作出有思考的評論時。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":3},{"front":"the line between…and…","meaning":"……與……之間的界線","examples":[{"en":"The line between an artist and a liar is a fine one.","zh":"藝術家與說謊者之間的界線很微妙。"},{"en":"The line between two things is the boundary or difference that separates them.","zh":"the line between two things 指分隔兩者的界線或差異。"},{"en":"The line between confidence and arrogance can be difficult to judge.","zh":"自信與自大之間的界線可能很難判斷。"},{"en":"If the line between work and rest disappears, people may feel constantly tired.","zh":"如果工作與休息之間的界線消失，人們可能長期感到疲累。"},{"en":"This phrase is useful when two things are similar but not exactly the same.","zh":"當兩件事相似但不完全相同時，這個短語很有用。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":3},{"front":"a fine line","meaning":"微妙的界線","examples":[{"en":"There is a fine line between artistic storytelling and lying.","zh":"藝術性的敘事與說謊之間有一條微妙的界線。"},{"en":"A fine line is a very small or subtle difference between two things.","zh":"a fine line 指兩件事之間非常細微或微妙的差別。"},{"en":"There is a fine line between helping a student and doing the work for them.","zh":"幫助學生與替學生完成作業之間有一條微妙界線。"},{"en":"When a fine line is crossed, acceptable behaviour may become dishonest or harmful.","zh":"當微妙界線被越過時，可接受行為可能變成不誠實或有害。"},{"en":"This phrase warns that two things may be easy to confuse.","zh":"這個短語提醒兩件事可能容易混淆。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":3},{"front":"a kind of","meaning":"一種","examples":[{"en":"The writer suggests that art may be a kind of lying.","zh":"作者暗示藝術可能是一種說謊。"},{"en":"A kind of something means one type or form of it.","zh":"a kind of something 指某事物的一種類型或形式。"},{"en":"A diary can be a kind of conversation with oneself.","zh":"日記可以是一種與自己的對話。"},{"en":"Calling something a kind of something else helps readers see a connection between them.","zh":"把某物稱為另一事物的一種，可以幫助讀者看見兩者關係。"},{"en":"This phrase is useful when making a comparison that is not exact but meaningful.","zh":"這個短語適合用於作出不完全相同但有意義的比較。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":3},{"front":"a form of art","meaning":"一種藝術形式","examples":[{"en":"Lying can be seen as a form of art, though of a lower order.","zh":"說謊可被視為一種藝術形式，雖然層次較低。"},{"en":"A form of art is a way of creating expression, beauty, meaning, or performance.","zh":"a form of art 指創造表達、美感、意義或表演的一種方式。"},{"en":"Dance is a form of art that uses movement instead of words.","zh":"舞蹈是一種使用動作而不是文字的藝術形式。"},{"en":"When an activity becomes expressive and carefully shaped, people may call it a form of art.","zh":"當一項活動變得有表達性並經過精心塑造，人們可能稱它為一種藝術形式。"},{"en":"This phrase can be serious or playful depending on context.","zh":"這個短語視乎語境，可以嚴肅，也可以帶玩笑意味。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":3},{"front":"albeit","meaning":"雖然；儘管","examples":[{"en":"Lying is a form of art, albeit of a lower order.","zh":"說謊是一種藝術形式，雖然層次較低。"},{"en":"Albeit means although or even though.","zh":"albeit 意思是 although 或 even though。"},{"en":"The plan is useful, albeit expensive.","zh":"這個計劃有用，雖然昂貴。"},{"en":"A student may improve, albeit slowly, after weeks of practice.","zh":"經過數星期練習後，學生可能會進步，雖然速度很慢。"},{"en":"This word is formal and introduces a contrast or limitation.","zh":"這個字較正式，用來引出對比或限制。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":3},{"front":"of a lower order","meaning":"較低層次的","examples":[{"en":"Lying may be an art form, but it is of a lower order.","zh":"說謊可能是一種藝術形式，但它屬於較低層次。"},{"en":"Of a lower order means less valuable, less noble, or less developed than another kind.","zh":"of a lower order 指比另一類較不珍貴、較不高尚或較不成熟。"},{"en":"A quick excuse may be a form of explanation, but it is of a lower order than an honest apology.","zh":"匆忙藉口可能是一種解釋，但比真誠道歉層次較低。"},{"en":"When something is of a lower order, it may share features with something better but lack its depth.","zh":"較低層次的東西可能與更好的東西有共同特徵，但缺乏深度。"},{"en":"This phrase often suggests a hierarchy of quality or moral value.","zh":"這個短語常暗示質素或道德價值上的層級。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":3},{"front":"artistic storytelling","meaning":"藝術性的敘事","examples":[{"en":"Artistic storytelling and lying may come from the same mental source.","zh":"藝術性的敘事與說謊可能來自同一心理來源。"},{"en":"Artistic storytelling is the creative use of stories to express meaning, emotion, or truth.","zh":"artistic storytelling 指以創意故事表達意義、情感或真相。"},{"en":"A film uses artistic storytelling when it shows grief through images rather than direct explanation.","zh":"電影透過畫面而不是直接解釋來呈現悲傷時，就是在使用藝術性的敘事。"},{"en":"Artistic storytelling can help people understand feelings that facts alone cannot explain.","zh":"藝術性的敘事可以幫助人理解單靠事實無法解釋的情感。"},{"en":"Unlike ordinary lying, artistic storytelling usually invites the audience to enter an imagined world knowingly.","zh":"與普通說謊不同，藝術性的敘事通常邀請觀眾明知地進入想像世界。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":3},{"front":"spring from","meaning":"源自","examples":[{"en":"Lying and artistic storytelling spring from a common neurological root.","zh":"說謊和藝術性的敘事源自共同的神經學根源。"},{"en":"To spring from something means to come from or originate in it.","zh":"spring from something 指來自或起源於某事。"},{"en":"A student’s fear of speaking may spring from one embarrassing classroom experience.","zh":"學生害怕說話可能源自一次尷尬的課堂經歷。"},{"en":"Many family arguments spring from poor communication rather than real dislike.","zh":"許多家庭爭吵源自溝通不良，而不是真正討厭彼此。"},{"en":"This phrase is useful for explaining the source of an action, idea, or feeling.","zh":"這個短語適合用來解釋行動、想法或感受的來源。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":3},{"front":"a common neurological root","meaning":"共同的神經學根源","examples":[{"en":"Lying and artistic storytelling spring from a common neurological root.","zh":"說謊和藝術性的敘事源自共同的神經學根源。"},{"en":"A common neurological root means a shared source in the brain or nervous system.","zh":"a common neurological root 指在大腦或神經系統中共享的來源。"},{"en":"Memory and imagination may share a common neurological root because both involve mental reconstruction.","zh":"記憶和想像可能有共同的神經學根源，因為兩者都涉及心理重構。"},{"en":"If two behaviours share a common neurological root, brain damage may affect both.","zh":"如果兩種行為有共同的神經學根源，腦部損傷可能同時影響兩者。"},{"en":"This phrase connects human behaviour to the way the brain works.","zh":"這個短語把人類行為與大腦運作方式連起來。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":4},{"front":"be exposed in cases involving","meaning":"在涉及……的個案中顯現出來","examples":[{"en":"This connection is exposed in cases involving psychiatric patients.","zh":"這種關係在涉及精神科病人的個案中顯現出來。"},{"en":"Be exposed in cases involving something means become clear through examples that include that situation or group.","zh":"be exposed in cases involving something 指透過涉及某情況或群體的例子變得清楚。"},{"en":"Weak safety rules may be exposed in cases involving workplace accidents.","zh":"薄弱安全規則可能在涉及工傷意外的個案中顯現出來。"},{"en":"A hidden problem becomes easier to see when real cases reveal it.","zh":"當真實個案揭示隱藏問題時，問題會更容易看見。"},{"en":"This phrase is often used when examples make an underlying issue visible.","zh":"這個短語常用於例子令深層問題顯現時。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":4},{"front":"psychiatric patients","meaning":"精神科病人","examples":[{"en":"The study involved psychiatric patients with a particular impairment.","zh":"該研究涉及有某種特定缺損的精神科病人。"},{"en":"Psychiatric patients are people receiving medical care for mental health conditions.","zh":"psychiatric patients 指因心理健康狀況接受醫療照顧的人。"},{"en":"Psychiatric patients may need support from doctors, nurses, family members, and counsellors.","zh":"精神科病人可能需要醫生、護士、家人和輔導員的支援。"},{"en":"Some psychiatric patients struggle with memory, mood, speech, or perception.","zh":"有些精神科病人在記憶、情緒、語言或感知方面有困難。"},{"en":"This phrase should be used respectfully because it refers to people receiving treatment.","zh":"這個短語應尊重地使用，因為它指接受治療的人。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":4},{"front":"a particular impairment","meaning":"某種特定缺損","examples":[{"en":"The patients suffered from a particular impairment affecting memory and speech.","zh":"這些病人患有某種影響記憶和說話的特定缺損。"},{"en":"A particular impairment is a specific weakness, damage, or loss of ability.","zh":"a particular impairment 指某種具體的弱點、損傷或能力喪失。"},{"en":"A child with a hearing impairment may need subtitles or special classroom support.","zh":"有聽力缺損的孩子可能需要字幕或特別課堂支援。"},{"en":"If an impairment affects memory, the person may struggle to recall recent events.","zh":"如果缺損影響記憶，該人可能難以回想近期事件。"},{"en":"This phrase focuses on a specific difficulty rather than a general problem.","zh":"這個短語集中於具體困難，而不是一般問題。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":4},{"front":"refuse to accept","meaning":"拒絕接受","examples":[{"en":"Both liars and artists refuse to accept the tyranny of reality.","zh":"說謊者和藝術家都拒絕接受現實的束縛。"},{"en":"To refuse to accept something means to reject it or not agree to live under it.","zh":"refuse to accept something 指拒絕承認或不願受其支配。"},{"en":"A student may refuse to accept that one bad exam defines their future.","zh":"學生可能拒絕接受一次差考試就決定自己未來。"},{"en":"Refusing to accept unfair treatment can lead people to demand change.","zh":"拒絕接受不公平待遇可以令人要求改變。"},{"en":"This phrase shows resistance, not simple disagreement.","zh":"這個短語表示抗拒，而不只是不同意。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":4},{"front":"the tyranny of reality","meaning":"現實的束縛","examples":[{"en":"Artists and liars both resist the tyranny of reality.","zh":"藝術家和說謊者都抗拒現實的束縛。"},{"en":"The tyranny of reality means the strict limits that real facts place on imagination or desire.","zh":"the tyranny of reality 指真實事實對想像或願望施加的嚴格限制。"},{"en":"A novelist escapes the tyranny of reality by creating a world where time can move backwards.","zh":"小說家創造一個時間可以倒流的世界，逃離現實的束縛。"},{"en":"People may invent stories when the tyranny of reality feels too painful or boring.","zh":"當現實的束縛令人太痛苦或沉悶時，人們可能編造故事。"},{"en":"This phrase makes reality sound like a force that controls people.","zh":"這個短語把現實描寫成控制人的力量。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":4},{"front":"carefully craft stories","meaning":"精心編造故事","examples":[{"en":"Liars and artists carefully craft stories worthy of belief.","zh":"說謊者和藝術家都精心編造值得相信的故事。"},{"en":"To carefully craft stories means to shape stories with thought, skill, and detail.","zh":"carefully craft stories 指用思考、技巧和細節塑造故事。"},{"en":"A writer carefully crafts stories by choosing scenes, dialogue, and endings.","zh":"作家透過選擇場景、對白和結局來精心編寫故事。"},{"en":"Carefully crafted stories can feel believable even when they are invented.","zh":"精心編造的故事即使是虛構，也可以令人覺得可信。"},{"en":"This phrase suggests deliberate design rather than careless talking.","zh":"這個短語暗示有意設計，而不是隨便說話。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":4},{"front":"worthy of belief","meaning":"值得相信的","examples":[{"en":"They create stories worthy of belief.","zh":"他們創造值得相信的故事。"},{"en":"Worthy of belief means believable enough to deserve being taken seriously.","zh":"worthy of belief 指可信到值得被認真看待。"},{"en":"A witness statement is worthy of belief if it is consistent and supported by evidence.","zh":"如果證人口供一致並有證據支持，就值得相信。"},{"en":"A story becomes worthy of belief when its details fit together naturally.","zh":"當故事細節自然吻合時，就會變得值得相信。"},{"en":"This phrase describes credibility, not guaranteed truth.","zh":"這個短語描述可信度，而不保證真實。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":4},{"front":"require intellectual sophistication","meaning":"需要思維上的複雜能力","examples":[{"en":"Crafting believable stories requires intellectual sophistication.","zh":"編造可信故事需要思維上的複雜能力。"},{"en":"To require intellectual sophistication means to need complex thinking and mental skill.","zh":"require intellectual sophistication 指需要複雜思考和心智能力。"},{"en":"Solving a difficult legal problem may require intellectual sophistication.","zh":"解決困難法律問題可能需要思維上的複雜能力。"},{"en":"A believable lie requires intellectual sophistication because the details must fit together.","zh":"可信的謊言需要思維上的複雜能力，因為細節必須互相吻合。"},{"en":"This phrase is used when a task needs more than simple intelligence.","zh":"這個短語用於某任務需要的不只是簡單聰明時。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":4},{"front":"emotional sensitivity","meaning":"情感上的敏銳度","examples":[{"en":"Good storytelling may require emotional sensitivity.","zh":"好的說故事可能需要情感上的敏銳度。"},{"en":"Emotional sensitivity is the ability to notice and understand feelings carefully.","zh":"emotional sensitivity 是仔細察覺和理解情感的能力。"},{"en":"A teacher needs emotional sensitivity when a student is quiet because of family problems.","zh":"當學生因家庭問題而沉默時，老師需要情感上的敏銳度。"},{"en":"Stories feel real when writers use emotional sensitivity to show fear, shame, hope, or love.","zh":"當作家用情感敏銳度呈現恐懼、羞愧、希望或愛，故事會更真實。"},{"en":"This phrase describes awareness of feelings, not weakness.","zh":"這個短語描述對情感的覺察，而不是軟弱。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":4},{"front":"physical self-control","meaning":"身體上的自我控制","examples":[{"en":"Convincing lying can require physical self-control.","zh":"令人信服的說謊可能需要身體上的自我控制。"},{"en":"Physical self-control is the ability to control one’s body, face, voice, and movements.","zh":"physical self-control 是控制身體、表情、聲音和動作的能力。"},{"en":"A speaker needs physical self-control to avoid shaking too much during a presentation.","zh":"演講者需要身體上的自我控制，以避免匯報時太過顫抖。"},{"en":"A liar may need physical self-control to hide nervousness.","zh":"說謊者可能需要身體上的自我控制來隱藏緊張。"},{"en":"This phrase connects mental intention with bodily behaviour.","zh":"這個短語把心理意圖與身體行為連起來。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":5},{"front":"performers of their own work","meaning":"自己作品的表演者","examples":[{"en":"Liars are the writers and performers of their own work.","zh":"說謊者是自己作品的作者和表演者。"},{"en":"Performers of their own work are people who both create and present what they have made.","zh":"performers of their own work 指既創作又呈現自己作品的人。"},{"en":"A songwriter who sings her own songs is a performer of her own work.","zh":"自己演唱原創歌曲的創作歌手，就是自己作品的表演者。"},{"en":"Liars become performers of their own work because they must deliver the story convincingly.","zh":"說謊者成為自己作品的表演者，因為他們必須令人信服地講出故事。"},{"en":"This phrase highlights both invention and presentation.","zh":"這個短語突出創造和呈現兩方面。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":5},{"front":"such parallels","meaning":"這些相似之處","examples":[{"en":"Such parallels between lying and art are hardly coincidental.","zh":"說謊與藝術之間的這些相似之處絕非巧合。"},{"en":"Such parallels means similarities of the kind just mentioned.","zh":"such parallels 指剛才提到的那類相似之處。"},{"en":"Such parallels between sport and business include teamwork, pressure, and competition.","zh":"體育與商業之間的這些相似之處包括團隊合作、壓力和競爭。"},{"en":"When such parallels appear repeatedly, they may reveal a deeper connection.","zh":"當這些相似之處反覆出現時，它們可能揭示更深層關係。"},{"en":"This phrase refers back to earlier similarities without repeating them.","zh":"這個短語指回前文的相似點，而不用重複。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":5},{"front":"hardly coincidental","meaning":"絕非巧合","examples":[{"en":"The parallels between lying and art are hardly coincidental.","zh":"說謊與藝術之間的相似之處絕非巧合。"},{"en":"Hardly coincidental means almost certainly not happening by chance.","zh":"hardly coincidental 指幾乎肯定不是偶然發生。"},{"en":"If several students make the same unusual mistake, it is hardly coincidental.","zh":"如果幾個學生犯同一個不尋常錯誤，那絕非巧合。"},{"en":"Repeated similarities may be hardly coincidental because they suggest a shared cause.","zh":"反覆出現的相似之處可能絕非巧合，因為它們暗示共同原因。"},{"en":"This phrase is used when the writer thinks there is a real connection.","zh":"當作者認為存在真實關係時，可以使用這個短語。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":5},{"front":"while researching","meaning":"在研究……時","examples":[{"en":"The writer discovered these parallels while researching a book on lying.","zh":"作者在研究一本關於說謊的書時發現這些相似之處。"},{"en":"While researching means during the process of studying a topic carefully.","zh":"while researching 指在仔細研究某主題的過程中。"},{"en":"While researching a school project, a student may find unexpected information.","zh":"學生在研究學校專題時，可能發現意想不到的資訊。"},{"en":"Writers often change their ideas while researching because new evidence appears.","zh":"作者在研究時常因新證據出現而改變想法。"},{"en":"This phrase shows what someone was doing when they discovered something.","zh":"這個短語顯示某人發現某事時正在做甚麼。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":5},{"front":"a case study","meaning":"個案研究","examples":[{"en":"A case study published in 1985 described a woman with brain damage.","zh":"一項於1985年發表的個案研究描述了一名腦部受損的女子。"},{"en":"A case study is a detailed examination of one person, group, event, or situation.","zh":"case study 是對一個人、群體、事件或情況的詳細研究。"},{"en":"A doctor may write a case study about a patient with unusual symptoms.","zh":"醫生可能撰寫一個關於有不尋常症狀病人的個案研究。"},{"en":"Case studies can reveal rare problems that large surveys may miss.","zh":"個案研究可以揭示大型調查可能忽略的罕見問題。"},{"en":"A case study gives depth, but it may not represent everyone.","zh":"個案研究提供深度，但未必代表所有人。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":5},{"front":"brain was damaged by","meaning":"腦部因……受損","examples":[{"en":"Her brain was damaged by a series of strokes.","zh":"她的腦部因一連串中風而受損。"},{"en":"Brain was damaged by something means the brain was harmed because of that cause.","zh":"brain was damaged by something 指腦部因某原因受到傷害。"},{"en":"A person’s brain may be damaged by a serious accident.","zh":"一個人的腦部可能因嚴重意外而受損。"},{"en":"When the brain is damaged, memory, speech, movement, or emotion may be affected.","zh":"當腦部受損，記憶、說話、動作或情緒可能受影響。"},{"en":"This phrase explains both the injury and its cause.","zh":"這個短語同時解釋傷害和原因。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":5},{"front":"a series of strokes","meaning":"一連串中風","examples":[{"en":"The woman’s brain was damaged by a series of strokes.","zh":"這名女子的腦部因一連串中風而受損。"},{"en":"A series of strokes means several strokes happening one after another or over a period of time.","zh":"a series of strokes 指幾次中風接連發生或在一段時間內發生。"},{"en":"An elderly patient may need long-term care after a series of strokes.","zh":"長者經歷一連串中風後，可能需要長期照顧。"},{"en":"A series of strokes can damage different parts of the brain.","zh":"一連串中風可以損害腦部不同區域。"},{"en":"This phrase suggests repeated medical events, not one single incident.","zh":"這個短語暗示反覆的醫療事件，而不是單一事故。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":5},{"front":"retain cognitive abilities","meaning":"保留認知能力","examples":[{"en":"She retained cognitive abilities, including coherent speech.","zh":"她保留了認知能力，包括條理清晰的說話能力。"},{"en":"To retain cognitive abilities means to keep mental skills such as thinking, memory, language, or understanding.","zh":"retain cognitive abilities 指保留思考、記憶、語言或理解等心智能力。"},{"en":"After an accident, a patient may retain cognitive abilities but lose physical strength.","zh":"意外後，病人可能保留認知能力，但失去體力。"},{"en":"Retained cognitive abilities can help doctors understand which parts of the brain still work well.","zh":"保留的認知能力可以幫助醫生了解腦部哪些部分仍運作良好。"},{"en":"This phrase is often used when some abilities remain after injury or illness.","zh":"這個短語常用於受傷或患病後仍保留某些能力時。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":5},{"front":"cognitive abilities","meaning":"認知能力","examples":[{"en":"The patient retained important cognitive abilities after her strokes.","zh":"該病人在中風後保留了重要認知能力。"},{"en":"Cognitive abilities are mental skills used for thinking, learning, remembering, and understanding.","zh":"cognitive abilities 是用於思考、學習、記憶和理解的心智能力。"},{"en":"Reading, problem-solving, and planning all use cognitive abilities.","zh":"閱讀、解難和規劃都會使用認知能力。"},{"en":"Illness or brain injury can affect cognitive abilities in different ways.","zh":"疾病或腦傷可以以不同方式影響認知能力。"},{"en":"Strong cognitive abilities help people manage school, work, and daily decisions.","zh":"強的認知能力幫助人處理學校、工作和日常決定。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":5},{"front":"coherent speech","meaning":"條理清晰的說話能力","examples":[{"en":"She retained coherent speech despite her brain damage.","zh":"儘管腦部受損，她仍保留條理清晰的說話能力。"},{"en":"Coherent speech is speech that is clear, logical, and easy to follow.","zh":"coherent speech 指清楚、有邏輯、容易跟上的說話。"},{"en":"A nervous student may struggle to produce coherent speech during an interview.","zh":"緊張的學生在面試中可能難以說出條理清晰的話。"},{"en":"When speech is coherent, listeners can understand the speaker’s meaning and order of ideas.","zh":"當說話條理清晰，聽者能理解說話者的意思和思路。"},{"en":"Coherent speech does not always mean the information is true.","zh":"條理清晰的說話不一定代表內容真實。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":6},{"front":"unpredictable","meaning":"難以預測的","examples":[{"en":"What she actually said was unpredictable.","zh":"她實際說出來的內容難以預測。"},{"en":"Unpredictable means difficult or impossible to know before it happens.","zh":"unpredictable 指事情在發生前很難或不可能知道。"},{"en":"A child’s mood may be unpredictable when they are tired.","zh":"孩子疲倦時，情緒可能難以預測。"},{"en":"Unpredictable answers make conversations harder because listeners cannot guess what comes next.","zh":"難以預測的回答令對話更困難，因為聽者無法猜到下一步。"},{"en":"This word describes uncertainty in behaviour, events, or results.","zh":"這個字描述行為、事件或結果中的不確定性。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":6},{"front":"contemporary events","meaning":"當代事件","examples":[{"en":"Damasio tested her knowledge of contemporary events.","zh":"Damasio 測試她對當代事件的認識。"},{"en":"Contemporary events are events happening in the present time or recent period.","zh":"contemporary events 指現在或近代正在發生的事件。"},{"en":"A news quiz may test students on contemporary events such as elections or major discoveries.","zh":"新聞小測可能考學生關於選舉或重大發現等當代事件。"},{"en":"Knowing contemporary events helps people understand current society.","zh":"了解當代事件有助人理解當前社會。"},{"en":"This phrase contrasts recent events with historical events from long ago.","zh":"這個短語把近期事件與久遠歷史事件作對比。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":6},{"front":"in psychiatric terms","meaning":"以精神醫學術語來說","examples":[{"en":"In psychiatric terms, the woman was confabulating.","zh":"以精神醫學術語來說，這名女子正在作虛談。"},{"en":"In psychiatric terms means using the language or concepts of mental health medicine.","zh":"in psychiatric terms 指使用心理健康醫學的語言或概念。"},{"en":"In psychiatric terms, repeated panic attacks may be treated as a serious anxiety condition.","zh":"以精神醫學術語來說，反覆恐慌發作可能被視為嚴重焦慮狀況。"},{"en":"This phrase signals that the writer is giving a professional medical description.","zh":"這個短語表示作者正在給出專業醫學描述。"},{"en":"It helps distinguish everyday language from clinical explanation.","zh":"它有助區分日常語言與臨床解釋。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":6},{"front":"confabulate","meaning":"虛構記憶；作虛談","examples":[{"en":"The patient began to confabulate when asked about current events.","zh":"當被問及時事時，病人開始虛構記憶。"},{"en":"To confabulate means to produce false or distorted memories without intending to deceive.","zh":"confabulate 指在無意欺騙的情況下產生虛假或扭曲記憶。"},{"en":"A patient may confabulate by giving a confident but invented explanation for being in hospital.","zh":"病人可能自信地編造自己為何在醫院的解釋，這就是作虛談。"},{"en":"Confabulation can happen when the brain tries to fill gaps in memory.","zh":"當大腦試圖填補記憶空白時，可能出現虛構記憶。"},{"en":"This word is medical and should not be used simply to mean ordinary lying.","zh":"這個字屬醫學用語，不應簡單用來指普通說謊。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":6},{"front":"chronic confabulation","meaning":"慢性虛構症；慢性虛談症","examples":[{"en":"Chronic confabulation is a rare memory disorder.","zh":"慢性虛構症是一種罕見的記憶障礙。"},{"en":"Chronic confabulation is a long-lasting condition in which a person repeatedly produces false memories without deliberate lying.","zh":"chronic confabulation 是一種長期狀況，患者會反覆產生虛假記憶，但並非故意說謊。"},{"en":"A patient with chronic confabulation may tell detailed stories that never happened.","zh":"患有慢性虛構症的病人可能講述從未發生過的詳細故事。"},{"en":"The condition can confuse families because the person may sound sincere.","zh":"這種狀況可能令家人困惑，因為患者聽起來很真誠。"},{"en":"This phrase describes a persistent medical condition, not a habit of dishonesty.","zh":"這個短語描述持續的醫療狀況，而不是不誠實的習慣。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":6},{"front":"a rare memory disorder","meaning":"罕見的記憶障礙","examples":[{"en":"Confabulation is a rare memory disorder affecting some people with brain damage.","zh":"虛構症是一種影響部分腦部受損人士的罕見記憶障礙。"},{"en":"A rare memory disorder is an uncommon condition that affects how memory works.","zh":"a rare memory disorder 指一種不常見、影響記憶運作的狀況。"},{"en":"Doctors may study a rare memory disorder carefully because few patients have it.","zh":"醫生可能仔細研究罕見記憶障礙，因為患者很少。"},{"en":"A rare memory disorder can reveal how normal memory usually functions.","zh":"罕見記憶障礙可以揭示正常記憶通常如何運作。"},{"en":"This phrase combines low frequency with a problem in remembering.","zh":"這個短語結合了低發生率與記憶問題。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":6},{"front":"a small proportion of","meaning":"一小部分","examples":[{"en":"The disorder affects a small proportion of people with brain damage.","zh":"這種障礙影響一小部分腦部受損人士。"},{"en":"A small proportion of a group means a small part or percentage of that group.","zh":"a small proportion of 某群體，指該群體中的一小部分或小百分比。"},{"en":"A small proportion of students may need extra time in exams.","zh":"一小部分學生可能在考試中需要額外時間。"},{"en":"If only a small proportion of users report a problem, it may still need investigation.","zh":"即使只有一小部分使用者報告問題，仍可能需要調查。"},{"en":"This phrase describes quantity without giving an exact number.","zh":"這個短語在不給出精確數字時描述數量。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":6},{"front":"people with brain damage","meaning":"腦部受損的人","examples":[{"en":"Confabulation can affect people with brain damage.","zh":"虛構症可以影響腦部受損的人。"},{"en":"People with brain damage are people whose brains have been injured by illness, accident, stroke, or other causes.","zh":"people with brain damage 指因疾病、意外、中風或其他原因而腦部受傷的人。"},{"en":"People with brain damage may need speech therapy, memory support, or physical rehabilitation.","zh":"腦部受損的人可能需要言語治療、記憶支援或物理復康。"},{"en":"Brain damage can affect different people in very different ways.","zh":"腦部受損可以以非常不同方式影響不同的人。"},{"en":"This phrase should be used with care and respect.","zh":"這個短語應小心而尊重地使用。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":6},{"front":"the literature defines it as","meaning":"文獻將其定義為","examples":[{"en":"The literature defines confabulation as the production of false memories.","zh":"文獻將虛構症定義為產生虛假記憶。"},{"en":"The literature defines it as means academic or professional writings describe it in a particular way.","zh":"the literature defines it as 指學術或專業文獻以某種方式描述它。"},{"en":"The literature defines burnout as a condition involving exhaustion and reduced motivation.","zh":"文獻將倦怠定義為涉及疲憊和動力下降的狀況。"},{"en":"This phrase is useful when giving a formal definition from research.","zh":"當給出來自研究的正式定義時，這個短語很有用。"},{"en":"It shows that the meaning comes from expert writing, not casual opinion.","zh":"它顯示意思來自專家文獻，而不是隨意意見。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":6},{"front":"fabricated memories","meaning":"虛構的記憶","examples":[{"en":"Confabulation involves fabricated memories about oneself or the world.","zh":"虛構症涉及關於自己或世界的虛構記憶。"},{"en":"Fabricated memories are memories that are invented rather than based on real events.","zh":"fabricated memories 指被編造出來，而不是基於真實事件的記憶。"},{"en":"A patient may have fabricated memories of visiting a place they have never been to.","zh":"病人可能有自己去過從未到過的地方的虛構記憶。"},{"en":"Fabricated memories can feel real to the person experiencing them.","zh":"虛構記憶對經歷者本人來說可能感覺真實。"},{"en":"This phrase does not always imply deliberate lying.","zh":"這個短語不一定表示故意說謊。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":7},{"front":"distorted memories","meaning":"扭曲的記憶","examples":[{"en":"Confabulators may produce distorted memories without intending to deceive.","zh":"虛構症患者可能在無意欺騙下產生扭曲記憶。"},{"en":"Distorted memories are memories that are changed, twisted, or remembered inaccurately.","zh":"distorted memories 指被改變、扭曲或不準確記住的記憶。"},{"en":"A child may have distorted memories of an argument if they were very frightened.","zh":"如果孩子當時很害怕，可能對一次爭吵有扭曲記憶。"},{"en":"Stress and time can make memories distorted rather than completely false.","zh":"壓力和時間可以令記憶扭曲，而不一定完全虛假。"},{"en":"This phrase suggests memory is partly altered, not necessarily fully invented.","zh":"這個短語暗示記憶部分被改變，而不一定完全編造。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":7},{"front":"misinterpreted memories","meaning":"誤解了的記憶","examples":[{"en":"Confabulation can involve misinterpreted memories about oneself or the world.","zh":"虛構症可能涉及關於自己或世界的誤解了的記憶。"},{"en":"Misinterpreted memories are memories understood in the wrong way.","zh":"misinterpreted memories 指以錯誤方式理解的記憶。"},{"en":"A person may misinterpret a childhood memory because they lacked the full context at the time.","zh":"一個人可能因當時缺乏完整背景，而誤解童年記憶。"},{"en":"Misinterpreted memories can lead someone to explain events incorrectly.","zh":"誤解了的記憶可以令人錯誤解釋事件。"},{"en":"This phrase shows that memory can be wrong because of mistaken meaning, not only missing facts.","zh":"這個短語顯示記憶可能因意思理解錯誤而出錯，不只是缺少事實。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":7},{"front":"without the conscious intention to","meaning":"並非有意去","examples":[{"en":"Confabulators create false memories without the conscious intention to deceive.","zh":"虛構症患者產生虛假記憶，並非有意去欺騙。"},{"en":"Without the conscious intention to do something means without deliberately deciding to do it.","zh":"without the conscious intention to do something 指沒有有意識地決定去做某事。"},{"en":"A tired person may interrupt others without the conscious intention to be rude.","zh":"疲倦的人可能打斷別人，但並非有意無禮。"},{"en":"If someone acts without conscious intention, blame may be more complicated.","zh":"如果某人並非有意行動，責任判斷可能更複雜。"},{"en":"This phrase separates accidental or unconscious behaviour from deliberate action.","zh":"這個短語把無意識或非故意行為與蓄意行動分開。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":7},{"front":"deceive","meaning":"欺騙","examples":[{"en":"Confabulators do not consciously intend to deceive others.","zh":"虛構症患者並非有意識地打算欺騙他人。"},{"en":"To deceive someone means to make them believe something false.","zh":"deceive someone 指令某人相信不真實的事情。"},{"en":"A fake email may deceive people into giving away passwords.","zh":"虛假電郵可能欺騙人交出密碼。"},{"en":"Deception can damage trust when the truth becomes clear.","zh":"當真相變得清楚，欺騙會破壞信任。"},{"en":"This verb usually suggests dishonesty, but confabulation is different because intention may be absent.","zh":"這個動詞通常暗示不誠實，但虛構症不同，因為可能沒有意圖。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":7},{"front":"whereas","meaning":"然而；相對而言","examples":[{"en":"Whereas amnesiacs make errors of omission, confabulators make errors of commission.","zh":"失憶症患者會犯遺漏錯誤，相對而言，虛構症患者會犯編造錯誤。"},{"en":"Whereas is used to compare two contrasting facts.","zh":"whereas 用來比較兩個相反或不同的事實。"},{"en":"Some students learn best by listening, whereas others need to write things down.","zh":"有些學生透過聆聽學得最好，然而其他學生需要寫下來。"},{"en":"This word helps show that two groups differ in an important way.","zh":"這個字有助顯示兩個群體在重要方面不同。"},{"en":"It is often used in formal comparison sentences.","zh":"它常用於正式比較句。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":7},{"front":"amnesiacs","meaning":"失憶症患者","examples":[{"en":"Amnesiacs may have gaps in their recollections.","zh":"失憶症患者的記憶中可能有空白。"},{"en":"Amnesiacs are people who suffer from amnesia, a condition involving memory loss.","zh":"amnesiacs 指患有失憶症、出現記憶喪失的人。"},{"en":"An amnesiac may remember childhood but forget recent events.","zh":"失憶症患者可能記得童年，卻忘記近期事件。"},{"en":"Amnesiacs may struggle because parts of their memory are missing.","zh":"失憶症患者可能因部分記憶缺失而感到困難。"},{"en":"This word refers to a medical condition, not ordinary forgetfulness.","zh":"這個字指醫療狀況，而不是普通健忘。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":7},{"front":"errors of omission","meaning":"遺漏錯誤","examples":[{"en":"Amnesiacs make errors of omission when they cannot fill memory gaps.","zh":"失憶症患者無法填補記憶空白時，會犯遺漏錯誤。"},{"en":"Errors of omission are mistakes caused by leaving something out.","zh":"errors of omission 是因漏掉某事而造成的錯誤。"},{"en":"A student makes an error of omission if they forget to answer one question.","zh":"如果學生忘記回答一題，就是犯了遺漏錯誤。"},{"en":"In memory, errors of omission happen when information is missing rather than invented.","zh":"在記憶中，遺漏錯誤發生於資訊缺失，而不是被編造。"},{"en":"This phrase contrasts with mistakes caused by adding false information.","zh":"這個短語與加入虛假資訊造成的錯誤形成對比。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":7},{"front":"gaps in recollections","meaning":"記憶中的空白","examples":[{"en":"Amnesiacs have gaps in their recollections that they cannot fill.","zh":"失憶症患者有他們無法填補的記憶空白。"},{"en":"Gaps in recollections are missing parts in someone’s memory of past events.","zh":"gaps in recollections 指某人對過去事件記憶中缺失的部分。"},{"en":"After a stressful accident, a person may have gaps in their recollections of what happened.","zh":"在一次壓力很大的意外後，一個人可能對事情經過有記憶空白。"},{"en":"Memory gaps can make people confused when they try to explain their past.","zh":"記憶空白會令人嘗試解釋過去時感到困惑。"},{"en":"This phrase focuses on what is absent from memory.","zh":"這個短語集中於記憶中缺失的部分。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":7},{"front":"errors of commission","meaning":"編造錯誤；主動錯誤","examples":[{"en":"Confabulators make errors of commission by inventing events.","zh":"虛構症患者透過編造事件犯主動錯誤。"},{"en":"Errors of commission are mistakes caused by adding something false or doing something wrong.","zh":"errors of commission 是因加入虛假內容或做錯事而造成的錯誤。"},{"en":"A student makes an error of commission if they add a fact that the passage never mentions.","zh":"如果學生加入文章從未提及的事實，就是犯了編造錯誤。"},{"en":"In confabulation, errors of commission happen when the mind invents details.","zh":"在虛構症中，主動錯誤發生於大腦編造細節時。"},{"en":"This phrase contrasts with errors caused by leaving information out.","zh":"這個短語與因漏掉資訊而造成的錯誤形成對比。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":7},{"front":"make things up","meaning":"編造事情","examples":[{"en":"Confabulators make things up rather than simply forgetting.","zh":"虛構症患者編造事情，而不只是忘記。"},{"en":"To make things up means to invent information, stories, or explanations.","zh":"make things up 指編造資訊、故事或解釋。"},{"en":"A child may make things up when they are afraid of getting into trouble.","zh":"孩子害怕惹麻煩時，可能編造事情。"},{"en":"Making things up can fill a gap, but it can also mislead others.","zh":"編造事情可以填補空白，但也可能誤導別人。"},{"en":"In medical contexts, making things up may happen without deliberate dishonesty.","zh":"在醫學語境中，編造事情可能並非故意不誠實。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":8},{"front":"rather than","meaning":"而不是","examples":[{"en":"Rather than forgetting, confabulators invent.","zh":"虛構症患者是編造，而不是忘記。"},{"en":"Rather than means instead of, and it shows contrast between two choices or explanations.","zh":"rather than 意思是「而不是」，用來顯示兩個選擇或解釋之間的對比。"},{"en":"A good teacher explains mistakes rather than simply marking them wrong.","zh":"好老師會解釋錯誤，而不是只把它們標錯。"},{"en":"If the problem is stress rather than laziness, the solution should be different.","zh":"如果問題是壓力而不是懶惰，解決方法應該不同。"},{"en":"This phrase helps separate what is true from what is not the main point.","zh":"這個短語有助分清真正情況與非重點。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":8},{"front":"be unaware of their condition","meaning":"不知道自己的狀況","examples":[{"en":"Confabulating patients are often unaware of their condition.","zh":"虛構症患者常不知道自己的狀況。"},{"en":"To be unaware of their condition means not to know that they have a particular illness or problem.","zh":"be unaware of their condition 指不知道自己有某種疾病或問題。"},{"en":"A patient may be unaware of their condition until a doctor explains the test results.","zh":"病人可能直到醫生解釋檢查結果後，才知道自己的狀況。"},{"en":"If people are unaware of their condition, they may not seek help.","zh":"如果人們不知道自己的狀況，可能不會尋求幫助。"},{"en":"This phrase is common in medical or psychological contexts.","zh":"這個短語常見於醫學或心理學語境。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":8},{"front":"earnestly offer","meaning":"誠懇地提出","examples":[{"en":"Patients may earnestly offer implausible explanations.","zh":"病人可能誠懇地提出難以置信的解釋。"},{"en":"To earnestly offer something means to give it sincerely and seriously.","zh":"earnestly offer something 指真誠而認真地提出某事。"},{"en":"A student may earnestly offer an apology after realising they hurt a friend.","zh":"學生意識到自己傷害朋友後，可能誠懇地道歉。"},{"en":"When people earnestly offer an explanation, they may truly believe it.","zh":"當人們誠懇地提出解釋時，他們可能真心相信它。"},{"en":"This phrase shows sincerity, even if the content is wrong.","zh":"這個短語顯示真誠，即使內容是錯的。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":8},{"front":"absurdly implausible explanations","meaning":"荒謬得難以置信的解釋","examples":[{"en":"Some patients give absurdly implausible explanations for why they are in hospital.","zh":"有些病人對自己為何在醫院給出荒謬得難以置信的解釋。"},{"en":"Absurdly implausible explanations are explanations so unreasonable that they are almost impossible to believe.","zh":"absurdly implausible explanations 指荒謬到幾乎不可能相信的解釋。"},{"en":"Saying a dog drove the school bus would be an absurdly implausible explanation for being late.","zh":"說狗駕駛校巴，是遲到原因中荒謬得難以置信的解釋。"},{"en":"Such explanations may reveal confusion rather than deliberate humour.","zh":"這類解釋可能揭示混亂，而不是故意幽默。"},{"en":"This phrase describes explanations that sound wildly unbelievable.","zh":"這個短語描述極度不可信的解釋。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":8},{"front":"surgical scar","meaning":"手術疤痕","examples":[{"en":"One patient was asked about his surgical scar.","zh":"一名病人被問及他的手術疤痕。"},{"en":"A surgical scar is a mark left on the body after an operation.","zh":"surgical scar 指手術後留在身體上的痕跡。"},{"en":"A person may have a surgical scar on the chest after heart surgery.","zh":"一個人做完心臟手術後，胸口可能有手術疤痕。"},{"en":"A surgical scar can remind doctors what treatment a patient has received.","zh":"手術疤痕可以提醒醫生病人接受過甚麼治療。"},{"en":"This phrase is used for scars specifically caused by surgery.","zh":"這個短語專指由手術造成的疤痕。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":8},{"front":"bring someone back to life","meaning":"令某人復活","examples":[{"en":"The patient claimed that surgery had brought him back to life.","zh":"病人聲稱手術令他復活。"},{"en":"To bring someone back to life means to make someone live again or recover after seeming dead or lifeless.","zh":"bring someone back to life 指令某人重新活過來，或從看似死亡或無生氣的狀態恢復。"},{"en":"Emergency doctors may try to bring a patient back to life after cardiac arrest.","zh":"急症醫生可能在病人心臟停頓後嘗試令其復活。"},{"en":"In stories, magic can bring someone back to life, but in reality the phrase is usually dramatic.","zh":"在故事中，魔法可以令某人復活，但現實中這個短語通常帶戲劇性。"},{"en":"This phrase can be literal in medical emergencies or figurative in storytelling.","zh":"這個短語可在醫療急症中按字面使用，也可在故事中作比喻使用。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":8},{"front":"at various times","meaning":"在不同時候","examples":[{"en":"At various times, the patient said that his family had died in his arms.","zh":"在不同時候，該病人說他的家人死在他懷中。"},{"en":"At various times means on several different occasions.","zh":"at various times 指在幾個不同場合或時間。"},{"en":"At various times during the year, the school holds parent meetings.","zh":"學校在一年中的不同時候舉行家長會。"},{"en":"If a person gives different stories at various times, listeners may become confused.","zh":"如果一個人在不同時候給出不同故事，聽者可能困惑。"},{"en":"This phrase shows repetition across different moments, not one single event.","zh":"這個短語顯示在不同時刻重複發生，而不是單一事件。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":8},{"front":"die in someone’s arms","meaning":"死在某人懷中","examples":[{"en":"The patient described family members dying in his arms.","zh":"該病人描述家人在他懷中死去。"},{"en":"To die in someone’s arms means to die while being held by that person.","zh":"die in someone’s arms 指在被某人抱著時死去。"},{"en":"In a tragic film, a soldier may die in his friend’s arms.","zh":"在悲劇電影中，士兵可能死在朋友懷中。"},{"en":"This image creates strong emotion because it suggests helplessness and closeness.","zh":"這個畫面製造強烈情感，因為它暗示無助和親近。"},{"en":"The phrase is dramatic and often appears in stories of grief.","zh":"這個短語具戲劇性，常出現在悲傷故事中。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":8},{"front":"before someone’s eyes","meaning":"在某人眼前","examples":[{"en":"He claimed that his family had been killed before his eyes.","zh":"他聲稱他的家人在他眼前被殺。"},{"en":"Before someone’s eyes means directly in front of someone, while they are watching.","zh":"before someone’s eyes 指直接在某人面前、被其看見。"},{"en":"The accident happened before the child’s eyes, so she was deeply shocked.","zh":"意外在孩子眼前發生，所以她受到很大震驚。"},{"en":"Seeing something painful before one’s eyes can make the memory especially strong.","zh":"在眼前看見痛苦事件，可以令記憶特別深刻。"},{"en":"This phrase stresses direct witnessing.","zh":"這個短語強調親眼目睹。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":8},{"front":"fantastical stories","meaning":"荒誕離奇的故事","examples":[{"en":"Other patients tell even more fantastical stories.","zh":"其他病人講述甚至更荒誕離奇的故事。"},{"en":"Fantastical stories are strange, imaginative stories that seem impossible or dreamlike.","zh":"fantastical stories 指奇怪、富想像力、看似不可能或像夢境的故事。"},{"en":"A child may tell fantastical stories about dragons living under the school.","zh":"孩子可能講述龍住在學校地下的荒誕離奇故事。"},{"en":"Fantastical stories can entertain people, but in a medical case they may signal confusion.","zh":"荒誕離奇的故事可以娛樂人，但在醫學個案中可能顯示混亂。"},{"en":"This phrase describes stories that go far beyond ordinary reality.","zh":"這個短語描述遠遠超出日常現實的故事。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":9},{"front":"trips to the Moon","meaning":"月球之旅","examples":[{"en":"Some confabulators tell stories about trips to the Moon.","zh":"有些虛構症患者講述月球之旅的故事。"},{"en":"Trips to the Moon are journeys to the Moon, usually imagined unless involving space missions.","zh":"trips to the Moon 指前往月球的旅程，通常是想像的，除非涉及太空任務。"},{"en":"A child may invent stories about trips to the Moon after watching a space film.","zh":"孩子看完太空電影後，可能編造月球之旅的故事。"},{"en":"In confabulation, stories about impossible trips may reveal false memory rather than fantasy play.","zh":"在虛構症中，關於不可能旅程的故事可能揭示虛假記憶，而不是幻想遊戲。"},{"en":"This phrase signals an extraordinary and unlikely event.","zh":"這個短語表示非凡且不太可能的事件。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":9},{"front":"fight alongside","meaning":"與……並肩作戰","examples":[{"en":"One patient described fighting alongside Alexander in India.","zh":"一名病人描述自己在印度與亞歷山大並肩作戰。"},{"en":"To fight alongside someone means to fight on the same side as that person.","zh":"fight alongside someone 指與某人在同一陣營作戰。"},{"en":"Soldiers from different countries may fight alongside one another in the same mission.","zh":"不同國家的士兵可能在同一任務中並肩作戰。"},{"en":"Fighting alongside someone can create loyalty because people face danger together.","zh":"與某人並肩作戰可以建立忠誠，因為人們一起面對危險。"},{"en":"This phrase is often used in war, sport, or struggle contexts.","zh":"這個短語常用於戰爭、運動或抗爭語境。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":9},{"front":"on the Cross","meaning":"在十字架上","examples":[{"en":"Some patients even claim to have seen Jesus on the Cross.","zh":"有些病人甚至聲稱曾看見耶穌在十字架上。"},{"en":"On the Cross refers to Jesus being crucified on the cross in Christian tradition.","zh":"on the Cross 指基督教傳統中耶穌被釘在十字架上。"},{"en":"Religious paintings often show Jesus on the Cross to represent suffering and sacrifice.","zh":"宗教畫常描繪耶穌在十字架上，以代表痛苦和犧牲。"},{"en":"Claiming to see Jesus on the Cross would suggest an extraordinary or impossible memory.","zh":"聲稱看見耶穌在十字架上，會暗示一段非凡或不可能的記憶。"},{"en":"This phrase carries strong religious and historical meaning.","zh":"這個短語帶有強烈宗教和歷史意義。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":9},{"front":"intend to deceive","meaning":"有意欺騙","examples":[{"en":"Confabulators do not intend to deceive.","zh":"虛構症患者並非有意欺騙。"},{"en":"To intend to deceive means to deliberately plan to make someone believe something false.","zh":"intend to deceive 指有意計劃令某人相信不真實的事情。"},{"en":"A scammer intends to deceive people when sending fake bank messages.","zh":"騙徒發送假銀行訊息時，是有意欺騙別人。"},{"en":"If a person does not intend to deceive, their false statement may come from error or confusion.","zh":"如果一個人並非有意欺騙，其錯誤說法可能來自錯誤或混亂。"},{"en":"This phrase focuses on intention, not only on whether the information is false.","zh":"這個短語集中於意圖，而不只是資訊是否虛假。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":9},{"front":"engage in","meaning":"從事；進行","examples":[{"en":"They engage in what Morris Moscovitch calls honest lying.","zh":"他們從事 Morris Moscovitch 所稱的誠實的謊言。"},{"en":"To engage in something means to take part in or do an activity.","zh":"engage in something 指參與或進行某項活動。"},{"en":"Students engage in group discussion when they share ideas and respond to classmates.","zh":"學生分享想法並回應同學時，就是在進行小組討論。"},{"en":"People who engage in risky behaviour may face serious consequences.","zh":"從事高風險行為的人可能面對嚴重後果。"},{"en":"This phrase is more formal than simply saying “do”.","zh":"這個短語比 simply saying “do” 更正式。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":9},{"front":"honest lying","meaning":"誠實的謊言","examples":[{"en":"Moscovitch calls confabulation honest lying.","zh":"Moscovitch 把虛構症稱為誠實的謊言。"},{"en":"Honest lying means saying something false while sincerely believing it is true.","zh":"honest lying 指說出不真實的事情，但本人真誠相信它是真的。"},{"en":"A confused patient may engage in honest lying when they explain a memory that never happened.","zh":"混亂的病人解釋一段從未發生的記憶時，可能是在說誠實的謊言。"},{"en":"Honest lying is different from ordinary lying because there is no deliberate attempt to deceive.","zh":"誠實的謊言不同於普通說謊，因為沒有故意欺騙。"},{"en":"This phrase sounds paradoxical because honesty and lying usually seem opposite.","zh":"這個短語聽起來矛盾，因為誠實和說謊通常看似相反。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":9},{"front":"obscurely distressed by","meaning":"因……而隱約不安","examples":[{"en":"Confabulators are obscurely distressed by uncertainty.","zh":"虛構症患者因不確定而隱約不安。"},{"en":"Obscurely distressed by something means troubled by it in a vague or unclear way.","zh":"obscurely distressed by something 指因某事而感到模糊或不清楚的不安。"},{"en":"A child may be obscurely distressed by family tension without knowing exactly why.","zh":"孩子可能因家庭緊張而隱約不安，卻不知道確切原因。"},{"en":"Unclear discomfort can push people to invent explanations.","zh":"不清楚的不適感可能推動人編造解釋。"},{"en":"This phrase suggests hidden, hard-to-name emotional unease.","zh":"這個短語暗示隱藏、難以命名的情緒不安。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":9},{"front":"be seized by","meaning":"被……支配；突然受到……控制","examples":[{"en":"They are seized by a compulsion to narrate.","zh":"他們被一種敘事衝動支配。"},{"en":"To be seized by something means to be suddenly strongly controlled by a feeling or urge.","zh":"be seized by something 指突然被某種感受或衝動強烈控制。"},{"en":"A student may be seized by panic when they see a difficult exam question.","zh":"學生看到困難考題時，可能突然被恐慌支配。"},{"en":"When people are seized by a strong urge, they may act before thinking carefully.","zh":"當人被強烈衝動支配，可能未經仔細思考便行動。"},{"en":"This phrase makes the feeling sound powerful and hard to resist.","zh":"這個短語令該感受聽起來強烈且難以抵抗。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":9},{"front":"a compulsion to narrate","meaning":"敘事衝動","examples":[{"en":"Confabulators feel a compulsion to narrate what they do not understand.","zh":"虛構症患者感到一種敘事衝動，想講述自己不理解的事。"},{"en":"A compulsion to narrate is a strong inner need to tell or explain a story.","zh":"a compulsion to narrate 是一種強烈內在需要，想講述或解釋故事。"},{"en":"Some people feel a compulsion to narrate every problem so life seems more organised.","zh":"有些人有敘事衝動，會把每個問題都講成故事，好讓生活看似更有秩序。"},{"en":"When uncertainty is painful, a compulsion to narrate may create explanations too quickly.","zh":"當不確定令人痛苦時，敘事衝動可能太快創造解釋。"},{"en":"This phrase connects storytelling with psychological pressure.","zh":"這個短語把說故事與心理壓力連起來。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":9},{"front":"a deep-seated need","meaning":"根深蒂固的需要","examples":[{"en":"They have a deep-seated need to explain uncertainty.","zh":"他們有一種根深蒂固的需要，想解釋不確定性。"},{"en":"A deep-seated need is a strong need that is rooted deeply in a person’s mind or character.","zh":"a deep-seated need 指深深扎根於一個人心理或性格中的強烈需要。"},{"en":"A child who moved often may develop a deep-seated need for stability.","zh":"經常搬家的孩子可能形成對穩定的根深蒂固需要。"},{"en":"Deep-seated needs can shape behaviour even when people do not fully notice them.","zh":"根深蒂固的需要可以塑造行為，即使人們未完全察覺。"},{"en":"This phrase describes something deeper than a temporary wish.","zh":"這個短語描述比暫時願望更深層的東西。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":10},{"front":"shape, order and explain","meaning":"塑造、整理並解釋","examples":[{"en":"They try to shape, order and explain what they do not understand.","zh":"他們嘗試塑造、整理並解釋自己不理解的事。"},{"en":"To shape, order and explain something means to give it form, structure, and meaning.","zh":"shape, order and explain something 指給某事形式、結構和意義。"},{"en":"A teacher helps students shape, order and explain their ideas before writing an essay.","zh":"老師幫助學生在寫文章前塑造、整理並解釋自己的想法。"},{"en":"People may shape, order and explain confusing experiences by turning them into stories.","zh":"人們可能透過把混亂經歷變成故事，來塑造、整理並解釋它們。"},{"en":"This phrase shows the mind trying to make sense of disorder.","zh":"這個短語顯示大腦試圖理解混亂。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":10},{"front":"highly inventive verbally","meaning":"在語言上極具創意","examples":[{"en":"Chronic confabulators are often highly inventive verbally.","zh":"慢性虛構症患者常在語言上極具創意。"},{"en":"Highly inventive verbally means very creative with words and speech.","zh":"highly inventive verbally 指在用詞和說話方面非常有創意。"},{"en":"A child who makes up funny names for everything may be highly inventive verbally.","zh":"一個為所有東西創造有趣名字的孩子，可能在語言上極具創意。"},{"en":"Verbal inventiveness can create vivid stories, even when the stories are not true.","zh":"語言創意可以創造生動故事，即使故事並不真實。"},{"en":"This phrase describes language creativity, not necessarily accuracy.","zh":"這個短語描述語言創造力，而不一定是準確性。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":10},{"front":"combine words in…ways","meaning":"以……方式組合詞語","examples":[{"en":"Some patients combine words in nonsensical but suggestive ways.","zh":"有些病人以無意義但富啟發性的方式組合詞語。"},{"en":"To combine words in particular ways means to put words together using a certain style or pattern.","zh":"combine words in particular ways 指以某種風格或模式把詞語放在一起。"},{"en":"Poets combine words in surprising ways to create fresh images.","zh":"詩人以令人驚訝的方式組合詞語，創造新鮮意象。"},{"en":"If someone combines words in unusual ways, the result may sound creative or confusing.","zh":"如果某人以不尋常方式組合詞語，結果可能聽起來有創意或令人困惑。"},{"en":"This phrase focuses on how language is arranged.","zh":"這個短語集中於語言如何被安排。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":10},{"front":"nonsensical but suggestive","meaning":"無意義但富啟發性的","examples":[{"en":"The patient used words in nonsensical but suggestive ways.","zh":"該病人以無意義但富啟發性的方式使用詞語。"},{"en":"Nonsensical but suggestive means not logically meaningful, but still giving hints or impressions.","zh":"nonsensical but suggestive 指邏輯上無意義，但仍帶有暗示或印象。"},{"en":"A dream may be nonsensical but suggestive because its strange images reveal hidden feelings.","zh":"夢可能無意義但富啟發性，因為奇怪畫面揭示隱藏感受。"},{"en":"Nonsensical language can still feel suggestive if it creates mood or association.","zh":"無意義語言如果能創造氣氛或聯想，仍可能富啟發性。"},{"en":"This phrase describes something irrational yet strangely meaningful.","zh":"這個短語描述不理性卻奇特地有意味的東西。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":10},{"front":"in a sense","meaning":"在某種意義上","examples":[{"en":"In a sense, these patients resemble novelists.","zh":"在某種意義上，這些病人像小說家。"},{"en":"In a sense means in one way, or from a particular point of view.","zh":"in a sense 指在某一方面或從某個角度來看。"},{"en":"In a sense, a good teacher is also a storyteller.","zh":"在某種意義上，好老師也是說故事者。"},{"en":"This phrase allows a comparison without claiming it is completely true.","zh":"這個短語可以作比較，而不聲稱它完全正確。"},{"en":"It is useful when making a careful or limited statement.","zh":"它適合用於謹慎或有限度的說法。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":10},{"front":"resemble","meaning":"類似；像","examples":[{"en":"Confabulators resemble writers in their verbal creativity.","zh":"虛構症患者在語言創意方面像作家。"},{"en":"To resemble someone or something means to be similar to them.","zh":"resemble someone or something 指與某人或某物相似。"},{"en":"The new library resembles a glass box from the outside.","zh":"新圖書館從外面看像一個玻璃盒。"},{"en":"Two ideas may resemble each other because they share the same basic structure.","zh":"兩個想法可能因共享同一基本結構而相似。"},{"en":"This word describes similarity, not complete sameness.","zh":"這個字描述相似，而不是完全一樣。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":10},{"front":"nothing is wasted","meaning":"任何事物都不會白費","examples":[{"en":"Henry James described novelists as people on whom nothing is wasted.","zh":"亨利詹姆斯把小說家描述為任何事物都不會白費的人。"},{"en":"Nothing is wasted means every experience can become useful material.","zh":"nothing is wasted 指每種經驗都可以變成有用材料。"},{"en":"For a good writer, an awkward bus ride may become a scene, so nothing is wasted.","zh":"對好作家來說，一次尷尬巴士旅程可能變成一幕，所以任何事物都不會白費。"},{"en":"When nothing is wasted, even failure can teach a person something.","zh":"當任何事物都不會白費時，即使失敗也能教人一些東西。"},{"en":"This phrase suggests that sensitive people can turn ordinary details into meaning.","zh":"這個短語暗示敏感的人能把普通細節轉化為意義。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":10},{"front":"have little or no control over","meaning":"對……幾乎沒有控制","examples":[{"en":"Confabulators have little or no control over their material.","zh":"虛構症患者對自己的材料幾乎沒有控制。"},{"en":"To have little or no control over something means to be unable or almost unable to manage it.","zh":"have little or no control over something 指無法或幾乎無法管理某事。"},{"en":"A patient may have little or no control over sudden pain.","zh":"病人可能對突然疼痛幾乎沒有控制。"},{"en":"When people have little control over their speech, they may say things they do not intend.","zh":"當人們對自己的說話幾乎沒有控制，可能說出自己並非有意說的話。"},{"en":"This phrase shows limited power or responsibility.","zh":"這個短語顯示權力或責任有限。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":10},{"front":"the wider significance of","meaning":"……更廣泛的意義","examples":[{"en":"The wider significance of this condition lies in what it reveals about us.","zh":"這種狀況更廣泛的意義在於它揭示了關於我們的事情。"},{"en":"The wider significance of something is its larger meaning or importance beyond the immediate case.","zh":"the wider significance of something 指超出當前個案的更大意義或重要性。"},{"en":"The wider significance of one school’s success may be what it teaches other schools.","zh":"一間學校成功的更廣泛意義，可能在於它能教其他學校甚麼。"},{"en":"A small medical case can have wider significance if it reveals how the brain works.","zh":"一個小型醫學個案若揭示大腦如何運作，就可能有更廣泛意義。"},{"en":"This phrase asks readers to think beyond the obvious example.","zh":"這個短語要求讀者思考明顯例子以外的意義。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":10},{"front":"lie in","meaning":"在於","examples":[{"en":"The importance of confabulation lies in what it reveals about the mind.","zh":"虛構症的重要性在於它揭示了關於心智的事情。"},{"en":"Lie in means to be found in or depend on something.","zh":"lie in 指存在於或取決於某事。"},{"en":"The value of a good lesson lies in how clearly students understand it afterwards.","zh":"一堂好課的價值在於學生之後理解得有多清楚。"},{"en":"A problem’s solution may lie in better communication rather than stricter rules.","zh":"一個問題的解決方法可能在於更好的溝通，而不是更嚴格的規則。"},{"en":"This phrase identifies where the main importance, answer, or cause is.","zh":"這個短語指出主要重要性、答案或原因所在。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":11},{"front":"reveal something about","meaning":"揭示關於……的事情","examples":[{"en":"This condition reveals something important about human storytelling.","zh":"這種狀況揭示了關於人類說故事的重要事情。"},{"en":"To reveal something about a topic means to show or make clear hidden information about it.","zh":"reveal something about 某主題，指顯示或揭開關於它的隱藏資訊。"},{"en":"A student’s mistakes can reveal something about how they understand grammar.","zh":"學生的錯誤可以揭示他們如何理解文法。"},{"en":"Research into memory can reveal something about how people build identity.","zh":"關於記憶的研究可以揭示人們如何建立身份。"},{"en":"This phrase is useful when an example teaches us a larger lesson.","zh":"當一個例子教會我們更大教訓時，這個短語很有用。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":11},{"front":"a gushing river of","meaning":"源源不絕的……","examples":[{"en":"A gushing river of verbal creativity flows through the human mind.","zh":"源源不絕的語言創意流經人類心智。"},{"en":"A gushing river of something means a large, energetic, continuous flow of it.","zh":"a gushing river of something 指大量、有活力且持續流出的某物。"},{"en":"After the exam, students released a gushing river of complaints and jokes.","zh":"考試後，學生爆發出源源不絕的投訴和笑話。"},{"en":"This image suggests something powerful that cannot easily be stopped.","zh":"這個意象暗示某物強大而難以阻止。"},{"en":"It is a vivid metaphor for ideas, words, emotions, or activity.","zh":"它是用於想法、文字、情緒或活動的生動比喻。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":11},{"front":"verbal creativity","meaning":"語言創意","examples":[{"en":"Artistic invention and lying both depend on verbal creativity.","zh":"藝術創作和說謊都依賴語言創意。"},{"en":"Verbal creativity is the ability to use words in original, flexible, or imaginative ways.","zh":"verbal creativity 是以原創、靈活或富想像力方式使用文字的能力。"},{"en":"A child shows verbal creativity when they invent funny names for family rules.","zh":"孩子為家庭規則創造有趣名字時，就是表現語言創意。"},{"en":"Verbal creativity helps writers create voices, jokes, images, and stories.","zh":"語言創意幫助作家創造聲音、笑話、意象和故事。"},{"en":"This phrase focuses on creativity in language rather than drawing or music.","zh":"這個短語集中於語言中的創意，而不是繪畫或音樂。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":11},{"front":"flow through","meaning":"流經；貫穿","examples":[{"en":"Creativity seems to flow through the normal human mind.","zh":"創意似乎流經正常的人類心智。"},{"en":"To flow through something means to move through it smoothly or continuously.","zh":"flow through something 指順暢或持續地穿過某物。"},{"en":"Ideas may flow through a group discussion when everyone feels safe to speak.","zh":"當每個人都感到可以安全發言，想法可能在小組討論中流動。"},{"en":"When anxiety blocks thought, words may stop flowing through the mind.","zh":"當焦慮阻礙思考，文字可能不再在腦中流動。"},{"en":"This phrase often describes movement of water, ideas, energy, or feeling.","zh":"這個短語常描述水、想法、能量或情感的移動。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":11},{"front":"draw from","meaning":"從……汲取","examples":[{"en":"Both artistic invention and lying draw from the same mental source.","zh":"藝術創作和說謊都從同一心理來源汲取材料。"},{"en":"To draw from something means to take ideas, strength, material, or inspiration from it.","zh":"draw from something 指從某處取得想法、力量、材料或靈感。"},{"en":"Writers often draw from childhood memories when creating characters.","zh":"作家創造角色時，常從童年記憶汲取靈感。"},{"en":"A teacher may draw from real classroom problems to design better examples.","zh":"老師可能從真實課堂問題汲取素材，設計更好例子。"},{"en":"This phrase identifies the source that provides material or energy.","zh":"這個短語指出提供材料或能量的來源。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":11},{"front":"born storytellers","meaning":"天生的說故事者","examples":[{"en":"Human beings are born storytellers.","zh":"人類是天生的說故事者。"},{"en":"Born storytellers are people who naturally create and share stories.","zh":"born storytellers 指自然會創造並分享故事的人。"},{"en":"Children are born storytellers when they turn small toys into heroes and villains.","zh":"孩子把小玩具變成英雄和壞人時，就是天生的說故事者。"},{"en":"Because humans are born storytellers, they often explain life through plots and characters.","zh":"因為人類是天生的說故事者，他們常透過情節和角色解釋生活。"},{"en":"This phrase suggests storytelling is a natural human ability.","zh":"這個短語暗示說故事是人類的自然能力。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":11},{"front":"spin narratives from","meaning":"從……編織敘事","examples":[{"en":"We spin narratives from experience and imagination.","zh":"我們從經驗和想像中編織敘事。"},{"en":"To spin narratives from something means to create stories using that material.","zh":"spin narratives from something 指用某些材料創造故事。"},{"en":"A student may spin narratives from family memories for a creative writing task.","zh":"學生可能從家庭記憶中編織敘事，用於創意寫作任務。"},{"en":"People spin narratives from random events because stories make life feel organised.","zh":"人們從隨機事件中編織敘事，因為故事令生活感覺有秩序。"},{"en":"This phrase shows the mind turning material into story.","zh":"這個短語顯示心智把材料轉化為故事。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":11},{"front":"strain against","meaning":"努力掙脫","examples":[{"en":"Human imagination strains against the limits of reality.","zh":"人類想像力努力掙脫現實的限制。"},{"en":"To strain against something means to push hard against a limit or restriction.","zh":"strain against something 指用力抗拒某種限制或束縛。"},{"en":"A child may strain against strict rules when they want more independence.","zh":"孩子想要更多獨立時，可能努力掙脫嚴格規則。"},{"en":"Creativity strains against reality when people imagine impossible worlds.","zh":"當人們想像不可能的世界時，創意就在努力掙脫現實。"},{"en":"This phrase suggests effort, pressure, and resistance.","zh":"這個短語暗示努力、壓力和抗拒。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":11},{"front":"the leash that tethers us to reality","meaning":"把我們繫於現實的束縛","examples":[{"en":"Storytelling strains against the leash that tethers us to reality.","zh":"說故事努力掙脫把我們繫於現實的束縛。"},{"en":"The leash that tethers us to reality is a metaphor for the limits that keep imagination tied to real facts.","zh":"the leash that tethers us to reality 是一個比喻，指把想像綁在真實事實上的限制。"},{"en":"A daydream breaks against the leash that tethers us to reality when homework still must be done.","zh":"當功課仍必須完成時，白日夢會撞上把我們繫於現實的束縛。"},{"en":"Stories loosen this leash by letting people imagine lives they cannot actually live.","zh":"故事讓人想像自己不能真正經歷的人生，從而鬆開這條束縛。"},{"en":"This phrase makes reality sound like something holding the mind back.","zh":"這個短語令現實聽起來像限制心智的東西。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":11},{"front":"conceive of","meaning":"構想；想像","examples":[{"en":"Storytelling allows us to conceive of alternative futures.","zh":"說故事讓我們能構想另一種未來。"},{"en":"To conceive of something means to imagine or form an idea of it.","zh":"conceive of something 指想像或形成某事的概念。"},{"en":"A city planner must conceive of how a neighbourhood may look in twenty years.","zh":"城市規劃師必須構想一個社區二十年後的樣子。"},{"en":"If people cannot conceive of a better future, they may stop trying to change things.","zh":"如果人們無法想像更好的未來，他們可能停止嘗試改變。"},{"en":"This phrase is formal and often used for imagining possibilities.","zh":"這個短語較正式，常用於想像可能性。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":12},{"front":"alternative futures","meaning":"另一種未來","examples":[{"en":"Stories help us imagine alternative futures.","zh":"故事幫助我們想像另一種未來。"},{"en":"Alternative futures are possible futures different from the one that seems most likely now.","zh":"alternative futures 指不同於目前看似最可能未來的其他可能未來。"},{"en":"Students may imagine alternative futures when choosing subjects for university.","zh":"學生選擇大學科目時，可能想像不同的未來。"},{"en":"Thinking about alternative futures helps people prepare for change.","zh":"思考另一種未來有助人們為改變作準備。"},{"en":"This phrase is useful when discussing possibility, planning, or imagination.","zh":"這個短語適合用於討論可能性、規劃或想像。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":12},{"front":"different worlds","meaning":"不同的世界","examples":[{"en":"Art allows us to imagine different worlds.","zh":"藝術讓我們想像不同的世界。"},{"en":"Different worlds are imagined or real places with different rules, cultures, or possibilities.","zh":"different worlds 指有不同規則、文化或可能性的想像或真實地方。"},{"en":"A science-fiction film may show different worlds with unfamiliar languages and societies.","zh":"科幻電影可能展示有陌生語言和社會的不同世界。"},{"en":"Imagining different worlds helps people question the limits of their own world.","zh":"想像不同世界有助人們質疑自己世界的限制。"},{"en":"This phrase can refer to fantasy settings or very different ways of living.","zh":"這個短語可以指幻想背景，也可以指非常不同的生活方式。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":12},{"front":"lead someone into trouble","meaning":"使某人陷入麻煩","examples":[{"en":"Our creativity can lead us into trouble.","zh":"我們的創意可以使我們陷入麻煩。"},{"en":"To lead someone into trouble means to cause someone to enter a difficult or risky situation.","zh":"lead someone into trouble 指令某人進入困難或有風險的情況。"},{"en":"A careless joke can lead a student into trouble with a teacher.","zh":"一個不小心的玩笑可以使學生陷入與老師的麻煩。"},{"en":"Creativity can lead people into trouble if invented stories are presented as facts.","zh":"如果虛構故事被當成事實呈現，創意可以令人陷入麻煩。"},{"en":"This phrase shows how an action or quality can create problems.","zh":"這個短語顯示某種行動或特質如何造成問題。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":12},{"front":"persuade others that","meaning":"說服別人相信","examples":[{"en":"Problems arise when we persuade others that our inventions are real.","zh":"當我們說服別人相信我們的創作是真實的，問題就會出現。"},{"en":"To persuade others that something is true means to convince them to believe it.","zh":"persuade others that something is true 指說服別人相信某事為真。"},{"en":"An advertiser may persuade customers that a product will change their lives.","zh":"廣告人可能說服顧客相信某產品會改變他們的人生。"},{"en":"If false stories persuade others that they are real, trust can be damaged.","zh":"如果虛假故事說服別人相信它們是真實的，信任可能受損。"},{"en":"This phrase focuses on changing other people’s beliefs.","zh":"這個短語集中於改變他人的信念。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":12},{"front":"bubble into consciousness","meaning":"浮現於意識之中","examples":[{"en":"Stories bubble into consciousness in the human mind.","zh":"故事在人類心智中浮現於意識之中。"},{"en":"To bubble into consciousness means to rise gradually into awareness.","zh":"bubble into consciousness 指逐漸浮上意識。"},{"en":"A forgotten memory may bubble into consciousness when someone hears an old song.","zh":"當某人聽到一首舊歌時，被遺忘的記憶可能浮現於意識之中。"},{"en":"Ideas often bubble into consciousness when the mind is relaxed.","zh":"當心智放鬆時，想法常會浮現於意識之中。"},{"en":"This phrase makes thoughts sound as if they rise naturally from below the surface.","zh":"這個短語令思想聽起來像從表面以下自然升起。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":12},{"front":"exercise our cerebral censors","meaning":"運用大腦的審查機制","examples":[{"en":"We exercise our cerebral censors when deciding which stories to tell.","zh":"當我們決定講述哪些故事時，我們會運用大腦的審查機制。"},{"en":"To exercise our cerebral censors means to use the brain’s ability to control, check, and filter thoughts before speaking.","zh":"exercise our cerebral censors 指使用大腦在說話前控制、檢查和篩選想法的能力。"},{"en":"A student exercises cerebral censors when they decide not to say a rude joke aloud.","zh":"學生決定不把粗魯笑話說出口時，就是在運用大腦的審查機制。"},{"en":"Without this mental filtering, people might tell every imagined story as if it were true.","zh":"如果沒有這種心理篩選，人們可能把每個想像故事都當成真事講出來。"},{"en":"This phrase describes self-control inside the mind.","zh":"這個短語描述心智內部的自我控制。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":12},{"front":"controlling which stories we tell","meaning":"控制我們講述哪些故事","examples":[{"en":"We control which stories we tell and to whom.","zh":"我們控制自己講述哪些故事，以及向誰講述。"},{"en":"Controlling which stories we tell means choosing what to say, what to keep private, and who should hear it.","zh":"controlling which stories we tell 指選擇說甚麼、保留甚麼私隱，以及誰應聽到。"},{"en":"A child learns social judgement by controlling which stories they tell at home and at school.","zh":"孩子透過控制在家和學校講述哪些故事來學習社交判斷。"},{"en":"If people cannot control which stories they tell, they may reveal private or false information.","zh":"如果人們不能控制自己講述哪些故事，可能透露私隱或虛假資訊。"},{"en":"This phrase connects storytelling with responsibility.","zh":"這個短語把說故事與責任連起來。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":12},{"front":"nevertheless","meaning":"然而；儘管如此","examples":[{"en":"People nevertheless lie for many reasons.","zh":"然而，人們仍因許多理由說謊。"},{"en":"Nevertheless means however, despite what has just been said.","zh":"nevertheless 意思是「然而」，表示儘管剛才所說如此。"},{"en":"The task was difficult; nevertheless, the class finished it together.","zh":"任務很困難；然而，全班一起完成了它。"},{"en":"People know lying can damage trust; nevertheless, they may lie to avoid shame.","zh":"人們知道說謊會破壞信任；然而，他們可能為避免羞愧而說謊。"},{"en":"This word introduces a contrast between expectation and reality.","zh":"這個字引出預期與現實之間的對比。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":12},{"front":"dangerously enjoyable","meaning":"危險地令人享受","examples":[{"en":"Confabulation can be dangerously enjoyable.","zh":"虛構症可能危險地令人享受。"},{"en":"Dangerously enjoyable means pleasurable in a way that may cause harm or risk.","zh":"dangerously enjoyable 指令人愉快，但愉快本身可能帶來傷害或風險。"},{"en":"Spending money online can be dangerously enjoyable when each purchase feels small.","zh":"網上購物可能危險地令人享受，因為每次購買都感覺金額很小。"},{"en":"A behaviour that is dangerously enjoyable may continue even after it creates problems.","zh":"危險地令人享受的行為即使造成問題，也可能繼續。"},{"en":"This phrase warns that pleasure can make danger harder to resist.","zh":"這個短語提醒人們，快感會令危險更難抗拒。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":12},{"front":"a now-famous libel case","meaning":"現已著名的誹謗案","examples":[{"en":"A now-famous libel case in 1996 involved Jonathan Aitken.","zh":"1996年一宗現已著名的誹謗案涉及 Jonathan Aitken。"},{"en":"A now-famous libel case is a legal case about damaging false statements that later became widely known.","zh":"a now-famous libel case 指一宗關於損害名譽的虛假陳述、後來廣為人知的法律案件。"},{"en":"A journalist may study a now-famous libel case to learn the risks of publishing accusations.","zh":"記者可能研究現已著名的誹謗案，以了解刊登指控的風險。"},{"en":"A libel case can become famous when it involves public figures and dramatic evidence.","zh":"當誹謗案涉及公眾人物和戲劇性證據時，可能變得著名。"},{"en":"This phrase combines legal conflict with public attention.","zh":"這個短語結合法律衝突與公眾關注。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":13},{"front":"former cabinet minister","meaning":"前內閣大臣","examples":[{"en":"Jonathan Aitken was a former cabinet minister.","zh":"Jonathan Aitken 是前內閣大臣。"},{"en":"A former cabinet minister is someone who once held a senior government position but no longer does.","zh":"former cabinet minister 指曾擔任高級政府職位但現已不再擔任的人。"},{"en":"A former cabinet minister may still influence public debate through speeches or articles.","zh":"前內閣大臣仍可能透過演說或文章影響公共討論。"},{"en":"When a former cabinet minister is involved in scandal, the case may attract media attention.","zh":"當前內閣大臣牽涉醜聞，案件可能吸引媒體關注。"},{"en":"This phrase gives a person’s previous political status.","zh":"這個短語交代某人過去的政治身份。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":13},{"front":"recount a story","meaning":"講述一個故事","examples":[{"en":"Aitken recounted a story to illustrate what he had endured.","zh":"Aitken 講述一個故事，以說明自己承受了甚麼。"},{"en":"To recount a story means to tell or describe it, usually in some detail.","zh":"recount a story 指講述或描述一個故事，通常帶有一定細節。"},{"en":"A grandfather may recount a story from his childhood at dinner.","zh":"祖父可能在晚飯時講述一個童年故事。"},{"en":"Recounting a story can help listeners understand what someone experienced.","zh":"講述故事可以幫助聽者理解某人經歷了甚麼。"},{"en":"This phrase is more formal than simply saying “tell a story”.","zh":"這個短語比 simply saying “tell a story” 更正式。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":13},{"front":"illustrate","meaning":"說明；闡明","examples":[{"en":"He told the story to illustrate the damage done to his reputation.","zh":"他講述這個故事，以說明其名譽受到的損害。"},{"en":"To illustrate means to explain or show something clearly using an example.","zh":"illustrate 指用例子清楚解釋或展示某事。"},{"en":"A teacher may use a simple diagram to illustrate how the heart works.","zh":"老師可能用簡單圖表說明心臟如何運作。"},{"en":"Real examples illustrate abstract ideas and make them easier to understand.","zh":"真實例子可以闡明抽象概念，使其更容易理解。"},{"en":"This verb often introduces the purpose of an example.","zh":"這個動詞常用來引出例子的目的。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":13},{"front":"the horrors someone had endured","meaning":"某人所承受的痛苦經歷","examples":[{"en":"Aitken described the horrors he had endured after the newspaper report.","zh":"Aitken 描述報章報道後自己所承受的痛苦經歷。"},{"en":"The horrors someone had endured are the terrible experiences someone suffered through.","zh":"the horrors someone had endured 指某人經歷並承受過的可怕事情。"},{"en":"A refugee may describe the horrors they had endured during war.","zh":"難民可能描述自己在戰爭中所承受的痛苦經歷。"},{"en":"Describing endured horrors can make listeners understand the emotional cost of an event.","zh":"描述所承受的痛苦經歷，可以令聽者理解事件的情感代價。"},{"en":"This phrase is dramatic and usually refers to serious suffering.","zh":"這個短語具戲劇性，通常指嚴重痛苦。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":13},{"front":"a national newspaper","meaning":"全國性報章","examples":[{"en":"A national newspaper had published claims about Aitken.","zh":"一份全國性報章刊登了關於 Aitken 的指稱。"},{"en":"A national newspaper is a newspaper distributed across a whole country.","zh":"national newspaper 指在整個國家發行的報章。"},{"en":"A national newspaper may influence public opinion more than a small local paper.","zh":"全國性報章可能比小型地方報章更能影響公眾意見。"},{"en":"When a national newspaper publishes serious accusations, the story can spread quickly.","zh":"當全國性報章刊登嚴重指控，消息可以迅速傳開。"},{"en":"This phrase contrasts nationwide media with local media.","zh":"這個短語把全國媒體與地方媒體作對比。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":13},{"front":"taint someone’s name","meaning":"玷污某人的名聲","examples":[{"en":"Aitken claimed that the newspaper had tainted his name.","zh":"Aitken 聲稱該報章玷污了他的名聲。"},{"en":"To taint someone’s name means to damage their reputation or make people think badly of them.","zh":"taint someone’s name 指損害某人的名譽，令別人對其有負面看法。"},{"en":"A false rumour can taint a teacher’s name even after it is corrected.","zh":"虛假謠言即使被更正，也可能玷污老師的名聲。"},{"en":"Once someone’s name is tainted, trust may be difficult to rebuild.","zh":"一旦某人的名聲被玷污，信任可能難以重建。"},{"en":"This phrase connects public reputation with moral damage.","zh":"這個短語把公眾名譽與道德損害連起來。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":13},{"front":"last more than two years","meaning":"持續超過兩年","examples":[{"en":"The case lasted more than two years.","zh":"該案件持續超過兩年。"},{"en":"To last more than two years means to continue for longer than two years.","zh":"last more than two years 指持續時間超過兩年。"},{"en":"A construction project may last more than two years if there are delays.","zh":"如果出現延誤，建築項目可能持續超過兩年。"},{"en":"Long cases can exhaust people because the pressure lasts for a long time.","zh":"漫長案件會令人疲累，因為壓力持續很久。"},{"en":"This phrase focuses on duration.","zh":"這個短語集中於持續時間。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":13},{"front":"concern claims by","meaning":"涉及……提出的指稱","examples":[{"en":"The case concerned claims by The Guardian.","zh":"該案件涉及《衛報》提出的指稱。"},{"en":"To concern claims by someone means to be about accusations or statements made by that person or organisation.","zh":"concern claims by someone 指關於某人或某機構提出的指控或說法。"},{"en":"The meeting concerned complaints by parents about school transport.","zh":"會議涉及家長提出的校車投訴。"},{"en":"If a legal case concerns claims by a newspaper, the truth of those claims becomes central.","zh":"如果法律案件涉及報章提出的指稱，這些指稱的真實性就成為核心。"},{"en":"This phrase identifies what the dispute is about and who made the claims.","zh":"這個短語指出爭議內容以及提出指稱的人。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":13},{"front":"Saudi arms dealers","meaning":"沙特軍火商","examples":[{"en":"The claims involved Aitken’s relationships with Saudi arms dealers.","zh":"這些指稱涉及 Aitken 與沙特軍火商的關係。"},{"en":"Saudi arms dealers are people from or connected with Saudi Arabia who trade weapons.","zh":"Saudi arms dealers 指來自或與沙特阿拉伯有關、買賣武器的人。"},{"en":"Arms dealers may become controversial because weapons can be linked to politics and conflict.","zh":"軍火商可能具爭議性，因為武器可與政治和衝突有關。"},{"en":"Relationships with arms dealers may attract suspicion when a person holds public office.","zh":"當某人擔任公職時，與軍火商的關係可能引起懷疑。"},{"en":"This phrase combines nationality, business, and the weapons trade.","zh":"這個短語結合國籍、商業和武器交易。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":13},{"front":"allegedly held","meaning":"據稱舉行","examples":[{"en":"The meetings were allegedly held during a trip to Paris.","zh":"據稱這些會議在一次巴黎之行期間舉行。"},{"en":"Allegedly held means said to have taken place, but not yet proven or accepted as fact.","zh":"allegedly held 指據稱曾發生，但尚未被證明或接受為事實。"},{"en":"The meeting was allegedly held in a private hotel room.","zh":"據稱會議在私人酒店房間舉行。"},{"en":"Journalists use allegedly when reporting claims that may later be challenged.","zh":"記者報道日後可能被質疑的指稱時，會使用 allegedly。"},{"en":"This phrase protects the distinction between accusation and confirmed fact.","zh":"這個短語保留指控與已確認事實之間的區別。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":14},{"front":"while serving as","meaning":"在擔任……期間","examples":[{"en":"Aitken allegedly held meetings while serving as a government minister.","zh":"據稱 Aitken 在擔任政府大臣期間舉行會議。"},{"en":"While serving as means during the time someone held a particular role or position.","zh":"while serving as 指在某人擔任某角色或職位期間。"},{"en":"A teacher may write a textbook while serving as head of department.","zh":"老師可能在擔任部門主任期間撰寫教科書。"},{"en":"Actions taken while serving as a public official may be judged more strictly.","zh":"在擔任公職期間作出的行為，可能受到更嚴格評價。"},{"en":"This phrase connects an action with someone’s official role at the time.","zh":"這個短語把某行動與當時的官方身份連起來。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":14},{"front":"a government minister","meaning":"政府大臣","examples":[{"en":"Aitken was serving as a government minister during the Paris trip.","zh":"Aitken 在巴黎之行期間擔任政府大臣。"},{"en":"A government minister is a senior politician responsible for a government department or policy area.","zh":"government minister 是負責政府部門或政策範疇的高級政治人物。"},{"en":"A health minister may be responsible for hospitals and public health policy.","zh":"衛生大臣可能負責醫院和公共衛生政策。"},{"en":"Government ministers are expected to avoid conflicts of interest.","zh":"政府大臣被期望避免利益衝突。"},{"en":"This phrase describes a high-level public role.","zh":"這個短語描述高層公共職位。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":14},{"front":"what later amazed many people was","meaning":"後來令很多人驚訝的是","examples":[{"en":"What later amazed many people was the sheer superfluity of the lies.","zh":"後來令很多人驚訝的是那些謊言極其不必要。"},{"en":"What later amazed many people was means the thing that surprised many people afterwards was.","zh":"what later amazed many people was 意思是後來令很多人感到驚訝的是。"},{"en":"What later amazed many people was how small the original mistake had been.","zh":"後來令很多人驚訝的是，最初的錯誤竟然如此小。"},{"en":"This structure highlights the most surprising part of a story.","zh":"這個句式突出故事中最令人驚訝的部分。"},{"en":"It is useful when the real shock appears after more facts are known.","zh":"當更多事實出現後真正震驚之處才顯現時，這個句式很有用。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":14},{"front":"the sheer superfluity of","meaning":"完全多餘；極其不必要","examples":[{"en":"Observers were struck by the sheer superfluity of Aitken’s lies.","zh":"觀察者對 Aitken 謊言的極其多餘感到震驚。"},{"en":"The sheer superfluity of something means the extreme and obvious excess or unnecessary amount of it.","zh":"the sheer superfluity of something 指某事物極度明顯的過量或不必要。"},{"en":"A teacher may be annoyed by the sheer superfluity of excuses when one honest explanation would be enough.","zh":"當一個誠實解釋已足夠時，老師可能對大量多餘藉口感到惱怒。"},{"en":"Superfluous details can make a lie riskier because there is more to disprove.","zh":"多餘細節會令謊言更危險，因為可被推翻的內容更多。"},{"en":"This phrase strongly criticises something as excessive and unnecessary.","zh":"這個短語強烈批評某事過量而不必要。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":14},{"front":"testimony","meaning":"證詞","examples":[{"en":"Aitken’s testimony contained many unnecessary lies.","zh":"Aitken 的證詞包含許多不必要的謊言。"},{"en":"Testimony is a formal statement given in court or to an official investigation.","zh":"testimony 指在法庭或正式調查中給出的正式陳述。"},{"en":"A witness gives testimony to explain what they saw or know.","zh":"證人給出證詞，以解釋自己看見或知道的事。"},{"en":"False testimony can seriously affect justice.","zh":"虛假證詞可以嚴重影響司法公正。"},{"en":"This word is mainly used in legal or official contexts.","zh":"這個字主要用於法律或官方語境。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":14},{"front":"case collapsed","meaning":"案件敗訴；訴訟崩潰","examples":[{"en":"Aitken’s case collapsed in June 1997.","zh":"Aitken 的案件在1997年6月敗訴。"},{"en":"If a case collapses, it fails because the argument or evidence can no longer support it.","zh":"If a case collapses 指案件因論點或證據無法再支持而失敗。"},{"en":"A court case may collapse when a key witness admits they lied.","zh":"當關鍵證人承認說謊時，法庭案件可能崩潰。"},{"en":"Once strong opposing evidence appears, a case can collapse quickly.","zh":"一旦強而有力的反證出現，案件可以迅速崩潰。"},{"en":"This phrase suggests a legal or argumentative failure.","zh":"這個短語暗示法律或論證上的失敗。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":14},{"front":"indisputable evidence","meaning":"無可爭辯的證據","examples":[{"en":"The defence found indisputable evidence about his Paris trip.","zh":"辯方找到關於他巴黎之行的無可爭辯證據。"},{"en":"Indisputable evidence is evidence so strong that it is very difficult to deny or argue against.","zh":"indisputable evidence 指非常有力、很難否認或反駁的證據。"},{"en":"A clear video recording may be indisputable evidence of what happened.","zh":"清楚錄像可能是事情經過的無可爭辯證據。"},{"en":"Indisputable evidence can end a debate because it removes reasonable doubt.","zh":"無可爭辯證據可以終結爭論，因為它消除合理懷疑。"},{"en":"This phrase is used when proof is extremely convincing.","zh":"這個短語用於證據極具說服力時。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":14},{"front":"until then","meaning":"在那之前","examples":[{"en":"Until then, Aitken’s performance had made victory seem possible.","zh":"在那之前，Aitken 的表現令勝利看似可能。"},{"en":"Until then means up to that time.","zh":"until then 指直到那個時間為止。"},{"en":"The class was noisy; until then, the teacher had believed the activity was working.","zh":"班上很嘈吵；在那之前，老師一直以為活動運作良好。"},{"en":"A situation can seem hopeful until new evidence changes everything.","zh":"情況可以一直看似有希望，直到新證據改變一切。"},{"en":"This phrase marks the moment before a turning point.","zh":"這個短語標示轉折點之前的時刻。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":14},{"front":"charm, fluency and flair","meaning":"魅力、流暢表達和天分","examples":[{"en":"Aitken’s charm, fluency and flair made his testimony seem convincing.","zh":"Aitken 的魅力、流暢表達和天分令他的證詞看似可信。"},{"en":"Charm, fluency and flair are attractiveness, smooth expression, and stylish skill.","zh":"charm, fluency and flair 指吸引力、流暢表達和有風格的技巧。"},{"en":"A speaker with charm, fluency and flair can hold an audience’s attention.","zh":"具魅力、流暢表達和天分的演講者，可以吸引觀眾注意。"},{"en":"These qualities can make weak content sound stronger than it is.","zh":"這些特質可以令薄弱內容聽起來比實際更強。"},{"en":"This phrase describes performance skill and personal style.","zh":"這個短語描述表現技巧和個人風格。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":14},{"front":"theatrical displays of sincerity","meaning":"戲劇化地表現真誠","examples":[{"en":"Aitken gave theatrical displays of sincerity in court.","zh":"Aitken 在庭上戲劇化地表現真誠。"},{"en":"Theatrical displays of sincerity are dramatic performances meant to show honesty or deep feeling.","zh":"theatrical displays of sincerity 指以戲劇化方式表現誠實或深切感受。"},{"en":"A student might make a theatrical display of sincerity when apologising loudly in front of everyone.","zh":"學生在所有人面前大聲道歉時，可能是在戲劇化地表現真誠。"},{"en":"Such displays may persuade people emotionally, even if the facts are weak.","zh":"這類表現可以在情感上說服人，即使事實薄弱。"},{"en":"This phrase suggests sincerity is being performed, not simply felt.","zh":"這個短語暗示真誠正在被表演，而不只是被感受。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":15},{"front":"make victory seem possible","meaning":"令勝利看似可能","examples":[{"en":"His performance made victory seem possible.","zh":"他的表現令勝利看似可能。"},{"en":"To make victory seem possible means to create the impression that winning could happen.","zh":"make victory seem possible 指令人覺得勝利有可能發生。"},{"en":"A strong first half made victory seem possible for the losing team.","zh":"出色的上半場令落後球隊覺得勝利看似可能。"},{"en":"Confidence and style can make victory seem possible even when the facts are weak.","zh":"信心和風格可以令勝利看似可能，即使事實薄弱。"},{"en":"This phrase describes hope created by appearance or performance.","zh":"這個短語描述由外表或表現創造出來的希望。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":15},{"front":"reveal not only that…but also that…","meaning":"不但揭示……而且揭示……","examples":[{"en":"The evidence revealed not only that his daughter was absent, but also that no car followed him.","zh":"證據不但揭示他的女兒不在場，而且揭示沒有車跟蹤他。"},{"en":"Reveal not only that…but also that… is a structure showing two pieces of information, with the second adding more force.","zh":"reveal not only that…but also that… 是顯示兩項資訊的句式，第二項增加力度。"},{"en":"The test revealed not only that the machine was old, but also that it was unsafe.","zh":"測試不但揭示機器老舊，而且揭示它不安全。"},{"en":"This structure helps build a stronger argument by adding a second important fact.","zh":"這個句式透過加入第二個重要事實，令論證更有力。"},{"en":"It is useful when evidence proves more than one thing.","zh":"當證據證明不止一件事時，這個句式很有用。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":15},{"front":"get into his car","meaning":"上車","examples":[{"en":"The evidence showed that Aitken simply got into his car and drove away.","zh":"證據顯示 Aitken 只是上車然後駕車離開。"},{"en":"To get into a car means to enter the car.","zh":"get into a car 指進入車內。"},{"en":"After school, the child got into his father’s car outside the gate.","zh":"放學後，孩子在校門外上了父親的車。"},{"en":"This phrase often describes the beginning of a journey by car.","zh":"這個短語常描述乘車旅程的開始。"},{"en":"In this passage, the simple action contrasts with a more dramatic false story.","zh":"在這篇文章中，這個簡單動作與更戲劇化的虛假故事形成對比。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":15},{"front":"drive away","meaning":"駕車離開","examples":[{"en":"Aitken got into his car and drove away.","zh":"Aitken 上車並駕車離開。"},{"en":"To drive away means to leave a place by driving a vehicle.","zh":"drive away 指駕駛車輛離開某地。"},{"en":"The taxi drove away after dropping the passenger at the station.","zh":"的士把乘客送到車站後駕車離開。"},{"en":"Driving away can end a scene because the person physically leaves.","zh":"駕車離開可以結束一幕，因為人物實際離開現場。"},{"en":"This phrase is simple but useful for describing movement away from a place.","zh":"這個短語簡單，但適合描述從某地離開的動作。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":15},{"front":"with no vehicle pursuing him","meaning":"沒有車輛追趕他","examples":[{"en":"Aitken drove away with no vehicle pursuing him.","zh":"Aitken 駕車離開，沒有車輛追趕他。"},{"en":"With no vehicle pursuing him means no car or other vehicle was following or chasing him.","zh":"with no vehicle pursuing him 指沒有汽車或其他車輛跟蹤或追趕他。"},{"en":"The cyclist reached home with no dog pursuing him.","zh":"單車手回到家時，沒有狗追趕他。"},{"en":"This detail can disprove a story about being chased.","zh":"這個細節可以推翻關於被追趕的故事。"},{"en":"The phrase adds evidence by showing what was absent.","zh":"這個短語透過顯示不存在的東西來增加證據。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":15},{"front":"unlike","meaning":"不像；與……不同","examples":[{"en":"Unlike Aitken, artists are not literally trying to deceive us.","zh":"不像 Aitken，藝術家並非真正試圖欺騙我們。"},{"en":"Unlike means different from or in contrast with.","zh":"unlike 指不像或與……不同。"},{"en":"Unlike his brother, Tom enjoys speaking in front of large groups.","zh":"與哥哥不同，Tom 喜歡在大群人面前說話。"},{"en":"This word helps compare two people or things by showing a difference.","zh":"這個字透過顯示差異來幫助比較兩個人或事物。"},{"en":"It is often placed at the beginning of a sentence to introduce contrast.","zh":"它常放在句首引出對比。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":15},{"front":"not literally trying to","meaning":"並非真正試圖","examples":[{"en":"Actors and novelists are not literally trying to deceive us.","zh":"演員和小說家並非真正試圖欺騙我們。"},{"en":"Not literally trying to means not actually or directly attempting to do something.","zh":"not literally trying to 指並非實際或直接嘗試做某事。"},{"en":"A teacher who says “your brain is a muscle” is not literally trying to describe anatomy.","zh":"老師說「你的大腦是一塊肌肉」時，並非真正試圖描述解剖學。"},{"en":"Artists may present false events, but they are not literally trying to trick the audience.","zh":"藝術家可能呈現虛假事件，但並非真正試圖欺騙觀眾。"},{"en":"This phrase separates metaphor or fiction from real intention.","zh":"這個短語把比喻或虛構與真實意圖分開。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":15},{"front":"the rules are stated in advance","meaning":"規則事先說明","examples":[{"en":"In art, the rules are stated in advance.","zh":"在藝術中，規則是事先說明的。"},{"en":"The rules are stated in advance means people are told the conditions before they take part.","zh":"the rules are stated in advance 指人們在參與前已被告知條件。"},{"en":"In a classroom game, the rules are stated in advance so students know what is fair.","zh":"在課堂遊戲中，規則事先說明，學生才知道甚麼公平。"},{"en":"When the rules are clear in advance, people cannot easily claim they were tricked.","zh":"當規則事先清楚，人們較難聲稱自己被欺騙。"},{"en":"This phrase explains why artistic illusion is different from deception.","zh":"這個短語解釋為何藝術幻象不同於欺騙。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":15},{"front":"come to the theatre","meaning":"來到劇院","examples":[{"en":"When people come to the theatre, they accept artistic illusion.","zh":"當人們來到劇院時，他們接受藝術幻象。"},{"en":"To come to the theatre means to attend a live performance in a theatre.","zh":"come to the theatre 指到劇院觀看現場表演。"},{"en":"Families may come to the theatre to watch a school drama.","zh":"家庭可能來到劇院觀看學校戲劇。"},{"en":"People who come to the theatre know the actors are pretending.","zh":"來到劇院的人知道演員在假裝。"},{"en":"This phrase sets the context for shared make-believe.","zh":"這個短語設定了共同相信虛構的情境。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":15},{"front":"open this book","meaning":"打開這本書","examples":[{"en":"When readers open this book, they understand that fiction is involved.","zh":"當讀者打開這本書時，他們明白其中涉及虛構。"},{"en":"To open this book means to begin reading the book in front of the reader.","zh":"open this book 指開始閱讀讀者面前的這本書。"},{"en":"When you open a novel, you usually accept that some events are invented.","zh":"當你打開一本小說時，通常會接受其中有些事件是虛構的。"},{"en":"Opening a book begins a contract between writer and reader.","zh":"打開一本書開始了作者與讀者之間的契約。"},{"en":"This phrase can invite readers directly into an argument or story.","zh":"這個短語可以直接邀請讀者進入論點或故事。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":16},{"front":"feel it necessary to","meaning":"認為有必要去","examples":[{"en":"Humans felt it necessary to invent art.","zh":"人類認為有必要創造藝術。"},{"en":"To feel it necessary to do something means to believe that doing it is needed.","zh":"feel it necessary to do something 指相信有需要做某事。"},{"en":"A teacher may feel it necessary to call parents when a student is often absent.","zh":"當學生經常缺席時，老師可能認為有必要聯絡家長。"},{"en":"People feel it necessary to create rules when behaviour becomes risky.","zh":"當行為變得有風險時，人們會認為有必要制定規則。"},{"en":"This phrase shows a sense of need, not just preference.","zh":"這個短語顯示需要感，而不只是偏好。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":16},{"front":"invent art","meaning":"創造藝術","examples":[{"en":"The writer suggests that people invented art to manage the impulse to lie.","zh":"作者暗示人們創造藝術是為了管理說謊衝動。"},{"en":"To invent art means to create artistic forms such as stories, drama, music, or images.","zh":"invent art 指創造故事、戲劇、音樂或圖像等藝術形式。"},{"en":"Early communities may have invented art to share memory, fear, and belief.","zh":"早期社群可能創造藝術來分享記憶、恐懼和信念。"},{"en":"Inventing art gives imagination a public and meaningful form.","zh":"創造藝術給想像力一種公共而有意義的形式。"},{"en":"This phrase treats art as something humans created to meet a deep need.","zh":"這個短語把藝術視為人類為滿足深層需要而創造的東西。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":16},{"front":"a safe space","meaning":"安全空間","examples":[{"en":"Art provides a safe space for imaginative lies.","zh":"藝術為想像中的謊言提供安全空間。"},{"en":"A safe space is a place or situation where people can explore ideas or feelings without serious harm.","zh":"safe space 指人們可以探索想法或感受而不會受到嚴重傷害的地方或情況。"},{"en":"A classroom discussion can be a safe space if students are not mocked for mistakes.","zh":"如果學生不會因錯誤被嘲笑，課堂討論可以是安全空間。"},{"en":"Art creates a safe space because audiences know the story is not literal reality.","zh":"藝術創造安全空間，因為觀眾知道故事不是字面現實。"},{"en":"This phrase suggests protection, permission, and emotional safety.","zh":"這個短語暗示保護、許可和情感安全。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":16},{"front":"be corralled and channelled into","meaning":"被約束並引導至","examples":[{"en":"In art, lies can be corralled and channelled into something useful.","zh":"在藝術中，謊言可以被約束並引導成有用的東西。"},{"en":"To be corralled and channelled into something means to be controlled and directed toward a particular purpose.","zh":"be corralled and channelled into something 指被控制並引導到某個特定目的。"},{"en":"A child’s wild energy can be corralled and channelled into sport or dance.","zh":"孩子旺盛的精力可以被約束並引導至運動或舞蹈。"},{"en":"When imagination is channelled into art, it can become meaningful instead of harmful.","zh":"當想像力被引導進藝術，它可以變得有意義，而不是有害。"},{"en":"This phrase suggests turning uncontrolled force into organised use.","zh":"這個短語暗示把不受控制的力量轉化為有組織的用途。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":16},{"front":"socially useful","meaning":"對社會有用的","examples":[{"en":"Art turns imaginative lies into something socially useful.","zh":"藝術把想像中的謊言轉化為對社會有用的東西。"},{"en":"Socially useful means helpful to society or to the way people live together.","zh":"socially useful 指對社會或人們共同生活方式有幫助。"},{"en":"Public libraries are socially useful because they give everyone access to knowledge.","zh":"公共圖書館對社會有用，因為它們讓每個人取得知識。"},{"en":"Stories can be socially useful when they help people discuss fear, love, or injustice.","zh":"當故事幫助人討論恐懼、愛或不公時，它們可以對社會有用。"},{"en":"This phrase shows value beyond private enjoyment.","zh":"這個短語顯示超越私人享受的價值。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":16},{"front":"given the universal compulsion to","meaning":"鑑於普遍存在……的衝動","examples":[{"en":"Given the universal compulsion to tell stories, art has an important role.","zh":"鑑於普遍存在說故事的衝動，藝術有重要作用。"},{"en":"Given the universal compulsion to do something means considering that nearly everyone feels a strong urge to do it.","zh":"given the universal compulsion to do something 指考慮到幾乎所有人都有強烈衝動去做某事。"},{"en":"Given the universal compulsion to share news, social media spreads information very quickly.","zh":"鑑於普遍存在分享消息的衝動，社交媒體令資訊迅速傳播。"},{"en":"If a desire is universal, societies may create safe forms for expressing it.","zh":"如果某種慾望普遍存在，社會可能創造安全形式去表達它。"},{"en":"This phrase introduces a reason based on a common human tendency.","zh":"這個短語基於共同人類傾向引出原因。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":16},{"front":"refine and enjoy","meaning":"提煉並欣賞","examples":[{"en":"Art allows us to refine and enjoy unusual stories.","zh":"藝術讓我們提煉並欣賞不尋常的故事。"},{"en":"To refine and enjoy something means to improve it carefully and take pleasure in it.","zh":"refine and enjoy something 指仔細改善某物並從中得到樂趣。"},{"en":"A writer may refine and enjoy a strange idea until it becomes a strong story.","zh":"作家可能提煉並欣賞一個奇怪想法，直到它變成有力故事。"},{"en":"Refining a rough idea can make it clearer, deeper, and more valuable.","zh":"提煉粗略想法可以令它更清楚、更深刻和更有價值。"},{"en":"This phrase connects careful improvement with pleasure.","zh":"這個短語把仔細改善與享受連起來。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":16},{"front":"outlandish or insightful","meaning":"荒誕離奇或富有洞察力的","examples":[{"en":"Art helps us enjoy stories that are outlandish or insightful.","zh":"藝術幫助我們欣賞荒誕離奇或富有洞察力的故事。"},{"en":"Outlandish or insightful means either very strange and unusual or full of deep understanding.","zh":"outlandish or insightful 指非常奇怪不尋常，或充滿深刻理解。"},{"en":"A science-fiction film may be outlandish but still insightful about loneliness.","zh":"科幻電影可能荒誕離奇，但仍對孤獨有洞察力。"},{"en":"Strange stories can be valuable when they reveal something true about human life.","zh":"奇怪故事如果揭示人類生活中的真相，也可以有價值。"},{"en":"This phrase captures two different kinds of artistic power: wild imagination and deep understanding.","zh":"這個短語捕捉兩種藝術力量：狂野想像和深刻理解。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":16},{"front":"not the whole story","meaning":"並非全部原因","examples":[{"en":"The writer says that this is not the whole story.","zh":"作者說這並非全部原因。"},{"en":"Not the whole story means not the complete explanation.","zh":"not the whole story 指不是完整解釋。"},{"en":"Good exam results are important, but they are not the whole story of education.","zh":"好考試成績很重要，但並非教育的全部。"},{"en":"When one reason is not the whole story, other causes must also be considered.","zh":"當一個理由並非全部原因時，也必須考慮其他原因。"},{"en":"This phrase warns that a simple answer may be incomplete.","zh":"這個短語提醒簡單答案可能不完整。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":16},{"front":"differ from","meaning":"與……不同","examples":[{"en":"Artistic lies differ from ordinary lies.","zh":"藝術性的謊言與普通謊言不同。"},{"en":"To differ from something means to be different from it.","zh":"differ from something 指與某事不同。"},{"en":"Online lessons differ from classroom lessons because students and teachers are not in the same room.","zh":"網課與實體課不同，因為學生和老師不在同一房間。"},{"en":"Two ideas may seem similar but differ from each other in purpose.","zh":"兩個想法可能看似相似，但目的不同。"},{"en":"This phrase is useful for making clear distinctions.","zh":"這個短語適合用來作清楚區分。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":17},{"front":"ordinary lies","meaning":"普通謊言","examples":[{"en":"Artistic lies differ from ordinary lies.","zh":"藝術性的謊言與普通謊言不同。"},{"en":"Ordinary lies are everyday false statements told to deceive or avoid consequences.","zh":"ordinary lies 指日常為欺騙或逃避後果而說出的虛假陳述。"},{"en":"A child telling a parent they finished homework when they did not is telling an ordinary lie.","zh":"孩子沒有完成功課卻告訴父母完成了，就是在說普通謊言。"},{"en":"Ordinary lies usually serve the liar’s own interest.","zh":"普通謊言通常服務說謊者自己的利益。"},{"en":"This phrase contrasts common deception with artistic fiction.","zh":"這個短語把常見欺騙與藝術虛構作對比。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":17},{"front":"meaning and resonance","meaning":"意義和共鳴","examples":[{"en":"Artistic lies have meaning and resonance beyond their creator.","zh":"藝術性的謊言具有超越創作者本人的意義和共鳴。"},{"en":"Meaning and resonance are deeper significance and emotional or intellectual impact.","zh":"meaning and resonance 指更深層意義，以及情感或思想上的影響。"},{"en":"A simple family story can have meaning and resonance for anyone who has felt loss.","zh":"一個簡單家庭故事可以對任何經歷過失去的人產生意義和共鳴。"},{"en":"Art gains resonance when audiences connect it to their own lives.","zh":"當觀眾把藝術連繫到自己生活時，它就會產生共鳴。"},{"en":"This phrase describes why a work continues to matter after it is made.","zh":"這個短語描述作品完成後為何仍然重要。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":17},{"front":"beyond their creator","meaning":"超越創作者本人","examples":[{"en":"Artistic stories can have meaning beyond their creator.","zh":"藝術故事可以具有超越創作者本人的意義。"},{"en":"Beyond their creator means reaching further than the person who made them.","zh":"beyond their creator 指影響超出創造它們的人。"},{"en":"A song may carry meaning beyond its creator when listeners use it during personal grief.","zh":"當聽眾在個人悲傷中使用一首歌，它可能承載超越創作者本人的意義。"},{"en":"Art becomes powerful when it speaks to people the artist has never met.","zh":"當藝術能觸動藝術家從未見過的人，它就變得有力量。"},{"en":"This phrase suggests that a work can belong emotionally to many people.","zh":"這個短語暗示作品在情感上可以屬於很多人。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":17},{"front":"on one’s own behalf","meaning":"為自己；代表自己","examples":[{"en":"A liar lies on his own behalf.","zh":"說謊者為自己說謊。"},{"en":"On one’s own behalf means for one’s own interest, benefit, or protection.","zh":"on one’s own behalf 指為自己的利益、好處或保護自己。"},{"en":"A student may speak on her own behalf when explaining why she missed class.","zh":"學生解釋自己為何缺課時，可能為自己發言。"},{"en":"Someone who lies on their own behalf usually tries to protect themselves.","zh":"為自己說謊的人通常想保護自己。"},{"en":"This phrase contrasts self-interest with acting for others.","zh":"這個短語把自我利益與為他人行動作對比。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":17},{"front":"on behalf of everyone","meaning":"代表所有人","examples":[{"en":"An artist tells lies on behalf of everyone.","zh":"藝術家代表所有人說謊。"},{"en":"On behalf of everyone means representing or serving all people, not just oneself.","zh":"on behalf of everyone 指代表或服務所有人，而不只是自己。"},{"en":"A class representative may speak on behalf of everyone during a meeting.","zh":"班代表可能在會議中代表所有人發言。"},{"en":"Art can speak on behalf of everyone when it expresses shared fear, hope, or pain.","zh":"當藝術表達共同恐懼、希望或痛苦時，它可以代表所有人發聲。"},{"en":"This phrase suggests public or collective meaning.","zh":"這個短語暗示公共或集體意義。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":17},{"front":"compel themselves to","meaning":"迫使自己去","examples":[{"en":"Writers compel themselves to find insights into the human condition.","zh":"作家迫使自己尋找對人類處境的洞察。"},{"en":"To compel themselves to do something means to force themselves to do it through discipline or inner pressure.","zh":"compel themselves to do something 指透過紀律或內在壓力迫使自己做某事。"},{"en":"A student may compel themselves to revise even when they feel tired.","zh":"學生即使感到疲倦，也可能迫使自己溫習。"},{"en":"Writers may compel themselves to keep searching until a story reveals deeper truth.","zh":"作家可能迫使自己不斷尋找，直到故事揭示更深真相。"},{"en":"This phrase shows self-discipline or inner necessity.","zh":"這個短語顯示自律或內在必要性。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":17},{"front":"find insights into","meaning":"找出對……的洞察","examples":[{"en":"Writers try to find insights into the human condition.","zh":"作家嘗試找出對人類處境的洞察。"},{"en":"To find insights into something means to discover deeper understanding about it.","zh":"find insights into something 指發現對某事的更深層理解。"},{"en":"A documentary may find insights into poverty by following one family closely.","zh":"紀錄片可能透過仔細跟拍一個家庭，找出對貧窮的洞察。"},{"en":"Literature helps readers find insights into love, shame, ambition, and fear.","zh":"文學幫助讀者找出對愛、羞愧、野心和恐懼的洞察。"},{"en":"This phrase is used when learning goes beyond surface facts.","zh":"這個短語用於學習超越表面事實時。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":17},{"front":"the human condition","meaning":"人類處境；人性狀況","examples":[{"en":"Literature explores truths about the human condition.","zh":"文學探索關於人類處境的真相。"},{"en":"The human condition means the basic experiences and problems shared by human beings.","zh":"the human condition 指人類共同面對的基本經驗和問題。"},{"en":"Illness, love, ageing, loneliness, hope, and death are parts of the human condition.","zh":"疾病、愛、衰老、孤獨、希望和死亡都是人類處境的一部分。"},{"en":"Stories about ordinary people can reveal the human condition more clearly than statistics.","zh":"關於普通人的故事可以比統計數字更清楚揭示人類處境。"},{"en":"This phrase is common in literature, philosophy, and art criticism.","zh":"這個短語常見於文學、哲學和藝術評論。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":17},{"front":"express a curious truth","meaning":"表達一種奇特的真相","examples":[{"en":"Novels express a curious truth through fiction.","zh":"小說透過虛構表達一種奇特的真相。"},{"en":"To express a curious truth means to reveal a strange, interesting, or unexpected truth.","zh":"express a curious truth 指揭示一種奇怪、有趣或意想不到的真相。"},{"en":"A comedy may express a curious truth about how people hide embarrassment.","zh":"喜劇可能表達一種關於人們如何掩飾尷尬的奇特真相。"},{"en":"Fiction can express truths that direct factual writing may not capture.","zh":"虛構作品可以表達直接事實寫作未必能捕捉的真相。"},{"en":"This phrase suggests truth can appear in unusual forms.","zh":"這個短語暗示真相可以以不尋常形式出現。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":17},{"front":"in a furtive and veiled fashion","meaning":"以隱秘而含蓄的方式","examples":[{"en":"Novels express truth in a furtive and veiled fashion.","zh":"小說以隱秘而含蓄的方式表達真相。"},{"en":"In a furtive and veiled fashion means in a hidden, indirect, or disguised way.","zh":"in a furtive and veiled fashion 指以隱藏、間接或偽裝的方式。"},{"en":"A shy student may show anger in a furtive and veiled fashion rather than speaking directly.","zh":"害羞學生可能以隱秘而含蓄的方式表現憤怒，而不是直接說出。"},{"en":"Art often reveals painful truth indirectly so people can face it more safely.","zh":"藝術常間接揭示痛苦真相，使人能較安全地面對。"},{"en":"This phrase describes expression that is not open or obvious.","zh":"這個短語描述不公開或不明顯的表達。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":18},{"front":"masquerade as","meaning":"偽裝成","examples":[{"en":"Fiction masquerades as what it is not.","zh":"虛構作品偽裝成它本身不是的東西。"},{"en":"To masquerade as something means to pretend to be something else.","zh":"masquerade as something 指假裝成另一種東西。"},{"en":"An advertisement may masquerade as helpful advice while mainly trying to sell a product.","zh":"廣告可能偽裝成有用建議，但主要是在推銷產品。"},{"en":"When fiction masquerades as truth, readers must understand the artistic rule.","zh":"當虛構作品偽裝成真相時，讀者必須理解藝術規則。"},{"en":"This phrase often suggests disguise or deliberate appearance.","zh":"這個短語常暗示偽裝或刻意呈現。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":18},{"front":"what it is not","meaning":"它本身並不是的東西","examples":[{"en":"Art often masquerades as what it is not.","zh":"藝術常偽裝成它本身並不是的東西。"},{"en":"What it is not means something different from its real nature.","zh":"what it is not 指與其真實本質不同的東西。"},{"en":"A fake charity may present itself as what it is not to gain money.","zh":"假慈善機構可能把自己呈現成它本身並不是的東西，以獲取金錢。"},{"en":"Fiction may appear to be reality, which is what it is not in a literal sense.","zh":"虛構作品可能看似現實，但從字面來說它並不是現實。"},{"en":"This phrase highlights the gap between appearance and truth.","zh":"這個短語突出外表與真相之間的差距。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":18},{"front":"secret ingredient","meaning":"秘密成分","examples":[{"en":"The secret ingredient of art is truth.","zh":"藝術的秘密成分是真相。"},{"en":"A secret ingredient is the hidden element that gives something its special power or quality.","zh":"secret ingredient 指賦予某物特殊力量或特質的隱藏元素。"},{"en":"In a family recipe, patience may be the secret ingredient, not extra sugar.","zh":"在家庭食譜中，秘密成分可能是耐性，而不是更多糖。"},{"en":"The secret ingredient in a good lesson is often clear examples.","zh":"好課堂的秘密成分往往是清楚例子。"},{"en":"This phrase can be literal in cooking or metaphorical in writing and ideas.","zh":"這個短語可在烹飪中按字面使用，也可在寫作和思想中作比喻使用。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":18},{"front":"Art is a lie whose secret ingredient is truth.","meaning":"藝術是以真相為秘密成分的謊言","examples":[{"en":"Art is a lie whose secret ingredient is truth.","zh":"藝術是以真相為秘密成分的謊言。"},{"en":"This sentence means art may use fiction, but its deeper power comes from truth.","zh":"這句話的意思是藝術可能使用虛構，但其深層力量來自真相。"},{"en":"A novel can invent characters while revealing real feelings about love or loneliness.","zh":"小說可以創造角色，同時揭示關於愛或孤獨的真實感受。"},{"en":"Art works because audiences find truth inside something they know is not literally real.","zh":"藝術之所以有效，是因為觀眾在明知不是字面真實的東西中找到真相。"},{"en":"The sentence captures the paradox that fiction can tell the truth.","zh":"這句話捕捉了虛構能說出真相的矛盾。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":18},{"front":"Reading Passage","meaning":"閱讀篇章","examples":[{"en":"Reading Passage 2 has six paragraphs.","zh":"閱讀篇章二有六段。"},{"en":"A reading passage is a text used for reading practice or an exam.","zh":"reading passage 指用於閱讀練習或考試的文章。"},{"en":"Students should skim a reading passage before answering detailed questions.","zh":"學生在回答細節題前應先略讀閱讀篇章。"},{"en":"Understanding the structure of a reading passage can make questions easier.","zh":"理解閱讀篇章的結構可以令題目更容易。"},{"en":"This phrase is common in IELTS and other reading tests.","zh":"這個短語常見於 IELTS 和其他閱讀測驗。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":18},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Candidates must choose the correct heading for each paragraph.","zh":"考生必須為每段選出正確標題。"},{"en":"To choose the correct heading means to select the title that best matches a paragraph’s main idea.","zh":"choose the correct heading 指選出最符合段落主旨的標題。"},{"en":"Students should read the whole paragraph before choosing the correct heading.","zh":"學生應先讀完整段，再選出正確標題。"},{"en":"A wrong heading often focuses on one small detail instead of the overall message.","zh":"錯誤標題常集中於一個小細節，而不是整體信息。"},{"en":"This task tests whether students understand the paragraph’s main point.","zh":"這類題目測試學生是否理解段落主旨。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":18},{"front":"from the list of headings below","meaning":"從以下標題列表中","examples":[{"en":"Students choose answers from the list of headings below.","zh":"學生從以下標題列表中選擇答案。"},{"en":"From the list of headings below means from the title options printed under the instruction.","zh":"from the list of headings below 指從指示下方列出的標題選項中選擇。"},{"en":"In a reading exam, students must choose from the list below, not invent their own headings.","zh":"在閱讀考試中，學生必須從下方列表選擇，而不是自己創作標題。"},{"en":"Checking every option in the list can prevent careless answers.","zh":"檢查列表中的每個選項可以避免粗心答案。"},{"en":"This phrase tells students exactly where the answer choices are.","zh":"這個短語告訴學生答案選項在哪裡。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":18},{"front":"write the correct number","meaning":"寫上正確編號","examples":[{"en":"Students write the correct number on their answer sheet.","zh":"學生在答題紙上寫上正確編號。"},{"en":"To write the correct number means to put the number that matches the chosen answer.","zh":"write the correct number 指填上與所選答案相配的編號。"},{"en":"In heading questions, students often write Roman numerals or numbers beside paragraph letters.","zh":"在標題題中，學生常在段落字母旁寫上羅馬數字或編號。"},{"en":"Writing the wrong number can lose marks even if the student understands the passage.","zh":"即使學生理解文章，寫錯編號也可能失分。"},{"en":"This phrase reminds students to copy the answer format carefully.","zh":"這個短語提醒學生小心抄寫答案格式。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":18},{"front":"a failed deception","meaning":"失敗的欺騙","examples":[{"en":"The heading a failed deception refers to an unsuccessful attempt to lie.","zh":"標題 a failed deception 指一次不成功的說謊嘗試。"},{"en":"A failed deception is a lie or trick that does not succeed.","zh":"failed deception 是沒有成功的謊言或詭計。"},{"en":"A fake excuse becomes a failed deception when a teacher sees clear evidence against it.","zh":"當老師看到清楚反證時，假藉口就變成失敗的欺騙。"},{"en":"Failed deception can damage someone more than honesty would have done.","zh":"失敗的欺騙對某人的傷害可能比誠實更大。"},{"en":"This phrase combines dishonesty with failure.","zh":"這個短語結合不誠實和失敗。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":18},{"front":"shared neurological basis","meaning":"共同的神經學基礎","examples":[{"en":"The passage discusses the shared neurological basis of lying and art.","zh":"文章討論說謊與藝術的共同神經學基礎。"},{"en":"A shared neurological basis means two behaviours may come from related processes in the brain.","zh":"shared neurological basis 指兩種行為可能來自大腦中相關的過程。"},{"en":"Memory and imagination may have a shared neurological basis because both reconstruct experience.","zh":"記憶和想像可能有共同神經學基礎，因為兩者都重構經驗。"},{"en":"If two abilities share a brain basis, damage to one area may affect both.","zh":"如果兩種能力共享大腦基礎，某個區域受損可能同時影響兩者。"},{"en":"This phrase explains a biological connection between mental activities.","zh":"這個短語解釋心理活動之間的生物學關係。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":19},{"front":"the distinction between…and…","meaning":"……與……之間的區別","examples":[{"en":"The final paragraph explains the distinction between artists and ordinary liars.","zh":"最後一段解釋藝術家與普通說謊者之間的區別。"},{"en":"The distinction between two things is the difference that separates them.","zh":"the distinction between two things 指分隔兩者的差異。"},{"en":"Students must understand the distinction between fact and opinion.","zh":"學生必須理解事實與意見之間的區別。"},{"en":"A clear distinction helps prevent two similar ideas from being confused.","zh":"清楚區別有助防止兩個相似概念被混淆。"},{"en":"This phrase is useful in essays and reading passages when comparing concepts.","zh":"這個短語適合在文章和閱讀篇章中比較概念時使用。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":19},{"front":"statements about","meaning":"關於……的陳述","examples":[{"en":"The question asks for statements about people suffering from confabulation.","zh":"題目要求找出關於患有虛構症人士的陳述。"},{"en":"Statements about something are sentences that give information or claims about it.","zh":"statements about something 指提供關於某事資訊或說法的句子。"},{"en":"A reading question may ask students to judge statements about the writer’s opinion.","zh":"閱讀題可能要求學生判斷關於作者觀點的陳述。"},{"en":"Students should match statements about a topic with evidence in the passage.","zh":"學生應把關於某主題的陳述與文章證據配對。"},{"en":"This phrase is common in True, False, Not Given and matching tasks.","zh":"這個短語常見於是非無從判斷題和配對題中。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":19},{"front":"suffer from","meaning":"患有；受……所苦","examples":[{"en":"Some patients suffer from confabulation after brain damage.","zh":"有些病人在腦部受損後患有虛構症。"},{"en":"To suffer from a condition means to have it, usually with pain, difficulty, or negative effects.","zh":"suffer from a condition 指患有某狀況，通常伴隨痛苦、困難或負面影響。"},{"en":"Many students suffer from stress before important exams.","zh":"許多學生在重要考試前受壓力所苦。"},{"en":"People who suffer from memory problems may need support in daily life.","zh":"患有記憶問題的人可能在日常生活中需要支援。"},{"en":"This phrase is usually used for illnesses, problems, or difficulties.","zh":"這個短語通常用於疾病、問題或困難。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":19},{"front":"deliberately lie","meaning":"故意說謊","examples":[{"en":"Confabulators do not deliberately lie.","zh":"虛構症患者並非故意說謊。"},{"en":"To deliberately lie means to say something false on purpose.","zh":"deliberately lie 指有意說出不真實的話。"},{"en":"A student deliberately lies if they know they did not finish the homework but say they did.","zh":"如果學生明知自己沒有完成功課卻說完成了，就是故意說謊。"},{"en":"Deliberate lying is different from making a mistake or being confused.","zh":"故意說謊不同於犯錯或混亂。"},{"en":"This phrase focuses on intention.","zh":"這個短語集中於意圖。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":19},{"front":"be aware of","meaning":"意識到；知道","examples":[{"en":"Patients are not usually aware of their condition.","zh":"病人通常不知道自己的狀況。"},{"en":"To be aware of something means to know about it or notice it.","zh":"be aware of something 指知道或注意到某事。"},{"en":"Drivers should be aware of children crossing near schools.","zh":"司機應注意學校附近過馬路的孩子。"},{"en":"If people are aware of a problem, they can take steps to deal with it.","zh":"如果人們意識到問題，就可以採取措施處理。"},{"en":"This phrase describes knowledge, attention, or consciousness.","zh":"這個短語描述知識、注意力或意識。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":19},{"front":"have the impetus to","meaning":"有……的動力","examples":[{"en":"The question asks whether patients have the impetus to explain uncertainty.","zh":"題目問病人是否有解釋不確定性的動力。"},{"en":"To have the impetus to do something means to have the force, motivation, or push to do it.","zh":"have the impetus to do something 指有力量、動機或推動力去做某事。"},{"en":"A poor exam result may give a student the impetus to study more regularly.","zh":"一次差考試成績可能給學生更規律學習的動力。"},{"en":"Anxiety can give people the impetus to search for explanations.","zh":"焦慮可以給人尋找解釋的動力。"},{"en":"This phrase is more formal than “have the motivation to”.","zh":"這個短語比 “have the motivation to” 更正式。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":19},{"front":"make up stories","meaning":"編造故事","examples":[{"en":"People with confabulation may make up stories.","zh":"患有虛構症的人可能編造故事。"},{"en":"To make up stories means to invent stories rather than report real events.","zh":"make up stories 指編造故事，而不是報告真實事件。"},{"en":"Children often make up stories while playing with toys.","zh":"孩子玩玩具時常會編造故事。"},{"en":"People may make up stories to entertain, to hide truth, or to fill memory gaps.","zh":"人們可能為了娛樂、隱瞞真相或填補記憶空白而編造故事。"},{"en":"Context decides whether making up stories is creative, dishonest, or medical.","zh":"語境決定編造故事是創意、不誠實還是醫學現象。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":19},{"front":"playwrights and novelists","meaning":"劇作家和小說家","examples":[{"en":"The question asks about playwrights and novelists.","zh":"題目問及劇作家和小說家。"},{"en":"Playwrights and novelists are writers who create plays and novels.","zh":"playwrights and novelists 指創作劇本和小說的作家。"},{"en":"Playwrights write dialogue for the stage, while novelists write longer fictional prose.","zh":"劇作家為舞台寫對白，而小說家寫較長的虛構散文。"},{"en":"Both playwrights and novelists use invented stories to explore human experience.","zh":"劇作家和小說家都用虛構故事探索人類經驗。"},{"en":"This phrase groups two kinds of literary creators together.","zh":"這個短語把兩類文學創作者放在一起。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":19},{"front":"convey broader meaning","meaning":"傳達更廣泛的意義","examples":[{"en":"Their stories can convey broader meaning.","zh":"他們的故事可以傳達更廣泛的意義。"},{"en":"To convey broader meaning means to communicate a larger idea beyond the surface story.","zh":"convey broader meaning 指傳達超越表面故事的更大思想。"},{"en":"A film about one family can convey broader meaning about migration.","zh":"一部關於一個家庭的電影可以傳達關於移民的更廣泛意義。"},{"en":"Stories convey broader meaning when personal events reflect common human experiences.","zh":"當個人事件反映共同人類經驗時，故事就能傳達更廣泛意義。"},{"en":"This phrase explains why art matters beyond plot.","zh":"這個短語解釋藝術為何不只關乎情節。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":19},{"front":"for one’s own benefit","meaning":"為了自己的利益","examples":[{"en":"The question contrasts artists with people who lie for their own benefit.","zh":"題目把藝術家與為了自己利益而說謊的人作對比。"},{"en":"For one’s own benefit means to help oneself or gain an advantage.","zh":"for one’s own benefit 指為了幫助自己或取得好處。"},{"en":"A worker may hide a mistake for their own benefit, hoping to avoid blame.","zh":"員工可能為了自己的利益隱瞞錯誤，希望避免責備。"},{"en":"Lying for one’s own benefit can harm others if they make decisions based on false information.","zh":"為了自己的利益而說謊，若令他人基於假資訊作決定，就可能傷害別人。"},{"en":"This phrase often suggests self-interest.","zh":"這個短語通常暗示自利。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":20},{"front":"have nothing to do with","meaning":"與……毫無關係","examples":[{"en":"The question asks whether their work has nothing to do with truth.","zh":"題目問他們的作品是否與真相毫無關係。"},{"en":"To have nothing to do with something means to be completely unrelated to it.","zh":"have nothing to do with something 指與某事完全無關。"},{"en":"A student’s accent has nothing to do with their intelligence.","zh":"學生的口音與智力毫無關係。"},{"en":"If fiction had nothing to do with truth, readers would not find real meaning in it.","zh":"如果虛構作品與真相毫無關係，讀者就不會在其中找到真實意義。"},{"en":"This phrase is useful for rejecting a connection.","zh":"這個短語適合用來否定關聯。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":20},{"front":"mislead someone","meaning":"誤導某人","examples":[{"en":"Stories can mislead us if we are not careful.","zh":"如果我們不小心，故事可以誤導我們。"},{"en":"To mislead someone means to make them believe the wrong thing.","zh":"mislead someone 指令人相信錯誤的事情。"},{"en":"A badly designed chart can mislead readers about the real trend.","zh":"設計差劣的圖表可以誤導讀者對真實趨勢的理解。"},{"en":"Misleading information can cause people to make poor decisions.","zh":"誤導性資訊可以令人作出差劣決定。"},{"en":"This verb does not always require a direct lie; wrong impressions can also mislead.","zh":"這個動詞不一定需要直接謊言；錯誤印象也可以誤導。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":20},{"front":"contain lies","meaning":"包含謊言","examples":[{"en":"The audience knows that fictional stories contain lies.","zh":"觀眾知道虛構故事包含謊言。"},{"en":"To contain lies means to include statements or events that are not literally true.","zh":"contain lies 指包含不是字面真實的說法或事件。"},{"en":"A fairy tale contains lies if judged as a news report, but it may still teach a moral truth.","zh":"如果把童話當新聞報道來看，它包含謊言，但仍可能教導道德真相。"},{"en":"Fiction can contain lies without trying to deceive, because readers know the rules.","zh":"虛構作品可以包含謊言而不試圖欺騙，因為讀者知道規則。"},{"en":"This phrase separates factual truth from artistic invention.","zh":"這個短語把事實真實與藝術創作分開。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":20},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用篇章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in the missing words in the short text that follows.","zh":"complete the summary below 指填補下方短文中的缺失字詞。"},{"en":"In IELTS Reading, students must complete the summary below with exact words from the passage.","zh":"在 IELTS 閱讀中，學生必須用篇章中的原字完成以下摘要。"},{"en":"Reading the summary first can help students predict the missing information.","zh":"先閱讀摘要可以幫助學生預測缺失資訊。"},{"en":"This instruction tests grammar, meaning, and careful locating skills.","zh":"這個指示測試文法、意思和仔細定位能力。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":20},{"front":"no more than two words","meaning":"不多於兩個字","examples":[{"en":"Students must choose no more than two words from the passage.","zh":"學生必須從篇章中選擇不多於兩個字。"},{"en":"No more than two words means the answer can contain one word or two words, but not three.","zh":"no more than two words 指答案可以是一個字或兩個字，但不能是三個字。"},{"en":"If the instruction says no more than two words, writing three words loses marks.","zh":"如果指示說不多於兩個字，寫三個字就會失分。"},{"en":"Students should count words carefully before transferring answers.","zh":"學生在轉填答案前應仔細數字數。"},{"en":"This phrase is a strict exam limit, not a suggestion.","zh":"這個短語是嚴格考試限制，而不是建議。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":20},{"front":"accuse someone of","meaning":"指控某人","examples":[{"en":"The newspaper accused Aitken of improper dealings.","zh":"該報章指控 Aitken 有不當交易。"},{"en":"To accuse someone of something means to say they have done something wrong.","zh":"accuse someone of something 指說某人做了錯事。"},{"en":"A teacher should not accuse a student of cheating without evidence.","zh":"老師不應在沒有證據下指控學生作弊。"},{"en":"Accusations can damage reputations, especially when they appear in public.","zh":"指控可以損害名譽，尤其是公開出現時。"},{"en":"This phrase is common in legal, school, and media contexts.","zh":"這個短語常見於法律、學校和媒體語境。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":20},{"front":"improper dealings with","meaning":"與……有不當交易","examples":[{"en":"Aitken was accused of improper dealings with arms dealers.","zh":"Aitken 被指控與軍火商有不當交易。"},{"en":"Improper dealings with someone are business or personal arrangements that seem dishonest, unethical, or unsuitable.","zh":"improper dealings with someone 指與某人的商業或私人安排看似不誠實、不道德或不合適。"},{"en":"A public official may be investigated for improper dealings with a private company.","zh":"公職人員可能因與私人公司有不當交易而被調查。"},{"en":"Improper dealings can create suspicion even before a crime is proven.","zh":"不當交易即使在罪行被證明前，也可以引起懷疑。"},{"en":"This phrase is often used when relationships or transactions may be corrupt.","zh":"這個短語常用於關係或交易可能涉及貪腐時。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":20},{"front":"former cabinet minister","meaning":"前內閣大臣","examples":[{"en":"The summary refers to former cabinet minister Jonathan Aitken.","zh":"摘要提到前內閣大臣 Jonathan Aitken。"},{"en":"A former cabinet minister is someone who once served in a senior government role.","zh":"former cabinet minister 指曾擔任高級政府職位的人。"},{"en":"A former cabinet minister may still be treated as an important public figure.","zh":"前內閣大臣仍可能被視為重要公眾人物。"},{"en":"If a former cabinet minister is accused of wrongdoing, the story may become national news.","zh":"如果前內閣大臣被指控做錯事，事件可能成為全國新聞。"},{"en":"This phrase identifies both past status and political importance.","zh":"這個短語同時指出過去身份和政治重要性。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":20},{"front":"in pursuit","meaning":"在追趕中","examples":[{"en":"The evidence showed that there was no vehicle in pursuit.","zh":"證據顯示沒有車輛在追趕中。"},{"en":"In pursuit means following or chasing someone or something.","zh":"in pursuit 指正在跟隨或追趕某人或某物。"},{"en":"The police car was in pursuit of a stolen vehicle.","zh":"警車正在追趕一輛被盜車輛。"},{"en":"If no one is in pursuit, a claim about being chased becomes doubtful.","zh":"如果沒有人在追趕，關於被追的說法就變得可疑。"},{"en":"This phrase is often used in reports, action scenes, or legal evidence.","zh":"這個短語常用於報告、動作場面或法律證據中。"}],"source":"49 - Are Artists Liars?.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 50":[{"front":"workplace stress","meaning":"職場壓力","examples":[{"en":"The passage discusses the causes and effects of workplace stress.","zh":"文章討論職場壓力的原因和影響。"},{"en":"Workplace stress is pressure caused by work demands, deadlines, people or lack of control.","zh":"職場壓力是由工作要求、期限、人際關係或缺乏控制權造成的壓力。"},{"en":"A nurse may feel workplace stress when the ward is short-staffed and patients keep arriving.","zh":"當病房人手不足而病人不斷到來，護士可能感到職場壓力。"},{"en":"Workplace stress can lead to poor sleep, mistakes, illness and absence from work.","zh":"職場壓力可以導致睡眠差、犯錯、生病和缺勤。"},{"en":"Workplace stress is not just being busy for one day; it becomes serious when pressure continues.","zh":"職場壓力不只是某一天很忙；當壓力持續時，它就會變得嚴重。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":1},{"front":"How busy is too busy?","meaning":"忙到怎樣才算太忙？","examples":[{"en":"The article asks, “How busy is too busy?”","zh":"文章問：「忙到怎樣才算太忙？」"},{"en":"“How busy is too busy?” asks when ordinary busyness becomes unhealthy or excessive.","zh":"“How busy is too busy?” 是問普通忙碌何時變成不健康或過度。"},{"en":"A student might ask this question when homework, tutoring and activities leave no time to sleep.","zh":"當功課、補習和活動令學生沒有時間睡覺，他可能會問這個問題。"},{"en":"If people ignore this question, they may accept harmful pressure as normal.","zh":"如果人們忽視這個問題，他們可能把有害壓力當成正常。"},{"en":"The question helps readers think about the boundary between hard work and overload.","zh":"這個問題幫助讀者思考努力工作和負荷過重之間的界線。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":1},{"front":"missing an occasional long lunch","meaning":"偶爾錯過悠長午餐","examples":[{"en":"For some people, being too busy means missing an occasional long lunch.","zh":"對一些人來說，太忙意味著偶爾錯過悠長午餐。"},{"en":"Missing an occasional long lunch means sometimes losing a relaxed midday break because of work.","zh":"missing an occasional long lunch 指有時因工作而失去輕鬆的午間休息。"},{"en":"An office worker may miss an occasional long lunch when a meeting runs late.","zh":"當會議超時，辦公室員工可能偶爾錯過悠長午餐。"},{"en":"If this happens only sometimes, it may be inconvenient rather than deeply harmful.","zh":"如果這只是偶爾發生，它可能是不方便，而不是嚴重有害。"},{"en":"The phrase suggests a mild level of busyness compared with missing meals completely.","zh":"這個短語相比完全錯過用餐，暗示較輕微的忙碌程度。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":1},{"front":"missing lunch altogether","meaning":"完全錯過午餐","examples":[{"en":"For others, it means missing lunch altogether.","zh":"對另一些人來說，這意味著完全錯過午餐。"},{"en":"Missing lunch altogether means having no lunch at all because there is too much to do.","zh":"missing lunch altogether 指因為有太多事要做而完全沒有吃午餐。"},{"en":"A teacher may miss lunch altogether when lessons, meetings and marking fill the whole day.","zh":"當課堂、會議和改卷填滿整天，老師可能完全錯過午餐。"},{"en":"Missing lunch often can reduce energy and make afternoon work harder.","zh":"經常完全錯過午餐會降低精力，令下午工作更困難。"},{"en":"The phrase describes a stronger sign of overload than simply eating late.","zh":"這個短語描述比只是遲吃飯更強烈的負荷過重跡象。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":1},{"front":"take a sickie","meaning":"請「病假」；詐病請假","examples":[{"en":"Some workers are too busy to take a sickie once a month.","zh":"有些員工忙到連每月請一次「病假」也做不到。"},{"en":"To take a sickie means to take a day off by saying one is sick, often informally or dishonestly.","zh":"take a sickie 指以生病為理由請一天假，常帶口語或不誠實意味。"},{"en":"An employee might take a sickie after feeling exhausted, even if he is not truly ill.","zh":"員工可能因太疲倦而請「病假」，即使他不是真的病了。"},{"en":"If many workers take sickies, it may show low morale or poor workplace culture.","zh":"如果很多員工詐病請假，這可能顯示士氣低或職場文化差。"},{"en":"The phrase is informal and should not be used in formal business writing.","zh":"這個短語較口語，不應用於正式商業寫作。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":1},{"front":"working every evening and weekend","meaning":"每晚和每個周末工作","examples":[{"en":"For some people, working every evening and weekend is normal.","zh":"對一些人來說，每晚和每個周末工作是正常的。"},{"en":"Working every evening and weekend means doing job tasks after normal hours almost all the time.","zh":"working every evening and weekend 指幾乎一直在正常工時後處理工作。"},{"en":"A junior lawyer may be working every evening and weekend before a major case.","zh":"初級律師在重大案件前可能每晚和每個周末工作。"},{"en":"If this pattern continues, family life, sleep and health can suffer.","zh":"如果這種模式持續，家庭生活、睡眠和健康都可能受損。"},{"en":"The phrase describes a heavy workload that leaves little real rest.","zh":"這個短語描述幾乎沒有真正休息的沉重工作量。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":1},{"front":"frantic activity","meaning":"忙亂的活動","examples":[{"en":"Frantic activity sets the tempo of life for some executives.","zh":"忙亂的活動訂定一些行政人員的生活節奏。"},{"en":"Frantic activity means very rushed, intense and restless action.","zh":"frantic activity 指非常匆忙、強烈而停不下來的活動。"},{"en":"A shop before Christmas may be full of frantic activity as staff serve long queues.","zh":"聖誕節前的商店可能充滿忙亂活動，員工要服務長長人龍。"},{"en":"Frantic activity can make people feel productive, but it can also hide poor planning.","zh":"忙亂活動可以令人覺得自己有生產力，但也可能掩蓋計劃不足。"},{"en":"The phrase suggests busyness that feels urgent and difficult to control.","zh":"這個短語暗示忙碌既急迫又難以控制。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":1},{"front":"set the tempo of life","meaning":"訂定生活節奏","examples":[{"en":"Frantic activity can set the tempo of life.","zh":"忙亂的活動可以訂定生活節奏。"},{"en":"To set the tempo of life means to decide the usual speed or rhythm of daily living.","zh":"set the tempo of life 指決定日常生活的通常速度或節奏。"},{"en":"A long commute can set the tempo of life for a family because everyone must wake early.","zh":"漫長通勤可以訂定一家人的生活節奏，因為所有人都必須早起。"},{"en":"If work sets the tempo of life, personal time may have to fit around job demands.","zh":"如果工作訂定生活節奏，私人時間可能要圍繞工作要求安排。"},{"en":"The phrase shows what controls the pace of someone’s routine.","zh":"這個短語顯示甚麼控制某人日常生活的步伐。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":1},{"front":"senior executives","meaning":"高級行政人員","examples":[{"en":"Most senior executives experience very heavy workloads.","zh":"大多數高級行政人員承受非常沉重的工作量。"},{"en":"Senior executives are high-level managers who make important business decisions.","zh":"senior executives 是作出重要商業決策的高層管理人員。"},{"en":"Senior executives may attend board meetings, manage teams and speak with major clients.","zh":"高級行政人員可能出席董事會會議、管理團隊和與大客戶溝通。"},{"en":"Because senior executives carry large responsibility, their decisions can affect many employees.","zh":"因為高級行政人員承擔重大責任，他們的決策可以影響許多員工。"},{"en":"The phrase refers to people near the top of an organisation.","zh":"這個短語指組織中接近最高層的人。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":1},{"front":"workloads swing between","meaning":"工作量在……之間擺動","examples":[{"en":"For senior executives, workloads swing between extremely busy and frenzied.","zh":"對高級行政人員來說，工作量在極度忙碌和近乎瘋狂之間擺動。"},{"en":"Workloads swing between two states means the amount of work moves back and forth between them.","zh":"workloads swing between 兩種狀態，指工作量在兩者之間來回變動。"},{"en":"A teacher’s workload may swing between quiet weeks and exam-marking weeks.","zh":"老師的工作量可能在清閒週和考試改卷週之間擺動。"},{"en":"If workloads swing too sharply, workers may find it hard to plan rest.","zh":"如果工作量變化太劇烈，員工可能難以安排休息。"},{"en":"The phrase suggests unstable changes in how much work people face.","zh":"這個短語暗示人們面對的工作量不穩定地變化。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":1},{"front":"extremely busy and frenzied","meaning":"極度忙碌和近乎瘋狂","examples":[{"en":"Their workloads swing between extremely busy and frenzied.","zh":"他們的工作量在極度忙碌和近乎瘋狂之間擺動。"},{"en":"Extremely busy and frenzied means not only full of work but also rushed and almost chaotic.","zh":"extremely busy and frenzied 指不只是工作多，還非常急促和近乎混亂。"},{"en":"A hospital emergency room may become extremely busy and frenzied after a major accident.","zh":"重大意外後，醫院急症室可能變得極度忙碌和近乎瘋狂。"},{"en":"When work becomes frenzied, people may make mistakes because everything feels urgent.","zh":"當工作變得近乎瘋狂，人們可能因一切都很急而犯錯。"},{"en":"The phrase describes a level of busyness beyond ordinary pressure.","zh":"這個短語描述超越普通壓力的忙碌程度。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":2},{"front":"vice-president of","meaning":"……的副總裁","examples":[{"en":"Neil Plumridge is vice-president of management consultancy A.T. Kearney.","zh":"Neil Plumridge 是管理顧問公司 A.T. Kearney 的副總裁。"},{"en":"A vice-president of an organisation is a senior manager below the president or top leadership.","zh":"vice-president of 某機構，是低於總裁或最高領導層的高級管理人員。"},{"en":"The vice-president of sales may be responsible for major clients and revenue targets.","zh":"銷售副總裁可能負責大客戶和收入目標。"},{"en":"If a vice-president makes a decision, many departments may be affected.","zh":"如果副總裁作出決定，許多部門可能受影響。"},{"en":"The phrase identifies a senior position in a company or institution.","zh":"這個短語指出公司或機構中的高級職位。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":2},{"front":"management consultancy","meaning":"管理顧問公司","examples":[{"en":"A.T. Kearney is a management consultancy.","zh":"A.T. Kearney 是一間管理顧問公司。"},{"en":"A management consultancy is a company that advises other organisations on strategy, operations or improvement.","zh":"management consultancy 是為其他組織提供策略、營運或改善建議的公司。"},{"en":"A supermarket may hire a management consultancy to reduce waste and improve delivery.","zh":"超市可能聘請管理顧問公司來減少浪費並改善送貨。"},{"en":"Because consultants solve business problems, their work can involve long hours and travel.","zh":"因為顧問要解決商業問題，他們的工作可能涉及長工時和出差。"},{"en":"The phrase refers to an advisory business, not a normal product-selling company.","zh":"這個短語指提供建議的企業，而不是一般銷售產品的公司。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":2},{"front":"head of its Asia-Pacific telecommunications practice","meaning":"亞太區電訊業務主管","examples":[{"en":"Plumridge is head of A.T. Kearney’s Asia-Pacific telecommunications practice.","zh":"Plumridge 是 A.T. Kearney 亞太區電訊業務主管。"},{"en":"Head of a practice means the person leading a specialist business area.","zh":"head of a practice 指領導某個專門業務範疇的人。"},{"en":"A lawyer may be head of the firm’s family-law practice.","zh":"律師可能是一間律師行家庭法律業務的主管。"},{"en":"If someone heads a regional practice, they manage clients, staff and projects in that region.","zh":"如果某人主管一個地區業務，他要管理該區的客戶、員工和項目。"},{"en":"The phrase describes both leadership and a specialised field.","zh":"這個短語同時描述領導職位和專門範疇。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":2},{"front":"working week varies from…to…","meaning":"每周工時由……到……不等","examples":[{"en":"His working week varies from 45 hours to 80 hours.","zh":"他的每周工時由45小時到80小時不等。"},{"en":"A working week varies from one number to another when the hours change within that range.","zh":"working week varies from 一個數字 to 另一個數字，指工時在該範圍內變動。"},{"en":"A restaurant manager’s working week may vary from 40 hours to 65 hours during holidays.","zh":"餐廳經理在假期期間的每周工時可能由40小時到65小時不等。"},{"en":"If working hours vary widely, planning family time becomes harder.","zh":"如果工時差異很大，安排家庭時間會更困難。"},{"en":"The phrase shows a range rather than one fixed number.","zh":"這個短語顯示範圍，而不是固定數字。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":2},{"front":"averaging 60 hours","meaning":"平均為60小時","examples":[{"en":"His working week averages 60 hours.","zh":"他的每周工時平均為60小時。"},{"en":"Averaging 60 hours means the usual or mean working time is about 60 hours.","zh":"averaging 60 hours 指通常或平均工作時間約為60小時。"},{"en":"A trainee doctor may work weeks averaging 60 hours during a demanding placement.","zh":"實習醫生在繁重實習期間，每周工時可能平均為60小時。"},{"en":"If someone averages 60 hours a week, rest and personal time may be limited.","zh":"如果某人每周平均工作60小時，休息和私人時間可能有限。"},{"en":"The phrase gives the typical amount after considering busy and quieter weeks.","zh":"這個短語在考慮忙碌和較清閒週後給出典型數量。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":2},{"front":"warning signs","meaning":"警號","examples":[{"en":"Three warning signs alert Plumridge to an excessive workload.","zh":"三個警號提醒 Plumridge 注意工作量過重。"},{"en":"Warning signs are early clues that something may be going wrong.","zh":"warning signs 是顯示某事可能出問題的早期線索。"},{"en":"Frequent headaches can be warning signs that a student is sleeping too little.","zh":"經常頭痛可以是學生睡眠太少的警號。"},{"en":"If warning signs are ignored, a small problem may become a serious crisis.","zh":"如果警號被忽視，小問題可能變成嚴重危機。"},{"en":"The phrase helps people notice danger before it becomes worse.","zh":"這個短語幫助人們在危險惡化前注意到它。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":2},{"front":"alert someone to","meaning":"提醒某人注意……","examples":[{"en":"Three warning signs alert him to an excessive workload.","zh":"三個警號提醒他注意工作量過重。"},{"en":"To alert someone to something means to make them notice a possible problem or danger.","zh":"alert someone to 某事，指令某人注意可能的問題或危險。"},{"en":"A smoke alarm alerts families to fire before they see flames.","zh":"煙霧警報在家人看見火焰前提醒他們注意火災。"},{"en":"If poor sleep alerts a worker to stress, the worker can change habits earlier.","zh":"如果睡眠差提醒員工注意壓力，員工可以更早改變習慣。"},{"en":"The phrase describes drawing attention to something important.","zh":"這個短語描述把注意力引向重要事情。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":2},{"front":"excessive workload","meaning":"過重工作量","examples":[{"en":"Sleep, scheduling and family can reveal an excessive workload.","zh":"睡眠、日程安排和家庭可以顯示工作量過重。"},{"en":"An excessive workload is more work than a person can reasonably handle.","zh":"excessive workload 是超出一個人合理承受範圍的工作量。"},{"en":"A student has an excessive workload if homework leaves no time to eat, sleep or travel safely.","zh":"如果功課令學生沒有時間吃飯、睡覺或安全通勤，他就有過重工作量。"},{"en":"Excessive workload can cause stress, mistakes, exhaustion and health problems.","zh":"過重工作量可以造成壓力、錯誤、疲憊和健康問題。"},{"en":"The phrase describes work that has gone beyond a healthy limit.","zh":"這個短語描述已超出健康界線的工作。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":2},{"front":"too much to do","meaning":"有太多事情要做","examples":[{"en":"He knows he has too much to do when he sleeps too little.","zh":"當他睡得太少時，他知道自己有太多事情要做。"},{"en":"Too much to do means having more tasks than can be managed comfortably.","zh":"too much to do 指任務多到不能舒服地處理。"},{"en":"A parent may have too much to do when work, childcare and housework all pile up.","zh":"當工作、照顧孩子和家務同時堆積，家長可能有太多事情要做。"},{"en":"If someone has too much to do, important tasks may be rushed or forgotten.","zh":"如果某人有太多事情要做，重要任務可能被趕急完成或遺忘。"},{"en":"The phrase describes overload in simple everyday language.","zh":"這個短語用簡單日常語言描述負荷過重。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":2},{"front":"fewer than six hours","meaning":"少於六小時","examples":[{"en":"He sleeps for fewer than six hours on three consecutive nights.","zh":"他連續三晚睡少於六小時。"},{"en":"Fewer than six hours means less than six hours.","zh":"fewer than six hours 指少過六小時。"},{"en":"A student who sleeps fewer than six hours before exams may struggle to concentrate.","zh":"考試前睡少於六小時的學生可能難以集中精神。"},{"en":"If sleep falls below six hours repeatedly, mood and memory can suffer.","zh":"如果睡眠反覆跌至六小時以下，心情和記憶可能受影響。"},{"en":"The phrase gives a clear limit showing insufficient sleep.","zh":"這個短語給出清楚界線，顯示睡眠不足。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":3},{"front":"consecutive nights","meaning":"連續多晚","examples":[{"en":"He notices stress when he sleeps badly on three consecutive nights.","zh":"當他連續三晚睡得不好時，他會注意到壓力。"},{"en":"Consecutive nights are nights that happen one after another without a break.","zh":"consecutive nights 是一晚接一晚、沒有中斷的夜晚。"},{"en":"A baby crying for three consecutive nights can leave parents exhausted.","zh":"嬰兒連續三晚哭鬧可以令父母筋疲力盡。"},{"en":"If poor sleep continues for consecutive nights, the body has less chance to recover.","zh":"如果睡眠差連續多晚持續，身體較少機會恢復。"},{"en":"The phrase stresses an unbroken sequence of nights.","zh":"這個短語強調不中斷的一連串夜晚。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":3},{"front":"constantly reschedules appointments","meaning":"不斷重新安排約會","examples":[{"en":"He knows he is overloaded when he constantly reschedules appointments.","zh":"當他不斷重新安排約會時，他知道自己負荷過重。"},{"en":"Constantly reschedules appointments means repeatedly changing meeting times because the schedule is too full.","zh":"constantly reschedules appointments 指因日程太滿而反覆更改會面時間。"},{"en":"A busy doctor may constantly reschedule appointments when emergencies interrupt the day.","zh":"當突發情況打斷一天工作，忙碌醫生可能不斷重新安排約會。"},{"en":"If someone keeps moving appointments, it may show poor planning or excessive workload.","zh":"如果某人一直改動約會，這可能顯示計劃差或工作量過重。"},{"en":"The phrase suggests that a person has lost control of their calendar.","zh":"這個短語暗示一個人已失去對日程的控制。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":3},{"front":"neglects his family","meaning":"忽略家人","examples":[{"en":"He becomes concerned when he neglects his family.","zh":"當他忽略家人時，他開始擔心。"},{"en":"To neglect his family means to give too little time, care or attention to family members.","zh":"neglect his family 指給家人的時間、照顧或注意太少。"},{"en":"A father may neglect his family if he answers work calls through every dinner.","zh":"如果父親每晚飯都接工作電話，他可能忽略家人。"},{"en":"Neglecting family can damage relationships and create guilt over time.","zh":"忽略家人可以隨時間損害關係並造成內疚。"},{"en":"The phrase describes a personal cost of work pressure.","zh":"這個短語描述工作壓力帶來的個人代價。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":3},{"front":"on the family side","meaning":"在家庭方面","examples":[{"en":"The third warning sign is on the family side.","zh":"第三個警號是在家庭方面。"},{"en":"On the family side means related to family life rather than work tasks directly.","zh":"on the family side 指與家庭生活有關，而不是直接與工作任務有關。"},{"en":"A manager may feel pressure on the family side when she misses children’s school events.","zh":"當經理錯過孩子的學校活動，她可能在家庭方面感到壓力。"},{"en":"If work problems appear on the family side, stress has crossed into private life.","zh":"如果工作問題出現在家庭方面，壓力已進入私人生活。"},{"en":"The phrase separates family effects from workplace effects.","zh":"這個短語把家庭影響與職場影響分開。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":3},{"front":"be expecting a second child","meaning":"即將迎來第二個孩子","examples":[{"en":"Plumridge was expecting a second child in October.","zh":"Plumridge 將在十月迎來第二個孩子。"},{"en":"To be expecting a second child means that someone or someone’s partner is pregnant with their second baby.","zh":"be expecting a second child 指某人或其伴侶正懷着第二個孩子。"},{"en":"A couple expecting a second child may prepare a room while still caring for their first child.","zh":"即將迎來第二個孩子的夫婦可能一邊照顧第一個孩子，一邊準備房間。"},{"en":"If a parent is expecting another child, work pressure may feel more serious.","zh":"如果家長即將再有孩子，工作壓力可能感覺更嚴重。"},{"en":"The phrase describes an important family responsibility coming soon.","zh":"這個短語描述即將到來的重要家庭責任。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":3},{"front":"happen to miss","meaning":"碰巧錯過","examples":[{"en":"If he happens to miss a birthday, he knows things are out of control.","zh":"如果他碰巧錯過生日，他就知道事情已失控。"},{"en":"To happen to miss something means to miss it by chance or because circumstances make it happen.","zh":"happen to miss 某事，指因偶然或環境影響而錯過它。"},{"en":"A commuter may happen to miss the train when a meeting finishes late.","zh":"當會議遲結束，通勤者可能碰巧錯過火車。"},{"en":"If someone happens to miss a family event because of work, it may reveal overload.","zh":"如果某人因工作碰巧錯過家庭活動，這可能顯示負荷過重。"},{"en":"The phrase often softens the idea of missing something, but the result may still matter.","zh":"這個短語常淡化錯過某事的感覺，但結果仍可能重要。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":3},{"front":"birthday or anniversary","meaning":"生日或周年紀念日","examples":[{"en":"Missing a birthday or anniversary tells him that work has become excessive.","zh":"錯過生日或周年紀念日告訴他，工作已變得過度。"},{"en":"A birthday or anniversary is an important personal or family date remembered each year.","zh":"birthday or anniversary 是每年記得的重要個人或家庭日子。"},{"en":"A parent may feel guilty after missing a child’s birthday or a wedding anniversary.","zh":"家長錯過孩子生日或結婚周年紀念日後，可能感到內疚。"},{"en":"If work repeatedly causes people to miss family dates, relationships may suffer.","zh":"如果工作反覆令人錯過家庭日子，關係可能受損。"},{"en":"The phrase represents meaningful private-life events.","zh":"這個短語代表有意義的私人生活事件。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":3},{"front":"out of control","meaning":"失控","examples":[{"en":"He knows things are out of control when he misses family events.","zh":"當他錯過家庭活動時，他知道事情已失控。"},{"en":"Out of control means no longer manageable or properly directed.","zh":"out of control 指不再能管理或正確控制。"},{"en":"A classroom can feel out of control if students shout and no one listens.","zh":"如果學生大叫而沒有人聽，課室可能感覺失控。"},{"en":"If work becomes out of control, small delays can turn into bigger problems.","zh":"如果工作變得失控，小延誤可以變成更大問題。"},{"en":"The phrase warns that normal management has broken down.","zh":"這個短語警告正常管理已經崩潰。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":3},{"front":"highly subjective","meaning":"非常主觀","examples":[{"en":"Being too busy is highly subjective.","zh":"是否太忙是非常主觀的。"},{"en":"Highly subjective means depending strongly on personal feelings, experience or judgement.","zh":"highly subjective 指強烈取決於個人感受、經驗或判斷。"},{"en":"Whether a homework load feels heavy can be highly subjective because students work at different speeds.","zh":"功課量是否沉重可以非常主觀，因為學生工作速度不同。"},{"en":"If stress is highly subjective, two people may react differently to the same workload.","zh":"如果壓力非常主觀，兩個人面對同一工作量可能反應不同。"},{"en":"The phrase means there is no single answer that fits everyone.","zh":"這個短語表示沒有一個答案適用於所有人。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":3},{"front":"prolonged perception of overload","meaning":"長期感到負荷過重","examples":[{"en":"A prolonged perception of overload can lead to stress.","zh":"長期感到負荷過重可以導致壓力。"},{"en":"A prolonged perception of overload means feeling overburdened for a long period.","zh":"prolonged perception of overload 指長時間覺得自己負擔太重。"},{"en":"A student may develop this feeling when every week seems full of tests and deadlines.","zh":"當每星期都像充滿測驗和期限，學生可能形成這種感覺。"},{"en":"If the perception continues, the body and mind may respond with stress symptoms.","zh":"如果這種感覺持續，身心可能以壓力症狀作反應。"},{"en":"The phrase focuses on long-term felt pressure, not just one busy afternoon.","zh":"這個短語重點在長期感受到的壓力，而不是某個忙碌下午。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":4},{"front":"manifest as","meaning":"表現為","examples":[{"en":"Overload can manifest as stress and disturbed sleep.","zh":"負荷過重可以表現為壓力和睡眠受干擾。"},{"en":"To manifest as something means to appear or show itself in that form.","zh":"manifest as 某事，指以該形式出現或顯示出來。"},{"en":"Anxiety may manifest as stomach pain before an exam.","zh":"焦慮可能在考試前表現為胃痛。"},{"en":"If pressure manifests as anger, people may not realise stress is the real cause.","zh":"如果壓力表現為憤怒，人們可能沒有意識到真正原因是壓力。"},{"en":"The phrase connects a hidden problem with visible symptoms.","zh":"這個短語把隱藏問題與可見症狀連繫起來。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":4},{"front":"disturbed sleep","meaning":"睡眠受干擾","examples":[{"en":"Stress can manifest as disturbed sleep.","zh":"壓力可以表現為睡眠受干擾。"},{"en":"Disturbed sleep is sleep that is broken, restless or not refreshing.","zh":"disturbed sleep 是斷斷續續、不安穩或不能恢復精神的睡眠。"},{"en":"A worker with disturbed sleep may wake up several times thinking about unfinished tasks.","zh":"睡眠受干擾的員工可能多次醒來，想着未完成任務。"},{"en":"Disturbed sleep can make concentration weaker the next day.","zh":"睡眠受干擾會令第二天專注力較弱。"},{"en":"The phrase describes poor sleep quality, not only sleeping fewer hours.","zh":"這個短語描述睡眠質素差，而不只是睡眠時間少。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":4},{"front":"declining mental and physical health","meaning":"精神和身體健康下降","examples":[{"en":"Stress can cause declining mental and physical health.","zh":"壓力可以導致精神和身體健康下降。"},{"en":"Declining mental and physical health means both emotional well-being and body condition are getting worse.","zh":"declining mental and physical health 指情緒健康和身體狀況都在惡化。"},{"en":"A student under constant pressure may feel anxious and also develop headaches.","zh":"長期受壓的學生可能感到焦慮，也可能頭痛。"},{"en":"If health declines, people may need rest, support and changes in workload.","zh":"如果健康下降，人們可能需要休息、支援和改變工作量。"},{"en":"The phrase shows that stress can affect the mind and the body together.","zh":"這個短語顯示壓力可以同時影響心靈和身體。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":4},{"front":"workers’ compensation figures","meaning":"工傷賠償數字","examples":[{"en":"National workers’ compensation figures show the cost of stress.","zh":"全國工傷賠償數字顯示壓力的成本。"},{"en":"Workers’ compensation figures are statistics about claims made by employees injured or harmed through work.","zh":"workers’ compensation figures 是關於員工因工作受傷或受害而提出申索的統計數字。"},{"en":"A government may study workers’ compensation figures to see which workplace risks are most costly.","zh":"政府可能研究工傷賠償數字，以了解哪些職場風險成本最高。"},{"en":"If stress claims increase, employers may need better prevention policies.","zh":"如果壓力申索增加，僱主可能需要更好的預防政策。"},{"en":"The phrase refers to official data about work-related harm and payments.","zh":"這個短語指有關工作相關傷害和賠償的官方數據。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":4},{"front":"lost time","meaning":"損失的工作時間","examples":[{"en":"Stress causes more lost time than any other workplace injury.","zh":"壓力造成的工作時間損失比任何其他工傷更多。"},{"en":"Lost time means working time lost because employees are absent or unable to work.","zh":"lost time 指因員工缺勤或不能工作而損失的工作時間。"},{"en":"A factory may record lost time after workers are injured and cannot finish shifts.","zh":"工廠可能在工人受傷不能完成班次後記錄損失工作時間。"},{"en":"Too much lost time can delay services and increase costs for employers.","zh":"太多工作時間損失可以延誤服務並增加僱主成本。"},{"en":"The phrase measures the practical impact of illness or injury on work.","zh":"這個短語量度疾病或傷害對工作的實際影響。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":4},{"front":"workplace injury","meaning":"工作場所傷害；工傷","examples":[{"en":"Stress causes more lost time than any other workplace injury.","zh":"壓力造成的工作時間損失比任何其他工作場所傷害更多。"},{"en":"A workplace injury is harm caused by conditions or events at work.","zh":"workplace injury 是由工作條件或工作事件造成的傷害。"},{"en":"A worker who slips on a wet floor may suffer a workplace injury.","zh":"工人在濕滑地板上滑倒，可能遭受工傷。"},{"en":"Workplace injuries can be physical or psychological, depending on the cause and effect.","zh":"工傷可以是身體上的，也可以是心理上的，視乎原因和影響。"},{"en":"The phrase refers to harm connected with employment.","zh":"這個短語指與僱傭相關的傷害。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":4},{"front":"suffering from stress","meaning":"受壓力困擾","examples":[{"en":"Employees suffering from stress are absent for many weeks.","zh":"受壓力困擾的員工會缺勤多個星期。"},{"en":"Suffering from stress means experiencing harmful pressure that affects health or functioning.","zh":"suffering from stress 指經歷影響健康或功能的有害壓力。"},{"en":"A receptionist suffering from stress may feel anxious before every shift.","zh":"受壓力困擾的接待員可能每次上班前都感到焦慮。"},{"en":"If workers are suffering from stress, they may need workload changes rather than simple encouragement.","zh":"如果員工受壓力困擾，他們可能需要改變工作量，而不只是簡單鼓勵。"},{"en":"The phrase describes stress as a real condition, not a minor complaint.","zh":"這個短語把壓力描述為真實狀況，而不是小抱怨。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":4},{"front":"absent for an average of","meaning":"平均缺勤……","examples":[{"en":"Employees suffering from stress are absent for an average of 16.6 weeks.","zh":"受壓力困擾的員工平均缺勤16.6星期。"},{"en":"Absent for an average of a period means the typical absence lasts that long.","zh":"absent for an average of 某段時間，指典型缺勤時間是那麼長。"},{"en":"Staff with serious injuries may be absent for an average of several weeks.","zh":"受嚴重傷害的員工可能平均缺勤數星期。"},{"en":"If workers are absent for a long average period, the organisation loses skills and time.","zh":"如果員工平均缺勤時間很長，機構會失去技能和時間。"},{"en":"The phrase reports the typical length of absence across a group.","zh":"這個短語報告一個群體的典型缺勤長度。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":4},{"front":"claim costs","meaning":"申索成本","examples":[{"en":"Psychological injuries accounted for almost 27 per cent of claim costs.","zh":"心理創傷佔申索成本接近百分之二十七。"},{"en":"Claim costs are the money paid or expected to be paid for insurance or compensation claims.","zh":"claim costs 是保險或賠償申索已支付或預計支付的金額。"},{"en":"An insurer may track claim costs after workplace accidents.","zh":"保險機構可能在職場意外後追蹤申索成本。"},{"en":"If claim costs rise, companies may improve safety to reduce future payments.","zh":"如果申索成本上升，公司可能改善安全以減少未來賠償。"},{"en":"The phrase focuses on the financial side of injury or illness claims.","zh":"這個短語重點在傷害或疾病申索的財務方面。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":4},{"front":"federal government’s insurer","meaning":"聯邦政府的保險機構","examples":[{"en":"Comcare is the Australian federal government’s insurer.","zh":"Comcare 是澳洲聯邦政府的保險機構。"},{"en":"A federal government’s insurer is the body that handles insurance or compensation for government employees.","zh":"federal government’s insurer 是處理政府員工保險或賠償的機構。"},{"en":"A public teacher injured at work may deal with a government insurer for compensation.","zh":"公校老師在工作中受傷，可能要與政府保險機構處理賠償。"},{"en":"If the insurer records many stress claims, it can show a major public-sector problem.","zh":"如果保險機構記錄到很多壓力申索，這可以顯示公營部門有重大問題。"},{"en":"The phrase identifies an official insurance organisation.","zh":"這個短語指出官方保險組織。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":5},{"front":"psychological injuries","meaning":"心理創傷","examples":[{"en":"Claims for psychological injuries were expensive.","zh":"心理創傷申索成本高昂。"},{"en":"Psychological injuries are mental or emotional harms caused by stress, trauma or pressure.","zh":"psychological injuries 是由壓力、創傷或壓迫造成的心理或情緒傷害。"},{"en":"A worker bullied for months may suffer psychological injuries even without physical harm.","zh":"被欺凌數月的員工即使沒有身體受傷，也可能遭受心理創傷。"},{"en":"Psychological injuries can lead to absence, treatment costs and reduced confidence.","zh":"心理創傷可以導致缺勤、治療成本和信心下降。"},{"en":"The phrase shows that workplace harm is not always visible.","zh":"這個短語顯示職場傷害不一定看得見。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":5},{"front":"account for","meaning":"佔……","examples":[{"en":"Psychological injuries accounted for 7 per cent of claims.","zh":"心理創傷佔申索個案百分之七。"},{"en":"To account for a percentage means to make up that part of the total.","zh":"account for 某百分比，指構成總數中的該部分。"},{"en":"Online sales may account for half of a shop’s revenue.","zh":"網上銷售可能佔商店收入一半。"},{"en":"If stress claims account for a large share of costs, stress is financially serious.","zh":"如果壓力申索佔成本很大比例，壓力在財務上很嚴重。"},{"en":"The phrase is useful when explaining proportions.","zh":"這個短語適合用來解釋比例。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":5},{"front":"temporary relief","meaning":"暫時紓緩","examples":[{"en":"Experts say the key is not temporary relief.","zh":"專家說關鍵不是暫時紓緩。"},{"en":"Temporary relief is short-term comfort that reduces a problem for a while but does not solve it.","zh":"temporary relief 是短期舒緩，只暫時減輕問題但不解決它。"},{"en":"A massage may give temporary relief from neck pain after a long day at a computer.","zh":"長時間用電腦後，按摩可能暫時紓緩頸痛。"},{"en":"If people rely only on temporary relief, the deeper workload problem may continue.","zh":"如果人們只依靠暫時紓緩，更深層的工作量問題可能持續。"},{"en":"The phrase contrasts quick comfort with real long-term change.","zh":"這個短語把短暫舒適與真正長期改變作對比。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":5},{"front":"such as","meaning":"例如","examples":[{"en":"Temporary relief may include activities such as golf or a massage.","zh":"暫時紓緩可能包括例如打高爾夫球或按摩等活動。"},{"en":"Such as introduces examples of a general category.","zh":"such as 用來引出某一類別的例子。"},{"en":"Healthy habits such as walking, sleeping well and eating breakfast can improve energy.","zh":"例如散步、睡好和吃早餐等健康習慣可以改善精力。"},{"en":"If a sentence uses “such as,” the list usually gives examples, not every possible item.","zh":"如果句子使用 such as，清單通常提供例子，而不是所有可能項目。"},{"en":"The phrase helps make a general idea more specific.","zh":"這個短語幫助令一般想法更具體。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":5},{"front":"reassessment of workloads","meaning":"重新評估工作量","examples":[{"en":"Experts recommend a reassessment of workloads.","zh":"專家建議重新評估工作量。"},{"en":"A reassessment of workloads is a fresh review of how much work people are expected to do.","zh":"reassessment of workloads 是重新檢視人們被期望完成多少工作。"},{"en":"A school may conduct a reassessment of workloads if teachers are marking late every night.","zh":"如果老師每晚改卷到很晚，學校可能進行工作量重新評估。"},{"en":"Reassessment can reveal whether deadlines, staffing or expectations need to change.","zh":"重新評估可以揭示期限、人手或期望是否需要改變。"},{"en":"The phrase suggests looking again at the real amount of work, not just asking people to cope.","zh":"這個短語暗示再次檢視真實工作量，而不是只要求人們應付。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":5},{"front":"make it a priority to","meaning":"優先做……","examples":[{"en":"Plumridge makes it a priority to identify what must change.","zh":"Plumridge 優先找出必須改變的地方。"},{"en":"To make it a priority to do something means to treat that action as very important and urgent.","zh":"make it a priority to do something 指把該行動視為非常重要和緊急。"},{"en":"A student may make it a priority to sleep earlier before exams.","zh":"學生可能優先在考試前早睡。"},{"en":"If managers make stress prevention a priority, they may change workloads before people break down.","zh":"如果管理者優先預防壓力，他們可能在人們崩潰前改變工作量。"},{"en":"The phrase shows that something is placed near the top of the to-do list.","zh":"這個短語顯示某事被放在待辦事項的較高位置。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":5},{"front":"identify what must change","meaning":"找出必須改變的地方","examples":[{"en":"He tries to identify what must change in his workload.","zh":"他嘗試找出自己工作量中必須改變的地方。"},{"en":"To identify what must change means to find the specific part of a situation that needs adjustment.","zh":"identify what must change 指找出情況中需要調整的具體部分。"},{"en":"A teacher may identify what must change when students keep failing the same grammar point.","zh":"當學生一直在同一文法點失分，老師可能找出必須改變的地方。"},{"en":"If people identify the real problem, they can stop wasting effort on the wrong solution.","zh":"如果人們找出真正問題，就能停止把努力浪費在錯誤解方上。"},{"en":"The phrase focuses on clear diagnosis before action.","zh":"這個短語重點在行動前作出清楚診斷。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":5},{"front":"allocating more resources","meaning":"分配更多資源","examples":[{"en":"Reducing stress may mean allocating more resources.","zh":"減輕壓力可能意味著分配更多資源。"},{"en":"Allocating more resources means giving more people, money, time or equipment to a task.","zh":"allocating more resources 指把更多人手、金錢、時間或設備投入某項任務。"},{"en":"A school may reduce teacher stress by allocating more teaching assistants to large classes.","zh":"學校可以透過為大班分配更多助教來減少老師壓力。"},{"en":"If resources are too limited, workers may have to do more than is reasonable.","zh":"如果資源太有限，員工可能要做超出合理範圍的工作。"},{"en":"The phrase describes solving pressure by adding support.","zh":"這個短語描述透過增加支援來解決壓力。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":5},{"front":"allowing more time","meaning":"給予更多時間","examples":[{"en":"Reducing pressure may involve allowing more time.","zh":"減輕壓力可能涉及給予更多時間。"},{"en":"Allowing more time means giving a longer period to finish a task properly.","zh":"allowing more time 指給較長時間來妥善完成任務。"},{"en":"A manager may allow more time for a report if the data is complex.","zh":"如果數據複雜，經理可能給予更多時間完成報告。"},{"en":"If people have more time, they may produce better work with less panic.","zh":"如果人們有更多時間，他們可能以較少恐慌完成更好工作。"},{"en":"The phrase suggests changing deadlines rather than forcing people to rush.","zh":"這個短語暗示改變期限，而不是強迫人趕工。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":5},{"front":"altering expectations","meaning":"改變期望","examples":[{"en":"Reducing pressure may require altering expectations.","zh":"減輕壓力可能需要改變期望。"},{"en":"Altering expectations means changing what people believe should be achieved or delivered.","zh":"altering expectations 指改變人們認為應該達成或交付的事情。"},{"en":"A client may accept a later deadline if the manager explains the work honestly.","zh":"如果經理解釋工作實況，客戶可能接受較遲期限。"},{"en":"If expectations are unrealistic, altering them can reduce stress immediately.","zh":"如果期望不切實際，改變期望可以立即減少壓力。"},{"en":"The phrase focuses on changing demands before they become impossible.","zh":"這個短語重點在要求變得不可能前先作調整。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":6},{"front":"rely on colleagues’ advice","meaning":"依靠同事的建議","examples":[{"en":"Plumridge also relies on colleagues’ advice.","zh":"Plumridge 也依靠同事的建議。"},{"en":"To rely on colleagues’ advice means to use co-workers’ opinions or experience for help.","zh":"rely on colleagues’ advice 指使用同事的意見或經驗來獲得幫助。"},{"en":"A new teacher may rely on colleagues’ advice when managing a difficult class.","zh":"新老師管理困難班級時，可能依靠同事的建議。"},{"en":"If people ask colleagues for advice, they may see solutions they missed alone.","zh":"如果人們向同事尋求建議，可能看到自己獨自時錯過的解決方法。"},{"en":"The phrase shows that support at work can reduce pressure.","zh":"這個短語顯示職場支援可以減少壓力。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":6},{"front":"coach one another through","meaning":"指導彼此處理……","examples":[{"en":"Peers coach one another through business problems.","zh":"同輩會指導彼此處理商業問題。"},{"en":"To coach one another through something means to guide each other while dealing with a difficulty.","zh":"coach one another through 某事，指在處理困難時互相指導。"},{"en":"Two nurses may coach one another through a new computer system during a busy shift.","zh":"兩名護士可能在繁忙班次中指導彼此使用新電腦系統。"},{"en":"If colleagues coach one another, they share experience and reduce isolation.","zh":"如果同事互相指導，他們會分享經驗並減少孤立感。"},{"en":"The phrase describes mutual support, not one-way instruction only.","zh":"這個短語描述互相支援，而不只是單向教導。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":6},{"front":"a fresh pair of eyes","meaning":"新的角度；旁觀者的眼光","examples":[{"en":"A fresh pair of eyes over an issue can help.","zh":"對某個問題有新的角度可以有幫助。"},{"en":"A fresh pair of eyes means a new person who can look at a problem without old assumptions.","zh":"a fresh pair of eyes 指能不帶舊假設地看問題的新人物。"},{"en":"A classmate can be a fresh pair of eyes when checking an essay draft.","zh":"同學檢查作文草稿時，可以提供新的旁觀者眼光。"},{"en":"A fresh perspective can notice mistakes that tired people no longer see.","zh":"新角度可以注意到疲倦的人不再看見的錯誤。"},{"en":"The phrase suggests that outside or new viewpoints can solve problems.","zh":"這個短語暗示外來或新觀點可以解決問題。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":6},{"front":"over an issue","meaning":"對某個問題","examples":[{"en":"A fresh pair of eyes over an issue can be useful.","zh":"對某個問題有新的旁觀者角度可能有用。"},{"en":"Over an issue means in relation to a particular problem, topic or disagreement.","zh":"over an issue 指與某個特定問題、題目或分歧有關。"},{"en":"A manager may ask for advice over an issue with staff scheduling.","zh":"經理可能就員工排班問題尋求建議。"},{"en":"If people disagree over an issue, a neutral person may help them discuss it calmly.","zh":"如果人們對某問題有分歧，中立人士可能幫助他們冷靜討論。"},{"en":"The phrase links attention or concern to one specific matter.","zh":"這個短語把注意或關注連繫到某一具體事情。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":6},{"front":"not confined to","meaning":"不限於……","examples":[{"en":"Executive stress is not confined to large organisations.","zh":"行政人員壓力不限於大型機構。"},{"en":"Not confined to something means not limited to that place, group or situation.","zh":"not confined to 某事，指不只限於該地方、群體或情況。"},{"en":"Bullying is not confined to schools; it can also happen in workplaces.","zh":"欺凌不限於學校；它也可以發生在職場。"},{"en":"If stress is not confined to big companies, small business owners can suffer too.","zh":"如果壓力不限於大公司，小企業老闆也可能受苦。"},{"en":"The phrase expands the problem beyond one obvious area.","zh":"這個短語把問題擴展到一個明顯範圍之外。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":6},{"front":"large organisations","meaning":"大型機構","examples":[{"en":"Executive stress is not confined to large organisations.","zh":"行政人員壓力不限於大型機構。"},{"en":"Large organisations are big companies, public bodies or institutions with many workers and departments.","zh":"large organisations 是有許多員工和部門的大公司、公共機構或院校。"},{"en":"A hospital network or multinational company is a large organisation.","zh":"醫院網絡或跨國公司就是大型機構。"},{"en":"Large organisations may create stress through complex systems and heavy responsibility.","zh":"大型機構可能透過複雜制度和沉重責任造成壓力。"},{"en":"The phrase contrasts big institutions with small businesses.","zh":"這個短語把大型機構與小企業作對比。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":6},{"front":"run her own business","meaning":"經營自己的生意","examples":[{"en":"Vanessa Stoykov has run her own business for seven years.","zh":"Vanessa Stoykov 經營自己的生意已有七年。"},{"en":"To run her own business means to manage and operate a company she owns.","zh":"run her own business 指管理和營運自己擁有的公司。"},{"en":"A baker who opens a shop must run her own business, not just bake bread.","zh":"開店的麵包師不只是烘焙麵包，也必須經營自己的生意。"},{"en":"Running a business can create freedom, but it also brings responsibility and stress.","zh":"經營生意可以帶來自由，但也帶來責任和壓力。"},{"en":"The phrase describes ownership and day-to-day management.","zh":"這個短語描述擁有權和日常管理。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":6},{"front":"advertising and public-relations business","meaning":"廣告和公關業務","examples":[{"en":"She runs an advertising and public-relations business.","zh":"她經營一間廣告和公關業務公司。"},{"en":"An advertising and public-relations business helps clients promote products and manage public image.","zh":"advertising and public-relations business 幫助客戶推廣產品和管理公眾形象。"},{"en":"A restaurant may hire such a business to launch a new menu and attract media attention.","zh":"餐廳可能聘請這類公司推出新餐牌並吸引媒體關注。"},{"en":"If clients expect fast results, this kind of business can become very stressful.","zh":"如果客戶期待快速成果，這類業務可以變得很有壓力。"},{"en":"The phrase combines promotion work with reputation management.","zh":"這個短語結合宣傳工作和聲譽管理。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":6},{"front":"specialise in","meaning":"專門從事","examples":[{"en":"Her business specialises in financial and professional-services firms.","zh":"她的公司專門服務金融及專業服務公司。"},{"en":"To specialise in something means to focus on one particular area of work or knowledge.","zh":"specialise in 某事，指集中於某個特定工作或知識範疇。"},{"en":"A doctor may specialise in children’s health rather than treating all patients.","zh":"醫生可能專門從事兒童健康，而不是治療所有病人。"},{"en":"If a company specialises in one field, it can build deeper expertise there.","zh":"如果公司專門從事某一範疇，它可以在該領域建立更深專業知識。"},{"en":"The phrase describes focused expertise, not general work.","zh":"這個短語描述集中專業能力，而不是一般工作。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":6},{"front":"financial and professional-services firms","meaning":"金融及專業服務公司","examples":[{"en":"The company serves financial and professional-services firms.","zh":"該公司服務金融及專業服務公司。"},{"en":"Financial and professional-services firms are companies such as banks, insurers, law firms and consultancies.","zh":"financial and professional-services firms 是銀行、保險公司、律師行和顧問公司等企業。"},{"en":"A public-relations agency may help financial firms explain complex services clearly.","zh":"公關公司可能幫助金融公司清楚解釋複雜服務。"},{"en":"If clients are professional-services firms, communication must sound accurate and trustworthy.","zh":"如果客戶是專業服務公司，溝通必須聽起來準確可信。"},{"en":"The phrase refers to businesses that sell expertise, advice or financial services.","zh":"這個短語指銷售專業知識、建議或金融服務的企業。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":7},{"front":"grew so quickly that","meaning":"增長得如此快以致……","examples":[{"en":"Evolution Media grew so quickly that it appeared on a business list.","zh":"Evolution Media 增長得如此快，以致它登上一個商業名單。"},{"en":"Grew so quickly that means expanded at such a fast rate that a clear result followed.","zh":"grew so quickly that 指擴展速度快到帶來明顯結果。"},{"en":"A café grew so quickly that the owner had to open a second branch.","zh":"咖啡店增長得如此快，以致老闆要開第二間分店。"},{"en":"Fast growth can bring success, but it can also create pressure to hire and train staff.","zh":"快速增長可以帶來成功，但也會造成招聘和培訓壓力。"},{"en":"The phrase connects rapid growth with its consequence.","zh":"這個短語把快速增長與其後果連繫起來。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":7},{"front":"appeared on the list of","meaning":"登上……名單","examples":[{"en":"The company appeared on the list of the fastest-growing small businesses.","zh":"該公司登上增長最快的小型企業名單。"},{"en":"Appeared on the list of something means was included in an official or public list.","zh":"appeared on the list of 某類別，指被列入官方或公開名單。"},{"en":"A school may appear on the list of top-performing schools after exam results improve.","zh":"學校在考試成績改善後，可能登上高表現學校名單。"},{"en":"If a business appears on a respected list, its reputation may rise.","zh":"如果企業登上受尊重的名單，其聲譽可能上升。"},{"en":"The phrase shows public recognition through inclusion.","zh":"這個短語透過被列入名單表示公開認可。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":7},{"front":"fastest-growing small businesses","meaning":"增長最快的小型企業","examples":[{"en":"Evolution Media was one of the fastest-growing small businesses.","zh":"Evolution Media 是增長最快的小型企業之一。"},{"en":"Fastest-growing small businesses are small companies whose sales, staff or influence are increasing very quickly.","zh":"fastest-growing small businesses 是銷售、人手或影響力快速增加的小公司。"},{"en":"A start-up may become one of the fastest-growing small businesses after winning many new clients.","zh":"初創公司贏得許多新客戶後，可能成為增長最快的小型企業之一。"},{"en":"Rapid growth can create excitement, but it can also increase workload and stress.","zh":"快速增長可以令人興奮，但也可以增加工作量和壓力。"},{"en":"The phrase praises growth speed while hinting at pressure behind it.","zh":"這個短語讚揚增長速度，同時暗示背後壓力。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":7},{"front":"have her first child","meaning":"生下第一個孩子","examples":[{"en":"Stoykov appeared on the list just after she had her first child.","zh":"Stoykov 剛生下第一個孩子後登上該名單。"},{"en":"To have her first child means to give birth to or welcome her first baby.","zh":"have her first child 指生下或迎來她的第一個嬰兒。"},{"en":"A business owner who has her first child may need to balance clients, staff and family care.","zh":"生下第一個孩子的企業主可能需要平衡客戶、員工和家庭照顧。"},{"en":"Having a first child can change sleep, priorities and available time.","zh":"生第一個孩子可以改變睡眠、優先事項和可用時間。"},{"en":"The phrase marks a major life event that can affect work pressure.","zh":"這個短語標示會影響工作壓力的重要人生事件。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":7},{"front":"thrive on","meaning":"因……而充滿幹勁","examples":[{"en":"She thrives on the mental stimulation of running a business.","zh":"她因經營生意帶來的精神刺激而充滿幹勁。"},{"en":"To thrive on something means to feel energised and perform well because of it.","zh":"thrive on 某事，指因它而有活力並表現良好。"},{"en":"Some students thrive on competition because it makes them work harder.","zh":"有些學生因競爭而充滿幹勁，因為競爭令他們更努力。"},{"en":"If someone thrives on challenge, a demanding job may feel exciting rather than only stressful.","zh":"如果某人因挑戰而有動力，要求高的工作可能令人興奮，而不只是有壓力。"},{"en":"The phrase describes gaining energy from something others may find difficult.","zh":"這個短語描述從別人覺得困難的事情中獲得能量。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":7},{"front":"mental stimulation","meaning":"精神刺激","examples":[{"en":"Running a business gives her mental stimulation.","zh":"經營生意給她精神刺激。"},{"en":"Mental stimulation is activity that keeps the mind active, interested and challenged.","zh":"mental stimulation 是令頭腦保持活躍、感興趣和受挑戰的活動。"},{"en":"A puzzle, debate or difficult project can provide mental stimulation.","zh":"謎題、辯論或困難項目可以提供精神刺激。"},{"en":"Mental stimulation can make work feel meaningful, but too much pressure can become stressful.","zh":"精神刺激可以令工作感覺有意義，但壓力太大會變成負擔。"},{"en":"The phrase describes challenge for the mind, not physical exercise.","zh":"這個短語描述對頭腦的挑戰，而不是身體運動。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":7},{"front":"running a business","meaning":"經營生意","examples":[{"en":"She enjoys the challenge of running a business.","zh":"她享受經營生意的挑戰。"},{"en":"Running a business means managing customers, staff, money, services and daily decisions.","zh":"running a business 指管理客戶、員工、金錢、服務和日常決策。"},{"en":"A café owner running a business must order food, pay wages and serve customers.","zh":"經營咖啡店的老闆必須訂購食材、支付工資和服務顧客。"},{"en":"Running a business can bring independence, but it often creates long hours.","zh":"經營生意可以帶來自主，但常造成長工時。"},{"en":"The phrase describes the whole responsibility of operating a company.","zh":"這個短語描述營運公司的整體責任。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":7},{"front":"the occasional day when","meaning":"偶爾有……的日子","examples":[{"en":"She has the occasional day when she feels overwhelmed.","zh":"她偶爾有感到不知所措的日子。"},{"en":"The occasional day when something happens means a day that happens sometimes but not regularly.","zh":"the occasional day when 某事發生，指該事情有時發生但不定期。"},{"en":"A teacher may have the occasional day when every class feels difficult.","zh":"老師可能偶爾有每堂課都覺得困難的日子。"},{"en":"If difficult days are only occasional, rest may help; if they become constant, workload may need review.","zh":"如果困難日子只是偶爾發生，休息可能有幫助；如果變成持續，就可能需要檢視工作量。"},{"en":"The phrase describes an event that happens from time to time.","zh":"這個短語描述有時出現的事情。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":7},{"front":"my head’s going to blow off","meaning":"頭快要爆炸","examples":[{"en":"She sometimes feels as if her head is going to blow off.","zh":"她有時覺得自己的頭快要爆炸。"},{"en":"“My head’s going to blow off” means feeling under so much pressure that the mind feels overloaded.","zh":"“my head’s going to blow off” 指壓力大到頭腦感覺負荷過重。"},{"en":"A student may say this before an exam when too many notes are still unread.","zh":"學生在考試前還有太多筆記未讀時，可能說自己頭快要爆炸。"},{"en":"This feeling can happen when demands arrive faster than a person can process them.","zh":"當要求來得比一個人能處理的速度更快，這種感覺可能出現。"},{"en":"The phrase is informal and dramatic, not a literal medical description.","zh":"這個短語是口語和誇張說法，不是字面醫學描述。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":7},{"front":"rely on short-term stress relief","meaning":"依靠短期紓壓方法","examples":[{"en":"Stoykov must rely on short-term stress relief.","zh":"Stoykov 必須依靠短期紓壓方法。"},{"en":"To rely on short-term stress relief means to depend on quick ways to feel better for a while.","zh":"rely on short-term stress relief 指依靠快速方法讓自己暫時好受一點。"},{"en":"A worker may rely on short-term stress relief such as a walk, coffee or music after a hard meeting.","zh":"員工在艱難會議後可能依靠散步、咖啡或音樂等短期紓壓方法。"},{"en":"Short-term relief can help people recover briefly, but it may not fix the workload.","zh":"短期紓緩可以幫助人短暫恢復，但未必解決工作量。"},{"en":"The phrase suggests temporary coping rather than structural change.","zh":"這個短語暗示暫時應付，而不是制度性改變。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":8},{"front":"weekends in the mountains","meaning":"到山區度周末","examples":[{"en":"Weekends in the mountains help her reduce stress temporarily.","zh":"到山區度周末幫助她暫時減輕壓力。"},{"en":"Weekends in the mountains are short breaks spent away from the city in a natural mountain area.","zh":"weekends in the mountains 是在山區自然環境中離開城市度過的短暫休息。"},{"en":"A business owner may spend weekends in the mountains to escape phone calls and traffic.","zh":"企業主可能到山區度周末，以避開電話和交通。"},{"en":"Nature breaks can calm the mind, but stress may return if work habits do not change.","zh":"親近自然的休息可以令心情平靜，但如果工作習慣不變，壓力可能回來。"},{"en":"The phrase represents a peaceful short escape from work pressure.","zh":"這個短語代表從工作壓力中短暫和平地逃離。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":8},{"front":"mental-health day","meaning":"心理健康休息日","examples":[{"en":"She sometimes takes a mental-health day.","zh":"她有時會請心理健康休息日。"},{"en":"A mental-health day is a day off used to rest and recover emotionally or mentally.","zh":"mental-health day 是用來休息並在情緒或心理上恢復的一天假。"},{"en":"An employee may take a mental-health day after weeks of anxiety and poor sleep.","zh":"員工在數星期焦慮和睡眠差後，可能請心理健康休息日。"},{"en":"A mental-health day can prevent burnout if it is combined with better workload management.","zh":"如果配合更好工作量管理，心理健康休息日可以預防倦怠。"},{"en":"The phrase treats mental recovery as a real need, not laziness.","zh":"這個短語把心理恢復視為真實需要，而不是懶惰。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":8},{"front":"rather than","meaning":"而不是","examples":[{"en":"She uses short breaks rather than delegating more work.","zh":"她使用短暫休息，而不是分派更多工作。"},{"en":"Rather than means instead of one option, another option is chosen.","zh":"rather than 指選擇一個選項，而不是另一個選項。"},{"en":"A student may ask for help rather than struggle silently for hours.","zh":"學生可能尋求幫助，而不是默默掙扎幾小時。"},{"en":"If a manager takes every task herself rather than delegating, stress may increase.","zh":"如果經理事事自己做而不是分派工作，壓力可能增加。"},{"en":"The phrase clearly contrasts two choices.","zh":"這個短語清楚對比兩個選擇。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":8},{"front":"delegating more work","meaning":"分派更多工作","examples":[{"en":"Delegating more work is difficult when a business is growing.","zh":"當企業正在增長時，分派更多工作很困難。"},{"en":"Delegating more work means giving more tasks to other people instead of doing them yourself.","zh":"delegating more work 指把更多任務交給其他人，而不是自己做。"},{"en":"A team leader may delegate more work to trained staff before a deadline.","zh":"團隊領袖可能在期限前把更多工作分派給受訓員工。"},{"en":"If delegation is not done well, the manager may spend extra time correcting mistakes.","zh":"如果分派工作做得不好，經理可能要花額外時間改錯。"},{"en":"The phrase describes sharing responsibility to reduce one person’s load.","zh":"這個短語描述分享責任以減少一個人的負擔。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":8},{"front":"hiring more people","meaning":"聘請更多人","examples":[{"en":"The company is hiring more people.","zh":"公司正在聘請更多人。"},{"en":"Hiring more people means recruiting additional staff to join an organisation.","zh":"hiring more people 指招聘額外員工加入機構。"},{"en":"A restaurant may start hiring more people when weekend queues become too long.","zh":"當周末人龍變得太長，餐廳可能開始聘請更多人。"},{"en":"Hiring more people can reduce pressure, but training them also takes time.","zh":"聘請更多人可以減輕壓力，但培訓他們也需要時間。"},{"en":"The phrase describes adding staff, not simply giving current workers more hours.","zh":"這個短語描述增加員工，而不是只要求現有員工加班。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":8},{"front":"train them and teach them about","meaning":"培訓他們並教他們關於……","examples":[{"en":"Managers need to train new staff and teach them about the clients.","zh":"管理者需要培訓新員工，並教他們關於客戶的事情。"},{"en":"To train them and teach them about something means to develop their skills and explain important background knowledge.","zh":"train them and teach them about 某事，指培養他們的技能並解釋重要背景知識。"},{"en":"A hotel manager must train new receptionists and teach them about regular guests.","zh":"酒店經理必須培訓新接待員，並教他們關於常客的資料。"},{"en":"If new workers are not trained, they may make mistakes that create more work.","zh":"如果新員工沒有受訓，他們可能犯錯，造成更多工作。"},{"en":"The phrase shows why adding staff does not reduce pressure immediately.","zh":"這個短語顯示為何增加員工不會立即減輕壓力。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":8},{"front":"the culture and the clients","meaning":"企業文化和客戶","examples":[{"en":"New employees need to learn about the culture and the clients.","zh":"新員工需要了解企業文化和客戶。"},{"en":"The culture and the clients means the company’s way of working and the people it serves.","zh":"the culture and the clients 指公司的工作方式和它所服務的人。"},{"en":"A new consultant must understand the culture and the clients before giving advice confidently.","zh":"新顧問必須理解企業文化和客戶，才能有信心地給建議。"},{"en":"If staff do not understand clients, they may damage relationships or miss expectations.","zh":"如果員工不了解客戶，他們可能損害關係或未能達到期望。"},{"en":"The phrase combines internal workplace habits with external customer needs.","zh":"這個短語結合內部工作習慣與外部客戶需要。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":8},{"front":"more work rather than less","meaning":"工作更多而不是更少","examples":[{"en":"Hiring new people can create more work rather than less.","zh":"聘請新人可能造成更多工作，而不是更少。"},{"en":"More work rather than less means the result is extra workload, not reduced workload.","zh":"more work rather than less 指結果是額外工作量，而不是工作量減少。"},{"en":"A new computer system may create more work rather than less if staff need weeks of training.","zh":"如果員工需要數星期培訓，新電腦系統可能造成更多工作而不是更少。"},{"en":"If a solution is badly timed, it can increase pressure instead of reducing it.","zh":"如果解決方法時機不當，它可以增加壓力而不是減少壓力。"},{"en":"The phrase shows an unexpected contrast between intention and result.","zh":"這個短語顯示意圖與結果之間的意外對比。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":8},{"front":"identify the causes","meaning":"找出原因","examples":[{"en":"The passage asks readers to identify the causes of stress.","zh":"文章要求讀者找出壓力的原因。"},{"en":"To identify the causes means to find the reasons why a problem happens.","zh":"identify the causes 指找出問題發生的原因。"},{"en":"A teacher may identify the causes of poor spelling by checking students’ reading habits.","zh":"老師可能透過檢查學生閱讀習慣，找出拼字差的原因。"},{"en":"If people identify the wrong causes, they may choose ineffective solutions.","zh":"如果人們找錯原因，他們可能選擇無效解決方法。"},{"en":"The phrase focuses on finding reasons before trying to fix a problem.","zh":"這個短語重點在嘗試解決問題前先找原因。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":8},{"front":"executive coaching","meaning":"行政人員教練輔導","examples":[{"en":"Jan Eisner specialises in executive coaching.","zh":"Jan Eisner 專門從事行政人員教練輔導。"},{"en":"Executive coaching is professional guidance that helps managers improve leadership, decisions and performance.","zh":"executive coaching 是幫助管理者改善領導、決策和表現的專業指導。"},{"en":"A senior manager may use executive coaching to handle conflict and stress more effectively.","zh":"高級經理可能使用行政人員教練輔導，更有效處理衝突和壓力。"},{"en":"If coaching is useful, leaders can change habits before problems damage the team.","zh":"如果教練輔導有用，領袖可以在問題損害團隊前改變習慣。"},{"en":"The phrase refers to development support for people in leadership roles.","zh":"這個短語指為領導職位人士提供的發展支援。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":9},{"front":"thriving on a demanding workload","meaning":"在繁重工作量下仍表現出色","examples":[{"en":"Thriving on a demanding workload is typical of some executives.","zh":"在繁重工作量下仍表現出色是一些行政人員的典型特徵。"},{"en":"Thriving on a demanding workload means performing well and feeling energised by heavy work demands.","zh":"thriving on a demanding workload 指在沉重工作要求下仍表現良好並感到有動力。"},{"en":"A start-up founder may thrive on a demanding workload when launching a new product.","zh":"初創公司創辦人在推出新產品時，可能在繁重工作量下仍表現出色。"},{"en":"This can be positive for a while, but constant pressure may still damage health.","zh":"這可以短期內是正面的，但持續壓力仍可能損害健康。"},{"en":"The phrase describes doing well under pressure, not simply surviving it.","zh":"這個短語描述在壓力下表現好，而不只是勉強生存。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":9},{"front":"be typical of","meaning":"是……的典型特徵","examples":[{"en":"A demanding workload is typical of senior executives.","zh":"繁重工作量是高級行政人員的典型特徵。"},{"en":"To be typical of something means to be a common or expected feature of it.","zh":"be typical of 某事，指是該事常見或預期中的特徵。"},{"en":"Long queues are typical of popular restaurants at lunchtime.","zh":"午餐時間排長隊是熱門餐廳的典型特徵。"},{"en":"If long hours are typical of a job, applicants should understand that before joining.","zh":"如果長工時是某工作的典型特徵，申請者加入前應理解。"},{"en":"The phrase describes what is normal or characteristic in a situation.","zh":"這個短語描述某情況中正常或具代表性的特徵。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":9},{"front":"high-potential businesspeople","meaning":"高潛力商界人士","examples":[{"en":"High-potential businesspeople may thrive under pressure.","zh":"高潛力商界人士可能在壓力下表現出色。"},{"en":"High-potential businesspeople are workers or leaders seen as likely to achieve strong future success.","zh":"high-potential businesspeople 是被認為日後很可能取得強大成功的員工或領袖。"},{"en":"A company may give high-potential businesspeople extra training and difficult projects.","zh":"公司可能給高潛力商界人士額外培訓和困難項目。"},{"en":"If these people receive support, pressure can help them grow rather than burn out.","zh":"如果這些人得到支援，壓力可以幫助他們成長，而不是倦怠。"},{"en":"The phrase refers to people with strong future promise in business.","zh":"這個短語指在商界有強大未來潛力的人。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":9},{"front":"adrenaline-charged periods","meaning":"充滿腎上腺素的時段","examples":[{"en":"Some people prefer adrenaline-charged periods followed by quiet times.","zh":"有些人偏好充滿腎上腺素的時段之後接着較平靜時間。"},{"en":"Adrenaline-charged periods are intense, exciting times when people feel alert and full of energy.","zh":"adrenaline-charged periods 是人們感到警覺和充滿能量的強烈、興奮時段。"},{"en":"A theatre team may experience adrenaline-charged periods before opening night.","zh":"劇團在首演夜前可能經歷充滿腎上腺素的時段。"},{"en":"These periods can improve focus, but they are tiring if they never end.","zh":"這些時段可以提高專注，但如果永不結束就會令人疲倦。"},{"en":"The phrase describes high-energy pressure that feels exciting as well as demanding.","zh":"這個短語描述既刺激又要求高的高能量壓力。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":9},{"front":"quieter patches","meaning":"較平靜的階段","examples":[{"en":"Some executives prefer busy periods followed by quieter patches.","zh":"有些行政人員偏好忙碌時段後接着較平靜的階段。"},{"en":"Quieter patches are periods with less pressure, fewer tasks or slower activity.","zh":"quieter patches 是壓力較小、任務較少或活動較慢的時段。"},{"en":"A shop may have quieter patches after the lunch rush ends.","zh":"午餐高峰結束後，商店可能有較平靜的階段。"},{"en":"Quieter patches help people recover after intense work.","zh":"較平靜階段幫助人們在強烈工作後恢復。"},{"en":"The phrase describes temporary calm, not a permanent lack of work.","zh":"這個短語描述暫時平靜，而不是永久沒有工作。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":9},{"front":"thrive under sustained pressure","meaning":"在持續壓力下表現出色","examples":[{"en":"Other executives thrive under sustained pressure.","zh":"其他行政人員在持續壓力下表現出色。"},{"en":"To thrive under sustained pressure means to perform well during long-lasting pressure.","zh":"thrive under sustained pressure 指在長期壓力下仍表現良好。"},{"en":"Some emergency doctors thrive under sustained pressure because they are trained for fast decisions.","zh":"有些急症醫生在持續壓力下表現出色，因為他們受過快速決策訓練。"},{"en":"If pressure lasts too long without recovery, even strong performers may suffer.","zh":"如果壓力持續太久而沒有恢復，即使表現強的人也可能受損。"},{"en":"The phrase describes strength under ongoing demands.","zh":"這個短語描述在持續要求下的能力。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":9},{"front":"hormonal measurements","meaning":"荷爾蒙測量","examples":[{"en":"Hormonal measurements can show whether someone is physiologically stressed.","zh":"荷爾蒙測量可以顯示某人是否在生理上受壓。"},{"en":"Hormonal measurements are tests that measure chemicals in the body linked to stress or other functions.","zh":"hormonal measurements 是測量體內與壓力或其他功能有關的化學物質的測試。"},{"en":"A doctor may use hormonal measurements when investigating unusual tiredness.","zh":"醫生調查異常疲倦時，可能使用荷爾蒙測量。"},{"en":"These measurements can show physical stress signals, but not the whole emotional experience.","zh":"這些測量可以顯示身體壓力信號，但不能顯示完整情緒經驗。"},{"en":"The phrase refers to biological data from the body.","zh":"這個短語指來自身體的生物數據。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":9},{"front":"urine and blood","meaning":"尿液和血液","examples":[{"en":"Stress can be measured through urine and blood samples.","zh":"壓力可以透過尿液和血液樣本量度。"},{"en":"Urine and blood are bodily fluids that can be tested for signs of health or stress.","zh":"urine and blood 是可以用來測試健康或壓力跡象的身體液體。"},{"en":"A clinic may collect urine and blood to check whether a patient has an infection.","zh":"診所可能收集尿液和血液，以檢查病人是否感染。"},{"en":"If tests use urine and blood, they reveal physical information from inside the body.","zh":"如果測試使用尿液和血液，它們會揭示身體內部的生理資訊。"},{"en":"The phrase refers to common medical sample types.","zh":"這個短語指常見醫學樣本類型。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":9},{"front":"physiologically stressed","meaning":"生理上受壓","examples":[{"en":"Tests can judge whether someone is physiologically stressed.","zh":"測試可以判斷某人是否生理上受壓。"},{"en":"Physiologically stressed means showing physical body signs of stress.","zh":"physiologically stressed 指顯示身體上的壓力跡象。"},{"en":"A person may be physiologically stressed even if they say they feel fine.","zh":"一個人即使說自己感覺沒事，也可能生理上受壓。"},{"en":"If the body is under stress, heart rate, hormones or sleep patterns may change.","zh":"如果身體受壓，心率、荷爾蒙或睡眠模式可能改變。"},{"en":"The phrase focuses on bodily stress, not only feelings.","zh":"這個短語重點在身體壓力，而不只是感受。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":9},{"front":"how that person experiences stress","meaning":"那個人如何感受壓力","examples":[{"en":"Medical tests cannot show exactly how that person experiences stress.","zh":"醫學測試不能準確顯示那個人如何感受壓力。"},{"en":"How a person experiences stress means what stress feels like to that individual.","zh":"how that person experiences stress 指壓力對該個人而言感覺如何。"},{"en":"One worker may experience stress as anger, while another experiences it as tiredness.","zh":"一名員工可能把壓力感受為憤怒，另一人則感受為疲倦。"},{"en":"If doctors know only the test results, they may miss the person’s emotional experience.","zh":"如果醫生只知道測試結果，可能錯過個人的情緒經驗。"},{"en":"The phrase highlights the personal side of stress.","zh":"這個短語突出壓力的個人面向。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":10},{"front":"emotional and cognitive effects","meaning":"情緒和認知影響","examples":[{"en":"Tests may not reveal the emotional and cognitive effects of stress.","zh":"測試可能不能揭示壓力的情緒和認知影響。"},{"en":"Emotional and cognitive effects are changes in feelings, thinking, memory or decision-making.","zh":"emotional and cognitive effects 是情緒、思考、記憶或決策上的變化。"},{"en":"A stressed student may feel anxious and also find it harder to remember notes.","zh":"受壓學生可能感到焦慮，也可能更難記住筆記。"},{"en":"If stress affects emotions and thinking, work quality and relationships can decline.","zh":"如果壓力影響情緒和思考，工作質素和關係都可能下降。"},{"en":"The phrase shows that stress affects more than the body.","zh":"這個短語顯示壓力影響的不只是身體。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":10},{"front":"be informed by","meaning":"受到……啟發；以……為依據","examples":[{"en":"Eisner’s practice is informed by positive psychology.","zh":"Eisner 的做法受到正向心理學啟發。"},{"en":"To be informed by something means to be guided or influenced by that knowledge or approach.","zh":"be informed by 某事，指受該知識或方法指導或影響。"},{"en":"A school’s homework policy may be informed by research on sleep and learning.","zh":"學校功課政策可能以睡眠和學習研究為依據。"},{"en":"If coaching is informed by psychology, it uses ideas about behaviour and motivation.","zh":"如果教練輔導以心理學為依據，它會使用關於行為和動機的想法。"},{"en":"The phrase shows the intellectual source behind a method.","zh":"這個短語顯示某方法背後的知識來源。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":10},{"front":"positive psychology","meaning":"正向心理學","examples":[{"en":"Positive psychology influences Eisner’s approach.","zh":"正向心理學影響 Eisner 的方法。"},{"en":"Positive psychology is a field that studies strengths, meaning, resilience and well-being.","zh":"positive psychology 是研究優勢、意義、抗逆力和幸福感的領域。"},{"en":"A teacher using positive psychology may help students notice progress, not only mistakes.","zh":"使用正向心理學的老師可能幫助學生注意進步，而不只是錯誤。"},{"en":"If workers feel engaged and meaningful, positive psychology suggests they may cope better.","zh":"如果員工感到投入和有意義，正向心理學認為他們可能更能應付壓力。"},{"en":"The phrase focuses on human strengths as well as problems.","zh":"這個短語重點在人類優勢以及問題。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":10},{"front":"a school of thought","meaning":"一個思想流派","examples":[{"en":"Positive psychology is a school of thought.","zh":"正向心理學是一個思想流派。"},{"en":"A school of thought is a shared way of thinking about a subject.","zh":"a school of thought 是對某主題的一套共同思考方式。"},{"en":"One school of thought in education says students learn best through real examples.","zh":"教育中的一個思想流派認為學生透過真實例子學得最好。"},{"en":"If a coach follows a school of thought, that approach shapes the advice given.","zh":"如果教練跟隨某思想流派，該方法會塑造所給建議。"},{"en":"The phrase refers to an intellectual tradition, not a physical school.","zh":"這個短語指思想傳統，而不是實體學校。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":10},{"front":"positive experiences","meaning":"正面經驗","examples":[{"en":"Positive experiences help people build resilience.","zh":"正面經驗幫助人建立抗逆力。"},{"en":"Positive experiences are events that give people satisfaction, meaning, confidence or hope.","zh":"positive experiences 是給人滿足感、意義、信心或希望的事件。"},{"en":"A student who receives helpful feedback may have a positive learning experience.","zh":"得到有用回饋的學生可能有正面學習經驗。"},{"en":"Positive experiences can give people energy to handle later difficulties.","zh":"正面經驗可以給人能量去處理之後的困難。"},{"en":"The phrase describes helpful moments that support well-being.","zh":"這個短語描述支援幸福感的有益時刻。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":10},{"front":"feeling engaged","meaning":"感到投入","examples":[{"en":"Feeling engaged can help people cope with stress.","zh":"感到投入可以幫助人應付壓力。"},{"en":"Feeling engaged means feeling interested, involved and mentally connected to what one is doing.","zh":"feeling engaged 指對正在做的事感興趣、參與其中並在心理上有連繫。"},{"en":"A student feels engaged when a lesson uses real-life examples and discussion.","zh":"當課堂使用生活例子和討論，學生會感到投入。"},{"en":"If workers feel engaged, pressure may feel meaningful rather than pointless.","zh":"如果員工感到投入，壓力可能感覺有意義，而不是毫無目的。"},{"en":"The phrase describes active involvement, not just being present.","zh":"這個短語描述主動參與，而不只是人在場。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":10},{"front":"feeling challenged","meaning":"感到受到挑戰","examples":[{"en":"Feeling challenged can be a positive experience.","zh":"感到受到挑戰可以是一種正面經驗。"},{"en":"Feeling challenged means being pushed to use effort and ability without being completely overwhelmed.","zh":"feeling challenged 指被推動去使用努力和能力，但沒有完全不知所措。"},{"en":"A student may feel challenged by a difficult essay that is still possible to complete.","zh":"學生面對一篇困難但仍能完成的文章時，可能感到受到挑戰。"},{"en":"Challenge can build confidence when people receive enough support.","zh":"當人們得到足夠支援，挑戰可以建立信心。"},{"en":"The phrase describes productive difficulty, not impossible pressure.","zh":"這個短語描述有生產力的困難，而不是不可能承受的壓力。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":10},{"front":"contribute to something meaningful","meaning":"為有意義的事情作出貢獻","examples":[{"en":"People benefit from being able to contribute to something meaningful.","zh":"能夠為有意義的事情作出貢獻，對人有益。"},{"en":"To contribute to something meaningful means to help with work that feels important or valuable.","zh":"contribute to something meaningful 指幫助一件感覺重要或有價值的事。"},{"en":"A volunteer may contribute to something meaningful by teaching children who cannot afford tutoring.","zh":"義工可以透過教無法負擔補習的孩子，為有意義的事情作出貢獻。"},{"en":"If work feels meaningful, people may handle pressure with more purpose.","zh":"如果工作感覺有意義，人們可能更有目的地應付壓力。"},{"en":"The phrase connects effort with a larger value.","zh":"這個短語把努力與更大的價值連繫起來。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":10},{"front":"balance negative experiences","meaning":"抵消負面經驗","examples":[{"en":"Positive experiences do not simply balance negative experiences.","zh":"正面經驗並不只是簡單抵消負面經驗。"},{"en":"To balance negative experiences means to offset bad experiences with good ones.","zh":"balance negative experiences 指用好經驗抵消壞經驗。"},{"en":"A pleasant lunch may balance a difficult morning, but it cannot solve a toxic workplace.","zh":"愉快午餐可能抵消困難早上的感覺，但不能解決有毒職場。"},{"en":"If negative experiences are constant, small positives may not be enough.","zh":"如果負面經驗持續不斷，小小正面事情可能不足夠。"},{"en":"The phrase shows contrast between harm and support.","zh":"這個短語顯示傷害與支援之間的對比。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":10},{"front":"build resilience over time","meaning":"隨時間建立抗逆力","examples":[{"en":"Positive experiences help people build resilience over time.","zh":"正面經驗幫助人隨時間建立抗逆力。"},{"en":"To build resilience over time means to gradually develop the ability to recover from difficulty.","zh":"build resilience over time 指逐漸發展從困難中恢復的能力。"},{"en":"Students build resilience over time when they learn from mistakes instead of giving up.","zh":"當學生從錯誤中學習而不是放棄，他們會隨時間建立抗逆力。"},{"en":"Repeated support and success can make future stress easier to manage.","zh":"反覆的支援和成功可以令未來壓力更容易管理。"},{"en":"The phrase stresses gradual growth, not instant toughness.","zh":"這個短語強調逐步成長，而不是即時變堅強。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":11},{"front":"good stress","meaning":"良性壓力","examples":[{"en":"Good stress can come from challenge and reward.","zh":"良性壓力可以來自挑戰和回報。"},{"en":"Good stress is pressure that feels meaningful, manageable and energising.","zh":"good stress 是感覺有意義、可管理並令人有動力的壓力。"},{"en":"A student may feel good stress before a speech because the challenge helps her prepare.","zh":"學生在演講前可能感到良性壓力，因為挑戰幫助她準備。"},{"en":"Good stress can improve focus, but too much pressure can become harmful.","zh":"良性壓力可以改善專注，但太多壓力會變得有害。"},{"en":"The phrase shows that not all stress is negative.","zh":"這個短語顯示並非所有壓力都是負面的。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":11},{"front":"challenge and reward","meaning":"挑戰與回報","examples":[{"en":"Good stress involves the positive experience of challenge and reward.","zh":"良性壓力涉及挑戰與回報這種正面經驗。"},{"en":"Challenge and reward means demanding work combined with a feeling of achievement or benefit.","zh":"challenge and reward 指要求高的工作加上成就感或好處。"},{"en":"A difficult project can offer challenge and reward when students finally solve it.","zh":"當學生最終解決困難項目時，該項目可以帶來挑戰與回報。"},{"en":"If there is challenge without reward, pressure may feel unfair and exhausting.","zh":"如果只有挑戰而沒有回報，壓力可能感覺不公平且令人疲憊。"},{"en":"The phrase explains why some hard work can feel satisfying.","zh":"這個短語解釋為何有些艱難工作會令人滿足。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":11},{"front":"be cumulative","meaning":"是累積性的","examples":[{"en":"Good stress is cumulative in the same way as bad stress.","zh":"良性壓力和負面壓力一樣是累積性的。"},{"en":"To be cumulative means to build up gradually over time.","zh":"be cumulative 指隨時間逐漸累積。"},{"en":"Small spelling mistakes are cumulative if a student never corrects them.","zh":"如果學生從不改正，小拼字錯誤會是累積性的。"},{"en":"Positive experiences can be cumulative because each one adds confidence for later challenges.","zh":"正面經驗可以是累積性的，因為每一次都為之後挑戰增加信心。"},{"en":"The phrase describes effects that grow through repeated experience.","zh":"這個短語描述透過重複經驗而增長的影響。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":11},{"front":"regulate bad stress","meaning":"調節負面壓力","examples":[{"en":"Many senior businesspeople regulate bad stress through meditation.","zh":"許多高級商界人士透過冥想調節負面壓力。"},{"en":"To regulate bad stress means to control harmful pressure so it does less damage.","zh":"regulate bad stress 指控制有害壓力，使其造成較少傷害。"},{"en":"A student may regulate bad stress by planning revision and taking short breaks.","zh":"學生可以透過規劃溫習和短暫休息來調節負面壓力。"},{"en":"If people cannot regulate bad stress, it may affect sleep, mood and health.","zh":"如果人們不能調節負面壓力，它可能影響睡眠、心情和健康。"},{"en":"The phrase focuses on managing stress rather than pretending it does not exist.","zh":"這個短語重點在管理壓力，而不是假裝壓力不存在。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":11},{"front":"meditation and yoga","meaning":"冥想和瑜伽","examples":[{"en":"Some executives use meditation and yoga to manage stress.","zh":"一些行政人員使用冥想和瑜伽來管理壓力。"},{"en":"Meditation and yoga are practices that can calm the mind, breathing and body.","zh":"meditation and yoga 是可以平靜頭腦、呼吸和身體的練習。"},{"en":"A worker may practise meditation and yoga after work to reduce tension.","zh":"員工可能下班後練習冥想和瑜伽，以減少緊張。"},{"en":"Regular practice can help people notice stress before they react badly.","zh":"定期練習可以幫助人們在反應不佳前注意到壓力。"},{"en":"The phrase refers to mind-body methods for stress management.","zh":"這個短語指管理壓力的身心方法。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":11},{"front":"cites research showing that","meaning":"引用研究指出","examples":[{"en":"Eisner cites research showing that meditation can affect the brain.","zh":"Eisner 引用研究指出冥想可以影響大腦。"},{"en":"To cite research showing that something is true means to refer to studies as evidence.","zh":"cite research showing that 某事為真，指引用研究作為證據。"},{"en":"A teacher may cite research showing that sleep improves memory.","zh":"老師可能引用研究指出睡眠能改善記憶。"},{"en":"If a speaker cites research, the argument may sound more credible.","zh":"如果演講者引用研究，論點可能聽起來更可信。"},{"en":"The phrase introduces evidence rather than personal opinion only.","zh":"這個短語引入證據，而不只是個人意見。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":11},{"front":"alter brain biochemistry","meaning":"改變腦部生物化學","examples":[{"en":"Meditation can alter brain biochemistry.","zh":"冥想可以改變腦部生物化學。"},{"en":"To alter brain biochemistry means to change chemical processes in the brain.","zh":"alter brain biochemistry 指改變大腦中的化學過程。"},{"en":"Sleep, exercise and stress can all affect brain chemistry.","zh":"睡眠、運動和壓力都可以影響腦部化學。"},{"en":"If a practice alters brain biochemistry, it may change how people respond to pressure.","zh":"如果某種練習改變腦部生物化學，它可能改變人們對壓力的反應。"},{"en":"The phrase describes a biological change inside the brain.","zh":"這個短語描述大腦內部的生物變化。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":11},{"front":"retrain the way","meaning":"重新訓練……的方式","examples":[{"en":"Meditation can retrain the way the brain responds to stress.","zh":"冥想可以重新訓練大腦對壓力作出反應的方式。"},{"en":"To retrain the way something works means to teach it a new pattern of response.","zh":"retrain the way 某物運作，指教它一種新的反應模式。"},{"en":"A speaking coach can retrain the way a student uses breathing before presentations.","zh":"口語教練可以重新訓練學生在演講前使用呼吸的方式。"},{"en":"If the brain learns a calmer response, stressful events may feel less overwhelming.","zh":"如果大腦學會較平靜的反應，壓力事件可能不再那麼令人不知所措。"},{"en":"The phrase suggests changing habits through repeated practice.","zh":"這個短語暗示透過重複練習改變習慣。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":11},{"front":"respond to stress","meaning":"對壓力作出反應","examples":[{"en":"The brain and body can learn to respond to stress differently.","zh":"大腦和身體可以學會以不同方式對壓力作出反應。"},{"en":"To respond to stress means to react physically, emotionally or mentally to pressure.","zh":"respond to stress 指在身體、情緒或心理上對壓力作出反應。"},{"en":"One person may respond to stress by becoming quiet, while another becomes angry.","zh":"一個人可能以變得沉默來回應壓力，另一人則變得憤怒。"},{"en":"If people learn calmer responses, stress may cause less damage.","zh":"如果人們學會較平靜的反應，壓力可能造成較少傷害。"},{"en":"The phrase describes reaction to pressure, not the pressure itself.","zh":"這個短語描述對壓力的反應，而不是壓力本身。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":11},{"front":"enable someone to shift","meaning":"使某人能夠轉變……","examples":[{"en":"Meditation and yoga enable people to shift their brain’s reactions.","zh":"冥想和瑜伽使人能夠轉變大腦的反應。"},{"en":"To enable someone to shift something means to make it possible for them to change it.","zh":"enable someone to shift 某事，指使某人能夠改變它。"},{"en":"A good timetable can enable students to shift from panic to steady revision.","zh":"良好時間表可以使學生從恐慌轉變為穩定溫習。"},{"en":"If training enables workers to shift their habits, stress management becomes more practical.","zh":"如果培訓使員工能夠轉變習慣，壓力管理就變得更實際。"},{"en":"The phrase connects support with change.","zh":"這個短語把支援與改變連繫起來。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":12},{"front":"become proficient","meaning":"變得熟練","examples":[{"en":"If people become proficient, they can better control their reactions.","zh":"如果人們變得熟練，他們可以更好控制自己的反應。"},{"en":"To become proficient means to become skilled and confident through practice.","zh":"become proficient 指透過練習變得有技巧和有信心。"},{"en":"A student becomes proficient in speaking when she can answer naturally without translating every word.","zh":"當學生能自然回答而不用每個字翻譯，她的口語就變得熟練。"},{"en":"If people become proficient at meditation, they may calm themselves more quickly.","zh":"如果人們在冥想上變得熟練，他們可能更快令自己平靜。"},{"en":"The phrase describes skill built over time, not instant ability.","zh":"這個短語描述隨時間建立的技能，而不是即時能力。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":12},{"front":"be in control","meaning":"掌控局面","examples":[{"en":"With practice, people can be in control.","zh":"透過練習，人們可以掌控局面。"},{"en":"To be in control means to manage a situation or one’s reactions effectively.","zh":"be in control 指有效管理情況或自己的反應。"},{"en":"A teacher is in control when the class is calm and students know what to do.","zh":"當課室平靜而學生知道要做甚麼，老師就是掌控局面。"},{"en":"If workers feel in control, pressure may become easier to handle.","zh":"如果員工覺得自己掌控局面，壓力可能較容易處理。"},{"en":"The phrase suggests confidence, order and ability to respond wisely.","zh":"這個短語暗示信心、秩序和明智回應的能力。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":12},{"front":"recent research","meaning":"近期研究","examples":[{"en":"Recent research challenges old ideas about stress.","zh":"近期研究挑戰關於壓力的舊想法。"},{"en":"Recent research means studies carried out or published not long ago.","zh":"recent research 指不久前進行或發表的研究。"},{"en":"Recent research on sleep may change how schools plan homework.","zh":"關於睡眠的近期研究可能改變學校安排功課的方式。"},{"en":"If recent research contradicts old beliefs, people may need to update their thinking.","zh":"如果近期研究與舊信念矛盾，人們可能需要更新想法。"},{"en":"The phrase introduces newer evidence.","zh":"這個短語引入較新的證據。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":12},{"front":"public servants","meaning":"公務員","examples":[{"en":"A study of public servants examined workplace stress.","zh":"一項關於公務員的研究檢視職場壓力。"},{"en":"Public servants are people who work for government or public services.","zh":"public servants 是為政府或公共服務工作的人。"},{"en":"Teachers, nurses and civil servants may be public servants depending on the system.","zh":"視乎制度，老師、護士和文職公務員都可能是公務員。"},{"en":"If public servants face high pressure with little control, public services may suffer.","zh":"如果公務員面對高壓而控制權少，公共服務可能受影響。"},{"en":"The phrase refers to workers serving the public rather than private owners.","zh":"這個短語指服務公眾而不是私人老闆的員工。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":12},{"front":"British epidemiologist","meaning":"英國流行病學家","examples":[{"en":"Sir Michael Marmot is a British epidemiologist.","zh":"Sir Michael Marmot 是一位英國流行病學家。"},{"en":"A British epidemiologist is a UK expert who studies patterns and causes of disease in populations.","zh":"British epidemiologist 是研究人口疾病模式和原因的英國專家。"},{"en":"An epidemiologist may study why some jobs are linked to poorer health.","zh":"流行病學家可能研究為何某些工作與較差健康有關。"},{"en":"If an epidemiologist studies stress, the focus may be on groups rather than one person only.","zh":"如果流行病學家研究壓力，焦點可能在群體，而不只是個人。"},{"en":"The phrase identifies both nationality and research field.","zh":"這個短語同時指出國籍和研究領域。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":12},{"front":"the most important predictor of","meaning":"……最重要的預測因素","examples":[{"en":"The most important predictor of stress is job control.","zh":"壓力最重要的預測因素是工作控制權。"},{"en":"The most important predictor of something is the factor that best helps forecast it.","zh":"the most important predictor of 某事，是最能幫助預測它的因素。"},{"en":"Sleep may be the most important predictor of a student’s concentration the next day.","zh":"睡眠可能是學生翌日專注力最重要的預測因素。"},{"en":"If job control predicts stress strongly, employers should examine how much autonomy workers have.","zh":"如果工作控制權強烈預測壓力，僱主應檢視員工有多少自主權。"},{"en":"The phrase points to the strongest warning or explanatory factor.","zh":"這個短語指出最強的警示或解釋因素。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":12},{"front":"job control","meaning":"工作控制權","examples":[{"en":"A person’s level of job control strongly predicts stress.","zh":"一個人的工作控制權水平強烈預測壓力。"},{"en":"Job control means how much freedom a worker has over tasks, timing and methods.","zh":"job control 指員工對任務、時間和方法有多少自由度。"},{"en":"A teacher has more job control when she can choose teaching materials and plan lessons flexibly.","zh":"當老師可以選擇教材並靈活備課，她就有較高工作控制權。"},{"en":"Low job control can make high demands feel more stressful.","zh":"低工作控制權可以令高要求感覺更有壓力。"},{"en":"The phrase is central to understanding why some demanding jobs harm health.","zh":"這個短語是理解為何某些高要求工作損害健康的核心。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":12},{"front":"challenge the theory that","meaning":"挑戰……的理論","examples":[{"en":"Recent research challenges the theory that stress belongs mainly to executives.","zh":"近期研究挑戰壓力主要屬於行政人員的理論。"},{"en":"To challenge the theory that something is true means to question or dispute that explanation.","zh":"challenge the theory that 某事為真，指質疑或反駁該解釋。"},{"en":"New exam data may challenge the theory that boys always perform better in science.","zh":"新考試數據可能挑戰男生總是在科學表現較好的理論。"},{"en":"If research challenges a theory, people may need a more accurate explanation.","zh":"如果研究挑戰某理論，人們可能需要更準確的解釋。"},{"en":"The phrase introduces evidence against an accepted idea.","zh":"這個短語引入反對既有想法的證據。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":12},{"front":"the preserve of","meaning":"……的專屬領域","examples":[{"en":"Stress is not simply the preserve of high-achieving executives.","zh":"壓力並不只是高成就行政人員的專屬領域。"},{"en":"The preserve of a group means something that belongs mainly or only to that group.","zh":"the preserve of 某群體，指某事主要或只屬於該群體。"},{"en":"Advanced technology is no longer the preserve of rich companies because cheaper tools are available.","zh":"先進科技不再是富裕公司的專屬領域，因為較便宜工具已經可用。"},{"en":"If stress is not the preserve of executives, ordinary workers can also be seriously affected.","zh":"如果壓力不是行政人員專屬，普通員工也可能受到嚴重影響。"},{"en":"The phrase challenges the idea that something is limited to one group.","zh":"這個短語挑戰某事只限於一個群體的想法。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":12},{"front":"high-achieving executives","meaning":"成就高的行政人員","examples":[{"en":"Stress is often associated with high-achieving executives.","zh":"壓力常與成就高的行政人員有關。"},{"en":"High-achieving executives are senior managers who perform very well and reach ambitious goals.","zh":"high-achieving executives 是表現優秀並達成高目標的高級管理者。"},{"en":"A high-achieving executive may lead major projects and manage large teams.","zh":"成就高的行政人員可能領導重大項目並管理大型團隊。"},{"en":"Success can bring recognition, but it can also bring heavier expectations.","zh":"成功可以帶來認可，但也可以帶來更高期望。"},{"en":"The phrase describes successful leaders, not all managers.","zh":"這個短語描述成功領袖，而不是所有管理者。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":13},{"front":"type-A personalities","meaning":"A型性格人士","examples":[{"en":"Stress is often linked to type-A personalities.","zh":"壓力常與A型性格人士有關。"},{"en":"Type-A personalities are people often described as competitive, impatient and strongly driven.","zh":"type-A personalities 是常被描述為好勝、急躁和非常有衝勁的人。"},{"en":"A type-A student may feel uncomfortable when a group project moves slowly.","zh":"A型性格學生在小組項目進展緩慢時，可能感到不舒服。"},{"en":"If a person is highly driven, deadlines may feel especially urgent.","zh":"如果一個人非常有衝勁，期限可能感覺特別急迫。"},{"en":"The phrase describes a personality pattern often associated with pressure.","zh":"這個短語描述常與壓力相關的性格模式。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":13},{"front":"extreme working hours","meaning":"極端工時","examples":[{"en":"Stress is often linked to extreme working hours.","zh":"壓力常與極端工時有關。"},{"en":"Extreme working hours are very long or irregular hours beyond a healthy normal pattern.","zh":"extreme working hours 是非常長或不規律、超出健康正常模式的工時。"},{"en":"A junior banker may face extreme working hours during a major deal.","zh":"初級銀行家在重大交易期間可能面對極端工時。"},{"en":"Extreme working hours can reduce sleep, family time and physical recovery.","zh":"極端工時可以減少睡眠、家庭時間和身體恢復。"},{"en":"The phrase describes work time that has become excessive.","zh":"這個短語描述已變得過度的工作時間。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":13},{"front":"suggest that","meaning":"顯示；指出","examples":[{"en":"Marmot’s research suggests that job control matters greatly.","zh":"Marmot 的研究顯示工作控制權非常重要。"},{"en":"To suggest that something is true means to indicate it as a likely conclusion.","zh":"suggest that 某事為真，指顯示它是可能的結論。"},{"en":"Falling attendance may suggest that students are unhappy with the timetable.","zh":"出席率下降可能顯示學生不滿時間表。"},{"en":"If evidence suggests a problem, leaders should investigate before it grows.","zh":"如果證據指出有問題，領導者應在問題擴大前調查。"},{"en":"The phrase presents an evidence-based idea without always stating absolute certainty.","zh":"這個短語提出有證據支持的想法，但不一定表示絕對肯定。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":13},{"front":"the best kind of job","meaning":"最理想的工作類型","examples":[{"en":"Such executives may actually have the best kind of job.","zh":"這類行政人員實際上可能擁有最理想的工作類型。"},{"en":"The best kind of job is work that combines challenge, control, meaning and manageable pressure.","zh":"the best kind of job 是結合挑戰、控制權、意義和可管理壓力的工作。"},{"en":"For some people, the best kind of job gives freedom to decide how tasks are done.","zh":"對一些人而言，最理想的工作類型給予自由去決定如何完成任務。"},{"en":"If a job has high demands and high control, it may feel exciting rather than damaging.","zh":"如果工作有高要求和高控制權，它可能令人興奮，而不是造成傷害。"},{"en":"The phrase describes an ideal type of work in the passage’s argument.","zh":"這個短語描述文章論點中的理想工作類型。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":13},{"front":"high demands","meaning":"高要求","examples":[{"en":"Some jobs combine high demands with high control.","zh":"有些工作結合高要求和高控制權。"},{"en":"High demands are heavy expectations, difficult tasks or strong pressure at work.","zh":"high demands 是工作中的沉重期望、困難任務或強大壓力。"},{"en":"A surgeon’s job has high demands because mistakes can seriously affect patients.","zh":"外科醫生的工作有高要求，因為錯誤可以嚴重影響病人。"},{"en":"High demands can be healthy if workers also have support and control.","zh":"如果員工也有支援和控制權，高要求可以是健康的。"},{"en":"The phrase describes pressure from the work itself.","zh":"這個短語描述來自工作本身的壓力。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":13},{"front":"high control","meaning":"高控制權","examples":[{"en":"The best jobs combine high demands with high control.","zh":"最理想的工作結合高要求和高控制權。"},{"en":"High control means having strong influence over how, when and in what order work is done.","zh":"high control 指對如何、何時和按甚麼次序工作有強大影響力。"},{"en":"A designer has high control when she can choose the method and schedule for a project.","zh":"當設計師可以選擇項目的方法和時間表，她就有高控制權。"},{"en":"High control can make demanding work feel more manageable.","zh":"高控制權可以令要求高的工作感覺更可管理。"},{"en":"The phrase describes autonomy that protects people from harmful stress.","zh":"這個短語描述能保護人免受有害壓力的自主權。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":13},{"front":"challenging work","meaning":"具挑戰性的工作","examples":[{"en":"A good job may involve challenging work and autonomy.","zh":"好工作可能包含具挑戰性的工作和自主權。"},{"en":"Challenging work is work that requires effort, skill and concentration.","zh":"challenging work 是需要努力、技能和專注的工作。"},{"en":"A student may enjoy challenging work when the task is difficult but meaningful.","zh":"當任務困難但有意義，學生可能享受具挑戰性的工作。"},{"en":"Challenging work can build confidence if people have enough control and feedback.","zh":"如果人們有足夠控制權和回饋，具挑戰性的工作可以建立信心。"},{"en":"The phrase describes demanding work that can be positive.","zh":"這個短語描述可以是正面的高要求工作。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":13},{"front":"autonomy","meaning":"自主權","examples":[{"en":"High autonomy can reduce the harmful effects of pressure.","zh":"高自主權可以減少壓力的有害影響。"},{"en":"Autonomy is the freedom to make decisions and control how one works.","zh":"autonomy 是作出決定和控制自己工作方式的自由。"},{"en":"A teacher has autonomy when she can choose examples that suit her students.","zh":"當老師可以選擇適合學生的例子，她就有自主權。"},{"en":"If employees lack autonomy, even simple tasks can feel frustrating.","zh":"如果員工缺乏自主權，即使簡單任務也可能令人沮喪。"},{"en":"The word describes independence and control in decision-making.","zh":"這個字描述決策中的獨立和控制。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":13},{"front":"high demands with low control","meaning":"高要求但低控制權","examples":[{"en":"The worst jobs combine high demands with low control.","zh":"最差的工作結合高要求但低控制權。"},{"en":"High demands with low control means people face heavy pressure but have little say over how to handle it.","zh":"high demands with low control 指人們面對沉重壓力，但很少能決定如何處理。"},{"en":"A call-centre worker may face high demands with low control if every script and break time is fixed.","zh":"如果每句話術和休息時間都固定，電話中心員工可能面對高要求但低控制權。"},{"en":"This combination can make stress feel unavoidable and unfair.","zh":"這種組合可以令壓力感覺無法避免且不公平。"},{"en":"The phrase describes a risky job design.","zh":"這個短語描述高風險的工作設計。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":13},{"front":"little autonomy","meaning":"缺乏自主權","examples":[{"en":"People with demanding jobs but little autonomy face serious risks.","zh":"從事高要求但缺乏自主權工作的人面對嚴重風險。"},{"en":"Little autonomy means having very little freedom to decide how to work.","zh":"little autonomy 指幾乎沒有自由決定如何工作。"},{"en":"A cashier has little autonomy if every action is timed and controlled by a supervisor.","zh":"如果每個動作都由主管計時和控制，收銀員就缺乏自主權。"},{"en":"If workers have little autonomy, they may feel trapped even when they work hard.","zh":"如果員工缺乏自主權，即使努力工作也可能感到被困住。"},{"en":"The phrase describes low control over one’s work.","zh":"這個短語描述對自己工作的控制權低。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":14},{"front":"up to four times the probability of","meaning":"高達四倍的……可能性","examples":[{"en":"These workers have up to four times the probability of depression.","zh":"這些員工患抑鬱的可能性高達四倍。"},{"en":"Up to four times the probability of something means the chance may be as high as four times greater.","zh":"up to four times the probability of 某事，指機會可能高達四倍。"},{"en":"A tired driver may have a much higher probability of making a mistake.","zh":"疲倦司機犯錯的可能性可能高得多。"},{"en":"If one group has up to four times the probability of illness, the risk difference is serious.","zh":"如果一個群體患病可能性高達四倍，風險差異就很嚴重。"},{"en":"The phrase expresses a strong increase in likelihood.","zh":"這個短語表達可能性的強烈增加。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":14},{"front":"depression","meaning":"抑鬱","examples":[{"en":"Low-control jobs increase the probability of depression.","zh":"低控制權工作增加患抑鬱的可能性。"},{"en":"Depression is a serious mental health condition involving persistent sadness, loss of interest and low energy.","zh":"depression 是涉及持續悲傷、失去興趣和低能量的嚴重心理健康狀況。"},{"en":"A worker with depression may struggle to sleep, concentrate or enjoy daily activities.","zh":"患抑鬱的員工可能難以睡眠、集中精神或享受日常活動。"},{"en":"Long-term stress can increase the risk of depression in some people.","zh":"長期壓力可以增加某些人患抑鬱的風險。"},{"en":"The word describes a medical condition, not just a bad mood for one day.","zh":"這個字描述醫學狀況，而不只是某一天心情差。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":14},{"front":"more than twice the risk of","meaning":"超過兩倍的……風險","examples":[{"en":"These workers have more than twice the risk of heart disease.","zh":"這些員工患心臟病的風險超過兩倍。"},{"en":"More than twice the risk of something means the danger is over two times higher.","zh":"more than twice the risk of 某事，指危險高出兩倍以上。"},{"en":"Smokers may face more than twice the risk of certain health problems compared with non-smokers.","zh":"與非吸煙者相比，吸煙者面對某些健康問題的風險可能超過兩倍。"},{"en":"If stress doubles a health risk, workplace design becomes a public health issue.","zh":"如果壓力令健康風險翻倍，職場設計就成為公共健康問題。"},{"en":"The phrase shows a large increase in danger.","zh":"這個短語顯示危險大幅增加。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":14},{"front":"heart disease","meaning":"心臟病","examples":[{"en":"Demanding jobs with little autonomy can increase the risk of heart disease.","zh":"要求高但缺乏自主權的工作可以增加患心臟病的風險。"},{"en":"Heart disease refers to serious health problems affecting the heart and blood vessels.","zh":"heart disease 指影響心臟和血管的嚴重健康問題。"},{"en":"A doctor may warn patients that stress, smoking and poor diet can affect heart health.","zh":"醫生可能警告病人，壓力、吸煙和飲食差會影響心臟健康。"},{"en":"If workplace stress raises heart disease risk, prevention matters beyond mental health alone.","zh":"如果職場壓力提高心臟病風險，預防就不只關乎心理健康。"},{"en":"The phrase names a major physical health condition.","zh":"這個短語指出一種重大身體健康狀況。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":14},{"front":"account for an enormous proportion of","meaning":"佔……的巨大比例","examples":[{"en":"Depression and heart disease account for an enormous proportion of chronic disease.","zh":"抑鬱和心臟病佔慢性疾病的巨大比例。"},{"en":"To account for an enormous proportion of something means to make up a very large share of it.","zh":"account for an enormous proportion of 某事，指構成其中非常大的部分。"},{"en":"Rent may account for an enormous proportion of a student’s monthly spending.","zh":"租金可能佔學生每月開支的巨大比例。"},{"en":"If two diseases account for a huge share of illness, prevention could save many lives.","zh":"如果兩種疾病佔疾病很大比例，預防可以拯救很多生命。"},{"en":"The phrase highlights a very large part of a total.","zh":"這個短語突出總數中的很大部分。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":14},{"front":"chronic disease","meaning":"慢性疾病","examples":[{"en":"Depression and heart disease are major forms of chronic disease.","zh":"抑鬱和心臟病是慢性疾病的主要形式。"},{"en":"Chronic disease is a long-term health condition that often needs ongoing management.","zh":"chronic disease 是通常需要持續管理的長期健康狀況。"},{"en":"Diabetes and heart disease are examples of chronic disease.","zh":"糖尿病和心臟病是慢性疾病的例子。"},{"en":"Chronic disease can reduce quality of life and create long-term healthcare costs.","zh":"慢性疾病可以降低生活質素並造成長期醫療成本。"},{"en":"The phrase describes illnesses that last, not short infections only.","zh":"這個短語描述持久疾病，而不只是短期感染。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":14},{"front":"potentially preventable component","meaning":"可能可預防的部分","examples":[{"en":"These conditions represent a potentially preventable component of disease.","zh":"這些疾病代表疾病中可能可預防的部分。"},{"en":"A potentially preventable component is a part of a problem that might be avoided with the right action.","zh":"potentially preventable component 是可能透過正確行動避免的問題部分。"},{"en":"Road accidents caused by speeding are a potentially preventable part of public injury.","zh":"由超速造成的交通意外是公共傷害中可能可預防的部分。"},{"en":"If stress-related illness is preventable, workplaces can reduce harm by redesigning jobs.","zh":"如果與壓力相關的疾病可預防，職場可以透過重新設計工作來減少傷害。"},{"en":"The phrase suggests there is room for prevention, not only treatment.","zh":"這個短語暗示有預防空間，而不只是治療。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":14},{"front":"overseas","meaning":"在海外","examples":[{"en":"Overseas, this research is prompting companies to change.","zh":"在海外，這項研究正促使公司改變。"},{"en":"Overseas means in other countries, especially outside the speaker’s country.","zh":"overseas 指在其他國家，尤其是在說話者本國以外。"},{"en":"A graduate may work overseas to gain international experience.","zh":"畢業生可能到海外工作，以獲得國際經驗。"},{"en":"If an idea spreads overseas, it may influence organisations in many different places.","zh":"如果想法傳到海外，它可能影響許多不同地方的機構。"},{"en":"The word describes activity beyond the home country.","zh":"這個字描述本國以外的活動。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":14},{"front":"particularly in Europe","meaning":"尤其是在歐洲","examples":[{"en":"The trend is especially strong overseas, particularly in Europe.","zh":"這趨勢在海外特別強，尤其是在歐洲。"},{"en":"Particularly in Europe means especially in European countries.","zh":"particularly in Europe 指尤其在歐洲國家。"},{"en":"Remote work has become common in many places, particularly in large European cities.","zh":"遙距工作在許多地方變得常見，尤其是在歐洲大城市。"},{"en":"If a change is strongest in Europe, researchers may examine European workplace laws and culture.","zh":"如果轉變在歐洲最強，研究人員可能檢視歐洲職場法律和文化。"},{"en":"The phrase narrows a general overseas trend to one important region.","zh":"這個短語把一般海外趨勢收窄到一個重要地區。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":14},{"front":"prompt companies to","meaning":"促使公司去……","examples":[{"en":"This research is prompting companies to redesign workplace practices.","zh":"這項研究正促使公司重新設計職場做法。"},{"en":"To prompt companies to do something means to cause or encourage them to take action.","zh":"prompt companies to do something 指造成或鼓勵公司採取行動。"},{"en":"Customer complaints may prompt a restaurant to improve service.","zh":"顧客投訴可能促使餐廳改善服務。"},{"en":"If evidence shows stress harms health, it may prompt employers to change job design.","zh":"如果證據顯示壓力損害健康，它可能促使僱主改變工作設計。"},{"en":"The phrase connects new information with action.","zh":"這個短語把新資訊與行動連繫起來。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":15},{"front":"redesign organisational practices","meaning":"重新設計機構做法","examples":[{"en":"Some companies redesign organisational practices to reduce stress.","zh":"一些公司重新設計機構做法以減少壓力。"},{"en":"To redesign organisational practices means to change the way a company structures work and decisions.","zh":"redesign organisational practices 指改變公司安排工作和決策的方式。"},{"en":"A school may redesign practices by giving teachers shared planning time.","zh":"學校可能透過給老師共同備課時間來重新設計做法。"},{"en":"If old practices create stress, redesigning them can improve health and efficiency.","zh":"如果舊做法造成壓力，重新設計它們可以改善健康和效率。"},{"en":"The phrase describes changing systems, not just telling people to relax.","zh":"這個短語描述改變制度，而不只是叫人放鬆。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":15},{"front":"increase employee autonomy","meaning":"提高員工自主權","examples":[{"en":"Companies try to increase employee autonomy.","zh":"公司嘗試提高員工自主權。"},{"en":"To increase employee autonomy means to give workers more freedom and control over their work.","zh":"increase employee autonomy 指給員工更多工作自由和控制權。"},{"en":"A manager can increase employee autonomy by letting staff choose how to organise tasks.","zh":"經理可以透過讓員工選擇如何安排任務來提高員工自主權。"},{"en":"More autonomy can reduce stress because workers feel less trapped.","zh":"更多自主權可以減少壓力，因為員工較少感到被困住。"},{"en":"The phrase describes giving employees more decision-making power.","zh":"這個短語描述給員工更多決策權。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":15},{"front":"reduce absenteeism","meaning":"減少缺勤","examples":[{"en":"Better job design can reduce absenteeism.","zh":"更好的工作設計可以減少缺勤。"},{"en":"To reduce absenteeism means to lower the number of days employees are absent from work.","zh":"reduce absenteeism 指降低員工缺勤日數。"},{"en":"A school may reduce absenteeism by improving safety and student support.","zh":"學校可以透過改善安全和學生支援來減少缺勤。"},{"en":"If workers feel healthier and more in control, they may take fewer stress-related days off.","zh":"如果員工感到更健康和更有控制權，他們可能較少因壓力請假。"},{"en":"The phrase describes improving attendance by tackling causes of absence.","zh":"這個短語描述透過處理缺勤原因來改善出勤。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":15},{"front":"raise productivity","meaning":"提高生產力","examples":[{"en":"Increasing autonomy may help raise productivity.","zh":"提高自主權可能有助提高生產力。"},{"en":"To raise productivity means to increase the amount or quality of useful work produced.","zh":"raise productivity 指增加有用工作產出的數量或質素。"},{"en":"A quiet workspace can raise productivity because workers lose less time to interruptions.","zh":"安靜工作空間可以提高生產力，因為員工較少因打斷而浪費時間。"},{"en":"If employees have more control, they may work more efficiently and produce better results.","zh":"如果員工有更多控制權，他們可能更有效率地工作並產生更好結果。"},{"en":"The phrase describes improving output, not simply working longer hours.","zh":"這個短語描述改善產出，而不只是工作更長時間。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":15},{"front":"unrealistic expectations","meaning":"不切實際的期望","examples":[{"en":"Stress is often caused by unrealistic expectations.","zh":"壓力常由不切實際的期望造成。"},{"en":"Unrealistic expectations are demands or hopes that cannot reasonably be achieved.","zh":"unrealistic expectations 是不能合理達成的要求或希望。"},{"en":"A boss has unrealistic expectations if she wants a full report finished in ten minutes.","zh":"如果老闆想在十分鐘內完成完整報告，她就是有不切實際的期望。"},{"en":"Unrealistic expectations can create pressure, disappointment and conflict.","zh":"不切實際的期望可以造成壓力、失望和衝突。"},{"en":"The phrase describes goals that ignore real time, resources or limits.","zh":"這個短語描述忽視真實時間、資源或限制的目標。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":15},{"front":"set ourselves","meaning":"為自己訂立……","examples":[{"en":"We often set unrealistic expectations for ourselves.","zh":"我們常為自己訂立不切實際的期望。"},{"en":"To set ourselves something means to create a goal, rule or demand for our own behaviour.","zh":"set ourselves 某事，指為自己的行為建立目標、規則或要求。"},{"en":"A student may set herself the goal of learning fifty new words a day.","zh":"學生可能為自己訂立每天學五十個新詞的目標。"},{"en":"If we set ourselves impossible targets, we create stress before anyone else pressures us.","zh":"如果我們為自己訂立不可能的目標，別人未施壓前我們已造成壓力。"},{"en":"The phrase shows self-imposed expectations.","zh":"這個短語顯示自我施加的期望。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":15},{"front":"promise one client that","meaning":"向一位客戶承諾","examples":[{"en":"He may promise one client that he will finish a task tomorrow.","zh":"他可能向一位客戶承諾明天完成任務。"},{"en":"To promise one client that something will happen means to give that customer a firm commitment.","zh":"promise one client that 某事會發生，指向該客戶作出堅定承諾。"},{"en":"A designer may promise one client that the logo will be ready by Friday.","zh":"設計師可能向一位客戶承諾標誌會在星期五前完成。"},{"en":"If the promise is unrealistic, the worker creates pressure for himself and his team.","zh":"如果承諾不切實際，員工就為自己和團隊製造壓力。"},{"en":"The phrase shows how overcommitment can begin with one promise.","zh":"這個短語顯示過度承諾如何由一個承諾開始。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":15},{"front":"even though","meaning":"即使","examples":[{"en":"He makes promises even though he knows they are unrealistic.","zh":"即使他知道那些承諾不切實際，他仍作出承諾。"},{"en":"Even though means although a fact is true, another action still happens.","zh":"even though 指雖然某事為真，另一個行動仍然發生。"},{"en":"A student may stay up late even though she knows she needs sleep.","zh":"即使學生知道自己需要睡眠，她仍可能熬夜。"},{"en":"If people agree to deadlines even though they are impossible, stress increases.","zh":"如果人們即使知道期限不可能，仍答應期限，壓力就會增加。"},{"en":"The phrase introduces a contrast between knowledge and action.","zh":"這個短語引出認知與行動之間的對比。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":15},{"front":"put stress on myself","meaning":"給自己施加壓力","examples":[{"en":"He puts stress on himself by overpromising.","zh":"他透過過度承諾給自己施加壓力。"},{"en":"To put stress on myself means to create pressure for myself through my own choices.","zh":"put stress on myself 指透過自己的選擇為自己製造壓力。"},{"en":"A student puts stress on herself when she leaves all revision until the night before.","zh":"學生把所有溫習留到前一晚，就是給自己施加壓力。"},{"en":"If people overpromise, they may create stress before the client even complains.","zh":"如果人們過度承諾，客戶還未投訴前，他們已造成壓力。"},{"en":"The phrase describes self-created pressure.","zh":"這個短語描述自我造成的壓力。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":15},{"front":"could have said","meaning":"本可以說","examples":[{"en":"He could have said that he needed 48 hours.","zh":"他本可以說他需要48小時。"},{"en":"Could have said means there was a possible thing to say in the past, but it was not said.","zh":"could have said 指過去本來有一句可能說的話，但沒有說。"},{"en":"A student could have said she needed help before missing the deadline.","zh":"學生本可以在錯過期限前說自己需要幫助。"},{"en":"If someone could have given a more realistic answer, later stress might have been avoided.","zh":"如果某人本可以給出更現實的答案，之後的壓力可能可以避免。"},{"en":"The phrase often expresses a missed opportunity.","zh":"這個短語常表達錯失的機會。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":16},{"front":"the client doesn’t care","meaning":"客戶並不介意","examples":[{"en":"The client may not care if the task takes 48 hours.","zh":"如果任務需時48小時，客戶可能並不介意。"},{"en":"The client doesn’t care means the customer is not troubled by that detail or delay.","zh":"the client doesn’t care 指客戶不被該細節或延誤困擾。"},{"en":"A client may not care whether a report arrives today or tomorrow if the quality is good.","zh":"如果報告質素好，客戶可能不介意它今天或明天到達。"},{"en":"If the client does not mind, rushing may create unnecessary stress.","zh":"如果客戶不介意，趕工可能造成不必要壓力。"},{"en":"The phrase shows that pressure sometimes comes from our own assumptions.","zh":"這個短語顯示壓力有時來自我們自己的假設。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":16},{"front":"overcommitment","meaning":"過度承諾","examples":[{"en":"People experience overcommitment as an individual problem.","zh":"人們把過度承諾經歷為個人問題。"},{"en":"Overcommitment means agreeing to do more than one can realistically complete.","zh":"overcommitment 指答應做超出自己實際可完成範圍的事情。"},{"en":"A student shows overcommitment when she joins five clubs while preparing for exams.","zh":"學生一邊準備考試，一邊加入五個學會，就是過度承諾。"},{"en":"Overcommitment can lead to missed deadlines, stress and guilt.","zh":"過度承諾可以導致錯過期限、壓力和內疚。"},{"en":"The phrase describes promising too much, not simply being hardworking.","zh":"這個短語描述承諾太多，而不只是努力工作。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":16},{"front":"individual problem","meaning":"個人問題","examples":[{"en":"Overcommitment is often treated as an individual problem.","zh":"過度承諾常被視為個人問題。"},{"en":"An individual problem is seen as belonging to one person rather than a whole system.","zh":"individual problem 是被看作屬於一個人，而不是整個系統的問題。"},{"en":"A worker’s lateness may look like an individual problem until managers notice trains are often delayed.","zh":"員工遲到可能看似個人問題，直到經理注意到火車經常延誤。"},{"en":"If stress is treated only as an individual problem, workplace causes may be ignored.","zh":"如果壓力只被視為個人問題，職場原因可能被忽略。"},{"en":"The phrase contrasts personal responsibility with wider structural causes.","zh":"這個短語把個人責任與更廣泛的結構原因作對比。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":16},{"front":"procrastination","meaning":"拖延","examples":[{"en":"People may explain overcommitment as procrastination.","zh":"人們可能把過度承諾解釋為拖延。"},{"en":"Procrastination means delaying tasks even though delay may create problems later.","zh":"procrastination 指延遲任務，即使延遲之後可能造成問題。"},{"en":"A student shows procrastination when she scrolls on her phone instead of starting homework.","zh":"學生不開始做功課而滑手機，就是拖延。"},{"en":"Procrastination can make small tasks become urgent and stressful.","zh":"拖延可以令小任務變得緊急和有壓力。"},{"en":"The word describes delay, not lack of ability.","zh":"這個字描述延遲，而不是能力不足。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":16},{"front":"Parkinson’s law","meaning":"帕金森定律","examples":[{"en":"Parkinson’s law says that work expands to fill the time available.","zh":"帕金森定律說工作會膨脹至填滿可用時間。"},{"en":"Parkinson’s law is the idea that tasks often take all the time people allow for them.","zh":"Parkinson’s law 是指任務常會用盡人們給它的所有時間。"},{"en":"If a student gives herself two hours to write one paragraph, the paragraph may take two hours.","zh":"如果學生給自己兩小時寫一段，那一段可能真的花兩小時。"},{"en":"This law helps explain why generous deadlines do not always reduce pressure.","zh":"這條定律幫助解釋為何寬鬆期限不一定減少壓力。"},{"en":"The phrase names a principle about time use and work expansion.","zh":"這個短語指出一條關於時間使用和工作膨脹的原則。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":16},{"front":"work expands to fill the time available","meaning":"工作會膨脹至填滿可用時間","examples":[{"en":"People explain overcommitment by saying that work expands to fill the time available.","zh":"人們用「工作會膨脹至填滿可用時間」來解釋過度承諾。"},{"en":"Work expands to fill the time available means tasks often take as long as the deadline allows.","zh":"work expands to fill the time available 指任務常會花掉期限容許的全部時間。"},{"en":"A student given one week for a worksheet may spend the whole week finishing it.","zh":"如果學生有一星期完成工作紙，他可能用整個星期才完成。"},{"en":"If people assume later time is free, tasks can grow until that time is full.","zh":"如果人們以為之後的時間是空的，任務可以膨脹到填滿那段時間。"},{"en":"The phrase explains why extra time does not always mean less pressure.","zh":"這個短語解釋為何額外時間不一定代表壓力較少。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":16},{"front":"hard-wired to behave this way","meaning":"天生傾向這樣行事","examples":[{"en":"New research suggests that people may be hard-wired to behave this way.","zh":"新研究顯示人們可能天生傾向這樣行事。"},{"en":"Hard-wired to behave this way means naturally or deeply inclined to act in this pattern.","zh":"hard-wired to behave this way 指自然或深層地傾向以這種模式行動。"},{"en":"Some people seem hard-wired to check their phones whenever they feel bored.","zh":"有些人似乎天生傾向一感到無聊就查看手機。"},{"en":"If people are hard-wired to underestimate future busyness, overcommitment becomes common.","zh":"如果人們天生傾向低估未來忙碌程度，過度承諾就會很常見。"},{"en":"The phrase suggests a deep habit or tendency, not a simple conscious choice.","zh":"這個短語暗示深層習慣或傾向，而不是簡單有意識選擇。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":16},{"front":"the February issue of","meaning":"……的二月刊","examples":[{"en":"A study appeared in the February issue of the journal.","zh":"一項研究刊登在該期刊的二月刊。"},{"en":"The February issue of a journal is the edition published for February.","zh":"the February issue of 某期刊，是為二月出版的版本。"},{"en":"A new article may appear in the March issue of a school magazine.","zh":"新文章可能刊登在校刊三月刊。"},{"en":"If a study appears in a journal issue, readers can locate it by month and publication.","zh":"如果研究出現在某期期刊，讀者可以按月份和出版物找出它。"},{"en":"The phrase gives publication timing.","zh":"這個短語提供出版時間。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":16},{"front":"Journal of Experimental Psychology","meaning":"《實驗心理學期刊》","examples":[{"en":"The study was published in the Journal of Experimental Psychology.","zh":"該研究刊登於《實驗心理學期刊》。"},{"en":"The Journal of Experimental Psychology is an academic journal that publishes psychology research.","zh":"Journal of Experimental Psychology 是刊登心理學研究的學術期刊。"},{"en":"A university student may read this journal when researching memory or decision-making.","zh":"大學生研究記憶或決策時，可能閱讀這本期刊。"},{"en":"If a study is published in an academic journal, it is part of scholarly discussion.","zh":"如果研究刊登在學術期刊中，它就是學術討論的一部分。"},{"en":"The phrase names the publication source of the research.","zh":"這個短語指出該研究的出版來源。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":16},{"front":"consistently believe","meaning":"一直相信","examples":[{"en":"People consistently believe that they will be less busy later.","zh":"人們一直相信自己之後會較不忙。"},{"en":"To consistently believe something means to keep believing it repeatedly over time.","zh":"consistently believe 某事，指隨時間反覆持續相信它。"},{"en":"Students may consistently believe they will revise tomorrow, even after delaying many times.","zh":"學生可能一直相信自己明天會溫習，即使已多次拖延。"},{"en":"If people consistently believe future time will be freer, they may accept too many commitments now.","zh":"如果人們一直相信未來時間會更空，他們現在可能接受太多承諾。"},{"en":"The phrase shows a repeated pattern of belief.","zh":"這個短語顯示重複出現的信念模式。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":17},{"front":"less busy in the future","meaning":"將來較不忙","examples":[{"en":"People believe they will be less busy in the future.","zh":"人們相信自己將來會較不忙。"},{"en":"Less busy in the future means having fewer demands or more free time later.","zh":"less busy in the future 指之後要求較少或空閒時間較多。"},{"en":"A student may think she will be less busy after exams, but new tasks may appear.","zh":"學生可能以為考試後會較不忙，但新任務可能出現。"},{"en":"If people expect future life to be quieter, they may agree to too many future tasks.","zh":"如果人們期待未來生活較清閒，他們可能答應太多未來任務。"},{"en":"The phrase describes an optimistic assumption about later time.","zh":"這個短語描述對之後時間的樂觀假設。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":17},{"front":"according to","meaning":"根據","examples":[{"en":"According to the report’s authors, this belief is a misconception.","zh":"根據報告作者，這種信念是一種錯誤觀念。"},{"en":"According to someone means based on what that person or source says.","zh":"according to 某人或某來源，指根據其所說。"},{"en":"According to the timetable, the last bus leaves at ten o’clock.","zh":"根據時間表，最後一班巴士十點開出。"},{"en":"If an answer is according to the passage, it should be supported by the text.","zh":"如果答案是根據文章，它應得到文本支持。"},{"en":"The phrase introduces a source of information.","zh":"這個短語引出資訊來源。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":17},{"front":"report’s authors","meaning":"報告作者","examples":[{"en":"The report’s authors describe the belief as a misconception.","zh":"報告作者把這種信念描述為錯誤觀念。"},{"en":"The report’s authors are the people who wrote the research report.","zh":"report’s authors 是撰寫研究報告的人。"},{"en":"A report’s authors may explain what their findings mean and what limits they have.","zh":"報告作者可能解釋研究發現的意思和限制。"},{"en":"If the authors warn about a misconception, readers should notice the main argument.","zh":"如果作者警告某個錯誤觀念，讀者應注意主要論點。"},{"en":"The phrase identifies who is responsible for the report’s claims.","zh":"這個短語指出誰對報告中的主張負責。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":17},{"front":"misconception","meaning":"錯誤觀念","examples":[{"en":"The belief that we will be less busy later is a misconception.","zh":"我們之後會較不忙這種信念是一種錯誤觀念。"},{"en":"A misconception is a wrong idea that many people may believe is true.","zh":"misconception 是許多人可能相信為真的錯誤想法。"},{"en":"It is a misconception that good students never need help.","zh":"認為好學生從不需要幫助是一種錯誤觀念。"},{"en":"Misconceptions can lead to poor decisions because people act on false assumptions.","zh":"錯誤觀念可以導致差劣決定，因為人們根據錯誤假設行動。"},{"en":"The word describes a mistaken belief, not a simple unknown fact.","zh":"這個字描述錯誤信念，而不是單純不知道某事。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":17},{"front":"on average","meaning":"平均而言","examples":[{"en":"On average, a person will be just as busy in the future.","zh":"平均而言，一個人在未來會一樣忙。"},{"en":"On average means considering the general result across many cases.","zh":"on average 指考慮許多情況後的一般結果。"},{"en":"On average, students who sleep more concentrate better in morning lessons.","zh":"平均而言，睡得較多的學生在早上課堂中更能集中。"},{"en":"If people are on average just as busy later, future free time may be overestimated.","zh":"如果人們之後平均而言一樣忙，未來空閒時間可能被高估。"},{"en":"The phrase gives a typical pattern, not a rule for every single person.","zh":"這個短語給出典型模式，而不是每個人都適用的規則。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":17},{"front":"just as busy","meaning":"一樣忙","examples":[{"en":"A person will be just as busy two weeks from now.","zh":"一個人在兩星期後會一樣忙。"},{"en":"Just as busy means equally busy, not less busy.","zh":"just as busy 指同樣忙，而不是較不忙。"},{"en":"A student may think next week will be easier, but she may be just as busy with new assignments.","zh":"學生可能以為下星期會輕鬆些，但她可能因新功課而一樣忙。"},{"en":"If the future is just as busy, accepting extra tasks now creates overload later.","zh":"如果未來一樣忙，現在接受額外任務會造成之後負荷過重。"},{"en":"The phrase compares two times and says the workload is the same.","zh":"這個短語比較兩個時間，並表示工作量相同。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":17},{"front":"two weeks or a month from now","meaning":"兩星期或一個月後","examples":[{"en":"People may be just as busy two weeks or a month from now.","zh":"人們兩星期或一個月後可能一樣忙。"},{"en":"Two weeks or a month from now means a short future period beginning from the present.","zh":"two weeks or a month from now 指從現在開始的短期未來。"},{"en":"A worker may assume she will be free two weeks from now, but another project may arrive.","zh":"員工可能假設自己兩星期後有空，但另一個項目可能到來。"},{"en":"If future demands are underestimated, commitments made now can become stressful later.","zh":"如果未來需求被低估，現在作出的承諾之後會變得有壓力。"},{"en":"The phrase points to near-future time, not a distant life stage.","zh":"這個短語指近期未來，而不是遙遠人生階段。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":17},{"front":"everyday life","meaning":"日常生活","examples":[{"en":"That is not how it appears in everyday life.","zh":"這並不是它在日常生活中看起來的樣子。"},{"en":"Everyday life means ordinary daily experience outside theory or research.","zh":"everyday life 指理論或研究以外的普通日常經驗。"},{"en":"In everyday life, people often feel next month will be calmer than today.","zh":"在日常生活中，人們常覺得下個月會比今天更平靜。"},{"en":"If research differs from everyday life, people may find the conclusion surprising.","zh":"如果研究與日常生活感受不同，人們可能覺得結論意外。"},{"en":"The phrase contrasts real daily perception with abstract findings.","zh":"這個短語把真實日常感知與抽象研究發現作對比。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":17},{"front":"make commitments far in advance","meaning":"很早以前作出承諾","examples":[{"en":"People often make commitments far in advance.","zh":"人們常很早以前作出承諾。"},{"en":"To make commitments far in advance means to agree to do things long before they happen.","zh":"make commitments far in advance 指在事情發生前很久就答應去做。"},{"en":"A teacher may agree in January to organise a school event in June.","zh":"老師可能在一月答應六月籌辦學校活動。"},{"en":"If people make too many future commitments, their later schedule can become crowded.","zh":"如果人們作出太多未來承諾，他們之後的日程會變得擁擠。"},{"en":"The phrase explains how future overload begins early.","zh":"這個短語解釋未來負荷過重如何早早開始。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":17},{"front":"immediate action","meaning":"即時行動","examples":[{"en":"People avoid commitments if they require immediate action.","zh":"如果承諾需要即時行動，人們會避開它們。"},{"en":"Immediate action is something that must be done now or very soon.","zh":"immediate action 是現在或很快必須完成的事情。"},{"en":"A leaking pipe requires immediate action before it damages the floor.","zh":"漏水水管需要即時行動，否則會損壞地板。"},{"en":"If a request needs immediate action, people can feel the time cost clearly.","zh":"如果請求需要即時行動，人們會清楚感受到時間成本。"},{"en":"The phrase contrasts urgent present work with distant future work.","zh":"這個短語把緊急當前工作與遙遠未來工作作對比。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":18},{"front":"discount future time investments","meaning":"大幅低估未來時間投入","examples":[{"en":"People discount future time investments relatively steeply.","zh":"人們相當大幅度地低估未來時間投入。"},{"en":"To discount future time investments means to underestimate how costly future tasks will be in time.","zh":"discount future time investments 指低估未來任務在時間上的成本。"},{"en":"A student may agree to help at a fair next month because she discounts the time it will take.","zh":"學生可能因低估所需時間而答應下月幫忙校園市集。"},{"en":"If people discount future time too much, they overcommit and later feel trapped.","zh":"如果人們太低估未來時間，就會過度承諾，之後感到被困。"},{"en":"The phrase describes undervaluing future time compared with present time.","zh":"這個短語描述相比當前時間低估未來時間價值。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":18},{"front":"relatively steeply","meaning":"相當大幅度地","examples":[{"en":"People discount future time investments relatively steeply.","zh":"人們相當大幅度地低估未來時間投入。"},{"en":"Relatively steeply means quite sharply compared with what might be expected.","zh":"relatively steeply 指相比預期而言相當急劇或大幅。"},{"en":"Prices may rise relatively steeply when supplies become limited.","zh":"當供應變得有限，價格可能相當大幅度地上升。"},{"en":"If people discount future time steeply, distant tasks seem easier than they really are.","zh":"如果人們大幅低估未來時間，遙遠任務會看起來比實際容易。"},{"en":"The phrase describes a strong degree of change or underestimation.","zh":"這個短語描述強烈程度的變化或低估。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":18},{"front":"perceive a greater surplus of future time","meaning":"覺得將來有更多剩餘時間","examples":[{"en":"People perceive a greater surplus of future time than they really have.","zh":"人們覺得將來有比實際更多的剩餘時間。"},{"en":"To perceive a greater surplus of future time means to think there will be more spare time later than there actually will be.","zh":"perceive a greater surplus of future time 指以為之後會有比實際更多的空閒時間。"},{"en":"A parent may think next month has plenty of free evenings, then discover school events fill them.","zh":"家長可能以為下個月有很多空閒晚上，然後發現學校活動填滿了它們。"},{"en":"If people overestimate future free time, they may accept too many tasks.","zh":"如果人們高估未來空閒時間，他們可能接受太多任務。"},{"en":"The phrase describes a false sense of future availability.","zh":"這個短語描述對未來可用時間的錯誤感覺。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":18},{"front":"underestimate how long","meaning":"低估……需時多久","examples":[{"en":"People underestimate how long future tasks will take.","zh":"人們低估未來任務需時多久。"},{"en":"To underestimate how long something will take means to think it needs less time than it really does.","zh":"underestimate how long 某事 will take 指以為它需要的時間比實際少。"},{"en":"A student may underestimate how long an essay will take and start too late.","zh":"學生可能低估作文需時多久，結果開始得太遲。"},{"en":"If people underestimate time, deadlines become stressful and rushed.","zh":"如果人們低估時間，期限會變得有壓力且匆忙。"},{"en":"The phrase describes a common planning mistake.","zh":"這個短語描述常見計劃錯誤。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":18},{"front":"future tasks","meaning":"未來任務","examples":[{"en":"People underestimate how long future tasks will take.","zh":"人們低估未來任務需時多久。"},{"en":"Future tasks are jobs or responsibilities that must be done later.","zh":"future tasks 是之後必須完成的工作或責任。"},{"en":"A student’s future tasks may include revising, writing reports and attending interviews.","zh":"學生的未來任務可能包括溫習、寫報告和參加面試。"},{"en":"If future tasks are ignored, they can arrive together and create overload.","zh":"如果未來任務被忽略，它們可能一起到來並造成負荷過重。"},{"en":"The phrase refers to work not yet done but already waiting.","zh":"這個短語指尚未完成但已等待着的工作。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":18},{"front":"poor at imagining","meaning":"不善於想像","examples":[{"en":"People are poor at imagining future demands on their time.","zh":"人們不善於想像將來對時間的需求。"},{"en":"To be poor at imagining something means to be bad at picturing or estimating it accurately.","zh":"poor at imagining 某事，指不擅長準確想像或估計它。"},{"en":"A new student may be poor at imagining how long university reading will take.","zh":"新生可能不善於想像大學閱讀需要多久。"},{"en":"If people are poor at imagining future pressure, they may make unrealistic promises.","zh":"如果人們不善於想像未來壓力，他們可能作出不切實際的承諾。"},{"en":"The phrase describes weak ability to predict a situation clearly.","zh":"這個短語描述清楚預測情況的能力弱。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":18},{"front":"future demands on their time","meaning":"將來對時間的需求","examples":[{"en":"People underestimate future demands on their time.","zh":"人們低估將來對時間的需求。"},{"en":"Future demands on their time are later tasks, responsibilities or events that will require hours and attention.","zh":"future demands on their time 是之後需要時間和注意力的任務、責任或事件。"},{"en":"A parent may forget future demands such as school meetings, doctor visits and family duties.","zh":"家長可能忘記未來需求，例如學校會議、覆診和家庭責任。"},{"en":"If future demands are underestimated, today’s easy promise becomes tomorrow’s stress.","zh":"如果未來時間需求被低估，今天輕鬆的承諾會變成明天的壓力。"},{"en":"The phrase describes future claims on someone’s limited time.","zh":"這個短語描述未來對某人有限時間的要求。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":18},{"front":"look at the following statements","meaning":"查看以下陳述","examples":[{"en":"Candidates look at the following statements before matching them with people.","zh":"考生先查看以下陳述，再把它們與人物配對。"},{"en":"Look at the following statements means read the sentences listed below the instruction.","zh":"look at the following statements 指閱讀指示下方列出的句子。"},{"en":"In a reading test, students should look at the following statements and underline key words.","zh":"在閱讀測驗中，學生應查看以下陳述並劃出關鍵字。"},{"en":"If candidates do not read the statements carefully, they may match the wrong person.","zh":"如果考生不仔細閱讀陳述，可能配錯人物。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":18},{"front":"match each statement with","meaning":"將每項陳述與……配對","examples":[{"en":"Students match each statement with the correct person.","zh":"學生將每項陳述與正確人物配對。"},{"en":"To match each statement with someone means to connect every sentence to the person who said or supports it.","zh":"match each statement with 某人，指把每句陳述連接到說出或支持它的人。"},{"en":"In a history lesson, students may match each quote with the correct leader.","zh":"在歷史課中，學生可能把每段引文與正確領袖配對。"},{"en":"If two people discuss similar ideas, students must look for precise evidence.","zh":"如果兩個人討論相似想法，學生必須尋找精確證據。"},{"en":"The phrase describes a matching task based on meaning.","zh":"這個短語描述根據意思進行的配對題。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":18},{"front":"the correct person","meaning":"正確人物","examples":[{"en":"Each statement must be matched with the correct person.","zh":"每項陳述必須與正確人物配對。"},{"en":"The correct person is the individual who best fits the statement according to the passage.","zh":"the correct person 是根據文章最符合該陳述的人。"},{"en":"In an interview article, students must identify which speaker made which point.","zh":"在訪問文章中，學生必須辨認哪位發言者提出哪個觀點。"},{"en":"If the correct person is chosen, the answer matches both the idea and the source.","zh":"如果選出正確人物，答案就同時配合想法和來源。"},{"en":"The phrase reminds students to link information to the right speaker.","zh":"這個短語提醒學生把資訊連到正確發言者。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":19},{"front":"may use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"Candidates may use any letter more than once.","zh":"考生可以重複使用任何字母。"},{"en":"May use any letter more than once means the same option can be chosen for more than one answer.","zh":"may use any letter more than once 指同一選項可以用於多於一個答案。"},{"en":"In a matching exercise, one paragraph letter may answer two different questions.","zh":"在配對練習中，同一段落字母可能回答兩道不同問題。"},{"en":"If students think each letter can be used only once, they may force wrong answers.","zh":"如果學生以為每個字母只能用一次，他們可能強行選錯答案。"},{"en":"The phrase gives flexibility in exam matching tasks.","zh":"這個短語在考試配對題中給予彈性。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":19},{"front":"usually associated with","meaning":"通常與……有關","examples":[{"en":"Workplace stress is usually associated with senior levels of business.","zh":"職場壓力通常與商界高層有關。"},{"en":"Usually associated with something means commonly connected with it in people’s minds.","zh":"usually associated with 某事，指在人們心中通常與它連繫。"},{"en":"Long holidays are usually associated with travel, but some people use them for rest at home.","zh":"長假通常與旅行有關，但有些人用來在家休息。"},{"en":"If stress is usually associated with executives, people may overlook stress among junior staff.","zh":"如果壓力通常與行政人員有關，人們可能忽視初級員工的壓力。"},{"en":"The phrase describes a common link, not always a true rule.","zh":"這個短語描述常見連繫，不一定是真實規則。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":19},{"front":"senior levels of business","meaning":"商界高層","examples":[{"en":"Workplace stress is often associated with senior levels of business.","zh":"職場壓力常與商界高層有關。"},{"en":"Senior levels of business are the higher management positions in companies.","zh":"senior levels of business 是公司中的較高管理職位。"},{"en":"People at senior levels of business may make decisions about budgets, staff and strategy.","zh":"商界高層人士可能作出關於預算、人手和策略的決定。"},{"en":"Because responsibility is high, pressure at senior levels can be intense.","zh":"因為責任重大，高層壓力可以很強烈。"},{"en":"The phrase refers to top layers of business leadership.","zh":"這個短語指商業領導層的上層。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":19},{"front":"adding people or other resources","meaning":"增加人手或其他資源","examples":[{"en":"Adding people or other resources can help relieve stress.","zh":"增加人手或其他資源可以幫助紓緩壓力。"},{"en":"Adding people or other resources means increasing staff, tools, money or time for a task.","zh":"adding people or other resources 指為任務增加員工、工具、金錢或時間。"},{"en":"A school may add teaching assistants or software to support overloaded teachers.","zh":"學校可能增加助教或軟件，以支援負荷過重的老師。"},{"en":"If resources increase, one person does not have to carry the whole workload alone.","zh":"如果資源增加，一個人就不用獨自承擔全部工作量。"},{"en":"The phrase describes practical support for reducing pressure.","zh":"這個短語描述減壓的實際支援。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":19},{"front":"relieve stress","meaning":"紓緩壓力","examples":[{"en":"Extra resources can help relieve stress.","zh":"額外資源可以幫助紓緩壓力。"},{"en":"To relieve stress means to reduce pressure and make someone feel less burdened.","zh":"relieve stress 指減少壓力，令人感覺負擔較輕。"},{"en":"A walk after work may relieve stress for a short time.","zh":"下班後散步可能短暫紓緩壓力。"},{"en":"Better staffing can relieve stress more deeply than a one-day break.","zh":"更好人手配置可以比一天休息更深入地紓緩壓力。"},{"en":"The phrase describes lowering tension or pressure.","zh":"這個短語描述降低緊張或壓力。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":19},{"front":"a short break","meaning":"短暫休息","examples":[{"en":"A short break can sometimes create more work.","zh":"短暫休息有時會造成更多工作。"},{"en":"A short break is a brief period of rest away from work or study.","zh":"a short break 是離開工作或學習的一小段休息時間。"},{"en":"A student may take a short break after finishing one section of revision.","zh":"學生完成一部分溫習後，可能短暫休息。"},{"en":"Short breaks can restore energy, but urgent tasks may pile up if no one covers the work.","zh":"短暫休息可以恢復精力，但如果無人接手工作，緊急任務可能堆積。"},{"en":"The phrase describes temporary rest, not a full solution.","zh":"這個短語描述暫時休息，而不是完整解決方法。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":19},{"front":"create more work rather than less","meaning":"令工作更多而不是更少","examples":[{"en":"A short break can create more work rather than less.","zh":"短暫休息可能令工作更多而不是更少。"},{"en":"Create more work rather than less means increase the workload instead of reducing it.","zh":"create more work rather than less 指增加工作量，而不是減少工作量。"},{"en":"A rushed holiday can create more work rather than less if emails pile up unanswered.","zh":"如果電郵無人回覆而堆積，匆忙假期可能令工作更多而不是更少。"},{"en":"If a solution delays problems without solving them, it may increase later pressure.","zh":"如果解決方法只是延遲問題而不解決它，之後壓力可能增加。"},{"en":"The phrase highlights an unintended opposite result.","zh":"這個短語突出意料之外的相反結果。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":19},{"front":"satisfy clients","meaning":"滿足客戶","examples":[{"en":"Trying to satisfy clients by overpromising can create stress.","zh":"嘗試透過過度承諾滿足客戶可以造成壓力。"},{"en":"To satisfy clients means to meet customers’ needs or expectations.","zh":"satisfy clients 指滿足顧客需要或期望。"},{"en":"A designer may satisfy clients by listening carefully and explaining realistic timelines.","zh":"設計師可以透過仔細聆聽和解釋現實時間表來滿足客戶。"},{"en":"If workers try to satisfy every demand immediately, they may create impossible pressure.","zh":"如果員工嘗試立即滿足每個要求，他們可能造成不可能承受的壓力。"},{"en":"The phrase describes pleasing customers, but it needs boundaries.","zh":"這個短語描述令客戶滿意，但需要界線。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":19},{"front":"overpromising","meaning":"過度承諾","examples":[{"en":"Overpromising can create unnecessary stress.","zh":"過度承諾可以造成不必要壓力。"},{"en":"Overpromising means promising more than one can realistically deliver.","zh":"overpromising 指承諾超出自己實際能做到的事情。"},{"en":"A tutor overpromises if he says a beginner will become fluent in one week.","zh":"如果導師說初學者一星期內會變流利，他就是過度承諾。"},{"en":"Overpromising can disappoint clients and exhaust workers.","zh":"過度承諾可以令客戶失望並令員工疲憊。"},{"en":"The phrase warns against saying yes too easily.","zh":"這個短語提醒人不要太輕易答應。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":19},{"front":"generally believe that","meaning":"普遍相信","examples":[{"en":"People generally believe that they will be less busy later.","zh":"人們普遍相信自己之後會較不忙。"},{"en":"Generally believe that means most people usually think something is true.","zh":"generally believe that 指大多數人通常認為某事是真的。"},{"en":"Students generally believe that next term will be easier, even before seeing the timetable.","zh":"學生在看到時間表前，可能普遍相信下學期會較容易。"},{"en":"If many people share the same belief, it can shape common behaviour.","zh":"如果許多人有同一信念，它可以塑造常見行為。"},{"en":"The phrase reports a broad belief, not one person’s private opinion.","zh":"這個短語報告廣泛信念，而不是某人的私人意見。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":20},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Candidates choose the correct letter in the multiple-choice section.","zh":"考生在多項選擇部分選出正確字母。"},{"en":"Choose the correct letter means select the letter that matches the right answer.","zh":"choose the correct letter 指選出與正確答案相配的字母。"},{"en":"In an exam, students must choose the correct letter, not write a full sentence.","zh":"在考試中，學生必須選出正確字母，而不是寫完整句子。"},{"en":"If the wrong letter is chosen, the answer is wrong even if the student understood the text.","zh":"如果選錯字母，即使學生理解文本，答案也會錯。"},{"en":"The phrase is a standard instruction in reading tests.","zh":"這個短語是閱讀測驗中的標準指示。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":20},{"front":"which of the following","meaning":"以下哪一項","examples":[{"en":"The question asks which of the following warning signs is not mentioned.","zh":"題目問以下哪一項警號並未被提及。"},{"en":"Which of the following asks students to choose from the listed options.","zh":"which of the following 要求學生從列出的選項中選擇。"},{"en":"A teacher may ask which of the following words best completes the sentence.","zh":"老師可能問以下哪一個詞最能完成句子。"},{"en":"If a question says “which of the following,” students must check every option.","zh":"如果題目說 which of the following，學生必須檢查每個選項。"},{"en":"The phrase introduces a multiple-choice question.","zh":"這個短語引出多項選擇題。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":20},{"front":"is NOT mentioned by","meaning":"並非由……提及","examples":[{"en":"Students identify which warning sign is not mentioned by Plumridge.","zh":"學生辨認哪個警號並非由 Plumridge 提及。"},{"en":"Is NOT mentioned by someone means that person does not say or refer to it.","zh":"is NOT mentioned by 某人，指該人沒有說到或提到它。"},{"en":"In a listening test, students must notice which detail is not mentioned by the speaker.","zh":"在聆聽測驗中，學生必須注意哪個細節並非由說話者提及。"},{"en":"If an option sounds reasonable but is not mentioned, it should not be chosen.","zh":"如果選項聽起來合理但文中沒有提及，就不應選擇。"},{"en":"The phrase tests evidence from the text, not general knowledge.","zh":"這個短語測試文本證據，而不是常識。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":20},{"front":"insufficient time with family","meaning":"與家人相處時間不足","examples":[{"en":"Insufficient time with family is a warning sign of stress.","zh":"與家人相處時間不足是壓力警號。"},{"en":"Insufficient time with family means not having enough time to spend with loved ones.","zh":"insufficient time with family 指沒有足夠時間與親人相處。"},{"en":"A parent may notice insufficient family time when work calls interrupt every dinner.","zh":"當工作電話打斷每次晚飯，家長可能注意到與家人相處時間不足。"},{"en":"If family time becomes too limited, relationships may become strained.","zh":"如果家庭時間太有限，關係可能變得緊張。"},{"en":"The phrase describes a personal-life signal that work is taking too much.","zh":"這個短語描述工作佔據太多私人生活的信號。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":20},{"front":"inability to concentrate on work","meaning":"無法集中精神工作","examples":[{"en":"The option mentions an inability to concentrate on work.","zh":"選項提到無法集中精神工作。"},{"en":"Inability to concentrate on work means being unable to focus properly on job tasks.","zh":"inability to concentrate on work 指不能妥善專注於工作任務。"},{"en":"A worker with poor sleep may stare at emails but fail to understand them.","zh":"睡眠差的員工可能盯着電郵，卻無法理解內容。"},{"en":"If people cannot concentrate, mistakes and delays become more likely.","zh":"如果人們不能集中精神，錯誤和延誤會更可能發生。"},{"en":"The phrase describes a possible effect of stress or tiredness.","zh":"這個短語描述壓力或疲倦的可能影響。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":20},{"front":"insufficient sleep","meaning":"睡眠不足","examples":[{"en":"Insufficient sleep may be a warning sign of stress.","zh":"睡眠不足可能是壓力警號。"},{"en":"Insufficient sleep means not getting enough sleep for normal health and performance.","zh":"insufficient sleep 指沒有足夠睡眠以維持正常健康和表現。"},{"en":"A student with insufficient sleep may feel slow and forgetful in morning lessons.","zh":"睡眠不足的學生在早上課堂可能反應慢和善忘。"},{"en":"If insufficient sleep continues, mood, memory and immunity may suffer.","zh":"如果睡眠不足持續，心情、記憶和免疫力可能受影響。"},{"en":"The phrase describes a shortage of rest, not just staying up late once.","zh":"這個短語描述休息不足，而不只是偶爾熬夜。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":20},{"front":"repeatedly rescheduling appointments","meaning":"反覆重新安排約會","examples":[{"en":"Repeatedly rescheduling appointments can signal overload.","zh":"反覆重新安排約會可以顯示負荷過重。"},{"en":"Repeatedly rescheduling appointments means changing meeting times again and again.","zh":"repeatedly rescheduling appointments 指一次又一次更改會面時間。"},{"en":"A dentist may repeatedly reschedule appointments if emergencies fill the calendar.","zh":"如果突發情況填滿日程，牙醫可能反覆重新安排約會。"},{"en":"If appointments keep moving, people may lose trust and the worker may feel more stressed.","zh":"如果約會不斷改動，人們可能失去信任，而員工可能更有壓力。"},{"en":"The phrase shows a schedule that is no longer stable.","zh":"這個短語顯示日程已不再穩定。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":20},{"front":"methods of reducing workload pressure","meaning":"減輕工作量壓力的方法","examples":[{"en":"The question asks about methods of reducing workload pressure.","zh":"題目問減輕工作量壓力的方法。"},{"en":"Methods of reducing workload pressure are practical ways to make work demands more manageable.","zh":"methods of reducing workload pressure 是令工作要求更可管理的實際方法。"},{"en":"A manager may reduce pressure by adding staff, extending deadlines or changing priorities.","zh":"經理可以透過增加人手、延長期限或改變優先次序來減壓。"},{"en":"If the method addresses the real cause, stress is more likely to fall.","zh":"如果方法處理真正原因，壓力更可能下降。"},{"en":"The phrase focuses on solutions to excessive work demands.","zh":"這個短語重點在解決過高工作要求的方法。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":20},{"front":"lowering expectations","meaning":"降低期望","examples":[{"en":"Lowering expectations may help reduce workload pressure.","zh":"降低期望可能有助減輕工作量壓力。"},{"en":"Lowering expectations means reducing what people are expected to achieve within a given time.","zh":"lowering expectations 指降低人們在指定時間內被期望達成的事情。"},{"en":"A teacher may lower expectations for one week if students are preparing for exams.","zh":"如果學生正在準備考試，老師可能一星期內降低期望。"},{"en":"If expectations are lowered realistically, workers may produce better work with less panic.","zh":"如果期望被現實地降低，員工可能以較少恐慌完成更好工作。"},{"en":"The phrase does not mean giving up; it means making demands more reasonable.","zh":"這個短語不是指放棄，而是令要求更合理。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":20},{"front":"taking exercise or having a massage","meaning":"做運動或按摩","examples":[{"en":"Taking exercise or having a massage may provide temporary relief.","zh":"做運動或按摩可能提供暫時紓緩。"},{"en":"Taking exercise or having a massage means using physical activity or body treatment to reduce tension.","zh":"taking exercise or having a massage 指用身體活動或身體療法減少緊張。"},{"en":"A worker may go jogging or book a massage after a stressful week.","zh":"員工在壓力大的一星期後，可能去跑步或預約按摩。"},{"en":"These activities can help the body relax, but they may not reduce the workload itself.","zh":"這些活動可以幫助身體放鬆，但未必減少工作量本身。"},{"en":"The phrase gives examples of short-term stress relief.","zh":"這個短語給出短期紓壓方法的例子。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":21},{"front":"view of workplace stress","meaning":"對職場壓力的看法","examples":[{"en":"The question asks about Jan Eisner’s view of workplace stress.","zh":"題目問 Jan Eisner 對職場壓力的看法。"},{"en":"A view of workplace stress is an opinion or explanation about what causes stress and how it should be handled.","zh":"view of workplace stress 是關於壓力原因和應如何處理的意見或解釋。"},{"en":"A manager’s view of workplace stress may affect whether employees receive support or blame.","zh":"經理對職場壓力的看法可能影響員工得到支援還是責備。"},{"en":"If someone views stress as partly structural, they may recommend job redesign.","zh":"如果某人把壓力看作部分由制度造成，他可能建議重新設計工作。"},{"en":"The phrase asks for a person’s understanding of the issue.","zh":"這個短語詢問某人如何理解該議題。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":21},{"front":"medical tests reveal only part of","meaning":"醫學測試只揭示……的一部分","examples":[{"en":"Medical tests reveal only part of the information needed to understand stress.","zh":"醫學測試只揭示理解壓力所需資訊的一部分。"},{"en":"Medical tests reveal only part of something means they show some evidence but not the full picture.","zh":"medical tests reveal only part of 某事，指它們顯示部分證據，但不是完整圖像。"},{"en":"A blood test may show tiredness is not caused by infection, but it cannot show all emotional pressure.","zh":"驗血可能顯示疲倦並非由感染造成，但不能顯示所有情緒壓力。"},{"en":"If tests reveal only part of a problem, interviews and personal history may also be needed.","zh":"如果測試只揭示問題一部分，面談和個人歷史也可能需要。"},{"en":"The phrase warns that biological data alone is limited.","zh":"這個短語提醒人，單靠生物數據有限。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":21},{"front":"bodily samples","meaning":"身體樣本","examples":[{"en":"Indicators from bodily samples do not tell the whole story.","zh":"來自身體樣本的指標不能說明全部情況。"},{"en":"Bodily samples are materials taken from the body, such as blood, urine or saliva.","zh":"bodily samples 是從身體取得的材料，例如血液、尿液或唾液。"},{"en":"A clinic may use bodily samples to check hormone levels or infection signs.","zh":"診所可能使用身體樣本檢查荷爾蒙水平或感染跡象。"},{"en":"Bodily samples can show physical information, but they may not show personal feelings.","zh":"身體樣本可以顯示生理資訊，但未必顯示個人感受。"},{"en":"The phrase refers to biological material used in medical testing.","zh":"這個短語指醫學測試所用的生物材料。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":21},{"front":"decisive role","meaning":"決定性作用","examples":[{"en":"The option claims that bodily samples play the decisive role.","zh":"選項聲稱身體樣本發揮決定性作用。"},{"en":"A decisive role is the most important role in determining a result.","zh":"decisive role 是決定結果時最重要的作用。"},{"en":"Good sleep may play a decisive role in how well a student performs in an exam.","zh":"良好睡眠可能在學生考試表現中發揮決定性作用。"},{"en":"If one factor plays the decisive role, other factors matter less.","zh":"如果一個因素發揮決定性作用，其他因素就較不重要。"},{"en":"The phrase describes the factor that most strongly decides the outcome.","zh":"這個短語描述最強烈決定結果的因素。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":21},{"front":"emotional effects","meaning":"情緒影響","examples":[{"en":"Stress can have emotional effects as well as physical effects.","zh":"壓力可以有情緒影響以及身體影響。"},{"en":"Emotional effects are changes in feelings, such as anxiety, anger, sadness or fear.","zh":"emotional effects 是情感上的變化，例如焦慮、憤怒、悲傷或恐懼。"},{"en":"A student under pressure may experience emotional effects before exam day.","zh":"受壓學生可能在考試日前經歷情緒影響。"},{"en":"If emotional effects are ignored, stress may damage relationships and motivation.","zh":"如果情緒影響被忽略，壓力可能損害關係和動力。"},{"en":"The phrase focuses on feelings rather than body symptoms only.","zh":"這個短語重點在感受，而不只是身體症狀。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":21},{"front":"physical effects","meaning":"身體影響","examples":[{"en":"Stress can produce both emotional and physical effects.","zh":"壓力可以產生情緒和身體影響。"},{"en":"Physical effects are changes in the body, such as headaches, tiredness or poor sleep.","zh":"physical effects 是身體上的變化，例如頭痛、疲倦或睡眠差。"},{"en":"A worker under pressure may notice physical effects like tight shoulders and stomach pain.","zh":"受壓員工可能注意到肩膀緊和胃痛等身體影響。"},{"en":"If stress creates physical effects, the body is showing that pressure is too high.","zh":"如果壓力造成身體影響，身體正在顯示壓力太高。"},{"en":"The phrase focuses on bodily signs of a problem.","zh":"這個短語重點在問題的身體跡象。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":21},{"front":"a single well-designed solution","meaning":"一個設計完善的單一方案","examples":[{"en":"A single well-designed solution cannot eliminate all stress.","zh":"一個設計完善的單一方案不能消除所有壓力。"},{"en":"A single well-designed solution is one carefully planned answer to a problem.","zh":"a single well-designed solution 是一個仔細計劃的問題解方。"},{"en":"A new timetable may be a well-designed solution for one class but not for the whole school.","zh":"新時間表可能是某班的完善方案，但不適用於全校。"},{"en":"If stress has many causes, one solution cannot fix every case.","zh":"如果壓力有很多原因，一個方案不能解決所有情況。"},{"en":"The phrase suggests that complex problems usually need several responses.","zh":"這個短語暗示複雜問題通常需要幾種回應。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":21},{"front":"eliminate all stress","meaning":"消除所有壓力","examples":[{"en":"No single solution can eliminate all stress.","zh":"沒有單一方案可以消除所有壓力。"},{"en":"To eliminate all stress means to remove every source and feeling of pressure.","zh":"eliminate all stress 指移除所有壓力來源和壓力感。"},{"en":"A school cannot eliminate all exam stress, but it can give students clearer support.","zh":"學校不能消除所有考試壓力，但可以給學生更清楚支援。"},{"en":"Trying to remove all stress may be unrealistic because some challenge is part of growth.","zh":"嘗試消除所有壓力可能不切實際，因為一些挑戰是成長的一部分。"},{"en":"The phrase describes a complete removal that is difficult to achieve.","zh":"這個短語描述難以達成的完全移除。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":21},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Candidates complete the summary below using words from the passage.","zh":"考生使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the short text that follows.","zh":"complete the summary below 指在下面的短文中填入缺失字詞。"},{"en":"In a reading test, students complete the summary below by finding exact words in the passage.","zh":"在閱讀測驗中，學生透過在文章中找原字來完成以下摘要。"},{"en":"If the grammar of the blank does not fit, the chosen word is probably wrong.","zh":"如果空格文法不合，所選字詞很可能錯。"},{"en":"The phrase is a common instruction for summary-completion questions.","zh":"這個短語是摘要填空題的常見指示。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":21},{"front":"NO MORE THAN TWO WORDS AND/OR A NUMBER","meaning":"不超過兩個詞及／或一個數字","examples":[{"en":"Candidates choose no more than two words and/or a number from the passage.","zh":"考生從文章中選擇不超過兩個詞及／或一個數字。"},{"en":"NO MORE THAN TWO WORDS AND/OR A NUMBER means the answer may contain up to two words plus a number if needed.","zh":"NO MORE THAN TWO WORDS AND/OR A NUMBER 指答案最多可包含兩個詞，並在需要時加上一個數字。"},{"en":"An answer such as “16.6 weeks” fits this instruction because it uses a number and one word.","zh":"例如 “16.6 weeks” 符合這個指示，因為它使用一個數字和一個詞。"},{"en":"If students write too many words, the answer may be marked wrong even if the idea is correct.","zh":"如果學生寫太多詞，即使意思正確也可能被判錯。"},{"en":"The phrase gives a strict word-limit rule.","zh":"這個短語給出嚴格字數限制。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":22},{"front":"national workers’ compensation statistics","meaning":"全國工傷賠償統計數字","examples":[{"en":"National workers’ compensation statistics indicate that stress causes serious absence.","zh":"全國工傷賠償統計數字顯示壓力造成嚴重缺勤。"},{"en":"National workers’ compensation statistics are countrywide figures about work-related injury or illness claims.","zh":"national workers’ compensation statistics 是全國範圍內關於工作相關傷病申索的數字。"},{"en":"A government may use these statistics to decide which workplace risks need attention.","zh":"政府可能使用這些統計數字來決定哪些職場風險需要關注。"},{"en":"If stress appears strongly in national statistics, it is not just a private problem.","zh":"如果壓力在全國統計中明顯出現，它就不只是私人問題。"},{"en":"The phrase refers to official data across a whole country.","zh":"這個短語指整個國家的官方數據。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":22},{"front":"the leading cause of","meaning":"……的主要原因","examples":[{"en":"Stress is the leading cause of lost time.","zh":"壓力是工作時間損失的主要原因。"},{"en":"The leading cause of something is the main or most important reason it happens.","zh":"the leading cause of 某事，是它發生的主要或最重要原因。"},{"en":"Poor sleep may be the leading cause of a student’s weak concentration.","zh":"睡眠差可能是學生專注力弱的主要原因。"},{"en":"If stress is the leading cause of absence, employers should treat it as a major risk.","zh":"如果壓力是缺勤的主要原因，僱主應把它視為重大風險。"},{"en":"The phrase identifies the strongest cause among several possible causes.","zh":"這個短語指出幾個可能原因中最強的原因。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":22},{"front":"because of stress","meaning":"因壓力而","examples":[{"en":"Employees are absent for weeks because of stress.","zh":"員工因壓力而缺勤多個星期。"},{"en":"Because of stress means stress is the reason for the result.","zh":"because of stress 指壓力是造成結果的原因。"},{"en":"A student may miss school because of stress before a major exam.","zh":"學生可能因大考前壓力而缺課。"},{"en":"If workers stay home because of stress, the workplace loses time and people suffer.","zh":"如果員工因壓力而留在家中，職場會損失時間，而人也會受苦。"},{"en":"The phrase clearly links stress with an effect.","zh":"這個短語清楚把壓力與結果連繫起來。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":22},{"front":"provide temporary relief","meaning":"提供暫時紓緩","examples":[{"en":"Activities such as golf and massage may provide temporary relief.","zh":"打高爾夫球和按摩等活動可能提供暫時紓緩。"},{"en":"To provide temporary relief means to reduce discomfort or pressure for a short time.","zh":"provide temporary relief 指短時間減少不適或壓力。"},{"en":"Listening to music may provide temporary relief after a difficult school day.","zh":"困難上課日後聽音樂可能提供暫時紓緩。"},{"en":"Temporary relief can help people breathe, but it may not remove the cause of stress.","zh":"暫時紓緩可以幫助人喘息，但未必移除壓力原因。"},{"en":"The phrase describes short-term help rather than a permanent solution.","zh":"這個短語描述短期幫助，而不是永久解決方法。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":22},{"front":"specialists recommend reassessing","meaning":"專家建議重新評估……","examples":[{"en":"Specialists recommend reassessing workloads instead.","zh":"專家反而建議重新評估工作量。"},{"en":"Specialists recommend reassessing something means experts advise people to review it again carefully.","zh":"specialists recommend reassessing 某事，指專家建議人們再次仔細檢視它。"},{"en":"Doctors may recommend reassessing a treatment plan if symptoms keep returning.","zh":"如果症狀不斷復發，醫生可能建議重新評估治療計劃。"},{"en":"If specialists recommend reassessing workloads, they think the structure of work may be the problem.","zh":"如果專家建議重新評估工作量，他們認為問題可能在工作結構。"},{"en":"The phrase introduces expert advice to look again before acting.","zh":"這個短語引出專家建議在行動前重新檢視。"}],"source":"50 - Stress of Workplace.pdf","sourcePage":22}],"ielts/reading/passage-2/Practice 51":[{"front":"Keep the Water Away","meaning":"避免洪水侵襲","examples":[{"en":"The article is titled “Keep the Water Away” because it discusses ways to control flooding.","zh":"文章題為 “Keep the Water Away”，因為它討論控制水災的方法。"},{"en":"“Keep the Water Away” means preventing unwanted water from reaching homes, roads, fields, or cities.","zh":"“Keep the Water Away” 指阻止不需要的水到達房屋、道路、農田或城市。"},{"en":"A family may use sandbags to keep the water away from the front door during a storm.","zh":"風暴期間，家庭可能用沙包避免洪水侵襲前門。"},{"en":"If a city cannot keep the water away, streets may flood and transport may stop.","zh":"如果城市無法避免洪水侵襲，街道可能水浸，交通可能停頓。"},{"en":"This phrase is useful when talking about flood defence, drainage, or protecting land from water.","zh":"這個短語適合用於談論防洪、排水或保護土地免受水害。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":1},{"front":"last winter’s floods","meaning":"去年冬天的水災","examples":[{"en":"Last winter’s floods in central Europe were among the worst since the Middle Ages.","zh":"中歐去年冬天的水災是自中世紀以來最嚴重之一。"},{"en":"Last winter’s floods means the floods that happened during the previous winter.","zh":"last winter’s floods 指上一個冬天發生的水災。"},{"en":"A town may still be repairing bridges damaged by last winter’s floods.","zh":"一個城鎮可能仍在修復去年冬天的水災所損壞的橋樑。"},{"en":"Serious floods can leave problems for months after the water disappears.","zh":"嚴重水災即使水退後，仍可能留下數月問題。"},{"en":"This phrase places a flood event in a recent past winter.","zh":"這個短語把水災事件放在最近一個過去冬季之中。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":1},{"front":"among the worst since","meaning":"自……以來最嚴重之一","examples":[{"en":"The floods were among the worst since the Middle Ages.","zh":"這次水災是自中世紀以來最嚴重之一。"},{"en":"Among the worst since means one of the most serious cases from a particular past time until now.","zh":"among the worst since 指從某個過去時間到現在，其中最嚴重的情況之一。"},{"en":"The hospital shortage was among the worst since the city began keeping records.","zh":"醫院人手短缺是該市開始記錄以來最嚴重之一。"},{"en":"This phrase shows that a problem is unusually severe compared with a long period.","zh":"這個短語顯示某問題與很長時期相比異常嚴重。"},{"en":"It does not always mean the single worst; it means one of the worst.","zh":"它不一定指最嚴重的一次，而是指最嚴重之一。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":1},{"front":"the Middle Ages","meaning":"中世紀","examples":[{"en":"Some floods in Europe were described as the worst since the Middle Ages.","zh":"歐洲有些水災被描述為自中世紀以來最嚴重。"},{"en":"The Middle Ages refers to a long period of European history between ancient times and the modern period.","zh":"Middle Ages 指歐洲歷史中古代與現代之間的一段漫長時期。"},{"en":"Students may study castles, knights, churches, and towns from the Middle Ages.","zh":"學生可能研究中世紀的城堡、騎士、教堂和城鎮。"},{"en":"Referring to the Middle Ages makes the comparison sound extremely long-term.","zh":"提到中世紀會令比較聽起來是極長期的。"},{"en":"This phrase is often used in historical comparisons.","zh":"這個短語常用於歷史比較。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":1},{"front":"as winter storms return","meaning":"隨着冬季風暴再次來臨","examples":[{"en":"As winter storms return, the spectre of floods is returning too.","zh":"隨着冬季風暴再次來臨，水災的陰影也再次出現。"},{"en":"As winter storms return means when severe storms come back during the winter season.","zh":"as winter storms return 指當嚴重風暴在冬季再次來臨時。"},{"en":"As winter storms return, coastal residents may check roofs, drains, and emergency supplies.","zh":"隨着冬季風暴再次來臨，沿岸居民可能檢查屋頂、排水渠和應急用品。"},{"en":"Returning storms can bring back old fears if a place flooded before.","zh":"如果某地曾經水浸，風暴再次來臨可以帶回舊有恐懼。"},{"en":"This phrase links seasonal weather with renewed danger.","zh":"這個短語把季節性天氣與重新出現的危險連繫起來。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":1},{"front":"the spectre of floods","meaning":"水災的陰影","examples":[{"en":"The spectre of floods returns whenever severe winter storms arrive.","zh":"每當嚴重冬季風暴來臨，水災的陰影就會回來。"},{"en":"The spectre of floods means the frightening possibility or threat of floods.","zh":"spectre of floods 指令人害怕的水災可能性或威脅。"},{"en":"After one bad flood, heavy rain can bring back the spectre of floods for local families.","zh":"一次嚴重水災後，大雨可以為本地家庭帶回水災的陰影。"},{"en":"A threat may feel real even before the disaster actually happens.","zh":"即使災難尚未真正發生，威脅也可能感覺很真實。"},{"en":"This phrase gives flood risk a haunting, fearful image.","zh":"這個短語把水災風險描寫成陰魂般令人恐懼的形象。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":1},{"front":"the River Rhône","meaning":"羅訥河","examples":[{"en":"The River Rhône in south-east France burst its banks just weeks ago.","zh":"法國東南部的羅訥河就在幾星期前決堤。"},{"en":"The River Rhône is a major river flowing through parts of Switzerland and south-eastern France.","zh":"River Rhône 是一條流經瑞士部分地區和法國東南部的大河。"},{"en":"Towns near the River Rhône may need flood defences when winter rain is heavy.","zh":"當冬季降雨嚴重時，羅訥河附近城鎮可能需要防洪設施。"},{"en":"A large river can become dangerous when storms increase its flow too quickly.","zh":"當風暴令流量上升太快，大河可能變得危險。"},{"en":"This phrase names a specific European river.","zh":"這個短語命名一條具體歐洲河流。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":1},{"front":"burst its banks","meaning":"河水決堤；河水漫過河岸","examples":[{"en":"The River Rhône burst its banks and forced thousands of people to leave their homes.","zh":"羅訥河河水決堤，迫使數千人離開家園。"},{"en":"When a river bursts its banks, its water rises over the sides and floods nearby land.","zh":"當河流 burst its banks，河水會升過兩岸並淹沒附近土地。"},{"en":"After three days of heavy rain, the small river burst its banks and covered the road.","zh":"連續三天大雨後，小河漫過河岸並淹沒道路。"},{"en":"If a river bursts its banks near homes, families may need to evacuate quickly.","zh":"如果河流在住宅附近漫過河岸，家庭可能需要迅速撤離。"},{"en":"This phrase describes a river overflowing, not a dam exploding.","zh":"這個短語描述河水氾濫，而不是水壩爆炸。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":1},{"front":"drive people from their homes","meaning":"迫使人們離開家園","examples":[{"en":"The flood drove 15,000 people from their homes.","zh":"水災迫使一萬五千人離開家園。"},{"en":"To drive people from their homes means to force them to leave because staying is unsafe or impossible.","zh":"drive people from their homes 指因留下不安全或不可能，而迫使人們離家。"},{"en":"A fire can drive people from their homes if smoke spreads through an apartment block.","zh":"如果煙霧蔓延整棟公寓，火災可以迫使人們離開家園。"},{"en":"Floods may drive families from their homes for weeks while repairs are made.","zh":"水災可能迫使家庭離開家園數星期，直至維修完成。"},{"en":"This phrase describes forced displacement, not voluntary moving.","zh":"這個短語描述被迫流離失所，而不是自願搬遷。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":1},{"front":"worse could be on the way","meaning":"情況可能會更壞","examples":[{"en":"Officials warned that worse could be on the way.","zh":"官員警告情況可能會更壞。"},{"en":"Worse could be on the way means a more serious problem may happen soon.","zh":"worse could be on the way 指更嚴重的問題可能很快發生。"},{"en":"If weather reports show heavier rain tomorrow, worse could be on the way for flooded villages.","zh":"如果天氣報告顯示明天有更大雨，受水浸村莊的情況可能會更壞。"},{"en":"Warnings like this help people prepare before the danger grows.","zh":"這類警告幫助人們在危險加劇前作準備。"},{"en":"This phrase expresses a worrying future possibility.","zh":"這個短語表達令人擔心的未來可能性。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":1},{"front":"traditionally","meaning":"傳統上","examples":[{"en":"Traditionally, river engineers have tried to remove floodwater as quickly as possible.","zh":"傳統上，河道工程師一直嘗試盡快排走洪水。"},{"en":"Traditionally means according to old or long-established practice.","zh":"traditionally 指根據舊有或長期建立的做法。"},{"en":"Traditionally, schools used paper notices before email became common.","zh":"傳統上，學校在電郵普及前使用紙本通告。"},{"en":"Traditional methods may continue because people trust what has been used for years.","zh":"傳統方法可能繼續存在，因為人們信任多年來使用的做法。"},{"en":"This word often introduces an old way before a newer approach is explained.","zh":"這個詞常在解釋新方法前引入舊方式。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":2},{"front":"river engineers","meaning":"河道工程師","examples":[{"en":"River engineers once believed that rivers should carry water to the sea as fast as possible.","zh":"河道工程師曾經相信河流應該盡快把水帶到大海。"},{"en":"River engineers are specialists who design, manage, or modify rivers and flood defences.","zh":"river engineers 指設計、管理或改造河流和防洪設施的專家。"},{"en":"River engineers may build banks, channels, and drainage systems to protect towns.","zh":"河道工程師可能興建河岸、水道和排水系統來保護城鎮。"},{"en":"Their decisions can affect flood risk upstream and downstream.","zh":"他們的決定可以影響上游和下游的水災風險。"},{"en":"This phrase refers to engineers working with rivers and water flow.","zh":"這個短語指處理河流和水流的工程師。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":2},{"front":"go for Plan A","meaning":"採用甲方案；選擇傳統方案","examples":[{"en":"River engineers traditionally went for Plan A and tried to drain water away quickly.","zh":"河道工程師傳統上採用甲方案，嘗試迅速把水排走。"},{"en":"To go for Plan A means to choose the first, usual, or traditional option.","zh":"go for Plan A 指選擇第一個、慣常或傳統方案。"},{"en":"If the school hall is free, teachers may go for Plan A and hold the event indoors.","zh":"如果學校禮堂有空，老師可能採用甲方案，在室內舉辦活動。"},{"en":"Plan A may feel safe because it is familiar, even if it no longer works well.","zh":"甲方案可能因熟悉而令人安心，即使它不再有效。"},{"en":"This phrase describes choosing one approach over alternatives.","zh":"這個短語描述在多個方案中選擇一種方法。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":2},{"front":"get rid of","meaning":"擺脫；排走","examples":[{"en":"The old approach tried to get rid of the water fast.","zh":"舊方法嘗試快速排走水。"},{"en":"To get rid of something means to remove it because it is unwanted or causing problems.","zh":"get rid of something 指因某物不需要或造成問題而把它移走。"},{"en":"A family may get rid of old furniture to make more space at home.","zh":"家庭可能清走舊家具，以騰出更多家居空間。"},{"en":"Getting rid of water too quickly can simply push flooding farther downstream.","zh":"太快排走水可能只是把水災推到更下游。"},{"en":"This phrase focuses on removal, not careful storage or reuse.","zh":"這個短語著重移除，而不是小心儲存或再用。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":2},{"front":"drain it off","meaning":"把……排走","examples":[{"en":"Engineers tried to drain the water off the land and down to the sea.","zh":"工程師嘗試把水從陸地排走，一直排到大海。"},{"en":"To drain something off means to remove liquid by letting it flow away.","zh":"drain something off 指讓液體流走而將其移除。"},{"en":"After washing vegetables, you drain the water off before cooking them.","zh":"洗完蔬菜後，你會先把水排走再烹調。"},{"en":"Draining water off land can dry it, but it may also reduce natural storage.","zh":"把土地上的水排走可以令土地變乾，但也可能減少天然儲水空間。"},{"en":"This phrase describes removing water through flow or channels.","zh":"這個短語描述透過水流或渠道移除水。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":2},{"front":"down to the sea","meaning":"一直流向大海","examples":[{"en":"The water was drained off the land and down to the sea.","zh":"水被從陸地排走，一直流向大海。"},{"en":"Down to the sea means towards the sea, usually following the natural downward flow of water.","zh":"down to the sea 指朝大海方向，通常跟隨水自然向下流動。"},{"en":"Rainwater in mountain streams may rush down to the sea after a storm.","zh":"風暴後，山間溪流水可能急速流向大海。"},{"en":"If water moves too quickly down to the sea, downstream towns may flood.","zh":"如果水太快流向大海，下游城鎮可能水浸。"},{"en":"This phrase describes the direction of water flow.","zh":"這個短語描述水流方向。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":2},{"front":"tall-sided rivers","meaning":"兩岸高築的河道","examples":[{"en":"Engineers created tall-sided rivers to carry floodwater away.","zh":"工程師建造兩岸高築的河道來排走洪水。"},{"en":"Tall-sided rivers are rivers with high built-up banks or walls along the sides.","zh":"tall-sided rivers 指兩側有高築河岸或牆壁的河道。"},{"en":"A city may create tall-sided channels to keep water inside during heavy rain.","zh":"城市可能建造兩岸高築的水道，以在大雨時把水留在河道內。"},{"en":"High river sides can contain water locally, but they may increase pressure downstream.","zh":"高河岸可以在本地控制河水，但可能增加下游壓力。"},{"en":"This phrase describes engineered river channels with raised sides.","zh":"這個短語描述兩側被加高的人工改造河道。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":2},{"front":"re-engineered as","meaning":"被重新改造成","examples":[{"en":"Some rivers were re-engineered as high-performance drains.","zh":"有些河流被重新改造成高效排水道。"},{"en":"To be re-engineered as something means to be redesigned and rebuilt to serve a different purpose.","zh":"be re-engineered as something 指被重新設計和改建，以服務另一目的。"},{"en":"An old factory may be re-engineered as a community centre with classrooms and offices.","zh":"舊工廠可能被重新改造成有課室和辦公室的社區中心。"},{"en":"When a river is re-engineered as a drain, its natural functions may be lost.","zh":"當河流被重新改造成排水道，它的自然功能可能消失。"},{"en":"This phrase describes major redesign for a new role.","zh":"這個短語描述為新角色而進行的重大重新設計。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":2},{"front":"high-performance drains","meaning":"高效排水道","examples":[{"en":"Rivers were treated as high-performance drains rather than natural systems.","zh":"河流被視為高效排水道，而不是自然系統。"},{"en":"High-performance drains are drainage channels designed to move water away very quickly.","zh":"high-performance drains 指設計用來非常快速排走水的排水渠道。"},{"en":"A shopping mall needs high-performance drains if heavy rain often floods the car park.","zh":"如果大雨經常淹浸停車場，商場需要高效排水道。"},{"en":"Fast drains can protect one place while increasing water pressure elsewhere.","zh":"快速排水道可以保護一個地方，同時增加其他地方的水壓。"},{"en":"This phrase criticises treating rivers like machines for removing water.","zh":"這個短語批評把河流當成排水機器。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":2},{"front":"however big they dug city drains","meaning":"無論他們把城市排水渠挖得多大","examples":[{"en":"However big they dug city drains, the floods kept coming back.","zh":"無論他們把城市排水渠挖得多大，水災仍不斷再次出現。"},{"en":"However big they dug city drains means no matter how large the drains were made.","zh":"however big they dug city drains 指無論排水渠被挖得多大。"},{"en":"However big a school makes its noticeboard, poor communication will continue if messages are unclear.","zh":"無論學校把告示板做得多大，如果訊息不清楚，溝通問題仍會存在。"},{"en":"Bigger drains do not always solve flooding if the whole water system is wrong.","zh":"如果整個水系統有問題，更大的排水渠不一定能解決水浸。"},{"en":"This structure stresses that size alone did not solve the problem.","zh":"這個結構強調單靠尺寸並沒有解決問題。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":2},{"front":"however wide and straight","meaning":"無論他們把河道修得多寬、多直","examples":[{"en":"However wide and straight they made the rivers, the floods still returned.","zh":"無論他們把河道修得多寬、多直，水災仍然回來。"},{"en":"However wide and straight means no matter how much they widened and straightened the rivers.","zh":"however wide and straight 指無論他們把河流加寬和拉直到甚麼程度。"},{"en":"However wide a road becomes, traffic may continue if public transport is poor.","zh":"無論道路修得多寬，如果公共交通差，交通擠塞仍可能持續。"},{"en":"Making rivers straighter can speed up water instead of reducing danger.","zh":"把河流拉直可能令水流加快，而不是降低危險。"},{"en":"This phrase shows that a physical improvement did not bring the expected result.","zh":"這個短語顯示實體改善沒有帶來預期結果。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":3},{"front":"however high they built the banks","meaning":"無論他們把河岸築得多高","examples":[{"en":"However high they built the banks, the floods kept coming back.","zh":"無論他們把河岸築得多高，水災仍不斷再次出現。"},{"en":"However high they built the banks means no matter how tall the river banks were made.","zh":"however high they built the banks 指無論河岸被築得多高。"},{"en":"However high a wall is built, water may still enter if there is one weak opening.","zh":"無論牆建得多高，如果有一個薄弱開口，水仍可能進入。"},{"en":"Higher banks may delay floods, but they cannot remove all flood risk.","zh":"更高河岸可能延遲水災，但不能消除所有水災風險。"},{"en":"This phrase shows the limits of building higher defences.","zh":"這個短語顯示築高防線的限制。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":3},{"front":"keep coming back","meaning":"不斷再次出現","examples":[{"en":"The floods kept coming back despite all the engineering work.","zh":"儘管做了所有工程，水災仍不斷再次出現。"},{"en":"To keep coming back means to return again and again.","zh":"keep coming back 指一次又一次地回來。"},{"en":"A leak may keep coming back if the plumber fixes only the surface crack.","zh":"如果水喉匠只修補表面裂縫，漏水問題可能不斷再次出現。"},{"en":"Problems keep coming back when their deeper causes are not addressed.","zh":"當深層原因沒有處理，問題就會不斷再次出現。"},{"en":"This phrase describes repeated recurrence.","zh":"這個短語描述反覆發生。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":3},{"front":"taunt them","meaning":"嘲弄他們；令他們難堪","examples":[{"en":"The repeated floods seemed to taunt the engineers.","zh":"反覆出現的水災似乎在嘲弄工程師。"},{"en":"To taunt someone means to mock them or make their failure feel more humiliating.","zh":"taunt someone 指嘲笑某人，或令其失敗感覺更難堪。"},{"en":"If a computer crashes again after every repair, it may feel as if the machine is taunting the technician.","zh":"如果電腦每次維修後又再當機，感覺就像機器在嘲弄技術員。"},{"en":"Repeated failure can make people feel mocked by the problem itself.","zh":"反覆失敗可以令人感到被問題本身嘲弄。"},{"en":"This phrase gives the floods a human-like mocking quality.","zh":"這個短語把水災寫成人一般帶有嘲笑意味。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":3},{"front":"no wonder","meaning":"難怪","examples":[{"en":"No wonder engineers are now turning to a different plan.","zh":"難怪工程師現在轉向另一個方案。"},{"en":"No wonder means it is not surprising because the reason is clear.","zh":"no wonder 指因原因清楚，所以某事並不令人驚訝。"},{"en":"The room is noisy and crowded; no wonder students cannot focus.","zh":"房間又嘈又擠；難怪學生不能集中。"},{"en":"This phrase connects a situation with an understandable reaction.","zh":"這個短語把某情況與可理解的反應連繫起來。"},{"en":"It is often used when the cause of something seems obvious.","zh":"當某事原因似乎明顯時，常會使用它。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":3},{"front":"turn to Plan B","meaning":"轉向乙方案；改用另一方案","examples":[{"en":"Engineers are turning to Plan B to reduce the power of floodwater.","zh":"工程師正在轉向乙方案，以減低洪水力量。"},{"en":"To turn to Plan B means to stop relying on the first approach and try another one.","zh":"turn to Plan B 指停止依賴第一個方案，改試另一個方法。"},{"en":"If an outdoor school fair is rained off, teachers may turn to Plan B and move it indoors.","zh":"如果戶外學校嘉年華因雨取消，老師可能轉向乙方案，搬到室內。"},{"en":"People turn to Plan B when Plan A fails or becomes too risky.","zh":"當甲方案失敗或變得太高風險，人們會轉向乙方案。"},{"en":"This phrase describes switching to an alternative strategy.","zh":"這個短語描述改用替代策略。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":3},{"front":"sap the water’s destructive strength","meaning":"削弱洪水的破壞力","examples":[{"en":"The new approach tries to sap the water’s destructive strength.","zh":"新方法嘗試削弱洪水的破壞力。"},{"en":"To sap the water’s destructive strength means to weaken the power that makes floodwater damaging.","zh":"sap the water’s destructive strength 指削弱令洪水造成破壞的力量。"},{"en":"Wetlands can sap floodwater’s strength by spreading and slowing the flow.","zh":"濕地可以透過分散和減慢水流來削弱洪水力量。"},{"en":"If water loses speed and force, it is less likely to destroy roads and homes.","zh":"如果水失去速度和力量，就較不可能摧毀道路和房屋。"},{"en":"This phrase describes weakening a danger rather than simply blocking it.","zh":"這個短語描述削弱危險，而不是單純阻擋它。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":3},{"front":"destructive strength","meaning":"破壞力","examples":[{"en":"Flood plains can reduce the destructive strength of floodwater.","zh":"洪泛平原可以減少洪水的破壞力。"},{"en":"Destructive strength is the force that allows something to damage or destroy things.","zh":"destructive strength 指某事物能夠損壞或摧毀東西的力量。"},{"en":"Strong winds have destructive strength when they break windows and tear off roofs.","zh":"強風打破窗戶並掀起屋頂時，就具有破壞力。"},{"en":"Reducing destructive strength can protect people even if the danger is not completely removed.","zh":"減低破壞力即使不能完全消除危險，也可以保護人們。"},{"en":"This phrase focuses on damaging power.","zh":"這個短語著重造成損害的力量。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":3},{"front":"disperse something into","meaning":"把……分散到","examples":[{"en":"Engineers can disperse floodwater into fields, lakes, flood plains and aquifers.","zh":"工程師可以把洪水分散到農田、湖泊、洪泛平原和含水層。"},{"en":"To disperse something into places means to spread it across several areas instead of keeping it concentrated.","zh":"disperse something into places 指把某物分散到幾個地方，而不是集中在一處。"},{"en":"A teacher may disperse students into small groups so one corner of the room is not too crowded.","zh":"老師可能把學生分散到小組中，避免課室一角太擠。"},{"en":"Dispersing floodwater reduces pressure in one narrow channel.","zh":"分散洪水可以減少狹窄河道中的壓力。"},{"en":"This phrase describes spreading something out to reduce concentration or force.","zh":"這個短語描述把某物分散，以降低集中度或力量。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":3},{"front":"forgotten lakes","meaning":"被遺忘的湖泊","examples":[{"en":"Floodwater can be dispersed into forgotten lakes.","zh":"洪水可以被分散到被遺忘的湖泊。"},{"en":"Forgotten lakes are old or neglected bodies of water that people may no longer think about or use.","zh":"forgotten lakes 指古老或被忽視、人們可能不再想到或使用的水體。"},{"en":"A village may rediscover forgotten lakes when planning new flood storage areas.","zh":"村莊規劃新蓄洪區時，可能重新發現被遺忘的湖泊。"},{"en":"Restoring old lakes can give floodwater somewhere to go during heavy rain.","zh":"修復舊湖泊可以在大雨期間給洪水去處。"},{"en":"This phrase suggests natural water spaces that have been ignored.","zh":"這個短語表示已被忽略的天然水域。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":3},{"front":"flood plains","meaning":"洪泛平原；河漫灘","examples":[{"en":"Flood plains give rivers space to spread out naturally.","zh":"洪泛平原給河流自然擴散的空間。"},{"en":"Flood plains are low flat areas beside rivers that can naturally hold floodwater.","zh":"flood plains 指河流旁邊低平、可自然容納洪水的地區。"},{"en":"Farmers may use flood plains for grazing when the land is dry.","zh":"當土地乾燥時，農民可能利用洪泛平原放牧。"},{"en":"If flood plains are built over, floodwater has fewer safe places to spread.","zh":"如果洪泛平原被建築物佔用，洪水就有較少安全地方擴散。"},{"en":"This phrase is central to natural flood management.","zh":"這個短語是自然防洪管理的核心概念。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":4},{"front":"aquifers","meaning":"含水層","examples":[{"en":"Aquifers can store water underground.","zh":"含水層可以在地下儲存水。"},{"en":"Aquifers are underground layers of rock or soil that hold water.","zh":"aquifers 指能儲水的地下岩層或土壤層。"},{"en":"A town may pump drinking water from an aquifer during dry months.","zh":"城鎮可能在乾旱月份從含水層抽取飲用水。"},{"en":"If rainwater is allowed to soak down, it can recharge aquifers.","zh":"如果雨水被容許滲入地下，就可以補充含水層。"},{"en":"This word refers to underground water storage, not a surface lake.","zh":"這個詞指地下儲水，而不是地面湖泊。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":4},{"front":"back in the days when","meaning":"在以前……的時候","examples":[{"en":"Back in the days when rivers followed natural courses, floodwater moved more slowly.","zh":"在以前河流沿自然路線流動的時候，洪水流動較慢。"},{"en":"Back in the days when means in an earlier time when a different situation existed.","zh":"back in the days when 指在較早時候，當另一種情況存在時。"},{"en":"Back in the days when students used only paper dictionaries, looking up words took longer.","zh":"在以前學生只使用紙本字典的時候，查字需要更長時間。"},{"en":"This phrase compares the past with the present.","zh":"這個短語把過去與現在作比較。"},{"en":"It often introduces a nostalgic or historical explanation.","zh":"它常引入懷舊或歷史性解釋。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":4},{"front":"take a tortuous path","meaning":"走蜿蜒曲折的路線","examples":[{"en":"Rivers once took a more tortuous path to the sea.","zh":"河流曾經走一條更蜿蜒曲折的路線流向大海。"},{"en":"To take a tortuous path means to follow a winding, twisting route rather than a straight one.","zh":"take a tortuous path 指沿着彎曲、扭轉的路線，而不是直線。"},{"en":"An old village road may take a tortuous path around hills and farms.","zh":"舊村道可能繞過山丘和農田，走蜿蜒曲折的路線。"},{"en":"A winding river slows water because it takes longer to reach the sea.","zh":"蜿蜒河流會減慢水流，因為水需要更長時間到達大海。"},{"en":"This phrase describes a curved and indirect route.","zh":"這個短語描述彎曲而間接的路線。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":4},{"front":"lose impetus and volume","meaning":"失去衝力和水量","examples":[{"en":"Floodwater lost impetus and volume as it spread across the landscape.","zh":"當洪水在地貌中擴散，它失去衝力和水量。"},{"en":"To lose impetus and volume means to lose force, speed, and amount.","zh":"lose impetus and volume 指失去力量、速度和水量。"},{"en":"A crowd leaving through several exits loses impetus because people are no longer packed together.","zh":"人群透過多個出口離開時會失去衝力，因為人不再擠在一起。"},{"en":"When water spreads over fields, it slows down and becomes less concentrated.","zh":"當水流擴散到田野上，它會減慢並變得不那麼集中。"},{"en":"This phrase describes water becoming weaker and less dangerous.","zh":"這個短語描述水變弱和較不危險。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":4},{"front":"meander across","meaning":"蜿蜒流經","examples":[{"en":"Floodwater once meandered across flood plains.","zh":"洪水曾經蜿蜒流經洪泛平原。"},{"en":"To meander across a place means to move slowly in a winding route across it.","zh":"meander across a place 指以彎曲路線慢慢穿過某地。"},{"en":"A path may meander across a park instead of going straight to the gate.","zh":"小路可能蜿蜒穿過公園，而不是直達大門。"},{"en":"Meandering water loses speed because it does not rush in a direct line.","zh":"蜿蜒流動的水會失去速度，因為它不是直線急流。"},{"en":"This phrase describes slow, winding movement across land.","zh":"這個短語描述穿過土地的緩慢曲折移動。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":4},{"front":"idle through","meaning":"緩慢流過","examples":[{"en":"Water idled through wetlands before reaching the sea.","zh":"水在到達大海前緩慢流過濕地。"},{"en":"To idle through a place means to move slowly and gently through it.","zh":"idle through a place 指慢慢而輕柔地穿過某地。"},{"en":"Shoppers may idle through a market on a quiet Sunday morning.","zh":"購物者可能在寧靜的星期日早上慢慢逛過街市。"},{"en":"When water idles through wetlands, plants and soil can slow and absorb it.","zh":"當水緩慢流過濕地，植物和土壤可以減慢並吸收它。"},{"en":"This phrase gives a sense of slow, unhurried movement.","zh":"這個短語帶有緩慢、不急促的感覺。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":4},{"front":"wetlands","meaning":"濕地","examples":[{"en":"Wetlands help slow down and absorb floodwater.","zh":"濕地幫助減慢並吸收洪水。"},{"en":"Wetlands are areas of land that are covered with water or have very wet soil for much of the time.","zh":"wetlands 指長時間被水覆蓋或土壤非常潮濕的土地。"},{"en":"Marshes and swamps are types of wetlands.","zh":"沼澤和濕沼都是濕地的種類。"},{"en":"Wetlands can reduce floods because they store water like a natural sponge.","zh":"濕地可以減少水災，因為它們像天然海綿一樣儲水。"},{"en":"This word refers to natural water-rich land, not ordinary dry fields.","zh":"這個詞指天然含水量高的土地，而不是普通乾田。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":4},{"front":"inland deltas","meaning":"內陸三角洲","examples":[{"en":"Floodwater used to pass through wetlands and inland deltas.","zh":"洪水過去會流經濕地和內陸三角洲。"},{"en":"Inland deltas are river areas inside the land where water spreads into channels and wetlands.","zh":"inland deltas 指位於內陸、河水分散成多條水道和濕地的河流區域。"},{"en":"An inland delta can slow water before it reaches a larger river or sea.","zh":"內陸三角洲可以在水到達大河或大海前減慢水流。"},{"en":"Such areas can store floodwater because water spreads out instead of rushing forward.","zh":"這類地區可以儲存洪水，因為水會擴散，而不是向前急流。"},{"en":"This phrase describes a delta-like system away from the coast.","zh":"這個短語描述遠離海岸的三角洲式系統。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":4},{"front":"an unimpeded journey","meaning":"暢通無阻的流動路線","examples":[{"en":"Modern rivers often give water an unimpeded journey to the sea.","zh":"現代河流常給水一條暢通無阻的流動路線直達大海。"},{"en":"An unimpeded journey is a journey with no obstacles or delays.","zh":"unimpeded journey 指沒有障礙或延誤的旅程。"},{"en":"A cyclist has an unimpeded journey when the road is clear and every traffic light is green.","zh":"當道路暢通且每個交通燈都是綠燈，騎單車者就有暢通無阻的旅程。"},{"en":"If floodwater has an unimpeded journey, it may reach downstream towns too quickly.","zh":"如果洪水有暢通無阻的路線，它可能太快到達下游城鎮。"},{"en":"This phrase describes smooth movement that can sometimes be dangerous.","zh":"這個短語描述順暢移動，但有時這反而危險。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":4},{"front":"when it rains in the uplands","meaning":"當高地降雨時","examples":[{"en":"When it rains in the uplands, water can rush down all at once.","zh":"當高地降雨時，水可能一下子湧下來。"},{"en":"When it rains in the uplands means when rain falls in higher land or hill areas.","zh":"when it rains in the uplands 指雨落在較高地勢或山丘地區時。"},{"en":"When it rains in the uplands, streams may rise before lowland towns see any rain.","zh":"當高地降雨時，低地城鎮還未下雨，溪流水位可能已上升。"},{"en":"Rain in high areas can quickly become floodwater downstream.","zh":"高地降雨可以迅速在下游變成洪水。"},{"en":"This phrase links upland rainfall with later flood risk.","zh":"這個短語把高地降雨與之後的水災風險連繫起來。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":5},{"front":"come down all at once","meaning":"一下子湧下來","examples":[{"en":"The water comes down all at once after heavy rain in the uplands.","zh":"高地大雨後，水一下子湧下來。"},{"en":"To come down all at once means to arrive suddenly in a large amount.","zh":"come down all at once 指突然大量到達。"},{"en":"If many students leave school at the same time, traffic may come down all at once on one road.","zh":"如果許多學生同時放學，交通可能一下子湧到同一條路上。"},{"en":"Water arriving all at once is harder to control than water arriving slowly.","zh":"一下子到達的水比慢慢到達的水更難控制。"},{"en":"This phrase describes sudden concentration of flow or pressure.","zh":"這個短語描述流量或壓力突然集中。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":5},{"front":"close off flood plains","meaning":"封閉洪泛平原","examples":[{"en":"When we close off flood plains, rivers become more dangerous downstream.","zh":"當我們封閉洪泛平原，河流在下游會變得更危險。"},{"en":"To close off flood plains means to block rivers from spreading naturally onto nearby low land.","zh":"close off flood plains 指阻止河水自然擴散到附近低地。"},{"en":"Building houses and walls on a flood plain can close it off from the river.","zh":"在洪泛平原上建屋和築牆，可能把它與河流隔絕。"},{"en":"Closed flood plains reduce natural water storage and can raise flood levels elsewhere.","zh":"被封閉的洪泛平原會減少天然儲水空間，並可能提高其他地方的洪水水位。"},{"en":"This phrase describes cutting off a river’s natural overflow space.","zh":"這個短語描述切斷河流的自然溢流空間。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":5},{"front":"farther downstream","meaning":"在更下游的地方","examples":[{"en":"The river’s flow becomes more violent farther downstream.","zh":"河流流量在更下游的地方變得更猛烈。"},{"en":"Farther downstream means further along the river in the direction the water flows.","zh":"farther downstream 指沿河水流動方向更遠的下游位置。"},{"en":"A factory upstream may affect villages farther downstream if waste enters the river.","zh":"如果上游工廠把廢物排入河中，可能影響更下游的村莊。"},{"en":"Flood decisions in one place can create problems farther downstream.","zh":"一地的防洪決定可以在更下游的地方造成問題。"},{"en":"This phrase gives a location lower along a river system.","zh":"這個短語給出河流系統中較下游的位置。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":5},{"front":"violent and uncontrollable","meaning":"猛烈且難以控制","examples":[{"en":"The river’s flow can become violent and uncontrollable.","zh":"河流流勢可能變得猛烈且難以控制。"},{"en":"Violent and uncontrollable means powerful, dangerous, and difficult to manage.","zh":"violent and uncontrollable 指力量強大、危險，而且難以管理。"},{"en":"A crowd can become violent and uncontrollable if people panic in a narrow exit.","zh":"如果人群在狹窄出口恐慌，可能變得猛烈且難以控制。"},{"en":"Water becomes harder to control when it is fast, deep, and concentrated.","zh":"當水流快速、深且集中，就更難控制。"},{"en":"This phrase describes a situation that has moved beyond easy management.","zh":"這個短語描述已超出容易管理範圍的情況。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":5},{"front":"dykes","meaning":"堤壩；防洪堤","examples":[{"en":"Dykes can fail if one weak section gives way.","zh":"如果一個薄弱部分崩塌，防洪堤可能失效。"},{"en":"Dykes are raised barriers built to stop water from flooding land.","zh":"dykes 指為阻止水淹沒土地而建的高起屏障。"},{"en":"Coastal villages may rely on dykes to keep seawater away during storms.","zh":"沿海村莊可能依靠防洪堤在風暴期間擋住海水。"},{"en":"If a dyke breaks, water can rush through the gap and flood nearby areas.","zh":"如果防洪堤破裂，水可以從缺口湧入並淹沒附近地區。"},{"en":"This word refers to flood barriers, not ordinary walls.","zh":"這個詞指防洪屏障，而不是普通牆壁。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":5},{"front":"only as good as their weakest link","meaning":"成敗取決於最薄弱的一環","examples":[{"en":"Dykes are only as good as their weakest link.","zh":"防洪堤成敗取決於最薄弱的一環。"},{"en":"Only as good as their weakest link means a whole system can fail because of its weakest part.","zh":"only as good as their weakest link 指整個系統可能因最弱部分而失敗。"},{"en":"A group project is only as good as its weakest link if one member does not finish their work.","zh":"如果一名成員沒有完成工作，小組項目的成敗就取決於最薄弱的一環。"},{"en":"Flood defences can fail even if most sections are strong but one section is weak.","zh":"即使大部分防洪設施很堅固，只要一段薄弱也可能失效。"},{"en":"This phrase warns that small weaknesses can ruin a large system.","zh":"這個短語提醒小弱點可以毀掉大型系統。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":5},{"front":"the weakest link","meaning":"最薄弱的一環","examples":[{"en":"The water will find the weakest link in a dyke.","zh":"水會找到防洪堤中最薄弱的一環。"},{"en":"The weakest link is the weakest part of a system, group, or defence.","zh":"weakest link 指系統、群體或防線中最弱的部分。"},{"en":"In a school security system, an unlocked side door may be the weakest link.","zh":"在學校保安系統中，沒鎖的側門可能是最薄弱的一環。"},{"en":"The weakest link matters because pressure often concentrates there.","zh":"最薄弱的一環很重要，因為壓力常集中在那裡。"},{"en":"This phrase identifies the part most likely to fail.","zh":"這個短語指出最可能失效的部分。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":5},{"front":"unerringly find it","meaning":"準確無誤地找到","examples":[{"en":"Floodwater will unerringly find the weakest part of the defence.","zh":"洪水會準確無誤地找到防線中最薄弱的部分。"},{"en":"To unerringly find something means to find it accurately and without missing it.","zh":"unerringly find something 指準確且毫不失誤地找到某物。"},{"en":"A good editor may unerringly find the one weak sentence in an essay.","zh":"好編輯可能準確無誤地找到文章中唯一薄弱句子。"},{"en":"Water follows pressure and gravity, so it often finds small weaknesses quickly.","zh":"水跟隨壓力和重力流動，因此常很快找到小弱點。"},{"en":"This phrase suggests almost perfect accuracy.","zh":"這個短語表示幾乎完美的準確性。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":5},{"front":"complex hydrology","meaning":"複雜的水文系統","examples":[{"en":"Engineers tried to simplify the complex hydrology of rivers.","zh":"工程師嘗試簡化河流複雜的水文系統。"},{"en":"Complex hydrology means the complicated movement, storage, and behaviour of water in an area.","zh":"complex hydrology 指某地區中水的流動、儲存和行為的複雜情況。"},{"en":"A city’s complex hydrology includes rain, drains, rivers, soil, and underground water.","zh":"城市複雜的水文系統包括雨水、排水渠、河流、土壤和地下水。"},{"en":"If hydrology is oversimplified, flood-control plans may fail.","zh":"如果水文系統被過度簡化，防洪計劃可能失敗。"},{"en":"This phrase describes water systems that interact in many ways.","zh":"這個短語描述以多種方式互相影響的水系統。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":5},{"front":"the simple mechanics of","meaning":"……的簡單機械原理","examples":[{"en":"They tried to turn river systems into the simple mechanics of a water pipe.","zh":"他們嘗試把河流系統變成水管的簡單機械原理。"},{"en":"The simple mechanics of something means the basic physical way it works.","zh":"simple mechanics of something 指某事物運作的基本物理方式。"},{"en":"A teacher may explain the simple mechanics of a bicycle by showing pedals, chain, and wheels.","zh":"老師可能透過展示腳踏、鏈條和車輪來解釋單車的簡單機械原理。"},{"en":"Treating a river like a simple machine can ignore ecology, soil, and flood plains.","zh":"把河流當成簡單機器，可能忽視生態、土壤和洪泛平原。"},{"en":"This phrase reduces a complex system to basic physical operation.","zh":"這個短語把複雜系統簡化為基本物理運作。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":6},{"front":"a water pipe","meaning":"水管","examples":[{"en":"A river should not be treated like a water pipe.","zh":"河流不應被當成水管。"},{"en":"A water pipe is a tube that carries water from one place to another.","zh":"water pipe 指把水從一處帶到另一處的管道。"},{"en":"A broken water pipe can flood a kitchen if the main valve is not turned off.","zh":"如果不關總掣，破裂水管可以淹浸廚房。"},{"en":"Pipes are designed for controlled flow, but rivers are part of wider natural systems.","zh":"水管被設計用於受控水流，但河流是更大自然系統的一部分。"},{"en":"This phrase is used as a contrast with natural rivers.","zh":"這個短語用來與天然河流作對比。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":6},{"front":"create danger where they promised safety","meaning":"在承諾安全之處製造危險","examples":[{"en":"Engineers sometimes created danger where they promised safety.","zh":"工程師有時在承諾安全之處製造危險。"},{"en":"To create danger where safety was promised means to make a situation riskier while claiming to protect people.","zh":"create danger where safety was promised 指一邊聲稱保護人們，一邊令情況更危險。"},{"en":"A poorly designed road barrier may create danger where it promised safety.","zh":"設計差劣的道路護欄可能在承諾安全之處製造危險。"},{"en":"Bad solutions can increase the very risk they were meant to reduce.","zh":"差劣解決方案可以增加它本應減低的風險。"},{"en":"This phrase strongly criticises failed protection measures.","zh":"這個短語強烈批評失敗的保護措施。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":6},{"front":"intensify the floods","meaning":"加劇水災","examples":[{"en":"Some flood-control projects intensified the floods they meant to end.","zh":"有些防洪工程加劇了它們本意要終結的水災。"},{"en":"To intensify the floods means to make floods stronger, higher, or more damaging.","zh":"intensify the floods 指令水災變得更強、更高或更具破壞性。"},{"en":"A blocked drain can intensify flooding by stopping rainwater from escaping.","zh":"堵塞排水渠可以因阻止雨水排走而加劇水浸。"},{"en":"If floodwater is forced into a narrow channel, its speed and power may increase.","zh":"如果洪水被迫進入狹窄渠道，其速度和力量可能增加。"},{"en":"This phrase describes a bad result of a control measure.","zh":"這個短語描述控制措施造成的壞結果。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":6},{"front":"mean to end something","meaning":"本意是要終結……","examples":[{"en":"The projects intensified the floods they meant to end.","zh":"這些工程加劇了它們本意要終結的水災。"},{"en":"To mean to end something means to intend to stop it.","zh":"mean to end something 指意圖阻止或終結某事。"},{"en":"A new homework policy may mean to end stress but create more pressure if it is badly designed.","zh":"新功課政策本意是要終結壓力，但如果設計差劣，可能製造更多壓力。"},{"en":"Good intentions do not guarantee good results.","zh":"好意圖不保證好結果。"},{"en":"This phrase contrasts intended purpose with actual outcome.","zh":"這個短語把原本目的與實際結果作對比。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":6},{"front":"the Rhine","meaning":"萊茵河","examples":[{"en":"The Rhine is described as Europe’s most engineered river.","zh":"萊茵河被描述為歐洲人工改造程度最高的河流。"},{"en":"The Rhine is a major European river flowing through or along several countries.","zh":"Rhine 是一條流經或沿着幾個國家流動的重要歐洲河流。"},{"en":"Cities near the Rhine depend on the river for transport, trade, and water management.","zh":"萊茵河附近城市依賴它進行運輸、貿易和水管理。"},{"en":"Changes to a major river like the Rhine can affect many communities downstream.","zh":"對萊茵河這類大河的改變，可以影響下游許多社區。"},{"en":"This phrase names a specific important European river.","zh":"這個短語命名一條具體重要的歐洲河流。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":6},{"front":"Europe’s most engineered river","meaning":"歐洲人工改造程度最高的河流","examples":[{"en":"The Rhine is Europe’s most engineered river.","zh":"萊茵河是歐洲人工改造程度最高的河流。"},{"en":"Europe’s most engineered river means the European river most heavily altered by human engineering.","zh":"Europe’s most engineered river 指歐洲被人類工程改造得最嚴重的河流。"},{"en":"A heavily engineered river may have straight channels, high banks, and controlled flow.","zh":"高度人工改造的河流可能有筆直河道、高河岸和受控水流。"},{"en":"Too much engineering can remove natural storage and make floods worse.","zh":"過多工程可能移除天然儲水空間，令水災更嚴重。"},{"en":"This phrase highlights extreme human modification.","zh":"這個短語突出極端的人為改造。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":6},{"front":"for two centuries","meaning":"長達兩個世紀","examples":[{"en":"German engineers changed the Rhine for two centuries.","zh":"德國工程師長達兩個世紀改造萊茵河。"},{"en":"For two centuries means for a period of about two hundred years.","zh":"for two centuries 指持續約二百年。"},{"en":"A university may keep the same ceremony for two centuries if tradition is strong.","zh":"如果傳統強烈，大學可能長達兩個世紀保留同一典禮。"},{"en":"Changes made over two centuries can deeply reshape a landscape.","zh":"長達兩個世紀的改變可以深刻重塑地貌。"},{"en":"This phrase gives a very long time span.","zh":"這個短語給出很長的時間跨度。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":6},{"front":"erase backwaters","meaning":"清除回水區","examples":[{"en":"Engineers erased the Rhine’s backwaters over many decades.","zh":"工程師在許多十年間清除了萊茵河的回水區。"},{"en":"To erase backwaters means to remove slow side waters connected with a river.","zh":"erase backwaters 指移除與河流相連的緩慢側水區。"},{"en":"A city may erase old ponds when it fills them to build roads.","zh":"城市填平舊池塘建路時，可能清除舊水體。"},{"en":"Removing backwaters can make the main river faster and reduce natural storage.","zh":"移除回水區可以令主河道更快，並減少天然儲水。"},{"en":"This phrase describes eliminating quiet water areas from a river system.","zh":"這個短語描述從河流系統中消除靜水區。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":6},{"front":"backwaters","meaning":"回水區；支流靜水區","examples":[{"en":"Backwaters can slow river flow and store floodwater.","zh":"回水區可以減慢河流並儲存洪水。"},{"en":"Backwaters are quiet side areas of a river where water moves slowly or stands still.","zh":"backwaters 指河流旁邊水流緩慢或靜止的安靜水域。"},{"en":"Fish and birds often use backwaters because the water is calmer.","zh":"魚類和鳥類常利用回水區，因為水較平靜。"},{"en":"Backwaters can reduce floods by holding water away from the main channel.","zh":"回水區可以透過把水留在主河道之外來減少水災。"},{"en":"This word refers to slow side waters, not the main fast flow.","zh":"這個詞指緩慢側水區，而不是主要急流。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":6},{"front":"cut it off from","meaning":"使……與……隔絕","examples":[{"en":"Engineers cut the Rhine off from its flood plain.","zh":"工程師使萊茵河與其洪泛平原隔絕。"},{"en":"To cut something off from something else means to separate it from what it was connected to.","zh":"cut something off from something else 指把某物與原本相連的東西分開。"},{"en":"A road closure can cut a village off from the nearest hospital.","zh":"封路可以令村莊與最近醫院隔絕。"},{"en":"Cutting a river off from its flood plain prevents natural overflow.","zh":"使河流與洪泛平原隔絕，會阻止自然溢流。"},{"en":"This phrase describes separation that can cause problems.","zh":"這個短語描述可能造成問題的分隔。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":7},{"front":"original length","meaning":"原本長度","examples":[{"en":"The Rhine has lost 7 percent of its original length.","zh":"萊茵河已失去其原本長度的百分之七。"},{"en":"Original length means the length something had before it was changed.","zh":"original length 指某物在被改變前的長度。"},{"en":"A road may lose part of its original length when engineers build a shortcut.","zh":"當工程師建造捷徑，道路可能失去部分原本長度。"},{"en":"Shortening a river can increase the speed at which water travels.","zh":"縮短河流可以增加水流速度。"},{"en":"This phrase compares the present size with the old size.","zh":"這個短語把現在尺寸與舊尺寸作比較。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":7},{"front":"run up to a third faster","meaning":"流速最多快了三分之一","examples":[{"en":"The river now runs up to a third faster.","zh":"這條河現在流速最多快了三分之一。"},{"en":"To run up to a third faster means to flow as much as one third faster than before.","zh":"run up to a third faster 指流動速度最多比以前快三分之一。"},{"en":"Traffic may move up to a third faster after a new road opens.","zh":"新道路開通後，交通速度可能最多快了三分之一。"},{"en":"Faster flow can mean water reaches downstream areas sooner and with more force.","zh":"更快水流可能代表水更早且以更大力量到達下游。"},{"en":"This phrase gives the maximum amount of speed increase.","zh":"這個短語給出速度增加的最大幅度。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":7},{"front":"rain hard","meaning":"下大雨","examples":[{"en":"When it rains hard in the Alps, several tributaries send water into the main river.","zh":"當阿爾卑斯山下大雨時，幾條支流會把水送入主河道。"},{"en":"To rain hard means to rain heavily and strongly.","zh":"rain hard 指雨勢很大很強。"},{"en":"If it rains hard after school, students may wait indoors until the roads are safer.","zh":"如果放學後下大雨，學生可能留在室內等道路較安全。"},{"en":"Hard rain can quickly fill drains, streams, and rivers.","zh":"大雨可以迅速填滿排水渠、溪流和河流。"},{"en":"This phrase describes intense rainfall, not light rain.","zh":"這個短語描述強降雨，而不是微雨。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":7},{"front":"the Alps","meaning":"阿爾卑斯山","examples":[{"en":"Heavy rain in the Alps can affect the Rhine’s flow.","zh":"阿爾卑斯山的大雨可以影響萊茵河水流。"},{"en":"The Alps are a major mountain range in Europe.","zh":"Alps 是歐洲一條主要山脈。"},{"en":"Snow and rain in the Alps can feed large rivers flowing to lower countries.","zh":"阿爾卑斯山的雪和雨可以補給流向低地國家的大河。"},{"en":"Weather in mountain areas can create flood risk far downstream.","zh":"山區天氣可以在遠下游造成水災風險。"},{"en":"This phrase names an important European mountain region.","zh":"這個短語命名一個重要歐洲山區。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":7},{"front":"peak flows","meaning":"流量高峰","examples":[{"en":"The peak flows from several tributaries now coincide in the main river.","zh":"幾條支流的流量高峰現在會在主河道同時出現。"},{"en":"Peak flows are the highest levels of water flow during a flood or storm.","zh":"peak flows 指水災或風暴期間最高的水流量。"},{"en":"Engineers watch peak flows to predict when a river may overflow.","zh":"工程師會監察流量高峰，以預測河流何時可能氾濫。"},{"en":"If peak flows arrive together, the main river can rise dangerously fast.","zh":"如果流量高峰同時到達，主河道水位可以危險地快速上升。"},{"en":"This phrase refers to maximum river flow, not average flow.","zh":"這個短語指最高河流流量，而不是平均流量。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":7},{"front":"tributaries","meaning":"支流","examples":[{"en":"Several tributaries feed into the main river.","zh":"幾條支流流入主河道。"},{"en":"Tributaries are smaller rivers or streams that flow into a larger river.","zh":"tributaries 指流入較大河流的小河或溪流。"},{"en":"A map of a river system shows tributaries joining the main channel from different directions.","zh":"河流系統地圖會顯示支流從不同方向匯入主河道。"},{"en":"Heavy rain in tributaries can raise the level of the main river.","zh":"支流中的大雨可以提高主河道水位。"},{"en":"This word refers to feeder rivers.","zh":"這個詞指補給主河的河流。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":7},{"front":"coincide in the main river","meaning":"在主河道同時出現","examples":[{"en":"The peak flows from several tributaries coincide in the main river.","zh":"幾條支流的流量高峰在主河道同時出現。"},{"en":"To coincide in the main river means to arrive in the main river at the same time.","zh":"coincide in the main river 指在同一時間到達主河道。"},{"en":"If several school buses arrive together, students may coincide at the entrance and cause crowding.","zh":"如果幾部校巴同時到達，學生可能同時聚集在入口並造成擠迫。"},{"en":"When tributary peaks coincide, flood pressure becomes much greater.","zh":"當支流高峰同時出現，洪水壓力會大得多。"},{"en":"This phrase describes timing that makes water levels combine.","zh":"這個短語描述令水位合併的時間配合。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":7},{"front":"arrive separately","meaning":"分開抵達；先後到達","examples":[{"en":"The peak flows once arrived separately.","zh":"流量高峰曾經是分開抵達的。"},{"en":"To arrive separately means to reach a place at different times rather than together.","zh":"arrive separately 指在不同時間到達某地，而不是一起到達。"},{"en":"If guests arrive separately, the restaurant entrance is less crowded.","zh":"如果客人分開抵達，餐廳入口就較不擠迫。"},{"en":"Flood peaks arriving separately give the main river more time to carry water away.","zh":"洪峰先後到達，可以給主河道更多時間排走水。"},{"en":"This phrase contrasts staggered timing with simultaneous arrival.","zh":"這個短語把錯開時間與同時到達作對比。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":7},{"front":"four-fifths of","meaning":"五分之四的……","examples":[{"en":"Four-fifths of the lower Rhine’s flood plain has been barricaded off.","zh":"萊茵河下游五分之四的洪泛平原已被封堵。"},{"en":"Four-fifths of something means 80 percent of it.","zh":"four-fifths of something 指某事物的百分之八十。"},{"en":"Four-fifths of the class passed the test, so most students understood the topic.","zh":"五分之四的班級學生通過測驗，所以大多數學生理解該主題。"},{"en":"When four-fifths of a flood plain is blocked, very little natural storage remains.","zh":"當五分之四的洪泛平原被堵住，剩下的天然儲水空間就很少。"},{"en":"This phrase expresses a large majority as a fraction.","zh":"這個短語用分數表達大多數。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":7},{"front":"the lower Rhine","meaning":"萊茵河下游","examples":[{"en":"Much of the lower Rhine’s flood plain has been blocked off.","zh":"萊茵河下游大部分洪泛平原已被封堵。"},{"en":"The lower Rhine is the downstream part of the Rhine River.","zh":"lower Rhine 指萊茵河較下游的部分。"},{"en":"Towns along the lower Rhine may face flood risk when water arrives from upstream.","zh":"當水從上游到達，萊茵河下游沿岸城鎮可能面對水災風險。"},{"en":"Downstream areas often suffer from decisions made higher up the river.","zh":"下游地區常承受上游決策造成的後果。"},{"en":"This phrase identifies the lower section of a major river.","zh":"這個短語指出一條大河的下游部分。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":8},{"front":"barricaded off","meaning":"被隔開；被封堵","examples":[{"en":"The lower Rhine’s flood plain has been barricaded off.","zh":"萊茵河下游的洪泛平原已被封堵。"},{"en":"Barricaded off means blocked or separated with barriers.","zh":"barricaded off 指用屏障阻隔或分開。"},{"en":"Police may barricade off a street after a serious accident.","zh":"嚴重意外後，警方可能封鎖街道。"},{"en":"If flood plains are barricaded off, water cannot spread there naturally.","zh":"如果洪泛平原被封堵，水就不能自然擴散到那裡。"},{"en":"This phrase describes physical blocking or separation.","zh":"這個短語描述實體阻隔或分隔。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":8},{"front":"rise ever higher","meaning":"不斷升得更高","examples":[{"en":"The waters rise ever higher when flood plains are blocked.","zh":"當洪泛平原被封堵，水位會不斷升得更高。"},{"en":"To rise ever higher means to continue rising to greater levels.","zh":"rise ever higher 指持續上升到更高水平。"},{"en":"Rent may rise ever higher if housing demand grows but supply stays low.","zh":"如果住屋需求上升但供應低，租金可能不斷升得更高。"},{"en":"When water has nowhere to spread, levels can keep climbing.","zh":"當水沒有地方擴散，水位可以繼續上升。"},{"en":"This phrase suggests an ongoing and worrying increase.","zh":"這個短語表示持續且令人擔心的上升。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":8},{"front":"more frequent flooding","meaning":"更頻繁的水災","examples":[{"en":"The result is more frequent flooding.","zh":"結果是更頻繁的水災。"},{"en":"More frequent flooding means floods happen more often than before.","zh":"more frequent flooding 指水災比以前更常發生。"},{"en":"A neighbourhood may suffer more frequent flooding when old drains are not upgraded.","zh":"如果舊排水渠沒有升級，社區可能遭受更頻繁水浸。"},{"en":"More frequent floods increase repair costs and make residents anxious every rainy season.","zh":"更頻繁水災會增加維修成本，並令居民每個雨季都焦慮。"},{"en":"This phrase focuses on how often floods occur.","zh":"這個短語著重水災發生頻率。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":8},{"front":"do ever-greater damage to","meaning":"對……造成越來越大的破壞","examples":[{"en":"Flooding does ever-greater damage to buildings and roads on the flood plain.","zh":"水災對洪泛平原上的建築物和道路造成越來越大的破壞。"},{"en":"To do ever-greater damage to something means to cause increasing harm over time.","zh":"do ever-greater damage to something 指隨時間造成越來越大的傷害。"},{"en":"Heavy traffic can do ever-greater damage to old roads if repairs are delayed.","zh":"如果維修延誤，繁忙交通可以對舊道路造成越來越大的破壞。"},{"en":"Repeated floods can make each repair more expensive than the last.","zh":"反覆水災可以令每次維修都比上一次更昂貴。"},{"en":"This phrase describes damage that keeps increasing.","zh":"這個短語描述不斷增加的破壞。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":8},{"front":"sit on the flood plain","meaning":"位於洪泛平原上","examples":[{"en":"Homes, offices and roads sit on the flood plain.","zh":"住宅、辦公室和道路位於洪泛平原上。"},{"en":"To sit on the flood plain means to be located on low land that can naturally flood.","zh":"sit on the flood plain 指位於可能自然氾濫的低地上。"},{"en":"A school built on a flood plain may need raised floors and emergency plans.","zh":"建於洪泛平原上的學校可能需要加高地板和應急計劃。"},{"en":"Buildings on flood plains are at risk because rivers may reclaim that space during storms.","zh":"洪泛平原上的建築物有風險，因為河流可能在風暴期間重新佔據該空間。"},{"en":"This phrase describes risky location, not sitting physically like a person.","zh":"這個短語描述有風險的位置，而不是像人一樣坐着。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":8},{"front":"much the same has happened","meaning":"大致相同的情況也發生了","examples":[{"en":"Much the same has happened on the Mississippi.","zh":"大致相同的情況也發生在密西西比河。"},{"en":"Much the same has happened means a very similar situation has occurred elsewhere.","zh":"much the same has happened 指非常相似的情況在其他地方出現。"},{"en":"A city may ban cars in the centre, and much the same has happened in other European cities.","zh":"一個城市可能禁止汽車進入市中心，而大致相同的情況也發生在其他歐洲城市。"},{"en":"This phrase helps compare two cases with similar patterns.","zh":"這個短語幫助比較兩個有相似模式的個案。"},{"en":"It shows that the problem is not isolated.","zh":"它顯示問題並非孤立。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":8},{"front":"the mighty Mississippi","meaning":"浩瀚的密西西比河","examples":[{"en":"Much the same has happened on the mighty Mississippi.","zh":"大致相同的情況也發生在浩瀚的密西西比河。"},{"en":"The mighty Mississippi refers to the Mississippi River as a very large and powerful river.","zh":"mighty Mississippi 指把密西西比河視為非常巨大而有力量的河流。"},{"en":"Writers may call a river “mighty” when it shapes transport, farming, and communities.","zh":"當一條河塑造運輸、農業和社區，作者可能稱它為 mighty。"},{"en":"A mighty river can bring wealth in normal times and danger during floods.","zh":"浩瀚大河在平時可以帶來財富，在水災時也可以帶來危險。"},{"en":"This phrase gives the Mississippi a grand and powerful image.","zh":"這個短語賦予密西西比河宏偉而強大的形象。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":8},{"front":"drain a river catchment","meaning":"排走流域內的水","examples":[{"en":"The Mississippi drains the world’s second-largest river catchment.","zh":"密西西比河排走世界第二大河流集水區內的水。"},{"en":"To drain a river catchment means to collect and carry water away from a whole drainage area.","zh":"drain a river catchment 指收集並帶走整個流域的水。"},{"en":"A main river drains many smaller streams, fields, and towns in its basin.","zh":"主河會排走其流域內許多小溪、農田和城鎮的水。"},{"en":"If a large catchment receives heavy rain, the river draining it may rise quickly.","zh":"如果大型流域下大雨，排走其水的河流可能快速上升。"},{"en":"This phrase describes how a river carries water from a wide area.","zh":"這個短語描述河流如何從廣大地區帶走水。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":8},{"front":"river catchment","meaning":"河流集水區；流域","examples":[{"en":"The Mississippi drains a huge river catchment into the Gulf of Mexico.","zh":"密西西比河把龐大流域的水排入墨西哥灣。"},{"en":"A river catchment is the whole area of land from which water flows into a river.","zh":"river catchment 指水流會流入某條河的整個土地範圍。"},{"en":"Rain falling in a catchment may eventually enter the same main river.","zh":"落在流域內的雨最終可能進入同一條主河。"},{"en":"Managing a river catchment means thinking about forests, farms, towns, and drains together.","zh":"管理河流集水區意味着同時考慮森林、農田、城鎮和排水渠。"},{"en":"This phrase refers to the wider drainage area, not just the river channel.","zh":"這個短語指更廣泛的排水區域，而不只是河道。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":8},{"front":"the Gulf of Mexico","meaning":"墨西哥灣","examples":[{"en":"The Mississippi drains into the Gulf of Mexico.","zh":"密西西比河流入墨西哥灣。"},{"en":"The Gulf of Mexico is a large body of water bordered by the United States, Mexico, and Cuba.","zh":"Gulf of Mexico 是一片由美國、墨西哥和古巴接壤的大型水域。"},{"en":"Rivers carry water, soil, and pollution into the Gulf of Mexico.","zh":"河流把水、泥土和污染物帶入墨西哥灣。"},{"en":"What happens far inland can affect coastal waters where the river ends.","zh":"內陸遠處發生的事可以影響河流終點的沿岸水域。"},{"en":"This phrase names the sea area where the Mississippi reaches the ocean system.","zh":"這個短語命名密西西比河進入海洋系統的海域。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":9},{"front":"the European Union","meaning":"歐洲聯盟","examples":[{"en":"The European Union is trying to improve rain forecasts.","zh":"歐洲聯盟正在嘗試改善降雨預測。"},{"en":"The European Union is a political and economic union of European countries.","zh":"European Union 是由歐洲國家組成的政治和經濟聯盟。"},{"en":"The European Union may fund research that helps countries share weather and flood data.","zh":"歐洲聯盟可能資助研究，幫助各國分享天氣和水災數據。"},{"en":"Cross-border cooperation matters because rivers and storms do not stop at national borders.","zh":"跨境合作很重要，因為河流和風暴不會在國界停止。"},{"en":"This phrase names a regional organisation in Europe.","zh":"這個短語命名一個歐洲地區組織。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":9},{"front":"improve rain forecasts","meaning":"改善降雨預測","examples":[{"en":"The European Union is trying to improve rain forecasts.","zh":"歐洲聯盟正在嘗試改善降雨預測。"},{"en":"To improve rain forecasts means to make predictions about rainfall more accurate and useful.","zh":"improve rain forecasts 指令關於降雨的預測更準確和有用。"},{"en":"Better rain forecasts help farmers decide when to plant or harvest crops.","zh":"更好的降雨預測幫助農民決定何時播種或收割。"},{"en":"Accurate forecasts can give cities more time to prepare pumps, sandbags, and warnings.","zh":"準確預測可以給城市更多時間準備水泵、沙包和警告。"},{"en":"This phrase focuses on better prediction of rainfall.","zh":"這個短語著重更好預測降雨。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":9},{"front":"more accurately model","meaning":"更準確地模擬","examples":[{"en":"Scientists want to more accurately model how intense rains swell rivers.","zh":"科學家希望更準確地模擬強降雨如何令河流水位上漲。"},{"en":"To more accurately model something means to represent or simulate it more correctly.","zh":"more accurately model something 指更正確地呈現或模擬某事。"},{"en":"Transport planners model traffic more accurately when they include buses, pedestrians, and school hours.","zh":"交通規劃者把巴士、行人和上學時間納入時，就能更準確地模擬交通。"},{"en":"Better models can improve decisions before real danger arrives.","zh":"更好的模型可以在真正危險來臨前改善決策。"},{"en":"This phrase describes improving a scientific or planning simulation.","zh":"這個短語描述改善科學或規劃模擬。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":9},{"front":"intense rains","meaning":"強降雨","examples":[{"en":"Intense rains can quickly swell rivers.","zh":"強降雨可以迅速令河流水位上漲。"},{"en":"Intense rains are very heavy rains that fall strongly, often in a short period.","zh":"intense rains 指非常大的雨，通常在短時間內猛烈落下。"},{"en":"Intense rains can flood school playgrounds before drains can clear the water.","zh":"強降雨可以在排水渠排清前淹浸學校操場。"},{"en":"When rain is intense, soil and drains may not absorb water fast enough.","zh":"當降雨強烈，土壤和排水渠可能來不及吸收或排走水。"},{"en":"This phrase describes rainfall that is strong enough to create danger.","zh":"這個短語描述足以造成危險的強雨。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":9},{"front":"swell rivers","meaning":"令河流水位上漲","examples":[{"en":"Intense rains can swell rivers and increase flood risk.","zh":"強降雨可以令河流水位上漲並增加水災風險。"},{"en":"To swell rivers means to make river levels rise and flow become larger.","zh":"swell rivers 指令河流水位上升、流量變大。"},{"en":"Melting snow can swell rivers in spring.","zh":"融雪可以在春天令河流水位上漲。"},{"en":"Swollen rivers may overflow banks and flood nearby roads or homes.","zh":"水位上漲的河流可能漫過河岸並淹浸附近道路或房屋。"},{"en":"This phrase links extra water with rising river levels.","zh":"這個短語把額外水量與河流水位上升連繫起來。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":9},{"front":"help cities prepare","meaning":"幫助城市作好準備","examples":[{"en":"Better forecasts may help cities prepare for flooding.","zh":"更好的預測可能幫助城市為水災作好準備。"},{"en":"To help cities prepare means to give city authorities time or information to get ready.","zh":"help cities prepare 指給城市當局時間或資訊作準備。"},{"en":"A storm warning can help cities prepare by closing roads and checking drains.","zh":"風暴警告可以透過封路和檢查排水渠，幫助城市作好準備。"},{"en":"Preparation reduces panic and can protect people before floods arrive.","zh":"準備可以減少恐慌，並在水災來臨前保護人們。"},{"en":"This phrase focuses on readiness, not prevention by itself.","zh":"這個短語著重準備，而不是本身阻止災害。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":9},{"front":"won’t stop the floods","meaning":"不能阻止水災","examples":[{"en":"Better forecasts may help cities prepare, but they won’t stop the floods.","zh":"更好的預測可能幫助城市作好準備，但不能阻止水災。"},{"en":"Won’t stop the floods means will not prevent floods from happening.","zh":"won’t stop the floods 指不能防止水災發生。"},{"en":"A weather app can warn a family about heavy rain, but it won’t stop the flood outside their house.","zh":"天氣應用程式可以提醒家庭有大雨，但不能阻止屋外水浸。"},{"en":"Prediction helps with response, but it does not remove the physical danger.","zh":"預測有助應對，但不能移除實際危險。"},{"en":"This phrase contrasts preparation with actual prevention.","zh":"這個短語把準備與真正預防作對比。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":9},{"front":"to do that","meaning":"要做到這一點","examples":[{"en":"To do that, hydrologists say we need a new approach.","zh":"要做到這一點，水文學家說我們需要新方法。"},{"en":"To do that means in order to achieve the goal just mentioned.","zh":"to do that 指為了達成剛提到的目標。"},{"en":"A school wants fewer late arrivals; to do that, it may change the bus schedule.","zh":"學校想減少遲到；要做到這一點，可能要改變巴士時間表。"},{"en":"This phrase links a goal with the action needed to reach it.","zh":"這個短語把目標與達成目標所需行動連繫起來。"},{"en":"It helps move from problem to solution.","zh":"它幫助由問題轉向解決方法。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":9},{"front":"hydrologists","meaning":"水文學家","examples":[{"en":"Hydrologists argue that flood control must consider the whole landscape.","zh":"水文學家認為防洪必須考慮整個地貌。"},{"en":"Hydrologists are scientists who study water, including rainfall, rivers, groundwater, and floods.","zh":"hydrologists 指研究水的科學家，包括降雨、河流、地下水和水災。"},{"en":"A hydrologist may advise a city on where floodwater is likely to go.","zh":"水文學家可能建議城市洪水可能流向哪裡。"},{"en":"Their work helps planners understand how water moves through land and cities.","zh":"他們的工作幫助規劃者理解水如何穿過土地和城市。"},{"en":"This word refers to experts in water systems.","zh":"這個詞指水系統專家。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":9},{"front":"a new approach to","meaning":"……的新方法","examples":[{"en":"Hydrologists are calling for a new approach to river engineering.","zh":"水文學家呼籲採用河道工程的新方法。"},{"en":"A new approach to something means a different way of dealing with it.","zh":"new approach to something 指處理某事的不同方法。"},{"en":"A school may need a new approach to homework if students are exhausted every night.","zh":"如果學生每晚都筋疲力盡，學校可能需要功課的新方法。"},{"en":"New approaches often appear when old methods fail repeatedly.","zh":"當舊方法反覆失敗，新方法常會出現。"},{"en":"This phrase introduces a change in method or thinking.","zh":"這個短語引入方法或思維上的改變。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":10},{"front":"not just rivers, but the whole landscape","meaning":"不只是河流，而是整個地貌","examples":[{"en":"The new approach engineers not just rivers, but the whole landscape.","zh":"新方法改造的不只是河流，而是整個地貌。"},{"en":"Not just rivers, but the whole landscape means the solution must consider rivers together with fields, towns, wetlands, soil, and groundwater.","zh":"not just rivers, but the whole landscape 指解決方案必須同時考慮河流、農田、城鎮、濕地、土壤和地下水。"},{"en":"A healthy transport plan considers not just roads, but the whole city.","zh":"健康交通計劃考慮的不只是道路，而是整個城市。"},{"en":"Flooding depends on many connected places, so managing only the river is too narrow.","zh":"水災取決於許多相連地方，所以只管理河流太狹窄。"},{"en":"This phrase expands the focus from one part to the entire system.","zh":"這個短語把焦點由一部分擴展到整個系統。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":10},{"front":"the whole landscape","meaning":"整個地貌；整個環境","examples":[{"en":"Flood management should consider the whole landscape.","zh":"防洪管理應考慮整個地貌。"},{"en":"The whole landscape means the full physical environment, including rivers, land, buildings, soil, and vegetation.","zh":"whole landscape 指完整實體環境，包括河流、土地、建築、土壤和植物。"},{"en":"A city planner must consider the whole landscape before deciding where water should go.","zh":"城市規劃者在決定水應流向哪裡前，必須考慮整個環境。"},{"en":"Looking at the whole landscape can reveal storage areas that a river-only plan misses.","zh":"觀察整個地貌可以揭示只看河流的計劃會錯過的儲水區。"},{"en":"This phrase means the complete surrounding environment.","zh":"這個短語指完整周邊環境。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":10},{"front":"the UK’s Environment Agency","meaning":"英國環境署","examples":[{"en":"The UK’s Environment Agency is working with natural flood-management methods.","zh":"英國環境署正在使用自然防洪管理方法。"},{"en":"The UK’s Environment Agency is a public body responsible for environmental protection and flood-related work in parts of the UK.","zh":"UK’s Environment Agency 是英國部分地區負責環境保護和防洪相關工作的公共機構。"},{"en":"The agency may warn communities before rivers overflow.","zh":"該署可能在河流氾濫前警告社區。"},{"en":"Public agencies can change flood policy by funding wetlands and river restoration.","zh":"公共機構可以透過資助濕地和河流復修來改變防洪政策。"},{"en":"This phrase names a specific environmental authority.","zh":"這個短語命名一個特定環境管理機構。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":10},{"front":"be granted an extra","meaning":"獲額外撥款","examples":[{"en":"The agency was granted an extra £150 million a year after serious floods.","zh":"嚴重水災後，該署每年獲額外撥款一億五千萬英鎊。"},{"en":"To be granted an extra amount means to receive additional money or resources officially.","zh":"be granted an extra amount 指正式獲得額外金錢或資源。"},{"en":"A school may be granted extra funding after student numbers rise sharply.","zh":"學生人數急升後，學校可能獲額外撥款。"},{"en":"Extra funding can allow an organisation to start projects it could not afford before.","zh":"額外資金可以讓組織開展之前負擔不起的項目。"},{"en":"This phrase describes official additional support.","zh":"這個短語描述正式額外支援。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":10},{"front":"in the wake of","meaning":"在……之後；由於……的影響","examples":[{"en":"The agency received extra funding in the wake of the 2000 floods.","zh":"在 2000 年水災之後，該署獲得額外資金。"},{"en":"In the wake of means after an event, especially when it causes consequences.","zh":"in the wake of 指在某事件之後，尤其是該事件造成後果時。"},{"en":"In the wake of a school fire, safety inspections became much stricter.","zh":"學校火警後，安全檢查變得嚴格得多。"},{"en":"Serious events often lead to new policies in their wake.","zh":"嚴重事件之後常會帶來新政策。"},{"en":"This phrase links an event with what happens afterwards.","zh":"這個短語把事件與之後發生的事情連繫起來。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":10},{"front":"put it like this","meaning":"這樣表達；這樣說","examples":[{"en":"The Environment Agency puts it like this: the focus is now on nature.","zh":"英國環境署這樣說：重點現在放在自然。"},{"en":"To put it like this means to express an idea in a particular clear way.","zh":"put it like this 指以某種清楚方式表達一個想法。"},{"en":"A teacher may put it like this: grammar is a tool, not a punishment.","zh":"老師可能這樣說：文法是工具，不是懲罰。"},{"en":"This phrase introduces a simple explanation of a bigger idea.","zh":"這個短語引入對較大概念的簡單解釋。"},{"en":"It helps make a point easier to understand.","zh":"它幫助令重點更易理解。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":10},{"front":"the focus is now on","meaning":"重點現在放在","examples":[{"en":"The focus is now on working with the forces of nature.","zh":"重點現在放在順應自然力量。"},{"en":"The focus is now on something means attention and effort are currently directed toward it.","zh":"focus is now on something 指目前的注意力和努力集中於某事。"},{"en":"After repeated exam failures, the focus is now on basic reading skills.","zh":"在反覆考試失敗後，重點現在放在基本閱讀技能。"},{"en":"Changing the focus can change what projects receive money and support.","zh":"改變重點可以改變哪些項目獲得金錢和支援。"},{"en":"This phrase shows a shift in priority.","zh":"這個短語顯示優先事項轉變。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":10},{"front":"work with the forces of nature","meaning":"順應自然力量","examples":[{"en":"Flood engineers are learning to work with the forces of nature.","zh":"防洪工程師正在學習順應自然力量。"},{"en":"To work with the forces of nature means to use natural processes instead of fighting them completely.","zh":"work with the forces of nature 指利用自然過程，而不是完全與其對抗。"},{"en":"Farmers work with nature when they plant trees to reduce soil loss instead of only building walls.","zh":"農民種樹減少泥土流失，而不是只築牆時，就是順應自然。"},{"en":"Working with nature can reduce costs and create healthier landscapes.","zh":"順應自然可以降低成本並創造更健康地貌。"},{"en":"This phrase describes cooperation with natural systems.","zh":"這個短語描述與自然系統合作。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":10},{"front":"towering concrete walls","meaning":"高聳的混凝土牆","examples":[{"en":"Towering concrete walls are no longer the preferred solution.","zh":"高聳的混凝土牆不再是首選解決方案。"},{"en":"Towering concrete walls are very high walls made of concrete.","zh":"towering concrete walls 指用混凝土建成的非常高的牆。"},{"en":"A city may build towering concrete walls beside a river to stop flooding.","zh":"城市可能在河邊建造高聳的混凝土牆以阻止水浸。"},{"en":"High concrete walls can protect one area but make rivers feel trapped and unnatural.","zh":"高混凝土牆可以保護一個地區，但會令河流感覺被困住且不自然。"},{"en":"This phrase suggests a hard engineering solution.","zh":"這個短語表示硬性工程解決方案。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":10},{"front":"are out","meaning":"已不再流行；不再受重視","examples":[{"en":"Towering concrete walls are out, and new wetlands are in.","zh":"高聳的混凝土牆已不再受重視，而新濕地正受重視。"},{"en":"Are out means are no longer fashionable, popular, or preferred.","zh":"are out 指不再流行、受歡迎或被偏好。"},{"en":"In some offices, strict dress codes are out and flexible clothing rules are in.","zh":"在有些辦公室，嚴格衣着規定已不再流行，彈性衣着規則正受重視。"},{"en":"When an old solution fails, it may fall out of favour.","zh":"當舊方案失敗，它可能失去支持。"},{"en":"This phrase describes something losing status or popularity.","zh":"這個短語描述某事失去地位或受歡迎程度。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":11},{"front":"are in","meaning":"正受重視；正流行","examples":[{"en":"New wetlands are in as part of modern flood management.","zh":"新濕地作為現代防洪管理的一部分正受重視。"},{"en":"Are in means are currently fashionable, accepted, or preferred.","zh":"are in 指目前流行、被接受或受偏好。"},{"en":"Reusable bottles are in because more people want to reduce plastic waste.","zh":"可重用水樽正流行，因為更多人想減少塑膠廢物。"},{"en":"A method becomes “in” when experts and the public start supporting it.","zh":"當專家和公眾開始支持某方法，它就會變得受重視。"},{"en":"This phrase describes something gaining popularity or approval.","zh":"這個短語描述某事正在獲得人氣或認可。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":11},{"front":"keep London’s feet dry","meaning":"令倫敦免受水浸","examples":[{"en":"The project aims to keep London’s feet dry.","zh":"該項目旨在令倫敦免受水浸。"},{"en":"To keep London’s feet dry means to protect London from flooding.","zh":"keep London’s feet dry 指保護倫敦免受水災。"},{"en":"A city may keep residents’ feet dry by giving rivers space to overflow safely outside town.","zh":"城市可以透過讓河流在市外安全氾濫，令居民免受水浸。"},{"en":"If floodwater is stored upstream, London may suffer less water damage.","zh":"如果洪水在上游被儲存，倫敦可能承受較少水害。"},{"en":"This phrase uses “feet dry” humorously to mean flood protection.","zh":"這個短語幽默地用「雙腳保持乾爽」表示防洪。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":11},{"front":"break the Thames’s banks upstream","meaning":"在上游打開泰晤士河河岸","examples":[{"en":"The agency is breaking the Thames’s banks upstream to restore flood plain.","zh":"該署正在上游打開泰晤士河河岸，以修復洪泛平原。"},{"en":"To break the Thames’s banks upstream means to open or lower river banks above London so water can spread onto flood plain.","zh":"break the Thames’s banks upstream 指在倫敦上游打開或降低河岸，讓水擴散到洪泛平原。"},{"en":"Engineers may deliberately open a river bank upstream to protect a town downstream.","zh":"工程師可能有意在上游打開河岸，以保護下游城鎮。"},{"en":"Letting water spread earlier can reduce pressure before it reaches a city.","zh":"讓水較早擴散可以在水到達城市前減少壓力。"},{"en":"This phrase describes controlled flooding, not accidental collapse.","zh":"這個短語描述受控氾濫，而不是意外崩塌。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":11},{"front":"upstream","meaning":"上游","examples":[{"en":"The agency is restoring flood plain upstream of London.","zh":"該署正在倫敦上游修復洪泛平原。"},{"en":"Upstream means in the direction closer to the river’s source, before the water reaches a place.","zh":"upstream 指沿河流方向較接近源頭、在水到達某地之前的位置。"},{"en":"Pollution upstream can affect everyone who uses the river downstream.","zh":"上游污染可以影響下游所有用水者。"},{"en":"Managing water upstream can reduce flood risk lower down the river.","zh":"在上游管理水流可以減少較下游水災風險。"},{"en":"This word describes position along a river system.","zh":"這個詞描述河流系統中的位置。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":11},{"front":"reflood ancient flood plain","meaning":"重新淹沒古老洪泛平原","examples":[{"en":"The agency is reflooding ancient flood plain at Otmoor.","zh":"該署正在 Otmoor 重新淹沒古老洪泛平原。"},{"en":"To reflood ancient flood plain means to allow water to return to old floodable land.","zh":"reflood ancient flood plain 指容許水重新回到古老可氾濫土地上。"},{"en":"A city may reflood old marshland to store stormwater safely.","zh":"城市可能重新淹沒舊沼澤地，以安全儲存暴雨水。"},{"en":"Reflooding can restore habitats and reduce pressure on rivers.","zh":"重新淹沒可以恢復棲息地並減少河流壓力。"},{"en":"This phrase describes bringing back a natural flood function.","zh":"這個短語描述恢復自然蓄洪功能。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":11},{"front":"ancient flood plain","meaning":"古老洪泛平原","examples":[{"en":"Ancient flood plain can store water during floods.","zh":"古老洪泛平原可以在水災期間儲水。"},{"en":"An ancient flood plain is old low land beside a river that historically flooded naturally.","zh":"ancient flood plain 指河邊過去自然氾濫的古老低地。"},{"en":"Old maps may show ancient flood plain where houses now stand.","zh":"舊地圖可能顯示現在建有房屋的地方曾是古老洪泛平原。"},{"en":"Restoring ancient flood plains can reconnect rivers with their natural storage areas.","zh":"修復古老洪泛平原可以重新連接河流與其天然儲水區。"},{"en":"This phrase refers to old floodable land, not newly built drainage.","zh":"這個短語指古老可氾濫土地，而不是新建排水設施。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":11},{"front":"create new wetlands","meaning":"建造新濕地","examples":[{"en":"The agency spent £100 million creating new wetlands.","zh":"該署花費一億英鎊建造新濕地。"},{"en":"To create new wetlands means to build or restore wet areas that can hold water and support wildlife.","zh":"create new wetlands 指建造或修復能儲水並支持野生生物的濕地。"},{"en":"A city may create new wetlands beside a river to absorb stormwater.","zh":"城市可能在河邊建造新濕地以吸收暴雨水。"},{"en":"New wetlands can reduce flooding while also improving habitats for birds and plants.","zh":"新濕地可以減少水浸，同時改善鳥類和植物棲息地。"},{"en":"This phrase describes a natural flood-management project.","zh":"這個短語描述自然防洪管理項目。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":11},{"front":"a relief channel","meaning":"分洪水道","examples":[{"en":"A relief channel can carry excess water away from vulnerable areas.","zh":"分洪水道可以把多餘的水帶離脆弱地區。"},{"en":"A relief channel is an artificial or restored waterway used to divert extra floodwater.","zh":"relief channel 指用來分流額外洪水的人工或修復水道。"},{"en":"A town may build a relief channel so stormwater bypasses the main street.","zh":"城鎮可能建造分洪水道，讓暴雨水繞過主要街道。"},{"en":"Relief channels reduce pressure when the main river cannot carry all the water.","zh":"當主河道無法承載所有水時，分洪水道可以減少壓力。"},{"en":"This phrase refers to a backup route for water.","zh":"這個短語指水的備用路線。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":11},{"front":"protect the town of","meaning":"保護……鎮","examples":[{"en":"The wetlands and relief channel protect the town of Maidenhead.","zh":"濕地和分洪水道保護 Maidenhead 鎮。"},{"en":"To protect the town of a place means to defend that specific town from danger.","zh":"protect the town of a place 指保護某個特定城鎮免受危險。"},{"en":"New sea walls may protect the town of a coastal village from storm waves.","zh":"新海堤可能保護某個沿海村鎮免受風暴浪侵襲。"},{"en":"Protection projects can reduce damage and help residents feel safer.","zh":"保護項目可以減少損害並讓居民感到較安全。"},{"en":"This phrase identifies the place receiving protection.","zh":"這個短語指出受保護的地方。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":11},{"front":"ancient playing fields","meaning":"古老運動場","examples":[{"en":"The project also protects the ancient playing fields of Eton College.","zh":"該項目也保護伊頓公學的古老運動場。"},{"en":"Ancient playing fields are old sports grounds with historical value.","zh":"ancient playing fields 指具有歷史價值的舊運動場地。"},{"en":"A school may protect ancient playing fields because generations of students have used them.","zh":"學校可能保護古老運動場，因為幾代學生都曾使用它們。"},{"en":"Flood protection can preserve not only homes but also cultural and educational spaces.","zh":"防洪不只可以保護房屋，也可以保護文化和教育空間。"},{"en":"This phrase refers to historic sports land.","zh":"這個短語指有歷史的運動用地。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":12},{"front":"the south coast","meaning":"南岸；南部海岸","examples":[{"en":"Another project is taking place near the south coast.","zh":"另一個項目正在南部海岸附近進行。"},{"en":"The south coast means the coastline on the southern side of a country or region.","zh":"south coast 指某國家或地區南面的海岸線。"},{"en":"A family may spend summer holidays on the south coast because the beaches are warmer.","zh":"家庭可能在南岸度暑假，因為海灘較溫暖。"},{"en":"Coastal projects often consider tides, storms, and river mouths together.","zh":"沿海項目常同時考慮潮汐、風暴和河口。"},{"en":"This phrase gives a general coastal location.","zh":"這個短語給出一般沿海位置。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":12},{"front":"dig out channels","meaning":"挖掘水道","examples":[{"en":"The agency is digging out channels to reconnect old meanders.","zh":"該署正在挖掘水道，以重新連接舊河曲。"},{"en":"To dig out channels means to excavate water passages so water can flow through them.","zh":"dig out channels 指挖出水道，讓水能流過。"},{"en":"Workers may dig out blocked roadside channels before the rainy season.","zh":"工人可能在雨季前挖通被堵塞的路邊水道。"},{"en":"Digging channels can redirect water, but the route must be planned carefully.","zh":"挖掘水道可以重新引導水流，但路線必須仔細規劃。"},{"en":"This phrase describes physical excavation for water flow.","zh":"這個短語描述為水流而進行的實體挖掘。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":12},{"front":"reconnect old meanders","meaning":"重新連接舊河曲","examples":[{"en":"Engineers are reconnecting old meanders on the River Cuckmere.","zh":"工程師正在卡克米爾河重新連接舊河曲。"},{"en":"To reconnect old meanders means to link a river back to its former winding bends.","zh":"reconnect old meanders 指把河流重新連回以前蜿蜒的彎道。"},{"en":"A river restoration project may reconnect old meanders to slow water naturally.","zh":"河流復修項目可能重新連接舊河曲，以自然減慢水流。"},{"en":"Reconnected bends can store water and create habitats for wildlife.","zh":"重新連接的彎道可以儲水並為野生生物創造棲息地。"},{"en":"This phrase describes restoring a river’s old winding route.","zh":"這個短語描述修復河流舊有曲折路線。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":12},{"front":"the River Cuckmere","meaning":"卡克米爾河","examples":[{"en":"Engineers are restoring old meanders on the River Cuckmere in East Sussex.","zh":"工程師正在英格蘭東薩塞克斯郡的卡克米爾河修復舊河曲。"},{"en":"The River Cuckmere is a river in East Sussex in southern England.","zh":"River Cuckmere 是英格蘭南部東薩塞克斯郡的一條河。"},{"en":"A local river like the Cuckmere can still become important in flood management.","zh":"像卡克米爾河這樣的本地河流，在防洪管理中仍可能很重要。"},{"en":"Restoring bends on the River Cuckmere can slow water before it reaches lower areas.","zh":"修復卡克米爾河的彎道可以在水到達低地前減慢水流。"},{"en":"This phrase names a specific English river.","zh":"這個短語命名一條特定英格蘭河流。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":12},{"front":"cut off by flood banks","meaning":"被防洪堤截斷","examples":[{"en":"The old meanders were cut off by flood banks 150 years ago.","zh":"舊河曲在一百五十年前被防洪堤截斷。"},{"en":"Cut off by flood banks means separated from the river by raised flood barriers.","zh":"cut off by flood banks 指被高起防洪屏障與河流分隔。"},{"en":"An old pond may be cut off from a stream when a road embankment is built.","zh":"當道路堤岸建成，舊池塘可能與溪流隔絕。"},{"en":"Cut-off meanders no longer help slow the main river’s flow.","zh":"被截斷的河曲不再幫助減慢主河道水流。"},{"en":"This phrase describes how flood defences can disconnect natural river features.","zh":"這個短語描述防洪設施如何切斷天然河流特徵。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":12},{"front":"flood banks","meaning":"防洪堤；河堤","examples":[{"en":"Flood banks once cut off the River Cuckmere’s old meanders.","zh":"防洪堤曾經截斷卡克米爾河的舊河曲。"},{"en":"Flood banks are raised banks built beside rivers to keep floodwater inside the channel.","zh":"flood banks 指建在河邊、用來把洪水留在河道內的高起堤岸。"},{"en":"Farmers may build flood banks to protect fields from seasonal river overflow.","zh":"農民可能建造防洪堤，保護農田免受季節性河水氾濫。"},{"en":"Flood banks can protect land, but they may also disconnect rivers from flood plains.","zh":"防洪堤可以保護土地，但也可能使河流與洪泛平原隔絕。"},{"en":"This phrase refers to river-side flood barriers.","zh":"這個短語指河邊防洪屏障。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":12},{"front":"on a much grander scale","meaning":"以大得多的規模","examples":[{"en":"The same approach is taking place on a much grander scale in Austria.","zh":"同一方法正在奧地利以大得多的規模進行。"},{"en":"On a much grander scale means in a much larger and more ambitious form.","zh":"on a much grander scale 指以大得多且更有雄心的形式進行。"},{"en":"A school garden project becomes grander in scale when the whole district joins it.","zh":"當整個地區都加入學校花園項目，它就以大得多的規模進行。"},{"en":"Larger scale projects can bring bigger benefits but require more planning and money.","zh":"較大規模項目可以帶來更大好處，但需要更多規劃和金錢。"},{"en":"This phrase compares a small example with a much bigger one.","zh":"這個短語把小例子與大得多的例子比較。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":12},{"front":"river restorations","meaning":"河流復修工程","examples":[{"en":"Austria is carrying out one of Europe’s largest river restorations.","zh":"奧地利正在進行歐洲最大型河流復修工程之一。"},{"en":"River restorations are projects that return rivers closer to their natural shape and function.","zh":"river restorations 指把河流恢復到較接近自然形態和功能的項目。"},{"en":"A river restoration may remove concrete banks and bring back wetlands.","zh":"河流復修工程可能移除混凝土河岸並恢復濕地。"},{"en":"Restoring rivers can reduce floods and improve habitats.","zh":"修復河流可以減少水災並改善棲息地。"},{"en":"This phrase describes repairing river systems, not just beautifying them.","zh":"這個短語描述修復河流系統，而不只是美化。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":12},{"front":"to date","meaning":"迄今為止","examples":[{"en":"The Drava project is one of Europe’s largest river restorations to date.","zh":"德拉瓦河項目是歐洲迄今為止最大型河流復修工程之一。"},{"en":"To date means up to the present time or up to the time being discussed.","zh":"to date 指直到現在，或直到所討論的時間為止。"},{"en":"This is the school’s most expensive science project to date.","zh":"這是該校迄今為止最昂貴的科學項目。"},{"en":"The phrase suggests comparison with everything that happened before.","zh":"這個短語表示與之前所有事情作比較。"},{"en":"It is often used when describing records or major achievements.","zh":"它常用於描述紀錄或重大成就。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":12},{"front":"regenerate flood plains","meaning":"修復洪泛平原","examples":[{"en":"Engineers are regenerating flood plains along the River Drava.","zh":"工程師正在德拉瓦河沿岸修復洪泛平原。"},{"en":"To regenerate flood plains means to restore damaged or lost flood plains so they can function again.","zh":"regenerate flood plains 指修復受損或消失的洪泛平原，使其再次發揮功能。"},{"en":"A town may regenerate flood plains by removing barriers and planting wetland vegetation.","zh":"城鎮可能透過移除屏障和種植濕地植物來修復洪泛平原。"},{"en":"Regenerated flood plains can store water and support wildlife.","zh":"已修復的洪泛平原可以儲水並支持野生生物。"},{"en":"This phrase describes bringing a natural flood area back to life.","zh":"這個短語描述讓天然洪泛區恢復生命。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":13},{"front":"the River Drava","meaning":"德拉瓦河","examples":[{"en":"The River Drava exits the Alps and flows towards Slovenia and Croatia.","zh":"德拉瓦河流出阿爾卑斯山，流向斯洛文尼亞和克羅地亞。"},{"en":"The River Drava is a European river connected with the Alps and countries in central and south-eastern Europe.","zh":"River Drava 是一條與阿爾卑斯山及中歐、東南歐國家相關的歐洲河流。"},{"en":"River projects on the Drava can affect towns across national borders.","zh":"德拉瓦河上的項目可以影響跨國城鎮。"},{"en":"Restoring the Drava’s flood plain can slow water moving out of mountain regions.","zh":"修復德拉瓦河洪泛平原可以減慢流出山區的水。"},{"en":"This phrase names a specific European river.","zh":"這個短語命名一條特定歐洲河流。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":13},{"front":"exit the Alps","meaning":"流出阿爾卑斯山","examples":[{"en":"The Drava exits the Alps before flowing downstream.","zh":"德拉瓦河在流向下游前流出阿爾卑斯山。"},{"en":"To exit the Alps means to leave the Alpine mountain region and flow into lower land.","zh":"exit the Alps 指離開阿爾卑斯山區並流入較低土地。"},{"en":"A river may become wider after it exits the mountains.","zh":"河流流出山區後可能變得更寬。"},{"en":"Water leaving steep mountains can carry speed and energy into valleys.","zh":"離開陡峭山區的水可以把速度和能量帶入山谷。"},{"en":"This phrase describes a river moving out of a mountain area.","zh":"這個短語描述河流離開山區。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":13},{"front":"widen the river bed","meaning":"擴闊河床","examples":[{"en":"Engineers are widening the river bed to give the river more space.","zh":"工程師正在擴闊河床，給河流更多空間。"},{"en":"To widen the river bed means to make the bottom channel of the river broader.","zh":"widen the river bed 指把河流底部水道變得更寬。"},{"en":"A city may widen a drainage channel so it can carry more stormwater.","zh":"城市可能擴闊排水渠，以承載更多暴雨水。"},{"en":"A wider river bed can slow water by spreading the flow over more space.","zh":"較寬河床可以透過把水流分散到更多空間來減慢水流。"},{"en":"This phrase describes changing the river’s physical channel.","zh":"這個短語描述改變河流實體河道。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":13},{"front":"river bed","meaning":"河床","examples":[{"en":"A wider river bed can slow down floodwater.","zh":"較寬的河床可以減慢洪水。"},{"en":"A river bed is the bottom of a river channel where water normally flows.","zh":"river bed 指河流水道底部，水通常在其上流動。"},{"en":"During drought, people may see stones and mud on the dry river bed.","zh":"乾旱期間，人們可能在乾河床上看到石頭和泥。"},{"en":"The shape of the river bed affects water speed and depth.","zh":"河床形狀會影響水流速度和深度。"},{"en":"This phrase refers to the physical base of a river.","zh":"這個短語指河流的實體底部。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":13},{"front":"channel it back into","meaning":"把……引回","examples":[{"en":"Engineers are channelling the river back into abandoned meanders.","zh":"工程師正把河流引回廢棄河曲。"},{"en":"To channel something back into a place means to direct it back there through a route or channel.","zh":"channel something back into a place 指透過路線或渠道把某物引回那裡。"},{"en":"A school may channel extra funds back into libraries after years of cuts.","zh":"學校可能在多年削減後，把額外資金重新投放回圖書館。"},{"en":"Channelling a river back into old bends can restore slower natural flow.","zh":"把河流引回舊彎道可以恢復較慢的自然流動。"},{"en":"This phrase describes guided return to an earlier route or use.","zh":"這個短語描述被引導回到較早路線或用途。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":13},{"front":"abandoned meanders","meaning":"廢棄河曲","examples":[{"en":"The river is being channelled back into abandoned meanders.","zh":"河流正被引回廢棄河曲。"},{"en":"Abandoned meanders are old winding river bends that have been cut off or left unused.","zh":"abandoned meanders 指已被截斷或不再使用的舊河流彎道。"},{"en":"Old maps may reveal abandoned meanders beside a straightened river.","zh":"舊地圖可能顯示被拉直河流旁邊的廢棄河曲。"},{"en":"Reusing abandoned meanders can slow floodwater and restore habitats.","zh":"重新利用廢棄河曲可以減慢洪水並恢復棲息地。"},{"en":"This phrase refers to former bends in a river.","zh":"這個短語指河流昔日的彎道。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":13},{"front":"oxbow lakes","meaning":"牛軛湖","examples":[{"en":"Oxbow lakes can store floodwater during storms.","zh":"牛軛湖可以在風暴期間儲存洪水。"},{"en":"Oxbow lakes are curved lakes formed when a river bend becomes cut off from the main channel.","zh":"oxbow lakes 指河流彎道被主河道截斷後形成的彎月形湖泊。"},{"en":"A geography class may draw oxbow lakes to understand how rivers change shape.","zh":"地理課可能繪畫牛軛湖，以理解河流如何改變形狀。"},{"en":"Oxbow lakes can become useful storage areas when water levels rise.","zh":"當水位上升，牛軛湖可以成為有用儲水區。"},{"en":"This phrase describes a lake made from an old river bend.","zh":"這個短語描述由舊河曲形成的湖泊。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":13},{"front":"overhung with willows","meaning":"被柳樹覆蓋；柳樹垂覆其上","examples":[{"en":"The backwaters are overhung with willows.","zh":"回水區被柳樹垂覆其上。"},{"en":"Overhung with willows means covered or shaded by willow trees leaning over the water.","zh":"overhung with willows 指柳樹伸向水面上方，覆蓋或遮蔽水域。"},{"en":"A pond overhung with trees may feel cool and sheltered in summer.","zh":"被樹木覆蓋的池塘在夏天可能感覺涼快而受保護。"},{"en":"Vegetation beside water can slow erosion and create habitats.","zh":"水邊植物可以減慢侵蝕並創造棲息地。"},{"en":"This phrase gives a natural image of tree-covered water edges.","zh":"這個短語呈現水邊被樹木覆蓋的自然畫面。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":13},{"front":"restored flood plain","meaning":"已修復的洪泛平原","examples":[{"en":"The restored flood plain can store millions of cubic metres of floodwater.","zh":"已修復的洪泛平原可以儲存數百萬立方米洪水。"},{"en":"A restored flood plain is floodable land that has been repaired or reconnected to a river.","zh":"restored flood plain 指已被修復或重新連接到河流的可氾濫土地。"},{"en":"A restored flood plain may become wet again after old barriers are removed.","zh":"移除舊屏障後，已修復的洪泛平原可能重新變濕。"},{"en":"Restored flood plains reduce flood peaks by spreading and storing water.","zh":"已修復的洪泛平原透過分散和儲存水來降低洪峰。"},{"en":"This phrase describes flood plain brought back into use.","zh":"這個短語描述重新投入使用的洪泛平原。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":13},{"front":"store up to","meaning":"最多儲存","examples":[{"en":"The restored flood plain can store up to 10 million cubic metres of floodwater.","zh":"已修復的洪泛平原最多可儲存一千萬立方米洪水。"},{"en":"To store up to an amount means to hold as much as that maximum amount.","zh":"store up to an amount 指最多可容納某個數量。"},{"en":"A school water tank may store up to 5,000 litres for gardening.","zh":"學校水箱最多可儲存五千公升水作園藝用途。"},{"en":"Storage capacity matters because excess water needs somewhere safe to go.","zh":"儲存容量很重要，因為多餘的水需要安全去處。"},{"en":"This phrase gives the upper limit of capacity.","zh":"這個短語給出容量上限。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":14},{"front":"cubic metres","meaning":"立方米","examples":[{"en":"The flood plain can store up to 10 million cubic metres of water.","zh":"洪泛平原最多可儲存一千萬立方米的水。"},{"en":"Cubic metres are units used to measure volume, especially the space taken up by water, air, or material.","zh":"cubic metres 是量度體積的單位，尤其用於水、空氣或材料佔用的空間。"},{"en":"A swimming pool may hold hundreds of cubic metres of water.","zh":"游泳池可能容納數百立方米的水。"},{"en":"Measuring floodwater in cubic metres helps engineers calculate storage needs.","zh":"以立方米量度洪水，有助工程師計算儲水需要。"},{"en":"This phrase refers to three-dimensional volume, not length or area.","zh":"這個短語指三維體積，而不是長度或面積。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":14},{"front":"storm surges","meaning":"暴雨引發的洪峰；風暴潮","examples":[{"en":"The restored flood plain can slow storm surges coming out of the Alps.","zh":"已修復的洪泛平原可以減慢從阿爾卑斯山湧出的暴雨洪峰。"},{"en":"Storm surges here means sudden powerful rises in water flow caused by storms.","zh":"storm surges 在這裡指由風暴造成的突然強大水流上升。"},{"en":"After intense mountain rain, a storm surge may rush down a river valley.","zh":"山區強降雨後，暴雨洪峰可能沿河谷急速湧下。"},{"en":"Slowing a surge gives downstream towns more time and reduces peak danger.","zh":"減慢洪峰可以給下游城鎮更多時間並降低最高危險。"},{"en":"This phrase describes a sudden dangerous pulse of water.","zh":"這個短語描述突然且危險的一股水流。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":14},{"front":"slow storm surges","meaning":"減慢洪峰速度","examples":[{"en":"The flood plain can slow storm surges by more than an hour.","zh":"洪泛平原可以把洪峰速度減慢超過一小時。"},{"en":"To slow storm surges means to delay and weaken sudden floodwater peaks.","zh":"slow storm surges 指延遲並削弱突然的洪水高峰。"},{"en":"Wetlands can slow storm surges by absorbing part of the flow.","zh":"濕地可以透過吸收部分水流來減慢洪峰速度。"},{"en":"Even a one-hour delay can help emergency teams close roads and warn residents.","zh":"即使只延遲一小時，也可以幫助緊急隊伍封路並警告居民。"},{"en":"This phrase focuses on reducing the speed and timing pressure of floodwater.","zh":"這個短語著重減少洪水速度和時間壓力。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":14},{"front":"as far downstream as","meaning":"遠至下游的……","examples":[{"en":"The project protects towns as far downstream as Slovenia and Croatia.","zh":"該項目保護遠至下游斯洛文尼亞和克羅地亞的城鎮。"},{"en":"As far downstream as means even to places far lower along the river.","zh":"as far downstream as 指甚至到達河流下游很遠的地方。"},{"en":"Pollution released upstream may affect communities as far downstream as the river mouth.","zh":"上游釋放的污染可能影響遠至河口的下游社區。"},{"en":"This phrase shows that effects can travel a long distance with the water.","zh":"這個短語顯示影響可以隨水流傳得很遠。"},{"en":"It highlights the wide reach of river management.","zh":"它突出河流管理的廣泛影響範圍。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":14},{"front":"be allowed to take more space","meaning":"被容許佔用更多空間","examples":[{"en":"Rivers have to be allowed to take more space.","zh":"河流必須被容許佔用更多空間。"},{"en":"To be allowed to take more space means to be given room to spread naturally instead of being tightly confined.","zh":"be allowed to take more space 指被給予空間自然擴散，而不是被嚴密限制。"},{"en":"A crowded classroom works better when students are allowed to take more space during group work.","zh":"小組活動時，若學生被容許佔用更多空間，擠迫課室會運作得更好。"},{"en":"Rivers need space because floodwater becomes dangerous when squeezed into narrow channels.","zh":"河流需要空間，因為洪水被擠進狹窄河道時會變得危險。"},{"en":"This phrase describes giving natural systems room to function.","zh":"這個短語描述給自然系統發揮功能的空間。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":14},{"front":"flood-chutes","meaning":"排洪槽","examples":[{"en":"Nienhuis says rivers should not be treated as flood-chutes.","zh":"Nienhuis 說河流不應被當作排洪槽。"},{"en":"Flood-chutes are channels that quickly carry floodwater away in one direction.","zh":"flood-chutes 指快速把洪水朝一個方向帶走的渠道。"},{"en":"A concrete drainage channel acts like a flood-chute when it sends stormwater straight downstream.","zh":"混凝土排水渠把暴雨水直接送往下游時，就像排洪槽。"},{"en":"Treating rivers as flood-chutes can increase speed and danger elsewhere.","zh":"把河流當作排洪槽可以增加其他地方的速度和危險。"},{"en":"This phrase criticises using rivers only as fast flood outlets.","zh":"這個短語批評只把河流用作快速排洪出口。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":14},{"front":"flood-foilers","meaning":"防洪屏障；阻洪工具","examples":[{"en":"Rivers should be turned from flood-chutes into flood-foilers.","zh":"河流應由排洪槽變成阻洪工具。"},{"en":"Flood-foilers are systems that help prevent, weaken, or disrupt floods.","zh":"flood-foilers 指幫助防止、削弱或干擾水災的系統。"},{"en":"Wetlands can act as flood-foilers by absorbing water before it reaches a town.","zh":"濕地可以在水到達城鎮前吸收水分，起阻洪工具作用。"},{"en":"A river becomes a flood-foiler when it is given space to slow and store water.","zh":"當河流被給予空間減速和儲水，它就成為防洪工具。"},{"en":"This phrase means a tool that frustrates flood damage.","zh":"這個短語指阻止洪水破壞的工具。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":14},{"front":"preventing floods","meaning":"防止水災","examples":[{"en":"For the Dutch, preventing floods is a matter of survival.","zh":"對荷蘭人而言，防止水災是生死攸關的事。"},{"en":"Preventing floods means stopping floods from happening or reducing their impact.","zh":"preventing floods 指阻止水災發生或減低其影響。"},{"en":"A town prevents floods by clearing drains, preserving wetlands, and warning residents early.","zh":"城鎮透過清理排水渠、保護濕地和及早警告居民來防止水災。"},{"en":"Flood prevention can save homes, farms, roads, and lives.","zh":"防止水災可以拯救房屋、農田、道路和生命。"},{"en":"This phrase focuses on avoiding flood damage before it happens.","zh":"這個短語著重在水災發生前避免損害。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":14},{"front":"a matter of survival","meaning":"生死攸關的事","examples":[{"en":"For the Dutch, flood prevention is a matter of survival.","zh":"對荷蘭人而言，防洪是生死攸關的事。"},{"en":"A matter of survival means something is essential for staying alive or safe.","zh":"matter of survival 指某事對維持生命或安全至關重要。"},{"en":"For a hospital during a power cut, backup electricity is a matter of survival.","zh":"對停電中的醫院而言，後備電力是生死攸關的事。"},{"en":"When land lies below sea level, flood control becomes more than convenience.","zh":"當土地位於海平面以下，防洪就不只是便利問題。"},{"en":"This phrase stresses extreme importance.","zh":"這個短語強調極端重要性。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":14},{"front":"go furthest","meaning":"走得最遠；做得最徹底","examples":[{"en":"The Dutch have gone furthest in rethinking flood control.","zh":"荷蘭人在重新思考防洪方面走得最遠。"},{"en":"To go furthest means to do the most or take the most advanced steps compared with others.","zh":"go furthest 指與其他人相比做得最多或採取最先進步驟。"},{"en":"One school may go furthest in reducing homework by redesigning the whole timetable.","zh":"一所學校可能透過重新設計整個時間表，在減少功課方面做得最徹底。"},{"en":"A country goes furthest when it changes not just one rule but the whole approach.","zh":"當一個國家改變的不只是一條規則，而是整個方法，它就是走得最遠。"},{"en":"This phrase describes the most complete action among a group.","zh":"這個短語描述一組之中最完整的行動。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":15},{"front":"built largely on","meaning":"主要建於……之上","examples":[{"en":"The Netherlands is built largely on drained marshes and seabed.","zh":"荷蘭主要建於已排乾水的沼澤地和海床之上。"},{"en":"Built largely on means mostly constructed or developed on a particular type of land or foundation.","zh":"built largely on 指大部分建造或發展於某種土地或基礎之上。"},{"en":"Some modern districts are built largely on reclaimed land.","zh":"有些現代地區主要建於填海土地之上。"},{"en":"The ground a country or city is built on affects its flood risk.","zh":"國家或城市建於甚麼地面會影響其水災風險。"},{"en":"This phrase describes the physical base of development.","zh":"這個短語描述發展的實體基礎。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":15},{"front":"drained marshes","meaning":"已排乾水的沼澤地","examples":[{"en":"Much of the Netherlands is built on drained marshes.","zh":"荷蘭大部分建於已排乾水的沼澤地之上。"},{"en":"Drained marshes are wetland areas from which water has been removed to make land usable.","zh":"drained marshes 指水被排走、以便土地可用的濕地區域。"},{"en":"Farmers may drain marshes to create fields, but the land may remain low and flood-prone.","zh":"農民可能排乾沼澤來創造農田，但土地可能仍然低窪且易水浸。"},{"en":"Draining marshes can provide land while reducing natural water storage.","zh":"排乾沼澤可以提供土地，同時減少天然儲水。"},{"en":"This phrase refers to former wetlands made dry by human action.","zh":"這個短語指經人為排水變乾的昔日濕地。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":15},{"front":"seabed","meaning":"海床","examples":[{"en":"Parts of the Netherlands were built on reclaimed seabed.","zh":"荷蘭部分地區建於填海後的海床之上。"},{"en":"Seabed is the ground at the bottom of the sea.","zh":"seabed 指海底的地面。"},{"en":"Engineers may reclaim seabed by building barriers and pumping out water.","zh":"工程師可能透過建造屏障和抽走水來開墾海床。"},{"en":"Land made from seabed can be useful but may need strong flood protection.","zh":"由海床造出的土地可以有用，但可能需要強大防洪保護。"},{"en":"This word refers to the sea floor.","zh":"這個詞指海底地面。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":15},{"front":"have the fright of its life","meaning":"嚇得魂飛魄散；受到極大驚嚇","examples":[{"en":"The Netherlands had the fright of its life when the Rhine almost overwhelmed it.","zh":"當萊茵河幾乎淹沒荷蘭時，荷蘭受到極大驚嚇。"},{"en":"To have the fright of one’s life means to be extremely frightened by a serious danger.","zh":"have the fright of one’s life 指因嚴重危險而極度驚恐。"},{"en":"A driver may have the fright of his life when a child suddenly runs into the road.","zh":"當孩子突然跑出馬路，司機可能嚇得魂飛魄散。"},{"en":"A near disaster can shock a country into changing its policies.","zh":"接近災難的事件可以震撼一個國家，促使政策改變。"},{"en":"This phrase is informal and dramatic.","zh":"這個短語較口語且帶戲劇性。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":15},{"front":"overwhelm something","meaning":"淹沒；壓倒","examples":[{"en":"The Rhine almost overwhelmed the Netherlands in 1993.","zh":"萊茵河在 1993 年幾乎淹沒荷蘭。"},{"en":"To overwhelm something means to overpower it with too much force, water, pressure, or demand.","zh":"overwhelm something 指以過多力量、水量、壓力或需求壓倒某物。"},{"en":"A hospital can be overwhelmed when too many patients arrive at once.","zh":"當太多病人同時到達，醫院可能不勝負荷。"},{"en":"Floodwater overwhelms defences when the water is higher or stronger than they can handle.","zh":"當水位或水力超出防線承受能力，洪水就會壓倒防線。"},{"en":"This phrase describes a system being unable to cope.","zh":"這個短語描述系統無法應付。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":15},{"front":"a quarter of a million people","meaning":"二十五萬人","examples":[{"en":"A quarter of a million people were evacuated from the Netherlands in 1995.","zh":"1995 年，有二十五萬人從荷蘭撤離。"},{"en":"A quarter of a million people means 250,000 people.","zh":"a quarter of a million people 指二十五萬人。"},{"en":"A music festival with a quarter of a million visitors needs huge transport planning.","zh":"有二十五萬訪客的音樂節需要大量交通規劃。"},{"en":"Moving this many people during a flood requires buses, shelters, and clear instructions.","zh":"在水災期間轉移這麼多人需要巴士、庇護所和清楚指示。"},{"en":"This phrase expresses a very large number of people.","zh":"這個短語表達非常龐大的人數。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":15},{"front":"be evacuated from","meaning":"從……撤離","examples":[{"en":"Many people were evacuated from the Netherlands during the floods.","zh":"水災期間，許多人從荷蘭撤離。"},{"en":"To be evacuated from a place means to be moved away from it because of danger.","zh":"be evacuated from a place 指因危險而被移離某地。"},{"en":"Students may be evacuated from a school building during a fire alarm.","zh":"火警鐘響起時，學生可能從校舍撤離。"},{"en":"Evacuation protects people before conditions become life-threatening.","zh":"撤離可以在情況危及生命前保護人們。"},{"en":"This phrase describes organised removal from danger.","zh":"這個短語描述有組織地離開危險地區。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":15},{"front":"a new breed of","meaning":"新一類的……","examples":[{"en":"A new breed of soft engineers wants cities to become porous.","zh":"新一類軟性工程師希望城市變得可滲水。"},{"en":"A new breed of people means a new type of people with different ideas or methods.","zh":"a new breed of people 指一種有不同想法或方法的新類型人群。"},{"en":"A new breed of teachers uses games, videos, and discussion instead of only lectures.","zh":"新一類老師使用遊戲、影片和討論，而不只是講課。"},{"en":"New types of professionals often appear when old methods stop working.","zh":"當舊方法不再有效，新類型專業人士常會出現。"},{"en":"This phrase describes a fresh group with a new approach.","zh":"這個短語描述帶有新方法的新群體。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":15},{"front":"soft engineers","meaning":"軟性工程師；自然工程派","examples":[{"en":"Soft engineers prefer natural and flexible flood-management methods.","zh":"軟性工程師偏好自然和彈性的防洪管理方法。"},{"en":"Soft engineers are engineers who use natural, flexible, and less concrete-heavy solutions.","zh":"soft engineers 指使用自然、彈性且較少依賴混凝土方案的工程師。"},{"en":"A soft engineer may restore wetlands instead of simply building higher walls.","zh":"軟性工程師可能修復濕地，而不是單純建更高牆。"},{"en":"Soft engineering can reduce floods while improving landscapes and wildlife habitats.","zh":"軟性工程可以減少水災，同時改善地貌和野生生物棲息地。"},{"en":"This phrase contrasts natural engineering with hard concrete defences.","zh":"這個短語把自然工程與硬性混凝土防線作對比。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":15},{"front":"become porous","meaning":"變得可滲水","examples":[{"en":"Soft engineers want cities to become porous.","zh":"軟性工程師希望城市變得可滲水。"},{"en":"To become porous means to allow water to soak in rather than run off quickly.","zh":"become porous 指讓水滲入，而不是快速流走。"},{"en":"A car park can become porous if concrete is replaced with permeable paving.","zh":"如果停車場用透水鋪面取代混凝土，它就可以變得可滲水。"},{"en":"Porous surfaces reduce flooding because rainwater enters the ground.","zh":"透水表面可以減少水浸，因為雨水會進入地下。"},{"en":"This phrase describes cities acting more like sponges.","zh":"這個短語描述城市像海綿一樣運作。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":16},{"front":"a shining example","meaning":"出色典範","examples":[{"en":"Berlin is a shining example of a porous city.","zh":"柏林是海綿城市的出色典範。"},{"en":"A shining example is an excellent example that clearly shows how something can work.","zh":"shining example 指清楚顯示某事如何可行的優秀例子。"},{"en":"A school with clean energy, gardens, and recycling can be a shining example of sustainability.","zh":"有清潔能源、花園和回收系統的學校，可以是可持續發展的出色典範。"},{"en":"Strong examples help other cities or organisations copy a successful idea.","zh":"強而有力的例子幫助其他城市或組織仿效成功想法。"},{"en":"This phrase praises an example as especially impressive.","zh":"這個短語稱讚某例子特別出色。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":16},{"front":"since reunification","meaning":"自重新統一以來","examples":[{"en":"Since reunification, Berlin’s redevelopment has followed strict drainage rules.","zh":"自重新統一以來，柏林重建一直遵循嚴格排水規則。"},{"en":"Since reunification means from the time when divided parts of a country or city were joined again.","zh":"since reunification 指自一個國家或城市分裂部分重新合併以來。"},{"en":"Since reunification, a city may rebuild transport links between areas once separated.","zh":"自重新統一以來，城市可能重建曾被分隔地區之間的交通連接。"},{"en":"Major political changes can lead to major planning changes.","zh":"重大政治變化可以帶來重大規劃變化。"},{"en":"This phrase gives a historical starting point after reunification.","zh":"這個短語給出重新統一後的歷史起點。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":16},{"front":"massive redevelopment","meaning":"大規模重建","examples":[{"en":"Berlin’s massive redevelopment has been governed by tough new rules.","zh":"柏林的大規模重建一直受嚴格新規定規管。"},{"en":"Massive redevelopment means very large-scale rebuilding or improvement of an area.","zh":"massive redevelopment 指對某地區進行非常大規模的重建或改善。"},{"en":"A former factory district may undergo massive redevelopment into homes, offices, and parks.","zh":"舊工廠區可能進行大規模重建，變成住宅、辦公室和公園。"},{"en":"Large redevelopment can change drainage, traffic, housing, and community life.","zh":"大型重建可以改變排水、交通、住屋和社區生活。"},{"en":"This phrase describes major urban rebuilding.","zh":"這個短語描述重大城市重建。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":16},{"front":"be governed by","meaning":"受……規管","examples":[{"en":"The city’s redevelopment has been governed by tough new rules.","zh":"這座城市的重建一直受嚴格新規定規管。"},{"en":"To be governed by rules means to be controlled or guided by them.","zh":"be governed by rules 指受規則控制或引導。"},{"en":"School exams are governed by rules about time, materials, and behaviour.","zh":"學校考試受關於時間、物品和行為的規則規管。"},{"en":"Strong rules can shape how buildings are designed and how water is managed.","zh":"強力規則可以塑造建築設計和水管理方式。"},{"en":"This phrase describes formal control by rules or principles.","zh":"這個短語描述由規則或原則作正式控制。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":16},{"front":"tough new rules","meaning":"嚴格的新規定","examples":[{"en":"Tough new rules prevent drains from becoming overloaded.","zh":"嚴格的新規定防止排水渠負荷過重。"},{"en":"Tough new rules are strict new regulations that people must follow.","zh":"tough new rules 指人們必須遵守的嚴格新規例。"},{"en":"A school may introduce tough new rules after repeated cheating in exams.","zh":"反覆出現考試作弊後，學校可能引入嚴格新規定。"},{"en":"Strict rules can prevent problems, but they may also require money and effort to follow.","zh":"嚴格規定可以防止問題，但也可能需要金錢和努力來遵守。"},{"en":"This phrase suggests firm regulation.","zh":"這個短語表示強硬規管。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":16},{"front":"become overloaded","meaning":"負荷過重","examples":[{"en":"City drains can become overloaded after heavy rain.","zh":"城市排水渠在大雨後可能負荷過重。"},{"en":"To become overloaded means to receive more work, water, weight, or demand than something can handle.","zh":"become overloaded 指承受超過能力範圍的工作、水量、重量或需求。"},{"en":"A school server may become overloaded when all students log in at the same time.","zh":"當所有學生同時登入，學校伺服器可能負荷過重。"},{"en":"Overloaded drains cannot carry water away fast enough, so streets flood.","zh":"負荷過重的排水渠無法足夠快地排走水，所以街道水浸。"},{"en":"This phrase describes capacity being exceeded.","zh":"這個短語描述容量被超出。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":16},{"front":"after heavy rains","meaning":"在強降雨之後","examples":[{"en":"Drains can become overloaded after heavy rains.","zh":"排水渠在強降雨之後可能負荷過重。"},{"en":"After heavy rains means following periods of strong or large amounts of rainfall.","zh":"after heavy rains 指大量或猛烈降雨之後。"},{"en":"After heavy rains, a school playground may stay muddy for several days.","zh":"強降雨之後，學校操場可能泥濘數天。"},{"en":"Heavy rain can reveal weaknesses in drains, roofs, and road surfaces.","zh":"大雨可以暴露排水渠、屋頂和路面弱點。"},{"en":"This phrase gives the time after intense rainfall.","zh":"這個短語給出強降雨之後的時間。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":16},{"front":"see rainwater as a resource","meaning":"把雨水視為資源","examples":[{"en":"Berlin now sees rainwater as a resource to be kept.","zh":"柏林現在把雨水視為應保留的資源。"},{"en":"To see rainwater as a resource means to treat rainwater as useful, not as waste.","zh":"see rainwater as a resource 指把雨水視為有用，而不是廢水。"},{"en":"A school garden may see rainwater as a resource by collecting it in barrels.","zh":"學校花園可能透過用水桶收集雨水，把雨水視為資源。"},{"en":"If rainwater is stored, it can water plants and reduce pressure on drains.","zh":"如果雨水被儲存，它可以灌溉植物並減少排水渠壓力。"},{"en":"This phrase changes the attitude from disposal to reuse.","zh":"這個短語把態度由排走轉向再用。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":16},{"front":"rather than got rid of","meaning":"而不是花大錢排走","examples":[{"en":"Rainwater is now kept rather than got rid of at great cost.","zh":"雨水現在被保留，而不是花大錢排走。"},{"en":"Rather than got rid of means instead of being removed or thrown away.","zh":"rather than got rid of 指而不是被移走或丟棄。"},{"en":"Food leftovers can be composted rather than got rid of in ordinary rubbish.","zh":"食物殘渣可以用來堆肥，而不是當普通垃圾丟掉。"},{"en":"Keeping useful resources can save money and reduce waste.","zh":"保留有用資源可以節省金錢並減少浪費。"},{"en":"This phrase contrasts reuse with disposal.","zh":"這個短語把再用與丟棄作對比。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":16},{"front":"at great cost","meaning":"以高昂成本","examples":[{"en":"Some cities get rid of rainwater at great cost.","zh":"有些城市以高昂成本排走雨水。"},{"en":"At great cost means with a large financial, social, or practical expense.","zh":"at great cost 指付出巨大金錢、社會或實際代價。"},{"en":"A family may repair an old roof at great cost after years of delay.","zh":"家庭在拖延多年後，可能以高昂成本維修舊屋頂。"},{"en":"Doing something at great cost can be wasteful if a cheaper natural option exists.","zh":"如果有較便宜的自然方案，以高昂成本做某事可能浪費。"},{"en":"This phrase stresses that the price or burden is high.","zh":"這個短語強調價格或負擔很高。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":17},{"front":"a good illustration","meaning":"很好的例子","examples":[{"en":"Potsdamer Platz is a good illustration of the new approach.","zh":"波茨坦廣場是新方法的很好例子。"},{"en":"A good illustration is a clear example that helps explain an idea.","zh":"good illustration 指幫助解釋想法的清楚例子。"},{"en":"A school recycling programme can be a good illustration of how small habits reduce waste.","zh":"學校回收計劃可以很好地說明小習慣如何減少浪費。"},{"en":"Good illustrations make abstract ideas easier to understand.","zh":"好例子令抽象想法更易理解。"},{"en":"This phrase introduces a concrete example.","zh":"這個短語引入具體例子。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":17},{"front":"commercial redevelopment","meaning":"商業重建項目","examples":[{"en":"Potsdamer Platz is a huge commercial redevelopment in central Berlin.","zh":"波茨坦廣場是柏林市中心一個大型商業重建項目。"},{"en":"Commercial redevelopment means rebuilding an area for business uses such as offices, shops, and entertainment.","zh":"commercial redevelopment 指為辦公室、商店和娛樂等商業用途重建某地區。"},{"en":"An old market district may become a commercial redevelopment with malls and hotels.","zh":"舊市場區可能變成有商場和酒店的商業重建項目。"},{"en":"Such projects can change drainage because large roofs and paved surfaces affect rainwater.","zh":"這類項目可以改變排水，因為大屋頂和鋪面會影響雨水。"},{"en":"This phrase refers to business-focused urban rebuilding.","zh":"這個短語指以商業為重點的城市重建。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":17},{"front":"in the heart of the city","meaning":"在市中心","examples":[{"en":"Potsdamer Platz is in the heart of the city.","zh":"波茨坦廣場位於市中心。"},{"en":"In the heart of the city means in the central and important part of the city.","zh":"in the heart of the city 指在城市中央而重要的部分。"},{"en":"A main train station is often located in the heart of the city.","zh":"主要火車站通常位於市中心。"},{"en":"Projects in the city centre can affect many workers, visitors, and residents.","zh":"市中心項目可以影響許多工人、訪客和居民。"},{"en":"This phrase gives a central urban location.","zh":"這個短語給出城市中心位置。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":17},{"front":"spend billions of dollars doing something","meaning":"花費數十億美元做某事","examples":[{"en":"Los Angeles has spent billions of dollars digging huge drains.","zh":"洛杉磯已花費數十億美元挖掘大型排水渠。"},{"en":"To spend billions of dollars doing something means to use an extremely large amount of money on that activity.","zh":"spend billions of dollars doing something 指在某活動上使用極大量金錢。"},{"en":"A government may spend billions of dollars building new railways.","zh":"政府可能花費數十億美元建造新鐵路。"},{"en":"Huge spending does not always solve a problem if the plan is wrong.","zh":"如果計劃錯誤，巨額開支不一定能解決問題。"},{"en":"This phrase stresses very large financial investment.","zh":"這個短語強調非常龐大的財務投資。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":17},{"front":"concrete river beds","meaning":"鋪上混凝土的河床","examples":[{"en":"Los Angeles has concreted river beds to carry stormwater away.","zh":"洛杉磯把河床鋪上混凝土，以排走暴雨水。"},{"en":"Concrete river beds are river bottoms covered with concrete to control and speed water flow.","zh":"concrete river beds 指鋪上混凝土以控制和加快水流的河流底部。"},{"en":"A concrete channel may look tidy but provide little space for plants or wildlife.","zh":"混凝土水道可能看起來整齊，但幾乎不給植物或野生生物空間。"},{"en":"Concrete beds can carry water quickly, but they may reduce natural absorption.","zh":"混凝土河床可以快速排水，但可能減少自然吸收。"},{"en":"This phrase describes hard engineering of a river base.","zh":"這個短語描述對河床的硬性工程改造。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":17},{"front":"carry away the water","meaning":"把水排走","examples":[{"en":"The drains were built to carry away water from intense storms.","zh":"這些排水渠被建造來把強烈風暴的水排走。"},{"en":"To carry away the water means to move water away from a place.","zh":"carry away the water 指把水從某地移走。"},{"en":"Roof gutters carry away rainwater so it does not pour over the front door.","zh":"屋頂水槽把雨水排走，讓它不會從前門倒下來。"},{"en":"Carrying water away quickly can protect one place but may waste a useful resource.","zh":"快速把水排走可以保護一個地方，但也可能浪費有用資源。"},{"en":"This phrase focuses on removal through drains or channels.","zh":"這個短語著重透過排水渠或水道移走水。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":17},{"front":"occasional intense storms","meaning":"偶發的強烈風暴","examples":[{"en":"Los Angeles suffers from occasional intense storms.","zh":"洛杉磯受到偶發的強烈風暴影響。"},{"en":"Occasional intense storms are powerful storms that happen from time to time, not constantly.","zh":"occasional intense storms 指不時發生、但不是持續發生的強力風暴。"},{"en":"A desert town may be dry most of the year but still face occasional intense storms.","zh":"沙漠城鎮一年大部分時間乾燥，但仍可能面對偶發強烈風暴。"},{"en":"Rare but strong storms can overwhelm systems built only for normal rain.","zh":"罕見但強烈的風暴可以壓垮只為普通降雨而設的系統。"},{"en":"This phrase combines low frequency with high severity.","zh":"這個短語結合低頻率和高嚴重性。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":17},{"front":"a cool $280 million","meaning":"高達二億八千萬美元","examples":[{"en":"The latest plan is to spend a cool $280 million on higher river walls.","zh":"最新計劃是花高達二億八千萬美元興建更高河牆。"},{"en":"A cool $280 million means a very large amount of money, said with slight irony or emphasis.","zh":"cool $280 million 指非常大筆金錢，語氣帶少許諷刺或強調。"},{"en":"A city may spend a cool $50 million on a new stadium while schools still need repairs.","zh":"城市可能花高達五千萬美元建新體育場，而學校仍需要維修。"},{"en":"This phrase draws attention to the surprising size of the cost.","zh":"這個短語把注意力放在驚人的成本規模上。"},{"en":"It is informal and often suggests the amount is strikingly high.","zh":"它較口語，常表示金額高得令人注目。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":17},{"front":"raise concrete walls","meaning":"加高混凝土牆","examples":[{"en":"The city plans to raise the concrete walls on the Los Angeles River.","zh":"該市計劃加高洛杉磯河的混凝土牆。"},{"en":"To raise concrete walls means to make existing concrete barriers higher.","zh":"raise concrete walls 指把現有混凝土屏障加高。"},{"en":"A town may raise sea walls after repeated storm damage.","zh":"城鎮在反覆風暴損害後，可能加高海堤。"},{"en":"Higher walls may hold back more water, but they can also be expensive and ugly.","zh":"更高牆可能擋住更多水，但也可能昂貴且難看。"},{"en":"This phrase describes increasing the height of hard flood defences.","zh":"這個短語描述增加硬性防洪設施的高度。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":17},{"front":"by another 2 metres","meaning":"再加高兩米","examples":[{"en":"The walls may be raised by another 2 metres.","zh":"這些牆可能再加高兩米。"},{"en":"By another 2 metres means an additional height of two metres will be added.","zh":"by another 2 metres 指額外增加兩米高度。"},{"en":"A fence may be raised by another metre if children keep climbing over it.","zh":"如果孩子一直爬過圍欄，圍欄可能再加高一米。"},{"en":"Adding height can increase protection, but it may not solve the deeper cause.","zh":"增加高度可以提高保護，但未必解決深層原因。"},{"en":"This phrase gives the amount of extra increase.","zh":"這個短語給出額外增加的幅度。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":18},{"front":"flood regularly","meaning":"經常水浸","examples":[{"en":"Many communities in Los Angeles still flood regularly.","zh":"洛杉磯許多社區仍經常水浸。"},{"en":"To flood regularly means to suffer flooding again and again.","zh":"flood regularly 指一次又一次遭受水浸。"},{"en":"A basement may flood regularly if the drain outside is always blocked.","zh":"如果外面的排水渠經常堵塞，地庫可能經常水浸。"},{"en":"Regular flooding makes insurance, repairs, and daily life more difficult.","zh":"經常水浸會令保險、維修和日常生活更困難。"},{"en":"This phrase describes a repeated local problem.","zh":"這個短語描述反覆出現的本地問題。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":18},{"front":"a desert city","meaning":"沙漠城市","examples":[{"en":"Los Angeles is a desert city that imports huge amounts of water.","zh":"洛杉磯是一個入口大量水源的沙漠城市。"},{"en":"A desert city is a city located in or near a dry region with limited local water.","zh":"desert city 指位於或靠近乾旱地區、本地水源有限的城市。"},{"en":"A desert city may depend on reservoirs, canals, or imported water to support residents.","zh":"沙漠城市可能依賴水庫、運河或外來水源支持居民。"},{"en":"Flooding in a desert city can seem ironic if the city also lacks water.","zh":"如果沙漠城市同時缺水又水浸，會顯得很諷刺。"},{"en":"This phrase highlights the contrast between dryness and flood risk.","zh":"這個短語突出乾旱與水災風險之間的對比。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":18},{"front":"ship in water","meaning":"從外地運水進來","examples":[{"en":"The city ships in water from hundreds of kilometres away.","zh":"該市從數百公里以外運水進來。"},{"en":"To ship in water means to bring water from somewhere else, often over a long distance.","zh":"ship in water 指從其他地方運送水進來，通常距離很遠。"},{"en":"An island may ship in water during a drought if local reservoirs run dry.","zh":"如果本地水庫乾涸，島嶼可能在旱災期間從外地運水進來。"},{"en":"Importing water is expensive and can create dependence on distant sources.","zh":"入口水源很昂貴，並可能造成對遠方水源的依賴。"},{"en":"This phrase describes transporting water into a place.","zh":"這個短語描述把水運入某地。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":18},{"front":"hundreds of kilometres away","meaning":"數百公里以外","examples":[{"en":"Los Angeles imports water from hundreds of kilometres away.","zh":"洛杉磯從數百公里以外入口水源。"},{"en":"Hundreds of kilometres away means very far away, over a distance of many hundred kilometres.","zh":"hundreds of kilometres away 指距離很遠，達數百公里。"},{"en":"A city may buy electricity from a power station hundreds of kilometres away.","zh":"城市可能從數百公里以外的發電站購買電力。"},{"en":"Long-distance supply can be costly and vulnerable to disruption.","zh":"長距離供應可能昂貴，而且容易受中斷影響。"},{"en":"This phrase stresses how far the source is.","zh":"這個短語強調來源距離有多遠。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":18},{"front":"fill its taps","meaning":"供應自來水","examples":[{"en":"The city imports water to fill its taps and swimming pools.","zh":"該市入口水源以供應自來水和泳池。"},{"en":"To fill its taps means to provide enough water for homes and public water supplies.","zh":"fill its taps 指為住戶和公共供水提供足夠水。"},{"en":"A dry village may need tanker trucks to fill its taps during a drought.","zh":"乾旱村莊可能需要水車在旱災期間供應自來水。"},{"en":"If local water is wasted, a city may need outside sources to keep taps running.","zh":"如果本地水源被浪費，城市可能需要外來水源來保持水龍頭有水。"},{"en":"This phrase means supplying usable water to residents.","zh":"這個短語指向居民供應可用水。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":18},{"front":"irrigate green spaces","meaning":"灌溉綠化地帶","examples":[{"en":"Imported water is used to irrigate green spaces.","zh":"入口水被用來灌溉綠化地帶。"},{"en":"To irrigate green spaces means to water parks, lawns, gardens, or planted areas.","zh":"irrigate green spaces 指為公園、草地、花園或種植區供水。"},{"en":"A school may collect rainwater to irrigate its garden during dry weeks.","zh":"學校可能收集雨水，在乾燥星期灌溉花園。"},{"en":"Irrigation keeps plants alive, but it can waste water if used carelessly.","zh":"灌溉可以令植物存活，但若使用不慎也會浪費水。"},{"en":"This phrase refers to watering managed outdoor plant areas.","zh":"這個短語指為受管理的戶外植物區澆水。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":18},{"front":"bad planning","meaning":"糟糕的規劃","examples":[{"en":"Throwing away rainwater while importing water sounds like bad planning.","zh":"一邊排走雨水，一邊入口水源，聽起來像糟糕的規劃。"},{"en":"Bad planning means poor preparation or decision-making that creates avoidable problems.","zh":"bad planning 指差劣準備或決策，造成本可避免的問題。"},{"en":"Scheduling three exams on the same day may be bad planning.","zh":"把三場考試安排在同一天可能是糟糕的規劃。"},{"en":"Bad planning wastes money when a city discards rainwater and buys water from far away.","zh":"當城市排走雨水又從遠方購水，糟糕規劃會浪費金錢。"},{"en":"This phrase criticises decisions that do not fit together sensibly.","zh":"這個短語批評不合理配合的決定。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":18},{"front":"receive half the water we need in rainfall","meaning":"從雨水中獲得所需水量的一半","examples":[{"en":"Los Angeles receives half the water it needs in rainfall.","zh":"洛杉磯從雨水中獲得所需水量的一半。"},{"en":"To receive half the water needed in rainfall means rainfall provides 50 percent of required water.","zh":"receive half the water needed in rainfall 指降雨提供所需水量的百分之五十。"},{"en":"A farm may receive half the water it needs from rain and pump the rest from wells.","zh":"農場可能從雨水中獲得所需水量的一半，其餘從井中抽取。"},{"en":"If rainfall already provides much water, wasting it can be poor management.","zh":"如果降雨已提供大量水，浪費它就是差劣管理。"},{"en":"This phrase compares natural rain supply with total water demand.","zh":"這個短語把天然降雨供應與總用水需求作比較。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":18},{"front":"throw it away","meaning":"把它白白排走","examples":[{"en":"The city receives rainwater but throws it away.","zh":"該市收到雨水，卻把它白白排走。"},{"en":"To throw it away means to waste or discard something that could be useful.","zh":"throw it away 指浪費或丟棄本來有用的東西。"},{"en":"A family throws away food if it buys too much and lets it spoil.","zh":"如果家庭買太多食物並讓它變壞，就是把食物浪費掉。"},{"en":"Throwing away rainwater can increase flooding and increase dependence on imported water.","zh":"白白排走雨水可以增加水浸，並增加對入口水源的依賴。"},{"en":"This phrase criticises waste.","zh":"這個短語批評浪費。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":18},{"front":"import water","meaning":"入口水；引入外來水源","examples":[{"en":"Los Angeles spends hundreds of millions to import water.","zh":"洛杉磯花費數億美元入口水源。"},{"en":"To import water means to bring water into a place from outside sources.","zh":"import water 指從外部水源把水帶入某地。"},{"en":"A dry island may import water when local wells cannot meet demand.","zh":"當本地水井無法滿足需求，乾旱島嶼可能入口水源。"},{"en":"Importing water can be expensive and less sustainable than storing local rain.","zh":"入口水可能昂貴，且比儲存本地雨水較不持續。"},{"en":"This phrase describes bringing in water from elsewhere.","zh":"這個短語描述從其他地方引入水。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":19},{"front":"environmentalist","meaning":"環保人士","examples":[{"en":"Andy Lipkis is an environmentalist in Los Angeles.","zh":"Andy Lipkis 是洛杉磯的一名環保人士。"},{"en":"An environmentalist is someone who works to protect nature, ecosystems, or the environment.","zh":"environmentalist 指致力保護自然、生態系統或環境的人。"},{"en":"An environmentalist may campaign for cleaner rivers and more trees in cities.","zh":"環保人士可能倡議更清潔河流和城市更多樹木。"},{"en":"Environmentalists often challenge policies that waste resources or damage habitats.","zh":"環保人士常挑戰浪費資源或破壞棲息地的政策。"},{"en":"This word describes a person concerned with environmental protection.","zh":"這個詞描述關注環境保護的人。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":19},{"front":"citizen groups","meaning":"公民團體","examples":[{"en":"Citizen groups want Los Angeles to hold onto its floodwater.","zh":"公民團體希望洛杉磯留住洪水。"},{"en":"Citizen groups are organised groups of ordinary residents working on public issues.","zh":"citizen groups 指由普通居民組成、處理公共議題的組織。"},{"en":"A citizen group may ask the local council for safer crossings near schools.","zh":"公民團體可能要求地方議會在學校附近設更安全過路處。"},{"en":"Citizen groups can push authorities to test ideas that officials may overlook.","zh":"公民團體可以推動當局測試官員可能忽略的想法。"},{"en":"This phrase refers to community-based public action groups.","zh":"這個短語指以社區為基礎的公共行動團體。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":19},{"front":"beat the urban flood hazard","meaning":"應對城市水災風險","examples":[{"en":"Lipkis wants to beat the urban flood hazard by storing rainwater.","zh":"Lipkis 希望透過儲存雨水來應對城市水災風險。"},{"en":"To beat the urban flood hazard means to overcome or reduce the danger of flooding in a city.","zh":"beat the urban flood hazard 指克服或減少城市水浸危險。"},{"en":"A city can beat flood risk by using parks, permeable streets, and rainwater tanks.","zh":"城市可以透過公園、透水街道和雨水缸來應對水災風險。"},{"en":"If rainwater is stored instead of rushed away, urban flooding may fall.","zh":"如果雨水被儲存而不是急速排走，城市水浸可能減少。"},{"en":"This phrase describes solving a city flood problem.","zh":"這個短語描述解決城市水災問題。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":19},{"front":"urban flood hazard","meaning":"城市水災風險","examples":[{"en":"The urban flood hazard remains a serious problem in Los Angeles.","zh":"城市水災風險仍是洛杉磯的嚴重問題。"},{"en":"Urban flood hazard means the risk of flooding in built-up city areas.","zh":"urban flood hazard 指建成城市地區的水浸風險。"},{"en":"Paved roads and roofs increase urban flood hazard because rain cannot soak into the ground.","zh":"鋪面道路和屋頂會增加城市水災風險，因為雨水不能滲入地下。"},{"en":"If drains overflow, urban flood hazards can damage shops, homes, and transport.","zh":"如果排水渠溢出，城市水災風險可以損害商店、房屋和交通。"},{"en":"This phrase focuses on flood risk in cities.","zh":"這個短語著重城市中的水災風險。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":19},{"front":"fill the taps","meaning":"供應自來水","examples":[{"en":"The plan aims to reduce flooding and fill the taps.","zh":"該計劃旨在減少水浸並供應自來水。"},{"en":"To fill the taps means to provide water for daily use in homes and buildings.","zh":"fill the taps 指為住宅和建築物提供日常用水。"},{"en":"A town may collect rainwater to help fill the taps during dry months.","zh":"城鎮可能收集雨水，以在乾旱月份幫助供應自來水。"},{"en":"Stored floodwater can become a water supply if it is treated properly.","zh":"如果經適當處理，儲存的洪水可以成為水源。"},{"en":"This phrase connects flood control with water supply.","zh":"這個短語把防洪與供水連繫起來。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":19},{"front":"hold onto floodwater","meaning":"留住洪水","examples":[{"en":"The city could hold onto floodwater instead of throwing it away.","zh":"該市可以留住洪水，而不是把它白白排走。"},{"en":"To hold onto floodwater means to keep and store floodwater rather than quickly drain it away.","zh":"hold onto floodwater 指保留和儲存洪水，而不是迅速排走。"},{"en":"A park basin can hold onto floodwater during storms and release it slowly later.","zh":"公園蓄水盆可以在風暴期間留住洪水，之後慢慢釋放。"},{"en":"Holding onto water can reduce floods and increase water reserves.","zh":"留住水可以減少水浸並增加水儲備。"},{"en":"This phrase describes storage instead of disposal.","zh":"這個短語描述儲存，而不是排走。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":19},{"front":"not just a pipe dream","meaning":"並非不切實際的空想","examples":[{"en":"The porous-city idea is not just a pipe dream.","zh":"海綿城市概念並非不切實際的空想。"},{"en":"Not just a pipe dream means not merely an unrealistic or impossible idea.","zh":"not just a pipe dream 指不只是幻想式或不可能的想法。"},{"en":"A school garden may sound ambitious, but it is not just a pipe dream if parents and teachers have funding.","zh":"學校花園聽起來很有野心，但如果家長和老師有資金，它就不是空想。"},{"en":"A plan becomes realistic when money, rules, and testing are in place.","zh":"當金錢、規則和試驗到位，計劃就會變得現實。"},{"en":"This phrase defends an idea as possible.","zh":"這個短語為某想法的可行性辯護。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":19},{"front":"the authorities","meaning":"當局","examples":[{"en":"The authorities launched a scheme to test the idea.","zh":"當局推出計劃來測試這個想法。"},{"en":"The authorities are the official organisations or people with power to make decisions.","zh":"authorities 指有權作決策的官方組織或人士。"},{"en":"The authorities may close roads when floodwater makes driving unsafe.","zh":"當洪水令駕駛不安全，當局可能封路。"},{"en":"Official action matters because large public projects need approval and funding.","zh":"官方行動很重要，因為大型公共項目需要批准和資金。"},{"en":"This phrase refers to government or official bodies.","zh":"這個短語指政府或官方機構。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":19},{"front":"launch a scheme","meaning":"推出計劃","examples":[{"en":"The authorities launched a $100 million scheme in Sun Valley.","zh":"當局在 Sun Valley 推出一項一億美元計劃。"},{"en":"To launch a scheme means to start an organised plan or programme.","zh":"launch a scheme 指開始一個有組織的計劃或項目。"},{"en":"A school may launch a reading scheme to help weaker students.","zh":"學校可能推出閱讀計劃來幫助較弱學生。"},{"en":"Launching a scheme shows that an idea is moving from discussion to action.","zh":"推出計劃顯示一個想法正從討論走向行動。"},{"en":"This phrase describes the official start of a project.","zh":"這個短語描述項目的正式開始。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":19},{"front":"road-test the porous city","meaning":"試行海綿城市概念","examples":[{"en":"The scheme will road-test the porous city in Sun Valley.","zh":"該計劃會在 Sun Valley 試行海綿城市概念。"},{"en":"To road-test the porous city means to try the porous-city idea in a real place to see whether it works.","zh":"road-test the porous city 指在真實地方試驗海綿城市想法，看看是否有效。"},{"en":"A school may road-test a new timetable with one year group before using it everywhere.","zh":"學校可能先用一個年級試行新時間表，再全面採用。"},{"en":"Testing an idea in real conditions reveals problems that theory may miss.","zh":"在真實環境測試想法，可以揭示理論可能錯過的問題。"},{"en":"This phrase means practical trial, not literally testing a road.","zh":"這個短語指實際試行，而不是真的測試道路。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":20},{"front":"flood-hit community","meaning":"受水災影響的社區","examples":[{"en":"Sun Valley is a flood-hit community in Los Angeles.","zh":"Sun Valley 是洛杉磯一個受水災影響的社區。"},{"en":"A flood-hit community is a neighbourhood or group of people seriously affected by flooding.","zh":"flood-hit community 指嚴重受水災影響的社區或人群。"},{"en":"A flood-hit community may need shelters, repairs, and help replacing damaged furniture.","zh":"受水災影響的社區可能需要庇護所、維修和更換受損家具的協助。"},{"en":"Repeated floods can make residents anxious whenever heavy rain is forecast.","zh":"反覆水災可以令居民每逢預測大雨就焦慮。"},{"en":"This phrase identifies a community damaged by floods.","zh":"這個短語指出受水災破壞的社區。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":20},{"front":"catch the rain that falls on","meaning":"收集落在……上的雨水","examples":[{"en":"The plan is to catch the rain that falls on driveways, parking lots and rooftops.","zh":"該計劃是收集落在私家車道、停車場和屋頂上的雨水。"},{"en":"To catch the rain that falls on a surface means to collect rainwater from that surface.","zh":"catch the rain that falls on a surface 指從某表面收集雨水。"},{"en":"A school can catch the rain that falls on its roof and use it for the garden.","zh":"學校可以收集落在屋頂上的雨水，用於花園。"},{"en":"Catching rain reduces runoff and turns stormwater into a resource.","zh":"收集雨水可以減少地表徑流，並把暴雨水變成資源。"},{"en":"This phrase describes rainwater collection.","zh":"這個短語描述雨水收集。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":20},{"front":"driveways","meaning":"私家車道","examples":[{"en":"The scheme collects rainwater from thousands of driveways.","zh":"該計劃從數以千計私家車道收集雨水。"},{"en":"Driveways are short private roads or paved areas where cars enter or park beside homes.","zh":"driveways 指住宅旁讓汽車進入或停泊的短私人道路或鋪面區。"},{"en":"Rain falling on driveways often runs quickly into street drains.","zh":"落在私家車道上的雨常迅速流入街道排水渠。"},{"en":"Permeable driveways can reduce flooding by letting water soak into the ground.","zh":"透水私家車道可以讓水滲入地下，減少水浸。"},{"en":"This word refers to vehicle access areas near buildings.","zh":"這個詞指建築物附近的車輛出入區。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":20},{"front":"parking lots","meaning":"停車場","examples":[{"en":"Rainwater can be collected from parking lots.","zh":"雨水可以從停車場收集。"},{"en":"Parking lots are open areas where many cars can be parked.","zh":"parking lots 指可停泊多部汽車的露天區域。"},{"en":"A shopping centre parking lot may flood quickly if the surface is sealed with asphalt.","zh":"如果購物中心停車場用瀝青封閉地面，可能很快水浸。"},{"en":"Large paved parking lots create runoff because rain cannot soak into the ground.","zh":"大型鋪面停車場會產生徑流，因為雨水不能滲入地下。"},{"en":"This phrase refers to car-parking areas, often with hard surfaces.","zh":"這個短語指汽車停泊區，通常有硬表面。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":20},{"front":"rooftops","meaning":"屋頂","examples":[{"en":"Homes and public buildings can capture water from rooftops.","zh":"住宅和公共建築物可以從屋頂收集水。"},{"en":"Rooftops are the upper outside surfaces of buildings.","zh":"rooftops 指建築物最上方的外部表面。"},{"en":"A house can collect rain from rooftops through gutters and storage tanks.","zh":"房屋可以透過水槽和儲水箱收集屋頂雨水。"},{"en":"Rooftop water collection reduces pressure on street drains during storms.","zh":"屋頂集水可以在風暴期間減少街道排水渠壓力。"},{"en":"This word refers to roofs as surfaces that receive rain.","zh":"這個詞指作為接收雨水表面的屋頂。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":20},{"front":"soak up water","meaning":"吸收水分","examples":[{"en":"Trees will soak up water from parking lots.","zh":"樹木會吸收停車場的水分。"},{"en":"To soak up water means to absorb water into soil, plants, or material.","zh":"soak up water 指把水吸收到土壤、植物或材料中。"},{"en":"A sponge soaks up water spilled on a kitchen table.","zh":"海綿會吸收廚房桌上灑出的水。"},{"en":"Trees and soil can soak up rainwater before it becomes street flooding.","zh":"樹木和土壤可以在雨水變成街道水浸前吸收它。"},{"en":"This phrase describes absorption rather than drainage.","zh":"這個短語描述吸收，而不是排水。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":20},{"front":"capture roof water","meaning":"收集屋頂雨水","examples":[{"en":"Homes and public buildings will capture roof water.","zh":"住宅和公共建築物會收集屋頂雨水。"},{"en":"To capture roof water means to collect rainwater that falls on roofs.","zh":"capture roof water 指收集落在屋頂上的雨水。"},{"en":"A family may capture roof water in a tank to water plants.","zh":"家庭可能把屋頂雨水收集到水箱中，用來澆花。"},{"en":"Capturing roof water reduces runoff and can provide useful stored water.","zh":"收集屋頂雨水可以減少徑流並提供有用儲水。"},{"en":"This phrase describes collecting rain from roof surfaces.","zh":"這個短語描述從屋頂表面收集雨水。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":20},{"front":"public buildings","meaning":"公共建築物","examples":[{"en":"Public buildings can capture roof water for irrigation.","zh":"公共建築物可以收集屋頂雨水作灌溉。"},{"en":"Public buildings are buildings used by the community or government, such as schools, libraries, and offices.","zh":"public buildings 指由社區或政府使用的建築物，例如學校、圖書館和辦公室。"},{"en":"A public library may collect rainwater from its roof to water nearby trees.","zh":"公共圖書館可能從屋頂收集雨水來灌溉附近樹木。"},{"en":"Public buildings can lead by example because many people see and use them.","zh":"公共建築物可以以身作則，因為很多人會看到和使用它們。"},{"en":"This phrase refers to buildings serving the public.","zh":"這個短語指服務公眾的建築物。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":20},{"front":"road drains","meaning":"道路排水渠","examples":[{"en":"Road drains will empty into old gravel pits.","zh":"道路排水渠會流入舊礫石坑。"},{"en":"Road drains are drainage systems beside or under roads that collect rainwater.","zh":"road drains 指道路旁或道路下收集雨水的排水系統。"},{"en":"Blocked road drains can flood a street during a storm.","zh":"堵塞的道路排水渠可以在風暴期間令街道水浸。"},{"en":"If road drains lead to storage areas, rainwater can be kept instead of wasted.","zh":"如果道路排水渠通往儲水區，雨水就可以被保留而不是浪費。"},{"en":"This phrase refers to drainage for roads.","zh":"這個短語指道路排水設施。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":20},{"front":"empty into","meaning":"流入","examples":[{"en":"Road drains will empty into gravel pits and other leaky places.","zh":"道路排水渠會流入礫石坑和其他滲水地點。"},{"en":"To empty into a place means to flow or discharge into it.","zh":"empty into a place 指流入或排入某地。"},{"en":"A kitchen sink may empty into a drain under the floor.","zh":"廚房水槽可能流入地板下的排水渠。"},{"en":"Where drains empty matters because water can either be wasted or stored.","zh":"排水渠流向哪裡很重要，因為水可以被浪費，也可以被儲存。"},{"en":"This phrase describes where water goes after leaving a channel.","zh":"這個短語描述水離開水道後去向哪裡。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":21},{"front":"gravel pits","meaning":"礫石坑","examples":[{"en":"Old gravel pits can help water seep underground.","zh":"舊礫石坑可以幫助水滲入地下。"},{"en":"Gravel pits are holes or excavated areas where gravel has been removed from the ground.","zh":"gravel pits 指從地下挖走礫石後留下的坑洞或挖掘區。"},{"en":"An old gravel pit may collect rainwater and let it slowly soak into the soil.","zh":"舊礫石坑可能收集雨水，並讓它慢慢滲入土壤。"},{"en":"Gravel pits can become useful storage places if they are planned safely.","zh":"如果安全規劃，礫石坑可以成為有用儲水地點。"},{"en":"This phrase refers to former extraction holes with loose stone.","zh":"這個短語指曾用來開採礫石的坑洞。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":21},{"front":"leaky places","meaning":"滲水地點","examples":[{"en":"Leaky places can help recharge underground water reserves.","zh":"滲水地點可以幫助補充地下水儲備。"},{"en":"Leaky places are areas where water can seep through the ground instead of staying on the surface.","zh":"leaky places 指水能穿過地面滲入地下，而不是停留在表面的區域。"},{"en":"A gravel path is more leaky than a concrete pavement because water can pass through it.","zh":"礫石小路比混凝土行人路更能滲水，因為水可以通過。"},{"en":"Leaky ground reduces runoff and helps refill underground water.","zh":"可滲水地面會減少徑流並幫助補充地下水。"},{"en":"This phrase describes permeable areas, not broken pipes.","zh":"這個短語描述可滲透區域，而不是破裂水管。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":21},{"front":"recharge underground water reserves","meaning":"補充地下水儲備","examples":[{"en":"Leaky places should recharge the city’s underground water reserves.","zh":"滲水地點應補充城市地下水儲備。"},{"en":"To recharge underground water reserves means to refill stored groundwater by letting water soak down.","zh":"recharge underground water reserves 指讓水滲入地下，以補充儲存的地下水。"},{"en":"A town can recharge underground water reserves by protecting open soil and wetlands.","zh":"城鎮可以透過保護裸露土壤和濕地來補充地下水儲備。"},{"en":"Recharged groundwater can support wells during dry periods.","zh":"得到補充的地下水可以在乾旱時期支持水井。"},{"en":"This phrase describes restoring hidden water supplies underground.","zh":"這個短語描述恢復地下隱藏水源。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":21},{"front":"underground water reserves","meaning":"地下水儲備","examples":[{"en":"The city’s underground water reserves can be refilled by captured rainwater.","zh":"城市地下水儲備可以由收集到的雨水補充。"},{"en":"Underground water reserves are stores of water beneath the ground.","zh":"underground water reserves 指地底下儲存的水。"},{"en":"Villages may depend on underground water reserves when rivers dry up.","zh":"當河流乾涸，村莊可能依賴地下水儲備。"},{"en":"If groundwater is not recharged, wells may become unreliable.","zh":"如果地下水沒有補充，水井可能變得不可靠。"},{"en":"This phrase refers to hidden water supplies below the surface.","zh":"這個短語指地表以下的隱藏水源。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":21},{"front":"less flooding and more water","meaning":"水浸減少、水源增加","examples":[{"en":"The result should be less flooding and more water for the city.","zh":"結果應該是城市水浸減少、水源增加。"},{"en":"Less flooding and more water means reduced flood damage and increased usable water supply.","zh":"less flooding and more water 指水災損害減少，並增加可用水源。"},{"en":"A rain garden can bring less flooding and more water for plants in a schoolyard.","zh":"雨水花園可以令校園水浸減少，並為植物提供更多水。"},{"en":"Capturing rainwater can solve two problems at once: too much water during storms and too little water later.","zh":"收集雨水可以同時解決兩個問題：風暴時水太多，之後水太少。"},{"en":"This phrase summarises the double benefit of porous-city planning.","zh":"這個短語總結海綿城市規劃的雙重好處。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":21},{"front":"have room to flood naturally","meaning":"有空間自然氾濫","examples":[{"en":"Every river should have room to flood naturally.","zh":"每條河流都應有空間自然氾濫。"},{"en":"To have room to flood naturally means to have nearby land where floodwater can spread safely.","zh":"have room to flood naturally 指附近有土地讓洪水安全擴散。"},{"en":"A river with open fields beside it has room to flood naturally during heavy rain.","zh":"河邊有開闊田野的河流，在大雨時有空間自然氾濫。"},{"en":"Natural flooding becomes dangerous when buildings occupy the space water needs.","zh":"當建築物佔用水所需空間，自然氾濫就會變得危險。"},{"en":"This phrase describes giving rivers safe overflow space.","zh":"這個短語描述給河流安全溢流空間。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":21},{"front":"build its own defences","meaning":"建立自身防線","examples":[{"en":"Every coastline should be left to build its own defences.","zh":"每條海岸線都應被留下來建立自身防線。"},{"en":"To build its own defences means to develop natural protection, such as dunes, marshes, or beaches.","zh":"build its own defences 指發展沙丘、沼澤或海灘等自然保護。"},{"en":"A beach can build its own defences when sand and plants are allowed to form dunes.","zh":"當沙和植物被允許形成沙丘，海灘就能建立自身防線。"},{"en":"Natural defences can absorb waves more flexibly than concrete walls.","zh":"自然防線可以比混凝土牆更有彈性地吸收海浪。"},{"en":"This phrase describes protection created by natural processes.","zh":"這個短語描述由自然過程建立的保護。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":21},{"front":"expensive and utopian","meaning":"昂貴而烏托邦式的","examples":[{"en":"The plan sounds expensive and utopian at first.","zh":"該計劃起初聽起來昂貴而烏托邦式。"},{"en":"Expensive and utopian means costly and idealistic, perhaps sounding unrealistic.","zh":"expensive and utopian 指成本高且理想化，可能聽起來不切實際。"},{"en":"A proposal to turn every car park into a park may sound expensive and utopian.","zh":"把每個停車場變成公園的提議可能聽起來昂貴而烏托邦式。"},{"en":"Some ambitious ideas seem unrealistic before pilot projects prove them possible.","zh":"有些有雄心的想法在試點項目證明可行前，看似不現實。"},{"en":"This phrase describes a plan that may look too costly and idealistic.","zh":"這個短語描述可能看起來太昂貴且太理想化的計劃。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":21},{"front":"protect our watery margins","meaning":"保護臨水邊緣地帶","examples":[{"en":"Societies spend huge sums trying to protect their watery margins.","zh":"社會花費巨額資金試圖保護臨水邊緣地帶。"},{"en":"Watery margins are edges of land near rivers, lakes, seas, or flood-prone water areas.","zh":"watery margins 指靠近河流、湖泊、海洋或易受水災影響水域的土地邊緣。"},{"en":"A coastal town protects its watery margins with dunes, wetlands, or sea walls.","zh":"沿海城鎮會用沙丘、濕地或海堤保護臨水邊緣地帶。"},{"en":"People often build on watery margins because water brings trade, beauty, and transport.","zh":"人們常在臨水地帶建設，因為水帶來貿易、美景和交通。"},{"en":"This phrase describes vulnerable land-water edges.","zh":"這個短語描述脆弱的水陸交界地帶。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":21},{"front":"how bad we are at it","meaning":"我們在這方面做得多差","examples":[{"en":"The article argues that we spend a lot on flood control but are bad at it.","zh":"文章認為我們在防洪上花很多錢，但在這方面做得很差。"},{"en":"How bad we are at it means how poorly we perform at that task.","zh":"how bad we are at it 指我們在某任務上的表現有多差。"},{"en":"If a school buys expensive software but students still cannot use it, people may ask how bad we are at planning technology.","zh":"如果學校買昂貴軟件但學生仍不能使用，人們可能會問我們在科技規劃上做得多差。"},{"en":"Spending money does not prove skill if the results remain poor.","zh":"如果結果仍差，花錢不代表有能力。"},{"en":"This phrase criticises failure despite effort or expense.","zh":"這個短語批評即使投入努力或金錢仍然失敗。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":22},{"front":"Reading Passage 2","meaning":"閱讀篇章二","examples":[{"en":"Reading Passage 2 has seven paragraphs.","zh":"閱讀篇章二有七段。"},{"en":"Reading Passage 2 means the second reading text in a test or exercise.","zh":"Reading Passage 2 指測驗或練習中的第二篇閱讀文章。"},{"en":"Students should check the title and paragraph structure before answering Reading Passage 2.","zh":"學生回答閱讀篇章二前，應檢查標題和段落結構。"},{"en":"Knowing which passage is being used prevents answers from being taken from the wrong text.","zh":"知道正在使用哪篇文章，可以避免從錯誤文本中取答案。"},{"en":"This phrase identifies a specific reading section.","zh":"這個短語指出特定閱讀部分。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":22},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"The question asks which paragraph contains the following information.","zh":"題目問哪一段包含以下資料。"},{"en":"Which paragraph contains means students must find the paragraph where certain information appears.","zh":"which paragraph contains 指學生必須找出某資料出現在哪一段。"},{"en":"In a reading test, students may scan for names, numbers, or key ideas to see which paragraph contains the answer.","zh":"在閱讀測驗中，學生可能掃讀人名、數字或關鍵概念，以判斷哪段包含答案。"},{"en":"This task checks location skills, not only general understanding.","zh":"這類題目測試定位能力，而不只是一般理解。"},{"en":"This phrase is common in matching-information questions.","zh":"這個短語常見於資料配對題。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":22},{"front":"the following information","meaning":"以下資料","examples":[{"en":"Students must match each statement with the paragraph containing the following information.","zh":"學生必須把每個陳述與包含以下資料的段落配對。"},{"en":"The following information means the details listed after the instruction.","zh":"following information 指指示後列出的資料細節。"},{"en":"Students should read the following information carefully before scanning the passage.","zh":"學生在掃讀文章前，應仔細閱讀以下資料。"},{"en":"Misreading the information can lead students to the wrong paragraph.","zh":"誤讀資料可能令學生找錯段落。"},{"en":"This phrase introduces the details students need to locate.","zh":"這個短語引入學生需要定位的細節。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":22},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Students write the correct letter in the answer box.","zh":"學生在答案格中寫上正確字母。"},{"en":"To write the correct letter means to record the letter that matches the right paragraph or option.","zh":"write the correct letter 指寫下與正確段落或選項相配的字母。"},{"en":"A student may know the answer but lose marks by writing B instead of D.","zh":"學生可能知道答案，但因把 D 寫成 B 而失分。"},{"en":"Careful copying is important in answer boxes.","zh":"在答案格中仔細抄寫很重要。"},{"en":"This phrase focuses on answer format.","zh":"這個短語著重答案格式。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":22},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Answers should be written on the answer sheet.","zh":"答案應寫在答題紙上。"},{"en":"On your answer sheet means in the official place where exam answers must be recorded.","zh":"on your answer sheet 指在考試答案必須記錄的正式位置。"},{"en":"Students may solve questions in the booklet but must copy final answers onto the answer sheet.","zh":"學生可以在題本中解題，但必須把最終答案抄到答題紙上。"},{"en":"If answers are not on the answer sheet, they may not be marked.","zh":"如果答案不在答題紙上，可能不會被評改。"},{"en":"This phrase gives an exam-format instruction.","zh":"這個短語給出考試格式指示。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":22},{"front":"a new approach carried out in","meaning":"在……實施的新方法","examples":[{"en":"The question refers to a new approach carried out in the UK.","zh":"題目指在英國實施的新方法。"},{"en":"A new approach carried out in a place means a different method that is actually being used there.","zh":"new approach carried out in a place 指在某地實際使用的不同方法。"},{"en":"A new teaching approach carried out in one school may later spread to others.","zh":"在一所學校實施的新教學方法，之後可能擴展到其他學校。"},{"en":"Real examples show whether a new approach works outside theory.","zh":"真實例子顯示新方法在理論以外是否有效。"},{"en":"This phrase links a method with the place where it is practised.","zh":"這個短語把方法與其實施地點連繫起來。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":22},{"front":"straightened rivers","meaning":"被拉直的河流","examples":[{"en":"The question asks why straightened rivers and dykes can fail.","zh":"題目問為何被拉直的河流和防洪堤可能失效。"},{"en":"Straightened rivers are rivers whose natural bends have been removed to make them flow more directly.","zh":"straightened rivers 指自然彎道被移除、令其更直接流動的河流。"},{"en":"A straightened river may look tidy but send water downstream faster.","zh":"被拉直的河流可能看起來整齊，但會更快把水送往下游。"},{"en":"Removing bends can reduce natural slowing and increase flood risk.","zh":"移除彎道會減少自然減速作用並增加水災風險。"},{"en":"This phrase describes human modification of river shape.","zh":"這個短語描述人為改變河流形狀。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":22},{"front":"an apparently unrealistic alternative plan","meaning":"表面上不切實際的替代方案","examples":[{"en":"The question mentions an apparently unrealistic alternative plan for Los Angeles.","zh":"題目提到洛杉磯一個表面上不切實際的替代方案。"},{"en":"An apparently unrealistic alternative plan is another proposal that seems impractical at first.","zh":"apparently unrealistic alternative plan 指一開始看起來不實際的另一個提議。"},{"en":"Turning car parks into rain gardens may seem like an unrealistic alternative until a pilot project works.","zh":"把停車場變成雨水花園可能像不切實際的替代方案，直到試點成功。"},{"en":"Some plans look unrealistic because people are used to old methods.","zh":"有些計劃看似不現實，是因為人們習慣舊方法。"},{"en":"This phrase describes a doubtful-looking Plan B.","zh":"這個短語描述看起來令人懷疑的乙方案。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":22},{"front":"the traditional approach to","meaning":"……的傳統方法","examples":[{"en":"One question asks about the traditional approach to flood control.","zh":"一題問及防洪的傳統方法。"},{"en":"The traditional approach to something is the older, usual way of dealing with it.","zh":"traditional approach to something 指處理某事的舊有、慣常方法。"},{"en":"The traditional approach to teaching vocabulary is often memorising word lists.","zh":"教詞彙的傳統方法通常是背單字表。"},{"en":"Traditional approaches may work in some cases but fail when conditions change.","zh":"傳統方法在某些情況下可能有效，但當條件改變就可能失敗。"},{"en":"This phrase contrasts old methods with newer alternatives.","zh":"這個短語把舊方法與新替代方案作對比。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":22},{"front":"flood control","meaning":"防洪；治水","examples":[{"en":"The passage compares traditional flood control with natural flood management.","zh":"文章把傳統防洪與自然防洪管理作比較。"},{"en":"Flood control means actions taken to prevent or reduce damage from floods.","zh":"flood control 指為防止或減少水災損害而採取的行動。"},{"en":"Flood control may include drains, river banks, wetlands, warning systems, and evacuation plans.","zh":"防洪可以包括排水渠、河岸、濕地、警報系統和撤離計劃。"},{"en":"Good flood control protects people without simply moving danger downstream.","zh":"良好防洪會保護人們，而不是單純把危險推到下游。"},{"en":"This phrase refers to managing flood risk.","zh":"這個短語指管理水災風險。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":23},{"front":"flood-management efforts","meaning":"防洪管理工作","examples":[{"en":"The question refers to flood-management efforts in the Netherlands and Germany.","zh":"題目指荷蘭和德國的防洪管理工作。"},{"en":"Flood-management efforts are actions or projects designed to control or reduce flood risk.","zh":"flood-management efforts 指設計用來控制或減少水災風險的行動或項目。"},{"en":"A city’s flood-management efforts may include clearing drains and restoring parks that store water.","zh":"城市的防洪管理工作可能包括清理排水渠和修復可儲水公園。"},{"en":"Such efforts can fail if they ignore the whole landscape.","zh":"如果忽視整個地貌，這些工作可能失敗。"},{"en":"This phrase describes organised attempts to deal with flooding.","zh":"這個短語描述有組織地處理水災的嘗試。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":23},{"front":"benefit three countries","meaning":"惠及三個國家","examples":[{"en":"The river project can benefit three countries.","zh":"該河流項目可以惠及三個國家。"},{"en":"To benefit three countries means to help or bring advantages to three different countries.","zh":"benefit three countries 指幫助或為三個不同國家帶來好處。"},{"en":"A clean-river project can benefit three countries if the river crosses all their borders.","zh":"如果河流跨越三國邊界，清潔河流項目可以惠及三個國家。"},{"en":"River management often has cross-border benefits because water flows beyond one nation.","zh":"河流管理常有跨境好處，因為水流超越一個國家。"},{"en":"This phrase stresses wide regional advantage.","zh":"這個短語強調廣泛地區利益。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":23},{"front":"agree with the information given","meaning":"與文中資料一致","examples":[{"en":"Students decide whether the statements agree with the information given in the passage.","zh":"學生判斷陳述是否與文中資料一致。"},{"en":"Agree with the information given means match what the passage says.","zh":"agree with the information given 指符合文章所說內容。"},{"en":"In a reading test, a statement must agree with the information given, not with the student’s outside knowledge.","zh":"在閱讀測驗中，陳述必須與文中資料一致，而不是與學生外部知識一致。"},{"en":"Students should check exact wording before choosing TRUE.","zh":"學生在選 TRUE 前應檢查準確措辭。"},{"en":"This phrase is common in TRUE, FALSE, NOT GIVEN tasks.","zh":"這個短語常見於 TRUE、FALSE、NOT GIVEN 題。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":23},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"FALSE 陳述與文章資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the passage says.","zh":"contradict the information 指說法與文章內容相反。"},{"en":"If the text says floods increased, a statement saying they decreased contradicts the information.","zh":"如果文章說水災增加，而陳述說水災減少，就是與資料相矛盾。"},{"en":"Students should choose FALSE only when there is clear conflict.","zh":"只有在明確衝突時，學生才應選 FALSE。"},{"en":"This phrase describes direct disagreement with the text.","zh":"這個短語描述與文本直接不一致。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":23},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"Students choose NOT GIVEN when there is no information on this.","zh":"當沒有相關資料時，學生選 NOT GIVEN。"},{"en":"No information on this means the passage does not say whether the statement is true or false.","zh":"no information on this 指文章沒有說明該陳述是真還是假。"},{"en":"If a passage describes floods but not insurance costs, there is no information on insurance.","zh":"如果文章描述水災但沒有提到保險成本，就沒有保險相關資料。"},{"en":"Students should not guess from common sense when the text gives no evidence.","zh":"當文本沒有證據時，學生不應靠常識猜測。"},{"en":"This phrase signals that the passage does not support a decision.","zh":"這個短語表示文章不支持作出判斷。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":23},{"front":"in the past","meaning":"在過去","examples":[{"en":"One statement describes what Europeans did in the past.","zh":"一個陳述描述歐洲人在過去做過甚麼。"},{"en":"In the past means in an earlier time before now.","zh":"in the past 指在現在之前的較早時期。"},{"en":"In the past, many students wrote essays by hand instead of typing them.","zh":"在過去，許多學生手寫作文，而不是打字。"},{"en":"Past habits can explain why current systems still look old-fashioned.","zh":"過去習慣可以解釋為何現有制度仍看起來過時。"},{"en":"This phrase contrasts earlier times with the present.","zh":"這個短語把較早時期與現在作對比。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":23},{"front":"make floods less severe","meaning":"令水災沒那麼嚴重","examples":[{"en":"The statement claims that river-bank improvements made floods less severe.","zh":"該陳述聲稱河岸改善令水災沒那麼嚴重。"},{"en":"To make floods less severe means to reduce their strength, height, damage, or frequency.","zh":"make floods less severe 指減少水災的強度、高度、損害或頻率。"},{"en":"Wetlands can make floods less severe by holding water upstream.","zh":"濕地可以透過在上游蓄水令水災沒那麼嚴重。"},{"en":"Some engineering works may fail to make floods less severe if they speed up river flow.","zh":"如果某些工程令河水加快，它們可能無法令水災沒那麼嚴重。"},{"en":"This phrase describes reducing flood seriousness.","zh":"這個短語描述減低水災嚴重性。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":23},{"front":"cause faster flows","meaning":"導致水流加快","examples":[{"en":"Shortened rivers can cause faster flows.","zh":"被縮短的河流可以導致水流加快。"},{"en":"To cause faster flows means to make water move more quickly.","zh":"cause faster flows 指令水移動得更快。"},{"en":"A straight concrete channel can cause faster flows than a winding natural stream.","zh":"筆直混凝土水道可以比蜿蜒天然溪流導致更快水流。"},{"en":"Faster flows may increase downstream flood risk because water arrives sooner.","zh":"更快水流可能增加下游水災風險，因為水更早到達。"},{"en":"This phrase links river design with water speed.","zh":"這個短語把河流設計與水速連繫起來。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":23},{"front":"greater damage to","meaning":"對……造成更大破壞","examples":[{"en":"Faster river flows may lead to greater damage to buildings on flood plains.","zh":"更快河流流速可能對洪泛平原上的建築造成更大破壞。"},{"en":"Greater damage to something means more serious harm to it.","zh":"greater damage to something 指對某物造成更嚴重傷害。"},{"en":"A stronger storm can cause greater damage to roofs and windows.","zh":"更強風暴可以對屋頂和窗戶造成更大破壞。"},{"en":"When water flows faster, it can hit buildings with more force.","zh":"當水流更快，它可以以更大力量撞擊建築物。"},{"en":"This phrase compares the level of harm.","zh":"這個短語比較傷害程度。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":23},{"front":"better than","meaning":"比……更好","examples":[{"en":"One statement compares whether the UK’s approach is better than Austria’s.","zh":"一個陳述比較英國的方法是否比奧地利的方法更好。"},{"en":"Better than means superior to another thing in quality, effectiveness, or suitability.","zh":"better than 指在質素、效果或適合程度上優於另一事物。"},{"en":"Walking may be better than driving for short journeys in a crowded city.","zh":"在擠迫城市中，短途步行可能比駕車更好。"},{"en":"One flood plan may be better than another if it protects more people at lower cost.","zh":"如果一個防洪計劃能以較低成本保護更多人，就可能比另一個更好。"},{"en":"This phrase is used for comparison.","zh":"這個短語用於比較。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":24},{"front":"at least","meaning":"至少","examples":[{"en":"The statement says that at least 300,000 people were evacuated.","zh":"該陳述說至少三十萬人被撤離。"},{"en":"At least means no less than a particular amount.","zh":"at least 指不少於某個數量。"},{"en":"Students should sleep at least seven hours before an important exam.","zh":"學生在重要考試前應至少睡七小時。"},{"en":"If officials say at least 300 homes were damaged, the final number may be higher.","zh":"如果官員說至少三百間房屋受損，最終數字可能更高。"},{"en":"This phrase gives a minimum number or level.","zh":"這個短語給出最低數字或程度。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":24},{"front":"complete the sentences below","meaning":"完成以下句子","examples":[{"en":"The task asks students to complete the sentences below.","zh":"題目要求學生完成以下句子。"},{"en":"To complete the sentences below means to fill in missing words in the sentences that follow.","zh":"complete the sentences below 指填入下方句子中的缺失字詞。"},{"en":"Students should read the whole sentence before choosing an answer.","zh":"學生選答案前應閱讀整句。"},{"en":"Grammar helps decide whether the missing word should be a noun, verb, or adjective.","zh":"文法有助判斷缺失字應是名詞、動詞還是形容詞。"},{"en":"This phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":24},{"front":"no more than two words","meaning":"不多於兩個字","examples":[{"en":"Students must choose no more than two words from the passage.","zh":"學生必須從篇章中選擇不多於兩個字。"},{"en":"No more than two words means one or two words, but not three.","zh":"no more than two words 指一個或兩個詞，但不是三個。"},{"en":"If the answer limit is no more than two words, “flood plains” is allowed.","zh":"如果答案限制是不多於兩個詞，“flood plains” 是可以的。"},{"en":"Writing too many words can lose marks even if the idea is correct.","zh":"即使意思正確，寫太多字也可能失分。"},{"en":"This phrase gives a strict answer-length rule.","zh":"這個短語給出嚴格答案長度規則。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":24},{"front":"choose from the passage","meaning":"從篇章中選取","examples":[{"en":"The answers must be chosen from the passage.","zh":"答案必須從篇章中選取。"},{"en":"To choose from the passage means to use words or information that appear in the text.","zh":"choose from the passage 指使用文本中出現的字詞或資料。"},{"en":"In IELTS completion tasks, students should not invent answers outside the passage.","zh":"在 IELTS 填充題中，學生不應自創文章以外的答案。"},{"en":"Choosing exact words from the passage helps avoid unnecessary paraphrase mistakes.","zh":"從篇章中選取原字可以避免不必要的改寫錯誤。"},{"en":"This phrase reminds students to stay close to the source.","zh":"這個短語提醒學生緊扣來源。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":24},{"front":"created wetlands near","meaning":"在……附近建造濕地","examples":[{"en":"The UK Environment Agency created wetlands near the town to protect it from flooding.","zh":"英國環境署在該鎮附近建造濕地，以保護它免受水災。"},{"en":"Created wetlands near means built or restored wetland areas close to a particular place.","zh":"created wetlands near 指在某地附近建造或修復濕地區域。"},{"en":"A city may create wetlands near a housing estate to absorb rainwater.","zh":"城市可能在屋邨附近建造濕地來吸收雨水。"},{"en":"Wetlands near vulnerable areas can slow water before it reaches homes.","zh":"脆弱地區附近的濕地可以在水到達房屋前減慢水流。"},{"en":"This phrase links wetland creation with location and protection.","zh":"這個短語把濕地建造與位置和保護連繫起來。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":24},{"front":"protect it from flooding","meaning":"保護它免受水災","examples":[{"en":"The wetlands were created to protect the town from flooding.","zh":"這些濕地被建造來保護該鎮免受水災。"},{"en":"To protect it from flooding means to prevent or reduce flood damage to that place.","zh":"protect it from flooding 指防止或減少水災對該地造成的損害。"},{"en":"A school may raise electrical sockets to protect it from flooding.","zh":"學校可能提高電插座位置，以保護它免受水災。"},{"en":"Flood protection reduces repair costs and keeps people safer during storms.","zh":"防洪保護可以減少維修成本，並在風暴期間提高安全。"},{"en":"This phrase explains the purpose of a flood-management measure.","zh":"這個短語解釋防洪措施的目的。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":24},{"front":"proposed that","meaning":"提出；建議","examples":[{"en":"Soft engineers proposed that cities should be porous.","zh":"軟性工程師提出城市應該變得可滲水。"},{"en":"Proposed that means suggested or put forward an idea for consideration.","zh":"proposed that 指提出某想法供人考慮。"},{"en":"A teacher proposed that students use examples before memorising definitions.","zh":"老師建議學生先使用例句，再背定義。"},{"en":"Proposals need testing before they become official policy.","zh":"提議在成為正式政策前需要測試。"},{"en":"This phrase introduces a suggested solution or argument.","zh":"這個短語引入建議的解決方案或論點。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":24},{"front":"provide a good example","meaning":"提供一個好例子","examples":[{"en":"Berlin provides a good example of a porous city.","zh":"柏林提供一個海綿城市的好例子。"},{"en":"To provide a good example means to show clearly how an idea works in practice.","zh":"provide a good example 指清楚展示某想法如何在實際中運作。"},{"en":"A school with solar panels and rain gardens provides a good example of sustainable design.","zh":"有太陽能板和雨水花園的學校提供一個可持續設計的好例子。"},{"en":"Good examples help people understand and copy useful methods.","zh":"好例子幫助人們理解並仿效有用方法。"},{"en":"This phrase identifies a clear model.","zh":"這個短語指出清楚典範。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":24},{"front":"frequently hit by severe storms","meaning":"經常受強烈風暴吹襲","examples":[{"en":"Los Angeles is frequently hit by severe storms.","zh":"洛杉磯經常受強烈風暴吹襲。"},{"en":"Frequently hit by severe storms means often affected by strong and damaging storms.","zh":"frequently hit by severe storms 指經常受強烈且具破壞性的風暴影響。"},{"en":"A coastal village frequently hit by severe storms may need shelters and warning systems.","zh":"經常受強烈風暴吹襲的沿海村莊可能需要庇護所和警報系統。"},{"en":"Repeated storm damage can make communities more willing to try new flood plans.","zh":"反覆風暴損害可以令社區更願意嘗試新防洪計劃。"},{"en":"This phrase describes repeated exposure to dangerous weather.","zh":"這個短語描述反覆暴露於危險天氣之中。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":24},{"front":"despite spending billions of dollars","meaning":"儘管花費數十億美元","examples":[{"en":"The city still floods despite spending billions of dollars on flood control.","zh":"儘管在防洪上花費數十億美元，該市仍然水浸。"},{"en":"Despite spending billions of dollars means even though an extremely large amount of money has been spent.","zh":"despite spending billions of dollars 指即使已花費極大量金錢。"},{"en":"A hospital may still have long waiting times despite spending millions on new software.","zh":"儘管花費數百萬購買新軟件，醫院仍可能有很長輪候時間。"},{"en":"Heavy spending cannot fix a problem if the strategy is poorly designed.","zh":"如果策略設計差劣，巨額開支也不能解決問題。"},{"en":"This phrase contrasts high cost with disappointing results.","zh":"這個短語把高成本與令人失望的結果作對比。"}],"source":"51 - Keep the Water Away.pdf","sourcePage":25}],"ielts/reading/passage-2/Practice 52":[{"front":"implications of","meaning":"……的含義；……的影響","examples":[{"en":"The passage discusses the implications of false-belief experiments.","zh":"文章討論錯誤信念實驗的含義和影響。"},{"en":"The implications of something are the possible meanings, effects, or consequences it has.","zh":"implications of something 指某事可能帶來的意思、影響或後果。"},{"en":"A teacher may discuss the implications of low attendance for students’ exam results.","zh":"老師可能討論低出席率對學生考試成績的影響。"},{"en":"If a study shows children understand beliefs later than expected, its implications affect education and psychology.","zh":"如果研究顯示兒童比預期更晚理解信念，其影響會涉及教育和心理學。"},{"en":"The phrase looks beyond the result itself and asks what the result means.","zh":"這個短語不只看結果本身，而是問該結果代表甚麼。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":1},{"front":"false-belief experiments","meaning":"錯誤信念實驗","examples":[{"en":"False-belief experiments are used to study children’s understanding of other people’s beliefs.","zh":"錯誤信念實驗用來研究兒童對他人信念的理解。"},{"en":"False-belief experiments test whether someone understands that another person can believe something untrue.","zh":"false-belief experiments 測試某人是否明白另一個人可以相信一件不真實的事。"},{"en":"A child may watch a toy hidden in one box while another character wrongly thinks it is in another box.","zh":"孩子可能看見玩具被藏在一個盒中，而另一角色錯誤地以為它在另一盒中。"},{"en":"If the child predicts the character’s wrong search, it shows understanding of false belief.","zh":"如果孩子預測角色會在錯誤地方尋找，這顯示他理解錯誤信念。"},{"en":"These experiments are useful because they reveal how children think about other minds.","zh":"這些實驗有用，因為它們揭示兒童如何理解他人的心智。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":1},{"front":"a considerable amount of research","meaning":"大量研究","examples":[{"en":"A considerable amount of research since the mid-1980s has examined children’s theory of mind.","zh":"自1980年代中期以來，大量研究探討了兒童的心智理論。"},{"en":"A considerable amount of research means a large and serious body of study.","zh":"considerable amount of research 指大量而認真的研究。"},{"en":"A considerable amount of research has been done on how sleep affects school performance.","zh":"關於睡眠如何影響學校表現，已有大量研究。"},{"en":"When many studies examine the same issue, the topic becomes more important and better understood.","zh":"當許多研究探討同一問題，該題目就變得更重要，也更容易理解。"},{"en":"The phrase stresses that the evidence comes from many studies, not one isolated paper.","zh":"這個短語強調證據來自許多研究，而不是單一論文。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":1},{"front":"since the mid-1980s","meaning":"自1980年代中期以來","examples":[{"en":"A considerable amount of research since the mid-1980s has examined children’s theory of mind.","zh":"自1980年代中期以來，大量研究探討了兒童的心智理論。"},{"en":"Since the mid-1980s means from around the middle years of the 1980s until now or a later point.","zh":"since the mid-1980s 指從1980年代中期左右起直到現在或後來某時間點。"},{"en":"Since the mid-1980s, computers have become far more common in schools and homes.","zh":"自1980年代中期以來，電腦在學校和家庭中變得普遍得多。"},{"en":"A long period of research allows scholars to compare early findings with newer evidence.","zh":"長期研究讓學者可以比較早期發現和較新證據。"},{"en":"The phrase gives a starting point for a continuing period.","zh":"這個短語提供持續時期的起點。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":1},{"front":"examine what is known as","meaning":"研究所謂的……","examples":[{"en":"Researchers have examined what is known as children’s theory of mind.","zh":"研究人員研究了所謂兒童心智理論。"},{"en":"To examine what is known as something means to study a concept that has a particular name.","zh":"examine what is known as something 指研究一個有特定名稱的概念。"},{"en":"Scientists may examine what is known as working memory when studying learning problems.","zh":"科學家研究學習問題時，可能研究所謂工作記憶。"},{"en":"Giving the name of a concept helps readers know the technical term being discussed.","zh":"說出概念名稱有助讀者知道正在討論的專門術語。"},{"en":"The phrase introduces a specialised idea in a careful way.","zh":"這個短語以謹慎方式引入專門概念。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":1},{"front":"theory of mind","meaning":"心智理論","examples":[{"en":"Theory of mind is the ability to understand that people can hold different beliefs.","zh":"心智理論是理解人們可以持有不同信念的能力。"},{"en":"Theory of mind means understanding that other people have thoughts, beliefs, desires, and knowledge that may differ from one’s own.","zh":"theory of mind 指明白他人有想法、信念、願望和知識，而且可能與自己不同。"},{"en":"A child uses theory of mind when she knows her friend may not know where the toy is hidden.","zh":"當孩子知道朋友可能不知道玩具藏在哪裡，她就在運用心智理論。"},{"en":"Theory of mind helps people explain behaviour, predict reactions, and communicate better.","zh":"心智理論幫助人們解釋行為、預測反應和更好地溝通。"},{"en":"Without theory of mind, social situations become harder to understand.","zh":"沒有心智理論，社交情境會更難理解。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":1},{"front":"the ability to understand that","meaning":"理解……的能力","examples":[{"en":"Theory of mind is the ability to understand that people can hold different beliefs.","zh":"心智理論是理解人們可以持有不同信念的能力。"},{"en":"The ability to understand that means the mental skill needed to recognise a fact or idea.","zh":"ability to understand that 指辨認某個事實或想法所需的心理能力。"},{"en":"Students need the ability to understand that a word can have different meanings in different contexts.","zh":"學生需要理解一個字在不同語境中可以有不同意思的能力。"},{"en":"When children gain this ability, they can explain why another person acts differently from them.","zh":"當兒童獲得這種能力，他們就能解釋為何另一個人的行為與自己不同。"},{"en":"The phrase focuses on a specific kind of understanding.","zh":"這個短語重點是某種特定理解能力。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":1},{"front":"hold different beliefs","meaning":"持有不同信念","examples":[{"en":"People can hold different beliefs and representations of the world.","zh":"人們可以持有不同信念和對世界的表徵。"},{"en":"To hold different beliefs means to think or believe things that are not the same as someone else’s beliefs.","zh":"hold different beliefs 指想法或信念與別人不同。"},{"en":"Two classmates may hold different beliefs about which answer is correct.","zh":"兩位同學可能對哪個答案正確持有不同信念。"},{"en":"If people hold different beliefs, they may act differently even in the same situation.","zh":"如果人們持有不同信念，即使在同一情況中也可能有不同行為。"},{"en":"The phrase is central to understanding that minds can differ.","zh":"這個短語是理解不同心智的核心。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":1},{"front":"representations of the world","meaning":"對世界的表徵","examples":[{"en":"Children gradually understand that people may have different representations of the world.","zh":"兒童逐漸明白人們可能對世界有不同表徵。"},{"en":"Representations of the world are mental pictures or ideas about how reality is organised.","zh":"representations of the world 指關於現實如何組成的心理圖像或想法。"},{"en":"A child may think the biscuit is in the jar, while another person thinks it is in the cupboard.","zh":"孩子可能以為餅乾在罐中，而另一個人以為它在櫃中。"},{"en":"Different representations can lead people to search, speak, or act in different ways.","zh":"不同表徵可以令人以不同方式尋找、說話或行動。"},{"en":"The phrase describes what people believe reality is like inside their minds.","zh":"這個短語描述人們心中相信現實是怎樣的。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":1},{"front":"a capacity normally evident by","meaning":"通常到……時明顯出現的能力","examples":[{"en":"Theory of mind is a capacity normally evident by the age of four.","zh":"心智理論是通常到四歲時明顯出現的能力。"},{"en":"A capacity normally evident by a certain age is an ability that usually becomes visible by that time.","zh":"capacity normally evident by a certain age 指通常到某年齡時會變得可見的能力。"},{"en":"Basic counting is often a capacity evident by early primary school.","zh":"基本數數通常是小學初期明顯出現的能力。"},{"en":"If an ability is not evident at the usual age, researchers may study development more closely.","zh":"如果能力沒有在通常年齡顯現，研究人員可能更仔細研究發展。"},{"en":"The phrase describes when an ability can normally be observed.","zh":"這個短語描述某能力通常何時可被觀察到。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":1},{"front":"be absent in","meaning":"在……身上缺失","examples":[{"en":"This ability appears to be absent in children with autism.","zh":"這種能力似乎在有自閉症的兒童身上缺失。"},{"en":"To be absent in a group means to be missing or not clearly present in that group.","zh":"be absent in a group 指某物在該群體中缺少或不明顯存在。"},{"en":"A skill may be absent in beginners if they have never practised it before.","zh":"如果初學者從未練習過某技能，該技能可能在他們身上缺失。"},{"en":"If an ability is absent, teachers or therapists may need different support methods.","zh":"如果某能力缺失，老師或治療師可能需要不同支援方法。"},{"en":"The phrase describes a lack of something in a particular group.","zh":"這個短語描述某群體中缺乏某物。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":1},{"front":"children with autism","meaning":"有自閉症的兒童","examples":[{"en":"Theory of mind may be absent in children with autism.","zh":"心智理論可能在有自閉症的兒童身上缺失。"},{"en":"Children with autism are children with a developmental condition that can affect communication, behaviour, and social understanding.","zh":"children with autism 指有一種可能影響溝通、行為和社交理解的發展狀況的兒童。"},{"en":"Some children with autism may find it difficult to guess what another person knows or feels.","zh":"有些自閉症兒童可能難以猜測別人知道甚麼或感受如何。"},{"en":"Support can help children with autism communicate, learn routines, and manage social situations.","zh":"支援可以幫助有自閉症的兒童溝通、學習規律和處理社交情境。"},{"en":"The phrase should be used respectfully and not as a label for the whole child.","zh":"這個短語應被尊重地使用，不應把孩子完全簡化成標籤。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":2},{"front":"work out what someone is thinking","meaning":"弄清楚某人在想甚麼","examples":[{"en":"Working out what another person is thinking is important to cognitive and social development.","zh":"弄清楚另一個人在想甚麼對認知和社交發展很重要。"},{"en":"To work out what someone is thinking means to infer their thoughts, beliefs, or intentions.","zh":"work out what someone is thinking 指推斷某人的想法、信念或意圖。"},{"en":"A student may work out that a friend is confused when the friend keeps staring at the question.","zh":"當朋友一直盯着題目，學生可能推斷出朋友感到困惑。"},{"en":"Understanding another person’s thoughts helps people respond kindly and avoid misunderstandings.","zh":"理解別人的想法有助人們友善回應並避免誤會。"},{"en":"The phrase focuses on guessing mental states from clues.","zh":"這個短語重點是從線索推測心理狀態。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":2},{"front":"cognitive and social development","meaning":"認知及社交發展","examples":[{"en":"The ability to understand other minds is important to cognitive and social development.","zh":"理解他人心智的能力對認知及社交發展很重要。"},{"en":"Cognitive and social development means the growth of thinking skills and the ability to interact with others.","zh":"cognitive and social development 指思考能力和與他人互動能力的成長。"},{"en":"Group games can support children’s social development while puzzles support cognitive development.","zh":"小組遊戲可以支援兒童社交發展，而謎題支援認知發展。"},{"en":"If children learn to understand others’ beliefs, they can think more flexibly and cooperate better.","zh":"如果兒童學會理解他人信念，他們可以更靈活思考並更好合作。"},{"en":"The phrase connects mental growth with social growth.","zh":"這個短語把心理成長與社交成長連起來。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":2},{"front":"one influential explanation of","meaning":"對……一個有影響力的解釋","examples":[{"en":"One influential explanation of autism is that affected children do not have a theory of mind.","zh":"對自閉症一個有影響力的解釋是受影響兒童沒有心智理論。"},{"en":"One influential explanation of something is a theory that has strongly shaped how people understand it.","zh":"one influential explanation of something 指一個強烈塑造人們如何理解某事的理論。"},{"en":"One influential explanation of exam anxiety is that students fear failure more than the test itself.","zh":"對考試焦慮一個有影響力的解釋是學生害怕失敗多於害怕考試本身。"},{"en":"Influential explanations guide research, teaching, and treatment even if they are later debated.","zh":"有影響力的解釋會引導研究、教學和治療，即使之後受到爭論。"},{"en":"The phrase introduces an important theory, not a final answer.","zh":"這個短語引入重要理論，而不是最終答案。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":2},{"front":"affected children","meaning":"受影響的兒童","examples":[{"en":"Affected children may not have a theory of mind.","zh":"受影響的兒童可能沒有心智理論。"},{"en":"Affected children are children who are influenced by a condition, problem, or disorder being discussed.","zh":"affected children 指受到正在討論的狀況、問題或障礙影響的兒童。"},{"en":"After a school fire, affected children may need counselling and temporary classrooms.","zh":"學校火災後，受影響的兒童可能需要輔導和臨時課室。"},{"en":"When children are affected by a developmental difficulty, they may need tailored support.","zh":"當兒童受發展困難影響，他們可能需要度身訂造的支援。"},{"en":"The phrase identifies the group experiencing the issue.","zh":"這個短語指出經歷該問題的群體。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":2},{"front":"consequently","meaning":"因此","examples":[{"en":"Consequently, the development of children’s theory of mind has attracted considerable attention.","zh":"因此，兒童心智理論的發展引起了相當大的關注。"},{"en":"Consequently means as a result.","zh":"consequently 指因此或結果是。"},{"en":"The school library closed early; consequently, many students studied in the canteen.","zh":"學校圖書館提早關閉；因此，許多學生在飯堂溫習。"},{"en":"If a theory may explain social difficulties, researchers consequently study it closely.","zh":"如果某理論可能解釋社交困難，研究人員因此會仔細研究它。"},{"en":"The word links a cause with its result.","zh":"這個詞把原因與結果連起來。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":2},{"front":"attract considerable attention","meaning":"引起相當大的關注","examples":[{"en":"The development of children’s theory of mind has attracted considerable attention.","zh":"兒童心智理論的發展引起了相當大的關注。"},{"en":"To attract considerable attention means to receive a large amount of interest from people.","zh":"attract considerable attention 指得到大量興趣或關注。"},{"en":"A new teaching method may attract considerable attention if students improve quickly.","zh":"如果學生進步很快，新教學方法可能引起相當大的關注。"},{"en":"Important findings attract attention because they may change how experts understand a problem.","zh":"重要發現會引起關注，因為它們可能改變專家對問題的理解。"},{"en":"The phrase suggests strong interest, not casual notice.","zh":"這個短語暗示強烈興趣，而不是隨便注意。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":2},{"front":"devise a task","meaning":"設計一項任務","examples":[{"en":"Wimmer and Perner devised a false-belief task to investigate this issue.","zh":"Wimmer 和 Perner 設計了一項錯誤信念任務來研究這個問題。"},{"en":"To devise a task means to design an activity or test for a particular purpose.","zh":"devise a task 指為特定目的設計活動或測試。"},{"en":"A teacher may devise a task to check whether students can use past tense correctly.","zh":"老師可能設計一項任務，檢查學生是否能正確使用過去式。"},{"en":"A well-designed task helps researchers measure a skill more clearly.","zh":"設計良好的任務幫助研究人員更清楚量度技能。"},{"en":"The phrase focuses on creating a method for testing or learning.","zh":"這個短語重點是創造測試或學習方法。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":2},{"front":"a false-belief task","meaning":"錯誤信念任務","examples":[{"en":"Wimmer and Perner devised a false-belief task to investigate this issue.","zh":"Wimmer 和 Perner 設計了一項錯誤信念任務來研究這個問題。"},{"en":"A false-belief task is a test that checks whether someone understands another person’s mistaken belief.","zh":"false-belief task 指測試某人是否理解另一人錯誤信念的任務。"},{"en":"A child may pass a false-belief task by saying a character will search where the object used to be.","zh":"孩子如果說角色會在物件原本所在位置尋找，就可能通過錯誤信念任務。"},{"en":"The task can reveal whether the child separates their own knowledge from another person’s belief.","zh":"該任務可以揭示孩子是否把自己的知識與別人的信念分開。"},{"en":"The phrase names a common tool in theory-of-mind research.","zh":"這個短語命名心智理論研究中的常見工具。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":2},{"front":"investigate this issue","meaning":"研究這個問題","examples":[{"en":"The researchers devised a task to investigate this issue.","zh":"研究人員設計了一項任務來研究這個問題。"},{"en":"To investigate this issue means to study a specific question carefully to find evidence.","zh":"investigate this issue 指仔細研究某特定問題，以尋找證據。"},{"en":"A school may investigate the issue of bullying by interviewing students and teachers.","zh":"學校可能透過訪問學生和老師來研究欺凌問題。"},{"en":"Investigation helps replace guessing with clearer information.","zh":"調查研究有助以較清楚資訊取代猜測。"},{"en":"The phrase describes purposeful research into a problem.","zh":"這個短語描述針對問題的有目的研究。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":2},{"front":"use toys to act out","meaning":"用玩具演繹","examples":[{"en":"They used toys to act out the story.","zh":"他們用玩具演繹這個故事。"},{"en":"To use toys to act out a story means to perform the events with toy figures or objects.","zh":"use toys to act out a story 指用玩具人物或物件表演故事事件。"},{"en":"A teacher may use toys to act out a shopping dialogue for young learners.","zh":"老師可能用玩具演繹購物對話給年幼學習者看。"},{"en":"Acting out a story makes abstract ideas easier for children to follow.","zh":"演繹故事令抽象概念較容易讓兒童跟上。"},{"en":"The phrase describes a concrete way to show events.","zh":"這個短語描述展示事件的具體方法。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":2},{"front":"leave some chocolate in","meaning":"把一些朱古力留在……","examples":[{"en":"Maxi leaves some chocolate in a blue cupboard before going out.","zh":"Maxi 外出前把一些朱古力留在藍色櫃中。"},{"en":"To leave some chocolate in a place means to put it there and go away without taking it.","zh":"leave some chocolate in a place 指把朱古力放在某處，然後不帶走地離開。"},{"en":"A child may leave some chocolate in a schoolbag and forget about it until lunch.","zh":"孩子可能把一些朱古力留在書包中，直到午餐才想起。"},{"en":"Where the chocolate is first left matters because another person may still believe it is there.","zh":"朱古力最初被留在哪裡很重要，因為另一個人可能仍相信它在那裡。"},{"en":"The phrase describes the original location of an object.","zh":"這個短語描述物件的原本位置。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":3},{"front":"while he is away","meaning":"當他不在時","examples":[{"en":"While he is away, his mother moves the chocolate to a green cupboard.","zh":"當他不在時，他的母親把朱古力移到綠色櫃中。"},{"en":"While he is away means during the time when he is not present.","zh":"while he is away 指在他不在場的期間。"},{"en":"While a student is away from her desk, a friend may move her notebook to another table.","zh":"當學生不在座位時，朋友可能把她的筆記移到另一張桌。"},{"en":"If something changes while a person is away, that person may not know the new situation.","zh":"如果某事在一個人不在時改變，那個人可能不知道新情況。"},{"en":"The phrase is important in false-belief stories because absence creates ignorance.","zh":"這個短語在錯誤信念故事中很重要，因為缺席造成不知道。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":3},{"front":"predict where","meaning":"預測……在哪裏","examples":[{"en":"Children are asked to predict where Maxi will look for the chocolate.","zh":"兒童被要求預測 Maxi 會在哪裡尋找朱古力。"},{"en":"To predict where means to say the place where something will probably happen.","zh":"predict where 指說出某事可能會在甚麼地方發生。"},{"en":"A teacher may ask students to predict where a character will go next in a story.","zh":"老師可能要求學生預測故事人物接下來會去哪裡。"},{"en":"Prediction shows whether a child understands what information the character has.","zh":"預測可以顯示孩子是否理解角色擁有甚麼資訊。"},{"en":"The phrase focuses on using clues to guess a future location.","zh":"這個短語重點是用線索猜測未來位置。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":3},{"front":"look for","meaning":"尋找","examples":[{"en":"Children predict where Maxi will look for the chocolate when he returns.","zh":"兒童預測 Maxi 回來時會在哪裡尋找朱古力。"},{"en":"To look for something means to try to find it.","zh":"look for something 指嘗試找出某物。"},{"en":"A student may look for a lost calculator before a maths test.","zh":"學生可能在數學測驗前尋找遺失的計算機。"},{"en":"People usually look for things where they believe those things are located.","zh":"人們通常會在自己相信物件所在的位置尋找它。"},{"en":"The phrase describes searching based on need or belief.","zh":"這個短語描述基於需要或信念的搜尋。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":3},{"front":"most children under four","meaning":"大多數四歲以下兒童","examples":[{"en":"Most children under four incorrectly answer that Maxi will look in the green cupboard.","zh":"大多數四歲以下兒童錯誤地回答 Maxi 會在綠色櫃中尋找。"},{"en":"Most children under four means the majority of children younger than four years old.","zh":"most children under four 指大部分未滿四歲的兒童。"},{"en":"Most children under four may need simple instructions with pictures and gestures.","zh":"大多數四歲以下兒童可能需要配合圖片和手勢的簡單指示。"},{"en":"Younger children may answer from what they know rather than what another person believes.","zh":"較年幼兒童可能根據自己知道的事回答，而不是根據別人的信念回答。"},{"en":"The phrase identifies a young age group in development research.","zh":"這個短語指出發展研究中的年幼年齡組。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":3},{"front":"incorrectly answer that","meaning":"錯誤地回答說","examples":[{"en":"Most children under four incorrectly answer that Maxi will look in the green cupboard.","zh":"大多數四歲以下兒童錯誤地回答說 Maxi 會在綠色櫃中尋找。"},{"en":"To incorrectly answer that means to give a response that is wrong.","zh":"incorrectly answer that 指給出錯誤回答。"},{"en":"A student may incorrectly answer that a story happened in France when the passage says Germany.","zh":"如果文章說故事發生在德國，學生可能錯誤地回答說發生在法國。"},{"en":"Wrong answers can show what learners misunderstand, not just that they failed.","zh":"錯誤答案可以顯示學習者誤解了甚麼，而不只是失敗。"},{"en":"The phrase introduces the mistaken response directly.","zh":"這個短語直接引入錯誤回應。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":3},{"front":"tend to answer correctly","meaning":"往往會正確回答","examples":[{"en":"Children over four tend to answer correctly that Maxi will look in the blue cupboard.","zh":"四歲以上兒童往往會正確回答 Maxi 會在藍色櫃中尋找。"},{"en":"Tend to answer correctly means usually give the right answer.","zh":"tend to answer correctly 指通常給出正確答案。"},{"en":"Students who read the question carefully tend to answer correctly in reading tests.","zh":"仔細閱讀題目的學生在閱讀測驗中往往會正確回答。"},{"en":"If older children answer correctly more often, researchers may infer a developmental change.","zh":"如果較年長兒童更常答對，研究人員可能推斷出發展變化。"},{"en":"The phrase describes a general pattern, not every single child.","zh":"這個短語描述一般模式，而不是每一個孩子。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":3},{"front":"no longer correspond to","meaning":"不再符合……","examples":[{"en":"Maxi’s belief no longer corresponds to the actual state of the world.","zh":"Maxi 的信念不再符合世界的實際狀況。"},{"en":"No longer correspond to means no longer match or agree with something.","zh":"no longer correspond to 指不再與某事相符或一致。"},{"en":"An old bus timetable may no longer correspond to the real departure times.","zh":"舊巴士時間表可能不再符合真正出發時間。"},{"en":"When a belief no longer matches reality, a person may act on outdated information.","zh":"當信念不再符合現實，一個人可能根據過時資訊行動。"},{"en":"The phrase shows a gap between belief and fact.","zh":"這個短語顯示信念與事實之間的差距。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":3},{"front":"the actual state of the world","meaning":"世界的實際狀況","examples":[{"en":"Younger children do not understand that Maxi’s belief differs from the actual state of the world.","zh":"較年幼兒童不明白 Maxi 的信念不同於世界的實際狀況。"},{"en":"The actual state of the world means what is really true in reality.","zh":"actual state of the world 指現實中真正成立的情況。"},{"en":"A child may know the toy is under the bed, but another person may think it is in the drawer.","zh":"孩子可能知道玩具在床下，但另一個人可能以為它在抽屜中。"},{"en":"False-belief tasks test whether children separate real facts from another person’s mistaken belief.","zh":"錯誤信念任務測試兒童是否把真實事實與他人錯誤信念分開。"},{"en":"The phrase refers to reality itself, not what someone thinks.","zh":"這個短語指現實本身，而不是某人的想法。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":3},{"front":"fail to appreciate that","meaning":"未能理解","examples":[{"en":"They fail to appreciate that Maxi will act on his belief.","zh":"他們未能理解 Maxi 會根據自己的信念行事。"},{"en":"To fail to appreciate that means not to understand or recognise an important point.","zh":"fail to appreciate that 指未能理解或認識到一個重要點。"},{"en":"A student may fail to appreciate that a question asks for opinion, not summary.","zh":"學生可能未能理解題目要求意見，而不是摘要。"},{"en":"If children miss this point, they may predict behaviour from reality rather than belief.","zh":"如果兒童錯過這一點，他們可能根據現實而不是信念預測行為。"},{"en":"The phrase suggests a deeper misunderstanding, not just a small mistake.","zh":"這個短語暗示較深層誤解，而不只是小錯。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":3},{"front":"act on one’s belief","meaning":"根據自己的信念行事","examples":[{"en":"Maxi will act on his belief rather than on how the world is actually organised.","zh":"Maxi 會根據自己的信念行事，而不是根據世界實際上如何安排。"},{"en":"To act on one’s belief means to behave according to what one thinks is true.","zh":"act on one’s belief 指按照自己認為真實的事情去行動。"},{"en":"A student who believes the class starts at nine may arrive at nine, even if the timetable changed.","zh":"如果學生相信課堂九點開始，即使時間表改了，他也可能九點到達。"},{"en":"People’s actions often follow their beliefs, even when those beliefs are wrong.","zh":"人們的行動常跟隨其信念，即使那些信念錯誤。"},{"en":"The phrase connects mental belief with real behaviour.","zh":"這個短語把心理信念與實際行為連起來。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":3},{"front":"rather than","meaning":"而不是","examples":[{"en":"Maxi will act on his belief rather than on how the world is actually organised.","zh":"Maxi 會根據自己的信念行事，而不是根據世界實際上如何安排。"},{"en":"Rather than means instead of and clearly contrasts two possibilities.","zh":"rather than 指而不是，清楚對比兩種可能。"},{"en":"A student should answer from the passage rather than from memory in a reading test.","zh":"在閱讀測驗中，學生應根據文章作答，而不是根據記憶。"},{"en":"In false-belief tasks, the key is belief rather than reality.","zh":"在錯誤信念任務中，關鍵是信念，而不是現實。"},{"en":"The phrase helps separate the real basis of an action from another possible basis.","zh":"這個短語幫助分開行動的真正依據和另一個可能依據。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":4},{"front":"how the world is actually organised","meaning":"世界實際上是如何安排的","examples":[{"en":"Young children focus on how the world is actually organised.","zh":"年幼兒童集中於世界實際上是如何安排的。"},{"en":"How the world is actually organised means the real arrangement or true situation of things.","zh":"how the world is actually organised 指事物的真實安排或真正情況。"},{"en":"A child may know the ball is in the cupboard because she saw someone move it there.","zh":"孩子可能知道球在櫃中，因為她看見有人把它移到那裡。"},{"en":"Focusing only on reality can make it hard to predict a person with a false belief.","zh":"只集中於現實，可能令人難以預測持有錯誤信念的人。"},{"en":"The phrase contrasts objective reality with someone’s mental picture.","zh":"這個短語把客觀現實與某人的心理圖像作對比。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":4},{"front":"a simpler version of","meaning":"……的較簡化版本","examples":[{"en":"Baron-Cohen devised a simpler version of the Maxi task.","zh":"Baron-Cohen 設計了 Maxi 任務的較簡化版本。"},{"en":"A simpler version of something is an easier form with fewer details or lower difficulty.","zh":"simpler version of something 指細節較少或難度較低的形式。"},{"en":"A teacher may give beginners a simpler version of a grammar exercise.","zh":"老師可能給初學者一個較簡化版本的文法練習。"},{"en":"Simplifying a task can show whether failure was caused by the concept or by confusing details.","zh":"簡化任務可以顯示失敗是由概念本身還是混亂細節造成。"},{"en":"The phrase describes an adjusted form of an original task.","zh":"這個短語描述原任務的調整形式。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":4},{"front":"in response to criticism that","meaning":"回應……的批評","examples":[{"en":"Baron-Cohen devised a simpler task in response to criticism that the original story was too complex.","zh":"Baron-Cohen 回應原本故事太複雜的批評，設計了一項較簡單任務。"},{"en":"In response to criticism that means because people criticised or questioned a particular point.","zh":"in response to criticism that 指因為有人批評或質疑某一點。"},{"en":"A school may change its homework policy in response to criticism that students are overloaded.","zh":"學校可能回應學生負擔過重的批評，改變功課政策。"},{"en":"Criticism can lead researchers to redesign a method and make results more reliable.","zh":"批評可以促使研究人員重新設計方法，使結果更可靠。"},{"en":"The phrase links a change to a previous objection.","zh":"這個短語把改變與先前反對意見連起來。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":4},{"front":"be affected by","meaning":"受……影響","examples":[{"en":"Younger children might have been affected by the original story’s complexity.","zh":"較年幼兒童可能受到原本故事複雜性的影響。"},{"en":"To be affected by something means to be influenced or changed by it.","zh":"be affected by something 指受到某事影響或改變。"},{"en":"A student’s concentration may be affected by noise outside the classroom.","zh":"學生專注力可能受課室外噪音影響。"},{"en":"If a task is too complex, performance may reflect confusion rather than real ability.","zh":"如果任務太複雜，表現可能反映困惑，而不是真正能力。"},{"en":"The phrase shows that one factor may influence a result.","zh":"這個短語顯示某因素可能影響結果。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":4},{"front":"the original story’s complexity","meaning":"原本故事的複雜性","examples":[{"en":"Critics argued that the original story’s complexity may have affected children’s answers.","zh":"批評者認為原本故事的複雜性可能影響了兒童答案。"},{"en":"The original story’s complexity means the difficulty caused by the first version’s many details or structure.","zh":"original story’s complexity 指第一版本因細節多或結構複雜而造成的難度。"},{"en":"A reading passage’s complexity may confuse students even if they understand the topic.","zh":"閱讀文章的複雜性可能令學生困惑，即使他們明白題目。"},{"en":"If a story has too many events, children may fail because of memory load rather than poor understanding.","zh":"如果故事事件太多，兒童可能因記憶負荷而失敗，而不是理解差。"},{"en":"The phrase points to task difficulty as a possible problem.","zh":"這個短語指出任務難度可能是一個問題。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":4},{"front":"quantity of information","meaning":"資料量","examples":[{"en":"The original task may have included too great a quantity of information.","zh":"原本任務可能包含過大的資料量。"},{"en":"Quantity of information means the amount of details, facts, or instructions given.","zh":"quantity of information 指所提供細節、事實或指示的數量。"},{"en":"A student may feel lost if a teacher gives a large quantity of information at once.","zh":"如果老師一次給大量資料，學生可能感到迷失。"},{"en":"Too much information can overload memory and reduce task performance.","zh":"過多資料可以令記憶負荷過重，降低任務表現。"},{"en":"The phrase focuses on amount, not whether the information is true.","zh":"這個短語重點是數量，而不是資料是否真實。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":4},{"front":"in the revised task","meaning":"在修訂後的任務中","examples":[{"en":"In the revised task, a child is shown two dolls.","zh":"在修訂後的任務中，孩子會看到兩個洋娃娃。"},{"en":"In the revised task means in the changed or improved version of the activity.","zh":"in the revised task 指在被修改或改善後的活動版本中。"},{"en":"In the revised test, students answer fewer questions but explain each answer more clearly.","zh":"在修訂後的測驗中，學生回答較少問題，但更清楚解釋每個答案。"},{"en":"A revised task can remove unnecessary difficulty and focus on the skill being tested.","zh":"修訂後任務可以移除不必要難度，集中測試目標技能。"},{"en":"The phrase refers to the new version after changes.","zh":"這個短語指經修改後的新版本。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":4},{"front":"two dolls","meaning":"兩個洋娃娃","examples":[{"en":"The revised task uses two dolls, Sally and Anne.","zh":"修訂後的任務使用兩個洋娃娃，Sally 和 Anne。"},{"en":"Two dolls means two toy figures used to represent characters in the story.","zh":"two dolls 指兩個用來代表故事角色的玩具人物。"},{"en":"A teacher may use two dolls to show a simple conversation in a language class.","zh":"老師可能用兩個洋娃娃在語言課中展示簡單對話。"},{"en":"Dolls make the story visible, so children do not need to imagine every detail.","zh":"洋娃娃令故事可見，所以兒童不需要想像每個細節。"},{"en":"The phrase names the concrete objects used in the experiment.","zh":"這個短語指出實驗中使用的具體物件。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":4},{"front":"respectively","meaning":"分別","examples":[{"en":"Sally and Anne have a basket and a box respectively.","zh":"Sally 和 Anne 分別有一個籃子和一個盒子。"},{"en":"Respectively means in the same order as the names or items just mentioned.","zh":"respectively 指按照剛提到名字或項目的相同次序。"},{"en":"Anna and Ben scored 80 and 90 respectively, meaning Anna scored 80 and Ben scored 90.","zh":"Anna 和 Ben 分別得80和90分，即 Anna 得80分，Ben 得90分。"},{"en":"The word prevents confusion when two items are matched with two details.","zh":"這個詞在兩個項目要配對兩個細節時避免混亂。"},{"en":"It is common in formal descriptions and comparisons.","zh":"它常見於正式描述和比較。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":4},{"front":"place a marble in","meaning":"把波子放進……","examples":[{"en":"Sally places a marble in her basket and leaves for a walk.","zh":"Sally 把波子放進籃子，然後離開去散步。"},{"en":"To place a marble in something means to put a small glass ball inside a container.","zh":"place a marble in something 指把一粒小玻璃球放入容器中。"},{"en":"A child may place a marble in a cup during a classroom sorting game.","zh":"孩子可能在課堂分類遊戲中把波子放進杯中。"},{"en":"Where the marble is placed first matters because Sally will later search based on that memory.","zh":"波子最初被放在哪裡很重要，因為 Sally 之後會根據該記憶尋找。"},{"en":"The phrase describes the first location of the object.","zh":"這個短語描述物件的最初位置。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":4},{"front":"leave for a walk","meaning":"離開去散步","examples":[{"en":"Sally places a marble in her basket and leaves for a walk.","zh":"Sally 把波子放進籃子，然後離開去散步。"},{"en":"To leave for a walk means to go away from a place in order to walk outside.","zh":"leave for a walk 指離開某地去外面走路。"},{"en":"A student may leave for a walk after studying for several hours.","zh":"學生讀書數小時後可能離開去散步。"},{"en":"When Sally leaves, she cannot see Anne move the marble.","zh":"當 Sally 離開，她看不到 Anne 移動波子。"},{"en":"The phrase creates the absence needed for a false belief.","zh":"這個短語造成錯誤信念所需的缺席情況。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":5},{"front":"take something from","meaning":"從……取走某物","examples":[{"en":"Anne takes the marble from the basket and puts it in the box.","zh":"Anne 從籃子取走波子，並把它放進盒子。"},{"en":"To take something from a place means to remove it from that place.","zh":"take something from a place 指把某物從某地方移走。"},{"en":"A child may take a pencil from a drawer and put it on the desk.","zh":"孩子可能從抽屜取走鉛筆，放到桌上。"},{"en":"Moving an object from its first location can create a gap between reality and someone’s belief.","zh":"把物件從原本位置移走，可以造成現實與某人信念之間的差距。"},{"en":"The phrase describes removal from an original place.","zh":"這個短語描述從原位置移除。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":5},{"front":"pass by answering that","meaning":"透過回答……而通過","examples":[{"en":"The child passes by answering that Sally will look in the basket.","zh":"孩子透過回答 Sally 會在籃子裏找而通過測試。"},{"en":"To pass by answering that means to succeed in a test because one gives that answer.","zh":"pass by answering that 指因給出某答案而成功通過測試。"},{"en":"A student passes a grammar item by answering that the verb should be plural.","zh":"學生透過回答動詞應用複數而答對文法題。"},{"en":"In this task, the correct answer shows the child understands Sally’s belief.","zh":"在這項任務中，正確答案顯示孩子理解 Sally 的信念。"},{"en":"The phrase connects a specific answer with successful performance.","zh":"這個短語把特定答案與成功表現連起來。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":5},{"front":"where she left it","meaning":"在她原本放下它的地方","examples":[{"en":"Sally will look in the basket, where she left the marble.","zh":"Sally 會在籃子裏找，因為那是她原本放下波子的地方。"},{"en":"Where she left it means the place where she originally put the object.","zh":"where she left it 指她原本放置該物件的地方。"},{"en":"A student may look for her phone on the desk where she left it before lunch.","zh":"學生可能在午餐前原本放手機的桌上找手機。"},{"en":"People often search first in the place they remember using last.","zh":"人們通常先在自己記得最後使用的地方尋找。"},{"en":"The phrase points to the original location from the character’s perspective.","zh":"這個短語指出角色視角中的原本位置。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":5},{"front":"where it is hidden","meaning":"它被藏起來的地方","examples":[{"en":"The child knows where the marble is hidden, but Sally cannot know this.","zh":"孩子知道波子被藏在哪裏，但 Sally 不可能知道。"},{"en":"Where it is hidden means the secret or actual place where an object has been put.","zh":"where it is hidden 指物件被秘密或實際放置的地方。"},{"en":"A child may know where a birthday present is hidden, but the birthday boy does not.","zh":"孩子可能知道生日禮物被藏在哪裏，但壽星不知道。"},{"en":"Knowing the hidden location can make it hard to ignore one’s own knowledge.","zh":"知道隱藏位置會令人難以忽略自己的知識。"},{"en":"The phrase contrasts the child’s knowledge with the character’s ignorance.","zh":"這個短語把孩子的知識與角色的無知作對比。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":5},{"front":"to pass","meaning":"要通過測試","examples":[{"en":"To pass, the child must understand that another person’s mental representation differs from their own.","zh":"要通過測試，孩子必須明白另一個人的心理表徵與自己的不同。"},{"en":"To pass means to succeed in a test or task.","zh":"to pass 指在測驗或任務中成功。"},{"en":"To pass a spelling quiz, a student must write enough words correctly.","zh":"要通過串字測驗，學生必須正確寫出足夠字詞。"},{"en":"In a false-belief task, passing depends on understanding another mind, not just remembering the object.","zh":"在錯誤信念任務中，通過取決於理解另一個心智，而不只是記得物件。"},{"en":"The phrase introduces the condition for success.","zh":"這個短語引入成功條件。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":5},{"front":"mental representation","meaning":"心理表徵","examples":[{"en":"The child must understand that another person’s mental representation differs from their own.","zh":"孩子必須明白另一個人的心理表徵與自己的不同。"},{"en":"A mental representation is a person’s internal idea or picture of something.","zh":"mental representation 指某人心中對某事的內在想法或圖像。"},{"en":"A student’s mental representation of a classroom may include desks, a board, and classmates.","zh":"學生對課室的心理表徵可能包括桌子、白板和同學。"},{"en":"If two people have different information, their mental representations may not match.","zh":"如果兩個人有不同資訊，他們的心理表徵可能不一致。"},{"en":"The phrase refers to what exists in the mind, not the outside world itself.","zh":"這個短語指心中存在的東西，而不是外在世界本身。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":5},{"front":"differ from","meaning":"與……不同","examples":[{"en":"Another person’s mental representation may differ from the child’s own.","zh":"另一個人的心理表徵可能與孩子自己的不同。"},{"en":"To differ from something means to be unlike or not the same as it.","zh":"differ from something 指與某事不同或不一樣。"},{"en":"A student’s answer may differ from the teacher’s because she misunderstood the question.","zh":"學生答案可能與老師答案不同，因為她誤解了題目。"},{"en":"Different experiences cause people’s beliefs and memories to differ.","zh":"不同經驗會令人們的信念和記憶不同。"},{"en":"The phrase is useful for comparing two things that are not identical.","zh":"這個短語適合比較兩件不相同的事。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":5},{"front":"predict behaviour from","meaning":"根據……預測行為","examples":[{"en":"The child must predict behaviour from an understanding of another person’s belief.","zh":"孩子必須根據對另一人信念的理解來預測行為。"},{"en":"To predict behaviour from something means to use that information to guess what someone will do.","zh":"predict behaviour from something 指利用某資訊猜測某人會做甚麼。"},{"en":"A teacher may predict a student’s behaviour from how nervous he looks before a speech.","zh":"老師可能根據學生演講前看起來多緊張來預測其行為。"},{"en":"If you know someone believes the door is locked, you can predict they may look for a key.","zh":"如果你知道某人相信門已鎖上，你可以預測他可能會找鑰匙。"},{"en":"The phrase connects mental understanding with expected action.","zh":"這個短語把心理理解與預期行動連起來。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":5},{"front":"results from","meaning":"來自……的結果","examples":[{"en":"Results from false-belief tasks have been fairly consistent.","zh":"來自錯誤信念任務的結果頗為一致。"},{"en":"Results from something are the findings or outcomes produced by that test, study, or activity.","zh":"results from something 指由某測試、研究或活動產生的發現或結果。"},{"en":"Results from a class survey may show that students prefer shorter homework tasks.","zh":"來自班級調查的結果可能顯示學生偏好較短功課任務。"},{"en":"Consistent results make researchers more confident about a pattern.","zh":"一致結果令研究人員對某模式更有信心。"},{"en":"The phrase identifies the source of the findings.","zh":"這個短語指出發現的來源。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":5},{"front":"fairly consistent","meaning":"頗為一致","examples":[{"en":"Results from false-belief tasks have been fairly consistent.","zh":"來自錯誤信念任務的結果頗為一致。"},{"en":"Fairly consistent means mostly similar or stable across different cases.","zh":"fairly consistent 指在不同個案中大致相似或穩定。"},{"en":"A student’s marks are fairly consistent if she usually scores between 75 and 80.","zh":"如果學生通常得75至80分，她的分數頗為一致。"},{"en":"If several studies give similar results, the finding becomes harder to dismiss.","zh":"如果幾項研究得出相似結果，該發現就較難被否定。"},{"en":"The phrase allows small variation but stresses a clear pattern.","zh":"這個短語容許小變化，但強調清楚模式。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":5},{"front":"normally developing children","meaning":"正常發展的兒童","examples":[{"en":"Most normally developing children cannot pass false-belief tasks until around the age of four.","zh":"大多數正常發展的兒童直到大約四歲才能通過錯誤信念任務。"},{"en":"Normally developing children are children whose development follows the usual pattern for their age.","zh":"normally developing children 指發展符合該年齡通常模式的兒童。"},{"en":"Normally developing children usually learn basic language and social skills step by step.","zh":"正常發展的兒童通常逐步學會基本語言和社交技能。"},{"en":"Comparing groups helps researchers see whether a difficulty is typical or unusual.","zh":"比較不同群體幫助研究人員了解困難是典型還是異常。"},{"en":"The phrase is used in developmental research, not as a value judgement.","zh":"這個短語用於發展研究，不是價值判斷。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":6},{"front":"pass a task","meaning":"通過一項任務","examples":[{"en":"Most normally developing children cannot pass false-belief tasks until around the age of four.","zh":"大多數正常發展的兒童直到大約四歲才能通過錯誤信念任務。"},{"en":"To pass a task means to complete it successfully according to the test criteria.","zh":"pass a task 指按照測試標準成功完成任務。"},{"en":"A student passes a listening task if she chooses the correct answers from the recording.","zh":"如果學生根據錄音選出正確答案，她就通過聆聽任務。"},{"en":"Passing a task can show that a learner has gained a particular skill.","zh":"通過一項任務可以顯示學習者已掌握某技能。"},{"en":"The phrase focuses on successful performance in a specific activity.","zh":"這個短語重點是在特定活動中的成功表現。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":6},{"front":"until around the age of four","meaning":"直到大約四歲","examples":[{"en":"Children usually cannot pass these tasks until around the age of four.","zh":"兒童通常直到大約四歲才能通過這些任務。"},{"en":"Until around the age of four means not before approximately four years old.","zh":"until around the age of four 指大約四歲之前通常不能。"},{"en":"Some children do not read simple words independently until around the age of six.","zh":"有些孩子直到大約六歲才會獨立讀簡單字。"},{"en":"Age patterns help researchers understand when abilities normally appear.","zh":"年齡模式幫助研究人員理解能力通常何時出現。"},{"en":"The phrase gives an approximate developmental time.","zh":"這個短語提供約略發展時間。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":6},{"front":"before 18 months","meaning":"在18個月大之前","examples":[{"en":"Leslie argues that, before 18 months, children interpret the world literally.","zh":"Leslie 認為，在18個月大之前，兒童從字面上理解世界。"},{"en":"Before 18 months means earlier than one and a half years of age.","zh":"before 18 months 指早於一歲半。"},{"en":"Before 18 months, many infants communicate more through gestures than full sentences.","zh":"在18個月大之前，許多嬰幼兒更多透過手勢而非完整句子溝通。"},{"en":"Very young children may not yet separate pretend situations from real ones.","zh":"很年幼的兒童可能尚未把假裝情況與真實情況分開。"},{"en":"The phrase marks an early stage of development.","zh":"這個短語標示早期發展階段。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":6},{"front":"interpret the world literally","meaning":"從字面上理解世界","examples":[{"en":"Before 18 months, children interpret the world literally.","zh":"在18個月大之前，兒童從字面上理解世界。"},{"en":"To interpret the world literally means to understand things only as they really appear, not as pretend or symbolic.","zh":"interpret the world literally 指只按事物實際樣子理解，而不是按假裝或象徵意思理解。"},{"en":"A young child may think a banana is only a banana, even when an adult pretends it is a phone.","zh":"年幼孩子可能認為香蕉就只是香蕉，即使成年人假裝它是電話。"},{"en":"Literal interpretation makes pretend play harder because imagination must be separated from reality.","zh":"字面理解令假裝遊戲較困難，因為想像必須與現實分開。"},{"en":"The phrase describes a direct, non-pretend way of understanding.","zh":"這個短語描述直接、非假裝式理解。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":6},{"front":"engage in pretence","meaning":"參與假裝行為","examples":[{"en":"Before 18 months, children rarely engage in pretence.","zh":"在18個月大之前，兒童很少參與假裝行為。"},{"en":"To engage in pretence means to take part in make-believe behaviour.","zh":"engage in pretence 指參與假裝或扮演行為。"},{"en":"A child engages in pretence when she uses a spoon as a microphone.","zh":"當孩子把匙羹當成咪高峰使用，她就是在參與假裝行為。"},{"en":"Pretence requires the child to treat one thing as if it were another.","zh":"假裝需要孩子把一件東西當作另一件東西。"},{"en":"The phrase describes active participation in imagined play.","zh":"這個短語描述主動參與想像遊戲。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":6},{"front":"the cognitive system","meaning":"認知系統","examples":[{"en":"The cognitive system must distinguish pretence from reality.","zh":"認知系統必須區分假裝與現實。"},{"en":"The cognitive system is the mind’s system for thinking, remembering, understanding, and processing information.","zh":"cognitive system 指心智中負責思考、記憶、理解和處理資訊的系統。"},{"en":"A student’s cognitive system works when she reads a question, remembers a rule, and chooses an answer.","zh":"當學生閱讀題目、記起規則並選答案時，她的認知系統正在運作。"},{"en":"If the cognitive system cannot separate pretend from real, make-believe play becomes confusing.","zh":"如果認知系統不能把假裝與真實分開，假裝遊戲就會令人混亂。"},{"en":"The phrase refers to mental processing, not a physical machine.","zh":"這個短語指心理處理，而不是實體機器。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":6},{"front":"distinguish pretence from reality","meaning":"區分假裝與現實","examples":[{"en":"The cognitive system must distinguish pretence from reality.","zh":"認知系統必須區分假裝與現實。"},{"en":"To distinguish pretence from reality means to tell the difference between make-believe and what is actually true.","zh":"distinguish pretence from reality 指分辨假裝和真正事實之間的差別。"},{"en":"A child distinguishes pretence from reality when she knows a toy cup has no real tea inside.","zh":"當孩子知道玩具杯中沒有真正茶，她就在區分假裝與現實。"},{"en":"This skill lets children enjoy pretend play without confusing it with real events.","zh":"這項技能讓兒童享受假裝遊戲，而不會把它與真實事件混淆。"},{"en":"The phrase focuses on separating imagination from fact.","zh":"這個短語重點是把想像與事實分開。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":6},{"front":"without this capacity","meaning":"如果沒有這種能力","examples":[{"en":"Without this capacity, children could not separate imagination from the real world.","zh":"如果沒有這種能力，兒童就不能把想像與真實世界分開。"},{"en":"Without this capacity means if this ability did not exist.","zh":"without this capacity 指如果沒有這種能力。"},{"en":"Without the capacity to read instructions, students may complete the wrong task.","zh":"如果沒有閱讀指示的能力，學生可能完成錯誤任務。"},{"en":"If children lack this ability, pretend play may be confusing or impossible.","zh":"如果兒童缺乏這種能力，假裝遊戲可能令人混亂或無法進行。"},{"en":"The phrase introduces the result of not having an ability.","zh":"這個短語引入沒有某能力的結果。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":6},{"front":"separate imagination from the real world","meaning":"把想像與真實世界分開","examples":[{"en":"Children need this capacity to separate imagination from the real world.","zh":"兒童需要這種能力來把想像與真實世界分開。"},{"en":"To separate imagination from the real world means to know what is pretend and what is actually true.","zh":"separate imagination from the real world 指知道甚麼是假裝、甚麼是真實。"},{"en":"A child separates imagination from reality when she says, “This box is a castle, but only in the game.”","zh":"當孩子說「這個盒子在遊戲中是城堡，但其實只是盒子」時，她就在把想像與現實分開。"},{"en":"This separation makes pretend play safe and understandable.","zh":"這種分隔令假裝遊戲安全而可理解。"},{"en":"The phrase describes a key mental boundary.","zh":"這個短語描述重要的心理界線。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":6},{"front":"pretend play","meaning":"假裝遊戲","examples":[{"en":"Leslie suggests that pretend play becomes possible through a decoupler.","zh":"Leslie 認為假裝遊戲透過解耦器而變得可能。"},{"en":"Pretend play is play in which children imagine one thing as another or act out unreal situations.","zh":"pretend play 指兒童把一物想像成另一物或演繹非真實情境的遊戲。"},{"en":"A child engages in pretend play when a chair becomes a bus and classmates become passengers.","zh":"當孩子把椅子當成巴士、同學當成乘客時，就是在玩假裝遊戲。"},{"en":"Pretend play helps children practise roles, language, and social understanding.","zh":"假裝遊戲幫助兒童練習角色、語言和社交理解。"},{"en":"The phrase refers to make-believe play, not lying.","zh":"這個短語指扮演遊戲，而不是說謊。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":6},{"front":"become possible through","meaning":"透過……而變得可能","examples":[{"en":"Pretend play becomes possible through a decoupler.","zh":"假裝遊戲透過解耦器而變得可能。"},{"en":"Become possible through means can happen because of a particular mechanism, tool, or condition.","zh":"become possible through 指因某種機制、工具或條件而能夠發生。"},{"en":"Online lessons become possible through stable internet and video platforms.","zh":"網上課堂透過穩定網絡和視像平台而變得可能。"},{"en":"If a mental mechanism separates pretend from reality, imagined play can begin.","zh":"如果心理機制把假裝與現實分開，想像遊戲就能開始。"},{"en":"The phrase links a result to the thing that enables it.","zh":"這個短語把結果與使其成為可能的事物連起來。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":7},{"front":"a decoupler","meaning":"解耦器；分離機制","examples":[{"en":"A decoupler copies primary representations into secondary ones.","zh":"解耦器把初級表徵複製成次級表徵。"},{"en":"A decoupler is a proposed mental mechanism that separates pretend ideas from real-world representations.","zh":"decoupler 指一種假設的心理機制，用來把假裝想法與現實世界表徵分開。"},{"en":"In pretend play, a child may treat a banana as a phone while still knowing it is a banana.","zh":"在假裝遊戲中，孩子可能把香蕉當電話，同時仍知道它是香蕉。"},{"en":"The decoupler prevents pretend information from being confused with reality.","zh":"解耦器防止假裝資訊與現實混淆。"},{"en":"The phrase is technical and belongs to Leslie’s theory of pretend play.","zh":"這個短語較技術性，屬於 Leslie 的假裝遊戲理論。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":7},{"front":"primary representations","meaning":"初級表徵","examples":[{"en":"The decoupler copies primary representations into secondary ones.","zh":"解耦器把初級表徵複製成次級表徵。"},{"en":"Primary representations are basic mental representations of what is actually true or directly perceived.","zh":"primary representations 指關於實際真相或直接感知內容的基本心理表徵。"},{"en":"A child’s primary representation may be that the banana is a piece of fruit.","zh":"孩子的初級表徵可能是香蕉是一種水果。"},{"en":"These representations provide the real-world base before pretend meaning is added.","zh":"這些表徵在加入假裝意思前提供現實基礎。"},{"en":"The phrase refers to the first, reality-based mental picture.","zh":"這個短語指最初、基於現實的心理圖像。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":7},{"front":"secondary representations","meaning":"次級表徵","examples":[{"en":"A child creates a secondary representation of the banana.","zh":"孩子創造香蕉的次級表徵。"},{"en":"Secondary representations are copied mental representations used for pretend or imagined meanings.","zh":"secondary representations 指用於假裝或想像意思的複製心理表徵。"},{"en":"A child may create a secondary representation in which a box is a spaceship.","zh":"孩子可能創造一個盒子是太空船的次級表徵。"},{"en":"These representations allow children to play with ideas without changing what they know is real.","zh":"這些表徵讓兒童玩弄想法，而不改變他們知道的現實。"},{"en":"The phrase refers to an imagined version of reality.","zh":"這個短語指現實的想像版本。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":7},{"front":"pretend that","meaning":"假裝……","examples":[{"en":"A child may pretend that a banana is a telephone.","zh":"孩子可能假裝香蕉是電話。"},{"en":"To pretend that something is true means to act as if it were true while knowing it is not really true.","zh":"pretend that something is true 指明知某事不是真的，仍把它當作真的來行動。"},{"en":"Children may pretend that a blanket is a tent during a game.","zh":"孩子可能在遊戲中假裝毛毯是帳篷。"},{"en":"Pretending lets children practise language, roles, and imagination.","zh":"假裝讓兒童練習語言、角色和想像力。"},{"en":"The phrase describes make-believe, not genuine belief.","zh":"這個短語描述扮演，而不是真正相信。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":7},{"front":"manipulate that representation","meaning":"操作該表徵","examples":[{"en":"The child manipulates that representation during pretend play.","zh":"孩子在假裝遊戲中操作該表徵。"},{"en":"To manipulate that representation means to change or use the mental image in imagination.","zh":"manipulate that representation 指在想像中改變或使用該心理圖像。"},{"en":"A child may imagine a cardboard box first as a car and then as a boat.","zh":"孩子可能先把紙箱想像成汽車，再想像成船。"},{"en":"Manipulating representations lets children create flexible stories during play.","zh":"操作表徵讓兒童在遊戲中創造靈活故事。"},{"en":"The phrase describes mental handling of an idea, not physical touching.","zh":"這個短語描述心理上處理想法，而不是實際觸摸。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":7},{"front":"stored knowledge about","meaning":"關於……的已儲存知識","examples":[{"en":"The child uses stored knowledge about telephones to elaborate the pretence.","zh":"孩子使用關於電話的已儲存知識，使假裝情節更豐富。"},{"en":"Stored knowledge about something is information already kept in memory about it.","zh":"stored knowledge about something 指記憶中已保存的相關資訊。"},{"en":"A student uses stored knowledge about restaurants when role-playing a waiter and customer.","zh":"學生扮演侍應和顧客時，會使用關於餐廳的已儲存知識。"},{"en":"Prior knowledge helps children add realistic details to pretend situations.","zh":"先前知識幫助兒童為假裝情境加入真實細節。"},{"en":"The phrase refers to remembered information that supports later thinking.","zh":"這個短語指支援之後思考的記憶資訊。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":7},{"front":"elaborate the pretence","meaning":"使假裝情節更豐富","examples":[{"en":"The child uses knowledge about telephones to elaborate the pretence.","zh":"孩子使用關於電話的知識，使假裝情節更豐富。"},{"en":"To elaborate the pretence means to make the pretend situation more detailed and developed.","zh":"elaborate the pretence 指令假裝情境更詳細和更發展。"},{"en":"A child may elaborate the pretence by saying the banana-phone is ringing and someone is calling.","zh":"孩子可能說香蕉電話正在響、有人打來，從而豐富假裝情節。"},{"en":"Adding details makes pretend play richer and more believable within the game.","zh":"加入細節令假裝遊戲在遊戲內更豐富、更可信。"},{"en":"The phrase focuses on expanding make-believe.","zh":"這個短語重點是擴展扮演情境。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":7},{"front":"there is evidence that","meaning":"有證據顯示","examples":[{"en":"There is also evidence that social processes contribute to the development of theory of mind.","zh":"亦有證據顯示社交過程促進心智理論的發展。"},{"en":"There is evidence that means research or facts support the idea that something is true.","zh":"there is evidence that 指研究或事實支持某想法為真。"},{"en":"There is evidence that regular reading improves vocabulary over time.","zh":"有證據顯示定期閱讀會隨時間改善詞彙。"},{"en":"Evidence makes a claim stronger than personal opinion alone.","zh":"證據令聲稱比單純個人意見更有力。"},{"en":"The phrase introduces support for a statement.","zh":"這個短語引入對陳述的支持。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":7},{"front":"social processes","meaning":"社交過程","examples":[{"en":"Social processes contribute to the development of theory of mind.","zh":"社交過程促進心智理論的發展。"},{"en":"Social processes are interactions and experiences with other people that shape development.","zh":"social processes 指與他人互動和經驗，並會塑造發展。"},{"en":"Talking with parents, playing with siblings, and arguing with friends are social processes.","zh":"與父母交談、與兄弟姊妹玩耍、與朋友爭論都是社交過程。"},{"en":"These processes may help children notice that different people think and feel differently.","zh":"這些過程可能幫助兒童注意到不同人有不同想法和感受。"},{"en":"The phrase focuses on learning through relationships.","zh":"這個短語重點是透過關係學習。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":7},{"front":"contribute to the development of","meaning":"促進……的發展","examples":[{"en":"Social processes contribute to the development of theory of mind.","zh":"社交過程促進心智理論的發展。"},{"en":"To contribute to the development of something means to help it grow or improve.","zh":"contribute to the development of something 指幫助某事成長或改善。"},{"en":"Reading stories can contribute to the development of children’s vocabulary.","zh":"閱讀故事可以促進兒童詞彙發展。"},{"en":"Repeated social interaction gives children practice in understanding other minds.","zh":"重複社交互動讓兒童練習理解他人心智。"},{"en":"The phrase shows that one factor supports a developmental process.","zh":"這個短語顯示某因素支持發展過程。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":7},{"front":"mind-mindedness","meaning":"重視心理狀態的傾向","examples":[{"en":"Meins and her colleagues studied mind-mindedness in mothers’ speech.","zh":"Meins 和她的同事研究母親說話中的重視心理狀態傾向。"},{"en":"Mind-mindedness is the tendency to treat a child as having thoughts, feelings, and mental states.","zh":"mind-mindedness 指把孩子視為有想法、感受和心理狀態的傾向。"},{"en":"A mother shows mind-mindedness when she says, “You look curious about that toy.”","zh":"當母親說「你看起來對那個玩具有點好奇」時，她展現了 mind-mindedness。"},{"en":"Such speech may help children learn that behaviour is linked to feelings and thoughts.","zh":"這類說話可能幫助孩子學會行為與感受和想法有關。"},{"en":"The phrase describes attention to another person’s inner mind.","zh":"這個短語描述對另一人內在心智的關注。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":8},{"front":"mothers’ speech to infants","meaning":"母親對嬰兒說話的方式","examples":[{"en":"Mind-mindedness in mothers’ speech to infants is related to later theory-of-mind ability.","zh":"母親對嬰兒說話中的重視心理狀態傾向，與之後的心智理論能力有關。"},{"en":"Mothers’ speech to infants means the way mothers talk to very young babies.","zh":"mothers’ speech to infants 指母親與很年幼嬰兒說話的方式。"},{"en":"A mother may speak gently to an infant and describe what the baby seems to feel.","zh":"母親可能溫柔地對嬰兒說話，並描述嬰兒似乎感受到甚麼。"},{"en":"Early speech can shape how children learn about emotions, attention, and communication.","zh":"早期說話可以塑造兒童如何學習情緒、注意力和溝通。"},{"en":"The phrase focuses on language used by mothers with babies.","zh":"這個短語重點是母親對嬰兒使用的語言。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":8},{"front":"six-month-old infants","meaning":"六個月大的嬰兒","examples":[{"en":"The researchers studied mothers’ speech to six-month-old infants.","zh":"研究人員研究母親對六個月大的嬰兒說話的方式。"},{"en":"Six-month-old infants are babies who are about half a year old.","zh":"six-month-old infants 指大約半歲的嬰兒。"},{"en":"A six-month-old infant may respond to voices, faces, and simple games.","zh":"六個月大的嬰兒可能會對聲音、面孔和簡單遊戲作出反應。"},{"en":"Studying infants helps researchers see how social understanding begins early.","zh":"研究嬰兒幫助研究人員了解社交理解如何早期開始。"},{"en":"The phrase identifies a very young age group.","zh":"這個短語指出非常年幼的年齡群。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":8},{"front":"be related to","meaning":"與……有關","examples":[{"en":"Mind-mindedness is related to secure attachment and later theory-of-mind ability.","zh":"重視心理狀態的傾向與安全依附和之後的心智理論能力有關。"},{"en":"To be related to something means to have a connection with it.","zh":"be related to something 指與某事有聯繫。"},{"en":"A student’s confidence may be related to how teachers respond to mistakes.","zh":"學生信心可能與老師如何回應錯誤有關。"},{"en":"If two things are related, one may help explain or influence the other.","zh":"如果兩件事有關，其中一件可能幫助解釋或影響另一件。"},{"en":"The phrase shows connection, not always direct proof of cause.","zh":"這個短語顯示關聯，不一定直接證明因果。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":8},{"front":"secure attachment","meaning":"安全依附","examples":[{"en":"Mind-minded speech is related to secure attachment.","zh":"重視心理狀態的說話與安全依附有關。"},{"en":"Secure attachment is a strong, trusting emotional bond between a child and caregiver.","zh":"secure attachment 指兒童與照顧者之間強烈而信任的情感連結。"},{"en":"A securely attached child may feel safe exploring because a parent is available for comfort.","zh":"有安全依附的孩子可能因知道父母可提供安慰，而安心探索。"},{"en":"Secure attachment can support confidence, communication, and emotional regulation.","zh":"安全依附可以支援信心、溝通和情緒調節。"},{"en":"The phrase describes a healthy relationship pattern in early development.","zh":"這個短語描述早期發展中的健康關係模式。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":8},{"front":"later ToM ability","meaning":"其後的心智理論能力","examples":[{"en":"Mind-mindedness is related to later ToM ability.","zh":"重視心理狀態的傾向與其後的心智理論能力有關。"},{"en":"Later ToM ability means theory-of-mind skill that appears or is measured at a later stage.","zh":"later ToM ability 指在較後階段出現或被量度的心智理論能力。"},{"en":"A child’s early conversations may be linked to later ToM ability in preschool.","zh":"兒童早期對話可能與學前階段其後的心智理論能力有關。"},{"en":"If early speech supports mental-state understanding, children may perform better later.","zh":"如果早期說話支援心理狀態理解，兒童之後可能表現更好。"},{"en":"The phrase connects early experience with later social-cognitive skill.","zh":"這個短語把早期經驗與其後社交認知能力連起來。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":8},{"front":"mind-minded speech","meaning":"重視心理狀態的說話","examples":[{"en":"Mind-minded speech discusses an infant’s feelings.","zh":"重視心理狀態的說話會談及嬰兒的感受。"},{"en":"Mind-minded speech is speech that talks about a child’s thoughts, feelings, desires, or intentions.","zh":"mind-minded speech 指談及孩子想法、感受、願望或意圖的說話方式。"},{"en":"A parent uses mind-minded speech by saying, “You want the ball because it rolled away.”","zh":"父母說「你想要那個球，因為它滾走了」就是使用重視心理狀態的說話。"},{"en":"This kind of speech may help children connect behaviour with inner states.","zh":"這種說話可能幫助兒童把行為與內在狀態連起來。"},{"en":"The phrase describes language that treats the child as having a mind.","zh":"這個短語描述把孩子視為有心智的語言。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":8},{"front":"discuss an infant’s feelings","meaning":"談及嬰兒的感受","examples":[{"en":"Mind-minded speech discusses an infant’s feelings.","zh":"重視心理狀態的說話會談及嬰兒的感受。"},{"en":"To discuss an infant’s feelings means to talk about what the baby may be feeling.","zh":"discuss an infant’s feelings 指談論嬰兒可能正在感受甚麼。"},{"en":"A mother may say, “You look upset because the toy fell.”","zh":"母親可能說：「你看起來不開心，因為玩具掉下來了。」"},{"en":"Naming feelings can help children later learn words for emotions.","zh":"命名感受可以幫助兒童日後學習情緒詞語。"},{"en":"The phrase shows adults treating babies as emotional beings.","zh":"這個短語顯示成年人把嬰兒視為有情感的個體。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":8},{"front":"explain behaviour in terms of","meaning":"以……來解釋行為","examples":[{"en":"Mind-minded speech explains behaviour in terms of mental states.","zh":"重視心理狀態的說話以心理狀態來解釋行為。"},{"en":"To explain behaviour in terms of something means to use that factor as the reason for an action.","zh":"explain behaviour in terms of something 指用某因素作為行為原因來解釋。"},{"en":"A teacher may explain a student’s silence in terms of shyness rather than laziness.","zh":"老師可能以害羞而非懶惰來解釋學生沉默。"},{"en":"Explaining behaviour through mental states helps children understand why people act as they do.","zh":"透過心理狀態解釋行為，幫助兒童理解人們為何如此行動。"},{"en":"The phrase links outward action with an inner cause.","zh":"這個短語把外在行動與內在原因連起來。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":8},{"front":"mental states","meaning":"心理狀態","examples":[{"en":"Mind-minded speech explains behaviour in terms of mental states.","zh":"重視心理狀態的說話以心理狀態來解釋行為。"},{"en":"Mental states are inner conditions such as beliefs, desires, feelings, intentions, and knowledge.","zh":"mental states 指信念、願望、感受、意圖和知識等內在狀態。"},{"en":"A child’s mental state may be fear if she hides behind a parent in a new classroom.","zh":"如果孩子在新課室躲在父母身後，她的心理狀態可能是害怕。"},{"en":"Understanding mental states helps people explain behaviour that is not obvious from the outside.","zh":"理解心理狀態幫助人們解釋外表不明顯的行為。"},{"en":"The phrase refers to what happens inside the mind.","zh":"這個短語指心裏發生的事情。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":8},{"front":"extended families","meaning":"大家庭","examples":[{"en":"Lewis investigated older children living in extended families in Crete and Cyprus.","zh":"Lewis 研究住在克里特島和塞浦路斯大家庭中的較年長兒童。"},{"en":"Extended families are families that include relatives beyond parents and children, such as grandparents, aunts, uncles, or cousins.","zh":"extended families 指包括父母和子女以外親人的家庭，例如祖父母、叔伯姨舅或表兄弟姊妹。"},{"en":"A child in an extended family may talk daily with grandparents and older cousins.","zh":"大家庭中的孩子可能每天與祖父母和年長表兄姊交談。"},{"en":"More family members can create more chances for social interaction and perspective-taking.","zh":"更多家庭成員可以創造更多社交互動和換位思考機會。"},{"en":"The phrase contrasts larger family networks with nuclear families.","zh":"這個短語把較大親屬網絡與核心家庭作對比。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":8},{"front":"interact socially with","meaning":"與……進行社交互動","examples":[{"en":"Children who interacted socially with more adults passed theory-of-mind tasks earlier.","zh":"與更多成年人進行社交互動的兒童較早通過心智理論任務。"},{"en":"To interact socially with people means to talk, play, cooperate, or communicate with them.","zh":"interact socially with people 指與人交談、玩耍、合作或溝通。"},{"en":"A child interacts socially with classmates when sharing toys or discussing a game.","zh":"孩子分享玩具或討論遊戲時，就是與同學進行社交互動。"},{"en":"More interaction gives children practice in understanding different opinions and feelings.","zh":"更多互動讓兒童練習理解不同意見和感受。"},{"en":"The phrase focuses on social contact, not just being near someone.","zh":"這個短語重點是社交接觸，而不只是靠近某人。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":9},{"front":"have older siblings","meaning":"有年長兄弟姊妹","examples":[{"en":"Children who had older siblings tended to pass theory-of-mind tasks slightly earlier.","zh":"有年長兄弟姊妹的兒童往往稍早通過心智理論任務。"},{"en":"To have older siblings means to have brothers or sisters who are older than oneself.","zh":"have older siblings 指有比自己年長的兄弟或姊妹。"},{"en":"A child with older siblings may learn games, arguments, and explanations from them.","zh":"有年長兄弟姊妹的孩子可能從他們身上學習遊戲、爭論和解釋。"},{"en":"Older siblings can expose younger children to more complex conversations and pretend play.","zh":"年長兄弟姊妹可以讓年幼孩子接觸更複雜對話和假裝遊戲。"},{"en":"The phrase identifies a family factor that may affect development.","zh":"這個短語指出可能影響發展的家庭因素。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":9},{"front":"tend to pass","meaning":"往往會通過","examples":[{"en":"Children with more social interaction tended to pass theory-of-mind tasks earlier.","zh":"有更多社交互動的兒童往往較早通過心智理論任務。"},{"en":"Tend to pass means usually succeed in a task or test.","zh":"tend to pass 指通常能成功完成任務或測驗。"},{"en":"Students who practise listening daily tend to pass oral exams more confidently.","zh":"每天練習聆聽的學生往往更有信心通過口試。"},{"en":"A tendency shows a general pattern, not a guarantee for every person.","zh":"傾向顯示一般模式，而不是保證每個人都如此。"},{"en":"The phrase is useful for reporting research findings cautiously.","zh":"這個短語適合謹慎報告研究發現。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":9},{"front":"at a slightly earlier age","meaning":"在稍早的年齡","examples":[{"en":"These children tended to pass theory-of-mind tasks at a slightly earlier age.","zh":"這些兒童往往在稍早的年齡通過心智理論任務。"},{"en":"At a slightly earlier age means a little younger than the usual or comparison group.","zh":"at a slightly earlier age 指比通常或比較群體稍微年幼一點時。"},{"en":"A child with many books at home may learn to read at a slightly earlier age.","zh":"家中有許多書的孩子可能在稍早年齡學會閱讀。"},{"en":"Small differences in age can still matter in developmental research.","zh":"在發展研究中，小小年齡差異仍可能重要。"},{"en":"The phrase describes a modest timing advantage.","zh":"這個短語描述輕微的時間優勢。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":9},{"front":"be more likely to","meaning":"更有可能","examples":[{"en":"Young children are more likely to discuss their thoughts and feelings with peers.","zh":"年幼兒童更有可能與同輩討論自己的想法和感受。"},{"en":"To be more likely to do something means to have a higher chance of doing it.","zh":"be more likely to do something 指做某事的機會較高。"},{"en":"Students are more likely to ask questions when the classroom feels safe.","zh":"當課室感覺安全，學生更有可能提問。"},{"en":"If children talk more with peers, they may get more practice explaining mental states.","zh":"如果兒童更多與同輩交談，他們可能得到更多練習解釋心理狀態。"},{"en":"The phrase describes increased probability, not certainty.","zh":"這個短語描述較高可能性，而不是確定性。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":9},{"front":"discuss one’s thoughts and feelings","meaning":"討論自己的想法和感受","examples":[{"en":"Young children often discuss their thoughts and feelings with peers.","zh":"年幼兒童常與同輩討論自己的想法和感受。"},{"en":"To discuss one’s thoughts and feelings means to talk about what one thinks and how one feels.","zh":"discuss one’s thoughts and feelings 指談論自己在想甚麼和感覺如何。"},{"en":"Friends may discuss their thoughts and feelings after an argument to understand each other better.","zh":"朋友爭吵後可能討論自己的想法和感受，以更好理解彼此。"},{"en":"Talking about inner experiences helps children learn words for mental states.","zh":"談論內在經驗幫助兒童學習心理狀態詞語。"},{"en":"The phrase describes emotional and mental communication.","zh":"這個短語描述情緒和心理溝通。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":9},{"front":"with peers","meaning":"與同輩","examples":[{"en":"Young children discuss their thoughts and feelings with peers.","zh":"年幼兒童與同輩討論自己的想法和感受。"},{"en":"With peers means with people of similar age, status, or level.","zh":"with peers 指與年齡、地位或水平相近的人一起。"},{"en":"Students may learn new study habits with peers during group revision.","zh":"學生可能在小組溫習中與同輩學到新學習習慣。"},{"en":"Peer interaction can be different from adult interaction because children must negotiate more equally.","zh":"同輩互動可以不同於成人互動，因為兒童必須更平等地協商。"},{"en":"The phrase identifies who the interaction happens with.","zh":"這個短語指出互動對象。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":9},{"front":"provide a special impetus for","meaning":"為……提供特殊推動力","examples":[{"en":"Interaction with peers may provide a special impetus for theory-of-mind development.","zh":"與同輩互動可能為心智理論發展提供特殊推動力。"},{"en":"To provide a special impetus for something means to give it a particular push or encouragement.","zh":"provide a special impetus for something 指為某事提供特別推動或鼓勵。"},{"en":"A school competition may provide a special impetus for students to practise public speaking.","zh":"學校比賽可能為學生練習公開演說提供特殊推動力。"},{"en":"Peer conflict can push children to explain what they want, think, and feel.","zh":"同輩衝突可以推動兒童解釋自己想要、相信和感受甚麼。"},{"en":"The phrase describes a factor that speeds up or strengthens development.","zh":"這個短語描述加快或加強發展的因素。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":9},{"front":"make a similar point","meaning":"提出類似觀點","examples":[{"en":"Dunn makes a similar point about peer interaction.","zh":"Dunn 對同輩互動提出類似觀點。"},{"en":"To make a similar point means to express a related or nearly same idea.","zh":"make a similar point 指表達相關或幾乎相同的想法。"},{"en":"Two teachers may make a similar point when both say students need more practice.","zh":"如果兩位老師都說學生需要更多練習，他們就是提出類似觀點。"},{"en":"Similar points from different researchers can strengthen an argument.","zh":"不同研究人員提出類似觀點，可以加強論證。"},{"en":"The phrase connects one person’s view with another’s.","zh":"這個短語把一個人的看法與另一個人的連起來。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":9},{"front":"peer interaction","meaning":"同輩互動","examples":[{"en":"Peer interaction is more likely to include pretend play.","zh":"同輩互動較有可能包括假裝遊戲。"},{"en":"Peer interaction means social contact and communication between people of similar age or status.","zh":"peer interaction 指年齡或地位相近的人之間的社交接觸和溝通。"},{"en":"Children have peer interaction when they build a tower together and decide who does what.","zh":"孩子一起搭塔並決定誰做甚麼時，就是在進行同輩互動。"},{"en":"Peer interaction can require children to explain ideas without adult help.","zh":"同輩互動可以要求兒童在沒有成人幫助下解釋想法。"},{"en":"The phrase focuses on child-to-child social experience.","zh":"這個短語重點是兒童之間的社交經驗。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":9},{"front":"be more likely to include","meaning":"較有可能包括","examples":[{"en":"Peer interaction is more likely to include pretend play.","zh":"同輩互動較有可能包括假裝遊戲。"},{"en":"Be more likely to include means have a higher chance of containing something.","zh":"be more likely to include 指較大機會包含某事物。"},{"en":"A creative writing lesson is more likely to include stories than a grammar drill.","zh":"創意寫作課比文法操練較有可能包括故事。"},{"en":"If peer interaction includes pretend play, children practise imagining different roles.","zh":"如果同輩互動包括假裝遊戲，兒童就練習想像不同角色。"},{"en":"The phrase compares what is common in one situation with another.","zh":"這個短語比較某情況中較常出現的內容。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":9},{"front":"be more challenging","meaning":"更具挑戰性","examples":[{"en":"Peer interaction may be more challenging than interaction with adults.","zh":"同輩互動可能比與成人互動更具挑戰性。"},{"en":"Be more challenging means be more difficult and require more effort or skill.","zh":"be more challenging 指更困難，需要更多努力或技能。"},{"en":"Group work with classmates can be more challenging than listening to a teacher because students must negotiate.","zh":"與同學做小組工作可能比聽老師講課更具挑戰性，因為學生必須協商。"},{"en":"Challenge can promote learning when children must explain, disagree, and adjust.","zh":"當兒童必須解釋、不同意和調整時，挑戰可以促進學習。"},{"en":"The phrase does not mean worse; it means harder in a useful way.","zh":"這個短語不代表更差，而是以有用方式更困難。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":10},{"front":"make large adjustments for","meaning":"為……作出大幅調整","examples":[{"en":"Adults make large adjustments for a child’s communicative needs.","zh":"成人會為孩子的溝通需要作出大幅調整。"},{"en":"To make large adjustments for someone means to change one’s behaviour greatly to suit that person.","zh":"make large adjustments for someone 指大幅改變自己的行為以配合某人。"},{"en":"A teacher may make large adjustments for a beginner by speaking slowly and using pictures.","zh":"老師可能透過放慢說話和使用圖片，為初學者作出大幅調整。"},{"en":"If adults adjust too much, children may face less pressure to explain themselves clearly.","zh":"如果成人調整太多，兒童可能面對較少壓力去清楚解釋自己。"},{"en":"The phrase describes strong accommodation.","zh":"這個短語描述高度遷就。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":10},{"front":"communicative needs","meaning":"溝通需要","examples":[{"en":"Adults often adjust their speech for a child’s communicative needs.","zh":"成人常為孩子的溝通需要調整說話方式。"},{"en":"Communicative needs are the language, listening, and understanding support a person needs to communicate.","zh":"communicative needs 指一個人溝通所需的語言、聆聽和理解支援。"},{"en":"A young child’s communicative needs may include short sentences, gestures, and repeated words.","zh":"年幼孩子的溝通需要可能包括短句、手勢和重複字詞。"},{"en":"Meeting communicative needs helps conversation continue smoothly.","zh":"滿足溝通需要有助對話順利繼續。"},{"en":"The phrase focuses on what makes communication possible.","zh":"這個短語重點是使溝通成為可能的需要。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":10},{"front":"there is concern that","meaning":"有人擔心","examples":[{"en":"There is concern that some aspects of the ToM approach underestimate children’s understanding.","zh":"有人擔心心智理論取向的某些方面低估兒童的理解。"},{"en":"There is concern that means some people are worried that a problem may exist.","zh":"there is concern that 指有人擔心某問題可能存在。"},{"en":"There is concern that too much homework may reduce students’ sleep.","zh":"有人擔心太多功課可能減少學生睡眠。"},{"en":"Concern often leads researchers to question old methods or interpretations.","zh":"擔憂常促使研究人員質疑舊方法或詮釋。"},{"en":"The phrase introduces a cautious criticism.","zh":"這個短語引入謹慎批評。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":10},{"front":"some aspects of","meaning":"……的某些方面","examples":[{"en":"Some aspects of the ToM approach may underestimate children’s understanding.","zh":"心智理論取向的某些方面可能低估兒童的理解。"},{"en":"Some aspects of something are particular parts or features of it.","zh":"some aspects of something 指某事的特定部分或特徵。"},{"en":"Some aspects of online learning help shy students, while others make group work harder.","zh":"網上學習的某些方面幫助害羞學生，而另一些方面令小組工作更難。"},{"en":"Looking at only one aspect can lead to an unfair judgement.","zh":"只看一個方面可能導致不公平判斷。"},{"en":"The phrase lets writers discuss part of a topic, not the whole thing.","zh":"這個短語讓作者討論主題的一部分，而不是整體。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":10},{"front":"the ToM approach","meaning":"心智理論取向","examples":[{"en":"The ToM approach may underestimate children’s understanding of other people.","zh":"心智理論取向可能低估兒童對他人的理解。"},{"en":"The ToM approach is the research approach that explains social understanding through theory of mind.","zh":"ToM approach 指透過心智理論解釋社交理解的研究取向。"},{"en":"A psychologist using the ToM approach may test whether a child understands false beliefs.","zh":"使用心智理論取向的心理學家可能測試孩子是否理解錯誤信念。"},{"en":"If the approach relies too much on formal tasks, it may miss everyday social skills.","zh":"如果該取向過分依賴正式任務，它可能錯過日常社交技能。"},{"en":"The phrase names a particular way of studying children’s understanding.","zh":"這個短語命名研究兒童理解的一種特定方式。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":10},{"front":"underestimate children’s understanding of","meaning":"低估兒童對……的理解","examples":[{"en":"The ToM approach may underestimate children’s understanding of other people.","zh":"心智理論取向可能低估兒童對他人的理解。"},{"en":"To underestimate children’s understanding of something means to think children understand less than they really do.","zh":"underestimate children’s understanding of something 指以為兒童理解得比實際少。"},{"en":"Adults may underestimate children’s understanding of fairness when they ignore children’s complaints.","zh":"成人忽視孩子投訴時，可能低估兒童對公平的理解。"},{"en":"If researchers use tasks that are too hard, they may misjudge children’s real ability.","zh":"如果研究人員使用太難的任務，他們可能錯判兒童真正能力。"},{"en":"The phrase warns that children may know more than test results suggest.","zh":"這個短語提醒兒童可能比測試結果顯示知道得更多。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":10},{"front":"point to objects","meaning":"指向物件","examples":[{"en":"Infants point to objects to redirect another person’s gaze and interest.","zh":"嬰兒指向物件，以轉移別人的目光和興趣。"},{"en":"To point to objects means to use a finger or gesture to show where something is.","zh":"point to objects 指用手指或手勢顯示某物在哪裡。"},{"en":"A baby may point to a dog so a parent will look at it too.","zh":"嬰兒可能指向狗，讓父母也看它。"},{"en":"Pointing can show that infants want to share attention with another person.","zh":"指向可以顯示嬰兒想與另一人分享注意力。"},{"en":"The phrase describes a simple but important social gesture.","zh":"這個短語描述簡單但重要的社交手勢。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":10},{"front":"apparently to","meaning":"看來是為了","examples":[{"en":"Infants point to objects, apparently to redirect another person’s gaze.","zh":"嬰兒指向物件，看來是為了轉移別人的目光。"},{"en":"Apparently to means seemingly for the purpose of doing something.","zh":"apparently to 指看似為了做某事。"},{"en":"A child may bring a book to a parent, apparently to ask for a story.","zh":"孩子把書拿給父母，看來是為了要求講故事。"},{"en":"The word apparently shows the purpose is inferred from behaviour, not directly stated.","zh":"apparently 顯示目的由行為推斷，而不是直接說出。"},{"en":"The phrase is useful when describing likely intention cautiously.","zh":"這個短語適合謹慎描述可能意圖。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":10},{"front":"redirect another person’s gaze","meaning":"轉移別人的目光","examples":[{"en":"Infants point to objects to redirect another person’s gaze.","zh":"嬰兒指向物件，以轉移別人的目光。"},{"en":"To redirect another person’s gaze means to make someone look at a different thing.","zh":"redirect another person’s gaze 指令某人看向另一件事物。"},{"en":"A student may point at the board to redirect a classmate’s gaze to the answer.","zh":"學生可能指向白板，把同學的目光轉移到答案上。"},{"en":"Redirecting gaze helps people share attention and communicate without many words.","zh":"轉移目光幫助人們分享注意力，並在沒有太多語言下溝通。"},{"en":"The phrase describes guiding someone’s visual attention.","zh":"這個短語描述引導某人的視覺注意。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":10},{"front":"interact effectively with","meaning":"與……有效互動","examples":[{"en":"Infants interact effectively with others.","zh":"嬰兒能與他人有效互動。"},{"en":"To interact effectively with others means to communicate or respond in a way that works well socially.","zh":"interact effectively with others 指以社交上有效的方式溝通或回應。"},{"en":"A child interacts effectively with classmates when she takes turns and listens during a game.","zh":"孩子在遊戲中輪流和聆聽，就是與同學有效互動。"},{"en":"Effective interaction can build trust and help people understand one another.","zh":"有效互動可以建立信任並幫助人們互相理解。"},{"en":"The phrase focuses on successful social communication.","zh":"這個短語重點是成功社交溝通。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":10},{"front":"express ideas that oppose","meaning":"表達反對……的想法","examples":[{"en":"Infants can express ideas that oppose other people’s wishes.","zh":"嬰兒能表達反對別人意願的想法。"},{"en":"To express ideas that oppose something means to show disagreement with it.","zh":"express ideas that oppose something 指顯示不同意某事。"},{"en":"A child may shake his head to express an idea that opposes a parent’s request.","zh":"孩子可能搖頭來表達反對父母要求的想法。"},{"en":"Opposing another person’s wish shows that the child has a separate preference.","zh":"反對另一人的意願顯示孩子有獨立偏好。"},{"en":"The phrase describes communication of disagreement.","zh":"這個短語描述不同意的溝通。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":11},{"front":"other people’s wishes","meaning":"別人的意願","examples":[{"en":"Infants sometimes express ideas that oppose other people’s wishes.","zh":"嬰兒有時表達反對別人意願的想法。"},{"en":"Other people’s wishes are what other people want to happen.","zh":"other people’s wishes 指別人希望發生的事情。"},{"en":"A parent may wish a child to sleep, while the child wants to keep playing.","zh":"父母可能希望孩子睡覺，而孩子想繼續玩。"},{"en":"Understanding others’ wishes is part of learning that minds differ.","zh":"理解別人的意願，是學習心智不同的一部分。"},{"en":"The phrase refers to desires belonging to someone else.","zh":"這個短語指屬於其他人的願望。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":11},{"front":"show empathy for","meaning":"對……表現出同理心","examples":[{"en":"Infants show empathy for others’ feelings.","zh":"嬰兒對他人的感受表現出同理心。"},{"en":"To show empathy for someone means to recognise and respond to that person’s feelings with concern.","zh":"show empathy for someone 指認出並關心地回應某人的感受。"},{"en":"A child may show empathy for a crying friend by offering a toy.","zh":"孩子可能把玩具遞給哭泣的朋友，表現出同理心。"},{"en":"Empathy helps people comfort others and build relationships.","zh":"同理心幫助人們安慰他人並建立關係。"},{"en":"The phrase describes emotional understanding and care.","zh":"這個短語描述情感理解和關懷。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":11},{"front":"spontaneous speech","meaning":"自發言語","examples":[{"en":"Schatz studied the spontaneous speech of three-year-olds.","zh":"Schatz 研究三歲兒童的自發言語。"},{"en":"Spontaneous speech is natural speech produced without being directly prompted or scripted.","zh":"spontaneous speech 指沒有直接提示或腳本下自然產生的說話。"},{"en":"A teacher may learn a lot from students’ spontaneous speech during group work.","zh":"老師可以從學生小組活動中的自發言語學到很多。"},{"en":"Natural speech can reveal what children understand outside formal testing.","zh":"自然說話可以揭示兒童在正式測試以外理解了甚麼。"},{"en":"The phrase contrasts everyday speaking with rehearsed answers.","zh":"這個短語把日常說話與排練答案作對比。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":11},{"front":"three-year-olds","meaning":"三歲兒童","examples":[{"en":"Schatz studied the spontaneous speech of three-year-olds.","zh":"Schatz 研究三歲兒童的自發言語。"},{"en":"Three-year-olds are children who are three years old.","zh":"three-year-olds 指三歲大的兒童。"},{"en":"Many three-year-olds can speak in short sentences and join simple pretend games.","zh":"許多三歲兒童能說短句並參與簡單假裝遊戲。"},{"en":"Studying three-year-olds can show what children understand before the age of four.","zh":"研究三歲兒童可以顯示孩子在四歲前理解了甚麼。"},{"en":"The phrase identifies a preschool age group.","zh":"這個短語指出學前兒童年齡組。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":11},{"front":"mental terms","meaning":"心理詞語","examples":[{"en":"Three-year-olds used mental terms in situations involving a contrast.","zh":"三歲兒童在涉及對比的情況中使用心理詞語。"},{"en":"Mental terms are words that refer to thoughts, feelings, beliefs, wants, or knowledge.","zh":"mental terms 指與想法、感受、信念、願望或知識有關的詞語。"},{"en":"Words like think, know, want, remember, and feel can be mental terms.","zh":"think、know、want、remember 和 feel 等字都可以是心理詞語。"},{"en":"Using mental terms shows children can talk about inner states, not just objects.","zh":"使用心理詞語顯示兒童能談論內在狀態，而不只是物件。"},{"en":"The phrase refers to language about the mind.","zh":"這個短語指關於心智的語言。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":11},{"front":"situations involving a contrast","meaning":"涉及對比的情況","examples":[{"en":"Children used mental terms in situations involving a contrast.","zh":"兒童在涉及對比的情況中使用心理詞語。"},{"en":"Situations involving a contrast are cases where two ideas, states, or possibilities are different from each other.","zh":"situations involving a contrast 指兩個想法、狀態或可能性彼此不同的情況。"},{"en":"A child may say “I thought it was milk, but it is water” in a contrast situation.","zh":"孩子可能在對比情況中說：「我以為是牛奶，但其實是水。」"},{"en":"Contrasts make mental states easier to notice because belief and reality differ.","zh":"對比令心理狀態更容易被注意，因為信念與現實不同。"},{"en":"The phrase describes contexts where difference is important.","zh":"這個短語描述差異很重要的語境。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":11},{"front":"uncertainty about","meaning":"對……不確定","examples":[{"en":"Children used mental terms when there was uncertainty about an object’s location.","zh":"當兒童對物件位置不確定時，他們會使用心理詞語。"},{"en":"Uncertainty about something means not knowing it clearly or definitely.","zh":"uncertainty about something 指不清楚或不確定某事。"},{"en":"A student may feel uncertainty about the exam room if the timetable is unclear.","zh":"如果時間表不清楚，學生可能對考試室不確定。"},{"en":"When people are unsure, they often use words like think, know, or guess.","zh":"當人們不肯定時，常會使用 think、know 或 guess 等詞。"},{"en":"The phrase describes a lack of clear knowledge.","zh":"這個短語描述缺乏清楚知識。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":11},{"front":"an object’s location","meaning":"物件的位置","examples":[{"en":"Children used mental terms when discussing an object’s location.","zh":"兒童討論物件的位置時會使用心理詞語。"},{"en":"An object’s location is the place where the object is.","zh":"object’s location 指某物所在的地方。"},{"en":"A child may ask about a toy’s location when it is not in the usual box.","zh":"當玩具不在平常的盒中，孩子可能詢問玩具的位置。"},{"en":"Uncertainty about location can create opportunities to talk about thinking and knowing.","zh":"對位置不確定可以創造機會談論想法和知道。"},{"en":"The phrase refers to where something is placed or found.","zh":"這個短語指某物被放置或被找到的地方。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":11},{"front":"between pretence and reality","meaning":"在假裝與現實之間","examples":[{"en":"Children used mental terms when contrasting pretence and reality.","zh":"兒童在對比假裝與現實時會使用心理詞語。"},{"en":"Between pretence and reality means comparing what is imagined with what is actually true.","zh":"between pretence and reality 指比較想像內容與真實情況。"},{"en":"A child may say, “This stick is a sword in the game, but really it is a stick.”","zh":"孩子可能說：「這支棍在遊戲中是劍，但其實是棍。」"},{"en":"Such contrasts show that children can keep play ideas separate from real facts.","zh":"這類對比顯示兒童能把遊戲想法與真實事實分開。"},{"en":"The phrase marks the boundary between make-believe and the real world.","zh":"這個短語標示扮演與真實世界之間的界線。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":11},{"front":"social abilities","meaning":"社交能力","examples":[{"en":"Children’s social abilities indicate that they distinguish mental states from external reality.","zh":"兒童的社交能力顯示他們能區分心理狀態與外在現實。"},{"en":"Social abilities are skills used to communicate, cooperate, understand others, and manage relationships.","zh":"social abilities 指用來溝通、合作、理解他人和處理關係的技能。"},{"en":"Sharing toys, comforting a friend, and taking turns are social abilities.","zh":"分享玩具、安慰朋友和輪流都是社交能力。"},{"en":"Strong social abilities may reveal understanding that formal tests miss.","zh":"強社交能力可能揭示正式測驗看不到的理解。"},{"en":"The phrase refers to practical interpersonal skills.","zh":"這個短語指實際人際技能。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":11},{"front":"indicate that","meaning":"顯示","examples":[{"en":"Children’s social abilities indicate that they understand mental states earlier than expected.","zh":"兒童的社交能力顯示他們比預期更早理解心理狀態。"},{"en":"Indicate that means show or suggest that something is true.","zh":"indicate that 指顯示或暗示某事為真。"},{"en":"A student’s careful notes may indicate that she has revised seriously.","zh":"學生仔細的筆記可能顯示她認真溫習過。"},{"en":"If behaviour points to understanding, researchers may question earlier conclusions.","zh":"如果行為指向理解，研究人員可能質疑早前結論。"},{"en":"The phrase introduces evidence-based suggestion.","zh":"這個短語引入基於證據的提示。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":12},{"front":"external reality","meaning":"外在現實","examples":[{"en":"Children can distinguish mental states from external reality.","zh":"兒童能把心理狀態與外在現實區分開來。"},{"en":"External reality is the outside world as it actually is, separate from thoughts or imagination.","zh":"external reality 指思想或想像以外的真實外部世界。"},{"en":"A child may imagine the floor is the sea, but external reality is that it is still a floor.","zh":"孩子可能想像地板是海，但外在現實是它仍然是地板。"},{"en":"Understanding external reality helps children avoid confusing pretend play with real danger.","zh":"理解外在現實幫助兒童避免把假裝遊戲與真正危險混淆。"},{"en":"The phrase contrasts the real outside world with inner mental states.","zh":"這個短語把真實外部世界與內在心理狀態作對比。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":12},{"front":"at ages younger than four","meaning":"在四歲以下的年齡","examples":[{"en":"Children may distinguish mental states from reality at ages younger than four.","zh":"兒童可能在四歲以下的年齡已能區分心理狀態與現實。"},{"en":"At ages younger than four means before children reach four years old.","zh":"at ages younger than four 指兒童未滿四歲時。"},{"en":"Some children begin using emotion words at ages younger than four.","zh":"有些孩子在四歲以下的年齡已開始使用情緒詞語。"},{"en":"If understanding appears before four, standard false-belief tasks may underestimate ability.","zh":"如果理解在四歲前出現，標準錯誤信念任務可能低估能力。"},{"en":"The phrase challenges a strict four-year-old boundary.","zh":"這個短語挑戰嚴格的四歲界線。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":12},{"front":"offer a different explanation","meaning":"提出不同解釋","examples":[{"en":"Harris offers a different explanation for success in false-belief tasks.","zh":"Harris 對錯誤信念任務中的成功提出不同解釋。"},{"en":"To offer a different explanation means to propose another way of understanding a result.","zh":"offer a different explanation 指提出另一種理解結果的方法。"},{"en":"A teacher may offer a different explanation for poor marks, such as unclear instructions instead of laziness.","zh":"老師可能對低分提出不同解釋，例如指示不清而不是懶惰。"},{"en":"Alternative explanations help researchers avoid accepting one theory too quickly.","zh":"其他解釋幫助研究人員避免太快接受單一理論。"},{"en":"The phrase introduces a competing interpretation.","zh":"這個短語引入競爭性的詮釋。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":12},{"front":"use simulation","meaning":"使用模擬","examples":[{"en":"Harris argues that children use simulation.","zh":"Harris 主張兒童使用模擬。"},{"en":"To use simulation means to imagine oneself in a situation in order to predict what would happen.","zh":"use simulation 指想像自己處於某情況中，以預測會發生甚麼。"},{"en":"A student may use simulation by imagining how she would feel before a speech.","zh":"學生可能透過想像自己演講前會有何感受來使用模擬。"},{"en":"Simulation can help children predict another person’s action without fully analysing that person’s beliefs.","zh":"模擬可以幫助兒童預測他人行動，而不一定完全分析對方信念。"},{"en":"The phrase describes thinking by mental role-play.","zh":"這個短語描述透過心理角色扮演來思考。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":12},{"front":"involve putting oneself in","meaning":"涉及把自己置身於……","examples":[{"en":"Simulation involves putting oneself in another person’s position.","zh":"模擬涉及把自己置身於另一個人的處境。"},{"en":"To involve putting oneself in a position means to imagine being in that situation.","zh":"involve putting oneself in a position 指想像自己身處該情況。"},{"en":"A student can understand a bullied classmate better by putting herself in that classmate’s position.","zh":"學生可以透過把自己置身於被欺凌同學的處境，更好理解他。"},{"en":"Imagining another position can help predict feelings, choices, and behaviour.","zh":"想像另一個處境可以幫助預測感受、選擇和行為。"},{"en":"The phrase describes mental perspective-taking.","zh":"這個短語描述心理換位思考。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":12},{"front":"another person’s position","meaning":"別人的處境","examples":[{"en":"Children may put themselves in another person’s position.","zh":"兒童可能把自己置身於別人的處境。"},{"en":"Another person’s position means that person’s situation, perspective, or set of circumstances.","zh":"another person’s position 指該人的情況、角度或所處環境。"},{"en":"A teacher may ask students to imagine another person’s position before judging their decision.","zh":"老師可能要求學生在評判某人決定前，想像別人的處境。"},{"en":"Seeing another person’s position can reduce quick blame and improve empathy.","zh":"看見別人的處境可以減少倉促責怪並改善同理心。"},{"en":"The phrase is about perspective, not physical location only.","zh":"這個短語關乎角度，而不只是實體位置。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":12},{"front":"predict what someone would do","meaning":"預測某人會做甚麼","examples":[{"en":"Children may predict what another person would do.","zh":"兒童可能預測另一個人會做甚麼。"},{"en":"To predict what someone would do means to guess their likely action in a situation.","zh":"predict what someone would do 指猜測某人在某情況中可能採取的行動。"},{"en":"A child may predict that a hungry friend would choose a sandwich before a game.","zh":"孩子可能預測飢餓的朋友會在遊戲前選三文治。"},{"en":"Prediction depends on understanding what the person knows, wants, or believes.","zh":"預測取決於理解該人知道、想要或相信甚麼。"},{"en":"The phrase connects mental understanding with expected behaviour.","zh":"這個短語把心理理解與預期行為連起來。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":12},{"front":"success in false-belief tasks","meaning":"在錯誤信念任務中的成功","examples":[{"en":"Success in false-belief tasks may reflect simulation.","zh":"在錯誤信念任務中的成功可能反映模擬。"},{"en":"Success in false-belief tasks means giving the correct answer in tests about another person’s mistaken belief.","zh":"success in false-belief tasks 指在關於他人錯誤信念的測試中給出正確答案。"},{"en":"A child shows success when she says Sally will look where Sally last saw the marble.","zh":"當孩子說 Sally 會在她最後看見波子的地方找，就是表現出成功。"},{"en":"Researchers debate whether this success shows true belief understanding or another strategy.","zh":"研究人員爭論這種成功是否顯示真正信念理解，還是另一策略。"},{"en":"The phrase refers to performance in a specific kind of psychological task.","zh":"這個短語指在特定心理任務中的表現。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":12},{"front":"reflect children imagining","meaning":"反映兒童在想像","examples":[{"en":"Success may reflect children imagining what they themselves would do.","zh":"成功可能反映兒童在想像自己會做甚麼。"},{"en":"Reflect children imagining means show that children are using imagination to think through a situation.","zh":"reflect children imagining 指顯示兒童正使用想像來思考某情況。"},{"en":"A child may solve a story problem by imagining herself in the character’s place.","zh":"孩子可能透過想像自己處於角色位置來解決故事問題。"},{"en":"If success reflects imagination, it may not prove full understanding of another person’s beliefs.","zh":"如果成功反映的是想像，它未必證明完全理解他人信念。"},{"en":"The phrase links a test result with a possible mental strategy.","zh":"這個短語把測試結果與可能心理策略連起來。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":12},{"front":"rather than an ability to","meaning":"而不是……的能力","examples":[{"en":"Success may reflect simulation rather than an ability to appreciate other people’s beliefs.","zh":"成功可能反映模擬，而不是理解別人信念的能力。"},{"en":"Rather than an ability to means not because of that ability, but because of something else.","zh":"rather than an ability to 指不是因為該能力，而是因為其他東西。"},{"en":"A student’s correct answer may come from guessing rather than an ability to explain the rule.","zh":"學生答對可能來自猜測，而不是解釋規則的能力。"},{"en":"This phrase separates a possible surface success from the deeper skill being tested.","zh":"這個短語把表面成功與被測試的深層技能分開。"},{"en":"It is useful when questioning what a result really proves.","zh":"它適合用於質疑結果真正證明了甚麼。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":12},{"front":"appreciate other people’s beliefs","meaning":"理解別人的信念","examples":[{"en":"Children may not fully appreciate other people’s beliefs.","zh":"兒童可能未能完全理解別人的信念。"},{"en":"To appreciate other people’s beliefs means to understand that others may think something different from oneself.","zh":"appreciate other people’s beliefs 指明白他人可能有不同於自己的想法。"},{"en":"A child appreciates a friend’s belief when she knows the friend still thinks the toy is outside.","zh":"當孩子知道朋友仍以為玩具在外面，她就是理解朋友的信念。"},{"en":"This understanding helps children explain why people make mistakes or act unexpectedly.","zh":"這種理解幫助兒童解釋為何人們會犯錯或有意外行為。"},{"en":"The phrase focuses on recognising another person’s mental perspective.","zh":"這個短語重點是辨認他人的心理角度。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":13},{"front":"think about situations that do not exist","meaning":"思考不存在的情境","examples":[{"en":"Thinking about situations that do not exist is known as counterfactual reasoning.","zh":"思考不存在的情境被稱為反事實推理。"},{"en":"To think about situations that do not exist means to imagine events that are not real or did not happen.","zh":"think about situations that do not exist 指想像不是真實或沒有發生的事件。"},{"en":"A student may think, “If I had studied earlier, I would have slept better.”","zh":"學生可能想：「如果我早點溫習，就會睡得更好。」"},{"en":"Imagining unreal situations helps people learn from mistakes and plan differently.","zh":"想像不存在的情境幫助人們從錯誤中學習並作不同計劃。"},{"en":"The phrase describes mental comparison between reality and alternatives.","zh":"這個短語描述現實與其他可能之間的心理比較。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":13},{"front":"be known as","meaning":"被稱為","examples":[{"en":"Thinking about situations that do not exist is known as counterfactual reasoning.","zh":"思考不存在的情境被稱為反事實推理。"},{"en":"Be known as means be called or recognised by a particular name.","zh":"be known as 指被稱作或以某特定名稱被認識。"},{"en":"A school may be known as a science school because its students win many science prizes.","zh":"一所學校可能因學生贏得許多科學獎而被稱為科學學校。"},{"en":"Naming a concept helps students remember and discuss it more clearly.","zh":"命名概念幫助學生更清楚記住和討論它。"},{"en":"The phrase introduces the term used for something.","zh":"這個短語引入某事所用的名稱。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":13},{"front":"counterfactual reasoning","meaning":"反事實推理","examples":[{"en":"Counterfactual reasoning involves thinking about situations that do not exist.","zh":"反事實推理涉及思考不存在的情境。"},{"en":"Counterfactual reasoning is thinking about what would be true if things had happened differently.","zh":"counterfactual reasoning 指思考如果事情以不同方式發生，會有甚麼不同。"},{"en":"A student uses counterfactual reasoning when she says, “If I had left earlier, I would not be late.”","zh":"學生說「如果我早點出門，就不會遲到」時，就是使用反事實推理。"},{"en":"This reasoning helps people understand causes, regrets, and possible alternatives.","zh":"這種推理幫助人們理解原因、遺憾和其他可能。"},{"en":"The phrase describes thinking about “what if” situations.","zh":"這個短語描述關於「如果……會怎樣」的思考。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":13},{"front":"look at the following statements","meaning":"查看以下陳述","examples":[{"en":"Students look at the following statements and match them with the correct researcher.","zh":"學生查看以下陳述，並把它們與正確研究人員配對。"},{"en":"Look at the following statements means read the listed sentences carefully.","zh":"look at the following statements 指仔細閱讀列出的句子。"},{"en":"In an exam, students should look at the following statements before searching the passage.","zh":"在考試中，學生應先查看以下陳述，再搜尋文章。"},{"en":"Careful reading prevents students from matching only by keywords.","zh":"仔細閱讀防止學生只靠關鍵詞配對。"},{"en":"The phrase is an instruction to examine answer items.","zh":"這個短語是要求檢視答案項目的指示。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":13},{"front":"the list of researchers below","meaning":"以下研究人員名單","examples":[{"en":"The list of researchers below gives seven possible answers.","zh":"以下研究人員名單提供七個可能答案。"},{"en":"The list of researchers below means the names of researchers printed after the instruction.","zh":"list of researchers below 指在指示下方列出的研究人員姓名。"},{"en":"Students should check the list below before deciding which name matches each idea.","zh":"學生在決定哪個名字配對每個想法前，應查看下方名單。"},{"en":"A list can limit possible answers and make matching more focused.","zh":"名單可以限制可能答案，令配對更集中。"},{"en":"The phrase refers to answer options in a reading task.","zh":"這個短語指閱讀任務中的答案選項。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":13},{"front":"match each statement with","meaning":"將每項陳述與……配對","examples":[{"en":"Students match each statement with the correct researcher.","zh":"學生將每項陳述與正確研究人員配對。"},{"en":"To match each statement with something means to connect every sentence to the right option.","zh":"match each statement with something 指把每個句子連到正確選項。"},{"en":"A teacher may ask students to match each example with the correct grammar rule.","zh":"老師可能要求學生將每個例子與正確文法規則配對。"},{"en":"Matching requires understanding meaning, not just finding repeated words.","zh":"配對需要理解意思，而不只是尋找重複字。"},{"en":"The phrase describes a pairing task.","zh":"這個短語描述配對任務。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":13},{"front":"the correct researcher","meaning":"正確的研究人員","examples":[{"en":"Each statement should be matched with the correct researcher.","zh":"每項陳述都應與正確的研究人員配對。"},{"en":"The correct researcher is the researcher whose work or idea matches the statement.","zh":"correct researcher 指其研究或想法與陳述相符的研究人員。"},{"en":"If a passage says Meins studied mothers’ speech, Meins is the correct researcher for that detail.","zh":"如果文章說 Meins 研究母親說話，Meins 就是該細節的正確研究人員。"},{"en":"Choosing the correct researcher depends on careful source attribution.","zh":"選出正確研究人員取決於仔細辨認來源。"},{"en":"The phrase focuses on identifying who made which claim.","zh":"這個短語重點是辨認誰提出了哪個主張。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":13},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Students write the correct letter on the answer sheet.","zh":"學生在答題紙上寫上正確字母。"},{"en":"Write the correct letter means put the letter of the right option as the answer.","zh":"write the correct letter 指把正確選項的字母寫作答案。"},{"en":"If option C is correct, students should write C rather than copying the whole sentence.","zh":"如果選項 C 正確，學生應寫 C，而不是抄整句。"},{"en":"Writing the letter clearly helps avoid marking mistakes.","zh":"清楚寫出字母有助避免評分錯誤。"},{"en":"The phrase is a standard exam instruction.","zh":"這個短語是標準考試指示。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":13},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生在答題紙上寫答案。"},{"en":"On your answer sheet means in the official place where answers must be recorded.","zh":"on your answer sheet 指在必須記錄答案的正式位置。"},{"en":"A student may lose marks if the correct answer is written in the booklet but not on the answer sheet.","zh":"如果正確答案寫在試題冊而不是答題紙上，學生可能失分。"},{"en":"Exam instructions often stress the answer sheet because it is what markers check.","zh":"考試指示常強調答題紙，因為評卷者會檢查它。"},{"en":"The phrase tells candidates where to put final answers.","zh":"這個短語告訴考生最終答案要放在哪裡。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":13},{"front":"propose an alternative explanation","meaning":"提出另一種解釋","examples":[{"en":"One researcher proposed an alternative explanation for the results.","zh":"一位研究人員對結果提出另一種解釋。"},{"en":"To propose an alternative explanation means to suggest another possible reason for the same finding.","zh":"propose an alternative explanation 指為同一發現提出另一個可能原因。"},{"en":"A doctor may propose an alternative explanation for tiredness, such as stress instead of illness.","zh":"醫生可能對疲倦提出另一種解釋，例如壓力而不是疾病。"},{"en":"Alternative explanations help researchers test whether a conclusion is too simple.","zh":"其他解釋幫助研究人員測試結論是否過於簡單。"},{"en":"The phrase introduces a different way to interpret evidence.","zh":"這個短語引入詮釋證據的不同方式。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":13},{"front":"may not actually understand","meaning":"可能其實並不理解","examples":[{"en":"Children may not actually understand another person’s beliefs.","zh":"兒童可能其實並不理解另一個人的信念。"},{"en":"May not actually understand means might seem to understand but perhaps do not truly understand.","zh":"may not actually understand 指看似理解，但也許並沒有真正理解。"},{"en":"A student may not actually understand a formula if she can only copy the steps.","zh":"如果學生只會抄步驟，她可能其實並不理解公式。"},{"en":"Correct performance can sometimes hide shallow or different reasoning.","zh":"正確表現有時會掩蓋淺層或不同推理。"},{"en":"The phrase questions whether apparent success reflects real understanding.","zh":"這個短語質疑表面成功是否反映真正理解。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":14},{"front":"conduct a well-known experiment","meaning":"進行一項著名實驗","examples":[{"en":"The researchers conducted a well-known experiment on false belief.","zh":"研究人員進行了一項關於錯誤信念的著名實驗。"},{"en":"To conduct a well-known experiment means to carry out a famous research test.","zh":"conduct a well-known experiment 指進行一項有名的研究測試。"},{"en":"A psychology class may discuss a well-known experiment to understand how memory works.","zh":"心理學課可能討論一項著名實驗，以理解記憶如何運作。"},{"en":"Famous experiments often shape later research and debate.","zh":"著名實驗常塑造後來研究和爭論。"},{"en":"The phrase describes doing an important recognised study.","zh":"這個短語描述進行重要而被認可的研究。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":14},{"front":"conclude that","meaning":"得出結論認為","examples":[{"en":"The researchers concluded that young children could not understand a person’s false belief.","zh":"研究人員得出結論認為年幼兒童不能理解某人的錯誤信念。"},{"en":"To conclude that means to decide something after considering evidence.","zh":"conclude that 指考慮證據後判定某事。"},{"en":"A teacher may conclude that students need more practice after marking their essays.","zh":"老師批改作文後，可能得出結論認為學生需要更多練習。"},{"en":"Conclusions should follow from results, not from personal guesses.","zh":"結論應來自結果，而不是個人猜測。"},{"en":"The phrase introduces a research finding or judgement.","zh":"這個短語引入研究發現或判斷。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":14},{"front":"a person’s false belief","meaning":"某人的錯誤信念","examples":[{"en":"Young children may not understand a person’s false belief.","zh":"年幼兒童可能不理解某人的錯誤信念。"},{"en":"A person’s false belief is something that person believes even though it is not true.","zh":"person’s false belief 指某人相信但其實不真實的事情。"},{"en":"A child may think her father believes the keys are on the table, though they have been moved.","zh":"孩子可能知道父親相信鑰匙在桌上，雖然鑰匙已被移走。"},{"en":"Understanding false belief helps children predict why someone will search in the wrong place.","zh":"理解錯誤信念幫助兒童預測為何某人會在錯誤地方尋找。"},{"en":"The phrase focuses on another person’s mistaken mental state.","zh":"這個短語重點是另一個人的錯誤心理狀態。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":14},{"front":"exclude the effects of","meaning":"排除……的影響","examples":[{"en":"The simpler experiment was designed to exclude the effects of complex reasoning.","zh":"較簡單的實驗旨在排除複雜推理的影響。"},{"en":"To exclude the effects of something means to remove that factor so it does not influence the result.","zh":"exclude the effects of something 指移除某因素，使其不影響結果。"},{"en":"A teacher may use simple vocabulary to exclude the effects of difficult language in a science test.","zh":"老師可能在科學測驗中使用簡單詞彙，以排除困難語言的影響。"},{"en":"Removing extra difficulty helps show what ability is really being measured.","zh":"移除額外難度有助顯示真正被量度的是甚麼能力。"},{"en":"The phrase describes controlling unwanted influences.","zh":"這個短語描述控制不想要的影響。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":14},{"front":"complex reasoning","meaning":"複雜推理","examples":[{"en":"The revised task reduced the need for complex reasoning.","zh":"修訂後的任務減少了對複雜推理的需要。"},{"en":"Complex reasoning is difficult thinking that involves several steps, details, or relationships.","zh":"complex reasoning 指涉及多個步驟、細節或關係的困難思考。"},{"en":"Solving a long word problem in maths may require complex reasoning.","zh":"解答長篇數學文字題可能需要複雜推理。"},{"en":"If a task requires too much reasoning, young children may fail even when they understand the basic idea.","zh":"如果任務需要太多推理，年幼兒童即使理解基本想法也可能失敗。"},{"en":"The phrase refers to demanding mental work.","zh":"這個短語指高要求的心理工作。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":14},{"front":"excessive information","meaning":"過多資料","examples":[{"en":"The simpler experiment was designed to avoid excessive information.","zh":"較簡單的實驗旨在避免過多資料。"},{"en":"Excessive information means too much information, more than is useful or manageable.","zh":"excessive information 指太多資料，超過有用或可處理的程度。"},{"en":"Students may become confused if exam instructions contain excessive information.","zh":"如果考試指示包含過多資料，學生可能變得困惑。"},{"en":"Too much information can overload memory and hide the skill being tested.","zh":"太多資料可以令記憶負荷過重，並掩蓋正在測試的技能。"},{"en":"The phrase describes information overload.","zh":"這個短語描述資訊過載。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":14},{"front":"link a social factor with","meaning":"將社會因素與……聯繫起來","examples":[{"en":"The study linked a social factor with theory-of-mind ability.","zh":"該研究將一個社會因素與心智理論能力聯繫起來。"},{"en":"To link a social factor with something means to show a connection between a social condition and an outcome.","zh":"link a social factor with something 指顯示某社會條件與某結果之間的關聯。"},{"en":"A school study may link family reading time with vocabulary growth.","zh":"學校研究可能把家庭閱讀時間與詞彙增長聯繫起來。"},{"en":"Finding a link does not always prove direct cause, but it suggests a relationship worth studying.","zh":"找到關聯不一定證明直接因果，但暗示某關係值得研究。"},{"en":"The phrase connects social experience with development.","zh":"這個短語把社會經驗與發展連起來。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":14},{"front":"mother–child communication","meaning":"母子溝通；母親與孩子的溝通","examples":[{"en":"Mother–child communication may be related to theory-of-mind ability.","zh":"母子溝通可能與心智理論能力有關。"},{"en":"Mother–child communication means the way a mother and child talk, respond, and share attention.","zh":"mother–child communication 指母親和孩子說話、回應和分享注意力的方式。"},{"en":"A mother may communicate with a child by naming feelings, asking questions, and following the child’s gaze.","zh":"母親可能透過命名感受、提問和跟隨孩子目光與孩子溝通。"},{"en":"Rich communication can help children learn how thoughts and feelings guide behaviour.","zh":"豐富溝通可以幫助兒童學習想法和感受如何引導行為。"},{"en":"The phrase focuses on interaction between mother and child.","zh":"這個短語重點是母親與孩子之間的互動。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":14},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"To complete the summary below means to fill gaps in a short version of the passage.","zh":"complete the summary below 指填補文章簡短版本中的空格。"},{"en":"Students should read the summary first, then locate matching information in the text.","zh":"學生應先讀摘要，然後在文本中定位相符資料。"},{"en":"Summary completion tests meaning, grammar, and exact word choice.","zh":"摘要填空測試意思、文法和準確用字。"},{"en":"The phrase is a common reading-exam instruction.","zh":"這個短語是常見閱讀考試指示。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":14},{"front":"choose one word only","meaning":"只選一個字","examples":[{"en":"Students must choose one word only from the passage for each answer.","zh":"學生每個答案必須從文章中只選一個字。"},{"en":"Choose one word only means write exactly one word, not two or more.","zh":"choose one word only 指準確寫一個詞，而不是兩個或更多。"},{"en":"If the answer is “basket,” students should not write “the basket” when only one word is allowed.","zh":"如果答案是 “basket”，當只容許一個字時，學生不應寫 “the basket”。"},{"en":"Ignoring the word limit can lose marks even when the idea is correct.","zh":"即使意思正確，忽視字數限制也可能失分。"},{"en":"The phrase sets a strict answer length.","zh":"這個短語設定嚴格答案長度。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":14},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answer must come from the passage.","zh":"答案必須來自文章。"},{"en":"From the passage means using words or information found in the reading text.","zh":"from the passage 指使用閱讀文本中的字詞或資料。"},{"en":"Students should not use outside knowledge if the answer must come from the passage.","zh":"如果答案必須來自文章，學生不應使用外部知識。"},{"en":"This instruction keeps answers tied to evidence in the text.","zh":"這個指示讓答案緊扣文本證據。"},{"en":"The phrase tells learners where the answer source must be.","zh":"這個短語告訴學習者答案來源必須在哪裏。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":15},{"front":"for each answer","meaning":"每個答案","examples":[{"en":"Students choose one word only for each answer.","zh":"學生每個答案只選一個字。"},{"en":"For each answer means for every separate answer space or question.","zh":"for each answer 指對每個獨立答案位置或問題而言。"},{"en":"In a vocabulary quiz, students may write one example sentence for each answer.","zh":"在詞彙測驗中，學生可能為每個答案寫一句例句。"},{"en":"This phrase reminds students to apply the same rule every time.","zh":"這個短語提醒學生每一次都套用同一規則。"},{"en":"It prevents students from using the rule for only one blank.","zh":"它防止學生只在其中一格使用該規則。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":15},{"front":"during the 1980s","meaning":"在1980年代期間","examples":[{"en":"During the 1980s, researchers developed experiments to test theory of mind.","zh":"在1980年代期間，研究人員設計實驗來測試心智理論。"},{"en":"During the 1980s means in the period from 1980 to 1989.","zh":"during the 1980s 指在1980年至1989年這段期間。"},{"en":"During the 1980s, personal computers began appearing in more offices and homes.","zh":"在1980年代期間，個人電腦開始出現在更多辦公室和家庭。"},{"en":"Giving a decade helps place research in historical context.","zh":"提供年代有助把研究放入歷史背景。"},{"en":"The phrase marks when something happened.","zh":"這個短語標示某事發生的時間。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":15},{"front":"develop experiments to test","meaning":"設計實驗來測試","examples":[{"en":"Researchers developed experiments to test theory of mind.","zh":"研究人員設計實驗來測試心智理論。"},{"en":"To develop experiments to test something means to design studies that measure or examine it.","zh":"develop experiments to test something 指設計研究來量度或檢查某事。"},{"en":"Scientists may develop experiments to test whether sleep improves memory.","zh":"科學家可能設計實驗來測試睡眠是否改善記憶。"},{"en":"Good experiments make abstract abilities easier to observe and compare.","zh":"良好實驗令抽象能力較容易被觀察和比較。"},{"en":"The phrase describes creating a research method for a question.","zh":"這個短語描述為某問題創造研究方法。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":15},{"front":"represent reality","meaning":"表徵現實","examples":[{"en":"Theory of mind involves the ability to represent reality and other people’s beliefs.","zh":"心智理論涉及表徵現實和他人信念的能力。"},{"en":"To represent reality means to form a mental picture or model of what is true.","zh":"represent reality 指形成關於真實情況的心理圖像或模型。"},{"en":"A map represents reality by showing where roads, rivers, and buildings are.","zh":"地圖透過顯示道路、河流和建築物的位置來表徵現實。"},{"en":"Children must represent reality separately from what another person believes about reality.","zh":"兒童必須把現實表徵與他人對現實的信念分開。"},{"en":"The phrase connects mental understanding with the real world.","zh":"這個短語把心理理解與真實世界連起來。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":15},{"front":"in the first experiment","meaning":"在第一個實驗中","examples":[{"en":"In the first experiment, children heard a story about a boy.","zh":"在第一個實驗中，兒童聽了一個關於男孩的故事。"},{"en":"In the first experiment means in the earliest study or task being described.","zh":"in the first experiment 指在正在描述的最早研究或任務中。"},{"en":"In the first experiment, students may watch a short video before answering questions.","zh":"在第一個實驗中，學生可能先看短片再回答問題。"},{"en":"Describing the first experiment helps readers follow the order of research methods.","zh":"描述第一個實驗幫助讀者跟隨研究方法的次序。"},{"en":"The phrase introduces the initial test in a sequence.","zh":"這個短語引入一系列測試中的最初測試。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":15},{"front":"in a second, simplified experiment","meaning":"在第二個簡化實驗中","examples":[{"en":"In a second, simplified experiment, researchers used two dolls.","zh":"在第二個簡化實驗中，研究人員使用兩個洋娃娃。"},{"en":"In a second, simplified experiment means in a later experiment made easier than the first.","zh":"in a second, simplified experiment 指在較後且比第一個更簡單的實驗中。"},{"en":"In a second, simplified test, students may answer fewer questions with clearer pictures.","zh":"在第二個簡化測驗中，學生可能用更清楚圖片回答較少問題。"},{"en":"Simplifying the experiment can reduce confusion and focus on the main ability.","zh":"簡化實驗可以減少困惑，並集中於主要能力。"},{"en":"The phrase introduces a revised follow-up study.","zh":"這個短語引入修訂後的後續研究。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":15},{"front":"perform better","meaning":"表現較好","examples":[{"en":"Children who interacted more with adults performed better.","zh":"與成年人互動更多的兒童表現較好。"},{"en":"To perform better means to do a task more successfully than others or than before.","zh":"perform better 指在任務中比別人或比以前更成功。"},{"en":"Students often perform better after practising with clear examples.","zh":"學生在用清楚例子練習後，通常表現較好。"},{"en":"Better performance may show that experience, support, or age has helped learning.","zh":"較好表現可能顯示經驗、支援或年齡幫助了學習。"},{"en":"The phrase describes improved or stronger results.","zh":"這個短語描述改善或較強結果。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":15},{"front":"include pretend play","meaning":"包括假裝遊戲","examples":[{"en":"Peer interaction can include pretend play.","zh":"同輩互動可以包括假裝遊戲。"},{"en":"To include pretend play means to contain make-believe games as part of the interaction.","zh":"include pretend play 指把扮演或想像遊戲包含為互動的一部分。"},{"en":"Children’s playtime may include pretend play when they act as doctors, teachers, or shopkeepers.","zh":"當孩子扮演醫生、老師或店員時，遊戲時間可能包括假裝遊戲。"},{"en":"Pretend play gives children chances to practise roles, beliefs, and feelings.","zh":"假裝遊戲給兒童機會練習角色、信念和感受。"},{"en":"The phrase shows one important feature that peer interaction may contain.","zh":"這個短語顯示同輩互動可能包含的一個重要特徵。"}],"source":"52 - Implication of False Belief Experiments.pdf","sourcePage":15}],"ielts/reading/passage-2/Practice 53":[{"front":"considerate computing","meaning":"體貼式運算；體貼式電腦科技","examples":[{"en":"The passage is about considerate computing and how devices can reduce interruptions.","zh":"篇章講述體貼式運算，以及裝置如何減少打擾。"},{"en":"Considerate computing means designing computers and devices that respect people’s attention, time, and mental limits.","zh":"體貼式運算是指設計尊重人類注意力、時間和心理限制的電腦及裝置。"},{"en":"A considerate computing system might wait until a meeting ends before showing a non-urgent message.","zh":"體貼式運算系統可能會等到會議結束後，才顯示不緊急訊息。"},{"en":"Considerate computing can reduce stress because users are not interrupted at the worst possible moment.","zh":"體貼式運算可以減少壓力，因為使用者不會在最糟糕的時刻被打斷。"},{"en":"This idea treats technology more like a polite assistant than a noisy machine.","zh":"這個概念把科技視為有禮貌的助手，而不是吵鬧的機器。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":1},{"front":"fully charged","meaning":"充滿電","examples":[{"en":"The laptop announced that the battery was now fully charged.","zh":"手提電腦宣布電池現在已充滿電。"},{"en":"Fully charged means a battery has reached its full power level.","zh":"充滿電是指電池已達到完整電量。"},{"en":"Your phone is fully charged when the battery icon shows 100%.","zh":"當手機電池圖示顯示 100% 時，手機就是充滿電。"},{"en":"A fully charged laptop can be used longer without being plugged in.","zh":"充滿電的手提電腦可以在不插電的情況下使用更久。"},{"en":"This phrase is used for batteries, devices, and anything powered by stored electricity.","zh":"這個短語用於電池、裝置和任何以儲存電力供電的東西。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":1},{"front":"synthetic voice","meaning":"合成語音","examples":[{"en":"The laptop spoke to its owner in a synthetic voice.","zh":"手提電腦用合成語音對主人說話。"},{"en":"A synthetic voice is a computer-made voice, not a natural human voice.","zh":"合成語音是由電腦製造的聲音，不是真正人類聲音。"},{"en":"A GPS uses a synthetic voice to tell drivers where to turn.","zh":"GPS 使用合成語音告訴司機在哪裡轉彎。"},{"en":"Synthetic voices help machines give spoken information without needing a real speaker.","zh":"合成語音幫助機器提供口頭資訊，而不需要真人說話。"},{"en":"This phrase is common when discussing speech technology and artificial voices.","zh":"這個短語常用於討論語音科技和人工聲音。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":1},{"front":"with great enthusiasm","meaning":"充滿熱情地","examples":[{"en":"The laptop made the announcement with great enthusiasm.","zh":"手提電腦充滿熱情地作出宣布。"},{"en":"With great enthusiasm means in a very excited, energetic, or eager way.","zh":"充滿熱情地，是指以非常興奮、有活力或熱切的方式。"},{"en":"A student may answer with great enthusiasm when the topic is their favourite hobby.","zh":"當題目是自己最喜歡的興趣時，學生可能充滿熱情地回答。"},{"en":"Enthusiasm can make a message sound cheerful, even if the content is simple.","zh":"熱情可以令訊息聽起來愉快，即使內容很簡單。"},{"en":"This phrase describes the feeling or energy behind an action.","zh":"這個短語描述行動背後的感覺或能量。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":1},{"front":"a hint of pride","meaning":"一絲自豪感","examples":[{"en":"The laptop sounded as if it had a hint of pride.","zh":"手提電腦聽起來好像帶有一絲自豪感。"},{"en":"A hint of pride means a small sign of satisfaction or self-importance.","zh":"一絲自豪感，是指少量滿足或自我重視的表現。"},{"en":"A child may show a hint of pride after finishing a difficult puzzle alone.","zh":"孩子獨自完成一個困難拼圖後，可能流露一絲自豪感。"},{"en":"A hint of pride can make someone’s voice sound pleased without being openly boastful.","zh":"一絲自豪感可以令人的聲音聽起來滿意，但不明顯炫耀。"},{"en":"This phrase describes a subtle feeling, not a strong display.","zh":"這個短語描述細微感覺，而不是強烈表現。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":1},{"front":"for the record","meaning":"順帶一提；鄭重說明","examples":[{"en":"For the record, humans are familiar with distractions and multitasking.","zh":"順帶一提，人類對干擾和多工處理很熟悉。"},{"en":"For the record means the speaker wants to state something clearly or officially.","zh":"順帶一提或鄭重說明，是指說話者想清楚或正式地說明某事。"},{"en":"For the record, I did finish the report before the deadline.","zh":"鄭重說明，我確實在截止日期前完成了報告。"},{"en":"People use this phrase to correct possible misunderstanding or mark a point clearly.","zh":"人們用這個短語來糾正可能的誤解，或清楚標記一個重點。"},{"en":"It often sounds like the speaker is adding a careful note.","zh":"它常聽起來像說話者在補充一個謹慎說明。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":1},{"front":"not at all unfamiliar with","meaning":"對……絕不陌生","examples":[{"en":"Humans are not at all unfamiliar with distractions and multitasking.","zh":"人類對干擾和多工處理絕不陌生。"},{"en":"Not at all unfamiliar with something means actually quite familiar with it.","zh":"對某事絕不陌生，是指其實相當熟悉它。"},{"en":"Teachers are not at all unfamiliar with students asking last-minute questions before exams.","zh":"老師對學生考試前最後一刻提問絕不陌生。"},{"en":"This phrase uses a negative form to emphasise familiarity.","zh":"這個短語用否定形式強調熟悉。"},{"en":"It can sound slightly formal or ironic.","zh":"它聽起來可以略正式或帶諷刺。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":1},{"front":"distractions and multitasking","meaning":"干擾和多工處理","examples":[{"en":"Modern workers often deal with distractions and multitasking.","zh":"現代工作者常要處理干擾和多工處理。"},{"en":"Distractions and multitasking are interruptions and the need to handle several tasks at once.","zh":"干擾和多工處理，是指被打斷，以及需要同時處理幾項任務。"},{"en":"A student doing homework while checking messages is dealing with distractions and multitasking.","zh":"學生一邊做功課一邊查看訊息，就是在處理干擾和多工處理。"},{"en":"Too many distractions and too much multitasking can reduce accuracy and focus.","zh":"太多干擾和過多多工處理會降低準確度和專注力。"},{"en":"This phrase describes a common problem in work, study, and digital life.","zh":"這個短語描述工作、學習和數碼生活中的常見問題。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":1},{"front":"be used to","meaning":"習慣於……","examples":[{"en":"We are used to a complex life that is constantly interrupted.","zh":"我們習慣於不斷被打斷的複雜生活。"},{"en":"To be used to something means to be familiar with it because it happens often.","zh":"習慣於某事，是指因它經常發生而熟悉它。"},{"en":"Nurses are used to working under pressure in busy hospitals.","zh":"護士習慣於在繁忙醫院中承受壓力工作。"},{"en":"When people are used to interruptions, they may stop noticing how tiring they are.","zh":"當人們習慣於打擾，他們可能不再注意這有多疲累。"},{"en":"This phrase describes familiarity, not necessarily enjoyment.","zh":"這個短語描述熟悉，而不一定代表喜歡。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":1},{"front":"a complex life","meaning":"複雜的生活","examples":[{"en":"Many people are used to a complex life full of interruptions.","zh":"許多人習慣於充滿打擾的複雜生活。"},{"en":"A complex life is a life with many responsibilities, decisions, and competing demands.","zh":"複雜的生活，是指有很多責任、決定和互相競爭需求的生活。"},{"en":"A working parent may have a complex life involving work, childcare, bills, and family duties.","zh":"在職父母可能有複雜生活，包括工作、照顧孩子、帳單和家庭責任。"},{"en":"A complex life can make interruptions feel even more stressful.","zh":"複雜生活會令打擾感覺更有壓力。"},{"en":"This phrase describes daily life that is not simple or calm.","zh":"這個短語描述不簡單、不平靜的日常生活。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":1},{"front":"get constantly interrupted by","meaning":"不斷被……打斷","examples":[{"en":"Our lives get constantly interrupted by computers’ requests.","zh":"我們的生活不斷被電腦的要求打斷。"},{"en":"To get constantly interrupted by something means to be repeatedly stopped or distracted by it.","zh":"不斷被某事打斷，是指反覆被它阻止或分散注意。"},{"en":"A student may get constantly interrupted by phone notifications while revising.","zh":"學生溫習時可能不斷被手機通知打斷。"},{"en":"Constant interruptions can make it harder to finish even simple tasks.","zh":"不斷打斷會令即使簡單任務也更難完成。"},{"en":"This phrase stresses repeated disturbance, not a single interruption.","zh":"這個短語強調反覆干擾，而不是一次打擾。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":1},{"front":"attention-seeking requests","meaning":"為吸引注意而發出的要求","examples":[{"en":"Computers often make attention-seeking requests.","zh":"電腦常發出為吸引注意而設的要求。"},{"en":"Attention-seeking requests are messages or alerts designed to make users notice and respond.","zh":"為吸引注意而發出的要求，是設計來令使用者注意並回應的訊息或提示。"},{"en":"A pop-up asking you to update software during class is an attention-seeking request.","zh":"上課時彈出要求更新軟件的視窗，就是為吸引注意而發出的要求。"},{"en":"Too many attention-seeking requests can break concentration and increase frustration.","zh":"太多這類要求會打斷專注並增加挫敗感。"},{"en":"This phrase treats devices as if they are demanding human attention.","zh":"這個短語把裝置形容得像在要求人類注意。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":2},{"front":"be familiar with","meaning":"熟悉……；對……很熟悉","examples":[{"en":"People are familiar with interruptions from electronic devices.","zh":"人們熟悉來自電子裝置的打擾。"},{"en":"To be familiar with something means to know it well because you have experienced it before.","zh":"熟悉某事，是指因以前經歷過而很了解它。"},{"en":"Office workers are familiar with email alerts arriving during meetings.","zh":"辦公室員工對會議期間收到電郵提示很熟悉。"},{"en":"Familiar problems may still be harmful if people accept them without thinking.","zh":"熟悉的問題如果人們不加思考地接受，仍可能有害。"},{"en":"This phrase describes experience and recognition.","zh":"這個短語描述經驗和辨認能力。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":2},{"front":"procreation","meaning":"生育繁衍","examples":[{"en":"Ted Selker compares people’s familiarity with interruptions to their familiarity with procreation.","zh":"Ted Selker 把人們對打擾的熟悉程度比作對生育繁衍的熟悉程度。"},{"en":"Procreation means the biological process of producing children or offspring.","zh":"生育繁衍是產生子女或後代的生物過程。"},{"en":"In biology lessons, students may learn how procreation works in humans and animals.","zh":"在生物課中，學生可能學習人類和動物如何生育繁衍。"},{"en":"Selker’s comparison suggests interruptions are extremely common and deeply familiar to human life.","zh":"Selker 的比較暗示打擾在人類生活中極常見且非常熟悉。"},{"en":"This word is formal and usually appears in biological or serious discussion.","zh":"這個詞較正式，通常出現在生物學或嚴肅討論中。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":2},{"front":"be connected to","meaning":"與……連接","examples":[{"en":"Humanity has been connected to billions of networked devices.","zh":"人類已與數十億部連網裝置連接起來。"},{"en":"To be connected to something means to be linked with it, physically, digitally, or socially.","zh":"與某物連接，是指以實體、數碼或社會方式與它相連。"},{"en":"A printer must be connected to the office network before staff can use it.","zh":"打印機必須連接到辦公室網絡，員工才能使用。"},{"en":"Being connected to many devices can make life easier but also more interruptive.","zh":"與許多裝置連接可以令生活更方便，但也更容易被打擾。"},{"en":"This phrase describes links between people, machines, or systems.","zh":"這個短語描述人、機器或系統之間的連繫。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":2},{"front":"approximately three billion","meaning":"大約三十億","examples":[{"en":"Humanity has been connected to approximately three billion networked devices.","zh":"人類已連接到大約三十億部連網裝置。"},{"en":"Approximately three billion means about 3,000,000,000, not an exact number.","zh":"大約三十億，是指約 3,000,000,000，而不是精確數字。"},{"en":"A report may say approximately three billion people use a service when the figure is estimated.","zh":"當數字是估算時，報告可能說大約三十億人使用某服務。"},{"en":"Approximate numbers help readers understand scale without claiming perfect precision.","zh":"近似數字幫助讀者理解規模，而不聲稱完全精確。"},{"en":"This phrase signals a very large estimated quantity.","zh":"這個短語表示非常龐大的估計數量。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":2},{"front":"networked telephones","meaning":"連接網絡的電話","examples":[{"en":"Networked telephones are part of modern connected life.","zh":"連接網絡的電話是現代連接生活的一部分。"},{"en":"Networked telephones are phones linked to communication networks so they can send and receive calls or data.","zh":"連接網絡的電話，是連接到通訊網絡、能收發電話或數據的電話。"},{"en":"A smartphone is a networked telephone because it connects to mobile networks and the internet.","zh":"智能手機是連接網絡的電話，因為它連接到流動網絡和互聯網。"},{"en":"Networked telephones make communication easier but can also interrupt people constantly.","zh":"連網電話令溝通更容易，但也會不斷打擾人。"},{"en":"This phrase refers to phones as connected digital devices.","zh":"這個短語把電話視為連接的數碼裝置。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":2},{"front":"networked devices","meaning":"連接網絡的裝置","examples":[{"en":"Computers, phones and traffic lights are examples of networked devices.","zh":"電腦、電話和交通燈都是連接網絡的裝置例子。"},{"en":"Networked devices are machines connected to other machines or systems through a network.","zh":"連接網絡的裝置，是透過網絡與其他機器或系統連接的機器。"},{"en":"A smart watch is a networked device because it exchanges data with a phone or cloud service.","zh":"智能手錶是連網裝置，因為它與手機或雲端服務交換資料。"},{"en":"Networked devices can coordinate useful services, but they can also send too many alerts.","zh":"連網裝置可以協調有用服務，但也可能發送太多提示。"},{"en":"This phrase describes connected technology in daily life.","zh":"這個短語描述日常生活中的連接科技。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":2},{"front":"facilitate our daily lives","meaning":"便利我們的日常生活","examples":[{"en":"These devices facilitate our daily lives.","zh":"這些裝置便利我們的日常生活。"},{"en":"To facilitate our daily lives means to make everyday tasks easier or more convenient.","zh":"便利我們的日常生活，是指令日常任務更容易或更方便。"},{"en":"Online banking facilitates our daily lives by letting people pay bills without visiting a branch.","zh":"網上銀行讓人不用到分行也能繳付帳單，從而便利日常生活。"},{"en":"Technology facilitates daily life when it saves time and reduces effort.","zh":"當科技節省時間並減少努力時，它就在便利日常生活。"},{"en":"This phrase focuses on help and convenience.","zh":"這個短語聚焦幫助和方便。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":2},{"front":"typically turn off","meaning":"通常關掉","examples":[{"en":"People do not typically turn off their phones before concentrated work.","zh":"人們在專心工作前通常不會關掉電話。"},{"en":"Typically turn off means usually switch something off in a common situation.","zh":"通常關掉，是指在常見情況下一般會關閉某物。"},{"en":"Students typically turn off their phones before an exam because noise is not allowed.","zh":"學生考試前通常關掉電話，因為不容許有聲響。"},{"en":"If people do not turn devices off, alerts may interrupt important tasks.","zh":"如果人們不關掉裝置，提示可能打斷重要任務。"},{"en":"This phrase describes a normal or expected habit.","zh":"這個短語描述正常或預期習慣。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":2},{"front":"shut down the e-mail system","meaning":"關閉電郵系統","examples":[{"en":"Workers rarely shut down the e-mail system before a meeting.","zh":"員工在會議前很少關閉電郵系統。"},{"en":"To shut down the e-mail system means to stop or close the program or service that handles email.","zh":"關閉電郵系統，是指停止或關掉處理電郵的程式或服務。"},{"en":"A manager may shut down the e-mail system during a workshop so staff can focus.","zh":"經理可能在工作坊期間關閉電郵系統，讓員工專注。"},{"en":"If email is not shut down, new messages can distract people during discussion.","zh":"如果不關閉電郵，新訊息會在討論期間令人分心。"},{"en":"This phrase describes deliberately stopping email access or alerts.","zh":"這個短語描述刻意停止電郵存取或提示。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":2},{"front":"upcoming meeting","meaning":"即將舉行的會議","examples":[{"en":"People often leave their phones on even when they have an upcoming meeting.","zh":"即使有即將舉行的會議，人們也常把電話開着。"},{"en":"An upcoming meeting is a meeting that will happen soon.","zh":"即將舉行的會議，是很快會發生的會議。"},{"en":"Before an upcoming meeting, a worker may check notes and silence their phone.","zh":"在即將舉行的會議前，員工可能查看筆記並把手機靜音。"},{"en":"If devices stay noisy before and during a meeting, they can disturb preparation and discussion.","zh":"如果裝置在會議前和會議中仍發出聲音，會干擾準備和討論。"},{"en":"This phrase points to a scheduled event in the near future.","zh":"這個短語指近期將發生的已安排活動。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":2},{"front":"a stretch of concentrated work","meaning":"一段需要專心工作的時間","examples":[{"en":"People may need a stretch of concentrated work without interruptions.","zh":"人們可能需要一段不受打擾的專心工作時間。"},{"en":"A stretch of concentrated work is a continuous period spent focusing on one task.","zh":"一段需要專心工作的時間，是連續用來集中處理一項任務的時間。"},{"en":"A writer may need a stretch of concentrated work to finish an essay draft.","zh":"作者可能需要一段專心工作時間來完成文章初稿。"},{"en":"Interruptions break this stretch and make it harder to return to the same level of focus.","zh":"打擾會打斷這段時間，令重新回到同一專注程度更困難。"},{"en":"This phrase describes protected time for deep work.","zh":"這個短語描述受保護的深度工作時間。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":3},{"front":"merely endure the consequences","meaning":"只是忍受後果","examples":[{"en":"Most people merely endure the consequences of constant interruptions.","zh":"大多數人只是忍受不斷被打斷的後果。"},{"en":"To merely endure the consequences means only suffer the results without solving the problem.","zh":"只是忍受後果，是指只承受結果，而沒有解決問題。"},{"en":"A student who keeps studying beside a noisy TV may merely endure the consequences instead of moving rooms.","zh":"學生一直在吵鬧電視旁溫習，可能只是忍受後果，而不是換房間。"},{"en":"Enduring interruptions can lead to stress, mistakes, and slower work.","zh":"忍受打擾會導致壓力、錯誤和工作變慢。"},{"en":"This phrase suggests passive acceptance rather than active change.","zh":"這個短語暗示被動接受，而不是主動改變。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":3},{"front":"countless research reports","meaning":"無數研究報告","examples":[{"en":"Countless research reports have confirmed the effects of interruptions.","zh":"無數研究報告已確認打擾的影響。"},{"en":"Countless research reports means a very large number of studies or written findings.","zh":"無數研究報告，是指數量非常多的研究或書面發現。"},{"en":"Countless research reports show that sleep affects memory and concentration.","zh":"無數研究報告顯示睡眠會影響記憶和專注力。"},{"en":"When many reports confirm the same point, the claim becomes harder to ignore.","zh":"當許多報告確認同一點，該主張就更難被忽視。"},{"en":"This phrase emphasises strong support from many sources.","zh":"這個短語強調來自多個來源的強力支持。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":3},{"front":"unexpectedly interrupted","meaning":"突然被打斷","examples":[{"en":"People may work less efficiently when they are unexpectedly interrupted.","zh":"人們突然被打斷時，工作效率可能較低。"},{"en":"Unexpectedly interrupted means suddenly stopped or distracted without warning.","zh":"突然被打斷，是指在沒有預警下突然被阻止或分心。"},{"en":"A cashier may lose track of a payment if they are unexpectedly interrupted by another customer.","zh":"收銀員如果突然被另一位顧客打斷，可能忘記付款進度。"},{"en":"Unexpected interruptions can break mental flow and increase mistakes.","zh":"突然打擾會打斷思路並增加錯誤。"},{"en":"This phrase describes disruption that people have not prepared for.","zh":"這個短語描述人們未有準備的干擾。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":3},{"front":"suffer a drop in","meaning":"遭受……下降","examples":[{"en":"Interrupted workers may suffer a drop in work efficiency.","zh":"被打斷的員工可能遭受工作效率下降。"},{"en":"To suffer a drop in something means to experience a decrease in it.","zh":"遭受某事下降，是指經歷某方面減少。"},{"en":"A student may suffer a drop in marks after missing several weeks of lessons.","zh":"學生缺課幾星期後，成績可能下降。"},{"en":"When attention is broken repeatedly, performance can drop even if workers try hard.","zh":"當注意力反覆被打斷，即使員工努力，表現也會下降。"},{"en":"This phrase describes a negative fall in level or quality.","zh":"這個短語描述水平或質素上的負面下降。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":3},{"front":"work efficiency","meaning":"工作效率","examples":[{"en":"Interruptions can reduce work efficiency.","zh":"打擾會降低工作效率。"},{"en":"Work efficiency means how quickly and well work is completed with available time and effort.","zh":"工作效率是指用現有時間和努力完成工作的速度和質素。"},{"en":"Clear instructions improve work efficiency because staff waste less time guessing.","zh":"清晰指示能改善工作效率，因為員工較少浪費時間猜測。"},{"en":"Poor work efficiency can delay projects and increase stress.","zh":"工作效率低會延誤項目並增加壓力。"},{"en":"This phrase is about doing work effectively without unnecessary waste.","zh":"這個短語關於有效完成工作而不作不必要浪費。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":3},{"front":"be more likely to","meaning":"較有可能……","examples":[{"en":"Interrupted people are more likely to make mistakes.","zh":"被打斷的人較有可能犯錯。"},{"en":"Be more likely to means have a greater chance of doing or experiencing something.","zh":"較有可能，是指做某事或經歷某事的機會較高。"},{"en":"Tired drivers are more likely to miss road signs.","zh":"疲倦司機較有可能錯過路牌。"},{"en":"If people are repeatedly distracted, they are more likely to forget details.","zh":"如果人們反覆分心，他們較有可能忘記細節。"},{"en":"This phrase compares probability or risk.","zh":"這個短語比較可能性或風險。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":3},{"front":"make mistakes","meaning":"犯錯","examples":[{"en":"People are more likely to make mistakes after interruptions.","zh":"人們被打斷後較有可能犯錯。"},{"en":"To make mistakes means to do something incorrectly.","zh":"犯錯，是指做錯某事。"},{"en":"A student may make mistakes in spelling when writing too quickly.","zh":"學生寫得太快時，可能在拼寫上犯錯。"},{"en":"Interruptions can make mistakes more common because people lose track of what they were doing.","zh":"打擾會令人忘記自己正在做甚麼，從而令錯誤更常見。"},{"en":"This phrase describes errors in work, speech, calculation, or judgement.","zh":"這個短語描述工作、說話、計算或判斷上的錯誤。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":3},{"front":"according to","meaning":"根據……","examples":[{"en":"According to Robert G. Picard, interruptions build frustration.","zh":"根據 Robert G. Picard 的說法，打擾會累積挫敗感。"},{"en":"According to means based on what a person, source, or rule says.","zh":"根據，是指基於某人、來源或規則所說。"},{"en":"According to the timetable, the next train leaves at 8:15.","zh":"根據時間表，下一班火車 8:15 開出。"},{"en":"This phrase shows where information or an opinion comes from.","zh":"這個短語顯示資訊或意見來自哪裡。"},{"en":"It is useful when reporting another person’s view.","zh":"它適合用來報告他人的看法。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":3},{"front":"build frustration cumulatively","meaning":"逐漸累積挫敗感","examples":[{"en":"Interruptions appear to build frustration cumulatively.","zh":"打擾似乎會逐漸累積挫敗感。"},{"en":"To build frustration cumulatively means to increase annoyance little by little over time.","zh":"逐漸累積挫敗感，是指煩躁或不滿隨時間一點一點增加。"},{"en":"A worker may become irritated if small software errors build frustration cumulatively all morning.","zh":"如果整個早上都有小型軟件錯誤，員工可能逐漸累積挫敗感。"},{"en":"One interruption may be tolerable, but many interruptions can slowly create stress.","zh":"一次打擾可能可以忍受，但許多打擾會慢慢造成壓力。"},{"en":"This phrase describes frustration growing through repeated small events.","zh":"這個短語描述挫敗感如何透過反覆小事件增長。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":3},{"front":"resulting stress","meaning":"隨之而來的壓力","examples":[{"en":"The resulting stress makes it difficult to focus again.","zh":"隨之而來的壓力令重新集中精神變得困難。"},{"en":"Resulting stress is the stress that happens because of a previous event or problem.","zh":"隨之而來的壓力，是由先前事件或問題引起的壓力。"},{"en":"If a train delay makes someone late for an interview, the resulting stress may affect their performance.","zh":"如果火車延誤令某人面試遲到，隨之而來的壓力可能影響表現。"},{"en":"Stress from interruptions can stay in the mind even after the interruption ends.","zh":"打擾造成的壓力即使在打擾結束後仍可能留在腦中。"},{"en":"This phrase links a cause with the stress that follows.","zh":"這個短語把原因與之後出現的壓力連接起來。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":3},{"front":"make it difficult to","meaning":"令……變得困難","examples":[{"en":"Stress makes it difficult to focus again.","zh":"壓力令重新集中精神變得困難。"},{"en":"To make it difficult to do something means to create conditions that make the action harder.","zh":"令做某事變得困難，是指創造令該行動更難的條件。"},{"en":"Noise can make it difficult to read a long article carefully.","zh":"噪音會令仔細閱讀長文章變得困難。"},{"en":"Interruptions make it difficult to finish work because people must rebuild concentration.","zh":"打擾令完成工作變得困難，因為人們必須重新建立專注力。"},{"en":"This phrase explains how one problem blocks another action.","zh":"這個短語解釋一個問題如何阻礙另一行動。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":4},{"front":"focus again","meaning":"重新集中精神","examples":[{"en":"After an interruption, it can be difficult to focus again.","zh":"被打斷後，重新集中精神可能很困難。"},{"en":"To focus again means to return attention to the original task after being distracted.","zh":"重新集中精神，是指分心後把注意力帶回原本任務。"},{"en":"A student may need several minutes to focus again after checking a message.","zh":"學生查看訊息後可能需要幾分鐘才能重新集中精神。"},{"en":"If interruptions happen too often, people spend more time recovering focus than working.","zh":"如果打擾太頻密，人們花在恢復專注上的時間可能比工作更多。"},{"en":"This phrase describes the effort of returning to concentration.","zh":"這個短語描述回到專注狀態的努力。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":4},{"front":"not solely about","meaning":"並不單是關於……","examples":[{"en":"The problem is not solely about productivity and the pace of life.","zh":"這個問題並不單是關於生產力和生活節奏。"},{"en":"Not solely about something means not only about that thing; other issues are involved too.","zh":"並不單是關於某事，是指不只是關於該事，還涉及其他問題。"},{"en":"School stress is not solely about homework; sleep, family pressure, and exams also matter.","zh":"學業壓力並不單是關於功課；睡眠、家庭壓力和考試也很重要。"},{"en":"This phrase widens the discussion beyond one explanation.","zh":"這個短語把討論擴展到單一解釋以外。"},{"en":"It is useful when a problem has several dimensions.","zh":"當問題有多個層面時，它很有用。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":4},{"front":"productivity and the pace of life","meaning":"生產力和生活節奏","examples":[{"en":"Interruptions affect productivity and the pace of life.","zh":"打擾會影響生產力和生活節奏。"},{"en":"Productivity and the pace of life refer to how much people get done and how fast daily life feels.","zh":"生產力和生活節奏，是指人們完成多少工作，以及日常生活感覺有多快。"},{"en":"Constant messages can reduce productivity and make the pace of life feel rushed.","zh":"不斷出現的訊息會降低生產力，並令生活節奏感覺急促。"},{"en":"When technology speeds everything up, people may work more but feel less calm.","zh":"當科技加快一切，人們可能工作更多，但感覺較不平靜。"},{"en":"This phrase connects work output with the rhythm of everyday living.","zh":"這個短語把工作產出與日常生活節奏連接起來。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":4},{"front":"loss of focus","meaning":"失去專注","examples":[{"en":"For some professionals, loss of focus can be disastrous.","zh":"對某些專業人士而言，失去專注可能是災難性的。"},{"en":"Loss of focus means losing concentration on the task that needs attention.","zh":"失去專注，是指對需要注意的任務失去集中力。"},{"en":"A driver’s loss of focus for just two seconds can cause an accident.","zh":"司機只失去專注兩秒也可能造成意外。"},{"en":"In serious jobs, loss of focus can lead to mistakes that harm others.","zh":"在嚴肅工作中，失去專注會導致傷害他人的錯誤。"},{"en":"This phrase describes a dangerous drop in attention.","zh":"這個短語描述注意力上的危險下降。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":4},{"front":"downright disastrous","meaning":"徹底災難性的","examples":[{"en":"For pilots and doctors, loss of focus can be downright disastrous.","zh":"對機師和醫生而言，失去專注可能是徹底災難性的。"},{"en":"Downright disastrous means completely and clearly terrible in its consequences.","zh":"徹底災難性的，是指後果完全且明顯非常糟糕。"},{"en":"Forgetting to check a patient’s allergy record could be downright disastrous.","zh":"忘記檢查病人的敏感紀錄可能是徹底災難性的。"},{"en":"Some errors are not merely inconvenient; they can cause serious harm.","zh":"有些錯誤不只是帶來不便，而是會造成嚴重傷害。"},{"en":"This phrase strongly emphasises how bad a result can be.","zh":"這個短語強烈強調結果可以有多糟。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":4},{"front":"find a way to","meaning":"找到方法去……","examples":[{"en":"Researchers hope to find a way to make computers more considerate.","zh":"研究人員希望找到方法令電腦更體貼。"},{"en":"To find a way to do something means to discover a method for achieving it.","zh":"找到方法做某事，是指發現達成該事的方法。"},{"en":"A teacher may find a way to help shy students speak more confidently.","zh":"老師可能找到方法幫助害羞學生更有信心地說話。"},{"en":"Finding a way usually requires testing ideas and solving practical problems.","zh":"找到方法通常需要測試想法和解決實際問題。"},{"en":"This phrase focuses on searching for a workable solution.","zh":"這個短語聚焦尋找可行方案。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":4},{"front":"realise the limits of","meaning":"意識到……的限制","examples":[{"en":"Computers should realise the limits of human attention and memory.","zh":"電腦應該意識到人類注意力和記憶力的限制。"},{"en":"To realise the limits of something means to understand how far it can go before it fails.","zh":"意識到某事的限制，是指明白它在失效前能承受多少。"},{"en":"Good teachers realise the limits of students’ concentration and give short breaks.","zh":"好老師會意識到學生專注力的限制，並安排短休息。"},{"en":"If a system ignores human limits, it may overload people with too many demands.","zh":"如果系統忽視人類限制，它可能以太多要求令使用者超負荷。"},{"en":"This phrase means recognising boundaries, not criticising weakness.","zh":"這個短語指認清界限，而不是批評弱點。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":4},{"front":"human attention and memory","meaning":"人類注意力和記憶力","examples":[{"en":"Devices need to respect the limits of human attention and memory.","zh":"裝置需要尊重人類注意力和記憶力的限制。"},{"en":"Human attention and memory are the mental abilities to focus on information and remember it.","zh":"人類注意力和記憶力，是集中於資訊並記住它的心理能力。"},{"en":"A student’s attention and memory can suffer after a night without sleep.","zh":"一晚沒有睡眠後，學生的注意力和記憶力可能受損。"},{"en":"Too many alerts can overload human attention and make memory less reliable.","zh":"太多提示會令人類注意力超負荷，並令記憶較不可靠。"},{"en":"This phrase names two mental limits that technology should consider.","zh":"這個短語指出科技應考慮的兩種心理限制。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":4},{"front":"come off as","meaning":"顯得像是……","examples":[{"en":"Computers may come off as more thoughtful if they respect human attention.","zh":"如果電腦尊重人類注意力，它們可能顯得更體貼。"},{"en":"To come off as something means to appear or seem that way to others.","zh":"顯得像是某樣，是指在別人眼中看起來或感覺如此。"},{"en":"A student who listens before speaking may come off as mature and respectful.","zh":"先聆聽再說話的學生可能顯得成熟而有禮。"},{"en":"A device that interrupts less may come off as helpful rather than annoying.","zh":"較少打擾人的裝置可能顯得有幫助，而不是煩人。"},{"en":"This phrase describes the impression something gives.","zh":"這個短語描述某物給人的印象。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":4},{"front":"thoughtful and courteous","meaning":"體貼而有禮貌","examples":[{"en":"Smarter devices may seem more thoughtful and courteous.","zh":"更聰明的裝置可能顯得更體貼而有禮貌。"},{"en":"Thoughtful and courteous means considerate, polite, and aware of other people’s needs.","zh":"體貼而有禮貌，是指為人着想、有禮並意識到別人的需要。"},{"en":"A thoughtful and courteous colleague knocks before entering a meeting room.","zh":"體貼而有禮貌的同事會先敲門，再進入會議室。"},{"en":"If technology waits for a suitable moment, users may feel respected.","zh":"如果科技等待合適時刻，使用者可能感到被尊重。"},{"en":"This phrase describes polite behaviour, whether from people or carefully designed machines.","zh":"這個短語描述有禮行為，不論來自人或精心設計的機器。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":4},{"front":"a small but growing group of","meaning":"一小群但正在增加的……","examples":[{"en":"A small but growing group of researchers is studying considerate technology.","zh":"一小群但正在增加的研究人員正在研究體貼科技。"},{"en":"A small but growing group of people means the group is still limited but increasing in size.","zh":"一小群但正在增加的人，是指群體仍然有限，但人數正在增加。"},{"en":"A small but growing group of schools is replacing long homework with shorter practice tasks.","zh":"一小群但正在增加的學校正在用較短練習取代長篇功課。"},{"en":"Growth suggests that more people are starting to see the issue as important.","zh":"增長暗示越來越多人開始認為該議題重要。"},{"en":"This phrase shows early but increasing interest.","zh":"這個短語顯示早期但正在增加的興趣。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":5},{"front":"attempt to make","meaning":"嘗試令……","examples":[{"en":"Researchers are attempting to make devices more considerate.","zh":"研究人員正嘗試令裝置更體貼。"},{"en":"To attempt to make something a certain way means to try to change or design it that way.","zh":"嘗試令某物變成某種樣子，是指努力改變或設計它成那樣。"},{"en":"A teacher may attempt to make grammar lessons more practical with real conversations.","zh":"老師可能透過真實對話嘗試令文法課更實用。"},{"en":"Attempts may fail at first because new designs need testing and improvement.","zh":"嘗試起初可能失敗，因為新設計需要測試和改善。"},{"en":"This phrase describes purposeful effort toward change.","zh":"這個短語描述朝改變作出的有目的努力。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":5},{"front":"function more like","meaning":"運作起來更像……","examples":[{"en":"Future devices may function more like considerate colleagues.","zh":"未來裝置運作起來可能更像體貼同事。"},{"en":"To function more like something means to operate in a similar way to it.","zh":"運作起來更像某物，是指以相似方式運行。"},{"en":"A good school app should function more like a helpful assistant than a confusing notice board.","zh":"好的學校應用程式應該更像有幫助的助手，而不是混亂告示板。"},{"en":"If devices function more like people who understand context, interruptions can become less annoying.","zh":"如果裝置運作得更像理解語境的人，打擾會較不煩人。"},{"en":"This phrase compares how something works.","zh":"這個短語比較某物如何運作。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":5},{"front":"considerate colleagues","meaning":"體貼的同事","examples":[{"en":"Researchers want devices to behave like considerate colleagues.","zh":"研究人員希望裝置像體貼的同事一樣行動。"},{"en":"Considerate colleagues are co-workers who think about others’ time, workload, and concentration.","zh":"體貼的同事，是會考慮別人時間、工作量和專注力的同事。"},{"en":"A considerate colleague sends a message instead of calling when they know you are teaching.","zh":"體貼的同事知道你在教學時，會發訊息而不是打電話。"},{"en":"Considerate colleagues reduce stress because they do not interrupt without reason.","zh":"體貼同事能減少壓力，因為他們不會無故打斷。"},{"en":"This phrase is used as a model for how polite technology should behave.","zh":"這個短語被用作有禮科技應如何行動的模型。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":5},{"front":"egocentric oafs","meaning":"自我中心的笨蛋","examples":[{"en":"Current devices can behave like egocentric oafs.","zh":"現時裝置可能表現得像自我中心的笨蛋。"},{"en":"Egocentric oafs are rude, clumsy people who act as if only their own needs matter.","zh":"自我中心的笨蛋，是粗魯、笨拙並表現得好像只有自己需要重要的人。"},{"en":"A person who shouts across the office during someone’s phone call behaves like an egocentric oaf.","zh":"在別人通電話時大聲穿過辦公室喊叫的人，就像自我中心的笨蛋。"},{"en":"Devices seem like egocentric oafs when they interrupt important work for minor updates.","zh":"當裝置為小更新打斷重要工作時，它們就像自我中心的笨蛋。"},{"en":"This phrase strongly criticises behaviour that is selfish and insensitive.","zh":"這個短語強烈批評自私且不敏感的行為。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":5},{"front":"new skills of three kinds","meaning":"三類新技能","examples":[{"en":"The machines need new skills of three kinds.","zh":"這些機器需要三類新技能。"},{"en":"New skills of three kinds means three different types of abilities that machines must develop.","zh":"三類新技能，是指機器必須發展的三種不同能力。"},{"en":"A school robot may need skills of three kinds: listening, moving safely, and answering questions.","zh":"學校機械人可能需要三類技能：聆聽、安全移動和回答問題。"},{"en":"Dividing skills into types helps researchers understand what problems must be solved.","zh":"把技能分成類別有助研究人員理解必須解決哪些問題。"},{"en":"This phrase introduces a structured list of abilities.","zh":"這個短語引入一個有結構的能力列表。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":5},{"front":"sensing, reasoning and communicating","meaning":"感知、推理和溝通","examples":[{"en":"Considerate machines need sensing, reasoning and communicating skills.","zh":"體貼機器需要感知、推理和溝通技能。"},{"en":"Sensing, reasoning and communicating are abilities to detect information, think about it, and share responses.","zh":"感知、推理和溝通，是探測資訊、思考資訊並分享回應的能力。"},{"en":"A smart assistant senses your calendar, reasons that you are busy, and communicates by delaying a message.","zh":"智能助手感知你的日程，推理你很忙，然後透過延遲訊息來溝通。"},{"en":"All three skills are needed because noticing a situation is not enough without deciding what to do.","zh":"三種技能都需要，因為只注意到情況而不決定怎樣做並不足夠。"},{"en":"This phrase describes the main abilities behind considerate technology.","zh":"這個短語描述體貼科技背後的主要能力。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":5},{"front":"sense or infer","meaning":"感知或推斷","examples":[{"en":"A system must sense or infer where its owner is.","zh":"系統必須感知或推斷主人在哪裡。"},{"en":"To sense or infer something means to detect it directly or work it out from clues.","zh":"感知或推斷某事，是指直接探測它，或從線索推算出來。"},{"en":"A phone may sense your location by GPS or infer you are driving from movement patterns.","zh":"手機可能透過 GPS 感知你的位置，或從移動模式推斷你正在駕駛。"},{"en":"If a device can sense or infer context, it can choose a better time to interrupt.","zh":"如果裝置能感知或推斷語境，它就能選擇較好的打擾時間。"},{"en":"This phrase combines direct detection with intelligent guessing.","zh":"這個短語結合直接探測和智能猜測。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":5},{"front":"what he or she is doing","meaning":"他或她正在做甚麼","examples":[{"en":"The system must infer what he or she is doing.","zh":"系統必須推斷他或她正在做甚麼。"},{"en":"What he or she is doing means the activity the person is currently engaged in.","zh":"他或她正在做甚麼，是指該人目前正在進行的活動。"},{"en":"A device may infer what a user is doing from calendar entries, keyboard use, or location.","zh":"裝置可能從日程項目、鍵盤使用或位置推斷使用者正在做甚麼。"},{"en":"Knowing the activity helps the system decide whether an alert would be disruptive.","zh":"知道活動有助系統決定提示會否造成打擾。"},{"en":"This phrase focuses on the user’s current situation.","zh":"這個短語聚焦使用者目前情況。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":5},{"front":"weigh…against…","meaning":"權衡……與……","examples":[{"en":"The system must weigh the value of a message against the cost of disruption.","zh":"系統必須權衡訊息價值與打擾代價。"},{"en":"To weigh one thing against another means to compare their benefits and costs before deciding.","zh":"權衡一事與另一事，是指在決定前比較它們的好處和成本。"},{"en":"A student may weigh extra revision against the need for sleep before an exam.","zh":"學生考試前可能權衡額外溫習與睡眠需要。"},{"en":"Good decisions often require balancing importance against possible harm.","zh":"好決定通常需要把重要性與可能傷害作平衡。"},{"en":"This phrase is useful when two competing factors must be judged together.","zh":"當兩個互相競爭的因素必須一起判斷時，這個短語很有用。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":5},{"front":"convey a message","meaning":"傳達訊息","examples":[{"en":"The system must decide whether it should convey a message.","zh":"系統必須決定是否應該傳達訊息。"},{"en":"To convey a message means to pass information or meaning to someone.","zh":"傳達訊息，是指把資訊或意思傳給某人。"},{"en":"A teacher may convey a message to parents through an email notice.","zh":"老師可能透過電郵通告向家長傳達訊息。"},{"en":"If a message is urgent, the system may need to convey it immediately.","zh":"如果訊息緊急，系統可能需要立即傳達。"},{"en":"This phrase focuses on delivering meaning, not only sending words.","zh":"這個短語聚焦傳遞意思，而不只是發送文字。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":5},{"front":"the cost of the disruption","meaning":"打擾所帶來的代價","examples":[{"en":"The machine must consider the cost of the disruption.","zh":"機器必須考慮打擾所帶來的代價。"},{"en":"The cost of the disruption means the harm caused by interrupting someone, such as lost focus or stress.","zh":"打擾所帶來的代價，是指打斷某人造成的傷害，例如失去專注或壓力。"},{"en":"A phone call during surgery would have a high cost of disruption.","zh":"手術期間的電話會有很高的打擾代價。"},{"en":"If the cost of disruption is high, a system should delay non-urgent alerts.","zh":"如果打擾代價很高，系統應延遲不緊急提示。"},{"en":"This phrase treats attention as something valuable that can be damaged.","zh":"這個短語把注意力視為會被損害的寶貴東西。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":6},{"front":"choose the best mode and time","meaning":"選擇最佳方式和時間","examples":[{"en":"The device must choose the best mode and time to interject.","zh":"裝置必須選擇最佳方式和時間來插話。"},{"en":"To choose the best mode and time means to decide how and when to deliver information.","zh":"選擇最佳方式和時間，是指決定如何以及何時傳遞資訊。"},{"en":"A phone may choose a silent notification during class and a loud ringtone after school.","zh":"手機可能在上課時選擇靜音通知，放學後才用響亮鈴聲。"},{"en":"Good timing can make the same message helpful rather than annoying.","zh":"好時機可以令同一訊息變得有幫助，而不是煩人。"},{"en":"This phrase combines communication method with timing.","zh":"這個短語結合溝通方法和時間安排。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":6},{"front":"interject","meaning":"插話；打斷","examples":[{"en":"The system has to decide when to interject.","zh":"系統必須決定何時插話。"},{"en":"To interject means to interrupt briefly by adding a message or comment.","zh":"插話，是指透過加入訊息或評論而短暫打斷。"},{"en":"A student should not interject while a classmate is giving a presentation unless it is urgent.","zh":"除非緊急，學生不應在同學演講時插話。"},{"en":"A device that interjects at the wrong moment can break concentration.","zh":"在錯誤時刻插話的裝置會打斷專注。"},{"en":"This word describes interruption, often with a short inserted message.","zh":"這個詞描述打斷，通常是插入一段短訊息。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":6},{"front":"push the limits of","meaning":"挑戰……的極限","examples":[{"en":"Each skill pushes the limits of computer science.","zh":"每項技能都挑戰電腦科學的極限。"},{"en":"To push the limits of something means to test how far it can go or what it can achieve.","zh":"挑戰某事的極限，是指測試它能走多遠或能達成甚麼。"},{"en":"Medical researchers push the limits of science when they try to treat rare diseases.","zh":"醫學研究人員嘗試治療罕見疾病時，會挑戰科學極限。"},{"en":"Difficult problems push limits because existing methods may not be enough.","zh":"困難問題會挑戰極限，因為現有方法可能不足夠。"},{"en":"This phrase suggests challenge, innovation, and difficulty.","zh":"這個短語暗示挑戰、創新和困難。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":6},{"front":"computer science","meaning":"電腦科學","examples":[{"en":"The problem pushes the limits of computer science.","zh":"這個問題挑戰電腦科學的極限。"},{"en":"Computer science is the study of computers, software, data, algorithms, and how systems process information.","zh":"電腦科學是研究電腦、軟件、數據、演算法和系統如何處理資訊的學科。"},{"en":"Students studying computer science may learn programming, networks, and artificial intelligence.","zh":"學習電腦科學的學生可能學編程、網絡和人工智能。"},{"en":"Problems involving human attention are difficult because computers must understand context, not just data.","zh":"涉及人類注意力的問題很困難，因為電腦必須理解語境，而不只是數據。"},{"en":"This phrase refers to the academic and technical field behind computing.","zh":"這個短語指運算背後的學術和技術領域。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":6},{"front":"raise issues of","meaning":"引發……方面的問題","examples":[{"en":"The technology raises issues of privacy and reliability.","zh":"這項科技引發私隱和可靠性方面的問題。"},{"en":"To raise issues of something means to create questions, concerns, or problems about it.","zh":"引發某方面的問題，是指產生相關疑問、擔憂或麻煩。"},{"en":"CCTV in classrooms may raise issues of privacy and trust.","zh":"課室閉路電視可能引發私隱和信任方面的問題。"},{"en":"New technology can be useful while still raising serious ethical questions.","zh":"新科技可以有用，但仍引發嚴重倫理問題。"},{"en":"This phrase introduces concerns that need discussion.","zh":"這個短語引入需要討論的擔憂。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":6},{"front":"privacy, complexity or reliability","meaning":"私隱、複雜性或可靠性","examples":[{"en":"Considerate computing raises issues of privacy, complexity or reliability.","zh":"體貼式運算引發私隱、複雜性或可靠性方面的問題。"},{"en":"Privacy, complexity or reliability are concerns about personal data, system difficulty, and whether technology works correctly.","zh":"私隱、複雜性或可靠性，是關於個人資料、系統難度和科技是否正確運作的擔憂。"},{"en":"A school app may raise privacy concerns if it tracks students’ locations.","zh":"如果學校應用程式追蹤學生位置，可能引發私隱問題。"},{"en":"Complex systems can fail if they are too hard to design, test, or explain.","zh":"如果系統太難設計、測試或解釋，複雜系統可能失效。"},{"en":"This phrase lists major risks behind smart technology.","zh":"這個短語列出智能科技背後的主要風險。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":6},{"front":"attentive computing systems","meaning":"注意力感知電腦系統","examples":[{"en":"Attentive computing systems have started to appear in new products.","zh":"注意力感知電腦系統已開始出現在新產品中。"},{"en":"Attentive computing systems are computer systems that notice a user’s attention and situation.","zh":"注意力感知電腦系統，是會注意使用者注意力和情況的電腦系統。"},{"en":"A car that checks whether the driver is tired uses an attentive computing system.","zh":"會檢查司機是否疲倦的汽車使用注意力感知電腦系統。"},{"en":"These systems can reduce danger by responding when attention is low.","zh":"這些系統可以在注意力低時作出反應，從而減少危險。"},{"en":"This phrase describes technology that tries to be aware of human focus.","zh":"這個短語描述嘗試感知人類專注狀態的科技。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":6},{"front":"make an appearance","meaning":"出現；開始露面","examples":[{"en":"Attentive computing systems have started to make an appearance in the latest Volvos.","zh":"注意力感知電腦系統已開始在最新款富豪汽車中出現。"},{"en":"To make an appearance means to appear or become visible in a place or situation.","zh":"出現或開始露面，是指在某地方或情況中變得可見。"},{"en":"Smart screens are starting to make an appearance in many classrooms.","zh":"智能屏幕正開始在許多課室中出現。"},{"en":"When a technology makes an appearance in products, it begins moving from research to real use.","zh":"當一項科技出現在產品中，它開始由研究走向實際使用。"},{"en":"This phrase often suggests something is newly arriving.","zh":"這個短語常暗示某事正在新近出現。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":6},{"front":"the latest Volvos","meaning":"最新款富豪汽車","examples":[{"en":"Attentive computing systems have appeared in the latest Volvos.","zh":"注意力感知電腦系統已出現在最新款富豪汽車中。"},{"en":"The latest Volvos means the newest models of cars made by Volvo.","zh":"最新款富豪汽車，是指 Volvo 製造的最新車款。"},{"en":"The latest Volvos may include driver-assistance features that older cars do not have.","zh":"最新款富豪汽車可能包括舊車沒有的駕駛輔助功能。"},{"en":"New car models often introduce safety technology before it becomes common elsewhere.","zh":"新車款常先引入安全科技，之後才在其他地方普及。"},{"en":"This phrase points to recent products from a specific car company.","zh":"這個短語指某特定汽車公司的近期產品。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":6},{"front":"designed and developed","meaning":"設計並開發","examples":[{"en":"IBM has designed and developed communications software.","zh":"IBM 已設計並開發通訊軟件。"},{"en":"Designed and developed means planned, created, tested, and improved into a working product.","zh":"設計並開發，是指規劃、創造、測試並改良成可用產品。"},{"en":"A school may design and develop an app for homework reminders.","zh":"學校可能設計並開發一個功課提醒應用程式。"},{"en":"Development turns an idea into software that people can actually use.","zh":"開發把想法變成人們真正能使用的軟件。"},{"en":"This phrase covers both planning and building.","zh":"這個短語涵蓋規劃和建構。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":6},{"front":"communications software","meaning":"通訊軟件","examples":[{"en":"IBM developed communications software called WebSphere.","zh":"IBM 開發了一款名為 WebSphere 的通訊軟件。"},{"en":"Communications software is software that helps people or systems send, receive, or manage messages.","zh":"通訊軟件是幫助人或系統發送、接收或管理訊息的軟件。"},{"en":"Email platforms and video-call apps are types of communications software.","zh":"電郵平台和視像通話應用程式都是通訊軟件。"},{"en":"Good communications software can reduce missed messages and organise contact more clearly.","zh":"良好通訊軟件可以減少錯過訊息，並更清楚地整理聯絡。"},{"en":"This phrase refers to software built for communication tasks.","zh":"這個短語指為通訊任務而設的軟件。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":7},{"front":"come with","meaning":"附帶；具備","examples":[{"en":"WebSphere comes with an underlying sense of busyness.","zh":"WebSphere 具備對忙碌程度的基本感知。"},{"en":"To come with something means to include or have that feature as part of it.","zh":"附帶或具備某物，是指包含或擁有該特徵作為其中一部分。"},{"en":"A new phone may come with a charger and a one-year warranty.","zh":"新手機可能附帶充電器和一年保養。"},{"en":"Software that comes with useful features can save users extra setup time.","zh":"附帶有用功能的軟件可以節省使用者額外設定時間。"},{"en":"This phrase describes what is included or built in.","zh":"這個短語描述包含或內置的東西。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":7},{"front":"an underlying sense of","meaning":"對……的基本感知","examples":[{"en":"The software comes with an underlying sense of busyness.","zh":"這款軟件具備對忙碌程度的基本感知。"},{"en":"An underlying sense of something means a basic built-in awareness or feeling of it.","zh":"對某事的基本感知，是指對它有一種內置的基本察覺或感覺。"},{"en":"A good teacher has an underlying sense of when students are tired or confused.","zh":"好老師對學生何時疲倦或困惑有基本感知。"},{"en":"If software has an underlying sense of busyness, it can avoid interrupting at bad times.","zh":"如果軟件對忙碌程度有基本感知，它就能避免在不合適時候打擾。"},{"en":"This phrase describes a deeper awareness behind visible action.","zh":"這個短語描述可見行動背後的深層意識。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":7},{"front":"sense of busyness","meaning":"對忙碌程度的感知","examples":[{"en":"WebSphere has a sense of busyness.","zh":"WebSphere 具有對忙碌程度的感知。"},{"en":"A sense of busyness is an awareness of how busy or available a person seems to be.","zh":"對忙碌程度的感知，是指察覺一個人看起來有多忙或是否有空。"},{"en":"A receptionist has a sense of busyness when they notice which staff members are in meetings.","zh":"接待員注意到哪些員工正在開會時，就是有對忙碌程度的感知。"},{"en":"A system with this sense can decide whether to interrupt now or wait.","zh":"具備這種感知的系統可以決定現在打擾還是等待。"},{"en":"This phrase connects technology with awareness of human workload.","zh":"這個短語把科技與對人類工作量的察覺連接起來。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":7},{"front":"conduct extensive in-house tests","meaning":"進行大規模內部測試","examples":[{"en":"Microsoft has been conducting extensive in-house tests.","zh":"Microsoft 一直在進行大規模內部測試。"},{"en":"To conduct extensive in-house tests means to carry out many detailed tests inside the organisation.","zh":"進行大規模內部測試，是指在組織內部進行許多詳細測試。"},{"en":"A company may conduct extensive in-house tests before releasing a new app to customers.","zh":"公司可能在向顧客推出新應用程式前進行大規模內部測試。"},{"en":"Internal testing helps find problems before the public uses the product.","zh":"內部測試有助在公眾使用產品前找出問題。"},{"en":"This phrase describes careful testing within the company itself.","zh":"這個短語描述公司內部的仔細測試。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":7},{"front":"far more sophisticated","meaning":"複雜得多；先進得多","examples":[{"en":"Microsoft tested a far more sophisticated system.","zh":"Microsoft 測試了一個先進得多的系統。"},{"en":"Far more sophisticated means much more advanced, complex, or intelligently designed.","zh":"複雜得多或先進得多，是指更高階、更複雜或設計更智能。"},{"en":"A modern smartphone is far more sophisticated than an old calculator.","zh":"現代智能手機比舊計算機先進得多。"},{"en":"More sophisticated systems can handle difficult tasks, but they may also be harder to build.","zh":"更先進系統可以處理困難任務，但也可能更難建造。"},{"en":"This phrase compares a higher level of technical development.","zh":"這個短語比較較高技術發展水平。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":7},{"front":"in a couple of years","meaning":"幾年內","examples":[{"en":"In a couple of years, companies may provide such software to office employees.","zh":"幾年內，公司可能向辦公室員工提供這類軟件。"},{"en":"In a couple of years means after about two years, or within a few years.","zh":"幾年內，是指約兩年後或數年之內。"},{"en":"In a couple of years, a new school building may be ready for students.","zh":"幾年內，新校舍可能準備好給學生使用。"},{"en":"This phrase gives an approximate future time, not an exact date.","zh":"這個短語給出大約未來時間，而不是精確日期。"},{"en":"It is useful when describing expected development soon but not immediately.","zh":"它適合描述預期不久後但非立即出現的發展。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":7},{"front":"manage to provide","meaning":"成功提供","examples":[{"en":"Companies might manage to provide each employee with a software assistant.","zh":"公司可能成功為每位員工提供一個軟件助手。"},{"en":"To manage to provide something means to succeed in giving it despite difficulty or effort.","zh":"成功提供某物，是指雖有困難或需要努力，仍成功給予它。"},{"en":"A small school may manage to provide tablets for all students through donations.","zh":"小學校可能透過捐款成功為所有學生提供平板電腦。"},{"en":"Providing technology to everyone can be difficult because of cost, training, and support.","zh":"向所有人提供科技可能困難，因為涉及成本、培訓和支援。"},{"en":"This phrase suggests achievement after effort.","zh":"這個短語暗示經努力後取得成果。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":7},{"front":"office employee","meaning":"辦公室員工","examples":[{"en":"The software may one day be available to each office employee.","zh":"這款軟件有一天可能可供每位辦公室員工使用。"},{"en":"An office employee is a person who works in an office, usually doing administrative, professional, or support tasks.","zh":"辦公室員工是在辦公室工作的人，通常處理行政、專業或支援任務。"},{"en":"An office employee may spend much of the day answering emails and attending meetings.","zh":"辦公室員工可能一天中大部分時間都在回覆電郵和參加會議。"},{"en":"Office employees often face many digital interruptions during work.","zh":"辦公室員工在工作時常面對許多數碼打擾。"},{"en":"This phrase refers to workers in office settings.","zh":"這個短語指辦公室環境中的工作者。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":7},{"front":"a software version of","meaning":"……的軟件版本","examples":[{"en":"The system may become a software version of a personal receptionist.","zh":"該系統可能成為個人接待員的軟件版本。"},{"en":"A software version of something is a digital program that performs a similar role to it.","zh":"某物的軟件版本，是執行相似角色的數碼程式。"},{"en":"A calendar app can be a software version of a paper diary.","zh":"日曆應用程式可以是紙本日記的軟件版本。"},{"en":"Software versions can make services cheaper and more widely available.","zh":"軟件版本可以令服務更便宜、更普及。"},{"en":"This phrase compares a digital tool with a real-world role or object.","zh":"這個短語把數碼工具與真實世界的角色或物件作比較。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":7},{"front":"personal receptionist","meaning":"個人接待員","examples":[{"en":"The software may act like a personal receptionist.","zh":"這款軟件可能像個人接待員一樣運作。"},{"en":"A personal receptionist is someone who manages calls, visitors, appointments, and messages for one person.","zh":"個人接待員是為某一個人管理來電、訪客、約會和訊息的人。"},{"en":"A busy executive may rely on a personal receptionist to screen calls during meetings.","zh":"忙碌行政人員可能依靠個人接待員在會議期間篩選來電。"},{"en":"A digital receptionist could reduce interruptions by deciding which messages are urgent.","zh":"數碼接待員可以透過判斷哪些訊息緊急來減少打擾。"},{"en":"This phrase describes a helper who controls access and communication.","zh":"這個短語描述控制接觸和通訊的助手。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":7},{"front":"be available to","meaning":"可供……使用","examples":[{"en":"Personal receptionists are usually available only to senior executives.","zh":"個人接待員通常只可供高級行政人員使用。"},{"en":"To be available to someone means they can use or access it.","zh":"可供某人使用，是指他們可以使用或取得它。"},{"en":"Free tutoring may be available to students who need extra help.","zh":"免費補習可能可供需要額外幫助的學生使用。"},{"en":"If a service becomes available to more people, its benefits spread beyond a small group.","zh":"如果服務可供更多人使用，其好處就會擴展到小群體以外。"},{"en":"This phrase describes access or availability.","zh":"這個短語描述使用權或可取得性。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":8},{"front":"corner-suite executives","meaning":"享有高級角落辦公室的行政人員","examples":[{"en":"Personal receptionists are usually available to corner-suite executives.","zh":"個人接待員通常可供享有高級角落辦公室的行政人員使用。"},{"en":"Corner-suite executives are senior managers with high status, often imagined as having large private offices.","zh":"享有高級角落辦公室的行政人員，是地位高的高級管理層，常被想像為擁有大型私人辦公室。"},{"en":"A corner-suite executive may have assistants who manage calls and appointments.","zh":"這類行政人員可能有助理管理來電和約會。"},{"en":"The phrase suggests privilege because only senior people usually receive such support.","zh":"這個短語暗示特權，因為通常只有高層才有這種支援。"},{"en":"This phrase is used to contrast powerful executives with ordinary office workers.","zh":"這個短語用來對比有權力的行政人員與普通辦公室員工。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":8},{"front":"the truth is that","meaning":"事實是……","examples":[{"en":"The truth is that most people are not as busy as they claim to be.","zh":"事實是，大多數人不像自己聲稱的那樣忙。"},{"en":"The truth is that means the speaker is about to state what they believe is the real situation.","zh":"事實是，是指說話者將說出他們認為真實的情況。"},{"en":"The truth is that many students waste time because they do not plan their revision.","zh":"事實是，許多學生浪費時間，是因為沒有規劃溫習。"},{"en":"This phrase often introduces a blunt or corrective point.","zh":"這個短語常引入直接或糾正性的觀點。"},{"en":"It signals that the speaker wants to cut through excuses or appearances.","zh":"它表示說話者想穿透藉口或表象。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":8},{"front":"not as busy as…claim to be","meaning":"不像……聲稱的那樣忙","examples":[{"en":"Most people are not as busy as they claim to be.","zh":"大多數人不像自己聲稱的那樣忙。"},{"en":"Not as busy as someone claims to be means less busy than they say they are.","zh":"不像某人聲稱的那樣忙，是指沒有他們所說那麼忙。"},{"en":"A colleague may say they are overloaded, but their calendar shows they are not as busy as they claim to be.","zh":"同事可能說自己工作爆滿，但日程顯示他並不像聲稱的那樣忙。"},{"en":"People may overstate busyness because they want to seem important or unavailable.","zh":"人們可能誇大忙碌程度，因為想顯得重要或沒空。"},{"en":"This phrase compares real busyness with stated busyness.","zh":"這個短語比較真實忙碌程度與聲稱的忙碌程度。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":8},{"front":"stand interruptions","meaning":"忍受打擾","examples":[{"en":"People can often stand interruptions from electronic devices.","zh":"人們常能忍受來自電子裝置的打擾。"},{"en":"To stand interruptions means to tolerate or endure being interrupted.","zh":"忍受打擾，是指容忍或承受被打斷。"},{"en":"A receptionist may stand many interruptions because answering questions is part of the job.","zh":"接待員可能忍受許多打擾，因為回答問題是工作一部分。"},{"en":"Even if people can stand interruptions, their work may still become slower.","zh":"即使人們能忍受打擾，他們的工作仍可能變慢。"},{"en":"This phrase describes tolerance, not approval.","zh":"這個短語描述容忍，而不是認同。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":8},{"front":"inconsiderate electronic paraphernalia","meaning":"欠體貼的電子設備","examples":[{"en":"People often tolerate interruptions from inconsiderate electronic paraphernalia.","zh":"人們常容忍來自欠體貼電子設備的打擾。"},{"en":"Inconsiderate electronic paraphernalia means electronic gadgets that interrupt without thinking about the user’s situation.","zh":"欠體貼的電子設備，是不考慮使用者情況就打擾人的電子工具。"},{"en":"A smartwatch that buzzes during every lesson can feel like inconsiderate electronic paraphernalia.","zh":"每堂課都震動的智能手錶可能感覺像欠體貼的電子設備。"},{"en":"Such devices may be useful but still create stress by demanding attention too often.","zh":"這類裝置可能有用，但仍會因過度要求注意而造成壓力。"},{"en":"This phrase criticises electronic tools as cluttered, rude, and intrusive.","zh":"這個短語批評電子工具雜亂、無禮且侵擾。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":8},{"front":"find out the extent to which","meaning":"找出……的程度","examples":[{"en":"Researchers tried to find out the extent to which disruptions take up people’s time.","zh":"研究人員嘗試找出打擾佔用人們時間的程度。"},{"en":"To find out the extent to which something happens means to discover how much or how far it happens.","zh":"找出某事發生的程度，是指發現它發生多少或影響多遠。"},{"en":"A school may find out the extent to which homework affects students’ sleep.","zh":"學校可能找出功課影響學生睡眠的程度。"},{"en":"Measuring the extent of a problem helps people decide how serious it is.","zh":"衡量問題程度有助人們判斷它有多嚴重。"},{"en":"This phrase is used when investigating degree or scale.","zh":"這個短語用於調查程度或規模。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":8},{"front":"claim people’s daily time","meaning":"佔用人們的日常時間","examples":[{"en":"Disruption may claim part of people’s daily time.","zh":"打擾可能佔用人們部分日常時間。"},{"en":"To claim people’s daily time means to take up or consume part of their day.","zh":"佔用人們的日常時間，是指耗用他們一天中的一部分時間。"},{"en":"Long commutes can claim people’s daily time before they even start work.","zh":"長途通勤在人們開始工作前已會佔用日常時間。"},{"en":"If interruptions claim too much time, important work is delayed.","zh":"如果打擾佔用太多時間，重要工作就會延誤。"},{"en":"This phrase presents time as something that can be taken away.","zh":"這個短語把時間呈現為可以被取走的東西。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":8},{"front":"an IBM Research team","meaning":"IBM研究團隊","examples":[{"en":"An IBM Research team studied workers at the workplace.","zh":"一個 IBM 研究團隊在工作場所研究員工。"},{"en":"An IBM Research team is a group of researchers working for IBM’s research division.","zh":"IBM 研究團隊，是在 IBM 研究部門工作的研究人員小組。"},{"en":"An IBM Research team may test how office software affects employees’ attention.","zh":"IBM 研究團隊可能測試辦公室軟件如何影響員工注意力。"},{"en":"Research teams collect evidence so companies can design better technology.","zh":"研究團隊收集證據，使公司能設計更好的科技。"},{"en":"This phrase identifies the organisation behind the study.","zh":"這個短語指出研究背後的組織。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":8},{"front":"led by","meaning":"由……帶領","examples":[{"en":"The research team was led by Jennifer Lai.","zh":"該研究團隊由 Jennifer Lai 帶領。"},{"en":"Led by means guided, managed, or directed by a particular person.","zh":"由某人帶領，是指由某人指導、管理或領導。"},{"en":"A school project led by a science teacher may involve experiments and reports.","zh":"由科學老師帶領的學校項目可能涉及實驗和報告。"},{"en":"Leadership matters because the leader shapes goals, methods, and decisions.","zh":"領導很重要，因為領導者塑造目標、方法和決策。"},{"en":"This phrase identifies who was in charge.","zh":"這個短語指出誰負責。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":8},{"front":"managers, researchers and interns","meaning":"經理、研究員和實習生","examples":[{"en":"The team studied managers, researchers and interns.","zh":"該團隊研究了經理、研究員和實習生。"},{"en":"Managers, researchers and interns are workers with different levels of responsibility and experience.","zh":"經理、研究員和實習生，是責任和經驗程度不同的工作者。"},{"en":"A company study may include managers, researchers and interns to compare different work patterns.","zh":"公司研究可能包括經理、研究員和實習生，以比較不同工作模式。"},{"en":"Studying several job groups gives a fuller picture of workplace interruptions.","zh":"研究幾個職位群體能更全面了解工作場所打擾。"},{"en":"This phrase lists different occupational roles in an organisation.","zh":"這個短語列出組織中的不同職業角色。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":8},{"front":"at the workplace","meaning":"在工作場所","examples":[{"en":"The study observed people at the workplace.","zh":"該研究在工作場所觀察人們。"},{"en":"At the workplace means in the place where people do their jobs.","zh":"在工作場所，是指在人們工作的地方。"},{"en":"Stress at the workplace can come from deadlines, meetings, and constant messages.","zh":"工作場所中的壓力可能來自截止日期、會議和不斷出現的訊息。"},{"en":"Observing people at the workplace gives researchers real behaviour, not just opinions.","zh":"在工作場所觀察人們能讓研究人員得到真實行為，而不只是意見。"},{"en":"This phrase describes a job setting.","zh":"這個短語描述工作環境。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":9},{"front":"videotaped the subjects","meaning":"錄影拍攝研究對象","examples":[{"en":"The researchers videotaped the subjects during the study.","zh":"研究人員在研究期間錄影拍攝研究對象。"},{"en":"To videotape the subjects means to record the people being studied on video.","zh":"錄影拍攝研究對象，是指以影片記錄被研究的人。"},{"en":"Researchers may videotape classroom discussions to study how students interact.","zh":"研究人員可能錄影拍攝課堂討論，以研究學生如何互動。"},{"en":"Video records help researchers review behaviour carefully after the event.","zh":"影片紀錄幫助研究人員在事後仔細回看行為。"},{"en":"This phrase describes a research method using video evidence.","zh":"這個短語描述使用影片證據的研究方法。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":9},{"front":"at specified intervals","meaning":"每隔指定時間","examples":[{"en":"The researchers questioned the subjects at specified intervals.","zh":"研究人員每隔指定時間詢問研究對象。"},{"en":"At specified intervals means at fixed or clearly chosen times.","zh":"每隔指定時間，是指在固定或清楚選定的時間點。"},{"en":"A nurse may check a patient’s temperature at specified intervals during the night.","zh":"護士可能在夜間每隔指定時間檢查病人體溫。"},{"en":"Regular intervals help researchers compare responses over time.","zh":"定期時間間隔幫助研究人員比較隨時間變化的回應。"},{"en":"This phrase describes planned timing, not random timing.","zh":"這個短語描述有計劃的時間安排，而不是隨機時間。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":9},{"front":"evaluate their interruptibility","meaning":"評估自己可被打擾的程度","examples":[{"en":"The subjects were asked to evaluate their interruptibility.","zh":"研究對象被要求評估自己可被打擾的程度。"},{"en":"To evaluate their interruptibility means to judge how open they were to being interrupted.","zh":"評估自己可被打擾的程度，是判斷自己當時有多能接受被打擾。"},{"en":"A worker may evaluate their interruptibility as low when writing an urgent report.","zh":"員工寫緊急報告時，可能把自己的可被打擾程度評為低。"},{"en":"Asking people to rate this helps researchers know when interruptions are most harmful.","zh":"要求人們評分有助研究人員知道何時打擾最有害。"},{"en":"This phrase describes self-assessment of how interruptible someone is.","zh":"這個短語描述對自己可否被打擾的自我評估。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":9},{"front":"interruptibility","meaning":"可被打擾程度","examples":[{"en":"The study measured workers’ interruptibility.","zh":"該研究量度員工的可被打擾程度。"},{"en":"Interruptibility is the degree to which someone can be interrupted without serious harm to their work.","zh":"可被打擾程度，是某人能被打斷而不嚴重影響工作的程度。"},{"en":"A receptionist may have high interruptibility, while a surgeon may have very low interruptibility.","zh":"接待員的可被打擾程度可能很高，而外科醫生可能非常低。"},{"en":"Interruptibility changes depending on task difficulty, stress, and time pressure.","zh":"可被打擾程度會因任務難度、壓力和時間壓力而改變。"},{"en":"This word describes how suitable a person is for interruption at a given moment.","zh":"這個詞描述某人在特定時刻適不適合被打擾。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":9},{"front":"a leave-me-alone state","meaning":"不想被打擾的狀態","examples":[{"en":"Workers sometimes entered a leave-me-alone state.","zh":"員工有時進入不想被打擾的狀態。"},{"en":"A leave-me-alone state is a period when someone strongly wants not to be interrupted.","zh":"不想被打擾的狀態，是某人強烈希望不被打斷的一段時間。"},{"en":"A student writing a timed essay may be in a leave-me-alone state.","zh":"正在限時寫作文的學生可能處於不想被打擾的狀態。"},{"en":"Interrupting someone in this state can damage focus and increase frustration.","zh":"在這種狀態下打擾某人會破壞專注並增加挫敗感。"},{"en":"This phrase describes a need for privacy and concentration.","zh":"這個短語描述對私隱和專注的需要。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":9},{"front":"vary from individual to individual","meaning":"因人而異","examples":[{"en":"The time spent in this state varied from individual to individual.","zh":"處於這種狀態的時間因人而異。"},{"en":"To vary from individual to individual means to be different for each person.","zh":"因人而異，是指每個人都不同。"},{"en":"The amount of sleep students need can vary from individual to individual.","zh":"學生需要的睡眠時間可能因人而異。"},{"en":"Personal differences matter because one rule may not suit everyone.","zh":"個人差異很重要，因為一條規則未必適合所有人。"},{"en":"This phrase highlights variation among people.","zh":"這個短語突出人與人之間的差異。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":9},{"front":"day to day","meaning":"每天不同","examples":[{"en":"The time also varied from day to day.","zh":"該時間也每天不同。"},{"en":"Day to day means from one day to the next, with possible changes each day.","zh":"每天不同，是指由一天到下一天都可能有變化。"},{"en":"A teacher’s workload may vary day to day depending on meetings and marking.","zh":"老師工作量可能因會議和改卷而每天不同。"},{"en":"If interruptibility changes day to day, systems must adapt rather than use fixed rules.","zh":"如果可被打擾程度每天不同，系統就必須適應，而不是使用固定規則。"},{"en":"This phrase describes daily variation.","zh":"這個短語描述每日變化。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":9},{"front":"range from…to…","meaning":"由……至……不等","examples":[{"en":"The percentage ranged from 10 to 51 per cent.","zh":"百分比由 10% 至 51% 不等。"},{"en":"Range from A to B means cover all values between a lower and an upper point.","zh":"由 A 至 B 不等，是指涵蓋低點與高點之間的所有數值。"},{"en":"Class sizes may range from 15 to 35 students depending on the school.","zh":"班級人數可能因學校而由 15 人至 35 人不等。"},{"en":"A wide range shows that different people or situations can vary greatly.","zh":"範圍大顯示不同人或情況可以有很大差異。"},{"en":"This phrase is useful for describing numerical spread.","zh":"這個短語適合描述數字範圍。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":9},{"front":"work without interruption","meaning":"不受打擾地工作","examples":[{"en":"Employees wished to work without interruption for part of the day.","zh":"員工希望一天中有部分時間不受打擾地工作。"},{"en":"To work without interruption means to continue working without being stopped or distracted.","zh":"不受打擾地工作，是指在沒有被停止或分心的情況下繼續工作。"},{"en":"A designer may close the office door to work without interruption on a difficult drawing.","zh":"設計師可能關上辦公室門，不受打擾地完成困難圖則。"},{"en":"Working without interruption can improve accuracy and help people finish complex tasks faster.","zh":"不受打擾地工作可以提高準確度，並幫助人更快完成複雜任務。"},{"en":"This phrase describes protected focus time.","zh":"這個短語描述受保護的專注時間。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":9},{"front":"roughly one-third of the time","meaning":"約三分之一的時間","examples":[{"en":"Employees wanted quiet work time for roughly one-third of the time.","zh":"員工希望約三分之一的時間是安靜工作時間。"},{"en":"Roughly one-third of the time means about 33% of the total time.","zh":"約三分之一的時間，是指總時間大約 33%。"},{"en":"A student may spend roughly one-third of study time reviewing old mistakes.","zh":"學生可能用約三分之一的溫習時間檢討舊錯誤。"},{"en":"Approximate fractions help describe patterns without needing exact numbers.","zh":"大約比例有助描述模式，而不需要精確數字。"},{"en":"This phrase gives an estimated share of time.","zh":"這個短語給出估計時間比例。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":9},{"front":"similarly","meaning":"同樣地","examples":[{"en":"Similarly, Horvitz found that Microsoft workers often had low attention demands.","zh":"同樣地，Horvitz 發現 Microsoft 員工常有低注意力需求。"},{"en":"Similarly means in a similar way or for a similar reason.","zh":"同樣地，是指以相似方式或基於相似原因。"},{"en":"The first class struggled with grammar; similarly, the second class needed more practice.","zh":"第一班在文法上有困難；同樣地，第二班也需要更多練習。"},{"en":"This word connects two findings or examples that point in the same direction.","zh":"這個詞連接兩個指向同一方向的發現或例子。"},{"en":"It is useful for showing a parallel.","zh":"它適合用來顯示平行情況。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":10},{"front":"ordinarily spend","meaning":"通常花費","examples":[{"en":"Microsoft workers ordinarily spend much of their day in a low-attention mode.","zh":"Microsoft 員工通常一天中很多時間都處於低注意力模式。"},{"en":"Ordinarily spend means usually use time in a certain way.","zh":"通常花費，是指一般以某種方式使用時間。"},{"en":"Office workers ordinarily spend mornings checking messages and planning tasks.","zh":"辦公室員工通常在早上花時間查看訊息和規劃任務。"},{"en":"Knowing how people ordinarily spend time helps designers create better systems.","zh":"知道人們通常如何使用時間，有助設計師創造更好的系統。"},{"en":"This phrase describes normal time use.","zh":"這個短語描述正常時間使用方式。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":10},{"front":"over 65 per cent of their day","meaning":"每天超過65%的時間","examples":[{"en":"They ordinarily spend over 65 per cent of their day in a low-attention mode.","zh":"他們通常每天超過 65% 的時間處於低注意力模式。"},{"en":"Over 65 per cent of their day means more than 65% of their daily time.","zh":"每天超過 65% 的時間，是指每日時間多於 65%。"},{"en":"A student who spends over 65 per cent of the evening online may have little time left for sleep.","zh":"如果學生每晚超過 65% 的時間上網，可能剩下很少時間睡覺。"},{"en":"Large percentages show that a behaviour occupies a major part of the day.","zh":"大百分比顯示某行為佔據一天中的主要部分。"},{"en":"This phrase gives a numerical measure of daily time.","zh":"這個短語給出每日時間的數字量度。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":10},{"front":"low-attention mode","meaning":"低注意力模式","examples":[{"en":"Microsoft workers often spend time in a low-attention mode.","zh":"Microsoft 員工常花時間處於低注意力模式。"},{"en":"Low-attention mode is a state in which a person does not need deep concentration.","zh":"低注意力模式，是一個人不需要高度集中精神的狀態。"},{"en":"A worker checking routine emails may be in a low-attention mode.","zh":"員工查看例行電郵時可能處於低注意力模式。"},{"en":"In low-attention mode, interruptions may be less damaging than during difficult work.","zh":"在低注意力模式中，打擾造成的傷害可能比困難工作期間小。"},{"en":"This phrase describes a period when a person may be easier to interrupt.","zh":"這個短語描述一段較容易被打擾的時間。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":10},{"front":"be correct about two-thirds of the time","meaning":"約三分之二時間是正確的","examples":[{"en":"Phones and computers are correct about two-thirds of the time.","zh":"電話和電腦約三分之二時間是正確的。"},{"en":"To be correct about two-thirds of the time means to be right in roughly 66% of cases.","zh":"約三分之二時間是正確的，是指大約 66% 情況下正確。"},{"en":"A weather app that is correct about two-thirds of the time is useful but not fully reliable.","zh":"如果天氣應用程式約三分之二時間正確，它有用但不完全可靠。"},{"en":"If a system is wrong one-third of the time, users may still find it annoying.","zh":"如果系統三分之一時間出錯，使用者仍可能覺得煩人。"},{"en":"This phrase gives an approximate accuracy rate.","zh":"這個短語給出大約準確率。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":10},{"front":"assuming that","meaning":"假設","examples":[{"en":"Devices often act by assuming that users are available.","zh":"裝置常透過假設使用者有空來行動。"},{"en":"Assuming that means acting as if something is true without checking fully.","zh":"假設，是指在未完全確認下把某事當成真。"},{"en":"A teacher may make a mistake by assuming that every student has internet at home.","zh":"老師如果假設每個學生家中都有互聯網，可能會犯錯。"},{"en":"If devices assume users are free, they may interrupt important tasks.","zh":"如果裝置假設使用者有空，就可能打斷重要任務。"},{"en":"This phrase describes an unchecked belief behind an action.","zh":"這個短語描述行動背後未經核實的信念。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":10},{"front":"be available to","meaning":"有空去……","examples":[{"en":"Users are often available to answer a call or check an e-mail.","zh":"使用者常有空接聽電話或查看電郵。"},{"en":"To be available to do something means to have the time or ability to do it now.","zh":"有空做某事，是指現在有時間或能力做它。"},{"en":"A doctor may not be available to answer a call during surgery.","zh":"醫生手術期間可能沒有空接聽電話。"},{"en":"Availability changes depending on meetings, tasks, and attention level.","zh":"是否有空會因會議、任務和注意力水平而改變。"},{"en":"This phrase describes whether someone can respond at a given moment.","zh":"這個短語描述某人在特定時刻能否回應。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":10},{"front":"answer a call","meaning":"接聽電話","examples":[{"en":"Users are often available to answer a call.","zh":"使用者常有空接聽電話。"},{"en":"To answer a call means to pick up or respond to a phone call.","zh":"接聽電話，是指接起或回應來電。"},{"en":"A receptionist answers calls from visitors who need directions.","zh":"接待員接聽需要方向指引的訪客來電。"},{"en":"Answering a call during deep work can break concentration.","zh":"在深度工作期間接聽電話會打斷專注。"},{"en":"This phrase describes responding to a phone ringing.","zh":"這個短語描述回應響起的電話。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":10},{"front":"check an e-mail","meaning":"查看電郵","examples":[{"en":"Users are often available to check an e-mail.","zh":"使用者常有空查看電郵。"},{"en":"To check an e-mail means to open and read an email message.","zh":"查看電郵，是指打開並閱讀電郵訊息。"},{"en":"A worker may check an e-mail before replying to a customer.","zh":"員工可能在回覆顧客前查看電郵。"},{"en":"Checking emails too often can interrupt larger tasks.","zh":"太頻密查看電郵會打斷較大的任務。"},{"en":"This phrase describes a common digital communication action.","zh":"這個短語描述常見的數碼通訊行動。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":10},{"front":"alert box","meaning":"提示框","examples":[{"en":"A computer may ask users to click the OK button on an alert box.","zh":"電腦可能要求使用者在提示框上按 OK 按鈕。"},{"en":"An alert box is a small window that appears on a screen to warn or inform the user.","zh":"提示框是在螢幕上出現、用來警告或通知使用者的小視窗。"},{"en":"An alert box may say that a file has not been saved.","zh":"提示框可能顯示檔案尚未儲存。"},{"en":"Alert boxes can be useful, but too many of them interrupt work.","zh":"提示框可以有用，但太多提示框會打斷工作。"},{"en":"This phrase describes a common computer pop-up message.","zh":"這個短語描述常見的電腦彈出訊息。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":10},{"front":"functional and useful","meaning":"功能正常且實用","examples":[{"en":"Considerate systems must be both functional and useful.","zh":"體貼系統必須功能正常且實用。"},{"en":"Functional and useful means able to work properly and genuinely help people.","zh":"功能正常且實用，是指能正常運作並真正幫助人。"},{"en":"A school app is functional and useful if it loads quickly and helps students find homework.","zh":"如果學校應用程式載入快速並幫助學生找到功課，它就是功能正常且實用。"},{"en":"A system can function technically but still not be useful if people dislike using it.","zh":"系統技術上可以運作，但如果人們不喜歡使用，仍可能不實用。"},{"en":"This phrase requires both performance and practical value.","zh":"這個短語要求同時具備性能和實際價值。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":10},{"front":"accuracy","meaning":"準確度","examples":[{"en":"The system’s accuracy has to be above 65 per cent.","zh":"系統的準確度必須高於 65%。"},{"en":"Accuracy is the degree to which something is correct or exact.","zh":"準確度是某事正確或精確的程度。"},{"en":"A calculator needs high accuracy because wrong answers can mislead students.","zh":"計算機需要高準確度，因為錯誤答案會誤導學生。"},{"en":"If a system’s accuracy is too low, users will stop trusting it.","zh":"如果系統準確度太低，使用者就會停止信任它。"},{"en":"This word measures how often a system gets things right.","zh":"這個詞衡量系統有多常做對。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":11},{"front":"sense when","meaning":"感知何時……","examples":[{"en":"The system must sense when users are close to their cognitive limit.","zh":"系統必須感知使用者何時接近認知極限。"},{"en":"To sense when something happens means to detect the moment or condition in which it happens.","zh":"感知某事何時發生，是指探測它發生的時刻或條件。"},{"en":"A smart light may sense when someone enters a room and turn on automatically.","zh":"智能燈可能感知何時有人進入房間，並自動開啟。"},{"en":"If software can sense when a user is overloaded, it can delay non-urgent messages.","zh":"如果軟件能感知使用者何時超負荷，它就能延遲不緊急訊息。"},{"en":"This phrase connects detection with timing.","zh":"這個短語把探測與時間判斷連接起來。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":11},{"front":"be about to reach","meaning":"即將達到","examples":[{"en":"Users may be about to reach their cognitive limit.","zh":"使用者可能即將達到認知極限。"},{"en":"To be about to reach something means to be very close to reaching it soon.","zh":"即將達到某事，是指很快就會到達該狀態。"},{"en":"A runner may be about to reach the finish line after the final turn.","zh":"跑手轉過最後一個彎後，可能即將到達終點。"},{"en":"If a person is about to reach a mental limit, another interruption may cause mistakes.","zh":"如果一個人即將達到心理極限，另一個打擾可能造成錯誤。"},{"en":"This phrase describes a near-future state.","zh":"這個短語描述即將出現的狀態。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":11},{"front":"cognitive limit","meaning":"認知極限","examples":[{"en":"The system must know when users are reaching their cognitive limit.","zh":"系統必須知道使用者何時正在達到認知極限。"},{"en":"A cognitive limit is the point at which the mind can no longer handle more information or tasks well.","zh":"認知極限是大腦無法再良好處理更多資訊或任務的界線。"},{"en":"A student may reach a cognitive limit after hours of revision without breaks.","zh":"學生連續溫習數小時而不休息後，可能達到認知極限。"},{"en":"When people reach this limit, they may forget details, misunderstand messages, or make mistakes.","zh":"當人們達到這個極限，可能忘記細節、誤解訊息或犯錯。"},{"en":"This phrase describes a boundary of mental capacity.","zh":"這個短語描述心理容量的界限。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":11},{"front":"inspired by","meaning":"受……啟發","examples":[{"en":"Bestcom-ET was inspired by Horvitz’s work.","zh":"Bestcom-ET 受 Horvitz 的工作啟發。"},{"en":"Inspired by something means influenced or encouraged by it.","zh":"受某事啟發，是指受其影響或鼓勵。"},{"en":"A student may write a poem inspired by a family memory.","zh":"學生可能寫一首受家庭記憶啟發的詩。"},{"en":"Research can inspire new products when ideas are turned into working systems.","zh":"當想法變成可運作系統，研究可以啟發新產品。"},{"en":"This phrase describes the source of an idea or motivation.","zh":"這個短語描述想法或動機的來源。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":11},{"front":"prototype","meaning":"原型；試驗版本","examples":[{"en":"Bestcom-ET was a Microsoft prototype.","zh":"Bestcom-ET 是 Microsoft 的原型。"},{"en":"A prototype is an early test version of a product or system.","zh":"原型是產品或系統的早期測試版本。"},{"en":"Engineers may build a prototype of a new chair before producing thousands of them.","zh":"工程師可能先製作新椅子的原型，再大量生產。"},{"en":"Prototypes help designers find problems before the final version is released.","zh":"原型幫助設計師在最終版本推出前找出問題。"},{"en":"This word describes a trial model, not a finished product.","zh":"這個詞描述試驗模型，而不是完成品。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":11},{"front":"dig a bit deeper into","meaning":"更深入地探查……","examples":[{"en":"The system digs a bit deeper into every user’s computer.","zh":"系統更深入地探查每位使用者的電腦。"},{"en":"To dig a bit deeper into something means to examine it more closely for more information.","zh":"更深入地探查某事，是指更仔細檢查它以取得更多資訊。"},{"en":"A teacher may dig a bit deeper into a student’s mistakes to find the real weakness.","zh":"老師可能更深入地探查學生錯誤，以找出真正弱點。"},{"en":"Deeper checking can reveal clues that a quick look would miss.","zh":"更深入檢查可以揭示快速查看會錯過的線索。"},{"en":"This phrase suggests more detailed investigation.","zh":"這個短語暗示更詳細調查。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":11},{"front":"find clues about","meaning":"尋找關於……的線索","examples":[{"en":"The system looks for clues about what users are doing.","zh":"系統尋找關於使用者正在做甚麼的線索。"},{"en":"To find clues about something means to look for small pieces of information that help explain it.","zh":"尋找關於某事的線索，是指尋找有助解釋它的小片資訊。"},{"en":"A doctor may find clues about an illness by asking when symptoms started.","zh":"醫生可能透過詢問症狀何時開始，尋找關於疾病的線索。"},{"en":"Clues help people or systems make better guesses when direct information is missing.","zh":"當缺乏直接資訊時，線索幫助人或系統作出更好猜測。"},{"en":"This phrase describes evidence-gathering.","zh":"這個短語描述收集證據。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":11},{"front":"what they are dealing with","meaning":"他們正在處理的事情","examples":[{"en":"Bestcom searches for clues about what users are dealing with.","zh":"Bestcom 尋找關於使用者正在處理甚麼事情的線索。"},{"en":"What they are dealing with means the tasks, problems, or situations they are currently handling.","zh":"他們正在處理的事情，是指他們目前正在應對的任務、問題或情況。"},{"en":"A manager may ask what staff are dealing with before giving them more work.","zh":"經理在給員工更多工作前，可能詢問他們正在處理甚麼。"},{"en":"Knowing what someone is dealing with helps others decide whether it is a good time to interrupt.","zh":"知道某人正在處理甚麼，有助別人判斷是否適合打擾。"},{"en":"This phrase focuses on a person’s current workload or problem.","zh":"這個短語聚焦一個人目前的工作量或問題。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":11},{"front":"launch an internal beta test","meaning":"展開內部測試版測試","examples":[{"en":"Microsoft launched an internal beta test of the system in mid-2003.","zh":"Microsoft 在 2003 年中展開該系統的內部測試版測試。"},{"en":"To launch an internal beta test means to start testing an unfinished product inside the company.","zh":"展開內部測試版測試，是指在公司內部開始測試尚未完成的產品。"},{"en":"A software firm may launch an internal beta test before inviting public users.","zh":"軟件公司可能在邀請公眾使用者前展開內部測試版測試。"},{"en":"Internal beta testing helps teams find bugs and improve features safely.","zh":"內部測試版測試幫助團隊安全地找出錯誤並改善功能。"},{"en":"This phrase describes an early controlled test of software.","zh":"這個短語描述軟件的早期受控測試。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":11},{"front":"in mid-2003","meaning":"在2003年中","examples":[{"en":"Microsoft launched the test in mid-2003.","zh":"Microsoft 在 2003 年中展開測試。"},{"en":"In mid-2003 means around the middle part of the year 2003.","zh":"在 2003 年中，是指 2003 年中段左右。"},{"en":"A project launched in mid-2003 may have begun around June or July.","zh":"在 2003 年中展開的項目，可能約在六月或七月開始。"},{"en":"This phrase gives an approximate historical time.","zh":"這個短語給出大約歷史時間。"},{"en":"It helps place the development of the technology in sequence.","zh":"它幫助把科技發展按時間排序。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":11},{"front":"by the end of","meaning":"到……結束時","examples":[{"en":"By the end of last October, thousands of people had used the system.","zh":"到去年十月底時，已有數千人使用過該系統。"},{"en":"By the end of a period means before that period finished.","zh":"到某段時間結束時，是指在該時期完成之前。"},{"en":"By the end of the school year, students should know all the key vocabulary.","zh":"到學年結束時，學生應掌握所有關鍵詞彙。"},{"en":"This phrase gives a deadline for completion or measurement.","zh":"這個短語給出完成或量度的期限。"},{"en":"It shows that something happened before a named endpoint.","zh":"它顯示某事在指定終點前已發生。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":12},{"front":"rely on the system to","meaning":"依靠系統去……","examples":[{"en":"Nearly 3,800 people relied on the system to handle calls.","zh":"近 3,800 人依靠系統處理來電。"},{"en":"To rely on the system to do something means to trust it to perform that task.","zh":"依靠系統做某事，是指信任它執行該任務。"},{"en":"A school may rely on an online system to record attendance.","zh":"學校可能依靠網上系統記錄出席率。"},{"en":"If people rely on a system, it must be accurate and dependable.","zh":"如果人們依靠系統，它就必須準確和可靠。"},{"en":"This phrase describes trust in technology to carry out work.","zh":"這個短語描述對科技執行工作的信任。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":12},{"front":"field incoming calls","meaning":"處理來電","examples":[{"en":"The system helped users field their incoming calls.","zh":"系統幫助使用者處理來電。"},{"en":"To field incoming calls means to handle, answer, screen, or redirect calls that come in.","zh":"處理來電，是指接聽、篩選或轉駁打進來的電話。"},{"en":"A receptionist fields incoming calls before passing urgent ones to the manager.","zh":"接待員處理來電，再把緊急電話轉給經理。"},{"en":"Fielding calls can protect busy people from unnecessary interruptions.","zh":"處理來電可以保護忙碌人士免受不必要打擾。"},{"en":"This phrase describes managing calls as they arrive.","zh":"這個短語描述電話到達時的管理。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":12},{"front":"in fact","meaning":"事實上","examples":[{"en":"Horvitz is, in fact, a tester himself.","zh":"Horvitz 事實上本人也是測試者。"},{"en":"In fact means actually, often used to add a surprising or clarifying detail.","zh":"事實上，是指實際上，常用來加入令人意外或澄清性的細節。"},{"en":"The app is not difficult to use; in fact, most students learn it in ten minutes.","zh":"這個應用程式不難用；事實上，大多數學生十分鐘內就學會。"},{"en":"This phrase can correct an assumption or strengthen a point.","zh":"這個短語可以修正假設或加強重點。"},{"en":"It often introduces information that makes the previous idea clearer.","zh":"它常引入令前面想法更清楚的資訊。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":12},{"front":"a tester himself","meaning":"本人也是測試者","examples":[{"en":"Horvitz is a tester himself.","zh":"Horvitz 本人也是測試者。"},{"en":"A tester himself means the person personally tests the system, not only studies or manages it.","zh":"本人也是測試者，是指該人親自測試系統，而不只是研究或管理它。"},{"en":"A teacher who designs a learning app may become a tester herself before students use it.","zh":"設計學習應用程式的老師在學生使用前，自己也可能成為測試者。"},{"en":"Testing a system personally can reveal problems that reports do not show.","zh":"親自測試系統可以揭示報告沒有顯示的問題。"},{"en":"This phrase stresses direct personal involvement.","zh":"這個短語強調直接個人參與。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":12},{"front":"have our conversation","meaning":"進行我們的談話","examples":[{"en":"Bestcom handles calls while we have our conversation.","zh":"當我們進行談話時，Bestcom 處理來電。"},{"en":"To have our conversation means to talk together for a period of time.","zh":"進行我們的談話，是指一起談話一段時間。"},{"en":"A receptionist may hold calls while two managers have their conversation in a meeting room.","zh":"當兩位經理在會議室談話時，接待員可能暫緩來電。"},{"en":"If calls are handled quietly, people can have a conversation without being interrupted.","zh":"如果電話被安靜地處理，人們就能不受打擾地談話。"},{"en":"This phrase describes an ongoing spoken exchange.","zh":"這個短語描述正在進行的口頭交流。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":12},{"front":"silently take care of","meaning":"默默處理","examples":[{"en":"Bestcom silently takes care of all the calls.","zh":"Bestcom 默默處理所有來電。"},{"en":"To silently take care of something means to handle it quietly without disturbing others.","zh":"默默處理某事，是指安靜地處理它，而不打擾其他人。"},{"en":"A good assistant may silently take care of room bookings during a busy event.","zh":"好助理可能在繁忙活動期間默默處理房間預訂。"},{"en":"Quiet handling is useful because the main conversation or task can continue.","zh":"安靜處理很有用，因為主要談話或任務可以繼續。"},{"en":"This phrase suggests efficient background support.","zh":"這個短語暗示有效的背景支援。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":12},{"front":"address book","meaning":"通訊錄","examples":[{"en":"The system checks whether the caller is in the address book.","zh":"系統檢查來電者是否在通訊錄中。"},{"en":"An address book is a list of contacts, often including names, phone numbers, and email addresses.","zh":"通訊錄是聯絡人列表，通常包括姓名、電話號碼和電郵地址。"},{"en":"A phone’s address book helps users call friends and colleagues quickly.","zh":"手機通訊錄幫助使用者快速致電朋友和同事。"},{"en":"Checking the address book helps the system identify whether a caller is known.","zh":"檢查通訊錄幫助系統識別來電者是否已知。"},{"en":"This phrase refers to stored contact information.","zh":"這個短語指儲存的聯絡資訊。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":12},{"front":"company directory","meaning":"公司通訊錄","examples":[{"en":"The system checks the company directory.","zh":"系統檢查公司通訊錄。"},{"en":"A company directory is a list of employees and contact details within an organisation.","zh":"公司通訊錄是一個組織內員工和聯絡資料的列表。"},{"en":"New staff may use the company directory to find a manager’s phone number.","zh":"新員工可能使用公司通訊錄尋找經理電話號碼。"},{"en":"Checking the directory helps identify whether a caller works in the same company.","zh":"檢查通訊錄有助識別來電者是否在同一公司工作。"},{"en":"This phrase refers to an organisation’s internal contact list.","zh":"這個短語指組織內部聯絡人列表。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":12},{"front":"recent call list","meaning":"最近通話清單","examples":[{"en":"The system also checks the recent call list.","zh":"系統也檢查最近通話清單。"},{"en":"A recent call list is a record of phone calls made or received recently.","zh":"最近通話清單，是近期撥出或接收電話的紀錄。"},{"en":"A user may check the recent call list to return a missed call.","zh":"使用者可能查看最近通話清單來回覆未接來電。"},{"en":"Recent calls can reveal which callers may be expected or important.","zh":"最近通話可以顯示哪些來電者可能是預期中或重要的人。"},{"en":"This phrase refers to phone history over a short recent period.","zh":"這個短語指短期近期電話紀錄。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":12},{"front":"triangulate resources","meaning":"交叉比對多項資料來源","examples":[{"en":"The system triangulates several resources to identify the caller.","zh":"系統交叉比對多項資料來源來識別來電者。"},{"en":"To triangulate resources means to compare several sources of information to reach a better conclusion.","zh":"交叉比對多項資料來源，是指比較幾個資訊來源以得出更好的結論。"},{"en":"A researcher may triangulate interviews, surveys, and records to understand a problem.","zh":"研究人員可能交叉比對訪談、問卷和紀錄來理解問題。"},{"en":"Using several resources reduces the chance of making a wrong identification.","zh":"使用多項資料來源可以減少錯誤識別的機會。"},{"en":"This phrase describes cross-checking information from different places.","zh":"這個短語描述從不同地方交叉檢查資訊。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":12},{"front":"at the same time","meaning":"同時","examples":[{"en":"Bestcom checks several resources at the same time.","zh":"Bestcom 同時檢查幾項資料來源。"},{"en":"At the same time means simultaneously or during the same moment.","zh":"同時是指在同一刻或同一時間內。"},{"en":"A student cannot listen carefully and reply to messages at the same time without losing focus.","zh":"學生不能同時仔細聆聽和回覆訊息，而不失去專注。"},{"en":"Doing several checks at the same time can make a system faster.","zh":"同時進行幾項檢查可以令系統更快。"},{"en":"This phrase describes actions happening together.","zh":"這個短語描述一起發生的動作。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":13},{"front":"figure out","meaning":"弄清楚","examples":[{"en":"The system attempts to figure out the caller’s relationship with the user.","zh":"系統嘗試弄清楚來電者與使用者的關係。"},{"en":"To figure out something means to understand it by thinking, checking, or using clues.","zh":"弄清楚某事，是指透過思考、檢查或使用線索來理解它。"},{"en":"A student may figure out a new word by reading the words around it.","zh":"學生可能透過閱讀周圍字詞來弄清楚新詞意思。"},{"en":"Systems figure things out by combining data from different sources.","zh":"系統透過結合不同來源的數據來弄清楚事情。"},{"en":"This phrase describes working something out, not simply being told the answer.","zh":"這個短語描述推算出某事，而不是單純被告知答案。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":13},{"front":"relationship","meaning":"關係","examples":[{"en":"The system tries to identify the relationship between the caller and the user.","zh":"系統嘗試識別來電者與使用者之間的關係。"},{"en":"A relationship is the connection between people, such as family, friend, colleague, or supervisor.","zh":"關係是人與人之間的連繫，例如家人、朋友、同事或主管。"},{"en":"A call from a doctor has a different relationship to the user than a call from a stranger.","zh":"醫生來電與陌生人來電對使用者有不同關係。"},{"en":"Knowing the relationship helps the system decide whether a call is likely to be important.","zh":"知道關係有助系統決定來電是否可能重要。"},{"en":"This word describes how people are connected.","zh":"這個詞描述人們如何連接。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":13},{"front":"get through","meaning":"接通；成功打入","examples":[{"en":"Only certain calls get through to Horvitz.","zh":"只有某些來電能成功接通 Horvitz。"},{"en":"To get through means to successfully reach someone by phone or message.","zh":"接通或成功打入，是指透過電話或訊息成功聯絡到某人。"},{"en":"During a busy office hour, only urgent calls may get through to the manager.","zh":"在繁忙辦公時間，可能只有緊急來電能接通經理。"},{"en":"Screening calls controls which people can interrupt the user directly.","zh":"篩選來電控制哪些人可以直接打擾使用者。"},{"en":"This phrase describes successful access after a filter or barrier.","zh":"這個短語描述經過篩選或障礙後成功接觸。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":13},{"front":"supervisors","meaning":"主管","examples":[{"en":"Calls from family and supervisors can get through.","zh":"來自家人和主管的電話可以接通。"},{"en":"Supervisors are people who manage, guide, or oversee other workers.","zh":"主管是管理、指導或監督其他員工的人。"},{"en":"A supervisor may call an employee about an urgent project decision.","zh":"主管可能致電員工討論緊急項目決定。"},{"en":"Calls from supervisors may be treated as important because they relate to work responsibilities.","zh":"主管來電可能被視為重要，因為它們與工作責任有關。"},{"en":"This word refers to people above someone in a workplace structure.","zh":"這個詞指工作架構中職級高於某人的人。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":13},{"front":"earlier that day","meaning":"當天較早時候","examples":[{"en":"The system allows calls from people he called earlier that day.","zh":"系統允許來自他當天較早時候致電過的人的來電。"},{"en":"Earlier that day means at a previous time on the same day.","zh":"當天較早時候，是指同一天內較早的時間。"},{"en":"If you emailed a client earlier that day, you may expect them to call back later.","zh":"如果你當天較早時候電郵客戶，你可能預期他稍後回電。"},{"en":"Recent contact can signal that a new call is relevant or expected.","zh":"近期聯絡可以顯示新來電是相關或預期中的。"},{"en":"This phrase gives a time reference within the same day.","zh":"這個短語給出同一天內的時間參照。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":13},{"front":"get a message on their screens","meaning":"在螢幕上收到訊息","examples":[{"en":"Other callers get a message on their screens.","zh":"其他來電者會在螢幕上收到訊息。"},{"en":"To get a message on their screens means a written notice appears on their computer or phone display.","zh":"在螢幕上收到訊息，是指書面通知出現在電腦或電話顯示屏上。"},{"en":"A visitor may get a message on their screen saying the online service is closed.","zh":"訪客可能在螢幕上收到訊息，顯示網上服務已關閉。"},{"en":"Screen messages can explain why a call is not being answered.","zh":"螢幕訊息可以解釋為何來電未被接聽。"},{"en":"This phrase describes receiving information visually through a device.","zh":"這個短語描述透過裝置視覺地接收資訊。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":13},{"front":"cannot answer now","meaning":"現在不能接聽","examples":[{"en":"The message says that Horvitz cannot answer now.","zh":"訊息說 Horvitz 現在不能接聽。"},{"en":"Cannot answer now means the person is not able to respond at the present moment.","zh":"現在不能接聽，是指該人目前不能回應。"},{"en":"A teacher may cannot answer now if they are in the middle of a lesson.","zh":"老師如果正在上課，可能現在不能接聽。"},{"en":"Stating this clearly helps callers understand the delay without feeling ignored.","zh":"清楚說明這一點有助來電者理解延遲，而不覺得被忽視。"},{"en":"This phrase explains temporary unavailability.","zh":"這個短語解釋暫時沒空。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":13},{"front":"be in a meeting","meaning":"正在開會","examples":[{"en":"The system may say that the user is in a meeting.","zh":"系統可能說使用者正在開會。"},{"en":"To be in a meeting means to be attending a scheduled discussion or work session.","zh":"正在開會，是指正在參加已安排的討論或工作會議。"},{"en":"A manager in a meeting may not want calls unless they are urgent.","zh":"正在開會的經理可能不想接電話，除非來電緊急。"},{"en":"If someone is in a meeting, interrupting them can disturb several people, not just one.","zh":"如果某人正在開會，打擾他可能會打擾幾個人，而不只是一個人。"},{"en":"This phrase describes a common reason for being unavailable.","zh":"這個短語描述沒空的常見原因。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":13},{"front":"not be available until","meaning":"直到……才有空","examples":[{"en":"The message says he will not be available until 3 p.m.","zh":"訊息說他直到下午三時才有空。"},{"en":"Not be available until a time means unable to respond before that time.","zh":"直到某時間才有空，是指在該時間之前不能回應。"},{"en":"A doctor may not be available until noon because of morning appointments.","zh":"醫生可能因上午有預約，直到中午才有空。"},{"en":"Giving a clear time helps others know when to try again.","zh":"給出清楚時間有助其他人知道何時再嘗試。"},{"en":"This phrase describes temporary unavailability with an endpoint.","zh":"這個短語描述有終點的暫時沒空。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":13},{"front":"scan both calendars","meaning":"掃描雙方日程表","examples":[{"en":"The system scans both Horvitz’s calendar and the caller’s calendar.","zh":"系統掃描 Horvitz 和來電者雙方的日程表。"},{"en":"To scan both calendars means to check two schedules for available times.","zh":"掃描雙方日程表，是指檢查兩個時間表以找出可用時間。"},{"en":"A meeting app may scan both calendars to find when a teacher and parent are free.","zh":"會議應用程式可能掃描老師和家長雙方日程表，以找出兩人都有空的時間。"},{"en":"Checking both calendars avoids suggesting a time that only one person can attend.","zh":"檢查雙方日程可以避免建議只有一方能出席的時間。"},{"en":"This phrase describes automatic schedule comparison.","zh":"這個短語描述自動比較日程。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":13},{"front":"reschedule a callback","meaning":"重新安排回電時間","examples":[{"en":"The system checks whether it can reschedule a callback.","zh":"系統檢查能否重新安排回電時間。"},{"en":"To reschedule a callback means to arrange a new time for someone to call back.","zh":"重新安排回電時間，是指為某人回電安排新時間。"},{"en":"If a manager is busy, an assistant may reschedule a callback for later that afternoon.","zh":"如果經理很忙，助理可能把回電時間重新安排到當天下午較後時間。"},{"en":"Rescheduling reduces interruption because the call happens at a better time.","zh":"重新安排可以減少打擾，因為電話會在較好時間發生。"},{"en":"This phrase describes changing a return call to a more suitable time.","zh":"這個短語描述把回電改到更合適時間。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":14},{"front":"a time that works for both of them","meaning":"雙方都合適的時間","examples":[{"en":"The system looks for a time that works for both of them.","zh":"系統尋找一個雙方都合適的時間。"},{"en":"A time that works for both of them is a time when both people are free or able to talk.","zh":"雙方都合適的時間，是兩個人都有空或能談話的時間。"},{"en":"Two teachers may choose a time that works for both of them before planning a joint lesson.","zh":"兩位老師可能先選擇雙方都合適的時間，再規劃共同課堂。"},{"en":"Finding a shared time prevents missed calls and repeated messages.","zh":"找到共同時間可以避免未接來電和反覆訊息。"},{"en":"This phrase describes mutually suitable timing.","zh":"這個短語描述互相合適的時間安排。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":14},{"front":"take that option","meaning":"選擇該選項","examples":[{"en":"Some callers take that option.","zh":"有些來電者選擇該選項。"},{"en":"To take that option means to choose that choice from the available possibilities.","zh":"選擇該選項，是指從可用可能性中選取那個選擇。"},{"en":"If the restaurant is full, customers may take the option of booking another night.","zh":"如果餐廳滿座，顧客可能選擇改訂另一晚。"},{"en":"Offering options gives people control instead of leaving them frustrated.","zh":"提供選項讓人有控制感，而不是只感到挫敗。"},{"en":"This phrase describes accepting one offered choice.","zh":"這個短語描述接受其中一個提供的選擇。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":14},{"front":"leave a voicemail","meaning":"留下語音留言","examples":[{"en":"Other callers simply leave a voicemail.","zh":"其他來電者則只是留下語音留言。"},{"en":"To leave a voicemail means to record a spoken message when someone cannot answer the phone.","zh":"留下語音留言，是指在某人不能接聽電話時錄下口頭訊息。"},{"en":"A parent may leave a voicemail for a teacher after school hours.","zh":"家長可能在放學後給老師留下語音留言。"},{"en":"Voicemail lets the receiver listen later without being interrupted immediately.","zh":"語音留言讓接收者稍後收聽，而不會立即被打斷。"},{"en":"This phrase describes an alternative to speaking live on the phone.","zh":"這個短語描述即時通話以外的另一選擇。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":14},{"front":"the same happens with","meaning":"……也是同樣情況","examples":[{"en":"The same happens with e-mails.","zh":"電郵也是同樣情況。"},{"en":"The same happens with something means the same process or result also applies to it.","zh":"某事也是同樣情況，是指相同過程或結果也適用於它。"},{"en":"Students often forget passwords for school accounts; the same happens with parents’ login details.","zh":"學生常忘記學校帳戶密碼；家長登入資料也是同樣情況。"},{"en":"This phrase extends a point from one case to another.","zh":"這個短語把一個情況的重點延伸到另一個情況。"},{"en":"It helps show that a system treats two situations similarly.","zh":"它幫助顯示系統如何以相似方式處理兩種情況。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":14},{"front":"automatically offer to","meaning":"自動提出去……","examples":[{"en":"Bestcom automatically offers to transfer selected callers.","zh":"Bestcom 自動提出轉駁指定來電者。"},{"en":"To automatically offer to do something means to suggest it without needing a person to ask first.","zh":"自動提出做某事，是指不需要人先要求就建議該做法。"},{"en":"A booking app may automatically offer to change your ticket if a train is cancelled.","zh":"如果火車取消，訂票應用程式可能自動提出更改車票。"},{"en":"Automatic offers can save time when the system understands the situation correctly.","zh":"當系統正確理解情況，自動建議可以節省時間。"},{"en":"This phrase describes a helpful action triggered by software.","zh":"這個短語描述由軟件觸發的幫助行動。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":14},{"front":"transfer selected callers to","meaning":"將指定來電者轉駁至……","examples":[{"en":"Bestcom can transfer selected callers to his cellphone.","zh":"Bestcom 可以將指定來電者轉駁至他的手提電話。"},{"en":"To transfer selected callers to a phone means to redirect certain callers to that phone.","zh":"將指定來電者轉駁至某電話，是指把某些來電者重新導向該電話。"},{"en":"A receptionist may transfer selected callers to a manager’s mobile during an urgent project.","zh":"在緊急項目期間，接待員可能把指定來電者轉駁到經理手機。"},{"en":"Selecting callers prevents every call from reaching the user directly.","zh":"選擇來電者可以防止每個電話都直接打到使用者。"},{"en":"This phrase describes controlled call forwarding.","zh":"這個短語描述受控的來電轉駁。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":14},{"front":"cellphone","meaning":"手提電話","examples":[{"en":"Bestcom may transfer selected callers to the user’s cellphone.","zh":"Bestcom 可能將指定來電者轉駁至使用者的手提電話。"},{"en":"A cellphone is a mobile phone that can be carried and used away from a fixed line.","zh":"手提電話是可以攜帶並離開固定電話線使用的流動電話。"},{"en":"Many workers use a cellphone to answer urgent calls outside the office.","zh":"許多員工在辦公室外用手提電話接聽緊急來電。"},{"en":"Transferring calls to a cellphone can keep important people connected even when the user is away.","zh":"將電話轉駁到手提電話，可以令重要人士即使在使用者離開辦公室時仍能聯絡上。"},{"en":"This word is mainly used in American English for mobile phone.","zh":"這個詞在美式英語中主要指 mobile phone。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":14},{"front":"unless","meaning":"除非","examples":[{"en":"The system transfers calls unless the calendar shows a meeting.","zh":"系統會轉駁電話，除非日程表顯示有會議。"},{"en":"Unless means except if; it introduces the condition that stops something happening.","zh":"除非是指 except if，用來引入阻止某事發生的條件。"},{"en":"Students may use phones after class unless an exam is taking place.","zh":"學生課後可以使用電話，除非正在考試。"},{"en":"In this system, a meeting stops the normal call-transfer rule.","zh":"在這個系統中，會議會阻止一般來電轉駁規則。"},{"en":"This word is important because it creates an exception.","zh":"這個詞很重要，因為它創造例外情況。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":14},{"front":"imply that","meaning":"暗示；顯示","examples":[{"en":"The calendar may imply that Horvitz is in a meeting.","zh":"日程表可能暗示 Horvitz 正在開會。"},{"en":"To imply that means to suggest something without saying it directly.","zh":"暗示某事，是指不直接說出但表示出來。"},{"en":"If a teacher closes the classroom door and turns off the lights, it may imply that class is over.","zh":"如果老師關上課室門並熄燈，可能暗示課堂已結束。"},{"en":"Calendar entries can imply availability even without a direct message from the user.","zh":"日程項目即使沒有使用者直接訊息，也可以顯示是否有空。"},{"en":"This phrase describes indirect meaning or evidence.","zh":"這個短語描述間接意思或證據。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":14},{"front":"agree with the information","meaning":"與資料一致","examples":[{"en":"Students decide whether the statements agree with the information in the passage.","zh":"學生判斷陳述是否與篇章資料一致。"},{"en":"To agree with the information means to match what the passage says.","zh":"與資料一致，是指符合篇章所說內容。"},{"en":"If the passage says the system checks calendars, that statement agrees with the information.","zh":"如果篇章說系統會檢查日程表，該陳述就與資料一致。"},{"en":"Students should choose TRUE only when the text clearly supports the statement.","zh":"只有當文本清楚支持陳述時，學生才應選 TRUE。"},{"en":"This phrase is common in reading-comprehension tasks.","zh":"這個短語常見於閱讀理解題。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":14},{"front":"in boxes","meaning":"在方格內","examples":[{"en":"Candidates write their answers in boxes on the answer sheet.","zh":"考生在答題紙上的方格內寫答案。"},{"en":"In boxes means inside the marked spaces provided for answers.","zh":"在方格內，是指在提供給答案的標記空格中。"},{"en":"Students should write one letter in each box on a multiple-choice answer sheet.","zh":"學生應在選擇題答題紙每個方格內寫一個字母。"},{"en":"Writing outside the boxes may make answers unclear or difficult to mark.","zh":"寫在方格外可能令答案不清楚或難以評分。"},{"en":"This phrase describes where exam answers should be written.","zh":"這個短語描述考試答案應寫在哪裡。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":15},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"Write FALSE if the statement contradicts the information.","zh":"如果陳述與資料相矛盾，就寫 FALSE。"},{"en":"To contradict the information means to say the opposite of what the passage says.","zh":"與資料相矛盾，是指說出與篇章相反的內容。"},{"en":"If the text says a system delays calls, saying it accepts every call contradicts the information.","zh":"如果文本說系統會延遲來電，說它接收所有來電就與資料相矛盾。"},{"en":"A statement is FALSE only when the passage clearly disagrees with it.","zh":"只有當篇章清楚不同意陳述時，陳述才是 FALSE。"},{"en":"This phrase describes conflict between a statement and the text.","zh":"這個短語描述陳述與文本之間的衝突。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":15},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"Write NOT GIVEN if there is no information on this.","zh":"如果沒有相關資料，就寫 NOT GIVEN。"},{"en":"No information on this means the passage does not say enough to decide whether it is true or false.","zh":"沒有相關資料，是指篇章沒有提供足夠內容判斷真假。"},{"en":"If a passage names a software system but never states its price, there is no information on the cost.","zh":"如果篇章提到一個軟件系統，但從未說明價格，就沒有關於成本的資料。"},{"en":"Students should not guess from outside knowledge when the text gives no evidence.","zh":"當文本沒有證據時，學生不應用外部知識猜測。"},{"en":"This phrase explains when NOT GIVEN is the correct answer.","zh":"這個短語解釋何時應選 NOT GIVEN。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":15},{"front":"according to","meaning":"根據……","examples":[{"en":"According to Ted Selker, people are used to interruptions.","zh":"根據 Ted Selker 的說法，人們已習慣被打擾。"},{"en":"According to means based on what a person, source, or text says.","zh":"根據，是指基於某人、來源或文本所說。"},{"en":"According to the school notice, the trip will start at 8 a.m.","zh":"根據學校通告，旅行將於早上八時開始。"},{"en":"This phrase helps show where a claim comes from.","zh":"這個短語幫助顯示主張來自哪裡。"},{"en":"It is useful when reporting someone else’s view.","zh":"它適合用來報告他人的看法。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":15},{"front":"human reproduction","meaning":"人類繁殖","examples":[{"en":"The question refers to human reproduction.","zh":"題目提到人類繁殖。"},{"en":"Human reproduction is the biological process by which humans have children.","zh":"人類繁殖是人類生育子女的生物過程。"},{"en":"Students may study human reproduction in biology lessons.","zh":"學生可能在生物課中學習人類繁殖。"},{"en":"In the passage, the comparison is used to show that interruptions are extremely familiar to people.","zh":"在篇章中，這個比較用來顯示人們對打擾極為熟悉。"},{"en":"This phrase is formal and biological, not casual.","zh":"這個短語較正式並屬生物學用語，不是日常閒談用語。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":15},{"front":"throughout history","meaning":"縱觀歷史","examples":[{"en":"The statement discusses whether something has happened throughout history.","zh":"該陳述討論某事是否縱觀歷史一直發生。"},{"en":"Throughout history means during many periods of the past, not just one moment.","zh":"縱觀歷史，是指在過去許多時期，而不只是某一刻。"},{"en":"Throughout history, people have created tools to make daily work easier.","zh":"縱觀歷史，人們一直創造工具來令日常工作更容易。"},{"en":"A claim about all of history needs strong evidence from many times and places.","zh":"關於整個歷史的主張需要來自多個時期和地方的強力證據。"},{"en":"This phrase gives a very broad historical scope.","zh":"這個短語給出非常廣泛的歷史範圍。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":15},{"front":"be disturbed","meaning":"受到干擾","examples":[{"en":"The statement asks whether human reproduction has been disturbed.","zh":"該陳述問人類繁殖是否受到干擾。"},{"en":"To be disturbed means to be interrupted, disrupted, or made less normal.","zh":"受到干擾，是指被打斷、破壞或變得不正常。"},{"en":"A class may be disturbed by loud building work outside the window.","zh":"課堂可能被窗外嘈雜建築工程干擾。"},{"en":"If an important process is disturbed, it may not continue smoothly.","zh":"如果重要過程受到干擾，它可能無法順利繼續。"},{"en":"This phrase describes interference with normal activity.","zh":"這個短語描述對正常活動的干預。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":15},{"front":"put up with it","meaning":"忍受它","examples":[{"en":"If people are interrupted by calls or e-mails, they usually put up with it.","zh":"如果人們被電話或電郵打斷，他們通常會忍受它。"},{"en":"To put up with something means to tolerate it even though it is annoying or unpleasant.","zh":"忍受某事，是指雖然它令人煩惱或不愉快，仍然容忍。"},{"en":"A student may put up with a noisy library because there is nowhere else to study.","zh":"學生可能因沒有其他地方溫習而忍受嘈雜圖書館。"},{"en":"People put up with interruptions when they feel they have no practical alternative.","zh":"當人們覺得沒有實際替代方法，就會忍受打擾。"},{"en":"This phrase suggests reluctant acceptance.","zh":"這個短語暗示不情願地接受。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":15},{"front":"investigate software","meaning":"研究軟件","examples":[{"en":"Microsoft is investigating software for ordinary offices.","zh":"Microsoft 正在研究適合普通辦公室的軟件。"},{"en":"To investigate software means to study, test, or examine software to understand or improve it.","zh":"研究軟件，是指學習、測試或檢查軟件，以理解或改善它。"},{"en":"A school may investigate software before using it for online lessons.","zh":"學校可能在用軟件上網課前先研究該軟件。"},{"en":"Investigation helps identify whether software is useful, safe, and reliable.","zh":"研究有助確認軟件是否有用、安全和可靠。"},{"en":"This phrase describes careful examination of a digital tool.","zh":"這個短語描述對數碼工具的仔細檢查。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":15},{"front":"suitable for","meaning":"適合……","examples":[{"en":"The software may be suitable for ordinary offices.","zh":"該軟件可能適合普通辦公室。"},{"en":"Suitable for means appropriate or useful for a particular person, place, or purpose.","zh":"適合某事，是指對特定人、地方或目的而言恰當或有用。"},{"en":"A quiet room is suitable for students who need to revise carefully.","zh":"安靜房間適合需要仔細溫習的學生。"},{"en":"Software is suitable for offices if it fits real work habits and does not cause confusion.","zh":"如果軟件符合真實工作習慣並不造成混亂，它就適合辦公室。"},{"en":"This phrase describes good fit.","zh":"這個短語描述配合程度好。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":15},{"front":"ordinary offices","meaning":"普通辦公室","examples":[{"en":"The statement refers to software for ordinary offices.","zh":"該陳述提到普通辦公室使用的軟件。"},{"en":"Ordinary offices are normal workplaces used by regular employees, not only senior executives.","zh":"普通辦公室是一般員工使用的正常工作場所，而不只是高級行政人員的地方。"},{"en":"An ordinary office may have desks, computers, meeting rooms, and shared printers.","zh":"普通辦公室可能有桌子、電腦、會議室和共用打印機。"},{"en":"If software works in ordinary offices, it can help many workers, not only top managers.","zh":"如果軟件適用於普通辦公室，它就能幫助許多員工，而不只是高層。"},{"en":"This phrase contrasts everyday workplaces with elite or special settings.","zh":"這個短語把日常工作場所與精英或特殊環境作對比。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":15},{"front":"misjudge how busy they are","meaning":"誤判自己有多忙","examples":[{"en":"People usually misjudge how busy they are.","zh":"人們通常誤判自己有多忙。"},{"en":"To misjudge how busy they are means to estimate their own workload incorrectly.","zh":"誤判自己有多忙，是指錯誤估計自己的工作量。"},{"en":"A worker may misjudge how busy they are by saying yes to extra tasks before checking the calendar.","zh":"員工在查看日程前就答應額外任務，可能誤判自己有多忙。"},{"en":"Misjudging busyness can lead to poor planning and unnecessary stress.","zh":"誤判忙碌程度會導致規劃差和不必要壓力。"},{"en":"This phrase shows that people may not accurately understand their own availability.","zh":"這個短語顯示人們未必準確理解自己是否有空。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":16},{"front":"observe employees","meaning":"觀察員工","examples":[{"en":"Researchers observed employees during the study.","zh":"研究人員在研究期間觀察員工。"},{"en":"To observe employees means to watch and record how workers behave.","zh":"觀察員工，是指觀看並記錄工作者如何行動。"},{"en":"A company may observe employees using a new checkout system to see where they struggle.","zh":"公司可能觀察員工使用新收銀系統，以了解他們在哪裡遇到困難。"},{"en":"Observation can reveal habits that people forget to mention in surveys.","zh":"觀察可以揭示人們在問卷中忘記提及的習慣。"},{"en":"This phrase describes a research method based on watching real behaviour.","zh":"這個短語描述基於觀看真實行為的研究方法。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":16},{"front":"occupational groups","meaning":"職業類別","examples":[{"en":"The question mentions employees in different occupational groups.","zh":"題目提到不同職業類別的員工。"},{"en":"Occupational groups are categories of workers based on job type or role.","zh":"職業類別是根據工作種類或角色劃分的工作者分類。"},{"en":"Teachers, nurses, engineers, and office clerks are different occupational groups.","zh":"老師、護士、工程師和辦公室文員是不同職業類別。"},{"en":"Comparing occupational groups helps researchers see whether problems affect all workers equally.","zh":"比較職業類別有助研究人員了解問題是否同樣影響所有工作者。"},{"en":"This phrase focuses on job categories.","zh":"這個短語聚焦工作分類。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":16},{"front":"current phone and computer systems","meaning":"現時的電話和電腦系統","examples":[{"en":"Current phone and computer systems often assume users are available.","zh":"現時的電話和電腦系統常假設使用者有空。"},{"en":"Current phone and computer systems are the communication technologies people commonly use now.","zh":"現時的電話和電腦系統，是人們現在常用的通訊科技。"},{"en":"A current phone system may ring immediately even if the user is in a meeting.","zh":"現時電話系統即使使用者正在開會，也可能立即響起。"},{"en":"These systems can interrupt because they rarely understand human context.","zh":"這些系統會造成打擾，因為它們很少理解人類語境。"},{"en":"This phrase refers to existing technology, not future considerate systems.","zh":"這個短語指現有科技，而不是未來體貼系統。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":16},{"front":"use shortcuts","meaning":"使用捷徑","examples":[{"en":"The statement asks whether current systems use shortcuts.","zh":"該陳述問現時系統是否使用捷徑。"},{"en":"To use shortcuts means to use quick, simplified methods instead of a fuller process.","zh":"使用捷徑，是指使用快速、簡化的方法，而不是完整過程。"},{"en":"A student may use shortcuts in mental maths by remembering patterns instead of counting every step.","zh":"學生心算時可能透過記住規律而不是每步計算來使用捷徑。"},{"en":"Shortcuts save time, but they can cause errors if the situation is more complex.","zh":"捷徑節省時間，但如果情況更複雜，可能造成錯誤。"},{"en":"This phrase describes a faster but less complete method.","zh":"這個短語描述較快但較不完整的方法。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":16},{"front":"deliver information immediately","meaning":"即時傳遞資料","examples":[{"en":"Current systems often deliver information immediately.","zh":"現時系統常即時傳遞資料。"},{"en":"To deliver information immediately means to send or show information without delay.","zh":"即時傳遞資料，是指不延遲地發送或顯示資訊。"},{"en":"A news app may deliver information immediately when breaking news happens.","zh":"當突發新聞發生，新聞應用程式可能即時傳遞資料。"},{"en":"Immediate delivery is useful for emergencies but distracting for minor updates.","zh":"即時傳遞對緊急情況有用，但對小更新而言會令人分心。"},{"en":"This phrase describes speed of communication.","zh":"這個短語描述溝通速度。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":16},{"front":"complete the flow-chart below","meaning":"完成以下流程圖","examples":[{"en":"Candidates complete the flow-chart below using words from the passage.","zh":"考生用篇章中的字詞完成以下流程圖。"},{"en":"Complete the flow-chart below means fill missing parts in a process diagram.","zh":"完成以下流程圖，是指填補流程圖中缺失部分。"},{"en":"In a reading test, students may complete a flow-chart showing how a machine works.","zh":"在閱讀測驗中，學生可能完成顯示機器如何運作的流程圖。"},{"en":"Flow-chart tasks test whether readers understand sequence and cause-and-effect.","zh":"流程圖題測試讀者是否理解次序和因果。"},{"en":"This phrase is an exam instruction for process-completion questions.","zh":"這個短語是流程填空題的考試指示。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":16},{"front":"ONLY ONE WORD","meaning":"只選一個詞","examples":[{"en":"Candidates choose only one word from the passage.","zh":"考生只從篇章中選一個詞。"},{"en":"ONLY ONE WORD means the answer must contain exactly one word, not two or more.","zh":"只選一個詞，是指答案必須剛好包含一個詞，而不是兩個或更多。"},{"en":"If the answer space allows ONLY ONE WORD, “phone” is acceptable but “mobile phone” is not.","zh":"如果答案要求只選一個詞，“phone” 可以，但 “mobile phone” 不可以。"},{"en":"Ignoring this instruction can make a correct idea lose marks.","zh":"忽視這項指示會令正確意思也失分。"},{"en":"This phrase gives a strict word-limit rule.","zh":"這個短語給出嚴格字數限制規則。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":16},{"front":"stage","meaning":"階段","examples":[{"en":"The flow-chart shows each stage of the Bestcom system.","zh":"流程圖顯示 Bestcom 系統的每個階段。"},{"en":"A stage is one step or part in a process.","zh":"階段是過程中的一個步驟或部分。"},{"en":"In cooking, washing vegetables is one stage before cutting and heating them.","zh":"在烹飪中，清洗蔬菜是切菜和加熱前的一個階段。"},{"en":"Understanding each stage helps people follow how a system works from start to finish.","zh":"理解每個階段有助人們由開始到結束跟上系統如何運作。"},{"en":"This word describes process order.","zh":"這個詞描述過程次序。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":16},{"front":"in the office","meaning":"在辦公室內","examples":[{"en":"The flow-chart compares what happens in the office and out of the office.","zh":"流程圖比較在辦公室內和辦公室外發生的情況。"},{"en":"In the office means physically present at the workplace or working from that location.","zh":"在辦公室內，是指身處工作場所或在該地點工作。"},{"en":"A worker in the office may answer a desk phone instead of a mobile phone.","zh":"在辦公室內的員工可能接聽桌面電話，而不是手提電話。"},{"en":"A system may behave differently depending on whether the user is in the office.","zh":"系統可能會根據使用者是否在辦公室內而有不同運作。"},{"en":"This phrase describes workplace location.","zh":"這個短語描述工作地點。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":16},{"front":"out of the office","meaning":"在辦公室外","examples":[{"en":"The system behaves differently when the user is out of the office.","zh":"使用者在辦公室外時，系統會有不同運作。"},{"en":"Out of the office means not physically present at the workplace.","zh":"在辦公室外，是指不在實體工作場所。"},{"en":"A manager out of the office may ask staff to send urgent issues by phone.","zh":"在辦公室外的經理可能要求員工用電話發送緊急事項。"},{"en":"If someone is out of the office, calls may need to be transferred to a mobile phone.","zh":"如果某人在辦公室外，來電可能需要轉駁到手提電話。"},{"en":"This phrase describes absence from the normal workplace.","zh":"這個短語描述不在正常工作地點。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":16},{"front":"carry out further analysis","meaning":"進行進一步分析","examples":[{"en":"The Bestcom system carries out further analysis.","zh":"Bestcom 系統進行進一步分析。"},{"en":"To carry out further analysis means to examine information more deeply after an initial check.","zh":"進行進一步分析，是指在初步檢查後更深入檢視資訊。"},{"en":"A doctor may carry out further analysis if a blood test result looks unusual.","zh":"如果驗血結果看起來不尋常，醫生可能進行進一步分析。"},{"en":"Further analysis helps avoid quick but wrong decisions.","zh":"進一步分析有助避免快速但錯誤的決定。"},{"en":"This phrase describes a deeper second stage of investigation.","zh":"這個短語描述更深入的第二階段調查。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":17},{"front":"known caller","meaning":"已知來電者","examples":[{"en":"The system treats a known caller differently from an unknown caller.","zh":"系統以不同方式處理已知來電者和未知來電者。"},{"en":"A known caller is a caller whose identity or relationship is recognised by the system.","zh":"已知來電者，是系統能辨認身份或關係的來電者。"},{"en":"A call from your manager may be treated as a known caller if the number is in the directory.","zh":"如果號碼在通訊錄中，來自經理的電話可能被視為已知來電者。"},{"en":"Known callers may receive faster or different handling because the system has more information.","zh":"已知來電者可能得到更快或不同處理，因為系統有更多資訊。"},{"en":"This phrase contrasts recognised callers with strangers.","zh":"這個短語把可識別來電者與陌生人作對比。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":17},{"front":"unknown caller","meaning":"未知來電者","examples":[{"en":"An unknown caller may receive a message on the screen.","zh":"未知來電者可能在螢幕上收到訊息。"},{"en":"An unknown caller is someone whose identity is not recognised by the system.","zh":"未知來電者，是系統不能辨認身份的人。"},{"en":"A phone may show “unknown caller” when the number is hidden or not saved.","zh":"當號碼被隱藏或未被儲存，電話可能顯示「未知來電者」。"},{"en":"Unknown callers may be screened more carefully to prevent unnecessary interruptions.","zh":"未知來電者可能被更仔細篩選，以防止不必要打擾。"},{"en":"This phrase refers to callers without recognised contact information.","zh":"這個短語指沒有可識別聯絡資料的來電者。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":17},{"front":"in the directory","meaning":"在通訊錄內","examples":[{"en":"The system checks whether the caller is in the directory.","zh":"系統檢查來電者是否在通訊錄內。"},{"en":"In the directory means listed in the organisation’s contact database.","zh":"在通訊錄內，是指被列在組織的聯絡人資料庫中。"},{"en":"If a caller is in the directory, the system may know their name and department.","zh":"如果來電者在通訊錄內，系統可能知道其姓名和部門。"},{"en":"Directory information helps identify whether a call is internal or external.","zh":"通訊錄資料有助識別來電是內部還是外部來電。"},{"en":"This phrase refers to being included in a contact list.","zh":"這個短語指被包括在聯絡人列表中。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":17},{"front":"appear on their screen","meaning":"出現在他們的螢幕上","examples":[{"en":"A message appears on the caller’s screen.","zh":"訊息出現在來電者的螢幕上。"},{"en":"To appear on their screen means to become visible on their computer or phone display.","zh":"出現在他們的螢幕上，是指在他們的電腦或電話顯示屏上變得可見。"},{"en":"A warning may appear on a user’s screen when the password is wrong.","zh":"當密碼錯誤時，警告可能出現在使用者螢幕上。"},{"en":"Screen messages give information without needing a live conversation.","zh":"螢幕訊息不用即時對話也能提供資訊。"},{"en":"This phrase describes visual display of information.","zh":"這個短語描述資訊的視覺顯示。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":17},{"front":"unavailable","meaning":"沒空；不可聯絡","examples":[{"en":"The message says that the user is unavailable.","zh":"訊息說使用者沒空。"},{"en":"Unavailable means not free, not reachable, or not able to respond at the moment.","zh":"沒空或不可聯絡，是指目前沒有時間、不能聯絡或不能回應。"},{"en":"A teacher may be unavailable during a lesson but free after school.","zh":"老師上課期間可能沒空，但放學後有空。"},{"en":"Saying someone is unavailable helps others understand why there is no immediate reply.","zh":"說某人沒空有助別人理解為何沒有即時回覆。"},{"en":"This word describes temporary lack of access.","zh":"這個詞描述暫時無法接觸。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":17},{"front":"a suitable time","meaning":"合適時間","examples":[{"en":"The system looks for a suitable time for both parties.","zh":"系統尋找雙方的合適時間。"},{"en":"A suitable time is a time that fits people’s schedules and needs.","zh":"合適時間，是符合人們日程和需要的時間。"},{"en":"A tutor and student may choose a suitable time after checking both calendars.","zh":"導師和學生可能在查看雙方日程後選擇合適時間。"},{"en":"Finding a suitable time prevents repeated missed calls and messages.","zh":"找到合適時間可以避免反覆未接來電和訊息。"},{"en":"This phrase describes timing that works well for the situation.","zh":"這個短語描述適合情況的時間安排。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":17},{"front":"both parties","meaning":"雙方","examples":[{"en":"The system tries to find a time that works for both parties.","zh":"系統嘗試找出雙方都合適的時間。"},{"en":"Both parties means the two people or sides involved.","zh":"雙方是指涉及的兩個人或兩邊。"},{"en":"A meeting time must suit both parties if a teacher and parent need to talk.","zh":"如果老師和家長需要談話，會議時間必須適合雙方。"},{"en":"Considering both parties prevents one side from being forced into an unsuitable time.","zh":"考慮雙方可以防止其中一方被迫接受不合適時間。"},{"en":"This phrase is often used in scheduling, negotiation, or agreement.","zh":"這個短語常用於安排時間、談判或協議。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":17},{"front":"call transfer","meaning":"來電轉駁","examples":[{"en":"Call transfer is offered when the user is out of the office.","zh":"使用者在辦公室外時，系統會提供來電轉駁。"},{"en":"Call transfer is the process of redirecting a phone call from one line or device to another.","zh":"來電轉駁是把電話從一條線路或一部裝置重新導向另一處的過程。"},{"en":"An office phone may use call transfer to send urgent calls to a manager’s mobile.","zh":"辦公室電話可能使用來電轉駁，把緊急電話轉到經理手機。"},{"en":"Call transfer helps important callers reach someone even when they are away from their desk.","zh":"來電轉駁幫助重要來電者即使對方離開座位也能聯絡上。"},{"en":"This phrase describes a phone-routing function.","zh":"這個短語描述電話路由功能。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":17},{"front":"no meeting in the schedule","meaning":"日程中沒有會議","examples":[{"en":"Bestcom transfers calls if there is no meeting in the user’s schedule.","zh":"如果使用者日程中沒有會議，Bestcom 會轉駁來電。"},{"en":"No meeting in the schedule means the calendar shows no planned meeting at that time.","zh":"日程中沒有會議，是指日曆顯示該時間沒有已安排會議。"},{"en":"If there is no meeting in a teacher’s schedule after school, a parent call may be accepted.","zh":"如果老師放學後日程中沒有會議，家長來電可能會被接聽。"},{"en":"Checking for meetings helps the system avoid interrupting important discussions.","zh":"檢查是否有會議有助系統避免打斷重要討論。"},{"en":"This phrase describes a calendar condition that allows contact.","zh":"這個短語描述允許聯絡的一項日程條件。"}],"source":"53 - Bestcom—Considerate Computing.pdf","sourcePage":17}],"ielts/reading/passage-2/Practice 54":[{"front":"the study of chimpanzee culture","meaning":"黑猩猩文化研究","examples":[{"en":"The study of chimpanzee culture has changed how researchers think about human uniqueness.","zh":"黑猩猩文化研究改變了研究人員對人類獨特性的看法。"},{"en":"The study of chimpanzee culture means research into learned behaviours shared within chimpanzee groups.","zh":"study of chimpanzee culture 指研究黑猩猩群體中共同學習得來的行為。"},{"en":"A biology student may study chimpanzee culture by comparing how different groups use tools.","zh":"生物學生可能透過比較不同黑猩猩群體如何使用工具來研究黑猩猩文化。"},{"en":"This research matters because it shows that culture is not limited only to humans.","zh":"這項研究很重要，因為它顯示文化並不只限於人類。"},{"en":"The phrase is useful when discussing animal learning, traditions, and behaviour passed between generations.","zh":"討論動物學習、傳統和代代相傳的行為時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":1},{"front":"similarities between","meaning":"……之間的相似之處","examples":[{"en":"Researchers have studied the similarities between chimpanzees and humans for years.","zh":"研究人員多年來研究黑猩猩與人類之間的相似之處。"},{"en":"Similarities between two things are features that they share.","zh":"similarities between two things 指兩者共有的特徵。"},{"en":"Teachers may ask students to find similarities between two poems before comparing their differences.","zh":"老師可能要求學生先找出兩首詩之間的相似之處，再比較差異。"},{"en":"Seeing similarities can make two groups seem more closely connected than people first thought.","zh":"看見相似之處可以令人覺得兩個群體比最初想像更接近。"},{"en":"This phrase is useful when comparing animals, people, systems, or ideas.","zh":"比較動物、人、制度或想法時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":1},{"front":"researchers have recognised","meaning":"研究人員已認識到","examples":[{"en":"Researchers have recognised that these resemblances run much deeper than first thought.","zh":"研究人員已認識到這些相似之處遠比最初所想更深。"},{"en":"Researchers have recognised means researchers have come to understand or accept something.","zh":"researchers have recognised 指研究人員已開始理解或接受某事。"},{"en":"Teachers have recognised that students learn better when examples are connected to daily life.","zh":"老師已認識到，當例子與日常生活相關時，學生學得更好。"},{"en":"New evidence can make experts recognise that an earlier view was too simple.","zh":"新證據可以令專家認識到早期看法過於簡單。"},{"en":"This phrase is useful when knowledge changes because of research or experience.","zh":"當知識因研究或經驗而改變時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":1},{"front":"over the past decade","meaning":"在過去十年間","examples":[{"en":"Over the past decade, researchers have made important discoveries about chimpanzees.","zh":"在過去十年間，研究人員對黑猩猩有了重要發現。"},{"en":"Over the past decade means during the last ten years.","zh":"over the past decade 指在過去十年期間。"},{"en":"Over the past decade, many schools have added more technology to classrooms.","zh":"在過去十年間，許多學校在課室加入更多科技。"},{"en":"This phrase helps describe recent long-term change rather than a single event.","zh":"這個短語幫助描述近期長期變化，而不是單一事件。"},{"en":"It is often used with research, trends, increases, and discoveries.","zh":"它常與研究、趨勢、增加和發現一起使用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":1},{"front":"resemblances run much deeper than","meaning":"相似之處遠比……深","examples":[{"en":"The resemblances between chimpanzees and humans run much deeper than anyone first thought.","zh":"黑猩猩與人類之間的相似之處遠比任何人最初所想更深。"},{"en":"If resemblances run much deeper than expected, the similarities are more serious or important than people realised.","zh":"resemblances run much deeper than expected 指相似之處比人們意識到的更深層或更重要。"},{"en":"Two classmates may seem different at first, but their family experiences may run much deeper than expected.","zh":"兩名同學起初可能看似不同，但他們的家庭經歷可能遠比預期更相似。"},{"en":"Deeper similarities can change how people judge relationships between groups.","zh":"更深層的相似之處可以改變人們對群體關係的判斷。"},{"en":"This phrase is useful when surface similarity becomes a deeper connection.","zh":"當表面相似變成深層連繫時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":1},{"front":"first thought","meaning":"最初所想","examples":[{"en":"The behaviour is more complex than researchers first thought.","zh":"這種行為比研究人員最初所想更複雜。"},{"en":"First thought means originally believed or assumed at the beginning.","zh":"first thought 指一開始原本相信或假設的。"},{"en":"A task may be harder than a student first thought after she reads the instructions carefully.","zh":"學生仔細閱讀指示後，可能發現任務比最初所想更難。"},{"en":"New information can show that an early assumption was incomplete.","zh":"新資訊可以顯示早期假設並不完整。"},{"en":"This phrase is useful when later understanding corrects an initial impression.","zh":"當後來理解修正最初印象時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":1},{"front":"for instance","meaning":"例如","examples":[{"en":"For instance, nut-cracking is found only in one particular part of Africa.","zh":"例如，敲開堅果只在非洲某個特定地區被發現。"},{"en":"For instance means for example.","zh":"for instance 指例如。"},{"en":"Some school rules protect safety; for instance, students must not run on wet stairs.","zh":"有些校規保護安全；例如，學生不可在濕滑樓梯奔跑。"},{"en":"Writers use this phrase to make a general idea clearer through a specific case.","zh":"作者使用這個短語，透過具體個案令一般想法更清楚。"},{"en":"This phrase is useful when introducing evidence or examples.","zh":"引入證據或例子時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":1},{"front":"nut-cracking","meaning":"敲開堅果","examples":[{"en":"Nut-cracking in the Taï Forest is considered a form of chimpanzee culture.","zh":"塔伊森林中的敲開堅果被認為是一種黑猩猩文化。"},{"en":"Nut-cracking means breaking open nuts, often with a stone or other tool.","zh":"nut-cracking 指敲破堅果，常用石頭或其他工具。"},{"en":"A child may crack nuts at home using a nutcracker during a family gathering.","zh":"孩子在家庭聚會中可能用堅果鉗敲開堅果。"},{"en":"In chimpanzees, nut-cracking matters because it can be learned and shared within a group.","zh":"在黑猩猩身上，敲開堅果很重要，因為它可以在群體中被學習和共享。"},{"en":"This word describes both a physical action and, in this passage, a cultural behaviour.","zh":"這個詞描述一個實際動作，而在本文中也指文化行為。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":1},{"front":"observed in","meaning":"在……被觀察到","examples":[{"en":"The nut-cracking observed in the Taï Forest is not a simple behaviour.","zh":"在塔伊森林被觀察到的敲開堅果並不是簡單行為。"},{"en":"Observed in means seen, recorded, or studied in a particular place or group.","zh":"observed in 指在某地或某群體中被看見、記錄或研究。"},{"en":"A teacher may note a pattern observed in several students’ essays.","zh":"老師可能記下一個在幾名學生文章中被觀察到的模式。"},{"en":"When behaviour is observed in one place but not another, researchers may ask why.","zh":"當某行為在一處被觀察到而另一處沒有，研究者可能會問原因。"},{"en":"This phrase is common in science and research writing.","zh":"這個短語常見於科學和研究寫作。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":1},{"front":"the Taï Forest","meaning":"塔伊森林","examples":[{"en":"The Taï Forest is one place where researchers have observed nut-cracking.","zh":"塔伊森林是研究人員觀察到敲開堅果的地方之一。"},{"en":"The Taï Forest is a specific forest site mentioned as a location for chimpanzee behaviour research.","zh":"Taï Forest 指文中提及的一個特定森林地點，用於黑猩猩行為研究。"},{"en":"A field researcher may return to the same forest every year to observe animal habits.","zh":"野外研究人員可能每年回到同一片森林觀察動物習性。"},{"en":"Naming the forest helps readers know exactly where the behaviour was recorded.","zh":"說出森林名稱幫助讀者知道該行為在哪裏被記錄。"},{"en":"This phrase gives a specific geographical context for the study.","zh":"這個短語為研究提供具體地理背景。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":1},{"front":"simple chimpanzee behaviour","meaning":"簡單的黑猩猩行為","examples":[{"en":"Nut-cracking is not merely a simple chimpanzee behaviour.","zh":"敲開堅果不只是簡單的黑猩猩行為。"},{"en":"Simple chimpanzee behaviour means a basic action that does not seem to involve complex learning or culture.","zh":"simple chimpanzee behaviour 指看似不涉及複雜學習或文化的基本行動。"},{"en":"Eating fruit from a branch may look like a simple animal behaviour.","zh":"從樹枝上吃水果可能看起來像簡單動物行為。"},{"en":"If a behaviour requires tools, practice, and copying others, it may not be simple.","zh":"如果一種行為需要工具、練習和模仿他者，它可能並不簡單。"},{"en":"This phrase is useful when contrasting basic action with culturally learned behaviour.","zh":"對比基本行動與文化學習行為時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":1},{"front":"a separate adaptation","meaning":"一種獨立的適應特徵","examples":[{"en":"Nut-cracking is a separate adaptation found in one part of Africa.","zh":"敲開堅果是在非洲某地發現的一種獨立適應特徵。"},{"en":"A separate adaptation is a distinct behaviour or feature that helps survival in a particular environment.","zh":"separate adaptation 指有助於在特定環境中生存的獨特行為或特徵。"},{"en":"A bird’s thick beak may be a separate adaptation for eating hard seeds.","zh":"鳥的厚喙可能是一種用來吃硬種子的獨立適應特徵。"},{"en":"An adaptation can develop in one group because local conditions make it useful.","zh":"適應特徵可以在某一群體中發展，因為當地條件令它有用。"},{"en":"This phrase is useful when describing a special trait found in one population.","zh":"描述某一族群中發現的特殊特徵時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":2},{"front":"found only in","meaning":"只在……找到","examples":[{"en":"This adaptation is found only in that particular part of Africa.","zh":"這種適應特徵只在非洲那個特定地區找到。"},{"en":"Found only in means existing or being observed in one limited place or group.","zh":"found only in 指只存在或只在某個有限地方或群體中被觀察到。"},{"en":"A rare plant may be found only in one mountain valley.","zh":"罕見植物可能只在一個山谷中找到。"},{"en":"If a behaviour is found only in one community, researchers may suspect local learning.","zh":"如果某行為只在一個社群中找到，研究人員可能懷疑是地方學習。"},{"en":"This phrase highlights limited distribution.","zh":"這個短語強調分布範圍有限。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":2},{"front":"a particular part of","meaning":"……的某個特定地區","examples":[{"en":"The behaviour is found only in a particular part of Africa.","zh":"這種行為只在非洲某個特定地區找到。"},{"en":"A particular part of something means one specific area within a larger place or group.","zh":"particular part of something 指較大地方或群體中的某一具體區域。"},{"en":"A bus stop may be located in a particular part of the campus.","zh":"巴士站可能位於校園某個特定位置。"},{"en":"Being specific helps readers avoid thinking the behaviour is found everywhere.","zh":"說得具體可以避免讀者以為該行為到處都有。"},{"en":"This phrase is useful when narrowing a general location to a precise area.","zh":"把一般地點收窄到精確區域時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":2},{"front":"as well as","meaning":"以及；亦是","examples":[{"en":"The behaviour is an adaptation as well as a cultural trait.","zh":"這種行為是一種適應特徵，亦是一種文化特徵。"},{"en":"As well as means in addition to.","zh":"as well as 指以及；除了某物之外還有。"},{"en":"A good teacher needs patience as well as subject knowledge.","zh":"好老師需要耐性，也需要學科知識。"},{"en":"This phrase adds another important quality without replacing the first one.","zh":"這個短語加入另一個重要特質，而不是取代第一個。"},{"en":"It is useful when something belongs to more than one category.","zh":"當某物屬於多於一個類別時，它很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":2},{"front":"a trait","meaning":"一種特徵","examples":[{"en":"Nut-cracking is a trait considered to be an expression of chimpanzee culture.","zh":"敲開堅果是一種被認為是黑猩猩文化表現的特徵。"},{"en":"A trait is a feature, quality, or behaviour that belongs to a person, animal, or group.","zh":"trait 指屬於某人、動物或群體的特徵、品質或行為。"},{"en":"Patience can be a useful trait in a teacher.","zh":"耐性可以是老師的一種有用特徵。"},{"en":"A trait may be physical, such as eye colour, or behavioural, such as tool use.","zh":"特徵可以是身體上的，例如眼睛顏色，也可以是行為上的，例如使用工具。"},{"en":"This word is useful in biology, psychology, and everyday description.","zh":"這個詞適用於生物學、心理學和日常描述。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":2},{"front":"be considered to be","meaning":"被認為是","examples":[{"en":"This behaviour is considered to be an expression of chimpanzee culture.","zh":"這種行為被認為是黑猩猩文化的表現。"},{"en":"To be considered to be something means to be regarded or judged as that thing.","zh":"be considered to be something 指被視為或判斷為某物。"},{"en":"Regular attendance is considered to be important for language progress.","zh":"定期出席被認為對語言進步很重要。"},{"en":"If experts consider a behaviour cultural, they see it as learned and shared.","zh":"如果專家認為某行為是文化性的，他們會視它為學習得來並被共享。"},{"en":"This phrase is common in formal explanation and academic writing.","zh":"這個短語常見於正式解釋和學術寫作。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":2},{"front":"an expression of","meaning":"……的表現","examples":[{"en":"Biologists regard the behaviour as an expression of chimpanzee culture.","zh":"生物學家把這種行為視為黑猩猩文化的表現。"},{"en":"An expression of something is a visible sign or example of it.","zh":"expression of something 指某事的可見跡象或例子。"},{"en":"A festival can be an expression of a community’s history and values.","zh":"節日可以是一個社區歷史和價值觀的表現。"},{"en":"When a hidden idea appears in behaviour, the behaviour can express that idea.","zh":"當隱藏想法在行為中出現，該行為就可以表現該想法。"},{"en":"This phrase is useful when an action shows a deeper quality or tradition.","zh":"當行動顯示更深層特質或傳統時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":2},{"front":"chimpanzee culture","meaning":"黑猩猩文化","examples":[{"en":"Nut-cracking may be an expression of chimpanzee culture.","zh":"敲開堅果可能是黑猩猩文化的表現。"},{"en":"Chimpanzee culture means learned behaviours or traditions shared by chimpanzee groups.","zh":"chimpanzee culture 指黑猩猩群體中共享的學習行為或傳統。"},{"en":"One chimpanzee group may use a tool in a way that another group does not.","zh":"一個黑猩猩群體可能以另一群體不會的方式使用工具。"},{"en":"If young chimpanzees learn by watching adults, the behaviour may become part of culture.","zh":"如果幼黑猩猩透過觀察成年黑猩猩學習，該行為可能成為文化一部分。"},{"en":"This phrase challenges the idea that only humans have cultural traditions.","zh":"這個短語挑戰只有人類有文化傳統的想法。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":2},{"front":"frequently use the term","meaning":"經常使用……一詞","examples":[{"en":"Researchers frequently use the term “culture” to describe animal behaviours.","zh":"研究人員經常使用 culture 一詞來描述動物行為。"},{"en":"To frequently use the term means to use a particular word or phrase often.","zh":"frequently use the term 指經常使用某個詞或短語。"},{"en":"Teachers frequently use the term “main idea” in reading lessons.","zh":"老師在閱讀課中經常使用 main idea 一詞。"},{"en":"Frequent use of a term shows that it has become important in a field.","zh":"某術語被頻繁使用，顯示它在某領域變得重要。"},{"en":"This phrase is useful when discussing specialist vocabulary.","zh":"討論專業詞彙時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":2},{"front":"elementary animal behaviours","meaning":"基本的動物行為","examples":[{"en":"The term “culture” can describe elementary animal behaviours.","zh":"culture 一詞可以描述基本的動物行為。"},{"en":"Elementary animal behaviours are basic behaviours shown by animals.","zh":"elementary animal behaviours 指動物表現出的基本行為。"},{"en":"A bird learning a simple song pattern may show an elementary learned behaviour.","zh":"鳥學習簡單歌聲模式，可能顯示基本的學習行為。"},{"en":"Even basic behaviours can become important if they are learned socially.","zh":"即使基本行為，如果是透過社交學習而來，也可以很重要。"},{"en":"This phrase describes simple animal actions that may still matter scientifically.","zh":"這個短語描述簡單動物行動，但它們在科學上仍可能重要。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":2},{"front":"regional dialects","meaning":"地區性方言","examples":[{"en":"Regional dialects of songbirds are sometimes described as animal culture.","zh":"鳴禽的地區性方言有時被描述為動物文化。"},{"en":"Regional dialects are local forms of sound or speech that differ from place to place.","zh":"regional dialects 指因地區不同而不同的本地聲音或說話形式。"},{"en":"People from different towns may use regional dialects with different words or accents.","zh":"來自不同城鎮的人可能使用有不同詞語或口音的地區方言。"},{"en":"If birds in one area sing differently from birds elsewhere, researchers may call this a dialect.","zh":"如果某地鳥類唱歌方式不同於其他地方，研究者可能稱之為方言。"},{"en":"This phrase connects local variation with communication.","zh":"這個短語把地方差異與溝通連接起來。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":2},{"front":"species of songbirds","meaning":"鳴禽物種","examples":[{"en":"Different species of songbirds may have regional dialects.","zh":"不同鳴禽物種可能有地區性方言。"},{"en":"Species of songbirds are kinds of birds known for producing songs or calls.","zh":"species of songbirds 指以發出歌聲或叫聲聞名的鳥類種類。"},{"en":"Birdwatchers may identify species of songbirds by their colour, size, and song.","zh":"觀鳥者可能透過顏色、大小和歌聲辨認鳴禽物種。"},{"en":"Different species may learn or produce sounds in different ways.","zh":"不同物種可能以不同方式學習或發出聲音。"},{"en":"This phrase is common in animal behaviour and ecology.","zh":"這個短語常見於動物行為和生態。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":3},{"front":"it turns out that","meaning":"結果是；原來","examples":[{"en":"It turns out that chimpanzee cultural traditions are rich and varied.","zh":"原來黑猩猩的文化傳統豐富多樣。"},{"en":"It turns out that means the truth is discovered to be a certain way, often surprisingly.","zh":"it turns out that 指真相被發現是某種情況，常帶出乎意料意味。"},{"en":"It turns out that the quiet student had prepared the best presentation.","zh":"原來那位安靜學生準備了最好的匯報。"},{"en":"This phrase introduces a result that may differ from earlier expectations.","zh":"這個短語引出可能與早期預期不同的結果。"},{"en":"It is useful when new evidence changes what people think.","zh":"當新證據改變人們看法時，它很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":3},{"front":"rich and varied","meaning":"豐富多樣","examples":[{"en":"Chimpanzees enjoy rich and varied cultural traditions.","zh":"黑猩猩擁有豐富多樣的文化傳統。"},{"en":"Rich and varied means containing many different and interesting forms.","zh":"rich and varied 指包含許多不同而有趣的形式。"},{"en":"A school library with novels, comics, history books, and science magazines is rich and varied.","zh":"如果學校圖書館有小說、漫畫、歷史書和科學雜誌，它就是豐富多樣的。"},{"en":"Variety makes a subject more complex and harder to reduce to one simple rule.","zh":"多樣性令主題更複雜，也更難簡化成一條規則。"},{"en":"This phrase is useful when describing diversity and depth.","zh":"描述多樣性和深度時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":3},{"front":"cultural traditions","meaning":"文化傳統","examples":[{"en":"Chimpanzees have cultural traditions that are highly complex.","zh":"黑猩猩有高度複雜的文化傳統。"},{"en":"Cultural traditions are learned customs or behaviours passed within a group.","zh":"cultural traditions 指在群體中傳承的學習得來習俗或行為。"},{"en":"A family’s New Year meal can be a cultural tradition passed from grandparents to children.","zh":"家庭的新年飯可以是由祖父母傳給孩子的文化傳統。"},{"en":"Traditions survive when younger members learn them from older members.","zh":"當年輕成員向年長成員學習，傳統就能延續。"},{"en":"This phrase is used for both human culture and, in this passage, learned animal behaviour.","zh":"這個短語可用於人類文化，也可在本文中用於動物學習行為。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":3},{"front":"rank second in complexity only to","meaning":"在複雜程度上僅次於……","examples":[{"en":"Chimpanzee traditions rank second in complexity only to human traditions.","zh":"黑猩猩傳統在複雜程度上僅次於人類傳統。"},{"en":"To rank second in complexity only to something means to be less complex than only that one thing.","zh":"rank second in complexity only to something 指複雜程度只低於某一事物。"},{"en":"A city’s transport system may rank second in complexity only to the capital’s network.","zh":"一個城市的交通系統在複雜程度上可能僅次於首都網絡。"},{"en":"This phrase shows that something is extremely complex compared with most others.","zh":"這個短語顯示某物相比大多數其他事物非常複雜。"},{"en":"It is useful when placing one item just below the highest level.","zh":"把某物放在最高水平之下時，它很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":3},{"front":"human traditions","meaning":"人類傳統","examples":[{"en":"Chimpanzee traditions are less complex than human traditions.","zh":"黑猩猩傳統比人類傳統簡單。"},{"en":"Human traditions are customs, practices, beliefs, and behaviours passed among people.","zh":"human traditions 指在人群中傳承的習俗、做法、信念和行為。"},{"en":"Weddings, festivals, stories, and food habits can all be human traditions.","zh":"婚禮、節日、故事和飲食習慣都可以是人類傳統。"},{"en":"Human traditions can become complex because language allows detailed teaching and memory.","zh":"人類傳統可以變得複雜，因為語言容許詳細教導和記憶。"},{"en":"This phrase is useful when comparing people’s culture with animal behaviour.","zh":"比較人類文化與動物行為時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":3},{"front":"major groups studying chimpanzees","meaning":"研究黑猩猩的主要團隊","examples":[{"en":"The major groups studying chimpanzees collaborated on an unprecedented scale.","zh":"研究黑猩猩的主要團隊以前所未有的規模合作。"},{"en":"Major groups studying chimpanzees are the leading research teams that observe and analyse chimpanzee behaviour.","zh":"major groups studying chimpanzees 指觀察和分析黑猩猩行為的主要研究團隊。"},{"en":"Large research teams may share notes when one group alone cannot collect enough data.","zh":"當單一團隊不能收集足夠數據，大型研究團隊可能共享筆記。"},{"en":"Cooperation between major groups can produce stronger evidence than isolated studies.","zh":"主要團隊之間的合作可以產生比孤立研究更有力的證據。"},{"en":"This phrase identifies the main expert teams in the field.","zh":"這個短語指出該領域中的主要專家團隊。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":3},{"front":"collaborate on an unprecedented scale","meaning":"以前所未有的規模合作","examples":[{"en":"Researchers collaborated on an unprecedented scale to study chimpanzee culture.","zh":"研究人員以前所未有的規模合作研究黑猩猩文化。"},{"en":"To collaborate on an unprecedented scale means to work together more widely than ever before.","zh":"collaborate on an unprecedented scale 指以前所未見的廣泛程度合作。"},{"en":"Schools may collaborate on a large scale to create shared online lessons.","zh":"學校可能大規模合作，製作共享網上課堂。"},{"en":"Large-scale collaboration can combine data, experience, and methods from many places.","zh":"大規模合作可以結合來自許多地方的數據、經驗和方法。"},{"en":"This phrase is useful when cooperation is unusually broad or ambitious.","zh":"當合作特別廣泛或有野心時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":3},{"front":"document distinct cultural patterns","meaning":"記錄不同的文化模式","examples":[{"en":"The researchers documented distinct cultural patterns among chimpanzees.","zh":"研究人員記錄了黑猩猩之間不同的文化模式。"},{"en":"To document distinct cultural patterns means to record clear differences in learned behaviours between groups.","zh":"document distinct cultural patterns 指記錄不同群體之間清晰的學習行為差異。"},{"en":"A teacher may document learning patterns by comparing homework across classes.","zh":"老師可能透過比較不同班級功課來記錄學習模式。"},{"en":"Careful documentation helps turn scattered observations into reliable evidence.","zh":"仔細記錄有助把零散觀察變成可靠證據。"},{"en":"This phrase is common in research that records differences across communities.","zh":"這個短語常見於記錄不同社群差異的研究。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":3},{"front":"distinct cultural patterns","meaning":"明顯不同的文化模式","examples":[{"en":"The study documented distinct cultural patterns in chimpanzee communities.","zh":"研究記錄了黑猩猩群體中明顯不同的文化模式。"},{"en":"Distinct cultural patterns are clear and recognisable differences in traditions or behaviours between groups.","zh":"distinct cultural patterns 指不同群體之間清楚可辨的傳統或行為差異。"},{"en":"Different neighbourhoods may have distinct cultural patterns in food, speech, and festivals.","zh":"不同社區可能在食物、說話和節日方面有明顯不同的文化模式。"},{"en":"If patterns are distinct, researchers can compare communities more accurately.","zh":"如果模式明顯不同，研究人員可以更準確比較社群。"},{"en":"This phrase highlights clear variation rather than random behaviour.","zh":"這個短語突出清楚差異，而不是隨機行為。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":3},{"front":"range from…to…","meaning":"由……至……不等","examples":[{"en":"The behaviours ranged from tool use to forms of communication.","zh":"這些行為由使用工具至溝通形式不等。"},{"en":"Range from…to… means include many types between two examples.","zh":"range from…to… 指包括兩個例子之間的許多種類。"},{"en":"School activities may range from sports to music and public speaking.","zh":"學校活動可能由運動至音樂和公開演說不等。"},{"en":"This structure shows the breadth of a topic by giving two endpoints.","zh":"這個結構透過提供兩端例子來顯示主題範圍。"},{"en":"It is useful when a list is too long to mention fully.","zh":"當清單太長不能完整列出時，它很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":3},{"front":"use of tools","meaning":"使用工具","examples":[{"en":"The study examined chimpanzees’ use of tools.","zh":"研究檢視了黑猩猩使用工具的情況。"},{"en":"Use of tools means using objects to help perform a task.","zh":"use of tools 指使用物件來幫助完成任務。"},{"en":"A child’s use of scissors helps them cut paper more neatly.","zh":"孩子使用剪刀可以幫助他們更整齊地剪紙。"},{"en":"Tool use can show planning, learning, and problem-solving ability.","zh":"使用工具可以顯示計劃、學習和解難能力。"},{"en":"This phrase is important when discussing intelligence in humans or animals.","zh":"討論人類或動物智能時，這個短語很重要。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":4},{"front":"forms of communication","meaning":"溝通形式","examples":[{"en":"The researchers studied chimpanzees’ forms of communication.","zh":"研究人員研究黑猩猩的溝通形式。"},{"en":"Forms of communication are different ways of sending messages, such as sound, gesture, or facial expression.","zh":"forms of communication 指傳遞訊息的不同方式，例如聲音、手勢或面部表情。"},{"en":"In school, students use forms of communication like speaking, writing, and body language.","zh":"在學校，學生使用說話、寫作和身體語言等溝通形式。"},{"en":"Different forms of communication can show different needs or emotions.","zh":"不同溝通形式可以顯示不同需要或情感。"},{"en":"This phrase is useful when comparing how people or animals exchange information.","zh":"比較人或動物如何交換資訊時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":4},{"front":"social customs","meaning":"社會習俗","examples":[{"en":"Chimpanzees display social customs that vary between communities.","zh":"黑猩猩展示出在不同群體之間有所不同的社會習俗。"},{"en":"Social customs are shared behaviours that members of a group regularly follow.","zh":"social customs 指群體成員定期遵循的共同社會行為。"},{"en":"Shaking hands, bowing, or removing shoes indoors can be social customs.","zh":"握手、鞠躬或入屋除鞋都可以是社會習俗。"},{"en":"Customs help group members know what behaviour is expected.","zh":"習俗幫助群體成員知道預期行為是甚麼。"},{"en":"This phrase is useful when discussing culture, manners, and group life.","zh":"討論文化、禮儀和群體生活時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":4},{"front":"emerging picture","meaning":"逐漸形成的圖像；新浮現的理解","examples":[{"en":"The emerging picture of chimpanzees affects how people think about them.","zh":"對黑猩猩逐漸形成的新理解影響人們對牠們的看法。"},{"en":"An emerging picture is a new understanding that is gradually becoming clear.","zh":"emerging picture 指逐漸變得清楚的新理解。"},{"en":"After several interviews, an emerging picture of the school’s problems may appear.","zh":"經過幾次訪問後，學校問題的逐漸形成圖像可能出現。"},{"en":"As more evidence is collected, the picture becomes clearer and more reliable.","zh":"隨着更多證據被收集，圖像會變得更清楚、更可靠。"},{"en":"This phrase is useful when knowledge develops step by step.","zh":"當知識一步步發展時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":4},{"front":"affect how someone thinks about","meaning":"影響某人對……的看法","examples":[{"en":"This emerging picture affects how humans think about chimpanzees.","zh":"這個新浮現的理解影響人類對黑猩猩的看法。"},{"en":"To affect how someone thinks about something means to change their view or judgement.","zh":"affect how someone thinks about something 指改變某人對某事的看法或判斷。"},{"en":"A documentary can affect how students think about poverty.","zh":"紀錄片可以影響學生對貧窮的看法。"},{"en":"New evidence can make people rethink old assumptions.","zh":"新證據可以令人重新思考舊假設。"},{"en":"This phrase is useful when information changes attitudes or beliefs.","zh":"當資訊改變態度或信念時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":4},{"front":"amazing creatures","meaning":"令人驚奇的生物","examples":[{"en":"Chimpanzees are amazing creatures with complex cultural traditions.","zh":"黑猩猩是具有複雜文化傳統的令人驚奇的生物。"},{"en":"Amazing creatures are animals that impress people because of their abilities or behaviour.","zh":"amazing creatures 指因能力或行為而令人印象深刻的動物。"},{"en":"Dolphins are amazing creatures because they communicate and learn in complex ways.","zh":"海豚是令人驚奇的生物，因為牠們以複雜方式溝通和學習。"},{"en":"Calling animals amazing encourages readers to respect their intelligence and value.","zh":"稱動物為 amazing 可以鼓勵讀者尊重牠們的智能和價值。"},{"en":"This phrase is warm and appreciative rather than purely technical.","zh":"這個短語語氣欣賞而溫暖，不只是技術性描述。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":4},{"front":"alter our conception of","meaning":"改變我們對……的理解","examples":[{"en":"The research alters our conception of human uniqueness.","zh":"這項研究改變我們對人類獨特性的理解。"},{"en":"To alter our conception of something means to change how we understand or define it.","zh":"alter our conception of something 指改變我們如何理解或定義某事。"},{"en":"Online learning has altered our conception of what a classroom can be.","zh":"網上學習改變了我們對課室可以是甚麼的理解。"},{"en":"When evidence challenges an old idea, our conception of the topic may shift.","zh":"當證據挑戰舊想法，我們對該主題的理解可能轉變。"},{"en":"This phrase is formal and useful for discussing deep changes in thinking.","zh":"這個短語較正式，適合討論思維上的深層改變。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":4},{"front":"human uniqueness","meaning":"人類獨特性","examples":[{"en":"Chimpanzee culture challenges traditional ideas about human uniqueness.","zh":"黑猩猩文化挑戰關於人類獨特性的傳統想法。"},{"en":"Human uniqueness means the qualities that people believe make humans different from other animals.","zh":"human uniqueness 指人們認為使人類有別於其他動物的特質。"},{"en":"Language, culture, and moral reasoning are often discussed as parts of human uniqueness.","zh":"語言、文化和道德推理常被視為人類獨特性的一部分。"},{"en":"If animals show culture, the boundary between humans and animals may seem less sharp.","zh":"如果動物展示文化，人類與動物之間的界線可能顯得不那麼清晰。"},{"en":"This phrase is useful in discussions about evolution, intelligence, and culture.","zh":"這個短語適用於進化、智能和文化討論。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":4},{"front":"extraordinary ability","meaning":"非凡能力","examples":[{"en":"The findings reveal the extraordinary ability of ancient ancestors to create cultures.","zh":"這些發現揭示遠古祖先創造文化的非凡能力。"},{"en":"Extraordinary ability means an unusually impressive or powerful skill.","zh":"extraordinary ability 指異常出色或強大的能力。"},{"en":"A student who learns three languages quickly may show extraordinary language ability.","zh":"快速學會三種語言的學生可能展現非凡語言能力。"},{"en":"Recognising extraordinary ability can change how people judge a person or species.","zh":"認識到非凡能力可以改變人們對某人或某物種的判斷。"},{"en":"This phrase strongly praises a capacity that goes beyond the ordinary.","zh":"這個短語強烈讚揚超越普通水平的能力。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":4},{"front":"ancient ancestors","meaning":"遠古祖先","examples":[{"en":"The research helps us understand the abilities of our ancient ancestors.","zh":"這項研究幫助我們理解遠古祖先的能力。"},{"en":"Ancient ancestors are people or species from the distant past from whom later groups descended.","zh":"ancient ancestors 指遙遠過去的人或物種，後來群體由其演化或傳承而來。"},{"en":"Archaeologists study tools to learn how ancient ancestors lived and solved problems.","zh":"考古學家研究工具，以了解遠古祖先如何生活和解決問題。"},{"en":"Understanding ancestors can help explain why modern humans behave as they do.","zh":"理解祖先可以幫助解釋現代人為何如此行事。"},{"en":"This phrase is common in evolution, history, and anthropology.","zh":"這個短語常見於進化、歷史和人類學。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":4},{"front":"create cultures","meaning":"創造文化","examples":[{"en":"Ancient ancestors had the ability to create cultures.","zh":"遠古祖先有能力創造文化。"},{"en":"To create cultures means to develop shared customs, behaviours, tools, stories, or traditions.","zh":"create cultures 指發展共同習俗、行為、工具、故事或傳統。"},{"en":"A community can create culture through food, festivals, songs, and shared rules.","zh":"社區可以透過食物、節日、歌曲和共同規則創造文化。"},{"en":"Culture develops when individuals learn from one another and pass behaviours on.","zh":"當個體互相學習並傳承行為時，文化就會發展。"},{"en":"This phrase is useful when discussing how social traditions begin.","zh":"討論社會傳統如何開始時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":4},{"front":"Homo sapiens","meaning":"智人","examples":[{"en":"Homo sapiens and chimpanzees have coexisted for hundreds of millennia.","zh":"智人和黑猩猩共存了數十萬年。"},{"en":"Homo sapiens is the scientific name for modern humans.","zh":"Homo sapiens 是現代人類的科學名稱。"},{"en":"In biology class, students may learn that Homo sapiens belongs to the primate order.","zh":"在生物課中，學生可能學到智人屬於靈長目。"},{"en":"Scientific names help researchers avoid confusion between common names in different languages.","zh":"科學名稱幫助研究人員避免不同語言中普通名稱造成混淆。"},{"en":"This phrase is formal and used in scientific writing.","zh":"這個短語較正式，用於科學寫作。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":5},{"front":"Pan troglodytes","meaning":"普通黑猩猩","examples":[{"en":"Pan troglodytes is the scientific name for the common chimpanzee.","zh":"Pan troglodytes 是普通黑猩猩的科學名稱。"},{"en":"Pan troglodytes identifies the species commonly called the chimpanzee.","zh":"Pan troglodytes 指通常稱為黑猩猩的物種。"},{"en":"Scientists use names like Pan troglodytes to classify animals precisely.","zh":"科學家使用 Pan troglodytes 這類名稱來精確分類動物。"},{"en":"Scientific names allow researchers from different countries to discuss the same species clearly.","zh":"科學名稱讓不同國家的研究者清楚討論同一物種。"},{"en":"This phrase is technical and belongs to biology.","zh":"這個短語較技術性，屬於生物學。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":5},{"front":"coexist for hundreds of millennia","meaning":"共存了數十萬年","examples":[{"en":"Humans and chimpanzees have coexisted for hundreds of millennia.","zh":"人類和黑猩猩已共存了數十萬年。"},{"en":"To coexist for hundreds of millennia means to live at the same time for hundreds of thousands of years.","zh":"coexist for hundreds of millennia 指同時存在數十萬年。"},{"en":"Different animal species may coexist in the same forest for long periods.","zh":"不同動物物種可能在同一森林中長期共存。"},{"en":"Long coexistence can make comparisons between related species especially interesting.","zh":"長期共存可以令相關物種之間的比較特別有趣。"},{"en":"This phrase highlights a very long shared history.","zh":"這個短語突出非常漫長的共同歷史。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":5},{"front":"genetic similarities","meaning":"基因相似度","examples":[{"en":"The genetic similarities between humans and chimpanzees surpass 98 per cent.","zh":"人類與黑猩猩之間的基因相似度超過百分之九十八。"},{"en":"Genetic similarities are shared features in DNA or inherited biological material.","zh":"genetic similarities 指 DNA 或遺傳生物材料中的共同特徵。"},{"en":"Siblings often have strong genetic similarities because they share the same parents.","zh":"兄弟姊妹通常有很高基因相似度，因為他們有相同父母。"},{"en":"High genetic similarity can explain why two species have related physical or behavioural traits.","zh":"高基因相似度可以解釋為何兩個物種有相關的身體或行為特徵。"},{"en":"This phrase is common in biology and evolution.","zh":"這個短語常見於生物和進化。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":5},{"front":"surpass 98 per cent","meaning":"超過百分之九十八","examples":[{"en":"Their genetic similarities surpass 98 per cent.","zh":"牠們的基因相似度超過百分之九十八。"},{"en":"To surpass 98 per cent means to be higher than 98 per cent.","zh":"surpass 98 per cent 指高於百分之九十八。"},{"en":"A student’s attendance may surpass 98 per cent if she misses only one lesson all year.","zh":"如果學生全年只缺席一課，出席率可能超過百分之九十八。"},{"en":"A number above 98 per cent suggests an extremely high level of similarity or success.","zh":"超過百分之九十八的數字暗示非常高的相似度或成功程度。"},{"en":"This phrase is useful when a figure goes beyond a stated benchmark.","zh":"當數字超越指定基準時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":5},{"front":"know next to nothing about","meaning":"對……幾乎一無所知","examples":[{"en":"Researchers knew next to nothing about chimpanzee behaviour in the wild until 40 years ago.","zh":"直到四十年前，研究人員對野外黑猩猩行為幾乎一無所知。"},{"en":"To know next to nothing about something means to know almost nothing about it.","zh":"know next to nothing about something 指對某事幾乎完全不了解。"},{"en":"A new student may know next to nothing about the school rules on the first day.","zh":"新學生在第一天可能對校規幾乎一無所知。"},{"en":"When people know very little, careful observation can change understanding quickly.","zh":"當人們了解很少，仔細觀察可以迅速改變理解。"},{"en":"This phrase strongly emphasises lack of knowledge.","zh":"這個短語強烈強調缺乏知識。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":5},{"front":"chimpanzee behaviour in the wild","meaning":"野外黑猩猩行為","examples":[{"en":"Scientists once knew very little about chimpanzee behaviour in the wild.","zh":"科學家曾經對野外黑猩猩行為所知甚少。"},{"en":"Chimpanzee behaviour in the wild means how chimpanzees act in their natural habitats.","zh":"chimpanzee behaviour in the wild 指黑猩猩在自然棲息地中的行為。"},{"en":"Researchers may observe wild animals quietly so their natural behaviour is not disturbed.","zh":"研究人員可能安靜觀察野生動物，以免打擾牠們的自然行為。"},{"en":"Studying animals in the wild can reveal behaviours not seen in zoos.","zh":"在野外研究動物可以揭示動物園中看不到的行為。"},{"en":"This phrase contrasts natural behaviour with behaviour in captivity.","zh":"這個短語把自然行為與圈養行為作對比。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":5},{"front":"begin to change","meaning":"開始改變","examples":[{"en":"Knowledge about chimpanzee behaviour began to change in the 1960s.","zh":"對黑猩猩行為的知識在二十世紀六十年代開始改變。"},{"en":"To begin to change means to start becoming different.","zh":"begin to change 指開始變得不同。"},{"en":"A student’s attitude may begin to change after one encouraging conversation with a teacher.","zh":"學生的態度可能在與老師一次鼓勵性對話後開始改變。"},{"en":"Change often starts when new evidence or experience appears.","zh":"改變通常在新證據或新經驗出現時開始。"},{"en":"This phrase is useful when describing the start of a gradual shift.","zh":"描述逐漸轉變的開始時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":5},{"front":"in the 1960s","meaning":"在二十世紀六十年代","examples":[{"en":"Major field studies of chimpanzees began in the 1960s.","zh":"主要黑猩猩野外研究在二十世紀六十年代開始。"},{"en":"In the 1960s means during the years from 1960 to 1969.","zh":"in the 1960s 指在1960年至1969年間。"},{"en":"Many social and scientific changes took place in the 1960s.","zh":"許多社會和科學變化發生在二十世紀六十年代。"},{"en":"Giving a decade helps readers place research in historical context.","zh":"提供十年時期有助讀者把研究放入歷史背景。"},{"en":"This phrase is used to identify a broad time period.","zh":"這個短語用來指出一個廣泛時期。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":5},{"front":"renowned British primatologist","meaning":"著名英國靈長類動物學家","examples":[{"en":"Jane Goodall is a renowned British primatologist.","zh":"Jane Goodall 是著名英國靈長類動物學家。"},{"en":"A renowned British primatologist is a famous British scientist who studies primates.","zh":"renowned British primatologist 指研究靈長類動物的著名英國科學家。"},{"en":"A university may invite a renowned scientist to speak because students trust her expertise.","zh":"大學可能邀請著名科學家演講，因為學生信任其專業。"},{"en":"Renowned experts often shape how a whole field develops.","zh":"著名專家常會塑造整個領域的發展。"},{"en":"This phrase identifies both reputation, nationality, and scientific specialism.","zh":"這個短語同時指出名望、國籍和科學專業。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":5},{"front":"launch their studies of","meaning":"展開對……的研究","examples":[{"en":"Nishida and Goodall launched their studies of wild chimpanzees in Tanzania.","zh":"Nishida 和 Goodall 在坦桑尼亞展開對野生黑猩猩的研究。"},{"en":"To launch studies of something means to begin a planned research project about it.","zh":"launch studies of something 指開始一項有計劃的相關研究。"},{"en":"A hospital may launch a study of sleep habits among teenagers.","zh":"醫院可能展開對青少年睡眠習慣的研究。"},{"en":"Launching a study usually requires preparation, funding, and clear questions.","zh":"展開研究通常需要準備、資金和清楚問題。"},{"en":"This phrase is useful when describing the start of formal research.","zh":"描述正式研究的開始時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":5},{"front":"wild chimpanzees","meaning":"野生黑猩猩","examples":[{"en":"The researchers studied wild chimpanzees at field sites in Tanzania.","zh":"研究人員在坦桑尼亞的野外地點研究野生黑猩猩。"},{"en":"Wild chimpanzees are chimpanzees living in natural habitats rather than in captivity.","zh":"wild chimpanzees 指生活在自然棲息地而非圈養環境中的黑猩猩。"},{"en":"A wildlife documentary may follow wild chimpanzees as they search for food.","zh":"野生動物紀錄片可能跟拍野生黑猩猩尋找食物。"},{"en":"Studying wild animals helps researchers see behaviour shaped by natural conditions.","zh":"研究野生動物幫助研究人員看到受自然條件塑造的行為。"},{"en":"This phrase contrasts with zoo or laboratory animals.","zh":"這個短語與動物園或實驗室動物形成對比。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":6},{"front":"field sites","meaning":"野外研究地點","examples":[{"en":"The researchers worked at two field sites in Tanzania.","zh":"研究人員在坦桑尼亞兩個野外研究地點工作。"},{"en":"Field sites are real-world locations where researchers collect observations or data.","zh":"field sites 指研究人員收集觀察或數據的真實地點。"},{"en":"A geography class may visit a field site to measure river flow.","zh":"地理課可能到野外研究地點量度河流流速。"},{"en":"Field sites allow researchers to study behaviour in natural conditions.","zh":"野外研究地點讓研究人員在自然條件下研究行為。"},{"en":"This phrase is common in science and social research.","zh":"這個短語常見於科學和社會研究。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":6},{"front":"research station","meaning":"研究站","examples":[{"en":"Goodall’s research station at Gombe was the first of its kind.","zh":"Goodall 在貢貝的研究站是同類中的首個。"},{"en":"A research station is a place where scientists stay or work while studying a subject in the field.","zh":"research station 指科學家在野外研究時居住或工作的地方。"},{"en":"Scientists in Antarctica may live in a research station during winter.","zh":"南極科學家可能在冬季住在研究站。"},{"en":"A station provides equipment, shelter, and a base for long-term observation.","zh":"研究站提供設備、庇護和長期觀察基地。"},{"en":"This phrase is common in field science.","zh":"這個短語常見於野外科學。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":6},{"front":"the first of its kind","meaning":"同類中的首個","examples":[{"en":"Goodall’s research station was the first of its kind.","zh":"Goodall 的研究站是同類中的首個。"},{"en":"The first of its kind means the first example of that particular type.","zh":"first of its kind 指某一特定類型中的第一個例子。"},{"en":"A school may open the first of its kind programme for bilingual science teaching.","zh":"學校可能開設同類中的首個雙語科學教學計劃。"},{"en":"Being first matters because later projects may learn from it.","zh":"成為首個很重要，因為後來項目可能向它學習。"},{"en":"This phrase highlights originality or historical importance.","zh":"這個短語突出原創性或歷史重要性。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":6},{"front":"the second oldest","meaning":"第二古老的","examples":[{"en":"Nishida’s site at Mahale is the second oldest chimpanzee research site in the world.","zh":"Nishida 在馬哈勒的地點是世界第二古老的黑猩猩研究地點。"},{"en":"The second oldest means older than all others except one.","zh":"second oldest 指比所有其他都古老，除了一個之外。"},{"en":"A city library may be the second oldest public library in the country.","zh":"城市圖書館可能是全國第二古老的公共圖書館。"},{"en":"A long history can make a research site especially valuable for comparing changes over time.","zh":"悠久歷史可以令研究地點在比較長期變化時特別有價值。"},{"en":"This phrase ranks age or history.","zh":"這個短語用來排列年齡或歷史。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":6},{"front":"chimpanzee research site","meaning":"黑猩猩研究地點","examples":[{"en":"Mahale is an important chimpanzee research site.","zh":"馬哈勒是一個重要的黑猩猩研究地點。"},{"en":"A chimpanzee research site is a location where scientists study chimpanzees over time.","zh":"chimpanzee research site 指科學家長期研究黑猩猩的地方。"},{"en":"A research site may include forest paths, observation points, and records of known animals.","zh":"研究地點可能包括森林小徑、觀察點和已知動物的記錄。"},{"en":"Long-term sites help scientists notice changes in behaviour across generations.","zh":"長期研究地點幫助科學家注意到跨世代行為變化。"},{"en":"This phrase identifies a place dedicated to chimpanzee study.","zh":"這個短語指出專門研究黑猩猩的地方。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":6},{"front":"initial studies","meaning":"初期研究","examples":[{"en":"Researchers made remarkable discoveries during the initial studies.","zh":"研究人員在初期研究期間有重大發現。"},{"en":"Initial studies are the first studies carried out at the beginning of a research project.","zh":"initial studies 指研究項目開始時進行的第一批研究。"},{"en":"Initial studies of a new teaching method may involve only a few classes.","zh":"新教學方法的初期研究可能只涉及幾個班。"},{"en":"Early studies can reveal surprising questions that guide later research.","zh":"早期研究可以揭示令人意外的問題，引導之後研究。"},{"en":"This phrase refers to the first stage of investigation.","zh":"這個短語指調查的第一階段。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":6},{"front":"become accustomed to","meaning":"習慣於","examples":[{"en":"The chimpanzees became accustomed to close observation.","zh":"黑猩猩習慣了近距離觀察。"},{"en":"To become accustomed to something means to get used to it over time.","zh":"become accustomed to something 指隨時間逐漸習慣某事。"},{"en":"New students become accustomed to school routines after a few weeks.","zh":"新學生幾星期後會習慣學校常規。"},{"en":"When animals become accustomed to observers, researchers can watch them more naturally.","zh":"當動物習慣觀察者，研究人員就能更自然地觀察牠們。"},{"en":"This phrase describes gradual comfort with a repeated situation.","zh":"這個短語描述對重複情況逐漸感到自在。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":6},{"front":"close observation","meaning":"近距離觀察","examples":[{"en":"The chimpanzees became accustomed to close observation by researchers.","zh":"黑猩猩習慣了研究人員的近距離觀察。"},{"en":"Close observation means careful watching from a near distance or with detailed attention.","zh":"close observation 指從近距離或以細緻注意力仔細觀察。"},{"en":"A doctor may use close observation to monitor a patient’s symptoms.","zh":"醫生可能透過近距離觀察監察病人症狀。"},{"en":"Careful observation can reveal behaviours that quick visits would miss.","zh":"仔細觀察可以揭示短暫探訪會錯過的行為。"},{"en":"This phrase is common in science, medicine, and teaching.","zh":"這個短語常見於科學、醫學和教學。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":6},{"front":"make remarkable discoveries","meaning":"有重大發現","examples":[{"en":"Researchers made remarkable discoveries about chimpanzee behaviour.","zh":"研究人員對黑猩猩行為有重大發現。"},{"en":"To make remarkable discoveries means to find important or surprising new information.","zh":"make remarkable discoveries 指發現重要或令人驚訝的新資訊。"},{"en":"A science class may make a small discovery when an experiment gives an unexpected result.","zh":"科學課實驗出現意外結果時，學生可能有小發現。"},{"en":"Important discoveries can change what people believe about a topic.","zh":"重要發現可以改變人們對某主題的信念。"},{"en":"This phrase is useful when research produces meaningful new knowledge.","zh":"當研究產生有意義的新知識時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":6},{"front":"witness a variety of","meaning":"目睹各種各樣的……","examples":[{"en":"Researchers witnessed a variety of unexpected behaviours.","zh":"研究人員目睹各種各樣出乎意料的行為。"},{"en":"To witness a variety of something means to see many different examples of it directly.","zh":"witness a variety of something 指親眼看到某事的許多不同例子。"},{"en":"A teacher may witness a variety of learning styles in one classroom.","zh":"老師可能在一個課室中目睹各種不同學習風格。"},{"en":"Seeing many examples helps researchers avoid judging from one case only.","zh":"看見許多例子有助研究人員避免只從單一個案下判斷。"},{"en":"This phrase is useful when people observe diversity first-hand.","zh":"當人們親身觀察到多樣性時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":6},{"front":"unexpected behaviours","meaning":"出乎意料的行為","examples":[{"en":"The researchers observed unexpected behaviours among chimpanzees.","zh":"研究人員觀察到黑猩猩之間出乎意料的行為。"},{"en":"Unexpected behaviours are actions people did not predict or imagine beforehand.","zh":"unexpected behaviours 指人們事前沒有預測或想像到的行動。"},{"en":"A quiet child may show unexpected behaviour by leading a group confidently.","zh":"安靜孩子自信地帶領小組，可能顯示出乎意料的行為。"},{"en":"Unexpected behaviours can make researchers question old assumptions.","zh":"出乎意料的行為可以令研究人員質疑舊假設。"},{"en":"This phrase is useful when observation surprises people.","zh":"當觀察結果令人驚訝時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":7},{"front":"fashion and use tools","meaning":"製作和使用工具","examples":[{"en":"Chimpanzees were seen fashioning and using tools.","zh":"研究人員看到黑猩猩製作和使用工具。"},{"en":"To fashion and use tools means to make or shape objects and then use them for a task.","zh":"fashion and use tools 指製作或塑造物件，然後用它完成任務。"},{"en":"A child may fashion a paper funnel and use it to pour rice into a bottle.","zh":"孩子可能製作紙漏斗，並用它把米倒進瓶子。"},{"en":"Making and using tools shows planning and practical problem-solving.","zh":"製作和使用工具顯示計劃和實際解難能力。"},{"en":"This phrase is important when discussing animal intelligence.","zh":"討論動物智能時，這個短語很重要。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":7},{"front":"meat eating","meaning":"食肉行為","examples":[{"en":"Researchers observed hunting, meat eating and food sharing.","zh":"研究人員觀察到狩獵、食肉行為和分享食物。"},{"en":"Meat eating means eating the flesh of animals.","zh":"meat eating 指吃動物肉。"},{"en":"A biology lesson may compare meat eating with plant-based diets in different animals.","zh":"生物課可能比較不同動物的食肉行為與植物性飲食。"},{"en":"Observing meat eating in chimpanzees changed older ideas about their diet and behaviour.","zh":"觀察到黑猩猩食肉改變了早期對牠們飲食和行為的看法。"},{"en":"This phrase describes a feeding behaviour.","zh":"這個短語描述進食行為。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":7},{"front":"food sharing","meaning":"分享食物","examples":[{"en":"Food sharing was one of the unexpected behaviours observed.","zh":"分享食物是被觀察到的出乎意料行為之一。"},{"en":"Food sharing means giving part of one’s food to others.","zh":"food sharing 指把自己部分食物給予他人。"},{"en":"Children practise food sharing when they offer snacks to classmates.","zh":"孩子把零食分給同學時，就是在練習分享食物。"},{"en":"In animals, food sharing may reveal social bonds and cooperation.","zh":"在動物身上，分享食物可能揭示社交連繫和合作。"},{"en":"This phrase is useful when discussing generosity, relationships, or group behaviour.","zh":"討論慷慨、關係或群體行為時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":7},{"front":"lethal fights","meaning":"致命打鬥","examples":[{"en":"Researchers observed lethal fights between neighbouring communities.","zh":"研究人員觀察到鄰近群體之間的致命打鬥。"},{"en":"Lethal fights are fights that can cause death.","zh":"lethal fights 指可能造成死亡的打鬥。"},{"en":"Police may treat a street fight as extremely serious if it becomes potentially lethal.","zh":"如果街頭打鬥變得可能致命，警方可能會極嚴肅處理。"},{"en":"Lethal conflict between animal groups can affect territory, survival, and group size.","zh":"動物群體之間的致命衝突可以影響領地、生存和群體大小。"},{"en":"This phrase is strong and describes violent conflict with deadly consequences.","zh":"這個短語語氣強，描述具有致命後果的暴力衝突。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":7},{"front":"neighbouring communities","meaning":"鄰近群體","examples":[{"en":"Chimpanzees sometimes fought members of neighbouring communities.","zh":"黑猩猩有時與鄰近群體的成員打鬥。"},{"en":"Neighbouring communities are groups that live close to one another.","zh":"neighbouring communities 指生活在彼此附近的群體。"},{"en":"Two neighbouring communities may share a park, a road, or a local market.","zh":"兩個鄰近社區可能共享公園、道路或本地市場。"},{"en":"Living near one another can lead to cooperation, competition, or conflict.","zh":"住得近可以導致合作、競爭或衝突。"},{"en":"This phrase is useful when discussing nearby groups of people or animals.","zh":"討論附近的人類或動物群體時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":7},{"front":"forms of tool use","meaning":"使用工具的形式","examples":[{"en":"Goodall recorded several forms of tool use among chimpanzees.","zh":"Goodall 記錄了黑猩猩幾種使用工具的形式。"},{"en":"Forms of tool use are different ways of using objects to solve problems or complete tasks.","zh":"forms of tool use 指使用物件解決問題或完成任務的不同方式。"},{"en":"Students may show different forms of tool use when they use rulers, calculators, or scissors.","zh":"學生使用尺、計數機或剪刀時，可能展現不同工具使用形式。"},{"en":"Different tool-use forms can reveal different skills and learning traditions.","zh":"不同工具使用形式可以揭示不同技能和學習傳統。"},{"en":"This phrase is useful when a general ability appears in several specific ways.","zh":"當一般能力以幾種具體方式出現時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":7},{"front":"social activities","meaning":"社交活動","examples":[{"en":"Goodall recorded eight social activities that varied between chimpanzee groups.","zh":"Goodall 記錄了八種在黑猩猩群體之間有所不同的社交活動。"},{"en":"Social activities are actions people or animals do with others in a group.","zh":"social activities 指人或動物在群體中與他者一起進行的活動。"},{"en":"School clubs, team games, and group lunches are social activities.","zh":"學會、團隊遊戲和小組午餐都是社交活動。"},{"en":"Social activities can show how relationships and group rules work.","zh":"社交活動可以顯示關係和群體規則如何運作。"},{"en":"This phrase is useful when discussing behaviour within a community.","zh":"討論社群內行為時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":7},{"front":"appear to differ between","meaning":"似乎在……之間有所不同","examples":[{"en":"Some behaviours appeared to differ between Gombe chimpanzees and chimpanzees elsewhere.","zh":"有些行為似乎在貢貝黑猩猩與其他地方黑猩猩之間有所不同。"},{"en":"Appear to differ between means seem to be different when two groups are compared.","zh":"appear to differ between 指比較兩個群體時似乎不同。"},{"en":"Study habits may appear to differ between morning students and evening students.","zh":"早班學生和晚班學生之間的學習習慣可能似乎有所不同。"},{"en":"When behaviours differ between groups, researchers may look for cultural or environmental reasons.","zh":"當行為在群體之間有所不同，研究者可能尋找文化或環境原因。"},{"en":"This phrase is cautious because appear suggests observation, not final proof.","zh":"這個短語較謹慎，因為 appear 暗示觀察結果，而非最終證明。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":7},{"front":"chimpanzees elsewhere","meaning":"其他地方的黑猩猩","examples":[{"en":"The Gombe chimpanzees behaved differently from chimpanzees elsewhere.","zh":"貢貝黑猩猩的行為不同於其他地方的黑猩猩。"},{"en":"Chimpanzees elsewhere means chimpanzees living in other places.","zh":"chimpanzees elsewhere 指生活在其他地方的黑猩猩。"},{"en":"Researchers may compare one forest group with chimpanzees elsewhere to find local patterns.","zh":"研究人員可能把一個森林群體與其他地方的黑猩猩比較，以找出地方模式。"},{"en":"Differences between places can suggest that environment or learning matters.","zh":"地區之間的差異可以暗示環境或學習很重要。"},{"en":"This phrase is useful when comparing one research site with other locations.","zh":"比較一個研究地點與其他地點時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":7},{"front":"speculate that","meaning":"推測","examples":[{"en":"Goodall speculated that some variations had a cultural origin.","zh":"Goodall 推測某些差異有文化起源。"},{"en":"To speculate that means to suggest a possible explanation without complete proof.","zh":"speculate that 指在沒有完整證明下提出可能解釋。"},{"en":"A teacher may speculate that low scores were caused by unclear instructions.","zh":"老師可能推測低分是由指示不清造成。"},{"en":"Speculation can guide research, but it needs evidence before becoming a conclusion.","zh":"推測可以引導研究，但在成為結論前需要證據。"},{"en":"This phrase is useful when discussing careful guesses.","zh":"討論謹慎猜測時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":7},{"front":"variations","meaning":"差異；變化","examples":[{"en":"Some behavioural variations may have had a cultural origin.","zh":"某些行為差異可能有文化起源。"},{"en":"Variations are differences or changes between examples of the same thing.","zh":"variations 指同一事物不同例子之間的差異或變化。"},{"en":"There may be variations in pronunciation between speakers from different regions.","zh":"不同地區說話者之間可能有發音差異。"},{"en":"Variations can help researchers see patterns that are not obvious at first.","zh":"差異可以幫助研究人員看到起初不明顯的模式。"},{"en":"This word is useful when comparing similar behaviours or forms.","zh":"比較相似行為或形式時，這個詞很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":8},{"front":"cultural origin","meaning":"文化起源","examples":[{"en":"Goodall suggested that some variations had a cultural origin.","zh":"Goodall 提出某些差異有文化起源。"},{"en":"Cultural origin means the source of a behaviour is learning or tradition within a group.","zh":"cultural origin 指某行為的來源是群體中的學習或傳統。"},{"en":"A local greeting may have a cultural origin rather than a practical one.","zh":"本地問候方式可能有文化起源，而不是純粹實際用途。"},{"en":"If a behaviour has a cultural origin, it is likely passed on socially.","zh":"如果一種行為有文化起源，它很可能是透過社交傳承。"},{"en":"This phrase contrasts learned tradition with genetics or environment alone.","zh":"這個短語把學習傳統與單純基因或環境作對比。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":8},{"front":"what exactly did someone mean by","meaning":"某人所說的……究竟是甚麼意思","examples":[{"en":"Researchers asked what exactly Goodall meant by “culture”.","zh":"研究人員問 Goodall 所說的 culture 究竟是甚麼意思。"},{"en":"What exactly did someone mean by asks for the precise meaning behind a word or claim.","zh":"what exactly did someone mean by 用來詢問某個詞或說法背後的精確意思。"},{"en":"A student may ask what exactly the teacher means by “analyse” in an essay question.","zh":"學生可能問老師在作文題中所說的 analyse 究竟是甚麼意思。"},{"en":"Asking for exact meaning prevents misunderstanding, especially with abstract words.","zh":"詢問確切意思可以避免誤解，尤其是抽象詞。"},{"en":"This phrase is useful when a term can be interpreted in different ways.","zh":"當術語可以有不同理解時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":8},{"front":"according to","meaning":"根據","examples":[{"en":"According to the dictionary, culture includes customs and achievements.","zh":"根據字典，文化包括習俗與成就。"},{"en":"According to means based on what a source says.","zh":"according to 指基於某來源所說。"},{"en":"According to the timetable, the last train leaves at midnight.","zh":"根據時間表，最後一班火車在午夜開出。"},{"en":"This phrase helps show where information comes from.","zh":"這個短語幫助顯示資訊來源。"},{"en":"It is common in reports, essays, and reading questions.","zh":"它常見於報告、文章和閱讀題。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":8},{"front":"be defined as","meaning":"被定義為","examples":[{"en":"Culture is defined as the customs and achievements of a particular people.","zh":"文化被定義為某一民族的習俗與成就。"},{"en":"To be defined as something means to be explained as having a particular meaning.","zh":"be defined as something 指被解釋為具有某特定意思。"},{"en":"A noun is often defined as a word that names a person, place, or thing.","zh":"名詞常被定義為命名人、地方或事物的詞。"},{"en":"Definitions help people use words accurately and consistently.","zh":"定義幫助人們準確而一致地使用詞語。"},{"en":"This phrase is useful when explaining terms clearly.","zh":"清楚解釋術語時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":8},{"front":"customs and achievements","meaning":"習俗與成就","examples":[{"en":"Culture includes the customs and achievements of a particular time or people.","zh":"文化包括某一時代或民族的習俗與成就。"},{"en":"Customs and achievements are a group’s traditions, habits, creations, and accomplishments.","zh":"customs and achievements 指一個群體的傳統、習慣、創作和成就。"},{"en":"A museum may display a community’s customs and achievements through clothing, tools, and art.","zh":"博物館可能透過衣物、工具和藝術展示一個社區的習俗與成就。"},{"en":"Customs show how people live, while achievements show what they have created or accomplished.","zh":"習俗顯示人們如何生活，而成就顯示他們創造或完成了甚麼。"},{"en":"This phrase is useful when describing broad culture.","zh":"描述廣義文化時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":8},{"front":"a particular time or people","meaning":"某一時代或民族","examples":[{"en":"The definition refers to the customs of a particular time or people.","zh":"這個定義指某一時代或民族的習俗。"},{"en":"A particular time or people means a specific historical period or group of people.","zh":"particular time or people 指特定歷史時期或人群。"},{"en":"Victorian clothing reflects the habits of a particular time and society.","zh":"維多利亞時代服裝反映某一時代和社會的習慣。"},{"en":"Culture often makes more sense when we know the period or people it belongs to.","zh":"當我們知道文化屬於哪個時期或人群，它通常更容易理解。"},{"en":"This phrase helps narrow a broad idea to a specific context.","zh":"這個短語幫助把廣泛想法收窄到具體背景。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":8},{"front":"the diversity of human cultures","meaning":"人類文化的多樣性","examples":[{"en":"The diversity of human cultures includes rituals, habits and stories.","zh":"人類文化的多樣性包括儀式、習慣和故事。"},{"en":"The diversity of human cultures means the many different ways human groups live, believe, and organise life.","zh":"diversity of human cultures 指人類群體生活、信仰和組織生活的多種方式。"},{"en":"Food, clothing, language, religion, and family roles show cultural diversity.","zh":"食物、衣服、語言、宗教和家庭角色都顯示文化多樣性。"},{"en":"Diversity makes comparison important because no single culture represents all people.","zh":"多樣性令比較重要，因為沒有單一文化代表所有人。"},{"en":"This phrase is useful when discussing human societies across the world.","zh":"討論世界各地人類社會時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":8},{"front":"extend from…to…","meaning":"從……延伸至……","examples":[{"en":"Human cultures extend from technological variations to marriage rituals.","zh":"人類文化從技術差異延伸至婚姻儀式。"},{"en":"Extend from…to… means cover a range between two examples.","zh":"extend from…to… 指涵蓋兩個例子之間的範圍。"},{"en":"School support may extend from homework help to counselling.","zh":"學校支援可能從功課幫助延伸至輔導。"},{"en":"This phrase shows that a topic includes many different areas.","zh":"這個短語顯示一個主題包括許多不同領域。"},{"en":"It is useful when the full range is broad.","zh":"當整體範圍很廣時，它很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":8},{"front":"technological variations","meaning":"技術差異","examples":[{"en":"Human cultures include technological variations and social rituals.","zh":"人類文化包括技術差異和社會儀式。"},{"en":"Technological variations are differences in tools, methods, or practical techniques between groups.","zh":"technological variations 指不同群體在工具、方法或實用技術上的差異。"},{"en":"Farmers in different regions may use technological variations suited to their climate.","zh":"不同地區農民可能使用適合其氣候的技術差異。"},{"en":"Different tools can reflect local needs, resources, and traditions.","zh":"不同工具可以反映本地需要、資源和傳統。"},{"en":"This phrase is useful when comparing how groups solve practical problems.","zh":"比較群體如何解決實際問題時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":8},{"front":"marriage rituals","meaning":"婚姻儀式","examples":[{"en":"Marriage rituals are part of the diversity of human cultures.","zh":"婚姻儀式是人類文化多樣性的一部分。"},{"en":"Marriage rituals are formal customs or ceremonies connected with marriage.","zh":"marriage rituals 指與婚姻相關的正式習俗或典禮。"},{"en":"A wedding may include marriage rituals such as exchanging rings or serving tea to elders.","zh":"婚禮可能包括交換戒指或向長輩敬茶等婚姻儀式。"},{"en":"Rituals help communities mark important life events and shared values.","zh":"儀式幫助社群標記重要人生事件和共同價值。"},{"en":"This phrase is useful when discussing culture, family, and tradition.","zh":"討論文化、家庭和傳統時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":8},{"front":"culinary habits","meaning":"飲食習慣","examples":[{"en":"Culinary habits differ widely across human cultures.","zh":"飲食習慣在人類文化之間差異很大。"},{"en":"Culinary habits are the ways people cook, eat, serve, and value food.","zh":"culinary habits 指人們烹調、進食、上菜和重視食物的方式。"},{"en":"A family’s habit of eating rice at dinner is part of its culinary habits.","zh":"家庭晚餐吃飯的習慣是其飲食習慣的一部分。"},{"en":"Food habits can reveal climate, religion, history, and family life.","zh":"飲食習慣可以揭示氣候、宗教、歷史和家庭生活。"},{"en":"This phrase is useful when discussing culture through food.","zh":"透過食物討論文化時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":9},{"front":"myths and legends","meaning":"神話與傳說","examples":[{"en":"Animals do not have myths and legends.","zh":"動物沒有神話與傳說。"},{"en":"Myths and legends are traditional stories passed down in a culture.","zh":"myths and legends 指在文化中傳承下來的傳統故事。"},{"en":"Children may hear myths and legends about heroes, gods, or strange creatures.","zh":"孩子可能聽到關於英雄、神明或奇異生物的神話與傳說。"},{"en":"Such stories help human groups explain values, origins, and fears.","zh":"這類故事幫助人類群體解釋價值、起源和恐懼。"},{"en":"This phrase is useful when discussing human culture and storytelling.","zh":"討論人類文化和敘事時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":9},{"front":"share the capacity to","meaning":"同樣具備……的能力","examples":[{"en":"Animals share the capacity to pass on behavioural traits.","zh":"動物同樣具備傳承行為特徵的能力。"},{"en":"To share the capacity to do something means to have the same ability to do it.","zh":"share the capacity to do something 指同樣有能力做某事。"},{"en":"Children and adults share the capacity to learn from mistakes.","zh":"孩子和成年人同樣具備從錯誤中學習的能力。"},{"en":"If animals share a capacity with humans, the difference between them may seem smaller.","zh":"如果動物與人類具備同一能力，牠們之間的差異可能顯得較小。"},{"en":"This phrase is useful when comparing abilities across groups.","zh":"比較不同群體能力時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":9},{"front":"pass on behavioural traits","meaning":"傳承行為特徵","examples":[{"en":"Animals can pass on behavioural traits through learning.","zh":"動物可以透過學習傳承行為特徵。"},{"en":"To pass on behavioural traits means to transmit ways of acting from one individual or generation to another.","zh":"pass on behavioural traits 指把行為方式由一個個體或世代傳給另一個。"},{"en":"Parents may pass on polite habits to children by modelling them daily.","zh":"父母可以透過每天示範把禮貌習慣傳給孩子。"},{"en":"In animals, behaviours can spread when younger individuals copy older ones.","zh":"在動物中，當年幼個體模仿年長個體，行為可以傳播。"},{"en":"This phrase focuses on learned behaviour being transferred.","zh":"這個短語聚焦學習得來行為的轉移。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":9},{"front":"from one generation to another","meaning":"由一代傳至下一代","examples":[{"en":"Cultural traits can pass from one generation to another.","zh":"文化特徵可以由一代傳至下一代。"},{"en":"From one generation to another means from older members of a group to younger members over time.","zh":"from one generation to another 指隨時間由群體中年長成員傳給年輕成員。"},{"en":"Family recipes often pass from one generation to another.","zh":"家庭食譜常由一代傳至下一代。"},{"en":"If knowledge is not taught, it may fail to reach the next generation.","zh":"如果知識沒有被教導，它可能無法傳到下一代。"},{"en":"This phrase is useful when discussing tradition and inheritance.","zh":"討論傳統和傳承時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":9},{"front":"not through genes but via learning","meaning":"不是透過基因，而是透過學習","examples":[{"en":"Chimpanzees pass on some behaviours not through genes but via learning.","zh":"黑猩猩傳承某些行為不是透過基因，而是透過學習。"},{"en":"Not through genes but via learning means the behaviour is transmitted by observation and practice, not inherited DNA.","zh":"not through genes but via learning 指行為透過觀察和練習傳遞，而不是透過遺傳 DNA。"},{"en":"A child learns table manners not through genes but by watching family members.","zh":"孩子學習餐桌禮儀不是透過基因，而是透過觀察家人。"},{"en":"This contrast helps separate biological inheritance from social learning.","zh":"這個對比幫助區分生物遺傳和社會學習。"},{"en":"The phrase is useful when explaining culture in animals or humans.","zh":"解釋動物或人類文化時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":9},{"front":"from the biologists’ point of view","meaning":"從生物學家的角度看","examples":[{"en":"From the biologists’ point of view, learning is central to culture.","zh":"從生物學家的角度看，學習是文化的核心。"},{"en":"From the biologists’ point of view means according to how biologists understand the issue.","zh":"from the biologists’ point of view 指根據生物學家對該議題的理解。"},{"en":"From a teacher’s point of view, regular practice matters more than last-minute study.","zh":"從老師的角度看，定期練習比臨急抱佛腳更重要。"},{"en":"Different fields may define the same word in different ways.","zh":"不同領域可能以不同方式定義同一個詞。"},{"en":"This phrase is useful when showing a specific expert perspective.","zh":"顯示特定專家角度時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":9},{"front":"fundamental criterion","meaning":"基本準則","examples":[{"en":"Learning from others is the fundamental criterion for a cultural trait.","zh":"向他者學習是文化特徵的基本準則。"},{"en":"A fundamental criterion is a basic rule or requirement used to judge something.","zh":"fundamental criterion 指用來判斷某事的基本規則或要求。"},{"en":"In a writing test, clear communication is a fundamental criterion for a good answer.","zh":"在寫作考試中，清楚溝通是好答案的基本準則。"},{"en":"Without the key criterion, an example may not belong to the category.","zh":"如果沒有關鍵準則，某例子可能不屬於該類別。"},{"en":"This phrase is formal and useful for definitions and classification.","zh":"這個短語較正式，適合定義和分類。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":9},{"front":"cultural trait","meaning":"文化特徵","examples":[{"en":"A cultural trait can be learnt and passed on to later generations.","zh":"文化特徵可以被學習並傳給後代。"},{"en":"A cultural trait is a learned behaviour, custom, or feature shared within a group.","zh":"cultural trait 指在群體中共享的學習行為、習俗或特點。"},{"en":"Greeting elders politely can be a cultural trait in a community.","zh":"禮貌問候長輩可以是一個社區的文化特徵。"},{"en":"Cultural traits survive when members copy, teach, and value them.","zh":"當成員模仿、教導和重視文化特徵，它們就能延續。"},{"en":"This phrase is useful when discussing specific parts of culture.","zh":"討論文化的具體部分時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":9},{"front":"learn by observing","meaning":"透過觀察學習","examples":[{"en":"Young chimpanzees may learn by observing the established skills of others.","zh":"幼黑猩猩可能透過觀察他者已掌握的技能來學習。"},{"en":"To learn by observing means to learn by watching how others do something.","zh":"learn by observing 指透過觀看他人如何做某事來學習。"},{"en":"A child may learn to tie shoelaces by observing an older sibling.","zh":"孩子可能透過觀察哥哥姐姐學會綁鞋帶。"},{"en":"Observation helps learners copy actions before they can explain the rules.","zh":"觀察幫助學習者在能解釋規則之前先模仿動作。"},{"en":"This phrase is useful when discussing social learning.","zh":"討論社會學習時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":9},{"front":"established skills","meaning":"已掌握的技能","examples":[{"en":"Cultural behaviours can be learnt by observing established skills.","zh":"文化行為可以透過觀察已掌握的技能而學會。"},{"en":"Established skills are abilities that someone has already learned and can perform reliably.","zh":"established skills 指某人已學會並能可靠表現的能力。"},{"en":"A new worker may learn established skills by watching experienced colleagues.","zh":"新員工可能透過觀察有經驗同事學習已掌握的技能。"},{"en":"Skills become established through practice, repetition, and successful use.","zh":"技能透過練習、重複和成功使用而變得穩固。"},{"en":"This phrase is useful when learners copy people who already know how to do something.","zh":"當學習者模仿已懂得做某事的人時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":9},{"front":"subsequent generations","meaning":"後代；其後的世代","examples":[{"en":"Cultural traits may be passed on to subsequent generations.","zh":"文化特徵可能傳給後代。"},{"en":"Subsequent generations are the generations that come later.","zh":"subsequent generations 指後來出現的世代。"},{"en":"Grandparents may pass family stories to subsequent generations.","zh":"祖父母可能把家庭故事傳給後代。"},{"en":"If traditions are not taught, subsequent generations may lose them.","zh":"如果傳統沒有被教導，後代可能失去它們。"},{"en":"This phrase is useful when discussing long-term cultural transmission.","zh":"討論長期文化傳承時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":10},{"front":"implications for","meaning":"對……的影響","examples":[{"en":"The implications for chimpanzees themselves are grave.","zh":"對黑猩猩本身的影響是嚴重的。"},{"en":"Implications for something are the possible effects or meanings for it.","zh":"implications for something 指對某事可能造成的影響或含意。"},{"en":"A new exam policy may have serious implications for teachers and students.","zh":"新考試政策可能對老師和學生有嚴重影響。"},{"en":"When implications are serious, people need to think beyond the immediate facts.","zh":"當影響嚴重，人們需要思考即時事實以外的後果。"},{"en":"This phrase is useful when discussing consequences.","zh":"討論後果時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":10},{"front":"grave","meaning":"嚴重的","examples":[{"en":"The implications for chimpanzees are grave.","zh":"對黑猩猩的影響是嚴重的。"},{"en":"Grave means very serious and worrying.","zh":"grave 指非常嚴重且令人擔憂。"},{"en":"A doctor may use a grave tone when explaining a dangerous illness.","zh":"醫生解釋危險疾病時，可能用嚴肅語氣。"},{"en":"Grave problems require urgent attention because the consequences may be severe.","zh":"嚴重問題需要緊急關注，因為後果可能很嚴重。"},{"en":"This word is formal and stronger than serious.","zh":"這個詞較正式，比 serious 更強。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":10},{"front":"populations are being decimated","meaning":"種群正被大量摧毀","examples":[{"en":"Chimpanzee populations are being decimated as researchers learn more about them.","zh":"當研究人員更了解黑猩猩時，黑猩猩種群正被大量摧毀。"},{"en":"Populations are being decimated means groups of animals or people are being destroyed or greatly reduced.","zh":"populations are being decimated 指動物或人類群體正被摧毀或大幅減少。"},{"en":"Fish populations may be decimated if a river is polluted for many years.","zh":"如果河流多年受污染，魚類種群可能被大量摧毀。"},{"en":"When populations are decimated, genetic diversity and local traditions may disappear.","zh":"當種群被大量摧毀，基因多樣性和地方傳統可能消失。"},{"en":"This phrase describes severe population decline.","zh":"這個短語描述嚴重的種群下降。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":10},{"front":"finally beginning to appreciate","meaning":"終於開始更全面地欣賞","examples":[{"en":"Humans are finally beginning to appreciate chimpanzees more fully.","zh":"人類終於開始更全面地欣賞黑猩猩。"},{"en":"Finally beginning to appreciate means starting, after a long time, to understand or value something.","zh":"finally beginning to appreciate 指經過很長時間後開始理解或重視某事。"},{"en":"A student may finally begin to appreciate grammar after seeing how it improves writing.","zh":"學生看到文法如何改善寫作後，可能終於開始欣賞文法。"},{"en":"Appreciation often grows when people see hidden value or complexity.","zh":"當人們看見隱藏價值或複雜性，欣賞常會增加。"},{"en":"This phrase suggests a delayed but important change in attitude.","zh":"這個短語暗示態度上延遲但重要的轉變。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":10},{"front":"astonishing animals","meaning":"令人驚嘆的動物","examples":[{"en":"Researchers are beginning to understand these astonishing animals more fully.","zh":"研究人員開始更全面地理解這些令人驚嘆的動物。"},{"en":"Astonishing animals are animals that surprise people because of their abilities or behaviour.","zh":"astonishing animals 指因能力或行為而令人驚訝的動物。"},{"en":"Octopuses are astonishing animals because they can solve problems and change colour.","zh":"章魚是令人驚嘆的動物，因為牠們能解難並改變顏色。"},{"en":"Seeing animals as astonishing can encourage people to protect them.","zh":"把動物視為令人驚嘆可以鼓勵人們保護牠們。"},{"en":"This phrase expresses wonder and respect.","zh":"這個短語表達驚奇和尊重。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":10},{"front":"populations have plummeted","meaning":"種群數量急劇下降","examples":[{"en":"Chimpanzee populations have plummeted in recent decades.","zh":"黑猩猩種群數量在近幾十年急劇下降。"},{"en":"Populations have plummeted means numbers have fallen very quickly and sharply.","zh":"populations have plummeted 指數量快速而大幅下降。"},{"en":"A shop’s sales may plummet if a new station diverts customers away.","zh":"如果新車站把顧客帶走，商店銷售可能急跌。"},{"en":"When wildlife populations plummet, conservation becomes urgent.","zh":"當野生動物種群急劇下降，保育就變得迫切。"},{"en":"This phrase is stronger than simply “have fallen”.","zh":"這個短語比 simply have fallen 更強。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":10},{"front":"continue to fall","meaning":"持續下降","examples":[{"en":"Chimpanzee populations continue to fall because of human activities.","zh":"黑猩猩種群因人類活動而持續下降。"},{"en":"Continue to fall means keep decreasing over time.","zh":"continue to fall 指隨時間繼續減少。"},{"en":"A student’s marks may continue to fall if she misses lessons and never reviews mistakes.","zh":"如果學生缺課又不檢討錯誤，成績可能持續下降。"},{"en":"Ongoing decline suggests the problem has not yet been solved.","zh":"持續下降暗示問題尚未解決。"},{"en":"This phrase is useful when a negative trend is still happening.","zh":"當負面趨勢仍在發生時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":10},{"front":"illegal trapping","meaning":"非法捕捉","examples":[{"en":"Illegal trapping has contributed to the decline of chimpanzee populations.","zh":"非法捕捉導致黑猩猩種群下降。"},{"en":"Illegal trapping means catching animals in ways that break the law.","zh":"illegal trapping 指以違法方式捕捉動物。"},{"en":"Rangers may remove illegal traps from forests to protect wildlife.","zh":"護林員可能移除森林中的非法陷阱，以保護野生動物。"},{"en":"Trapping can reduce animal numbers when adults are captured or killed.","zh":"當成年動物被捕或被殺，捕捉可以減少動物數量。"},{"en":"This phrase is common in conservation and wildlife protection.","zh":"這個短語常見於保育和野生動物保護。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":10},{"front":"logging","meaning":"伐木","examples":[{"en":"Logging has opened roads into forests.","zh":"伐木把道路開進森林。"},{"en":"Logging is the cutting down of trees for wood or commercial use.","zh":"logging 指為木材或商業用途砍伐樹木。"},{"en":"A forest may lose habitat if logging is not controlled carefully.","zh":"如果伐木沒有小心管制，森林可能失去棲息地。"},{"en":"Logging can create roads that make hunting and transport easier.","zh":"伐木可以造出道路，使狩獵和運輸更容易。"},{"en":"This word is common in environmental and conservation discussions.","zh":"這個詞常見於環境和保育討論。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":10},{"front":"bushmeat trade","meaning":"野味肉類貿易","examples":[{"en":"The bushmeat trade is a serious threat to chimpanzees.","zh":"野味肉類貿易是對黑猩猩的嚴重威脅。"},{"en":"The bushmeat trade is the buying and selling of meat from wild animals.","zh":"bushmeat trade 指買賣野生動物肉類。"},{"en":"In some regions, roads allow hunters to sell wild-animal meat to distant markets.","zh":"在某些地區，道路讓獵人把野生動物肉類賣到遠方市場。"},{"en":"This trade can reduce wildlife populations and damage ecosystems.","zh":"這種貿易可以減少野生動物數量並破壞生態系統。"},{"en":"This phrase is often used in conservation and wildlife-crime contexts.","zh":"這個短語常用於保育和野生動物犯罪語境。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":10},{"front":"the latter","meaning":"後者","examples":[{"en":"The latter is particularly alarming because roads now reach deep into forests.","zh":"後者特別令人憂慮，因為道路現在深入森林。"},{"en":"The latter means the second of two things just mentioned.","zh":"the latter 指剛提到的兩項事物中的第二項。"},{"en":"I considered walking and taking the bus; the latter is faster in heavy rain.","zh":"我考慮步行和乘巴士；在大雨中後者較快。"},{"en":"This phrase helps avoid repeating the second item in a pair.","zh":"這個短語幫助避免重複一對事物中的第二項。"},{"en":"Readers must look back to know what the latter refers to.","zh":"讀者必須回看前文，才知道 the latter 指甚麼。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":11},{"front":"particularly alarming","meaning":"特別令人憂慮","examples":[{"en":"The bushmeat trade is particularly alarming.","zh":"野味肉類貿易特別令人憂慮。"},{"en":"Particularly alarming means especially worrying or frightening.","zh":"particularly alarming 指特別令人擔心或害怕。"},{"en":"A sudden drop in school attendance is particularly alarming if many students are ill.","zh":"如果許多學生生病，學校出席率突然下降就特別令人憂慮。"},{"en":"Something becomes alarming when it suggests danger is growing quickly.","zh":"當某事暗示危險正在迅速增加，它就令人憂慮。"},{"en":"This phrase highlights the most worrying part of a problem.","zh":"這個短語突出問題中最令人擔心的部分。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":11},{"front":"drive roads into forests","meaning":"將道路伸延入森林","examples":[{"en":"Logging has driven roads into forests.","zh":"伐木把道路伸延入森林。"},{"en":"To drive roads into forests means to create or push roads deep into forest areas.","zh":"drive roads into forests 指把道路建造或推進到森林深處。"},{"en":"Mining companies may drive roads into mountains to reach work sites.","zh":"採礦公司可能把道路伸延入山區，以到達工作地點。"},{"en":"Roads can open remote habitats to hunters, vehicles, and markets.","zh":"道路可以讓獵人、車輛和市場進入偏遠棲息地。"},{"en":"This phrase shows how human development penetrates natural areas.","zh":"這個短語顯示人類發展如何進入自然地區。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":11},{"front":"transport wild-animal meat","meaning":"運送野生動物肉類","examples":[{"en":"The roads are used to transport wild-animal meat to consumers.","zh":"這些道路被用來把野生動物肉類運送給消費者。"},{"en":"To transport wild-animal meat means to carry meat from wild animals from one place to another.","zh":"transport wild-animal meat 指把野生動物肉類從一地運到另一地。"},{"en":"Trucks may transport food from farms to city markets.","zh":"貨車可能把食物從農場運送到城市市場。"},{"en":"When roads make transport easier, illegal trade can spread farther.","zh":"當道路令運輸更容易，非法貿易可以傳得更遠。"},{"en":"This phrase links infrastructure with the movement of bushmeat.","zh":"這個短語把基建與野味肉類流動連接起來。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":11},{"front":"as far away as","meaning":"遠至","examples":[{"en":"Chimpanzee meat may be transported to consumers as far away as Europe.","zh":"黑猩猩肉可能被運送給遠至歐洲的消費者。"},{"en":"As far away as means reaching a surprisingly distant place.","zh":"as far away as 指到達令人驚訝的遙遠地方。"},{"en":"A small local product may be sold as far away as another continent.","zh":"小型本地產品可能賣到遠至另一個大洲。"},{"en":"This phrase emphasises distance and the wide reach of an activity.","zh":"這個短語強調距離和某活動的廣泛範圍。"},{"en":"It is useful when showing that something travels farther than expected.","zh":"當顯示某物去得比預期更遠時，它很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":11},{"front":"such destruction","meaning":"這種破壞","examples":[{"en":"Such destruction threatens both chimpanzees and their cultures.","zh":"這種破壞威脅黑猩猩及其文化。"},{"en":"Such destruction refers to the damaging actions just described.","zh":"such destruction 指剛才描述的破壞行動。"},{"en":"After a fire destroys homes and schools, such destruction affects the whole community.","zh":"火災摧毀房屋和學校後，這種破壞會影響整個社區。"},{"en":"Destruction can harm not only physical life but also memory and tradition.","zh":"破壞不但可以傷害實體生命，也可以傷害記憶和傳統。"},{"en":"This phrase connects previous damage with its consequences.","zh":"這個短語把前文破壞與其後果連接起來。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":11},{"front":"threaten not only…but also…","meaning":"不但威脅……亦威脅……","examples":[{"en":"Such destruction threatens not only the animals but also their cultures.","zh":"這種破壞不但威脅動物，亦威脅牠們的文化。"},{"en":"Threaten not only…but also… means put two different things at risk.","zh":"threaten not only…but also… 指令兩種不同事物面臨風險。"},{"en":"Pollution threatens not only rivers but also the people who depend on them.","zh":"污染不但威脅河流，亦威脅依賴河流的人。"},{"en":"This structure expands the danger from one obvious target to another less obvious one.","zh":"這個結構把危險由一個明顯目標擴展到另一個較不明顯目標。"},{"en":"It is useful when a problem has more than one serious consequence.","zh":"當問題有多於一個嚴重後果時，它很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":11},{"front":"a host of","meaning":"大量；許多","examples":[{"en":"The destruction threatens a host of different ape cultures.","zh":"這種破壞威脅大量不同猿類文化。"},{"en":"A host of means a large number of many different things.","zh":"a host of 指大量且多種不同的事物。"},{"en":"A new library can offer a host of resources, from books to study rooms.","zh":"新圖書館可以提供大量資源，從書籍到自修室都有。"},{"en":"This phrase emphasises that the number is large and varied.","zh":"這個短語強調數量大而且種類多。"},{"en":"It is useful when a simple word like many feels too weak.","zh":"當 many 感覺不夠有力時，它很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":11},{"front":"fascinatingly different","meaning":"迷人地各不相同的","examples":[{"en":"The destruction threatens fascinatingly different ape cultures.","zh":"這種破壞威脅迷人地各不相同的猿類文化。"},{"en":"Fascinatingly different means different in a way that is interesting and worth studying.","zh":"fascinatingly different 指差異令人感興趣並值得研究。"},{"en":"Two neighbourhoods may be fascinatingly different in food, language, and street life.","zh":"兩個社區在食物、語言和街頭生活上可能迷人地各不相同。"},{"en":"Interesting differences can make people value diversity more deeply.","zh":"有趣差異可以令人更深入重視多樣性。"},{"en":"This phrase is positive and appreciative.","zh":"這個短語帶正面和欣賞意味。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":11},{"front":"ape cultures","meaning":"猿類文化","examples":[{"en":"The loss of chimpanzees also means the loss of ape cultures.","zh":"失去黑猩猩也意味着失去猿類文化。"},{"en":"Ape cultures are learned traditions or behaviours found in ape communities.","zh":"ape cultures 指猿類群體中的學習傳統或行為。"},{"en":"One ape group may use tools or gestures differently from another group.","zh":"一個猿類群體可能與另一群體以不同方式使用工具或手勢。"},{"en":"If a group disappears, its local traditions may disappear with it.","zh":"如果一個群體消失，其地方傳統也可能隨之消失。"},{"en":"This phrase extends the idea of culture beyond humans.","zh":"這個短語把文化概念延伸到人類以外。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":11},{"front":"cultural richness","meaning":"文化豐富性","examples":[{"en":"The cultural richness of apes may contribute to their salvation.","zh":"猿類的文化豐富性可能有助於牠們的保護。"},{"en":"Cultural richness means the depth and variety of traditions, behaviours, or meanings in a group.","zh":"cultural richness 指一個群體傳統、行為或意義的深度和多樣性。"},{"en":"A city’s cultural richness may appear in its food, dialects, festivals, and music.","zh":"一個城市的文化豐富性可以在食物、方言、節日和音樂中出現。"},{"en":"When people recognise richness, they may feel a stronger reason to protect it.","zh":"當人們認識到豐富性，他們可能有更強理由去保護它。"},{"en":"This phrase links diversity with value.","zh":"這個短語把多樣性與價值連接起來。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":11},{"front":"contribute to","meaning":"促成；有助於","examples":[{"en":"The cultural richness of apes may contribute to their protection.","zh":"猿類的文化豐富性可能有助於牠們的保護。"},{"en":"To contribute to something means to help cause or support it.","zh":"contribute to something 指幫助造成或支持某事。"},{"en":"Regular reading can contribute to better writing.","zh":"定期閱讀可以有助於更好的寫作。"},{"en":"Small actions can contribute to a larger result over time.","zh":"小行動可以隨時間促成更大的結果。"},{"en":"This phrase is useful when one factor helps produce an outcome.","zh":"當某因素幫助產生結果時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":12},{"front":"salvation","meaning":"拯救；保護","examples":[{"en":"The cultural richness of apes may contribute to their salvation.","zh":"猿類的文化豐富性可能有助於牠們的拯救。"},{"en":"Salvation means rescue, protection, or being saved from danger.","zh":"salvation 指救援、保護或免於危險。"},{"en":"A community garden may become the salvation of a neglected neighbourhood.","zh":"社區花園可能成為被忽視社區的救星。"},{"en":"If people see an animal as valuable, conservation may become its salvation.","zh":"如果人們視動物為有價值，保育可能成為牠的拯救方式。"},{"en":"This word is strong and often suggests serious danger followed by rescue.","zh":"這個詞語氣強，常暗示嚴重危險後的拯救。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":12},{"front":"conservation efforts","meaning":"保育工作","examples":[{"en":"Conservation efforts have changed the attitudes of some local people.","zh":"保育工作改變了一些本地居民的態度。"},{"en":"Conservation efforts are actions taken to protect animals, plants, habitats, or natural resources.","zh":"conservation efforts 指為保護動物、植物、棲息地或自然資源而採取的行動。"},{"en":"A school may join conservation efforts by planting trees and reducing waste.","zh":"學校可以透過植樹和減廢參與保育工作。"},{"en":"Effective conservation can change behaviour by helping people understand what is at risk.","zh":"有效保育可以透過幫助人們理解風險而改變行為。"},{"en":"This phrase is common in environmental protection.","zh":"這個短語常見於環境保護。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":12},{"front":"alter the attitudes of","meaning":"改變……的態度","examples":[{"en":"Conservation efforts have altered the attitudes of some local people.","zh":"保育工作改變了一些本地居民的態度。"},{"en":"To alter the attitudes of people means to change how they think or feel about something.","zh":"alter the attitudes of people 指改變人們對某事的想法或感受。"},{"en":"A visit to a care home may alter students’ attitudes towards ageing.","zh":"到訪護老院可能改變學生對老年的態度。"},{"en":"Attitudes often change when people see evidence or personal stories.","zh":"當人們看見證據或個人故事，態度常會改變。"},{"en":"This phrase is useful when education or experience changes beliefs.","zh":"當教育或經驗改變信念時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":12},{"front":"local people","meaning":"本地居民","examples":[{"en":"Some local people changed their views after watching videos of chimpanzees.","zh":"一些本地居民觀看黑猩猩影片後改變了看法。"},{"en":"Local people are residents who live in or near a particular place.","zh":"local people 指住在某特定地方或附近的居民。"},{"en":"A park project should ask local people what they need before construction begins.","zh":"公園項目在施工前應詢問本地居民需要甚麼。"},{"en":"Conservation is more likely to work when local people understand and support it.","zh":"當本地居民理解並支持保育，保育更可能成功。"},{"en":"This phrase focuses on the community closest to an issue.","zh":"這個短語聚焦最接近議題的社區。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":12},{"front":"show videotapes","meaning":"播放錄影片段","examples":[{"en":"Several organisations showed videotapes about chimpanzee intelligence.","zh":"幾個組織播放關於黑猩猩智能的錄影片段。"},{"en":"To show videotapes means to play recorded video material for an audience.","zh":"show videotapes 指為觀眾播放錄製好的影像材料。"},{"en":"A teacher may show videotapes of experiments before students enter the lab.","zh":"老師可能在學生進入實驗室前播放實驗錄影片段。"},{"en":"Video can change attitudes because people see behaviour directly.","zh":"影片可以改變態度，因為人們直接看見行為。"},{"en":"This phrase is slightly old-fashioned but clear for recorded video viewing.","zh":"這個短語略舊式，但清楚表示觀看錄影。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":12},{"front":"cognitive prowess","meaning":"認知能力","examples":[{"en":"The videotapes illustrated the cognitive prowess of chimpanzees.","zh":"錄影片段展示了黑猩猩的認知能力。"},{"en":"Cognitive prowess means strong mental ability, such as learning, memory, or problem-solving.","zh":"cognitive prowess 指強大的心智能力，例如學習、記憶或解難。"},{"en":"A chess player may show cognitive prowess by planning several moves ahead.","zh":"棋手能預先計劃幾步，可能顯示認知能力。"},{"en":"Seeing cognitive ability in animals can change how people value them.","zh":"看見動物的認知能力可以改變人們對牠們的重視。"},{"en":"This phrase is formal and strongly praises mental skill.","zh":"這個短語較正式，強烈讚揚心智能力。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":12},{"front":"was heard to exclaim","meaning":"被聽到驚呼","examples":[{"en":"One Zairian viewer was heard to exclaim that the ape was like him.","zh":"有人聽到一位扎伊爾觀眾驚呼那隻猿像他。"},{"en":"Was heard to exclaim means someone was heard saying something suddenly and emotionally.","zh":"was heard to exclaim 指有人聽到某人突然且情緒化地說出某話。"},{"en":"A student was heard to exclaim with joy when her result was announced.","zh":"成績公布時，有人聽到學生高興地驚呼。"},{"en":"Exclamations often show surprise, excitement, fear, or realisation.","zh":"驚呼常顯示驚訝、興奮、害怕或頓悟。"},{"en":"This phrase is formal and reports a spoken reaction.","zh":"這個短語較正式，用來報告口頭反應。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":12},{"front":"so like me","meaning":"與我如此相似","examples":[{"en":"The viewer said that the ape was so like him.","zh":"觀眾說那隻猿與他如此相似。"},{"en":"So like me means extremely similar to me in behaviour, feeling, or appearance.","zh":"so like me 指在行為、感受或外貌上與我非常相似。"},{"en":"A child may say a story character is so like her because they both worry before exams.","zh":"孩子可能說故事人物與她如此相似，因為兩者都在考試前焦慮。"},{"en":"Recognising similarity can create empathy and change behaviour.","zh":"認出相似之處可以產生同理心並改變行為。"},{"en":"This phrase expresses personal identification.","zh":"這個短語表達個人認同。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":12},{"front":"can no longer","meaning":"再也不能","examples":[{"en":"The viewer said he could no longer eat the ape.","zh":"觀眾說他再也不能吃那隻猿。"},{"en":"Can no longer means cannot continue doing something anymore.","zh":"can no longer 指不能再繼續做某事。"},{"en":"A student who understands animal suffering may no longer want to support cruel shows.","zh":"理解動物痛苦的學生可能再也不想支持殘酷表演。"},{"en":"New knowledge can make an old habit feel impossible to continue.","zh":"新知識可以令舊習慣感覺無法再繼續。"},{"en":"This phrase shows a change from possible before to impossible now.","zh":"這個短語顯示從以前可以到現在不再可以的轉變。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":12},{"front":"an international team of","meaning":"一個國際……團隊","examples":[{"en":"An international team of chimpanzee experts conducted a major survey.","zh":"一個國際黑猩猩專家團隊進行了一項大型調查。"},{"en":"An international team of people is a group whose members come from different countries.","zh":"international team of people 指成員來自不同國家的團隊。"},{"en":"An international team of doctors may respond to a disease outbreak.","zh":"一個國際醫生團隊可能應對疾病爆發。"},{"en":"International teams can combine knowledge from different regions and traditions.","zh":"國際團隊可以結合不同地區和傳統的知識。"},{"en":"This phrase highlights cooperation across borders.","zh":"這個短語突出跨國合作。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":12},{"front":"chimpanzee experts","meaning":"黑猩猩專家","examples":[{"en":"Chimpanzee experts worked together to study cultural variation.","zh":"黑猩猩專家合作研究文化差異。"},{"en":"Chimpanzee experts are specialists who study chimpanzee behaviour, biology, or conservation.","zh":"chimpanzee experts 指研究黑猩猩行為、生物或保育的專家。"},{"en":"A zoo may invite chimpanzee experts to advise on animal care.","zh":"動物園可能邀請黑猩猩專家就動物護理提供建議。"},{"en":"Experts provide reliable knowledge because they have long experience with the species.","zh":"專家因長期接觸該物種而提供可靠知識。"},{"en":"This phrase identifies people with specialist knowledge of chimpanzees.","zh":"這個短語指出具黑猩猩專門知識的人。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":13},{"front":"comprehensive survey","meaning":"全面調查","examples":[{"en":"The team performed the most comprehensive survey of chimpanzees ever attempted.","zh":"該團隊進行了歷來嘗試過最全面的黑猩猩調查。"},{"en":"A comprehensive survey is a detailed study that covers many cases, places, or questions.","zh":"comprehensive survey 指涵蓋許多個案、地點或問題的詳細研究。"},{"en":"A school may conduct a comprehensive survey to understand student stress.","zh":"學校可能進行全面調查，以了解學生壓力。"},{"en":"A broad survey can reveal patterns that small studies miss.","zh":"廣泛調查可以揭示小型研究錯過的模式。"},{"en":"This phrase suggests wide coverage and serious research.","zh":"這個短語暗示涵蓋範圍廣且研究認真。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":13},{"front":"ever attempted","meaning":"歷來嘗試過的","examples":[{"en":"This was the most comprehensive survey of chimpanzees ever attempted.","zh":"這是歷來嘗試過最全面的黑猩猩調查。"},{"en":"Ever attempted means tried at any time before now.","zh":"ever attempted 指到目前為止曾嘗試過的。"},{"en":"The project was the largest school survey ever attempted by the district.","zh":"該項目是該區歷來嘗試過最大型的學校調查。"},{"en":"This phrase emphasises historical scale or ambition.","zh":"這個短語強調歷史規模或企圖。"},{"en":"It is useful when comparing a current effort with all earlier efforts.","zh":"比較當前努力與所有早前努力時，它很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":13},{"front":"delve into","meaning":"深入研究","examples":[{"en":"Scientists have been delving into chimpanzee culture for several decades.","zh":"科學家數十年來一直深入研究黑猩猩文化。"},{"en":"To delve into something means to study or investigate it deeply.","zh":"delve into something 指深入學習或調查某事。"},{"en":"A journalist may delve into old records to understand a corruption case.","zh":"記者可能深入研究舊記錄，以了解貪污案件。"},{"en":"Deep investigation can reveal details that surface reading misses.","zh":"深入調查可以揭示表面閱讀錯過的細節。"},{"en":"This phrase is useful when research goes beyond a quick look.","zh":"當研究不只是快速看一眼時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":13},{"front":"for several decades","meaning":"數十年來","examples":[{"en":"Scientists have studied chimpanzee culture for several decades.","zh":"科學家數十年來研究黑猩猩文化。"},{"en":"For several decades means for many periods of ten years.","zh":"for several decades 指持續幾個十年。"},{"en":"A teacher may work in the same school for several decades.","zh":"老師可能在同一間學校工作數十年。"},{"en":"Long periods of study allow researchers to see change across generations.","zh":"長期研究讓研究人員看見跨世代變化。"},{"en":"This phrase gives a broad sense of long duration.","zh":"這個短語提供長時間的廣泛概念。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":13},{"front":"contain a fatal defect","meaning":"存在致命缺陷","examples":[{"en":"Some earlier studies contained a fatal defect.","zh":"一些早期研究存在致命缺陷。"},{"en":"To contain a fatal defect means to have a serious flaw that can ruin the value of the work.","zh":"contain a fatal defect 指有一個會破壞作品價值的嚴重缺點。"},{"en":"A research report contains a fatal defect if it ignores the main group being studied.","zh":"如果研究報告忽視主要研究群體，它就存在致命缺陷。"},{"en":"A serious defect can make conclusions unreliable even when the effort was large.","zh":"即使投入很大，嚴重缺陷也可以令結論不可靠。"},{"en":"This phrase is strong and used for major methodological problems.","zh":"這個短語語氣強，用於重大方法問題。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":13},{"front":"attempt to document","meaning":"嘗試記錄","examples":[{"en":"Researchers have attempted to document cultural diversity among chimpanzees.","zh":"研究人員曾嘗試記錄黑猩猩之間的文化多樣性。"},{"en":"To attempt to document something means to try to record it carefully.","zh":"attempt to document something 指嘗試仔細記錄某事。"},{"en":"A school may attempt to document changes in students’ reading habits.","zh":"學校可能嘗試記錄學生閱讀習慣的變化。"},{"en":"Documentation helps turn observations into information that others can check.","zh":"記錄有助把觀察變成他人可以檢查的資訊。"},{"en":"This phrase is useful when research is trying to build a record.","zh":"當研究試圖建立記錄時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":13},{"front":"cultural diversity","meaning":"文化多樣性","examples":[{"en":"Earlier research tried to document cultural diversity among chimpanzees.","zh":"早期研究嘗試記錄黑猩猩之間的文化多樣性。"},{"en":"Cultural diversity means the presence of many different traditions, behaviours, or ways of life.","zh":"cultural diversity 指存在許多不同傳統、行為或生活方式。"},{"en":"A city shows cultural diversity through food, languages, festivals, and beliefs.","zh":"一個城市透過食物、語言、節日和信念顯示文化多樣性。"},{"en":"Diversity matters because it shows that not all groups behave in the same way.","zh":"多樣性很重要，因為它顯示並非所有群體都以同樣方式行事。"},{"en":"This phrase is useful when comparing differences across communities.","zh":"比較不同社群之間的差異時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":13},{"front":"solely rely upon","meaning":"只依賴","examples":[{"en":"Many studies solely relied upon officially published accounts.","zh":"許多研究只依賴正式發表的記錄。"},{"en":"To solely rely upon something means to depend only on that source or method.","zh":"solely rely upon something 指只依靠某一來源或方法。"},{"en":"A student should not solely rely upon one website for an important project.","zh":"學生不應在重要項目中只依賴一個網站。"},{"en":"Depending on only one source can cause missing information or bias.","zh":"只依賴一個來源可能造成資料缺失或偏見。"},{"en":"This phrase is useful when criticising limited evidence.","zh":"批評證據有限時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":13},{"front":"officially published accounts","meaning":"正式發表的記錄","examples":[{"en":"Researchers often relied on officially published accounts of chimpanzee behaviour.","zh":"研究人員常依賴正式發表的黑猩猩行為記錄。"},{"en":"Officially published accounts are formal reports or records made available to the public.","zh":"officially published accounts 指正式向公眾發布的報告或記錄。"},{"en":"A historian may use officially published accounts to study past events.","zh":"歷史學家可能使用正式發表的記錄來研究過去事件。"},{"en":"Published accounts can be useful, but they may omit details not considered important at the time.","zh":"發表記錄可以很有用，但可能省略當時不被視為重要的細節。"},{"en":"This phrase is common in research and documentation.","zh":"這個短語常見於研究和文獻記錄。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":13},{"front":"research site","meaning":"研究地點","examples":[{"en":"Reports described behaviours at each research site.","zh":"報告描述每個研究地點的行為。"},{"en":"A research site is a place where data or observations are collected for a study.","zh":"research site 指為研究收集數據或觀察的地方。"},{"en":"A hospital can be a research site for a study on patient care.","zh":"醫院可以是病人護理研究的研究地點。"},{"en":"Comparing research sites helps researchers see whether patterns are local or widespread.","zh":"比較研究地點幫助研究人員判斷模式是地方性還是廣泛存在。"},{"en":"This phrase identifies the location where research happens.","zh":"這個短語指出研究發生的地點。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":13},{"front":"this approach","meaning":"這種方法","examples":[{"en":"This approach may neglect a good deal of cultural variation.","zh":"這種方法可能忽略大量文化差異。"},{"en":"This approach means this method or way of dealing with a task.","zh":"this approach 指這種處理任務的方法或方式。"},{"en":"A teacher may change her approach if students do not understand the lesson.","zh":"如果學生不理解課堂，老師可能改變她的方法。"},{"en":"An approach can solve some problems but create others.","zh":"一種方法可以解決某些問題，但也可能造成其他問題。"},{"en":"This phrase is useful when evaluating a method.","zh":"評估方法時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":14},{"front":"neglect a good deal of","meaning":"忽略大量……","examples":[{"en":"The approach probably neglects a good deal of cultural variation.","zh":"這種方法可能忽略大量文化差異。"},{"en":"To neglect a good deal of something means to ignore or miss a large amount of it.","zh":"neglect a good deal of something 指忽視或錯過大量某事物。"},{"en":"A study of student life may neglect a good deal of stress if it asks only about grades.","zh":"如果學生生活研究只問成績，它可能忽略大量壓力。"},{"en":"Missing a large part of the evidence can lead to weak conclusions.","zh":"錯過大量證據可以導致薄弱結論。"},{"en":"This phrase is useful when a method leaves out too much.","zh":"當方法漏掉太多內容時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":14},{"front":"cultural variation","meaning":"文化差異","examples":[{"en":"Published accounts may miss cultural variation among chimpanzees.","zh":"發表的記錄可能錯過黑猩猩之間的文化差異。"},{"en":"Cultural variation means differences in learned behaviours or traditions between groups.","zh":"cultural variation 指不同群體在學習行為或傳統上的差異。"},{"en":"Regional food habits show cultural variation within one country.","zh":"地區飲食習慣顯示一個國家內部的文化差異。"},{"en":"Variation helps researchers understand that a species or society is not uniform.","zh":"差異幫助研究人員理解一個物種或社會並非完全一致。"},{"en":"This phrase is useful when comparing different communities.","zh":"比較不同社群時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":14},{"front":"for three reasons","meaning":"基於三個原因","examples":[{"en":"The approach is problematic for three reasons.","zh":"這種方法基於三個原因而有問題。"},{"en":"For three reasons means there are three separate explanations for a point.","zh":"for three reasons 指一個觀點有三個分開的解釋。"},{"en":"A student may choose a course for three reasons: cost, interest, and timetable.","zh":"學生可能基於三個原因選擇課程：費用、興趣和時間表。"},{"en":"Numbering reasons helps readers follow an argument clearly.","zh":"把原因編號有助讀者清楚跟隨論證。"},{"en":"This phrase is useful when organising explanation.","zh":"組織解釋時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":14},{"front":"publish an extensive list of","meaning":"發表一份詳盡的……清單","examples":[{"en":"Scientists usually do not publish an extensive list of behaviours they do not see.","zh":"科學家通常不會發表一份詳盡清單，列出他們沒有看見的行為。"},{"en":"To publish an extensive list of something means to make a long and detailed list publicly available.","zh":"publish an extensive list of something 指公開一份長而詳細的清單。"},{"en":"A school may publish an extensive list of reading materials for summer study.","zh":"學校可能為暑期學習發表一份詳盡閱讀材料清單。"},{"en":"Long lists can be useful when researchers need to know both what appears and what does not.","zh":"當研究人員需要知道甚麼出現和甚麼沒有出現時，長清單很有用。"},{"en":"This phrase is formal and common in research or official communication.","zh":"這個短語較正式，常見於研究或官方溝通。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":14},{"front":"particular location","meaning":"某一特定地點","examples":[{"en":"Some behaviours may be absent at a particular location.","zh":"有些行為可能在某一特定地點不存在。"},{"en":"A particular location is one specific place.","zh":"particular location 指某一個具體地方。"},{"en":"A shop may sell well in one particular location because many students pass by.","zh":"商店可能因為很多學生經過而在某一特定地點生意很好。"},{"en":"Location matters because behaviour or demand can change from place to place.","zh":"地點很重要，因為行為或需求可以因地而異。"},{"en":"This phrase is useful when narrowing a claim to one site.","zh":"把說法收窄到某一地點時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":14},{"front":"the very information","meaning":"正正是所需的資料","examples":[{"en":"The missing observations are the very information researchers need.","zh":"缺失的觀察正正是研究人員所需的資料。"},{"en":"The very information means exactly the information being referred to as important.","zh":"the very information 指正是所提到的重要資料。"},{"en":"A student’s mistakes may be the very information a teacher needs to plan revision.","zh":"學生的錯誤可能正正是老師規劃溫習所需的資料。"},{"en":"Sometimes missing data is not a small problem but exactly what is needed for analysis.","zh":"有時缺失數據不是小問題，而正是分析所需要的內容。"},{"en":"This phrase strongly emphasises importance.","zh":"這個短語強烈強調重要性。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":14},{"front":"were and were not observed","meaning":"曾被及未被觀察到","examples":[{"en":"Researchers need to know which behaviours were and were not observed.","zh":"研究人員需要知道哪些行為曾被及未被觀察到。"},{"en":"Were and were not observed means did appear in observation and did not appear in observation.","zh":"were and were not observed 指在觀察中出現和沒有出現。"},{"en":"A teacher may record which errors were and were not observed in students’ writing.","zh":"老師可能記錄學生寫作中哪些錯誤曾被及未被觀察到。"},{"en":"Knowing absences as well as presences helps researchers compare sites fairly.","zh":"知道存在與不存在同樣有助研究人員公平比較地點。"},{"en":"This phrase is useful in systematic data collection.","zh":"這個短語適用於系統化數據收集。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":14},{"front":"reports describing","meaning":"描述……的報告","examples":[{"en":"Many reports describing chimpanzee behaviours lack important details.","zh":"許多描述黑猩猩行為的報告缺乏重要細節。"},{"en":"Reports describing something are written records that explain or present that subject.","zh":"reports describing something 指解釋或呈現某主題的書面記錄。"},{"en":"Reports describing student attendance may include dates, reasons, and patterns.","zh":"描述學生出席情況的報告可能包括日期、原因和模式。"},{"en":"If reports lack detail, readers may not understand how common an event is.","zh":"如果報告缺乏細節，讀者可能不知道事件有多常見。"},{"en":"This phrase is useful when discussing research documents.","zh":"討論研究文件時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":14},{"front":"without expressing how common they are","meaning":"沒有說明其常見程度","examples":[{"en":"Some reports describe behaviours without expressing how common they are.","zh":"有些報告描述行為，卻沒有說明其常見程度。"},{"en":"Without expressing how common they are means without saying whether they happen often or rarely.","zh":"without expressing how common they are 指沒有說明它們經常還是很少發生。"},{"en":"A report may mention student lateness without expressing how common it is.","zh":"報告可能提到學生遲到，卻沒有說明其常見程度。"},{"en":"Frequency matters because a rare event may not be a routine pattern.","zh":"頻率很重要，因為罕見事件未必是常規模式。"},{"en":"This phrase is useful when criticising incomplete reporting.","zh":"批評報告不完整時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":14},{"front":"determine whether","meaning":"判斷是否","examples":[{"en":"Researchers cannot determine whether an action is routine without more information.","zh":"沒有更多資料，研究人員不能判斷某行為是否屬常規。"},{"en":"To determine whether means to find out if something is true or not.","zh":"determine whether 指查明某事是否真實。"},{"en":"A doctor may run tests to determine whether an infection is present.","zh":"醫生可能做測試，以判斷是否有感染。"},{"en":"Better evidence helps people decide accurately rather than guess.","zh":"更好的證據幫助人們準確判斷，而不是猜測。"},{"en":"This phrase is common in research, exams, and decision-making.","zh":"這個短語常見於研究、考試和決策。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":14},{"front":"a particular action","meaning":"某一特定行為","examples":[{"en":"A particular action may be temporary or routine.","zh":"某一特定行為可能是短暫的，也可能是常規的。"},{"en":"A particular action is one specific thing that someone or something does.","zh":"particular action 指某人或某物做的一個具體行動。"},{"en":"A teacher may focus on a particular action, such as raising a hand before speaking.","zh":"老師可能聚焦某一特定行為，例如發言前舉手。"},{"en":"Looking at one action carefully helps researchers decide what it means.","zh":"仔細觀察一個行動幫助研究人員判斷它的意思。"},{"en":"This phrase narrows attention to a specific behaviour.","zh":"這個短語把注意力收窄到具體行為。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":15},{"front":"transient phenomenon","meaning":"短暫現象","examples":[{"en":"A rare behaviour may be only a transient phenomenon.","zh":"罕見行為可能只是一個短暫現象。"},{"en":"A transient phenomenon is something that appears briefly and does not last.","zh":"transient phenomenon 指短暫出現且不持久的事情。"},{"en":"A sudden fashion in school may be a transient phenomenon if students forget it after a week.","zh":"如果學生一星期後就忘記某種校園潮流，它可能只是短暫現象。"},{"en":"Researchers must distinguish temporary events from stable patterns.","zh":"研究人員必須區分暫時事件和穩定模式。"},{"en":"This phrase is formal and useful in scientific explanation.","zh":"這個短語較正式，適用於科學解釋。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":15},{"front":"routine event","meaning":"常規事件","examples":[{"en":"A routine event may be considered part of chimpanzee culture.","zh":"常規事件可能被視為黑猩猩文化的一部分。"},{"en":"A routine event is something that happens regularly, not just once.","zh":"routine event 指定期發生的事情，而不是只發生一次。"},{"en":"Morning assembly is a routine event in many schools.","zh":"早會是許多學校的常規事件。"},{"en":"Regular repetition can make an action part of a group’s normal life.","zh":"定期重複可以令一個行動成為群體正常生活的一部分。"},{"en":"This phrase contrasts with rare or temporary events.","zh":"這個短語與罕見或暫時事件形成對比。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":15},{"front":"be considered part of","meaning":"被視為……的一部分","examples":[{"en":"A repeated behaviour may be considered part of chimpanzee culture.","zh":"重複出現的行為可能被視為黑猩猩文化的一部分。"},{"en":"To be considered part of something means to be regarded as belonging to it.","zh":"be considered part of something 指被認為屬於某事物。"},{"en":"Daily reading may be considered part of a student’s study routine.","zh":"每天閱讀可能被視為學生學習常規的一部分。"},{"en":"If a behaviour is repeated and shared, researchers may classify it as part of culture.","zh":"如果行為被重複且共享，研究人員可能把它分類為文化的一部分。"},{"en":"This phrase is useful when explaining classification.","zh":"解釋分類時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":15},{"front":"potentially significant","meaning":"可能具有重要意義的","examples":[{"en":"Potentially significant behaviours often require detailed descriptions.","zh":"可能具有重要意義的行為通常需要詳細描述。"},{"en":"Potentially significant means possibly important, though not yet fully proven.","zh":"potentially significant 指可能重要，但尚未完全證明。"},{"en":"A small change in a patient’s symptoms may be potentially significant to a doctor.","zh":"病人症狀的小改變對醫生而言可能具有重要意義。"},{"en":"Researchers pay attention to potentially significant details because they may explain larger patterns.","zh":"研究人員重視可能重要的細節，因為它們可能解釋更大模式。"},{"en":"This phrase is cautious and formal.","zh":"這個短語較謹慎而正式。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":15},{"front":"lack sufficient detail","meaning":"缺乏足夠細節","examples":[{"en":"Researchers’ descriptions often lack sufficient detail.","zh":"研究人員的描述常缺乏足夠細節。"},{"en":"To lack sufficient detail means not to include enough information.","zh":"lack sufficient detail 指沒有包括足夠資料。"},{"en":"A student’s answer may lack sufficient detail if it gives a conclusion without examples.","zh":"如果學生答案只給結論而沒有例子，可能缺乏足夠細節。"},{"en":"Without enough detail, readers cannot judge the situation accurately.","zh":"沒有足夠細節，讀者無法準確判斷情況。"},{"en":"This phrase is useful when criticising vague writing or reporting.","zh":"批評模糊寫作或報告時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":15},{"front":"report the presence or absence of","meaning":"報告……是否存在","examples":[{"en":"Scientists need enough detail to report the presence or absence of activities.","zh":"科學家需要足夠細節來報告活動是否存在。"},{"en":"To report the presence or absence of something means to state whether it exists or does not exist.","zh":"report the presence or absence of something 指說明某物存在或不存在。"},{"en":"A doctor’s report may record the presence or absence of fever.","zh":"醫生報告可能記錄是否有發燒。"},{"en":"Knowing both presence and absence helps people make accurate comparisons.","zh":"知道存在和不存在都有助人們作出準確比較。"},{"en":"This phrase is common in science, medicine, and data collection.","zh":"這個短語常見於科學、醫學和數據收集。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":15},{"front":"tackle these problems","meaning":"處理這些問題","examples":[{"en":"The researchers developed a new approach to tackle these problems.","zh":"研究人員發展了一種新方法來處理這些問題。"},{"en":"To tackle these problems means to deal with them directly and try to solve them.","zh":"tackle these problems 指直接處理並嘗試解決這些問題。"},{"en":"A school may tackle bullying by improving supervision and teaching respect.","zh":"學校可以透過加強監督和教導尊重來處理欺凌問題。"},{"en":"Problems become easier to solve when their causes are clearly identified.","zh":"當問題原因被清楚找出，問題會較容易解決。"},{"en":"This phrase is practical and action-focused.","zh":"這個短語實用且聚焦行動。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":15},{"front":"take a new approach","meaning":"採取新的方法","examples":[{"en":"The researchers decided to take a new approach.","zh":"研究人員決定採取新的方法。"},{"en":"To take a new approach means to use a different method from before.","zh":"take a new approach 指使用不同於以往的方法。"},{"en":"A teacher may take a new approach if students are bored by memorisation.","zh":"如果學生對死記感到沉悶，老師可能採取新的方法。"},{"en":"New methods can solve problems that old methods failed to handle.","zh":"新方法可以解決舊方法未能處理的問題。"},{"en":"This phrase is useful when changing strategy.","zh":"改變策略時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":15},{"front":"field researchers","meaning":"野外研究人員","examples":[{"en":"Field researchers listed behaviours that might be local traditions.","zh":"野外研究人員列出可能屬於地方傳統的行為。"},{"en":"Field researchers are researchers who collect data in real-world locations rather than only in offices or laboratories.","zh":"field researchers 指在真實地點收集數據，而不是只在辦公室或實驗室工作的研究人員。"},{"en":"Field researchers may spend months in forests, schools, or communities observing behaviour.","zh":"野外研究人員可能在森林、學校或社區花數月觀察行為。"},{"en":"Their direct experience helps them notice details not found in published reports.","zh":"他們的直接經驗幫助他們注意到發表報告中沒有的細節。"},{"en":"This phrase is common in science and social research.","zh":"這個短語常見於科學和社會研究。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":15},{"front":"local traditions","meaning":"地方傳統","examples":[{"en":"The team asked researchers to list suspected local traditions.","zh":"團隊要求研究人員列出被懷疑屬於地方傳統的行為。"},{"en":"Local traditions are customs or behaviours found in a particular community or place.","zh":"local traditions 指在特定社區或地方中存在的習俗或行為。"},{"en":"A village festival can be a local tradition passed down by older residents.","zh":"村莊節日可以是由年長居民傳下來的地方傳統。"},{"en":"Local traditions may disappear if younger members stop learning them.","zh":"如果年輕成員停止學習，地方傳統可能消失。"},{"en":"This phrase is useful when discussing culture tied to a specific place.","zh":"討論與特定地方相關的文化時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":15},{"front":"with this information","meaning":"憑藉這些資料","examples":[{"en":"With this information, the team assembled a comprehensive list.","zh":"憑藉這些資料，團隊整理出一份全面清單。"},{"en":"With this information means using the information just mentioned.","zh":"with this information 指使用剛提到的資料。"},{"en":"With this information, a student can choose the right course more confidently.","zh":"憑藉這些資料，學生可以更有信心地選擇合適課程。"},{"en":"Good information helps people make better lists, plans, or decisions.","zh":"好資料幫助人們制定更好的清單、計劃或決定。"},{"en":"This phrase links data to the next action.","zh":"這個短語把數據與下一步行動連接起來。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":16},{"front":"assemble a comprehensive list","meaning":"整理出一份全面清單","examples":[{"en":"The researchers assembled a comprehensive list of cultural behaviour candidates.","zh":"研究人員整理出一份可能屬於文化行為的全面清單。"},{"en":"To assemble a comprehensive list means to gather many items into a detailed and complete list.","zh":"assemble a comprehensive list 指把許多項目收集成詳細而完整的清單。"},{"en":"A teacher may assemble a comprehensive list of common grammar mistakes before revision.","zh":"老師可能在溫習前整理出一份常見文法錯誤的全面清單。"},{"en":"A complete list helps people compare, classify, and check information systematically.","zh":"完整清單幫助人們有系統地比較、分類和檢查資料。"},{"en":"This phrase is common in research and planning.","zh":"這個短語常見於研究和規劃。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":16},{"front":"candidates for cultural behaviours","meaning":"可能屬於文化行為的候選項目","examples":[{"en":"The list contained 65 candidates for cultural behaviours.","zh":"這份清單包含65項可能屬於文化行為的候選項目。"},{"en":"Candidates for cultural behaviours are behaviours that may qualify as cultural but still need checking.","zh":"candidates for cultural behaviours 指可能符合文化行為資格但仍需檢查的行為。"},{"en":"In a study, researchers may list possible candidates before deciding which examples truly fit.","zh":"在研究中，研究人員可能先列出候選項目，再決定哪些例子真正符合。"},{"en":"Calling them candidates shows that the classification is not final yet.","zh":"稱它們為 candidates 顯示分類尚未最終確定。"},{"en":"This phrase is useful when sorting possible examples in research.","zh":"在研究中整理可能例子時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":16},{"front":"distribute a list to","meaning":"將清單分發給……","examples":[{"en":"The researchers distributed their list to team leaders at each site.","zh":"研究人員將清單分發給每個地點的團隊負責人。"},{"en":"To distribute a list to people means to send or give the list to them.","zh":"distribute a list to people 指把清單寄給或交給某些人。"},{"en":"A teacher may distribute a reading list to students before the holiday.","zh":"老師可能在假期前將閱讀清單分發給學生。"},{"en":"Sharing the same list helps different groups use the same standards.","zh":"分享同一清單有助不同群體使用相同標準。"},{"en":"This phrase is useful when materials are sent for review or action.","zh":"當材料被發送作審閱或行動時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":16},{"front":"team leaders","meaning":"團隊負責人","examples":[{"en":"Team leaders classified each behaviour after consulting their colleagues.","zh":"團隊負責人在與同事商討後分類每種行為。"},{"en":"Team leaders are people responsible for guiding or coordinating a group’s work.","zh":"team leaders 指負責指導或協調小組工作的人。"},{"en":"A project team leader may divide tasks and check progress each week.","zh":"項目團隊負責人可能每週分配任務並檢查進度。"},{"en":"Leaders help make sure different members follow the same plan.","zh":"負責人幫助確保不同成員跟隨同一計劃。"},{"en":"This phrase is common in workplaces, research, and group projects.","zh":"這個短語常見於工作場所、研究和小組項目。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":16},{"front":"consult with","meaning":"與……商討","examples":[{"en":"The team leaders consulted with their colleagues.","zh":"團隊負責人與同事商討。"},{"en":"To consult with someone means to discuss something with them before deciding.","zh":"consult with someone 指在作決定前與某人討論。"},{"en":"A doctor may consult with another specialist before recommending surgery.","zh":"醫生在建議手術前可能與另一名專科醫生商討。"},{"en":"Consultation helps reduce mistakes because more experience is included.","zh":"商討有助減少錯誤，因為納入了更多經驗。"},{"en":"This phrase is useful in professional decision-making.","zh":"這個短語適用於專業決策。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":16},{"front":"classify each behaviour","meaning":"將每種行為分類","examples":[{"en":"The researchers classified each behaviour according to its occurrence or absence.","zh":"研究人員根據每種行為是否出現來分類。"},{"en":"To classify each behaviour means to sort every behaviour into a category.","zh":"classify each behaviour 指把每種行為分入某個類別。"},{"en":"A teacher may classify each mistake as grammar, vocabulary, or organisation.","zh":"老師可能把每個錯誤分類為文法、詞彙或組織。"},{"en":"Classification helps researchers compare large amounts of information clearly.","zh":"分類幫助研究人員清楚比較大量資料。"},{"en":"This phrase is common in research and data analysis.","zh":"這個短語常見於研究和數據分析。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":16},{"front":"according to","meaning":"根據","examples":[{"en":"Each behaviour was classified according to its occurrence or absence.","zh":"每種行為根據其出現或缺席而被分類。"},{"en":"According to means based on a rule, standard, or source.","zh":"according to 指基於某規則、標準或來源。"},{"en":"Students may be grouped according to their reading level.","zh":"學生可能根據閱讀程度分組。"},{"en":"Using a clear standard makes classification fairer and easier to check.","zh":"使用清楚標準令分類更公平，也更容易檢查。"},{"en":"This phrase is common in academic and exam writing.","zh":"這個短語常見於學術和考試寫作。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":16},{"front":"occurrence or absence","meaning":"出現或缺席","examples":[{"en":"The classification depended on the occurrence or absence of each behaviour.","zh":"分類取決於每種行為的出現或缺席。"},{"en":"Occurrence or absence means whether something happens or does not happen.","zh":"occurrence or absence 指某事發生或不發生。"},{"en":"A doctor may record the occurrence or absence of symptoms during a check-up.","zh":"醫生檢查時可能記錄症狀的出現或缺席。"},{"en":"Knowing both presence and absence helps researchers avoid incomplete conclusions.","zh":"同時知道存在和不存在有助研究人員避免不完整結論。"},{"en":"This phrase is useful in systematic observation.","zh":"這個短語適用於系統觀察。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":16},{"front":"chimpanzee community","meaning":"黑猩猩群體","examples":[{"en":"Each behaviour was classified within a chimpanzee community.","zh":"每種行為在黑猩猩群體內被分類。"},{"en":"A chimpanzee community is a group of chimpanzees living and interacting together.","zh":"chimpanzee community 指一起生活和互動的黑猩猩群體。"},{"en":"Researchers may study one chimpanzee community for many years to understand its habits.","zh":"研究人員可能多年研究一個黑猩猩群體，以了解其習性。"},{"en":"Behaviour may vary from one community to another because members learn locally.","zh":"行為可能因群體而異，因為成員在本地學習。"},{"en":"This phrase is useful when discussing group life among chimpanzees.","zh":"討論黑猩猩群體生活時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":16},{"front":"main categories","meaning":"主要類別","examples":[{"en":"The main categories included customary, habitual, present, absent and unknown.","zh":"主要類別包括慣常、習慣性出現、存在、缺席和未知。"},{"en":"Main categories are the most important groups used to organise information.","zh":"main categories 指用來整理資料的最重要組別。"},{"en":"A teacher may sort errors into main categories such as spelling, grammar, and structure.","zh":"老師可能把錯誤分成拼寫、文法和結構等主要類別。"},{"en":"Categories help people handle complex data more clearly.","zh":"類別幫助人們更清楚處理複雜數據。"},{"en":"This phrase is useful in classification and analysis.","zh":"這個短語適用於分類和分析。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":16},{"front":"customary behaviour","meaning":"慣常行為","examples":[{"en":"Customary behaviour occurs in most or all members of a class.","zh":"慣常行為出現在某一類別的大部分或所有成員之中。"},{"en":"Customary behaviour is behaviour that is usual or regularly practised by a group.","zh":"customary behaviour 指某群體通常或定期實踐的行為。"},{"en":"Taking off shoes before entering a home can be customary behaviour in some families.","zh":"入屋前脫鞋可以是某些家庭的慣常行為。"},{"en":"If most group members do the same thing, the behaviour may be considered customary.","zh":"如果大多數群體成員都做同一件事，該行為可能被視為慣常。"},{"en":"This phrase is useful when describing normal group habits.","zh":"描述群體正常習慣時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":17},{"front":"occur in most or all of","meaning":"出現在大部分或所有……之中","examples":[{"en":"Customary behaviour occurs in most or all able-bodied members.","zh":"慣常行為出現在大部分或所有身體健全的成員之中。"},{"en":"To occur in most or all of a group means to be seen in nearly everyone or everyone in that group.","zh":"occur in most or all of a group 指在該群體中幾乎所有或所有成員身上出現。"},{"en":"Wearing uniforms may occur in most or all students at a school.","zh":"穿校服可能出現在一所學校大部分或所有學生之中。"},{"en":"When a behaviour occurs widely, researchers may treat it as a group pattern.","zh":"當行為廣泛出現，研究人員可能把它視為群體模式。"},{"en":"This phrase is useful when describing frequency across members.","zh":"描述成員之間的頻率時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":17},{"front":"able-bodied members","meaning":"身體健全的成員","examples":[{"en":"The category includes able-bodied members of an age or sex class.","zh":"這個類別包括某年齡或性別組別中身體健全的成員。"},{"en":"Able-bodied members are individuals physically able to perform the behaviour being considered.","zh":"able-bodied members 指身體上有能力做出所考慮行為的個體。"},{"en":"In a sports class, able-bodied students may be expected to complete the same basic activity.","zh":"在體育課中，身體健全的學生可能被期望完成同一基本活動。"},{"en":"Researchers may exclude individuals unable to perform an action when judging how common it is.","zh":"研究人員判斷行為有多常見時，可能排除無法做該行動的個體。"},{"en":"This phrase focuses on physical capability.","zh":"這個短語聚焦身體能力。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":17},{"front":"age or sex class","meaning":"年齡或性別組別","examples":[{"en":"The behaviour may occur in at least one age or sex class.","zh":"該行為可能出現在至少一個年齡或性別組別中。"},{"en":"An age or sex class is a group defined by age, sex, or both.","zh":"age or sex class 指按年齡、性別或兩者定義的群體。"},{"en":"A wildlife study may compare adult males, adult females, and young animals as different classes.","zh":"野生動物研究可能把成年雄性、成年雌性和幼體作為不同組別比較。"},{"en":"Grouping by age or sex helps researchers see who performs a behaviour.","zh":"按年齡或性別分組幫助研究人員看出誰會做某行為。"},{"en":"This phrase is common in animal behaviour research.","zh":"這個短語常見於動物行為研究。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":17},{"front":"adult males","meaning":"成年雄性","examples":[{"en":"All adult males may show a particular customary behaviour.","zh":"所有成年雄性可能表現某一慣常行為。"},{"en":"Adult males are fully grown male individuals.","zh":"adult males 指已完全長成的雄性個體。"},{"en":"In a wildlife study, adult males may behave differently from young males or females.","zh":"在野生動物研究中，成年雄性的行為可能不同於年輕雄性或雌性。"},{"en":"Age and sex can affect behaviour, strength, status, and social roles.","zh":"年齡和性別可以影響行為、力量、地位和社會角色。"},{"en":"This phrase is common in biology and animal studies.","zh":"這個短語常見於生物和動物研究。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":17},{"front":"habitual","meaning":"習慣性出現的","examples":[{"en":"A habitual behaviour is less common than a customary one.","zh":"習慣性行為比慣常行為較不常見。"},{"en":"Habitual means repeated often enough to be a regular habit, though not necessarily shown by almost everyone.","zh":"habitual 指經常重複到成為習慣，但不一定幾乎所有人都做。"},{"en":"Checking a phone before sleeping can become habitual for students.","zh":"睡前查看手機可以成為學生習慣性行為。"},{"en":"A behaviour becomes habitual when it happens repeatedly over time.","zh":"當某行為隨時間反覆發生，它就會變成習慣性。"},{"en":"This word is useful when describing regular but not universal actions.","zh":"描述規律但非普遍的行動時，這個詞很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":17},{"front":"less common than","meaning":"沒有……那麼常見","examples":[{"en":"Habitual behaviour is less common than customary behaviour.","zh":"習慣性行為沒有慣常行為那麼常見。"},{"en":"Less common than means happening less often than something else.","zh":"less common than 指比另一事物發生得較少。"},{"en":"Taking the ferry may be less common than taking the train in a city.","zh":"在城市中，乘渡輪可能沒有乘火車那麼常見。"},{"en":"Comparing frequency helps people understand how widespread a behaviour is.","zh":"比較頻率幫助人們理解行為有多普遍。"},{"en":"This phrase is useful in research, statistics, and everyday comparison.","zh":"這個短語適用於研究、統計和日常比較。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":17},{"front":"occur repeatedly","meaning":"重複出現","examples":[{"en":"Habitual behaviours occur repeatedly in several individuals.","zh":"習慣性行為在數個個體中重複出現。"},{"en":"To occur repeatedly means to happen again and again.","zh":"occur repeatedly 指一次又一次發生。"},{"en":"A grammar mistake may occur repeatedly in a student’s essays.","zh":"文法錯誤可能在學生文章中重複出現。"},{"en":"Repeated occurrence suggests that something may be a pattern, not an accident.","zh":"重複出現暗示某事可能是模式，而不是意外。"},{"en":"This phrase is useful when describing frequency over time.","zh":"描述隨時間發生的頻率時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":17},{"front":"several individuals","meaning":"數個個體","examples":[{"en":"A behaviour may occur repeatedly in several individuals.","zh":"某行為可能在數個個體中重複出現。"},{"en":"Several individuals means more than two separate members of a group.","zh":"several individuals 指一個群體中多於兩個獨立成員。"},{"en":"A teacher may notice the same mistake in several individuals in the class.","zh":"老師可能注意到班中數個個體犯同一錯誤。"},{"en":"If several individuals show the same behaviour, it may not be a one-off event.","zh":"如果數個個體表現同一行為，它可能不是一次性事件。"},{"en":"This phrase is useful when moving beyond one isolated case.","zh":"當討論不只是一個孤立個案時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":17},{"front":"observed at the site","meaning":"在該地點被觀察到","examples":[{"en":"A present behaviour has been observed at the site but is not habitual.","zh":"存在行為是在該地點被觀察到但並非習慣性出現的行為。"},{"en":"Observed at the site means seen or recorded at that research location.","zh":"observed at the site 指在該研究地點被看見或記錄。"},{"en":"A bird species may be observed at a site only during winter.","zh":"某鳥類可能只在冬季在某地點被觀察到。"},{"en":"A behaviour can be present at a site without being common there.","zh":"行為可以在某地點存在，但不一定常見。"},{"en":"This phrase is useful in field research.","zh":"這個短語適用於野外研究。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":17},{"front":"not habitual","meaning":"並非習慣性出現","examples":[{"en":"A present behaviour is observed but not habitual.","zh":"存在行為是被觀察到但並非習慣性出現的行為。"},{"en":"Not habitual means not happening often enough to be considered a regular habit.","zh":"not habitual 指發生頻率不足以被視為固定習慣。"},{"en":"A student may arrive late once, but if it is not habitual, it is not a pattern.","zh":"學生可能遲到一次，但如果並非習慣性出現，就不是模式。"},{"en":"Distinguishing present from habitual prevents researchers from overstating evidence.","zh":"區分存在和習慣性行為，可以防止研究人員誇大證據。"},{"en":"This phrase contrasts occasional occurrence with repeated behaviour.","zh":"這個短語把偶然出現與重複行為作對比。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":17},{"front":"never seen","meaning":"從未被看見","examples":[{"en":"An absent behaviour is never seen at a site.","zh":"缺席行為是在某地點從未被看見的行為。"},{"en":"Never seen means not observed at any time.","zh":"never seen 指在任何時候都沒有被觀察到。"},{"en":"A teacher may say a certain spelling mistake is never seen in the top essays.","zh":"老師可能說某拼寫錯誤在最高分文章中從未被看見。"},{"en":"If a behaviour is never seen in one community, it may be absent there.","zh":"如果某行為在一個群體中從未被看見，它可能在那裏不存在。"},{"en":"This phrase is useful when recording absence clearly.","zh":"清楚記錄缺席時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":18},{"front":"unknown","meaning":"未知","examples":[{"en":"A behaviour may be classified as unknown if the evidence is unclear.","zh":"如果證據不清楚，某行為可能被分類為未知。"},{"en":"Unknown means not known or not yet confirmed.","zh":"unknown 指不知情或尚未確認。"},{"en":"A school may mark a student’s reason for absence as unknown until parents reply.","zh":"學校在家長回覆前，可能把學生缺席原因標為未知。"},{"en":"When evidence is unclear, researchers should not pretend they know the answer.","zh":"當證據不清楚，研究人員不應假裝知道答案。"},{"en":"This word is useful when information is incomplete.","zh":"當資訊不完整時，這個詞很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":18},{"front":"contains the following information","meaning":"包含以下資料","examples":[{"en":"The question asks which paragraph contains the following information.","zh":"題目問哪一段包含以下資料。"},{"en":"Contains the following information means includes the details listed after the instruction.","zh":"contains the following information 指包括指示後列出的細節。"},{"en":"In a reading test, students scan for the paragraph that contains the required detail.","zh":"在閱讀測驗中，學生掃讀找出包含所需細節的段落。"},{"en":"A paragraph may contain the information even if it uses different wording.","zh":"即使用詞不同，段落仍可能包含該資料。"},{"en":"This phrase is common in information-location questions.","zh":"這個短語常見於資料定位題。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":18},{"front":"based solely on official sources","meaning":"只基於官方來源","examples":[{"en":"One research approach was based solely on official sources.","zh":"一種研究方法只基於官方來源。"},{"en":"Based solely on official sources means using only formal published records or authorities as evidence.","zh":"based solely on official sources 指只使用正式發表記錄或權威來源作證據。"},{"en":"A report based solely on school notices may miss what students actually experience.","zh":"只基於學校通告的報告可能錯過學生實際經歷。"},{"en":"Relying only on official sources can leave out informal but important information.","zh":"只依賴官方來源可能忽略非正式但重要的資訊。"},{"en":"This phrase is useful when evaluating the limits of evidence.","zh":"評估證據限制時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":18},{"front":"official sources","meaning":"官方來源","examples":[{"en":"Previous studies often depended on official sources.","zh":"以往研究常依賴官方來源。"},{"en":"Official sources are formal records or statements from recognised organisations or authorities.","zh":"official sources 指來自受認可組織或權威機構的正式記錄或聲明。"},{"en":"Government websites and published research reports can be official sources.","zh":"政府網站和已發表研究報告都可以是官方來源。"},{"en":"Official sources are useful, but they may not include every detail from daily experience.","zh":"官方來源很有用，但未必包括日常經驗中的每個細節。"},{"en":"This phrase is common in research and evidence evaluation.","zh":"這個短語常見於研究和證據評估。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":18},{"front":"mention of","meaning":"提及","examples":[{"en":"The question asks for mention of a new research approach.","zh":"題目要求找出提及新研究方法的地方。"},{"en":"Mention of something means a reference to it in speech or writing.","zh":"mention of something 指在口頭或書面中提到某事。"},{"en":"A report may include mention of student stress but not discuss it deeply.","zh":"報告可能提及學生壓力，但沒有深入討論。"},{"en":"In reading tasks, a brief mention can still be enough to locate an answer.","zh":"在閱讀題中，即使只是簡短提及，也可能足以定位答案。"},{"en":"This phrase is useful when identifying where a topic appears.","zh":"識別主題在哪裏出現時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":18},{"front":"a new research approach","meaning":"新的研究方法","examples":[{"en":"The passage describes a new research approach developed by two scientists.","zh":"文章描述一種由兩位科學家發展出來的新研究方法。"},{"en":"A new research approach is a different method used to study a question.","zh":"new research approach 指用來研究問題的不同方法。"},{"en":"A school may use a new research approach by interviewing students instead of only reading grades.","zh":"學校可以透過訪問學生而不是只看成績，使用新的研究方法。"},{"en":"New approaches can fix weaknesses in older methods.","zh":"新方法可以修正舊方法中的弱點。"},{"en":"This phrase is useful when explaining changes in research design.","zh":"解釋研究設計改變時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":18},{"front":"developed by two scientists","meaning":"由兩位科學家發展出來","examples":[{"en":"The new research approach was developed by two scientists.","zh":"新研究方法由兩位科學家發展出來。"},{"en":"Developed by two scientists means created or designed by two researchers.","zh":"developed by two scientists 指由兩位研究人員創造或設計。"},{"en":"A new test may be developed by two doctors after years of hospital work.","zh":"新測試可能由兩位醫生經多年醫院工作後發展出來。"},{"en":"Naming who developed a method helps readers understand its origin.","zh":"說明方法由誰發展出來，有助讀者理解其來源。"},{"en":"This phrase identifies the creators of an idea or system.","zh":"這個短語指出想法或系統的創造者。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":18},{"front":"address the problems","meaning":"處理問題","examples":[{"en":"The new approach was designed to address the problems in earlier studies.","zh":"新方法旨在處理早期研究中的問題。"},{"en":"To address the problems means to deal with them seriously and directly.","zh":"address the problems 指認真而直接地處理問題。"},{"en":"A school may address the problems of lateness by changing bus arrangements.","zh":"學校可能透過改變巴士安排來處理遲到問題。"},{"en":"Addressing problems requires understanding their causes, not only noticing them.","zh":"處理問題需要理解其原因，而不只是注意到問題。"},{"en":"This phrase is useful in formal writing about solutions.","zh":"在正式寫作中談解決方案時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":18},{"front":"previous research","meaning":"以往研究","examples":[{"en":"Previous research on ape culture had several weaknesses.","zh":"以往關於猿類文化的研究有幾個弱點。"},{"en":"Previous research means studies that were done earlier.","zh":"previous research 指早前已完成的研究。"},{"en":"A student should read previous research before starting a science project.","zh":"學生在開始科學項目前應閱讀以往研究。"},{"en":"Earlier studies can provide useful knowledge but may also have limitations.","zh":"早期研究可以提供有用知識，但也可能有限制。"},{"en":"This phrase is common in academic writing.","zh":"這個短語常見於學術寫作。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":18},{"front":"be problematic","meaning":"有問題；存在問題","examples":[{"en":"The passage explains why previous research on ape culture is problematic.","zh":"文章解釋為何以往猿類文化研究有問題。"},{"en":"To be problematic means to have problems, weaknesses, or causes for concern.","zh":"be problematic 指存在問題、弱點或令人擔憂之處。"},{"en":"A timetable is problematic if students have no time to eat lunch.","zh":"如果時間表令學生沒有時間吃午飯，它就是有問題的。"},{"en":"Something may seem useful but still be problematic if it leaves out important information.","zh":"某物可能看似有用，但如果漏掉重要資訊，仍然存在問題。"},{"en":"This word is useful for careful criticism.","zh":"這個詞適合謹慎批評。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":18},{"front":"classification of data","meaning":"數據分類","examples":[{"en":"The final paragraph describes a classification of data.","zh":"最後一段描述數據分類。"},{"en":"Classification of data means sorting information into categories.","zh":"classification of data 指把資料分入不同類別。"},{"en":"A teacher may use classification of data to group errors by type.","zh":"老師可能使用數據分類，把錯誤按類型分組。"},{"en":"Classification makes a large set of information easier to compare and analyse.","zh":"分類令大量資訊更容易比較和分析。"},{"en":"This phrase is useful in research, statistics, and study skills.","zh":"這個短語適用於研究、統計和學習技巧。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":19},{"front":"observed or collected","meaning":"被觀察或收集到","examples":[{"en":"The study classified data that had been observed or collected.","zh":"研究把被觀察或收集到的數據分類。"},{"en":"Observed or collected means seen directly or gathered as information.","zh":"observed or collected 指直接看見或作為資料收集。"},{"en":"A science student may analyse data observed or collected during an experiment.","zh":"科學學生可能分析在實驗中被觀察或收集到的數據。"},{"en":"Good research records where data came from and how it was gathered.","zh":"好研究會記錄數據來自哪裏以及如何收集。"},{"en":"This phrase is useful when describing sources of evidence.","zh":"描述證據來源時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":19},{"front":"lead to a change in","meaning":"導致……的改變","examples":[{"en":"Cultural traits can lead to a change in local people’s attitudes.","zh":"文化特徵可以導致本地居民態度的改變。"},{"en":"To lead to a change in something means to cause it to become different.","zh":"lead to a change in something 指造成某事變得不同。"},{"en":"A powerful documentary can lead to a change in how students think about waste.","zh":"有力量的紀錄片可以導致學生對浪費看法的改變。"},{"en":"Changes in attitude often happen when people see new evidence or personal stories.","zh":"當人們看到新證據或個人故事，態度常會改變。"},{"en":"This phrase is useful when showing cause and result.","zh":"顯示原因和結果時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":19},{"front":"attitudes towards","meaning":"對……的態度","examples":[{"en":"Local people’s attitudes towards conservation may change.","zh":"本地居民對保育的態度可能改變。"},{"en":"Attitudes towards something are people’s feelings, beliefs, or opinions about it.","zh":"attitudes towards something 指人們對某事的感受、信念或意見。"},{"en":"Students’ attitudes towards reading may improve after they find books they enjoy.","zh":"學生找到喜歡的書後，對閱讀的態度可能改善。"},{"en":"Changing attitudes can change behaviour over time.","zh":"改變態度可以隨時間改變行為。"},{"en":"This phrase is common in social research and opinion writing.","zh":"這個短語常見於社會研究和意見寫作。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":19},{"front":"their conservation","meaning":"對牠們的保育","examples":[{"en":"The example shows support for chimpanzee conservation.","zh":"這個例子顯示對黑猩猩保育的支持。"},{"en":"Their conservation means the protection of the animals being discussed.","zh":"their conservation 指對正在討論的動物的保護。"},{"en":"A national park may help with the conservation of rare birds.","zh":"國家公園可能有助罕見鳥類的保育。"},{"en":"Conservation requires protecting habitats, reducing threats, and changing human behaviour.","zh":"保育需要保護棲息地、減少威脅並改變人類行為。"},{"en":"This phrase is useful when discussing efforts to save a species.","zh":"討論拯救物種的努力時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":19},{"front":"agree with the information given","meaning":"與文中資料一致","examples":[{"en":"The statements must agree with the information given in the passage.","zh":"這些陳述必須與文中資料一致。"},{"en":"Agree with the information given means match what the text says or supports.","zh":"agree with the information given 指符合文章所說或支持的內容。"},{"en":"In a reading test, an answer must agree with the passage rather than personal opinion.","zh":"在閱讀測驗中，答案必須與文章一致，而不是符合個人意見。"},{"en":"A statement may use different words but still agree with the meaning.","zh":"陳述可能使用不同字眼，但仍與意思一致。"},{"en":"This phrase is common in TRUE, FALSE, NOT GIVEN questions.","zh":"這個短語常見於 TRUE, FALSE, NOT GIVEN 題。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":19},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與文章資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"contradict the information 指說出與文章內容相反的意思。"},{"en":"If a passage says a study began in Tanzania, a statement saying it began in Kenya may contradict it.","zh":"如果文章說研究在坦桑尼亞開始，而陳述說在肯尼亞開始，就可能與它矛盾。"},{"en":"Contradiction is different from missing information because there is a direct conflict.","zh":"矛盾不同於資料缺失，因為它有直接衝突。"},{"en":"This phrase helps students identify FALSE answers.","zh":"這個短語幫助學生辨認 FALSE 答案。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":19},{"front":"no information on this","meaning":"沒有這方面的資料","examples":[{"en":"Write “not given” if there is no information on this.","zh":"如果沒有這方面的資料，就寫 not given。"},{"en":"No information on this means the passage does not say whether the statement is true or false.","zh":"no information on this 指文章沒有說明該陳述是真或是假。"},{"en":"If a text discusses chimpanzee behaviour but not their exact weight, there is no information on that.","zh":"如果文本討論黑猩猩行為但沒有提到牠們確切體重，就沒有這方面的資料。"},{"en":"Students should not guess when the passage gives no evidence.","zh":"當文章沒有提供證據，學生不應猜測。"},{"en":"This phrase is essential for NOT GIVEN questions.","zh":"這個短語對 NOT GIVEN 題很重要。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":19},{"front":"possess a culture","meaning":"擁有文化","examples":[{"en":"Chimpanzees possess a culture, but it is not as complex as human culture.","zh":"黑猩猩擁有文化，但它不如人類文化複雜。"},{"en":"To possess a culture means to have shared learned behaviours or traditions.","zh":"possess a culture 指擁有共同學習得來的行為或傳統。"},{"en":"A community may possess a culture shown through language, food, and rituals.","zh":"一個社群可能透過語言、食物和儀式顯示其擁有文化。"},{"en":"If animals possess culture, researchers must think differently about learning and tradition.","zh":"如果動物擁有文化，研究人員必須重新思考學習和傳統。"},{"en":"This phrase is useful when discussing whether culture exists beyond humans.","zh":"討論文化是否存在於人類以外時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":19},{"front":"as complex as","meaning":"與……一樣複雜","examples":[{"en":"Chimpanzee culture is not described as being as complex as human culture.","zh":"文章沒有把黑猩猩文化描述為與人類文化一樣複雜。"},{"en":"As complex as means having the same level of complexity as something else.","zh":"as complex as 指與另一事物有相同複雜程度。"},{"en":"A short quiz is not as complex as a full research project.","zh":"小測並不像完整研究項目一樣複雜。"},{"en":"This phrase compares the difficulty, structure, or depth of two things.","zh":"這個短語比較兩件事的難度、結構或深度。"},{"en":"It is useful when showing equality or inequality in complexity.","zh":"顯示複雜程度相同或不同時，它很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":19},{"front":"share most of their genetic material","meaning":"共享大部分基因物質","examples":[{"en":"Humans and chimpanzees share most of their genetic material.","zh":"人類和黑猩猩共享大部分基因物質。"},{"en":"To share most of their genetic material means to have a very large amount of DNA in common.","zh":"share most of their genetic material 指有非常大量共同 DNA。"},{"en":"Brothers and sisters share much genetic material because they have the same parents.","zh":"兄弟姊妹因有相同父母而共享大量基因物質。"},{"en":"Shared genetic material can help explain biological similarities.","zh":"共同基因物質可以幫助解釋生物相似之處。"},{"en":"This phrase is useful in evolution and biology.","zh":"這個短語適用於進化和生物學。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":19},{"front":"early studies","meaning":"早期研究","examples":[{"en":"Nishida’s and Goodall’s early studies revealed surprising behaviours.","zh":"Nishida 和 Goodall 的早期研究揭示了令人驚訝的行為。"},{"en":"Early studies are research projects carried out near the beginning of a field or investigation.","zh":"early studies 指某領域或調查初期進行的研究項目。"},{"en":"Early studies of online learning focused mainly on access and equipment.","zh":"網上學習的早期研究主要聚焦可及性和設備。"},{"en":"Early studies can open a new field by showing unexpected results.","zh":"早期研究可以透過顯示意外結果開創新領域。"},{"en":"This phrase is useful when discussing the first stage of research history.","zh":"討論研究歷史的第一階段時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":20},{"front":"reveal surprising examples of","meaning":"揭示令人驚訝的……例子","examples":[{"en":"The early studies revealed surprising examples of sophisticated chimpanzee behaviour.","zh":"早期研究揭示了複雜黑猩猩行為的驚人例子。"},{"en":"To reveal surprising examples of something means to show unexpected cases of it.","zh":"reveal surprising examples of something 指顯示某事的意想不到個案。"},{"en":"A teacher’s marking may reveal surprising examples of creativity in weak essays.","zh":"老師批改時可能在薄弱文章中發現令人驚訝的創意例子。"},{"en":"Surprising examples can challenge what people assumed before.","zh":"令人驚訝的例子可以挑戰人們之前的假設。"},{"en":"This phrase is useful when evidence uncovers something unexpected.","zh":"當證據揭示意料之外的內容時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":20},{"front":"sophisticated chimpanzee behaviour","meaning":"複雜的黑猩猩行為","examples":[{"en":"The studies revealed examples of sophisticated chimpanzee behaviour.","zh":"這些研究揭示了複雜黑猩猩行為的例子。"},{"en":"Sophisticated chimpanzee behaviour is complex behaviour that suggests learning, planning, or social understanding.","zh":"sophisticated chimpanzee behaviour 指暗示學習、計劃或社交理解的複雜行為。"},{"en":"Using a tool to reach food may be more sophisticated than simply grabbing it by hand.","zh":"使用工具拿食物可能比單純用手抓更複雜。"},{"en":"Sophisticated behaviour can make researchers rethink animal intelligence.","zh":"複雜行為可以令研究人員重新思考動物智能。"},{"en":"This phrase is useful when describing advanced animal actions.","zh":"描述進階動物行動時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":20},{"front":"primarily through genetic inheritance","meaning":"主要透過遺傳","examples":[{"en":"Cultural behaviours are not passed primarily through genetic inheritance.","zh":"文化行為並非主要透過遺傳傳承。"},{"en":"Primarily through genetic inheritance means mainly by receiving traits through genes from parents.","zh":"primarily through genetic inheritance 指主要透過從父母基因中獲得特徵。"},{"en":"Eye colour is passed primarily through genetic inheritance, but table manners are learned.","zh":"眼睛顏色主要透過遺傳傳承，但餐桌禮儀是學來的。"},{"en":"This phrase contrasts inherited biology with learned behaviour.","zh":"這個短語把生物遺傳與學習行為作對比。"},{"en":"It is useful when explaining why culture is not simply genetic.","zh":"解釋為何文化不只是基因時，它很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":20},{"front":"genetic inheritance","meaning":"遺傳","examples":[{"en":"The passage contrasts learning with genetic inheritance.","zh":"文章把學習與遺傳作對比。"},{"en":"Genetic inheritance is the passing of biological traits from parents to offspring through genes.","zh":"genetic inheritance 指透過基因把生物特徵由父母傳給後代。"},{"en":"Hair colour can be influenced by genetic inheritance.","zh":"頭髮顏色可能受遺傳影響。"},{"en":"Not every behaviour comes from inheritance; some behaviours are learned socially.","zh":"並非每種行為都來自遺傳；有些行為是透過社交學習而來。"},{"en":"This phrase is central to biology and evolution.","zh":"這個短語是生物學和進化的核心。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":20},{"front":"using data about","meaning":"使用關於……的數據","examples":[{"en":"The statement refers to researchers using data about observed and unobserved behaviours.","zh":"該陳述指研究人員使用關於已觀察及未觀察到行為的數據。"},{"en":"Using data about something means relying on collected information about that topic.","zh":"using data about something 指依靠關於該主題已收集的資料。"},{"en":"A school may make timetable decisions using data about student travel times.","zh":"學校可能使用關於學生通勤時間的數據來制定時間表。"},{"en":"Good data helps people make decisions based on evidence rather than guesses.","zh":"良好數據幫助人們根據證據而不是猜測作決定。"},{"en":"This phrase is useful in research, planning, and analysis.","zh":"這個短語適用於研究、規劃和分析。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":20},{"front":"observed and unobserved behaviours","meaning":"已觀察及未觀察到的行為","examples":[{"en":"The survey needed information about observed and unobserved behaviours.","zh":"調查需要關於已觀察及未觀察到行為的資料。"},{"en":"Observed and unobserved behaviours are behaviours that were seen and behaviours that were not seen.","zh":"observed and unobserved behaviours 指已被看見和未被看見的行為。"},{"en":"A teacher may record observed and unobserved skills during a speaking test.","zh":"老師可能在口語測驗中記錄已觀察和未觀察到的技能。"},{"en":"Knowing what was not observed can be as important as knowing what was observed.","zh":"知道甚麼沒有被觀察到，可以與知道甚麼被觀察到同樣重要。"},{"en":"This phrase is useful for complete and balanced data collection.","zh":"這個短語適合完整而平衡的數據收集。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":20},{"front":"answer the questions below","meaning":"回答以下問題","examples":[{"en":"Students must answer the questions below using words from the passage.","zh":"學生必須使用文章中的詞語回答以下問題。"},{"en":"Answer the questions below means respond to the questions listed after the instruction.","zh":"answer the questions below 指回答指示後列出的問題。"},{"en":"In a worksheet, students may answer the questions below after reading a short text.","zh":"在工作紙中，學生可能閱讀短文後回答以下問題。"},{"en":"Following the instruction carefully helps avoid using the wrong source or format.","zh":"仔細跟從指示有助避免使用錯誤來源或格式。"},{"en":"This phrase is common in exam and textbook tasks.","zh":"這個短語常見於考試和教科書任務。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":20},{"front":"no more than two words and/or a number","meaning":"不超過兩個詞及／或一個數字","examples":[{"en":"The instructions require no more than two words and/or a number.","zh":"指示要求不超過兩個詞及／或一個數字。"},{"en":"No more than two words and/or a number means the answer must be very short and follow that limit.","zh":"no more than two words and/or a number 指答案必須很短並符合該限制。"},{"en":"If the answer is “the 1960s,” it uses words and a number within the limit.","zh":"如果答案是 the 1960s，它就在限制內使用詞語和數字。"},{"en":"Writing too many words can lose marks even if the idea is correct.","zh":"即使意思正確，寫太多詞也可能失分。"},{"en":"This phrase is common in IELTS-style completion questions.","zh":"這個短語常見於 IELTS 類填空題。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":20},{"front":"unexpected discoveries","meaning":"意想不到的發現","examples":[{"en":"The question asks when the unexpected discoveries began.","zh":"題目問意想不到的發現何時開始。"},{"en":"Unexpected discoveries are findings that surprise researchers because they were not predicted.","zh":"unexpected discoveries 指令研究人員驚訝、事前未預測到的發現。"},{"en":"A student may make unexpected discoveries when a simple experiment gives unusual results.","zh":"當簡單實驗產生異常結果，學生可能有意想不到的發現。"},{"en":"Unexpected discoveries can change the direction of later research.","zh":"意想不到的發現可以改變後續研究方向。"},{"en":"This phrase is useful when new evidence challenges old beliefs.","zh":"當新證據挑戰舊信念時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":20},{"front":"start","meaning":"開始","examples":[{"en":"The discoveries started when researchers began close field studies.","zh":"當研究人員開始近距離野外研究時，這些發現開始出現。"},{"en":"To start means to begin.","zh":"start 指開始。"},{"en":"A lesson may start when the teacher writes the first question on the board.","zh":"當老師在白板上寫下第一條問題，課堂可能開始。"},{"en":"Starting a study creates the first chance to collect evidence.","zh":"開始研究創造了收集證據的第一個機會。"},{"en":"This word is simple but important for time-order questions.","zh":"這個詞很簡單，但對時間順序題很重要。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":20},{"front":"in which country","meaning":"在哪個國家","examples":[{"en":"The question asks in which country the research sites are located.","zh":"題目問研究地點位於哪個國家。"},{"en":"In which country asks for the nation where something is found or happens.","zh":"in which country 詢問某物位於或某事發生在哪個國家。"},{"en":"A geography question may ask in which country a river begins.","zh":"地理題可能問一條河流在哪個國家發源。"},{"en":"This phrase helps students identify location information precisely.","zh":"這個短語幫助學生精確識別地點資訊。"},{"en":"It is common in short-answer reading questions.","zh":"它常見於閱讀短答題。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":21},{"front":"research sites are located","meaning":"研究地點位於","examples":[{"en":"The research sites are located in Tanzania.","zh":"研究地點位於坦桑尼亞。"},{"en":"Research sites are located means the study places are found in a particular area.","zh":"research sites are located 指研究地點位於某特定區域。"},{"en":"The school’s sports facilities are located behind the main building.","zh":"學校運動設施位於主樓後方。"},{"en":"Knowing where research sites are located helps readers understand the setting of a study.","zh":"知道研究地點位於何處，有助讀者理解研究背景。"},{"en":"This phrase is useful when giving geographical information.","zh":"提供地理資訊時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":21},{"front":"become accustomed to","meaning":"習慣於","examples":[{"en":"The chimpanzees had to become accustomed to close observation.","zh":"黑猩猩必須習慣近距離觀察。"},{"en":"To become accustomed to something means to get used to it over time.","zh":"become accustomed to something 指隨時間逐漸習慣某事。"},{"en":"A new worker may become accustomed to early shifts after a few weeks.","zh":"新員工幾星期後可能習慣早班。"},{"en":"When animals get used to researchers, their behaviour may become easier to observe naturally.","zh":"當動物習慣研究人員，牠們的自然行為可能更容易被觀察。"},{"en":"This phrase describes gradual adjustment.","zh":"這個短語描述逐漸適應。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":21},{"front":"during the initial studies","meaning":"在初期研究期間","examples":[{"en":"The chimpanzees became accustomed to observation during the initial studies.","zh":"黑猩猩在初期研究期間習慣了觀察。"},{"en":"During the initial studies means while the first stage of research was taking place.","zh":"during the initial studies 指在第一階段研究進行時。"},{"en":"During the initial studies, researchers may test methods and build trust with participants.","zh":"在初期研究期間，研究人員可能測試方法並與參與者建立信任。"},{"en":"Early research periods often shape what later studies can discover.","zh":"早期研究階段常會塑造後來研究能發現甚麼。"},{"en":"This phrase gives the time context for an early research process.","zh":"這個短語提供早期研究過程的時間背景。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":21},{"front":"regional differences","meaning":"地區差異","examples":[{"en":"Goodall used a term to describe regional differences in tool use.","zh":"Goodall 使用一個詞語描述工具使用上的地區差異。"},{"en":"Regional differences are variations between places or areas.","zh":"regional differences 指不同地方或地區之間的差異。"},{"en":"Students may notice regional differences in accents when watching interviews from different cities.","zh":"學生觀看不同城市訪問時，可能注意到口音上的地區差異。"},{"en":"Regional differences can reveal local habits, environments, or traditions.","zh":"地區差異可以揭示本地習慣、環境或傳統。"},{"en":"This phrase is useful when comparing behaviour across locations.","zh":"比較不同地點的行為時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":21},{"front":"tool use","meaning":"工具使用","examples":[{"en":"Researchers studied regional differences in chimpanzees’ tool use.","zh":"研究人員研究黑猩猩工具使用上的地區差異。"},{"en":"Tool use means using an object to help complete a task.","zh":"tool use 指使用物件來幫助完成任務。"},{"en":"A child shows tool use when she uses a ruler to draw a straight line.","zh":"孩子用尺畫直線時，就是展示工具使用。"},{"en":"In animals, tool use can suggest learning, planning, and problem-solving.","zh":"在動物身上，工具使用可以暗示學習、計劃和解難能力。"},{"en":"This phrase is important in discussions of intelligence and behaviour.","zh":"這個短語在智能和行為討論中很重要。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":21},{"front":"use a term to describe","meaning":"使用一個詞語去描述","examples":[{"en":"Goodall used a term to describe regional differences in chimpanzee behaviour.","zh":"Goodall 使用一個詞語去描述黑猩猩行為上的地區差異。"},{"en":"To use a term to describe something means to choose a word or phrase to explain it.","zh":"use a term to describe something 指選擇一個詞或短語來解釋某事。"},{"en":"A teacher may use the term “run-on sentence” to describe a sentence with two wrongly joined clauses.","zh":"老師可能使用 run-on sentence 一詞來描述兩個分句錯誤連接的句子。"},{"en":"Choosing the right term helps people discuss an idea more accurately.","zh":"選擇正確術語幫助人們更準確討論一個想法。"},{"en":"This phrase is useful when introducing specialist vocabulary.","zh":"引入專業詞彙時，這個短語很有用。"}],"source":"54 - The Study of Chimpanzee Culture.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 55":[{"front":"the evolutionary mystery","meaning":"進化之謎","examples":[{"en":"The evolutionary mystery of crocodile survival has interested scientists for many years.","zh":"鱷魚生存的進化之謎多年來一直令科學家感興趣。"},{"en":"An evolutionary mystery is a question about how a living thing changed, survived, or developed over time.","zh":"evolutionary mystery 指關於生物如何隨時間改變、生存或發展的問題。"},{"en":"The long neck of the giraffe is an evolutionary mystery students often discuss in biology lessons.","zh":"長頸鹿的長頸是學生在生物課中常討論的進化之謎。"},{"en":"If an animal survives while similar species disappear, scientists may study it as an evolutionary mystery.","zh":"如果一種動物在相似物種消失時仍能生存，科學家可能把它作為進化之謎來研究。"},{"en":"The phrase usually points to something in nature that is not yet fully explained.","zh":"這個片語通常指自然界中尚未完全解釋的現象。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":1},{"front":"crocodile survival","meaning":"鱷魚的生存","examples":[{"en":"Crocodile survival is remarkable because crocodiles have existed for millions of years.","zh":"鱷魚的生存非常驚人，因為鱷魚已存在數百萬年。"},{"en":"Crocodile survival means the ability of crocodiles to continue living as a group over a very long period.","zh":"crocodile survival 指鱷魚作為一個類群在極長時間內繼續存活的能力。"},{"en":"A biology teacher may use crocodile survival to explain why adaptation matters.","zh":"生物老師可能用鱷魚的生存來解釋適應為何重要。"},{"en":"If crocodiles survive climate change and food shortage, their bodies and behaviour must be effective.","zh":"如果鱷魚能熬過氣候變化和食物短缺，牠們的身體和行為必然有效。"},{"en":"The phrase focuses on long-term survival, not one individual crocodile staying alive.","zh":"這個片語集中於長期生存，而不是單一隻鱷魚活下來。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":1},{"front":"even though","meaning":"即使；儘管","examples":[{"en":"Even though crocodiles have existed for 200 million years, they are anything but primitive.","zh":"即使鱷魚已存在兩億年，牠們絕非原始。"},{"en":"Even though introduces a contrast between something expected and something surprising.","zh":"even though 引出預期情況與令人意外事實之間的對比。"},{"en":"Even though the test was difficult, many students passed because they practised carefully.","zh":"即使測驗很難，許多學生仍因仔細練習而合格。"},{"en":"If we say “even though”, we usually show that one fact does not stop another fact from being true.","zh":"當我們說 even though，通常表示一個事實不會阻止另一個事實成立。"},{"en":"The phrase means “although”, but it often makes the contrast feel stronger.","zh":"這個片語意思是 although，但通常令對比感更強。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":1},{"front":"have existed for","meaning":"已經存在了……","examples":[{"en":"Crocodiles have existed for 200 million years.","zh":"鱷魚已經存在了兩億年。"},{"en":"Have existed for means have been present or alive during a stated period of time.","zh":"have existed for 指在某段指定時間內一直存在或存活。"},{"en":"This school has existed for over one hundred years.","zh":"這間學校已經存在了一百多年。"},{"en":"If a species has existed for millions of years, it must have survived many environmental changes.","zh":"如果一個物種已經存在了數百萬年，它必然熬過許多環境變化。"},{"en":"The phrase is useful when talking about duration from the past to now.","zh":"這個片語適合用來談從過去延續到現在的時間長度。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":1},{"front":"anything but primitive","meaning":"絕非原始","examples":[{"en":"Crocodiles are anything but primitive.","zh":"鱷魚絕非原始。"},{"en":"Anything but primitive means not primitive at all; in fact, quite advanced or effective.","zh":"anything but primitive 指完全不原始；其實相當先進或有效。"},{"en":"The old library looks simple outside, but its digital system is anything but primitive.","zh":"舊圖書館外表簡單，但它的數碼系統絕非原始。"},{"en":"If an animal has survived for millions of years, calling it primitive may be misleading.","zh":"如果一種動物已存活數百萬年，稱它為原始可能具誤導性。"},{"en":"The phrase strongly rejects the idea after “but”.","zh":"這個片語強烈否定 but 後面的想法。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":1},{"front":"the ancestors of modern crocodiles","meaning":"現代鱷魚的祖先","examples":[{"en":"The ancestors of modern crocodiles adapted to an aquatic lifestyle.","zh":"現代鱷魚的祖先適應了水棲生活方式。"},{"en":"The ancestors of modern crocodiles were earlier crocodile-like animals from which present crocodiles developed.","zh":"the ancestors of modern crocodiles 指現代鱷魚演化而來的較早期類似鱷魚動物。"},{"en":"In science class, students compare modern animals with their ancestors to understand evolution.","zh":"在科學課中，學生比較現代動物和牠們的祖先，以理解演化。"},{"en":"If ancestors developed useful body features, later species may inherit advantages.","zh":"如果祖先發展出有用身體特徵，後來物種可能繼承優勢。"},{"en":"The phrase points to the earlier forms in the crocodile family line.","zh":"這個片語指鱷魚譜系中的早期形態。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":1},{"front":"adapted to","meaning":"適應了……","examples":[{"en":"The ancestors of modern crocodiles adapted to an aquatic lifestyle.","zh":"現代鱷魚的祖先適應了水棲生活方式。"},{"en":"Adapted to means changed or became suited to a particular environment or way of life.","zh":"adapted to 指改變或變得適合某種環境或生活方式。"},{"en":"New students adapted to online lessons after learning how to use the platform.","zh":"新學生學會使用平台後，適應了網上課堂。"},{"en":"If animals adapt to water, their bodies may become better for swimming and hunting there.","zh":"如果動物適應水中生活，牠們的身體可能更適合在水中游泳和獵食。"},{"en":"The phrase describes adjustment that helps survival or success.","zh":"這個片語描述有助生存或成功的調整。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":1},{"front":"an aquatic lifestyle","meaning":"水棲生活方式","examples":[{"en":"Modern crocodiles’ ancestors adapted to an aquatic lifestyle.","zh":"現代鱷魚的祖先適應了水棲生活方式。"},{"en":"An aquatic lifestyle is a way of life mainly connected with water.","zh":"an aquatic lifestyle 指主要與水有關的生活方式。"},{"en":"Fish, frogs, and many water insects have an aquatic lifestyle.","zh":"魚、青蛙和許多水生昆蟲都有水棲生活方式。"},{"en":"If an animal has an aquatic lifestyle, features such as webbed feet or a streamlined body may help it move.","zh":"如果動物有水棲生活方式，有蹼的腳或流線型身體等特徵可能幫助牠移動。"},{"en":"The phrase describes living, hunting, or moving mostly in water.","zh":"這個片語描述主要在水中生活、獵食或移動。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":1},{"front":"contemporary reptiles","meaning":"同時期的爬行動物","examples":[{"en":"Most other contemporary reptiles went extinct.","zh":"大多數其他同時期的爬行動物滅絕了。"},{"en":"Contemporary reptiles are reptiles living during the same period as the animals being discussed.","zh":"contemporary reptiles 指與正在討論的動物生活在同一時期的爬行動物。"},{"en":"Dinosaurs and some ancient reptiles were contemporary animals during parts of prehistoric time.","zh":"恐龍和一些古代爬行動物在史前部分時期是同時期動物。"},{"en":"If one group survives while its contemporary reptiles disappear, scientists may ask why.","zh":"如果一個類群生存下來，而同時期爬行動物消失，科學家可能會問原因。"},{"en":"The phrase compares animals from the same historical period.","zh":"這個片語比較同一歷史時期的動物。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":1},{"front":"went extinct","meaning":"滅絕","examples":[{"en":"Many contemporary reptiles went extinct.","zh":"許多同時期的爬行動物滅絕了。"},{"en":"Went extinct means died out completely as a species or group.","zh":"went extinct 指作為物種或類群完全消失。"},{"en":"Some island birds went extinct after new predators arrived.","zh":"一些島嶼鳥類在新捕食者到來後滅絕。"},{"en":"If a species cannot find food or reproduce, it may eventually go extinct.","zh":"如果物種找不到食物或不能繁殖，最終可能滅絕。"},{"en":"The phrase describes total disappearance from the natural world.","zh":"這個片語描述從自然界完全消失。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":1},{"front":"were able to survive","meaning":"能夠生存下來","examples":[{"en":"Crocodiles were able to survive because their bodies changed.","zh":"鱷魚能夠生存下來，因為牠們的身體發生了變化。"},{"en":"Were able to survive means had the ability to stay alive despite danger or difficulty.","zh":"were able to survive 指即使面對危險或困難仍有能力活下來。"},{"en":"A small shop was able to survive because loyal customers kept buying from it.","zh":"小店能夠生存下來，因為忠實顧客持續光顧。"},{"en":"If animals can survive harsh climates, they often have useful adaptations.","zh":"如果動物能在嚴酷氣候中生存，通常有有用的適應特徵。"},{"en":"The phrase focuses on successful survival under pressure.","zh":"這個片語集中於在壓力下成功存活。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":2},{"front":"adapted better to the climate","meaning":"更能適應氣候","examples":[{"en":"Crocodiles survived because they adapted better to the climate.","zh":"鱷魚能生存，是因為牠們更能適應氣候。"},{"en":"Adapted better to the climate means became more suited to weather, temperature, and seasonal conditions than others.","zh":"adapted better to the climate 指比其他生物更適合天氣、溫度和季節條件。"},{"en":"Farmers may choose crops that are adapted better to a dry climate.","zh":"農民可能選擇更能適應乾旱氣候的農作物。"},{"en":"If a species adapts better to climate change, it may survive while others decline.","zh":"如果一個物種更能適應氣候變化，它可能在其他物種衰退時存活。"},{"en":"The phrase compares how well different groups fit their environment.","zh":"這個片語比較不同類群有多適合其環境。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":2},{"front":"witnessed the rise and fall of","meaning":"見證……的興衰","examples":[{"en":"Crocodiles witnessed the rise and fall of the dinosaurs.","zh":"鱷魚見證了恐龍的興衰。"},{"en":"Witnessed the rise and fall of means existed through both the growth and decline of something.","zh":"witnessed the rise and fall of 指經歷並存在於某事物興起和衰落的整個過程。"},{"en":"An old city may have witnessed the rise and fall of several empires.","zh":"古老城市可能見證幾個帝國的興衰。"},{"en":"If a species witnesses another group’s rise and fall, it has survived an extremely long time.","zh":"如果一個物種見證另一類群的興衰，它已存活極長時間。"},{"en":"The phrase gives a dramatic sense of historical endurance.","zh":"這個片語帶出歷史持久性的戲劇感。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":2},{"front":"the rise and fall of the dinosaurs","meaning":"恐龍的興衰","examples":[{"en":"Crocodiles lived through the rise and fall of the dinosaurs.","zh":"鱷魚經歷了恐龍的興衰。"},{"en":"The rise and fall of the dinosaurs means the period when dinosaurs became dominant and later disappeared.","zh":"the rise and fall of the dinosaurs 指恐龍變得強盛並後來消失的時期。"},{"en":"A museum exhibit may show the rise and fall of the dinosaurs through fossils and timelines.","zh":"博物館展覽可能透過化石和時間線展示恐龍的興衰。"},{"en":"If crocodiles lived through that period, their survival is especially striking.","zh":"如果鱷魚經歷了那個時期，牠們的生存就特別驚人。"},{"en":"The phrase describes a major chapter in prehistoric life.","zh":"這個片語描述史前生命中的重大篇章。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":2},{"front":"ruled the planet","meaning":"主宰地球","examples":[{"en":"Dinosaurs once ruled the planet.","zh":"恐龍曾經主宰地球。"},{"en":"Ruled the planet means were the dominant or most powerful living group on Earth.","zh":"ruled the planet 指曾是地球上占主導或最強大的生物類群。"},{"en":"Humans now affect the planet so greatly that some say they rule many environments.","zh":"人類如今極大地影響地球，因此有人說人類主宰許多環境。"},{"en":"If one group rules an ecosystem, other animals must compete with or avoid it.","zh":"如果一個類群主宰生態系統，其他動物必須與其競爭或避開它。"},{"en":"The phrase is dramatic and means dominance, not literal government.","zh":"這個片語帶戲劇性，意思是主導，而不是字面上的管治。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":2},{"front":"alleged mammalian dominance","meaning":"所謂的哺乳類動物主導地位","examples":[{"en":"Even 65 million years of alleged mammalian dominance did not wipe crocodiles out.","zh":"即使所謂的哺乳類動物主導地位持續了6500萬年，也未能令鱷魚滅絕。"},{"en":"Alleged mammalian dominance means the supposed or claimed period when mammals became the dominant animals.","zh":"alleged mammalian dominance 指據稱或所謂哺乳類動物成為主導動物的時期。"},{"en":"A writer may use “alleged” when they want to question whether a claim is fully true.","zh":"作者使用 alleged 時，可能想質疑某說法是否完全真確。"},{"en":"If mammals dominated the planet but crocodiles survived, that dominance was not enough to remove them.","zh":"如果哺乳類動物主宰地球但鱷魚仍存活，這種主導地位仍不足以消滅牠們。"},{"en":"The phrase carries a slightly sceptical tone.","zh":"這個片語帶有輕微懷疑語氣。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":2},{"front":"wipe them out","meaning":"將牠們消滅；令牠們滅絕","examples":[{"en":"Mammalian dominance did not wipe crocodiles out.","zh":"哺乳類動物的主導地位沒有將鱷魚消滅。"},{"en":"Wipe them out means destroy them completely or make them extinct.","zh":"wipe them out 指徹底摧毀牠們或令牠們滅絕。"},{"en":"A disease can wipe out a small crop field if farmers do not act quickly.","zh":"如果農民不迅速行動，疾病可以摧毀一小片農作物。"},{"en":"If a habitat disappears, it may wipe out animals that cannot move elsewhere.","zh":"如果棲息地消失，可能令無法遷往別處的動物滅絕。"},{"en":"The phrase is strong and means total destruction.","zh":"這個片語語氣強烈，意思是完全毀滅。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":2},{"front":"crocodiles and alligators","meaning":"鱷魚和短吻鱷","examples":[{"en":"Crocodiles and alligators are not very different from their prehistoric ancestors.","zh":"鱷魚和短吻鱷與牠們的史前祖先沒有太大不同。"},{"en":"Crocodiles and alligators are related reptiles with long bodies, strong jaws, and aquatic habits.","zh":"crocodiles and alligators 是有長身體、強壯顎部和水棲習性的相關爬行動物。"},{"en":"Zoo signs often explain the differences between crocodiles and alligators.","zh":"動物園標示常解釋鱷魚和短吻鱷的差異。"},{"en":"If both animals resemble their ancient relatives, their body design has remained useful.","zh":"如果兩者都像古代親族，其身體設計就一直有用。"},{"en":"The phrase names two closely related crocodilian animals.","zh":"這個片語指兩種關係密切的鱷類動物。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":2},{"front":"not that different from","meaning":"與……沒有那麼不同","examples":[{"en":"Modern crocodiles are not that different from their prehistoric ancestors.","zh":"現代鱷魚與牠們的史前祖先沒有那麼不同。"},{"en":"Not that different from means quite similar to someone or something else.","zh":"not that different from 指與某人或某物相當相似。"},{"en":"This year’s exam format is not that different from last year’s.","zh":"今年的考試形式與去年沒有那麼不同。"},{"en":"If a modern animal is not very different from its ancestors, its old body plan may still work well.","zh":"如果現代動物與祖先沒有太大不同，其舊有身體設計可能仍然有效。"},{"en":"The phrase reduces the sense of difference.","zh":"這個片語減弱差異感。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":2},{"front":"prehistoric ancestors","meaning":"史前祖先","examples":[{"en":"Modern crocodiles still resemble their prehistoric ancestors.","zh":"現代鱷魚仍然像牠們的史前祖先。"},{"en":"Prehistoric ancestors are earlier life forms that lived before written human history.","zh":"prehistoric ancestors 指生活在人類文字歷史以前的較早生命形態。"},{"en":"Fossils help scientists compare modern animals with their prehistoric ancestors.","zh":"化石幫助科學家比較現代動物與其史前祖先。"},{"en":"If a species resembles its prehistoric ancestors, some ancient features may still be useful.","zh":"如果物種像其史前祖先，一些古代特徵可能仍然有用。"},{"en":"The phrase connects present animals with ancient evolutionary history.","zh":"這個片語把現今動物與古老演化史連接起來。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":2},{"front":"proves that","meaning":"證明","examples":[{"en":"Their survival proves that crocodiles are incredibly adaptable.","zh":"牠們的生存證明鱷魚適應力極強。"},{"en":"Proves that means gives strong evidence showing something is true.","zh":"proves that 指提供有力證據顯示某事為真。"},{"en":"A student’s improved marks prove that regular practice can work.","zh":"學生成績提升證明定期練習可以有效。"},{"en":"If a species survives many disasters, this proves that its survival strategies are effective.","zh":"如果一個物種熬過許多災難，這證明其生存策略有效。"},{"en":"The phrase introduces evidence-based conclusion.","zh":"這個片語引出有證據支持的結論。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":3},{"front":"incredibly adaptable","meaning":"適應力極強的","examples":[{"en":"Crocodiles are incredibly adaptable animals.","zh":"鱷魚是適應力極強的動物。"},{"en":"Incredibly adaptable means able to adjust very well to different conditions.","zh":"incredibly adaptable 指能非常好地適應不同情況。"},{"en":"A good teacher is incredibly adaptable when lessons change suddenly because of student needs.","zh":"當課堂因學生需要突然改變時，好老師會表現得適應力極強。"},{"en":"If an animal is adaptable, it can survive changes in food, weather, or habitat.","zh":"如果動物適應力強，就能熬過食物、天氣或棲息地變化。"},{"en":"The phrase strongly praises flexibility and survival ability.","zh":"這個片語強烈讚賞靈活性和生存能力。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":3},{"front":"crocodile-like ancestors","meaning":"類似鱷魚的祖先","examples":[{"en":"The first crocodile-like ancestors came into existence approximately 230 million years ago.","zh":"第一批類似鱷魚的祖先大約在2.3億年前出現。"},{"en":"Crocodile-like ancestors were ancient animals that looked or functioned somewhat like crocodiles.","zh":"crocodile-like ancestors 指外形或功能有點像鱷魚的古代動物。"},{"en":"Scientists study fossils of crocodile-like ancestors to understand how modern crocodiles developed.","zh":"科學家研究類似鱷魚祖先的化石，以了解現代鱷魚如何發展。"},{"en":"If an ancestor is crocodile-like, it may already have features such as strong jaws or a long body.","zh":"如果祖先類似鱷魚，它可能已具有強壯顎部或長身體等特徵。"},{"en":"The phrase describes early relatives, not modern crocodiles themselves.","zh":"這個片語描述早期親族，而不是現代鱷魚本身。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":3},{"front":"came into existence","meaning":"出現；形成","examples":[{"en":"The first crocodile-like ancestors came into existence approximately 230 million years ago.","zh":"第一批類似鱷魚的祖先大約在2.3億年前出現。"},{"en":"Came into existence means began to exist or appeared for the first time.","zh":"came into existence 指開始存在或首次出現。"},{"en":"The school club came into existence when students asked for a place to practise debate.","zh":"當學生要求有地方練習辯論時，學校學會就形成了。"},{"en":"If a new species comes into existence, it has developed from earlier life forms.","zh":"如果新物種出現，它已由較早生命形態發展而來。"},{"en":"The phrase focuses on origin or beginning.","zh":"這個片語集中於起源或開始。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":3},{"front":"approximately","meaning":"大約","examples":[{"en":"Crocodile-like ancestors appeared approximately 230 million years ago.","zh":"類似鱷魚的祖先大約在2.3億年前出現。"},{"en":"Approximately means about or nearly, not exactly.","zh":"approximately 指大約或接近，而不是精確。"},{"en":"The bus journey takes approximately thirty minutes when traffic is normal.","zh":"在交通正常時，巴士旅程大約需三十分鐘。"},{"en":"If scientists say a fossil is approximately 200 million years old, the date is an estimate.","zh":"如果科學家說化石大約有兩億年歷史，該日期是估計。"},{"en":"The word is useful when exact numbers are impossible or unnecessary.","zh":"當精確數字不可能或不必要時，這個詞很有用。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":3},{"front":"features that make","meaning":"令……成為……的特徵","examples":[{"en":"Early crocodiles had many features that make crocodiles effective hunters.","zh":"早期鱷魚有許多令鱷魚成為有效獵手的特徵。"},{"en":"Features that make something effective are qualities that help it perform a task well.","zh":"features that make something effective 指幫助某物把任務做好的特質。"},{"en":"A phone has features that make studying easier, such as reminders and dictionaries.","zh":"手機有令學習更容易的功能，例如提醒和字典。"},{"en":"If an animal has features that make hunting easier, it is more likely to catch food.","zh":"如果動物有令獵食更容易的特徵，就更可能捕到食物。"},{"en":"The phrase links physical or practical qualities with their result.","zh":"這個片語把身體或實用特質與其結果連接起來。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":3},{"front":"highly effective stealth hunters","meaning":"非常有效率的潛伏獵手","examples":[{"en":"Crocodiles are highly effective stealth hunters.","zh":"鱷魚是非常有效率的潛伏獵手。"},{"en":"Highly effective stealth hunters are predators that catch prey very successfully by staying hidden and quiet.","zh":"highly effective stealth hunters 指透過隱藏和安靜行動而非常成功捕捉獵物的捕食者。"},{"en":"A cat can be a stealth hunter when it waits silently before jumping at a toy.","zh":"貓靜靜等待再撲向玩具時，可以是潛伏獵手。"},{"en":"If a hunter can approach without being noticed, its chance of success increases.","zh":"如果獵手能不被察覺地接近，成功機會就會增加。"},{"en":"The phrase combines skill, secrecy, and hunting success.","zh":"這個片語結合技巧、隱蔽和獵食成功。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":3},{"front":"a streamlined body","meaning":"流線型身體","examples":[{"en":"A streamlined body helps crocodiles move efficiently through water.","zh":"流線型身體幫助鱷魚有效地在水中移動。"},{"en":"A streamlined body is a smooth, narrow body shape that reduces resistance in water or air.","zh":"a streamlined body 指平滑、狹長、能減少水中或空氣阻力的身體形狀。"},{"en":"Racing bicycles and fast boats often have streamlined shapes.","zh":"賽車單車和快艇通常有流線型形狀。"},{"en":"If an animal has a streamlined body, it can move faster or use less energy.","zh":"如果動物有流線型身體，就能移動更快或用更少能量。"},{"en":"The phrase describes a body shape designed for efficient movement.","zh":"這個片語描述有利於高效移動的身體形狀。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":3},{"front":"protective armour","meaning":"防護甲殼","examples":[{"en":"Crocodiles have protective armour on their bodies.","zh":"鱷魚身上有防護甲殼。"},{"en":"Protective armour means hard covering that helps protect the body from injury.","zh":"protective armour 指幫助保護身體免受傷害的堅硬覆蓋物。"},{"en":"A cyclist wears a helmet as protective armour for the head.","zh":"單車手戴頭盔作為頭部防護。"},{"en":"If an animal has protective armour, attackers may find it harder to hurt it.","zh":"如果動物有防護甲殼，攻擊者可能較難傷害牠。"},{"en":"The phrase can describe natural body covering or human-made protection.","zh":"這個片語可描述天然身體覆蓋物或人造保護。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":3},{"front":"long jaws","meaning":"長顎","examples":[{"en":"Long jaws help crocodiles catch prey.","zh":"長顎幫助鱷魚捕捉獵物。"},{"en":"Long jaws are extended mouth structures that help an animal bite, grip, or catch food.","zh":"long jaws 指延長的口部結構，幫助動物咬住、抓緊或捕食。"},{"en":"A bird with long jaws or a long beak may catch fish more easily.","zh":"有長顎或長喙的鳥可能更容易捕魚。"},{"en":"If a predator has long jaws, it can grab prey from a greater distance.","zh":"如果捕食者有長顎，就能從較遠距離抓住獵物。"},{"en":"The phrase describes a body feature useful for feeding.","zh":"這個片語描述有利於進食的身體特徵。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":3},{"front":"webbed legs","meaning":"有蹼的腿","examples":[{"en":"Crocodiles have four short, webbed legs.","zh":"鱷魚有四條短而有蹼的腿。"},{"en":"Webbed legs have skin between the toes that helps an animal swim.","zh":"webbed legs 指腳趾之間有皮膜、有助游泳的腿。"},{"en":"Ducks have webbed feet that push water backward as they move.","zh":"鴨子有蹼足，移動時把水向後推。"},{"en":"If an animal lives near water, webbed legs or feet can improve swimming ability.","zh":"如果動物生活在水邊，有蹼的腿或腳可以提升游泳能力。"},{"en":"The phrase describes a body feature suited to aquatic movement.","zh":"這個片語描述適合水中移動的身體特徵。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":4},{"front":"capacity to move","meaning":"移動能力","examples":[{"en":"The crocodile’s capacity to move on the ground should not be underestimated.","zh":"鱷魚在地面上的移動能力不應被低估。"},{"en":"Capacity to move means ability to move physically from one place to another.","zh":"capacity to move 指從一處移到另一處的身體能力。"},{"en":"A patient’s capacity to move may improve after physiotherapy.","zh":"病人的移動能力可能在物理治療後改善。"},{"en":"If an animal has a strong capacity to move on land and in water, it can hunt in more places.","zh":"如果動物在陸地和水中都有強移動能力，就能在更多地方獵食。"},{"en":"The phrase focuses on ability, not just actual movement.","zh":"這個片語集中於能力，而不只是實際移動。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":4},{"front":"on the ground","meaning":"在地面上","examples":[{"en":"Crocodiles can move surprisingly quickly on the ground.","zh":"鱷魚在地面上可以出奇地快速移動。"},{"en":"On the ground means on land or on the surface beneath one’s feet.","zh":"on the ground 指在陸地上或腳下的表面上。"},{"en":"Children should not leave toys on the ground where people may trip.","zh":"孩子不應把玩具留在地面上，以免別人絆倒。"},{"en":"If crocodiles can move fast on the ground, people near riverbanks must stay alert.","zh":"如果鱷魚能在地面上快速移動，河岸附近的人必須保持警覺。"},{"en":"The phrase contrasts land movement with movement in water or air.","zh":"這個片語把陸地移動與水中或空中移動作對比。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":4},{"front":"should not be underestimated","meaning":"不應被低估","examples":[{"en":"Their ability to move on land should not be underestimated.","zh":"牠們在陸地上移動的能力不應被低估。"},{"en":"Should not be underestimated means should not be judged as weaker, smaller, or less important than it really is.","zh":"should not be underestimated 指不應把某事判斷得比實際更弱、更小或更不重要。"},{"en":"A quiet student’s ability should not be underestimated because they may perform well in exams.","zh":"安靜學生的能力不應被低估，因為他們可能在考試中表現很好。"},{"en":"If danger is underestimated, people may take careless risks.","zh":"如果危險被低估，人們可能冒下粗心風險。"},{"en":"The phrase warns readers to take something seriously.","zh":"這個片語提醒讀者認真看待某事。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":4},{"front":"get too close","meaning":"靠得太近","examples":[{"en":"Anyone who gets too close to a hunting crocodile may be in danger.","zh":"任何靠得太近正在獵食的鱷魚的人都可能有危險。"},{"en":"Get too close means move nearer than is safe or sensible.","zh":"get too close 指移得比安全或合理距離更近。"},{"en":"Children should not get too close to a hot stove.","zh":"孩子不應靠火爐太近。"},{"en":"If people get too close to wild animals, they may be attacked or injured.","zh":"如果人們靠野生動物太近，可能被攻擊或受傷。"},{"en":"The phrase often appears in warnings about safety.","zh":"這個片語常出現在安全警告中。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":4},{"front":"while they are hunting","meaning":"在牠們獵食時","examples":[{"en":"Crocodiles can move very quickly while they are hunting.","zh":"鱷魚在牠們獵食時可以移動得非常快。"},{"en":"While they are hunting means during the time when they are looking for or attacking prey.","zh":"while they are hunting 指牠們正在尋找或攻擊獵物的期間。"},{"en":"Cats often become quiet and focused while they are hunting insects at home.","zh":"貓在家中獵捕昆蟲時，通常變得安靜而專注。"},{"en":"If animals move faster while hunting, prey have less time to escape.","zh":"如果動物在獵食時移動更快，獵物逃走的時間就更少。"},{"en":"The phrase describes what happens during the hunting process.","zh":"這個片語描述獵食過程期間發生的事情。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":4},{"front":"may not get a second chance","meaning":"可能沒有第二次機會","examples":[{"en":"A person who gets too close may not get a second chance.","zh":"靠得太近的人可能沒有第二次機會。"},{"en":"May not get a second chance means may not have another opportunity to correct a dangerous mistake.","zh":"may not get a second chance 指可能沒有另一次機會去改正危險錯誤。"},{"en":"If a driver ignores a red light near a truck, they may not get a second chance.","zh":"如果司機在貨車附近衝紅燈，可能沒有第二次機會。"},{"en":"When danger is immediate, one careless action can have final consequences.","zh":"當危險即時存在，一個粗心行動可能帶來最終後果。"},{"en":"The phrase is a serious warning.","zh":"這個片語是嚴重警告。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":4},{"front":"like other reptiles","meaning":"像其他爬行動物一樣","examples":[{"en":"Like other reptiles, crocodiles depend on external heat.","zh":"像其他爬行動物一樣，鱷魚依賴外部熱量。"},{"en":"Like other reptiles means in the same way as other animals in the reptile group.","zh":"like other reptiles 指與爬行動物類群中的其他動物一樣。"},{"en":"Like other students, new classmates need time to learn school routines.","zh":"像其他學生一樣，新同學需要時間學習學校常規。"},{"en":"If crocodiles share a feature with other reptiles, that feature helps classify them.","zh":"如果鱷魚與其他爬行動物共有某特徵，該特徵有助分類。"},{"en":"The phrase introduces similarity with a larger group.","zh":"這個片語引出與更大群體的相似之處。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":4},{"front":"poikilothermal animals","meaning":"變溫動物","examples":[{"en":"Crocodiles are poikilothermal animals.","zh":"鱷魚是變溫動物。"},{"en":"Poikilothermal animals are animals whose body temperature changes with the temperature around them.","zh":"poikilothermal animals 指體溫會隨周圍溫度改變的動物。"},{"en":"Many reptiles and fish are poikilothermal animals.","zh":"許多爬行動物和魚類都是變溫動物。"},{"en":"If an animal is poikilothermal, it may need sunlight, shade, or water to manage body temperature.","zh":"如果動物是變溫動物，可能需要陽光、陰影或水來管理體溫。"},{"en":"The term is scientific and is often explained as cold-blooded.","zh":"這是科學術語，常被解釋為冷血動物。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":4},{"front":"commonly known as","meaning":"通常稱為","examples":[{"en":"Poikilothermal animals are commonly known as cold-blooded animals.","zh":"變溫動物通常稱為冷血動物。"},{"en":"Commonly known as means usually called by a simpler or more familiar name.","zh":"commonly known as 指通常以較簡單或較熟悉的名字稱呼。"},{"en":"Sodium chloride is commonly known as salt.","zh":"氯化鈉通常稱為鹽。"},{"en":"If a scientific term is difficult, writers often add the name it is commonly known as.","zh":"如果科學術語很困難，作者常加入它通常被稱為甚麼。"},{"en":"The phrase connects a technical term with an everyday term.","zh":"這個片語把技術術語與日常用語連接起來。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":4},{"front":"cold-blooded","meaning":"冷血的","examples":[{"en":"Crocodiles are commonly known as cold-blooded animals.","zh":"鱷魚通常被稱為冷血動物。"},{"en":"Cold-blooded means an animal depends on external heat to control its body temperature.","zh":"cold-blooded 指動物依賴外部熱量來控制體溫。"},{"en":"A cold-blooded lizard may lie on a warm rock in the morning.","zh":"冷血蜥蜴早上可能躺在暖石上。"},{"en":"If the environment is too cold, a cold-blooded animal may become slow.","zh":"如果環境太冷，冷血動物可能變得遲緩。"},{"en":"The word is common, but “poikilothermal” is the more scientific term.","zh":"這個詞很常見，但 poikilothermal 是較科學的術語。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":5},{"front":"body temperature","meaning":"體溫","examples":[{"en":"A crocodile’s body temperature changes with its surroundings.","zh":"鱷魚的體溫會隨周圍環境改變。"},{"en":"Body temperature is the level of heat inside an animal’s or person’s body.","zh":"body temperature 指動物或人體內的熱度水平。"},{"en":"A nurse checks body temperature to see whether a patient has a fever.","zh":"護士量度體溫，以查看病人是否發燒。"},{"en":"If body temperature becomes too high or too low, normal functions can be affected.","zh":"如果體溫變得太高或太低，正常功能可能受影響。"},{"en":"The phrase is important in health and biology.","zh":"這個片語在健康和生物學中很重要。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":5},{"front":"changes with","meaning":"隨……而改變","examples":[{"en":"Their body temperature changes with the temperature of the surroundings.","zh":"牠們的體溫會隨周圍環境溫度而改變。"},{"en":"Changes with means becomes different when another thing becomes different.","zh":"changes with 指當另一事物改變時，某事也跟着改變。"},{"en":"Clothing choices change with the weather.","zh":"衣着選擇會隨天氣而改變。"},{"en":"If body temperature changes with the environment, the animal must use behaviour to stay safe.","zh":"如果體溫隨環境改變，動物必須透過行為保持安全。"},{"en":"The phrase shows a relationship between two changing things.","zh":"這個片語顯示兩件會變化事物之間的關係。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":5},{"front":"the surroundings","meaning":"周圍環境","examples":[{"en":"The body temperature of a crocodile changes with that of the surroundings.","zh":"鱷魚的體溫會隨周圍環境的溫度而改變。"},{"en":"The surroundings are the environment, objects, and conditions around a person or animal.","zh":"the surroundings 指人或動物周圍的環境、物件和條件。"},{"en":"A student may concentrate better when the surroundings are quiet and tidy.","zh":"當周圍環境安靜整潔時，學生可能更能集中。"},{"en":"If surroundings are too hot, a crocodile may move into water or shade.","zh":"如果周圍環境太熱，鱷魚可能移入水中或陰涼處。"},{"en":"The phrase refers to what is around something.","zh":"這個片語指某物周圍的一切。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":5},{"front":"consequently","meaning":"因此","examples":[{"en":"Crocodiles are cold-blooded and consequently need regular sunlight.","zh":"鱷魚是冷血動物，因此需要定期曬太陽。"},{"en":"Consequently means as a result.","zh":"consequently 指作為結果。"},{"en":"The train was cancelled; consequently, many students arrived late.","zh":"火車取消；因此許多學生遲到。"},{"en":"If an animal cannot produce enough internal heat, it consequently depends on outside warmth.","zh":"如果動物不能產生足夠內部熱量，因此會依賴外部溫暖。"},{"en":"The word introduces a logical result.","zh":"這個詞引出邏輯結果。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":5},{"front":"require regular exposure to sunlight","meaning":"需要定期曬太陽","examples":[{"en":"Crocodiles require regular exposure to sunlight.","zh":"鱷魚需要定期曬太陽。"},{"en":"Require regular exposure to sunlight means need to be in sunlight often enough to stay healthy or warm.","zh":"require regular exposure to sunlight 指需要經常接觸陽光，以保持健康或溫暖。"},{"en":"Some plants require regular exposure to sunlight to grow strong leaves.","zh":"有些植物需要定期曬太陽，才能長出強壯葉子。"},{"en":"If crocodiles do not get sunlight, their body temperature may not rise enough.","zh":"如果鱷魚得不到陽光，體溫可能升得不夠高。"},{"en":"The phrase shows a repeated need, not a one-time action.","zh":"這個片語顯示重複需要，而不是一次性行動。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":5},{"front":"exposure to sunlight","meaning":"接觸陽光；曬太陽","examples":[{"en":"Regular exposure to sunlight helps crocodiles raise their body temperature.","zh":"定期接觸陽光幫助鱷魚提高體溫。"},{"en":"Exposure to sunlight means being in contact with sunlight.","zh":"exposure to sunlight 指接觸陽光。"},{"en":"Short exposure to sunlight can help people produce vitamin D.","zh":"短時間接觸陽光可以幫助人產生維他命D。"},{"en":"If exposure to sunlight is excessive, skin can be damaged.","zh":"如果接觸陽光過多，皮膚可能受損。"},{"en":"The phrase can describe useful or harmful contact, depending on amount.","zh":"這個片語可描述有益或有害的接觸，視乎份量。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":5},{"front":"raise body temperature","meaning":"提高體溫","examples":[{"en":"Crocodiles use sunlight to raise body temperature.","zh":"鱷魚利用陽光提高體溫。"},{"en":"Raise body temperature means make the body warmer.","zh":"raise body temperature 指令身體變暖。"},{"en":"A person may wear a coat to raise body temperature in cold weather.","zh":"人在寒冷天氣可能穿外套來提高體溫。"},{"en":"If a cold-blooded animal raises body temperature, it can move and digest more effectively.","zh":"如果冷血動物提高體溫，就能更有效移動和消化。"},{"en":"The phrase describes increasing internal warmth.","zh":"這個片語描述增加體內熱度。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":5},{"front":"would rather stay in","meaning":"寧願留在……","examples":[{"en":"When it is too hot, crocodiles would rather stay in water or shade.","zh":"當天氣太熱時，鱷魚寧願留在水中或陰涼處。"},{"en":"Would rather stay in means prefer to remain in a particular place instead of going elsewhere.","zh":"would rather stay in 指較喜歡留在某個地方，而不是去其他地方。"},{"en":"On a rainy day, students may rather stay in the library than play outside.","zh":"下雨天，學生可能寧願留在圖書館，而不是到外面玩。"},{"en":"If the weather is too hot, staying in shade can help animals avoid overheating.","zh":"如果天氣太熱，留在陰涼處可幫助動物避免過熱。"},{"en":"The phrase expresses preference.","zh":"這個片語表達偏好。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":5},{"front":"water or shade","meaning":"水中或陰涼處","examples":[{"en":"When it is too hot, crocodiles stay in water or shade.","zh":"當天氣太熱時，鱷魚會留在水中或陰涼處。"},{"en":"Water or shade means cooler places that protect an animal from direct heat.","zh":"water or shade 指能保護動物免受直接高溫的較涼地方。"},{"en":"During a hot sports day, students should rest in water stations or shade areas.","zh":"在炎熱運動日，學生應在飲水站或陰涼處休息。"},{"en":"If animals stay in water or shade, they can reduce heat stress.","zh":"如果動物留在水中或陰涼處，就能減少熱壓力。"},{"en":"The phrase names two common ways to cool down.","zh":"這個片語指出兩種常見降溫方法。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":5},{"front":"compared with","meaning":"與……相比","examples":[{"en":"Compared with mammals and birds, crocodiles have a slower metabolism.","zh":"與哺乳類動物和鳥類相比，鱷魚的新陳代謝較慢。"},{"en":"Compared with means when one thing is judged beside another thing.","zh":"compared with 指把一件事物放在另一件事物旁邊判斷。"},{"en":"Compared with buses, trains may be faster during rush hour.","zh":"與巴士相比，火車在繁忙時間可能更快。"},{"en":"If crocodiles are compared with mammals, their lower energy needs become clearer.","zh":"如果把鱷魚與哺乳類動物比較，牠們較低的能量需求會更清楚。"},{"en":"The phrase introduces comparison.","zh":"這個片語引出比較。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":6},{"front":"a slower metabolism","meaning":"較慢的新陳代謝","examples":[{"en":"Crocodiles have a slower metabolism than mammals and birds.","zh":"鱷魚的新陳代謝比哺乳類動物和鳥類慢。"},{"en":"A slower metabolism means the body uses energy more slowly.","zh":"a slower metabolism 指身體使用能量的速度較慢。"},{"en":"Some animals with slower metabolism do not need to eat as often.","zh":"有些新陳代謝較慢的動物不需要那麼經常進食。"},{"en":"If metabolism is slower, an animal may survive longer during food shortages.","zh":"如果新陳代謝較慢，動物可能在食物短缺時存活更久。"},{"en":"The phrase is important when explaining energy use.","zh":"這個片語在解釋能量使用時很重要。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":6},{"front":"less vulnerable to","meaning":"較不易受……影響","examples":[{"en":"A slower metabolism makes crocodiles less vulnerable to food shortage.","zh":"較慢的新陳代謝令鱷魚較不易受食物短缺影響。"},{"en":"Less vulnerable to means less likely to be harmed by something.","zh":"less vulnerable to 指較不容易被某事傷害。"},{"en":"A student with good savings is less vulnerable to sudden school expenses.","zh":"有良好儲蓄的學生較不易受突然學校開支影響。"},{"en":"If animals need less food, they are less vulnerable when prey becomes scarce.","zh":"如果動物需要較少食物，當獵物變少時就較不脆弱。"},{"en":"The phrase compares risk or weakness.","zh":"這個片語比較風險或弱點。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":6},{"front":"food shortage","meaning":"食物短缺","examples":[{"en":"Crocodiles are less vulnerable to food shortage than many mammals.","zh":"鱷魚比許多哺乳類動物較不易受食物短缺影響。"},{"en":"Food shortage means there is not enough food available.","zh":"food shortage 指可取得的食物不足。"},{"en":"A village may face food shortage after floods destroy crops.","zh":"水災毀壞農作物後，村莊可能面對食物短缺。"},{"en":"If food shortage lasts for months, animals with high energy needs may die first.","zh":"如果食物短缺持續數月，能量需求高的動物可能先死亡。"},{"en":"The phrase describes a lack of food in an environment or community.","zh":"這個片語描述環境或社區中的食物不足。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":6},{"front":"in the most extreme case","meaning":"在最極端的情況下","examples":[{"en":"In the most extreme case, a crocodile can survive without food for a whole year.","zh":"在最極端的情況下，鱷魚可以沒有食物也存活一整年。"},{"en":"In the most extreme case means in the most unusual or severe situation.","zh":"in the most extreme case 指在最不尋常或最嚴重的情況下。"},{"en":"In the most extreme case, a patient may need emergency surgery.","zh":"在最極端的情況下，病人可能需要緊急手術。"},{"en":"If a writer uses this phrase, the example is not normal but shows the upper limit.","zh":"如果作者使用這個片語，例子並不普通，而是顯示上限。"},{"en":"The phrase warns that the example is exceptional.","zh":"這個片語提醒例子屬例外情況。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":6},{"front":"slow its metabolism down","meaning":"降低其新陳代謝速度","examples":[{"en":"A crocodile can slow its metabolism down even further.","zh":"鱷魚可以進一步降低其新陳代謝速度。"},{"en":"Slow its metabolism down means reduce the speed at which the body uses energy.","zh":"slow its metabolism down 指降低身體使用能量的速度。"},{"en":"Some animals slow their metabolism down during winter to save energy.","zh":"有些動物在冬天降低新陳代謝速度以節省能量。"},{"en":"If a crocodile slows its metabolism, it needs less food to stay alive.","zh":"如果鱷魚降低新陳代謝，就需要較少食物維持生命。"},{"en":"The phrase describes an energy-saving process.","zh":"這個片語描述節省能量的過程。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":6},{"front":"to the point that","meaning":"到……的程度","examples":[{"en":"A crocodile can slow its metabolism to the point that it survives without food for a year.","zh":"鱷魚可以把新陳代謝降低到沒有食物也能生存一年之久。"},{"en":"To the point that means so much that a particular result happens.","zh":"to the point that 指到某種程度，以致出現某結果。"},{"en":"The room became noisy to the point that the teacher had to stop the activity.","zh":"課室變得吵到老師不得不停止活動。"},{"en":"If energy use falls to the point that food is barely needed, survival time can increase greatly.","zh":"如果能量使用降低到幾乎不需要食物的程度，生存時間可以大幅增加。"},{"en":"The phrase connects degree with result.","zh":"這個片語把程度與結果連接起來。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":6},{"front":"survive without food","meaning":"沒有食物也能生存","examples":[{"en":"A crocodile can survive without food for a whole year.","zh":"鱷魚可以沒有食物也生存一整年。"},{"en":"Survive without food means stay alive even when no food is eaten.","zh":"survive without food 指即使沒有進食仍能活着。"},{"en":"Some insects can survive without food for a long time in cold conditions.","zh":"有些昆蟲在寒冷環境中可以長時間沒有食物也生存。"},{"en":"If an animal stores energy well, it may survive without food during drought.","zh":"如果動物善於儲存能量，可能在乾旱期間沒有食物也能生存。"},{"en":"The phrase describes endurance during starvation.","zh":"這個片語描述飢餓期間的忍耐力。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":6},{"front":"for a whole year","meaning":"長達一整年","examples":[{"en":"Some crocodiles can survive without food for a whole year.","zh":"有些鱷魚可以沒有食物也生存長達一整年。"},{"en":"For a whole year means for twelve full months.","zh":"for a whole year 指完整十二個月。"},{"en":"A student may study abroad for a whole year before returning home.","zh":"學生可能出國留學一整年後才回家。"},{"en":"If an animal survives without food for a whole year, its energy use must be extremely low.","zh":"如果動物沒有食物也能生存一整年，其能量使用必然極低。"},{"en":"The phrase stresses the length of time.","zh":"這個片語強調時間長度。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":6},{"front":"enabling crocodiles to","meaning":"使鱷魚能夠……","examples":[{"en":"A slow metabolism helps conserve energy, enabling crocodiles to outlive mammals.","zh":"緩慢的新陳代謝有助保存能量，使鱷魚能夠比哺乳類動物存活得更久。"},{"en":"Enabling crocodiles to means making it possible for crocodiles to do something.","zh":"enabling crocodiles to 指令鱷魚有可能做某事。"},{"en":"Strong legs enable athletes to run faster and jump higher.","zh":"強壯雙腿使運動員能夠跑得更快、跳得更高。"},{"en":"If slow metabolism saves energy, it enables crocodiles to survive long food shortages.","zh":"如果緩慢代謝節省能量，就使鱷魚能熬過長時間食物短缺。"},{"en":"The phrase links a cause with what becomes possible.","zh":"這個片語把原因與變得可能的事情連接起來。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":6},{"front":"outlive mammals","meaning":"比哺乳類動物存活得更久","examples":[{"en":"Crocodiles can outlive mammals in volatile environments.","zh":"鱷魚能在多變環境中比哺乳類動物存活得更久。"},{"en":"Outlive mammals means live longer than mammals or survive when mammals do not.","zh":"outlive mammals 指比哺乳類動物活得更久，或在哺乳類動物不能生存時仍存活。"},{"en":"Some trees outlive humans by hundreds of years.","zh":"有些樹木比人類活得長數百年。"},{"en":"If crocodiles need less food, they may outlive mammals during harsh periods.","zh":"如果鱷魚需要較少食物，就可能在嚴酷時期比哺乳類動物存活得更久。"},{"en":"The phrase compares survival length between groups.","zh":"這個片語比較不同類群的生存長度。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":7},{"front":"relatively volatile environments","meaning":"相對多變的環境","examples":[{"en":"Crocodiles can survive in relatively volatile environments.","zh":"鱷魚能在相對多變的環境中生存。"},{"en":"Relatively volatile environments are environments that change often or unpredictably compared with others.","zh":"relatively volatile environments 指與其他環境相比，經常或難以預測地改變的環境。"},{"en":"A small business in a tourist area may face a relatively volatile market.","zh":"旅遊區的小企業可能面對相對多變的市場。"},{"en":"If an animal survives volatile environments, it must cope with change well.","zh":"如果動物能在多變環境中生存，就必須善於應對變化。"},{"en":"The phrase describes conditions that are somewhat unstable.","zh":"這個片語描述某程度上不穩定的條件。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":7},{"front":"a highly efficient way to","meaning":"非常有效率的……方法","examples":[{"en":"Crocodiles have a highly efficient way to catch prey.","zh":"鱷魚有非常有效率的捕捉獵物方法。"},{"en":"A highly efficient way to do something is a method that works well with little wasted effort.","zh":"a highly efficient way to do something 指能以很少浪費努力而做得好的方法。"},{"en":"Using a checklist is a highly efficient way to avoid mistakes before submitting homework.","zh":"使用清單是交功課前避免錯誤的非常有效率方法。"},{"en":"If a hunting method saves energy and succeeds often, it is highly efficient.","zh":"如果獵食方法節省能量且經常成功，它就非常有效率。"},{"en":"The phrase praises a method for being effective and economical.","zh":"這個片語讚賞方法有效且省力。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":7},{"front":"catch prey","meaning":"捕捉獵物","examples":[{"en":"Crocodiles have a highly efficient way to catch prey.","zh":"鱷魚有非常有效率的方法捕捉獵物。"},{"en":"Catch prey means capture an animal for food.","zh":"catch prey 指捕獲動物作為食物。"},{"en":"A spider uses a web to catch prey such as flies.","zh":"蜘蛛用蜘蛛網捕捉蒼蠅等獵物。"},{"en":"If a predator cannot catch prey, it may go hungry or move elsewhere.","zh":"如果捕食者不能捕捉獵物，可能挨餓或遷往別處。"},{"en":"The phrase is common in descriptions of hunting animals.","zh":"這個片語常見於描述獵食動物。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":7},{"front":"the prey","meaning":"獵物","examples":[{"en":"The prey rarely realises that a crocodile may be under the water.","zh":"獵物很少察覺鱷魚可能在水下。"},{"en":"The prey is the animal that is hunted and eaten by another animal.","zh":"the prey 指被另一種動物獵捕並吃掉的動物。"},{"en":"A mouse can be the prey of an owl.","zh":"老鼠可以是貓頭鷹的獵物。"},{"en":"If prey cannot detect a predator, the predator has a greater chance of success.","zh":"如果獵物不能察覺捕食者，捕食者成功機會更大。"},{"en":"The phrase contrasts with predator, the animal that hunts.","zh":"這個片語與 predator 形成對比，predator 是獵食者。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":7},{"front":"rarely realises","meaning":"很少察覺","examples":[{"en":"The prey rarely realises that a crocodile is nearby.","zh":"獵物很少察覺鱷魚就在附近。"},{"en":"Rarely realises means usually does not notice or understand something.","zh":"rarely realises 指通常沒有注意到或理解某事。"},{"en":"A student rarely realises how much time is lost when checking a phone every few minutes.","zh":"學生很少察覺每隔幾分鐘看手機會浪費多少時間。"},{"en":"If prey rarely realises danger is near, an ambush becomes easier.","zh":"如果獵物很少察覺危險接近，伏擊就更容易。"},{"en":"The phrase shows that awareness happens only occasionally.","zh":"這個片語顯示只有偶爾才有意識。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":7},{"front":"under the water","meaning":"在水下","examples":[{"en":"A crocodile may wait silently under the water.","zh":"鱷魚可能靜靜地在水下等待。"},{"en":"Under the water means below the surface of water.","zh":"under the water 指在水面以下。"},{"en":"Swimmers can see fish under the water if the sea is clear.","zh":"如果海水清澈，游泳者可以看見水下的魚。"},{"en":"If a predator hides under the water, animals at the edge may not see it.","zh":"如果捕食者藏在水下，水邊動物可能看不見牠。"},{"en":"The phrase describes position below the water surface.","zh":"這個片語描述水面以下的位置。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":7},{"front":"moves quietly","meaning":"靜靜地移動","examples":[{"en":"The crocodile moves quietly when it spots its prey.","zh":"鱷魚發現獵物時會靜靜地移動。"},{"en":"Moves quietly means moves with little noise or disturbance.","zh":"moves quietly 指移動時幾乎沒有聲音或干擾。"},{"en":"A student may move quietly into the classroom when arriving late.","zh":"學生遲到時可能靜靜地走進課室。"},{"en":"If a hunter moves quietly, the target is less likely to notice danger.","zh":"如果獵手靜靜地移動，目標較不容易察覺危險。"},{"en":"The phrase describes careful, silent movement.","zh":"這個片語描述小心而安靜的移動。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":7},{"front":"creates little vibration","meaning":"產生很少震動","examples":[{"en":"The crocodile creates little vibration when it moves.","zh":"鱷魚移動時產生很少震動。"},{"en":"Creates little vibration means produces only small movements or shaking in the water or ground.","zh":"creates little vibration 指在水中或地面只產生很小的移動或震動。"},{"en":"A quiet washing machine creates little vibration and does not disturb neighbours.","zh":"安靜洗衣機產生很少震動，不會打擾鄰居。"},{"en":"If a crocodile creates little vibration, prey may not detect its approach.","zh":"如果鱷魚產生很少震動，獵物可能察覺不到牠接近。"},{"en":"The phrase explains how silent movement helps stealth.","zh":"這個片語解釋安靜移動如何幫助潛伏。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":7},{"front":"spots its prey","meaning":"發現獵物","examples":[{"en":"The crocodile moves quietly when it spots its prey.","zh":"鱷魚發現獵物時會靜靜地移動。"},{"en":"Spots its prey means sees or notices the animal it wants to catch.","zh":"spots its prey 指看見或注意到牠想捕捉的動物。"},{"en":"A cat may freeze when it spots a bird in the garden.","zh":"貓在花園中發現鳥時可能突然停住。"},{"en":"If a predator spots its prey before being noticed, it gains an advantage.","zh":"如果捕食者在被察覺前發現獵物，就取得優勢。"},{"en":"The phrase marks the moment hunting begins.","zh":"這個片語標示獵食開始的一刻。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":7},{"front":"above the water level","meaning":"在水面以上","examples":[{"en":"The crocodile keeps only its eyes above the water level.","zh":"鱷魚只把眼睛保持在水面以上。"},{"en":"Above the water level means higher than the surface of the water.","zh":"above the water level 指高於水面。"},{"en":"A swimmer keeps their mouth above the water level to breathe.","zh":"游泳者把嘴保持在水面以上以呼吸。"},{"en":"If only the eyes are above the water level, the rest of the body remains hidden.","zh":"如果只有眼睛在水面以上，身體其餘部分仍被隱藏。"},{"en":"The phrase describes exact position relative to water.","zh":"這個片語描述相對水面的準確位置。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":8},{"front":"as soon as","meaning":"一……就……","examples":[{"en":"As soon as it is close enough, the crocodile attacks.","zh":"鱷魚一足夠接近就會攻擊。"},{"en":"As soon as means immediately when something happens.","zh":"as soon as 指某事一發生就立即。"},{"en":"Students should start writing as soon as the exam begins.","zh":"考試一開始，學生就應開始寫作。"},{"en":"If a predator attacks as soon as it is close enough, the prey has little time to escape.","zh":"如果捕食者一足夠接近就攻擊，獵物就幾乎沒有時間逃走。"},{"en":"The phrase shows quick action after a condition is met.","zh":"這個片語顯示條件達成後迅速行動。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":8},{"front":"close enough to","meaning":"足夠接近……","examples":[{"en":"The crocodile attacks when it is close enough to the victim.","zh":"當鱷魚足夠接近受害者時，就會攻擊。"},{"en":"Close enough to means near enough for a particular action to become possible.","zh":"close enough to 指距離足夠近，使某行動變得可能。"},{"en":"A student must sit close enough to the board to read the writing clearly.","zh":"學生必須坐得足夠接近黑板，才能清楚看字。"},{"en":"If a crocodile gets close enough to prey, a sudden attack can succeed.","zh":"如果鱷魚足夠接近獵物，突然攻擊就可能成功。"},{"en":"The phrase links distance with possibility.","zh":"這個片語把距離與可能性連接起來。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":8},{"front":"jerks out of the water","meaning":"從水中猛然衝出","examples":[{"en":"The crocodile jerks out of the water with its jaws wide open.","zh":"鱷魚張大顎部從水中猛然衝出。"},{"en":"Jerks out of the water means suddenly moves upward or outward from the water with force.","zh":"jerks out of the water 指突然用力從水中向上或向外移動。"},{"en":"A fish may jerk out of the water when it is hooked.","zh":"魚被魚鉤勾住時可能從水中猛然跳出。"},{"en":"If a crocodile jerks out suddenly, prey may have no time to react.","zh":"如果鱷魚突然衝出，獵物可能沒有時間反應。"},{"en":"The phrase describes a quick violent movement.","zh":"這個片語描述迅速而猛烈的動作。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":8},{"front":"wide-open jaws","meaning":"張大的顎","examples":[{"en":"The crocodile attacks with its wide-open jaws.","zh":"鱷魚以張大的顎攻擊。"},{"en":"Wide-open jaws are jaws opened as widely as possible.","zh":"wide-open jaws 指盡可能張開的顎部。"},{"en":"A dog may show wide-open jaws when yawning, not only when biting.","zh":"狗打呵欠時也可能露出張大的顎，不只是咬東西時。"},{"en":"If a predator attacks with wide-open jaws, it is ready to grab prey.","zh":"如果捕食者以張大的顎攻擊，就是準備抓住獵物。"},{"en":"The phrase creates a strong image of danger.","zh":"這個片語形成強烈的危險畫面。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":8},{"front":"capable of switching","meaning":"能夠轉換","examples":[{"en":"Crocodiles are capable of switching feeding methods.","zh":"鱷魚能夠轉換覓食方法。"},{"en":"Capable of switching means able to change from one method or behaviour to another.","zh":"capable of switching 指能由一種方法或行為轉到另一種。"},{"en":"A good teacher is capable of switching activities when students lose focus.","zh":"好老師在學生失去專注時能夠轉換活動。"},{"en":"If animals can switch feeding methods, they can survive when one food source is scarce.","zh":"如果動物能轉換覓食方法，當某種食物來源稀少時也能生存。"},{"en":"The phrase highlights flexibility.","zh":"這個片語突出靈活性。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":8},{"front":"feeding methods","meaning":"覓食方法","examples":[{"en":"Crocodiles can switch feeding methods.","zh":"鱷魚可以轉換覓食方法。"},{"en":"Feeding methods are the ways animals find, catch, or eat food.","zh":"feeding methods 指動物尋找、捕捉或進食食物的方法。"},{"en":"Birds have different feeding methods, such as pecking seeds or catching insects.","zh":"鳥類有不同覓食方法，例如啄食種子或捕捉昆蟲。"},{"en":"If one feeding method fails, an animal with another method has a better chance of survival.","zh":"如果一種覓食方法失敗，擁有另一種方法的動物生存機會較高。"},{"en":"The phrase describes how food is obtained.","zh":"這個片語描述食物如何取得。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":8},{"front":"chase fish","meaning":"追捕魚類","examples":[{"en":"Crocodiles chase fish in the water.","zh":"鱷魚在水中追捕魚類。"},{"en":"Chase fish means swim after fish in order to catch them.","zh":"chase fish 指在水中追着魚，以捕捉牠們。"},{"en":"Children may watch dolphins chase fish in a nature documentary.","zh":"孩子可能在自然紀錄片中觀看海豚追捕魚類。"},{"en":"If water is deep and clear, predators may chase fish more easily.","zh":"如果水又深又清，捕食者可能更容易追捕魚類。"},{"en":"The phrase describes active pursuit, not waiting quietly.","zh":"這個片語描述主動追逐，而不是靜靜等待。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":8},{"front":"snatch birds","meaning":"迅速抓住鳥類","examples":[{"en":"Crocodiles can snatch birds at the water surface.","zh":"鱷魚可以在水面迅速抓住鳥類。"},{"en":"Snatch birds means grab birds suddenly and quickly.","zh":"snatch birds 指突然快速抓住鳥。"},{"en":"A cat may snatch a toy bird when it swings past.","zh":"當玩具鳥擺過時，貓可能迅速抓住它。"},{"en":"If birds land too close to water, crocodiles may snatch them before they fly away.","zh":"如果鳥停在離水太近的地方，鱷魚可能在牠們飛走前迅速抓住牠們。"},{"en":"The phrase suggests sudden grabbing.","zh":"這個片語暗示突然抓取。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":8},{"front":"at the water surface","meaning":"在水面上","examples":[{"en":"Crocodiles snatch birds at the water surface.","zh":"鱷魚在水面上迅速抓住鳥類。"},{"en":"At the water surface means at the top layer where water meets the air.","zh":"at the water surface 指水與空氣接觸的最上層。"},{"en":"Leaves may float at the water surface after rain.","zh":"雨後葉子可能漂浮在水面上。"},{"en":"If birds feed at the water surface, hidden predators can attack from below.","zh":"如果鳥在水面覓食，隱藏的捕食者可從下方攻擊。"},{"en":"The phrase describes a position on top of water.","zh":"這個片語描述水頂部的位置。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":8},{"front":"waterside bushes","meaning":"水邊灌木叢","examples":[{"en":"Crocodiles hide in waterside bushes while waiting for prey.","zh":"鱷魚等待獵物時會藏在水邊灌木叢中。"},{"en":"Waterside bushes are bushes growing near the edge of a river, lake, or pond.","zh":"waterside bushes 指生長在河、湖或池塘邊的灌木叢。"},{"en":"Walkers should be careful near waterside bushes in areas where wild animals live.","zh":"在有野生動物生活的地區，行人應小心水邊灌木叢。"},{"en":"If a predator hides in waterside bushes, prey may not notice it until too late.","zh":"如果捕食者藏在水邊灌木叢中，獵物可能太遲才察覺。"},{"en":"The phrase describes vegetation beside water.","zh":"這個片語描述水邊植物。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":9},{"front":"in anticipation of","meaning":"預期；等待","examples":[{"en":"A crocodile may hide in anticipation of a gazelle.","zh":"鱷魚可能藏起來等待瞪羚。"},{"en":"In anticipation of means expecting something to happen and preparing for it.","zh":"in anticipation of 指預期某事會發生並為此準備。"},{"en":"Students may review notes in anticipation of a surprise quiz.","zh":"學生可能預期突擊測驗而溫習筆記。"},{"en":"If a predator waits in anticipation of prey, it saves energy until the moment arrives.","zh":"如果捕食者等待獵物出現，就能保存能量直到時機來臨。"},{"en":"The phrase connects waiting with expectation.","zh":"這個片語把等待與預期連接起來。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":9},{"front":"a gazelle","meaning":"瞪羚","examples":[{"en":"A crocodile may wait near the water for a gazelle.","zh":"鱷魚可能在水邊等待瞪羚。"},{"en":"A gazelle is a small, fast antelope-like animal often found in open grassland.","zh":"a gazelle 指一種小型、快速、類似羚羊並常見於開闊草地的動物。"},{"en":"In a nature documentary, a gazelle may approach a river carefully to drink.","zh":"在自然紀錄片中，瞪羚可能小心靠近河流飲水。"},{"en":"If a gazelle comes too close to hidden crocodiles, it may be ambushed.","zh":"如果瞪羚太接近隱藏的鱷魚，可能被伏擊。"},{"en":"The word names a possible prey animal.","zh":"這個詞指一種可能的獵物動物。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":9},{"front":"the chance to ambush","meaning":"伏擊的機會","examples":[{"en":"The crocodile attacks when the chance to ambush presents itself.","zh":"當伏擊的機會出現時，鱷魚就會攻擊。"},{"en":"The chance to ambush means an opportunity to attack suddenly from a hidden position.","zh":"the chance to ambush 指從隱藏位置突然攻擊的機會。"},{"en":"In a game, a player may hide behind a wall and wait for the chance to ambush an opponent.","zh":"在遊戲中，玩家可能躲在牆後等待伏擊對手的機會。"},{"en":"If prey steps close to water, the chance to ambush may appear.","zh":"如果獵物走近水邊，伏擊的機會可能出現。"},{"en":"The phrase combines opportunity with surprise attack.","zh":"這個片語結合機會和突襲。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":9},{"front":"presents itself","meaning":"出現；來臨","examples":[{"en":"The crocodile dashes forward when an opportunity presents itself.","zh":"當機會出現時，鱷魚向前猛衝。"},{"en":"Presents itself means appears or becomes available.","zh":"presents itself 指出現或變得可用。"},{"en":"If a chance to ask a question presents itself, students should use it.","zh":"如果提問機會出現，學生應把握。"},{"en":"When an opportunity presents itself, quick action may be necessary.","zh":"當機會來臨時，可能需要迅速行動。"},{"en":"The phrase describes a chance appearing naturally.","zh":"這個片語描述機會自然出現。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":9},{"front":"dashes forward","meaning":"向前猛衝","examples":[{"en":"The crocodile dashes forward to attack its prey.","zh":"鱷魚向前猛衝去攻擊獵物。"},{"en":"Dashes forward means moves suddenly and quickly toward something.","zh":"dashes forward 指突然快速向某物前進。"},{"en":"A student may dash forward to catch a bus before it leaves.","zh":"學生可能向前猛衝去趕上即將開走的巴士。"},{"en":"If a predator dashes forward, the prey has little time to react.","zh":"如果捕食者向前猛衝，獵物幾乎沒有時間反應。"},{"en":"The phrase suggests sudden fast movement.","zh":"這個片語暗示突然快速移動。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":9},{"front":"knocks the animal out","meaning":"把動物擊昏","examples":[{"en":"The crocodile knocks the animal out with its powerful tail.","zh":"鱷魚用強而有力的尾巴把動物擊昏。"},{"en":"Knocks the animal out means hits the animal so hard that it becomes unconscious or unable to move.","zh":"knocks the animal out 指猛烈擊打動物，使其昏迷或無法移動。"},{"en":"In boxing, a strong punch can knock a fighter out.","zh":"在拳擊中，強力一拳可以把拳手擊倒昏迷。"},{"en":"If prey is knocked out, it cannot escape or defend itself.","zh":"如果獵物被擊昏，就不能逃跑或自衛。"},{"en":"The phrase describes a forceful disabling blow.","zh":"這個片語描述使對方失去行動能力的重擊。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":9},{"front":"powerful tail","meaning":"強而有力的尾巴","examples":[{"en":"A crocodile can use its powerful tail to strike prey.","zh":"鱷魚可以用強而有力的尾巴打擊獵物。"},{"en":"A powerful tail is a strong tail that can push, swim, balance, or hit with force.","zh":"powerful tail 指能用力推動、游泳、保持平衡或擊打的強壯尾巴。"},{"en":"A swimmer uses strong legs like a crocodile uses a powerful tail in water.","zh":"游泳者使用強壯雙腿，就像鱷魚在水中使用強力尾巴。"},{"en":"If a crocodile strikes with its tail, the blow can knock prey off balance.","zh":"如果鱷魚用尾巴擊打，這一擊可以令獵物失去平衡。"},{"en":"The phrase describes an important physical weapon or tool.","zh":"這個片語描述重要的身體武器或工具。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":9},{"front":"drags the prey into the water","meaning":"把獵物拖入水中","examples":[{"en":"The crocodile drags the prey into the water.","zh":"鱷魚把獵物拖入水中。"},{"en":"Drags the prey into the water means pulls the captured animal into water by force.","zh":"drags the prey into the water 指用力把被捕獲的動物拉進水中。"},{"en":"A dog may drag a toy into the garden when it wants to play outside.","zh":"狗想在外面玩時，可能把玩具拖到花園。"},{"en":"If a crocodile drags prey into water, escape becomes much harder.","zh":"如果鱷魚把獵物拖入水中，逃脫就困難得多。"},{"en":"The phrase describes forceful movement toward water.","zh":"這個片語描述朝水中用力拉動。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":9},{"front":"drown it","meaning":"將其溺斃","examples":[{"en":"The crocodile drags the prey into the water to drown it.","zh":"鱷魚把獵物拖入水中將其溺斃。"},{"en":"Drown it means kill it by keeping it underwater so it cannot breathe.","zh":"drown it 指把牠保持在水下，使牠不能呼吸而死亡。"},{"en":"People must supervise children near pools because a child can drown quickly.","zh":"人們必須在泳池旁看顧孩子，因為孩子可能很快溺水。"},{"en":"If prey is dragged underwater, drowning may happen before it can escape.","zh":"如果獵物被拖到水下，可能在逃脫前被溺斃。"},{"en":"The phrase describes death caused by lack of air in water.","zh":"這個片語描述因在水中缺氧而死亡。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":9},{"front":"crocodilian habitats","meaning":"鱷類棲息地","examples":[{"en":"Many crocodilian habitats experience seasonal drought.","zh":"許多鱷類棲息地會經歷季節性乾旱。"},{"en":"Crocodilian habitats are natural places where crocodiles, alligators, or related animals live.","zh":"crocodilian habitats 指鱷魚、短吻鱷或相關動物生活的自然地方。"},{"en":"Rivers, wetlands, lakes, and swamps can be crocodilian habitats.","zh":"河流、濕地、湖泊和沼澤都可以是鱷類棲息地。"},{"en":"If crocodilian habitats dry up, crocodiles must find ways to survive without normal hunting grounds.","zh":"如果鱷類棲息地乾涸，鱷魚就必須尋找方法在沒有正常狩獵場下生存。"},{"en":"The phrase refers to living environments of crocodile relatives.","zh":"這個片語指鱷魚親族的生活環境。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":10},{"front":"the hot season","meaning":"炎熱季節","examples":[{"en":"The hot season brings drought in many crocodilian habitats.","zh":"炎熱季節在許多鱷類棲息地帶來乾旱。"},{"en":"The hot season is the time of year when temperatures are especially high.","zh":"the hot season 指一年中氣溫特別高的時期。"},{"en":"In some countries, schools adjust sports lessons during the hot season.","zh":"在一些國家，學校會在炎熱季節調整體育課。"},{"en":"If the hot season reduces water levels, animals may struggle to find food and shade.","zh":"如果炎熱季節令水位下降，動物可能難以尋找食物和陰涼處。"},{"en":"The phrase describes a seasonal period of high heat.","zh":"這個片語描述高溫的季節性時期。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":10},{"front":"brings drought","meaning":"帶來旱災；導致乾旱","examples":[{"en":"The hot season brings drought to many habitats.","zh":"炎熱季節給許多棲息地帶來旱災。"},{"en":"Brings drought means causes or results in a long dry period with little water.","zh":"brings drought 指造成或導致長時間缺水的乾旱時期。"},{"en":"A failed rainy season can bring drought to farming villages.","zh":"雨季失敗可以給農村帶來旱災。"},{"en":"If drought arrives, rivers may shrink and animals may lose feeding areas.","zh":"如果乾旱到來，河流可能縮小，動物可能失去覓食區。"},{"en":"The phrase links a season or event with dry conditions.","zh":"這個片語把季節或事件與乾旱情況連接起來。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":10},{"front":"dries up","meaning":"使……乾涸","examples":[{"en":"Drought dries up the crocodiles’ hunting grounds.","zh":"乾旱使鱷魚的狩獵場乾涸。"},{"en":"Dries up means removes water from something until it becomes dry.","zh":"dries up 指使某物失去水分直到變乾。"},{"en":"Hot weather can dry up small puddles in a few hours.","zh":"炎熱天氣可在幾小時內使小水坑乾涸。"},{"en":"If a river dries up, fish and other prey may disappear from that area.","zh":"如果河流乾涸，魚和其他獵物可能從該區消失。"},{"en":"The phrase describes loss of water.","zh":"這個片語描述水分流失。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":10},{"front":"hunting grounds","meaning":"狩獵場","examples":[{"en":"Drought can dry up the crocodiles’ hunting grounds.","zh":"乾旱可以使鱷魚的狩獵場乾涸。"},{"en":"Hunting grounds are places where an animal usually finds and catches prey.","zh":"hunting grounds 指動物通常尋找和捕捉獵物的地方。"},{"en":"A forest may be the hunting ground of owls at night.","zh":"森林可能是貓頭鷹夜間的狩獵場。"},{"en":"If hunting grounds disappear, predators may need to move or stop feeding.","zh":"如果狩獵場消失，捕食者可能需要遷移或停止進食。"},{"en":"The phrase describes a usual feeding area.","zh":"這個片語描述常用覓食區。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":10},{"front":"making it more difficult for","meaning":"令……更難","examples":[{"en":"Drought makes it more difficult for crocodiles to regulate body temperature.","zh":"乾旱令鱷魚更難調節體溫。"},{"en":"Making it more difficult for means causing a task to become harder for someone or something.","zh":"making it more difficult for 指使某人或某物做某事變得更困難。"},{"en":"Noise makes it more difficult for students to concentrate.","zh":"噪音令學生更難集中。"},{"en":"If water disappears, it becomes harder for crocodiles to cool down safely.","zh":"如果水消失，鱷魚就更難安全降溫。"},{"en":"The phrase explains how one problem creates another problem.","zh":"這個片語解釋一個問題如何造成另一個問題。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":10},{"front":"regulate body temperatures","meaning":"調節體溫","examples":[{"en":"Crocodiles need to regulate body temperatures during hot weather.","zh":"鱷魚在炎熱天氣中需要調節體溫。"},{"en":"Regulate body temperatures means control body heat so it stays within a safe range.","zh":"regulate body temperatures 指控制身體熱度，使其維持在安全範圍內。"},{"en":"People regulate body temperature by sweating, drinking water, and resting in shade.","zh":"人們透過流汗、喝水和在陰涼處休息來調節體溫。"},{"en":"If animals cannot regulate body temperature, they may overheat or become too cold.","zh":"如果動物不能調節體溫，可能過熱或過冷。"},{"en":"The phrase is important in explaining survival.","zh":"這個片語在解釋生存時很重要。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":10},{"front":"harsh seasonal cycle","meaning":"嚴酷的季節循環","examples":[{"en":"This harsh seasonal cycle helps explain crocodile survival.","zh":"這種嚴酷的季節循環有助解釋鱷魚的生存。"},{"en":"A harsh seasonal cycle is a repeated pattern of seasons that creates difficult conditions.","zh":"harsh seasonal cycle 指造成艱難條件的季節反覆模式。"},{"en":"Farmers in dry regions may plan around a harsh seasonal cycle of heat and drought.","zh":"乾旱地區的農民可能圍繞炎熱和乾旱的嚴酷季節循環作規劃。"},{"en":"If animals survive harsh cycles year after year, they must have strong survival strategies.","zh":"如果動物年復一年熬過嚴酷循環，就必須有強生存策略。"},{"en":"The phrase connects repeated seasonal difficulty with adaptation.","zh":"這個片語把反覆季節困難與適應連接起來。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":10},{"front":"helps explain why","meaning":"有助解釋為何","examples":[{"en":"The harsh seasonal cycle helps explain why reptiles have survived.","zh":"嚴酷的季節循環有助解釋為何爬行動物能生存下來。"},{"en":"Helps explain why means gives part of the reason for something.","zh":"helps explain why 指給出某事發生的部分原因。"},{"en":"Regular practice helps explain why some students improve faster than others.","zh":"定期練習有助解釋為何一些學生比其他學生進步更快。"},{"en":"If a behaviour helps survival, it may explain why a species lasts so long.","zh":"如果某行為有助生存，它可能解釋為何物種能延續如此長時間。"},{"en":"The phrase introduces a partial explanation, not always the whole answer.","zh":"這個片語引出部分解釋，而不一定是完整答案。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":10},{"front":"for instance","meaning":"例如","examples":[{"en":"For instance, many crocodiles protect themselves by digging holes.","zh":"例如，許多鱷魚透過挖洞保護自己。"},{"en":"For instance means for example.","zh":"for instance 指例如。"},{"en":"Some students learn better with visual help; for instance, diagrams can explain grammar patterns.","zh":"有些學生用視覺輔助學得更好；例如，圖表可以解釋文法模式。"},{"en":"If a writer uses “for instance”, the next detail should support the previous idea.","zh":"如果作者使用 for instance，下一個細節應支持前面的想法。"},{"en":"The phrase introduces a concrete example.","zh":"這個片語引出具體例子。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":10},{"front":"protect themselves by","meaning":"透過……保護自己","examples":[{"en":"Crocodiles protect themselves by digging holes.","zh":"鱷魚透過挖洞保護自己。"},{"en":"Protect themselves by means keep themselves safe through a particular action.","zh":"protect themselves by 指透過某特定行動令自己安全。"},{"en":"Cyclists protect themselves by wearing helmets.","zh":"單車手透過戴頭盔保護自己。"},{"en":"If animals protect themselves by hiding, predators or harsh weather may harm them less.","zh":"如果動物透過躲藏保護自己，捕食者或惡劣天氣對牠們的傷害可能較少。"},{"en":"The phrase links a protective action with safety.","zh":"這個片語把保護行動與安全連接起來。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":11},{"front":"digging holes","meaning":"挖洞","examples":[{"en":"Crocodiles protect themselves by digging holes.","zh":"鱷魚透過挖洞保護自己。"},{"en":"Digging holes means making openings in the ground by removing soil.","zh":"digging holes 指移走泥土，在地面形成洞口。"},{"en":"Children may dig holes in sand at the beach.","zh":"孩子可能在海灘沙地挖洞。"},{"en":"If crocodiles dig holes, they can hide from heat and drought underground.","zh":"如果鱷魚挖洞，就能在地下躲避高溫和乾旱。"},{"en":"The phrase describes a simple physical action with survival value.","zh":"這個片語描述具有生存價值的簡單身體動作。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":11},{"front":"covering themselves in mud","meaning":"用泥覆蓋自己","examples":[{"en":"Crocodiles may survive drought by covering themselves in mud.","zh":"鱷魚可能透過用泥覆蓋自己來熬過乾旱。"},{"en":"Covering themselves in mud means putting mud over their bodies as protection.","zh":"covering themselves in mud 指把泥覆蓋在身體上作保護。"},{"en":"Some animals roll in mud to cool down or keep insects away.","zh":"有些動物在泥中打滾，以降溫或驅趕昆蟲。"},{"en":"If mud covers the body, it can help reduce water loss and heat stress.","zh":"如果泥覆蓋身體，可以幫助減少水分流失和熱壓力。"},{"en":"The phrase describes using the environment as protection.","zh":"這個片語描述利用環境作保護。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":11},{"front":"waiting for months without","meaning":"幾個月都不……地等待","examples":[{"en":"Crocodiles can wait for months without consuming food or water.","zh":"鱷魚可以幾個月都不攝取食物或水分地等待。"},{"en":"Waiting for months without means remaining for several months while not doing a particular activity.","zh":"waiting for months without 指在幾個月期間保持等待，同時不做某特定活動。"},{"en":"A plant seed can wait for months without growing until rain arrives.","zh":"植物種子可以幾個月都不生長地等待，直到雨水到來。"},{"en":"If animals wait for months without food, their bodies must use energy very slowly.","zh":"如果動物幾個月都不進食而等待，其身體必須非常緩慢地使用能量。"},{"en":"The phrase stresses long endurance without normal resources.","zh":"這個片語強調在沒有正常資源下的長期忍耐。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":11},{"front":"consuming food or water","meaning":"攝取食物或水分","examples":[{"en":"Some crocodiles survive for months without consuming food or water.","zh":"有些鱷魚在幾個月不攝取食物或水分下仍能生存。"},{"en":"Consuming food or water means taking food or water into the body.","zh":"consuming food or water 指把食物或水分帶入身體。"},{"en":"Athletes need to keep consuming water during long training sessions.","zh":"運動員在長時間訓練期間需要持續攝取水分。"},{"en":"If an animal stops consuming food or water, it must rely on stored reserves.","zh":"如果動物停止攝取食物或水分，就必須依賴儲備。"},{"en":"The phrase is more formal than eating or drinking.","zh":"這個片語比 eating or drinking 更正式。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":11},{"front":"until the rains finally return","meaning":"直到雨水終於重臨","examples":[{"en":"Crocodiles may wait underground until the rains finally return.","zh":"鱷魚可能在地下等待，直到雨水終於重臨。"},{"en":"Until the rains finally return means up to the time when rainfall comes back after a dry period.","zh":"until the rains finally return 指直到乾旱期後雨水再次出現。"},{"en":"Farmers may store water until the rains finally return.","zh":"農民可能儲水直到雨水終於重臨。"},{"en":"If animals wait until rain returns, they can restart normal feeding when water appears.","zh":"如果動物等到雨水重臨，水出現時就能重新正常覓食。"},{"en":"The phrase marks the end of drought conditions.","zh":"這個片語標示乾旱情況的結束。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":11},{"front":"enter a quiescent state","meaning":"進入靜止狀態","examples":[{"en":"Crocodiles enter a quiescent state called aestivation.","zh":"鱷魚進入一種稱為夏眠的靜止狀態。"},{"en":"Enter a quiescent state means go into a quiet, inactive condition with reduced activity.","zh":"enter a quiescent state 指進入安靜、不活躍、活動減少的狀態。"},{"en":"Some seeds enter a quiet state until conditions are right for growth.","zh":"有些種子會進入靜止狀態，直到條件適合生長。"},{"en":"If animals enter a quiescent state, they can save energy during hard times.","zh":"如果動物進入靜止狀態，就能在艱難時期節省能量。"},{"en":"The phrase describes becoming inactive for survival.","zh":"這個片語描述為了生存而變得不活躍。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":11},{"front":"a quiescent state","meaning":"靜止狀態","examples":[{"en":"Aestivation is a quiescent state.","zh":"夏眠是一種靜止狀態。"},{"en":"A quiescent state is a quiet and inactive condition.","zh":"a quiescent state 指安靜而不活躍的狀態。"},{"en":"A machine in standby mode is in a kind of quiescent state.","zh":"處於待機模式的機器可說是在某種靜止狀態。"},{"en":"If an animal enters a quiescent state, its body may use less energy.","zh":"如果動物進入靜止狀態，其身體可能使用較少能量。"},{"en":"The phrase is formal and often used in science.","zh":"這個片語較正式，常用於科學。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":11},{"front":"aestivation","meaning":"夏眠","examples":[{"en":"Aestivation helps crocodiles survive the dry season.","zh":"夏眠幫助鱷魚熬過旱季。"},{"en":"Aestivation is a state of inactivity that helps some animals survive hot or dry periods.","zh":"aestivation 指幫助某些動物熬過炎熱或乾燥時期的不活躍狀態。"},{"en":"Some snails use aestivation when the weather becomes too dry.","zh":"有些蝸牛在天氣太乾時會進入夏眠。"},{"en":"If an animal enters aestivation, it can reduce energy and water use.","zh":"如果動物進入夏眠，就能減少能量和水分使用。"},{"en":"The word is similar to hibernation, but it usually happens during heat or drought.","zh":"這個詞類似冬眠，但通常發生在炎熱或乾旱期間。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":11},{"front":"most crocodilians are thought to","meaning":"大多數鱷類被認為……","examples":[{"en":"Most crocodilians are thought to go into aestivation during the dry season.","zh":"大多數鱷類被認為會在旱季期間進入夏眠。"},{"en":"Most crocodilians are thought to means scientists or experts generally believe most of them do something.","zh":"most crocodilians are thought to 指科學家或專家一般相信大多數鱷類會做某事。"},{"en":"Many old buildings are thought to have hidden rooms, though not all claims are proven.","zh":"許多古老建築被認為有隱藏房間，雖然並非所有說法都被證明。"},{"en":"If something is thought to happen, the writer is reporting belief rather than absolute certainty.","zh":"如果某事被認為會發生，作者是在報告看法，而不是絕對確定。"},{"en":"The phrase softens a scientific claim.","zh":"這個片語緩和科學主張。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":11},{"front":"go into aestivation","meaning":"進入夏眠","examples":[{"en":"Many crocodilians go into aestivation during the dry season.","zh":"許多鱷類在旱季期間進入夏眠。"},{"en":"Go into aestivation means enter a low-activity state to survive heat or drought.","zh":"go into aestivation 指進入低活動狀態，以熬過高溫或乾旱。"},{"en":"Some animals go into aestivation when water becomes scarce.","zh":"有些動物在水變得稀少時進入夏眠。"},{"en":"If crocodilians go into aestivation, they can wait out months of poor conditions.","zh":"如果鱷類進入夏眠，就能熬過數月惡劣條件。"},{"en":"The phrase describes a survival response.","zh":"這個片語描述一種生存反應。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":12},{"front":"during the dry season","meaning":"在旱季期間","examples":[{"en":"Crocodilians often go into aestivation during the dry season.","zh":"鱷類常在旱季期間進入夏眠。"},{"en":"During the dry season means in the part of the year when little rain falls.","zh":"during the dry season 指在一年中降雨很少的時期。"},{"en":"Farmers may save water carefully during the dry season.","zh":"農民在旱季期間可能小心儲水。"},{"en":"If rivers shrink during the dry season, animals may need special survival strategies.","zh":"如果河流在旱季期間縮小，動物可能需要特殊生存策略。"},{"en":"The phrase describes timing within a seasonal climate pattern.","zh":"這個片語描述季節性氣候模式中的時間。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":12},{"front":"a six-year study","meaning":"為期六年的研究","examples":[{"en":"A six-year study examined Australian freshwater crocodiles.","zh":"一項為期六年的研究檢視了澳洲淡水鱷。"},{"en":"A six-year study is research carried out over six years.","zh":"a six-year study 指進行六年的研究。"},{"en":"A six-year study of students may show how reading habits affect exam results.","zh":"一項為期六年的學生研究可能顯示閱讀習慣如何影響考試成績。"},{"en":"If a study lasts six years, it can observe long-term patterns more clearly.","zh":"如果研究持續六年，就能更清楚觀察長期模式。"},{"en":"The phrase highlights the length and seriousness of research.","zh":"這個片語突出研究的時間長度和認真程度。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":12},{"front":"Australian freshwater crocodiles","meaning":"澳洲淡水鱷","examples":[{"en":"The study focused on Australian freshwater crocodiles.","zh":"研究集中於澳洲淡水鱷。"},{"en":"Australian freshwater crocodiles are crocodiles that live in freshwater habitats in Australia.","zh":"Australian freshwater crocodiles 指生活在澳洲淡水棲息地的鱷魚。"},{"en":"A wildlife documentary may compare Australian freshwater crocodiles with saltwater crocodiles.","zh":"野生動物紀錄片可能比較澳洲淡水鱷和鹹水鱷。"},{"en":"If researchers study one species closely, they can understand its survival strategies better.","zh":"如果研究人員仔細研究一個物種，就能更了解其生存策略。"},{"en":"The phrase names the specific crocodiles studied.","zh":"這個片語指出被研究的特定鱷魚。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":12},{"front":"spent nearly four months a year","meaning":"每年花近四個月","examples":[{"en":"The crocodiles spent nearly four months a year underground.","zh":"這些鱷魚每年花近四個月在地下。"},{"en":"Spent nearly four months a year means used almost four months each year doing or being somewhere.","zh":"spent nearly four months a year 指每年用接近四個月做某事或待在某處。"},{"en":"A student athlete may spend nearly four months a year training for competitions.","zh":"學生運動員可能每年花近四個月訓練比賽。"},{"en":"If crocodiles spend months underground, aestivation is a major part of their yearly cycle.","zh":"如果鱷魚每年在地下待數月，夏眠就是其年度循環的重要部分。"},{"en":"The phrase shows repeated annual duration.","zh":"這個片語顯示每年重複的時間長度。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":12},{"front":"underground","meaning":"在地下","examples":[{"en":"The crocodiles spent nearly four months a year underground.","zh":"這些鱷魚每年花近四個月在地下。"},{"en":"Underground means below the surface of the ground.","zh":"underground 指在地面以下。"},{"en":"Some train systems run underground through busy cities.","zh":"有些鐵路系統在繁忙城市地下行駛。"},{"en":"If animals stay underground, they may avoid heat, predators, or dryness.","zh":"如果動物留在地下，可能避開高溫、捕食者或乾燥。"},{"en":"The word describes position below the earth’s surface.","zh":"這個詞描述地表以下的位置。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":12},{"front":"without access to","meaning":"無法取得……","examples":[{"en":"The crocodiles stayed underground without access to water.","zh":"這些鱷魚待在地下，無法取得水源。"},{"en":"Without access to means unable to reach, use, or obtain something.","zh":"without access to 指不能接觸、使用或取得某物。"},{"en":"Students without access to the internet may struggle with online homework.","zh":"無法取得互聯網的學生可能難以完成網上功課。"},{"en":"If animals are without access to water, they must rely on stored body reserves.","zh":"如果動物無法取得水源，就必須依賴身體儲備。"},{"en":"The phrase describes lack of available resources.","zh":"這個片語描述缺乏可用資源。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":12},{"front":"access to water","meaning":"獲取水源","examples":[{"en":"Aestivating crocodiles had no access to water.","zh":"夏眠中的鱷魚無法獲取水源。"},{"en":"Access to water means the ability to obtain or use water.","zh":"access to water 指取得或使用水的能力。"},{"en":"Villages need reliable access to water for drinking, cooking, and washing.","zh":"村莊需要穩定獲取水源，以飲用、煮食和清潔。"},{"en":"If animals lose access to water, survival becomes much harder.","zh":"如果動物失去水源，生存就變得困難得多。"},{"en":"The phrase is often used in environmental and health contexts.","zh":"這個片語常用於環境和健康情境。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":12},{"front":"doubly labelled water","meaning":"雙標記水","examples":[{"en":"Doubly labelled water was used to measure metabolic activity.","zh":"雙標記水被用來量度代謝活動。"},{"en":"Doubly labelled water is water containing special markers that help scientists measure energy use and water movement.","zh":"doubly labelled water 指含有特殊標記、幫助科學家量度能量使用和水分流動的水。"},{"en":"Researchers may give labelled water to animals and later test samples from their bodies.","zh":"研究人員可能給動物飲用標記水，之後測試牠們體內樣本。"},{"en":"If scientists track the labelled atoms, they can estimate metabolism without watching every movement.","zh":"如果科學家追蹤被標記的原子，就能在不觀察每個動作下估計代謝。"},{"en":"The phrase names a scientific measurement method.","zh":"這個片語指一種科學測量方法。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":12},{"front":"was used to detect","meaning":"被用來檢測","examples":[{"en":"Doubly labelled water was used to detect field metabolic rates.","zh":"雙標記水被用來檢測野外代謝率。"},{"en":"Was used to detect means was used as a method for finding or measuring something.","zh":"was used to detect 指被用作尋找或量度某事的方法。"},{"en":"A thermometer was used to detect fever in students entering the clinic.","zh":"溫度計被用來檢測進入診所學生是否發燒。"},{"en":"If a method detects hidden changes, researchers can study processes that are hard to see directly.","zh":"如果方法能檢測隱藏變化，研究人員就能研究難以直接看見的過程。"},{"en":"The phrase links a tool with what it finds.","zh":"這個片語把工具與它能發現的內容連接起來。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":12},{"front":"field metabolic rates","meaning":"野外代謝率","examples":[{"en":"The researchers measured field metabolic rates during aestivation.","zh":"研究人員量度夏眠期間的野外代謝率。"},{"en":"Field metabolic rates are rates of energy use measured in animals living in natural conditions.","zh":"field metabolic rates 指在自然條件下生活的動物的能量使用速率。"},{"en":"Scientists may compare field metabolic rates with laboratory metabolic rates.","zh":"科學家可能比較野外代謝率和實驗室代謝率。"},{"en":"If field metabolic rates fall, an animal is using less energy in the wild.","zh":"如果野外代謝率下降，動物在野外使用的能量就較少。"},{"en":"The phrase is technical and belongs to animal physiology research.","zh":"這個片語屬技術用語，用於動物生理研究。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":13},{"front":"water flux","meaning":"水分通量","examples":[{"en":"The researchers used doubly labelled water to detect water flux.","zh":"研究人員使用雙標記水檢測水分通量。"},{"en":"Water flux means movement or turnover of water through a body or system.","zh":"water flux 指水在身體或系統中的流動或周轉。"},{"en":"Doctors may monitor fluid movement in patients who are dehydrated.","zh":"醫生可能監察脫水病人的體液流動。"},{"en":"If water flux is low, an animal may be conserving water during drought.","zh":"如果水分通量低，動物可能在乾旱期間保存水分。"},{"en":"The phrase describes how water moves or changes amount over time.","zh":"這個片語描述水如何隨時間移動或改變數量。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":13},{"front":"plasma samples","meaning":"血漿樣本","examples":[{"en":"Plasma samples were taken once a month during some years.","zh":"在某些年份，血漿樣本每月抽取一次。"},{"en":"Plasma samples are small amounts of the liquid part of blood collected for testing.","zh":"plasma samples 指為測試而收集的少量血液液體部分。"},{"en":"A hospital may take plasma samples to check a patient’s chemical balance.","zh":"醫院可能抽取血漿樣本，以檢查病人的化學平衡。"},{"en":"If researchers test plasma samples regularly, they can track changes inside the body.","zh":"如果研究人員定期測試血漿樣本，就能追蹤身體內部變化。"},{"en":"The phrase refers to biological samples used in science or medicine.","zh":"這個片語指科學或醫學中使用的生物樣本。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":13},{"front":"were taken once a month","meaning":"每月抽取一次","examples":[{"en":"Plasma samples were taken once a month.","zh":"血漿樣本每月抽取一次。"},{"en":"Were taken once a month means were collected one time every month.","zh":"were taken once a month 指每個月收集一次。"},{"en":"Rent payments are often taken once a month from a bank account.","zh":"租金通常每月一次從銀行戶口扣除。"},{"en":"If samples are taken monthly, researchers can observe gradual changes.","zh":"如果樣本每月抽取一次，研究人員就能觀察逐漸變化。"},{"en":"The phrase describes regular monthly collection.","zh":"這個片語描述定期每月收集。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":13},{"front":"monitor the effects of","meaning":"監測……的影響","examples":[{"en":"Plasma samples were used to monitor the effects of aestivation.","zh":"血漿樣本被用來監測夏眠的影響。"},{"en":"Monitor the effects of means watch or measure how something changes a body, system, or situation.","zh":"monitor the effects of 指觀察或量度某事如何改變身體、系統或情況。"},{"en":"Teachers monitor the effects of a new study plan by checking student progress.","zh":"老師透過檢查學生進度來監測新學習計劃的影響。"},{"en":"If researchers monitor effects carefully, they can tell whether changes are harmful or harmless.","zh":"如果研究人員仔細監測影響，就能判斷變化有害還是無害。"},{"en":"The phrase describes ongoing observation of results.","zh":"這個片語描述對結果的持續觀察。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":13},{"front":"the accumulation of","meaning":"……的積聚","examples":[{"en":"The study monitored the accumulation of nitrogenous wastes.","zh":"該研究監測含氮廢物的積聚。"},{"en":"The accumulation of something means its gradual build-up over time.","zh":"the accumulation of 指某物隨時間逐漸累積。"},{"en":"The accumulation of homework can stress students if they delay tasks.","zh":"如果學生拖延任務，功課的積聚會造成壓力。"},{"en":"If waste accumulates in the body, it may become dangerous unless controlled.","zh":"如果廢物在體內積聚，除非受到控制，否則可能變危險。"},{"en":"The phrase focuses on gradual increase.","zh":"這個片語集中於逐漸增加。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":13},{"front":"nitrogenous wastes","meaning":"含氮廢物","examples":[{"en":"The researchers measured nitrogenous wastes in the crocodiles’ bodies.","zh":"研究人員量度鱷魚體內的含氮廢物。"},{"en":"Nitrogenous wastes are waste substances containing nitrogen, produced when bodies process protein.","zh":"nitrogenous wastes 指身體處理蛋白質時產生、含有氮的廢物。"},{"en":"Doctors may check waste products in blood to understand kidney function.","zh":"醫生可能檢查血液中的廢物，以了解腎功能。"},{"en":"If nitrogenous wastes build up too much, they can harm normal body function.","zh":"如果含氮廢物積聚太多，就可能損害正常身體功能。"},{"en":"The phrase is technical and related to body chemistry.","zh":"這個片語屬技術用語，與身體化學有關。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":13},{"front":"electrolyte concentrations","meaning":"電解質濃度","examples":[{"en":"The study monitored electrolyte concentrations during aestivation.","zh":"該研究監測夏眠期間的電解質濃度。"},{"en":"Electrolyte concentrations are the levels of minerals such as sodium and potassium in body fluids.","zh":"electrolyte concentrations 指體液中鈉、鉀等礦物質的水平。"},{"en":"Athletes may drink sports drinks to replace electrolytes after heavy sweating.","zh":"運動員大量流汗後可能飲用運動飲品補充電解質。"},{"en":"If electrolyte concentrations become abnormal, muscles and nerves may not work properly.","zh":"如果電解質濃度變得異常，肌肉和神經可能無法正常運作。"},{"en":"The phrase is used in biology and medicine.","zh":"這個片語用於生物和醫學。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":13},{"front":"the study found that","meaning":"研究發現","examples":[{"en":"The study found that the crocodiles’ metabolic engines function slowly.","zh":"研究發現鱷魚的代謝引擎運作緩慢。"},{"en":"The study found that means the research results showed a particular conclusion.","zh":"the study found that 指研究結果顯示某個結論。"},{"en":"The study found that students slept better when they stopped using phones before bed.","zh":"研究發現學生睡前停止使用手機時睡得更好。"},{"en":"If a study finds a pattern, the claim should be based on data, not guesswork.","zh":"如果研究發現某種模式，該主張應基於數據，而不是猜測。"},{"en":"The phrase introduces a research finding.","zh":"這個片語引出研究結果。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":13},{"front":"metabolic engines","meaning":"代謝引擎","examples":[{"en":"The crocodiles’ metabolic engines function slowly during aestivation.","zh":"鱷魚的代謝引擎在夏眠期間運作緩慢。"},{"en":"Metabolic engines is a figurative way to describe the body systems that use energy and keep life processes running.","zh":"metabolic engines 是比喻說法，用來描述使用能量並維持生命過程的身體系統。"},{"en":"During sleep, a person’s metabolic engine may slow compared with intense exercise.","zh":"睡眠時，人的代謝引擎可能比劇烈運動時慢。"},{"en":"If an animal’s metabolic engine slows, it burns less energy.","zh":"如果動物的代謝引擎放慢，就會燃燒較少能量。"},{"en":"The phrase makes body energy use easier to imagine.","zh":"這個片語令身體能量使用更容易想像。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":13},{"front":"function slowly","meaning":"運作緩慢","examples":[{"en":"The crocodiles’ metabolic engines function slowly.","zh":"鱷魚的代謝引擎運作緩慢。"},{"en":"Function slowly means work at a reduced speed.","zh":"function slowly 指以降低了的速度運作。"},{"en":"An old computer may function slowly when too many programs are open.","zh":"當太多程式開啟時，舊電腦可能運作緩慢。"},{"en":"If a body system functions slowly, it may use fewer resources.","zh":"如果身體系統運作緩慢，可能使用較少資源。"},{"en":"The phrase describes slow operation, not complete stopping.","zh":"這個片語描述慢速運作，而不是完全停止。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":14},{"front":"water and fat reserves","meaning":"水分和脂肪儲備","examples":[{"en":"Aestivating crocodiles consume water and fat reserves.","zh":"夏眠中的鱷魚會消耗水分和脂肪儲備。"},{"en":"Water and fat reserves are stored supplies of water and body fat used when outside resources are unavailable.","zh":"water and fat reserves 指在外部資源不可得時使用的水分和身體脂肪儲備。"},{"en":"A hiker carries water reserves, while the body stores fat as energy.","zh":"遠足者攜帶水分儲備，而身體以脂肪儲存能量。"},{"en":"If an animal cannot drink or eat, reserves help it survive temporarily.","zh":"如果動物不能飲水或進食，儲備能幫助牠暫時生存。"},{"en":"The phrase refers to stored survival resources.","zh":"這個片語指儲存起來的生存資源。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":14},{"front":"producing waste","meaning":"產生廢物","examples":[{"en":"The crocodiles’ bodies continue producing waste during aestivation.","zh":"鱷魚的身體在夏眠期間繼續產生廢物。"},{"en":"Producing waste means creating unwanted substances as a result of body processes or activity.","zh":"producing waste 指由身體過程或活動產生不需要的物質。"},{"en":"A kitchen produces waste when food scraps and packaging are thrown away.","zh":"廚房丟棄食物殘渣和包裝時會產生廢物。"},{"en":"If the body keeps producing waste, it must store or remove it safely.","zh":"如果身體持續產生廢物，就必須安全儲存或排走它。"},{"en":"The phrase describes a by-product of living or working systems.","zh":"這個片語描述生命或工作系統的副產品。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":14},{"front":"stored in the urine","meaning":"儲存在尿液中","examples":[{"en":"Waste is stored in the urine.","zh":"廢物儲存在尿液中。"},{"en":"Stored in the urine means kept in liquid waste inside the body before removal.","zh":"stored in the urine 指在排出前保存在體內液體廢物中。"},{"en":"Doctors can test substances stored in the urine to learn about a patient’s health.","zh":"醫生可以測試儲存在尿液中的物質，以了解病人健康。"},{"en":"If waste stays stored in urine, its concentration may increase over time.","zh":"如果廢物留在尿液中，濃度可能隨時間增加。"},{"en":"The phrase describes where body waste is held.","zh":"這個片語描述身體廢物被保存在何處。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":14},{"front":"becoming more and more concentrated","meaning":"變得越來越濃縮","examples":[{"en":"The waste becomes more and more concentrated.","zh":"廢物變得越來越濃縮。"},{"en":"Becoming more and more concentrated means having less water and a higher amount of substance in the same space.","zh":"becoming more and more concentrated 指水分較少，而同一空間中的物質含量較高。"},{"en":"Soup becomes more concentrated if it boils for a long time and water evaporates.","zh":"如果湯煮很久而水分蒸發，湯會變得更濃。"},{"en":"If urine becomes concentrated, waste levels inside it are higher.","zh":"如果尿液變濃縮，其中廢物水平更高。"},{"en":"The phrase describes gradual strengthening of concentration.","zh":"這個片語描述濃度逐漸增加。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":14},{"front":"nevertheless","meaning":"然而；儘管如此","examples":[{"en":"Nevertheless, the concentration of waste products in blood does not fluctuate much.","zh":"然而，血液中廢物的濃度沒有太大波動。"},{"en":"Nevertheless means despite what has just been said.","zh":"nevertheless 指儘管剛才所說的情況仍然如此。"},{"en":"The homework was difficult; nevertheless, most students finished it on time.","zh":"功課很難；然而，大多數學生仍準時完成。"},{"en":"If waste becomes concentrated in urine but blood remains stable, the contrast is important.","zh":"如果尿液中的廢物變濃，但血液仍保持穩定，這種對比很重要。"},{"en":"The word introduces a surprising contrast.","zh":"這個詞引出令人意外的對比。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":14},{"front":"waste products in blood","meaning":"血液中的廢物","examples":[{"en":"The concentration of waste products in blood remains fairly stable.","zh":"血液中廢物的濃度保持相當穩定。"},{"en":"Waste products in blood are unwanted substances carried in the bloodstream after body processes.","zh":"waste products in blood 指身體過程後由血流攜帶的不需要物質。"},{"en":"Doctors check waste products in blood to understand whether organs are working properly.","zh":"醫生檢查血液中的廢物，以了解器官是否正常運作。"},{"en":"If waste products in blood rise too much, health may be at risk.","zh":"如果血液中的廢物升得太高，健康可能有風險。"},{"en":"The phrase refers to internal chemical waste measured in blood.","zh":"這個片語指在血液中量度的體內化學廢物。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":14},{"front":"does not fluctuate much","meaning":"沒有太大波動","examples":[{"en":"The concentration of waste products in blood does not fluctuate much.","zh":"血液中廢物的濃度沒有太大波動。"},{"en":"Does not fluctuate much means does not rise and fall greatly.","zh":"does not fluctuate much 指沒有大幅上升和下降。"},{"en":"A student’s grades do not fluctuate much when their study habits are steady.","zh":"當學生學習習慣穩定時，成績通常沒有太大波動。"},{"en":"If a blood value does not fluctuate much, the body is keeping it stable.","zh":"如果血液數值沒有太大波動，身體正在保持其穩定。"},{"en":"The phrase describes only small changes.","zh":"這個片語描述只有小幅變化。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":14},{"front":"allowing crocodiles to","meaning":"使鱷魚能夠……","examples":[{"en":"The stable blood concentration allows crocodiles to carry on normal functions.","zh":"穩定的血液濃度使鱷魚能夠維持正常功能。"},{"en":"Allowing crocodiles to means making it possible for crocodiles to do something.","zh":"allowing crocodiles to 指令鱷魚有可能做某事。"},{"en":"Clear signs allow visitors to find the museum exit easily.","zh":"清楚標示使訪客能容易找到博物館出口。"},{"en":"If blood chemistry stays stable, it allows crocodiles to keep body systems working.","zh":"如果血液化學保持穩定，就使鱷魚能維持身體系統運作。"},{"en":"The phrase links a condition with what it permits.","zh":"這個片語把條件與其允許發生的事連接起來。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":14},{"front":"carry on their normal functions","meaning":"維持正常功能","examples":[{"en":"Crocodiles can carry on their normal functions during aestivation.","zh":"鱷魚在夏眠期間可以維持正常功能。"},{"en":"Carry on their normal functions means continue basic body processes or activities.","zh":"carry on their normal functions 指繼續基本身體過程或活動。"},{"en":"A school can carry on its normal functions after a power cut if backup systems work.","zh":"如果後備系統有效，學校可在停電後維持正常功能。"},{"en":"If an animal carries on normal functions during stress, it avoids serious harm.","zh":"如果動物在壓力下維持正常功能，就能避免嚴重傷害。"},{"en":"The phrase means continue operating normally.","zh":"這個片語意思是繼續正常運作。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":14},{"front":"lost water reserves","meaning":"失去水分儲備","examples":[{"en":"The crocodiles lost water reserves while underground.","zh":"鱷魚在地下時失去水分儲備。"},{"en":"Lost water reserves means used up or reduced stored water inside the body.","zh":"lost water reserves 指身體內儲存的水分被使用或減少。"},{"en":"A runner may lose water reserves through sweating during a marathon.","zh":"跑手在馬拉松期間可能透過流汗失去水分儲備。"},{"en":"If an animal loses water reserves, it must avoid dehydration or replace water later.","zh":"如果動物失去水分儲備，就必須避免脫水或之後補水。"},{"en":"The phrase describes reduction in stored body water.","zh":"這個片語描述身體儲水減少。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":15},{"front":"body weight","meaning":"體重","examples":[{"en":"The crocodiles lost both water reserves and body weight.","zh":"鱷魚同時失去水分儲備和體重。"},{"en":"Body weight is the total weight of a person’s or animal’s body.","zh":"body weight 指人或動物身體的總重量。"},{"en":"A doctor may record body weight to monitor a patient’s health.","zh":"醫生可能記錄體重以監測病人健康。"},{"en":"If body weight falls during a long period without food, stored energy is being used.","zh":"如果在長時間沒有食物期間體重下降，儲存能量正在被使用。"},{"en":"The phrase is common in health, sport, and biology.","zh":"這個片語常見於健康、運動和生物學。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":15},{"front":"losses were proportional","meaning":"損失成比例","examples":[{"en":"The losses of water reserves and body weight were proportional.","zh":"水分儲備和體重的損失成比例。"},{"en":"Losses were proportional means the amounts lost changed in a matching ratio.","zh":"losses were proportional 指損失的數量按相配比例改變。"},{"en":"If two students lose marks proportional to the number of missing answers, the marking is consistent.","zh":"如果兩名學生失分與漏答題數成比例，評分就是一致的。"},{"en":"If water loss and weight loss are proportional, the body may avoid sudden imbalance.","zh":"如果水分損失和體重損失成比例，身體可能避免突然失衡。"},{"en":"The phrase describes losses that change together in a balanced way.","zh":"這個片語描述以平衡方式一起改變的損失。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":15},{"front":"upon emerging","meaning":"出來時；離開地底時","examples":[{"en":"Upon emerging, the crocodiles showed no signs of dehydration.","zh":"離開地底時，鱷魚沒有顯示脫水跡象。"},{"en":"Upon emerging means when they came out or appeared after being hidden or inside something.","zh":"upon emerging 指從隱藏處或某物內出來或出現時。"},{"en":"Upon emerging from the exam hall, students began discussing the answers.","zh":"從試場出來時，學生開始討論答案。"},{"en":"If crocodiles show no harm upon emerging, their underground strategy has worked.","zh":"如果鱷魚出來時沒有受害跡象，牠們的地下策略就有效。"},{"en":"The phrase is formal and means “when coming out”.","zh":"這個片語較正式，意思是「出來時」。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":15},{"front":"aestivating animals","meaning":"夏眠中的動物","examples":[{"en":"The aestivating animals showed no signs of dehydration.","zh":"夏眠中的動物沒有顯示脫水跡象。"},{"en":"Aestivating animals are animals that are in a low-activity state during hot or dry periods.","zh":"aestivating animals 指在炎熱或乾燥時期處於低活動狀態的動物。"},{"en":"A biology class may compare hibernating animals with aestivating animals.","zh":"生物課可能比較冬眠動物和夏眠中的動物。"},{"en":"If aestivating animals remain healthy, their bodies must conserve water well.","zh":"如果夏眠中的動物保持健康，其身體必須善於保存水分。"},{"en":"The phrase describes animals while they are undergoing aestivation.","zh":"這個片語描述正在夏眠的動物。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":15},{"front":"showed no signs of","meaning":"沒有……跡象","examples":[{"en":"The crocodiles showed no signs of dehydration.","zh":"鱷魚沒有脫水跡象。"},{"en":"Showed no signs of means did not display any visible or measurable evidence of something.","zh":"showed no signs of 指沒有顯示任何可見或可量度的證據。"},{"en":"A student showed no signs of stress before the speaking test.","zh":"學生在口試前沒有壓力跡象。"},{"en":"If an animal shows no signs of illness after stress, it may have recovered well.","zh":"如果動物在壓力後沒有疾病跡象，可能恢復良好。"},{"en":"The phrase is common in medical and observational descriptions.","zh":"這個片語常見於醫學和觀察描述。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":15},{"front":"dehydration","meaning":"脫水","examples":[{"en":"The crocodiles showed no signs of dehydration after aestivation.","zh":"鱷魚在夏眠後沒有脫水跡象。"},{"en":"Dehydration is a condition in which the body does not have enough water.","zh":"dehydration 指身體沒有足夠水分的狀態。"},{"en":"A person may suffer dehydration after exercising in hot weather without drinking.","zh":"人在炎熱天氣中運動而不喝水後，可能出現脫水。"},{"en":"If dehydration becomes severe, dizziness, weakness, and organ problems may appear.","zh":"如果脫水變得嚴重，可能出現頭暈、虛弱和器官問題。"},{"en":"The word is important in health and survival contexts.","zh":"這個詞在健康和生存情境中很重要。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":15},{"front":"harmful effects","meaning":"有害影響","examples":[{"en":"The crocodiles showed no harmful effects after aestivation.","zh":"鱷魚在夏眠後沒有顯示有害影響。"},{"en":"Harmful effects are negative results that damage health, growth, or function.","zh":"harmful effects 指損害健康、生長或功能的負面結果。"},{"en":"Poor sleep can have harmful effects on memory and mood.","zh":"睡眠不足可以對記憶和心情有有害影響。"},{"en":"If a survival strategy has no harmful effects, it may be very successful.","zh":"如果生存策略沒有有害影響，它可能非常成功。"},{"en":"The phrase describes damaging consequences.","zh":"這個片語描述有損害性的後果。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":15},{"front":"a slowed-down growth rate","meaning":"減慢的生長速度","examples":[{"en":"The crocodiles did not show a slowed-down growth rate.","zh":"鱷魚沒有顯示減慢的生長速度。"},{"en":"A slowed-down growth rate means growth happens more slowly than normal.","zh":"a slowed-down growth rate 指生長比正常速度更慢。"},{"en":"A child’s growth rate may slow down if nutrition is poor for a long time.","zh":"如果長期營養不良，孩子的生長速度可能減慢。"},{"en":"If aestivation does not slow growth, the crocodile can survive drought without losing development progress.","zh":"如果夏眠不減慢生長，鱷魚就能熬過乾旱而不失去發展進度。"},{"en":"The phrase describes reduced speed of growth.","zh":"這個片語描述生長速度降低。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":15},{"front":"concluded that","meaning":"得出結論認為","examples":[{"en":"The researchers concluded that this capacity helps explain crocodile survival.","zh":"研究人員得出結論認為，這種能力有助解釋鱷魚的生存。"},{"en":"Concluded that means reached a judgement after studying evidence.","zh":"concluded that 指研究證據後作出判斷。"},{"en":"After checking the data, the teacher concluded that extra practice improved results.","zh":"檢查數據後，老師得出結論認為額外練習改善成績。"},{"en":"If researchers conclude something, they are presenting a reasoned finding, not a random guess.","zh":"如果研究人員作出結論，他們是在提出有理據的發現，而不是隨機猜測。"},{"en":"The phrase introduces a research-based conclusion.","zh":"這個片語引出基於研究的結論。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":15},{"front":"capacity to endure","meaning":"忍受……的能力","examples":[{"en":"Crocodiles have a strong capacity to endure harsh times.","zh":"鱷魚有很強忍受艱難時期的能力。"},{"en":"Capacity to endure means ability to survive or continue through difficulty.","zh":"capacity to endure 指在困難中生存或繼續的能力。"},{"en":"A student’s capacity to endure exam pressure improves with sleep, planning, and practice.","zh":"學生忍受考試壓力的能力可透過睡眠、規劃和練習改善。"},{"en":"If animals can endure drought and hunger, they are more likely to survive long-term.","zh":"如果動物能忍受乾旱和飢餓，就更可能長期生存。"},{"en":"The phrase highlights strength under hardship.","zh":"這個片語突出在困境中的力量。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":16},{"front":"harsh times","meaning":"艱難時期","examples":[{"en":"Crocodiles can endure harsh times and long starvation periods.","zh":"鱷魚可以忍受艱難時期和長時間飢餓期。"},{"en":"Harsh times are difficult periods with severe conditions.","zh":"harsh times 指條件嚴酷的困難時期。"},{"en":"Families may face harsh times when income falls and prices rise.","zh":"當收入下降而物價上升時，家庭可能面對艱難時期。"},{"en":"If animals survive harsh times, their behaviour and body systems must help them cope.","zh":"如果動物熬過艱難時期，其行為和身體系統必須幫助牠們應對。"},{"en":"The phrase describes periods of hardship.","zh":"這個片語描述困苦時期。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":16},{"front":"long starvation periods","meaning":"長時間飢餓期","examples":[{"en":"Crocodiles can survive long starvation periods.","zh":"鱷魚可以熬過長時間飢餓期。"},{"en":"Long starvation periods are extended times when an animal has little or no food.","zh":"long starvation periods 指動物幾乎沒有或完全沒有食物的長時期。"},{"en":"Some animals store fat before long starvation periods in winter or drought.","zh":"有些動物在冬天或乾旱的長時間飢餓期前儲存脂肪。"},{"en":"If metabolism slows during starvation, the body can use stored energy more slowly.","zh":"如果飢餓期間代謝放慢，身體就能更慢地使用儲存能量。"},{"en":"The phrase describes serious food absence over time.","zh":"這個片語描述長時間嚴重缺乏食物。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":16},{"front":"helps explain","meaning":"有助解釋","examples":[{"en":"This capacity helps explain the survival of the crocodilian line.","zh":"這種能力有助解釋鱷類譜系的生存。"},{"en":"Helps explain means gives part of the reason for something.","zh":"helps explain 指提供某事的部分原因。"},{"en":"A student’s daily reading helps explain their strong vocabulary.","zh":"學生每天閱讀，有助解釋其強大的詞彙量。"},{"en":"If a trait helps explain survival, it probably gives an important advantage.","zh":"如果某特徵有助解釋生存，它可能提供重要優勢。"},{"en":"The phrase introduces a useful explanation, not always the complete cause.","zh":"這個片語引出有用解釋，但不一定是完整原因。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":16},{"front":"the crocodilian line","meaning":"鱷類譜系","examples":[{"en":"The crocodilian line has survived throughout history.","zh":"鱷類譜系縱觀歷史一直存活。"},{"en":"The crocodilian line means the evolutionary family line that includes crocodiles and related animals.","zh":"the crocodilian line 指包括鱷魚及相關動物的演化家族譜系。"},{"en":"Scientists study fossils to trace the crocodilian line through prehistoric time.","zh":"科學家研究化石，以追溯史前時期的鱷類譜系。"},{"en":"If a line survives for millions of years, its members must have adapted successfully.","zh":"如果一個譜系能存活數百萬年，其成員必然成功適應。"},{"en":"The phrase refers to ancestry and evolution, not a straight physical line.","zh":"這個片語指祖先和演化，而不是實體直線。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":16},{"front":"survival throughout history","meaning":"縱觀歷史的生存","examples":[{"en":"The survival of crocodiles throughout history is remarkable.","zh":"鱷魚縱觀歷史的生存非常驚人。"},{"en":"Survival throughout history means continuing to exist across many historical or prehistoric periods.","zh":"survival throughout history 指跨越許多歷史或史前時期繼續存在。"},{"en":"The survival of an old tradition throughout history shows that people kept finding meaning in it.","zh":"一項古老傳統縱觀歷史的生存顯示人們一直在其中找到意義。"},{"en":"If a species survives throughout history, it must pass through many environmental changes.","zh":"如果物種縱觀歷史一直生存，就必須經歷許多環境變化。"},{"en":"The phrase stresses long-term endurance.","zh":"這個片語強調長期耐受。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":16},{"front":"Reading Passage","meaning":"閱讀篇章","examples":[{"en":"Reading Passage 2 has seven paragraphs.","zh":"閱讀篇章二有七段。"},{"en":"A Reading Passage is a text that students read in an exam or exercise.","zh":"Reading Passage 指學生在考試或練習中閱讀的文章。"},{"en":"Students should skim the Reading Passage before answering detailed questions.","zh":"學生回答細節題前應略讀閱讀篇章。"},{"en":"If a question refers to the Reading Passage, answers should come from that text.","zh":"如果題目提到閱讀篇章，答案應來自該文本。"},{"en":"The phrase is common in IELTS-style reading tasks.","zh":"這個片語常見於 IELTS 類閱讀題。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":16},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Students choose the correct heading for each paragraph.","zh":"學生為每段選出正確標題。"},{"en":"Choose the correct heading means select the title that best matches the main idea of a paragraph.","zh":"choose the correct heading 指選出最符合段落主旨的標題。"},{"en":"In a reading test, students should read the whole paragraph before choosing the heading.","zh":"在閱讀測驗中，學生應先讀完整段再選標題。"},{"en":"If the heading is too narrow, it may miss the paragraph’s main point.","zh":"如果標題太狹窄，可能錯過段落主旨。"},{"en":"The phrase is a common matching-headings instruction.","zh":"這個片語是常見配對標題題指示。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":16},{"front":"the list of headings","meaning":"標題列表","examples":[{"en":"The list of headings contains several possible paragraph titles.","zh":"標題列表包含幾個可能的段落標題。"},{"en":"The list of headings is a set of title options for matching with paragraphs.","zh":"the list of headings 指用來與段落配對的一組標題選項。"},{"en":"Students should compare each paragraph with the list of headings before answering.","zh":"學生作答前應把每段與標題列表比較。"},{"en":"If two headings seem similar, the paragraph’s main idea decides which one fits better.","zh":"如果兩個標題看似相似，段落主旨決定哪一個更合適。"},{"en":"The phrase refers to the answer options in a reading task.","zh":"這個片語指閱讀題中的答案選項。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":16},{"front":"write the correct number","meaning":"寫下正確編號","examples":[{"en":"Students write the correct number on their answer sheet.","zh":"學生在答題紙上寫下正確編號。"},{"en":"Write the correct number means record the number of the chosen answer option.","zh":"write the correct number 指寫下所選答案選項的編號。"},{"en":"In matching tasks, students may write Roman numerals or ordinary numbers beside each question.","zh":"在配對題中，學生可能在每題旁寫羅馬數字或普通數字。"},{"en":"If the number is copied wrongly, the answer may be marked wrong.","zh":"如果編號抄錯，答案可能被判錯。"},{"en":"The phrase gives an answer-format instruction.","zh":"這個片語給出答案格式指示。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":16},{"front":"the positive impact of","meaning":"……的正面影響","examples":[{"en":"The heading describes the positive impact of drought.","zh":"該標題描述乾旱的正面影響。"},{"en":"The positive impact of something means its beneficial or helpful effect.","zh":"the positive impact of 指某事的有益或有幫助的影響。"},{"en":"The positive impact of daily reading can be seen in stronger vocabulary.","zh":"每日閱讀的正面影響可從更強詞彙量中看出。"},{"en":"If drought pushes animals to develop survival strategies, it may have an unexpected positive impact.","zh":"如果乾旱促使動物發展生存策略，它可能有意想不到的正面影響。"},{"en":"The phrase focuses on good results, even from a difficult situation.","zh":"這個片語集中於好結果，即使來自困難情況。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":17},{"front":"research findings into","meaning":"關於……的研究結果","examples":[{"en":"The paragraph presents research findings into crocodile survival.","zh":"該段呈現關於鱷魚生存的研究結果。"},{"en":"Research findings into something are results discovered through study of that topic.","zh":"research findings into 指透過研究某主題而發現的結果。"},{"en":"A school may use research findings into sleep to improve homework policy.","zh":"學校可能使用關於睡眠的研究結果來改善功課政策。"},{"en":"If findings are based on long study, they can support stronger conclusions.","zh":"如果研究結果基於長期研究，就能支持更有力結論。"},{"en":"The phrase introduces evidence from research.","zh":"這個片語引出來自研究的證據。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":17},{"front":"a unique animal","meaning":"獨特的動物","examples":[{"en":"The heading asks what makes the crocodile a unique animal.","zh":"該標題詢問甚麼令鱷魚成為獨特的動物。"},{"en":"A unique animal is an animal with special features that make it different from others.","zh":"a unique animal 指具有特殊特徵、令其不同於其他動物的動物。"},{"en":"The platypus is a unique animal because it has a mixture of unusual traits.","zh":"鴨嘴獸是獨特的動物，因為牠有混合的不尋常特徵。"},{"en":"If an animal survives in several difficult environments, it may be considered unique.","zh":"如果動物能在幾種困難環境中生存，就可能被視為獨特。"},{"en":"The phrase highlights difference and specialness.","zh":"這個片語突出差異和特殊性。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":17},{"front":"the slow metabolism","meaning":"緩慢的新陳代謝","examples":[{"en":"The slow metabolism of crocodiles helps them survive food shortages.","zh":"鱷魚緩慢的新陳代謝幫助牠們熬過食物短缺。"},{"en":"The slow metabolism means the relatively low speed at which crocodiles use energy.","zh":"the slow metabolism 指鱷魚使用能量的速度相對較低。"},{"en":"A slow metabolism can allow an animal to go longer between meals.","zh":"緩慢的新陳代謝可讓動物在兩餐之間維持更久。"},{"en":"If metabolism is slow, stored energy lasts longer during drought or starvation.","zh":"如果代謝緩慢，儲存能量在乾旱或飢餓期間可維持更久。"},{"en":"The phrase explains an important survival advantage.","zh":"這個片語解釋重要生存優勢。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":17},{"front":"a perfectly designed body","meaning":"設計完美的身體","examples":[{"en":"A perfectly designed body can help an animal survive in its environment.","zh":"設計完美的身體可以幫助動物在其環境中生存。"},{"en":"A perfectly designed body means a body with features that fit its way of life extremely well.","zh":"a perfectly designed body 指有極適合其生活方式特徵的身體。"},{"en":"A fish has a body well designed for swimming, with fins and a smooth shape.","zh":"魚有適合游泳的身體，包括魚鰭和平滑形狀。"},{"en":"If an animal’s body matches its environment, feeding and survival become easier.","zh":"如果動物身體與環境匹配，覓食和生存就更容易。"},{"en":"The phrase praises how useful body structure can be.","zh":"這個片語讚賞身體結構的實用性。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":17},{"front":"a great land roamer","meaning":"出色的陸地漫遊者","examples":[{"en":"The heading refers to the crocodile as a great land roamer.","zh":"該標題把鱷魚稱為出色的陸地漫遊者。"},{"en":"A great land roamer is an animal that can move around effectively on land.","zh":"a great land roamer 指能在陸地上有效四處移動的動物。"},{"en":"A camel is a great desert roamer because it can travel long distances in dry places.","zh":"駱駝是出色的沙漠漫遊者，因為牠能在乾燥地方長距離移動。"},{"en":"If crocodiles move well on land, they are not limited to water alone.","zh":"如果鱷魚能在陸地上良好移動，就不只限於水中。"},{"en":"The phrase highlights movement across land.","zh":"這個片語突出在陸地上的移動。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":17},{"front":"shifting eating habits","meaning":"不斷轉變的飲食習慣","examples":[{"en":"Shifting eating habits allow crocodiles to catch different kinds of prey.","zh":"不斷轉變的飲食習慣讓鱷魚捕捉不同種類的獵物。"},{"en":"Shifting eating habits are changing ways of feeding or choosing food.","zh":"shifting eating habits 指覓食方式或食物選擇的改變。"},{"en":"A student’s eating habits may shift when they move from home to university.","zh":"學生由家中搬到大學後，飲食習慣可能改變。"},{"en":"If animals shift eating habits, they can survive when one type of food disappears.","zh":"如果動物轉變飲食習慣，當某種食物消失時仍可生存。"},{"en":"The phrase shows flexibility in diet.","zh":"這個片語顯示飲食上的靈活性。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":17},{"front":"food intake","meaning":"食物攝取量","examples":[{"en":"Food intake may decrease when crocodiles enter aestivation.","zh":"當鱷魚進入夏眠時，食物攝取量可能下降。"},{"en":"Food intake is the amount of food a person or animal consumes.","zh":"food intake 指人或動物攝取的食物量。"},{"en":"A doctor may ask about food intake when checking a patient’s health.","zh":"醫生檢查病人健康時可能詢問食物攝取量。"},{"en":"If food intake falls, the body may rely more on stored energy.","zh":"如果食物攝取量下降，身體可能更依賴儲存能量。"},{"en":"The phrase is common in health and biology.","zh":"這個片語常見於健康和生物學。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":17},{"front":"a special mechanism","meaning":"特殊機制","examples":[{"en":"Aestivation is a special mechanism for surviving drought.","zh":"夏眠是熬過乾旱的特殊機制。"},{"en":"A special mechanism is a particular process or system that helps something work or survive.","zh":"a special mechanism 指幫助某物運作或生存的特定過程或系統。"},{"en":"The body has special mechanisms to cool itself, such as sweating.","zh":"身體有降溫的特殊機制，例如流汗。"},{"en":"If an animal has a special mechanism for drought, it can survive when water disappears.","zh":"如果動物有應對乾旱的特殊機制，水消失時仍可生存。"},{"en":"The phrase describes a useful biological process.","zh":"這個片語描述有用的生物過程。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":17},{"front":"regulating body temperature","meaning":"調節體溫","examples":[{"en":"Regulating body temperature is important for cold-blooded animals.","zh":"調節體溫對冷血動物很重要。"},{"en":"Regulating body temperature means controlling body heat so it stays safe.","zh":"regulating body temperature 指控制身體熱度，使其保持安全。"},{"en":"People regulate body temperature by sweating or wearing warmer clothes.","zh":"人們透過流汗或穿更暖衣服來調節體溫。"},{"en":"If animals cannot regulate body temperature, heat or cold can become dangerous.","zh":"如果動物不能調節體溫，高溫或寒冷可能變得危險。"},{"en":"The phrase describes a basic survival process.","zh":"這個片語描述基本生存過程。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":17},{"front":"the surrounding environment","meaning":"周圍環境","examples":[{"en":"Crocodiles regulate body temperature by using the surrounding environment.","zh":"鱷魚透過利用周圍環境調節體溫。"},{"en":"The surrounding environment means the natural conditions around an animal or person.","zh":"the surrounding environment 指動物或人周圍的自然條件。"},{"en":"A student’s concentration can improve if the surrounding environment is quiet.","zh":"如果周圍環境安靜，學生專注力可以改善。"},{"en":"If crocodiles use sunlight, water, and shade, they are using the surrounding environment to control heat.","zh":"如果鱷魚利用陽光、水和陰涼處，就是在利用周圍環境控制熱量。"},{"en":"The phrase refers to nearby conditions and spaces.","zh":"這個片語指附近的條件和空間。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":18},{"front":"body structure","meaning":"身體結構","examples":[{"en":"The crocodile’s body structure helps it hunt underwater.","zh":"鱷魚的身體結構幫助牠在水下獵食。"},{"en":"Body structure means the shape and arrangement of body parts.","zh":"body structure 指身體部位的形狀和排列。"},{"en":"A bird’s body structure, including wings and light bones, helps it fly.","zh":"鳥的身體結構，包括翅膀和輕骨，有助飛行。"},{"en":"If body structure matches an animal’s lifestyle, survival becomes easier.","zh":"如果身體結構配合動物生活方式，生存就更容易。"},{"en":"The phrase describes physical design.","zh":"這個片語描述身體設計。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":18},{"front":"underwater aid","meaning":"水下輔助","examples":[{"en":"The crocodile’s body structure offers underwater aid to a successful predator.","zh":"鱷魚的身體結構為成功捕食者提供水下輔助。"},{"en":"Underwater aid means help or advantage used below the surface of water.","zh":"underwater aid 指在水面以下使用的幫助或優勢。"},{"en":"Goggles provide underwater aid by helping swimmers see clearly.","zh":"泳鏡透過幫助游泳者看清楚來提供水下輔助。"},{"en":"If body features give underwater aid, a predator can move and attack more effectively in water.","zh":"如果身體特徵提供水下輔助，捕食者就能在水中更有效移動和攻擊。"},{"en":"The phrase describes support for activity below water.","zh":"這個片語描述對水下活動的支援。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":18},{"front":"a successful predator","meaning":"成功捕食者","examples":[{"en":"The crocodile is a successful predator.","zh":"鱷魚是成功捕食者。"},{"en":"A successful predator is an animal that often catches prey and survives by hunting well.","zh":"a successful predator 指經常捕捉獵物並靠有效獵食生存的動物。"},{"en":"An owl is a successful predator because it can see and hear well at night.","zh":"貓頭鷹是成功捕食者，因為牠夜間視力和聽覺很好。"},{"en":"If a predator is successful, its hunting methods and body features work effectively.","zh":"如果捕食者成功，其獵食方法和身體特徵就有效。"},{"en":"The phrase focuses on hunting success.","zh":"這個片語集中於獵食成功。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":18},{"front":"supreme survivors","meaning":"最強生存者","examples":[{"en":"Crocodiles are often described as supreme survivors.","zh":"鱷魚常被描述為最強生存者。"},{"en":"Supreme survivors are living things that are exceptionally good at staying alive through difficult conditions.","zh":"supreme survivors 指極其擅長在困難條件下存活的生物。"},{"en":"Some desert plants are supreme survivors because they can live with very little water.","zh":"有些沙漠植物是最強生存者，因為它們能在極少水分下生活。"},{"en":"If a species survives disasters for millions of years, it may earn this description.","zh":"如果一個物種熬過數百萬年的災難，就可能獲得這種描述。"},{"en":"The phrase strongly praises survival ability.","zh":"這個片語強烈讚賞生存能力。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":18},{"front":"competition between","meaning":"……之間的競爭","examples":[{"en":"The heading refers to competition between crocodiles and other animals.","zh":"該標題提到鱷魚與其他動物之間的競爭。"},{"en":"Competition between two groups means they both try to use the same resources or gain advantage.","zh":"competition between two groups 指兩個群體都嘗試使用同一資源或取得優勢。"},{"en":"There is competition between small shops and large supermarkets for customers.","zh":"小店和大型超市之間有顧客競爭。"},{"en":"If animals compete for food, the better adapted group may survive longer.","zh":"如果動物競爭食物，適應更好的類群可能存活更久。"},{"en":"The phrase describes a struggle for limited resources or success.","zh":"這個片語描述對有限資源或成功的爭奪。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":18},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the short text that follows.","zh":"complete the summary below 指在下方短文中填入缺失字詞。"},{"en":"In a reading test, students complete the summary below by finding matching ideas in the passage.","zh":"在閱讀測驗中，學生透過在文章中尋找相符意思來完成以下摘要。"},{"en":"If the word does not fit the grammar of the summary, the answer may be wrong.","zh":"如果字詞不符合摘要文法，答案可能錯。"},{"en":"The phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":18},{"front":"choose no more than two words","meaning":"選擇不多於兩個字","examples":[{"en":"Students choose no more than two words from the passage.","zh":"學生從文章中選擇不多於兩個字。"},{"en":"Choose no more than two words means the answer must contain one or two words, not three or more.","zh":"choose no more than two words 指答案必須包含一個或兩個詞，不能三個或以上。"},{"en":"If the answer is “dry season”, it follows the no-more-than-two-words rule.","zh":"如果答案是 dry season，就符合不多於兩個詞的規則。"},{"en":"If students add extra words, they may lose marks even with the right idea.","zh":"如果學生加入多餘字詞，即使意思正確也可能失分。"},{"en":"The phrase gives a strict word limit.","zh":"這個片語給出嚴格字數限制。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":18},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must come from the passage.","zh":"答案必須從文章中得出。"},{"en":"From the passage means taken directly from the reading text, not from outside knowledge.","zh":"from the passage 指直接取自閱讀文本，而不是外部知識。"},{"en":"In IELTS reading, students should answer from the passage even if they know extra facts.","zh":"在 IELTS 閱讀中，即使學生知道額外事實，也應從文章中作答。"},{"en":"If an answer is not supported by the passage, it may be wrong.","zh":"如果答案沒有文章支持，就可能錯。"},{"en":"The phrase reminds students to rely on the text.","zh":"這個片語提醒學生依賴文本。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":18},{"front":"write your answers in boxes","meaning":"在方格內寫下答案","examples":[{"en":"Students write their answers in boxes on the answer sheet.","zh":"學生在答題紙的方格內寫下答案。"},{"en":"Write your answers in boxes means put the answers in the numbered spaces provided.","zh":"write your answers in boxes 指把答案寫在所提供的編號空格中。"},{"en":"In exams, students should write answers in boxes clearly so markers can read them.","zh":"在考試中，學生應清楚在方格內寫答案，讓閱卷者能讀到。"},{"en":"If an answer is written in the wrong box, it may be counted for the wrong question.","zh":"如果答案寫在錯誤方格，可能被當成另一題答案。"},{"en":"The phrase gives a practical exam-format instruction.","zh":"這個片語給出實用考試格式指示。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":18},{"front":"summary completion","meaning":"摘要填充題","examples":[{"en":"Summary completion questions test whether students can follow the main ideas.","zh":"摘要填充題測試學生能否跟上主要意思。"},{"en":"Summary completion is a task where students fill gaps in a short summary of a passage.","zh":"summary completion 指學生在文章摘要中填補空格的題型。"},{"en":"Students should read around each blank before choosing words for summary completion.","zh":"學生做摘要填充題前，應閱讀每個空格前後內容。"},{"en":"If students understand the main flow, summary completion becomes easier.","zh":"如果學生理解主要脈絡，摘要填充題就更容易。"},{"en":"The phrase names a common reading-question type.","zh":"這個片語指常見閱讀題型。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":19},{"front":"inhabited by crocodilians","meaning":"有鱷類棲息的","examples":[{"en":"Many places inhabited by crocodilians experience seasonal drought.","zh":"許多有鱷類棲息的地方會經歷季節性乾旱。"},{"en":"Inhabited by crocodilians means lived in by crocodiles, alligators, or related animals.","zh":"inhabited by crocodilians 指有鱷魚、短吻鱷或相關動物生活其中。"},{"en":"Wetlands inhabited by birds may need protection from pollution.","zh":"有鳥類棲息的濕地可能需要保護免受污染。"},{"en":"If an area is inhabited by crocodilians, visitors should follow wildlife safety rules.","zh":"如果某地有鱷類棲息，訪客應遵守野生動物安全規則。"},{"en":"The phrase describes the animals that live in a place.","zh":"這個片語描述生活在某地方的動物。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":19},{"front":"have evolved a successful strategy","meaning":"已演化出成功策略","examples":[{"en":"Crocodilians have evolved a successful strategy for surviving drought.","zh":"鱷類已演化出成功策略，以熬過乾旱。"},{"en":"Have evolved a successful strategy means have developed an effective survival method over time.","zh":"have evolved a successful strategy 指隨時間發展出有效的生存方法。"},{"en":"Some plants have evolved strategies for storing water in dry climates.","zh":"有些植物已演化出在乾燥氣候中儲水的策略。"},{"en":"If a strategy helps survival, it may continue through many generations.","zh":"如果策略有助生存，就可能延續許多世代。"},{"en":"The phrase links evolution with practical survival behaviour.","zh":"這個片語把演化與實際生存行為連接起來。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":19},{"front":"a strategy for surviving","meaning":"生存策略","examples":[{"en":"Aestivation is a strategy for surviving drought.","zh":"夏眠是熬過乾旱的生存策略。"},{"en":"A strategy for surviving is a planned or evolved way to stay alive in difficult conditions.","zh":"a strategy for surviving 指在困難條件下活下來的計劃或演化出的方法。"},{"en":"Saving money is a strategy for surviving a period without work.","zh":"儲蓄是在失業期間生存的一種策略。"},{"en":"If animals use a survival strategy well, they can endure danger longer.","zh":"如果動物善用生存策略，就能更長時間忍受危險。"},{"en":"The phrase focuses on a method that helps survival.","zh":"這個片語集中於有助生存的方法。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":19},{"front":"caused by","meaning":"由……引起","examples":[{"en":"The drought is caused by a harsh seasonal cycle.","zh":"乾旱由嚴酷的季節循環引起。"},{"en":"Caused by means happening because of a particular reason.","zh":"caused by 指因某特定原因而發生。"},{"en":"The delay was caused by heavy traffic near the school.","zh":"延誤由學校附近交通繁忙引起。"},{"en":"If drought is caused by seasonal heat, it may return every year.","zh":"如果乾旱由季節性高溫引起，就可能每年重臨。"},{"en":"The phrase introduces the reason behind a result.","zh":"這個片語引出結果背後的原因。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":19},{"front":"according to","meaning":"根據","examples":[{"en":"According to the study, crocodiles spent months underground.","zh":"根據該研究，鱷魚在地下待了數月。"},{"en":"According to means as stated by a source or based on information from it.","zh":"according to 指按照某來源所述或基於其資料。"},{"en":"According to the timetable, the next bus arrives at 8:15.","zh":"根據時間表，下一班巴士在8:15到達。"},{"en":"If an answer begins with “according to the passage”, it should follow the text closely.","zh":"如果答案以 according to the passage 開始，就應緊貼文章。"},{"en":"The phrase identifies the source of information.","zh":"這個片語指出資料來源。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":19},{"front":"aestivating crocodiles","meaning":"夏眠中的鱷魚","examples":[{"en":"Aestivating crocodiles can remain underground for months.","zh":"夏眠中的鱷魚可以在地下停留數月。"},{"en":"Aestivating crocodiles are crocodiles in a low-activity state during hot or dry periods.","zh":"aestivating crocodiles 指在炎熱或乾燥時期處於低活動狀態的鱷魚。"},{"en":"Researchers may study aestivating crocodiles to understand how they save water.","zh":"研究人員可能研究夏眠中的鱷魚，以了解牠們如何節水。"},{"en":"If crocodiles are aestivating, they may eat little or nothing for a long time.","zh":"如果鱷魚正在夏眠，可能長時間很少進食或完全不進食。"},{"en":"The phrase describes crocodiles while they are in summer dormancy.","zh":"這個片語描述處於夏季休眠狀態的鱷魚。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":19},{"front":"spent around four months","meaning":"花大約四個月","examples":[{"en":"The crocodiles spent around four months of the year underground.","zh":"這些鱷魚一年中花大約四個月在地下。"},{"en":"Spent around four months means used approximately four months doing something or staying somewhere.","zh":"spent around four months 指花大約四個月做某事或待在某處。"},{"en":"A student may spend around four months preparing for a major exam.","zh":"學生可能花大約四個月準備大型考試。"},{"en":"If crocodiles spend around four months underground, the dry season strongly shapes their behaviour.","zh":"如果鱷魚花大約四個月在地下，旱季就強烈塑造牠們的行為。"},{"en":"The phrase gives an approximate duration.","zh":"這個片語給出大約時間長度。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":19},{"front":"no access to water","meaning":"無法取得水源","examples":[{"en":"The crocodiles had no access to water while underground.","zh":"鱷魚在地下時無法取得水源。"},{"en":"No access to water means no ability to reach or use water.","zh":"no access to water 指不能接觸或使用水。"},{"en":"A campsite with no access to water is unsafe for a long stay.","zh":"無法取得水源的營地不適合長時間逗留。"},{"en":"If animals have no access to water, they must conserve body water carefully.","zh":"如果動物無法取得水源，就必須小心保存體內水分。"},{"en":"The phrase describes a serious survival challenge.","zh":"這個片語描述嚴重生存挑戰。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":19},{"front":"the amount of water","meaning":"水分量","examples":[{"en":"The amount of water in their bodies declined during aestivation.","zh":"牠們體內的水分量在夏眠期間下降。"},{"en":"The amount of water means how much water is present.","zh":"the amount of water 指存在多少水分。"},{"en":"A doctor may ask a patient to increase the amount of water they drink each day.","zh":"醫生可能要求病人增加每天飲用的水分量。"},{"en":"If the amount of water in the body falls too low, dehydration can occur.","zh":"如果身體中的水分量降得太低，就可能出現脫水。"},{"en":"The phrase refers to quantity.","zh":"這個片語指數量。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":19},{"front":"declined in proportion to","meaning":"按照……比例下降","examples":[{"en":"The amount of water declined in proportion to body weight.","zh":"水分量按照體重比例下降。"},{"en":"Declined in proportion to means decreased at a matching rate or ratio with something else.","zh":"declined in proportion to 指以與另一事物相配的速度或比例下降。"},{"en":"A shop’s electricity use may decline in proportion to shorter opening hours.","zh":"商店用電量可能按照營業時間縮短的比例下降。"},{"en":"If water loss declines in proportion to weight, the balance between them stays consistent.","zh":"如果水分損失按照體重比例下降，兩者之間的平衡保持一致。"},{"en":"The phrase describes linked decreases.","zh":"這個片語描述相關聯的下降。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":20},{"front":"thus","meaning":"因此","examples":[{"en":"The losses were proportional; thus, there were no signs of dehydration.","zh":"損失成比例；因此沒有脫水跡象。"},{"en":"Thus means therefore or as a result.","zh":"thus 指因此或作為結果。"},{"en":"The class practised daily; thus, their speaking became more fluent.","zh":"全班每天練習；因此，他們的口語變得更流利。"},{"en":"If body losses remain balanced, the animal may avoid dehydration; thus, survival becomes possible.","zh":"如果身體損失保持平衡，動物可能避免脫水；因此，生存變得可能。"},{"en":"The word introduces a logical result.","zh":"這個詞引出邏輯結果。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":20},{"front":"other harmful effects","meaning":"其他有害影響","examples":[{"en":"The crocodiles showed no dehydration or other harmful effects.","zh":"鱷魚沒有顯示脫水或其他有害影響。"},{"en":"Other harmful effects are additional negative results besides the one already mentioned.","zh":"other harmful effects 指除了已提及者外的其他負面結果。"},{"en":"A medicine may stop pain but still cause other harmful effects such as dizziness.","zh":"藥物可能止痛，但仍造成頭暈等其他有害影響。"},{"en":"If no other harmful effects appear, a survival strategy may be safer than expected.","zh":"如果沒有其他有害影響出現，生存策略可能比預期更安全。"},{"en":"The phrase adds possible extra damage.","zh":"這個片語加入可能的額外傷害。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":20},{"front":"this remarkable capacity","meaning":"這種非凡能力","examples":[{"en":"This remarkable capacity helps crocodiles endure severe drought.","zh":"這種非凡能力幫助鱷魚熬過嚴重乾旱。"},{"en":"This remarkable capacity means this impressive ability to do something difficult.","zh":"this remarkable capacity 指這種令人印象深刻、能做到困難事情的能力。"},{"en":"A student’s remarkable capacity to learn languages may show in quick progress and good pronunciation.","zh":"學生學語言的非凡能力可能體現在快速進步和良好發音上。"},{"en":"If crocodiles can wait underground without lasting harm, that capacity is remarkable.","zh":"如果鱷魚能在地下等待而沒有長期傷害，這種能力就很非凡。"},{"en":"The phrase points back to an ability that deserves attention.","zh":"這個片語回指一種值得注意的能力。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":20},{"front":"endure severe drought","meaning":"熬過嚴重乾旱","examples":[{"en":"Crocodiles can endure severe drought without lasting harm.","zh":"鱷魚可以熬過嚴重乾旱而沒有持久傷害。"},{"en":"Endure severe drought means survive a very serious dry period.","zh":"endure severe drought 指熬過非常嚴重的乾旱時期。"},{"en":"Some desert plants endure severe drought by storing water in thick stems.","zh":"有些沙漠植物透過在厚莖中儲水來熬過嚴重乾旱。"},{"en":"If animals endure severe drought, they must reduce water loss or find shelter.","zh":"如果動物熬過嚴重乾旱，就必須減少水分流失或尋找庇護。"},{"en":"The phrase describes survival under extreme dryness.","zh":"這個片語描述在極端乾燥中的生存。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":20},{"front":"without slowing","meaning":"沒有減慢……","examples":[{"en":"Crocodiles can survive drought without slowing their growth rate.","zh":"鱷魚可以熬過乾旱而沒有減慢生長速度。"},{"en":"Without slowing means without reducing the speed of something.","zh":"without slowing 指沒有降低某事的速度。"},{"en":"A student improved English without slowing progress in other subjects by using short daily practice.","zh":"學生透過每天短時間練習改善英語，而沒有減慢其他科目的進度。"},{"en":"If crocodiles survive drought without slowing growth, aestivation does not seem to harm development.","zh":"如果鱷魚熬過乾旱而沒有減慢生長，夏眠似乎沒有損害發展。"},{"en":"The phrase shows that one difficult condition does not reduce another process.","zh":"這個片語顯示某困難條件沒有降低另一過程。"}],"source":"55 - The Evolutionary Mystery - Crocodile Survives.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 56":[{"front":"how deserts are formed","meaning":"沙漠是如何形成的","examples":[{"en":"The passage explains how deserts are formed.","zh":"文章解釋沙漠是如何形成的。"},{"en":"How deserts are formed means the process by which land becomes extremely dry and barren.","zh":"「how deserts are formed」指土地變得極度乾旱和荒蕪的過程。"},{"en":"A geography lesson may explain how deserts are formed through climate, wind, and human activity.","zh":"地理課可能透過氣候、風和人類活動解釋沙漠如何形成。"},{"en":"If vegetation disappears and rainfall is low, land may slowly become desert-like.","zh":"如果植被消失而降雨少，土地可能慢慢變得像沙漠。"},{"en":"The phrase focuses on the process, not just the appearance of deserts.","zh":"這個短語集中於形成過程，而不只是沙漠外觀。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":1},{"front":"refer to","meaning":"指的是","examples":[{"en":"A desert refers to a barren section of land.","zh":"沙漠指的是一片荒蕪的土地。"},{"en":"To refer to something means to mean, describe, or point to it.","zh":"「refer to」某物，意思是指、描述或表示它。"},{"en":"In class, “precipitation” refers to rain, snow, or other water falling from the sky.","zh":"在課堂上，“precipitation” 指雨、雪或其他從天空落下的水。"},{"en":"If a word refers to a process, students should learn what happens step by step.","zh":"如果一個詞指某個過程，學生應學會每一步發生甚麼。"},{"en":"The phrase is useful when giving definitions.","zh":"這個短語常用於下定義。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":1},{"front":"a barren section of land","meaning":"一片荒蕪的土地","examples":[{"en":"A desert refers to a barren section of land.","zh":"沙漠指的是一片荒蕪的土地。"},{"en":"A barren section of land is an area where very little can grow.","zh":"「a barren section of land」是幾乎沒有東西能生長的土地區域。"},{"en":"An abandoned field may become a barren section of land if the soil is badly damaged.","zh":"如果土壤嚴重受損，廢棄田地可能變成一片荒蕪的土地。"},{"en":"Without water or plant cover, land can become dry, empty, and unproductive.","zh":"沒有水或植被覆蓋，土地可能變得乾燥、空曠而沒有生產力。"},{"en":"The phrase describes land that is harsh and not fertile.","zh":"這個短語描述惡劣且不肥沃的土地。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":1},{"front":"arid and semi-arid areas","meaning":"乾旱及半乾旱地區","examples":[{"en":"Deserts are mainly found in arid and semi-arid areas.","zh":"沙漠主要出現在乾旱及半乾旱地區。"},{"en":"Arid and semi-arid areas are dry places with very little or limited rainfall.","zh":"「arid and semi-arid areas」是降雨很少或有限的乾燥地區。"},{"en":"Farmers in arid and semi-arid areas often need careful water management.","zh":"乾旱及半乾旱地區的農民通常需要仔細管理用水。"},{"en":"If rainfall becomes unreliable, these areas can become more vulnerable to desertification.","zh":"如果降雨變得不可靠，這些地區可能更容易沙漠化。"},{"en":"The phrase describes dry regions, not necessarily complete deserts.","zh":"這個短語描述乾燥地區，不一定是完整沙漠。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":1},{"front":"arid areas","meaning":"乾旱地區","examples":[{"en":"Arid areas receive very little precipitation.","zh":"乾旱地區接收非常少降水。"},{"en":"Arid areas are regions that are extremely dry.","zh":"「arid areas」是極度乾燥的地區。"},{"en":"A village in an arid area may depend on wells or stored rainwater.","zh":"乾旱地區的村莊可能依賴井水或儲存雨水。"},{"en":"Because arid areas lack moisture, plants and crops struggle to survive there.","zh":"因為乾旱地區缺乏水分，植物和農作物很難生存。"},{"en":"The phrase describes land with very limited water.","zh":"這個短語描述水分非常有限的土地。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":1},{"front":"semi-arid areas","meaning":"半乾旱地區","examples":[{"en":"Semi-arid areas are vulnerable to desertification.","zh":"半乾旱地區容易受到沙漠化影響。"},{"en":"Semi-arid areas are partly dry regions that receive some rainfall but not much.","zh":"「semi-arid areas」是部分乾燥、仍有一些降雨但不多的地區。"},{"en":"Farmers in semi-arid areas may grow crops only during short rainy seasons.","zh":"半乾旱地區的農民可能只在短暫雨季種植作物。"},{"en":"If vegetation is removed, semi-arid areas can lose soil quickly.","zh":"如果植被被移除，半乾旱地區可能很快失去土壤。"},{"en":"The phrase describes land between dry grassland and desert.","zh":"這個短語描述介乎乾燥草地和沙漠之間的土地。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":1},{"front":"almost no precipitation","meaning":"幾乎沒有降雨","examples":[{"en":"In a desert, there is almost no precipitation.","zh":"在沙漠中，幾乎沒有降雨。"},{"en":"Almost no precipitation means there is hardly any rain, snow, or other falling water.","zh":"「almost no precipitation」意思是幾乎沒有雨、雪或其他降水。"},{"en":"A town with almost no precipitation must store water very carefully.","zh":"幾乎沒有降雨的城鎮必須非常小心儲水。"},{"en":"If almost no precipitation falls for years, plants may disappear from the land.","zh":"如果多年幾乎沒有降水，植物可能從土地上消失。"},{"en":"The phrase stresses extreme dryness.","zh":"這個短語強調極端乾燥。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":1},{"front":"precipitation","meaning":"降水；降雨","examples":[{"en":"Precipitation is extremely limited in desert regions.","zh":"沙漠地區的降水極其有限。"},{"en":"Precipitation is water that falls from the sky, such as rain, snow, or hail.","zh":"「precipitation」是從天空落下的水，例如雨、雪或冰雹。"},{"en":"Farmers watch precipitation levels to decide when to plant crops.","zh":"農民會留意降水量來決定何時種植作物。"},{"en":"If precipitation decreases, rivers, soil moisture, and crops may all suffer.","zh":"如果降水減少，河流、土壤水分和農作物都可能受影響。"},{"en":"The word is more scientific than simply saying “rain”.","zh":"這個詞比單純說 “rain” 更科學。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":1},{"front":"be hostile to life","meaning":"對生命構成惡劣環境","examples":[{"en":"The environment in a desert is hostile to life.","zh":"沙漠環境對生命構成惡劣環境。"},{"en":"To be hostile to life means to be so harsh that living things struggle to survive.","zh":"「be hostile to life」意思是環境嚴酷到令生物難以生存。"},{"en":"A polluted river can be hostile to fish and plants.","zh":"受污染河流可能對魚類和植物構成惡劣環境。"},{"en":"If heat, dryness, and poor soil combine, the land becomes hostile to life.","zh":"如果高溫、乾燥和貧瘠土壤結合，土地就會不利生命。"},{"en":"The phrase describes conditions that make survival difficult.","zh":"這個短語描述令生存困難的條件。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":1},{"front":"classify something in a number of ways","meaning":"以多種方式分類……","examples":[{"en":"Deserts have been classified in a number of ways.","zh":"沙漠已被以多種方式分類。"},{"en":"To classify something in a number of ways means to organise it using several different systems.","zh":"「classify something in a number of ways」意思是用幾套不同系統整理某物。"},{"en":"Teachers can classify books by genre, level, author, or topic.","zh":"老師可以按類型、程度、作者或主題分類書本。"},{"en":"If scientists use different criteria, the same desert may be classified differently.","zh":"如果科學家使用不同標準，同一個沙漠可能被不同分類。"},{"en":"The phrase shows that there is not only one method of grouping things.","zh":"這個短語顯示分類不只有一種方法。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":1},{"front":"combine several factors","meaning":"結合幾個因素","examples":[{"en":"Scientists classify deserts by combining several factors.","zh":"科學家透過結合幾個因素來分類沙漠。"},{"en":"To combine several factors means to consider a few causes, features, or measurements together.","zh":"「combine several factors」意思是把幾個原因、特徵或測量一起考慮。"},{"en":"A doctor may combine several factors before deciding on treatment.","zh":"醫生可能結合幾個因素才決定治療方法。"},{"en":"If rainfall, temperature, and humidity are combined, desert classification becomes more accurate.","zh":"如果把降雨、氣溫和濕度結合起來，沙漠分類會更準確。"},{"en":"The phrase shows that one factor alone is not enough.","zh":"這個短語顯示單一因素並不足夠。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":1},{"front":"total precipitation","meaning":"總降水量","examples":[{"en":"Total precipitation is one way to classify deserts.","zh":"總降水量是分類沙漠的一種方式。"},{"en":"Total precipitation means the full amount of rain, snow, or other water received over a period.","zh":"「total precipitation」指某段時間內接收的雨、雪或其他降水總量。"},{"en":"A city may compare total precipitation this year with last year’s rainfall.","zh":"城市可能把今年總降水量與去年降雨量比較。"},{"en":"If total precipitation is extremely low, the region may be classified as desert.","zh":"如果總降水量極低，該地區可能被分類為沙漠。"},{"en":"The phrase measures the overall water input from the sky.","zh":"這個短語量度來自天空的整體水分輸入。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":2},{"front":"the number of days on which rain falls","meaning":"下雨日數","examples":[{"en":"Desert classification may consider the number of days on which rain falls.","zh":"沙漠分類可能考慮下雨日數。"},{"en":"The number of days on which rain falls means how many days receive rain in a period.","zh":"「the number of days on which rain falls」指某段期間有多少天下雨。"},{"en":"A school trip planner may check the number of rainy days in summer.","zh":"學校旅行策劃者可能查看夏天下雨日數。"},{"en":"If rain falls on very few days, plants may struggle even if one storm is heavy.","zh":"如果下雨日數很少，即使某次暴雨很大，植物仍可能難以生存。"},{"en":"The phrase focuses on rainfall frequency, not just total amount.","zh":"這個短語集中於降雨頻率，而不只是總量。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":2},{"front":"temperature and humidity","meaning":"氣溫和濕度","examples":[{"en":"Temperature and humidity are used to classify deserts.","zh":"氣溫和濕度被用來分類沙漠。"},{"en":"Temperature and humidity mean how hot the air is and how much water vapour it contains.","zh":"「temperature and humidity」指空氣有多熱，以及含有多少水汽。"},{"en":"A classroom can feel uncomfortable when temperature and humidity are both high.","zh":"當氣溫和濕度都高時，課室會令人不舒服。"},{"en":"If heat is high and humidity is low, water evaporates quickly from soil.","zh":"如果氣溫高而濕度低，水分會很快從土壤蒸發。"},{"en":"The phrase describes two important climate conditions.","zh":"這個短語描述兩個重要氣候條件。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":2},{"front":"additional factors","meaning":"額外因素","examples":[{"en":"Some systems also consider additional factors.","zh":"有些系統也考慮額外因素。"},{"en":"Additional factors are extra things considered beyond the main ones.","zh":"「additional factors」是主要因素以外再考慮的其他事情。"},{"en":"When choosing a school, distance and fees matter, but additional factors may include class size.","zh":"選校時，距離和學費重要，但額外因素可能包括班級大小。"},{"en":"If scientists add more factors, classification may become more detailed.","zh":"如果科學家加入更多因素，分類可能變得更細緻。"},{"en":"The phrase means “other relevant factors too”.","zh":"這個短語意思是「其他相關因素也包括在內」。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":2},{"front":"clear boundaries","meaning":"清晰邊界","examples":[{"en":"Some deserts have clear boundaries marked by landforms.","zh":"有些沙漠有由地形標示的清晰邊界。"},{"en":"Clear boundaries are easy-to-see limits between one area and another.","zh":"「clear boundaries」是兩個區域之間容易看見的界線。"},{"en":"Students need clear boundaries between study time and rest time.","zh":"學生需要在溫習時間和休息時間之間有清晰界線。"},{"en":"If a river marks a desert edge, the boundary may be easy to identify.","zh":"如果河流標示沙漠邊緣，邊界可能容易辨認。"},{"en":"The phrase describes limits that are not vague.","zh":"這個短語描述不模糊的界線。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":2},{"front":"be marked by","meaning":"以……作為標記","examples":[{"en":"Some desert boundaries are marked by rivers or mountains.","zh":"有些沙漠邊界以河流或山脈作為標記。"},{"en":"To be marked by something means to be shown or indicated by it.","zh":"「be marked by」某物，意思是由它顯示或標示出來。"},{"en":"A school entrance may be marked by a large sign.","zh":"學校入口可能以大型招牌作為標記。"},{"en":"If a boundary is marked by mountains, people can see where one region ends.","zh":"如果邊界以山脈作標記，人們可以看到一個地區在哪裡結束。"},{"en":"The phrase explains what makes something visible or identifiable.","zh":"這個短語解釋甚麼令某物可見或可辨認。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":2},{"front":"rivers, mountains or other landforms","meaning":"河流、山脈或其他地形","examples":[{"en":"Desert boundaries may be marked by rivers, mountains or other landforms.","zh":"沙漠邊界可能以河流、山脈或其他地形作標記。"},{"en":"Rivers, mountains or other landforms are natural features that shape the land.","zh":"「rivers, mountains or other landforms」是塑造土地的自然特徵。"},{"en":"A map may use rivers and mountains to show where regions begin and end.","zh":"地圖可能用河流和山脈顯示地區從哪裡開始和結束。"},{"en":"If landforms form boundaries, people can identify areas more easily.","zh":"如果地形形成邊界，人們可以更容易辨認地區。"},{"en":"The phrase lists physical features of the landscape.","zh":"這個短語列出景觀中的自然特徵。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":2},{"front":"landforms","meaning":"地形","examples":[{"en":"Mountains and rivers are examples of landforms.","zh":"山脈和河流都是地形的例子。"},{"en":"Landforms are natural shapes or features on Earth’s surface.","zh":"「landforms」是地球表面的自然形狀或特徵。"},{"en":"Valleys, cliffs, dunes, and hills are all landforms.","zh":"山谷、懸崖、沙丘和山丘都是地形。"},{"en":"Landforms can affect where people build roads, farms, and towns.","zh":"地形可以影響人們在哪裡建路、耕作和建城鎮。"},{"en":"The phrase is common in geography.","zh":"這個短語常見於地理。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":2},{"front":"clear-cut borders","meaning":"清晰明確的邊界","examples":[{"en":"Some deserts do not have clear-cut borders.","zh":"有些沙漠沒有清晰明確的邊界。"},{"en":"Clear-cut borders are exact and easy-to-identify boundaries.","zh":"「clear-cut borders」是準確而容易辨認的邊界。"},{"en":"A country may have clear-cut borders if fences or rivers mark them.","zh":"如果有圍欄或河流標示，國家可能有清晰明確的邊界。"},{"en":"If deserts spread gradually into grassland, the border may not be clear-cut.","zh":"如果沙漠逐漸擴展到草地，邊界可能並不明確。"},{"en":"The phrase describes boundaries without uncertainty.","zh":"這個短語描述沒有不確定性的邊界。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":2},{"front":"between desert and other landscapes","meaning":"沙漠與其他地貌之間","examples":[{"en":"There may be no clear-cut borders between desert and other landscapes.","zh":"沙漠與其他地貌之間可能沒有清晰明確的邊界。"},{"en":"Between desert and other landscapes means in the area where desert meets other land types.","zh":"「between desert and other landscapes」指沙漠與其他土地類型交接的區域。"},{"en":"A traveller may see dry grassland between desert and farmland.","zh":"旅客可能在沙漠與農地之間看到乾燥草地。"},{"en":"If one landscape changes gradually into another, the boundary is hard to draw.","zh":"如果一種地貌逐漸變成另一種地貌，邊界就難以劃定。"},{"en":"The phrase describes a transition zone.","zh":"這個短語描述過渡地帶。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":2},{"front":"vegetation cover","meaning":"植被覆蓋","examples":[{"en":"Vegetation cover protects the land from erosion.","zh":"植被覆蓋保護土地免受侵蝕。"},{"en":"Vegetation cover means the plants that cover and protect the soil.","zh":"「vegetation cover」指覆蓋並保護土壤的植物。"},{"en":"Grass in a school field is vegetation cover that stops soil from blowing away.","zh":"學校操場上的草是防止泥土被吹走的植被覆蓋。"},{"en":"If vegetation cover is removed, wind and rain can damage the soil more easily.","zh":"如果植被覆蓋被移除，風和雨會更容易破壞土壤。"},{"en":"The phrase describes a natural protective layer.","zh":"這個短語描述天然保護層。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":2},{"front":"protect the land","meaning":"保護土地","examples":[{"en":"Vegetation cover helps protect the land.","zh":"植被覆蓋有助保護土地。"},{"en":"To protect the land means to keep soil and ground from being damaged.","zh":"「protect the land」意思是防止土壤和地面受損。"},{"en":"Farmers plant grass strips to protect the land from heavy rain.","zh":"農民種植草帶來保護土地免受大雨侵蝕。"},{"en":"If land is protected, it can keep producing crops and supporting plants.","zh":"如果土地受到保護，它可以繼續生產農作物並支持植物生長。"},{"en":"The phrase focuses on preventing damage to soil and surface.","zh":"這個短語集中於防止土壤和地表受損。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":3},{"front":"sand and dust storms","meaning":"沙塵暴","examples":[{"en":"Sand and dust storms frequently take place in arid areas.","zh":"沙塵暴經常在乾旱地區發生。"},{"en":"Sand and dust storms are strong winds carrying sand or fine dust through the air.","zh":"「sand and dust storms」是強風吹起沙粒或幼細塵埃在空中移動。"},{"en":"A city near a desert may close schools during severe dust storms.","zh":"沙漠附近的城市可能在嚴重沙塵暴期間停課。"},{"en":"If soil is exposed and dry, wind can lift particles and create storms.","zh":"如果土壤裸露又乾燥，風可以捲起微粒並形成風暴。"},{"en":"The phrase describes dangerous weather linked to dry land.","zh":"這個短語描述與乾旱土地相關的危險天氣。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":3},{"front":"frequently take place","meaning":"經常發生","examples":[{"en":"Sand and dust storms frequently take place where vegetation is absent.","zh":"沙塵暴經常在沒有植被的地方發生。"},{"en":"To frequently take place means to happen often.","zh":"「frequently take place」意思是經常發生。"},{"en":"Traffic jams frequently take place near schools at dismissal time.","zh":"放學時間，學校附近經常發生交通擠塞。"},{"en":"If vegetation disappears, dust storms may take place more often.","zh":"如果植被消失，沙塵暴可能更常發生。"},{"en":"The phrase describes repeated occurrence.","zh":"這個短語描述重複出現。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":3},{"front":"this phenomenon","meaning":"這種現象","examples":[{"en":"This phenomenon often occurs at desert margins.","zh":"這種現象常在沙漠邊緣發生。"},{"en":"This phenomenon means the event or situation just described.","zh":"「this phenomenon」指剛才描述的事件或情況。"},{"en":"If many students feel tired after lunch, this phenomenon may be linked to heavy meals.","zh":"如果許多學生午飯後感到疲倦，這種現象可能與吃得太飽有關。"},{"en":"When a writer says “this phenomenon”, readers should look back to the previous idea.","zh":"當作者說 “this phenomenon”，讀者應回看前面的想法。"},{"en":"The phrase points to a specific observed event.","zh":"這個短語指某個具體觀察到的事件。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":3},{"front":"occur at desert margins","meaning":"在沙漠邊緣發生","examples":[{"en":"Sand and dust storms often occur at desert margins.","zh":"沙塵暴常在沙漠邊緣發生。"},{"en":"To occur at desert margins means to happen near the edges of deserts.","zh":"「occur at desert margins」意思是在沙漠邊緣附近發生。"},{"en":"Villages at desert margins may experience dust storms more often than towns far away.","zh":"位於沙漠邊緣的村莊可能比遠處城鎮更常經歷沙塵暴。"},{"en":"If fine particles remain near the edge, storms may start there.","zh":"如果幼細微粒仍留在邊緣附近，風暴可能在那裡開始。"},{"en":"The phrase describes where the event usually happens.","zh":"這個短語描述事件通常發生的位置。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":3},{"front":"desert margins","meaning":"沙漠邊緣","examples":[{"en":"Fine particles are often found at desert margins.","zh":"幼細微粒常出現在沙漠邊緣。"},{"en":"Desert margins are the edge areas where desert meets other land.","zh":"「desert margins」是沙漠與其他土地交接的邊緣地區。"},{"en":"Farmers living near desert margins may worry about sand moving into fields.","zh":"住在沙漠邊緣附近的農民可能擔心沙粒移入田地。"},{"en":"If desert margins lose vegetation, desertification can spread outward.","zh":"如果沙漠邊緣失去植被，沙漠化可能向外擴展。"},{"en":"The phrase describes a vulnerable transition zone.","zh":"這個短語描述脆弱的過渡地帶。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":3},{"front":"instead of within the deserts","meaning":"而不是在沙漠內部","examples":[{"en":"Dust storms often occur at desert margins instead of within the deserts.","zh":"沙塵暴常在沙漠邊緣發生，而不是在沙漠內部。"},{"en":"Instead of within the deserts means not inside the deserts, but in another nearby area.","zh":"「instead of within the deserts」意思是不在沙漠內部，而是在附近另一區域。"},{"en":"A school event may be held in the hall instead of within the classrooms.","zh":"學校活動可能在禮堂舉行，而不是在課室內。"},{"en":"If storms occur at the edges, the cause may be different from conditions deep inside deserts.","zh":"如果風暴在邊緣發生，其原因可能不同於沙漠深處的情況。"},{"en":"The phrase creates a clear location contrast.","zh":"這個短語建立清楚的位置對比。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":3},{"front":"finer materials","meaning":"較幼細的物質","examples":[{"en":"There are often no finer materials left inside the deserts.","zh":"沙漠內部通常已沒有較幼細的物質留下。"},{"en":"Finer materials are very small particles, such as dust or fine sand.","zh":"「finer materials」是非常細小的微粒，例如塵土或細沙。"},{"en":"A gardener may use fine soil particles for planting small seeds.","zh":"園丁可能使用細小泥土微粒來種小種子。"},{"en":"If wind removes finer materials, only heavier sand or stones may remain.","zh":"如果風移走較幼細物質，可能只剩較重的沙或石頭。"},{"en":"The phrase refers to small, light materials that wind can move easily.","zh":"這個短語指容易被風吹動的細小輕質物。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":3},{"front":"a steady wind","meaning":"穩定吹動的風","examples":[{"en":"A steady wind can set fine particles in motion.","zh":"穩定吹動的風可以使幼細微粒開始移動。"},{"en":"A steady wind is a wind that blows continuously at a fairly regular speed.","zh":"「a steady wind」是以相當穩定速度持續吹動的風。"},{"en":"A steady wind can help dry clothes faster on a washing line.","zh":"穩定吹動的風可以令晾衣繩上的衣服更快乾。"},{"en":"If steady wind blows over exposed soil, small particles may begin to move.","zh":"如果穩定風掠過裸露土壤，小微粒可能開始移動。"},{"en":"The phrase describes wind that is constant, not sudden.","zh":"這個短語描述持續的風，而不是突如其來的風。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":3},{"front":"start to blow","meaning":"開始吹起","examples":[{"en":"When a steady wind starts to blow, fine particles begin vibrating.","zh":"當穩定的風開始吹起，幼細微粒開始震動。"},{"en":"To start to blow means for wind to begin moving through an area.","zh":"「start to blow」意思是風開始在某區域移動。"},{"en":"When the wind starts to blow, people may close windows to keep papers from flying.","zh":"當風開始吹起，人們可能關窗以免紙張飛走。"},{"en":"If wind starts to blow across dry ground, dust may begin to rise.","zh":"如果風開始吹過乾地，塵土可能開始升起。"},{"en":"The phrase marks the beginning of wind movement.","zh":"這個短語標示風開始移動。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":3},{"front":"fine particles","meaning":"幼細微粒","examples":[{"en":"Fine particles on open ground begin vibrating in the wind.","zh":"空曠地面上的幼細微粒在風中開始震動。"},{"en":"Fine particles are very small pieces of dust, sand, or soil.","zh":"「fine particles」是非常細小的塵、沙或土壤碎粒。"},{"en":"Fine particles can enter a classroom through open windows during a dust storm.","zh":"沙塵暴期間，幼細微粒可以透過開着的窗進入課室。"},{"en":"Because fine particles are light, wind can lift them into the air.","zh":"因為幼細微粒很輕，風可以把它們捲到空中。"},{"en":"The phrase describes small materials that are easily moved.","zh":"這個短語描述容易被移動的細小物質。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":3},{"front":"on the open ground","meaning":"在空曠地面上","examples":[{"en":"Fine particles on the open ground begin vibrating.","zh":"空曠地面上的幼細微粒開始震動。"},{"en":"On the open ground means on land that is exposed and not covered by plants or buildings.","zh":"「on the open ground」意思是在沒有植物或建築物遮蓋的裸露土地上。"},{"en":"Children playing on open ground may feel the wind more strongly than those indoors.","zh":"在空曠地面上玩耍的孩子，可能比室內的人更感到風力。"},{"en":"If soil lies on open ground, it is more exposed to wind erosion.","zh":"如果土壤位於空曠地面上，它更容易受風蝕。"},{"en":"The phrase describes exposed surface land.","zh":"這個短語描述裸露的地表。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":4},{"front":"begin vibrating","meaning":"開始震動","examples":[{"en":"Fine particles begin vibrating when the wind starts to blow.","zh":"當風開始吹起，幼細微粒開始震動。"},{"en":"To begin vibrating means to start shaking quickly in small movements.","zh":"「begin vibrating」意思是開始快速地小幅震動。"},{"en":"A phone may begin vibrating when a message arrives.","zh":"電話收到訊息時可能開始震動。"},{"en":"If soil particles begin vibrating, they may soon be lifted by stronger wind.","zh":"如果土壤微粒開始震動，它們可能很快被更強的風吹起。"},{"en":"The phrase describes the first stage of movement.","zh":"這個短語描述移動的第一階段。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":4},{"front":"as the wind picks up","meaning":"隨着風勢增強","examples":[{"en":"As the wind picks up, particles are lifted into the air.","zh":"隨着風勢增強，微粒被捲到空中。"},{"en":"As the wind picks up means as the wind becomes stronger.","zh":"「as the wind picks up」意思是隨着風變強。"},{"en":"As the wind picks up, people at a beach may pack away umbrellas.","zh":"隨着風勢增強，沙灘上的人可能收起太陽傘。"},{"en":"If wind speed increases, loose dust and sand can rise into the air.","zh":"如果風速增加，鬆散塵土和沙粒可以升到空中。"},{"en":"The phrase links stronger wind with its result.","zh":"這個短語把風變強與結果連繫起來。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":4},{"front":"pick up","meaning":"增強；加大","examples":[{"en":"The wind picks up and lifts particles into the air.","zh":"風勢增強並把微粒捲到空中。"},{"en":"When wind picks up, it becomes stronger.","zh":"當風 picks up，意思是風變強。"},{"en":"If rain picks up, students may wait indoors before going home.","zh":"如果雨勢加大，學生可能留在室內等候回家。"},{"en":"When wind picks up over dry soil, dust can start moving quickly.","zh":"當風在乾土上增強，塵土可以迅速開始移動。"},{"en":"The phrase describes an increase in force or speed.","zh":"這個短語描述力量或速度增加。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":4},{"front":"be lifted into the air","meaning":"被捲到空中","examples":[{"en":"Some fine particles are lifted into the air.","zh":"有些幼細微粒被捲到空中。"},{"en":"To be lifted into the air means to be carried upward by wind or force.","zh":"「be lifted into the air」意思是被風或力量向上帶起。"},{"en":"Leaves are lifted into the air when a strong gust passes through a park.","zh":"當一陣強風穿過公園，樹葉會被捲到空中。"},{"en":"If dust is lifted into the air, visibility and breathing may become worse.","zh":"如果塵土被捲到空中，能見度和呼吸情況可能變差。"},{"en":"The phrase describes movement from ground to air.","zh":"這個短語描述從地面到空中的移動。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":4},{"front":"fall onto the ground","meaning":"落到地面上","examples":[{"en":"The particles fall onto the ground and hit other particles.","zh":"微粒落到地面上並撞擊其他微粒。"},{"en":"To fall onto the ground means to drop down and land on the surface of the earth.","zh":"「fall onto the ground」意思是向下掉落並落在地面表面。"},{"en":"Rain drops fall onto the ground during a storm.","zh":"暴風雨期間，雨滴落到地面上。"},{"en":"When airborne particles fall down, they can disturb other loose particles.","zh":"當空中微粒落下，它們可以擾動其他鬆散微粒。"},{"en":"The phrase describes downward movement.","zh":"這個短語描述向下移動。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":4},{"front":"hit other particles","meaning":"撞擊其他微粒","examples":[{"en":"The falling particles hit other particles on the ground.","zh":"落下的微粒撞擊地面上的其他微粒。"},{"en":"To hit other particles means to strike small pieces of dust, sand, or soil nearby.","zh":"「hit other particles」意思是撞到附近的塵、沙或土壤小粒。"},{"en":"A falling marble may hit other marbles and make them move.","zh":"掉下的彈珠可能撞擊其他彈珠並令它們移動。"},{"en":"If one particle hits another, it can start a chain of movement.","zh":"如果一粒微粒撞擊另一粒，它可以引發一連串移動。"},{"en":"The phrase describes physical impact.","zh":"這個短語描述物理撞擊。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":4},{"front":"be jerked into the air","meaning":"被猛然帶到空中","examples":[{"en":"Other particles are jerked into the air in their turn.","zh":"其他微粒接着被猛然帶到空中。"},{"en":"To be jerked into the air means to be suddenly pulled or thrown upward.","zh":"「be jerked into the air」意思是被突然拉起或拋向空中。"},{"en":"A kite may be jerked into the air when a strong wind catches it.","zh":"當強風抓住風箏，風箏可能被猛然帶到空中。"},{"en":"If particles are suddenly jerked upward, a dust cloud can grow quickly.","zh":"如果微粒突然被帶到空中，塵雲可以快速擴大。"},{"en":"The phrase suggests sudden, sharp movement.","zh":"這個短語暗示突然而急促的移動。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":4},{"front":"in their turn","meaning":"輪到它們；接着","examples":[{"en":"Other particles are then jerked into the air in their turn.","zh":"其他微粒接着輪到它們被猛然帶到空中。"},{"en":"In their turn means when their time or sequence comes.","zh":"「in their turn」意思是輪到它們或到它們的順序時。"},{"en":"Students answer questions in their turn during a speaking exam.","zh":"在口試中，學生輪到自己時回答問題。"},{"en":"If each particle moves in its turn, the process can spread step by step.","zh":"如果每粒微粒按次序移動，過程可以一步步擴散。"},{"en":"The phrase describes ordered sequence.","zh":"這個短語描述有順序的過程。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":4},{"front":"initiate a chain reaction","meaning":"引發連鎖反應","examples":[{"en":"The movement of particles initiates a chain reaction.","zh":"微粒的移動引發連鎖反應。"},{"en":"To initiate a chain reaction means to start a series of events where one causes the next.","zh":"「initiate a chain reaction」意思是開始一連串一個導致下一個的事件。"},{"en":"One student laughing may initiate a chain reaction across the classroom.","zh":"一名學生笑起來可能引發整個課室的連鎖反應。"},{"en":"If one particle knocks another into the air, more particles may follow.","zh":"如果一粒微粒把另一粒撞到空中，更多微粒可能跟着移動。"},{"en":"The phrase describes the start of a spreading process.","zh":"這個短語描述擴散過程的開始。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":4},{"front":"a chain reaction","meaning":"連鎖反應","examples":[{"en":"A chain reaction begins when falling particles hit other particles.","zh":"當落下的微粒撞擊其他微粒時，連鎖反應開始。"},{"en":"A chain reaction is a series of events where each event causes the next one.","zh":"「a chain reaction」是一連串每一件事都造成下一件事的事件。"},{"en":"One late bus can create a chain reaction of missed lessons and appointments.","zh":"一班遲到的巴士可以造成錯過課堂和約會的連鎖反應。"},{"en":"In a dust storm, one moving particle can disturb many others.","zh":"在沙塵暴中，一粒移動中的微粒可以擾動許多其他微粒。"},{"en":"The phrase shows how a small start can create a larger result.","zh":"這個短語顯示小開始可以造成更大結果。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":4},{"front":"a great deal of publicity","meaning":"大量宣傳；廣泛報道","examples":[{"en":"There has been a great deal of publicity about desertification.","zh":"關於沙漠化已有大量宣傳和廣泛報道。"},{"en":"A great deal of publicity means a lot of public attention, media coverage, or discussion.","zh":"「a great deal of publicity」意思是大量公眾關注、媒體報道或討論。"},{"en":"A new school policy may receive a great deal of publicity if parents disagree.","zh":"如果家長不同意新校政，它可能獲得大量報道。"},{"en":"If an environmental problem receives publicity, more people may become aware of it.","zh":"如果環境問題受到廣泛報道，更多人可能意識到它。"},{"en":"The phrase describes widespread attention.","zh":"這個短語描述廣泛關注。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":5},{"front":"how severe desertification can be","meaning":"沙漠化可以有多嚴重","examples":[{"en":"There has been publicity about how severe desertification can be.","zh":"關於沙漠化可以有多嚴重已有廣泛報道。"},{"en":"How severe desertification can be means how serious and damaging desertification may become.","zh":"「how severe desertification can be」意思是沙漠化可能變得多嚴重和有破壞性。"},{"en":"A documentary may show how severe flooding can be after forests are removed.","zh":"紀錄片可能展示森林被移除後洪水可以有多嚴重。"},{"en":"If people understand the severity of desertification, they may support prevention measures.","zh":"如果人們理解沙漠化的嚴重性，他們可能支持預防措施。"},{"en":"The phrase focuses on the possible seriousness of the problem.","zh":"這個短語集中於問題可能有多嚴重。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":5},{"front":"desertification","meaning":"沙漠化","examples":[{"en":"Human activities are often responsible for desertification.","zh":"人類活動往往是沙漠化的原因。"},{"en":"Desertification is the process by which fertile or usable land becomes desert-like.","zh":"「desertification」是肥沃或可用土地變得像沙漠的過程。"},{"en":"Overgrazing and tree cutting can contribute to desertification in dry regions.","zh":"過度放牧和砍樹可以促成乾旱地區沙漠化。"},{"en":"If soil loses plants and moisture, desertification may advance.","zh":"如果土壤失去植物和水分，沙漠化可能推進。"},{"en":"The word describes land degradation, not simply natural deserts.","zh":"這個詞描述土地退化，而不只是天然沙漠。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":5},{"front":"the academic community","meaning":"學術界","examples":[{"en":"The academic community has not agreed on the causes of desertification.","zh":"學術界尚未就沙漠化成因達成共識。"},{"en":"The academic community means scholars, researchers, and experts in universities or research fields.","zh":"「the academic community」指大學或研究領域中的學者、研究人員和專家。"},{"en":"The academic community may debate new findings before accepting them.","zh":"學術界可能先辯論新發現，再接受它們。"},{"en":"If experts disagree, the causes of a problem may be complex.","zh":"如果專家意見不同，問題成因可能很複雜。"},{"en":"The phrase refers to researchers as a group.","zh":"這個短語指作為群體的研究者。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":5},{"front":"agree on the causes of","meaning":"對……的成因達成共識","examples":[{"en":"Scientists have not agreed on the causes of desertification.","zh":"科學家尚未對沙漠化的成因達成共識。"},{"en":"To agree on the causes of something means to share the same explanation for why it happens.","zh":"「agree on the causes of」某事，意思是對它為何發生有共同解釋。"},{"en":"Doctors may not agree on the causes of a patient’s repeated headaches at first.","zh":"醫生起初可能未能對病人反覆頭痛的成因達成共識。"},{"en":"If experts cannot agree on causes, solutions may be harder to design.","zh":"如果專家不能就成因達成共識，設計解決方案會更困難。"},{"en":"The phrase focuses on reaching shared explanation.","zh":"這個短語集中於形成共同解釋。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":5},{"front":"a common misunderstanding","meaning":"常見誤解","examples":[{"en":"A common misunderstanding is that lack of rain causes desertification.","zh":"一個常見誤解是降雨不足導致沙漠化。"},{"en":"A common misunderstanding is a wrong idea that many people believe.","zh":"「a common misunderstanding」是許多人相信的錯誤想法。"},{"en":"A common misunderstanding is that all deserts are hot, but some are cold.","zh":"一個常見誤解是所有沙漠都很熱，但有些是寒冷沙漠。"},{"en":"If many people misunderstand the cause, they may support the wrong solution.","zh":"如果許多人誤解成因，他們可能支持錯誤解決方法。"},{"en":"The phrase introduces a popular but incorrect belief.","zh":"這個短語引入流行但不正確的信念。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":5},{"front":"a shortage of precipitation","meaning":"降水不足","examples":[{"en":"A shortage of precipitation is often wrongly blamed for desertification.","zh":"降水不足常被錯誤歸咎為沙漠化的原因。"},{"en":"A shortage of precipitation means not enough rain, snow, or other water falling from the sky.","zh":"「a shortage of precipitation」意思是雨、雪或其他降水不足。"},{"en":"A farm may struggle when there is a shortage of precipitation during the growing season.","zh":"如果生長季節降水不足，農場可能難以運作。"},{"en":"If people blame only rainfall shortage, they may ignore human land use.","zh":"如果人們只責怪降雨不足，他們可能忽略人類土地使用。"},{"en":"The phrase describes lack of water from weather.","zh":"這個短語描述天氣帶來的水分不足。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":5},{"front":"cause desertification","meaning":"導致沙漠化","examples":[{"en":"Human activities can cause desertification.","zh":"人類活動可以導致沙漠化。"},{"en":"To cause desertification means to make land become degraded and desert-like.","zh":"「cause desertification」意思是令土地退化並變得像沙漠。"},{"en":"Cutting trees for fuel can cause desertification in dry regions.","zh":"在乾旱地區砍樹作燃料可以導致沙漠化。"},{"en":"If farming removes plant cover, soil may erode and desertification may begin.","zh":"如果耕作移除植被覆蓋，土壤可能侵蝕，沙漠化可能開始。"},{"en":"The phrase shows a direct cause of land degradation.","zh":"這個短語顯示土地退化的直接原因。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":5},{"front":"barren areas","meaning":"荒蕪地區","examples":[{"en":"Some barren areas can recover after rain falls.","zh":"有些荒蕪地區在降雨後可以恢復。"},{"en":"Barren areas are places where little or no vegetation grows.","zh":"「barren areas」是幾乎沒有植被生長的地方。"},{"en":"A dry field may look barren after a long drought.","zh":"長期乾旱後，乾田可能看起來像荒蕪地區。"},{"en":"If rain returns and soil is not destroyed, barren areas may grow plants again.","zh":"如果雨水回來而土壤未被破壞，荒蕪地區可能再次長出植物。"},{"en":"The phrase describes land that looks empty or lifeless.","zh":"這個短語描述看起來空曠或沒有生命的土地。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":5},{"front":"soon recover after","meaning":"在……之後很快恢復","examples":[{"en":"Even barren land may soon recover after rain falls.","zh":"即使荒蕪土地也可能在降雨之後很快恢復。"},{"en":"To soon recover after something means to become healthy or active again shortly after it happens.","zh":"「soon recover after」某事，意思是在它發生後不久恢復健康或活動。"},{"en":"A tired student may soon recover after a good night’s sleep.","zh":"疲倦學生在一晚好睡眠後可能很快恢復。"},{"en":"If dry land still has seeds in the soil, it may recover after rain.","zh":"如果乾地土壤中仍有種子，它可能在雨後恢復。"},{"en":"The phrase describes quick improvement after a helpful event.","zh":"這個短語描述在有利事件後快速改善。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":5},{"front":"after the rain falls","meaning":"雨水降下之後","examples":[{"en":"Barren land may recover after the rain falls.","zh":"荒蕪土地可能在雨水降下之後恢復。"},{"en":"After the rain falls means after rain has come down onto the land.","zh":"「after the rain falls」意思是雨水落到土地之後。"},{"en":"Children may return to the playground after the rain falls and stops.","zh":"雨水降下並停下後，孩子可能回到操場。"},{"en":"If rain falls on dry soil, plants may begin to grow again.","zh":"如果雨水落在乾燥土壤上，植物可能重新生長。"},{"en":"The phrase gives a time point following rainfall.","zh":"這個短語提供降雨後的時間點。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":5},{"front":"in fact","meaning":"事實上","examples":[{"en":"In fact, human activities are often responsible for desertification.","zh":"事實上，人類活動往往是沙漠化的原因。"},{"en":"In fact introduces the true or more accurate point.","zh":"「in fact」引出真正或更準確的一點。"},{"en":"Many students think grammar is only rules; in fact, it helps meaning become clear.","zh":"許多學生以為文法只是規則；事實上，它幫助意思變清晰。"},{"en":"If a common belief is wrong, “in fact” can introduce the correction.","zh":"如果常見信念錯誤，in fact 可以引出更正。"},{"en":"The phrase often contrasts reality with misunderstanding.","zh":"這個短語常把現實與誤解作對比。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":6},{"front":"more often than not","meaning":"多數情況下","examples":[{"en":"More often than not, human activities are responsible for desertification.","zh":"多數情況下，人類活動是沙漠化的原因。"},{"en":"More often than not means usually or in most cases.","zh":"「more often than not」意思是通常或在大多數情況下。"},{"en":"More often than not, students improve when feedback is clear and regular.","zh":"多數情況下，當回饋清楚而定期，學生會進步。"},{"en":"If human actions are usually responsible, prevention must focus on land use.","zh":"如果人類行為通常負有責任，預防就必須集中於土地使用。"},{"en":"The phrase suggests a common pattern, not an absolute rule.","zh":"這個短語表示常見模式，而不是絕對規則。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":6},{"front":"human activities","meaning":"人類活動","examples":[{"en":"Human activities are often responsible for desertification.","zh":"人類活動往往是沙漠化的原因。"},{"en":"Human activities are things people do, such as farming, grazing, cutting trees, or building.","zh":"「human activities」是人們所做的事情，例如耕作、放牧、砍樹或建設。"},{"en":"Human activities in a city include transport, construction, shopping, and waste disposal.","zh":"城市中的人類活動包括交通、建築、購物和棄置垃圾。"},{"en":"If human activities damage soil and plants, land may become less productive.","zh":"如果人類活動破壞土壤和植物，土地可能變得較沒有生產力。"},{"en":"The phrase contrasts human causes with natural causes.","zh":"這個短語把人為原因與自然原因作對比。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":6},{"front":"be responsible for","meaning":"對……負有責任；是……的原因","examples":[{"en":"Human activities are responsible for many cases of desertification.","zh":"人類活動是許多沙漠化個案的原因。"},{"en":"To be responsible for something means to be the cause of it or have duty over it.","zh":"「be responsible for」某事，意思是造成它或對它負有責任。"},{"en":"Poor planning may be responsible for delays in a school trip.","zh":"規劃不善可能是學校旅行延誤的原因。"},{"en":"If overgrazing is responsible for soil loss, grazing methods must change.","zh":"如果過度放牧是土壤流失的原因，放牧方式就必須改變。"},{"en":"The phrase can mean cause or accountability.","zh":"這個短語可以表示成因或責任。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":6},{"front":"the explosion in world population","meaning":"世界人口急增","examples":[{"en":"The explosion in world population may be a primary cause of soil degradation.","zh":"世界人口急增可能是土壤退化的主要原因。"},{"en":"The explosion in world population means a very rapid increase in the number of people worldwide.","zh":"「the explosion in world population」意思是全球人口數量非常快速增加。"},{"en":"A city may struggle with housing if its population grows suddenly.","zh":"如果城市人口突然增長，住房可能變得緊張。"},{"en":"If population grows quickly, more land may be used for food and fuel.","zh":"如果人口快速增加，更多土地可能被用於糧食和燃料。"},{"en":"The phrase stresses sudden and large population growth.","zh":"這個短語強調突然且大量的人口增長。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":6},{"front":"developing countries","meaning":"發展中國家","examples":[{"en":"Population growth is especially rapid in some developing countries.","zh":"一些發展中國家的人口增長尤其快速。"},{"en":"Developing countries are countries with lower average income and less industrial development.","zh":"「developing countries」是平均收入較低、工業發展較少的國家。"},{"en":"Some developing countries face pressure to provide schools, jobs, and clean water quickly.","zh":"有些發展中國家面對快速提供學校、工作和清潔食水的壓力。"},{"en":"If population rises fast in developing countries, land and resources may be strained.","zh":"如果發展中國家人口快速上升，土地和資源可能受壓。"},{"en":"The phrase is broad and should be used carefully.","zh":"這個短語範圍很廣，應小心使用。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":6},{"front":"the primary cause of","meaning":"……的主要原因","examples":[{"en":"Population growth may be the primary cause of soil degradation.","zh":"人口增長可能是土壤退化的主要原因。"},{"en":"The primary cause of something is the main reason it happens.","zh":"「the primary cause of」某事，是它發生的主要原因。"},{"en":"Lack of sleep may be the primary cause of a student’s poor concentration.","zh":"睡眠不足可能是學生專注力差的主要原因。"},{"en":"If the primary cause is land pressure, solutions must reduce pressure on land.","zh":"如果主要原因是土地壓力，解決方法就必須減少土地壓力。"},{"en":"The phrase identifies the most important cause.","zh":"這個短語指出最重要的原因。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":6},{"front":"soil degradation","meaning":"土壤退化","examples":[{"en":"Soil degradation can lead to desertification.","zh":"土壤退化可以導致沙漠化。"},{"en":"Soil degradation is the decline in soil quality, fertility, or structure.","zh":"「soil degradation」是土壤質素、肥力或結構下降。"},{"en":"A farm may suffer soil degradation if nutrients are lost year after year.","zh":"如果養分年復年流失，農場可能出現土壤退化。"},{"en":"If soil becomes degraded, crops grow poorly and erosion becomes easier.","zh":"如果土壤退化，農作物會長得差，侵蝕也更容易發生。"},{"en":"The phrase describes damage to the land’s productive layer.","zh":"這個短語描述土地生產層受損。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":6},{"front":"population density","meaning":"人口密度","examples":[{"en":"Population density has increased in many dryland areas.","zh":"許多旱地地區的人口密度已上升。"},{"en":"Population density means the number of people living in a given area.","zh":"「population density」指某一面積內居住的人數。"},{"en":"A city has high population density when many people live in a small space.","zh":"當許多人住在小空間內，城市就有人口密度高的情況。"},{"en":"If population density increases in drylands, demand for food, fuel, and land rises.","zh":"如果旱地人口密度上升，對食物、燃料和土地的需求就增加。"},{"en":"The phrase measures how crowded a place is.","zh":"這個短語量度一個地方有多擠迫。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":6},{"front":"cultivation has expanded into","meaning":"耕作已擴展至……","examples":[{"en":"Cultivation has expanded into progressively drier areas.","zh":"耕作已擴展至逐漸更乾旱的地區。"},{"en":"Cultivation has expanded into an area means farming has spread there.","zh":"「cultivation has expanded into」某地，意思是耕作已蔓延到那裡。"},{"en":"Housing may expand into old farmland when a city grows.","zh":"當城市增長，住宅可能擴展至舊農地。"},{"en":"If farming expands into dry areas, crop failure and erosion may become more likely.","zh":"如果耕作擴展至乾旱地區，農作物失收和侵蝕可能更容易發生。"},{"en":"The phrase describes movement of farming into new land.","zh":"這個短語描述耕作進入新土地。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":6},{"front":"cultivation","meaning":"耕作；耕種","examples":[{"en":"Cultivation has expanded into drier regions.","zh":"耕作已擴展至較乾旱地區。"},{"en":"Cultivation means preparing and using land to grow crops.","zh":"「cultivation」意思是準備和使用土地來種植農作物。"},{"en":"Rice cultivation requires water, labour, and suitable soil.","zh":"稻米耕作需要水、勞力和合適土壤。"},{"en":"If cultivation removes natural vegetation, soil may become exposed.","zh":"如果耕作移除天然植被，土壤可能暴露。"},{"en":"The word is a formal term for farming crops.","zh":"這個詞是種植農作物的正式說法。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":6},{"front":"progressively drier areas","meaning":"逐漸更乾旱的地區","examples":[{"en":"Farmers have moved into progressively drier areas.","zh":"農民已進入逐漸更乾旱的地區。"},{"en":"Progressively drier areas are places that become drier step by step.","zh":"「progressively drier areas」是一步步變得更乾燥的地方。"},{"en":"A walking route may move from green hills into progressively drier areas.","zh":"步行路線可能從綠色山丘進入逐漸更乾旱的地區。"},{"en":"If farming moves into drier land, water stress and crop failure increase.","zh":"如果耕作進入更乾燥土地，水分壓力和農作物失收會增加。"},{"en":"The phrase shows gradual change toward dryness.","zh":"這個短語顯示逐漸變乾的變化。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":7},{"front":"be prone to","meaning":"容易受到……影響","examples":[{"en":"These regions are prone to periods of severe drought.","zh":"這些地區容易受到嚴重乾旱時期影響。"},{"en":"To be prone to something means to be likely to suffer from it.","zh":"「be prone to」某事，意思是容易受它影響或較可能經歷它。"},{"en":"A student who sleeps too little may be prone to headaches.","zh":"睡眠太少的學生可能容易頭痛。"},{"en":"If dry regions are prone to drought, farming there is risky.","zh":"如果乾旱地區容易發生旱災，在那裡耕作就有風險。"},{"en":"The phrase describes vulnerability, not certainty.","zh":"這個短語描述脆弱性，而不是必然。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":7},{"front":"periods of severe drought","meaning":"嚴重乾旱時期","examples":[{"en":"Dry regions are prone to periods of severe drought.","zh":"乾旱地區容易出現嚴重乾旱時期。"},{"en":"Periods of severe drought are times when there is very little rain for a long or damaging period.","zh":"「periods of severe drought」是長時間或造成破壞的極少降雨時期。"},{"en":"During periods of severe drought, families may save every bucket of water.","zh":"在嚴重乾旱時期，家庭可能節省每一桶水。"},{"en":"If severe drought lasts too long, crops fail and soil dries out.","zh":"如果嚴重乾旱持續太久，農作物會失收，土壤會乾裂。"},{"en":"The phrase describes extreme dry spells.","zh":"這個短語描述極端乾旱期。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":7},{"front":"crop failures","meaning":"農作物失收","examples":[{"en":"Crop failures are common in areas affected by drought.","zh":"在受乾旱影響的地區，農作物失收很常見。"},{"en":"Crop failures happen when crops do not grow well enough to be harvested.","zh":"「crop failures」是農作物長得不夠好而無法收成。"},{"en":"A farmer may face crop failure if rain stops during the growing season.","zh":"如果生長季節中雨水停止，農民可能面對農作物失收。"},{"en":"If crop failures happen repeatedly, families may lose income and food supply.","zh":"如果農作物反覆失收，家庭可能失去收入和食物供應。"},{"en":"The phrase describes agricultural loss.","zh":"這個短語描述農業損失。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":7},{"front":"be common","meaning":"很常見","examples":[{"en":"Crop failures are common in drought-prone regions.","zh":"農作物失收在易受乾旱影響的地區很常見。"},{"en":"To be common means to happen often or be found frequently.","zh":"「be common」意思是經常發生或常見。"},{"en":"Traffic delays are common near busy schools in the morning.","zh":"早上繁忙學校附近交通延誤很常見。"},{"en":"If crop failures are common, farmers may avoid risky crops.","zh":"如果農作物失收很常見，農民可能避免種植高風險作物。"},{"en":"The phrase describes frequency.","zh":"這個短語描述頻率。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":7},{"front":"growing most crops","meaning":"種植大部分農作物","examples":[{"en":"Growing most crops requires the natural vegetation cover to be removed.","zh":"種植大部分農作物需要移除天然植被覆蓋。"},{"en":"Growing most crops means cultivating many kinds of food or commercial plants.","zh":"「growing most crops」意思是栽培許多種類的糧食或商業植物。"},{"en":"Growing vegetables in a school garden may require clearing weeds first.","zh":"在學校花園種蔬菜可能需要先清除雜草。"},{"en":"If natural cover is removed for crops, soil protection may decrease.","zh":"如果為了種植作物而移除天然覆蓋，土壤保護可能下降。"},{"en":"The phrase focuses on the farming process before harvest.","zh":"這個短語集中於收成前的耕作過程。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":7},{"front":"natural vegetation cover","meaning":"天然植被覆蓋","examples":[{"en":"Natural vegetation cover is often removed before crops are grown.","zh":"種植農作物前，天然植被覆蓋常被移除。"},{"en":"Natural vegetation cover is the original plant layer growing on land without farming.","zh":"「natural vegetation cover」是土地上原本自然生長的植物層。"},{"en":"Bushes, grasses, and small trees can form natural vegetation cover.","zh":"灌木、草和小樹可以形成天然植被覆蓋。"},{"en":"If this cover is removed, soil becomes more exposed to erosion.","zh":"如果這種覆蓋被移除，土壤會更暴露於侵蝕之下。"},{"en":"The phrase describes the land’s original plant protection.","zh":"這個短語描述土地原本的植物保護層。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":7},{"front":"be removed first","meaning":"必須先被移除","examples":[{"en":"The natural vegetation cover must be removed first.","zh":"天然植被覆蓋必須先被移除。"},{"en":"To be removed first means to be taken away before another action happens.","zh":"「be removed first」意思是在另一行動發生前先被拿走。"},{"en":"Old paint may be removed first before a wall is repainted.","zh":"牆壁重新油漆前，舊油漆可能必須先被移除。"},{"en":"If vegetation is removed first, soil loses protection before crops even grow.","zh":"如果植被先被移除，土壤在作物長出前已失去保護。"},{"en":"The phrase shows the first step in a process.","zh":"這個短語顯示過程中的第一步。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":7},{"front":"when crop failures occur","meaning":"當農作物失收時","examples":[{"en":"When crop failures occur, the land may be left without plant cover.","zh":"當農作物失收時，土地可能沒有植被覆蓋。"},{"en":"When crop failures occur means when crops fail to grow or produce harvest.","zh":"「when crop failures occur」意思是當農作物不能生長或不能收成時。"},{"en":"When exam failures occur, teachers may review study methods with students.","zh":"當考試失敗發生時，老師可能與學生檢視學習方法。"},{"en":"If crop failures occur after vegetation has been removed, bare soil remains exposed.","zh":"如果植被已被移除後農作物失收，裸露土壤就會暴露。"},{"en":"The phrase introduces the condition that creates later problems.","zh":"這個短語引入造成後續問題的條件。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":7},{"front":"extensive tracts of land","meaning":"大片土地","examples":[{"en":"Extensive tracts of land may be devoid of plant cover.","zh":"大片土地可能缺乏植被覆蓋。"},{"en":"Extensive tracts of land are very large areas of land.","zh":"「extensive tracts of land」是非常大片土地。"},{"en":"A wildfire can damage extensive tracts of forest in a few days.","zh":"山火可以在幾天內破壞大片森林。"},{"en":"If extensive land loses plants, wind erosion can affect a wide region.","zh":"如果大片土地失去植物，風蝕可以影響廣闊地區。"},{"en":"The phrase stresses large scale.","zh":"這個短語強調規模很大。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":7},{"front":"be devoid of","meaning":"缺乏；沒有","examples":[{"en":"The land is devoid of plant cover after crop failures.","zh":"農作物失收後，土地沒有植被覆蓋。"},{"en":"To be devoid of something means to have none of it.","zh":"「be devoid of」某物，意思是完全沒有它。"},{"en":"A classroom devoid of chairs cannot be used for a normal lesson.","zh":"沒有椅子的課室不能用作正常課堂。"},{"en":"If land is devoid of plants, soil is exposed to wind and rain.","zh":"如果土地沒有植物，土壤就暴露於風雨之下。"},{"en":"The phrase is formal and means “without”.","zh":"這個短語較正式，意思是「沒有」。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":7},{"front":"plant cover","meaning":"植被覆蓋","examples":[{"en":"Plant cover protects the soil from erosion.","zh":"植被覆蓋保護土壤免受侵蝕。"},{"en":"Plant cover means plants that cover the ground and hold soil in place.","zh":"「plant cover」指覆蓋地面並固定土壤的植物。"},{"en":"Grass in a park acts as plant cover after heavy rain.","zh":"大雨後，公園草地發揮植被覆蓋作用。"},{"en":"If plant cover disappears, soil can be washed or blown away.","zh":"如果植被覆蓋消失，土壤可以被沖走或吹走。"},{"en":"The phrase describes a protective layer of vegetation.","zh":"這個短語描述植物形成的保護層。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":8},{"front":"be susceptible to","meaning":"容易受到……影響","examples":[{"en":"Land without plant cover is susceptible to wind and water erosion.","zh":"沒有植被覆蓋的土地容易受到風蝕和水蝕影響。"},{"en":"To be susceptible to something means to be easily affected or damaged by it.","zh":"「be susceptible to」某事，意思是容易被它影響或破壞。"},{"en":"A tired student may be susceptible to colds during exam season.","zh":"疲倦學生在考試季可能容易感冒。"},{"en":"If soil is exposed, it becomes susceptible to erosion.","zh":"如果土壤裸露，它就容易受到侵蝕。"},{"en":"The phrase describes vulnerability.","zh":"這個短語描述脆弱性。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":8},{"front":"wind and water erosion","meaning":"風蝕和水蝕","examples":[{"en":"Exposed land is susceptible to wind and water erosion.","zh":"裸露土地容易受到風蝕和水蝕。"},{"en":"Wind and water erosion means soil being removed by wind or flowing water.","zh":"「wind and water erosion」指土壤被風或流水移走。"},{"en":"A hillside without plants may suffer water erosion after heavy rain.","zh":"沒有植物的山坡在大雨後可能受水蝕。"},{"en":"If dry soil is loose, wind erosion can carry it away as dust.","zh":"如果乾土鬆散，風蝕可以把它以塵土形式帶走。"},{"en":"The phrase names two major ways soil is lost.","zh":"這個短語指出土壤流失的兩大方式。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":8},{"front":"throughout the 1990s","meaning":"整個九十年代期間","examples":[{"en":"Throughout the 1990s, dryland areas experienced population growth.","zh":"整個九十年代期間，旱地地區經歷人口增長。"},{"en":"Throughout the 1990s means during the whole period from 1990 to 1999.","zh":"「throughout the 1990s」意思是在1990至1999整個期間。"},{"en":"Throughout the school year, students practised writing every week.","zh":"整個學年期間，學生每星期練習寫作。"},{"en":"If population grew throughout a decade, pressure on land continued for years.","zh":"如果人口在整個十年間增長，土地壓力會持續多年。"},{"en":"The phrase describes a whole time period.","zh":"這個短語描述整段時期。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":8},{"front":"dryland areas","meaning":"旱地地區","examples":[{"en":"Dryland areas went through rapid population growth.","zh":"旱地地區經歷了快速人口增長。"},{"en":"Dryland areas are regions where water is limited and rainfall is low or unreliable.","zh":"「dryland areas」是水分有限、降雨少或不可靠的地區。"},{"en":"People in dryland areas may depend on wells, grazing, or drought-resistant crops.","zh":"旱地地區的人可能依靠井水、放牧或抗旱作物。"},{"en":"If dryland areas are overused, soil can degrade quickly.","zh":"如果旱地地區被過度使用，土壤可以快速退化。"},{"en":"The phrase describes land with limited moisture.","zh":"這個短語描述水分有限的土地。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":8},{"front":"go through population growth","meaning":"經歷人口增長","examples":[{"en":"Dryland areas went through a population growth of 18.5 per cent.","zh":"旱地地區經歷了18.5%的人口增長。"},{"en":"To go through population growth means to experience an increase in the number of residents.","zh":"「go through population growth」意思是經歷居民人數增加。"},{"en":"A town may go through population growth when new jobs are created nearby.","zh":"當附近創造新工作，城鎮可能經歷人口增長。"},{"en":"If drylands go through rapid population growth, land demand increases.","zh":"如果旱地經歷快速人口增長，土地需求會增加。"},{"en":"The phrase describes demographic change.","zh":"這個短語描述人口變化。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":8},{"front":"severely impoverished","meaning":"極度貧困的","examples":[{"en":"Many dryland areas are in severely impoverished developing countries.","zh":"許多旱地地區位於極度貧困的發展中國家。"},{"en":"Severely impoverished means extremely poor and lacking basic resources.","zh":"「severely impoverished」意思是極度貧窮並缺乏基本資源。"},{"en":"A severely impoverished community may lack clean water, schools, and healthcare.","zh":"極度貧困的社區可能缺乏清潔食水、學校和醫療。"},{"en":"If people are severely impoverished, they may depend heavily on local land for survival.","zh":"如果人們極度貧困，他們可能高度依賴本地土地維生。"},{"en":"The phrase describes deep poverty.","zh":"這個短語描述深度貧窮。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":8},{"front":"impoverished developing countries","meaning":"貧困的發展中國家","examples":[{"en":"Population growth mainly occurred in impoverished developing countries.","zh":"人口增長主要發生在貧困的發展中國家。"},{"en":"Impoverished developing countries are poorer nations with limited resources and development.","zh":"「impoverished developing countries」是資源和發展有限的較貧窮國家。"},{"en":"Schools in impoverished developing countries may lack books and trained teachers.","zh":"貧困發展中國家的學校可能缺乏書本和受訓老師。"},{"en":"If dryland populations grow in poor countries, land pressure can become severe.","zh":"如果貧困國家的旱地人口增長，土地壓力可能變得嚴重。"},{"en":"The phrase links poverty with national development level.","zh":"這個短語把貧窮與國家發展水平連繫起來。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":8},{"front":"raising livestock","meaning":"飼養牲畜","examples":[{"en":"Raising livestock in semi-arid areas accelerates soil erosion.","zh":"在半乾旱地區飼養牲畜會加速土壤侵蝕。"},{"en":"Raising livestock means keeping animals such as cattle, goats, or sheep for food or income.","zh":"「raising livestock」意思是飼養牛、山羊或羊等動物作食物或收入來源。"},{"en":"A family may raise livestock to sell milk, meat, or wool.","zh":"家庭可能飼養牲畜來出售牛奶、肉類或羊毛。"},{"en":"If too many animals graze on dry land, vegetation may disappear.","zh":"如果太多動物在乾地放牧，植被可能消失。"},{"en":"The phrase describes animal farming.","zh":"這個短語描述畜牧業。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":8},{"front":"accelerate soil erosion","meaning":"加速土壤侵蝕","examples":[{"en":"Raising livestock can accelerate soil erosion.","zh":"飼養牲畜可以加速土壤侵蝕。"},{"en":"To accelerate soil erosion means to make soil loss happen faster.","zh":"「accelerate soil erosion」意思是令土壤流失更快發生。"},{"en":"Heavy foot traffic can accelerate soil erosion on a hiking path.","zh":"大量人流可以加速遠足徑上的土壤侵蝕。"},{"en":"If animals overgraze land, exposed soil is removed more quickly by wind and rain.","zh":"如果動物過度放牧，裸露土壤會更快被風雨移走。"},{"en":"The phrase describes speeding up land damage.","zh":"這個短語描述加快土地破壞。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":8},{"front":"soil erosion","meaning":"土壤侵蝕","examples":[{"en":"Soil erosion is one cause of advancing desertification.","zh":"土壤侵蝕是不斷擴大的沙漠化的原因之一。"},{"en":"Soil erosion is the removal of soil by wind, water, animals, or human activity.","zh":"「soil erosion」是土壤被風、水、動物或人類活動移走。"},{"en":"A garden on a slope may suffer soil erosion after heavy rain.","zh":"斜坡上的花園在大雨後可能出現土壤侵蝕。"},{"en":"If topsoil is eroded, crops have fewer nutrients to grow.","zh":"如果表土被侵蝕，農作物就有較少養分生長。"},{"en":"The phrase describes the loss of the soil surface.","zh":"這個短語描述土壤表面的流失。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":8},{"front":"advancing desertification","meaning":"不斷擴大的沙漠化","examples":[{"en":"Overgrazing is one cause of advancing desertification.","zh":"過度放牧是不斷擴大的沙漠化的原因之一。"},{"en":"Advancing desertification is desertification that is spreading or becoming worse.","zh":"「advancing desertification」是正在擴展或惡化的沙漠化。"},{"en":"A village near a desert may fear advancing desertification if fields become sandy.","zh":"如果田地變得多沙，沙漠附近村莊可能害怕沙漠化不斷擴大。"},{"en":"If land loses vegetation year after year, desertification can advance.","zh":"如果土地年復年失去植被，沙漠化可以推進。"},{"en":"The phrase describes a worsening process.","zh":"這個短語描述惡化中的過程。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":9},{"front":"be dominated by grasses","meaning":"以草類為主","examples":[{"en":"In some semi-arid areas, the vegetation is dominated by grasses.","zh":"在一些半乾旱地區，植被以草類為主。"},{"en":"To be dominated by grasses means grasses are the main plants in the area.","zh":"「be dominated by grasses」意思是草類是該地區的主要植物。"},{"en":"A school field is dominated by grass if few trees or flowers grow there.","zh":"如果學校操場少有樹木或花朵生長，它就是以草類為主。"},{"en":"If grasses dominate dryland vegetation, removing them exposes the soil.","zh":"如果草類主導旱地植被，移除它們會令土壤暴露。"},{"en":"The phrase describes the main plant type in a landscape.","zh":"這個短語描述景觀中的主要植物類型。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":9},{"front":"livestock grazing","meaning":"牲畜放牧","examples":[{"en":"Livestock grazing is a major economic activity in semi-arid areas.","zh":"牲畜放牧是半乾旱地區的主要經濟活動。"},{"en":"Livestock grazing means animals feeding on grass or plants in open land.","zh":"「livestock grazing」指動物在開闊土地上吃草或植物。"},{"en":"Goats and sheep may be used for livestock grazing in dry villages.","zh":"在乾旱村莊中，山羊和綿羊可能用於牲畜放牧。"},{"en":"If grazing is too heavy, grasses cannot recover and soil becomes exposed.","zh":"如果放牧過度，草類無法恢復，土壤會暴露。"},{"en":"The phrase describes feeding animals on natural pasture.","zh":"這個短語描述牲畜在天然牧草地上進食。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":9},{"front":"a major economic activity","meaning":"主要經濟活動","examples":[{"en":"Livestock grazing is a major economic activity in many dry regions.","zh":"牲畜放牧是許多乾旱地區的主要經濟活動。"},{"en":"A major economic activity is an important way people earn money in an area.","zh":"「a major economic activity」是某地人們賺取收入的重要方式。"},{"en":"Tourism is a major economic activity in some coastal towns.","zh":"旅遊業是一些沿海城鎮的主要經濟活動。"},{"en":"If grazing is a major economic activity, limiting it may affect many families.","zh":"如果放牧是主要經濟活動，限制它可能影響許多家庭。"},{"en":"The phrase describes work that supports local income.","zh":"這個短語描述支持本地收入的工作。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":9},{"front":"anchoring vulnerable topsoil","meaning":"固定脆弱的表土","examples":[{"en":"Grasses are necessary for anchoring vulnerable topsoil.","zh":"草類對固定脆弱的表土是必要的。"},{"en":"Anchoring vulnerable topsoil means holding fragile surface soil in place.","zh":"「anchoring vulnerable topsoil」意思是把脆弱的表層土壤固定在原位。"},{"en":"Tree roots can anchor soil along a riverbank after heavy rain.","zh":"大雨後，樹根可以固定河岸泥土。"},{"en":"If roots no longer anchor topsoil, wind and water can remove it easily.","zh":"如果根部不再固定表土，風和水就可以輕易移走它。"},{"en":"The phrase explains how plants protect soil.","zh":"這個短語解釋植物如何保護土壤。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":9},{"front":"vulnerable topsoil","meaning":"脆弱的表土","examples":[{"en":"Grasses help protect vulnerable topsoil.","zh":"草類幫助保護脆弱的表土。"},{"en":"Vulnerable topsoil is fragile surface soil that can be easily damaged or removed.","zh":"「vulnerable topsoil」是容易受損或被移走的脆弱表層土壤。"},{"en":"Garden beds without mulch may have vulnerable topsoil after dry weather.","zh":"乾燥天氣後，沒有覆蓋物的花圃可能有脆弱表土。"},{"en":"If vulnerable topsoil is exposed, erosion can happen quickly.","zh":"如果脆弱表土暴露，侵蝕可以很快發生。"},{"en":"The phrase describes the most easily damaged soil layer.","zh":"這個短語描述最容易受損的土壤層。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":9},{"front":"a dryland area","meaning":"旱地地區","examples":[{"en":"Topsoil is especially vulnerable in a dryland area.","zh":"在旱地地區，表土尤其脆弱。"},{"en":"A dryland area is a region where water is scarce and rainfall is limited.","zh":"「a dryland area」是水分稀少、降雨有限的地區。"},{"en":"A farm in a dryland area may grow drought-resistant crops.","zh":"旱地地區的農場可能種植抗旱作物。"},{"en":"If a dryland area loses vegetation, soil erosion becomes more likely.","zh":"如果旱地地區失去植被，土壤侵蝕更可能發生。"},{"en":"The phrase describes a water-limited landscape.","zh":"這個短語描述水分有限的景觀。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":9},{"front":"graze an excessively large herd","meaning":"放牧過大的畜群","examples":[{"en":"A field may be damaged when it is used to graze an excessively large herd.","zh":"當一塊田地被用來放牧過大的畜群時，它可能受損。"},{"en":"To graze an excessively large herd means to let too many animals feed on one area.","zh":"「graze an excessively large herd」意思是讓太多動物在同一區域進食。"},{"en":"A small pasture cannot support an excessively large herd of goats for long.","zh":"小牧場不能長期承受過大的山羊群。"},{"en":"If too many animals graze, plants are eaten faster than they can regrow.","zh":"如果太多動物放牧，植物被吃掉的速度會快過再生速度。"},{"en":"The phrase describes overuse of land by livestock.","zh":"這個短語描述牲畜對土地的過度使用。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":9},{"front":"an excessively large herd","meaning":"過大的畜群","examples":[{"en":"An excessively large herd can destroy vegetation cover.","zh":"過大的畜群可以破壞植被覆蓋。"},{"en":"An excessively large herd is a group of animals too big for the land to support.","zh":"「an excessively large herd」是大到土地無法承受的動物群。"},{"en":"A village pasture may suffer if an excessively large herd feeds there every day.","zh":"如果過大的畜群每天在村莊牧草地進食，牧地可能受損。"},{"en":"If the herd is too large, plants cannot recover and soil is exposed.","zh":"如果畜群太大，植物無法恢復，土壤會暴露。"},{"en":"The phrase stresses that the number of animals is beyond a safe limit.","zh":"這個短語強調動物數量超出安全限度。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":9},{"front":"lose vegetation cover","meaning":"失去植被覆蓋","examples":[{"en":"The field will lose vegetation cover after overgrazing.","zh":"過度放牧後，田地會失去植被覆蓋。"},{"en":"To lose vegetation cover means to lose the plants that protect the ground.","zh":"「lose vegetation cover」意思是失去保護地面的植物。"},{"en":"A park may lose vegetation cover if people keep walking over the same grass.","zh":"如果人們不斷踩同一片草地，公園可能失去植被覆蓋。"},{"en":"If land loses plant cover, erosion and dust storms become more likely.","zh":"如果土地失去植被覆蓋，侵蝕和沙塵暴更可能發生。"},{"en":"The phrase describes the removal of protective plants.","zh":"這個短語描述保護性植物被移除。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":9},{"front":"be trampled and pulverised","meaning":"被踐踏並壓碎","examples":[{"en":"The soil will be trampled and pulverised by livestock.","zh":"土壤會被牲畜踐踏並壓碎。"},{"en":"To be trampled and pulverised means to be stepped on and broken into fine pieces.","zh":"「be trampled and pulverised」意思是被踩踏並碎成細小顆粒。"},{"en":"Grass near a busy school gate may be trampled and turned into mud.","zh":"繁忙校門附近的草地可能被踩踏並變成泥。"},{"en":"If livestock repeatedly step on dry soil, it can break apart and become dust.","zh":"如果牲畜反覆踩踏乾土，它可能碎裂並變成塵土。"},{"en":"The phrase describes physical damage from pressure and movement.","zh":"這個短語描述壓力和移動造成的物理損害。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":9},{"front":"leave the topsoil exposed to","meaning":"令表土暴露於……之下","examples":[{"en":"Overgrazing leaves the topsoil exposed to destructive forces.","zh":"過度放牧令表土暴露於破壞力量之下。"},{"en":"To leave the topsoil exposed to something means to remove protection so surface soil faces danger.","zh":"「leave the topsoil exposed to」某事，意思是移除保護，使表層土壤面對危險。"},{"en":"Removing roof tiles leaves a house exposed to rain.","zh":"移除屋瓦會令房屋暴露於雨水之下。"},{"en":"If plant cover disappears, topsoil is exposed to wind and sudden storms.","zh":"如果植被覆蓋消失，表土會暴露於風和突如其來的風暴之下。"},{"en":"The phrase shows how protection is lost.","zh":"這個短語顯示保護如何失去。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":10},{"front":"destructive forces","meaning":"破壞力量","examples":[{"en":"Wind and sudden thunderstorms are destructive forces.","zh":"風和突如其來的雷暴都是破壞力量。"},{"en":"Destructive forces are powers that can damage or break something down.","zh":"「destructive forces」是可以損害或摧毀某物的力量。"},{"en":"Floodwater can be a destructive force when it washes away roads.","zh":"當洪水沖走道路時，它可以是一種破壞力量。"},{"en":"If soil is exposed to destructive forces, erosion can happen quickly.","zh":"如果土壤暴露於破壞力量之下，侵蝕可以很快發生。"},{"en":"The phrase describes powerful causes of damage.","zh":"這個短語描述造成損害的強大因素。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":10},{"front":"sudden thunderstorms","meaning":"突如其來的雷暴","examples":[{"en":"Exposed topsoil is vulnerable to sudden thunderstorms.","zh":"暴露的表土容易受到突如其來的雷暴影響。"},{"en":"Sudden thunderstorms are storms that arrive quickly with heavy rain, wind, or lightning.","zh":"「sudden thunderstorms」是迅速出現並伴隨大雨、強風或閃電的風暴。"},{"en":"A picnic may be cancelled when sudden thunderstorms appear in the afternoon.","zh":"下午突如其來的雷暴出現時，野餐可能取消。"},{"en":"If topsoil is bare, sudden heavy rain can wash it away.","zh":"如果表土裸露，突如其來的大雨可以把它沖走。"},{"en":"The phrase describes fast and powerful storm events.","zh":"這個短語描述快速而強烈的風暴事件。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":10},{"front":"for centuries","meaning":"幾個世紀以來","examples":[{"en":"For centuries, nomads have moved their flocks and herds.","zh":"幾個世紀以來，遊牧民族一直遷移羊群和畜群。"},{"en":"For centuries means for hundreds of years.","zh":"「for centuries」意思是幾百年以來。"},{"en":"For centuries, people have used rivers for transport and farming.","zh":"幾個世紀以來，人們一直使用河流作交通和耕作。"},{"en":"If a practice continues for centuries, it is deeply rooted in local life.","zh":"如果一種做法持續幾個世紀，它就深深植根於本地生活。"},{"en":"The phrase describes a very long historical period.","zh":"這個短語描述非常長的歷史時期。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":10},{"front":"nomads","meaning":"遊牧民族","examples":[{"en":"Nomads move their flocks and herds in search of pasture.","zh":"遊牧民族遷移羊群和畜群以尋找牧草地。"},{"en":"Nomads are people who move from place to place rather than living permanently in one location.","zh":"「nomads」是不永久住在一地，而是從一地遷往另一地的人。"},{"en":"Some nomads travel with animals to find water and grass.","zh":"有些遊牧民族帶着動物旅行以尋找水和草。"},{"en":"If pasture becomes scarce, nomads may move to another area.","zh":"如果牧草地變少，遊牧民族可能遷往另一地區。"},{"en":"The phrase describes a mobile way of life.","zh":"這個短語描述流動的生活方式。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":10},{"front":"move their flocks and herds","meaning":"遷移羊群和畜群","examples":[{"en":"Nomads move their flocks and herds wherever pasture can be found.","zh":"遊牧民族哪裏有牧草地便把羊群和畜群遷往哪裏。"},{"en":"To move their flocks and herds means to lead groups of sheep, goats, or cattle to another place.","zh":"「move their flocks and herds」意思是帶領羊、山羊或牛群到另一地方。"},{"en":"A farmer may move animals to a new field when the old field has little grass.","zh":"當舊田地草很少時，農民可能把動物遷到新田地。"},{"en":"If animals are moved regularly, one area has time to recover.","zh":"如果動物定期遷移，一個區域就有時間恢復。"},{"en":"The phrase describes traditional animal management.","zh":"這個短語描述傳統牲畜管理方式。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":10},{"front":"pasture","meaning":"牧草地","examples":[{"en":"Nomads move wherever pasture can be found.","zh":"遊牧民族哪裏有牧草地便遷往哪裏。"},{"en":"Pasture is land covered with grass or plants for animals to eat.","zh":"「pasture」是覆蓋着供動物食用的草或植物的土地。"},{"en":"Cows may be moved to fresh pasture after one field is grazed.","zh":"當一塊田被吃光後，牛可能被移到新鮮牧草地。"},{"en":"If pasture disappears, livestock may overgraze the remaining land.","zh":"如果牧草地消失，牲畜可能過度啃食剩餘土地。"},{"en":"The phrase refers to grazing land.","zh":"這個短語指放牧用地。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":10},{"front":"wherever pasture can be found","meaning":"哪裏有牧草地便去哪裏","examples":[{"en":"Nomads move their herds wherever pasture can be found.","zh":"遊牧民族哪裏有牧草地便把畜群遷去哪裏。"},{"en":"Wherever pasture can be found means to any place where grazing land is available.","zh":"「wherever pasture can be found」意思是到任何有牧草地的地方。"},{"en":"Travellers may stop wherever water can be found during a long hike.","zh":"長途遠足時，旅客可能哪裏有水便在哪裏停下。"},{"en":"If pasture is scarce, nomads must travel farther to feed their animals.","zh":"如果牧草地稀少，遊牧民族必須走更遠來餵養動物。"},{"en":"The phrase shows movement based on resource availability.","zh":"這個短語顯示根據資源位置而移動。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":10},{"front":"oases","meaning":"綠洲","examples":[{"en":"Oases have offered opportunities for a more settled way of living.","zh":"綠洲為較定居的生活方式提供了機會。"},{"en":"Oases are places in deserts where water allows plants and people to survive.","zh":"「oases」是沙漠中有水、能讓植物和人類生存的地方。"},{"en":"A small community may grow around an oasis because water is available there.","zh":"因為有水，小社區可能在綠洲周圍形成。"},{"en":"If an oasis supports farming, nomads may settle nearby for longer periods.","zh":"如果綠洲支持耕作，遊牧民族可能在附近停留更久。"},{"en":"The word describes rare life-supporting places in dry regions.","zh":"這個詞描述乾旱地區中罕見的生命支撐地點。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":10},{"front":"offer opportunities for","meaning":"為……提供機會","examples":[{"en":"Oases offer opportunities for a more settled way of living.","zh":"綠洲為較定居的生活方式提供機會。"},{"en":"To offer opportunities for something means to make it possible or easier.","zh":"「offer opportunities for」某事，意思是使它成為可能或更容易。"},{"en":"A scholarship can offer opportunities for students from poor families.","zh":"獎學金可以為貧困家庭學生提供機會。"},{"en":"If water is available, it offers opportunities for farming and settlement.","zh":"如果有水，就為耕作和定居提供機會。"},{"en":"The phrase describes opening a possible path.","zh":"這個短語描述打開可能路徑。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":10},{"front":"a more settled way of living","meaning":"較定居的生活方式","examples":[{"en":"Oases make a more settled way of living possible.","zh":"綠洲使較定居的生活方式成為可能。"},{"en":"A more settled way of living means living more permanently in one place.","zh":"「a more settled way of living」意思是更長期固定居住在一個地方。"},{"en":"A family may choose a more settled way of living when children start school.","zh":"當孩子開始上學，家庭可能選擇較定居的生活方式。"},{"en":"If water and food are reliable, people can stay instead of moving constantly.","zh":"如果水和食物可靠，人們可以留下，而不用不斷遷移。"},{"en":"The phrase contrasts settled life with nomadic life.","zh":"這個短語把定居生活與遊牧生活作對比。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":10},{"front":"wherever they move to","meaning":"無論他們遷往哪裏","examples":[{"en":"For some nomads, wherever they move to, the desert follows.","zh":"對一些遊牧民族來說，無論他們遷往哪裏，沙漠也隨之而來。"},{"en":"Wherever they move to means no matter which place they go to.","zh":"「wherever they move to」意思是無論他們去到哪個地方。"},{"en":"Wherever a student moves to, good study habits can still help.","zh":"無論學生搬去哪裏，良好學習習慣仍然有幫助。"},{"en":"If nomads overuse each new area, land damage may follow them.","zh":"如果遊牧民族過度使用每個新地區，土地破壞可能跟隨他們。"},{"en":"The phrase shows repeated movement across different places.","zh":"這個短語顯示跨不同地方的重複移動。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":11},{"front":"the desert follows","meaning":"沙漠也隨之而來","examples":[{"en":"For some nomads, the desert follows wherever they move.","zh":"對一些遊牧民族來說，無論他們遷往哪裏，沙漠也隨之而來。"},{"en":"The desert follows means desert-like conditions spread to places people move into.","zh":"「the desert follows」意思是沙漠般的情況蔓延到人們遷入的地方。"},{"en":"If a family leaves debt but keeps the same spending habits, the problem follows them.","zh":"如果家庭離開債務但保留同樣花錢習慣，問題也會跟着他們。"},{"en":"If land is repeatedly overused, degradation may appear in each new place.","zh":"如果土地被反覆過度使用，退化可能在每個新地方出現。"},{"en":"The phrase is figurative and suggests the problem travels with people.","zh":"這個短語是比喻，暗示問題跟隨人們移動。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":11},{"front":"be of great importance","meaning":"非常重要","examples":[{"en":"Trees are of great importance for maintaining topsoil.","zh":"樹木對保持表土非常重要。"},{"en":"To be of great importance means to be very important.","zh":"「be of great importance」意思是非常重要。"},{"en":"Clean water is of great importance for public health.","zh":"清潔食水對公共健康非常重要。"},{"en":"If trees are important for topsoil, removing them can increase erosion.","zh":"如果樹木對表土重要，移除它們會增加侵蝕。"},{"en":"The phrase is a formal way to stress importance.","zh":"這個短語是強調重要性的正式說法。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":11},{"front":"when it comes to","meaning":"當談到……時","examples":[{"en":"Trees are important when it comes to maintaining topsoil.","zh":"當談到保持表土時，樹木很重要。"},{"en":"When it comes to something means when discussing or dealing with that matter.","zh":"「when it comes to」某事，意思是當討論或處理該事情時。"},{"en":"When it comes to exams, regular practice matters more than last-minute panic.","zh":"當談到考試時，定期練習比臨急抱佛腳更重要。"},{"en":"When it comes to soil protection, roots and plant cover are essential.","zh":"當談到土壤保護時，根部和植被覆蓋很重要。"},{"en":"The phrase introduces the topic being considered.","zh":"這個短語引出正在考慮的主題。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":11},{"front":"maintaining topsoil","meaning":"保持表土","examples":[{"en":"Trees are important for maintaining topsoil.","zh":"樹木對保持表土很重要。"},{"en":"Maintaining topsoil means keeping the fertile surface layer of soil in place and healthy.","zh":"「maintaining topsoil」意思是保持肥沃的表層土壤不流失並維持健康。"},{"en":"Farmers maintain topsoil by planting cover crops after harvest.","zh":"農民在收成後種植覆蓋作物來保持表土。"},{"en":"If topsoil is maintained, land can remain productive for longer.","zh":"如果表土得到保持，土地可以更長時間保持生產力。"},{"en":"The phrase describes protecting the most useful soil layer.","zh":"這個短語描述保護最有用的土壤層。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":11},{"front":"reducing wind speed","meaning":"降低風速","examples":[{"en":"Trees help reduce wind speed in dryland areas.","zh":"樹木有助降低旱地地區的風速。"},{"en":"Reducing wind speed means making the wind move more slowly.","zh":"「reducing wind speed」意思是令風移動得較慢。"},{"en":"A row of trees can reduce wind speed around a playground.","zh":"一排樹可以降低遊樂場周圍的風速。"},{"en":"If wind speed is reduced, fewer soil particles are blown away.","zh":"如果風速降低，較少土壤微粒會被吹走。"},{"en":"The phrase describes one way trees protect land.","zh":"這個短語描述樹木保護土地的一種方式。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":11},{"front":"firewood","meaning":"柴枝；薪柴","examples":[{"en":"Firewood is the chief fuel used for cooking and heating in many areas.","zh":"在許多地區，柴枝是用於煮食和取暖的主要燃料。"},{"en":"Firewood is wood used as fuel for fire.","zh":"「firewood」是用作燃料燃燒的木材。"},{"en":"Rural families may collect firewood when electricity or gas is expensive.","zh":"當電力或煤氣昂貴時，鄉村家庭可能收集柴枝。"},{"en":"If too much firewood is cut, forests can shrink quickly.","zh":"如果砍伐太多薪柴，森林可以迅速縮小。"},{"en":"The word refers to wood burned for energy.","zh":"這個詞指燃燒產能的木材。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":11},{"front":"the chief fuel","meaning":"主要燃料","examples":[{"en":"Firewood is the chief fuel used for cooking and heating.","zh":"柴枝是用於煮食和取暖的主要燃料。"},{"en":"The chief fuel means the main source of energy used for a purpose.","zh":"「the chief fuel」指用於某目的的主要能源來源。"},{"en":"Electricity is the chief fuel for many household appliances.","zh":"電力是許多家用電器的主要能源。"},{"en":"If firewood is the chief fuel, demand for trees can become high.","zh":"如果柴枝是主要燃料，對樹木的需求可能變高。"},{"en":"The phrase identifies the most important fuel source.","zh":"這個短語指出最重要的燃料來源。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":11},{"front":"cooking and heating","meaning":"煮食和取暖","examples":[{"en":"Firewood is used for cooking and heating.","zh":"柴枝用於煮食和取暖。"},{"en":"Cooking and heating means preparing food and keeping people or homes warm.","zh":"「cooking and heating」意思是準備食物和讓人或家居保持溫暖。"},{"en":"Families may need gas or electricity for cooking and heating in winter.","zh":"家庭在冬天可能需要煤氣或電力煮食和取暖。"},{"en":"If communities rely on wood for cooking and heating, forests may be under pressure.","zh":"如果社區依賴木材煮食和取暖，森林可能承受壓力。"},{"en":"The phrase describes two basic household energy needs.","zh":"這個短語描述兩種基本家庭能源需要。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":11},{"front":"uncontrolled clear-cutting of forests","meaning":"無節制地砍伐森林","examples":[{"en":"The use of firewood has caused uncontrolled clear-cutting of forests.","zh":"使用柴枝已造成無節制地砍伐森林。"},{"en":"Uncontrolled clear-cutting of forests means cutting down whole forest areas without proper limits.","zh":"「uncontrolled clear-cutting of forests」意思是在沒有適當限制下砍掉整片森林。"},{"en":"A village may lose nearby woodland if tree cutting is uncontrolled.","zh":"如果砍樹不受控制，村莊可能失去附近林地。"},{"en":"If forests are clear-cut, wind speed rises and soil protection decreases.","zh":"如果森林被清除，風速會上升，土壤保護會減少。"},{"en":"The phrase describes severe and poorly managed deforestation.","zh":"這個短語描述嚴重且管理不善的砍伐森林。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":11},{"front":"clear-cutting of forests","meaning":"砍伐森林","examples":[{"en":"Clear-cutting of forests damages dryland ecosystems.","zh":"砍伐森林會破壞旱地生態系統。"},{"en":"Clear-cutting of forests means removing all or most trees from a forest area.","zh":"「clear-cutting of forests」意思是移除森林區域中全部或大部分樹木。"},{"en":"Clear-cutting may make timber collection quick but leaves land exposed.","zh":"砍伐森林可能令木材收集變快，但會令土地暴露。"},{"en":"If forests are clear-cut in drylands, soil erosion may increase sharply.","zh":"如果旱地森林被砍清，土壤侵蝕可能急劇增加。"},{"en":"The phrase describes large-scale tree removal.","zh":"這個短語描述大規模移除樹木。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":11},{"front":"dryland ecosystems","meaning":"旱地生態系統","examples":[{"en":"Forests in dryland ecosystems are vulnerable to damage.","zh":"旱地生態系統中的森林容易受損。"},{"en":"Dryland ecosystems are communities of plants, animals, soil, and climate in dry regions.","zh":"「dryland ecosystems」是乾旱地區中植物、動物、土壤和氣候組成的群落。"},{"en":"A dryland ecosystem may include grasses, shrubs, insects, and grazing animals.","zh":"旱地生態系統可能包括草、灌木、昆蟲和放牧動物。"},{"en":"If trees are removed, the balance of a dryland ecosystem can collapse.","zh":"如果樹木被移除，旱地生態系統的平衡可能崩潰。"},{"en":"The phrase describes living systems in water-limited places.","zh":"這個短語描述水分有限地方的生命系統。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":12},{"front":"cut down","meaning":"砍伐","examples":[{"en":"When too many trees are cut down, dust storms tend to occur.","zh":"當太多樹木被砍伐，沙塵暴往往會發生。"},{"en":"To cut down trees means to chop or fell them.","zh":"「cut down」樹木，意思是砍倒它們。"},{"en":"Workers may cut down a dead tree if it is unsafe near a road.","zh":"如果路邊死樹不安全，工人可能把它砍伐。"},{"en":"If too many trees are cut down, roots no longer hold the soil.","zh":"如果太多樹木被砍伐，樹根就不再固定土壤。"},{"en":"The phrase describes tree removal.","zh":"這個短語描述移除樹木。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":12},{"front":"tend to occur","meaning":"往往會發生","examples":[{"en":"Windstorms and dust storms tend to occur when trees are removed.","zh":"當樹木被移除，風暴和沙塵暴往往會發生。"},{"en":"Tend to occur means usually happen under certain conditions.","zh":"「tend to occur」意思是在某些條件下通常會發生。"},{"en":"Traffic delays tend to occur when it rains during rush hour.","zh":"在繁忙時間下雨時，交通延誤往往會發生。"},{"en":"If trees are removed, wind can move more freely and storms may become common.","zh":"如果樹木被移除，風可以更自由移動，風暴可能變得常見。"},{"en":"The phrase describes a likely pattern.","zh":"這個短語描述可能出現的模式。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":12},{"front":"windstorms and dust storms","meaning":"風暴和沙塵暴","examples":[{"en":"Windstorms and dust storms may occur after forests are cleared.","zh":"森林被清除後，風暴和沙塵暴可能發生。"},{"en":"Windstorms and dust storms are severe wind events, sometimes carrying large amounts of dust.","zh":"「windstorms and dust storms」是嚴重強風事件，有時帶着大量塵土。"},{"en":"A desert town may close roads during windstorms and dust storms.","zh":"沙漠城鎮可能在風暴和沙塵暴期間封路。"},{"en":"If forests are removed, wind loses a natural barrier and storms may worsen.","zh":"如果森林被移除，風失去天然屏障，風暴可能惡化。"},{"en":"The phrase describes damaging weather linked to exposed land.","zh":"這個短語描述與裸露土地相關的破壞性天氣。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":12},{"front":"political conflicts and wars","meaning":"政治衝突和戰爭","examples":[{"en":"Political conflicts and wars can contribute to desertification.","zh":"政治衝突和戰爭可以促成沙漠化。"},{"en":"Political conflicts and wars are struggles over power that may involve violence and displacement.","zh":"「political conflicts and wars」是涉及權力爭奪、可能包括暴力和流離失所的事件。"},{"en":"A farming community may be forced to leave its land during war.","zh":"戰爭期間，農業社區可能被迫離開土地。"},{"en":"If people flee into fragile ecosystems, land pressure can increase.","zh":"如果人們逃入脆弱生態系統，土地壓力可以增加。"},{"en":"The phrase links human conflict with environmental damage.","zh":"這個短語把人類衝突與環境破壞連繫起來。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":12},{"front":"contribute to desertification","meaning":"促成沙漠化","examples":[{"en":"Wars and conflicts can contribute to desertification.","zh":"戰爭和衝突可以促成沙漠化。"},{"en":"To contribute to desertification means to help cause or worsen the process.","zh":"「contribute to desertification」意思是幫助造成或惡化沙漠化過程。"},{"en":"Poor irrigation can contribute to soil damage in farming areas.","zh":"灌溉不善可以促成農地土壤損害。"},{"en":"If refugees and livestock enter fragile land suddenly, desertification may increase.","zh":"如果難民和牲畜突然進入脆弱土地，沙漠化可能增加。"},{"en":"The phrase describes one factor adding to a larger problem.","zh":"這個短語描述一個因素加入更大問題中。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":12},{"front":"escape invading enemies","meaning":"逃避入侵的敵人","examples":[{"en":"Refugees may move to vulnerable ecosystems to escape invading enemies.","zh":"難民可能遷往脆弱生態系統以逃避入侵的敵人。"},{"en":"To escape invading enemies means to flee from hostile forces entering an area.","zh":"「escape invading enemies」意思是逃離進入某地的敵對力量。"},{"en":"Families may leave their homes to escape fighting near their village.","zh":"家庭可能為逃避村莊附近戰鬥而離家。"},{"en":"If many people flee at once, they may settle in fragile land with limited resources.","zh":"如果許多人同時逃走，他們可能在資源有限的脆弱土地定居。"},{"en":"The phrase describes movement caused by danger.","zh":"這個短語描述由危險造成的遷移。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":12},{"front":"refugees","meaning":"難民","examples":[{"en":"Refugees may move en masse into vulnerable ecosystems.","zh":"難民可能大批遷入脆弱生態系統。"},{"en":"Refugees are people forced to leave their homes because of war, violence, or danger.","zh":"「refugees」是因戰爭、暴力或危險而被迫離家的人。"},{"en":"A refugee family may cross a border to find safety.","zh":"難民家庭可能越過邊境尋找安全。"},{"en":"If refugees arrive suddenly in dryland areas, local resources may become strained.","zh":"如果難民突然到達旱地地區，本地資源可能受壓。"},{"en":"The phrase describes displaced people needing protection.","zh":"這個短語描述需要保護的流離失所者。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":12},{"front":"move en masse","meaning":"大批遷移","examples":[{"en":"Refugees may move en masse into fragile environments.","zh":"難民可能大批遷入脆弱環境。"},{"en":"To move en masse means to move in a large group at the same time.","zh":"「move en masse」意思是大群人同時移動。"},{"en":"Students may move en masse to the hall after the fire alarm rings.","zh":"火警鐘響起後，學生可能大批移往禮堂。"},{"en":"If many people move en masse into one area, resources can be quickly stretched.","zh":"如果許多人同時大批遷入一個地區，資源可能很快緊張。"},{"en":"The phrase stresses large-scale movement.","zh":"這個短語強調大規模移動。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":12},{"front":"the planet’s most vulnerable ecosystems","meaning":"地球上最脆弱的生態系統","examples":[{"en":"Refugees may enter some of the planet’s most vulnerable ecosystems.","zh":"難民可能進入地球上最脆弱的一些生態系統。"},{"en":"The planet’s most vulnerable ecosystems are Earth’s natural systems most easily damaged.","zh":"「the planet’s most vulnerable ecosystems」是地球上最容易受損的自然系統。"},{"en":"Coral reefs and dryland ecosystems can be highly vulnerable to human pressure.","zh":"珊瑚礁和旱地生態系統都可能非常容易受人類壓力影響。"},{"en":"If vulnerable ecosystems receive sudden population pressure, damage can occur quickly.","zh":"如果脆弱生態系統突然承受人口壓力，破壞可以很快發生。"},{"en":"The phrase stresses global environmental fragility.","zh":"這個短語強調全球環境脆弱性。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":12},{"front":"farming practices","meaning":"耕作方式","examples":[{"en":"Refugees may bring farming practices that are unsuited to the new environment.","zh":"難民可能帶來不適合新環境的耕作方式。"},{"en":"Farming practices are the methods people use to grow crops or raise animals.","zh":"「farming practices」是人們種植作物或飼養動物的方法。"},{"en":"Farmers may change farming practices when water becomes scarce.","zh":"當水變得稀少，農民可能改變耕作方式。"},{"en":"If farming practices do not suit dry land, soil can be damaged.","zh":"如果耕作方式不適合乾地，土壤可能受損。"},{"en":"The phrase describes how agriculture is carried out.","zh":"這個短語描述農業如何進行。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":12},{"front":"be unsuited to","meaning":"不適合……","examples":[{"en":"Some farming practices are unsuited to dryland ecosystems.","zh":"有些耕作方式不適合旱地生態系統。"},{"en":"To be unsuited to something means to be unsuitable for it.","zh":"「be unsuited to」某物，意思是不適合它。"},{"en":"Heavy winter clothing is unsuited to a hot summer classroom.","zh":"厚冬衣不適合炎熱夏天的課室。"},{"en":"If farming methods are unsuited to dryland, they may waste water and damage soil.","zh":"如果耕作方法不適合旱地，它們可能浪費水並破壞土壤。"},{"en":"The phrase describes a poor fit.","zh":"這個短語描述不匹配。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":13},{"front":"the new environment","meaning":"新環境","examples":[{"en":"Some farming practices are unsuited to the new environment.","zh":"有些耕作方式不適合新環境。"},{"en":"The new environment means the unfamiliar place or conditions people have moved into.","zh":"「the new environment」指人們遷入的陌生地方或條件。"},{"en":"A student changing schools needs time to adjust to the new environment.","zh":"轉校學生需要時間適應新環境。"},{"en":"If old methods do not fit the new environment, people must adapt.","zh":"如果舊方法不適合新環境，人們必須適應。"},{"en":"The phrase describes changed surroundings.","zh":"這個短語描述改變了的周遭環境。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":13},{"front":"a large section of farmland","meaning":"大片農地","examples":[{"en":"One US state had a large section of farmland that had turned into desert.","zh":"美國一個州有大片農地已變成沙漠。"},{"en":"A large section of farmland means a big area of land used for growing crops.","zh":"「a large section of farmland」是用於種植作物的大片土地。"},{"en":"A flood can damage a large section of farmland near a river.","zh":"洪水可以破壞河流附近大片農地。"},{"en":"If farmland loses soil and water, it may stop being productive.","zh":"如果農地失去土壤和水分，它可能停止有生產力。"},{"en":"The phrase stresses that the affected area is large.","zh":"這個短語強調受影響範圍很大。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":13},{"front":"turn into desert","meaning":"變成沙漠","examples":[{"en":"A large section of farmland had turned into desert.","zh":"大片農地已變成沙漠。"},{"en":"To turn into desert means to become dry, barren, and no longer productive.","zh":"「turn into desert」意思是變得乾旱、荒蕪並不再有生產力。"},{"en":"A green field can turn into bare land if irrigation fails for years.","zh":"如果灌溉多年失效，綠色田地可以變成裸地。"},{"en":"If vegetation disappears and soil erodes, farmland may turn into desert.","zh":"如果植被消失且土壤侵蝕，農地可能變成沙漠。"},{"en":"The phrase describes serious land degradation.","zh":"這個短語描述嚴重土地退化。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":13},{"front":"since then","meaning":"自那時起","examples":[{"en":"Since then, measures have been implemented to prevent desertification.","zh":"自那時起，已實施措施來防止沙漠化。"},{"en":"Since then means from that time until now or until a later point.","zh":"「since then」意思是從那時起直到現在或後來某時。"},{"en":"The school changed its rules in 2020; since then, fewer students have been late.","zh":"學校在2020年改變規則；自那時起，遲到學生減少了。"},{"en":"If a disaster happens, actions taken since then may prevent a repeat.","zh":"如果災害發生，自那時起採取的行動可能防止重演。"},{"en":"The phrase links a past event with later developments.","zh":"這個短語把過去事件與後來發展連繫起來。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":13},{"front":"measures have been implemented","meaning":"已實施措施","examples":[{"en":"Measures have been implemented to prevent desertification from recurring.","zh":"已實施措施防止沙漠化再次發生。"},{"en":"Measures have been implemented means actions or policies have been put into practice.","zh":"「measures have been implemented」意思是行動或政策已付諸實行。"},{"en":"A school may implement measures to reduce bullying after complaints.","zh":"學校在收到投訴後可能實施措施減少欺凌。"},{"en":"If measures are implemented early, land damage may be slowed.","zh":"如果及早實施措施，土地破壞可能被減慢。"},{"en":"The phrase describes action taken, not just planned.","zh":"這個短語描述已採取行動，而不只是計劃。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":13},{"front":"prevent something from recurring","meaning":"防止……再次發生","examples":[{"en":"Measures were implemented to prevent desertification from recurring.","zh":"已實施措施防止沙漠化再次發生。"},{"en":"To prevent something from recurring means to stop it from happening again.","zh":"「prevent something from recurring」意思是阻止某事再次發生。"},{"en":"A teacher may change classroom rules to prevent arguments from recurring.","zh":"老師可能改變課室規則，以防止爭吵再次發生。"},{"en":"If desertification recurs, the same land may become damaged again.","zh":"如果沙漠化再次發生，同一片土地可能再次受損。"},{"en":"The phrase focuses on stopping repetition.","zh":"這個短語集中於阻止重複出現。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":13},{"front":"be encouraged to","meaning":"被鼓勵去","examples":[{"en":"People are encouraged to find livelihoods that use fewer natural resources.","zh":"人們被鼓勵去尋找使用較少天然資源的生計。"},{"en":"To be encouraged to do something means to be advised or supported to do it.","zh":"「be encouraged to」做某事，意思是被建議或支持去做它。"},{"en":"Students are encouraged to ask questions when they do not understand.","zh":"當學生不明白時，他們被鼓勵去提問。"},{"en":"If people are encouraged to use fewer resources, land pressure may decrease.","zh":"如果人們被鼓勵使用較少資源，土地壓力可能下降。"},{"en":"The phrase describes positive guidance.","zh":"這個短語描述正面引導。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":13},{"front":"livelihoods","meaning":"生計；謀生方式","examples":[{"en":"People are encouraged to find sustainable livelihoods.","zh":"人們被鼓勵尋找可持續的生計。"},{"en":"Livelihoods are ways people earn enough money or resources to live.","zh":"「livelihoods」是人們賺取足夠金錢或資源來生活的方式。"},{"en":"Fishing, farming, teaching, and shopkeeping can all be livelihoods.","zh":"捕魚、耕作、教學和開店都可以是謀生方式。"},{"en":"If a livelihood damages land, it may not be sustainable.","zh":"如果一種生計破壞土地，它可能不可持續。"},{"en":"The phrase focuses on how people support themselves.","zh":"這個短語集中於人們如何養活自己。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":13},{"front":"place fewer demands on","meaning":"對……造成較少需求","examples":[{"en":"Some livelihoods place fewer demands on local land.","zh":"有些生計對本地土地造成較少需求。"},{"en":"To place fewer demands on something means to require less from it.","zh":"「place fewer demands on」某物，意思是對它要求較少。"},{"en":"Online work may place fewer demands on transport than daily commuting.","zh":"網上工作可能比每天通勤對交通造成較少需求。"},{"en":"If people earn income outside farming, they place less pressure on dryland soil.","zh":"如果人們在農業以外賺取收入，他們對旱地土壤的壓力較少。"},{"en":"The phrase describes reducing pressure on resources.","zh":"這個短語描述減少對資源的壓力。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":13},{"front":"local land and natural resources","meaning":"本地土地和天然資源","examples":[{"en":"People need livelihoods that place fewer demands on local land and natural resources.","zh":"人們需要對本地土地和天然資源造成較少需求的生計。"},{"en":"Local land and natural resources are nearby soil, water, plants, animals, and materials people use.","zh":"「local land and natural resources」是附近人們使用的土壤、水、植物、動物和材料。"},{"en":"A village may depend on local land and natural resources for food and fuel.","zh":"村莊可能依賴本地土地和天然資源獲取食物和燃料。"},{"en":"If these resources are overused, desertification risk can rise.","zh":"如果這些資源被過度使用，沙漠化風險可能上升。"},{"en":"The phrase describes the environment people rely on.","zh":"這個短語描述人們依賴的環境。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":13},{"front":"generate a viable income","meaning":"產生可行的收入","examples":[{"en":"Alternative livelihoods can still generate a viable income.","zh":"替代生計仍可以產生可行的收入。"},{"en":"To generate a viable income means to earn enough money to live on.","zh":"「generate a viable income」意思是賺取足夠生活的金錢。"},{"en":"A small shop can generate a viable income if it has regular customers.","zh":"如果有固定顧客，小店可以產生可行的收入。"},{"en":"If new work pays enough, people may depend less on fragile land.","zh":"如果新工作收入足夠，人們可能較少依賴脆弱土地。"},{"en":"The phrase describes income that is realistic and sustainable.","zh":"這個短語描述實際而可持續的收入。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":14},{"front":"a viable income","meaning":"可維持生計的收入","examples":[{"en":"People need work that can generate a viable income.","zh":"人們需要能產生可維持生計收入的工作。"},{"en":"A viable income is enough money to support basic living needs.","zh":"「a viable income」是足以支持基本生活需要的收入。"},{"en":"A part-time job may not provide a viable income for a whole family.","zh":"兼職工作未必能為整個家庭提供可維持生計的收入。"},{"en":"If income is viable, people can survive without damaging land for short-term gain.","zh":"如果收入可維持生計，人們就能生存，而不用為短期收益破壞土地。"},{"en":"The phrase means income that can realistically sustain life.","zh":"這個短語指實際上能支持生活的收入。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":14},{"front":"include but are not limited to","meaning":"包括但不限於","examples":[{"en":"These livelihoods include but are not limited to aquaculture and tourism.","zh":"這些生計包括但不限於水產養殖和旅遊。"},{"en":"Include but are not limited to means the list gives examples but not every possibility.","zh":"「include but are not limited to」意思是清單提供例子，但不是全部可能性。"},{"en":"School activities include but are not limited to sports, music, and debate.","zh":"學校活動包括但不限於運動、音樂和辯論。"},{"en":"If a list is not limited, other suitable options can also be considered.","zh":"如果清單不限於某些項目，其他合適選項也可以考慮。"},{"en":"The phrase is formal and often used in instructions or reports.","zh":"這個短語較正式，常用於指示或報告。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":14},{"front":"dryland aquaculture","meaning":"旱地水產養殖","examples":[{"en":"Dryland aquaculture can provide an alternative livelihood.","zh":"旱地水產養殖可以提供替代生計。"},{"en":"Dryland aquaculture is raising aquatic organisms in dry regions using managed water systems.","zh":"「dryland aquaculture」是在乾旱地區利用管理水系統養殖水生生物。"},{"en":"A community may use ponds or tanks for dryland aquaculture.","zh":"社區可能使用池塘或水箱進行旱地水產養殖。"},{"en":"If aquaculture earns income, people may rely less on overgrazing.","zh":"如果水產養殖能帶來收入，人們可能較少依賴過度放牧。"},{"en":"The phrase describes fish or water-based farming in dry areas.","zh":"這個短語描述乾旱地區的魚類或水基養殖。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":14},{"front":"raising fish and crustaceans","meaning":"養殖魚類和甲殼類動物","examples":[{"en":"Dryland aquaculture may involve raising fish and crustaceans.","zh":"旱地水產養殖可能涉及養殖魚類和甲殼類動物。"},{"en":"Raising fish and crustaceans means farming aquatic animals such as fish, crabs, or shrimps.","zh":"「raising fish and crustaceans」意思是養殖魚、蟹或蝦等水生動物。"},{"en":"A village pond may be used for raising fish for local markets.","zh":"村莊池塘可能用於養魚供本地市場出售。"},{"en":"If people raise aquatic animals successfully, they can earn income without expanding crop fields.","zh":"如果人們成功養殖水生動物，他們可以賺取收入而不用擴展農田。"},{"en":"The phrase describes a type of aquaculture.","zh":"這個短語描述一種水產養殖。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":14},{"front":"crustaceans","meaning":"甲殼類動物","examples":[{"en":"Crabs and shrimps are examples of crustaceans.","zh":"蟹和蝦都是甲殼類動物的例子。"},{"en":"Crustaceans are aquatic animals with hard outer shells, such as crabs and prawns.","zh":"「crustaceans」是有堅硬外殼的水生動物，例如蟹和蝦。"},{"en":"Seafood markets often sell crustaceans alongside fish.","zh":"海鮮市場常把甲殼類動物和魚一起出售。"},{"en":"If crustaceans are farmed carefully, they can provide food and income.","zh":"如果甲殼類動物被仔細養殖，它們可以提供食物和收入。"},{"en":"The word names a group of shell-covered animals.","zh":"這個詞指出一類有外殼的動物。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":14},{"front":"industrial compounds","meaning":"工業化合物","examples":[{"en":"Microalgae can be used to produce industrial compounds.","zh":"微藻可以用來生產工業化合物。"},{"en":"Industrial compounds are chemical substances used in manufacturing or industry.","zh":"「industrial compounds」是用於製造或工業的化學物質。"},{"en":"Factories may use industrial compounds to make plastics, medicines, or cleaning products.","zh":"工廠可能使用工業化合物製造塑膠、藥物或清潔產品。"},{"en":"If useful compounds come from microalgae, dryland economies may gain new income sources.","zh":"如果有用化合物來自微藻，旱地經濟可能獲得新收入來源。"},{"en":"The phrase describes materials with commercial or industrial value.","zh":"這個短語描述具有商業或工業價值的材料。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":14},{"front":"be derived from","meaning":"源自……","examples":[{"en":"Some industrial compounds are derived from microalgae.","zh":"有些工業化合物源自微藻。"},{"en":"To be derived from something means to come from it or be produced from it.","zh":"「be derived from」某物，意思是來自它或由它製成。"},{"en":"Some medicines are derived from plants.","zh":"有些藥物源自植物。"},{"en":"If a product is derived from algae, algae are its source material.","zh":"如果產品源自藻類，藻類就是其原材料。"},{"en":"The phrase identifies origin or source.","zh":"這個短語指出來源。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":14},{"front":"microalgae","meaning":"微藻","examples":[{"en":"Industrial compounds can be derived from microalgae.","zh":"工業化合物可以源自微藻。"},{"en":"Microalgae are tiny algae that live in water and can be grown for useful products.","zh":"「microalgae」是生活在水中、可培養成有用產品的微小藻類。"},{"en":"Scientists may grow microalgae in tanks for food, fuel, or chemicals.","zh":"科學家可能在水箱中培養微藻，用於食物、燃料或化學品。"},{"en":"If microalgae are farmed successfully, they can create income without using much land.","zh":"如果微藻成功被養殖，它們可以在不使用大量土地下創造收入。"},{"en":"The word describes very small plant-like organisms.","zh":"這個詞描述非常細小、類似植物的生物。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":14},{"front":"greenhouse agriculture","meaning":"溫室農業","examples":[{"en":"Greenhouse agriculture is another possible livelihood.","zh":"溫室農業是另一種可能的生計。"},{"en":"Greenhouse agriculture means growing crops inside controlled structures.","zh":"「greenhouse agriculture」是在受控制結構內種植作物。"},{"en":"A greenhouse can protect vegetables from wind, pests, and extreme weather.","zh":"溫室可以保護蔬菜免受風、害蟲和極端天氣影響。"},{"en":"If crops are grown in greenhouses, water and soil use may be better managed.","zh":"如果作物在溫室中種植，水和土壤使用可能更好管理。"},{"en":"The phrase describes farming under controlled conditions.","zh":"這個短語描述受控制條件下的農業。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":14},{"front":"tourism-related activities","meaning":"與旅遊相關的活動","examples":[{"en":"Tourism-related activities can generate income outside farming.","zh":"與旅遊相關的活動可以在農業以外產生收入。"},{"en":"Tourism-related activities are jobs or services connected with visitors and travel.","zh":"「tourism-related activities」是與旅客和旅行有關的工作或服務。"},{"en":"Guiding tours, selling crafts, and running guesthouses are tourism-related activities.","zh":"導賞、出售手工藝品和經營民宿都是與旅遊相關的活動。"},{"en":"If tourism brings income, people may depend less on fragile land for farming.","zh":"如果旅遊帶來收入，人們可能較少依賴脆弱土地耕作。"},{"en":"The phrase describes work linked to tourism.","zh":"這個短語描述與旅遊相關的工作。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":14},{"front":"the recurrence of desertification","meaning":"沙漠化再次發生","examples":[{"en":"New measures can prevent the recurrence of desertification.","zh":"新措施可以防止沙漠化再次發生。"},{"en":"The recurrence of desertification means desertification happening again after it has been controlled or stopped.","zh":"「the recurrence of desertification」是沙漠化在被控制或停止後再次發生。"},{"en":"A town may work to prevent the recurrence of flooding after a major storm.","zh":"大風暴後，城鎮可能努力防止洪水再次發生。"},{"en":"If old land-use habits return, desertification may recur.","zh":"如果舊土地使用習慣恢復，沙漠化可能再次出現。"},{"en":"The phrase focuses on preventing the same problem from coming back.","zh":"這個短語集中於防止同一問題回來。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":15},{"front":"improve economic prospects","meaning":"改善經濟前景","examples":[{"en":"Another solution is to improve economic prospects outside drylands.","zh":"另一個解決方法是在旱地以外改善經濟前景。"},{"en":"To improve economic prospects means to create better chances for jobs and income.","zh":"「improve economic prospects」意思是創造更好的就業和收入機會。"},{"en":"A training centre can improve economic prospects for young workers.","zh":"培訓中心可以改善年輕工人的經濟前景。"},{"en":"If people have better job options, pressure on dryland farming may fall.","zh":"如果人們有更好工作選擇，旱地耕作壓力可能下降。"},{"en":"The phrase describes strengthening future economic opportunities.","zh":"這個短語描述加強未來經濟機會。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":15},{"front":"economic prospects","meaning":"經濟前景","examples":[{"en":"Better economic prospects can reduce pressure on drylands.","zh":"更好的經濟前景可以減少旱地壓力。"},{"en":"Economic prospects are future chances for jobs, income, and financial improvement.","zh":"「economic prospects」是未來就業、收入和財務改善的機會。"},{"en":"A city with new industries may offer strong economic prospects for graduates.","zh":"有新產業的城市可能為畢業生提供良好經濟前景。"},{"en":"If economic prospects are poor, people may overuse local land to survive.","zh":"如果經濟前景差，人們可能為生存過度使用本地土地。"},{"en":"The phrase describes future economic opportunity.","zh":"這個短語描述未來經濟機會。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":15},{"front":"city centres","meaning":"市中心","examples":[{"en":"Economic prospects may be improved in city centres.","zh":"經濟前景可能在市中心得到改善。"},{"en":"City centres are the central areas of cities where many jobs, shops, and services are located.","zh":"「city centres」是城市中央地區，通常有許多工作、商店和服務。"},{"en":"A young worker may move to a city centre for better employment.","zh":"年輕工人可能搬到市中心尋找更好就業。"},{"en":"If city centres offer jobs, fewer people may rely on dryland resources.","zh":"如果市中心提供工作，較少人可能依賴旱地資源。"},{"en":"The phrase refers to urban economic hubs.","zh":"這個短語指城市經濟中心。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":15},{"front":"outside of drylands","meaning":"在旱地以外","examples":[{"en":"Opportunities outside of drylands can reduce pressure on vulnerable land.","zh":"旱地以外的機會可以減少脆弱土地的壓力。"},{"en":"Outside of drylands means in places that are not dryland regions.","zh":"「outside of drylands」意思是在非旱地地區。"},{"en":"A family may seek work outside of drylands if farming becomes unreliable.","zh":"如果耕作變得不可靠，家庭可能在旱地以外尋找工作。"},{"en":"If income is available elsewhere, people may place fewer demands on fragile soil.","zh":"如果其他地方有收入，人們可能對脆弱土壤造成較少需求。"},{"en":"The phrase contrasts dryland areas with other locations.","zh":"這個短語把旱地與其他地點作對比。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":15},{"front":"economic and institutional structures","meaning":"經濟和制度結構","examples":[{"en":"Economic and institutional structures can create new opportunities.","zh":"經濟和制度結構可以創造新機會。"},{"en":"Economic and institutional structures are systems of jobs, markets, laws, organisations, and public services.","zh":"「economic and institutional structures」是就業、市場、法律、組織和公共服務等系統。"},{"en":"A city’s transport, banks, schools, and laws form part of its institutional structure.","zh":"城市的交通、銀行、學校和法律構成其制度結構的一部分。"},{"en":"If these structures improve, people may find work without overusing land.","zh":"如果這些結構改善，人們可能找到工作而不用過度使用土地。"},{"en":"The phrase describes the systems that shape people’s choices.","zh":"這個短語描述塑造人們選擇的系統。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":15},{"front":"create new opportunities for","meaning":"為……創造新機會","examples":[{"en":"New structures can create new opportunities for people to support themselves.","zh":"新結構可以為人們養活自己創造新機會。"},{"en":"To create new opportunities for someone means to open new chances for them.","zh":"「create new opportunities for」某人，意思是為他們開創新機會。"},{"en":"A training programme can create new opportunities for school leavers.","zh":"培訓計劃可以為離校生創造新機會。"},{"en":"If people get new opportunities, they may not need to rely on damaging land use.","zh":"如果人們獲得新機會，他們可能不需要依賴破壞土地的做法。"},{"en":"The phrase describes making better choices possible.","zh":"這個短語描述使更好選擇成為可能。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":15},{"front":"support themselves","meaning":"養活自己","examples":[{"en":"People need opportunities to support themselves.","zh":"人們需要機會來養活自己。"},{"en":"To support themselves means to earn enough to pay for their own basic needs.","zh":"「support themselves」意思是賺取足夠金錢支付自己的基本需要。"},{"en":"A graduate may take a job to support herself after university.","zh":"畢業生可能在大學後找工作來養活自己。"},{"en":"If people cannot support themselves, they may overuse local resources to survive.","zh":"如果人們不能養活自己，他們可能為生存而過度使用本地資源。"},{"en":"The phrase describes financial self-sufficiency.","zh":"這個短語描述經濟自立。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":15},{"front":"alleviate the current pressures","meaning":"紓緩目前的壓力","examples":[{"en":"Economic change can alleviate the current pressures on drylands.","zh":"經濟改變可以紓緩旱地目前的壓力。"},{"en":"To alleviate the current pressures means to reduce the problems or demands happening now.","zh":"「alleviate the current pressures」意思是減少目前正在發生的問題或需求。"},{"en":"Hiring more nurses can alleviate current pressure in a busy hospital.","zh":"聘請更多護士可以紓緩繁忙醫院目前的壓力。"},{"en":"If people find other income sources, pressure on dryland farming may ease.","zh":"如果人們找到其他收入來源，旱地耕作壓力可能減輕。"},{"en":"The phrase describes reducing strain.","zh":"這個短語描述減少壓力。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":15},{"front":"current pressures","meaning":"目前的壓力","examples":[{"en":"Desertification processes are accompanied by current pressures on land.","zh":"沙漠化過程伴隨土地目前的壓力。"},{"en":"Current pressures are the demands or stresses affecting a situation now.","zh":"「current pressures」是目前影響某情況的需求或壓力。"},{"en":"A school’s current pressures may include large classes and limited teachers.","zh":"學校目前的壓力可能包括班級太大和老師不足。"},{"en":"If current pressures on land continue, desertification may worsen.","zh":"如果土地目前壓力持續，沙漠化可能惡化。"},{"en":"The phrase describes present strain, not past problems only.","zh":"這個短語描述當前壓力，而不只是過去問題。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":15},{"front":"accompanying the desertification processes","meaning":"伴隨沙漠化過程的","examples":[{"en":"Economic pressures may accompany the desertification processes.","zh":"經濟壓力可能伴隨沙漠化過程。"},{"en":"Accompanying the desertification processes means happening together with land becoming desert-like.","zh":"「accompanying the desertification processes」意思是與土地變得沙漠化同時發生。"},{"en":"Stress may accompany exam preparation when deadlines are close.","zh":"當截止日期接近，壓力可能伴隨考試準備。"},{"en":"If poverty accompanies desertification, environmental and social problems can reinforce each other.","zh":"如果貧窮伴隨沙漠化，環境和社會問題可能互相加強。"},{"en":"The phrase describes problems occurring alongside desertification.","zh":"這個短語描述與沙漠化同時發生的問題。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":15},{"front":"desertification processes","meaning":"沙漠化過程","examples":[{"en":"Alternative livelihoods can reduce pressure linked to desertification processes.","zh":"替代生計可以減少與沙漠化過程相關的壓力。"},{"en":"Desertification processes are the steps through which land becomes degraded and desert-like.","zh":"「desertification processes」是土地退化並變得像沙漠的步驟。"},{"en":"A geography diagram may show desertification processes such as overgrazing and erosion.","zh":"地理圖表可能展示過度放牧和侵蝕等沙漠化過程。"},{"en":"If these processes are interrupted, land may be protected.","zh":"如果這些過程被打斷，土地可能受到保護。"},{"en":"The phrase focuses on ongoing changes, not one sudden event.","zh":"這個短語集中於持續變化，而不是單一突發事件。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":16},{"front":"new technologies","meaning":"新科技","examples":[{"en":"New technologies are being used to address desertification.","zh":"新科技正被用來處理沙漠化。"},{"en":"New technologies are recently developed tools, machines, or methods.","zh":"「new technologies」是近年開發的工具、機器或方法。"},{"en":"Schools use new technologies such as online platforms and interactive screens.","zh":"學校使用網上平台和互動屏幕等新科技。"},{"en":"If new technologies track land damage early, prevention becomes easier.","zh":"如果新科技能及早追蹤土地破壞，預防會更容易。"},{"en":"The phrase refers to modern tools for solving problems.","zh":"這個短語指解決問題的現代工具。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":16},{"front":"address the problems caused by","meaning":"處理由……造成的問題","examples":[{"en":"New technologies address the problems caused by desertification.","zh":"新科技處理由沙漠化造成的問題。"},{"en":"To address the problems caused by something means to deal with the difficulties it creates.","zh":"「address the problems caused by」某事，意思是處理它造成的困難。"},{"en":"A school may address problems caused by bullying through counselling and clear rules.","zh":"學校可能透過輔導和清楚規則處理欺凌造成的問題。"},{"en":"If desertification causes poverty and soil loss, solutions must deal with both.","zh":"如果沙漠化造成貧窮和土壤流失，解決方法必須兩者都處理。"},{"en":"The phrase describes active problem-solving.","zh":"這個短語描述主動解決問題。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":16},{"front":"satellites","meaning":"衛星","examples":[{"en":"Satellites have been used to investigate desertification.","zh":"衛星已被用來調查沙漠化。"},{"en":"Satellites are machines sent into space to collect information or support communication.","zh":"「satellites」是送入太空以收集資料或支援通訊的機器。"},{"en":"Weather satellites help people track storms before they arrive.","zh":"氣象衛星幫助人們在風暴到來前追蹤它。"},{"en":"If satellites monitor land changes, scientists can study desertification from above.","zh":"如果衛星監測土地變化，科學家可以從上方研究沙漠化。"},{"en":"The word describes space-based technology.","zh":"這個詞描述太空技術。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":16},{"front":"investigate the influence of","meaning":"調查……的影響","examples":[{"en":"Satellites investigate the influence of people and livestock on desertification.","zh":"衛星調查人類和牲畜對沙漠化的影響。"},{"en":"To investigate the influence of something means to study how it affects another thing.","zh":"「investigate the influence of」某事，意思是研究它如何影響另一事物。"},{"en":"Teachers may investigate the influence of sleep on students’ test scores.","zh":"老師可能調查睡眠對學生考試分數的影響。"},{"en":"If scientists study livestock influence, they can see whether grazing worsens land damage.","zh":"如果科學家研究牲畜的影響，他們可以看到放牧是否惡化土地破壞。"},{"en":"The phrase describes research into cause and effect.","zh":"這個短語描述對因果影響的研究。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":16},{"front":"the influence that people and livestock have on","meaning":"人類和牲畜對……的影響","examples":[{"en":"Satellites can investigate the influence that people and livestock have on desertification.","zh":"衛星可以調查人類和牲畜對沙漠化的影響。"},{"en":"The influence that people and livestock have on something means the effect they create.","zh":"「the influence that people and livestock have on」某事，意思是他們造成的影響。"},{"en":"A school may study the influence that homework and sleep have on exam results.","zh":"學校可能研究功課和睡眠對考試成績的影響。"},{"en":"If people and livestock damage vegetation, their influence on desertification may be strong.","zh":"如果人類和牲畜破壞植被，他們對沙漠化的影響可能很強。"},{"en":"The phrase identifies who or what is affecting the process.","zh":"這個短語指出誰或甚麼正在影響該過程。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":16},{"front":"livestock","meaning":"牲畜","examples":[{"en":"Livestock can have a serious impact on dryland ecosystems.","zh":"牲畜可以對旱地生態系統有嚴重影響。"},{"en":"Livestock are farm animals such as cattle, sheep, goats, or camels.","zh":"「livestock」是牛、羊、山羊或駱駝等農場動物。"},{"en":"A farmer may keep livestock for meat, milk, wool, or transport.","zh":"農民可能飼養牲畜以獲取肉、奶、羊毛或運輸力。"},{"en":"If too much livestock grazes one area, vegetation may disappear.","zh":"如果太多牲畜在同一地區放牧，植被可能消失。"},{"en":"The word refers to animals raised for practical use.","zh":"這個詞指為實際用途飼養的動物。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":16},{"front":"even so","meaning":"即使如此","examples":[{"en":"Even so, alternative technologies are still needed.","zh":"即使如此，仍然需要替代技術。"},{"en":"Even so means despite what has just been said.","zh":"「even so」意思是儘管剛才所說如此。"},{"en":"The lesson was clear; even so, some students still needed more practice.","zh":"課堂很清楚；即使如此，有些學生仍需要更多練習。"},{"en":"If satellites are useful, even so, other methods may still be necessary.","zh":"如果衛星有用，即使如此，其他方法可能仍然必要。"},{"en":"The phrase introduces a contrast or limitation.","zh":"這個短語引入對比或限制。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":16},{"front":"alternative technologies","meaning":"替代技術；其他技術","examples":[{"en":"Alternative technologies are still needed to address desertification.","zh":"仍然需要替代技術來處理沙漠化。"},{"en":"Alternative technologies are other tools or methods used when existing ones are not enough.","zh":"「alternative technologies」是在現有工具不足時使用的其他工具或方法。"},{"en":"A school may use alternative technologies if the internet fails during online lessons.","zh":"如果網課期間網絡失效，學校可能使用替代技術。"},{"en":"If satellites cannot solve every problem, other technologies must fill the gaps.","zh":"如果衛星不能解決每個問題，其他技術必須填補空白。"},{"en":"The phrase describes additional or different technical solutions.","zh":"這個短語描述額外或不同的技術解決方案。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":16},{"front":"problems and processes of desertification","meaning":"沙漠化的問題和過程","examples":[{"en":"More technologies are needed to address the problems and processes of desertification.","zh":"需要更多科技來處理沙漠化的問題和過程。"},{"en":"Problems and processes of desertification means both the damage caused and the steps by which it happens.","zh":"「problems and processes of desertification」指沙漠化造成的破壞以及它發生的步驟。"},{"en":"A teacher may explain both the problems and processes of pollution.","zh":"老師可能同時解釋污染的問題和過程。"},{"en":"If we understand the process, we can design better ways to solve the problem.","zh":"如果我們理解過程，就能設計更好的解決方法。"},{"en":"The phrase includes both causes and results.","zh":"這個短語同時包括成因和結果。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":16},{"front":"the following information","meaning":"以下資料","examples":[{"en":"Students match each paragraph with the following information.","zh":"學生把每段與以下資料配對。"},{"en":"The following information means the details listed after the instruction.","zh":"「the following information」指指示後列出的資料。"},{"en":"In a reading task, students should read the following information before scanning the text.","zh":"在閱讀題中，學生應先閱讀以下資料，再掃讀文章。"},{"en":"If the information matches a paragraph, students choose that paragraph letter.","zh":"如果資料與某段匹配，學生就選該段字母。"},{"en":"The phrase points to the items students must use.","zh":"這個短語指向學生必須使用的項目。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":16},{"front":"contains the following information","meaning":"包含以下資料","examples":[{"en":"Each paragraph may contain the following information.","zh":"每段可能包含以下資料。"},{"en":"Contains the following information means includes the details listed below.","zh":"「contains the following information」意思是包括下方列出的細節。"},{"en":"A notice may contain the following information: date, time, place, and fee.","zh":"通告可能包含以下資料：日期、時間、地點和費用。"},{"en":"If a paragraph contains the detail, students can match it correctly.","zh":"如果某段包含該細節，學生就能正確配對。"},{"en":"The phrase is common in information-matching tasks.","zh":"這個短語常見於資料配對題。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":17},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Students write the correct letter on the answer sheet.","zh":"學生在答題紙上寫上正確字母。"},{"en":"Write the correct letter means record the option letter that matches the answer.","zh":"「write the correct letter」意思是寫下與答案相符的選項字母。"},{"en":"In a matching task, students may write A, B, C, or D.","zh":"在配對題中，學生可能寫 A、B、C 或 D。"},{"en":"If the idea is right but the letter is wrong, the answer may be marked incorrect.","zh":"如果意思正確但字母錯誤，答案可能被判錯。"},{"en":"The phrase is a practical exam instruction.","zh":"這個短語是實際考試指示。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":17},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生在答題紙上寫下答案。"},{"en":"On your answer sheet means in the official place where answers must be recorded.","zh":"「on your answer sheet」意思是在必須記錄答案的正式位置。"},{"en":"In exams, students should not leave correct answers only on the question paper.","zh":"在考試中，學生不應只把正確答案留在試卷上。"},{"en":"If answers are not written on the answer sheet, they may not be marked.","zh":"如果答案沒有寫在答題紙上，可能不會被評分。"},{"en":"The phrase tells students where to write.","zh":"這個短語告訴學生在哪裡書寫。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":17},{"front":"use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"Students may use any letter more than once.","zh":"學生可以重複使用任何字母。"},{"en":"Use any letter more than once means the same option can be selected repeatedly.","zh":"「use any letter more than once」意思是同一選項可以重複選擇。"},{"en":"In a matching exercise, one paragraph letter may answer two questions.","zh":"在配對練習中，一個段落字母可能回答兩條問題。"},{"en":"If a letter can be repeated, students should not force each answer to be different.","zh":"如果字母可以重複使用，學生不應強行令每個答案不同。"},{"en":"The phrase removes a common exam misunderstanding.","zh":"這個短語消除常見考試誤解。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":17},{"front":"a reference to","meaning":"提及……","examples":[{"en":"The question asks for a reference to the movement of particles.","zh":"問題要求找出提及微粒移動的地方。"},{"en":"A reference to something is a mention of it.","zh":"「a reference to」某事，是對它的提及。"},{"en":"A passage may include a reference to climate change without discussing it in detail.","zh":"文章可能提及氣候變化，但沒有詳細討論。"},{"en":"If a question asks for a reference, students should find where the idea is mentioned.","zh":"如果問題要求找出提及之處，學生應找該想法在哪裡出現。"},{"en":"The phrase points to a specific mention in a text.","zh":"這個短語指文本中的具體提及。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":17},{"front":"irregular movement of particles","meaning":"微粒的不規則移動","examples":[{"en":"The paragraph describes the irregular movement of particles.","zh":"該段描述微粒的不規則移動。"},{"en":"Irregular movement of particles means particles moving in an uneven or unpredictable way.","zh":"「irregular movement of particles」意思是微粒以不均勻或難以預測的方式移動。"},{"en":"Dust in sunlight may show irregular movement when air flows through a room.","zh":"當空氣穿過房間，陽光中的塵埃可能顯示不規則移動。"},{"en":"If particles bounce, fall, and rise again, their movement is not smooth.","zh":"如果微粒彈起、落下又再升起，其移動就不是平滑的。"},{"en":"The phrase describes uneven physical motion.","zh":"這個短語描述不均勻的物理運動。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":17},{"front":"mention of","meaning":"提到……","examples":[{"en":"The question asks for mention of productive land turning into a desert.","zh":"問題要求找出提到有生產力土地變成沙漠的地方。"},{"en":"Mention of something means a place where it is referred to or talked about.","zh":"「mention of」某事，意思是提及或談到它的地方。"},{"en":"A news article may make mention of school closures after a storm.","zh":"新聞文章可能提到風暴後學校停課。"},{"en":"If a question asks for mention of an idea, students should locate where it appears.","zh":"如果問題要求找出提到某想法之處，學生應定位它出現的位置。"},{"en":"The phrase is useful in reading-location questions.","zh":"這個短語常用於閱讀定位題。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":17},{"front":"productive land","meaning":"有生產力的土地","examples":[{"en":"Productive land can turn into desert under certain conditions.","zh":"在某些條件下，有生產力的土地可以變成沙漠。"},{"en":"Productive land is land that can grow crops or support useful vegetation.","zh":"「productive land」是能種植作物或支持有用植被的土地。"},{"en":"A farm with healthy soil and enough water is productive land.","zh":"有健康土壤和足夠水分的農場是有生產力的土地。"},{"en":"If productive land loses topsoil, it may become barren.","zh":"如果有生產力的土地失去表土，它可能變得荒蕪。"},{"en":"The phrase describes land that can produce food or resources.","zh":"這個短語描述能生產食物或資源的土地。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":17},{"front":"turn into a desert","meaning":"變成沙漠","examples":[{"en":"A productive area of farmland may turn into a desert.","zh":"一片有生產力的農地可能變成沙漠。"},{"en":"To turn into a desert means to become dry, barren, and unable to support normal plant growth.","zh":"「turn into a desert」意思是變得乾旱、荒蕪，無法支持正常植物生長。"},{"en":"A field may turn into a desert-like area if overused for many years.","zh":"如果田地多年被過度使用，它可能變成沙漠般的地區。"},{"en":"If soil, water, and vegetation are lost, farmland may become desert.","zh":"如果土壤、水和植被流失，農地可能變成沙漠。"},{"en":"The phrase describes a serious environmental change.","zh":"這個短語描述嚴重環境變化。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":17},{"front":"types of deserts","meaning":"沙漠類型","examples":[{"en":"The passage describes different types of deserts.","zh":"文章描述不同沙漠類型。"},{"en":"Types of deserts are categories of deserts based on climate, rainfall, temperature, or location.","zh":"「types of deserts」是根據氣候、降雨、氣溫或位置劃分的沙漠類別。"},{"en":"Students may learn about hot deserts and cold deserts in geography class.","zh":"學生可能在地理課學習熱沙漠和寒冷沙漠。"},{"en":"If deserts are classified by different factors, several types may be identified.","zh":"如果沙漠按不同因素分類，就可以識別幾種類型。"},{"en":"The phrase shows that not all deserts are the same.","zh":"這個短語顯示並非所有沙漠都相同。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":17},{"front":"technological methods","meaning":"科技方法","examples":[{"en":"Technological methods are used to address desertification.","zh":"科技方法被用來處理沙漠化。"},{"en":"Technological methods are practical ways of using technology to solve a problem.","zh":"「technological methods」是使用科技解決問題的實際方法。"},{"en":"Schools use technological methods such as online quizzes to track progress.","zh":"學校使用網上測驗等科技方法追蹤進度。"},{"en":"If satellite images reveal land damage, technology can guide prevention work.","zh":"如果衛星影像揭示土地破壞，科技可以指導預防工作。"},{"en":"The phrase describes solution methods based on tools or systems.","zh":"這個短語描述基於工具或系統的解決方法。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":17},{"front":"traditional livestock-grazing practices","meaning":"傳統牲畜放牧做法","examples":[{"en":"Traditional livestock-grazing practices can influence desertification.","zh":"傳統牲畜放牧做法可以影響沙漠化。"},{"en":"Traditional livestock-grazing practices are long-used ways of moving and feeding animals on pasture.","zh":"「traditional livestock-grazing practices」是長久以來移動和餵養牲畜於牧草地的方法。"},{"en":"Nomads may use traditional grazing practices to find grass in dry seasons.","zh":"遊牧民族可能使用傳統放牧做法在旱季尋找草地。"},{"en":"If grazing patterns become too intense, traditional practices may still damage land.","zh":"如果放牧模式變得過於密集，傳統做法仍可能破壞土地。"},{"en":"The phrase connects old animal-management methods with environmental impact.","zh":"這個短語把舊有牲畜管理方法與環境影響連繫起來。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":18},{"front":"a lack of agreement among scientists","meaning":"科學家之間缺乏共識","examples":[{"en":"There is a lack of agreement among scientists about the causes of desertification.","zh":"科學家之間對沙漠化成因缺乏共識。"},{"en":"A lack of agreement among scientists means experts do not share one clear view.","zh":"「a lack of agreement among scientists」意思是專家沒有共同清楚看法。"},{"en":"There may be a lack of agreement among doctors about a difficult diagnosis.","zh":"醫生之間可能對困難診斷缺乏共識。"},{"en":"If scientists disagree, the problem is probably complex or evidence is incomplete.","zh":"如果科學家意見不同，問題可能複雜或證據不完整。"},{"en":"The phrase describes expert disagreement.","zh":"這個短語描述專家分歧。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":18},{"front":"causes of desertification","meaning":"沙漠化的成因","examples":[{"en":"The causes of desertification are still debated.","zh":"沙漠化的成因仍有爭議。"},{"en":"Causes of desertification are the factors that make land become desert-like.","zh":"「causes of desertification」是令土地變得像沙漠的因素。"},{"en":"Overgrazing, deforestation, poor farming, and drought may all be discussed as causes.","zh":"過度放牧、砍伐森林、不良耕作和乾旱都可能被討論為成因。"},{"en":"If causes are identified correctly, prevention can target the real problem.","zh":"如果成因被正確識別，預防就能針對真正問題。"},{"en":"The phrase focuses on why desertification happens.","zh":"這個短語集中於沙漠化為何發生。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":18},{"front":"a description of","meaning":"對……的描述","examples":[{"en":"The question asks for a description of the adverse effects of growing crops.","zh":"問題要求找出對種植農作物不良影響的描述。"},{"en":"A description of something is an explanation of what it is like or what happens.","zh":"「a description of」某事，是解釋它是甚麼樣子或發生甚麼。"},{"en":"A report may include a description of how a river floods after heavy rain.","zh":"報告可能包括對大雨後河流如何泛濫的描述。"},{"en":"If a question asks for a description, students should find details, not just a keyword.","zh":"如果問題要求描述，學生應尋找細節，而不只是關鍵字。"},{"en":"The phrase points to explanatory information.","zh":"這個短語指向解釋性資料。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":18},{"front":"adverse effects","meaning":"不良影響","examples":[{"en":"Growing crops in dry areas can have adverse effects.","zh":"在乾旱地區種植農作物可以有不良影響。"},{"en":"Adverse effects are harmful or negative results.","zh":"「adverse effects」是有害或負面的結果。"},{"en":"Too much screen time can have adverse effects on sleep.","zh":"太多屏幕時間可以對睡眠有不良影響。"},{"en":"If farming removes plant cover, adverse effects may include erosion and soil loss.","zh":"如果耕作移除植被覆蓋，不良影響可能包括侵蝕和土壤流失。"},{"en":"The phrase describes unwanted consequences.","zh":"這個短語描述不想要的後果。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":18},{"front":"growing food crops","meaning":"種植糧食作物","examples":[{"en":"Growing food crops can remove natural vegetation cover.","zh":"種植糧食作物可以移除天然植被覆蓋。"},{"en":"Growing food crops means cultivating plants that people eat.","zh":"「growing food crops」意思是栽培人類食用的植物。"},{"en":"A farmer may grow food crops such as wheat, rice, or vegetables.","zh":"農民可能種植小麥、稻米或蔬菜等糧食作物。"},{"en":"If food crops are grown in dry areas, natural plants may first be cleared.","zh":"如果在乾旱地區種植糧食作物，天然植物可能先被清除。"},{"en":"The phrase refers to farming for food production.","zh":"這個短語指為食物生產而耕作。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":18},{"front":"agree with the information given in","meaning":"與……提供的資料一致","examples":[{"en":"Students decide whether the statements agree with the information given in the passage.","zh":"學生判斷陳述是否與篇章提供的資料一致。"},{"en":"To agree with the information given in a passage means to match what the text says.","zh":"「agree with the information given in」篇章，意思是符合文本所說。"},{"en":"In reading tests, students choose TRUE only when the passage clearly supports the statement.","zh":"在閱讀測驗中，只有文章清楚支持陳述時，學生才選 TRUE。"},{"en":"If a statement adds an idea not in the text, it may not agree with the information.","zh":"如果陳述加入文本沒有的想法，它可能不與資料一致。"},{"en":"The phrase reminds students to use evidence from the passage.","zh":"這個短語提醒學生使用篇章證據。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":18},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與篇章資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"「contradict the information」意思是說出與文本所說相反的內容。"},{"en":"If a notice says the library closes at six, saying it closes at eight contradicts the information.","zh":"如果通告說圖書館六時關門，說它八時關門就與資料矛盾。"},{"en":"If a statement contradicts the passage, the answer should be FALSE.","zh":"如果陳述與篇章矛盾，答案應是 FALSE。"},{"en":"The phrase describes a clear conflict with the text.","zh":"這個短語描述與文本的清楚衝突。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":18},{"front":"there is no information on this","meaning":"沒有關於這方面的資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有關於這方面的資料，學生寫 NOT GIVEN。"},{"en":"There is no information on this means the text does not say whether it is true or false.","zh":"「there is no information on this」意思是文本沒有說它是真還是假。"},{"en":"If a passage never mentions a writer’s age, there is no information on it.","zh":"如果文章從未提到作者年齡，就沒有關於這方面的資料。"},{"en":"If evidence is missing, students should not guess from background knowledge.","zh":"如果缺乏證據，學生不應憑背景知識猜測。"},{"en":"The phrase is important for TRUE/FALSE/NOT GIVEN tasks.","zh":"這個短語對 TRUE/FALSE/NOT GIVEN 題很重要。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":18},{"front":"difficult to ascertain","meaning":"難以確定","examples":[{"en":"It is difficult to ascertain where deserts end in some areas.","zh":"在某些地區，沙漠在哪裏結束是難以確定的。"},{"en":"Difficult to ascertain means hard to find out or determine clearly.","zh":"「difficult to ascertain」意思是難以查明或清楚判定。"},{"en":"It may be difficult to ascertain why a student’s marks suddenly dropped.","zh":"學生成績突然下降的原因可能難以確定。"},{"en":"If desert borders are gradual, their exact end point is hard to identify.","zh":"如果沙漠邊界是逐漸過渡，其確切終點就難以辨認。"},{"en":"The phrase is formal and means “hard to determine”.","zh":"這個短語較正式，意思是「難以判定」。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":18},{"front":"where the deserts end","meaning":"沙漠在哪裏結束","examples":[{"en":"It can be difficult to ascertain where the deserts end.","zh":"沙漠在哪裏結束可能難以確定。"},{"en":"Where the deserts end means the place where desert land stops and another landscape begins.","zh":"「where the deserts end」意思是沙漠土地停止、另一地貌開始的地方。"},{"en":"On some maps, it is hard to show exactly where a forest ends.","zh":"在一些地圖上，很難準確顯示森林在哪裏結束。"},{"en":"If dry land changes gradually into grassland, desert edges become unclear.","zh":"如果乾地逐漸變成草地，沙漠邊緣就變得不清楚。"},{"en":"The phrase asks about the boundary of deserts.","zh":"這個短語詢問沙漠邊界位置。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":18},{"front":"in some areas","meaning":"在某些地區","examples":[{"en":"In some areas, deserts do not have clear-cut borders.","zh":"在某些地區，沙漠沒有清晰明確的邊界。"},{"en":"In some areas means in certain places, but not everywhere.","zh":"「in some areas」意思是在某些地方，但不是所有地方。"},{"en":"In some areas, students walk to school because buses are rare.","zh":"在某些地區，學生步行上學，因為巴士很少。"},{"en":"If a statement says “in some areas”, it should not be treated as universal.","zh":"如果陳述說 “in some areas”，就不應把它視為普遍情況。"},{"en":"The phrase limits the statement to particular places.","zh":"這個短語把說法限制在特定地點。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":19},{"front":"be uninterested in","meaning":"對……不感興趣","examples":[{"en":"The statement claims that the media are uninterested in desertification.","zh":"該陳述聲稱媒體對沙漠化不感興趣。"},{"en":"To be uninterested in something means to have little or no concern about it.","zh":"「be uninterested in」某事，意思是對它幾乎沒有關心或興趣。"},{"en":"A student may be uninterested in history until a teacher tells a personal story.","zh":"學生可能對歷史不感興趣，直到老師講述個人故事。"},{"en":"If the media report a problem widely, they are not uninterested in it.","zh":"如果媒體廣泛報道某問題，它們就不是對該問題不感興趣。"},{"en":"The phrase describes lack of interest or attention.","zh":"這個短語描述缺乏興趣或關注。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":19},{"front":"the problems of desertification","meaning":"沙漠化問題","examples":[{"en":"The media have reported the problems of desertification.","zh":"媒體已報道沙漠化問題。"},{"en":"The problems of desertification are the harmful effects caused by land becoming desert-like.","zh":"「the problems of desertification」是土地變得像沙漠所造成的有害影響。"},{"en":"These problems may include crop failure, poverty, migration, and dust storms.","zh":"這些問題可能包括農作物失收、貧窮、遷移和沙塵暴。"},{"en":"If the problems are publicised, governments may act sooner.","zh":"如果這些問題受到宣傳，政府可能更早行動。"},{"en":"The phrase focuses on the damage desertification creates.","zh":"這個短語集中於沙漠化造成的破壞。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":19},{"front":"the most common cause of","meaning":"……最常見的原因","examples":[{"en":"The statement asks about the most common cause of desertification.","zh":"該陳述問沙漠化最常見的原因。"},{"en":"The most common cause of something is the reason that happens most often.","zh":"「the most common cause of」某事，是最常出現的原因。"},{"en":"The most common cause of lateness may be traffic near the school.","zh":"遲到最常見的原因可能是學校附近交通擠塞。"},{"en":"If the most common cause is human activity, solutions must address human behaviour.","zh":"如果最常見原因是人類活動，解決方法必須處理人類行為。"},{"en":"The phrase asks for the most frequent reason.","zh":"這個短語詢問最頻繁的原因。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":19},{"front":"the lack of rainfall","meaning":"降雨不足","examples":[{"en":"The lack of rainfall is often misunderstood as the main cause of desertification.","zh":"降雨不足常被誤解為沙漠化的主要原因。"},{"en":"The lack of rainfall means not having enough rain.","zh":"「the lack of rainfall」意思是沒有足夠降雨。"},{"en":"A garden may dry out quickly because of a lack of rainfall.","zh":"花園可能因降雨不足而很快變乾。"},{"en":"If people blame only rainfall, they may ignore overgrazing and deforestation.","zh":"如果人們只責怪降雨，他們可能忽略過度放牧和砍伐森林。"},{"en":"The phrase describes a shortage of rain, not necessarily the full cause.","zh":"這個短語描述雨水不足，但不一定是完整原因。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":19},{"front":"increase soil erosion","meaning":"增加土壤侵蝕","examples":[{"en":"Raising livestock in semi-arid areas can increase soil erosion.","zh":"在半乾旱地區飼養牲畜可以增加土壤侵蝕。"},{"en":"To increase soil erosion means to make soil loss happen more often or more severely.","zh":"「increase soil erosion」意思是令土壤流失更常發生或更嚴重。"},{"en":"Removing grass from a slope can increase soil erosion after rain.","zh":"移除斜坡上的草可以在雨後增加土壤侵蝕。"},{"en":"If animals trample dry ground, loose soil can be removed more easily.","zh":"如果動物踐踏乾地，鬆散土壤會更容易被移走。"},{"en":"The phrase describes worsening soil loss.","zh":"這個短語描述土壤流失惡化。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":19},{"front":"no longer use","meaning":"不再使用","examples":[{"en":"The statement claims that people no longer use firewood as the chief fuel.","zh":"該陳述聲稱人們不再使用柴枝作為主要燃料。"},{"en":"No longer use means used something before but do not use it now.","zh":"「no longer use」意思是以前使用某物，但現在不再使用。"},{"en":"Many students no longer use paper dictionaries because they use apps.","zh":"許多學生不再使用紙本字典，因為他們使用應用程式。"},{"en":"If people still rely on firewood, it is wrong to say they no longer use it.","zh":"如果人們仍依賴柴枝，說他們不再使用它就是錯誤的。"},{"en":"The phrase describes a change from past use to present non-use.","zh":"這個短語描述從過去使用轉為現在不使用。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":19},{"front":"as the chief fuel","meaning":"作為主要燃料","examples":[{"en":"Firewood is used as the chief fuel in many Asian countries.","zh":"在許多亞洲國家，柴枝被用作主要燃料。"},{"en":"As the chief fuel means as the main energy source.","zh":"「as the chief fuel」意思是作為主要能源來源。"},{"en":"Some homes use electricity as the chief fuel for cooking.","zh":"有些家庭使用電力作為煮食的主要能源。"},{"en":"If firewood is used as the chief fuel, tree cutting may increase.","zh":"如果柴枝被用作主要燃料，砍樹可能增加。"},{"en":"The phrase identifies the main fuel role.","zh":"這個短語指出主要燃料角色。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":19},{"front":"technology for studying","meaning":"用於研究……的科技","examples":[{"en":"Technology for studying desertification has already been developed.","zh":"用於研究沙漠化的科技已經被開發。"},{"en":"Technology for studying something means tools used to investigate or measure it.","zh":"「technology for studying」某事，意思是用於調查或測量它的工具。"},{"en":"Scientists use technology for studying storms, oceans, and forests.","zh":"科學家使用科技研究風暴、海洋和森林。"},{"en":"If technology exists, researchers can collect more accurate information.","zh":"如果科技存在，研究人員就能收集更準確資料。"},{"en":"The phrase describes research tools.","zh":"這個短語描述研究工具。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":19},{"front":"the effects of people and livestock on","meaning":"人類和牲畜對……的影響","examples":[{"en":"Satellites study the effects of people and livestock on desertification.","zh":"衛星研究人類和牲畜對沙漠化的影響。"},{"en":"The effects of people and livestock on something are the changes caused by human activity and animals.","zh":"「the effects of people and livestock on」某事，是人類活動和動物造成的變化。"},{"en":"A park manager may study the effects of visitors and dogs on grassland.","zh":"公園管理員可能研究遊客和狗對草地的影響。"},{"en":"If people and livestock damage vegetation, their effects may appear in satellite images.","zh":"如果人類和牲畜破壞植被，其影響可能出現在衛星影像中。"},{"en":"The phrase focuses on impact caused by humans and animals.","zh":"這個短語集中於人類和動物造成的影響。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":19},{"front":"has not yet been developed","meaning":"尚未被開發","examples":[{"en":"The statement claims that this technology has not yet been developed.","zh":"該陳述聲稱這項科技尚未被開發。"},{"en":"Has not yet been developed means does not exist or has not been created so far.","zh":"「has not yet been developed」意思是到目前為止仍不存在或尚未被創造。"},{"en":"A school may say a new app has not yet been developed if it is still only an idea.","zh":"如果新應用程式仍只是想法，學校可能說它尚未被開發。"},{"en":"If technology has already been used, it is wrong to say it has not yet been developed.","zh":"如果科技已經被使用，說它尚未被開發就是錯誤的。"},{"en":"The phrase describes something that is still unavailable.","zh":"這個短語描述某物仍未可用。"}],"source":"56 - How are deserts formed?.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 57":[{"front":"larger enterprises","meaning":"較大型企業","examples":[{"en":"Several Italian car makers were bought by larger enterprises.","zh":"幾間意大利汽車製造商被較大型企業收購。"},{"en":"Larger enterprises are bigger companies or business groups with more money, staff, and market power.","zh":"較大型企業是擁有更多資金、員工和市場力量的大公司或商業集團。"},{"en":"A small bakery may be bought by a larger enterprise that owns shops across the country.","zh":"小型麵包店可能被一間在全國擁有店舖的較大型企業收購。"},{"en":"If larger enterprises buy niche brands, those brands may gain funding but lose some independence.","zh":"如果較大型企業收購小眾品牌，那些品牌可能得到資金，但失去部分獨立性。"},{"en":"The phrase contrasts small specialist firms with bigger corporate organisations.","zh":"這個短語把小型專門公司與較大型企業組織作對比。"}],"source":"57 - The automobile’s history.pdf","sourcePage":1},{"front":"by the end of","meaning":"到……結束時","examples":[{"en":"By the end of the 20th century, fewer automobile marques remained.","zh":"到20世紀結束時，留下的汽車品牌較少。"},{"en":"By the end of a period means when that period was finished or almost finished.","zh":"“By the end of” 某時期指到該時期完成或接近完成時。"},{"en":"By the end of the school year, most students had completed their reading projects.","zh":"到學年結束時，大多數學生已完成閱讀項目。"},{"en":"If a market changes by the end of a century, the change has taken place over a long period.","zh":"如果市場到一個世紀結束時改變，該變化就是經過長時間發生的。"},{"en":"The phrase gives a time limit for measuring a result.","zh":"這個短語給出衡量結果的時間界限。"}],"source":"57 - The automobile’s history.pdf","sourcePage":1},{"front":"a sharp fall in","meaning":"……急劇下降","examples":[{"en":"There was a sharp fall in the number of automobile marques.","zh":"汽車品牌數目急劇下降。"},{"en":"A sharp fall in something means a large and sudden decrease.","zh":"“A sharp fall in” 某事指大幅而突然下降。"},{"en":"A shop may see a sharp fall in customers after a new mall opens nearby.","zh":"新商場在附近開業後，小店顧客數目可能急劇下降。"},{"en":"If there is a sharp fall in the number of brands, the market becomes less diverse.","zh":"如果品牌數目急劇下降，市場就變得較少元。"},{"en":"The phrase stresses a strong downward change.","zh":"這個短語強調強烈向下變化。"}],"source":"57 - The automobile’s history.pdf","sourcePage":1},{"front":"the number of automobile marques","meaning":"汽車品牌數目","examples":[{"en":"The number of automobile marques fell sharply by the end of the century.","zh":"到世紀結束時，汽車品牌數目急劇下降。"},{"en":"The number of automobile marques means how many separate car brands existed.","zh":"汽車品牌數目指存在多少個獨立汽車品牌。"},{"en":"A car historian may compare the number of marques before and after corporate mergers.","zh":"汽車歷史學者可能比較企業合併前後的品牌數目。"},{"en":"If the number of automobile marques falls, consumers may have fewer independent brands to choose from.","zh":"如果汽車品牌數目下降，消費者可選擇的獨立品牌可能較少。"},{"en":"The phrase focuses on brand count in the car industry.","zh":"這個短語強調汽車業中的品牌數量。"}],"source":"57 - The automobile’s history.pdf","sourcePage":1},{"front":"car performance","meaning":"汽車性能","examples":[{"en":"In the US, car performance dominated marketing.","zh":"在美國，汽車性能主導市場推廣。"},{"en":"Car performance means how well a car accelerates, handles, brakes, and drives overall.","zh":"汽車性能指汽車加速、操控、煞車和整體駕駛表現有多好。"},{"en":"A buyer who cares about car performance may compare engine power, speed, and road handling.","zh":"重視汽車性能的買家可能比較引擎動力、速度和路面操控。"},{"en":"If car performance becomes the main selling point, advertising may focus on power and excitement.","zh":"如果汽車性能成為主要賣點，廣告可能集中於動力和刺激感。"},{"en":"The phrase refers to how a car performs, not only how it looks.","zh":"這個短語指汽車表現，而不只是外觀。"}],"source":"57 - The automobile’s history.pdf","sourcePage":1},{"front":"dominate marketing","meaning":"主導市場推廣","examples":[{"en":"Car performance dominated marketing in the US.","zh":"汽車性能在美國主導市場推廣。"},{"en":"To dominate marketing means to be the main idea or feature used in advertising and selling.","zh":"“Dominate marketing” 指成為廣告和銷售中使用的主要概念或特點。"},{"en":"Low prices may dominate marketing when shops compete during a holiday sale.","zh":"商店在假期促銷競爭時，低價可能主導市場推廣。"},{"en":"If performance dominates car marketing, other qualities like fuel economy may receive less attention.","zh":"如果性能主導汽車市場推廣，燃油效益等其他品質可能得到較少關注。"},{"en":"The phrase describes what controls the message in promotion.","zh":"這個短語描述宣傳訊息由甚麼主導。"}],"source":"57 - The automobile’s history.pdf","sourcePage":1},{"front":"as exemplified by","meaning":"以……為例","examples":[{"en":"This trend was exemplified by pony cars and muscle cars.","zh":"這個趨勢以小型運動車和肌肉車為例。"},{"en":"As exemplified by means as clearly shown by a particular example.","zh":"“As exemplified by” 指由某個具體例子清楚顯示。"},{"en":"Student stress is often visible before exams, as exemplified by late-night study and tired faces.","zh":"學生壓力常在考試前可見，以深夜溫習和疲倦臉容為例。"},{"en":"If a trend is exemplified by famous products, those products clearly show the trend in action.","zh":"如果某趨勢由著名產品作例子，那些產品就清楚顯示該趨勢如何運作。"},{"en":"The phrase introduces evidence through examples.","zh":"這個短語透過例子引出證據。"}],"source":"57 - The automobile’s history.pdf","sourcePage":1},{"front":"pony cars","meaning":"小型運動車","examples":[{"en":"Pony cars showed the importance of performance in American marketing.","zh":"小型運動車顯示性能在美國市場推廣中的重要性。"},{"en":"Pony cars are compact, sporty American cars designed to look exciting and perform strongly.","zh":"小型運動車是設計得富動感、外形刺激且性能強的美式緊湊型運動車。"},{"en":"A buyer choosing a pony car may care more about style and acceleration than rear-seat space.","zh":"選擇小型運動車的買家可能比起後座空間，更重視風格和加速。"},{"en":"If pony cars become popular, car makers may advertise youth, speed, and freedom.","zh":"如果小型運動車受歡迎，汽車製造商可能宣傳青春、速度和自由。"},{"en":"The phrase names a type of sporty American car.","zh":"這個短語指一類美式運動車。"}],"source":"57 - The automobile’s history.pdf","sourcePage":1},{"front":"muscle cars","meaning":"肌肉車","examples":[{"en":"Muscle cars became symbols of American car performance.","zh":"肌肉車成為美國汽車性能的象徵。"},{"en":"Muscle cars are powerful cars, often American, built with large engines and strong acceleration.","zh":"肌肉車是動力強大的汽車，通常是美式車，配有大型引擎和強勁加速。"},{"en":"A driver who likes engine noise and straight-line speed may be attracted to muscle cars.","zh":"喜歡引擎聲和直線速度的司機可能被肌肉車吸引。"},{"en":"If muscle cars dominate advertising, fuel economy may seem less important than power.","zh":"如果肌肉車主導廣告，燃油效益可能顯得不如動力重要。"},{"en":"The phrase suggests strength, speed, and a bold car image.","zh":"這個短語暗示力量、速度和大膽的汽車形象。"}],"source":"57 - The automobile’s history.pdf","sourcePage":1},{"front":"everything changed","meaning":"一切都改變了","examples":[{"en":"In the 1970s, everything changed for the American automobile industry.","zh":"在1970年代，美國汽車工業的一切都改變了。"},{"en":"Everything changed means the whole situation became very different.","zh":"“Everything changed” 指整個情況變得非常不同。"},{"en":"When a new principal arrived, everything changed in the school’s daily routine.","zh":"新校長到任後，學校日常運作一切都改變了。"},{"en":"If fuel prices rise suddenly, everything can change for drivers and car makers.","zh":"如果燃油價格突然上升，司機和汽車製造商的一切都可能改變。"},{"en":"The phrase signals a major turning point.","zh":"這個短語表示重大轉捩點。"}],"source":"57 - The automobile’s history.pdf","sourcePage":1},{"front":"suffer from","meaning":"受……打擊；遭受","examples":[{"en":"The American automobile industry suffered from the 1973 oil crisis.","zh":"美國汽車工業受到1973年石油危機打擊。"},{"en":"To suffer from something means to be harmed or negatively affected by it.","zh":"“Suffer from” 某事指受到它傷害或負面影響。"},{"en":"A student may suffer from headaches if they sleep too little.","zh":"如果學生睡得太少，可能受頭痛之苦。"},{"en":"If an industry suffers from a crisis, sales, jobs, and confidence may fall.","zh":"如果行業受危機打擊，銷量、職位和信心可能下降。"},{"en":"The phrase describes damage caused by a problem.","zh":"這個短語描述由問題造成的損害。"}],"source":"57 - The automobile’s history.pdf","sourcePage":1},{"front":"the 1973 oil crisis","meaning":"1973年石油危機","examples":[{"en":"The 1973 oil crisis hurt the American automobile industry.","zh":"1973年石油危機傷害了美國汽車工業。"},{"en":"The 1973 oil crisis was a period when oil supply problems and high prices shocked many economies.","zh":"1973年石油危機是一段石油供應問題和高油價衝擊許多經濟體的時期。"},{"en":"During an oil crisis, drivers may avoid large cars because fuel becomes expensive.","zh":"在石油危機期間，司機可能避免大型車，因為燃油變得昂貴。"},{"en":"If an industry depends on cheap petrol, an oil crisis can expose its weakness.","zh":"如果一個行業依賴廉價汽油，石油危機就可以暴露其弱點。"},{"en":"The phrase refers to a major historical energy shock.","zh":"這個短語指重大歷史能源衝擊。"}],"source":"57 - The automobile’s history.pdf","sourcePage":2},{"front":"competition with imports","meaning":"與進口貨競爭","examples":[{"en":"American car makers faced competition with Japanese and European imports.","zh":"美國汽車製造商面對與日本和歐洲進口車的競爭。"},{"en":"Competition with imports means rivalry with goods made in other countries and brought into the market.","zh":"“Competition with imports” 指與在其他國家製造並進入市場的貨品競爭。"},{"en":"Local farmers may face competition with imported fruit if imports are cheaper.","zh":"如果進口水果較便宜，本地農民可能面對與進口水果的競爭。"},{"en":"If imported cars are efficient and affordable, domestic car makers may lose customers.","zh":"如果進口車高效又價格相宜，本土汽車製造商可能失去顧客。"},{"en":"The phrase describes market pressure from foreign products.","zh":"這個短語描述來自外國產品的市場壓力。"}],"source":"57 - The automobile’s history.pdf","sourcePage":2},{"front":"Japanese and European imports","meaning":"日本和歐洲進口車","examples":[{"en":"Japanese and European imports challenged the American automobile industry.","zh":"日本和歐洲進口車挑戰了美國汽車工業。"},{"en":"Japanese and European imports are cars or products made in Japan and Europe and sold in another country.","zh":"日本和歐洲進口車是在日本和歐洲製造並在另一個國家銷售的汽車或產品。"},{"en":"A buyer may choose Japanese and European imports because of reliability, design, or fuel economy.","zh":"買家可能因可靠性、設計或燃油效益選擇日本和歐洲進口車。"},{"en":"If imports offer better value, local companies must improve to compete.","zh":"如果進口車提供更好價值，本地公司就必須改善以競爭。"},{"en":"The phrase identifies foreign products entering a domestic market.","zh":"這個短語指出進入本土市場的外國產品。"}],"source":"57 - The automobile’s history.pdf","sourcePage":2},{"front":"emission-control regulations","meaning":"排放管制規例","examples":[{"en":"Emission-control regulations affected the American automobile industry.","zh":"排放管制規例影響了美國汽車工業。"},{"en":"Emission-control regulations are rules that limit the pollution vehicles or factories can release.","zh":"排放管制規例是限制車輛或工廠可排放污染的規則。"},{"en":"A car maker may need new technology to meet stricter emission-control regulations.","zh":"汽車製造商可能需要新科技來符合更嚴格的排放管制規例。"},{"en":"If regulations become tougher, older engine designs may no longer be acceptable.","zh":"如果規例變得更嚴格，舊引擎設計可能不再可接受。"},{"en":"The phrase connects environmental law with industrial design.","zh":"這個短語把環境法律與工業設計連繫起來。"}],"source":"57 - The automobile’s history.pdf","sourcePage":2},{"front":"a lack of innovation","meaning":"缺乏創新","examples":[{"en":"A lack of innovation hurt the American automobile industry.","zh":"缺乏創新傷害了美國汽車工業。"},{"en":"A lack of innovation means not producing enough new ideas, designs, or improvements.","zh":"缺乏創新指沒有產生足夠的新想法、設計或改善。"},{"en":"A school may suffer from a lack of innovation if lessons stay the same for twenty years.","zh":"如果課堂二十年不變，學校可能受缺乏創新影響。"},{"en":"If companies fail to innovate, competitors with better products may overtake them.","zh":"如果公司未能創新，產品更好的競爭者可能超越它們。"},{"en":"The phrase describes weakness caused by not changing or improving.","zh":"這個短語描述因不改變或不改善而造成的弱點。"}],"source":"57 - The automobile’s history.pdf","sourcePage":2},{"front":"the irony in all this","meaning":"其中諷刺的是","examples":[{"en":"The irony in all this was that some full-size sedans became popular again.","zh":"其中諷刺的是，一些全尺寸房車再次流行起來。"},{"en":"The irony in all this means the surprising or unexpected contrast in the situation.","zh":"“The irony in all this” 指情況中令人意外或出乎預料的對比。"},{"en":"The irony in a busy gym is that some people drive there only to walk on a treadmill.","zh":"忙碌健身室中的諷刺之處，是有些人開車到那裡，只為在跑步機上步行。"},{"en":"If large cars return during an economic crisis, that result feels unexpected and ironic.","zh":"如果大型車在經濟危機期間回歸，這個結果就令人意外且帶諷刺意味。"},{"en":"The phrase introduces a surprising twist.","zh":"這個短語引出令人意外的轉折。"}],"source":"57 - The automobile’s history.pdf","sourcePage":2},{"front":"full-size sedans","meaning":"全尺寸房車","examples":[{"en":"Full-size sedans such as Cadillac and Lincoln made a comeback.","zh":"Cadillac 和 Lincoln 等全尺寸房車強勢回歸。"},{"en":"Full-size sedans are large passenger cars with separate spaces for engine, passengers, and luggage.","zh":"全尺寸房車是大型乘用車，通常有分開的引擎、乘客和行李空間。"},{"en":"A family may choose a full-size sedan for comfort on long journeys.","zh":"家庭可能為長途旅程的舒適而選擇全尺寸房車。"},{"en":"If fuel prices are high, full-size sedans may become less attractive because they often use more petrol.","zh":"如果燃油價格高，全尺寸房車可能較不吸引，因為它們通常耗油較多。"},{"en":"The phrase refers to large traditional passenger cars.","zh":"這個短語指大型傳統乘用車。"}],"source":"57 - The automobile’s history.pdf","sourcePage":2},{"front":"make a huge comeback","meaning":"強勢回歸","examples":[{"en":"Cadillac and Lincoln made a huge comeback during the economic crisis.","zh":"Cadillac 和 Lincoln 在經濟危機期間強勢回歸。"},{"en":"To make a huge comeback means to become popular or successful again after declining.","zh":"“Make a huge comeback” 指在衰落後再次變得受歡迎或成功。"},{"en":"Vinyl records made a comeback when young listeners became interested in old sound quality.","zh":"當年輕聽眾對舊式音質感興趣時，黑膠唱片強勢回歸。"},{"en":"If a product returns strongly after poor sales, its comeback can surprise the market.","zh":"如果產品在銷量差後強力回歸，其回歸可以令市場驚訝。"},{"en":"The phrase describes a strong return to success.","zh":"這個短語描述強勢重返成功。"}],"source":"57 - The automobile’s history.pdf","sourcePage":2},{"front":"economic crisis","meaning":"經濟危機","examples":[{"en":"Some full-size sedans sold well during the economic crisis.","zh":"一些全尺寸房車在經濟危機期間賣得很好。"},{"en":"An economic crisis is a serious period of financial difficulty affecting businesses, workers, and consumers.","zh":"經濟危機是影響企業、工人和消費者的嚴重財政困難時期。"},{"en":"During an economic crisis, families may delay buying expensive goods.","zh":"在經濟危機期間，家庭可能延遲購買昂貴物品。"},{"en":"If a car sells well during a crisis, its popularity is especially surprising.","zh":"如果汽車在危機期間賣得好，其受歡迎程度尤其令人驚訝。"},{"en":"The phrase describes a period of major economic stress.","zh":"這個短語描述重大經濟壓力時期。"}],"source":"57 - The automobile’s history.pdf","sourcePage":2},{"front":"on the technology front","meaning":"在技術層面上","examples":[{"en":"On the technology front, several important developments appeared after the war.","zh":"在技術層面上，戰後出現了幾項重要發展。"},{"en":"On the technology front means regarding technological progress or technical development.","zh":"“On the technology front” 指在科技進步或技術發展方面。"},{"en":"On the technology front, schools now use online platforms, smart boards, and digital homework.","zh":"在技術層面上，學校現在使用網上平台、智能白板和數碼功課。"},{"en":"If progress happens on the technology front, products may become safer, faster, or more efficient.","zh":"如果技術層面有進展，產品可能變得更安全、更快速或更高效。"},{"en":"The phrase shifts attention to technical changes.","zh":"這個短語把注意力轉向技術變化。"}],"source":"57 - The automobile’s history.pdf","sourcePage":2},{"front":"the post-war era","meaning":"戰後時代","examples":[{"en":"The post-war era brought important automobile developments.","zh":"戰後時代帶來重要汽車發展。"},{"en":"The post-war era means the period after a major war has ended.","zh":"戰後時代指重大戰爭結束後的時期。"},{"en":"In the post-war era, countries often rebuild industries, transport, and housing.","zh":"在戰後時代，國家通常重建工業、交通和住房。"},{"en":"If technology improves in the post-war era, wartime research may have influenced civilian products.","zh":"如果技術在戰後時代改善，戰時研究可能影響民用產品。"},{"en":"The phrase gives a historical period after war.","zh":"這個短語給出戰爭後的歷史時期。"}],"source":"57 - The automobile’s history.pdf","sourcePage":2},{"front":"widespread use of","meaning":"……的廣泛使用","examples":[{"en":"The post-war era saw the widespread use of independent suspension.","zh":"戰後時代見證了獨立懸掛系統的廣泛使用。"},{"en":"Widespread use of something means it is used by many people, companies, or places.","zh":"“Widespread use of” 某物指它被許多人、公司或地方使用。"},{"en":"The widespread use of smartphones changed how students communicate with teachers.","zh":"智能手機的廣泛使用改變了學生與老師溝通的方式。"},{"en":"If a technology becomes widely used, it may become a standard feature.","zh":"如果一項技術被廣泛使用，它可能成為標準功能。"},{"en":"The phrase describes broad adoption.","zh":"這個短語描述廣泛採用。"}],"source":"57 - The automobile’s history.pdf","sourcePage":3},{"front":"independent suspension","meaning":"獨立懸掛系統","examples":[{"en":"Independent suspension became widely used after the war.","zh":"獨立懸掛系統在戰後變得廣泛使用。"},{"en":"Independent suspension is a car system that allows each wheel to move separately for better ride and handling.","zh":"獨立懸掛系統是一種汽車系統，讓每個車輪能分開移動，以改善乘坐感和操控。"},{"en":"A car with independent suspension may feel smoother on uneven roads.","zh":"配有獨立懸掛系統的汽車在不平路面上可能感覺更平穩。"},{"en":"If each wheel reacts separately, passengers can experience more comfort and control.","zh":"如果每個車輪分開反應，乘客可以有更舒適和更受控的體驗。"},{"en":"The phrase refers to a vehicle suspension design.","zh":"這個短語指一種車輛懸掛設計。"}],"source":"57 - The automobile’s history.pdf","sourcePage":3},{"front":"wider application of","meaning":"……的更廣泛應用","examples":[{"en":"The wider application of fuel injection was an important development.","zh":"燃油噴射的更廣泛應用是一項重要發展。"},{"en":"Wider application of something means using it in more situations, products, or places than before.","zh":"“Wider application of” 某事指比以前在更多情況、產品或地方使用它。"},{"en":"The wider application of online payment made shopping faster and more convenient.","zh":"網上付款的更廣泛應用令購物更快和更方便。"},{"en":"If a car technology is applied more widely, it can improve many models instead of just a few.","zh":"如果汽車技術被更廣泛應用，它可以改善許多車型，而不只是少數車型。"},{"en":"The phrase describes broader practical use.","zh":"這個短語描述更廣泛的實際使用。"}],"source":"57 - The automobile’s history.pdf","sourcePage":3},{"front":"fuel injection","meaning":"燃油噴射","examples":[{"en":"Fuel injection became more widely applied in automobile technology.","zh":"燃油噴射在汽車科技中得到更廣泛應用。"},{"en":"Fuel injection is a system that sends fuel into an engine in a controlled way.","zh":"燃油噴射是一種以受控方式把燃料送入引擎的系統。"},{"en":"Modern cars often use fuel injection instead of older carburettor systems.","zh":"現代汽車常使用燃油噴射，而不是較舊的化油器系統。"},{"en":"If fuel injection is well managed, engines can become more efficient and responsive.","zh":"如果燃油噴射管理得好，引擎可以變得更高效和反應更快。"},{"en":"The phrase refers to a key engine technology.","zh":"這個短語指一項關鍵引擎科技。"}],"source":"57 - The automobile’s history.pdf","sourcePage":3},{"front":"a growing emphasis on","meaning":"對……日益重視","examples":[{"en":"There was a growing emphasis on safety in automobile design.","zh":"汽車設計中對安全日益重視。"},{"en":"A growing emphasis on something means people are paying more and more attention to it.","zh":"“A growing emphasis on” 某事指人們越來越重視它。"},{"en":"Schools have placed a growing emphasis on mental health in recent years.","zh":"近年，學校對心理健康日益重視。"},{"en":"If safety receives growing emphasis, designers may add stronger brakes and better seat belts.","zh":"如果安全受到日益重視，設計師可能加入更強煞車和更好的安全帶。"},{"en":"The phrase describes increasing importance over time.","zh":"這個短語描述重要性隨時間增加。"}],"source":"57 - The automobile’s history.pdf","sourcePage":3},{"front":"automobile design","meaning":"汽車設計","examples":[{"en":"Safety became more important in automobile design.","zh":"安全在汽車設計中變得更重要。"},{"en":"Automobile design is the process of planning a car’s structure, appearance, safety, and performance.","zh":"汽車設計是規劃汽車結構、外觀、安全和性能的過程。"},{"en":"A car design team may consider passenger comfort, fuel economy, and crash protection.","zh":"汽車設計團隊可能考慮乘客舒適、燃油效益和撞擊保護。"},{"en":"If automobile design improves, cars can become safer and more enjoyable to drive.","zh":"如果汽車設計改善，汽車可以變得更安全和更好駕駛。"},{"en":"The phrase refers to both technical and visual design of cars.","zh":"這個短語指汽車的技術和視覺設計。"}],"source":"57 - The automobile’s history.pdf","sourcePage":3},{"front":"achieve considerable success with","meaning":"憑……取得相當成功","examples":[{"en":"Mazda achieved considerable success with its rotary engine.","zh":"Mazda 憑其轉子引擎取得相當成功。"},{"en":"To achieve considerable success with something means to become quite successful by using or developing it.","zh":"“Achieve considerable success with” 某事指透過使用或發展它而取得相當成功。"},{"en":"A school may achieve considerable success with a new reading programme if students’ results improve.","zh":"如果學生成績改善，學校可能憑新的閱讀計劃取得相當成功。"},{"en":"If a company succeeds with unusual technology, it may gain a special reputation.","zh":"如果公司憑不尋常科技成功，可能獲得特殊聲譽。"},{"en":"The phrase describes notable but not necessarily perfect success.","zh":"這個短語描述顯著但不一定完美的成功。"}],"source":"57 - The automobile’s history.pdf","sourcePage":3},{"front":"rotary engine","meaning":"轉子引擎","examples":[{"en":"Mazda achieved considerable success with its rotary engine.","zh":"Mazda 憑其轉子引擎取得相當成功。"},{"en":"A rotary engine is an engine that uses a rotating design instead of traditional pistons.","zh":"轉子引擎是一種使用旋轉設計，而不是傳統活塞的引擎。"},{"en":"Car enthusiasts may admire rotary engines for their smooth power and unusual sound.","zh":"汽車愛好者可能欣賞轉子引擎平順的動力和不尋常聲音。"},{"en":"If a rotary engine uses too much fuel, drivers may enjoy performance but worry about cost.","zh":"如果轉子引擎耗油太多，司機可能享受性能但擔心成本。"},{"en":"The phrase names a distinctive type of engine.","zh":"這個短語指一種獨特引擎類型。"}],"source":"57 - The automobile’s history.pdf","sourcePage":3},{"front":"nevertheless","meaning":"然而；儘管如此","examples":[{"en":"The rotary engine nevertheless acquired a negative reputation.","zh":"然而，轉子引擎得到負面名聲。"},{"en":"Nevertheless means however or despite what has just been said.","zh":"“Nevertheless” 指然而或儘管剛才所說如此。"},{"en":"The lesson was difficult; nevertheless, the students understood the main idea.","zh":"課堂很困難；然而，學生明白主要意思。"},{"en":"If a product is innovative but costly to run, it may nevertheless receive criticism.","zh":"如果產品創新但運行成本高，它仍然可能受到批評。"},{"en":"The word introduces contrast after a positive or expected point.","zh":"這個詞在正面或預期重點之後引出對比。"}],"source":"57 - The automobile’s history.pdf","sourcePage":3},{"front":"acquire a reputation as","meaning":"得到……的名聲","examples":[{"en":"The rotary engine acquired a reputation as a polluting gas-guzzler.","zh":"轉子引擎得到污染嚴重的耗油引擎的名聲。"},{"en":"To acquire a reputation as something means to become known in that way over time.","zh":"“Acquire a reputation as” 某物指隨時間變得以某種方式為人所知。"},{"en":"A restaurant may acquire a reputation as a friendly place if staff treat customers warmly.","zh":"如果員工熱情對待顧客，餐廳可能得到友善場所的名聲。"},{"en":"If an engine often uses too much fuel, it may gain a negative reputation.","zh":"如果引擎經常耗油過多，它可能得到負面名聲。"},{"en":"The phrase describes how public opinion develops.","zh":"這個短語描述公眾看法如何形成。"}],"source":"57 - The automobile’s history.pdf","sourcePage":3},{"front":"polluting gas-guzzler","meaning":"污染嚴重的耗油引擎","examples":[{"en":"Mazda’s rotary engine acquired a reputation as a polluting gas-guzzler.","zh":"Mazda 的轉子引擎得到污染嚴重的耗油引擎的名聲。"},{"en":"A polluting gas-guzzler is a vehicle or engine that uses a lot of fuel and creates much pollution.","zh":"污染嚴重的耗油引擎，是消耗大量燃料並產生大量污染的車輛或引擎。"},{"en":"A large old car may be called a gas-guzzler if it needs frequent refuelling.","zh":"如果大型舊車需要頻繁加油，可能被稱為耗油車。"},{"en":"If an engine is seen as polluting and wasteful, buyers may avoid it when fuel prices rise.","zh":"如果引擎被視為污染嚴重且浪費，燃油價格上升時買家可能避開它。"},{"en":"The phrase is strongly negative and criticises environmental and fuel performance.","zh":"這個短語非常負面，批評環境和燃油表現。"}],"source":"57 - The automobile’s history.pdf","sourcePage":3},{"front":"the modern era","meaning":"現代時期","examples":[{"en":"The modern era has seen a sharp rise in engine power.","zh":"現代時期見證引擎動力急劇上升。"},{"en":"The modern era means the recent or present period of development.","zh":"現代時期指近期或當代發展階段。"},{"en":"In the modern era, students often use online tools alongside textbooks.","zh":"在現代時期，學生通常把網上工具與教科書一起使用。"},{"en":"If engine power rises in the modern era, computer technology may be one reason.","zh":"如果引擎動力在現代時期上升，電腦科技可能是其中一個原因。"},{"en":"The phrase gives a broad recent time setting.","zh":"這個短語給出廣泛的近期時間背景。"}],"source":"57 - The automobile’s history.pdf","sourcePage":4},{"front":"witness a sharp rise in","meaning":"見證……急劇上升","examples":[{"en":"The modern era has witnessed a sharp rise in engine power.","zh":"現代時期見證了引擎動力急劇上升。"},{"en":"To witness a sharp rise in something means to see or experience a large increase in it.","zh":"“Witness a sharp rise in” 某事指看見或經歷它大幅增加。"},{"en":"Many cities have witnessed a sharp rise in online food delivery.","zh":"許多城市見證網上外賣急劇上升。"},{"en":"If an industry witnesses a sharp rise in demand, companies may expand production quickly.","zh":"如果行業見證需求急劇上升，公司可能迅速擴大生產。"},{"en":"The phrase describes a noticeable upward trend.","zh":"這個短語描述明顯向上趨勢。"}],"source":"57 - The automobile’s history.pdf","sourcePage":4},{"front":"with the help of","meaning":"在……的幫助下","examples":[{"en":"Engine power has increased with the help of computerised systems.","zh":"引擎動力在電腦化系統的幫助下增加。"},{"en":"With the help of something means because that thing provides support or assistance.","zh":"“With the help of” 某物指因該物提供支持或協助。"},{"en":"Students can improve pronunciation with the help of recordings and teacher feedback.","zh":"學生可以在錄音和老師回饋的幫助下改善發音。"},{"en":"If machines become more powerful with computer support, technology is assisting performance.","zh":"如果機器在電腦支援下變得更強大，就是科技協助了性能。"},{"en":"The phrase identifies what helps a result happen.","zh":"這個短語指出甚麼幫助結果發生。"}],"source":"57 - The automobile’s history.pdf","sourcePage":4},{"front":"computerised engine-management systems","meaning":"電腦化引擎管理系統","examples":[{"en":"Computerised engine-management systems have helped increase engine power.","zh":"電腦化引擎管理系統幫助增加引擎動力。"},{"en":"Computerised engine-management systems are electronic systems that control how an engine uses fuel, air, and timing.","zh":"電腦化引擎管理系統是控制引擎如何使用燃料、空氣和點火時間的電子系統。"},{"en":"A modern car’s computerised system can adjust engine performance many times per second.","zh":"現代汽車的電腦化系統可以每秒多次調整引擎性能。"},{"en":"If engine management is computerised, the car can balance power, fuel use, and emissions more precisely.","zh":"如果引擎管理電腦化，汽車就能更精確地平衡動力、燃油使用和排放。"},{"en":"The phrase refers to electronic control of engine operation.","zh":"這個短語指引擎運作的電子控制。"}],"source":"57 - The automobile’s history.pdf","sourcePage":4},{"front":"automobiles in use","meaning":"正在使用中的汽車","examples":[{"en":"Most automobiles in use are powered by an internal combustion engine.","zh":"大多數正在使用中的汽車由內燃機驅動。"},{"en":"Automobiles in use are cars that are currently being driven or operated.","zh":"正在使用中的汽車是目前正在被駕駛或運作的汽車。"},{"en":"A city may count automobiles in use to plan roads, parking, and pollution controls.","zh":"城市可能統計正在使用中的汽車，以規劃道路、泊車和污染控制。"},{"en":"If most automobiles in use burn petrol or diesel, transport emissions remain a major concern.","zh":"如果大多數正在使用中的汽車燃燒汽油或柴油，交通排放仍是主要憂慮。"},{"en":"The phrase refers to vehicles currently active, not museum models.","zh":"這個短語指目前活躍使用的車輛，而不是博物館車款。"}],"source":"57 - The automobile’s history.pdf","sourcePage":4},{"front":"fuelled by petrol or diesel","meaning":"以汽油或柴油為燃料","examples":[{"en":"Most automobiles are fuelled by petrol or diesel.","zh":"大多數汽車以汽油或柴油為燃料。"},{"en":"Fuelled by petrol or diesel means using petrol or diesel as the energy source.","zh":"“Fuelled by petrol or diesel” 指使用汽油或柴油作為能源來源。"},{"en":"A fuelled-by-diesel truck may travel long distances carrying heavy goods.","zh":"以柴油為燃料的貨車可能長途運送重貨。"},{"en":"If transport is fuelled mainly by petrol or diesel, air pollution and fuel prices become important issues.","zh":"如果交通主要以汽油或柴油為燃料，空氣污染和燃油價格就成為重要問題。"},{"en":"The phrase identifies the fuel used to power vehicles.","zh":"這個短語指出車輛所使用的燃料。"}],"source":"57 - The automobile’s history.pdf","sourcePage":4},{"front":"exhaust gases","meaning":"廢氣","examples":[{"en":"Exhaust gases from petrol and diesel engines pollute the air.","zh":"汽油和柴油引擎排出的廢氣污染空氣。"},{"en":"Exhaust gases are waste gases released from an engine after fuel is burned.","zh":"廢氣是燃料燃燒後由引擎排出的廢氣體。"},{"en":"A busy road may smell unpleasant because of exhaust gases from many vehicles.","zh":"繁忙道路可能因許多車輛排出的廢氣而氣味難聞。"},{"en":"If exhaust gases are not controlled, they can harm air quality and public health.","zh":"如果廢氣沒有受到控制，就可能傷害空氣質素和公共健康。"},{"en":"The phrase refers to pollution coming out of engines.","zh":"這個短語指從引擎排出的污染物。"}],"source":"57 - The automobile’s history.pdf","sourcePage":4},{"front":"pollute the air","meaning":"污染空氣","examples":[{"en":"Exhaust gases pollute the air.","zh":"廢氣污染空氣。"},{"en":"To pollute the air means to make the air dirty or harmful by adding dangerous substances.","zh":"“Pollute the air” 指加入危險物質，使空氣變髒或有害。"},{"en":"Factories can pollute the air if smoke and chemicals are not controlled.","zh":"如果煙霧和化學物質沒有受控，工廠可以污染空氣。"},{"en":"If traffic pollutes the air near schools, children’s health may be affected.","zh":"如果交通在學校附近污染空氣，兒童健康可能受影響。"},{"en":"The phrase describes damage to air quality.","zh":"這個短語描述對空氣質素的損害。"}],"source":"57 - The automobile’s history.pdf","sourcePage":4},{"front":"contribute to","meaning":"導致；促成；加劇","examples":[{"en":"Exhaust gases contribute to climate change and global warming.","zh":"廢氣促成氣候變化和全球暖化。"},{"en":"To contribute to something means to help cause it or make it stronger.","zh":"“Contribute to” 某事指幫助造成它或令它更嚴重。"},{"en":"Poor sleep can contribute to low concentration in class.","zh":"睡眠不足可以導致課堂專注力低。"},{"en":"If many vehicles release greenhouse gases, they contribute to environmental change.","zh":"如果許多車輛排放溫室氣體，它們就會加劇環境變化。"},{"en":"The phrase shows that something is one cause among others.","zh":"這個短語顯示某事是多個原因之一。"}],"source":"57 - The automobile’s history.pdf","sourcePage":4},{"front":"climate change","meaning":"氣候變化","examples":[{"en":"Vehicle exhaust gases contribute to climate change.","zh":"車輛廢氣促成氣候變化。"},{"en":"Climate change is long-term change in global or regional climate patterns, often linked to human emissions.","zh":"氣候變化是全球或地區氣候模式的長期改變，常與人類排放有關。"},{"en":"Climate change can affect rainfall, heatwaves, storms, farming, and sea levels.","zh":"氣候變化可以影響降雨、熱浪、風暴、農業和海平面。"},{"en":"If transport produces many emissions, it can add to the causes of climate change.","zh":"如果交通產生大量排放，就可能加劇氣候變化的原因。"},{"en":"The phrase refers to broad environmental change over time.","zh":"這個短語指隨時間出現的廣泛環境變化。"}],"source":"57 - The automobile’s history.pdf","sourcePage":4},{"front":"global warming","meaning":"全球暖化","examples":[{"en":"Vehicle exhaust gases contribute to global warming.","zh":"車輛廢氣促成全球暖化。"},{"en":"Global warming is the long-term rise in Earth’s average temperature.","zh":"全球暖化是地球平均溫度長期上升。"},{"en":"Global warming can make heatwaves more severe and affect ice, oceans, and ecosystems.","zh":"全球暖化可以令熱浪更嚴重，並影響冰層、海洋和生態系統。"},{"en":"If engines burn fossil fuels, they can release gases that add to global warming.","zh":"如果引擎燃燒化石燃料，就可能釋放加劇全球暖化的氣體。"},{"en":"The phrase focuses especially on temperature increase.","zh":"這個短語特別強調溫度上升。"}],"source":"57 - The automobile’s history.pdf","sourcePage":4},{"front":"look at the following descriptions","meaning":"查看以下描述","examples":[{"en":"Students look at the following descriptions and match them with automobile brands.","zh":"學生查看以下描述，並將它們與汽車品牌配對。"},{"en":"Look at the following descriptions means read the descriptions given below the instruction.","zh":"“Look at the following descriptions” 指閱讀指示下方給出的描述。"},{"en":"In a reading test, students should look at each description carefully before choosing an answer.","zh":"在閱讀測驗中，學生應仔細查看每項描述，再選答案。"},{"en":"If descriptions contain small differences, careless reading can lead to wrong matching.","zh":"如果描述包含細微差異，粗心閱讀可能導致配對錯誤。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"57 - The automobile’s history.pdf","sourcePage":5},{"front":"list of automobile brands","meaning":"汽車品牌列表","examples":[{"en":"The question provides a list of automobile brands.","zh":"題目提供汽車品牌列表。"},{"en":"A list of automobile brands is a set of car company names given as answer choices.","zh":"汽車品牌列表是一組作為答案選項給出的汽車公司名稱。"},{"en":"A worksheet may include a list of brands such as Ford, Mazda, Jeep, and Mercedes-Benz.","zh":"工作紙可能包括 Ford、Mazda、Jeep 和 Mercedes-Benz 等品牌列表。"},{"en":"If students know the list first, they can scan the passage for matching evidence.","zh":"如果學生先知道列表，就可以掃讀文章尋找配對證據。"},{"en":"The phrase refers to the choices in a matching question.","zh":"這個短語指配對題中的選項。"}],"source":"57 - The automobile’s history.pdf","sourcePage":5},{"front":"match each description with","meaning":"將每項描述與……配對","examples":[{"en":"Students match each description with the correct automobile brand.","zh":"學生將每項描述與正確汽車品牌配對。"},{"en":"To match each description with something means to connect every description to the item it best describes.","zh":"“Match each description with” 某物指把每項描述連接到最符合它的項目。"},{"en":"In a vocabulary exercise, students match each word with the correct meaning.","zh":"在詞彙練習中，學生將每個詞與正確意思配對。"},{"en":"If a description mentions assembly-line production, students should match it with the brand linked to that feature.","zh":"如果描述提到流水線生產，學生應把它與相關品牌配對。"},{"en":"The phrase describes a matching task.","zh":"這個短語描述配對任務。"}],"source":"57 - The automobile’s history.pdf","sourcePage":5},{"front":"the correct automobile brand","meaning":"正確的汽車品牌","examples":[{"en":"Each description should be matched with the correct automobile brand.","zh":"每項描述都應與正確的汽車品牌配對。"},{"en":"The correct automobile brand is the car brand that best fits the information in the description.","zh":"正確的汽車品牌是最符合描述資料的汽車品牌。"},{"en":"If a description mentions a rotary engine, the correct automobile brand may be Mazda.","zh":"如果描述提到轉子引擎，正確汽車品牌可能是 Mazda。"},{"en":"Students should use passage evidence rather than guessing from general knowledge.","zh":"學生應使用文章證據，而不是靠常識猜測。"},{"en":"The phrase refers to the right answer in a brand-matching task.","zh":"這個短語指品牌配對題中的正確答案。"}],"source":"57 - The automobile’s history.pdf","sourcePage":5},{"front":"began producing","meaning":"開始生產","examples":[{"en":"The question asks which brand began producing the first practical automobiles.","zh":"題目問哪個品牌開始生產第一批實用汽車。"},{"en":"Began producing means started making something regularly or commercially.","zh":"“Began producing” 指開始定期或商業性製造某物。"},{"en":"A small factory began producing school uniforms after receiving many orders.","zh":"小工廠收到許多訂單後開始生產校服。"},{"en":"If a company began producing cars early, it may have played an important role in automotive history.","zh":"如果公司很早開始生產汽車，它可能在汽車史中扮演重要角色。"},{"en":"The phrase marks the start of manufacture.","zh":"這個短語標示製造的開始。"}],"source":"57 - The automobile’s history.pdf","sourcePage":5},{"front":"first practical automobiles","meaning":"第一批實用汽車","examples":[{"en":"The passage discusses the first practical automobiles.","zh":"文章討論第一批實用汽車。"},{"en":"First practical automobiles were the earliest cars useful enough for real transport.","zh":"第一批實用汽車是最早足以用於真實交通的汽車。"},{"en":"A museum may display early practical automobiles to show how modern cars began.","zh":"博物館可能展示早期實用汽車，以顯示現代汽車如何開始。"},{"en":"If a vehicle is practical, it can be used beyond experiments or demonstrations.","zh":"如果車輛實用，它就可以用於實驗或展示以外的用途。"},{"en":"The phrase refers to the first usable cars, not every early machine.","zh":"這個短語指最早可用的汽車，而不是每部早期機器。"}],"source":"57 - The automobile’s history.pdf","sourcePage":5},{"front":"mass-produced cars","meaning":"大規模生產汽車","examples":[{"en":"Ford mass-produced cars that ordinary consumers could afford.","zh":"Ford 大規模生產普通消費者負擔得起的汽車。"},{"en":"Mass-produced cars are cars made in large quantities using standardised factory methods.","zh":"大規模生產汽車是使用標準化工廠方法大量製造的汽車。"},{"en":"A mass-produced product usually costs less because many identical units are made efficiently.","zh":"大規模生產的產品通常成本較低，因為許多相同單位被高效製造。"},{"en":"If cars are mass-produced, more ordinary families may be able to buy them.","zh":"如果汽車被大規模生產，更多普通家庭可能能購買。"},{"en":"The phrase connects large-scale production with lower prices.","zh":"這個短語把大規模生產與較低價格連繫起來。"}],"source":"57 - The automobile’s history.pdf","sourcePage":5},{"front":"ordinary consumers","meaning":"普通消費者","examples":[{"en":"Ordinary consumers could afford Ford’s cars.","zh":"普通消費者能負擔得起 Ford 的汽車。"},{"en":"Ordinary consumers are normal buyers without exceptional wealth or special status.","zh":"普通消費者是沒有特殊財富或特殊地位的一般買家。"},{"en":"A product aimed at ordinary consumers must usually be affordable and easy to use.","zh":"面向普通消費者的產品通常必須價格相宜且容易使用。"},{"en":"If ordinary consumers can buy cars, car ownership spreads beyond the wealthy.","zh":"如果普通消費者能買車，汽車擁有就會超越富裕人士。"},{"en":"The phrase contrasts everyday buyers with rich elites.","zh":"這個短語把日常買家與富裕精英作對比。"}],"source":"57 - The automobile’s history.pdf","sourcePage":5},{"front":"use space efficiently","meaning":"高效運用空間","examples":[{"en":"The BMC Mini used automobile space efficiently.","zh":"BMC Mini 高效運用汽車空間。"},{"en":"To use space efficiently means to arrange a small area cleverly so little space is wasted.","zh":"“Use space efficiently” 指聰明安排小空間，使浪費的空間很少。"},{"en":"A small flat uses space efficiently when beds, shelves, and desks are built into one wall.","zh":"如果小單位把床、架和書桌建入同一道牆，就是高效運用空間。"},{"en":"If a car uses space efficiently, it can feel roomy even when the outside is small.","zh":"如果汽車高效運用空間，即使外形細小也可以感覺寬敞。"},{"en":"The phrase describes smart design within limited space.","zh":"這個短語描述有限空間中的聰明設計。"}],"source":"57 - The automobile’s history.pdf","sourcePage":5},{"front":"overall performance","meaning":"整體性能","examples":[{"en":"Some brands continuously improved the car’s overall performance.","zh":"一些品牌持續改善汽車的整體性能。"},{"en":"Overall performance means the total quality of how well something works in different areas.","zh":"整體性能指某物在不同方面運作得多好的總體質素。"},{"en":"A student’s overall performance includes speaking, writing, reading, and listening, not one score only.","zh":"學生的整體表現包括說、寫、讀、聽，而不只是一個分數。"},{"en":"If a car’s overall performance improves, it may become faster, safer, smoother, and more reliable.","zh":"如果汽車整體性能改善，它可能變得更快、更安全、更順暢和更可靠。"},{"en":"The phrase looks at the whole result rather than one feature.","zh":"這個短語看整體結果，而不是單一功能。"}],"source":"57 - The automobile’s history.pdf","sourcePage":5},{"front":"achieve strong sales","meaning":"取得強勁銷量","examples":[{"en":"The Mini went on to achieve strong sales globally.","zh":"Mini 其後在全球取得強勁銷量。"},{"en":"To achieve strong sales means to sell many units successfully.","zh":"“Achieve strong sales” 指成功賣出大量產品。"},{"en":"A textbook may achieve strong sales if teachers find it clear and useful.","zh":"如果老師覺得教科書清晰有用，它可能取得強勁銷量。"},{"en":"If a car is affordable and clever in design, it may sell well in many markets.","zh":"如果汽車價格相宜且設計聰明，可能在許多市場賣得好。"},{"en":"The phrase describes commercial success.","zh":"這個短語描述商業成功。"}],"source":"57 - The automobile’s history.pdf","sourcePage":5},{"front":"economic recession","meaning":"經濟衰退","examples":[{"en":"Some large cars sold well even during an economic recession.","zh":"即使在經濟衰退期間，一些大型車仍賣得很好。"},{"en":"An economic recession is a period when the economy slows down and businesses and consumers spend less.","zh":"經濟衰退是經濟放緩、企業和消費者減少開支的時期。"},{"en":"During an economic recession, families may avoid expensive purchases and save more money.","zh":"在經濟衰退期間，家庭可能避免昂貴購買並儲更多錢。"},{"en":"If luxury goods sell well in a recession, the result may seem surprising.","zh":"如果奢侈品在衰退中賣得好，結果可能令人驚訝。"},{"en":"The phrase describes a serious economic slowdown.","zh":"這個短語描述嚴重經濟放緩。"}],"source":"57 - The automobile’s history.pdf","sourcePage":6},{"front":"answer the questions below","meaning":"回答以下問題","examples":[{"en":"Students answer the questions below using words from the passage.","zh":"學生使用文章中的詞語回答以下問題。"},{"en":"Answer the questions below means respond to the tasks printed after the reading text or instruction.","zh":"“Answer the questions below” 指回答閱讀文本或指示下方列出的題目。"},{"en":"In a reading test, students should answer the questions below by finding evidence in the passage.","zh":"在閱讀測驗中，學生應透過在文章中尋找證據來回答以下問題。"},{"en":"If answers must come from the passage, students should not use outside knowledge.","zh":"如果答案必須來自文章，學生不應使用外部知識。"},{"en":"The phrase is a basic exam instruction.","zh":"這個短語是基本考試指示。"}],"source":"57 - The automobile’s history.pdf","sourcePage":6},{"front":"no more than three words and/or a number","meaning":"不多於三個詞及／或一個數字","examples":[{"en":"Students should choose no more than three words and/or a number from the passage.","zh":"學生應從文章中選擇不多於三個詞及／或一個數字。"},{"en":"No more than three words and/or a number means the answer must stay within that exact word and number limit.","zh":"“No more than three words and/or a number” 指答案必須符合該字數和數字限制。"},{"en":"If the answer is “every 15 minutes,” it fits the instruction because it has words and a number.","zh":"如果答案是 “every 15 minutes”，它符合指示，因為包含詞語和一個數字。"},{"en":"Students may lose marks if they write four words when only three are allowed.","zh":"如果只允許三個詞而學生寫四個詞，可能會失分。"},{"en":"The phrase gives a strict answer format in reading tests.","zh":"這個短語給出閱讀測驗中的嚴格答案格式。"}],"source":"57 - The automobile’s history.pdf","sourcePage":6},{"front":"important engine feature","meaning":"重要引擎特徵","examples":[{"en":"The question asks what important engine feature became widespread.","zh":"題目問哪項重要引擎特徵變得普及。"},{"en":"An important engine feature is a key part or system that affects how an engine works.","zh":"重要引擎特徵是影響引擎如何運作的關鍵部件或系統。"},{"en":"Fuel injection can be an important engine feature because it controls how fuel enters the engine.","zh":"燃油噴射可以是重要引擎特徵，因為它控制燃油如何進入引擎。"},{"en":"If an engine feature becomes widespread, many car makers begin using it as standard technology.","zh":"如果引擎特徵變得普及，許多汽車製造商開始把它作為標準技術使用。"},{"en":"The phrase points to a significant technical detail.","zh":"這個短語指重要技術細節。"}],"source":"57 - The automobile’s history.pdf","sourcePage":6},{"front":"become widespread","meaning":"變得普及","examples":[{"en":"The internal combustion engine became widespread.","zh":"內燃機變得普及。"},{"en":"To become widespread means to be used or found in many places.","zh":"“Become widespread” 指在許多地方被使用或找到。"},{"en":"Online payment became widespread when shops and customers started using it daily.","zh":"當商店和顧客每天使用網上付款時，它就變得普及。"},{"en":"If a technology becomes widespread, it moves from being unusual to being normal.","zh":"如果科技變得普及，它就由不尋常變成正常。"},{"en":"The phrase describes broad adoption or distribution.","zh":"這個短語描述廣泛採用或分布。"}],"source":"57 - The automobile’s history.pdf","sourcePage":6},{"front":"symbolise to","meaning":"對……象徵","examples":[{"en":"The question asks what a car symbolised to wealthy people.","zh":"題目問汽車對富裕人士象徵甚麼。"},{"en":"To symbolise something to someone means to represent an idea or value for that person or group.","zh":"“Symbolise something to someone” 指對某人或某群體代表某想法或價值。"},{"en":"A graduation certificate may symbolise achievement to a family.","zh":"畢業證書對家庭可能象徵成就。"},{"en":"If early cars symbolised status, owners used them to show wealth and identity.","zh":"如果早期汽車象徵地位，車主就用它們顯示財富和身份。"},{"en":"The phrase connects an object with meaning.","zh":"這個短語把物件與意義連繫起來。"}],"source":"57 - The automobile’s history.pdf","sourcePage":6},{"front":"wealthy people","meaning":"富裕人士","examples":[{"en":"Cars were first a product for wealthy people.","zh":"汽車最初是富裕人士的產品。"},{"en":"Wealthy people are people who have a lot of money, property, or financial resources.","zh":"富裕人士是擁有大量金錢、財產或財務資源的人。"},{"en":"Wealthy people may buy expensive products before they become affordable to the public.","zh":"富裕人士可能在產品變得大眾負擔得起前先購買昂貴產品。"},{"en":"If a new technology is costly, it may first be used mainly by wealthy people.","zh":"如果新科技昂貴，它最初可能主要由富裕人士使用。"},{"en":"The phrase contrasts rich buyers with ordinary consumers.","zh":"這個短語把富有買家與普通消費者作對比。"}],"source":"57 - The automobile’s history.pdf","sourcePage":6},{"front":"assembly line","meaning":"流水線","examples":[{"en":"Ford’s assembly line produced a car every 15 minutes.","zh":"Ford 的流水線每15分鐘生產一輛汽車。"},{"en":"An assembly line is a factory system where a product moves through stations and workers add parts step by step.","zh":"流水線是一種工廠系統，產品經過不同工位，工人逐步加入零件。"},{"en":"A toy factory may use an assembly line to put wheels, doors, and labels on toy cars.","zh":"玩具工廠可能使用流水線，把車輪、車門和標籤加到玩具車上。"},{"en":"If an assembly line is efficient, production becomes faster and more predictable.","zh":"如果流水線有效率，生產就變得更快和更可預測。"},{"en":"The phrase refers to organised step-by-step mass production.","zh":"這個短語指有組織的逐步大規模生產。"}],"source":"57 - The automobile’s history.pdf","sourcePage":6},{"front":"take to produce a car","meaning":"需時多久生產一輛車","examples":[{"en":"The question asks how long Ford’s assembly line took to produce a car.","zh":"題目問 Ford 的流水線需時多久生產一輛車。"},{"en":"How long it takes to produce a car means the amount of time needed to complete one car.","zh":"生產一輛車需時多久，指完成一輛車所需的時間量。"},{"en":"A factory manager may measure how long it takes to produce each unit to improve efficiency.","zh":"工廠經理可能量度生產每個單位需時多久，以提高效率。"},{"en":"If a car takes less time to produce, the company can make more cars each day.","zh":"如果生產一輛車需時較少，公司每天就能製造更多車。"},{"en":"The phrase focuses on production time.","zh":"這個短語強調生產時間。"}],"source":"57 - The automobile’s history.pdf","sourcePage":6},{"front":"major historical event","meaning":"重大歷史事件","examples":[{"en":"The question asks which major historical event caused the industry to struggle.","zh":"題目問哪個重大歷史事件導致該行業陷入困境。"},{"en":"A major historical event is an important event in history that affects many people or industries.","zh":"重大歷史事件是歷史上影響許多人或行業的重要事件。"},{"en":"A war, crisis, or technological breakthrough can be a major historical event.","zh":"戰爭、危機或技術突破都可以是重大歷史事件。"},{"en":"If a major event disrupts fuel supply, transport industries may suffer badly.","zh":"如果重大事件擾亂燃料供應，運輸行業可能嚴重受損。"},{"en":"The phrase points to a large event with broad consequences.","zh":"這個短語指有廣泛後果的大事件。"}],"source":"57 - The automobile’s history.pdf","sourcePage":6},{"front":"struggle against","meaning":"與……抗衡；艱難應對","examples":[{"en":"The American automobile industry struggled against Japanese imports.","zh":"美國汽車工業艱難應對日本進口車。"},{"en":"To struggle against something means to have difficulty competing with or resisting it.","zh":"“Struggle against” 某事指難以與它競爭或抵抗它。"},{"en":"Small shops may struggle against large online retailers.","zh":"小店可能難以與大型網上零售商抗衡。"},{"en":"If domestic car makers struggle against imports, they may need better design and lower prices.","zh":"如果本土汽車製造商艱難應對進口車，可能需要更好設計和較低價格。"},{"en":"The phrase describes difficult competition or resistance.","zh":"這個短語描述艱難競爭或抵抗。"}],"source":"57 - The automobile’s history.pdf","sourcePage":6},{"front":"be reputed to be","meaning":"被認為是","examples":[{"en":"Mazda’s rotary engine was reputed to be a polluting gas-guzzler.","zh":"Mazda 的轉子引擎被認為是污染嚴重的耗油引擎。"},{"en":"To be reputed to be something means to be generally believed or said to have that quality.","zh":"“Be reputed to be” 某物指普遍被相信或被說成具有該特質。"},{"en":"A restaurant may be reputed to be expensive even if some dishes are affordable.","zh":"餐廳可能被認為昂貴，即使部分菜式價格相宜。"},{"en":"If an engine is reputed to be wasteful, buyers may avoid it even before checking details.","zh":"如果引擎被認為浪費燃油，買家可能在查明細節前已避開它。"},{"en":"The phrase describes public reputation rather than proven fact only.","zh":"這個短語描述公眾名聲，而不只是已證實事實。"}],"source":"57 - The automobile’s history.pdf","sourcePage":7},{"front":"greatly increased with","meaning":"隨着……大幅增加","examples":[{"en":"Engine power greatly increased with computerised engine-management systems.","zh":"隨着電腦化引擎管理系統出現，引擎動力大幅增加。"},{"en":"Greatly increased with something means rose a lot because that thing helped or was introduced.","zh":"“Greatly increased with” 某物指因該物幫助或被引入而大幅上升。"},{"en":"Student participation greatly increased with clearer tasks and more supportive feedback.","zh":"隨着任務更清晰和回饋更有支持性，學生參與度大幅增加。"},{"en":"If engine control improves through computers, power can increase without relying only on bigger engines.","zh":"如果透過電腦改善引擎控制，動力可以增加，而不只依賴更大引擎。"},{"en":"The phrase links a large increase to a supporting factor.","zh":"這個短語把大幅增加與支持因素連繫起來。"}],"source":"57 - The automobile’s history.pdf","sourcePage":7},{"front":"substance","meaning":"物質","examples":[{"en":"The question asks what substance contributes to pollution and global warming.","zh":"題目問哪種物質促成污染和全球暖化。"},{"en":"A substance is a material or type of matter, such as a gas, liquid, or solid.","zh":"物質是材料或物質種類，例如氣體、液體或固體。"},{"en":"Smoke contains substances that can harm the lungs.","zh":"煙含有可以傷害肺部的物質。"},{"en":"If a substance enters the air in large amounts, it may damage health or the environment.","zh":"如果某種物質大量進入空氣，可能損害健康或環境。"},{"en":"The word is often used in science and environmental topics.","zh":"這個詞常用於科學和環境題目。"}],"source":"57 - The automobile’s history.pdf","sourcePage":7},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter from the options.","zh":"學生從選項中選出正確字母。"},{"en":"To choose the correct letter means to select the answer option marked by the right letter.","zh":"“Choose the correct letter” 指選出由正確字母標示的答案選項。"},{"en":"In multiple-choice questions, students should read all options before choosing the correct letter.","zh":"在選擇題中，學生應先閱讀所有選項，再選出正確字母。"},{"en":"If two answers look similar, passage evidence should decide which letter is correct.","zh":"如果兩個答案看起來相似，文章證據應決定哪個字母正確。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"57 - The automobile’s history.pdf","sourcePage":7},{"front":"the main idea of the passage","meaning":"文章主旨","examples":[{"en":"The question asks for the main idea of the passage.","zh":"題目問文章主旨。"},{"en":"The main idea of the passage is the central message or overall topic of the text.","zh":"文章主旨是文本的中心信息或整體題目。"},{"en":"In a reading test, students should identify the main idea before focusing on small details.","zh":"在閱讀測驗中，學生應先識別文章主旨，再集中小細節。"},{"en":"If a passage covers many examples, the main idea helps connect them into one purpose.","zh":"如果文章涵蓋許多例子，文章主旨能把它們連接成一個目的。"},{"en":"The phrase asks what the whole passage is mainly about.","zh":"這個短語問整篇文章主要關於甚麼。"}],"source":"57 - The automobile’s history.pdf","sourcePage":7},{"front":"the influence of cars on the environment","meaning":"汽車對環境的影響","examples":[{"en":"One option concerns the influence of cars on the environment.","zh":"其中一個選項涉及汽車對環境的影響。"},{"en":"The influence of cars on the environment means how cars affect air, climate, land, and natural resources.","zh":"汽車對環境的影響指汽車如何影響空氣、氣候、土地和自然資源。"},{"en":"Exhaust gases show one influence of cars on the environment.","zh":"廢氣顯示汽車對環境的一種影響。"},{"en":"If cars burn petrol or diesel, they may contribute to pollution and climate change.","zh":"如果汽車燃燒汽油或柴油，就可能促成污染和氣候變化。"},{"en":"The phrase focuses on environmental effects, not the whole history of cars.","zh":"這個短語強調環境影響，而不是汽車的整段歷史。"}],"source":"57 - The automobile’s history.pdf","sourcePage":7},{"front":"historical development","meaning":"歷史發展","examples":[{"en":"The passage describes the historical development of automobile technology.","zh":"文章描述汽車科技的歷史發展。"},{"en":"Historical development means the way something changes and progresses over time.","zh":"歷史發展指某事如何隨時間改變和進步。"},{"en":"The historical development of phones shows how communication moved from landlines to smartphones.","zh":"電話的歷史發展顯示溝通如何由固定電話走向智能手機。"},{"en":"If a passage follows inventions, factories, wars, and technology, it is describing historical development.","zh":"如果文章追溯發明、工廠、戰爭和科技，它就是在描述歷史發展。"},{"en":"The phrase focuses on change across history.","zh":"這個短語強調歷史中的變化。"}],"source":"57 - The automobile’s history.pdf","sourcePage":7},{"front":"innovation in car designs","meaning":"汽車設計創新","examples":[{"en":"The passage discusses innovation in car designs.","zh":"文章討論汽車設計創新。"},{"en":"Innovation in car designs means new and improved ideas in how cars are built, shaped, or organised.","zh":"汽車設計創新指汽車建造、外形或安排方式中的新改良想法。"},{"en":"A space-efficient small car is an example of innovation in car design.","zh":"空間運用高效的小型車是汽車設計創新的例子。"},{"en":"If designers innovate, cars may become safer, cheaper, faster, or more comfortable.","zh":"如果設計師創新，汽車可能變得更安全、更便宜、更快速或更舒適。"},{"en":"The phrase focuses on new design ideas in automobiles.","zh":"這個短語強調汽車中的新設計想法。"}],"source":"57 - The automobile’s history.pdf","sourcePage":7},{"front":"modern gasoline-engine design","meaning":"現代汽油引擎設計","examples":[{"en":"The passage mentions the beginning of modern gasoline-engine design.","zh":"文章提到現代汽油引擎設計的開始。"},{"en":"Modern gasoline-engine design means the technical design of engines that use petrol in modern-style vehicles.","zh":"現代汽油引擎設計指現代車輛中使用汽油的引擎技術設計。"},{"en":"Engineers studying gasoline-engine design examine fuel, combustion, power, and emissions.","zh":"研究汽油引擎設計的工程師會檢視燃料、燃燒、動力和排放。"},{"en":"If modern engine design improves, cars can become more powerful and cleaner.","zh":"如果現代引擎設計改善，汽車可以變得更強大和更潔淨。"},{"en":"The phrase refers to the development of petrol-based engine technology.","zh":"這個短語指汽油引擎科技的發展。"}],"source":"57 - The automobile’s history.pdf","sourcePage":7},{"front":"the automobile industry","meaning":"汽車工業","examples":[{"en":"The automobile industry changed greatly during the twentieth century.","zh":"汽車工業在20世紀發生了巨大變化。"},{"en":"The automobile industry is the business sector that designs, makes, sells, and repairs cars and related vehicles.","zh":"汽車工業是設計、製造、銷售和維修汽車及相關車輛的商業部門。"},{"en":"The automobile industry includes manufacturers, parts suppliers, dealerships, and repair services.","zh":"汽車工業包括製造商、零件供應商、代理商和維修服務。"},{"en":"If the automobile industry changes, jobs, cities, transport habits, and fuel use can also change.","zh":"如果汽車工業改變，職位、城市、交通習慣和燃油使用也可能改變。"},{"en":"The phrase refers to the whole economic system around cars.","zh":"這個短語指圍繞汽車的整個經濟系統。"}],"source":"57 - The automobile’s history.pdf","sourcePage":7}],"ielts/reading/passage-2/Practice 58":[{"front":"muscle attachment","meaning":"肌肉附着處","examples":[{"en":"The muscle attachment indicated huge leg muscles.","zh":"肌肉附着處顯示巨大的腿部肌肉。"},{"en":"Muscle attachment is the place on a bone where muscle connects to it.","zh":"muscle attachment 是肌肉連接到骨骼上的位置。"},{"en":"Athletes may develop strong muscle attachments after years of heavy training.","zh":"運動員多年高強度訓練後，可能形成強壯的肌肉附着處。"},{"en":"If muscle attachments are large, they can suggest repeated physical effort.","zh":"如果肌肉附着處很大，它們可以暗示反覆體力勞動。"},{"en":"This phrase helps researchers infer body strength from bones.","zh":"這個片語幫助研究人員從骨骼推斷身體力量。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":1},{"front":"indicate","meaning":"顯示；表明","examples":[{"en":"The bone structure indicated a strenuous lifestyle.","zh":"骨骼結構顯示一種勞累的生活方式。"},{"en":"To indicate something means to show, suggest or point to it as evidence.","zh":"indicate something 指顯示、暗示或作為證據指向某事。"},{"en":"A red warning light may indicate that a machine needs repair.","zh":"紅色警告燈可能顯示機器需要維修。"},{"en":"If bones indicate hard physical work, researchers can infer how ancient people lived.","zh":"如果骨骼顯示繁重體力勞動，研究人員可以推斷古代人如何生活。"},{"en":"This word is often used when evidence points to a conclusion.","zh":"當證據指向某結論時，常使用這個詞。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":1},{"front":"huge leg muscles","meaning":"巨大的腿部肌肉","examples":[{"en":"The Kiffians had huge leg muscles.","zh":"基菲安人有巨大的腿部肌肉。"},{"en":"Huge leg muscles are very large and powerful muscles in the legs.","zh":"huge leg muscles 是腿部非常大而有力的肌肉。"},{"en":"A cyclist who trains on hills every day may develop huge leg muscles.","zh":"每天在山路訓練的單車手可能發展出巨大的腿部肌肉。"},{"en":"If ancient bones show signs of huge leg muscles, the person probably walked, carried or worked heavily.","zh":"如果古代骨骼顯示巨大腿部肌肉的痕跡，該人很可能經常步行、搬運或勞動。"},{"en":"This phrase describes physical strength built through repeated activity.","zh":"這個片語描述透過反覆活動形成的身體力量。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":1},{"front":"a strenuous lifestyle","meaning":"勞累的生活方式","examples":[{"en":"The Kiffians probably had a strenuous lifestyle.","zh":"基菲安人很可能過着勞累的生活方式。"},{"en":"A strenuous lifestyle is a way of life involving hard physical effort and tiring work.","zh":"strenuous lifestyle 是涉及大量體力和疲累工作的生活方式。"},{"en":"A farmer who works long hours in the fields may have a strenuous lifestyle.","zh":"長時間在田裡工作的農民可能有勞累的生活方式。"},{"en":"If people depend on fishing, carrying nets and moving through difficult land, their lifestyle may become physically demanding.","zh":"如果人們依賴捕魚、搬運魚網和穿越艱難地形，他們的生活方式可能變得體力要求很高。"},{"en":"This phrase describes daily life that requires strength and endurance.","zh":"這個片語描述需要力量和耐力的日常生活。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":1},{"front":"protein-rich diet","meaning":"高蛋白飲食","examples":[{"en":"Their bones suggested a protein-rich diet.","zh":"他們的骨骼顯示高蛋白飲食。"},{"en":"A protein-rich diet is a diet containing a lot of protein from foods such as fish, meat, eggs, beans or dairy products.","zh":"protein-rich diet 是含有大量蛋白質的飲食，例如來自魚、肉、蛋、豆類或奶製品。"},{"en":"An athlete may follow a protein-rich diet to help repair muscles after training.","zh":"運動員可能採用高蛋白飲食，以幫助訓練後修復肌肉。"},{"en":"If ancient people ate many fish, their bones may show signs of a protein-rich diet.","zh":"如果古代人吃很多魚，他們的骨骼可能顯示高蛋白飲食的痕跡。"},{"en":"This phrase focuses on the nutritional content of what people eat.","zh":"這個片語聚焦於人們所吃食物的營養成分。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":1},{"front":"all consistent with","meaning":"全都與……一致","examples":[{"en":"The evidence was all consistent with people who lived by fishing.","zh":"這些證據全都與以捕魚為生的人一致。"},{"en":"All consistent with means all the evidence matches or supports the same explanation.","zh":"all consistent with 指所有證據都符合或支持同一個解釋。"},{"en":"Wet clothes, muddy shoes and an umbrella are all consistent with someone walking home in heavy rain.","zh":"濕衣服、滿泥的鞋和雨傘，全都與某人在大雨中步行回家一致。"},{"en":"If strong leg bones, fish remains and tools point in the same direction, the fishing theory becomes more convincing.","zh":"如果強壯腿骨、魚類遺骸和工具都指向同一方向，捕魚理論就更有說服力。"},{"en":"This phrase shows that different pieces of evidence fit together.","zh":"這個片語顯示不同證據能互相配合。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":1},{"front":"live by fishing","meaning":"以捕魚為生","examples":[{"en":"The Kiffians probably lived by fishing.","zh":"基菲安人很可能以捕魚為生。"},{"en":"To live by fishing means to depend on catching fish for food, work or survival.","zh":"live by fishing 指依靠捕魚來取得食物、工作或生存。"},{"en":"A family near a lake may live by fishing if they catch and sell fish every day.","zh":"湖邊家庭如果每天捕魚並出售魚獲，可能以捕魚為生。"},{"en":"If a group lives by fishing, water sources and fish populations are essential to its survival.","zh":"如果一個群體以捕魚為生，水源和魚類數量對其生存至關重要。"},{"en":"This phrase describes fishing as a main way of life.","zh":"這個片語描述捕魚作為主要生活方式。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":1},{"front":"in contrast","meaning":"相比之下","examples":[{"en":"In contrast, the Tenerian male had less visible muscle markings.","zh":"相比之下，特內里安男性的肌肉痕跡較不明顯。"},{"en":"In contrast means compared with the previous point, the next point is different.","zh":"in contrast 指與前一點相比，下一點不同。"},{"en":"One student revised every day; in contrast, another studied only the night before the exam.","zh":"一名學生每天溫習；相比之下，另一名只在考試前一晚讀書。"},{"en":"If Kiffian bones suggest hard physical work, Tenerian bones may show a different lifestyle.","zh":"如果基菲安骨骼顯示繁重體力勞動，特內里安骨骼可能顯示不同生活方式。"},{"en":"This phrase introduces a clear difference between two things.","zh":"這個片語引入兩者之間的清楚差異。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":1},{"front":"the same ridge","meaning":"同一道骨脊","examples":[{"en":"The same ridge was barely visible on the femur of a Tenerian male.","zh":"同一道骨脊在特內里安男性的股骨上幾乎看不見。"},{"en":"The same ridge means the identical raised line or feature on a bone being compared.","zh":"the same ridge 指正在比較的骨骼上同一條隆起線或特徵。"},{"en":"A doctor may compare the same ridge on two X-rays to see whether a bone has changed.","zh":"醫生可能比較兩張 X 光片上的同一道骨脊，看骨骼是否有變化。"},{"en":"If the same ridge is strong in one skeleton but weak in another, researchers may infer different muscle use.","zh":"如果同一道骨脊在一具骸骨上很明顯，而在另一具上很弱，研究人員可能推斷肌肉使用不同。"},{"en":"This phrase points to a repeated feature used for comparison.","zh":"這個片語指出用於比較的重複特徵。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":1},{"front":"barely visible","meaning":"幾乎看不見","examples":[{"en":"The ridge was barely visible on the Tenerian femur.","zh":"那道骨脊在特內里安股骨上幾乎看不見。"},{"en":"Barely visible means almost impossible to see because something is very faint or small.","zh":"barely visible 指某物非常淡或細小，幾乎看不見。"},{"en":"The pencil mark was barely visible after the student erased it.","zh":"學生擦掉後，鉛筆痕跡幾乎看不見。"},{"en":"If a muscle mark is barely visible, it may suggest that the muscle was not heavily used.","zh":"如果肌肉痕跡幾乎看不見，可能暗示該肌肉沒有被大量使用。"},{"en":"This phrase describes something that can only just be seen.","zh":"這個片語描述只能勉強看到的東西。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":1},{"front":"Tenerian male","meaning":"特內里安男性","examples":[{"en":"The femur of a Tenerian male suggested a less strenuous lifestyle.","zh":"一名特內里安男性的股骨顯示較不勞累的生活方式。"},{"en":"A Tenerian male is a male individual belonging to the Tenerian culture.","zh":"Tenerian male 是屬於特內里安文化的男性個體。"},{"en":"Archaeologists may compare a Tenerian male skeleton with Kiffian skeletons to understand cultural differences.","zh":"考古學家可能把特內里安男性骸骨與基菲安骸骨比較，以理解文化差異。"},{"en":"If a Tenerian male shows lighter muscle markings, he may have done less heavy physical work.","zh":"如果特內里安男性顯示較淡的肌肉痕跡，他可能從事較少繁重體力工作。"},{"en":"This phrase identifies both sex and cultural group.","zh":"這個片語同時指出性別和文化群體。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":1},{"front":"this individual","meaning":"這個個體","examples":[{"en":"This individual appeared to have lived less strenuously.","zh":"這個個體似乎生活得較不勞累。"},{"en":"This individual means this particular person rather than the whole group.","zh":"this individual 指這一個特定的人，而不是整個群體。"},{"en":"A doctor may say this individual needs rest even if other patients can return to work.","zh":"醫生可能說這個個體需要休息，即使其他病人可以復工。"},{"en":"If one skeleton differs from others, researchers must be careful not to generalise too quickly.","zh":"如果一具骸骨與其他不同，研究人員必須小心，不要太快概括。"},{"en":"This phrase narrows attention to one person.","zh":"這個片語把注意力收窄到一個人身上。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":2},{"front":"expect of","meaning":"對……來說可以預期","examples":[{"en":"A less strenuous lifestyle might be expected of a herder.","zh":"較不勞累的生活方式對牧民來說可以預期。"},{"en":"To expect something of someone means to think it is likely, normal or reasonable for that person.","zh":"expect something of someone 指認為某事對某人而言很可能、正常或合理。"},{"en":"Teachers expect careful preparation of students before an important presentation.","zh":"老師會期望學生在重要匯報前仔細準備。"},{"en":"If herders spend time managing animals rather than hauling fishing nets, lighter muscle marks may be expected of them.","zh":"如果牧民花時間管理牲畜，而不是拖拉魚網，較淡的肌肉痕跡對他們來說可以預期。"},{"en":"This phrase connects a prediction with a person’s role or situation.","zh":"這個片語把預測與某人的角色或情況連接起來。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":2},{"front":"a herder","meaning":"牧民","examples":[{"en":"A Tenerian male may have lived the lifestyle of a herder.","zh":"一名特內里安男性可能過着牧民的生活方式。"},{"en":"A herder is a person who looks after and moves animals such as cattle, goats or sheep.","zh":"herder 是照顧和趕移牛、山羊或綿羊等牲畜的人。"},{"en":"A herder may guide animals to fresh grass and water during dry seasons.","zh":"牧民可能在旱季帶領牲畜前往新鮮草地和水源。"},{"en":"If people become herders, their food and daily movement may depend on their animals.","zh":"如果人們成為牧民，他們的食物和日常移動可能取決於牲畜。"},{"en":"This word describes someone whose work centres on livestock.","zh":"這個詞描述工作以牲畜為中心的人。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":2},{"front":"conclude that","meaning":"得出結論認為","examples":[{"en":"Stojanowski concluded that the Tenerians were herders.","zh":"Stojanowski 得出結論認為特內里安人是牧民。"},{"en":"To conclude that means to reach a final judgement after considering evidence.","zh":"conclude that 指考慮證據後得出最終判斷。"},{"en":"After reading several essays, a teacher may conclude that students need more help with paragraphing.","zh":"老師讀完幾篇文章後，可能得出結論認為學生需要更多段落寫作幫助。"},{"en":"If bones, tools and animal remains point in one direction, researchers may conclude something about lifestyle.","zh":"如果骨骼、工具和動物遺骸都指向同一方向，研究人員可能得出關於生活方式的結論。"},{"en":"This phrase introduces a reasoned conclusion, not a random guess.","zh":"這個片語引入有理據的結論，而不是隨意猜測。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":2},{"front":"consistent with","meaning":"與……一致","examples":[{"en":"His conclusion was consistent with the prevailing view of Saharan life.","zh":"他的結論與關於撒哈拉生活的主流觀點一致。"},{"en":"Consistent with means matching or supporting something else without contradiction.","zh":"consistent with 指與另一事物相符或支持它，沒有矛盾。"},{"en":"A student’s strong test score is consistent with their careful preparation.","zh":"學生的高測驗分數與其仔細準備一致。"},{"en":"If a new finding is consistent with an existing theory, it strengthens that theory.","zh":"如果新發現與現有理論一致，它會加強該理論。"},{"en":"This phrase shows agreement between evidence and explanation.","zh":"這個片語顯示證據與解釋之間的一致。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":2},{"front":"the prevailing view","meaning":"主流觀點","examples":[{"en":"The prevailing view was that herding became more important as the climate dried.","zh":"主流觀點是，隨着氣候變乾，畜牧變得更重要。"},{"en":"The prevailing view is the opinion or explanation most widely accepted at a particular time.","zh":"prevailing view 是某一時期最廣泛被接受的意見或解釋。"},{"en":"The prevailing view in a school may be that regular reading improves writing.","zh":"學校中的主流觀點可能是定期閱讀能改善寫作。"},{"en":"If new evidence challenges the prevailing view, researchers may need to rethink old assumptions.","zh":"如果新證據挑戰主流觀點，研究人員可能需要重新思考舊假設。"},{"en":"This phrase refers to the dominant or common understanding.","zh":"這個片語指佔主導地位或普遍的理解。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":2},{"front":"life in the Sahara","meaning":"撒哈拉沙漠的生活","examples":[{"en":"The findings relate to life in the Sahara 6,000 years ago.","zh":"這些發現與六千年前撒哈拉沙漠的生活有關。"},{"en":"Life in the Sahara means how people, animals and communities lived in the Saharan region.","zh":"life in the Sahara 指人、動物和社群如何在撒哈拉地區生活。"},{"en":"Life in the Sahara today requires careful use of water and knowledge of desert conditions.","zh":"今日撒哈拉沙漠的生活需要小心用水和了解沙漠環境。"},{"en":"If ancient Sahara was wetter, life in the Sahara would have included lakes, fish and grazing animals.","zh":"如果古代撒哈拉較濕潤，撒哈拉沙漠的生活便會包括湖泊、魚類和放牧動物。"},{"en":"This phrase focuses on living conditions in the Saharan environment.","zh":"這個片語聚焦於撒哈拉環境中的生活條件。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":2},{"front":"drying climate","meaning":"越來越乾旱的氣候","examples":[{"en":"The drying climate favoured herding over hunting.","zh":"越來越乾旱的氣候使畜牧比狩獵更有利。"},{"en":"A drying climate is a climate that is becoming less wet and more arid over time.","zh":"drying climate 是隨時間變得較少雨、較乾旱的氣候。"},{"en":"Farmers may worry about a drying climate because crops need regular rainfall.","zh":"農民可能擔心越來越乾旱的氣候，因為農作物需要定期降雨。"},{"en":"If lakes shrink and grasslands change, people may adjust their food sources and work.","zh":"如果湖泊縮小、草地改變，人們可能調整食物來源和工作方式。"},{"en":"This phrase describes environmental change toward dryness.","zh":"這個片語描述環境向乾旱方向改變。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":2},{"front":"favour herding over hunting","meaning":"使畜牧比狩獵更有利","examples":[{"en":"The climate favoured herding over hunting.","zh":"氣候使畜牧比狩獵更有利。"},{"en":"To favour herding over hunting means to make raising animals more useful or successful than hunting wild animals.","zh":"favour herding over hunting 指令飼養動物比狩獵野生動物更有用或更成功。"},{"en":"A dry region may favour goats over crops because goats can survive with less water.","zh":"乾旱地區可能使養山羊比種植農作物更有利，因為山羊用水較少也能生存。"},{"en":"If wild animals become harder to find, people may turn to herding for a more reliable food supply.","zh":"如果野生動物變得較難找到，人們可能轉向畜牧以取得較可靠食物來源。"},{"en":"This phrase compares which livelihood becomes more suitable.","zh":"這個片語比較哪種生計方式變得更合適。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":2},{"front":"herding","meaning":"畜牧；放牧","examples":[{"en":"The Tenerians may have practised herding.","zh":"特內里安人可能從事畜牧。"},{"en":"Herding is the activity of keeping, moving and caring for animals such as cattle, goats or sheep.","zh":"herding 是飼養、趕移和照顧牛、山羊或綿羊等動物的活動。"},{"en":"Herding requires people to find grass and water for their animals.","zh":"畜牧需要人們為牲畜尋找草地和水源。"},{"en":"If a society practises herding, its movement and diet may depend heavily on livestock.","zh":"如果一個社會從事畜牧，其移動和飲食可能很大程度上依賴牲畜。"},{"en":"This word describes a pastoral way of life.","zh":"這個詞描述牧民式生活方式。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":2},{"front":"hunting","meaning":"狩獵","examples":[{"en":"Some groups still relied on hunting and fishing.","zh":"一些群體仍然依靠狩獵和捕魚。"},{"en":"Hunting is the activity of catching or killing wild animals for food, skins or other resources.","zh":"hunting 是捕捉或殺死野生動物，以取得食物、獸皮或其他資源的活動。"},{"en":"In the past, people often hunted animals when farming was not possible.","zh":"在過去，當耕種不可能時，人們常狩獵動物。"},{"en":"If wild animals become scarce, hunting becomes less reliable as a way to survive.","zh":"如果野生動物變得稀少，狩獵作為生存方式便較不可靠。"},{"en":"This word refers to obtaining resources from wild animals.","zh":"這個詞指從野生動物取得資源。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":2},{"front":"raise a puzzling question","meaning":"提出一個令人困惑的問題","examples":[{"en":"Sereno raised a puzzling question about the Tenerians.","zh":"Sereno 提出一個關於特內里安人的令人困惑的問題。"},{"en":"To raise a puzzling question means to bring up a question that is difficult to explain.","zh":"raise a puzzling question 指提出一個難以解釋的問題。"},{"en":"A teacher may raise a puzzling question when two exam answers both seem partly correct.","zh":"當兩個考試答案似乎都有部分正確時，老師可能提出一個令人困惑的問題。"},{"en":"If evidence does not fit the expected theory, it can raise a new question for researchers.","zh":"如果證據不符合預期理論，它可以為研究人員提出新問題。"},{"en":"This phrase introduces a problem that needs more explanation.","zh":"這個片語引入需要更多解釋的問題。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":3},{"front":"puzzling question","meaning":"令人困惑的問題","examples":[{"en":"The lack of herd remains created a puzzling question.","zh":"缺乏牲畜遺骸造成一個令人困惑的問題。"},{"en":"A puzzling question is a question that is confusing because the evidence does not immediately make sense.","zh":"puzzling question 是因證據不能立即解釋清楚而令人困惑的問題。"},{"en":"A doctor faces a puzzling question when symptoms do not match common illnesses.","zh":"當症狀不符合常見疾病時，醫生會面對令人困惑的問題。"},{"en":"If herders left almost no herd-animal remains, archaeologists must explain why.","zh":"如果牧民幾乎沒有留下牲畜遺骸，考古學家必須解釋原因。"},{"en":"This phrase describes a question that invites investigation.","zh":"這個片語描述引人調查的問題。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":3},{"front":"among thousands of","meaning":"在數千個……之中","examples":[{"en":"Among thousands of animal bones, the team found very few herd animals.","zh":"在數千個動物骨骼之中，團隊發現很少牲畜。"},{"en":"Among thousands of something means within a very large number of items.","zh":"among thousands of something 指在非常大量的項目之中。"},{"en":"Among thousands of applications, only a few students may receive the scholarship.","zh":"在數千份申請之中，可能只有少數學生獲得獎學金。"},{"en":"If only three cow skeletons appear among thousands of bones, the finding is surprising.","zh":"如果數千塊骨頭中只有三副牛骨架，這個發現令人意外。"},{"en":"This phrase highlights contrast between a large total and a small part.","zh":"這個片語突出龐大總數與小部分之間的對比。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":3},{"front":"animal bones","meaning":"動物骨骼","examples":[{"en":"Thousands of animal bones were excavated at Gobero.","zh":"數千塊動物骨骼在戈貝羅被挖掘出來。"},{"en":"Animal bones are bones from animals, often studied to learn about diet, hunting, herding or environment.","zh":"animal bones 是來自動物的骨骼，常被研究以了解飲食、狩獵、畜牧或環境。"},{"en":"Archaeologists may identify animal bones to see whether people ate fish, cattle or wild animals.","zh":"考古學家可能識別動物骨骼，以了解人們吃魚、牛還是野生動物。"},{"en":"If many animal bones are found, they can reveal what species once lived nearby.","zh":"如果發現許多動物骨骼，它們可以揭示附近曾有哪些物種生活。"},{"en":"This phrase refers to physical evidence from animals.","zh":"這個片語指來自動物的實體證據。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":3},{"front":"cow skeletons","meaning":"牛骨架","examples":[{"en":"The team found only three cow skeletons.","zh":"團隊只發現三副牛骨架。"},{"en":"Cow skeletons are the bone structures left from cows after death.","zh":"cow skeletons 是牛死亡後留下的骨架結構。"},{"en":"A farm museum may display cow skeletons to teach children about animal anatomy.","zh":"農場博物館可能展示牛骨架，教孩子認識動物解剖結構。"},{"en":"If only a few cow skeletons are found at a site, cattle may not have been commonly killed there.","zh":"如果遺址只發現少量牛骨架，牛可能並不常在那裡被宰殺。"},{"en":"This phrase identifies remains from cattle.","zh":"這個片語指出來自牛隻的遺骸。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":3},{"front":"no remains of","meaning":"沒有……的遺骸","examples":[{"en":"The team found no remains of goats or sheep.","zh":"團隊沒有發現山羊或綿羊的遺骸。"},{"en":"No remains of something means no physical traces or surviving parts of it were found.","zh":"no remains of something 指沒有找到某物的實體痕跡或殘留部分。"},{"en":"After a fire, investigators may find no remains of the old wooden furniture.","zh":"火災後，調查人員可能找不到舊木家具的遺骸。"},{"en":"If archaeologists find no remains of herd animals, they may question whether herding was fully practised.","zh":"如果考古學家沒有發現牲畜遺骸，可能會質疑畜牧是否已被完全實行。"},{"en":"This phrase uses absence of evidence as an important clue.","zh":"這個片語把缺乏證據本身視為重要線索。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":3},{"front":"goats or sheep","meaning":"山羊或綿羊","examples":[{"en":"No remains of goats or sheep were found at Gobero.","zh":"在戈貝羅沒有發現山羊或綿羊的遺骸。"},{"en":"Goats or sheep are common herd animals often kept for meat, milk, wool or hides.","zh":"goats or sheep 是常見牲畜，常被飼養以取得肉、奶、羊毛或獸皮。"},{"en":"A herder may move goats or sheep to new grazing land when grass becomes scarce.","zh":"當草變得稀少時，牧民可能把山羊或綿羊趕到新的放牧地。"},{"en":"If a site has no goat or sheep bones, researchers may question how important herding was there.","zh":"如果遺址沒有山羊或綿羊骨，研究人員可能質疑畜牧在當地有多重要。"},{"en":"This phrase refers to typical livestock animals.","zh":"這個片語指典型牲畜。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":3},{"front":"note that","meaning":"指出","examples":[{"en":"Garcea noted that herding people do not commonly kill their cattle.","zh":"Garcea 指出畜牧民族通常不會殺牛。"},{"en":"To note that means to point out or mention something as important.","zh":"note that 指指出或提及某件重要事情。"},{"en":"A teacher may note that the essay has good ideas but weak organisation.","zh":"老師可能指出文章有好想法，但組織較弱。"},{"en":"If an expert notes a cultural habit, it can help explain unusual evidence.","zh":"如果專家指出某種文化習慣，它可以幫助解釋不尋常證據。"},{"en":"This phrase introduces an observation or important comment.","zh":"這個片語引入觀察或重要評論。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":3},{"front":"herding people","meaning":"畜牧民族","examples":[{"en":"Herding people do not commonly kill their cattle in cemeteries.","zh":"畜牧民族通常不會在墓地殺牛。"},{"en":"Herding people are groups whose lives are based mainly on raising and moving livestock.","zh":"herding people 是生活主要以飼養和遷移牲畜為基礎的群體。"},{"en":"Herding people may value cattle as wealth, food security and social status.","zh":"畜牧民族可能把牛隻視為財富、食物保障和社會地位。"},{"en":"If herding people rarely kill their animals, few livestock bones may appear at burial sites.","zh":"如果畜牧民族很少宰殺自己的牲畜，墓地中可能只出現少量牲畜骨骼。"},{"en":"This phrase describes people whose economy centres on animals.","zh":"這個片語描述經濟以動物為中心的人群。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":3},{"front":"cattle","meaning":"牛隻","examples":[{"en":"Garcea noted that herding people rarely kill their cattle.","zh":"Garcea 指出畜牧民族很少殺自己的牛隻。"},{"en":"Cattle are large farm animals, especially cows and bulls, kept for meat, milk, labour or wealth.","zh":"cattle 是大型農場動物，尤其指牛和公牛，為肉、奶、勞力或財富而飼養。"},{"en":"A farmer may move cattle to another field when the grass is eaten down.","zh":"當草被吃光時，農民可能把牛隻趕到另一塊田。"},{"en":"If cattle are valuable, herders may avoid slaughtering them except on special occasions.","zh":"如果牛隻很有價值，牧民可能避免宰殺牠們，除非在特殊場合。"},{"en":"This word refers to cows and related herd animals collectively.","zh":"這個詞集合地指牛和相關牲畜。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":3},{"front":"particularly in","meaning":"尤其是在……","examples":[{"en":"Herding people rarely kill cattle, particularly in a cemetery.","zh":"畜牧民族很少殺牛，尤其是在墓地。"},{"en":"Particularly in means especially in a certain place, situation or condition.","zh":"particularly in 指尤其在某個地方、情況或條件下。"},{"en":"Students should speak quietly, particularly in the library.","zh":"學生應保持安靜，尤其是在圖書館。"},{"en":"If cattle are valuable, killing them is unusual, especially in a burial place.","zh":"如果牛隻很有價值，宰殺牠們並不尋常，尤其是在墓葬地點。"},{"en":"This phrase highlights a specific situation where the point is especially true.","zh":"這個片語突出某一特定情況下重點尤其成立。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":3},{"front":"cemetery","meaning":"墓地","examples":[{"en":"Garcea found it unusual to find cattle remains in a cemetery.","zh":"Garcea 覺得在墓地發現牛隻遺骸很不尋常。"},{"en":"A cemetery is a place where dead people are buried.","zh":"cemetery 是埋葬死者的地方。"},{"en":"Families may visit a cemetery to remember relatives who have died.","zh":"家庭可能到墓地探望並紀念已故親人。"},{"en":"If animal bones are found in a cemetery, they may be linked to rituals, offerings or unusual events.","zh":"如果在墓地發現動物骨骼，它們可能與儀式、祭品或不尋常事件有關。"},{"en":"This word refers to a burial ground for people.","zh":"這個詞指埋葬人類的地方。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":4},{"front":"modern pastoralists","meaning":"現代牧民","examples":[{"en":"Modern pastoralists such as Niger’s Wodaabe avoid slaughtering herd animals.","zh":"現代牧民，例如尼日爾的 Wodaabe，避免宰殺牲畜。"},{"en":"Modern pastoralists are present-day people who raise and move livestock as a major part of life.","zh":"modern pastoralists 是今天以飼養和遷移牲畜為生活重要部分的人。"},{"en":"Modern pastoralists may move cattle seasonally to find water and grass.","zh":"現代牧民可能按季節遷移牛群，以尋找水和草。"},{"en":"If modern pastoralists value herd animals highly, they may kill them only when necessary.","zh":"如果現代牧民高度重視牲畜，他們可能只在必要時宰殺牠們。"},{"en":"This phrase connects present-day herders with ancient herding practices.","zh":"這個片語把現代牧民與古代畜牧做法連接起來。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":4},{"front":"be reluctant to","meaning":"不願意","examples":[{"en":"Modern pastoralists are reluctant to slaughter animals from their herds.","zh":"現代牧民不願意宰殺自己牲畜群中的動物。"},{"en":"To be reluctant to do something means to be unwilling or hesitant to do it.","zh":"be reluctant to do something 指不願意或猶豫去做某事。"},{"en":"A student may be reluctant to ask a question if they fear classmates will laugh.","zh":"如果學生害怕同學取笑，可能不願意提問。"},{"en":"If animals are valuable, herders may be reluctant to slaughter them.","zh":"如果動物很有價值，牧民可能不願意宰殺牠們。"},{"en":"This phrase describes hesitation or unwillingness.","zh":"這個片語描述猶豫或不情願。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":4},{"front":"slaughter animals","meaning":"宰殺動物","examples":[{"en":"Pastoralists are often reluctant to slaughter animals from their herds.","zh":"牧民常不願意宰殺自己牲畜群中的動物。"},{"en":"To slaughter animals means to kill animals, usually for food or ritual purposes.","zh":"slaughter animals 指殺死動物，通常為食物或儀式目的。"},{"en":"A farm may slaughter animals only when they are needed for meat production.","zh":"農場可能只在肉類生產需要時宰殺動物。"},{"en":"If animals are central to wealth and survival, people may avoid slaughtering them frequently.","zh":"如果動物對財富和生存很重要，人們可能避免頻繁宰殺牠們。"},{"en":"This phrase is direct and often used in farming or food contexts.","zh":"這個片語較直接，常用於畜牧或食物語境。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":4},{"front":"from their herds","meaning":"從他們的牲畜群中","examples":[{"en":"Pastoralists avoid slaughtering animals from their herds.","zh":"牧民避免從他們的牲畜群中宰殺動物。"},{"en":"From their herds means belonging to the groups of animals they own or look after.","zh":"from their herds 指屬於他們擁有或照顧的牲畜群。"},{"en":"A herder may choose a weak goat from the herd if an animal must be sold.","zh":"如果必須出售動物，牧民可能從牲畜群中選一隻較弱的山羊。"},{"en":"If animals come from their own herds, killing them may reduce wealth and future food supply.","zh":"如果動物來自自己的牲畜群，宰殺牠們可能減少財富和未來食物供應。"},{"en":"This phrase identifies the animals as part of a herder’s livestock group.","zh":"這個片語指出動物屬於牧民的牲畜群。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":4},{"front":"suggest that","meaning":"提出；認為","examples":[{"en":"Sereno suggested that the Tenerians may have formed a transitional group.","zh":"Sereno 提出特內里安人可能形成一個過渡群體。"},{"en":"Suggest that can mean to propose an idea or explanation for others to consider.","zh":"suggest that 可以指提出一個想法或解釋，讓其他人考慮。"},{"en":"A teacher may suggest that students read the question twice before choosing an answer.","zh":"老師可能建議學生在選答案前把題目讀兩次。"},{"en":"If evidence is incomplete, researchers may suggest a possible explanation rather than claim certainty.","zh":"如果證據不完整，研究人員可能提出可能解釋，而不是聲稱確定。"},{"en":"This phrase introduces a cautious proposal or interpretation.","zh":"這個片語引入謹慎的提議或詮釋。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":4},{"front":"transitional group","meaning":"過渡群體","examples":[{"en":"The Tenerians at Gobero may have been a transitional group.","zh":"戈貝羅的特內里安人可能是一個過渡群體。"},{"en":"A transitional group is a group in the middle of changing from one way of life to another.","zh":"transitional group 是正處於從一種生活方式轉向另一種生活方式之間的群體。"},{"en":"A village moving from farming to factory work may be a transitional community.","zh":"從農業轉向工廠工作的村莊，可能是一個過渡社群。"},{"en":"If the Tenerians still hunted and fished but began herding, they may represent a shift between lifestyles.","zh":"如果特內里安人仍狩獵和捕魚，但開始畜牧，他們可能代表生活方式之間的轉變。"},{"en":"This phrase describes a group between two stages or systems.","zh":"這個片語描述處於兩個階段或制度之間的群體。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":4},{"front":"rely heavily on","meaning":"很大程度上依賴","examples":[{"en":"The Tenerians may have relied heavily on hunting and fishing.","zh":"特內里安人可能很大程度上依賴狩獵和捕魚。"},{"en":"To rely heavily on something means to depend on it very much.","zh":"rely heavily on something 指非常依賴某事物。"},{"en":"A student who lives far from school may rely heavily on public transport.","zh":"住得離學校很遠的學生可能很大程度上依賴公共交通。"},{"en":"If a community relies heavily on fishing, a dry climate can threaten its food supply.","zh":"如果社群很大程度上依賴捕魚，乾旱氣候可能威脅其食物供應。"},{"en":"This phrase shows strong dependence.","zh":"這個片語顯示強烈依賴。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":4},{"front":"hunting and fishing","meaning":"狩獵和捕魚","examples":[{"en":"The group may still have depended on hunting and fishing.","zh":"這個群體可能仍依賴狩獵和捕魚。"},{"en":"Hunting and fishing are ways of getting food by catching wild animals and fish.","zh":"hunting and fishing 是透過捕捉野生動物和魚類取得食物的方法。"},{"en":"Some rural families may use hunting and fishing to add food to their diet.","zh":"一些鄉郊家庭可能透過狩獵和捕魚增加食物來源。"},{"en":"If people depend on hunting and fishing, changes in animal populations or water levels can affect survival.","zh":"如果人們依賴狩獵和捕魚，動物數量或水位變化會影響生存。"},{"en":"This phrase describes two food-gathering activities.","zh":"這個片語描述兩種取得食物的活動。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":4},{"front":"fully adopt","meaning":"完全採用","examples":[{"en":"The Tenerians may not have fully adopted herding.","zh":"特內里安人可能尚未完全採用畜牧。"},{"en":"To fully adopt something means to accept and use it completely as a regular practice.","zh":"fully adopt something 指完全接受並定期使用某做法。"},{"en":"A school may not fully adopt online homework until all students have Internet access.","zh":"在所有學生都有互聯網前，學校可能不會完全採用網上功課。"},{"en":"If a group only partly adopts herding, older habits like hunting and fishing may continue.","zh":"如果一個群體只是部分採用畜牧，狩獵和捕魚等舊習慣可能繼續。"},{"en":"This phrase shows complete acceptance of a new practice.","zh":"這個片語顯示對新做法的完全接受。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":4},{"front":"adopted herding","meaning":"採用畜牧","examples":[{"en":"The group had not fully adopted herding.","zh":"這個群體尚未完全採用畜牧。"},{"en":"Adopted herding means began to use animal raising as a way of life or food production.","zh":"adopted herding 指開始把飼養動物作為生活方式或食物生產方式。"},{"en":"A community may have adopted herding when farming became difficult because of drought.","zh":"當旱災令耕種變得困難，社群可能採用畜牧。"},{"en":"If people adopted herding gradually, their old hunting habits might remain for generations.","zh":"如果人們逐漸採用畜牧，舊有狩獵習慣可能仍延續幾代。"},{"en":"This phrase describes taking up pastoral life.","zh":"這個片語描述開始採取牧民生活方式。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":4},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"The task asks whether the statements agree with the information in the passage.","zh":"任務要求判斷以下陳述是否與文章中的資料一致。"},{"en":"Do the following statements agree with asks students to judge whether each statement matches the text.","zh":"do the following statements agree with 要求學生判斷每個陳述是否與文本相符。"},{"en":"In reading tests, students should check exact meaning before deciding whether a statement agrees.","zh":"在閱讀測驗中，學生應檢查確切意思，再判斷陳述是否一致。"},{"en":"If a statement changes a detail from the passage, it may not agree with the information.","zh":"如果陳述改變文章中的細節，它可能與資料不一致。"},{"en":"This phrase is a common instruction for TRUE, FALSE and NOT GIVEN questions.","zh":"這個片語是 TRUE、FALSE 和 NOT GIVEN 題的常見指示。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":5},{"front":"information given in","meaning":"……中提供的資料","examples":[{"en":"Students compare each statement with the information given in the passage.","zh":"學生把每個陳述與文章中提供的資料比較。"},{"en":"Information given in something means the facts or details provided inside that text or source.","zh":"information given in something 指該文本或來源中提供的事實或細節。"},{"en":"Students should answer according to the information given in the notice, not what they assume.","zh":"學生應根據通告中提供的資料作答，而不是根據自己的假設。"},{"en":"If the passage gives no information on a claim, students should not use outside knowledge.","zh":"如果文章沒有提供某主張的資料，學生不應使用外部知識。"},{"en":"This phrase keeps the answer grounded in the text.","zh":"這個片語令答案緊扣文本。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":5},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"Candidates write their responses on the answer sheet.","zh":"考生把答案寫在答題紙上。"},{"en":"An answer sheet is the paper or digital form where students record their answers in a test.","zh":"answer sheet 是學生在測驗中記錄答案的紙張或電子表格。"},{"en":"A student may lose marks if the correct answer is written in the booklet but not on the answer sheet.","zh":"如果正確答案寫在題目簿上但沒有寫在答題紙上，學生可能失分。"},{"en":"If the answer sheet requires letters, students should not write long sentences.","zh":"如果答題紙要求寫字母，學生不應寫長句。"},{"en":"This phrase refers to the official place for final answers.","zh":"這個片語指正式填寫最終答案的地方。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":5},{"front":"the statement agrees with","meaning":"陳述與……一致","examples":[{"en":"A statement agrees with the passage when it matches the information.","zh":"當陳述符合資料時，該陳述與文章一致。"},{"en":"The statement agrees with means the statement has the same meaning as the text.","zh":"the statement agrees with 指陳述與文本意思相同。"},{"en":"If a notice says school starts at eight and a statement says lessons begin at eight, the statement agrees with it.","zh":"如果通告說學校八點開始，而陳述說課堂八點開始，該陳述與它一致。"},{"en":"If the statement adds something not mentioned, it may not truly agree with the passage.","zh":"如果陳述加入未提及的內容，它未必真正與文章一致。"},{"en":"This phrase is used to judge meaning in reading tasks.","zh":"這個片語用於閱讀題中判斷意思。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":5},{"front":"contradict the information","meaning":"與資料矛盾","examples":[{"en":"A statement contradicts the information if it says the opposite.","zh":"如果陳述說出相反內容，它就與資料矛盾。"},{"en":"To contradict the information means to disagree with or oppose what the text says.","zh":"contradict the information 指與文本所說內容不一致或相反。"},{"en":"If the text says the team returned in 2006, saying they never returned contradicts the information.","zh":"如果文本說團隊在2006年返回，說他們從未返回便與資料矛盾。"},{"en":"Students should choose FALSE when the statement clearly says the opposite of the passage.","zh":"當陳述清楚說出文章相反意思時，學生應選 FALSE。"},{"en":"This phrase is different from NOT GIVEN because the text provides conflicting evidence.","zh":"這個片語不同於 NOT GIVEN，因為文本提供相反證據。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":5},{"front":"there is no information on this","meaning":"文中沒有相關資料","examples":[{"en":"Students choose the option when there is no information on this in the passage.","zh":"當文中沒有相關資料時，學生選擇該選項。"},{"en":"There is no information on this means the passage does not give enough detail to confirm or deny the statement.","zh":"there is no information on this 指文章沒有提供足夠細節去確認或否定陳述。"},{"en":"If a passage discusses bones but not the researchers’ salaries, there is no information on salaries.","zh":"如果文章討論骨骼但沒有討論研究人員薪酬，文中就沒有薪酬的相關資料。"},{"en":"When there is no information, students should not guess from general knowledge.","zh":"當沒有相關資料時，學生不應根據常識猜測。"},{"en":"This phrase usually points to a NOT GIVEN answer.","zh":"這個片語通常指向 NOT GIVEN 答案。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":5},{"front":"rock engravings","meaning":"岩石刻畫","examples":[{"en":"The question mentions rock engravings found in the Green Sahara.","zh":"題目提到在綠色撒哈拉發現的岩石刻畫。"},{"en":"Rock engravings are images or marks carved into rock surfaces by people in the past.","zh":"rock engravings 是過去人類刻在岩石表面的圖像或標記。"},{"en":"Archaeologists may study rock engravings to learn about animals, rituals or daily life.","zh":"考古學家可能研究岩石刻畫，以了解動物、儀式或日常生活。"},{"en":"If rock engravings show cattle, they may suggest herding or the importance of animals.","zh":"如果岩石刻畫顯示牛隻，它們可能暗示畜牧或動物的重要性。"},{"en":"This phrase refers to carved visual evidence on stone.","zh":"這個片語指石頭上的雕刻視覺證據。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":5},{"front":"the Green Sahara","meaning":"綠色撒哈拉","examples":[{"en":"The Green Sahara refers to a wetter period in the Sahara’s past.","zh":"綠色撒哈拉指撒哈拉過去較濕潤的時期。"},{"en":"The Green Sahara means the time when parts of the Sahara had more water, plants and animal life than today.","zh":"Green Sahara 指撒哈拉部分地區曾比今天有更多水、植物和動物生命的時期。"},{"en":"Students may be surprised to learn that the Green Sahara once supported lakes and people.","zh":"學生可能驚訝地得知綠色撒哈拉曾支持湖泊和人類生活。"},{"en":"If the Sahara was once green, ancient communities could fish, hunt and live there more easily.","zh":"如果撒哈拉曾經綠化，古代社群便能更容易在那裡捕魚、狩獵和生活。"},{"en":"This phrase contrasts the Sahara’s wetter past with its dry present.","zh":"這個片語把撒哈拉較濕潤的過去與乾旱的現在作對比。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":5},{"front":"be similar to","meaning":"與……相似","examples":[{"en":"The question asks whether the engravings are similar to those in other places.","zh":"題目問這些刻畫是否與其他地方的刻畫相似。"},{"en":"To be similar to something means to share features or qualities with it.","zh":"be similar to something 指與某物共享特徵或質素。"},{"en":"A student’s answer may be similar to the model answer if it uses the same structure.","zh":"如果學生答案使用相同結構，它可能與範文相似。"},{"en":"If rock engravings in different regions are similar, they may show shared ideas or contact.","zh":"如果不同地區的岩石刻畫相似，它們可能顯示共同想法或接觸。"},{"en":"This phrase compares likeness between two things.","zh":"這個片語比較兩者之間的相似性。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":5},{"front":"in other places","meaning":"在其他地方","examples":[{"en":"The statement compares the engravings with those in other places.","zh":"該陳述把這些刻畫與其他地方的刻畫比較。"},{"en":"In other places means in different locations or regions.","zh":"in other places 指在不同地點或地區。"},{"en":"A rule that works in one school may not work in other places.","zh":"在一間學校有效的規則，在其他地方未必有效。"},{"en":"If similar artefacts are found in other places, researchers may compare cultural connections.","zh":"如果在其他地方發現相似文物，研究人員可能比較文化連繫。"},{"en":"This phrase moves attention beyond the current location.","zh":"這個片語把注意力移到目前地點之外。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":5},{"front":"a fertile area","meaning":"肥沃地區","examples":[{"en":"The question asks whether the Ténéré Desert was once a fertile area.","zh":"題目問泰內雷沙漠是否曾經是肥沃地區。"},{"en":"A fertile area is land that can support plant growth, farming or abundant life.","zh":"fertile area 是能支持植物生長、耕種或豐富生命的土地。"},{"en":"A river valley is often a fertile area because floods leave rich soil behind.","zh":"河谷常是肥沃地區，因為洪水會留下肥沃土壤。"},{"en":"If a desert was once fertile, people and animals could have lived there in greater numbers.","zh":"如果沙漠曾經肥沃，人和動物可能曾以更多數量生活在那裡。"},{"en":"This phrase contrasts productive land with barren land.","zh":"這個片語把有生產力的土地與荒蕪土地作對比。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":5},{"front":"archaeological projects","meaning":"考古項目","examples":[{"en":"The question refers to archaeological projects about ancient Saharan people.","zh":"題目提及關於古代撒哈拉人的考古項目。"},{"en":"Archaeological projects are organised studies that investigate past human life through remains, sites and artefacts.","zh":"archaeological projects 是透過遺骸、遺址和文物調查過去人類生活的有組織研究。"},{"en":"A university may run archaeological projects to study old villages before new buildings are constructed.","zh":"大學可能在新建築施工前進行考古項目，研究舊村落。"},{"en":"If archaeological projects are well planned, they can protect fragile evidence while collecting information.","zh":"如果考古項目規劃良好，它們可以在收集資料時保護脆弱證據。"},{"en":"This phrase refers to research projects about the human past.","zh":"這個片語指關於人類過去的研究項目。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":6},{"front":"before studying","meaning":"在研究……之前","examples":[{"en":"The statement asks whether the researchers had worked together before studying the Sahara site.","zh":"該陳述問研究人員在研究撒哈拉遺址之前是否曾合作。"},{"en":"Before studying means before beginning research or investigation into a topic or place.","zh":"before studying 指在開始研究或調查某主題或地點之前。"},{"en":"Students should read the instructions before studying the chart in detail.","zh":"學生應先閱讀指示，再仔細研究圖表。"},{"en":"If two researchers had not met before studying a site, their collaboration began with that project.","zh":"如果兩名研究人員在研究遺址前從未見面，他們的合作便始於該項目。"},{"en":"This phrase gives the time before a research activity.","zh":"這個片語給出研究活動之前的時間。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":6},{"front":"answer the questions below","meaning":"回答以下問題","examples":[{"en":"Candidates answer the questions below using words from the passage.","zh":"考生使用篇章中的字詞回答以下問題。"},{"en":"Answer the questions below means respond to the questions that follow the instruction.","zh":"answer the questions below 指回答指示後面列出的問題。"},{"en":"In a reading test, students should answer the questions below only after locating evidence in the text.","zh":"在閱讀測驗中，學生應先在文本中定位證據，再回答以下問題。"},{"en":"If the instruction says to use words from the passage, candidates should not invent new wording.","zh":"如果指示說要使用篇章中的字詞，考生不應自行創作新措辭。"},{"en":"This phrase is a standard exam instruction.","zh":"這個片語是標準考試指示。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":6},{"front":"no more than three words and/or a number","meaning":"不多於三個字及／或一個數字","examples":[{"en":"The instructions allow no more than three words and/or a number.","zh":"指示容許不多於三個字及／或一個數字。"},{"en":"No more than three words and/or a number means the answer may contain up to three words and may also include one number.","zh":"no more than three words and/or a number 指答案最多可包含三個英文詞，並可包括一個數字。"},{"en":"If the answer is “about 6,000 years”, it follows the word-and-number limit.","zh":"如果答案是 “about 6,000 years”，它符合字詞和數字限制。"},{"en":"If candidates write too many words, they may lose marks even when the idea is correct.","zh":"如果考生寫太多字，即使意思正確也可能失分。"},{"en":"This phrase sets a strict answer-length rule.","zh":"這個片語設定嚴格的答案長度規則。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":6},{"front":"from the passage","meaning":"從篇章中","examples":[{"en":"Answers must be chosen from the passage.","zh":"答案必須從篇章中選取。"},{"en":"From the passage means the answer should come directly from the reading text.","zh":"from the passage 指答案應直接來自閱讀文本。"},{"en":"Students should copy the exact word from the passage if the question requires it.","zh":"如果題目要求，學生應從篇章中抄下確切字詞。"},{"en":"If the passage does not mention the answer, outside knowledge should not be used.","zh":"如果篇章沒有提及答案，就不應使用外部知識。"},{"en":"This phrase keeps answers based on the text.","zh":"這個片語令答案建基於文本。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":6},{"front":"initial weeks","meaning":"最初幾個星期","examples":[{"en":"The question asks what the team produced during the initial weeks.","zh":"題目問團隊在最初幾個星期製作了甚麼。"},{"en":"Initial weeks means the first few weeks of a project, trip or process.","zh":"initial weeks 指項目、旅程或過程開始的頭幾個星期。"},{"en":"During the initial weeks of a course, students learn the basic rules and expectations.","zh":"在課程最初幾個星期，學生學習基本規則和要求。"},{"en":"If researchers map a site in the initial weeks, later excavation can be more organised.","zh":"如果研究人員在最初幾個星期繪製遺址地圖，之後挖掘可以更有組織。"},{"en":"This phrase refers to the early stage of an activity.","zh":"這個片語指活動的早期階段。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":6},{"front":"before excavation began","meaning":"挖掘開始前","examples":[{"en":"The team mapped the site before excavation began.","zh":"團隊在挖掘開始前繪製了遺址地圖。"},{"en":"Before excavation began means before digging at the site started.","zh":"before excavation began 指遺址挖掘工作開始之前。"},{"en":"Builders may survey land before construction begins to avoid mistakes.","zh":"建築工人在施工開始前可能先測量土地，以避免錯誤。"},{"en":"If archaeologists map a site before excavation begins, they can record where everything is located.","zh":"如果考古學家在挖掘開始前繪製遺址地圖，就能記錄所有東西的位置。"},{"en":"This phrase gives the stage before digging work.","zh":"這個片語給出挖掘工作之前的階段。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":6},{"front":"research centre","meaning":"研究中心","examples":[{"en":"The question asks what was sent to the research centre.","zh":"題目問甚麼被送到研究中心。"},{"en":"A research centre is an organisation or place where specialists investigate questions and analyse evidence.","zh":"research centre 是專家調查問題和分析證據的機構或地方。"},{"en":"A hospital may send samples to a research centre for advanced testing.","zh":"醫院可能把樣本送到研究中心進行高階測試。"},{"en":"If teeth are sent to a research centre, scientists can use equipment not available at the field site.","zh":"如果牙齒被送到研究中心，科學家可以使用田野地點沒有的設備。"},{"en":"This phrase refers to a place for specialised study.","zh":"這個片語指進行專門研究的地方。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":6},{"front":"estimated to be","meaning":"估計為","examples":[{"en":"The question asks how old the larger burials were estimated to be.","zh":"題目問較大墓葬的年代估計為多少。"},{"en":"Estimated to be means judged to be approximately a certain amount based on evidence.","zh":"estimated to be 指根據證據判斷大約為某個數量。"},{"en":"The repair cost was estimated to be around two thousand dollars.","zh":"維修費用估計為約二千美元。"},{"en":"If a burial is estimated to be 9,000 years old, the age is not exact but evidence-based.","zh":"如果墓葬估計為九千年歷史，該年代不是完全精確，但有證據支持。"},{"en":"This phrase is used when giving an informed approximation.","zh":"這個片語用於給出有根據的估算。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":6},{"front":"complete the notes below","meaning":"完成以下筆記","examples":[{"en":"Candidates complete the notes below using words from the passage.","zh":"考生使用篇章中的字詞完成以下筆記。"},{"en":"Complete the notes below means fill in the missing information in the notes that follow.","zh":"complete the notes below 指填寫下面筆記中缺少的資料。"},{"en":"Students should complete the notes below after identifying the correct paragraph in the passage.","zh":"學生應在找出篇章中正確段落後，完成以下筆記。"},{"en":"If the notes summarise a culture, answers must fit both meaning and grammar.","zh":"如果筆記概括某種文化，答案必須同時符合意思和文法。"},{"en":"This phrase is a common reading-test instruction.","zh":"這個片語是常見閱讀測驗指示。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":6},{"front":"one word only","meaning":"只限一個字","examples":[{"en":"The instructions require one word only for each answer.","zh":"指示要求每個答案只限一個字。"},{"en":"One word only means each answer must contain exactly one word, not two or more.","zh":"one word only 指每個答案必須只包含一個英文詞，不能有兩個或更多。"},{"en":"If the answer is “fishing”, writing “by fishing” would break a one-word-only rule.","zh":"如果答案是 “fishing”，寫 “by fishing” 就會違反只限一個字的規則。"},{"en":"Students should count words carefully because extra words can make a correct idea wrong.","zh":"學生應仔細數字數，因為多餘字詞會令正確意思變錯。"},{"en":"This phrase sets the strictest common word limit in completion tasks.","zh":"這個片語設定填充題中最嚴格的常見字數限制。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":6},{"front":"culture and findings","meaning":"文化與發現","examples":[{"en":"The notes organise information under culture and findings.","zh":"筆記按文化與發現整理資料。"},{"en":"Culture and findings means the table groups information by cultural group and the evidence discovered about it.","zh":"culture and findings 指表格按文化群體和有關它的證據發現來分類資料。"},{"en":"A history worksheet may organise notes under “period” and “evidence” to help students compare clearly.","zh":"歷史工作紙可能按「時期」和「證據」整理筆記，以幫助學生清楚比較。"},{"en":"If findings are placed under each culture, students can see which evidence belongs to which group.","zh":"如果發現被放在每種文化之下，學生就能看出哪些證據屬於哪個群體。"},{"en":"This phrase describes how information is organised.","zh":"這個片語描述資訊如何被組織。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":7},{"front":"peaceful and industrious","meaning":"和平而勤勞","examples":[{"en":"The notes describe the Kiffians as peaceful and industrious.","zh":"筆記把基菲安人描述為和平而勤勞。"},{"en":"Peaceful and industrious means not violent and very hardworking.","zh":"peaceful and industrious 指不暴力並且非常勤奮。"},{"en":"A peaceful and industrious community may solve disputes calmly and work hard to maintain farms or shops.","zh":"和平而勤勞的社區可能冷靜解決爭端，並努力維持農場或店舖。"},{"en":"If skeletons show few injuries but strong muscles, researchers may describe people as peaceful and industrious.","zh":"如果骸骨顯示很少傷痕但肌肉強壯，研究人員可能把人們描述為和平而勤勞。"},{"en":"This phrase combines social behaviour with work habits.","zh":"這個片語結合社會行為和工作習慣。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":7},{"front":"researcher found no injuries","meaning":"研究人員沒有發現傷痕","examples":[{"en":"The researcher found no injuries on their heads or forearms.","zh":"研究人員在他們的頭部或前臂沒有發現傷痕。"},{"en":"Researcher found no injuries means the expert did not see wounds or damage on the examined bones.","zh":"researcher found no injuries 指專家在檢查的骨骼上沒有看到傷口或損傷。"},{"en":"A doctor may find no injuries after checking a child who fell from a chair.","zh":"醫生檢查從椅子跌下的孩子後，可能沒有發現傷痕。"},{"en":"If no injuries appear on defensive body parts, violent fighting may have been uncommon.","zh":"如果防禦性身體部位沒有傷痕，暴力打鬥可能並不常見。"},{"en":"This phrase describes a negative finding that still provides evidence.","zh":"這個片語描述負面發現，但它仍能提供證據。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":7},{"front":"infer that","meaning":"推斷","examples":[{"en":"Researchers inferred that the diet contained plenty of protein.","zh":"研究人員推斷飲食含有大量蛋白質。"},{"en":"To infer that means to reach a conclusion by using evidence and reasoning.","zh":"infer that 指使用證據和推理得出結論。"},{"en":"A teacher may infer that a student was tired if the work has many careless mistakes.","zh":"如果功課有很多粗心錯誤，老師可能推斷學生很疲倦。"},{"en":"If bones show certain chemical signs, scientists can infer what people ate.","zh":"如果骨骼顯示某些化學跡象，科學家可以推斷人們吃甚麼。"},{"en":"This phrase means concluding indirectly rather than being told directly.","zh":"這個片語指間接得出結論，而不是被直接告知。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":7},{"front":"contain plenty of","meaning":"含有大量……","examples":[{"en":"The diet appeared to contain plenty of protein.","zh":"這種飲食似乎含有大量蛋白質。"},{"en":"To contain plenty of something means to have a large amount of it.","zh":"contain plenty of something 指含有大量某物。"},{"en":"Beans and eggs contain plenty of protein for people who do not eat much meat.","zh":"豆類和雞蛋含有大量蛋白質，適合不常吃肉的人。"},{"en":"If a diet contains plenty of fish, it may leave signs of high protein intake in bones.","zh":"如果飲食含有大量魚類，它可能在骨骼中留下高蛋白攝取的跡象。"},{"en":"This phrase describes having more than enough of something.","zh":"這個片語描述某物含量充足甚至很多。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":7},{"front":"prefer herding over hunting","meaning":"較喜歡畜牧而非狩獵","examples":[{"en":"Stojanowski believed that the Tenerians preferred herding over hunting.","zh":"Stojanowski 認為特內里安人較喜歡畜牧而非狩獵。"},{"en":"To prefer herding over hunting means to choose raising animals rather than hunting wild animals.","zh":"prefer herding over hunting 指選擇飼養動物，而不是狩獵野生動物。"},{"en":"A family may prefer cooking at home over eating out because it is cheaper and healthier.","zh":"家庭可能較喜歡在家煮飯而非外出用餐，因為更便宜和健康。"},{"en":"If climate change made wild animals scarce, people may have preferred herding for reliability.","zh":"如果氣候變化令野生動物稀少，人們可能因可靠性而較喜歡畜牧。"},{"en":"This phrase clearly compares two choices and shows which one is favoured.","zh":"這個片語清楚比較兩個選擇，並顯示較偏好哪一個。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":7},{"front":"isolated bones","meaning":"零散的骨頭","examples":[{"en":"The question refers to isolated animal bones found at the site.","zh":"題目指遺址中發現的零散動物骨頭。"},{"en":"Isolated bones are separate bones found apart from a complete skeleton or large group.","zh":"isolated bones 是與完整骨架或大型骨群分開發現的單獨骨頭。"},{"en":"Archaeologists may find isolated bones scattered by wind, water or animal activity.","zh":"考古學家可能發現被風、水或動物活動分散的零散骨頭。"},{"en":"If only isolated bones are found, it may be harder to identify the full animal or event.","zh":"如果只發現零散骨頭，就可能較難識別完整動物或事件。"},{"en":"This phrase describes bones found separately rather than as a complete body.","zh":"這個片語描述分開發現而非完整身體的一些骨頭。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":7},{"front":"animals such as","meaning":"例如……的動物","examples":[{"en":"The notes mention animals such as cattle, goats and sheep.","zh":"筆記提到例如牛、山羊和綿羊的動物。"},{"en":"Animals such as introduces examples of animals within a larger group.","zh":"animals such as 用來引入較大群體中的動物例子。"},{"en":"Children may see farm animals such as chickens, pigs and cows on a school visit.","zh":"孩子在學校參觀中可能看到雞、豬和牛等農場動物。"},{"en":"If a text says animals such as goats and sheep, it is giving examples rather than a complete list.","zh":"如果文本說山羊和綿羊等動物，它是在給出例子，而不是完整清單。"},{"en":"This phrase is useful for introducing examples.","zh":"這個片語適合用來引入例子。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":7},{"front":"form a transitional group","meaning":"形成一個過渡群體","examples":[{"en":"Sereno suggested that the Tenerians formed a transitional group.","zh":"Sereno 提出特內里安人形成一個過渡群體。"},{"en":"To form a transitional group means to become or represent a group between two different stages or lifestyles.","zh":"form a transitional group 指成為或代表處於兩個不同階段或生活方式之間的群體。"},{"en":"A community that still farms but begins factory work may form a transitional group.","zh":"仍然耕種但開始進入工廠工作的社區，可能形成一個過渡群體。"},{"en":"If people partly adopt herding while still hunting and fishing, they may show cultural transition.","zh":"如果人們部分採用畜牧，同時仍狩獵和捕魚，他們可能顯示文化過渡。"},{"en":"This phrase describes a group moving from one way of life toward another.","zh":"這個片語描述一個群體正從一種生活方式走向另一種。"}],"source":"58 - Ancient People in Sahara.pdf","sourcePage":7}],"ielts/reading/passage-2/Practice 59":[{"front":"the intense rate of change","meaning":"急劇的變化速度","examples":[{"en":"The intense rate of change in the world gives rise to numerous new electronic products.","zh":"世界急劇的變化速度引致大量新的電子產品出現。"},{"en":"The intense rate of change means things are changing very quickly and strongly.","zh":"the intense rate of change 指事物非常快速而強烈地改變。"},{"en":"Students may feel pressure when the intense rate of change in technology makes old skills less useful.","zh":"當科技急劇變化令舊技能較不實用時，學生可能感到壓力。"},{"en":"The intense rate of change can make companies release new products before people have fully used the old ones.","zh":"急劇的變化速度可以令公司在人們還未充分使用舊產品前，就推出新產品。"},{"en":"When change is intense, people need time, support, and clear information to adapt.","zh":"當變化很急劇時，人們需要時間、支援和清楚資訊去適應。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":1},{"front":"give rise to","meaning":"引致；導致","examples":[{"en":"Rapid technological change gives rise to large amounts of electronic waste.","zh":"快速的科技變化導致大量電子廢物。"},{"en":"To give rise to something means to cause it or make it happen.","zh":"give rise to something 意思是造成或引起某事。"},{"en":"Poor communication can give rise to misunderstandings in a group project.","zh":"溝通不良可以在小組項目中引致誤會。"},{"en":"High housing costs may give rise to stress among young families.","zh":"高昂住屋成本可能導致年輕家庭感到壓力。"},{"en":"This phrase is often used when one situation creates another problem or result.","zh":"這個短語常用於一個情況造成另一個問題或結果時。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":1},{"front":"numerous new products","meaning":"大量新產品","examples":[{"en":"The market produces numerous new products every year.","zh":"市場每年生產大量新產品。"},{"en":"Numerous new products are many recently made or recently released items.","zh":"numerous new products 指許多最近製造或推出的產品。"},{"en":"A supermarket may introduce numerous new products before a major festival.","zh":"超級市場可能在大型節日前推出大量新產品。"},{"en":"Numerous new products can give consumers more choice but also make shopping confusing.","zh":"大量新產品可以給消費者更多選擇，但也可能令購物變得混亂。"},{"en":"Not all numerous new products are necessary; some only replace items that still work.","zh":"並非所有大量新產品都有必要；有些只是取代仍能使用的物品。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":1},{"front":"electronic products","meaning":"電子產品","examples":[{"en":"Many new products are electronic products.","zh":"許多新產品都是電子產品。"},{"en":"Electronic products are devices that use electricity, circuits, or digital parts to work.","zh":"electronic products 是使用電力、電路或數碼零件運作的裝置。"},{"en":"Phones, laptops, tablets, cameras, and headphones are common electronic products.","zh":"手機、手提電腦、平板、相機和耳機都是常見電子產品。"},{"en":"Electronic products can improve daily life, but they can also create waste when replaced too often.","zh":"電子產品可以改善日常生活，但如果太常被替換，也會造成廢物。"},{"en":"Users should think about repair and recycling before throwing away electronic products.","zh":"使用者在丟棄電子產品前，應考慮維修和回收。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":1},{"front":"brand new","meaning":"全新的","examples":[{"en":"A device that is brand new one month may become outdated soon afterwards.","zh":"一部某個月還是全新的裝置，之後很快可能變得過時。"},{"en":"Brand new means completely new and not used before.","zh":"brand new 意思是完全新的，從未被使用過。"},{"en":"A student may feel excited when they receive a brand-new laptop for school.","zh":"學生收到一部全新的手提電腦上學時，可能感到興奮。"},{"en":"A brand-new product can quickly lose value if a newer model appears.","zh":"如果更新型號出現，全新產品可能很快失去價值。"},{"en":"Brand new does not always mean better; sometimes an older item still works well.","zh":"全新不一定代表更好；有時舊物品仍然運作良好。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":1},{"front":"state-of-the-art","meaning":"最先進的","examples":[{"en":"What is state-of-the-art one month may quickly become an old model.","zh":"某個月還是最先進的東西，可能很快變成舊型號。"},{"en":"State-of-the-art means using the newest and most advanced technology or design.","zh":"state-of-the-art 指使用最新和最先進科技或設計的。"},{"en":"A hospital may buy state-of-the-art machines to diagnose illness more accurately.","zh":"醫院可能購買最先進的機器，以更準確診斷疾病。"},{"en":"State-of-the-art equipment can be expensive to repair because it uses advanced parts.","zh":"最先進的設備可能維修昂貴，因為它使用高階零件。"},{"en":"A state-of-the-art product can become ordinary when competitors develop better versions.","zh":"當競爭者開發出更好版本時，最先進的產品也可能變得普通。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":1},{"front":"be relegated to","meaning":"被降級為；被貶為","examples":[{"en":"A new product can quickly be relegated to old-model status.","zh":"一件新產品可以很快被降級為舊型號。"},{"en":"To be relegated to a lower position means to be pushed down to a less important or less valued level.","zh":"be relegated to 較低位置，意思是被推到較不重要或較不被重視的層級。"},{"en":"A once-popular phone may be relegated to a backup device when the owner buys a newer one.","zh":"當主人買了更新手機，一部曾經受歡迎的手機可能被降級為備用裝置。"},{"en":"If a skill is no longer needed, it may be relegated to a minor role in the workplace.","zh":"如果一項技能不再被需要，它可能在工作場所中被降級為次要角色。"},{"en":"The phrase often suggests a loss of status or importance.","zh":"這個短語通常暗示地位或重要性下降。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":1},{"front":"old-model status","meaning":"舊型號的地位","examples":[{"en":"Many electronic devices are quickly pushed into old-model status.","zh":"許多電子裝置很快被推入舊型號的地位。"},{"en":"Old-model status means a product is no longer considered new, advanced, or current.","zh":"old-model status 指產品不再被視為新、先進或當前型號。"},{"en":"A phone may enter old-model status when the company releases a newer version.","zh":"當公司推出更新版本時，一部手機可能進入舊型號的地位。"},{"en":"Old-model status can reduce resale value even if the device still works perfectly.","zh":"舊型號的地位可以降低二手價值，即使裝置仍完全可用。"},{"en":"Being in old-model status does not always mean the product is useless.","zh":"變成舊型號並不一定代表產品沒有用。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":1},{"front":"within the world of computing","meaning":"在電腦科技領域內","examples":[{"en":"Within the world of computing, products become outdated very quickly.","zh":"在電腦科技領域內，產品很快變得過時。"},{"en":"Within the world of computing means in the area of computers, software, networks, and digital technology.","zh":"within the world of computing 指在電腦、軟件、網絡和數碼科技的範疇內。"},{"en":"Within the world of computing, students often need to learn new tools every year.","zh":"在電腦科技領域內，學生通常每年都要學習新工具。"},{"en":"Fast development within the world of computing can make old hardware and software less useful.","zh":"電腦科技領域內的快速發展可以令舊硬件和軟件較不實用。"},{"en":"This phrase limits the discussion to computer-related technology.","zh":"這個短語把討論限制在與電腦相關的科技上。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":1},{"front":"frenetic pace of change","meaning":"瘋狂急速的變化步伐","examples":[{"en":"The frenetic pace of change has created millions of outdated products.","zh":"瘋狂急速的變化步伐已造成數百萬件過時產品。"},{"en":"A frenetic pace of change is an extremely fast, busy, and almost uncontrolled speed of change.","zh":"frenetic pace of change 指極度快速、忙亂而幾乎失控的變化速度。"},{"en":"Workers may feel tired when the frenetic pace of change forces them to learn new systems constantly.","zh":"當瘋狂急速的變化迫使員工不斷學新系統時，他們可能感到疲累。"},{"en":"A frenetic pace of change can create waste because products are replaced before they are worn out.","zh":"瘋狂急速的變化步伐可以造成廢物，因為產品在耗損前已被替換。"},{"en":"This phrase suggests change is not just fast, but stressful and difficult to manage.","zh":"這個短語暗示變化不只是快，而且令人有壓力和難以管理。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":1},{"front":"lead to","meaning":"導致","examples":[{"en":"The rapid pace of change has led to millions of obsolete computers.","zh":"快速的變化步伐已導致數百萬部過時電腦。"},{"en":"To lead to something means to cause it or bring it about.","zh":"lead to something 意思是造成或帶來某事。"},{"en":"Lack of sleep can lead to poor concentration in class.","zh":"睡眠不足可以導致課堂上注意力差。"},{"en":"Poor planning may lead to delays, extra costs, and customer complaints.","zh":"規劃不善可能導致延誤、額外成本和顧客投訴。"},{"en":"This phrase is useful when explaining cause and effect.","zh":"這個短語適合用來解釋因果關係。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":1},{"front":"outdated products","meaning":"過時產品","examples":[{"en":"Outdated products often end up as electronic waste.","zh":"過時產品常最終變成電子廢物。"},{"en":"Outdated products are products that are no longer modern, useful, or supported by current technology.","zh":"outdated products 指不再現代、實用或受當前科技支援的產品。"},{"en":"A school may replace outdated products such as old projectors and slow computers.","zh":"學校可能替換舊投影機和慢速電腦等過時產品。"},{"en":"Outdated products can become waste when repairs are difficult or replacement seems cheaper.","zh":"當維修困難或替換看似更便宜時，過時產品可能變成廢物。"},{"en":"An outdated product may still be useful if it meets the user’s basic needs.","zh":"如果過時產品仍能滿足使用者的基本需要，它仍可能有用。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":2},{"front":"worthless products","meaning":"沒有價值的產品","examples":[{"en":"Some old electronic goods are treated as worthless products.","zh":"有些舊電子產品被當作沒有價值的產品。"},{"en":"Worthless products are items that people believe have no value or practical use.","zh":"worthless products 指人們認為沒有價值或實際用途的物品。"},{"en":"A broken printer may be treated as a worthless product if repair costs more than replacement.","zh":"如果維修費比替換費更高，一部壞打印機可能被當成沒有價值的產品。"},{"en":"Calling something worthless can lead people to throw it away instead of repairing or recycling it.","zh":"把某物稱為沒有價值，可能令人直接丟棄它，而不是維修或回收。"},{"en":"A product may seem worthless to one person but useful to someone who needs spare parts.","zh":"一件產品對某人看似沒有價值，但對需要零件的人可能有用。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":2},{"front":"US-based research company","meaning":"總部設於美國的研究公司","examples":[{"en":"Keystone is described as a US-based research company.","zh":"Keystone 被描述為一間總部設於美國的研究公司。"},{"en":"A US-based research company is a company located in or operating mainly from the United States that studies information professionally.","zh":"US-based research company 指位於美國或主要從美國運作，並專業研究資訊的公司。"},{"en":"A US-based research company may collect data on technology, health, business, or the environment.","zh":"總部設於美國的研究公司可能收集科技、健康、商業或環境數據。"},{"en":"Reports from a research company can influence public debate if people trust its methods.","zh":"如果人們信任其方法，研究公司的報告可以影響公共討論。"},{"en":"The phrase tells readers where the company is based and what kind of work it does.","zh":"這個短語告訴讀者公司設於哪裡，以及它從事甚麼工作。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":2},{"front":"become obsolete","meaning":"變得過時；被淘汰","examples":[{"en":"One computer became obsolete for every new one introduced on the market.","zh":"市場每推出一部新電腦，就有一部電腦變得過時。"},{"en":"To become obsolete means to become outdated and no longer useful, supported, or needed.","zh":"become obsolete 意思是變得過時，不再實用、受支援或被需要。"},{"en":"A charging cable may become obsolete when phone companies change the charging port.","zh":"當手機公司改變充電接口時，一條充電線可能變得過時。"},{"en":"Products become obsolete faster when companies stop providing updates or spare parts.","zh":"當公司停止提供更新或零件時，產品會更快被淘汰。"},{"en":"Something can become obsolete even if it still works physically.","zh":"某物即使仍能實際運作，也可以變得過時。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":2},{"front":"be introduced on the market","meaning":"被推出市場","examples":[{"en":"A new computer is introduced on the market almost every day.","zh":"幾乎每天都有一部新電腦被推出市場。"},{"en":"To be introduced on the market means to be made available for people to buy.","zh":"be introduced on the market 意思是被推出讓人購買。"},{"en":"A new health app may be introduced on the market after testing and advertising.","zh":"一個新的健康應用程式可能在測試和宣傳後被推出市場。"},{"en":"When many similar products are introduced on the market, older versions may lose attention.","zh":"當許多相似產品被推出市場時，較舊版本可能失去注意力。"},{"en":"This phrase is common when talking about new commercial products.","zh":"這個短語常用於談論新的商業產品。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":2},{"front":"experts estimated that","meaning":"專家估計","examples":[{"en":"Experts estimated that there would be over 500 million obsolete computers in the USA by 2010.","zh":"專家估計，到2010年美國會有超過5億部過時電腦。"},{"en":"Experts estimated that means specialists made an informed guess based on data or knowledge.","zh":"experts estimated that 意思是專家根據數據或知識作出有根據的估算。"},{"en":"Experts estimated that the repair would take two weeks after checking the damage.","zh":"專家檢查損壞後估計維修需時兩星期。"},{"en":"If experts estimate a serious rise in waste, governments may need to prepare early.","zh":"如果專家估計廢物會嚴重增加，政府可能需要及早準備。"},{"en":"An estimate is not exact, but it should be based on reasonable evidence.","zh":"估計並非精確數字，但應基於合理證據。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":2},{"front":"obsolete computers","meaning":"過時電腦；被淘汰的電腦","examples":[{"en":"Obsolete computers create a major disposal problem.","zh":"過時電腦造成重大的棄置問題。"},{"en":"Obsolete computers are computers that are too old to be useful, efficient, or supported.","zh":"obsolete computers 指太舊而不再實用、有效率或受支援的電腦。"},{"en":"A school may store obsolete computers because no one knows how to dispose of them safely.","zh":"學校可能存放過時電腦，因為沒有人知道如何安全棄置它們。"},{"en":"Obsolete computers can leak harmful materials if they are dumped carelessly.","zh":"如果被隨意傾倒，過時電腦可能滲出有害物質。"},{"en":"Some obsolete computers can still be reused for parts before final recycling.","zh":"有些過時電腦在最終回收前，仍可被拆件再用。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":2},{"front":"be destined for","meaning":"注定會被送往；最終會去到","examples":[{"en":"Most obsolete computers are destined for landfills, incinerators or hazardous-waste exports.","zh":"大多數過時電腦最終會被送往堆填區、焚化爐或作有害廢物出口。"},{"en":"To be destined for a place means to be likely or expected to end up there.","zh":"be destined for 某地，意思是很可能或預期最終會去到那裡。"},{"en":"Unsold food may be destined for the bin unless a shop donates it quickly.","zh":"未售出的食物如果商店不及時捐出，可能最終會被丟進垃圾桶。"},{"en":"If old phones are not collected for recycling, they may be destined for drawers or landfills.","zh":"如果舊手機沒有被收集回收，它們可能最終留在抽屜或送往堆填區。"},{"en":"This phrase often suggests an expected final outcome.","zh":"這個短語通常暗示預期中的最終結果。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":2},{"front":"landfills","meaning":"堆填區","examples":[{"en":"Many obsolete computers are sent to landfills.","zh":"許多過時電腦被送往堆填區。"},{"en":"Landfills are places where waste is buried in the ground.","zh":"landfills 是把廢物埋在地下的地方。"},{"en":"A city may use landfills when recycling and reuse cannot handle all waste.","zh":"當回收和再用無法處理所有廢物時，城市可能使用堆填區。"},{"en":"Landfills can create environmental risks if chemicals leak into soil or water.","zh":"如果化學物質滲入泥土或水中，堆填區可能造成環境風險。"},{"en":"Reducing waste is important because landfills take up land and can last for many years.","zh":"減少廢物很重要，因為堆填區佔用土地，而且可存在很多年。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":2},{"front":"incinerators","meaning":"焚化爐","examples":[{"en":"Some old computers are sent to incinerators instead of being recycled.","zh":"有些舊電腦被送往焚化爐，而不是被回收。"},{"en":"Incinerators are facilities that burn waste at high temperatures.","zh":"incinerators 是在高溫下焚燒廢物的設施。"},{"en":"A city may use incinerators to reduce the volume of rubbish.","zh":"城市可能使用焚化爐來減少垃圾體積。"},{"en":"Incinerators can release harmful substances if dangerous waste is burned improperly.","zh":"如果危險廢物被不當焚燒，焚化爐可能釋放有害物質。"},{"en":"Burning waste may reduce its size, but it does not always remove environmental risk.","zh":"焚燒廢物可能減少其體積，但不一定消除環境風險。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":2},{"front":"hazardous-waste exports","meaning":"有害廢物出口","examples":[{"en":"Hazardous-waste exports are one way some countries dispose of e-waste.","zh":"有害廢物出口是一些國家處理電子廢物的一種方式。"},{"en":"Hazardous-waste exports are dangerous wastes sent from one country to another.","zh":"hazardous-waste exports 指從一個國家送到另一個國家的危險廢物。"},{"en":"A company may choose hazardous-waste exports if overseas disposal is cheaper than local recycling.","zh":"如果海外棄置比本地回收便宜，公司可能選擇有害廢物出口。"},{"en":"Hazardous-waste exports can shift pollution and health risks to poorer communities.","zh":"有害廢物出口可以把污染和健康風險轉移到較貧困社區。"},{"en":"Such exports need strict control because the waste can harm people and the environment.","zh":"這類出口需要嚴格管制，因為廢物可以傷害人和環境。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":2},{"front":"outdated keyboards","meaning":"過時鍵盤","examples":[{"en":"Outdated keyboards are part of the growing e-waste problem.","zh":"過時鍵盤是日益嚴重的電子廢物問題的一部分。"},{"en":"Outdated keyboards are old computer keyboards that people no longer use or need.","zh":"outdated keyboards 指人們不再使用或需要的舊電腦鍵盤。"},{"en":"An office may throw away outdated keyboards after changing to wireless equipment.","zh":"辦公室改用無線設備後，可能丟棄過時鍵盤。"},{"en":"Outdated keyboards add to e-waste when they are replaced instead of repaired or donated.","zh":"當過時鍵盤被替換而不是維修或捐出時，會增加電子廢物。"},{"en":"Even small items like keyboards matter when millions are discarded.","zh":"即使像鍵盤這樣的小物品，當數以百萬計被丟棄時也很重要。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":3},{"front":"monitors","meaning":"顯示器","examples":[{"en":"Old monitors can contain toxic materials.","zh":"舊顯示器可能含有有毒物料。"},{"en":"Monitors are screens used to display images, text, and video from computers or other devices.","zh":"monitors 是用來顯示電腦或其他裝置影像、文字和影片的螢幕。"},{"en":"A student may use a monitor with a laptop to make online lessons easier to view.","zh":"學生可能用顯示器連接手提電腦，令網課更容易觀看。"},{"en":"Old monitors can become waste when schools upgrade computer rooms.","zh":"當學校升級電腦室時，舊顯示器可能變成廢物。"},{"en":"Monitors should be recycled carefully because some older models contain harmful substances.","zh":"顯示器應小心回收，因為一些較舊型號含有有害物質。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":3},{"front":"hard drives","meaning":"硬碟","examples":[{"en":"Hard drives are among the computer parts that may become e-waste.","zh":"硬碟是可能變成電子廢物的電腦零件之一。"},{"en":"Hard drives are computer storage devices that keep files, photos, programmes, and data.","zh":"hard drives 是儲存文件、照片、程式和數據的電腦儲存裝置。"},{"en":"Before recycling a hard drive, a company should remove or destroy private data safely.","zh":"公司在回收硬碟前，應安全刪除或銷毀私人數據。"},{"en":"Hard drives become e-waste when computers are replaced or storage systems change.","zh":"當電腦被替換或儲存系統改變時，硬碟會變成電子廢物。"},{"en":"A hard drive may look small, but it can contain both valuable metals and sensitive information.","zh":"硬碟看似細小，但可以含有有價值金屬和敏感資訊。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":3},{"front":"combine to produce","meaning":"結合起來產生","examples":[{"en":"Old keyboards, monitors and hard drives combine to produce e-waste.","zh":"舊鍵盤、顯示器和硬碟結合起來產生電子廢物。"},{"en":"To combine to produce something means several things together create one result.","zh":"combine to produce something 意思是幾樣事物一起造成一個結果。"},{"en":"Long working hours, poor sleep, and stress can combine to produce burnout.","zh":"長工時、睡眠不足和壓力可以結合起來造成倦怠。"},{"en":"Cheap prices and heavy advertising may combine to produce unnecessary buying.","zh":"低價和大量廣告可能結合起來造成不必要購買。"},{"en":"This phrase shows that a result may come from several causes, not just one.","zh":"這個短語顯示一個結果可能來自多個原因，而不只是單一原因。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":3},{"front":"widely known as","meaning":"廣泛稱為","examples":[{"en":"Old electronic products are now widely known as e-waste.","zh":"舊電子產品現在廣泛稱為電子廢物。"},{"en":"Widely known as means commonly called or recognised by many people as something.","zh":"widely known as 意思是被許多人普遍稱為或認識為某事物。"},{"en":"A famous street may be widely known as a shopping area because many stores are there.","zh":"一條著名街道可能因有許多商店而被廣泛稱為購物區。"},{"en":"When a problem becomes widely known as serious, governments may face pressure to act.","zh":"當一個問題被廣泛認為嚴重時，政府可能面對行動壓力。"},{"en":"This phrase helps introduce a common name or label.","zh":"這個短語有助介紹常見名稱或標籤。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":3},{"front":"e-waste","meaning":"電子廢物","examples":[{"en":"E-waste is difficult to dispose of safely.","zh":"電子廢物難以安全處理。"},{"en":"E-waste means electronic waste, such as old phones, computers, cables, and screens.","zh":"e-waste 指電子廢物，例如舊手機、電腦、電線和螢幕。"},{"en":"A family may collect e-waste when old chargers and broken devices pile up at home.","zh":"當家中舊充電器和壞裝置堆積時，一個家庭可能累積電子廢物。"},{"en":"E-waste can harm the environment if toxic materials leak or burn.","zh":"如果有毒物料滲漏或燃燒，電子廢物可以傷害環境。"},{"en":"Proper recycling can reduce the danger and recover useful materials from e-waste.","zh":"妥善回收可以減低危險，並從電子廢物中回收有用物料。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":3},{"front":"dispose of something appropriately","meaning":"妥善處理……","examples":[{"en":"How to dispose of e-waste appropriately is proving to be a challenge.","zh":"如何妥善處理電子廢物正證明是一個挑戰。"},{"en":"To dispose of something appropriately means to get rid of it in a safe, legal, and suitable way.","zh":"dispose of something appropriately 意思是以安全、合法和合適的方式處理或棄置某物。"},{"en":"Hospitals must dispose of medical waste appropriately to protect patients and cleaners.","zh":"醫院必須妥善處理醫療廢物，以保護病人和清潔工。"},{"en":"If people do not dispose of batteries appropriately, chemicals may leak into the environment.","zh":"如果人們沒有妥善處理電池，化學物質可能滲入環境。"},{"en":"Appropriate disposal often requires sorting, collection, and specialist treatment.","zh":"妥善處理通常需要分類、收集和專門處理。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":3},{"front":"prove to be a challenge","meaning":"證明是個挑戰","examples":[{"en":"Disposing of electronic waste safely is proving to be a challenge.","zh":"安全處理電子廢物正證明是個挑戰。"},{"en":"To prove to be a challenge means to turn out to be difficult after people try to do it.","zh":"prove to be a challenge 意思是在嘗試後發現某事很困難。"},{"en":"Teaching online classes may prove to be a challenge when students have poor internet access.","zh":"當學生網絡連線差時，網上教學可能證明是個挑戰。"},{"en":"Recycling e-waste proves to be a challenge because products contain many different materials.","zh":"回收電子廢物證明是個挑戰，因為產品含有許多不同物料。"},{"en":"This phrase suggests the difficulty becomes clear through experience.","zh":"這個短語暗示困難是透過經驗變得清楚的。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":3},{"front":"a complicated assembly of","meaning":"由……組成的複雜組合","examples":[{"en":"A computer is a complicated assembly of hundreds of different materials.","zh":"電腦是由數百種不同物料組成的複雜組合。"},{"en":"A complicated assembly of things is a complex structure made from many connected parts.","zh":"a complicated assembly of things 指由許多相連部分構成的複雜結構。"},{"en":"A car is a complicated assembly of metal, glass, rubber, wires, and electronic systems.","zh":"汽車是由金屬、玻璃、橡膠、電線和電子系統組成的複雜組合。"},{"en":"Because a computer is a complicated assembly, recycling it requires careful separation of parts.","zh":"因為電腦是複雜組合，回收時需要小心分離部件。"},{"en":"The phrase helps explain why disposal or repair is not simple.","zh":"這個短語有助解釋為何棄置或維修並不簡單。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":3},{"front":"highly toxic","meaning":"高毒性的","examples":[{"en":"Many materials in computers are highly toxic.","zh":"電腦中的許多物料都是高毒性的。"},{"en":"Highly toxic means very poisonous or dangerous to human health or the environment.","zh":"highly toxic 指對人體健康或環境非常有毒或危險。"},{"en":"A cleaning chemical may be highly toxic if it can burn skin or damage lungs.","zh":"如果清潔化學品會灼傷皮膚或傷害肺部，它可能是高毒性的。"},{"en":"Highly toxic materials require special handling so workers are not harmed.","zh":"高毒性物料需要特別處理，避免傷害工人。"},{"en":"Something highly toxic should never be dumped or burned carelessly.","zh":"高毒性的東西絕不應被隨意傾倒或焚燒。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":3},{"front":"computer users","meaning":"電腦用戶","examples":[{"en":"Most computer users are unaware of the toxic materials inside their devices.","zh":"大多數電腦用戶不知道裝置內有有毒物料。"},{"en":"Computer users are people who use computers for work, study, communication, or entertainment.","zh":"computer users 是使用電腦工作、學習、溝通或娛樂的人。"},{"en":"Computer users may focus on speed and price but forget disposal problems.","zh":"電腦用戶可能集中於速度和價格，卻忘記棄置問題。"},{"en":"If computer users understand e-waste risks, they may choose repair or recycling more often.","zh":"如果電腦用戶了解電子廢物風險，他們可能更常選擇維修或回收。"},{"en":"Ordinary computer users can reduce waste by keeping devices longer and buying carefully.","zh":"普通電腦用戶可以透過延長裝置使用期和謹慎購買來減少廢物。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":3},{"front":"be unaware that","meaning":"不知道；沒有意識到","examples":[{"en":"Many users are unaware that computers contain dangerous substances.","zh":"許多用戶不知道電腦含有危險物質。"},{"en":"To be unaware that something is true means not to know or realise it.","zh":"be unaware that something is true 意思是不知道或沒有意識到某事是真實的。"},{"en":"A customer may be unaware that a cheap charger can damage their phone.","zh":"顧客可能不知道廉價充電器會損壞手機。"},{"en":"If people are unaware that e-waste is toxic, they may throw devices into ordinary bins.","zh":"如果人們不知道電子廢物有毒，他們可能把裝置丟進普通垃圾桶。"},{"en":"This phrase often introduces hidden information that people should know.","zh":"這個短語常用來引出人們應知道的隱藏資訊。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":4},{"front":"toxic metals","meaning":"有毒金屬","examples":[{"en":"Toxic metals in computers can harm human health.","zh":"電腦中的有毒金屬可以傷害人體健康。"},{"en":"Toxic metals are poisonous metals that can damage living bodies or the environment.","zh":"toxic metals 是會傷害生物身體或環境的有毒金屬。"},{"en":"Lead and mercury are toxic metals that must be handled carefully.","zh":"鉛和水銀是必須小心處理的有毒金屬。"},{"en":"Toxic metals can enter soil and water if electronic devices are broken or burned.","zh":"如果電子裝置破裂或被焚燒，有毒金屬可以進入泥土和水中。"},{"en":"Recycling centres need safety rules because toxic metals can harm workers.","zh":"回收中心需要安全規則，因為有毒金屬可以傷害工人。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":4},{"front":"acids","meaning":"酸性物質","examples":[{"en":"Some computer components contain acids and other harmful substances.","zh":"一些電腦部件含有酸性物質和其他有害物質。"},{"en":"Acids are chemicals that can react strongly and sometimes burn skin or damage materials.","zh":"acids 是可以強烈反應，有時會灼傷皮膚或損壞材料的化學物質。"},{"en":"A battery may contain acids, so it should not be opened by children.","zh":"電池可能含有酸性物質，所以兒童不應打開它。"},{"en":"If acids leak from waste, they can damage containers and pollute surrounding materials.","zh":"如果酸性物質從廢物中滲漏，它們可以損壞容器並污染周圍物料。"},{"en":"Acids must be stored and disposed of carefully because they can be dangerous.","zh":"酸性物質必須小心儲存和棄置，因為它們可能危險。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":4},{"front":"plastics","meaning":"塑膠","examples":[{"en":"Plastics in electronic waste can create pollution when burned.","zh":"電子廢物中的塑膠被焚燒時可以造成污染。"},{"en":"Plastics are artificial materials often used to make cases, covers, buttons, and packaging.","zh":"plastics 是常用來製作外殼、保護套、按鈕和包裝的人造材料。"},{"en":"Computer keyboards, phone cases, and cable covers often contain plastics.","zh":"電腦鍵盤、手機殼和電線外層通常含有塑膠。"},{"en":"When plastics are burned, they may release smoke and harmful chemicals.","zh":"當塑膠被焚燒時，可能釋放煙霧和有害化學物質。"},{"en":"Reducing unnecessary plastics can lower pollution and make recycling easier.","zh":"減少不必要塑膠可以降低污染，並令回收更容易。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":4},{"front":"harmful substances","meaning":"有害物質","examples":[{"en":"Computers may contain toxic metals, acids, plastics and other harmful substances.","zh":"電腦可能含有有毒金屬、酸性物質、塑膠和其他有害物質。"},{"en":"Harmful substances are materials that can damage health, safety, or the environment.","zh":"harmful substances 是可以損害健康、安全或環境的物料。"},{"en":"Cleaning products should be labelled clearly if they contain harmful substances.","zh":"如果清潔產品含有有害物質，應清楚標示。"},{"en":"Harmful substances in e-waste can spread when devices are broken, burned, or dumped.","zh":"當裝置被打碎、焚燒或傾倒時，電子廢物中的有害物質可以擴散。"},{"en":"People need clear disposal rules when products contain harmful substances.","zh":"當產品含有有害物質時，人們需要清楚的棄置規則。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":4},{"front":"be shown to be the cause of","meaning":"被證實是……的成因","examples":[{"en":"Some toxic substances have been shown to be the cause of blood diseases and cancers.","zh":"有些有毒物質已被證實是血液疾病和癌症的成因。"},{"en":"To be shown to be the cause of something means evidence has indicated that it causes that result.","zh":"be shown to be the cause of something 意思是證據顯示某事造成該結果。"},{"en":"Smoking has been shown to be the cause of many serious health problems.","zh":"吸煙已被證實是許多嚴重健康問題的成因。"},{"en":"If a chemical is shown to be the cause of illness, workers need stronger protection.","zh":"如果一種化學物質被證實是疾病成因，工人需要更強保護。"},{"en":"This phrase is stronger than saying people merely suspect a connection.","zh":"這個短語比只說人們懷疑有關聯更強。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":4},{"front":"blood diseases","meaning":"血液疾病","examples":[{"en":"Workers exposed to e-waste may face a higher risk of blood diseases.","zh":"接觸電子廢物的工人可能面對較高血液疾病風險。"},{"en":"Blood diseases are illnesses that affect the blood, blood cells, or the body’s ability to carry oxygen and fight infection.","zh":"blood diseases 是影響血液、血細胞或身體輸送氧氣和抵抗感染能力的疾病。"},{"en":"Doctors may order blood tests if they suspect blood diseases.","zh":"如果醫生懷疑有血液疾病，可能會要求驗血。"},{"en":"Exposure to toxic substances may increase the risk of certain blood diseases.","zh":"接觸有毒物質可能增加某些血液疾病的風險。"},{"en":"Preventing harmful exposure is important because blood diseases can be serious and long-lasting.","zh":"防止有害接觸很重要，因為血液疾病可以很嚴重且持久。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":4},{"front":"cancers","meaning":"癌症","examples":[{"en":"Toxic substances in computers have been linked to cancers.","zh":"電腦中的有毒物質已被指與癌症有關。"},{"en":"Cancers are diseases in which abnormal cells grow and spread in the body.","zh":"cancers 是身體中異常細胞生長和擴散的疾病。"},{"en":"Doctors treat cancers with methods such as surgery, medicine, and radiation.","zh":"醫生以手術、藥物和放射治療等方法治療癌症。"},{"en":"Long-term exposure to harmful chemicals may increase the risk of some cancers.","zh":"長期接觸有害化學物質可能增加某些癌症風險。"},{"en":"Reducing toxic exposure is one way to protect workers from serious disease.","zh":"減少有毒接觸是保護工人免受嚴重疾病的方法之一。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":4},{"front":"workers involved in","meaning":"參與……的工人","examples":[{"en":"Workers involved in recycling computer products may be exposed to dangerous substances.","zh":"參與電腦產品回收的工人可能接觸危險物質。"},{"en":"Workers involved in an activity are people who take part in doing that work.","zh":"workers involved in 某活動，指參與該工作的工人。"},{"en":"Workers involved in cleaning a chemical spill need masks, gloves, and training.","zh":"參與清理化學品洩漏的工人需要口罩、手套和訓練。"},{"en":"If workers involved in recycling lack protection, they may suffer health problems.","zh":"如果參與回收的工人缺乏保護，他們可能出現健康問題。"},{"en":"This phrase identifies the people directly connected to a job or process.","zh":"這個短語指出直接與某工作或過程有關的人。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":4},{"front":"recycling of computer products","meaning":"電腦產品回收","examples":[{"en":"The recycling of computer products can expose workers to toxic materials.","zh":"電腦產品回收可能令工人接觸有毒物料。"},{"en":"The recycling of computer products means collecting, taking apart, and processing old computer equipment for reuse or material recovery.","zh":"recycling of computer products 指收集、拆解和處理舊電腦設備，以再用或回收物料。"},{"en":"A school may arrange the recycling of computer products after replacing its computer room equipment.","zh":"學校在更換電腦室設備後，可能安排電腦產品回收。"},{"en":"Recycling computer products can reduce waste, but it must be done safely.","zh":"電腦產品回收可以減少廢物，但必須安全進行。"},{"en":"Poor recycling methods can turn a useful environmental practice into a health risk.","zh":"差劣回收方法可以把有益環保的做法變成健康風險。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":4},{"front":"an increase in","meaning":"……的增加","examples":[{"en":"There has been an increase in blood diseases among some recycling workers.","zh":"一些回收工人之間出現血液疾病增加的情況。"},{"en":"An increase in something means that the amount, number, or level of it has gone up.","zh":"an increase in something 指某事物的數量、數字或水平上升。"},{"en":"A school may notice an increase in late arrivals after bus services are reduced.","zh":"巴士服務減少後，學校可能注意到遲到人數增加。"},{"en":"An increase in e-waste can put more pressure on recycling systems.","zh":"電子廢物的增加可以對回收系統造成更大壓力。"},{"en":"This phrase is useful when describing a rising trend.","zh":"這個短語適合描述上升趨勢。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":4},{"front":"printed circuit boards","meaning":"印刷電路板","examples":[{"en":"Printed circuit boards contain several heavy metals.","zh":"印刷電路板含有幾種重金屬。"},{"en":"Printed circuit boards are flat boards inside electronic devices that connect and support electronic parts.","zh":"printed circuit boards 是電子裝置內連接和支撐電子零件的平面板。"},{"en":"A phone, computer, or television usually contains printed circuit boards.","zh":"手機、電腦或電視通常含有印刷電路板。"},{"en":"Printed circuit boards can be hard to recycle because they contain many materials joined together.","zh":"印刷電路板難以回收，因為它們含有許多結合在一起的物料。"},{"en":"They are small but important parts of the e-waste problem.","zh":"它們雖然細小，卻是電子廢物問題的重要部分。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":5},{"front":"heavy metals","meaning":"重金屬","examples":[{"en":"Heavy metals such as lead and copper are found in printed circuit boards.","zh":"鉛和銅等重金屬存在於印刷電路板中。"},{"en":"Heavy metals are dense metals, some of which can be toxic to people and the environment.","zh":"heavy metals 是密度較高的金屬，其中一些會對人和環境有毒。"},{"en":"Lead, mercury, cadmium, and chromium are examples of heavy metals of concern.","zh":"鉛、水銀、鎘和鉻都是值得關注的重金屬例子。"},{"en":"Heavy metals can pollute soil and water if waste is not handled properly.","zh":"如果廢物處理不當，重金屬可以污染泥土和水。"},{"en":"Because heavy metals can build up in living bodies, they require careful control.","zh":"因為重金屬可以在生物體內累積，所以需要小心管制。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":5},{"front":"antimony","meaning":"銻","examples":[{"en":"Antimony is one of the heavy metals found in printed circuit boards.","zh":"銻是在印刷電路板中發現的重金屬之一。"},{"en":"Antimony is a metallic element used in some industrial and electronic materials.","zh":"antimony 是一種金屬元素，用於某些工業和電子材料。"},{"en":"Workers may need protection when handling materials that contain antimony.","zh":"工人處理含銻物料時，可能需要保護。"},{"en":"If antimony enters waste streams without control, it can add to environmental risk.","zh":"如果銻不受控制地進入廢物流，可能增加環境風險。"},{"en":"Students do not need to use this word often, but they should recognise it in pollution texts.","zh":"學生不需要常用這個字，但應在污染文章中認得它。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":5},{"front":"chromium","meaning":"鉻","examples":[{"en":"Chromium can be found in some computer circuit boards.","zh":"鉻可在一些電腦電路板中找到。"},{"en":"Chromium is a metal used in some industrial processes and materials.","zh":"chromium 是一種用於某些工業過程和材料的金屬。"},{"en":"Some forms of chromium can be harmful, so disposal rules are important.","zh":"某些形式的鉻可能有害，所以棄置規則很重要。"},{"en":"If chromium-containing waste is burned or dumped, it may contribute to pollution.","zh":"如果含鉻廢物被焚燒或傾倒，可能造成污染。"},{"en":"In environmental passages, chromium is often mentioned as a metal requiring control.","zh":"在環境文章中，鉻常被提及為需要管制的金屬。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":5},{"front":"zinc","meaning":"鋅","examples":[{"en":"Zinc is listed as one of the metals found in printed circuit boards.","zh":"鋅被列為印刷電路板中發現的金屬之一。"},{"en":"Zinc is a metal used in many products, including batteries, coatings, and electronic parts.","zh":"zinc 是用於許多產品的金屬，包括電池、塗層和電子零件。"},{"en":"Small amounts of zinc are useful in the body, but waste containing metals still needs control.","zh":"少量鋅對身體有用，但含金屬廢物仍需管制。"},{"en":"If zinc and other metals leak from waste, they may affect soil and water quality.","zh":"如果鋅和其他金屬從廢物中滲漏，可能影響泥土和水質。"},{"en":"In this passage, zinc is important because it is part of the mixture inside electronic waste.","zh":"在這篇文章中，鋅重要是因為它是電子廢物內混合物的一部分。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":5},{"front":"lead","meaning":"鉛","examples":[{"en":"Lead is a toxic metal found in some electronic products.","zh":"鉛是在某些電子產品中發現的有毒金屬。"},{"en":"Lead is a heavy metal that can harm the brain, blood, and nervous system.","zh":"lead 是一種會傷害大腦、血液和神經系統的重金屬。"},{"en":"Old paint, batteries, and some electronic parts may contain lead.","zh":"舊油漆、電池和一些電子零件可能含有鉛。"},{"en":"If lead enters soil or water, it can create long-term health risks.","zh":"如果鉛進入泥土或水中，可能造成長期健康風險。"},{"en":"Products containing lead should be collected and treated carefully.","zh":"含鉛產品應被小心收集和處理。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":5},{"front":"tin","meaning":"錫","examples":[{"en":"Tin is one of the metals used in printed circuit boards.","zh":"錫是印刷電路板中使用的金屬之一。"},{"en":"Tin is a metal often used in solder and protective coatings.","zh":"tin 是常用於焊料和保護塗層的金屬。"},{"en":"Electronic parts may use tin to help connect components on a board.","zh":"電子零件可能使用錫來幫助連接電路板上的部件。"},{"en":"When e-waste is recycled, tin may be recovered along with other metals.","zh":"當電子廢物被回收時，錫可能與其他金屬一起被回收。"},{"en":"Tin is not the only concern; it appears with other materials that complicate recycling.","zh":"錫不是唯一問題；它與其他物料一起出現，使回收變得複雜。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":5},{"front":"copper","meaning":"銅","examples":[{"en":"Copper can act as a catalyst when electronic waste is burned.","zh":"當電子廢物被焚燒時，銅可以作為催化劑。"},{"en":"Copper is a reddish-brown metal that conducts electricity well.","zh":"copper 是一種紅褐色金屬，導電能力良好。"},{"en":"Electrical wires often contain copper because it carries current efficiently.","zh":"電線常含有銅，因為它能有效傳導電流。"},{"en":"In burning e-waste, copper may help chemical reactions release harmful substances.","zh":"在焚燒電子廢物時，銅可能幫助化學反應釋放有害物質。"},{"en":"Copper is valuable for recycling, but it must be recovered safely.","zh":"銅有回收價值，但必須安全回收。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":5},{"front":"environmental impacts","meaning":"環境影響","examples":[{"en":"The environmental impacts of computer production and disposal are extensive.","zh":"電腦生產和棄置的環境影響非常廣泛。"},{"en":"Environmental impacts are the effects something has on nature, air, water, soil, and living things.","zh":"environmental impacts 是某事對自然、空氣、水、泥土和生物造成的影響。"},{"en":"A factory’s environmental impacts may include smoke, wastewater, noise, and waste.","zh":"工廠的環境影響可能包括煙霧、廢水、噪音和廢物。"},{"en":"Electronic products have environmental impacts from mining, manufacturing, use, and disposal.","zh":"電子產品從採礦、製造、使用到棄置都有環境影響。"},{"en":"Understanding environmental impacts helps people see the full cost of a product.","zh":"理解環境影響有助人們看見產品的完整成本。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":5},{"front":"raw-material extraction","meaning":"原材料開採","examples":[{"en":"Raw-material extraction is part of the environmental cost of producing computers.","zh":"原材料開採是生產電腦的環境成本之一。"},{"en":"Raw-material extraction means taking natural materials such as metals, minerals, or oil from the earth.","zh":"raw-material extraction 指從地球取得金屬、礦物或石油等天然材料。"},{"en":"Mining copper for electronics is one form of raw-material extraction.","zh":"為電子產品開採銅是一種原材料開採。"},{"en":"Raw-material extraction can damage land, use energy, and create pollution.","zh":"原材料開採可以破壞土地、消耗能源並造成污染。"},{"en":"A product’s environmental cost begins before it reaches the shop.","zh":"產品的環境成本在它到達商店前已經開始。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":5},{"front":"industrial refining","meaning":"工業提煉","examples":[{"en":"Industrial refining can add to the environmental impact of electronic products.","zh":"工業提煉會增加電子產品的環境影響。"},{"en":"Industrial refining means processing raw materials in factories to make them purer or more useful.","zh":"industrial refining 指在工廠中處理原材料，使其更純或更有用。"},{"en":"Metals may go through industrial refining before they are used in circuit boards.","zh":"金屬在用於電路板前，可能經過工業提煉。"},{"en":"Industrial refining can use large amounts of energy and produce pollution.","zh":"工業提煉可以消耗大量能源並產生污染。"},{"en":"This stage shows that environmental damage can occur long before disposal.","zh":"這個階段顯示環境傷害可能早在棄置前已經發生。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":5},{"front":"use and disposal","meaning":"使用及棄置","examples":[{"en":"The environmental impact includes production, use and disposal.","zh":"環境影響包括生產、使用及棄置。"},{"en":"Use and disposal refer to how a product is used during its life and how it is thrown away afterwards.","zh":"use and disposal 指產品在生命周期中如何被使用，以及之後如何被丟棄。"},{"en":"A phone’s use and disposal both matter: charging uses energy, and dumping can create waste.","zh":"手機的使用及棄置都重要：充電會用能源，丟棄會造成廢物。"},{"en":"Poor disposal after use can turn a helpful product into an environmental problem.","zh":"使用後的不當棄置可以把有用產品變成環境問題。"},{"en":"Considering use and disposal helps people judge the full life of a product.","zh":"考慮使用及棄置，有助人們判斷產品的完整生命周期。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":6},{"front":"so extensive as","meaning":"如此廣泛以至","examples":[{"en":"Few products have environmental impacts so extensive as printed circuit boards.","zh":"很少產品的環境影響像印刷電路板那樣廣泛。"},{"en":"So extensive as means as wide, large, or far-reaching as something else.","zh":"so extensive as 意思是像某事物一樣廣泛、巨大或影響深遠。"},{"en":"Few school problems are so extensive as poor communication between teachers, parents, and students.","zh":"很少學校問題像老師、家長和學生之間溝通不良那樣影響廣泛。"},{"en":"When impacts are so extensive, solutions must cover many stages, not only one point.","zh":"當影響如此廣泛時，解決方法必須涵蓋許多階段，而不只是某一點。"},{"en":"This phrase is formal and often used for comparison.","zh":"這個短語較正式，常用於比較。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":6},{"front":"disposal of computers","meaning":"電腦棄置","examples":[{"en":"The disposal of computers can expose workers to toxic substances.","zh":"電腦棄置可能令工人接觸有毒物質。"},{"en":"Disposal of computers means the process of getting rid of old or unwanted computers.","zh":"disposal of computers 指處理不再需要或舊電腦的過程。"},{"en":"A company should plan the disposal of computers when it upgrades office equipment.","zh":"公司升級辦公室設備時，應規劃電腦棄置。"},{"en":"Unsafe disposal of computers can release metals, plastics, and other harmful substances.","zh":"不安全的電腦棄置可能釋放金屬、塑膠和其他有害物質。"},{"en":"Proper disposal includes data protection, material recovery, and safe treatment.","zh":"妥善棄置包括保護數據、回收物料和安全處理。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":6},{"front":"via incineration","meaning":"透過焚化","examples":[{"en":"Some computers are disposed of via incineration.","zh":"有些電腦透過焚化被棄置。"},{"en":"Via incineration means by burning waste in an incinerator or similar process.","zh":"via incineration 意思是透過焚化爐或類似過程焚燒廢物。"},{"en":"Some cities reduce waste volume via incineration when landfill space is limited.","zh":"當堆填空間有限時，有些城市透過焚化減少廢物體積。"},{"en":"Disposing of e-waste via incineration can release toxic substances if controls are weak.","zh":"如果管制薄弱，透過焚化處理電子廢物可能釋放有毒物質。"},{"en":"This phrase explains the method used to deal with waste.","zh":"這個短語解釋處理廢物所使用的方法。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":6},{"front":"be exposed to","meaning":"接觸到；暴露於","examples":[{"en":"Workers may be exposed to high levels of toxicity during incineration.","zh":"工人在焚化期間可能接觸到高水平毒性。"},{"en":"To be exposed to something means to come into contact with it, especially something harmful or influential.","zh":"be exposed to something 意思是接觸到某事，尤其是有害或有影響力的事物。"},{"en":"Children may be exposed to loud noise if they live near a busy road.","zh":"如果孩子住在繁忙馬路附近，可能暴露於巨大噪音之中。"},{"en":"Workers exposed to toxic smoke may develop health problems over time.","zh":"接觸有毒煙霧的工人可能隨時間出現健康問題。"},{"en":"Exposure can be physical, like chemicals, or social, like new ideas.","zh":"exposure 可以是身體上的，例如化學品，也可以是社會上的，例如新思想。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":6},{"front":"significantly high levels of","meaning":"顯著高水平的……","examples":[{"en":"Incineration can expose workers to significantly high levels of toxicity.","zh":"焚化可以令工人接觸顯著高水平的毒性。"},{"en":"Significantly high levels of something means amounts that are clearly and importantly high.","zh":"significantly high levels of something 指某物數量明顯而重要地高。"},{"en":"A classroom with poor ventilation may have significantly high levels of carbon dioxide.","zh":"通風差的課室可能有顯著高水平的二氧化碳。"},{"en":"Significantly high levels of toxic smoke can create serious health risks.","zh":"顯著高水平的有毒煙霧可以造成嚴重健康風險。"},{"en":"The phrase suggests the level is not just slightly high, but high enough to matter.","zh":"這個短語暗示水平不只是稍高，而是高到值得關注。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":6},{"front":"toxicity","meaning":"毒性","examples":[{"en":"Computer waste can release high levels of toxicity when burned.","zh":"電腦廢物被焚燒時可以釋放高水平毒性。"},{"en":"Toxicity is the degree to which something is poisonous or harmful.","zh":"toxicity 是某物有毒或有害的程度。"},{"en":"A chemical label may warn users about the toxicity of a cleaning product.","zh":"化學品標籤可能警告使用者清潔產品的毒性。"},{"en":"Burning e-waste can increase toxicity in the air if harmful chemicals are released.","zh":"如果有害化學物質被釋放，焚燒電子廢物可以增加空氣中的毒性。"},{"en":"Reducing toxicity protects workers, nearby residents, and the environment.","zh":"減少毒性可以保護工人、附近居民和環境。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":6},{"front":"a catalyst in","meaning":"……的催化劑","examples":[{"en":"Copper is a catalyst in the release of harmful chemicals.","zh":"銅是釋放有害化學物質的催化劑。"},{"en":"A catalyst in a process is something that speeds up or helps a reaction or change happen.","zh":"a catalyst in 某過程，指加快或幫助反應或變化發生的事物。"},{"en":"A complaint can be a catalyst in improving customer service.","zh":"投訴可以成為改善客戶服務的催化劑。"},{"en":"In burning e-waste, copper may act as a catalyst in chemical reactions.","zh":"在焚燒電子廢物時，銅可能在化學反應中作為催化劑。"},{"en":"A catalyst does not always create a problem alone, but it can make the process happen faster.","zh":"催化劑不一定單獨造成問題，但可以令過程更快發生。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":6},{"front":"the release of","meaning":"……的釋放","examples":[{"en":"High temperatures can cause the release of harmful chemicals.","zh":"高溫可以導致有害化學物質的釋放。"},{"en":"The release of something means it escapes, is let out, or becomes available.","zh":"the release of something 指某物逃出、被放出或變得可取得。"},{"en":"A broken pipe can cause the release of dirty water into a street.","zh":"水管破裂可以導致污水釋放到街上。"},{"en":"The release of toxic smoke can harm workers and nearby residents.","zh":"有毒煙霧的釋放可以傷害工人和附近居民。"},{"en":"This phrase is often used for gases, chemicals, information, or products.","zh":"這個短語常用於氣體、化學物質、資訊或產品。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":6},{"front":"harmful chemicals","meaning":"有害化學物質","examples":[{"en":"Burning e-waste may release harmful chemicals.","zh":"焚燒電子廢物可能釋放有害化學物質。"},{"en":"Harmful chemicals are chemical substances that can damage health or the environment.","zh":"harmful chemicals 是可以傷害健康或環境的化學物質。"},{"en":"Some cleaning sprays contain harmful chemicals if used without ventilation.","zh":"如果在沒有通風的情況下使用，有些清潔噴霧含有有害化學物質。"},{"en":"Harmful chemicals from burning waste can spread through air and settle on soil.","zh":"焚燒廢物產生的有害化學物質可以經空氣擴散並沉降到泥土上。"},{"en":"People should avoid burning materials that may release harmful chemicals.","zh":"人們應避免焚燒可能釋放有害化學物質的材料。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":6},{"front":"high temperatures","meaning":"高溫","examples":[{"en":"Copper can trigger chemical reactions at the high temperatures of incineration.","zh":"銅可以在焚化高溫下觸發化學反應。"},{"en":"High temperatures are very hot conditions that can cause materials to melt, burn, or react.","zh":"high temperatures 指非常炎熱的狀態，可以令材料熔化、燃燒或反應。"},{"en":"Food spoils faster when it is stored at high temperatures.","zh":"食物在高溫下存放會更快變壞。"},{"en":"High temperatures during burning can change safe materials into dangerous fumes.","zh":"焚燒期間的高溫可以把安全材料轉變成危險煙霧。"},{"en":"In waste treatment, high temperatures must be carefully controlled.","zh":"在廢物處理中，高溫必須被小心控制。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":6},{"front":"heavy metal contamination","meaning":"重金屬污染","examples":[{"en":"Incineration is a major source of heavy metal contamination in the atmosphere.","zh":"焚化是大氣中重金屬污染的主要來源。"},{"en":"Heavy metal contamination means pollution caused by toxic or dangerous metals entering air, soil, or water.","zh":"heavy metal contamination 指有毒或危險金屬進入空氣、泥土或水而造成的污染。"},{"en":"A river may suffer heavy metal contamination if factory waste is dumped into it.","zh":"如果工廠廢物被傾倒入河流，河流可能遭受重金屬污染。"},{"en":"Heavy metal contamination can harm wildlife and enter the food chain.","zh":"重金屬污染可以傷害野生動物，並進入食物鏈。"},{"en":"Preventing contamination is easier than cleaning it up after it spreads.","zh":"防止污染比污染擴散後清理更容易。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":7},{"front":"the atmosphere","meaning":"大氣層","examples":[{"en":"Heavy metal contamination can spread through the atmosphere.","zh":"重金屬污染可以透過大氣層擴散。"},{"en":"The atmosphere is the layer of air surrounding the Earth.","zh":"the atmosphere 是圍繞地球的空氣層。"},{"en":"Smoke from fires can rise into the atmosphere and travel long distances.","zh":"火災產生的煙可以升入大氣層並飄到很遠。"},{"en":"Pollutants in the atmosphere can affect breathing and weather conditions.","zh":"大氣層中的污染物可以影響呼吸和天氣狀況。"},{"en":"Protecting the atmosphere matters because everyone shares the same air system.","zh":"保護大氣層很重要，因為所有人共享同一空氣系統。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":7},{"front":"another form of","meaning":"另一種形式的……","examples":[{"en":"Smelting is another form of incineration.","zh":"冶煉是焚化的另一種形式。"},{"en":"Another form of something means a different type or version of the same general thing.","zh":"another form of something 指同一大類事物的另一種類型或版本。"},{"en":"Online tutoring is another form of private lesson.","zh":"網上補習是私人課堂的另一種形式。"},{"en":"Exporting waste can be another form of avoiding local disposal costs.","zh":"出口廢物可以是逃避本地棄置成本的另一種形式。"},{"en":"This phrase helps connect a new example to an earlier category.","zh":"這個短語有助把新例子連接到之前的類別。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":7},{"front":"smelting","meaning":"冶煉","examples":[{"en":"Smelting can present dangers similar to incineration.","zh":"冶煉可能帶來與焚化相似的危險。"},{"en":"Smelting is a process that uses heat to extract metal from ore or waste material.","zh":"smelting 是使用熱力從礦石或廢料中提取金屬的過程。"},{"en":"Metal recycling plants may use smelting to recover valuable metals.","zh":"金屬回收廠可能使用冶煉來回收有價值金屬。"},{"en":"Smelting can release pollutants if plastics or toxic materials remain in the waste.","zh":"如果廢物中仍有塑膠或有毒物料，冶煉可能釋放污染物。"},{"en":"Although smelting can recover resources, it must be carefully controlled.","zh":"雖然冶煉可以回收資源，但必須被小心控制。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":7},{"front":"present dangers similar to","meaning":"帶來與……相似的危險","examples":[{"en":"Smelting can present dangers similar to ordinary incineration.","zh":"冶煉可以帶來與普通焚化相似的危險。"},{"en":"To present dangers similar to something means to create risks like those caused by another thing.","zh":"present dangers similar to something 意思是造成與另一事物相似的風險。"},{"en":"Poorly stored batteries can present dangers similar to other hazardous waste.","zh":"儲存不當的電池可以帶來與其他有害廢物相似的危險。"},{"en":"If a process uses high heat, it may present dangers similar to burning waste.","zh":"如果一個過程使用高溫，它可能帶來與焚燒廢物相似的危險。"},{"en":"This phrase is useful for comparing risks.","zh":"這個短語適合用來比較風險。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":7},{"front":"concerns have been expressed that","meaning":"有人表示擔心","examples":[{"en":"Concerns have been expressed that the smelter is producing atmospheric pollutants.","zh":"有人表示擔心該冶煉廠正在產生大氣污染物。"},{"en":"Concerns have been expressed that means people have publicly said they are worried about something.","zh":"concerns have been expressed that 意思是有人公開表示對某事感到擔心。"},{"en":"Concerns have been expressed that a new road will increase noise near schools.","zh":"有人表示擔心新道路會增加學校附近的噪音。"},{"en":"When concerns are expressed, authorities may need to investigate and provide evidence.","zh":"當有人表示擔心時，當局可能需要調查並提供證據。"},{"en":"This phrase is formal and common in reports.","zh":"這個短語較正式，常見於報告中。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":7},{"front":"atmospheric pollutants","meaning":"大氣污染物","examples":[{"en":"The smelter may produce atmospheric pollutants from plastic residues.","zh":"該冶煉廠可能從塑膠殘留物產生大氣污染物。"},{"en":"Atmospheric pollutants are harmful substances released into the air.","zh":"atmospheric pollutants 是被釋放到空氣中的有害物質。"},{"en":"Smoke from factories and vehicles can contain atmospheric pollutants.","zh":"工廠和車輛的煙霧可以含有大氣污染物。"},{"en":"Atmospheric pollutants can travel far from the place where they were produced.","zh":"大氣污染物可以從產生地飄到很遠。"},{"en":"Reducing atmospheric pollutants helps protect breathing, crops, and climate.","zh":"減少大氣污染物有助保護呼吸、農作物和氣候。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":7},{"front":"residual presence of","meaning":"……的殘留","examples":[{"en":"Pollutants may come from the residual presence of plastics in e-scrap.","zh":"污染物可能來自電子廢料中塑膠的殘留。"},{"en":"The residual presence of something means a small amount remains after most of it has been removed.","zh":"residual presence of something 指某物大部分被移除後仍剩下少量。"},{"en":"The residual presence of detergent in a bottle may affect what can be stored in it later.","zh":"瓶中清潔劑的殘留可能影響日後可存放甚麼。"},{"en":"If plastics remain in e-scrap, their residual presence can cause pollution during heating.","zh":"如果塑膠仍留在電子廢料中，其殘留可能在加熱時造成污染。"},{"en":"This phrase focuses on what is left behind, even in small amounts.","zh":"這個短語集中於即使少量仍留下的東西。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":7},{"front":"e-scrap","meaning":"電子廢料","examples":[{"en":"E-scrap can contain plastics, metals and other hazardous materials.","zh":"電子廢料可以含有塑膠、金屬和其他危險物料。"},{"en":"E-scrap means discarded electronic parts or broken electronic material that may be recycled or processed.","zh":"e-scrap 指被丟棄的電子零件或破損電子材料，可能被回收或處理。"},{"en":"A repair shop may collect e-scrap from broken phones, laptops, and chargers.","zh":"維修店可能收集來自壞手機、手提電腦和充電器的電子廢料。"},{"en":"E-scrap can be valuable because it contains metals, but it can also be dangerous.","zh":"電子廢料因含有金屬而可能有價值，但也可能危險。"},{"en":"Safe handling of e-scrap is important before any metal recovery process.","zh":"在任何金屬回收過程前，安全處理電子廢料很重要。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":7},{"front":"in an effort to","meaning":"為了","examples":[{"en":"In an effort to explore other alternatives, landfills have been tried.","zh":"為了探索其他替代方法，人們曾嘗試使用堆填區。"},{"en":"In an effort to means in order to try to achieve a particular goal.","zh":"in an effort to 意思是為了嘗試達成某個目標。"},{"en":"In an effort to save money, a family may repair a phone instead of buying a new one.","zh":"為了省錢，一個家庭可能維修手機而不是買新手機。"},{"en":"Governments may introduce recycling schemes in an effort to reduce landfill waste.","zh":"政府可能為了減少堆填廢物而推出回收計劃。"},{"en":"This phrase explains the purpose behind an action.","zh":"這個短語解釋行動背後的目的。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":7},{"front":"explore other alternatives","meaning":"探索其他替代方法","examples":[{"en":"Researchers explored other alternatives to incineration.","zh":"研究者探索焚化以外的其他替代方法。"},{"en":"To explore other alternatives means to examine different possible choices or solutions.","zh":"explore other alternatives 意思是研究不同可能選擇或解決方法。"},{"en":"If a medicine does not work, doctors may explore other alternatives.","zh":"如果一種藥物無效，醫生可能探索其他替代方法。"},{"en":"A city may explore other alternatives when landfills become full.","zh":"當堆填區爆滿時，城市可能探索其他替代方法。"},{"en":"Exploring alternatives helps avoid relying on one method that may be unsafe or ineffective.","zh":"探索替代方法有助避免依賴一種可能不安全或無效的方法。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":7},{"front":"landfills have been tried","meaning":"曾嘗試使用堆填區","examples":[{"en":"Landfills have been tried as a method of dealing with e-waste.","zh":"人們曾嘗試使用堆填區作為處理電子廢物的方法。"},{"en":"Landfills have been tried means people have attempted to use landfills as a solution.","zh":"landfills have been tried 意思是人們曾嘗試把堆填區用作解決方法。"},{"en":"Online lessons have been tried when schools cannot open during storms.","zh":"當學校因暴風雨不能開放時，人們曾嘗試使用網課。"},{"en":"Landfills have been tried because they are familiar, but they may not solve the pollution problem.","zh":"人們曾嘗試使用堆填區，因為它們熟悉，但它們未必能解決污染問題。"},{"en":"This phrase suggests a method has been tested, not necessarily proven successful.","zh":"這個短語暗示一種方法曾被測試，但不一定證明成功。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":8},{"front":"studies have shown that","meaning":"研究顯示","examples":[{"en":"Studies have shown that even modern landfills are not completely safe.","zh":"研究顯示，即使現代堆填區也並非完全安全。"},{"en":"Studies have shown that means research has provided evidence for a statement.","zh":"studies have shown that 意思是研究為某說法提供了證據。"},{"en":"Studies have shown that regular sleep helps memory and mood.","zh":"研究顯示，規律睡眠有助記憶和情緒。"},{"en":"If studies show that a disposal method is unsafe, governments should review it.","zh":"如果研究顯示某種棄置方法不安全，政府應重新檢視它。"},{"en":"This phrase is stronger than personal opinion because it refers to research evidence.","zh":"這個短語比個人意見更有力，因為它指向研究證據。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":8},{"front":"not completely safe","meaning":"並非完全安全","examples":[{"en":"Even the best landfills are not completely safe.","zh":"即使最好的堆填區也並非完全安全。"},{"en":"Not completely safe means something still has some risk even if it seems controlled.","zh":"not completely safe 意思是某事即使看似受控，仍有一些風險。"},{"en":"A road with traffic lights is safer, but not completely safe for careless pedestrians.","zh":"有交通燈的道路較安全，但對不小心的行人來說並非完全安全。"},{"en":"Modern landfills are not completely safe because leaks can still occur over time.","zh":"現代堆填區並非完全安全，因為隨時間仍可能發生滲漏。"},{"en":"This phrase warns that improvement does not equal zero risk.","zh":"這個短語提醒人們，改善並不等於零風險。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":8},{"front":"the shortcomings of","meaning":"……的缺點","examples":[{"en":"The shortcomings of dealing with waste through landfills are well documented.","zh":"透過堆填區處理廢物的缺點已有充分記錄。"},{"en":"The shortcomings of something are its weaknesses, problems, or limitations.","zh":"the shortcomings of something 指某事物的弱點、問題或限制。"},{"en":"The shortcomings of online learning may include poor concentration and unequal internet access.","zh":"網上學習的缺點可能包括注意力不足和網絡接入不平等。"},{"en":"Knowing the shortcomings of a policy helps people improve it.","zh":"了解一項政策的缺點有助人們改善它。"},{"en":"This phrase is useful when giving a balanced criticism.","zh":"這個短語適合用來作平衡批評。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":8},{"front":"deal with waste","meaning":"處理廢物","examples":[{"en":"Modern landfills are used to deal with waste.","zh":"現代堆填區被用來處理廢物。"},{"en":"To deal with waste means to manage, treat, store, recycle, or dispose of unwanted materials.","zh":"deal with waste 意思是管理、處理、儲存、回收或棄置不需要的物料。"},{"en":"A restaurant must deal with waste from food scraps, packaging, and used oil.","zh":"餐廳必須處理廚餘、包裝和用過的油所產生的廢物。"},{"en":"If a city cannot deal with waste properly, pollution and public health problems may follow.","zh":"如果城市不能妥善處理廢物，污染和公共健康問題可能隨之而來。"},{"en":"Waste management works best when reduction, reuse, recycling, and safe disposal are combined.","zh":"當減廢、再用、回收和安全棄置結合時，廢物管理效果最好。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":8},{"front":"via modern landfills","meaning":"透過現代堆填區","examples":[{"en":"Dealing with waste via modern landfills still has serious limitations.","zh":"透過現代堆填區處理廢物仍有嚴重限制。"},{"en":"Via modern landfills means by using newer landfill sites designed with better controls.","zh":"via modern landfills 意思是透過使用設計上有較好控制的新式堆填區。"},{"en":"Some cities manage rubbish via modern landfills when recycling cannot handle everything.","zh":"當回收不能處理所有垃圾時，有些城市透過現代堆填區管理垃圾。"},{"en":"Waste disposed of via modern landfills may still create leaching risks over time.","zh":"透過現代堆填區棄置的廢物，隨時間仍可能有滲漏風險。"},{"en":"This phrase identifies the method, not a guarantee of safety.","zh":"這個短語指出方法，而不是保證安全。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":8},{"front":"well documented","meaning":"有充分記錄的","examples":[{"en":"The problems of landfill disposal are well documented.","zh":"堆填棄置的問題已有充分記錄。"},{"en":"Well documented means recorded clearly and supported by many reports, studies, or examples.","zh":"well documented 指被清楚記錄，並由許多報告、研究或例子支持。"},{"en":"The benefits of regular exercise are well documented in health research.","zh":"規律運動的好處在健康研究中已有充分記錄。"},{"en":"If a problem is well documented, leaders cannot easily claim they did not know about it.","zh":"如果一個問題已有充分記錄，領袖很難聲稱自己不知道。"},{"en":"This phrase suggests there is strong recorded evidence.","zh":"這個短語暗示有強而有記錄的證據。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":8},{"front":"the main offender","meaning":"主要元兇","examples":[{"en":"Mercury is the main offender in the area of metal leaching.","zh":"在金屬滲漏方面，水銀是主要元兇。"},{"en":"The main offender is the thing or person most responsible for a problem.","zh":"the main offender 指對某問題負最大責任的事物或人。"},{"en":"In a noisy classroom, one broken fan may be the main offender.","zh":"在嘈雜課室中，一把壞風扇可能是主要元兇。"},{"en":"If mercury is the main offender, safety efforts should focus strongly on mercury-containing parts.","zh":"如果水銀是主要元兇，安全措施應特別集中於含水銀零件。"},{"en":"This phrase is slightly informal but useful for identifying the biggest cause.","zh":"這個短語略帶口語，但適合指出最大成因。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":8},{"front":"in the area of","meaning":"在……方面","examples":[{"en":"Mercury is a major problem in the area of metal leaching.","zh":"在金屬滲漏方面，水銀是一個主要問題。"},{"en":"In the area of means in the field, topic, or aspect of something.","zh":"in the area of 意思是在某個範疇、主題或方面。"},{"en":"A student may need help in the area of grammar but not speaking.","zh":"學生可能在文法方面需要幫助，但說話方面不需要。"},{"en":"In the area of waste disposal, small mistakes can create serious pollution.","zh":"在廢物棄置方面，小錯誤可以造成嚴重污染。"},{"en":"This phrase helps narrow a discussion to one specific aspect.","zh":"這個短語有助把討論收窄到某個具體方面。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":8},{"front":"metal leaching","meaning":"金屬滲漏","examples":[{"en":"Metal leaching can pollute soil and groundwater.","zh":"金屬滲漏可以污染泥土和地下水。"},{"en":"Metal leaching means metals slowly escape or dissolve from materials into soil or water.","zh":"metal leaching 指金屬慢慢從材料中流出或溶出，進入泥土或水中。"},{"en":"Old batteries can cause metal leaching if they are left in wet ground.","zh":"舊電池如果被留在潮濕地面，可能造成金屬滲漏。"},{"en":"Metal leaching from e-waste can harm plants, animals, and drinking water.","zh":"電子廢物中的金屬滲漏可以傷害植物、動物和飲用水。"},{"en":"Preventing metal leaching requires safe storage and proper disposal.","zh":"防止金屬滲漏需要安全儲存和妥善棄置。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":8},{"front":"mercury","meaning":"水銀；汞","examples":[{"en":"Mercury can leach from electronic devices into the soil.","zh":"水銀可以從電子裝置滲入泥土。"},{"en":"Mercury is a toxic metal that can harm the nervous system and the environment.","zh":"mercury 是一種會傷害神經系統和環境的有毒金屬。"},{"en":"Some older lamps, switches, and electronic parts may contain mercury.","zh":"一些較舊燈管、開關和電子零件可能含有水銀。"},{"en":"If mercury leaks into soil or water, it can spread through ecosystems.","zh":"如果水銀滲入泥土或水中，可以在生態系統中擴散。"},{"en":"Products containing mercury should never be thrown away casually.","zh":"含水銀產品絕不應被隨意丟棄。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":8},{"front":"in varying degrees","meaning":"在不同程度上","examples":[{"en":"In varying degrees, mercury can escape from electronic devices.","zh":"在不同程度上，水銀可以從電子裝置中流出。"},{"en":"In varying degrees means to different amounts, levels, or extents.","zh":"in varying degrees 意思是在不同數量、水平或程度上。"},{"en":"Students may feel exam pressure in varying degrees depending on family expectations.","zh":"學生可能因家庭期望不同而在不同程度上感到考試壓力。"},{"en":"Waste sites leak in varying degrees, so even controlled sites may still pose some risk.","zh":"廢物場會在不同程度上滲漏，所以即使受控場地仍可能有一些風險。"},{"en":"This phrase shows that a problem may not happen equally everywhere.","zh":"這個短語顯示問題不一定在每個地方同樣發生。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":9},{"front":"escape or leach from","meaning":"從……流出或滲出","examples":[{"en":"Mercury can escape or leach from circuit boards into the soil.","zh":"水銀可以從電路板流出或滲入泥土。"},{"en":"To escape or leach from something means to leak out or slowly move out of it.","zh":"escape or leach from something 意思是從某物中漏出或慢慢滲出。"},{"en":"Chemicals may escape or leach from old containers if they are cracked.","zh":"如果舊容器有裂縫，化學物質可能從中流出或滲出。"},{"en":"If metals escape or leach from e-waste, nearby soil and water may become polluted.","zh":"如果金屬從電子廢物中流出或滲出，附近泥土和水可能受污染。"},{"en":"This phrase is often used for harmful substances leaving waste materials.","zh":"這個短語常用於有害物質離開廢料時。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":9},{"front":"electronic devices","meaning":"電子裝置","examples":[{"en":"Some electronic devices contain mercury.","zh":"一些電子裝置含有水銀。"},{"en":"Electronic devices are machines or tools that use electricity and electronic parts to work.","zh":"electronic devices 是使用電力和電子零件運作的機器或工具。"},{"en":"Phones, tablets, laptops, and smart watches are everyday electronic devices.","zh":"手機、平板、手提電腦和智能手錶都是日常電子裝置。"},{"en":"Electronic devices become waste when they break, lose support, or are replaced too quickly.","zh":"當電子裝置損壞、失去支援或太快被替換時，它們會變成廢物。"},{"en":"People should recycle electronic devices through proper collection schemes.","zh":"人們應透過合適收集計劃回收電子裝置。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":9},{"front":"circuit breakers","meaning":"斷路器","examples":[{"en":"Circuit breakers may contain substances that can leach into the soil.","zh":"斷路器可能含有會滲入泥土的物質。"},{"en":"Circuit breakers are safety devices that stop electrical current when there is an overload or fault.","zh":"circuit breakers 是在過載或故障時切斷電流的安全裝置。"},{"en":"A home’s circuit breaker may cut power if too many appliances are used at once.","zh":"如果家中同時使用太多電器，斷路器可能切斷電源。"},{"en":"Old circuit breakers can become e-waste when buildings are repaired or upgraded.","zh":"建築物維修或升級時，舊斷路器可能變成電子廢物。"},{"en":"Because some components may contain hazardous materials, circuit breakers should be disposed of carefully.","zh":"因為部分部件可能含有危險物料，斷路器應被小心棄置。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":9},{"front":"condensers","meaning":"電容器","examples":[{"en":"Condensers are among the electronic parts that may release mercury.","zh":"電容器是可能釋放水銀的電子零件之一。"},{"en":"Condensers are electronic components that store electrical energy; they are often called capacitors today.","zh":"condensers 是儲存電能的電子部件；今天常稱為 capacitors。"},{"en":"Old electrical equipment may contain condensers that need careful handling.","zh":"舊電氣設備可能含有需要小心處理的電容器。"},{"en":"If condensers contain hazardous substances, breaking them can create pollution risks.","zh":"如果電容器含有危險物質，打破它們可能造成污染風險。"},{"en":"In e-waste texts, this word usually refers to small but important electrical parts.","zh":"在電子廢物文章中，這個詞通常指細小但重要的電氣零件。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":9},{"front":"computer circuit boards","meaning":"電腦電路板","examples":[{"en":"Computer circuit boards may release metals into the soil.","zh":"電腦電路板可能把金屬釋放到泥土中。"},{"en":"Computer circuit boards are boards inside computers that connect chips, wires, and other electronic parts.","zh":"computer circuit boards 是電腦內連接晶片、電線和其他電子零件的板。"},{"en":"A computer cannot work properly if its circuit board is badly damaged.","zh":"如果電路板嚴重損壞，電腦就無法正常運作。"},{"en":"Computer circuit boards can pollute the environment if they are dumped and metals leach out.","zh":"如果電腦電路板被傾倒並有金屬滲出，可能污染環境。"},{"en":"They are valuable for recycling but risky if handled carelessly.","zh":"它們有回收價值，但若處理粗疏就有風險。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":9},{"front":"into the soil","meaning":"滲入泥土","examples":[{"en":"Mercury can leach from electronic devices into the soil.","zh":"水銀可以從電子裝置滲入泥土。"},{"en":"Into the soil means moving or entering the ground where plants grow.","zh":"into the soil 意思是進入植物生長的泥土或地面。"},{"en":"Rain can wash chemicals from rubbish into the soil.","zh":"雨水可以把垃圾中的化學物質沖入泥土。"},{"en":"When toxic metals enter the soil, crops and groundwater may be affected.","zh":"當有毒金屬進入泥土，農作物和地下水可能受影響。"},{"en":"Pollution that goes into the soil can remain there for a long time.","zh":"滲入泥土的污染物可以長時間留在那裡。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":9},{"front":"according to","meaning":"根據","examples":[{"en":"According to Phil Stevenson, everyone knows that landfills leak.","zh":"根據 Phil Stevenson 的說法，人人都知道堆填區會滲漏。"},{"en":"According to means as stated by or based on a particular source.","zh":"according to 意思是根據某個來源所說或所示。"},{"en":"According to the timetable, the last train leaves at midnight.","zh":"根據時間表，尾班車午夜開出。"},{"en":"According to experts, unsafe e-waste disposal can create health risks.","zh":"根據專家所說，不安全的電子廢物棄置可以造成健康風險。"},{"en":"This phrase helps show where information comes from.","zh":"這個短語有助顯示資訊來源。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":9},{"front":"managing director","meaning":"董事總經理","examples":[{"en":"Phil Stevenson is the managing director of CleanCo.","zh":"Phil Stevenson 是 CleanCo 的董事總經理。"},{"en":"A managing director is a senior leader who manages the overall work of a company.","zh":"managing director 是管理公司整體工作的高級領導。"},{"en":"The managing director may decide company strategy, budgets, and major partnerships.","zh":"董事總經理可能決定公司策略、預算和主要合作。"},{"en":"If a recycling plant faces safety problems, the managing director may be asked to explain the response.","zh":"如果回收廠面對安全問題，董事總經理可能被要求解釋回應。"},{"en":"This job title suggests the person has authority inside the organisation.","zh":"這個職銜暗示該人在機構內有權力。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":9},{"front":"recycling plant","meaning":"回收廠","examples":[{"en":"CleanCo is described as a recycling plant in the UK.","zh":"CleanCo 被描述為英國一間回收廠。"},{"en":"A recycling plant is a facility where waste materials are sorted, processed, and prepared for reuse.","zh":"recycling plant 是把廢料分類、處理並準備再用的設施。"},{"en":"A recycling plant may handle paper, plastic, metal, glass, or electronic waste.","zh":"回收廠可能處理紙張、塑膠、金屬、玻璃或電子廢物。"},{"en":"If a recycling plant lacks safety controls, workers may be exposed to harmful materials.","zh":"如果回收廠缺乏安全控制，工人可能接觸有害物料。"},{"en":"Recycling plants are important, but they must be managed carefully.","zh":"回收廠很重要，但必須被妥善管理。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":9},{"front":"common knowledge","meaning":"常識；眾所周知的事","examples":[{"en":"It has become common knowledge that landfills can leak.","zh":"堆填區會滲漏已成為常識。"},{"en":"Common knowledge is information that many people know or accept as true.","zh":"common knowledge 是許多人知道或接受為真的資訊。"},{"en":"It is common knowledge that exercise and sleep affect health.","zh":"運動和睡眠會影響健康是常識。"},{"en":"When a risk becomes common knowledge, companies cannot easily deny responsibility.","zh":"當風險成為眾所周知的事，公司很難否認責任。"},{"en":"Common knowledge may still need evidence in formal writing.","zh":"在正式寫作中，常識仍可能需要證據支持。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":9},{"front":"state-of-the-art landfills","meaning":"最先進的堆填區","examples":[{"en":"Even state-of-the-art landfills are not completely tight.","zh":"即使最先進的堆填區也不是完全密封的。"},{"en":"State-of-the-art landfills are modern landfill sites built with the newest technology and controls.","zh":"state-of-the-art landfills 是以最新科技和控制措施建造的現代堆填區。"},{"en":"A city may build state-of-the-art landfills to reduce leakage and smell.","zh":"城市可能建造最先進的堆填區，以減少滲漏和氣味。"},{"en":"Even state-of-the-art landfills can fail over time if materials wear down.","zh":"即使最先進的堆填區，材料隨時間耗損後也可能失效。"},{"en":"Advanced design reduces risk, but it does not remove risk completely.","zh":"先進設計降低風險，但不會完全消除風險。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":10},{"front":"completely tight","meaning":"完全密封的","examples":[{"en":"Even the best landfills are not completely tight throughout their lifetimes.","zh":"即使最好的堆填區在整個使用期內也不是完全密封的。"},{"en":"Completely tight means fully sealed so that nothing can leak out.","zh":"completely tight 意思是完全封閉，沒有東西能漏出。"},{"en":"A water bottle is not completely tight if liquid escapes from the cap.","zh":"如果水從瓶蓋漏出，水樽就不是完全密封的。"},{"en":"If a landfill is not completely tight, chemicals may slowly leak into surrounding soil.","zh":"如果堆填區不是完全密封的，化學物質可能慢慢滲入周圍泥土。"},{"en":"This phrase focuses on whether a container or barrier can prevent leakage.","zh":"這個短語集中於容器或屏障能否防止滲漏。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":10},{"front":"throughout their lifetimes","meaning":"在其整個使用期內","examples":[{"en":"Landfills are not completely tight throughout their lifetimes.","zh":"堆填區在其整個使用期內並非完全密封。"},{"en":"Throughout their lifetimes means during the whole period that something exists or is used.","zh":"throughout their lifetimes 意思是在某物存在或被使用的整個時期內。"},{"en":"A phone may need software updates throughout its lifetime.","zh":"手機在其整個使用期內可能需要軟件更新。"},{"en":"Landfill barriers may weaken throughout their lifetimes because materials age.","zh":"堆填區屏障可能在整個使用期內因材料老化而變弱。"},{"en":"This phrase reminds us that long-term performance matters, not only the first day.","zh":"這個短語提醒我們，長期表現很重要，而不只是第一天的表現。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":10},{"front":"to one degree or another","meaning":"在某程度上","examples":[{"en":"To one degree or another, chemical and metal leaching occurs.","zh":"在某程度上，化學物質及金屬滲漏會發生。"},{"en":"To one degree or another means in some amount or level, even if the amount differs.","zh":"to one degree or another 意思是在某種數量或程度上，即使程度不同。"},{"en":"All students feel nervous before exams to one degree or another.","zh":"所有學生在考試前都會在某程度上緊張。"},{"en":"Waste sites may leak to one degree or another depending on design and age.","zh":"廢物場可能因設計和年期不同而在某程度上滲漏。"},{"en":"This phrase shows that something happens generally, but not equally everywhere.","zh":"這個短語顯示某事普遍會發生，但不一定每處程度相同。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":10},{"front":"chemical and metal leaching","meaning":"化學物質及金屬滲漏","examples":[{"en":"Chemical and metal leaching can occur even in modern landfills.","zh":"即使在現代堆填區中，化學物質及金屬滲漏也可能發生。"},{"en":"Chemical and metal leaching means chemicals and metals slowly leaking from waste into soil or water.","zh":"chemical and metal leaching 指化學物質和金屬從廢物中慢慢滲入泥土或水中。"},{"en":"Old batteries may cause chemical and metal leaching if they are thrown into normal rubbish.","zh":"如果舊電池被丟進普通垃圾，可能造成化學物質及金屬滲漏。"},{"en":"Chemical and metal leaching can pollute groundwater and make cleanup difficult.","zh":"化學物質及金屬滲漏可以污染地下水，並令清理困難。"},{"en":"Proper liners and collection systems are used to reduce this risk.","zh":"妥善襯層和收集系統被用來減少這種風險。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":10},{"front":"far worse","meaning":"糟得多","examples":[{"en":"The situation is far worse for older dump sites.","zh":"對較舊的垃圾場來說，情況糟得多。"},{"en":"Far worse means much more serious, harmful, or bad.","zh":"far worse 意思是嚴重、有害或糟糕得多。"},{"en":"A small leak is bad, but a broken pipe flooding a classroom is far worse.","zh":"小滲漏已經不好，但水管破裂淹浸課室就糟得多。"},{"en":"Older waste sites can be far worse because they were built with fewer controls.","zh":"較舊廢物場可能糟得多，因為它們建造時管制較少。"},{"en":"This phrase is stronger than worse and shows a large difference.","zh":"這個短語比 worse 更強，顯示差異很大。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":10},{"front":"less stringent dump sites","meaning":"規管較寬鬆的堆填場","examples":[{"en":"Older or less stringent dump sites create greater risks.","zh":"較舊或規管較寬鬆的堆填場會造成更大風險。"},{"en":"Less stringent dump sites are waste areas with weaker rules, looser controls, or poorer safety standards.","zh":"less stringent dump sites 指規則較弱、控制較鬆或安全標準較差的廢物場。"},{"en":"A less stringent dump site may allow dangerous waste without proper checks.","zh":"規管較寬鬆的堆填場可能容許危險廢物未經妥善檢查進入。"},{"en":"Less stringent dump sites can lead to fires, leaks, and toxic pollution.","zh":"規管較寬鬆的堆填場可以導致火災、滲漏和有毒污染。"},{"en":"Strict standards matter because weak dumping rules often shift risks to nearby communities.","zh":"嚴格標準很重要，因為寬鬆傾倒規則常把風險轉移到附近社區。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":10},{"front":"uncontrolled fires","meaning":"不受控制的火災","examples":[{"en":"Uncontrolled fires can release toxic chemicals from landfill areas.","zh":"不受控制的火災可以從堆填區釋放有毒化學物質。"},{"en":"Uncontrolled fires are fires that are not managed, contained, or safely put out.","zh":"uncontrolled fires 指沒有被管理、限制或安全撲滅的火災。"},{"en":"An uncontrolled fire in a waste site can spread quickly because many materials burn easily.","zh":"廢物場中的不受控制火災可以迅速擴散，因為許多材料容易燃燒。"},{"en":"When uncontrolled fires burn e-waste, toxic smoke may be released into the air.","zh":"當不受控制的火災焚燒電子廢物時，有毒煙霧可能被釋放到空氣中。"},{"en":"Fire prevention is essential at waste sites because uncontrolled fires are difficult to stop.","zh":"廢物場必須預防火災，因為不受控制的火災難以撲滅。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":10},{"front":"burn through","meaning":"燒遍；燒穿","examples":[{"en":"Uncontrolled fires may burn through landfill areas.","zh":"不受控制的火災可能燒遍堆填區。"},{"en":"To burn through something means fire spreads across or penetrates it by burning.","zh":"burn through something 意思是火透過燃燒擴散或穿透某物。"},{"en":"A candle can burn through paper if it is placed too close.","zh":"如果蠟燭放得太近，可能燒穿紙張。"},{"en":"If fire burns through e-waste, toxic metals and chemicals may be released.","zh":"如果火燒過電子廢物，有毒金屬和化學物質可能被釋放。"},{"en":"This phrase suggests fire moves through material and causes damage.","zh":"這個短語暗示火在材料中移動並造成損害。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":10},{"front":"toxic chemicals","meaning":"有毒化學物質","examples":[{"en":"Lead and cadmium are toxic chemicals that can be released by fire.","zh":"鉛和鎘是可由火災釋放的有毒化學物質。"},{"en":"Toxic chemicals are chemical substances that can poison people, animals, plants, or the environment.","zh":"toxic chemicals 是可以毒害人、動物、植物或環境的化學物質。"},{"en":"Factories must label toxic chemicals clearly so workers know the risks.","zh":"工廠必須清楚標示有毒化學物質，讓工人知道風險。"},{"en":"Toxic chemicals released by burning waste can enter the air and harm nearby residents.","zh":"焚燒廢物釋放的有毒化學物質可以進入空氣並傷害附近居民。"},{"en":"Careful storage and disposal reduce the chance of toxic chemicals escaping.","zh":"小心儲存和棄置可以減少有毒化學物質外洩的機會。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":10},{"front":"cadmium","meaning":"鎘","examples":[{"en":"Cadmium may be released when landfill fires burn through e-waste.","zh":"當堆填區火災燒過電子廢物時，鎘可能被釋放。"},{"en":"Cadmium is a toxic heavy metal used in some batteries and electronic materials.","zh":"cadmium 是一種有毒重金屬，用於某些電池和電子材料。"},{"en":"Workers handling cadmium-containing waste need protective equipment.","zh":"處理含鎘廢物的工人需要防護設備。"},{"en":"If cadmium enters soil or water, it can create long-term health and environmental risks.","zh":"如果鎘進入泥土或水中，可能造成長期健康和環境風險。"},{"en":"In e-waste discussions, cadmium is usually mentioned as a substance requiring strict control.","zh":"在電子廢物討論中，鎘通常被提及為需要嚴格管制的物質。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":10},{"front":"be released","meaning":"被釋放","examples":[{"en":"Toxic chemicals can be released when waste burns.","zh":"廢物燃燒時，有毒化學物質可以被釋放。"},{"en":"To be released means to be let out, set free, or allowed to escape.","zh":"be released 意思是被放出、釋出或允許逃出。"},{"en":"Smoke may be released when plastic is burned.","zh":"塑膠被焚燒時，煙霧可能被釋放。"},{"en":"If toxic gases are released, people nearby may need to leave the area.","zh":"如果有毒氣體被釋放，附近的人可能需要離開該區。"},{"en":"This phrase is often used when hidden substances come out into the environment.","zh":"這個短語常用於隱藏物質進入環境時。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":11},{"front":"an overwhelming majority of","meaning":"壓倒性大多數的……","examples":[{"en":"An overwhelming majority of hazardous e-waste comes from industrialised economies.","zh":"壓倒性大多數的有害電子廢物來自工業化經濟體。"},{"en":"An overwhelming majority of something means almost all or a very large proportion of it.","zh":"an overwhelming majority of something 指幾乎全部或非常大比例的某事物。"},{"en":"An overwhelming majority of students may prefer clear examples to abstract explanations.","zh":"壓倒性大多數學生可能較喜歡清楚例子，而不是抽象解釋。"},{"en":"If an overwhelming majority of waste comes from wealthy countries, responsibility is not evenly shared.","zh":"如果壓倒性大多數廢物來自富裕國家，責任就不是平均分擔的。"},{"en":"This phrase is stronger than most and suggests a very clear imbalance.","zh":"這個短語比 most 更強，暗示非常明顯的不平衡。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":11},{"front":"hazardous e-waste","meaning":"有害電子廢物","examples":[{"en":"Hazardous e-waste is often generated by wealthy industrialised economies.","zh":"有害電子廢物通常由富裕工業化經濟體產生。"},{"en":"Hazardous e-waste is electronic waste that contains dangerous substances and can harm health or the environment.","zh":"hazardous e-waste 指含有危險物質，並可能傷害健康或環境的電子廢物。"},{"en":"Old monitors, batteries, and circuit boards may become hazardous e-waste.","zh":"舊顯示器、電池和電路板可能變成有害電子廢物。"},{"en":"Hazardous e-waste requires special handling because toxic materials may leak or burn.","zh":"有害電子廢物需要特別處理，因為有毒物料可能滲漏或燃燒。"},{"en":"Treating hazardous e-waste like normal rubbish can create serious risks.","zh":"把有害電子廢物當成普通垃圾處理，可以造成嚴重風險。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":11},{"front":"be generated by","meaning":"由……產生","examples":[{"en":"Most hazardous e-waste is generated by industrialised market economies.","zh":"大多數有害電子廢物由工業化市場經濟體產生。"},{"en":"To be generated by something means to be produced or created by it.","zh":"be generated by something 意思是由某事物生產或造成。"},{"en":"Noise may be generated by traffic outside a school.","zh":"噪音可能由學校外的交通產生。"},{"en":"Large amounts of e-waste are generated by frequent upgrades and short product lives.","zh":"大量電子廢物由頻繁升級和短產品壽命產生。"},{"en":"This phrase is often used in formal writing about causes and sources.","zh":"這個短語常用於正式寫作中描述原因和來源。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":11},{"front":"industrialised market economies","meaning":"工業化市場經濟體","examples":[{"en":"Industrialised market economies produce most of the world’s hazardous e-waste.","zh":"工業化市場經濟體產生世界上大部分有害電子廢物。"},{"en":"Industrialised market economies are wealthy economies with advanced industries and market-based business systems.","zh":"industrialised market economies 指擁有先進工業和市場式商業制度的富裕經濟體。"},{"en":"Countries with large technology markets often belong to industrialised market economies.","zh":"擁有大型科技市場的國家通常屬於工業化市場經濟體。"},{"en":"Industrialised market economies may create more e-waste because consumers buy and replace more products.","zh":"工業化市場經濟體可能產生更多電子廢物，因為消費者購買和替換更多產品。"},{"en":"The phrase connects economic development with waste responsibility.","zh":"這個短語把經濟發展與廢物責任連繫起來。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":11},{"front":"labour costs","meaning":"勞工成本","examples":[{"en":"Low labour costs can make e-waste exports attractive.","zh":"低勞工成本可以令電子廢物出口變得吸引。"},{"en":"Labour costs are the money paid for workers’ wages, benefits, and related employment expenses.","zh":"labour costs 是支付工人工資、福利和相關僱傭開支的金錢。"},{"en":"A company may move work overseas if labour costs are much lower there.","zh":"如果海外勞工成本低得多，公司可能把工作轉移到海外。"},{"en":"Low labour costs can reduce business expenses but may also hide unsafe working conditions.","zh":"低勞工成本可以降低企業開支，但也可能掩蓋不安全工作環境。"},{"en":"In waste disposal, labour costs can influence where companies send materials.","zh":"在廢物棄置中，勞工成本可以影響公司把物料送到哪裡。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":11},{"front":"government regulations","meaning":"政府規管","examples":[{"en":"Weak government regulations can encourage the export of e-waste.","zh":"薄弱的政府規管可以鼓勵電子廢物出口。"},{"en":"Government regulations are official rules made by authorities to control behaviour, safety, or business.","zh":"government regulations 是當局制定的官方規則，用來管制行為、安全或商業。"},{"en":"Government regulations may require companies to recycle batteries safely.","zh":"政府規管可能要求公司安全回收電池。"},{"en":"If government regulations are weak, companies may choose cheaper but harmful disposal methods.","zh":"如果政府規管薄弱，公司可能選擇較便宜但有害的棄置方法。"},{"en":"Strong regulations can protect workers, consumers, and the environment.","zh":"強而有力的規管可以保護工人、消費者和環境。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":11},{"front":"decidedly lax","meaning":"明顯寬鬆的","examples":[{"en":"Government regulations in some countries are decidedly lax.","zh":"一些國家的政府規管明顯寬鬆。"},{"en":"Decidedly lax means clearly too loose, weak, or not strict enough.","zh":"decidedly lax 意思是明顯過於寬鬆、薄弱或不夠嚴格。"},{"en":"A school’s phone rules are decidedly lax if students can use phones during exams.","zh":"如果學生考試期間可以用手機，學校的手機規則就是明顯寬鬆的。"},{"en":"Decidedly lax waste controls can allow dangerous materials to be dumped cheaply.","zh":"明顯寬鬆的廢物管制可以容許危險物料被低價傾倒。"},{"en":"This phrase is critical and suggests the weakness is obvious.","zh":"這個短語帶批評意味，暗示弱點很明顯。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":11},{"front":"the export of e-waste","meaning":"電子廢物出口","examples":[{"en":"The export of e-waste has been used as another method of disposal.","zh":"電子廢物出口一直被用作另一種棄置方法。"},{"en":"The export of e-waste means sending electronic waste to another country.","zh":"the export of e-waste 指把電子廢物送到另一個國家。"},{"en":"A company may choose the export of e-waste if overseas treatment is cheaper.","zh":"如果海外處理較便宜，公司可能選擇電子廢物出口。"},{"en":"The export of e-waste can move pollution from rich countries to poorer ones.","zh":"電子廢物出口可以把污染從富裕國家轉移到較貧困國家。"},{"en":"This practice needs transparency because the final destination may be unclear.","zh":"這種做法需要透明度，因為最終去向可能不清楚。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":11},{"front":"method of disposal","meaning":"棄置方法","examples":[{"en":"Exporting e-waste is one method of disposal.","zh":"出口電子廢物是一種棄置方法。"},{"en":"A method of disposal is a way of getting rid of unwanted materials.","zh":"method of disposal 是處理不需要物料的方法。"},{"en":"Recycling, landfill, incineration, and export are different methods of disposal.","zh":"回收、堆填、焚化和出口都是不同棄置方法。"},{"en":"A cheap method of disposal may still be harmful if it creates pollution elsewhere.","zh":"便宜的棄置方法若在其他地方造成污染，仍可能有害。"},{"en":"The best method of disposal depends on safety, cost, law, and environmental impact.","zh":"最佳棄置方法取決於安全、成本、法律和環境影響。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":11},{"front":"12 times cheaper to","meaning":"便宜十二倍","examples":[{"en":"It was estimated to be 12 times cheaper to ship monitors to China than to recycle them.","zh":"據估計，把顯示器運到中國比回收它們便宜十二倍。"},{"en":"12 times cheaper to do something means the cost is much lower, at one-twelfth of another option.","zh":"12 times cheaper to do something 意思是成本低很多，大約是另一選項的十二分之一。"},{"en":"It may be 12 times cheaper to repair a small part than to replace the whole machine.","zh":"維修一個小零件可能比更換整部機器便宜十二倍。"},{"en":"If exporting waste is 12 times cheaper, companies may choose it unless laws prevent harm.","zh":"如果出口廢物便宜十二倍，除非法律阻止傷害，否則公司可能選擇這樣做。"},{"en":"Large cost differences can explain why environmentally risky choices happen.","zh":"巨大成本差異可以解釋為何會出現有環境風險的選擇。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":11},{"front":"ship old computer monitors","meaning":"運送舊電腦顯示器","examples":[{"en":"Some companies ship old computer monitors overseas.","zh":"有些公司把舊電腦顯示器運往海外。"},{"en":"To ship old computer monitors means to send used or unwanted screens by transport, often to another place or country.","zh":"ship old computer monitors 意思是把使用過或不需要的螢幕運送到另一地方或國家。"},{"en":"An office may ship old computer monitors to a recycling contractor after upgrading equipment.","zh":"辦公室升級設備後，可能把舊電腦顯示器運給回收承辦商。"},{"en":"Companies may ship monitors overseas if local recycling is expensive.","zh":"如果本地回收昂貴，公司可能把顯示器運往海外。"},{"en":"Shipping old monitors can be risky if no one checks how they are handled later.","zh":"如果無人檢查之後如何處理，運送舊顯示器可能有風險。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":12},{"front":"recycle them domestically","meaning":"在本地回收它們","examples":[{"en":"It may cost more to recycle old monitors domestically.","zh":"在本地回收舊顯示器可能成本較高。"},{"en":"To recycle them domestically means to process and reuse the materials within the same country.","zh":"recycle them domestically 意思是在同一國家內處理並再用其物料。"},{"en":"A country may prefer to recycle batteries domestically to control safety standards.","zh":"一個國家可能偏好在本地回收電池，以控制安全標準。"},{"en":"Recycling e-waste domestically can be more expensive because wages and regulations may be stricter.","zh":"在本地回收電子廢物可能較昂貴，因為工資和規管可能較嚴格。"},{"en":"Domestic recycling helps keep responsibility closer to the place where waste is produced.","zh":"本地回收有助把責任留在廢物產生地附近。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":12},{"front":"data on the prevalence of","meaning":"關於……普遍程度的數據","examples":[{"en":"Data on the prevalence of e-waste exports are scarce.","zh":"關於電子廢物出口普遍程度的數據很少。"},{"en":"Data on the prevalence of something means information about how common or widespread it is.","zh":"data on the prevalence of something 指關於某事有多常見或多廣泛的資訊。"},{"en":"Schools may collect data on the prevalence of bullying to decide what support is needed.","zh":"學校可能收集關於欺凌普遍程度的數據，以決定需要甚麼支援。"},{"en":"Without data on prevalence, it is difficult to know how large a problem is.","zh":"沒有關於普遍程度的數據，就很難知道問題有多大。"},{"en":"This phrase is formal and common in research writing.","zh":"這個短語較正式，常見於研究寫作。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":12},{"front":"scarce","meaning":"稀少的；不足的","examples":[{"en":"Reliable data on e-waste exports are scarce.","zh":"關於電子廢物出口的可靠數據很稀少。"},{"en":"Scarce means not enough or difficult to find.","zh":"scarce 意思是不足或難以找到。"},{"en":"Affordable housing is scarce in many large cities.","zh":"在許多大城市，負擔得起的住房很稀少。"},{"en":"When data are scarce, researchers must be careful not to make overconfident claims.","zh":"當數據不足時，研究者必須小心，不要提出過度自信的說法。"},{"en":"Scarce resources should be used wisely because there is not enough for everyone.","zh":"稀少資源應被明智使用，因為並非人人都夠用。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":12},{"front":"due to","meaning":"由於","examples":[{"en":"Data are scarce due to past bad publicity.","zh":"由於過往的負面宣傳，數據很少。"},{"en":"Due to means because of.","zh":"due to 意思是由於或因為。"},{"en":"The lesson was cancelled due to bad weather.","zh":"課堂因天氣惡劣而取消。"},{"en":"E-waste data may be scarce due to secrecy, poor records, or fear of criticism.","zh":"電子廢物數據可能因保密、紀錄差或害怕批評而稀少。"},{"en":"Use due to when explaining the reason behind a result.","zh":"解釋結果背後的原因時，可以使用 due to。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":12},{"front":"past bad publicity","meaning":"過往的負面宣傳","examples":[{"en":"Past bad publicity made dealers less willing to reveal details.","zh":"過往的負面宣傳令商人較不願透露細節。"},{"en":"Past bad publicity means earlier negative attention from newspapers, the public, or other media.","zh":"past bad publicity 指早前來自報章、公眾或其他媒體的負面關注。"},{"en":"A restaurant may lose customers because of past bad publicity about hygiene.","zh":"餐廳可能因過往關於衛生的負面宣傳而失去顧客。"},{"en":"Past bad publicity can make companies secretive even when people ask reasonable questions.","zh":"過往的負面宣傳可以令公司變得保密，即使人們提出合理問題。"},{"en":"This phrase explains why people may avoid sharing information.","zh":"這個短語解釋為何人們可能避免分享資訊。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":12},{"front":"dealers of e-scrap","meaning":"電子廢料商","examples":[{"en":"Dealers of e-scrap may not know the final destination of the products they sell.","zh":"電子廢料商可能不知道他們所售產品的最終去向。"},{"en":"Dealers of e-scrap are people or companies that buy and sell discarded electronic materials.","zh":"dealers of e-scrap 是買賣廢棄電子材料的人或公司。"},{"en":"A dealer of e-scrap may collect old circuit boards from repair shops.","zh":"電子廢料商可能從維修店收集舊電路板。"},{"en":"If dealers do not track e-scrap, hazardous waste may end up in unsafe places.","zh":"如果商人不追蹤電子廢料，有害廢物可能最終去到不安全地方。"},{"en":"Responsible dealers should know who receives the waste and how it is processed.","zh":"負責任的商人應知道誰接收廢物以及如何處理。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":12},{"front":"do not bother to","meaning":"懶得；不費心去","examples":[{"en":"Some dealers do not bother to determine where the e-scrap ends up.","zh":"有些商人懶得確定電子廢料最終去向。"},{"en":"Do not bother to do something means do not make the effort to do it.","zh":"do not bother to do something 意思是不願花心力去做某事。"},{"en":"Some students do not bother to check spelling before submitting homework.","zh":"有些學生交功課前懶得檢查串字。"},{"en":"If dealers do not bother to track waste, pollution may be hidden from public view.","zh":"如果商人不費心追蹤廢物，污染可能被隱藏在公眾視線之外。"},{"en":"This phrase often shows criticism of laziness or carelessness.","zh":"這個短語常帶有對懶惰或粗心的批評。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":12},{"front":"determine the final destination","meaning":"確定最終去向","examples":[{"en":"Dealers often do not determine the final destination of the products they sell.","zh":"商人常沒有確定他們所售產品的最終去向。"},{"en":"To determine the final destination means to find out or decide where something finally goes.","zh":"determine the final destination 意思是查明或決定某物最後去到哪裡。"},{"en":"A delivery company must determine the final destination before sending a parcel.","zh":"速遞公司在寄包裹前必須確定最終目的地。"},{"en":"If no one determines the final destination of e-waste, unsafe dumping may continue.","zh":"如果沒有人確定電子廢物的最終去向，不安全傾倒可能繼續。"},{"en":"This phrase is important when responsibility depends on tracking movement.","zh":"當責任取決於追蹤流向時，這個短語很重要。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":12},{"front":"the final destination of","meaning":"……的最終去向","examples":[{"en":"The final destination of exported e-waste is often unclear.","zh":"出口電子廢物的最終去向常不清楚。"},{"en":"The final destination of something is the place where it finally ends up.","zh":"the final destination of something 指某物最後到達的地方。"},{"en":"The final destination of a recycled bottle may be a factory that turns it into new material.","zh":"回收膠樽的最終去向可能是一間把它變成新材料的工廠。"},{"en":"If the final destination of waste is unknown, safety cannot be fully checked.","zh":"如果廢物的最終去向不明，安全就不能完全核查。"},{"en":"This phrase asks where something goes at the end of a process.","zh":"這個短語問某物在過程結束時去到哪裡。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":12},{"front":"the world community","meaning":"國際社會","examples":[{"en":"The world community established an agreement on hazardous waste movements.","zh":"國際社會就有害廢物轉移制定了一項協議。"},{"en":"The world community means countries and international organisations acting together on global issues.","zh":"the world community 指各國和國際組織一起處理全球議題。"},{"en":"The world community may cooperate during climate disasters or disease outbreaks.","zh":"國際社會可能在氣候災害或疾病爆發期間合作。"},{"en":"When pollution crosses borders, the world community must create shared rules.","zh":"當污染跨越國界時，國際社會必須制定共同規則。"},{"en":"This phrase presents a problem as international, not only local.","zh":"這個短語把問題呈現為國際問題，而不只是本地問題。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":12},{"front":"establish a convention","meaning":"制定公約","examples":[{"en":"The world community established a convention to control hazardous waste exports.","zh":"國際社會制定公約以管制有害廢物出口。"},{"en":"To establish a convention means to create a formal international agreement.","zh":"establish a convention 意思是建立正式國際協議。"},{"en":"Countries may establish a convention to protect endangered animals.","zh":"各國可能制定公約來保護瀕危動物。"},{"en":"A convention can create shared rules when individual national laws are not enough.","zh":"當個別國家法律不足時，公約可以建立共同規則。"},{"en":"This phrase is common in discussions of international law.","zh":"這個短語常見於國際法討論。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":13},{"front":"the Basel Convention","meaning":"《巴塞爾公約》","examples":[{"en":"The Basel Convention was created to control hazardous waste movements.","zh":"《巴塞爾公約》被制定來管制有害廢物轉移。"},{"en":"The Basel Convention is an international agreement about controlling the movement and disposal of hazardous waste.","zh":"the Basel Convention 是關於管制有害廢物轉移和棄置的國際協議。"},{"en":"Governments refer to the Basel Convention when discussing cross-border waste trade.","zh":"政府討論跨境廢物貿易時，會提及《巴塞爾公約》。"},{"en":"The Basel Convention aims to stop rich countries from simply dumping dangerous waste elsewhere.","zh":"《巴塞爾公約》旨在阻止富裕國家只是把危險廢物傾倒到其他地方。"},{"en":"In this passage, it represents an international response to e-waste risks.","zh":"在這篇文章中，它代表國際社會對電子廢物風險的回應。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":13},{"front":"transboundary movements","meaning":"跨境轉移","examples":[{"en":"The convention controls transboundary movements of hazardous wastes.","zh":"該公約管制有害廢物的跨境轉移。"},{"en":"Transboundary movements are movements across national borders.","zh":"transboundary movements 是跨越國界的移動。"},{"en":"Shipping waste from one country to another is a transboundary movement.","zh":"把廢物從一個國家運到另一個國家，就是跨境轉移。"},{"en":"Transboundary movements of hazardous waste need rules because pollution risks can be shifted abroad.","zh":"有害廢物的跨境轉移需要規則，因為污染風險可以被轉移到海外。"},{"en":"This phrase is formal and often appears in environmental law.","zh":"這個短語較正式，常出現在環境法中。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":13},{"front":"hazardous wastes","meaning":"有害廢物","examples":[{"en":"The Basel Convention deals with hazardous wastes and their disposal.","zh":"《巴塞爾公約》處理有害廢物及其棄置問題。"},{"en":"Hazardous wastes are wastes that can harm people, animals, plants, or the environment.","zh":"hazardous wastes 是可以傷害人、動物、植物或環境的廢物。"},{"en":"Chemical waste, medical waste, and some e-waste are hazardous wastes.","zh":"化學廢物、醫療廢物和部分電子廢物都是有害廢物。"},{"en":"Hazardous wastes require special treatment because ordinary disposal may be dangerous.","zh":"有害廢物需要特別處理，因為普通棄置可能危險。"},{"en":"Clear labelling and tracking help prevent hazardous wastes from being handled carelessly.","zh":"清楚標籤和追蹤有助防止有害廢物被粗心處理。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":13},{"front":"industrialised nations","meaning":"工業化國家","examples":[{"en":"The convention aimed to stop industrialised nations from dumping waste abroad.","zh":"該公約旨在阻止工業化國家把廢物傾倒到海外。"},{"en":"Industrialised nations are countries with developed industries, advanced infrastructure, and strong manufacturing or technology sectors.","zh":"industrialised nations 指擁有發達工業、先進基建和強大製造或科技部門的國家。"},{"en":"Industrialised nations often consume more electronic goods than poorer countries.","zh":"工業化國家通常比較貧困國家消耗更多電子產品。"},{"en":"Because industrialised nations generate much e-waste, they carry major responsibility for disposal.","zh":"由於工業化國家產生大量電子廢物，它們對棄置負有重大責任。"},{"en":"The phrase often contrasts wealthy developed countries with less-developed ones.","zh":"這個短語常把富裕發達國家與較不發達國家作對比。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":13},{"front":"the OECD","meaning":"經合組織","examples":[{"en":"The OECD includes many industrialised nations.","zh":"經合組織包括許多工業化國家。"},{"en":"The OECD is an organisation of mainly developed countries that discuss economic and social policy.","zh":"the OECD 是主要由發達國家組成，討論經濟和社會政策的組織。"},{"en":"Reports from the OECD may compare education, health, labour, and environmental policies.","zh":"經合組織的報告可能比較教育、健康、勞工和環境政策。"},{"en":"If OECD countries produce much e-waste, their policies can strongly affect global waste flows.","zh":"如果經合組織國家產生大量電子廢物，其政策可以強烈影響全球廢物流向。"},{"en":"In reading passages, the OECD often signals a group of wealthy industrialised countries.","zh":"在閱讀文章中，OECD 通常表示一組富裕工業化國家。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":13},{"front":"dump their waste in","meaning":"把廢物傾倒在……","examples":[{"en":"The convention tried to stop wealthy nations from dumping their waste in poorer countries.","zh":"該公約試圖阻止富裕國家把廢物傾倒在較貧困國家。"},{"en":"To dump their waste in a place means to leave or dispose of waste there, often carelessly or unfairly.","zh":"dump their waste in 某地，意思是把廢物留在或棄置在某地，通常帶有粗心或不公平意味。"},{"en":"A factory should not dump its waste in a river to save money.","zh":"工廠不應為了省錢把廢物傾倒在河流中。"},{"en":"Wealthy countries dumping waste in poorer countries can create environmental injustice.","zh":"富裕國家把廢物傾倒在較貧困國家，可以造成環境不公。"},{"en":"This phrase often carries a negative meaning because the action is irresponsible.","zh":"這個短語通常帶負面意思，因為行為不負責任。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":13},{"front":"less-developed countries","meaning":"較不發達國家","examples":[{"en":"Some e-waste is exported to less-developed countries.","zh":"一些電子廢物被出口到較不發達國家。"},{"en":"Less-developed countries are countries with lower income, weaker infrastructure, or fewer industrial resources.","zh":"less-developed countries 指收入較低、基建較弱或工業資源較少的國家。"},{"en":"Less-developed countries may lack safe recycling systems for imported e-waste.","zh":"較不發達國家可能缺乏安全處理進口電子廢物的回收系統。"},{"en":"Sending hazardous waste to less-developed countries can increase health risks for vulnerable workers.","zh":"把有害廢物送到較不發達國家，可以增加弱勢工人的健康風險。"},{"en":"This phrase is often used in development and global inequality discussions.","zh":"這個短語常用於發展和全球不平等討論。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":13},{"front":"take the lead on","meaning":"在……方面帶頭","examples":[{"en":"Europe has taken the lead on e-waste management.","zh":"歐洲在電子廢物管理方面帶頭。"},{"en":"To take the lead on something means to act first or guide others in dealing with an issue.","zh":"take the lead on something 意思是在處理某議題時率先行動或引導他人。"},{"en":"A school may take the lead on recycling by placing collection boxes in every classroom.","zh":"學校可以透過在每個課室放置回收箱，在回收方面帶頭。"},{"en":"If one region takes the lead on waste laws, other governments may follow later.","zh":"如果一個地區在廢物法律方面帶頭，其他政府之後可能跟隨。"},{"en":"This phrase suggests leadership, initiative, and responsibility.","zh":"這個短語暗示領導、主動性和責任。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":13},{"front":"e-waste management","meaning":"電子廢物管理","examples":[{"en":"Europe has introduced laws on e-waste management.","zh":"歐洲已推出關於電子廢物管理的法律。"},{"en":"E-waste management means the collection, treatment, recycling, disposal, and regulation of electronic waste.","zh":"e-waste management 指電子廢物的收集、處理、回收、棄置和規管。"},{"en":"Good e-waste management includes safe drop-off points and clear public instructions.","zh":"良好的電子廢物管理包括安全回收點和清楚的公眾指示。"},{"en":"Poor e-waste management can expose workers to toxic materials and pollute soil.","zh":"差劣電子廢物管理可以令工人接觸有毒物料，並污染泥土。"},{"en":"Effective management requires cooperation between consumers, producers, recyclers, and governments.","zh":"有效管理需要消費者、生產商、回收商和政府合作。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":13},{"front":"require governments to","meaning":"要求政府去","examples":[{"en":"The EU requires governments to implement laws on electronic waste.","zh":"歐盟要求政府實施關於電子廢物的法律。"},{"en":"To require governments to do something means to officially demand that governments take that action.","zh":"require governments to do something 意思是正式要求政府採取該行動。"},{"en":"International agreements may require governments to report pollution levels.","zh":"國際協議可能要求政府報告污染水平。"},{"en":"If laws require governments to collect e-waste, public systems must be created.","zh":"如果法律要求政府收集電子廢物，就必須建立公共系統。"},{"en":"This phrase shows that responsibility is placed on authorities.","zh":"這個短語顯示責任落在當局身上。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":13},{"front":"implement laws","meaning":"實施法律","examples":[{"en":"Governments must implement laws controlling the disposal of electrical products.","zh":"政府必須實施控制電器產品棄置的法律。"},{"en":"To implement laws means to put laws into practice so they actually operate.","zh":"implement laws 意思是把法律付諸實行，使其真正運作。"},{"en":"A government may pass a law first and implement it later through rules and inspections.","zh":"政府可能先通過法律，再透過規則和檢查實施它。"},{"en":"If laws are not implemented, companies may continue unsafe disposal.","zh":"如果法律沒有被實施，公司可能繼續不安全棄置。"},{"en":"Implementation matters because written rules alone do not change behaviour.","zh":"實施很重要，因為只有書面規則不會改變行為。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":14},{"front":"controlling the production and disposal of","meaning":"規管……的生產及棄置","examples":[{"en":"European laws control the production and disposal of electrical products.","zh":"歐洲法律規管電器產品的生產及棄置。"},{"en":"Controlling the production and disposal of something means regulating both how it is made and how it is thrown away.","zh":"controlling the production and disposal of something 意思是規管某物如何被製造以及如何被丟棄。"},{"en":"Laws controlling the production and disposal of plastic bags can reduce waste.","zh":"規管膠袋生產及棄置的法律可以減少廢物。"},{"en":"If governments control both production and disposal, companies must consider the full product life cycle.","zh":"如果政府同時規管生產和棄置，公司就必須考慮完整產品生命周期。"},{"en":"This phrase shows that regulation covers the beginning and end of a product’s life.","zh":"這個短語顯示規管涵蓋產品生命的開始和結束。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":14},{"front":"electrical products","meaning":"電器產品","examples":[{"en":"The laws apply to many electrical products.","zh":"這些法律適用於許多電器產品。"},{"en":"Electrical products are products that use electricity to work.","zh":"electrical products 是使用電力運作的產品。"},{"en":"Washing machines, lamps, computers, and televisions are electrical products.","zh":"洗衣機、燈、電腦和電視都是電器產品。"},{"en":"Electrical products become waste when they break, become outdated, or are replaced.","zh":"電器產品損壞、過時或被替換時會變成廢物。"},{"en":"Because many electrical products contain complex materials, disposal rules are needed.","zh":"因為許多電器產品含有複雜物料，所以需要棄置規則。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":14},{"front":"draft legislation","meaning":"草擬法例","examples":[{"en":"The European Union has drafted legislation on electronic waste.","zh":"歐盟已草擬關於電子廢物的法例。"},{"en":"To draft legislation means to prepare the written form of a proposed law.","zh":"draft legislation 意思是準備擬議法律的書面版本。"},{"en":"A government may draft legislation before discussing it in parliament.","zh":"政府可能在議會討論前草擬法例。"},{"en":"Draft legislation on e-waste can set out who pays for collection and recycling.","zh":"關於電子廢物的草擬法例可以列明誰支付收集和回收費用。"},{"en":"A draft is not always final; it may change before becoming law.","zh":"草案不一定是最終版本；它在成為法律前可能改變。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":14},{"front":"Waste from Electrical and Electronic Equipment","meaning":"電器及電子設備廢物","examples":[{"en":"The WEEE Directive deals with waste from electrical and electronic equipment.","zh":"《WEEE 指令》處理電器及電子設備廢物。"},{"en":"Waste from Electrical and Electronic Equipment means discarded items that use electricity or electronic components.","zh":"Waste from Electrical and Electronic Equipment 指被丟棄的電器或含電子部件的設備。"},{"en":"Old fridges, computers, printers, and phones are examples of waste from electrical and electronic equipment.","zh":"舊雪櫃、電腦、打印機和手機都是電器及電子設備廢物的例子。"},{"en":"This waste needs special handling because it can contain metals, plastics, and toxic substances.","zh":"這類廢物需要特別處理，因為它可以含有金屬、塑膠和有毒物質。"},{"en":"The phrase is often shortened to WEEE in European law.","zh":"這個短語在歐洲法律中常縮寫為 WEEE。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":14},{"front":"the WEEE Directive","meaning":"《電器及電子設備廢物指令》","examples":[{"en":"The WEEE Directive is European legislation on electronic waste.","zh":"《電器及電子設備廢物指令》是歐洲關於電子廢物的法例。"},{"en":"The WEEE Directive is a European law that sets rules for collecting, recycling, and disposing of electrical and electronic waste.","zh":"the WEEE Directive 是歐洲法律，為收集、回收和棄置電器及電子廢物訂立規則。"},{"en":"The WEEE Directive affects manufacturers, governments, recyclers, and consumers.","zh":"《電器及電子設備廢物指令》影響製造商、政府、回收商和消費者。"},{"en":"By requiring recycling targets, the WEEE Directive aims to reduce waste sent to landfills.","zh":"透過要求回收目標，《WEEE 指令》旨在減少送往堆填區的廢物。"},{"en":"In this passage, it is used as an example of Europe’s legal response.","zh":"在這篇文章中，它被用作歐洲法律回應的例子。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":14},{"front":"be based on","meaning":"基於","examples":[{"en":"The legislation is based on Extended Producer Responsibility.","zh":"這項法例基於生產者延伸責任。"},{"en":"To be based on something means to be built from, supported by, or guided by it.","zh":"be based on something 意思是以某事為基礎、支撐或指引。"},{"en":"A school rule should be based on safety and fairness.","zh":"校規應基於安全和公平。"},{"en":"If a policy is based on producer responsibility, companies must consider waste after sale.","zh":"如果政策基於生產者責任，公司就必須考慮銷售後的廢物。"},{"en":"This phrase shows the principle behind a system or decision.","zh":"這個短語顯示制度或決定背後的原則。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":14},{"front":"a concept known as","meaning":"一個稱為……的概念","examples":[{"en":"The law is based on a concept known as Extended Producer Responsibility.","zh":"這項法律基於一個稱為生產者延伸責任的概念。"},{"en":"A concept known as something is an idea with a particular name.","zh":"a concept known as something 指一個有特定名稱的概念。"},{"en":"Some schools use a concept known as peer learning, where students help one another.","zh":"有些學校使用一個稱為朋輩學習的概念，讓學生互相幫助。"},{"en":"Naming a concept helps readers understand and remember the policy idea.","zh":"為概念命名有助讀者理解和記住政策想法。"},{"en":"This phrase is useful when introducing a technical term.","zh":"這個短語適合用來介紹專門術語。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":14},{"front":"Extended Producer Responsibility","meaning":"生產者延伸責任","examples":[{"en":"Extended Producer Responsibility makes producers responsible for their products.","zh":"生產者延伸責任令生產商對其產品負責。"},{"en":"Extended Producer Responsibility is a policy idea that makes manufacturers responsible for products even after consumers finish using them.","zh":"Extended Producer Responsibility 是一種政策概念，要求製造商在消費者用完產品後仍對產品負責。"},{"en":"Under Extended Producer Responsibility, a company may have to pay for collection and recycling.","zh":"在生產者延伸責任下，公司可能必須支付收集和回收費用。"},{"en":"EPR encourages producers to design products that create less waste.","zh":"生產者延伸責任鼓勵生產商設計產生較少廢物的產品。"},{"en":"The idea shifts responsibility from consumers alone to the companies that make the products.","zh":"這個概念把責任從單靠消費者，轉移到製造產品的公司身上。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":14},{"front":"essentially","meaning":"基本上","examples":[{"en":"Essentially, EPR places responsibility on producers.","zh":"基本上，生產者延伸責任把責任放在生產商身上。"},{"en":"Essentially means basically or in the most important sense.","zh":"essentially 意思是基本上，或從最重要意義上說。"},{"en":"Essentially, a library is a place where people can access knowledge.","zh":"基本上，圖書館是一個讓人取得知識的地方。"},{"en":"Essentially, e-waste laws try to make disposal safer and more responsible.","zh":"基本上，電子廢物法律試圖令棄置更安全和更負責任。"},{"en":"Use essentially when simplifying a complex idea to its core meaning.","zh":"當把複雜想法簡化到核心意思時，可以使用 essentially。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":14},{"front":"place responsibility on","meaning":"把責任放在……身上","examples":[{"en":"EPR places responsibility on the producers of electronic products.","zh":"生產者延伸責任把責任放在電子產品生產商身上。"},{"en":"To place responsibility on someone means to make them accountable for dealing with a problem or duty.","zh":"place responsibility on someone 意思是要求某人為處理問題或責任負責。"},{"en":"A school may place responsibility on students to return borrowed books on time.","zh":"學校可能把準時歸還借書的責任放在學生身上。"},{"en":"Placing responsibility on producers can encourage better product design.","zh":"把責任放在生產商身上，可以鼓勵更好的產品設計。"},{"en":"This phrase shows who is expected to act or pay.","zh":"這個短語顯示誰被期望行動或付款。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":14},{"front":"squarely on the shoulders of","meaning":"完全落在……肩上","examples":[{"en":"EPR places responsibility squarely on the shoulders of producers.","zh":"生產者延伸責任把責任完全放在生產商肩上。"},{"en":"Squarely on the shoulders of someone means clearly and directly making that person or group responsible.","zh":"squarely on the shoulders of someone 意思是清楚而直接地讓某人或某群體負責。"},{"en":"The safety of a school trip rests squarely on the shoulders of the organiser.","zh":"學校旅行的安全完全落在組織者肩上。"},{"en":"Putting recycling costs squarely on the shoulders of producers can change how products are designed.","zh":"把回收成本完全放在生產商肩上，可以改變產品設計方式。"},{"en":"This phrase is vivid and emphasises direct responsibility.","zh":"這個短語形象化地強調直接責任。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":15},{"front":"producers of electronic products","meaning":"電子產品生產商","examples":[{"en":"Producers of electronic products must consider their environmental impact.","zh":"電子產品生產商必須考慮其環境影響。"},{"en":"Producers of electronic products are companies or manufacturers that make devices such as phones, computers, and appliances.","zh":"producers of electronic products 是製造手機、電腦和電器等裝置的公司或製造商。"},{"en":"Producers of electronic products may choose materials, packaging, and repair policies.","zh":"電子產品生產商可以選擇材料、包裝和維修政策。"},{"en":"If producers design products that are hard to repair, waste may increase.","zh":"如果生產商設計出難以維修的產品，廢物可能增加。"},{"en":"These producers can reduce e-waste by making products last longer.","zh":"這些生產商可以透過製造更耐用的產品來減少電子廢物。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":15},{"front":"consider carefully","meaning":"仔細考慮","examples":[{"en":"Producers must consider carefully the environmental impact of their products.","zh":"生產商必須仔細考慮其產品的環境影響。"},{"en":"To consider carefully means to think seriously and in detail before deciding or acting.","zh":"consider carefully 意思是在決定或行動前認真而詳細地思考。"},{"en":"Students should consider carefully which subjects match their interests and future plans.","zh":"學生應仔細考慮哪些科目符合自己的興趣和未來計劃。"},{"en":"If producers consider disposal carefully, they may choose safer materials.","zh":"如果生產商仔細考慮棄置問題，可能會選擇更安全材料。"},{"en":"Careful consideration helps prevent problems that appear later.","zh":"仔細考慮有助防止日後出現問題。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":15},{"front":"environmental impact","meaning":"環境影響","examples":[{"en":"Manufacturers must consider the environmental impact of the products they sell.","zh":"製造商必須考慮他們所售產品的環境影響。"},{"en":"Environmental impact means the effect something has on nature, pollution, resources, and living things.","zh":"environmental impact 指某事對自然、污染、資源和生物造成的影響。"},{"en":"A plastic bottle has an environmental impact from production, transport, use, and disposal.","zh":"膠樽從生產、運輸、使用到棄置都有環境影響。"},{"en":"If a product has a large environmental impact, consumers and governments may demand change.","zh":"如果產品有巨大環境影響，消費者和政府可能要求改變。"},{"en":"Environmental impact should be measured across the whole life of a product.","zh":"環境影響應在產品整個生命周期中衡量。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":15},{"front":"bring to the marketplace","meaning":"推向市場","examples":[{"en":"Producers must think about the products they bring to the marketplace.","zh":"生產商必須思考他們推向市場的產品。"},{"en":"To bring a product to the marketplace means to make it available for customers to buy.","zh":"bring a product to the marketplace 意思是把產品推出讓顧客購買。"},{"en":"A company may test a new device before bringing it to the marketplace.","zh":"公司可能在把新裝置推向市場前進行測試。"},{"en":"When producers bring products to the marketplace, they should also plan for repair and disposal.","zh":"當生產商把產品推向市場時，也應計劃維修和棄置。"},{"en":"This phrase connects product design with commercial release.","zh":"這個短語把產品設計與商業推出連繫起來。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":15},{"front":"the aim of","meaning":"……的目的","examples":[{"en":"The aim of EPR is to encourage producers to reduce pollution.","zh":"生產者延伸責任的目的是鼓勵生產商減少污染。"},{"en":"The aim of something is its purpose or goal.","zh":"the aim of something 指某事的目的或目標。"},{"en":"The aim of a reading lesson may be to help students identify main ideas.","zh":"閱讀課的目的可能是幫助學生找出主旨。"},{"en":"If the aim of a policy is clear, people can judge whether it works.","zh":"如果政策目的清楚，人們就能判斷它是否有效。"},{"en":"This phrase is useful for explaining why a plan exists.","zh":"這個短語適合用來解釋計劃為何存在。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":15},{"front":"encourage producers to","meaning":"鼓勵生產商去","examples":[{"en":"The policy encourages producers to prevent pollution.","zh":"該政策鼓勵生產商防止污染。"},{"en":"To encourage producers to do something means to push or motivate manufacturers to take that action.","zh":"encourage producers to do something 意思是推動或促使製造商採取該行動。"},{"en":"Tax benefits may encourage producers to use cleaner materials.","zh":"稅務優惠可能鼓勵生產商使用更清潔的材料。"},{"en":"Laws can encourage producers to design products that are easier to repair.","zh":"法律可以鼓勵生產商設計更容易維修的產品。"},{"en":"Encouragement may come through rules, costs, rewards, or public pressure.","zh":"鼓勵可以來自規則、成本、獎勵或公眾壓力。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":15},{"front":"prevent pollution","meaning":"防止污染","examples":[{"en":"EPR aims to help prevent pollution.","zh":"生產者延伸責任旨在幫助防止污染。"},{"en":"To prevent pollution means to stop harmful substances from damaging air, water, soil, or ecosystems.","zh":"prevent pollution 意思是阻止有害物質損害空氣、水、泥土或生態系統。"},{"en":"Factories can prevent pollution by treating wastewater before releasing it.","zh":"工廠可以透過排放前處理廢水來防止污染。"},{"en":"Better product design can prevent pollution by reducing toxic materials.","zh":"更好的產品設計可以透過減少有毒材料來防止污染。"},{"en":"Prevention is often cheaper and safer than cleaning up pollution later.","zh":"預防污染通常比日後清理污染更便宜和安全。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":15},{"front":"reduce resource and energy use","meaning":"減少資源及能源使用","examples":[{"en":"The policy aims to reduce resource and energy use.","zh":"該政策旨在減少資源及能源使用。"},{"en":"To reduce resource and energy use means to use fewer materials and less power.","zh":"reduce resource and energy use 意思是使用較少材料和較少能源。"},{"en":"Turning off unused lights can reduce energy use at home.","zh":"關掉不用的燈可以減少家中的能源使用。"},{"en":"Designing lighter products can reduce resource use and lower transport costs.","zh":"設計較輕的產品可以減少資源使用並降低運輸成本。"},{"en":"Reducing resource and energy use helps protect the environment before waste is even created.","zh":"減少資源及能源使用有助在廢物產生前已保護環境。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":15},{"front":"at each stage of","meaning":"在……的每個階段","examples":[{"en":"Producers should reduce pollution at each stage of the product life cycle.","zh":"生產商應在產品生命周期的每個階段減少污染。"},{"en":"At each stage of something means during every step or part of a process.","zh":"at each stage of something 意思是在某個過程的每一步或每一部分。"},{"en":"Students need feedback at each stage of writing: planning, drafting, and editing.","zh":"學生在寫作的每個階段都需要回饋：規劃、起草和修改。"},{"en":"If pollution is reduced at each stage of production, the final product becomes less harmful.","zh":"如果在生產的每個階段都減少污染，最終產品就較少有害。"},{"en":"This phrase reminds us to look at the whole process, not only the end.","zh":"這個短語提醒我們看整個過程，而不只是結尾。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":15},{"front":"the product life cycle","meaning":"產品生命周期","examples":[{"en":"Environmental impact should be considered throughout the product life cycle.","zh":"環境影響應在整個產品生命周期中被考慮。"},{"en":"The product life cycle is the full journey of a product from design and production to use and disposal.","zh":"product life cycle 是產品從設計、生產到使用和棄置的完整旅程。"},{"en":"A phone’s product life cycle includes mining materials, manufacturing, shipping, use, repair, and recycling.","zh":"手機的產品生命周期包括開採材料、製造、運輸、使用、維修和回收。"},{"en":"Looking at the product life cycle shows where waste and pollution are created.","zh":"觀察產品生命周期可以顯示廢物和污染在哪裡產生。"},{"en":"Good design considers the product life cycle before the product reaches customers.","zh":"良好設計會在產品到達顧客前考慮其產品生命周期。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":15},{"front":"European leadership","meaning":"歐洲的領導作用","examples":[{"en":"European leadership has been necessary because e-waste is growing rapidly.","zh":"由於電子廢物快速增長，歐洲的領導作用一直是必要的。"},{"en":"European leadership means Europe taking a leading role in making rules or setting examples.","zh":"European leadership 指歐洲在制定規則或樹立榜樣方面帶頭。"},{"en":"European leadership on recycling can encourage other regions to adopt similar systems.","zh":"歐洲在回收方面的領導作用可以鼓勵其他地區採用類似制度。"},{"en":"When a problem grows quickly, leadership may be needed to push coordinated action.","zh":"當問題快速增長時，可能需要領導作用推動協調行動。"},{"en":"This phrase presents Europe as an early or important actor in policy.","zh":"這個短語把歐洲呈現為政策上的早期或重要行動者。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":16},{"front":"municipal waste stream","meaning":"市政廢物流","examples":[{"en":"WEEE is growing faster than any other municipal waste stream.","zh":"電器及電子設備廢物比任何其他市政廢物流增長得更快。"},{"en":"A municipal waste stream is the flow or category of waste collected and managed by local authorities.","zh":"municipal waste stream 是由地方政府收集和管理的廢物流向或類別。"},{"en":"Food scraps, packaging, and household rubbish are parts of municipal waste streams.","zh":"廚餘、包裝和家居垃圾都是市政廢物流的一部分。"},{"en":"If one waste stream grows quickly, cities need new collection and treatment systems.","zh":"如果某一廢物流快速增長，城市需要新的收集和處理系統。"},{"en":"This phrase is formal and common in environmental policy.","zh":"這個短語較正式，常見於環境政策中。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":16},{"front":"three times faster than","meaning":"比……快三倍","examples":[{"en":"WEEE is growing about three times faster than other municipal waste streams.","zh":"電器及電子設備廢物的增長速度約比其他市政廢物流快三倍。"},{"en":"Three times faster than means the speed of growth or movement is about three times as high as another comparison point.","zh":"three times faster than 意思是增長或移動速度大約是另一比較對象的三倍。"},{"en":"A child may read three times faster than before after months of practice.","zh":"經過數月練習後，孩子的閱讀速度可能比以前快三倍。"},{"en":"If e-waste grows three times faster than other waste, ordinary systems may not cope.","zh":"如果電子廢物比其他廢物快三倍增長，普通系統可能應付不了。"},{"en":"This phrase is useful for showing a strong difference in speed.","zh":"這個短語適合用來顯示速度上的強烈差異。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":16},{"front":"phase out","meaning":"逐步淘汰","examples":[{"en":"WEEE legislation will phase out toxic substances in electronic goods.","zh":"電器及電子設備廢物法例會逐步淘汰電子產品中的有毒物質。"},{"en":"To phase out something means to gradually stop using or allowing it over time.","zh":"phase out something 意思是隨時間逐漸停止使用或允許某物。"},{"en":"Schools may phase out old textbooks as new editions arrive.","zh":"當新版本到達時，學校可能逐步淘汰舊課本。"},{"en":"Governments may phase out toxic materials so companies have time to change production.","zh":"政府可能逐步淘汰有毒材料，讓公司有時間改變生產。"},{"en":"Phasing out is gradual, not immediate.","zh":"phase out 是逐步的，不是立即的。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":16},{"front":"toxic substances","meaning":"有毒物質","examples":[{"en":"Mercury, cadmium and lead are toxic substances.","zh":"水銀、鎘和鉛都是有毒物質。"},{"en":"Toxic substances are materials that can poison or harm people, animals, plants, or ecosystems.","zh":"toxic substances 是可以毒害或傷害人、動物、植物或生態系統的物料。"},{"en":"A bottle of cleaning fluid may contain toxic substances and need warning labels.","zh":"一瓶清潔液可能含有有毒物質，並需要警告標籤。"},{"en":"Toxic substances in electronics can become dangerous during burning or careless dumping.","zh":"電子產品中的有毒物質在焚燒或粗心傾倒時可能變得危險。"},{"en":"Laws often restrict toxic substances to reduce health and environmental harm.","zh":"法律常限制有毒物質，以減少健康和環境傷害。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":16},{"front":"electronic and electrical goods","meaning":"電子及電器產品","examples":[{"en":"The law limits toxic substances in electronic and electrical goods.","zh":"法律限制電子及電器產品中的有毒物質。"},{"en":"Electronic and electrical goods are products that use circuits, electricity, or both.","zh":"electronic and electrical goods 是使用電路、電力或兩者的產品。"},{"en":"Phones, computers, lamps, and kitchen appliances are electronic and electrical goods.","zh":"手機、電腦、燈和廚房電器都是電子及電器產品。"},{"en":"Electronic and electrical goods can create complex waste because they contain many materials.","zh":"電子及電器產品含有許多物料，所以可以造成複雜廢物。"},{"en":"Regulations often group these goods together because they share similar disposal problems.","zh":"規例常把這些產品歸在一起，因為它們有相似棄置問題。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":16},{"front":"financially responsible for","meaning":"在財政上負責","examples":[{"en":"Producers will be financially responsible for collection, recycling and disposal.","zh":"生產商將在財政上負責收集、回收及棄置。"},{"en":"To be financially responsible for something means to have to pay for it.","zh":"financially responsible for something 意思是必須支付某事的費用。"},{"en":"A tenant may be financially responsible for repairs if they damage the flat.","zh":"如果租客損壞單位，可能要在財政上負責維修。"},{"en":"If producers are financially responsible for e-waste, they may design products that are cheaper to recycle.","zh":"如果生產商在財政上負責電子廢物，他們可能設計較便宜回收的產品。"},{"en":"This phrase focuses on who carries the cost.","zh":"這個短語集中於誰承擔成本。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":16},{"front":"collection, recycling and disposal","meaning":"收集、回收及棄置","examples":[{"en":"Manufacturers must pay for the collection, recycling and disposal of their products.","zh":"製造商必須支付其產品的收集、回收及棄置費用。"},{"en":"Collection, recycling and disposal are the steps of gathering waste, recovering useful materials, and safely getting rid of what remains.","zh":"collection, recycling and disposal 是收集廢物、回收有用物料，以及安全處理剩餘部分的步驟。"},{"en":"A city needs trucks, centres, and workers for collection, recycling and disposal.","zh":"城市需要貨車、中心和工人來進行收集、回收及棄置。"},{"en":"If collection fails, recycling and disposal cannot happen properly.","zh":"如果收集失敗，回收及棄置就不能妥善進行。"},{"en":"These three steps show that waste management is a full system, not one action.","zh":"這三個步驟顯示廢物管理是一套完整系統，而不是單一行動。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":16},{"front":"stipulate that","meaning":"規定","examples":[{"en":"The legislation stipulates that certain toxic products must not be incinerated.","zh":"該法例規定某些有毒產品不得被焚化。"},{"en":"To stipulate that something must happen means to state it clearly as a rule or requirement.","zh":"stipulate that something must happen 意思是清楚列明某事作為規則或要求。"},{"en":"A rental contract may stipulate that tenants cannot keep pets.","zh":"租約可能規定租客不能養寵物。"},{"en":"If a law stipulates that toxic products cannot be burned, companies must use safer methods.","zh":"如果法律規定有毒產品不能被焚燒，公司必須使用更安全方法。"},{"en":"This phrase is formal and common in legal or official writing.","zh":"這個短語較正式，常見於法律或官方寫作。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":16},{"front":"products containing","meaning":"含有……的產品","examples":[{"en":"Products containing lead, mercury or cadmium must not be burned.","zh":"含有鉛、水銀或鎘的產品不得被焚燒。"},{"en":"Products containing something are products that have that material or substance inside them.","zh":"products containing something 指內部含有某材料或物質的產品。"},{"en":"Food products containing nuts should have clear labels for people with allergies.","zh":"含有堅果的食品應有清楚標籤，供過敏人士查看。"},{"en":"Products containing toxic metals require special disposal rules.","zh":"含有有毒金屬的產品需要特別棄置規則。"},{"en":"This phrase helps identify which items are affected by a rule.","zh":"這個短語有助指出哪些物品受規則影響。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":16},{"front":"must not be incinerated","meaning":"不得被焚化","examples":[{"en":"Products containing toxic substances must not be incinerated.","zh":"含有有毒物質的產品不得被焚化。"},{"en":"Must not be incinerated means must not be burned in a waste-burning facility.","zh":"must not be incinerated 意思是不得在焚化設施中被焚燒。"},{"en":"Some medical items must not be incinerated if burning them releases dangerous gases.","zh":"如果某些醫療物品焚燒後會釋放危險氣體，就不得被焚化。"},{"en":"If mercury-containing products are incinerated, toxic substances may enter the air.","zh":"如果含水銀產品被焚化，有毒物質可能進入空氣。"},{"en":"This phrase states a strict prohibition, not a suggestion.","zh":"這個短語表示嚴格禁止，而不是建議。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":16},{"front":"integrate recycled material into","meaning":"把回收物料加入……","examples":[{"en":"Producers are encouraged to integrate recycled material into new products.","zh":"生產商被鼓勵把回收物料加入新產品中。"},{"en":"To integrate recycled material into a product means to include reused material as part of making it.","zh":"integrate recycled material into a product 意思是在製造產品時把再用物料包括其中。"},{"en":"A notebook company may integrate recycled paper into its new products.","zh":"筆記本公司可能把回收紙加入新產品中。"},{"en":"Integrating recycled material into electronics can reduce demand for newly mined resources.","zh":"把回收物料加入電子產品可以減少對新開採資源的需求。"},{"en":"This phrase shows how recycling can become part of production, not just disposal.","zh":"這個短語顯示回收可以成為生產的一部分，而不只是棄置的一部分。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":17},{"front":"an increasing quantity of","meaning":"越來越多的……","examples":[{"en":"Manufacturers should use an increasing quantity of recycled material.","zh":"製造商應使用越來越多的回收物料。"},{"en":"An increasing quantity of something means a growing amount of it over time.","zh":"an increasing quantity of something 指某物的數量隨時間增加。"},{"en":"A school may use an increasing quantity of digital materials as students move online.","zh":"隨著學生轉向網上學習，學校可能使用越來越多的數碼材料。"},{"en":"Using an increasing quantity of recycled material can reduce pressure on natural resources.","zh":"使用越來越多的回收物料可以減少自然資源壓力。"},{"en":"This phrase describes gradual growth in amount.","zh":"這個短語描述數量逐步增長。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":17},{"front":"recycled material","meaning":"回收物料","examples":[{"en":"New products should contain more recycled material.","zh":"新產品應含有更多回收物料。"},{"en":"Recycled material is material recovered from waste and used again to make something new.","zh":"recycled material 是從廢物中回收並再次用來製造新東西的材料。"},{"en":"A bag may be made from recycled material such as old plastic bottles.","zh":"袋子可能由舊膠樽等回收物料製成。"},{"en":"Using recycled material can reduce waste and lower demand for new raw materials.","zh":"使用回收物料可以減少廢物，並降低對新原材料的需求。"},{"en":"Recycled material still needs quality control before it is used in new products.","zh":"回收物料在用於新產品前仍需要品質控制。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":17},{"front":"by weight","meaning":"按重量計","examples":[{"en":"Between 70 per cent and 90 per cent by weight of collected equipment must be recycled or reused.","zh":"收集到的設備按重量計有70%至90%必須被回收或再用。"},{"en":"By weight means measured according to how heavy something is, not by number or size.","zh":"by weight 意思是按照重量衡量，而不是按數量或大小。"},{"en":"A recycling target may require 80 per cent by weight of glass bottles to be recovered.","zh":"回收目標可能要求按重量計回收80%的玻璃樽。"},{"en":"Measuring by weight can make large heavy items count more than small light ones.","zh":"按重量計算會令大型重物比細小輕物佔更大比重。"},{"en":"This phrase is common in recycling rules and product standards.","zh":"這個短語常見於回收規則和產品標準中。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":17},{"front":"collected equipment","meaning":"收集到的設備","examples":[{"en":"Most collected equipment must be recycled or reused.","zh":"大部分收集到的設備必須被回收或再用。"},{"en":"Collected equipment refers to devices or machines that have been gathered for recycling, repair, or disposal.","zh":"collected equipment 指為回收、維修或棄置而被收集起來的裝置或機器。"},{"en":"A school may store collected equipment in a room before a recycling company arrives.","zh":"學校可能在回收公司到達前，把收集到的設備存放在房間。"},{"en":"If collected equipment is not sorted properly, useful parts may be wasted.","zh":"如果收集到的設備沒有妥善分類，有用零件可能被浪費。"},{"en":"Collection is only the first step; the equipment still needs proper treatment.","zh":"收集只是第一步；設備仍需要妥善處理。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":17},{"front":"be recycled or reused","meaning":"被回收或再用","examples":[{"en":"A large proportion of collected equipment must be recycled or reused.","zh":"大比例收集到的設備必須被回收或再用。"},{"en":"To be recycled or reused means to be processed into materials again or used again in its existing form.","zh":"be recycled or reused 意思是被重新處理成材料，或以現有形式再次使用。"},{"en":"A working old laptop can be reused, while a broken one may be recycled for parts.","zh":"一部仍能運作的舊手提電腦可以被再用，而壞掉的可能被拆件回收。"},{"en":"If more equipment is recycled or reused, less waste goes to landfills.","zh":"如果更多設備被回收或再用，送往堆填區的廢物就會減少。"},{"en":"Reuse usually keeps the product whole, while recycling breaks it down into materials.","zh":"再用通常保留產品完整，而回收則把它分解成材料。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":17},{"front":"go a long way toward","meaning":"大大有助於","examples":[{"en":"These directives will go a long way toward improving the e-waste problem.","zh":"這些指令將大大有助於改善電子廢物問題。"},{"en":"To go a long way toward something means to help greatly in achieving it, though not necessarily solve it completely.","zh":"go a long way toward something 意思是大大有助於達成某事，但不一定完全解決。"},{"en":"Clear instructions can go a long way toward reducing mistakes in an exam.","zh":"清楚指示可以大大有助於減少考試錯誤。"},{"en":"Producer responsibility can go a long way toward making electronics easier to recycle.","zh":"生產者責任可以大大有助於令電子產品更容易回收。"},{"en":"This phrase suggests strong progress, not a perfect solution.","zh":"這個短語暗示有很大進展，但不是完美解決方案。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":17},{"front":"improve the e-waste problem","meaning":"改善電子廢物問題","examples":[{"en":"European directives may improve the e-waste problem.","zh":"歐洲指令可能改善電子廢物問題。"},{"en":"To improve the e-waste problem means to make the problem of electronic waste less serious.","zh":"improve the e-waste problem 意思是令電子廢物問題變得較不嚴重。"},{"en":"Repair services can improve the e-waste problem by helping people use devices longer.","zh":"維修服務可以透過幫助人們延長裝置使用期來改善電子廢物問題。"},{"en":"Laws improve the e-waste problem when they reduce unsafe dumping and increase recycling.","zh":"當法律減少不安全傾倒並增加回收時，就能改善電子廢物問題。"},{"en":"The problem is improved by prevention, collection, recycling, and producer responsibility together.","zh":"預防、收集、回收和生產者責任結合起來，才能改善這個問題。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":17},{"front":"seriously consider","meaning":"認真考慮","examples":[{"en":"Other governments should seriously consider implementing similar legislation.","zh":"其他政府應認真考慮實施類似法例。"},{"en":"To seriously consider something means to think about it carefully and treat it as a real possibility.","zh":"seriously consider something 意思是仔細思考某事，並把它視為真正可能的選項。"},{"en":"A student should seriously consider asking for help if they keep failing practice tests.","zh":"如果學生一直練習測驗不合格，就應認真考慮尋求幫助。"},{"en":"Governments may seriously consider new waste laws when pollution becomes visible.","zh":"當污染變得可見時，政府可能認真考慮新的廢物法律。"},{"en":"This phrase suggests the idea deserves real attention, not a quick dismissal.","zh":"這個短語暗示該想法值得真正關注，而不應快速否定。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":17},{"front":"implement legislation","meaning":"實施法例","examples":[{"en":"Governments can implement legislation to control e-waste.","zh":"政府可以實施法例來管制電子廢物。"},{"en":"To implement legislation means to put laws into actual operation.","zh":"implement legislation 意思是把法律實際執行。"},{"en":"A city may implement legislation by setting deadlines, inspections, and penalties.","zh":"城市可以透過設定期限、檢查和罰則來實施法例。"},{"en":"If legislation is implemented well, companies know what they must do.","zh":"如果法例實施得好，公司就知道自己必須做甚麼。"},{"en":"Laws only work when implementation turns words into action.","zh":"只有當實施把文字變成行動，法律才會有效。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":17},{"front":"some or all of","meaning":"部分或全部的……","examples":[{"en":"Other governments may adopt some or all of the European legislation.","zh":"其他政府可能採用部分或全部歐洲法例。"},{"en":"Some or all of something means part of it or the whole thing.","zh":"some or all of something 意思是某事物的一部分或全部。"},{"en":"A teacher may ask students to rewrite some or all of an essay depending on the mistakes.","zh":"老師可能根據錯誤要求學生重寫文章的部分或全部。"},{"en":"Governments may copy some or all of another region’s law if it fits local needs.","zh":"如果適合本地需要，政府可能仿效另一地區法律的部分或全部。"},{"en":"This phrase gives flexibility instead of demanding complete adoption.","zh":"這個短語提供彈性，而不是要求完全採用。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":17},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Students must choose the correct heading for each paragraph.","zh":"學生必須為每段選出正確標題。"},{"en":"To choose the correct heading means to select the title that best matches a paragraph’s main idea.","zh":"choose the correct heading 意思是選出最符合段落主旨的標題。"},{"en":"In reading tests, students should read the whole paragraph before choosing the correct heading.","zh":"在閱讀測驗中，學生應先讀完整段，再選出正確標題。"},{"en":"A wrong heading often focuses on one detail instead of the overall message.","zh":"錯誤標題常集中於一個細節，而不是整體信息。"},{"en":"The correct heading usually summarises the paragraph, not just one example.","zh":"正確標題通常概括整段，而不只是其中一個例子。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":18},{"front":"list of headings","meaning":"標題列表","examples":[{"en":"The question provides a list of headings for the paragraphs.","zh":"題目提供了一個段落標題列表。"},{"en":"A list of headings is a set of possible paragraph titles in a reading task.","zh":"list of headings 是閱讀題中一組可能的段落標題。"},{"en":"Students compare the list of headings with paragraph main ideas.","zh":"學生會把標題列表與段落主旨作比較。"},{"en":"A long list of headings can confuse students when several options sound similar.","zh":"當多個選項聽起來相似時，長標題列表可能令學生混亂。"},{"en":"Crossing out used headings can make the task easier.","zh":"劃走已使用的標題可以令任務更容易。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":18},{"front":"write the correct number","meaning":"寫上正確編號","examples":[{"en":"Students write the correct number in the answer box.","zh":"學生在答案框中寫上正確編號。"},{"en":"To write the correct number means to put the number that matches the chosen answer.","zh":"write the correct number 意思是填上與所選答案相配的編號。"},{"en":"In matching questions, students may write the correct number beside each paragraph letter.","zh":"在配對題中，學生可能要在每個段落字母旁寫上正確編號。"},{"en":"Writing the wrong number can lose marks even if the student understands the text.","zh":"即使學生理解文章，寫錯編號也可能失分。"},{"en":"Always check whether the answer should be a number, letter, or word.","zh":"一定要檢查答案應填數字、字母還是單字。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":18},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Answers should be written on the answer sheet.","zh":"答案應寫在答題紙上。"},{"en":"On your answer sheet means in the official place where exam answers must be recorded.","zh":"on your answer sheet 指在考試答案必須被記錄的正式位置上。"},{"en":"In a reading test, writing the answer in the booklet may not count if it is not on your answer sheet.","zh":"在閱讀測驗中，如果答案沒有寫在答題紙上，只寫在題簿中可能不算。"},{"en":"Students lose marks when correct answers are not transferred to the answer sheet.","zh":"如果正確答案沒有轉填到答題紙上，學生會失分。"},{"en":"This phrase reminds students where the final answer must appear.","zh":"這個短語提醒學生最終答案必須出現在哪裡。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":18},{"front":"exporting e-waste","meaning":"出口電子廢物","examples":[{"en":"Exporting e-waste can shift pollution problems to poorer countries.","zh":"出口電子廢物可以把污染問題轉移到較貧困國家。"},{"en":"Exporting e-waste means sending electronic waste to another country for disposal, recycling, or processing.","zh":"exporting e-waste 指把電子廢物送到另一國家棄置、回收或處理。"},{"en":"A company may choose exporting e-waste when local recycling is expensive.","zh":"當本地回收昂貴時，公司可能選擇出口電子廢物。"},{"en":"Exporting e-waste can hide the problem from consumers while harming workers abroad.","zh":"出口電子廢物可以把問題從消費者眼前隱藏，同時傷害海外工人。"},{"en":"This practice needs strict tracking to prevent unsafe dumping.","zh":"這種做法需要嚴格追蹤，以防止不安全傾倒。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":18},{"front":"the hazards of","meaning":"……的危害","examples":[{"en":"The heading refers to the hazards of burning computer junk.","zh":"這個標題指焚燒電腦廢料的危害。"},{"en":"The hazards of something are the dangers or risks connected with it.","zh":"the hazards of something 指與某事相關的危險或風險。"},{"en":"The hazards of cycling without a helmet include head injury after a fall.","zh":"不戴頭盔踩單車的危害包括跌倒後頭部受傷。"},{"en":"The hazards of burning e-waste include toxic smoke and metal pollution.","zh":"焚燒電子廢物的危害包括有毒煙霧和金屬污染。"},{"en":"This phrase is useful when introducing why something is dangerous.","zh":"這個短語適合用來介紹某事為何危險。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":18},{"front":"burning computer junk","meaning":"焚燒電腦廢料","examples":[{"en":"Burning computer junk can release toxic substances.","zh":"焚燒電腦廢料可以釋放有毒物質。"},{"en":"Burning computer junk means setting old or unwanted computer parts on fire to get rid of them or recover materials.","zh":"burning computer junk 指把舊或不需要的電腦零件焚燒，以棄置或回收材料。"},{"en":"Burning computer junk may seem cheap, but it can poison the air.","zh":"焚燒電腦廢料可能看似便宜，但可以污染空氣。"},{"en":"When computer junk burns, plastics and metals may create harmful chemicals.","zh":"當電腦廢料燃燒時，塑膠和金屬可能產生有害化學物質。"},{"en":"Safer recycling is better than burning computer junk carelessly.","zh":"安全回收比粗心焚燒電腦廢料更好。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":18},{"front":"blame developed countries for","meaning":"把……歸咎於發達國家","examples":[{"en":"Some critics blame developed countries for the e-waste problem.","zh":"有些批評者把電子廢物問題歸咎於發達國家。"},{"en":"To blame developed countries for something means to say wealthy industrialised countries are responsible for it.","zh":"blame developed countries for something 意思是說富裕工業化國家應為某事負責。"},{"en":"Activists may blame developed countries for high carbon emissions because they consume more resources.","zh":"活動人士可能把高碳排放歸咎於發達國家，因為它們消耗更多資源。"},{"en":"If developed countries export waste, critics may blame them for pollution abroad.","zh":"如果發達國家出口廢物，批評者可能把海外污染歸咎於它們。"},{"en":"This phrase identifies who is being held responsible.","zh":"這個短語指出誰被追究責任。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":18},{"front":"developed countries","meaning":"發達國家","examples":[{"en":"Developed countries generate much of the world’s hazardous e-waste.","zh":"發達國家產生世界上許多有害電子廢物。"},{"en":"Developed countries are wealthy countries with advanced industries, infrastructure, and public services.","zh":"developed countries 指擁有先進工業、基建和公共服務的富裕國家。"},{"en":"Developed countries often have high levels of consumption and technology use.","zh":"發達國家通常有高消費和高科技使用水平。"},{"en":"Because developed countries buy many electronic products, they may create large amounts of e-waste.","zh":"由於發達國家購買許多電子產品，它們可能產生大量電子廢物。"},{"en":"Development brings responsibility as well as comfort and convenience.","zh":"發展帶來舒適和便利，也帶來責任。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":18},{"front":"not satisfactory","meaning":"不能令人滿意的","examples":[{"en":"The heading suggests that landfills are not satisfactory.","zh":"這個標題暗示堆填區不能令人滿意。"},{"en":"Not satisfactory means not good enough or not acceptable as a solution.","zh":"not satisfactory 意思是不夠好，或作為解決方法不能接受。"},{"en":"A repair is not satisfactory if the phone breaks again the next day.","zh":"如果手機第二天又壞掉，該次維修就不能令人滿意。"},{"en":"Landfills are not satisfactory for e-waste if toxic materials can leak out.","zh":"如果有毒物料會滲出，堆填區用來處理電子廢物就不能令人滿意。"},{"en":"This phrase expresses criticism without using very emotional language.","zh":"這個短語表達批評，但語氣不太情緒化。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":18},{"front":"producers’ legal responsibility","meaning":"生產商的法律責任","examples":[{"en":"The law focuses on producers’ legal responsibility for e-waste.","zh":"法律集中於生產商對電子廢物的法律責任。"},{"en":"Producers’ legal responsibility is the duty that manufacturers must follow under the law.","zh":"producers’ legal responsibility 是製造商在法律下必須履行的責任。"},{"en":"Producers’ legal responsibility may include paying for recycling and safe disposal.","zh":"生產商的法律責任可能包括支付回收和安全棄置費用。"},{"en":"When legal responsibility is clear, companies cannot easily avoid the cost of waste.","zh":"當法律責任清楚時，公司很難逃避廢物成本。"},{"en":"This phrase connects environmental protection with law and business duty.","zh":"這個短語把環境保護與法律和商業責任連繫起來。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":18},{"front":"the dangers of","meaning":"……的危險","examples":[{"en":"The passage discusses the dangers of computer circuit boards.","zh":"文章討論電腦電路板的危險。"},{"en":"The dangers of something are the possible harms or risks it creates.","zh":"the dangers of something 指某事可能造成的傷害或風險。"},{"en":"The dangers of driving too fast include accidents and serious injuries.","zh":"開車太快的危險包括意外和嚴重受傷。"},{"en":"The dangers of circuit boards come from the metals and chemicals they may contain.","zh":"電路板的危險來自它們可能含有的金屬和化學物質。"},{"en":"This phrase helps introduce a risk-focused explanation.","zh":"這個短語有助引入以風險為中心的解釋。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":19},{"front":"dangerous substances found in","meaning":"在……中發現的危險物質","examples":[{"en":"The question refers to dangerous substances found in computers.","zh":"題目指在電腦中發現的危險物質。"},{"en":"Dangerous substances found in something are harmful materials that exist inside it.","zh":"dangerous substances found in something 指存在於某物內的有害物料。"},{"en":"Warning labels tell users about dangerous substances found in cleaning products.","zh":"警告標籤會告訴使用者清潔產品中發現的危險物質。"},{"en":"Dangerous substances found in electronics can create risks during recycling or disposal.","zh":"在電子產品中發現的危險物質，在回收或棄置期間可能造成風險。"},{"en":"This phrase helps students identify where the harmful materials are located.","zh":"這個短語幫助學生辨認有害物料位於哪裡。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":19},{"front":"electronic changes bring waste","meaning":"電子科技變化帶來廢物","examples":[{"en":"Rapid electronic changes bring waste as products become obsolete.","zh":"快速電子科技變化令產品變得過時，從而帶來廢物。"},{"en":"Electronic changes bring waste means new technology creates discarded old devices.","zh":"electronic changes bring waste 意思是新科技造成被丟棄的舊裝置。"},{"en":"When schools replace tablets every few years, electronic changes bring waste.","zh":"當學校每幾年替換平板電腦時，電子科技變化就帶來廢物。"},{"en":"Fast upgrades bring waste because working products may be treated as old too soon.","zh":"快速升級會帶來廢物，因為仍能運作的產品可能太早被視為舊。"},{"en":"This phrase summarises the link between innovation and disposal.","zh":"這個短語概括創新與棄置之間的關係。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":19},{"front":"European e-waste laws","meaning":"歐洲電子廢物法例","examples":[{"en":"The passage discusses European e-waste laws.","zh":"文章討論歐洲電子廢物法例。"},{"en":"European e-waste laws are rules in Europe that control the production, collection, recycling, and disposal of electronic waste.","zh":"European e-waste laws 是歐洲規管電子廢物生產、收集、回收和棄置的規則。"},{"en":"European e-waste laws may require manufacturers to pay for recycling systems.","zh":"歐洲電子廢物法例可能要求製造商支付回收系統費用。"},{"en":"These laws can reduce unsafe disposal by setting clear responsibilities.","zh":"這些法律可以透過設定清楚責任來減少不安全棄置。"},{"en":"The phrase refers to Europe’s legal approach to managing electronic waste.","zh":"這個短語指歐洲管理電子廢物的法律做法。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":19},{"front":"mercury leaching","meaning":"水銀滲漏","examples":[{"en":"Mercury leaching is a serious problem in landfills.","zh":"水銀滲漏是堆填區中的嚴重問題。"},{"en":"Mercury leaching means mercury slowly leaking out of waste into soil or water.","zh":"mercury leaching 指水銀從廢物中慢慢滲入泥土或水中。"},{"en":"Old electronic parts may cause mercury leaching if they are buried carelessly.","zh":"如果舊電子零件被隨意掩埋，可能造成水銀滲漏。"},{"en":"Mercury leaching can pollute groundwater and harm living organisms.","zh":"水銀滲漏可以污染地下水並傷害生物。"},{"en":"Preventing mercury leaching requires proper collection and safe disposal of mercury-containing products.","zh":"防止水銀滲漏需要妥善收集和安全棄置含水銀產品。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":19},{"front":"recycled products","meaning":"回收產品；回收物料製成的產品","examples":[{"en":"New products may be required to contain recycled materials.","zh":"新產品可能被要求含有回收物料。"},{"en":"Recycled products are products made partly or fully from materials recovered from waste.","zh":"recycled products 是部分或全部由廢物中回收的材料製成的產品。"},{"en":"A notebook made from old paper is a simple recycled product.","zh":"由舊紙製成的筆記本是簡單的回收產品。"},{"en":"Recycled products can reduce demand for new raw materials.","zh":"回收產品可以減少對新原材料的需求。"},{"en":"Buying recycled products supports a market for materials that might otherwise become waste.","zh":"購買回收產品支持回收物料市場，否則這些物料可能變成廢物。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":19},{"front":"look at the following list of statements","meaning":"查看以下陳述列表","examples":[{"en":"Students look at the following list of statements before matching them with companies.","zh":"學生先查看以下陳述列表，然後把它們與公司配對。"},{"en":"Look at the following list of statements means read the set of sentences or claims provided below.","zh":"look at the following list of statements 意思是閱讀下面提供的一組句子或說法。"},{"en":"In an exam, students should look at the following list of statements carefully before scanning the passage.","zh":"在考試中，學生應先仔細查看以下陳述列表，再掃讀文章。"},{"en":"If students rush through the list, they may miss key words that guide the answer.","zh":"如果學生匆忙看過列表，可能錯過引導答案的關鍵詞。"},{"en":"This instruction tells students where to focus before answering.","zh":"這個指示告訴學生答題前應集中在哪裡。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":19},{"front":"match each statement with","meaning":"把每項陳述與……配對","examples":[{"en":"Students match each statement with the correct company.","zh":"學生把每項陳述與正確公司配對。"},{"en":"To match each statement with something means to connect every sentence to the option it belongs to.","zh":"match each statement with something 意思是把每個句子連接到所屬的選項。"},{"en":"In a reading task, students may match each statement with a person, place, or organisation.","zh":"在閱讀題中，學生可能要把每項陳述與人物、地方或機構配對。"},{"en":"Students should match statements with evidence in the passage, not guesses.","zh":"學生應根據文章證據配對陳述，而不是靠猜。"},{"en":"This task tests careful reading and comparison.","zh":"這類題目測試仔細閱讀和比較能力。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":19},{"front":"the correct company","meaning":"正確公司","examples":[{"en":"The task asks students to identify the correct company.","zh":"題目要求學生辨認正確公司。"},{"en":"The correct company is the company that matches the statement according to the passage.","zh":"the correct company 是根據文章與陳述相配的公司。"},{"en":"Students should look for names, actions, and opinions to find the correct company.","zh":"學生應尋找名稱、行動和觀點，以找出正確公司。"},{"en":"Choosing the correct company requires evidence, not just a familiar word.","zh":"選出正確公司需要證據，而不只是熟悉字詞。"},{"en":"This phrase appears in matching questions involving organisations.","zh":"這個短語出現在涉及機構的配對題中。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":19},{"front":"may use any letter more than once","meaning":"可以多次使用任何字母","examples":[{"en":"Students may use any letter more than once.","zh":"學生可以多次使用任何字母。"},{"en":"May use any letter more than once means the same option can be chosen for several answers.","zh":"may use any letter more than once 意思是同一選項可以被用於多個答案。"},{"en":"In matching tasks, students should not cross out an option if the instructions allow repeated letters.","zh":"在配對題中，如果指示容許重複使用字母，學生不應劃走某選項。"},{"en":"If a letter can be used more than once, two statements may refer to the same company.","zh":"如果字母可以多次使用，兩項陳述可能指同一公司。"},{"en":"Reading instructions carefully prevents avoidable mistakes.","zh":"仔細閱讀指示可以避免不必要錯誤。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":19},{"front":"waste sites without strict dumping rules","meaning":"沒有嚴格傾倒規則的廢物場","examples":[{"en":"Waste sites without strict dumping rules can cause major pollution problems.","zh":"沒有嚴格傾倒規則的廢物場可以造成重大污染問題。"},{"en":"Waste sites without strict dumping rules are places where rubbish is accepted with weak control over what can be dumped.","zh":"waste sites without strict dumping rules 指對可傾倒物品缺乏嚴格管制的垃圾場。"},{"en":"A poorly managed dump may accept batteries, chemicals, and e-waste without checks.","zh":"管理不善的垃圾場可能在未檢查下接收電池、化學品和電子廢物。"},{"en":"Without strict dumping rules, toxic materials may enter soil, water, or air.","zh":"沒有嚴格傾倒規則，有毒物料可能進入泥土、水或空氣。"},{"en":"This phrase highlights the danger of weak waste regulation.","zh":"這個短語突出廢物規管薄弱的危險。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":19},{"front":"strict dumping rules","meaning":"嚴格的傾倒規則","examples":[{"en":"Strict dumping rules can reduce the risks of toxic waste.","zh":"嚴格的傾倒規則可以減少有毒廢物的風險。"},{"en":"Strict dumping rules are clear and firm regulations about what waste may be placed where.","zh":"strict dumping rules 是關於哪些廢物可以放在哪裡的清楚而嚴格規定。"},{"en":"A city may require strict dumping rules for batteries, chemicals, and electronics.","zh":"城市可能要求電池、化學品和電子產品遵守嚴格傾倒規則。"},{"en":"Strict dumping rules help prevent dangerous materials from entering ordinary landfills.","zh":"嚴格傾倒規則有助防止危險物料進入普通堆填區。"},{"en":"Rules must also be enforced; otherwise, they only exist on paper.","zh":"規則也必須被執行；否則只會停留在紙上。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":20},{"front":"lead to big problems","meaning":"導致重大問題","examples":[{"en":"Weak controls at waste sites can lead to big problems.","zh":"廢物場的薄弱管制可以導致重大問題。"},{"en":"To lead to big problems means to cause serious difficulties or harmful results.","zh":"lead to big problems 意思是造成嚴重困難或有害結果。"},{"en":"A small leak can lead to big problems if no one repairs it quickly.","zh":"如果沒有人迅速維修，小滲漏可以導致重大問題。"},{"en":"Weak e-waste controls can lead to big problems such as fires, pollution, and illness.","zh":"薄弱電子廢物管制可以導致火災、污染和疾病等重大問題。"},{"en":"This phrase is simple but useful for explaining consequences.","zh":"這個短語簡單，但適合用來解釋後果。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":20},{"front":"sending e-waste abroad","meaning":"把電子廢物送往海外","examples":[{"en":"Sending e-waste abroad may be cheaper than recycling it locally.","zh":"把電子廢物送往海外可能比在本地回收便宜。"},{"en":"Sending e-waste abroad means transporting electronic waste to another country.","zh":"sending e-waste abroad 意思是把電子廢物運到另一個國家。"},{"en":"A company may send e-waste abroad if foreign labour costs are lower.","zh":"如果外國勞工成本較低，公司可能把電子廢物送往海外。"},{"en":"Sending e-waste abroad can hide pollution from the country that produced it.","zh":"把電子廢物送往海外可以把污染從產生廢物的國家隱藏起來。"},{"en":"This practice needs control so waste does not end up in unsafe sites.","zh":"這種做法需要管制，避免廢物最終去到不安全場地。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":20},{"front":"cheaper than recycling it domestically","meaning":"比在本地回收便宜","examples":[{"en":"Exporting monitors can be cheaper than recycling them domestically.","zh":"出口顯示器可能比在本地回收它們便宜。"},{"en":"Cheaper than recycling it domestically means costing less than processing the waste within the same country.","zh":"cheaper than recycling it domestically 意思是成本低於在同一國家內處理廢物。"},{"en":"Shipping old equipment overseas may be cheaper than recycling it domestically if local wages are high.","zh":"如果本地工資高，把舊設備運往海外可能比在本地回收便宜。"},{"en":"When export is cheaper, companies may need laws to stop them choosing unsafe options.","zh":"當出口較便宜時，公司可能需要法律阻止它們選擇不安全方法。"},{"en":"Cost alone should not decide waste policy.","zh":"成本不應單獨決定廢物政策。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":20},{"front":"most old computers","meaning":"大多數舊電腦","examples":[{"en":"The passage suggests that most old computers will be buried, burned or exported.","zh":"文章暗示大多數舊電腦會被掩埋、焚燒或出口。"},{"en":"Most old computers means the majority of computers that are no longer new or wanted.","zh":"most old computers 指大部分不再新或不再被需要的電腦。"},{"en":"Most old computers in an office may be stored for months before disposal.","zh":"辦公室中的大多數舊電腦可能在棄置前被存放數月。"},{"en":"If most old computers are not recycled properly, they can become a major waste problem.","zh":"如果大多數舊電腦沒有被妥善回收，它們可以成為重大廢物問題。"},{"en":"This phrase focuses on the scale of discarded computer equipment.","zh":"這個短語集中於被丟棄電腦設備的規模。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":20},{"front":"buried or burned","meaning":"被掩埋或焚燒","examples":[{"en":"Old computers may be buried or burned if they are not recycled properly.","zh":"如果舊電腦沒有被妥善回收，可能被掩埋或焚燒。"},{"en":"Buried or burned means placed underground or destroyed by fire.","zh":"buried or burned 意思是被埋在地下或被火燒毀。"},{"en":"Waste may be buried or burned when proper recycling systems are not available.","zh":"當沒有合適回收系統時，廢物可能被掩埋或焚燒。"},{"en":"If e-waste is buried or burned, toxic materials may enter soil or air.","zh":"如果電子廢物被掩埋或焚燒，有毒物料可能進入泥土或空氣。"},{"en":"This phrase describes two disposal methods that can be harmful.","zh":"這個短語描述兩種可能有害的棄置方法。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":20},{"front":"contain metal waste in soil","meaning":"把金屬廢物封存在泥土中","examples":[{"en":"Even modern landfills cannot fully contain metal waste in soil.","zh":"即使現代堆填區也不能完全把金屬廢物封存在泥土中。"},{"en":"To contain metal waste in soil means to keep metal pollutants trapped so they do not spread.","zh":"contain metal waste in soil 意思是把金屬污染物困住，不讓它們擴散。"},{"en":"A landfill liner is designed to contain waste in the ground.","zh":"堆填區襯層的設計目的是把廢物封存在地下。"},{"en":"If a site cannot contain metal waste, leaching may pollute groundwater.","zh":"如果場地不能封存金屬廢物，滲漏可能污染地下水。"},{"en":"This phrase shows the challenge of stopping metals from moving through soil.","zh":"這個短語顯示阻止金屬在泥土中移動的挑戰。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":20},{"front":"choose three letters","meaning":"選出三個字母","examples":[{"en":"Students must choose three letters from the list.","zh":"學生必須從列表中選出三個字母。"},{"en":"To choose three letters means to select three option labels as the answer.","zh":"choose three letters 意思是選出三個選項字母作為答案。"},{"en":"In multiple-answer questions, students should choose three letters only if the instruction says so.","zh":"在多選題中，只有當指示要求時，學生才應選出三個字母。"},{"en":"Choosing too many letters can lose marks even if some are correct.","zh":"選太多字母可能失分，即使其中一些正確。"},{"en":"This phrase reminds students of the exact number of answers required.","zh":"這個短語提醒學生所需答案的準確數量。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":20},{"front":"according to the passage","meaning":"根據篇章","examples":[{"en":"Students should answer according to the passage.","zh":"學生應根據篇章作答。"},{"en":"According to the passage means based only on what the text says.","zh":"according to the passage 意思是只根據文章所說。"},{"en":"In reading exams, students must answer according to the passage, not their own opinions.","zh":"在閱讀考試中，學生必須根據篇章作答，而不是根據自己的意見。"},{"en":"An answer may sound true in real life but be wrong if the passage does not support it.","zh":"答案在現實生活中可能聽起來正確，但如果篇章不支持它，就可能是錯的。"},{"en":"This phrase reminds students to use textual evidence.","zh":"這個短語提醒學生使用文本證據。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":20},{"front":"pollution laws","meaning":"污染法例","examples":[{"en":"The question asks which pollution laws have been proposed in Europe.","zh":"題目問歐洲提出了哪些污染法例。"},{"en":"Pollution laws are rules designed to reduce or control damage to air, water, soil, or ecosystems.","zh":"pollution laws 是旨在減少或控制對空氣、水、泥土或生態系統傷害的規則。"},{"en":"Pollution laws may limit factory emissions or require safe waste disposal.","zh":"污染法例可能限制工廠排放或要求安全棄置廢物。"},{"en":"Strong pollution laws can make companies pay attention to environmental harm.","zh":"強而有力的污染法例可以令公司重視環境傷害。"},{"en":"These laws work best when they are clear, enforced, and regularly updated.","zh":"這些法律在清楚、被執行並定期更新時最有效。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":20},{"front":"have been proposed","meaning":"已被提出","examples":[{"en":"Several pollution laws have been proposed in Europe.","zh":"歐洲已提出數項污染法例。"},{"en":"Have been proposed means have been suggested for discussion or possible approval.","zh":"have been proposed 意思是已被建議作討論或可能批准。"},{"en":"New school rules have been proposed after several safety complaints.","zh":"在多宗安全投訴後，新的校規已被提出。"},{"en":"Proposed laws may change before they are finally passed.","zh":"擬議法律在最終通過前可能改變。"},{"en":"This phrase shows that an idea has been put forward but may not yet be final.","zh":"這個短語顯示想法已被提出，但未必已成定案。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":20},{"front":"manufacturers will have to pay for","meaning":"生產商將須支付……費用","examples":[{"en":"Manufacturers will have to pay for the disposal of their products.","zh":"生產商將須支付其產品的棄置費用。"},{"en":"Manufacturers will have to pay for something means companies that make products will be required to cover the cost.","zh":"manufacturers will have to pay for something 意思是製造產品的公司將被要求承擔費用。"},{"en":"Manufacturers may have to pay for repairs if a product is recalled.","zh":"如果產品被召回，生產商可能須支付維修費用。"},{"en":"If manufacturers pay for disposal, they may design products that are easier and cheaper to recycle.","zh":"如果生產商支付棄置費用，他們可能設計更容易和更便宜回收的產品。"},{"en":"This phrase highlights financial responsibility.","zh":"這個短語突出財政責任。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":21},{"front":"disposal of their products","meaning":"其產品的棄置","examples":[{"en":"Manufacturers may be responsible for the disposal of their products.","zh":"製造商可能要為其產品的棄置負責。"},{"en":"Disposal of their products means the process of safely getting rid of the items they make after use.","zh":"disposal of their products 指在使用後安全處理其製造物品的過程。"},{"en":"A printer company may need a plan for the disposal of its products when customers replace them.","zh":"打印機公司可能需要在顧客替換產品時，為其產品的棄置制定計劃。"},{"en":"If companies are responsible for disposal, they may reduce toxic materials during design.","zh":"如果公司負責棄置，它們可能在設計時減少有毒材料。"},{"en":"This phrase links a product’s end-of-life stage back to its maker.","zh":"這個短語把產品生命結束階段連回製造商。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":21},{"front":"dispose of electronic goods","meaning":"棄置電子產品","examples":[{"en":"Manufacturers may have to dispose of the electronic goods they produce.","zh":"製造商可能必須棄置自己生產的電子產品。"},{"en":"To dispose of electronic goods means to safely get rid of used electrical or electronic products.","zh":"dispose of electronic goods 意思是安全處理用過的電器或電子產品。"},{"en":"A shop may collect old phones and dispose of electronic goods through licensed recyclers.","zh":"商店可能收集舊手機，並透過持牌回收商棄置電子產品。"},{"en":"If companies dispose of electronic goods properly, fewer toxic materials enter landfills.","zh":"如果公司妥善棄置電子產品，進入堆填區的有毒物料就會減少。"},{"en":"Proper disposal requires more than throwing devices into ordinary rubbish.","zh":"妥善棄置不只是把裝置丟進普通垃圾。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":21},{"front":"completely recyclable","meaning":"可完全回收的","examples":[{"en":"The option mentions products that are completely recyclable.","zh":"該選項提到可完全回收的產品。"},{"en":"Completely recyclable means every part of a product can be processed and used again as material.","zh":"completely recyclable 意思是產品的每一部分都可以被處理並再次用作材料。"},{"en":"A bottle is not completely recyclable if its label, cap, or coating cannot be recycled.","zh":"如果樽上的標籤、瓶蓋或塗層不能回收，該樽就不是可完全回收的。"},{"en":"Designing completely recyclable electronics is difficult because devices contain many mixed materials.","zh":"設計可完全回收的電子產品很困難，因為裝置含有許多混合材料。"},{"en":"This phrase sets a very high standard for product design.","zh":"這個短語為產品設計設定了很高標準。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":21},{"front":"consumers are responsible for","meaning":"消費者負責","examples":[{"en":"The option says consumers are responsible for disposal.","zh":"該選項說消費者負責棄置。"},{"en":"Consumers are responsible for something means people who buy or use products must take care of that duty.","zh":"consumers are responsible for something 意思是購買或使用產品的人必須承擔該責任。"},{"en":"Consumers are responsible for returning borrowed library books on time.","zh":"消費者負責準時歸還借閱的圖書館書籍。"},{"en":"If consumers alone are responsible for e-waste, producers may have little reason to change design.","zh":"如果只有消費者負責電子廢物，生產商可能沒有太大理由改變設計。"},{"en":"This phrase identifies responsibility on the buyer or user side.","zh":"這個短語指出責任在買家或使用者一方。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":21},{"front":"products containing mercury","meaning":"含水銀的產品","examples":[{"en":"Products containing mercury require careful disposal.","zh":"含水銀的產品需要小心棄置。"},{"en":"Products containing mercury are items that include the toxic metal mercury inside their parts.","zh":"products containing mercury 指零件中含有有毒金屬水銀的物品。"},{"en":"Some old switches, lamps, and electronic components may be products containing mercury.","zh":"一些舊開關、燈管和電子部件可能是含水銀產品。"},{"en":"If products containing mercury are broken or burned, mercury may enter the environment.","zh":"如果含水銀產品被打碎或焚燒，水銀可能進入環境。"},{"en":"These products should be collected separately and handled safely.","zh":"這些產品應分開收集並安全處理。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":21},{"front":"should be incinerated","meaning":"應被焚化","examples":[{"en":"The option discusses whether products containing mercury should be incinerated.","zh":"該選項討論含水銀產品是否應被焚化。"},{"en":"Should be incinerated means should be burned as a method of disposal.","zh":"should be incinerated 意思是應透過焚燒作為棄置方法。"},{"en":"Some waste should be incinerated only if burning is safer than other treatment methods.","zh":"某些廢物只有在焚燒比其他處理方法更安全時才應被焚化。"},{"en":"Products containing mercury should not be incinerated because burning can release toxic substances.","zh":"含水銀產品不應被焚化，因為焚燒可以釋放有毒物質。"},{"en":"This phrase is often tested because students must notice whether the passage supports or rejects it.","zh":"這個短語常被考核，因為學生必須注意文章支持還是否定它。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":21},{"front":"implement EU laws","meaning":"實施歐盟法律","examples":[{"en":"Other governments may consider whether to implement EU laws.","zh":"其他政府可能考慮是否實施歐盟法律。"},{"en":"To implement EU laws means to put European Union legal rules into practice.","zh":"implement EU laws 意思是把歐盟法律規則付諸實行。"},{"en":"A country outside Europe may implement EU-style laws if it wants stricter recycling standards.","zh":"歐洲以外的國家如果想要更嚴格回收標準，可能實施歐盟式法律。"},{"en":"Implementing EU laws can require new collection systems, inspections, and producer payments.","zh":"實施歐盟法律可能需要新的收集系統、檢查和生產商付款。"},{"en":"This phrase focuses on turning legal ideas into real policy action.","zh":"這個短語集中於把法律想法變成實際政策行動。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":21},{"front":"a large percentage of","meaning":"大比例的……","examples":[{"en":"A large percentage of old equipment must be recycled or reused.","zh":"大比例的舊設備必須被回收或再用。"},{"en":"A large percentage of something means a high proportion or many out of every hundred.","zh":"a large percentage of something 指高比例或每一百個中有很多。"},{"en":"A large percentage of students may use phones for homework research.","zh":"大比例學生可能用手機做功課資料搜集。"},{"en":"If a large percentage of collected equipment is reused, landfill pressure falls.","zh":"如果大比例收集到的設備被再用，堆填壓力會下降。"},{"en":"This phrase is useful when describing quantity in a general but numerical way.","zh":"這個短語適合用一般但帶數字感的方式描述數量。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":21},{"front":"be included in new products","meaning":"被加入新產品中","examples":[{"en":"Recycled material can be included in new products.","zh":"回收物料可以被加入新產品中。"},{"en":"To be included in new products means to be used as part of newly made items.","zh":"be included in new products 意思是被用作新製造物品的一部分。"},{"en":"Recycled plastic can be included in new chairs, bags, or packaging.","zh":"回收塑膠可以被加入新椅子、袋或包裝中。"},{"en":"If recycled metals are included in new electronics, fewer raw materials may need to be mined.","zh":"如果回收金屬被加入新電子產品中，需要開採的新原材料可能減少。"},{"en":"This phrase shows how waste can return to production as useful material.","zh":"這個短語顯示廢物如何以有用材料形式回到生產中。"}],"source":"59 - The intense rate of change in the world.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 60":[{"front":"park the car permanently","meaning":"永久停用汽車","examples":[{"en":"The article asks whether people should park the car permanently.","zh":"文章問人們是否應該永久停用汽車。"},{"en":"To park the car permanently means to stop using a car for good.","zh":"To park the car permanently 指永遠停止使用汽車。"},{"en":"A family may park the car permanently if buses, trains, and bicycles meet their daily needs.","zh":"如果巴士、火車和單車能滿足日常需要，一個家庭可能會永久停用汽車。"},{"en":"Rising fuel, insurance, and parking costs may make some drivers park the car permanently.","zh":"汽油、保險和泊車費上升，可能令一些駕駛者永久停用汽車。"},{"en":"This phrase suggests giving up regular car use, not just leaving the car in a car park.","zh":"這個片語指放棄經常使用汽車，而不只是把車停在停車場。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":1},{"front":"more than a million people","meaning":"超過一百萬人","examples":[{"en":"More than a million people are likely to be disappointed by the government’s plans.","zh":"超過一百萬人很可能對政府計劃感到失望。"},{"en":"More than a million people means over 1,000,000 individuals.","zh":"More than a million people 指超過1,000,000人。"},{"en":"More than a million people may sign a petition if an issue affects transport, housing, or healthcare.","zh":"如果某議題影響交通、住屋或醫療，可能有超過一百萬人簽署請願書。"},{"en":"When more than a million people object to a plan, the government may face strong public pressure.","zh":"當超過一百萬人反對一項計劃，政府可能面對強大公眾壓力。"},{"en":"This phrase highlights a very large group, not a small complaint.","zh":"這個片語突顯非常龐大的群體，而不是小規模投訴。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":1},{"front":"be likely to be disappointed by","meaning":"很可能對……感到失望","examples":[{"en":"Many drivers are likely to be disappointed by the government’s response.","zh":"許多駕駛者很可能對政府回應感到失望。"},{"en":"To be likely to be disappointed by something means to probably feel unhappy because it does not meet expectations.","zh":"To be likely to be disappointed by something 指很可能因某事未達期望而感到不高興。"},{"en":"Students are likely to be disappointed by a cancelled school trip if they have prepared for weeks.","zh":"如果學生已準備數星期，學校旅行卻被取消，他們很可能感到失望。"},{"en":"If people expect the government to change a policy but it refuses, they are likely to be disappointed.","zh":"如果人們期望政府改變政策但政府拒絕，他們很可能感到失望。"},{"en":"This phrase predicts a negative emotional reaction.","zh":"這個片語預測負面情緒反應。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":1},{"front":"attempts to improve","meaning":"改善……的嘗試","examples":[{"en":"The government made attempts to improve the democratic process.","zh":"政府作出了改善民主程序的嘗試。"},{"en":"Attempts to improve something are efforts to make it better.","zh":"Attempts to improve something 是令某事變得更好的努力。"},{"en":"A school may make attempts to improve reading by giving students clearer feedback.","zh":"學校可能透過給學生更清晰回饋，作出改善閱讀的嘗試。"},{"en":"Attempts to improve public transport can fail if buses remain unreliable.","zh":"如果巴士仍然不可靠，改善公共交通的嘗試可能失敗。"},{"en":"This phrase shows effort, but not necessarily success.","zh":"這個片語顯示努力，但不一定代表成功。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":1},{"front":"the democratic process","meaning":"民主程序","examples":[{"en":"Many people were disappointed by their experience of the democratic process.","zh":"許多人對自己在民主程序中的經驗感到失望。"},{"en":"The democratic process is the way citizens express views and influence decisions in a democracy.","zh":"The democratic process 是公民在民主制度中表達意見和影響決策的方式。"},{"en":"Voting, public consultation, petitions, and debates are parts of the democratic process.","zh":"投票、公眾諮詢、請願和辯論都是民主程序的一部分。"},{"en":"If people feel officials ignore their voices, trust in the democratic process may weaken.","zh":"如果人們覺得官員忽視他們的聲音，對民主程序的信任可能削弱。"},{"en":"This phrase refers to how public decisions are made with citizen involvement.","zh":"這個片語指公共決策如何透過公民參與而形成。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":1},{"front":"sign an online petition","meaning":"簽署網上請願書","examples":[{"en":"They may have signed an online petition against road pricing.","zh":"他們可能已簽署反對道路收費的網上請願書。"},{"en":"To sign an online petition means to add your name digitally to support or oppose an issue.","zh":"To sign an online petition 指以電子方式加入姓名，以支持或反對某議題。"},{"en":"Parents may sign an online petition if they want a school bus route to be kept.","zh":"如果家長想保留校巴路線，他們可能簽署網上請願書。"},{"en":"If many people sign an online petition, leaders may realise that public feeling is strong.","zh":"如果許多人簽署網上請願書，領導者可能意識到民意強烈。"},{"en":"This phrase describes a digital form of protest or support.","zh":"這個片語描述一種數碼形式的抗議或支持。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":1},{"front":"against road pricing","meaning":"反對道路收費","examples":[{"en":"Many people signed a petition against road pricing.","zh":"許多人簽署請願書反對道路收費。"},{"en":"Against road pricing means opposed to charging drivers for using certain roads.","zh":"Against road pricing 指反對向駕駛者收取某些道路使用費。"},{"en":"Drivers may campaign against road pricing if they believe it unfairly punishes commuters.","zh":"如果駕駛者認為道路收費不公平地懲罰通勤者，他們可能發起運動反對道路收費。"},{"en":"If road pricing makes daily travel more expensive, opposition may increase.","zh":"如果道路收費令日常出行更昂貴，反對聲音可能增加。"},{"en":"This phrase shows a clear position against a transport policy.","zh":"這個片語顯示對一項交通政策的明確反對立場。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":1},{"front":"be determined to","meaning":"決心要","examples":[{"en":"Ministers are determined to push ahead with the plans.","zh":"部長們決心要繼續推行計劃。"},{"en":"To be determined to do something means to have a firm decision and not give up easily.","zh":"To be determined to do something 指下定決心做某事，而且不輕易放棄。"},{"en":"A student may be determined to improve speaking by practising every day.","zh":"學生可能決心要透過每日練習改善口語。"},{"en":"If leaders are determined to continue a policy, public protests may not change their minds quickly.","zh":"如果領導者決心要繼續某政策，公眾抗議未必能很快改變他們想法。"},{"en":"This phrase shows strong intention and persistence.","zh":"這個片語顯示強烈意圖和堅持。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":1},{"front":"push ahead with plans","meaning":"推行計劃；繼續推進計劃","examples":[{"en":"Ministers are determined to push ahead with plans to charge drivers more.","zh":"部長們決心繼續推進向駕駛者收取更多費用的計劃。"},{"en":"To push ahead with plans means to continue with them despite opposition or difficulty.","zh":"To push ahead with plans 指即使有反對或困難，仍繼續推行計劃。"},{"en":"A school may push ahead with exam reform even if some parents complain.","zh":"即使有些家長投訴，學校仍可能繼續推進考試改革計劃。"},{"en":"If a government pushes ahead with unpopular plans, public anger may grow.","zh":"如果政府繼續推行不受歡迎的計劃，公眾憤怒可能增加。"},{"en":"This phrase suggests moving forward firmly with a planned action.","zh":"這個片語暗示堅定地推進已計劃的行動。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":1},{"front":"make it more expensive to","meaning":"令……更昂貴","examples":[{"en":"The plans will make it more expensive to drive.","zh":"這些計劃會令駕車更昂貴。"},{"en":"To make it more expensive to do something means to increase the cost of doing it.","zh":"To make it more expensive to do something 指提高做某事的成本。"},{"en":"Higher ticket prices make it more expensive to take the train every day.","zh":"車票價格上升會令每天乘火車更昂貴。"},{"en":"If fuel tax rises, it can make it more expensive to own and use a car.","zh":"如果燃油稅上升，它可以令擁有和使用汽車更昂貴。"},{"en":"This phrase explains how a policy or change raises costs.","zh":"這個片語解釋政策或變化如何提高成本。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":1},{"front":"be convinced that","meaning":"確信","examples":[{"en":"The government is convinced that road pricing is necessary.","zh":"政府確信道路收費是必要的。"},{"en":"To be convinced that something is true means to strongly believe it because of reasons or evidence.","zh":"To be convinced that something is true 指因理由或證據而強烈相信某事是真的。"},{"en":"A teacher may be convinced that small classes help weaker students after seeing better results.","zh":"老師看見成績改善後，可能確信小班教學能幫助較弱學生。"},{"en":"If officials are convinced that a policy will reduce congestion, they may continue despite criticism.","zh":"如果官員確信某政策會減少交通擠塞，他們可能即使受批評仍繼續推行。"},{"en":"This phrase describes strong belief, not a casual guess.","zh":"這個片語描述強烈信念，而不是隨便猜測。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":2},{"front":"the only way to","meaning":"……的唯一方法","examples":[{"en":"The government believes that road pricing is the only way to reduce congestion.","zh":"政府相信道路收費是減少交通擠塞的唯一方法。"},{"en":"The only way to do something means the single method that can achieve the result.","zh":"The only way to do something 指達成某結果的唯一方法。"},{"en":"For some students, daily practice may be the only way to build real fluency.","zh":"對一些學生來說，每日練習可能是建立真正流利度的唯一方法。"},{"en":"If traffic keeps worsening, officials may argue that charging drivers is the only way to change behaviour.","zh":"如果交通持續惡化，官員可能主張向駕駛者收費是改變行為的唯一方法。"},{"en":"This phrase presents one method as necessary and without a real alternative.","zh":"這個片語把一種方法呈現為必要，而且沒有真正替代方案。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":2},{"front":"reduce congestion","meaning":"減少交通擠塞","examples":[{"en":"Road pricing may reduce congestion in busy areas.","zh":"道路收費可能減少繁忙地區的交通擠塞。"},{"en":"To reduce congestion means to make roads, streets, or transport systems less crowded.","zh":"To reduce congestion 指令道路、街道或交通系統不那麼擠塞。"},{"en":"More frequent buses can reduce congestion if fewer people choose to drive.","zh":"如果較少人選擇駕車，更頻密的巴士服務可以減少交通擠塞。"},{"en":"If congestion is reduced, journeys may become faster and less stressful.","zh":"如果交通擠塞減少，旅程可能更快且壓力較少。"},{"en":"This phrase is often used in transport and city-planning discussions.","zh":"這個片語常用於交通和城市規劃討論。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":2},{"front":"environmental damage","meaning":"環境破壞","examples":[{"en":"The government wants to reduce the environmental damage caused by motoring.","zh":"政府想減少由駕車造成的環境破壞。"},{"en":"Environmental damage is harm done to air, water, land, wildlife, or climate.","zh":"Environmental damage 是對空氣、水、土地、野生生物或氣候造成的傷害。"},{"en":"Heavy traffic can cause environmental damage by increasing pollution and carbon emissions.","zh":"嚴重交通可以透過增加污染和碳排放造成環境破壞。"},{"en":"If car use falls, some environmental damage from fuel burning may also fall.","zh":"如果汽車使用量下降，燃油燃燒造成的一些環境破壞也可能下降。"},{"en":"This phrase refers to harm to the natural world.","zh":"這個片語指對自然世界的傷害。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":2},{"front":"caused by motoring","meaning":"由駕車造成","examples":[{"en":"The policy targets the environmental damage caused by motoring.","zh":"這項政策針對由駕車造成的環境破壞。"},{"en":"Caused by motoring means produced as a result of driving cars or using motor vehicles.","zh":"Caused by motoring 指由駕駛汽車或使用機動車輛所造成。"},{"en":"Air pollution caused by motoring can affect children who live near busy roads.","zh":"由駕車造成的空氣污染可以影響住在繁忙道路附近的兒童。"},{"en":"If more people drive alone, the damage caused by motoring may increase.","zh":"如果更多人獨自駕車，由駕車造成的傷害可能增加。"},{"en":"This phrase links a problem directly to car use.","zh":"這個片語把問題直接連接到汽車使用。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":2},{"front":"forced off the road","meaning":"被迫不再駕車上路","examples":[{"en":"Drivers may eventually be forced off the road by costly charges.","zh":"駕駛者最終可能因高昂收費而被迫不再駕車上路。"},{"en":"To be forced off the road means to stop driving because pressure or cost makes driving impossible or impractical.","zh":"To be forced off the road 指因壓力或成本令駕車不可能或不實際而停止駕車。"},{"en":"A delivery driver may be forced off the road if fuel costs rise too high.","zh":"如果燃油成本升得太高，送貨司機可能被迫不再駕車上路。"},{"en":"If road charges become unaffordable, low-income drivers may be forced off the road first.","zh":"如果道路收費變得負擔不起，低收入駕駛者可能最先被迫不再駕車上路。"},{"en":"This phrase suggests that drivers lose the choice to continue driving.","zh":"這個片語暗示駕駛者失去繼續駕車的選擇。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":2},{"front":"costly charges","meaning":"高昂收費","examples":[{"en":"Some drivers may give up their cars because of costly charges.","zh":"一些駕駛者可能因高昂收費而放棄汽車。"},{"en":"Costly charges are fees that are expensive and difficult for people to afford.","zh":"Costly charges 是昂貴且令人難以負擔的費用。"},{"en":"Costly charges for parking can discourage shoppers from driving into town.","zh":"高昂泊車費可以令購物者不想駕車入市中心。"},{"en":"If costly charges are added to daily travel, families may change how they commute.","zh":"如果日常出行加入高昂收費，家庭可能改變通勤方式。"},{"en":"This phrase emphasises that fees create financial pressure.","zh":"這個片語強調收費造成財政壓力。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":2},{"front":"enjoy the convenience of","meaning":"享受……的便利","examples":[{"en":"Many people enjoy the convenience of their cars.","zh":"許多人享受汽車帶來的便利。"},{"en":"To enjoy the convenience of something means to benefit from how easy and comfortable it makes daily life.","zh":"To enjoy the convenience of something 指受惠於某物令日常生活更容易和舒適。"},{"en":"Parents may enjoy the convenience of a car when taking children to school and activities.","zh":"家長接送孩子上學和參加活動時，可能享受汽車的便利。"},{"en":"If people enjoy the convenience of driving, they may resist giving up their cars.","zh":"如果人們享受駕車的便利，他們可能抗拒放棄汽車。"},{"en":"This phrase highlights comfort, flexibility, and ease of use.","zh":"這個片語突顯舒適、彈性和易用性。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":2},{"front":"the truth is that","meaning":"事實是","examples":[{"en":"The truth is that owning a car makes little financial sense for many people.","zh":"事實是，對許多人來說，擁有汽車在經濟上不太合理。"},{"en":"The truth is that introduces a direct statement about what is really the case.","zh":"The truth is that 用來引出關於實際情況的直接陳述。"},{"en":"The truth is that a cheaper phone may meet most people’s needs.","zh":"事實是，較便宜的手機可能已滿足大多數人的需要。"},{"en":"If a writer says “the truth is that”, they are often correcting a common misunderstanding.","zh":"如果作者說 “the truth is that”，他通常是在糾正常見誤解。"},{"en":"This phrase prepares the reader for a clear and sometimes uncomfortable fact.","zh":"這個片語讓讀者準備接受清楚而有時令人不舒服的事實。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":2},{"front":"huge numbers of people","meaning":"大量人士","examples":[{"en":"For huge numbers of people, owning a car is not financially sensible.","zh":"對大量人士來說，擁有汽車在財政上並不明智。"},{"en":"Huge numbers of people means very many people.","zh":"Huge numbers of people 指非常多人。"},{"en":"Huge numbers of people use buses every day because parking is expensive.","zh":"大量人士每天使用巴士，因為泊車很昂貴。"},{"en":"If huge numbers of people change travel habits, a city’s transport system may also change.","zh":"如果大量人士改變出行習慣，城市交通系統也可能改變。"},{"en":"This phrase stresses the large scale of a group.","zh":"這個片語強調群體規模龐大。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":2},{"front":"owning a car","meaning":"擁有汽車","examples":[{"en":"Owning a car can be a huge financial commitment.","zh":"擁有汽車可以是一項巨大的財政承擔。"},{"en":"Owning a car means having legal possession of a car and being responsible for its costs.","zh":"Owning a car 指合法擁有一輛汽車，並負責其相關成本。"},{"en":"Owning a car may help a family travel easily to school, work, and shops.","zh":"擁有汽車可能幫助家庭更容易前往學校、工作地點和商店。"},{"en":"If someone owns a car, they must usually pay for insurance, repairs, fuel, and parking.","zh":"如果某人擁有汽車，他通常必須支付保險、維修、燃油和泊車費。"},{"en":"This phrase is about responsibility as well as convenience.","zh":"這個片語不只關於便利，也關於責任。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":3},{"front":"make little financial sense","meaning":"在經濟上不太合理","examples":[{"en":"For many people, owning a car makes little financial sense.","zh":"對許多人來說，擁有汽車在經濟上不太合理。"},{"en":"To make little financial sense means to be hard to justify in terms of money.","zh":"To make little financial sense 指從金錢角度看難以合理化。"},{"en":"Buying an expensive printer makes little financial sense if you print only twice a year.","zh":"如果你一年只打印兩次，買昂貴打印機在經濟上不太合理。"},{"en":"If a car sits unused most days, paying thousands each year may make little financial sense.","zh":"如果汽車大多數日子都不用，每年支付數千英鎊可能在經濟上不太合理。"},{"en":"This phrase suggests that the costs are greater than the benefits.","zh":"這個片語暗示成本大於好處。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":3},{"front":"be far better off","meaning":"情況會好得多；更划算","examples":[{"en":"Many drivers would be far better off giving up their cars.","zh":"許多駕駛者如果放棄汽車，情況會好得多。"},{"en":"To be far better off means to be in a much better situation, often financially.","zh":"To be far better off 指處境好得多，通常是財政上更好。"},{"en":"A student may be far better off studying little and often instead of cramming all night.","zh":"學生若少量多次溫習，而不是通宵死背，情況可能好得多。"},{"en":"If public transport is cheap and reliable, a commuter may be far better off without a car.","zh":"如果公共交通便宜可靠，通勤者沒有汽車可能更划算。"},{"en":"This phrase compares two choices and shows one is clearly better.","zh":"這個片語比較兩個選擇，並顯示其中一個明顯更好。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":3},{"front":"give it up","meaning":"放棄它","examples":[{"en":"Some motorists would save money if they gave up their cars.","zh":"一些駕駛者如果放棄汽車，便可以省錢。"},{"en":"To give it up means to stop having or using something.","zh":"To give it up 指停止擁有或使用某物。"},{"en":"A person may give up a gym membership if they never use it.","zh":"如果一個人從不使用健身會籍，他可能放棄它。"},{"en":"If a car costs too much to run, a driver may give it up and use public transport.","zh":"如果汽車使用成本太高，駕駛者可能放棄它並使用公共交通。"},{"en":"This phrase suggests stopping something that has become unnecessary or costly.","zh":"這個片語暗示停止某個變得不必要或昂貴的東西。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":3},{"front":"rely on other forms of transport","meaning":"依靠其他交通方式","examples":[{"en":"People can give up their cars and rely on other forms of transport.","zh":"人們可以放棄汽車，依靠其他交通方式。"},{"en":"To rely on other forms of transport means to depend on buses, trains, bicycles, walking, taxis, or shared cars instead of a private car.","zh":"To rely on other forms of transport 指依賴巴士、火車、單車、步行、的士或共享汽車，而不是私家車。"},{"en":"A student may rely on other forms of transport if the family car is not available.","zh":"如果家庭汽車不可用，學生可能依靠其他交通方式。"},{"en":"If public transport improves, more workers may rely on other forms of transport.","zh":"如果公共交通改善，更多工人可能依靠其他交通方式。"},{"en":"This phrase describes replacing private car use with different travel methods.","zh":"這個片語描述以不同出行方法取代私家車使用。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":3},{"front":"despite having","meaning":"儘管有","examples":[{"en":"Donnachadh McCarthy has never owned a car despite having a job that requires travel.","zh":"Donnachadh McCarthy儘管有一份需要出行的工作，卻從未擁有汽車。"},{"en":"Despite having means although someone has something or is in a certain situation.","zh":"Despite having 指雖然某人擁有某物或處於某情況。"},{"en":"Despite having little time, the student finished the essay carefully.","zh":"儘管時間很少，學生仍仔細完成作文。"},{"en":"If someone lives without a car despite having a travel-heavy job, it challenges common assumptions.","zh":"如果某人儘管有大量出行的工作仍不擁有汽車，這就挑戰常見假設。"},{"en":"This phrase shows contrast between a situation and an unexpected result.","zh":"這個片語顯示情況與意外結果之間的對比。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":3},{"front":"require someone to","meaning":"要求某人","examples":[{"en":"His job requires him to travel all over the South-East.","zh":"他的工作要求他走遍東南部。"},{"en":"To require someone to do something means to make it necessary for that person to do it.","zh":"To require someone to do something 指令某人有必要做某事。"},{"en":"A school may require students to wear uniforms during formal events.","zh":"學校可能要求學生在正式活動中穿校服。"},{"en":"If a job requires someone to travel often, transport choices become very important.","zh":"如果工作要求某人經常出行，交通選擇就變得非常重要。"},{"en":"This phrase shows obligation or necessity.","zh":"這個片語顯示責任或必要性。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":3},{"front":"travel all over","meaning":"到處去；走遍","examples":[{"en":"He travels all over the South-East to visit clients.","zh":"他走遍東南部探訪客戶。"},{"en":"To travel all over a place means to go to many different parts of it.","zh":"To travel all over a place 指前往某地方的許多不同部分。"},{"en":"A nurse may travel all over a district to visit patients at home.","zh":"護士可能走遍一個地區，到病人家中探訪。"},{"en":"If someone travels all over a region, they need reliable transport.","zh":"如果某人走遍一個地區，他需要可靠交通。"},{"en":"This phrase suggests frequent movement across a wide area.","zh":"這個片語暗示在廣闊範圍內頻繁移動。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":3},{"front":"visit clients","meaning":"探訪客戶；會見客戶","examples":[{"en":"His job requires him to visit clients across the region.","zh":"他的工作要求他在整個地區會見客戶。"},{"en":"To visit clients means to meet customers or professional contacts for work.","zh":"To visit clients 指因工作而會見顧客或專業聯絡人。"},{"en":"A financial adviser may visit clients to explain savings plans.","zh":"財務顧問可能會見客戶，以解釋儲蓄計劃。"},{"en":"If a worker must visit clients often, travel time can become part of the job cost.","zh":"如果員工必須經常會見客戶，出行時間可能成為工作成本的一部分。"},{"en":"This phrase is common in business and service work.","zh":"這個片語常見於商業和服務工作。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":3},{"front":"an environmental expert","meaning":"環保專家","examples":[{"en":"Donnachadh McCarthy is an environmental expert.","zh":"Donnachadh McCarthy是一位環保專家。"},{"en":"An environmental expert is someone with specialist knowledge about pollution, resources, energy, or sustainability.","zh":"Environmental expert 是對污染、資源、能源或可持續發展有專門知識的人。"},{"en":"A school may invite an environmental expert to explain how to reduce waste.","zh":"學校可能邀請環保專家解釋如何減少浪費。"},{"en":"If a city wants cleaner transport, an environmental expert may advise on greener options.","zh":"如果城市想要更清潔交通，環保專家可能就更環保選擇提供意見。"},{"en":"This phrase describes a person who understands environmental problems and solutions.","zh":"這個片語描述理解環境問題和解決方法的人。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":3},{"front":"specialise in","meaning":"專門從事","examples":[{"en":"He specialises in advising people on how to be greener.","zh":"他專門從事就如何更環保向人提供意見。"},{"en":"To specialise in something means to focus on one particular area of work or knowledge.","zh":"To specialise in something 指專注於某個特定工作或知識範疇。"},{"en":"A doctor may specialise in children’s health instead of treating every kind of patient.","zh":"醫生可能專門從事兒童健康，而不是治療所有類型病人。"},{"en":"If a consultant specialises in green living, people ask them for environmental advice.","zh":"如果顧問專門從事環保生活，人們會向他們尋求環保意見。"},{"en":"This phrase shows a person’s main area of expertise.","zh":"這個片語顯示某人的主要專業範疇。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":4},{"front":"advise people on","meaning":"就……向人提供意見","examples":[{"en":"He advises people on how to be greener.","zh":"他就如何更環保向人提供意見。"},{"en":"To advise people on something means to give them guidance about what to do.","zh":"To advise people on something 指就該事向人提供該怎樣做的指導。"},{"en":"A teacher may advise students on how to plan revision before exams.","zh":"老師可能就如何在考試前安排溫習向學生提供意見。"},{"en":"If people want to cut car use, an expert can advise them on cheaper travel choices.","zh":"如果人們想減少汽車使用量，專家可以就更便宜的出行選擇向他們提供意見。"},{"en":"This phrase describes giving practical suggestions or professional guidance.","zh":"這個片語描述提供實用建議或專業指導。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":4},{"front":"be greener","meaning":"更環保","examples":[{"en":"Many people want advice on how to be greener.","zh":"許多人想得到關於如何更環保的意見。"},{"en":"To be greener means to live or act in a way that causes less harm to the environment.","zh":"To be greener 指以對環境傷害較少的方式生活或行動。"},{"en":"A family can be greener by wasting less food and using public transport more often.","zh":"家庭可以透過減少食物浪費和更常使用公共交通來更環保。"},{"en":"If a company becomes greener, it may reduce energy use and pollution.","zh":"如果公司變得更環保，它可能減少能源使用和污染。"},{"en":"This phrase describes more environmentally responsible behaviour.","zh":"這個片語描述更負責任的環保行為。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":4},{"front":"a huge financial commitment","meaning":"巨大的財政承擔","examples":[{"en":"A car is a huge financial commitment.","zh":"汽車是一項巨大的財政承擔。"},{"en":"A huge financial commitment is a large long-term money responsibility.","zh":"Huge financial commitment 是一項大型而長期的金錢責任。"},{"en":"Buying a flat is a huge financial commitment because payments may last for decades.","zh":"買樓是一項巨大的財政承擔，因為供款可能持續數十年。"},{"en":"If someone buys a car, insurance, repairs, fuel, and depreciation make it a continuing commitment.","zh":"如果某人買車，保險、維修、燃油和折舊令它成為持續承擔。"},{"en":"This phrase warns that the purchase price is only part of the cost.","zh":"這個片語提醒人，購買價格只是成本的一部分。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":4},{"front":"a psychological addiction","meaning":"心理上的依賴；心理成癮","examples":[{"en":"McCarthy describes car ownership as a psychological addiction.","zh":"McCarthy把擁有汽車描述為心理上的依賴。"},{"en":"A psychological addiction is a strong mental dependence on something, even when it may not be necessary.","zh":"Psychological addiction 是對某事的強烈心理依賴，即使它未必必要。"},{"en":"Some people have a psychological addiction to checking their phones every few minutes.","zh":"有些人心理上依賴每隔幾分鐘查看手機。"},{"en":"If drivers feel unable to live without a car, the problem may be emotional as well as practical.","zh":"如果駕駛者覺得沒有汽車就無法生活，問題可能既是情感上的，也是實際上的。"},{"en":"This phrase describes dependence in the mind, not only physical need.","zh":"這個片語描述心理上的依賴，而不只是身體需要。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":4},{"front":"far more practical than","meaning":"比……實際得多","examples":[{"en":"Not owning a vehicle is far more practical than most people realise.","zh":"不擁有車輛比大多數人所意識到的實際得多。"},{"en":"Far more practical than means much easier, more useful, or more realistic than people expect.","zh":"Far more practical than 指比人們預期容易、有用或現實得多。"},{"en":"Cooking at home may be far more practical than eating out if money is tight.","zh":"如果金錢緊張，在家煮飯可能比外出用餐實際得多。"},{"en":"If buses are frequent and shops are nearby, living without a car may be far more practical than expected.","zh":"如果巴士班次頻密而商店在附近，沒有汽車生活可能比預期實際得多。"},{"en":"This phrase corrects the idea that something is unrealistic.","zh":"這個片語糾正某事不切實際的想法。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":4},{"front":"most people realise","meaning":"大多數人所意識到的","examples":[{"en":"Living without a car is easier than most people realise.","zh":"沒有汽車生活比大多數人所意識到的容易。"},{"en":"Most people realise means what the majority of people understand or notice.","zh":"Most people realise 指大多數人理解或注意到的程度。"},{"en":"Saving money is often harder than most people realise because small daily costs add up.","zh":"儲錢通常比大多數人所意識到的困難，因為每日小開支會累積。"},{"en":"If a task is easier than most people realise, fear may be the main barrier.","zh":"如果一項任務比大多數人所意識到的容易，恐懼可能是主要障礙。"},{"en":"This phrase compares reality with common awareness.","zh":"這個片語比較現實與一般認知。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":4},{"front":"it may seem as if","meaning":"看起來好像","examples":[{"en":"It may seem as if cars have never been cheaper.","zh":"看起來好像汽車從未如此便宜。"},{"en":"It may seem as if means it appears to be true, although the full truth may be different.","zh":"It may seem as if 指某事看起來是真的，雖然完整真相可能不同。"},{"en":"It may seem as if a sale saves money, but buying things you do not need still wastes money.","zh":"減價看起來好像省錢，但購買不需要的東西仍然浪費金錢。"},{"en":"If car prices fall, it may seem as if owning a car is cheap.","zh":"如果汽車價格下降，看起來好像擁有汽車很便宜。"},{"en":"This phrase introduces an appearance that may hide a deeper reality.","zh":"這個片語引出可能掩蓋更深層現實的表象。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":4},{"front":"have never been cheaper","meaning":"從未如此便宜","examples":[{"en":"Cars may seem as if they have never been cheaper.","zh":"汽車可能看起來好像從未如此便宜。"},{"en":"Have never been cheaper means the price appears lower than at any previous time.","zh":"Have never been cheaper 指價格看起來比以往任何時候都低。"},{"en":"Laptops may seem to have never been cheaper during a large online sale.","zh":"在大型網上減價期間，手提電腦可能看起來從未如此便宜。"},{"en":"If purchase prices fall, people may forget that running costs are still high.","zh":"如果購買價格下降，人們可能忘記使用成本仍然很高。"},{"en":"This phrase describes low buying price, not necessarily low total cost.","zh":"這個片語描述購買價格低，而不一定是總成本低。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":4},{"front":"after all","meaning":"畢竟","examples":[{"en":"After all, it is possible to buy a brand-new car for less than £4,800.","zh":"畢竟，購買一輛少於4,800英鎊的全新汽車是可能的。"},{"en":"After all introduces a reason that supports or explains what has just been said.","zh":"After all 用來引出支持或解釋剛才所說內容的理由。"},{"en":"I chose to walk; after all, the shop is only five minutes away.","zh":"我選擇步行；畢竟，商店只在五分鐘路程外。"},{"en":"If something seems surprising, “after all” can give the evidence behind it.","zh":"如果某事看起來令人驚訝，after all 可以給出背後證據。"},{"en":"This phrase often makes an explanation feel more reasonable.","zh":"這個片語常令解釋聽起來更合理。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":4},{"front":"a brand-new car","meaning":"全新汽車","examples":[{"en":"It is possible to buy a brand-new car for less than £4,800.","zh":"購買一輛少於4,800英鎊的全新汽車是可能的。"},{"en":"A brand-new car is a car that has not been owned or used before.","zh":"Brand-new car 是從未被擁有或使用過的汽車。"},{"en":"A driver may prefer a brand-new car because it comes with a warranty.","zh":"駕駛者可能偏好全新汽車，因為它附有保養。"},{"en":"Even if a brand-new car is cheap to buy, it may still be expensive to run.","zh":"即使全新汽車買入價便宜，使用成本仍可能昂貴。"},{"en":"This phrase contrasts a new vehicle with a second-hand one.","zh":"這個片語把新車與二手車作對比。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":5},{"front":"if you’re interested","meaning":"如果你有興趣的話","examples":[{"en":"The Perodua Kelisa costs less than £4,800, if you’re interested.","zh":"如果你有興趣的話，Perodua Kelisa售價少於4,800英鎊。"},{"en":"If you’re interested is a casual phrase used when offering extra information that someone may want.","zh":"If you’re interested 是提供對方可能想知道的額外資訊時使用的口語片語。"},{"en":"The library has free English classes on Saturday, if you’re interested.","zh":"如果你有興趣的話，圖書館星期六有免費英文課。"},{"en":"If a speaker adds “if you’re interested”, they are not forcing the listener to act.","zh":"如果說話者加上 “if you’re interested”，他不是強迫聽者行動。"},{"en":"This phrase makes a suggestion sound informal and optional.","zh":"這個片語令建議聽起來較隨意和可選。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":5},{"front":"decent vehicles","meaning":"不錯的汽車","examples":[{"en":"There are plenty of decent vehicles available for between £5,000 and £7,000.","zh":"有很多介乎5,000至7,000英鎊的不錯汽車可供購買。"},{"en":"Decent vehicles are acceptable, reliable, and reasonably good cars or transport machines.","zh":"Decent vehicles 是可接受、可靠且相當不錯的汽車或交通工具。"},{"en":"A family may choose a decent vehicle that is safe and affordable rather than stylish.","zh":"家庭可能選擇安全且負擔得起的不錯汽車，而不是時尚汽車。"},{"en":"If decent vehicles are cheap to buy, people may underestimate the later running costs.","zh":"如果不錯的汽車買入價便宜，人們可能低估之後的使用成本。"},{"en":"This phrase means good enough, not luxurious.","zh":"這個片語意思是足夠好，而不是豪華。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":5},{"front":"straight from the showroom","meaning":"直接從陳列室購買","examples":[{"en":"You can buy some decent vehicles straight from the showroom.","zh":"你可以直接從陳列室購買一些不錯的汽車。"},{"en":"Straight from the showroom means directly from the car dealer’s display area, usually as a new vehicle.","zh":"Straight from the showroom 指直接從汽車經銷商的展示區購買，通常是新車。"},{"en":"A driver may feel excited buying a car straight from the showroom.","zh":"駕駛者直接從陳列室買車時可能感到興奮。"},{"en":"If a car comes straight from the showroom, it may cost more than a used one.","zh":"如果汽車直接從陳列室購買，它可能比二手車更貴。"},{"en":"This phrase highlights that the vehicle is bought directly from the seller’s display stock.","zh":"這個片語突顯車輛是直接從賣方展示庫存購買。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":5},{"front":"between £5,000 and £7,000","meaning":"介乎5,000至7,000英鎊之間","examples":[{"en":"Many decent vehicles cost between £5,000 and £7,000.","zh":"許多不錯的汽車售價介乎5,000至7,000英鎊之間。"},{"en":"Between £5,000 and £7,000 means within that price range.","zh":"Between £5,000 and £7,000 指在這個價格範圍內。"},{"en":"A used family car may cost between £5,000 and £7,000 depending on age and condition.","zh":"一輛二手家庭車可能視乎車齡和狀況，售價介乎5,000至7,000英鎊之間。"},{"en":"If a buyer has this budget, they should still consider insurance and repair costs.","zh":"如果買家有這個預算，他仍應考慮保險和維修費。"},{"en":"This phrase gives a lower and upper price limit.","zh":"這個片語提供價格下限和上限。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":5},{"front":"buy second-hand","meaning":"買二手","examples":[{"en":"If you buy second-hand, the prices will be even lower.","zh":"如果你買二手，價格會更低。"},{"en":"To buy second-hand means to buy something that has already been owned or used by someone else.","zh":"To buy second-hand 指購買已被別人擁有或使用過的東西。"},{"en":"A student may buy second-hand textbooks to save money.","zh":"學生可能買二手教科書來省錢。"},{"en":"If you buy a car second-hand, the purchase price may fall but repair risks may rise.","zh":"如果你買二手車，購買價格可能下降，但維修風險可能上升。"},{"en":"This phrase contrasts used goods with brand-new goods.","zh":"這個片語把二手貨與全新貨作對比。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":5},{"front":"falling purchase price","meaning":"不斷下降的購買價格","examples":[{"en":"The falling purchase price of cars hides the real cost of ownership.","zh":"汽車不斷下降的購買價格掩蓋了擁有汽車的真正成本。"},{"en":"Falling purchase price means the amount needed to buy something is decreasing.","zh":"Falling purchase price 指購買某物所需金額正在下降。"},{"en":"The falling purchase price of laptops may make students think they are easy to afford.","zh":"手提電腦不斷下降的購買價格可能令人以為它們容易負擔。"},{"en":"If purchase prices fall, people may ignore maintenance, repair, and service costs.","zh":"如果購買價格下降，人們可能忽視保養、維修和服務成本。"},{"en":"This phrase focuses on the buying price, not the total cost over time.","zh":"這個片語著重買入價格，而不是長期總成本。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":5},{"front":"mask the fact that","meaning":"掩蓋……的事實","examples":[{"en":"The falling purchase price masks the fact that cars are expensive to run.","zh":"不斷下降的購買價格掩蓋了汽車使用成本昂貴的事實。"},{"en":"To mask the fact that means to hide or make people less aware of the truth.","zh":"To mask the fact that 指掩藏真相或令人較難察覺真相。"},{"en":"A low gym joining fee may mask the fact that the monthly payments are expensive.","zh":"低廉健身會入會費可能掩蓋月費昂貴的事實。"},{"en":"If one cost is obvious and low, it can mask the fact that other costs are high.","zh":"如果一項成本明顯且低，它可能掩蓋其他成本高昂的事實。"},{"en":"This phrase shows that one detail hides a more important reality.","zh":"這個片語顯示一個細節隱藏了更重要的現實。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":5},{"front":"own and run a vehicle","meaning":"擁有及使用汽車","examples":[{"en":"It has never been more expensive to own and run a vehicle.","zh":"擁有及使用汽車從未如此昂貴。"},{"en":"To own and run a vehicle means to possess it and pay the costs needed to use it.","zh":"To own and run a vehicle 指擁有車輛，並支付使用它所需的成本。"},{"en":"A driver who owns and runs a car must pay for fuel, insurance, repairs, and parking.","zh":"擁有及使用汽車的駕駛者必須支付燃油、保險、維修和泊車費。"},{"en":"If these costs rise together, it becomes harder to own and run a vehicle.","zh":"如果這些成本一起上升，擁有及使用汽車會變得更困難。"},{"en":"This phrase includes both buying the vehicle and keeping it usable.","zh":"這個片語包括購買車輛和維持它可使用。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":5},{"front":"the estimate is that","meaning":"估計是","examples":[{"en":"The estimate is that the cost of running a car rose sharply last year.","zh":"估計是使用汽車的成本去年急劇上升。"},{"en":"The estimate is that introduces an approximate calculation or informed guess.","zh":"The estimate is that 用來引出近似計算或有根據的估算。"},{"en":"The estimate is that the school trip will cost about £40 per student.","zh":"估計是學校旅行每名學生約需40英鎊。"},{"en":"If exact figures are unavailable, people use estimates to plan budgets.","zh":"如果沒有確切數字，人們會使用估算來安排預算。"},{"en":"This phrase signals that the number may not be exact but is based on available information.","zh":"這個片語表示數字未必精確，但根據現有資訊而來。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":5},{"front":"the cost of running a car","meaning":"使用汽車的成本","examples":[{"en":"The cost of running a car rose by more than ten per cent last year.","zh":"使用汽車的成本去年上升超過百分之十。"},{"en":"The cost of running a car is the money needed to use and maintain a car.","zh":"Cost of running a car 是使用和保養汽車所需的金錢。"},{"en":"Fuel, insurance, servicing, repairs, and parking are all part of the cost of running a car.","zh":"燃油、保險、保養、維修和泊車費都是使用汽車成本的一部分。"},{"en":"If these expenses rise, the cost of running a car becomes harder for families to manage.","zh":"如果這些開支上升，使用汽車的成本會令家庭更難應付。"},{"en":"This phrase refers to ongoing costs, not just the purchase price.","zh":"這個片語指持續成本，而不只是購買價格。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":6},{"front":"rise by more than","meaning":"上升超過","examples":[{"en":"The cost of running a car rose by more than ten per cent.","zh":"使用汽車的成本上升超過百分之十。"},{"en":"To rise by more than a certain amount means to increase beyond that level.","zh":"To rise by more than a certain amount 指增加幅度超過某水平。"},{"en":"Rent may rise by more than 5% if demand for housing is high.","zh":"如果住屋需求高，租金可能上升超過5%。"},{"en":"If travel costs rise by more than wages, commuting becomes less affordable.","zh":"如果交通成本上升幅度超過工資，通勤會變得較難負擔。"},{"en":"This phrase gives the size of an increase.","zh":"這個片語指出增加幅度。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":6},{"front":"last year alone","meaning":"單是去年","examples":[{"en":"The cost of running a car rose sharply last year alone.","zh":"單是去年，使用汽車的成本就急劇上升。"},{"en":"Last year alone means in only that one year, without counting other years.","zh":"Last year alone 指只在那一年內，不包括其他年份。"},{"en":"The shop gained 500 new customers last year alone.","zh":"單是去年，這間商店就增加了500名新顧客。"},{"en":"If costs rose sharply last year alone, the recent pressure on drivers is serious.","zh":"如果單是去年成本就急劇上升，駕駛者最近面對的壓力很大。"},{"en":"This phrase emphasises that a change happened within a short, specific period.","zh":"這個片語強調變化發生在短而特定的時間內。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":6},{"front":"the annual cost of","meaning":"……的每年成本","examples":[{"en":"The annual cost of running your own vehicle is estimated at £5,539.","zh":"使用自己車輛的每年成本估計為5,539英鎊。"},{"en":"The annual cost of something is the total amount paid for it in one year.","zh":"Annual cost of something 是一年內為某事支付的總金額。"},{"en":"The annual cost of a phone plan includes twelve months of payments.","zh":"手機月費計劃的每年成本包括十二個月的付款。"},{"en":"If the annual cost of owning a car is high, cheaper transport may be attractive.","zh":"如果擁有汽車的每年成本很高，較便宜交通可能吸引人。"},{"en":"This phrase helps people compare yearly expenses.","zh":"這個片語幫助人們比較年度開支。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":6},{"front":"be put at","meaning":"被估計為","examples":[{"en":"The annual cost of running a vehicle is put at an average of £5,539.","zh":"使用車輛的每年成本被估計為平均5,539英鎊。"},{"en":"To be put at a figure means to be estimated or stated as that amount.","zh":"To be put at a figure 指被估計或陳述為某金額。"},{"en":"The cost of repairing the roof was put at £2,000.","zh":"屋頂維修費被估計為2,000英鎊。"},{"en":"If a cost is put at a high figure, people may rethink whether the purchase is worthwhile.","zh":"如果成本被估計為很高，人們可能重新考慮購買是否值得。"},{"en":"This phrase is often used when reporting estimates.","zh":"這個片語常用於報告估算。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":6},{"front":"an average of","meaning":"平均","examples":[{"en":"The weekly cost is an average of £107.","zh":"每週成本平均為107英鎊。"},{"en":"An average of a number means the typical amount calculated from several cases.","zh":"An average of a number 指由多個情況計算出的典型數量。"},{"en":"The class reads an average of two books each month.","zh":"這個班平均每月閱讀兩本書。"},{"en":"If drivers spend an average of £107 a week, some will spend less and some more.","zh":"如果駕駛者平均每週花107英鎊，有些人會花得較少，有些會較多。"},{"en":"This phrase gives a typical figure, not every individual case.","zh":"這個片語提供典型數字，而不是每個個別情況。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":6},{"front":"average mileage","meaning":"平均行車里數","examples":[{"en":"Drivers who do less than the average mileage spend less on some costs.","zh":"行車里數低於平均行車里數的駕駛者，在某些成本上花費較少。"},{"en":"Average mileage is the typical distance driven by drivers over a certain period.","zh":"Average mileage 是駕駛者在某段時間內行駛的典型距離。"},{"en":"A delivery driver usually has higher mileage than someone who drives only at weekends.","zh":"送貨司機的行車里數通常高於只在週末駕車的人。"},{"en":"If your mileage is below average, your fuel costs may be lower.","zh":"如果你的行車里數低於平均水平，燃油成本可能較低。"},{"en":"This phrase helps compare how much different people drive.","zh":"這個片語幫助比較不同人駕車多少。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":6},{"front":"correspondingly less or more","meaning":"相應地較少或較多","examples":[{"en":"Drivers with different mileage will spend correspondingly less or more.","zh":"行車里數不同的駕駛者會相應地花較少或較多。"},{"en":"Correspondingly less or more means lower or higher in a way that matches another difference.","zh":"Correspondingly less or more 指隨着另一差異而相應變低或變高。"},{"en":"If a student takes fewer classes, the fee may be correspondingly less.","zh":"如果學生修讀較少課堂，費用可能相應地較少。"},{"en":"If someone drives twice as far, their fuel cost may be correspondingly more.","zh":"如果某人駕駛距離多一倍，燃油成本可能相應地較多。"},{"en":"This phrase shows that one amount changes in relation to another.","zh":"這個片語顯示一個數量會跟另一個因素相應改變。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":6},{"front":"car ownership","meaning":"汽車擁有權；擁有汽車","examples":[{"en":"Many of the costs of car ownership are fixed.","zh":"擁有汽車的許多成本是固定的。"},{"en":"Car ownership means having and being responsible for a car.","zh":"Car ownership 指擁有汽車並對它負責。"},{"en":"Car ownership may feel convenient, but it includes insurance, repairs, and loss of value.","zh":"擁有汽車可能感覺方便，但它包括保險、維修和價值損失。"},{"en":"If car ownership becomes expensive, people may turn to car clubs or public transport.","zh":"如果擁有汽車變得昂貴，人們可能轉向汽車共享會或公共交通。"},{"en":"This phrase focuses on the responsibilities and costs of having a car.","zh":"這個片語著重擁有汽車的責任和成本。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":6},{"front":"fixed costs","meaning":"固定成本","examples":[{"en":"Many fixed costs of car ownership are unavoidable.","zh":"擁有汽車的許多固定成本無法避免。"},{"en":"Fixed costs are expenses that stay broadly the same even if you use something less.","zh":"Fixed costs 是即使你較少使用某物也大致不變的開支。"},{"en":"A shop’s rent is a fixed cost because it must be paid even when sales are low.","zh":"商店租金是固定成本，因為即使銷售低也必須支付。"},{"en":"Insurance is a fixed cost for many drivers because it does not change much with mileage.","zh":"對許多駕駛者來說，保險是固定成本，因為它不太隨行車里數改變。"},{"en":"This phrase contrasts with variable costs such as fuel.","zh":"這個片語與燃油等可變成本形成對比。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":6},{"front":"unavoidable","meaning":"無法避免的","examples":[{"en":"Many costs of car ownership are fixed and therefore unavoidable.","zh":"擁有汽車的許多成本是固定的，因此無法避免。"},{"en":"Unavoidable means impossible or very difficult to avoid.","zh":"Unavoidable 指不可能或很難避免。"},{"en":"School exam fees may be unavoidable if students want to enter the exam.","zh":"如果學生想參加考試，考試費可能無法避免。"},{"en":"If insurance is legally required, that cost is unavoidable for car owners.","zh":"如果法律規定必須有保險，這項成本對車主來說就是無法避免的。"},{"en":"This word describes something people must face even if they dislike it.","zh":"這個詞描述人們即使不喜歡也必須面對的事。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":7},{"front":"depreciation","meaning":"折舊","examples":[{"en":"Depreciation is one of the biggest costs of owning a car.","zh":"折舊是擁有汽車的最大成本之一。"},{"en":"Depreciation is the loss in value of something over time.","zh":"Depreciation 是某物隨時間流逝而價值下降。"},{"en":"A new phone suffers depreciation as soon as newer models appear.","zh":"當更新型號出現，全新手機就會出現折舊。"},{"en":"If a car loses value every year, depreciation can cost the owner thousands.","zh":"如果汽車每年失去價值，折舊可以令車主損失數千英鎊。"},{"en":"This word explains why a cheap-looking purchase can still lose money.","zh":"這個詞解釋為何看似便宜的購買仍可能損失金錢。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":7},{"front":"lose a large chunk of","meaning":"失去很大一部分……","examples":[{"en":"Your vehicle loses a large chunk of its resale value each year.","zh":"你的車輛每年都失去很大一部分轉售價值。"},{"en":"To lose a large chunk of something means to lose a big part of it.","zh":"To lose a large chunk of something 指失去某物很大一部分。"},{"en":"A student may lose a large chunk of study time if they keep checking their phone.","zh":"如果學生不停查看手機，可能失去很大一部分溫習時間。"},{"en":"If a car loses a large chunk of its value, selling it later brings back much less money.","zh":"如果汽車失去很大一部分價值，日後出售時收回的錢會少得多。"},{"en":"This phrase stresses a large and noticeable loss.","zh":"這個片語強調重大而明顯的損失。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":7},{"front":"resale value","meaning":"轉售價值","examples":[{"en":"A vehicle loses much of its resale value each year.","zh":"車輛每年都失去大量轉售價值。"},{"en":"Resale value is the amount of money something can be sold for after it has been used.","zh":"Resale value 是某物使用後可以出售的金額。"},{"en":"A well-kept laptop may have a higher resale value than a damaged one.","zh":"保養良好的手提電腦可能比損壞的手提電腦有更高轉售價值。"},{"en":"If resale value falls quickly, ownership becomes more expensive overall.","zh":"如果轉售價值快速下降，整體擁有成本會更高。"},{"en":"This phrase helps explain depreciation.","zh":"這個片語幫助解釋折舊。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":7},{"front":"account for","meaning":"佔；構成","examples":[{"en":"Depreciation accounts for £2,420 a year.","zh":"折舊每年佔2,420英鎊。"},{"en":"To account for an amount means to make up that part of the total.","zh":"To account for an amount 指構成總數中的該部分。"},{"en":"Rent may account for half of a student’s monthly spending.","zh":"租金可能佔學生每月開支的一半。"},{"en":"If depreciation accounts for a large share of car costs, fuel is not the main expense.","zh":"如果折舊佔汽車成本很大部分，燃油就不是主要開支。"},{"en":"This phrase explains how much one part contributes to a total.","zh":"這個片語解釋某部分對總數的貢獻有多大。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":7},{"front":"finance packages","meaning":"分期付款計劃；融資方案","examples":[{"en":"Finance packages add to the annual cost of owning a car.","zh":"分期付款計劃增加擁有汽車的每年成本。"},{"en":"Finance packages are payment plans that allow people to buy something by borrowing or paying over time.","zh":"Finance packages 是讓人透過借款或分期付款購買某物的付款計劃。"},{"en":"A buyer may use a finance package to spread the cost of a new car across several years.","zh":"買家可能使用融資方案，把新車成本分攤到數年。"},{"en":"If interest is high, finance packages can make the total cost much larger.","zh":"如果利息高，分期付款計劃可以令總成本大得多。"},{"en":"This phrase refers to borrowing arrangements linked to purchases.","zh":"這個片語指與購買相關的借貸安排。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":7},{"front":"resort to","meaning":"訴諸；依靠","examples":[{"en":"Most people have to resort to finance packages to buy a new car.","zh":"大多數人不得不依靠分期付款計劃來購買新車。"},{"en":"To resort to something means to use it because other choices are difficult or unavailable.","zh":"To resort to something 指因其他選擇困難或不可得而使用某方法。"},{"en":"A student may resort to taking a taxi if the last bus has already left.","zh":"如果尾班巴士已開出，學生可能被迫坐的士。"},{"en":"If people cannot pay for a car in cash, they may resort to borrowing.","zh":"如果人們不能用現金買車，他們可能依靠借貸。"},{"en":"This phrase often suggests using a less ideal but necessary option.","zh":"這個片語常暗示使用一個不太理想但必要的選擇。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":7},{"front":"in order to","meaning":"為了","examples":[{"en":"Many buyers use finance packages in order to pay for part of a new car.","zh":"許多買家使用分期付款計劃，為了支付新車的部分費用。"},{"en":"In order to means for the purpose of doing something.","zh":"In order to 指為了做某事。"},{"en":"Students save money in order to buy books for the new term.","zh":"學生儲錢是為了購買新學期的書本。"},{"en":"If someone borrows money in order to buy a car, the loan becomes part of the real cost.","zh":"如果某人為了買車而借錢，貸款就成為真正成本的一部分。"},{"en":"This phrase connects an action with its purpose.","zh":"這個片語把行動與目的連接起來。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":7},{"front":"at least part of","meaning":"至少一部分","examples":[{"en":"Most people borrow money to pay for at least part of a new car.","zh":"大多數人借錢支付新車至少一部分費用。"},{"en":"At least part of something means some portion of it, even if not the whole amount.","zh":"At least part of something 指某事物的一部分，即使不是全部。"},{"en":"A student may understand at least part of a difficult article after reading the introduction.","zh":"學生閱讀引言後，可能至少理解困難文章的一部分。"},{"en":"If buyers finance at least part of a car, they must consider interest payments.","zh":"如果買家為汽車至少一部分費用融資，他們必須考慮利息付款。"},{"en":"This phrase shows a minimum portion.","zh":"這個片語顯示最低限度的一部分。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":7},{"front":"insurance","meaning":"保險","examples":[{"en":"Insurance is one of the fixed costs of owning a car.","zh":"保險是擁有汽車的固定成本之一。"},{"en":"Insurance is an agreement in which a company helps pay for loss, damage, or accidents in return for regular payments.","zh":"Insurance 是一種協議，公司收取定期付款，並在損失、損壞或意外時幫忙支付費用。"},{"en":"Drivers need car insurance so that accidents do not create impossible costs.","zh":"駕駛者需要汽車保險，令意外不會造成無法承擔的成本。"},{"en":"If insurance prices rise, car ownership becomes more expensive even before fuel is considered.","zh":"如果保險價格上升，即使未計燃油，擁有汽車也會更昂貴。"},{"en":"This word refers to financial protection against risk.","zh":"這個詞指針對風險的財政保障。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":7},{"front":"maintenance","meaning":"保養；維修","examples":[{"en":"Maintenance costs are part of the expense of running a car.","zh":"保養成本是使用汽車開支的一部分。"},{"en":"Maintenance means work done to keep something in good condition.","zh":"Maintenance 指為保持某物良好狀態而進行的工作。"},{"en":"A bicycle needs maintenance such as brake checks and tyre repairs.","zh":"單車需要保養，例如檢查煞車和修補車胎。"},{"en":"If car maintenance is ignored, small problems may become expensive repairs.","zh":"如果忽視汽車保養，小問題可能變成昂貴維修。"},{"en":"This word refers to regular care, not only emergency repair.","zh":"這個詞指定期照顧，而不只是緊急維修。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":8},{"front":"breakdown insurance","meaning":"拋錨保險","examples":[{"en":"Breakdown insurance costs about the same however many miles you drive.","zh":"不論你駕駛多少里數，拋錨保險成本都差不多。"},{"en":"Breakdown insurance is cover that helps drivers when their vehicle stops working.","zh":"Breakdown insurance 是在車輛停止運作時幫助駕駛者的保障。"},{"en":"A driver with breakdown insurance can call for help if the car breaks down on a motorway.","zh":"有拋錨保險的駕駛者，如果汽車在高速公路拋錨，可以致電求助。"},{"en":"Because breakdown insurance is often fixed, driving less may not reduce this cost much.","zh":"因為拋錨保險通常是固定成本，少駕車未必能大幅降低這項費用。"},{"en":"This phrase refers to protection against car failure.","zh":"這個片語指針對汽車故障的保障。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":8},{"front":"broadly the same amount","meaning":"大致相同的金額","examples":[{"en":"These fixed costs will be broadly the same amount for most drivers.","zh":"對大多數駕駛者來說，這些固定成本會是大致相同的金額。"},{"en":"Broadly the same amount means roughly equal, though not exactly identical.","zh":"Broadly the same amount 指大約相等，雖然不是完全一樣。"},{"en":"Two students may spend broadly the same amount on lunch each week.","zh":"兩名學生每星期花在午餐上的金額可能大致相同。"},{"en":"If insurance stays broadly the same amount, driving fewer miles will not greatly reduce it.","zh":"如果保險保持大致相同的金額，少駕駛里數不會大幅減少它。"},{"en":"This phrase describes approximate equality.","zh":"這個片語描述近似相等。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":8},{"front":"however many miles you do","meaning":"不論你駕駛多少里數","examples":[{"en":"Insurance costs remain similar however many miles you do.","zh":"不論你駕駛多少里數，保險成本都保持相似。"},{"en":"However many miles you do means no matter how far you drive.","zh":"However many miles you do 指不論你駕駛多遠。"},{"en":"A monthly gym fee stays the same however many times you go.","zh":"不論你去多少次，健身室月費都一樣。"},{"en":"If a cost stays the same however many miles you do, it is not affected much by usage.","zh":"如果一項成本不論你駕駛多少里數都一樣，它就不太受使用量影響。"},{"en":"This phrase emphasises that distance does not change the cost.","zh":"這個片語強調距離不改變成本。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":8},{"front":"truly variable","meaning":"真正可變的","examples":[{"en":"Only fuel costs are truly variable.","zh":"只有燃油成本是真正可變的。"},{"en":"Truly variable means really changing according to how much something is used.","zh":"Truly variable 指真正會根據某物使用量而改變。"},{"en":"Electricity bills are truly variable if they rise when a family uses more power.","zh":"如果家庭用電越多，電費就越高，電費就是真正可變的。"},{"en":"Fuel is truly variable because driving more miles usually means buying more petrol.","zh":"燃油是真正可變的，因為駕駛里數越多通常代表要買更多汽油。"},{"en":"This phrase contrasts changing costs with fixed costs.","zh":"這個片語把可變成本與固定成本作對比。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":8},{"front":"petrol prices","meaning":"汽油價格","examples":[{"en":"Petrol prices are the most visible indicator of car-running costs.","zh":"汽油價格是使用汽車成本最明顯的指標。"},{"en":"Petrol prices are the amounts people pay for fuel used in cars.","zh":"Petrol prices 是人們為汽車燃油支付的金額。"},{"en":"Drivers often notice petrol prices first because they pay at the pump regularly.","zh":"駕駛者通常最先注意汽油價格，因為他們定期在油站付款。"},{"en":"If petrol prices rise, some people may drive less or use buses more often.","zh":"如果汽油價格上升，有些人可能少駕車或更常使用巴士。"},{"en":"This phrase refers to a common but not complete measure of car costs.","zh":"這個片語指汽車成本中常見但不完整的衡量方式。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":8},{"front":"the most visible indicator of","meaning":"……最明顯的指標","examples":[{"en":"Petrol prices are the most visible indicator of the cost of running a car.","zh":"汽油價格是使用汽車成本最明顯的指標。"},{"en":"The most visible indicator of something is the sign people notice most easily.","zh":"The most visible indicator of something 是人們最容易注意到的徵象。"},{"en":"Empty shelves are the most visible indicator of a supply problem in a supermarket.","zh":"空貨架是超級市場供應問題最明顯的指標。"},{"en":"If petrol prices rise, they become a visible sign of higher driving costs.","zh":"如果汽油價格上升，它們會成為駕車成本上升的明顯徵象。"},{"en":"This phrase refers to what is easiest to see, not necessarily what is most important.","zh":"這個片語指最容易看見的東西，而不一定是最重要的東西。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":8},{"front":"the typical driver","meaning":"典型駕駛者；一般駕駛者","examples":[{"en":"Fuel costs are not the biggest expense for the typical driver.","zh":"對一般駕駛者來說，燃油成本不是最大開支。"},{"en":"The typical driver means an ordinary or average driver, not an unusual case.","zh":"Typical driver 指普通或平均駕駛者，而不是特殊例子。"},{"en":"The typical driver uses a car for work, shopping, family visits, and short trips.","zh":"一般駕駛者使用汽車上班、購物、探親和短途出行。"},{"en":"If the typical driver focuses only on petrol, they may miss hidden ownership costs.","zh":"如果一般駕駛者只留意汽油，可能忽略隱藏的擁有成本。"},{"en":"This phrase describes the common driver used for comparison.","zh":"這個片語描述用於比較的常見駕駛者。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":8},{"front":"account for less than","meaning":"佔少於","examples":[{"en":"Fuel costs account for less than one-fifth of the real costs.","zh":"燃油成本佔真正成本少於五分之一。"},{"en":"To account for less than a share means to make up a smaller portion than that.","zh":"To account for less than a share 指構成的比例少於該部分。"},{"en":"Snacks may account for less than 10% of a family’s food budget.","zh":"零食可能佔家庭食物預算少於10%。"},{"en":"If fuel accounts for less than one-fifth of car costs, other costs are more important.","zh":"如果燃油佔汽車成本少於五分之一，其他成本就更重要。"},{"en":"This phrase helps compare one part with the whole.","zh":"這個片語幫助比較部分與整體。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":8},{"front":"one-fifth of","meaning":"五分之一","examples":[{"en":"Fuel accounts for less than one-fifth of the real cost of running a car.","zh":"燃油佔使用汽車真正成本少於五分之一。"},{"en":"One-fifth of something means one part out of five equal parts, or 20%.","zh":"One-fifth of something 指五等份中的一份，即20%。"},{"en":"If a class has 25 students, one-fifth of the class is five students.","zh":"如果一個班有25名學生，五分之一就是5名學生。"},{"en":"If fuel is only one-fifth of car costs, reducing mileage may not remove most expenses.","zh":"如果燃油只是汽車成本的五分之一，減少行車里數未必能消除大部分開支。"},{"en":"This phrase gives a simple fraction.","zh":"這個片語提供一個簡單分數。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":8},{"front":"in other words","meaning":"換句話說","examples":[{"en":"In other words, giving up your car can make financial sense.","zh":"換句話說，放棄汽車可以在財政上合理。"},{"en":"In other words introduces the same idea in a clearer or simpler way.","zh":"In other words 用來以更清楚或更簡單的方式重新表達同一想法。"},{"en":"The bus is cheaper, cleaner, and faster; in other words, it is the better choice.","zh":"巴士更便宜、更清潔、更快捷；換句話說，它是更好的選擇。"},{"en":"If a writer uses “in other words”, they are helping readers understand the point again.","zh":"如果作者使用 “in other words”，他是在幫助讀者再次理解重點。"},{"en":"This phrase is useful for explaining a conclusion more directly.","zh":"這個片語適合更直接地解釋結論。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":9},{"front":"leaving aside","meaning":"撇開……不談","examples":[{"en":"Leaving aside practical barriers, giving up a car may save money.","zh":"撇開實際障礙不談，放棄汽車可能省錢。"},{"en":"Leaving aside something means not discussing it for the moment.","zh":"Leaving aside something 指暫時不討論某事。"},{"en":"Leaving aside the weather, the picnic plan is simple and cheap.","zh":"撇開天氣不談，野餐計劃簡單又便宜。"},{"en":"If we leave aside emotional attachment to cars, the financial argument may look clearer.","zh":"如果撇開對汽車的情感依附不談，財政論點可能更清晰。"},{"en":"This phrase temporarily removes one issue so another can be considered.","zh":"這個片語暫時移除一個議題，以便考慮另一個。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":9},{"front":"practical and psychological barriers","meaning":"實際及心理障礙","examples":[{"en":"There are practical and psychological barriers to giving up a car.","zh":"放棄汽車有實際及心理障礙。"},{"en":"Practical and psychological barriers are real-life difficulties and mental or emotional obstacles.","zh":"Practical and psychological barriers 是現實生活困難，以及心理或情感上的障礙。"},{"en":"Poor bus service is a practical barrier, while fear of losing freedom is a psychological barrier.","zh":"巴士服務差是實際障礙，而害怕失去自由是心理障礙。"},{"en":"If both types of barriers exist, people may keep driving even when it costs more.","zh":"如果兩種障礙都存在，即使成本較高，人們仍可能繼續駕車。"},{"en":"This phrase separates external problems from inner resistance.","zh":"這個片語把外在問題與內心抗拒分開。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":9},{"front":"financial terms","meaning":"從財政角度來說","examples":[{"en":"In financial terms, giving up a car makes sense for many people.","zh":"從財政角度來說，對許多人而言放棄汽車是合理的。"},{"en":"In financial terms means when considered from the point of view of money.","zh":"In financial terms 指從金錢角度考慮。"},{"en":"In financial terms, sharing a flat may be better than renting alone.","zh":"從財政角度來說，與人合租單位可能比獨自租住更好。"},{"en":"If a choice saves thousands each year, it may be wise in financial terms.","zh":"如果一個選擇每年節省數千元，從財政角度來說它可能明智。"},{"en":"This phrase focuses on cost, not comfort or emotion.","zh":"這個片語著重成本，而不是舒適或情感。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":9},{"front":"doing so makes sense","meaning":"這樣做是合理的","examples":[{"en":"For many people, giving up a car makes sense.","zh":"對許多人來說，放棄汽車是合理的。"},{"en":"Doing so makes sense means that taking that action is reasonable or sensible.","zh":"Doing so makes sense 指採取該行動是合理或明智的。"},{"en":"If a student lives near school, walking there makes sense.","zh":"如果學生住近學校，步行上學是合理的。"},{"en":"If car costs are higher than transport needs, giving it up makes sense.","zh":"如果汽車成本高於出行需要，放棄它是合理的。"},{"en":"This phrase judges an action as practical or logical.","zh":"這個片語把某行動判斷為實際或合乎邏輯。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":9},{"front":"public transport","meaning":"公共交通","examples":[{"en":"The cost of public transport may be much lower than the cost of owning a car.","zh":"公共交通的成本可能遠低於擁有汽車的成本。"},{"en":"Public transport is transport used by the public, such as buses, trains, trams, and underground systems.","zh":"Public transport 是公眾使用的交通，例如巴士、火車、電車和地鐵系統。"},{"en":"Many workers use public transport because parking near the office is expensive.","zh":"許多上班族使用公共交通，因為辦公室附近泊車昂貴。"},{"en":"If public transport is reliable, fewer people may need private cars.","zh":"如果公共交通可靠，較少人可能需要私家車。"},{"en":"This phrase refers to shared transport services, not private vehicles.","zh":"這個片語指共享交通服務，而不是私人車輛。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":9},{"front":"for example","meaning":"例如","examples":[{"en":"Take the cost of public transport, for example.","zh":"以公共交通的成本為例。"},{"en":"For example introduces a specific case that explains or supports a point.","zh":"For example 用來引出解釋或支持某重點的具體例子。"},{"en":"Some daily costs are easy to reduce; for example, you can bring lunch from home.","zh":"有些日常開支容易減少；例如，你可以從家中帶午餐。"},{"en":"If a writer gives an example, readers can understand the general idea more clearly.","zh":"如果作者給出例子，讀者可以更清楚理解一般想法。"},{"en":"This phrase signals that a concrete illustration is coming.","zh":"這個片語標示接下來會有具體說明。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":9},{"front":"annual Travelcard","meaning":"全年Travelcard交通卡","examples":[{"en":"The most expensive annual Travelcard in London costs just over £1,700.","zh":"倫敦最昂貴的全年Travelcard交通卡售價剛超過1,700英鎊。"},{"en":"An annual Travelcard is a transport pass that allows travel for one year.","zh":"Annual Travelcard 是允許一年內乘搭交通工具的交通卡。"},{"en":"A commuter may buy an annual Travelcard to avoid paying for tickets every day.","zh":"通勤者可能購買全年Travelcard交通卡，以避免每天買票。"},{"en":"If an annual Travelcard is cheaper than running a car, it may help people save money.","zh":"如果全年Travelcard交通卡比使用汽車便宜，它可能幫助人們省錢。"},{"en":"This phrase names a yearly public-transport ticket.","zh":"這個片語命名一種全年公共交通車票。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":9},{"front":"allow travel in any zone","meaning":"允許在任何區域乘搭交通工具","examples":[{"en":"The annual Travelcard allows travel in any zone at any time.","zh":"全年Travelcard交通卡允許在任何區域、任何時間乘搭交通工具。"},{"en":"To allow travel in any zone means to permit passengers to use transport across all fare areas.","zh":"To allow travel in any zone 指准許乘客在所有收費區域使用交通工具。"},{"en":"A student pass may allow travel in any zone so students can reach school and activities.","zh":"學生證可能允許在任何區域乘車，讓學生到達學校和活動地點。"},{"en":"If a ticket allows travel in any zone, users do not need to buy separate tickets for different areas.","zh":"如果車票允許在任何區域乘車，使用者不需要為不同區域購買額外車票。"},{"en":"This phrase describes the coverage of a transport ticket.","zh":"這個片語描述交通票的覆蓋範圍。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":9},{"front":"at any time","meaning":"在任何時間","examples":[{"en":"The Travelcard allows travel in any zone at any time.","zh":"Travelcard交通卡允許在任何區域、任何時間乘搭交通工具。"},{"en":"At any time means whenever someone chooses, without time restrictions.","zh":"At any time 指無時間限制，在某人選擇的任何時候。"},{"en":"A library card may let students borrow books at any time during opening hours.","zh":"圖書證可能讓學生在開放時間內任何時間借書。"},{"en":"If a transport pass can be used at any time, it is more flexible for commuters.","zh":"如果交通卡可以在任何時間使用，它對通勤者更有彈性。"},{"en":"This phrase shows freedom from a fixed schedule.","zh":"這個片語顯示不受固定時間表限制。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":9},{"front":"just over","meaning":"剛超過","examples":[{"en":"The most expensive annual Travelcard costs just over £1,700.","zh":"最昂貴的全年Travelcard交通卡售價剛超過1,700英鎊。"},{"en":"Just over means slightly more than a stated amount.","zh":"Just over 指略高於某個數量。"},{"en":"The meeting lasted just over an hour.","zh":"會議持續剛超過一小時。"},{"en":"If a ticket costs just over £1,700, the price is a little higher than £1,700.","zh":"如果車票售價剛超過1,700英鎊，價格就是稍高於1,700英鎊。"},{"en":"This phrase gives an approximate amount above a number.","zh":"這個片語提供高於某數字的近似數量。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":10},{"front":"have thousands of pounds to spare","meaning":"尚有數千英鎊剩餘","examples":[{"en":"You could give up your car and still have thousands of pounds to spare.","zh":"你可以放棄汽車，仍尚有數千英鎊剩餘。"},{"en":"To have thousands of pounds to spare means to have a large amount of money left after paying necessary costs.","zh":"To have thousands of pounds to spare 指支付必要成本後仍有大量金錢剩下。"},{"en":"A family may have money to spare if they cancel an expensive unused membership.","zh":"如果家庭取消昂貴而未使用的會籍，可能會有錢剩餘。"},{"en":"If public transport costs much less than car ownership, former drivers may have thousands left.","zh":"如果公共交通成本遠低於擁有汽車，前駕駛者可能尚有數千英鎊剩餘。"},{"en":"This phrase emphasises saving more than is needed for the alternative.","zh":"這個片語強調節省的金額多於替代方案所需。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":10},{"front":"spend on","meaning":"花在……上","examples":[{"en":"You would have money to spend on occasional car hire.","zh":"你會有錢花在偶爾租車上。"},{"en":"To spend money on something means to use money to pay for it.","zh":"To spend money on something 指用金錢支付某物。"},{"en":"A student may spend money on books instead of snacks.","zh":"學生可能把錢花在書本上，而不是零食上。"},{"en":"If you save money by not owning a car, you can spend some on transport only when needed.","zh":"如果你因不擁有汽車而省錢，就可以只在需要時把部分錢花在交通上。"},{"en":"This phrase connects money with its purpose.","zh":"這個片語把金錢與用途連接起來。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":10},{"front":"occasional car hire","meaning":"偶爾租車","examples":[{"en":"Drivers could use occasional car hire instead of owning a car.","zh":"駕駛者可以偶爾租車，而不是擁有汽車。"},{"en":"Occasional car hire means renting a car only sometimes, when it is needed.","zh":"Occasional car hire 指只在有需要時偶爾租用汽車。"},{"en":"A family may use occasional car hire for a weekend trip but take buses during the week.","zh":"家庭可能在週末旅行時偶爾租車，但平日乘搭巴士。"},{"en":"If car hire is only occasional, the total yearly cost may be lower than ownership.","zh":"如果只是偶爾租車，每年總成本可能低於擁有汽車。"},{"en":"This phrase describes temporary car use rather than permanent ownership.","zh":"這個片語描述臨時用車，而不是永久擁有。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":10},{"front":"assuming that","meaning":"假設","examples":[{"en":"Assuming that you buy the most expensive Travelcard, you could still save money.","zh":"假設你購買最昂貴的Travelcard交通卡，你仍可以省錢。"},{"en":"Assuming that means if we accept something as true for the purpose of calculation or argument.","zh":"Assuming that 指為了計算或論證而先接受某事為真。"},{"en":"Assuming that lunch costs £8 a day, bringing food from home can save a lot each month.","zh":"假設午餐每天花8英鎊，從家中帶飯每月可以省很多錢。"},{"en":"If we assume the most expensive case and still save money, the argument becomes stronger.","zh":"如果我們假設最昂貴情況仍能省錢，論點就變得更強。"},{"en":"This phrase introduces a condition used for reasoning.","zh":"這個片語引入用於推理的條件。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":10},{"front":"hire a cheap car","meaning":"租用便宜汽車","examples":[{"en":"You could hire a cheap car for about 30 weeks a year.","zh":"你可以一年約30星期租用便宜汽車。"},{"en":"To hire a cheap car means to rent a low-cost car for temporary use.","zh":"To hire a cheap car 指臨時租用低成本汽車。"},{"en":"A couple may hire a cheap car for moving furniture instead of buying a van.","zh":"情侶可能租用便宜汽車搬家具，而不是購買客貨車。"},{"en":"If you hire a cheap car only when needed, you avoid many fixed ownership costs.","zh":"如果你只在需要時租用便宜汽車，就能避免許多固定擁有成本。"},{"en":"This phrase describes renting an affordable vehicle for a limited time.","zh":"這個片語描述在有限時間內租用可負擔車輛。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":10},{"front":"about 30 weeks a year","meaning":"一年約30星期","examples":[{"en":"You could hire a cheap car for about 30 weeks a year.","zh":"你可以一年約30星期租用便宜汽車。"},{"en":"About 30 weeks a year means roughly thirty weeks within one year.","zh":"About 30 weeks a year 指一年中大約三十星期。"},{"en":"A part-time worker may work about 30 weeks a year if the job is seasonal.","zh":"如果工作是季節性的，兼職員工可能一年約工作30星期。"},{"en":"If you can rent a car for about 30 weeks and still save money, ownership may be unnecessary.","zh":"如果你一年約30星期租車仍能省錢，擁有汽車可能並非必要。"},{"en":"This phrase gives an approximate yearly duration.","zh":"這個片語提供近似年度時長。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":10},{"front":"be better off overall","meaning":"整體上更划算","examples":[{"en":"You could still be better off overall than if you owned your own car.","zh":"與擁有自己的汽車相比，你整體上仍可能更划算。"},{"en":"To be better off overall means to be in a better total situation after considering all costs and benefits.","zh":"To be better off overall 指在考慮所有成本和好處後，整體處境更好。"},{"en":"A student may be better off overall by working fewer hours and sleeping more.","zh":"學生減少工作時間並睡更多，整體上可能更好。"},{"en":"If public transport plus car hire costs less than ownership, you are better off overall.","zh":"如果公共交通加租車成本低於擁有汽車，你整體上就更划算。"},{"en":"This phrase looks at the whole picture, not one single cost.","zh":"這個片語看整體情況，而不是單一成本。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":10},{"front":"not necessarily","meaning":"未必；不一定","examples":[{"en":"Car hire is not necessarily the most cost-effective option.","zh":"租車未必是最具成本效益的選擇。"},{"en":"Not necessarily means not always or not in every case.","zh":"Not necessarily 指不總是或不在每種情況下都是如此。"},{"en":"The cheapest phone is not necessarily the best choice if it breaks easily.","zh":"如果最便宜手機容易壞，它未必是最佳選擇。"},{"en":"If car hire is expensive in your area, it is not necessarily cheaper than a car club.","zh":"如果你所在地區租車很貴，它未必比汽車共享會便宜。"},{"en":"This phrase warns that a statement may be true only in some situations.","zh":"這個片語提醒某說法可能只在某些情況下成立。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":10},{"front":"the most cost-effective option","meaning":"最具成本效益的選擇","examples":[{"en":"Car hire is not necessarily the most cost-effective option.","zh":"租車未必是最具成本效益的選擇。"},{"en":"The most cost-effective option is the choice that gives the best value for the money spent.","zh":"The most cost-effective option 是花費金錢後最物有所值的選擇。"},{"en":"Buying a monthly pass may be the most cost-effective option for daily commuters.","zh":"對每日通勤者來說，購買月票可能是最具成本效益的選擇。"},{"en":"If a person drives only twice a week, a car club may be more cost-effective than ownership.","zh":"如果一個人每星期只駕車兩次，汽車共享會可能比擁有汽車更具成本效益。"},{"en":"This phrase compares value, not just the lowest price.","zh":"這個片語比較價值，而不只是最低價格。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":10},{"front":"be prepared to","meaning":"願意","examples":[{"en":"Some people are prepared to do without a car.","zh":"有些人願意沒有汽車也能應付。"},{"en":"To be prepared to do something means to be willing and ready to do it.","zh":"To be prepared to do something 指願意並準備好做某事。"},{"en":"A student may be prepared to wake up earlier to catch a cheaper bus.","zh":"學生可能願意早起，以乘搭較便宜的巴士。"},{"en":"If people are prepared to change habits, they may save money and reduce pollution.","zh":"如果人們願意改變習慣，他們可能省錢並減少污染。"},{"en":"This phrase shows willingness to accept effort or inconvenience.","zh":"這個片語顯示願意接受努力或不便。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":11},{"front":"do without","meaning":"沒有……也能應付","examples":[{"en":"Some people are prepared to do without a car.","zh":"有些人願意沒有汽車也能應付。"},{"en":"To do without something means to manage without having or using it.","zh":"To do without something 指在沒有或不使用某物的情況下仍能應付。"},{"en":"A family can do without a television if they mostly read or use computers.","zh":"如果家庭主要閱讀或使用電腦，他們可以沒有電視也能應付。"},{"en":"If public transport is reliable, some commuters can do without a car.","zh":"如果公共交通可靠，一些通勤者可以沒有汽車也能應付。"},{"en":"This phrase shows that something useful is not always necessary.","zh":"這個片語顯示有用的東西不一定必要。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":11},{"front":"drive occasionally","meaning":"偶爾駕車","examples":[{"en":"Some people may still need to drive occasionally.","zh":"有些人可能仍需要偶爾駕車。"},{"en":"To drive occasionally means to drive only sometimes, not every day.","zh":"To drive occasionally 指只是有時駕車，而不是每天駕車。"},{"en":"A person may drive occasionally to visit relatives in a village.","zh":"一個人可能偶爾駕車去村莊探親。"},{"en":"If someone drives occasionally, car clubs or rentals may be cheaper than ownership.","zh":"如果某人只是偶爾駕車，汽車共享會或租車可能比擁有汽車便宜。"},{"en":"This phrase describes limited, irregular car use.","zh":"這個片語描述有限而不定期的汽車使用。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":11},{"front":"one of several","meaning":"若干……之一","examples":[{"en":"Streetcar is one of several car clubs with growing numbers of members.","zh":"Streetcar是若干會員人數不斷增加的汽車共享會之一。"},{"en":"One of several means one example among a number of similar things.","zh":"One of several 指同類事物中的其中一個例子。"},{"en":"This library is one of several places where students can study quietly.","zh":"這間圖書館是若干學生可以安靜溫習的地方之一。"},{"en":"If a company is one of several providers, customers have more than one choice.","zh":"如果一間公司是若干供應商之一，顧客就有多於一個選擇。"},{"en":"This phrase shows that the example is not the only one.","zh":"這個片語顯示該例子不是唯一一個。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":11},{"front":"car clubs","meaning":"汽車共享會；汽車共享服務","examples":[{"en":"Car clubs allow members to use shared vehicles when needed.","zh":"汽車共享會讓會員在有需要時使用共享車輛。"},{"en":"Car clubs are services where members can book and use shared cars without owning them.","zh":"Car clubs 是會員可以預約和使用共享汽車，而不必擁有汽車的服務。"},{"en":"A city resident may join a car club for weekend shopping trips.","zh":"城市居民可能加入汽車共享會，用於週末購物旅程。"},{"en":"If car clubs are easy to access, fewer people may need private cars.","zh":"如果汽車共享服務容易使用，較少人可能需要私家車。"},{"en":"This phrase describes organised shared access to vehicles.","zh":"這個片語描述有組織的共享車輛使用途徑。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":11},{"front":"growing numbers of members","meaning":"不斷增加的會員人數","examples":[{"en":"Car clubs have growing numbers of members.","zh":"汽車共享會有不斷增加的會員人數。"},{"en":"Growing numbers of members means more and more people are joining.","zh":"Growing numbers of members 指越來越多人加入。"},{"en":"A sports club may have growing numbers of members after it lowers fees.","zh":"體育會降低費用後，會員人數可能不斷增加。"},{"en":"If car clubs gain growing numbers of members, shared transport may be becoming more acceptable.","zh":"如果汽車共享會會員人數不斷增加，共享交通可能正變得更被接受。"},{"en":"This phrase describes membership growth over time.","zh":"這個片語描述會員人數隨時間增長。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":11},{"front":"reckon that","meaning":"估計；認為","examples":[{"en":"Streetcar reckons that using its vehicles twice a week would cost £700 a year.","zh":"Streetcar估計每星期使用其車輛兩次，每年會花700英鎊。"},{"en":"To reckon that means to think, estimate, or calculate something.","zh":"To reckon that 指認為、估計或計算某事。"},{"en":"A shop owner may reckon that opening earlier will attract more customers.","zh":"店主可能認為早點開門會吸引更多顧客。"},{"en":"If a car club reckons the yearly cost is low, drivers may compare it with car ownership.","zh":"如果汽車共享會估計每年成本較低，駕駛者可能把它與擁有汽車作比較。"},{"en":"This phrase introduces an estimate or opinion.","zh":"這個片語引出估算或意見。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":11},{"front":"twice a week","meaning":"每星期兩次","examples":[{"en":"Using Streetcar vehicles twice a week would cost about £700 a year.","zh":"每星期使用Streetcar車輛兩次，每年會花約700英鎊。"},{"en":"Twice a week means two times every week.","zh":"Twice a week 指每星期兩次。"},{"en":"A student may practise speaking twice a week with a tutor.","zh":"學生可能每星期兩次與導師練習口語。"},{"en":"If someone drives only twice a week, owning a car may be more expensive than sharing one.","zh":"如果某人每星期只駕車兩次，擁有汽車可能比共享汽車更昂貴。"},{"en":"This phrase describes frequency.","zh":"這個片語描述頻率。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":11},{"front":"operate similarly to","meaning":"運作方式與……相似","examples":[{"en":"Streetcar’s model operates similarly to those of its main rivals.","zh":"Streetcar的模式運作方式與其主要競爭對手相似。"},{"en":"To operate similarly to something means to work in almost the same way.","zh":"To operate similarly to something 指以幾乎相同的方式運作。"},{"en":"Two libraries may operate similarly if both use online booking and self-service machines.","zh":"如果兩間圖書館都使用網上預約和自助機，它們的運作方式可能相似。"},{"en":"If car clubs operate similarly, customers can compare price and location more easily.","zh":"如果汽車共享會運作方式相似，顧客可以更容易比較價格和地點。"},{"en":"This phrase describes similar systems or methods.","zh":"這個片語描述相似制度或方法。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":11},{"front":"main rivals","meaning":"主要競爭對手","examples":[{"en":"Citycarclub and Whizzgo are Streetcar’s main rivals.","zh":"Citycarclub和Whizzgo是Streetcar的主要競爭對手。"},{"en":"Main rivals are the most important competitors in the same market or activity.","zh":"Main rivals 是同一市場或活動中最重要的競爭者。"},{"en":"Two nearby supermarkets may be main rivals because they sell similar products.","zh":"兩間附近超級市場可能是主要競爭對手，因為它們售賣相似產品。"},{"en":"If a company’s main rivals offer lower prices, it may need to improve its service.","zh":"如果公司的主要競爭對手提供較低價格，它可能需要改善服務。"},{"en":"This phrase identifies the strongest competitors.","zh":"這個片語指出最強的競爭者。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":11},{"front":"charge their members","meaning":"向會員收取費用","examples":[{"en":"Car clubs charge their members a refundable deposit.","zh":"汽車共享會向會員收取可退還按金。"},{"en":"To charge their members means to require members to pay money.","zh":"To charge their members 指要求會員付款。"},{"en":"A gym may charge its members a monthly fee.","zh":"健身室可能向會員收取月費。"},{"en":"If a club charges members a deposit, it may help protect shared property.","zh":"如果會社向會員收取按金，它可能有助保護共享財產。"},{"en":"This phrase describes collecting payment from people who belong to a group.","zh":"這個片語描述向某群體成員收款。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":12},{"front":"a refundable deposit","meaning":"可退還按金","examples":[{"en":"Streetcar charges its members a refundable deposit.","zh":"Streetcar向會員收取可退還按金。"},{"en":"A refundable deposit is money paid in advance that can be returned later if conditions are met.","zh":"Refundable deposit 是預先支付、在符合條件後可退回的金錢。"},{"en":"A tenant may pay a refundable deposit before moving into a flat.","zh":"租客搬入單位前可能支付可退還按金。"},{"en":"If a driver returns a shared car properly, the deposit may remain refundable.","zh":"如果駕駛者妥善歸還共享汽車，按金可能仍可退還。"},{"en":"This phrase describes a temporary payment used as security.","zh":"這個片語描述用作保障的臨時付款。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":12},{"front":"provide someone with","meaning":"向某人提供","examples":[{"en":"Car clubs provide members with an electronic smart card.","zh":"汽車共享會向會員提供電子智能卡。"},{"en":"To provide someone with something means to give or supply it to them.","zh":"To provide someone with something 指給予或供應某物給某人。"},{"en":"A school may provide students with tablets for online lessons.","zh":"學校可能向學生提供平板電腦，用於網上課堂。"},{"en":"If a service provides users with a smart card, access becomes easier.","zh":"如果服務向使用者提供智能卡，使用會變得更容易。"},{"en":"This phrase describes giving someone a tool, service, or resource.","zh":"這個片語描述向某人提供工具、服務或資源。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":12},{"front":"an electronic smart card","meaning":"電子智能卡","examples":[{"en":"Members use an electronic smart card to get into the vehicles.","zh":"會員使用電子智能卡進入車輛。"},{"en":"An electronic smart card is a plastic card with digital technology that can unlock or identify access.","zh":"Electronic smart card 是含有數碼技術、可解鎖或識別使用權的塑膠卡。"},{"en":"Students may use an electronic smart card to enter a library or pay for lunch.","zh":"學生可能使用電子智能卡進入圖書館或支付午餐費。"},{"en":"If a car club uses smart cards, members can collect cars without meeting staff.","zh":"如果汽車共享會使用智能卡，會員無需見職員也能取車。"},{"en":"This phrase refers to a digital access card.","zh":"這個片語指數碼門禁卡。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":12},{"front":"enable members to","meaning":"讓會員能夠","examples":[{"en":"The smart card enables members to get into the vehicles.","zh":"智能卡讓會員能夠進入車輛。"},{"en":"To enable members to do something means to make it possible for them to do it.","zh":"To enable members to do something 指令會員能夠做某事。"},{"en":"A library card enables students to borrow books and use computers.","zh":"圖書證讓學生能夠借書和使用電腦。"},{"en":"If a smart card enables members to open a shared car, the service becomes more convenient.","zh":"如果智能卡讓會員能夠打開共享汽車，服務就變得更方便。"},{"en":"This phrase shows how a tool gives people access or ability.","zh":"這個片語顯示工具如何給人使用權或能力。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":12},{"front":"get into the vehicles","meaning":"進入車輛","examples":[{"en":"The smart card enables members to get into the vehicles.","zh":"智能卡讓會員能夠進入車輛。"},{"en":"To get into the vehicles means to enter the cars or other transport machines.","zh":"To get into the vehicles 指進入汽車或其他交通工具。"},{"en":"Passengers should wait until the bus stops before they get into the vehicle.","zh":"乘客應等巴士停定後才進入車輛。"},{"en":"If members cannot get into the vehicles easily, the car-club system will be frustrating.","zh":"如果會員不能輕易進入車輛，汽車共享系統會令人沮喪。"},{"en":"This phrase describes physical access to transport.","zh":"這個片語描述實際進入交通工具。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":12},{"front":"be left parked in","meaning":"被停泊在……","examples":[{"en":"The vehicles are left parked in set locations.","zh":"車輛被停泊在固定地點。"},{"en":"To be left parked in a place means to remain stopped and stored there.","zh":"To be left parked in a place 指車輛停下並留存在該處。"},{"en":"Shared bicycles are often left parked in marked areas near stations.","zh":"共享單車通常被停泊在車站附近的指定區域。"},{"en":"If cars are left parked in set locations, members know where to find them.","zh":"如果汽車被停泊在固定地點，會員便知道在哪裡找到它們。"},{"en":"This phrase describes where vehicles are kept when not being used.","zh":"這個片語描述車輛不用時被放置的位置。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":12},{"front":"set locations","meaning":"固定地點","examples":[{"en":"Car-club vehicles are parked in set locations.","zh":"汽車共享會車輛停泊在固定地點。"},{"en":"Set locations are fixed or agreed places.","zh":"Set locations 是固定或已約定的地點。"},{"en":"School buses may pick up students from set locations every morning.","zh":"校巴可能每天早上在固定地點接學生。"},{"en":"If shared cars are kept at set locations, users can plan journeys more easily.","zh":"如果共享汽車停放在固定地點，使用者可以更容易計劃旅程。"},{"en":"This phrase means the places are not random.","zh":"這個片語意思是地點不是隨機的。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":12},{"front":"the glove compartment","meaning":"車內雜物箱","examples":[{"en":"The keys are found in the glove compartment.","zh":"鎖匙可在車內雜物箱找到。"},{"en":"The glove compartment is the small storage space in front of the passenger seat in a car.","zh":"Glove compartment 是汽車乘客座前方的小型儲物空間。"},{"en":"A driver may keep the car manual in the glove compartment.","zh":"駕駛者可能把汽車手冊放在車內雜物箱。"},{"en":"If keys are kept in the glove compartment, members can collect them after unlocking the car.","zh":"如果鎖匙放在車內雜物箱，會員解鎖汽車後便可以取用。"},{"en":"This phrase names a common storage space inside a car.","zh":"這個片語命名車內常見儲物空間。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":12},{"front":"pay an hourly rate","meaning":"按小時付費","examples":[{"en":"Members pay an hourly rate for the car.","zh":"會員按小時為汽車付費。"},{"en":"To pay an hourly rate means to pay a set amount for each hour of use or work.","zh":"To pay an hourly rate 指按每小時使用或工作支付固定金額。"},{"en":"A student may pay an hourly rate for private tutoring.","zh":"學生可能為私人補習按小時付費。"},{"en":"If a driver uses a shared car for only two hours, an hourly rate can be cheaper than daily rental.","zh":"如果駕駛者只使用共享汽車兩小時，按小時付費可能比日租便宜。"},{"en":"This phrase describes payment based on time.","zh":"這個片語描述按時間付款。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":12},{"front":"return it to the same spot","meaning":"把它歸還到同一地點","examples":[{"en":"Members can return the car to the same spot.","zh":"會員可以把汽車歸還到同一地點。"},{"en":"To return it to the same spot means to bring it back to the exact place where it was taken from.","zh":"To return it to the same spot 指把它帶回取用時的確切位置。"},{"en":"A student should return a borrowed laptop to the same spot in the library.","zh":"學生應把借用的手提電腦歸還到圖書館同一地點。"},{"en":"If members return cars to the same spot, the next user can find them easily.","zh":"如果會員把汽車歸還到同一地點，下一位使用者就能輕易找到。"},{"en":"This phrase describes putting something back where it belongs.","zh":"這個片語描述把某物放回原本位置。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":13},{"front":"a designated parking place","meaning":"指定泊車位","examples":[{"en":"Members may return the car to a designated parking place.","zh":"會員可以把汽車歸還到指定泊車位。"},{"en":"A designated parking place is an officially chosen space where a vehicle should be parked.","zh":"Designated parking place 是官方指定應停泊車輛的地方。"},{"en":"Visitors must leave their cars in the designated parking place behind the school.","zh":"訪客必須把車停在學校後方的指定泊車位。"},{"en":"If shared cars have designated parking places, users do not waste time searching.","zh":"如果共享汽車有指定泊車位，使用者不會浪費時間尋找車輛。"},{"en":"This phrase refers to an assigned parking spot.","zh":"這個片語指被分配的泊車位置。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":13},{"front":"car sharing","meaning":"汽車共乘","examples":[{"en":"Car sharing is an increasingly popular option.","zh":"汽車共乘是越來越受歡迎的選擇。"},{"en":"Car sharing means several people using the same car or sharing a journey instead of each driving separately.","zh":"Car sharing 指幾個人使用同一輛汽車或共享同一段旅程，而不是各自駕車。"},{"en":"Colleagues may use car sharing when they live near each other and work in the same office.","zh":"如果同事住得近並在同一辦公室工作，他們可能使用汽車共乘。"},{"en":"If more people share cars, traffic, fuel costs, and parking demand may fall.","zh":"如果更多人共乘汽車，交通、燃油成本和泊車需求可能下降。"},{"en":"This phrase describes sharing transport to reduce cost or waste.","zh":"這個片語描述共享交通以減少成本或浪費。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":13},{"front":"an increasingly popular option","meaning":"越來越受歡迎的選擇","examples":[{"en":"Car sharing is an increasingly popular option for regular journeys.","zh":"汽車共乘是定期出行中越來越受歡迎的選擇。"},{"en":"An increasingly popular option is a choice that more and more people are using.","zh":"Increasingly popular option 是越來越多人使用的選擇。"},{"en":"Cycling has become an increasingly popular option for short city journeys.","zh":"踩單車已成為短途城市旅程中越來越受歡迎的選擇。"},{"en":"If an option saves money and reduces stress, it may become more popular over time.","zh":"如果某選擇省錢並減少壓力，它可能隨時間變得更受歡迎。"},{"en":"This phrase describes a choice gaining public acceptance.","zh":"這個片語描述正在獲得公眾接受的選擇。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":13},{"front":"make the same journeys regularly","meaning":"定期走相同路線","examples":[{"en":"Car sharing suits people who make the same journeys regularly.","zh":"汽車共乘適合定期走相同路線的人。"},{"en":"To make the same journeys regularly means to travel the same route again and again.","zh":"To make the same journeys regularly 指一次又一次走同一條路線。"},{"en":"Colleagues who travel from the same district to the same office make the same journey regularly.","zh":"從同一地區到同一辦公室上班的同事，就是定期走相同路線。"},{"en":"If people make the same journeys regularly, sharing a car is easier to organise.","zh":"如果人們定期走相同路線，安排共乘汽車會更容易。"},{"en":"This phrase describes repeated travel patterns.","zh":"這個片語描述重複出行模式。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":13},{"front":"to and from work","meaning":"上下班往返","examples":[{"en":"Many people share cars to and from work.","zh":"許多人上下班往返時共乘汽車。"},{"en":"To and from work means travelling from home to work and back again.","zh":"To and from work 指從家到工作地點，再從工作地點回家。"},{"en":"A commuter may read on the train to and from work.","zh":"通勤者可能在上下班往返的火車上閱讀。"},{"en":"If colleagues live nearby, they can share fuel costs to and from work.","zh":"如果同事住得近，他們可以在上下班往返時分擔燃油成本。"},{"en":"This phrase describes the daily work commute in both directions.","zh":"這個片語描述雙向的日常上班通勤。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":13},{"front":"run schemes","meaning":"推行計劃","examples":[{"en":"Many companies run schemes to help colleagues share journeys.","zh":"許多公司推行計劃，幫助同事共享旅程。"},{"en":"To run schemes means to organise and operate planned programmes.","zh":"To run schemes 指組織和運作有計劃的項目。"},{"en":"A school may run schemes to help weaker readers after class.","zh":"學校可能推行課後計劃來幫助閱讀較弱的學生。"},{"en":"If companies run car-sharing schemes, employees may save money and reduce traffic.","zh":"如果公司推行汽車共乘計劃，員工可能省錢並減少交通。"},{"en":"This phrase describes managing a structured plan.","zh":"這個片語描述管理有結構的計劃。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":13},{"front":"live near each other","meaning":"住得近","examples":[{"en":"Car-sharing schemes connect colleagues who live near each other.","zh":"汽車共乘計劃連接住得近的同事。"},{"en":"To live near each other means to have homes close to one another.","zh":"To live near each other 指彼此住所距離近。"},{"en":"Students who live near each other may walk to school together.","zh":"住得近的學生可能一起步行上學。"},{"en":"If colleagues live near each other, sharing a journey to work becomes practical.","zh":"如果同事住得近，共乘上班就變得實際。"},{"en":"This phrase describes physical closeness between homes.","zh":"這個片語描述住所之間距離接近。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":13},{"front":"work in the same place","meaning":"在同一地方工作","examples":[{"en":"Car-sharing schemes help people who work in the same place.","zh":"汽車共乘計劃幫助在同一地方工作的人。"},{"en":"To work in the same place means to have jobs at the same office, building, school, or site.","zh":"To work in the same place 指在同一辦公室、大樓、學校或工作地點工作。"},{"en":"Nurses who work in the same hospital may arrange shared transport.","zh":"在同一間醫院工作的護士可能安排共享交通。"},{"en":"If people work in the same place and live nearby, car sharing is easier.","zh":"如果人們在同一地方工作並住得近，汽車共乘會更容易。"},{"en":"This phrase describes a shared workplace.","zh":"這個片語描述共同工作地點。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":13},{"front":"contact each other","meaning":"互相聯絡","examples":[{"en":"The schemes help colleagues contact each other.","zh":"這些計劃幫助同事互相聯絡。"},{"en":"To contact each other means to communicate with one another by phone, message, email, or another method.","zh":"To contact each other 指透過電話、訊息、電郵或其他方法互相溝通。"},{"en":"Parents may contact each other to arrange school pick-ups.","zh":"家長可能互相聯絡，以安排接送孩子放學。"},{"en":"If commuters can contact each other easily, car sharing becomes simpler to organise.","zh":"如果通勤者能輕易互相聯絡，汽車共乘會更容易安排。"},{"en":"This phrase describes two-way communication.","zh":"這個片語描述雙向溝通。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":13},{"front":"share the journey to work","meaning":"共乘上班","examples":[{"en":"Colleagues can share the journey to work.","zh":"同事可以共乘上班。"},{"en":"To share the journey to work means to travel to the workplace together, often in one car.","zh":"To share the journey to work 指一起前往工作地點，通常乘同一輛車。"},{"en":"Two teachers may share the journey to work if they live in the same area.","zh":"如果兩位老師住在同一區，他們可能共乘上班。"},{"en":"If workers share the journey to work, each person may pay less for fuel.","zh":"如果員工共乘上班，每個人可能支付較少燃油費。"},{"en":"This phrase describes commuting together.","zh":"這個片語描述一起通勤上班。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":14},{"front":"national organisations","meaning":"全國性組織","examples":[{"en":"Liftshare and Carshare are two national organisations.","zh":"Liftshare和Carshare是兩個全國性組織。"},{"en":"National organisations are groups or services that operate across a whole country.","zh":"National organisations 是在整個國家範圍內運作的團體或服務。"},{"en":"A national charity may support families in many different cities.","zh":"全國性慈善機構可能支援許多不同城市的家庭。"},{"en":"If a car-sharing organisation is national, users from many regions can join.","zh":"如果汽車共乘組織是全國性的，許多地區的使用者都可以加入。"},{"en":"This phrase contrasts countrywide groups with local groups.","zh":"這個片語把全國團體與本地團體作對比。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":14},{"front":"maintain online databases","meaning":"維持網上資料庫","examples":[{"en":"These organisations maintain online databases of potential car sharers.","zh":"這些組織維持潛在汽車共乘者的網上資料庫。"},{"en":"To maintain online databases means to keep digital collections of information updated and working.","zh":"To maintain online databases 指保持數碼資訊集合更新並正常運作。"},{"en":"A school may maintain an online database of books available in the library.","zh":"學校可能維持圖書館可借書籍的網上資料庫。"},{"en":"If a car-sharing database is maintained well, users can find suitable travel partners.","zh":"如果汽車共乘資料庫維持得好，使用者可以找到合適旅伴。"},{"en":"This phrase describes managing organised information on the Internet.","zh":"這個片語描述在互聯網上管理有組織資訊。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":14},{"front":"be prepared to team up","meaning":"願意合作；願意結伴同行","examples":[{"en":"Some drivers are prepared to team up with others.","zh":"有些駕駛者願意與其他人合作。"},{"en":"To be prepared to team up means to be willing to work or travel together with other people.","zh":"To be prepared to team up 指願意與其他人合作或結伴同行。"},{"en":"Students may be prepared to team up for a group presentation.","zh":"學生可能願意合作完成小組報告。"},{"en":"If drivers are prepared to team up, they can share fuel costs and reduce traffic.","zh":"如果駕駛者願意結伴同行，他們可以分擔燃油成本並減少交通。"},{"en":"This phrase shows willingness to cooperate.","zh":"這個片語顯示合作意願。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":14},{"front":"replace part or all of","meaning":"取代部分或全部……","examples":[{"en":"Some people can replace part or all of their journey with low-cost transport.","zh":"有些人可以用低成本交通方式取代部分或全部旅程。"},{"en":"To replace part or all of something means to substitute some or the whole of it with another option.","zh":"To replace part or all of something 指以另一選擇替代某事的一部分或全部。"},{"en":"A student may replace part of a long bus journey by cycling to a nearer station.","zh":"學生可能踩單車到較近車站，以取代長巴士旅程的一部分。"},{"en":"If people replace all of a car journey with walking, they spend no fuel money.","zh":"如果人們以步行取代全部汽車旅程，他們就不用花燃油費。"},{"en":"This phrase describes partial or complete substitution.","zh":"這個片語描述部分或完全替代。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":14},{"front":"for that matter","meaning":"就此而言；甚至可以說","examples":[{"en":"People may replace journeys to work, or any journeys for that matter, with walking.","zh":"人們可以用步行取代上班旅程，甚至可以說任何旅程。"},{"en":"For that matter means used to add a related point that is also true.","zh":"For that matter 用來加入另一個同樣成立的相關重點。"},{"en":"You can use this app for homework, or for revision for that matter.","zh":"你可以用這個應用程式做功課，甚至可以用來溫習。"},{"en":"If walking works for work journeys, it may work for short shopping trips for that matter.","zh":"如果步行適用於上班旅程，就此而言，它也可能適用於短途購物旅程。"},{"en":"This phrase widens the statement to include another similar case.","zh":"這個片語把陳述擴展到另一個相似情況。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":14},{"front":"low-cost transport","meaning":"低成本交通方式","examples":[{"en":"A bicycle is a form of low-cost transport.","zh":"單車是一種低成本交通方式。"},{"en":"Low-cost transport is a way of travelling that does not require much money.","zh":"Low-cost transport 是不需要花太多錢的出行方式。"},{"en":"Walking, cycling, and some bus services can be low-cost transport.","zh":"步行、踩單車和一些巴士服務都可以是低成本交通方式。"},{"en":"If people use low-cost transport more often, they may save money on fuel and parking.","zh":"如果人們更常使用低成本交通方式，他們可能節省燃油和泊車費。"},{"en":"This phrase contrasts cheaper travel with expensive private car use.","zh":"這個片語把較便宜出行與昂貴私家車使用作對比。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":14},{"front":"by walking","meaning":"以步行方式","examples":[{"en":"Some journeys can be replaced by walking.","zh":"一些旅程可以以步行方式取代。"},{"en":"By walking means through travelling on foot instead of using a vehicle.","zh":"By walking 指透過步行而不是使用車輛出行。"},{"en":"A student may get to school by walking if the school is nearby.","zh":"如果學校在附近，學生可能以步行方式上學。"},{"en":"If short trips are done by walking, people save money and get exercise.","zh":"如果短途旅程以步行方式完成，人們可以省錢並運動。"},{"en":"This phrase describes walking as the method of travel.","zh":"這個片語描述步行作為出行方法。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":14},{"front":"reduce your car use","meaning":"減少汽車使用量","examples":[{"en":"The more you reduce your car use, the more you save.","zh":"你越減少汽車使用量，就越省錢。"},{"en":"To reduce your car use means to drive less often or for fewer journeys.","zh":"To reduce your car use 指較少駕車或減少用車旅程。"},{"en":"A family can reduce car use by walking to nearby shops.","zh":"家庭可以透過步行到附近商店來減少汽車使用量。"},{"en":"If you reduce your car use, you may spend less on fuel, parking, and repairs.","zh":"如果你減少汽車使用量，可能在燃油、泊車和維修上花費較少。"},{"en":"This phrase focuses on using the car less, not necessarily giving it up completely.","zh":"這個片語著重少用汽車，而不一定是完全放棄。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":14},{"front":"gain access to","meaning":"取得使用……的途徑","examples":[{"en":"You may gain access to a car through ownership, hire or a car club.","zh":"你可以透過擁有、租用或汽車共享會取得使用汽車的途徑。"},{"en":"To gain access to something means to get the ability or permission to use it.","zh":"To gain access to something 指取得使用某物的能力或許可。"},{"en":"A student can gain access to online lessons after receiving a school login.","zh":"學生收到學校登入資料後，可以取得使用網上課堂的途徑。"},{"en":"If people gain access to shared cars, they may not need to own one.","zh":"如果人們取得使用共享汽車的途徑，他們可能不需要擁有汽車。"},{"en":"This phrase focuses on availability and permission to use something.","zh":"這個片語著重可用性和使用許可。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":14},{"front":"the more…, the more…","meaning":"越……就越……","examples":[{"en":"The more you can reduce your car use, the more you will save.","zh":"你越能減少汽車使用量，就越能省錢。"},{"en":"The more…, the more… shows that one increase or decrease leads to another.","zh":"The more…, the more… 顯示一個增加或減少會導致另一個增加或減少。"},{"en":"The more you practise speaking, the more confident you become.","zh":"你越練習口語，就越有信心。"},{"en":"The more people share journeys, the more traffic and fuel costs may fall.","zh":"越多人共享旅程，交通和燃油成本就越可能下降。"},{"en":"This structure connects two changes that move together.","zh":"這個結構連接兩個一起變化的情況。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":15},{"front":"which paragraph does each heading best fit","meaning":"每個標題最適合哪一段","examples":[{"en":"Students decide which paragraph each heading best fits.","zh":"學生判斷每個標題最適合哪一段。"},{"en":"Which paragraph does each heading best fit means students must match each title to the paragraph it summarises best.","zh":"Which paragraph does each heading best fit 指學生必須把每個標題配對到最能概括它的段落。"},{"en":"In a reading test, a heading should fit the whole paragraph, not just one word.","zh":"在閱讀測驗中，標題應符合整段，而不只是其中一個字。"},{"en":"If students understand the main idea, they can decide which heading best fits.","zh":"如果學生理解主要意思，就能判斷哪個標題最適合。"},{"en":"This phrase describes a paragraph-heading matching task.","zh":"這個片語描述段落標題配對題。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":15},{"front":"the following headings","meaning":"以下標題","examples":[{"en":"The following headings summarise four of the paragraphs.","zh":"以下標題概括其中四段。"},{"en":"The following headings means the titles listed below the instruction.","zh":"The following headings 指指示下方列出的標題。"},{"en":"Students should read the following headings before scanning the paragraphs.","zh":"學生應先閱讀以下標題，再掃讀段落。"},{"en":"If the following headings are similar, students must compare their meanings carefully.","zh":"如果以下標題相似，學生必須仔細比較它們的意思。"},{"en":"This phrase introduces answer options in a reading task.","zh":"這個片語引出閱讀任務中的答案選項。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":15},{"front":"best fit","meaning":"最適合","examples":[{"en":"Each heading should best fit one paragraph.","zh":"每個標題應最適合一段。"},{"en":"Best fit means match most accurately or appropriately.","zh":"Best fit 指最準確或最合適地配合。"},{"en":"A warm coat is the best fit for a cold outdoor trip.","zh":"厚外套最適合寒冷的戶外旅行。"},{"en":"If a heading best fits a paragraph, it captures the main idea better than the other options.","zh":"如果一個標題最適合某段，它比其他選項更能概括主要意思。"},{"en":"This phrase is about the most suitable match.","zh":"這個片語指最合適的配對。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":15},{"front":"don’t wait","meaning":"不要等","examples":[{"en":"The heading “Don’t wait” suggests taking action before charges are imposed.","zh":"標題 “Don’t wait” 暗示在收費實施前採取行動。"},{"en":"Don’t wait means act now instead of delaying.","zh":"Don’t wait 指現在行動，而不是拖延。"},{"en":"A teacher may say “don’t wait” if students need to start revision early.","zh":"如果學生需要早點開始溫習，老師可能會說「不要等」。"},{"en":"If road charges are coming, drivers may save more by changing habits before they begin.","zh":"如果道路收費即將推出，駕駛者在開始前改變習慣可能省更多錢。"},{"en":"This phrase is a warning against delaying action.","zh":"這個片語是不要拖延行動的提醒。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":15},{"front":"team up","meaning":"結伴同行；合作","examples":[{"en":"Drivers may team up with others to share a journey.","zh":"駕駛者可能與其他人結伴同行，共享旅程。"},{"en":"To team up means to work or act together with another person or group.","zh":"To team up 指與另一人或群體合作或一起行動。"},{"en":"Students may team up to prepare a class presentation.","zh":"學生可能合作準備課堂報告。"},{"en":"If commuters team up, they can share fuel costs and reduce the number of cars on the road.","zh":"如果通勤者結伴同行，他們可以分擔燃油成本並減少路上汽車數量。"},{"en":"This phrase describes cooperation for a shared purpose.","zh":"這個片語描述為共同目的而合作。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":15},{"front":"join a club","meaning":"加入會社；加入俱樂部","examples":[{"en":"Some motorists may join a club to use shared vehicles.","zh":"一些駕駛者可能加入會社，以使用共享車輛。"},{"en":"To join a club means to become a member of an organised group or service.","zh":"To join a club 指成為有組織團體或服務的會員。"},{"en":"A student may join a reading club to discuss books with classmates.","zh":"學生可能加入閱讀會，與同學討論書籍。"},{"en":"If drivers join a car club, they can use cars without owning one.","zh":"如果駕駛者加入汽車共享會，他們可以使用汽車而不必擁有汽車。"},{"en":"This phrase describes becoming part of a group with shared benefits.","zh":"這個片語描述成為有共同好處的群體一員。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":15},{"front":"according to the text","meaning":"根據文章","examples":[{"en":"Students choose statements that are true according to the text.","zh":"學生選出根據文章屬實的陳述。"},{"en":"According to the text means based only on what the passage says.","zh":"According to the text 指只根據文章所說。"},{"en":"In reading exams, answers should be chosen according to the text, not personal opinion.","zh":"在閱讀考試中，答案應根據文章選出，而不是根據個人意見。"},{"en":"If a statement is not supported by the passage, it is not true according to the text.","zh":"如果陳述不受文章支持，它就不是根據文章屬實。"},{"en":"This phrase points students back to the source material.","zh":"這個片語把學生帶回原文材料。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":15},{"front":"the following statements","meaning":"以下陳述","examples":[{"en":"Five of the following statements are true.","zh":"以下陳述中有五項屬實。"},{"en":"The following statements means the sentences listed below the instruction.","zh":"The following statements 指指示下方列出的句子。"},{"en":"Students should read the following statements carefully before checking the passage.","zh":"學生應仔細閱讀以下陳述，再查看文章。"},{"en":"If two statements look similar, small differences in meaning may matter.","zh":"如果兩項陳述看似相似，意思上的小差異可能很重要。"},{"en":"This phrase introduces the answer choices in a reading exercise.","zh":"這個片語引出閱讀練習中的答案選項。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":15},{"front":"corresponding letters","meaning":"相應字母","examples":[{"en":"Students write the corresponding letters in the answer boxes.","zh":"學生在答案方格中寫上相應字母。"},{"en":"Corresponding letters are the letters that match the correct statements or choices.","zh":"Corresponding letters 是與正確陳述或選項相配的字母。"},{"en":"If answer A matches the first question, students write the corresponding letter A.","zh":"如果答案A符合第一題，學生便寫上相應字母A。"},{"en":"If students write the wrong letter, the answer may be marked wrong even if they understood the idea.","zh":"如果學生寫錯字母，即使理解意思，答案也可能被判錯。"},{"en":"This phrase is common in multiple-choice and matching tasks.","zh":"這個片語常見於選擇題和配對題。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":15},{"front":"in any order","meaning":"以任何次序","examples":[{"en":"The five letters may be written in any order.","zh":"五個字母可以以任何次序寫下。"},{"en":"In any order means the sequence does not matter.","zh":"In any order 指排列次序不重要。"},{"en":"Students may list the correct names in any order if the question allows it.","zh":"如果題目允許，學生可以以任何次序列出正確姓名。"},{"en":"If answers can be written in any order, accuracy matters more than arrangement.","zh":"如果答案可以以任何次序寫下，準確比排列更重要。"},{"en":"This phrase tells students they do not need to follow a fixed sequence.","zh":"這個片語告訴學生不需要跟隨固定次序。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":16},{"front":"become addicted to","meaning":"對……上癮","examples":[{"en":"McCarthy claims that people can become addicted to using cars.","zh":"McCarthy聲稱人們可能對使用汽車上癮。"},{"en":"To become addicted to something means to develop a strong need or habit that is hard to stop.","zh":"To become addicted to something 指形成難以停止的強烈需要或習慣。"},{"en":"Some students become addicted to checking social media before sleeping.","zh":"有些學生睡前會對查看社交媒體上癮。"},{"en":"If people become addicted to driving, they may use a car even for very short trips.","zh":"如果人們對駕車上癮，他們甚至很短路程也可能使用汽車。"},{"en":"This phrase describes dependence that affects behaviour.","zh":"這個片語描述影響行為的依賴。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":16},{"front":"using cars","meaning":"使用汽車","examples":[{"en":"Some people become psychologically dependent on using cars.","zh":"有些人在心理上依賴使用汽車。"},{"en":"Using cars means travelling by car for daily journeys or specific trips.","zh":"Using cars 指日常旅程或特定出行時乘搭或駕駛汽車。"},{"en":"A family may depend on using cars if public transport is poor near their home.","zh":"如果家附近公共交通差，家庭可能依賴使用汽車。"},{"en":"If people get used to using cars for every small trip, walking may feel inconvenient.","zh":"如果人們習慣每段小旅程都使用汽車，步行可能感覺不方便。"},{"en":"This phrase focuses on the act of travelling by car.","zh":"這個片語著重以汽車出行的行為。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":16},{"front":"borrow money to","meaning":"借錢去","examples":[{"en":"Many people borrow money to help buy cars.","zh":"許多人借錢去幫助購買汽車。"},{"en":"To borrow money to do something means to receive money temporarily and repay it later for that purpose.","zh":"To borrow money to do something 指暫時取得金錢，之後償還，以達到某目的。"},{"en":"A student may borrow money to pay for a course if they cannot afford it immediately.","zh":"如果學生無法即時負擔課程費用，可能借錢去支付。"},{"en":"If buyers borrow money to buy a car, interest can increase the total cost.","zh":"如果買家借錢去買車，利息可以增加總成本。"},{"en":"This phrase connects borrowing with a specific purchase or need.","zh":"這個片語把借貸與特定購買或需要連接起來。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":16},{"front":"help buy cars","meaning":"幫助購買汽車","examples":[{"en":"Finance packages help people buy cars.","zh":"分期付款計劃幫助人們購買汽車。"},{"en":"To help buy cars means to make it easier for people to pay for cars.","zh":"To help buy cars 指令支付汽車費用變得較容易。"},{"en":"A parent may help buy a car for a child who needs to travel to work.","zh":"家長可能幫助需要出行上班的子女購買汽車。"},{"en":"If loans help people buy cars, they may also create long-term repayments.","zh":"如果貸款幫助人們購買汽車，也可能造成長期還款。"},{"en":"This phrase describes financial support for car purchase.","zh":"這個片語描述購買汽車的財政支援。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":16},{"front":"operate in over 20 cities","meaning":"在超過20個城市營運","examples":[{"en":"A company may operate in over 20 cities in Britain.","zh":"一間公司可能在英國超過20個城市營運。"},{"en":"To operate in over 20 cities means to provide services or do business in more than twenty cities.","zh":"To operate in over 20 cities 指在超過二十個城市提供服務或經營業務。"},{"en":"A delivery company may operate in over 20 cities if demand is high.","zh":"如果需求高，送貨公司可能在超過20個城市營運。"},{"en":"If a car club operates in many cities, more people can use shared vehicles.","zh":"如果汽車共享會在許多城市營運，更多人可以使用共享車輛。"},{"en":"This phrase describes the geographical reach of a company or service.","zh":"這個片語描述公司或服務的地理覆蓋範圍。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":16},{"front":"must be left at","meaning":"必須留在……","examples":[{"en":"The cars must be left at specific locations.","zh":"汽車必須留在特定地點。"},{"en":"Must be left at means have to be returned to or kept in a required place.","zh":"Must be left at 指必須被歸還到或保存在指定地點。"},{"en":"Library books must be left at the return desk after use.","zh":"圖書館書籍使用後必須留在還書處。"},{"en":"If shared cars must be left at set locations, the next user can find them.","zh":"如果共享汽車必須留在固定地點，下一位使用者便能找到。"},{"en":"This phrase gives a rule about where something should remain.","zh":"這個片語給出某物應留在哪裡的規則。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":16},{"front":"specific locations","meaning":"特定地點","examples":[{"en":"Streetcar’s cars are parked at specific locations.","zh":"Streetcar的汽車停泊在特定地點。"},{"en":"Specific locations are clearly identified places.","zh":"Specific locations 是清楚指定的地方。"},{"en":"Students may meet at specific locations before a school trip begins.","zh":"學校旅行開始前，學生可能在特定地點集合。"},{"en":"If cars are parked at specific locations, users do not need to search across a whole district.","zh":"如果汽車停泊在特定地點，使用者不需要在整個地區尋找。"},{"en":"This phrase means the places are exact, not vague.","zh":"這個片語意思是地點明確，而不是模糊。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":16},{"front":"becoming more popular with","meaning":"越來越受……歡迎","examples":[{"en":"Car sharing is becoming more popular with regular commuters.","zh":"汽車共乘越來越受定期通勤者歡迎。"},{"en":"Becoming more popular with a group means being chosen or liked by more people in that group.","zh":"Becoming more popular with a group 指越來越被該群體中的人選擇或喜愛。"},{"en":"Online banking is becoming more popular with older adults as apps become simpler.","zh":"隨着應用程式變得更簡單，網上銀行越來越受長者歡迎。"},{"en":"If petrol prices rise, car sharing may become more popular with workers.","zh":"如果汽油價格上升，汽車共乘可能越來越受上班族歡迎。"},{"en":"This phrase describes increasing acceptance among a particular group.","zh":"這個片語描述在某特定群體中接受度增加。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":16},{"front":"encourage people to","meaning":"鼓勵人們","examples":[{"en":"The government may encourage people to go to work on foot or by bicycle.","zh":"政府可能鼓勵人們步行或踩單車上班。"},{"en":"To encourage people to do something means to persuade or support them to do it.","zh":"To encourage people to do something 指說服或支持人們做某事。"},{"en":"A school may encourage students to read by creating a comfortable reading corner.","zh":"學校可能透過設立舒適閱讀角，鼓勵學生閱讀。"},{"en":"If governments encourage people to cycle, they may also need to build safer bike lanes.","zh":"如果政府鼓勵人們踩單車，也可能需要興建更安全的單車徑。"},{"en":"This phrase describes positive pressure or support for action.","zh":"這個片語描述促使行動的正面壓力或支持。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":16},{"front":"go to work on foot","meaning":"步行上班","examples":[{"en":"Some people may go to work on foot instead of driving.","zh":"有些人可能步行上班，而不是駕車。"},{"en":"To go to work on foot means to walk to the workplace.","zh":"To go to work on foot 指步行到工作地點。"},{"en":"A shop assistant who lives nearby may go to work on foot every morning.","zh":"住在附近的店員可能每天早上步行上班。"},{"en":"If more people go to work on foot, traffic and transport costs may fall.","zh":"如果更多人步行上班，交通和出行成本可能下降。"},{"en":"This phrase describes walking as the commuting method.","zh":"這個片語描述步行作為通勤方式。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":17},{"front":"by bicycle","meaning":"踩單車","examples":[{"en":"Some commuters travel by bicycle.","zh":"有些通勤者踩單車出行。"},{"en":"By bicycle means using a bicycle as the method of transport.","zh":"By bicycle 指使用單車作為交通方式。"},{"en":"A student may go to school by bicycle if there is a safe cycle path.","zh":"如果有安全單車徑，學生可能踩單車上學。"},{"en":"Travelling by bicycle can save money and provide daily exercise.","zh":"踩單車出行可以省錢並提供每日運動。"},{"en":"This phrase describes cycling as a way to travel.","zh":"這個片語描述踩單車作為出行方法。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":17},{"front":"choose the correct answer or answers","meaning":"選出正確答案","examples":[{"en":"Students choose the correct answer or answers from the choices given.","zh":"學生從所給選項中選出正確答案。"},{"en":"Choose the correct answer or answers means select one or more options that match the question.","zh":"Choose the correct answer or answers 指選出一個或多個符合題目的選項。"},{"en":"In some reading questions, students must choose two correct answers, not just one.","zh":"在一些閱讀題中，學生必須選出兩個正確答案，而不只一個。"},{"en":"If the instruction says “answer or answers”, students should check whether more than one option is possible.","zh":"如果指示說 “answer or answers”，學生應檢查是否可能有多於一個選項。"},{"en":"This phrase is a careful exam instruction.","zh":"這個片語是仔細的考試指示。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":17},{"front":"from the choices given","meaning":"從所提供選項中","examples":[{"en":"The answer must be selected from the choices given.","zh":"答案必須從所提供選項中選出。"},{"en":"From the choices given means from the options provided in the question.","zh":"From the choices given 指從題目提供的選項中選擇。"},{"en":"Students should not invent an answer if the instruction says to choose from the choices given.","zh":"如果指示說要從所提供選項中選擇，學生不應自創答案。"},{"en":"If the choices given are similar, students must compare the wording carefully.","zh":"如果所提供選項很相似，學生必須仔細比較用字。"},{"en":"This phrase limits answers to the listed options.","zh":"這個片語把答案限制在列出的選項內。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":17},{"front":"decide not to","meaning":"決定不","examples":[{"en":"The government has decided not to follow protestors’ suggestions.","zh":"政府已決定不跟隨抗議者的建議。"},{"en":"To decide not to do something means to choose against doing it.","zh":"To decide not to do something 指選擇不做某事。"},{"en":"A student may decide not to join a club if it clashes with homework time.","zh":"如果社團活動與功課時間衝突，學生可能決定不加入。"},{"en":"If officials decide not to change a policy, protesters may feel ignored.","zh":"如果官員決定不改變政策，抗議者可能覺得被忽視。"},{"en":"This phrase describes a clear negative decision.","zh":"這個片語描述明確的否定決定。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":17},{"front":"follow protestors’ suggestions","meaning":"跟隨抗議者的建議","examples":[{"en":"The government may refuse to follow protestors’ suggestions.","zh":"政府可能拒絕跟隨抗議者的建議。"},{"en":"To follow protestors’ suggestions means to act according to what protesters ask for.","zh":"To follow protestors’ suggestions 指按照抗議者要求的內容行動。"},{"en":"A school may follow parents’ suggestions by changing lunch arrangements.","zh":"學校可能跟隨家長建議，改變午餐安排。"},{"en":"If leaders do not follow protestors’ suggestions, public frustration may increase.","zh":"如果領導者不跟隨抗議者的建議，公眾不滿可能增加。"},{"en":"This phrase connects public demands with official action.","zh":"這個片語把公眾要求與官方行動連接起來。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":17},{"front":"go ahead with","meaning":"繼續推行；着手進行","examples":[{"en":"The government has decided to go ahead with charging drivers.","zh":"政府已決定繼續推行向駕駛者收費。"},{"en":"To go ahead with something means to continue or begin it as planned.","zh":"To go ahead with something 指按計劃繼續或開始某事。"},{"en":"A school may go ahead with sports day even if the weather is cloudy.","zh":"即使天氣多雲，學校可能繼續舉行運動會。"},{"en":"If a government goes ahead with a charge, drivers will need to prepare for extra costs.","zh":"如果政府繼續推行收費，駕駛者便需要準備額外成本。"},{"en":"This phrase shows that a plan will proceed.","zh":"這個片語顯示計劃會進行。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":17},{"front":"charge drivers to use roads","meaning":"向駕駛者收取道路使用費","examples":[{"en":"The government plans to charge drivers to use roads.","zh":"政府計劃向駕駛者收取道路使用費。"},{"en":"To charge drivers to use roads means to make motorists pay for driving on certain roads.","zh":"To charge drivers to use roads 指要求駕駛者為使用某些道路付款。"},{"en":"A city may charge drivers to use roads in the busiest districts during rush hour.","zh":"城市可能在繁忙時間向在最擠塞地區使用道路的駕駛者收費。"},{"en":"If drivers are charged to use roads, some may switch to public transport.","zh":"如果駕駛者被收取道路使用費，一些人可能轉用公共交通。"},{"en":"This phrase describes road pricing in direct terms.","zh":"這個片語直接描述道路收費。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":17},{"front":"relatively cheap","meaning":"相對便宜","examples":[{"en":"Cars are often relatively cheap to buy in Britain.","zh":"在英國，汽車買入價通常相對便宜。"},{"en":"Relatively cheap means inexpensive compared with something else or compared with other costs.","zh":"Relatively cheap 指與其他東西或其他成本相比較便宜。"},{"en":"A printer may be relatively cheap to buy but expensive to refill with ink.","zh":"打印機買入價可能相對便宜，但補充墨水昂貴。"},{"en":"If cars are relatively cheap to buy, people may overlook the high cost of running them.","zh":"如果汽車買入價相對便宜，人們可能忽視高昂使用成本。"},{"en":"This phrase describes price by comparison, not total affordability.","zh":"這個片語描述比較下的價格，而不是整體可負擔程度。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":17},{"front":"relatively expensive to operate","meaning":"使用成本相對昂貴","examples":[{"en":"Cars are relatively expensive to operate in Britain.","zh":"在英國，汽車使用成本相對昂貴。"},{"en":"Relatively expensive to operate means costly to use and maintain compared with other options.","zh":"Relatively expensive to operate 指與其他選擇相比，使用和維持成本較高。"},{"en":"An old air conditioner may be relatively expensive to operate because it uses too much electricity.","zh":"舊冷氣機可能使用成本相對昂貴，因為它耗電太多。"},{"en":"If cars are expensive to operate, owners pay heavily after the purchase.","zh":"如果汽車使用成本昂貴，車主在購買後仍需支付大量費用。"},{"en":"This phrase focuses on running costs rather than buying costs.","zh":"這個片語著重使用成本，而不是購買成本。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":17},{"front":"sold second-hand","meaning":"以二手方式出售","examples":[{"en":"Many cars are sold second-hand.","zh":"許多汽車以二手方式出售。"},{"en":"Sold second-hand means sold after already being owned or used by someone else.","zh":"Sold second-hand 指某物在已被他人擁有或使用後出售。"},{"en":"Textbooks are often sold second-hand at the end of the school year.","zh":"教科書常在學年結束時以二手方式出售。"},{"en":"If cars are sold second-hand, buyers may pay less but should check their condition carefully.","zh":"如果汽車以二手方式出售，買家可能付較少錢，但應仔細檢查車況。"},{"en":"This phrase describes the resale of used goods.","zh":"這個片語描述已使用物品的轉售。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":18},{"front":"make up about","meaning":"約佔","examples":[{"en":"Fuel costs make up about one-fifth of the cost of running a car.","zh":"燃油成本約佔使用汽車成本的五分之一。"},{"en":"To make up about a share means to form approximately that part of the whole.","zh":"To make up about a share 指大約構成整體中的該部分。"},{"en":"Rent may make up about half of a student’s monthly budget.","zh":"租金可能約佔學生每月預算的一半。"},{"en":"If fuel makes up only about one-fifth of car costs, other expenses are larger.","zh":"如果燃油只約佔汽車成本的五分之一，其他開支就更大。"},{"en":"This phrase gives an approximate proportion.","zh":"這個片語提供近似比例。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":18},{"front":"be related to","meaning":"與……有關","examples":[{"en":"Some costs are related to how far you drive.","zh":"有些成本與你駕駛多遠有關。"},{"en":"To be related to something means to be connected with it.","zh":"To be related to something 指與某事有連繫。"},{"en":"A student’s tiredness may be related to late-night phone use.","zh":"學生疲倦可能與深夜使用手機有關。"},{"en":"Fuel costs are related to distance because longer journeys use more petrol.","zh":"燃油成本與距離有關，因為較長旅程使用更多汽油。"},{"en":"This phrase shows a connection between two things.","zh":"這個片語顯示兩件事之間的連繫。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":18},{"front":"the amount drivers pay for","meaning":"駕駛者為……所支付的金額","examples":[{"en":"Fuel costs are not directly related to the amount drivers pay for their cars.","zh":"燃油成本與駕駛者為汽車所支付的金額沒有直接關係。"},{"en":"The amount drivers pay for something means the money motorists spend on it.","zh":"The amount drivers pay for something 指駕駛者花在某事上的金錢。"},{"en":"The amount drivers pay for parking may be higher in city centres.","zh":"駕駛者為泊車所支付的金額在市中心可能較高。"},{"en":"If the amount drivers pay for fuel rises, some may reduce unnecessary journeys.","zh":"如果駕駛者為燃油所支付的金額上升，一些人可能減少不必要旅程。"},{"en":"This phrase focuses on the money paid by drivers.","zh":"這個片語著重駕駛者支付的金額。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":18},{"front":"depend on how far","meaning":"取決於……有多遠","examples":[{"en":"Fuel costs depend on how far you drive.","zh":"燃油成本取決於你駕駛多遠。"},{"en":"To depend on how far something happens means to change according to distance.","zh":"To depend on how far something happens 指根據距離而改變。"},{"en":"Taxi fares usually depend on how far passengers travel.","zh":"的士費通常取決於乘客乘搭多遠。"},{"en":"If fuel costs depend on how far you drive, short trips cost less than long trips.","zh":"如果燃油成本取決於你駕駛多遠，短途旅程會比長途旅程便宜。"},{"en":"This phrase links cost or result with distance.","zh":"這個片語把成本或結果與距離連接起來。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":18},{"front":"renting a car part of the time","meaning":"部分時間租車","examples":[{"en":"Using public transport and renting a car part of the time can save money.","zh":"使用公共交通並部分時間租車可以省錢。"},{"en":"Renting a car part of the time means hiring a car only for some journeys or periods.","zh":"Renting a car part of the time 指只為部分旅程或時段租用汽車。"},{"en":"A family may rent a car part of the time for holidays but use buses during the week.","zh":"家庭可能假期部分時間租車，但平日使用巴士。"},{"en":"If car use is occasional, renting part of the time may be cheaper than ownership.","zh":"如果只是偶爾用車，部分時間租車可能比擁有汽車便宜。"},{"en":"This phrase describes mixed transport instead of full car ownership.","zh":"這個片語描述混合交通方式，而不是完全擁有汽車。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":18},{"front":"save money","meaning":"省錢","examples":[{"en":"Reducing car use can save money.","zh":"減少汽車使用量可以省錢。"},{"en":"To save money means to spend less or keep more of your income.","zh":"To save money 指花費較少或保留更多收入。"},{"en":"Students can save money by bringing lunch from home.","zh":"學生可以透過從家中帶午餐來省錢。"},{"en":"If drivers share journeys, they may save money on fuel and parking.","zh":"如果駕駛者共享旅程，他們可能在燃油和泊車上省錢。"},{"en":"This phrase describes reducing expenses or keeping extra cash.","zh":"這個片語描述減少開支或保留額外現金。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":18},{"front":"cost Londoners about","meaning":"花費倫敦居民約……","examples":[{"en":"The most expensive annual Travelcard costs Londoners about £1,700 a year.","zh":"最昂貴的全年Travelcard交通卡每年花費倫敦居民約1,700英鎊。"},{"en":"To cost Londoners about an amount means to require people in London to pay approximately that amount.","zh":"To cost Londoners about an amount 指要求倫敦居民支付大約該金額。"},{"en":"A monthly phone plan may cost users about £20.","zh":"手機月費計劃可能花費使用者約20英鎊。"},{"en":"If public transport costs Londoners about £1,700 a year, it may still be cheaper than owning a car.","zh":"如果公共交通每年花費倫敦居民約1,700英鎊，它可能仍比擁有汽車便宜。"},{"en":"This phrase gives an approximate cost for a specific group of people.","zh":"這個片語為特定群體提供近似成本。"}],"source":"60 - Park the Car Permanently.pdf","sourcePage":18}],"ielts/reading/passage-2/Practice 61":[{"front":"Patients Are a Virtue","meaning":"「病人／耐心是一種美德」的雙關語","examples":[{"en":"The title “Patients Are a Virtue” plays on the expression “Patience is a virtue.”","zh":"標題 “Patients Are a Virtue” 玩弄了 “Patience is a virtue” 這個說法。"},{"en":"“Patients Are a Virtue” is a pun because “patients” sounds like “patience.”","zh":"“Patients Are a Virtue” 是雙關語，因為 patients 聽起來像 patience。"},{"en":"A newspaper might use this title for an article about hospitals and popular employers.","zh":"報章可能用這個標題寫一篇關於醫院和熱門僱主的文章。"},{"en":"The joke works because the article discusses patients, health services and careers.","zh":"這個笑位成立，因為文章討論病人、醫療服務和職業。"},{"en":"The title is memorable because it changes a familiar saying into a health-related joke.","zh":"這個標題令人容易記住，因為它把熟悉諺語改成與醫療有關的玩笑。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":1},{"front":"despite","meaning":"儘管","examples":[{"en":"Despite conference jeers, job cuts and a financial crisis, Patricia Hewitt may find a reason to smile.","zh":"儘管有會議上的嘲笑、裁員和財政危機，Patricia Hewitt 仍可能找到值得高興的理由。"},{"en":"Despite means although something difficult or negative is true.","zh":"despite 指雖然某件困難或負面的事是真的。"},{"en":"Despite heavy rain, the school picnic continued indoors.","zh":"儘管下大雨，學校野餐仍在室內繼續。"},{"en":"Despite poor sales last month, the shop stayed open because loyal customers returned.","zh":"儘管上月銷售差，商店仍然營業，因為忠實顧客回來了。"},{"en":"The word introduces a contrast between a problem and a surprising result.","zh":"這個字引出問題與意外結果之間的對比。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":1},{"front":"conference jeers","meaning":"會議上的嘲笑；喝倒彩","examples":[{"en":"The minister faced conference jeers before the NHS was praised in the survey.","zh":"在 NHS 於調查中受到讚揚前，這位大臣面對會議上的嘲笑。"},{"en":"Conference jeers are mocking sounds or comments made by people at a conference.","zh":"conference jeers 是會議上人們發出的嘲笑聲或批評說話。"},{"en":"A speaker may face conference jeers if the audience strongly dislikes a policy.","zh":"如果聽眾非常不喜歡某政策，演講者可能面對會議上的喝倒彩。"},{"en":"Conference jeers can embarrass a leader and show public anger within a party or organisation.","zh":"會議上的嘲笑可以令領袖尷尬，並顯示政黨或組織內部的憤怒。"},{"en":"The phrase describes open criticism, not quiet disagreement.","zh":"這個短語描述公開批評，而不是安靜分歧。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":1},{"front":"job cuts","meaning":"裁員","examples":[{"en":"The health service was praised despite job cuts.","zh":"儘管有裁員，醫療服務機構仍受到讚揚。"},{"en":"Job cuts are reductions in the number of workers employed by an organisation.","zh":"job cuts 是機構減少僱用員工數目的做法。"},{"en":"A company may announce job cuts when it cannot afford all its staff.","zh":"當公司負擔不起所有員工時，可能宣布裁員。"},{"en":"Job cuts can lower costs, but they may also increase pressure on remaining workers.","zh":"裁員可以降低成本，但也可能增加剩餘員工的壓力。"},{"en":"The phrase usually suggests a difficult financial or organisational situation.","zh":"這個短語通常暗示財務或組織處境困難。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":1},{"front":"financial crisis","meaning":"財政危機","examples":[{"en":"The NHS was named a top employer despite a financial crisis.","zh":"儘管有財政危機，NHS 仍被評為理想僱主。"},{"en":"A financial crisis is a serious situation in which money problems threaten normal operation.","zh":"financial crisis 是金錢問題威脅正常運作的嚴重情況。"},{"en":"A school may face a financial crisis if funding is suddenly reduced.","zh":"如果資助突然減少，學校可能面對財政危機。"},{"en":"A financial crisis can lead to budget cuts, job losses and delayed projects.","zh":"財政危機可以導致削減預算、裁員和延遲項目。"},{"en":"The phrase describes more than a small money problem.","zh":"這個短語描述的不只是小金錢問題。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":1},{"front":"Health Secretary","meaning":"衞生大臣","examples":[{"en":"Patricia Hewitt was the Health Secretary mentioned in the article.","zh":"Patricia Hewitt 是文章提及的衞生大臣。"},{"en":"A Health Secretary is a government minister responsible for health services.","zh":"Health Secretary 是負責醫療服務的政府大臣。"},{"en":"The Health Secretary may answer questions about hospitals, doctors and public health policy.","zh":"衞生大臣可能回答關於醫院、醫生和公共衞生政策的問題。"},{"en":"If hospitals face a crisis, the Health Secretary may receive public criticism.","zh":"如果醫院面對危機，衞生大臣可能受到公眾批評。"},{"en":"The phrase names a senior political role in healthcare.","zh":"這個短語指出醫療保健中的高級政治職位。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":1},{"front":"find a reason to smile","meaning":"找到值得高興的理由","examples":[{"en":"Patricia Hewitt may find a reason to smile this week.","zh":"Patricia Hewitt 本星期可能找到值得高興的理由。"},{"en":"To find a reason to smile means to discover something positive in a difficult situation.","zh":"find a reason to smile 指在困難情況中發現正面的事。"},{"en":"A student may find a reason to smile after passing a test she expected to fail.","zh":"學生原本以為考試會不合格，結果合格後可能找到值得高興的理由。"},{"en":"Good news can help someone find a reason to smile after weeks of stress.","zh":"好消息可以幫助人在數星期壓力後找到值得高興的理由。"},{"en":"The phrase suggests relief or happiness after trouble.","zh":"這個短語暗示困難後的安慰或快樂。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":1},{"front":"the NHS","meaning":"英國國民保健服務","examples":[{"en":"The NHS was named one of the top places to work by students.","zh":"NHS 被學生評為最理想工作地點之一。"},{"en":"The NHS is the UK’s public health service.","zh":"the NHS 是英國的公共醫療服務。"},{"en":"Many people rely on the NHS for hospital care, clinics and emergency treatment.","zh":"許多人依靠 NHS 接受住院護理、診所服務和急症治療。"},{"en":"If students see the NHS as a good employer, it may attract graduates from many subjects.","zh":"如果學生把 NHS 視為好僱主，它可能吸引來自多種學科的畢業生。"},{"en":"The phrase refers to a large public healthcare organisation.","zh":"這個短語指一個大型公共醫療機構。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":1},{"front":"be named one of","meaning":"被評為……之一","examples":[{"en":"The NHS was named one of the top places to work.","zh":"NHS 被評為最理想工作地點之一。"},{"en":"To be named one of something means to be officially listed as part of a top group.","zh":"be named one of 某類別，指被正式列為某個優秀群體的一部分。"},{"en":"A school may be named one of the safest schools in the city.","zh":"一間學校可能被評為全城最安全學校之一。"},{"en":"If a company is named one of the best employers, more graduates may apply.","zh":"如果公司被評為最佳僱主之一，更多畢業生可能申請。"},{"en":"The phrase shows public recognition or ranking.","zh":"這個短語表示公開認可或排名。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":1},{"front":"top places to work","meaning":"最理想工作地點","examples":[{"en":"Students considered the NHS one of the top places to work.","zh":"學生認為 NHS 是最理想工作地點之一。"},{"en":"Top places to work are employers that many people regard as attractive or desirable.","zh":"top places to work 是許多人認為吸引或理想的僱主。"},{"en":"A company with fair pay and good training may become one of the top places to work.","zh":"一間有公平薪酬和良好培訓的公司可能成為最理想工作地點之一。"},{"en":"If an organisation is seen as a top place to work, recruitment becomes easier.","zh":"如果機構被視為最理想工作地點，招聘會變得更容易。"},{"en":"The phrase describes workplace appeal, not physical location only.","zh":"這個短語描述工作場所吸引力，而不只是實際地點。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":1},{"front":"among engineering, science and IT students","meaning":"在工程、科學和資訊科技學生之中","examples":[{"en":"Among engineering, science and IT students, the health service was ranked second.","zh":"在工程、科學和資訊科技學生之中，醫療服務機構排名第二。"},{"en":"Among engineering, science and IT students means within that group of students.","zh":"among engineering, science and IT students 指在該組學生之內。"},{"en":"Among engineering, science and IT students, employers with training schemes may be especially popular.","zh":"在工程、科學和資訊科技學生之中，有培訓計劃的僱主可能特別受歡迎。"},{"en":"If an organisation ranks highly among this group, it may appeal to technical graduates.","zh":"如果機構在這個群體中排名高，它可能吸引技術科畢業生。"},{"en":"The phrase limits the result to specific subject areas.","zh":"這個短語把結果限制在特定學科範圍內。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":2},{"front":"the health service","meaning":"醫療服務機構","examples":[{"en":"The health service was ranked second in the graduate survey.","zh":"醫療服務機構在畢業生調查中排名第二。"},{"en":"The health service means the organisation or system that provides healthcare to the public.","zh":"the health service 指向公眾提供醫療保健的組織或系統。"},{"en":"A strong health service needs doctors, nurses, engineers, managers and IT staff.","zh":"強大的醫療服務機構需要醫生、護士、工程師、管理人員和資訊科技員工。"},{"en":"If the health service is trusted, people may feel safer during illness.","zh":"如果醫療服務機構受信任，人們生病時可能感到更安全。"},{"en":"The phrase can refer to the NHS in this article.","zh":"在這篇文章中，這個短語可以指 NHS。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":2},{"front":"be ranked second","meaning":"排名第二","examples":[{"en":"The health service was ranked second in the survey.","zh":"醫療服務機構在調查中排名第二。"},{"en":"To be ranked second means to be placed in the number two position.","zh":"be ranked second 指被排在第二位。"},{"en":"A student may be ranked second in a speaking competition after a very close final.","zh":"學生在非常接近的決賽後，可能在口語比賽中排名第二。"},{"en":"If a company is ranked second, it is highly regarded but not first.","zh":"如果公司排名第二，它很受重視，但不是第一。"},{"en":"The phrase describes position in an ordered list.","zh":"這個短語描述有次序名單中的位置。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":2},{"front":"graduate survey","meaning":"畢業生調查","examples":[{"en":"The Universum UK graduate survey asked students about ideal employers.","zh":"Universum 英國畢業生調查詢問學生關於理想僱主的看法。"},{"en":"A graduate survey is a study that collects opinions from university students or graduates.","zh":"graduate survey 是收集大學生或畢業生意見的研究。"},{"en":"A graduate survey may ask students what salary, training and work culture they want.","zh":"畢業生調查可能詢問學生想要甚麼薪金、培訓和工作文化。"},{"en":"If a graduate survey shows changing priorities, employers may adjust recruitment plans.","zh":"如果畢業生調查顯示優先事項改變，僱主可能調整招聘計劃。"},{"en":"The phrase refers to research about students entering the job market.","zh":"這個短語指關於學生進入就業市場的研究。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":2},{"front":"ideal employers","meaning":"理想僱主","examples":[{"en":"Students selected the employers they considered to be ideal employers.","zh":"學生選出他們認為是理想僱主的機構。"},{"en":"Ideal employers are organisations that students most want to work for.","zh":"ideal employers 是學生最想為其工作的機構。"},{"en":"An ideal employer may offer training, fair pay, good culture and career growth.","zh":"理想僱主可能提供培訓、公平薪酬、良好文化和事業發展。"},{"en":"If students see a company as an ideal employer, it gains an advantage in recruitment.","zh":"如果學生把公司視為理想僱主，它在招聘上就有優勢。"},{"en":"The phrase describes preference, not necessarily actual job availability.","zh":"這個短語描述偏好，不一定代表實際有職位。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":2},{"front":"a leap of 54 places","meaning":"躍升54位","examples":[{"en":"The NHS made a leap of 54 places from last year.","zh":"NHS 較去年躍升54位。"},{"en":"A leap of 54 places means moving upward by 54 positions in a ranking.","zh":"a leap of 54 places 指在排名中向上移動54個位置。"},{"en":"A university may make a leap of 20 places after improving teaching and research.","zh":"大學在改善教學和研究後，可能躍升20位。"},{"en":"If an employer makes a large leap, its reputation among students has improved sharply.","zh":"如果僱主大幅躍升，它在學生之間的聲譽已明顯改善。"},{"en":"The phrase describes a big rise, not a small improvement.","zh":"這個短語描述大幅上升，而不是小改善。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":2},{"front":"annual survey","meaning":"年度調查","examples":[{"en":"The annual survey has been conducted in the UK since 1997.","zh":"這項年度調查自1997年起在英國進行。"},{"en":"An annual survey is a survey carried out once every year.","zh":"annual survey 是每年進行一次的調查。"},{"en":"A school may run an annual survey to ask parents about teaching and facilities.","zh":"學校可能進行年度調查，詢問家長對教學和設施的意見。"},{"en":"If an annual survey repeats the same questions, changes over time become easier to see.","zh":"如果年度調查重複同樣問題，長期變化會更容易看見。"},{"en":"The phrase connects research with a yearly schedule.","zh":"這個短語把研究與每年時間表連繫起來。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":2},{"front":"conducted in the UK","meaning":"在英國進行","examples":[{"en":"The survey has been conducted in the UK since 1997.","zh":"該調查自1997年起在英國進行。"},{"en":"Conducted in the UK means carried out within the United Kingdom.","zh":"conducted in the UK 指在英國境內進行。"},{"en":"A study conducted in the UK may not always describe students in other countries.","zh":"在英國進行的研究未必總能描述其他國家的學生。"},{"en":"If a survey is conducted in one country, its results should be read in that context.","zh":"如果調查在一個國家進行，其結果應放在該背景下閱讀。"},{"en":"The phrase identifies where the research took place.","zh":"這個短語指出研究在哪裏進行。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":2},{"front":"canvass the opinions of","meaning":"徵詢……的意見","examples":[{"en":"The survey canvassed the opinions of more than 7,700 students.","zh":"該調查徵詢了超過7,700名學生的意見。"},{"en":"To canvass the opinions of people means to ask many people what they think.","zh":"canvass the opinions of 人們，指詢問許多人有甚麼看法。"},{"en":"A school may canvass the opinions of parents before changing the uniform policy.","zh":"學校在改變校服政策前，可能徵詢家長意見。"},{"en":"If leaders canvass opinions widely, they can understand support and opposition better.","zh":"如果領導者廣泛徵詢意見，就能更好理解支持和反對。"},{"en":"The phrase describes organised collection of views.","zh":"這個短語描述有組織地收集看法。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":2},{"front":"final-year students","meaning":"最後一年學生","examples":[{"en":"The survey included final-year students at 39 universities.","zh":"調查包括39間大學的最後一年學生。"},{"en":"Final-year students are students in the last year of their course.","zh":"final-year students 是課程最後一年中的學生。"},{"en":"Final-year students often think seriously about jobs, interviews and graduate schemes.","zh":"最後一年學生常認真思考工作、面試和畢業生計劃。"},{"en":"Because final-year students are close to graduation, employers want to understand their choices.","zh":"因為最後一年學生接近畢業，僱主想了解他們的選擇。"},{"en":"The phrase identifies students nearing the end of university study.","zh":"這個短語指出接近完成大學學習的學生。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":2},{"front":"penultimate-year students","meaning":"倒數第二年學生","examples":[{"en":"The survey included penultimate-year students as well as final-year students.","zh":"調查包括倒數第二年學生以及最後一年學生。"},{"en":"Penultimate-year students are students in the year before their final year.","zh":"penultimate-year students 是最後一年之前那一年的學生。"},{"en":"Penultimate-year students may start applying for internships before graduate recruitment begins.","zh":"倒數第二年學生可能在畢業生招聘開始前申請實習。"},{"en":"If employers reach penultimate-year students early, they can build interest before graduation.","zh":"如果僱主及早接觸倒數第二年學生，就能在畢業前建立興趣。"},{"en":"The phrase means second-to-last-year students.","zh":"這個短語意思是倒數第二年學生。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":3},{"front":"studying for degrees in","meaning":"修讀……學位","examples":[{"en":"The students were studying for degrees in business, science and other subjects.","zh":"這些學生修讀商科、科學和其他學科的學位。"},{"en":"Studying for degrees in a subject means taking university courses to earn that qualification.","zh":"studying for degrees in 某學科，指修讀大學課程以取得該資格。"},{"en":"Students studying for degrees in engineering often complete projects and laboratory work.","zh":"修讀工程學位的學生常完成項目和實驗室工作。"},{"en":"If students study for degrees in different subjects, their career interests may differ.","zh":"如果學生修讀不同學科的學位，他們的事業興趣可能不同。"},{"en":"The phrase connects students with their university fields.","zh":"這個短語把學生與其大學學科連繫起來。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":3},{"front":"the humanities","meaning":"人文學科","examples":[{"en":"The survey included students studying the humanities.","zh":"調查包括修讀人文學科的學生。"},{"en":"The humanities are subjects such as history, languages, literature and philosophy.","zh":"the humanities 是歷史、語言、文學和哲學等學科。"},{"en":"Humanities students often read, write, discuss ideas and analyse culture.","zh":"人文學科學生常閱讀、寫作、討論想法和分析文化。"},{"en":"If employers value communication, humanities graduates may have useful skills.","zh":"如果僱主重視溝通，人文學科畢業生可能有有用技能。"},{"en":"The phrase refers to human culture and thought, not laboratory science.","zh":"這個短語指人類文化和思想，而不是實驗室科學。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":3},{"front":"be presented with","meaning":"獲提供；被展示","examples":[{"en":"Each student was presented with a list of 130 employers.","zh":"每名學生獲提供一份有130個僱主的名單。"},{"en":"To be presented with something means to be given or shown it.","zh":"be presented with 某物，指獲給予或被展示該物。"},{"en":"Students may be presented with several course options before choosing electives.","zh":"學生在選擇選修科前，可能獲提供幾個課程選項。"},{"en":"If people are presented with too many choices, they may need clear categories.","zh":"如果人們獲提供太多選擇，可能需要清楚分類。"},{"en":"The phrase describes receiving information for consideration.","zh":"這個短語描述收到資訊以作考慮。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":3},{"front":"a list of 130 employers","meaning":"一份有130個僱主的名單","examples":[{"en":"Each student selected ideal employers from a list of 130 employers.","zh":"每名學生從一份有130個僱主的名單中選出理想僱主。"},{"en":"A list of 130 employers is a set of 130 organisations offered as choices.","zh":"a list of 130 employers 是一組包含130個機構的選項。"},{"en":"A careers office may give students a list of employers attending a job fair.","zh":"就業中心可能向學生提供參加招聘會的僱主名單。"},{"en":"If the list is long, students need criteria to choose the best options.","zh":"如果名單很長，學生需要標準來選出最佳選項。"},{"en":"The phrase refers to the survey’s fixed choice list.","zh":"這個短語指調查中的固定選擇名單。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":3},{"front":"nominated by","meaning":"由……提名","examples":[{"en":"The employers were nominated by students through a separate process.","zh":"這些僱主透過另一個程序由學生提名。"},{"en":"Nominated by someone means suggested or put forward by that person or group.","zh":"nominated by 某人，指由該人或群體建議或提出。"},{"en":"A teacher may be nominated by students for a teaching award.","zh":"老師可能由學生提名參選教學獎。"},{"en":"If an organisation is nominated by many students, it may enter the final survey list.","zh":"如果機構由許多學生提名，它可能進入最終調查名單。"},{"en":"The phrase identifies who proposed the name.","zh":"這個短語指出名稱由誰提出。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":3},{"front":"through a separate process","meaning":"透過另一個程序","examples":[{"en":"The employers were nominated through a separate process.","zh":"這些僱主透過另一個程序提名。"},{"en":"Through a separate process means by using another procedure, not the main one.","zh":"through a separate process 指使用另一套程序，而不是主要程序。"},{"en":"Scholarship candidates may be chosen through a separate process from normal admissions.","zh":"獎學金候選人可能透過與一般入學不同的程序選出。"},{"en":"If names are collected through a separate process, the final list has an earlier selection stage.","zh":"如果名稱透過另一個程序收集，最終名單就有早前篩選階段。"},{"en":"The phrase separates one method from another.","zh":"這個短語把一種方法與另一種分開。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":3},{"front":"select the five","meaning":"選出五個","examples":[{"en":"Students selected the five employers they considered ideal.","zh":"學生選出他們認為理想的五個僱主。"},{"en":"To select the five means to choose exactly five items from a larger group.","zh":"select the five 指從較大群體中剛好選出五個項目。"},{"en":"In a class vote, students may select the five activities they most want for sports day.","zh":"在班級投票中，學生可能選出他們最想在運動會做的五項活動。"},{"en":"If students must select only five, they have to prioritise their strongest preferences.","zh":"如果學生只能選五個，他們必須優先考慮最強偏好。"},{"en":"The phrase gives both an action and a fixed number.","zh":"這個短語同時給出行動和固定數量。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":3},{"front":"consider something to be","meaning":"認為……是","examples":[{"en":"Students selected the employers they considered to be ideal.","zh":"學生選出他們認為是理想的僱主。"},{"en":"To consider something to be a certain way means to judge or think of it that way.","zh":"consider something to be 某樣子，指判斷或認為它是那樣。"},{"en":"Many parents consider safety to be the most important feature of a school bus.","zh":"許多家長認為安全是校巴最重要的特點。"},{"en":"If students consider an employer to be supportive, they may apply there first.","zh":"如果學生認為某僱主支持員工，他們可能先申請那裏。"},{"en":"The phrase introduces someone’s opinion or judgement.","zh":"這個短語引出某人的看法或判斷。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":3},{"front":"be based on","meaning":"以……為基礎","examples":[{"en":"The Universum list is based on the frequency of an organisation being selected.","zh":"Universum 名單以某機構被選中的頻率為基礎。"},{"en":"To be based on something means to use it as the main foundation or evidence.","zh":"be based on 某事，指以它作為主要基礎或證據。"},{"en":"A teacher may base a study plan on a student’s weakest skills.","zh":"老師可能根據學生最弱的技能制定溫習計劃。"},{"en":"If a ranking is based on survey choices, it reflects people’s preferences.","zh":"如果排名以調查選擇為基礎，它就反映人們的偏好。"},{"en":"The phrase explains what information supports a result.","zh":"這個短語解釋結果由甚麼資訊支持。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":3},{"front":"frequency of","meaning":"……的頻率","examples":[{"en":"The list depends on the frequency of an organisation being selected.","zh":"該名單取決於某機構被選中的頻率。"},{"en":"Frequency of something means how often it happens.","zh":"frequency of 某事，指它發生得有多頻繁。"},{"en":"A doctor may ask about the frequency of headaches before choosing tests.","zh":"醫生在選擇檢查前，可能詢問頭痛的頻率。"},{"en":"If the frequency of a company’s selection is high, it appears more popular.","zh":"如果公司被選中的頻率高，它看起來更受歡迎。"},{"en":"The phrase measures repeated occurrence.","zh":"這個短語量度重複出現的次數。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":4},{"front":"following a weighting process","meaning":"經過加權程序後","examples":[{"en":"The final list was produced following a weighting process.","zh":"最終名單經過加權程序後產生。"},{"en":"Following a weighting process means after results were adjusted according to set importance or value.","zh":"following a weighting process 指結果按照設定重要性或價值調整之後。"},{"en":"A school prize may be decided following a weighting process that counts effort and achievement differently.","zh":"學校獎項可能經過加權程序決定，把努力和成績以不同權重計算。"},{"en":"If survey answers are weighted, some groups or answers may count more than others.","zh":"如果調查答案被加權，有些群體或答案可能比其他更重要。"},{"en":"The phrase describes a calculation step before the final result.","zh":"這個短語描述最終結果前的一個計算步驟。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":4},{"front":"government departments","meaning":"政府部門","examples":[{"en":"Government departments dominated the top spots this year.","zh":"政府部門今年佔據最高排名。"},{"en":"Government departments are official parts of government responsible for particular areas of public work.","zh":"government departments 是政府中負責特定公共工作範疇的官方部門。"},{"en":"Education, transport and health may each have government departments managing policy.","zh":"教育、交通和衞生可能各有政府部門負責政策。"},{"en":"If government departments attract graduates, public service may gain new talent.","zh":"如果政府部門吸引畢業生，公共服務可能得到新人才。"},{"en":"The phrase refers to public bodies, not private companies.","zh":"這個短語指公共機構，而不是私人公司。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":4},{"front":"public sector organisations","meaning":"公營機構","examples":[{"en":"Public sector organisations dominated the top spots in the survey.","zh":"公營機構在調查中佔據最高排名。"},{"en":"Public sector organisations are bodies funded or run by government to serve the public.","zh":"public sector organisations 是由政府資助或營運、服務公眾的機構。"},{"en":"Hospitals, councils and public agencies are examples of public sector organisations.","zh":"醫院、市議會和公共機構都是公營機構的例子。"},{"en":"If public sector organisations rank highly, students may value public service and stability.","zh":"如果公營機構排名高，學生可能重視公共服務和穩定性。"},{"en":"The phrase contrasts public employers with private businesses.","zh":"這個短語把公營僱主與私人企業作對比。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":4},{"front":"dominate the top spots","meaning":"佔據最高排名","examples":[{"en":"Government departments and public sector organisations dominated the top spots.","zh":"政府部門和公營機構佔據最高排名。"},{"en":"To dominate the top spots means to occupy most of the highest positions in a ranking.","zh":"dominate the top spots 指佔據排名中大部分最高位置。"},{"en":"Local schools may dominate the top spots in a debate competition.","zh":"本地學校可能在辯論比賽中佔據最高排名。"},{"en":"If one type of employer dominates the top spots, it shows strong popularity in that survey.","zh":"如果某類僱主佔據最高排名，這顯示它在該調查中很受歡迎。"},{"en":"The phrase suggests clear control of the highest ranks.","zh":"這個短語暗示明顯掌控最高名次。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":4},{"front":"ranked first among","meaning":"在……之中排名第一","examples":[{"en":"The BBC was ranked first among several groups of students.","zh":"BBC 在幾個學生群體中排名第一。"},{"en":"Ranked first among a group means placed number one within that group.","zh":"ranked first among 某群體，指在該群體中排第一。"},{"en":"A university may be ranked first among local schools for student satisfaction.","zh":"大學可能在本地院校中就學生滿意度排名第一。"},{"en":"If an employer is ranked first among humanities students, it is their top choice.","zh":"如果僱主在人文學科學生中排名第一，它就是他們的首選。"},{"en":"The phrase links a top position with a specific group.","zh":"這個短語把第一位置與特定群體連繫起來。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":4},{"front":"retain its place","meaning":"保持原有排名","examples":[{"en":"The BBC retained its place from last year.","zh":"BBC 保持了去年的原有排名。"},{"en":"To retain its place means to keep the same position in a ranking.","zh":"retain its place 指在排名中保持同一位置。"},{"en":"A school team may retain its place at the top after winning again.","zh":"學校隊伍再次勝出後，可能保持榜首位置。"},{"en":"If a company retains its place, its reputation has stayed strong.","zh":"如果公司保持原有排名，它的聲譽仍然強。"},{"en":"The phrase describes stability in ranking.","zh":"這個短語描述排名穩定。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":4},{"front":"come third for","meaning":"在……中排名第三","examples":[{"en":"The BBC came third for students studying business.","zh":"BBC 在商科學生中排名第三。"},{"en":"To come third for a group means to be ranked in third place by that group.","zh":"come third for 某群體，指被該群體排在第三位。"},{"en":"A bank may come third for business students who prefer finance careers.","zh":"對偏好金融事業的商科學生而言，銀行可能排名第三。"},{"en":"If an employer comes third, it is popular but has two competitors ahead of it.","zh":"如果僱主排名第三，它受歡迎，但前面有兩個競爭者。"},{"en":"The phrase identifies a ranking result for a specific group.","zh":"這個短語指出特定群體中的排名結果。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":4},{"front":"humanities students","meaning":"人文學科學生","examples":[{"en":"Among humanities students, the BBC was followed by several public bodies.","zh":"在人文學科學生之中，BBC 之後是幾個公共機構。"},{"en":"Humanities students are students studying subjects such as history, languages and literature.","zh":"humanities students 是修讀歷史、語言和文學等學科的學生。"},{"en":"Humanities students may value communication, culture, public service and social impact.","zh":"人文學科學生可能重視溝通、文化、公共服務和社會影響。"},{"en":"If humanities students prefer public bodies, they may be seeking meaningful work.","zh":"如果人文學科學生偏好公共機構，他們可能在尋找有意義的工作。"},{"en":"The phrase identifies students in non-science cultural and social subjects.","zh":"這個短語指出修讀非科學文化和社會學科的學生。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":4},{"front":"be followed closely by","meaning":"緊隨其後的是","examples":[{"en":"The BBC was followed closely by the Foreign and Commonwealth Office.","zh":"BBC 緊隨其後的是英國外交及聯邦事務部。"},{"en":"To be followed closely by something means the next item is only slightly behind.","zh":"be followed closely by 某物，指下一項只稍微落後。"},{"en":"In a race, the leader may be followed closely by two runners.","zh":"在比賽中，領先者可能緊隨其後有兩名跑手。"},{"en":"If one employer is followed closely by another, their popularity is similar.","zh":"如果一個僱主緊隨其後的是另一僱主，兩者受歡迎程度相近。"},{"en":"The phrase shows a narrow gap in ranking or position.","zh":"這個短語顯示排名或位置差距很小。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":4},{"front":"Foreign and Commonwealth Office","meaning":"英國外交及聯邦事務部","examples":[{"en":"The Foreign and Commonwealth Office was popular among humanities students.","zh":"英國外交及聯邦事務部在人文學科學生中受歡迎。"},{"en":"The Foreign and Commonwealth Office was a UK government department dealing with foreign affairs.","zh":"Foreign and Commonwealth Office 是處理外交事務的英國政府部門。"},{"en":"Students interested in diplomacy may see the Foreign and Commonwealth Office as attractive.","zh":"對外交有興趣的學生可能覺得英國外交及聯邦事務部吸引。"},{"en":"If graduates join a foreign affairs department, they may work on international relations.","zh":"如果畢業生加入外交部門，他們可能從事國際關係工作。"},{"en":"The phrase names a public employer linked with diplomacy and government work.","zh":"這個短語指出一個與外交和政府工作相關的公營僱主。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":5},{"front":"Civil Service fast stream","meaning":"公務員快速晉升計劃","examples":[{"en":"The Civil Service fast stream was highly ranked by humanities students.","zh":"公務員快速晉升計劃在人文學科學生中排名很高。"},{"en":"The Civil Service fast stream is a graduate route for future government leaders.","zh":"Civil Service fast stream 是培養未來政府領袖的畢業生途徑。"},{"en":"A student interested in public policy may apply for the Civil Service fast stream.","zh":"對公共政策有興趣的學生可能申請公務員快速晉升計劃。"},{"en":"If a programme offers rapid training and responsibility, it may attract ambitious graduates.","zh":"如果計劃提供快速培訓和責任，它可能吸引有抱負的畢業生。"},{"en":"The phrase refers to a structured government graduate scheme.","zh":"這個短語指一個有結構的政府畢業生計劃。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":5},{"front":"not far behind","meaning":"落後不遠","examples":[{"en":"The Cabinet Office and the Ministry of Defence were not far behind.","zh":"內閣辦公室和國防部落後不遠。"},{"en":"Not far behind means only a little lower or later than others.","zh":"not far behind 指只比其他人稍低或稍遲。"},{"en":"In a class test, the second student may be not far behind the first.","zh":"在班級測驗中，第二名學生可能落後第一名不遠。"},{"en":"If a company is not far behind the leader, it still has strong support.","zh":"如果公司落後領先者不遠，它仍有強大支持。"},{"en":"The phrase shows a small gap rather than a large difference.","zh":"這個短語顯示小差距，而不是大差異。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":5},{"front":"ranked fifth and sixth respectively","meaning":"分別排名第五和第六","examples":[{"en":"The two departments were ranked fifth and sixth respectively.","zh":"兩個部門分別排名第五和第六。"},{"en":"Ranked fifth and sixth respectively means the first named was fifth and the second named was sixth.","zh":"ranked fifth and sixth respectively 指首先提到的排名第五，其次提到的排名第六。"},{"en":"Tom and Anna came second and third respectively means Tom was second and Anna was third.","zh":"Tom 和 Anna 分別第二和第三，意思是 Tom 第二，Anna 第三。"},{"en":"If two results are given respectively, readers must match them in the same order.","zh":"如果兩個結果以 respectively 給出，讀者必須按相同次序配對。"},{"en":"The phrase avoids confusion when comparing two ranked items.","zh":"這個短語避免比較兩個排名項目時混亂。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":5},{"front":"as well as","meaning":"除了……之外","examples":[{"en":"As well as the NHS, engineering students favoured the Environment Agency.","zh":"除了 NHS 之外，工程學生也偏好環境署。"},{"en":"As well as means in addition to another person, thing or group.","zh":"as well as 指除另一人、事物或群體之外也包括。"},{"en":"Students may need writing practice as well as speaking practice.","zh":"學生可能需要寫作練習，也需要口語練習。"},{"en":"If a job offers training as well as travel, graduates may find it more attractive.","zh":"如果工作除了旅遊機會外也提供培訓，畢業生可能覺得更吸引。"},{"en":"The phrase adds another item without removing the first.","zh":"這個短語加入另一項，而不是移除第一項。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":5},{"front":"favour an employer","meaning":"偏好某僱主","examples":[{"en":"Engineering, science and IT students favoured the Environment Agency.","zh":"工程、科學和資訊科技學生偏好環境署。"},{"en":"To favour an employer means to prefer that organisation as a place to work.","zh":"favour an employer 指偏好某機構作為工作地點。"},{"en":"Students may favour an employer that offers training, stability and meaningful work.","zh":"學生可能偏好提供培訓、穩定性和有意義工作的僱主。"},{"en":"If graduates favour an employer, the employer may receive more applications.","zh":"如果畢業生偏好某僱主，該僱主可能收到更多申請。"},{"en":"The phrase describes preference in career choice.","zh":"這個短語描述事業選擇中的偏好。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":5},{"front":"the Environment Agency","meaning":"環境署","examples":[{"en":"The Environment Agency leapt 83 places in the survey.","zh":"環境署在調查中躍升83位。"},{"en":"The Environment Agency is a public body connected with environmental protection and management.","zh":"the Environment Agency 是與環境保護和管理相關的公共機構。"},{"en":"Students interested in climate, rivers and pollution may favour the Environment Agency.","zh":"對氣候、河流和污染有興趣的學生可能偏好環境署。"},{"en":"If environmental issues become more important, agencies like this may attract more graduates.","zh":"如果環境議題變得更重要，這類機構可能吸引更多畢業生。"},{"en":"The phrase names a public-sector employer in the article.","zh":"這個短語指出文章中的一個公營僱主。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":5},{"front":"leap 83 places","meaning":"躍升83位","examples":[{"en":"The Environment Agency leapt 83 places this year.","zh":"環境署今年躍升83位。"},{"en":"To leap 83 places means to rise by 83 positions in a ranking.","zh":"leap 83 places 指在排名中上升83個位置。"},{"en":"A university may leap 30 places after improving research and student support.","zh":"大學在改善研究和學生支援後，可能躍升30位。"},{"en":"If an employer leaps many places, its image has improved sharply.","zh":"如果僱主躍升許多位，它的形象已大幅改善。"},{"en":"The phrase describes a dramatic upward movement.","zh":"這個短語描述劇烈向上移動。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":5},{"front":"accountancy giants","meaning":"會計業巨頭","examples":[{"en":"Business students voted accountancy giants PwC as their favoured employer.","zh":"商科學生把會計業巨頭 PwC 選為他們偏好的僱主。"},{"en":"Accountancy giants are very large and powerful accounting firms.","zh":"accountancy giants 是非常大型且有影響力的會計師行。"},{"en":"Accountancy giants often recruit graduates for audit, tax and consulting work.","zh":"會計業巨頭常招聘畢業生從事審計、稅務和顧問工作。"},{"en":"If accountancy giants visit campuses often, business students may know them well.","zh":"如果會計業巨頭經常到訪校園，商科學生可能很熟悉它們。"},{"en":"The phrase emphasises size and influence in the accounting industry.","zh":"這個短語強調會計行業中的規模和影響力。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":5},{"front":"favoured employer","meaning":"受青睞的僱主","examples":[{"en":"PwC was the favoured employer among business students.","zh":"PwC 是商科學生中受青睞的僱主。"},{"en":"A favoured employer is an organisation that a group especially wants to work for.","zh":"favoured employer 是某群體特別想為其工作的機構。"},{"en":"A bank may become a favoured employer if it offers strong training and clear promotion.","zh":"如果銀行提供強大培訓和清晰晉升，它可能成為受青睞的僱主。"},{"en":"If a company is a favoured employer, it can attract talented applicants more easily.","zh":"如果公司是受青睞的僱主，它更容易吸引有才華的申請者。"},{"en":"The phrase describes popularity among job seekers.","zh":"這個短語描述求職者之間的受歡迎程度。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":5},{"front":"awards ceremony","meaning":"頒獎典禮","examples":[{"en":"The comments were made at a London awards ceremony.","zh":"這些評論是在倫敦頒獎典禮上作出的。"},{"en":"An awards ceremony is an event where prizes or honours are officially given.","zh":"awards ceremony 是正式頒發獎項或榮譽的活動。"},{"en":"A school may hold an awards ceremony to celebrate students’ effort and progress.","zh":"學校可能舉行頒獎典禮，表揚學生的努力和進步。"},{"en":"If an organisation is praised at an awards ceremony, its public image may improve.","zh":"如果機構在頒獎典禮上受到讚揚，其公眾形象可能改善。"},{"en":"The phrase refers to a formal celebration of achievement.","zh":"這個短語指正式慶祝成就的活動。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":6},{"front":"sponsored by","meaning":"由……贊助","examples":[{"en":"The awards ceremony was sponsored by the Guardian.","zh":"頒獎典禮由 Guardian 贊助。"},{"en":"Sponsored by someone means financially or publicly supported by that person or organisation.","zh":"sponsored by 某人或機構，指由其提供財務或公開支持。"},{"en":"A school race may be sponsored by a local sports shop.","zh":"學校跑步比賽可能由本地運動用品店贊助。"},{"en":"If an event is sponsored by a famous newspaper, it may gain more attention.","zh":"如果活動由著名報章贊助，它可能得到更多關注。"},{"en":"The phrase identifies who supports an event.","zh":"這個短語指出誰支持某活動。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":6},{"front":"head of NHS Careers","meaning":"NHS Careers主管","examples":[{"en":"Foluke Ajayi was head of NHS Careers at NHS Employers.","zh":"Foluke Ajayi 是 NHS Employers 旗下 NHS Careers 的主管。"},{"en":"The head of NHS Careers is the person leading career information or recruitment work for NHS careers.","zh":"head of NHS Careers 是領導 NHS 職業資訊或招聘工作的負責人。"},{"en":"A head of careers may explain job paths to students and graduates.","zh":"職業服務主管可能向學生和畢業生解釋職業路徑。"},{"en":"If the head of a careers service speaks publicly, she may shape how students view the employer.","zh":"如果職業服務主管公開發言，她可能塑造學生如何看待該僱主。"},{"en":"The phrase names a senior role in career communication.","zh":"這個短語指出職業溝通方面的高級職位。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":6},{"front":"reflect the reality of","meaning":"反映……的實際情況","examples":[{"en":"The NHS’s success reflected the reality of the health service.","zh":"NHS 的成功反映醫療服務機構的實際情況。"},{"en":"To reflect the reality of something means to show what it is truly like.","zh":"reflect the reality of 某事，指顯示它真實是怎樣的。"},{"en":"Exam results may reflect the reality of a student’s practice habits.","zh":"考試成績可能反映學生練習習慣的實際情況。"},{"en":"If a survey reflects reality, its findings match what people experience in daily life.","zh":"如果調查反映現實，其發現會符合人們日常經驗。"},{"en":"The phrase connects an outcome with the true situation behind it.","zh":"這個短語把結果與背後真實情況連繫起來。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":6},{"front":"the third largest employer in the world","meaning":"全球第三大僱主","examples":[{"en":"The health service is the third largest employer in the world.","zh":"該醫療服務機構是全球第三大僱主。"},{"en":"The third largest employer in the world means only two employers globally have more staff.","zh":"the third largest employer in the world 指全球只有兩個僱主的員工數目更多。"},{"en":"An organisation that large needs workers in many roles, not just one profession.","zh":"這樣大型的機構需要許多職位的人員，而不只是一個專業。"},{"en":"If an employer is extremely large, graduates may see many possible career paths.","zh":"如果僱主規模極大，畢業生可能看到很多職業路徑。"},{"en":"The phrase stresses huge employment scale.","zh":"這個短語強調巨大的聘用規模。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":6},{"front":"the largest in Europe","meaning":"歐洲最大僱主","examples":[{"en":"The NHS is the largest employer in Europe.","zh":"NHS 是歐洲最大僱主。"},{"en":"The largest in Europe means bigger than every other comparable organisation in Europe.","zh":"the largest in Europe 指比歐洲所有同類機構都大。"},{"en":"A university described as the largest in Europe would have an unusually high number of students.","zh":"被描述為歐洲最大的大學會有異常多學生。"},{"en":"If an employer is the largest in Europe, it likely offers many different roles.","zh":"如果僱主是歐洲最大，它很可能提供許多不同職位。"},{"en":"The phrase compares size within Europe.","zh":"這個短語在歐洲範圍內比較規模。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":6},{"front":"employ people in areas other than","meaning":"在……以外的範疇聘請人員","examples":[{"en":"The NHS employs people in areas other than clinical care.","zh":"NHS 在臨床護理以外的範疇聘請人員。"},{"en":"To employ people in areas other than something means to hire staff for additional fields beyond that area.","zh":"employ people in areas other than 某範疇，指在該範疇以外的其他領域聘請員工。"},{"en":"A school employs people in areas other than teaching, such as IT, finance and counselling.","zh":"學校在教學以外的範疇聘請人員，例如資訊科技、財務和輔導。"},{"en":"If an organisation has many support functions, it can employ graduates from many backgrounds.","zh":"如果機構有許多支援功能，它可以聘請來自不同背景的畢業生。"},{"en":"The phrase expands the idea of what jobs are available.","zh":"這個短語擴闊可用職位的概念。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":6},{"front":"clinical care","meaning":"臨床護理","examples":[{"en":"The NHS offers careers outside clinical care.","zh":"NHS 提供臨床護理以外的職業。"},{"en":"Clinical care is direct medical care given to patients by health professionals.","zh":"clinical care 是醫療專業人員直接給予病人的醫療護理。"},{"en":"Nurses and doctors provide clinical care when they examine, treat and support patients.","zh":"護士和醫生檢查、治療和支援病人時，就是提供臨床護理。"},{"en":"If a job is outside clinical care, it may involve management, technology or administration.","zh":"如果工作在臨床護理以外，它可能涉及管理、科技或行政。"},{"en":"The phrase refers to patient-facing healthcare work.","zh":"這個短語指面向病人的醫療工作。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":6},{"front":"no longer seen as","meaning":"不再被視為","examples":[{"en":"The health service is no longer seen as a second-choice career.","zh":"醫療服務不再被視為次選職業。"},{"en":"No longer seen as something means people used to view it that way, but now they do not.","zh":"no longer seen as 某物，指人們以前這樣看它，但現在不再如此。"},{"en":"Online learning is no longer seen as only a backup option in many schools.","zh":"在許多學校，網上學習不再被視為只是後備選項。"},{"en":"If a job is no longer seen as second choice, its status has improved.","zh":"如果一份工作不再被視為次選，其地位已改善。"},{"en":"The phrase marks a change in public perception.","zh":"這個短語標示公眾看法的轉變。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":6},{"front":"second-choice career","meaning":"次選職業","examples":[{"en":"The NHS is no longer seen as a second-choice career.","zh":"NHS 不再被視為次選職業。"},{"en":"A second-choice career is a job path people choose only after preferring something else first.","zh":"second-choice career 是人們在先偏好其他選項後才選擇的職業路徑。"},{"en":"A student may treat teaching as a second-choice career until classroom experience changes her mind.","zh":"學生可能把教學視為次選職業，直到課室經驗改變她的想法。"},{"en":"If a career loses its second-choice image, more ambitious graduates may consider it seriously.","zh":"如果職業擺脫次選形象，更多有抱負的畢業生可能認真考慮它。"},{"en":"The phrase suggests lower status or weaker first preference.","zh":"這個短語暗示較低地位或較弱的首選程度。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":6},{"front":"recognise that","meaning":"意識到；承認","examples":[{"en":"People recognise that they can give something back to the community.","zh":"人們意識到他們可以回饋社會。"},{"en":"To recognise that something is true means to realise or accept it.","zh":"recognise that 某事為真，指意識到或接受它。"},{"en":"Students may recognise that sleep matters after their marks fall from tiredness.","zh":"學生因疲倦而成績下降後，可能意識到睡眠很重要。"},{"en":"If graduates recognise that a job has social value, they may feel more attracted to it.","zh":"如果畢業生意識到某工作有社會價值，他們可能更受吸引。"},{"en":"The phrase introduces a new understanding.","zh":"這個短語引出新的理解。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":7},{"front":"give something back to the community","meaning":"回饋社會","examples":[{"en":"People can give something back to the community through NHS careers.","zh":"人們可以透過 NHS 職業回饋社會。"},{"en":"To give something back to the community means to help the society that has supported you.","zh":"give something back to the community 指幫助曾支持自己的社會。"},{"en":"A successful student may give something back to the community by tutoring younger pupils for free.","zh":"成功學生可能透過免費輔導年幼學生來回饋社會。"},{"en":"If a job helps vulnerable people, workers may feel they are giving something back.","zh":"如果工作幫助弱勢人士，員工可能覺得自己正在回饋社會。"},{"en":"The phrase connects personal success with social responsibility.","zh":"這個短語把個人成功與社會責任連繫起來。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":7},{"front":"develop a worthwhile career","meaning":"發展有價值的事業","examples":[{"en":"People can serve the community and still develop a worthwhile career.","zh":"人們可以服務社區，同時仍發展有價值的事業。"},{"en":"To develop a worthwhile career means to build meaningful, valuable and satisfying work over time.","zh":"develop a worthwhile career 指隨時間建立有意義、有價值且令人滿足的工作。"},{"en":"A nurse may develop a worthwhile career by helping patients and gaining advanced skills.","zh":"護士可以透過幫助病人並取得高階技能，發展有價值的事業。"},{"en":"If a job gives growth and purpose, it can become a worthwhile career.","zh":"如果工作帶來成長和目的，它可以成為有價值的事業。"},{"en":"The phrase describes career value beyond salary alone.","zh":"這個短語描述超越薪金的職業價值。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":7},{"front":"student recruitment and diversity","meaning":"學生招聘及多元共融","examples":[{"en":"Sarah Churchman was director of student recruitment and diversity at PwC.","zh":"Sarah Churchman 是 PwC 的學生招聘及多元共融總監。"},{"en":"Student recruitment and diversity means attracting students while building an inclusive workforce.","zh":"student recruitment and diversity 指吸引學生，同時建立包容不同背景的員工隊伍。"},{"en":"A university may have a student recruitment and diversity team to reach applicants from different backgrounds.","zh":"大學可能有學生招聘及多元共融團隊，接觸來自不同背景的申請人。"},{"en":"If recruitment includes diversity, more people may feel they belong in the organisation.","zh":"如果招聘包括多元共融，更多人可能覺得自己屬於該機構。"},{"en":"The phrase connects hiring students with inclusion.","zh":"這個短語把學生招聘與包容連繫起來。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":7},{"front":"be down to","meaning":"歸因於","examples":[{"en":"PwC’s success is down to a good campus presence.","zh":"PwC 的成功歸因於良好的校園曝光。"},{"en":"To be down to something means to be caused by or explained by it.","zh":"be down to 某事，指由它造成或解釋。"},{"en":"A student’s improvement may be down to regular practice and honest feedback.","zh":"學生的進步可能歸因於定期練習和誠實回饋。"},{"en":"If a company’s popularity is down to campus visits, visibility matters.","zh":"如果公司受歡迎歸因於校園到訪，能見度就很重要。"},{"en":"The phrase gives the reason behind a result.","zh":"這個短語給出結果背後的原因。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":7},{"front":"campus presence","meaning":"校園曝光；校園存在感","examples":[{"en":"PwC’s strong campus presence helped it do well in the survey.","zh":"PwC 強大的校園曝光幫助它在調查中表現出色。"},{"en":"Campus presence means how visible and active an employer is at universities.","zh":"campus presence 指僱主在大學中的可見度和活躍程度。"},{"en":"A company builds campus presence by giving talks, attending fairs and meeting students.","zh":"公司可以透過演講、參加招聘會和接觸學生來建立校園存在感。"},{"en":"If students often see an employer on campus, they may remember it when applying.","zh":"如果學生經常在校園看見某僱主，申請時可能記得它。"},{"en":"The phrase describes visibility among university students.","zh":"這個短語描述在大學生中的能見度。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":7},{"front":"commitment to invest in","meaning":"投資於……的承諾","examples":[{"en":"PwC emphasised its commitment to invest in its employees.","zh":"PwC 強調其投資於員工的承諾。"},{"en":"A commitment to invest in something is a serious promise to spend resources on it.","zh":"commitment to invest in 某事，是把資源投入其中的認真承諾。"},{"en":"A school’s commitment to invest in teachers may include training and better materials.","zh":"學校投資於老師的承諾可能包括培訓和更好教材。"},{"en":"If a company invests in employees, staff may feel valued and stay longer.","zh":"如果公司投資於員工，員工可能感到被重視並留下更久。"},{"en":"The phrase shows long-term support, not a one-time gift.","zh":"這個短語顯示長期支持，而不是一次性禮物。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":7},{"front":"invest in its employees","meaning":"投資於員工","examples":[{"en":"The company is committed to investing in its employees.","zh":"公司承諾投資於員工。"},{"en":"To invest in its employees means to spend money, time or training on staff development.","zh":"invest in its employees 指把金錢、時間或培訓投入員工發展。"},{"en":"A company may invest in employees by paying for courses and mentoring.","zh":"公司可以透過支付課程費和提供指導來投資於員工。"},{"en":"If employers invest in staff, workers can gain skills and take on bigger roles.","zh":"如果僱主投資於員工，員工可以獲得技能並承擔更大角色。"},{"en":"The phrase treats people as a long-term asset.","zh":"這個短語把人視為長期資產。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":7},{"front":"with offices around the world","meaning":"在世界各地設有辦事處","examples":[{"en":"PwC offers the chance to travel because it has offices around the world.","zh":"PwC 因在世界各地設有辦事處而提供旅行或外派機會。"},{"en":"With offices around the world means having workplaces in many countries.","zh":"with offices around the world 指在許多國家設有工作地點。"},{"en":"A company with offices around the world may send staff to different cities for projects.","zh":"在世界各地設有辦事處的公司可能派員到不同城市工作。"},{"en":"If an employer has global offices, graduates may see more international opportunities.","zh":"如果僱主有全球辦事處，畢業生可能看到更多國際機會。"},{"en":"The phrase suggests a wide international network.","zh":"這個短語暗示廣泛的國際網絡。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":7},{"front":"the chance to travel","meaning":"旅行／外派工作的機會","examples":[{"en":"The chance to travel was important to many students.","zh":"旅行或外派工作的機會對許多學生很重要。"},{"en":"The chance to travel means an opportunity to visit or work in other places.","zh":"the chance to travel 指到其他地方旅遊或工作的機會。"},{"en":"A graduate may choose a job partly because it offers the chance to travel abroad.","zh":"畢業生可能部分因某工作提供海外工作機會而選擇它。"},{"en":"If travel matters to students, employers with global projects may appear more attractive.","zh":"如果學生重視旅行，有全球項目的僱主可能更吸引。"},{"en":"The phrase describes an opportunity, not a guaranteed holiday.","zh":"這個短語描述機會，而不是保證假期。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":7},{"front":"just under half of","meaning":"接近一半但不足一半","examples":[{"en":"Just under half of the students said travel was important.","zh":"接近一半但不足一半的學生表示旅行很重要。"},{"en":"Just under half of a group means slightly less than 50 per cent.","zh":"just under half of 某群體，指略少於百分之五十。"},{"en":"Just under half of the class chose science as their favourite subject.","zh":"接近一半但不足一半的班級學生選科學為最喜歡科目。"},{"en":"If just under half of students want travel, it is a major but not majority preference.","zh":"如果接近一半但不足一半的學生想要旅行機會，這是重要但非多數的偏好。"},{"en":"The phrase gives an approximate proportion below one half.","zh":"這個短語表示低於一半的大概比例。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":8},{"front":"students polled","meaning":"受訪學生","examples":[{"en":"The students polled said travel was an important factor.","zh":"受訪學生表示旅行是重要因素。"},{"en":"Students polled are students who were asked questions in a survey.","zh":"students polled 是在調查中被問問題的學生。"},{"en":"Students polled in a school survey may comment on lessons, homework and facilities.","zh":"在學校調查中受訪的學生可能評論課堂、功課和設施。"},{"en":"If many students polled mention the same issue, the survey result becomes more meaningful.","zh":"如果許多受訪學生提到同一問題，調查結果就更有意義。"},{"en":"The phrase identifies the people who gave survey answers.","zh":"這個短語指出提供調查答案的人。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":8},{"front":"an important factor","meaning":"重要因素","examples":[{"en":"Travel was an important factor when students looked for work.","zh":"學生找工作時，旅行是重要因素。"},{"en":"An important factor is something that strongly affects a decision or result.","zh":"an important factor 是強烈影響決定或結果的事。"},{"en":"Distance from home is an important factor when families choose a school.","zh":"離家距離是家庭選擇學校時的重要因素。"},{"en":"If salary is an important factor, students may compare pay before applying.","zh":"如果薪金是重要因素，學生申請前可能比較薪酬。"},{"en":"The phrase names a reason that matters in decision-making.","zh":"這個短語指出決策中重要的原因。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":8},{"front":"when it came to looking for work","meaning":"在找工作方面","examples":[{"en":"Travel mattered when it came to looking for work.","zh":"在找工作方面，旅行很重要。"},{"en":"When it came to looking for work means when students were considering jobs or employers.","zh":"when it came to looking for work 指當學生考慮工作或僱主時。"},{"en":"When it came to choosing a school, parents cared most about safety.","zh":"在選擇學校方面，家長最重視安全。"},{"en":"If travel matters when it comes to work, international firms may gain an advantage.","zh":"如果在工作方面旅行很重要，國際公司可能有優勢。"},{"en":"The phrase introduces the specific situation being discussed.","zh":"這個短語引出正在討論的特定情況。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":8},{"front":"one of the big four accountancy firms","meaning":"四大會計師行之一","examples":[{"en":"PwC is one of the big four accountancy firms.","zh":"PwC 是四大會計師行之一。"},{"en":"One of the big four accountancy firms means one of the four largest global accounting firms.","zh":"one of the big four accountancy firms 指全球四大會計師行之一。"},{"en":"Business students often recognise the big four because they recruit many graduates.","zh":"商科學生常認識四大，因為它們招聘許多畢業生。"},{"en":"If a firm is one of the big four, its brand can attract ambitious applicants.","zh":"如果一間公司是四大之一，其品牌可以吸引有抱負的申請者。"},{"en":"The phrase signals high status in the accounting profession.","zh":"這個短語表示會計專業中的高地位。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":8},{"front":"not into gimmicks","meaning":"不搞噱頭","examples":[{"en":"PwC is not into gimmicks when recruiting students.","zh":"PwC 招聘學生時不搞噱頭。"},{"en":"Not into gimmicks means not interested in cheap tricks or flashy methods to attract attention.","zh":"not into gimmicks 指不喜歡用廉價花招或浮誇方法吸引注意。"},{"en":"A teacher who is not into gimmicks prefers clear teaching to noisy classroom tricks.","zh":"不搞噱頭的老師偏好清楚教學，而不是吵鬧課堂花招。"},{"en":"If a company is not into gimmicks, it may focus on real training and career value.","zh":"如果公司不搞噱頭，它可能集中於真正培訓和職業價值。"},{"en":"The phrase suggests seriousness and substance.","zh":"這個短語暗示認真和有實質內容。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":8},{"front":"offer freebies","meaning":"提供免費贈品","examples":[{"en":"The company does not offer freebies to attract students.","zh":"公司不提供免費贈品來吸引學生。"},{"en":"To offer freebies means to give free gifts or items to attract people.","zh":"offer freebies 指給免費禮品或物品來吸引人。"},{"en":"A stall may offer freebies such as pens or snacks at a careers fair.","zh":"招聘會攤位可能提供筆或小食等免費贈品。"},{"en":"Freebies can draw attention, but they do not prove a job is good.","zh":"免費贈品可以吸引注意，但不能證明工作好。"},{"en":"The phrase describes small free gifts used in promotion.","zh":"這個短語描述宣傳中使用的小型免費禮品。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":8},{"front":"a solid foundation","meaning":"穩固基礎","examples":[{"en":"PwC offers a solid foundation for a career in business.","zh":"PwC 為商業事業提供穩固基礎。"},{"en":"A solid foundation is a strong base that supports future growth.","zh":"a solid foundation 是支持未來成長的強大基礎。"},{"en":"Good grammar gives students a solid foundation for better writing.","zh":"良好文法為學生更好寫作提供穩固基礎。"},{"en":"If a first job provides strong training, it can become a solid foundation for a career.","zh":"如果第一份工作提供強大培訓，它可以成為事業的穩固基礎。"},{"en":"The phrase suggests reliable support at the beginning.","zh":"這個短語暗示起步時的可靠支援。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":8},{"front":"a career in business","meaning":"商業事業","examples":[{"en":"PwC offers a solid foundation for anyone wanting a career in business.","zh":"PwC 為任何想發展商業事業的人提供穩固基礎。"},{"en":"A career in business means long-term work in areas such as finance, management, sales or consulting.","zh":"a career in business 指在財務、管理、銷售或顧問等範疇的長期工作。"},{"en":"A student may study accounting because she wants a career in business.","zh":"學生可能修讀會計，因為她想發展商業事業。"},{"en":"If someone wants a business career, early training and client experience can help.","zh":"如果某人想投身商業事業，早期培訓和客戶經驗會有幫助。"},{"en":"The phrase refers to a professional path in the commercial world.","zh":"這個短語指商業世界中的專業道路。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":8},{"front":"sell people’s skills","meaning":"銷售人的技能","examples":[{"en":"PwC sells its people’s skills rather than a product.","zh":"PwC 銷售的是人的技能，而不是產品。"},{"en":"To sell people’s skills means to offer employees’ expertise as the main service.","zh":"sell people’s skills 指把員工專業能力作為主要服務提供。"},{"en":"A consulting firm sells people’s skills when clients pay for advice and analysis.","zh":"顧問公司在客戶付費購買建議和分析時，就是銷售人的技能。"},{"en":"If a company sells skills, training its staff becomes central to its success.","zh":"如果公司銷售技能，培訓員工就成為成功核心。"},{"en":"The phrase contrasts human expertise with physical products.","zh":"這個短語把人的專業能力與實體產品作對比。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":8},{"front":"be interested in developing","meaning":"有意發展……","examples":[{"en":"The company is interested in developing employees’ skills.","zh":"公司有意發展員工技能。"},{"en":"To be interested in developing something means to care about improving it over time.","zh":"be interested in developing 某物，指重視隨時間改善它。"},{"en":"A school may be interested in developing students’ confidence, not only exam marks.","zh":"學校可能有意發展學生信心，而不只是考試分數。"},{"en":"If an employer develops staff skills, workers can take on more complex tasks.","zh":"如果僱主發展員工技能，員工就能承擔更複雜任務。"},{"en":"The phrase shows a focus on growth and improvement.","zh":"這個短語顯示對成長和改善的重視。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":9},{"front":"invest in our people","meaning":"投資於我們的人才","examples":[{"en":"PwC says it invests in its people.","zh":"PwC 表示它投資於自己的人才。"},{"en":"To invest in our people means to support staff through training, opportunities and resources.","zh":"invest in our people 指透過培訓、機會和資源支援員工。"},{"en":"A school invests in its people when it trains teachers and supports new staff.","zh":"學校培訓老師並支援新員工時，就是投資於自己的人才。"},{"en":"If an organisation invests in people, employees may become more skilled and loyal.","zh":"如果機構投資於人才，員工可能變得更有技能和忠誠。"},{"en":"The phrase presents workers as the organisation’s main strength.","zh":"這個短語把員工呈現為機構的主要力量。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":9},{"front":"further down the rankings","meaning":"在排名較低位置","examples":[{"en":"Further down the rankings, John Lewis still had reason to celebrate.","zh":"在排名較低位置，John Lewis 仍有理由慶祝。"},{"en":"Further down the rankings means in a lower position on the list.","zh":"further down the rankings 指在名單中較低的位置。"},{"en":"A company may appear further down the rankings but still improve greatly from last year.","zh":"公司可能在排名較低位置，但仍比去年大幅改善。"},{"en":"If an employer is further down the rankings, it is below the top positions.","zh":"如果僱主在排名較低位置，它就在最高名次以下。"},{"en":"The phrase locates an item lower in an ordered list.","zh":"這個短語把項目定位在有序名單較低處。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":9},{"front":"with reason to celebrate","meaning":"有理由慶祝","examples":[{"en":"John Lewis was further down the rankings but still had reason to celebrate.","zh":"John Lewis 排名較低，但仍有理由慶祝。"},{"en":"With reason to celebrate means having a good cause for happiness or pride.","zh":"with reason to celebrate 指有充分原因感到高興或自豪。"},{"en":"A student who improves from a fail to a pass has reason to celebrate.","zh":"從不合格進步到合格的學生有理由慶祝。"},{"en":"If a company rises sharply in a ranking, staff may have reason to celebrate.","zh":"如果公司排名大幅上升，員工可能有理由慶祝。"},{"en":"The phrase suggests success even if the result is not perfect.","zh":"這個短語暗示成功，即使結果不完美。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":9},{"front":"bumper sales","meaning":"強勁銷售額","examples":[{"en":"John Lewis matched bumper sales with a rise in the rankings.","zh":"John Lewis 以排名上升配合強勁銷售額。"},{"en":"Bumper sales are unusually high or very strong sales.","zh":"bumper sales 是異常高或非常強勁的銷售額。"},{"en":"A toy shop may have bumper sales before Christmas.","zh":"玩具店在聖誕節前可能有強勁銷售額。"},{"en":"Bumper sales can improve confidence and make a company more attractive to graduates.","zh":"強勁銷售額可以提升信心，並令公司對畢業生更吸引。"},{"en":"The phrase describes excellent sales performance.","zh":"這個短語描述優秀銷售表現。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":9},{"front":"match something with","meaning":"以……配合……","examples":[{"en":"John Lewis matched bumper sales with a leap in popularity.","zh":"John Lewis 以受歡迎程度躍升配合強勁銷售額。"},{"en":"To match something with something else means to combine one success or feature with another.","zh":"match something with something else 指把一項成功或特點與另一項結合。"},{"en":"A school may match good exam results with strong sports performance.","zh":"學校可能以優秀考試成績配合強勁體育表現。"},{"en":"If a company matches high sales with better reputation, it succeeds in two ways.","zh":"如果公司以更好聲譽配合高銷售，它就在兩方面成功。"},{"en":"The phrase shows two positive results happening together.","zh":"這個短語顯示兩個正面結果同時發生。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":9},{"front":"a leap from…to…","meaning":"從……躍升至……","examples":[{"en":"John Lewis made a leap from 111th place to 26th.","zh":"John Lewis 從第111位躍升至第26位。"},{"en":"A leap from one position to another means a large upward move in ranking.","zh":"a leap from 一個位置 to 另一位置，指排名大幅上升。"},{"en":"A student may make a leap from the bottom group to the top group after steady practice.","zh":"學生經穩定練習後，可能從最低組躍升至最高組。"},{"en":"If a brand leaps from 100th to 20th, many more people now recognise it.","zh":"如果品牌從第100位躍升至第20位，現在有更多人認識它。"},{"en":"The phrase makes the size of improvement clear.","zh":"這個短語清楚顯示改善幅度。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":9},{"front":"find itself in","meaning":"發現自己處於……","examples":[{"en":"Sky found itself in 12th place this year.","zh":"Sky 發現自己今年處於第12位。"},{"en":"To find itself in a position means to end up in that position, sometimes unexpectedly.","zh":"find itself in 某位置，指最終處於該位置，有時帶意外意味。"},{"en":"A small café may find itself in local news after a famous visitor posts about it.","zh":"小咖啡店在名人發帖後，可能發現自己登上本地新聞。"},{"en":"If a company finds itself high in a ranking, its reputation may have risen quickly.","zh":"如果公司發現自己在排名高位，其聲譽可能快速上升。"},{"en":"The phrase often suggests a new or surprising situation.","zh":"這個短語常暗示新的或意外的情況。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":9},{"front":"up from","meaning":"由……上升","examples":[{"en":"Sky was in 12th place, up from 104th last year.","zh":"Sky 排名第12位，由去年的第104位上升。"},{"en":"Up from means higher than a previous position, number or level.","zh":"up from 指比之前的位置、數字或水平更高。"},{"en":"A student scored 80, up from 62 in the last test.","zh":"學生今次得80分，由上次62分上升。"},{"en":"If a company is up from 104th to 12th, its popularity has risen dramatically.","zh":"如果公司由第104位升至第12位，其受歡迎程度大幅上升。"},{"en":"The phrase shows improvement compared with the past.","zh":"這個短語顯示與過去相比的改善。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":9},{"front":"prove popular among","meaning":"在……之中受歡迎","examples":[{"en":"The Environment Agency also proved popular among humanities students.","zh":"環境署在人文學科學生之中也證明受歡迎。"},{"en":"To prove popular among a group means to turn out to be liked by that group.","zh":"prove popular among 某群體，指結果顯示受該群體喜歡。"},{"en":"A new reading club may prove popular among younger students.","zh":"新閱讀會可能在較年幼學生中受歡迎。"},{"en":"If an employer proves popular among graduates, it may receive more applications.","zh":"如果僱主在畢業生中受歡迎，它可能收到更多申請。"},{"en":"The phrase describes popularity shown by results or reactions.","zh":"這個短語描述由結果或反應顯示的受歡迎程度。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":9},{"front":"this student group","meaning":"這個學生群體","examples":[{"en":"The Environment Agency proved popular among this student group.","zh":"環境署在這個學生群體中證明受歡迎。"},{"en":"This student group means the specific group of students just mentioned.","zh":"this student group 指剛提及的特定學生群體。"},{"en":"If this student group values public service, government jobs may rank highly.","zh":"如果這個學生群體重視公共服務，政府工作可能排名高。"},{"en":"Survey results can differ because each student group has different career priorities.","zh":"調查結果可能不同，因為每個學生群體有不同職業優先事項。"},{"en":"The phrase points back to a particular category of students.","zh":"這個短語指回某一類學生。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":10},{"front":"a reversal of fortunes","meaning":"命運逆轉；形勢好轉","examples":[{"en":"Shell saw a reversal of fortunes among business students.","zh":"Shell 在商科學生中出現形勢好轉。"},{"en":"A reversal of fortunes is a major change from bad results to good results, or the opposite.","zh":"a reversal of fortunes 是由壞結果轉為好結果，或相反的重大變化。"},{"en":"A shop may enjoy a reversal of fortunes after moving to a busier street.","zh":"商店搬到更繁忙街道後，可能經歷形勢好轉。"},{"en":"If a company rises after a poor year, it has experienced a reversal of fortunes.","zh":"如果公司在差劣一年後上升，它就經歷了命運逆轉。"},{"en":"The phrase describes a clear turn in luck or performance.","zh":"這個短語描述運氣或表現的明顯轉變。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":10},{"front":"rise to 30th place","meaning":"上升至第30位","examples":[{"en":"Shell rose to 30th place after last year’s 76th position.","zh":"Shell 從去年的第76位上升至第30位。"},{"en":"To rise to 30th place means to move upward until reaching position number 30.","zh":"rise to 30th place 指向上移動至第30位。"},{"en":"A school team may rise to third place after winning several matches.","zh":"學校隊伍連贏幾場後，可能上升至第三位。"},{"en":"If an employer rises to 30th place, it has become more popular than before.","zh":"如果僱主上升至第30位，它比以前更受歡迎。"},{"en":"The phrase marks a specific improved ranking.","zh":"這個短語標示具體改善後的排名。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":10},{"front":"dramatic drops in the rankings","meaning":"排名大幅下跌","examples":[{"en":"There were a few dramatic drops in the rankings.","zh":"排名中有幾個大幅下跌。"},{"en":"Dramatic drops in the rankings are large and noticeable falls in position.","zh":"dramatic drops in the rankings 是排名位置上大而明顯的下降。"},{"en":"A university may suffer dramatic drops in rankings after student satisfaction falls.","zh":"如果學生滿意度下降，大學排名可能大幅下跌。"},{"en":"If an employer drops dramatically, graduates may have become less interested in it.","zh":"如果僱主排名大幅下跌，畢業生可能對它興趣減少。"},{"en":"The phrase describes sharp decline, not a small movement.","zh":"這個短語描述急劇下降，而不是小變動。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":10},{"front":"fall from…to…","meaning":"從……跌至……","examples":[{"en":"The Bank of England fell from 14th to 27th place.","zh":"英倫銀行從第14位跌至第27位。"},{"en":"To fall from one position to another means to move down in a ranking.","zh":"fall from 某位置 to 某位置，指在排名中下降。"},{"en":"A student may fall from second to sixth after missing several assignments.","zh":"學生漏交幾份功課後，可能從第二跌至第六。"},{"en":"If a company falls from 14th to 27th, its ranking has clearly worsened.","zh":"如果公司從第14位跌至第27位，它的排名明顯變差。"},{"en":"The phrase gives both the old and new lower position.","zh":"這個短語同時給出舊位置和新的較低位置。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":10},{"front":"retain its mid-table position","meaning":"保持中游排名","examples":[{"en":"The Bank of England retained its mid-table position among business students.","zh":"英倫銀行在商科學生中保持中游排名。"},{"en":"To retain its mid-table position means to stay around the middle of a ranking.","zh":"retain its mid-table position 指保持在排名中間位置。"},{"en":"A football team may retain its mid-table position after neither winning nor losing many games.","zh":"足球隊在勝負不多後，可能保持中游排名。"},{"en":"If an employer remains mid-table, it is neither highly popular nor very unpopular.","zh":"如果僱主保持中游，它既不是很受歡迎，也不是很不受歡迎。"},{"en":"The phrase suggests stability at an average level.","zh":"這個短語暗示在平均水平上保持穩定。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":10},{"front":"see a slight dip","meaning":"略為下跌","examples":[{"en":"British Airways also saw a slight dip.","zh":"British Airways 也略為下跌。"},{"en":"To see a slight dip means to experience a small decrease.","zh":"see a slight dip 指經歷小幅下降。"},{"en":"A student’s marks may see a slight dip during a busy sports season.","zh":"學生在繁忙運動季期間，成績可能略為下跌。"},{"en":"If popularity sees a slight dip, the change is noticeable but not serious.","zh":"如果受歡迎程度略為下跌，變化可見但不嚴重。"},{"en":"The phrase describes a mild fall.","zh":"這個短語描述輕微下降。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":10},{"front":"business undergraduates","meaning":"商科本科生","examples":[{"en":"McKinsey & Co dropped in popularity among business undergraduates.","zh":"McKinsey & Co 在商科本科生中受歡迎程度下降。"},{"en":"Business undergraduates are university students studying business before receiving their first degree.","zh":"business undergraduates 是正在修讀第一個商科學位的大學生。"},{"en":"Business undergraduates often look for internships in finance, consulting and marketing.","zh":"商科本科生常尋找金融、顧問和市場營銷實習。"},{"en":"If business undergraduates lose interest in an employer, that employer may change its campus strategy.","zh":"如果商科本科生對某僱主失去興趣，該僱主可能改變校園策略。"},{"en":"The phrase identifies a specific group of students.","zh":"這個短語指出特定學生群體。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":10},{"front":"perhaps more surprisingly","meaning":"更令人意外的是","examples":[{"en":"Perhaps more surprisingly, Teach First appeared in the rankings for the first time.","zh":"更令人意外的是，Teach First 首次出現在排名中。"},{"en":"Perhaps more surprisingly introduces a fact that is even more unexpected than the previous point.","zh":"perhaps more surprisingly 用來引出比前一點更出乎意料的事實。"},{"en":"The quiet student won the debate; perhaps more surprisingly, she also won best speaker.","zh":"安靜的學生贏得辯論；更令人意外的是，她還贏得最佳辯手。"},{"en":"If a small charity enters a major ranking, the result may be more surprising than a large company rising.","zh":"如果小型慈善機構進入主要排名，結果可能比大公司上升更令人意外。"},{"en":"The phrase prepares readers for unexpected information.","zh":"這個短語讓讀者準備接收意外資訊。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":10},{"front":"first appearance in the rankings","meaning":"首次出現在排名中","examples":[{"en":"This year was Teach First’s first appearance in the rankings.","zh":"今年是 Teach First 首次出現在排名中。"},{"en":"First appearance in the rankings means the first time an organisation is included in the ranked list.","zh":"first appearance in the rankings 指某機構第一次被納入排名名單。"},{"en":"A new school may celebrate its first appearance in national rankings.","zh":"新學校可能慶祝首次出現在全國排名中。"},{"en":"If an organisation enters the rankings for the first time, awareness of it has grown.","zh":"如果機構首次進入排名，人們對它的認識已增加。"},{"en":"The phrase describes a debut in an ordered list.","zh":"這個短語描述在有序名單中的首次登場。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":10},{"front":"small charity","meaning":"小型慈善機構","examples":[{"en":"Teach First is a small charity launched three years ago.","zh":"Teach First 是一間三年前成立的小型慈善機構。"},{"en":"A small charity is a non-profit organisation with limited size, money or reach.","zh":"small charity 是規模、資金或覆蓋範圍有限的非牟利組織。"},{"en":"A small charity may support local children with free tutoring after school.","zh":"小型慈善機構可能在放學後為本地兒童提供免費補習。"},{"en":"If a small charity gains national attention, its mission may spread quickly.","zh":"如果小型慈善機構得到全國關注，其使命可能迅速傳開。"},{"en":"The phrase contrasts a modest organisation with large employers.","zh":"這個短語把小規模組織與大型僱主作對比。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":11},{"front":"launched three years ago","meaning":"三年前成立","examples":[{"en":"Teach First was launched three years ago.","zh":"Teach First 三年前成立。"},{"en":"Launched three years ago means started or introduced three years before the time discussed.","zh":"launched three years ago 指在所討論時間的三年前開始或推出。"},{"en":"A learning app launched three years ago may now have many users.","zh":"三年前推出的學習應用程式現在可能有許多用戶。"},{"en":"If a charity launched only three years ago becomes popular, its growth is impressive.","zh":"如果一間只在三年前成立的慈善機構變得受歡迎，其增長很突出。"},{"en":"The phrase gives the organisation’s recent starting point.","zh":"這個短語給出機構較近期的起點。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":11},{"front":"aim to create","meaning":"旨在培養","examples":[{"en":"The charity aims to create the leaders of the future.","zh":"該慈善機構旨在培養未來領袖。"},{"en":"To aim to create something means to have the goal of producing or developing it.","zh":"aim to create 某物，指以產生或培養它為目標。"},{"en":"A school may aim to create confident readers through daily reading time.","zh":"學校可能透過每日閱讀時間，旨在培養有信心的讀者。"},{"en":"If a programme aims to create leaders, it must offer challenge and responsibility.","zh":"如果計劃旨在培養領袖，它必須提供挑戰和責任。"},{"en":"The phrase states a clear purpose.","zh":"這個短語陳述清晰目的。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":11},{"front":"leaders of the future","meaning":"未來領袖","examples":[{"en":"Teach First aims to create the leaders of the future.","zh":"Teach First 旨在培養未來領袖。"},{"en":"Leaders of the future are people expected to take important roles later in society or organisations.","zh":"leaders of the future 是預期日後在社會或組織中承擔重要角色的人。"},{"en":"Schools try to prepare leaders of the future by teaching responsibility and communication.","zh":"學校透過教責任感和溝通，嘗試培養未來領袖。"},{"en":"If graduates learn in difficult environments, they may become stronger future leaders.","zh":"如果畢業生在困難環境中學習，他們可能成為更強的未來領袖。"},{"en":"The phrase looks forward to later influence and responsibility.","zh":"這個短語展望日後的影響力和責任。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":11},{"front":"encourage top graduates to","meaning":"鼓勵優秀畢業生去……","examples":[{"en":"The charity encourages top graduates to work in challenging schools.","zh":"該慈善機構鼓勵優秀畢業生到具挑戰性的學校工作。"},{"en":"To encourage top graduates to do something means to persuade highly able graduates to take that action.","zh":"encourage top graduates to do something 指說服能力很強的畢業生採取該行動。"},{"en":"A hospital may encourage top graduates to join public health projects.","zh":"醫院可能鼓勵優秀畢業生加入公共衞生項目。"},{"en":"If a programme encourages talented graduates into difficult work, it needs a strong mission.","zh":"如果計劃鼓勵有才華畢業生投身困難工作，它需要強大使命。"},{"en":"The phrase connects persuasion with high-achieving graduates.","zh":"這個短語把說服與高成就畢業生連繫起來。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":11},{"front":"top graduates","meaning":"優秀畢業生","examples":[{"en":"Teach First tries to attract top graduates into teaching.","zh":"Teach First 嘗試吸引優秀畢業生投身教學。"},{"en":"Top graduates are highly successful university graduates with strong academic or personal qualities.","zh":"top graduates 是學業或個人素質強的大學畢業生。"},{"en":"Employers compete for top graduates by offering training, responsibility and career growth.","zh":"僱主透過提供培訓、責任和事業發展來爭取優秀畢業生。"},{"en":"If top graduates enter teaching, schools may gain fresh energy and strong skills.","zh":"如果優秀畢業生投身教學，學校可能得到新活力和強大技能。"},{"en":"The phrase refers to outstanding graduates, not all graduates.","zh":"這個短語指傑出畢業生，而不是所有畢業生。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":11},{"front":"consider a career in teaching","meaning":"考慮從事教學事業","examples":[{"en":"Some top graduates would not normally consider a career in teaching.","zh":"一些優秀畢業生通常不會考慮從事教學事業。"},{"en":"To consider a career in teaching means to seriously think about becoming a teacher.","zh":"consider a career in teaching 指認真考慮成為老師。"},{"en":"A science graduate may consider a career in teaching after helping younger students.","zh":"科學畢業生在幫助年幼學生後，可能考慮從事教學事業。"},{"en":"If teaching is presented as challenging and meaningful, more graduates may consider it.","zh":"如果教學被呈現為具挑戰和有意義，更多畢業生可能會考慮它。"},{"en":"The phrase describes thinking about teaching as a professional path.","zh":"這個短語描述把教學視為專業道路來思考。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":11},{"front":"commit to work in","meaning":"承諾在……工作","examples":[{"en":"Graduates commit to work in challenging secondary schools.","zh":"畢業生承諾在具挑戰性的中學工作。"},{"en":"To commit to work in a place means to promise to work there for a period.","zh":"commit to work in 某地，指承諾在那裏工作一段時間。"},{"en":"A nurse may commit to work in a rural hospital for two years.","zh":"護士可能承諾在鄉郊醫院工作兩年。"},{"en":"If graduates commit to difficult schools, they accept responsibility before entering the classroom.","zh":"如果畢業生承諾在困難學校工作，他們在進入課室前已接受責任。"},{"en":"The phrase stresses a serious promise.","zh":"這個短語強調認真的承諾。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":11},{"front":"challenging secondary schools","meaning":"具挑戰性的中學","examples":[{"en":"Teach First places graduates in challenging secondary schools.","zh":"Teach First 把畢業生安排到具挑戰性的中學。"},{"en":"Challenging secondary schools are schools where teaching may be difficult because of social, academic or behavioural issues.","zh":"challenging secondary schools 是因社會、學業或行為問題而教學較困難的中學。"},{"en":"A teacher in a challenging secondary school may need patience, creativity and strong classroom routines.","zh":"在具挑戰性中學任教的老師可能需要耐性、創意和強大課堂流程。"},{"en":"If graduates succeed in challenging schools, they may develop leadership quickly.","zh":"如果畢業生在具挑戰性學校成功，他們可能快速發展領導能力。"},{"en":"The phrase describes schools that require extra skill and commitment.","zh":"這個短語描述需要額外技能和承諾的學校。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":11},{"front":"for at least two years","meaning":"至少兩年","examples":[{"en":"Graduates work in the schools for at least two years.","zh":"畢業生在這些學校工作至少兩年。"},{"en":"For at least two years means for two years or longer, but not less.","zh":"for at least two years 指兩年或更長，但不能少於兩年。"},{"en":"A new teacher may agree to stay in a school for at least two years.","zh":"新老師可能同意在學校留下至少兩年。"},{"en":"If a programme requires at least two years, participants must plan for a real commitment.","zh":"如果計劃要求至少兩年，參加者必須為真正承諾作準備。"},{"en":"The phrase gives a minimum length of time.","zh":"這個短語給出最短時間長度。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":11},{"front":"come straight in at number eight","meaning":"直接進入第八位","examples":[{"en":"Teach First came straight in at number eight among humanities students.","zh":"Teach First 在人文學科學生中直接進入第八位。"},{"en":"To come straight in at number eight means to enter the ranking for the first time at eighth place.","zh":"come straight in at number eight 指首次進入排名就排第八。"},{"en":"A new café may come straight in at number three in a local food ranking.","zh":"新咖啡店可能在本地美食排名中直接進入第三位。"},{"en":"If an organisation enters high immediately, it has made a strong first impression.","zh":"如果機構一進榜就排名高，它已留下強烈第一印象。"},{"en":"The phrase describes an impressive debut position.","zh":"這個短語描述令人印象深刻的首次排名。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":12},{"front":"be voted 22nd by","meaning":"被……選為第22位","examples":[{"en":"Teach First was voted 22nd by engineering, science and IT students.","zh":"Teach First 被工程、科學和資訊科技學生選為第22位。"},{"en":"To be voted 22nd by a group means that group ranked it in 22nd place.","zh":"be voted 22nd by 某群體，指該群體把它排在第22位。"},{"en":"A charity may be voted 10th by students who value social impact.","zh":"重視社會影響的學生可能把慈善機構選為第10位。"},{"en":"If an organisation is voted highly by several groups, its appeal is broad.","zh":"如果機構被幾個群體選得很高，它的吸引力就很廣。"},{"en":"The phrase identifies both the ranking and the voters.","zh":"這個短語指出排名和投票者。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":12},{"front":"graduate recruitment","meaning":"畢業生招聘","examples":[{"en":"James Darley was director of graduate recruitment at Teach First.","zh":"James Darley 是 Teach First 的畢業生招聘總監。"},{"en":"Graduate recruitment is the process of attracting and hiring university graduates.","zh":"graduate recruitment 是吸引和聘請大學畢業生的過程。"},{"en":"Companies run graduate recruitment events to meet students before they finish university.","zh":"公司舉辦畢業生招聘活動，在學生完成大學前接觸他們。"},{"en":"If graduate recruitment is successful, an organisation gains young talent for future roles.","zh":"如果畢業生招聘成功，機構就能得到未來職位所需的年輕人才。"},{"en":"The phrase refers to hiring people at the start of their careers.","zh":"這個短語指招聘事業起步階段的人。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":12},{"front":"be bowled over by","meaning":"因……大感驚喜","examples":[{"en":"James Darley was bowled over by the news.","zh":"James Darley 因這消息大感驚喜。"},{"en":"To be bowled over by something means to be very surprised and delighted by it.","zh":"be bowled over by 某事，指因它感到非常驚訝和高興。"},{"en":"A teacher may be bowled over by a shy student’s excellent speech.","zh":"老師可能因害羞學生出色演講而大感驚喜。"},{"en":"If a small charity receives unexpected recognition, its staff may be bowled over.","zh":"如果小型慈善機構得到意外認可，員工可能大感驚喜。"},{"en":"The phrase describes strong positive surprise.","zh":"這個短語描述強烈的正面驚訝。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":12},{"front":"be not expecting this","meaning":"沒有預料到這一點","examples":[{"en":"The organisation was not expecting this result.","zh":"該機構沒有預料到這個結果。"},{"en":"To be not expecting this means to be surprised because the result was not predicted.","zh":"be not expecting this 指因結果並非預測之內而感到意外。"},{"en":"A student may not expect a prize after thinking her project was ordinary.","zh":"學生以為自己的項目普通，可能沒有預料到會得獎。"},{"en":"If a charity was not expecting success, the ranking may feel especially exciting.","zh":"如果慈善機構沒有預料到成功，排名可能特別令人興奮。"},{"en":"The phrase shows surprise at an outcome.","zh":"這個短語顯示對結果感到意外。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":12},{"front":"registered charity","meaning":"註冊慈善機構","examples":[{"en":"Teach First is a registered charity.","zh":"Teach First 是註冊慈善機構。"},{"en":"A registered charity is a charity officially recorded and recognised by the authorities.","zh":"registered charity 是由當局正式記錄和認可的慈善機構。"},{"en":"Donors may trust a registered charity more because it must follow rules.","zh":"捐款者可能更信任註冊慈善機構，因為它必須遵守規則。"},{"en":"If an organisation is a registered charity, its purpose is public benefit rather than private profit.","zh":"如果機構是註冊慈善機構，其目的就是公共利益，而不是私人利潤。"},{"en":"The phrase describes official charitable status.","zh":"這個短語描述官方慈善身份。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":12},{"front":"physically go to","meaning":"親身前往","examples":[{"en":"The charity was only able to physically go to 15 universities.","zh":"該慈善機構只能親身前往15間大學。"},{"en":"To physically go to a place means to visit it in person, not just contact it online or by phone.","zh":"physically go to 某地，指親身到訪，而不只是網上或電話聯絡。"},{"en":"A recruiter may physically go to campuses to meet students face to face.","zh":"招聘人員可能親身前往校園，與學生面對面見面。"},{"en":"If a small charity can physically go to only a few universities, its resources are limited.","zh":"如果小型慈善機構只能親身前往少數大學，其資源有限。"},{"en":"The phrase stresses actual presence at a place.","zh":"這個短語強調實際到場。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":12},{"front":"the scheme","meaning":"該計劃","examples":[{"en":"The Teach First scheme is based on one run in the US.","zh":"Teach First 計劃以一個在美國推行的計劃為藍本。"},{"en":"The scheme means a planned programme designed to achieve a particular purpose.","zh":"the scheme 指為達成特定目的而設計的有計劃項目。"},{"en":"A school may introduce a reading scheme to help younger students improve.","zh":"學校可能推出閱讀計劃，幫助年幼學生進步。"},{"en":"If a scheme is successful, it may expand to more cities or schools.","zh":"如果計劃成功，它可能擴展至更多城市或學校。"},{"en":"The phrase refers to an organised plan, not a vague idea.","zh":"這個短語指有組織的計劃，而不是模糊想法。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":12},{"front":"be based on","meaning":"以……為藍本","examples":[{"en":"The scheme is based on one run in the US.","zh":"該計劃以一個在美國推行的計劃為藍本。"},{"en":"To be based on something means to use it as a model, foundation or source.","zh":"be based on 某物，指以它作為模式、基礎或來源。"},{"en":"A local training course may be based on a successful programme from another country.","zh":"本地培訓課程可能以另一國家的成功計劃為藍本。"},{"en":"If a scheme is based on an existing model, organisers can learn from earlier experience.","zh":"如果計劃以現有模式為藍本，組織者可以從早前經驗中學習。"},{"en":"The phrase explains where an idea comes from.","zh":"這個短語解釋想法來自哪裏。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":12},{"front":"one run in the US","meaning":"在美國推行的一個計劃","examples":[{"en":"The UK scheme is based on one run in the US.","zh":"英國計劃以在美國推行的一個計劃為藍本。"},{"en":"One run in the US means a similar programme operated in the United States.","zh":"one run in the US 指在美國運作的一個類似計劃。"},{"en":"A charity may copy one run abroad if it has already helped many schools.","zh":"如果海外推行的一個計劃已幫助許多學校，慈善機構可能仿效它。"},{"en":"If a local scheme is based on one run elsewhere, it may need changes for local needs.","zh":"如果本地計劃以其他地方的計劃為藍本，它可能需要因應本地需要調整。"},{"en":"The phrase refers to a model programme from another country.","zh":"這個短語指來自另一國家的模式計劃。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":12},{"front":"have the backing of","meaning":"得到……支持","examples":[{"en":"The scheme has the backing of more than 80 businesses.","zh":"該計劃得到超過80間企業支持。"},{"en":"To have the backing of someone means to have their support, money or approval.","zh":"have the backing of 某人，指得到其支持、資金或認可。"},{"en":"A school project may have the backing of parents and local shops.","zh":"學校項目可能得到家長和本地商店支持。"},{"en":"If a charity has business backing, it may gain money, contacts and credibility.","zh":"如果慈善機構得到商界支持，它可能獲得資金、人脈和可信度。"},{"en":"The phrase shows support from important people or organisations.","zh":"這個短語顯示來自重要人物或機構的支持。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":13},{"front":"undertake leadership training","meaning":"接受領導才能培訓","examples":[{"en":"Candidates undertake leadership training during the programme.","zh":"候選人在計劃期間接受領導才能培訓。"},{"en":"To undertake leadership training means to take part in training that develops leadership skills.","zh":"undertake leadership training 指參與培養領導能力的培訓。"},{"en":"New prefects may undertake leadership training before guiding younger students.","zh":"新領袖生在指導年幼學生前，可能接受領導才能培訓。"},{"en":"If graduates undertake leadership training, they may learn communication, decision-making and teamwork.","zh":"如果畢業生接受領導才能培訓，他們可能學習溝通、決策和團隊合作。"},{"en":"The phrase describes active participation in skill development.","zh":"這個短語描述主動參與技能發展。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":13},{"front":"emerge from the programme with","meaning":"完成計劃後具備……","examples":[{"en":"Candidates emerge from the programme with a range of skills and experiences.","zh":"候選人完成計劃後具備一系列技能和經驗。"},{"en":"To emerge from a programme with something means to finish it having gained that thing.","zh":"emerge from the programme with 某物，指完成計劃時已獲得該東西。"},{"en":"Students may emerge from a debating course with greater confidence.","zh":"學生完成辯論課程後，可能具備更大信心。"},{"en":"If participants emerge with strong skills, the programme has probably challenged them well.","zh":"如果參加者完成後具備強大技能，該計劃可能給予了良好挑戰。"},{"en":"The phrase describes what people gain after completing a programme.","zh":"這個短語描述人們完成計劃後獲得甚麼。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":13},{"front":"a range of skills and experiences","meaning":"一系列技能和經驗","examples":[{"en":"The programme gives graduates a range of skills and experiences.","zh":"該計劃給予畢業生一系列技能和經驗。"},{"en":"A range of skills and experiences means many different abilities and practical lessons.","zh":"a range of skills and experiences 指許多不同能力和實際經驗。"},{"en":"A summer internship can give students a range of skills and experiences, from teamwork to client communication.","zh":"暑期實習可以給學生一系列技能和經驗，從團隊合作到客戶溝通。"},{"en":"If graduates gain varied experience, they become more flexible in future jobs.","zh":"如果畢業生獲得多樣經驗，他們在未來工作中會更靈活。"},{"en":"The phrase stresses breadth of learning.","zh":"這個短語強調學習範圍廣。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":13},{"front":"in the long term","meaning":"長遠而言","examples":[{"en":"Teach First hopes its graduates will be ambassadors in the long term.","zh":"Teach First 希望其畢業生長遠而言會成為倡導者。"},{"en":"In the long term means over a long future period, not immediately.","zh":"in the long term 指在較長未來時期內，而不是立即。"},{"en":"Regular reading helps vocabulary in the long term, even if progress feels slow.","zh":"定期閱讀長遠而言有助詞彙，即使進步感覺緩慢。"},{"en":"If a programme changes attitudes in the long term, its impact lasts beyond the first year.","zh":"如果計劃長遠而言改變態度，其影響會超越第一年。"},{"en":"The phrase focuses on future results over time.","zh":"這個短語重點在隨時間出現的未來結果。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":13},{"front":"ambassadors","meaning":"大使；倡導者","examples":[{"en":"Teach First hopes its graduates will become ambassadors for its mission.","zh":"Teach First 希望其畢業生成為其使命的倡導者。"},{"en":"Ambassadors are people who represent, promote or speak for a cause or organisation.","zh":"ambassadors 是代表、推廣或為某事業或機構發聲的人。"},{"en":"Former students can become ambassadors for a school by sharing positive experiences.","zh":"舊生可以透過分享正面經驗成為學校的大使。"},{"en":"If graduates support a mission after leaving, they act as ambassadors in wider society.","zh":"如果畢業生離開後仍支持使命，他們就在更廣泛社會中充當倡導者。"},{"en":"The word can mean official diplomats or informal advocates.","zh":"這個字可以指正式外交官，也可以指非正式倡導者。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":13},{"front":"continue to support","meaning":"繼續支持","examples":[{"en":"The graduates are expected to continue to support disadvantaged students.","zh":"畢業生預期會繼續支持弱勢學生。"},{"en":"To continue to support someone means to keep helping them after an earlier stage.","zh":"continue to support 某人，指在早前階段後繼續幫助他們。"},{"en":"A mentor may continue to support a student after the programme ends.","zh":"導師可能在計劃結束後繼續支持學生。"},{"en":"If graduates continue to support schools, the scheme’s impact lasts longer.","zh":"如果畢業生繼續支持學校，該計劃的影響會持續更久。"},{"en":"The phrase stresses ongoing help.","zh":"這個短語強調持續協助。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":13},{"front":"the educationally disadvantaged","meaning":"教育上處於弱勢的人","examples":[{"en":"The scheme supports the educationally disadvantaged.","zh":"該計劃支持教育上處於弱勢的人。"},{"en":"The educationally disadvantaged are people who have fewer learning opportunities because of poverty, poor schools or social barriers.","zh":"the educationally disadvantaged 是因貧窮、學校不足或社會障礙而學習機會較少的人。"},{"en":"Free tutoring can help the educationally disadvantaged prepare for important exams.","zh":"免費補習可以幫助教育上處於弱勢的人準備重要考試。"},{"en":"If disadvantaged students receive strong teachers, their future choices may improve.","zh":"如果弱勢學生得到優秀老師，他們未來選擇可能改善。"},{"en":"The phrase refers to unequal access to education.","zh":"這個短語指教育機會不平等。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":13},{"front":"be expected to take up","meaning":"預計會接受","examples":[{"en":"This year, 260 graduates are expected to take up the Teach First challenge.","zh":"今年預計有260名畢業生會接受 Teach First 的挑戰。"},{"en":"To be expected to take up something means people think someone will accept or start it.","zh":"be expected to take up 某事，指人們預計某人會接受或開始它。"},{"en":"New teachers are expected to take up their posts before term begins.","zh":"新老師預計會在學期開始前上任。"},{"en":"If many graduates are expected to take up a challenge, the programme is growing.","zh":"如果預計許多畢業生會接受挑戰，該計劃正在成長。"},{"en":"The phrase describes a predicted acceptance of an opportunity.","zh":"這個短語描述預期接受某機會。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":13},{"front":"take up the challenge","meaning":"接受挑戰","examples":[{"en":"Graduates are expected to take up the Teach First challenge.","zh":"畢業生預計會接受 Teach First 的挑戰。"},{"en":"To take up the challenge means to accept a difficult task willingly.","zh":"take up the challenge 指願意接受困難任務。"},{"en":"A student may take up the challenge of speaking English every day for a month.","zh":"學生可能接受每天說英文一個月的挑戰。"},{"en":"If graduates take up a difficult teaching challenge, they must be ready for pressure and growth.","zh":"如果畢業生接受困難教學挑戰，他們必須準備好面對壓力和成長。"},{"en":"The phrase suggests courage and active acceptance.","zh":"這個短語暗示勇氣和主動接受。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":13},{"front":"over the coming years","meaning":"未來數年","examples":[{"en":"More graduates are expected over the coming years.","zh":"未來數年預計會有更多畢業生加入。"},{"en":"Over the coming years means during the next several years.","zh":"over the coming years 指在接下來幾年期間。"},{"en":"A school may expand its library over the coming years.","zh":"學校可能在未來數年擴建圖書館。"},{"en":"If a programme grows over the coming years, it may need more staff and funding.","zh":"如果計劃在未來數年增長，它可能需要更多人手和資金。"},{"en":"The phrase points to a future period, not one exact date.","zh":"這個短語指未來一段時間，而不是一個確切日期。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":14},{"front":"expand to","meaning":"擴展至","examples":[{"en":"The scheme will expand to Birmingham and three other cities.","zh":"該計劃將擴展至伯明翰和另外三個城市。"},{"en":"To expand to a place means to begin operating in that place as well.","zh":"expand to 某地，指也開始在該地運作。"},{"en":"A tutoring centre may expand to another district after attracting many students.","zh":"補習中心吸引許多學生後，可能擴展至另一區。"},{"en":"If a programme expands to more cities, more people can take part.","zh":"如果計劃擴展至更多城市，更多人可以參與。"},{"en":"The phrase describes geographical growth.","zh":"這個短語描述地理上的增長。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":14},{"front":"the first set of recruits","meaning":"第一批招募成員","examples":[{"en":"The first set of recruits has completed the programme.","zh":"第一批招募成員已完成該計劃。"},{"en":"The first set of recruits means the first group of people accepted into a programme or job.","zh":"the first set of recruits 指第一組被接納進入計劃或工作的人成員。"},{"en":"A company may train the first set of recruits before hiring a larger group.","zh":"公司可能先培訓第一批招募成員，再聘請更大群體。"},{"en":"If the first recruits succeed, the programme gains evidence that it can work.","zh":"如果第一批成員成功，該計劃就得到可行證據。"},{"en":"The phrase identifies the earliest intake of participants.","zh":"這個短語指出最早一批參加者。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":14},{"front":"complete the programme","meaning":"完成該計劃","examples":[{"en":"The first set of recruits completed the programme.","zh":"第一批招募成員完成該計劃。"},{"en":"To complete the programme means to finish all required parts of it.","zh":"complete the programme 指完成該計劃的所有要求部分。"},{"en":"Students complete a leadership programme after attending workshops and finishing projects.","zh":"學生參加工作坊並完成項目後，完成領導計劃。"},{"en":"If participants complete the programme, they may receive certification or move to the next stage.","zh":"如果參加者完成計劃，他們可能獲得證書或進入下一階段。"},{"en":"The phrase stresses finishing, not merely starting.","zh":"這個短語強調完成，而不只是開始。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":14},{"front":"go on to work for","meaning":"之後去為……工作","examples":[{"en":"Half of the recruits have gone on to work for other companies.","zh":"一半招募成員之後去為其他公司工作。"},{"en":"To go on to work for someone means to later take a job with that employer.","zh":"go on to work for 某僱主，指之後受聘於該僱主。"},{"en":"After an internship, a student may go on to work for the same company full time.","zh":"實習後，學生可能之後全職為同一公司工作。"},{"en":"If graduates go on to work elsewhere, the programme still influences their later careers.","zh":"如果畢業生之後到其他地方工作，該計劃仍影響他們後來的事業。"},{"en":"The phrase describes the next career step.","zh":"這個短語描述下一步職業去向。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":14},{"front":"choose to stay on","meaning":"選擇留下","examples":[{"en":"The other half have chosen to stay on in their schools.","zh":"另一半選擇留在他們的學校。"},{"en":"To choose to stay on means to decide to remain after the expected period ends.","zh":"choose to stay on 指在預期時期結束後決定留下。"},{"en":"A student helper may choose to stay on after class to support younger pupils.","zh":"學生助手可能選擇課後留下，支援年幼學生。"},{"en":"If teachers choose to stay on, the school keeps valuable experience.","zh":"如果老師選擇留下，學校就保留寶貴經驗。"},{"en":"The phrase suggests voluntary continuation.","zh":"這個短語暗示自願繼續。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":14},{"front":"for a further year","meaning":"再多一年","examples":[{"en":"Some graduates stayed on in their schools for a further year.","zh":"一些畢業生在學校再多留一年。"},{"en":"For a further year means for one additional year.","zh":"for a further year 指額外多一年。"},{"en":"A tenant may stay in a flat for a further year after renewing the contract.","zh":"租客續約後，可能在單位再住一年。"},{"en":"If a teacher stays for a further year, students benefit from continuity.","zh":"如果老師再留一年，學生會受惠於延續性。"},{"en":"The phrase adds one more year to an existing period.","zh":"這個短語在原有時期上增加一年。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":14},{"front":"leadership roles","meaning":"領導職位","examples":[{"en":"Twenty per cent stayed in leadership roles.","zh":"百分之二十的人留在領導職位。"},{"en":"Leadership roles are positions that involve guiding, managing or influencing others.","zh":"leadership roles 是涉及指導、管理或影響他人的職位。"},{"en":"A student may take leadership roles as a prefect, club chair or team captain.","zh":"學生可能擔任領袖生、學會主席或隊長等領導職位。"},{"en":"If graduates enter leadership roles early, they gain responsibility quickly.","zh":"如果畢業生早期進入領導職位，他們會快速取得責任。"},{"en":"The phrase describes positions with authority and responsibility.","zh":"這個短語描述帶有權力和責任的位置。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":14},{"front":"more than half of students","meaning":"超過一半學生","examples":[{"en":"More than half of students were concerned about work–life balance.","zh":"超過一半學生關心工作與生活平衡。"},{"en":"More than half of students means a majority of the students.","zh":"more than half of students 指學生中的多數。"},{"en":"More than half of students in a class may prefer online submission for homework.","zh":"班上超過一半學生可能較喜歡網上提交功課。"},{"en":"If more than half of students share a concern, employers should take it seriously.","zh":"如果超過一半學生有同一憂慮，僱主應認真看待。"},{"en":"The phrase indicates a result above 50 per cent.","zh":"這個短語表示高於百分之五十的結果。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":14},{"front":"be concerned about","meaning":"關心；擔心","examples":[{"en":"Students were concerned about achieving a good work–life balance.","zh":"學生關心能否達致良好的工作與生活平衡。"},{"en":"To be concerned about something means to worry about it or consider it important.","zh":"be concerned about 某事，指擔心它或認為它重要。"},{"en":"Parents may be concerned about children using phones late at night.","zh":"家長可能擔心孩子深夜使用手機。"},{"en":"If graduates are concerned about working hours, employers may need clearer policies.","zh":"如果畢業生關心工作時間，僱主可能需要更清晰政策。"},{"en":"The phrase can mean worry or serious interest.","zh":"這個短語可以表示擔心，也可以表示重視。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":14},{"front":"achieve a good work–life balance","meaning":"達致良好的工作與生活平衡","examples":[{"en":"Many students wanted to achieve a good work–life balance.","zh":"許多學生想達致良好的工作與生活平衡。"},{"en":"To achieve a good work–life balance means to have enough time and energy for both work and personal life.","zh":"achieve a good work–life balance 指有足夠時間和精力兼顧工作與私人生活。"},{"en":"A teacher may achieve better work–life balance by setting clear marking hours.","zh":"老師可能透過設定清楚批改時間，達致更好的工作與生活平衡。"},{"en":"If employees cannot balance work and life, stress and burnout may increase.","zh":"如果員工不能平衡工作和生活，壓力和倦怠可能增加。"},{"en":"The phrase describes a healthy relationship between job demands and private life.","zh":"這個短語描述工作要求與私人生活之間的健康關係。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":15},{"front":"a third said","meaning":"三分之一表示","examples":[{"en":"A third said they wanted a job that would challenge them.","zh":"三分之一表示他們想要一份具挑戰性的工作。"},{"en":"A third said means one out of three people in the group stated something.","zh":"a third said 指群體中三分之一的人表示某事。"},{"en":"A third of the class said they preferred group projects to individual essays.","zh":"班上三分之一學生表示他們較喜歡小組項目而不是個人文章。"},{"en":"If a third of students want challenge, employers should not advertise only comfort and stability.","zh":"如果三分之一學生想要挑戰，僱主不應只宣傳舒適和穩定。"},{"en":"The phrase reports a survey proportion.","zh":"這個短語報告調查比例。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":15},{"front":"a job that would challenge them","meaning":"具挑戰性的工作","examples":[{"en":"Some students wanted a job that would challenge them.","zh":"一些學生想要一份具挑戰性的工作。"},{"en":"A job that would challenge them is work that pushes them to use and develop their abilities.","zh":"a job that would challenge them 是推動他們使用和發展能力的工作。"},{"en":"A graduate may choose a difficult teaching role because she wants a job that challenges her.","zh":"畢業生可能選擇困難教學職位，因為她想要具挑戰性的工作。"},{"en":"If a job challenges people well, they may learn faster and feel more engaged.","zh":"如果工作能適度挑戰人，他們可能學得更快並更投入。"},{"en":"The phrase describes demanding work with growth potential.","zh":"這個短語描述要求高且有成長潛力的工作。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":15},{"front":"tend to focus more on","meaning":"傾向較重視……","examples":[{"en":"Male students tended to focus more on practical aspects of work.","zh":"男學生傾向較重視工作的實際方面。"},{"en":"To tend to focus more on something means to usually pay more attention to it.","zh":"tend to focus more on 某事，指通常更注意它。"},{"en":"Some students tend to focus more on exam marks than on long-term learning.","zh":"有些學生傾向較重視考試分數，而不是長期學習。"},{"en":"If graduates focus more on salary and stability, employers may emphasise practical benefits.","zh":"如果畢業生較重視薪金和穩定，僱主可能強調實際好處。"},{"en":"The phrase describes a general pattern, not a rule for everyone.","zh":"這個短語描述一般模式，而不是每個人都如此。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":15},{"front":"practical aspects of work","meaning":"工作的實際方面","examples":[{"en":"Male students focused more on practical aspects of work.","zh":"男學生較重視工作的實際方面。"},{"en":"Practical aspects of work are concrete job features such as pay, hours, training and location.","zh":"practical aspects of work 是薪酬、工時、培訓和地點等具體工作特點。"},{"en":"Before accepting a job, students may compare practical aspects like commuting time and overtime pay.","zh":"接受工作前，學生可能比較通勤時間和加班費等實際方面。"},{"en":"If practical aspects are poor, even meaningful work may become hard to sustain.","zh":"如果實際方面很差，即使工作有意義也可能難以持續。"},{"en":"The phrase refers to real job conditions, not only ideals.","zh":"這個短語指真實工作條件，而不只是理想。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":15},{"front":"building a sound financial base","meaning":"建立穩健的財務基礎","examples":[{"en":"Some students focused on building a sound financial base.","zh":"一些學生重視建立穩健的財務基礎。"},{"en":"Building a sound financial base means creating stable money support for future life.","zh":"building a sound financial base 指為未來生活建立穩定金錢支援。"},{"en":"A young worker may build a sound financial base by saving regularly and avoiding debt.","zh":"年輕員工可以透過定期儲蓄和避免負債建立穩健財務基礎。"},{"en":"If graduates want financial security, they may choose jobs with clear pay and benefits.","zh":"如果畢業生想要財務安全，他們可能選擇薪酬和福利清晰的工作。"},{"en":"The phrase connects career choice with long-term money stability.","zh":"這個短語把職業選擇與長期金錢穩定連繫起來。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":15},{"front":"have a more idealistic outlook","meaning":"有較理想主義的看法","examples":[{"en":"Women had a more idealistic outlook on careers.","zh":"女性對事業有較理想主義的看法。"},{"en":"To have a more idealistic outlook means to care more about values, purpose and social good.","zh":"have a more idealistic outlook 指更重視價值、目的和社會福祉。"},{"en":"A student with an idealistic outlook may choose charity work over a higher-paying job.","zh":"有理想主義看法的學生可能選擇慈善工作，而不是薪金較高的工作。"},{"en":"If graduates have an idealistic outlook, they may ask whether work helps society.","zh":"如果畢業生有理想主義看法，他們可能問工作是否幫助社會。"},{"en":"The phrase contrasts values-based thinking with mainly practical concerns.","zh":"這個短語把價值導向思考與主要實際考慮作對比。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":15},{"front":"making a contribution to society","meaning":"對社會作出貢獻","examples":[{"en":"Many women saw making a contribution to society as a key career goal.","zh":"許多女性把對社會作出貢獻視為主要事業目標。"},{"en":"Making a contribution to society means doing work that helps other people or the community.","zh":"making a contribution to society 指做有助他人或社區的工作。"},{"en":"A doctor, teacher or social worker may feel they are making a contribution to society.","zh":"醫生、老師或社工可能覺得自己正在對社會作出貢獻。"},{"en":"If a job improves lives, employees may find it meaningful beyond salary.","zh":"如果工作改善人們生活，員工可能覺得它在薪金以外也有意義。"},{"en":"The phrase connects work with social value.","zh":"這個短語把工作與社會價值連繫起來。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":15},{"front":"key career goal","meaning":"主要事業目標","examples":[{"en":"Making a contribution to society was a key career goal.","zh":"對社會作出貢獻是主要事業目標。"},{"en":"A key career goal is one of the most important things a person wants from work.","zh":"key career goal 是一個人從工作中最想得到的重要事情之一。"},{"en":"For some graduates, learning new skills is a key career goal.","zh":"對一些畢業生而言，學習新技能是主要事業目標。"},{"en":"If social impact is a key career goal, public service jobs may be attractive.","zh":"如果社會影響是主要事業目標，公共服務工作可能很吸引。"},{"en":"The phrase identifies a main aim in working life.","zh":"這個短語指出工作人生中的主要目標。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":15},{"front":"paid overtime","meaning":"有薪加班","examples":[{"en":"Almost half of all students said paid overtime was important.","zh":"接近一半學生表示有薪加班很重要。"},{"en":"Paid overtime is extra pay for working beyond normal hours.","zh":"paid overtime 是超出正常工時工作所得到的額外薪酬。"},{"en":"A nurse may receive paid overtime after working an additional evening shift.","zh":"護士在額外上一個夜班後，可能獲得有薪加班。"},{"en":"If overtime is unpaid, employees may feel their extra effort is not respected.","zh":"如果加班無薪，員工可能覺得額外努力不被尊重。"},{"en":"The phrase is part of pay and working-condition discussions.","zh":"這個短語屬於薪酬和工作條件討論。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":15},{"front":"key part of","meaning":"……的重要部分","examples":[{"en":"Paid overtime was a key part of a compensation package.","zh":"有薪加班是薪酬福利方案的重要部分。"},{"en":"A key part of something is an important element within it.","zh":"key part of 某事，是其中重要元素。"},{"en":"Clear feedback is a key part of effective writing lessons.","zh":"清楚回饋是有效寫作課的重要部分。"},{"en":"If paid overtime is a key part of a package, students care about fair reward for extra work.","zh":"如果有薪加班是方案的重要部分，學生就重視額外工作的公平回報。"},{"en":"The phrase identifies an essential component.","zh":"這個短語指出必要組成部分。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":16},{"front":"compensation package","meaning":"薪酬福利方案","examples":[{"en":"Students cared about the company compensation package.","zh":"學生關心公司的薪酬福利方案。"},{"en":"A compensation package is the total pay and benefits an employer offers.","zh":"compensation package 是僱主提供的總薪酬和福利。"},{"en":"A compensation package may include salary, bonuses, overtime pay, pension and insurance.","zh":"薪酬福利方案可能包括薪金、花紅、加班費、退休金和保險。"},{"en":"If a compensation package is strong, graduates may choose that employer over another.","zh":"如果薪酬福利方案優厚，畢業生可能選擇該僱主而非另一間。"},{"en":"The phrase refers to more than salary alone.","zh":"這個短語指的不只是薪金。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":16},{"front":"apart from salary","meaning":"除薪金以外","examples":[{"en":"Apart from salary, business students valued performance-related bonuses.","zh":"除薪金以外，商科學生重視與表現掛鈎的花紅。"},{"en":"Apart from salary means besides the basic pay.","zh":"apart from salary 指除了基本薪酬之外。"},{"en":"Apart from salary, graduates may consider training, location and working hours.","zh":"除薪金以外，畢業生可能考慮培訓、地點和工時。"},{"en":"If students look beyond salary, employers must explain wider benefits clearly.","zh":"如果學生看重薪金以外的因素，僱主必須清楚解釋更廣泛福利。"},{"en":"The phrase adds other considerations beyond pay.","zh":"這個短語加入薪酬以外的其他考慮。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":16},{"front":"performance-related bonuses","meaning":"與表現掛鈎的花紅","examples":[{"en":"Business students valued performance-related bonuses.","zh":"商科學生重視與表現掛鈎的花紅。"},{"en":"Performance-related bonuses are extra payments linked to how well someone works or how well the company performs.","zh":"performance-related bonuses 是與個人工作表現或公司表現相連的額外付款。"},{"en":"A salesperson may receive performance-related bonuses after reaching sales targets.","zh":"銷售員達成銷售目標後，可能收到與表現掛鈎的花紅。"},{"en":"If bonuses depend on performance, workers may feel motivated but also pressured.","zh":"如果花紅取決於表現，員工可能感到受激勵，但也有壓力。"},{"en":"The phrase connects pay with results.","zh":"這個短語把薪酬與結果連繫起來。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":16},{"front":"important considerations","meaning":"重要考慮因素","examples":[{"en":"Retirement plans were important considerations for humanities students.","zh":"退休計劃是人文學科學生的重要考慮因素。"},{"en":"Important considerations are factors that people think carefully about before deciding.","zh":"important considerations 是人們決定前仔細思考的因素。"},{"en":"Safety and travel time are important considerations when parents choose a school.","zh":"安全和交通時間是家長選校時的重要考慮因素。"},{"en":"If pensions are important considerations, students are thinking about long-term security.","zh":"如果退休金是重要考慮因素，學生就在思考長遠保障。"},{"en":"The phrase refers to key factors in a decision.","zh":"這個短語指決策中的關鍵因素。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":16},{"front":"retirement plans","meaning":"退休計劃","examples":[{"en":"Humanities students considered retirement plans important.","zh":"人文學科學生認為退休計劃重要。"},{"en":"Retirement plans are arrangements that help people save money for life after work.","zh":"retirement plans 是幫助人們為退休後生活儲蓄的安排。"},{"en":"A company may offer retirement plans so employees can prepare for the future.","zh":"公司可能提供退休計劃，讓員工為未來準備。"},{"en":"If graduates care about retirement plans, they are thinking beyond their first salary.","zh":"如果畢業生重視退休計劃，他們思考的不只是第一份薪金。"},{"en":"The phrase refers to long-term financial support after working life.","zh":"這個短語指工作生涯後的長期財務支援。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":16},{"front":"working overseas","meaning":"海外工作","examples":[{"en":"Working overseas also scored highly among students.","zh":"海外工作在學生中也得分很高。"},{"en":"Working overseas means having a job in another country.","zh":"working overseas 指在另一個國家工作。"},{"en":"A graduate may enjoy working overseas because it offers travel and cultural experience.","zh":"畢業生可能喜歡海外工作，因為它提供旅行和文化經驗。"},{"en":"If an employer offers overseas work, students who value travel may rank it higher.","zh":"如果僱主提供海外工作，重視旅行的學生可能給它更高排名。"},{"en":"The phrase describes international work, not just a short holiday.","zh":"這個短語描述國際工作，而不只是短暫假期。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":16},{"front":"score highly among","meaning":"在……中得分很高；很受重視","examples":[{"en":"Working overseas scored highly among those surveyed.","zh":"海外工作在受訪者中得分很高。"},{"en":"To score highly among a group means to receive strong approval or high ratings from that group.","zh":"score highly among 某群體，指從該群體得到高評價或強烈認可。"},{"en":"A new school library may score highly among students if it is quiet and comfortable.","zh":"如果新學校圖書館安靜舒適，它可能在學生中得分很高。"},{"en":"If a benefit scores highly, employers may emphasise it in recruitment.","zh":"如果某福利得分很高，僱主可能在招聘中強調它。"},{"en":"The phrase describes strong positive survey results.","zh":"這個短語描述強烈正面調查結果。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":16},{"front":"those surveyed","meaning":"受訪者","examples":[{"en":"Working overseas scored highly among those surveyed.","zh":"海外工作在受訪者中得分很高。"},{"en":"Those surveyed are the people who answered the survey questions.","zh":"those surveyed 是回答調查問題的人。"},{"en":"Those surveyed in a class poll may not represent every student in the school.","zh":"班級投票中的受訪者未必代表全校每個學生。"},{"en":"If those surveyed are mostly final-year students, the results reflect that group.","zh":"如果受訪者主要是最後一年學生，結果就反映該群體。"},{"en":"The phrase identifies the respondents.","zh":"這個短語指出回應調查的人。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":16},{"front":"list something as a priority","meaning":"將……列為優先事項","examples":[{"en":"Many students listed working overseas as a priority.","zh":"許多學生將海外工作列為優先事項。"},{"en":"To list something as a priority means to name it as one of the most important things.","zh":"list something as a priority 指把某事列為最重要的事情之一。"},{"en":"Parents may list safety as a priority when choosing transport for children.","zh":"家長為孩子選擇交通時，可能把安全列為優先事項。"},{"en":"If students list travel as a priority, employers with global offices may seem more attractive.","zh":"如果學生把旅行列為優先事項，有全球辦事處的僱主可能更吸引。"},{"en":"The phrase shows what people value most.","zh":"這個短語顯示人們最重視甚麼。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":16},{"front":"ethical considerations","meaning":"道德考慮","examples":[{"en":"Ethical considerations were mentioned by many students.","zh":"許多學生提到道德考慮。"},{"en":"Ethical considerations are questions about what is right, fair and responsible.","zh":"ethical considerations 是關於甚麼是正確、公平和負責任的問題。"},{"en":"A shopper may think about ethical considerations before buying clothes made cheaply overseas.","zh":"購物者在購買海外廉價製衣前，可能思考道德考慮。"},{"en":"If students consider ethics, companies may need to show fair and responsible behaviour.","zh":"如果學生考慮道德，公司可能需要展示公平和負責任行為。"},{"en":"The phrase connects decisions with moral values.","zh":"這個短語把決定與道德價值連繫起來。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":17},{"front":"corporate social responsibility","meaning":"企業社會責任","examples":[{"en":"Corporate social responsibility was a key factor for many students.","zh":"企業社會責任是許多學生的重要因素。"},{"en":"Corporate social responsibility means a company’s duty to act responsibly toward society and the environment.","zh":"corporate social responsibility 指公司對社會和環境負責任行事的責任。"},{"en":"A company shows corporate social responsibility by reducing waste and treating workers fairly.","zh":"公司透過減少浪費和公平對待員工展示企業社會責任。"},{"en":"If graduates value corporate social responsibility, unethical companies may seem less attractive.","zh":"如果畢業生重視企業社會責任，不道德公司可能較不吸引。"},{"en":"The phrase links business behaviour with social duty.","zh":"這個短語把商業行為與社會責任連繫起來。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":17},{"front":"key considerations when choosing","meaning":"選擇……時的重要考慮因素","examples":[{"en":"Ethics and corporate social responsibility were key considerations when choosing an employer.","zh":"道德和企業社會責任是選擇僱主時的重要考慮因素。"},{"en":"Key considerations when choosing something are the main factors people think about before deciding.","zh":"key considerations when choosing 某物，是人們決定前思考的主要因素。"},{"en":"Distance, fees and teaching quality are key considerations when choosing a school.","zh":"距離、費用和教學質素是選擇學校時的重要考慮因素。"},{"en":"If ethics are key considerations, students may reject employers with poor records.","zh":"如果道德是重要考慮因素，學生可能拒絕紀錄差的僱主。"},{"en":"The phrase highlights what matters most in a choice.","zh":"這個短語突出選擇時最重要的東西。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":17},{"front":"choose an employer","meaning":"選擇僱主","examples":[{"en":"Students considered ethics when choosing an employer.","zh":"學生選擇僱主時會考慮道德。"},{"en":"To choose an employer means to decide which organisation one wants to work for.","zh":"choose an employer 指決定自己想為哪個機構工作。"},{"en":"Graduates may choose an employer after comparing training, salary and values.","zh":"畢業生可能在比較培訓、薪金和價值觀後選擇僱主。"},{"en":"If students choose employers carefully, they are more likely to find suitable jobs.","zh":"如果學生仔細選擇僱主，他們較可能找到合適工作。"},{"en":"The phrase describes a career decision.","zh":"這個短語描述職業決定。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":17},{"front":"the following headings","meaning":"以下標題","examples":[{"en":"Students match the following headings with the paragraphs.","zh":"學生把以下標題與段落配對。"},{"en":"The following headings are the titles listed after the instruction.","zh":"the following headings 是指示後列出的標題。"},{"en":"In a reading task, students read the following headings before matching them to paragraphs.","zh":"在閱讀題中，學生在配對段落前先閱讀以下標題。"},{"en":"If headings are similar, students must focus on the main idea of each paragraph.","zh":"如果標題相似，學生必須集中於每段主旨。"},{"en":"The phrase introduces answer choices in a matching exercise.","zh":"這個短語引出配對練習中的答案選項。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":17},{"front":"best fit","meaning":"最適合","examples":[{"en":"Students decide which paragraph each heading best fits.","zh":"學生判斷每個標題最適合哪一段。"},{"en":"Best fit means the option that matches most accurately.","zh":"best fit 指最準確配合的選項。"},{"en":"A teacher may ask which title is the best fit for a short story.","zh":"老師可能問哪個標題最適合一篇短篇故事。"},{"en":"If two answers seem possible, the best fit is the one matching the main idea, not one small detail.","zh":"如果兩個答案看似可行，最適合的是配合主旨的那個，而不是只配合小細節的那個。"},{"en":"The phrase describes the most suitable choice.","zh":"這個短語描述最合適的選擇。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":17},{"front":"most popular employers","meaning":"最受歡迎僱主","examples":[{"en":"The heading refers to the most popular employers for different students.","zh":"這個標題指不同學生眼中最受歡迎僱主。"},{"en":"Most popular employers are the organisations chosen or liked by the largest number of students.","zh":"most popular employers 是被最多學生選擇或喜歡的機構。"},{"en":"A careers fair may reveal the most popular employers by the length of queues at their stalls.","zh":"招聘會可以透過攤位前排隊長度顯示最受歡迎僱主。"},{"en":"If an employer becomes one of the most popular, it may receive more applications than expected.","zh":"如果僱主成為最受歡迎之一，它可能收到比預期更多申請。"},{"en":"The phrase describes employers with the strongest appeal.","zh":"這個短語描述吸引力最強的僱主。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":17},{"front":"different students","meaning":"不同類別的學生","examples":[{"en":"The passage compares popular employers for different students.","zh":"文章比較不同類別學生眼中的熱門僱主。"},{"en":"Different students means students from different subjects, backgrounds or preference groups.","zh":"different students 指來自不同學科、背景或偏好群體的學生。"},{"en":"Different students may want different jobs because their skills and values are not the same.","zh":"不同學生可能想要不同工作，因為他們的技能和價值觀不一樣。"},{"en":"If survey results vary between different students, one employer may appeal to one group more than another.","zh":"如果調查結果在不同學生之間有差異，某僱主可能較吸引其中一個群體。"},{"en":"The phrase reminds readers not to treat all students as identical.","zh":"這個短語提醒讀者不要把所有學生視為一樣。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":17},{"front":"students’ expectations","meaning":"學生的期望","examples":[{"en":"The final paragraph discusses students’ expectations.","zh":"最後一段討論學生的期望。"},{"en":"Students’ expectations are what students hope or believe an employer or job will provide.","zh":"students’ expectations 是學生希望或相信僱主或工作會提供的東西。"},{"en":"Students’ expectations may include fair pay, training, flexibility and meaningful work.","zh":"學生的期望可能包括公平薪酬、培訓、彈性和有意義工作。"},{"en":"If employers misunderstand students’ expectations, recruitment campaigns may fail.","zh":"如果僱主誤解學生的期望，招聘宣傳可能失敗。"},{"en":"The phrase refers to hopes and requirements students bring to career choices.","zh":"這個短語指學生在職業選擇中帶來的希望和要求。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":17},{"front":"give and develop with","meaning":"回饋並發展","examples":[{"en":"The NHS allows people to give and develop their careers.","zh":"NHS 讓人們可以回饋並發展自己的事業。"},{"en":"To give and develop means to contribute to others while also growing personally or professionally.","zh":"give and develop 指為他人作出貢獻，同時在個人或專業上成長。"},{"en":"A teacher can give to students and develop her own skills at the same time.","zh":"老師可以回饋學生，同時發展自己的技能。"},{"en":"If a job lets people serve society and build a career, it offers both purpose and growth.","zh":"如果一份工作讓人服務社會並建立事業，它就同時提供目的和成長。"},{"en":"The phrase combines contribution with career development.","zh":"這個短語結合貢獻與職業發展。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":17},{"front":"reason for the NHS to be happy","meaning":"NHS值得高興的原因","examples":[{"en":"The ranking gave the NHS a reason to be happy.","zh":"這個排名給了 NHS 值得高興的原因。"},{"en":"A reason for someone to be happy is a positive result or event that gives satisfaction.","zh":"reason for someone to be happy 是令人滿意的正面結果或事件。"},{"en":"A school has reason to be happy when students’ reading scores improve.","zh":"當學生閱讀成績改善，學校有值得高興的原因。"},{"en":"If the NHS rises sharply in employer rankings, it has reason to celebrate.","zh":"如果 NHS 在僱主排名中大幅上升，它就有理由慶祝。"},{"en":"The phrase explains why good news matters.","zh":"這個短語解釋好消息為何重要。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":18},{"front":"according to the text","meaning":"根據文章","examples":[{"en":"According to the text, several statements are true.","zh":"根據文章，幾個陳述是正確的。"},{"en":"According to the text means based on what the passage says, not outside knowledge.","zh":"according to the text 指根據文章所說，而不是外部知識。"},{"en":"According to the text, students chose employers from a fixed list.","zh":"根據文章，學生從固定名單中選擇僱主。"},{"en":"If an answer is not supported by the text, it should not be selected.","zh":"如果答案沒有文章支持，就不應選擇。"},{"en":"The phrase reminds students to use passage evidence.","zh":"這個短語提醒學生使用文章證據。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":18},{"front":"corresponding letters","meaning":"對應字母","examples":[{"en":"Candidates write the corresponding letters in the answer boxes.","zh":"考生在答案框中寫上對應字母。"},{"en":"Corresponding letters are the letters that match the correct options.","zh":"corresponding letters 是與正確選項相配的字母。"},{"en":"In a matching task, students write corresponding letters instead of full sentences.","zh":"在配對題中，學生寫對應字母，而不是完整句子。"},{"en":"If the wrong letter is written, the answer is wrong even if the idea was understood.","zh":"如果寫錯字母，即使理解了意思，答案也會錯。"},{"en":"The phrase describes exam answer format.","zh":"這個短語描述考試答案格式。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":18},{"front":"in any order","meaning":"以任何次序","examples":[{"en":"The five answers can be written in any order.","zh":"五個答案可以以任何次序寫出。"},{"en":"In any order means the sequence does not matter.","zh":"in any order 指次序不重要。"},{"en":"Students may list three reasons in any order if the question accepts all correct answers.","zh":"如果題目接受所有正確答案，學生可以以任何次序列出三個原因。"},{"en":"If answers can be written in any order, accuracy matters more than arrangement.","zh":"如果答案可以以任何次序寫出，準確性比排列更重要。"},{"en":"The phrase removes the need for ranking or sequence.","zh":"這個短語取消排名或順序要求。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":18},{"front":"rate employers","meaning":"評價僱主","examples":[{"en":"Students could rate employers from a given list.","zh":"學生可以從指定名單中評價僱主。"},{"en":"To rate employers means to judge or score organisations as possible places to work.","zh":"rate employers 指評判或給機構作為工作地點的分數。"},{"en":"Graduates may rate employers by salary, culture, training and social impact.","zh":"畢業生可能按薪金、文化、培訓和社會影響評價僱主。"},{"en":"If many students rate an employer highly, it may rise in the survey.","zh":"如果許多學生高度評價某僱主，它可能在調查中上升。"},{"en":"The phrase describes evaluation of potential workplaces.","zh":"這個短語描述對潛在工作場所的評估。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":18},{"front":"on a given list","meaning":"在指定名單上","examples":[{"en":"Students selected employers on a given list.","zh":"學生在指定名單上選擇僱主。"},{"en":"On a given list means from the specific list provided.","zh":"on a given list 指從所提供的特定名單中。"},{"en":"In an exam, students may choose words only from a given list.","zh":"在考試中，學生可能只能從指定名單中選詞。"},{"en":"If choices must come from a given list, students cannot add their own options.","zh":"如果選項必須來自指定名單，學生不能加入自己的選項。"},{"en":"The phrase sets a fixed range of choices.","zh":"這個短語設定固定選擇範圍。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":18},{"front":"rose the most places","meaning":"上升最多位","examples":[{"en":"The question asks which organisation rose the most places.","zh":"題目問哪個機構上升最多位。"},{"en":"Rose the most places means moved upward by the largest number of ranking positions.","zh":"rose the most places 指在排名中上升最多位置。"},{"en":"A student who moves from 30th to 5th has risen more places than one moving from 6th to 2nd.","zh":"從第30升至第5的學生，比從第6升至第2的學生上升更多位。"},{"en":"If an organisation rose the most places, it had the biggest improvement in rank.","zh":"如果某機構上升最多位，它在排名上有最大改善。"},{"en":"The phrase compares the size of upward movement.","zh":"這個短語比較向上移動的幅度。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":18},{"front":"a variety of careers","meaning":"多種職業選擇","examples":[{"en":"The NHS offers a variety of careers outside health care.","zh":"NHS 在醫療護理以外提供多種職業選擇。"},{"en":"A variety of careers means many different kinds of job paths.","zh":"a variety of careers 指許多不同種類的職業路徑。"},{"en":"A large university offers a variety of careers in teaching, IT, finance and student support.","zh":"大型大學提供教學、資訊科技、財務和學生支援等多種職業選擇。"},{"en":"If an employer offers varied careers, graduates from different subjects may apply.","zh":"如果僱主提供多元職業，來自不同學科的畢業生可能申請。"},{"en":"The phrase stresses choice and diversity of roles.","zh":"這個短語強調職位選擇和多樣性。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":18},{"front":"outside health care","meaning":"在醫療護理以外","examples":[{"en":"The NHS offers roles outside health care and clinical work.","zh":"NHS 提供醫療護理和臨床工作以外的職位。"},{"en":"Outside health care means not directly involved in treating or caring for patients.","zh":"outside health care 指不直接涉及治療或照顧病人。"},{"en":"A hospital has jobs outside health care, such as finance, IT and communications.","zh":"醫院有醫療護理以外的工作，例如財務、資訊科技和傳訊。"},{"en":"If graduates know there are roles outside clinical care, more subject groups may consider the NHS.","zh":"如果畢業生知道有臨床護理以外的職位，更多學科群體可能考慮 NHS。"},{"en":"The phrase separates support roles from direct medical work.","zh":"這個短語把支援職位與直接醫療工作分開。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":18},{"front":"fall in popularity","meaning":"受歡迎程度下降","examples":[{"en":"Some companies fell in popularity among students.","zh":"一些公司在學生中受歡迎程度下降。"},{"en":"To fall in popularity means to become less liked or less often chosen.","zh":"fall in popularity 指變得較少人喜歡或較少被選擇。"},{"en":"A restaurant may fall in popularity if service becomes slow.","zh":"如果服務變慢，餐廳受歡迎程度可能下降。"},{"en":"If an employer falls in popularity, it may need to improve communication or benefits.","zh":"如果僱主受歡迎程度下降，它可能需要改善溝通或福利。"},{"en":"The phrase describes declining appeal.","zh":"這個短語描述吸引力下降。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":18},{"front":"be surprised by","meaning":"對……感到驚訝","examples":[{"en":"James Darley was surprised by his organisation’s performance.","zh":"James Darley 對其機構的表現感到驚訝。"},{"en":"To be surprised by something means to find it unexpected.","zh":"be surprised by 某事，指覺得它出乎意料。"},{"en":"A teacher may be surprised by a quiet student’s confident presentation.","zh":"老師可能對安靜學生自信的匯報感到驚訝。"},{"en":"If a small charity performs well in a survey, staff may be surprised by the result.","zh":"如果小型慈善機構在調查中表現出色，員工可能對結果感到驚訝。"},{"en":"The phrase describes reaction to unexpected information.","zh":"這個短語描述對意外資訊的反應。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":19},{"front":"organisation’s performance","meaning":"機構的表現","examples":[{"en":"The question refers to Teach First’s performance in the survey.","zh":"題目指 Teach First 在調查中的機構表現。"},{"en":"An organisation’s performance is how well it does in a task, ranking or situation.","zh":"organisation’s performance 是機構在任務、排名或情況中的表現。"},{"en":"A charity’s performance can be measured by funds raised and people helped.","zh":"慈善機構的表現可以用籌得資金和幫助人數量度。"},{"en":"If an organisation performs strongly in a survey, its public reputation may improve.","zh":"如果機構在調查中表現強勁，其公眾聲譽可能改善。"},{"en":"The phrase describes results achieved by an organisation.","zh":"這個短語描述機構取得的結果。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":19},{"front":"continue in a teaching career","meaning":"繼續從事教學事業","examples":[{"en":"The option asks whether most Teach First teachers continue in teaching.","zh":"選項問大多數 Teach First 老師是否繼續從事教學事業。"},{"en":"To continue in a teaching career means to remain working as a teacher after an initial period.","zh":"continue in a teaching career 指在最初階段後仍然擔任教師。"},{"en":"A graduate may continue in a teaching career after discovering she enjoys helping students grow.","zh":"畢業生發現自己喜歡幫助學生成長後，可能繼續從事教學事業。"},{"en":"If many participants stay in teaching, the programme may have lasting educational impact.","zh":"如果許多參加者留在教學，該計劃可能有持久教育影響。"},{"en":"The phrase describes long-term commitment to the teaching profession.","zh":"這個短語描述對教學專業的長期承諾。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":19},{"front":"achieve a good work–life balance","meaning":"達致良好的工作與生活平衡","examples":[{"en":"Most students wanted to achieve a good work–life balance.","zh":"大多數學生想達致良好的工作與生活平衡。"},{"en":"To achieve a good work–life balance means to manage work without losing health, rest or family time.","zh":"achieve a good work–life balance 指管理工作而不失去健康、休息或家庭時間。"},{"en":"A worker may achieve work–life balance by avoiding emails late at night.","zh":"員工可能透過避免深夜電郵來達致工作與生活平衡。"},{"en":"If a job destroys work–life balance, graduates may leave even with good pay.","zh":"如果工作破壞工作與生活平衡，即使薪金好，畢業生也可能離開。"},{"en":"The phrase describes a sustainable way to work.","zh":"這個短語描述可持續的工作方式。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":19},{"front":"be concerned about working for","meaning":"關心為……工作","examples":[{"en":"The option asks whether business students were concerned about working for an ethical company.","zh":"選項問商科學生是否關心為有道德操守的公司工作。"},{"en":"To be concerned about working for a company means to care or worry about what that employer is like.","zh":"be concerned about working for 某公司，指關心或擔心該僱主是怎樣的。"},{"en":"Students may be concerned about working for a firm with poor treatment of staff.","zh":"學生可能關心是否為一間對員工待遇差的公司工作。"},{"en":"If graduates care about ethics, they may research an employer before applying.","zh":"如果畢業生重視道德，他們可能在申請前研究僱主。"},{"en":"The phrase links career choice with values or worries.","zh":"這個短語把職業選擇與價值或憂慮連繫起來。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":19},{"front":"ethical company","meaning":"有道德操守的公司","examples":[{"en":"Some students considered whether a company was ethical.","zh":"一些學生考慮公司是否有道德操守。"},{"en":"An ethical company acts fairly, honestly and responsibly toward workers, customers and society.","zh":"ethical company 是公平、誠實和負責任地對待員工、顧客和社會的公司。"},{"en":"An ethical company may pay fair wages and reduce environmental harm.","zh":"有道德操守的公司可能支付公平薪酬並減少環境傷害。"},{"en":"If a company behaves unethically, students may avoid applying there.","zh":"如果公司行為不道德，學生可能避免申請。"},{"en":"The phrase describes moral business behaviour.","zh":"這個短語描述有道德的商業行為。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":19},{"front":"choose the correct answer or answers","meaning":"選出正確答案","examples":[{"en":"Candidates choose the correct answer or answers from the options.","zh":"考生從選項中選出正確答案。"},{"en":"Choose the correct answer or answers means select one or more options that match the passage.","zh":"choose the correct answer or answers 指選出一個或多個符合文章的選項。"},{"en":"In reading tests, students must check whether the question asks for one answer or several.","zh":"在閱讀測驗中，學生必須檢查題目要求一個答案還是幾個答案。"},{"en":"If candidates choose too many answers, they may lose marks even when one choice is correct.","zh":"如果考生選太多答案，即使其中一個正確也可能失分。"},{"en":"The phrase gives exam instructions about selection.","zh":"這個短語給出關於選擇的考試指示。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":19},{"front":"survey covered students","meaning":"調查涵蓋學生","examples":[{"en":"The question asks which students the survey covered.","zh":"題目問調查涵蓋哪些學生。"},{"en":"Survey covered students means the survey included those students as participants.","zh":"survey covered students 指調查包括那些學生作為參與者。"},{"en":"A school survey may cover students from all year groups, not only seniors.","zh":"學校調查可能涵蓋所有年級學生，而不只是高年級。"},{"en":"If a survey covers many subjects, its results may show wider student opinion.","zh":"如果調查涵蓋許多學科，其結果可能顯示更廣泛學生意見。"},{"en":"The phrase asks who was included in the research.","zh":"這個短語詢問研究包括了誰。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":19},{"front":"a variety of subjects","meaning":"多種學科","examples":[{"en":"The survey covered students studying a variety of subjects.","zh":"調查涵蓋修讀多種學科的學生。"},{"en":"A variety of subjects means many different academic fields.","zh":"a variety of subjects 指許多不同學術範疇。"},{"en":"A university fair may welcome students from a variety of subjects, including science and humanities.","zh":"大學招聘會可能歡迎來自科學和人文等多種學科的學生。"},{"en":"If a survey includes many subjects, employer preferences can be compared across groups.","zh":"如果調查包括許多學科，就可以比較不同群體的僱主偏好。"},{"en":"The phrase stresses academic diversity.","zh":"這個短語強調學科多樣性。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":19},{"front":"in their last year of studies","meaning":"在最後一年學習中","examples":[{"en":"The option refers to students in their last year of studies only.","zh":"選項只指正在最後一年學習的學生。"},{"en":"In their last year of studies means in the final year before graduation.","zh":"in their last year of studies 指在畢業前的最後一年。"},{"en":"Students in their last year of studies often focus on job applications and final exams.","zh":"在最後一年學習中的學生常專注於求職申請和期末考試。"},{"en":"If a survey includes only final-year students, it may miss younger students’ opinions.","zh":"如果調查只包括最後一年學生，可能錯過年幼學生的意見。"},{"en":"The phrase describes a specific stage of university life.","zh":"這個短語描述大學生活的特定階段。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":19},{"front":"first choice in most categories","meaning":"在大多數類別中是首選","examples":[{"en":"The question asks whether the BBC was first choice in most categories.","zh":"題目問 BBC 是否在大多數類別中是首選。"},{"en":"First choice in most categories means ranked number one in most student groups or sections.","zh":"first choice in most categories 指在大多數學生群體或分類中排名第一。"},{"en":"A university may be first choice in most categories if students from many subjects prefer it.","zh":"如果來自許多學科的學生都偏好某大學，它可能在大多數類別中是首選。"},{"en":"If an employer is first choice in most categories, its appeal is broad and strong.","zh":"如果僱主在大多數類別中是首選，它的吸引力廣而強。"},{"en":"The phrase combines top preference with wide coverage.","zh":"這個短語結合首選和廣泛覆蓋。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":20},{"front":"unpopular with","meaning":"不受……歡迎","examples":[{"en":"The option asks whether the BBC was unpopular with business students.","zh":"選項問 BBC 是否不受商科學生歡迎。"},{"en":"Unpopular with a group means not liked or not chosen by many people in that group.","zh":"unpopular with 某群體，指不被該群體中許多人喜歡或選擇。"},{"en":"A new rule may be unpopular with students if it removes lunch breaks.","zh":"如果新規則取消午膳時間，它可能不受學生歡迎。"},{"en":"If an employer is unpopular with business students, it may receive fewer applications from them.","zh":"如果僱主不受商科學生歡迎，它可能收到較少來自他們的申請。"},{"en":"The phrase describes weak appeal within a particular group.","zh":"這個短語描述在特定群體中的吸引力弱。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":20},{"front":"employ more graduates than","meaning":"聘用比……更多畢業生","examples":[{"en":"The option compares whether one organisation employs more graduates than others.","zh":"選項比較某機構是否聘用比其他機構更多畢業生。"},{"en":"To employ more graduates than another organisation means to hire a larger number of graduates.","zh":"employ more graduates than 另一機構，指聘請更多畢業生。"},{"en":"A large bank may employ more graduates than a small local charity.","zh":"大型銀行可能聘用比本地小型慈善機構更多畢業生。"},{"en":"If one employer hires more graduates, it may have larger training programmes.","zh":"如果某僱主聘請更多畢業生，它可能有較大型培訓計劃。"},{"en":"The phrase compares graduate hiring numbers.","zh":"這個短語比較畢業生聘用數量。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":20},{"front":"choose TWO answers","meaning":"選出兩個答案","examples":[{"en":"Candidates choose two answers from the options.","zh":"考生從選項中選出兩個答案。"},{"en":"Choose TWO answers means exactly two options must be selected.","zh":"choose TWO answers 指必須剛好選兩個選項。"},{"en":"In reading exams, students should circle only two answers when the instruction says “TWO.”","zh":"在閱讀考試中，當指示寫明 TWO 時，學生只應圈兩個答案。"},{"en":"If candidates choose one or three, the answer may be marked wrong.","zh":"如果考生選一個或三個，答案可能被判錯。"},{"en":"The phrase gives a strict number of required answers.","zh":"這個短語給出所需答案的嚴格數量。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":20},{"front":"did well in the survey","meaning":"在調查中表現出色","examples":[{"en":"Sarah Churchman explains why PwC did well in the survey.","zh":"Sarah Churchman 解釋 PwC 為何在調查中表現出色。"},{"en":"To do well in the survey means to receive strong results or a high ranking.","zh":"did well in the survey 指取得強勁結果或高排名。"},{"en":"A school did well in a parent survey after improving communication.","zh":"學校改善溝通後，在家長調查中表現出色。"},{"en":"If a company does well in a graduate survey, its recruitment image improves.","zh":"如果公司在畢業生調查中表現出色，其招聘形象會改善。"},{"en":"The phrase describes successful survey performance.","zh":"這個短語描述成功的調查表現。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":20},{"front":"visit universities","meaning":"到訪大學","examples":[{"en":"PwC often visits universities to meet students.","zh":"PwC 經常到訪大學與學生見面。"},{"en":"To visit universities means to go to campuses for talks, fairs, interviews or recruitment events.","zh":"visit universities 指到校園進行講座、招聘會、面試或招聘活動。"},{"en":"Employers visit universities to explain career paths and answer student questions.","zh":"僱主到訪大學，以解釋職業路徑並回答學生問題。"},{"en":"If a company visits universities regularly, students may remember it more easily.","zh":"如果公司定期到訪大學，學生可能更容易記得它。"},{"en":"The phrase describes direct campus engagement.","zh":"這個短語描述直接校園接觸。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":20},{"front":"provide scholarships","meaning":"提供獎學金","examples":[{"en":"The option asks whether PwC provides many scholarships.","zh":"選項問 PwC 是否提供許多獎學金。"},{"en":"To provide scholarships means to give money or financial support for study.","zh":"provide scholarships 指提供金錢或財務支援讓人讀書。"},{"en":"A company may provide scholarships to students from low-income families.","zh":"公司可能向低收入家庭學生提供獎學金。"},{"en":"If employers provide scholarships, students may become aware of them before graduation.","zh":"如果僱主提供獎學金，學生可能在畢業前已認識它們。"},{"en":"The phrase describes financial support for education.","zh":"這個短語描述教育方面的財務支援。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":20},{"front":"opportunities to travel","meaning":"旅行／海外工作的機會","examples":[{"en":"PwC offers many opportunities to travel.","zh":"PwC 提供許多旅行或海外工作的機會。"},{"en":"Opportunities to travel are chances to visit or work in other places through a job or programme.","zh":"opportunities to travel 是透過工作或計劃到其他地方訪問或工作的機會。"},{"en":"A graduate scheme with overseas projects offers opportunities to travel and meet international teams.","zh":"有海外項目的畢業生計劃提供旅行和接觸國際團隊的機會。"},{"en":"If students value travel, employers with global offices may become more attractive.","zh":"如果學生重視旅行，有全球辦事處的僱主可能變得更吸引。"},{"en":"The phrase describes possible travel experiences, not guaranteed holidays.","zh":"這個短語描述可能的旅行經驗，而不是保證假期。"}],"source":"61 - Patients Are a Virtue.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 62":[{"front":"for those of a certain age","meaning":"對某個年紀的人來說","examples":[{"en":"For those of a certain age, it is hard to think of higher education without thinking of ancient institutions.","zh":"對某個年紀的人來說，很難想到高等教育而不想到古老學府。"},{"en":"For those of a certain age means for people old enough to remember or understand a particular older experience.","zh":"for those of a certain age 指對年紀足以記得或理解某種舊經驗的人來說。"},{"en":"For those of a certain age, paper maps may feel more familiar than phone navigation.","zh":"對某個年紀的人來說，紙本地圖可能比手機導航更熟悉。"},{"en":"This phrase is often used when memories or habits differ between generations.","zh":"當記憶或習慣因世代而異時，常會使用這個短語。"},{"en":"It politely refers to older people without directly saying “old”.","zh":"它是一種有禮貌地指較年長人士的說法，而不是直接說「老」。"}],"source":"62 - The Brains Business.pdf","sourcePage":1},{"front":"educational background","meaning":"教育背景","examples":[{"en":"People with a certain educational background may associate universities with ancient institutions.","zh":"有某種教育背景的人，可能會把大學與古老學府聯繫起來。"},{"en":"Educational background means a person’s history of schooling, training, and qualifications.","zh":"educational background 指一個人的學校教育、培訓和學歷經歷。"},{"en":"An employer may ask about a candidate’s educational background before offering an interview.","zh":"僱主在安排面試前，可能詢問求職者的教育背景。"},{"en":"A person’s educational background can shape how they understand work, society, and opportunity.","zh":"一個人的教育背景可以塑造他如何理解工作、社會和機會。"},{"en":"This phrase refers to education history, not family background alone.","zh":"這個短語指教育經歷，而不只是家庭背景。"}],"source":"62 - The Brains Business.pdf","sourcePage":1},{"front":"higher education","meaning":"高等教育","examples":[{"en":"Higher education is undergoing fundamental changes.","zh":"高等教育正在經歷根本性變化。"},{"en":"Higher education means education after secondary school, especially at universities or colleges.","zh":"higher education 指中學後的教育，尤其是大學或學院教育。"},{"en":"A student enters higher education when they begin a degree at university.","zh":"學生開始在大學攻讀學位時，就是進入高等教育。"},{"en":"Higher education can improve career choices, but it may also bring high costs.","zh":"高等教育可以改善職業選擇，但也可能帶來高昂成本。"},{"en":"This phrase usually refers to advanced study, not primary or secondary school.","zh":"這個短語通常指進階學習，而不是小學或中學。"}],"source":"62 - The Brains Business.pdf","sourcePage":1},{"front":"ancient institutions","meaning":"古老學府","examples":[{"en":"It is hard to think of higher education without thinking of ancient institutions.","zh":"很難想到高等教育而不想到古老學府。"},{"en":"Ancient institutions are very old organisations with a long history and established traditions.","zh":"ancient institutions 指歷史非常悠久、傳統已建立的組織。"},{"en":"Some old libraries are ancient institutions that still influence local education today.","zh":"有些舊圖書館是古老機構，至今仍影響本地教育。"},{"en":"Long history can give institutions prestige, but it can also make change slower.","zh":"悠久歷史可以給機構威望，但也可能令改變較慢。"},{"en":"This phrase suggests age, tradition, and cultural authority.","zh":"這個短語表示年資、傳統和文化權威。"}],"source":"62 - The Brains Business.pdf","sourcePage":1},{"front":"be of a venerable age","meaning":"歷史悠久","examples":[{"en":"Some universities are of a venerable age.","zh":"有些大學歷史悠久。"},{"en":"To be of a venerable age means to be very old in a respected and impressive way.","zh":"be of a venerable age 指非常古老，而且令人尊敬和印象深刻。"},{"en":"A school founded two hundred years ago may be of a venerable age.","zh":"一所創校二百年的學校可以說是歷史悠久。"},{"en":"Age can make an institution respected because many generations have passed through it.","zh":"年代久遠可以令機構受尊敬，因為許多代人曾經在其中經歷。"},{"en":"This phrase is formal and positive, not insulting.","zh":"這個短語較正式，而且帶正面意思，不是貶義。"}],"source":"62 - The Brains Business.pdf","sourcePage":1},{"front":"was founded in","meaning":"創立於","examples":[{"en":"The University of Bologna was founded in 1088.","zh":"博洛尼亞大學創立於 1088 年。"},{"en":"Was founded in means was officially established in a particular year or place.","zh":"was founded in 指在某一年或某地正式成立。"},{"en":"The school was founded in 1950 by a group of local teachers.","zh":"這所學校由一群本地老師於 1950 年創立。"},{"en":"Knowing when an organisation was founded helps people understand its history.","zh":"知道一個組織何時創立，有助人們理解其歷史。"},{"en":"This phrase is used for the beginning of institutions, companies, or movements.","zh":"這個短語用於機構、公司或運動的開端。"}],"source":"62 - The Brains Business.pdf","sourcePage":1},{"front":"a strong sense of tradition","meaning":"強烈的傳統意識","examples":[{"en":"Many universities have a strong sense of tradition.","zh":"許多大學有強烈的傳統意識。"},{"en":"A strong sense of tradition means a deep respect for old customs, ceremonies, and ways of doing things.","zh":"strong sense of tradition 指對舊習俗、典禮和做事方式有深厚尊重。"},{"en":"A school with a strong sense of tradition may keep the same graduation ceremony every year.","zh":"有強烈傳統意識的學校，可能每年保留相同畢業典禮。"},{"en":"Tradition can create identity, but it may also make reform harder.","zh":"傳統可以創造身份認同，但也可能令改革更困難。"},{"en":"This phrase describes attachment to the past.","zh":"這個短語描述對過去的依附。"}],"source":"62 - The Brains Business.pdf","sourcePage":1},{"front":"make the most of","meaning":"充分利用","examples":[{"en":"The truly old universities make the most of their pedigrees.","zh":"真正古老的大學會充分利用自己的歷史淵源。"},{"en":"To make the most of something means to use it as fully and effectively as possible.","zh":"make the most of something 指盡可能充分而有效地使用某事物。"},{"en":"A student can make the most of a short lesson by asking focused questions.","zh":"學生可以透過提出集中問題，充分利用短短一堂課。"},{"en":"Schools make the most of limited space when classrooms serve several purposes.","zh":"當課室可作多種用途，學校就是充分利用有限空間。"},{"en":"This phrase suggests using an advantage wisely.","zh":"這個短語表示明智地運用優勢。"}],"source":"62 - The Brains Business.pdf","sourcePage":1},{"front":"pedigrees","meaning":"歷史淵源；名門背景","examples":[{"en":"Old universities make the most of their pedigrees.","zh":"古老大學會充分利用自己的歷史淵源。"},{"en":"Pedigrees are the respected histories, origins, or backgrounds that give institutions prestige.","zh":"pedigrees 指能給機構帶來聲望的受尊重歷史、起源或背景。"},{"en":"A company with a long pedigree in engineering may use its history to build trust.","zh":"一間在工程方面有悠久背景的公司，可能利用其歷史建立信任。"},{"en":"A strong pedigree can attract students, customers, or supporters.","zh":"強大的歷史淵源可以吸引學生、顧客或支持者。"},{"en":"This word suggests inherited status and reputation.","zh":"這個詞表示承襲而來的地位和名聲。"}],"source":"62 - The Brains Business.pdf","sourcePage":1},{"front":"of a more recent vintage","meaning":"較近期創立的","examples":[{"en":"Universities of a more recent vintage work hard to look old.","zh":"較近期創立的大學會努力讓自己看起來古老。"},{"en":"Of a more recent vintage means created or produced more recently than others.","zh":"of a more recent vintage 指比其他事物較近期創立或製成。"},{"en":"A café of a more recent vintage may decorate itself with old photos to look historic.","zh":"較近期開設的咖啡店可能用舊照片裝飾，讓自己看起來有歷史感。"},{"en":"Newer organisations sometimes borrow old styles to gain respect quickly.","zh":"較新的組織有時借用舊風格，以快速取得尊重。"},{"en":"This phrase politely describes something newer.","zh":"這個短語以較委婉方式描述較新的事物。"}],"source":"62 - The Brains Business.pdf","sourcePage":1},{"front":"create an aura of antiquity","meaning":"營造古老氛圍","examples":[{"en":"Some newer universities try to create an aura of antiquity.","zh":"有些較新的大學嘗試營造古老氛圍。"},{"en":"To create an aura of antiquity means to make something seem old, historic, and traditional.","zh":"create an aura of antiquity 指令某物看起來古老、有歷史感和傳統感。"},{"en":"A new hotel may use stone walls and old-style lamps to create an aura of antiquity.","zh":"新酒店可能使用石牆和復古燈飾來營造古老氛圍。"},{"en":"This atmosphere can make a place feel more prestigious or trustworthy.","zh":"這種氣氛可以令地方感覺更有聲望或更可信。"},{"en":"The phrase suggests appearance, not necessarily real age.","zh":"這個短語表示外觀感覺，不一定是真實年齡。"}],"source":"62 - The Brains Business.pdf","sourcePage":2},{"front":"tradition-loving institutions","meaning":"熱愛傳統的機構","examples":[{"en":"These tradition-loving institutions are facing major changes.","zh":"這些熱愛傳統的機構正面對重大變化。"},{"en":"Tradition-loving institutions are organisations that strongly value old customs and established ways.","zh":"tradition-loving institutions 指非常重視舊習俗和既定做法的組織。"},{"en":"A tradition-loving school may keep uniforms, morning assemblies, and old house names.","zh":"熱愛傳統的學校可能保留校服、早會和舊社制名稱。"},{"en":"Such institutions may feel threatened when society changes quickly.","zh":"當社會迅速變化，這類機構可能感到受威脅。"},{"en":"This phrase describes organisations attached to continuity and heritage.","zh":"這個短語描述依附延續性和傳承的組織。"}],"source":"62 - The Brains Business.pdf","sourcePage":2},{"front":"endure a thunderstorm of changes","meaning":"經歷一場劇烈變革","examples":[{"en":"Universities are enduring a thunderstorm of changes.","zh":"大學正在經歷一場劇烈變革。"},{"en":"To endure a thunderstorm of changes means to experience many sudden and intense changes at once.","zh":"endure a thunderstorm of changes 指同時經歷許多突然而強烈的變化。"},{"en":"A small company may endure a thunderstorm of changes when prices rise, staff leave, and customers move online.","zh":"當價格上升、員工離職、顧客轉到網上，小公司可能經歷一場劇烈變革。"},{"en":"Too many changes at once can create stress, confusion, and resistance.","zh":"太多變化同時出現，可以造成壓力、混亂和抗拒。"},{"en":"This phrase uses weather as a metaphor for severe pressure.","zh":"這個短語用天氣比喻嚴重壓力。"}],"source":"62 - The Brains Business.pdf","sourcePage":2},{"front":"so fundamental that","meaning":"根本到……的程度","examples":[{"en":"The changes are so fundamental that some people question the idea of the university.","zh":"這些變化根本到有些人質疑大學概念的程度。"},{"en":"So fundamental that means so basic and important that it produces a serious result.","zh":"so fundamental that 指某事非常基本且重要，以致產生嚴重結果。"},{"en":"The timetable change was so fundamental that every teacher had to redesign their lessons.","zh":"時間表改動根本到每位老師都要重新設計課堂的程度。"},{"en":"Fundamental changes affect the structure of a system, not just small details.","zh":"根本性變化影響系統結構，而不只是小細節。"},{"en":"This phrase shows that the effect is caused by deep change.","zh":"這個短語顯示結果由深層變化造成。"}],"source":"62 - The Brains Business.pdf","sourcePage":2},{"front":"the very idea of","meaning":"……這個概念本身","examples":[{"en":"Some say the very idea of the university is being challenged.","zh":"有些人說大學這個概念本身正在受到挑戰。"},{"en":"The very idea of something means the basic concept or meaning of that thing itself.","zh":"very idea of something 指某事物本身的基本概念或意義。"},{"en":"Online work challenges the very idea of an office for some companies.","zh":"網上工作對某些公司而言，挑戰了辦公室這個概念本身。"},{"en":"When the very idea of something changes, people question its purpose and identity.","zh":"當某事物本身的概念改變，人們會質疑其目的和身份。"},{"en":"This phrase adds emphasis to the core concept.","zh":"這個短語強調核心概念。"}],"source":"62 - The Brains Business.pdf","sourcePage":2},{"front":"be challenged","meaning":"受到挑戰","examples":[{"en":"The traditional idea of the university is being challenged.","zh":"傳統大學概念正在受到挑戰。"},{"en":"To be challenged means to be questioned, tested, or opposed.","zh":"be challenged 指被質疑、考驗或反對。"},{"en":"A school rule may be challenged if students feel it is unfair.","zh":"如果學生覺得校規不公平，該校規可能受到挑戰。"},{"en":"When old ideas are challenged, people may need to defend or change them.","zh":"當舊想法受到挑戰，人們可能需要捍衛或改變它們。"},{"en":"This phrase shows pressure against an accepted belief or practice.","zh":"這個短語顯示既有信念或做法面對壓力。"}],"source":"62 - The Brains Business.pdf","sourcePage":2},{"front":"experiment with","meaning":"試行；嘗試","examples":[{"en":"Universities are experimenting with new ways of funding.","zh":"大學正在嘗試新的資金來源方法。"},{"en":"To experiment with something means to try it to see whether it works.","zh":"experiment with something 指嘗試某事，看看是否有效。"},{"en":"A teacher may experiment with short videos to see whether students understand grammar better.","zh":"老師可能試用短片，看看學生是否更理解文法。"},{"en":"Experimenting can lead to better methods, but it may also produce mistakes.","zh":"嘗試可以帶來更好方法，但也可能產生錯誤。"},{"en":"This phrase suggests testing rather than fully committing.","zh":"這個短語表示測試，而不是完全承諾。"}],"source":"62 - The Brains Business.pdf","sourcePage":2},{"front":"new ways of funding","meaning":"新的資金來源方法","examples":[{"en":"Universities are experimenting with new ways of funding.","zh":"大學正在試行新的資金來源方法。"},{"en":"New ways of funding are different methods for getting money to support an organisation or project.","zh":"new ways of funding 指獲取金錢以支持組織或項目的不同方法。"},{"en":"A community centre may try new ways of funding, such as donations, workshops, and business sponsorship.","zh":"社區中心可能嘗試新的資金來源方法，例如捐款、工作坊和企業贊助。"},{"en":"Funding methods affect what services an organisation can provide.","zh":"資金方法會影響組織能提供甚麼服務。"},{"en":"This phrase focuses on how money is raised.","zh":"這個短語著重金錢如何籌集。"}],"source":"62 - The Brains Business.pdf","sourcePage":2},{"front":"most notably through","meaning":"最明顯是透過","examples":[{"en":"Universities are raising money most notably through student fees.","zh":"大學正在籌集資金，最明顯是透過學費。"},{"en":"Most notably through means especially or most clearly by using a particular method.","zh":"most notably through 指尤其或最清楚地透過某種方法。"},{"en":"A charity may raise awareness most notably through social media campaigns.","zh":"慈善機構可能提高關注度，最明顯是透過社交媒體宣傳。"},{"en":"This phrase highlights the most important or visible example.","zh":"這個短語突出最重要或最明顯的例子。"},{"en":"It tells readers which method deserves special attention.","zh":"它告訴讀者哪種方法值得特別注意。"}],"source":"62 - The Brains Business.pdf","sourcePage":2},{"front":"student fees","meaning":"學費","examples":[{"en":"Some universities are relying more heavily on student fees.","zh":"有些大學更加依賴學費。"},{"en":"Student fees are the money students pay for studying at a school, college, or university.","zh":"student fees 指學生為在學校、學院或大學讀書而支付的金錢。"},{"en":"A family may save for years to afford student fees at a private college.","zh":"家庭可能儲蓄多年，才能負擔私立學院的學費。"},{"en":"Higher student fees can help universities raise money, but they may reduce access for poorer students.","zh":"較高學費可以幫助大學籌集資金，但可能減少較貧困學生的入學機會。"},{"en":"This phrase refers to tuition-related payments.","zh":"這個短語指與學費相關的付款。"}],"source":"62 - The Brains Business.pdf","sourcePage":2},{"front":"forge partnerships with","meaning":"與……建立合作關係","examples":[{"en":"Universities are forging partnerships with private companies.","zh":"大學正在與私營公司建立合作關係。"},{"en":"To forge partnerships with someone means to build strong working relationships with them.","zh":"forge partnerships with someone 指與某人或某機構建立強而有力的工作關係。"},{"en":"A school may forge partnerships with local businesses to provide student internships.","zh":"學校可能與本地企業建立合作關係，為學生提供實習。"},{"en":"Partnerships can bring money, training, and opportunities, but they may also create conflicts of interest.","zh":"合作關係可以帶來金錢、培訓和機會，但也可能造成利益衝突。"},{"en":"This phrase suggests active effort to build cooperation.","zh":"這個短語表示主動努力建立合作。"}],"source":"62 - The Brains Business.pdf","sourcePage":3},{"front":"private companies","meaning":"私營公司","examples":[{"en":"Some universities are working with private companies.","zh":"有些大學正在與私營公司合作。"},{"en":"Private companies are businesses owned by individuals or groups rather than the government.","zh":"private companies 指由個人或團體擁有、而非由政府擁有的企業。"},{"en":"A private company may sponsor a school technology lab in exchange for publicity.","zh":"私營公司可能贊助學校科技實驗室，以換取宣傳。"},{"en":"Working with private companies can provide resources, but public values must still be protected.","zh":"與私營公司合作可以提供資源，但公共價值仍須受到保護。"},{"en":"This phrase contrasts business organisations with public institutions.","zh":"這個短語把商業組織與公共機構作對比。"}],"source":"62 - The Brains Business.pdf","sourcePage":3},{"front":"engage in mergers and acquisitions","meaning":"進行合併與收購","examples":[{"en":"Universities are engaging in mergers and acquisitions.","zh":"大學正在進行合併與收購。"},{"en":"To engage in mergers and acquisitions means to take part in joining with or buying other organisations.","zh":"engage in mergers and acquisitions 指參與與其他組織合併或收購其他組織。"},{"en":"Two small schools may merge if falling enrolment makes separate operation too expensive.","zh":"如果收生下降令分開營運太昂貴，兩所小學校可能合併。"},{"en":"Mergers can save money, but they may also change identity and staff roles.","zh":"合併可以節省金錢，但也可能改變身份和員工角色。"},{"en":"This phrase is common in business but can also describe institutional restructuring.","zh":"這個短語常見於商業，但也可以描述機構重組。"}],"source":"62 - The Brains Business.pdf","sourcePage":3},{"front":"mergers and acquisitions","meaning":"合併與收購","examples":[{"en":"Mergers and acquisitions are becoming part of university reform.","zh":"合併與收購正成為大學改革的一部分。"},{"en":"Mergers and acquisitions are processes where organisations join together or one takes over another.","zh":"mergers and acquisitions 指組織合併，或一方接管另一方的過程。"},{"en":"A hospital group may grow through mergers and acquisitions with smaller clinics.","zh":"醫院集團可能透過與較小診所合併與收購而擴展。"},{"en":"These processes can increase size and efficiency, but they may reduce independence.","zh":"這些過程可以增加規模和效率，但可能減少自主性。"},{"en":"This phrase describes organisational joining or takeover.","zh":"這個短語描述組織聯合或接管。"}],"source":"62 - The Brains Business.pdf","sourcePage":3},{"front":"tug at the ivy’s roots","meaning":"動搖大學傳統根基","examples":[{"en":"Such changes are tugging at the ivy’s roots.","zh":"這些變化正在動搖大學傳統根基。"},{"en":"To tug at the ivy’s roots means to disturb the deep traditions of old universities.","zh":"tug at the ivy’s roots 指擾動古老大學深層傳統。"},{"en":"Online degrees may tug at the ivy’s roots by questioning whether students must live on campus.","zh":"網上學位可能透過質疑學生是否必須住校而動搖大學傳統根基。"},{"en":"When traditions are pulled at their roots, institutions may feel their identity is threatened.","zh":"當傳統根基被拉扯，機構可能感到身份受到威脅。"},{"en":"This phrase uses ivy as a symbol of old university tradition.","zh":"這個短語用常春藤象徵古老大學傳統。"}],"source":"62 - The Brains Business.pdf","sourcePage":3},{"front":"happen for four reasons","meaning":"基於四個原因發生","examples":[{"en":"These changes are happening for four reasons.","zh":"這些變化基於四個原因發生。"},{"en":"Happen for four reasons means there are four causes behind the changes.","zh":"happen for four reasons 指變化背後有四個原因。"},{"en":"A school may change its timetable for four reasons: transport, staff, costs, and student needs.","zh":"學校可能基於交通、員工、成本和學生需要四個原因改變時間表。"},{"en":"Listing reasons helps readers understand a complex situation step by step.","zh":"列出原因幫助讀者逐步理解複雜情況。"},{"en":"This phrase prepares the reader for an organised explanation.","zh":"這個短語為有條理的解釋作準備。"}],"source":"62 - The Brains Business.pdf","sourcePage":3},{"front":"the democratisation of higher education","meaning":"高等教育民主化；普及化","examples":[{"en":"The first reason is the democratisation of higher education.","zh":"第一個原因是高等教育民主化。"},{"en":"The democratisation of higher education means making university or college study available to many more people.","zh":"democratisation of higher education 指讓大學或學院教育可供更多人接受。"},{"en":"Scholarships and public universities can support the democratisation of higher education.","zh":"獎學金和公立大學可以支持高等教育普及化。"},{"en":"When more people enter higher education, societies may gain skills but universities face pressure.","zh":"當更多人進入高等教育，社會可能獲得技能，但大學也面對壓力。"},{"en":"This phrase links education expansion with wider access.","zh":"這個短語把教育擴展與更廣泛入學機會連繫起來。"}],"source":"62 - The Brains Business.pdf","sourcePage":3},{"front":"massification","meaning":"大眾化；普及化","examples":[{"en":"Educators sometimes call the democratisation of higher education “massification”.","zh":"教育工作者有時把高等教育民主化稱為 massification。"},{"en":"Massification means the expansion of higher education from a small elite group to large numbers of people.","zh":"massification 指高等教育由少數精英擴展至大量人群。"},{"en":"A university system experiences massification when many more ordinary families send children to college.","zh":"當更多普通家庭送孩子入讀大學，大學制度就經歷高等教育大眾化。"},{"en":"Massification increases opportunity, but it can also strain classrooms, staff, and funding.","zh":"大眾化增加機會，但也可能令課室、員工和資金受壓。"},{"en":"This word describes education becoming large-scale and widely available.","zh":"這個詞描述教育變成大規模和廣泛可及。"}],"source":"62 - The Brains Business.pdf","sourcePage":3},{"front":"in the language of","meaning":"用……的說法","examples":[{"en":"Massification is the term used in the language of the educational profession.","zh":"massification 是教育界說法中使用的術語。"},{"en":"In the language of a field means using the special words or terminology of that field.","zh":"in the language of a field 指使用某領域的專門詞語或術語。"},{"en":"In the language of medicine, a heart attack may be called a myocardial infarction.","zh":"用醫學說法，心臟病發可稱為 myocardial infarction。"},{"en":"Specialist language can be precise, but it may confuse outsiders.","zh":"專門語言可以精確，但可能令外行人困惑。"},{"en":"This phrase introduces professional terminology.","zh":"這個短語引入專業術語。"}],"source":"62 - The Brains Business.pdf","sourcePage":3},{"front":"the educational profession","meaning":"教育界","examples":[{"en":"Massification is a term used by the educational profession.","zh":"massification 是教育界使用的術語。"},{"en":"The educational profession means the field of people who work in teaching, schooling, and education policy.","zh":"educational profession 指從事教學、學校管理和教育政策的人所屬領域。"},{"en":"Teachers, principals, curriculum writers, and education researchers belong to the educational profession.","zh":"老師、校長、課程編寫者和教育研究者都屬於教育界。"},{"en":"The profession creates terms to discuss problems more precisely.","zh":"這個專業界別會創造術語，以更精確討論問題。"},{"en":"This phrase refers to the education field as a whole.","zh":"這個短語指整個教育領域。"}],"source":"62 - The Brains Business.pdf","sourcePage":3},{"front":"the rich world","meaning":"富裕國家","examples":[{"en":"Massification has been going on in the rich world for some time.","zh":"高等教育大眾化在富裕國家已持續了一段時間。"},{"en":"The rich world means wealthy countries with developed economies.","zh":"rich world 指經濟已發展的富裕國家。"},{"en":"Universities in the rich world often have more funding and older research systems.","zh":"富裕國家的大學通常有更多資金和較成熟研究制度。"},{"en":"Trends that begin in wealthy countries may later spread to developing countries.","zh":"在富裕國家開始的趨勢，之後可能擴展至發展中國家。"},{"en":"This phrase is a broad way to refer to developed countries.","zh":"這個短語是指已發展國家的概括說法。"}],"source":"62 - The Brains Business.pdf","sourcePage":4},{"front":"have been going on for some time","meaning":"已持續了一段時間","examples":[{"en":"Massification has been going on for some time.","zh":"高等教育大眾化已持續了一段時間。"},{"en":"Have been going on for some time means have continued for a while before now.","zh":"have been going on for some time 指在現在之前已持續一段時間。"},{"en":"Complaints about crowded buses have been going on for some time.","zh":"關於巴士擠迫的投訴已持續了一段時間。"},{"en":"When a problem continues for a long period, people may stop seeing it as temporary.","zh":"當問題持續很久，人們可能不再把它視為暫時現象。"},{"en":"This phrase describes an ongoing process.","zh":"這個短語描述持續中的過程。"}],"source":"62 - The Brains Business.pdf","sourcePage":4},{"front":"the proportion of adults with","meaning":"擁有……的成年人比例","examples":[{"en":"The proportion of adults with higher educational qualifications has increased.","zh":"擁有高等教育學歷的成年人比例已增加。"},{"en":"The proportion of adults with something means the percentage or share of adults who have it.","zh":"proportion of adults with something 指擁有某物的成年人百分比或比例。"},{"en":"A city may measure the proportion of adults with full-time jobs.","zh":"城市可能量度擁有全職工作的成年人比例。"},{"en":"Changes in this proportion can show how society is becoming more educated or skilled.","zh":"這個比例的變化可以顯示社會如何變得更有教育程度或技能。"},{"en":"This phrase is used when discussing population statistics.","zh":"這個短語用於討論人口統計。"}],"source":"62 - The Brains Business.pdf","sourcePage":4},{"front":"higher educational qualifications","meaning":"高等教育學歷","examples":[{"en":"More adults now have higher educational qualifications.","zh":"現在更多成年人擁有高等教育學歷。"},{"en":"Higher educational qualifications are degrees, diplomas, or certificates gained after secondary school.","zh":"higher educational qualifications 指中學後取得的學位、文憑或證書。"},{"en":"A person with a university degree has a higher educational qualification.","zh":"擁有大學學位的人具有高等教育學歷。"},{"en":"More qualifications can improve job opportunities, but they do not guarantee success.","zh":"更多學歷可以改善工作機會，但不保證成功。"},{"en":"This phrase refers to formal education achievements above school level.","zh":"這個短語指學校以上層級的正式教育成就。"}],"source":"62 - The Brains Business.pdf","sourcePage":4},{"front":"developed countries","meaning":"已發展國家","examples":[{"en":"The proportion increased in developed countries.","zh":"這個比例在已發展國家增加。"},{"en":"Developed countries are countries with advanced economies, infrastructure, and education systems.","zh":"developed countries 指擁有先進經濟、基建和教育制度的國家。"},{"en":"Developed countries often have more universities and public services than poorer countries.","zh":"已發展國家通常比貧窮國家有更多大學和公共服務。"},{"en":"Their education trends may influence policy debates elsewhere.","zh":"它們的教育趨勢可能影響其他地方的政策辯論。"},{"en":"This phrase refers to economic development, not moral superiority.","zh":"這個短語指經濟發展，而不是道德上較優越。"}],"source":"62 - The Brains Business.pdf","sourcePage":4},{"front":"almost doubled","meaning":"幾乎翻倍","examples":[{"en":"The proportion of qualified adults almost doubled between 1975 and 2000.","zh":"合資格成年人的比例在 1975 年至 2000 年之間幾乎翻倍。"},{"en":"Almost doubled means increased to nearly twice the original amount.","zh":"almost doubled 指增加至接近原本數量的兩倍。"},{"en":"A class almost doubled in size when enrolment rose from 20 students to 38.","zh":"當收生由 20 人升至 38 人，一班人數幾乎翻倍。"},{"en":"When numbers almost double, schools may need more teachers, rooms, and resources.","zh":"當數字幾乎翻倍，學校可能需要更多老師、課室和資源。"},{"en":"This phrase describes a very large increase.","zh":"這個短語描述非常大的增長。"}],"source":"62 - The Brains Business.pdf","sourcePage":4},{"front":"between…and…","meaning":"在……與……之間","examples":[{"en":"The proportion almost doubled between 1975 and 2000.","zh":"該比例在 1975 年與 2000 年之間幾乎翻倍。"},{"en":"Between…and… gives the starting and ending points of a period or range.","zh":"between…and… 給出一段時間或範圍的起點和終點。"},{"en":"The library is busiest between 4 p.m. and 6 p.m. after school.","zh":"圖書館在放學後下午四時至六時之間最繁忙。"},{"en":"This structure helps readers see exactly which period is being discussed.","zh":"這個結構幫助讀者看清楚討論的是哪一段時間。"},{"en":"It is useful for comparing change over time.","zh":"它適合用於比較隨時間的變化。"}],"source":"62 - The Brains Business.pdf","sourcePage":4},{"front":"from…to…","meaning":"由……上升至……","examples":[{"en":"The figure rose from 22 per cent to 41 per cent.","zh":"該數字由 22% 上升至 41%。"},{"en":"From…to… shows the starting number and the final number after a change.","zh":"from…to… 顯示變化前的起始數字和變化後的最終數字。"},{"en":"The price increased from $10 to $15 after demand rose.","zh":"需求上升後，價格由 10 美元上升至 15 美元。"},{"en":"This pattern makes the direction and size of change clear.","zh":"這個句式令變化方向和幅度清楚。"},{"en":"It is often used in data descriptions.","zh":"它常用於數據描述。"}],"source":"62 - The Brains Business.pdf","sourcePage":4},{"front":"struggle to digest","meaning":"努力消化；艱難應對","examples":[{"en":"Many rich countries are still struggling to digest this huge growth.","zh":"許多富裕國家仍在艱難應對這種巨大增長。"},{"en":"To struggle to digest growth means to have difficulty understanding, managing, or absorbing a rapid increase.","zh":"struggle to digest growth 指難以理解、管理或吸收快速增長。"},{"en":"A school may struggle to digest a sudden rise in student numbers.","zh":"學校可能難以消化學生人數突然上升。"},{"en":"Rapid growth can create pressure on staff, buildings, and budgets.","zh":"快速增長可以對員工、建築和預算造成壓力。"},{"en":"This phrase uses digestion as a metaphor for coping with change.","zh":"這個短語用消化比喻應對變化。"}],"source":"62 - The Brains Business.pdf","sourcePage":4},{"front":"huge growth in numbers","meaning":"人數大幅增長","examples":[{"en":"Universities are struggling to manage huge growth in numbers.","zh":"大學正努力管理人數大幅增長。"},{"en":"Huge growth in numbers means a very large increase in the amount of people or things.","zh":"huge growth in numbers 指人或物的數量非常大幅增加。"},{"en":"A hospital may face huge growth in patient numbers during flu season.","zh":"流感季節期間，醫院可能面對病人人數大幅增長。"},{"en":"Large increases can overwhelm services if resources do not grow as well.","zh":"如果資源沒有同樣增長，大幅增加會壓垮服務。"},{"en":"This phrase focuses on quantity expanding quickly.","zh":"這個短語著重數量快速擴張。"}],"source":"62 - The Brains Business.pdf","sourcePage":4},{"front":"spread to","meaning":"擴展至","examples":[{"en":"Massification is spreading to the developing world.","zh":"高等教育大眾化正擴展至發展中國家。"},{"en":"To spread to a place means to move or extend into that place.","zh":"spread to a place 指移動或延伸到某地方。"},{"en":"Online payment spread to small shops when customers stopped carrying cash.","zh":"當顧客不再攜帶現金，網上付款擴展至小店。"},{"en":"When a trend spreads, new groups begin to experience its effects.","zh":"當趨勢擴散，新群體開始經歷其影響。"},{"en":"This phrase describes expansion from one area to another.","zh":"這個短語描述由一個地區擴展到另一個地區。"}],"source":"62 - The Brains Business.pdf","sourcePage":5},{"front":"the developing world","meaning":"發展中國家","examples":[{"en":"Massification is now spreading to the developing world.","zh":"高等教育大眾化現在正擴展至發展中國家。"},{"en":"The developing world means countries with less wealthy or less industrialised economies.","zh":"developing world 指經濟較不富裕或工業化程度較低的國家。"},{"en":"Universities in the developing world may face rapid growth with limited funding.","zh":"發展中國家的大學可能在資金有限下經歷快速增長。"},{"en":"Education expansion in these countries can create opportunity but also pressure.","zh":"這些國家的教育擴展可以創造機會，但也帶來壓力。"},{"en":"This phrase is broad and should be used carefully because countries differ greatly.","zh":"這個短語很概括，應小心使用，因為各國差異很大。"}],"source":"62 - The Brains Business.pdf","sourcePage":5},{"front":"student population","meaning":"學生人數","examples":[{"en":"China doubled its student population in the late 1990s.","zh":"中國在二十世紀九十年代末令學生人數翻倍。"},{"en":"Student population means the total number of students in a school, university, region, or country.","zh":"student population 指一所學校、一間大學、一個地區或國家的學生總數。"},{"en":"A university with a growing student population may need more dormitories and teachers.","zh":"學生人數上升的大學可能需要更多宿舍和老師。"},{"en":"If the student population rises too quickly, services may become overcrowded.","zh":"如果學生人數上升太快，服務可能變得擠迫。"},{"en":"This phrase focuses on the size of the student body.","zh":"這個短語著重學生群體的規模。"}],"source":"62 - The Brains Business.pdf","sourcePage":5},{"front":"in the late 1990s","meaning":"在二十世紀九十年代末","examples":[{"en":"China doubled its student population in the late 1990s.","zh":"中國在二十世紀九十年代末令學生人數翻倍。"},{"en":"In the late 1990s means near the end of the decade from 1990 to 1999.","zh":"in the late 1990s 指接近 1990 至 1999 年這個十年的尾段。"},{"en":"Many families first used home internet in the late 1990s.","zh":"許多家庭在二十世紀九十年代末首次使用家居互聯網。"},{"en":"This phrase gives an approximate time rather than an exact year.","zh":"這個短語給出大約時間，而不是準確年份。"},{"en":"It helps place changes in historical context.","zh":"它幫助把變化放進歷史語境。"}],"source":"62 - The Brains Business.pdf","sourcePage":5},{"front":"follow suit","meaning":"仿效；跟隨做法","examples":[{"en":"India is trying to follow suit.","zh":"印度正嘗試仿效。"},{"en":"To follow suit means to do the same thing that another person or country has already done.","zh":"follow suit 指跟隨另一人或國家已經做過的做法。"},{"en":"If one school bans phones successfully, nearby schools may follow suit.","zh":"如果一所學校成功禁止手機，附近學校可能跟隨做法。"},{"en":"People follow suit when they think an earlier example is worth copying.","zh":"當人們認為早前例子值得模仿，就會仿效。"},{"en":"This phrase describes imitation of a previous action.","zh":"這個短語描述對先前行動的模仿。"}],"source":"62 - The Brains Business.pdf","sourcePage":5},{"front":"the rise of","meaning":"……的興起","examples":[{"en":"The second reason is the rise of the knowledge economy.","zh":"第二個原因是知識型經濟的興起。"},{"en":"The rise of something means its growth in power, importance, or influence.","zh":"rise of something 指某事在力量、重要性或影響力上的增長。"},{"en":"The rise of online shopping changed how small shops reach customers.","zh":"網上購物的興起改變了小店接觸顧客的方式。"},{"en":"When something rises, people and institutions often need to adapt to it.","zh":"當某事興起，人和機構通常需要適應。"},{"en":"This phrase describes a trend becoming more important.","zh":"這個短語描述趨勢變得更重要。"}],"source":"62 - The Brains Business.pdf","sourcePage":5},{"front":"the knowledge economy","meaning":"知識型經濟","examples":[{"en":"The knowledge economy is changing the role of universities.","zh":"知識型經濟正在改變大學的角色。"},{"en":"The knowledge economy is an economy where ideas, skills, information, and research drive growth.","zh":"knowledge economy 指由思想、技能、資訊和研究推動增長的經濟。"},{"en":"Software design, biotechnology, and data analysis are important in the knowledge economy.","zh":"軟件設計、生物科技和數據分析在知識型經濟中很重要。"},{"en":"In a knowledge economy, education and research become major sources of value.","zh":"在知識型經濟中，教育和研究成為主要價值來源。"},{"en":"This phrase contrasts knowledge with land, factories, or raw materials as the main resource.","zh":"這個短語把知識與土地、工廠或原材料作為主要資源形成對比。"}],"source":"62 - The Brains Business.pdf","sourcePage":5},{"front":"be in the grips of","meaning":"受到……強烈影響；陷入……之中","examples":[{"en":"The world is in the grips of a soft revolution.","zh":"世界正受到一場軟性革命強烈影響。"},{"en":"To be in the grips of something means to be strongly affected or controlled by it.","zh":"be in the grips of something 指受到某事強烈影響或控制。"},{"en":"A city may be in the grips of a housing crisis when rents rise faster than wages.","zh":"當租金升幅快過工資，城市可能陷入住房危機之中。"},{"en":"When a society is in the grips of change, everyday life can shift quickly.","zh":"當社會受到變化強烈影響，日常生活可能快速轉變。"},{"en":"This phrase suggests strong pressure that is difficult to escape.","zh":"這個短語表示難以擺脫的強大壓力。"}],"source":"62 - The Brains Business.pdf","sourcePage":5},{"front":"a soft revolution","meaning":"軟性革命","examples":[{"en":"The world is in the grips of a soft revolution.","zh":"世界正受到一場軟性革命強烈影響。"},{"en":"A soft revolution is a major change that happens through ideas, knowledge, and systems rather than violence.","zh":"soft revolution 指透過思想、知識和制度而非暴力發生的重大變化。"},{"en":"Remote work created a soft revolution in how many offices operate.","zh":"遙距工作在許多辦公室運作方式上創造了一場軟性革命。"},{"en":"Soft revolutions can be quiet but still change jobs, education, and daily habits.","zh":"軟性革命可以安靜地發生，但仍改變工作、教育和日常習慣。"},{"en":"This phrase describes deep change without dramatic physical conflict.","zh":"這個短語描述沒有劇烈實體衝突的深層變化。"}],"source":"62 - The Brains Business.pdf","sourcePage":5},{"front":"replace…as…","meaning":"取代……成為……","examples":[{"en":"Knowledge is replacing physical resources as the main driver of growth.","zh":"知識正在取代實體資源，成為增長的主要推動力。"},{"en":"Replace A as B means take over A’s role as B.","zh":"replace A as B 指取代 A 的角色，成為 B。"},{"en":"Online messages are replacing printed notices as the main way schools contact parents.","zh":"網上訊息正在取代印刷通告，成為學校聯絡家長的主要方式。"},{"en":"When one thing replaces another as the main tool, people must learn new habits.","zh":"當一件事物取代另一件事物成為主要工具，人們必須學習新習慣。"},{"en":"This structure shows a change in role or importance.","zh":"這個結構顯示角色或重要性的變化。"}],"source":"62 - The Brains Business.pdf","sourcePage":5},{"front":"physical resources","meaning":"實體資源","examples":[{"en":"Knowledge is replacing physical resources in the modern economy.","zh":"在現代經濟中，知識正在取代實體資源。"},{"en":"Physical resources are material assets such as land, buildings, machines, minerals, and raw materials.","zh":"physical resources 指土地、建築物、機器、礦物和原材料等物質資產。"},{"en":"A factory depends on physical resources like machines, electricity, and warehouse space.","zh":"工廠依賴機器、電力和倉庫空間等實體資源。"},{"en":"In a knowledge economy, physical resources still matter, but ideas and skills matter more.","zh":"在知識型經濟中，實體資源仍重要，但思想和技能更重要。"},{"en":"This phrase contrasts material things with knowledge or information.","zh":"這個短語把物質事物與知識或資訊作對比。"}],"source":"62 - The Brains Business.pdf","sourcePage":6},{"front":"the main driver of","meaning":"……的主要推動力","examples":[{"en":"Knowledge has become the main driver of economic growth.","zh":"知識已成為經濟增長的主要推動力。"},{"en":"The main driver of something is the most important force causing it to happen.","zh":"main driver of something 指造成某事發生的最重要力量。"},{"en":"Good teaching may be the main driver of improvement in a weak school.","zh":"良好教學可能是薄弱學校進步的主要推動力。"},{"en":"If the main driver changes, policy and investment priorities often change too.","zh":"如果主要推動力改變，政策和投資優先次序通常也會改變。"},{"en":"This phrase identifies the strongest cause behind a result.","zh":"這個短語指出結果背後最強原因。"}],"source":"62 - The Brains Business.pdf","sourcePage":6},{"front":"economic growth","meaning":"經濟增長","examples":[{"en":"Knowledge is increasingly important to economic growth.","zh":"知識對經濟增長越來越重要。"},{"en":"Economic growth means an increase in the value of goods and services produced by an economy.","zh":"economic growth 指一個經濟體所生產的商品和服務價值增加。"},{"en":"New businesses can support economic growth by creating jobs and selling useful products.","zh":"新企業可以透過創造職位和銷售有用產品來支持經濟增長。"},{"en":"Growth can raise living standards, but it may also create inequality if benefits are uneven.","zh":"增長可以提升生活水平，但如果好處分配不均，也可能造成不平等。"},{"en":"This phrase refers to expansion in the economy.","zh":"這個短語指經濟的擴張。"}],"source":"62 - The Brains Business.pdf","sourcePage":6},{"front":"the contribution of…to…","meaning":"……對……的貢獻","examples":[{"en":"The contribution of knowledge-based industries to total value added increased.","zh":"知識型產業對總增值額的貢獻增加了。"},{"en":"The contribution of A to B means how much A adds to or supports B.","zh":"contribution of A to B 指 A 對 B 增加或支援了多少。"},{"en":"The contribution of public transport to clean air grows when fewer people drive cars.","zh":"當較少人駕車，公共交通對清潔空氣的貢獻會增加。"},{"en":"Measuring contribution helps people see which sectors matter most.","zh":"量度貢獻幫助人們看見哪些行業最重要。"},{"en":"This structure links a source with the result it helps create.","zh":"這個結構把來源與它幫助創造的結果連繫起來。"}],"source":"62 - The Brains Business.pdf","sourcePage":6},{"front":"knowledge-based industries","meaning":"知識型產業","examples":[{"en":"Knowledge-based industries have grown in importance.","zh":"知識型產業的重要性已上升。"},{"en":"Knowledge-based industries are businesses that depend mainly on information, research, skills, and ideas.","zh":"knowledge-based industries 指主要依賴資訊、研究、技能和思想的行業。"},{"en":"Software, medical research, finance, and design are often knowledge-based industries.","zh":"軟件、醫學研究、金融和設計通常屬於知識型產業。"},{"en":"These industries need educated workers because value comes from expertise.","zh":"這些產業需要受過教育的工作者，因為價值來自專業知識。"},{"en":"This phrase contrasts knowledge work with industries based mainly on raw materials.","zh":"這個短語把知識工作與主要依賴原材料的行業作對比。"}],"source":"62 - The Brains Business.pdf","sourcePage":6},{"front":"total value added","meaning":"總增值額","examples":[{"en":"The contribution to total value added increased in Germany and Britain.","zh":"在德國和英國，對總增值額的貢獻增加了。"},{"en":"Total value added means the total extra economic value created by production or services.","zh":"total value added 指由生產或服務創造的額外經濟價值總量。"},{"en":"A bakery adds value when flour, labour, and skill become bread that customers buy.","zh":"麵包店把麵粉、勞力和技術變成顧客購買的麵包時，就是增加價值。"},{"en":"Rising value added can show that an industry is becoming more important to the economy.","zh":"增值額上升可以顯示某行業對經濟變得更重要。"},{"en":"This phrase is used in economic measurement.","zh":"這個短語用於經濟量度。"}],"source":"62 - The Brains Business.pdf","sourcePage":6},{"front":"devote investment to","meaning":"將投資投放於……","examples":[{"en":"The best companies devote investment to knowledge-intensive intangibles.","zh":"最優秀的公司將投資投放於知識密集型無形資產。"},{"en":"To devote investment to something means to put money, time, or resources into it seriously.","zh":"devote investment to something 指認真把金錢、時間或資源投放於某事。"},{"en":"A school may devote investment to teacher training rather than only new buildings.","zh":"學校可能將投資投放於教師培訓，而不只是新建築。"},{"en":"Investment choices show what an organisation believes will create future value.","zh":"投資選擇顯示組織相信甚麼會創造未來價值。"},{"en":"This phrase describes deliberate allocation of resources.","zh":"這個短語描述有意識地分配資源。"}],"source":"62 - The Brains Business.pdf","sourcePage":6},{"front":"at least a third of","meaning":"至少三分之一的……","examples":[{"en":"The best companies devote at least a third of their investment to intangibles.","zh":"最優秀的公司將至少三分之一的投資投放於無形資產。"},{"en":"At least a third of something means one third or more of the total amount.","zh":"at least a third of something 指總量的三分之一或以上。"},{"en":"A student may spend at least a third of revision time on weak topics.","zh":"學生可能把至少三分之一的溫習時間花在弱項上。"},{"en":"Using such a large share shows that the area is considered important.","zh":"使用如此大的比例，顯示該範疇被視為重要。"},{"en":"This phrase gives a minimum proportion.","zh":"這個短語給出最低比例。"}],"source":"62 - The Brains Business.pdf","sourcePage":6},{"front":"knowledge-intensive intangibles","meaning":"知識密集型無形資產","examples":[{"en":"Companies invest in knowledge-intensive intangibles such as research and marketing.","zh":"公司投資於研發和市場推廣等知識密集型無形資產。"},{"en":"Knowledge-intensive intangibles are valuable non-physical assets based on expertise, ideas, research, or brand knowledge.","zh":"knowledge-intensive intangibles 指以專業知識、思想、研究或品牌知識為基礎的非實體有價值資產。"},{"en":"Staff training, patents, software, and customer data can be knowledge-intensive intangibles.","zh":"員工培訓、專利、軟件和客戶數據都可以是知識密集型無形資產。"},{"en":"These assets can increase future profits even though they cannot be touched like machines.","zh":"這些資產雖然不能像機器一樣被觸摸，仍可以增加未來利潤。"},{"en":"This phrase describes non-physical value created by knowledge.","zh":"這個短語描述由知識創造的非實體價值。"}],"source":"62 - The Brains Business.pdf","sourcePage":6},{"front":"R&D","meaning":"研發","examples":[{"en":"Companies invest heavily in R&D, licensing and marketing.","zh":"公司大量投資於研發、授權和市場推廣。"},{"en":"R&D means research and development, the work of creating and improving products, services, or technologies.","zh":"R&D 指 research and development，即創造和改善產品、服務或科技的工作。"},{"en":"A medicine company invests in R&D when scientists test new treatments.","zh":"當科學家測試新療法，藥物公司就是在投資研發。"},{"en":"Strong R&D can lead to better products and long-term competitiveness.","zh":"強大的研發可以帶來更好產品和長期競爭力。"},{"en":"This abbreviation is common in business and technology writing.","zh":"這個縮寫常見於商業和科技寫作。"}],"source":"62 - The Brains Business.pdf","sourcePage":6},{"front":"licensing","meaning":"授權","examples":[{"en":"Licensing is one form of knowledge-intensive investment.","zh":"授權是知識密集型投資的一種形式。"},{"en":"Licensing means giving or receiving legal permission to use an idea, product, brand, or technology.","zh":"licensing 指授予或取得使用某個想法、產品、品牌或科技的法律許可。"},{"en":"A school may pay licensing fees to use educational software legally.","zh":"學校可能支付授權費，以合法使用教育軟件。"},{"en":"Licensing lets companies earn money from knowledge without making every product themselves.","zh":"授權讓公司不用親自製造每件產品，也能從知識中賺錢。"},{"en":"This word refers to legal permission, not casual sharing.","zh":"這個詞指法律許可，而不是隨便分享。"}],"source":"62 - The Brains Business.pdf","sourcePage":7},{"front":"marketing","meaning":"市場推廣","examples":[{"en":"Marketing is part of companies’ knowledge-intensive investment.","zh":"市場推廣是公司知識密集型投資的一部分。"},{"en":"Marketing is the work of understanding customers and promoting products or services to them.","zh":"marketing 指理解顧客並向他們推廣產品或服務的工作。"},{"en":"A small bakery uses marketing when it posts photos of fresh bread online.","zh":"小麵包店在網上發布新鮮麵包照片時，就是在做市場推廣。"},{"en":"Good marketing can increase sales by showing customers why a product matters.","zh":"良好市場推廣可以透過顯示產品為何重要來增加銷售。"},{"en":"This word refers to promotion and customer understanding, not selling alone.","zh":"這個詞指推廣和顧客理解，而不只是銷售。"}],"source":"62 - The Brains Business.pdf","sourcePage":7},{"front":"among the most important","meaning":"屬於最重要的……之一","examples":[{"en":"Universities are among the most important engines of the knowledge economy.","zh":"大學屬於知識型經濟最重要的引擎之一。"},{"en":"Among the most important means included in the group of the most important things.","zh":"among the most important 指被包括在最重要事物的群組之中。"},{"en":"Sleep is among the most important factors in student learning.","zh":"睡眠屬於學生學習最重要因素之一。"},{"en":"This phrase shows high importance without saying something is the single most important.","zh":"這個短語顯示高度重要性，但不是說某物是唯一最重要。"},{"en":"It is useful when several things are very important.","zh":"當有幾件事都非常重要時，這個短語很有用。"}],"source":"62 - The Brains Business.pdf","sourcePage":7},{"front":"engines of the knowledge economy","meaning":"知識型經濟的引擎","examples":[{"en":"Universities are engines of the knowledge economy.","zh":"大學是知識型經濟的引擎。"},{"en":"Engines of the knowledge economy are institutions that drive growth by producing ideas, research, and skilled workers.","zh":"engines of the knowledge economy 指透過產生思想、研究和熟練人才來推動增長的機構。"},{"en":"Research centres can be engines of the knowledge economy when they turn discoveries into useful products.","zh":"研究中心把發現轉化成有用產品時，可以成為知識型經濟的引擎。"},{"en":"These engines support innovation by connecting talent, funding, and knowledge.","zh":"這些引擎透過連接人才、資金和知識來支持創新。"},{"en":"This phrase uses “engines” as a metaphor for powerful drivers.","zh":"這個短語用「引擎」比喻強大推動力。"}],"source":"62 - The Brains Business.pdf","sourcePage":7},{"front":"brain workers","meaning":"腦力勞動者；知識工作者","examples":[{"en":"Universities produce the brain workers who support the knowledge economy.","zh":"大學生產支撐知識型經濟的知識工作者。"},{"en":"Brain workers are people whose jobs depend mainly on thinking, analysis, creativity, or specialised knowledge.","zh":"brain workers 指工作主要依賴思考、分析、創意或專門知識的人。"},{"en":"Engineers, designers, researchers, and data analysts are brain workers.","zh":"工程師、設計師、研究員和數據分析師都是知識工作者。"},{"en":"A knowledge economy needs brain workers because ideas and expertise create value.","zh":"知識型經濟需要知識工作者，因為思想和專業知識創造價值。"},{"en":"This phrase contrasts mental labour with mainly physical labour.","zh":"這個短語把腦力勞動與主要體力勞動作對比。"}],"source":"62 - The Brains Business.pdf","sourcePage":7},{"front":"man it","meaning":"為……提供人手","examples":[{"en":"Universities produce the brain workers who man the knowledge economy.","zh":"大學培養為知識型經濟提供人手的知識工作者。"},{"en":"To man something means to provide the people needed to operate or run it.","zh":"man something 指提供運作某事所需的人手。"},{"en":"A hospital needs nurses and doctors to man emergency rooms around the clock.","zh":"醫院需要護士和醫生全天候為急症室提供人手。"},{"en":"If there are not enough trained workers to man a system, services may slow down.","zh":"如果沒有足夠受訓人員支撐系統，服務可能變慢。"},{"en":"This phrase means “staff” or “operate”, not only men specifically.","zh":"這個短語意思是「配備人手」或「運作」，不一定只指男性。"}],"source":"62 - The Brains Business.pdf","sourcePage":7},{"front":"provide much of its backbone","meaning":"提供大部分骨幹支撐","examples":[{"en":"Universities provide much of the backbone of the knowledge economy.","zh":"大學為知識型經濟提供大部分骨幹支撐。"},{"en":"To provide much of its backbone means to supply many of the essential supports that keep it working.","zh":"provide much of its backbone 指提供大量維持其運作的必要支撐。"},{"en":"Public transport provides much of a city’s backbone because workers rely on it daily.","zh":"公共交通為城市提供大部分骨幹支撐，因為工人每天依賴它。"},{"en":"Without backbone support, a system may look large but function poorly.","zh":"沒有骨幹支撐，系統可能看起來龐大但運作不佳。"},{"en":"This phrase uses the body’s backbone as a metaphor for core support.","zh":"這個短語用人體脊骨比喻核心支撐。"}],"source":"62 - The Brains Business.pdf","sourcePage":7},{"front":"laboratories","meaning":"實驗室","examples":[{"en":"Laboratories form part of the backbone of the knowledge economy.","zh":"實驗室構成知識型經濟骨幹的一部分。"},{"en":"Laboratories are rooms or buildings where scientific tests, research, or experiments are carried out.","zh":"laboratories 指進行科學測試、研究或實驗的房間或建築物。"},{"en":"A school laboratory lets students test chemical reactions safely.","zh":"學校實驗室讓學生安全測試化學反應。"},{"en":"Laboratories help create new knowledge by turning questions into experiments.","zh":"實驗室透過把問題轉化為實驗來幫助創造新知識。"},{"en":"This word refers to practical research spaces.","zh":"這個詞指實際研究空間。"}],"source":"62 - The Brains Business.pdf","sourcePage":7},{"front":"computer networks","meaning":"電腦網絡","examples":[{"en":"Universities provide computer networks that support the knowledge economy.","zh":"大學提供支撐知識型經濟的電腦網絡。"},{"en":"Computer networks are connected computers and systems that share data, software, and communication.","zh":"computer networks 指互相連接、可分享數據、軟件和通訊的電腦和系統。"},{"en":"A school computer network lets students access files from different classrooms.","zh":"學校電腦網絡讓學生從不同課室存取文件。"},{"en":"Strong networks support research because people can store, send, and analyse information quickly.","zh":"強大網絡支援研究，因為人們可以快速儲存、傳送和分析資訊。"},{"en":"This phrase refers to digital infrastructure.","zh":"這個短語指數碼基礎設施。"}],"source":"62 - The Brains Business.pdf","sourcePage":7},{"front":"globalisation","meaning":"全球化","examples":[{"en":"The third factor affecting universities is globalisation.","zh":"影響大學的第三個因素是全球化。"},{"en":"Globalisation is the process by which countries, economies, cultures, and institutions become more connected.","zh":"globalisation 指國家、經濟、文化和機構變得更互相連接的過程。"},{"en":"A student experiences globalisation when they take an online course from a university overseas.","zh":"學生修讀海外大學的網上課程時，就經歷全球化。"},{"en":"Globalisation increases exchange, but it also creates more competition.","zh":"全球化增加交流，但也帶來更多競爭。"},{"en":"This word describes growing connection across borders.","zh":"這個詞描述跨國界連繫增長。"}],"source":"62 - The Brains Business.pdf","sourcePage":7},{"front":"the death of distance","meaning":"距離消亡","examples":[{"en":"The death of distance is transforming academia.","zh":"距離消亡正在改變學術界。"},{"en":"The death of distance means technology has made physical distance much less important.","zh":"death of distance 指科技令實體距離變得不那麼重要。"},{"en":"Video calls created a death of distance for many office meetings.","zh":"視像通話讓許多辦公室會議經歷距離消亡。"},{"en":"When distance matters less, universities can teach and compete across borders.","zh":"當距離不再那麼重要，大學可以跨國教學和競爭。"},{"en":"This phrase is a metaphor for easier global connection.","zh":"這個短語是全球連接更容易的比喻。"}],"source":"62 - The Brains Business.pdf","sourcePage":8},{"front":"transform academia","meaning":"改變學術界","examples":[{"en":"Globalisation is transforming academia.","zh":"全球化正在改變學術界。"},{"en":"To transform academia means to change the world of universities, research, and teaching deeply.","zh":"transform academia 指深刻改變大學、研究和教學世界。"},{"en":"Online journals transformed academia by making research easier to share.","zh":"網上期刊透過令研究更易分享而改變學術界。"},{"en":"When academia changes, students, teachers, and researchers all feel the effects.","zh":"當學術界改變，學生、老師和研究人員都會感受到影響。"},{"en":"This phrase describes deep change in the academic world.","zh":"這個短語描述學術世界中的深層變化。"}],"source":"62 - The Brains Business.pdf","sourcePage":8},{"front":"just as radically as","meaning":"與……一樣徹底","examples":[{"en":"Distance is transforming academia just as radically as it is transforming business.","zh":"距離正在與改變商業一樣徹底地改變學術界。"},{"en":"Just as radically as means with the same deep and dramatic level of change.","zh":"just as radically as 指以同樣深刻而劇烈的程度改變。"},{"en":"Smartphones changed shopping just as radically as they changed communication.","zh":"智能手機改變購物的程度，與改變溝通一樣徹底。"},{"en":"This phrase compares two areas affected with equal strength.","zh":"這個短語比較兩個受同等強烈影響的領域。"},{"en":"It shows that the change is not minor in either field.","zh":"它顯示兩個領域中的變化都不是小變化。"}],"source":"62 - The Brains Business.pdf","sourcePage":8},{"front":"study abroad","meaning":"到海外升學","examples":[{"en":"More people from developed countries are studying abroad.","zh":"更多來自已發展國家的人正在到海外升學。"},{"en":"To study abroad means to go to another country for education.","zh":"study abroad 指到另一個國家接受教育。"},{"en":"A student may study abroad to learn a language and experience a different university system.","zh":"學生可能到海外升學，以學習語言並體驗不同大學制度。"},{"en":"Studying abroad can broaden views, but it may also be expensive and stressful.","zh":"海外升學可以擴闊視野，但也可能昂貴和有壓力。"},{"en":"This phrase refers to overseas education.","zh":"這個短語指海外教育。"}],"source":"62 - The Brains Business.pdf","sourcePage":8},{"front":"over the past twenty years","meaning":"在過去二十年間","examples":[{"en":"The number of students studying abroad has doubled over the past twenty years.","zh":"到海外升學的學生人數在過去二十年間翻倍。"},{"en":"Over the past twenty years means during the twenty-year period leading up to now or the time being discussed.","zh":"over the past twenty years 指截至現在或所討論時間之前的二十年期間。"},{"en":"Over the past twenty years, many schools have added more technology to classrooms.","zh":"在過去二十年間，許多學校在課室加入更多科技。"},{"en":"This phrase shows change across a long but recent period.","zh":"這個短語顯示一段長但較近期的變化。"},{"en":"It is useful for describing trends.","zh":"它適合用於描述趨勢。"}],"source":"62 - The Brains Business.pdf","sourcePage":8},{"front":"open campuses","meaning":"開設校園","examples":[{"en":"Universities are opening campuses around the world.","zh":"大學正在世界各地開設校園。"},{"en":"To open campuses means to establish new university sites or branches in different places.","zh":"open campuses 指在不同地方建立新的大學地點或分校。"},{"en":"A university may open a campus in another city to reach more students.","zh":"大學可能在另一個城市開設校園，以接觸更多學生。"},{"en":"New campuses can expand access, but they require staff, buildings, and local support.","zh":"新校園可以擴大入學機會，但需要員工、建築和本地支援。"},{"en":"This phrase describes physical expansion of an institution.","zh":"這個短語描述機構的實體擴張。"}],"source":"62 - The Brains Business.pdf","sourcePage":8},{"front":"all around the world","meaning":"在世界各地","examples":[{"en":"Universities are opening campuses all around the world.","zh":"大學正在世界各地開設校園。"},{"en":"All around the world means in many countries and regions globally.","zh":"all around the world 指在全球許多國家和地區。"},{"en":"Students can now join online competitions with classmates all around the world.","zh":"學生現在可以與世界各地的同學參加網上比賽。"},{"en":"When an institution expands worldwide, it meets new cultures, rules, and markets.","zh":"當機構在全球擴展，它會遇到新文化、規則和市場。"},{"en":"This phrase emphasises global reach.","zh":"這個短語強調全球範圍。"}],"source":"62 - The Brains Business.pdf","sourcePage":8},{"front":"a growing number of","meaning":"越來越多的……","examples":[{"en":"A growing number of countries are promoting higher education as an export.","zh":"越來越多國家正在把高等教育作為出口推廣。"},{"en":"A growing number of means more and more people, places, or organisations.","zh":"growing number of 指越來越多的人、地方或組織。"},{"en":"A growing number of students use tablets to take notes in class.","zh":"越來越多學生在課堂上用平板電腦做筆記。"},{"en":"When a number grows, the trend becomes harder to ignore.","zh":"當數量增長，該趨勢就更難被忽視。"},{"en":"This phrase shows gradual increase.","zh":"這個短語顯示逐漸增加。"}],"source":"62 - The Brains Business.pdf","sourcePage":8},{"front":"turn…into an export industry","meaning":"將……變成出口產業","examples":[{"en":"Some countries are trying to turn higher education into an export industry.","zh":"有些國家正嘗試將高等教育變成出口產業。"},{"en":"To turn something into an export industry means to sell it internationally as a source of national income.","zh":"turn something into an export industry 指把某事變成可向國際出售、帶來國家收入的產業。"},{"en":"A country may turn language courses into an export industry by attracting foreign students.","zh":"國家可以透過吸引外國學生，把語言課程變成出口產業。"},{"en":"Exporting education can bring money, but it may also make universities more market-driven.","zh":"輸出教育可以帶來收入，但也可能令大學更受市場主導。"},{"en":"This phrase treats education like an international service product.","zh":"這個短語把教育視為國際服務產品。"}],"source":"62 - The Brains Business.pdf","sourcePage":8},{"front":"export industry","meaning":"出口產業","examples":[{"en":"Higher education is becoming an export industry in some countries.","zh":"在有些國家，高等教育正變成出口產業。"},{"en":"An export industry is a business sector that earns money by selling goods or services to other countries.","zh":"export industry 指透過向其他國家銷售商品或服務來賺取收入的行業。"},{"en":"Tourism can be an export industry because foreign visitors bring money into the country.","zh":"旅遊可以是出口產業，因為外國旅客把金錢帶入國家。"},{"en":"When education becomes an export industry, international students become economically important.","zh":"當教育成為出口產業，國際學生就變得具有經濟重要性。"},{"en":"This phrase connects national income with overseas customers.","zh":"這個短語把國家收入與海外顧客連繫起來。"}],"source":"62 - The Brains Business.pdf","sourcePage":8},{"front":"competition","meaning":"競爭","examples":[{"en":"The fourth factor affecting universities is competition.","zh":"影響大學的第四個因素是競爭。"},{"en":"Competition is the situation in which people or organisations try to win the same students, money, customers, or opportunities.","zh":"competition 指人或組織嘗試爭取同一批學生、金錢、顧客或機會的情況。"},{"en":"Two tutoring centres may be in competition for the same group of students.","zh":"兩間補習中心可能為同一批學生競爭。"},{"en":"Competition can improve quality, but it can also create pressure and inequality.","zh":"競爭可以改善質素，但也可以造成壓力和不平等。"},{"en":"This word describes rivalry for limited resources or attention.","zh":"這個詞描述對有限資源或注意力的爭奪。"}],"source":"62 - The Brains Business.pdf","sourcePage":9},{"front":"be forced to compete for","meaning":"被迫爭奪……","examples":[{"en":"Traditional universities are being forced to compete for students and grants.","zh":"傳統大學正被迫爭奪學生和撥款。"},{"en":"To be forced to compete for something means to have no choice but to fight for limited resources.","zh":"be forced to compete for something 指別無選擇，只能爭奪有限資源。"},{"en":"Small shops are forced to compete for customers when a large mall opens nearby.","zh":"當附近開設大型商場，小店被迫爭奪顧客。"},{"en":"Competition can push organisations to improve, but it may also make them anxious.","zh":"競爭可以推動組織改善，但也可能令它們焦慮。"},{"en":"This phrase shows pressure rather than voluntary choice.","zh":"這個短語顯示壓力，而不是自願選擇。"}],"source":"62 - The Brains Business.pdf","sourcePage":9},{"front":"research grants","meaning":"研究撥款","examples":[{"en":"Universities compete for students and research grants.","zh":"大學爭奪學生和研究撥款。"},{"en":"Research grants are funds given to support scientific or academic research projects.","zh":"research grants 指用來支持科學或學術研究項目的資金。"},{"en":"A professor may apply for a research grant to study air pollution in cities.","zh":"教授可能申請研究撥款，以研究城市空氣污染。"},{"en":"Grants allow researchers to hire staff, buy equipment, and collect data.","zh":"撥款讓研究人員聘請員工、購買設備和收集數據。"},{"en":"This phrase refers to money awarded for research.","zh":"這個短語指為研究而批出的金錢。"}],"source":"62 - The Brains Business.pdf","sourcePage":9},{"front":"break into a sector","meaning":"進軍某個行業","examples":[{"en":"Private companies are trying to break into the higher education sector.","zh":"私營公司正嘗試進軍高等教育行業。"},{"en":"To break into a sector means to enter an industry or market that is difficult to access.","zh":"break into a sector 指進入一個難以進入的行業或市場。"},{"en":"A new brand may try to break into the smartphone sector with a cheap but reliable model.","zh":"新品牌可能透過便宜但可靠的型號進軍智能手機行業。"},{"en":"Breaking into a sector often requires money, reputation, and a clear advantage.","zh":"進軍某行業通常需要資金、聲譽和明確優勢。"},{"en":"This phrase suggests a challenging entry into a field.","zh":"這個短語表示具挑戰性的進入某領域。"}],"source":"62 - The Brains Business.pdf","sourcePage":9},{"front":"regard something as","meaning":"將……視為","examples":[{"en":"Private companies regard higher education as the new healthcare.","zh":"私營公司將高等教育視為新一個醫療保健式商機。"},{"en":"To regard something as something else means to see or consider it in that way.","zh":"regard something as something else 指把某事看成或認為是另一種事物。"},{"en":"Some parents regard reading as the foundation of all learning.","zh":"有些家長將閱讀視為所有學習的基礎。"},{"en":"How people regard a sector affects how they invest in it.","zh":"人們如何看待某行業，會影響他們如何投資。"},{"en":"This phrase describes perception or judgement.","zh":"這個短語描述看法或判斷。"}],"source":"62 - The Brains Business.pdf","sourcePage":9},{"front":"the new healthcare","meaning":"新一個醫療保健式商機","examples":[{"en":"Some companies regard higher education as the new healthcare.","zh":"有些公司把高等教育視為新一個醫療保健式商機。"},{"en":"The new healthcare means a large, profitable service sector that private companies see as a major business opportunity.","zh":"new healthcare 指私營公司視為重大商業機會的大型有利可圖服務行業。"},{"en":"Investors may call elder care the new healthcare if they expect fast growth and steady demand.","zh":"如果投資者預期長者照護快速增長且需求穩定，可能稱它為新一個醫療保健式商機。"},{"en":"The phrase suggests education is being treated like a market with big profits.","zh":"這個短語暗示教育正被視為有巨大利潤的市場。"},{"en":"It compares higher education with another expensive service industry.","zh":"它把高等教育與另一個昂貴服務行業作比較。"}],"source":"62 - The Brains Business.pdf","sourcePage":9},{"front":"calculate that","meaning":"計算出；估算","examples":[{"en":"The World Bank calculates that global spending on higher education is enormous.","zh":"世界銀行估算全球高等教育開支非常龐大。"},{"en":"To calculate that means to estimate or work out a fact using numbers.","zh":"calculate that 指用數字估算或計算出某事實。"},{"en":"A shop owner calculates that weekend sales are usually twice weekday sales.","zh":"店主計算出週末銷售通常是平日的兩倍。"},{"en":"Calculations can make a claim more concrete because they provide figures.","zh":"計算可以提供數字，令說法更具體。"},{"en":"This phrase introduces a numerical estimate.","zh":"這個短語引入數字估算。"}],"source":"62 - The Brains Business.pdf","sourcePage":9},{"front":"global spending on","meaning":"全球在……方面的開支","examples":[{"en":"Global spending on higher education amounts to $300 billion a year.","zh":"全球在高等教育方面的開支每年達三千億美元。"},{"en":"Global spending on something means the total money spent on it worldwide.","zh":"global spending on something 指全球在某事上的總開支。"},{"en":"Global spending on smartphones rises when more people upgrade their devices.","zh":"當更多人升級裝置，全球在智能手機方面的開支會上升。"},{"en":"High global spending shows that a sector is economically important.","zh":"高全球開支顯示某行業在經濟上重要。"},{"en":"This phrase connects a topic with worldwide expenditure.","zh":"這個短語把某主題與全球支出連繫起來。"}],"source":"62 - The Brains Business.pdf","sourcePage":9},{"front":"amount to","meaning":"達到；總計為","examples":[{"en":"Global spending on higher education amounts to $300 billion a year.","zh":"全球高等教育開支每年總計為三千億美元。"},{"en":"To amount to a figure means to add up to that total.","zh":"amount to a figure 指加起來達到某個總數。"},{"en":"The family’s monthly transport costs amount to $500.","zh":"這個家庭每月交通費總計為 500 美元。"},{"en":"When small costs amount to a large total, people may need to review their budget.","zh":"當小開支累積成大總額，人們可能需要檢視預算。"},{"en":"This phrase is used when stating a total amount.","zh":"這個短語用於說明總數。"}],"source":"62 - The Brains Business.pdf","sourcePage":9},{"front":"global economic output","meaning":"全球經濟產出","examples":[{"en":"Higher education spending equals about 1 per cent of global economic output.","zh":"高等教育開支相當於全球經濟產出的約百分之一。"},{"en":"Global economic output means the total value of goods and services produced around the world.","zh":"global economic output 指全球所生產的商品和服務總價值。"},{"en":"A large industry affects global economic output when it creates many jobs and products.","zh":"當一個大型行業創造許多職位和產品，它會影響全球經濟產出。"},{"en":"Comparing spending with global output shows the scale of the sector.","zh":"把開支與全球產出比較，可以顯示該行業的規模。"},{"en":"This phrase refers to worldwide production value.","zh":"這個短語指全球生產價值。"}],"source":"62 - The Brains Business.pdf","sourcePage":9},{"front":"worldwide","meaning":"全球；全世界","examples":[{"en":"There are more than 80 million students worldwide.","zh":"全球有超過八千萬名學生。"},{"en":"Worldwide means across the whole world or in many countries.","zh":"worldwide 指遍及全世界或許多國家。"},{"en":"A popular app may have users worldwide if it supports many languages.","zh":"如果熱門應用程式支援多種語言，它可能有全球用戶。"},{"en":"Worldwide growth can create both opportunities and competition.","zh":"全球增長可以創造機會，也可以帶來競爭。"},{"en":"This word emphasises global scale.","zh":"這個詞強調全球規模。"}],"source":"62 - The Brains Business.pdf","sourcePage":10},{"front":"be employed to","meaning":"受僱去","examples":[{"en":"Millions of people are employed to teach or support students.","zh":"數百萬人受僱去教導或支援學生。"},{"en":"To be employed to do something means to be paid to do that job.","zh":"be employed to do something 指受薪去做某項工作。"},{"en":"A school nurse is employed to care for students’ health during the day.","zh":"學校護士受僱在日間照顧學生健康。"},{"en":"Employment shows that a service requires organised labour and funding.","zh":"就業顯示一項服務需要有組織的勞力和資金。"},{"en":"This phrase identifies the purpose of a person’s job.","zh":"這個短語指出某人工作的目的。"}],"source":"62 - The Brains Business.pdf","sourcePage":10},{"front":"look after","meaning":"照顧；照料","examples":[{"en":"Millions of people are employed to teach students or look after them.","zh":"數百萬人受僱去教導學生或照顧他們。"},{"en":"To look after someone means to care for them and make sure they are safe or supported.","zh":"look after someone 指照顧某人，確保他們安全或得到支援。"},{"en":"Parents look after young children by feeding them and keeping them safe.","zh":"父母透過餵食和保護安全來照顧幼兒。"},{"en":"If universities look after students well, students may learn more confidently.","zh":"如果大學妥善照顧學生，學生可能更有信心地學習。"},{"en":"This phrase is common in everyday English for care and support.","zh":"這個短語在日常英語中常用於照顧和支援。"}],"source":"62 - The Brains Business.pdf","sourcePage":10},{"front":"sound as though","meaning":"聽起來好像","examples":[{"en":"All this sounds as though a golden age has arrived.","zh":"這一切聽起來好像黃金時代已經來臨。"},{"en":"Sound as though means give the impression that something is true.","zh":"sound as though 指給人一種某事為真的印象。"},{"en":"The advertisement sounds as though the course guarantees success, but students still need practice.","zh":"廣告聽起來好像課程保證成功，但學生仍需要練習。"},{"en":"Something may sound positive even when the reality is more complicated.","zh":"某事可能聽起來正面，但現實更複雜。"},{"en":"This phrase introduces an impression, not necessarily a fact.","zh":"這個短語引入印象，而不一定是事實。"}],"source":"62 - The Brains Business.pdf","sourcePage":10},{"front":"a golden age","meaning":"黃金時代","examples":[{"en":"It may sound as though a golden age for universities has arrived.","zh":"聽起來好像大學的黃金時代已經來臨。"},{"en":"A golden age is a period of great success, growth, wealth, or achievement.","zh":"golden age 指成功、增長、財富或成就特別大的時期。"},{"en":"A city may enjoy a golden age when jobs, culture, and transport all improve.","zh":"當職位、文化和交通都改善，城市可能享有黃金時代。"},{"en":"People call a period a golden age when conditions seem especially favourable.","zh":"當條件似乎特別有利，人們會稱某段時期為黃金時代。"},{"en":"This phrase is positive and often slightly idealised.","zh":"這個短語帶正面意思，而且常有一點理想化。"}],"source":"62 - The Brains Business.pdf","sourcePage":10},{"front":"has arrived","meaning":"已經來臨","examples":[{"en":"A golden age for universities seems to have arrived.","zh":"大學的黃金時代似乎已經來臨。"},{"en":"Has arrived means has begun or has come into existence.","zh":"has arrived 指已經開始或已經出現。"},{"en":"When many students use tablets daily, a new style of learning may seem to have arrived.","zh":"當許多學生每天使用平板電腦，新的學習方式可能似乎已經來臨。"},{"en":"This phrase suggests that a new period or situation is now present.","zh":"這個短語表示新的時期或情況現在已存在。"},{"en":"It is often used for trends, eras, or important changes.","zh":"它常用於趨勢、時代或重要變化。"}],"source":"62 - The Brains Business.pdf","sourcePage":10},{"front":"inside academia","meaning":"在學術界內部","examples":[{"en":"Inside academia, the situation does not feel like a golden age.","zh":"在學術界內部，情況並不像黃金時代。"},{"en":"Inside academia means among people who work or study in universities and research institutions.","zh":"inside academia 指在大學和研究機構工作或學習的人之中。"},{"en":"Inside academia, publishing papers and winning grants can create strong pressure.","zh":"在學術界內部，發表論文和取得撥款可以造成很大壓力。"},{"en":"People outside universities may see prestige, while those inside academia feel workload and funding stress.","zh":"大學外的人可能看見聲望，而學術界內部的人感受到工作量和資金壓力。"},{"en":"This phrase gives the viewpoint of the academic world.","zh":"這個短語給出學術世界的觀點。"}],"source":"62 - The Brains Business.pdf","sourcePage":10},{"front":"particularly in Europe","meaning":"尤其在歐洲","examples":[{"en":"Academics are especially unhappy in Europe.","zh":"學者尤其在歐洲感到不滿。"},{"en":"Particularly in Europe means especially in European countries, more than in some other places.","zh":"particularly in Europe 指尤其在歐洲國家，比某些其他地方更明顯。"},{"en":"Public transport strikes may be disruptive, particularly in cities where few people drive.","zh":"公共交通罷工可能造成混亂，尤其在少人駕車的城市。"},{"en":"This phrase narrows a general statement to a place where it is especially true.","zh":"這個短語把一般陳述收窄到特別成立的地方。"},{"en":"It helps show where a problem is strongest.","zh":"它幫助顯示問題在哪裡最強烈。"}],"source":"62 - The Brains Business.pdf","sourcePage":10},{"front":"academics","meaning":"學者；大學教師","examples":[{"en":"Academics complain about the current state of universities.","zh":"學者抱怨大學目前的狀況。"},{"en":"Academics are people who teach, research, or write in universities or scholarly fields.","zh":"academics 指在大學或學術領域教學、研究或寫作的人。"},{"en":"Academics may spend years studying one question before publishing their findings.","zh":"學者可能花多年研究一個問題，然後才發表發現。"},{"en":"Their working conditions affect teaching quality and research output.","zh":"他們的工作條件會影響教學質素和研究成果。"},{"en":"This word usually refers to university teachers and researchers.","zh":"這個詞通常指大學教師和研究人員。"}],"source":"62 - The Brains Business.pdf","sourcePage":10},{"front":"administrators","meaning":"行政管理人員","examples":[{"en":"Administrators are in conflict with the politicians who fund universities.","zh":"行政管理人員與資助大學的政治人物發生衝突。"},{"en":"Administrators are people who manage organisations, budgets, rules, and daily operations.","zh":"administrators 指管理組織、預算、規則和日常運作的人。"},{"en":"University administrators may organise admissions, finance, housing, and student services.","zh":"大學行政管理人員可能安排收生、財務、住宿和學生服務。"},{"en":"Good administration helps teachers teach and students receive support.","zh":"良好行政管理幫助老師教學，並讓學生獲得支援。"},{"en":"This word refers to management staff, not necessarily teachers.","zh":"這個詞指管理人員，不一定是老師。"}],"source":"62 - The Brains Business.pdf","sourcePage":10},{"front":"be locked in exchanges with","meaning":"與……陷入爭論","examples":[{"en":"Administrators are locked in bad-tempered exchanges with politicians.","zh":"行政管理人員與政治人物陷入火藥味濃的爭論。"},{"en":"To be locked in exchanges with someone means to be stuck in repeated arguments or discussions with them.","zh":"be locked in exchanges with someone 指與某人陷入反覆爭論或討論。"},{"en":"Parents and a school may be locked in exchanges over a new uniform policy.","zh":"家長和學校可能因新校服政策陷入爭論。"},{"en":"When both sides keep arguing, decisions can become slower and trust can fall.","zh":"當雙方持續爭論，決策可能變慢，信任也可能下降。"},{"en":"This phrase suggests an ongoing conflict that is hard to end.","zh":"這個短語表示難以結束的持續衝突。"}],"source":"62 - The Brains Business.pdf","sourcePage":11},{"front":"bad-tempered exchanges","meaning":"火藥味濃的爭論","examples":[{"en":"Administrators are locked in bad-tempered exchanges with government funders.","zh":"行政管理人員與政府資助者陷入火藥味濃的爭論。"},{"en":"Bad-tempered exchanges are angry or unfriendly discussions between people.","zh":"bad-tempered exchanges 指人們之間憤怒或不友善的討論。"},{"en":"A meeting can turn into bad-tempered exchanges if parents feel ignored by the school.","zh":"如果家長覺得被學校忽視，會議可能變成火藥味濃的爭論。"},{"en":"Angry exchanges can make it harder to solve the original problem.","zh":"憤怒爭論會令原本問題更難解決。"},{"en":"This phrase describes a discussion with hostility.","zh":"這個短語描述帶有敵意的討論。"}],"source":"62 - The Brains Business.pdf","sourcePage":11},{"front":"politicians who fund them","meaning":"資助他們的政治人物","examples":[{"en":"Administrators argue with the politicians who fund universities.","zh":"行政管理人員與資助大學的政治人物爭論。"},{"en":"Politicians who fund them are government figures who decide or influence the money universities receive.","zh":"politicians who fund them 指決定或影響大學所得資金的政府人物。"},{"en":"A school may depend on officials who fund building repairs and extra teachers.","zh":"學校可能依賴資助校舍維修和額外老師的官員。"},{"en":"Funders can influence institutions because money affects what they can do.","zh":"資助者可以影響機構，因為金錢影響它們能做甚麼。"},{"en":"This phrase identifies the political source of financial support.","zh":"這個短語指出財政支援的政治來源。"}],"source":"62 - The Brains Business.pdf","sourcePage":11},{"front":"what has gone wrong","meaning":"出了甚麼問題","examples":[{"en":"The passage asks what has gone wrong inside academia.","zh":"文章問學術界內部出了甚麼問題。"},{"en":"What has gone wrong means what problem has caused a situation to become bad.","zh":"what has gone wrong 指有甚麼問題令情況變壞。"},{"en":"If exam results suddenly fall, teachers may ask what has gone wrong.","zh":"如果考試成績突然下降，老師可能問出了甚麼問題。"},{"en":"Asking this question helps people look for causes rather than only blaming outcomes.","zh":"提出這個問題幫助人尋找原因，而不只是責怪結果。"},{"en":"This phrase introduces problem diagnosis.","zh":"這個短語引入問題診斷。"}],"source":"62 - The Brains Business.pdf","sourcePage":11},{"front":"the role of the state","meaning":"國家的角色","examples":[{"en":"The biggest problem is the role of the state.","zh":"最大問題是國家的角色。"},{"en":"The role of the state means what the government does or should do in a system.","zh":"role of the state 指政府在一個制度中做甚麼或應該做甚麼。"},{"en":"In healthcare, the role of the state may include funding hospitals and regulating safety.","zh":"在醫療中，國家的角色可能包括資助醫院和監管安全。"},{"en":"If the state expands access without funding it, public services may suffer.","zh":"如果國家擴大使用機會但不提供資金，公共服務可能受損。"},{"en":"This phrase focuses on government responsibility.","zh":"這個短語著重政府責任。"}],"source":"62 - The Brains Business.pdf","sourcePage":11},{"front":"embrace massification","meaning":"接受高等教育大眾化","examples":[{"en":"Many governments are embracing massification.","zh":"許多政府正在接受高等教育大眾化。"},{"en":"To embrace massification means to accept or support the expansion of higher education to many more people.","zh":"embrace massification 指接受或支持高等教育擴展至更多人。"},{"en":"A government embraces mass education when it builds more schools and funds more places.","zh":"當政府興建更多學校並資助更多學位，它就是接受大眾教育。"},{"en":"Supporting wider access requires planning, staff, and money.","zh":"支持更廣泛入學需要規劃、員工和金錢。"},{"en":"This phrase suggests approval of broad educational expansion.","zh":"這個短語表示贊成廣泛教育擴展。"}],"source":"62 - The Brains Business.pdf","sourcePage":11},{"front":"be willing to","meaning":"願意","examples":[{"en":"Few governments are willing to fund massification properly.","zh":"很少政府願意妥善資助高等教育大眾化。"},{"en":"To be willing to do something means to be ready or prepared to do it.","zh":"be willing to do something 指準備好或願意做某事。"},{"en":"A student is willing to improve when they accept feedback and practise regularly.","zh":"當學生接受回饋並定期練習，他就是願意進步。"},{"en":"If governments are not willing to pay, expansion may damage quality.","zh":"如果政府不願意付費，擴展可能損害質素。"},{"en":"This phrase shows readiness, not ability alone.","zh":"這個短語顯示意願，而不只是能力。"}],"source":"62 - The Brains Business.pdf","sourcePage":11},{"front":"draw the appropriate conclusion","meaning":"得出恰當結論","examples":[{"en":"Governments are unwilling to draw the appropriate conclusion from massification.","zh":"政府不願意從高等教育大眾化中得出恰當結論。"},{"en":"To draw the appropriate conclusion means to reach the sensible judgement that follows from the evidence.","zh":"draw the appropriate conclusion 指根據證據作出合理判斷。"},{"en":"If a class is overcrowded, the appropriate conclusion may be that more teachers are needed.","zh":"如果班級太擠迫，恰當結論可能是需要更多老師。"},{"en":"Ignoring the obvious conclusion can make a problem worse.","zh":"忽視明顯結論可以令問題惡化。"},{"en":"This phrase links evidence with the decision it should lead to.","zh":"這個短語把證據與應得出的決定連繫起來。"}],"source":"62 - The Brains Business.pdf","sourcePage":11},{"front":"the requisite funds","meaning":"所需資金","examples":[{"en":"Governments should provide the requisite funds for expanding higher education.","zh":"政府應為擴展高等教育提供所需資金。"},{"en":"The requisite funds are the necessary amount of money needed for a purpose.","zh":"requisite funds 指達成某目的所需的必要金額。"},{"en":"A school cannot build a new library without the requisite funds.","zh":"學校沒有所需資金就不能興建新圖書館。"},{"en":"If funds are insufficient, expansion may lower quality instead of improving access.","zh":"如果資金不足，擴展可能降低質素，而不是改善入學機會。"},{"en":"This phrase is formal and means “the needed money”.","zh":"這個短語較正式，意思是「需要的錢」。"}],"source":"62 - The Brains Business.pdf","sourcePage":11},{"front":"charge realistic fees","meaning":"收取符合實際成本的學費","examples":[{"en":"Governments could allow universities to charge realistic fees.","zh":"政府可以容許大學收取符合實際成本的學費。"},{"en":"To charge realistic fees means to ask for payments that reflect the real cost of providing a service.","zh":"charge realistic fees 指收取能反映提供服務真實成本的費用。"},{"en":"A music teacher charges realistic fees when the price covers preparation, teaching time, and room rental.","zh":"音樂老師的收費涵蓋備課、教學時間和場地租金時，就是收取符合實際成本的費用。"},{"en":"Realistic fees can improve funding, but they may make access harder for poorer students.","zh":"符合實際成本的費用可以改善資金，但可能令較貧困學生較難入讀。"},{"en":"This phrase connects pricing with actual cost.","zh":"這個短語把定價與實際成本連繫起來。"}],"source":"62 - The Brains Business.pdf","sourcePage":11},{"front":"square the circle","meaning":"試圖化解難以兼顧的矛盾","examples":[{"en":"Many governments have tried to square the circle through tighter management.","zh":"許多政府嘗試透過更嚴格管理，化解難以兼顧的矛盾。"},{"en":"To square the circle means to try to solve a problem with goals that seem impossible to satisfy together.","zh":"square the circle 指嘗試解決看似無法同時滿足多個目標的問題。"},{"en":"A school tries to square the circle when it wants smaller classes without hiring more teachers.","zh":"學校既想縮小班級又不聘請更多老師，就是嘗試化解難以兼顧的矛盾。"},{"en":"Such attempts often fail because the demands conflict with one another.","zh":"這類嘗試常會失敗，因為要求彼此衝突。"},{"en":"This phrase describes trying to make an impossible compromise work.","zh":"這個短語描述試圖讓不可能的折衷方案奏效。"}],"source":"62 - The Brains Business.pdf","sourcePage":12},{"front":"tighter management","meaning":"更嚴格的管理","examples":[{"en":"Governments have tried to solve funding problems through tighter management.","zh":"政府嘗試透過更嚴格的管理解決資金問題。"},{"en":"Tighter management means stricter control of budgets, staff, rules, or performance.","zh":"tighter management 指對預算、員工、規則或表現作更嚴格控制。"},{"en":"A company may introduce tighter management after repeated delays and overspending.","zh":"公司在反覆延誤和超支後，可能引入更嚴格管理。"},{"en":"Better management can reduce waste, but it cannot replace missing resources entirely.","zh":"更好管理可以減少浪費，但不能完全取代缺失資源。"},{"en":"This phrase describes more control and supervision.","zh":"這個短語描述更多控制和監督。"}],"source":"62 - The Brains Business.pdf","sourcePage":12},{"front":"make up for","meaning":"彌補","examples":[{"en":"Management cannot make up for a lack of resources.","zh":"管理不能彌補資源不足。"},{"en":"To make up for something means to compensate for a problem, loss, or weakness.","zh":"make up for something 指補償某個問題、損失或弱點。"},{"en":"Extra practice can make up for a missed lesson if the student catches up quickly.","zh":"如果學生很快追回進度，額外練習可以彌補缺席一堂課。"},{"en":"Some problems are too large for small improvements to make up for them.","zh":"有些問題太大，小改善無法彌補。"},{"en":"This phrase shows compensation, not complete prevention.","zh":"這個短語表示補償，而不是完全預防。"}],"source":"62 - The Brains Business.pdf","sourcePage":12},{"front":"lack of resources","meaning":"資源不足","examples":[{"en":"Universities suffer from a lack of resources.","zh":"大學受資源不足困擾。"},{"en":"Lack of resources means not having enough money, staff, space, equipment, or time.","zh":"lack of resources 指沒有足夠金錢、員工、空間、設備或時間。"},{"en":"A school with a lack of resources may have old computers and overcrowded classrooms.","zh":"資源不足的學校可能有舊電腦和擠迫課室。"},{"en":"Resource shortages can reduce quality even when teachers work hard.","zh":"即使老師努力工作，資源短缺也可能降低質素。"},{"en":"This phrase describes shortage of what is needed.","zh":"這個短語描述所需事物不足。"}],"source":"62 - The Brains Business.pdf","sourcePage":12},{"front":"in all too many parts of","meaning":"在太多……地方","examples":[{"en":"Problems are appearing in all too many parts of the academic world.","zh":"問題正在學術界太多地方出現。"},{"en":"In all too many parts of means in far more areas than is acceptable or comfortable.","zh":"in all too many parts of 指在遠多於可接受或令人安心的範圍中。"},{"en":"In all too many parts of the city, families struggle to afford rent.","zh":"在城市太多地方，家庭難以負擔租金。"},{"en":"This phrase suggests worry because a problem is widespread.","zh":"這個短語表示擔憂，因為問題廣泛存在。"},{"en":"It is stronger than simply saying “in many parts of”.","zh":"它比簡單說 in many parts of 語氣更強。"}],"source":"62 - The Brains Business.pdf","sourcePage":12},{"front":"the academic world","meaning":"學術界","examples":[{"en":"The academic world is facing pressure from massification.","zh":"學術界正面對高等教育大眾化帶來的壓力。"},{"en":"The academic world means the community of universities, researchers, teachers, and scholarly institutions.","zh":"academic world 指由大學、研究人員、教師和學術機構組成的群體。"},{"en":"The academic world values research, teaching, publication, and debate.","zh":"學術界重視研究、教學、發表和辯論。"},{"en":"When funding changes, the academic world may change how it teaches and researches.","zh":"當資金改變，學術界可能改變其教學和研究方式。"},{"en":"This phrase refers to higher education and scholarship as a whole.","zh":"這個短語指整個高等教育和學術領域。"}],"source":"62 - The Brains Business.pdf","sourcePage":12},{"front":"famous dictum","meaning":"著名格言","examples":[{"en":"Kingsley Amis’s famous dictum is coming to pass.","zh":"Kingsley Amis 的著名格言正成為現實。"},{"en":"A famous dictum is a well-known saying that expresses a strong opinion or rule.","zh":"famous dictum 指表達強烈觀點或原則的著名說法。"},{"en":"“Practice makes perfect” is a familiar dictum often used in education.","zh":"“Practice makes perfect” 是教育中常用的熟悉格言。"},{"en":"Dictums are memorable because they reduce a complex idea to a short statement.","zh":"格言令人容易記住，因為它把複雜想法縮短成一句話。"},{"en":"This phrase refers to a recognised saying, not a detailed argument.","zh":"這個短語指受認可的說法，而不是詳細論證。"}],"source":"62 - The Brains Business.pdf","sourcePage":12},{"front":"more means worse","meaning":"更多即更差","examples":[{"en":"The dictum says that more means worse.","zh":"這句格言說，更多即更差。"},{"en":"More means worse means increasing quantity can reduce quality.","zh":"more means worse 指數量增加可能令質素下降。"},{"en":"A restaurant may find that more customers mean worse service if it does not hire more staff.","zh":"如果餐廳沒有聘請更多員工，更多顧客可能意味着更差服務。"},{"en":"Growth without enough resources can turn success into decline.","zh":"沒有足夠資源的增長，可以把成功變成衰退。"},{"en":"This phrase warns that expansion is not always improvement.","zh":"這個短語提醒擴張不一定是改善。"}],"source":"62 - The Brains Business.pdf","sourcePage":12},{"front":"come to pass","meaning":"成為現實","examples":[{"en":"The warning that more means worse is coming to pass.","zh":"「更多即更差」這個警告正在成為現實。"},{"en":"To come to pass means to happen or become reality.","zh":"come to pass 指發生或成為現實。"},{"en":"A teacher’s warning about poor attendance may come to pass when students fail the exam.","zh":"老師關於出席率差的警告，可能在學生考試不合格時成為現實。"},{"en":"Predictions come to pass when later events prove them true.","zh":"當後來事件證明預測為真，預測就成為現實。"},{"en":"This phrase is slightly formal and often used for warnings or prophecies.","zh":"這個短語稍正式，常用於警告或預言。"}],"source":"62 - The Brains Business.pdf","sourcePage":12},{"front":"academic salaries","meaning":"大學教職員薪酬","examples":[{"en":"Academic salaries are declining compared with similar jobs.","zh":"大學教職員薪酬與類似工作相比正在下降。"},{"en":"Academic salaries are the pay received by university teachers, researchers, or academic staff.","zh":"academic salaries 指大學教師、研究人員或學術人員所得薪酬。"},{"en":"Low academic salaries may push talented researchers into private companies.","zh":"大學薪酬偏低可能令有才華研究人員轉投私營公司。"},{"en":"If salaries fall behind other jobs, universities may struggle to attract staff.","zh":"如果薪酬落後於其他工作，大學可能難以吸引員工。"},{"en":"This phrase refers to pay in the academic profession.","zh":"這個短語指學術專業中的薪酬。"}],"source":"62 - The Brains Business.pdf","sourcePage":12},{"front":"measured against","meaning":"與……相比","examples":[{"en":"Academic salaries are declining when measured against similar jobs elsewhere.","zh":"大學教職員薪酬與其他地方的類似工作相比正在下降。"},{"en":"Measured against something means compared with it as a standard.","zh":"measured against something 指以某物作標準來比較。"},{"en":"A student’s progress may look strong when measured against their own starting point.","zh":"如果與學生自己的起點相比，他的進步可能看起來很大。"},{"en":"Comparisons depend on what standard is used.","zh":"比較取決於使用甚麼標準。"},{"en":"This phrase introduces a benchmark for judgement.","zh":"這個短語引入判斷基準。"}],"source":"62 - The Brains Business.pdf","sourcePage":13},{"front":"similar jobs elsewhere","meaning":"其他地方的類似工作","examples":[{"en":"Academic salaries are lower than salaries in similar jobs elsewhere.","zh":"大學教職員薪酬低於其他地方的類似工作薪酬。"},{"en":"Similar jobs elsewhere are comparable positions in other organisations, sectors, or places.","zh":"similar jobs elsewhere 指其他組織、行業或地方中可比較的職位。"},{"en":"A teacher may compare their pay with similar jobs elsewhere, such as training roles in companies.","zh":"老師可能把自己的薪酬與其他地方的類似工作比較，例如公司的培訓職位。"},{"en":"If similar jobs elsewhere pay more, staff may leave.","zh":"如果其他地方的類似工作薪酬更高，員工可能離開。"},{"en":"This phrase helps compare pay or conditions across different workplaces.","zh":"這個短語幫助比較不同工作場所的薪酬或條件。"}],"source":"62 - The Brains Business.pdf","sourcePage":13},{"front":"deteriorate","meaning":"日漸惡化","examples":[{"en":"Buildings and libraries are deteriorating.","zh":"建築物和圖書館正在日漸惡化。"},{"en":"To deteriorate means to become worse in condition or quality over time.","zh":"deteriorate 指狀況或質素隨時間變差。"},{"en":"A classroom will deteriorate if leaks, broken lights, and old furniture are ignored.","zh":"如果漏水、壞燈和舊家具被忽視，課室會日漸惡化。"},{"en":"When facilities deteriorate, students and staff may find it harder to work well.","zh":"當設施惡化，學生和員工可能更難好好工作。"},{"en":"This word describes gradual decline.","zh":"這個詞描述逐漸衰退。"}],"source":"62 - The Brains Business.pdf","sourcePage":13},{"front":"mega-institutions","meaning":"巨型院校","examples":[{"en":"Mega-institutions may struggle to give students individual attention.","zh":"巨型院校可能難以給學生個別關注。"},{"en":"Mega-institutions are extremely large organisations with many people, departments, and procedures.","zh":"mega-institutions 指規模極大的組織，擁有很多人、部門和程序。"},{"en":"A huge hospital network can become a mega-institution that feels impersonal to patients.","zh":"大型醫院網絡可以成為巨型機構，令病人感到不夠人性化。"},{"en":"Large size can bring resources, but it can also reduce personal contact.","zh":"大規模可以帶來資源，但也可以減少個人接觸。"},{"en":"This phrase suggests an institution so large that it becomes hard to manage closely.","zh":"這個短語表示機構大到難以細緻管理。"}],"source":"62 - The Brains Business.pdf","sourcePage":13},{"front":"individual attention to students","meaning":"對學生的個別關注","examples":[{"en":"Individual attention to students is harder in very large universities.","zh":"在非常大型的大學中，對學生的個別關注更難做到。"},{"en":"Individual attention to students means personal support, feedback, and care given to each student.","zh":"individual attention to students 指給每位學生的個人支援、回饋和關懷。"},{"en":"A teacher gives individual attention when they explain a mistake to one student after class.","zh":"老師課後向一名學生解釋錯誤時，就是給予個別關注。"},{"en":"Without individual attention, weaker students may fall behind quietly.","zh":"沒有個別關注，較弱學生可能默默落後。"},{"en":"This phrase focuses on personalised teaching and support.","zh":"這個短語著重個人化教學和支援。"}],"source":"62 - The Brains Business.pdf","sourcePage":13},{"front":"be bound to","meaning":"必然會","examples":[{"en":"In huge institutions, individual attention is bound to take a back seat.","zh":"在巨型機構中，個別關注必然會退居次要位置。"},{"en":"Be bound to means be very likely or almost certain to happen.","zh":"be bound to 指非常可能或幾乎必然會發生。"},{"en":"If a student never sleeps before exams, tiredness is bound to affect performance.","zh":"如果學生考試前從不睡覺，疲倦必然會影響表現。"},{"en":"This phrase expresses a strong expectation based on the situation.","zh":"這個短語根據情況表達強烈預期。"},{"en":"It is stronger than simply saying “may”.","zh":"它比簡單說 may 語氣更強。"}],"source":"62 - The Brains Business.pdf","sourcePage":13},{"front":"take a back seat","meaning":"退居次要位置","examples":[{"en":"Individual attention to students is bound to take a back seat.","zh":"對學生的個別關注必然會退居次要位置。"},{"en":"To take a back seat means to become less important than other priorities.","zh":"take a back seat 指變得不如其他優先事項重要。"},{"en":"During exam season, hobbies may take a back seat to revision.","zh":"考試季節期間，嗜好可能退居次要位置，讓位給溫習。"},{"en":"When budgets are tight, personal support may take a back seat to basic operations.","zh":"當預算緊張，個人支援可能退居次要位置，讓位給基本運作。"},{"en":"This phrase describes something being pushed into a secondary position.","zh":"這個短語描述某事被推到較次要位置。"}],"source":"62 - The Brains Business.pdf","sourcePage":13},{"front":"innate conservatism","meaning":"內在保守性","examples":[{"en":"The innate conservatism of the academic profession does not help.","zh":"學術專業界別的內在保守性並沒有幫助。"},{"en":"Innate conservatism is a natural tendency to prefer old ways and resist change.","zh":"innate conservatism 指自然傾向偏好舊方式並抗拒改變。"},{"en":"A family business may show innate conservatism if it refuses to use online payment.","zh":"如果家族企業拒絕使用網上付款，就可能顯示內在保守性。"},{"en":"Conservatism can protect standards, but it can also delay necessary reform.","zh":"保守性可以保護標準，但也可能延遲必要改革。"},{"en":"This phrase describes a built-in resistance to change.","zh":"這個短語描述內建的抗拒改變傾向。"}],"source":"62 - The Brains Business.pdf","sourcePage":13},{"front":"the academic profession","meaning":"學術專業界別","examples":[{"en":"The academic profession can be slow to adapt.","zh":"學術專業界別可能適應得很慢。"},{"en":"The academic profession means the community of people whose work is university teaching and research.","zh":"academic profession 指以大學教學和研究為工作的群體。"},{"en":"Academic professionals include lecturers, professors, researchers, and scholars.","zh":"學術專業人士包括講師、教授、研究人員和學者。"},{"en":"Their values shape how universities teach, publish, and judge knowledge.","zh":"他們的價值觀塑造大學如何教學、發表和判斷知識。"},{"en":"This phrase refers to academia as a career field.","zh":"這個短語指作為職業領域的學術界。"}],"source":"62 - The Brains Business.pdf","sourcePage":13},{"front":"be born in a very different world","meaning":"誕生於一個截然不同的世界","examples":[{"en":"The modern university was born in a very different world.","zh":"現代大學誕生於一個截然不同的世界。"},{"en":"To be born in a very different world means to have begun in conditions unlike today’s society.","zh":"be born in a very different world 指在與今日社會不同的條件下開始。"},{"en":"Many old school rules were born in a very different world before smartphones existed.","zh":"許多舊校規誕生於智能手機出現前一個截然不同的世界。"},{"en":"Institutions created for one era may struggle when the world changes around them.","zh":"為某個時代而創立的機構，在世界改變時可能難以適應。"},{"en":"This phrase connects an institution’s origin with historical context.","zh":"這個短語把機構起源與歷史語境連繫起來。"}],"source":"62 - The Brains Business.pdf","sourcePage":13},{"front":"the current one","meaning":"現今這個世界","examples":[{"en":"The old university system was created in a world different from the current one.","zh":"舊大學制度創立於一個與現今這個世界不同的世界。"},{"en":"The current one means the present world, system, situation, or version already being discussed.","zh":"current one 指正在討論的現在世界、制度、情況或版本。"},{"en":"Old teaching methods may not fit the current one because students now use digital tools.","zh":"舊教學方法可能不適合現今這個世界，因為學生現在使用數碼工具。"},{"en":"Comparing the past with the current one helps explain why reform is needed.","zh":"把過去與現今比較，有助解釋為何需要改革。"},{"en":"This phrase avoids repeating the full noun.","zh":"這個短語避免重複完整名詞。"}],"source":"62 - The Brains Business.pdf","sourcePage":14},{"front":"a tiny minority of","meaning":"極少數的……","examples":[{"en":"Only a tiny minority of the population once entered higher education.","zh":"曾經只有極少數人口進入高等教育。"},{"en":"A tiny minority of something means a very small part of the whole group.","zh":"tiny minority of something 指整體中非常小的一部分。"},{"en":"A tiny minority of students may choose ancient Greek as an elective.","zh":"可能只有極少數學生選修古希臘語。"},{"en":"If only a tiny minority has access, a system is selective rather than mass-based.","zh":"如果只有極少數人能使用某制度，它就是精英式而非大眾式。"},{"en":"This phrase highlights how small a group is.","zh":"這個短語突出一個群體有多小。"}],"source":"62 - The Brains Business.pdf","sourcePage":14},{"front":"enter higher education","meaning":"進入高等教育","examples":[{"en":"A tiny minority of the population used to enter higher education.","zh":"過去只有極少數人口進入高等教育。"},{"en":"To enter higher education means to begin studying at a university, college, or similar institution.","zh":"enter higher education 指開始在大學、學院或類似機構學習。"},{"en":"A student may enter higher education after finishing secondary school exams.","zh":"學生完成中學考試後，可能進入高等教育。"},{"en":"More people entering higher education can increase skills across society.","zh":"更多人進入高等教育可以提高整個社會的技能。"},{"en":"This phrase refers to starting post-secondary study.","zh":"這個短語指開始中學後教育。"}],"source":"62 - The Brains Business.pdf","sourcePage":14},{"front":"be reluctant to","meaning":"不願意","examples":[{"en":"Many academics have been reluctant to adapt to massification.","zh":"許多學者一直不願意適應高等教育大眾化。"},{"en":"To be reluctant to do something means to be unwilling or hesitant to do it.","zh":"be reluctant to do something 指不願意或猶豫去做某事。"},{"en":"A student may be reluctant to speak English because they fear making mistakes.","zh":"學生可能因害怕犯錯而不願意說英文。"},{"en":"Reluctance can slow change even when change is necessary.","zh":"不情願可以拖慢改變，即使改變是必要的。"},{"en":"This phrase shows hesitation, not complete refusal every time.","zh":"這個短語顯示猶豫，而不一定每次都完全拒絕。"}],"source":"62 - The Brains Business.pdf","sourcePage":14},{"front":"make allowances for","meaning":"顧及；適應","examples":[{"en":"Many academics have been reluctant to make allowances for massification.","zh":"許多學者一直不願意顧及高等教育大眾化。"},{"en":"To make allowances for something means to adjust expectations or plans because of it.","zh":"make allowances for something 指因某事而調整期望或計劃。"},{"en":"A teacher may make allowances for a student who has been ill by extending a deadline.","zh":"老師可能因學生生病而延長限期，作出顧及。"},{"en":"If universities expand rapidly, staff may need to adjust teaching methods.","zh":"如果大學迅速擴展，員工可能需要調整教學方法。"},{"en":"This phrase means to take a factor into account fairly.","zh":"這個短語意思是公平地考慮某因素。"}],"source":"62 - The Brains Business.pdf","sourcePage":14},{"front":"insist that","meaning":"堅持要求","examples":[{"en":"Italian universities still insist that all students undergo an oral examination.","zh":"意大利大學仍堅持要求所有學生接受口試。"},{"en":"To insist that something happen means to demand it firmly.","zh":"insist that something happen 指堅定要求某事發生。"},{"en":"A teacher may insist that students show their working in maths answers.","zh":"老師可能堅持要求學生在數學答案中展示計算過程。"},{"en":"Insisting on a rule can protect standards, but it may also create pressure.","zh":"堅持規則可以保護標準，但也可能造成壓力。"},{"en":"This phrase shows a strong requirement.","zh":"這個短語顯示強烈要求。"}],"source":"62 - The Brains Business.pdf","sourcePage":14},{"front":"undergo an examination","meaning":"接受考試","examples":[{"en":"Italian students must undergo a viva voce examination.","zh":"意大利學生必須接受口試。"},{"en":"To undergo an examination means to go through or take a formal test.","zh":"undergo an examination 指經歷或參加正式測驗。"},{"en":"A patient may undergo a medical examination before surgery.","zh":"病人在手術前可能接受醫學檢查。"},{"en":"Examinations can be stressful because performance is being judged.","zh":"考試可能令人有壓力，因為表現正在被評核。"},{"en":"This phrase is more formal than “take an exam”.","zh":"這個短語比 take an exam 更正式。"}],"source":"62 - The Brains Business.pdf","sourcePage":14},{"front":"viva voce examination","meaning":"口試","examples":[{"en":"Italian universities require students to undergo a viva voce examination.","zh":"意大利大學要求學生接受口試。"},{"en":"A viva voce examination is an oral examination in which students answer questions aloud.","zh":"viva voce examination 指學生口頭回答問題的考試。"},{"en":"A student may defend a project in a viva voce examination before professors.","zh":"學生可能在教授面前透過口試為項目答辯。"},{"en":"Oral exams test whether students can explain ideas clearly without written notes.","zh":"口試測試學生能否不用書面筆記清楚解釋想法。"},{"en":"This phrase is often shortened to “viva”.","zh":"這個短語常被簡稱為 viva。"}],"source":"62 - The Brains Business.pdf","sourcePage":14},{"front":"full professor","meaning":"正教授","examples":[{"en":"The examination is conducted by a full professor.","zh":"該考試由正教授主持。"},{"en":"A full professor is a senior academic with the highest ordinary university rank.","zh":"full professor 指擁有最高一般大學職級的資深學者。"},{"en":"A full professor may lead a research group and supervise doctoral students.","zh":"正教授可能帶領研究小組並指導博士生。"},{"en":"Having a full professor conduct an exam may show tradition and academic authority.","zh":"由正教授主持考試可能顯示傳統和學術權威。"},{"en":"This phrase refers to academic rank, not simply a teacher who works full-time.","zh":"這個短語指學術職級，而不只是全職工作的老師。"}],"source":"62 - The Brains Business.pdf","sourcePage":14},{"front":"lasting an average of","meaning":"平均持續","examples":[{"en":"The examination lasts an average of about five minutes.","zh":"該考試平均持續約五分鐘。"},{"en":"Lasting an average of means continuing for about that length of time on average.","zh":"lasting an average of 指平均持續約某段時間。"},{"en":"A bus journey may last an average of thirty minutes on weekdays.","zh":"平日巴士車程可能平均持續三十分鐘。"},{"en":"Averages describe typical duration, but individual cases may be longer or shorter.","zh":"平均數描述典型時間，但個別情況可能較長或較短。"},{"en":"This phrase is used when giving a general time measurement.","zh":"這個短語用於給出一般時間量度。"}],"source":"62 - The Brains Business.pdf","sourcePage":14},{"front":"what, if anything, can be done","meaning":"究竟可以做些甚麼","examples":[{"en":"The passage asks what, if anything, can be done.","zh":"文章問究竟可以做些甚麼。"},{"en":"What, if anything, can be done means what action is possible, if any action is possible at all.","zh":"what, if anything, can be done 指如果真的有可行行動，究竟可以採取甚麼行動。"},{"en":"After repeated floods, residents may ask what, if anything, can be done to protect their homes.","zh":"反覆水浸後，居民可能問究竟可以做些甚麼來保護家園。"},{"en":"This phrase suggests uncertainty about whether solutions exist.","zh":"這個短語表示對是否存在解決方法感到不確定。"},{"en":"It introduces a problem-solving discussion cautiously.","zh":"它謹慎地引入解難討論。"}],"source":"62 - The Brains Business.pdf","sourcePage":15},{"front":"techno-utopians","meaning":"技術烏托邦主義者","examples":[{"en":"Techno-utopians believe that higher education is ready for revolution.","zh":"技術烏托邦主義者相信高等教育已準備好迎接革命。"},{"en":"Techno-utopians are people who believe technology can solve major social or institutional problems.","zh":"techno-utopians 指相信科技能解決重大社會或機構問題的人。"},{"en":"A techno-utopian may think online learning can replace most physical classrooms.","zh":"技術烏托邦主義者可能認為網上學習可以取代大部分實體課室。"},{"en":"Such optimism can inspire innovation, but it may ignore human needs and inequality.","zh":"這種樂觀可以啟發創新，但也可能忽視人類需要和不平等。"},{"en":"This phrase describes strong faith in technological solutions.","zh":"這個短語描述對科技解決方案的強烈信念。"}],"source":"62 - The Brains Business.pdf","sourcePage":15},{"front":"be ripe for revolution","meaning":"革命性變革的時機已成熟","examples":[{"en":"Some reformers believe higher education is ripe for revolution.","zh":"有些改革者相信高等教育革命性變革的時機已成熟。"},{"en":"To be ripe for revolution means to be ready for major and rapid change.","zh":"be ripe for revolution 指已準備好迎接重大而快速的改變。"},{"en":"A company with outdated systems and unhappy customers may be ripe for reform.","zh":"擁有過時系統和不滿顧客的公司，可能改革時機已成熟。"},{"en":"When pressure builds for years, a sector may become ready for radical change.","zh":"當壓力累積多年，一個行業可能已準備好徹底改變。"},{"en":"This phrase suggests the time for big change has arrived.","zh":"這個短語表示重大變革的時間已到。"}],"source":"62 - The Brains Business.pdf","sourcePage":15},{"front":"hopelessly antiquated","meaning":"過時得無可救藥","examples":[{"en":"They see the university as a hopelessly antiquated institution.","zh":"他們把大學視為過時得無可救藥的機構。"},{"en":"Hopelessly antiquated means so old-fashioned that it seems impossible to fix or modernise easily.","zh":"hopelessly antiquated 指過時到似乎無法輕易修正或現代化。"},{"en":"A hospital using only paper records may seem hopelessly antiquated to younger doctors.","zh":"仍只使用紙本紀錄的醫院，對較年輕醫生來說可能過時得無可救藥。"},{"en":"Antiquated systems can slow work and frustrate people who need modern services.","zh":"過時制度可以拖慢工作，並令需要現代服務的人感到挫敗。"},{"en":"This phrase is strongly negative.","zh":"這個短語帶強烈負面意思。"}],"source":"62 - The Brains Business.pdf","sourcePage":15},{"front":"be wedded to","meaning":"固守；依附於","examples":[{"en":"Universities are wedded to outdated practices.","zh":"大學固守過時做法。"},{"en":"To be wedded to something means to be strongly attached to it and unwilling to give it up.","zh":"be wedded to something 指強烈依附於某事，並不願放棄。"},{"en":"A teacher may be wedded to printed worksheets even when online tools would help.","zh":"即使網上工具有幫助，老師也可能固守紙本工作紙。"},{"en":"Being too attached to old methods can block necessary improvement.","zh":"過分依附舊方法可以阻礙必要改善。"},{"en":"This phrase suggests stubborn loyalty to an idea or practice.","zh":"這個短語表示對某想法或做法的頑固忠誠。"}],"source":"62 - The Brains Business.pdf","sourcePage":15},{"front":"outdated practices","meaning":"過時做法","examples":[{"en":"Tenure and lectures are described as outdated practices.","zh":"終身教席制和講課被描述為過時做法。"},{"en":"Outdated practices are old methods that no longer fit present needs or conditions.","zh":"outdated practices 指不再符合目前需要或條件的舊方法。"},{"en":"A school using only handwritten notices may be relying on outdated practices.","zh":"只使用手寫通告的學校，可能依賴過時做法。"},{"en":"Outdated practices can continue because people are used to them.","zh":"過時做法可能因人們習慣了而繼續存在。"},{"en":"This phrase criticises old methods that need review.","zh":"這個短語批評需要重新檢視的舊方法。"}],"source":"62 - The Brains Business.pdf","sourcePage":15},{"front":"tenure","meaning":"終身教席制","examples":[{"en":"Some critics regard tenure as an outdated practice.","zh":"有些批評者把終身教席制視為過時做法。"},{"en":"Tenure is a system giving academics long-term job security after they meet certain standards.","zh":"tenure 指學者達到某些標準後獲得長期職位保障的制度。"},{"en":"A professor with tenure may have more freedom to research unpopular ideas.","zh":"擁有終身教席的教授可能更自由研究不受歡迎的想法。"},{"en":"Tenure can protect academic freedom, but critics say it may reduce accountability.","zh":"終身教席制可以保護學術自由，但批評者說它可能降低問責。"},{"en":"This word refers to a university employment system.","zh":"這個詞指大學聘用制度。"}],"source":"62 - The Brains Business.pdf","sourcePage":15},{"front":"incapable of serving","meaning":"無法服務；無法滿足","examples":[{"en":"They claim universities are incapable of serving a new world.","zh":"他們聲稱大學無法滿足一個新世界的需要。"},{"en":"Incapable of serving means unable to meet the needs of a person, group, or situation.","zh":"incapable of serving 指無法滿足某人、群體或情況的需要。"},{"en":"A bus system may be incapable of serving a growing suburb if there are too few routes.","zh":"如果路線太少，巴士系統可能無法服務成長中的郊區。"},{"en":"When an institution cannot serve new needs, people demand reform.","zh":"當機構不能滿足新需要，人們就會要求改革。"},{"en":"This phrase expresses serious inability.","zh":"這個短語表達嚴重無能力。"}],"source":"62 - The Brains Business.pdf","sourcePage":15},{"front":"mass audiences","meaning":"大眾受眾","examples":[{"en":"Universities must serve a new world of mass audiences.","zh":"大學必須服務一個面向大眾受眾的新世界。"},{"en":"Mass audiences are very large groups of ordinary people rather than a small elite group.","zh":"mass audiences 指非常龐大的普通人群，而不是少數精英群體。"},{"en":"Television channels design programmes for mass audiences when they want millions of viewers.","zh":"電視頻道想吸引數百萬觀眾時，就會為大眾受眾設計節目。"},{"en":"Serving mass audiences requires scale, clarity, and affordability.","zh":"服務大眾受眾需要規模、清晰度和可負擔性。"},{"en":"This phrase contrasts broad public access with elite access.","zh":"這個短語把廣泛公共可及性與精英可及性作對比。"}],"source":"62 - The Brains Business.pdf","sourcePage":15},{"front":"just-in-time information","meaning":"即時資訊","examples":[{"en":"The modern world demands just-in-time information.","zh":"現代世界要求即時資訊。"},{"en":"Just-in-time information is information delivered exactly when people need it.","zh":"just-in-time information 指在人們正需要時提供的資訊。"},{"en":"A bus app gives just-in-time information when it tells passengers the next bus arrival time.","zh":"巴士應用程式告訴乘客下一班巴士到達時間時，就是提供即時資訊。"},{"en":"Timely information helps people make quick decisions without reading a whole manual.","zh":"及時資訊幫助人快速決策，而不必閱讀整本手冊。"},{"en":"This phrase describes fast, practical, moment-of-need knowledge.","zh":"這個短語描述快速、實用、按需要提供的知識。"}],"source":"62 - The Brains Business.pdf","sourcePage":15},{"front":"thirty years from now","meaning":"三十年後","examples":[{"en":"Thirty years from now, large university campuses may be relics.","zh":"三十年後，大型大學校園可能成為過時遺物。"},{"en":"Thirty years from now means three decades in the future.","zh":"thirty years from now 指從現在起三十年後。"},{"en":"Thirty years from now, many jobs may require skills that are rare today.","zh":"三十年後，許多工作可能需要今天罕見的技能。"},{"en":"Long-term predictions help people imagine how current systems might change.","zh":"長期預測幫助人想像現有制度可能如何改變。"},{"en":"This phrase places an idea in the future.","zh":"這個短語把想法放在未來。"}],"source":"62 - The Brains Business.pdf","sourcePage":16},{"front":"university campuses","meaning":"大學校園","examples":[{"en":"Peter Drucker predicted that large university campuses would become relics.","zh":"Peter Drucker 預測大型大學校園會成為過時遺物。"},{"en":"University campuses are the buildings, grounds, and facilities where university life takes place.","zh":"university campuses 指大學生活進行所在的建築、土地和設施。"},{"en":"A campus may include lecture halls, libraries, dormitories, laboratories, and sports fields.","zh":"校園可能包括演講廳、圖書館、宿舍、實驗室和運動場。"},{"en":"If learning moves online, campuses may need to redefine their purpose.","zh":"如果學習轉到網上，校園可能需要重新界定其目的。"},{"en":"This phrase refers to the physical setting of a university.","zh":"這個短語指大學的實體環境。"}],"source":"62 - The Brains Business.pdf","sourcePage":16},{"front":"be relics","meaning":"成為遺跡；過時遺物","examples":[{"en":"Big university campuses may become relics.","zh":"大型大學校園可能成為過時遺物。"},{"en":"To be relics means to become old objects or systems left over from the past.","zh":"be relics 指成為過去留下的舊物件或舊制度。"},{"en":"Fax machines are relics in many offices where email has replaced them.","zh":"在許多已由電郵取代傳真的辦公室，傳真機成為過時遺物。"},{"en":"Something becomes a relic when society no longer needs it in the same way.","zh":"當社會不再以同樣方式需要某物，它就成為遺物。"},{"en":"This phrase suggests obsolescence and historical leftover.","zh":"這個短語表示過時和歷史遺留。"}],"source":"62 - The Brains Business.pdf","sourcePage":16},{"front":"veteran management guru","meaning":"資深管理大師","examples":[{"en":"Peter Drucker was a veteran management guru.","zh":"Peter Drucker 是一位資深管理大師。"},{"en":"A veteran management guru is a long-experienced expert known for advice on how organisations are run.","zh":"veteran management guru 指在組織管理方面經驗豐富且以建議聞名的專家。"},{"en":"A company may invite a management guru to explain leadership and strategy.","zh":"公司可能邀請管理大師解釋領導和策略。"},{"en":"Expert advice can shape how leaders think about future change.","zh":"專家建議可以塑造領導者如何思考未來變化。"},{"en":"This phrase describes both experience and reputation in management.","zh":"這個短語同時描述管理方面的經驗和聲譽。"}],"source":"62 - The Brains Business.pdf","sourcePage":16},{"front":"research university","meaning":"研究型大學","examples":[{"en":"He considered the American research university to be a failure.","zh":"他認為美國研究型大學是失敗的。"},{"en":"A research university is a university that strongly focuses on producing new research as well as teaching students.","zh":"research university 指除了教學外，也非常重視產生新研究的大學。"},{"en":"Research universities often have laboratories, doctoral programmes, and major grants.","zh":"研究型大學通常有實驗室、博士課程和大型撥款。"},{"en":"Strong research can raise prestige, but it may also compete with teaching time.","zh":"強大研究可以提升聲望，但也可能與教學時間競爭。"},{"en":"This phrase refers to a university model centred on research.","zh":"這個短語指以研究為核心的大學模式。"}],"source":"62 - The Brains Business.pdf","sourcePage":16},{"front":"consider something to be","meaning":"認為……是","examples":[{"en":"He considered the American research university to be a failure.","zh":"他認為美國研究型大學是失敗的。"},{"en":"To consider something to be something means to judge or think of it in that way.","zh":"consider something to be something 指判斷或認為某事是某種情況。"},{"en":"Some teachers consider homework to be useful only when it gives clear practice.","zh":"有些老師認為只有提供清楚練習的功課才有用。"},{"en":"Judgement depends on what standards people use.","zh":"判斷取決於人們使用甚麼標準。"},{"en":"This phrase introduces someone’s opinion or evaluation.","zh":"這個短語引入某人的意見或評價。"}],"source":"62 - The Brains Business.pdf","sourcePage":16},{"front":"in his view","meaning":"在他看來","examples":[{"en":"In his view, help is on the way.","zh":"在他看來，解決方法即將出現。"},{"en":"In his view means according to his opinion or judgement.","zh":"in his view 指根據他的意見或判斷。"},{"en":"In the principal’s view, smaller classes would improve student confidence.","zh":"在校長看來，較小班級會提升學生信心。"},{"en":"This phrase reminds readers that the statement is one person’s perspective.","zh":"這個短語提醒讀者該說法是一個人的觀點。"},{"en":"It is useful when reporting opinion rather than fact.","zh":"它適合用於報告意見而不是事實。"}],"source":"62 - The Brains Business.pdf","sourcePage":16},{"front":"help is on the way","meaning":"解決方法即將出現","examples":[{"en":"Some reformers believe help is on the way.","zh":"有些改革者相信解決方法即將出現。"},{"en":"Help is on the way means a solution or support is coming soon.","zh":"help is on the way 指解決方法或支援很快會到來。"},{"en":"If a student is stuck online, a message from the teacher can make them feel help is on the way.","zh":"如果學生在網上學習中卡住，老師的訊息可以令他感到支援快到了。"},{"en":"This phrase can give hope during a difficult situation.","zh":"這個短語可以在困難情況中給人希望。"},{"en":"It suggests the problem is not solved yet, but support is approaching.","zh":"它表示問題尚未解決，但支援正在接近。"}],"source":"62 - The Brains Business.pdf","sourcePage":16},{"front":"in the form of","meaning":"以……形式","examples":[{"en":"Help may arrive in the form of Internet tuition.","zh":"解決方法可能以網上教學形式出現。"},{"en":"In the form of means appearing or being provided as a particular type of thing.","zh":"in the form of 指以某種特定類型出現或被提供。"},{"en":"Support may come in the form of money, advice, or extra lessons.","zh":"支援可能以金錢、建議或額外課堂形式出現。"},{"en":"The form of help matters because different problems need different solutions.","zh":"支援形式很重要，因為不同問題需要不同解決方法。"},{"en":"This phrase identifies what shape or type something takes.","zh":"這個短語指出某事採取甚麼形態或類型。"}],"source":"62 - The Brains Business.pdf","sourcePage":16},{"front":"Internet tuition","meaning":"網上教學","examples":[{"en":"Internet tuition is presented as one possible solution.","zh":"網上教學被提出作為一種可能的解決方法。"},{"en":"Internet tuition means teaching delivered online through videos, live classes, or digital platforms.","zh":"Internet tuition 指透過影片、直播課堂或數碼平台提供的教學。"},{"en":"A student may use Internet tuition to learn maths from home after school.","zh":"學生可能放學後在家使用網上教學學數學。"},{"en":"Online teaching can increase access, but it may not replace all face-to-face support.","zh":"網上教學可以增加可及性，但未必能取代所有面對面支援。"},{"en":"This phrase refers to education through the internet.","zh":"這個短語指透過互聯網進行的教育。"}],"source":"62 - The Brains Business.pdf","sourcePage":16},{"front":"for-profit universities","meaning":"牟利大學","examples":[{"en":"Some reformers support the growth of for-profit universities.","zh":"有些改革者支持牟利大學增長。"},{"en":"For-profit universities are universities operated to earn profit as well as provide education.","zh":"for-profit universities 指以賺取利潤並提供教育為目的營運的大學。"},{"en":"A for-profit college may advertise flexible courses to working adults.","zh":"牟利學院可能向在職成年人宣傳彈性課程。"},{"en":"Profit motives can encourage efficiency, but they may also conflict with educational values.","zh":"牟利動機可以鼓勵效率，但也可能與教育價值衝突。"},{"en":"This phrase identifies a market-based university model.","zh":"這個短語指出市場化大學模式。"}],"source":"62 - The Brains Business.pdf","sourcePage":17},{"front":"cultural conservatives","meaning":"文化保守派","examples":[{"en":"Cultural conservatives reject many market-based reforms.","zh":"文化保守派拒絕許多市場化改革。"},{"en":"Cultural conservatives are people who want to protect traditional culture, values, or institutions from rapid change.","zh":"cultural conservatives 指希望保護傳統文化、價值或機構免受快速改變影響的人。"},{"en":"A cultural conservative may oppose replacing classic literature with only popular media.","zh":"文化保守派可能反對只用流行媒體取代經典文學。"},{"en":"Their concern is often that speed, profit, or fashion may damage deeper values.","zh":"他們的擔憂通常是速度、利潤或潮流可能損害更深層價值。"},{"en":"This phrase describes a traditionalist position on culture.","zh":"這個短語描述文化上的傳統主義立場。"}],"source":"62 - The Brains Business.pdf","sourcePage":17},{"front":"on the other hand","meaning":"另一方面","examples":[{"en":"Cultural conservatives, on the other hand, prefer older models.","zh":"另一方面，文化保守派偏好較舊模式。"},{"en":"On the other hand introduces a different or opposite viewpoint.","zh":"on the other hand 用來引入不同或相反觀點。"},{"en":"Online lessons are flexible; on the other hand, some students learn better face to face.","zh":"網上課堂很彈性；另一方面，有些學生面對面學得更好。"},{"en":"This phrase helps writers compare two sides of an argument.","zh":"這個短語幫助作者比較論點兩面。"},{"en":"It signals contrast without completely rejecting the first point.","zh":"它表示對比，但不完全否定第一點。"}],"source":"62 - The Brains Business.pdf","sourcePage":17},{"front":"the best way forward is backward","meaning":"前進的最佳方法是回到過去","examples":[{"en":"Some conservatives believe the best way forward is backward.","zh":"有些保守派相信前進的最佳方法是回到過去。"},{"en":"The best way forward is backward means progress should come by returning to older methods or values.","zh":"the best way forward is backward 指進步應透過回到舊方法或舊價值來達成。"},{"en":"A school may think the best way forward is backward if it restores handwritten essays to improve focus.","zh":"如果學校恢復手寫作文以提升專注，它可能認為前進的最佳方法是回到過去。"},{"en":"This idea suggests that not every new method is better than an old one.","zh":"這種想法表示不是每種新方法都比舊方法好。"},{"en":"The phrase is paradoxical because “forward” and “backward” normally oppose each other.","zh":"這個短語帶有矛盾感，因為 forward 和 backward 通常相反。"}],"source":"62 - The Brains Business.pdf","sourcePage":17},{"front":"it is foolish to","meaning":"……是愚蠢的","examples":[{"en":"They think it is foolish to waste higher education on unsuitable students.","zh":"他們認為把高等教育浪費在不合適學生身上是愚蠢的。"},{"en":"It is foolish to do something means doing it is unwise or lacking good judgement.","zh":"it is foolish to do something 指做某事不明智或缺乏良好判斷。"},{"en":"It is foolish to ignore a deadline and hope the problem will disappear.","zh":"忽視限期並希望問題消失是愚蠢的。"},{"en":"People use this phrase to strongly criticise an action.","zh":"人們使用這個短語來強烈批評某行動。"},{"en":"This phrase expresses judgement, not neutral description.","zh":"這個短語表達判斷，而不是中性描述。"}],"source":"62 - The Brains Business.pdf","sourcePage":17},{"front":"waste higher education on","meaning":"將高等教育浪費在……身上","examples":[{"en":"Conservatives argue that higher education should not be wasted on everyone.","zh":"保守派認為高等教育不應浪費在所有人身上。"},{"en":"To waste higher education on someone means to give advanced education to people seen as unable or unwilling to benefit from it.","zh":"waste higher education on someone 指把高等教育給予被視為無法或不願從中受益的人。"},{"en":"A critic may say expensive training is wasted on staff who never use the skills.","zh":"批評者可能說昂貴培訓浪費在從不使用技能的員工身上。"},{"en":"This phrase is judgemental because it assumes some people do not deserve or need the opportunity.","zh":"這個短語帶判斷性，因為它假設有些人不值得或不需要該機會。"},{"en":"It reflects an elitist view of education.","zh":"它反映一種精英主義教育觀。"}],"source":"62 - The Brains Business.pdf","sourcePage":17},{"front":"would rather…than…","meaning":"寧願……也不……","examples":[{"en":"Some students would rather study popular television than philosophy.","zh":"有些學生寧願研究流行電視節目，也不願研究哲學。"},{"en":"Would rather A than B means prefer A instead of B.","zh":"would rather A than B 指寧願選 A 而不是 B。"},{"en":"A tired student may would rather revise at home than travel to the library.","zh":"疲倦學生可能寧願在家溫習，也不去圖書館。"},{"en":"This structure clearly shows preference between two choices.","zh":"這個結構清楚顯示兩個選擇之間的偏好。"},{"en":"It often contrasts what someone likes with what others think they should choose.","zh":"它常把某人喜歡的選擇與他人認為應選的東西作對比。"}],"source":"62 - The Brains Business.pdf","sourcePage":17},{"front":"Socrates","meaning":"蘇格拉底","examples":[{"en":"Some conservatives contrast popular culture with Socrates.","zh":"有些保守派把流行文化與蘇格拉底作對比。"},{"en":"Socrates was an ancient Greek philosopher often associated with questioning, truth, and serious thought.","zh":"Socrates 是古希臘哲學家，常與提問、真理和嚴肅思考相關。"},{"en":"A teacher may mention Socrates when explaining why asking questions is central to learning.","zh":"老師解釋為何提問是學習核心時，可能提到蘇格拉底。"},{"en":"Comparing television with Socrates creates a contrast between popular entertainment and classical philosophy.","zh":"把電視與蘇格拉底比較，形成流行娛樂與古典哲學之間的對比。"},{"en":"This name symbolises traditional intellectual seriousness.","zh":"這個名字象徵傳統知識嚴肅性。"}],"source":"62 - The Brains Business.pdf","sourcePage":17},{"front":"disingenuous","meaning":"不真誠的；虛偽的","examples":[{"en":"They think it is disingenuous to confuse truth with profit.","zh":"他們認為把真理與利潤混淆是不真誠的。"},{"en":"Disingenuous means not fully honest, especially by pretending not to understand something.","zh":"disingenuous 指不完全誠實，尤其是假裝不理解某事。"},{"en":"A company is disingenuous if it claims a fee is optional while making it almost impossible to avoid.","zh":"如果公司聲稱費用可選，但幾乎不可能避免，這就是虛偽。"},{"en":"Disingenuous arguments can mislead people because they hide the speaker’s real intention.","zh":"不真誠的論點可以誤導人，因為它隱藏說話者真正意圖。"},{"en":"This word criticises insincerity and intellectual dishonesty.","zh":"這個詞批評不真誠和思想上的不誠實。"}],"source":"62 - The Brains Business.pdf","sourcePage":17},{"front":"confuse…with…","meaning":"將……與……混淆","examples":[{"en":"It is disingenuous to confuse the pursuit of truth with the pursuit of profit.","zh":"將追求真理與追求利潤混淆是不真誠的。"},{"en":"To confuse A with B means to mix them up as if they were the same thing.","zh":"confuse A with B 指把 A 和 B 混在一起，好像它們是同一回事。"},{"en":"Students should not confuse confidence with accuracy when answering reading questions.","zh":"學生回答閱讀題時，不應將自信與準確混淆。"},{"en":"Confusing two ideas can lead to wrong decisions and weak arguments.","zh":"混淆兩個概念可以導致錯誤決定和薄弱論點。"},{"en":"This structure highlights a mistaken comparison.","zh":"這個結構突出錯誤比較。"}],"source":"62 - The Brains Business.pdf","sourcePage":17},{"front":"the pursuit of truth","meaning":"追求真理","examples":[{"en":"Universities are traditionally associated with the pursuit of truth.","zh":"大學傳統上與追求真理相關。"},{"en":"The pursuit of truth means the effort to discover what is real, accurate, or justified by evidence.","zh":"pursuit of truth 指努力發現真實、準確或有證據支持的事物。"},{"en":"A journalist engaged in the pursuit of truth checks sources before publishing a story.","zh":"追求真理的記者會在發表故事前查核資料來源。"},{"en":"This pursuit can conflict with profit when facts are inconvenient or unpopular.","zh":"當事實不方便或不受歡迎時，這種追求可能與利潤衝突。"},{"en":"The phrase describes an ideal of honest inquiry.","zh":"這個短語描述誠實探究的理想。"}],"source":"62 - The Brains Business.pdf","sourcePage":18},{"front":"the pursuit of profit","meaning":"追求利潤","examples":[{"en":"Critics dislike confusing the pursuit of truth with the pursuit of profit.","zh":"批評者不喜歡將追求真理與追求利潤混淆。"},{"en":"The pursuit of profit means the effort to make money or increase financial gain.","zh":"pursuit of profit 指努力賺錢或增加財務收益。"},{"en":"A company may cut costs in the pursuit of profit, but this can harm service quality.","zh":"公司可能為追求利潤而削減成本，但這可能損害服務質素。"},{"en":"Profit-seeking can support growth, but it may conflict with education or public values.","zh":"追求利潤可以支持增長，但也可能與教育或公共價值衝突。"},{"en":"This phrase describes a business goal.","zh":"這個短語描述商業目標。"}],"source":"62 - The Brains Business.pdf","sourcePage":18},{"front":"each of the following headings","meaning":"以下每個標題","examples":[{"en":"Students must match each of the following headings with a paragraph.","zh":"學生必須把以下每個標題與段落配對。"},{"en":"Each of the following headings means every title listed after the instruction.","zh":"each of the following headings 指指示後列出的每一個標題。"},{"en":"In a reading task, students should read each heading before choosing answers.","zh":"在閱讀題中，學生應先閱讀以下每個標題再選答案。"},{"en":"Checking each heading carefully helps avoid choosing a title based on one repeated word.","zh":"仔細檢查每個標題有助避免只根據一個重複字選題。"},{"en":"This phrase is common in matching-headings questions.","zh":"這個短語常見於標題配對題。"}],"source":"62 - The Brains Business.pdf","sourcePage":18},{"front":"best fit","meaning":"最適合","examples":[{"en":"The question asks which paragraph each heading best fits.","zh":"題目問每個標題最適合哪一段。"},{"en":"Best fit means the option that matches most closely, even if other options seem partly related.","zh":"best fit 指最接近匹配的選項，即使其他選項似乎部分相關。"},{"en":"A teacher may ask which title is the best fit for a student’s essay.","zh":"老師可能問哪個標題最適合學生文章。"},{"en":"Finding the best fit requires looking at the whole meaning, not one small detail.","zh":"找出最適合答案需要看整體意思，而不是一個小細節。"},{"en":"This phrase is used when choosing the most suitable match.","zh":"這個短語用於選擇最合適配對。"}],"source":"62 - The Brains Business.pdf","sourcePage":18},{"front":"education for the masses","meaning":"大眾教育","examples":[{"en":"Massification means education for the masses.","zh":"高等教育大眾化意思是大眾教育。"},{"en":"Education for the masses means education made available to large numbers of ordinary people.","zh":"education for the masses 指提供給大量普通人的教育。"},{"en":"Free public schooling is a form of education for the masses.","zh":"免費公立教育是一種大眾教育。"},{"en":"When education reaches the masses, societies may become more skilled and mobile.","zh":"當教育接觸大眾，社會可能變得更有技能和流動性。"},{"en":"This phrase contrasts broad access with elite education.","zh":"這個短語把廣泛可及性與精英教育作對比。"}],"source":"62 - The Brains Business.pdf","sourcePage":18},{"front":"future possibilities","meaning":"未來可能性","examples":[{"en":"The final paragraph discusses future possibilities for universities.","zh":"最後一段討論大學的未來可能性。"},{"en":"Future possibilities are things that may happen later but are not certain yet.","zh":"future possibilities 指將來可能發生但尚未確定的事情。"},{"en":"A school may discuss future possibilities such as online lessons, smaller classes, or new subjects.","zh":"學校可能討論網上課堂、小班教學或新學科等未來可能性。"},{"en":"Thinking about possibilities helps institutions prepare for change.","zh":"思考可能性幫助機構為改變作準備。"},{"en":"This phrase refers to possible future directions.","zh":"這個短語指未來可能方向。"}],"source":"62 - The Brains Business.pdf","sourcePage":18},{"front":"globalisation and competition","meaning":"全球化與競爭","examples":[{"en":"The text discusses globalisation and competition in higher education.","zh":"文章討論高等教育中的全球化與競爭。"},{"en":"Globalisation and competition mean universities are connected across borders and must compete for students, money, and reputation.","zh":"globalisation and competition 指大學跨國連接，並必須爭奪學生、金錢和聲譽。"},{"en":"A local college may face globalisation and competition when overseas universities offer online degrees.","zh":"當海外大學提供網上學位，本地學院可能面對全球化與競爭。"},{"en":"These forces can improve choice but also increase pressure on institutions.","zh":"這些力量可以增加選擇，但也增加機構壓力。"},{"en":"This phrase combines two major external pressures.","zh":"這個短語結合兩種主要外部壓力。"}],"source":"62 - The Brains Business.pdf","sourcePage":18},{"front":"funding problem","meaning":"資金問題","examples":[{"en":"The passage describes a serious funding problem in higher education.","zh":"文章描述高等教育中的嚴重資金問題。"},{"en":"A funding problem is a shortage or difficulty in getting enough money to support an activity.","zh":"funding problem 指取得足夠金錢支持某活動時出現短缺或困難。"},{"en":"A school has a funding problem if it cannot repair classrooms or hire enough teachers.","zh":"如果學校不能維修課室或聘請足夠老師，就有資金問題。"},{"en":"Funding problems can reduce quality even when demand is high.","zh":"即使需求高，資金問題也可以降低質素。"},{"en":"This phrase identifies money as the central difficulty.","zh":"這個短語指出金錢是核心困難。"}],"source":"62 - The Brains Business.pdf","sourcePage":18},{"front":"according to the text","meaning":"根據文章","examples":[{"en":"According to the text, universities are facing several major pressures.","zh":"根據文章，大學正面對幾項重大壓力。"},{"en":"According to the text means based on what the passage says, not outside knowledge.","zh":"according to the text 指根據文章所說，而不是外部知識。"},{"en":"According to the text, students should answer with words from the passage.","zh":"根據文章，學生應使用文章中的字詞作答。"},{"en":"This phrase reminds test-takers to rely on the source material.","zh":"這個短語提醒應試者依賴文本材料。"},{"en":"It is common in reading questions.","zh":"它常見於閱讀題。"}],"source":"62 - The Brains Business.pdf","sourcePage":18},{"front":"the following statements","meaning":"以下陳述","examples":[{"en":"Students must decide which of the following statements are true.","zh":"學生必須判斷以下哪些陳述屬實。"},{"en":"The following statements means the sentences listed after the instruction.","zh":"following statements 指指示後列出的句子。"},{"en":"In an exam, students should read the following statements before returning to the passage.","zh":"在考試中，學生應先閱讀以下陳述，再回到文章。"},{"en":"Checking each statement carefully helps avoid traps in wording.","zh":"仔細檢查每個陳述有助避免措辭陷阱。"},{"en":"This phrase introduces a set of answer items.","zh":"這個短語引入一組答題項目。"}],"source":"62 - The Brains Business.pdf","sourcePage":18},{"front":"corresponding letters","meaning":"相應字母","examples":[{"en":"Students write the corresponding letters in the answer boxes.","zh":"學生在答案格中寫上相應字母。"},{"en":"Corresponding letters are the letters that match the chosen answers.","zh":"corresponding letters 指與所選答案相配的字母。"},{"en":"If the correct options are A and D, students must write the corresponding letters clearly.","zh":"如果正確選項是 A 和 D，學生必須清楚寫上相應字母。"},{"en":"Even if the idea is right, copying the wrong letter can lose marks.","zh":"即使想法正確，抄錯字母也可能失分。"},{"en":"This phrase focuses on answer format.","zh":"這個短語著重答案格式。"}],"source":"62 - The Brains Business.pdf","sourcePage":19},{"front":"in any order","meaning":"以任何次序","examples":[{"en":"The five answers may be written in any order.","zh":"五個答案可以以任何次序寫下。"},{"en":"In any order means the sequence does not matter.","zh":"in any order 指次序並不重要。"},{"en":"If a teacher says answers can be written in any order, students do not need to arrange them alphabetically.","zh":"如果老師說答案可以以任何次序寫下，學生不需要按字母排列。"},{"en":"This instruction reduces worry about sequence and lets students focus on correctness.","zh":"這個指示減少對次序的擔心，讓學生集中於正確性。"},{"en":"This phrase means order will not affect the mark.","zh":"這個短語表示次序不會影響分數。"}],"source":"62 - The Brains Business.pdf","sourcePage":19},{"front":"join with each other","meaning":"彼此合併；聯合","examples":[{"en":"Some universities are joining with each other through mergers.","zh":"有些大學透過合併彼此聯合。"},{"en":"To join with each other means to combine, cooperate, or become one organisation.","zh":"join with each other 指結合、合作或成為一個組織。"},{"en":"Two small clubs may join with each other to share members and reduce costs.","zh":"兩個小學會可能彼此聯合，以共享會員並降低成本。"},{"en":"Joining can create strength, but it may also require compromise.","zh":"聯合可以創造力量，但也可能需要妥協。"},{"en":"This phrase describes mutual connection or combination.","zh":"這個短語描述相互連接或結合。"}],"source":"62 - The Brains Business.pdf","sourcePage":19},{"front":"not enough graduates","meaning":"畢業生不足","examples":[{"en":"The option claims that there are not enough graduates in developed countries.","zh":"該選項聲稱已發展國家畢業生不足。"},{"en":"Not enough graduates means the number of people finishing university is lower than what is needed.","zh":"not enough graduates 指完成大學教育的人數低於所需水平。"},{"en":"A hospital system may face problems if there are not enough nursing graduates.","zh":"如果護理畢業生不足，醫院系統可能面對問題。"},{"en":"A shortage of graduates can limit economic growth or public services.","zh":"畢業生短缺可以限制經濟增長或公共服務。"},{"en":"This phrase describes an insufficient supply of educated workers.","zh":"這個短語描述受教育工作者供應不足。"}],"source":"62 - The Brains Business.pdf","sourcePage":19},{"front":"devote a third of profits to","meaning":"將三分之一利潤投放於……","examples":[{"en":"The option says companies devote a third of profits to research and development.","zh":"該選項說公司將三分之一利潤投放於研發。"},{"en":"To devote a third of profits to something means to put one third of earned money into that purpose.","zh":"devote a third of profits to something 指把賺得金錢的三分之一投放於某目的。"},{"en":"A small business may devote a third of profits to improving equipment.","zh":"小企業可能將三分之一利潤投放於改善設備。"},{"en":"Spending a large share of profits shows a strong priority.","zh":"花費大比例利潤顯示強烈優先次序。"},{"en":"This phrase connects company earnings with investment choices.","zh":"這個短語把公司收益與投資選擇連繫起來。"}],"source":"62 - The Brains Business.pdf","sourcePage":19},{"front":"research and development","meaning":"研發","examples":[{"en":"Research and development is a key part of knowledge-based investment.","zh":"研發是知識型投資的關鍵部分。"},{"en":"Research and development means work done to discover new knowledge and create or improve products.","zh":"research and development 指發現新知識並創造或改善產品的工作。"},{"en":"A technology company uses research and development to design better batteries.","zh":"科技公司使用研發來設計更好的電池。"},{"en":"Strong R&D can lead to innovation, patents, and competitive advantage.","zh":"強大研發可以帶來創新、專利和競爭優勢。"},{"en":"This phrase is often shortened to R&D.","zh":"這個短語常縮寫為 R&D。"}],"source":"62 - The Brains Business.pdf","sourcePage":19},{"front":"outside their home countries","meaning":"在本國以外","examples":[{"en":"More students are studying outside their home countries.","zh":"更多學生在本國以外升學。"},{"en":"Outside their home countries means in countries other than the ones where they usually live or come from.","zh":"outside their home countries 指在他們通常居住或來自的國家以外。"},{"en":"A student from Japan studying in Britain is studying outside their home country.","zh":"來自日本並在英國讀書的學生，就是在本國以外升學。"},{"en":"Studying overseas can bring new experience but also language and cultural challenges.","zh":"海外升學可以帶來新經驗，但也有語言和文化挑戰。"},{"en":"This phrase describes international movement for education or work.","zh":"這個短語描述為教育或工作而作的國際移動。"}],"source":"62 - The Brains Business.pdf","sourcePage":19},{"front":"in the last two decades","meaning":"在過去二十年間","examples":[{"en":"The number of students studying abroad doubled in the last two decades.","zh":"到海外升學的學生人數在過去二十年間翻倍。"},{"en":"In the last two decades means during the most recent twenty years.","zh":"in the last two decades 指最近二十年期間。"},{"en":"In the last two decades, smartphones have changed how students communicate.","zh":"在過去二十年間，智能手機改變了學生溝通方式。"},{"en":"This phrase is useful for describing recent long-term trends.","zh":"這個短語適合描述近期長期趨勢。"},{"en":"It gives a time frame without naming exact years.","zh":"它給出時間範圍，而不列明準確年份。"}],"source":"62 - The Brains Business.pdf","sourcePage":19},{"front":"provide enough money for","meaning":"為……提供足夠資金","examples":[{"en":"Some governments provide enough money for their universities.","zh":"有些政府為其大學提供足夠資金。"},{"en":"To provide enough money for something means to fund it at the level it needs.","zh":"provide enough money for something 指按某事所需水平資助它。"},{"en":"A school trip can happen only if parents and sponsors provide enough money for transport.","zh":"只有當家長和贊助者為交通提供足夠資金，學校旅行才能成行。"},{"en":"Without enough money, even a good plan may fail.","zh":"沒有足夠金錢，即使好計劃也可能失敗。"},{"en":"This phrase connects funding with practical ability to operate.","zh":"這個短語把資金與實際運作能力連繫起來。"}],"source":"62 - The Brains Business.pdf","sourcePage":19},{"front":"before being accepted into university","meaning":"被大學取錄前","examples":[{"en":"Some applicants may have an interview before being accepted into university.","zh":"有些申請者被大學取錄前可能需要面試。"},{"en":"Before being accepted into university means before a university officially offers a student a place.","zh":"before being accepted into university 指在大學正式給學生學位之前。"},{"en":"A student may submit grades, references, and a personal statement before being accepted.","zh":"學生被取錄前可能提交成績、推薦信和個人陳述。"},{"en":"Admissions steps help universities decide who is suitable for a course.","zh":"收生步驟幫助大學決定誰適合課程。"},{"en":"This phrase describes the period before admission is confirmed.","zh":"這個短語描述入學確認之前的時期。"}],"source":"62 - The Brains Business.pdf","sourcePage":19},{"front":"foresee the end of","meaning":"預見……的終結","examples":[{"en":"Peter Drucker foresees the end of large university campuses.","zh":"Peter Drucker 預見大型大學校園的終結。"},{"en":"To foresee the end of something means to predict that it will disappear or stop being important.","zh":"foresee the end of something 指預測某事會消失或不再重要。"},{"en":"Some people foresee the end of paper tickets as transport apps become common.","zh":"隨着交通應用程式普及，有些人預見紙本車票的終結。"},{"en":"Forecasting an end can push organisations to prepare for change.","zh":"預測終結可以推動組織為改變作準備。"},{"en":"This phrase describes a prediction about disappearance or decline.","zh":"這個短語描述關於消失或衰落的預測。"}],"source":"62 - The Brains Business.pdf","sourcePage":20},{"front":"according to the information given","meaning":"根據所提供的資料","examples":[{"en":"Students must answer according to the information given in the text.","zh":"學生必須根據文本中所提供的資料作答。"},{"en":"According to the information given means based only on the details provided in the source.","zh":"according to the information given 指只根據來源中提供的細節。"},{"en":"In a reading exam, students should not use outside knowledge when answering according to the information given.","zh":"在閱讀考試中，學生根據所提供資料作答時，不應使用外部知識。"},{"en":"This phrase reminds students to stay close to the passage.","zh":"這個短語提醒學生緊扣文章。"},{"en":"It is common in test instructions.","zh":"它常見於考試指示。"}],"source":"62 - The Brains Business.pdf","sourcePage":20},{"front":"choose the correct answer or answers","meaning":"選出正確答案","examples":[{"en":"The instructions ask students to choose the correct answer or answers.","zh":"指示要求學生選出正確答案。"},{"en":"Choose the correct answer or answers means select one or more options that are right.","zh":"choose the correct answer or answers 指選出一個或多個正確選項。"},{"en":"Students should check whether the question asks for one answer or more than one.","zh":"學生應檢查題目要求一個答案還是多於一個答案。"},{"en":"Missing the plural “answers” can cause careless mistakes.","zh":"忽略 answers 的複數形式可能造成粗心錯誤。"},{"en":"This phrase focuses on selecting the right option count.","zh":"這個短語著重選出正確選項數量。"}],"source":"62 - The Brains Business.pdf","sourcePage":20},{"front":"from the choices given","meaning":"從所給選項中","examples":[{"en":"Students choose their answers from the choices given.","zh":"學生從所給選項中選擇答案。"},{"en":"From the choices given means only from the options provided in the question.","zh":"from the choices given 指只從題目提供的選項中選擇。"},{"en":"In a multiple-choice task, students should not invent an answer outside the choices given.","zh":"在多項選擇題中，學生不應在所給選項以外自創答案。"},{"en":"Provided choices may include distractors that sound partly correct.","zh":"提供的選項可能包括聽起來部分正確的干擾項。"},{"en":"This phrase identifies the answer set.","zh":"這個短語指出答案集合。"}],"source":"62 - The Brains Business.pdf","sourcePage":20},{"front":"respond to change by","meaning":"透過……回應變化","examples":[{"en":"Universities are responding to change by experimenting with new funding methods.","zh":"大學正在透過試行新的資金方法來回應變化。"},{"en":"To respond to change by doing something means to react to a new situation through a particular action.","zh":"respond to change by doing something 指透過某種行動來應對新情況。"},{"en":"Shops respond to change by offering online ordering when customers stop visiting in person.","zh":"當顧客不再親身到店，商店透過提供網上訂購回應變化。"},{"en":"Responses to change can help organisations survive, but poor responses can create new problems.","zh":"對變化的回應可以幫助組織生存，但差劣回應可能造成新問題。"},{"en":"This phrase links pressure with action.","zh":"這個短語把壓力與行動連繫起來。"}],"source":"62 - The Brains Business.pdf","sourcePage":20},{"front":"construct new buildings","meaning":"興建新建築","examples":[{"en":"Some institutions may construct new buildings to appear traditional.","zh":"有些機構可能興建新建築，以顯得傳統。"},{"en":"To construct new buildings means to build new physical structures.","zh":"construct new buildings 指建造新的實體建築物。"},{"en":"A university may construct new buildings when student numbers increase.","zh":"當學生人數增加，大學可能興建新建築。"},{"en":"New buildings can solve space problems, but they require large investment.","zh":"新建築可以解決空間問題，但需要大量投資。"},{"en":"This phrase refers to building construction, not policy design.","zh":"這個短語指建築施工，而不是政策設計。"}],"source":"62 - The Brains Business.pdf","sourcePage":20},{"front":"in old styles","meaning":"以古老風格","examples":[{"en":"New buildings can be designed in old styles.","zh":"新建築可以以古老風格設計。"},{"en":"In old styles means using design features from earlier historical periods.","zh":"in old styles 指使用較早歷史時期的設計特色。"},{"en":"A new restaurant may decorate in old styles with wooden signs and vintage lights.","zh":"新餐廳可能用木牌和復古燈飾，以古老風格裝飾。"},{"en":"Old styles can make a new place feel more traditional or familiar.","zh":"古老風格可以令新地方感覺更傳統或更熟悉。"},{"en":"This phrase describes appearance, not actual age.","zh":"這個短語描述外觀，而不是實際年齡。"}],"source":"62 - The Brains Business.pdf","sourcePage":20},{"front":"appear old and traditional","meaning":"顯得古老而傳統","examples":[{"en":"Some universities try to appear old and traditional.","zh":"有些大學嘗試顯得古老而傳統。"},{"en":"To appear old and traditional means to look as if one has a long history and established customs.","zh":"appear old and traditional 指看起來像有悠久歷史和既定習俗。"},{"en":"A new school may use classic architecture to appear old and traditional.","zh":"新學校可能使用古典建築風格，令自己顯得古老而傳統。"},{"en":"Appearing traditional can help institutions seem respectable.","zh":"顯得傳統可以幫助機構看起來受尊重。"},{"en":"This phrase focuses on image rather than reality.","zh":"這個短語著重形象，而不是現實。"}],"source":"62 - The Brains Business.pdf","sourcePage":20},{"front":"introduce new subjects for study","meaning":"引入新的學科","examples":[{"en":"Universities may introduce new subjects for study.","zh":"大學可能引入新的學科。"},{"en":"To introduce new subjects for study means to add new academic areas or courses for students.","zh":"introduce new subjects for study 指為學生加入新的學術範疇或課程。"},{"en":"A school may introduce coding as a new subject when technology becomes more important.","zh":"當科技變得更重要，學校可能引入編程作為新學科。"},{"en":"New subjects can help education match changing job markets and social needs.","zh":"新學科可以幫助教育配合改變中的就業市場和社會需要。"},{"en":"This phrase describes curriculum expansion.","zh":"這個短語描述課程擴展。"}],"source":"62 - The Brains Business.pdf","sourcePage":20},{"front":"charge students higher fees","meaning":"向學生收取更高學費","examples":[{"en":"Universities may respond to funding pressure by charging students higher fees.","zh":"大學可能透過向學生收取更高學費來回應資金壓力。"},{"en":"To charge students higher fees means to ask students to pay more money for their education.","zh":"charge students higher fees 指要求學生為教育支付更多金錢。"},{"en":"A college may charge higher fees if government support is reduced.","zh":"如果政府支援減少，學院可能收取更高學費。"},{"en":"Higher fees can raise income, but they may discourage poorer students.","zh":"更高學費可以增加收入，但可能令較貧困學生卻步。"},{"en":"This phrase describes a funding method with social consequences.","zh":"這個短語描述一種有社會後果的資金方法。"}],"source":"62 - The Brains Business.pdf","sourcePage":20},{"front":"not fully appreciated","meaning":"未被充分重視","examples":[{"en":"The importance of the knowledge economy is not fully appreciated by everyone.","zh":"知識型經濟的重要性未被所有人充分重視。"},{"en":"Not fully appreciated means not completely understood, valued, or recognised.","zh":"not fully appreciated 指沒有被完全理解、重視或認可。"},{"en":"A quiet student’s effort may not be fully appreciated until their project succeeds.","zh":"安靜學生的努力可能直到項目成功後才被充分重視。"},{"en":"When something is not fully appreciated, people may underinvest in it.","zh":"當某事未被充分重視，人們可能投資不足。"},{"en":"This phrase describes incomplete recognition of importance.","zh":"這個短語描述對重要性的認可不完整。"}],"source":"62 - The Brains Business.pdf","sourcePage":21},{"front":"be heavily reliant on","meaning":"極度依賴……","examples":[{"en":"The knowledge economy is heavily reliant on universities.","zh":"知識型經濟極度依賴大學。"},{"en":"To be heavily reliant on something means to depend on it very strongly.","zh":"be heavily reliant on something 指非常強烈地依賴某事物。"},{"en":"A hospital is heavily reliant on nurses to keep daily care running.","zh":"醫院極度依賴護士來維持日常護理運作。"},{"en":"Strong dependence creates risk if the supporting institution becomes weak.","zh":"強烈依賴會帶來風險，若支撐機構變弱就會出問題。"},{"en":"This phrase shows serious dependence.","zh":"這個短語顯示嚴重依賴。"}],"source":"62 - The Brains Business.pdf","sourcePage":21},{"front":"current problems","meaning":"當前問題","examples":[{"en":"Current problems at universities include funding pressure and conflict with governments.","zh":"大學的當前問題包括資金壓力和與政府的衝突。"},{"en":"Current problems are difficulties that exist now, not only in the past or future.","zh":"current problems 指現在存在的困難，而不只是過去或未來的問題。"},{"en":"A school’s current problems may include staff shortages and ageing computers.","zh":"學校的當前問題可能包括員工短缺和電腦老化。"},{"en":"Identifying current problems helps leaders decide what needs urgent attention.","zh":"識別當前問題幫助領導者決定甚麼需要迫切處理。"},{"en":"This phrase focuses on present difficulties.","zh":"這個短語著重目前困難。"}],"source":"62 - The Brains Business.pdf","sourcePage":21},{"front":"government funders","meaning":"政府資助者","examples":[{"en":"Administrators may argue with government funders.","zh":"行政管理人員可能與政府資助者爭論。"},{"en":"Government funders are public officials or bodies that provide money to support institutions or projects.","zh":"government funders 指提供金錢支持機構或項目的公共官員或機構。"},{"en":"A school may need approval from government funders before building a new sports hall.","zh":"學校興建新體育館前，可能需要政府資助者批准。"},{"en":"Funders can influence priorities because they control part of the budget.","zh":"資助者可以影響優先事項，因為他們控制部分預算。"},{"en":"This phrase identifies the public source of money.","zh":"這個短語指出公共資金來源。"}],"source":"62 - The Brains Business.pdf","sourcePage":21},{"front":"possible solutions","meaning":"可能的解決方法","examples":[{"en":"The passage discusses possible solutions proposed by different groups.","zh":"文章討論不同群體提出的可能解決方法。"},{"en":"Possible solutions are ideas or actions that may help solve a problem.","zh":"possible solutions 指可能幫助解決問題的想法或行動。"},{"en":"A class with noise problems may discuss possible solutions such as seating plans or group rules.","zh":"有噪音問題的班級可能討論座位安排或小組規則等可能解決方法。"},{"en":"Different solutions may solve different parts of a problem.","zh":"不同解決方法可能處理問題的不同部分。"},{"en":"This phrase suggests options, not guaranteed answers.","zh":"這個短語表示選項，而不是保證有效的答案。"}],"source":"62 - The Brains Business.pdf","sourcePage":21},{"front":"put forward by","meaning":"由……提出","examples":[{"en":"Possible solutions are put forward by reformists and conservatives.","zh":"可能的解決方法由改革派和保守派提出。"},{"en":"To be put forward by someone means to be proposed or suggested by that person or group.","zh":"be put forward by someone 指由某人或某群體提出或建議。"},{"en":"A new homework policy may be put forward by teachers after student complaints.","zh":"學生投訴後，新功課政策可能由老師提出。"},{"en":"Ideas put forward for reform still need testing and discussion.","zh":"為改革提出的想法仍需要測試和討論。"},{"en":"This phrase identifies who proposed an idea.","zh":"這個短語指出由誰提出某想法。"}],"source":"62 - The Brains Business.pdf","sourcePage":21},{"front":"reformists and conservatives","meaning":"改革派與保守派","examples":[{"en":"Reformists and conservatives suggest very different solutions.","zh":"改革派與保守派提出非常不同的解決方法。"},{"en":"Reformists and conservatives are people who favour change and people who prefer preserving older ways.","zh":"reformists and conservatives 指支持改變的人，以及偏好保留舊方式的人。"},{"en":"In a school debate, reformists may support online exams while conservatives defend handwritten exams.","zh":"在學校辯論中，改革派可能支持網上考試，而保守派維護手寫考試。"},{"en":"These groups often disagree because they value progress and tradition differently.","zh":"這些群體常有分歧，因為他們對進步和傳統的重視不同。"},{"en":"This phrase contrasts two political or cultural positions.","zh":"這個短語對比兩種政治或文化立場。"}],"source":"62 - The Brains Business.pdf","sourcePage":21},{"front":"greater use of technology","meaning":"更廣泛使用科技","examples":[{"en":"Some reformists support greater use of technology in higher education.","zh":"有些改革派支持在高等教育中更廣泛使用科技。"},{"en":"Greater use of technology means using more digital tools, systems, or machines than before.","zh":"greater use of technology 指比以前使用更多數碼工具、系統或機器。"},{"en":"A school makes greater use of technology when it adds online homework and digital feedback.","zh":"學校加入網上功課和數碼回饋，就是更廣泛使用科技。"},{"en":"More technology can improve access, but it may also require training and equipment.","zh":"更多科技可以改善可及性，但也可能需要培訓和設備。"},{"en":"This phrase describes increased reliance on technological tools.","zh":"這個短語描述對科技工具的使用增加。"}],"source":"62 - The Brains Business.pdf","sourcePage":21},{"front":"management gurus","meaning":"管理大師","examples":[{"en":"Management gurus sometimes predict major changes in universities.","zh":"管理大師有時預測大學會有重大變化。"},{"en":"Management gurus are well-known experts who give advice about running organisations.","zh":"management gurus 指提供組織管理建議的知名專家。"},{"en":"A business leader may read books by management gurus to improve strategy.","zh":"商業領袖可能閱讀管理大師的書來改善策略。"},{"en":"Their predictions can influence managers, but they may also be too dramatic.","zh":"他們的預測可以影響管理者，但也可能過分戲劇化。"},{"en":"This phrase describes famous advisory figures in management.","zh":"這個短語描述管理領域中的知名顧問人物。"}],"source":"62 - The Brains Business.pdf","sourcePage":21},{"front":"teach fewer students","meaning":"教授較少學生","examples":[{"en":"Some conservatives may prefer universities to teach fewer students.","zh":"有些保守派可能偏好大學教授較少學生。"},{"en":"To teach fewer students means to educate a smaller number of learners.","zh":"teach fewer students 指教育較少數量的學習者。"},{"en":"A school may teach fewer students in each class to give more individual attention.","zh":"學校可能每班教授較少學生，以提供更多個別關注。"},{"en":"Teaching fewer students can improve support, but it may reduce access to education.","zh":"教授較少學生可以改善支援，但可能減少接受教育的機會。"},{"en":"This phrase contrasts quality-focused selectiveness with wider participation.","zh":"這個短語把重視質素的選擇性與更廣泛參與作對比。"}],"source":"62 - The Brains Business.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 63":[{"front":"fertility bust","meaning":"生育率暴跌；生育低迷","examples":[{"en":"The passage discusses the possible causes and effects of a fertility bust in Europe.","zh":"文章討論歐洲生育率暴跌的可能原因和影響。"},{"en":"A fertility bust is a sharp or serious fall in the number of babies being born.","zh":"fertility bust 指嬰兒出生數量急劇或嚴重下降。"},{"en":"A country may face a fertility bust when many young adults delay marriage and parenthood.","zh":"當許多年輕成年人推遲結婚和生育，一個國家可能面對生育率暴跌。"},{"en":"A fertility bust can lead to ageing populations and pressure on pension systems.","zh":"生育率暴跌可以導致人口老化，並對退休金制度造成壓力。"},{"en":"The phrase is usually used for a long-term demographic problem, not one quiet year.","zh":"這個短語通常用於長期人口問題，而不是某一年出生率較低。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":1},{"front":"falling populations","meaning":"人口下降","examples":[{"en":"Falling populations are often regarded calmly by ordinary people.","zh":"人口下降常被普通人平靜看待。"},{"en":"Falling populations are populations that are decreasing over time.","zh":"falling populations 指隨時間減少的人口。"},{"en":"A village may have a falling population if young people leave for city jobs.","zh":"如果年輕人離開村莊到城市工作，村莊可能出現人口下降。"},{"en":"Falling populations can mean fewer workers, fewer students, and more elderly residents.","zh":"人口下降可能代表勞動力減少、學生減少，以及長者比例上升。"},{"en":"The phrase describes demographic decline, not just people moving house temporarily.","zh":"這個短語描述人口結構下降，而不是人們暫時搬屋。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":1},{"front":"the despair of","meaning":"令……絕望的事","examples":[{"en":"Falling populations are the despair of state pension systems.","zh":"人口下降是令國家退休金制度絕望的事。"},{"en":"The despair of someone means something causes serious worry, difficulty, or hopelessness for them.","zh":"the despair of someone 指某事令某人嚴重擔心、困難重重或感到無望。"},{"en":"Late homework can be the despair of teachers who try to mark work on time.","zh":"遲交功課可能令想準時批改的老師非常頭痛。"},{"en":"If fewer workers pay taxes, pension systems may struggle to support retirees.","zh":"如果納稅工人減少，退休金制度可能難以支援退休人士。"},{"en":"The phrase stresses that a problem is especially troubling for a particular group.","zh":"這個短語強調某問題對特定群體尤其令人困擾。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":1},{"front":"state pension systems","meaning":"國家退休金制度","examples":[{"en":"Falling populations can create problems for state pension systems.","zh":"人口下降可以為國家退休金制度造成問題。"},{"en":"State pension systems are government-run schemes that provide income for retired people.","zh":"state pension systems 指由政府營運、為退休人士提供收入的制度。"},{"en":"Workers usually help fund state pension systems through taxes or social contributions.","zh":"工人通常透過稅收或社會供款支撐國家退休金制度。"},{"en":"If there are fewer young workers, the system may have less money to support older citizens.","zh":"如果年輕工人減少，制度可能有較少資金支援長者。"},{"en":"The phrase refers to public retirement support, not private savings.","zh":"這個短語指公共退休保障，而不是私人儲蓄。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":1},{"front":"be regarded with calmness","meaning":"被平靜看待","examples":[{"en":"Falling populations are often regarded with calmness by ordinary people.","zh":"人口下降常被普通人平靜看待。"},{"en":"To be regarded with calmness means to be viewed without panic or strong worry.","zh":"be regarded with calmness 指被人不帶恐慌或強烈憂慮地看待。"},{"en":"A small drop in class size may be regarded with calmness if the school still runs well.","zh":"如果學校仍運作良好，班級人數小幅下降可能被平靜看待。"},{"en":"People may stay calm about population decline if they think fewer people means less crowding.","zh":"如果人們認為人口較少代表較少擠迫，他們可能平靜看待人口下降。"},{"en":"The phrase describes attitude, not whether the issue is actually harmless.","zh":"這個短語描述態度，而不是說問題真的無害。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":1},{"front":"secret satisfaction","meaning":"暗自滿意","examples":[{"en":"Some people may even feel a secret satisfaction about falling populations.","zh":"有些人甚至可能對人口下降感到暗自滿意。"},{"en":"Secret satisfaction is a quiet private pleasure that people may not openly admit.","zh":"secret satisfaction 指人們未必公開承認的私下愉悅。"},{"en":"A student may feel secret satisfaction when a difficult test is postponed.","zh":"當困難測驗延期，學生可能暗自滿意。"},{"en":"People may feel secretly pleased if fewer people seem to mean quieter cities or cheaper housing.","zh":"如果人口較少看似代表城市較安靜或住屋較便宜，人們可能暗自高興。"},{"en":"The phrase suggests a feeling that may be slightly selfish or socially awkward to express.","zh":"這個短語暗示一種可能略帶自私或不便公開表達的感受。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":1},{"front":"ordinary people","meaning":"一般人；普通人","examples":[{"en":"Ordinary people may not worry about falling populations.","zh":"一般人可能不擔心人口下降。"},{"en":"Ordinary people are normal members of the public, not experts, officials, or specialists.","zh":"ordinary people 指普通公眾，而不是專家、官員或專業人士。"},{"en":"Ordinary people may judge a policy by rent, jobs, schools, and daily costs.","zh":"一般人可能按租金、工作、學校和日常成本判斷政策。"},{"en":"If ordinary people do not feel an immediate problem, they may not worry about long-term statistics.","zh":"如果普通人沒有感到即時問題，他們可能不擔心長期統計數字。"},{"en":"The phrase contrasts everyday citizens with professional policymakers.","zh":"這個短語把日常市民與專業政策制定者作對比。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":1},{"front":"no longer need large families","meaning":"不再需要大家庭","examples":[{"en":"Europeans no longer need large families to gather the harvest.","zh":"歐洲人不再需要大家庭來收割莊稼。"},{"en":"No longer need large families means big households are no longer necessary for work or survival.","zh":"no longer need large families 指大家庭不再是工作或生存所必需。"},{"en":"A farm using machines may no longer need large families to do every task by hand.","zh":"使用機器的農場可能不再需要大家庭用人手完成每項工作。"},{"en":"When work changes, people may choose fewer children because children are no longer needed as labour.","zh":"當工作方式改變，人們可能選擇少生孩子，因為孩子不再被需要作勞動力。"},{"en":"The phrase links family size with changing economic needs.","zh":"這個短語把家庭規模與經濟需要變化連起來。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":1},{"front":"gather the harvest","meaning":"收割莊稼","examples":[{"en":"Large families were once useful for gathering the harvest.","zh":"大家庭過去曾對收割莊稼有用。"},{"en":"To gather the harvest means to collect crops from fields when they are ready.","zh":"gather the harvest 指在作物成熟時從田中收集農作物。"},{"en":"A farming family may gather the harvest together before rain damages the crops.","zh":"農家可能在雨水損害作物前一起收割莊稼。"},{"en":"Harvest work needs labour, so bigger families were once practical in farming societies.","zh":"收割工作需要勞力，所以大家庭在農業社會曾經實用。"},{"en":"The phrase describes agricultural work at the end of a growing season.","zh":"這個短語描述生長季節末段的農業工作。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":1},{"front":"look after parents","meaning":"照顧父母","examples":[{"en":"Large families were once needed to look after parents.","zh":"大家庭過去曾被需要來照顧父母。"},{"en":"To look after parents means to care for one’s mother and father, especially when they are old or ill.","zh":"look after parents 指照顧自己的母親和父親，尤其是當他們年老或患病時。"},{"en":"Adult children may look after parents by helping with meals, medicine, and hospital visits.","zh":"成年子女可能透過協助膳食、藥物和覆診來照顧父母。"},{"en":"In places without strong pensions, families often become the main support for elderly parents.","zh":"在退休保障不完善的地方，家庭常成為年老父母的主要支援。"},{"en":"The phrase focuses on family care and responsibility.","zh":"這個短語重點是家庭照顧和責任。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":1},{"front":"use good fortune to","meaning":"利用好運去……","examples":[{"en":"Europeans have used their good fortune to have fewer children.","zh":"歐洲人利用自己的好運去生較少孩子。"},{"en":"To use good fortune to do something means to use one’s advantages or improved situation for a chosen purpose.","zh":"use good fortune to do something 指利用自己的優勢或改善了的處境去達成某目的。"},{"en":"A student may use good fortune to study abroad if the family can afford it.","zh":"如果家庭負擔得起，學生可能利用好運去海外升學。"},{"en":"When people become richer and safer, they may use that security to choose smaller families.","zh":"當人們變得更富裕和安全，他們可能利用這種安全感選擇較小家庭。"},{"en":"The phrase suggests people are acting from advantage, not desperation.","zh":"這個短語暗示人們基於優勢行動，而不是出於絕望。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":1},{"front":"have fewer children","meaning":"生較少孩子","examples":[{"en":"Many Europeans have chosen to have fewer children.","zh":"許多歐洲人選擇生較少孩子。"},{"en":"To have fewer children means to give birth to or raise a smaller number of children than before or than expected.","zh":"have fewer children 指生育或撫養比以前或預期更少的孩子。"},{"en":"A couple may have fewer children because housing, childcare, and education are expensive.","zh":"夫妻可能因住屋、幼兒照顧和教育昂貴而生較少孩子。"},{"en":"If many families have fewer children, schools may shrink and populations may age.","zh":"如果許多家庭生較少孩子，學校可能縮小，人口可能老化。"},{"en":"The phrase describes family-size choice or demographic change.","zh":"這個短語描述家庭規模選擇或人口變化。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":2},{"front":"make their lives better","meaning":"令生活更好","examples":[{"en":"Some people think fewer children will make their lives better.","zh":"有些人認為較少孩子會令生活更好。"},{"en":"To make their lives better means to improve people’s comfort, freedom, money, or daily happiness.","zh":"make their lives better 指改善人們的舒適、自由、金錢或日常幸福感。"},{"en":"A shorter commute can make workers’ lives better by giving them more family time.","zh":"較短通勤可以給工人更多家庭時間，令生活更好。"},{"en":"Parents may think fewer children allow more money, space, and attention for each child.","zh":"父母可能認為較少孩子能讓每個孩子得到更多金錢、空間和注意。"},{"en":"The phrase focuses on practical improvement in everyday life.","zh":"這個短語重點是日常生活中的實際改善。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":2},{"front":"too crowded as it is","meaning":"本來已經太擠迫","examples":[{"en":"Much of Europe is too crowded as it is.","zh":"歐洲很多地方本來已經太擠迫。"},{"en":"Too crowded as it is means already crowded enough without adding more people or pressure.","zh":"too crowded as it is 指目前已經夠擠迫，不能再增加人或壓力。"},{"en":"A classroom may be too crowded as it is, so adding five more desks would be difficult.","zh":"課室本來已經太擠迫，所以再加五張桌會很困難。"},{"en":"If people feel cities are already crowded, they may see lower population growth as a relief.","zh":"如果人們覺得城市已經擠迫，他們可能把人口增長放慢視為鬆一口氣。"},{"en":"The phrase stresses that the present situation is already full or pressured.","zh":"這個短語強調目前情況已經很滿或有壓力。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":2},{"front":"Is this all that is going on?","meaning":"事情是否就這麼簡單？","examples":[{"en":"The writer asks whether this is all that is going on.","zh":"作者問事情是否就這麼簡單。"},{"en":"Is this all that is going on? asks whether the explanation is complete or whether deeper causes exist.","zh":"Is this all that is going on? 是在問解釋是否完整，還是有更深層原因。"},{"en":"If students keep failing a test, a teacher may ask whether poor revision is all that is going on.","zh":"如果學生不斷測驗不合格，老師可能會問是否只是溫習不足這麼簡單。"},{"en":"The question invites readers to look beyond the simple explanation.","zh":"這個問題邀請讀者看穿簡單解釋。"},{"en":"The phrase signals that the issue may be more complicated than it first appears.","zh":"這個短語表示事情可能比表面更複雜。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":2},{"front":"agonise about","meaning":"為……感到焦慮不安","examples":[{"en":"Germans have been agonising about recent European Union estimates.","zh":"德國人一直為近期歐盟估算感到焦慮不安。"},{"en":"To agonise about something means to worry deeply and painfully about it.","zh":"agonise about something 指為某事深深而痛苦地擔憂。"},{"en":"Parents may agonise about choosing a school if every option has serious drawbacks.","zh":"如果每個學校選項都有嚴重缺點，家長可能為選校焦慮不安。"},{"en":"Alarming statistics can make a society worry about its future.","zh":"令人警惕的統計數字可以令社會擔心未來。"},{"en":"The phrase suggests intense concern, not mild interest.","zh":"這個短語暗示強烈憂慮，而不是輕微興趣。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":2},{"front":"European Union estimates","meaning":"歐盟估算","examples":[{"en":"European Union estimates suggest that many German women may remain childless.","zh":"歐盟估算顯示許多德國女性可能終身無子女。"},{"en":"European Union estimates are approximate figures or forecasts produced by EU sources.","zh":"European Union estimates 指由歐盟來源提出的約略數字或預測。"},{"en":"Governments may use European Union estimates to plan schools, pensions, and healthcare.","zh":"政府可能使用歐盟估算來規劃學校、退休金和醫療。"},{"en":"Estimates can guide debate even when exact figures are unavailable.","zh":"即使精確數字不可得，估算仍可以引導討論。"},{"en":"The phrase refers to official approximate data, not personal opinion.","zh":"這個短語指官方近似數據，而不是個人意見。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":2},{"front":"remain childless","meaning":"保持無子女；終身無子女","examples":[{"en":"Many German women may remain childless.","zh":"許多德國女性可能終身無子女。"},{"en":"To remain childless means to continue through life without having children.","zh":"remain childless 指一生中一直沒有孩子。"},{"en":"A couple may remain childless by choice, because of health problems, or because of delayed plans.","zh":"夫妻可能因選擇、健康問題或計劃延遲而無子女。"},{"en":"If many adults remain childless, the average number of births falls.","zh":"如果許多成年人保持無子女，平均出生數就會下降。"},{"en":"The phrase describes having no children, not having fewer children.","zh":"這個短語描述沒有孩子，而不是孩子較少。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":2},{"front":"the number is a guess","meaning":"這個數字只是估計","examples":[{"en":"The number is a guess because Germany does not collect such figures.","zh":"這個數字只是估計，因為德國不收集這類統計資料。"},{"en":"The number is a guess means the figure is an estimate rather than confirmed data.","zh":"the number is a guess 指該數字是估算，而不是已確認數據。"},{"en":"If a school does not count visitors, the number of parents at open day is only a guess.","zh":"如果學校沒有點算訪客，開放日家長人數就只是估計。"},{"en":"When data are not collected, reports must rely on approximation.","zh":"當資料沒有被收集，報告必須依賴約略估算。"},{"en":"The phrase warns readers not to treat a number as exact.","zh":"這個短語提醒讀者不要把數字視為精確。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":2},{"front":"collect figures","meaning":"收集數字；收集統計資料","examples":[{"en":"Germany does not collect figures like this.","zh":"德國不收集這類統計資料。"},{"en":"To collect figures means to gather numerical data or statistics.","zh":"collect figures 指收集數字資料或統計數據。"},{"en":"A school may collect figures on attendance to see whether lateness is increasing.","zh":"學校可能收集出席數字，以了解遲到是否增加。"},{"en":"Without collected figures, it is harder to compare groups accurately.","zh":"沒有收集統計資料，就較難準確比較群體。"},{"en":"The phrase refers to gathering numbers for analysis.","zh":"這個短語指為分析而收集數字。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":2},{"front":"even if","meaning":"即使","examples":[{"en":"Even if the share is 25 per cent, it is still the highest in Europe.","zh":"即使該比例是百分之二十五，它仍然是歐洲最高。"},{"en":"Even if means although something may be true, the main point still remains.","zh":"even if 指即使某事可能是真的，主要意思仍然成立。"},{"en":"Even if a student gets one answer wrong, the essay can still be excellent.","zh":"即使學生答錯一題，作文仍可以很出色。"},{"en":"The phrase helps show that a conclusion stands despite a possible adjustment.","zh":"這個短語幫助顯示即使有可能修正，結論仍成立。"},{"en":"It introduces a condition that does not change the main argument.","zh":"它引入一個不改變主要論點的條件。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":2},{"front":"by far the highest","meaning":"遠遠是最高的","examples":[{"en":"Germany’s share of childless women is by far the highest in Europe.","zh":"德國無子女女性比例遠遠是歐洲最高。"},{"en":"By far the highest means clearly and greatly higher than all others.","zh":"by far the highest 指明顯而大幅高於所有其他。"},{"en":"In a class, one student may have by far the highest score if she is ten marks ahead of everyone else.","zh":"在班中，如果一名學生比所有人高十分，她可能遠遠是最高分。"},{"en":"A figure that is by far the highest suggests an unusual or extreme case.","zh":"遠遠最高的數字暗示情況異常或極端。"},{"en":"The phrase strongly emphasises a large difference.","zh":"這個短語強烈強調巨大差距。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":2},{"front":"something of an oddity","meaning":"有點異常；頗為特殊","examples":[{"en":"Germany is something of an oddity in this.","zh":"德國在這方面有點異常。"},{"en":"Something of an oddity means rather unusual or different from what is expected.","zh":"something of an oddity 指頗為不尋常或不同於預期。"},{"en":"A student who dislikes holidays may be something of an oddity among classmates.","zh":"不喜歡假期的學生在同學中可能有點異常。"},{"en":"If one country does not follow the regional pattern, it becomes interesting to study.","zh":"如果一個國家不跟隨地區模式，它就變得值得研究。"},{"en":"The phrase is softer than saying completely strange.","zh":"這個短語比完全奇怪語氣較溫和。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":3},{"front":"low fertility","meaning":"低生育率","examples":[{"en":"Germany has experienced low fertility for a long time.","zh":"德國長期經歷低生育率。"},{"en":"Low fertility means women are having relatively few children on average.","zh":"low fertility 指女性平均生育孩子數相對較少。"},{"en":"A country with low fertility may close schools if there are fewer children each year.","zh":"低生育率國家如果每年兒童減少，可能關閉學校。"},{"en":"Low fertility can lead to an older population and a smaller workforce.","zh":"低生育率可以導致人口更老化和勞動力縮小。"},{"en":"The phrase describes birth patterns, not soil quality in this context.","zh":"在這個語境中，這個短語描述出生模式，而不是土壤肥沃度。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":3},{"front":"have their first child late","meaning":"很晚才生第一個孩子","examples":[{"en":"In many low-fertility countries, young women have their first child late.","zh":"在許多低生育率國家，年輕女性很晚才生第一個孩子。"},{"en":"To have their first child late means to become mothers at a later age than earlier generations.","zh":"have their first child late 指比上一代更遲成為母親。"},{"en":"Some women have their first child late because they study longer or build careers first.","zh":"有些女性因為讀書更久或先發展事業，所以很晚才生第一個孩子。"},{"en":"Later first births can leave less time for having a second or third child.","zh":"較遲首次生育可能留下較少時間生第二或第三個孩子。"},{"en":"The phrase focuses on timing of the first birth.","zh":"這個短語重點是首次生育的時間。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":3},{"front":"stop at one","meaning":"只生一個就停止","examples":[{"en":"Some women have their first child late and then stop at one.","zh":"有些女性很晚才生第一個孩子，然後只生一個就停止。"},{"en":"To stop at one means to have only one child and not have any more.","zh":"stop at one 指只生一個孩子，之後不再生。"},{"en":"A couple may stop at one child because childcare costs are too high.","zh":"夫妻可能因幼兒照顧成本太高而只生一個就停止。"},{"en":"If many families stop at one, fertility remains far below replacement level.","zh":"如果許多家庭只生一個，生育率會遠低於人口替代水平。"},{"en":"The phrase describes a final family-size decision.","zh":"這個短語描述最終家庭規模決定。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":3},{"front":"none at all","meaning":"一個也沒有","examples":[{"en":"Many German women have none at all.","zh":"許多德國女性一個孩子也沒有。"},{"en":"None at all means not even one.","zh":"none at all 指連一個也沒有。"},{"en":"A student may have no free periods at all if the timetable is completely full.","zh":"如果時間表完全排滿，學生可能一個空堂也沒有。"},{"en":"In fertility discussions, having none at all means remaining childless.","zh":"在生育討論中，一個也沒有就是無子女。"},{"en":"The phrase strongly emphasises zero.","zh":"這個短語強烈強調零。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":3},{"front":"experience low fertility","meaning":"經歷低生育率","examples":[{"en":"Germany has experienced low fertility for a long time.","zh":"德國長期經歷低生育率。"},{"en":"To experience low fertility means to go through a period when birth rates stay low.","zh":"experience low fertility 指經歷出生率保持低水平的時期。"},{"en":"A country may experience low fertility when housing costs rise and young adults delay family plans.","zh":"當住屋成本上升、年輕成年人推遲家庭計劃，國家可能經歷低生育率。"},{"en":"Long periods of low fertility can change schools, workplaces, and pension systems.","zh":"長期低生育率可以改變學校、工作場所和退休金制度。"},{"en":"The phrase treats low fertility as a social condition a country goes through.","zh":"這個短語把低生育率視為一個國家經歷的社會狀況。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":3},{"front":"for such a long time","meaning":"如此長時間","examples":[{"en":"Germany has had low fertility for such a long time.","zh":"德國低生育率已持續如此長時間。"},{"en":"For such a long time means for an unusually long or important period.","zh":"for such a long time 指持續了異常長或重要的一段時間。"},{"en":"A school that has used the same textbook for such a long time may need an update.","zh":"如果學校使用同一本教科書如此長時間，可能需要更新。"},{"en":"When a problem lasts for a long time, it may become harder to reverse.","zh":"當問題持續很久，可能變得更難逆轉。"},{"en":"The phrase stresses duration and persistence.","zh":"這個短語強調時間長和持續性。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":3},{"front":"demographically polarised","meaning":"人口結構上兩極化","examples":[{"en":"Europe is demographically polarised.","zh":"歐洲在人口結構上兩極化。"},{"en":"Demographically polarised means divided into sharply different population patterns.","zh":"demographically polarised 指在人口模式上分成明顯不同的兩端。"},{"en":"A region may be demographically polarised if some towns are full of young families while others are mostly elderly.","zh":"如果一些城鎮充滿年輕家庭，而另一些主要是長者，該地區可能人口結構兩極化。"},{"en":"Different fertility trends can make one part of Europe age faster than another.","zh":"不同生育趨勢可以令歐洲某些地區比其他地區老化得更快。"},{"en":"The phrase describes a strong population contrast.","zh":"這個短語描述強烈的人口對比。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":3},{"front":"fertility fall early","meaning":"生育率早早下降","examples":[{"en":"Countries in northern and western Europe saw fertility fall early.","zh":"北歐和西歐國家的生育率早早下降。"},{"en":"Fertility fall early means birth rates began declining sooner than in other places.","zh":"fertility fall early 指出生率比其他地方更早開始下降。"},{"en":"A country may see fertility fall early when urban life, education, and contraception spread quickly.","zh":"當城市生活、教育和避孕迅速普及，一個國家可能早早出現生育率下降。"},{"en":"Early decline gives society more time to adjust, but it can still create long-term ageing.","zh":"早期下降給社會更多時間適應，但仍可造成長期老化。"},{"en":"The phrase compares the timing of fertility decline.","zh":"這個短語比較生育率下降的時間。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":3},{"front":"stabilise or rise back towards","meaning":"穩定下來或回升至接近……","examples":[{"en":"Some countries have seen fertility stabilise or rise back towards replacement level.","zh":"一些國家見到生育率穩定下來或回升至接近人口替代水平。"},{"en":"Stabilise or rise back towards means stop falling or increase again in the direction of a target level.","zh":"stabilise or rise back towards 指停止下跌，或再次向某目標水平上升。"},{"en":"A student’s grades may stabilise or rise back towards passing level after regular tutoring.","zh":"學生接受定期補習後，成績可能穩定下來或回升至接近合格水平。"},{"en":"If fertility stops falling, governments may feel less pressure from demographic decline.","zh":"如果生育率停止下跌，政府可能較少承受人口下降壓力。"},{"en":"The phrase describes partial recovery, not necessarily a full return.","zh":"這個短語描述部分恢復，而不一定完全回到原水平。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":3},{"front":"replacement level","meaning":"人口替代水平","examples":[{"en":"Replacement level is about 2.1 births per woman.","zh":"人口替代水平約為每名女性生育2.1個孩子。"},{"en":"Replacement level is the fertility rate needed for a population to replace itself over time.","zh":"replacement level 指人口長期維持自身規模所需的生育率。"},{"en":"If a country stays below replacement level for decades, its population may shrink without immigration.","zh":"如果一個國家數十年低於人口替代水平，沒有移民時人口可能萎縮。"},{"en":"The level is slightly above two because not every child survives to adulthood.","zh":"這個水平略高於二，因為不是每個孩子都能活到成年。"},{"en":"The phrase is a key term in demographic analysis.","zh":"這個短語是人口分析中的關鍵術語。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":3},{"front":"births per woman","meaning":"每名女性生育數","examples":[{"en":"Replacement level is 2.1 births per woman.","zh":"人口替代水平是每名女性生育2.1個孩子。"},{"en":"Births per woman means the average number of children a woman has in a population.","zh":"births per woman 指某人口中女性平均生育孩子數。"},{"en":"A rate of one birth per woman means the next generation will probably be smaller.","zh":"每名女性生育一個孩子的比率，代表下一代很可能較小。"},{"en":"Demographers use births per woman to compare fertility across countries.","zh":"人口學家使用每名女性生育數比較不同國家的生育率。"},{"en":"The phrase gives an average, not the exact number for every woman.","zh":"這個短語提供平均數，而不是每位女性的確切數字。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":4},{"front":"fertility rates","meaning":"生育率","examples":[{"en":"Fertility rates fell much faster in southern and eastern Europe.","zh":"南歐和東歐的生育率下降得快得多。"},{"en":"Fertility rates are measurements of how many children women have on average.","zh":"fertility rates 指女性平均生育多少孩子的量度。"},{"en":"Governments track fertility rates to plan nurseries, schools, and pensions.","zh":"政府追蹤生育率，以規劃幼兒園、學校和退休金。"},{"en":"Falling fertility rates can change a country’s age structure over time.","zh":"生育率下降可以隨時間改變國家的年齡結構。"},{"en":"The phrase is statistical and refers to birth patterns.","zh":"這個短語屬統計用語，指出生模式。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":4},{"front":"below 1.3","meaning":"低於1.3","examples":[{"en":"Some fertility rates fell to below 1.3.","zh":"一些生育率跌至低於1.3。"},{"en":"Below 1.3 means lower than 1.3 births per woman.","zh":"below 1.3 指低於每名女性生育1.3個孩子。"},{"en":"If a class average falls below 50, teachers may review the test difficulty.","zh":"如果班級平均分低於50分，老師可能檢討測驗難度。"},{"en":"Fertility below 1.3 is extremely low and can lead to rapid population ageing.","zh":"低於1.3的生育率極低，可以導致人口快速老化。"},{"en":"The phrase marks a numerical threshold.","zh":"這個短語標示數字門檻。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":4},{"front":"population falls by half","meaning":"人口減半","examples":[{"en":"At that rate, the population falls by half every 45 years.","zh":"按那個比率，人口每45年減半。"},{"en":"Population falls by half means the number of people decreases to 50 percent of the original size.","zh":"population falls by half 指人口數量降至原本的一半。"},{"en":"A village population falls by half if it drops from 2,000 residents to 1,000.","zh":"如果村莊人口由2,000人降至1,000人，就是人口減半。"},{"en":"Such a decline can close schools, reduce local services, and leave more empty homes.","zh":"這種下降可以令學校關閉、本地服務減少，並留下更多空置房屋。"},{"en":"The phrase describes a major demographic shrinkage.","zh":"這個短語描述重大人口萎縮。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":4},{"front":"combine both","meaning":"兼具兩者","examples":[{"en":"Germany combines both demographic patterns.","zh":"德國兼具兩種人口模式。"},{"en":"To combine both means to include two different features, patterns, or qualities at the same time.","zh":"combine both 指同時包含兩種不同特徵、模式或性質。"},{"en":"A school may combine both online lessons and face-to-face tutorials.","zh":"學校可能兼具網上課堂和面授導修。"},{"en":"If a country combines early fertility decline with very low fertility, its case becomes unusual.","zh":"如果一個國家同時有早期生育率下降和極低生育率，其情況就變得不尋常。"},{"en":"The phrase shows that two things are present together.","zh":"這個短語顯示兩件事同時存在。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":4},{"front":"fall below","meaning":"跌穿；降至……以下","examples":[{"en":"Germany’s fertility rate fell below 2 in 1971.","zh":"德國生育率在1971年跌穿2。"},{"en":"To fall below a level means to drop to a point lower than that level.","zh":"fall below a level 指下降至低於某水平。"},{"en":"A student’s attendance may fall below 80 percent after repeated absences.","zh":"學生反覆缺席後，出席率可能跌至百分之八十以下。"},{"en":"When fertility falls below replacement level, a population may eventually shrink.","zh":"當生育率跌穿人口替代水平，人口最終可能萎縮。"},{"en":"The phrase is used for numbers crossing downward past a threshold.","zh":"這個短語用於數字向下越過門檻。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":4},{"front":"remain low","meaning":"維持低水平","examples":[{"en":"Germany’s fertility rate has remained low.","zh":"德國生育率一直維持低水平。"},{"en":"To remain low means to stay at a low level over time.","zh":"remain low 指隨時間保持在低水平。"},{"en":"A shop’s sales may remain low if few customers know it exists.","zh":"如果很少顧客知道商店存在，其銷售可能維持低水平。"},{"en":"When fertility remains low for decades, social expectations may change.","zh":"當生育率數十年維持低水平，社會期望可能改變。"},{"en":"The phrase stresses persistence, not a short drop.","zh":"這個短語強調持續性，而不是短暫下跌。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":4},{"front":"just above","meaning":"僅高於","examples":[{"en":"Germany’s fertility rate is still only just above 1.3.","zh":"德國生育率仍然僅高於1.3。"},{"en":"Just above means only slightly higher than a number or level.","zh":"just above 指只略高於某數字或水平。"},{"en":"A student who scores just above the pass mark has passed, but only narrowly.","zh":"剛高於合格線的學生雖然合格，但只是勉強通過。"},{"en":"A fertility rate just above 1.3 remains very low even if it is not below the line.","zh":"僅高於1.3的生育率仍然非常低，即使沒有低於該線。"},{"en":"The phrase stresses a small margin.","zh":"這個短語強調差距很小。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":4},{"front":"challenge the notion that","meaning":"挑戰……的觀念","examples":[{"en":"Germany’s experience challenges the notion that European fertility will stabilise.","zh":"德國經驗挑戰歐洲生育率會穩定下來的觀念。"},{"en":"To challenge the notion that something is true means to question or weaken that belief.","zh":"challenge the notion that something is true 指質疑或削弱某信念。"},{"en":"A student’s improvement can challenge the notion that weak learners cannot catch up.","zh":"學生的進步可以挑戰弱學生不能追上的觀念。"},{"en":"If one country stays low for decades, it questions the belief that fertility naturally recovers.","zh":"如果一個國家數十年維持低水平，就會質疑生育率自然恢復的信念。"},{"en":"The phrase is used when evidence pushes against an accepted idea.","zh":"這個短語用於證據反駁既有想法時。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":4},{"front":"be likely to stabilise","meaning":"很可能穩定下來","examples":[{"en":"European fertility may not be likely to stabilise at tolerable levels.","zh":"歐洲生育率未必很可能穩定在可接受水平。"},{"en":"To be likely to stabilise means to probably stop changing sharply and settle at a steady level.","zh":"be likely to stabilise 指很可能停止劇烈變化並穩定在某水平。"},{"en":"A student’s grades are likely to stabilise after regular practice and clearer feedback.","zh":"經過定期練習和清晰回饋，學生分數很可能穩定下來。"},{"en":"If social pressures remain strong, fertility may not stabilise quickly.","zh":"如果社會壓力仍然強烈，生育率未必會很快穩定。"},{"en":"The phrase expresses probability, not certainty.","zh":"這個短語表達可能性，而不是確定性。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":4},{"front":"tolerable levels","meaning":"可接受的水平","examples":[{"en":"Some people expect fertility to stabilise at tolerable levels.","zh":"有些人預期生育率會穩定在可接受水平。"},{"en":"Tolerable levels are levels that are low or imperfect but still acceptable or manageable.","zh":"tolerable levels 指雖然偏低或不完美，但仍可接受或可處理的水平。"},{"en":"A school may accept tolerable noise levels during lunch, but not during exams.","zh":"學校可能接受午餐時段的可接受噪音水平，但考試時不行。"},{"en":"If fertility stays below tolerable levels, governments may face long-term demographic stress.","zh":"如果生育率保持低於可接受水平，政府可能面對長期人口壓力。"},{"en":"The phrase suggests something is not ideal but can be handled.","zh":"這個短語暗示某事不理想，但仍可處理。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":4},{"front":"raise questions about","meaning":"引發關於……的疑問","examples":[{"en":"Germany’s case raises questions about low birth rates elsewhere.","zh":"德國個案引發關於其他地方低出生率的疑問。"},{"en":"To raise questions about something means to make people wonder, doubt, or investigate it.","zh":"raise questions about something 指令人對某事產生疑問、懷疑或進一步調查。"},{"en":"A sudden fall in exam results may raise questions about teaching methods.","zh":"考試成績突然下降可能引發關於教學方法的疑問。"},{"en":"One unusual case can make experts rethink assumptions about similar places.","zh":"一個不尋常個案可以令專家重新思考相似地方的假設。"},{"en":"The phrase signals that an issue needs further thought.","zh":"這個短語表示議題需要進一步思考。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":5},{"front":"low birth rates","meaning":"低出生率","examples":[{"en":"The passage discusses whether low birth rates are temporary.","zh":"文章討論低出生率是否暫時。"},{"en":"Low birth rates mean relatively few babies are born compared with the population size.","zh":"low birth rates 指相對人口規模而言，出生嬰兒數較少。"},{"en":"A city with low birth rates may need fewer kindergartens in the future.","zh":"低出生率城市未來可能需要較少幼稚園。"},{"en":"Low birth rates can make the working-age population smaller over time.","zh":"低出生率可以隨時間令工作年齡人口縮小。"},{"en":"The phrase focuses on births, not deaths or migration.","zh":"這個短語重點是出生，而不是死亡或移民。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":5},{"front":"as some have argued","meaning":"正如一些人所主張","examples":[{"en":"The low birth rates may not be temporary, as some have argued.","zh":"低出生率未必是暫時的，正如一些人所主張。"},{"en":"As some have argued means according to what some people have claimed or reasoned.","zh":"as some have argued 指根據一些人的聲稱或推論。"},{"en":"Homework may not always improve learning, as some have argued.","zh":"功課未必總能改善學習，正如一些人所主張。"},{"en":"The phrase introduces a view while keeping some distance from it.","zh":"這個短語引入一種觀點，同時與它保持一定距離。"},{"en":"It is useful when reporting a debated opinion.","zh":"它適合用於報告有爭議的意見。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":5},{"front":"merely temporary","meaning":"只是暫時的","examples":[{"en":"Some people argue that low birth rates are merely temporary.","zh":"有些人認為低出生率只是暫時的。"},{"en":"Merely temporary means only lasting for a short time, not permanent.","zh":"merely temporary 指只持續短時間，而非永久。"},{"en":"A student’s poor score may be merely temporary if it comes from illness before the test.","zh":"如果學生低分是因考試前生病造成，可能只是暫時的。"},{"en":"If low fertility is not temporary, societies need long-term solutions.","zh":"如果低生育率不是暫時的，社會就需要長期解決方法。"},{"en":"The phrase reduces the seriousness of a problem by suggesting it will pass.","zh":"這個短語透過暗示問題會過去，降低其嚴重性。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":5},{"front":"list of explanations","meaning":"一系列解釋","examples":[{"en":"The list of explanations for Germany’s low fertility is long.","zh":"對德國低生育率的一系列解釋很長。"},{"en":"A list of explanations is a set of possible reasons for something.","zh":"list of explanations 指某事的一組可能原因。"},{"en":"A teacher may make a list of explanations for why students are late.","zh":"老師可能列出一系列解釋，說明學生為何遲到。"},{"en":"When many explanations exist, a problem is probably caused by several factors.","zh":"當存在許多解釋，問題很可能由多個因素造成。"},{"en":"The phrase introduces multiple possible causes.","zh":"這個短語引入多個可能原因。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":5},{"front":"fertility has not rebounded","meaning":"生育率尚未回升","examples":[{"en":"German fertility has not rebounded.","zh":"德國生育率尚未回升。"},{"en":"Fertility has not rebounded means birth rates have not risen again after falling.","zh":"fertility has not rebounded 指出生率下跌後沒有再次上升。"},{"en":"A shop’s sales have not rebounded if customers do not return after a bad month.","zh":"如果商店在差劣月份後顧客沒有回來，其銷售就尚未回升。"},{"en":"If fertility does not rebound, temporary explanations become less convincing.","zh":"如果生育率沒有回升，暫時性解釋就較不令人信服。"},{"en":"The phrase describes a missing recovery.","zh":"這個短語描述缺乏恢復。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":5},{"front":"demographer","meaning":"人口學家","examples":[{"en":"Michael Teitelbaum is a demographer at the Sloan Foundation.","zh":"Michael Teitelbaum 是 Sloan Foundation 的人口學家。"},{"en":"A demographer is a specialist who studies populations, births, deaths, migration, and age structure.","zh":"demographer 指研究人口、出生、死亡、移民和年齡結構的專家。"},{"en":"A demographer may help a government predict how many schools or hospitals will be needed.","zh":"人口學家可能幫助政府預測需要多少學校或醫院。"},{"en":"Demographers use statistics to understand how societies change over time.","zh":"人口學家使用統計數字理解社會如何隨時間改變。"},{"en":"The word refers to a population expert.","zh":"這個詞指人口專家。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":5},{"front":"tick them off","meaning":"逐一列出","examples":[{"en":"Michael Teitelbaum ticks off several explanations for low fertility.","zh":"Michael Teitelbaum 逐一列出低生育率的幾個解釋。"},{"en":"To tick them off means to list items one by one.","zh":"tick them off 指逐項列出。"},{"en":"A teacher may tick off homework tasks before students leave the classroom.","zh":"老師可能在學生離開課室前逐一列出功課任務。"},{"en":"Listing reasons one by one helps readers see that a problem has many possible causes.","zh":"逐一列出原因有助讀者看見問題有許多可能成因。"},{"en":"The phrase here means enumerate, not scold.","zh":"這裡的短語意思是列舉，而不是責罵。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":5},{"front":"poor childcare","meaning":"欠佳的幼兒照顧服務","examples":[{"en":"Poor childcare may help explain Germany’s low fertility.","zh":"欠佳的幼兒照顧服務可能有助解釋德國低生育率。"},{"en":"Poor childcare means childcare services are limited, expensive, inconvenient, or low in quality.","zh":"poor childcare 指幼兒照顧服務有限、昂貴、不方便或質素低。"},{"en":"Parents may delay having children if nursery places are hard to find.","zh":"如果幼兒園名額難找，父母可能推遲生孩子。"},{"en":"Weak childcare support can make it difficult to combine work and parenting.","zh":"薄弱幼兒照顧支援可以令人難以兼顧工作和育兒。"},{"en":"The phrase refers to the care system for young children.","zh":"這個短語指年幼兒童的照顧制度。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":5},{"front":"unusually extended higher education","meaning":"異常漫長的高等教育","examples":[{"en":"Unusually extended higher education may delay family formation.","zh":"異常漫長的高等教育可能推遲組織家庭。"},{"en":"Unusually extended higher education means university or advanced study lasts longer than usual.","zh":"unusually extended higher education 指大學或高階學習比平常持續更久。"},{"en":"If students spend many years earning degrees, they may start full-time work later.","zh":"如果學生花很多年取得學位，他們可能較遲開始全職工作。"},{"en":"Longer education can delay income, independence, marriage, and childbirth.","zh":"較長教育可以推遲收入、獨立、結婚和生育。"},{"en":"The phrase links long study periods with later adult milestones.","zh":"這個短語把漫長學習期與較遲成年里程碑連起來。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":5},{"front":"inflexible labour laws","meaning":"缺乏彈性的勞工法例","examples":[{"en":"Inflexible labour laws may contribute to low fertility.","zh":"缺乏彈性的勞工法例可能導致低生育率。"},{"en":"Inflexible labour laws are work rules that make it hard for employers and employees to adjust hours, roles, or contracts.","zh":"inflexible labour laws 指令僱主和僱員難以調整工時、角色或合約的工作規則。"},{"en":"Parents may struggle if labour laws or workplace rules make part-time work difficult.","zh":"如果勞工法例或職場規則令兼職工作困難，父母可能感到吃力。"},{"en":"If jobs cannot adapt to family needs, adults may postpone having children.","zh":"如果工作不能配合家庭需要，成年人可能推遲生孩子。"},{"en":"The phrase connects employment rules with family decisions.","zh":"這個短語把就業規則與家庭決定連起來。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":5},{"front":"high youth unemployment","meaning":"高青年失業率","examples":[{"en":"High youth unemployment is one possible explanation.","zh":"高青年失業率是一個可能解釋。"},{"en":"High youth unemployment means many young adults cannot find jobs.","zh":"high youth unemployment 指許多年輕成年人找不到工作。"},{"en":"Young people without stable work may delay moving out, marrying, or having children.","zh":"沒有穩定工作的年輕人可能推遲搬出去住、結婚或生孩子。"},{"en":"Job insecurity can reduce confidence about starting a family.","zh":"就業不穩可以降低人們組織家庭的信心。"},{"en":"The phrase refers to employment problems among younger adults.","zh":"這個短語指年輕成年人中的就業問題。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":6},{"front":"non-economic or cultural factors","meaning":"非經濟或文化因素","examples":[{"en":"Non-economic or cultural factors may also affect fertility.","zh":"非經濟或文化因素也可能影響生育率。"},{"en":"Non-economic or cultural factors are causes linked to values, beliefs, habits, or social expectations rather than money alone.","zh":"non-economic or cultural factors 指與價值觀、信念、習慣或社會期望有關，而不只是金錢的原因。"},{"en":"A couple may avoid children because their friends also prefer child-free lives.","zh":"夫妻可能因朋友也偏好無子女生活而避免生孩子。"},{"en":"Even when jobs and income improve, culture may still shape family size.","zh":"即使工作和收入改善，文化仍可能塑造家庭規模。"},{"en":"The phrase reminds readers that behaviour is not driven only by economics.","zh":"這個短語提醒讀者，行為不只由經濟推動。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":6},{"front":"a model couple","meaning":"模範夫婦","examples":[{"en":"Harm and Dorte Peters are described as a model couple.","zh":"Harm 和 Dorte Peters 被描述為一對模範夫婦。"},{"en":"A model couple is a pair presented as a typical or ideal example of a certain lifestyle.","zh":"model couple 指被呈現為某種生活方式的典型或理想例子的伴侶。"},{"en":"A magazine may call two successful professionals a model couple if they seem happy and organised.","zh":"如果兩位成功專業人士看似幸福又有條理，雜誌可能稱他們為模範夫婦。"},{"en":"Using a model couple helps writers show a wider social trend through one example.","zh":"使用模範夫婦作例子，可以幫助作者透過一個個案展示更廣泛社會趨勢。"},{"en":"The phrase can be admiring, ironic, or illustrative depending on context.","zh":"這個短語可按語境帶欣賞、諷刺或舉例意味。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":6},{"front":"disport themselves","meaning":"嬉遊；消遣","examples":[{"en":"The couple disport themselves on the beaches of Asia.","zh":"這對夫婦在亞洲海灘嬉遊消遣。"},{"en":"To disport themselves means to enjoy themselves in a playful or leisurely way.","zh":"disport themselves 指以玩樂或悠閒方式享受自己。"},{"en":"Holidaymakers may disport themselves by swimming, sunbathing, and taking photos.","zh":"度假者可能透過游泳、曬太陽和拍照來嬉遊消遣。"},{"en":"The phrase suggests pleasure and leisure rather than duty or responsibility.","zh":"這個短語暗示享樂和休閒，而不是義務或責任。"},{"en":"It is literary or formal, so it sounds more colourful than simply enjoy themselves.","zh":"它較文學或正式，比 simply enjoy themselves 更生動。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":6},{"front":"rather than","meaning":"而不是","examples":[{"en":"They travel rather than invest time in bringing up a baby.","zh":"他們選擇旅行，而不是投入時間撫養嬰兒。"},{"en":"Rather than means instead of and shows a contrast between two choices.","zh":"rather than 指而不是，用來對比兩個選擇。"},{"en":"A student may revise regularly rather than wait until the night before the exam.","zh":"學生可能定期溫習，而不是等到考試前一晚才開始。"},{"en":"The phrase helps show what people choose and what they avoid.","zh":"這個短語幫助顯示人們選擇甚麼和避免甚麼。"},{"en":"It is useful for explaining trade-offs.","zh":"它適合用於解釋取捨。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":6},{"front":"invest time and trouble in","meaning":"投入時間和心力於……","examples":[{"en":"They do not invest time and trouble in bringing up a baby.","zh":"他們不把時間和心力投入撫養嬰兒。"},{"en":"To invest time and trouble in something means to spend effort, attention, and inconvenience on it.","zh":"invest time and trouble in something 指為某事投入努力、注意力和不便。"},{"en":"A teacher invests time and trouble in weaker students by giving extra feedback.","zh":"老師透過提供額外回饋，把時間和心力投入較弱學生身上。"},{"en":"Raising a child requires daily effort, so some adults may choose other priorities.","zh":"撫養孩子需要每日努力，所以一些成年人可能選擇其他優先事項。"},{"en":"The phrase stresses commitment, not only money.","zh":"這個短語強調投入，而不只是金錢。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":6},{"front":"bringing up a baby","meaning":"撫養嬰兒","examples":[{"en":"The couple avoid bringing up a baby.","zh":"這對夫婦避免撫養嬰兒。"},{"en":"Bringing up a baby means raising and caring for a baby as it grows.","zh":"bringing up a baby 指在嬰兒成長過程中撫養和照顧他。"},{"en":"Parents bringing up a baby must feed, clean, comfort, and protect the child every day.","zh":"撫養嬰兒的父母每天必須餵食、清潔、安慰和保護孩子。"},{"en":"The work can affect sleep, money, travel, and career plans.","zh":"這項工作可以影響睡眠、金錢、旅行和事業計劃。"},{"en":"The phrase focuses on the responsibility of early child-rearing.","zh":"這個短語重點是早期育兒責任。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":6},{"front":"be subtitled","meaning":"副題為","examples":[{"en":"The novel is subtitled “The Germans Are Dying Out.”","zh":"該小說副題為「德國人正在消亡」。"},{"en":"To be subtitled means to have a secondary title that adds explanation or emphasis.","zh":"be subtitled 指有一個補充說明或強調意思的副標題。"},{"en":"A book may be subtitled “A Guide for Busy Parents” to show its purpose.","zh":"一本書可能副題為「忙碌父母指南」，以顯示其目的。"},{"en":"A subtitle can frame how readers understand the main title.","zh":"副題可以塑造讀者如何理解主標題。"},{"en":"The phrase refers to naming, not translation captions here.","zh":"這裡的短語指命名，而不是字幕翻譯。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":6},{"front":"die out","meaning":"逐漸消亡","examples":[{"en":"The subtitle suggests that Germans are dying out.","zh":"副題暗示德國人正在逐漸消亡。"},{"en":"To die out means to gradually disappear or cease to exist.","zh":"die out 指逐漸消失或不再存在。"},{"en":"A local tradition may die out if young people stop practising it.","zh":"如果年輕人停止實踐，本地傳統可能逐漸消亡。"},{"en":"If birth rates remain very low, a population may shrink over generations.","zh":"如果出生率長期很低，人口可能經過幾代後萎縮。"},{"en":"The phrase sounds dramatic and often refers to long-term disappearance.","zh":"這個短語語氣較戲劇化，常指長期消失。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":6},{"front":"with the exception of","meaning":"除了……之外","examples":[{"en":"With the exception of the cultural factor, these features are not unique to Germany.","zh":"除了文化因素之外，這些特徵並非德國獨有。"},{"en":"With the exception of means except for one thing or person.","zh":"with the exception of 指除了某一事物或某人之外。"},{"en":"With the exception of science, all classes were moved online during the renovation.","zh":"除了科學課之外，所有課堂在裝修期間都轉為網上進行。"},{"en":"The phrase separates one case from a general statement.","zh":"這個短語把一個個案與一般陳述分開。"},{"en":"It is a formal way to say except for.","zh":"它是 except for 的正式說法。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":6},{"front":"be peculiar to","meaning":"是……所獨有","examples":[{"en":"These features are not peculiar to Germany.","zh":"這些特徵並非德國所獨有。"},{"en":"To be peculiar to a place means to be special or unique to that place.","zh":"be peculiar to a place 指某事對某地而言特有或獨有。"},{"en":"A school rule may be peculiar to one campus and not used elsewhere.","zh":"某校規可能是某校區所獨有，其他地方不使用。"},{"en":"If a problem is not peculiar to one country, other countries may face it too.","zh":"如果問題並非某一國家獨有，其他國家也可能面對它。"},{"en":"The phrase focuses on uniqueness or special association.","zh":"這個短語重點是獨特性或特殊關聯。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":6},{"front":"social and economic explanations","meaning":"社會和經濟解釋","examples":[{"en":"Social and economic explanations may account for persistent low fertility.","zh":"社會和經濟解釋可能說明持續低生育率的原因。"},{"en":"Social and economic explanations are reasons connected with society, work, money, housing, or public services.","zh":"social and economic explanations 指與社會、工作、金錢、住屋或公共服務相關的原因。"},{"en":"High rent and weak childcare are social and economic explanations for delaying children.","zh":"高租金和薄弱幼兒照顧是推遲生育的社會和經濟解釋。"},{"en":"These explanations show that personal choices are shaped by outside conditions.","zh":"這些解釋顯示個人選擇受外在條件塑造。"},{"en":"The phrase contrasts practical social causes with purely personal preference.","zh":"這個短語把實際社會原因與純個人偏好作對比。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":7},{"front":"account for","meaning":"解釋；說明……的原因","examples":[{"en":"These explanations may account for persistent low fertility.","zh":"這些解釋可能說明持續低生育率的原因。"},{"en":"To account for something means to explain why it happened or why it exists.","zh":"account for something 指解釋某事為何發生或存在。"},{"en":"A teacher may account for low attendance by noting a flu outbreak.","zh":"老師可能用流感爆發來解釋低出席率。"},{"en":"A strong explanation should account for both the timing and persistence of a problem.","zh":"強有力解釋應能說明問題的時間點和持續性。"},{"en":"The phrase focuses on explaining causes.","zh":"這個短語重點是解釋原因。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":7},{"front":"persistent low fertility","meaning":"持續低生育率","examples":[{"en":"Social and economic factors may explain persistent low fertility.","zh":"社會和經濟因素可能解釋持續低生育率。"},{"en":"Persistent low fertility means birth rates stay low for a long time.","zh":"persistent low fertility 指出生率長期保持低水平。"},{"en":"A country with persistent low fertility may see school enrolment fall year after year.","zh":"持續低生育率的國家可能見到學校收生逐年下降。"},{"en":"When low fertility persists, short-term solutions may not be enough.","zh":"當低生育率持續，短期解決方法可能不足夠。"},{"en":"The phrase stresses long-lasting demographic decline.","zh":"這個短語強調長期人口下降。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":7},{"front":"may well produce","meaning":"很可能造成","examples":[{"en":"The same factors may well produce persistence elsewhere.","zh":"相同因素很可能在其他地方造成持續情況。"},{"en":"May well produce means are quite likely to cause or create something.","zh":"may well produce 指相當可能造成或產生某事。"},{"en":"Poor sleep may well produce lower concentration in class.","zh":"睡眠不足很可能造成課堂專注力下降。"},{"en":"If the same pressures exist in other countries, they may also keep fertility low.","zh":"如果相同壓力存在於其他國家，它們也可能令生育率保持低水平。"},{"en":"The phrase expresses a strong possibility, not absolute certainty.","zh":"這個短語表達強烈可能性，而不是絕對確定。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":7},{"front":"the same persistence elsewhere","meaning":"在其他地方出現同樣的持續情況","examples":[{"en":"Similar conditions may produce the same persistence elsewhere.","zh":"相似情況可能在其他地方造成同樣的持續情況。"},{"en":"The same persistence elsewhere means the same long-lasting pattern may appear in other places.","zh":"same persistence elsewhere 指同樣長期持續的模式可能在其他地方出現。"},{"en":"If high rent keeps young people from starting families in one city, the same persistence may appear in another expensive city.","zh":"如果高租金令一個城市的年輕人不敢組織家庭，另一個昂貴城市也可能出現同樣持續情況。"},{"en":"Similar causes can create similar results across countries.","zh":"相似原因可以在不同國家造成相似結果。"},{"en":"The phrase extends one country’s pattern to other contexts.","zh":"這個短語把一個國家的模式延伸到其他語境。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":7},{"front":"reason for hoping otherwise","meaning":"有理由抱有相反希望","examples":[{"en":"There is a reason for hoping otherwise.","zh":"有理由抱有相反希望。"},{"en":"A reason for hoping otherwise is evidence or logic suggesting a better outcome may still happen.","zh":"reason for hoping otherwise 指有證據或道理顯示較好結果仍可能發生。"},{"en":"A weak student’s recent improvement gives the teacher a reason for hoping otherwise.","zh":"較弱學生近期進步，給老師理由抱有相反希望。"},{"en":"Even when a trend looks bad, temporary causes may allow recovery.","zh":"即使趨勢看起來差，暫時原因也可能容許恢復。"},{"en":"The phrase introduces a more optimistic counterpoint.","zh":"這個短語引入較樂觀的相反觀點。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":7},{"front":"initial decline","meaning":"初期下降","examples":[{"en":"The initial decline in southern and eastern Europe was drastic.","zh":"南歐和東歐的初期下降很急劇。"},{"en":"Initial decline means the first stage of a fall or decrease.","zh":"initial decline 指下降或減少的第一階段。"},{"en":"A new café may see an initial decline in customers during renovation work.","zh":"新咖啡店在裝修期間可能出現初期顧客下降。"},{"en":"A sharp initial decline may later stabilise if the causes are temporary.","zh":"如果原因是暫時的，急劇初期下降之後可能穩定。"},{"en":"The phrase focuses on the beginning of a downward trend.","zh":"這個短語重點是下行趨勢的開始。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":7},{"front":"southern and eastern Europe","meaning":"南歐和東歐","examples":[{"en":"The passage compares Germany with southern and eastern Europe.","zh":"文章把德國與南歐和東歐作比較。"},{"en":"Southern and eastern Europe refers to European regions in the south and east of the continent.","zh":"southern and eastern Europe 指歐洲大陸南部和東部地區。"},{"en":"Italy and Spain are often discussed as southern Europe, while Poland and Hungary are often discussed as eastern Europe.","zh":"意大利和西班牙常被視為南歐，而波蘭和匈牙利常被視為東歐。"},{"en":"Comparing regions helps show whether fertility decline follows the same pattern everywhere.","zh":"比較地區有助顯示生育率下降是否在各地遵循同一模式。"},{"en":"The phrase names broad geographical areas, not one single country.","zh":"這個短語指廣泛地理區域，而不是單一國家。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":7},{"front":"drastic","meaning":"急劇的；嚴重的","examples":[{"en":"The initial decline was drastic.","zh":"初期下降是急劇的。"},{"en":"Drastic means very severe, sudden, or extreme.","zh":"drastic 指非常嚴重、突然或極端。"},{"en":"A school may take drastic action if student safety is at risk.","zh":"如果學生安全受威脅，學校可能採取嚴厲行動。"},{"en":"Drastic population change can force governments to rethink long-term plans.","zh":"急劇人口變化可以迫使政府重新思考長期計劃。"},{"en":"The word signals a serious change, not a small adjustment.","zh":"這個詞表示嚴重變化，而不是小調整。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":7},{"front":"may be reversible","meaning":"可能可以逆轉","examples":[{"en":"The decline may be reversible.","zh":"下降可能可以逆轉。"},{"en":"May be reversible means it may be possible to change the trend back.","zh":"may be reversible 指趨勢可能可以被改回。"},{"en":"A student’s bad study habits may be reversible with routine and support.","zh":"學生差劣學習習慣可能可以透過規律和支援逆轉。"},{"en":"If fertility decline was caused by temporary shocks, birth rates may rise again later.","zh":"如果生育率下降由暫時衝擊造成，出生率日後可能再次上升。"},{"en":"The phrase expresses possible recovery.","zh":"這個短語表達可能恢復。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":7},{"front":"the Mediterranean","meaning":"地中海地區","examples":[{"en":"In the Mediterranean, demographic decline had particular social causes.","zh":"在地中海地區，人口下降有特定社會原因。"},{"en":"The Mediterranean refers to countries or regions around the Mediterranean Sea.","zh":"the Mediterranean 指地中海周邊的國家或地區。"},{"en":"Italy, Spain, Greece, and parts of southern France are often linked with the Mediterranean.","zh":"意大利、西班牙、希臘和法國南部部分地區常與地中海地區有關。"},{"en":"Regional culture, religion, and family norms may shape fertility patterns there.","zh":"當地文化、宗教和家庭規範可能塑造生育模式。"},{"en":"The phrase is geographical and cultural, not just about the sea.","zh":"這個短語有地理和文化意思，不只是指海。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":7},{"front":"demographic decline","meaning":"人口下降","examples":[{"en":"Demographic decline was associated with social change.","zh":"人口下降與社會變化有關。"},{"en":"Demographic decline means a fall in population size, birth rates, or population growth.","zh":"demographic decline 指人口規模、出生率或人口增長下降。"},{"en":"A town may face demographic decline if young families move away and few babies are born.","zh":"如果年輕家庭搬走且少有嬰兒出生，城鎮可能面對人口下降。"},{"en":"Decline can affect schools, housing markets, and public services.","zh":"人口下降可以影響學校、住屋市場和公共服務。"},{"en":"The phrase is a formal term for population weakening or shrinking.","zh":"這個短語是描述人口弱化或縮小的正式用語。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":8},{"front":"be associated with","meaning":"與……有關","examples":[{"en":"Demographic decline was associated with freeing young women from old constraints.","zh":"人口下降與年輕女性擺脫舊限制有關。"},{"en":"To be associated with something means to be connected with it, though not always directly caused by it.","zh":"be associated with something 指與某事有聯繫，但不一定直接由它造成。"},{"en":"Poor sleep is associated with lower concentration in many students.","zh":"睡眠不足與許多學生專注力下降有關。"},{"en":"If fertility decline is associated with social freedom, the cause may be cultural as well as economic.","zh":"如果生育率下降與社會自由有關，原因可能既是文化的，也是經濟的。"},{"en":"The phrase shows connection, not always proof of cause.","zh":"這個短語顯示關聯，不一定證明因果。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":8},{"front":"free someone from constraints","meaning":"使某人擺脫限制","examples":[{"en":"Social change freed young women from traditional constraints.","zh":"社會變化使年輕女性擺脫傳統限制。"},{"en":"To free someone from constraints means to remove limits that restricted their choices.","zh":"free someone from constraints 指移除限制某人選擇的束縛。"},{"en":"Scholarships can free students from financial constraints and let them study abroad.","zh":"獎學金可以使學生擺脫財政限制，讓他們海外升學。"},{"en":"When women gain more freedom, they may delay or reduce childbearing by choice.","zh":"當女性獲得更多自由，她們可能自願推遲或減少生育。"},{"en":"The phrase links freedom with the removal of pressure or restriction.","zh":"這個短語把自由與壓力或限制的移除連起來。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":8},{"front":"constraints of traditional Catholicism","meaning":"傳統天主教的限制","examples":[{"en":"Traditional Catholicism placed constraints on young women.","zh":"傳統天主教對年輕女性施加限制。"},{"en":"Constraints of traditional Catholicism are social or religious limits linked to traditional Catholic beliefs and expectations.","zh":"constraints of traditional Catholicism 指與傳統天主教信念和期望有關的社會或宗教限制。"},{"en":"A community may expect early marriage and large families because of religious tradition.","zh":"社區可能因宗教傳統而期望早婚和大家庭。"},{"en":"When these constraints weaken, women may feel freer to choose education, work, or smaller families.","zh":"當這些限制減弱，女性可能更自由地選擇教育、工作或較小家庭。"},{"en":"The phrase refers to social-religious restrictions, not physical barriers.","zh":"這個短語指社會宗教限制，而不是實體障礙。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":8},{"front":"encourage large families","meaning":"鼓勵大家庭","examples":[{"en":"Traditional Catholicism encouraged large families.","zh":"傳統天主教鼓勵大家庭。"},{"en":"To encourage large families means to support or promote having many children.","zh":"encourage large families 指支持或推動人們生育多名孩子。"},{"en":"A government may encourage large families by offering child benefits and housing support.","zh":"政府可能透過兒童津貼和住屋支援鼓勵大家庭。"},{"en":"If religious or social values praise large families, fertility may stay higher.","zh":"如果宗教或社會價值讚揚大家庭，生育率可能保持較高。"},{"en":"The phrase describes pressure or support for more children.","zh":"這個短語描述對更多孩子的壓力或支持。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":8},{"front":"collapse in living standards","meaning":"生活水平崩潰","examples":[{"en":"In eastern Europe, fertility decline was associated with a collapse in living standards.","zh":"在東歐，生育率下降與生活水平崩潰有關。"},{"en":"A collapse in living standards is a sudden serious fall in people’s quality of life.","zh":"collapse in living standards 指人們生活質素突然嚴重下降。"},{"en":"Families may feel a collapse in living standards when jobs vanish and prices rise quickly.","zh":"當工作消失而物價快速上升，家庭可能感到生活水平崩潰。"},{"en":"If people cannot afford secure lives, they may delay or avoid having children.","zh":"如果人們負擔不起穩定生活，他們可能推遲或避免生孩子。"},{"en":"The phrase describes a severe social and economic decline.","zh":"這個短語描述嚴重社會和經濟下降。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":8},{"front":"ending of pro-birth policies","meaning":"鼓勵生育政策的終結","examples":[{"en":"The decline was also linked to the ending of pro-birth policies.","zh":"下降也與鼓勵生育政策的終結有關。"},{"en":"Ending of pro-birth policies means government measures that encouraged childbirth were stopped.","zh":"ending of pro-birth policies 指鼓勵生育的政府措施被停止。"},{"en":"If childcare subsidies end, some families may feel less able to have another child.","zh":"如果幼兒照顧津貼終止，一些家庭可能覺得較難再生一個孩子。"},{"en":"Removing birth-support policies can reduce incentives for larger families.","zh":"移除生育支援政策可以降低大家庭誘因。"},{"en":"The phrase links policy change with fertility decline.","zh":"這個短語把政策改變與生育率下降連起來。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":8},{"front":"pro-birth policies","meaning":"鼓勵生育政策","examples":[{"en":"Eastern Europe once had pro-birth policies.","zh":"東歐過去曾有鼓勵生育政策。"},{"en":"Pro-birth policies are government measures designed to encourage people to have children.","zh":"pro-birth policies 指旨在鼓勵人們生孩子的政府措施。"},{"en":"Paid parental leave and child allowances can be pro-birth policies.","zh":"有薪育兒假和兒童津貼都可以是鼓勵生育政策。"},{"en":"Such policies may reduce the cost or risk of starting a family.","zh":"這類政策可能降低組織家庭的成本或風險。"},{"en":"The phrase refers to state support for childbirth.","zh":"這個短語指國家對生育的支持。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":8},{"front":"in both regions","meaning":"在兩個地區","examples":[{"en":"In both regions, temporary factors may fade.","zh":"在兩個地區，暫時因素可能逐漸消退。"},{"en":"In both regions means in the two areas being discussed.","zh":"in both regions 指在正在討論的兩個地區中。"},{"en":"In both regions of the city, rents rose after the new railway opened.","zh":"新鐵路開通後，城市兩個地區的租金都上升。"},{"en":"Comparing both regions helps show whether the same explanation applies twice.","zh":"比較兩個地區有助顯示同一解釋是否都適用。"},{"en":"The phrase refers back to two previously mentioned places.","zh":"這個短語指回之前提到的兩個地方。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":8},{"front":"temporary factors fade","meaning":"暫時因素逐漸消退","examples":[{"en":"Fertility may rise as temporary factors fade.","zh":"當暫時因素逐漸消退，生育率可能上升。"},{"en":"Temporary factors fade means short-term causes gradually become weaker or disappear.","zh":"temporary factors fade 指短期原因逐漸減弱或消失。"},{"en":"Exam stress may fade after students finish their final paper.","zh":"學生完成最後一科後，考試壓力可能逐漸消退。"},{"en":"If a fertility drop is caused by temporary hardship, births may recover when hardship weakens.","zh":"如果生育率下降由暫時困難造成，當困難減弱，出生數可能恢復。"},{"en":"The phrase suggests a problem may become less powerful over time.","zh":"這個短語暗示問題可能隨時間變得較不強烈。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":8},{"front":"in principle","meaning":"原則上","examples":[{"en":"Fertility rates might, in principle, be expected to rise.","zh":"原則上，生育率可能被預期會上升。"},{"en":"In principle means according to the general idea or theory, before considering practical problems.","zh":"in principle 指根據一般理念或理論，而未考慮實際問題。"},{"en":"In principle, every student can improve with practice, but support and time also matter.","zh":"原則上，每名學生都可以透過練習進步，但支援和時間也重要。"},{"en":"A trend may look reversible in principle but remain difficult in real life.","zh":"某趨勢原則上可能可逆，但現實中仍困難。"},{"en":"The phrase separates theoretical possibility from practical certainty.","zh":"這個短語把理論可能性與實際確定性分開。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":8},{"front":"be expected to rise","meaning":"預期會上升","examples":[{"en":"Fertility rates might be expected to rise.","zh":"生育率可能被預期會上升。"},{"en":"To be expected to rise means people think something will probably increase.","zh":"be expected to rise 指人們認為某事很可能增加。"},{"en":"School enrolment may be expected to rise after new housing is built nearby.","zh":"附近建成新住宅後，學校收生人數可能預期會上升。"},{"en":"If temporary pressures weaken, birth rates may be expected to recover.","zh":"如果暫時壓力減弱，出生率可能被預期恢復。"},{"en":"The phrase expresses prediction based on reasoning.","zh":"這個短語表達基於推理的預測。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":9},{"front":"may already be stabilising","meaning":"可能已經正在穩定","examples":[{"en":"Fertility rates may already be stabilising in Italy and Spain.","zh":"意大利和西班牙的生育率可能已經正在穩定。"},{"en":"May already be stabilising means may have started to stop falling and become steadier.","zh":"may already be stabilising 指可能已經開始停止下跌並變得較穩定。"},{"en":"A student’s grades may already be stabilising after several weeks of regular revision.","zh":"經過數星期定期溫習，學生分數可能已經正在穩定。"},{"en":"Early signs of stability can suggest a decline is slowing down.","zh":"早期穩定跡象可以暗示下降正在放慢。"},{"en":"The phrase expresses cautious optimism about a trend.","zh":"這個短語對趨勢表達謹慎樂觀。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":9},{"front":"reversing these trends","meaning":"逆轉這些趨勢","examples":[{"en":"Germany shows that reversing these trends can be hard.","zh":"德國顯示逆轉這些趨勢可能很困難。"},{"en":"Reversing these trends means changing downward patterns so they move upward again.","zh":"reversing these trends 指把下降模式改變，使其重新向上。"},{"en":"A school may find reversing falling attendance difficult if students have lost motivation.","zh":"如果學生失去動力，學校可能發現逆轉出席率下降很困難。"},{"en":"Once low fertility becomes normal, raising birth rates again may require more than money.","zh":"一旦低生育率成為常態，再提高出生率可能需要的不只是金錢。"},{"en":"The phrase focuses on turning a trend around.","zh":"這個短語重點是扭轉趨勢。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":9},{"front":"not merely fall","meaning":"不只是下降","examples":[{"en":"Fertility rates did not merely fall.","zh":"生育率不只是下降。"},{"en":"Not merely fall means the issue was more than just a simple decline.","zh":"not merely fall 指問題不只是單純下降。"},{"en":"A student’s grades did not merely fall; she also lost confidence and stopped attending class.","zh":"學生成績不只是下降；她也失去信心並停止上課。"},{"en":"Sometimes a fall creates new habits that make recovery harder.","zh":"有時下降會造成新習慣，使恢復更困難。"},{"en":"The phrase signals that the writer will describe an additional problem.","zh":"這個短語表示作者將描述額外問題。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":9},{"front":"go below","meaning":"低於","examples":[{"en":"Fertility rates went below what people said they wanted.","zh":"生育率低於人們聲稱自己想要的數量。"},{"en":"To go below something means to fall lower than that level or amount.","zh":"go below something 指跌至低於某水平或數量。"},{"en":"A student’s score may go below the pass mark if she leaves too many questions blank.","zh":"如果學生留空太多題，分數可能低於合格線。"},{"en":"If actual births go below desired family size, something is preventing people from achieving their plans.","zh":"如果實際出生數低於理想家庭規模，某些因素正在阻礙人們實現計劃。"},{"en":"The phrase marks a downward movement past a reference point.","zh":"這個短語標示向下越過參照點。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":9},{"front":"what people said they wanted","meaning":"人們聲稱自己想要的數量","examples":[{"en":"Fertility fell below what people said they wanted.","zh":"生育率低於人們聲稱自己想要的數量。"},{"en":"What people said they wanted means the number or outcome people reported as their preference.","zh":"what people said they wanted 指人們報稱偏好的數量或結果。"},{"en":"A student may study less than what she said she wanted to do before exams.","zh":"學生考試前實際溫習時間可能少於她聲稱想做的時間。"},{"en":"A gap between stated wishes and real behaviour can reveal hidden barriers.","zh":"聲稱願望與實際行為之間的差距，可以揭示隱藏障礙。"},{"en":"The phrase contrasts declared preference with actual outcome.","zh":"這個短語把表達出的偏好與實際結果作對比。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":9},{"front":"ask Europeans how many children they would like","meaning":"詢問歐洲人想要多少個孩子","examples":[{"en":"Eurobarometer asked Europeans how many children they would like.","zh":"歐洲晴雨表詢問歐洲人想要多少個孩子。"},{"en":"To ask Europeans how many children they would like means to survey people about their ideal family size.","zh":"ask Europeans how many children they would like 指調查人們的理想家庭規模。"},{"en":"A school may ask parents how many activities they would like their children to join.","zh":"學校可能詢問家長希望孩子參加多少活動。"},{"en":"Asking about preferences helps compare desired behaviour with actual behaviour.","zh":"詢問偏好有助比較理想行為與實際行為。"},{"en":"The phrase describes survey research into family ideals.","zh":"這個短語描述關於家庭理想的調查研究。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":9},{"front":"almost everywhere","meaning":"幾乎到處","examples":[{"en":"Almost everywhere, the answer was two.","zh":"幾乎到處，答案都是兩個。"},{"en":"Almost everywhere means in nearly all places.","zh":"almost everywhere 指在幾乎所有地方。"},{"en":"Almost everywhere in the school, students use digital platforms for homework.","zh":"在學校幾乎到處，學生都使用數碼平台交功課。"},{"en":"If an answer is the same almost everywhere, it suggests a widespread social ideal.","zh":"如果某答案幾乎到處相同，它暗示有廣泛社會理想。"},{"en":"The phrase allows a few exceptions while stressing broad agreement.","zh":"這個短語容許少數例外，同時強調廣泛一致。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":9},{"front":"two-child ideal","meaning":"兩孩理想","examples":[{"en":"The traditional two-child ideal persisted.","zh":"傳統兩孩理想持續存在。"},{"en":"The two-child ideal is the belief that having two children is the best or normal family size.","zh":"two-child ideal 指認為生兩個孩子是最佳或正常家庭規模的信念。"},{"en":"Many parents imagine a two-child ideal because it gives each child a sibling without creating a very large family.","zh":"許多父母想像兩孩理想，因為孩子有兄弟姊妹，但家庭又不會太大。"},{"en":"If people still want two children but have one, practical barriers may be involved.","zh":"如果人們仍想要兩個孩子卻只生一個，可能涉及實際障礙。"},{"en":"The phrase refers to a social preference, not an official rule.","zh":"這個短語指社會偏好，而不是官方規則。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":9},{"front":"persist","meaning":"持續存在","examples":[{"en":"The two-child ideal persisted even when people were not achieving it.","zh":"即使人們沒有實現兩孩理想，它仍持續存在。"},{"en":"To persist means to continue existing or happening over time.","zh":"persist 指隨時間繼續存在或發生。"},{"en":"A student’s fear of speaking may persist even after grammar improves.","zh":"即使文法改善，學生對說話的恐懼仍可能持續存在。"},{"en":"When an idea persists, it remains influential despite changing behaviour.","zh":"當一個想法持續存在，即使行為改變，它仍有影響力。"},{"en":"The word stresses continuation.","zh":"這個詞強調延續。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":9},{"front":"old habits of mind","meaning":"舊有思維習慣","examples":[{"en":"The answer may have reflected old habits of mind.","zh":"該答案可能反映舊有思維習慣。"},{"en":"Old habits of mind are long-standing ways of thinking that people repeat without much reflection.","zh":"old habits of mind 指人們長期重複、未必深入反思的思考方式。"},{"en":"A worker may keep using paper forms because of old habits of mind, even when an app is easier.","zh":"即使應用程式更方便，員工可能因舊有思維習慣繼續使用紙表格。"},{"en":"People may say they want two children because that was long seen as normal.","zh":"人們可能說自己想要兩個孩子，因為這長期被視為正常。"},{"en":"The phrase refers to mental patterns inherited from the past.","zh":"這個短語指從過去承襲而來的思維模式。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":9},{"front":"claim to want","meaning":"聲稱想要","examples":[{"en":"People may be having fewer children than they claim to want.","zh":"人們實際生的孩子可能少於他們聲稱想要的數量。"},{"en":"To claim to want something means to say that one wants it.","zh":"claim to want something 指說自己想要某事。"},{"en":"A student may claim to want high marks but still avoid regular practice.","zh":"學生可能聲稱想要高分，但仍避免定期練習。"},{"en":"When action differs from stated desire, hidden costs or pressures may be involved.","zh":"當行動不同於聲稱願望，可能涉及隱藏成本或壓力。"},{"en":"The phrase contrasts what people say with what happens.","zh":"這個短語把人們所說與實際發生作對比。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":10},{"front":"a recent paper suggests","meaning":"一篇近期論文指出","examples":[{"en":"A recent paper suggests how this might come about.","zh":"一篇近期論文指出這可能如何形成。"},{"en":"A recent paper suggests means a newly published study proposes or explains an idea.","zh":"a recent paper suggests 指一篇新近發表的研究提出或解釋某想法。"},{"en":"A recent paper suggests that sleep affects memory more strongly than students expect.","zh":"一篇近期論文指出睡眠對記憶的影響比學生預期更強。"},{"en":"Research papers can offer mechanisms that explain puzzling social trends.","zh":"研究論文可以提供機制，解釋令人困惑的社會趨勢。"},{"en":"The phrase introduces evidence or reasoning from academic work.","zh":"這個短語引入來自學術研究的證據或推理。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":10},{"front":"come about","meaning":"發生；形成","examples":[{"en":"The paper explains how lower fertility might come about.","zh":"該論文解釋較低生育率可能如何形成。"},{"en":"To come about means to happen or develop.","zh":"come about 指發生或形成。"},{"en":"A timetable change may come about after many students complain about early lessons.","zh":"許多學生投訴早課後，時間表改動可能發生。"},{"en":"Understanding how a trend comes about helps people address its causes.","zh":"理解趨勢如何形成，有助人們處理其原因。"},{"en":"The phrase focuses on the process by which something happens.","zh":"這個短語重點是某事發生的過程。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":10},{"front":"postpone their first child","meaning":"推遲生第一個孩子","examples":[{"en":"Women may postpone their first child past their mid-30s.","zh":"女性可能把生第一個孩子推遲到三十五歲左右以後。"},{"en":"To postpone their first child means to delay having a first baby until later.","zh":"postpone their first child 指把第一個孩子的出生推遲到較後時間。"},{"en":"Some couples postpone their first child until they feel financially secure.","zh":"一些夫妻把第一個孩子推遲到自己覺得財政穩定後。"},{"en":"Delaying the first child can reduce the time available for later children.","zh":"推遲第一個孩子可以減少日後再生孩子的時間。"},{"en":"The phrase focuses on delaying the beginning of parenthood.","zh":"這個短語重點是推遲成為父母的開始。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":10},{"front":"past their mid-30s","meaning":"過了三十五歲左右","examples":[{"en":"If women postpone childbirth past their mid-30s, it may be too late to have another child.","zh":"如果女性把生育推遲到過了三十五歲左右，可能太遲而不能再生一個孩子。"},{"en":"Past their mid-30s means older than about 35 or 36 years old.","zh":"past their mid-30s 指年齡超過約35或36歲。"},{"en":"Some workers change career past their mid-30s after gaining enough savings.","zh":"一些工人在三十五歲左右之後，儲夠錢便轉行。"},{"en":"In fertility discussions, age matters because biological time becomes shorter.","zh":"在生育討論中，年齡重要，因為生理時間會變短。"},{"en":"The phrase marks a later stage of adulthood.","zh":"這個短語標示成年較後階段。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":10},{"front":"too late to have a second","meaning":"太遲而不能生第二個","examples":[{"en":"It may be too late to have a second child even if women want one.","zh":"即使女性想要第二個孩子，也可能已太遲而不能生第二個。"},{"en":"Too late to have a second means the chance to have another child may have passed.","zh":"too late to have a second 指再生一個孩子的機會可能已經過去。"},{"en":"A couple may want another baby, but age, health, or time may make it difficult.","zh":"夫妻可能想再生一個嬰兒，但年齡、健康或時間可能令它困難。"},{"en":"Delaying the first birth can accidentally reduce final family size.","zh":"推遲首次生育可以意外降低最終家庭規模。"},{"en":"The phrase shows a gap between desire and biological or practical limits.","zh":"這個短語顯示願望與生理或實際限制之間的差距。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":10},{"front":"average age of first births","meaning":"首次生育平均年齡","examples":[{"en":"The average age of first births in most of Europe is now 30.","zh":"歐洲大部分地區的首次生育平均年齡現在是30歲。"},{"en":"Average age of first births means the typical age at which women have their first child.","zh":"average age of first births 指女性生第一個孩子的典型年齡。"},{"en":"If the average age of first births rises, many parents are starting families later.","zh":"如果首次生育平均年齡上升，許多父母就是較遲組織家庭。"},{"en":"Later first births can affect how many children families eventually have.","zh":"較遲首次生育可以影響家庭最終有多少孩子。"},{"en":"The phrase is a demographic measure of timing.","zh":"這個短語是量度生育時間的人口指標。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":10},{"front":"one child becomes the norm","meaning":"一個孩子成為常態","examples":[{"en":"If everyone behaves similarly, one child becomes the norm.","zh":"如果人人行為相似，一個孩子就成為常態。"},{"en":"One child becomes the norm means having only one child becomes the usual or expected pattern.","zh":"one child becomes the norm 指只生一個孩子變成通常或預期模式。"},{"en":"In a school, bringing lunch from home becomes the norm if most students do it daily.","zh":"如果大多數學生每天自備午餐，帶飯就成為學校常態。"},{"en":"When one-child families become common, people may begin to see larger families as unusual.","zh":"當一孩家庭變得常見，人們可能開始把較大家庭視為不尋常。"},{"en":"The phrase describes a new social standard.","zh":"這個短語描述新的社會標準。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":10},{"front":"by example rather than coercion","meaning":"以榜樣而非強制方式","examples":[{"en":"The passage describes a one-child policy by example rather than coercion.","zh":"文章描述一種以榜樣而非強制方式形成的一孩政策。"},{"en":"By example rather than coercion means people copy what others do instead of being forced by law.","zh":"by example rather than coercion 指人們模仿他人做法，而不是被法律強迫。"},{"en":"Students may start reading more by example rather than coercion when classmates enjoy books openly.","zh":"當同學公開享受閱讀，學生可能以榜樣而非強制方式開始多閱讀。"},{"en":"Social behaviour can spread quietly when people follow visible norms.","zh":"當人們跟隨可見常態，社會行為可以悄悄傳播。"},{"en":"The phrase contrasts imitation with force.","zh":"這個短語把模仿與強制作對比。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":10},{"front":"as it were","meaning":"可以說；可謂","examples":[{"en":"It becomes a one-child policy by example rather than coercion, as it were.","zh":"可以說，它成為一種以榜樣而非強制方式形成的一孩政策。"},{"en":"As it were means so to speak or in a way, often used when a phrase is not literally exact.","zh":"as it were 指可以這樣說，常用於短語並非完全字面準確時。"},{"en":"A teacher may become the class’s coach, as it were, during exam season.","zh":"考試季期間，老師可謂成為班上的教練。"},{"en":"The phrase lets a writer use a comparison while showing it is figurative.","zh":"這個短語讓作者使用比較，同時顯示它是比喻。"},{"en":"It softens a bold or unusual expression.","zh":"它軟化大膽或不尋常的表達。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":10},{"front":"start a family","meaning":"組織家庭；生兒育女","examples":[{"en":"Women may wait to start a family until they are established at work.","zh":"女性可能等到在工作上站穩陣腳才開始組織家庭。"},{"en":"To start a family means to begin having children or building a household with children.","zh":"start a family 指開始生孩子或建立有孩子的家庭。"},{"en":"A couple may wait to start a family until they have stable housing.","zh":"夫妻可能等到有穩定住屋才開始組織家庭。"},{"en":"Work, money, health, and relationships can affect when people start a family.","zh":"工作、金錢、健康和關係都可以影響人們何時生兒育女。"},{"en":"The phrase usually refers to parenthood, not simply getting married.","zh":"這個短語通常指成為父母，而不只是結婚。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":10},{"front":"be established at work","meaning":"在工作上站穩陣腳","examples":[{"en":"Some women wait until they are established at work before having children.","zh":"一些女性等到在工作上站穩陣腳後才生孩子。"},{"en":"To be established at work means to have a stable position, confidence, and progress in one’s career.","zh":"be established at work 指在事業中有穩定位置、信心和進展。"},{"en":"A young lawyer may wait until she is established at work before taking long leave.","zh":"年輕律師可能等到工作上站穩陣腳後才放長假。"},{"en":"Career stability can make people feel more ready for family responsibilities.","zh":"事業穩定可以令人覺得更準備好承擔家庭責任。"},{"en":"The phrase focuses on professional security and status.","zh":"這個短語重點是職業安全感和地位。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":11},{"front":"end up postponing","meaning":"最終推遲","examples":[{"en":"They may end up postponing children longer than planned.","zh":"她們最終可能把生孩子推遲得比計劃更久。"},{"en":"To end up postponing something means to eventually delay it, often more than intended.","zh":"end up postponing something 指最終延遲某事，而且常比原本打算更久。"},{"en":"A student may end up postponing revision because small tasks keep appearing.","zh":"學生可能因小任務不斷出現而最終推遲溫習。"},{"en":"Delays can build up until the original plan becomes impossible.","zh":"延誤可以累積，直到原本計劃變得不可能。"},{"en":"The phrase suggests an unintended final result.","zh":"這個短語暗示非預期的最終結果。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":11},{"front":"might otherwise have chosen","meaning":"本來可能會選擇","examples":[{"en":"Women may postpone children longer than they might otherwise have chosen.","zh":"女性可能把生孩子推遲得比她們本來可能會選擇的時間更久。"},{"en":"Might otherwise have chosen means would perhaps have chosen a different option under other conditions.","zh":"might otherwise have chosen 指在其他條件下或許會選擇不同選項。"},{"en":"A student may take a part-time job longer than she might otherwise have chosen because fees are high.","zh":"由於學費高，學生做兼職的時間可能比她本來會選擇的更長。"},{"en":"External pressure can push people away from their preferred timing.","zh":"外部壓力可以把人推離他們偏好的時間安排。"},{"en":"The phrase compares actual behaviour with a likely alternative choice.","zh":"這個短語比較實際行為與可能的另一選擇。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":11},{"front":"simple matter of choice","meaning":"純粹是選擇問題","examples":[{"en":"Falling birth rates were once seen as a simple matter of choice.","zh":"出生率下降曾被視為純粹是選擇問題。"},{"en":"A simple matter of choice means something is viewed as only depending on personal preference.","zh":"simple matter of choice 指某事被視為只取決於個人偏好。"},{"en":"Choosing a lunch may be a simple matter of choice if all options are affordable.","zh":"如果所有選項都負擔得起，選午餐可能純粹是選擇問題。"},{"en":"Fertility is not always simple choice because money, work, age, and culture shape decisions.","zh":"生育不一定只是簡單選擇，因為金錢、工作、年齡和文化都會塑造決定。"},{"en":"The phrase can be used to question an oversimplified explanation.","zh":"這個短語可用來質疑過度簡化的解釋。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":11},{"front":"fertility may overshoot","meaning":"生育率可能過度下跌","examples":[{"en":"Fertility may overshoot below what people would naturally choose.","zh":"生育率可能過度下跌，低於人們自然會選擇的水平。"},{"en":"Fertility may overshoot means birth rates may fall further than people actually prefer.","zh":"fertility may overshoot 指出生率可能跌得比人們真正偏好更低。"},{"en":"Prices can overshoot when panic makes shoppers pay more than goods are worth.","zh":"當恐慌令購物者支付高於貨品價值的價格，價格就可能過度上升。"},{"en":"If people delay children too long, final fertility may drop below their ideal number.","zh":"如果人們把生孩子推遲太久，最終生育率可能低於理想數量。"},{"en":"The phrase suggests a decline goes beyond the intended or natural level.","zh":"這個短語暗示下降超出本來意圖或自然水平。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":11},{"front":"naturally have chosen","meaning":"自然會選擇","examples":[{"en":"People may have fewer children than they would naturally have chosen.","zh":"人們生的孩子可能少於他們自然會選擇的數量。"},{"en":"Naturally have chosen means would have chosen without extra pressure, obstacles, or distortion.","zh":"naturally have chosen 指在沒有額外壓力、障礙或扭曲下本會選擇。"},{"en":"A student may study a subject she would not naturally have chosen because parents insist.","zh":"學生可能因父母堅持而讀一科她本來不會自然選擇的科目。"},{"en":"If social conditions push people into delay, their final family size may not match their real preference.","zh":"如果社會條件迫使人們推遲，最終家庭規模可能不符合真正偏好。"},{"en":"The phrase separates free preference from pressured outcome.","zh":"這個短語把自由偏好與受壓結果分開。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":11},{"front":"catch up from","meaning":"從……中追趕回來","examples":[{"en":"Some politicians argue that southern Europe will catch up from its fertility decline.","zh":"一些政客認為南歐會從生育率下降中追趕回來。"},{"en":"To catch up from a decline means to recover lost ground after falling behind.","zh":"catch up from a decline 指在落後或下降後追回失地。"},{"en":"A student who missed lessons may catch up from absence by attending extra tutorials.","zh":"缺課學生可能透過額外導修從缺席中追趕回來。"},{"en":"If delayed births happen later, fertility may partly recover.","zh":"如果被推遲的出生之後發生，生育率可能部分恢復。"},{"en":"The phrase suggests making up for a previous fall or delay.","zh":"這個短語暗示彌補之前的下降或延誤。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":11},{"front":"fertility decline","meaning":"生育率下降","examples":[{"en":"Southern Europe may not fully recover from its fertility decline.","zh":"南歐可能無法完全從生育率下降中恢復。"},{"en":"Fertility decline is a fall in the average number of children being born.","zh":"fertility decline 指平均出生孩子數下降。"},{"en":"A country may experience fertility decline when young adults marry later and housing becomes expensive.","zh":"當年輕成年人較遲結婚且住屋變貴，一個國家可能經歷生育率下降。"},{"en":"Long fertility decline can shrink future workforces and school populations.","zh":"長期生育率下降可以縮小未來勞動力和學校人口。"},{"en":"The phrase describes a demographic downward trend.","zh":"這個短語描述人口方面的下降趨勢。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":11},{"front":"having postponed their first child","meaning":"推遲生第一個孩子之後","examples":[{"en":"Women may have a second child after having postponed their first child.","zh":"女性可能在推遲生第一個孩子之後再生第二個。"},{"en":"Having postponed their first child means after delaying the birth of their first baby.","zh":"having postponed their first child 指在延遲第一個孩子出生之後。"},{"en":"A couple may find parenthood harder if they begin after years of postponement.","zh":"如果夫妻經多年推遲後才開始育兒，他們可能覺得更困難。"},{"en":"Delaying the first child can compress the time available for later children.","zh":"推遲第一個孩子可以壓縮之後再生孩子的時間。"},{"en":"The phrase describes a prior delay that affects later family plans.","zh":"這個短語描述影響後續家庭計劃的先前延誤。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":11},{"front":"have a second and third","meaning":"生第二和第三個孩子","examples":[{"en":"Some people expect women to quickly have a second and third child.","zh":"有些人預期女性會很快生第二和第三個孩子。"},{"en":"To have a second and third means to have two more children after the first one.","zh":"have a second and third 指在第一個孩子之後再生兩個孩子。"},{"en":"A couple may plan to have a second and third child if housing and childcare become easier.","zh":"如果住屋和幼兒照顧變容易，夫妻可能計劃生第二和第三個孩子。"},{"en":"If the first child comes very late, having more children soon may be difficult.","zh":"如果第一個孩子來得很晚，很快再生更多孩子可能困難。"},{"en":"The phrase refers to later births in a family sequence.","zh":"這個短語指家庭次序中的後續出生。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":11},{"front":"overshoot theory","meaning":"過度下跌理論","examples":[{"en":"The overshoot theory suggests only partial recovery.","zh":"過度下跌理論指出可能只有部分恢復。"},{"en":"Overshoot theory is the idea that fertility falls below people’s real preferred level and may not fully return.","zh":"overshoot theory 指生育率跌破人們真正偏好水平，並可能無法完全回升的想法。"},{"en":"A student may overshoot a target by studying too narrowly and missing other topics.","zh":"學生可能因溫習範圍過窄而偏離目標，錯過其他題目。"},{"en":"In fertility, delay can push final birth numbers lower than intended.","zh":"在生育方面，延遲可以把最終出生數推低至低於原意。"},{"en":"The phrase explains why a fall may go too far and recover only partly.","zh":"這個短語解釋為何下降可能過頭，並只部分恢復。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":11},{"front":"partial recuperation","meaning":"部分恢復","examples":[{"en":"The overshoot theory suggests there may be only partial recuperation.","zh":"過度下跌理論指出可能只有部分恢復。"},{"en":"Partial recuperation means only some recovery, not a full return to the previous level.","zh":"partial recuperation 指只有一部分恢復，而不是完全回到之前水平。"},{"en":"A student may show partial recuperation after illness if grades improve but remain below normal.","zh":"如果學生病後成績改善但仍低於正常，就是部分恢復。"},{"en":"If fertility recovers only partly, population ageing may continue.","zh":"如果生育率只部分恢復，人口老化可能繼續。"},{"en":"The phrase describes incomplete recovery.","zh":"這個短語描述不完整恢復。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":12},{"front":"permanently lower fertility","meaning":"永久降低生育率","examples":[{"en":"Postponement could permanently lower fertility.","zh":"推遲生育可能永久降低生育率。"},{"en":"Permanently lower fertility means reduce birth rates in a lasting way.","zh":"permanently lower fertility 指以持久方式降低出生率。"},{"en":"If many adults delay parenthood until it is biologically difficult, fertility may remain lower.","zh":"如果許多成年人把育兒推遲到生理上困難的年齡，生育率可能持續較低。"},{"en":"A temporary delay can become permanent when missed births are not fully made up later.","zh":"當被錯過的出生之後沒有完全補回，暫時延遲可以變成永久影響。"},{"en":"The phrase describes a long-term effect, not a short postponement only.","zh":"這個短語描述長期效果，而不只是短暫推遲。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":12},{"front":"not just redistribute it across time","meaning":"不只是將……重新分配到不同時間","examples":[{"en":"Postponement may not just redistribute fertility across time.","zh":"推遲生育可能不只是將生育重新分配到不同時間。"},{"en":"Not just redistribute it across time means not merely move births from earlier years to later years.","zh":"not just redistribute it across time 指不只是把出生由較早年份移到較後年份。"},{"en":"If a student delays all revision, she may not just move the work later; she may lose time completely.","zh":"如果學生推遲所有溫習，她可能不只是把工作移後，而是完全失去時間。"},{"en":"Delayed childbirth may reduce total births, not simply change their timing.","zh":"推遲生育可能減少總出生數，而不只是改變時間。"},{"en":"The phrase contrasts timing shift with real long-term loss.","zh":"這個短語把時間轉移與真正長期損失作對比。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":12},{"front":"across time","meaning":"跨時間；在不同時間之間","examples":[{"en":"Postponement may redistribute births across time.","zh":"推遲可能把出生跨時間重新分配。"},{"en":"Across time means over different periods rather than at one moment.","zh":"across time 指分布在不同時期，而不是集中於一刻。"},{"en":"A teacher may spread homework across time so students do not do everything in one night.","zh":"老師可能把功課分散在不同時間，讓學生不用一晚完成所有。"},{"en":"Moving events across time changes when they happen, but not always how many happen.","zh":"把事件移到不同時間會改變其發生時間，但不一定改變總數。"},{"en":"The phrase focuses on distribution over a timeline.","zh":"這個短語重點是沿時間線的分布。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":12},{"front":"there is a twist","meaning":"事情有轉折","examples":[{"en":"There is a twist in the argument about low fertility.","zh":"關於低生育率的論點有一個轉折。"},{"en":"There is a twist means there is an unexpected extra point or surprising change in the discussion.","zh":"there is a twist 指討論中有一個意想不到的額外點或驚人變化。"},{"en":"A film has a twist when the quiet character is revealed as the hero.","zh":"當安靜角色被揭示為英雄，電影就有轉折。"},{"en":"In an argument, a twist can make readers rethink the earlier explanation.","zh":"在論證中，轉折可以令讀者重新思考早前解釋。"},{"en":"The phrase signals a surprising development.","zh":"這個短語表示有驚人發展。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":12},{"front":"how they see the family","meaning":"他們如何看待家庭","examples":[{"en":"Low fertility may change how people see the family.","zh":"低生育率可能改變人們如何看待家庭。"},{"en":"How they see the family means people’s attitudes and beliefs about family life.","zh":"how they see the family 指人們對家庭生活的態度和信念。"},{"en":"A child raised in a small household may see the family differently from someone raised with many siblings.","zh":"在小家庭長大的孩子，可能與有很多兄弟姊妹的人不同地看待家庭。"},{"en":"If one-child families become common, people may begin to view them as normal.","zh":"如果一孩家庭變得普遍，人們可能開始把它視為正常。"},{"en":"The phrase focuses on perception and values.","zh":"這個短語重點是看法和價值觀。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":12},{"front":"Institute of Demography","meaning":"人口研究所","examples":[{"en":"Tomas Sobotka works at the Vienna Institute of Demography.","zh":"Tomas Sobotka 在維也納人口研究所工作。"},{"en":"An Institute of Demography is a research organisation that studies population patterns.","zh":"Institute of Demography 指研究人口模式的研究機構。"},{"en":"Such an institute may analyse births, deaths, ageing, migration, and family size.","zh":"這類研究所可能分析出生、死亡、老化、移民和家庭規模。"},{"en":"Research institutes help governments understand long-term social change.","zh":"研究所幫助政府理解長期社會變化。"},{"en":"The phrase names an academic or research body.","zh":"這個短語命名學術或研究機構。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":12},{"front":"after decades of low fertility","meaning":"經過數十年的低生育率後","examples":[{"en":"After decades of low fertility, attitudes towards children may change.","zh":"經過數十年的低生育率後，人們對孩子的態度可能改變。"},{"en":"After decades of low fertility means after many tens of years with low birth rates.","zh":"after decades of low fertility 指在低出生率持續幾十年之後。"},{"en":"After decades of decline, a town may stop expecting many new schools to open.","zh":"經過數十年下降後，城鎮可能不再期望有許多新學校開辦。"},{"en":"Long exposure to low fertility can make small families feel normal.","zh":"長期處於低生育率中，可以令小家庭感覺正常。"},{"en":"The phrase links a long trend with changed attitudes.","zh":"這個短語把長期趨勢與態度改變連起來。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":12},{"front":"a quarter of","meaning":"四分之一的……","examples":[{"en":"A quarter of young German men say they have no intention of having children.","zh":"四分之一的德國年輕男性表示無意生孩子。"},{"en":"A quarter of something means one out of four parts, or 25 percent.","zh":"a quarter of something 指四份中的一份，即百分之二十五。"},{"en":"A quarter of a class of forty students is ten students.","zh":"四十人班級的四分之一是十名學生。"},{"en":"If a quarter of young adults reject parenthood, the attitude is socially significant.","zh":"如果四分之一的年輕成年人拒絕成為父母，這種態度具有社會意義。"},{"en":"The phrase expresses a clear proportion.","zh":"這個短語表達清楚比例。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":12},{"front":"a fifth of","meaning":"五分之一的……","examples":[{"en":"A fifth of young German women say they have no intention of having children.","zh":"五分之一的德國年輕女性表示無意生孩子。"},{"en":"A fifth of something means one out of five parts, or 20 percent.","zh":"a fifth of something 指五份中的一份，即百分之二十。"},{"en":"A fifth of a hundred students is twenty students.","zh":"一百名學生的五分之一是二十名學生。"},{"en":"If a fifth of a group chooses something, it is a noticeable minority.","zh":"如果一個群體的五分之一選擇某事，那是一個明顯少數。"},{"en":"The phrase gives a proportion without using a percentage sign.","zh":"這個短語不用百分號也能表達比例。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":12},{"front":"have no intention of","meaning":"無意去……","examples":[{"en":"Some young Germans have no intention of having children.","zh":"一些德國年輕人無意生孩子。"},{"en":"To have no intention of doing something means not to plan or want to do it.","zh":"have no intention of doing something 指沒有計劃或不想做某事。"},{"en":"A student may have no intention of joining the school trip if the fee is too high.","zh":"如果費用太高，學生可能無意參加學校旅行。"},{"en":"If many young adults have no intention of becoming parents, future birth rates may remain low.","zh":"如果許多年輕成年人無意成為父母，未來出生率可能保持低水平。"},{"en":"The phrase expresses clear unwillingness or lack of plan.","zh":"這個短語表達明確不願意或沒有計劃。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":12},{"front":"think that this is fine","meaning":"認為這沒有問題","examples":[{"en":"Some young Germans think that having no children is fine.","zh":"一些德國年輕人認為沒有孩子沒有問題。"},{"en":"To think that this is fine means to consider a situation acceptable or not problematic.","zh":"think that this is fine 指認為某情況可以接受或沒有問題。"},{"en":"A student may think online lessons are fine if they save travel time.","zh":"如果網課節省交通時間，學生可能認為網課沒問題。"},{"en":"When people see childlessness as fine, social pressure to have children becomes weaker.","zh":"當人們認為無子女沒有問題，生孩子的社會壓力就變弱。"},{"en":"The phrase describes acceptance rather than enthusiasm.","zh":"這個短語描述接受，而不一定是熱衷。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":13},{"front":"repeat a poll","meaning":"重做民意調查","examples":[{"en":"Eurobarometer repeated its poll about ideal family size in 2001.","zh":"歐洲晴雨表在2001年重做關於理想家庭規模的民意調查。"},{"en":"To repeat a poll means to ask the same or similar survey questions again later.","zh":"repeat a poll 指之後再次提出相同或相似的調查問題。"},{"en":"A school may repeat a poll each term to see whether students feel less stressed.","zh":"學校可能每學期重做民意調查，看學生是否壓力減少。"},{"en":"Repeating a poll helps researchers compare changes over time.","zh":"重做民意調查幫助研究人員比較隨時間出現的變化。"},{"en":"The phrase describes survey follow-up.","zh":"這個短語描述調查跟進。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":13},{"front":"ideal family size","meaning":"理想家庭規模","examples":[{"en":"The poll asked about ideal family size.","zh":"該民意調查詢問理想家庭規模。"},{"en":"Ideal family size is the number of children people think would be best for a family.","zh":"ideal family size 指人們認為一個家庭最理想的孩子數量。"},{"en":"Some people’s ideal family size is two children, while others prefer none or one.","zh":"有些人的理想家庭規模是兩個孩子，而另一些人偏好沒有或一個。"},{"en":"Ideal family size can differ from actual family size because of money, health, or timing.","zh":"理想家庭規模可能因金錢、健康或時間而不同於實際家庭規模。"},{"en":"The phrase refers to preference, not necessarily reality.","zh":"這個短語指偏好，而不一定是現實。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":13},{"front":"support for","meaning":"對……的支持","examples":[{"en":"Support for the two-child model had fallen everywhere.","zh":"對兩孩模式的支持在各地都下降了。"},{"en":"Support for something means approval, agreement, or backing for it.","zh":"support for something 指對某事的認可、同意或支持。"},{"en":"Support for a school uniform policy may fall if students feel it is uncomfortable.","zh":"如果學生覺得校服不舒服，對校服政策的支持可能下降。"},{"en":"When support for an idea falls, social norms may begin to change.","zh":"當對某想法的支持下降，社會規範可能開始改變。"},{"en":"The phrase measures how much people approve of an idea.","zh":"這個短語量度人們有多認同某想法。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":13},{"front":"two-child model","meaning":"兩孩模式","examples":[{"en":"Support for the two-child model had fallen everywhere.","zh":"對兩孩模式的支持在各地都下降了。"},{"en":"The two-child model is the family pattern in which having two children is treated as normal or ideal.","zh":"two-child model 指把兩個孩子視為正常或理想的家庭模式。"},{"en":"A society may prefer the two-child model because it balances siblings with manageable family size.","zh":"社會可能偏好兩孩模式，因為它平衡兄弟姊妹陪伴和可管理的家庭規模。"},{"en":"If support for this model falls, more people may accept one-child or child-free lives.","zh":"如果對這種模式的支持下降，更多人可能接受一孩或無子女生活。"},{"en":"The phrase describes a family norm.","zh":"這個短語描述家庭規範。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":13},{"front":"enter a new demographic trap","meaning":"進入新的人口陷阱","examples":[{"en":"Parts of Europe may be entering a new demographic trap.","zh":"歐洲部分地區可能正在進入新的人口陷阱。"},{"en":"To enter a new demographic trap means to move into a population pattern that is hard to escape.","zh":"enter a new demographic trap 指進入一種難以逃脫的人口模式。"},{"en":"A town enters a demographic trap if few babies are born and young workers keep leaving.","zh":"如果城鎮出生嬰兒少，而年輕工人持續離開，它就進入人口陷阱。"},{"en":"Low fertility can change expectations, which then keeps fertility low.","zh":"低生育率可以改變期望，而這些期望又使生育率保持低水平。"},{"en":"The phrase suggests a self-reinforcing population problem.","zh":"這個短語暗示自我強化的人口問題。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":13},{"front":"restrict family size by choice","meaning":"自願限制家庭規模","examples":[{"en":"People restrict family size by choice.","zh":"人們自願限制家庭規模。"},{"en":"To restrict family size by choice means to voluntarily decide to have fewer children.","zh":"restrict family size by choice 指自願決定生較少孩子。"},{"en":"A couple may restrict family size by choice because they want more time, freedom, or financial security.","zh":"夫妻可能因想要更多時間、自由或財政安全而自願限制家庭規模。"},{"en":"When many people make the same choice, it becomes a social trend.","zh":"當許多人作出相同選擇，它就成為社會趨勢。"},{"en":"The phrase contrasts voluntary limitation with government force.","zh":"這個短語把自願限制與政府強制作對比。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":13},{"front":"natural fertility decline","meaning":"自然生育率下降","examples":[{"en":"Social and cultural factors may cause natural fertility decline to overshoot.","zh":"社會和文化因素可能令自然生育率下降過度。"},{"en":"Natural fertility decline is a fall in birth rates that happens through people’s choices and social change.","zh":"natural fertility decline 指透過人們選擇和社會變化而發生的出生率下降。"},{"en":"Urban living and longer education can contribute to natural fertility decline.","zh":"城市生活和較長教育可以促成自然生育率下降。"},{"en":"If decline overshoots, fertility may fall lower than people truly prefer.","zh":"如果下降過度，生育率可能低於人們真正偏好。"},{"en":"The phrase describes demographic change without direct coercion.","zh":"這個短語描述沒有直接強制的人口變化。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":13},{"front":"change expectations","meaning":"改變期望","examples":[{"en":"Low fertility can change expectations about family size.","zh":"低生育率可以改變人們對家庭規模的期望。"},{"en":"To change expectations means to alter what people think is normal, likely, or desirable.","zh":"change expectations 指改變人們認為正常、可能或理想的事情。"},{"en":"Online shopping changed expectations about how quickly goods should arrive.","zh":"網上購物改變了人們對貨物應多快送達的期望。"},{"en":"If small families become common, young adults may expect to have fewer children too.","zh":"如果小家庭變得普遍，年輕成年人可能也預期自己生較少孩子。"},{"en":"The phrase focuses on shifts in what people consider normal.","zh":"這個短語重點是人們對正常情況的看法轉變。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":13},{"front":"respond by having","meaning":"以……作回應","examples":[{"en":"People may respond by having even fewer children.","zh":"人們可能以生更少孩子作回應。"},{"en":"To respond by having something means to react to a situation through that behaviour or result.","zh":"respond by having something 指透過某行為或結果回應某情況。"},{"en":"Families may respond to high rent by having fewer expenses and delaying big plans.","zh":"家庭可能以減少開支和推遲重大計劃來回應高租金。"},{"en":"If social norms shift, people may react by reducing family size further.","zh":"如果社會規範轉變，人們可能透過進一步縮小家庭規模作出反應。"},{"en":"The phrase connects a reaction with an action.","zh":"這個短語把反應與行動連起來。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":13},{"front":"even fewer children","meaning":"更少孩子","examples":[{"en":"Changed expectations may lead people to have even fewer children.","zh":"改變了的期望可能令人們生更少孩子。"},{"en":"Even fewer children means a smaller number of children than already low numbers.","zh":"even fewer children 指比本來已少的數量還要更少的孩子。"},{"en":"A family may have even fewer children if housing costs rise again.","zh":"如果住屋成本再次上升，家庭可能生更少孩子。"},{"en":"If one child becomes normal, some people may choose none at all.","zh":"如果一個孩子成為正常，有些人可能選擇一個也不要。"},{"en":"The phrase emphasises further reduction.","zh":"這個短語強調進一步減少。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":13},{"front":"not necessarily mean that","meaning":"不一定意味着","examples":[{"en":"That does not necessarily mean that birth rates will fall further.","zh":"那不一定意味着出生率會進一步下降。"},{"en":"Not necessarily mean that means one result does not automatically prove another conclusion.","zh":"not necessarily mean that 指一個結果不會自動證明另一結論。"},{"en":"A quiet student does not necessarily mean that the student is unhappy.","zh":"學生安靜不一定意味着他不開心。"},{"en":"The phrase warns readers not to jump too quickly from one fact to another.","zh":"這個短語提醒讀者不要太快從一個事實跳到另一結論。"},{"en":"It leaves room for other possibilities.","zh":"它保留其他可能性。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":14},{"front":"natural floor","meaning":"自然下限","examples":[{"en":"There may yet be some natural floor for birth rates.","zh":"出生率可能仍有某種自然下限。"},{"en":"A natural floor is the lowest level something may fall to before it stops declining naturally.","zh":"natural floor 指某事自然停止下降前可能跌到的最低水平。"},{"en":"A shop’s sales may have a natural floor if loyal customers keep buying essentials.","zh":"如果忠實顧客繼續購買必需品，商店銷售可能有自然下限。"},{"en":"If birth rates have a natural floor, they may stop falling even without full recovery.","zh":"如果出生率有自然下限，即使沒有完全恢復，也可能停止下降。"},{"en":"The phrase describes a possible lower limit.","zh":"這個短語描述可能的最低界線。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":14},{"front":"recovery from very low fertility rates","meaning":"從極低生育率中恢復","examples":[{"en":"Recovery from very low fertility rates may be slow.","zh":"從極低生育率中恢復可能很慢。"},{"en":"Recovery from very low fertility rates means birth rates rising again after being extremely low.","zh":"recovery from very low fertility rates 指出生率在極低水平後再次上升。"},{"en":"A country may try to support recovery through childcare, housing, and parental leave.","zh":"國家可能透過幼兒照顧、住屋和育兒假來支援恢復。"},{"en":"If attitudes have changed, recovery may take longer than economic recovery.","zh":"如果態度已改變，恢復可能比經濟復甦更久。"},{"en":"The phrase focuses on coming back from an extremely low demographic level.","zh":"這個短語重點是從極低人口水平回升。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":14},{"front":"prove to be slow","meaning":"結果證明是緩慢的","examples":[{"en":"Recovery may prove to be slow.","zh":"恢復可能結果證明是緩慢的。"},{"en":"Prove to be slow means turn out, after time or evidence, to happen slowly.","zh":"prove to be slow 指經過時間或證據顯示，某事進展緩慢。"},{"en":"A student’s improvement may prove to be slow if the grammar gaps are deep.","zh":"如果文法漏洞很深，學生進步可能結果證明是緩慢的。"},{"en":"Some recoveries look possible at first but take much longer than expected.","zh":"有些恢復起初看似可行，但所需時間比預期長得多。"},{"en":"The phrase describes what evidence later shows.","zh":"這個短語描述後來證據顯示的情況。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":14},{"front":"non-existent","meaning":"不存在的","examples":[{"en":"Recovery from very low fertility may even be non-existent.","zh":"從極低生育率中恢復甚至可能不存在。"},{"en":"Non-existent means not existing at all.","zh":"non-existent 指完全不存在。"},{"en":"In a poorly planned building, wheelchair access may be almost non-existent.","zh":"在規劃差劣的大廈中，輪椅通道可能幾乎不存在。"},{"en":"If fertility recovery is non-existent, birth rates do not rise again.","zh":"如果生育率恢復不存在，出生率就不會再次上升。"},{"en":"The phrase strongly states absence.","zh":"這個短語強烈表達缺失。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":14},{"front":"the following headings","meaning":"以下標題","examples":[{"en":"Students match the following headings with paragraphs.","zh":"學生將以下標題與段落配對。"},{"en":"The following headings are the titles or options listed after the instruction.","zh":"following headings 指指示之後列出的標題或選項。"},{"en":"In a reading test, students should read all the following headings before matching them.","zh":"在閱讀測驗中，學生應先閱讀所有以下標題，再進行配對。"},{"en":"Similar headings can confuse students if they rely only on keywords.","zh":"如果學生只依靠關鍵詞，相似標題可能令人混淆。"},{"en":"The phrase introduces answer choices in a heading-matching task.","zh":"這個短語引入標題配對題的答案選項。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":14},{"front":"best fit","meaning":"最適合","examples":[{"en":"Students decide which paragraph each heading best fits.","zh":"學生判斷每個標題最適合哪一段。"},{"en":"Best fit means the option that matches the main idea most closely.","zh":"best fit 指最接近主旨的選項。"},{"en":"A teacher may ask which title best fits a student’s story.","zh":"老師可能問哪個標題最適合學生的故事。"},{"en":"In reading tasks, the best fit captures the whole paragraph, not one minor detail.","zh":"在閱讀題中，最適合的選項要概括整段，而不是單一小細節。"},{"en":"The phrase focuses on the strongest match.","zh":"這個短語重點是最強配對。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":14},{"front":"even further falls","meaning":"甚至進一步下降","examples":[{"en":"The heading asks whether there may be even further falls.","zh":"該標題詢問是否可能甚至進一步下降。"},{"en":"Even further falls means additional decreases beyond those that have already happened.","zh":"even further falls 指在已經發生的下降之外再有額外下跌。"},{"en":"A shop with weak sales may fear even further falls during a rainy week.","zh":"銷售疲弱的商店可能擔心雨天一週會令銷售進一步下降。"},{"en":"If attitudes continue changing, birth rates may fall beyond current levels.","zh":"如果態度繼續改變，出生率可能跌破目前水平。"},{"en":"The phrase emphasises continued decline.","zh":"這個短語強調持續下降。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":14},{"front":"one-child policy","meaning":"一孩政策","examples":[{"en":"The passage compares the trend to a one-child policy.","zh":"文章把這個趨勢比作一孩政策。"},{"en":"A one-child policy is a rule or social pattern in which families have only one child.","zh":"one-child policy 指家庭只生一個孩子的規則或社會模式。"},{"en":"A society may develop a one-child pattern even without legal force if most people copy one another.","zh":"如果大多數人互相仿效，即使沒有法律強制，社會也可能形成一孩模式。"},{"en":"If one child becomes normal, larger families may seem unusual.","zh":"如果一個孩子成為正常，較大家庭可能顯得不尋常。"},{"en":"The phrase can describe official policy or a social trend by comparison.","zh":"這個短語可以描述官方政策，也可以作為社會趨勢的比喻。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":14},{"front":"Germany differs","meaning":"德國有所不同","examples":[{"en":"The heading “Germany differs” refers to Germany’s unusual fertility pattern.","zh":"“Germany differs” 這個標題指德國不尋常的生育模式。"},{"en":"Germany differs means Germany is not following the same pattern as other countries.","zh":"Germany differs 指德國沒有遵循其他國家的相同模式。"},{"en":"A school may differ from others if its students start lessons later in the morning.","zh":"如果一所學校早上較遲上課，它可能與其他學校不同。"},{"en":"When one case differs, researchers study why it does not fit the general trend.","zh":"當一個個案不同，研究人員會研究它為何不符合一般趨勢。"},{"en":"The phrase highlights contrast.","zh":"這個短語突出對比。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":14},{"front":"possible reasons","meaning":"可能原因","examples":[{"en":"The paragraph gives possible reasons for low fertility.","zh":"該段提供低生育率的可能原因。"},{"en":"Possible reasons are causes that may explain something, though they may not be fully proven.","zh":"possible reasons 指可能解釋某事的原因，雖然未必完全證實。"},{"en":"A teacher may list possible reasons for why a class performed poorly.","zh":"老師可能列出班級表現差的可能原因。"},{"en":"Considering several possible reasons prevents an over-simple explanation.","zh":"考慮幾個可能原因可以避免過度簡化解釋。"},{"en":"The phrase introduces tentative causes.","zh":"這個短語引入暫定原因。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":14},{"front":"according to the text","meaning":"根據文章","examples":[{"en":"Students choose statements that are true according to the text.","zh":"學生選擇根據文章屬實的陳述。"},{"en":"According to the text means based only on what the passage says.","zh":"according to the text 指只根據文章所說內容。"},{"en":"In reading tests, students should answer according to the text, not outside knowledge.","zh":"在閱讀測驗中，學生應根據文章作答，而不是根據外部知識。"},{"en":"This phrase keeps answers tied to evidence in the passage.","zh":"這個短語讓答案緊扣文章證據。"},{"en":"It warns students not to guess beyond the source.","zh":"它提醒學生不要超出來源猜測。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":15},{"front":"the following statements are true","meaning":"以下陳述屬實","examples":[{"en":"Five of the following statements are true.","zh":"以下陳述中有五項屬實。"},{"en":"The following statements are true means the listed sentences match the information in the text.","zh":"following statements are true 指列表中的句子與文本資料相符。"},{"en":"A teacher may ask students to choose which statements are true after reading a report.","zh":"老師可能要求學生讀完報告後選出哪些陳述屬實。"},{"en":"Students must check each statement carefully because some may sound possible but lack support.","zh":"學生必須仔細核對每項陳述，因為有些可能聽起來合理但沒有支持。"},{"en":"The phrase introduces a selection task based on accuracy.","zh":"這個短語引入根據準確性選擇的題目。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":15},{"front":"corresponding letters","meaning":"對應字母","examples":[{"en":"Candidates write the corresponding letters in the answer boxes.","zh":"考生把對應字母寫在答案格中。"},{"en":"Corresponding letters are the letters that match the correct answer choices.","zh":"corresponding letters 指與正確答案選項相配的字母。"},{"en":"If option B is correct, the corresponding letter is B.","zh":"如果選項 B 正確，對應字母就是 B。"},{"en":"Writing the correct letter matters because markers may not read rewritten options.","zh":"寫正確字母很重要，因為評卷者未必閱讀改寫選項。"},{"en":"The phrase refers to answer labels, not full answers.","zh":"這個短語指答案標籤，而不是完整答案。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":15},{"front":"in any order","meaning":"以任何次序","examples":[{"en":"The answers can be written in any order.","zh":"答案可以以任何次序書寫。"},{"en":"In any order means the sequence does not matter.","zh":"in any order 指排列次序不重要。"},{"en":"If a teacher says names can be written in any order, students do not need to rank them.","zh":"如果老師說名字可以任何次序寫，學生就不需要排序。"},{"en":"This instruction reduces pressure because only the correct choices matter.","zh":"這個指示減少壓力，因為重要的是選項正確。"},{"en":"The phrase contrasts free ordering with fixed sequence.","zh":"這個短語把自由排序與固定次序作對比。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":15},{"front":"the highest percentage of","meaning":"最高百分比的……","examples":[{"en":"The question asks whether Germany has the highest percentage of childless women.","zh":"題目問德國是否有最高百分比的無子女女性。"},{"en":"The highest percentage of something means the largest share compared with other groups.","zh":"highest percentage of something 指與其他群體相比最高比例。"},{"en":"A class may have the highest percentage of absentees if many students are sick.","zh":"如果許多學生生病，某班可能有最高百分比的缺席者。"},{"en":"Percentages allow comparison even when countries have different population sizes.","zh":"百分比讓人即使在國家人口規模不同時仍可比較。"},{"en":"The phrase focuses on relative share, not total number.","zh":"這個短語重點是相對比例，而不是總數。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":15},{"front":"childless women","meaning":"無子女女性","examples":[{"en":"The passage discusses the percentage of childless women in Germany.","zh":"文章討論德國無子女女性的百分比。"},{"en":"Childless women are women who do not have children.","zh":"childless women 指沒有孩子的女性。"},{"en":"Some women remain childless by choice, while others may be childless because of health, timing, or circumstances.","zh":"有些女性自願無子女，而另一些可能因健康、時間或環境而無子女。"},{"en":"A high share of childless women can lower overall fertility rates.","zh":"無子女女性比例高可以降低整體生育率。"},{"en":"The phrase describes family status, not personal worth.","zh":"這個短語描述家庭狀態，而不是個人價值。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":15},{"front":"high birth rates","meaning":"高出生率","examples":[{"en":"The option asks whether Italy and Poland have high birth rates.","zh":"選項問意大利和波蘭是否有高出生率。"},{"en":"High birth rates mean many babies are born compared with the population size.","zh":"high birth rates 指相對人口規模而言有許多嬰兒出生。"},{"en":"A country with high birth rates may need more schools and childcare centres.","zh":"高出生率國家可能需要更多學校和幼兒照顧中心。"},{"en":"High birth rates can increase the young population and future workforce.","zh":"高出生率可以增加年輕人口和未來勞動力。"},{"en":"The phrase contrasts with low birth rates.","zh":"這個短語與低出生率相對。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":15},{"front":"reasons given by","meaning":"由……提出的原因","examples":[{"en":"The question refers to the reasons given by Michael Teitelbaum.","zh":"題目提到由 Michael Teitelbaum 提出的原因。"},{"en":"Reasons given by someone are explanations that person provides.","zh":"reasons given by someone 指某人提供的解釋。"},{"en":"Students should identify the reasons given by the writer, not reasons they already know.","zh":"學生應辨認作者提出的原因，而不是自己已知道的原因。"},{"en":"In reading tests, details must be linked to the person who actually said them.","zh":"在閱讀測驗中，細節必須連回真正提出它的人。"},{"en":"The phrase focuses on source attribution.","zh":"這個短語重點是來源歸屬。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":15},{"front":"unique to","meaning":"……獨有","examples":[{"en":"Most of the reasons are not unique to Germany.","zh":"大多數原因並非德國獨有。"},{"en":"Unique to a place means found only there and not elsewhere.","zh":"unique to a place 指只在該地存在，而其他地方沒有。"},{"en":"A school tradition may be unique to one campus if no other branch follows it.","zh":"如果某校園傳統沒有其他分校遵循，它可能是該校區獨有。"},{"en":"If a reason is not unique to Germany, it may also explain low fertility in other countries.","zh":"如果某原因並非德國獨有，它也可能解釋其他國家的低生育率。"},{"en":"The phrase tests whether a feature is exclusive.","zh":"這個短語測試某特徵是否專屬。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":15},{"front":"encourage people to have children","meaning":"鼓勵人們生孩子","examples":[{"en":"Some governments encouraged people to have children.","zh":"一些政府鼓勵人們生孩子。"},{"en":"To encourage people to have children means to support or persuade adults to become parents.","zh":"encourage people to have children 指支持或說服成年人做父母。"},{"en":"A government may encourage people to have children by offering childcare subsidies.","zh":"政府可能透過幼兒照顧津貼鼓勵人們生孩子。"},{"en":"If the cost of raising children falls, more couples may feel able to start families.","zh":"如果養育孩子成本下降，更多夫妻可能覺得能組織家庭。"},{"en":"The phrase describes pro-birth policy or social encouragement.","zh":"這個短語描述鼓勵生育政策或社會鼓勵。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":15},{"front":"later usually have more soon after","meaning":"較遲生育後通常很快再生","examples":[{"en":"The option asks whether women who have a child later usually have more soon after.","zh":"選項問較遲生育的女性是否通常很快再生更多孩子。"},{"en":"Later usually have more soon after means people who delay the first child normally have additional children quickly afterward.","zh":"later usually have more soon after 指推遲第一個孩子的人通常之後很快再生。"},{"en":"A couple who has a first child at 38 may find it difficult to have two more soon after.","zh":"38歲才生第一個孩子的夫妻，可能很難之後很快再生兩個。"},{"en":"The phrase tests whether delayed childbirth simply shifts births later or reduces total births.","zh":"這個短語測試延遲生育是否只是把出生移後，還是減少總出生。"},{"en":"It focuses on timing after a late first birth.","zh":"它重點是較遲首次生育後的時間安排。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":15},{"front":"wanted fewer children than","meaning":"想要比……更少的孩子","examples":[{"en":"The question asks whether people wanted fewer children than before.","zh":"題目問人們是否想要比以前更少的孩子。"},{"en":"Wanted fewer children than means preferred a smaller number of children compared with another time or group.","zh":"wanted fewer children than 指相比另一時間或群體，偏好較少孩子。"},{"en":"Some young adults may want fewer children than their parents because housing is expensive.","zh":"一些年輕成年人可能因住屋昂貴而想要比父母更少的孩子。"},{"en":"A fall in desired family size can reduce birth rates even without economic crisis.","zh":"理想家庭規模下降可以在沒有經濟危機下也降低出生率。"},{"en":"The phrase compares preferences.","zh":"這個短語比較偏好。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":16},{"front":"according to Eurobarometer research","meaning":"根據歐洲晴雨表研究","examples":[{"en":"The statement refers to findings according to Eurobarometer research.","zh":"該陳述提到根據歐洲晴雨表研究所得的發現。"},{"en":"According to Eurobarometer research means based on survey evidence from Eurobarometer.","zh":"according to Eurobarometer research 指根據歐洲晴雨表的調查證據。"},{"en":"According to school survey research, many students prefer shorter but more frequent quizzes.","zh":"根據學校調查研究，許多學生偏好較短但較頻密的小測。"},{"en":"Citing research helps readers know where a claim comes from.","zh":"引用研究幫助讀者知道聲稱來自哪裡。"},{"en":"The phrase ties a statement to a specific data source.","zh":"這個短語把陳述連到特定資料來源。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":16},{"front":"natural level at which","meaning":"……所處的自然水平","examples":[{"en":"There may be a natural level at which birth rates stop declining.","zh":"可能存在一個出生率停止下降的自然水平。"},{"en":"A natural level at which something happens is a point where a process settles without external force.","zh":"natural level at which something happens 指某過程在沒有外力下穩定下來的點。"},{"en":"A shop may find a natural level at which daily sales stop falling because regular customers remain.","zh":"商店可能找到每日銷售停止下降的自然水平，因為固定顧客仍然存在。"},{"en":"If birth rates reach a natural floor, further decline may slow or stop.","zh":"如果出生率達到自然下限，進一步下降可能放慢或停止。"},{"en":"The phrase describes a possible settling point.","zh":"這個短語描述可能的穩定點。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":16},{"front":"stop declining","meaning":"停止下降","examples":[{"en":"Birth rates may eventually stop declining.","zh":"出生率可能最終停止下降。"},{"en":"To stop declining means to stop falling or decreasing.","zh":"stop declining 指停止下跌或減少。"},{"en":"A student’s grades may stop declining after she changes her study routine.","zh":"學生改變學習規律後，成績可能停止下降。"},{"en":"When a statistic stops declining, it may stabilise even if it does not rise.","zh":"當統計數字停止下降，它可能穩定，即使沒有上升。"},{"en":"The phrase describes the end of a downward trend.","zh":"這個短語描述下行趨勢的結束。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":16},{"front":"according to the information given","meaning":"根據所提供的資料","examples":[{"en":"Candidates choose answers according to the information given in the text.","zh":"考生根據文章所提供的資料選擇答案。"},{"en":"According to the information given means based only on the details provided.","zh":"according to the information given 指只根據已提供的細節。"},{"en":"In an exam, students should answer according to the information given, not personal belief.","zh":"在考試中，學生應根據所提供的資料作答，而不是個人信念。"},{"en":"If the text does not support an option, students should not choose it.","zh":"如果文本不支持某選項，學生不應選它。"},{"en":"The phrase sets the evidence source for answering.","zh":"這個短語設定作答的證據來源。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":16},{"front":"choose the correct answer or answers","meaning":"選出正確答案","examples":[{"en":"Students choose the correct answer or answers from the choices.","zh":"學生從選項中選出正確答案。"},{"en":"Choose the correct answer or answers means select one or more options that are right.","zh":"choose the correct answer or answers 指選出一個或多個正確選項。"},{"en":"If a question allows more than one answer, students must check all choices carefully.","zh":"如果題目容許多於一個答案，學生必須仔細檢查所有選項。"},{"en":"Some options may be partly true but not supported by the exact text.","zh":"有些選項可能部分正確，但沒有被文本準確支持。"},{"en":"The phrase is an exam instruction about selecting answers.","zh":"這個短語是關於選答案的考試指示。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":16},{"front":"from the choices given","meaning":"從所提供選項中","examples":[{"en":"Candidates choose from the choices given.","zh":"考生從所提供選項中選擇。"},{"en":"From the choices given means only from the options provided in the question.","zh":"from the choices given 指只從題目提供的選項中選擇。"},{"en":"A student should not invent option E if only A to D are given.","zh":"如果只提供 A 至 D，學生不應自創選項 E。"},{"en":"The phrase limits the possible answers to the listed choices.","zh":"這個短語把可能答案限制在列表選項之內。"},{"en":"It is common in multiple-choice instructions.","zh":"它常見於選擇題指示。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":16},{"front":"as many children","meaning":"那麼多孩子","examples":[{"en":"Ordinary Europeans may not think it is necessary to have as many children.","zh":"普通歐洲人可能不認為有必要生那麼多孩子。"},{"en":"As many children means the same large number of children as before or as another group.","zh":"as many children 指與以前或另一群體相同的大量孩子。"},{"en":"A couple may not want as many children as their grandparents had.","zh":"夫妻可能不想要祖父母那一代那麼多孩子。"},{"en":"When farms need less labour, families may feel fewer children are enough.","zh":"當農場需要較少勞力，家庭可能覺得較少孩子已足夠。"},{"en":"The phrase compares family size.","zh":"這個短語比較家庭規模。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":16},{"front":"less labour needed to farm land","meaning":"耕種土地所需勞力較少","examples":[{"en":"One reason is that less labour is needed to farm land.","zh":"其中一個原因是耕種土地所需勞力較少。"},{"en":"Less labour needed to farm land means fewer workers are required to grow and harvest crops.","zh":"less labour needed to farm land 指種植和收割作物所需工人較少。"},{"en":"Tractors and machines can mean less labour is needed to farm land than in the past.","zh":"拖拉機和機器可以令耕種土地所需勞力比過去少。"},{"en":"If children are no longer needed as farm workers, families may become smaller.","zh":"如果孩子不再需要作農場勞力，家庭可能變小。"},{"en":"The phrase links technology and farming changes with family size.","zh":"這個短語把科技和農業變化與家庭規模連起來。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":16},{"front":"the feeling that Europe is too crowded","meaning":"歐洲太擠迫的感覺","examples":[{"en":"The option mentions the feeling that Europe is too crowded.","zh":"選項提到歐洲太擠迫的感覺。"},{"en":"The feeling that Europe is too crowded is the belief that there are already too many people in many places.","zh":"feeling that Europe is too crowded 指相信許多地方已經有太多人。"},{"en":"City residents may feel a place is too crowded when trains, flats, and schools are full.","zh":"當火車、住宅和學校都很滿，城市居民可能覺得某地太擠迫。"},{"en":"If people feel crowding is a problem, they may not worry about population decline.","zh":"如果人們覺得擠迫是問題，他們可能不擔心人口下降。"},{"en":"The phrase describes perception, not necessarily measured population density.","zh":"這個短語描述感受，不一定是量度出來的人口密度。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":16},{"front":"general dislike of children","meaning":"普遍不喜歡孩子","examples":[{"en":"The option refers to a general dislike of children.","zh":"選項指普遍不喜歡孩子。"},{"en":"General dislike of children means a broad negative feeling toward children as a group.","zh":"general dislike of children 指對孩子作為群體有廣泛負面感覺。"},{"en":"A café that bans all children may be accused of showing a general dislike of children.","zh":"禁止所有孩子進入的咖啡店，可能被指普遍不喜歡孩子。"},{"en":"Low fertility does not automatically prove people dislike children; practical pressures may matter more.","zh":"低生育率不會自動證明人們不喜歡孩子；實際壓力可能更重要。"},{"en":"The phrase describes attitude, not economic conditions.","zh":"這個短語描述態度，而不是經濟條件。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":16},{"front":"childcare facilities","meaning":"幼兒照顧設施","examples":[{"en":"Poor childcare facilities may contribute to low fertility.","zh":"欠佳幼兒照顧設施可能導致低生育率。"},{"en":"Childcare facilities are places or services that care for young children while parents work or study.","zh":"childcare facilities 指在父母工作或學習時照顧年幼孩子的地方或服務。"},{"en":"Nurseries, daycare centres, and after-school care can be childcare facilities.","zh":"托兒所、日托中心和課後照顧都可以是幼兒照顧設施。"},{"en":"Good childcare facilities make it easier for parents to combine work and family life.","zh":"良好幼兒照顧設施令父母更容易兼顧工作和家庭生活。"},{"en":"The phrase refers to practical support for raising children.","zh":"這個短語指育兒的實際支援。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":17},{"front":"longer working hours","meaning":"較長工時","examples":[{"en":"The option mentions longer working hours as a possible reason.","zh":"選項提到較長工時作為可能原因。"},{"en":"Longer working hours mean spending more time at work each day or week.","zh":"longer working hours 指每天或每週花更多時間工作。"},{"en":"Parents with longer working hours may find it harder to collect children from school.","zh":"工時較長的父母可能較難接孩子放學。"},{"en":"Heavy work schedules can make adults postpone family plans.","zh":"沉重工作時間表可以令人推遲家庭計劃。"},{"en":"The phrase links work pressure with personal life choices.","zh":"這個短語把工作壓力與個人生活選擇連起來。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":17},{"front":"unemployment amongst young adults","meaning":"年輕成年人失業","examples":[{"en":"The question refers to unemployment amongst young adults.","zh":"題目提到年輕成年人失業。"},{"en":"Unemployment amongst young adults means many people in early adulthood do not have jobs.","zh":"unemployment amongst young adults 指許多早期成年人士沒有工作。"},{"en":"Young adults without work may delay renting homes, marrying, or having children.","zh":"沒有工作的年輕成年人可能推遲租屋、結婚或生孩子。"},{"en":"Joblessness can reduce confidence about long-term commitments.","zh":"失業可以降低人們對長期承擔的信心。"},{"en":"The phrase describes labour-market difficulty for younger people.","zh":"這個短語描述年輕人的勞動市場困難。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":17},{"front":"initial declines","meaning":"初期下降","examples":[{"en":"The question asks about initial declines in southern and eastern Europe.","zh":"題目詢問南歐和東歐的初期下降。"},{"en":"Initial declines are the first drops in a trend or statistic.","zh":"initial declines 指某趨勢或統計數字最初的下跌。"},{"en":"A new school policy may cause initial declines in complaints before long-term results appear.","zh":"新校政可能先令投訴初期下降，之後才見到長期結果。"},{"en":"Early declines can be sharp but may later stabilise.","zh":"初期下降可以很急劇，但之後可能穩定。"},{"en":"The phrase focuses on the beginning of a downward movement.","zh":"這個短語重點是下行的開始。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":17},{"front":"reduced influence of","meaning":"……影響力減弱","examples":[{"en":"The reduced influence of the Catholic Church affected family size.","zh":"天主教會影響力減弱影響了家庭規模。"},{"en":"Reduced influence of something means its power to shape behaviour or beliefs has become weaker.","zh":"reduced influence of something 指某事塑造行為或信念的力量變弱。"},{"en":"The reduced influence of printed newspapers has changed how people read news.","zh":"紙本報章影響力減弱，改變了人們閱讀新聞的方式。"},{"en":"If a church has less influence, traditional family expectations may weaken.","zh":"如果教會影響力較弱，傳統家庭期望可能減弱。"},{"en":"The phrase describes a decline in social power.","zh":"這個短語描述社會力量下降。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":17},{"front":"Catholic Church","meaning":"天主教會","examples":[{"en":"The passage refers to the influence of the Catholic Church.","zh":"文章提到天主教會的影響。"},{"en":"The Catholic Church is a major Christian church with long religious and social influence in many countries.","zh":"Catholic Church 指在許多國家長期具有宗教和社會影響力的重要基督宗教教會。"},{"en":"In some communities, the Catholic Church has shaped views on marriage, family, and children.","zh":"在一些社區中，天主教會塑造了人們對婚姻、家庭和孩子的看法。"},{"en":"If its influence declines, people may feel freer to choose smaller families.","zh":"如果其影響力下降，人們可能更自由地選擇較小家庭。"},{"en":"The phrase names a religious institution.","zh":"這個短語命名一個宗教機構。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":17},{"front":"lower standards of living","meaning":"較低生活水平","examples":[{"en":"Lower standards of living were linked to fertility decline in eastern Europe.","zh":"較低生活水平與東歐生育率下降有關。"},{"en":"Lower standards of living mean poorer quality of life, income, housing, services, or security.","zh":"lower standards of living 指生活質素、收入、住屋、服務或安全感較差。"},{"en":"Families may feel lower living standards when prices rise but wages do not.","zh":"當物價上升但工資不升，家庭可能感到生活水平下降。"},{"en":"If daily life becomes insecure, people may delay having children.","zh":"如果日常生活變得不穩定，人們可能推遲生孩子。"},{"en":"The phrase describes worsening living conditions.","zh":"這個短語描述生活條件惡化。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":17},{"front":"encouraged smaller families","meaning":"鼓勵較小型家庭","examples":[{"en":"The option asks whether governments encouraged smaller families.","zh":"選項問政府是否鼓勵較小型家庭。"},{"en":"Encouraged smaller families means supported or promoted having fewer children.","zh":"encouraged smaller families 指支持或推動人們生較少孩子。"},{"en":"A campaign about family planning may encourage smaller families by promoting contraception.","zh":"關於家庭計劃的宣傳可能透過推廣避孕來鼓勵較小型家庭。"},{"en":"If governments encourage smaller families, fertility may fall by policy design.","zh":"如果政府鼓勵小家庭，生育率可能因政策設計而下降。"},{"en":"The phrase contrasts with policies that encourage people to have more children.","zh":"這個短語與鼓勵人們多生孩子的政策相對。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":17},{"front":"at a later age","meaning":"在較遲年齡","examples":[{"en":"Women may have children at a later age.","zh":"女性可能在較遲年齡生孩子。"},{"en":"At a later age means when someone is older than usual or older than before.","zh":"at a later age 指在比平常或比以前更年長的時候。"},{"en":"Many people buy homes at a later age because property is expensive.","zh":"許多人因樓價昂貴而在較遲年齡買樓。"},{"en":"Having children later can reduce the number of years available for more births.","zh":"較遲生孩子可以減少日後再生孩子的年數。"},{"en":"The phrase focuses on delayed timing.","zh":"這個短語重點是時間延後。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":17},{"front":"follow the example of","meaning":"仿效……","examples":[{"en":"People may have fewer children because they follow the example of others.","zh":"人們可能因仿效他人而生較少孩子。"},{"en":"To follow the example of someone means to copy or be influenced by what they do.","zh":"follow the example of someone 指模仿或受某人的行為影響。"},{"en":"A student may start reading daily after following the example of a hardworking friend.","zh":"學生可能因仿效勤力朋友而開始每天閱讀。"},{"en":"If many friends have one child, others may begin to see one child as normal.","zh":"如果許多朋友只有一個孩子，其他人可能開始把一個孩子視為正常。"},{"en":"The phrase explains how behaviour spreads socially.","zh":"這個短語解釋行為如何在社會中傳播。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":17},{"front":"politicians want them to","meaning":"政客希望他們這樣做","examples":[{"en":"The option asks whether people have fewer children because politicians want them to.","zh":"選項問人們是否因政客希望他們這樣做而生較少孩子。"},{"en":"Politicians want them to means political leaders prefer or encourage people to do that action.","zh":"politicians want them to 指政治領袖偏好或鼓勵人們做該行動。"},{"en":"Students should not assume people change behaviour simply because politicians want them to.","zh":"學生不應假設人們改變行為只是因政客希望他們這樣做。"},{"en":"Personal decisions about children are usually shaped by work, money, culture, and age as well as policy.","zh":"關於孩子的個人決定通常受工作、金錢、文化、年齡和政策共同塑造。"},{"en":"The phrase tests whether a claim wrongly gives politicians too much influence.","zh":"這個短語測試某聲稱是否錯誤地給予政客過大影響。"}],"source":"63 - The Fertility Bust.pdf","sourcePage":17}],"ielts/reading/passage-2/Practice 64":[{"front":"tricky sums","meaning":"棘手的算術題","examples":[{"en":"Some children find tricky sums stressful when they have to answer quickly.","zh":"有些孩子在必須快速回答時，會覺得棘手的算術題很有壓力。"},{"en":"Tricky sums are arithmetic questions that are difficult, confusing, or easy to get wrong.","zh":"棘手的算術題是困難、令人混亂或容易答錯的算術問題。"},{"en":"A student may find 7 × 8 a tricky sum because the answer does not come to mind immediately.","zh":"學生可能覺得 7 × 8 是棘手的算術題，因為答案不會立刻浮現。"},{"en":"Tricky sums can cause stress when people feel they must answer in front of others.","zh":"當人們覺得必須在別人面前回答時，棘手的算術題會造成壓力。"},{"en":"Even adults may hesitate over tricky sums if they are tired or under pressure.","zh":"即使成年人疲倦或受壓時，也可能在棘手算術題前猶豫。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":1},{"front":"psychology","meaning":"心理學","examples":[{"en":"The passage links tricky sums with psychology.","zh":"篇章把棘手算術題與心理學連繫起來。"},{"en":"Psychology is the study of the mind, feelings, behaviour, and how people react in different situations.","zh":"心理學是研究思想、情緒、行為，以及人們在不同情況下如何反應的學科。"},{"en":"A teacher may use psychology to understand why a student panics during tests.","zh":"老師可能用心理學理解為何學生在測驗中恐慌。"},{"en":"Psychology helps explain why pressure can make people forget answers they normally know.","zh":"心理學有助解釋為何壓力會令人忘記平時知道的答案。"},{"en":"In this passage, psychology connects simple maths with stress and performance.","zh":"在這篇文章中，心理學把簡單數學與壓力和表現連接起來。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":1},{"front":"in their first years of studying","meaning":"在學習……的最初幾年","examples":[{"en":"In their first years of studying mathematics, children usually learn the times table.","zh":"在學習數學的最初幾年，孩子通常會學乘數表。"},{"en":"In their first years of studying means during the early stage of learning a subject.","zh":"在學習某科的最初幾年，是指學習該科的早期階段。"},{"en":"In their first years of studying English, students often learn greetings, numbers, and simple sentences.","zh":"在學習英文的最初幾年，學生常學問候語、數字和簡單句子。"},{"en":"Early learning years are important because they build the basic skills used later.","zh":"早期學習年份很重要，因為它們建立之後會使用的基本技能。"},{"en":"This phrase describes the beginning period of a learner’s education in one area.","zh":"這個短語描述學習者在某領域教育中的開始時期。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":1},{"front":"studying mathematics","meaning":"學習數學","examples":[{"en":"Children begin studying mathematics at school when they are young.","zh":"孩子年幼時便在學校開始學習數學。"},{"en":"Studying mathematics means learning numbers, shapes, calculations, patterns, and logical thinking.","zh":"學習數學，是指學習數字、形狀、計算、規律和邏輯思考。"},{"en":"A child studying mathematics may practise addition, multiplication, and problem-solving.","zh":"學習數學的孩子可能練習加法、乘法和解難。"},{"en":"Studying mathematics helps people handle money, time, measurement, and everyday decisions.","zh":"學習數學幫助人處理金錢、時間、量度和日常決定。"},{"en":"This phrase refers to learning maths as a school subject.","zh":"這個短語指把數學作為學校科目來學習。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":1},{"front":"all over the world","meaning":"世界各地","examples":[{"en":"Children all over the world learn the times table.","zh":"世界各地的孩子都學乘數表。"},{"en":"All over the world means in many countries and regions globally.","zh":"世界各地，是指全球許多國家和地區。"},{"en":"Students all over the world learn basic reading, writing, and counting skills.","zh":"世界各地的學生都學基本閱讀、寫作和數數技能。"},{"en":"When something is taught all over the world, it is seen as widely useful.","zh":"當某事在世界各地被教授，它被視為廣泛有用。"},{"en":"This phrase emphasises that the practice is not limited to one country.","zh":"這個短語強調該做法不限於一個國家。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":1},{"front":"the times table","meaning":"乘數表；乘法表","examples":[{"en":"Children usually have to learn the times table at school.","zh":"孩子通常必須在學校學乘數表。"},{"en":"The times table is a list of multiplication facts, such as 3 × 4 = 12.","zh":"乘數表是一系列乘法事實，例如 3 × 4 = 12。"},{"en":"A student who knows the times table can answer many multiplication questions quickly.","zh":"熟記乘數表的學生可以快速回答許多乘法問題。"},{"en":"Learning the times table helps children solve larger maths problems more easily.","zh":"學習乘數表幫助孩子更容易解決較大的數學問題。"},{"en":"This phrase is commonly used in British English for the multiplication table.","zh":"這個短語在英式英語中常用來指乘法表。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":1},{"front":"also known as","meaning":"亦稱為","examples":[{"en":"The times table is also known as the multiplication table.","zh":"乘數表亦稱為乘法表。"},{"en":"Also known as means having another name.","zh":"亦稱為，是指有另一個名稱。"},{"en":"Hong Kong International Airport is also known as Chek Lap Kok Airport.","zh":"香港國際機場亦稱為赤鱲角機場。"},{"en":"Writers use this phrase when one thing has two names that readers may know differently.","zh":"當一件事有兩個讀者可能不同程度熟悉的名稱時，作者會使用這個短語。"},{"en":"This phrase helps introduce an alternative term.","zh":"這個短語有助引入另一個稱呼。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":1},{"front":"the multiplication table","meaning":"乘法表","examples":[{"en":"The multiplication table shows the results of multiplying numbers together.","zh":"乘法表顯示數字相乘所得的結果。"},{"en":"The multiplication table is a chart or list showing answers to multiplication facts.","zh":"乘法表是顯示乘法答案的圖表或列表。"},{"en":"A child may use the multiplication table to check that 8 × 6 = 48.","zh":"孩子可能使用乘法表檢查 8 × 6 = 48。"},{"en":"The table helps learners remember patterns rather than counting every time.","zh":"這個表幫助學習者記住規律，而不是每次都重新數。"},{"en":"This phrase is the more formal name for the times table.","zh":"這個短語是乘數表較正式的名稱。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":1},{"front":"what you get when","meaning":"當……時所得的結果","examples":[{"en":"The multiplication table shows what you get when you multiply numbers together.","zh":"乘法表顯示當你把數字相乘時所得的結果。"},{"en":"What you get when means the result that appears after doing something.","zh":"當做某事時所得的結果，是指完成該動作後出現的答案或結果。"},{"en":"A receipt shows what you get when the shop adds the price of each item together.","zh":"收據顯示商店把每件貨品價格相加後所得的結果。"},{"en":"This phrase is useful for explaining results in simple steps.","zh":"這個短語適合用來簡單逐步解釋結果。"},{"en":"It connects an action with its outcome.","zh":"它把一個動作與其結果連接起來。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":1},{"front":"multiply numbers together","meaning":"把數字相乘","examples":[{"en":"Children learn what happens when they multiply numbers together.","zh":"孩子學習把數字相乘時會發生甚麼。"},{"en":"To multiply numbers together means to combine numbers by repeated addition.","zh":"把數字相乘，是指透過重複加法把數字結合。"},{"en":"If you multiply 4 and 5 together, you get 20.","zh":"如果把 4 和 5 相乘，就得到 20。"},{"en":"Multiplying numbers together helps people calculate totals, areas, and quantities quickly.","zh":"把數字相乘幫助人快速計算總數、面積和數量。"},{"en":"This phrase describes the basic action in multiplication.","zh":"這個短語描述乘法中的基本動作。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":1},{"front":"have traditionally learned","meaning":"傳統上一直學習","examples":[{"en":"Children have traditionally learned their times table by repeating it.","zh":"孩子傳統上一直透過重複背誦學習乘數表。"},{"en":"Have traditionally learned means have usually learned something in this way for a long time.","zh":"傳統上一直學習，是指長久以來通常以這種方式學習某事。"},{"en":"Students have traditionally learned spelling by copying words and testing themselves.","zh":"學生傳統上一直透過抄寫字詞和自測來學拼寫。"},{"en":"Traditional learning methods often continue because teachers and parents are familiar with them.","zh":"傳統學習方法常延續，因為老師和家長熟悉它們。"},{"en":"This phrase points to an old and common way of learning.","zh":"這個短語指出一種古老而常見的學習方式。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":1},{"front":"go from…all the way up to…","meaning":"由……一直到……","examples":[{"en":"Children go from “1 times 1 is 1” all the way up to “12 times 12 is 144”.","zh":"孩子由「1 乘 1 等於 1」一直學到「12 乘 12 等於 144」。"},{"en":"Go from A all the way up to B means cover the whole range from a low point to a high point.","zh":"由 A 一直到 B，是指涵蓋由低點到高點的整個範圍。"},{"en":"A beginner course may go from simple greetings all the way up to short conversations.","zh":"初學課程可能由簡單問候語一直到短對話。"},{"en":"This phrase shows that the learner must move through many levels or examples.","zh":"這個短語顯示學習者必須經過很多層級或例子。"},{"en":"It emphasises the full range, not just the beginning and end.","zh":"它強調完整範圍，而不只是開始和結束。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":2},{"front":"have been around for","meaning":"已存在了……時間","examples":[{"en":"Times tables have been around for a very long time.","zh":"乘數表已存在了很長時間。"},{"en":"Have been around for means have existed for a certain period.","zh":"已存在了某段時間，是指某物已經存在某個時期。"},{"en":"Public libraries have been around for many years because communities need shared knowledge.","zh":"公共圖書館已存在多年，因為社區需要共享知識。"},{"en":"If a teaching tool has been around for centuries, it has probably been useful in many societies.","zh":"如果一種教學工具已存在數百年，它很可能在許多社會中有用。"},{"en":"This phrase describes how long something has existed.","zh":"這個短語描述某物存在了多久。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":2},{"front":"a very long time","meaning":"很長時間","examples":[{"en":"The times table has been used for a very long time.","zh":"乘數表已被使用很長時間。"},{"en":"A very long time means a long period, often many years or even centuries.","zh":"很長時間，是指很久的一段時期，常常是多年甚至數百年。"},{"en":"People have used paper money for a very long time, though digital payment is now common.","zh":"人們使用紙幣已有很長時間，雖然現在電子支付很普遍。"},{"en":"When something lasts a very long time, it often becomes part of tradition.","zh":"當某事持續很長時間，它常成為傳統的一部分。"},{"en":"This phrase emphasises duration.","zh":"這個短語強調持續時間。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":2},{"front":"the oldest known tables","meaning":"已知最古老的表格","examples":[{"en":"The oldest known tables using base-10 numbers were found in China.","zh":"使用十進制數字的已知最古老表格在中國被發現。"},{"en":"The oldest known tables are the earliest tables that scholars have discovered and identified.","zh":"已知最古老的表格，是學者已發現並確認的最早表格。"},{"en":"A museum may display the oldest known map of a city if no earlier one has survived.","zh":"如果沒有更早地圖保存下來，博物館可能展示某城市已知最古老地圖。"},{"en":"Discovering the oldest known tables helps historians understand early mathematics.","zh":"發現已知最古老表格幫助歷史學家理解早期數學。"},{"en":"This phrase does not mean older tables never existed; it means these are the oldest we currently know.","zh":"這個短語不是指更古老表格從未存在，而是指目前已知最古老。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":2},{"front":"base-10 numbers","meaning":"十進制數字","examples":[{"en":"The oldest known tables used base-10 numbers.","zh":"已知最古老表格使用十進制數字。"},{"en":"Base-10 numbers are numbers organised around tens, using digits from 0 to 9.","zh":"十進制數字是以十為基礎、使用 0 至 9 數字組成的數字。"},{"en":"In base-10, the number 345 means 3 hundreds, 4 tens, and 5 ones.","zh":"在十進制中，345 表示 3 個百、4 個十和 5 個一。"},{"en":"Base-10 is easy to use partly because humans commonly count with ten fingers.","zh":"十進制容易使用，部分原因是人類常用十隻手指數數。"},{"en":"This phrase refers to the decimal number system.","zh":"這個短語指十進位數字系統。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":2},{"front":"the base that is now used","meaning":"現時使用的進位制","examples":[{"en":"Base 10 is the base that is now used everywhere in the world.","zh":"十進制是現時世界各地使用的進位制。"},{"en":"The base that is now used means the number system currently used as the standard.","zh":"現時使用的進位制，是指目前被作為標準使用的數字系統。"},{"en":"In most shops, prices are written in base 10 because that is the system people use daily.","zh":"在大多數商店，價格用十進制寫出，因為那是人們日常使用的系統。"},{"en":"A common number base makes trade, education, and record-keeping easier.","zh":"共同的數字進位制令貿易、教育和記錄更容易。"},{"en":"This phrase points to the system accepted in present-day practice.","zh":"這個短語指出當前實際使用中被接受的系統。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":2},{"front":"bamboo strips","meaning":"竹簡","examples":[{"en":"The ancient tables were written on bamboo strips.","zh":"古代表格寫在竹簡上。"},{"en":"Bamboo strips are thin pieces of bamboo that people once used for writing.","zh":"竹簡是古人用來書寫的薄竹片。"},{"en":"Before paper was common, records could be written on bamboo strips and tied together.","zh":"在紙張普及前，記錄可以寫在竹簡上並綁在一起。"},{"en":"Bamboo strips helped preserve ancient texts, including mathematical information.","zh":"竹簡幫助保存古代文本，包括數學資料。"},{"en":"This phrase refers to an early writing material.","zh":"這個短語指早期書寫材料。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":2},{"front":"date from","meaning":"追溯至","examples":[{"en":"The bamboo strips date from 305 BC.","zh":"這些竹簡可追溯至公元前 305 年。"},{"en":"Date from means come from or belong to a particular time in history.","zh":"追溯至，是指來自或屬於歷史上某個特定時間。"},{"en":"This old temple may date from the 1700s.","zh":"這座古寺可能追溯至十八世紀。"},{"en":"If an object dates from an early period, it can teach historians about that age.","zh":"如果一件物件追溯至早期，它可以教歷史學家認識那個年代。"},{"en":"This phrase identifies historical origin by time.","zh":"這個短語以時間指出歷史來源。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":2},{"front":"305 BC","meaning":"公元前305年","examples":[{"en":"The oldest known tables date from 305 BC.","zh":"已知最古老表格可追溯至公元前 305 年。"},{"en":"305 BC means 305 years before the traditional birth year of Christ.","zh":"公元前 305 年，是指傳統基督誕生年份之前 305 年。"},{"en":"A text from 305 BC is more than two thousand years old.","zh":"來自公元前 305 年的文本已有二千多年歷史。"},{"en":"Dates such as 305 BC help historians place ancient discoveries in order.","zh":"公元前 305 年這類日期幫助歷史學家把古代發現按時間排序。"},{"en":"This phrase gives a precise ancient date.","zh":"這個短語給出精確古代日期。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":2},{"front":"be found in","meaning":"在……被發現","examples":[{"en":"The bamboo strips were found in China.","zh":"這些竹簡在中國被發現。"},{"en":"To be found in a place means to be discovered or located there.","zh":"在某地被發現，是指在那裡被找到或位於那裡。"},{"en":"Fossils may be found in rocks near an old riverbed.","zh":"化石可能在舊河床附近的岩石中被發現。"},{"en":"Where something is found can help explain its history and cultural background.","zh":"某物在哪裡被發現，有助解釋其歷史和文化背景。"},{"en":"This phrase connects an object with its discovery location.","zh":"這個短語把物件與其發現地點連接起來。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":2},{"front":"European cultures","meaning":"歐洲文化","examples":[{"en":"In many European cultures, the times table is named after Pythagoras.","zh":"在許多歐洲文化中，乘數表以畢達哥拉斯命名。"},{"en":"European cultures are the languages, traditions, histories, and ideas of European societies.","zh":"歐洲文化是歐洲社會的語言、傳統、歷史和思想。"},{"en":"European cultures may share some ancient Greek and Roman influences.","zh":"歐洲文化可能共享一些古希臘和古羅馬影響。"},{"en":"A name used across European cultures can show how ideas spread through education.","zh":"在不同歐洲文化中使用的名稱，可以顯示思想如何透過教育傳播。"},{"en":"This phrase refers to cultural traditions across Europe, not one single country.","zh":"這個短語指歐洲各地文化傳統，而不是單一國家。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":2},{"front":"be named after","meaning":"以……命名","examples":[{"en":"The times table is named after Pythagoras in many languages.","zh":"在很多語言中，乘數表以畢達哥拉斯命名。"},{"en":"To be named after someone means to receive a name in honour of that person.","zh":"以某人命名，是指為了紀念或尊重那個人而使用其名字。"},{"en":"A school may be named after a respected teacher who served the community.","zh":"學校可能以一位服務社區的受尊敬老師命名。"},{"en":"Naming something after a famous figure can show respect or historical influence.","zh":"以名人命名某物可以表示尊重或歷史影響。"},{"en":"This phrase explains where a name comes from.","zh":"這個短語解釋名稱來源。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":3},{"front":"Ancient Greek","meaning":"古希臘的","examples":[{"en":"Pythagoras was an Ancient Greek mathematician and philosopher.","zh":"畢達哥拉斯是一位古希臘數學家和哲學家。"},{"en":"Ancient Greek means belonging to the civilisation of Greece in ancient times.","zh":"古希臘的，是指屬於古代希臘文明。"},{"en":"Ancient Greek thinkers influenced mathematics, philosophy, politics, and science.","zh":"古希臘思想家影響了數學、哲學、政治和科學。"},{"en":"Many modern academic words come from Ancient Greek roots.","zh":"許多現代學術詞語來自古希臘詞根。"},{"en":"This phrase describes a historical and cultural origin.","zh":"這個短語描述歷史和文化來源。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":3},{"front":"mathematician and philosopher","meaning":"數學家及哲學家","examples":[{"en":"Pythagoras was a mathematician and philosopher.","zh":"畢達哥拉斯是一位數學家及哲學家。"},{"en":"A mathematician and philosopher is someone who studies numbers and also deep questions about knowledge, truth, or life.","zh":"數學家及哲學家，是研究數字，也研究知識、真理或人生深層問題的人。"},{"en":"A thinker may be both a mathematician and philosopher if they study logic and the nature of reality.","zh":"如果思想家研究邏輯和現實本質，他可能既是數學家也是哲學家。"},{"en":"Ancient scholars often worked across several fields rather than one narrow subject.","zh":"古代學者常跨越幾個領域工作，而不是只限一個狹窄科目。"},{"en":"This phrase describes a person with both mathematical and philosophical interests.","zh":"這個短語描述同時對數學和哲學有興趣的人。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":3},{"front":"be called","meaning":"被稱為","examples":[{"en":"The table is called the Table of Pythagoras in many languages.","zh":"在很多語言中，這張表被稱為畢達哥拉斯表。"},{"en":"To be called something means to have that name.","zh":"被稱為某物，是指有那個名稱。"},{"en":"A teacher may be called “Miss Chan” by her students.","zh":"老師可能被學生稱為「陳老師」。"},{"en":"Different cultures may call the same object by different names.","zh":"不同文化可能用不同名稱稱呼同一物件。"},{"en":"This phrase introduces a name or label.","zh":"這個短語引入名稱或標籤。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":3},{"front":"the Table of Pythagoras","meaning":"畢達哥拉斯表","examples":[{"en":"The multiplication table is called the Table of Pythagoras in French and Italian.","zh":"在法文和意大利文中，乘法表被稱為畢達哥拉斯表。"},{"en":"The Table of Pythagoras is another name for the multiplication table in some languages.","zh":"畢達哥拉斯表是在一些語言中對乘法表的另一稱呼。"},{"en":"A French child may hear the name Table of Pythagoras when learning multiplication.","zh":"法國孩子學乘法時，可能聽到畢達哥拉斯表這個名稱。"},{"en":"The name links a basic school tool with an ancient mathematical figure.","zh":"這個名稱把一種基本學校工具與古代數學人物連接起來。"},{"en":"This phrase shows how historical names can survive in education.","zh":"這個短語顯示歷史名稱如何在教育中保存下來。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":3},{"front":"in many languages","meaning":"在很多語言中","examples":[{"en":"The times table has a similar name in many languages.","zh":"乘數表在很多語言中有相似名稱。"},{"en":"In many languages means across several different languages.","zh":"在很多語言中，是指跨越幾種不同語言。"},{"en":"The word “school” has related forms in many languages because ideas and words travel.","zh":"“school” 這個詞在很多語言中有相關形式，因為思想和詞語會傳播。"},{"en":"If a term appears in many languages, it may reflect shared history or education.","zh":"如果術語出現在很多語言中，它可能反映共同歷史或教育。"},{"en":"This phrase stresses broad linguistic spread.","zh":"這個短語強調廣泛語言傳播。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":3},{"front":"including French and Italian","meaning":"包括法文和意大利文","examples":[{"en":"The name is used in many languages, including French and Italian.","zh":"這個名稱在很多語言中使用，包括法文和意大利文。"},{"en":"Including French and Italian means French and Italian are examples within a larger group.","zh":"包括法文和意大利文，是指法文和意大利文是較大群體中的例子。"},{"en":"Many European students learn foreign languages, including French and Italian.","zh":"許多歐洲學生學外語，包括法文和意大利文。"},{"en":"The phrase gives examples without claiming the list is complete.","zh":"這個短語給出例子，而不聲稱列表完整。"},{"en":"It helps readers understand the range more concretely.","zh":"它幫助讀者更具體理解範圍。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":3},{"front":"in his book","meaning":"在他的書中","examples":[{"en":"John Leslie made this recommendation in his book The Philosophy of Arithmetic.","zh":"John Leslie 在他的書《算術哲學》中提出這項建議。"},{"en":"In his book means in the written work he authored.","zh":"在他的書中，是指在他所寫的作品中。"},{"en":"A scientist may explain a theory in his book before it becomes widely known.","zh":"科學家可能在他的書中解釋一個理論，之後該理論才廣為人知。"},{"en":"Mentioning a book gives readers the source of an opinion or recommendation.","zh":"提到一本書能給讀者某意見或建議的來源。"},{"en":"This phrase identifies where an idea was written.","zh":"這個短語指出一個想法寫在哪裡。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":3},{"front":"The Philosophy of Arithmetic","meaning":"《算術哲學》","examples":[{"en":"The Philosophy of Arithmetic was written by John Leslie.","zh":"《算術哲學》由 John Leslie 撰寫。"},{"en":"The Philosophy of Arithmetic is the title of a book about arithmetic and mathematical thinking.","zh":"《算術哲學》是一本關於算術和數學思維的書名。"},{"en":"A teacher might quote The Philosophy of Arithmetic when discussing older ideas about maths education.","zh":"老師討論數學教育的舊觀點時，可能引用《算術哲學》。"},{"en":"Book titles help readers locate the source of historical claims.","zh":"書名幫助讀者找到歷史主張的來源。"},{"en":"This title connects arithmetic with deeper questions about how it should be learned.","zh":"這個書名把算術與它應如何被學習的深層問題連接起來。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":3},{"front":"recommend that","meaning":"建議","examples":[{"en":"John Leslie recommended that young pupils memorise a large times table.","zh":"John Leslie 建議年幼學生背熟一個大型乘數表。"},{"en":"Recommend that means advise or suggest that someone should do something.","zh":"建議某人做某事，是指提出意見或認為某人應該做。"},{"en":"A doctor may recommend that a patient sleep earlier and drink more water.","zh":"醫生可能建議病人早睡並多喝水。"},{"en":"Recommendations often reflect what experts think will be useful or beneficial.","zh":"建議通常反映專家認為甚麼有用或有益。"},{"en":"This phrase introduces advice rather than a command.","zh":"這個短語引入建議，而不是命令。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":3},{"front":"young pupils","meaning":"年幼學生","examples":[{"en":"John Leslie recommended that young pupils memorise the times table.","zh":"John Leslie 建議年幼學生背熟乘數表。"},{"en":"Young pupils are children in the early years of school.","zh":"年幼學生是學校早期階段的孩子。"},{"en":"Young pupils often need repeated practice when learning spelling or arithmetic.","zh":"年幼學生學拼寫或算術時，通常需要反覆練習。"},{"en":"Because young pupils are still building basic skills, teaching methods must be clear and patient.","zh":"因為年幼學生仍在建立基本技能，教學方法必須清楚而有耐性。"},{"en":"This phrase refers to schoolchildren, not university students.","zh":"這個短語指中小學兒童，而不是大學生。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":3},{"front":"memorise the times table","meaning":"背熟乘數表","examples":[{"en":"Educators want children to memorise the times table.","zh":"教育工作者希望孩子背熟乘數表。"},{"en":"To memorise the times table means to learn multiplication facts so well that you can recall them quickly.","zh":"背熟乘數表，是指把乘法事實學到能快速回憶出來。"},{"en":"A child who has memorised the times table can answer 9 × 7 without counting.","zh":"背熟乘數表的孩子不用數也能回答 9 × 7。"},{"en":"Memorising basic facts can make harder maths less stressful.","zh":"背熟基本事實可以令較難數學較少壓力。"},{"en":"This phrase refers to remembering multiplication answers by heart.","zh":"這個短語指把乘法答案記在心中。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":4},{"front":"up to 25 × 25","meaning":"直至25乘25","examples":[{"en":"John Leslie recommended memorising the times table up to 25 × 25.","zh":"John Leslie 建議背熟直至 25 × 25 的乘數表。"},{"en":"Up to 25 × 25 means including all multiplication facts from smaller numbers through 25 times 25.","zh":"直至 25 × 25，是指包括由較小數字一直到 25 乘 25 的所有乘法事實。"},{"en":"A student who learns up to 25 × 25 must know answers beyond the usual 12 × 12 table.","zh":"學到直至 25 × 25 的學生，必須知道超出常見 12 × 12 表的答案。"},{"en":"A larger table requires more memory and more practice.","zh":"更大的乘法表需要更多記憶和更多練習。"},{"en":"This phrase gives the upper limit of what should be memorised.","zh":"這個短語給出應背熟內容的上限。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":4},{"front":"nowadays","meaning":"現今","examples":[{"en":"Nowadays, educators have a different view of what children should memorise.","zh":"現今，教育工作者對兒童應背熟甚麼有不同看法。"},{"en":"Nowadays means at the present time or in modern times.","zh":"現今，是指目前或現代。"},{"en":"Nowadays, many students use calculators, but they still need basic number sense.","zh":"現今，許多學生使用計算機，但仍需要基本數感。"},{"en":"This word often introduces a contrast between the past and the present.","zh":"這個詞常引入過去與現在的對比。"},{"en":"It helps show how opinions or habits have changed.","zh":"它幫助顯示觀點或習慣如何改變。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":4},{"front":"educators generally believe","meaning":"教育工作者普遍認為","examples":[{"en":"Educators generally believe that children should memorise smaller times tables.","zh":"教育工作者普遍認為孩子應背熟較小範圍的乘數表。"},{"en":"Educators generally believe means most education professionals think this is true or useful.","zh":"教育工作者普遍認為，是指大多數教育專業人士認為某事真實或有用。"},{"en":"Educators generally believe that reading practice should be regular, not rushed before exams.","zh":"教育工作者普遍認為閱讀練習應定期進行，而不是考前匆忙完成。"},{"en":"General agreement among educators can influence school targets and classroom methods.","zh":"教育工作者的普遍共識會影響學校目標和課堂方法。"},{"en":"This phrase presents a common professional view.","zh":"這個短語呈現常見專業看法。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":4},{"front":"it is important for children to","meaning":"對兒童來說，……是重要的","examples":[{"en":"It is important for children to memorise the multiplication table.","zh":"對兒童來說，背熟乘法表是重要的。"},{"en":"It is important for children to do something means the action matters for their learning or development.","zh":"對兒童來說做某事是重要的，是指該行動對他們的學習或發展有價值。"},{"en":"It is important for children to sleep enough before school.","zh":"對兒童來說，上學前睡眠充足是重要的。"},{"en":"Important skills learned early can support later confidence and independence.","zh":"早期學會的重要技能可以支持之後的信心和獨立。"},{"en":"This phrase explains why an action is valuable for young learners.","zh":"這個短語解釋某行動對年幼學習者為何有價值。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":4},{"front":"up to 12 × 12","meaning":"直至12乘12","examples":[{"en":"Some educators believe children should know the times table up to 12 × 12.","zh":"有些教育工作者認為孩子應知道直至 12 × 12 的乘數表。"},{"en":"Up to 12 × 12 means including multiplication facts from smaller numbers through 12 times 12.","zh":"直至 12 × 12，是指包括由較小數字一直到 12 乘 12 的乘法事實。"},{"en":"A child who knows up to 12 × 12 can answer 11 × 12 and 12 × 12 quickly.","zh":"知道直至 12 × 12 的孩子可以快速回答 11 × 12 和 12 × 12。"},{"en":"This limit is smaller than 25 × 25, so it is more realistic for many pupils.","zh":"這個上限比 25 × 25 小，因此對許多學生較現實。"},{"en":"This phrase gives a learning target in multiplication.","zh":"這個短語給出乘法學習目標。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":4},{"front":"the current aim","meaning":"目前目標","examples":[{"en":"The current aim in the UK is for pupils to know their times tables by age nine.","zh":"英國目前目標是學生在九歲前熟記乘數表。"},{"en":"The current aim means the goal that is being used at present.","zh":"目前目標，是指現在正在使用的目標。"},{"en":"The current aim of the reading programme is for students to finish one book a month.","zh":"閱讀計劃目前目標是學生每月完成一本書。"},{"en":"A current aim may change when schools or governments revise education policy.","zh":"當學校或政府修訂教育政策，目前目標可能改變。"},{"en":"This phrase describes today’s target, not an old one.","zh":"這個短語描述今日目標，而不是舊目標。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":4},{"front":"school pupils","meaning":"中小學生","examples":[{"en":"School pupils in the UK are expected to learn their times tables.","zh":"英國中小學生被期望學習乘數表。"},{"en":"School pupils are children or teenagers who attend school.","zh":"中小學生是就讀學校的兒童或青少年。"},{"en":"School pupils often practise maths, reading, writing, and science in daily lessons.","zh":"中小學生通常在日常課堂中練習數學、閱讀、寫作和科學。"},{"en":"If school pupils learn key facts early, later subjects may feel easier.","zh":"如果中小學生早期學會關鍵知識，之後科目可能感覺更容易。"},{"en":"This phrase refers to learners in primary or secondary school.","zh":"這個短語指小學或中學學習者。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":4},{"front":"know all their times tables","meaning":"熟記所有乘數表","examples":[{"en":"Pupils are expected to know all their times tables up to 12 × 12.","zh":"學生被期望熟記直至 12 × 12 的所有乘數表。"},{"en":"To know all their times tables means to remember every multiplication fact in the required range.","zh":"熟記所有乘數表，是指記得指定範圍內每個乘法事實。"},{"en":"A pupil who knows all their times tables can answer 8 × 9 without using fingers.","zh":"熟記所有乘數表的學生不用手指也能回答 8 × 9。"},{"en":"Knowing these facts saves time when solving fractions, division, and word problems.","zh":"熟記這些事實在解分數、除法和文字題時能節省時間。"},{"en":"This phrase means more than recognising the table; it means quick recall.","zh":"這個短語不只是認得表格，而是能快速回憶答案。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":4},{"front":"by the age of nine","meaning":"到九歲時","examples":[{"en":"The aim is for pupils to know their times tables by the age of nine.","zh":"目標是學生到九歲時熟記乘數表。"},{"en":"By the age of nine means before or when a child reaches nine years old.","zh":"到九歲時，是指在孩子九歲之前或九歲那時。"},{"en":"Some children can read short chapter books by the age of nine.","zh":"有些孩子到九歲時能閱讀短篇章節書。"},{"en":"Age targets help schools decide when skills should normally be secure.","zh":"年齡目標幫助學校決定技能通常應在何時穩固。"},{"en":"This phrase gives a deadline based on age.","zh":"這個短語給出以年齡為基礎的期限。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":4},{"front":"even as adults","meaning":"即使成年後","examples":[{"en":"Many people do not know all their times tables, even as adults.","zh":"許多人即使成年後也不熟記所有乘數表。"},{"en":"Even as adults means despite being fully grown and no longer children.","zh":"即使成年後，是指雖然已完全長大、不再是孩子。"},{"en":"Some people still feel nervous about public speaking, even as adults.","zh":"有些人即使成年後仍對公開演說感到緊張。"},{"en":"Skills missed in childhood can remain difficult later in life.","zh":"童年未掌握的技能可能在日後仍然困難。"},{"en":"This phrase shows that a childhood problem may continue into adulthood.","zh":"這個短語顯示童年問題可能延續到成年。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":4},{"front":"politicians have been asked","meaning":"政治人物曾被問及","examples":[{"en":"Some politicians have been asked arithmetical questions in public.","zh":"有些政治人物曾在公開場合被問及算術問題。"},{"en":"Politicians have been asked means public officials or candidates were questioned by someone.","zh":"政治人物曾被問及，是指公職人員或候選人被人提問。"},{"en":"Politicians may be asked difficult questions during interviews or school visits.","zh":"政治人物可能在訪問或學校探訪中被問及困難問題。"},{"en":"Public questions can test both knowledge and the ability to stay calm.","zh":"公開提問可以測試知識，也測試保持冷靜的能力。"},{"en":"This phrase describes politicians being put under public scrutiny.","zh":"這個短語描述政治人物受到公眾檢視。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":5},{"front":"arithmetical questions","meaning":"算術問題","examples":[{"en":"Politicians have been asked arithmetical questions of this kind.","zh":"政治人物曾被問及這類算術問題。"},{"en":"Arithmetical questions are questions involving basic calculations such as addition, subtraction, multiplication, or division.","zh":"算術問題是涉及加、減、乘、除等基本計算的問題。"},{"en":"“What is 8 × 7?” is an arithmetical question.","zh":"「8 × 7 是多少？」就是一條算術問題。"},{"en":"Arithmetical questions can become stressful when asked suddenly in public.","zh":"當算術問題在公開場合突然被問及，它們會變得有壓力。"},{"en":"This phrase refers to calculation questions rather than advanced mathematics.","zh":"這個短語指計算問題，而不是高階數學。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":5},{"front":"of this kind","meaning":"這類的","examples":[{"en":"Some politicians have been asked questions of this kind.","zh":"有些政治人物曾被問及這類問題。"},{"en":"Of this kind means of this type or category.","zh":"這類的，是指屬於這個種類或類別。"},{"en":"Students often struggle with questions of this kind if they rush the calculation.","zh":"如果學生匆忙計算，常會在這類題目上吃力。"},{"en":"This phrase refers back to an example already mentioned.","zh":"這個短語指回已提到的例子。"},{"en":"It helps avoid repeating the full description of the question type.","zh":"它有助避免重複完整描述問題類型。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":5},{"front":"give the answer to","meaning":"給出……的答案","examples":[{"en":"Stephen Byers was asked to give the answer to 7 × 8.","zh":"Stephen Byers 被要求給出 7 × 8 的答案。"},{"en":"To give the answer to a question means to state the correct response.","zh":"給出某問題的答案，是指說出正確回應。"},{"en":"A student may be asked to give the answer to a mental maths question without writing it down.","zh":"學生可能被要求不用寫下來，就給出心算題的答案。"},{"en":"Giving an answer quickly can be harder when people are watching.","zh":"當有人看着時，快速給出答案會更困難。"},{"en":"This phrase focuses on producing the response, not just understanding the question.","zh":"這個短語聚焦說出回應，而不只是理解問題。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":5},{"front":"get the answer wrong","meaning":"答錯","examples":[{"en":"Stephen Byers got the answer wrong.","zh":"Stephen Byers 答錯了。"},{"en":"To get the answer wrong means to give an incorrect answer.","zh":"答錯，是指給出不正確答案。"},{"en":"A student may get the answer wrong if they confuse 6 × 8 with 7 × 8.","zh":"如果學生混淆 6 × 8 和 7 × 8，就可能答錯。"},{"en":"Pressure can make people get answers wrong even when they know the method.","zh":"壓力會令人即使知道方法也答錯。"},{"en":"This phrase describes an error in response.","zh":"這個短語描述回答上的錯誤。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":5},{"front":"rather than","meaning":"而不是","examples":[{"en":"He said 54 rather than 56.","zh":"他說 54，而不是 56。"},{"en":"Rather than means instead of, showing a contrast between what happened and what was correct or expected.","zh":"而不是表示 instead of，用來對比實際發生的事與正確或預期的事。"},{"en":"A student wrote “their” rather than “there” in the sentence.","zh":"學生在句子中寫了 “their”，而不是 “there”。"},{"en":"This phrase makes the contrast between the wrong choice and the right choice clear.","zh":"這個短語清楚顯示錯誤選擇與正確選擇之間的對比。"},{"en":"It is useful when explaining mistakes or alternatives.","zh":"它適合用來解釋錯誤或替代選項。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":5},{"front":"laugh at someone","meaning":"嘲笑某人","examples":[{"en":"Everyone laughed at Stephen Byers when he got the answer wrong.","zh":"Stephen Byers 答錯時，所有人都嘲笑他。"},{"en":"To laugh at someone means to make fun of them because of something they did.","zh":"嘲笑某人，是指因某人做了某事而取笑他。"},{"en":"Classmates should not laugh at a student who makes a mistake while reading aloud.","zh":"同學不應嘲笑朗讀時犯錯的學生。"},{"en":"Being laughed at can make people feel embarrassed and more anxious next time.","zh":"被嘲笑會令人尷尬，並在下次更焦慮。"},{"en":"This phrase often describes unkind laughter directed at a person.","zh":"這個短語常描述針對某人的不友善笑聲。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":5},{"front":"UK Chancellor","meaning":"英國財政大臣","examples":[{"en":"George Osborne was the UK Chancellor at the time.","zh":"George Osborne 當時是英國財政大臣。"},{"en":"The UK Chancellor is the government minister responsible for the country’s finances and economic policy.","zh":"英國財政大臣是負責國家財政和經濟政策的政府部長。"},{"en":"A UK Chancellor gives budget speeches about tax, spending, and public money.","zh":"英國財政大臣會發表關於稅收、開支和公共財政的財政預算演說。"},{"en":"Because the role involves numbers, people may expect the Chancellor to answer arithmetic questions confidently.","zh":"因為這個職位涉及數字，人們可能期望財政大臣能自信回答算術問題。"},{"en":"This phrase names a senior British government position.","zh":"這個短語命名英國政府中的高級職位。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":5},{"front":"ask someone the same question","meaning":"問某人同一條問題","examples":[{"en":"A young boy asked George Osborne the same question.","zh":"一名小男孩問 George Osborne 同一條問題。"},{"en":"To ask someone the same question means to give that person a question that another person has already been asked.","zh":"問某人同一條問題，是指把另一人已被問過的問題問那個人。"},{"en":"A teacher may ask two students the same question to compare their explanations.","zh":"老師可能問兩名學生同一條問題，以比較他們的解釋。"},{"en":"When the same question is asked again, people may compare the two answers.","zh":"當同一條問題再次被問，人們可能比較兩個答案。"},{"en":"This phrase shows repetition of a question across different people.","zh":"這個短語顯示問題在不同人之間重複。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":5},{"front":"pass A-level maths","meaning":"通過英國高級程度數學科考試","examples":[{"en":"George Osborne had passed A-level maths.","zh":"George Osborne 已通過英國高級程度數學科考試。"},{"en":"To pass A-level maths means to successfully complete the advanced mathematics exam taken by many UK students before university.","zh":"通過英國高級程度數學科考試，是指成功完成許多英國學生上大學前應考的高階數學考試。"},{"en":"A student who passes A-level maths has studied topics beyond basic arithmetic.","zh":"通過 A-level 數學的學生已學過超出基本算術的課題。"},{"en":"Passing a higher maths exam makes it surprising if someone avoids a simple multiplication question.","zh":"通過高階數學考試的人避開簡單乘法問題，會令人意外。"},{"en":"This phrase refers to a recognised academic achievement in mathematics.","zh":"這個短語指數學方面受承認的學術成就。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":5},{"front":"be in charge of","meaning":"負責；掌管","examples":[{"en":"George Osborne was in charge of the UK’s economic policies.","zh":"George Osborne 負責英國的經濟政策。"},{"en":"To be in charge of something means to be responsible for managing or leading it.","zh":"負責某事，是指有責任管理或領導它。"},{"en":"A class monitor may be in charge of collecting homework before the lesson.","zh":"班長可能負責上課前收功課。"},{"en":"People in charge are expected to make decisions and answer questions about their area.","zh":"負責的人被期望就自己的範疇作決定和回答問題。"},{"en":"This phrase describes responsibility and authority.","zh":"這個短語描述責任和權力。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":5},{"front":"economic policies","meaning":"經濟政策","examples":[{"en":"The Chancellor was in charge of the UK’s economic policies.","zh":"財政大臣負責英國的經濟政策。"},{"en":"Economic policies are government plans about money, tax, spending, jobs, trade, and growth.","zh":"經濟政策是政府關於金錢、稅收、開支、就業、貿易和增長的計劃。"},{"en":"A government may change economic policies to reduce unemployment.","zh":"政府可能改變經濟政策來降低失業率。"},{"en":"Economic policies affect families through prices, wages, taxes, and public services.","zh":"經濟政策透過物價、工資、稅收和公共服務影響家庭。"},{"en":"This phrase refers to decisions that shape a country’s economy.","zh":"這個短語指塑造一國經濟的決定。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":6},{"front":"at the time","meaning":"當時","examples":[{"en":"George Osborne was Chancellor at the time.","zh":"George Osborne 當時是財政大臣。"},{"en":"At the time means during that particular period.","zh":"當時，是指在那個特定時期。"},{"en":"I was living near the school at the time, so I walked there every day.","zh":"我當時住在學校附近，所以每天走路上學。"},{"en":"This phrase helps explain the situation when an event happened.","zh":"這個短語幫助解釋事件發生時的情況。"},{"en":"It connects a person’s role or condition with a specific moment in the past.","zh":"它把某人的角色或狀況與過去特定時刻連接起來。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":6},{"front":"you would expect someone to","meaning":"你會預期某人會……","examples":[{"en":"You would expect the Chancellor to know the answer.","zh":"你會預期財政大臣知道答案。"},{"en":"You would expect someone to do something means it seems reasonable to think they should be able to do it.","zh":"你會預期某人做某事，是指認為他們應該有能力做到是合理的。"},{"en":"You would expect a doctor to know how to check a patient’s pulse.","zh":"你會預期醫生知道如何檢查病人脈搏。"},{"en":"Expectations come from a person’s role, training, or experience.","zh":"期望來自一個人的角色、訓練或經驗。"},{"en":"This phrase often introduces a contrast between what seems likely and what actually happens.","zh":"這個短語常引入看似合理的事與實際發生的事之間的對比。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":6},{"front":"make it a rule in life","meaning":"把……定為人生原則","examples":[{"en":"George Osborne said he had made it a rule in life not to answer such questions.","zh":"George Osborne 說他把不回答這類問題定為人生原則。"},{"en":"To make it a rule in life means to decide firmly to behave in a certain way whenever that situation appears.","zh":"把某事定為人生原則，是指堅定決定在該情況出現時都以某種方式行動。"},{"en":"A person may make it a rule in life never to reply to angry messages immediately.","zh":"一個人可能把不立即回覆憤怒訊息定為人生原則。"},{"en":"Such rules can protect people from pressure, embarrassment, or poor decisions.","zh":"這類原則可以保護人免受壓力、尷尬或差劣決定影響。"},{"en":"This phrase describes a personal principle.","zh":"這個短語描述個人原則。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":6},{"front":"answer such questions","meaning":"回答這類問題","examples":[{"en":"He refused to answer such questions in public.","zh":"他拒絕在公開場合回答這類問題。"},{"en":"Answer such questions means respond to questions of this type.","zh":"回答這類問題，是指回應這種類型的問題。"},{"en":"Some students avoid answering such questions aloud because they fear making mistakes.","zh":"有些學生避免大聲回答這類問題，因為害怕犯錯。"},{"en":"If a person refuses to answer such questions, they may be trying to avoid pressure.","zh":"如果一個人拒絕回答這類問題，他可能是在避免壓力。"},{"en":"This phrase refers back to a type of question already mentioned.","zh":"這個短語指回已提到的某類問題。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":6},{"front":"refuse to answer","meaning":"拒絕回答","examples":[{"en":"George Osborne refused to answer the arithmetic question.","zh":"George Osborne 拒絕回答那條算術問題。"},{"en":"To refuse to answer means to choose not to give a response.","zh":"拒絕回答，是指選擇不作回應。"},{"en":"A student may refuse to answer if they feel embarrassed or unprepared.","zh":"如果學生感到尷尬或未準備好，可能拒絕回答。"},{"en":"Refusing to answer can protect someone from making a public mistake.","zh":"拒絕回答可以保護某人免於在公開場合犯錯。"},{"en":"This phrase shows a deliberate decision not to respond.","zh":"這個短語顯示不回應是有意決定。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":6},{"front":"it is certainly true that","meaning":"的確是","examples":[{"en":"It is certainly true that some sums are harder than others.","zh":"的確，有些算術題比其他題目更難。"},{"en":"It is certainly true that means there is no real doubt about the statement.","zh":"的確是，是指該陳述幾乎沒有疑問。"},{"en":"It is certainly true that regular sleep helps students concentrate better.","zh":"的確，規律睡眠能幫助學生更好集中精神。"},{"en":"This phrase adds confidence before explaining a point.","zh":"這個短語在解釋重點前加入信心。"},{"en":"It often introduces a fact that the writer wants readers to accept.","zh":"它常引入作者希望讀者接受的事實。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":6},{"front":"some sums are much harder than others","meaning":"有些算術題比其他題目難得多","examples":[{"en":"Some sums are much harder than others.","zh":"有些算術題比其他題目難得多。"},{"en":"Some sums are much harder than others means certain calculations are more difficult to learn, remember, or answer quickly.","zh":"有些算術題比其他題目難得多，是指某些計算較難學、較難記或較難快速回答。"},{"en":"A child may find 2 × 5 easy but 7 × 8 much harder.","zh":"孩子可能覺得 2 × 5 容易，但 7 × 8 難得多。"},{"en":"Differences in difficulty can affect confidence during mental maths.","zh":"難度差異會影響心算時的信心。"},{"en":"This phrase explains why not all multiplication facts feel equally simple.","zh":"這個短語解釋為何不是所有乘法事實都同樣簡單。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":6},{"front":"research has shown that","meaning":"研究顯示","examples":[{"en":"Research has shown that some multiplication sums are especially difficult.","zh":"研究顯示有些乘法算式特別困難。"},{"en":"Research has shown that means studies have provided evidence for a claim.","zh":"研究顯示，是指研究為某主張提供了證據。"},{"en":"Research has shown that sleep affects memory and learning.","zh":"研究顯示睡眠會影響記憶和學習。"},{"en":"This phrase makes a statement sound supported by evidence, not just opinion.","zh":"這個短語令陳述聽起來由證據支持，而不只是意見。"},{"en":"It is common in academic and educational writing.","zh":"它常見於學術和教育寫作。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":6},{"front":"learning and remembering sums","meaning":"學習和記住算式","examples":[{"en":"Learning and remembering sums involving 6, 7, 8 and 9 can be difficult.","zh":"學習和記住涉及 6、7、8 和 9 的算式可能很困難。"},{"en":"Learning and remembering sums means understanding calculations and being able to recall their answers.","zh":"學習和記住算式，是指理解計算並能回憶其答案。"},{"en":"A student may learn a sum in class but fail to remember it during a test.","zh":"學生可能在課堂上學會一條算式，但在測驗中記不起。"},{"en":"Practice helps because learning and remembering are not always the same thing.","zh":"練習有幫助，因為學會和記住並不總是同一回事。"},{"en":"This phrase covers both first learning and later recall.","zh":"這個短語涵蓋最初學習和之後回憶。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":6},{"front":"involving 6, 7, 8 and 9","meaning":"涉及6、7、8和9的","examples":[{"en":"Sums involving 6, 7, 8 and 9 tend to be harder.","zh":"涉及 6、7、8 和 9 的算式往往較難。"},{"en":"Involving 6, 7, 8 and 9 means including these numbers in the calculation.","zh":"涉及 6、7、8 和 9，是指計算中包括這些數字。"},{"en":"A sum like 7 × 8 involves two numbers that many children find difficult.","zh":"7 × 8 這類算式涉及兩個許多孩子覺得困難的數字。"},{"en":"Calculations involving larger single-digit numbers may be harder to recall quickly.","zh":"涉及較大個位數的計算可能較難快速回憶。"},{"en":"This phrase specifies which numbers make the sums more challenging.","zh":"這個短語指出哪些數字令算式更具挑戰性。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":6},{"front":"tend to be harder than","meaning":"往往比……更難","examples":[{"en":"These sums tend to be harder than sums involving other numbers.","zh":"這些算式往往比涉及其他數字的算式更難。"},{"en":"Tend to be harder than means are usually more difficult than something else.","zh":"往往比某事更難，是指通常比另一事物更困難。"},{"en":"Long reading passages tend to be harder than short notices for beginners.","zh":"對初學者來說，長閱讀文章往往比短告示更難。"},{"en":"A pattern can be common even if there are exceptions.","zh":"即使有例外，一種模式仍可以很常見。"},{"en":"This phrase describes a general tendency, not an absolute rule.","zh":"這個短語描述一般傾向，而不是絕對規則。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":7},{"front":"sums involving other numbers","meaning":"涉及其他數字的算式","examples":[{"en":"Sums involving other numbers are often easier to remember.","zh":"涉及其他數字的算式通常較容易記住。"},{"en":"Sums involving other numbers are calculations using numbers outside the difficult group being discussed.","zh":"涉及其他數字的算式，是指使用正在討論的困難數字組以外數字的計算。"},{"en":"Children may find 2 × 4 easier than sums involving 7 and 8.","zh":"孩子可能覺得 2 × 4 比涉及 7 和 8 的算式容易。"},{"en":"Easier sums can build confidence before learners practise harder ones.","zh":"較容易算式可以在學習者練習較難題目前建立信心。"},{"en":"This phrase creates a contrast with the more difficult 6, 7, 8, and 9 sums.","zh":"這個短語與較困難的 6、7、8 和 9 算式形成對比。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":7},{"front":"be multiplied by each other","meaning":"互相相乘","examples":[{"en":"The sums are harder when 6, 7, 8 and 9 are multiplied by each other.","zh":"當 6、7、8 和 9 互相相乘時，算式會更難。"},{"en":"To be multiplied by each other means each number is used with another number in multiplication.","zh":"互相相乘，是指每個數字與另一個數字進行乘法運算。"},{"en":"When 7 is multiplied by 8, the answer is 56.","zh":"當 7 與 8 相乘，答案是 56。"},{"en":"Multiplying difficult numbers together can make recall slower and more stressful.","zh":"困難數字互相相乘會令回憶答案較慢且更有壓力。"},{"en":"This phrase describes how numbers are combined in multiplication.","zh":"這個短語描述數字如何在乘法中結合。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":7},{"front":"studies often find that","meaning":"研究經常發現","examples":[{"en":"Studies often find that 6 × 8 is the hardest sum.","zh":"研究經常發現 6 × 8 是最難的算式。"},{"en":"Studies often find that means repeated research commonly reaches this result.","zh":"研究經常發現，是指多項研究通常得出這個結果。"},{"en":"Studies often find that students remember words better when they meet them in clear examples.","zh":"研究經常發現，當學生在清楚例句中遇到字詞時，會記得更好。"},{"en":"When many studies point the same way, the claim becomes more convincing.","zh":"當許多研究指向同一方向，主張會更有說服力。"},{"en":"This phrase presents a repeated research finding.","zh":"這個短語呈現反覆出現的研究發現。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":7},{"front":"the hardest sum","meaning":"最難的算式","examples":[{"en":"Studies often find that 6 × 8 is the hardest sum.","zh":"研究經常發現 6 × 8 是最難的算式。"},{"en":"The hardest sum is the calculation that most people find most difficult among the group.","zh":"最難的算式，是在某組題目中最多人覺得最困難的計算。"},{"en":"In one class, the hardest sum may be the one most students answer slowly or wrongly.","zh":"在一班中，最難的算式可能是最多學生答得慢或答錯的那題。"},{"en":"A hard sum can cause hesitation because the answer is not recalled automatically.","zh":"困難算式會令人猶豫，因為答案不能自動回憶出來。"},{"en":"This phrase identifies the most difficult calculation.","zh":"這個短語指出最困難的計算。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":7},{"front":"not far behind","meaning":"相差不遠；緊隨其後","examples":[{"en":"Seven times eight is not far behind in difficulty.","zh":"7 乘 8 的難度也相差不遠。"},{"en":"Not far behind means almost as close, difficult, successful, or important as the first one.","zh":"相差不遠，是指幾乎和第一項一樣接近、困難、成功或重要。"},{"en":"If 6 × 8 is the hardest sum, 7 × 8 may be not far behind.","zh":"如果 6 × 8 是最難算式，7 × 8 可能緊隨其後。"},{"en":"The phrase shows that the second item is slightly lower but still very close.","zh":"這個短語顯示第二項稍低，但仍非常接近。"},{"en":"It is useful when ranking similar things.","zh":"它適合用於排列相似事物。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":7},{"front":"relatively difficult","meaning":"相對較難的","examples":[{"en":"Seven times eight is a relatively difficult sum.","zh":"7 乘 8 是一道相對較難的算式。"},{"en":"Relatively difficult means difficult compared with other similar things.","zh":"相對較難，是指與其他相似事物相比較困難。"},{"en":"A short essay may be relatively difficult if the topic is unfamiliar.","zh":"如果題目陌生，一篇短作文也可能相對較難。"},{"en":"A task can be easy for one person but relatively difficult for another.","zh":"一項任務對某人可能容易，但對另一人相對較難。"},{"en":"This phrase shows difficulty by comparison.","zh":"這個短語透過比較顯示難度。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":7},{"front":"it is unlikely that","meaning":"……是不大可能的","examples":[{"en":"It is unlikely that George Osborne did not know the answer.","zh":"George Osborne 不知道答案是不大可能的。"},{"en":"It is unlikely that means something probably is not true or probably will not happen.","zh":"某事是不大可能的，是指它大概不是真的或大概不會發生。"},{"en":"It is unlikely that a trained nurse would forget how to check a pulse.","zh":"受訓護士忘記如何檢查脈搏是不大可能的。"},{"en":"This phrase is used when evidence or common sense points against a possibility.","zh":"當證據或常識不支持某可能性時，會使用這個短語。"},{"en":"It presents doubt about an explanation.","zh":"它對某解釋表示懷疑。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":7},{"front":"there must be some other reason why","meaning":"一定另有原因解釋為何……","examples":[{"en":"There must be some other reason why he refused to answer.","zh":"他拒絕回答一定另有原因。"},{"en":"There must be some other reason why means another explanation is needed because the obvious one does not seem right.","zh":"一定另有原因解釋為何，是指因明顯解釋似乎不合理，所以需要另一個解釋。"},{"en":"If a good student leaves an easy question blank, there must be some other reason why.","zh":"如果好學生把容易問題留空，一定另有原因。"},{"en":"This phrase pushes the reader to look beyond the first explanation.","zh":"這個短語推動讀者超越第一個解釋去思考。"},{"en":"It is useful when behaviour seems surprising or illogical.","zh":"當行為看起來令人驚訝或不合邏輯時，它很有用。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":7},{"front":"put on the spot","meaning":"被迫即場回應；被置於尷尬位置","examples":[{"en":"George Osborne was being put on the spot.","zh":"George Osborne 被迫即場回應。"},{"en":"To be put on the spot means to be forced to answer or act immediately in a difficult public situation.","zh":"被迫即場回應，是指在困難的公開情況下被迫立即回答或行動。"},{"en":"A teacher may put a student on the spot by asking a hard question without warning.","zh":"老師不預先提醒就問難題，可能令學生被迫即場回應。"},{"en":"Being put on the spot can make even simple tasks feel stressful.","zh":"被置於尷尬位置會令即使簡單任務也變得有壓力。"},{"en":"This phrase describes sudden pressure to respond.","zh":"這個短語描述突然需要回應的壓力。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":7},{"front":"it is well known that","meaning":"眾所周知","examples":[{"en":"It is well known that pressure can affect performance.","zh":"眾所周知，壓力會影響表現。"},{"en":"It is well known that means many people already understand or accept the fact.","zh":"眾所周知，是指許多人已理解或接受該事實。"},{"en":"It is well known that lack of sleep makes concentration harder.","zh":"眾所周知，睡眠不足會令集中精神更困難。"},{"en":"This phrase introduces a widely accepted idea.","zh":"這個短語引入廣泛接受的想法。"},{"en":"It gives the writer’s point a sense of common knowledge.","zh":"它令作者觀點帶有常識感。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":7},{"front":"a lot of pressure to","meaning":"很大壓力去……","examples":[{"en":"There was a lot of pressure to answer the question correctly.","zh":"正確回答問題有很大壓力。"},{"en":"A lot of pressure to do something means strong stress or expectation to perform well.","zh":"很大壓力去做某事，是指有強烈壓力或期望要表現好。"},{"en":"A student may feel a lot of pressure to get full marks in a public quiz.","zh":"學生可能在公開問答中感到很大壓力要取得滿分。"},{"en":"Strong pressure can make people rush, freeze, or doubt themselves.","zh":"強大壓力會令人匆忙、僵住或懷疑自己。"},{"en":"This phrase explains why a simple task may become difficult.","zh":"這個短語解釋為何簡單任務會變困難。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":8},{"front":"do something right","meaning":"把某事做好","examples":[{"en":"People may struggle when there is pressure to do something right.","zh":"當有壓力要把某事做好時，人們可能會吃力。"},{"en":"To do something right means to do it correctly or properly.","zh":"把某事做好，是指正確或妥善地完成它。"},{"en":"A new worker may worry about doing the cash register right on the first day.","zh":"新員工第一天可能擔心能否正確操作收銀機。"},{"en":"Wanting to do something right can help performance, but too much pressure can hurt it.","zh":"想把事情做好可以幫助表現，但太大壓力會傷害表現。"},{"en":"This phrase focuses on accuracy and proper performance.","zh":"這個短語聚焦準確度和妥善表現。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":8},{"front":"have difficulty doing something","meaning":"做某事有困難","examples":[{"en":"People often have difficulty doing something that they normally find easy.","zh":"人們常在做平時覺得容易的事時有困難。"},{"en":"To have difficulty doing something means to find it hard to do.","zh":"做某事有困難，是指覺得做該事很難。"},{"en":"A student may have difficulty reading aloud if the whole class is watching.","zh":"如果全班都在看着，學生可能朗讀有困難。"},{"en":"Stress can make people have difficulty with tasks they usually manage well.","zh":"壓力會令人在平時能做好之事上有困難。"},{"en":"This phrase describes struggle with an action.","zh":"這個短語描述做某行動時遇到困難。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":8},{"front":"normally find easy","meaning":"平時覺得容易","examples":[{"en":"People may fail at tasks they normally find easy.","zh":"人們可能在平時覺得容易的任務上失敗。"},{"en":"Normally find easy means usually think something is simple or not difficult.","zh":"平時覺得容易，是指通常認為某事簡單或不困難。"},{"en":"A singer may forget lyrics on stage even if she normally finds the song easy.","zh":"歌手即使平時覺得那首歌容易，也可能在台上忘詞。"},{"en":"Pressure can change how a familiar task feels.","zh":"壓力會改變熟悉任務帶來的感覺。"},{"en":"This phrase contrasts ordinary confidence with unusual failure.","zh":"這個短語把平常信心與不尋常失誤作對比。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":8},{"front":"put someone on the spot","meaning":"令某人當場難以招架","examples":[{"en":"The boy put Osborne on the spot by asking him the question.","zh":"那個男孩透過問問題令 Osborne 當場難以招架。"},{"en":"To put someone on the spot means to force them to answer or act immediately, often in public.","zh":"令某人當場難以招架，是指迫使他們立即回答或行動，通常是在公開場合。"},{"en":"A reporter may put a politician on the spot with a direct question.","zh":"記者可能用直接問題令政治人物當場難以招架。"},{"en":"Putting someone on the spot can create embarrassment if they are not prepared.","zh":"如果對方沒有準備，把某人置於尷尬位置會造成尷尬。"},{"en":"This phrase describes causing sudden pressure for another person.","zh":"這個短語描述為另一個人製造突然壓力。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":8},{"front":"cause stress","meaning":"造成壓力","examples":[{"en":"Being put on the spot can cause stress.","zh":"被迫即場回應會造成壓力。"},{"en":"To cause stress means to make someone feel worried, tense, or under pressure.","zh":"造成壓力，是指令某人感到擔心、緊張或受壓。"},{"en":"A sudden test can cause stress if students have not revised.","zh":"如果學生沒有溫習，突然測驗會造成壓力。"},{"en":"Stress can make thinking slower and mistakes more likely.","zh":"壓力會令思考變慢，並更容易犯錯。"},{"en":"This phrase connects a situation with emotional pressure.","zh":"這個短語把情況與情緒壓力連接起來。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":8},{"front":"heart beats faster","meaning":"心跳加速","examples":[{"en":"The person’s heart beats faster under pressure.","zh":"人在壓力下心跳加速。"},{"en":"Heart beats faster means the heart pumps more quickly than usual.","zh":"心跳加速，是指心臟跳動比平時更快。"},{"en":"Before a speech, a student’s heart may beat faster because they feel nervous.","zh":"演講前，學生可能因緊張而心跳加速。"},{"en":"A faster heartbeat is one physical sign of stress or excitement.","zh":"心跳較快是壓力或興奮的一種身體跡象。"},{"en":"This phrase describes a body reaction to pressure.","zh":"這個短語描述身體對壓力的反應。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":8},{"front":"adrenaline levels","meaning":"腎上腺素水平","examples":[{"en":"The person’s adrenaline levels go up.","zh":"那個人的腎上腺素水平上升。"},{"en":"Adrenaline levels are the amount of adrenaline, a stress hormone, in the body.","zh":"腎上腺素水平，是身體中腎上腺素這種壓力荷爾蒙的數量。"},{"en":"Before a race, an athlete’s adrenaline levels may rise sharply.","zh":"比賽前，運動員的腎上腺素水平可能急升。"},{"en":"Higher adrenaline levels can make the heart beat faster and the body feel alert.","zh":"較高腎上腺素水平會令心跳加速，身體感到警覺。"},{"en":"This phrase describes a biological response to pressure.","zh":"這個短語描述對壓力的生物反應。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":8},{"front":"go up","meaning":"上升","examples":[{"en":"Adrenaline levels go up when a person feels stressed.","zh":"當人感到壓力時，腎上腺素水平會上升。"},{"en":"Go up means increase or become higher.","zh":"上升，是指增加或變高。"},{"en":"Prices may go up when supply is low and demand is high.","zh":"當供應低而需求高，價格可能上升。"},{"en":"When stress goes up, concentration may go down.","zh":"當壓力上升，專注力可能下降。"},{"en":"This phrase is a simple way to describe an increase.","zh":"這個短語是描述增加的簡單方式。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":8},{"front":"as a result","meaning":"因此","examples":[{"en":"As a result, people may make mistakes.","zh":"因此，人們可能會犯錯。"},{"en":"As a result means because of what happened before.","zh":"因此，是指因為之前發生的事。"},{"en":"The bus was late; as a result, many students missed the first lesson.","zh":"巴士遲到；因此，許多學生錯過第一堂課。"},{"en":"This phrase connects a cause with its consequence.","zh":"這個短語把原因與結果連接起來。"},{"en":"It is useful when explaining why something happened.","zh":"它適合用來解釋某事為何發生。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":8},{"front":"make mistakes","meaning":"犯錯","examples":[{"en":"People often make mistakes under pressure.","zh":"人們在壓力下常常犯錯。"},{"en":"To make mistakes means to do something incorrectly.","zh":"犯錯，是指做錯某事。"},{"en":"A cashier may make mistakes if the queue is long and customers are impatient.","zh":"如果排隊很長而顧客不耐煩，收銀員可能犯錯。"},{"en":"Stress, tiredness, and rushing can all increase mistakes.","zh":"壓力、疲倦和匆忙都會增加錯誤。"},{"en":"This phrase describes errors in action, speech, or thinking.","zh":"這個短語描述行動、說話或思考上的錯誤。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":8},{"front":"would not normally make","meaning":"平時不會犯的","examples":[{"en":"People may make mistakes that they would not normally make.","zh":"人們可能犯下平時不會犯的錯誤。"},{"en":"Would not normally make means usually would not do under ordinary conditions.","zh":"平時不會犯的，是指在普通情況下通常不會做出的。"},{"en":"A careful driver may make a mistake they would not normally make when rushing to the hospital.","zh":"小心駕駛者趕往醫院時，可能犯下平時不會犯的錯。"},{"en":"Pressure can change behaviour that is usually steady and accurate.","zh":"壓力會改變平時穩定和準確的行為。"},{"en":"This phrase contrasts normal ability with unusual error.","zh":"這個短語把正常能力與不尋常錯誤作對比。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":9},{"front":"be called choking","meaning":"被稱為「怯場」；臨場失準","examples":[{"en":"This kind of failure under pressure is called choking.","zh":"這種壓力下的失敗被稱為「怯場」或臨場失準。"},{"en":"Be called choking means be given the name “choking” when pressure causes poor performance.","zh":"被稱為「怯場」，是指當壓力造成表現差時，這種現象被命名為 choking。"},{"en":"A tennis player missing an easy shot at match point may be called choking.","zh":"網球選手在賽點打失簡單球，可能被稱為臨場失準。"},{"en":"Naming the problem helps explain why ability disappears under stress.","zh":"為問題命名有助解釋為何能力會在壓力下消失。"},{"en":"This phrase introduces the term for pressure-related failure.","zh":"這個短語引入壓力相關失誤的名稱。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":9},{"front":"choking","meaning":"怯場；臨場失準","examples":[{"en":"Choking happens when pressure makes someone perform worse than usual.","zh":"當壓力令某人表現比平時差時，就會出現怯場或臨場失準。"},{"en":"Choking is a failure to perform normally because stress becomes too strong.","zh":"怯場是在壓力過強時無法正常表現。"},{"en":"A student may choke during an oral exam and forget words they practised many times.","zh":"學生可能在口試中怯場，忘記已練習很多次的字詞。"},{"en":"Choking can happen when the fear of failure becomes stronger than the task itself.","zh":"當對失敗的恐懼比任務本身更強，臨場失準就可能發生。"},{"en":"This word describes mental pressure harming performance.","zh":"這個詞描述心理壓力損害表現。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":9},{"front":"happen in sport","meaning":"在運動中發生","examples":[{"en":"Choking often happens in sport.","zh":"怯場常在運動中發生。"},{"en":"Happen in sport means occur during athletic competition or physical games.","zh":"在運動中發生，是指在體育比賽或體能遊戲期間出現。"},{"en":"A basketball player may choke when taking the final free throw in a close match.","zh":"籃球員在緊湊比賽中投最後一球罰球時，可能臨場失準。"},{"en":"Sport creates pressure because audiences, teammates, and results are all visible.","zh":"運動會製造壓力，因為觀眾、隊友和結果都很明顯。"},{"en":"This phrase gives sports as a common setting for pressure-related failure.","zh":"這個短語把運動作為壓力相關失誤的常見場景。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":9},{"front":"such as","meaning":"例如","examples":[{"en":"Choking can happen in sport, such as when a footballer takes a penalty.","zh":"怯場可以在運動中發生，例如足球員主射十二碼時。"},{"en":"Such as means for example.","zh":"例如是指 for example。"},{"en":"Students need basic equipment, such as pens, notebooks, and a calculator.","zh":"學生需要基本用具，例如筆、筆記簿和計算機。"},{"en":"This phrase introduces a clear example of a general idea.","zh":"這個短語引入一般想法的清楚例子。"},{"en":"It helps readers understand an abstract point through a concrete case.","zh":"它幫助讀者透過具體個案理解抽象重點。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":9},{"front":"a footballer","meaning":"足球員","examples":[{"en":"A footballer may choke when taking a crucial penalty.","zh":"足球員在主射關鍵十二碼時可能怯場。"},{"en":"A footballer is a person who plays football, especially as a sport or profession.","zh":"足球員是踢足球的人，尤其是作為運動或職業。"},{"en":"A footballer trains to pass, shoot, defend, and work with teammates.","zh":"足球員訓練傳球、射門、防守和與隊友合作。"},{"en":"Because footballers perform in front of crowds, pressure can affect their decisions.","zh":"因為足球員在觀眾面前表現，壓力會影響他們的決定。"},{"en":"This word refers to a player in football.","zh":"這個詞指足球運動中的球員。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":9},{"front":"take a crucial penalty","meaning":"主射關鍵十二碼","examples":[{"en":"A footballer may feel pressure when he takes a crucial penalty.","zh":"足球員主射關鍵十二碼時可能感到壓力。"},{"en":"To take a crucial penalty means to shoot an important penalty kick that may decide the match.","zh":"主射關鍵十二碼，是指射出可能決定比賽結果的重要十二碼。"},{"en":"A footballer taking a crucial penalty may hear the crowd shouting and feel his heart race.","zh":"主射關鍵十二碼的足球員可能聽到觀眾叫喊，並感到心跳加速。"},{"en":"Missing such a penalty can change the result of a game.","zh":"射失這類十二碼可以改變比賽結果。"},{"en":"This phrase describes a high-pressure sporting moment.","zh":"這個短語描述高壓運動時刻。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":9},{"front":"in the same way","meaning":"同樣地","examples":[{"en":"In the same way, the boy’s question put Osborne under pressure.","zh":"同樣地，那個男孩的問題令 Osborne 承受壓力。"},{"en":"In the same way means similarly or by a similar process.","zh":"同樣地，是指以相似方式或相似過程。"},{"en":"A singer may freeze on stage; in the same way, a student may freeze during an oral exam.","zh":"歌手可能在台上僵住；同樣地，學生可能在口試中僵住。"},{"en":"This phrase connects two examples that share the same logic.","zh":"這個短語連接兩個具有相同邏輯的例子。"},{"en":"It helps readers transfer understanding from one situation to another.","zh":"它幫助讀者把一個情況的理解轉移到另一個情況。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":9},{"front":"put someone under great pressure","meaning":"使某人承受巨大壓力","examples":[{"en":"The boy’s question put Osborne under great pressure.","zh":"那個男孩的問題使 Osborne 承受巨大壓力。"},{"en":"To put someone under great pressure means to make them feel strong stress or expectation.","zh":"使某人承受巨大壓力，是指令他感到強烈壓力或期望。"},{"en":"A manager may put staff under great pressure by demanding a full report in one hour.","zh":"經理要求員工一小時內交完整報告，可能使員工承受巨大壓力。"},{"en":"Great pressure can make people hesitate, rush, or avoid answering.","zh":"巨大壓力會令人猶豫、匆忙或避免回答。"},{"en":"This phrase describes a situation that strongly stresses someone.","zh":"這個短語描述強烈壓迫某人的情況。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":9},{"front":"it would be a disaster for someone if","meaning":"如果……，對某人來說會是一場災難","examples":[{"en":"It would be a disaster for Osborne if he got the answer wrong.","zh":"如果 Osborne 答錯，對他來說會是一場災難。"},{"en":"It would be a disaster for someone if means the result would be very damaging or embarrassing for that person.","zh":"如果某事發生，對某人來說會是一場災難，是指結果對那人非常有害或尷尬。"},{"en":"It would be a disaster for a baker if the wedding cake collapsed before delivery.","zh":"如果婚禮蛋糕在送貨前倒塌，對麵包師來說會是一場災難。"},{"en":"Fear of disaster can make people more nervous and less able to perform.","zh":"對災難的恐懼會令人更緊張，更難表現。"},{"en":"This phrase explains why a person feels high pressure.","zh":"這個短語解釋某人為何感到高壓。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":9},{"front":"such a simple question","meaning":"如此簡單的問題","examples":[{"en":"He feared getting such a simple question wrong.","zh":"他害怕答錯如此簡單的問題。"},{"en":"Such a simple question means a question that looks very easy or basic.","zh":"如此簡單的問題，是指看起來非常容易或基本的問題。"},{"en":"A teacher may be embarrassed if they cannot answer such a simple question from a child.","zh":"如果老師不能回答孩子提出的如此簡單問題，可能會尷尬。"},{"en":"Simple questions can feel dangerous when answering wrongly would damage reputation.","zh":"當答錯會損害聲譽，簡單問題也會感覺危險。"},{"en":"This phrase highlights the contrast between the question’s ease and the pressure around it.","zh":"這個短語突出問題容易程度與周圍壓力之間的對比。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":9},{"front":"fear that","meaning":"擔心；害怕","examples":[{"en":"He feared that he might choke.","zh":"他擔心自己可能會臨場失準。"},{"en":"Fear that means worry that something bad may happen.","zh":"擔心某事，是指害怕不好的事可能發生。"},{"en":"A student may fear that they will forget everything during the exam.","zh":"學生可能擔心自己在考試中忘記所有東西。"},{"en":"Fear can make a person avoid a situation even if they know the answer.","zh":"恐懼會令一個人即使知道答案也避開某情況。"},{"en":"This phrase introduces the worry behind someone’s action.","zh":"這個短語引入某人行動背後的憂慮。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":10},{"front":"might choke","meaning":"可能會臨場失準","examples":[{"en":"Osborne feared that he might choke under pressure.","zh":"Osborne 擔心自己在壓力下可能會臨場失準。"},{"en":"Might choke means might perform badly because of pressure.","zh":"可能會臨場失準，是指可能因壓力而表現差。"},{"en":"A pianist may worry that she might choke during a competition performance.","zh":"鋼琴家可能擔心自己在比賽演出中臨場失準。"},{"en":"Fear of choking can itself increase stress and make mistakes more likely.","zh":"對臨場失準的恐懼本身會增加壓力，令錯誤更可能出現。"},{"en":"This phrase describes a possible pressure-related failure.","zh":"這個短語描述可能出現的壓力相關失敗。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":10},{"front":"that is why","meaning":"這就是為何","examples":[{"en":"That is why he refused to answer the question.","zh":"這就是為何他拒絕回答問題。"},{"en":"That is why means this is the reason.","zh":"這就是為何，是指這就是原因。"},{"en":"The road was flooded; that is why the bus was late.","zh":"道路水浸；這就是為何巴士遲到。"},{"en":"This phrase connects an explanation with the result it caused.","zh":"這個短語把解釋與其造成的結果連接起來。"},{"en":"It is often used after giving a reason.","zh":"它常用於給出原因之後。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":10},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"The task asks which paragraph contains the following information.","zh":"題目問哪一段包含以下資料。"},{"en":"Which paragraph contains means students must identify the paragraph where certain information appears.","zh":"哪一段包含，是指學生必須找出某資料出現在哪個段落。"},{"en":"In reading tests, students may scan for names, dates, or examples to find which paragraph contains the answer.","zh":"在閱讀測驗中，學生可能掃讀姓名、日期或例子，以找出哪一段包含答案。"},{"en":"This task checks whether students can locate information efficiently.","zh":"這項任務檢查學生能否有效定位資料。"},{"en":"The phrase is common in matching-information questions.","zh":"這個短語常見於資料配對題。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":10},{"front":"the following information","meaning":"以下資料","examples":[{"en":"Students must match each item with the paragraph containing the following information.","zh":"學生必須把每項內容與包含以下資料的段落配對。"},{"en":"The following information means the details listed after the instruction.","zh":"以下資料，是指指示後列出的細節。"},{"en":"A worksheet may ask students to find the following information: date, place, and main cause.","zh":"工作紙可能要求學生找出以下資料：日期、地點和主要原因。"},{"en":"This phrase prepares readers to look at a list of required details.","zh":"這個短語讓讀者準備查看所需細節列表。"},{"en":"It is used in instructions before examples or items.","zh":"它用於例子或項目之前的指示。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":10},{"front":"a 19th-century opinion","meaning":"十九世紀的看法","examples":[{"en":"The passage includes a 19th-century opinion about what children should learn.","zh":"篇章包括一個關於兒童應該學甚麼的十九世紀看法。"},{"en":"A 19th-century opinion is a view expressed during the years 1801 to 1900.","zh":"十九世紀的看法，是在 1801 至 1900 年期間表達的觀點。"},{"en":"A 19th-century opinion on education may seem demanding by modern standards.","zh":"以現代標準看，十九世紀的教育看法可能顯得嚴苛。"},{"en":"Historical opinions help readers see how ideas about learning have changed.","zh":"歷史觀點幫助讀者看見學習理念如何改變。"},{"en":"This phrase identifies a view from a specific historical period.","zh":"這個短語指出來自特定歷史時期的看法。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":10},{"front":"what children should learn","meaning":"兒童應該學習的內容","examples":[{"en":"John Leslie gave an opinion about what children should learn.","zh":"John Leslie 對兒童應該學習的內容提出看法。"},{"en":"What children should learn means the knowledge or skills people think children need to study.","zh":"兒童應該學習的內容，是人們認為孩子需要學習的知識或技能。"},{"en":"Parents and teachers may disagree about what children should learn first: grammar, speaking, or reading.","zh":"家長和老師可能不同意兒童應先學甚麼：文法、口語還是閱讀。"},{"en":"Views about children’s learning change when society’s needs change.","zh":"當社會需要改變，對兒童學習內容的看法也會改變。"},{"en":"This phrase refers to educational priorities.","zh":"這個短語指教育優先事項。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":10},{"front":"the most difficult sums","meaning":"最難的算式","examples":[{"en":"The passage discusses the most difficult sums in the multiplication table.","zh":"篇章討論乘法表中最難的算式。"},{"en":"The most difficult sums are the calculations that learners find hardest to remember or answer.","zh":"最難的算式，是學習者最難記住或回答的計算。"},{"en":"A teacher may spend extra time on the most difficult sums before a mental maths test.","zh":"老師可能在心算測驗前多花時間練習最難的算式。"},{"en":"Identifying difficult sums helps students practise where they need it most.","zh":"找出困難算式有助學生練習最需要改善的地方。"},{"en":"This phrase refers to the hardest calculations within a set.","zh":"這個短語指一組題目中最困難的計算。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":10},{"front":"the effect of pressure on","meaning":"壓力對……的影響","examples":[{"en":"The final paragraph explains the effect of pressure on performance.","zh":"最後一段解釋壓力對表現的影響。"},{"en":"The effect of pressure on something means how stress changes or influences it.","zh":"壓力對某事的影響，是指壓力如何改變或左右它。"},{"en":"The effect of pressure on memory can be seen when students forget answers in exams.","zh":"學生在考試中忘記答案，可以看見壓力對記憶的影響。"},{"en":"Pressure can improve focus in small amounts but damage performance when it becomes too strong.","zh":"少量壓力可以改善專注，但壓力太大會損害表現。"},{"en":"This phrase links stress with its consequences.","zh":"這個短語把壓力與其後果連接起來。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":10},{"front":"doing something","meaning":"做某事","examples":[{"en":"Pressure can affect someone’s ability to do something correctly.","zh":"壓力會影響某人正確做某事的能力。"},{"en":"Doing something means carrying out an action or task.","zh":"做某事，是指執行一個行動或任務。"},{"en":"A child doing a maths question may need quiet time to think.","zh":"孩子做數學題時可能需要安靜時間思考。"},{"en":"When people are watched closely, doing something simple can become harder.","zh":"當人被密切注視時，做簡單事情也會變難。"},{"en":"This phrase is general and can refer to almost any action.","zh":"這個短語很概括，可以指幾乎任何行動。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":10},{"front":"a politician who got a sum wrong","meaning":"答錯算式的政治人物","examples":[{"en":"The text mentions a politician who got a sum wrong.","zh":"文章提到一位答錯算式的政治人物。"},{"en":"A politician who got a sum wrong is a public figure who answered a calculation incorrectly.","zh":"答錯算式的政治人物，是回答計算題時出錯的公眾人物。"},{"en":"News reports may repeat the story of a politician who got a simple sum wrong.","zh":"新聞報道可能反覆提及一位答錯簡單算式的政治人物。"},{"en":"Such mistakes attract attention because people expect leaders to be confident with numbers.","zh":"這類錯誤吸引注意，因為人們期望領袖對數字有信心。"},{"en":"This phrase identifies a person through a public arithmetic error.","zh":"這個短語透過公開算術錯誤識別某人。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":10},{"front":"a history of the times table","meaning":"乘數表的歷史","examples":[{"en":"The second paragraph gives a history of the times table.","zh":"第二段講述乘數表的歷史。"},{"en":"A history of the times table explains where it came from and how it has been used over time.","zh":"乘數表的歷史，是解釋它從何而來，以及如何隨時間被使用。"},{"en":"A textbook may give a history of numbers before teaching modern arithmetic.","zh":"教科書可能在教授現代算術前講述數字的歷史。"},{"en":"Historical background helps students see that school tools developed over centuries.","zh":"歷史背景幫助學生看見學校工具經過數百年發展而來。"},{"en":"This phrase refers to the past development of the multiplication table.","zh":"這個短語指乘法表的過去發展。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":11},{"front":"agree with the information given","meaning":"與文中資料一致","examples":[{"en":"Students decide whether the statements agree with the information given in the text.","zh":"學生判斷陳述是否與文中資料一致。"},{"en":"Agree with the information given means match what the passage says.","zh":"與文中資料一致，是指符合篇章所說內容。"},{"en":"If the text says the table was found in China, that statement agrees with the information given.","zh":"如果文章說該表在中國被發現，這個陳述就與文中資料一致。"},{"en":"Students should choose TRUE only when the text clearly supports the statement.","zh":"只有當文本清楚支持陳述時，學生才應選 TRUE。"},{"en":"This phrase is used in reading-comprehension tasks.","zh":"這個短語用於閱讀理解題。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":11},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A false statement contradicts the information in the text.","zh":"錯誤陳述與文中資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"與資料相矛盾，是指說出與文本相反的內容。"},{"en":"If the text says a table was found in China, saying it was found in France contradicts the information.","zh":"如果文章說表格在中國被發現，說它在法國被發現就與資料相矛盾。"},{"en":"Students should choose FALSE when the passage clearly disagrees with the statement.","zh":"當篇章清楚不同意陳述時，學生應選 FALSE。"},{"en":"This phrase describes conflict between a statement and the source.","zh":"這個短語描述陳述與來源之間的衝突。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":11},{"front":"no information on this","meaning":"沒有這方面的資料","examples":[{"en":"Write “Not Given” if there is no information on this.","zh":"如果沒有這方面的資料，就寫 “Not Given”。"},{"en":"No information on this means the text does not say enough to decide whether it is true or false.","zh":"沒有這方面的資料，是指文本沒有提供足夠內容判斷真假。"},{"en":"If a passage names a mathematician but never mentions his family, there is no information on his children.","zh":"如果篇章提到一位數學家，但從未提及其家庭，就沒有關於他孩子的資料。"},{"en":"Students should not guess from outside knowledge when there is no information in the text.","zh":"當文本沒有資料時，學生不應用外部知識猜測。"},{"en":"This phrase explains when NOT GIVEN is correct.","zh":"這個短語解釋何時應選 NOT GIVEN。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":11},{"front":"invent the times table","meaning":"發明乘數表","examples":[{"en":"The statement asks whether Pythagoras invented the times table in China.","zh":"該陳述問畢達哥拉斯是否在中國發明乘數表。"},{"en":"To invent the times table means to create the multiplication table for the first time.","zh":"發明乘數表，是指首次創造乘法表。"},{"en":"A person can use a tool without being the one who invented it.","zh":"一個人可以使用工具，但不一定是發明它的人。"},{"en":"Claims about who invented something need historical evidence.","zh":"關於誰發明某物的主張需要歷史證據。"},{"en":"This phrase focuses on original creation, not later naming or use.","zh":"這個短語聚焦原始創造，而不是後來命名或使用。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":11},{"front":"were asked the same question","meaning":"被問及同一條問題","examples":[{"en":"Stephen Byers and George Osborne were asked the same question.","zh":"Stephen Byers 和 George Osborne 被問及同一條問題。"},{"en":"Were asked the same question means two or more people received an identical question.","zh":"被問及同一條問題，是指兩個或更多人收到相同問題。"},{"en":"In an interview, all candidates may be asked the same question to make comparison fair.","zh":"在面試中，所有候選人可能被問及同一條問題，以令比較公平。"},{"en":"When people are asked the same question, their different responses become easier to compare.","zh":"當人們被問及同一問題，他們不同回應就更容易比較。"},{"en":"This phrase shows repeated questioning across people.","zh":"這個短語顯示同一問題在不同人身上重複。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":11},{"front":"have to learn the multiplication table","meaning":"必須學習乘法表","examples":[{"en":"The question asks whether all UK children have to learn the multiplication table.","zh":"題目問是否所有英國兒童都必須學習乘法表。"},{"en":"Have to learn the multiplication table means are required or expected to study multiplication facts.","zh":"必須學習乘法表，是指被要求或被期望學習乘法事實。"},{"en":"A pupil may have to learn the multiplication table before moving on to long division.","zh":"學生可能必須學習乘法表，然後才進入長除法。"},{"en":"Required learning targets help schools make sure basic skills are covered.","zh":"必修學習目標幫助學校確保基本技能被涵蓋。"},{"en":"This phrase describes an educational requirement or expectation.","zh":"這個短語描述教育要求或期望。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":11},{"front":"did not know the answer to","meaning":"不知道……的答案","examples":[{"en":"The statement claims that George Osborne did not know the answer to 7 × 8.","zh":"該陳述聲稱 George Osborne 不知道 7 × 8 的答案。"},{"en":"Did not know the answer to means lacked the correct response to a question.","zh":"不知道某問題的答案，是指缺乏正確回應。"},{"en":"A student may not know the answer to a question if they never practised that topic.","zh":"如果學生從未練習某課題，可能不知道問題答案。"},{"en":"Not answering a question does not always prove that someone does not know the answer.","zh":"不回答問題不一定證明某人不知道答案。"},{"en":"This phrase separates lack of knowledge from refusal or pressure.","zh":"這個短語把缺乏知識與拒絕回答或壓力分開。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":11},{"front":"the hardest sum that children have to learn","meaning":"兒童必須學習的最難算式","examples":[{"en":"The statement claims that 7 × 8 is the hardest sum children have to learn.","zh":"該陳述聲稱 7 × 8 是兒童必須學習的最難算式。"},{"en":"The hardest sum that children have to learn means the most difficult required calculation for pupils.","zh":"兒童必須學習的最難算式，是指學生必修計算中最困難的一題。"},{"en":"A teacher may ask which sum children find hardest so she can give extra practice.","zh":"老師可能詢問孩子覺得哪條算式最難，以便提供額外練習。"},{"en":"The hardest required sum may cause more mistakes because pupils must answer it despite finding it difficult.","zh":"最難的必修算式可能造成更多錯誤，因為學生即使覺得困難也必須回答。"},{"en":"This phrase combines difficulty with a school learning requirement.","zh":"這個短語結合難度與學校學習要求。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":11},{"front":"get the sum wrong because","meaning":"因為……而答錯算式","examples":[{"en":"The statement asks whether Stephen Byers got the sum wrong because he choked.","zh":"該陳述問 Stephen Byers 是否因為怯場而答錯算式。"},{"en":"Get the sum wrong because means answer the calculation incorrectly for a particular reason.","zh":"因為某原因而答錯算式，是指因特定原因給出錯誤計算答案。"},{"en":"A child may get the sum wrong because they confuse the order of the numbers.","zh":"孩子可能因混淆數字順序而答錯算式。"},{"en":"When pressure is the reason, the mistake may come from stress rather than lack of knowledge.","zh":"當壓力是原因，錯誤可能來自緊張，而不是缺乏知識。"},{"en":"This phrase links a wrong calculation with its cause.","zh":"這個短語把錯誤計算與其原因連接起來。"}],"source":"64 - TRICKY SUMS AND PSYCHOLOGY.pdf","sourcePage":11}],"ielts/reading/passage-2/Practice 65":[{"front":"Drinking Filtered Water","meaning":"飲用過濾水","examples":[{"en":"The passage discusses the health benefits of drinking filtered water.","zh":"文章討論飲用過濾水的健康好處。"},{"en":"Drinking filtered water means drinking water that has passed through a filter to remove some unwanted substances.","zh":"drinking filtered water 指飲用經濾水器處理、去除部分不需要物質的水。"},{"en":"A family may start drinking filtered water if their tap water tastes strongly of chlorine.","zh":"如果家中的自來水有很強氯味，一家人可能開始飲用過濾水。"},{"en":"Drinking filtered water can make people feel more confident about what they consume every day.","zh":"飲用過濾水可以令人對自己每天喝進身體的東西更有信心。"},{"en":"This phrase is usually used when comparing filtered water with tap water or bottled water.","zh":"這個短語通常用於比較過濾水、自來水或樽裝水。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":1},{"front":"be made up mainly of","meaning":"主要由……構成","examples":[{"en":"The body is made up mainly of water.","zh":"身體主要由水構成。"},{"en":"To be made up mainly of something means that something forms the largest part of it.","zh":"be made up mainly of something 指某物構成了整體中最大部分。"},{"en":"A fruit smoothie may be made up mainly of fruit and yoghurt.","zh":"水果沙冰可能主要由水果和乳酪構成。"},{"en":"If something is made up mainly of water, water quality and quantity may matter greatly.","zh":"如果某物主要由水構成，水的質素和數量就可能非常重要。"},{"en":"This phrase is useful when describing the main material or component of something.","zh":"描述某物主要材料或成分時，這個短語很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":1},{"front":"the quality of water","meaning":"水質","examples":[{"en":"The quality of water that we drink every day affects our health.","zh":"我們每天飲用的水質會影響健康。"},{"en":"The quality of water means how clean, safe, and suitable the water is for use or drinking.","zh":"quality of water 指水有多清潔、安全，以及是否適合使用或飲用。"},{"en":"A school may test the quality of water before letting students drink from new taps.","zh":"學校可能在讓學生使用新水龍頭飲水前測試水質。"},{"en":"Poor water quality can lead people to use filters or buy bottled water.","zh":"水質差可能令人使用濾水器或購買樽裝水。"},{"en":"This phrase focuses on how good or safe the water is, not just how much water there is.","zh":"這個短語聚焦水有多好或多安全，而不只是水量多少。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":1},{"front":"have an important effect on","meaning":"對……有重要影響","examples":[{"en":"The quality of drinking water has an important effect on our health.","zh":"飲用水質對我們的健康有重要影響。"},{"en":"To have an important effect on something means to influence it in a serious or meaningful way.","zh":"have an important effect on something 指對某事有重大或有意義的影響。"},{"en":"Sleep has an important effect on students’ memory and mood.","zh":"睡眠對學生記憶和心情有重要影響。"},{"en":"If water quality affects health, people may pay more attention to what they drink.","zh":"如果水質影響健康，人們可能更注意自己喝甚麼。"},{"en":"This phrase is useful when explaining why one factor matters.","zh":"解釋某因素為何重要時，這個短語很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":1},{"front":"filtered water","meaning":"過濾水","examples":[{"en":"Filtered water is described as healthier than tap water.","zh":"過濾水被描述為比自來水更健康。"},{"en":"Filtered water is water that has passed through a filter to remove certain substances.","zh":"filtered water 指經過濾器處理以去除某些物質的水。"},{"en":"An office may provide filtered water so staff do not need to buy plastic bottles.","zh":"辦公室可能提供過濾水，讓員工不必購買膠樽水。"},{"en":"Different filters remove different things, so filtered water is not always the same everywhere.","zh":"不同濾水器去除不同物質，所以各地的過濾水不一定相同。"},{"en":"This phrase is often used in discussions about drinking habits and water safety.","zh":"這個短語常用於討論飲水習慣和食水安全。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":1},{"front":"healthier than","meaning":"比……更健康","examples":[{"en":"Filtered water may be healthier than tap water in some situations.","zh":"在某些情況下，過濾水可能比自來水更健康。"},{"en":"Healthier than means better for health when compared with another option.","zh":"healthier than 指與另一選項相比，對健康較好。"},{"en":"Walking to school can be healthier than taking a short car ride every day.","zh":"每天步行上學可能比短途乘車更健康。"},{"en":"People choose what is healthier than another option when they want to reduce risk.","zh":"當人們想降低風險，會選擇比另一選項更健康的東西。"},{"en":"This phrase always involves comparison between two things.","zh":"這個短語一定涉及兩者之間的比較。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":1},{"front":"tap water","meaning":"自來水","examples":[{"en":"Tap water may contain contaminants.","zh":"自來水可能含有污染物。"},{"en":"Tap water is water that comes directly from a household or public tap.","zh":"tap water 指直接從家用或公共水龍頭流出的水。"},{"en":"People often drink tap water at home, at school, or in offices.","zh":"人們常在家中、學校或辦公室飲用自來水。"},{"en":"If tap water tastes unusual, residents may ask the water supplier for information.","zh":"如果自來水味道異常，居民可能向供水商查詢資料。"},{"en":"This phrase contrasts with bottled water, filtered water, or boiled water.","zh":"這個短語與樽裝水、過濾水或煮沸水形成對比。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":1},{"front":"bottled water","meaning":"樽裝水","examples":[{"en":"Some bottled water may also contain contaminants.","zh":"有些樽裝水也可能含有污染物。"},{"en":"Bottled water is drinking water sold in sealed bottles.","zh":"bottled water 指以密封樽出售的飲用水。"},{"en":"Travellers may buy bottled water when they are unsure about local tap water.","zh":"旅客不確定當地自來水是否安全時，可能購買樽裝水。"},{"en":"Bottled water can be convenient, but it also creates plastic waste.","zh":"樽裝水很方便，但也會製造塑膠廢物。"},{"en":"This phrase refers to packaging and sale, not automatically to perfect purity.","zh":"這個短語指包裝和銷售形式，不自動表示完全純淨。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":1},{"front":"be free of contaminants","meaning":"不含污染物","examples":[{"en":"Filtered water is free of contaminants.","zh":"過濾水不含污染物。"},{"en":"To be free of contaminants means to contain no harmful or unwanted substances.","zh":"be free of contaminants 指不含有害或不需要的物質。"},{"en":"A clean kitchen surface should be free of contaminants before food is prepared.","zh":"準備食物前，乾淨廚房表面應不含污染物。"},{"en":"If water is free of contaminants, people may consider it safer to drink.","zh":"如果水不含污染物，人們可能認為它較安全可飲用。"},{"en":"This phrase is used when emphasising cleanliness or safety.","zh":"強調清潔或安全時，會使用這個短語。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":1},{"front":"contaminants","meaning":"污染物","examples":[{"en":"Contaminants are substances that make water dirty or harmful.","zh":"污染物是令水骯髒或有害的物質。"},{"en":"Contaminants are unwanted substances that reduce safety or quality.","zh":"contaminants 指降低安全性或質素的不需要物質。"},{"en":"Dust, bacteria, and chemicals can become contaminants in food or water.","zh":"灰塵、細菌和化學物質都可能成為食物或水中的污染物。"},{"en":"If contaminants enter drinking water, people may need treatment or filtration.","zh":"如果污染物進入飲用水，人們可能需要處理或過濾。"},{"en":"This word is common in health, food safety, and environmental science.","zh":"這個詞常見於健康、食物安全和環境科學。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":1},{"front":"that is","meaning":"即是；也就是說","examples":[{"en":"Contaminants are substances that make water dirty or harmful; that is, they reduce water quality.","zh":"污染物是令水骯髒或有害的物質；也就是說，它們降低水質。"},{"en":"That is introduces a clearer explanation of what has just been said.","zh":"that is 用來引出對剛才內容的更清楚解釋。"},{"en":"The shop is cashless; that is, customers must pay by card or phone.","zh":"這間店是無現金的；也就是說，顧客必須用卡或手機付款。"},{"en":"Writers use that is when they want to restate an idea more simply.","zh":"作者想用更簡單方式重述想法時，會使用 that is。"},{"en":"This phrase is useful for definitions and clarification.","zh":"這個短語適合用於定義和澄清。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":1},{"front":"substances that make it dirty or harmful","meaning":"令其骯髒或有害的物質","examples":[{"en":"Contaminants are substances that make water dirty or harmful.","zh":"污染物是令水骯髒或有害的物質。"},{"en":"Substances that make it dirty or harmful are materials that reduce cleanliness or safety.","zh":"substances that make it dirty or harmful 指降低清潔程度或安全性的材料。"},{"en":"Oil leaking into a river can be a substance that makes the water dirty or harmful.","zh":"漏入河流的油可以是令水骯髒或有害的物質。"},{"en":"When such substances are present, water may need testing before use.","zh":"當這類物質存在時，水在使用前可能需要檢測。"},{"en":"This phrase explains the meaning of contaminants in plain language.","zh":"這個短語用簡單語言解釋 contaminants 的意思。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":2},{"front":"settle on the bottom of","meaning":"沉積在……底部","examples":[{"en":"Some substances settle on the bottom of a glass of tap water.","zh":"有些物質會沉積在一杯自來水的底部。"},{"en":"To settle on the bottom of something means to sink and stay at the lowest part.","zh":"settle on the bottom of something 指下沉並停留在最低部分。"},{"en":"Sand may settle on the bottom of a bucket after muddy water is left still.","zh":"泥水靜置後，沙粒可能沉積在水桶底部。"},{"en":"Heavy particles settle when water stops moving.","zh":"當水停止流動，較重微粒會沉積。"},{"en":"This phrase describes downward movement and accumulation.","zh":"這個短語描述向下移動和累積。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":2},{"front":"a glass of tap water","meaning":"一杯自來水","examples":[{"en":"Some substances may settle on the bottom of a glass of tap water.","zh":"有些物質可能沉積在一杯自來水底部。"},{"en":"A glass of tap water is one serving of water taken from a tap.","zh":"glass of tap water 指從水龍頭取出的一杯水。"},{"en":"A student may drink a glass of tap water after sports practice.","zh":"學生運動練習後可能喝一杯自來水。"},{"en":"If particles appear in a glass of tap water, people may worry about water quality.","zh":"如果一杯自來水中出現微粒，人們可能擔心水質。"},{"en":"This phrase gives a simple everyday example of drinking water.","zh":"這個短語提供飲用水的簡單日常例子。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":2},{"front":"microorganisms","meaning":"微生物","examples":[{"en":"Microorganisms can cause disease.","zh":"微生物可以引致疾病。"},{"en":"Microorganisms are tiny living things that are too small to see clearly without a microscope.","zh":"microorganisms 指細小到沒有顯微鏡難以看清的生物。"},{"en":"Some microorganisms are useful in yoghurt, while others may make people ill.","zh":"有些微生物在乳酪中有用，另一些則可能令人患病。"},{"en":"If harmful microorganisms enter drinking water, they may spread infection.","zh":"如果有害微生物進入飲用水，它們可能傳播感染。"},{"en":"This word is common in biology, health, and food safety.","zh":"這個詞常見於生物、健康和食物安全。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":2},{"front":"cause disease","meaning":"引致疾病","examples":[{"en":"Some microorganisms in water can cause disease.","zh":"水中的某些微生物可以引致疾病。"},{"en":"To cause disease means to make people or animals become ill.","zh":"cause disease 指令人體或動物患病。"},{"en":"Germs on unwashed hands can cause disease if they enter the body.","zh":"未洗手上的病菌如果進入身體，可以引致疾病。"},{"en":"Clean water and hygiene reduce the chance that harmful organisms cause disease.","zh":"清潔食水和衛生習慣可以降低有害生物引致疾病的機會。"},{"en":"This phrase is used when explaining a source of illness.","zh":"解釋疾病來源時，會使用這個短語。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":2},{"front":"known as bacteria or germs","meaning":"被稱為細菌或病菌","examples":[{"en":"Microorganisms that cause disease are known as bacteria or germs.","zh":"引致疾病的微生物被稱為細菌或病菌。"},{"en":"Known as means called by a particular name.","zh":"known as 指被叫作某個名稱。"},{"en":"Small organisms that make food spoil are often known as germs in everyday speech.","zh":"令食物變壞的小生物在日常說法中常被稱為病菌。"},{"en":"Giving a common name helps readers understand a technical word.","zh":"提供常見名稱有助讀者理解技術詞。"},{"en":"This phrase introduces a familiar label for something.","zh":"這個短語引入某物的熟悉稱呼。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":2},{"front":"bacteria or germs","meaning":"細菌或病菌","examples":[{"en":"Bacteria or germs are examples of contaminants.","zh":"細菌或病菌是污染物的例子。"},{"en":"Bacteria or germs are tiny organisms that may cause illness in some situations.","zh":"bacteria or germs 指在某些情況下可能引致疾病的微小生物。"},{"en":"Washing hands helps remove bacteria or germs before eating.","zh":"飯前洗手有助去除細菌或病菌。"},{"en":"If bacteria or germs are found in water, the water may need treatment.","zh":"如果水中發現細菌或病菌，該水可能需要處理。"},{"en":"This phrase is common in health education and hygiene advice.","zh":"這個短語常見於健康教育和衛生建議。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":2},{"front":"examples of contaminants","meaning":"污染物的例子","examples":[{"en":"Bacteria and poisonous metals are examples of contaminants.","zh":"細菌和有毒金屬是污染物的例子。"},{"en":"Examples of contaminants are specific substances that can make water, food, or air less safe.","zh":"examples of contaminants 指會令水、食物或空氣較不安全的具體物質。"},{"en":"Smoke, oil, and germs can be examples of contaminants in different environments.","zh":"煙、油和病菌在不同環境中都可以是污染物的例子。"},{"en":"Listing examples helps people understand what a general word means.","zh":"列出例子有助人理解一般詞語的意思。"},{"en":"This phrase is useful when moving from definition to real cases.","zh":"從定義轉到真實個案時，這個短語很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":2},{"front":"poisonous metals and chemicals","meaning":"有毒金屬和化學物質","examples":[{"en":"Filtered water is free of many poisonous metals and chemicals.","zh":"過濾水不含許多有毒金屬和化學物質。"},{"en":"Poisonous metals and chemicals are substances that can harm the body if people are exposed to enough of them.","zh":"poisonous metals and chemicals 指人接觸足夠分量時可能傷害身體的物質。"},{"en":"A factory must handle poisonous chemicals carefully to protect workers.","zh":"工廠必須小心處理有毒化學物，以保護工人。"},{"en":"If poisonous substances enter drinking water, people may need safer water sources.","zh":"如果有毒物質進入飲用水，人們可能需要更安全水源。"},{"en":"This phrase describes contaminants that are dangerous because of toxicity.","zh":"這個短語描述因毒性而危險的污染物。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":2},{"front":"common in tap water","meaning":"在自來水中常見","examples":[{"en":"Some chemicals are common in tap water.","zh":"有些化學物質在自來水中常見。"},{"en":"Common in tap water means often found in water that comes from taps.","zh":"common in tap water 指常在水龍頭流出的水中發現。"},{"en":"Chlorine taste may be common in tap water in some cities.","zh":"在某些城市，自來水中有氯味可能很常見。"},{"en":"If a substance is common in tap water, filters may be designed to reduce it.","zh":"如果某物質在自來水中常見，濾水器可能被設計來減少它。"},{"en":"This phrase describes frequency, not necessarily danger by itself.","zh":"這個短語描述出現頻率，本身不一定等於危險。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":2},{"front":"bottled water brands","meaning":"樽裝水牌子","examples":[{"en":"Some bottled water brands may contain chemicals.","zh":"有些樽裝水牌子可能含有化學物質。"},{"en":"Bottled water brands are companies or product lines that sell water in bottles.","zh":"bottled water brands 指銷售樽裝水的公司或產品系列。"},{"en":"Shoppers may compare bottled water brands by price, taste, and source.","zh":"購物者可能按價格、味道和來源比較樽裝水牌子。"},{"en":"Different brands may use different sources or treatment methods.","zh":"不同牌子可能使用不同水源或處理方法。"},{"en":"This phrase refers to commercial water products.","zh":"這個短語指商業飲用水產品。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":2},{"front":"the authorities","meaning":"當局","examples":[{"en":"The authorities use chemicals to disinfect tap water.","zh":"當局使用化學物質為自來水消毒。"},{"en":"The authorities are official organisations or people with power to make decisions.","zh":"authorities 指有權作決定的官方機構或人士。"},{"en":"The authorities may close a beach if water tests show danger.","zh":"如果水質測試顯示危險，當局可能關閉海灘。"},{"en":"When public health is involved, authorities may create rules to protect residents.","zh":"當涉及公共健康，當局可能制定規則保護居民。"},{"en":"This phrase usually refers to government or official bodies.","zh":"這個短語通常指政府或官方機構。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":3},{"front":"normal tap water","meaning":"一般自來水","examples":[{"en":"Normal tap water can contain contaminants.","zh":"一般自來水可能含有污染物。"},{"en":"Normal tap water means ordinary water supplied through household taps.","zh":"normal tap water 指透過家用水龍頭供應的普通水。"},{"en":"A student may fill a bottle with normal tap water before going to school.","zh":"學生上學前可能用一般自來水裝滿水樽。"},{"en":"If people worry about normal tap water, they may boil or filter it.","zh":"如果人們擔心一般自來水，可能會煮沸或過濾。"},{"en":"This phrase contrasts ordinary tap water with specially treated water.","zh":"這個短語把普通自來水與特別處理的水作對比。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":3},{"front":"full of contaminants","meaning":"充滿污染物","examples":[{"en":"The passage says that normal tap water is full of contaminants.","zh":"文章說一般自來水充滿污染物。"},{"en":"Full of contaminants means containing many unwanted or harmful substances.","zh":"full of contaminants 指含有許多不需要或有害物質。"},{"en":"A pond full of contaminants may smell bad and be unsafe for swimming.","zh":"充滿污染物的池塘可能氣味難聞，也不適合游泳。"},{"en":"If water is full of contaminants, people may avoid drinking it untreated.","zh":"如果水充滿污染物，人們可能避免未經處理就飲用。"},{"en":"This phrase is strong and suggests serious impurity.","zh":"這個短語語氣強，暗示嚴重不純。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":3},{"front":"such as chlorine and bromine","meaning":"例如氯和溴","examples":[{"en":"Chemicals such as chlorine and bromine are used to disinfect water.","zh":"例如氯和溴等化學物質被用來為水消毒。"},{"en":"Such as chlorine and bromine introduces specific examples of chemicals.","zh":"such as chlorine and bromine 用來引出化學物質的具體例子。"},{"en":"Cleaning products may contain chemicals such as alcohol or bleach.","zh":"清潔產品可能含有酒精或漂白劑等化學物質。"},{"en":"Examples after such as help readers understand the category being discussed.","zh":"such as 後面的例子幫助讀者理解正在討論的類別。"},{"en":"This phrase is useful when moving from a general group to named examples.","zh":"從一般類別轉到具名例子時，這個短語很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":3},{"front":"chlorine","meaning":"氯","examples":[{"en":"Chlorine is used to disinfect tap water.","zh":"氯被用來為自來水消毒。"},{"en":"Chlorine is a chemical often used to kill germs in water.","zh":"chlorine 指一種常用來殺滅水中病菌的化學物質。"},{"en":"Swimming pools often smell of chlorine because it is used for disinfection.","zh":"游泳池常有氯味，因為它被用於消毒。"},{"en":"Chlorine can make water safer from germs, but some people dislike its taste or smell.","zh":"氯可以令水免受病菌污染而較安全，但有些人不喜歡其味道或氣味。"},{"en":"This word is common in water treatment and pool maintenance.","zh":"這個詞常見於水處理和泳池保養。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":3},{"front":"bromine","meaning":"溴","examples":[{"en":"Long-term consumption of bromine may be harmful.","zh":"長期攝取溴可能有害。"},{"en":"Bromine is a chemical element sometimes mentioned in water-disinfection contexts.","zh":"bromine 指一種化學元素，有時在水消毒語境中被提及。"},{"en":"A water report may list bromine-related substances if they are present.","zh":"如果水中存在與溴相關的物質，水質報告可能列出它們。"},{"en":"If people worry about bromine in water, they may check testing results before choosing a filter.","zh":"如果人們擔心水中的溴，可能在選擇濾水器前查看測試結果。"},{"en":"This word is technical and usually appears in chemistry or water-quality discussions.","zh":"這個詞較技術性，通常出現在化學或水質討論中。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":3},{"front":"in order to disinfect","meaning":"為了消毒","examples":[{"en":"The authorities use chemicals in order to disinfect tap water.","zh":"當局使用化學物質，是為了為自來水消毒。"},{"en":"In order to disinfect means for the purpose of killing germs or making something cleaner.","zh":"in order to disinfect 指為了殺滅病菌或令某物更清潔。"},{"en":"Hospitals clean equipment carefully in order to disinfect it before use.","zh":"醫院在使用前仔細清潔設備，是為了消毒。"},{"en":"Disinfection is done to reduce the risk of infection.","zh":"消毒是為了降低感染風險。"},{"en":"This phrase clearly explains the purpose of an action.","zh":"這個短語清楚解釋行動目的。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":3},{"front":"disinfect water","meaning":"為水消毒","examples":[{"en":"Chlorine and bromine can be used to disinfect water.","zh":"氯和溴可以用來為水消毒。"},{"en":"To disinfect water means to treat it so that harmful germs are killed or reduced.","zh":"disinfect water 指處理水，以殺死或減少有害病菌。"},{"en":"Campers may disinfect water before drinking from a stream.","zh":"露營者飲用溪水前可能會為水消毒。"},{"en":"If water is not disinfected, harmful microorganisms may remain in it.","zh":"如果水沒有被消毒，有害微生物可能仍留在水中。"},{"en":"This phrase is common in public health and water treatment.","zh":"這個短語常見於公共健康和水處理。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":3},{"front":"hardly safe","meaning":"不算安全","examples":[{"en":"The passage suggests that some disinfectant chemicals are hardly safe.","zh":"文章暗示某些消毒化學物質不算安全。"},{"en":"Hardly safe means not really safe or only barely safe.","zh":"hardly safe 指不真正安全，或只是勉強安全。"},{"en":"A broken staircase is hardly safe for young children.","zh":"破損樓梯對幼童來說不算安全。"},{"en":"If something is hardly safe, people may look for a better alternative.","zh":"如果某物不算安全，人們可能尋找更好的替代方案。"},{"en":"This phrase expresses strong doubt about safety.","zh":"這個短語表達對安全性的強烈懷疑。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":3},{"front":"indeed","meaning":"事實上","examples":[{"en":"Indeed, some chemicals may be dangerous for children and pregnant women.","zh":"事實上，有些化學物質可能對兒童和孕婦危險。"},{"en":"Indeed is used to add emphasis or strengthen a previous point.","zh":"indeed 用來加強語氣或強化前一點。"},{"en":"The test was difficult; indeed, half the class could not finish it.","zh":"測驗很難；事實上，全班一半人未能完成。"},{"en":"Writers use indeed when the next sentence gives stronger evidence.","zh":"當下一句提供更強證據時，作者會使用 indeed。"},{"en":"This word often means “in fact” or “actually” in formal writing.","zh":"這個詞在正式寫作中常表示「事實上」。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":3},{"front":"be associated with","meaning":"與……有關","examples":[{"en":"The use of certain chemicals in water is associated with health conditions.","zh":"水中使用某些化學物質與健康狀況有關。"},{"en":"To be associated with something means to be connected with it in some way.","zh":"be associated with something 指以某種方式與某事有聯繫。"},{"en":"Lack of sleep is often associated with poor concentration.","zh":"睡眠不足常與專注力差有關。"},{"en":"An association does not always prove direct cause, but it suggests a relationship.","zh":"關聯不一定證明直接因果，但暗示兩者有關係。"},{"en":"This phrase is common in health and research writing.","zh":"這個短語常見於健康和研究寫作。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":3},{"front":"many different conditions","meaning":"多種不同健康狀況","examples":[{"en":"The use of some chemicals is associated with many different conditions.","zh":"使用某些化學物質與多種不同健康狀況有關。"},{"en":"Many different conditions means many types of illnesses, states, or health problems.","zh":"many different conditions 指許多類型的疾病、狀態或健康問題。"},{"en":"A doctor may ask questions because tiredness can be linked to many different conditions.","zh":"醫生可能會提問，因為疲倦可與多種不同健康狀況有關。"},{"en":"When a symptom has many possible conditions behind it, diagnosis becomes harder.","zh":"當一個症狀背後有多種可能狀況，診斷會變得較難。"},{"en":"This phrase shows variety in possible health situations.","zh":"這個短語顯示可能健康情況的多樣性。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":4},{"front":"particularly dangerous for","meaning":"對……尤其危險","examples":[{"en":"Some chemicals are particularly dangerous for children and pregnant women.","zh":"有些化學物質對兒童和孕婦尤其危險。"},{"en":"Particularly dangerous for means especially risky or harmful to a certain group.","zh":"particularly dangerous for 指對某群體特別有風險或有害。"},{"en":"Extreme heat can be particularly dangerous for elderly people.","zh":"極端高溫對長者可能尤其危險。"},{"en":"Some groups need extra protection because their bodies are more vulnerable.","zh":"有些群體需要額外保護，因為他們身體較脆弱。"},{"en":"This phrase highlights who faces the greatest risk.","zh":"這個短語突出誰面對最大風險。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":4},{"front":"pregnant women","meaning":"孕婦","examples":[{"en":"Pregnant women may be more vulnerable to some chemicals.","zh":"孕婦可能較容易受某些化學物質影響。"},{"en":"Pregnant women are women who are carrying developing babies in their bodies.","zh":"pregnant women 指身體內懷有胎兒的女性。"},{"en":"Doctors may advise pregnant women to avoid certain foods or substances.","zh":"醫生可能建議孕婦避免某些食物或物質。"},{"en":"Extra caution is often used because both the mother and baby may be affected.","zh":"人們常會格外小心，因為母親和胎兒都可能受影響。"},{"en":"This phrase is common in health and safety advice.","zh":"這個短語常見於健康和安全建議。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":4},{"front":"long-term consumption of","meaning":"長期攝取……","examples":[{"en":"Long-term consumption of bromine may result in low blood pressure.","zh":"長期攝取溴可能導致低血壓。"},{"en":"Long-term consumption of something means taking it into the body repeatedly over a long period.","zh":"long-term consumption of something 指長時間反覆把某物攝入身體。"},{"en":"Long-term consumption of sugary drinks can affect teeth and weight.","zh":"長期攝取含糖飲品可能影響牙齒和體重。"},{"en":"Repeated exposure over time may matter more than one small amount.","zh":"長期反覆接觸可能比一次少量接觸更重要。"},{"en":"This phrase is often used when discussing health risks.","zh":"討論健康風險時，常使用這個短語。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":4},{"front":"may result in","meaning":"可能導致","examples":[{"en":"Long-term consumption of bromine may result in low blood pressure.","zh":"長期攝取溴可能導致低血壓。"},{"en":"May result in means may cause or lead to a particular outcome.","zh":"may result in 指可能造成或導致某結果。"},{"en":"Skipping breakfast may result in tiredness during morning lessons.","zh":"不吃早餐可能導致早上上課時疲倦。"},{"en":"This phrase shows possible cause and effect, not absolute certainty.","zh":"這個短語顯示可能的因果，而不是絕對肯定。"},{"en":"It is useful when discussing risks or consequences.","zh":"討論風險或後果時，它很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":4},{"front":"low blood pressure","meaning":"低血壓","examples":[{"en":"Bromine consumption may result in low blood pressure.","zh":"攝取溴可能導致低血壓。"},{"en":"Low blood pressure means blood pressure is below the usual healthy range.","zh":"low blood pressure 指血壓低於一般健康範圍。"},{"en":"A person with low blood pressure may feel dizzy when standing up quickly.","zh":"低血壓的人快速站起來時可能感到頭暈。"},{"en":"If someone often feels faint, a doctor may check their blood pressure.","zh":"如果某人經常感到暈眩，醫生可能檢查其血壓。"},{"en":"This phrase is a health term related to circulation.","zh":"這個短語是與血液循環有關的健康術語。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":4},{"front":"poison the brain","meaning":"毒害大腦","examples":[{"en":"Some chemicals may poison the brain.","zh":"有些化學物質可能毒害大腦。"},{"en":"To poison the brain means to damage the brain with a toxic substance.","zh":"poison the brain 指有毒物質對大腦造成損害。"},{"en":"Certain industrial chemicals can poison the body if workers are not protected.","zh":"如果工人沒有受到保護，某些工業化學品可以毒害身體。"},{"en":"If the brain is poisoned, thinking, memory, or movement may be affected.","zh":"如果大腦受毒害，思考、記憶或動作都可能受影響。"},{"en":"This phrase is very strong and describes serious harm.","zh":"這個短語語氣很強，描述嚴重傷害。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":4},{"front":"the brain, heart, kidneys and liver","meaning":"大腦、心臟、腎臟和肝臟","examples":[{"en":"Some chemicals may affect the brain, heart, kidneys and liver.","zh":"有些化學物質可能影響大腦、心臟、腎臟和肝臟。"},{"en":"The brain, heart, kidneys and liver are major organs needed for life and body function.","zh":"brain, heart, kidneys and liver 是維持生命和身體功能所需的重要器官。"},{"en":"Doctors often monitor these organs when checking serious illness.","zh":"醫生檢查嚴重疾病時常會監察這些器官。"},{"en":"If harmful substances affect these organs, the whole body may suffer.","zh":"如果有害物質影響這些器官，整個身體都可能受損。"},{"en":"This phrase lists several vital parts of the body.","zh":"這個短語列出幾個身體重要部位。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":4},{"front":"vital organs","meaning":"重要器官","examples":[{"en":"The brain, heart, kidneys and liver are vital organs.","zh":"大腦、心臟、腎臟和肝臟都是重要器官。"},{"en":"Vital organs are body parts essential for survival and normal body function.","zh":"vital organs 指對生存和正常身體功能必不可少的身體部位。"},{"en":"The heart is a vital organ because it pumps blood around the body.","zh":"心臟是重要器官，因為它把血液泵到全身。"},{"en":"Damage to vital organs can create serious health risks.","zh":"重要器官受損可以造成嚴重健康風險。"},{"en":"This phrase is common in health and biology.","zh":"這個短語常見於健康和生物。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":4},{"front":"typically free of","meaning":"通常不含……","examples":[{"en":"Filtered water is typically free of disinfectant chemicals.","zh":"過濾水通常不含消毒化學物質。"},{"en":"Typically free of means usually does not contain something.","zh":"typically free of 指通常不含某物。"},{"en":"A quiet study room is typically free of loud conversation.","zh":"安靜自修室通常沒有大聲談話。"},{"en":"If something is typically free of a substance, people expect not to find it there most of the time.","zh":"如果某物通常不含某物質，人們預期大多數時候找不到它。"},{"en":"This phrase describes a usual condition, not a guaranteed rule.","zh":"這個短語描述通常情況，而不是保證規則。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":4},{"front":"disinfectant chemicals","meaning":"消毒化學物質","examples":[{"en":"Filtered water is typically free of disinfectant chemicals used in tap water.","zh":"過濾水通常不含自來水中使用的消毒化學物質。"},{"en":"Disinfectant chemicals are chemicals used to kill or reduce germs.","zh":"disinfectant chemicals 指用來殺死或減少病菌的化學物質。"},{"en":"Hospitals use disinfectant chemicals to clean surfaces after patient contact.","zh":"醫院在病人接觸後使用消毒化學物質清潔表面。"},{"en":"These chemicals can reduce infection risk when used properly.","zh":"這些化學物質若使用得當，可以降低感染風險。"},{"en":"This phrase is common in hygiene, cleaning, and water treatment.","zh":"這個短語常見於衛生、清潔和水處理。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":4},{"front":"metals such as mercury and lead","meaning":"水銀和鉛等金屬","examples":[{"en":"Filtered water is also free of metals such as mercury and lead.","zh":"過濾水也不含水銀和鉛等金屬。"},{"en":"Metals such as mercury and lead are examples of heavy metals that may be harmful in drinking water.","zh":"metals such as mercury and lead 指飲用水中可能有害的重金屬例子。"},{"en":"A water test may check for metals such as mercury and lead in old buildings.","zh":"水質測試可能檢查舊建築物中是否有水銀和鉛等金屬。"},{"en":"If these metals enter water, people may choose filters designed to reduce them.","zh":"如果這些金屬進入水中，人們可能選擇專門減少它們的濾水器。"},{"en":"This phrase gives specific examples of dangerous metals.","zh":"這個短語提供危險金屬的具體例子。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":5},{"front":"mercury","meaning":"水銀","examples":[{"en":"Mercury can end up in drinking water.","zh":"水銀可能最終進入飲用水。"},{"en":"Mercury is a metal that can be toxic if it enters the body in unsafe amounts.","zh":"mercury 指一種金屬，若以不安全分量進入身體，可能有毒。"},{"en":"Environmental reports may test fish or water for mercury.","zh":"環境報告可能檢測魚類或水中是否有水銀。"},{"en":"If mercury pollution enters rivers, it may affect water and food chains.","zh":"如果水銀污染進入河流，可能影響水和食物鏈。"},{"en":"This word is common in pollution and health discussions.","zh":"這個詞常見於污染和健康討論。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":5},{"front":"lead","meaning":"鉛","examples":[{"en":"Lead can enter drinking water through old pipes.","zh":"鉛可以透過舊水管進入飲用水。"},{"en":"Lead is a heavy metal that can be harmful when people are exposed to unsafe levels.","zh":"lead 指一種重金屬，當人接觸不安全水平時可能有害。"},{"en":"Older houses may be checked for lead in paint or pipes.","zh":"舊屋可能需要檢查油漆或水管中是否有鉛。"},{"en":"If lead enters water through plumbing, residents may need repairs or filtration.","zh":"如果鉛透過水管系統進入水中，居民可能需要維修或過濾。"},{"en":"This word is important in public health and building safety.","zh":"這個詞在公共健康和建築安全中很重要。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":5},{"front":"end up in","meaning":"最終進入","examples":[{"en":"Mercury has ended up in drinking water because of unsafe waste disposal.","zh":"水銀因不安全廢物棄置而最終進入飲用水。"},{"en":"To end up in a place means to finally arrive there, often unexpectedly or undesirably.","zh":"end up in a place 指最終到達某處，常帶意外或不理想意味。"},{"en":"Plastic rubbish can end up in the sea if it is not collected properly.","zh":"如果塑膠垃圾沒有妥善收集，可能最終進入海洋。"},{"en":"Waste can travel through drains, rivers, and soil before ending up in water supplies.","zh":"廢物可以經排水渠、河流和土壤移動，最後進入供水。"},{"en":"This phrase often describes an unwanted final destination.","zh":"這個短語常描述不想要的最終去向。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":5},{"front":"drinking water","meaning":"飲用水","examples":[{"en":"Mercury and lead may be found in drinking water.","zh":"水銀和鉛可能存在於飲用水中。"},{"en":"Drinking water is water considered suitable for people to drink.","zh":"drinking water 指被認為適合人飲用的水。"},{"en":"Schools must provide safe drinking water for students.","zh":"學校必須為學生提供安全飲用水。"},{"en":"If drinking water is contaminated, public health can be affected quickly.","zh":"如果飲用水受污染，公共健康可能很快受影響。"},{"en":"This phrase focuses on water used for human consumption.","zh":"這個短語聚焦供人飲用的水。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":5},{"front":"mainly because","meaning":"主要因為","examples":[{"en":"Mercury has ended up in drinking water mainly because of dental waste.","zh":"水銀最終進入飲用水，主要因為牙科廢料。"},{"en":"Mainly because means chiefly or mostly for that reason.","zh":"mainly because 指主要或大多數是因為那個原因。"},{"en":"Students may feel tired mainly because they sleep too late.","zh":"學生感到疲倦可能主要因為睡得太晚。"},{"en":"This phrase identifies the most important cause among possible causes.","zh":"這個短語在多個可能原因中指出最重要原因。"},{"en":"It is useful when one reason matters more than others.","zh":"當一個原因比其他原因更重要時，它很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":5},{"front":"dental amalgam waste","meaning":"牙科汞合金廢料","examples":[{"en":"Dental amalgam waste has not always been disposed of safely.","zh":"牙科汞合金廢料長時間以來並非總是被安全棄置。"},{"en":"Dental amalgam waste is waste from dental materials that contain a mixture of metals.","zh":"dental amalgam waste 指來自含多種金屬牙科材料的廢料。"},{"en":"Dental clinics need proper systems for handling dental waste.","zh":"牙科診所需要適當系統處理牙科廢料。"},{"en":"If dental waste is not managed safely, harmful materials may enter the environment.","zh":"如果牙科廢料沒有安全管理，有害材料可能進入環境。"},{"en":"This phrase is technical and belongs to dentistry and waste management.","zh":"這個短語較技術性，屬於牙科和廢物管理。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":5},{"front":"produced by dentists","meaning":"由牙醫產生","examples":[{"en":"Dental amalgam waste is produced by dentists.","zh":"牙科汞合金廢料由牙醫產生。"},{"en":"Produced by dentists means created as part of dental work or dental treatment.","zh":"produced by dentists 指作為牙科工作或牙科治療一部分而產生。"},{"en":"Clinics produce medical waste when doctors and nurses treat patients.","zh":"診所醫生和護士治療病人時會產生醫療廢物。"},{"en":"Waste produced by professionals must often be handled under safety rules.","zh":"專業人士產生的廢物通常必須按安全規則處理。"},{"en":"This phrase identifies the source of the waste.","zh":"這個短語指出廢物來源。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":5},{"front":"be disposed of safely","meaning":"被安全棄置","examples":[{"en":"Dental amalgam waste should be disposed of safely.","zh":"牙科汞合金廢料應被安全棄置。"},{"en":"To be disposed of safely means to be thrown away or treated without harming people or the environment.","zh":"be disposed of safely 指以不傷害人或環境的方式丟棄或處理。"},{"en":"Used needles must be disposed of safely in hospitals.","zh":"醫院中的用過針筒必須被安全棄置。"},{"en":"Safe disposal prevents dangerous substances from entering water, soil, or workplaces.","zh":"安全棄置防止危險物質進入水、土壤或工作場所。"},{"en":"This phrase is common in waste management and public health.","zh":"這個短語常見於廢物管理和公共健康。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":5},{"front":"for a long time","meaning":"長時間以來","examples":[{"en":"Dental amalgam waste was not disposed of safely for a long time.","zh":"牙科汞合金廢料長時間以來沒有被安全棄置。"},{"en":"For a long time means over many years or a long period.","zh":"for a long time 指多年或很長一段時間。"},{"en":"A family business may stay in the same shop for a long time.","zh":"家族企業可能長時間以來都在同一間店經營。"},{"en":"If a bad practice continues for a long time, its effects may build up.","zh":"如果壞做法持續很長時間，其影響可能累積。"},{"en":"This phrase gives a broad sense of duration.","zh":"這個短語提供大概的持續時間。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":5},{"front":"scientists believe","meaning":"科學家認為","examples":[{"en":"Scientists believe there may be a connection between mercury and some health problems.","zh":"科學家認為水銀與某些健康問題之間可能有關聯。"},{"en":"Scientists believe means researchers think something is likely based on evidence or study.","zh":"scientists believe 指研究人員根據證據或研究認為某事可能成立。"},{"en":"Scientists believe regular exercise can support heart health.","zh":"科學家認為定期運動可以支持心臟健康。"},{"en":"This phrase presents a view from scientific experts, not casual opinion.","zh":"這個短語提出來自科學專家的看法，而不是隨便意見。"},{"en":"It is often followed by a cautious claim.","zh":"它後面常接較謹慎的說法。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":5},{"front":"a connection between","meaning":"……之間的關聯","examples":[{"en":"The passage mentions a connection between mercury in water and some diseases.","zh":"文章提到水中水銀與某些疾病之間的關聯。"},{"en":"A connection between two things is a relationship or link between them.","zh":"connection between two things 指兩件事之間的關係或連繫。"},{"en":"A teacher may notice a connection between poor sleep and late homework.","zh":"老師可能注意到睡眠不足和遲交功課之間的關聯。"},{"en":"Finding a connection can help people investigate causes more carefully.","zh":"找到關聯可以幫助人們更仔細調查原因。"},{"en":"This phrase does not always mean one thing directly causes the other.","zh":"這個短語不一定表示一件事直接造成另一件事。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":6},{"front":"allergies and cancers","meaning":"過敏和癌症","examples":[{"en":"The passage links mercury in water with allergies and cancers.","zh":"文章把水中的水銀與過敏和癌症聯繫起來。"},{"en":"Allergies and cancers are health conditions involving immune reactions and abnormal cell growth.","zh":"allergies and cancers 指涉及免疫反應和異常細胞生長的健康狀況。"},{"en":"Doctors may ask about allergies before giving medicine.","zh":"醫生給藥前可能詢問病人有否過敏。"},{"en":"Cancer concerns often lead people to pay close attention to environmental risks.","zh":"對癌症的擔憂常令人密切注意環境風險。"},{"en":"This phrase lists serious health topics mentioned in the passage.","zh":"這個短語列出文章提到的嚴重健康主題。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":6},{"front":"as well as","meaning":"以及","examples":[{"en":"The passage mentions allergies and cancers as well as several disorders.","zh":"文章提到過敏和癌症，以及幾種障礙。"},{"en":"As well as means in addition to.","zh":"as well as 指以及；除了某物之外還有。"},{"en":"A school trip may include museums as well as outdoor activities.","zh":"學校旅行可能包括博物館以及戶外活動。"},{"en":"This phrase adds extra items without making a new sentence.","zh":"這個短語不用另開新句也能加入額外項目。"},{"en":"It is useful when listing related things.","zh":"列出相關事物時，它很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":6},{"front":"disorders such as","meaning":"例如……的疾病；障礙","examples":[{"en":"The passage refers to disorders such as ADD, OCD, autism and depression.","zh":"文章提到例如 ADD、OCD、自閉症和抑鬱症等障礙。"},{"en":"Disorders such as introduces examples of medical or psychological conditions.","zh":"disorders such as 用來引出醫學或心理狀況的例子。"},{"en":"Clinics may support people with disorders such as anxiety or depression.","zh":"診所可能支援患有焦慮或抑鬱等障礙的人。"},{"en":"Giving examples helps readers understand what type of disorder is being discussed.","zh":"提供例子有助讀者理解正在討論哪類障礙。"},{"en":"This phrase is formal and common in health writing.","zh":"這個短語較正式，常見於健康寫作。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":6},{"front":"ADD","meaning":"注意力不足症","examples":[{"en":"ADD is mentioned as one of the disorders linked to mercury in water.","zh":"ADD 被提及為與水中水銀有關的障礙之一。"},{"en":"ADD stands for attention deficit disorder.","zh":"ADD 是 attention deficit disorder 的縮寫。"},{"en":"A student with ADD may find it hard to stay focused on long tasks.","zh":"有注意力不足症的學生可能難以長時間專注於任務。"},{"en":"Clear routines and shorter steps can help some learners manage attention difficulties.","zh":"清楚常規和較短步驟可以幫助部分學習者管理注意力困難。"},{"en":"This abbreviation appears in health and education contexts.","zh":"這個縮寫出現在健康和教育語境。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":6},{"front":"OCD","meaning":"強迫症","examples":[{"en":"OCD is mentioned together with other disorders.","zh":"OCD 與其他障礙一起被提及。"},{"en":"OCD stands for obsessive-compulsive disorder.","zh":"OCD 是 obsessive-compulsive disorder 的縮寫。"},{"en":"A person with OCD may feel driven to repeat certain actions or thoughts.","zh":"有強迫症的人可能感到被迫重複某些行為或想法。"},{"en":"Mental health conditions can affect daily routines, schoolwork, and relationships.","zh":"心理健康狀況可以影響日常生活、學業和關係。"},{"en":"This abbreviation is common in psychology and health discussions.","zh":"這個縮寫常見於心理學和健康討論。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":6},{"front":"autism","meaning":"自閉症","examples":[{"en":"Autism is mentioned as one of the disorders in the passage.","zh":"自閉症被提及為文章中的障礙之一。"},{"en":"Autism is a developmental condition that can affect communication, behaviour, and social interaction.","zh":"autism 指一種發展狀況，可能影響溝通、行為和社交互動。"},{"en":"An autistic student may need clear routines and sensory-friendly spaces.","zh":"自閉症學生可能需要清楚常規和感官友善空間。"},{"en":"Understanding autism helps schools support different learning needs.","zh":"理解自閉症有助學校支援不同學習需要。"},{"en":"This word is common in health, education, and inclusion discussions.","zh":"這個詞常見於健康、教育和共融討論。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":6},{"front":"depression","meaning":"抑鬱症","examples":[{"en":"Depression is mentioned as a possible disorder connected with water contamination.","zh":"抑鬱症被提及為可能與水污染有關的障礙。"},{"en":"Depression is a mental health condition involving persistent low mood or loss of interest.","zh":"depression 指涉及持續情緒低落或失去興趣的心理健康狀況。"},{"en":"A person with depression may struggle with sleep, energy, and daily tasks.","zh":"患有抑鬱症的人可能在睡眠、精力和日常任務上遇到困難。"},{"en":"Support, treatment, and understanding can help people manage depression.","zh":"支援、治療和理解可以幫助人管理抑鬱症。"},{"en":"This word is common in mental health discussions.","zh":"這個詞常見於心理健康討論。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":6},{"front":"on the other hand","meaning":"另一方面","examples":[{"en":"Lead, on the other hand, usually enters drinking water through pipe leaks.","zh":"另一方面，鉛通常透過水管滲漏進入飲用水。"},{"en":"On the other hand introduces a contrasting point or different case.","zh":"on the other hand 用來引出對比點或另一種情況。"},{"en":"Filtered water may cost more; on the other hand, it may reduce plastic bottle use.","zh":"過濾水可能成本較高；另一方面，它可能減少膠樽使用。"},{"en":"This phrase helps writers compare two sides of a topic.","zh":"這個短語幫助作者比較議題的兩面。"},{"en":"It is useful when moving from one example to another different example.","zh":"從一個例子轉到另一個不同例子時，它很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":6},{"front":"find its way into","meaning":"進入……","examples":[{"en":"Lead typically finds its way into drinking water through pipe leaks.","zh":"鉛通常透過水管滲漏進入飲用水。"},{"en":"To find its way into something means to enter it, often gradually or indirectly.","zh":"find its way into something 指進入某物，常是逐漸或間接地。"},{"en":"Dust can find its way into a computer if the room is not cleaned.","zh":"如果房間不清潔，灰塵可以進入電腦。"},{"en":"When a substance finds its way into water, people may not notice it immediately.","zh":"當某物質進入水中，人們未必立即察覺。"},{"en":"This phrase often describes unwanted entry.","zh":"這個短語常描述不受歡迎的進入。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":6},{"front":"due to","meaning":"由於","examples":[{"en":"Lead may enter drinking water due to pipe leaks.","zh":"鉛可能由於水管滲漏而進入飲用水。"},{"en":"Due to means because of.","zh":"due to 指因為。"},{"en":"The class was cancelled due to heavy rain.","zh":"課堂由於大雨而取消。"},{"en":"This phrase introduces the cause of a situation.","zh":"這個短語引出某情況的原因。"},{"en":"It is common in formal notices and explanations.","zh":"它常見於正式通知和解釋。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":6},{"front":"pipe leaks","meaning":"水管滲漏","examples":[{"en":"Pipe leaks can allow lead to enter drinking water.","zh":"水管滲漏可以讓鉛進入飲用水。"},{"en":"Pipe leaks are openings or cracks in pipes that let water or substances escape or enter.","zh":"pipe leaks 指水管中的開口或裂縫，令水或物質流出或進入。"},{"en":"A wet wall may be a sign of pipe leaks inside a building.","zh":"牆身潮濕可能是建築物內水管滲漏的跡象。"},{"en":"If pipes leak, repair is needed before damage becomes worse.","zh":"如果水管滲漏，需在損害惡化前維修。"},{"en":"This phrase is common in plumbing and building maintenance.","zh":"這個短語常見於水管和建築維修。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":7},{"front":"modern pipes","meaning":"現代水管","examples":[{"en":"Modern pipes are not usually made of lead.","zh":"現代水管通常不是由鉛製成。"},{"en":"Modern pipes are newer pipes made with current materials and safety standards.","zh":"modern pipes 指用當代材料和安全標準製成的新式水管。"},{"en":"A renovated flat may have modern pipes instead of old metal pipes.","zh":"翻新單位可能有現代水管，而不是舊金屬水管。"},{"en":"Newer materials can reduce some risks found in old plumbing.","zh":"較新材料可以減少舊水管系統中的某些風險。"},{"en":"This phrase contrasts newer building systems with older ones.","zh":"這個短語把較新的建築系統與舊系統作對比。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":7},{"front":"be made of lead","meaning":"由鉛製成","examples":[{"en":"Pipes in old houses may be made of lead.","zh":"舊屋中的水管可能由鉛製成。"},{"en":"To be made of lead means to be constructed using the metal lead.","zh":"be made of lead 指用鉛這種金屬製成。"},{"en":"Old paint or pipes may contain materials that are no longer commonly used.","zh":"舊油漆或水管可能含有現時不常使用的材料。"},{"en":"If pipes are made of lead, testing water quality may be important.","zh":"如果水管由鉛製成，檢測水質可能很重要。"},{"en":"This phrase describes material composition.","zh":"這個短語描述材料構成。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":7},{"front":"old houses","meaning":"舊屋","examples":[{"en":"Pipes in old houses may contain lead.","zh":"舊屋中的水管可能含有鉛。"},{"en":"Old houses are buildings built many years ago, often using older materials or systems.","zh":"old houses 指多年前建成、常使用較舊材料或系統的建築物。"},{"en":"People buying old houses may inspect wiring, pipes, and walls carefully.","zh":"購買舊屋的人可能仔細檢查電線、水管和牆身。"},{"en":"Older buildings can have charm, but they may also need safety upgrades.","zh":"舊建築可以很有韻味，但也可能需要安全升級。"},{"en":"This phrase gives a common context for outdated plumbing.","zh":"這個短語提供舊式水管常見的背景。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":7},{"front":"a well-known carcinogen","meaning":"眾所周知的致癌物","examples":[{"en":"Lead is described as a well-known carcinogen.","zh":"鉛被描述為眾所周知的致癌物。"},{"en":"A well-known carcinogen is a substance widely recognised as capable of causing cancer.","zh":"well-known carcinogen 指被廣泛認為能引致癌症的物質。"},{"en":"Health warnings may identify a chemical as a well-known carcinogen.","zh":"健康警告可能把某化學物質列為眾所周知的致癌物。"},{"en":"If something is a known carcinogen, people try to reduce exposure to it.","zh":"如果某物是已知致癌物，人們會嘗試減少接觸。"},{"en":"This phrase is serious and common in health-risk discussions.","zh":"這個短語語氣嚴肅，常見於健康風險討論。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":7},{"front":"carcinogen","meaning":"致癌物","examples":[{"en":"A carcinogen is a substance that can cause cancer.","zh":"致癌物是可以引致癌症的物質。"},{"en":"A carcinogen is any agent or substance that may increase the risk of cancer.","zh":"carcinogen 指任何可能增加癌症風險的因素或物質。"},{"en":"Some workplace chemicals are controlled because they are carcinogens.","zh":"有些工作場所化學物因為是致癌物而受到管制。"},{"en":"Reducing contact with carcinogens can lower certain health risks.","zh":"減少接觸致癌物可以降低某些健康風險。"},{"en":"This word is common in medicine, public health, and safety labels.","zh":"這個詞常見於醫學、公共健康和安全標籤。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":7},{"front":"be associated with pregnancy problems","meaning":"與懷孕問題有關","examples":[{"en":"Lead is associated with pregnancy problems.","zh":"鉛與懷孕問題有關。"},{"en":"To be associated with pregnancy problems means to be connected with risks during pregnancy.","zh":"be associated with pregnancy problems 指與懷孕期間的風險有關。"},{"en":"Doctors may warn pregnant women about substances associated with pregnancy problems.","zh":"醫生可能提醒孕婦注意與懷孕問題有關的物質。"},{"en":"If a substance is linked with pregnancy risks, extra caution is usually advised.","zh":"如果某物質與懷孕風險有關，通常會建議格外小心。"},{"en":"This phrase is common in health and safety discussions.","zh":"這個短語常見於健康和安全討論。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":7},{"front":"pregnancy problems","meaning":"懷孕問題","examples":[{"en":"Lead exposure is associated with pregnancy problems.","zh":"接觸鉛與懷孕問題有關。"},{"en":"Pregnancy problems are health difficulties that occur during pregnancy.","zh":"pregnancy problems 指懷孕期間出現的健康困難。"},{"en":"Pregnant women may attend check-ups so doctors can detect pregnancy problems early.","zh":"孕婦可能定期檢查，讓醫生及早發現懷孕問題。"},{"en":"Early care can reduce risks for both mother and baby.","zh":"早期護理可以降低母親和嬰兒的風險。"},{"en":"This phrase is general and may refer to many different medical issues.","zh":"這個短語較籠統，可指許多不同醫療問題。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":7},{"front":"birth defects","meaning":"先天缺陷","examples":[{"en":"Lead is associated with pregnancy problems and birth defects.","zh":"鉛與懷孕問題和先天缺陷有關。"},{"en":"Birth defects are physical or developmental problems present when a baby is born.","zh":"birth defects 指嬰兒出生時已有的身體或發展問題。"},{"en":"Doctors may screen for certain birth defects before birth.","zh":"醫生可能在出生前篩查某些先天缺陷。"},{"en":"Avoiding harmful substances during pregnancy can reduce some risks.","zh":"懷孕期間避免有害物質可以減少某些風險。"},{"en":"This phrase is common in medical and public-health contexts.","zh":"這個短語常見於醫學和公共健康語境。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":7},{"front":"another reason why","meaning":"另一個……的原因","examples":[{"en":"This is another reason why some people choose filtered water.","zh":"這是一些人選擇過濾水的另一個原因。"},{"en":"Another reason why introduces an additional explanation for a decision or belief.","zh":"another reason why 用來引出某決定或信念的額外解釋。"},{"en":"High cost is one problem; long travel time is another reason why students avoid the course.","zh":"成本高是一個問題；路程長是學生避開該課程的另一個原因。"},{"en":"Adding another reason can make an argument stronger.","zh":"加入另一個原因可以令論點更有力。"},{"en":"This phrase is useful when building a list of causes.","zh":"建立原因列表時，這個短語很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":7},{"front":"the benefits of water","meaning":"水的好處","examples":[{"en":"The benefits of water are well known.","zh":"水的好處眾所周知。"},{"en":"The benefits of water are the good effects water has on the body or daily life.","zh":"benefits of water 指水對身體或日常生活的良好影響。"},{"en":"Drinking enough water can help people feel more alert during school or work.","zh":"飲用足夠水分可以幫助人在學校或工作時更精神。"},{"en":"Because water supports many body functions, people are advised to drink enough each day.","zh":"因為水支援許多身體功能，人們被建議每天喝足夠水。"},{"en":"This phrase introduces positive effects connected with water.","zh":"這個短語引出與水有關的正面效果。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":7},{"front":"be well known","meaning":"眾所周知","examples":[{"en":"The benefits of water are well known.","zh":"水的好處眾所周知。"},{"en":"To be well known means to be widely understood or recognised by many people.","zh":"be well known 指被許多人廣泛理解或認識。"},{"en":"It is well known that regular practice helps language learning.","zh":"定期練習有助語言學習是眾所周知的。"},{"en":"When something is well known, writers may not need to explain it in great detail.","zh":"當某事眾所周知，作者可能不需要詳細解釋。"},{"en":"This phrase is used for common knowledge or widely accepted ideas.","zh":"這個短語用於常識或廣泛接受的想法。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":8},{"front":"help to detoxify","meaning":"幫助身體排毒","examples":[{"en":"Water helps to detoxify the body.","zh":"水幫助身體排毒。"},{"en":"To help to detoxify means to help remove or process unwanted substances from the body.","zh":"help to detoxify 指幫助身體清除或處理不需要的物質。"},{"en":"The body uses organs such as the liver and kidneys to process waste.","zh":"身體使用肝臟和腎臟等器官處理廢物。"},{"en":"Drinking enough water can support normal body functions related to waste removal.","zh":"飲用足夠水分可以支援與廢物排出相關的正常身體功能。"},{"en":"This phrase is often used in health-related writing.","zh":"這個短語常用於健康相關寫作。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":8},{"front":"detoxify the body","meaning":"為身體排毒","examples":[{"en":"Drinking water helps detoxify the body.","zh":"飲水有助為身體排毒。"},{"en":"To detoxify the body means to help the body remove or process toxins and waste.","zh":"detoxify the body 指幫助身體清除或處理毒素和廢物。"},{"en":"Hospitals may use treatment to help remove harmful substances from a patient’s body.","zh":"醫院可能使用治療方法幫助病人身體排出有害物質。"},{"en":"If the body cannot process waste properly, health problems may develop.","zh":"如果身體不能正常處理廢物，健康問題可能出現。"},{"en":"This phrase should be used carefully because the body already has natural detox systems.","zh":"使用這個短語時應小心，因為身體本身已有自然排毒系統。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":8},{"front":"the purer…, the easier…","meaning":"越……就越容易……","examples":[{"en":"The purer the water we drink, the easier it is for the body to remove toxins.","zh":"我們喝的水越純淨，身體清除毒素就越容易。"},{"en":"The purer…, the easier… means that as one thing becomes purer, another action becomes easier.","zh":"the purer…, the easier… 指一件事越純淨，另一個行動就越容易。"},{"en":"The clearer the instructions, the easier it is for students to finish the task.","zh":"指示越清楚，學生完成任務就越容易。"},{"en":"This structure shows a direct relationship between two changes.","zh":"這個結構顯示兩種變化之間的直接關係。"},{"en":"It is useful for comparing cause and result together.","zh":"它適合用來同時比較原因和結果。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":8},{"front":"rid itself of toxins","meaning":"清除體內毒素","examples":[{"en":"The body can rid itself of toxins more easily when the water is purer.","zh":"當水越純淨，身體就越容易清除體內毒素。"},{"en":"To rid itself of toxins means to remove harmful or unwanted substances from itself.","zh":"rid itself of toxins 指身體自行清除有害或不需要的物質。"},{"en":"The body uses urine, sweat, and other processes to remove waste.","zh":"身體透過尿液、汗液和其他過程排出廢物。"},{"en":"If unwanted substances build up, the body may need more effort to process them.","zh":"如果不需要的物質累積，身體可能需要更多力氣處理。"},{"en":"This phrase describes the body removing something harmful.","zh":"這個短語描述身體清除有害物質。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":8},{"front":"toxins","meaning":"毒素","examples":[{"en":"The body needs to rid itself of toxins.","zh":"身體需要清除體內毒素。"},{"en":"Toxins are harmful substances that can damage living cells or body systems.","zh":"toxins 指可以傷害活細胞或身體系統的有害物質。"},{"en":"Some bacteria produce toxins that make people sick.","zh":"有些細菌會產生令人患病的毒素。"},{"en":"If toxins enter food or water, health risks may increase.","zh":"如果毒素進入食物或水中，健康風險可能增加。"},{"en":"This word is common in biology and health discussions.","zh":"這個詞常見於生物和健康討論。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":8},{"front":"the result of drinking","meaning":"飲用……的結果","examples":[{"en":"The result of drinking filtered water is that the body uses less energy for detoxification.","zh":"飲用過濾水的結果是身體用於排毒的能量較少。"},{"en":"The result of drinking something means what happens after someone drinks it.","zh":"result of drinking something 指某人飲用某物後發生的事情。"},{"en":"The result of drinking too much coffee may be difficulty sleeping.","zh":"飲用太多咖啡的結果可能是難以入睡。"},{"en":"This phrase connects an action with its effect.","zh":"這個短語把行動與其效果連接起來。"},{"en":"It is useful when explaining consequences of a habit.","zh":"解釋習慣的後果時，它很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":8},{"front":"devote energy to","meaning":"把精力用於……","examples":[{"en":"The body does not have to devote as much energy to detoxification.","zh":"身體不必把同樣多精力用於排毒。"},{"en":"To devote energy to something means to use effort or resources for that purpose.","zh":"devote energy to something 指把努力或資源用於某目的。"},{"en":"A student may devote energy to revision instead of worrying about rumours.","zh":"學生可以把精力用於溫習，而不是擔心傳言。"},{"en":"If less energy is used for one task, more may be available for other functions.","zh":"如果某任務使用較少能量，就可能有更多能量供其他功能使用。"},{"en":"This phrase is useful when discussing effort and priorities.","zh":"討論努力和優先次序時，這個短語很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":8},{"front":"as much energy to","meaning":"同樣多精力於……","examples":[{"en":"The body does not need to devote as much energy to detoxification.","zh":"身體不需要把同樣多精力用於排毒。"},{"en":"As much energy to means the same amount of effort or energy for a task.","zh":"as much energy to 指把同樣多努力或能量用於某任務。"},{"en":"If homework is well organised, students may not need to devote as much energy to finding materials.","zh":"如果功課整理得好，學生可能不需要把同樣多精力用於尋找材料。"},{"en":"Saving energy on one process can leave more energy for another.","zh":"在一個過程中節省能量，可以留下更多能量給另一個過程。"},{"en":"This phrase is often used in comparisons of effort.","zh":"這個短語常用於比較努力。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":8},{"front":"detoxification","meaning":"排毒","examples":[{"en":"Filtered water may reduce the body’s need for detoxification.","zh":"過濾水可能減少身體對排毒的需要。"},{"en":"Detoxification is the process of removing or processing harmful substances.","zh":"detoxification 指清除或處理有害物質的過程。"},{"en":"The liver and kidneys are involved in the body’s natural detoxification processes.","zh":"肝臟和腎臟參與身體自然排毒過程。"},{"en":"If fewer harmful substances enter the body, detoxification may be less demanding.","zh":"如果較少有害物質進入身體，排毒負擔可能較低。"},{"en":"This word is common in health writing, but it should be used accurately.","zh":"這個詞常見於健康寫作，但應準確使用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":8},{"front":"unfiltered water","meaning":"未經過濾的水","examples":[{"en":"Unfiltered water may contain more contaminants.","zh":"未經過濾的水可能含有更多污染物。"},{"en":"Unfiltered water is water that has not passed through a filter.","zh":"unfiltered water 指沒有經過濾器處理的水。"},{"en":"Campers may avoid drinking unfiltered river water.","zh":"露營者可能避免飲用未經過濾的河水。"},{"en":"If water is unfiltered, substances in it may remain unless removed by another method.","zh":"如果水未經過濾，其中物質可能仍然存在，除非用其他方法去除。"},{"en":"This phrase contrasts with filtered water.","zh":"這個短語與過濾水形成對比。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":8},{"front":"in general","meaning":"一般來說；整體而言","examples":[{"en":"Drinking filtered water is described as good for health in general.","zh":"飲用過濾水被描述為整體而言對健康有益。"},{"en":"In general means overall or in most situations.","zh":"in general 指整體而言或在大多數情況下。"},{"en":"In general, students learn better when examples are clear.","zh":"一般來說，例子清楚時，學生學得更好。"},{"en":"This phrase allows a broad statement while leaving room for exceptions.","zh":"這個短語容許提出廣泛說法，同時保留例外空間。"},{"en":"It is useful when summarising the overall situation.","zh":"概括整體情況時，它很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":9},{"front":"perform all of its functions","meaning":"執行所有功能","examples":[{"en":"The body can perform all of its functions more easily.","zh":"身體可以更容易執行所有功能。"},{"en":"To perform all of its functions means to carry out all the jobs it needs to do.","zh":"perform all of its functions 指完成它需要做的所有工作。"},{"en":"A phone with enough battery can perform all of its functions during the day.","zh":"電話有足夠電量時，可以在一天中執行所有功能。"},{"en":"If the body has what it needs, its systems may work more smoothly.","zh":"如果身體有需要的東西，其系統可能運作得更順暢。"},{"en":"This phrase describes normal operation of a system.","zh":"這個短語描述系統的正常運作。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":9},{"front":"results in","meaning":"導致；帶來","examples":[{"en":"Better water quality may result in improved metabolism.","zh":"更好的水質可能帶來改善了的新陳代謝。"},{"en":"Results in means causes or leads to a particular outcome.","zh":"results in 指造成或導致某個結果。"},{"en":"Regular practice often results in better pronunciation.","zh":"定期練習常帶來更好的發音。"},{"en":"This phrase is used to show cause and effect.","zh":"這個短語用來顯示因果關係。"},{"en":"It is more formal than “leads to” in many contexts.","zh":"在許多語境中，它比 leads to 更正式。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":9},{"front":"improved metabolism","meaning":"改善了的新陳代謝","examples":[{"en":"Filtered water is linked in the passage to improved metabolism.","zh":"文章把過濾水與改善了的新陳代謝聯繫起來。"},{"en":"Improved metabolism means the body processes energy and nutrients more effectively.","zh":"improved metabolism 指身體更有效處理能量和營養。"},{"en":"Exercise and balanced meals are often discussed in relation to metabolism.","zh":"運動和均衡飲食常與新陳代謝一起討論。"},{"en":"If metabolism improves, the body may use food and energy more efficiently.","zh":"如果新陳代謝改善，身體可能更有效使用食物和能量。"},{"en":"This phrase belongs to health and body-function discussions.","zh":"這個短語屬於健康和身體功能討論。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":9},{"front":"better weight management","meaning":"更好的體重管理","examples":[{"en":"The passage connects filtered water with better weight management.","zh":"文章把過濾水與更好的體重管理連繫起來。"},{"en":"Better weight management means controlling body weight in a healthier or more effective way.","zh":"better weight management 指以更健康或更有效方式控制體重。"},{"en":"Regular meals, sleep, and exercise can support better weight management.","zh":"定時進食、睡眠和運動可以支持更好的體重管理。"},{"en":"If people manage weight better, they may reduce some health risks.","zh":"如果人們更好地管理體重，可能減少某些健康風險。"},{"en":"This phrase is common in health and lifestyle writing.","zh":"這個短語常見於健康和生活方式寫作。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":9},{"front":"improved joint lubrication","meaning":"改善關節潤滑","examples":[{"en":"Filtered water is said to support improved joint lubrication.","zh":"過濾水據說有助改善關節潤滑。"},{"en":"Improved joint lubrication means joints move more smoothly because there is enough fluid or support.","zh":"improved joint lubrication 指關節因有足夠液體或支援而更順暢地活動。"},{"en":"People may notice joint stiffness when movement feels dry or uncomfortable.","zh":"當活動感覺乾澀或不舒服，人們可能注意到關節僵硬。"},{"en":"Good hydration is often discussed as part of supporting normal joint function.","zh":"良好水分攝取常被視為支持正常關節功能的一部分。"},{"en":"This phrase belongs to body movement and health contexts.","zh":"這個短語屬於身體活動和健康語境。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":9},{"front":"efficient skin hydration","meaning":"有效皮膚保濕","examples":[{"en":"The passage mentions efficient skin hydration as a possible benefit.","zh":"文章提到有效皮膚保濕是可能好處之一。"},{"en":"Efficient skin hydration means the skin receives and keeps moisture effectively.","zh":"efficient skin hydration 指皮膚有效獲得並保持水分。"},{"en":"Drinking enough water and using moisturiser can support skin hydration.","zh":"飲用足夠水分和使用保濕產品可以支持皮膚保濕。"},{"en":"If skin lacks hydration, it may feel dry or tight.","zh":"如果皮膚缺乏水分，可能感到乾燥或繃緊。"},{"en":"This phrase is common in health and skincare discussions.","zh":"這個短語常見於健康和護膚討論。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":9},{"front":"different ways to filter water","meaning":"不同濾水方法","examples":[{"en":"There are many different ways to filter water.","zh":"有許多不同濾水方法。"},{"en":"Different ways to filter water means different methods for removing unwanted substances from water.","zh":"different ways to filter water 指去除水中不需要物質的不同方法。"},{"en":"A family may use a jug filter, a tap filter, or a larger home system.","zh":"家庭可能使用濾水壺、水龍頭濾器或大型家用系統。"},{"en":"Different methods matter because not all filters remove the same contaminants.","zh":"不同方法很重要，因為不是所有濾水器都去除同一類污染物。"},{"en":"This phrase introduces choices in water treatment.","zh":"這個短語引出水處理方面的選擇。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":9},{"front":"each type of filter","meaning":"每種濾水器","examples":[{"en":"Each type of filter targets different contaminants.","zh":"每種濾水器針對不同污染物。"},{"en":"Each type of filter means every kind of filtering device or method.","zh":"each type of filter 指每一種濾水裝置或方法。"},{"en":"One type of filter may remove chlorine, while another may target germs.","zh":"一種濾水器可能去除氯，另一種可能針對病菌。"},{"en":"Choosing the wrong filter may leave the main problem untreated.","zh":"選錯濾水器可能令主要問題仍未處理。"},{"en":"This phrase is useful when comparing filter options.","zh":"比較濾水選項時，這個短語很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":9},{"front":"target different contaminants","meaning":"針對不同污染物","examples":[{"en":"Different filters target different contaminants.","zh":"不同濾水器針對不同污染物。"},{"en":"To target different contaminants means to be designed to remove different unwanted substances.","zh":"target different contaminants 指被設計來去除不同不需要物質。"},{"en":"A filter for chlorine may not be the best filter for bacteria.","zh":"針對氯的濾水器未必最適合處理細菌。"},{"en":"Knowing the target contaminant helps consumers choose the correct product.","zh":"知道目標污染物有助消費者選擇正確產品。"},{"en":"This phrase links a tool with the specific problem it is meant to solve.","zh":"這個短語把工具與它要解決的具體問題連接起來。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":9},{"front":"activated carbon water filters","meaning":"活性碳濾水器","examples":[{"en":"Activated carbon water filters are good at removing chlorine.","zh":"活性碳濾水器擅長去除氯。"},{"en":"Activated carbon water filters use treated carbon to absorb or reduce certain substances in water.","zh":"activated carbon water filters 指使用經處理碳來吸附或減少水中某些物質的濾水器。"},{"en":"A household jug may contain an activated carbon filter.","zh":"家用濾水壺可能含有活性碳濾芯。"},{"en":"These filters are often chosen when people want to reduce taste or smell from chlorine.","zh":"當人們想減少氯帶來的味道或氣味，常會選擇這類濾水器。"},{"en":"This phrase names a specific type of water filter.","zh":"這個短語指一種特定濾水器。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":9},{"front":"be good at","meaning":"擅長；有效於","examples":[{"en":"Activated carbon water filters are good at taking chlorine out.","zh":"活性碳濾水器擅長去除氯。"},{"en":"To be good at something means to be effective or skilled at doing it.","zh":"be good at something 指在某事上有效或熟練。"},{"en":"A student may be good at remembering vocabulary through stories.","zh":"學生可能擅長透過故事記詞彙。"},{"en":"If a filter is good at removing one substance, it may still be weak at removing another.","zh":"如果濾水器擅長去除一種物質，它仍可能不擅長去除另一種。"},{"en":"This phrase describes strength or effectiveness.","zh":"這個短語描述能力或效果。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":10},{"front":"take chlorine out","meaning":"去除氯","examples":[{"en":"Activated carbon filters can take chlorine out of water.","zh":"活性碳濾水器可以去除水中的氯。"},{"en":"To take chlorine out means to remove chlorine from something.","zh":"take chlorine out 指把氯從某物中去除。"},{"en":"A filter may take chlorine out so the water tastes less chemical.","zh":"濾水器可能去除氯，使水的化學味較少。"},{"en":"Removing a substance can change smell, taste, or safety depending on the situation.","zh":"去除某種物質可以視情況改變氣味、味道或安全性。"},{"en":"This phrase is informal and clear.","zh":"這個短語較口語但清楚。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":10},{"front":"ozone water filters","meaning":"臭氧濾水器","examples":[{"en":"Ozone water filters are effective at removing germs.","zh":"臭氧濾水器有效去除病菌。"},{"en":"Ozone water filters use ozone to treat water and reduce microorganisms.","zh":"ozone water filters 指使用臭氧處理水並減少微生物的濾水器。"},{"en":"Some water-treatment systems use ozone instead of relying only on chlorine.","zh":"有些水處理系統使用臭氧，而不是只依賴氯。"},{"en":"A filter choice depends on what contaminant the user wants to reduce.","zh":"濾水器選擇取決於使用者想減少哪種污染物。"},{"en":"This phrase names a filter type linked with disinfection.","zh":"這個短語指一種與消毒有關的濾水器。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":10},{"front":"particularly effective at","meaning":"尤其有效於","examples":[{"en":"Ozone water filters are particularly effective at removing germs.","zh":"臭氧濾水器尤其有效於去除病菌。"},{"en":"Particularly effective at means especially good at doing a certain job.","zh":"particularly effective at 指在做某件事方面特別有效。"},{"en":"Flashcards are particularly effective at helping students review vocabulary quickly.","zh":"單詞卡尤其有效於幫助學生快速溫習詞彙。"},{"en":"If a tool is particularly effective at one task, people choose it for that specific purpose.","zh":"如果工具在某任務上尤其有效，人們會為該特定目的選擇它。"},{"en":"This phrase highlights a strong advantage.","zh":"這個短語突出強項。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":10},{"front":"removing germs","meaning":"去除病菌","examples":[{"en":"Ozone water filters are effective at removing germs.","zh":"臭氧濾水器有效去除病菌。"},{"en":"Removing germs means taking away or killing tiny organisms that may cause disease.","zh":"removing germs 指去除或殺死可能引致疾病的微小生物。"},{"en":"Washing hands with soap helps remove germs before eating.","zh":"飯前用肥皂洗手有助去除病菌。"},{"en":"Removing germs can lower the chance of infection.","zh":"去除病菌可以降低感染機會。"},{"en":"This phrase is common in hygiene and health contexts.","zh":"這個短語常見於衛生和健康語境。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":10},{"front":"for this reason","meaning":"因此","examples":[{"en":"For this reason, it is important to know what is in the water.","zh":"因此，知道水中含有甚麼很重要。"},{"en":"For this reason means because of the fact just mentioned.","zh":"for this reason 指因為剛才提到的事實。"},{"en":"The road is flooded; for this reason, the school bus will be delayed.","zh":"道路水浸；因此，校巴將會延誤。"},{"en":"This phrase connects a cause with a logical conclusion.","zh":"這個短語把原因與合理結論連接起來。"},{"en":"It is useful in explanations and essays.","zh":"它適合用於解釋和文章。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":10},{"front":"it is very important to","meaning":"……非常重要","examples":[{"en":"It is very important to know exactly what is in the water.","zh":"確切知道水中含有甚麼非常重要。"},{"en":"It is very important to means something is necessary or strongly worth doing.","zh":"it is very important to 指某事必要或非常值得做。"},{"en":"It is very important to read medicine labels before taking tablets.","zh":"服藥前閱讀藥物標籤非常重要。"},{"en":"Important actions often prevent mistakes, waste, or danger.","zh":"重要行動常能防止錯誤、浪費或危險。"},{"en":"This phrase emphasises priority.","zh":"這個短語強調優先性。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":10},{"front":"know exactly what is in","meaning":"確切知道……含有甚麼","examples":[{"en":"Consumers should know exactly what is in their drinking water.","zh":"消費者應確切知道自己的飲用水含有甚麼。"},{"en":"To know exactly what is in something means to understand its contents clearly.","zh":"know exactly what is in something 指清楚了解某物的成分。"},{"en":"People with allergies need to know exactly what is in packaged food.","zh":"有過敏的人需要確切知道包裝食物含有甚麼。"},{"en":"Clear information helps consumers make safer choices.","zh":"清楚資訊幫助消費者作出更安全選擇。"},{"en":"This phrase is useful when contents affect health or decisions.","zh":"當成分影響健康或決定時，這個短語很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":10},{"front":"so that","meaning":"以便","examples":[{"en":"We need to know the contaminants so that we can choose the right filter.","zh":"我們需要知道污染物，以便選擇合適濾水器。"},{"en":"So that means in order that or for the purpose of making something possible.","zh":"so that 指為了使某事成為可能。"},{"en":"Students should save their work often so that they do not lose it.","zh":"學生應經常儲存功課，以免遺失。"},{"en":"This phrase links an action with its purpose.","zh":"這個短語把行動與目的連接起來。"},{"en":"It is useful when explaining why something is done.","zh":"解釋為何做某事時，它很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":10},{"front":"decide what type of","meaning":"決定哪一種……","examples":[{"en":"Consumers can decide what type of water filter to use.","zh":"消費者可以決定使用哪一種濾水器。"},{"en":"To decide what type of something means to choose which kind is suitable.","zh":"decide what type of something 指選擇哪一種類合適。"},{"en":"A family may decide what type of school best fits a child’s needs.","zh":"家庭可能決定哪一種學校最符合孩子需要。"},{"en":"Better information makes it easier to choose the right type.","zh":"更好的資訊令人更容易選擇合適類型。"},{"en":"This phrase is useful when comparing options.","zh":"比較選項時，這個短語很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":10},{"front":"water filter","meaning":"濾水器","examples":[{"en":"A water filter can remove specific contaminants.","zh":"濾水器可以去除特定污染物。"},{"en":"A water filter is a device used to reduce or remove unwanted substances from water.","zh":"water filter 指用來減少或去除水中不需要物質的裝置。"},{"en":"A kitchen may have a water filter attached to the tap.","zh":"廚房可能有接在水龍頭上的濾水器。"},{"en":"If the filter is not changed, it may become less effective.","zh":"如果濾芯沒有更換，濾水器可能變得較不有效。"},{"en":"This phrase names a common household water-treatment tool.","zh":"這個短語指常見家用水處理工具。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":10},{"front":"Consumer Confidence Report","meaning":"消費者信心報告","examples":[{"en":"A Consumer Confidence Report lists contaminants in the water supply.","zh":"消費者信心報告列出供水中的污染物。"},{"en":"A Consumer Confidence Report is a report that gives consumers information about water quality.","zh":"Consumer Confidence Report 指向消費者提供水質資訊的報告。"},{"en":"Residents may read a Consumer Confidence Report before choosing a filter.","zh":"居民可能在選擇濾水器前閱讀消費者信心報告。"},{"en":"The report can help people understand what substances are present in their water.","zh":"該報告可以幫助人們了解水中存在甚麼物質。"},{"en":"This phrase names a specific type of public water-quality document.","zh":"這個短語指一種特定公共水質文件。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":11},{"front":"be useful for this purpose","meaning":"對此目的有用","examples":[{"en":"A Consumer Confidence Report should be useful for this purpose.","zh":"消費者信心報告應對此目的有用。"},{"en":"To be useful for this purpose means to help achieve the goal just mentioned.","zh":"be useful for this purpose 指有助達成剛才提到的目標。"},{"en":"A checklist is useful for this purpose if the goal is to avoid forgetting items.","zh":"如果目標是避免忘記事項，清單就對此目的有用。"},{"en":"Useful information makes decisions easier and more accurate.","zh":"有用資訊令決定更容易和更準確。"},{"en":"This phrase connects a tool with a specific aim.","zh":"這個短語把工具與特定目的連接起來。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":11},{"front":"be issued by","meaning":"由……發出","examples":[{"en":"The report is issued by public water suppliers every year.","zh":"該報告每年由公共供水商發出。"},{"en":"To be issued by someone means to be officially provided or released by them.","zh":"be issued by someone 指由某人或機構正式提供或發布。"},{"en":"Exam results may be issued by the school office.","zh":"考試成績可能由學校辦公室發出。"},{"en":"Officially issued reports help people know where information comes from.","zh":"正式發出的報告幫助人們知道資訊來源。"},{"en":"This phrase is common in formal documents and public notices.","zh":"這個短語常見於正式文件和公共通知。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":11},{"front":"public water suppliers","meaning":"公共供水商","examples":[{"en":"Public water suppliers issue Consumer Confidence Reports.","zh":"公共供水商發出消費者信心報告。"},{"en":"Public water suppliers are organisations that provide water to homes and communities.","zh":"public water suppliers 指向家庭和社區提供食水的機構。"},{"en":"Residents may contact public water suppliers if tap water becomes cloudy.","zh":"如果自來水變得混濁，居民可能聯絡公共供水商。"},{"en":"Water suppliers are responsible for monitoring and reporting water quality.","zh":"供水商負責監測和報告水質。"},{"en":"This phrase refers to the organisations behind public water service.","zh":"這個短語指公共供水服務背後的機構。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":11},{"front":"every year","meaning":"每年","examples":[{"en":"Public water suppliers issue the report every year.","zh":"公共供水商每年發出該報告。"},{"en":"Every year means once each year or annually.","zh":"every year 指每一年一次。"},{"en":"Schools review safety rules every year before classes begin.","zh":"學校每年開課前檢視安全規則。"},{"en":"Regular yearly reports help people track changes over time.","zh":"定期年度報告幫助人們追蹤隨時間的變化。"},{"en":"This phrase describes repeated annual action.","zh":"這個短語描述每年重複的行動。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":11},{"front":"listing the contaminants present","meaning":"列出存在的污染物","examples":[{"en":"The report lists the contaminants present in the water.","zh":"該報告列出水中存在的污染物。"},{"en":"Listing the contaminants present means naming the substances currently found there.","zh":"listing the contaminants present 指列明目前在其中發現的物質。"},{"en":"A food label lists ingredients present in a packaged meal.","zh":"食物標籤列出包裝餐點中存在的成分。"},{"en":"When contaminants are listed, consumers can decide what action to take.","zh":"當污染物被列出，消費者可以決定採取甚麼行動。"},{"en":"This phrase connects reporting with informed choice.","zh":"這個短語把報告與知情選擇連接起來。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":11},{"front":"present in the water","meaning":"存在於水中的","examples":[{"en":"The report identifies contaminants present in the water.","zh":"該報告識別存在於水中的污染物。"},{"en":"Present in the water means existing or found in the water.","zh":"present in the water 指存在或被發現在水中。"},{"en":"A test can show whether bacteria are present in the water.","zh":"測試可以顯示水中是否存在細菌。"},{"en":"If a harmful substance is present, the correct treatment can be chosen.","zh":"如果有害物質存在，就可以選擇合適處理方法。"},{"en":"This phrase describes what is actually there.","zh":"這個短語描述實際存在的東西。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":11},{"front":"it is easier to decide","meaning":"較容易決定","examples":[{"en":"If consumers know the contaminants, it is easier to decide which filter to get.","zh":"如果消費者知道污染物，就較容易決定買哪種濾水器。"},{"en":"It is easier to decide means the choice becomes less confusing.","zh":"it is easier to decide 指選擇變得較不混亂。"},{"en":"It is easier to decide what to study when students know their goals.","zh":"當學生知道自己的目標，就較容易決定讀甚麼。"},{"en":"Clear information reduces guessing and poor choices.","zh":"清楚資訊減少猜測和差劣選擇。"},{"en":"This phrase links knowledge with better decision-making.","zh":"這個短語把知識與更好決策連接起來。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":11},{"front":"which type of water filter to get","meaning":"應選購哪種濾水器","examples":[{"en":"The report helps consumers decide which type of water filter to get.","zh":"該報告幫助消費者決定應選購哪種濾水器。"},{"en":"Which type of water filter to get means which kind of filter a person should buy or use.","zh":"which type of water filter to get 指一個人應購買或使用哪一種濾水器。"},{"en":"A customer may ask a shop assistant which type of water filter to get for chlorine taste.","zh":"顧客可能問店員應選購哪種濾水器來處理氯味。"},{"en":"The right choice depends on the contaminants present in the water.","zh":"正確選擇取決於水中存在的污染物。"},{"en":"This phrase is practical and purchase-focused.","zh":"這個短語很實用，聚焦購買選擇。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":11},{"front":"the text has seven paragraphs","meaning":"文章有七段","examples":[{"en":"The text has seven paragraphs about drinking filtered water.","zh":"這篇關於飲用過濾水的文章有七段。"},{"en":"The text has seven paragraphs means the reading passage is divided into seven sections.","zh":"the text has seven paragraphs 指閱讀篇章分成七個部分。"},{"en":"Students may number the paragraphs before answering location questions.","zh":"學生可能在回答定位題前先為段落編號。"},{"en":"Knowing the number of paragraphs helps students scan the passage more efficiently.","zh":"知道段落數目有助學生更有效掃讀文章。"},{"en":"This phrase is common in reading-test instructions.","zh":"這個短語常見於閱讀測驗指示。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":11},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"Students must decide which paragraph contains the information.","zh":"學生必須判斷哪一段包含該資料。"},{"en":"Which paragraph contains asks students to find where a detail appears in the passage.","zh":"which paragraph contains 指要求學生找出細節出現在篇章哪一段。"},{"en":"In IELTS reading, students scan for the paragraph that contains a specific idea.","zh":"在 IELTS 閱讀中，學生掃讀尋找包含特定想法的段落。"},{"en":"A paragraph may use different words from the question but still contain the same meaning.","zh":"段落可能使用與題目不同的字眼，但仍包含相同意思。"},{"en":"This phrase is common in information-location tasks.","zh":"這個短語常見於資料定位題。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":11},{"front":"the following information","meaning":"以下資料","examples":[{"en":"The exercise asks students to find the following information.","zh":"練習要求學生找出以下資料。"},{"en":"The following information means the details listed after the instruction.","zh":"following information 指指示後列出的細節。"},{"en":"Students should read the following information carefully before scanning the passage.","zh":"學生在掃讀文章前應仔細閱讀以下資料。"},{"en":"Understanding exactly what to find prevents careless matching.","zh":"準確理解要找甚麼，可以避免粗心配對。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":12},{"front":"write the correct letter","meaning":"寫下正確字母","examples":[{"en":"Students write the correct letter next to each question.","zh":"學生在每條題目旁邊寫下正確字母。"},{"en":"To write the correct letter means to record the paragraph or option letter that matches the answer.","zh":"write the correct letter 指寫下與答案相符的段落或選項字母。"},{"en":"If paragraph C contains the information, students write C.","zh":"如果 C 段包含該資料，學生就寫 C。"},{"en":"Correct meaning can still lose marks if the wrong letter is written.","zh":"即使意思理解正確，寫錯字母仍可能失分。"},{"en":"This phrase reminds students to follow answer format.","zh":"這個短語提醒學生跟從答案格式。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":12},{"front":"next to questions","meaning":"在題目旁邊","examples":[{"en":"Students write the paragraph letter next to the questions.","zh":"學生在題目旁邊寫下段落字母。"},{"en":"Next to questions means beside the questions on the answer page or worksheet.","zh":"next to questions 指在答案頁或工作紙上的題目旁邊。"},{"en":"A teacher may ask students to write vocabulary meanings next to questions in a worksheet.","zh":"老師可能要求學生在工作紙題目旁邊寫下詞義。"},{"en":"Putting answers next to questions makes checking easier.","zh":"把答案寫在題目旁邊令檢查更容易。"},{"en":"This phrase describes where to place an answer.","zh":"這個短語描述答案放置位置。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":12},{"front":"a short summary of","meaning":"……的簡短摘要","examples":[{"en":"The first paragraph gives a short summary of the main points.","zh":"第一段給出文章重點的簡短摘要。"},{"en":"A short summary of something is a brief version of its main ideas.","zh":"short summary of something 指某事主要意思的簡短版本。"},{"en":"Students may write a short summary of an article after reading it.","zh":"學生讀完文章後可能寫一段簡短摘要。"},{"en":"Summaries help readers understand the big picture before details.","zh":"摘要幫助讀者在細節前理解大方向。"},{"en":"This phrase is useful in reading and writing tasks.","zh":"這個短語適用於閱讀和寫作任務。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":12},{"front":"the main points of the text","meaning":"文章重點","examples":[{"en":"The question asks about the main points of the text.","zh":"題目問文章重點。"},{"en":"The main points of the text are the most important ideas in the passage.","zh":"main points of the text 指篇章中最重要的想法。"},{"en":"A teacher may ask students to underline the main points before writing a summary.","zh":"老師可能要求學生在寫摘要前劃出文章重點。"},{"en":"Focusing on main points prevents students from getting lost in small details.","zh":"聚焦重點可以防止學生迷失於小細節。"},{"en":"This phrase is common in comprehension and summary questions.","zh":"這個短語常見於理解題和摘要題。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":12},{"front":"a variety of methods","meaning":"多種方法","examples":[{"en":"The passage mentions a variety of methods used for water filtration.","zh":"文章提到多種用於濾水的方法。"},{"en":"A variety of methods means several different ways to do something.","zh":"variety of methods 指做某事的幾種不同方式。"},{"en":"Teachers use a variety of methods, such as games, reading, and discussion.","zh":"老師使用多種方法，例如遊戲、閱讀和討論。"},{"en":"Different methods may work better for different problems.","zh":"不同方法可能更適合不同問題。"},{"en":"This phrase emphasises choice and diversity.","zh":"這個短語強調選擇和多樣性。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":12},{"front":"water filtration","meaning":"水過濾；濾水","examples":[{"en":"Different filters are used for water filtration.","zh":"不同濾水器被用於水過濾。"},{"en":"Water filtration is the process of passing water through a filter to remove unwanted substances.","zh":"water filtration 指讓水通過濾器以去除不需要物質的過程。"},{"en":"A café may use water filtration to improve the taste of coffee.","zh":"咖啡店可能使用濾水來改善咖啡味道。"},{"en":"Filtration can target particles, chemicals, or germs depending on the system.","zh":"過濾可以視系統而針對微粒、化學物質或病菌。"},{"en":"This phrase is common in water treatment.","zh":"這個短語常見於水處理。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":12},{"front":"make it easier for","meaning":"令……更容易","examples":[{"en":"Pure water can make it easier for the body to remove toxins.","zh":"純淨水可以令身體更容易清除毒素。"},{"en":"To make it easier for someone or something means to reduce difficulty for them.","zh":"make it easier for someone or something 指降低某人或某物做事的難度。"},{"en":"Clear notes make it easier for students to revise before exams.","zh":"清楚筆記令學生考試前更容易溫習。"},{"en":"When a process becomes easier, less effort may be needed.","zh":"當一個過程變得更容易，可能需要較少努力。"},{"en":"This phrase connects support with reduced difficulty.","zh":"這個短語把支援與降低難度連接起來。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":12},{"front":"get rid of dangerous chemicals","meaning":"清除有害化學物質","examples":[{"en":"Filtered water may help the body get rid of dangerous chemicals.","zh":"過濾水可能幫助身體清除有害化學物質。"},{"en":"To get rid of dangerous chemicals means to remove harmful substances.","zh":"get rid of dangerous chemicals 指去除有害物質。"},{"en":"A school lab must get rid of dangerous chemicals through proper waste disposal.","zh":"學校實驗室必須透過適當廢物棄置清除有害化學物質。"},{"en":"Removing harmful chemicals can reduce risk to people and the environment.","zh":"去除有害化學物質可以降低對人和環境的風險。"},{"en":"This phrase is practical and often used in health or safety contexts.","zh":"這個短語很實用，常用於健康或安全語境。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":12},{"front":"find out which contaminants","meaning":"找出哪些污染物","examples":[{"en":"Consumers should find out which contaminants their water contains.","zh":"消費者應找出自己的水含有哪些污染物。"},{"en":"To find out which contaminants means to discover what unwanted substances are present.","zh":"find out which contaminants 指查明有哪些不需要物質存在。"},{"en":"A homeowner may test water to find out which contaminants are in it.","zh":"屋主可能檢測食水，以找出其中有哪些污染物。"},{"en":"Knowing the exact contaminants helps people choose the right solution.","zh":"知道確切污染物有助人們選擇正確解決方法。"},{"en":"This phrase describes investigation before action.","zh":"這個短語描述行動前的調查。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":12},{"front":"your water filter should target","meaning":"你的濾水器應針對的","examples":[{"en":"Consumers need to know which contaminants their water filter should target.","zh":"消費者需要知道他們的濾水器應針對哪些污染物。"},{"en":"Your water filter should target means the filter should be chosen to deal with specific substances.","zh":"your water filter should target 指濾水器應被選來處理特定物質。"},{"en":"If chlorine is the problem, your water filter should target chlorine taste and smell.","zh":"如果問題是氯，你的濾水器應針對氯味和氣味。"},{"en":"A filter that targets the wrong issue may not improve the water in the way you need.","zh":"針對錯誤問題的濾水器，可能不能按你的需要改善水質。"},{"en":"This phrase connects a product choice with a specific problem.","zh":"這個短語把產品選擇與具體問題連接起來。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":12},{"front":"dangerous metals","meaning":"危險金屬","examples":[{"en":"Mercury and lead are examples of dangerous metals.","zh":"水銀和鉛是危險金屬的例子。"},{"en":"Dangerous metals are metals that can harm health if people are exposed to unsafe amounts.","zh":"dangerous metals 指人在接觸不安全分量時可能危害健康的金屬。"},{"en":"Old buildings may need testing for dangerous metals in pipes or paint.","zh":"舊建築物可能需要檢查水管或油漆中是否有危險金屬。"},{"en":"If dangerous metals enter water, proper treatment or replacement may be needed.","zh":"如果危險金屬進入水中，可能需要適當處理或更換設備。"},{"en":"This phrase is common in pollution and health-risk discussions.","zh":"這個短語常見於污染和健康風險討論。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":13},{"front":"found in the plumbing of old buildings","meaning":"在舊建築物的水管系統中發現","examples":[{"en":"Lead may be found in the plumbing of old buildings.","zh":"鉛可能在舊建築物的水管系統中被發現。"},{"en":"Found in the plumbing of old buildings means discovered in the pipe systems of older properties.","zh":"found in the plumbing of old buildings 指在舊物業的水管系統中發現。"},{"en":"A flat buyer may inspect the plumbing of an old building before moving in.","zh":"買樓人士搬入前可能檢查舊建築物的水管系統。"},{"en":"Old plumbing can affect water quality if outdated materials are still present.","zh":"如果舊水管仍有過時材料，可能影響水質。"},{"en":"This phrase links a contaminant with building infrastructure.","zh":"這個短語把污染物與建築基建連接起來。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":13},{"front":"plumbing","meaning":"水管系統","examples":[{"en":"Old plumbing may contain lead pipes.","zh":"舊水管系統可能含有鉛管。"},{"en":"Plumbing is the system of pipes, taps, and fittings that carry water in a building.","zh":"plumbing 指建築物中輸送水的水管、水龍頭和配件系統。"},{"en":"A plumber repairs plumbing when a bathroom pipe leaks.","zh":"浴室水管滲漏時，水喉師傅會維修水管系統。"},{"en":"Poor plumbing can cause leaks, low water pressure, or water-quality concerns.","zh":"水管系統差可以造成滲漏、水壓低或水質問題。"},{"en":"This word is common in housing and building maintenance.","zh":"這個詞常見於房屋和建築維修。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":13},{"front":"chemicals used to clean water","meaning":"用作淨化水的化學物質","examples":[{"en":"Chlorine and bromine are chemicals used to clean water.","zh":"氯和溴是用作淨化水的化學物質。"},{"en":"Chemicals used to clean water are substances added or applied to reduce germs or impurities.","zh":"chemicals used to clean water 指加入或使用來減少病菌或雜質的物質。"},{"en":"Swimming pools often use chemicals to keep water clean.","zh":"游泳池常使用化學物質保持水清潔。"},{"en":"Cleaning chemicals may improve hygiene, but their amount and use must be controlled.","zh":"清潔化學物質可以改善衛生，但其用量和使用方式必須受控制。"},{"en":"This phrase explains the purpose of disinfectant chemicals.","zh":"這個短語解釋消毒化學物質的目的。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":13},{"front":"by destroying bacteria","meaning":"透過殺滅細菌","examples":[{"en":"Disinfectant chemicals clean water by destroying bacteria.","zh":"消毒化學物質透過殺滅細菌來淨化水。"},{"en":"By destroying bacteria means through killing or breaking down harmful bacteria.","zh":"by destroying bacteria 指透過殺死或破壞有害細菌。"},{"en":"Soap helps clean hands by removing and reducing germs.","zh":"肥皂透過去除和減少病菌來清潔雙手。"},{"en":"Killing bacteria can lower the chance that water spreads disease.","zh":"殺滅細菌可以降低水傳播疾病的機會。"},{"en":"This phrase explains the method used to clean water.","zh":"這個短語解釋淨化水所用方法。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":13},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"Students decide whether the following statements agree with the information in the text.","zh":"學生判斷以下陳述是否與文章資料一致。"},{"en":"Do the following statements agree with asks whether each statement matches the source information.","zh":"do the following statements agree with 指詢問每個陳述是否與來源資料相符。"},{"en":"In reading exams, students must check the text before writing TRUE or FALSE.","zh":"在閱讀考試中，學生寫 TRUE 或 FALSE 前必須查看文章。"},{"en":"A statement can sound reasonable but still fail to agree with the text.","zh":"陳述可能聽起來合理，但仍未必與文章一致。"},{"en":"This phrase is common in TRUE, FALSE, NOT GIVEN tasks.","zh":"這個短語常見於 TRUE, FALSE, NOT GIVEN 題。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":13},{"front":"information given in the text","meaning":"文章所提供的資料","examples":[{"en":"The answers must match the information given in the text.","zh":"答案必須符合文章所提供的資料。"},{"en":"Information given in the text means facts or ideas stated or supported by the passage.","zh":"information given in the text 指篇章中陳述或支持的事實或想法。"},{"en":"Students should answer from the information given in the text, not from outside knowledge.","zh":"學生應根據文章所提供的資料作答，而不是外部知識。"},{"en":"If the text gives no information, the answer may be NOT GIVEN.","zh":"如果文章沒有提供資料，答案可能是 NOT GIVEN。"},{"en":"This phrase focuses on evidence inside the reading passage.","zh":"這個短語聚焦閱讀篇章內的證據。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":13},{"front":"if the statement agrees with","meaning":"如果陳述與……一致","examples":[{"en":"Students write TRUE if the statement agrees with the information.","zh":"如果陳述與資料一致，學生寫 TRUE。"},{"en":"If the statement agrees with means if the sentence matches what the text says.","zh":"if the statement agrees with 指如果句子與文章所說相符。"},{"en":"If a passage says water is filtered, a statement saying it is filtered agrees with the text.","zh":"如果篇章說水經過過濾，而陳述說它經過過濾，就與文章一致。"},{"en":"Students should compare meaning, not only identical words.","zh":"學生應比較意思，而不只是相同字眼。"},{"en":"This phrase is part of exam instructions.","zh":"這個短語是考試指示的一部分。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":13},{"front":"if the statement contradicts","meaning":"如果陳述與……矛盾","examples":[{"en":"Students write FALSE if the statement contradicts the information.","zh":"如果陳述與資料矛盾，學生寫 FALSE。"},{"en":"If the statement contradicts means if it says the opposite of the text.","zh":"if the statement contradicts 指如果它說出與文章相反的意思。"},{"en":"If the passage says a report is issued yearly, a statement saying it is never issued contradicts it.","zh":"如果文章說報告每年發出，而陳述說從不發出，就與文章矛盾。"},{"en":"Contradiction is different from missing information because it directly conflicts with the text.","zh":"矛盾不同於沒有資料，因為它直接與文本衝突。"},{"en":"This phrase helps students identify FALSE answers.","zh":"這個短語幫助學生辨認 FALSE 答案。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":13},{"front":"there is no information on this","meaning":"沒有這方面的資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有這方面的資料，學生寫 NOT GIVEN。"},{"en":"There is no information on this means the text does not say whether the statement is true or false.","zh":"there is no information on this 指文章沒有說明該陳述是真還是假。"},{"en":"If a passage discusses filters but not their price, there is no information on the price.","zh":"如果文章討論濾水器但沒有討論價格，就沒有價格方面的資料。"},{"en":"Students should not guess when the passage gives no evidence.","zh":"當篇章沒有證據，學生不應猜測。"},{"en":"This phrase is essential for NOT GIVEN questions.","zh":"這個短語對 NOT GIVEN 題很重要。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":13},{"front":"on a regular basis","meaning":"定期地；經常地","examples":[{"en":"The type of water you drink on a regular basis can affect your health.","zh":"你定期飲用的水類型可能影響健康。"},{"en":"On a regular basis means repeatedly or routinely.","zh":"on a regular basis 指反覆地或按日常習慣地。"},{"en":"Students who read on a regular basis usually build vocabulary faster.","zh":"定期閱讀的學生通常更快建立詞彙。"},{"en":"Habits done regularly can have stronger effects than occasional actions.","zh":"定期做的習慣可以比偶爾行動有更強影響。"},{"en":"This phrase is more formal than “often”.","zh":"這個短語比 often 更正式。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":13},{"front":"have a great impact on","meaning":"對……有很大影響","examples":[{"en":"Drinking water quality can have a great impact on health.","zh":"飲用水質可以對健康有很大影響。"},{"en":"To have a great impact on something means to affect it strongly.","zh":"have a great impact on something 指強烈影響某事。"},{"en":"A good teacher can have a great impact on a student’s confidence.","zh":"好老師可以對學生信心有很大影響。"},{"en":"Strong impacts can change behaviour, results, or long-term well-being.","zh":"強烈影響可以改變行為、結果或長遠福祉。"},{"en":"This phrase is useful when the effect is large.","zh":"當影響很大時，這個短語很有用。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":14},{"front":"overall health and well-being","meaning":"整體健康和身心安康","examples":[{"en":"Clean drinking water is important for overall health and well-being.","zh":"清潔飲用水對整體健康和身心安康很重要。"},{"en":"Overall health and well-being means general physical and mental wellness.","zh":"overall health and well-being 指整體身體和心理健康。"},{"en":"Sleep, exercise, food, and clean water all support overall health and well-being.","zh":"睡眠、運動、食物和清潔食水都支持整體健康和身心安康。"},{"en":"If one basic need is poor, the whole person may be affected.","zh":"如果一項基本需要很差，整個人都可能受影響。"},{"en":"This phrase is broader than simply “not being sick”.","zh":"這個短語比單純「沒有生病」更廣。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":14},{"front":"typically contains","meaning":"通常含有","examples":[{"en":"The statement asks whether filtered water typically contains disinfectant chemicals.","zh":"這個陳述問過濾水是否通常含有消毒化學物質。"},{"en":"Typically contains means usually has something inside it.","zh":"typically contains 指通常內含某物。"},{"en":"A school lunch typically contains vegetables, rice, and protein.","zh":"學校午餐通常含有蔬菜、米飯和蛋白質。"},{"en":"If something typically contains an ingredient, people expect to find it most of the time.","zh":"如果某物通常含有某成分，人們預期大多數時候會找到它。"},{"en":"This phrase describes a usual pattern, not every single case.","zh":"這個短語描述一般模式，不是每一個個案。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":14},{"front":"exposure to","meaning":"接觸；暴露於","examples":[{"en":"Exposure to disinfectant chemicals may be linked with health risks.","zh":"接觸消毒化學物質可能與健康風險有關。"},{"en":"Exposure to something means contact with it or being affected by it.","zh":"exposure to something 指接觸某物或受其影響。"},{"en":"Exposure to sunlight can be healthy in small amounts but harmful if excessive.","zh":"少量接觸陽光可以健康，但過量則有害。"},{"en":"Repeated exposure may increase concern if the substance is harmful.","zh":"如果某物質有害，反覆接觸可能增加擔憂。"},{"en":"This phrase is common in health and environmental writing.","zh":"這個短語常見於健康和環境寫作。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":14},{"front":"be linked with","meaning":"與……有關","examples":[{"en":"Exposure to some chemicals is linked with health problems.","zh":"接觸某些化學物質與健康問題有關。"},{"en":"To be linked with something means to be connected with it.","zh":"be linked with something 指與某事有連繫。"},{"en":"Poor sleep is often linked with low concentration in class.","zh":"睡眠不足常與課堂專注力低有關。"},{"en":"A link may suggest a relationship, though it may need more evidence.","zh":"關聯可能暗示兩者有關係，但可能需要更多證據。"},{"en":"This phrase is common in research and health topics.","zh":"這個短語常見於研究和健康主題。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":14},{"front":"poisoning of the vital organs","meaning":"重要器官中毒","examples":[{"en":"The statement refers to poisoning of the vital organs.","zh":"這個陳述提到重要器官中毒。"},{"en":"Poisoning of the vital organs means toxic damage to essential body parts such as the brain, heart, liver, or kidneys.","zh":"poisoning of the vital organs 指毒性物質對大腦、心臟、肝臟或腎臟等重要器官造成損害。"},{"en":"Doctors take poisoning seriously because vital organs control life-supporting functions.","zh":"醫生嚴肅看待中毒，因為重要器官控制維持生命的功能。"},{"en":"If vital organs are poisoned, the whole body may be in danger.","zh":"如果重要器官中毒，整個身體可能有危險。"},{"en":"This phrase describes a severe health condition.","zh":"這個短語描述嚴重健康狀況。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":14},{"front":"minimise your exposure to","meaning":"盡量減少接觸……","examples":[{"en":"Filtered water may minimise your exposure to harmful elements.","zh":"過濾水可能盡量減少你接觸有害元素。"},{"en":"To minimise your exposure to something means to reduce how much contact you have with it.","zh":"minimise your exposure to something 指減少你與某物接觸的程度。"},{"en":"Wearing gloves can minimise your exposure to strong cleaning chemicals.","zh":"戴手套可以盡量減少接觸強力清潔化學品。"},{"en":"Reducing exposure is important when complete avoidance is difficult.","zh":"當完全避免很困難，減少接觸就很重要。"},{"en":"This phrase is common in safety advice.","zh":"這個短語常見於安全建議。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":14},{"front":"harmful elements","meaning":"有害元素","examples":[{"en":"The question refers to harmful elements in drinking water.","zh":"題目提到飲用水中的有害元素。"},{"en":"Harmful elements are substances or materials that may damage health or safety.","zh":"harmful elements 指可能損害健康或安全的物質或材料。"},{"en":"A safety report may identify harmful elements in old paint or soil.","zh":"安全報告可能識別舊油漆或土壤中的有害元素。"},{"en":"If harmful elements are found, people may need treatment, removal, or protection.","zh":"如果發現有害元素，人們可能需要處理、移除或保護措施。"},{"en":"This phrase is broad and often used in environmental health.","zh":"這個短語較廣，常用於環境健康。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":14},{"front":"people who wear dentures","meaning":"戴假牙的人","examples":[{"en":"The statement mentions people who wear dentures.","zh":"這個陳述提到戴假牙的人。"},{"en":"People who wear dentures are people who use artificial teeth to replace missing teeth.","zh":"people who wear dentures 指使用人工牙齒取代缺失牙齒的人。"},{"en":"Older adults may wear dentures so they can eat and speak more comfortably.","zh":"長者可能戴假牙，以便更舒適地進食和說話。"},{"en":"Dentures need cleaning because they are used inside the mouth every day.","zh":"假牙需要清潔，因為它們每天在口腔內使用。"},{"en":"This phrase identifies a specific group of people by a dental device they use.","zh":"這個短語以他們使用的牙科裝置識別特定群體。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":14},{"front":"be more likely to be exposed to","meaning":"較有可能接觸到……","examples":[{"en":"Some groups may be more likely to be exposed to contaminants.","zh":"有些群體可能較有可能接觸到污染物。"},{"en":"To be more likely to be exposed to something means to have a higher chance of coming into contact with it.","zh":"be more likely to be exposed to something 指接觸某物的機會較高。"},{"en":"Workers in a factory may be more likely to be exposed to chemicals than office staff.","zh":"工廠工人可能比辦公室員工較有可能接觸到化學品。"},{"en":"Higher exposure risk often means stronger safety measures are needed.","zh":"較高接觸風險通常表示需要更強安全措施。"},{"en":"This phrase compares risk between groups.","zh":"這個短語比較不同群體之間的風險。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":14},{"front":"suffer from dehydration","meaning":"患有脫水；受脫水影響","examples":[{"en":"The statement asks whether depressed people often suffer from dehydration.","zh":"這個陳述問抑鬱症患者是否經常受脫水影響。"},{"en":"To suffer from dehydration means to be affected by not having enough water in the body.","zh":"suffer from dehydration 指因身體水分不足而受影響。"},{"en":"A runner may suffer from dehydration after exercising in hot weather without drinking enough.","zh":"跑步者在炎熱天氣運動而飲水不足後，可能脫水。"},{"en":"Dehydration can cause thirst, dizziness, tiredness, or confusion.","zh":"脫水可以造成口渴、頭暈、疲倦或混亂。"},{"en":"This phrase describes a health problem caused by fluid loss or low fluid intake.","zh":"這個短語描述由水分流失或攝取不足造成的健康問題。"}],"source":"65 - DRINKING FILTERED WATER.pdf","sourcePage":14}],"ielts/reading/passage-2/Practice 66":[{"front":"Salvador Dalí","meaning":"薩爾瓦多・達利","examples":[{"en":"Salvador Dalí is one of the most famous figures associated with Surrealism.","zh":"薩爾瓦多・達利是與超現實主義有關的最著名人物之一。"},{"en":"Salvador Dalí was a Spanish artist known for strange dream-like paintings and an eccentric public image.","zh":"薩爾瓦多・達利是一位西班牙藝術家，以奇異如夢的畫作和古怪的公眾形象聞名。"},{"en":"Art students often study Salvador Dalí when learning about Surrealism and symbolic imagery.","zh":"藝術學生學習超現實主義和象徵意象時，常會研究薩爾瓦多・達利。"},{"en":"If a museum exhibits Salvador Dalí’s work, visitors may expect unusual scenes, melting objects, and hidden meanings.","zh":"如果博物館展出薩爾瓦多・達利的作品，參觀者可能會期待奇特場景、融化物件和隱藏意思。"},{"en":"The name Salvador Dalí is often linked with imagination, self-promotion, and unforgettable images.","zh":"薩爾瓦多・達利這個名字常與想像力、自我宣傳和令人難忘的形象連在一起。"}],"source":"66 - Salvador Dali.pdf","sourcePage":1},{"front":"a passing knowledge of","meaning":"對……有粗略認識","examples":[{"en":"Almost everyone with even a passing knowledge of the art world has heard of Dalí.","zh":"幾乎每個對藝術界有粗略認識的人都聽說過達利。"},{"en":"A passing knowledge of something means a basic or rough understanding of it.","zh":"a passing knowledge of 指對某事有基本或粗略理解。"},{"en":"A student with a passing knowledge of French may understand simple signs but not a long conversation.","zh":"對法文有粗略認識的學生可能看得懂簡單標誌，但不懂長對話。"},{"en":"If someone has only a passing knowledge of art, they may know famous names but not detailed history.","zh":"如果某人只對藝術有粗略認識，可能知道著名名字，但不了解詳細歷史。"},{"en":"The phrase suggests limited familiarity, not expert knowledge.","zh":"這個片語暗示有限熟悉，而不是專家知識。"}],"source":"66 - Salvador Dali.pdf","sourcePage":1},{"front":"the art world","meaning":"藝術界","examples":[{"en":"Dalí is widely known in the art world.","zh":"達利在藝術界廣為人知。"},{"en":"The art world means the community of artists, galleries, critics, museums, collectors, and viewers connected with art.","zh":"the art world 指與藝術有關的藝術家、畫廊、評論家、博物館、收藏家和觀眾群體。"},{"en":"A young painter may enter the art world by joining exhibitions and meeting curators.","zh":"年輕畫家可能透過參加展覽和認識策展人進入藝術界。"},{"en":"If someone becomes famous in the art world, their work may be discussed by critics and museums.","zh":"如果某人在藝術界成名，其作品可能被評論家和博物館討論。"},{"en":"The phrase refers to the social and professional world surrounding art.","zh":"這個片語指圍繞藝術的社會和專業世界。"}],"source":"66 - Salvador Dali.pdf","sourcePage":1},{"front":"have heard of","meaning":"聽說過","examples":[{"en":"Most people interested in art have heard of Salvador Dalí.","zh":"大多數對藝術感興趣的人都聽說過薩爾瓦多・達利。"},{"en":"Have heard of means know that someone or something exists, even if you do not know much detail.","zh":"have heard of 指知道某人或某事存在，即使不了解太多細節。"},{"en":"Many students have heard of Shakespeare, though they may not have read his plays.","zh":"許多學生聽說過莎士比亞，雖然未必讀過他的劇作。"},{"en":"If a name is famous enough, people may have heard of it without studying the subject deeply.","zh":"如果名字足夠有名，人們即使沒有深入研究該主題，也可能聽說過。"},{"en":"The phrase shows recognition, not full understanding.","zh":"這個片語表示認得，而不是完全理解。"}],"source":"66 - Salvador Dali.pdf","sourcePage":1},{"front":"eccentric","meaning":"古怪的；異於常人的","examples":[{"en":"Dalí was famous for his eccentric personality.","zh":"達利以其古怪性格聞名。"},{"en":"Eccentric means unusual in behaviour, style, or thinking, often in a memorable way.","zh":"eccentric 指在行為、風格或思想上不尋常，通常令人印象深刻。"},{"en":"An eccentric teacher may wear colourful suits and use strange objects to explain grammar.","zh":"古怪的老師可能穿鮮色西裝，並用奇怪物件解釋文法。"},{"en":"If someone is eccentric, people may find them interesting, amusing, or difficult to understand.","zh":"如果某人古怪，人們可能覺得他有趣、好笑或難以理解。"},{"en":"The word can be positive or negative depending on tone.","zh":"這個詞可正面也可負面，視乎語氣。"}],"source":"66 - Salvador Dali.pdf","sourcePage":1},{"front":"avant-garde","meaning":"前衛的","examples":[{"en":"Dalí was an avant-garde exponent of the Surrealist movement.","zh":"達利是超現實主義運動的前衛代表人物。"},{"en":"Avant-garde means experimental, modern, and ahead of mainstream artistic taste.","zh":"avant-garde 指實驗性、現代、走在主流藝術品味前面的。"},{"en":"An avant-garde film may confuse viewers because it breaks normal storytelling rules.","zh":"前衛電影可能因打破正常敘事規則而令觀眾困惑。"},{"en":"If an artist is avant-garde, critics may reject the work at first but later recognise its influence.","zh":"如果藝術家很前衛，評論家起初可能拒絕其作品，但後來承認其影響力。"},{"en":"The word is often used for art that challenges tradition.","zh":"這個詞常用於挑戰傳統的藝術。"}],"source":"66 - Salvador Dali.pdf","sourcePage":1},{"front":"exponent of","meaning":"……的代表人物；倡導者","examples":[{"en":"Dalí was an exponent of the Surrealist movement.","zh":"達利是超現實主義運動的代表人物。"},{"en":"An exponent of something is a person who represents, supports, or promotes an idea, style, or movement.","zh":"exponent of 指代表、支持或推動某理念、風格或運動的人。"},{"en":"A famous chef may become an exponent of healthy local cooking.","zh":"著名廚師可能成為健康本地烹飪的倡導者。"},{"en":"If someone is an exponent of a movement, people often connect that movement with their name.","zh":"如果某人是某運動的代表人物，人們常會把該運動與他的名字連在一起。"},{"en":"The phrase is formal and often used in art, politics, and ideas.","zh":"這個片語較正式，常用於藝術、政治和思想。"}],"source":"66 - Salvador Dali.pdf","sourcePage":1},{"front":"the Surrealist movement","meaning":"超現實主義運動","examples":[{"en":"Dalí became closely associated with the Surrealist movement.","zh":"達利與超現實主義運動變得密切相關。"},{"en":"The Surrealist movement was an artistic movement that explored dreams, the unconscious, and strange unexpected images.","zh":"the Surrealist movement 是探索夢境、潛意識和奇異意外形象的藝術運動。"},{"en":"Art students study the Surrealist movement to understand why ordinary objects appear in impossible situations.","zh":"藝術學生研究超現實主義運動，以理解為何普通物件會出現在不可能的情境中。"},{"en":"If an artist joined the Surrealist movement, their work might become more dream-like and symbolic.","zh":"如果藝術家加入超現實主義運動，其作品可能變得更如夢似幻且充滿象徵。"},{"en":"The phrase refers to a major twentieth-century art movement.","zh":"這個片語指二十世紀一個重要藝術運動。"}],"source":"66 - Salvador Dali.pdf","sourcePage":1},{"front":"Love him or loathe him","meaning":"無論喜歡他還是討厭他","examples":[{"en":"Love him or loathe him, Dalí remains impossible to ignore.","zh":"無論喜歡他還是討厭他，達利仍然令人無法忽視。"},{"en":"Love him or loathe him means whether people admire him or strongly dislike him.","zh":"Love him or loathe him 指無論人們欣賞他還是非常討厭他。"},{"en":"Love her or loathe her, a strict teacher may still change how students study.","zh":"無論喜歡她還是討厭她，嚴格老師仍可能改變學生學習方式。"},{"en":"If someone is impossible to ignore, strong dislike can still prove their influence.","zh":"如果某人令人無法忽視，強烈反感仍可證明其影響力。"},{"en":"The phrase introduces a person who divides opinion but still matters.","zh":"這個片語引出一個令人意見分歧但仍重要的人物。"}],"source":"66 - Salvador Dali.pdf","sourcePage":1},{"front":"achieve enduring worldwide fame","meaning":"獲得持久的世界聲譽","examples":[{"en":"Dalí’s work has achieved enduring worldwide fame.","zh":"達利的作品已獲得持久的世界聲譽。"},{"en":"Achieve enduring worldwide fame means become famous around the world for a very long time.","zh":"achieve enduring worldwide fame 指在世界各地長時間成名。"},{"en":"A singer may achieve enduring worldwide fame if songs remain popular across generations.","zh":"如果歌手的歌曲跨世代仍受歡迎，就可能獲得持久的世界聲譽。"},{"en":"If an image is recognised in many countries decades later, it has achieved lasting fame.","zh":"如果一個形象數十年後仍在許多國家被認出，它就獲得持久名聲。"},{"en":"The phrase combines success, global recognition, and long-term memory.","zh":"這個片語結合成功、全球認可和長期記憶。"}],"source":"66 - Salvador Dali.pdf","sourcePage":1},{"front":"enduring fame","meaning":"持久的名聲","examples":[{"en":"Dalí’s paintings brought him enduring fame.","zh":"達利的畫作為他帶來持久的名聲。"},{"en":"Enduring fame is fame that lasts for many years rather than disappearing quickly.","zh":"enduring fame 指持續多年而不是很快消失的名聲。"},{"en":"A writer gains enduring fame when readers still study their books long after death.","zh":"如果作家死後很久仍有讀者研究其作品，就獲得持久名聲。"},{"en":"If fame is based only on a short trend, it may not be enduring.","zh":"如果名聲只基於短暫潮流，它未必持久。"},{"en":"The phrase stresses long-lasting public recognition.","zh":"這個片語強調長久的公眾認可。"}],"source":"66 - Salvador Dali.pdf","sourcePage":2},{"front":"virtually synonymous with","meaning":"幾乎等同於……","examples":[{"en":"Dalí’s name has become virtually synonymous with Surrealism.","zh":"達利的名字已變得幾乎等同於超現實主義。"},{"en":"Virtually synonymous with means almost having the same meaning or being very closely associated with something.","zh":"virtually synonymous with 指意思幾乎相同，或與某事物非常密切相關。"},{"en":"In some cities, one famous street becomes virtually synonymous with shopping.","zh":"在一些城市，一條著名街道會幾乎等同於購物。"},{"en":"If a person becomes virtually synonymous with a style, people think of them whenever that style is mentioned.","zh":"如果某人幾乎等同於某風格，人們一提到該風格就會想到他。"},{"en":"The phrase shows an extremely strong association, though not exact identity.","zh":"這個片語顯示極強關聯，但不是完全相同。"}],"source":"66 - Salvador Dali.pdf","sourcePage":2},{"front":"Surrealism itself","meaning":"超現實主義本身","examples":[{"en":"Dalí’s work became virtually synonymous with Surrealism itself.","zh":"達利的作品變得幾乎等同於超現實主義本身。"},{"en":"Surrealism itself means the art movement as a whole, not just one example of it.","zh":"Surrealism itself 指整個超現實主義藝術運動，而不只是其中一個例子。"},{"en":"A single painting may become so famous that people connect it with modern art itself.","zh":"一幅畫可能有名到令人把它與現代藝術本身連在一起。"},{"en":"If an artist represents Surrealism itself, their work shapes how the public imagines the movement.","zh":"如果藝術家代表超現實主義本身，其作品就塑造公眾如何想像該運動。"},{"en":"The phrase emphasises the whole idea or movement.","zh":"這個片語強調整個理念或運動。"}],"source":"66 - Salvador Dali.pdf","sourcePage":2},{"front":"melting-clock image","meaning":"融化時鐘的形象","examples":[{"en":"The melting-clock image is one of Dalí’s best-known creations.","zh":"融化時鐘的形象是達利最著名的創作之一。"},{"en":"A melting-clock image is a picture of a clock that looks soft, bent, or melting like liquid.","zh":"melting-clock image 指看起來柔軟、彎曲或像液體般融化的時鐘圖像。"},{"en":"A teacher may show the melting-clock image to explain how Surrealism makes ordinary objects strange.","zh":"老師可能展示融化時鐘的形象，以解釋超現實主義如何令普通物件變得奇異。"},{"en":"If a familiar object melts in a painting, viewers may question time, memory, and reality.","zh":"如果熟悉物件在畫中融化，觀眾可能質疑時間、記憶和現實。"},{"en":"The phrase refers to one of Dalí’s most recognisable visual symbols.","zh":"這個片語指達利最容易辨認的視覺象徵之一。"}],"source":"66 - Salvador Dali.pdf","sourcePage":2},{"front":"iconic images","meaning":"標誌性形象","examples":[{"en":"The melting-clock image is one of the most iconic images in art.","zh":"融化時鐘的形象是藝術中最具標誌性的形象之一。"},{"en":"Iconic images are pictures that are widely recognised and strongly represent an idea, person, or period.","zh":"iconic images 指被廣泛認出，並強烈代表某理念、人物或時代的圖像。"},{"en":"A protest photograph can become an iconic image if it captures a historic moment.","zh":"如果抗議照片捕捉歷史時刻，它可以成為標誌性形象。"},{"en":"If an image is iconic, people may recognise it even without knowing the full story.","zh":"如果圖像具標誌性，人們即使不知道完整故事也可能認得它。"},{"en":"The phrase describes images with lasting cultural power.","zh":"這個片語描述具有持久文化力量的圖像。"}],"source":"66 - Salvador Dali.pdf","sourcePage":2},{"front":"antics","meaning":"古怪行徑","examples":[{"en":"Dalí’s antics became almost as famous as his paintings.","zh":"達利的古怪行徑幾乎與他的畫作一樣有名。"},{"en":"Antics are unusual, silly, or attention-seeking actions.","zh":"antics 指不尋常、滑稽或吸引注意的行為。"},{"en":"A comedian’s antics on stage may make the audience laugh before the joke begins.","zh":"喜劇演員在台上的古怪行徑可能在笑話開始前已令觀眾發笑。"},{"en":"If an artist’s antics attract too much attention, people may talk more about behaviour than work.","zh":"如果藝術家的古怪行徑吸引太多注意，人們可能談行為多於作品。"},{"en":"The word often suggests entertaining but not fully serious behaviour.","zh":"這個詞通常暗示有娛樂性但不完全嚴肅的行為。"}],"source":"66 - Salvador Dali.pdf","sourcePage":2},{"front":"the stuff of anecdotes","meaning":"成為軼事題材","examples":[{"en":"Dalí’s behaviour became the stuff of anecdotes.","zh":"達利的行為成為軼事題材。"},{"en":"The stuff of anecdotes means material that people like to tell as short interesting stories.","zh":"the stuff of anecdotes 指人們喜歡作為短小有趣故事講述的材料。"},{"en":"A teacher’s habit of bringing strange objects to class can become the stuff of anecdotes among students.","zh":"老師帶奇怪物件上課的習慣，可能成為學生之間的軼事題材。"},{"en":"If someone behaves memorably, small incidents may later turn into popular stories.","zh":"如果某人行為令人難忘，小事件日後可能變成流傳故事。"},{"en":"The phrase shows that behaviour has become story-worthy.","zh":"這個片語顯示某行為值得被講成故事。"}],"source":"66 - Salvador Dali.pdf","sourcePage":2},{"front":"be born into","meaning":"出生於……家庭","examples":[{"en":"Dalí was born into a middle-class family in Spain.","zh":"達利出生於西班牙一個中產家庭。"},{"en":"Be born into means enter life as a member of a particular family, class, or situation.","zh":"be born into 指出生時成為某家庭、階層或情況的一員。"},{"en":"A child born into a musical family may hear instruments every day.","zh":"出生於音樂家庭的孩子可能每天都聽到樂器聲。"},{"en":"If someone is born into wealth, they may have opportunities others lack.","zh":"如果某人出生於富裕家庭，可能擁有別人缺乏的機會。"},{"en":"The phrase describes the circumstances at the start of a person’s life.","zh":"這個片語描述一個人生命開始時的處境。"}],"source":"66 - Salvador Dali.pdf","sourcePage":2},{"front":"a middle-class family","meaning":"中產家庭","examples":[{"en":"Dalí was born into a middle-class family.","zh":"達利出生於中產家庭。"},{"en":"A middle-class family is a family with moderate economic comfort, education, or social status.","zh":"a middle-class family 指在經濟舒適度、教育或社會地位上屬中等的家庭。"},{"en":"A middle-class family may be able to pay for lessons, books, and some travel, but not unlimited luxury.","zh":"中產家庭可能負擔得起課程、書本和一些旅行，但不是無限奢華。"},{"en":"If an artist comes from a middle-class family, early education may be easier to access.","zh":"如果藝術家來自中產家庭，早期教育可能較容易取得。"},{"en":"The phrase describes social and economic background.","zh":"這個片語描述社會和經濟背景。"}],"source":"66 - Salvador Dali.pdf","sourcePage":2},{"front":"the Catalonian town of Figueres","meaning":"加泰羅尼亞城鎮菲格雷斯","examples":[{"en":"Dalí was born in the Catalonian town of Figueres.","zh":"達利出生於加泰羅尼亞城鎮菲格雷斯。"},{"en":"The Catalonian town of Figueres means the town of Figueres in Catalonia, a region in north-eastern Spain.","zh":"the Catalonian town of Figueres 指位於西班牙東北部加泰羅尼亞地區的菲格雷斯鎮。"},{"en":"Art tourists may visit the Catalonian town of Figueres because of its connection with Dalí.","zh":"藝術旅客可能因其與達利的關係而到訪加泰羅尼亞城鎮菲格雷斯。"},{"en":"If a museum is built in an artist’s hometown, that town may become part of the artist’s story.","zh":"如果博物館建於藝術家家鄉，該城鎮可能成為藝術家故事的一部分。"},{"en":"The phrase identifies Dalí’s birthplace with regional detail.","zh":"這個片語以地區細節指出達利的出生地。"}],"source":"66 - Salvador Dali.pdf","sourcePage":2},{"front":"north-eastern Spain","meaning":"西班牙東北部","examples":[{"en":"Figueres is in north-eastern Spain.","zh":"菲格雷斯位於西班牙東北部。"},{"en":"North-eastern Spain means the part of Spain located toward the north and east of the country.","zh":"north-eastern Spain 指西班牙國土中偏北和偏東的部分。"},{"en":"A traveller visiting north-eastern Spain may go to Catalonia, Barcelona, or nearby towns.","zh":"到訪西班牙東北部的旅客可能前往加泰羅尼亞、巴塞隆拿或附近城鎮。"},{"en":"If a place is in north-eastern Spain, it may have Catalan cultural influences.","zh":"如果某地位於西班牙東北部，可能受到加泰羅尼亞文化影響。"},{"en":"The phrase gives geographical location.","zh":"這個片語給出地理位置。"}],"source":"66 - Salvador Dali.pdf","sourcePage":3},{"front":"to give him his full name","meaning":"說出他的全名","examples":[{"en":"Salvador Felipe Jacinto Dalí Domenech was his full name.","zh":"Salvador Felipe Jacinto Dalí Domenech 是他的全名。"},{"en":"To give him his full name means to state a person’s complete official name rather than a shorter version.","zh":"to give him his full name 指說出一個人的完整官方姓名，而不是較短稱呼。"},{"en":"William Shakespeare, to give him his full name, is often simply called Shakespeare.","zh":"William Shakespeare，說出他的全名，常被簡稱為 Shakespeare。"},{"en":"If a writer gives a full name, it may sound formal or add biographical detail.","zh":"如果作者給出全名，可能顯得正式或增加傳記細節。"},{"en":"The phrase is used when introducing the complete name after a shorter common name.","zh":"這個片語用於在常用短名後引出完整名字。"}],"source":"66 - Salvador Dali.pdf","sourcePage":3},{"front":"aim high","meaning":"志向遠大","examples":[{"en":"Dalí aimed high from the beginning.","zh":"達利從一開始就志向遠大。"},{"en":"Aim high means set ambitious goals and expect great achievement.","zh":"aim high 指設定有抱負的目標，並期待重大成就。"},{"en":"A student who aims high may plan to enter a top university and work hard for it.","zh":"志向遠大的學生可能計劃入讀頂尖大學，並為此努力。"},{"en":"If people aim high without effort, ambition may turn into empty boasting.","zh":"如果人們志向遠大但不努力，抱負可能變成空談。"},{"en":"The phrase suggests strong ambition and confidence.","zh":"這個片語暗示強烈抱負和自信。"}],"source":"66 - Salvador Dali.pdf","sourcePage":3},{"front":"from the beginning","meaning":"從一開始","examples":[{"en":"Dalí showed ambition from the beginning.","zh":"達利從一開始就展現抱負。"},{"en":"From the beginning means starting from the earliest point or first stage.","zh":"from the beginning 指從最早的時刻或第一階段開始。"},{"en":"A good project needs clear communication from the beginning.","zh":"好項目從一開始就需要清晰溝通。"},{"en":"If a student practises pronunciation from the beginning, bad habits are less likely to form.","zh":"如果學生從一開始就練習發音，較不容易形成壞習慣。"},{"en":"The phrase points to the start of a process or story.","zh":"這個片語指一個過程或故事的開端。"}],"source":"66 - Salvador Dali.pdf","sourcePage":3},{"front":"autobiography","meaning":"自傳","examples":[{"en":"Dalí described his ambition in his autobiography.","zh":"達利在自傳中描述他的抱負。"},{"en":"An autobiography is a book or account written by someone about their own life.","zh":"autobiography 是某人寫關於自己人生的書或記述。"},{"en":"A retired teacher may write an autobiography about students, schools, and social change.","zh":"退休老師可能寫一本關於學生、學校和社會變遷的自傳。"},{"en":"If an artist writes an autobiography, readers can see how the artist wants to present themselves.","zh":"如果藝術家寫自傳，讀者可以看到藝術家希望如何呈現自己。"},{"en":"The word refers to a self-written life story.","zh":"這個詞指自己撰寫的人生故事。"}],"source":"66 - Salvador Dali.pdf","sourcePage":3},{"front":"entitled","meaning":"題為……","examples":[{"en":"Dalí wrote an autobiography entitled The Secret Life of Salvador Dalí.","zh":"達利寫了一本題為《薩爾瓦多・達利的秘密生活》的自傳。"},{"en":"Entitled means given the title of a book, film, article, or artwork.","zh":"entitled 指一本書、電影、文章或藝術作品被命名為某標題。"},{"en":"Students read an article entitled “How Sleep Affects Memory”.","zh":"學生閱讀一篇題為《睡眠如何影響記憶》的文章。"},{"en":"If a book is entitled with a dramatic phrase, readers may expect a personal or exciting story.","zh":"如果一本書題為戲劇性字句，讀者可能期待個人化或刺激故事。"},{"en":"The word is formal and often used when naming works.","zh":"這個詞較正式，常用於命名作品。"}],"source":"66 - Salvador Dali.pdf","sourcePage":3},{"front":"ambition","meaning":"抱負；野心","examples":[{"en":"Dalí’s ambition grew steadily throughout his early life.","zh":"達利的抱負在早年生活中穩步增長。"},{"en":"Ambition is a strong desire to achieve something important or become successful.","zh":"ambition 指想達成重要事情或取得成功的強烈願望。"},{"en":"A student with ambition may spend extra time preparing for competitions.","zh":"有抱負的學生可能花額外時間準備比賽。"},{"en":"If ambition is balanced with humility, it can push people to improve without becoming arrogant.","zh":"如果抱負與謙遜取得平衡，它可以推動人進步而不變得傲慢。"},{"en":"The word can be positive or negative depending on how it is expressed.","zh":"這個詞可正面也可負面，視乎如何表達。"}],"source":"66 - Salvador Dali.pdf","sourcePage":3},{"front":"grow steadily","meaning":"穩步增長","examples":[{"en":"His ambition grew steadily over the years.","zh":"他的抱負多年來穩步增長。"},{"en":"Grow steadily means increase gradually and consistently over time.","zh":"grow steadily 指隨時間逐漸而持續增加。"},{"en":"A small business may grow steadily if customers return every month.","zh":"如果顧客每月回來，小企業可能穩步增長。"},{"en":"If confidence grows steadily, a shy student may eventually speak in public.","zh":"如果信心穩步增長，害羞學生最終可能公開發言。"},{"en":"The phrase suggests slow but continuous development.","zh":"這個片語暗示緩慢但持續的發展。"}],"source":"66 - Salvador Dali.pdf","sourcePage":3},{"front":"ever since","meaning":"自那以後一直","examples":[{"en":"His ambition had been growing steadily ever since childhood.","zh":"他的抱負自童年以來一直穩步增長。"},{"en":"Ever since means continuously from a particular past time until now or a later point.","zh":"ever since 指從某個過去時間起一直持續到現在或後來某時。"},{"en":"She has loved drawing ever since her grandfather gave her coloured pencils.","zh":"自從祖父送她彩色鉛筆後，她一直喜愛畫畫。"},{"en":"If a habit starts early and continues, we can say it has existed ever since that time.","zh":"如果習慣很早開始並持續，我們可以說它自那時以後一直存在。"},{"en":"The phrase links a starting point with continued development.","zh":"這個片語把起點與持續發展連接起來。"}],"source":"66 - Salvador Dali.pdf","sourcePage":3},{"front":"self-belief","meaning":"自信；自我信念","examples":[{"en":"Dalí’s self-belief later turned into arrogance.","zh":"達利的自信後來變成傲慢。"},{"en":"Self-belief is confidence in one’s own ability, judgement, or value.","zh":"self-belief 指對自己能力、判斷或價值的信心。"},{"en":"A student needs self-belief before giving a speech in front of a large class.","zh":"學生在大班面前演講前需要自信。"},{"en":"If self-belief becomes too extreme, it may turn into arrogance.","zh":"如果自信變得過度極端，可能轉化為傲慢。"},{"en":"The phrase is usually positive, but the context can make it sound excessive.","zh":"這個片語通常正面，但語境可令它聽起來過度。"}],"source":"66 - Salvador Dali.pdf","sourcePage":3},{"front":"mature into","meaning":"發展成","examples":[{"en":"His ambition matured into full-blown arrogance.","zh":"他的抱負發展成十足的傲慢。"},{"en":"Mature into means gradually develop into a later, stronger, or more complete form.","zh":"mature into 指逐漸發展成後來、更強或更完整的形式。"},{"en":"A childhood interest in science may mature into a career in medicine.","zh":"童年對科學的興趣可能發展成醫學事業。"},{"en":"If confidence matures into arrogance, other people may feel dismissed or insulted.","zh":"如果自信發展成傲慢，其他人可能感到被否定或冒犯。"},{"en":"The phrase describes development over time.","zh":"這個片語描述隨時間發展。"}],"source":"66 - Salvador Dali.pdf","sourcePage":4},{"front":"full-blown arrogance","meaning":"十足的傲慢","examples":[{"en":"Dalí’s self-belief matured into full-blown arrogance.","zh":"達利的自信發展成十足的傲慢。"},{"en":"Full-blown arrogance means complete and obvious excessive pride in oneself.","zh":"full-blown arrogance 指完整而明顯的過度自大。"},{"en":"A talented student shows full-blown arrogance if he refuses to listen to any teacher.","zh":"如果有才華的學生拒絕聽任何老師，就是表現出十足傲慢。"},{"en":"If confidence becomes full-blown arrogance, it can damage relationships and judgement.","zh":"如果自信變成十足傲慢，就會損害關係和判斷。"},{"en":"The phrase is strongly negative.","zh":"這個片語非常負面。"}],"source":"66 - Salvador Dali.pdf","sourcePage":4},{"front":"in later years","meaning":"在後來的歲月","examples":[{"en":"His arrogance became more obvious in later years.","zh":"他的傲慢在後來的歲月變得更明顯。"},{"en":"In later years means during a later period of someone’s life or a process.","zh":"in later years 指在某人人生或某過程的後期。"},{"en":"In later years, a teacher may become more patient because of experience.","zh":"在後來的歲月，老師可能因經驗而變得更有耐性。"},{"en":"If a habit becomes stronger in later years, people may see it as part of someone’s character.","zh":"如果習慣在後來歲月變得更強，人們可能把它視為某人性格一部分。"},{"en":"The phrase contrasts a later stage with an earlier one.","zh":"這個片語把後期與早期作對比。"}],"source":"66 - Salvador Dali.pdf","sourcePage":4},{"front":"be amply demonstrated","meaning":"得到充分顯示","examples":[{"en":"His arrogance was amply demonstrated by his attitude towards the examiners.","zh":"他對考官的態度充分顯示了他的傲慢。"},{"en":"Be amply demonstrated means be shown very clearly and with enough evidence.","zh":"be amply demonstrated 指以充分證據非常清楚地顯示出來。"},{"en":"A student’s kindness is amply demonstrated when they help classmates every day.","zh":"如果學生每天幫助同學，其善良就得到充分顯示。"},{"en":"If a pattern appears many times, the point is amply demonstrated.","zh":"如果模式多次出現，該觀點就得到充分顯示。"},{"en":"The phrase is formal and means the evidence is strong.","zh":"這個片語較正式，意思是證據很強。"}],"source":"66 - Salvador Dali.pdf","sourcePage":4},{"front":"examiners","meaning":"考官","examples":[{"en":"Dalí believed the examiners at the Academy were below par.","zh":"達利認為學院的考官低於標準。"},{"en":"Examiners are people who test, judge, or assess students’ work or performance.","zh":"examiners 指測試、判斷或評估學生作品或表現的人。"},{"en":"Examiners may mark essays, interview candidates, or judge practical exams.","zh":"考官可能批改文章、面試考生或評審實作考試。"},{"en":"If candidates disagree with examiners, they may still need to follow official procedures.","zh":"如果考生不同意考官，仍可能需要遵循官方程序。"},{"en":"The word refers to assessors in exams or evaluations.","zh":"這個詞指考試或評估中的評審者。"}],"source":"66 - Salvador Dali.pdf","sourcePage":4},{"front":"the Madrid Academy","meaning":"馬德里學院","examples":[{"en":"Dalí attended the Madrid Academy as a young artist.","zh":"達利年輕時就讀馬德里學院。"},{"en":"The Madrid Academy refers to the art academy in Madrid where Dalí studied.","zh":"the Madrid Academy 指達利曾就讀、位於馬德里的藝術學院。"},{"en":"A young painter may enter an academy to receive formal artistic training.","zh":"年輕畫家可能進入學院接受正式藝術訓練。"},{"en":"If an academy refuses to grant a degree, a student’s career path may change.","zh":"如果學院拒絕授予學位，學生的事業路向可能改變。"},{"en":"The phrase identifies an important institution in Dalí’s early training.","zh":"這個片語指出達利早期訓練中的重要機構。"}],"source":"66 - Salvador Dali.pdf","sourcePage":4},{"front":"well below par","meaning":"遠低於標準","examples":[{"en":"Dalí felt that his examiners were well below par.","zh":"達利覺得他的考官遠低於標準。"},{"en":"Well below par means much lower than the expected or acceptable standard.","zh":"well below par 指遠低於預期或可接受標準。"},{"en":"A restaurant’s service is well below par if customers wait an hour for simple food.","zh":"如果顧客等一小時才收到簡單食物，餐廳服務就是遠低於標準。"},{"en":"If work is well below par, teachers may ask students to revise it completely.","zh":"如果作品遠低於標準，老師可能要求學生完全修改。"},{"en":"The phrase is strongly negative and means far from good enough.","zh":"這個片語很負面，意思是遠遠不夠好。"}],"source":"66 - Salvador Dali.pdf","sourcePage":4},{"front":"to a degree","meaning":"在某程度上","examples":[{"en":"To a degree, Dalí’s talent excused his conceit.","zh":"在某程度上，達利的才華為他的自負開脫。"},{"en":"To a degree means partly or to some extent, but not completely.","zh":"to a degree 指部分地或在某程度上，但不是完全。"},{"en":"To a degree, nervousness can help students prepare more carefully.","zh":"在某程度上，緊張可以幫助學生更仔細準備。"},{"en":"If a person is very talented, others may tolerate some difficult behaviour to a degree.","zh":"如果一個人很有才華，其他人可能在某程度上容忍一些難相處行為。"},{"en":"The phrase softens a claim and avoids making it absolute.","zh":"這個片語緩和主張，避免絕對化。"}],"source":"66 - Salvador Dali.pdf","sourcePage":4},{"front":"undeniably impressive","meaning":"無可否認地令人印象深刻的","examples":[{"en":"Dalí had an undeniably impressive talent.","zh":"達利有無可否認地令人印象深刻的才華。"},{"en":"Undeniably impressive means so strong or striking that it is difficult to reject or ignore.","zh":"undeniably impressive 指非常強或突出，以致難以否定或忽視。"},{"en":"A student’s progress is undeniably impressive if they move from failing to top marks in one year.","zh":"如果學生一年內由不及格進步到最高分，其進步就是無可否認地令人印象深刻。"},{"en":"If evidence is undeniably impressive, even critics may have to admit its value.","zh":"如果證據無可否認地令人印象深刻，即使批評者也可能不得不承認其價值。"},{"en":"The phrase expresses strong approval while leaving little room for doubt.","zh":"這個片語表達強烈讚賞，並幾乎不留疑問空間。"}],"source":"66 - Salvador Dali.pdf","sourcePage":4},{"front":"precocious talent","meaning":"早熟的才華","examples":[{"en":"Dalí displayed precocious talent as a young artist.","zh":"達利作為年輕藝術家時展現早熟才華。"},{"en":"Precocious talent is ability that appears unusually early in a young person.","zh":"precocious talent 指年輕人身上異常早出現的能力。"},{"en":"A child who composes music at age six may show precocious talent.","zh":"六歲就能作曲的孩子可能展現早熟才華。"},{"en":"If talent appears early, teachers may need to provide advanced challenges.","zh":"如果才華早早出現，老師可能需要提供進階挑戰。"},{"en":"The phrase describes early development beyond normal expectation.","zh":"這個片語描述超出一般預期的早期發展。"}],"source":"66 - Salvador Dali.pdf","sourcePage":4},{"front":"excuse his conceit","meaning":"為他的自負開脫","examples":[{"en":"His impressive talent partly excused his conceit.","zh":"他令人印象深刻的才華部分為他的自負開脫。"},{"en":"Excuse his conceit means make his excessive pride seem more understandable or forgivable.","zh":"excuse his conceit 指令他的過度自大看起來較可理解或較可原諒。"},{"en":"A brilliant student’s results may partly excuse confidence, but not rudeness.","zh":"優秀學生的成績可能部分為其自信開脫，但不能為無禮開脫。"},{"en":"If talent excuses arrogance too much, poor behaviour may go unchecked.","zh":"如果才華過度為傲慢開脫，差劣行為可能不受約束。"},{"en":"The phrase suggests a reason for tolerance, not full approval.","zh":"這個片語暗示容忍的理由，而不是完全認同。"}],"source":"66 - Salvador Dali.pdf","sourcePage":5},{"front":"conceit","meaning":"自負","examples":[{"en":"Dalí’s conceit affected the course of his life.","zh":"達利的自負影響了他的人生走向。"},{"en":"Conceit is excessive pride in one’s own ability or importance.","zh":"conceit 指對自己能力或重要性的過度驕傲。"},{"en":"A team leader shows conceit if they believe no one else can offer useful ideas.","zh":"如果團隊領袖認為沒有其他人能提出有用想法，就是表現自負。"},{"en":"If conceit grows, a person may stop listening to advice.","zh":"如果自負增長，一個人可能停止聽取建議。"},{"en":"The word is negative and stronger than confidence.","zh":"這個詞是負面的，比 confidence 更強。"}],"source":"66 - Salvador Dali.pdf","sourcePage":5},{"front":"be exhibited","meaning":"被展出","examples":[{"en":"Dalí’s first works were exhibited when he was only 14.","zh":"達利第一批作品在他只有14歲時被展出。"},{"en":"Be exhibited means be shown publicly, especially in a gallery, museum, or exhibition.","zh":"be exhibited 指被公開展示，尤其在畫廊、博物館或展覽中。"},{"en":"Student paintings may be exhibited in the school hall at the end of the year.","zh":"學生畫作可能在年終於學校禮堂被展出。"},{"en":"If a young artist’s work is exhibited early, it can bring attention and confidence.","zh":"如果年輕藝術家的作品早早被展出，可以帶來關注和信心。"},{"en":"The phrase focuses on public display.","zh":"這個片語集中於公開展示。"}],"source":"66 - Salvador Dali.pdf","sourcePage":5},{"front":"as part of","meaning":"作為……的一部分","examples":[{"en":"His early works were shown as part of an exhibition in Figueres.","zh":"他的早期作品作為菲格雷斯一個展覽的一部分展出。"},{"en":"As part of means included within a larger event, plan, or group.","zh":"as part of 指包含在更大的活動、計劃或群體之內。"},{"en":"Students may write a short speech as part of an English assessment.","zh":"學生可能寫短演講作為英語評估的一部分。"},{"en":"If something is shown as part of an exhibition, it appears with other related works.","zh":"如果某物作為展覽的一部分展出，它會與其他相關作品一起出現。"},{"en":"The phrase explains how one thing fits inside a larger whole.","zh":"這個片語解釋一件事如何屬於更大整體。"}],"source":"66 - Salvador Dali.pdf","sourcePage":5},{"front":"be admitted to","meaning":"獲准進入；被錄取入","examples":[{"en":"Dalí was admitted to the Royal Academy of Fine Arts.","zh":"達利獲准進入皇家美術學院。"},{"en":"Be admitted to means be accepted into a school, organisation, hospital, or programme.","zh":"be admitted to 指被學校、組織、醫院或計劃正式接納。"},{"en":"A student may be admitted to a university after passing interviews and exams.","zh":"學生通過面試和考試後，可能被大學錄取。"},{"en":"If someone is admitted to a famous academy, it can mark an important step in their career.","zh":"如果某人獲准進入著名學院，這可以標誌其事業重要一步。"},{"en":"The phrase focuses on official acceptance.","zh":"這個片語集中於正式接納。"}],"source":"66 - Salvador Dali.pdf","sourcePage":5},{"front":"the Royal Academy of Fine Arts","meaning":"皇家美術學院","examples":[{"en":"Dalí studied at the Royal Academy of Fine Arts in Madrid.","zh":"達利在馬德里的皇家美術學院學習。"},{"en":"The Royal Academy of Fine Arts refers to a formal art institution where students receive artistic training.","zh":"the Royal Academy of Fine Arts 指學生接受藝術訓練的正式藝術機構。"},{"en":"A young painter may study drawing, composition, and art history at an academy of fine arts.","zh":"年輕畫家可能在美術學院學習素描、構圖和藝術史。"},{"en":"If an artist attends a prestigious academy, their training may influence their early style.","zh":"如果藝術家就讀著名學院，其訓練可能影響早期風格。"},{"en":"The phrase names the institution connected with Dalí’s formal education.","zh":"這個片語指與達利正式教育有關的機構。"}],"source":"66 - Salvador Dali.pdf","sourcePage":5},{"front":"it wasn’t long before","meaning":"沒過多久就","examples":[{"en":"It wasn’t long before Dalí’s sense of self-worth came to the fore.","zh":"沒過多久，達利的自我價值感就變得明顯。"},{"en":"It wasn’t long before means something happened soon after another event.","zh":"it wasn’t long before 指某事在另一事件後很快發生。"},{"en":"It wasn’t long before the new student made friends in class.","zh":"沒過多久，新學生就在班中交到朋友。"},{"en":"If a strong personality is present, it may not be long before others notice it.","zh":"如果性格強烈，沒多久其他人可能就會注意到。"},{"en":"The phrase shows that a change or event happened quickly.","zh":"這個片語顯示變化或事件很快發生。"}],"source":"66 - Salvador Dali.pdf","sourcePage":5},{"front":"highly developed","meaning":"高度發展的","examples":[{"en":"Dalí had a highly developed sense of self-worth.","zh":"達利有高度發展的自我價值感。"},{"en":"Highly developed means very strong, advanced, or fully formed.","zh":"highly developed 指非常強、先進或充分形成。"},{"en":"A musician with a highly developed ear can notice tiny changes in pitch.","zh":"聽覺高度發展的音樂人能察覺音高的細微變化。"},{"en":"If a person has a highly developed sense of confidence, they may take bold risks.","zh":"如果一個人有高度發展的自信感，可能會冒大膽風險。"},{"en":"The phrase describes something that has grown to a high level.","zh":"這個片語描述某物已發展到高水平。"}],"source":"66 - Salvador Dali.pdf","sourcePage":5},{"front":"sense of self-worth","meaning":"自我價值感","examples":[{"en":"Dalí’s sense of self-worth affected his life choices.","zh":"達利的自我價值感影響了他的人生選擇。"},{"en":"Sense of self-worth means how valuable or capable a person feels themselves to be.","zh":"sense of self-worth 指一個人感到自己有多有價值或有能力。"},{"en":"Encouragement from teachers can help students build a healthy sense of self-worth.","zh":"老師的鼓勵可以幫助學生建立健康自我價值感。"},{"en":"If self-worth becomes too inflated, it may turn into arrogance.","zh":"如果自我價值感過度膨脹，可能變成傲慢。"},{"en":"The phrase describes inner confidence about one’s own value.","zh":"這個片語描述對自身價值的內在信心。"}],"source":"66 - Salvador Dali.pdf","sourcePage":5},{"front":"depending on how you view","meaning":"視乎你如何看待","examples":[{"en":"The same quality may be called confidence or conceit, depending on how you view the artist.","zh":"同一特質可被稱為自信或自負，視乎你如何看待這位藝術家。"},{"en":"Depending on how you view means the judgement changes according to your perspective.","zh":"depending on how you view 指判斷會根據你的角度而改變。"},{"en":"A strict teacher may seem helpful or harsh, depending on how students view discipline.","zh":"嚴格老師可能顯得有幫助或苛刻，視乎學生如何看待紀律。"},{"en":"If people value originality, they may view eccentric behaviour more positively.","zh":"如果人們重視原創性，可能會較正面看待古怪行為。"},{"en":"The phrase shows that interpretation can change with viewpoint.","zh":"這個片語顯示詮釋可隨觀點改變。"}],"source":"66 - Salvador Dali.pdf","sourcePage":5},{"front":"come to the fore","meaning":"變得明顯；浮現出來","examples":[{"en":"Dalí’s sense of self-worth soon came to the fore.","zh":"達利的自我價值感很快變得明顯。"},{"en":"Come to the fore means become noticeable, important, or clearly visible.","zh":"come to the fore 指變得可見、重要或清楚明顯。"},{"en":"A quiet student’s leadership may come to the fore during a group project.","zh":"安靜學生的領導能力可能在小組項目中浮現出來。"},{"en":"If pressure increases, a person’s confidence or weakness may come to the fore.","zh":"如果壓力增加，一個人的信心或弱點可能變得明顯。"},{"en":"The phrase describes something moving into attention.","zh":"這個片語描述某事進入人們注意。"}],"source":"66 - Salvador Dali.pdf","sourcePage":6},{"front":"affect the course of his life","meaning":"影響他的人生走向","examples":[{"en":"His self-belief affected the course of his life.","zh":"他的自信影響了他的人生走向。"},{"en":"Affect the course of his life means change the direction or development of his life.","zh":"affect the course of his life 指改變他人生的方向或發展。"},{"en":"A scholarship can affect the course of a student’s life by opening access to university.","zh":"獎學金可以透過打開大學機會來影響學生的人生走向。"},{"en":"If a strong belief shapes many decisions, it can change a person’s future path.","zh":"如果強烈信念塑造許多決定，它可以改變一個人的未來道路。"},{"en":"The phrase connects one quality or event with long-term life direction.","zh":"這個片語把某一特質或事件與長遠人生方向連接起來。"}],"source":"66 - Salvador Dali.pdf","sourcePage":6},{"front":"far superior to","meaning":"遠遠優於","examples":[{"en":"Dalí believed himself far superior to his tutors.","zh":"達利相信自己遠遠優於他的導師。"},{"en":"Far superior to means much better than someone or something else.","zh":"far superior to 指比某人或某物好得多。"},{"en":"A new phone may be far superior to an old one if it is faster, safer, and easier to use.","zh":"如果新手機更快、更安全、更易用，它可能遠遠優於舊手機。"},{"en":"If someone thinks they are far superior to others, they may ignore advice.","zh":"如果某人認為自己遠遠優於他人，可能會忽視建議。"},{"en":"The phrase shows a strong comparison of quality or ability.","zh":"這個片語顯示能力或質素上的強烈比較。"}],"source":"66 - Salvador Dali.pdf","sourcePage":6},{"front":"nevertheless","meaning":"然而；儘管如此","examples":[{"en":"His tutors nevertheless refused to grant him a degree.","zh":"然而，他的導師拒絕授予他學位。"},{"en":"Nevertheless means despite what has just been said.","zh":"nevertheless 指儘管剛才所說的情況仍然如此。"},{"en":"The plan was expensive; nevertheless, the school approved it because it was necessary.","zh":"該計劃很昂貴；然而，學校因其必要性而批准。"},{"en":"If a person is talented, others may nevertheless reject their behaviour or demands.","zh":"即使一個人有才華，其他人仍可能拒絕其行為或要求。"},{"en":"The word introduces contrast.","zh":"這個詞引出對比。"}],"source":"66 - Salvador Dali.pdf","sourcePage":6},{"front":"grant him a degree","meaning":"授予他學位","examples":[{"en":"The Academy refused to grant him a degree.","zh":"學院拒絕授予他學位。"},{"en":"Grant him a degree means officially award him an academic qualification.","zh":"grant him a degree 指正式授予他學術資格。"},{"en":"A university may grant a student a degree after all exams and projects are completed.","zh":"大學可能在學生完成所有考試和項目後授予學位。"},{"en":"If an institution refuses to grant a degree, the student may leave without formal qualification.","zh":"如果機構拒絕授予學位，學生可能在沒有正式資格下離開。"},{"en":"The phrase focuses on official academic approval.","zh":"這個片語集中於官方學術認可。"}],"source":"66 - Salvador Dali.pdf","sourcePage":6},{"front":"rebellious artist","meaning":"反叛的藝術家","examples":[{"en":"The rebellious artist left for Paris.","zh":"這位反叛的藝術家動身前往巴黎。"},{"en":"A rebellious artist is an artist who resists rules, authority, or conventional expectations.","zh":"rebellious artist 指抗拒規則、權威或傳統期望的藝術家。"},{"en":"A rebellious artist may refuse to paint in the style their teachers prefer.","zh":"反叛的藝術家可能拒絕按老師喜歡的風格作畫。"},{"en":"If rebellion is joined with talent, it may lead to originality or conflict.","zh":"如果反叛加上才華，可能帶來原創性或衝突。"},{"en":"The phrase describes both artistic independence and defiance.","zh":"這個片語同時描述藝術獨立和反抗。"}],"source":"66 - Salvador Dali.pdf","sourcePage":6},{"front":"leave for Paris","meaning":"動身前往巴黎","examples":[{"en":"Dalí left for Paris to continue his artistic development.","zh":"達利動身前往巴黎，以繼續他的藝術發展。"},{"en":"Leave for Paris means depart in order to go to Paris.","zh":"leave for Paris 指出發前往巴黎。"},{"en":"A student may leave for London after receiving a university offer.","zh":"學生收到大學錄取後，可能動身前往倫敦。"},{"en":"If an artist leaves for a major cultural city, new ideas and contacts may follow.","zh":"如果藝術家前往重要文化城市，可能接觸新想法和人脈。"},{"en":"The phrase focuses on departure toward a destination.","zh":"這個片語集中於向目的地出發。"}],"source":"66 - Salvador Dali.pdf","sourcePage":6},{"front":"acquire knowledge","meaning":"獲取知識","examples":[{"en":"Dalí hoped to acquire knowledge in Paris.","zh":"達利希望在巴黎獲取知識。"},{"en":"Acquire knowledge means gain understanding, information, or skill through learning and experience.","zh":"acquire knowledge 指透過學習和經驗獲得理解、資訊或技能。"},{"en":"Students acquire knowledge by reading, asking questions, and practising.","zh":"學生透過閱讀、提問和練習獲取知識。"},{"en":"If someone enters a new environment, they may acquire knowledge that school alone cannot provide.","zh":"如果某人進入新環境，可能獲取學校單獨無法提供的知識。"},{"en":"The phrase is formal and focuses on learning.","zh":"這個片語較正式，集中於學習。"}],"source":"66 - Salvador Dali.pdf","sourcePage":6},{"front":"be adequate to","meaning":"足以……","examples":[{"en":"Dalí believed his tutors were not adequate to teach him.","zh":"達利認為他的導師不足以教導他。"},{"en":"Be adequate to means be good enough or suitable enough for a task.","zh":"be adequate to 指足夠好或足夠合適去完成某任務。"},{"en":"A small classroom may not be adequate to hold eighty students safely.","zh":"小課室可能不足以安全容納八十名學生。"},{"en":"If support is not adequate, students may need extra help or a different method.","zh":"如果支援不足，學生可能需要額外幫助或不同方法。"},{"en":"The phrase judges whether something is sufficient.","zh":"這個片語判斷某事是否足夠。"}],"source":"66 - Salvador Dali.pdf","sourcePage":6},{"front":"impart knowledge","meaning":"傳授知識","examples":[{"en":"Dalí felt that his tutors were not adequate to impart knowledge to him.","zh":"達利覺得他的導師不足以向他傳授知識。"},{"en":"Impart knowledge means pass understanding or information from one person to another.","zh":"impart knowledge 指把理解或資訊從一個人傳給另一個人。"},{"en":"A good teacher imparts knowledge through clear explanation and useful examples.","zh":"好老師透過清晰解釋和有用例子傳授知識。"},{"en":"If lessons only give facts without context, they may fail to impart real knowledge.","zh":"如果課堂只給事實而沒有背景，可能無法傳授真正知識。"},{"en":"The phrase is formal and often used about teaching.","zh":"這個片語較正式，常用於教學。"}],"source":"66 - Salvador Dali.pdf","sourcePage":6},{"front":"make the acquaintance of","meaning":"結識","examples":[{"en":"Dalí made the acquaintance of several French Surrealists.","zh":"達利結識了幾位法國超現實主義者。"},{"en":"Make the acquaintance of means meet someone for the first time and begin to know them.","zh":"make the acquaintance of 指第一次見到某人並開始認識他們。"},{"en":"A new employee may make the acquaintance of colleagues during orientation.","zh":"新員工可能在入職培訓期間結識同事。"},{"en":"If an artist makes the acquaintance of influential people, new opportunities may appear.","zh":"如果藝術家結識有影響力的人，新機會可能出現。"},{"en":"The phrase is formal and means get to know someone.","zh":"這個片語較正式，意思是認識某人。"}],"source":"66 - Salvador Dali.pdf","sourcePage":7},{"front":"French Surrealists","meaning":"法國超現實主義者","examples":[{"en":"Dalí met several French Surrealists in Paris.","zh":"達利在巴黎遇見幾位法國超現實主義者。"},{"en":"French Surrealists were artists and writers in France connected with the Surrealist movement.","zh":"French Surrealists 指在法國與超現實主義運動有關的藝術家和作家。"},{"en":"An art class may study French Surrealists to understand dream imagery and unconscious thought.","zh":"藝術課可能研究法國超現實主義者，以理解夢境意象和潛意識思想。"},{"en":"If Dalí met French Surrealists, he could see how their ideas worked in practice.","zh":"如果達利遇見法國超現實主義者，他就能看見他們的思想如何實踐。"},{"en":"The phrase identifies a group of artists by nationality and movement.","zh":"這個片語以國籍和運動識別一群藝術家。"}],"source":"66 - Salvador Dali.pdf","sourcePage":7},{"front":"prove a turning point","meaning":"證明是轉捩點","examples":[{"en":"The meeting would prove a turning point in Dalí’s artistic life.","zh":"這次會面後來證明是達利藝術生涯的轉捩點。"},{"en":"Prove a turning point means later show itself to be an event that changed direction significantly.","zh":"prove a turning point 指後來顯示某事件重大地改變方向。"},{"en":"Meeting a good mentor can prove a turning point in a student’s confidence.","zh":"遇見好導師可以證明是學生信心的轉捩點。"},{"en":"If one decision changes what happens afterwards, it may prove a turning point.","zh":"如果一個決定改變之後的事情，它可能證明是轉捩點。"},{"en":"The phrase looks back at an event and recognises its importance.","zh":"這個片語回看某事件並承認其重要性。"}],"source":"66 - Salvador Dali.pdf","sourcePage":7},{"front":"a turning point","meaning":"轉捩點","examples":[{"en":"Meeting the French Surrealists was a turning point for Dalí.","zh":"遇見法國超現實主義者是達利的轉捩點。"},{"en":"A turning point is a moment when a situation begins to change in an important way.","zh":"a turning point 指情況開始以重要方式改變的時刻。"},{"en":"A failed exam can become a turning point if it makes a student change study habits.","zh":"如果失敗考試令學生改變學習習慣，它可以成為轉捩點。"},{"en":"If a person meets new people who reshape their ideas, that meeting may become a turning point.","zh":"如果某人遇見重塑其想法的人，這次會面可能成為轉捩點。"},{"en":"The phrase marks a major change in direction.","zh":"這個片語標示方向上的重大改變。"}],"source":"66 - Salvador Dali.pdf","sourcePage":7},{"front":"artistic life","meaning":"藝術生涯","examples":[{"en":"Paris became important in Dalí’s artistic life.","zh":"巴黎在達利的藝術生涯中變得重要。"},{"en":"Artistic life means a person’s development, work, relationships, and experiences as an artist.","zh":"artistic life 指一個人作為藝術家的發展、作品、人際關係和經歷。"},{"en":"A musician’s artistic life may change after joining a new orchestra.","zh":"音樂家加入新樂團後，其藝術生涯可能改變。"},{"en":"If an artist moves to a creative city, their artistic life may become richer and more experimental.","zh":"如果藝術家搬到創意城市，其藝術生涯可能變得更豐富和實驗性。"},{"en":"The phrase focuses on the career and inner development of an artist.","zh":"這個片語集中於藝術家的事業和內在發展。"}],"source":"66 - Salvador Dali.pdf","sourcePage":7},{"front":"be familiar with","meaning":"熟悉","examples":[{"en":"Dalí was already familiar with Freud’s theories.","zh":"達利已經熟悉佛洛伊德的理論。"},{"en":"Be familiar with means know something because you have seen, studied, or experienced it before.","zh":"be familiar with 指因曾經看過、學過或經歷過而知道某事。"},{"en":"Students become familiar with exam formats by practising past papers.","zh":"學生透過練習歷屆試題熟悉考試格式。"},{"en":"If an artist is familiar with a theory, they may use it in their work.","zh":"如果藝術家熟悉某理論，可能會在作品中使用它。"},{"en":"The phrase suggests knowledge or comfort, not necessarily expertise.","zh":"這個片語暗示認識或熟悉感，不一定是專家水平。"}],"source":"66 - Salvador Dali.pdf","sourcePage":7},{"front":"psychoanalytic theories","meaning":"精神分析理論","examples":[{"en":"Dalí was familiar with Freud’s psychoanalytic theories.","zh":"達利熟悉佛洛伊德的精神分析理論。"},{"en":"Psychoanalytic theories are ideas about the unconscious mind, dreams, desire, and hidden mental conflicts.","zh":"psychoanalytic theories 指關於潛意識、夢、慾望和隱藏心理衝突的思想。"},{"en":"Literature students may use psychoanalytic theories to interpret a character’s strange behaviour.","zh":"文學學生可能使用精神分析理論解讀角色的奇怪行為。"},{"en":"If artists use psychoanalytic theories, they may focus on dreams and hidden fears.","zh":"如果藝術家使用精神分析理論，可能集中於夢境和隱藏恐懼。"},{"en":"The phrase refers to theories connected with psychoanalysis.","zh":"這個片語指與精神分析學有關的理論。"}],"source":"66 - Salvador Dali.pdf","sourcePage":7},{"front":"Sigmund Freud","meaning":"西格蒙德・佛洛伊德","examples":[{"en":"Sigmund Freud’s ideas had a strong influence on Dalí.","zh":"西格蒙德・佛洛伊德的思想對達利有強烈影響。"},{"en":"Sigmund Freud was a major figure in psychoanalysis whose ideas about dreams and the unconscious influenced many artists.","zh":"西格蒙德・佛洛伊德是精神分析學的重要人物，其關於夢和潛意識的思想影響許多藝術家。"},{"en":"Psychology students often learn about Sigmund Freud when studying early theories of the mind.","zh":"心理學學生研究早期心智理論時，常會學習西格蒙德・佛洛伊德。"},{"en":"If artists were influenced by Freud, their work might explore hidden desires or fears.","zh":"如果藝術家受佛洛伊德影響，其作品可能探索隱藏慾望或恐懼。"},{"en":"The name is closely linked with psychoanalysis.","zh":"這個名字與精神分析學密切相連。"}],"source":"66 - Salvador Dali.pdf","sourcePage":7},{"front":"witness how","meaning":"見證……如何","examples":[{"en":"Dalí witnessed how the French Surrealists used Freud’s ideas.","zh":"達利見證法國超現實主義者如何使用佛洛伊德的思想。"},{"en":"Witness how means see directly the way something happens or is done.","zh":"witness how 指直接看見某事如何發生或如何被做。"},{"en":"A trainee teacher may witness how experienced teachers calm a noisy classroom.","zh":"實習老師可能見證有經驗老師如何安撫嘈雜課室。"},{"en":"If Dalí witnessed how ideas became paintings, he could apply similar methods himself.","zh":"如果達利見證思想如何變成畫作，他就能自己應用類似方法。"},{"en":"The phrase combines observation with learning.","zh":"這個片語結合觀察和學習。"}],"source":"66 - Salvador Dali.pdf","sourcePage":7},{"front":"attempt to","meaning":"嘗試","examples":[{"en":"The Surrealists attempted to capture Freud’s ideas in paint.","zh":"超現實主義者嘗試用繪畫呈現佛洛伊德的思想。"},{"en":"Attempt to means try to do something, especially something difficult.","zh":"attempt to 指嘗試做某事，尤其是困難的事。"},{"en":"Students may attempt to write a full essay in English before the exam.","zh":"學生可能在考試前嘗試用英文寫完整文章。"},{"en":"If people attempt a difficult task, success is not guaranteed but effort is clear.","zh":"如果人們嘗試困難任務，成功未必保證，但努力很清楚。"},{"en":"The phrase focuses on trying.","zh":"這個片語集中於嘗試。"}],"source":"66 - Salvador Dali.pdf","sourcePage":7},{"front":"capture ideas in paint","meaning":"用繪畫呈現思想","examples":[{"en":"The French Surrealists attempted to capture Freud’s ideas in paint.","zh":"法國超現實主義者嘗試用繪畫呈現佛洛伊德的思想。"},{"en":"Capture ideas in paint means express abstract thoughts through painted images.","zh":"capture ideas in paint 指透過繪畫圖像表達抽象思想。"},{"en":"A student may capture loneliness in paint by showing an empty chair in a dark room.","zh":"學生可能用黑暗房間中的空椅子，在畫中呈現孤獨。"},{"en":"If artists capture theories in paint, viewers can feel ideas rather than only read them.","zh":"如果藝術家用繪畫呈現理論，觀眾就能感受思想，而不只是閱讀它們。"},{"en":"The phrase describes turning thought into visual art.","zh":"這個片語描述把思想轉化為視覺藝術。"}],"source":"66 - Salvador Dali.pdf","sourcePage":8},{"front":"the realm of the unconscious","meaning":"潛意識領域","examples":[{"en":"The realm of the unconscious became central to Surrealist art.","zh":"潛意識領域成為超現實主義藝術的核心。"},{"en":"The realm of the unconscious means the hidden part of the mind that contains dreams, fears, desires, and memories outside conscious control.","zh":"the realm of the unconscious 指心智中隱藏的部分，包含不受意識控制的夢、恐懼、慾望和記憶。"},{"en":"A strange dream may seem to come from the realm of the unconscious.","zh":"奇怪的夢可能看似來自潛意識領域。"},{"en":"If artists explore the unconscious, their images may appear illogical or dream-like.","zh":"如果藝術家探索潛意識，其圖像可能顯得不合邏輯或像夢一樣。"},{"en":"The phrase refers to hidden mental life.","zh":"這個片語指隱藏的心理生活。"}],"source":"66 - Salvador Dali.pdf","sourcePage":8},{"front":"be expressed through dreams","meaning":"透過夢境表達","examples":[{"en":"The unconscious was often expressed through dreams.","zh":"潛意識常透過夢境表達。"},{"en":"Be expressed through dreams means appear or be shown in dream images rather than direct speech.","zh":"be expressed through dreams 指透過夢中圖像而不是直接語言出現或被表現。"},{"en":"Anxiety may be expressed through dreams about missing an exam or losing a train.","zh":"焦慮可能透過夢見錯過考試或錯過火車來表達。"},{"en":"If hidden fears are expressed through dreams, artists may use dream scenes to show them.","zh":"如果隱藏恐懼透過夢境表達，藝術家可能使用夢境場景呈現它們。"},{"en":"The phrase connects inner feelings with dream imagery.","zh":"這個片語把內在感受與夢境意象連接起來。"}],"source":"66 - Salvador Dali.pdf","sourcePage":8},{"front":"become the content of","meaning":"成為……的內容","examples":[{"en":"Dreams became the content of these artists’ work.","zh":"夢境成為這些藝術家作品的內容。"},{"en":"Become the content of means become the subject matter or material used in something.","zh":"become the content of 指成為某事物使用的主題或材料。"},{"en":"A family memory may become the content of a student’s short story.","zh":"家庭記憶可能成為學生短篇故事的內容。"},{"en":"If dreams become the content of art, strange private images enter public paintings.","zh":"如果夢境成為藝術內容，奇異私人圖像就進入公共畫作。"},{"en":"The phrase describes what a work is mainly about.","zh":"這個片語描述作品主要關於甚麼。"}],"source":"66 - Salvador Dali.pdf","sourcePage":8},{"front":"international acclaim","meaning":"國際讚譽","examples":[{"en":"International acclaim followed shortly after.","zh":"國際讚譽不久後隨之而來。"},{"en":"International acclaim means praise and recognition from people or institutions in many countries.","zh":"international acclaim 指來自多個國家的人或機構的讚賞和認可。"},{"en":"A film may receive international acclaim after winning awards at overseas festivals.","zh":"電影在海外電影節得獎後可能獲得國際讚譽。"},{"en":"If an artist gains international acclaim, exhibitions and buyers may appear worldwide.","zh":"如果藝術家獲得國際讚譽，世界各地可能出現展覽和買家。"},{"en":"The phrase describes global praise.","zh":"這個片語描述全球性的讚賞。"}],"source":"66 - Salvador Dali.pdf","sourcePage":8},{"front":"follow shortly after","meaning":"不久後隨之而來","examples":[{"en":"International acclaim followed shortly after Dalí joined the Surrealist circle.","zh":"達利加入超現實主義圈子後不久，國際讚譽隨之而來。"},{"en":"Follow shortly after means happen soon after another event.","zh":"follow shortly after 指在另一事件後很快發生。"},{"en":"The exam results followed shortly after the final interview.","zh":"考試結果在最後面試後不久隨之而來。"},{"en":"If praise follows shortly after a major change, that change may have helped create success.","zh":"如果讚譽在重大改變後不久出現，該改變可能幫助創造成功。"},{"en":"The phrase links two events close in time.","zh":"這個片語把時間接近的兩件事連接起來。"}],"source":"66 - Salvador Dali.pdf","sourcePage":8},{"front":"solo exhibitions","meaning":"個人展覽","examples":[{"en":"Dalí enjoyed solo exhibitions in Paris and New York City.","zh":"達利在巴黎和紐約市舉行個人展覽。"},{"en":"Solo exhibitions are art shows featuring the work of one artist only.","zh":"solo exhibitions 指只展出一位藝術家作品的藝術展。"},{"en":"A young painter may dream of holding a solo exhibition in a respected gallery.","zh":"年輕畫家可能夢想在受尊重的畫廊舉行個人展覽。"},{"en":"If an artist receives solo exhibitions abroad, their reputation may grow quickly.","zh":"如果藝術家在海外獲得個人展覽，聲譽可能迅速增長。"},{"en":"The phrase contrasts one-person shows with group exhibitions.","zh":"這個片語把個展與群展作對比。"}],"source":"66 - Salvador Dali.pdf","sourcePage":8},{"front":"exhibition curator","meaning":"展覽策展人","examples":[{"en":"An exhibition curator described Dalí as a prominent figure.","zh":"一位展覽策展人把達利描述為重要人物。"},{"en":"An exhibition curator is a person who selects, organises, and explains artworks for an exhibition.","zh":"exhibition curator 指為展覽挑選、組織和解釋藝術品的人。"},{"en":"A curator may decide which paintings appear together in a museum room.","zh":"策展人可能決定哪些畫作一起出現在博物館展室中。"},{"en":"If a curator describes an artist as important, visitors may pay closer attention.","zh":"如果策展人把藝術家描述為重要人物，參觀者可能更留意。"},{"en":"The phrase refers to a professional who shapes how exhibitions are presented.","zh":"這個片語指塑造展覽呈現方式的專業人士。"}],"source":"66 - Salvador Dali.pdf","sourcePage":8},{"front":"as one curator put it","meaning":"正如一位策展人所說","examples":[{"en":"Dalí became, as one curator put it, a prominent figure in Surrealism.","zh":"正如一位策展人所說，達利成為超現實主義中的重要人物。"},{"en":"As one curator put it means in the words or opinion of one curator.","zh":"as one curator put it 指用一位策展人的說法或觀點來說。"},{"en":"The school hall became, as one teacher put it, the heart of the community.","zh":"正如一位老師所說，學校禮堂成為社區的心臟。"},{"en":"If a writer uses this phrase, they are bringing in another person’s wording.","zh":"如果作者使用這個片語，就是引入另一人的措辭。"},{"en":"The phrase introduces quoted or paraphrased judgement.","zh":"這個片語引出引用或轉述的判斷。"}],"source":"66 - Salvador Dali.pdf","sourcePage":8},{"front":"exotic and prominent figure","meaning":"異國情調濃厚而重要的人物","examples":[{"en":"Dalí became Surrealism’s most exotic and prominent figure.","zh":"達利成為超現實主義中最具異國情調而重要的人物。"},{"en":"An exotic and prominent figure is a highly noticeable person who seems unusual, colourful, or foreign in style.","zh":"exotic and prominent figure 指非常顯眼、風格不尋常、多彩或帶異國感的重要人物。"},{"en":"A musician with strange costumes and international fame may become an exotic and prominent figure.","zh":"穿着奇異服裝且享有國際聲譽的音樂人，可能成為異國情調濃厚而重要的人物。"},{"en":"If someone is prominent, people notice their influence; if exotic, they notice their unusual style.","zh":"如果某人 prominent，人們注意其影響力；如果 exotic，人們注意其不尋常風格。"},{"en":"The phrase combines importance with striking difference.","zh":"這個片語結合重要性和鮮明差異。"}],"source":"66 - Salvador Dali.pdf","sourcePage":8},{"front":"praise was heaped on","meaning":"大量讚譽加諸於……","examples":[{"en":"Praise continued to be heaped on Dalí.","zh":"大量讚譽繼續加諸於達利。"},{"en":"Praise was heaped on means a large amount of praise was given to someone.","zh":"praise was heaped on 指大量讚賞被給予某人。"},{"en":"Praise was heaped on the rescue workers after they saved families from the flood.","zh":"救援人員從水災中救出家庭後，大量讚譽加諸於他們。"},{"en":"If praise is heaped on an artist, their reputation may grow even faster.","zh":"如果大量讚譽加諸於藝術家，其聲譽可能更快增長。"},{"en":"The phrase suggests abundant public admiration.","zh":"這個片語暗示大量公眾欣賞。"}],"source":"66 - Salvador Dali.pdf","sourcePage":9},{"front":"poet and critic","meaning":"詩人兼評論家","examples":[{"en":"André Breton was a French poet and critic.","zh":"André Breton 是法國詩人兼評論家。"},{"en":"A poet and critic is someone who writes poetry and also evaluates art, literature, or culture.","zh":"poet and critic 指寫詩並評價藝術、文學或文化的人。"},{"en":"A poet and critic may both create works and judge the works of others.","zh":"詩人兼評論家既可能創作作品，也可能評論他人作品。"},{"en":"If a critic is also a poet, their judgement may come from creative experience.","zh":"如果評論家同時是詩人，其判斷可能來自創作經驗。"},{"en":"The phrase combines creative and analytical roles.","zh":"這個片語結合創作和分析角色。"}],"source":"66 - Salvador Dali.pdf","sourcePage":9},{"front":"the leader of the Surrealist movement","meaning":"超現實主義運動的領袖","examples":[{"en":"André Breton was the leader of the Surrealist movement.","zh":"André Breton 是超現實主義運動的領袖。"},{"en":"The leader of the Surrealist movement means the person who guided, organised, or shaped the movement’s ideas.","zh":"the leader of the Surrealist movement 指引導、組織或塑造該運動思想的人。"},{"en":"A movement’s leader may write statements, gather members, and define its goals.","zh":"運動領袖可能撰寫宣言、聚集成員並界定目標。"},{"en":"If Breton supported Dalí, that support carried artistic authority.","zh":"如果 Breton 支持達利，這種支持就帶有藝術權威。"},{"en":"The phrase identifies a central figure in an art movement.","zh":"這個片語指出藝術運動中的核心人物。"}],"source":"66 - Salvador Dali.pdf","sourcePage":9},{"front":"give someone his blessing","meaning":"給予某人支持；祝福","examples":[{"en":"Breton gave Dalí his blessing to continue promoting Surrealism.","zh":"Breton 給予達利支持，讓他繼續推動超現實主義。"},{"en":"Give someone his blessing means give approval, support, or permission.","zh":"give someone his blessing 指給予批准、支持或許可。"},{"en":"A teacher may give a student her blessing to enter an advanced competition.","zh":"老師可能支持學生參加進階比賽。"},{"en":"If a respected leader gives someone his blessing, others may accept that person more easily.","zh":"如果受尊重的領袖給予某人支持，其他人可能更容易接受那個人。"},{"en":"The phrase suggests approval from someone with authority.","zh":"這個片語暗示來自有權威者的認可。"}],"source":"66 - Salvador Dali.pdf","sourcePage":9},{"front":"carry the torch for","meaning":"繼承並推動……","examples":[{"en":"Dalí continued to carry the torch for the artistic movement.","zh":"達利繼續繼承並推動這個藝術運動。"},{"en":"Carry the torch for means continue to support, represent, or promote an idea or tradition.","zh":"carry the torch for 指繼續支持、代表或推動某理念或傳統。"},{"en":"A former student may carry the torch for a school charity after graduation.","zh":"畢業後，舊生可能繼續推動學校慈善計劃。"},{"en":"If one artist carries the torch for a movement, that movement stays visible to the public.","zh":"如果一位藝術家繼承並推動某運動，該運動就能繼續被公眾看見。"},{"en":"The phrase suggests continuing a mission after others began it.","zh":"這個片語暗示在他人開始後延續使命。"}],"source":"66 - Salvador Dali.pdf","sourcePage":9},{"front":"artistic movement","meaning":"藝術運動","examples":[{"en":"Surrealism was an influential artistic movement.","zh":"超現實主義是一個有影響力的藝術運動。"},{"en":"An artistic movement is a group of artists who share ideas, styles, or goals during a period.","zh":"artistic movement 指某時期分享思想、風格或目標的一群藝術家。"},{"en":"Impressionism was an artistic movement that changed how painters used light and colour.","zh":"印象派是一個改變畫家使用光線和色彩方式的藝術運動。"},{"en":"If an artistic movement becomes influential, it can change museums, teaching, and public taste.","zh":"如果藝術運動變得有影響力，它可以改變博物館、教學和公眾品味。"},{"en":"The phrase describes organised or shared change in art.","zh":"這個片語描述藝術中有組織或共同的變化。"}],"source":"66 - Salvador Dali.pdf","sourcePage":9},{"front":"synonymous with revelation","meaning":"等同於啟示","examples":[{"en":"Breton described Dalí’s name as synonymous with revelation.","zh":"Breton 把達利的名字描述為等同於啟示。"},{"en":"Synonymous with revelation means so closely linked with revealing hidden truth that the two seem almost the same.","zh":"synonymous with revelation 指與揭示隱藏真相非常密切相連，以致兩者幾乎相同。"},{"en":"A powerful documentary may become synonymous with revelation if it exposes a hidden public problem.","zh":"如果有力紀錄片揭露隱藏公共問題，它可能變得等同於啟示。"},{"en":"If an artist’s work reveals unconscious images, critics may connect that artist with revelation.","zh":"如果藝術家的作品揭示潛意識圖像，評論家可能把該藝術家與啟示連在一起。"},{"en":"The phrase is highly complimentary and abstract.","zh":"這個片語非常讚賞性且抽象。"}],"source":"66 - Salvador Dali.pdf","sourcePage":9},{"front":"in the most resplendent sense","meaning":"以最輝煌的意義來說","examples":[{"en":"Breton praised Dalí in the most resplendent sense of the word.","zh":"Breton 以這個詞最輝煌的意義讚賞達利。"},{"en":"In the most resplendent sense means in the most brilliant, glorious, or impressive meaning of a word.","zh":"in the most resplendent sense 指以某詞最燦爛、光輝或令人印象深刻的意思來說。"},{"en":"A teacher might call a student “brave” in the most resplendent sense after they defend a bullied classmate.","zh":"學生保護被欺凌同學後，老師可能以最輝煌的意義稱他為「勇敢」。"},{"en":"If praise is given in the most resplendent sense, it is meant as very high praise.","zh":"如果讚美以最輝煌的意義給出，就是非常高度的讚美。"},{"en":"The phrase sounds literary and strongly admiring.","zh":"這個片語帶文學感，並強烈表示欣賞。"}],"source":"66 - Salvador Dali.pdf","sourcePage":9},{"front":"surrealist paintings","meaning":"超現實主義畫作","examples":[{"en":"Dalí’s surrealist paintings were packed with symbolic imagery.","zh":"達利的超現實主義畫作充滿象徵意象。"},{"en":"Surrealist paintings are paintings that show dream-like, strange, or unconscious images rather than ordinary reality.","zh":"surrealist paintings 指呈現夢境般、奇異或潛意識圖像，而不是普通現實的畫作。"},{"en":"A surrealist painting may show a clock melting over a tree branch.","zh":"超現實主義畫作可能展示時鐘在樹枝上融化。"},{"en":"If viewers see impossible scenes in a painting, the work may feel surrealist.","zh":"如果觀眾在畫中看見不可能的場景，作品可能感覺很超現實。"},{"en":"The phrase refers to paintings connected with Surrealism.","zh":"這個片語指與超現實主義有關的畫作。"}],"source":"66 - Salvador Dali.pdf","sourcePage":9},{"front":"be packed with","meaning":"充滿","examples":[{"en":"Dalí’s paintings were packed with Freudian imagery.","zh":"達利的畫作充滿佛洛伊德式意象。"},{"en":"Be packed with means be full of many examples of something.","zh":"be packed with 指充滿許多某事物的例子。"},{"en":"A good study guide is packed with examples, explanations, and practice questions.","zh":"好的學習指南充滿例子、解釋和練習題。"},{"en":"If a painting is packed with symbols, viewers may need time to interpret it.","zh":"如果畫作充滿象徵，觀眾可能需要時間解讀。"},{"en":"The phrase suggests a large amount in a limited space.","zh":"這個片語暗示有限空間中有大量內容。"}],"source":"66 - Salvador Dali.pdf","sourcePage":9},{"front":"Freudian imagery","meaning":"佛洛伊德式意象","examples":[{"en":"Dalí’s paintings were packed with Freudian imagery.","zh":"達利的畫作充滿佛洛伊德式意象。"},{"en":"Freudian imagery means images connected with Freud’s ideas about dreams, desire, fear, and the unconscious mind.","zh":"Freudian imagery 指與佛洛伊德關於夢、慾望、恐懼和潛意識思想相關的圖像。"},{"en":"A film using locked doors, strange dreams, and hidden childhood memories may contain Freudian imagery.","zh":"使用鎖住的門、奇怪夢境和隱藏童年記憶的電影，可能包含佛洛伊德式意象。"},{"en":"If a painting includes symbols of hidden desire, critics may call it Freudian.","zh":"如果畫作包含隱藏慾望的象徵，評論家可能稱它為佛洛伊德式。"},{"en":"The phrase connects visual symbols with psychoanalysis.","zh":"這個片語把視覺象徵與精神分析連接起來。"}],"source":"66 - Salvador Dali.pdf","sourcePage":10},{"front":"dripping candles","meaning":"滴蠟的蠟燭","examples":[{"en":"Dripping candles appeared in Dalí’s surrealist paintings.","zh":"滴蠟的蠟燭出現在達利的超現實主義畫作中。"},{"en":"Dripping candles are candles with melted wax running down their sides.","zh":"dripping candles 指融化蠟液沿邊流下的蠟燭。"},{"en":"A dinner table with dripping candles may look old-fashioned, mysterious, or dramatic.","zh":"有滴蠟蠟燭的餐桌可能看起來古舊、神秘或戲劇化。"},{"en":"If dripping candles appear in a painting, they can suggest time, decay, or uneasy atmosphere.","zh":"如果滴蠟的蠟燭出現在畫中，它們可以暗示時間、腐朽或不安氣氛。"},{"en":"The phrase names a visual object often rich in mood.","zh":"這個片語指一種常帶豐富氣氛的視覺物件。"}],"source":"66 - Salvador Dali.pdf","sourcePage":10},{"front":"in addition to","meaning":"除了……之外","examples":[{"en":"Dalí used staircases and keys in addition to personal symbols.","zh":"除了個人象徵之外，達利也使用樓梯和鑰匙。"},{"en":"In addition to means as well as or besides something already mentioned.","zh":"in addition to 指除了已提及的事物之外，也包括另一事物。"},{"en":"In addition to homework, students should read books for pleasure.","zh":"除了功課之外，學生也應為興趣閱讀書本。"},{"en":"If an artist uses public symbols in addition to private ones, the work may have several layers.","zh":"如果藝術家除了私人象徵外也使用公共象徵，作品可能有幾個層次。"},{"en":"The phrase adds another item or category.","zh":"這個片語加入另一項或類別。"}],"source":"66 - Salvador Dali.pdf","sourcePage":10},{"front":"a host of","meaning":"大量","examples":[{"en":"Dalí’s paintings contained a host of personal symbols.","zh":"達利的畫作包含大量個人象徵。"},{"en":"A host of means a large number of something.","zh":"a host of 指大量某事物。"},{"en":"A busy school office deals with a host of forms, calls, and parent questions each day.","zh":"繁忙校務處每天處理大量表格、電話和家長問題。"},{"en":"If a painting contains a host of symbols, viewers may interpret it in many ways.","zh":"如果畫作包含大量象徵，觀眾可能以許多方式解讀它。"},{"en":"The phrase suggests abundance.","zh":"這個片語暗示數量豐富。"}],"source":"66 - Salvador Dali.pdf","sourcePage":10},{"front":"personally significant symbols","meaning":"具有個人意義的象徵","examples":[{"en":"Grasshoppers and ants were personally significant symbols for Dalí.","zh":"蚱蜢和螞蟻對達利而言是具有個人意義的象徵。"},{"en":"Personally significant symbols are images that carry special private meaning for one person.","zh":"personally significant symbols 指對某個人帶有特殊私人意義的圖像。"},{"en":"A broken watch may be a personally significant symbol for someone who remembers a family loss.","zh":"對記得家庭失去的人而言，破手錶可能是具有個人意義的象徵。"},{"en":"If artists use personally significant symbols, viewers may need background knowledge to understand them.","zh":"如果藝術家使用具有個人意義的象徵，觀眾可能需要背景知識才能理解。"},{"en":"The phrase links visual signs with private meaning.","zh":"這個片語把視覺符號與私人意義連接起來。"}],"source":"66 - Salvador Dali.pdf","sourcePage":10},{"front":"grasshoppers and ants","meaning":"蚱蜢和螞蟻","examples":[{"en":"Grasshoppers and ants appeared as symbols in Dalí’s paintings.","zh":"蚱蜢和螞蟻作為象徵出現在達利畫作中。"},{"en":"Grasshoppers and ants are insects that Dalí used as repeated symbolic images.","zh":"grasshoppers and ants 是達利用作重複象徵圖像的昆蟲。"},{"en":"A child may see grasshoppers and ants in a garden, but in art they can carry hidden meaning.","zh":"孩子可能在花園中看到蚱蜢和螞蟻，但在藝術中它們可以帶有隱藏意思。"},{"en":"If insects appear repeatedly in an artist’s work, they may represent fear, decay, or memory.","zh":"如果昆蟲反覆出現在藝術家作品中，它們可能代表恐懼、腐朽或記憶。"},{"en":"The phrase names small creatures that became part of Dalí’s visual language.","zh":"這個片語指成為達利視覺語言一部分的小生物。"}],"source":"66 - Salvador Dali.pdf","sourcePage":10},{"front":"capture his phobias on canvas","meaning":"在畫布上呈現他的恐懼症","examples":[{"en":"Dalí captured his phobias on canvas through symbolic images.","zh":"達利透過象徵圖像在畫布上呈現他的恐懼症。"},{"en":"Capture his phobias on canvas means express his deep fears in paintings.","zh":"capture his phobias on canvas 指在畫作中表達他的深層恐懼。"},{"en":"A painter may capture fear on canvas by showing dark rooms, insects, or distorted faces.","zh":"畫家可能透過黑暗房間、昆蟲或扭曲面孔在畫布上呈現恐懼。"},{"en":"If an artist paints personal fears, the canvas becomes a place for emotional expression.","zh":"如果藝術家畫出個人恐懼，畫布就成為情感表達的地方。"},{"en":"The phrase connects psychological fear with visual art.","zh":"這個片語把心理恐懼與視覺藝術連接起來。"}],"source":"66 - Salvador Dali.pdf","sourcePage":10},{"front":"phobias","meaning":"恐懼症","examples":[{"en":"Dalí used insects to represent his phobias.","zh":"達利用昆蟲代表他的恐懼症。"},{"en":"Phobias are strong and often irrational fears of particular objects, situations, or creatures.","zh":"phobias 指對特定物件、情況或生物的強烈且常不理性的恐懼。"},{"en":"A person with a phobia of heights may avoid bridges and tall buildings.","zh":"有畏高恐懼症的人可能避開橋和高樓。"},{"en":"If a phobia appears in art, it may be shown through repeated frightening images.","zh":"如果恐懼症出現在藝術中，可能透過反覆出現的可怕圖像呈現。"},{"en":"The word describes intense fear, not ordinary dislike.","zh":"這個詞描述強烈恐懼，而不是普通討厭。"}],"source":"66 - Salvador Dali.pdf","sourcePage":10},{"front":"on canvas","meaning":"在畫布上","examples":[{"en":"Dalí expressed his fears on canvas.","zh":"達利在畫布上表達他的恐懼。"},{"en":"On canvas means in a painting, especially one made on cloth stretched over a frame.","zh":"on canvas 指在畫作中，尤其是在繃在畫框上的布面上。"},{"en":"A student may show memories of home on canvas through colour and shape.","zh":"學生可能透過顏色和形狀在畫布上呈現家的記憶。"},{"en":"If emotions appear on canvas, private feelings become visible to viewers.","zh":"如果情感出現在畫布上，私人感受就變得可被觀眾看見。"},{"en":"The phrase is often used to talk about painted expression.","zh":"這個片語常用於談繪畫表達。"}],"source":"66 - Salvador Dali.pdf","sourcePage":10},{"front":"overt adulation for","meaning":"對……公開表現出崇拜","examples":[{"en":"Dalí showed overt adulation for Freud.","zh":"達利公開表現出對佛洛伊德的崇拜。"},{"en":"Overt adulation for means open and obvious extreme admiration for someone.","zh":"overt adulation for 指公開而明顯地對某人表現極度崇拜。"},{"en":"Fans may show overt adulation for a singer by cheering, crying, and copying their style.","zh":"粉絲可能透過歡呼、哭泣和模仿風格，公開表現對歌手的崇拜。"},{"en":"If admiration becomes too intense, it may make the admired person uncomfortable.","zh":"如果崇拜變得過於強烈，可能令被崇拜者不舒服。"},{"en":"The phrase suggests admiration that is very visible and perhaps excessive.","zh":"這個片語暗示非常可見且可能過度的欣賞。"}],"source":"66 - Salvador Dali.pdf","sourcePage":10},{"front":"psychoanalysis","meaning":"精神分析學","examples":[{"en":"Freud was a major figure in psychoanalysis.","zh":"佛洛伊德是精神分析學的重要人物。"},{"en":"Psychoanalysis is a theory and method of exploring the unconscious mind, dreams, and hidden mental conflicts.","zh":"psychoanalysis 是探索潛意識、夢境和隱藏心理衝突的理論和方法。"},{"en":"Literature students may use psychoanalysis to interpret a character’s strange fears.","zh":"文學學生可能使用精神分析學解讀角色的奇怪恐懼。"},{"en":"If art is influenced by psychoanalysis, it may focus on dreams and buried desires.","zh":"如果藝術受精神分析學影響，可能集中於夢境和被埋藏的慾望。"},{"en":"The word refers to both a psychological theory and a method of interpretation.","zh":"這個詞同時指心理學理論和詮釋方法。"}],"source":"66 - Salvador Dali.pdf","sourcePage":11},{"front":"prove somewhat unfortunate","meaning":"結果有點不幸","examples":[{"en":"Dalí’s meeting with Freud proved somewhat unfortunate.","zh":"達利與佛洛伊德的會面結果有點不幸。"},{"en":"Prove somewhat unfortunate means later turn out to be rather unlucky, awkward, or disappointing.","zh":"prove somewhat unfortunate 指後來顯得有點不走運、尷尬或令人失望。"},{"en":"Inviting two rivals to the same meeting proved somewhat unfortunate when they began arguing.","zh":"邀請兩名對手參加同一會議，當他們開始爭吵時證明有點不幸。"},{"en":"If a meeting goes badly, it may damage admiration rather than deepen respect.","zh":"如果會面進展不佳，可能損害崇拜而不是加深尊重。"},{"en":"The phrase is understated and polite.","zh":"這個片語語氣含蓄而禮貌。"}],"source":"66 - Salvador Dali.pdf","sourcePage":11},{"front":"on the occasion that","meaning":"在……的場合","examples":[{"en":"On the occasion that Dalí met Freud, he began to sketch him.","zh":"在達利見到佛洛伊德的場合，他開始為他素描。"},{"en":"On the occasion that means at the time when a particular event happened.","zh":"on the occasion that 指在某特定事件發生的時候。"},{"en":"On the occasion that the school opened its new library, students performed a short play.","zh":"在學校開設新圖書館的場合，學生表演了一齣短劇。"},{"en":"If someone behaves strangely on an important occasion, people may remember the moment clearly.","zh":"如果某人在重要場合表現奇怪，人們可能清楚記住那一刻。"},{"en":"The phrase is formal and refers to a specific event.","zh":"這個片語較正式，指特定事件。"}],"source":"66 - Salvador Dali.pdf","sourcePage":11},{"front":"proceed to","meaning":"接着去做","examples":[{"en":"Dalí proceeded to sketch Freud in earnest.","zh":"達利接着認真為佛洛伊德素描。"},{"en":"Proceed to means continue by doing the next action.","zh":"proceed to 指繼續做下一個行動。"},{"en":"After explaining the rules, the teacher proceeded to give students a practice task.","zh":"老師解釋規則後，接着給學生練習任務。"},{"en":"If someone proceeds to act without reading the room, the action may feel awkward.","zh":"如果某人沒有看清氣氛便接着行動，該行動可能顯得尷尬。"},{"en":"The phrase shows the next step in a sequence.","zh":"這個片語顯示一連串行動中的下一步。"}],"source":"66 - Salvador Dali.pdf","sourcePage":11},{"front":"sketch someone","meaning":"為某人素描","examples":[{"en":"Dalí sketched Freud during their meeting.","zh":"達利在會面期間為佛洛伊德素描。"},{"en":"Sketch someone means make a quick drawing of a person.","zh":"sketch someone 指快速畫出某人的圖像。"},{"en":"An art student may sketch a classmate to practise drawing faces.","zh":"藝術學生可能為同學素描，以練習畫面孔。"},{"en":"If an artist sketches someone during a conversation, the action may feel flattering or intrusive.","zh":"如果藝術家在談話期間為某人素描，這個行動可能令人感到受重視或被打擾。"},{"en":"The phrase refers to drawing, usually quickly and by hand.","zh":"這個片語指畫畫，通常是快速而手繪。"}],"source":"66 - Salvador Dali.pdf","sourcePage":11},{"front":"the latter","meaning":"後者","examples":[{"en":"Dalí met Freud and proceeded to sketch the latter.","zh":"達利見到佛洛伊德後，接着為後者素描。"},{"en":"The latter means the second of two people or things just mentioned.","zh":"the latter 指剛提到的兩個人或事物中的第二個。"},{"en":"Tom and Ben joined the race, but the latter finished first.","zh":"Tom 和 Ben 參加比賽，但後者先完成。"},{"en":"If a sentence mentions two names, the latter refers to the second one.","zh":"如果句子提到兩個名字，the latter 指第二個名字。"},{"en":"The phrase helps avoid repeating a name.","zh":"這個片語幫助避免重複名字。"}],"source":"66 - Salvador Dali.pdf","sourcePage":11},{"front":"in earnest","meaning":"認真地","examples":[{"en":"Dalí sketched Freud in earnest.","zh":"達利認真地為佛洛伊德素描。"},{"en":"In earnest means seriously, sincerely, and with real effort.","zh":"in earnest 指嚴肅、真誠並投入真實努力地。"},{"en":"A student begins revision in earnest when they make a plan and practise daily.","zh":"當學生制定計劃並每天練習，就開始認真地溫習。"},{"en":"If someone works in earnest, the task is no longer just casual or playful.","zh":"如果某人認真做事，該任務就不再只是隨意或玩票。"},{"en":"The phrase shows serious commitment.","zh":"這個片語顯示認真投入。"}],"source":"66 - Salvador Dali.pdf","sourcePage":11},{"front":"fervid attitude","meaning":"狂熱的態度","examples":[{"en":"Dalí’s fervid attitude alarmed Freud.","zh":"達利的狂熱態度令佛洛伊德感到不安。"},{"en":"A fervid attitude is an extremely intense, passionate, or overexcited way of behaving.","zh":"fervid attitude 指非常強烈、熱情或過度興奮的行為方式。"},{"en":"A fan with a fervid attitude may make a celebrity uncomfortable by standing too close and talking too fast.","zh":"狂熱粉絲可能站得太近、說得太快，令名人不舒服。"},{"en":"If enthusiasm becomes too fervid, it can seem alarming rather than flattering.","zh":"如果熱情變得太狂熱，它可能顯得令人不安，而不是令人受寵。"},{"en":"The phrase suggests emotional intensity that may feel excessive.","zh":"這個片語暗示可能過度的情感強度。"}],"source":"66 - Salvador Dali.pdf","sourcePage":11},{"front":"alarm the psychoanalyst","meaning":"令精神分析學家感到不安","examples":[{"en":"Dalí’s behaviour seemed to alarm the psychoanalyst.","zh":"達利的行為似乎令這位精神分析學家感到不安。"},{"en":"Alarm the psychoanalyst means make the psychoanalyst feel worried, uneasy, or disturbed.","zh":"alarm the psychoanalyst 指令精神分析學家感到擔心、不安或受困擾。"},{"en":"A patient’s sudden confusion may alarm a doctor during an examination.","zh":"病人在檢查期間突然混亂，可能令醫生感到不安。"},{"en":"If someone’s admiration becomes intense and strange, it may alarm the person being admired.","zh":"如果某人的崇拜變得強烈而奇怪，可能令被崇拜者感到不安。"},{"en":"The phrase shows that behaviour creates concern.","zh":"這個片語顯示行為引起憂慮。"}],"source":"66 - Salvador Dali.pdf","sourcePage":11},{"front":"be said to have","meaning":"據說曾經","examples":[{"en":"Freud is said to have described Dalí as a fanatic.","zh":"據說佛洛伊德曾把達利描述為狂熱分子。"},{"en":"Be said to have means people report or claim that someone did something, though the writer may not prove it directly.","zh":"be said to have 指有人報稱或聲稱某人做過某事，但作者未必直接證明。"},{"en":"The old teacher is said to have helped hundreds of poor students.","zh":"據說那位老老師曾幫助數百名貧困學生。"},{"en":"If a story is introduced this way, it may be based on reported speech or tradition.","zh":"如果故事用這種方式引入，可能基於轉述或傳聞。"},{"en":"The phrase keeps some distance from the claim.","zh":"這個片語與主張保持一定距離。"}],"source":"66 - Salvador Dali.pdf","sourcePage":11},{"front":"whisper to others","meaning":"向其他人低聲說","examples":[{"en":"Freud whispered to others in the room.","zh":"佛洛伊德向房間內其他人低聲說話。"},{"en":"Whisper to others means speak very quietly to other people so not everyone hears.","zh":"whisper to others 指非常小聲地對其他人說話，使不是所有人都聽見。"},{"en":"Students may whisper to others during a group activity, but not during a test.","zh":"學生在小組活動期間可能向其他人低聲說話，但考試期間不可以。"},{"en":"If someone whispers during a meeting, others may wonder what is being said.","zh":"如果某人在會議中低聲說話，其他人可能想知道他說甚麼。"},{"en":"The phrase describes quiet private speech.","zh":"這個片語描述安靜的私人說話。"}],"source":"66 - Salvador Dali.pdf","sourcePage":12},{"front":"look like a fanatic","meaning":"看起來像狂熱分子","examples":[{"en":"Freud reportedly thought Dalí looked like a fanatic.","zh":"據報佛洛伊德認為達利看起來像狂熱分子。"},{"en":"Look like a fanatic means appear extremely intense, obsessive, or irrationally devoted.","zh":"look like a fanatic 指看起來極端強烈、沉迷或不理性地投入。"},{"en":"A supporter who shouts at everyone may look like a fanatic rather than a calm admirer.","zh":"對所有人大喊的支持者可能看起來像狂熱分子，而不是冷靜欣賞者。"},{"en":"If passion appears uncontrolled, people may judge it as fanaticism.","zh":"如果熱情顯得失控，人們可能把它判斷為狂熱。"},{"en":"The phrase describes impression, not necessarily the truth about someone.","zh":"這個片語描述印象，而不一定是真相。"}],"source":"66 - Salvador Dali.pdf","sourcePage":12},{"front":"come across as","meaning":"給人……的印象","examples":[{"en":"Dalí sometimes came across as mad and unintelligible.","zh":"達利有時給人瘋狂而難以理解的印象。"},{"en":"Come across as means give people a particular impression.","zh":"come across as 指給人某種印象。"},{"en":"A quiet student may come across as unfriendly, even if they are just shy.","zh":"安靜學生可能給人不友善的印象，即使他只是害羞。"},{"en":"If an artist behaves dramatically, they may come across as eccentric or arrogant.","zh":"如果藝術家行為戲劇化，可能給人古怪或傲慢的印象。"},{"en":"The phrase focuses on how others perceive someone.","zh":"這個片語集中於他人如何感知某人。"}],"source":"66 - Salvador Dali.pdf","sourcePage":12},{"front":"unintelligible","meaning":"難以理解的","examples":[{"en":"Some of Dalí’s paintings seemed unintelligible to viewers.","zh":"達利的一些畫作對觀眾而言似乎難以理解。"},{"en":"Unintelligible means impossible or very difficult to understand.","zh":"unintelligible 指無法理解或非常難理解。"},{"en":"A message with too many mistakes may be unintelligible to the reader.","zh":"如果訊息錯誤太多，讀者可能難以理解。"},{"en":"If a painting has private symbols, viewers without context may find it unintelligible.","zh":"如果畫作有私人象徵，沒有背景的觀眾可能覺得難以理解。"},{"en":"The word describes lack of clear meaning.","zh":"這個詞描述意思不清晰。"}],"source":"66 - Salvador Dali.pdf","sourcePage":12},{"front":"as far as something is concerned","meaning":"就……而言","examples":[{"en":"Dalí’s paintings were sometimes unintelligible as far as viewers were concerned.","zh":"就觀眾而言，達利的畫作有時難以理解。"},{"en":"As far as something is concerned means from the viewpoint of a particular person, group, or issue.","zh":"as far as something is concerned 指從某個人、群體或議題的角度來看。"},{"en":"As far as parents are concerned, school safety matters more than decoration.","zh":"就家長而言，學校安全比裝飾更重要。"},{"en":"If viewers are concerned, a work may feel confusing even if experts understand it.","zh":"就觀眾而言，即使專家理解某作品，它仍可能令人困惑。"},{"en":"The phrase limits a statement to a particular perspective.","zh":"這個片語把陳述限制於特定角度。"}],"source":"66 - Salvador Dali.pdf","sourcePage":12},{"front":"The Persistence of Memory","meaning":"《記憶的堅持》","examples":[{"en":"The Persistence of Memory is one of Dalí’s most famous works.","zh":"《記憶的堅持》是達利最著名的作品之一。"},{"en":"The Persistence of Memory is the title of Dalí’s painting best known for its melting clocks.","zh":"The Persistence of Memory 是達利一幅以融化時鐘最為人熟知的畫作標題。"},{"en":"Art teachers often use The Persistence of Memory to introduce Surrealism to students.","zh":"藝術老師常用《記憶的堅持》向學生介紹超現實主義。"},{"en":"If a single painting becomes famous worldwide, it can shape how people remember an artist.","zh":"如果一幅畫在全球成名，它可以塑造人們如何記住藝術家。"},{"en":"The title is closely linked with Dalí’s exploration of time, memory, and dream imagery.","zh":"這個標題與達利對時間、記憶和夢境意象的探索密切相關。"}],"source":"66 - Salvador Dali.pdf","sourcePage":12},{"front":"be singled out for","meaning":"因……而被特別指出","examples":[{"en":"The painting was singled out for the confusion it caused.","zh":"這幅畫因造成困惑而被特別指出。"},{"en":"Be singled out for means be specially noticed or mentioned because of a particular reason.","zh":"be singled out for 指因某特定原因而被特別注意或提及。"},{"en":"A student may be singled out for excellent improvement in reading.","zh":"學生可能因閱讀進步出色而被特別表揚。"},{"en":"If a painting causes unusual confusion, critics may single it out for discussion.","zh":"如果一幅畫造成異常困惑，評論家可能把它特別提出討論。"},{"en":"The phrase shows that one example is chosen from many.","zh":"這個片語顯示從許多例子中選出一個。"}],"source":"66 - Salvador Dali.pdf","sourcePage":12},{"front":"sheer confusion","meaning":"極大的困惑","examples":[{"en":"The painting caused sheer confusion among viewers.","zh":"這幅畫在觀眾之中造成極大的困惑。"},{"en":"Sheer confusion means complete or very strong confusion.","zh":"sheer confusion 指完全或非常強烈的困惑。"},{"en":"A badly written exam instruction can cause sheer confusion in the classroom.","zh":"寫得很差的考試指示可以在課室中造成極大困惑。"},{"en":"If viewers cannot connect the symbols, a painting may leave them in sheer confusion.","zh":"如果觀眾無法連接象徵，畫作可能令他們極度困惑。"},{"en":"The phrase intensifies the feeling of not understanding.","zh":"這個片語加強「不理解」的感覺。"}],"source":"66 - Salvador Dali.pdf","sourcePage":12},{"front":"amongst its viewers","meaning":"在觀眾之中","examples":[{"en":"The work caused confusion amongst its viewers.","zh":"這件作品在觀眾之中造成困惑。"},{"en":"Amongst its viewers means within the group of people who looked at or watched the work.","zh":"amongst its viewers 指在觀看該作品的人群之中。"},{"en":"A film ending may create debate amongst its viewers after the lights come on.","zh":"電影結局可能在燈亮後於觀眾之中引起討論。"},{"en":"If a work is difficult, confusion may spread amongst viewers who lack background knowledge.","zh":"如果作品很困難，缺乏背景知識的觀眾之中可能出現困惑。"},{"en":"The phrase identifies the audience affected.","zh":"這個片語指出受影響的觀眾群體。"}],"source":"66 - Salvador Dali.pdf","sourcePage":12},{"front":"feature melting clocks","meaning":"以融化時鐘為特色","examples":[{"en":"The painting features melting clocks and swarming ants.","zh":"這幅畫以融化時鐘和成群螞蟻為特色。"},{"en":"Feature melting clocks means include melting clocks as a noticeable part of the work.","zh":"feature melting clocks 指把融化時鐘作為作品中明顯的一部分。"},{"en":"A poster may feature a large red question mark to attract attention.","zh":"海報可能以大型紅色問號為特色來吸引注意。"},{"en":"If a painting features an unforgettable image, viewers may remember that image before the title.","zh":"如果畫作以令人難忘的形象為特色，觀眾可能先記住該形象而不是標題。"},{"en":"The phrase describes what appears prominently in a work.","zh":"這個片語描述作品中突出出現的內容。"}],"source":"66 - Salvador Dali.pdf","sourcePage":12},{"front":"swarming ants","meaning":"成群螞蟻","examples":[{"en":"Swarming ants appear in The Persistence of Memory.","zh":"成群螞蟻出現在《記憶的堅持》中。"},{"en":"Swarming ants are ants gathered or moving in a large active group.","zh":"swarming ants 指大量聚集或活躍移動的螞蟻。"},{"en":"A kitchen with spilled sugar may soon have swarming ants near the floor.","zh":"撒了糖的廚房地板附近可能很快有成群螞蟻。"},{"en":"If swarming ants appear in a painting, they may suggest decay, anxiety, or hidden fear.","zh":"如果成群螞蟻出現在畫中，它們可能暗示腐朽、焦慮或隱藏恐懼。"},{"en":"The phrase gives an image of many insects moving together.","zh":"這個片語給出許多昆蟲一起移動的圖像。"}],"source":"66 - Salvador Dali.pdf","sourcePage":13},{"front":"a mollusc","meaning":"軟體動物","examples":[{"en":"A mollusc appeared as a strange image in the painting.","zh":"軟體動物作為奇怪圖像出現在畫中。"},{"en":"A mollusc is a soft-bodied animal such as a snail, clam, or octopus.","zh":"mollusc 是蝸牛、蛤或章魚等軟身動物。"},{"en":"Children may see a mollusc on a beach when they find a shell or snail.","zh":"孩子在海灘找到貝殼或蝸牛時，可能看見軟體動物。"},{"en":"If a mollusc appears in a surrealist painting, it may represent something symbolic rather than biological.","zh":"如果軟體動物出現在超現實主義畫作中，它可能代表象徵，而不只是生物。"},{"en":"The word names a kind of animal with a soft body.","zh":"這個詞指一種軟身動物。"}],"source":"66 - Salvador Dali.pdf","sourcePage":13},{"front":"the deflated head of","meaning":"……洩氣般的頭部","examples":[{"en":"The mollusc represented the deflated head of Dalí.","zh":"軟體動物代表達利洩氣般的頭部。"},{"en":"The deflated head of someone means a head shown as soft, collapsed, or lacking normal firmness.","zh":"the deflated head of someone 指某人的頭被呈現得柔軟、塌陷或失去正常堅實感。"},{"en":"A cartoon may show the deflated head of a tired worker to suggest exhaustion.","zh":"卡通可能畫出疲倦工人洩氣般的頭部，以暗示精疲力竭。"},{"en":"If a face is painted as deflated, it may suggest weakness, dream, or loss of energy.","zh":"如果臉被畫成洩氣般，可能暗示脆弱、夢境或失去能量。"},{"en":"The phrase describes a distorted symbolic image.","zh":"這個片語描述扭曲的象徵圖像。"}],"source":"66 - Salvador Dali.pdf","sourcePage":13},{"front":"in disguise","meaning":"偽裝成","examples":[{"en":"The mollusc was Dalí’s deflated head in disguise.","zh":"這個軟體動物是偽裝成達利洩氣般的頭部。"},{"en":"In disguise means hidden under another appearance or form.","zh":"in disguise 指隱藏在另一種外表或形式之下。"},{"en":"A police officer in disguise may dress like an ordinary customer.","zh":"偽裝的警員可能穿得像普通顧客。"},{"en":"If a symbol is a portrait in disguise, viewers may not recognise it immediately.","zh":"如果某象徵是偽裝成肖像，觀眾可能不會立即認出。"},{"en":"The phrase suggests concealed identity.","zh":"這個片語暗示身份被隱藏。"}],"source":"66 - Salvador Dali.pdf","sourcePage":13},{"front":"puzzling","meaning":"令人費解的","examples":[{"en":"The images in the painting were extremely puzzling.","zh":"畫中的圖像極其令人費解。"},{"en":"Puzzling means confusing and difficult to understand or explain.","zh":"puzzling 指令人困惑，難以理解或解釋。"},{"en":"A teacher’s sudden silence may be puzzling if students do not know what happened.","zh":"如果學生不知道發生甚麼，老師突然沉默可能令人費解。"},{"en":"If a painting has unrelated objects in one scene, viewers may find it puzzling.","zh":"如果畫中在同一場景放入不相關物件，觀眾可能覺得令人費解。"},{"en":"The word describes something that makes people ask questions.","zh":"這個詞描述令人提出疑問的事物。"}],"source":"66 - Salvador Dali.pdf","sourcePage":13},{"front":"urge readers to","meaning":"敦促讀者去","examples":[{"en":"One critic urged readers to consult Freud for the meaning of the painting.","zh":"一位評論家敦促讀者去查閱佛洛伊德，以理解畫作意思。"},{"en":"Urge readers to means strongly encourage readers to do something.","zh":"urge readers to 指強烈鼓勵讀者做某事。"},{"en":"A health article may urge readers to see a doctor if symptoms last for weeks.","zh":"健康文章可能敦促讀者在症狀持續數週時求醫。"},{"en":"If a critic urges readers to consult another source, the work may be difficult to interpret alone.","zh":"如果評論家敦促讀者查閱另一來源，該作品可能難以單獨解讀。"},{"en":"The phrase suggests strong advice.","zh":"這個片語暗示強烈建議。"}],"source":"66 - Salvador Dali.pdf","sourcePage":13},{"front":"uncover the meaning of","meaning":"揭示……的意思","examples":[{"en":"The critic wanted readers to uncover the meaning of the canvas.","zh":"評論家希望讀者揭示這幅畫的意思。"},{"en":"Uncover the meaning of means discover or reveal what something really means.","zh":"uncover the meaning of 指發現或揭示某事真正意思。"},{"en":"Students may uncover the meaning of a poem by looking at repeated images.","zh":"學生可能透過查看重複圖像來揭示詩的意思。"},{"en":"If a painting uses private symbols, uncovering its meaning may require background knowledge.","zh":"如果畫作使用私人象徵，揭示其意思可能需要背景知識。"},{"en":"The phrase suggests meaning is hidden and must be found.","zh":"這個片語暗示意思被隱藏，需要被找出。"}],"source":"66 - Salvador Dali.pdf","sourcePage":13},{"front":"the canvas","meaning":"畫作；畫布","examples":[{"en":"The critic wanted to uncover the meaning of the canvas.","zh":"評論家想揭示這幅畫作的意思。"},{"en":"The canvas can mean the painted work itself, especially a painting made on canvas cloth.","zh":"the canvas 可指畫作本身，尤其是畫在畫布上的作品。"},{"en":"A museum label may explain the story behind the canvas on the wall.","zh":"博物館標籤可能解釋牆上那幅畫作背後的故事。"},{"en":"If a canvas is full of symbols, viewers may study it slowly.","zh":"如果畫作充滿象徵，觀眾可能慢慢研究。"},{"en":"The word can refer to both the physical surface and the artwork.","zh":"這個詞既可指實體表面，也可指藝術作品。"}],"source":"66 - Salvador Dali.pdf","sourcePage":13},{"front":"if nothing else","meaning":"至少；不管怎樣","examples":[{"en":"His work was, if nothing else, provocative and powerful.","zh":"他的作品至少具挑釁性而有震撼力。"},{"en":"If nothing else means at least this is true, even if nothing more can be agreed.","zh":"if nothing else 指即使其他都不能同意，至少這一點是真的。"},{"en":"The lesson was difficult, but if nothing else, it made students think.","zh":"這堂課很難，但至少它令學生思考。"},{"en":"If critics disagree about beauty, they may still admit a work is memorable.","zh":"如果評論家對美感意見不同，他們仍可能承認作品令人難忘。"},{"en":"The phrase gives a minimum judgement.","zh":"這個片語給出最低限度的判斷。"}],"source":"66 - Salvador Dali.pdf","sourcePage":13},{"front":"provocative and powerful","meaning":"具挑釁性而有震撼力","examples":[{"en":"Dalí’s work was provocative and powerful.","zh":"達利的作品具挑釁性而有震撼力。"},{"en":"Provocative and powerful means strongly affecting viewers and making them think, react, or feel disturbed.","zh":"provocative and powerful 指強烈影響觀眾，令他們思考、反應或感到不安。"},{"en":"A poster about climate change can be provocative and powerful if it shows real families affected by floods.","zh":"如果氣候變化海報展示受水災影響的真實家庭，它可以具挑釁性而有震撼力。"},{"en":"If art is provocative, some people may dislike it; if powerful, they still remember it.","zh":"如果藝術具挑釁性，有些人可能不喜歡；如果有震撼力，他們仍會記得。"},{"en":"The phrase combines emotional force with challenge.","zh":"這個片語結合情感力量與挑戰性。"}],"source":"66 - Salvador Dali.pdf","sourcePage":13},{"front":"with the passing years","meaning":"隨着歲月流逝","examples":[{"en":"With the passing years, Dalí became more interested in money.","zh":"隨着歲月流逝，達利變得更關心金錢。"},{"en":"With the passing years means as time went by over many years.","zh":"with the passing years 指多年時間逐漸過去。"},{"en":"With the passing years, a neighbourhood may change from quiet streets to busy shops.","zh":"隨着歲月流逝，一個社區可能由安靜街道變成繁忙商店。"},{"en":"If values change with time, people may act differently later in life.","zh":"如果價值觀隨時間改變，人們在晚年可能行事不同。"},{"en":"The phrase shows gradual change over time.","zh":"這個片語顯示隨時間逐漸變化。"}],"source":"66 - Salvador Dali.pdf","sourcePage":14},{"front":"ever more infatuated with","meaning":"越來越迷戀","examples":[{"en":"Dalí became ever more infatuated with money.","zh":"達利變得越來越迷戀金錢。"},{"en":"Ever more infatuated with means increasingly obsessed with or strongly attracted to something.","zh":"ever more infatuated with 指越來越沉迷或強烈被某事吸引。"},{"en":"A teenager may become ever more infatuated with social media if likes feel like approval.","zh":"如果讚好感覺像認可，青少年可能越來越迷戀社交媒體。"},{"en":"If someone becomes infatuated with money, choices may be driven by profit rather than quality.","zh":"如果某人迷戀金錢，選擇可能由利潤而不是質素推動。"},{"en":"The phrase suggests a growing and possibly unhealthy attraction.","zh":"這個片語暗示逐漸增強且可能不健康的吸引。"}],"source":"66 - Salvador Dali.pdf","sourcePage":14},{"front":"be infatuated with","meaning":"迷戀","examples":[{"en":"Dalí was infatuated with money.","zh":"達利迷戀金錢。"},{"en":"Be infatuated with means be extremely and often unreasonably attracted to someone or something.","zh":"be infatuated with 指極度且常常不理性地被某人或某事吸引。"},{"en":"A student may be infatuated with a celebrity and copy everything they do.","zh":"學生可能迷戀名人，並模仿其一切。"},{"en":"If someone is infatuated with success, they may ignore rest, family, or ethics.","zh":"如果某人迷戀成功，可能忽視休息、家庭或道德。"},{"en":"The phrase suggests strong attraction that may cloud judgement.","zh":"這個片語暗示可能影響判斷的強烈吸引。"}],"source":"66 - Salvador Dali.pdf","sourcePage":14},{"front":"admit to","meaning":"承認有","examples":[{"en":"Dalí admitted to having a love of cash.","zh":"達利承認自己熱愛現金。"},{"en":"Admit to means accept or confess that something is true.","zh":"admit to 指接受或承認某事是真的。"},{"en":"A student may admit to forgetting homework after the teacher checks the class list.","zh":"老師檢查名單後，學生可能承認忘記功課。"},{"en":"If someone admits to a weakness, they are not trying to hide it.","zh":"如果某人承認弱點，就是沒有試圖隱藏。"},{"en":"The phrase often introduces an honest or uncomfortable confession.","zh":"這個片語常引出誠實或令人不舒服的承認。"}],"source":"66 - Salvador Dali.pdf","sourcePage":14},{"front":"a love of cash","meaning":"對金錢的熱愛","examples":[{"en":"Dalí admitted to a strong love of cash.","zh":"達利承認自己強烈熱愛現金。"},{"en":"A love of cash means a strong liking for money, especially immediate or visible money.","zh":"a love of cash 指強烈喜愛金錢，尤其是即時或可見的金錢。"},{"en":"A business owner with a love of cash may focus on quick sales more than long-term reputation.","zh":"熱愛現金的企業主可能較注重快速銷售，而不是長期聲譽。"},{"en":"If an artist has a love of cash, critics may question whether money affects the work.","zh":"如果藝術家熱愛金錢，評論家可能質疑金錢是否影響作品。"},{"en":"The phrase sounds more blunt and materialistic than a love of success.","zh":"這個片語比 a love of success 更直接和物質化。"}],"source":"66 - Salvador Dali.pdf","sourcePage":14},{"front":"accordingly","meaning":"因此","examples":[{"en":"Accordingly, Dalí endorsed many commercial products.","zh":"因此，達利為許多商業產品代言。"},{"en":"Accordingly means as a result of what has just been stated.","zh":"accordingly 指作為剛才所述情況的結果。"},{"en":"The road was flooded; accordingly, the school bus was delayed.","zh":"道路被水淹；因此校巴延誤。"},{"en":"If an artist loves money, they may accordingly accept commercial projects.","zh":"如果藝術家熱愛金錢，因此可能接受商業項目。"},{"en":"The word introduces a logical consequence.","zh":"這個詞引出邏輯結果。"}],"source":"66 - Salvador Dali.pdf","sourcePage":14},{"front":"indiscriminately endorse","meaning":"不加選擇地代言","examples":[{"en":"Dalí indiscriminately endorsed a host of products.","zh":"達利不加選擇地為大量產品代言。"},{"en":"Indiscriminately endorse means support or advertise products without choosing carefully.","zh":"indiscriminately endorse 指沒有仔細選擇便支持或宣傳產品。"},{"en":"A celebrity who advertises any product for money may be said to endorse brands indiscriminately.","zh":"如果名人為金錢替任何產品賣廣告，可以說他不加選擇地代言品牌。"},{"en":"If someone endorses products indiscriminately, their reputation may seem less serious.","zh":"如果某人不加選擇地代言產品，其聲譽可能顯得不那麼嚴肅。"},{"en":"The phrase suggests careless commercial support.","zh":"這個片語暗示草率的商業支持。"}],"source":"66 - Salvador Dali.pdf","sourcePage":14},{"front":"endorse products","meaning":"為產品代言","examples":[{"en":"Dalí endorsed products in TV commercials.","zh":"達利在電視廣告中為產品代言。"},{"en":"Endorse products means publicly support or advertise goods, often for payment.","zh":"endorse products 指公開支持或宣傳商品，通常收取報酬。"},{"en":"A famous athlete may endorse sports shoes in an advertising campaign.","zh":"著名運動員可能在廣告宣傳活動中為運動鞋代言。"},{"en":"If an artist endorses too many products, critics may accuse them of selling out.","zh":"如果藝術家為太多產品代言，評論家可能指責他出賣藝術。"},{"en":"The phrase connects reputation with marketing.","zh":"這個片語把聲譽與市場推廣連接起來。"}],"source":"66 - Salvador Dali.pdf","sourcePage":14},{"front":"TV commercials","meaning":"電視廣告","examples":[{"en":"Dalí appeared in French and American TV commercials.","zh":"達利出現在法國和美國電視廣告中。"},{"en":"TV commercials are short advertisements shown on television.","zh":"TV commercials 是在電視播放的短廣告。"},{"en":"A TV commercial may use a famous face to make viewers trust a product.","zh":"電視廣告可能使用名人面孔，令觀眾信任產品。"},{"en":"If an artist appears in commercials, the boundary between art and business becomes less clear.","zh":"如果藝術家出現在廣告中，藝術與商業之間的界線就變得不太清楚。"},{"en":"The phrase refers to televised advertising.","zh":"這個片語指電視上的廣告。"}],"source":"66 - Salvador Dali.pdf","sourcePage":14},{"front":"never fail to","meaning":"總是會；從不忘記","examples":[{"en":"Dalí never failed to promote himself.","zh":"達利總是會宣傳自己。"},{"en":"Never fail to means always do something whenever the chance appears.","zh":"never fail to 指每當有機會就總是做某事。"},{"en":"A careful teacher never fails to check whether students understand the instructions.","zh":"細心老師總是會檢查學生是否明白指示。"},{"en":"If someone never fails to mention their achievements, others may see them as self-promoting.","zh":"如果某人總是不忘提及自己的成就，其他人可能覺得他愛自我宣傳。"},{"en":"The phrase emphasises repeated reliability or habit.","zh":"這個片語強調反覆的可靠性或習慣。"}],"source":"66 - Salvador Dali.pdf","sourcePage":14},{"front":"promote himself","meaning":"宣傳自己","examples":[{"en":"Dalí constantly promoted himself.","zh":"達利不斷宣傳自己。"},{"en":"Promote himself means advertise his own name, image, talents, or achievements.","zh":"promote himself 指宣傳自己的名字、形象、才華或成就。"},{"en":"A freelancer may promote herself online to attract new clients.","zh":"自由工作者可能在網上宣傳自己，以吸引新客戶。"},{"en":"If an artist promotes himself too aggressively, people may focus on personality instead of work.","zh":"如果藝術家過度積極宣傳自己，人們可能集中於性格而不是作品。"},{"en":"The phrase can be neutral or critical depending on context.","zh":"這個片語可中性也可批評，視乎語境。"}],"source":"66 - Salvador Dali.pdf","sourcePage":15},{"front":"increasingly exhibitionist behaviour","meaning":"越來越愛出風頭的行為","examples":[{"en":"Dalí displayed increasingly exhibitionist behaviour.","zh":"達利表現出越來越愛出風頭的行為。"},{"en":"Increasingly exhibitionist behaviour means behaviour that becomes more and more attention-seeking and publicly dramatic.","zh":"increasingly exhibitionist behaviour 指行為越來越追求注意並具公開戲劇性。"},{"en":"A performer may show increasingly exhibitionist behaviour if every appearance becomes louder and stranger.","zh":"如果表演者每次露面都變得更大聲和更奇怪，可能表現出越來越愛出風頭的行為。"},{"en":"If self-promotion grows too extreme, it may seem more like performance than ordinary behaviour.","zh":"如果自我宣傳變得過度極端，它可能看似表演多於普通行為。"},{"en":"The phrase suggests a rising desire to be seen.","zh":"這個片語暗示越來越想被看見。"}],"source":"66 - Salvador Dali.pdf","sourcePage":15},{"front":"as time went on","meaning":"隨着時間過去","examples":[{"en":"Dalí became more exhibitionist as time went on.","zh":"隨着時間過去，達利變得更愛出風頭。"},{"en":"As time went on means as more time passed.","zh":"as time went on 指隨着更多時間流逝。"},{"en":"As time went on, the new student became more comfortable speaking in class.","zh":"隨着時間過去，新學生在課堂發言時變得更自在。"},{"en":"If a habit grows stronger over time, people may notice it more clearly later.","zh":"如果習慣隨時間變得更強，人們後來可能更清楚注意到它。"},{"en":"The phrase marks gradual change.","zh":"這個片語標示逐漸變化。"}],"source":"66 - Salvador Dali.pdf","sourcePage":15},{"front":"most notably","meaning":"最值得注意的是","examples":[{"en":"Most notably, he once arrived at a lecture in a strange car.","zh":"最值得注意的是，他曾乘一輛奇怪的車出席講座。"},{"en":"Most notably means the most important, memorable, or obvious example is this.","zh":"most notably 指最重要、最難忘或最明顯的例子是這個。"},{"en":"The school improved in many ways, most notably in student attendance.","zh":"學校在許多方面改善，最值得注意的是學生出席率。"},{"en":"If a writer says most notably, they are pointing to the clearest example.","zh":"如果作者說 most notably，就是指出最清楚的例子。"},{"en":"The phrase introduces a standout detail.","zh":"這個片語引出突出細節。"}],"source":"66 - Salvador Dali.pdf","sourcePage":15},{"front":"turn up for","meaning":"出席；現身於","examples":[{"en":"Dalí once turned up for a lecture in Paris in a Rolls Royce.","zh":"達利曾乘勞斯萊斯出席巴黎一場講座。"},{"en":"Turn up for means arrive at or appear at an event.","zh":"turn up for 指到達或現身於某活動。"},{"en":"Students should turn up for exams at least fifteen minutes early.","zh":"學生應至少提早十五分鐘到場考試。"},{"en":"If someone turns up in a dramatic way, people may remember the arrival more than the event.","zh":"如果某人以戲劇性方式現身，人們可能記得他的到來多於活動本身。"},{"en":"The phrase is informal and common in everyday English.","zh":"這個片語較口語，常見於日常英語。"}],"source":"66 - Salvador Dali.pdf","sourcePage":15},{"front":"a Rolls Royce stuffed with cauliflowers","meaning":"塞滿椰菜花的勞斯萊斯","examples":[{"en":"Dalí arrived in a Rolls Royce stuffed with cauliflowers.","zh":"達利乘坐塞滿椰菜花的勞斯萊斯到達。"},{"en":"A Rolls Royce stuffed with cauliflowers means a luxury car filled with cauliflowers, creating a deliberately bizarre image.","zh":"a Rolls Royce stuffed with cauliflowers 指一輛塞滿椰菜花的豪華汽車，刻意製造奇異形象。"},{"en":"A performer arriving in a taxi full of balloons would create a similarly strange public scene.","zh":"表演者乘一輛塞滿氣球的的士到場，也會製造類似奇怪公眾場面。"},{"en":"If a celebrity uses absurd props, the arrival becomes a performance in itself.","zh":"如果名人使用荒誕道具，到場本身就變成一場表演。"},{"en":"The phrase captures Dalí’s love of spectacle and eccentricity.","zh":"這個片語捕捉達利對奇觀和古怪作風的熱愛。"}],"source":"66 - Salvador Dali.pdf","sourcePage":15},{"front":"advertising campaign","meaning":"廣告宣傳活動","examples":[{"en":"Dalí appeared in an advertising campaign for Braniff Airlines.","zh":"達利出現在 Braniff Airlines 的廣告宣傳活動中。"},{"en":"An advertising campaign is a planned series of advertisements promoting a product, service, or brand.","zh":"advertising campaign 指一系列有計劃的廣告，用來推廣產品、服務或品牌。"},{"en":"A school may run an advertising campaign to attract new students.","zh":"學校可能進行廣告宣傳活動以吸引新學生。"},{"en":"If a campaign uses a famous artist, it may gain attention quickly.","zh":"如果宣傳活動使用著名藝術家，可能很快獲得注意。"},{"en":"The phrase refers to organised marketing, not one random advertisement.","zh":"這個片語指有組織的市場推廣，而不是一則隨機廣告。"}],"source":"66 - Salvador Dali.pdf","sourcePage":15},{"front":"If you got it, flaunt it.","meaning":"有就要炫耀出來","examples":[{"en":"Dalí declared the slogan, “If you got it, flaunt it.”","zh":"達利說出「有就要炫耀出來」這句口號。"},{"en":"If you got it, flaunt it means if you have something impressive, show it proudly.","zh":"If you got it, flaunt it 指如果你有令人印象深刻的東西，就自豪地展示出來。"},{"en":"A fashion advert might use this slogan to tell customers to show confidence in their style.","zh":"時裝廣告可能使用這句口號，叫顧客展示對自己風格的信心。"},{"en":"If people follow this idea too far, confidence can look like vanity.","zh":"如果人們把這個想法走得太遠，自信可能看起來像虛榮。"},{"en":"The phrase is informal and celebrates open display.","zh":"這個片語較口語，推崇公開展示。"}],"source":"66 - Salvador Dali.pdf","sourcePage":15},{"front":"flaunt something","meaning":"炫耀……","examples":[{"en":"Dalí believed that people should flaunt what they had.","zh":"達利相信人們應該炫耀自己擁有的東西。"},{"en":"Flaunt something means show something off openly and proudly, often to attract attention.","zh":"flaunt something 指公開而自豪地展示某物，通常為了吸引注意。"},{"en":"A student may flaunt a new phone by placing it on the desk where everyone can see it.","zh":"學生可能把新手機放在人人看得見的桌上來炫耀。"},{"en":"If someone flaunts wealth too much, others may see them as arrogant.","zh":"如果某人過度炫耀財富，其他人可能覺得他傲慢。"},{"en":"The word often suggests showiness rather than quiet confidence.","zh":"這個詞通常暗示張揚，而不是低調自信。"}],"source":"66 - Salvador Dali.pdf","sourcePage":15},{"front":"as a more positive outcome of","meaning":"作為……較正面的結果","examples":[{"en":"As a more positive outcome of his love of money, Dalí took on diverse projects.","zh":"作為他熱愛金錢較正面的結果，達利承接了多元化項目。"},{"en":"As a more positive outcome of means as a better or more beneficial result of something.","zh":"as a more positive outcome of 指作為某事較好或較有益的結果。"},{"en":"As a more positive outcome of a school rivalry, students worked harder and improved.","zh":"作為學校競爭較正面的結果，學生更努力並有所進步。"},{"en":"If a weakness leads to useful work, writers may describe it as a positive outcome.","zh":"如果弱點導致有用工作，作者可能把它描述為正面結果。"},{"en":"The phrase reframes a negative trait by showing a beneficial result.","zh":"這個片語透過展示有益結果，重新框定負面特質。"}],"source":"66 - Salvador Dali.pdf","sourcePage":15},{"front":"take on projects","meaning":"承接項目","examples":[{"en":"Dalí took on increasingly diverse projects.","zh":"達利承接越來越多元化的項目。"},{"en":"Take on projects means accept or begin work on different tasks or commissions.","zh":"take on projects 指接受或開始處理不同任務或委託。"},{"en":"A designer may take on projects for shops, schools, and community groups.","zh":"設計師可能承接商店、學校和社區團體的項目。"},{"en":"If someone takes on too many projects, quality or time management may suffer.","zh":"如果某人承接太多項目，質素或時間管理可能受影響。"},{"en":"The phrase focuses on accepting work responsibilities.","zh":"這個片語集中於接受工作責任。"}],"source":"66 - Salvador Dali.pdf","sourcePage":16},{"front":"increasingly diverse projects","meaning":"越來越多元化的項目","examples":[{"en":"Dalí took on increasingly diverse projects outside painting.","zh":"達利承接繪畫以外越來越多元化的項目。"},{"en":"Increasingly diverse projects are projects that become more varied in type over time.","zh":"increasingly diverse projects 指隨時間在類型上變得更多樣的項目。"},{"en":"A student may take on increasingly diverse projects, from writing articles to making videos.","zh":"學生可能承接越來越多元化的項目，從寫文章到製作影片。"},{"en":"If an artist works in many areas, their skills and audience may expand.","zh":"如果藝術家在許多領域工作，其技能和觀眾可能擴大。"},{"en":"The phrase shows growing variety.","zh":"這個片語顯示逐漸增加的多樣性。"}],"source":"66 - Salvador Dali.pdf","sourcePage":16},{"front":"ranging from … to …","meaning":"從……到……不等","examples":[{"en":"His projects ranged from set design to jewellery design.","zh":"他的項目從佈景設計到首飾設計不等。"},{"en":"Ranging from … to … means covering a variety between two examples or limits.","zh":"ranging from … to … 指涵蓋兩個例子或範圍之間的多種內容。"},{"en":"The workshop covers skills ranging from public speaking to video editing.","zh":"工作坊涵蓋從公開演說到影片剪輯不等的技能。"},{"en":"If an artist’s work ranges from painting to fashion, the career is broad.","zh":"如果藝術家的作品從繪畫到時裝不等，其事業就很廣泛。"},{"en":"The phrase introduces a wide span of examples.","zh":"這個片語引出廣闊例子範圍。"}],"source":"66 - Salvador Dali.pdf","sourcePage":16},{"front":"set design","meaning":"舞台設計；佈景設計","examples":[{"en":"Dalí worked on set design as well as painting.","zh":"達利除了繪畫，也從事佈景設計。"},{"en":"Set design means designing the physical background, scenery, or visual environment for theatre, film, or performance.","zh":"set design 指為戲劇、電影或表演設計實體背景、場景或視覺環境。"},{"en":"A school drama needs set design to create a classroom, castle, or street on stage.","zh":"學校戲劇需要佈景設計，在舞台上創造課室、城堡或街道。"},{"en":"If set design is strong, audiences can understand the world of a play before anyone speaks.","zh":"如果佈景設計出色，觀眾在任何人開口前已能理解劇中世界。"},{"en":"The phrase refers to visual design for staged or filmed scenes.","zh":"這個片語指舞台或影像場景的視覺設計。"}],"source":"66 - Salvador Dali.pdf","sourcePage":16},{"front":"clothing and jewellery design","meaning":"服裝和首飾設計","examples":[{"en":"Dalí also worked on clothing and jewellery design.","zh":"達利也從事服裝和首飾設計。"},{"en":"Clothing and jewellery design means creating garments, accessories, and decorative wearable objects.","zh":"clothing and jewellery design 指創作衣物、配飾和可佩戴的裝飾物。"},{"en":"A fashion student may study clothing and jewellery design to learn shape, material, and style.","zh":"時裝學生可能學習服裝和首飾設計，以了解形狀、材料和風格。"},{"en":"If an artist enters clothing design, their visual ideas can move from canvas to the body.","zh":"如果藝術家進入服裝設計，其視覺想法可以從畫布移到身體上。"},{"en":"The phrase refers to design work connected with what people wear.","zh":"這個片語指與人們穿戴物品有關的設計工作。"}],"source":"66 - Salvador Dali.pdf","sourcePage":16},{"front":"early on in his career","meaning":"在其事業早期","examples":[{"en":"Some critics believed Dalí changed early on in his career.","zh":"有些評論家認為達利在其事業早期已經改變。"},{"en":"Early on in his career means during the first stage of his working or artistic life.","zh":"early on in his career 指在其工作或藝術生涯的初期。"},{"en":"A teacher may develop strong classroom habits early on in her career.","zh":"老師可能在事業早期建立強烈課室習慣。"},{"en":"If an artist changes early in a career, that shift may shape everything later.","zh":"如果藝術家在事業早期改變，這種轉變可能塑造之後一切。"},{"en":"The phrase identifies the beginning phase of professional development.","zh":"這個片語指出專業發展的起始階段。"}],"source":"66 - Salvador Dali.pdf","sourcePage":16},{"front":"exceed his dedication to","meaning":"超過他對……的投入","examples":[{"en":"Critics believed his love of money exceeded his dedication to art.","zh":"評論家認為他對金錢的熱愛超過他對藝術的投入。"},{"en":"Exceed his dedication to means become stronger or greater than his commitment to something.","zh":"exceed his dedication to 指變得比他對某事的投入更強或更大。"},{"en":"A student’s love of gaming may exceed his dedication to homework if he plays all night.","zh":"如果學生通宵打機，他對遊戲的熱愛可能超過他對功課的投入。"},{"en":"If money exceeds art in importance, critics may question the quality of the work.","zh":"如果金錢的重要性超過藝術，評論家可能質疑作品質素。"},{"en":"The phrase compares two priorities.","zh":"這個片語比較兩種優先事項。"}],"source":"66 - Salvador Dali.pdf","sourcePage":16},{"front":"dedication to","meaning":"對……的投入；奉獻","examples":[{"en":"Some critics questioned Dalí’s dedication to producing great art.","zh":"有些評論家質疑達利對創作偉大藝術的投入。"},{"en":"Dedication to means strong commitment, effort, and loyalty toward a goal or activity.","zh":"dedication to 指對某目標或活動的強烈承諾、努力和忠誠。"},{"en":"A nurse shows dedication to patients by working carefully even under pressure.","zh":"護士在壓力下仍細心工作，展現對病人的奉獻。"},{"en":"If dedication weakens, the quality of work may decline.","zh":"如果投入減弱，作品質素可能下降。"},{"en":"The phrase describes serious long-term commitment.","zh":"這個片語描述認真的長期承諾。"}],"source":"66 - Salvador Dali.pdf","sourcePage":16},{"front":"result in","meaning":"導致","examples":[{"en":"His love of money resulted in work that some critics disliked.","zh":"他對金錢的熱愛導致一些評論家不喜歡的作品。"},{"en":"Result in means cause something to happen.","zh":"result in 指造成某事發生。"},{"en":"Poor planning can result in missed deadlines and confused students.","zh":"規劃不善可以導致錯過期限和學生困惑。"},{"en":"If commercial pressure results in rushed work, critics may notice a decline in quality.","zh":"如果商業壓力導致作品倉促，評論家可能注意到質素下降。"},{"en":"The phrase links cause and effect.","zh":"這個片語連接原因和結果。"}],"source":"66 - Salvador Dali.pdf","sourcePage":16},{"front":"awful junk","meaning":"糟糕的垃圾作品","examples":[{"en":"One critic claimed that Dalí produced awful junk after 1939.","zh":"一位評論家聲稱達利在1939年後創作糟糕的垃圾作品。"},{"en":"Awful junk means extremely poor-quality work that the speaker thinks has little value.","zh":"awful junk 指說話者認為質素極差且幾乎沒有價值的作品。"},{"en":"A harsh reviewer might call a badly made film awful junk if it feels careless and empty.","zh":"嚴厲影評人可能把一部粗製濫造、空洞的電影稱為糟糕垃圾作品。"},{"en":"If critics use this phrase, they are expressing strong dislike, not neutral judgement.","zh":"如果評論家使用這個片語，他們是在表達強烈厭惡，而不是中立判斷。"},{"en":"The phrase is informal, severe, and insulting.","zh":"這個片語口語、嚴厲且帶侮辱性。"}],"source":"66 - Salvador Dali.pdf","sourcePage":16},{"front":"despite a lukewarm reception","meaning":"儘管反應冷淡","examples":[{"en":"Despite a lukewarm reception from critics, Dalí remained popular.","zh":"儘管評論家反應冷淡，達利仍然受歡迎。"},{"en":"Despite a lukewarm reception means although the response was only mildly interested or not very enthusiastic.","zh":"despite a lukewarm reception 指雖然反應只是略有興趣或不太熱烈。"},{"en":"Despite a lukewarm reception from teachers, the new school app became popular with students.","zh":"儘管老師反應冷淡，新的學校應用程式仍受學生歡迎。"},{"en":"If critics are cool but the public enjoys the work, popularity may continue.","zh":"如果評論家冷淡但公眾喜歡作品，受歡迎程度可能持續。"},{"en":"The phrase contrasts weak approval with later success.","zh":"這個片語把弱反應與後來成功作對比。"}],"source":"66 - Salvador Dali.pdf","sourcePage":17},{"front":"lukewarm reception","meaning":"冷淡的反應","examples":[{"en":"Some of Dalí’s later work received a lukewarm reception from critics.","zh":"達利的一些後期作品收到評論家的冷淡反應。"},{"en":"A lukewarm reception is a response that is neither strongly positive nor openly hostile, but rather cool.","zh":"lukewarm reception 指既非強烈正面，也非公開敵對，而是較冷淡的回應。"},{"en":"The school play received a lukewarm reception because the audience clapped politely but briefly.","zh":"學校劇收到冷淡反應，因為觀眾只是禮貌而短暫地拍掌。"},{"en":"If a product receives a lukewarm reception, its makers may need to improve or explain it better.","zh":"如果產品收到冷淡反應，製作者可能需要改善或更好解釋它。"},{"en":"The phrase describes mild or unenthusiastic approval.","zh":"這個片語描述溫和或缺乏熱情的認可。"}],"source":"66 - Salvador Dali.pdf","sourcePage":17},{"front":"public popularity","meaning":"大眾歡迎程度","examples":[{"en":"Dalí’s public popularity never declined.","zh":"達利的大眾歡迎程度從未下降。"},{"en":"Public popularity means how much ordinary people like, recognise, or support someone.","zh":"public popularity 指普通人有多喜歡、認識或支持某人。"},{"en":"A singer may have strong public popularity even if critics dislike the music.","zh":"即使評論家不喜歡音樂，歌手仍可能有很高大眾歡迎程度。"},{"en":"If public popularity remains high, museums and advertisers may continue to invite the person.","zh":"如果大眾歡迎程度保持高企，博物館和廣告商可能繼續邀請該人。"},{"en":"The phrase focuses on the general public, not experts.","zh":"這個片語集中於一般公眾，而不是專家。"}],"source":"66 - Salvador Dali.pdf","sourcePage":17},{"front":"never decline","meaning":"從未下降","examples":[{"en":"Dalí’s popularity never declined among the public.","zh":"達利在公眾中的受歡迎程度從未下降。"},{"en":"Never decline means never become lower, weaker, or less popular.","zh":"never decline 指從未變低、變弱或變得不受歡迎。"},{"en":"A useful community service may never decline in importance because people always need it.","zh":"有用的社區服務可能重要性從未下降，因為人們一直需要它。"},{"en":"If public interest never declines, a figure can remain famous across generations.","zh":"如果公眾興趣從未下降，一個人物可以跨世代保持知名。"},{"en":"The phrase describes lasting strength.","zh":"這個片語描述持久強度。"}],"source":"66 - Salvador Dali.pdf","sourcePage":17},{"front":"at the age of","meaning":"在……歲時","examples":[{"en":"At the age of 70, Dalí saw a museum open in his hometown.","zh":"在70歲時，達利看到一座博物館在他的家鄉開幕。"},{"en":"At the age of means when someone was a particular age.","zh":"at the age of 指在某人某個年齡時。"},{"en":"At the age of sixteen, a student may begin thinking seriously about university choices.","zh":"在16歲時，學生可能開始認真思考大學選擇。"},{"en":"If an artist receives a museum at the age of seventy, their fame is recognised during life.","zh":"如果藝術家在70歲時獲得一座博物館，其名聲就在有生之年被承認。"},{"en":"The phrase gives the time in a person’s life.","zh":"這個片語給出某人人生中的時間。"}],"source":"66 - Salvador Dali.pdf","sourcePage":17},{"front":"hometown","meaning":"家鄉","examples":[{"en":"The Dalí Theatre Museum opened in his hometown, Figueres.","zh":"達利劇院博物館在他的家鄉菲格雷斯開幕。"},{"en":"A hometown is the town or place where someone was born or grew up.","zh":"hometown 指某人出生或成長的城鎮或地方。"},{"en":"A student may feel proud when their hometown appears in a film.","zh":"當家鄉出現在電影中，學生可能感到自豪。"},{"en":"If a museum opens in an artist’s hometown, local identity becomes part of the attraction.","zh":"如果博物館在藝術家家鄉開幕，本地身份就成為吸引力的一部分。"},{"en":"The phrase connects personal history with place.","zh":"這個片語把個人歷史與地方連接起來。"}],"source":"66 - Salvador Dali.pdf","sourcePage":17},{"front":"more of … than …","meaning":"與其說是……不如說是……","examples":[{"en":"The museum was more of a surrealist happening than a traditional museum.","zh":"這座博物館與其說是傳統博物館，不如說是超現實主義活動。"},{"en":"More of … than … means something is closer to the first description than the second.","zh":"more of … than … 指某事物更接近第一種描述，而不是第二種。"},{"en":"The lesson was more of a conversation than a lecture because students kept asking questions.","zh":"這堂課與其說是講座，不如說是對話，因為學生一直提問。"},{"en":"If a museum feels like a performance, it may be more of an event than a quiet display space.","zh":"如果博物館感覺像表演，它與其說是安靜展示空間，不如說是一場活動。"},{"en":"The phrase compares two ways of understanding something.","zh":"這個片語比較理解某事物的兩種方式。"}],"source":"66 - Salvador Dali.pdf","sourcePage":17},{"front":"surrealist happening","meaning":"超現實主義活動；超現實主義事件","examples":[{"en":"The museum was more of a surrealist happening than a museum.","zh":"這座博物館與其說是博物館，不如說是超現實主義活動。"},{"en":"A surrealist happening is an unusual art event or experience that feels dream-like, strange, and staged.","zh":"surrealist happening 指一種不尋常、如夢似幻、奇怪且經過設計的藝術事件或體驗。"},{"en":"A gallery full of moving objects, strange sounds, and audience participation may feel like a surrealist happening.","zh":"充滿移動物件、奇怪聲音和觀眾參與的畫廊，可能感覺像超現實主義活動。"},{"en":"If a museum visit becomes a performance-like experience, it is no longer only a display.","zh":"如果博物館參觀變成類似表演的體驗，它就不再只是展示。"},{"en":"The phrase suggests an event shaped by Surrealist imagination.","zh":"這個片語暗示由超現實主義想像塑造的事件。"}],"source":"66 - Salvador Dali.pdf","sourcePage":17},{"front":"exhibit","meaning":"展品","examples":[{"en":"One exhibit was a black Cadillac that rained inside itself.","zh":"其中一件展品是一輛內部會下雨的黑色 Cadillac。"},{"en":"An exhibit is an object, artwork, or display shown in a museum or exhibition.","zh":"exhibit 指在博物館或展覽中展示的物件、藝術品或展示項目。"},{"en":"A science museum exhibit may let children press buttons and see how electricity works.","zh":"科學博物館展品可能讓孩子按按鈕並觀察電力如何運作。"},{"en":"If an exhibit is unusual, visitors may remember it more than ordinary labels or walls.","zh":"如果展品不尋常，參觀者可能比起普通標籤或牆壁更記得它。"},{"en":"The word refers to something displayed for public viewing.","zh":"這個詞指供公眾觀看的展示物。"}],"source":"66 - Salvador Dali.pdf","sourcePage":17},{"front":"drop a coin into the slot","meaning":"把硬幣投入投幣口","examples":[{"en":"The Cadillac rained whenever a visitor dropped a coin into the slot.","zh":"每當訪客把硬幣投入投幣口，這輛 Cadillac 內部就會下雨。"},{"en":"Drop a coin into the slot means put a coin into a machine opening to make something happen.","zh":"drop a coin into the slot 指把硬幣放入機器開口，以啟動某事。"},{"en":"A child may drop a coin into the slot to start a toy ride outside a shop.","zh":"孩子可能把硬幣投入投幣口，啟動商店外的玩具車。"},{"en":"If an exhibit reacts when money is inserted, the visitor becomes part of the artwork.","zh":"如果展品在投入金錢後作出反應，訪客就成為藝術品的一部分。"},{"en":"The phrase describes a simple mechanical action.","zh":"這個片語描述簡單的機械動作。"}],"source":"66 - Salvador Dali.pdf","sourcePage":17},{"front":"hundreds of thousands of","meaning":"數以十萬計的","examples":[{"en":"Hundreds of thousands of visitors tour the museum each year.","zh":"數以十萬計的訪客每年參觀這座博物館。"},{"en":"Hundreds of thousands of means several hundred thousand, usually a very large number.","zh":"hundreds of thousands of 指幾十萬，通常是非常大的數量。"},{"en":"Hundreds of thousands of people may watch a popular video in one day.","zh":"數以十萬計的人可能在一天內觀看熱門影片。"},{"en":"If a museum attracts hundreds of thousands of visitors, it has major public appeal.","zh":"如果博物館吸引數以十萬計訪客，它就有重大公眾吸引力。"},{"en":"The phrase gives a large approximate quantity.","zh":"這個片語給出龐大的大約數量。"}],"source":"66 - Salvador Dali.pdf","sourcePage":18},{"front":"tour the museum","meaning":"參觀博物館","examples":[{"en":"Visitors still tour the museum each year.","zh":"訪客每年仍參觀這座博物館。"},{"en":"Tour the museum means walk through the museum to see its exhibits and displays.","zh":"tour the museum 指走遍博物館，觀看展品和展示。"},{"en":"Students may tour a history museum before writing a report.","zh":"學生可能在寫報告前參觀歷史博物館。"},{"en":"If visitors tour a museum with a guide, they may understand the exhibits more deeply.","zh":"如果訪客跟隨導賞參觀博物館，可能更深入理解展品。"},{"en":"The phrase describes visiting a museum systematically.","zh":"這個片語描述有系統地參觀博物館。"}],"source":"66 - Salvador Dali.pdf","sourcePage":18},{"front":"each year","meaning":"每年","examples":[{"en":"Hundreds of thousands of visitors visit the museum each year.","zh":"數以十萬計的訪客每年參觀這座博物館。"},{"en":"Each year means every year.","zh":"each year 指每一年。"},{"en":"Students choose new courses each year as they move through school.","zh":"學生隨着升級，每年選擇新課程。"},{"en":"If a museum attracts visitors each year, its appeal remains steady over time.","zh":"如果博物館每年都吸引訪客，其吸引力隨時間保持穩定。"},{"en":"The phrase describes repeated annual occurrence.","zh":"這個片語描述每年重複發生。"}],"source":"66 - Salvador Dali.pdf","sourcePage":18},{"front":"whatever your opinion of him","meaning":"無論你對他有何看法","examples":[{"en":"Whatever your opinion of him, Dalí is unlikely to be forgotten.","zh":"無論你對他有何看法，達利都不大可能被遺忘。"},{"en":"Whatever your opinion of him means no matter whether you admire, dislike, or feel unsure about him.","zh":"whatever your opinion of him 指不論你欣賞、討厭或對他不確定。"},{"en":"Whatever your opinion of a strict principal, you may admit that the school changed under her leadership.","zh":"無論你對嚴格校長有何看法，你可能承認學校在她領導下改變了。"},{"en":"If a person divides opinion but remains influential, personal judgement does not erase their impact.","zh":"如果一個人令人意見分歧但仍有影響力，個人判斷不會抹去其影響。"},{"en":"The phrase introduces a balanced statement despite disagreement.","zh":"這個片語在分歧中引出平衡陳述。"}],"source":"66 - Salvador Dali.pdf","sourcePage":18},{"front":"be unlikely ever to be forgotten","meaning":"不大可能被遺忘","examples":[{"en":"Dalí is unlikely ever to be forgotten.","zh":"達利不大可能被遺忘。"},{"en":"Be unlikely ever to be forgotten means probably remain remembered for a very long time.","zh":"be unlikely ever to be forgotten 指很可能會長時間被記住。"},{"en":"A writer whose stories are still read by children may be unlikely ever to be forgotten.","zh":"如果作家的故事仍被孩子閱讀，他可能不大可能被遺忘。"},{"en":"If a person creates iconic images, memory of them can last beyond their lifetime.","zh":"如果某人創造標誌性形象，人們對他的記憶可超越其一生。"},{"en":"The phrase expresses strong confidence in lasting fame.","zh":"這個片語表達對持久名聲的強烈信心。"}],"source":"66 - Salvador Dali.pdf","sourcePage":18},{"front":"complete each sentence with","meaning":"用……完成每個句子","examples":[{"en":"Students complete each sentence with the correct ending.","zh":"學生用正確結尾完成每個句子。"},{"en":"Complete each sentence with means finish each sentence by adding the required word, phrase, or ending.","zh":"complete each sentence with 指加入所需詞語、片語或結尾來完成每個句子。"},{"en":"In a grammar exercise, students complete each sentence with the correct verb form.","zh":"在文法練習中，學生用正確動詞形式完成每個句子。"},{"en":"If the ending does not fit the sentence grammar, the answer may be wrong.","zh":"如果結尾不符合句子文法，答案可能錯。"},{"en":"The phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"66 - Salvador Dali.pdf","sourcePage":18},{"front":"the correct ending","meaning":"正確結尾","examples":[{"en":"Students choose the correct ending for each sentence.","zh":"學生為每個句子選擇正確結尾。"},{"en":"The correct ending is the sentence ending that best matches meaning and grammar.","zh":"the correct ending 指最符合意思和文法的句子結尾。"},{"en":"A reading question may give five endings, but only one matches the passage.","zh":"閱讀題可能給五個結尾，但只有一個符合文章。"},{"en":"If students choose an ending by grammar only, they may miss the meaning.","zh":"如果學生只按文法選結尾，可能會錯過意思。"},{"en":"The phrase refers to the right completion option.","zh":"這個片語指正確的完成選項。"}],"source":"66 - Salvador Dali.pdf","sourcePage":18},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Students write the correct letter next to each question.","zh":"學生在每題旁邊寫上正確字母。"},{"en":"Write the correct letter means record the option letter that matches the right answer.","zh":"write the correct letter 指寫下與正確答案相符的選項字母。"},{"en":"In a multiple-choice task, students may write A, B, C, or D beside the question number.","zh":"在多項選擇題中，學生可能在題號旁寫 A、B、C 或 D。"},{"en":"If a student knows the answer but writes the wrong letter, the mark may be lost.","zh":"如果學生知道答案但寫錯字母，可能失分。"},{"en":"The phrase gives an answer-format instruction.","zh":"這個片語給出答案格式指示。"}],"source":"66 - Salvador Dali.pdf","sourcePage":18},{"front":"next to questions","meaning":"在題目旁邊","examples":[{"en":"Students write letters next to the questions.","zh":"學生在題目旁邊寫字母。"},{"en":"Next to questions means beside the question numbers or question text.","zh":"next to questions 指在題號或題目文字旁邊。"},{"en":"In a worksheet, students may write answers next to questions instead of on a separate sheet.","zh":"在工作紙中，學生可能在題目旁邊寫答案，而不是寫在另一張紙上。"},{"en":"If answers are placed next to questions, marking becomes easier and clearer.","zh":"如果答案放在題目旁邊，批改就更容易、更清晰。"},{"en":"The phrase describes position on a page.","zh":"這個片語描述頁面上的位置。"}],"source":"66 - Salvador Dali.pdf","sourcePage":18},{"front":"certain limitations","meaning":"某些限制","examples":[{"en":"The option refers to certain limitations in Dalí’s artistic skills.","zh":"該選項提到達利藝術技巧中的某些限制。"},{"en":"Certain limitations means particular weaknesses or restrictions, not all possible problems.","zh":"certain limitations 指特定弱點或限制，而不是所有可能問題。"},{"en":"A student may have certain limitations in spelling but be strong in speaking.","zh":"學生可能在拼寫方面有某些限制，但口語很強。"},{"en":"If limitations are specific, feedback should focus on those exact areas.","zh":"如果限制是特定的，回饋應集中於那些確切範疇。"},{"en":"The phrase narrows criticism to selected weaknesses.","zh":"這個片語把批評縮窄至指定弱點。"}],"source":"66 - Salvador Dali.pdf","sourcePage":18},{"front":"artistic skills","meaning":"藝術技巧","examples":[{"en":"Critics discussed limitations in Dalí’s artistic skills.","zh":"評論家討論達利藝術技巧中的限制。"},{"en":"Artistic skills are abilities used to create art, such as drawing, colour use, composition, and imagination.","zh":"artistic skills 指創作藝術所用的能力，例如素描、用色、構圖和想像力。"},{"en":"A student improves artistic skills by sketching regularly and studying other artists.","zh":"學生透過定期素描和研究其他藝術家來提升藝術技巧。"},{"en":"If artistic skills weaken, critics may notice poorer technique or less original work.","zh":"如果藝術技巧變弱，評論家可能注意到技巧較差或作品較不原創。"},{"en":"The phrase focuses on ability in making art.","zh":"這個片語集中於製作藝術的能力。"}],"source":"66 - Salvador Dali.pdf","sourcePage":19},{"front":"become evident","meaning":"變得明顯","examples":[{"en":"Some weaknesses became evident in his later works.","zh":"一些弱點在他的後期作品中變得明顯。"},{"en":"Become evident means become clear or easy to notice.","zh":"become evident 指變得清楚或容易注意到。"},{"en":"A student’s improvement becomes evident when their essays contain fewer repeated mistakes.","zh":"當學生文章中重複錯誤減少，其進步就變得明顯。"},{"en":"If problems become evident only later, early praise may need to be reconsidered.","zh":"如果問題只在後來變得明顯，早期讚賞可能需要重新考慮。"},{"en":"The phrase describes something becoming visible or obvious.","zh":"這個片語描述某事變得可見或明顯。"}],"source":"66 - Salvador Dali.pdf","sourcePage":19},{"front":"later works","meaning":"後期作品","examples":[{"en":"Some critics disliked Dalí’s later works.","zh":"有些評論家不喜歡達利的後期作品。"},{"en":"Later works are works created in a later period of an artist’s career.","zh":"later works 指藝術家事業後期創作的作品。"},{"en":"A writer’s later works may feel calmer or darker than early books.","zh":"作家的後期作品可能比早期書籍更平靜或更黑暗。"},{"en":"If later works receive criticism, people may compare them with earlier achievements.","zh":"如果後期作品受到批評，人們可能把它們與早期成就比較。"},{"en":"The phrase contrasts later creations with early ones.","zh":"這個片語把後來創作與早期作品作對比。"}],"source":"66 - Salvador Dali.pdf","sourcePage":19},{"front":"open someone’s eyes to","meaning":"令某人開眼界；使某人認識到","examples":[{"en":"Paris opened Dalí’s eyes to new artistic ideas.","zh":"巴黎令達利認識到新的藝術思想。"},{"en":"Open someone’s eyes to means make someone realise, understand, or notice something new.","zh":"open someone’s eyes to 指令某人意識到、理解或注意到新事物。"},{"en":"Volunteering can open students’ eyes to poverty beyond textbook statistics.","zh":"做義工可以令學生對課本統計以外的貧窮開眼界。"},{"en":"If travel opens your eyes to new ideas, your choices may change afterwards.","zh":"如果旅行令你對新想法開眼界，你之後的選擇可能改變。"},{"en":"The phrase describes a new awareness.","zh":"這個片語描述新的覺察。"}],"source":"66 - Salvador Dali.pdf","sourcePage":19},{"front":"psychoanalytic movement","meaning":"精神分析運動","examples":[{"en":"Freud’s ideas were central to the psychoanalytic movement.","zh":"佛洛伊德的思想是精神分析運動的核心。"},{"en":"The psychoanalytic movement was the development and spread of psychoanalytic ideas about the unconscious mind.","zh":"psychoanalytic movement 指關於潛意識的精神分析思想的發展和傳播。"},{"en":"Psychology students may study the psychoanalytic movement to understand early theories of personality.","zh":"心理學學生可能研究精神分析運動，以理解早期人格理論。"},{"en":"If artists draw on this movement, their work may focus on dreams and hidden desires.","zh":"如果藝術家借用這個運動，其作品可能集中於夢境和隱藏慾望。"},{"en":"The phrase refers to the broader intellectual movement around psychoanalysis.","zh":"這個片語指圍繞精神分析學的更廣泛思想運動。"}],"source":"66 - Salvador Dali.pdf","sourcePage":19},{"front":"incorporate something into","meaning":"把……融入","examples":[{"en":"Dalí incorporated psychoanalytic ideas into his work.","zh":"達利把精神分析思想融入他的作品。"},{"en":"Incorporate something into means include something as part of a larger whole.","zh":"incorporate something into 指把某物加入並成為更大整體的一部分。"},{"en":"A teacher may incorporate games into a grammar lesson to make practice more active.","zh":"老師可能把遊戲融入文法課，令練習更主動。"},{"en":"If an artist incorporates theory into painting, ideas become part of the visual design.","zh":"如果藝術家把理論融入繪畫，思想就成為視覺設計的一部分。"},{"en":"The phrase describes adding and blending something into something else.","zh":"這個片語描述把某物加入並融合進另一物。"}],"source":"66 - Salvador Dali.pdf","sourcePage":19},{"front":"artistic studies","meaning":"藝術學習","examples":[{"en":"Dalí believed his artistic studies needed further development.","zh":"達利認為他的藝術學習需要進一步發展。"},{"en":"Artistic studies are formal or informal learning connected with art, technique, theory, and style.","zh":"artistic studies 指與藝術、技巧、理論和風格有關的正式或非正式學習。"},{"en":"A student may continue artistic studies by attending workshops and visiting museums.","zh":"學生可能透過參加工作坊和參觀博物館繼續藝術學習。"},{"en":"If artistic studies feel incomplete, an artist may seek new teachers or cities.","zh":"如果藝術學習感到不完整，藝術家可能尋找新老師或新城市。"},{"en":"The phrase refers to learning as an artist.","zh":"這個片語指作為藝術家的學習。"}],"source":"66 - Salvador Dali.pdf","sourcePage":19},{"front":"be supplemented by","meaning":"由……補充","examples":[{"en":"Dalí felt his studies needed to be supplemented by experience in Paris.","zh":"達利覺得他的學習需要由巴黎經驗補充。"},{"en":"Be supplemented by means be added to or strengthened by something extra.","zh":"be supplemented by 指由額外事物加入或加強。"},{"en":"Classroom learning can be supplemented by real workplace experience.","zh":"課堂學習可以由真實工作經驗補充。"},{"en":"If theory is supplemented by practice, students may understand it more deeply.","zh":"如果理論由實踐補充，學生可能更深入理解。"},{"en":"The phrase shows that something existing needs extra support or addition.","zh":"這個片語顯示現有事物需要額外支援或補充。"}],"source":"66 - Salvador Dali.pdf","sourcePage":19},{"front":"artistic legacy","meaning":"藝術遺產","examples":[{"en":"Dalí’s artistic legacy remains secure.","zh":"達利的藝術遺產仍然穩固。"},{"en":"Artistic legacy means the lasting influence, reputation, and works an artist leaves behind.","zh":"artistic legacy 指藝術家留下的持久影響、聲譽和作品。"},{"en":"A painter’s artistic legacy may include famous paintings, students, and influence on later artists.","zh":"畫家的藝術遺產可能包括名畫、學生和對後來藝術家的影響。"},{"en":"If a legacy is strong, criticism of some works may not destroy the artist’s place in history.","zh":"如果遺產強大，對某些作品的批評未必摧毀藝術家的歷史地位。"},{"en":"The phrase focuses on what remains after an artist’s life.","zh":"這個片語集中於藝術家人生之後仍留下的東西。"}],"source":"66 - Salvador Dali.pdf","sourcePage":19},{"front":"be secure","meaning":"穩固的","examples":[{"en":"Dalí’s artistic legacy is secure despite criticism.","zh":"儘管有批評，達利的藝術遺產仍然穩固。"},{"en":"Be secure means be safe, strong, and unlikely to be lost or damaged.","zh":"be secure 指安全、強大且不大可能失去或受損。"},{"en":"A student’s place on a course is secure after the fee and documents are submitted.","zh":"學生提交費用和文件後，課程名額就穩固。"},{"en":"If an artist’s reputation is secure, a few negative reviews may not matter much.","zh":"如果藝術家的聲譽穩固，少數負面評論未必很重要。"},{"en":"The phrase suggests stability and protection.","zh":"這個片語暗示穩定和受保護。"}],"source":"66 - Salvador Dali.pdf","sourcePage":19},{"front":"be less impressed with","meaning":"對……印象較不深","examples":[{"en":"Some critics were less impressed with Dalí’s later work.","zh":"有些評論家對達利的後期作品印象較不深。"},{"en":"Be less impressed with means admire or approve of something less than before or less than others do.","zh":"be less impressed with 指較以前或較他人更少欣賞或認同某事。"},{"en":"A teacher may be less impressed with a rushed essay than with a carefully planned one.","zh":"與仔細規劃的文章相比，老師可能對倉促完成的文章印象較不深。"},{"en":"If critics are less impressed with later work, they may think quality has declined.","zh":"如果評論家對後期作品印象較不深，可能認為質素下降。"},{"en":"The phrase signals weaker approval.","zh":"這個片語表示較弱認可。"}],"source":"66 - Salvador Dali.pdf","sourcePage":20},{"front":"the general public","meaning":"普羅大眾","examples":[{"en":"The general public continued to admire Dalí.","zh":"普羅大眾繼續欣賞達利。"},{"en":"The general public means ordinary people as a whole, not experts or specialists.","zh":"the general public 指普通人整體，而不是專家或專業人士。"},{"en":"A film may be loved by the general public even if critics dislike it.","zh":"電影即使被評論家不喜歡，也可能受到普羅大眾喜愛。"},{"en":"If the general public keeps visiting exhibitions, an artist’s popularity remains strong.","zh":"如果普羅大眾繼續參觀展覽，藝術家的受歡迎程度仍然強。"},{"en":"The phrase contrasts public taste with expert opinion.","zh":"這個片語把公眾品味與專家意見作對比。"}],"source":"66 - Salvador Dali.pdf","sourcePage":20},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter from the options.","zh":"學生從選項中選出正確字母。"},{"en":"Choose the correct letter means select the option letter that matches the right answer.","zh":"choose the correct letter 指選出與正確答案相符的選項字母。"},{"en":"In a reading test, students choose the correct letter after checking evidence in the passage.","zh":"在閱讀測驗中，學生查看文章證據後選出正確字母。"},{"en":"If the letter does not match the answer, the response may be marked wrong.","zh":"如果字母與答案不符，回應可能被判錯。"},{"en":"The phrase is a standard multiple-choice instruction.","zh":"這個片語是標準多項選擇指示。"}],"source":"66 - Salvador Dali.pdf","sourcePage":20},{"front":"departure for Paris","meaning":"前往巴黎；離開去巴黎","examples":[{"en":"Dalí’s departure for Paris changed the course of his career.","zh":"達利前往巴黎改變了他的事業走向。"},{"en":"Departure for Paris means leaving in order to go to Paris.","zh":"departure for Paris 指離開並前往巴黎。"},{"en":"A student’s departure for university may mark the start of a more independent life.","zh":"學生前往大學可能標誌更獨立生活的開始。"},{"en":"If departure leads to new contacts and ideas, it can change a career path.","zh":"如果離開帶來新人脈和新想法，就可以改變事業道路。"},{"en":"The phrase focuses on the act of leaving toward a destination.","zh":"這個片語集中於離開並前往目的地的行動。"}],"source":"66 - Salvador Dali.pdf","sourcePage":20},{"front":"be inspired by a desire to","meaning":"由想要……的渴望所激發","examples":[{"en":"His departure was inspired by a desire to learn more.","zh":"他的離開是由想學更多的渴望所激發。"},{"en":"Be inspired by a desire to means be motivated by a wish to do something.","zh":"be inspired by a desire to 指被做某事的願望所推動。"},{"en":"A student may join a debate club inspired by a desire to speak more confidently.","zh":"學生可能由想更有信心說話的渴望所激發而加入辯論社。"},{"en":"If a journey is inspired by a desire to improve, it may involve sacrifice and effort.","zh":"如果旅程由自我提升的渴望所激發，它可能涉及犧牲和努力。"},{"en":"The phrase explains the motivation behind an action.","zh":"這個片語解釋行動背後的動機。"}],"source":"66 - Salvador Dali.pdf","sourcePage":20},{"front":"be disgraced at","meaning":"在……蒙羞","examples":[{"en":"The option suggests that Dalí was disgraced at the Academy.","zh":"該選項暗示達利在學院蒙羞。"},{"en":"Be disgraced at means suffer shame or public loss of respect in a particular place or institution.","zh":"be disgraced at 指在某地方或機構遭受羞辱或失去公眾尊重。"},{"en":"A student may feel disgraced at school after being caught cheating.","zh":"學生作弊被發現後，可能覺得在學校蒙羞。"},{"en":"If someone leaves an institution after conflict, people may ask whether they were disgraced or simply dissatisfied.","zh":"如果某人在衝突後離開機構，人們可能問他是蒙羞離開還是單純不滿。"},{"en":"The phrase describes shame connected with a setting.","zh":"這個片語描述與某環境相關的羞恥。"}],"source":"66 - Salvador Dali.pdf","sourcePage":20},{"front":"to blame for","meaning":"是……的原因；應為……負責","examples":[{"en":"The option asks whether Paris was to blame for his failure to graduate.","zh":"該選項問巴黎是否是他未能畢業的原因。"},{"en":"To blame for means responsible for causing a problem or failure.","zh":"to blame for 指對造成問題或失敗負責。"},{"en":"Poor planning may be to blame for a delayed school trip.","zh":"規劃不善可能是學校旅行延誤的原因。"},{"en":"If someone is wrongly blamed, the real cause may be ignored.","zh":"如果某人被錯誤歸咎，真正原因可能被忽視。"},{"en":"The phrase identifies responsibility for a negative result.","zh":"這個片語指出負面結果的責任。"}],"source":"66 - Salvador Dali.pdf","sourcePage":20},{"front":"failure to complete","meaning":"未能完成","examples":[{"en":"The question refers to Dalí’s failure to complete his Academy degree.","zh":"題目提到達利未能完成學院學位。"},{"en":"Failure to complete means not successfully finishing something required.","zh":"failure to complete 指未能成功完成所需事項。"},{"en":"A student’s failure to complete coursework may affect their final grade.","zh":"學生未能完成課業可能影響最終成績。"},{"en":"If someone fails to complete a degree, they may still build a career through other routes.","zh":"如果某人未能完成學位，仍可能透過其他途徑建立事業。"},{"en":"The phrase focuses on an unfinished requirement.","zh":"這個片語集中於未完成的要求。"}],"source":"66 - Salvador Dali.pdf","sourcePage":20},{"front":"a quest for self-improvement","meaning":"追求自我提升","examples":[{"en":"Dalí’s journey to Paris can be seen as a quest for self-improvement.","zh":"達利前往巴黎可被視為追求自我提升。"},{"en":"A quest for self-improvement is a serious effort to become better, more skilled, or more knowledgeable.","zh":"a quest for self-improvement 指認真努力變得更好、更有技能或更有知識。"},{"en":"Joining an evening English course can be part of a quest for self-improvement.","zh":"參加晚間英語課可以是追求自我提升的一部分。"},{"en":"If someone moves city to learn from better teachers, the move may be a quest for growth.","zh":"如果某人搬到另一城市向更好老師學習，這個遷移可能是追求成長。"},{"en":"The phrase presents personal development as a purposeful journey.","zh":"這個片語把個人發展呈現為有目的旅程。"}],"source":"66 - Salvador Dali.pdf","sourcePage":20},{"front":"come to represent","meaning":"逐漸代表","examples":[{"en":"Dalí came to represent the Surrealist movement.","zh":"達利逐漸代表超現實主義運動。"},{"en":"Come to represent means gradually become seen as a symbol or main example of something.","zh":"come to represent 指逐漸被視為某事物的象徵或主要例子。"},{"en":"A school uniform may come to represent discipline and shared identity.","zh":"校服可能逐漸代表紀律和共同身份。"},{"en":"If one artist becomes strongly linked with a movement, their image may represent it publicly.","zh":"如果一位藝術家與某運動密切相連，其形象可能在公眾眼中代表該運動。"},{"en":"The phrase describes a change in public meaning over time.","zh":"這個片語描述公眾意義隨時間改變。"}],"source":"66 - Salvador Dali.pdf","sourcePage":20},{"front":"due to","meaning":"由於","examples":[{"en":"Dalí’s fame was partly due to his memorable images.","zh":"達利的名聲部分由於他令人難忘的形象。"},{"en":"Due to means because of or caused by something.","zh":"due to 指因為或由某事造成。"},{"en":"The bus was late due to heavy traffic.","zh":"巴士因交通繁忙而遲到。"},{"en":"If popularity is due to one strong image, that image becomes central to memory.","zh":"如果受歡迎是由於一個強烈形象，該形象就成為記憶核心。"},{"en":"The phrase introduces a cause.","zh":"這個片語引出原因。"}],"source":"66 - Salvador Dali.pdf","sourcePage":21},{"front":"personal endorsement","meaning":"個人背書；個人支持","examples":[{"en":"The question mentions a personal endorsement from André Breton.","zh":"題目提到 André Breton 的個人支持。"},{"en":"Personal endorsement means direct approval or support from a named person.","zh":"personal endorsement 指來自具名人士的直接認可或支持。"},{"en":"A recommendation letter is a personal endorsement from a teacher or employer.","zh":"推薦信是來自老師或僱主的個人背書。"},{"en":"If a respected leader gives a personal endorsement, others may trust the person more.","zh":"如果受尊敬的領袖給予個人支持，其他人可能更信任該人。"},{"en":"The phrase focuses on support linked to an individual’s authority.","zh":"這個片語集中於與個人權威相關的支持。"}],"source":"66 - Salvador Dali.pdf","sourcePage":21},{"front":"fellow artist","meaning":"藝術家同儕","examples":[{"en":"Dalí was admired by some fellow artists.","zh":"達利受到一些藝術家同儕欣賞。"},{"en":"A fellow artist is another artist working in the same general field or community.","zh":"fellow artist 指在同一大致領域或社群工作的另一位藝術家。"},{"en":"A painter may receive advice from fellow artists during a group exhibition.","zh":"畫家可能在群展期間從藝術家同儕獲得建議。"},{"en":"If fellow artists respect someone, that respect can strengthen professional reputation.","zh":"如果藝術家同儕尊重某人，這種尊重可以加強專業聲譽。"},{"en":"The phrase refers to peers within the arts.","zh":"這個片語指藝術圈內的同輩。"}],"source":"66 - Salvador Dali.pdf","sourcePage":21},{"front":"depict memorable images","meaning":"描繪令人難忘的形象","examples":[{"en":"Dalí depicted some of the most memorable images of Surrealism.","zh":"達利描繪了超現實主義中一些最令人難忘的形象。"},{"en":"Depict memorable images means create visual scenes that people remember clearly.","zh":"depict memorable images 指創造令人清楚記得的視覺場景。"},{"en":"A film poster may depict a memorable image that viewers recognise years later.","zh":"電影海報可能描繪令人難忘的形象，讓觀眾多年後仍認得。"},{"en":"If an artist depicts strong images, the work may become famous beyond art experts.","zh":"如果藝術家描繪強烈形象，作品可能在藝術專家以外也成名。"},{"en":"The phrase connects visual creation with lasting memory.","zh":"這個片語把視覺創作與持久記憶連接起來。"}],"source":"66 - Salvador Dali.pdf","sourcePage":21},{"front":"have a better understanding of","meaning":"對……有更深入理解","examples":[{"en":"The option refers to having a better understanding of psychoanalysis.","zh":"該選項指對精神分析學有更深入理解。"},{"en":"Have a better understanding of means know something more clearly or deeply than before.","zh":"have a better understanding of 指比以前更清楚或更深入地認識某事。"},{"en":"Students have a better understanding of grammar when they see mistakes corrected with explanations.","zh":"當學生看見錯誤被連同解釋改正，就會對文法有更深入理解。"},{"en":"If artists understand a theory better, they may use it more effectively in their work.","zh":"如果藝術家更理解理論，可能更有效地在作品中使用它。"},{"en":"The phrase focuses on improved knowledge.","zh":"這個片語集中於知識提升。"}],"source":"66 - Salvador Dali.pdf","sourcePage":21},{"front":"peers","meaning":"同輩；同儕","examples":[{"en":"Dalí compared himself with his artistic peers.","zh":"達利把自己與藝術同儕比較。"},{"en":"Peers are people of similar age, status, role, or level in the same group.","zh":"peers 指同一群體中年齡、地位、角色或水平相近的人。"},{"en":"Students often compare exam results with their peers.","zh":"學生常把考試成績與同輩比較。"},{"en":"If someone sees themselves as superior to peers, conflict may arise.","zh":"如果某人認為自己優於同儕，可能出現衝突。"},{"en":"The word refers to equals or near-equals.","zh":"這個詞指平輩或接近平輩的人。"}],"source":"66 - Salvador Dali.pdf","sourcePage":21},{"front":"accessible to","meaning":"對……來說容易理解","examples":[{"en":"Some art is more accessible to viewers than Dalí’s paintings.","zh":"有些藝術對觀眾來說比達利的畫作更容易理解。"},{"en":"Accessible to means easy for a particular group to understand, use, or reach.","zh":"accessible to 指對某群體而言容易理解、使用或接觸。"},{"en":"A museum label written in simple language makes art more accessible to children.","zh":"用簡單語言寫成的博物館標籤，令藝術對兒童更容易理解。"},{"en":"If a painting is not accessible to viewers, they may need guidance or background information.","zh":"如果畫作對觀眾來說不易理解，他們可能需要導賞或背景資料。"},{"en":"The phrase describes ease of understanding or access.","zh":"這個片語描述理解或接觸的容易程度。"}],"source":"66 - Salvador Dali.pdf","sourcePage":21},{"front":"loaded with","meaning":"充滿","examples":[{"en":"Dalí’s work was loaded with secret symbolism.","zh":"達利的作品充滿隱秘象徵。"},{"en":"Loaded with means full of a large amount of something, often meaning-heavy.","zh":"loaded with 指充滿大量某物，通常是含義豐富的內容。"},{"en":"A political speech may be loaded with emotional language and hidden messages.","zh":"政治演說可能充滿情感語言和隱藏訊息。"},{"en":"If a painting is loaded with symbols, viewers may need time to decode it.","zh":"如果畫作充滿象徵，觀眾可能需要時間解碼。"},{"en":"The phrase suggests dense meaning or content.","zh":"這個片語暗示密集意思或內容。"}],"source":"66 - Salvador Dali.pdf","sourcePage":21},{"front":"secret symbolism","meaning":"隱秘象徵","examples":[{"en":"Dalí’s paintings were loaded with secret symbolism.","zh":"達利的畫作充滿隱秘象徵。"},{"en":"Secret symbolism means hidden meanings expressed through objects, colours, or images.","zh":"secret symbolism 指透過物件、顏色或圖像表達的隱藏意思。"},{"en":"A film may use secret symbolism by showing a broken mirror whenever a character lies.","zh":"電影可能每當角色說謊就展示破鏡，使用隱秘象徵。"},{"en":"If viewers do not know the symbols, the work may seem confusing.","zh":"如果觀眾不知道象徵，作品可能顯得令人困惑。"},{"en":"The phrase describes meaning hidden beneath the surface.","zh":"這個片語描述表面之下的隱藏意思。"}],"source":"66 - Salvador Dali.pdf","sourcePage":21},{"front":"a channel for personal expression","meaning":"個人表達的渠道","examples":[{"en":"Dalí’s art served as a channel for personal expression.","zh":"達利的藝術成為個人表達的渠道。"},{"en":"A channel for personal expression is a way to show one’s thoughts, feelings, fears, or identity.","zh":"a channel for personal expression 指展示自己思想、感受、恐懼或身份的方式。"},{"en":"A diary can be a channel for personal expression for a shy student.","zh":"日記可以成為害羞學生個人表達的渠道。"},{"en":"If art becomes personal expression, private emotions can take public form.","zh":"如果藝術成為個人表達，私人情感就能以公共形式出現。"},{"en":"The phrase describes a medium through which inner life is shown.","zh":"這個片語描述呈現內在生活的媒介。"}],"source":"66 - Salvador Dali.pdf","sourcePage":21},{"front":"financial undertaking","meaning":"財務性質的工作；賺錢項目","examples":[{"en":"Some projects were financial undertakings as well as artistic ones.","zh":"有些項目既是藝術項目，也是財務性質的工作。"},{"en":"A financial undertaking is a project or activity involving money, cost, profit, or financial risk.","zh":"financial undertaking 指涉及金錢、成本、利潤或財務風險的項目或活動。"},{"en":"Opening a small café is a financial undertaking because rent, staff, and supplies must be paid.","zh":"開小咖啡店是一項財務性質的工作，因為要支付租金、員工和物資。"},{"en":"If an art project is also a financial undertaking, commercial success may influence decisions.","zh":"如果藝術項目也是賺錢項目，商業成功可能影響決定。"},{"en":"The phrase highlights the money side of a project.","zh":"這個片語突出項目的金錢面向。"}],"source":"66 - Salvador Dali.pdf","sourcePage":22},{"front":"prove more popular","meaning":"證明更受歡迎","examples":[{"en":"Dalí’s work proved more popular with the public than with some critics.","zh":"達利的作品證明在公眾中比在某些評論家中更受歡迎。"},{"en":"Prove more popular means turn out to be liked more by one group than another.","zh":"prove more popular 指結果顯示某物比另一群體更受某一群體喜歡。"},{"en":"A school app may prove more popular with students than with teachers.","zh":"學校應用程式可能證明在學生中比在老師中更受歡迎。"},{"en":"If public taste differs from expert judgement, a work may still succeed commercially.","zh":"如果公眾品味與專家判斷不同，作品仍可能在商業上成功。"},{"en":"The phrase compares actual popularity after a response is seen.","zh":"這個片語在反應出現後比較實際受歡迎程度。"}],"source":"66 - Salvador Dali.pdf","sourcePage":22},{"front":"two correct answers","meaning":"兩個正確答案","examples":[{"en":"The question states that there are two correct answers.","zh":"題目說有兩個正確答案。"},{"en":"Two correct answers means exactly two options should be chosen.","zh":"two correct answers 指應選出正好兩個選項。"},{"en":"In a reading test, students may lose marks if they choose one answer when two are required.","zh":"在閱讀測驗中，如果需要兩個答案而學生只選一個，可能失分。"},{"en":"If a question says two correct answers, students should look for two separate pieces of evidence.","zh":"如果題目說有兩個正確答案，學生應尋找兩個獨立證據。"},{"en":"The phrase gives an important exam instruction.","zh":"這個片語給出重要考試指示。"}],"source":"66 - Salvador Dali.pdf","sourcePage":22},{"front":"be most likely to be remembered for","meaning":"最有可能因……被記住","examples":[{"en":"Dalí is most likely to be remembered for his unusual paintings and eccentricity.","zh":"達利最有可能因其不尋常畫作和古怪作風被記住。"},{"en":"Be most likely to be remembered for means probably be remembered mainly because of something.","zh":"be most likely to be remembered for 指很可能主要因某事而被記住。"},{"en":"A teacher may be most likely to be remembered for kindness rather than strict rules.","zh":"老師最有可能因善良而不是嚴格規則被記住。"},{"en":"If one feature stands out strongly, it becomes the main thing people remember.","zh":"如果一個特徵非常突出，它就成為人們記住的主要內容。"},{"en":"The phrase asks what will define someone in public memory.","zh":"這個片語詢問甚麼會在公眾記憶中定義某人。"}],"source":"66 - Salvador Dali.pdf","sourcePage":22},{"front":"contribution to","meaning":"對……的貢獻","examples":[{"en":"The option refers to Dalí’s contribution to psychoanalysis.","zh":"該選項提到達利對精神分析學的貢獻。"},{"en":"Contribution to means something someone gives, adds, or does that helps a field or activity.","zh":"contribution to 指某人給予、加入或做出的有助於某領域或活動的事。"},{"en":"A volunteer’s contribution to a school fair may include planning games and serving food.","zh":"義工對學校市集的貢獻可能包括策劃遊戲和提供食物。"},{"en":"If an artist contributes to a field, that field changes because of their work.","zh":"如果藝術家對某領域有貢獻，該領域會因其作品而改變。"},{"en":"The phrase focuses on positive input or influence.","zh":"這個片語集中於正面投入或影響。"}],"source":"66 - Salvador Dali.pdf","sourcePage":22},{"front":"the field of psychoanalysis","meaning":"精神分析學領域","examples":[{"en":"Dalí was influenced by the field of psychoanalysis.","zh":"達利受精神分析學領域影響。"},{"en":"The field of psychoanalysis is the area of study and practice connected with unconscious mental processes.","zh":"the field of psychoanalysis 指與潛意識心理過程有關的研究和實踐範疇。"},{"en":"Students in psychology may study the field of psychoanalysis as part of the history of therapy.","zh":"心理學學生可能把精神分析學領域作為治療史的一部分來研究。"},{"en":"If an artist uses ideas from psychoanalysis, hidden emotions may appear in the work.","zh":"如果藝術家使用精神分析學思想，隱藏情感可能出現在作品中。"},{"en":"The phrase refers to a specialised intellectual and clinical area.","zh":"這個片語指專門的思想和臨床領域。"}],"source":"66 - Salvador Dali.pdf","sourcePage":22},{"front":"diverse output","meaning":"多元化的作品產出","examples":[{"en":"Dalí produced a diverse output of artistic works.","zh":"達利創作了多元化的藝術作品。"},{"en":"Diverse output means a wide range of work in different forms, styles, or media.","zh":"diverse output 指不同形式、風格或媒介的廣泛作品。"},{"en":"A writer’s diverse output may include novels, poems, essays, and film scripts.","zh":"作家的多元化作品產出可能包括小說、詩、散文和電影劇本。"},{"en":"If an artist has diverse output, audiences may know different sides of their creativity.","zh":"如果藝術家有多元化作品，觀眾可能認識其創意的不同面向。"},{"en":"The phrase highlights variety in production.","zh":"這個片語突出創作產出的多樣性。"}],"source":"66 - Salvador Dali.pdf","sourcePage":22},{"front":"artistic works","meaning":"藝術作品","examples":[{"en":"Dalí’s artistic works included paintings and design projects.","zh":"達利的藝術作品包括畫作和設計項目。"},{"en":"Artistic works are creations made for artistic expression, such as paintings, sculptures, films, or designs.","zh":"artistic works 指為藝術表達而創作的作品，例如畫作、雕塑、電影或設計。"},{"en":"A school exhibition may display students’ artistic works from the whole year.","zh":"學校展覽可能展示學生全年藝術作品。"},{"en":"If artistic works are varied, they may attract different types of viewers.","zh":"如果藝術作品多樣化，可能吸引不同類型觀眾。"},{"en":"The phrase refers to created art objects or projects.","zh":"這個片語指被創作出來的藝術物件或項目。"}],"source":"66 - Salvador Dali.pdf","sourcePage":22},{"front":"inappropriate behaviour","meaning":"不恰當行為","examples":[{"en":"Dalí was sometimes remembered for inappropriate behaviour.","zh":"達利有時因不恰當行為而被記住。"},{"en":"Inappropriate behaviour means behaviour that does not fit the situation, rules, or expected respect.","zh":"inappropriate behaviour 指不符合情境、規則或應有尊重的行為。"},{"en":"Shouting during a quiet ceremony is inappropriate behaviour.","zh":"在安靜典禮中大喊是不恰當行為。"},{"en":"If inappropriate behaviour attracts attention, it may damage how people view a person’s work.","zh":"如果不恰當行為吸引注意，可能損害人們如何看待某人的作品。"},{"en":"The phrase describes behaviour judged as unsuitable.","zh":"這個片語描述被判斷為不合適的行為。"}],"source":"66 - Salvador Dali.pdf","sourcePage":22},{"front":"eccentricity","meaning":"古怪作風","examples":[{"en":"Dalí’s eccentricity made him famous beyond the art world.","zh":"達利的古怪作風令他在藝術界以外也成名。"},{"en":"Eccentricity means unusual behaviour, style, or personality.","zh":"eccentricity 指不尋常的行為、風格或個性。"},{"en":"A professor’s eccentricity may include wearing bright hats and teaching with puppets.","zh":"教授的古怪作風可能包括戴鮮色帽子和用木偶教書。"},{"en":"If eccentricity is entertaining, it can attract public attention; if excessive, it may distract from the work.","zh":"如果古怪作風有娛樂性，可以吸引公眾注意；如果過度，可能分散對作品的注意。"},{"en":"The word describes unusual individuality.","zh":"這個詞描述不尋常的個人特色。"}],"source":"66 - Salvador Dali.pdf","sourcePage":22},{"front":"striking and unusual paintings","meaning":"醒目而與眾不同的畫作","examples":[{"en":"Dalí is remembered for his striking and unusual paintings.","zh":"達利因其醒目而與眾不同的畫作被記住。"},{"en":"Striking and unusual paintings are paintings that strongly catch attention and look different from normal works.","zh":"striking and unusual paintings 指強烈吸引注意並看起來不同於普通作品的畫作。"},{"en":"A gallery visitor may stop immediately in front of a striking and unusual painting.","zh":"畫廊訪客可能在醒目而與眾不同的畫作前立即停下。"},{"en":"If paintings are striking, people notice them; if unusual, they may remember them longer.","zh":"如果畫作醒目，人們會注意到；如果與眾不同，可能記得更久。"},{"en":"The phrase combines visual force with originality.","zh":"這個片語結合視覺力量和原創性。"}],"source":"66 - Salvador Dali.pdf","sourcePage":23},{"front":"an attempt to create","meaning":"嘗試創作","examples":[{"en":"The option refers to an attempt to create accessible works.","zh":"該選項提到嘗試創作容易理解的作品。"},{"en":"An attempt to create means an effort to produce or make something.","zh":"an attempt to create 指努力製作或創造某物。"},{"en":"A school project may be an attempt to create a quieter study space.","zh":"學校項目可能是嘗試創造更安靜自修空間。"},{"en":"If an attempt to create clearer art fails, viewers may still find the work confusing.","zh":"如果嘗試創作更清晰藝術失敗，觀眾仍可能覺得作品困惑。"},{"en":"The phrase focuses on effort, not guaranteed success.","zh":"這個片語集中於努力，而不是保證成功。"}],"source":"66 - Salvador Dali.pdf","sourcePage":23},{"front":"accessible works","meaning":"容易理解的作品","examples":[{"en":"Some artists try to create accessible works for the public.","zh":"有些藝術家嘗試為公眾創作容易理解的作品。"},{"en":"Accessible works are works that ordinary people can understand, enjoy, or approach without specialised knowledge.","zh":"accessible works 指普通人不需要專門知識也能理解、欣賞或接近的作品。"},{"en":"A museum may add simple labels to make difficult paintings more accessible.","zh":"博物館可能加入簡單標籤，令困難畫作更容易理解。"},{"en":"If works are too private or symbolic, they may be less accessible to viewers.","zh":"如果作品太私人或太象徵化，對觀眾來說可能較不易理解。"},{"en":"The phrase focuses on ease of understanding and public access.","zh":"這個片語集中於理解容易度和公眾可及性。"}],"source":"66 - Salvador Dali.pdf","sourcePage":23},{"front":"convey about","meaning":"表達關於……的看法","examples":[{"en":"The question asks what the writer conveys about Dalí’s early life.","zh":"題目問作者表達了關於達利早年生活的甚麼看法。"},{"en":"Convey about means communicate or suggest an idea about a topic.","zh":"convey about 指傳達或暗示關於某主題的想法。"},{"en":"A teacher’s comments may convey concern about a student’s progress.","zh":"老師的評語可能表達對學生進度的擔心。"},{"en":"If a writer describes early ambition, they may convey admiration or criticism.","zh":"如果作者描述早期抱負，可能表達欣賞或批評。"},{"en":"The phrase asks what impression or message is being communicated.","zh":"這個片語詢問正在傳達的印象或訊息。"}],"source":"66 - Salvador Dali.pdf","sourcePage":23},{"front":"childhood and student days","meaning":"童年和學生時期","examples":[{"en":"The writer discusses Dalí’s childhood and student days.","zh":"作者討論達利的童年和學生時期。"},{"en":"Childhood and student days means the period when someone was young and studying.","zh":"childhood and student days 指某人年幼和求學的時期。"},{"en":"A biography may describe a scientist’s childhood and student days to explain early interests.","zh":"傳記可能描述科學家的童年和學生時期，以解釋早期興趣。"},{"en":"If childhood and student days show strong ambition, later success may seem less surprising.","zh":"如果童年和學生時期展現強烈抱負，後來成功可能較不令人意外。"},{"en":"The phrase refers to early life and education.","zh":"這個片語指早年生活和教育。"}],"source":"66 - Salvador Dali.pdf","sourcePage":23},{"front":"inability to pursue a goal","meaning":"無法追求目標","examples":[{"en":"The option refers to an inability to pursue a goal.","zh":"該選項提到無法追求目標。"},{"en":"Inability to pursue a goal means not being able to continue working toward an aim.","zh":"inability to pursue a goal 指不能繼續朝某目標努力。"},{"en":"A student’s inability to pursue a goal may come from poor health, lack of support, or unclear planning.","zh":"學生無法追求目標可能來自健康差、缺乏支援或規劃不清。"},{"en":"If someone cannot pursue a goal to completion, ambition alone is not enough.","zh":"如果某人不能把目標追求至完成，單靠抱負並不足夠。"},{"en":"The phrase describes a failure of sustained effort or capacity.","zh":"這個片語描述持續努力或能力上的失敗。"}],"source":"66 - Salvador Dali.pdf","sourcePage":23},{"front":"until its conclusion","meaning":"直到完成為止","examples":[{"en":"The option suggests he could not pursue a goal until its conclusion.","zh":"該選項暗示他無法追求目標直到完成為止。"},{"en":"Until its conclusion means until something is finished or brought to an end.","zh":"until its conclusion 指直到某事完成或結束。"},{"en":"Students should follow an experiment until its conclusion before writing results.","zh":"學生應完成整個實驗後才寫結果。"},{"en":"If someone abandons a project before its conclusion, the final outcome cannot be tested.","zh":"如果某人在項目完成前放棄，就無法測試最終結果。"},{"en":"The phrase focuses on completion.","zh":"這個片語集中於完成。"}],"source":"66 - Salvador Dali.pdf","sourcePage":23},{"front":"mental instability","meaning":"精神不穩定","examples":[{"en":"The option mentions mental instability in Dalí’s ambitions.","zh":"該選項提到達利抱負中的精神不穩定。"},{"en":"Mental instability means serious difficulty maintaining steady emotions, thoughts, or behaviour.","zh":"mental instability 指難以維持穩定情緒、思想或行為的嚴重情況。"},{"en":"A film character with mental instability may act unpredictably and need support.","zh":"有精神不穩定的電影角色可能行為難以預測並需要支援。"},{"en":"If a writer mentions instability, they may be suggesting that behaviour seems uncontrolled.","zh":"如果作者提到不穩定，可能暗示行為看似失控。"},{"en":"The phrase should be used carefully because it relates to mental health.","zh":"這個片語應小心使用，因為它與心理健康有關。"}],"source":"66 - Salvador Dali.pdf","sourcePage":23},{"front":"be evident in","meaning":"在……中顯而易見","examples":[{"en":"Dalí’s confidence was evident in his comments.","zh":"達利的自信在他的評論中顯而易見。"},{"en":"Be evident in means be clearly shown in a particular action, statement, or detail.","zh":"be evident in 指在某行動、陳述或細節中清楚顯示。"},{"en":"A student’s preparation is evident in a well-organised essay.","zh":"學生的準備在組織良好的文章中顯而易見。"},{"en":"If confidence is evident in someone’s words, listeners can hear it immediately.","zh":"如果自信在某人的言語中顯而易見，聽眾可立即聽出。"},{"en":"The phrase points to where something can be seen.","zh":"這個片語指出某事在哪裡可被看見。"}],"source":"66 - Salvador Dali.pdf","sourcePage":23},{"front":"grandiose ambitions","meaning":"宏大的抱負","examples":[{"en":"Dalí had grandiose ambitions from an early age.","zh":"達利從早年起就有宏大的抱負。"},{"en":"Grandiose ambitions are extremely large, impressive, and sometimes unrealistic goals.","zh":"grandiose ambitions 指極其龐大、令人印象深刻且有時不切實際的目標。"},{"en":"A teenager with grandiose ambitions may plan to build a global company before learning basic business skills.","zh":"有宏大抱負的青少年可能在學會基本商業技巧前，已計劃建立全球公司。"},{"en":"If ambition is grandiose, it can inspire effort but also sound arrogant.","zh":"如果抱負宏大，它可以激發努力，但也可能聽起來傲慢。"},{"en":"The phrase suggests oversized confidence and big dreams.","zh":"這個片語暗示過大的自信和遠大夢想。"}],"source":"66 - Salvador Dali.pdf","sourcePage":23},{"front":"supreme confidence","meaning":"極大的自信","examples":[{"en":"Dalí showed supreme confidence in his own abilities.","zh":"達利對自己的能力展現極大的自信。"},{"en":"Supreme confidence means extremely strong belief in oneself.","zh":"supreme confidence 指對自己極其強烈的信念。"},{"en":"A speaker with supreme confidence can face a large audience without appearing nervous.","zh":"有極大自信的演講者可以面對大量觀眾而不顯得緊張。"},{"en":"If confidence becomes supreme, it may impress people or make them uncomfortable.","zh":"如果自信變得極大，可能令人印象深刻，也可能令人不舒服。"},{"en":"The phrase suggests confidence at the highest level.","zh":"這個片語暗示最高程度的自信。"}],"source":"66 - Salvador Dali.pdf","sourcePage":24},{"front":"one’s own abilities","meaning":"自己的能力","examples":[{"en":"Dalí had great confidence in his own abilities.","zh":"達利對自己的能力有極大信心。"},{"en":"One’s own abilities means the skills, talents, or capacities a person personally has.","zh":"one’s own abilities 指一個人自己擁有的技能、才華或能力。"},{"en":"Students gain confidence in their own abilities when they solve problems without help.","zh":"當學生不用幫助解決問題，就會對自己的能力建立信心。"},{"en":"If someone doubts their own abilities, encouragement and practice can help.","zh":"如果某人懷疑自己的能力，鼓勵和練習可以幫忙。"},{"en":"The phrase focuses on personal capability.","zh":"這個片語集中於個人能力。"}],"source":"66 - Salvador Dali.pdf","sourcePage":24},{"front":"obviously superior intelligence","meaning":"明顯較高的智力","examples":[{"en":"The option refers to Dalí’s obviously superior intelligence.","zh":"該選項提到達利明顯較高的智力。"},{"en":"Obviously superior intelligence means intelligence that appears clearly higher than that of others.","zh":"obviously superior intelligence 指看起來清楚高於他人的智力。"},{"en":"A child who solves advanced maths problems may seem to have superior intelligence, but effort still matters.","zh":"能解決進階數學問題的孩子可能看似有較高智力，但努力仍重要。"},{"en":"If a person is described this way, the wording may sound admiring or arrogant.","zh":"如果某人被這樣描述，措辭可能聽起來讚賞或傲慢。"},{"en":"The phrase makes a strong comparison of mental ability.","zh":"這個片語對智力能力作出強烈比較。"}],"source":"66 - Salvador Dali.pdf","sourcePage":24},{"front":"turn against","meaning":"轉而反對","examples":[{"en":"Some critics turned against Dalí’s later work.","zh":"有些評論家轉而反對達利的後期作品。"},{"en":"Turn against means stop supporting someone or something and become critical or hostile.","zh":"turn against 指停止支持某人或某事，並變得批評或敵對。"},{"en":"Fans may turn against a team if they feel the players no longer try hard.","zh":"如果球迷覺得球員不再努力，可能轉而反對球隊。"},{"en":"If critics turn against an artist, reviews may become harsher.","zh":"如果評論家轉而反對藝術家，評論可能變得更嚴厲。"},{"en":"The phrase describes a shift from support to opposition.","zh":"這個片語描述由支持轉向反對。"}],"source":"66 - Salvador Dali.pdf","sourcePage":24},{"front":"a reaction to","meaning":"對……的反應","examples":[{"en":"The criticism was a reaction to Dalí’s later choices.","zh":"這些批評是對達利後期選擇的反應。"},{"en":"A reaction to means a response caused by something.","zh":"a reaction to 指由某事引起的回應。"},{"en":"A student’s silence may be a reaction to harsh criticism from a teacher.","zh":"學生沉默可能是對老師嚴厲批評的反應。"},{"en":"If critics dislike commercial work, their comments may be a reaction to the artist’s money-making choices.","zh":"如果評論家不喜歡商業作品，其評論可能是對藝術家賺錢選擇的反應。"},{"en":"The phrase connects a response with its cause.","zh":"這個片語把回應與原因連接起來。"}],"source":"66 - Salvador Dali.pdf","sourcePage":24},{"front":"obscure works","meaning":"晦澀難懂的作品","examples":[{"en":"Some viewers found Dalí’s works obscure.","zh":"有些觀眾覺得達利的作品晦澀難懂。"},{"en":"Obscure works are works that are difficult to understand because their meaning is hidden or unclear.","zh":"obscure works 指因意思隱藏或不清而難以理解的作品。"},{"en":"A poem full of private symbols may become obscure to ordinary readers.","zh":"充滿私人象徵的詩可能對普通讀者變得晦澀難懂。"},{"en":"If art is obscure, viewers may need explanations before they can appreciate it.","zh":"如果藝術晦澀難懂，觀眾可能需要解釋才能欣賞。"},{"en":"The phrase describes works with unclear meaning.","zh":"這個片語描述意思不清的作品。"}],"source":"66 - Salvador Dali.pdf","sourcePage":24},{"front":"devote more time to","meaning":"投放更多時間於","examples":[{"en":"The option suggests Dalí devoted more time to commercials than painting.","zh":"該選項暗示達利投放更多時間於廣告而不是繪畫。"},{"en":"Devote more time to means spend a greater amount of time on one activity than another.","zh":"devote more time to 指在某活動上花更多時間。"},{"en":"A student may devote more time to speaking practice before an oral exam.","zh":"學生可能在口試前投放更多時間於口語練習。"},{"en":"If an artist devotes more time to advertising than art, critics may question priorities.","zh":"如果藝術家投放更多時間於廣告而不是藝術，評論家可能質疑其優先次序。"},{"en":"The phrase compares time and attention.","zh":"這個片語比較時間和注意力。"}],"source":"66 - Salvador Dali.pdf","sourcePage":24},{"front":"no longer do justice to","meaning":"不再配得上；未能充分展現","examples":[{"en":"Critics felt his later work no longer did justice to his talent.","zh":"評論家覺得他的後期作品不再充分展現其才華。"},{"en":"No longer do justice to means no longer show the true quality or ability of someone or something.","zh":"no longer do justice to 指不再展現某人或某事物的真正質素或能力。"},{"en":"A rushed essay may no longer do justice to a student’s real English ability.","zh":"倉促寫成的文章可能無法充分展現學生真正英語能力。"},{"en":"If an artist’s work becomes careless, it may fail to show the talent they still have.","zh":"如果藝術家的作品變得粗心，可能無法顯示他仍擁有的才華。"},{"en":"The phrase suggests something deserves better representation.","zh":"這個片語暗示某事值得更好呈現。"}],"source":"66 - Salvador Dali.pdf","sourcePage":24},{"front":"overshadow his work","meaning":"掩蓋他的作品","examples":[{"en":"Some believed Dalí’s behaviour overshadowed his work.","zh":"有些人認為達利的行為掩蓋了他的作品。"},{"en":"Overshadow his work means attract so much attention that people notice the behaviour more than the art.","zh":"overshadow his work 指吸引太多注意，以致人們注意行為多於藝術。"},{"en":"A singer’s scandal may overshadow their new album.","zh":"歌手的醜聞可能掩蓋其新專輯。"},{"en":"If publicity becomes too loud, it can hide the quality of the actual work.","zh":"如果宣傳太張揚，可能遮蓋實際作品的質素。"},{"en":"The phrase describes one thing taking attention away from another.","zh":"這個片語描述一件事搶走另一件事的注意力。"}],"source":"66 - Salvador Dali.pdf","sourcePage":24},{"front":"attitude towards","meaning":"對……的態度","examples":[{"en":"The question asks about the writer’s attitude towards Dalí’s life and work.","zh":"題目問作者對達利人生和作品的態度。"},{"en":"Attitude towards means a person’s opinion, feeling, or position about someone or something.","zh":"attitude towards 指一個人對某人或某事的意見、感受或立場。"},{"en":"A teacher’s attitude towards mistakes affects whether students feel safe to try.","zh":"老師對錯誤的態度會影響學生是否安心嘗試。"},{"en":"If a writer praises and criticises someone, the attitude may be mixed.","zh":"如果作者既讚賞又批評某人，態度可能是複雜的。"},{"en":"The phrase focuses on viewpoint.","zh":"這個片語集中於觀點。"}],"source":"66 - Salvador Dali.pdf","sourcePage":24},{"front":"promising beginnings","meaning":"充滿希望的開端","examples":[{"en":"Dalí had promising beginnings as a young artist.","zh":"達利作為年輕藝術家有充滿希望的開端。"},{"en":"Promising beginnings are early signs that someone or something may become successful.","zh":"promising beginnings 指早期跡象顯示某人或某事可能成功。"},{"en":"A new student has promising beginnings if they learn quickly and ask thoughtful questions.","zh":"如果新學生學得快並提出有思想的問題，就有充滿希望的開端。"},{"en":"If promising beginnings are followed by hard work, early potential may become achievement.","zh":"如果充滿希望的開端之後有努力，早期潛能可能變成成就。"},{"en":"The phrase describes hopeful early stages.","zh":"這個片語描述令人期待的早期階段。"}],"source":"66 - Salvador Dali.pdf","sourcePage":25},{"front":"waste his talents","meaning":"浪費才華","examples":[{"en":"Some critics believed Dalí wasted his talents.","zh":"有些評論家認為達利浪費才華。"},{"en":"Waste his talents means fail to use his abilities in the best or most meaningful way.","zh":"waste his talents 指未能以最好或最有意義方式使用他的能力。"},{"en":"A gifted student may waste their talents if they never practise or finish assignments.","zh":"有天分的學生如果從不練習或完成作業，可能浪費才華。"},{"en":"If an artist focuses only on money, critics may say they are wasting their talent.","zh":"如果藝術家只集中於金錢，評論家可能說他浪費才華。"},{"en":"The phrase expresses disappointment about unused ability.","zh":"這個片語表達對能力未被善用的失望。"}],"source":"66 - Salvador Dali.pdf","sourcePage":25},{"front":"make such an impact","meaning":"造成如此大的影響","examples":[{"en":"Few artists made such an impact during their lifetime.","zh":"很少藝術家在有生之年造成如此大的影響。"},{"en":"Make such an impact means have such a strong influence or effect.","zh":"make such an impact 指產生如此強烈的影響或效果。"},{"en":"A teacher can make a strong impact if former students still remember their advice years later.","zh":"如果舊生多年後仍記得老師的建議，老師就能造成強烈影響。"},{"en":"If an artist changes public imagination, they have made a major impact.","zh":"如果藝術家改變公眾想像，就造成重大影響。"},{"en":"The phrase emphasises the size of someone’s influence.","zh":"這個片語強調某人影響力的大小。"}],"source":"66 - Salvador Dali.pdf","sourcePage":25},{"front":"during his lifetime","meaning":"在有生之年","examples":[{"en":"Dalí achieved worldwide fame during his lifetime.","zh":"達利在有生之年獲得世界聲譽。"},{"en":"During his lifetime means while he was alive.","zh":"during his lifetime 指在他仍然在世時。"},{"en":"Some writers become famous only after death, but others are celebrated during their lifetime.","zh":"有些作家死後才成名，但另一些在有生之年已受讚賞。"},{"en":"If an artist sees their own museum open during their lifetime, their success is publicly recognised early.","zh":"如果藝術家在有生之年看到自己的博物館開幕，其成功就早已獲公眾認可。"},{"en":"The phrase contrasts life with posthumous recognition.","zh":"這個片語把生前與死後認可作對比。"}],"source":"66 - Salvador Dali.pdf","sourcePage":25},{"front":"focus more on … than …","meaning":"較注重……而不是……","examples":[{"en":"Some people focused more on Dalí’s behaviour than his talent.","zh":"有些人較注重達利的行為，而不是他的才華。"},{"en":"Focus more on … than … means give greater attention to one thing than another.","zh":"focus more on … than … 指較多注意一件事，而不是另一件事。"},{"en":"Some students focus more on grades than learning, so they memorise without understanding.","zh":"有些學生較注重分數而不是學習，所以只背誦而不理解。"},{"en":"If the public focuses more on behaviour than art, the artwork may receive less serious discussion.","zh":"如果公眾較注重行為而不是藝術，作品可能較少獲得認真討論。"},{"en":"The phrase clearly compares two priorities.","zh":"這個片語清楚比較兩個優先事項。"}],"source":"66 - Salvador Dali.pdf","sourcePage":25},{"front":"despite his failings","meaning":"儘管他有缺點","examples":[{"en":"Despite his failings, Dalí left an enduring legacy.","zh":"儘管他有缺點，達利留下持久的遺產。"},{"en":"Despite his failings means although he had weaknesses, mistakes, or faults.","zh":"despite his failings 指雖然他有弱點、錯誤或缺陷。"},{"en":"Despite his failings as a manager, he helped the company survive a crisis.","zh":"儘管他作為經理有缺點，他仍幫助公司渡過危機。"},{"en":"If someone has failings but also creates lasting value, judgement becomes complex.","zh":"如果某人有缺點但也創造持久價值，判斷就變得複雜。"},{"en":"The phrase balances criticism with recognition.","zh":"這個片語在批評與認可之間取得平衡。"}],"source":"66 - Salvador Dali.pdf","sourcePage":25},{"front":"leave an enduring legacy","meaning":"留下持久的遺產","examples":[{"en":"Dalí left an enduring legacy in the art world.","zh":"達利在藝術界留下持久的遺產。"},{"en":"Leave an enduring legacy means create influence or achievements that last long after one’s life or career.","zh":"leave an enduring legacy 指創造在一生或事業後仍長久存在的影響或成就。"},{"en":"A caring principal can leave an enduring legacy by changing how a school supports students.","zh":"關懷學生的校長可以透過改變學校支援學生的方式留下持久遺產。"},{"en":"If an artist’s images remain famous for generations, they have left an enduring legacy.","zh":"如果藝術家的形象跨世代仍然有名，就留下了持久遺產。"},{"en":"The phrase focuses on lasting influence.","zh":"這個片語集中於持久影響。"}],"source":"66 - Salvador Dali.pdf","sourcePage":25},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the short text that follows.","zh":"complete the summary below 指在下方短文中填入缺失字詞。"},{"en":"In a reading exercise, students complete the summary below by finding key words in the passage.","zh":"在閱讀練習中，學生透過在文章中尋找關鍵字完成以下摘要。"},{"en":"If the word does not fit the grammar of the summary, the answer may be wrong.","zh":"如果字詞不符合摘要文法，答案可能錯。"},{"en":"The phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"66 - Salvador Dali.pdf","sourcePage":25},{"front":"no more than two words","meaning":"不超過兩個字","examples":[{"en":"Students should use no more than two words for each answer.","zh":"學生每個答案應使用不超過兩個字。"},{"en":"No more than two words means the answer can contain one or two words, but not three.","zh":"no more than two words 指答案可包含一個或兩個詞，但不能三個。"},{"en":"If the correct idea is “melting clocks”, it fits the no-more-than-two-words rule.","zh":"如果正確概念是 melting clocks，就符合不超過兩個詞的規則。"},{"en":"If students write extra words, they may lose marks even when the idea is correct.","zh":"如果學生寫多餘字詞，即使意思正確也可能失分。"},{"en":"The phrase gives a strict word limit.","zh":"這個片語給出嚴格字數限制。"}],"source":"66 - Salvador Dali.pdf","sourcePage":25},{"front":"manage to achieve","meaning":"成功獲得","examples":[{"en":"Dalí managed to achieve worldwide fame.","zh":"達利成功獲得世界聲譽。"},{"en":"Manage to achieve means succeed in reaching a goal, often despite difficulty.","zh":"manage to achieve 指成功達到目標，通常儘管有困難。"},{"en":"A student may manage to achieve fluency after years of regular speaking practice.","zh":"學生可能經多年定期口語練習後成功達到流利程度。"},{"en":"If someone manages to achieve fame during their lifetime, their work has reached many people.","zh":"如果某人在有生之年成功成名，其作品已接觸許多人。"},{"en":"The phrase emphasises successful effort.","zh":"這個片語強調努力後成功。"}],"source":"66 - Salvador Dali.pdf","sourcePage":25},{"front":"figurehead of","meaning":"……的代表人物","examples":[{"en":"Dalí became the figurehead of the Surrealist movement.","zh":"達利成為超現實主義運動的代表人物。"},{"en":"Figurehead of means the public symbol or representative face of a group or movement.","zh":"figurehead of 指某群體或運動的公眾象徵或代表面孔。"},{"en":"A famous athlete may become the figurehead of a campaign for youth sports.","zh":"著名運動員可能成為青年體育宣傳活動的代表人物。"},{"en":"If someone becomes a figurehead, people may connect the whole cause with that person.","zh":"如果某人成為代表人物，人們可能把整個事業與那個人連在一起。"},{"en":"The phrase focuses on symbolic public representation.","zh":"這個片語集中於象徵性的公眾代表。"}],"source":"66 - Salvador Dali.pdf","sourcePage":26},{"front":"sheer confidence","meaning":"十足的自信","examples":[{"en":"Dalí’s sheer confidence could be interpreted as arrogance.","zh":"達利十足的自信可被理解為傲慢。"},{"en":"Sheer confidence means very strong and unmistakable self-belief.","zh":"sheer confidence 指非常強烈而明顯的自我信念。"},{"en":"A speaker with sheer confidence may answer questions without hesitation.","zh":"有十足自信的演講者可能毫不猶豫回答問題。"},{"en":"If confidence is too strong, others may interpret it as arrogance.","zh":"如果自信太強，其他人可能把它理解為傲慢。"},{"en":"The phrase intensifies the idea of confidence.","zh":"這個片語加強自信的概念。"}],"source":"66 - Salvador Dali.pdf","sourcePage":26},{"front":"be interpreted as","meaning":"被理解為","examples":[{"en":"Dalí’s confidence could be interpreted as arrogance.","zh":"達利的自信可被理解為傲慢。"},{"en":"Be interpreted as means be understood or explained in a particular way.","zh":"be interpreted as 指被以某種特定方式理解或解釋。"},{"en":"A quiet reply may be interpreted as agreement, even if the person is only thinking.","zh":"安靜回應可能被理解為同意，即使那人只是思考。"},{"en":"If behaviour is open to different interpretations, people may disagree about its meaning.","zh":"如果行為可有不同解讀，人們可能對其意思意見不一。"},{"en":"The phrase focuses on how something is understood.","zh":"這個片語集中於某事如何被理解。"}],"source":"66 - Salvador Dali.pdf","sourcePage":26},{"front":"be capable of","meaning":"有能力","examples":[{"en":"Dalí believed he was capable of achieving anything.","zh":"達利相信自己有能力成就任何事。"},{"en":"Be capable of means have the ability or potential to do something.","zh":"be capable of 指有能力或潛力做某事。"},{"en":"A hardworking student is capable of improving quickly with the right feedback.","zh":"勤奮學生在合適回饋下有能力快速進步。"},{"en":"If someone believes they are capable of anything, confidence may become ambition or arrogance.","zh":"如果某人相信自己有能力做任何事，自信可能變成抱負或傲慢。"},{"en":"The phrase describes ability or possibility.","zh":"這個片語描述能力或可能性。"}],"source":"66 - Salvador Dali.pdf","sourcePage":26},{"front":"achieve anything","meaning":"成就任何事","examples":[{"en":"Dalí believed he could achieve anything.","zh":"達利相信自己能成就任何事。"},{"en":"Achieve anything means succeed in reaching any goal, however difficult.","zh":"achieve anything 指無論目標多困難都能成功達成。"},{"en":"A child may feel they can achieve anything after winning their first competition.","zh":"孩子贏得第一次比賽後，可能覺得自己能成就任何事。"},{"en":"If belief in success is too extreme, it may ignore real limits and other people’s skills.","zh":"如果對成功的信念過度極端，可能忽視現實限制和他人技能。"},{"en":"The phrase expresses very broad confidence.","zh":"這個片語表達非常廣泛的自信。"}],"source":"66 - Salvador Dali.pdf","sourcePage":26},{"front":"be chiefly inspired by","meaning":"主要受……啟發","examples":[{"en":"Dalí’s work was chiefly inspired by Freud’s theories.","zh":"達利的作品主要受佛洛伊德理論啟發。"},{"en":"Be chiefly inspired by means be mainly influenced or motivated by something.","zh":"be chiefly inspired by 指主要受某事影響或推動。"},{"en":"A student’s project may be chiefly inspired by family history.","zh":"學生的項目可能主要受家族歷史啟發。"},{"en":"If a painting is chiefly inspired by dreams, its scenes may look illogical.","zh":"如果畫作主要受夢境啟發，其場景可能看起來不合邏輯。"},{"en":"The phrase identifies the main source of influence.","zh":"這個片語指出主要影響來源。"}],"source":"66 - Salvador Dali.pdf","sourcePage":26},{"front":"the standard of his art","meaning":"他的藝術水準","examples":[{"en":"Some critics believed the standard of Dalí’s art declined.","zh":"有些評論家認為達利的藝術水準下降。"},{"en":"The standard of his art means the quality or level of his artistic work.","zh":"the standard of his art 指其藝術作品的質素或水平。"},{"en":"A teacher may say the standard of a student’s writing has improved after regular feedback.","zh":"老師可能說學生寫作水準在定期回饋後提升。"},{"en":"If the standard of art declines, critics may compare later work with earlier masterpieces.","zh":"如果藝術水準下降，評論家可能把後期作品與早期傑作比較。"},{"en":"The phrase evaluates quality.","zh":"這個片語評估質素。"}],"source":"66 - Salvador Dali.pdf","sourcePage":26},{"front":"decline","meaning":"下降","examples":[{"en":"Critics argued that the standard of Dalí’s art declined.","zh":"評論家主張達利的藝術水準下降。"},{"en":"Decline means become lower, weaker, worse, or less successful.","zh":"decline 指變低、變弱、變差或較不成功。"},{"en":"A student’s concentration may decline after several nights of poor sleep.","zh":"學生連續幾晚睡不好後，專注力可能下降。"},{"en":"If quality declines, people may notice more mistakes and less originality.","zh":"如果質素下降，人們可能注意到更多錯誤和較少原創性。"},{"en":"The word describes downward change.","zh":"這個詞描述向下的變化。"}],"source":"66 - Salvador Dali.pdf","sourcePage":26},{"front":"varying quality","meaning":"質素參差","examples":[{"en":"Dalí’s work is often seen as being of varying quality.","zh":"達利的作品常被視為質素參差。"},{"en":"Varying quality means some examples are strong while others are weaker or less successful.","zh":"varying quality 指有些例子很強，而另一些較弱或較不成功。"},{"en":"A restaurant with varying quality may serve excellent food one day and disappointing food the next.","zh":"質素參差的餐廳可能一天提供出色食物，另一天令人失望。"},{"en":"If an artist produces many different projects, the quality may vary across them.","zh":"如果藝術家創作許多不同項目，質素可能在其中有所差異。"},{"en":"The phrase gives a mixed judgement.","zh":"這個片語給出混合評價。"}],"source":"66 - Salvador Dali.pdf","sourcePage":26},{"front":"never be forgotten","meaning":"永不被遺忘","examples":[{"en":"Dalí will never be forgotten.","zh":"達利將永不被遺忘。"},{"en":"Never be forgotten means remain in people’s memory for a very long time.","zh":"never be forgotten 指長時間留在人們記憶中。"},{"en":"A kind teacher may never be forgotten by students they helped during difficult years.","zh":"幫助學生度過困難歲月的善良老師，可能永不被學生遺忘。"},{"en":"If an artist creates unforgettable images, future generations may continue to remember them.","zh":"如果藝術家創造難忘形象，後代可能繼續記住他們。"},{"en":"The phrase expresses lasting memory and legacy.","zh":"這個片語表達持久記憶和遺產。"}],"source":"66 - Salvador Dali.pdf","sourcePage":26}],"ielts/reading/passage-2/Practice 67":[{"front":"physiology and criminality","meaning":"生理學與犯罪性","examples":[{"en":"The passage discusses theories about physiology and criminality.","zh":"文章討論關於生理學與犯罪性的理論。"},{"en":"Physiology and criminality refers to the study of whether body features or biological factors are linked to crime.","zh":"「physiology and criminality」指研究身體特徵或生物因素是否與犯罪有關。"},{"en":"A criminology class may discuss physiology and criminality when studying old theories about body type.","zh":"犯罪學課研究關於體型的舊理論時，可能討論生理學與犯罪性。"},{"en":"If people wrongly link appearance with crime, unfair prejudice can result.","zh":"如果人們錯誤地把外貌與犯罪聯繫起來，可能導致不公平偏見。"},{"en":"Modern discussions treat physiology and criminality more carefully than early theories did.","zh":"現代討論比早期理論更謹慎地處理生理學與犯罪性的關係。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":1},{"front":"prior to the 19th century","meaning":"在19世紀之前","examples":[{"en":"Prior to the 19th century, criminality was seen mainly as a moral or philosophical issue.","zh":"在19世紀之前，犯罪性主要被視為道德或哲學問題。"},{"en":"Prior to the 19th century means before the 1800s.","zh":"「prior to the 19th century」意思是在1800年代之前。"},{"en":"Prior to the 19th century, many illnesses were explained without modern medical science.","zh":"在19世紀之前，許多疾病並不是用現代醫學科學來解釋。"},{"en":"If an idea existed prior to modern research, it may have been based more on belief than evidence.","zh":"如果某想法早於現代研究存在，它可能更多建基於信念而非證據。"},{"en":"The phrase is a formal way to say “before the 19th century”.","zh":"這個短語是 “before the 19th century” 的正式說法。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":1},{"front":"criminality","meaning":"犯罪性；犯罪傾向","examples":[{"en":"Criminality was once considered more of a moral issue than a scientific one.","zh":"犯罪性曾經被視為更像道德問題，而不是科學問題。"},{"en":"Criminality means the tendency to commit crimes or the quality of being criminal.","zh":"「criminality」指犯罪傾向，或具有犯罪性質。"},{"en":"A court may focus on a crime, while criminologists may study wider patterns of criminality.","zh":"法庭可能集中於一宗罪行，而犯罪學家可能研究更廣泛的犯罪性模式。"},{"en":"If criminality is treated only as biology, social causes may be ignored.","zh":"如果犯罪性只被視為生物問題，社會原因可能被忽略。"},{"en":"The word is more abstract than “crime” because it refers to the condition or tendency.","zh":"這個詞比 “crime” 更抽象，因為它指狀態或傾向。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":1},{"front":"be considered more of","meaning":"被視為更像是……","examples":[{"en":"Criminality was considered more of a moral or philosophical issue.","zh":"犯罪性被視為更像是道德或哲學問題。"},{"en":"To be considered more of something means to be seen mainly as that type of thing.","zh":"「be considered more of」某物，意思是主要被看成那類事物。"},{"en":"Homework may be considered more of a learning tool than a punishment.","zh":"功課可以被視為更像學習工具，而不是懲罰。"},{"en":"If crime is considered more of a social problem, solutions may focus on poverty and education.","zh":"如果犯罪被視為更像社會問題，解決方法可能集中於貧窮和教育。"},{"en":"The phrase shows how people classify or interpret something.","zh":"這個短語顯示人們如何分類或理解某事。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":1},{"front":"a moral or philosophical issue","meaning":"道德或哲學問題","examples":[{"en":"Criminality was considered a moral or philosophical issue before scientific theories developed.","zh":"在科學理論發展之前，犯罪性被視為道德或哲學問題。"},{"en":"A moral or philosophical issue is a question about right, wrong, human nature, or meaning.","zh":"「a moral or philosophical issue」是關於對錯、人性或意義的問題。"},{"en":"Whether punishment should focus on revenge or reform is a moral or philosophical issue.","zh":"懲罰應集中於報復還是改造，是道德或哲學問題。"},{"en":"If a topic is treated only as a moral issue, scientific evidence may be overlooked.","zh":"如果某題目只被視為道德問題，科學證據可能被忽略。"},{"en":"The phrase contrasts ethical thinking with scientific explanation.","zh":"這個短語把倫理思考與科學解釋作對比。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":1},{"front":"only with the work of","meaning":"只有隨着……的研究","examples":[{"en":"Only with the work of Cesare Lombroso did criminality take a more scientific turn.","zh":"只有隨着 Cesare Lombroso 的研究，犯罪性才轉向更科學的方向。"},{"en":"Only with the work of someone means that change happened only after that person’s work appeared.","zh":"「only with the work of」某人，意思是只有在那人的研究出現後，改變才發生。"},{"en":"Only with the work of public health doctors did cities understand the spread of some diseases.","zh":"只有隨着公共衛生醫生的研究，城市才理解某些疾病如何傳播。"},{"en":"If a field changes only with one researcher’s work, that researcher had major influence.","zh":"如果一個領域只有隨某位研究者的工作才改變，那位研究者影響重大。"},{"en":"The phrase highlights a turning point caused by someone’s contribution.","zh":"這個短語強調由某人貢獻造成的轉折點。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":1},{"front":"Italian anthropologist","meaning":"意大利人類學家","examples":[{"en":"Cesare Lombroso was an Italian anthropologist who studied criminal behaviour.","zh":"Cesare Lombroso 是研究犯罪行為的意大利人類學家。"},{"en":"An Italian anthropologist is a scholar from Italy who studies humans and human societies.","zh":"「Italian anthropologist」是來自意大利、研究人類和人類社會的學者。"},{"en":"An anthropologist may study customs, bodies, beliefs, or social behaviour.","zh":"人類學家可能研究習俗、身體、信念或社會行為。"},{"en":"If an anthropologist studies crime, they may look at how people explain criminal behaviour.","zh":"如果人類學家研究犯罪，他們可能考察人們如何解釋犯罪行為。"},{"en":"The phrase identifies Lombroso’s nationality and academic field.","zh":"這個短語指出 Lombroso 的國籍和學術領域。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":1},{"front":"take a more scientific turn","meaning":"轉向更科學的方向","examples":[{"en":"The subject of criminality took a more scientific turn through Lombroso’s work.","zh":"犯罪性這個題目透過 Lombroso 的研究轉向更科學的方向。"},{"en":"To take a more scientific turn means to become more based on observation, evidence, or research.","zh":"「take a more scientific turn」意思是變得更建基於觀察、證據或研究。"},{"en":"Health advice took a more scientific turn when doctors began testing treatments systematically.","zh":"當醫生開始系統地測試治療方法，健康建議就轉向更科學的方向。"},{"en":"If a debate becomes more scientific, people start asking for data rather than opinions only.","zh":"如果辯論變得更科學，人們會開始要求數據，而不只是意見。"},{"en":"The phrase describes a shift toward evidence-based thinking.","zh":"這個短語描述轉向循證思考。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":1},{"front":"with the publication of","meaning":"隨着……的出版","examples":[{"en":"With the publication of his theories, Lombroso changed the study of criminal behaviour.","zh":"隨着他的理論出版，Lombroso 改變了犯罪行為研究。"},{"en":"With the publication of something means after it was formally printed or released.","zh":"「with the publication of」某物，意思是在它正式印行或發表後。"},{"en":"With the publication of a new report, the school changed its safety rules.","zh":"隨着新報告出版，學校改變了安全規則。"},{"en":"If a theory is published, other scholars can discuss, criticise, or test it.","zh":"如果理論被出版，其他學者就能討論、批評或測試它。"},{"en":"The phrase marks the release of written work as an important event.","zh":"這個短語把書面作品發表標示為重要事件。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":1},{"front":"theories of criminal behaviour","meaning":"犯罪行為理論","examples":[{"en":"Lombroso published theories of criminal behaviour.","zh":"Lombroso 出版了犯罪行為理論。"},{"en":"Theories of criminal behaviour are explanations of why people commit crimes.","zh":"「theories of criminal behaviour」是解釋人們為何犯罪的理論。"},{"en":"A sociology class may compare theories of criminal behaviour based on poverty, family, or biology.","zh":"社會學課可能比較以貧窮、家庭或生物學為基礎的犯罪行為理論。"},{"en":"If a theory ignores evidence, it may lead to unfair conclusions.","zh":"如果理論忽略證據，它可能導致不公平結論。"},{"en":"The phrase refers to explanations, not crimes themselves.","zh":"這個短語指解釋，而不是罪行本身。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":1},{"front":"criminal behaviour","meaning":"犯罪行為","examples":[{"en":"Lombroso tried to explain criminal behaviour scientifically.","zh":"Lombroso 試圖以科學方式解釋犯罪行為。"},{"en":"Criminal behaviour means actions that break the law.","zh":"「criminal behaviour」指違反法律的行為。"},{"en":"Theft, assault, and fraud are examples of criminal behaviour.","zh":"盜竊、襲擊和詐騙都是犯罪行為例子。"},{"en":"If researchers study criminal behaviour, they may examine personal, social, and environmental causes.","zh":"如果研究人員研究犯罪行為，他們可能考察個人、社會和環境原因。"},{"en":"The phrase focuses on actions rather than only thoughts or personality.","zh":"這個短語集中於行為，而不只是思想或性格。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":1},{"front":"advance the idea that","meaning":"提出……的觀點","examples":[{"en":"Lombroso advanced the idea that criminal behaviour had a biological cause.","zh":"Lombroso 提出犯罪行為有生物成因的觀點。"},{"en":"To advance the idea that means to put forward or promote a particular view.","zh":"「advance the idea that」意思是提出或推廣某個看法。"},{"en":"A student may advance the idea that later school starts improve concentration.","zh":"學生可能提出較遲上課能改善專注力的觀點。"},{"en":"If a scholar advances an idea, others may later test or challenge it.","zh":"如果學者提出一個觀點，其他人之後可能測試或挑戰它。"},{"en":"The phrase is formal and often used in academic writing.","zh":"這個短語較正式，常用於學術寫作。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":2},{"front":"be attributable to","meaning":"可歸因於……","examples":[{"en":"Lombroso believed that criminal behaviour was attributable to physiological disposition.","zh":"Lombroso 相信犯罪行為可歸因於生理傾向。"},{"en":"To be attributable to something means to be caused by or explained by it.","zh":"「be attributable to」某事，意思是由它造成或可由它解釋。"},{"en":"A fall in exam results may be attributable to poor attendance.","zh":"考試成績下降可能可歸因於出席率差。"},{"en":"If crime is attributed only to biology, other causes may be ignored.","zh":"如果犯罪只被歸因於生物因素，其他原因可能被忽略。"},{"en":"The phrase links an effect to a supposed cause.","zh":"這個短語把結果與被認為的原因連繫起來。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":2},{"front":"physiological disposition","meaning":"生理傾向","examples":[{"en":"Lombroso linked criminal behaviour to physiological disposition.","zh":"Lombroso 把犯罪行為與生理傾向聯繫起來。"},{"en":"Physiological disposition means a tendency based on the body’s biological features.","zh":"「physiological disposition」指基於身體生物特徵的傾向。"},{"en":"A person’s physical sensitivity to heat may be a physiological disposition.","zh":"一個人對熱的身體敏感度可能是一種生理傾向。"},{"en":"If someone claims behaviour comes from physiological disposition, they are linking action to biology.","zh":"如果有人聲稱行為來自生理傾向，他就是把行動與生物學聯繫起來。"},{"en":"The phrase is formal and often used in biological explanations.","zh":"這個短語較正式，常用於生物學解釋。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":2},{"front":"rather than","meaning":"而不是","examples":[{"en":"He attributed crime to physical disposition rather than existential reasons.","zh":"他把犯罪歸因於身體傾向，而不是存在層面的原因。"},{"en":"Rather than shows contrast and means “instead of”.","zh":"「rather than」表示對比，意思是「而不是」。"},{"en":"A teacher may ask students to explain an answer rather than just memorise it.","zh":"老師可能要求學生解釋答案，而不是只背答案。"},{"en":"If a problem comes from poor planning rather than laziness, the solution should change.","zh":"如果問題來自規劃差，而不是懶惰，解決方法就應改變。"},{"en":"The phrase separates one explanation from another.","zh":"這個短語把一個解釋與另一個解釋分開。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":2},{"front":"existential reasons","meaning":"存在層面的原因","examples":[{"en":"Lombroso rejected existential reasons as the main explanation for criminal behaviour.","zh":"Lombroso 拒絕把存在層面的原因視為犯罪行為的主要解釋。"},{"en":"Existential reasons are explanations connected with human existence, meaning, choice, or purpose.","zh":"「existential reasons」是與人類存在、意義、選擇或目的有關的解釋。"},{"en":"A person may discuss existential reasons when asking what makes life meaningful.","zh":"當一個人問人生有何意義時，他可能在討論存在層面的原因。"},{"en":"If crime is explained by existential reasons, the focus may be on choice and human purpose.","zh":"如果犯罪由存在層面的原因解釋，焦點可能放在選擇和人生目的上。"},{"en":"The phrase contrasts philosophical explanation with biological explanation.","zh":"這個短語把哲學解釋與生物解釋作對比。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":2},{"front":"atavistic form theory","meaning":"返祖形態理論","examples":[{"en":"Lombroso published his atavistic form theory in 1876.","zh":"Lombroso 在1876年出版了他的返祖形態理論。"},{"en":"Atavistic form theory claimed that criminals showed primitive inherited features from earlier humans.","zh":"「atavistic form theory」聲稱罪犯顯示來自早期人類的原始遺傳特徵。"},{"en":"A history of criminology class may study atavistic form theory as an outdated idea.","zh":"犯罪學史課可能把返祖形態理論作為過時觀念來研究。"},{"en":"If a theory links appearance with criminality, it can encourage unfair judgement.","zh":"如果理論把外貌與犯罪性聯繫起來，它可能鼓勵不公平判斷。"},{"en":"The phrase names Lombroso’s now-discredited biological theory.","zh":"這個短語指 Lombroso 現已被否定的生物理論。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":2},{"front":"claim that","meaning":"聲稱；主張","examples":[{"en":"Lombroso claimed that criminality was heritable.","zh":"Lombroso 聲稱犯罪性是可遺傳的。"},{"en":"To claim that means to say something is true, often before it is fully proven.","zh":"「claim that」意思是聲稱某事為真，通常是在完全證明之前。"},{"en":"A company may claim that its product improves sleep, but customers should check evidence.","zh":"公司可能聲稱其產品改善睡眠，但顧客應檢查證據。"},{"en":"If a researcher claims that a behaviour is inherited, later studies must test it.","zh":"如果研究人員聲稱某行為是遺傳的，後來研究必須測試它。"},{"en":"The phrase introduces an assertion.","zh":"這個短語引出一項主張。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":2},{"front":"heritable","meaning":"可遺傳的","examples":[{"en":"Lombroso believed that criminality was heritable.","zh":"Lombroso 相信犯罪性是可遺傳的。"},{"en":"Heritable means able to be passed from parents to children through genes.","zh":"「heritable」意思是能透過基因由父母傳給子女。"},{"en":"Eye colour is heritable, although many traits are more complex than one gene.","zh":"眼睛顏色是可遺傳的，雖然許多特徵比單一基因更複雜。"},{"en":"If a condition is heritable, family patterns may appear across generations.","zh":"如果某狀況可遺傳，家族模式可能跨世代出現。"},{"en":"The word is biological and should not be used without evidence.","zh":"這個詞屬於生物學用語，不應在沒有證據下使用。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":2},{"front":"propose that","meaning":"提出；認為","examples":[{"en":"He proposed that some people were biologically prone to crime.","zh":"他提出有些人在生物上易於犯罪。"},{"en":"To propose that means to suggest an explanation or idea for consideration.","zh":"「propose that」意思是提出一個解釋或想法供人考慮。"},{"en":"A student may propose that school stress is reduced by shorter homework tasks.","zh":"學生可能提出縮短功課能減少學校壓力。"},{"en":"If someone proposes a theory, others may accept, reject, or test it.","zh":"如果有人提出理論，其他人可能接受、拒絕或測試它。"},{"en":"The phrase is formal and common in academic writing.","zh":"這個短語較正式，常見於學術寫作。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":2},{"front":"a distinct biological class of people","meaning":"一個獨特的生物類別人群","examples":[{"en":"Lombroso proposed that criminals formed a distinct biological class of people.","zh":"Lombroso 提出罪犯形成一個獨特的生物類別人群。"},{"en":"A distinct biological class of people means a clearly separate group defined by biology.","zh":"「a distinct biological class of people」指由生物特徵界定的清楚分開群體。"},{"en":"Modern science is cautious about dividing people into fixed biological classes.","zh":"現代科學對把人分成固定生物類別十分謹慎。"},{"en":"If a theory labels criminals as a separate biological class, it may lead to discrimination.","zh":"如果理論把罪犯標籤為分開的生物類別，它可能導致歧視。"},{"en":"The phrase reflects Lombroso’s old and problematic view.","zh":"這個短語反映 Lombroso 舊而有問題的觀點。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":2},{"front":"be prone to","meaning":"易於；有……傾向","examples":[{"en":"Some people were thought to be prone to criminality.","zh":"有些人被認為易於有犯罪傾向。"},{"en":"To be prone to something means to be likely to experience it or have a tendency towards it.","zh":"「be prone to」某事，意思是較可能經歷它或有朝向它的傾向。"},{"en":"A student who sleeps too little may be prone to headaches.","zh":"睡眠太少的學生可能容易頭痛。"},{"en":"If someone is said to be prone to risk-taking, they may choose dangerous activities more often.","zh":"如果某人被說成有冒險傾向，他可能較常選擇危險活動。"},{"en":"The phrase describes tendency, not certainty.","zh":"這個短語描述傾向，而不是必然。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":2},{"front":"exhibit primitive features","meaning":"顯現原始特徵","examples":[{"en":"Lombroso claimed that criminals exhibited primitive features.","zh":"Lombroso 聲稱罪犯顯現原始特徵。"},{"en":"To exhibit primitive features means to show physical traits thought to belong to earlier stages of human development.","zh":"「exhibit primitive features」意思是顯示被認為屬於人類早期發展階段的身體特徵。"},{"en":"A museum display may exhibit primitive tools used by early human communities.","zh":"博物館展示可能展出早期人類社群使用的原始工具。"},{"en":"If a theory says people exhibit primitive features, it is making a claim about visible traits.","zh":"如果理論說人們顯現原始特徵，它是在提出關於可見特徵的主張。"},{"en":"In Lombroso’s case, this claim is now regarded as flawed.","zh":"在 Lombroso 的情況中，這個主張現在被視為有缺陷。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":3},{"front":"atavistic features","meaning":"返祖特徵","examples":[{"en":"He believed that criminals had atavistic features.","zh":"他相信罪犯具有返祖特徵。"},{"en":"Atavistic features are traits believed to be throwbacks to earlier ancestral forms.","zh":"「atavistic features」是被認為回到較早祖先形態的特徵。"},{"en":"An old theory might describe a physical feature as atavistic if it seemed ancient or primitive.","zh":"如果某身體特徵看似古老或原始，舊理論可能把它描述為返祖特徵。"},{"en":"If people are judged by supposed atavistic features, prejudice can replace evidence.","zh":"如果人們被所謂返祖特徵評判，偏見可能取代證據。"},{"en":"The phrase belongs to outdated biological theories of crime.","zh":"這個短語屬於過時的犯罪生物理論。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":3},{"front":"primitive features","meaning":"原始特徵","examples":[{"en":"Lombroso associated criminality with primitive features.","zh":"Lombroso 把犯罪性與原始特徵聯繫起來。"},{"en":"Primitive features are traits described as simple, ancient, or undeveloped.","zh":"「primitive features」是被描述為簡單、古老或未發展的特徵。"},{"en":"Early tools made of stone are often described as primitive tools.","zh":"用石頭製成的早期工具常被描述為原始工具。"},{"en":"If human faces are labelled primitive, the judgement can be unfair and unscientific.","zh":"如果人的面貌被標籤為原始，這種判斷可能不公平且不科學。"},{"en":"The phrase must be used carefully because it can carry biased meanings.","zh":"這個短語必須小心使用，因為它可能帶有偏見。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":3},{"front":"throwbacks","meaning":"返祖者","examples":[{"en":"Lombroso described such people as throwbacks to earlier human forms.","zh":"Lombroso 把這些人描述為早期人類形態的返祖者。"},{"en":"Throwbacks are people or things thought to resemble an earlier time or ancestral form.","zh":"「throwbacks」是被認為像較早時代或祖先形態的人或物。"},{"en":"A fashion style from the 1970s may be called a throwback look.","zh":"1970年代風格的時裝可以被稱為復古造型。"},{"en":"If a theory calls people throwbacks, it suggests they are biologically behind others.","zh":"如果理論稱人為返祖者，它暗示他們在生物上落後於其他人。"},{"en":"In this passage, the word shows Lombroso’s outdated view of criminals.","zh":"在本文中，這個詞顯示 Lombroso 對罪犯的過時看法。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":3},{"front":"bear physical resemblances to","meaning":"與……有外貌相似之處","examples":[{"en":"Criminal types were said to bear physical resemblances to evolutionary predecessors.","zh":"所謂犯罪類型被說成與進化上的祖先有外貌相似之處。"},{"en":"To bear physical resemblances to someone means to look physically similar to them.","zh":"「bear physical resemblances to」某人，意思是在外貌上與他相似。"},{"en":"A child may bear a physical resemblance to a grandparent in face shape.","zh":"孩子可能在面形上與祖父母有外貌相似之處。"},{"en":"If a theory links resemblance with behaviour, it needs strong evidence.","zh":"如果理論把相貌與行為連繫起來，它需要強力證據。"},{"en":"The phrase describes appearance, not proven character.","zh":"這個短語描述外貌，而不是被證實的性格。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":3},{"front":"human evolutionary predecessors","meaning":"人類進化上的祖先","examples":[{"en":"Lombroso compared criminals with human evolutionary predecessors.","zh":"Lombroso 把罪犯與人類進化上的祖先作比較。"},{"en":"Human evolutionary predecessors are earlier human or human-like ancestors in evolutionary history.","zh":"「human evolutionary predecessors」是進化歷史中較早的人類或類人祖先。"},{"en":"Students learn about human evolutionary predecessors when studying fossils.","zh":"學生研究化石時，會學到人類進化上的祖先。"},{"en":"If a theory compares modern people to ancient ancestors, it must avoid unfair biological ranking.","zh":"如果理論把現代人與古代祖先比較，它必須避免不公平的生物排序。"},{"en":"The phrase belongs to discussions of human evolution.","zh":"這個短語屬於人類進化討論。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":3},{"front":"the Neanderthals","meaning":"尼安德特人","examples":[{"en":"Lombroso claimed that some criminals resembled the Neanderthals.","zh":"Lombroso 聲稱有些罪犯像尼安德特人。"},{"en":"The Neanderthals were an extinct group of ancient humans.","zh":"尼安德特人是一群已滅絕的古人類。"},{"en":"A history museum may display skull models of the Neanderthals.","zh":"歷史博物館可能展示尼安德特人的頭骨模型。"},{"en":"If a writer compares modern people with Neanderthals, the comparison may carry outdated assumptions.","zh":"如果作者把現代人與尼安德特人比較，這種比較可能帶有過時假設。"},{"en":"In this passage, the reference shows Lombroso’s flawed evolutionary thinking.","zh":"在本文中，這個提法顯示 Lombroso 有缺陷的進化思維。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":3},{"front":"be characterised by","meaning":"具有……特徵","examples":[{"en":"His criminal type was characterised by a strong jaw and a heavy brow.","zh":"他的犯罪類型具有強壯下巴和突出眉骨等特徵。"},{"en":"To be characterised by something means to have it as a typical feature.","zh":"「be characterised by」某物，意思是以它作為典型特徵。"},{"en":"A good school may be characterised by supportive teachers and clear rules.","zh":"好學校可能具有有支援性的老師和清楚規則等特徵。"},{"en":"If a theory says a group is characterised by certain features, it is describing a pattern.","zh":"如果理論說某群體具有某些特徵，它是在描述一種模式。"},{"en":"The phrase identifies common or supposed traits.","zh":"這個短語指出常見或被認為的特徵。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":3},{"front":"a well-defined jaw","meaning":"輪廓分明的下巴","examples":[{"en":"The atavistic type was said to have a well-defined jaw.","zh":"返祖類型被說成有輪廓分明的下巴。"},{"en":"A well-defined jaw is a jawline with a clear and strong shape.","zh":"「a well-defined jaw」是線條清楚而有力的下顎輪廓。"},{"en":"A portrait artist may draw a well-defined jaw to make a face look sharper.","zh":"肖像畫家可能畫出輪廓分明的下巴，使面孔看起來更銳利。"},{"en":"If old theories linked jaw shape with crime, they confused appearance with behaviour.","zh":"如果舊理論把下巴形狀與犯罪連繫起來，它們就是把外貌與行為混淆。"},{"en":"The phrase describes physical appearance only.","zh":"這個短語只描述外貌。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":3},{"front":"heavy brow","meaning":"突出的眉骨","examples":[{"en":"Lombroso associated criminality with a heavy brow.","zh":"Lombroso 把犯罪性與突出的眉骨聯繫起來。"},{"en":"A heavy brow is a prominent or strong-looking area above the eyes.","zh":"「heavy brow」是眼睛上方突出或看起來厚重的部位。"},{"en":"A sculpture of an ancient warrior may show a heavy brow to create a stern expression.","zh":"古代戰士雕像可能用突出的眉骨營造嚴肅表情。"},{"en":"If someone judges character from a heavy brow, the judgement is based on appearance, not evidence.","zh":"如果有人從突出眉骨判斷性格，那是根據外貌而非證據。"},{"en":"The phrase describes facial structure.","zh":"這個短語描述面部結構。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":3},{"front":"have little to recommend them","meaning":"沒有甚麼可取之處","examples":[{"en":"These features had little to recommend them in the beauty stakes.","zh":"這些特徵在外貌方面沒有甚麼可取之處。"},{"en":"To have little to recommend something means to have few attractive or useful qualities.","zh":"「have little to recommend」某物，意思是它幾乎沒有吸引人或有用之處。"},{"en":"A restaurant with bad food and slow service has little to recommend it.","zh":"食物差、服務慢的餐廳沒有甚麼可取之處。"},{"en":"If a plan has little to recommend it, people will not support it easily.","zh":"如果一個計劃沒有甚麼可取之處，人們不會容易支持它。"},{"en":"The phrase is a mild but clear criticism.","zh":"這個短語是溫和但清楚的批評。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":3},{"front":"in the beauty stakes","meaning":"在外貌方面","examples":[{"en":"The atavistic type had little to recommend it in the beauty stakes.","zh":"返祖類型在外貌方面沒有甚麼可取之處。"},{"en":"In the beauty stakes means when judged by appearance or attractiveness.","zh":"「in the beauty stakes」意思是在外貌或吸引力方面被評價。"},{"en":"A plain school uniform may not win much in the beauty stakes, but it can be practical.","zh":"樸素校服在外貌方面未必突出，但可以很實用。"},{"en":"If someone is judged only in the beauty stakes, deeper qualities are ignored.","zh":"如果某人只在外貌方面被評價，更深層的品質會被忽略。"},{"en":"The phrase is informal and slightly humorous.","zh":"這個短語較口語，並帶一點幽默感。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":4},{"front":"coupled with","meaning":"加上；連同","examples":[{"en":"These physical features, coupled with criminal tendencies, made the type socially undesirable.","zh":"這些身體特徵加上犯罪傾向，使這類型在社會上不受歡迎。"},{"en":"Coupled with means together with or combined with.","zh":"「coupled with」意思是加上、連同或結合。"},{"en":"Poor sleep, coupled with exam stress, can make students feel exhausted.","zh":"睡眠不足加上考試壓力，可以令學生感到筋疲力盡。"},{"en":"If weak evidence is coupled with strong prejudice, unfair theories may spread.","zh":"如果薄弱證據加上強烈偏見，不公平理論可能擴散。"},{"en":"The phrase shows two factors working together.","zh":"這個短語顯示兩個因素一起作用。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":4},{"front":"a tendency towards","meaning":"對……的傾向","examples":[{"en":"Lombroso associated certain physical features with a tendency towards criminal behaviour.","zh":"Lombroso 把某些身體特徵與犯罪行為傾向聯繫起來。"},{"en":"A tendency towards something is a habit or likelihood of moving in that direction.","zh":"「a tendency towards」某事，是朝向該方向的習慣或可能性。"},{"en":"A student with a tendency towards procrastination may start homework too late.","zh":"有拖延傾向的學生可能太遲才開始做功課。"},{"en":"If a theory says someone has a tendency towards crime, it must provide strong evidence.","zh":"如果理論說某人有犯罪傾向，它必須提供強力證據。"},{"en":"The phrase describes likelihood, not certainty.","zh":"這個短語描述可能性，而不是必然。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":4},{"front":"not be cut out for","meaning":"不適合；不是……的材料","examples":[{"en":"Lombroso’s atavistic type was not cut out for social success.","zh":"Lombroso 的返祖類型不適合在社會上成功。"},{"en":"To not be cut out for something means to be unsuitable for it.","zh":"「not be cut out for」某事，意思是不適合它或不是那方面的材料。"},{"en":"A person who hates noise may not be cut out for a job in a busy restaurant.","zh":"討厭噪音的人可能不適合在繁忙餐廳工作。"},{"en":"If someone is not cut out for public speaking, they may need training or another role.","zh":"如果某人不適合公開演說，他可能需要訓練或另一個角色。"},{"en":"The phrase describes a poor fit between a person and a situation.","zh":"這個短語描述人與情境之間不匹配。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":4},{"front":"social success","meaning":"社會上的成功","examples":[{"en":"The atavistic type was not suited to social success.","zh":"返祖類型不適合社會上的成功。"},{"en":"Social success means doing well in society, relationships, work, or public life.","zh":"「social success」指在社會、人際關係、工作或公共生活中表現良好。"},{"en":"Good communication skills can help students achieve social success at school.","zh":"良好溝通技巧可以幫助學生在學校取得社會上的成功。"},{"en":"If people are judged unfairly by appearance, their chances of social success may be damaged.","zh":"如果人們因外貌被不公平評價，他們取得社會成功的機會可能受損。"},{"en":"The phrase describes acceptance and achievement within society.","zh":"這個短語描述在社會中的接納和成就。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":4},{"front":"just for good measure","meaning":"為了再加一層；順帶再加上","examples":[{"en":"Just for good measure, Lombroso added more features to identify criminals.","zh":"為了再加一層，Lombroso 加入更多特徵來識別罪犯。"},{"en":"Just for good measure means as an extra addition, often to make something feel more complete.","zh":"「just for good measure」意思是額外加入，通常為了令某事感覺更完整。"},{"en":"A teacher may give one more example just for good measure before ending the lesson.","zh":"老師可能在下課前為了再加一層，再給一個例子。"},{"en":"If someone adds extra evidence for good measure, they want the argument to feel stronger.","zh":"如果有人順帶再加上額外證據，他想令論點感覺更有力。"},{"en":"The phrase often sounds slightly humorous or casual.","zh":"這個短語常帶一點幽默或口語感。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":4},{"front":"distinguishing features","meaning":"識別特徵","examples":[{"en":"Lombroso listed distinguishing features that supposedly identified criminals.","zh":"Lombroso 列出據稱能識別罪犯的識別特徵。"},{"en":"Distinguishing features are characteristics that help tell one person or thing apart from others.","zh":"「distinguishing features」是幫助把一個人或物與其他區分開來的特徵。"},{"en":"A school uniform may have distinguishing features such as a special badge or colour.","zh":"校服可能有校章或特定顏色等識別特徵。"},{"en":"If a feature is used to identify a group, it must be accurate and fair.","zh":"如果某特徵被用來識別群體，它必須準確而公平。"},{"en":"The phrase describes marks of difference.","zh":"這個短語描述可作區分的標記。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":4},{"front":"identify criminals","meaning":"識別罪犯","examples":[{"en":"Lombroso tried to identify criminals by their physical appearance.","zh":"Lombroso 試圖透過外貌識別罪犯。"},{"en":"To identify criminals means to recognise or find people who have committed crimes.","zh":"「identify criminals」意思是辨認或找出犯下罪行的人。"},{"en":"Police may identify criminals through evidence, witnesses, and investigation.","zh":"警方可能透過證據、證人和調查識別罪犯。"},{"en":"If people try to identify criminals by appearance alone, innocent people may be judged unfairly.","zh":"如果人們只靠外貌識別罪犯，無辜者可能被不公平評價。"},{"en":"The phrase should be connected with evidence, not prejudice.","zh":"這個短語應與證據相關，而不是偏見。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":4},{"front":"bloodshot eyes","meaning":"充血的眼睛","examples":[{"en":"Lombroso associated bloodshot eyes with murderers.","zh":"Lombroso 把充血的眼睛與殺人犯聯繫起來。"},{"en":"Bloodshot eyes are eyes that look red because the small blood vessels are irritated or visible.","zh":"「bloodshot eyes」是因微細血管受刺激或明顯而看起來發紅的眼睛。"},{"en":"A student may have bloodshot eyes after staying up all night studying.","zh":"學生通宵溫習後可能有充血的眼睛。"},{"en":"If someone has bloodshot eyes, it may show tiredness or illness, not criminality.","zh":"如果某人眼睛充血，這可能顯示疲倦或疾病，而不是犯罪性。"},{"en":"The phrase describes an eye appearance.","zh":"這個短語描述眼睛外觀。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":4},{"front":"curly hair","meaning":"鬈髮","examples":[{"en":"Curly hair was listed as one of the features of murderers.","zh":"鬈髮被列為殺人犯的特徵之一。"},{"en":"Curly hair is hair that forms curls rather than lying straight.","zh":"「curly hair」是形成卷曲而不是筆直垂下的頭髮。"},{"en":"A child may inherit curly hair from one side of the family.","zh":"孩子可能從家族一方遺傳鬈髮。"},{"en":"If a theory links curly hair with crime, it is using appearance unfairly.","zh":"如果理論把鬈髮與犯罪聯繫起來，它就是不公平地使用外貌。"},{"en":"The phrase describes hair shape only.","zh":"這個短語只描述頭髮形狀。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":4},{"front":"murderers","meaning":"殺人犯","examples":[{"en":"Lombroso claimed that murderers could be identified by certain features.","zh":"Lombroso 聲稱殺人犯可以透過某些特徵識別。"},{"en":"Murderers are people who unlawfully kill other people intentionally.","zh":"「murderers」是非法並蓄意殺害他人的人。"},{"en":"A murder investigation uses evidence, not appearance, to identify suspects.","zh":"殺人案調查使用證據，而不是外貌，來識別疑犯。"},{"en":"If murderers could be identified by looks alone, police work would be unrealistically simple.","zh":"如果殺人犯只靠外貌就能識別，警務工作就會不切實際地簡單。"},{"en":"The word refers to people who commit the crime of murder.","zh":"這個詞指犯下謀殺罪的人。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":4},{"front":"thick lips","meaning":"厚唇","examples":[{"en":"He linked thick lips with sex offenders.","zh":"他把厚唇與性罪犯聯繫起來。"},{"en":"Thick lips are lips that appear full or large.","zh":"「thick lips」是看起來豐滿或較大的嘴唇。"},{"en":"A portrait may describe a person as having thick lips, a narrow nose, or dark hair.","zh":"肖像描述可能形容一個人有厚唇、窄鼻或深色頭髮。"},{"en":"If appearance is linked with crime without evidence, the result is prejudice.","zh":"如果外貌在沒有證據下與犯罪聯繫起來，結果就是偏見。"},{"en":"The phrase describes a facial feature only.","zh":"這個短語只描述面部特徵。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":5},{"front":"protruding ears","meaning":"突出的耳朵","examples":[{"en":"Protruding ears were included among the features of sex offenders.","zh":"突出的耳朵被列入性罪犯的特徵之中。"},{"en":"Protruding ears are ears that stick out noticeably from the head.","zh":"「protruding ears」是明顯向外突出的耳朵。"},{"en":"A child with protruding ears may feel self-conscious if classmates tease him.","zh":"有突出耳朵的孩子如果被同學取笑，可能感到不自在。"},{"en":"If a theory treats protruding ears as criminal signs, it is confusing looks with behaviour.","zh":"如果理論把突出的耳朵視為犯罪跡象，它就是把外貌與行為混淆。"},{"en":"The phrase describes physical appearance.","zh":"這個短語描述身體外貌。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":5},{"front":"sex offenders","meaning":"性罪犯","examples":[{"en":"Lombroso claimed that sex offenders had certain physical features.","zh":"Lombroso 聲稱性罪犯有某些身體特徵。"},{"en":"Sex offenders are people convicted of sexual crimes.","zh":"「sex offenders」是被判犯下性罪行的人。"},{"en":"Modern justice systems identify sex offenders through evidence and legal process.","zh":"現代司法制度透過證據和法律程序識別性罪犯。"},{"en":"If people are judged by appearance rather than evidence, justice becomes unfair.","zh":"如果人們按外貌而非證據被判斷，司法就變得不公平。"},{"en":"The phrase refers to a legal category, not a body type.","zh":"這個短語指法律類別，而不是體型。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":5},{"front":"one has to wonder","meaning":"不禁令人懷疑","examples":[{"en":"One has to wonder how such criminals could approach their victims.","zh":"不禁令人懷疑這些罪犯如何能接近受害者。"},{"en":"One has to wonder means it is natural to question or doubt something.","zh":"「one has to wonder」意思是很自然會質疑或懷疑某事。"},{"en":"One has to wonder why a school rule exists if no one can explain its purpose.","zh":"如果沒有人能解釋某校規的目的，不禁令人懷疑它為何存在。"},{"en":"If a theory creates obvious practical problems, readers have to wonder whether it makes sense.","zh":"如果理論造成明顯實際問題，讀者不禁懷疑它是否合理。"},{"en":"The phrase gently expresses scepticism.","zh":"這個短語溫和地表達懷疑。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":5},{"front":"given the unusual appearance","meaning":"鑑於那種異常外貌","examples":[{"en":"Given the unusual appearance attributed to them, such criminals would be easy to recognise.","zh":"鑑於被認為具有那種異常外貌，這些罪犯會很容易被認出。"},{"en":"Given the unusual appearance means considering how strange or noticeable they supposedly looked.","zh":"「given the unusual appearance」意思是考慮到他們據稱奇怪或顯眼的外貌。"},{"en":"Given the unusual design of the building, visitors can find it easily.","zh":"鑑於那座建築設計異常，訪客很容易找到它。"},{"en":"If someone has a very unusual appearance, they may be remembered by witnesses.","zh":"如果某人外貌非常特別，證人可能會記得他。"},{"en":"The phrase introduces a reason based on appearance.","zh":"這個短語引出基於外貌的理由。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":5},{"front":"be attributed to","meaning":"被歸因於；被認為具有","examples":[{"en":"An unusual appearance was attributed to these supposed criminal types.","zh":"異常外貌被認為屬於這些所謂犯罪類型。"},{"en":"To be attributed to someone or something means to be said to belong to them or be caused by them.","zh":"「be attributed to」某人或某物，意思是被說成屬於它或由它造成。"},{"en":"The delay was attributed to heavy rain and traffic accidents.","zh":"延誤被歸因於大雨和交通意外。"},{"en":"If a feature is wrongly attributed to a group, stereotypes can spread.","zh":"如果某特徵被錯誤歸於某群體，刻板印象可能擴散。"},{"en":"The phrase can describe cause or assigned quality.","zh":"這個短語可以描述成因或被賦予的特質。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":5},{"front":"approach their victims","meaning":"接近受害者","examples":[{"en":"The passage questions how such criminals could have approached their victims.","zh":"文章質疑這些罪犯如何能接近受害者。"},{"en":"To approach their victims means to get close to the people they plan to harm.","zh":"「approach their victims」意思是接近他們打算傷害的人。"},{"en":"A scammer may approach victims by pretending to offer help.","zh":"騙徒可能假裝提供幫助來接近受害者。"},{"en":"If someone is easy to recognise, approaching victims without being noticed becomes harder.","zh":"如果某人容易被認出，不被注意地接近受害者就更難。"},{"en":"The phrase describes getting close before committing harm.","zh":"這個短語描述在造成傷害前靠近對方。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":5},{"front":"more to the point","meaning":"更重要的是","examples":[{"en":"More to the point, they would have been easy to identify.","zh":"更重要的是，他們本來很容易被識別。"},{"en":"More to the point means more importantly or more directly relevant.","zh":"「more to the point」意思是更重要或更直接相關的是。"},{"en":"The classroom is noisy; more to the point, students cannot hear instructions.","zh":"課室很嘈吵；更重要的是，學生聽不到指示。"},{"en":"If a theory is strange, more to the point, it may fail in real situations.","zh":"如果理論很奇怪，更重要的是，它可能在現實情況中失效。"},{"en":"The phrase introduces the stronger or more important argument.","zh":"這個短語引出更強或更重要的論點。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":5},{"front":"get away with a crime","meaning":"犯罪後逍遙法外","examples":[{"en":"Such criminals would find it difficult to get away with a crime.","zh":"這些罪犯會很難犯罪後逍遙法外。"},{"en":"To get away with a crime means to commit a crime without being caught or punished.","zh":"「get away with a crime」意思是犯案後沒有被抓到或受罰。"},{"en":"A thief may not get away with a crime if cameras record the whole act.","zh":"如果攝影機錄下整個行為，小偷可能無法犯罪後逍遙法外。"},{"en":"If someone is easily identifiable, getting away with a crime becomes harder.","zh":"如果某人很容易被識別，犯罪後逃避懲罰就更難。"},{"en":"The phrase focuses on avoiding detection or punishment.","zh":"這個短語集中於逃避偵查或懲罰。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":5},{"front":"seeing as","meaning":"既然；鑑於","examples":[{"en":"They could hardly escape punishment, seeing as they were readily identifiable.","zh":"既然他們容易被識別，就幾乎不能逃避懲罰。"},{"en":"Seeing as means because or considering that.","zh":"「seeing as」意思是因為或鑑於。"},{"en":"Seeing as the bus is late, we may need to walk to school.","zh":"既然巴士遲到，我們可能要步行回學校。"},{"en":"If a suspect is easy to recognise, escape is unlikely, seeing as witnesses can describe him.","zh":"如果疑犯容易被認出，逃走就不太可能，因為證人能描述他。"},{"en":"The phrase gives a reason in a conversational way.","zh":"這個短語以較口語方式提供理由。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":5},{"front":"readily identifiable","meaning":"容易被識別的","examples":[{"en":"Lombroso’s criminal types would have been readily identifiable.","zh":"Lombroso 的犯罪類型本來會很容易被識別。"},{"en":"Readily identifiable means easy to recognise quickly.","zh":"「readily identifiable」意思是能很快容易認出。"},{"en":"A school team is readily identifiable if all players wear the same bright uniform.","zh":"如果校隊所有球員穿同一套鮮色制服，就很容易被識別。"},{"en":"If someone is readily identifiable, hiding in a crowd becomes difficult.","zh":"如果某人容易被識別，在人群中隱藏就變得困難。"},{"en":"The phrase describes easy recognition.","zh":"這個短語描述容易辨認。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":5},{"front":"in hindsight","meaning":"事後看來","examples":[{"en":"In hindsight, Lombroso’s hypothesis seems ludicrous and deeply flawed.","zh":"事後看來，Lombroso 的假說顯得荒謬而且有嚴重缺陷。"},{"en":"In hindsight means looking back after knowing what happened or after gaining more knowledge.","zh":"「in hindsight」意思是在知道結果或得到更多知識後回頭看。"},{"en":"In hindsight, the student realised he should have started revision earlier.","zh":"事後看來，學生意識到自己應該更早開始溫習。"},{"en":"If later evidence disproves a theory, it may look weak in hindsight.","zh":"如果後來證據推翻一個理論，事後看來它可能顯得薄弱。"},{"en":"The phrase describes judgement made after the fact.","zh":"這個短語描述事後作出的判斷。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":6},{"front":"hypothesis","meaning":"假說","examples":[{"en":"Lombroso’s hypothesis is now viewed as scientifically weak.","zh":"Lombroso 的假說現在被視為科學上薄弱。"},{"en":"A hypothesis is a proposed explanation that can be tested.","zh":"「hypothesis」是可被測試的初步解釋。"},{"en":"In science class, students may test a hypothesis about plant growth and sunlight.","zh":"在科學課中，學生可能測試關於植物生長和陽光的假說。"},{"en":"If a hypothesis lacks proper controls, its results may not be reliable.","zh":"如果假說缺乏適當對照，其結果可能不可靠。"},{"en":"The word is more tentative than “proven fact”.","zh":"這個詞比「已證實事實」更具暫定性。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":6},{"front":"ludicrous and deeply flawed","meaning":"荒謬而且有嚴重缺陷","examples":[{"en":"Lombroso’s hypothesis seems ludicrous and deeply flawed today.","zh":"Lombroso 的假說今天看來荒謬而且有嚴重缺陷。"},{"en":"Ludicrous and deeply flawed means ridiculous and seriously wrong.","zh":"「ludicrous and deeply flawed」意思是荒唐可笑，而且嚴重錯誤。"},{"en":"A rule banning umbrellas because one student was late would be ludicrous and flawed.","zh":"因為一名學生遲到就禁止雨傘，這條規則會很荒謬且有缺陷。"},{"en":"If a theory has no proper evidence and unfair assumptions, it may be deeply flawed.","zh":"如果理論沒有適當證據並含有不公平假設，它可能有嚴重缺陷。"},{"en":"The phrase expresses strong criticism.","zh":"這個短語表達強烈批評。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":6},{"front":"one major failing in","meaning":"……的一個重大缺陷","examples":[{"en":"One major failing in Lombroso’s theory was the lack of proper controls.","zh":"Lombroso 理論的一個重大缺陷是缺乏適當對照組。"},{"en":"One major failing in something is one serious weakness in it.","zh":"「one major failing in」某物，是其中一個嚴重弱點。"},{"en":"One major failing in a school survey may be that only top students were asked.","zh":"學校調查的一個重大缺陷可能是只訪問了成績最好的學生。"},{"en":"If research has a major failing, its conclusions become less trustworthy.","zh":"如果研究有重大缺陷，其結論就變得較不可信。"},{"en":"The phrase introduces an important criticism.","zh":"這個短語引入重要批評。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":6},{"front":"proper controls","meaning":"適當的對照組","examples":[{"en":"No proper controls were used in Lombroso’s studies.","zh":"Lombroso 的研究沒有使用適當的對照組。"},{"en":"Proper controls are comparison groups or conditions used to make research fair and reliable.","zh":"「proper controls」是使研究公平可靠的比較組或條件。"},{"en":"A medicine test needs proper controls to show whether the medicine truly works.","zh":"藥物測試需要適當對照組，才能顯示藥物是否真正有效。"},{"en":"Without proper controls, researchers may confuse coincidence with cause.","zh":"沒有適當對照組，研究人員可能把巧合與原因混淆。"},{"en":"The phrase is important in scientific experiments.","zh":"這個短語在科學實驗中很重要。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":6},{"front":"studies designed to support","meaning":"旨在支持……的研究","examples":[{"en":"The studies designed to support the hypothesis were poorly controlled.","zh":"旨在支持該假說的研究控制得很差。"},{"en":"Studies designed to support something are research projects created to provide evidence for it.","zh":"「studies designed to support」某事，是為提供證據支持它而設計的研究。"},{"en":"Studies designed to support a new teaching method should compare it with normal teaching.","zh":"旨在支持新教學法的研究應把它與普通教學作比較。"},{"en":"If studies are designed badly, they may seem supportive but prove little.","zh":"如果研究設計差，它們可能看似支持某說法，但證明力很低。"},{"en":"The phrase focuses on research purpose.","zh":"這個短語集中於研究目的。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":6},{"front":"study participants","meaning":"研究參加者","examples":[{"en":"All study participants were drawn from a criminal population.","zh":"所有研究參加者都來自犯罪人群。"},{"en":"Study participants are the people who take part in research.","zh":"「study participants」是參與研究的人。"},{"en":"A health study may ask participants to record sleep and exercise for one month.","zh":"健康研究可能要求參加者記錄一個月的睡眠和運動。"},{"en":"If all participants come from one group, the results may be biased.","zh":"如果所有參加者都來自同一群體，結果可能有偏差。"},{"en":"The phrase identifies the people included in a study.","zh":"這個短語指出被納入研究的人。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":6},{"front":"be drawn from","meaning":"來自；取自","examples":[{"en":"The participants were drawn from a criminal population.","zh":"參加者取自犯罪人群。"},{"en":"To be drawn from a group means to be selected or taken from that group.","zh":"「be drawn from」某群體，意思是從該群體中選取或取出。"},{"en":"Survey answers may be drawn from students in three different schools.","zh":"調查答案可能來自三所不同學校的學生。"},{"en":"If participants are drawn only from one group, comparison becomes difficult.","zh":"如果參加者只取自一個群體，比較就變得困難。"},{"en":"The phrase describes the source of a sample.","zh":"這個短語描述樣本來源。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":6},{"front":"a criminal population","meaning":"犯罪人群","examples":[{"en":"Lombroso’s participants all came from a criminal population.","zh":"Lombroso 的參加者全部來自犯罪人群。"},{"en":"A criminal population is a group of people who have committed crimes or are in the criminal justice system.","zh":"「a criminal population」是曾犯罪或在刑事司法系統中的人群。"},{"en":"A prison study may use a criminal population as its sample.","zh":"監獄研究可能以犯罪人群作為樣本。"},{"en":"If researchers study only a criminal population, they cannot know how non-criminals compare.","zh":"如果研究人員只研究犯罪人群，他們無法知道非犯罪者如何比較。"},{"en":"The phrase describes the source group in Lombroso’s research.","zh":"這個短語描述 Lombroso 研究中的來源群體。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":6},{"front":"no comparison was made with","meaning":"沒有與……作比較","examples":[{"en":"No comparison was made with non-criminal control groups.","zh":"沒有與非犯罪對照組作比較。"},{"en":"No comparison was made with something means it was not compared against that thing.","zh":"「no comparison was made with」某物，意思是沒有把它與該物比較。"},{"en":"A school survey is weak if no comparison is made with students from other schools.","zh":"如果學校調查沒有與其他學校學生作比較，就會很薄弱。"},{"en":"If criminals are not compared with non-criminals, physical differences cannot be judged fairly.","zh":"如果罪犯沒有與非罪犯比較，身體差異就不能被公平判斷。"},{"en":"The phrase points to a missing research step.","zh":"這個短語指出缺失的研究步驟。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":6},{"front":"non-criminal control groups","meaning":"非犯罪對照組","examples":[{"en":"Lombroso did not use non-criminal control groups.","zh":"Lombroso 沒有使用非犯罪對照組。"},{"en":"Non-criminal control groups are comparison groups made up of people who have not committed crimes.","zh":"「non-criminal control groups」是由沒有犯罪的人組成的比較組。"},{"en":"A fair study of criminals’ features would need non-criminal control groups.","zh":"公平研究罪犯特徵需要非犯罪對照組。"},{"en":"Without such groups, researchers cannot tell whether a feature is truly unusual.","zh":"沒有這些組別，研究人員無法判斷某特徵是否真的不尋常。"},{"en":"The phrase is central to criticising Lombroso’s method.","zh":"這個短語是批評 Lombroso 方法的核心。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":6},{"front":"the concept of what constitutes a crime","meaning":"何謂犯罪的概念","examples":[{"en":"The concept of what constitutes a crime changes across societies.","zh":"何謂犯罪的概念在不同社會中會改變。"},{"en":"The concept of what constitutes a crime means the idea of what actions count as criminal.","zh":"「the concept of what constitutes a crime」指哪些行為算犯罪的概念。"},{"en":"A law class may discuss how different countries define protest, theft, or drug use.","zh":"法律課可能討論不同國家如何界定抗議、盜竊或吸毒。"},{"en":"If societies define crime differently, inherited criminality becomes harder to argue.","zh":"如果社會對犯罪定義不同，遺傳性犯罪傾向就更難論證。"},{"en":"The phrase focuses on how crime is socially and legally defined.","zh":"這個短語集中於犯罪如何被社會和法律界定。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":7},{"front":"constitute a crime","meaning":"構成犯罪","examples":[{"en":"Different societies may disagree about what constitutes a crime.","zh":"不同社會可能對甚麼構成犯罪有不同意見。"},{"en":"To constitute a crime means to count as a crime under law or social rules.","zh":"「constitute a crime」意思是在法律或社會規則下算作犯罪。"},{"en":"Taking someone’s bike without permission may constitute a crime.","zh":"未經允許拿走他人的單車可能構成犯罪。"},{"en":"If an action does not constitute a crime in one country, it may still be illegal in another.","zh":"如果某行為在一個國家不構成犯罪，在另一國仍可能違法。"},{"en":"The phrase is legal and formal.","zh":"這個短語屬於法律及正式用語。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":7},{"front":"in itself","meaning":"本身","examples":[{"en":"The concept of crime is in itself a social construct.","zh":"犯罪概念本身是一種社會建構。"},{"en":"In itself means considered alone, without adding anything else.","zh":"「in itself」意思是單獨考慮，不加上其他因素。"},{"en":"A low mark is not in itself proof that a student is lazy.","zh":"低分本身並不能證明學生懶惰。"},{"en":"If an idea is complex in itself, simple explanations may be misleading.","zh":"如果一個概念本身很複雜，簡單解釋可能誤導。"},{"en":"The phrase helps focus on the nature of one thing alone.","zh":"這個短語幫助集中於某事本身的性質。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":7},{"front":"a social construct","meaning":"社會建構","examples":[{"en":"Crime can be viewed as a social construct.","zh":"犯罪可以被視為一種社會建構。"},{"en":"A social construct is an idea created and shaped by society rather than fixed by nature alone.","zh":"「a social construct」是由社會創造和塑造，而不是單由自然固定的概念。"},{"en":"Ideas about politeness are social constructs because they differ across cultures.","zh":"關於禮貌的想法是社會建構，因為它們因文化而異。"},{"en":"If crime is partly a social construct, definitions can change with laws and values.","zh":"如果犯罪部分是社會建構，定義就會隨法律和價值改變。"},{"en":"The phrase is common in sociology.","zh":"這個短語常見於社會學。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":7},{"front":"vary cross-culturally","meaning":"跨文化地有所不同","examples":[{"en":"Ideas about crime vary cross-culturally.","zh":"關於犯罪的想法跨文化地有所不同。"},{"en":"To vary cross-culturally means to differ between cultures.","zh":"「vary cross-culturally」意思是在不同文化之間有所不同。"},{"en":"Table manners vary cross-culturally, so travellers should observe before judging.","zh":"餐桌禮儀跨文化地有所不同，所以旅客應先觀察再判斷。"},{"en":"If crime definitions vary cross-culturally, biological explanations become less simple.","zh":"如果犯罪定義跨文化地不同，生物解釋就不再簡單。"},{"en":"The phrase compares patterns across cultures.","zh":"這個短語比較不同文化中的模式。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":7},{"front":"over time","meaning":"隨時間而改變","examples":[{"en":"The definition of crime can change over time.","zh":"犯罪的定義可以隨時間而改變。"},{"en":"Over time means gradually as time passes.","zh":"「over time」意思是隨時間過去逐漸地。"},{"en":"A student’s confidence can grow over time with practice.","zh":"學生的信心可以隨練習而逐漸增長。"},{"en":"If laws and values change over time, crime definitions may also change.","zh":"如果法律和價值觀隨時間改變，犯罪定義也可能改變。"},{"en":"The phrase describes gradual change.","zh":"這個短語描述逐漸變化。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":7},{"front":"the argument that","meaning":"……的論點","examples":[{"en":"The argument that criminal behaviour is inherited is difficult to sustain.","zh":"犯罪行為是遺傳的這一論點難以維持。"},{"en":"The argument that means the claim or reasoning which says something is true.","zh":"「the argument that」意思是聲稱某事為真的主張或推理。"},{"en":"The argument that homework improves learning needs evidence, not just opinion.","zh":"功課能改善學習這一論點需要證據，而不只是意見。"},{"en":"If an argument has weak evidence, people may reject it.","zh":"如果論點證據薄弱，人們可能拒絕它。"},{"en":"The phrase introduces a specific claim for discussion.","zh":"這個短語引出要討論的具體主張。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":7},{"front":"be hard to sustain","meaning":"難以維持；難以支持","examples":[{"en":"The claim that criminal behaviour is inherited is hard to sustain.","zh":"犯罪行為是遺傳的這一主張難以支持。"},{"en":"To be hard to sustain means to be difficult to support or keep believable.","zh":"「be hard to sustain」意思是難以支持或保持可信。"},{"en":"A rumour is hard to sustain when clear evidence proves it false.","zh":"當清楚證據證明謠言錯誤，該謠言就難以維持。"},{"en":"If modern genetics rejects a simple theory, that theory becomes hard to sustain.","zh":"如果現代遺傳學否定簡單理論，該理論就難以支持。"},{"en":"The phrase describes a claim that cannot easily survive criticism.","zh":"這個短語描述不能輕易經受批評的主張。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":7},{"front":"in the light of","meaning":"鑑於；根據","examples":[{"en":"In the light of modern genetic research, Lombroso’s theory is no longer credible.","zh":"鑑於現代遺傳學研究，Lombroso 的理論不再可信。"},{"en":"In the light of means considering new evidence or information.","zh":"「in the light of」意思是鑑於新的證據或資料。"},{"en":"In the light of falling attendance, the school changed its after-school programme.","zh":"鑑於出席率下降，學校改變了課後計劃。"},{"en":"If new research appears, old theories may need to be judged in the light of it.","zh":"如果新研究出現，舊理論可能需要根據它重新評價。"},{"en":"The phrase introduces the evidence used to reassess something.","zh":"這個短語引入用來重新評估某事的證據。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":7},{"front":"modern genetic research","meaning":"現代遺傳學研究","examples":[{"en":"Modern genetic research challenges the idea of inherited criminality.","zh":"現代遺傳學研究挑戰遺傳性犯罪傾向的想法。"},{"en":"Modern genetic research is recent scientific study of genes and inheritance.","zh":"「modern genetic research」是近代對基因和遺傳的科學研究。"},{"en":"Doctors use modern genetic research to understand some inherited diseases.","zh":"醫生使用現代遺傳學研究來理解某些遺傳疾病。"},{"en":"If genetic research shows behaviours are complex, single-cause theories become weaker.","zh":"如果遺傳研究顯示行為很複雜，單一原因理論就變弱。"},{"en":"The phrase refers to current evidence about genes.","zh":"這個短語指關於基因的當代證據。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":7},{"front":"complex behaviours","meaning":"複雜行為","examples":[{"en":"Complex behaviours are not controlled by single genes.","zh":"複雜行為不是由單一基因控制。"},{"en":"Complex behaviours are actions shaped by many biological, social, and environmental factors.","zh":"「complex behaviours」是由許多生物、社會和環境因素塑造的行為。"},{"en":"Learning habits are complex behaviours because sleep, motivation, family, and teaching all matter.","zh":"學習習慣是複雜行為，因為睡眠、動機、家庭和教學都重要。"},{"en":"If a behaviour is complex, simple genetic explanations are usually inadequate.","zh":"如果行為很複雜，簡單基因解釋通常不足夠。"},{"en":"The phrase describes behaviour with many causes.","zh":"這個短語描述有多種成因的行為。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":7},{"front":"be controlled by single genes","meaning":"由單一基因控制","examples":[{"en":"Criminal behaviour is not considered to be controlled by single genes.","zh":"犯罪行為不被認為由單一基因控制。"},{"en":"To be controlled by single genes means to be determined by one gene alone.","zh":"「be controlled by single genes」意思是單由一個基因決定。"},{"en":"Some simple inherited traits may be influenced strongly by one gene, but behaviour is usually not.","zh":"有些簡單遺傳特徵可能受一個基因強烈影響，但行為通常不是。"},{"en":"If criminality were controlled by one gene, predicting crime would be much simpler than it is.","zh":"如果犯罪性由一個基因控制，預測犯罪會比現實簡單得多。"},{"en":"The phrase describes an overly simple genetic explanation.","zh":"這個短語描述過於簡化的基因解釋。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":8},{"front":"rule out any possibility of","meaning":"排除……的任何可能性","examples":[{"en":"Modern research rules out any possibility of inherited criminality in this simple form.","zh":"現代研究排除了這種簡單形式的遺傳性犯罪傾向的任何可能性。"},{"en":"To rule out any possibility of something means to show that it cannot be true or cannot happen.","zh":"「rule out any possibility of」某事，意思是證明它不可能為真或不會發生。"},{"en":"A doctor may run tests to rule out any possibility of a serious infection.","zh":"醫生可能進行測試，以排除嚴重感染的任何可能性。"},{"en":"If evidence rules out a theory, that theory should no longer be used.","zh":"如果證據排除某理論，該理論就不應再被使用。"},{"en":"The phrase means completely exclude an explanation.","zh":"這個短語意思是完全排除某種解釋。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":8},{"front":"inherited criminality","meaning":"遺傳性犯罪傾向","examples":[{"en":"The idea of inherited criminality is not supported by modern genetics.","zh":"遺傳性犯罪傾向的想法不受現代遺傳學支持。"},{"en":"Inherited criminality is the claim that criminal tendencies are passed through genes.","zh":"「inherited criminality」是犯罪傾向透過基因傳遞的主張。"},{"en":"A criminology course may discuss inherited criminality as an old and controversial idea.","zh":"犯罪學課可能把遺傳性犯罪傾向作為舊而具爭議的想法來討論。"},{"en":"If crime depends on laws and society, inherited criminality becomes difficult to prove.","zh":"如果犯罪取決於法律和社會，遺傳性犯罪傾向就難以證明。"},{"en":"The phrase refers to a biological theory of crime.","zh":"這個短語指一種犯罪的生物理論。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":8},{"front":"given his strong conviction","meaning":"鑑於他強烈相信……","examples":[{"en":"Given his strong conviction, Lombroso’s later change of view is surprising.","zh":"鑑於他強烈相信自己的觀點，Lombroso 後來改變看法令人意外。"},{"en":"Given his strong conviction means considering how firmly he believed something.","zh":"「given his strong conviction」意思是考慮到他多麼堅定相信某事。"},{"en":"Given her strong conviction that practice matters, the coach was surprised by the lazy training plan.","zh":"鑑於那位教練強烈相信練習很重要，她對懶散訓練計劃感到驚訝。"},{"en":"If someone changes their view despite strong conviction, the change is noteworthy.","zh":"如果某人即使有強烈信念仍改變看法，這種改變值得注意。"},{"en":"The phrase introduces background that makes a later fact surprising.","zh":"這個短語引入令後來事實顯得意外的背景。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":8},{"front":"strong conviction","meaning":"強烈信念","examples":[{"en":"Lombroso had a strong conviction that criminality had a biological basis.","zh":"Lombroso 有一種強烈信念，認為犯罪性有生物基礎。"},{"en":"A strong conviction is a firm belief that someone holds seriously.","zh":"「strong conviction」是某人認真持有的堅定信念。"},{"en":"A teacher may have a strong conviction that every student can improve.","zh":"老師可能有強烈信念，相信每位學生都能進步。"},{"en":"If a strong conviction lacks evidence, it can still lead people in the wrong direction.","zh":"如果強烈信念缺乏證據，它仍可能把人帶到錯誤方向。"},{"en":"The phrase describes belief strength, not proof.","zh":"這個短語描述信念強度，而不是證明。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":8},{"front":"biological disposition towards criminality","meaning":"對犯罪性的生物傾向","examples":[{"en":"Lombroso believed in a biological disposition towards criminality.","zh":"Lombroso 相信人有對犯罪性的生物傾向。"},{"en":"A biological disposition towards criminality means a supposed inborn tendency to commit crimes.","zh":"「biological disposition towards criminality」指所謂天生的犯罪傾向。"},{"en":"Old theories sometimes claimed that behaviour was fixed by biology.","zh":"舊理論有時聲稱行為由生物因素固定。"},{"en":"If criminality is seen as biological disposition only, rehabilitation may be undervalued.","zh":"如果犯罪性只被視為生物傾向，更生可能被低估。"},{"en":"The phrase describes a controversial biological explanation.","zh":"這個短語描述具爭議的生物解釋。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":8},{"front":"modify his views","meaning":"修改自己的觀點","examples":[{"en":"Lombroso later modified his views on criminal behaviour.","zh":"Lombroso 後來修改了自己對犯罪行為的觀點。"},{"en":"To modify one’s views means to change or adjust one’s opinions.","zh":"「modify one’s views」意思是改變或調整自己的意見。"},{"en":"A student may modify her view after hearing stronger evidence in a debate.","zh":"學生在辯論中聽到更強證據後，可能修改自己的觀點。"},{"en":"If new evidence appears, honest researchers may modify their views.","zh":"如果新證據出現，誠實研究者可能會修改觀點。"},{"en":"The phrase suggests adjustment rather than complete rejection.","zh":"這個短語暗示調整，而不一定是完全否定。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":8},{"front":"admit environmental influences","meaning":"承認環境影響","examples":[{"en":"He modified his theory to admit environmental influences.","zh":"他修改理論以承認環境影響。"},{"en":"To admit environmental influences means to accept that surroundings and life conditions affect behaviour.","zh":"「admit environmental influences」意思是承認周遭環境和生活條件會影響行為。"},{"en":"A school may admit family stress influences student performance.","zh":"學校可能承認家庭壓力會影響學生表現。"},{"en":"If a crime theory admits environmental influences, it considers poverty, peers, and upbringing.","zh":"如果犯罪理論承認環境影響，它會考慮貧窮、朋輩和成長背景。"},{"en":"The phrase broadens explanation beyond biology.","zh":"這個短語把解釋擴展到生物因素以外。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":8},{"front":"determine criminal behaviour","meaning":"決定犯罪行為","examples":[{"en":"Environmental influences may help determine criminal behaviour.","zh":"環境影響可能有助決定犯罪行為。"},{"en":"To determine criminal behaviour means to shape or decide whether criminal actions occur.","zh":"「determine criminal behaviour」意思是塑造或決定犯罪行動是否出現。"},{"en":"A person’s choices can be affected by family, school, neighbourhood, and opportunities.","zh":"一個人的選擇可能受家庭、學校、社區和機會影響。"},{"en":"If environment helps determine behaviour, changing conditions may reduce crime.","zh":"如果環境有助決定行為，改變條件可能減少犯罪。"},{"en":"The phrase describes factors that influence criminal actions.","zh":"這個短語描述影響犯罪行動的因素。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":8},{"front":"form the basis of","meaning":"構成……的基礎","examples":[{"en":"These views now form the basis of contemporary theories of criminality.","zh":"這些觀點現在構成當代犯罪性理論的基礎。"},{"en":"To form the basis of something means to provide the main foundation for it.","zh":"「form the basis of」某物，意思是為它提供主要基礎。"},{"en":"Clear rules form the basis of a fair classroom.","zh":"清楚規則構成公平課室的基礎。"},{"en":"If a theory considers both biology and environment, it can form the basis of modern explanations.","zh":"如果理論同時考慮生物和環境，它可以構成現代解釋的基礎。"},{"en":"The phrase shows what something is built on.","zh":"這個短語顯示某物建立在甚麼之上。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":8},{"front":"contemporary theories of criminality","meaning":"當代犯罪性理論","examples":[{"en":"Contemporary theories of criminality include both biological and environmental factors.","zh":"當代犯罪性理論包括生物和環境因素。"},{"en":"Contemporary theories of criminality are modern explanations of why crime occurs.","zh":"「contemporary theories of criminality」是現代對犯罪發生原因的解釋。"},{"en":"A modern criminology course may compare family, poverty, brain development, and peer influence.","zh":"現代犯罪學課可能比較家庭、貧窮、腦部發展和朋輩影響。"},{"en":"If theories are contemporary, they usually use current evidence and reject simple old claims.","zh":"如果理論是當代的，它們通常使用現有證據並拒絕簡單舊主張。"},{"en":"The phrase refers to present-day crime theories.","zh":"這個短語指現今的犯罪理論。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":8},{"front":"in recognition of","meaning":"為表揚……","examples":[{"en":"In recognition of his contribution, criminologists gave Lombroso an honorary title.","zh":"為表揚他的貢獻，犯罪學家給 Lombroso 一個榮譽稱號。"},{"en":"In recognition of means to show appreciation for someone’s work or achievement.","zh":"「in recognition of」意思是為了表示對某人工作或成就的欣賞。"},{"en":"A school may give a prize in recognition of a student’s volunteer service.","zh":"學校可能為表揚學生的義工服務而頒獎。"},{"en":"If someone’s work changes a field, honours may be given in recognition of that influence.","zh":"如果某人的工作改變一個領域，榮譽可能因表揚其影響而授予。"},{"en":"The phrase introduces the reason for an award or praise.","zh":"這個短語引出獎項或讚揚的原因。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":9},{"front":"contemporary criminologists","meaning":"當代犯罪學家","examples":[{"en":"Contemporary criminologists still recognise Lombroso’s historical importance.","zh":"當代犯罪學家仍承認 Lombroso 的歷史重要性。"},{"en":"Contemporary criminologists are modern scholars who study crime and criminal behaviour.","zh":"「contemporary criminologists」是研究犯罪和犯罪行為的現代學者。"},{"en":"Contemporary criminologists may study prisons, policing, poverty, and rehabilitation.","zh":"當代犯罪學家可能研究監獄、警務、貧窮和更生。"},{"en":"If criminologists study old theories, they can learn both their influence and their mistakes.","zh":"如果犯罪學家研究舊理論，他們可以學到其影響和錯誤。"},{"en":"The phrase refers to present-day crime researchers.","zh":"這個短語指當今犯罪研究者。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":9},{"front":"bestow on someone","meaning":"授予某人……","examples":[{"en":"Criminologists bestowed on Lombroso the title father of criminology.","zh":"犯罪學家授予 Lombroso「犯罪學之父」的稱號。"},{"en":"To bestow on someone means to formally give them an honour, title, or gift.","zh":"「bestow on someone」意思是正式授予某人榮譽、稱號或禮物。"},{"en":"A university may bestow an honorary degree on a respected scientist.","zh":"大學可能授予受尊敬科學家榮譽學位。"},{"en":"If a title is bestowed on someone, it shows public recognition.","zh":"如果稱號被授予某人，它顯示公開認可。"},{"en":"The phrase is formal and ceremonial.","zh":"這個短語正式且帶儀式感。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":9},{"front":"honorary title","meaning":"榮譽稱號","examples":[{"en":"Lombroso was given the honorary title father of criminology.","zh":"Lombroso 被授予「犯罪學之父」這一榮譽稱號。"},{"en":"An honorary title is a title given to recognise someone’s contribution, not necessarily a job role.","zh":"「honorary title」是為表揚某人貢獻而授予的稱號，不一定是職位。"},{"en":"A community leader may receive an honorary title for years of public service.","zh":"社區領袖可能因多年公共服務而獲得榮譽稱號。"},{"en":"If someone receives an honorary title, others are acknowledging their influence.","zh":"如果某人獲得榮譽稱號，其他人是在承認其影響。"},{"en":"The phrase refers to symbolic recognition.","zh":"這個短語指象徵性認可。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":9},{"front":"the father of criminology","meaning":"犯罪學之父","examples":[{"en":"Lombroso is sometimes called the father of criminology.","zh":"Lombroso 有時被稱為犯罪學之父。"},{"en":"The father of criminology means a person seen as an important founder of criminology.","zh":"「the father of criminology」指被視為犯罪學重要奠基者的人。"},{"en":"A scientist may be called the father of a field if his work helped establish it.","zh":"如果科學家的工作幫助建立一個領域，他可能被稱為該領域之父。"},{"en":"Even if Lombroso was flawed, his work helped move crime study toward evidence.","zh":"即使 Lombroso 有缺陷，他的工作仍幫助犯罪研究走向證據。"},{"en":"The phrase is an honorary label, not a literal family title.","zh":"這個短語是榮譽稱號，而不是字面上的家庭稱謂。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":9},{"front":"scientific failings","meaning":"科學上的缺陷","examples":[{"en":"Lombroso’s work had serious scientific failings.","zh":"Lombroso 的研究有嚴重科學上的缺陷。"},{"en":"Scientific failings are weaknesses in research method, evidence, or reasoning.","zh":"「scientific failings」是研究方法、證據或推理上的弱點。"},{"en":"A study without a control group has a serious scientific failing.","zh":"沒有對照組的研究有嚴重科學缺陷。"},{"en":"If scientific failings are ignored, weak conclusions may look convincing.","zh":"如果科學缺陷被忽略，薄弱結論可能看起來有說服力。"},{"en":"The phrase identifies problems in how research was done.","zh":"這個短語指出研究進行方式上的問題。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":9},{"front":"experimental approach","meaning":"實驗方法","examples":[{"en":"His experimental approach was scientifically weak.","zh":"他的實驗方法在科學上很薄弱。"},{"en":"An experimental approach is the way a researcher designs and carries out experiments.","zh":"「experimental approach」是研究者設計和進行實驗的方式。"},{"en":"A good experimental approach compares results with a fair control group.","zh":"良好實驗方法會把結果與公平對照組比較。"},{"en":"If the approach is weak, the results may not prove the theory.","zh":"如果方法薄弱，結果可能不能證明理論。"},{"en":"The phrase focuses on research method.","zh":"這個短語集中於研究方法。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":9},{"front":"be credited with","meaning":"因……而受到肯定","examples":[{"en":"Lombroso is credited with making the study of crime more empirical.","zh":"Lombroso 因使犯罪研究更實證而受到肯定。"},{"en":"To be credited with something means to be recognised for doing it.","zh":"「be credited with」某事，意思是因做成該事而被認可。"},{"en":"A teacher may be credited with improving students’ confidence.","zh":"老師可能因提升學生信心而受到肯定。"},{"en":"If a researcher changes a field, later scholars may credit him with that shift.","zh":"如果研究者改變一個領域，後來學者可能肯定他帶來那種轉變。"},{"en":"The phrase gives recognition for a contribution.","zh":"這個短語表達對貢獻的認可。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":9},{"front":"shift the study of","meaning":"轉移對……的研究方向","examples":[{"en":"Lombroso shifted the study of criminal behaviour towards science.","zh":"Lombroso 把犯罪行為研究轉向科學。"},{"en":"To shift the study of something means to move its focus or method in a new direction.","zh":"「shift the study of」某事，意思是把其焦點或方法轉向新方向。"},{"en":"A school may shift the study of history from memorising dates to analysing sources.","zh":"學校可能把歷史研究從背日期轉向分析來源。"},{"en":"If a field shifts toward science, evidence becomes more important.","zh":"如果一個領域轉向科學，證據就變得更重要。"},{"en":"The phrase describes a change in academic direction.","zh":"這個短語描述學術方向的改變。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":9},{"front":"from a moral basis to an empirical one","meaning":"從道德基礎轉向實證基礎","examples":[{"en":"He shifted criminology from a moral basis to an empirical one.","zh":"他把犯罪學從道德基礎轉向實證基礎。"},{"en":"From a moral basis to an empirical one means from ethical judgement to evidence-based study.","zh":"「from a moral basis to an empirical one」意思是從倫理判斷轉向以證據為基礎的研究。"},{"en":"A school may move discipline from personal blame to empirical analysis of behaviour patterns.","zh":"學校可能把紀律處理從個人責備轉向行為模式的實證分析。"},{"en":"If a field becomes empirical, observation and data matter more than opinion alone.","zh":"如果一個領域變得實證，觀察和數據就比單純意見更重要。"},{"en":"The phrase shows a major intellectual shift.","zh":"這個短語顯示重大思想轉變。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":9},{"front":"empirical","meaning":"實證的","examples":[{"en":"Lombroso helped make criminology more empirical.","zh":"Lombroso 幫助使犯罪學更實證。"},{"en":"Empirical means based on observation, measurement, or evidence.","zh":"「empirical」意思是建基於觀察、測量或證據。"},{"en":"An empirical study of sleep asks students to record actual sleeping hours.","zh":"關於睡眠的實證研究會要求學生記錄實際睡眠時間。"},{"en":"If a claim is empirical, it should be tested against real data.","zh":"如果主張是實證的，它應與真實數據作測試。"},{"en":"The word contrasts with purely philosophical or speculative thinking.","zh":"這個詞與純哲學或推測性思考形成對比。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":9},{"front":"thereby","meaning":"從而","examples":[{"en":"He used empirical methods, thereby placing criminology on a scientific footing.","zh":"他使用實證方法，從而使犯罪學建立在科學基礎上。"},{"en":"Thereby means as a result of that action.","zh":"「thereby」意思是由於該行動而造成某結果。"},{"en":"The school added more buses, thereby reducing late arrivals.","zh":"學校增加巴士，從而減少遲到。"},{"en":"If researchers collect data carefully, they thereby make conclusions more reliable.","zh":"如果研究人員仔細收集數據，他們從而令結論更可靠。"},{"en":"The word links an action with its result.","zh":"這個詞把行動與結果連繫起來。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":10},{"front":"place something on a more scientific footing","meaning":"使……建立在更科學的基礎上","examples":[{"en":"Lombroso placed the study of criminology on a more scientific footing.","zh":"Lombroso 使犯罪學研究建立在更科學的基礎上。"},{"en":"To place something on a more scientific footing means to make it more based on evidence and method.","zh":"「place something on a more scientific footing」意思是令某事更建基於證據和方法。"},{"en":"A school can place health education on a more scientific footing by using medical research.","zh":"學校可以透過使用醫學研究，使健康教育建立在更科學的基礎上。"},{"en":"If a subject gains data and testing, it becomes more scientifically grounded.","zh":"如果一個科目獲得數據和測試，它就變得更有科學根據。"},{"en":"The phrase describes making a field more rigorous.","zh":"這個短語描述使一個領域更嚴謹。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":10},{"front":"the argument for","meaning":"支持……的論點","examples":[{"en":"The argument for a biological basis to criminality resurfaced later.","zh":"支持犯罪性具有生物基礎的論點後來再度出現。"},{"en":"The argument for something is the reasoning that supports it.","zh":"「the argument for」某事，是支持它的推理。"},{"en":"The argument for later school start times often focuses on sleep and concentration.","zh":"支持較遲上課時間的論點常集中於睡眠和專注力。"},{"en":"If evidence is weak, the argument for a theory becomes less convincing.","zh":"如果證據薄弱，支持某理論的論點就較不具說服力。"},{"en":"The phrase introduces support for a position.","zh":"這個短語引入對某立場的支持。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":10},{"front":"a biological basis to criminality","meaning":"犯罪性的生物基礎","examples":[{"en":"Sheldon also proposed a biological basis to criminality.","zh":"Sheldon 也提出犯罪性的生物基礎。"},{"en":"A biological basis to criminality means a claim that crime is partly caused by bodily or genetic factors.","zh":"「a biological basis to criminality」指犯罪部分由身體或基因因素造成的主張。"},{"en":"A debate about crime may compare biological causes with social causes.","zh":"關於犯罪的辯論可能比較生物原因與社會原因。"},{"en":"If a theory claims a biological basis, it must explain how biology affects behaviour.","zh":"如果理論聲稱有生物基礎，它必須解釋生物如何影響行為。"},{"en":"The phrase does not mean biology is the only cause.","zh":"這個短語不代表生物是唯一原因。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":10},{"front":"resurface","meaning":"再度出現","examples":[{"en":"The biological argument resurfaced nearly a century later.","zh":"生物論點在接近一個世紀後再度出現。"},{"en":"To resurface means to appear again after being hidden, forgotten, or less discussed.","zh":"「resurface」意思是在被隱藏、忘記或較少討論後再次出現。"},{"en":"An old school rule may resurface when teachers discuss discipline again.","zh":"當老師再次討論紀律時，舊校規可能再度出現。"},{"en":"If an argument resurfaces, people begin paying attention to it again.","zh":"如果某論點再度出現，人們會再次注意它。"},{"en":"The phrase describes a return of an idea or issue.","zh":"這個短語描述想法或問題的回歸。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":10},{"front":"nearly a century later","meaning":"接近一個世紀後","examples":[{"en":"Nearly a century later, Sheldon proposed a new biological theory.","zh":"接近一個世紀後，Sheldon 提出新的生物理論。"},{"en":"Nearly a century later means almost one hundred years after an earlier event.","zh":"「nearly a century later」意思是在較早事件後接近一百年。"},{"en":"Nearly a century later, an old building may still influence the city’s identity.","zh":"接近一個世紀後，舊建築可能仍影響城市身份。"},{"en":"If an idea returns nearly a century later, it has survived a long historical gap.","zh":"如果一個想法接近一個世紀後回歸，它就跨過了很長歷史間隔。"},{"en":"The phrase gives a long time interval.","zh":"這個短語提供很長的時間距離。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":10},{"front":"theory of somatotypes","meaning":"體型分類理論","examples":[{"en":"Sheldon’s theory of somatotypes linked body type with personality.","zh":"Sheldon 的體型分類理論把體型與性格聯繫起來。"},{"en":"The theory of somatotypes classifies people by body shape and links it with temperament.","zh":"「theory of somatotypes」按身體形狀分類人，並把它與氣質聯繫起來。"},{"en":"A psychology class may study somatotypes as an old theory about body and behaviour.","zh":"心理學課可能把體型分類作為關於身體和行為的舊理論來研究。"},{"en":"If body type is linked with personality too simply, stereotyping can result.","zh":"如果體型與性格被過於簡單地聯繫起來，刻板印象可能出現。"},{"en":"The phrase names Sheldon’s body-type theory.","zh":"這個短語指出 Sheldon 的體型理論。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":10},{"front":"advance the theory that","meaning":"提出……理論","examples":[{"en":"Sheldon advanced the theory that people fell into three broad physical types.","zh":"Sheldon 提出人們屬於三種廣泛體型類別的理論。"},{"en":"To advance the theory that means to put forward a theory for others to consider.","zh":"「advance the theory that」意思是提出一項理論供他人考慮。"},{"en":"A scientist may advance the theory that diet affects sleep quality.","zh":"科學家可能提出飲食影響睡眠質素的理論。"},{"en":"If a theory is advanced, other researchers may test whether it is true.","zh":"如果理論被提出，其他研究人員可能測試它是否真實。"},{"en":"The phrase is formal and academic.","zh":"這個短語正式而學術化。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":10},{"front":"fall within","meaning":"屬於……範圍","examples":[{"en":"Sheldon believed that individuals fell within three broad physical types.","zh":"Sheldon 相信個人屬於三種廣泛體型類別範圍。"},{"en":"To fall within a category means to belong to that category or range.","zh":"「fall within」某類別，意思是屬於該類別或範圍。"},{"en":"A student’s score may fall within the top ten percent of the class.","zh":"學生成績可能屬於全班前百分之十範圍。"},{"en":"If people are forced to fall within fixed types, individual differences may be ignored.","zh":"如果人們被迫歸入固定類型，個體差異可能被忽略。"},{"en":"The phrase describes classification.","zh":"這個短語描述分類。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":10},{"front":"broad physical types","meaning":"廣泛的體型類別","examples":[{"en":"Sheldon divided people into three broad physical types.","zh":"Sheldon 把人分成三種廣泛的體型類別。"},{"en":"Broad physical types are general categories based on body shape.","zh":"「broad physical types」是根據身體形狀劃分的一般類別。"},{"en":"Sports coaches may describe broad physical types when discussing strength or endurance.","zh":"體育教練討論力量或耐力時，可能描述廣泛體型類別。"},{"en":"If categories are too broad, they may miss important individual differences.","zh":"如果類別太廣，它們可能忽略重要個體差異。"},{"en":"The phrase means general body-type groups.","zh":"這個短語指一般體型組別。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":10},{"front":"ectomorph","meaning":"外胚型體型的人；瘦長型","examples":[{"en":"An ectomorph was described as essentially thin.","zh":"外胚型體型的人被描述為基本上瘦削。"},{"en":"An ectomorph is a body type described as thin, narrow, and lightly built.","zh":"「ectomorph」是一種被描述為瘦、窄和輕巧的體型。"},{"en":"A tall, slim student might be described in old somatotype language as an ectomorph.","zh":"高而瘦的學生在舊體型分類語言中可能被描述為外胚型。"},{"en":"If body type is used to predict personality, the prediction may be unfair or inaccurate.","zh":"如果用體型預測性格，預測可能不公平或不準確。"},{"en":"The word belongs to Sheldon’s body-type theory.","zh":"這個詞屬於 Sheldon 的體型分類理論。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":10},{"front":"mesomorph","meaning":"中胚型體型的人；肌肉型","examples":[{"en":"A mesomorph was described as muscular and athletic.","zh":"中胚型體型的人被描述為肌肉發達而健壯。"},{"en":"A mesomorph is a body type described as strong, muscular, and physically powerful.","zh":"「mesomorph」是一種被描述為強壯、肌肉發達和有力量的體型。"},{"en":"A rugby player may have a mesomorphic build because of muscle and strength training.","zh":"欖球員可能因肌肉和力量訓練而有中胚型體格。"},{"en":"If mesomorphs are linked automatically with crime, the theory becomes stereotyping.","zh":"如果中胚型體型被自動與犯罪聯繫起來，理論就變成刻板定型。"},{"en":"The word is part of Sheldon’s somatotype classification.","zh":"這個詞是 Sheldon 體型分類的一部分。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":11},{"front":"endomorph","meaning":"內胚型體型的人；肥胖型","examples":[{"en":"An endomorph was said to be fat and rather lethargic.","zh":"內胚型體型的人被說成肥胖且頗為遲鈍乏力。"},{"en":"An endomorph is a body type described as rounder or heavier.","zh":"「endomorph」是一種被描述為較圓或較重的體型。"},{"en":"In old body-type theories, an endomorph was often linked with relaxed behaviour.","zh":"在舊體型理論中，內胚型常被與輕鬆行為聯繫起來。"},{"en":"If body size is used to judge character, people may be treated unfairly.","zh":"如果用體型判斷性格，人們可能受到不公平對待。"},{"en":"The word comes from Sheldon’s somatotype theory.","zh":"這個詞來自 Sheldon 的體型分類理論。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":11},{"front":"essentially thin","meaning":"基本上瘦削的","examples":[{"en":"The ectomorph was essentially thin.","zh":"外胚型體型基本上瘦削。"},{"en":"Essentially thin means basically or mainly slim in body shape.","zh":"「essentially thin」意思是體型基本上或主要是瘦削的。"},{"en":"A runner may be essentially thin but still strong and healthy.","zh":"跑手可能基本上瘦削，但仍然強壯健康。"},{"en":"If someone is described only as thin, many other personal qualities are ignored.","zh":"如果某人只被描述為瘦削，許多其他個人特質會被忽略。"},{"en":"The phrase gives the main physical description.","zh":"這個短語提供主要身體描述。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":11},{"front":"muscular and athletic","meaning":"肌肉發達而健壯的","examples":[{"en":"The mesomorph was muscular and athletic.","zh":"中胚型體型肌肉發達而健壯。"},{"en":"Muscular and athletic means strong-looking, fit, and suited to physical activity.","zh":"「muscular and athletic」意思是看起來強壯、健康並適合體能活動。"},{"en":"A swimmer may become muscular and athletic after years of training.","zh":"游泳運動員多年訓練後可能變得肌肉發達而健壯。"},{"en":"If someone is muscular and athletic, people may wrongly assume things about their personality.","zh":"如果某人肌肉發達而健壯，人們可能錯誤推測其性格。"},{"en":"The phrase describes body build and fitness.","zh":"這個短語描述體格和體能。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":11},{"front":"rather lethargic","meaning":"頗為遲鈍乏力的","examples":[{"en":"The endomorph was said to be rather lethargic.","zh":"內胚型體型被說成頗為遲鈍乏力。"},{"en":"Rather lethargic means quite low in energy or slow to act.","zh":"「rather lethargic」意思是相當缺乏精力或行動緩慢。"},{"en":"A student may feel rather lethargic after sleeping only four hours.","zh":"學生只睡四小時後可能感到頗為乏力。"},{"en":"If someone feels lethargic every day, health or lifestyle may need attention.","zh":"如果某人每天都感到乏力，健康或生活方式可能需要注意。"},{"en":"The phrase describes low energy, not moral weakness.","zh":"這個短語描述低能量，而不是道德弱點。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":11},{"front":"be associated with","meaning":"與……有關","examples":[{"en":"Each physical type was associated with a distinct personality.","zh":"每種體型都與一種獨特性格有關。"},{"en":"To be associated with something means to be linked or connected with it.","zh":"「be associated with」某物，意思是與它有聯繫或關聯。"},{"en":"Regular exercise is often associated with better mood and sleep.","zh":"定期運動常與更好心情和睡眠有關。"},{"en":"If two things are associated, it does not always mean one causes the other.","zh":"如果兩件事有關，並不一定代表一件事造成另一件事。"},{"en":"The phrase shows a connection, not necessarily proof of cause.","zh":"這個短語顯示關聯，而不一定證明因果。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":11},{"front":"distinct personality and temperament","meaning":"獨特的性格和氣質","examples":[{"en":"Each body type was linked to a distinct personality and temperament.","zh":"每種體型都被聯繫到獨特的性格和氣質。"},{"en":"Distinct personality and temperament means a clearly different pattern of character and emotional style.","zh":"「distinct personality and temperament」指清楚不同的性格和情緒風格模式。"},{"en":"One child may have a calm temperament, while another is more energetic and impulsive.","zh":"一個孩子可能氣質平靜，另一個則更有活力和衝動。"},{"en":"If body type is linked too strongly with temperament, individual variation may be ignored.","zh":"如果體型與氣質被過度強烈地聯繫起來，個體差異可能被忽略。"},{"en":"The phrase describes supposed differences in character.","zh":"這個短語描述所謂性格上的差異。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":11},{"front":"solitary and restrained nature","meaning":"孤僻而克制的性情","examples":[{"en":"Ectomorphs were characterised by a solitary and restrained nature.","zh":"外胚型體型被描述為具有孤僻而克制的性情。"},{"en":"A solitary and restrained nature means a quiet personality that avoids crowds and controls emotion.","zh":"「solitary and restrained nature」指安靜、避開人群並控制情緒的性格。"},{"en":"A student with a restrained nature may prefer reading alone to joining loud games.","zh":"性情克制的學生可能較喜歡獨自閱讀，而不是參加吵鬧遊戲。"},{"en":"If someone is solitary, it does not mean they are unhappy or antisocial.","zh":"如果某人孤僻，這不代表他不快樂或反社會。"},{"en":"The phrase describes temperament, not physical appearance.","zh":"這個短語描述氣質，而不是外貌。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":11},{"front":"adventurous","meaning":"有冒險精神的","examples":[{"en":"Mesomorphs were said to be adventurous.","zh":"中胚型體型被說成有冒險精神。"},{"en":"Adventurous means willing to try new, exciting, or risky experiences.","zh":"「adventurous」意思是願意嘗試新鮮、刺激或有風險的經歷。"},{"en":"An adventurous student may join a hiking trip even if the route is difficult.","zh":"有冒險精神的學生可能參加遠足，即使路線困難。"},{"en":"If someone is adventurous, they may seek challenges more often.","zh":"如果某人有冒險精神，他可能較常尋求挑戰。"},{"en":"The word describes attitude toward new experiences.","zh":"這個詞描述對新經歷的態度。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":11},{"front":"relaxed and pleasure-loving","meaning":"輕鬆而愛享樂的","examples":[{"en":"Endomorphs were described as relaxed and pleasure-loving.","zh":"內胚型體型被描述為輕鬆而愛享樂。"},{"en":"Relaxed and pleasure-loving means easy-going and fond of comfort or enjoyment.","zh":"「relaxed and pleasure-loving」意思是隨和並喜歡舒適或享受。"},{"en":"A relaxed and pleasure-loving person may enjoy long meals with friends.","zh":"輕鬆而愛享樂的人可能喜歡與朋友慢慢吃飯。"},{"en":"If someone values comfort, it does not prove anything about morality or ability.","zh":"如果某人重視舒適，這不能證明任何道德或能力問題。"},{"en":"The phrase describes personality in Sheldon’s theory.","zh":"這個短語描述 Sheldon 理論中的性格。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":11},{"front":"corresponding to this physical type","meaning":"符合這種體型的","examples":[{"en":"Those corresponding to this physical type were said to have criminal tendencies.","zh":"符合這種體型的人被說成具有犯罪傾向。"},{"en":"Corresponding to this physical type means matching or belonging to this body category.","zh":"「corresponding to this physical type」意思是符合或屬於這種身體類別。"},{"en":"Students corresponding to a certain age group may be placed in the same sports competition.","zh":"符合某年齡組別的學生可能被安排在同一體育比賽中。"},{"en":"If people are classified by body type, those corresponding to one type may be labelled unfairly.","zh":"如果人們按體型分類，符合某類型的人可能被不公平標籤。"},{"en":"The phrase links people to a category.","zh":"這個短語把人連到某一類別。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":11},{"front":"criminal tendencies","meaning":"犯罪傾向","examples":[{"en":"Sheldon claimed that mesomorphs had criminal tendencies.","zh":"Sheldon 聲稱中胚型體型的人有犯罪傾向。"},{"en":"Criminal tendencies are supposed inclinations toward committing crimes.","zh":"「criminal tendencies」是所謂傾向於犯罪的特質。"},{"en":"A psychologist would need strong evidence before saying someone has criminal tendencies.","zh":"心理學家在說某人有犯罪傾向前，需要強力證據。"},{"en":"If society labels a group as having criminal tendencies, discrimination may follow.","zh":"如果社會標籤某群體有犯罪傾向，歧視可能隨之而來。"},{"en":"The phrase describes a claimed tendency, not a proven act.","zh":"這個短語描述被聲稱的傾向，而不是已證實行為。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":12},{"front":"by linking","meaning":"透過把……聯繫起來","examples":[{"en":"By linking body type with personality, Sheldon suggested a hereditary aspect to crime.","zh":"透過把體型與性格聯繫起來，Sheldon 暗示犯罪有遺傳層面。"},{"en":"By linking means by connecting one thing with another.","zh":"「by linking」意思是透過把一事與另一事連接起來。"},{"en":"By linking sleep with exam performance, a teacher can show students why rest matters.","zh":"透過把睡眠與考試表現聯繫起來，老師可以向學生顯示休息為何重要。"},{"en":"If researchers link body type with behaviour, they must prove the connection carefully.","zh":"如果研究人員把體型與行為聯繫起來，他們必須仔細證明這種關聯。"},{"en":"The phrase explains the method used to build an argument.","zh":"這個短語解釋建立論點的方法。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":12},{"front":"inherited physical types","meaning":"遺傳體型","examples":[{"en":"Sheldon linked inherited physical types with personality.","zh":"Sheldon 把遺傳體型與性格聯繫起來。"},{"en":"Inherited physical types are body forms thought to be passed down through genes.","zh":"「inherited physical types」是被認為透過基因傳下來的身體形態。"},{"en":"A child may inherit height or body shape from parents.","zh":"孩子可能從父母遺傳身高或體形。"},{"en":"If body type is inherited, that still does not prove personality is inherited in the same way.","zh":"即使體型是遺傳的，也不證明性格以同樣方式遺傳。"},{"en":"The phrase connects biology with body classification.","zh":"這個短語把生物學與體型分類連繫起來。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":12},{"front":"hypothesise a hereditary aspect to","meaning":"假設……具有遺傳層面","examples":[{"en":"Sheldon hypothesised a hereditary aspect to criminal behaviour.","zh":"Sheldon 假設犯罪行為具有遺傳層面。"},{"en":"To hypothesise a hereditary aspect to something means to suggest that inheritance partly explains it.","zh":"「hypothesise a hereditary aspect to」某事，意思是假設遺傳部分解釋它。"},{"en":"Scientists may hypothesise a hereditary aspect to a disease after seeing family patterns.","zh":"科學家看到家族模式後，可能假設某疾病具有遺傳層面。"},{"en":"If a hereditary aspect is proposed, genetic evidence is needed.","zh":"如果提出遺傳層面，就需要遺傳證據。"},{"en":"The phrase introduces an unproven inherited explanation.","zh":"這個短語引入未經證實的遺傳解釋。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":12},{"front":"mesomorphic college students","meaning":"中胚型大學生","examples":[{"en":"Sheldon studied mesomorphic college students.","zh":"Sheldon 研究了中胚型大學生。"},{"en":"Mesomorphic college students are university students with a muscular body type.","zh":"「mesomorphic college students」是具有肌肉型體格的大學生。"},{"en":"A sports science study might include mesomorphic students from athletic teams.","zh":"體育科學研究可能包括來自運動隊的中胚型學生。"},{"en":"If a sample includes only one body type, the results may not apply to everyone.","zh":"如果樣本只包括一種體型，結果未必適用於所有人。"},{"en":"The phrase identifies the group Sheldon studied.","zh":"這個短語指出 Sheldon 研究的群體。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":12},{"front":"to some extent","meaning":"在某程度上","examples":[{"en":"Sheldon’s studies did, to some extent, confirm his theory.","zh":"Sheldon 的研究在某程度上確實證實了他的理論。"},{"en":"To some extent means partly, but not completely.","zh":"「to some extent」意思是部分地，但不是完全地。"},{"en":"A student may understand the lesson to some extent but still need more practice.","zh":"學生可能在某程度上明白課堂，但仍需要更多練習。"},{"en":"If evidence supports a theory only to some extent, the conclusion should be cautious.","zh":"如果證據只在某程度上支持理論，結論應該謹慎。"},{"en":"The phrase softens a claim.","zh":"這個短語弱化一項主張。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":12},{"front":"confirm his theory","meaning":"證實他的理論","examples":[{"en":"His studies seemed to confirm his theory to some extent.","zh":"他的研究似乎在某程度上證實了他的理論。"},{"en":"To confirm a theory means to provide evidence that supports it.","zh":"「confirm a theory」意思是提供支持該理論的證據。"},{"en":"A science experiment may confirm a student’s theory about plant growth.","zh":"科學實驗可能證實學生關於植物生長的理論。"},{"en":"If later research fails to confirm a theory, confidence in it decreases.","zh":"如果後來研究未能證實理論，人們對它的信心會下降。"},{"en":"The phrase means support through evidence, not simply agree.","zh":"這個短語指透過證據支持，而不只是同意。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":12},{"front":"a later study conducted by","meaning":"由……進行的較後期研究","examples":[{"en":"A later study conducted by Putwain and Sammons partly supported Sheldon’s theory.","zh":"由 Putwain 和 Sammons 進行的較後期研究部分支持 Sheldon 的理論。"},{"en":"A later study conducted by someone is research done afterwards by named researchers.","zh":"「a later study conducted by」某人，是之後由具名研究者完成的研究。"},{"en":"A later study conducted by another university may check earlier results.","zh":"由另一所大學進行的較後期研究可能核查早期結果。"},{"en":"If later studies support a theory, the theory may gain credibility.","zh":"如果後來研究支持某理論，該理論可能更可信。"},{"en":"The phrase identifies both timing and researchers.","zh":"這個短語同時指出時間和研究人員。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":12},{"front":"as recently as","meaning":"直至近至……","examples":[{"en":"A related study was conducted as recently as 2002.","zh":"一項相關研究直至近至2002年才進行。"},{"en":"As recently as means as late as a surprisingly recent time.","zh":"「as recently as」意思是直到令人意外地接近現在的時間。"},{"en":"Some old school rules were still used as recently as last year.","zh":"有些舊校規直到近至去年仍在使用。"},{"en":"If an idea was studied as recently as 2002, it did not disappear long ago.","zh":"如果某想法直至2002年仍被研究，它並不是很久以前已消失。"},{"en":"The phrase emphasises recency.","zh":"這個短語強調時間接近現在。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":12},{"front":"in partial support of","meaning":"部分支持……","examples":[{"en":"In partial support of Sheldon’s theory, testosterone may explain the link.","zh":"部分支持 Sheldon 理論的是，睾酮可能解釋該關聯。"},{"en":"In partial support of means giving some evidence for, but not fully proving.","zh":"「in partial support of」意思是提供一些支持，但未能完全證明。"},{"en":"A small survey may be in partial support of a school policy but not prove it completely.","zh":"小型調查可能部分支持某校政，但不能完全證明它。"},{"en":"If evidence is only partial, the conclusion should remain careful.","zh":"如果證據只是部分支持，結論仍應保持謹慎。"},{"en":"The phrase signals limited support.","zh":"這個短語表示有限支持。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":12},{"front":"increased testosterone","meaning":"較高的睾酮水平","examples":[{"en":"Increased testosterone may be associated with a mesomorphic build.","zh":"較高的睾酮水平可能與中胚型體格有關。"},{"en":"Increased testosterone means a higher level of the hormone testosterone.","zh":"「increased testosterone」意思是睾酮這種荷爾蒙水平較高。"},{"en":"Doctors may measure testosterone levels when studying certain health conditions.","zh":"醫生研究某些健康狀況時，可能量度睾酮水平。"},{"en":"If testosterone is higher, it may affect muscle development and energy.","zh":"如果睾酮較高，它可能影響肌肉發展和能量。"},{"en":"The phrase describes a biological factor, not a complete explanation of behaviour.","zh":"這個短語描述生物因素，而不是行為的完整解釋。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":12},{"front":"be associated with a mesomorphic build","meaning":"與中胚型體格有關","examples":[{"en":"Increased testosterone is associated with a mesomorphic build.","zh":"較高睾酮水平與中胚型體格有關。"},{"en":"To be associated with a mesomorphic build means to be linked with a muscular body type.","zh":"「be associated with a mesomorphic build」意思是與肌肉型體格有關。"},{"en":"Strength training may be associated with a more muscular build.","zh":"力量訓練可能與較肌肉發達的體格有關。"},{"en":"If a hormone is associated with body build, it may help explain physical differences.","zh":"如果荷爾蒙與體格有關，它可能幫助解釋身體差異。"},{"en":"The phrase describes correlation, not automatic causation.","zh":"這個短語描述相關性，而不是自動因果。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":13},{"front":"mesomorphic build","meaning":"中胚型體格","examples":[{"en":"A mesomorphic build may be linked with higher testosterone.","zh":"中胚型體格可能與較高睾酮水平有關。"},{"en":"A mesomorphic build is a muscular, athletic body shape.","zh":"「mesomorphic build」是肌肉發達、健壯的體形。"},{"en":"A sprinter may have a mesomorphic build because speed training develops muscle.","zh":"短跑選手可能有中胚型體格，因為速度訓練會發展肌肉。"},{"en":"If someone has a mesomorphic build, it still does not prove anything about character.","zh":"如果某人有中胚型體格，這仍不能證明任何性格特質。"},{"en":"The phrase describes body structure only.","zh":"這個短語只描述身體結構。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":13},{"front":"help explain the link between","meaning":"有助解釋……之間的關聯","examples":[{"en":"Testosterone could help explain the link between body type and criminality.","zh":"睾酮可能有助解釋體型與犯罪性之間的關聯。"},{"en":"To help explain the link between two things means to make their connection easier to understand.","zh":"「help explain the link between」兩件事，意思是令它們的關係更容易理解。"},{"en":"Sleep data may help explain the link between tiredness and low exam scores.","zh":"睡眠數據可能有助解釋疲倦與低考試分數之間的關聯。"},{"en":"If a third factor explains a link, the original connection may be more complex than it seems.","zh":"如果第三因素解釋某關聯，原本的關係可能比看起來更複雜。"},{"en":"The phrase points to a possible explanation for a relationship.","zh":"這個短語指出某關係的可能解釋。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":13},{"front":"body type and criminality","meaning":"體型與犯罪性的關係","examples":[{"en":"Researchers examined the link between body type and criminality.","zh":"研究人員考察體型與犯罪性的關係。"},{"en":"Body type and criminality refers to the proposed relationship between physique and crime tendency.","zh":"「body type and criminality」指體格與犯罪傾向之間被提出的關係。"},{"en":"A criminology student may study why old theories linked body shape with crime.","zh":"犯罪學學生可能研究舊理論為何把體形與犯罪聯繫起來。"},{"en":"If body type is used to judge criminality, unfair stereotypes can follow.","zh":"如果用體型判斷犯罪性，不公平刻板印象可能隨之而來。"},{"en":"The phrase summarises a controversial research question.","zh":"這個短語概括一個具爭議的研究問題。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":13},{"front":"social prejudices","meaning":"社會偏見","examples":[{"en":"Social prejudices may also influence the link between body type and crime.","zh":"社會偏見也可能影響體型與犯罪之間的關聯。"},{"en":"Social prejudices are unfair beliefs about groups of people.","zh":"「social prejudices」是關於人群的不公平信念。"},{"en":"A teacher may challenge social prejudices when students make unfair assumptions about classmates.","zh":"當學生對同學作出不公平假設時，老師可能挑戰社會偏見。"},{"en":"If police or employers treat muscular people as more dangerous, prejudice may shape outcomes.","zh":"如果警察或僱主把肌肉發達的人視為較危險，偏見可能塑造結果。"},{"en":"The phrase points to society’s bias, not biology alone.","zh":"這個短語指出社會偏見，而不只是生物因素。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":13},{"front":"self-fulfilling prophecies","meaning":"自我實現預言","examples":[{"en":"Self-fulfilling prophecies may affect how mesomorphic people behave or are treated.","zh":"自我實現預言可能影響中胚型人士的行為或他們被對待的方式。"},{"en":"A self-fulfilling prophecy happens when expectations cause behaviour that makes the expectation come true.","zh":"「self-fulfilling prophecy」是期望導致行為，令該期望成真的情況。"},{"en":"If a teacher expects a student to fail, the student may lose confidence and perform worse.","zh":"如果老師預期學生失敗，學生可能失去信心並表現更差。"},{"en":"If society treats one body type as dangerous, some people may respond to that treatment.","zh":"如果社會把某種體型視為危險，有些人可能回應這種對待方式。"},{"en":"The phrase explains how belief can create reality.","zh":"這個短語解釋信念如何創造現實。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":13},{"front":"be at play","meaning":"在起作用；有影響","examples":[{"en":"Social prejudices may be at play in the correlation.","zh":"社會偏見可能在該相關性中起作用。"},{"en":"To be at play means to be influencing a situation, often behind the scenes.","zh":"「be at play」意思是在影響某情況，通常是在背後發揮作用。"},{"en":"Stress may be at play when a normally calm student becomes angry.","zh":"當平常冷靜的學生變得憤怒時，壓力可能正在起作用。"},{"en":"If prejudice is at play, the observed pattern may not be purely biological.","zh":"如果偏見在起作用，觀察到的模式就未必純粹是生物性的。"},{"en":"The phrase identifies a hidden factor.","zh":"這個短語指出隱藏因素。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":13},{"front":"above-average correlation between","meaning":"……之間高於平均的相關性","examples":[{"en":"There may be an above-average correlation between mesomorphic types and criminal behaviour.","zh":"中胚型類型與犯罪行為之間可能有高於平均的相關性。"},{"en":"An above-average correlation between two things means they are linked more strongly than usual.","zh":"「above-average correlation between」兩件事，意思是它們之間的關聯比一般更強。"},{"en":"A school may find an above-average correlation between attendance and exam results.","zh":"學校可能發現出席率與考試成績之間有高於平均的相關性。"},{"en":"If correlation is above average, researchers still need to explain why it exists.","zh":"如果相關性高於平均，研究人員仍需要解釋原因。"},{"en":"The phrase describes a statistical relationship, not definite cause.","zh":"這個短語描述統計關係，而不是確定因果。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":13},{"front":"following on from","meaning":"承接……","examples":[{"en":"Following on from Sheldon’s hypothesis, another biological argument was proposed.","zh":"承接 Sheldon 的假說，另一個生物論點被提出。"},{"en":"Following on from means continuing from or building on an earlier idea.","zh":"「following on from」意思是承接或建立在較早想法之上。"},{"en":"Following on from last week’s lesson, the teacher introduced a harder grammar point.","zh":"承接上星期的課堂，老師介紹了一個更難的文法點。"},{"en":"If a new theory follows on from an old one, it may keep some assumptions while changing others.","zh":"如果新理論承接舊理論，它可能保留一些假設並改變另一些。"},{"en":"The phrase shows sequence and connection.","zh":"這個短語顯示順序和連繫。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":13},{"front":"a further argument for","meaning":"進一步支持……的論點","examples":[{"en":"A further argument for a biological disposition to criminality appeared in the 1960s.","zh":"在1960年代，進一步支持犯罪性具有生物傾向的論點出現。"},{"en":"A further argument for something is another reason or claim supporting it.","zh":"「a further argument for」某事，是支持它的另一個理由或主張。"},{"en":"Better health is a further argument for improving school lunches.","zh":"更好健康是進一步支持改善學校午餐的論點。"},{"en":"If further arguments appear, a debate becomes broader and more complex.","zh":"如果進一步論點出現，辯論會變得更廣和更複雜。"},{"en":"The phrase adds another supporting point.","zh":"這個短語加入另一個支持點。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":13},{"front":"hereditary tendencies","meaning":"遺傳傾向","examples":[{"en":"Hereditary tendencies were linked to a genetic defect.","zh":"遺傳傾向被與基因缺陷聯繫起來。"},{"en":"Hereditary tendencies are tendencies thought to be passed through genes.","zh":"「hereditary tendencies」是被認為透過基因傳遞的傾向。"},{"en":"A family history of a disease may suggest hereditary tendencies.","zh":"某疾病的家族史可能顯示遺傳傾向。"},{"en":"If a tendency is hereditary, it may appear across generations.","zh":"如果某傾向是遺傳的，它可能跨世代出現。"},{"en":"The phrase refers to inherited patterns, not personal choice alone.","zh":"這個短語指遺傳模式，而不只是個人選擇。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":13},{"front":"genetic defect","meaning":"基因缺陷","examples":[{"en":"The theory linked criminality to a genetic defect.","zh":"該理論把犯罪性與基因缺陷聯繫起來。"},{"en":"A genetic defect is a harmful or unusual change in genes or chromosomes.","zh":"「genetic defect」是基因或染色體中有害或異常的變化。"},{"en":"Some genetic defects can affect health from birth.","zh":"有些基因缺陷可以從出生起影響健康。"},{"en":"If a theory links behaviour to a genetic defect, strong biological evidence is needed.","zh":"如果理論把行為與基因缺陷聯繫起來，就需要強力生物證據。"},{"en":"The phrase describes a biological abnormality.","zh":"這個短語描述生物異常。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":14},{"front":"chromosomal abnormality","meaning":"染色體異常","examples":[{"en":"Criminality was also linked to chromosomal abnormality.","zh":"犯罪性也被與染色體異常聯繫起來。"},{"en":"A chromosomal abnormality is an unusual number or structure of chromosomes.","zh":"「chromosomal abnormality」是染色體數目或結構異常。"},{"en":"Doctors may detect a chromosomal abnormality through genetic testing.","zh":"醫生可能透過基因測試偵測染色體異常。"},{"en":"If a chromosome pattern is unusual, it does not automatically explain behaviour.","zh":"如果染色體模式不尋常，它不會自動解釋行為。"},{"en":"The phrase belongs to genetics.","zh":"這個短語屬於遺傳學。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":14},{"front":"variations in","meaning":"……的變異","examples":[{"en":"Variations in the normal male genotype were studied.","zh":"正常男性基因型的變異受到研究。"},{"en":"Variations in something are differences or changes within it.","zh":"「variations in」某物，是其內部的差異或變化。"},{"en":"Teachers may notice variations in students’ reading speed.","zh":"老師可能注意到學生閱讀速度的差異。"},{"en":"If researchers study variations in genes, they look at differences between genetic patterns.","zh":"如果研究人員研究基因變異，他們會考察遺傳模式之間的差異。"},{"en":"The phrase describes differences inside a category.","zh":"這個短語描述類別內部差異。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":14},{"front":"the normal male XY genotype","meaning":"正常男性 XY 基因型","examples":[{"en":"The normal male XY genotype was compared with abnormal chromosome patterns.","zh":"正常男性 XY 基因型被與異常染色體模式比較。"},{"en":"The normal male XY genotype is the usual male chromosome pattern of one X and one Y chromosome.","zh":"「the normal male XY genotype」是通常男性的一條 X 和一條 Y 染色體模式。"},{"en":"Biology students learn about the XY genotype when studying sex chromosomes.","zh":"生物學生研究性染色體時會學到 XY 基因型。"},{"en":"If a chromosome pattern differs from XY, researchers may study whether it affects development.","zh":"如果染色體模式不同於 XY，研究人員可能研究它是否影響發展。"},{"en":"The phrase describes a standard genetic pattern.","zh":"這個短語描述標準遺傳模式。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":14},{"front":"be hypothesised to predispose","meaning":"被假設會使……較易有……傾向","examples":[{"en":"Variations in genotype were hypothesised to predispose men to crime.","zh":"基因型變異被假設會使男性較易有犯罪傾向。"},{"en":"To be hypothesised to predispose means to be suggested as making someone more likely to develop a tendency.","zh":"「be hypothesised to predispose」意思是被假設會使某人較易形成某傾向。"},{"en":"Lack of sleep may be hypothesised to predispose students to poor concentration.","zh":"睡眠不足可能被假設會使學生較易專注力差。"},{"en":"If a factor is only hypothesised, it still needs evidence.","zh":"如果某因素只是被假設，它仍需要證據。"},{"en":"The phrase introduces an unproven risk explanation.","zh":"這個短語引入未經證實的風險解釋。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":14},{"front":"predispose men to criminal behaviour","meaning":"使男性較易有犯罪傾向","examples":[{"en":"Some chromosome patterns were thought to predispose men to criminal behaviour.","zh":"有些染色體模式被認為會使男性較易有犯罪傾向。"},{"en":"To predispose men to criminal behaviour means to make men more likely to commit crimes.","zh":"「predispose men to criminal behaviour」意思是使男性較可能犯罪。"},{"en":"A difficult childhood may predispose some people to risky choices, but it does not determine them.","zh":"困難童年可能使某些人較易作出冒險選擇，但不會決定他們必然如此。"},{"en":"If a factor predisposes someone to behaviour, other factors still matter.","zh":"如果某因素使人較易有某行為，其他因素仍然重要。"},{"en":"The phrase describes increased likelihood, not certainty.","zh":"這個短語描述可能性增加，而不是必然。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":14},{"front":"homicide","meaning":"殺人罪；殺人行為","examples":[{"en":"The theory linked chromosome patterns with homicide and violent crime.","zh":"該理論把染色體模式與殺人行為和暴力罪行聯繫起來。"},{"en":"Homicide means the killing of one person by another.","zh":"「homicide」意思是一個人殺死另一個人。"},{"en":"Police investigate homicide cases very carefully because a life has been lost.","zh":"警方非常仔細調查殺人案件，因為有人失去生命。"},{"en":"If a theory links biology with homicide, the evidence must be extremely strong.","zh":"如果理論把生物因素與殺人行為聯繫起來，證據必須極強。"},{"en":"The word is a legal and formal term.","zh":"這個詞是法律及正式用語。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":14},{"front":"violent crime","meaning":"暴力罪行","examples":[{"en":"The XYY genotype was wrongly associated with violent crime.","zh":"XYY 基因型被錯誤地與暴力罪行聯繫起來。"},{"en":"Violent crime is crime involving physical force or threat of harm.","zh":"「violent crime」是涉及身體武力或傷害威脅的罪行。"},{"en":"Robbery with weapons and serious assault are examples of violent crime.","zh":"持械行劫和嚴重襲擊都是暴力罪行例子。"},{"en":"If a group is falsely linked with violent crime, stigma can result.","zh":"如果某群體被錯誤地與暴力罪行聯繫起來，污名可能出現。"},{"en":"The phrase describes a serious category of crime.","zh":"這個短語描述嚴重罪行類別。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":14},{"front":"be based on","meaning":"基於……","examples":[{"en":"The theory was based on an unproven assumption.","zh":"該理論基於未經證實的假設。"},{"en":"To be based on something means to use it as the foundation or main support.","zh":"「be based on」某物，意思是以它作為基礎或主要支持。"},{"en":"A school rule should be based on safety needs, not rumours.","zh":"校規應基於安全需要，而不是謠言。"},{"en":"If a theory is based on weak assumptions, its conclusions may fail.","zh":"如果理論基於薄弱假設，其結論可能失敗。"},{"en":"The phrase shows what supports an idea.","zh":"這個短語顯示想法由甚麼支撐。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":14},{"front":"unproven assumption","meaning":"未經證實的假設","examples":[{"en":"The theory rested on an unproven assumption about chromosomes.","zh":"該理論建立在關於染色體的未經證實假設上。"},{"en":"An unproven assumption is an idea accepted without enough evidence.","zh":"「unproven assumption」是沒有足夠證據卻被接受的想法。"},{"en":"Saying a quiet student is lazy is an unproven assumption if no one has checked the reason.","zh":"如果沒有人查明原因，就說安靜學生懶惰，是未經證實的假設。"},{"en":"If research begins with unproven assumptions, the findings may be unreliable.","zh":"如果研究從未經證實的假設開始，結果可能不可靠。"},{"en":"The phrase warns that a claim has not been demonstrated.","zh":"這個短語警告某主張尚未被證明。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":14},{"front":"possession of an extra chromosome","meaning":"擁有額外染色體","examples":[{"en":"Possession of an extra chromosome was assumed to affect behaviour.","zh":"擁有額外染色體被假設會影響行為。"},{"en":"Possession of an extra chromosome means having one more chromosome than the usual pattern.","zh":"「possession of an extra chromosome」意思是比通常模式多一條染色體。"},{"en":"Genetic testing can show whether a person has an extra chromosome.","zh":"基因測試可以顯示一個人是否擁有額外染色體。"},{"en":"If someone has an extra chromosome, its effects must be studied carefully rather than guessed.","zh":"如果某人有額外染色體，其影響必須仔細研究，而不是猜測。"},{"en":"The phrase describes a genetic condition.","zh":"這個短語描述遺傳狀況。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":14},{"front":"feminise a man","meaning":"使男性女性化","examples":[{"en":"The theory assumed that an extra X chromosome would feminise a man.","zh":"該理論假設額外 X 染色體會使男性女性化。"},{"en":"To feminise a man means to make him appear or behave in ways traditionally seen as feminine.","zh":"「feminise a man」意思是使男性顯得或行為上更像傳統認為的女性化。"},{"en":"Old stereotypes may wrongly treat gentle behaviour as something that feminises men.","zh":"舊刻板印象可能錯誤地把溫和行為視為使男性女性化。"},{"en":"If a theory assumes chromosomes simply feminise or masculinise behaviour, it may be too simplistic.","zh":"如果理論假設染色體簡單地使行為女性化或男性化，它可能過於簡化。"},{"en":"The phrase reflects outdated gender assumptions in the passage.","zh":"這個短語反映文章中的過時性別假設。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":15},{"front":"conversely","meaning":"相反地","examples":[{"en":"Conversely, an extra Y chromosome was thought to make a man more aggressive.","zh":"相反地，額外 Y 染色體被認為會使男性更具攻擊性。"},{"en":"Conversely means in the opposite way or on the other hand.","zh":"「conversely」意思是相反地或另一方面。"},{"en":"Some students prefer group work; conversely, others learn better alone.","zh":"有些學生喜歡小組活動；相反地，另一些獨自學習更好。"},{"en":"If one factor is said to reduce risk, conversely another may be said to increase it.","zh":"如果一個因素被說成降低風險，相反地，另一因素可能被說成增加風險。"},{"en":"The word introduces a contrast.","zh":"這個詞引入對比。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":15},{"front":"an extra male Y chromosome","meaning":"額外的男性 Y 染色體","examples":[{"en":"An extra male Y chromosome was linked with aggression.","zh":"額外的男性 Y 染色體被與攻擊性聯繫起來。"},{"en":"An extra male Y chromosome means having an additional Y chromosome beyond the usual male XY pattern.","zh":"「an extra male Y chromosome」意思是在通常男性 XY 模式之外多一條 Y 染色體。"},{"en":"Genetic researchers may describe this chromosome pattern as XYY.","zh":"遺傳研究人員可能把這種染色體模式描述為 XYY。"},{"en":"If an extra chromosome is linked with behaviour, the link must be tested carefully.","zh":"如果額外染色體被與行為聯繫起來，該關聯必須仔細測試。"},{"en":"The phrase describes a genetic variation.","zh":"這個短語描述一種遺傳變異。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":15},{"front":"masculine and aggressive","meaning":"男性化而具攻擊性的","examples":[{"en":"The theory claimed that an extra Y chromosome made men more masculine and aggressive.","zh":"該理論聲稱額外 Y 染色體令男性更男性化而具攻擊性。"},{"en":"Masculine and aggressive means showing traits traditionally linked with men and with forceful or hostile behaviour.","zh":"「masculine and aggressive」指顯示傳統上與男性相關、並帶強硬或敵意行為的特質。"},{"en":"A film character may be written as masculine and aggressive to appear threatening.","zh":"電影角色可能被寫成男性化而具攻擊性，以顯得有威脅。"},{"en":"If science uses stereotypes of masculinity, conclusions can become biased.","zh":"如果科學使用男性氣質的刻板印象，結論可能變得有偏見。"},{"en":"The phrase reflects the theory’s assumptions about gender and behaviour.","zh":"這個短語反映該理論對性別和行為的假設。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":15},{"front":"somewhat weak hypothesis","meaning":"頗薄弱的假說","examples":[{"en":"This somewhat weak hypothesis was severely undermined.","zh":"這個頗薄弱的假說被嚴重削弱。"},{"en":"A somewhat weak hypothesis is an explanation that has limited support or clear problems.","zh":"「somewhat weak hypothesis」是支持有限或有明顯問題的解釋。"},{"en":"A student’s hypothesis is weak if it is based only on one observation.","zh":"如果學生的假說只基於一次觀察，它就是薄弱的。"},{"en":"If later evidence contradicts a weak hypothesis, it may collapse quickly.","zh":"如果後來證據與薄弱假說矛盾，它可能很快崩潰。"},{"en":"The phrase gives cautious criticism.","zh":"這個短語給出謹慎批評。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":15},{"front":"be severely undermined by","meaning":"被……嚴重削弱","examples":[{"en":"The hypothesis was severely undermined by Epps’s 1995 study.","zh":"該假說被 Epps 1995年的研究嚴重削弱。"},{"en":"To be severely undermined by something means to be seriously weakened by it.","zh":"「be severely undermined by」某事，意思是被它嚴重削弱。"},{"en":"A school policy may be undermined by evidence that it harms students.","zh":"如果證據顯示某校政傷害學生，該政策可能被削弱。"},{"en":"If new research undermines a theory, confidence in the theory falls.","zh":"如果新研究削弱理論，人們對該理論的信心會下降。"},{"en":"The phrase describes strong damage to credibility.","zh":"這個短語描述可信度受到嚴重損害。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":15},{"front":"demonstrate that","meaning":"證明","examples":[{"en":"Epps demonstrated that XYY men were no more likely to commit violent crime.","zh":"Epps 證明 XYY 男性並不更可能犯下暴力罪行。"},{"en":"To demonstrate that means to show something clearly with evidence.","zh":"「demonstrate that」意思是用證據清楚顯示某事。"},{"en":"A teacher may demonstrate that revision improves scores by comparing practice results.","zh":"老師可能透過比較練習結果，證明溫習能改善分數。"},{"en":"If a study demonstrates a claim, it provides stronger support than opinion alone.","zh":"如果研究證明某主張，它比單純意見提供更強支持。"},{"en":"The phrase introduces evidence-based proof.","zh":"這個短語引入以證據為基礎的證明。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":15},{"front":"no more likely to","meaning":"並不比……更可能","examples":[{"en":"XYY men were no more likely to commit violent crime than anyone else.","zh":"XYY 男性並不比任何其他人更可能犯下暴力罪行。"},{"en":"No more likely to means not more likely than another person or group.","zh":"「no more likely to」意思是不比另一人或群體更可能。"},{"en":"A careful driver is no more likely to cause an accident than other safe drivers.","zh":"小心駕駛者並不比其他安全司機更可能造成意外。"},{"en":"If one group is no more likely to offend, blaming that group is unfair.","zh":"如果某群體並不更可能犯罪，責怪該群體就是不公平。"},{"en":"The phrase rejects an assumed higher risk.","zh":"這個短語否定被假設的較高風險。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":15},{"front":"commit violent crime","meaning":"犯下暴力罪行","examples":[{"en":"Epps found that XYY men were no more likely to commit violent crime.","zh":"Epps 發現 XYY 男性並不更可能犯下暴力罪行。"},{"en":"To commit violent crime means to carry out a crime involving force or serious threat.","zh":"「commit violent crime」意思是做出涉及武力或嚴重威脅的罪行。"},{"en":"Someone who attacks another person may commit violent crime.","zh":"攻擊他人的人可能犯下暴力罪行。"},{"en":"If research shows a group is not more likely to commit violent crime, stereotypes should be rejected.","zh":"如果研究顯示某群體並不更可能犯下暴力罪行，刻板印象應被拒絕。"},{"en":"The phrase describes serious criminal action.","zh":"這個短語描述嚴重犯罪行動。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":15},{"front":"the further finding that","meaning":"進一步發現……","examples":[{"en":"The further finding that testosterone levels were similar weakened the theory.","zh":"進一步發現睾酮水平相似，削弱了該理論。"},{"en":"The further finding that means an additional research result showing something.","zh":"「the further finding that」意思是顯示某事的額外研究結果。"},{"en":"The further finding that students slept less before exams helped explain lower scores.","zh":"進一步發現學生考試前睡得較少，有助解釋分數較低。"},{"en":"If an extra finding contradicts a theory, it weakens the theory further.","zh":"如果額外發現與理論矛盾，它會進一步削弱該理論。"},{"en":"The phrase introduces additional evidence.","zh":"這個短語引入額外證據。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":15},{"front":"testosterone levels","meaning":"睾酮水平","examples":[{"en":"Testosterone levels among XYY men were no different from those in XY men.","zh":"XYY 男性的睾酮水平與 XY 男性沒有分別。"},{"en":"Testosterone levels are the amount of testosterone hormone in the body.","zh":"「testosterone levels」是身體中睾酮荷爾蒙的數量。"},{"en":"Doctors may test testosterone levels when investigating certain health problems.","zh":"醫生調查某些健康問題時，可能測試睾酮水平。"},{"en":"If testosterone levels are similar, they cannot explain different behaviour in that case.","zh":"如果睾酮水平相似，在該情況下它就不能解釋不同行為。"},{"en":"The phrase refers to a biological measurement.","zh":"這個短語指一項生物測量。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":15},{"front":"no different from","meaning":"與……沒有分別","examples":[{"en":"XYY men were no different from XY men in testosterone levels.","zh":"XYY 男性的睾酮水平與 XY 男性沒有分別。"},{"en":"No different from means the same as or not meaningfully different from.","zh":"「no different from」意思是與某物相同或沒有有意義的差異。"},{"en":"One class’s average score may be no different from another’s.","zh":"一班的平均分可能與另一班沒有分別。"},{"en":"If two groups are no different in a key factor, that factor cannot explain a difference.","zh":"如果兩個群體在關鍵因素上沒有分別，該因素就不能解釋差異。"},{"en":"The phrase rejects a supposed difference.","zh":"這個短語否定所謂差異。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":16},{"front":"the former and the latter","meaning":"前者與後者","examples":[{"en":"The former were no more aggressive than the latter.","zh":"前者並不比後者更具攻擊性。"},{"en":"The former and the latter refer to the first and second things mentioned.","zh":"「the former and the latter」指前面提到的第一項和第二項。"},{"en":"If we compare buses and trains, the former means buses and the latter means trains.","zh":"如果我們比較巴士和火車，前者指巴士，後者指火車。"},{"en":"Using former and latter avoids repeating long names.","zh":"使用 former 和 latter 可以避免重複長名稱。"},{"en":"The phrase is useful in formal comparison.","zh":"這個短語適合正式比較。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":16},{"front":"sound the final death knell for","meaning":"為……敲響喪鐘","examples":[{"en":"The findings sounded the final death knell for the genotype theory.","zh":"這些發現為基因型理論敲響最後喪鐘。"},{"en":"To sound the final death knell for something means to mark its final failure or end.","zh":"「sound the final death knell for」某事，意思是標誌它最終失敗或終結。"},{"en":"A failed safety test may sound the death knell for a new product.","zh":"安全測試失敗可能為新產品敲響喪鐘。"},{"en":"If repeated evidence disproves a theory, the theory may finally be abandoned.","zh":"如果反覆證據推翻某理論，該理論可能最終被放棄。"},{"en":"The phrase is dramatic and means “bring to an end”.","zh":"這個短語較戲劇化，意思是「使其終結」。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":16},{"front":"determined by genotype alone","meaning":"單由基因型決定","examples":[{"en":"The idea of a criminal type determined by genotype alone was rejected.","zh":"犯罪類型單由基因型決定的想法被拒絕。"},{"en":"Determined by genotype alone means caused only by a person’s genetic pattern.","zh":"「determined by genotype alone」意思是只由一個人的基因模式造成。"},{"en":"Height may be influenced by genes, but it is not always determined by genes alone.","zh":"身高可能受基因影響，但不一定只由基因決定。"},{"en":"If behaviour were determined by genotype alone, environment would not matter.","zh":"如果行為單由基因型決定，環境就不重要。"},{"en":"The phrase describes an overly simple genetic explanation.","zh":"這個短語描述過於簡化的基因解釋。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":16},{"front":"place trust in","meaning":"信任；相信","examples":[{"en":"People who place trust in rehabilitation programmes can feel relieved.","zh":"信任更生計劃的人可以鬆一口氣。"},{"en":"To place trust in something means to believe it can help or work.","zh":"「place trust in」某物，意思是相信它能幫助或有效。"},{"en":"Parents place trust in teachers when they send children to school each day.","zh":"家長每天送孩子上學，就是信任老師。"},{"en":"If society trusts rehabilitation, it believes people can change.","zh":"如果社會相信更生，它就是相信人可以改變。"},{"en":"The phrase expresses confidence in a person, system, or idea.","zh":"這個短語表達對人、制度或想法的信心。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":16},{"front":"rehabilitation programmes","meaning":"更生計劃","examples":[{"en":"Rehabilitation programmes aim to reform criminal types.","zh":"更生計劃旨在改造犯罪者。"},{"en":"Rehabilitation programmes are organised efforts to help offenders change and rejoin society.","zh":"「rehabilitation programmes」是幫助罪犯改變並重返社會的有組織措施。"},{"en":"A prison may offer education and counselling as part of rehabilitation programmes.","zh":"監獄可能提供教育和輔導作為更生計劃的一部分。"},{"en":"If rehabilitation works, fewer people may return to crime after release.","zh":"如果更生有效，較少人出獄後再犯罪。"},{"en":"The phrase focuses on reform, not only punishment.","zh":"這個短語集中於改造，而不只是懲罰。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":16},{"front":"reform criminal types","meaning":"改造犯罪者","examples":[{"en":"Some programmes try to reform criminal types.","zh":"有些計劃試圖改造犯罪者。"},{"en":"To reform criminal types means to help offenders change their behaviour and live lawfully.","zh":"「reform criminal types」意思是幫助犯罪者改變行為並守法生活。"},{"en":"Education programmes may reform offenders by giving them job skills and structure.","zh":"教育計劃可能透過提供工作技能和規律來改造罪犯。"},{"en":"If people are seen as changeable, reform becomes possible.","zh":"如果人被視為可以改變，改造就成為可能。"},{"en":"The phrase reflects belief in improvement.","zh":"這個短語反映對改善的信念。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":16},{"front":"breathe a sigh of relief","meaning":"鬆一口氣","examples":[{"en":"Supporters of rehabilitation can now breathe a sigh of relief.","zh":"支持更生的人現在可以鬆一口氣。"},{"en":"To breathe a sigh of relief means to feel less worried after a danger or problem passes.","zh":"「breathe a sigh of relief」意思是在危險或問題過去後感到不再那麼擔心。"},{"en":"A student may breathe a sigh of relief after finding out the exam is postponed.","zh":"學生知道考試延期後可能鬆一口氣。"},{"en":"If a harsh biological theory is rejected, believers in rehabilitation may feel relieved.","zh":"如果嚴苛生物理論被拒絕，相信更生的人可能感到安心。"},{"en":"The phrase describes emotional release after worry.","zh":"這個短語描述憂慮後的情緒釋放。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":16},{"front":"pessimistic prognosis","meaning":"悲觀的預測","examples":[{"en":"The pessimistic prognosis for people with certain body types is no longer accepted.","zh":"對具有某些體型人士的悲觀預測已不再被接受。"},{"en":"A pessimistic prognosis is a negative prediction about someone’s future.","zh":"「pessimistic prognosis」是對某人未來的負面預測。"},{"en":"A doctor may give a pessimistic prognosis if treatment options are limited.","zh":"如果治療選項有限，醫生可能給出悲觀預測。"},{"en":"If body type is no longer seen as destiny, the old prognosis loses force.","zh":"如果體型不再被視為命運，舊有預測就失去力量。"},{"en":"The phrase describes an unfavourable expectation.","zh":"這個短語描述不利的預期。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":16},{"front":"born with a certain physique","meaning":"天生具有某種體格","examples":[{"en":"People born with a certain physique are not doomed to become criminals.","zh":"天生具有某種體格的人並不注定成為罪犯。"},{"en":"Born with a certain physique means having a particular body build from birth or early development.","zh":"「born with a certain physique」意思是從出生或早期發展起具有某種體型。"},{"en":"A child born with a small frame may later become strong through training.","zh":"天生骨架較小的孩子，日後可能透過訓練變強壯。"},{"en":"If physique does not determine behaviour, body shape should not be used to judge morality.","zh":"如果體格不決定行為，就不應用體形判斷道德。"},{"en":"The phrase describes body build, not destiny.","zh":"這個短語描述體格，而不是命運。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":16},{"front":"physique","meaning":"體格","examples":[{"en":"A person’s physique alone does not determine criminal behaviour.","zh":"一個人的體格本身不決定犯罪行為。"},{"en":"Physique means the size, shape, and build of a person’s body.","zh":"「physique」指一個人身體的大小、形狀和體型。"},{"en":"Athletes in different sports often have different physiques.","zh":"不同運動項目的運動員通常有不同體格。"},{"en":"If people judge character by physique, they may make unfair assumptions.","zh":"如果人們按體格判斷性格，他們可能作出不公平假設。"},{"en":"The word describes body form, not personality.","zh":"這個詞描述身體形態，而不是性格。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":16},{"front":"genotype","meaning":"基因型","examples":[{"en":"A person’s genotype alone does not determine criminality.","zh":"一個人的基因型本身不決定犯罪性。"},{"en":"Genotype means a person’s genetic make-up.","zh":"「genotype」指一個人的基因構成。"},{"en":"Biology students study genotype when learning how traits are inherited.","zh":"生物學生學習特徵如何遺傳時會研究基因型。"},{"en":"If genotype is treated as destiny, environment and choice are ignored.","zh":"如果基因型被視為命運，環境和選擇就被忽略。"},{"en":"The phrase refers to genes, not visible appearance.","zh":"這個短語指基因，而不是可見外貌。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":17},{"front":"no longer accepted","meaning":"不再被接受","examples":[{"en":"A purely biological view of criminality is no longer accepted.","zh":"犯罪性的純生物觀點已不再被接受。"},{"en":"No longer accepted means once believed or tolerated, but not believed now.","zh":"「no longer accepted」意思是曾經被相信或容許，但現在不再被相信或接受。"},{"en":"Smoking in classrooms is no longer accepted in modern schools.","zh":"在現代學校，課室吸煙已不再被接受。"},{"en":"If evidence disproves a theory, it may no longer be accepted by scientists.","zh":"如果證據推翻理論，它可能不再被科學家接受。"},{"en":"The phrase marks a change in belief or standards.","zh":"這個短語標示信念或標準的改變。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":17},{"front":"scientific circles","meaning":"科學界","examples":[{"en":"This theory is no longer accepted in scientific circles.","zh":"這個理論在科學界已不再被接受。"},{"en":"Scientific circles means the community of scientists and researchers.","zh":"「scientific circles」指科學家和研究人員的社群。"},{"en":"A theory may be popular online but rejected in scientific circles.","zh":"一個理論可能在網上受歡迎，但在科學界被拒絕。"},{"en":"If scientific circles reject a claim, it usually lacks reliable evidence.","zh":"如果科學界拒絕某主張，它通常缺乏可靠證據。"},{"en":"The phrase refers to expert academic communities.","zh":"這個短語指專家學術社群。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":17},{"front":"biological predisposition","meaning":"生物傾向","examples":[{"en":"Biological predisposition may play a role in criminality.","zh":"生物傾向可能在犯罪性中發揮作用。"},{"en":"Biological predisposition means an inborn tendency that may influence behaviour or risk.","zh":"「biological predisposition」指可能影響行為或風險的天生傾向。"},{"en":"Some people may have a biological predisposition to anxiety, but environment also matters.","zh":"有些人可能有焦慮的生物傾向，但環境也重要。"},{"en":"If predisposition exists, it does not mean the outcome is fixed.","zh":"如果傾向存在，這不代表結果已固定。"},{"en":"The phrase describes tendency, not destiny.","zh":"這個短語描述傾向，而不是命運。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":17},{"front":"play a role in","meaning":"在……中發揮作用","examples":[{"en":"Biological factors may play a role in criminality.","zh":"生物因素可能在犯罪性中發揮作用。"},{"en":"To play a role in something means to contribute to it or affect it.","zh":"「play a role in」某事，意思是對它有貢獻或影響。"},{"en":"Sleep plays a role in memory and concentration.","zh":"睡眠在記憶和專注力中發揮作用。"},{"en":"If biology plays a role in behaviour, social factors may still be important.","zh":"如果生物因素在行為中發揮作用，社會因素仍可能重要。"},{"en":"The phrase describes contribution, not complete control.","zh":"這個短語描述貢獻，而不是完全控制。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":17},{"front":"be tempered substantially by","meaning":"受到……大幅調節","examples":[{"en":"Biological predisposition is tempered substantially by environmental factors.","zh":"生物傾向受到環境因素大幅調節。"},{"en":"To be tempered substantially by something means to be strongly moderated or softened by it.","zh":"「be tempered substantially by」某物，意思是受到它強烈調節或緩和。"},{"en":"A strict rule may be tempered by a teacher’s understanding of a student’s situation.","zh":"嚴格規則可能因老師理解學生情況而被調節。"},{"en":"If biology is tempered by environment, the final behaviour is not fixed by genes alone.","zh":"如果生物因素受環境調節，最終行為就不是單由基因固定。"},{"en":"The phrase shows that one factor reduces or changes another factor’s effect.","zh":"這個短語顯示一個因素減弱或改變另一因素的效果。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":17},{"front":"environmental and social factors","meaning":"環境及社會因素","examples":[{"en":"Criminal behaviour may be shaped by environmental and social factors.","zh":"犯罪行為可能由環境及社會因素塑造。"},{"en":"Environmental and social factors are influences from surroundings, family, school, community, and society.","zh":"「environmental and social factors」是來自周遭、家庭、學校、社區和社會的影響。"},{"en":"A child’s learning may be affected by home conditions and peer support.","zh":"孩子的學習可能受家庭環境和朋輩支援影響。"},{"en":"If crime is shaped by social factors, improving communities may reduce risk.","zh":"如果犯罪受社會因素塑造，改善社區可能降低風險。"},{"en":"The phrase broadens explanation beyond biology.","zh":"這個短語把解釋擴展到生物因素以外。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":17},{"front":"complete the timeline diagram below","meaning":"完成以下時間線圖","examples":[{"en":"Students complete the timeline diagram below using words from the passage.","zh":"學生使用文章中的字詞完成以下時間線圖。"},{"en":"To complete the timeline diagram below means to fill missing information into a time-ordered chart.","zh":"「complete the timeline diagram below」意思是把缺少資料填入按時間排序的圖表。"},{"en":"In history class, students may complete a timeline diagram of major events.","zh":"在歷史課中，學生可能完成重大事件時間線圖。"},{"en":"If a timeline is incomplete, students must find dates and key ideas in the text.","zh":"如果時間線不完整，學生必須在文本中找日期和重點。"},{"en":"The phrase is an exam instruction for organising information by time.","zh":"這個短語是按時間整理資料的考試指示。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":17},{"front":"no more than three words from the passage","meaning":"文章中不多於三個詞","examples":[{"en":"Students should write no more than three words from the passage.","zh":"學生應寫文章中不多於三個詞。"},{"en":"No more than three words from the passage means the answer must use one, two, or three words taken from the text.","zh":"「no more than three words from the passage」意思是答案必須使用文本中的一、二或三個詞。"},{"en":"If the answer is “atavistic features”, it fits the word limit.","zh":"如果答案是 “atavistic features”，它符合字數限制。"},{"en":"If students add four words, the answer may be marked wrong even if the idea is correct.","zh":"如果學生加入四個詞，即使意思正確，答案也可能被判錯。"},{"en":"The phrase sets both a word limit and a source rule.","zh":"這個短語同時設定字數限制和來源規則。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":17},{"front":"be no longer confined to","meaning":"不再局限於……","examples":[{"en":"Criminality was no longer confined to a moral realm.","zh":"犯罪性不再局限於道德範疇。"},{"en":"To be no longer confined to something means to no longer be limited to it.","zh":"「be no longer confined to」某事，意思是不再被限制在其中。"},{"en":"Learning is no longer confined to classrooms because students can study online.","zh":"學習不再局限於課室，因為學生可以網上學習。"},{"en":"If crime study is no longer confined to morality, science and data can enter the discussion.","zh":"如果犯罪研究不再局限於道德，科學和數據就能進入討論。"},{"en":"The phrase describes expansion beyond an old boundary.","zh":"這個短語描述超越舊界限。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":17},{"front":"a moral realm","meaning":"道德範疇","examples":[{"en":"Early discussions of criminality belonged mainly to a moral realm.","zh":"早期關於犯罪性的討論主要屬於道德範疇。"},{"en":"A moral realm is an area of thought concerned with right and wrong.","zh":"「a moral realm」是關乎對與錯的思想領域。"},{"en":"Questions about honesty and fairness belong to a moral realm.","zh":"關於誠實和公平的問題屬於道德範疇。"},{"en":"If crime is discussed only in a moral realm, biological or social evidence may be ignored.","zh":"如果犯罪只在道德範疇中討論，生物或社會證據可能被忽略。"},{"en":"The phrase describes an ethical area of discussion.","zh":"這個短語描述倫理討論領域。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":17},{"front":"biological theory of criminality","meaning":"犯罪性的生物理論","examples":[{"en":"The timeline refers to a biological theory of criminality.","zh":"時間線提到犯罪性的生物理論。"},{"en":"A biological theory of criminality explains crime by using body, genes, hormones, or inherited traits.","zh":"「biological theory of criminality」用身體、基因、荷爾蒙或遺傳特徵解釋犯罪。"},{"en":"A criminology class may compare biological theories with social theories of crime.","zh":"犯罪學課可能比較犯罪的生物理論和社會理論。"},{"en":"If a biological theory ignores environment, it may be too narrow.","zh":"如果生物理論忽略環境，它可能過於狹窄。"},{"en":"The phrase names one type of explanation for crime.","zh":"這個短語指出犯罪解釋的一種類型。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":18},{"front":"presuppose that","meaning":"預先假定","examples":[{"en":"A biological theory presupposes that criminality can be inherited.","zh":"生物理論預先假定犯罪性可以遺傳。"},{"en":"To presuppose that means to assume something before the argument begins.","zh":"「presuppose that」意思是在論證開始前先假定某事。"},{"en":"A school rule presupposes that students know where to find the handbook.","zh":"校規預先假定學生知道在哪裡找到手冊。"},{"en":"If a theory presupposes inherited crime, it may interpret evidence through that assumption.","zh":"如果理論預先假定犯罪會遺傳，它可能透過該假設解讀證據。"},{"en":"The phrase identifies a hidden starting assumption.","zh":"這個短語指出隱藏的起始假設。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":18},{"front":"be claimed to be","meaning":"被聲稱是……","examples":[{"en":"Criminal types were claimed to be physically distinctive.","zh":"犯罪類型被聲稱在身體上具有獨特性。"},{"en":"To be claimed to be something means someone says it is so, but it may not be proven.","zh":"「be claimed to be」某物，意思是有人聲稱它如此，但未必已證明。"},{"en":"A product may be claimed to be healthy even if the evidence is weak.","zh":"產品可能被聲稱是健康的，即使證據薄弱。"},{"en":"If a group is claimed to be different, the claim must be tested carefully.","zh":"如果某群體被聲稱有所不同，該主張必須仔細測試。"},{"en":"The phrase introduces an unsupported or disputed assertion.","zh":"這個短語引入未受支持或具爭議的聲稱。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":18},{"front":"distinctive atavistic features","meaning":"獨特的返祖特徵","examples":[{"en":"Lombroso claimed that criminals had distinctive atavistic features.","zh":"Lombroso 聲稱罪犯有獨特的返祖特徵。"},{"en":"Distinctive atavistic features are noticeable traits supposedly inherited from earlier ancestral forms.","zh":"「distinctive atavistic features」是據稱來自早期祖先形態的顯眼特徵。"},{"en":"Old theories sometimes treated unusual facial features as signs of character.","zh":"舊理論有時把不尋常面部特徵視為性格跡象。"},{"en":"If such features are used to judge crime, the result is biased and unreliable.","zh":"如果這些特徵被用來判斷犯罪，結果就是有偏見且不可靠。"},{"en":"The phrase summarises Lombroso’s flawed physical theory.","zh":"這個短語概括 Lombroso 有缺陷的身體理論。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":18},{"front":"particular dispositions","meaning":"特定傾向","examples":[{"en":"Body types were linked with particular dispositions.","zh":"體型被與特定傾向聯繫起來。"},{"en":"Particular dispositions are specific tendencies in behaviour, personality, or mood.","zh":"「particular dispositions」是行為、性格或情緒上的特定傾向。"},{"en":"A child may have a disposition toward curiosity or caution.","zh":"孩子可能有好奇或謹慎的傾向。"},{"en":"If body type is linked with disposition without strong evidence, the link may be misleading.","zh":"如果體型在缺乏強力證據下與傾向聯繫起來，該關聯可能誤導。"},{"en":"The phrase refers to tendencies, not fixed actions.","zh":"這個短語指傾向，而不是固定行動。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":18},{"front":"be considered to have","meaning":"被認為具有……","examples":[{"en":"Mesomorphs were considered to have criminal tendencies.","zh":"中胚型體型的人被認為具有犯罪傾向。"},{"en":"To be considered to have something means to be thought or judged to possess it.","zh":"「be considered to have」某物，意思是被認為或判斷擁有它。"},{"en":"A student may be considered to have leadership potential after organising a class event.","zh":"學生組織班級活動後，可能被認為具有領導潛力。"},{"en":"If people are considered to have a trait without evidence, the judgement may be unfair.","zh":"如果人們在沒有證據下被認為具有某特質，判斷可能不公平。"},{"en":"The phrase describes how others view someone or a group.","zh":"這個短語描述他人如何看待某人或某群體。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":18},{"front":"be implicated in","meaning":"被牽涉在……之中","examples":[{"en":"Genetics was implicated in a biological disposition towards criminality.","zh":"遺傳學被牽涉在對犯罪性的生物傾向之中。"},{"en":"To be implicated in something means to be involved in or connected with it, often as a cause.","zh":"「be implicated in」某事，意思是被牽涉或連接其中，常作為原因之一。"},{"en":"Poor lighting may be implicated in a road accident.","zh":"照明不足可能被牽涉在道路意外之中。"},{"en":"If genetics is implicated in behaviour, researchers must still examine environment.","zh":"如果遺傳被牽涉在行為中，研究人員仍必須考察環境。"},{"en":"The phrase suggests involvement, not complete proof.","zh":"這個短語暗示涉及，而不是完全證明。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":18},{"front":"an additional Y chromosome","meaning":"額外的 Y 染色體","examples":[{"en":"An additional Y chromosome was once associated with aggression.","zh":"額外的 Y 染色體曾經被與攻擊性聯繫起來。"},{"en":"An additional Y chromosome means one extra Y chromosome beyond the usual male pattern.","zh":"「an additional Y chromosome」意思是在通常男性模式之外多一條 Y 染色體。"},{"en":"The XYY pattern includes an additional Y chromosome.","zh":"XYY 模式包括額外的 Y 染色體。"},{"en":"If an additional chromosome is linked with behaviour, evidence must show the link clearly.","zh":"如果額外染色體被與行為聯繫起來，證據必須清楚顯示該關聯。"},{"en":"The phrase describes a chromosome variation.","zh":"這個短語描述染色體變異。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":18},{"front":"proposed link between","meaning":"……之間所提出的關聯","examples":[{"en":"The proposed link between criminality and genotype was later challenged.","zh":"犯罪性與基因型之間所提出的關聯後來受到挑戰。"},{"en":"A proposed link between two things is a suggested connection that may or may not be true.","zh":"「proposed link between」兩件事，是被提出但未必真確的關係。"},{"en":"A proposed link between screen time and poor sleep should be tested with data.","zh":"屏幕時間與睡眠差之間所提出的關聯應用數據測試。"},{"en":"If later studies challenge a proposed link, the original claim becomes weaker.","zh":"如果後來研究挑戰所提出的關聯，原本主張就變弱。"},{"en":"The phrase describes a suggested relationship.","zh":"這個短語描述被提出的關係。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":18},{"front":"a purely biological basis for","meaning":"……的純生物基礎","examples":[{"en":"A purely biological basis for criminality is now discredited.","zh":"犯罪性的純生物基礎現在已失去可信性。"},{"en":"A purely biological basis for something means explaining it only through biology.","zh":"「a purely biological basis for」某事，意思是只透過生物學解釋它。"},{"en":"A purely biological basis for school failure would ignore teaching, family, and poverty.","zh":"對學業失敗的純生物基礎解釋會忽略教學、家庭和貧窮。"},{"en":"If behaviour has many causes, a purely biological explanation is too narrow.","zh":"如果行為有多種成因，純生物解釋就太狹窄。"},{"en":"The phrase contrasts with explanations that include social factors.","zh":"這個短語與包括社會因素的解釋形成對比。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":18},{"front":"be discredited","meaning":"被否定；失去可信性","examples":[{"en":"The theory of inherited criminality has been discredited.","zh":"遺傳性犯罪傾向理論已被否定。"},{"en":"To be discredited means to lose trust because evidence shows a claim is weak or false.","zh":"「be discredited」意思是因證據顯示主張薄弱或錯誤而失去信任。"},{"en":"A rumour is discredited when video evidence proves it wrong.","zh":"當影片證據證明謠言錯誤，該謠言就失去可信性。"},{"en":"If a theory is discredited, it should not be taught as reliable science.","zh":"如果理論已被否定，就不應被當作可靠科學教授。"},{"en":"The phrase describes loss of credibility.","zh":"這個短語描述可信度喪失。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":18},{"front":"genetic factors","meaning":"遺傳因素","examples":[{"en":"Genetic factors may be moderated by the environment.","zh":"遺傳因素可能受到環境調節。"},{"en":"Genetic factors are influences that come from a person’s genes.","zh":"「genetic factors」是來自一個人基因的影響。"},{"en":"Genetic factors may affect height, health risks, or some personality tendencies.","zh":"遺傳因素可能影響身高、健康風險或某些性格傾向。"},{"en":"If genetic factors interact with environment, outcomes are not fixed by genes alone.","zh":"如果遺傳因素與環境互動，結果就不是單由基因固定。"},{"en":"The phrase refers to inherited biological influences.","zh":"這個短語指遺傳的生物影響。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":19},{"front":"be moderated by","meaning":"受到……調節","examples":[{"en":"Genetic factors may be moderated by social elements.","zh":"遺傳因素可能受到社會元素調節。"},{"en":"To be moderated by something means to have its effect reduced, changed, or controlled by it.","zh":"「be moderated by」某物，意思是其效果被它減弱、改變或控制。"},{"en":"A student’s stress may be moderated by strong family support.","zh":"學生壓力可能受到強大家庭支援調節。"},{"en":"If biology is moderated by environment, behaviour can change under different conditions.","zh":"如果生物因素受到環境調節，行為可以在不同條件下改變。"},{"en":"The phrase shows that one factor shapes another factor’s effect.","zh":"這個短語顯示一個因素塑造另一因素的效果。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":19},{"front":"choose two letters","meaning":"選擇兩個字母","examples":[{"en":"Students choose two letters from the options.","zh":"學生從選項中選擇兩個字母。"},{"en":"Choose two letters means select exactly two answer options.","zh":"「choose two letters」意思是準確選出兩個答案選項。"},{"en":"In a reading test, students may choose two letters that match the writer’s views.","zh":"在閱讀測驗中，學生可能選擇兩個符合作者觀點的字母。"},{"en":"If the instruction says choose two, choosing three may lose marks.","zh":"如果指示說選兩個，選三個可能失分。"},{"en":"The phrase is an exam instruction about answer number.","zh":"這個短語是關於答案數量的考試指示。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":19},{"front":"overwhelming evidence","meaning":"壓倒性的證據","examples":[{"en":"There is no overwhelming evidence in support of a purely biological theory.","zh":"沒有壓倒性的證據支持純生物理論。"},{"en":"Overwhelming evidence means evidence that is very strong and difficult to doubt.","zh":"「overwhelming evidence」是非常強、難以懷疑的證據。"},{"en":"Video recordings and multiple witnesses can provide overwhelming evidence in a case.","zh":"影片記錄和多名證人可以在案件中提供壓倒性證據。"},{"en":"If there is no overwhelming evidence, claims should be made cautiously.","zh":"如果沒有壓倒性證據，主張就應謹慎提出。"},{"en":"The phrase describes very powerful proof.","zh":"這個短語描述非常有力的證明。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":19},{"front":"in support of","meaning":"支持……","examples":[{"en":"Some evidence may exist in support of Sheldon’s theory.","zh":"可能有一些證據支持 Sheldon 的理論。"},{"en":"In support of means helping to prove, defend, or strengthen an idea.","zh":"「in support of」意思是幫助證明、辯護或加強某想法。"},{"en":"A student may use statistics in support of an argument about school lunches.","zh":"學生可能使用統計數字支持關於學校午餐的論點。"},{"en":"If evidence is only partial, it supports a claim but does not prove it fully.","zh":"如果證據只是部分的，它支持主張但不能完全證明。"},{"en":"The phrase introduces supporting evidence.","zh":"這個短語引入支持證據。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":19},{"front":"biological predisposition towards crime","meaning":"對犯罪的生物傾向","examples":[{"en":"The question discusses a biological predisposition towards crime.","zh":"問題討論對犯罪的生物傾向。"},{"en":"A biological predisposition towards crime is a supposed inborn tendency toward criminal behaviour.","zh":"「biological predisposition towards crime」是所謂天生傾向於犯罪行為。"},{"en":"Old criminology theories often looked for biological causes of crime.","zh":"舊犯罪學理論常尋找犯罪的生物原因。"},{"en":"If predisposition is treated as destiny, rehabilitation and environment may be ignored.","zh":"如果傾向被視為命運，更生和環境可能被忽略。"},{"en":"The phrase describes a controversial idea about crime.","zh":"這個短語描述關於犯罪的具爭議想法。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":19},{"front":"experimental work","meaning":"實驗研究","examples":[{"en":"Lombroso’s experimental work had serious weaknesses.","zh":"Lombroso 的實驗研究有嚴重弱點。"},{"en":"Experimental work is research based on experiments or systematic observation.","zh":"「experimental work」是基於實驗或系統觀察的研究。"},{"en":"A science project’s experimental work may involve measuring plant growth every day.","zh":"科學專題的實驗研究可能包括每天測量植物生長。"},{"en":"If experimental work lacks control groups, its results may be unreliable.","zh":"如果實驗研究缺乏對照組，其結果可能不可靠。"},{"en":"The phrase refers to the practical research done to test ideas.","zh":"這個短語指用來測試想法的實際研究。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":19},{"front":"completely discredited","meaning":"被完全否定","examples":[{"en":"Some theories have been completely discredited by later research.","zh":"有些理論已被後來研究完全否定。"},{"en":"Completely discredited means fully shown to be unreliable or false.","zh":"「completely discredited」意思是被完全證明不可靠或錯誤。"},{"en":"A cheating accusation may be completely discredited if clear camera evidence proves innocence.","zh":"如果清楚攝影證據證明清白，作弊指控可能被完全否定。"},{"en":"If a theory is completely discredited, it should not guide policy.","zh":"如果理論被完全否定，它不應指導政策。"},{"en":"The phrase describes total loss of credibility.","zh":"這個短語描述可信性完全喪失。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":19},{"front":"modern scientists","meaning":"現代科學家","examples":[{"en":"Modern scientists reject simple biological explanations of criminality.","zh":"現代科學家拒絕對犯罪性的簡單生物解釋。"},{"en":"Modern scientists are researchers working with current scientific methods and evidence.","zh":"「modern scientists」是使用當前科學方法和證據的研究人員。"},{"en":"Modern scientists test claims with data, controls, and peer review.","zh":"現代科學家用數據、對照和同行評審測試主張。"},{"en":"If modern scientists reject a theory, it usually lacks reliable support.","zh":"如果現代科學家拒絕某理論，它通常缺乏可靠支持。"},{"en":"The phrase refers to present-day scientific experts.","zh":"這個短語指當代科學專家。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":19},{"front":"hinder rather than help","meaning":"阻礙而非幫助","examples":[{"en":"The option asks whether Lombroso hindered rather than helped criminology.","zh":"該選項問 Lombroso 是否阻礙而非幫助犯罪學。"},{"en":"Hinder rather than help means make progress harder instead of supporting it.","zh":"「hinder rather than help」意思是令進展更困難，而不是提供支持。"},{"en":"Too many rules may hinder rather than help students’ learning.","zh":"太多規則可能阻礙而非幫助學生學習。"},{"en":"If a theory spreads prejudice, it may hinder rather than help a field.","zh":"如果理論散播偏見，它可能阻礙而非幫助一個領域。"},{"en":"The phrase creates a clear contrast between harm and support.","zh":"這個短語在傷害和支持之間建立清楚對比。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":19},{"front":"the advance of criminology","meaning":"犯罪學的發展","examples":[{"en":"Lombroso influenced the advance of criminology.","zh":"Lombroso 影響了犯罪學的發展。"},{"en":"The advance of criminology means the development and progress of crime study.","zh":"「the advance of criminology」指犯罪研究的發展和進步。"},{"en":"Better data collection can support the advance of criminology.","zh":"更好的數據收集可以支持犯罪學的發展。"},{"en":"If a researcher changes methods in a field, he may influence its advance.","zh":"如果研究者改變一個領域的方法，他可能影響其發展。"},{"en":"The phrase describes progress in criminology as a discipline.","zh":"這個短語描述犯罪學作為學科的進步。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":19},{"front":"shift away from","meaning":"從……轉移","examples":[{"en":"There has been a shift away from purely biological explanations.","zh":"已經出現從純生物解釋轉移的趨勢。"},{"en":"To shift away from something means to move gradually away from it.","zh":"「shift away from」某事，意思是逐漸遠離它。"},{"en":"Schools may shift away from memorisation toward problem-solving.","zh":"學校可能從背誦轉向解難。"},{"en":"If criminology shifts away from biology alone, social context becomes more important.","zh":"如果犯罪學從單純生物因素轉移，社會背景就變得更重要。"},{"en":"The phrase describes a change in focus.","zh":"這個短語描述焦點改變。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":20},{"front":"the emphasis on biological factors","meaning":"對生物因素的重視","examples":[{"en":"Modern theories reduce the emphasis on biological factors alone.","zh":"現代理論減少只對生物因素的重視。"},{"en":"The emphasis on biological factors means the importance given to genes, body, hormones, or brain factors.","zh":"「the emphasis on biological factors」指對基因、身體、荷爾蒙或腦部因素給予的重要性。"},{"en":"A health lesson may place emphasis on both exercise and diet, not one factor only.","zh":"健康課可能同時重視運動和飲食，而不是只重視一個因素。"},{"en":"If the emphasis on biology is too strong, social causes may be overlooked.","zh":"如果對生物因素的重視太強，社會原因可能被忽略。"},{"en":"The phrase describes what an explanation focuses on.","zh":"這個短語描述解釋所集中之處。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":20},{"front":"basis of criminality","meaning":"犯罪性的基礎","examples":[{"en":"The passage evaluates different theories about the basis of criminality.","zh":"文章評估不同關於犯罪性基礎的理論。"},{"en":"The basis of criminality means the underlying cause or foundation of criminal behaviour.","zh":"「basis of criminality」指犯罪行為的深層原因或基礎。"},{"en":"A criminology essay may compare poverty, family background, and biology as possible bases of crime.","zh":"犯罪學文章可能比較貧窮、家庭背景和生物因素作為犯罪可能基礎。"},{"en":"If the basis of criminality is complex, one simple explanation is not enough.","zh":"如果犯罪性基礎很複雜，一個簡單解釋就不足夠。"},{"en":"The phrase asks what crime is rooted in.","zh":"這個短語詢問犯罪根源是甚麼。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":20},{"front":"partially support","meaning":"部分支持","examples":[{"en":"Biological evidence may partially support Sheldon’s theory.","zh":"生物證據可能部分支持 Sheldon 的理論。"},{"en":"To partially support something means to support it in some ways but not completely.","zh":"「partially support」某事，意思是在某些方面支持它，但不是完全支持。"},{"en":"A survey may partially support a new school rule if only some students benefit.","zh":"如果只有部分學生受益，調查可能只是部分支持新校規。"},{"en":"If evidence partially supports a theory, the theory still needs caution and limits.","zh":"如果證據部分支持理論，該理論仍需要謹慎和限制。"},{"en":"The phrase signals incomplete support.","zh":"這個短語表示支持不完整。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":20},{"front":"theory of somatotypes","meaning":"體型分類理論","examples":[{"en":"The theory of somatotypes links body shape with personality and behaviour.","zh":"體型分類理論把體形與性格和行為聯繫起來。"},{"en":"The theory of somatotypes is Sheldon’s theory that body types correspond to personality types.","zh":"「theory of somatotypes」是 Sheldon 認為體型對應性格類型的理論。"},{"en":"Psychology students may study this theory as an example of biological explanations of behaviour.","zh":"心理學學生可能把這個理論作為行為生物解釋的例子來研究。"},{"en":"If a theory links body shape and crime, it must avoid confusing correlation with cause.","zh":"如果理論把體形和犯罪聯繫起來，它必須避免混淆相關與因果。"},{"en":"The phrase names an influential but controversial body-type theory.","zh":"這個短語指出一個有影響但具爭議的體型理論。"}],"source":"67 - Physiology and Criminality.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 68":[{"front":"be born in","meaning":"出生於","examples":[{"en":"Hugh O’Flaherty was born in Kiskeam, in North Cork.","zh":"Hugh O’Flaherty 出生於北科克的 Kiskeam。"},{"en":"To be born in a place means to come into the world there.","zh":"“Be born in” 某地指在該地出生。"},{"en":"A child born in Hong Kong may later study or work in another country.","zh":"出生於香港的孩子日後可能到另一個國家讀書或工作。"},{"en":"Where someone is born can shape their early identity and family story.","zh":"一個人的出生地可以塑造其早期身份和家庭故事。"},{"en":"The phrase is used when giving basic biographical information.","zh":"這個短語用於提供基本生平資料。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":1},{"front":"native North Cork","meaning":"母親的家鄉北科克","examples":[{"en":"O’Flaherty was born in his mother’s native area of North Cork.","zh":"O’Flaherty 出生於他母親的家鄉北科克。"},{"en":"A native area is the place where someone or their family originally comes from.","zh":"Native area 指某人或其家庭原本來自的地方。"},{"en":"A person may return to their mother’s native village during school holidays.","zh":"一個人可能在學校假期回到母親的家鄉村莊。"},{"en":"If a place is described as someone’s native area, it has family or personal roots.","zh":"如果某地被形容為某人的家鄉地區，它就有家庭或個人根源。"},{"en":"The phrase connects geography with origin and belonging.","zh":"這個短語把地理位置與出身和歸屬感連繫起來。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":1},{"front":"be brought up in","meaning":"在……長大","examples":[{"en":"Hugh O’Flaherty was brought up in Killarney.","zh":"Hugh O’Flaherty 在 Killarney 長大。"},{"en":"To be brought up in a place means to grow up there as a child.","zh":"“Be brought up in” 某地指童年在該地成長。"},{"en":"A student brought up in a small town may know many neighbours well.","zh":"在小鎮長大的學生可能很熟悉許多鄰居。"},{"en":"The place where someone is brought up can influence their values and habits.","zh":"一個人成長的地方可以影響其價值觀和習慣。"},{"en":"The phrase focuses on childhood upbringing, not only birthplace.","zh":"這個短語強調童年成長環境，而不只是出生地。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":1},{"front":"the steward of","meaning":"……的管理員","examples":[{"en":"His father was the steward of a local golf club.","zh":"他的父親是本地高爾夫球會的管理員。"},{"en":"A steward is someone who manages or looks after a place, service, or organisation.","zh":"Steward 指管理或照看某地方、服務或組織的人。"},{"en":"The steward of a club may deal with members, facilities, and daily arrangements.","zh":"球會管理員可能處理會員、設施和日常安排。"},{"en":"If a steward works well, visitors and members experience smoother service.","zh":"如果管理員工作良好，訪客和會員會得到更順暢的服務。"},{"en":"The phrase describes a practical management role.","zh":"這個短語描述實際管理角色。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":1},{"front":"a local golf club","meaning":"本地高爾夫球會","examples":[{"en":"O’Flaherty’s father worked at a local golf club.","zh":"O’Flaherty 的父親在本地高爾夫球會工作。"},{"en":"A local golf club is a nearby place where members play golf and socialise.","zh":"本地高爾夫球會是附近讓會員打高爾夫球和社交的地方。"},{"en":"A family may know many people through a local sports club.","zh":"一個家庭可能透過本地體育會認識許多人。"},{"en":"If someone grows up around a golf club, they may learn the game early.","zh":"如果某人在高爾夫球會附近長大，可能很早就學會這項運動。"},{"en":"The phrase gives a simple community setting.","zh":"這個短語提供簡單的社區背景。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":1},{"front":"the eldest of four children","meaning":"四名子女中的長子","examples":[{"en":"O’Flaherty was the eldest of four children.","zh":"O’Flaherty 是四名子女中的長子。"},{"en":"The eldest of four children means the oldest child among four siblings.","zh":"“The eldest of four children” 指四名兄弟姊妹中年紀最大的孩子。"},{"en":"The eldest child in a family may often help look after younger brothers and sisters.","zh":"家中長子或長女可能經常幫忙照顧弟妹。"},{"en":"Being the eldest can bring responsibility early in life.","zh":"作為最年長的孩子，可能很早就承擔責任。"},{"en":"The phrase describes birth order within a family.","zh":"這個短語描述家庭中的出生排行。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":1},{"front":"from an early age","meaning":"從小；自幼","examples":[{"en":"From an early age, he appeared to have a vocation for the priesthood.","zh":"從小，他看來就有投身神職的聖召。"},{"en":"From an early age means since childhood or when someone was still young.","zh":"“From an early age” 指自童年或年紀還小時開始。"},{"en":"From an early age, some children show strong interest in music, science, or sport.","zh":"從小，有些孩子就對音樂、科學或運動表現出強烈興趣。"},{"en":"If a habit begins from an early age, it may become part of a person’s identity.","zh":"如果一個習慣從小開始，它可能成為個人身份的一部分。"},{"en":"The phrase highlights that something started very early.","zh":"這個短語強調某事很早就開始。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":1},{"front":"appear to have","meaning":"看來有……","examples":[{"en":"O’Flaherty appeared to have a vocation for the priesthood.","zh":"O’Flaherty 看來有投身神職的聖召。"},{"en":"To appear to have something means to seem to possess it, based on signs or behaviour.","zh":"“Appear to have” 某物指根據跡象或行為，看似擁有它。"},{"en":"A student may appear to have leadership ability when classmates naturally follow their ideas.","zh":"當同學自然跟隨某學生的想法時，他可能看來有領導能力。"},{"en":"If someone appears to have a strong calling, others may encourage them to pursue it.","zh":"如果某人看來有強烈召命，其他人可能鼓勵他追求它。"},{"en":"The phrase suggests a careful judgement, not absolute proof.","zh":"這個短語暗示謹慎判斷，而不是絕對證明。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":1},{"front":"a vocation for the priesthood","meaning":"投身神職的聖召","examples":[{"en":"He appeared to have a vocation for the priesthood from an early age.","zh":"他從小看來就有投身神職的聖召。"},{"en":"A vocation for the priesthood is a strong sense of calling to become a priest.","zh":"投身神職的聖召是成為神父的強烈召命感。"},{"en":"A young person with this vocation may spend much time in church and religious study.","zh":"有這種聖召的年輕人可能花許多時間在教會和宗教學習上。"},{"en":"If someone feels called to religious service, they may apply to a seminary.","zh":"如果某人感到被召喚去服務宗教，可能申請進入修院。"},{"en":"The phrase describes a deep spiritual calling, not only a career choice.","zh":"這個短語描述深層精神召命，而不只是職業選擇。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":1},{"front":"fondness for","meaning":"對……的喜愛","examples":[{"en":"His fondness for the church was formed during his education.","zh":"他對教會的喜愛是在求學期間形成的。"},{"en":"Fondness for something means a warm liking or affection for it.","zh":"“Fondness for” 某事指對它有溫暖的喜歡或感情。"},{"en":"A child may develop a fondness for reading after a teacher introduces exciting books.","zh":"老師介紹有趣書籍後，孩子可能對閱讀產生喜愛。"},{"en":"If fondness grows over time, it can influence later choices.","zh":"如果喜愛隨時間增長，它可以影響後來選擇。"},{"en":"The phrase describes emotional attachment rather than formal duty.","zh":"這個短語描述情感依附，而不是正式責任。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":1},{"front":"be formed in part","meaning":"部分形成於","examples":[{"en":"His fondness for the church was formed in part during his education.","zh":"他對教會的喜愛部分形成於他的求學期間。"},{"en":"To be formed in part means to be partly shaped or developed by something.","zh":"“Be formed in part” 指部分受到某事塑造或發展。"},{"en":"A student’s confidence may be formed in part by supportive teachers.","zh":"學生的信心可能部分形成於支持性的老師。"},{"en":"If an interest is formed in part at school, education has influenced personal development.","zh":"如果興趣部分形成於學校，教育就影響了個人發展。"},{"en":"The phrase shows that one factor helped create something, but was not the only cause.","zh":"這個短語顯示一個因素幫助形成某事，但不是唯一原因。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":1},{"front":"during his education","meaning":"在求學期間","examples":[{"en":"His religious interests developed during his education.","zh":"他的宗教興趣在求學期間發展。"},{"en":"During his education means while he was studying or being taught.","zh":"“During his education” 指他學習或接受教導的時期。"},{"en":"During her education, a student may discover an interest in medicine or law.","zh":"在求學期間，學生可能發現自己對醫學或法律有興趣。"},{"en":"What happens during education can shape a person’s future work and beliefs.","zh":"求學期間發生的事情可以塑造一個人的未來工作和信念。"},{"en":"The phrase refers to the period of formal learning.","zh":"這個短語指正式學習時期。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":2},{"front":"Presentation Brothers’ School","meaning":"Presentation Brothers’ School（校名）","examples":[{"en":"He began his education at Presentation Brothers’ School.","zh":"他在 Presentation Brothers’ School 開始接受教育。"},{"en":"Presentation Brothers’ School is the name of the school where he first studied.","zh":"Presentation Brothers’ School 是他最初就讀學校的名稱。"},{"en":"A biography often names a person’s school to show their early background.","zh":"傳記常會列出一個人的學校，以顯示其早期背景。"},{"en":"If someone begins education at a religious school, that may influence later spiritual interests.","zh":"如果某人在宗教學校開始求學，這可能影響日後的宗教興趣。"},{"en":"The phrase should be treated as a proper school name.","zh":"這個短語應視為正式校名。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":2},{"front":"local monastery","meaning":"本地修道院","examples":[{"en":"His education began at a local monastery in his home town.","zh":"他的教育始於家鄉的一所本地修道院。"},{"en":"A local monastery is a nearby religious community where monks live, pray, and sometimes teach.","zh":"本地修道院是附近讓修士生活、祈禱，有時也教學的宗教團體。"},{"en":"A child educated at a monastery may become familiar with religious discipline and daily worship.","zh":"在修道院受教育的孩子可能熟悉宗教紀律和日常崇拜。"},{"en":"If a monastery provides schooling, religion and education may be closely linked.","zh":"如果修道院提供教育，宗教和學習可能緊密相連。"},{"en":"The phrase describes both a place and a religious environment.","zh":"這個短語同時描述地方和宗教環境。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":2},{"front":"home town","meaning":"家鄉","examples":[{"en":"He studied at a monastery in his home town.","zh":"他在家鄉的一所修道院學習。"},{"en":"A home town is the town where someone grew up or feels they belong.","zh":"家鄉是某人成長或感到歸屬的城鎮。"},{"en":"People may return to their home town for family events or festivals.","zh":"人們可能為家庭活動或節日返回家鄉。"},{"en":"If someone studies in their home town, their early education stays close to family life.","zh":"如果某人在家鄉求學，其早期教育就與家庭生活接近。"},{"en":"The phrase connects a place with personal roots.","zh":"這個短語把地方與個人根源連繫起來。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":2},{"front":"later attended","meaning":"後來就讀於","examples":[{"en":"He later attended Waterford College.","zh":"他後來就讀於 Waterford College。"},{"en":"Later attended means studied at or went to a school after an earlier stage.","zh":"“Later attended” 指在較早階段之後，到某學校就讀。"},{"en":"A student may first attend a local primary school and later attend a boarding school.","zh":"學生可能先就讀本地小學，後來就讀寄宿學校。"},{"en":"If someone later attends another college, their education has moved to a new stage.","zh":"如果某人後來就讀另一所學院，其教育就進入新階段。"},{"en":"The phrase helps show the order of educational history.","zh":"這個短語幫助顯示教育經歷的次序。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":2},{"front":"the priesthood","meaning":"神職；司鐸職分","examples":[{"en":"The priesthood was always going to be his calling.","zh":"神職一直會是他的召命。"},{"en":"The priesthood is the role, life, and office of being a priest.","zh":"神職是成為神父的角色、生活和職分。"},{"en":"A person entering the priesthood usually receives religious training and ordination.","zh":"進入神職的人通常接受宗教訓練和祝聖。"},{"en":"If someone chooses the priesthood, their life is shaped by religious service.","zh":"如果某人選擇神職，其人生會受宗教服務塑造。"},{"en":"The phrase refers to a religious vocation, not an ordinary job.","zh":"這個短語指宗教召命，而不是普通工作。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":2},{"front":"his calling","meaning":"他的召命；他的天職","examples":[{"en":"The priesthood was always going to be his calling.","zh":"神職一直會是他的召命。"},{"en":"Someone’s calling is the work or life path they feel deeply meant to follow.","zh":"某人的召命是他深深感到自己應走的工作或人生道路。"},{"en":"A teacher may feel that helping children learn is her calling.","zh":"老師可能覺得幫助孩子學習是她的天職。"},{"en":"If a person discovers their calling early, they may commit to it for life.","zh":"如果一個人早早發現自己的召命，可能終生投入其中。"},{"en":"The phrase suggests purpose and inner conviction.","zh":"這個短語暗示使命感和內在信念。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":2},{"front":"apply to","meaning":"申請入讀","examples":[{"en":"He applied to Mungret College in Limerick.","zh":"他申請入讀 Limerick 的 Mungret College。"},{"en":"To apply to a school or programme means to formally ask to be accepted.","zh":"“Apply to” 學校或課程指正式申請被取錄。"},{"en":"A student may apply to a university after preparing grades, references, and a personal statement.","zh":"學生可能在準備成績、推薦信和個人陳述後申請入讀大學。"},{"en":"If someone applies to a seminary, they are seeking entry into religious training.","zh":"如果某人申請入讀修院，就是尋求進入宗教訓練。"},{"en":"The phrase describes a formal request for admission.","zh":"這個短語描述正式入學申請。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":2},{"front":"be accepted into","meaning":"被取錄進入","examples":[{"en":"He was accepted into the seminary at Mungret College.","zh":"他被取錄進入 Mungret College 的修院。"},{"en":"To be accepted into a place or programme means to be officially allowed to join it.","zh":"“Be accepted into” 某地方或課程指被正式允許加入。"},{"en":"A student accepted into medical school has passed the admissions process.","zh":"被取錄進入醫學院的學生已通過收生程序。"},{"en":"If someone is accepted into a seminary, their religious training can begin.","zh":"如果某人被取錄進入修院，其宗教訓練就可以開始。"},{"en":"The phrase marks successful admission.","zh":"這個短語標示成功入學。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":2},{"front":"the seminary","meaning":"神學院；修院","examples":[{"en":"O’Flaherty was accepted into the seminary in Limerick.","zh":"O’Flaherty 被取錄進入 Limerick 的修院。"},{"en":"A seminary is a school where people train to become priests or religious leaders.","zh":"修院是訓練人成為神父或宗教領袖的學校。"},{"en":"A young man entering a seminary may study theology, scripture, and church practice.","zh":"進入修院的年輕人可能學習神學、聖經和教會實務。"},{"en":"If someone studies in a seminary, they are preparing for religious service.","zh":"如果某人在修院學習，他就是在為宗教服務作準備。"},{"en":"The phrase refers to a specialised religious training institution.","zh":"這個短語指專門的宗教訓練機構。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":2},{"front":"be posted to","meaning":"被派駐到","examples":[{"en":"He was posted to Rome as a young seminarian in 1922.","zh":"1922年，他以年輕修生身份被派駐到羅馬。"},{"en":"To be posted to a place means to be officially sent there for work, study, or service.","zh":"“Be posted to” 某地指被正式派往該地工作、學習或服務。"},{"en":"A diplomat may be posted to another country for several years.","zh":"外交官可能被派駐到另一個國家數年。"},{"en":"If someone is posted to Rome, the move is usually decided by an organisation, not only personal choice.","zh":"如果某人被派駐到羅馬，該調動通常由組織決定，不只是個人選擇。"},{"en":"The phrase often appears in work, military, religious, or diplomatic contexts.","zh":"這個短語常見於工作、軍事、宗教或外交語境。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":2},{"front":"young seminarian","meaning":"年輕修生","examples":[{"en":"He arrived in Rome as a young seminarian.","zh":"他以年輕修生身份抵達羅馬。"},{"en":"A young seminarian is a young person training in a seminary to become a priest.","zh":"年輕修生是在修院受訓成為神父的年輕人。"},{"en":"A young seminarian may spend years studying religion before ordination.","zh":"年輕修生可能在被祝聖前花多年學習宗教。"},{"en":"If a young seminarian is sent abroad, their training may become more advanced and international.","zh":"如果年輕修生被派往海外，其訓練可能變得更高階和國際化。"},{"en":"The phrase identifies both age and religious training status.","zh":"這個短語同時指出年齡和宗教訓練身份。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":3},{"front":"come to power","meaning":"掌權；上台","examples":[{"en":"Mussolini came to power in 1922.","zh":"Mussolini 於1922年上台。"},{"en":"To come to power means to gain control of a government or political system.","zh":"“Come to power” 指取得政府或政治制度的控制權。"},{"en":"A leader may come to power after an election, revolution, or political crisis.","zh":"領袖可能在選舉、革命或政治危機後掌權。"},{"en":"When an extreme leader comes to power, laws and public life may change quickly.","zh":"當極端領袖上台，法律和公共生活可能迅速改變。"},{"en":"The phrase is used for political rise and authority.","zh":"這個短語用於政治崛起和權力取得。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":3},{"front":"while studying in Rome","meaning":"在羅馬求學期間","examples":[{"en":"While studying in Rome, O’Flaherty earned a degree in theology.","zh":"在羅馬求學期間，O’Flaherty 取得神學學位。"},{"en":"While studying in Rome means during the period when he was a student in Rome.","zh":"“While studying in Rome” 指他在羅馬作學生的那段期間。"},{"en":"While studying abroad, a student may learn both academic knowledge and local culture.","zh":"在海外求學期間，學生可能同時學到學術知識和本地文化。"},{"en":"If someone earns a degree while studying overseas, that experience can shape their future career.","zh":"如果某人在海外求學期間取得學位，該經驗可以塑造其未來事業。"},{"en":"The phrase gives time and place for an educational achievement.","zh":"這個短語為教育成就提供時間和地點。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":3},{"front":"earn a degree in","meaning":"取得……學位","examples":[{"en":"He earned a degree in theology while studying in Rome.","zh":"他在羅馬求學期間取得神學學位。"},{"en":"To earn a degree in a subject means to complete a university-level qualification in that subject.","zh":"“Earn a degree in” 某科指完成該科的大學程度資格。"},{"en":"A student may earn a degree in engineering after several years of study and exams.","zh":"學生可能在多年學習和考試後取得工程學位。"},{"en":"If someone earns a degree in theology, they have formally studied religious ideas and doctrine.","zh":"如果某人取得神學學位，他就正式研究過宗教思想和教義。"},{"en":"The phrase describes academic achievement.","zh":"這個短語描述學術成就。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":3},{"front":"theology","meaning":"神學","examples":[{"en":"O’Flaherty studied theology in Rome.","zh":"O’Flaherty 在羅馬學習神學。"},{"en":"Theology is the academic study of God, religion, beliefs, and religious doctrine.","zh":"神學是對上帝、宗教、信仰和宗教教義的學術研究。"},{"en":"A theology student may study scripture, church history, and moral teaching.","zh":"神學學生可能學習聖經、教會歷史和道德教導。"},{"en":"If someone studies theology deeply, they may be preparing for religious leadership.","zh":"如果某人深入學習神學，可能是在準備宗教領導工作。"},{"en":"The word refers to serious study of religion.","zh":"這個詞指對宗教的嚴肅研究。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":3},{"front":"be ordained","meaning":"被祝聖為神父","examples":[{"en":"O’Flaherty was ordained in 1925.","zh":"O’Flaherty 於1925年被祝聖為神父。"},{"en":"To be ordained means to be officially made a priest or religious minister.","zh":"“Be ordained” 指被正式任命為神父或宗教神職人員。"},{"en":"After years of training, a seminarian may be ordained in a church ceremony.","zh":"經過多年訓練後，修生可能在教堂儀式中被祝聖為神父。"},{"en":"Once someone is ordained, they can perform priestly duties such as saying Mass.","zh":"一旦某人被祝聖為神父，就可以履行主持彌撒等神職職責。"},{"en":"The phrase marks an official religious appointment.","zh":"這個短語標示正式宗教任命。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":3},{"front":"go on to study","meaning":"繼續深造","examples":[{"en":"He went on to study in Rome for a further two years.","zh":"他繼續在羅馬深造兩年。"},{"en":"To go on to study means to continue studying after completing an earlier stage.","zh":"“Go on to study” 指完成較早階段後繼續學習。"},{"en":"After finishing secondary school, a student may go on to study at university.","zh":"完成中學後，學生可能繼續到大學深造。"},{"en":"If someone goes on to study further, they are deepening their knowledge.","zh":"如果某人繼續深造，就是在加深知識。"},{"en":"The phrase shows educational progression.","zh":"這個短語顯示教育上的進展。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":3},{"front":"for a further two years","meaning":"再多兩年","examples":[{"en":"He remained in Rome for a further two years.","zh":"他在羅馬再留了兩年。"},{"en":"For a further two years means for two additional years after the earlier period.","zh":"“For a further two years” 指在之前時期之後再多兩年。"},{"en":"A student may stay overseas for a further two years to finish a master’s degree.","zh":"學生可能為完成碩士學位而在海外再留兩年。"},{"en":"If someone studies for a further two years, their training becomes longer and more specialised.","zh":"如果某人再學習兩年，其訓練會變得更長和更專門。"},{"en":"The phrase adds extra time to an existing period.","zh":"這個短語在原有時段上加入額外時間。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":3},{"front":"earn doctorates in","meaning":"取得……博士學位","examples":[{"en":"He earned doctorates in divinity, canon law and philosophy.","zh":"他取得神學、教會法和哲學博士學位。"},{"en":"To earn doctorates in subjects means to complete advanced doctoral qualifications in those fields.","zh":"“Earn doctorates in” 某些科目指完成那些範疇的高階博士資格。"},{"en":"A scholar may earn doctorates in history and law after many years of research.","zh":"學者可能經過多年研究後取得歷史和法律博士學位。"},{"en":"Earning doctorates shows high academic achievement and specialist knowledge.","zh":"取得博士學位顯示高度學術成就和專門知識。"},{"en":"The phrase describes advanced university-level success.","zh":"這個短語描述高階大學程度成就。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":3},{"front":"divinity","meaning":"神學","examples":[{"en":"O’Flaherty earned a doctorate in divinity.","zh":"O’Flaherty 取得神學博士學位。"},{"en":"Divinity is the study of God, religion, and sacred matters, especially in Christian education.","zh":"Divinity 是對上帝、宗教和神聖事物的研究，尤其用於基督宗教教育。"},{"en":"A divinity student may study scripture, church teaching, and religious ethics.","zh":"神學學生可能學習聖經、教會教導和宗教倫理。"},{"en":"If someone earns a doctorate in divinity, they have completed advanced religious scholarship.","zh":"如果某人取得神學博士學位，他就完成了高階宗教學術研究。"},{"en":"The word is closely related to theology.","zh":"這個詞與 theology 密切相關。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":3},{"front":"canon law","meaning":"教會法","examples":[{"en":"He studied canon law as part of his advanced religious education.","zh":"他把教會法作為高階宗教教育的一部分來學習。"},{"en":"Canon law is the body of rules and laws used by the Catholic Church.","zh":"教會法是天主教會使用的一套規則和法律。"},{"en":"A priest may study canon law to understand church marriage rules and church discipline.","zh":"神父可能學習教會法，以理解教會婚姻規則和教會紀律。"},{"en":"If a religious dispute involves official church rules, canon law may be important.","zh":"如果宗教爭議涉及正式教會規則，教會法可能很重要。"},{"en":"The phrase refers to church law, not ordinary state law.","zh":"這個短語指教會法律，而不是普通國家法律。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":3},{"front":"philosophy","meaning":"哲學","examples":[{"en":"He also earned a doctorate in philosophy.","zh":"他也取得哲學博士學位。"},{"en":"Philosophy is the study of big questions about truth, knowledge, morality, and existence.","zh":"哲學研究關於真理、知識、道德和存在的重大問題。"},{"en":"A philosophy class may ask what makes an action right or wrong.","zh":"哲學課可能問甚麼令一個行為正確或錯誤。"},{"en":"Studying philosophy can train people to reason carefully and question assumptions.","zh":"學習哲學可以訓練人謹慎推理和質疑假設。"},{"en":"The word refers to abstract but disciplined thinking.","zh":"這個詞指抽象但有紀律的思考。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":4},{"front":"at various times","meaning":"在不同時期","examples":[{"en":"O’Flaherty was posted at various times in Egypt, Haiti and Czechoslovakia.","zh":"O’Flaherty 在不同時期被派駐埃及、海地和捷克斯洛伐克。"},{"en":"At various times means on different occasions or during different periods.","zh":"“At various times” 指在不同場合或不同時期。"},{"en":"A teacher may work at various times in primary schools, language centres, and universities.","zh":"老師可能在不同時期於小學、語言中心和大學工作。"},{"en":"If someone serves in different countries at various times, they gain broad experience.","zh":"如果某人在不同時期於不同國家服務，就會獲得廣泛經驗。"},{"en":"The phrase shows that events did not all happen at once.","zh":"這個短語顯示事件並非同時發生。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":4},{"front":"as well as","meaning":"以及","examples":[{"en":"He served in Czechoslovakia as well as Palestine.","zh":"他曾在捷克斯洛伐克以及巴勒斯坦服務。"},{"en":"As well as means in addition to another thing or place.","zh":"“As well as” 指除了另一事物或地方之外也包括。"},{"en":"A student may study English as well as Italian if they enjoy languages.","zh":"如果學生喜歡語言，可能學習英語以及意大利語。"},{"en":"If someone works in one country as well as another, their experience becomes more international.","zh":"如果某人在一個國家以及另一個國家工作，其經驗會變得更國際化。"},{"en":"The phrase adds extra information.","zh":"這個短語加入額外資料。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":4},{"front":"prove oneself","meaning":"證明自己的能力","examples":[{"en":"O’Flaherty soon proved himself a very able diplomat.","zh":"O’Flaherty 很快證明自己是一名非常能幹的外交官。"},{"en":"To prove oneself means to show through action that one is capable or worthy.","zh":"“Prove oneself” 指透過行動顯示自己有能力或值得信任。"},{"en":"A new employee may prove herself by solving a difficult customer problem calmly.","zh":"新員工可能透過冷靜解決困難客戶問題來證明自己的能力。"},{"en":"If someone proves himself in a demanding role, others begin to trust him.","zh":"如果某人在艱難角色中證明自己，別人就開始信任他。"},{"en":"The phrase focuses on demonstrating ability.","zh":"這個短語強調展示能力。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":4},{"front":"an able diplomat","meaning":"能幹的外交官","examples":[{"en":"He soon proved himself a very able diplomat.","zh":"他很快證明自己是一名非常能幹的外交官。"},{"en":"An able diplomat is a skilled person who represents an organisation or country in sensitive relations.","zh":"能幹的外交官是熟練地在敏感關係中代表組織或國家的人。"},{"en":"An able diplomat can speak calmly even when two sides disagree strongly.","zh":"能幹的外交官即使在雙方嚴重分歧時，也能冷靜說話。"},{"en":"If a diplomat is able, they can build trust and avoid unnecessary conflict.","zh":"如果外交官能幹，就能建立信任並避免不必要衝突。"},{"en":"The phrase describes diplomatic skill and good judgement.","zh":"這個短語描述外交技巧和良好判斷。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":4},{"front":"golfing skills","meaning":"高爾夫球技","examples":[{"en":"His golfing skills were also noted.","zh":"他的高爾夫球技也受到注意。"},{"en":"Golfing skills are the abilities needed to play golf well.","zh":"高爾夫球技是打好高爾夫所需的能力。"},{"en":"A person with strong golfing skills may hit accurately and stay calm under pressure.","zh":"高爾夫球技強的人可能擊球準確，並在壓力下保持冷靜。"},{"en":"If someone’s golfing skills impress powerful people, sport can become a way to build contacts.","zh":"如果某人的高爾夫球技令權貴留下深刻印象，運動可以成為建立人脈的方法。"},{"en":"The phrase refers to ability in golf, not general athletic talent only.","zh":"這個短語指高爾夫能力，而不只是一般運動天賦。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":4},{"front":"be noted","meaning":"受到注意；被留意到","examples":[{"en":"His skill as a golfer was also noted.","zh":"他作為高爾夫球手的技巧也受到注意。"},{"en":"To be noted means to be noticed, recorded, or recognised.","zh":"“Be noted” 指被注意、記錄或認可。"},{"en":"A student’s careful handwriting may be noted by a teacher during marking.","zh":"學生仔細的字跡可能在批改時被老師留意到。"},{"en":"If a talent is noted by influential people, it may create opportunities.","zh":"如果才能被有影響力的人注意到，可能創造機會。"},{"en":"The phrase suggests that something attracted attention.","zh":"這個短語暗示某事吸引了注意。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":4},{"front":"develop connections","meaning":"建立人脈","examples":[{"en":"He developed important connections through the world of golf.","zh":"他透過高爾夫球界建立了重要人脈。"},{"en":"To develop connections means to build useful relationships with people over time.","zh":"“Develop connections” 指隨時間與人建立有用關係。"},{"en":"A student may develop connections through internships, clubs, and volunteer work.","zh":"學生可能透過實習、社團和義工工作建立人脈。"},{"en":"If someone develops strong connections, they may later receive help or information.","zh":"如果某人建立強大人脈，日後可能得到幫助或資訊。"},{"en":"The phrase focuses on building a network of people.","zh":"這個短語強調建立人際網絡。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":4},{"front":"high-profile connections","meaning":"顯赫的人脈","examples":[{"en":"O’Flaherty developed a number of high-profile connections in Italy.","zh":"O’Flaherty 在意大利建立了多個顯赫人脈。"},{"en":"High-profile connections are relationships with well-known or powerful people.","zh":"顯赫的人脈是與知名或有權勢人士的關係。"},{"en":"A business owner may gain high-profile connections by working with senior officials or famous clients.","zh":"企業主可能透過與高級官員或知名客戶合作而獲得顯赫人脈。"},{"en":"If someone has high-profile connections, authorities may treat them more cautiously.","zh":"如果某人有顯赫人脈，當局可能更謹慎對待他。"},{"en":"The phrase suggests social influence through important contacts.","zh":"這個短語暗示透過重要聯絡人形成社會影響力。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":4},{"front":"through the world of","meaning":"透過……界別","examples":[{"en":"He made influential friends through the world of golf.","zh":"他透過高爾夫球界結識有影響力的朋友。"},{"en":"Through the world of something means by taking part in that area or community.","zh":"“Through the world of” 某事指透過參與該範疇或社群。"},{"en":"A singer may meet producers through the world of music.","zh":"歌手可能透過音樂界認識製作人。"},{"en":"If someone enters an elite sporting world, they may meet people they would not meet otherwise.","zh":"如果某人進入精英運動圈，就可能認識平時不會遇到的人。"},{"en":"The phrase shows the channel through which relationships are formed.","zh":"這個短語顯示關係形成的途徑。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":4},{"front":"with the likes of","meaning":"與……這類人物","examples":[{"en":"He often played golf with the likes of ex-king Alfonso of Spain.","zh":"他經常與西班牙前國王 Alfonso 這類人物打高爾夫球。"},{"en":"With the likes of means with people such as those named, usually important or famous people.","zh":"“With the likes of” 指與所提及這類人一起，通常是重要或知名人士。"},{"en":"A young designer may work with the likes of famous brands after winning a prize.","zh":"年輕設計師得獎後，可能與知名品牌這類對象合作。"},{"en":"If someone socialises with the likes of former kings and ministers, they have elite connections.","zh":"如果某人與前國王和部長這類人物交往，就有精英人脈。"},{"en":"The phrase often highlights the status of the people mentioned.","zh":"這個短語常突出所提人物的地位。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":4},{"front":"ex-king","meaning":"前國王","examples":[{"en":"O’Flaherty played golf with an ex-king of Spain.","zh":"O’Flaherty 與一位西班牙前國王打高爾夫球。"},{"en":"An ex-king is a man who was once king but no longer holds that position.","zh":"前國王是曾經為國王但不再擁有該職位的男子。"},{"en":"An ex-president or ex-king may still have social influence after leaving office.","zh":"前總統或前國王離任後仍可能有社會影響力。"},{"en":"If someone plays sport with an ex-king, they are moving in very high social circles.","zh":"如果某人與前國王打球，就是在非常高層的社交圈中活動。"},{"en":"The phrase describes former royal status.","zh":"這個短語描述過去的王室身份。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":5},{"front":"son-in-law","meaning":"女婿","examples":[{"en":"Count Ciano was Mussolini’s son-in-law.","zh":"Ciano 伯爵是 Mussolini 的女婿。"},{"en":"A son-in-law is the husband of someone’s daughter.","zh":"女婿是某人女兒的丈夫。"},{"en":"Parents may invite their son-in-law to family dinners and celebrations.","zh":"父母可能邀請女婿參加家庭晚餐和慶祝活動。"},{"en":"If a political leader’s son-in-law has power, family ties may influence politics.","zh":"如果政治領袖的女婿有權力，家庭關係可能影響政治。"},{"en":"The phrase describes a family relationship by marriage.","zh":"這個短語描述婚姻形成的家庭關係。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":5},{"front":"since early childhood","meaning":"自幼以來","examples":[{"en":"His golfing skill had developed since early childhood.","zh":"他的高爾夫球技自幼以來已經發展。"},{"en":"Since early childhood means from the time when someone was very young.","zh":"“Since early childhood” 指從某人很小的時候開始。"},{"en":"A pianist may have practised since early childhood and become highly skilled.","zh":"鋼琴家可能自幼以來練習，並變得非常熟練。"},{"en":"If a skill develops since early childhood, years of practice can make it impressive.","zh":"如果一項技能自幼以來發展，多年練習可以令它令人印象深刻。"},{"en":"The phrase emphasises a long period of development.","zh":"這個短語強調長時間發展。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":5},{"front":"undoubtedly impressed","meaning":"無疑令……留下深刻印象","examples":[{"en":"His golfing skill undoubtedly impressed powerful people.","zh":"他的高爾夫球技無疑令有權勢的人留下深刻印象。"},{"en":"Undoubtedly impressed means clearly made people admire or respect something.","zh":"“Undoubtedly impressed” 指明顯令人欣賞或尊重某事。"},{"en":"A student’s calm speech undoubtedly impressed the interview panel.","zh":"學生冷靜的演講無疑令面試小組留下深刻印象。"},{"en":"If a skill impresses powerful people, it may open social and professional doors.","zh":"如果一項技能令有權勢的人留下印象，可能打開社交和職業機會。"},{"en":"The phrase expresses strong confidence that admiration was created.","zh":"這個短語強烈表示確實產生了欣賞。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":5},{"front":"come to rely on","meaning":"後來開始依靠","examples":[{"en":"O’Flaherty would come to rely on his high profile.","zh":"O’Flaherty 後來開始依靠自己的高知名度。"},{"en":"To come to rely on something means to gradually begin depending on it.","zh":"“Come to rely on” 某事指逐漸開始依靠它。"},{"en":"A student may come to rely on a study timetable after seeing that it reduces stress.","zh":"學生看見溫習時間表能減少壓力後，可能開始依靠它。"},{"en":"If someone’s public reputation protects them, they may rely on it during danger.","zh":"如果某人的公眾聲譽保護了他，他可能在危險中依靠它。"},{"en":"The phrase shows dependence developing over time.","zh":"這個短語顯示依賴隨時間形成。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":5},{"front":"high profile","meaning":"高知名度","examples":[{"en":"His high profile made the authorities slow to move against him.","zh":"他的高知名度令當局遲遲沒有對他採取行動。"},{"en":"A high profile means a person is well known and publicly visible.","zh":"高知名度指一個人廣為人知並受到公眾注意。"},{"en":"A high-profile teacher may attract attention because many parents know their results.","zh":"高知名度老師可能因許多家長知道其成績而受到注意。"},{"en":"If someone has a high profile, officials may fear public reaction before acting against them.","zh":"如果某人有高知名度，官員在對付他前可能害怕公眾反應。"},{"en":"The phrase describes public visibility and reputation.","zh":"這個短語描述公眾能見度和聲譽。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":5},{"front":"high connections","meaning":"高層人脈；顯赫關係","examples":[{"en":"His high connections helped him protect innocent people.","zh":"他的高層人脈幫助他保護無辜的人。"},{"en":"High connections are relationships with powerful or influential people.","zh":"高層人脈是與有權力或有影響力人士的關係。"},{"en":"A charity leader with high connections may reach senior officials quickly.","zh":"有高層人脈的慈善領袖可能很快接觸到高級官員。"},{"en":"If someone has high connections, they may gain protection, information, or access.","zh":"如果某人有高層人脈，可能得到保護、資訊或渠道。"},{"en":"The phrase suggests influence through elite relationships.","zh":"這個短語暗示透過精英關係產生影響力。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":5},{"front":"in the coming years","meaning":"在隨後幾年","examples":[{"en":"His connections became important in the coming years.","zh":"他的人脈在隨後幾年變得重要。"},{"en":"In the coming years means in the years after the present point in the story.","zh":"“In the coming years” 指故事中此刻之後的幾年。"},{"en":"A student’s language skills may become useful in the coming years when they work abroad.","zh":"學生的語言能力在隨後幾年到海外工作時可能變得有用。"},{"en":"If relationships are built early, they may matter greatly in the coming years.","zh":"如果關係早早建立，它們在隨後幾年可能非常重要。"},{"en":"The phrase points forward to later events.","zh":"這個短語指向後來事件。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":5},{"front":"war broke out","meaning":"戰爭爆發","examples":[{"en":"War broke out in Europe.","zh":"歐洲爆發戰爭。"},{"en":"When war breaks out, fighting begins suddenly or officially between countries or groups.","zh":"“War breaks out” 指國家或群體之間突然或正式開始戰鬥。"},{"en":"If war breaks out, families may flee, schools may close, and supplies may become scarce.","zh":"如果戰爭爆發，家庭可能逃難，學校可能關閉，物資可能短缺。"},{"en":"War breaking out can change ordinary lives almost overnight.","zh":"戰爭爆發可以幾乎一夜之間改變普通生活。"},{"en":"The phrase describes the start of armed conflict.","zh":"這個短語描述武裝衝突的開始。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":5},{"front":"align itself with","meaning":"與……結盟","examples":[{"en":"Italy aligned itself with Hitler’s Germany.","zh":"意大利與希特拉德國結盟。"},{"en":"To align itself with another power means to support it or join its side.","zh":"“Align itself with” 另一勢力指支持它或加入其一方。"},{"en":"A company may align itself with an environmental campaign to show shared values.","zh":"公司可能與環保活動結盟，以顯示共同價值。"},{"en":"If a country aligns itself with a dangerous regime, its policies may also become harsher.","zh":"如果一個國家與危險政權結盟，其政策也可能變得更嚴厲。"},{"en":"The phrase describes political or strategic joining.","zh":"這個短語描述政治或策略上的結合。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":5},{"front":"Hitler’s Germany","meaning":"希特拉德國","examples":[{"en":"Italy aligned itself with Hitler’s Germany.","zh":"意大利與希特拉德國結盟。"},{"en":"Hitler’s Germany refers to Germany under Adolf Hitler’s Nazi rule.","zh":"希特拉德國指 Adolf Hitler 納粹統治下的德國。"},{"en":"In history lessons, Hitler’s Germany is studied as an example of dictatorship and extremist ideology.","zh":"在歷史課中，希特拉德國被作為獨裁和極端意識形態的例子研究。"},{"en":"If a state joined Hitler’s Germany, it became linked to Nazi policies and war aims.","zh":"如果一個國家加入希特拉德國一方，就與納粹政策和戰爭目標相連。"},{"en":"The phrase identifies a specific historical regime.","zh":"這個短語指出特定歷史政權。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":5},{"front":"a policy of discriminating against","meaning":"歧視……的政策","examples":[{"en":"Italy supported a policy of discriminating against minority groups.","zh":"意大利支持歧視少數群體的政策。"},{"en":"A policy of discriminating against people is an official practice of treating them unfairly because of identity.","zh":"歧視某些人的政策，是因身份而不公平對待他們的官方做法。"},{"en":"A school would be unjust if it had a policy of discriminating against students from poorer families.","zh":"如果學校有歧視較貧窮家庭學生的政策，那就是不公義。"},{"en":"If discrimination becomes policy, harm becomes systematic rather than accidental.","zh":"如果歧視變成政策，傷害就變成系統性，而不是偶然。"},{"en":"The phrase describes organised unfair treatment.","zh":"這個短語描述有組織的不公平對待。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":6},{"front":"minority groups","meaning":"少數群體；少數族裔","examples":[{"en":"The regime discriminated against minority groups.","zh":"該政權歧視少數群體。"},{"en":"Minority groups are groups that are smaller in number or less powerful within a society.","zh":"少數群體是在社會中人數較少或權力較小的群體。"},{"en":"Minority groups may need legal protection if they face prejudice or exclusion.","zh":"如果少數群體面對偏見或排斥，可能需要法律保護。"},{"en":"If a government targets minority groups, injustice can become widespread.","zh":"如果政府針對少數群體，不公義可能變得普遍。"},{"en":"The phrase often refers to ethnic, religious, racial, or cultural groups.","zh":"這個短語常指族裔、宗教、種族或文化群體。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":6},{"front":"give someone the power to","meaning":"給予某人……的能力","examples":[{"en":"His connections gave him the power to help others.","zh":"他的人脈給予他幫助別人的能力。"},{"en":"To give someone the power to do something means to give them the ability, authority, or opportunity to do it.","zh":"“Give someone the power to” 做某事指給予某人能力、權限或機會去做它。"},{"en":"Education can give students the power to choose better jobs.","zh":"教育可以給予學生選擇更好工作的能力。"},{"en":"If connections give someone the power to protect others, social networks can become lifesaving.","zh":"如果人脈給予某人保護他人的能力，社交網絡可以變得能救命。"},{"en":"The phrase links a resource with ability to act.","zh":"這個短語把資源與行動能力連繫起來。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":6},{"front":"make a difference to","meaning":"對……產生影響","examples":[{"en":"O’Flaherty made a difference to the lives of thousands of innocent people.","zh":"O’Flaherty 對數以千計無辜者的人生產生影響。"},{"en":"To make a difference to someone means to have a real positive effect on them.","zh":"“Make a difference to” 某人指對他們產生真實正面影響。"},{"en":"A kind teacher can make a difference to a shy student’s confidence.","zh":"仁慈的老師可以對害羞學生的信心產生影響。"},{"en":"If one person helps many people escape danger, their actions make a huge difference.","zh":"如果一個人幫助許多人逃離危險，其行動就產生巨大影響。"},{"en":"The phrase focuses on meaningful impact.","zh":"這個短語強調有意義的影響。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":6},{"front":"innocent people","meaning":"無辜的人","examples":[{"en":"He helped thousands of innocent people escape danger.","zh":"他幫助數以千計無辜的人逃離危險。"},{"en":"Innocent people are people who have done nothing wrong and do not deserve harm or punishment.","zh":"無辜的人是沒有做錯事、也不應受到傷害或懲罰的人。"},{"en":"In war, innocent people may suffer even though they are not soldiers.","zh":"在戰爭中，無辜的人即使不是士兵也可能受苦。"},{"en":"Protecting innocent people is often seen as a moral duty.","zh":"保護無辜的人常被視為道德責任。"},{"en":"The phrase stresses that the victims were not guilty.","zh":"這個短語強調受害者沒有罪。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":6},{"front":"when the time came","meaning":"到了關鍵時刻","examples":[{"en":"His influence became useful when the time came.","zh":"到了關鍵時刻，他的影響力變得有用。"},{"en":"When the time came means when the important or necessary moment arrived.","zh":"“When the time came” 指重要或必要時刻到來時。"},{"en":"A student may practise for months so they are ready when the exam time comes.","zh":"學生可能練習數月，以便考試時刻到來時已準備好。"},{"en":"If someone builds trust early, they can use that trust when a crisis arrives.","zh":"如果某人早早建立信任，危機來臨時就能使用那份信任。"},{"en":"The phrase points to a decisive moment.","zh":"這個短語指向決定性時刻。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":6},{"front":"the authorities","meaning":"當局","examples":[{"en":"The German and Italian authorities were slow to move against him.","zh":"德國和意大利當局遲遲沒有對他採取行動。"},{"en":"The authorities are the people or organisations with official power.","zh":"當局是擁有官方權力的人或組織。"},{"en":"School authorities may close a campus if a building becomes unsafe.","zh":"如果校舍變得不安全，學校當局可能關閉校園。"},{"en":"If authorities fear public embarrassment, they may delay taking action.","zh":"如果當局害怕公眾尷尬，可能延遲採取行動。"},{"en":"The phrase usually refers to official bodies, not ordinary citizens.","zh":"這個短語通常指官方機構，而不是普通市民。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":6},{"front":"be slow to move against","meaning":"遲遲沒有對……採取行動","examples":[{"en":"The authorities were slow to move against O’Flaherty.","zh":"當局遲遲沒有對 O’Flaherty 採取行動。"},{"en":"To be slow to move against someone means to delay taking action against them.","zh":"“Be slow to move against” 某人指延遲對他採取行動。"},{"en":"A company may be slow to move against a popular manager because staff respect him.","zh":"公司可能遲遲沒有對受歡迎經理採取行動，因為員工尊重他。"},{"en":"If someone has powerful friends, officials may hesitate before acting.","zh":"如果某人有強大朋友，官員在行動前可能猶豫。"},{"en":"The phrase suggests caution, delay, or reluctance.","zh":"這個短語暗示謹慎、拖延或不情願。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":6},{"front":"in the autumn of","meaning":"在……的秋天","examples":[{"en":"In the autumn of 1942, the authorities began targeting opponents.","zh":"1942年秋天，當局開始針對反對者。"},{"en":"In the autumn of a year means during the fall season of that year.","zh":"“In the autumn of” 某年指該年的秋季期間。"},{"en":"In the autumn of 2020, many schools changed their teaching plans.","zh":"2020年秋天，許多學校改變了教學計劃。"},{"en":"Giving a season and year helps readers understand when events happened.","zh":"給出季節和年份有助讀者理解事件何時發生。"},{"en":"The phrase gives a specific historical time period.","zh":"這個短語給出特定歷史時期。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":6},{"front":"crack down on","meaning":"打壓；鎮壓","examples":[{"en":"The Germans and Italians started to crack down on hostile figures.","zh":"德國人和意大利人開始打壓敵對人物。"},{"en":"To crack down on people means to take strong action to stop or punish them.","zh":"“Crack down on” 某些人指採取強硬行動阻止或懲罰他們。"},{"en":"A school may crack down on cheating before final exams.","zh":"學校可能在期末考前嚴厲打擊作弊。"},{"en":"If a government cracks down on opponents, freedom and safety may quickly decrease.","zh":"如果政府鎮壓反對者，自由和安全可能迅速下降。"},{"en":"The phrase often suggests harsh official action.","zh":"這個短語常暗示嚴厲官方行動。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":6},{"front":"prominent figures","meaning":"知名人物；重要人物","examples":[{"en":"The authorities targeted prominent figures who opposed their goals.","zh":"當局針對反對其目標的知名人物。"},{"en":"Prominent figures are important or well-known people in society.","zh":"知名人物是社會中重要或廣為人知的人。"},{"en":"A city may invite prominent figures to speak at a public ceremony.","zh":"城市可能邀請知名人物在公共典禮上發言。"},{"en":"If prominent figures oppose a regime, the authorities may see them as dangerous.","zh":"如果知名人物反對政權，當局可能視他們為危險。"},{"en":"The phrase highlights public importance and visibility.","zh":"這個短語強調公眾重要性和能見度。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":6},{"front":"view someone as","meaning":"把某人視為","examples":[{"en":"They viewed some prominent figures as hostile to their goals.","zh":"他們把一些知名人物視為對其目標抱敵意。"},{"en":"To view someone as something means to regard or consider that person in a particular way.","zh":"“View someone as” 某物指以某種方式看待或認為某人。"},{"en":"A teacher may view a quiet student as thoughtful rather than lazy.","zh":"老師可能把安靜學生視為深思，而不是懶惰。"},{"en":"If authorities view someone as a threat, they may monitor or restrict them.","zh":"如果當局把某人視為威脅，可能監察或限制他。"},{"en":"The phrase shows perception or judgement.","zh":"這個短語顯示看法或判斷。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":7},{"front":"hostile to","meaning":"對……抱敵意","examples":[{"en":"The authorities targeted people who were hostile to their goals.","zh":"當局針對對其目標抱敵意的人。"},{"en":"Hostile to something means strongly opposed to it or unfriendly toward it.","zh":"“Hostile to” 某事指強烈反對它或對它不友善。"},{"en":"Some parents may be hostile to a school policy if they think it is unfair.","zh":"如果家長認為校政不公平，可能對它抱敵意。"},{"en":"If a person is hostile to a regime’s aims, the regime may treat them as an enemy.","zh":"如果一個人對政權目標抱敵意，政權可能把他視為敵人。"},{"en":"The phrase describes active opposition or unfriendly attitude.","zh":"這個短語描述積極反對或不友善態度。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":7},{"front":"become more and more extreme","meaning":"變得越來越極端","examples":[{"en":"Their policies became more and more extreme.","zh":"他們的政策變得越來越極端。"},{"en":"To become more and more extreme means to grow increasingly harsh, radical, or severe.","zh":"“Become more and more extreme” 指變得越來越嚴厲、激進或嚴重。"},{"en":"A classroom rule may become more and more extreme if every small mistake receives a heavy punishment.","zh":"如果每個小錯誤都受到重罰，課室規則可能變得越來越極端。"},{"en":"If political policies become extreme, ordinary people may lose safety and rights.","zh":"如果政治政策變得極端，普通人可能失去安全和權利。"},{"en":"The phrase shows a gradual movement toward greater severity.","zh":"這個短語顯示逐漸走向更嚴重。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":7},{"front":"become alarmed by","meaning":"對……感到憂慮","examples":[{"en":"Many people became alarmed by fascist propaganda.","zh":"許多人對法西斯宣傳感到憂慮。"},{"en":"To become alarmed by something means to feel worried or frightened because of it.","zh":"“Become alarmed by” 某事指因它感到擔心或害怕。"},{"en":"Parents may become alarmed by a sudden rise in school bullying.","zh":"家長可能對學校欺凌突然增加感到憂慮。"},{"en":"If propaganda becomes hateful, thoughtful people may become alarmed by its danger.","zh":"如果宣傳變得充滿仇恨，有思想的人可能會對其危險感到憂慮。"},{"en":"The phrase describes a reaction of serious concern.","zh":"這個短語描述嚴重關注的反應。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":7},{"front":"fascist propaganda","meaning":"法西斯宣傳","examples":[{"en":"Many people were alarmed by fascist propaganda.","zh":"許多人對法西斯宣傳感到憂慮。"},{"en":"Fascist propaganda is political messaging that promotes fascist ideas and tries to control public opinion.","zh":"法西斯宣傳是推廣法西斯思想並試圖控制公眾意見的政治訊息。"},{"en":"Propaganda may use posters, speeches, and newspapers to make hatred seem normal.","zh":"宣傳可能使用海報、演講和報紙，使仇恨看起來正常。"},{"en":"If fascist propaganda spreads, minority groups may become targets of fear and blame.","zh":"如果法西斯宣傳擴散，少數群體可能成為恐懼和責怪的目標。"},{"en":"The phrase refers to persuasive political messaging, not neutral information.","zh":"這個短語指具說服目的的政治訊息，而不是中立資訊。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":7},{"front":"be interested in justice","meaning":"關心公義","examples":[{"en":"The German and Italian governments were not interested in justice.","zh":"德國和意大利政府並不關心公義。"},{"en":"To be interested in justice means to care about fairness, rights, and moral treatment.","zh":"“Be interested in justice” 指關心公平、權利和道德對待。"},{"en":"A fair teacher is interested in justice when listening to both sides of an argument.","zh":"公平的老師在聽取爭執雙方時，就是關心公義。"},{"en":"If a government is not interested in justice, it may use law only as a tool of control.","zh":"如果政府不關心公義，它可能只把法律用作控制工具。"},{"en":"The phrase describes concern for fairness and right conduct.","zh":"這個短語描述對公平和正當行為的關注。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":7},{"front":"on an ideological level","meaning":"在意識形態層面","examples":[{"en":"The two governments were aligned on an ideological level.","zh":"兩個政府在意識形態層面一致。"},{"en":"On an ideological level means in terms of political beliefs or guiding ideas.","zh":"“On an ideological level” 指在政治信念或指導思想方面。"},{"en":"Two organisations may disagree on methods but agree on an ideological level about equality.","zh":"兩個組織可能在方法上不同，但在平等這個意識形態層面一致。"},{"en":"If governments align ideologically, their policies may support similar aims.","zh":"如果政府在意識形態上結盟，其政策可能支持相似目標。"},{"en":"The phrase focuses on beliefs rather than practical details.","zh":"這個短語強調信念，而不是實務細節。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":7},{"front":"carry out a policy","meaning":"執行政策","examples":[{"en":"The governments began to carry out a policy of ethnic cleansing.","zh":"兩個政府開始執行種族清洗政策。"},{"en":"To carry out a policy means to put it into action.","zh":"“Carry out a policy” 指把政策付諸實行。"},{"en":"A school may carry out a new attendance policy by checking every class.","zh":"學校可能透過每堂點名來執行新的出席政策。"},{"en":"If a harmful policy is carried out, real people suffer from its consequences.","zh":"如果有害政策被執行，真實的人會承受其後果。"},{"en":"The phrase describes implementation, not just planning.","zh":"這個短語描述實施，而不只是規劃。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":7},{"front":"ethnic cleansing","meaning":"種族清洗","examples":[{"en":"The authorities carried out a policy of ethnic cleansing in Italy.","zh":"當局在意大利執行種族清洗政策。"},{"en":"Ethnic cleansing is the violent removal or destruction of an ethnic or religious group from an area.","zh":"種族清洗是以暴力方式從某地移除或摧毀某族裔或宗教群體。"},{"en":"History classes discuss ethnic cleansing to understand how hatred can become organised violence.","zh":"歷史課討論種族清洗，以理解仇恨如何變成有組織暴力。"},{"en":"If a state supports ethnic cleansing, minority groups face extreme danger.","zh":"如果國家支持種族清洗，少數群體會面臨極大危險。"},{"en":"The phrase describes a grave human rights abuse.","zh":"這個短語描述嚴重人權侵犯。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":7},{"front":"the so-called unwanted","meaning":"所謂「不受歡迎者」","examples":[{"en":"The victims included the so-called unwanted.","zh":"受害者包括所謂「不受歡迎者」。"},{"en":"The so-called unwanted refers to people labelled as undesirable by those in power.","zh":"所謂「不受歡迎者」指被掌權者標籤為不想要的人。"},{"en":"A cruel regime may call certain groups unwanted to justify excluding or harming them.","zh":"殘酷政權可能稱某些群體為不受歡迎者，以合理化排斥或傷害他們。"},{"en":"If people are described this way, the label can make injustice seem acceptable.","zh":"如果人們被這樣描述，該標籤可能令不公義看似可接受。"},{"en":"The phrase is critical because it questions the label itself.","zh":"這個短語帶批判意味，因為它質疑該標籤本身。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":7},{"front":"and so on","meaning":"等等","examples":[{"en":"The victims included Jews, black people, Roma people and so on.","zh":"受害者包括猶太人、黑人、羅姆人等等。"},{"en":"And so on means and other similar people or things in the same list.","zh":"“And so on” 指同一列表中其他相似的人或事物。"},{"en":"A school bag may contain books, pens, notebooks and so on.","zh":"書包可能有書、筆、筆記簿等等。"},{"en":"If a writer uses “and so on,” they show the list continues without naming every item.","zh":"如果作者使用 “and so on”，就是表示列表繼續，但不逐一列出。"},{"en":"The phrase is useful for shortening a list.","zh":"這個短語適合縮短列表。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":7},{"front":"on the other hand","meaning":"另一方面","examples":[{"en":"O’Flaherty, on the other hand, rejected Nazi ideology.","zh":"另一方面，O’Flaherty 拒絕納粹意識形態。"},{"en":"On the other hand introduces a contrasting point or opposite situation.","zh":"“On the other hand” 引出相反觀點或對比情況。"},{"en":"Some students like online lessons; on the other hand, others learn better face to face.","zh":"有些學生喜歡網上課；另一方面，另一些學生面授學得更好。"},{"en":"If one side supports injustice, another person may, on the other hand, resist it.","zh":"如果一方支持不公義，另一人則可能反過來抵抗它。"},{"en":"The phrase helps show contrast clearly.","zh":"這個短語幫助清楚顯示對比。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":8},{"front":"socialise with","meaning":"與……交往","examples":[{"en":"He had socialised with many prominent Jews in Italy.","zh":"他曾與意大利許多知名猶太人交往。"},{"en":"To socialise with people means to spend time with them in friendly or social situations.","zh":"“Socialise with” 某些人指在友好或社交場合與他們相處。"},{"en":"A new employee may socialise with colleagues after work to build trust.","zh":"新員工可能下班後與同事交往，以建立信任。"},{"en":"If someone socialises with people from a targeted group, they may understand their humanity more deeply.","zh":"如果某人與受針對群體的人交往，可能更深入理解他們的人性。"},{"en":"The phrase describes friendly interaction, not only formal meetings.","zh":"這個短語描述友好互動，而不只是正式會面。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":8},{"front":"prominent Jews","meaning":"知名猶太人","examples":[{"en":"O’Flaherty had socialised with many prominent Jews.","zh":"O’Flaherty 曾與許多知名猶太人交往。"},{"en":"Prominent Jews are Jewish people who are well known or influential in society.","zh":"知名猶太人是在社會中廣為人知或有影響力的猶太人。"},{"en":"A city may have prominent lawyers, artists, and businesspeople from different communities.","zh":"一個城市可能有來自不同社群的知名律師、藝術家和商人。"},{"en":"If prominent Jews were targeted, the attack was aimed not only at individuals but at a community.","zh":"如果知名猶太人被針對，攻擊目標就不只是個人，也是一個社群。"},{"en":"The phrase identifies status within a Jewish community.","zh":"這個短語指出猶太社群中的地位。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":8},{"front":"throughout his time in","meaning":"在……期間一直","examples":[{"en":"He met many Jewish people throughout his time in Italy.","zh":"他在意大利期間一直認識許多猶太人。"},{"en":"Throughout his time in a place means during the whole period he stayed there.","zh":"“Throughout his time in” 某地指他留在該地的整段期間。"},{"en":"A student may make friends throughout their time at university.","zh":"學生可能在大學期間一直結識朋友。"},{"en":"If someone builds relationships throughout their stay, those connections may later matter.","zh":"如果某人在逗留期間一直建立關係，這些人脈日後可能重要。"},{"en":"The phrase stresses duration across a whole period.","zh":"這個短語強調整段時期的持續性。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":8},{"front":"adhere to","meaning":"信奉；遵從","examples":[{"en":"O’Flaherty did not adhere to Nazi ideology.","zh":"O’Flaherty 並不信奉納粹意識形態。"},{"en":"To adhere to an idea means to follow, accept, or remain loyal to it.","zh":"“Adhere to” 某想法指遵從、接受或忠於它。"},{"en":"A school should adhere to safety rules even when it is busy.","zh":"學校即使忙碌，也應遵從安全規則。"},{"en":"If a person refuses to adhere to hateful ideology, they may resist unjust orders.","zh":"如果一個人拒絕信奉仇恨意識形態，就可能抵抗不公命令。"},{"en":"The phrase suggests commitment to a belief or rule.","zh":"這個短語暗示對信念或規則的承諾。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":8},{"front":"Nazi ideology","meaning":"納粹意識形態","examples":[{"en":"O’Flaherty rejected Nazi ideology.","zh":"O’Flaherty 拒絕納粹意識形態。"},{"en":"Nazi ideology was a hateful political belief system based on dictatorship, racism, and extreme nationalism.","zh":"納粹意識形態是一套充滿仇恨的政治信念，建基於獨裁、種族主義和極端民族主義。"},{"en":"History education studies Nazi ideology to show how prejudice can become state violence.","zh":"歷史教育研究納粹意識形態，以顯示偏見如何變成國家暴力。"},{"en":"If someone rejects Nazi ideology, they reject its racism and cruelty.","zh":"如果某人拒絕納粹意識形態，就是拒絕其種族主義和殘酷。"},{"en":"The phrase refers to the ideas behind the Nazi regime.","zh":"這個短語指納粹政權背後的思想。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":8},{"front":"start to act","meaning":"開始採取行動","examples":[{"en":"It was then that O’Flaherty started to act.","zh":"正是在那時，O’Flaherty 開始採取行動。"},{"en":"To start to act means to begin taking practical steps instead of only thinking or worrying.","zh":"“Start to act” 指開始採取實際步驟，而不只是思考或擔心。"},{"en":"A student may start to act when they finally make a revision timetable.","zh":"學生終於制定溫習時間表時，可能就是開始採取行動。"},{"en":"If injustice becomes urgent, a moral person may feel they must act.","zh":"如果不公義變得緊急，有道德感的人可能覺得必須行動。"},{"en":"The phrase marks the beginning of action.","zh":"這個短語標示行動的開始。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":8},{"front":"victims of injustice","meaning":"不公義的受害者","examples":[{"en":"He protected Jews and other victims of injustice.","zh":"他保護猶太人和其他不公義的受害者。"},{"en":"Victims of injustice are people harmed by unfair treatment, discrimination, or abuse of power.","zh":"不公義的受害者是受不公平對待、歧視或權力濫用傷害的人。"},{"en":"Workers denied fair pay may become victims of injustice.","zh":"被拒絕公平薪酬的工人可能成為不公義的受害者。"},{"en":"If victims of injustice receive protection, someone has chosen to resist unfairness.","zh":"如果不公義的受害者得到保護，就是有人選擇抵抗不公平。"},{"en":"The phrase stresses moral wrong done to people.","zh":"這個短語強調人們所承受的道德錯誤。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":8},{"front":"keep someone away from","meaning":"使某人遠離","examples":[{"en":"He kept victims away from the Italian and German police.","zh":"他使受害者遠離意大利和德國警察。"},{"en":"To keep someone away from danger means to stop them from getting near it.","zh":"“Keep someone away from” 危險指阻止某人接近它。"},{"en":"Parents keep young children away from busy roads to protect them.","zh":"父母讓年幼兒童遠離繁忙道路，以保護他們。"},{"en":"If people are kept away from hostile police, their chance of survival may increase.","zh":"如果人們被使遠離敵意警察，其生存機會可能增加。"},{"en":"The phrase describes protective separation.","zh":"這個短語描述保護性的分隔。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":8},{"front":"the claws of","meaning":"……的魔爪","examples":[{"en":"He kept victims away from the claws of the police.","zh":"他使受害者遠離警察的魔爪。"},{"en":"The claws of someone is a figurative phrase meaning their dangerous control or power.","zh":"“The claws of” 某人是比喻說法，指其危險控制或權力。"},{"en":"A charity may try to keep young people away from the claws of criminal gangs.","zh":"慈善機構可能嘗試讓年輕人遠離犯罪團伙的魔爪。"},{"en":"If someone falls into the claws of a violent regime, escape becomes difficult.","zh":"如果某人落入暴力政權的魔爪，逃脫就變得困難。"},{"en":"The phrase makes danger sound like being caught by a predator.","zh":"這個短語令危險聽起來像被捕食者抓住。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":8},{"front":"whose orders were to","meaning":"其命令是","examples":[{"en":"The police had orders to send victims to concentration camps.","zh":"警察的命令是把受害者送往集中營。"},{"en":"Whose orders were to means whose official instructions were to do a certain action.","zh":"“Whose orders were to” 指其官方指示是做某個行動。"},{"en":"A guard whose orders were to block the gate may not allow anyone through.","zh":"如果守衛的命令是封鎖大門，就可能不讓任何人通過。"},{"en":"If police orders are unjust, obeying them can still harm innocent people.","zh":"如果警察命令不公，服從它們仍可傷害無辜者。"},{"en":"The phrase explains what someone was instructed to do.","zh":"這個短語解釋某人被指示做甚麼。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":8},{"front":"ship someone to","meaning":"把某人送往","examples":[{"en":"The police planned to ship victims to concentration camps.","zh":"警察計劃把受害者送往集中營。"},{"en":"To ship someone to a place means to send or transport them there, often coldly or forcibly.","zh":"“Ship someone to” 某地指把某人送或運到那裡，常帶冷酷或強迫意味。"},{"en":"Prisoners may be shipped to distant camps without family knowing where they are.","zh":"囚犯可能被送往遙遠營地，而家人不知道他們在哪裡。"},{"en":"If people are shipped away by force, they lose safety, freedom, and contact with home.","zh":"如果人們被強行送走，就失去安全、自由和與家的聯繫。"},{"en":"The phrase often sounds harsh when used about people.","zh":"這個短語用於人時常帶嚴酷感。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":9},{"front":"concentration camps","meaning":"集中營","examples":[{"en":"The victims were at risk of being sent to concentration camps.","zh":"受害者面臨被送往集中營的風險。"},{"en":"Concentration camps were prison camps where regimes detained, abused, and often killed targeted groups.","zh":"集中營是政權拘留、虐待並常殺害受針對群體的監禁營地。"},{"en":"History lessons teach about concentration camps to remember the victims of Nazi persecution.","zh":"歷史課教授集中營，是為了記住納粹迫害的受害者。"},{"en":"Being sent to a concentration camp often meant extreme suffering and death.","zh":"被送往集中營往往意味着極端痛苦和死亡。"},{"en":"The phrase refers to places of mass detention and brutality.","zh":"這個短語指大規模拘禁和殘暴場所。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":9},{"front":"official residence","meaning":"官方住所","examples":[{"en":"O’Flaherty used his official residence as a hiding place.","zh":"O’Flaherty 把自己的官方住所用作藏身之處。"},{"en":"An official residence is a home provided for someone because of their formal position.","zh":"官方住所是因某人的正式職位而提供給他的住所。"},{"en":"A governor may live in an official residence used for meetings and ceremonies.","zh":"總督可能住在用於會議和典禮的官方住所。"},{"en":"If an official residence is used as a hiding place, a public role becomes part of rescue work.","zh":"如果官方住所被用作藏身之處，公共角色就成為救援工作的一部分。"},{"en":"The phrase connects living space with official status.","zh":"這個短語把居住空間與官方身份連繫起來。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":9},{"front":"hiding places","meaning":"藏身之處","examples":[{"en":"He used his old college and official residence as hiding places.","zh":"他把舊學院和官方住所用作藏身之處。"},{"en":"Hiding places are secret or safe places where people or things can be concealed.","zh":"藏身之處是可以隱藏人或物的秘密或安全地方。"},{"en":"Children may use hiding places during a game, but refugees need them for survival.","zh":"兒童在遊戲中可能使用藏身之處，但難民需要它們來生存。"},{"en":"If police are searching for people, good hiding places can save lives.","zh":"如果警察正在搜捕人，好的藏身之處可以救命。"},{"en":"The phrase describes places used to avoid discovery.","zh":"這個短語描述用來避免被發現的地方。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":9},{"front":"as the situation got more desperate","meaning":"隨着情況越來越危急","examples":[{"en":"As the situation got more desperate, he used more hiding places.","zh":"隨着情況越來越危急，他使用了更多藏身之處。"},{"en":"As the situation got more desperate means while conditions became more dangerous and urgent.","zh":"“As the situation got more desperate” 指當情況變得更危險和更緊急時。"},{"en":"As a family’s money problems get more desperate, they may ask relatives for help.","zh":"隨着家庭金錢問題越來越危急，他們可能向親戚求助。"},{"en":"If danger increases, people need more resources and faster decisions.","zh":"如果危險增加，人們就需要更多資源和更快決定。"},{"en":"The phrase links worsening conditions with stronger action.","zh":"這個短語把惡化情況與更強行動連繫起來。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":9},{"front":"threatened","meaning":"受威脅的","examples":[{"en":"The number of threatened people grew.","zh":"受威脅的人數增加了。"},{"en":"Threatened people are people in danger of harm, arrest, punishment, or death.","zh":"受威脅的人是面臨傷害、拘捕、懲罰或死亡危險的人。"},{"en":"A witness may feel threatened if powerful criminals know where they live.","zh":"如果有權勢的罪犯知道證人住在哪裡，證人可能感到受威脅。"},{"en":"If more people become threatened, a rescue network needs more hiding places and helpers.","zh":"如果更多人受威脅，救援網絡就需要更多藏身之處和助手。"},{"en":"The word describes people facing serious danger.","zh":"這個詞描述面對嚴重危險的人。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":9},{"front":"turn to using","meaning":"轉而使用","examples":[{"en":"He turned to using monasteries and convents as hideouts.","zh":"他轉而使用男修道院和女修道院作為藏身地點。"},{"en":"To turn to using something means to start using it because other options are not enough.","zh":"“Turn to using” 某物指因其他選項不足而開始使用它。"},{"en":"A teacher may turn to using videos when students cannot understand a grammar point from notes.","zh":"當學生不能從筆記理解文法點時，老師可能轉而使用影片。"},{"en":"If familiar hiding places become insufficient, rescuers may turn to new safe locations.","zh":"如果熟悉藏身之處變得不足，救援者可能轉而使用新的安全地點。"},{"en":"The phrase suggests a practical change in method.","zh":"這個短語暗示方法上的實際轉變。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":9},{"front":"monasteries and convents","meaning":"男修道院和女修道院","examples":[{"en":"He used monasteries and convents as hideouts.","zh":"他使用男修道院和女修道院作為藏身地點。"},{"en":"Monasteries and convents are religious communities where monks or nuns live.","zh":"男修道院和女修道院是修士或修女居住的宗教團體。"},{"en":"During danger, religious houses may provide food, shelter, and secrecy.","zh":"在危險時期，宗教住所可能提供食物、庇護和保密。"},{"en":"If monasteries and convents agree to hide people, religious networks become rescue networks.","zh":"如果男修道院和女修道院同意藏匿人，宗教網絡就變成救援網絡。"},{"en":"The phrase refers to male and female religious houses.","zh":"這個短語指男性和女性宗教住所。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":9},{"front":"hideouts","meaning":"藏身地點","examples":[{"en":"Monasteries and convents became hideouts for the people he protected.","zh":"男修道院和女修道院成為他所保護的人們的藏身地點。"},{"en":"Hideouts are secret places where people stay to avoid being found.","zh":"藏身地點是人們為避免被發現而停留的秘密地方。"},{"en":"During a crisis, a safe house can become a hideout for people escaping danger.","zh":"在危機中，安全屋可以成為逃避危險者的藏身地點。"},{"en":"If a hideout is discovered, everyone inside may be at risk.","zh":"如果藏身地點被發現，裡面的所有人都可能有危險。"},{"en":"The phrase suggests secrecy and protection.","zh":"這個短語暗示保密和保護。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":9},{"front":"call in favours from","meaning":"請……幫忙；請人還人情","examples":[{"en":"O’Flaherty called in favours from old friends.","zh":"O’Flaherty 請舊友幫忙。"},{"en":"To call in favours from people means to ask them to help because they owe you help or trust you.","zh":"“Call in favours from” 某些人指因他們欠你人情或信任你而請他們幫忙。"},{"en":"A student may call in a favour from a classmate who once received help with homework.","zh":"學生可能請曾受自己功課幫助的同學還人情。"},{"en":"If rescue work becomes dangerous, trusted friends may be asked to repay past kindness.","zh":"如果救援工作變得危險，可信朋友可能被請求回報過去的善意。"},{"en":"The phrase describes using personal relationships for help.","zh":"這個短語描述利用私人關係尋求幫助。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":9},{"front":"old friends","meaning":"舊友","examples":[{"en":"He asked old friends in religious houses to help.","zh":"他請宗教住所中的舊友幫忙。"},{"en":"Old friends are friends known for a long time.","zh":"舊友是認識了很長時間的朋友。"},{"en":"A person may trust old friends more than new acquaintances in a crisis.","zh":"在危機中，一個人可能比起新相識更信任舊友。"},{"en":"If old friends agree to help, past relationships can become practical support.","zh":"如果舊友同意幫忙，過去的關係就可以變成實際支援。"},{"en":"The phrase suggests loyalty built over years.","zh":"這個短語暗示多年建立的忠誠。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":9},{"front":"agree to house","meaning":"同意收容","examples":[{"en":"His friends agreed to house the people he was protecting.","zh":"他的朋友同意收容他所保護的人。"},{"en":"To agree to house people means to allow them to stay in a place for shelter.","zh":"“Agree to house” 某些人指允許他們留在某地得到庇護。"},{"en":"A family may agree to house relatives after a fire destroys their home.","zh":"火災摧毀親戚家園後，一個家庭可能同意收容他們。"},{"en":"If someone agrees to house people secretly, they accept serious responsibility.","zh":"如果某人同意秘密收容人，就接受了重大責任。"},{"en":"The phrase describes giving accommodation.","zh":"這個短語描述提供住宿。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":10},{"front":"the unwanted","meaning":"被視為不受歡迎的人","examples":[{"en":"The unwanted were hidden in religious buildings.","zh":"被視為不受歡迎的人被藏在宗教建築中。"},{"en":"The unwanted refers to people rejected or targeted by a society or regime.","zh":"“The unwanted” 指被社會或政權拒絕或針對的人。"},{"en":"Cruel governments may label refugees or minorities as unwanted to reduce public sympathy.","zh":"殘酷政府可能把難民或少數族裔標籤為不受歡迎者，以減少公眾同情。"},{"en":"If the unwanted are hidden and protected, someone is resisting that cruel label.","zh":"如果被視為不受歡迎的人被藏起並保護，就是有人在抵抗該殘酷標籤。"},{"en":"The phrase is critical because it exposes dehumanising language.","zh":"這個短語帶批判意味，因為它揭示去人性化語言。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":10},{"front":"risk a reprimand","meaning":"冒着被斥責的風險","examples":[{"en":"His friends risked a reprimand from the fascists if caught.","zh":"如果被抓到，他的朋友冒着被法西斯分子斥責的風險。"},{"en":"To risk a reprimand means to face the possibility of being officially criticised or punished.","zh":"“Risk a reprimand” 指面臨被正式批評或懲罰的可能。"},{"en":"A student may risk a reprimand if they break school rules to help a friend.","zh":"如果學生違反校規幫助朋友，可能冒着被斥責的風險。"},{"en":"If helping others is forbidden, even kindness can bring punishment.","zh":"如果幫助他人被禁止，即使善意也可能帶來懲罰。"},{"en":"The phrase describes taking action despite possible official blame.","zh":"這個短語描述即使可能被官方責備仍採取行動。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":10},{"front":"the fascists","meaning":"法西斯分子","examples":[{"en":"The fascists punished those who helped the unwanted.","zh":"法西斯分子懲罰那些幫助被視為不受歡迎者的人。"},{"en":"The fascists were supporters or agents of fascist rule and ideology.","zh":"法西斯分子是法西斯統治和意識形態的支持者或執行者。"},{"en":"In history, fascists often used fear, violence, and propaganda to control society.","zh":"在歷史中，法西斯分子常使用恐懼、暴力和宣傳控制社會。"},{"en":"If fascists punish helpers, rescue work becomes much more dangerous.","zh":"如果法西斯分子懲罰幫助者，救援工作就變得危險得多。"},{"en":"The phrase refers to people acting for a fascist regime or movement.","zh":"這個短語指為法西斯政權或運動行事的人。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":10},{"front":"if caught","meaning":"如果被抓到","examples":[{"en":"The helpers risked punishment if caught.","zh":"如果被抓到，幫助者就冒着受懲罰的風險。"},{"en":"If caught means if someone is discovered while doing something forbidden or dangerous.","zh":"“If caught” 指如果某人在做被禁止或危險事情時被發現。"},{"en":"A student cheating in an exam may be punished if caught.","zh":"考試作弊的學生如果被抓到，可能受懲罰。"},{"en":"If rescuers are caught hiding fugitives, they may face serious consequences.","zh":"如果救援者被抓到藏匿逃亡者，可能面對嚴重後果。"},{"en":"The phrase highlights the risk of discovery.","zh":"這個短語強調被發現的風險。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":10},{"front":"endanger one’s own life","meaning":"危及自己的生命","examples":[{"en":"They endangered their own lives by helping O’Flaherty.","zh":"他們透過幫助 O’Flaherty 而危及自己的生命。"},{"en":"To endanger one’s own life means to put oneself at risk of death or serious harm.","zh":"“Endanger one’s own life” 指令自己面臨死亡或嚴重傷害風險。"},{"en":"A firefighter may endanger their own life to rescue people from a burning building.","zh":"消防員可能為從燃燒建築中救人而危及自己的生命。"},{"en":"If helpers hide people from violent authorities, they may endanger their own lives.","zh":"如果幫助者把人藏起避開暴力當局，他們可能危及自己的生命。"},{"en":"The phrase describes extreme personal risk.","zh":"這個短語描述極大個人風險。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":10},{"front":"be party to","meaning":"參與……","examples":[{"en":"They were party to O’Flaherty’s rescue campaign.","zh":"他們參與了 O’Flaherty 的救援行動。"},{"en":"To be party to something means to be involved in or take part in it.","zh":"“Be party to” 某事指牽涉其中或參與其中。"},{"en":"A school should not be party to unfair treatment of any student.","zh":"學校不應參與對任何學生的不公平對待。"},{"en":"If friends are party to a secret rescue plan, they share both responsibility and risk.","zh":"如果朋友參與秘密救援計劃，他們就共同承擔責任和風險。"},{"en":"The phrase can be neutral, positive, or negative depending on context.","zh":"這個短語可中性、正面或負面，取決於語境。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":10},{"front":"rescue campaign","meaning":"救援行動","examples":[{"en":"O’Flaherty organised a secret rescue campaign.","zh":"O’Flaherty 組織了一場秘密救援行動。"},{"en":"A rescue campaign is an organised effort to save people from danger.","zh":"救援行動是有組織地把人從危險中救出的努力。"},{"en":"After a flood, volunteers may join a rescue campaign to bring families to safety.","zh":"洪水後，義工可能加入救援行動，把家庭帶到安全地方。"},{"en":"If a rescue campaign is secret, planning and trust become essential.","zh":"如果救援行動是秘密的，規劃和信任就變得必要。"},{"en":"The phrase describes coordinated action to save lives.","zh":"這個短語描述協調一致的救命行動。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":10},{"front":"extend one’s efforts to include","meaning":"擴大行動至包括","examples":[{"en":"O’Flaherty extended his efforts to include Allied airmen.","zh":"O’Flaherty 擴大行動至包括盟軍飛行員。"},{"en":"To extend one’s efforts to include someone means to widen the work so that this group is also helped.","zh":"“Extend one’s efforts to include” 某人指擴大工作，使該群體也得到幫助。"},{"en":"A school may extend its support to include parents who need language help.","zh":"學校可能擴大支援至包括需要語言協助的家長。"},{"en":"If a rescue mission expands to include more groups, it needs more resources.","zh":"如果救援任務擴大至包括更多群體，就需要更多資源。"},{"en":"The phrase describes broadening the scope of action.","zh":"這個短語描述擴大行動範圍。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":10},{"front":"escaped British prisoners of war","meaning":"逃脫的英國戰俘","examples":[{"en":"He helped escaped British prisoners of war.","zh":"他幫助逃脫的英國戰俘。"},{"en":"Escaped British prisoners of war were British soldiers who had escaped after being captured during war.","zh":"逃脫的英國戰俘是在戰爭中被俘後逃出的英國士兵。"},{"en":"Escaped prisoners need food, shelter, and a safe route home.","zh":"逃脫的戰俘需要食物、庇護和安全回家路線。"},{"en":"If captured soldiers escape, they remain in danger until they reach friendly territory.","zh":"如果被俘士兵逃脫，在到達友方地區前仍處於危險中。"},{"en":"The phrase identifies a specific group of wartime escapees.","zh":"這個短語指出特定一群戰時逃亡者。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":10},{"front":"prisoners of war","meaning":"戰俘","examples":[{"en":"British prisoners of war received help from O’Flaherty.","zh":"英國戰俘得到 O’Flaherty 的幫助。"},{"en":"Prisoners of war are soldiers or fighters captured by the enemy during war.","zh":"戰俘是在戰爭中被敵方俘虜的士兵或戰鬥人員。"},{"en":"Prisoners of war may be held in camps far from home.","zh":"戰俘可能被關押在遠離家鄉的營地。"},{"en":"If prisoners of war escape, they often need civilian help to survive.","zh":"如果戰俘逃脫，通常需要平民幫助才能生存。"},{"en":"The phrase is a formal term for captured military personnel.","zh":"這個短語是被俘軍事人員的正式說法。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":10},{"front":"downed Allied airmen","meaning":"被擊落的盟軍飛行員","examples":[{"en":"He also helped downed Allied airmen.","zh":"他也幫助被擊落的盟軍飛行員。"},{"en":"Downed Allied airmen were Allied pilots or crew whose aircraft had been shot down or forced down.","zh":"被擊落的盟軍飛行員是飛機被擊落或迫降的盟軍機師或機組人員。"},{"en":"A downed pilot may hide in farmland until a rescue network finds him.","zh":"被擊落的飛行員可能藏在農地中，直到救援網絡找到他。"},{"en":"If airmen are downed behind enemy lines, capture may mean imprisonment or death.","zh":"如果飛行員在敵後被擊落，被俘可能意味着監禁或死亡。"},{"en":"The phrase describes wartime flyers stranded after losing their aircraft.","zh":"這個短語描述失去飛機後滯留的戰時飛行人員。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":11},{"front":"calling once again on","meaning":"再次依靠","examples":[{"en":"Calling once again on his contacts, he found places for people to stay.","zh":"他再次依靠自己的人脈，為人們找到可住之處。"},{"en":"Calling once again on someone means asking them for help again.","zh":"“Calling once again on” 某人指再次請他們幫忙。"},{"en":"A teacher may call once again on parents when a student needs extra support.","zh":"當學生需要額外支援時，老師可能再次請家長幫忙。"},{"en":"If a rescue network grows, the organiser may need to call on trusted contacts repeatedly.","zh":"如果救援網絡擴大，組織者可能需要反覆依靠可信聯絡人。"},{"en":"The phrase shows repeated reliance on people.","zh":"這個短語顯示重複依賴他人。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":11},{"front":"contacts","meaning":"人脈；聯絡人","examples":[{"en":"O’Flaherty used his contacts to build a rescue network.","zh":"O’Flaherty 使用他的人脈建立救援網絡。"},{"en":"Contacts are people one knows who can provide help, information, or access.","zh":"人脈是某人認識並能提供幫助、資訊或渠道的人。"},{"en":"A job seeker may use contacts to learn about opportunities before they are advertised.","zh":"求職者可能利用人脈，在職位刊登前了解機會。"},{"en":"If someone has reliable contacts, they can act more quickly in a crisis.","zh":"如果某人有可靠人脈，就能在危機中更快行動。"},{"en":"The word refers to useful relationships.","zh":"這個詞指有用的人際關係。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":11},{"front":"a network of apartments","meaning":"住宅單位網絡","examples":[{"en":"He developed a network of apartments to house escapees.","zh":"他建立了一個住宅單位網絡來收容逃亡者。"},{"en":"A network of apartments is a connected group of flats used for a shared purpose.","zh":"住宅單位網絡是一組互相連繫、為共同目的使用的單位。"},{"en":"A charity may use a network of apartments to shelter families after a disaster.","zh":"慈善機構可能使用住宅單位網絡，在災難後收容家庭。"},{"en":"If hiding places are spread across a city, discovery of one place may not destroy the whole network.","zh":"如果藏身之處分散於城市各處，一個地方被發現未必摧毀整個網絡。"},{"en":"The phrase suggests organised, connected accommodation.","zh":"這個短語暗示有組織且互相連繫的住宿安排。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":11},{"front":"house someone","meaning":"收容某人","examples":[{"en":"The apartments were used to house escaped prisoners and airmen.","zh":"這些住宅單位用來收容逃脫的戰俘和飛行員。"},{"en":"To house someone means to provide them with a place to live or stay.","zh":"“House someone” 指為某人提供居住或停留的地方。"},{"en":"A community centre may house families temporarily after a fire.","zh":"火災後，社區中心可能暫時收容家庭。"},{"en":"If people are housed safely, they can rest and avoid immediate danger.","zh":"如果人們被安全收容，就可以休息並避免即時危險。"},{"en":"The phrase refers to giving shelter or accommodation.","zh":"這個短語指提供庇護或住宿。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":11},{"front":"safe return to","meaning":"安全返回……","examples":[{"en":"He protected them until their safe return to Britain could be arranged.","zh":"他保護他們，直到可以安排他們安全返回英國。"},{"en":"Safe return to a place means going back there without being harmed.","zh":"“Safe return to” 某地指沒有受傷地回到該地。"},{"en":"Parents wait for their child’s safe return from a school trip.","zh":"父母等待孩子從學校旅行安全返回。"},{"en":"If escapees need safe return to their country, rescue work continues after hiding them.","zh":"如果逃亡者需要安全返回自己的國家，救援工作在藏匿他們後仍要繼續。"},{"en":"The phrase focuses on reaching home safely.","zh":"這個短語強調安全到家。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":11},{"front":"could be arranged","meaning":"可以被安排","examples":[{"en":"Their safe return to Britain could be arranged later.","zh":"他們安全返回英國一事可以稍後被安排。"},{"en":"Could be arranged means could be planned or organised.","zh":"“Could be arranged” 指可以被計劃或組織。"},{"en":"A meeting could be arranged after all members confirm their schedules.","zh":"在所有成員確認時間表後，會議可以被安排。"},{"en":"If travel documents and safe routes are found, a return journey can be arranged.","zh":"如果找到旅行文件和安全路線，回程就可以被安排。"},{"en":"The phrase describes something made possible through planning.","zh":"這個短語描述透過規劃而變得可能的事情。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":11},{"front":"by the end of the war","meaning":"到戰爭結束時","examples":[{"en":"By the end of the war, thousands of people had escaped.","zh":"到戰爭結束時，數以千計的人已經逃脫。"},{"en":"By the end of the war means when the war was finished or nearly finished.","zh":"“By the end of the war” 指在戰爭結束時或接近結束時。"},{"en":"By the end of the school year, students may have completed several projects.","zh":"到學年結束時，學生可能已完成幾個項目。"},{"en":"If thousands had escaped by that time, the rescue work had become large and effective.","zh":"如果到那時數以千計的人已逃脫，救援工作就已變得龐大而有效。"},{"en":"The phrase gives a time limit for measuring results.","zh":"這個短語給出衡量結果的時間界限。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":11},{"front":"have someone to thank for","meaning":"要感謝某人","examples":[{"en":"Thousands of people had O’Flaherty to thank for their escape.","zh":"數以千計的人要感謝 O’Flaherty 令他們得以逃脫。"},{"en":"To have someone to thank for something means that person is responsible for helping make it happen.","zh":"“Have someone to thank for” 某事指某人對幫助事情發生負有功勞。"},{"en":"A student may have a patient teacher to thank for their improved confidence.","zh":"學生可能要感謝一位有耐性的老師，令其信心提升。"},{"en":"If survivors escaped because of one person’s courage, they had that person to thank.","zh":"如果生還者因一個人的勇氣而逃脫，他們就要感謝那個人。"},{"en":"The phrase expresses gratitude and responsibility for a positive outcome.","zh":"這個短語表達感激，以及某人對正面結果的貢獻。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":11},{"front":"escape from","meaning":"逃離……","examples":[{"en":"They owed their escape from the Germans to O’Flaherty.","zh":"他們能逃離德國人，要歸功於 O’Flaherty。"},{"en":"Escape from someone or something means getting away from danger, control, or captivity.","zh":"“Escape from” 某人或某事指離開危險、控制或囚禁。"},{"en":"A family may escape from a burning building through a back door.","zh":"一家人可能從後門逃離燃燒中的建築物。"},{"en":"If people escape from hostile authorities, they may still need protection afterward.","zh":"如果人們逃離敵對當局，之後可能仍需要保護。"},{"en":"The phrase describes leaving danger successfully.","zh":"這個短語描述成功離開危險。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":11},{"front":"nearly certain death","meaning":"幾乎必然的死亡","examples":[{"en":"O’Flaherty saved many people from nearly certain death.","zh":"O’Flaherty 把許多人從幾乎必然的死亡中救出。"},{"en":"Nearly certain death means a situation where death is extremely likely.","zh":"幾乎必然的死亡指死亡極可能發生的情況。"},{"en":"A person trapped in a collapsed building without rescue may face nearly certain death.","zh":"如果一個人被困在倒塌建築物中而沒有救援，可能面臨幾乎必然的死亡。"},{"en":"If people were being sent to concentration camps, rescue could save them from almost inevitable death.","zh":"如果人們正被送往集中營，救援可以使他們逃離幾乎不可避免的死亡。"},{"en":"The phrase stresses extreme danger.","zh":"這個短語強調極端危險。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":11},{"front":"success in doing something","meaning":"成功做到某事","examples":[{"en":"His success in avoiding identification made him famous.","zh":"他成功避免被識別，使他成名。"},{"en":"Success in doing something means managing to achieve that action or result.","zh":"“Success in doing something” 指成功達成某行動或結果。"},{"en":"A student’s success in speaking English may come from daily practice.","zh":"學生成功說英語可能來自每日練習。"},{"en":"If someone succeeds in staying hidden, they can continue dangerous rescue work longer.","zh":"如果某人成功保持隱藏，就能更長時間繼續危險救援工作。"},{"en":"The phrase links achievement with a specific action.","zh":"這個短語把成就與具體行動連繫起來。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":12},{"front":"be identified","meaning":"被認出；被識別","examples":[{"en":"O’Flaherty was never identified during unauthorised rescue missions.","zh":"O’Flaherty 在未經授權的救援任務中從未被認出。"},{"en":"To be identified means to be recognised or discovered as a particular person.","zh":"“Be identified” 指被認出或被發現是某個特定人物。"},{"en":"A witness may be identified from security camera footage.","zh":"證人可能從保安攝錄片段中被識別。"},{"en":"If a rescuer is not identified, they can avoid arrest and continue helping others.","zh":"如果救援者沒有被認出，就可以避免被捕並繼續幫助他人。"},{"en":"The phrase focuses on being recognised.","zh":"這個短語強調被辨認。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":12},{"front":"unauthorised rescue missions","meaning":"未經授權的救援任務","examples":[{"en":"He carried out unauthorised rescue missions outside Vatican City.","zh":"他在梵蒂岡城外執行未經授權的救援任務。"},{"en":"Unauthorised rescue missions are rescue operations done without official permission.","zh":"未經授權的救援任務是沒有官方許可下進行的救援行動。"},{"en":"A volunteer entering a dangerous area without approval may be carrying out an unauthorised mission.","zh":"義工未經批准進入危險地區，可能正在執行未經授權的任務。"},{"en":"If rescue missions are unauthorised, the rescuers may face punishment if discovered.","zh":"如果救援任務未經授權，救援者被發現時可能受懲罰。"},{"en":"The phrase combines lifesaving action with legal or official risk.","zh":"這個短語結合救命行動與法律或官方風險。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":12},{"front":"outside Vatican City","meaning":"在梵蒂岡城外","examples":[{"en":"O’Flaherty carried out rescue missions outside Vatican City.","zh":"O’Flaherty 在梵蒂岡城外執行救援任務。"},{"en":"Outside Vatican City means beyond the borders of Vatican territory.","zh":"“Outside Vatican City” 指超出梵蒂岡領土邊界。"},{"en":"A worker may live inside a campus but meet friends outside the campus after work.","zh":"工人可能住在校園內，但下班後在校園外見朋友。"},{"en":"If O’Flaherty acted outside Vatican City, he faced greater danger from hostile authorities.","zh":"如果 O’Flaherty 在梵蒂岡城外行動，他就面對來自敵對當局的更大危險。"},{"en":"The phrase gives the location and boundary of the action.","zh":"這個短語給出行動的位置和邊界。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":12},{"front":"smuggle someone into","meaning":"秘密帶某人進入","examples":[{"en":"He smuggled Jews and Allied airmen into Vatican City.","zh":"他秘密把猶太人和盟軍飛行員帶進梵蒂岡城。"},{"en":"To smuggle someone into a place means to secretly bring them there, usually past guards or authorities.","zh":"“Smuggle someone into” 某地指秘密把某人帶入該地，通常避過守衛或當局。"},{"en":"During danger, refugees may be smuggled into safe territory by trusted helpers.","zh":"在危險時期，難民可能由可信幫助者秘密帶入安全地區。"},{"en":"If someone is smuggled into a protected place, they may avoid arrest or death.","zh":"如果某人被秘密帶入受保護地方，就可能避免被捕或死亡。"},{"en":"The phrase describes secret movement across a boundary.","zh":"這個短語描述秘密跨越邊界的行動。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":12},{"front":"lead to someone being given","meaning":"導致某人被冠以","examples":[{"en":"His rescue work led to him being given a famous nickname.","zh":"他的救援工作導致他被冠以一個著名外號。"},{"en":"To lead to someone being given something means to cause others to give that person a title, name, award, or result.","zh":"“Lead to someone being given” 某物指導致別人給予某人稱號、名稱、獎項或結果。"},{"en":"A student’s kindness may lead to them being given a leadership award.","zh":"學生的仁慈可能導致他被頒發領袖獎。"},{"en":"If brave actions become well known, they may lead to public recognition.","zh":"如果勇敢行動變得廣為人知，就可能導致公眾認可。"},{"en":"The phrase connects action with a later honour or label.","zh":"這個短語把行動與後來的榮譽或標籤連繫起來。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":12},{"front":"nickname","meaning":"外號","examples":[{"en":"He was given the nickname the Scarlet Pimpernel of the Vatican.","zh":"他被冠以「梵蒂岡的紅花俠」這個外號。"},{"en":"A nickname is an informal name given to a person because of their character, actions, or appearance.","zh":"外號是因某人的性格、行動或外貌而給予的非正式名字。"},{"en":"A student who always fixes computers may get the nickname “Tech Doctor.”","zh":"經常修理電腦的學生可能得到 “Tech Doctor” 這個外號。"},{"en":"If a nickname becomes famous, it can shape how people remember someone.","zh":"如果外號變得有名，它可以塑造人們如何記住某人。"},{"en":"The phrase refers to a name used instead of or alongside a real name.","zh":"這個短語指代替真名或與真名並用的名字。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":12},{"front":"the Scarlet Pimpernel of the Vatican","meaning":"梵蒂岡的紅花俠","examples":[{"en":"O’Flaherty became known as the Scarlet Pimpernel of the Vatican.","zh":"O’Flaherty 被稱為梵蒂岡的紅花俠。"},{"en":"The Scarlet Pimpernel of the Vatican was a nickname comparing O’Flaherty to a fictional rescuer skilled in disguise.","zh":"梵蒂岡的紅花俠是一個外號，把 O’Flaherty 比作擅長變裝的虛構救援英雄。"},{"en":"A person who repeatedly rescues others while escaping capture may earn a heroic nickname.","zh":"一個反覆救人並逃避追捕的人可能得到英雄式外號。"},{"en":"If a nickname compares someone to a famous rescuer, it praises courage and cleverness.","zh":"如果外號把某人比作著名救援者，就是稱讚其勇氣和機智。"},{"en":"The phrase highlights secret rescue work and mastery of disguise.","zh":"這個短語突出秘密救援工作和變裝技巧。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":12},{"front":"an acknowledgement of","meaning":"對……的認可","examples":[{"en":"The nickname was an acknowledgement of his skill in disguise.","zh":"這個外號是對他變裝技巧的認可。"},{"en":"An acknowledgement of something is a recognition or admission that it is real or important.","zh":"對某事的認可是承認或確認它是真實或重要的。"},{"en":"A certificate can be an acknowledgement of a student’s hard work.","zh":"證書可以是對學生努力的認可。"},{"en":"If a nickname acknowledges someone’s skill, it shows others noticed and valued it.","zh":"如果外號認可某人的技能，就顯示別人注意並重視它。"},{"en":"The phrase refers to recognising a contribution or quality.","zh":"這個短語指認可貢獻或特質。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":12},{"front":"a master of disguise","meaning":"變裝大師","examples":[{"en":"O’Flaherty had become a master of disguise.","zh":"O’Flaherty 已成為變裝大師。"},{"en":"A master of disguise is someone extremely skilled at changing appearance to avoid recognition.","zh":"變裝大師是極擅長改變外貌以避免被認出的人。"},{"en":"A spy in a film may be a master of disguise, using clothes and accents to hide identity.","zh":"電影中的間諜可能是變裝大師，用衣服和口音隱藏身份。"},{"en":"If a rescuer is a master of disguise, they can move through dangerous places more safely.","zh":"如果救援者是變裝大師，就能更安全地穿越危險地區。"},{"en":"The phrase praises exceptional skill in concealment.","zh":"這個短語稱讚隱藏身份方面的卓越技巧。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":12},{"front":"after the war","meaning":"戰後","examples":[{"en":"After the war, O’Flaherty continued to serve in Rome.","zh":"戰後，O’Flaherty 繼續在羅馬服務。"},{"en":"After the war means during the period following the end of the war.","zh":"“After the war” 指戰爭結束後的時期。"},{"en":"After the war, many families had to rebuild homes, schools, and communities.","zh":"戰後，許多家庭必須重建家園、學校和社區。"},{"en":"If someone continues serving after the war, their commitment lasts beyond the crisis.","zh":"如果某人在戰後繼續服務，其投入就超越了危機時期。"},{"en":"The phrase gives a post-war time setting.","zh":"這個短語給出戰後時間背景。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":12},{"front":"continue to serve in","meaning":"繼續在……服務","examples":[{"en":"He continued to serve in Rome after the war.","zh":"戰後，他繼續在羅馬服務。"},{"en":"To continue to serve in a place means to keep working or carrying out duties there.","zh":"“Continue to serve in” 某地指繼續在那裡工作或履行職責。"},{"en":"A nurse may continue to serve in a rural clinic after a disaster ends.","zh":"災難結束後，護士可能繼續在鄉村診所服務。"},{"en":"If someone continues to serve, their work is not limited to one dramatic moment.","zh":"如果某人繼續服務，其工作就不只限於一個戲劇性時刻。"},{"en":"The phrase shows sustained duty.","zh":"這個短語顯示持續職責。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":13},{"front":"receive many accolades","meaning":"獲得許多嘉許","examples":[{"en":"O’Flaherty received many accolades after the war.","zh":"O’Flaherty 戰後獲得許多嘉許。"},{"en":"To receive many accolades means to be given many honours, awards, or public praises.","zh":"“Receive many accolades” 指獲得許多榮譽、獎項或公眾讚揚。"},{"en":"A scientist may receive accolades after developing a life-saving treatment.","zh":"科學家研發救命療法後，可能獲得許多嘉許。"},{"en":"If someone saves thousands of lives, public recognition may follow.","zh":"如果某人拯救數以千計生命，公眾認可可能隨之而來。"},{"en":"The phrase describes being honoured for achievement.","zh":"這個短語描述因成就而受到表揚。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":13},{"front":"the US Medal of Freedom","meaning":"美國自由勳章","examples":[{"en":"He received the US Medal of Freedom.","zh":"他獲頒美國自由勳章。"},{"en":"The US Medal of Freedom is a high American honour given for important service or contribution.","zh":"美國自由勳章是美國頒發給有重大服務或貢獻人士的高級榮譽。"},{"en":"A person who protects human life during war may receive a major national award.","zh":"在戰爭期間保護人命的人可能獲得重要國家獎項。"},{"en":"If O’Flaherty received this medal, his work was recognised beyond Ireland and Italy.","zh":"如果 O’Flaherty 獲得這枚勳章，其工作就得到愛爾蘭和意大利以外的認可。"},{"en":"The phrase names a specific official honour.","zh":"這個短語指一項特定官方榮譽。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":13},{"front":"the title Commander of the British Empire","meaning":"大英帝國司令勳章銜","examples":[{"en":"He received the title Commander of the British Empire.","zh":"他獲得大英帝國司令勳章銜。"},{"en":"Commander of the British Empire is a British honour awarded for distinguished service.","zh":"大英帝國司令勳章銜是英國頒予傑出服務者的榮譽。"},{"en":"A person may receive a title for courage, public service, or cultural contribution.","zh":"一個人可能因勇氣、公共服務或文化貢獻而獲得稱銜。"},{"en":"If O’Flaherty received this British title, Britain recognised his wartime help.","zh":"如果 O’Flaherty 獲得這項英國稱銜，英國就是認可他的戰時幫助。"},{"en":"The phrase names a formal honour within the British honours system.","zh":"這個短語指英國榮譽制度中的正式榮譽。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":13},{"front":"fledgling Jewish state","meaning":"新成立的猶太國家","examples":[{"en":"The fledgling Jewish state of Israel recognised his contribution.","zh":"新成立的猶太國家以色列表彰了他的貢獻。"},{"en":"A fledgling state is a newly formed country still developing its institutions and identity.","zh":"Fledgling state 指新成立、仍在發展制度和身份的國家。"},{"en":"A fledgling school may still be building its timetable, staff team, and reputation.","zh":"新成立的學校可能仍在建立時間表、教師團隊和聲譽。"},{"en":"If a fledgling state honours someone, it is already shaping its public memory.","zh":"如果新成立國家表揚某人，它已在塑造公共記憶。"},{"en":"The phrase describes a new state in its early stage.","zh":"這個短語描述處於早期階段的新國家。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":13},{"front":"recognise someone’s contribution","meaning":"表彰某人的貢獻","examples":[{"en":"Israel recognised O’Flaherty’s contribution.","zh":"以色列表彰 O’Flaherty 的貢獻。"},{"en":"To recognise someone’s contribution means to publicly acknowledge the help or value they provided.","zh":"“Recognise someone’s contribution” 指公開承認某人提供的幫助或價值。"},{"en":"A school may recognise a volunteer’s contribution at an end-of-year ceremony.","zh":"學校可能在年終典禮上表彰義工的貢獻。"},{"en":"If a country recognises a rescuer’s contribution, it keeps the memory of their courage alive.","zh":"如果一個國家表彰救援者的貢獻，就能延續其勇氣記憶。"},{"en":"The phrase describes formal or public appreciation.","zh":"這個短語描述正式或公開感謝。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":13},{"front":"proclaim someone","meaning":"宣布某人為","examples":[{"en":"Israel proclaimed him Righteous Among the Nations.","zh":"以色列宣布他為國際義人。"},{"en":"To proclaim someone something means to officially announce that they have that title or status.","zh":"“Proclaim someone” 為某身份指正式宣布某人擁有該稱號或地位。"},{"en":"A city may proclaim a local hero an honorary citizen.","zh":"城市可能宣布本地英雄為榮譽市民。"},{"en":"If a state proclaims someone a national hero, the person’s actions become part of public honour.","zh":"如果國家宣布某人為民族英雄，其行動就成為公共榮譽的一部分。"},{"en":"The phrase describes a formal public declaration.","zh":"這個短語描述正式公開宣告。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":13},{"front":"Righteous Among the Nations","meaning":"國際義人","examples":[{"en":"O’Flaherty was proclaimed Righteous Among the Nations.","zh":"O’Flaherty 被宣布為國際義人。"},{"en":"Righteous Among the Nations is an honour given to non-Jews who risked their lives to save Jews during the Holocaust.","zh":"國際義人是頒給在大屠殺期間冒生命危險拯救猶太人的非猶太人的榮譽。"},{"en":"A person receiving this title is remembered for moral courage during extreme danger.","zh":"獲得這個稱號的人因極端危險中的道德勇氣而被銘記。"},{"en":"If O’Flaherty was given this honour, his protection of Jewish lives was formally recognised.","zh":"如果 O’Flaherty 獲得這項榮譽，他保護猶太人生命的行動就得到正式認可。"},{"en":"The phrase names a specific title of remembrance and honour.","zh":"這個短語指特定紀念和榮譽稱號。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":13},{"front":"retire","meaning":"退休","examples":[{"en":"O’Flaherty retired in 1960 and returned to Ireland.","zh":"O’Flaherty 於1960年退休並返回愛爾蘭。"},{"en":"To retire means to stop working, usually because of age or health.","zh":"“Retire” 指停止工作，通常因年齡或健康原因。"},{"en":"A teacher may retire after many years of service and move closer to family.","zh":"老師可能在多年服務後退休，並搬近家人。"},{"en":"If someone retires after a life of service, they may finally live more quietly.","zh":"如果某人在一生服務後退休，可能終於過較安靜的生活。"},{"en":"The phrase marks the end of formal work.","zh":"這個短語標示正式工作的結束。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":13},{"front":"go home to","meaning":"返回家鄉","examples":[{"en":"He went home to Ireland after retiring.","zh":"他退休後返回家鄉愛爾蘭。"},{"en":"To go home to a place means to return to the place one considers home.","zh":"“Go home to” 某地指回到自己視為家的地方。"},{"en":"A student studying overseas may go home to see family during the summer.","zh":"在海外讀書的學生可能暑假回家探望家人。"},{"en":"If someone goes home after many years abroad, the return may feel emotional.","zh":"如果某人多年在海外後回家，這次返回可能很有情感。"},{"en":"The phrase stresses return and belonging.","zh":"這個短語強調回歸和歸屬。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":13},{"front":"for the remainder of his life","meaning":"在餘生中","examples":[{"en":"He lived in Cahersiveen for the remainder of his life.","zh":"他在餘生中住在 Cahersiveen。"},{"en":"For the remainder of his life means for the rest of his life until death.","zh":"“For the remainder of his life” 指在餘生直到去世。"},{"en":"A retired worker may live near the sea for the remainder of their life.","zh":"退休工人可能在餘生中住在海邊。"},{"en":"If someone spends their final years in a quiet town, their life has entered a calmer stage.","zh":"如果某人在安靜城鎮度過最後歲月，其人生就進入較平靜階段。"},{"en":"The phrase describes the final period of a person’s life.","zh":"這個短語描述人生最後時期。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":13},{"front":"until he died","meaning":"直至他去世","examples":[{"en":"He lived there until he died in 1963.","zh":"他一直住在那裡，直至1963年去世。"},{"en":"Until he died means up to the time of his death.","zh":"“Until he died” 指直到他死亡的時候。"},{"en":"A writer may continue writing letters until she dies.","zh":"作家可能一直寫信，直至她去世。"},{"en":"If someone lives in one place until death, that place becomes part of their final story.","zh":"如果某人一直住在一個地方直到去世，該地就成為其最後故事的一部分。"},{"en":"The phrase gives the ending point of an action or state.","zh":"這個短語給出行動或狀態的終點。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":14},{"front":"be mourned throughout the world","meaning":"受到全世界哀悼","examples":[{"en":"His death was mourned throughout the world.","zh":"他的離世受到全世界哀悼。"},{"en":"To be mourned throughout the world means people in many countries felt sadness after someone died.","zh":"“Be mourned throughout the world” 指某人去世後，許多國家的人感到悲傷。"},{"en":"A humanitarian leader may be mourned worldwide if their work touched many lives.","zh":"如果人道領袖的工作感動許多生命，其去世可能受到全球哀悼。"},{"en":"If a person’s death is mourned globally, their impact reached beyond their own country.","zh":"如果一個人的離世受到全球哀悼，其影響就超越本國。"},{"en":"The phrase describes wide international grief and respect.","zh":"這個短語描述廣泛國際哀傷和尊重。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":14},{"front":"prestigious","meaning":"享負盛名的","examples":[{"en":"The prestigious New York Times published a tribute to him.","zh":"享負盛名的《紐約時報》刊登了一篇向他致敬的文章。"},{"en":"Prestigious means highly respected and admired because of quality, history, or influence.","zh":"“Prestigious” 指因品質、歷史或影響力而受到高度尊重和欽佩。"},{"en":"A prestigious university may attract students from many countries.","zh":"享負盛名的大學可能吸引來自許多國家的學生。"},{"en":"If a prestigious newspaper honours someone, the recognition carries public weight.","zh":"如果享負盛名的報紙表彰某人，該認可就有公共分量。"},{"en":"The word describes high status and respect.","zh":"這個詞描述高地位和尊重。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":14},{"front":"carry a front-page tribute","meaning":"刊登頭版悼文","examples":[{"en":"The New York Times carried a front-page tribute in his honour.","zh":"《紐約時報》刊登頭版悼文向他致敬。"},{"en":"To carry a front-page tribute means to publish an honouring article on the first page of a newspaper.","zh":"“Carry a front-page tribute” 指在報紙第一版刊登致敬文章。"},{"en":"A newspaper may carry a front-page tribute when a national hero dies.","zh":"當民族英雄去世時，報紙可能刊登頭版悼文。"},{"en":"If a tribute appears on the front page, the person’s life is considered highly important.","zh":"如果悼文出現在頭版，該人的人生就被視為非常重要。"},{"en":"The phrase describes prominent public recognition in print.","zh":"這個短語描述報章中顯著的公眾認可。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":14},{"front":"in someone’s honour","meaning":"向某人致敬","examples":[{"en":"The newspaper published a tribute in his honour.","zh":"該報章刊登悼文向他致敬。"},{"en":"In someone’s honour means done to show respect, praise, or remembrance for that person.","zh":"“In someone’s honour” 指為表示對某人的尊重、讚揚或紀念而做。"},{"en":"A school may name a scholarship in a former teacher’s honour.","zh":"學校可能以一位前老師之名命名獎學金，向他致敬。"},{"en":"If an event is held in someone’s honour, their contribution is being publicly remembered.","zh":"如果活動是為某人而舉行，就是公開記住其貢獻。"},{"en":"The phrase expresses respect and commemoration.","zh":"這個短語表達尊重和紀念。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":14},{"front":"never doubt that","meaning":"永遠不要懷疑","examples":[{"en":"Never doubt that committed citizens can change the world.","zh":"永遠不要懷疑堅定投入的公民可以改變世界。"},{"en":"Never doubt that means one should firmly believe the following statement.","zh":"“Never doubt that” 指應堅定相信後面的陳述。"},{"en":"Never doubt that small daily practice can improve language ability over time.","zh":"永遠不要懷疑每日小量練習可以隨時間改善語言能力。"},{"en":"If people doubt their power too much, they may never begin to act.","zh":"如果人們過度懷疑自己的力量，可能永遠不會開始行動。"},{"en":"The phrase introduces a strong reminder or encouragement.","zh":"這個短語引出強烈提醒或鼓勵。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":14},{"front":"a small group of","meaning":"一小群","examples":[{"en":"A small group of committed citizens can change the world.","zh":"一小群堅定投入的公民可以改變世界。"},{"en":"A small group of people means only a few people working or standing together.","zh":"“A small group of” 人指只有少數人一起工作或站在一起。"},{"en":"A small group of students can start a recycling project that later spreads across school.","zh":"一小群學生可以開始回收項目，之後傳遍學校。"},{"en":"If a small group is organised and committed, its influence can become larger than its size.","zh":"如果一小群人有組織且投入，其影響可以大於人數。"},{"en":"The phrase highlights the power of a few people.","zh":"這個短語突出少數人的力量。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":14},{"front":"thoughtful, committed citizens","meaning":"有思想且堅定投入的公民","examples":[{"en":"Thoughtful, committed citizens can change the world.","zh":"有思想且堅定投入的公民可以改變世界。"},{"en":"Thoughtful, committed citizens are people who think carefully and stay dedicated to doing what is right.","zh":"有思想且堅定投入的公民，是仔細思考並持續致力做正確事情的人。"},{"en":"Community volunteers who plan carefully and keep helping families are thoughtful, committed citizens.","zh":"仔細規劃並持續幫助家庭的社區義工，就是有思想且堅定投入的公民。"},{"en":"If such citizens act together, they can challenge injustice and protect vulnerable people.","zh":"如果這些公民一起行動，就能挑戰不公義並保護弱勢者。"},{"en":"The phrase praises moral seriousness and steady action.","zh":"這個短語稱讚道德嚴肅性和穩定行動。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":14},{"front":"change the world","meaning":"改變世界","examples":[{"en":"Margaret Mead believed that committed citizens can change the world.","zh":"Margaret Mead 相信堅定投入的公民可以改變世界。"},{"en":"To change the world means to make society better in a large or meaningful way.","zh":"“Change the world” 指以重大或有意義的方式令社會變得更好。"},{"en":"A teacher may change the world for one child by giving hope and confidence.","zh":"老師可能透過給予希望和信心，改變一個孩子的世界。"},{"en":"If many small acts protect lives, they can add up to world-changing impact.","zh":"如果許多小行動保護生命，它們可以累積成改變世界的影響。"},{"en":"The phrase can mean global change or deeply meaningful human change.","zh":"這個短語可以指全球改變，也可以指深具意義的人性改變。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":14},{"front":"indeed","meaning":"事實上","examples":[{"en":"Indeed, it is the only thing that ever has.","zh":"事實上，這正是唯一曾經改變世界的東西。"},{"en":"Indeed means truly, in fact, or used to strengthen what has just been said.","zh":"“Indeed” 指真的、事實上，或用來加強剛說過的內容。"},{"en":"Small habits matter; indeed, they often decide whether students improve.","zh":"小習慣很重要；事實上，它們常決定學生是否進步。"},{"en":"If a writer says “indeed,” they are reinforcing the previous point.","zh":"如果作者說 “indeed”，就是在加強前面的重點。"},{"en":"The word adds emphasis and confirmation.","zh":"這個詞加入強調和確認。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":14},{"front":"loyal group of helpers","meaning":"忠誠的助手團隊","examples":[{"en":"O’Flaherty had a loyal group of helpers inside and outside the Vatican.","zh":"O’Flaherty 在梵蒂岡內外有一支忠誠的助手團隊。"},{"en":"A loyal group of helpers is a trusted team that continues to support someone despite difficulty or danger.","zh":"忠誠的助手團隊是即使有困難或危險，也持續支持某人的可信團隊。"},{"en":"A community leader may rely on a loyal group of helpers during emergency food distribution.","zh":"社區領袖在緊急食物派發期間，可能依靠忠誠的助手團隊。"},{"en":"If helpers are loyal, secret work becomes safer and more organised.","zh":"如果助手忠誠，秘密工作會更安全和更有組織。"},{"en":"The phrase highlights trust, teamwork, and commitment.","zh":"這個短語突出信任、團隊合作和投入。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":14},{"front":"inside and outside","meaning":"在……內外","examples":[{"en":"He had helpers inside and outside the Vatican.","zh":"他在梵蒂岡內外都有助手。"},{"en":"Inside and outside means both within a place or organisation and beyond it.","zh":"“Inside and outside” 指在某地方或組織之內和之外。"},{"en":"A school project may need support inside and outside the classroom.","zh":"學校項目可能需要課室內外的支援。"},{"en":"If helpers exist inside and outside a protected area, a rescue network can move more flexibly.","zh":"如果受保護地區內外都有助手，救援網絡就能更靈活行動。"},{"en":"The phrase shows support on both sides of a boundary.","zh":"這個短語顯示邊界兩邊都有支援。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":15},{"front":"the kind of people","meaning":"……那類人","examples":[{"en":"O’Flaherty and his helpers were the kind of people Mead was referring to.","zh":"O’Flaherty 和他的助手就是 Mead 所指的那類人。"},{"en":"The kind of people means the type of people with certain qualities or behaviour.","zh":"“The kind of people” 指具有某些品質或行為的那類人。"},{"en":"Honest volunteers are the kind of people a charity needs most.","zh":"誠實義工是慈善機構最需要的那類人。"},{"en":"If people risk themselves to save others, they are the kind of people history remembers.","zh":"如果人們冒險救助他人，他們就是歷史會記住的那類人。"},{"en":"The phrase groups people by character or action.","zh":"這個短語按性格或行動把人分類。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":15},{"front":"refer to","meaning":"指的是","examples":[{"en":"Mead was referring to people like O’Flaherty and his helpers.","zh":"Mead 指的是像 O’Flaherty 和他的助手那樣的人。"},{"en":"To refer to someone or something means to mention, describe, or point to them.","zh":"“Refer to” 某人或某事指提及、描述或指向他們。"},{"en":"A teacher may refer to an earlier lesson when explaining a new grammar point.","zh":"老師解釋新文法點時，可能提到較早課堂。"},{"en":"If a quote refers to committed citizens, O’Flaherty’s helpers are a clear example.","zh":"如果一句引言指的是堅定投入的公民，O’Flaherty 的助手就是清晰例子。"},{"en":"The phrase connects words with the people or ideas they mean.","zh":"這個短語把說話與其所指的人或想法連繫起來。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":15},{"front":"in life","meaning":"生前","examples":[{"en":"In life, O’Flaherty saved thousands of innocent Romans.","zh":"生前，O’Flaherty 拯救了數以千計無辜的羅馬人。"},{"en":"In life means while a person was alive.","zh":"“In life” 指某人在世時。"},{"en":"In life, a teacher may influence students in ways they never fully know.","zh":"生前，老師可能以自己也未必完全知道的方式影響學生。"},{"en":"What someone does in life can shape how they are remembered after death.","zh":"某人生前所做的事可以塑造死後如何被記住。"},{"en":"The phrase contrasts living actions with memory after death.","zh":"這個短語把在世時的行動與死後記憶作對比。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":15},{"front":"in death","meaning":"死後","examples":[{"en":"In death, he is remembered for his courage.","zh":"死後，他因勇氣而被銘記。"},{"en":"In death means after a person has died, especially in how others remember them.","zh":"“In death” 指某人死後，尤其是別人如何記住他。"},{"en":"In death, a public servant may be honoured for years of quiet work.","zh":"死後，公職人員可能因多年默默工作而受到表彰。"},{"en":"If someone is remembered in death for courage, their actions have left a lasting moral example.","zh":"如果某人死後因勇氣被銘記，其行動就留下持久道德榜樣。"},{"en":"The phrase focuses on posthumous memory.","zh":"這個短語強調死後記憶。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":15},{"front":"innocent Romans","meaning":"無辜的羅馬人","examples":[{"en":"He saved thousands of innocent Romans during the war.","zh":"他在戰爭期間拯救了數以千計無辜的羅馬人。"},{"en":"Innocent Romans were people in Rome who had done nothing wrong but were threatened by war and persecution.","zh":"無辜的羅馬人是在羅馬沒有做錯事、卻受戰爭和迫害威脅的人。"},{"en":"Ordinary residents can become innocent victims when violent authorities target civilians.","zh":"當暴力當局針對平民，普通居民可以成為無辜受害者。"},{"en":"If innocent Romans were protected, the rescue work reached local civilians, not only soldiers.","zh":"如果無辜的羅馬人得到保護，救援工作就觸及本地平民，而不只是士兵。"},{"en":"The phrase stresses both place and innocence.","zh":"這個短語同時強調地點和無辜。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":15},{"front":"be remembered as","meaning":"被銘記為","examples":[{"en":"He is remembered as a man who opposed extremism.","zh":"他被銘記為一個反對極端主義的人。"},{"en":"To be remembered as something means that people later think of someone in that way.","zh":"“Be remembered as” 某身份指後來人們以那種方式記住某人。"},{"en":"A kind principal may be remembered as a leader who cared about every student.","zh":"仁慈校長可能被銘記為關心每個學生的領袖。"},{"en":"If someone risks their life for justice, they may be remembered as courageous.","zh":"如果某人為公義冒生命危險，可能被銘記為勇敢。"},{"en":"The phrase describes reputation after time has passed.","zh":"這個短語描述時間過去後的聲譽。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":15},{"front":"bravely stand up to","meaning":"勇敢挺身對抗","examples":[{"en":"O’Flaherty bravely stood up to extremism.","zh":"O’Flaherty 勇敢挺身對抗極端主義。"},{"en":"To bravely stand up to something means to courageously resist or confront it.","zh":"“Bravely stand up to” 某事指勇敢地抵抗或面對它。"},{"en":"A student may bravely stand up to bullying by reporting it and supporting the victim.","zh":"學生可能透過舉報欺凌和支持受害者，勇敢挺身對抗欺凌。"},{"en":"If someone stands up to a violent ideology, they may face danger but protect others.","zh":"如果某人挺身對抗暴力意識形態，可能面對危險但能保護他人。"},{"en":"The phrase combines courage with moral resistance.","zh":"這個短語結合勇氣與道德抵抗。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":15},{"front":"extremism","meaning":"極端主義","examples":[{"en":"He stood up to extremism and injustice.","zh":"他挺身對抗極端主義和不公義。"},{"en":"Extremism is a belief or action that is extreme, intolerant, and often harmful to others.","zh":"極端主義是極端、不寬容並常傷害他人的信念或行動。"},{"en":"Extremism can grow when people are taught to hate groups they do not understand.","zh":"當人們被教導仇恨自己不理解的群體時，極端主義可能增長。"},{"en":"If extremism controls government, violence and discrimination may become policy.","zh":"如果極端主義控制政府，暴力和歧視可能變成政策。"},{"en":"The word describes dangerous political or social rigidity.","zh":"這個詞描述危險的政治或社會僵化思想。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":15},{"front":"be prepared to","meaning":"願意；準備好","examples":[{"en":"He was not prepared to ignore injustice.","zh":"他不願意忽視不公義。"},{"en":"To be prepared to do something means to be willing and ready to do it.","zh":"“Be prepared to” 做某事指願意並準備好去做它。"},{"en":"A good friend may be prepared to help even when it is inconvenient.","zh":"好朋友即使不方便，也可能願意幫忙。"},{"en":"If someone is not prepared to accept injustice, they may take action against it.","zh":"如果某人不願意接受不公義，就可能採取行動反對它。"},{"en":"The phrase describes willingness, not only planning.","zh":"這個短語描述意願，而不只是計劃。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":15},{"front":"turn a blind eye to","meaning":"對……視而不見","examples":[{"en":"O’Flaherty was not prepared to turn a blind eye to injustice.","zh":"O’Flaherty 不願意對不公義視而不見。"},{"en":"To turn a blind eye to something means to ignore it deliberately even though one knows it is wrong.","zh":"“Turn a blind eye to” 某事指明知它錯誤卻故意忽視。"},{"en":"A teacher should not turn a blind eye to bullying in the classroom.","zh":"老師不應對課室欺凌視而不見。"},{"en":"If people turn a blind eye to cruelty, injustice can continue unchecked.","zh":"如果人們對殘酷行為視而不見，不公義就可以不受制止地延續。"},{"en":"The phrase criticises deliberate inaction.","zh":"這個短語批評故意不行動。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":15},{"front":"injustice","meaning":"不公義","examples":[{"en":"He refused to turn a blind eye to injustice.","zh":"他拒絕對不公義視而不見。"},{"en":"Injustice means unfair treatment or a situation where people are denied what is right.","zh":"不公義指不公平對待，或人們被剝奪應有權利的情況。"},{"en":"Paying workers far below a fair wage is a form of injustice.","zh":"給工人遠低於公平水平的工資，是一種不公義。"},{"en":"If injustice is ignored, victims may lose hope and safety.","zh":"如果不公義被忽視，受害者可能失去希望和安全。"},{"en":"The word refers to moral unfairness, not just inconvenience.","zh":"這個詞指道德上的不公平，而不只是麻煩。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":16},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Candidates choose the correct letter, A, B, C or D.","zh":"考生選出正確字母 A、B、C 或 D。"},{"en":"To choose the correct letter means to select the answer option marked by the right letter.","zh":"“Choose the correct letter” 指選出由正確字母標示的答案選項。"},{"en":"In a reading exam, students should check the passage before choosing A, B, C, or D.","zh":"在閱讀考試中，學生應先查看文章，再選 A、B、C 或 D。"},{"en":"If two options are similar, small details in the text decide the correct letter.","zh":"如果兩個選項相似，文本中的小細節會決定正確字母。"},{"en":"The phrase is a common multiple-choice instruction.","zh":"這個短語是常見選擇題指示。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":16},{"front":"voluntarily","meaning":"自願地","examples":[{"en":"The option says that O’Flaherty went to Rome voluntarily.","zh":"該選項說 O’Flaherty 自願地前往羅馬。"},{"en":"Voluntarily means by one’s own choice, without being forced.","zh":"“Voluntarily” 指出於自己的選擇，而不是被迫。"},{"en":"A student may voluntarily join a charity event during the weekend.","zh":"學生可能自願地在週末參加慈善活動。"},{"en":"If someone goes somewhere voluntarily, the decision comes from personal willingness.","zh":"如果某人自願前往某地，該決定來自個人意願。"},{"en":"The word contrasts free choice with being ordered or forced.","zh":"這個詞把自由選擇與被命令或被迫作對比。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":16},{"front":"for personal reasons","meaning":"出於個人原因","examples":[{"en":"The option says that he went to Rome for personal reasons.","zh":"該選項說他出於個人原因前往羅馬。"},{"en":"For personal reasons means because of private motives, needs, or choices.","zh":"“For personal reasons” 指因私人動機、需要或選擇。"},{"en":"A worker may leave a job for personal reasons without explaining every detail.","zh":"員工可能出於個人原因離職，而不解釋每個細節。"},{"en":"If someone moves for personal reasons, the decision may not be ordered by an organisation.","zh":"如果某人因個人原因搬遷，該決定可能不是由組織命令。"},{"en":"The phrase gives a private explanation rather than an official one.","zh":"這個短語給出私人解釋，而不是官方解釋。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":16},{"front":"pursue his studies","meaning":"繼續深造","examples":[{"en":"He wanted to pursue his studies in Rome.","zh":"他想在羅馬繼續深造。"},{"en":"To pursue his studies means to continue or follow a course of education seriously.","zh":"“Pursue his studies” 指認真繼續或從事某個學習課程。"},{"en":"A student may move abroad to pursue her studies in medicine.","zh":"學生可能搬到海外繼續深造醫學。"},{"en":"If someone pursues studies in a famous city, they may gain specialist training and contacts.","zh":"如果某人在著名城市深造，可能獲得專門訓練和人脈。"},{"en":"The phrase describes continuing formal learning.","zh":"這個短語描述繼續正式學習。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":16},{"front":"after completing his studies","meaning":"完成學業後","examples":[{"en":"The option refers to his actions after completing his studies.","zh":"該選項指他完成學業後的行動。"},{"en":"After completing his studies means after finishing a course, degree, or period of education.","zh":"“After completing his studies” 指完成課程、學位或教育時期之後。"},{"en":"After completing her studies, a student may start work or continue to a higher degree.","zh":"學生完成學業後，可能開始工作或繼續攻讀更高學位。"},{"en":"If someone takes a post after completing studies, training has moved into service.","zh":"如果某人在完成學業後接受職位，訓練就轉入服務。"},{"en":"The phrase gives the time after education ends.","zh":"這個短語給出教育結束後的時間。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":16},{"front":"become a priest","meaning":"成為神父","examples":[{"en":"The question asks whether he became a priest before going to Rome.","zh":"題目問他是否在前往羅馬前成為神父。"},{"en":"To become a priest means to be ordained and take on priestly religious duties.","zh":"“Become a priest” 指被祝聖並承擔神父的宗教職責。"},{"en":"A seminarian studies for years before becoming a priest.","zh":"修生在成為神父前會學習多年。"},{"en":"If someone becomes a priest, they can serve religious communities formally.","zh":"如果某人成為神父，就能正式服務宗教社群。"},{"en":"The phrase describes a change into a religious office.","zh":"這個短語描述轉變成宗教職分。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":16},{"front":"at the same time as","meaning":"與……同時","examples":[{"en":"The option compares his move with Mussolini’s rise to power at the same time.","zh":"該選項把他的調動與 Mussolini 同時上台作比較。"},{"en":"At the same time as means during the same period or moment as another event.","zh":"“At the same time as” 指與另一事件在同一時期或同一時刻。"},{"en":"A student may start university at the same time as their sibling starts a new job.","zh":"學生可能在兄弟姊妹開始新工作同時入讀大學。"},{"en":"If two historical events happen at the same time, writers may compare their connection.","zh":"如果兩個歷史事件同時發生，作者可能比較它們的關係。"},{"en":"The phrase links two events by timing.","zh":"這個短語以時間把兩件事連繫起來。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":16},{"front":"under the instructions of","meaning":"在……的指示下","examples":[{"en":"He went to Rome under the instructions of a religious organisation.","zh":"他在一個宗教組織的指示下前往羅馬。"},{"en":"Under the instructions of someone means acting because that person or group gave directions.","zh":"“Under the instructions of” 某人指因該人或團體給出指示而行動。"},{"en":"A trainee nurse may move to another ward under the instructions of a supervisor.","zh":"見習護士可能在主管指示下調到另一病房。"},{"en":"If someone travels under instructions, the move is official rather than purely personal.","zh":"如果某人在指示下旅行，該調動就是官方的，而不純粹是個人決定。"},{"en":"The phrase shows authority behind an action.","zh":"這個短語顯示行動背後的權威。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":16},{"front":"religious organisation","meaning":"宗教組織","examples":[{"en":"The question refers to the religious organisation he belonged to.","zh":"題目指他所屬的宗教組織。"},{"en":"A religious organisation is a group connected with worship, faith, training, or religious service.","zh":"宗教組織是與崇拜、信仰、訓練或宗教服務有關的團體。"},{"en":"A church, monastery, or missionary society can be a religious organisation.","zh":"教會、修道院或傳教會都可以是宗教組織。"},{"en":"If a religious organisation posts someone abroad, it may be directing their training or service.","zh":"如果宗教組織派某人到海外，可能是在安排其訓練或服務。"},{"en":"The phrase refers to an organised faith-based group.","zh":"這個短語指有組織的信仰團體。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":16},{"front":"golfing talents","meaning":"高爾夫球天賦","examples":[{"en":"The question focuses on O’Flaherty’s golfing talents.","zh":"題目集中於 O’Flaherty 的高爾夫球天賦。"},{"en":"Golfing talents are natural or developed abilities in playing golf well.","zh":"高爾夫球天賦是在打高爾夫方面的天生或後天能力。"},{"en":"A young player with golfing talents may attract coaches before becoming famous.","zh":"有高爾夫球天賦的年輕球員可能在成名前吸引教練。"},{"en":"If golfing talents impress powerful people, they can help build unusual social connections.","zh":"如果高爾夫球天賦令權貴留下印象，就能幫助建立不尋常社交關係。"},{"en":"The phrase refers to skill in a specific sport.","zh":"這個短語指特定運動中的技能。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":16},{"front":"be exploited by","meaning":"被……利用","examples":[{"en":"His golfing talents were exploited by him to make connections.","zh":"他的高爾夫球天賦被他用來建立人脈。"},{"en":"To be exploited by someone means to be used by that person, often for a practical advantage.","zh":"“Be exploited by” 某人指被該人利用，通常為了實際優勢。"},{"en":"A student may exploit strong computer skills to help a club design posters.","zh":"學生可能利用強電腦技能幫社團設計海報。"},{"en":"If a talent is exploited wisely, it can create opportunities beyond the skill itself.","zh":"如果才能被明智運用，它可以創造該技能本身以外的機會。"},{"en":"In this context, the phrase means “used strategically,” not abused.","zh":"在這個語境中，這個短語指「策略性使用」，不是濫用。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":17},{"front":"as a means by which to","meaning":"作為……的手段","examples":[{"en":"Golf served as a means by which to meet important people.","zh":"高爾夫球作為結識重要人物的手段。"},{"en":"As a means by which to do something means as a method or tool for doing it.","zh":"“As a means by which to” 做某事指作為做該事的方法或工具。"},{"en":"A school may use drama as a means by which to build speaking confidence.","zh":"學校可能使用戲劇作為建立口語信心的手段。"},{"en":"If sport becomes a means to meet leaders, a hobby can become socially useful.","zh":"如果運動成為結識領袖的手段，興趣就可以變得具社交用途。"},{"en":"The phrase explains the purpose of an activity.","zh":"這個短語解釋活動的目的。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":17},{"front":"meet and influence","meaning":"結識並影響","examples":[{"en":"The option says that he used golf to meet and influence important people.","zh":"該選項說他利用高爾夫球結識並影響重要人物。"},{"en":"To meet and influence people means to get to know them and affect their views or decisions.","zh":"“Meet and influence” 某些人指認識他們並影響其看法或決定。"},{"en":"A community organiser may meet and influence officials through public meetings.","zh":"社區組織者可能透過公開會議結識並影響官員。"},{"en":"If someone can meet important people socially, they may later influence them more easily.","zh":"如果某人能在社交場合結識重要人物，日後可能更容易影響他們。"},{"en":"The phrase combines access with persuasion.","zh":"這個短語結合接觸機會與說服力。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":17},{"front":"important people","meaning":"重要人物","examples":[{"en":"O’Flaherty met important people through golf.","zh":"O’Flaherty 透過高爾夫球認識重要人物。"},{"en":"Important people are people with influence, status, power, or useful knowledge.","zh":"重要人物是有影響力、地位、權力或有用知識的人。"},{"en":"A young worker may meet important people at professional conferences.","zh":"年輕工作者可能在專業會議中認識重要人物。"},{"en":"If important people trust someone, they may help them during a crisis.","zh":"如果重要人物信任某人，可能在危機中幫助他。"},{"en":"The phrase is general and depends on context.","zh":"這個短語較概括，取決於語境。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":17},{"front":"the product of","meaning":"……的成果","examples":[{"en":"The option describes his talents as the product of hard work.","zh":"該選項把他的天賦描述為努力的成果。"},{"en":"The product of something means the result of that cause or process.","zh":"“The product of” 某事指由該原因或過程產生的結果。"},{"en":"A student’s fluent speaking may be the product of years of practice.","zh":"學生流利的口語可能是多年練習的成果。"},{"en":"If a skill is the product of hard work, it did not appear by chance.","zh":"如果技能是努力的成果，它就不是偶然出現的。"},{"en":"The phrase links an outcome to its source.","zh":"這個短語把結果與來源連繫起來。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":17},{"front":"extremely hard work","meaning":"極其努力","examples":[{"en":"The option links his skill to extremely hard work.","zh":"該選項把他的技巧與極其努力連繫起來。"},{"en":"Extremely hard work means very serious, sustained effort.","zh":"“Extremely hard work” 指非常認真而持續的努力。"},{"en":"Preparing for a difficult exam may require extremely hard work over many months.","zh":"準備困難考試可能需要數月極其努力。"},{"en":"If talent is supported by hard work, skill can improve greatly.","zh":"如果天賦由努力支撐，技能可以大幅提升。"},{"en":"The phrase stresses effort at a high level.","zh":"這個短語強調高程度努力。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":17},{"front":"tireless practice","meaning":"不懈練習","examples":[{"en":"The option says that his skill came from tireless practice.","zh":"該選項說他的技巧來自不懈練習。"},{"en":"Tireless practice is repeated practice done with great energy and persistence.","zh":"不懈練習是以巨大精力和堅持進行的反覆練習。"},{"en":"A violinist may improve through tireless practice before a competition.","zh":"小提琴手可能在比賽前透過不懈練習進步。"},{"en":"If someone practises tirelessly, a difficult skill can become natural.","zh":"如果某人不懈練習，困難技能可以變得自然。"},{"en":"The phrase praises long, determined effort.","zh":"這個短語稱讚長期而堅定的努力。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":17},{"front":"go unnoticed","meaning":"未被注意","examples":[{"en":"The option says that his talents went unnoticed until he reached Italy.","zh":"該選項說他的才能直到抵達意大利才被注意。"},{"en":"To go unnoticed means not to be seen, recognised, or appreciated.","zh":"“Go unnoticed” 指未被看見、認出或欣賞。"},{"en":"A quiet student’s effort may go unnoticed if teachers only praise top marks.","zh":"如果老師只稱讚高分，安靜學生的努力可能未被注意。"},{"en":"If a talent goes unnoticed, it may not create opportunities until the right people see it.","zh":"如果才能未被注意，可能直到合適的人看見才創造機會。"},{"en":"The phrase describes lack of attention or recognition.","zh":"這個短語描述缺乏注意或認可。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":17},{"front":"high-profile individuals","meaning":"知名人士；顯赫人物","examples":[{"en":"His golf impressed a number of high-profile individuals.","zh":"他的高爾夫球技令多名知名人士留下深刻印象。"},{"en":"High-profile individuals are well-known people with public status or influence.","zh":"知名人士是有公眾地位或影響力的人。"},{"en":"A charity event may invite high-profile individuals to attract attention and donations.","zh":"慈善活動可能邀請知名人士，以吸引注意和捐款。"},{"en":"If high-profile individuals admire someone, that person’s reputation may grow quickly.","zh":"如果知名人士欣賞某人，該人的聲譽可能迅速提升。"},{"en":"The phrase highlights public importance and social power.","zh":"這個短語突出公眾重要性和社會力量。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":17},{"front":"be exaggerated by","meaning":"被……誇大","examples":[{"en":"The option says that his talents were exaggerated by friends.","zh":"該選項說他的才能被朋友誇大。"},{"en":"To be exaggerated by someone means to be described as greater or more impressive than they really are.","zh":"“Be exaggerated by” 某人指被描述得比實際更大或更令人印象深刻。"},{"en":"A student’s small mistake may be exaggerated by classmates into a big story.","zh":"學生的小錯誤可能被同學誇大成大故事。"},{"en":"If a talent is exaggerated, people may expect more than the person can actually do.","zh":"如果才能被誇大，人們可能期待超出該人實際能力的表現。"},{"en":"The phrase warns that a claim may be overstated.","zh":"這個短語提醒說法可能被過度放大。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":17},{"front":"win someone favour with","meaning":"為某人贏得……好感","examples":[{"en":"The option says his talents helped win him favour with the authorities.","zh":"該選項說他的才能幫助他贏得當局好感。"},{"en":"To win someone favour with people means to make those people like, trust, or support that person.","zh":"“Win someone favour with” 某些人指令那些人喜歡、信任或支持某人。"},{"en":"A worker’s honesty may win her favour with managers and customers.","zh":"工人的誠實可能為她贏得經理和顧客好感。"},{"en":"If a skill wins someone favour with powerful people, it may later offer protection.","zh":"如果一項技能為某人贏得權貴好感，日後可能提供保護。"},{"en":"The phrase describes gaining approval through ability or behaviour.","zh":"這個短語描述透過能力或行為取得認可。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":17},{"front":"when it comes to","meaning":"談到……時","examples":[{"en":"When it comes to Nazi ideology, O’Flaherty’s beliefs were different.","zh":"談到納粹意識形態時，O’Flaherty 的信念不同。"},{"en":"When it comes to something means regarding that particular topic or issue.","zh":"“When it comes to” 某事指關於該特定題目或議題。"},{"en":"When it comes to grammar, small mistakes can change the meaning of a sentence.","zh":"談到文法時，小錯誤可以改變句子意思。"},{"en":"If two people agree on sport but disagree on politics, their views differ when it comes to political values.","zh":"如果兩個人在運動上同意但政治上不同，談到政治價值時，他們的看法就不同。"},{"en":"The phrase introduces the specific subject being discussed.","zh":"這個短語引出正在討論的特定主題。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":18},{"front":"be similar to those of","meaning":"與……的相似","examples":[{"en":"The option asks whether his beliefs were similar to those of minority groups.","zh":"該選項問他的信念是否與少數群體的信念相似。"},{"en":"To be similar to those of another group means to resemble that group’s beliefs, views, or qualities.","zh":"“Be similar to those of” 另一群體指與該群體的信念、看法或特質相似。"},{"en":"A student’s study habits may be similar to those of a hardworking older sibling.","zh":"學生的學習習慣可能與勤奮兄姊的習慣相似。"},{"en":"If two groups face the same injustice, their views may become similar.","zh":"如果兩個群體面對相同不公義，他們的看法可能變得相似。"},{"en":"The phrase compares one person’s ideas with another group’s ideas.","zh":"這個短語比較某人的想法與另一群體的想法。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":18},{"front":"view something as unwanted","meaning":"視……為不受歡迎","examples":[{"en":"Some groups viewed German interference in Italy as unwanted.","zh":"一些群體視德國對意大利的干預為不受歡迎。"},{"en":"To view something as unwanted means to consider it unwelcome or undesirable.","zh":"“View something as unwanted” 指把某事視為不受歡迎或不想要。"},{"en":"Residents may view noisy construction at night as unwanted disruption.","zh":"居民可能把夜間嘈雜工程視為不受歡迎的干擾。"},{"en":"If foreign interference is viewed as unwanted, people may resist it politically or socially.","zh":"如果外國干預被視為不受歡迎，人們可能在政治或社會上抵抗它。"},{"en":"The phrase shows negative judgement toward an action or presence.","zh":"這個短語顯示對某行動或存在的負面判斷。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":18},{"front":"interference in","meaning":"對……的干預","examples":[{"en":"The option refers to German interference in Italy.","zh":"該選項指德國對意大利的干預。"},{"en":"Interference in something means unwanted involvement that affects or controls it.","zh":"“Interference in” 某事指不受歡迎的介入，並影響或控制它。"},{"en":"Parents may complain about interference in school decisions if outsiders pressure teachers unfairly.","zh":"如果外部人士不公平地向老師施壓，家長可能投訴對學校決策的干預。"},{"en":"If a foreign power interferes in another country, local people may feel their freedom is threatened.","zh":"如果外國勢力干預另一個國家，當地人可能感到自由受威脅。"},{"en":"The phrase usually suggests unwelcome influence.","zh":"這個短語通常暗示不受歡迎的影響。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":18},{"front":"be influenced by","meaning":"受……影響","examples":[{"en":"The option asks whether his beliefs were influenced by past experiences.","zh":"該選項問他的信念是否受過去經歷影響。"},{"en":"To be influenced by something means to be shaped or affected by it.","zh":"“Be influenced by” 某事指被它塑造或影響。"},{"en":"A student’s career choice may be influenced by a favourite teacher.","zh":"學生的職業選擇可能受喜愛的老師影響。"},{"en":"If someone has socialised with persecuted people, their beliefs may be influenced by that contact.","zh":"如果某人曾與受迫害者交往，其信念可能受該接觸影響。"},{"en":"The phrase shows cause or shaping force.","zh":"這個短語顯示原因或塑造力量。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":18},{"front":"draw conclusions from","meaning":"從……得出結論","examples":[{"en":"He may have drawn conclusions from socialising with certain groups.","zh":"他可能從與某些群體交往中得出結論。"},{"en":"To draw conclusions from something means to form opinions or understanding based on it.","zh":"“Draw conclusions from” 某事指根據它形成意見或理解。"},{"en":"A doctor draws conclusions from symptoms, tests, and patient history.","zh":"醫生從症狀、檢查和病史得出結論。"},{"en":"If someone meets persecuted people personally, they may conclude that propaganda is false.","zh":"如果某人親身認識受迫害者，可能得出宣傳是虛假的結論。"},{"en":"The phrase describes reasoning from evidence or experience.","zh":"這個短語描述從證據或經驗中推理。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":18},{"front":"socialising with certain groups","meaning":"與某些群體交往","examples":[{"en":"The option refers to his socialising with certain groups of people.","zh":"該選項指他與某些群體交往。"},{"en":"Socialising with certain groups means spending friendly time with particular communities or types of people.","zh":"“Socialising with certain groups” 指與特定社群或類型的人友好相處。"},{"en":"A student who socialises with international classmates may learn new customs and viewpoints.","zh":"與國際同學交往的學生可能學到新習俗和觀點。"},{"en":"If someone socialises with a targeted minority group, they may reject stereotypes about them.","zh":"如果某人與受針對的少數群體交往，可能拒絕關於他們的刻板印象。"},{"en":"The phrase focuses on personal contact and interaction.","zh":"這個短語強調個人接觸和互動。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":18},{"front":"in keeping with","meaning":"與……一致","examples":[{"en":"The option asks whether his views were in keeping with government ideology.","zh":"該選項問他的觀點是否與政府意識形態一致。"},{"en":"In keeping with something means consistent with or matching it.","zh":"“In keeping with” 某事指與它一致或相符。"},{"en":"A school’s punishment should be in keeping with its values of fairness and respect.","zh":"學校的懲罰應與其公平和尊重的價值觀一致。"},{"en":"If someone’s views are not in keeping with a regime’s ideology, they may become a target.","zh":"如果某人的觀點與政權意識形態不一致，他可能成為目標。"},{"en":"The phrase describes agreement or consistency.","zh":"這個短語描述一致或相符。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":18},{"front":"stated views","meaning":"公開表明的觀點","examples":[{"en":"The option refers to the stated views of the German and Italian governments.","zh":"該選項指德國和意大利政府公開表明的觀點。"},{"en":"Stated views are opinions or positions that have been publicly expressed.","zh":"公開表明的觀點是已公開表達的意見或立場。"},{"en":"A company’s stated views on sustainability may appear on its website.","zh":"公司關於可持續發展的公開觀點可能出現在其網站上。"},{"en":"If stated views are hateful, they can reveal the direction of future policy.","zh":"如果公開表明的觀點充滿仇恨，就可能揭示未來政策方向。"},{"en":"The phrase refers to openly declared beliefs.","zh":"這個短語指公開宣示的信念。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":18},{"front":"equally hostile and extreme","meaning":"同樣敵對和極端","examples":[{"en":"The option suggests that his beliefs were equally hostile and extreme.","zh":"該選項暗示他的信念同樣敵對和極端。"},{"en":"Equally hostile and extreme means just as aggressive, hateful, or radical as another view.","zh":"“Equally hostile and extreme” 指與另一觀點同樣具攻擊性、仇恨或激進。"},{"en":"Two groups may become equally hostile if both refuse to listen or compromise.","zh":"如果兩個群體都拒絕聆聽或妥協，可能變得同樣敵對。"},{"en":"If one person resists injustice, that does not mean their beliefs are equally extreme.","zh":"如果一個人抵抗不公義，這不代表其信念同樣極端。"},{"en":"The phrase compares the severity of two attitudes.","zh":"這個短語比較兩種態度的嚴重程度。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":18},{"front":"two correct answers","meaning":"兩個正確答案","examples":[{"en":"The question states that there are two correct answers.","zh":"題目說有兩個正確答案。"},{"en":"Two correct answers means exactly two options should be chosen.","zh":"兩個正確答案指應正正選擇兩個選項。"},{"en":"In a reading test, students should not choose three answers if the instruction says two.","zh":"在閱讀測驗中，如果指示說兩個，學生就不應選三個答案。"},{"en":"If there are two correct answers, both must be supported by the passage.","zh":"如果有兩個正確答案，兩者都必須得到文章支持。"},{"en":"The phrase gives an important exam instruction.","zh":"這個短語給出重要考試指示。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":18},{"front":"conceal people","meaning":"藏匿人們","examples":[{"en":"The question asks where O’Flaherty concealed people.","zh":"題目問 O’Flaherty 在哪裡藏匿人們。"},{"en":"To conceal people means to hide them so others cannot find them.","zh":"“Conceal people” 指把人藏起來，使別人找不到。"},{"en":"During war, families may conceal neighbours in cellars or back rooms.","zh":"戰爭期間，家庭可能在地窖或後房藏匿鄰居。"},{"en":"If people are concealed well, searching authorities may fail to discover them.","zh":"如果人們被妥善藏匿，搜查當局可能無法發現他們。"},{"en":"The phrase describes hiding people for protection.","zh":"這個短語描述為保護而把人藏起來。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":19},{"front":"take someone into one’s care","meaning":"把某人納入自己的保護之下","examples":[{"en":"O’Flaherty took many threatened people into his care.","zh":"O’Flaherty 把許多受威脅的人納入自己的保護之下。"},{"en":"To take someone into one’s care means to accept responsibility for protecting and looking after them.","zh":"“Take someone into one’s care” 指接受保護和照顧某人的責任。"},{"en":"A relative may take a child into their care when the parents are ill.","zh":"當父母生病時，親戚可能把孩子納入自己照顧之下。"},{"en":"If someone takes refugees into their care, they must provide safety, food, and support.","zh":"如果某人把難民納入自己的保護之下，就必須提供安全、食物和支援。"},{"en":"The phrase shows protection and responsibility.","zh":"這個短語顯示保護和責任。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":19},{"front":"the place at which","meaning":"……所在的地方","examples":[{"en":"The option refers to the place at which he was studying.","zh":"該選項指他求學所在的地方。"},{"en":"The place at which means the place where something happened.","zh":"“The place at which” 指某事發生所在的地方。"},{"en":"A student should write the place at which the experiment was carried out.","zh":"學生應寫出實驗進行所在的地方。"},{"en":"If a question asks for the place at which someone studied, it wants a location, not a reason.","zh":"如果題目問某人求學所在的地方，它要的是地點，而不是原因。"},{"en":"The phrase is a formal way to say “where.”","zh":"這個短語是 “where” 的正式說法。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":19},{"front":"former college","meaning":"舊學院；曾就讀的學院","examples":[{"en":"The option mentions a former college.","zh":"該選項提到一所舊學院。"},{"en":"A former college is a college someone attended in the past.","zh":"舊學院是某人過去曾就讀的學院。"},{"en":"A graduate may return to a former college to give a speech to new students.","zh":"畢業生可能回到曾就讀的學院，向新生演講。"},{"en":"If a former college becomes a hiding place, an old connection is used for rescue.","zh":"如果舊學院成為藏身之處，舊關係就被用於救援。"},{"en":"The phrase refers to an institution from someone’s earlier life.","zh":"這個短語指某人早年生活中的機構。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":19},{"front":"be converted into","meaning":"被改建成","examples":[{"en":"The option describes a college that had been converted into apartments.","zh":"該選項描述一所被改建成住宅單位的學院。"},{"en":"To be converted into something means to be changed into a different form or use.","zh":"“Be converted into” 某物指被改變成不同形式或用途。"},{"en":"An old factory may be converted into flats or art studios.","zh":"舊工廠可能被改建成住宅或藝術工作室。"},{"en":"If a building is converted into apartments, its original purpose has changed.","zh":"如果建築被改建成住宅單位，其原本用途就已改變。"},{"en":"The phrase describes transformation of use or structure.","zh":"這個短語描述用途或結構的轉變。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":19},{"front":"officially lived","meaning":"官方居住","examples":[{"en":"The option refers to the place where he officially lived.","zh":"該選項指他官方居住的地方。"},{"en":"Officially lived means lived there as one’s recognised or formal residence.","zh":"“Officially lived” 指以被承認或正式住所身份住在那裡。"},{"en":"A diplomat may officially live in an embassy residence while also travelling often.","zh":"外交官可能官方居住在大使館住所，同時經常外出旅行。"},{"en":"If someone officially lives in a protected area, that address may give them special status.","zh":"如果某人官方居住在受保護地區，該地址可能給予他特殊地位。"},{"en":"The phrase contrasts formal residence with temporary hiding places.","zh":"這個短語把正式住所與臨時藏身之處作對比。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":19},{"front":"residences of religious groups","meaning":"宗教團體的住所","examples":[{"en":"He used residences of religious groups as hiding places.","zh":"他使用宗教團體的住所作為藏身之處。"},{"en":"Residences of religious groups are buildings where monks, nuns, priests, or religious communities live.","zh":"宗教團體的住所是修士、修女、神父或宗教社群居住的建築。"},{"en":"A convent or monastery can be a residence of a religious group.","zh":"女修道院或男修道院可以是宗教團體的住所。"},{"en":"If such residences shelter people, religious communities become part of humanitarian protection.","zh":"如果這些住所收容人，宗教社群就成為人道保護的一部分。"},{"en":"The phrase identifies living places linked to faith communities.","zh":"這個短語指出與信仰社群相關的居住地方。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":19},{"front":"old friends of his","meaning":"他的舊友","examples":[{"en":"The option refers to the houses of old friends of his.","zh":"該選項指他的舊友的房子。"},{"en":"Old friends of his means people who had known him for a long time.","zh":"“Old friends of his” 指認識他很久的人。"},{"en":"A person may trust old friends of his when a situation becomes risky.","zh":"當情況變得危險，一個人可能信任他的舊友。"},{"en":"If old friends help in a crisis, past loyalty becomes practical protection.","zh":"如果舊友在危機中幫忙，過去的忠誠就變成實際保護。"},{"en":"The phrase highlights long-standing personal relationships.","zh":"這個短語突出長久私人關係。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":19},{"front":"impressive aspect","meaning":"令人印象深刻的一面","examples":[{"en":"The question asks about an impressive aspect of the helpers’ actions.","zh":"題目問助手行動中令人印象深刻的一面。"},{"en":"An impressive aspect is a part of something that causes admiration.","zh":"令人印象深刻的一面是某事中令人欽佩的部分。"},{"en":"An impressive aspect of a student’s speech may be how calmly they answer difficult questions.","zh":"學生演講中令人印象深刻的一面，可能是他如何冷靜回答難題。"},{"en":"If helpers risk their lives, that risk is an impressive aspect of their courage.","zh":"如果助手冒生命危險，那種風險就是其勇氣中令人印象深刻的一面。"},{"en":"The phrase points to what is especially admirable.","zh":"這個短語指出尤其令人欽佩之處。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":19},{"front":"highlight","meaning":"強調","examples":[{"en":"The writer highlights the risks taken by O’Flaherty’s helpers.","zh":"作者強調 O’Flaherty 的助手所承擔的風險。"},{"en":"To highlight something means to emphasise it or draw attention to it.","zh":"“Highlight” 某事指強調它或吸引注意到它。"},{"en":"A teacher may highlight common mistakes before students write another essay.","zh":"老師可能在學生再寫作文前強調常見錯誤。"},{"en":"If a writer highlights danger, readers understand the helpers’ courage more clearly.","zh":"如果作者強調危險，讀者就更清楚理解助手的勇氣。"},{"en":"The phrase shows what the writer wants readers to notice.","zh":"這個短語顯示作者想讀者注意甚麼。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":19},{"front":"be eager to help","meaning":"熱切想幫忙","examples":[{"en":"The option asks whether the helpers were eager to help him.","zh":"該選項問助手是否熱切想幫助他。"},{"en":"To be eager to help means to be very willing and ready to assist.","zh":"“Be eager to help” 指非常願意並準備好提供協助。"},{"en":"A kind classmate may be eager to help a new student find the right classroom.","zh":"友善同學可能熱切想幫新生找到正確課室。"},{"en":"If helpers are eager to help, a rescue effort can grow quickly.","zh":"如果助手熱切想幫忙，救援工作就能迅速擴大。"},{"en":"The phrase describes strong willingness.","zh":"這個短語描述強烈意願。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":19},{"front":"be willing to volunteer","meaning":"願意自願幫忙","examples":[{"en":"The option asks how many people were willing to volunteer.","zh":"該選項問有多少人願意自願幫忙。"},{"en":"To be willing to volunteer means to be ready to help without being forced or paid.","zh":"“Be willing to volunteer” 指願意在沒有被迫或受薪下提供幫助。"},{"en":"Many parents may be willing to volunteer at a school fair.","zh":"許多家長可能願意在學校賣物會自願幫忙。"},{"en":"If people are willing to volunteer in danger, their courage is especially clear.","zh":"如果人們願意在危險中自願幫忙，其勇氣尤其清楚。"},{"en":"The phrase combines free choice with service.","zh":"這個短語結合自由選擇與服務。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":20},{"front":"disregard for","meaning":"對……不顧；無視","examples":[{"en":"The option refers to their disregard for possible consequences.","zh":"該選項指他們對可能後果不顧。"},{"en":"Disregard for something means lack of concern about it or refusal to let it control one’s actions.","zh":"“Disregard for” 某事指不在意它，或拒絕讓它控制自己的行動。"},{"en":"A driver’s disregard for traffic lights can put others in danger.","zh":"司機無視交通燈可以使他人陷入危險。"},{"en":"If helpers show disregard for personal danger, they may be acting from deep moral commitment.","zh":"如果助手不顧個人危險，可能是出於深厚道德承擔。"},{"en":"The phrase can be negative or admiring depending on context.","zh":"這個短語可帶負面或讚賞意味，取決於語境。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":20},{"front":"possible consequences","meaning":"可能後果","examples":[{"en":"The helpers faced serious possible consequences if they were caught.","zh":"如果被抓到，助手們面對嚴重可能後果。"},{"en":"Possible consequences are results that may happen after an action.","zh":"可能後果是行動之後可能發生的結果。"},{"en":"A student should consider possible consequences before posting angry comments online.","zh":"學生在網上發布憤怒留言前，應考慮可能後果。"},{"en":"If rescuers are caught, possible consequences may include arrest, punishment, or death.","zh":"如果救援者被抓到，可能後果包括被捕、懲罰或死亡。"},{"en":"The phrase asks what could happen next.","zh":"這個短語問接下來可能發生甚麼。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":20},{"front":"being caught","meaning":"被抓到","examples":[{"en":"Being caught could have cost the helpers their lives.","zh":"被抓到可能令助手喪命。"},{"en":"Being caught means being discovered while doing something hidden or forbidden.","zh":"“Being caught” 指在做隱藏或被禁止的事情時被發現。"},{"en":"A student fears being caught if they break a school rule.","zh":"學生違反校規時，可能害怕被抓到。"},{"en":"In wartime rescue work, being caught could mean imprisonment or execution.","zh":"在戰時救援工作中，被抓到可能意味着監禁或處決。"},{"en":"The phrase focuses on the danger of discovery.","zh":"這個短語強調被發現的危險。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":20},{"front":"coordinate and work together","meaning":"協調合作","examples":[{"en":"The option refers to the helpers’ ability to coordinate and work together.","zh":"該選項指助手協調合作的能力。"},{"en":"To coordinate and work together means to organise actions jointly so that people support one another effectively.","zh":"“Coordinate and work together” 指共同組織行動，使人們有效互相支援。"},{"en":"Students must coordinate and work together when preparing a group presentation.","zh":"學生準備小組匯報時，必須協調合作。"},{"en":"If rescue helpers coordinate well, food, shelter, and travel can be arranged safely.","zh":"如果救援助手協調良好，食物、庇護和交通就能安全安排。"},{"en":"The phrase stresses teamwork and organisation.","zh":"這個短語強調團隊合作和組織。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":20},{"front":"avoid being identified","meaning":"避免被認出","examples":[{"en":"O’Flaherty used disguises to avoid being identified.","zh":"O’Flaherty 使用變裝來避免被認出。"},{"en":"To avoid being identified means to prevent others from recognising who you are.","zh":"“Avoid being identified” 指防止別人認出自己是誰。"},{"en":"A witness may hide their face to avoid being identified by criminals.","zh":"證人可能遮住臉，以避免被罪犯認出。"},{"en":"If rescuers avoid being identified, they can continue their work without immediate arrest.","zh":"如果救援者避免被認出，就能在不立即被捕下繼續工作。"},{"en":"The phrase describes protecting one’s identity from discovery.","zh":"這個短語描述保護身份不被發現。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":20},{"front":"writer’s attitude towards","meaning":"作者對……的態度","examples":[{"en":"The question asks about the writer’s attitude towards O’Flaherty.","zh":"題目問作者對 O’Flaherty 的態度。"},{"en":"A writer’s attitude towards someone is the writer’s feeling, opinion, or tone about that person.","zh":"作者對某人的態度，是作者對該人的感受、意見或語氣。"},{"en":"In reading exams, words like “brave” or “foolish” reveal the writer’s attitude.","zh":"在閱讀考試中，“brave” 或 “foolish” 等詞揭示作者態度。"},{"en":"If the writer praises courage and sacrifice, the attitude is admiring.","zh":"如果作者稱讚勇氣和犧牲，態度就是敬佩。"},{"en":"The phrase helps students analyse tone.","zh":"這個短語幫助學生分析語氣。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":20},{"front":"life and achievements","meaning":"人生與成就","examples":[{"en":"The question focuses on O’Flaherty’s life and achievements.","zh":"題目集中於 O’Flaherty 的人生與成就。"},{"en":"Life and achievements means a person’s experiences and the important things they accomplished.","zh":"人生與成就是指一個人的經歷和其完成的重要事情。"},{"en":"A biography usually describes a leader’s childhood, work, struggles, and achievements.","zh":"傳記通常描述領袖的童年、工作、掙扎和成就。"},{"en":"If someone’s achievements saved lives, their life story becomes historically important.","zh":"如果某人的成就拯救生命，其人生故事就變得具歷史重要性。"},{"en":"The phrase combines personal history with successful actions.","zh":"這個短語結合個人歷史與成功行動。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":20},{"front":"bravery and determination","meaning":"勇氣和決心","examples":[{"en":"The writer admires O’Flaherty’s bravery and determination.","zh":"作者欣賞 O’Flaherty 的勇氣和決心。"},{"en":"Bravery and determination are courage and firm commitment to continue despite danger or difficulty.","zh":"勇氣和決心是在危險或困難中仍繼續的膽量和堅定投入。"},{"en":"A student shows bravery and determination when they keep speaking English after being laughed at.","zh":"學生被取笑後仍繼續說英語，就是展現勇氣和決心。"},{"en":"If someone continues rescue work under threat, bravery and determination are clear.","zh":"如果某人在威脅下繼續救援工作，勇氣和決心就很清楚。"},{"en":"The phrase praises moral strength and persistence.","zh":"這個短語稱讚道德力量和堅持。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":20},{"front":"stop injustice","meaning":"制止不公義","examples":[{"en":"O’Flaherty was determined to stop injustice.","zh":"O’Flaherty 決心制止不公義。"},{"en":"To stop injustice means to prevent unfair or cruel treatment from continuing.","zh":"“Stop injustice” 指防止不公平或殘酷對待繼續。"},{"en":"A student can help stop injustice by reporting bullying and supporting the victim.","zh":"學生可以透過舉報欺凌和支持受害者來幫助制止不公義。"},{"en":"If people refuse to ignore cruelty, they may help stop injustice in their community.","zh":"如果人們拒絕忽視殘酷行為，可能幫助社區制止不公義。"},{"en":"The phrase describes active resistance to unfairness.","zh":"這個短語描述對不公平的積極抵抗。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":20},{"front":"loyalty to","meaning":"對……的忠誠","examples":[{"en":"The option refers to O’Flaherty’s loyalty to the Vatican and his church.","zh":"該選項指 O’Flaherty 對梵蒂岡和教會的忠誠。"},{"en":"Loyalty to someone or something means faithful support and commitment.","zh":"對某人或某事的忠誠指忠實支持和投入。"},{"en":"A worker may show loyalty to a company by staying during difficult times.","zh":"員工可能透過在困難時期留下來，顯示對公司的忠誠。"},{"en":"If loyalty to an institution is strong, a person may act to protect its values.","zh":"如果對機構的忠誠很強，一個人可能行動保護其價值。"},{"en":"The phrase describes faithfulness to a person, place, or organisation.","zh":"這個短語描述對人、地方或組織的忠實。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":20},{"front":"superior speech-maker","meaning":"更出色的演說家","examples":[{"en":"The option compares Margaret Mead as a superior speech-maker.","zh":"該選項把 Margaret Mead 比較為更出色的演說家。"},{"en":"A superior speech-maker is someone better at giving speeches than another person.","zh":"更出色的演說家是比另一人更擅長演講的人。"},{"en":"A speaker may be superior because they use clear examples and a calm voice.","zh":"演說者可能因使用清晰例子和冷靜聲音而更出色。"},{"en":"If a question mentions a superior speech-maker, students should check whether the passage actually compares speaking ability.","zh":"如果題目提到更出色的演說家，學生應檢查文章是否真的比較演講能力。"},{"en":"The phrase describes comparative skill in public speaking.","zh":"這個短語描述公開演說方面的比較能力。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":21},{"front":"get the recognition someone deserves","meaning":"得到某人應有的認可","examples":[{"en":"The option asks whether O’Flaherty got the recognition he deserved.","zh":"該選項問 O’Flaherty 是否得到他應有的認可。"},{"en":"To get the recognition someone deserves means to receive fair praise or honour for what they did.","zh":"“Get the recognition someone deserves” 指某人因其所做之事得到公平讚揚或榮譽。"},{"en":"A quiet helper may not get the recognition they deserve if others take credit.","zh":"如果別人搶功，安靜的幫助者可能得不到應有的認可。"},{"en":"If a rescuer saves many lives, public honours may help give deserved recognition.","zh":"如果救援者拯救許多生命，公眾榮譽可能幫助給予應有認可。"},{"en":"The phrase connects achievement with fair acknowledgement.","zh":"這個短語把成就與公平承認連繫起來。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":21},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Candidates complete the summary below using words from the passage.","zh":"考生使用文章中的詞語完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the summary under the question.","zh":"“Complete the summary below” 指填寫題目下方摘要中的缺漏詞語。"},{"en":"Students should read the whole summary before choosing answers from the passage.","zh":"學生應先閱讀整段摘要，再從文章選擇答案。"},{"en":"If the word limit is strict, even a correct idea may be wrong if too many words are used.","zh":"如果字數限制嚴格，即使意思正確，用太多字也可能錯。"},{"en":"The phrase is a common reading-test instruction.","zh":"這個短語是常見閱讀測驗指示。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":21},{"front":"no more than two words","meaning":"不多於兩個字","examples":[{"en":"The instructions allow no more than two words from the passage.","zh":"指示允許使用文章中不多於兩個字。"},{"en":"No more than two words means the answer must contain two words or fewer.","zh":"“No more than two words” 指答案必須包含兩個字或更少。"},{"en":"If the correct answer is “concentration camps,” it fits the two-word limit.","zh":"如果正確答案是 “concentration camps”，它符合兩字限制。"},{"en":"Students may lose marks if they add an unnecessary third word.","zh":"如果學生加入不必要的第三個字，可能會失分。"},{"en":"The phrase gives a strict exam answer limit.","zh":"這個短語給出嚴格考試答案限制。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":21},{"front":"a moral, determined and resourceful man","meaning":"有道德、堅定而足智多謀的人","examples":[{"en":"The summary describes O’Flaherty as a moral, determined and resourceful man.","zh":"摘要把 O’Flaherty 描述為有道德、堅定而足智多謀的人。"},{"en":"A moral, determined and resourceful man is someone guided by right and wrong, persistent, and clever at solving problems.","zh":"有道德、堅定而足智多謀的人，是受是非引導、堅持不懈且善於解決問題的人。"},{"en":"A community leader who protects neighbours during danger may be moral, determined and resourceful.","zh":"在危險中保護鄰居的社區領袖，可能是有道德、堅定而足智多謀的人。"},{"en":"If a person rescues others under threat, they need both courage and practical intelligence.","zh":"如果一個人在威脅下救助他人，就需要勇氣和實際智慧。"},{"en":"The phrase praises character, persistence, and problem-solving ability.","zh":"這個短語稱讚品格、堅持和解難能力。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":21},{"front":"at loggerheads with","meaning":"與……嚴重不和；與……相衝","examples":[{"en":"O’Flaherty’s beliefs were at loggerheads with fascist ideology.","zh":"O’Flaherty 的信念與法西斯意識形態嚴重相衝。"},{"en":"To be at loggerheads with something means to be in strong disagreement or conflict with it.","zh":"“Be at loggerheads with” 某事指與它有強烈分歧或衝突。"},{"en":"Parents and teenagers may be at loggerheads over screen time rules.","zh":"父母和青少年可能在螢幕時間規則上嚴重不和。"},{"en":"If a person values justice, they may be at loggerheads with a hateful political ideology.","zh":"如果一個人重視公義，就可能與仇恨政治意識形態相衝。"},{"en":"The phrase describes serious opposition.","zh":"這個短語描述嚴重對立。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":21},{"front":"mindless propaganda","meaning":"盲目的宣傳","examples":[{"en":"He saw fascist ideology as mindless propaganda.","zh":"他把法西斯意識形態視為盲目的宣傳。"},{"en":"Mindless propaganda is messaging that pushes an idea without honest thought, evidence, or moral judgement.","zh":"盲目的宣傳是沒有誠實思考、證據或道德判斷，只是推動某想法的訊息。"},{"en":"A campaign full of slogans but no facts may feel like mindless propaganda.","zh":"充滿口號卻沒有事實的宣傳活動，可能感覺像盲目的宣傳。"},{"en":"If propaganda tells people to hate without thinking, it can become extremely dangerous.","zh":"如果宣傳叫人不思考地仇恨，就可以變得極其危險。"},{"en":"The phrase criticises empty and harmful political messaging.","zh":"這個短語批評空洞而有害的政治訊息。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":21},{"front":"take it upon oneself to","meaning":"主動承擔起……","examples":[{"en":"He took it upon himself to combat injustice.","zh":"他主動承擔起對抗不公義的責任。"},{"en":"To take it upon oneself to do something means to accept responsibility for doing it without being asked.","zh":"“Take it upon oneself to” 做某事指在沒有人要求下接受做該事的責任。"},{"en":"A student may take it upon herself to welcome a lonely new classmate.","zh":"學生可能主動承擔起歡迎孤單新同學的責任。"},{"en":"If no authority helps victims, a brave person may take responsibility personally.","zh":"如果沒有當局幫助受害者，勇敢的人可能親自承擔責任。"},{"en":"The phrase shows voluntary responsibility and initiative.","zh":"這個短語顯示自願責任和主動性。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":21},{"front":"combat injustices","meaning":"對抗不公義","examples":[{"en":"O’Flaherty tried to combat the injustices committed against minority groups.","zh":"O’Flaherty 嘗試對抗施加於少數群體的不公義。"},{"en":"To combat injustices means to fight against unfair or cruel treatment.","zh":"“Combat injustices” 指對抗不公平或殘酷對待。"},{"en":"A lawyer may combat injustices by defending people who cannot afford legal help.","zh":"律師可能透過為負擔不起法律援助的人辯護來對抗不公義。"},{"en":"If citizens combat injustice, they challenge systems that harm vulnerable people.","zh":"如果公民對抗不公義，就是挑戰傷害弱勢者的制度。"},{"en":"The phrase describes active moral resistance.","zh":"這個短語描述積極道德抵抗。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":21},{"front":"be perpetrated against","meaning":"被施加於……","examples":[{"en":"Injustices were being perpetrated against Jews and other minority groups.","zh":"不公義正被施加於猶太人和其他少數群體。"},{"en":"To be perpetrated against someone means to be committed or carried out against them, usually as a harmful act.","zh":"“Be perpetrated against” 某人指有害行為被實施於他們身上。"},{"en":"Violence perpetrated against civilians should never be treated as normal.","zh":"施加於平民的暴力絕不應被視為正常。"},{"en":"If injustice is perpetrated against a group, that group is being deliberately harmed.","zh":"如果不公義被施加於一個群體，該群體就是被蓄意傷害。"},{"en":"The phrase is formal and often used for crimes or abuses.","zh":"這個短語較正式，常用於罪行或虐待。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":21},{"front":"at the hands of","meaning":"在……手中；由……造成","examples":[{"en":"The victims suffered at the hands of the police.","zh":"受害者在警察手中受苦。"},{"en":"At the hands of someone means caused by or done by that person or group.","zh":"“At the hands of” 某人指由該人或群體造成或做出。"},{"en":"Workers may suffer at the hands of dishonest employers if labour laws are ignored.","zh":"如果勞工法被忽視，工人可能在不誠實僱主手中受苦。"},{"en":"If victims suffer at the hands of authorities, the abuse comes from people with power.","zh":"如果受害者在當局手中受苦，虐待就是來自有權力的人。"},{"en":"The phrase identifies who caused the harm.","zh":"這個短語指出傷害由誰造成。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":21},{"front":"acting on orders from above","meaning":"按上級命令行事","examples":[{"en":"The police were acting on orders from above.","zh":"警察按上級命令行事。"},{"en":"Acting on orders from above means following instructions from higher authorities.","zh":"“Acting on orders from above” 指遵從更高當局的指示。"},{"en":"A junior employee may act on orders from above even if they dislike the decision.","zh":"初級員工即使不喜歡某決定，也可能按上級命令行事。"},{"en":"If police act on unjust orders from above, responsibility may reach higher officials too.","zh":"如果警察按不公上級命令行事，責任也可能延伸至高級官員。"},{"en":"The phrase shows that actions were directed by superiors.","zh":"這個短語顯示行動由上級指揮。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":22},{"front":"round someone up","meaning":"圍捕某人","examples":[{"en":"The police were rounding minority groups up.","zh":"警察正在圍捕少數群體。"},{"en":"To round people up means to gather or arrest them as a group, often by force.","zh":"“Round people up” 指把人作為一群聚集或拘捕，通常以武力進行。"},{"en":"Police may round up suspects after a serious incident.","zh":"嚴重事件後，警察可能圍捕嫌疑人。"},{"en":"If a regime rounds up minority groups, people may be taken away without fair process.","zh":"如果政權圍捕少數群體，人們可能在沒有公平程序下被帶走。"},{"en":"The phrase often suggests mass arrest or forced collection.","zh":"這個短語常暗示大規模拘捕或強制集合。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":22},{"front":"be sent to","meaning":"被送往","examples":[{"en":"The groups were being sent to concentration camps.","zh":"這些群體正被送往集中營。"},{"en":"To be sent to a place means to be taken or ordered to go there.","zh":"“Be sent to” 某地指被帶到或被命令前往該地。"},{"en":"A patient may be sent to a specialist hospital for treatment.","zh":"病人可能被送往專科醫院接受治療。"},{"en":"If people are sent to camps by force, they lose control over their own safety.","zh":"如果人們被強行送往營地，就失去對自身安全的控制。"},{"en":"The phrase can be neutral, but here it describes forced removal.","zh":"這個短語可以是中性，但在此描述強制移送。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":22},{"front":"initially","meaning":"起初","examples":[{"en":"Initially, O’Flaherty used familiar places as hideouts.","zh":"起初，O’Flaherty 使用熟悉的地方作為藏身地點。"},{"en":"Initially means at the beginning or in the first stage.","zh":"“Initially” 指在開始時或第一階段。"},{"en":"Initially, a new student may feel nervous before making friends.","zh":"起初，新學生在交朋友前可能感到緊張。"},{"en":"If a plan initially uses familiar places, later danger may force it to expand.","zh":"如果計劃起初使用熟悉地方，後來的危險可能迫使它擴展。"},{"en":"The word introduces the starting point of a process.","zh":"這個詞引出過程的起點。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":22},{"front":"familiar places","meaning":"熟悉的地方","examples":[{"en":"O’Flaherty first used familiar places as hideouts.","zh":"O’Flaherty 最初使用熟悉的地方作為藏身地點。"},{"en":"Familiar places are locations someone already knows well.","zh":"熟悉的地方是某人已經很了解的位置。"},{"en":"A child may feel safer in familiar places such as home, school, or a grandparent’s house.","zh":"孩子可能在家、學校或祖父母家等熟悉地方感到更安全。"},{"en":"If rescuers use familiar places, they may know entrances, exits, and trusted people nearby.","zh":"如果救援者使用熟悉地方，可能知道入口、出口和附近可信的人。"},{"en":"The phrase suggests known and trusted locations.","zh":"這個短語暗示已知且可信的地點。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":22},{"front":"start to deteriorate","meaning":"開始惡化","examples":[{"en":"The situation started to deteriorate.","zh":"情況開始惡化。"},{"en":"To start to deteriorate means to begin becoming worse.","zh":"“Start to deteriorate” 指開始變差。"},{"en":"A student’s health may start to deteriorate if they sleep too little for many weeks.","zh":"如果學生連續多週睡得太少，健康可能開始惡化。"},{"en":"If a political situation deteriorates, danger and uncertainty increase.","zh":"如果政治局勢惡化，危險和不確定會增加。"},{"en":"The phrase marks the beginning of decline.","zh":"這個短語標示衰退的開始。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":22},{"front":"be in need of assistance","meaning":"需要協助","examples":[{"en":"More and more people were in need of assistance.","zh":"越來越多人需要協助。"},{"en":"To be in need of assistance means to require help.","zh":"“Be in need of assistance” 指需要幫助。"},{"en":"An elderly neighbour may be in need of assistance after a fall.","zh":"老年鄰居跌倒後可能需要協助。"},{"en":"If more people need assistance during a crisis, helpers must expand their support network.","zh":"如果危機中更多人需要協助，幫助者就必須擴大支援網絡。"},{"en":"The phrase is a formal way to say someone needs help.","zh":"這個短語是 “需要幫助” 的正式說法。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":22},{"front":"call upon","meaning":"求助於；請求……幫忙","examples":[{"en":"He was forced to call upon old friends for help.","zh":"他被迫向舊友求助。"},{"en":"To call upon someone means to ask them formally or seriously for help.","zh":"“Call upon” 某人指正式或認真地請求他幫忙。"},{"en":"A principal may call upon teachers to support students after a crisis.","zh":"校長可能在危機後請求老師支援學生。"},{"en":"If danger grows, leaders may call upon trusted people to act quickly.","zh":"如果危險增加，領袖可能請求可信的人迅速行動。"},{"en":"The phrase suggests an important request for assistance.","zh":"這個短語暗示重要的求助請求。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":22},{"front":"show bravery","meaning":"展現勇氣","examples":[{"en":"His friends showed bravery by helping him.","zh":"他的朋友透過幫助他展現勇氣。"},{"en":"To show bravery means to act courageously despite fear or danger.","zh":"“Show bravery” 指即使害怕或危險仍勇敢行動。"},{"en":"A student shows bravery when they report bullying even though they feel afraid.","zh":"學生即使害怕仍舉報欺凌，就是展現勇氣。"},{"en":"If people help others under a violent regime, their bravery is shown through action.","zh":"如果人們在暴力政權下幫助他人，其勇氣就透過行動顯現。"},{"en":"The phrase describes courage made visible.","zh":"這個短語描述被看見的勇氣。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":22},{"front":"cost someone their life","meaning":"令某人喪命","examples":[{"en":"Getting caught might have cost them their lives.","zh":"被抓到可能令他們喪命。"},{"en":"To cost someone their life means to cause that person to die.","zh":"“Cost someone their life” 指導致某人死亡。"},{"en":"Ignoring safety rules in a dangerous workplace can cost workers their lives.","zh":"在危險工作場所忽視安全規則，可以令工人喪命。"},{"en":"If helpers were caught by fascists, the punishment could have been fatal.","zh":"如果幫助者被法西斯分子抓到，懲罰可能是致命的。"},{"en":"The phrase describes the highest possible cost.","zh":"這個短語描述最高可能代價。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":22},{"front":"extend assistance to","meaning":"將援助擴展至","examples":[{"en":"He extended his assistance to downed Allied airmen.","zh":"他將援助擴展至被擊落的盟軍飛行員。"},{"en":"To extend assistance to someone means to widen help so that it also reaches that person or group.","zh":"“Extend assistance to” 某人指擴大幫助，使它也觸及該人或群體。"},{"en":"A school may extend assistance to families who cannot afford lunch.","zh":"學校可能將援助擴展至負擔不起午餐的家庭。"},{"en":"If a rescue network extends assistance to more people, it needs more places, food, and helpers.","zh":"如果救援網絡將援助擴展至更多人，就需要更多地點、食物和助手。"},{"en":"The phrase describes broadening support.","zh":"這個短語描述擴大支援。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":22},{"front":"be detained by","meaning":"被……拘留","examples":[{"en":"British soldiers had been detained by the Germans.","zh":"英國士兵曾被德國人拘留。"},{"en":"To be detained by someone means to be held or kept under their control, often by authority.","zh":"“Be detained by” 某人指被其扣留或置於其控制之下，通常由當局執行。"},{"en":"A traveller may be detained by airport officials for questioning.","zh":"旅客可能被機場官員拘留問話。"},{"en":"If soldiers are detained by the enemy, they become prisoners of war.","zh":"如果士兵被敵方拘留，就成為戰俘。"},{"en":"The phrase describes being held and not free to leave.","zh":"這個短語描述被扣留而不能自由離開。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":23},{"front":"by the war’s end","meaning":"到戰爭結束時","examples":[{"en":"By the war’s end, thousands of lives had been spared.","zh":"到戰爭結束時，數以千計生命得以保全。"},{"en":"By the war’s end means by the time the war finished.","zh":"“By the war’s end” 指到戰爭結束的時候。"},{"en":"By the school year’s end, students may have built stronger writing habits.","zh":"到學年結束時，學生可能已建立更強寫作習慣。"},{"en":"If thousands of lives were spared by the war’s end, the rescue effort had lasting results.","zh":"如果到戰爭結束時數以千計生命得以保全，救援努力就有持久成果。"},{"en":"The phrase gives a time point for measuring what had happened.","zh":"這個短語給出衡量已發生事情的時間點。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":23},{"front":"lives had been spared","meaning":"生命得以保全","examples":[{"en":"The lives of 6,500 people had been spared.","zh":"6,500人的生命得以保全。"},{"en":"If lives had been spared, people who might have died were saved.","zh":"如果生命得以保全，就是本可能死亡的人被救了。"},{"en":"A successful rescue operation may mean many lives have been spared after an earthquake.","zh":"地震後，成功救援行動可能意味許多生命得以保全。"},{"en":"If someone’s actions spare lives, their courage has direct human value.","zh":"如果某人的行動保全生命，其勇氣就有直接人道價值。"},{"en":"The phrase describes survival because danger was avoided or prevented.","zh":"這個短語描述因避免或阻止危險而生還。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":23},{"front":"thanks to","meaning":"多虧；由於","examples":[{"en":"Many lives were spared thanks to O’Flaherty and his helpers.","zh":"多虧 O’Flaherty 和他的助手，許多生命得以保全。"},{"en":"Thanks to someone or something means because of their help or influence.","zh":"“Thanks to” 某人或某事指因為其幫助或影響。"},{"en":"Thanks to a patient teacher, a nervous student may begin to enjoy speaking English.","zh":"多虧有耐性的老師，緊張學生可能開始享受說英語。"},{"en":"If people survive thanks to a rescue network, gratitude belongs to all who helped.","zh":"如果人們多虧救援網絡而生還，感激就屬於所有幫助者。"},{"en":"The phrase identifies the positive cause of a good result.","zh":"這個短語指出好結果的正面原因。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":23},{"front":"so effective had he been at","meaning":"他在……方面如此有效，以致","examples":[{"en":"So effective had he been at rescue work that he earned a nickname.","zh":"他在救援工作方面如此有效，以致獲得一個外號。"},{"en":"So effective had he been at something is an inverted form meaning he had been so successful at it that a result followed.","zh":"“So effective had he been at” 是倒裝句式，意思是他在某方面如此成功，以致帶來某結果。"},{"en":"So effective had the teacher been at explaining grammar that even weak students understood the lesson.","zh":"老師在解釋文法方面如此有效，以致連較弱學生也理解課堂。"},{"en":"If someone is extremely effective at dangerous work, their reputation may grow quickly.","zh":"如果某人在危險工作方面極其有效，其聲譽可能迅速提升。"},{"en":"The phrase is formal and emphatic.","zh":"這個短語較正式且帶強調語氣。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":23},{"front":"servicemen","meaning":"軍人","examples":[{"en":"O’Flaherty helped Jews and servicemen reach safety.","zh":"O’Flaherty 幫助猶太人和軍人到達安全地點。"},{"en":"Servicemen are men serving in the armed forces.","zh":"軍人是在武裝部隊服役的男子。"},{"en":"During war, servicemen may be captured, injured, or separated from their units.","zh":"戰爭期間，軍人可能被俘、受傷或與部隊失散。"},{"en":"If servicemen are helped to reach safety, they may return to their country or unit.","zh":"如果軍人被幫助到達安全地點，就可能返回自己的國家或部隊。"},{"en":"The word refers to military personnel, especially male soldiers or airmen.","zh":"這個詞指軍事人員，尤其是男性士兵或飛行員。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":23},{"front":"a huge number of","meaning":"大量；許多","examples":[{"en":"O’Flaherty received a huge number of accolades.","zh":"O’Flaherty 獲得大量嘉許。"},{"en":"A huge number of something means a very large number of it.","zh":"“A huge number of” 某物指非常多的數量。"},{"en":"A popular video may receive a huge number of comments in one day.","zh":"受歡迎影片可能在一天內收到大量留言。"},{"en":"If someone receives a huge number of awards, many organisations have recognised their work.","zh":"如果某人獲得大量獎項，就有許多組織認可其工作。"},{"en":"The phrase strongly emphasises quantity.","zh":"這個短語強烈強調數量。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":23},{"front":"in acknowledgement of","meaning":"為表彰……","examples":[{"en":"He received accolades in acknowledgement of his wartime achievements.","zh":"他獲得嘉許，以表彰其戰時成就。"},{"en":"In acknowledgement of something means as recognition or appreciation of it.","zh":"“In acknowledgement of” 某事指作為對它的認可或感謝。"},{"en":"A school may give a prize in acknowledgement of a student’s service to classmates.","zh":"學校可能頒獎以表彰學生服務同學。"},{"en":"If a medal is given in acknowledgement of bravery, it publicly honours that courage.","zh":"如果勳章是為表彰勇氣而頒發，它就公開表揚那份勇氣。"},{"en":"The phrase explains the reason for praise or award.","zh":"這個短語解釋讚揚或獎項的原因。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":23},{"front":"wartime achievements","meaning":"戰時成就","examples":[{"en":"His wartime achievements were recognised around the world.","zh":"他的戰時成就受到世界各地認可。"},{"en":"Wartime achievements are important things accomplished during a war.","zh":"戰時成就是在戰爭期間完成的重要事情。"},{"en":"A doctor’s wartime achievements may include saving wounded civilians under bombardment.","zh":"醫生的戰時成就可能包括在轟炸下拯救受傷平民。"},{"en":"If wartime achievements saved lives, later honours may preserve that memory.","zh":"如果戰時成就拯救生命，後來的榮譽可能保存那份記憶。"},{"en":"The phrase connects accomplishment with the dangerous conditions of war.","zh":"這個短語把成就與戰爭的危險條件連繫起來。"}],"source":"68 - The Scarlet Pimpernel of the Vatican.pdf","sourcePage":23}],"ielts/reading/passage-2/Practice 69":[{"front":"the race to","meaning":"爭相……；競相……","examples":[{"en":"The passage discusses the race to make artificial spider silk.","zh":"文章討論人們爭相製造人造蜘蛛絲。"},{"en":"The race to do something means a competition to achieve something before others do.","zh":"the race to do something 指為了比別人更早達成某事而進行的競爭。"},{"en":"Several schools may join the race to improve exam results by offering better support.","zh":"幾間學校可能透過提供更好支援，加入提升考試成績的競爭。"},{"en":"When a new technology seems valuable, companies often enter the race to develop it first.","zh":"當新科技看似有價值，公司常會競相率先開發它。"},{"en":"This phrase suggests urgency, competition, and the desire to be first.","zh":"這個片語暗示急切、競爭和想成為第一。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":1},{"front":"spider silk","meaning":"蜘蛛絲","examples":[{"en":"Scientists are trying to make artificial spider silk.","zh":"科學家正嘗試製造人造蜘蛛絲。"},{"en":"Spider silk is the strong, thin fibre produced by spiders to build webs or catch prey.","zh":"spider silk 是蜘蛛製造的強韌幼細纖維，用來織網或捕捉獵物。"},{"en":"A child may see spider silk shining between plants after rain.","zh":"下雨後，孩子可能看見植物之間閃閃發亮的蜘蛛絲。"},{"en":"Because spider silk is light but strong, researchers hope to copy it for useful products.","zh":"因為蜘蛛絲輕而強韌，研究人員希望複製它來製造有用產品。"},{"en":"This phrase refers to a natural fibre made by spiders, not ordinary sewing silk.","zh":"這個片語指蜘蛛製造的天然纖維，而不是普通縫紉絲線。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":1},{"front":"strength, toughness, and elasticity","meaning":"強度、韌性和彈性","examples":[{"en":"The strength, toughness, and elasticity of silk continue to fascinate scientists.","zh":"絲的強度、韌性和彈性繼續令科學家着迷。"},{"en":"Strength, toughness, and elasticity mean how strong, damage-resistant, and stretchable a material is.","zh":"strength, toughness, and elasticity 指材料有多強、有多能抵抗損壞，以及有多能伸展。"},{"en":"A good school bag needs strength, toughness, and elasticity so it can carry books without tearing.","zh":"好書包需要強度、韌性和彈性，才能裝書而不撕裂。"},{"en":"If a fibre has all three qualities, it can survive pulling, bending, and sudden force.","zh":"如果纖維同時有這三種特質，就能承受拉扯、彎曲和突然受力。"},{"en":"This phrase describes several physical properties working together.","zh":"這個片語描述幾種物理特性共同發揮作用。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":1},{"front":"continue to fascinate","meaning":"繼續令……着迷","examples":[{"en":"The unusual qualities of silk continue to fascinate scientists.","zh":"絲的不尋常特質繼續令科學家着迷。"},{"en":"To continue to fascinate means to keep attracting strong interest over time.","zh":"continue to fascinate 指隨時間仍然強烈吸引某人的興趣。"},{"en":"Space travel continues to fascinate students because it combines danger, science, and imagination.","zh":"太空旅行繼續令學生着迷，因為它結合危險、科學和想像。"},{"en":"If a material has properties people cannot easily copy, it may fascinate researchers for decades.","zh":"如果一種材料有難以複製的特性，它可能令研究人員着迷數十年。"},{"en":"This phrase shows long-lasting curiosity rather than a short moment of interest.","zh":"這個片語顯示長久好奇，而不是短暫興趣。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":1},{"front":"give something its unusual qualities","meaning":"賦予……不尋常特質","examples":[{"en":"Scientists wonder what gives silk its unusual qualities.","zh":"科學家想知道甚麼賦予絲不尋常特質。"},{"en":"To give something its unusual qualities means to be the reason it has special features.","zh":"give something its unusual qualities 指成為某物擁有特殊特徵的原因。"},{"en":"A recipe’s slow cooking time may give the soup its unusual flavour.","zh":"食譜中的慢煮時間可能賦予湯不尋常味道。"},{"en":"If scientists identify what gives silk its strength, they may learn how to copy it.","zh":"如果科學家識別出甚麼賦予絲強度，他們可能學會如何複製它。"},{"en":"This phrase asks what causes a thing to be special.","zh":"這個片語詢問甚麼令某物特別。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":1},{"front":"natural material","meaning":"天然物料","examples":[{"en":"Silk is a natural material with remarkable properties.","zh":"絲是一種具有非凡特性的天然物料。"},{"en":"A natural material is a material that comes from nature rather than being fully made by humans.","zh":"natural material 是來自自然界，而不是完全由人類製造的物料。"},{"en":"Cotton, wood, wool, and bamboo are common natural materials used in daily life.","zh":"棉花、木材、羊毛和竹都是日常生活中常見的天然物料。"},{"en":"Natural materials can be useful, but their quality may vary depending on how they are produced.","zh":"天然物料可以很有用，但其質素可能因生產方式而不同。"},{"en":"This phrase contrasts materials from nature with synthetic materials made in factories.","zh":"這個片語把來自自然的物料與工廠製造的合成物料作對比。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":1},{"front":"finer than human hair","meaning":"比人類頭髮更幼細","examples":[{"en":"Spider silk is finer than human hair.","zh":"蜘蛛絲比人類頭髮更幼細。"},{"en":"Finer than human hair means thinner or more delicate than a strand of hair from a person.","zh":"finer than human hair 指比一根人類頭髮更細或更纖幼。"},{"en":"Some medical needles are finer than human hair, so they cause less pain.","zh":"一些醫療針頭比人類頭髮更幼細，因此造成較少痛楚。"},{"en":"If a fibre is very fine, it can feel light while still being useful.","zh":"如果纖維非常幼細，它可以感覺很輕，同時仍然有用。"},{"en":"This phrase compares thickness using something familiar.","zh":"這個片語用熟悉的東西來比較厚度。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":1},{"front":"lighter than cotton","meaning":"比棉花更輕","examples":[{"en":"Silk is lighter than cotton.","zh":"絲比棉花更輕。"},{"en":"Lighter than cotton means having less weight than cotton when compared fairly.","zh":"lighter than cotton 指在公平比較下重量少於棉花。"},{"en":"A jacket made from a lighter material may be easier to carry on a trip.","zh":"由較輕物料製成的外套，旅行時可能較容易攜帶。"},{"en":"If a material is lighter than cotton but still strong, it may be useful for sports equipment.","zh":"如果一種物料比棉花更輕但仍然強韌，它可能適合用於運動裝備。"},{"en":"This phrase compares weight, not colour.","zh":"這個片語比較重量，而不是顏色。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":1},{"front":"ounce for ounce","meaning":"同等重量下","examples":[{"en":"Ounce for ounce, silk can be stronger than steel.","zh":"同等重量下，絲可以比鋼更堅韌。"},{"en":"Ounce for ounce means when equal weights of two materials are compared.","zh":"ounce for ounce 指比較兩種物料相同重量時。"},{"en":"Ounce for ounce, nuts contain more energy than many fruits.","zh":"同等重量下，堅果比許多水果含有更多能量。"},{"en":"If silk is stronger ounce for ounce, a small amount can carry impressive force.","zh":"如果絲在同等重量下更強韌，少量絲也能承受驚人力量。"},{"en":"This phrase is used to make a fair weight-based comparison.","zh":"這個片語用來作公平的重量比較。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":1},{"front":"stronger than steel","meaning":"比鋼更堅韌","examples":[{"en":"Spider silk can be stronger than steel.","zh":"蜘蛛絲可以比鋼更堅韌。"},{"en":"Stronger than steel means able to resist breaking better than steel under a fair comparison.","zh":"stronger than steel 指在公平比較下，比鋼更能抵抗斷裂。"},{"en":"A bridge cable needs material strong enough to hold heavy weight safely.","zh":"橋樑纜索需要足夠強韌的材料，才能安全承受重物。"},{"en":"If a fibre is stronger than steel by weight, engineers may want to use it in safety equipment.","zh":"如果纖維按重量計比鋼更強韌，工程師可能想把它用於安全設備。"},{"en":"This phrase describes remarkable strength, not ordinary toughness.","zh":"這個片語描述非凡強度，而不是普通堅固。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":1},{"front":"be of special interest to","meaning":"對……特別有吸引力","examples":[{"en":"Silk is of special interest to materials researchers.","zh":"絲對材料研究人員特別有吸引力。"},{"en":"To be of special interest to someone means to be especially important, useful, or attractive to that group.","zh":"be of special interest to someone 指對某群體特別重要、有用或吸引。"},{"en":"A new teaching app may be of special interest to language teachers.","zh":"新教學應用程式可能對語言教師特別有吸引力。"},{"en":"If a material combines lightness and strength, it becomes especially interesting to engineers.","zh":"如果一種材料結合輕巧和強韌，它對工程師便特別有吸引力。"},{"en":"This phrase shows that a topic matters strongly to a particular audience.","zh":"這個片語顯示某主題對特定受眾特別重要。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":1},{"front":"materials researchers","meaning":"材料研究人員","examples":[{"en":"Materials researchers are trying to duplicate silk’s properties.","zh":"材料研究人員正嘗試複製絲的特性。"},{"en":"Materials researchers are scientists who study the structure, behaviour, and uses of materials.","zh":"materials researchers 是研究材料結構、行為和用途的科學家。"},{"en":"Materials researchers may test whether a new plastic can survive heat and pressure.","zh":"材料研究人員可能測試新塑膠能否承受高溫和壓力。"},{"en":"If researchers understand a material deeply, they can design better products from it.","zh":"如果研究人員深入理解材料，就能用它設計更好的產品。"},{"en":"This phrase refers to experts who study what materials are made of and how they perform.","zh":"這個片語指研究材料成分和性能的專家。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":2},{"front":"duplicate its properties","meaning":"複製其特性","examples":[{"en":"Researchers are trying to duplicate the properties of spider silk.","zh":"研究人員正嘗試複製蜘蛛絲的特性。"},{"en":"To duplicate its properties means to copy the special features or behaviour of a material.","zh":"duplicate its properties 指複製某種材料的特殊特徵或表現。"},{"en":"A sportswear company may try to duplicate the softness of cotton in a cheaper fabric.","zh":"運動服公司可能嘗試在較便宜布料中複製棉花的柔軟感。"},{"en":"If scientists can duplicate silk’s strength and elasticity, they can create new high-performance fibres.","zh":"如果科學家能複製絲的強度和彈性，就能創造新的高性能纖維。"},{"en":"This phrase focuses on copying qualities, not copying the whole organism.","zh":"這個片語聚焦於複製特質，而不是複製整個生物。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":2},{"front":"synthesise it","meaning":"合成它","examples":[{"en":"Scientists want to synthesise spider silk for large-scale production.","zh":"科學家想合成蜘蛛絲以進行大規模生產。"},{"en":"To synthesise it means to make it artificially through chemical or biological processes.","zh":"synthesise it 指透過化學或生物過程人工製造它。"},{"en":"A lab may synthesise a medicine instead of extracting it from rare plants.","zh":"實驗室可能合成藥物，而不是從稀有植物中提取它。"},{"en":"If spider silk can be synthesised cheaply, factories may produce it without needing millions of spiders.","zh":"如果蜘蛛絲能被廉價合成，工廠便可能不需要數百萬隻蜘蛛也能生產它。"},{"en":"This phrase describes creating something artificially, not simply collecting it.","zh":"這個片語描述人工創造某物，而不只是收集它。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":2},{"front":"large-scale production","meaning":"大規模生產","examples":[{"en":"Artificial spider silk could be made through large-scale production.","zh":"人造蜘蛛絲可以透過大規模生產製成。"},{"en":"Large-scale production means making something in very large quantities, usually in factories.","zh":"large-scale production 指大量製造某物，通常在工廠中進行。"},{"en":"A small bakery makes bread by hand, but large-scale production makes thousands of loaves each day.","zh":"小麵包店手工製作麵包，但大規模生產每天製造數千條麵包。"},{"en":"If a material can enter large-scale production, it becomes more affordable and widely available.","zh":"如果材料能進入大規模生產，它就會更便宜並更廣泛可得。"},{"en":"This phrase contrasts mass production with small laboratory samples.","zh":"這個片語把大量生產與小型實驗室樣本作對比。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":2},{"front":"hold the promise of","meaning":"有望帶來……","examples":[{"en":"Spider silk holds the promise of many useful products.","zh":"蜘蛛絲有望帶來許多有用產品。"},{"en":"To hold the promise of something means to have the potential to lead to it in the future.","zh":"hold the promise of something 指有潛力在未來帶來某事。"},{"en":"A new vaccine may hold the promise of preventing a serious disease.","zh":"新疫苗可能有望預防嚴重疾病。"},{"en":"If a material is strong, light, and flexible, it may lead to many practical inventions.","zh":"如果材料強韌、輕巧又柔韌，它可能帶來許多實用發明。"},{"en":"This phrase suggests future hope, not guaranteed success.","zh":"這個片語暗示未來希望，而不是保證成功。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":2},{"front":"wear-resistant shoes","meaning":"耐磨鞋","examples":[{"en":"Spider silk may be used to make wear-resistant shoes.","zh":"蜘蛛絲可能被用來製造耐磨鞋。"},{"en":"Wear-resistant shoes are shoes designed to last longer and resist damage from rubbing or regular use.","zh":"wear-resistant shoes 是設計來更耐用並抵抗摩擦或日常使用損壞的鞋。"},{"en":"A delivery worker needs wear-resistant shoes because walking all day quickly damages ordinary soles.","zh":"送貨員需要耐磨鞋，因為整天走路會很快磨損普通鞋底。"},{"en":"If a fibre resists wear, shoes made from it may need replacing less often.","zh":"如果纖維耐磨，由它製成的鞋可能不用那麼頻繁更換。"},{"en":"This phrase focuses on durability under repeated use.","zh":"這個片語聚焦於反覆使用下的耐用性。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":2},{"front":"stronger ropes","meaning":"更堅韌的繩索","examples":[{"en":"Artificial spider silk could be used to make stronger ropes.","zh":"人造蜘蛛絲可以用來製造更堅韌的繩索。"},{"en":"Stronger ropes are ropes that can hold heavier loads or resist breaking better.","zh":"stronger ropes 是能承受更重負荷或更能抵抗斷裂的繩索。"},{"en":"Climbers need stronger ropes because a weak rope can put lives at risk.","zh":"攀石者需要更堅韌的繩索，因為脆弱繩索可能危及生命。"},{"en":"If fibres become stronger, ropes can be thinner, lighter, and safer.","zh":"如果纖維變得更強韌，繩索可以更幼、更輕和更安全。"},{"en":"This phrase describes improved strength in practical equipment.","zh":"這個片語描述實用設備中強度的改善。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":2},{"front":"seatbelts","meaning":"安全帶","examples":[{"en":"Spider silk may improve the strength of seatbelts.","zh":"蜘蛛絲可能改善安全帶的強度。"},{"en":"Seatbelts are safety straps in vehicles that hold passengers in place during sudden stops or crashes.","zh":"seatbelts 是車輛中的安全帶，在突然停車或撞車時固定乘客。"},{"en":"Drivers and passengers should wear seatbelts before the car starts moving.","zh":"司機和乘客在車輛開動前應扣好安全帶。"},{"en":"If a seatbelt is stronger, it may protect people better during an accident.","zh":"如果安全帶更堅韌，它可能在意外中更好地保護人。"},{"en":"This word refers to a basic vehicle safety device.","zh":"這個詞指基本車輛安全裝置。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":2},{"front":"parachutes","meaning":"降落傘","examples":[{"en":"Stronger silk fibres could be useful in parachutes.","zh":"更堅韌的絲纖維可能對降落傘有用。"},{"en":"Parachutes are devices made of fabric that slow a person or object as it falls through the air.","zh":"parachutes 是由布料製成、使人或物在空中下降時減速的裝置。"},{"en":"Skydivers rely on parachutes to land safely after jumping from a plane.","zh":"跳傘者依靠降落傘在從飛機跳下後安全着陸。"},{"en":"If parachute fabric is lighter and stronger, it may be safer and easier to carry.","zh":"如果降落傘布料更輕和更強韌，它可能更安全也更易攜帶。"},{"en":"This word is connected with controlled falling and safety.","zh":"這個詞與受控下降和安全有關。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":2},{"front":"rust-free panels","meaning":"防鏽板","examples":[{"en":"Spider silk could help create rust-free panels for automobiles.","zh":"蜘蛛絲可以幫助製造汽車防鏽板。"},{"en":"Rust-free panels are vehicle or machine panels that do not corrode when exposed to moisture.","zh":"rust-free panels 是暴露於濕氣時不會腐蝕的車輛或機械面板。"},{"en":"A car owner near the sea may want rust-free panels because salty air damages metal quickly.","zh":"住在海邊的車主可能想要防鏽板，因為鹹濕空氣很快損壞金屬。"},{"en":"If panels do not rust, vehicles may last longer and need fewer repairs.","zh":"如果面板不生鏽，車輛可能更耐用並需要較少維修。"},{"en":"This phrase describes materials that avoid corrosion problems.","zh":"這個片語描述避免腐蝕問題的材料。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":2},{"front":"bumpers","meaning":"汽車保險槓","examples":[{"en":"Artificial silk might be used in automobile bumpers.","zh":"人造絲可能被用於汽車保險槓。"},{"en":"Bumpers are parts at the front and back of a vehicle that help absorb impact in minor collisions.","zh":"bumpers 是車輛前後用來在輕微碰撞中吸收衝擊的部分。"},{"en":"A parking mistake may scratch a bumper before damaging the main body of the car.","zh":"泊車失誤可能先刮花保險槓，而未損壞車身主要部分。"},{"en":"If bumpers are made from stronger materials, they may protect vehicles better.","zh":"如果保險槓由更強韌材料製成，它們可能更好地保護車輛。"},{"en":"This word refers to a protective part of a car.","zh":"這個詞指汽車的保護部件。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":2},{"front":"improved sutures","meaning":"改良縫合線","examples":[{"en":"Spider silk may lead to improved sutures.","zh":"蜘蛛絲可能帶來改良縫合線。"},{"en":"Improved sutures are better medical stitches used to close wounds or surgical cuts.","zh":"improved sutures 是用來縫合傷口或手術切口的更好醫療縫線。"},{"en":"After surgery, doctors use sutures to hold skin or tissue together while it heals.","zh":"手術後，醫生使用縫合線把皮膚或組織固定在一起，讓它癒合。"},{"en":"If sutures are stronger and safer, wounds may close more reliably.","zh":"如果縫合線更強韌和安全，傷口可能更可靠地閉合。"},{"en":"This phrase refers to medical thread with better performance.","zh":"這個片語指性能更好的醫療線材。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":3},{"front":"bandages","meaning":"繃帶","examples":[{"en":"Spider silk could be used in better bandages.","zh":"蜘蛛絲可以用於更好的繃帶。"},{"en":"Bandages are strips or pieces of material used to cover, protect, or support an injured part of the body.","zh":"bandages 是用來覆蓋、保護或支撐身體受傷部位的材料條或材料片。"},{"en":"A child with a cut knee may need a clean bandage to protect the wound.","zh":"膝蓋擦傷的孩子可能需要乾淨繃帶保護傷口。"},{"en":"If bandages are stronger and more flexible, they may stay in place more comfortably.","zh":"如果繃帶更堅韌和更柔韌，它們可能更舒適地固定在原位。"},{"en":"This word refers to basic wound-care material.","zh":"這個詞指基本傷口護理材料。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":3},{"front":"artificial tendons","meaning":"人造肌腱","examples":[{"en":"Researchers hope spider silk can support the development of artificial tendons.","zh":"研究人員希望蜘蛛絲可以支援人造肌腱的發展。"},{"en":"Artificial tendons are man-made replacements or supports for the tissues that connect muscles to bones.","zh":"artificial tendons 是用來替代或支撐連接肌肉與骨骼組織的人造物。"},{"en":"A patient with a serious hand injury may need tendon repair to regain movement.","zh":"手部嚴重受傷的病人可能需要肌腱修復來恢復活動能力。"},{"en":"If a material is strong and flexible, it may be useful for artificial tendons.","zh":"如果材料強韌又柔韌，它可能適用於人造肌腱。"},{"en":"This phrase belongs to medical repair and tissue engineering.","zh":"這個片語屬於醫療修復和組織工程。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":3},{"front":"ligaments","meaning":"韌帶","examples":[{"en":"Spider silk may be useful for artificial ligaments.","zh":"蜘蛛絲可能對人造韌帶有用。"},{"en":"Ligaments are tough bands of tissue that connect bones and help stabilise joints.","zh":"ligaments 是連接骨骼並幫助穩定關節的強韌組織帶。"},{"en":"A football player may tear a knee ligament during a sudden turn.","zh":"足球員在突然轉身時可能撕裂膝部韌帶。"},{"en":"If artificial ligaments are strong and flexible, they can help damaged joints move safely again.","zh":"如果人造韌帶強韌又柔韌，它們可以幫助受損關節再次安全活動。"},{"en":"This word refers to body tissues that support joints.","zh":"這個詞指支撐關節的身體組織。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":3},{"front":"weakened blood vessels","meaning":"衰弱的血管","examples":[{"en":"Spider silk may support weakened blood vessels.","zh":"蜘蛛絲可能支撐衰弱的血管。"},{"en":"Weakened blood vessels are blood-carrying tubes in the body that have become fragile or less able to hold pressure.","zh":"weakened blood vessels 是身體中變得脆弱或較難承受壓力的輸血管道。"},{"en":"A doctor may monitor weakened blood vessels carefully because they can create serious health risks.","zh":"醫生可能仔細監察衰弱的血管，因為它們可以造成嚴重健康風險。"},{"en":"If a material can support weak vessels safely, it may help prevent further damage.","zh":"如果材料能安全支撐脆弱血管，它可能幫助防止進一步損傷。"},{"en":"This phrase refers to a medical problem involving fragile circulation pathways.","zh":"這個片語指涉及脆弱循環管道的醫療問題。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":3},{"front":"bulletproof vests","meaning":"防彈背心","examples":[{"en":"Spider silk could be used to make bulletproof vests.","zh":"蜘蛛絲可以用來製造防彈背心。"},{"en":"Bulletproof vests are protective garments designed to reduce injury from bullets or sharp impacts.","zh":"bulletproof vests 是設計來減少子彈或尖銳衝擊傷害的防護衣物。"},{"en":"Police officers may wear bulletproof vests when entering dangerous situations.","zh":"警員進入危險情況時可能穿防彈背心。"},{"en":"If a vest is lighter but strong, it can protect people without limiting movement too much.","zh":"如果背心更輕但強韌，它可以保護人，同時不過度限制活動。"},{"en":"This phrase refers to safety clothing used in high-risk work.","zh":"這個片語指高風險工作中使用的安全衣物。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":3},{"front":"secrete silks of varying quality","meaning":"分泌品質不一的絲","examples":[{"en":"Many insects secrete silks of varying quality.","zh":"許多昆蟲分泌品質不一的絲。"},{"en":"To secrete silks of varying quality means to produce silk fibres that differ in strength, texture, or usefulness.","zh":"secrete silks of varying quality 指產生在強度、質感或用途上不同的絲纖維。"},{"en":"Different students may produce homework of varying quality if they receive different levels of guidance.","zh":"如果學生得到不同程度的指導，他們可能交出品質不一的功課。"},{"en":"If insects make silks of different quality, researchers will focus on the most useful types.","zh":"如果昆蟲製造不同品質的絲，研究人員會專注於最有用的類型。"},{"en":"This phrase combines biological production with differences in quality.","zh":"這個片語結合生物分泌與質素差異。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":3},{"front":"best known is","meaning":"最為人熟悉的是","examples":[{"en":"Best known is the moth Bombyx mori.","zh":"最為人熟悉的是家蠶蛾 Bombyx mori。"},{"en":"Best known is means the most familiar or widely recognised example is.","zh":"best known is 指最熟悉或最廣為人認識的例子是。"},{"en":"Among English exams, best known is probably IELTS for many international students.","zh":"在英語考試之中，對許多國際學生而言，最為人熟悉的可能是 IELTS。"},{"en":"If many species make silk, the best-known one may still receive the most public attention.","zh":"即使許多物種會製絲，最為人熟悉的一種仍可能得到最多公眾關注。"},{"en":"This phrase introduces the most famous example in a group.","zh":"這個片語引入一組之中最有名的例子。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":3},{"front":"Bombyx mori","meaning":"家蠶蛾","examples":[{"en":"Bombyx mori is the moth whose caterpillar is known as the silkworm.","zh":"Bombyx mori 是其幼蟲被稱為蠶的蛾。"},{"en":"Bombyx mori is the scientific name for the domesticated silkworm moth.","zh":"Bombyx mori 是家養蠶蛾的學名。"},{"en":"A biology teacher may use Bombyx mori as an example of an insect important to human industry.","zh":"生物老師可能用 Bombyx mori 作為對人類產業重要的昆蟲例子。"},{"en":"Because Bombyx mori produces silk, it has been raised by people for centuries.","zh":"因為 Bombyx mori 會產絲，人類已飼養牠數百年。"},{"en":"This term is a scientific species name, not an everyday English name.","zh":"這個詞是科學物種名稱，而不是日常英文名稱。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":3},{"front":"be commonly known as","meaning":"通常稱為","examples":[{"en":"The caterpillar of Bombyx mori is commonly known as the silkworm.","zh":"Bombyx mori 的幼蟲通常稱為蠶。"},{"en":"To be commonly known as something means to be usually called by that name.","zh":"be commonly known as something 指通常被稱為某個名稱。"},{"en":"The city of New York is commonly known as the Big Apple.","zh":"紐約市通常稱為 Big Apple。"},{"en":"If a scientific name is difficult, people often use the name it is commonly known as.","zh":"如果科學名稱很難，人們常使用它通常被稱為的名稱。"},{"en":"This phrase introduces a familiar name for something.","zh":"這個片語引入某物的熟悉名稱。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":3},{"front":"the silkworm","meaning":"蠶","examples":[{"en":"The silkworm has been used for centuries to make fine garments.","zh":"蠶數百年來被用來製造精美衣物。"},{"en":"The silkworm is the caterpillar that produces silk thread to form its cocoon.","zh":"silkworm 是會吐絲結繭的幼蟲。"},{"en":"Children may learn about silkworms in science class by observing their life cycle.","zh":"孩子可能在科學課透過觀察蠶的生命週期來學習。"},{"en":"Because silkworms produce useful silk, people have raised them for clothing production.","zh":"因為蠶產生有用的絲，人類長期飼養牠們以製衣。"},{"en":"This word refers to the larval stage of the silkworm moth.","zh":"這個詞指蠶蛾的幼蟲階段。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":3},{"front":"spin its cocoon","meaning":"吐絲結繭","examples":[{"en":"The silkworm spins its cocoon from a single thread.","zh":"蠶用一條單絲吐絲結繭。"},{"en":"To spin its cocoon means to produce silk thread and wrap it around itself to form a protective case.","zh":"spin its cocoon 指產生絲線並把它圍繞自己形成保護外殼。"},{"en":"A caterpillar may spin a cocoon before changing into a moth.","zh":"毛蟲可能在變成蛾之前吐絲結繭。"},{"en":"If a silkworm spins a long continuous thread, people can unwind it to make silk fabric.","zh":"如果蠶吐出長而連續的絲，人們可以把它拆開來製作絲布。"},{"en":"This phrase describes how an insect creates a protective silk covering.","zh":"這個片語描述昆蟲如何製造保護性絲外殼。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":4},{"front":"a single thread","meaning":"一條單絲","examples":[{"en":"The silkworm spins its cocoon from a single thread.","zh":"蠶用一條單絲吐絲結繭。"},{"en":"A single thread means one continuous strand of fibre.","zh":"single thread 指一條連續纖維。"},{"en":"A loose button may hang from a shirt by a single thread.","zh":"鬆脫的鈕扣可能靠一條單線掛在襯衫上。"},{"en":"If a cocoon is made from a single thread, that thread can be unwound into a very long fibre.","zh":"如果繭由一條單絲組成，那條絲可以被拆成很長的纖維。"},{"en":"This phrase stresses one continuous line rather than many separate pieces.","zh":"這個片語強調一條連續線，而不是許多分開片段。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":4},{"front":"between 300 and 900 metres long","meaning":"長達三百至九百米","examples":[{"en":"The thread can be between 300 and 900 metres long.","zh":"那條絲可長達三百至九百米。"},{"en":"Between 300 and 900 metres long means its length falls somewhere within that range.","zh":"between 300 and 900 metres long 指其長度介乎這個範圍之內。"},{"en":"A running route between 300 and 900 metres long may be suitable for a short training session.","zh":"三百至九百米長的跑步路線可能適合短時間訓練。"},{"en":"If one thread is hundreds of metres long, it can provide enough fibre for textile production.","zh":"如果一條絲長達數百米，它可以提供足夠纖維作紡織生產。"},{"en":"This phrase gives an approximate measured range.","zh":"這個片語給出大約量度範圍。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":4},{"front":"for centuries","meaning":"數百年來","examples":[{"en":"Silkworm silk has been used for centuries to make fine garments.","zh":"蠶絲數百年來被用來製作精美衣物。"},{"en":"For centuries means for hundreds of years.","zh":"for centuries 指歷時數百年。"},{"en":"Some families have passed down festival recipes for centuries.","zh":"一些家庭數百年來傳承節日食譜。"},{"en":"If a material has been used for centuries, people have had a long time to learn its value.","zh":"如果某種材料被使用數百年，人們已有很長時間了解其價值。"},{"en":"This phrase gives a long historical time span.","zh":"這個片語給出很長的歷史時間跨度。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":4},{"front":"fine garments","meaning":"精美衣物","examples":[{"en":"Silkworm silk is used to make fine garments.","zh":"蠶絲被用來製作精美衣物。"},{"en":"Fine garments are high-quality, elegant, or carefully made clothes.","zh":"fine garments 是高質、優雅或精心製作的衣服。"},{"en":"A tailor may make fine garments for weddings, formal dinners, or special ceremonies.","zh":"裁縫可能為婚禮、正式晚宴或特別典禮製作精美衣物。"},{"en":"If a fabric is soft and beautiful, it is often used for more expensive clothing.","zh":"如果布料柔軟又美觀，它常被用於較昂貴的衣物。"},{"en":"This phrase describes clothing valued for quality and appearance.","zh":"這個片語描述因質素和外觀而受重視的衣物。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":4},{"front":"the focus of scientific attention","meaning":"科學界關注的焦點","examples":[{"en":"The focus of scientific attention today is on spider silk.","zh":"今日科學界關注的焦點是蜘蛛絲。"},{"en":"The focus of scientific attention is the topic scientists are especially studying or discussing.","zh":"focus of scientific attention 是科學家特別研究或討論的主題。"},{"en":"During a health crisis, vaccines may become the focus of scientific attention.","zh":"在健康危機期間，疫苗可能成為科學界關注的焦點。"},{"en":"If a material has unusual properties, researchers may shift their attention toward it.","zh":"如果一種材料具有不尋常特性，研究人員可能把注意力轉向它。"},{"en":"This phrase shows where scientific interest is concentrated.","zh":"這個片語顯示科學興趣集中在哪裡。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":4},{"front":"tougher, stretchier, and more waterproof","meaning":"更堅韌、更有彈性、更防水","examples":[{"en":"Spider silk is tougher, stretchier, and more waterproof than silkworm strands.","zh":"蜘蛛絲比蠶絲絲縷更堅韌、更有彈性、更防水。"},{"en":"Tougher, stretchier, and more waterproof means more resistant to damage, more able to stretch, and better at resisting water.","zh":"tougher, stretchier, and more waterproof 指更能抵抗損壞、更能伸展，以及更能防水。"},{"en":"A good rain jacket should be tough, flexible, and waterproof for outdoor use.","zh":"好雨衣應該堅韌、靈活和防水，適合戶外使用。"},{"en":"If spider silk has these qualities, it may be more useful than ordinary silk for technical products.","zh":"如果蜘蛛絲具備這些特性，它可能比普通絲更適合技術產品。"},{"en":"This phrase compares several useful material properties at once.","zh":"這個片語一次比較幾種有用的材料特性。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":4},{"front":"silkworm strands","meaning":"蠶絲絲縷","examples":[{"en":"Spider silk is stretchier than silkworm strands.","zh":"蜘蛛絲比蠶絲絲縷更有彈性。"},{"en":"Silkworm strands are individual threads of silk produced by silkworms.","zh":"silkworm strands 是由蠶產生的一條條絲線。"},{"en":"A silk factory may unwind silkworm strands from cocoons to make fabric.","zh":"絲綢工廠可能從繭中拆出蠶絲絲縷來製作布料。"},{"en":"If strands are long and smooth, they can be woven into fine clothing.","zh":"如果絲縷又長又順滑，它們可以被織成精美衣物。"},{"en":"This phrase refers to silk fibres made by silkworms.","zh":"這個片語指由蠶製造的絲纖維。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":4},{"front":"as many as","meaning":"多達","examples":[{"en":"Spiders make as many as seven different types of silk.","zh":"蜘蛛能製造多達七種不同類型的絲。"},{"en":"As many as means up to a surprisingly large number.","zh":"as many as 指多達某個令人意外的大數目。"},{"en":"A busy teacher may mark as many as 100 essays in one weekend.","zh":"忙碌的老師可能一個週末批改多達100篇文章。"},{"en":"If spiders can make as many as seven silks, each type may have a different purpose.","zh":"如果蜘蛛能製造多達七種絲，每一種可能有不同用途。"},{"en":"This phrase emphasises that the number is high.","zh":"這個片語強調數量很高。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":4},{"front":"seven different types of silk","meaning":"七種不同類型的絲","examples":[{"en":"Spiders can make seven different types of silk.","zh":"蜘蛛能製造七種不同類型的絲。"},{"en":"Seven different types of silk means seven separate silk varieties with different properties or uses.","zh":"seven different types of silk 指七種在特性或用途上不同的絲。"},{"en":"A workshop may use different types of glue for paper, wood, plastic, and metal.","zh":"工作坊可能使用不同類型的膠水來黏紙、木材、塑膠和金屬。"},{"en":"If each silk type serves a different purpose, the spider can build, protect, and catch prey more effectively.","zh":"如果每種絲都有不同用途，蜘蛛便能更有效地築網、防護和捕食。"},{"en":"This phrase highlights variety within one spider’s silk production.","zh":"這個片語突出蜘蛛製絲中的多樣性。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":4},{"front":"at the centre of intense interest","meaning":"是高度關注的焦點","examples":[{"en":"One spider and two types of silk are at the centre of intense interest.","zh":"一種蜘蛛和兩種絲是高度關注的焦點。"},{"en":"To be at the centre of intense interest means to receive strong attention from many people.","zh":"at the centre of intense interest 指受到許多人強烈關注。"},{"en":"A new cancer treatment may be at the centre of intense interest among doctors.","zh":"新癌症治療可能成為醫生高度關注的焦點。"},{"en":"If a discovery could lead to valuable products, it naturally attracts strong research attention.","zh":"如果發現可能帶來有價值產品，它自然會吸引強烈研究關注。"},{"en":"This phrase shows that a topic is being studied or discussed very seriously.","zh":"這個片語顯示某主題正被非常認真地研究或討論。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":4},{"front":"the golden orb-weaving spider","meaning":"金色圓網蛛","examples":[{"en":"The golden orb-weaving spider produces silk of special scientific interest.","zh":"金色圓網蛛產生具有特殊科學價值的絲。"},{"en":"The golden orb-weaving spider is a spider known for making large round webs and strong silk.","zh":"golden orb-weaving spider 是以製造大型圓形蛛網和強韌絲而聞名的蜘蛛。"},{"en":"A nature guide may point out a golden orb-weaving spider because its web is easy to recognise.","zh":"自然導賞員可能指出金色圓網蛛，因為牠的蛛網容易辨認。"},{"en":"Because its silk has special properties, researchers study this spider closely.","zh":"因為牠的絲具有特殊特性，研究人員仔細研究這種蜘蛛。"},{"en":"This phrase names a specific spider species valued in silk research.","zh":"這個片語指出一種在絲研究中有價值的特定蜘蛛。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":5},{"front":"Nephila clavipes","meaning":"金色圓網蛛","examples":[{"en":"Nephila clavipes is the golden orb-weaving spider studied by researchers.","zh":"Nephila clavipes 是研究人員研究的金色圓網蛛。"},{"en":"Nephila clavipes is the scientific name of a golden orb-weaving spider species.","zh":"Nephila clavipes 是一種金色圓網蛛的學名。"},{"en":"A biology paper may use Nephila clavipes instead of the common name for accuracy.","zh":"生物論文可能使用 Nephila clavipes 而不是普通名稱，以求準確。"},{"en":"Scientific names help researchers in different countries know exactly which species is being discussed.","zh":"學名幫助不同國家的研究人員準確知道正在討論哪個物種。"},{"en":"This term is a formal species name used in scientific contexts.","zh":"這個詞是科學語境中使用的正式物種名稱。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":5},{"front":"under investigation","meaning":"正在研究中的","examples":[{"en":"The spider’s two silks under investigation are called dragline and capture.","zh":"這種蜘蛛正在研究中的兩種絲稱為牽引絲和捕捉絲。"},{"en":"Under investigation means being studied, examined, or tested carefully.","zh":"under investigation 指正在被仔細研究、檢查或測試。"},{"en":"A school rule may be under investigation if many parents complain about it.","zh":"如果許多家長投訴，校規可能正在接受調查。"},{"en":"If a material is under investigation, researchers have not finished understanding it yet.","zh":"如果一種材料正在研究中，研究人員尚未完全理解它。"},{"en":"This phrase signals active research or inquiry.","zh":"這個片語表示正在進行研究或查詢。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":5},{"front":"go by the evocative names","meaning":"以富有聯想意味的名稱為人所知","examples":[{"en":"The two silks go by the evocative names “dragline” and “capture”.","zh":"這兩種絲以 “dragline” 和 “capture” 這些富有聯想意味的名稱為人所知。"},{"en":"To go by evocative names means to be known by names that create clear images or associations.","zh":"go by evocative names 指以能產生清楚畫面或聯想的名稱為人所知。"},{"en":"A café may go by the evocative name “Morning Harbour” to make customers imagine calm breakfasts.","zh":"咖啡店可能以 “Morning Harbour” 這個富有聯想意味的名稱為人所知，令顧客想像平靜早餐。"},{"en":"If a scientific term is evocative, students may remember its function more easily.","zh":"如果科學術語富有聯想，學生可能更容易記住其功能。"},{"en":"This phrase focuses on names that suggest meaning beyond mere labels.","zh":"這個片語聚焦於暗示意義而不只是標籤的名稱。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":5},{"front":"dragline silk","meaning":"牽引絲","examples":[{"en":"Dragline silk forms the framework of the spider’s web.","zh":"牽引絲形成蜘蛛網的框架。"},{"en":"Dragline silk is a strong type of spider silk used for support, movement, and the main structure of a web.","zh":"dragline silk 是一種強韌蜘蛛絲，用於支撐、移動和蛛網主要結構。"},{"en":"A spider may hang from dragline silk when it drops from a branch.","zh":"蜘蛛從樹枝垂下時，可能懸掛在牽引絲上。"},{"en":"Because dragline silk must hold weight, it needs great strength and toughness.","zh":"因為牽引絲必須承受重量，它需要很高強度和韌性。"},{"en":"This phrase refers to one of the strongest and most studied spider silks.","zh":"這個片語指最強韌、最常被研究的蜘蛛絲之一。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":5},{"front":"capture silk","meaning":"捕捉絲","examples":[{"en":"Capture silk is the resilient substance at the centre of the web.","zh":"捕捉絲是蛛網中央有彈性的物質。"},{"en":"Capture silk is a flexible, sticky type of spider silk used to trap insects.","zh":"capture silk 是一種柔韌而黏性的蜘蛛絲，用來困住昆蟲。"},{"en":"A fly hitting capture silk may become stuck before it can escape.","zh":"蒼蠅撞上捕捉絲時，可能在逃走前被黏住。"},{"en":"Because capture silk stretches, it can absorb the force of a fast-moving insect.","zh":"因為捕捉絲能伸展，它可以吸收快速飛行昆蟲的衝擊力。"},{"en":"This phrase refers to the silk used mainly for catching prey.","zh":"這個片語指主要用於捕捉獵物的絲。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":5},{"front":"form the framework of","meaning":"形成……的框架","examples":[{"en":"Dragline silk forms the framework of the wheel-shaped web.","zh":"牽引絲形成輪狀蛛網的框架。"},{"en":"To form the framework of something means to create its main supporting structure.","zh":"form the framework of something 指創造某物的主要支撐結構。"},{"en":"Steel beams form the framework of a tall building.","zh":"鋼樑形成高樓的框架。"},{"en":"If the framework is weak, the whole structure may collapse or fail.","zh":"如果框架薄弱，整個結構可能倒塌或失效。"},{"en":"This phrase describes the part that gives shape and support.","zh":"這個片語描述提供形狀和支撐的部分。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":5},{"front":"wheel-shaped webs","meaning":"輪狀蛛網","examples":[{"en":"The spider builds wheel-shaped webs using dragline silk.","zh":"蜘蛛使用牽引絲建造輪狀蛛網。"},{"en":"Wheel-shaped webs are round spider webs with lines spreading out like the spokes of a wheel.","zh":"wheel-shaped webs 是圓形蛛網，線條像車輪輻條般向外伸展。"},{"en":"A child may notice a wheel-shaped web between garden plants in the morning.","zh":"孩子可能在清晨注意到花園植物之間的輪狀蛛網。"},{"en":"If the web has a strong frame, it can hold its shape when insects strike it.","zh":"如果蛛網有強韌框架，昆蟲撞上它時仍可保持形狀。"},{"en":"This phrase describes the web’s visible circular structure.","zh":"這個片語描述蛛網可見的圓形結構。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":5},{"front":"dangling spider","meaning":"懸掛着的蜘蛛","examples":[{"en":"Dragline silk enables the dangling spider to drop down and grab its prey.","zh":"牽引絲讓懸掛着的蜘蛛向下垂降並抓住獵物。"},{"en":"A dangling spider is a spider hanging from a thread or web line.","zh":"dangling spider 是吊在絲線或蛛網線上的蜘蛛。"},{"en":"Someone cleaning a window may suddenly see a dangling spider hanging in front of the glass.","zh":"擦窗的人可能突然看見一隻懸掛着的蜘蛛吊在玻璃前。"},{"en":"If a spider can dangle safely, it can move quickly without falling to the ground.","zh":"如果蜘蛛能安全懸掛，它就能快速移動而不跌落地面。"},{"en":"This phrase shows the spider suspended in the air.","zh":"這個片語顯示蜘蛛懸在空中的狀態。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":5},{"front":"drop down","meaning":"向下垂降","examples":[{"en":"The spider can drop down quickly using dragline silk.","zh":"蜘蛛可以使用牽引絲快速向下垂降。"},{"en":"To drop down means to move or fall downward from a higher position.","zh":"drop down 指從較高位置向下移動或落下。"},{"en":"A child may drop down from a low climbing frame after checking the ground is safe.","zh":"孩子確認地面安全後，可能從低矮攀爬架向下跳。"},{"en":"If a spider drops down suddenly, it can reach prey or escape danger quickly.","zh":"如果蜘蛛突然向下垂降，它可以快速接近獵物或逃避危險。"},{"en":"This phrase describes downward movement.","zh":"這個片語描述向下移動。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":5},{"front":"grab its prey","meaning":"抓住獵物","examples":[{"en":"The spider drops down to grab its prey.","zh":"蜘蛛向下垂降以抓住獵物。"},{"en":"To grab its prey means to seize the animal it wants to catch and eat.","zh":"grab its prey 指抓住牠想捕捉並吃掉的動物。"},{"en":"A cat may leap forward to grab a toy mouse during play.","zh":"貓玩耍時可能向前跳去抓住玩具老鼠。"},{"en":"If a predator grabs its prey quickly, the prey has little time to escape.","zh":"如果掠食者快速抓住獵物，獵物就幾乎沒有時間逃走。"},{"en":"This phrase describes the moment of catching food.","zh":"這個片語描述捕捉食物的一刻。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":5},{"front":"exhibit a combination of","meaning":"展現……的結合","examples":[{"en":"Dragline silk exhibits a combination of strength and toughness.","zh":"牽引絲展現強度和韌性的結合。"},{"en":"To exhibit a combination of qualities means to show several qualities at the same time.","zh":"exhibit a combination of qualities 指同時展現幾種特質。"},{"en":"A good teacher may exhibit a combination of patience, clarity, and firmness.","zh":"好老師可能展現耐性、清晰和堅定的結合。"},{"en":"If a material combines strength and toughness, it can resist both force and damage.","zh":"如果材料結合強度和韌性，它就能抵抗力量和損壞。"},{"en":"This phrase highlights qualities working together.","zh":"這個片語突出幾種特質共同發揮作用。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":6},{"front":"unmatched by","meaning":"是……無法匹敵的","examples":[{"en":"The toughness of dragline silk is unmatched by any high-performance synthetic fibre.","zh":"牽引絲的韌性是任何高性能合成纖維都無法匹敵的。"},{"en":"Unmatched by means not equalled or beaten by another thing.","zh":"unmatched by 指未被另一事物追平或超越。"},{"en":"The convenience of a school next door may be unmatched by a famous school far away.","zh":"住在隔壁學校的便利，可能是遠方名校無法匹敵的。"},{"en":"If a natural fibre is unmatched by synthetic fibres, scientists will try to understand why.","zh":"如果天然纖維是合成纖維無法匹敵的，科學家會嘗試理解原因。"},{"en":"This phrase shows that something is superior in a specific quality.","zh":"這個片語顯示某物在特定特質上較優越。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":6},{"front":"high-performance synthetic fibre","meaning":"高性能合成纖維","examples":[{"en":"No high-performance synthetic fibre matches the strength and toughness of dragline silk.","zh":"沒有高性能合成纖維能匹敵牽引絲的強度和韌性。"},{"en":"A high-performance synthetic fibre is a man-made fibre designed to be very strong, light, or durable.","zh":"high-performance synthetic fibre 是被設計得非常強韌、輕巧或耐用的人造纖維。"},{"en":"Sports equipment may use high-performance synthetic fibres to reduce weight and increase safety.","zh":"運動裝備可能使用高性能合成纖維來減輕重量和提升安全。"},{"en":"If even advanced synthetic fibres cannot match spider silk, the natural material is remarkable.","zh":"如果連先進合成纖維都不能匹敵蜘蛛絲，這種天然物料就很非凡。"},{"en":"This phrase refers to technically advanced man-made fibres.","zh":"這個片語指技術上先進的人造纖維。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":6},{"front":"resilient substance","meaning":"有彈性的物質","examples":[{"en":"Capture silk is the resilient substance at the centre of the web.","zh":"捕捉絲是蛛網中央有彈性的物質。"},{"en":"A resilient substance can stretch, absorb force, and return toward its original shape.","zh":"resilient substance 是能伸展、吸收力量並回復接近原本形狀的物質。"},{"en":"A rubber band is a resilient substance because it stretches and then tightens again.","zh":"橡筋是有彈性的物質，因為它能伸展後再次收緊。"},{"en":"If capture silk is resilient, it can hold insects without breaking immediately.","zh":"如果捕捉絲有彈性，它就能困住昆蟲而不會立即斷裂。"},{"en":"This phrase describes a material that can recover after pressure.","zh":"這個片語描述受壓後能恢復的材料。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":6},{"front":"at the centre of the web","meaning":"在蛛網中央","examples":[{"en":"Capture silk is found at the centre of the web.","zh":"捕捉絲位於蛛網中央。"},{"en":"At the centre of the web means in the middle part of the spider’s web.","zh":"at the centre of the web 指在蜘蛛網的中間部分。"},{"en":"A spider may wait at the centre of the web to sense when an insect is caught.","zh":"蜘蛛可能在蛛網中央等待，感應昆蟲何時被困住。"},{"en":"If the centre is sticky and elastic, it can help trap prey effectively.","zh":"如果中央部分黏而有彈性，它可以有效幫助捕捉獵物。"},{"en":"This phrase describes the location within the web.","zh":"這個片語描述蛛網中的位置。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":6},{"front":"a speeding insect","meaning":"快速飛行的昆蟲","examples":[{"en":"Capture silk can catch a speeding insect.","zh":"捕捉絲可以捉住快速飛行的昆蟲。"},{"en":"A speeding insect is an insect moving very fast through the air or across a surface.","zh":"speeding insect 是在空中或表面上快速移動的昆蟲。"},{"en":"A fly rushing across a kitchen may look like a speeding insect to a waiting spider.","zh":"一隻在廚房中快速飛過的蒼蠅，對等待中的蜘蛛來說可能像快速飛行的昆蟲。"},{"en":"If the web cannot absorb the insect’s speed, the insect may bounce away.","zh":"如果蛛網不能吸收昆蟲的速度，昆蟲可能被彈走。"},{"en":"This phrase highlights the force and movement that the web must handle.","zh":"這個片語突出蛛網必須承受的力量和移動。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":6},{"front":"stretch to almost three times","meaning":"伸展至接近三倍","examples":[{"en":"Capture silk may stretch to almost three times its original length.","zh":"捕捉絲可以伸展至接近其原本長度的三倍。"},{"en":"To stretch to almost three times means to become nearly three times as long without immediately breaking.","zh":"stretch to almost three times 指在不立即斷裂的情況下，變得接近原本三倍長。"},{"en":"A flexible exercise band may stretch to several times its original length during training.","zh":"柔韌的運動彈力帶在訓練時可能伸展至原本長度幾倍。"},{"en":"If silk stretches this far, it can absorb sudden impact from flying insects.","zh":"如果絲能伸展到這種程度，它就能吸收飛行昆蟲的突然衝擊。"},{"en":"This phrase describes extreme elasticity.","zh":"這個片語描述極高彈性。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":6},{"front":"original length","meaning":"原本長度","examples":[{"en":"Capture silk can stretch far beyond its original length.","zh":"捕捉絲可以伸展到遠超其原本長度。"},{"en":"Original length means the length something had before it was stretched or changed.","zh":"original length 指某物被拉伸或改變前的長度。"},{"en":"A rubber band returns close to its original length after being pulled.","zh":"橡筋被拉長後會回到接近原本長度。"},{"en":"If a material cannot return after stretching, it may lose its useful shape.","zh":"如果材料伸展後不能回復，它可能失去有用形狀。"},{"en":"This phrase is used when comparing before and after stretching.","zh":"這個片語用於比較拉伸前後。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":6},{"front":"get entangled in","meaning":"被纏住","examples":[{"en":"Insects get entangled in the sticky web.","zh":"昆蟲被黏性的蛛網纏住。"},{"en":"To get entangled in something means to become caught, trapped, or twisted in it.","zh":"get entangled in something 指被某物捉住、困住或纏繞。"},{"en":"A child’s kite string may get entangled in a tree branch on a windy day.","zh":"大風天，孩子的風箏線可能被樹枝纏住。"},{"en":"If an insect gets entangled in a web, it may be unable to fly away.","zh":"如果昆蟲被蛛網纏住，它可能無法飛走。"},{"en":"This phrase suggests being stuck in something difficult to escape.","zh":"這個片語暗示被困在難以逃脫的東西中。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":6},{"front":"sticky web","meaning":"黏性的蛛網","examples":[{"en":"Insects can become trapped in a sticky web.","zh":"昆蟲可能被困在黏性的蛛網中。"},{"en":"A sticky web is a spider web with adhesive silk that catches insects.","zh":"sticky web 是帶有黏性絲、能捕捉昆蟲的蜘蛛網。"},{"en":"A fly may touch a sticky web and find its legs glued to the silk.","zh":"蒼蠅可能一碰到黏性的蛛網，腳就黏在絲上。"},{"en":"If the web were not sticky, insects might hit it and escape quickly.","zh":"如果蛛網不黏，昆蟲可能撞上後迅速逃脫。"},{"en":"This phrase describes the trapping function of a spider web.","zh":"這個片語描述蜘蛛網的捕捉功能。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":6},{"front":"the stretchiness of","meaning":"……的伸展性","examples":[{"en":"The stretchiness of capture silk lets the web move back and forth.","zh":"捕捉絲的伸展性讓蛛網前後擺動。"},{"en":"The stretchiness of something is its ability to stretch without breaking.","zh":"stretchiness of something 是某物在不斷裂下伸展的能力。"},{"en":"The stretchiness of sports leggings helps people move comfortably during exercise.","zh":"運動緊身褲的伸展性幫助人在運動時舒適活動。"},{"en":"If a web has enough stretchiness, it can absorb impact instead of snapping.","zh":"如果蛛網有足夠伸展性，它就能吸收衝擊而不是斷裂。"},{"en":"This phrase names the elastic quality of a material.","zh":"這個片語指出材料的彈性特質。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":6},{"front":"move back and forth","meaning":"前後擺動","examples":[{"en":"The web can move back and forth after an insect hits it.","zh":"昆蟲撞上後，蛛網可以前後擺動。"},{"en":"To move back and forth means to move repeatedly in one direction and then the opposite direction.","zh":"move back and forth 指反覆朝一個方向，再朝相反方向移動。"},{"en":"A swing moves back and forth when a child pushes it with their feet.","zh":"孩子用腳推鞦韆時，鞦韆會前後擺動。"},{"en":"If a web moves back and forth, it can absorb energy from a fast insect.","zh":"如果蛛網前後擺動，它就能吸收快速昆蟲的能量。"},{"en":"This phrase describes repeated movement between two positions.","zh":"這個片語描述兩個位置之間的反覆移動。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":7},{"front":"bounce off","meaning":"彈開","examples":[{"en":"A stiff web might make the insect bounce off.","zh":"僵硬的蛛網可能令昆蟲彈開。"},{"en":"To bounce off means to hit a surface and spring away from it.","zh":"bounce off 指撞上表面後反彈離開。"},{"en":"A ball may bounce off a wall if it is thrown hard.","zh":"如果球被大力擲出，可能從牆上彈開。"},{"en":"If a web is too stiff, an insect may hit it but not become trapped.","zh":"如果蛛網太硬，昆蟲可能撞上它但不會被困住。"},{"en":"This phrase describes impact followed by moving away.","zh":"這個片語描述撞擊後移開。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":7},{"front":"whereas","meaning":"然而；相比之下","examples":[{"en":"Whereas dragline is stronger, capture silk is more flexible.","zh":"牽引絲更強韌，然而捕捉絲更柔韌。"},{"en":"Whereas introduces a contrast between two facts or situations.","zh":"whereas 引入兩個事實或情況之間的對比。"},{"en":"Whereas one student learns best by listening, another learns best by doing.","zh":"有學生最適合透過聆聽學習，相比之下，另一位最適合透過實踐學習。"},{"en":"If two materials have different strengths, whereas helps compare their roles clearly.","zh":"如果兩種材料有不同優點，whereas 幫助清楚比較其角色。"},{"en":"This word is useful for showing contrast in formal writing.","zh":"這個詞適合在正式寫作中展示對比。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":7},{"front":"more flexible","meaning":"更柔韌；更靈活","examples":[{"en":"Capture silk is more flexible than dragline silk.","zh":"捕捉絲比牽引絲更柔韌。"},{"en":"More flexible means able to bend, stretch, or adapt more easily.","zh":"more flexible 指更容易彎曲、伸展或適應。"},{"en":"A flexible timetable helps working parents study after work.","zh":"靈活時間表幫助在職父母下班後讀書。"},{"en":"If capture silk is more flexible, it can stretch when insects hit the web.","zh":"如果捕捉絲更柔韌，昆蟲撞上蛛網時它就能伸展。"},{"en":"This phrase can describe both physical materials and adaptable plans.","zh":"這個片語可描述物理材料，也可描述靈活計劃。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":7},{"front":"five times more flexible","meaning":"柔韌性高五倍","examples":[{"en":"Capture silk is five times more flexible than dragline silk.","zh":"捕捉絲的柔韌性比牽引絲高五倍。"},{"en":"Five times more flexible means it can bend or stretch far more than the other material.","zh":"five times more flexible 指它比另一種材料更能彎曲或伸展得多。"},{"en":"A new phone case may be five times more flexible than the old one, so it absorbs drops better.","zh":"新手機殼可能比舊手機殼柔韌性高五倍，因此更能吸收跌落衝擊。"},{"en":"If one silk is much more flexible, it may be better for catching fast-moving insects.","zh":"如果一種絲柔韌性高得多，它可能更適合捕捉快速移動昆蟲。"},{"en":"This phrase gives a measured comparison of flexibility.","zh":"這個片語給出柔韌性的量化比較。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":7},{"front":"the orb weaver","meaning":"圓網蛛","examples":[{"en":"The orb weaver’s survival depends on its silk.","zh":"圓網蛛的生存取決於其絲。"},{"en":"The orb weaver is a type of spider that builds round, wheel-like webs.","zh":"orb weaver 是一種建造圓形、輪狀蛛網的蜘蛛。"},{"en":"An orb weaver may rebuild its web after wind or rain damages it.","zh":"圓網蛛可能在風雨損壞蛛網後重新築網。"},{"en":"If the orb weaver’s silk fails, it may catch less food and struggle to survive.","zh":"如果圓網蛛的絲失效，它可能捕到較少食物並難以生存。"},{"en":"This phrase refers to a spider known for circular web-building.","zh":"這個片語指以建造圓形蛛網聞名的蜘蛛。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":7},{"front":"survival depends on","meaning":"生存取決於","examples":[{"en":"The orb weaver’s survival depends on the quality of its silk.","zh":"圓網蛛的生存取決於其絲的質素。"},{"en":"Survival depends on something means staying alive requires that thing.","zh":"survival depends on something 指生存需要某事物。"},{"en":"In winter, a small bird’s survival depends on finding enough food and shelter.","zh":"冬天，小鳥的生存取決於找到足夠食物和庇護。"},{"en":"If a spider cannot make strong silk, it may fail to catch prey.","zh":"如果蜘蛛不能製造強韌的絲，它可能無法捕捉獵物。"},{"en":"This phrase shows that something is essential for life or success.","zh":"這個片語顯示某事物對生命或成功至關重要。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":7},{"front":"400 million years of evolution","meaning":"四億年的進化","examples":[{"en":"Four hundred million years of evolution have shaped spider silk.","zh":"四億年的進化塑造了蜘蛛絲。"},{"en":"Four hundred million years of evolution means an extremely long process of biological change over time.","zh":"400 million years of evolution 指極其漫長的生物變化過程。"},{"en":"The human eye is also the result of a long evolutionary history.","zh":"人眼也是漫長進化歷史的結果。"},{"en":"If a material has been shaped by millions of years of survival pressure, it may be highly efficient.","zh":"如果一種材料受數百萬年生存壓力塑造，它可能非常有效率。"},{"en":"This phrase highlights the deep natural history behind a biological feature.","zh":"這個片語突出某生物特徵背後深厚的自然歷史。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":7},{"front":"fine-tune","meaning":"精細調整；逐步完善","examples":[{"en":"Evolution has fine-tuned spider silk into a tough material.","zh":"進化已把蜘蛛絲精細調整成堅韌材料。"},{"en":"To fine-tune something means to make small adjustments so it works better.","zh":"fine-tune something 指作出細小調整，使其運作得更好。"},{"en":"A teacher may fine-tune a lesson after seeing which examples confuse students.","zh":"老師看到哪些例子令學生困惑後，可能精細調整課堂。"},{"en":"If nature fine-tunes a material over time, tiny improvements can build up into remarkable performance.","zh":"如果自然長時間精細調整一種材料，微小改善可以累積成非凡表現。"},{"en":"This phrase suggests gradual improvement through careful adjustment.","zh":"這個片語暗示透過仔細調整逐步改善。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":7},{"front":"remarkably tough","meaning":"異常堅韌的","examples":[{"en":"Spider silk is a remarkably tough material.","zh":"蜘蛛絲是一種異常堅韌的材料。"},{"en":"Remarkably tough means unusually able to resist damage, force, or breaking.","zh":"remarkably tough 指異常能抵抗損壞、力量或斷裂。"},{"en":"A phone case that survives many drops is remarkably tough.","zh":"能承受多次跌落的手機殼異常堅韌。"},{"en":"If a thin fibre is remarkably tough, it may be useful in protective products.","zh":"如果一條幼細纖維異常堅韌，它可能適合用於防護產品。"},{"en":"This phrase emphasises toughness that is surprising or impressive.","zh":"這個片語強調令人驚訝或印象深刻的韌性。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":7},{"front":"versatile material","meaning":"用途廣泛的物料","examples":[{"en":"Spider silk is a remarkably tough and versatile material.","zh":"蜘蛛絲是一種異常堅韌且用途廣泛的物料。"},{"en":"A versatile material can be used in many different ways or products.","zh":"versatile material 是可以用於許多不同方式或產品的物料。"},{"en":"Plastic is a versatile material because it can become bottles, boxes, toys, and tools.","zh":"塑膠是用途廣泛的物料，因為它可以變成瓶子、盒子、玩具和工具。"},{"en":"If spider silk can be used in medicine, clothing, and safety equipment, it is highly versatile.","zh":"如果蜘蛛絲能用於醫療、服裝和安全設備，它就是高度用途廣泛的。"},{"en":"This phrase focuses on wide usefulness.","zh":"這個片語聚焦於廣泛用途。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":7},{"front":"research groups","meaning":"研究小組","examples":[{"en":"Research groups all over the world are studying spider silk.","zh":"世界各地的研究小組正在研究蜘蛛絲。"},{"en":"Research groups are teams of scientists or scholars working together on a question or project.","zh":"research groups 是一起研究某問題或項目的科學家或學者團隊。"},{"en":"A university research group may study how students learn vocabulary more effectively.","zh":"大學研究小組可能研究學生如何更有效學習詞彙。"},{"en":"If several research groups study the same material, progress may happen faster.","zh":"如果幾個研究小組研究同一材料，進展可能更快。"},{"en":"This phrase refers to organised teams doing research.","zh":"這個片語指有組織的研究團隊。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":8},{"front":"all over the world","meaning":"世界各地","examples":[{"en":"Research groups all over the world are competing to make artificial spider silk.","zh":"世界各地的研究小組正競相製造人造蜘蛛絲。"},{"en":"All over the world means in many countries or regions globally.","zh":"all over the world 指在全球許多國家或地區。"},{"en":"Students all over the world use online videos to learn difficult subjects.","zh":"世界各地的學生使用網上影片學習困難科目。"},{"en":"If scientists all over the world work on a problem, the discovery may have global value.","zh":"如果世界各地的科學家都研究某問題，該發現可能具有全球價值。"},{"en":"This phrase emphasises wide international spread.","zh":"這個片語強調廣泛國際分布。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":8},{"front":"compete to","meaning":"競相……","examples":[{"en":"Scientists are competing to spin the first artificial spider silk.","zh":"科學家正競相紡製第一批人造蜘蛛絲。"},{"en":"To compete to do something means to try to achieve it before or better than others.","zh":"compete to do something 指嘗試比別人更早或更好地完成某事。"},{"en":"Several cafés may compete to attract students by offering cheaper lunches.","zh":"幾間咖啡店可能透過提供較便宜午餐競相吸引學生。"},{"en":"If a scientific breakthrough could be valuable, many labs may compete to reach it first.","zh":"如果科學突破可能很有價值，許多實驗室可能競相率先達成。"},{"en":"This phrase shows rivalry directed toward a goal.","zh":"這個片語顯示朝向某目標的競爭。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":8},{"front":"spin artificial spider silk","meaning":"紡製人造蜘蛛絲","examples":[{"en":"Researchers are trying to spin artificial spider silk.","zh":"研究人員正嘗試紡製人造蜘蛛絲。"},{"en":"To spin artificial spider silk means to turn man-made silk protein into thin fibres like spider silk.","zh":"spin artificial spider silk 指把人造絲蛋白變成像蜘蛛絲一樣的幼細纖維。"},{"en":"A factory spins cotton into thread before weaving it into cloth.","zh":"工廠先把棉花紡成線，再織成布。"},{"en":"If scientists can spin artificial silk properly, they can test whether it matches natural spider silk.","zh":"如果科學家能正確紡製人造絲，他們就能測試它是否能匹敵天然蜘蛛絲。"},{"en":"This phrase describes turning raw material into usable fibre.","zh":"這個片語描述把原材料變成可用纖維。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":8},{"front":"a three-step approach","meaning":"三步驟方法","examples":[{"en":"Making artificial spider silk requires a three-step approach.","zh":"製造人造蜘蛛絲需要三步驟方法。"},{"en":"A three-step approach is a method that breaks a task into three main stages.","zh":"three-step approach 是把任務分成三個主要階段的方法。"},{"en":"A teacher may use a three-step approach to writing: plan, draft, and revise.","zh":"老師可能使用三步驟寫作方法：計劃、起草和修改。"},{"en":"If a difficult project is divided into steps, students can understand what to do first and next.","zh":"如果困難項目被分成步驟，學生就能理解先做甚麼和下一步做甚麼。"},{"en":"This phrase describes an organised process with three parts.","zh":"這個片語描述包含三部分的有組織過程。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":8},{"front":"determine the fibre’s molecular architecture","meaning":"確定纖維的分子結構","examples":[{"en":"Scientists first need to determine the fibre’s molecular architecture.","zh":"科學家首先需要確定纖維的分子結構。"},{"en":"To determine the fibre’s molecular architecture means to identify how its molecules are arranged.","zh":"determine the fibre’s molecular architecture 指識別其分子如何排列。"},{"en":"Doctors may need to determine the structure of a virus before designing a vaccine.","zh":"醫生可能需要確定病毒結構，才能設計疫苗。"},{"en":"If researchers know the molecular architecture, they can understand why the fibre is strong.","zh":"如果研究人員知道分子結構，就能理解纖維為何強韌。"},{"en":"This phrase describes finding the hidden structure of a material.","zh":"這個片語描述找出材料的隱藏結構。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":8},{"front":"molecular architecture","meaning":"分子結構","examples":[{"en":"The molecular architecture of spider silk helps explain its strength.","zh":"蜘蛛絲的分子結構有助解釋其強度。"},{"en":"Molecular architecture means the way molecules are arranged and connected inside a material.","zh":"molecular architecture 指材料內部分子排列和連接的方式。"},{"en":"In a building, architecture controls strength; in a material, molecular architecture does a similar job.","zh":"在建築物中，建築結構控制強度；在材料中，分子結構有類似作用。"},{"en":"If molecules are arranged well, a material may become stronger or more flexible.","zh":"如果分子排列良好，材料可能變得更強韌或更柔韌。"},{"en":"This phrase refers to structure at the molecular level.","zh":"這個片語指分子層面的結構。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":8},{"front":"yield silk proteins","meaning":"產生絲蛋白","examples":[{"en":"Researchers study the genes that yield silk proteins.","zh":"研究人員研究會產生絲蛋白的基因。"},{"en":"To yield silk proteins means to produce the proteins that form silk.","zh":"yield silk proteins 指產生形成絲的蛋白質。"},{"en":"A recipe yields dough when flour, water, and yeast are mixed correctly.","zh":"當麵粉、水和酵母正確混合，食譜會產生麵糰。"},{"en":"If scientists find genes that yield silk proteins, they can try to put those genes into other organisms.","zh":"如果科學家找到產生絲蛋白的基因，就可以嘗試把這些基因放入其他生物。"},{"en":"This phrase describes biological production.","zh":"這個片語描述生物生產。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":8},{"front":"silk proteins","meaning":"絲蛋白","examples":[{"en":"Artificial genes may be used to make silk proteins.","zh":"人造基因可能被用來製造絲蛋白。"},{"en":"Silk proteins are the protein molecules that make up silk fibres.","zh":"silk proteins 是構成絲纖維的蛋白質分子。"},{"en":"In the body, proteins build muscles and tissues; in silk, proteins build strong threads.","zh":"在身體中，蛋白質構成肌肉和組織；在絲中，蛋白質構成強韌絲線。"},{"en":"If silk proteins can be produced in large amounts, artificial silk becomes more realistic.","zh":"如果絲蛋白可以被大量生產，人造絲就變得更現實。"},{"en":"This phrase refers to the biological building blocks of silk.","zh":"這個片語指絲的生物構成單位。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":8},{"front":"raw material","meaning":"原材料","examples":[{"en":"Researchers must learn how to spin the raw material into threads.","zh":"研究人員必須學會如何把原材料紡成線。"},{"en":"Raw material is the basic substance used to make a finished product.","zh":"raw material 是用來製作成品的基本物質。"},{"en":"Flour is a raw material for bread, and cotton is a raw material for fabric.","zh":"麵粉是麵包的原材料，棉花是布料的原材料。"},{"en":"If raw material cannot be processed properly, the final product may fail.","zh":"如果原材料不能被正確加工，最終產品可能失敗。"},{"en":"This phrase refers to the starting material before manufacturing.","zh":"這個片語指製造前的起始材料。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":8},{"front":"spin something into threads","meaning":"把……紡成線","examples":[{"en":"Scientists must learn how to spin the raw material into threads.","zh":"科學家必須學會如何把原材料紡成線。"},{"en":"To spin something into threads means to turn a material into long, thin fibres.","zh":"spin something into threads 指把某種材料變成長而幼的纖維。"},{"en":"A textile factory spins cotton into threads before weaving cloth.","zh":"紡織工廠先把棉花紡成線，再織布。"},{"en":"If proteins cannot be spun into threads, they cannot become useful artificial silk.","zh":"如果蛋白質不能被紡成線，它們就不能成為有用的人造絲。"},{"en":"This phrase describes a key step in making fibres.","zh":"這個片語描述製造纖維的關鍵步驟。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":8},{"front":"be well underway","meaning":"正在順利進行","examples":[{"en":"The first two steps are well underway.","zh":"前兩個步驟正在順利進行。"},{"en":"To be well underway means to have already started and be making clear progress.","zh":"be well underway 指已經開始並取得明顯進展。"},{"en":"The school renovation is well underway if the old walls have been removed and new rooms are being built.","zh":"如果舊牆已拆除，新課室正在建造，學校翻新工程就是正在順利進行。"},{"en":"If research is well underway, scientists have moved beyond the first idea stage.","zh":"如果研究正在順利進行，科學家已超越最初想法階段。"},{"en":"This phrase suggests active progress, not completion.","zh":"這個片語暗示正在積極進展，而不是已完成。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":9},{"front":"molecular structure","meaning":"分子結構","examples":[{"en":"The molecular structure of both dragline and capture silk is known.","zh":"牽引絲和捕捉絲的分子結構都已為人所知。"},{"en":"Molecular structure means the arrangement of atoms and molecules inside a substance.","zh":"molecular structure 指物質內部原子和分子的排列。"},{"en":"Chemistry students study molecular structure to understand why water and oil behave differently.","zh":"化學學生研究分子結構，以理解水和油為何表現不同。"},{"en":"If the molecular structure is known, scientists can try to copy it in artificial materials.","zh":"如果分子結構已知，科學家可以嘗試在人造材料中複製它。"},{"en":"This phrase refers to the small-scale structure that affects material behaviour.","zh":"這個片語指影響材料表現的小尺度結構。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":9},{"front":"clone genes","meaning":"複製基因","examples":[{"en":"Researchers have cloned several genes for the silks.","zh":"研究人員已複製幾個與這些絲有關的基因。"},{"en":"To clone genes means to make copies of specific pieces of genetic information.","zh":"clone genes 指複製特定遺傳資訊片段。"},{"en":"A lab may clone a gene to study what protein it produces.","zh":"實驗室可能複製一個基因，以研究它產生甚麼蛋白質。"},{"en":"If researchers clone silk genes, they can insert copies into other organisms for production.","zh":"如果研究人員複製絲基因，就可以把副本植入其他生物進行生產。"},{"en":"This phrase describes copying genetic instructions.","zh":"這個片語描述複製遺傳指令。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":9},{"front":"unravel protein structure","meaning":"解開蛋白質結構","examples":[{"en":"Scientists have unravelled the protein structure of the silks.","zh":"科學家已解開這些絲的蛋白質結構。"},{"en":"To unravel protein structure means to work out how a protein is built and arranged.","zh":"unravel protein structure 指弄清楚蛋白質如何組成和排列。"},{"en":"Researchers may unravel the structure of a disease protein to design better medicine.","zh":"研究人員可能解開疾病蛋白質結構，以設計更好藥物。"},{"en":"If scientists understand protein structure, they can explain how the material gains its properties.","zh":"如果科學家理解蛋白質結構，他們就能解釋材料如何獲得其特性。"},{"en":"This phrase describes solving a complex biological puzzle.","zh":"這個片語描述解決複雜生物謎題。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":9},{"front":"find hosts for","meaning":"為……尋找宿主","examples":[{"en":"The next step is to find hosts for the artificial genes.","zh":"下一步是為人造基因尋找宿主。"},{"en":"To find hosts for genes means to identify organisms that can carry and express those genes.","zh":"find hosts for genes 指識別能攜帶並表達那些基因的生物。"},{"en":"Scientists may find a host cell for a vaccine protein in order to produce it safely.","zh":"科學家可能為疫苗蛋白尋找宿主細胞，以安全生產它。"},{"en":"If the host organism works well, it can produce the desired protein in useful amounts.","zh":"如果宿主生物運作良好，它就能以有用數量產生所需蛋白質。"},{"en":"This phrase describes choosing a living production system.","zh":"這個片語描述選擇一個活的生產系統。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":9},{"front":"artificial genes","meaning":"人造基因","examples":[{"en":"Scientists have produced artificial genes for spider silk.","zh":"科學家已製造用於蜘蛛絲的人造基因。"},{"en":"Artificial genes are man-made genetic sequences designed to carry particular instructions.","zh":"artificial genes 是人造遺傳序列，被設計來攜帶特定指令。"},{"en":"A lab may design artificial genes to make bacteria produce a useful enzyme.","zh":"實驗室可能設計人造基因，讓細菌產生有用酵素。"},{"en":"If artificial genes are inserted into the right host, the host may make the desired protein.","zh":"如果人造基因被植入合適宿主，宿主可能製造所需蛋白質。"},{"en":"This phrase refers to engineered genetic instructions.","zh":"這個片語指經工程設計的遺傳指令。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":9},{"front":"plants and fungi","meaning":"植物和真菌","examples":[{"en":"Plants and fungi are being considered as hosts for silk genes.","zh":"植物和真菌正被考慮作為絲基因的宿主。"},{"en":"Plants and fungi are living organisms that may be used to produce proteins in biotechnology.","zh":"plants and fungi 是可在生物技術中用來生產蛋白質的生物。"},{"en":"Yeast, a kind of fungus, is often used to make bread and can also be used in laboratories.","zh":"酵母是一種真菌，常用於製作麵包，也可用於實驗室。"},{"en":"If plants or fungi can make silk protein, production may become cheaper or easier.","zh":"如果植物或真菌能製造絲蛋白，生產可能變得更便宜或更容易。"},{"en":"This phrase names possible biological hosts.","zh":"這個片語指出可能的生物宿主。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":9},{"front":"as well as bacteria","meaning":"以及細菌","examples":[{"en":"Plants and fungi, as well as bacteria, are being considered.","zh":"植物和真菌，以及細菌，正被考慮。"},{"en":"As well as bacteria means bacteria are included in addition to the other things mentioned.","zh":"as well as bacteria 指除了前面提到的事物外，也包括細菌。"},{"en":"A science project may use plants as well as bacteria to study growth under different conditions.","zh":"科學項目可能使用植物以及細菌，研究不同條件下的生長。"},{"en":"If several hosts are considered, researchers can compare which one produces protein best.","zh":"如果考慮幾種宿主，研究人員可以比較哪一種最能生產蛋白質。"},{"en":"This phrase adds bacteria to a list of possibilities.","zh":"這個片語把細菌加入可能性列表。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":9},{"front":"be considered","meaning":"被考慮","examples":[{"en":"Bacteria are being considered as hosts for artificial genes.","zh":"細菌正被考慮作為人造基因的宿主。"},{"en":"To be considered means to be thought about as a possible choice or solution.","zh":"be considered 指被視為可能選擇或解決方法來思考。"},{"en":"A new timetable may be considered if students keep arriving late.","zh":"如果學生經常遲到，新時間表可能被考慮。"},{"en":"If a method is being considered, it has not necessarily been chosen yet.","zh":"如果某方法正被考慮，它不一定已被選定。"},{"en":"This phrase shows that something is under serious discussion.","zh":"這個片語顯示某事正在被認真討論。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":9},{"front":"a hardy plant","meaning":"生命力強的植物","examples":[{"en":"A hardy plant could express a dragline silk gene.","zh":"生命力強的植物可以表達牽引絲基因。"},{"en":"A hardy plant is a plant that can survive difficult conditions such as cold, heat, or poor soil.","zh":"hardy plant 是能在寒冷、高溫或貧瘠土壤等困難條件下生存的植物。"},{"en":"A school garden may use hardy plants because students cannot water them every day.","zh":"學校花園可能使用生命力強的植物，因為學生不能每天澆水。"},{"en":"If a hardy plant can produce silk protein, it may survive well during large-scale farming.","zh":"如果生命力強的植物能生產絲蛋白，它在大規模種植中可能生存良好。"},{"en":"This phrase describes a strong and resilient plant.","zh":"這個片語描述強健而有韌性的植物。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":9},{"front":"express a gene","meaning":"表達基因","examples":[{"en":"A plant might express a dragline silk gene.","zh":"植物可能表達牽引絲基因。"},{"en":"To express a gene means to use the information in a gene to produce a protein or trait.","zh":"express a gene 指使用基因中的資訊來產生蛋白質或特徵。"},{"en":"In biology class, students learn that genes are expressed when cells make the proteins they code for.","zh":"在生物課中，學生學到細胞製造基因所編碼的蛋白質時，就是基因被表達。"},{"en":"If a plant expresses a silk gene, it may produce silk protein inside its tissues.","zh":"如果植物表達絲基因，它可能在組織中產生絲蛋白。"},{"en":"This phrase describes a gene becoming active in a living cell.","zh":"這個片語描述基因在活細胞中變得活躍。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":9},{"front":"dragline silk gene","meaning":"牽引絲基因","examples":[{"en":"A dragline silk gene could be inserted into another organism.","zh":"牽引絲基因可以被植入另一種生物。"},{"en":"A dragline silk gene is genetic information that codes for protein used in dragline silk.","zh":"dragline silk gene 是編碼牽引絲所用蛋白質的遺傳資訊。"},{"en":"A scientist may study a dragline silk gene to understand how spiders make strong silk.","zh":"科學家可能研究牽引絲基因，以理解蜘蛛如何製造強韌絲。"},{"en":"If this gene works in another organism, that organism may produce silk protein.","zh":"如果這個基因在另一種生物中運作，該生物可能產生絲蛋白。"},{"en":"This phrase refers to the genetic instruction for one type of spider silk.","zh":"這個片語指某一類蜘蛛絲的遺傳指令。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":10},{"front":"be harvested in large quantities","meaning":"被大量收集","examples":[{"en":"Silk proteins could eventually be harvested in large quantities.","zh":"絲蛋白最終可以被大量收集。"},{"en":"To be harvested in large quantities means to be collected in large amounts after being produced or grown.","zh":"be harvested in large quantities 指在被生產或生長後大量收集。"},{"en":"Rice is harvested in large quantities during the main farming season.","zh":"水稻在主要農季會被大量收割。"},{"en":"If silk proteins can be harvested in large quantities, commercial production becomes more possible.","zh":"如果絲蛋白可以被大量收集，商業化生產就變得更可能。"},{"en":"This phrase describes large-scale collection of useful material.","zh":"這個片語描述有用材料的大規模收集。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":10},{"front":"processed into","meaning":"被加工成","examples":[{"en":"The proteins could be processed into a liquid polymer.","zh":"這些蛋白質可以被加工成液態聚合物。"},{"en":"To be processed into something means to be treated or changed into a new form.","zh":"processed into something 指被處理或改變成新的形式。"},{"en":"Milk can be processed into cheese, yoghurt, or butter.","zh":"牛奶可以被加工成芝士、乳酪或牛油。"},{"en":"If silk protein is processed correctly, it can become material suitable for spinning fibres.","zh":"如果絲蛋白被正確加工，它可以變成適合紡成纖維的材料。"},{"en":"This phrase describes transformation during manufacturing.","zh":"這個片語描述製造過程中的轉化。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":10},{"front":"liquid polymer","meaning":"液態聚合物","examples":[{"en":"Silk proteins could be processed into a liquid polymer.","zh":"絲蛋白可以被加工成液態聚合物。"},{"en":"A liquid polymer is a liquid material made of long repeating molecular chains.","zh":"liquid polymer 是由長而重複的分子鏈構成的液態材料。"},{"en":"Some glues begin as liquid polymers and harden after they are applied.","zh":"一些膠水開始時是液態聚合物，塗上後會硬化。"},{"en":"If silk protein becomes a liquid polymer, factories may be able to spin it into fibres.","zh":"如果絲蛋白變成液態聚合物，工廠可能能把它紡成纖維。"},{"en":"This phrase refers to a chemical form useful in manufacturing.","zh":"這個片語指製造中有用的化學形態。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":10},{"front":"spun into fibres","meaning":"被紡成纖維","examples":[{"en":"The liquid polymer could be spun into fibres in factories.","zh":"液態聚合物可以在工廠中被紡成纖維。"},{"en":"To be spun into fibres means to be turned into long, thin strands for practical use.","zh":"spun into fibres 指被轉化成可實際使用的長而幼的絲縷。"},{"en":"Plastic can be spun into fibres to make clothing, carpets, or ropes.","zh":"塑膠可以被紡成纖維來製作衣物、地氈或繩索。"},{"en":"If a liquid polymer cannot be spun evenly, the fibres may be weak or uneven.","zh":"如果液態聚合物不能均勻紡製，纖維可能脆弱或不均。"},{"en":"This phrase describes turning material into thread-like form.","zh":"這個片語描述把材料變成線狀形態。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":10},{"front":"experimental approach","meaning":"實驗性方法","examples":[{"en":"A different experimental approach is to insert the web gene into goats.","zh":"一種不同的實驗性方法是把蛛網基因植入山羊。"},{"en":"An experimental approach is a method being tested to see whether it works.","zh":"experimental approach 是正在測試是否有效的方法。"},{"en":"A teacher may try an experimental approach by using games to teach difficult grammar.","zh":"老師可能嘗試用遊戲教授困難文法作為實驗性方法。"},{"en":"If an experimental approach succeeds, it may become a standard method later.","zh":"如果實驗性方法成功，它之後可能成為標準方法。"},{"en":"This phrase suggests trial, testing, and uncertainty.","zh":"這個片語暗示試驗、測試和不確定性。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":10},{"front":"insert the web gene into","meaning":"把蛛網基因植入……","examples":[{"en":"Researchers may insert the web gene into goats.","zh":"研究人員可能把蛛網基因植入山羊。"},{"en":"To insert the web gene into an organism means to place spider-silk genetic instructions into that organism.","zh":"insert the web gene into an organism 指把蜘蛛絲遺傳指令放入該生物。"},{"en":"Scientists can insert a useful gene into bacteria so the bacteria produce a medicine.","zh":"科學家可以把有用基因植入細菌，讓細菌生產藥物。"},{"en":"If the gene is inserted successfully, the host may make the protein researchers want.","zh":"如果基因成功植入，宿主可能製造研究人員想要的蛋白質。"},{"en":"This phrase describes genetic engineering.","zh":"這個片語描述基因工程。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":10},{"front":"collect the protein from","meaning":"從……收集蛋白質","examples":[{"en":"Scientists hope to collect the protein from the goats’ milk.","zh":"科學家希望從山羊奶中收集蛋白質。"},{"en":"To collect the protein from something means to obtain and separate the desired protein from that source.","zh":"collect the protein from something 指從某來源取得並分離所需蛋白質。"},{"en":"A lab may collect a useful enzyme from a liquid culture after bacteria produce it.","zh":"細菌生產酵素後，實驗室可能從液體培養物中收集有用酵素。"},{"en":"If goats’ milk contains silk protein, researchers can extract it for further processing.","zh":"如果山羊奶含有絲蛋白，研究人員可以提取它作進一步加工。"},{"en":"This phrase describes obtaining a useful biological product.","zh":"這個片語描述取得有用生物產品。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":10},{"front":"goats’ milk","meaning":"山羊奶","examples":[{"en":"Researchers may collect silk protein from goats’ milk.","zh":"研究人員可能從山羊奶中收集絲蛋白。"},{"en":"Goats’ milk is milk produced by female goats.","zh":"goats’ milk 是母山羊產生的奶。"},{"en":"Some families drink goats’ milk when they prefer it to cow’s milk.","zh":"有些家庭在較喜歡山羊奶時會飲用它，而不是牛奶。"},{"en":"If goats are engineered to produce silk protein, their milk may become a source of industrial material.","zh":"如果山羊被工程改造以生產絲蛋白，其奶可能成為工業材料來源。"},{"en":"This phrase refers to milk from goats, not milk for goats.","zh":"這個片語指來自山羊的奶，而不是給山羊喝的奶。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":10},{"front":"instead of","meaning":"而不是","examples":[{"en":"Goats are being used instead of bacteria.","zh":"山羊正被使用，而不是細菌。"},{"en":"Instead of means one thing is used or chosen in place of another.","zh":"instead of 指一事物被用來或被選擇來取代另一事物。"},{"en":"A student may take the bus instead of walking when it rains heavily.","zh":"下大雨時，學生可能坐巴士而不是步行。"},{"en":"If bacteria do not produce silk protein properly, researchers may try goats instead.","zh":"如果細菌不能正確產生絲蛋白，研究人員可能改用山羊。"},{"en":"This phrase shows replacement or contrast between choices.","zh":"這個片語顯示選擇之間的取代或對比。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":10},{"front":"much cheaper bacteria","meaning":"便宜得多的細菌","examples":[{"en":"Bacteria are simpler and much cheaper than goats.","zh":"細菌比山羊更簡單且便宜得多。"},{"en":"Much cheaper bacteria means bacteria cost far less to use or maintain than another option.","zh":"much cheaper bacteria 指使用或維持細菌的成本遠低於另一選項。"},{"en":"A school may choose a much cheaper online tool if an expensive platform is not necessary.","zh":"如果昂貴平台不是必要，學校可能選擇便宜得多的網上工具。"},{"en":"If bacteria were effective, they would be attractive because they are cheaper and easier to grow.","zh":"如果細菌有效，它們會很吸引，因為它們更便宜也更容易培養。"},{"en":"This phrase compares cost strongly.","zh":"這個片語強烈比較成本。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":10},{"front":"the secret of","meaning":"……的奧秘","examples":[{"en":"The secret of the protein’s strength lies in how the molecules cross-link.","zh":"蛋白質強度的奧秘在於分子如何交聯。"},{"en":"The secret of something means the hidden reason behind its success, power, or special quality.","zh":"secret of something 指某事成功、力量或特殊質素背後的隱藏原因。"},{"en":"The secret of a good lesson may be clear examples and enough practice.","zh":"好課堂的奧秘可能是清楚例子和足夠練習。"},{"en":"If scientists discover the secret of silk’s strength, they can try to copy it.","zh":"如果科學家發現絲強度的奧秘，就可以嘗試複製它。"},{"en":"This phrase points to the key explanation behind something impressive.","zh":"這個片語指出令人印象深刻之事背後的關鍵解釋。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":11},{"front":"lie in","meaning":"在於","examples":[{"en":"The protein’s strength lies in the way its molecules cross-link.","zh":"蛋白質的強度在於其分子交聯的方式。"},{"en":"To lie in something means to be found in or depend on that thing.","zh":"lie in something 指存在於某事之中或取決於某事。"},{"en":"The success of a small café may lie in friendly service rather than fancy decoration.","zh":"小咖啡店的成功可能在於友善服務，而不是華麗裝修。"},{"en":"If silk’s strength lies in molecular links, copying the protein alone may not be enough.","zh":"如果絲的強度在於分子連結，單靠複製蛋白質可能不足夠。"},{"en":"This phrase identifies the true source of a quality or result.","zh":"這個片語指出某種特質或結果的真正來源。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":11},{"front":"molecules","meaning":"分子","examples":[{"en":"The strength of silk depends on how its molecules connect.","zh":"絲的強度取決於其分子如何連接。"},{"en":"Molecules are tiny groups of atoms joined together to form substances.","zh":"molecules 是由原子結合而成、形成物質的微小組合。"},{"en":"Water molecules are made of hydrogen and oxygen atoms.","zh":"水分子由氫原子和氧原子組成。"},{"en":"If molecules are arranged differently, the same basic material may behave differently.","zh":"如果分子排列不同，同一種基本材料可能表現不同。"},{"en":"This word refers to extremely small building blocks of matter.","zh":"這個詞指物質的極小構成單位。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":11},{"front":"cross-link with one another","meaning":"互相交聯","examples":[{"en":"The molecules need to cross-link with one another properly.","zh":"分子需要正確地互相交聯。"},{"en":"To cross-link with one another means to form connecting bonds between separate molecules.","zh":"cross-link with one another 指不同分子之間形成連接鍵。"},{"en":"In some plastics, molecules cross-link to make the material harder and stronger.","zh":"在一些塑膠中，分子會交聯，使材料更硬更強。"},{"en":"If silk molecules cross-link properly, the fibre can become strong and tough.","zh":"如果絲分子正確交聯，纖維可以變得強韌。"},{"en":"This phrase describes molecules joining into a stronger network.","zh":"這個片語描述分子連成更強網絡。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":11},{"front":"fold in a way that","meaning":"以某種方式摺疊，以致……","examples":[{"en":"In bacteria, the protein folds in a way that prevents proper cross-linking.","zh":"在細菌中，蛋白質以某種方式摺疊，以致阻止正確交聯。"},{"en":"To fold in a way that causes something means a protein takes a shape that leads to a particular result.","zh":"fold in a way that causes something 指蛋白質形成某種形狀，並導致特定結果。"},{"en":"If clothes are folded in a way that traps moisture, they may smell bad later.","zh":"如果衣服以某種方式摺疊而困住濕氣，之後可能有異味。"},{"en":"If a protein folds incorrectly, it may not connect with other molecules as needed.","zh":"如果蛋白質摺疊不正確，它可能無法按需要與其他分子連接。"},{"en":"This phrase shows how shape affects function.","zh":"這個片語顯示形狀如何影響功能。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":11},{"front":"prevent it from","meaning":"阻止它……","examples":[{"en":"The protein folds in a way that prevents it from cross-linking properly.","zh":"蛋白質以某種方式摺疊，阻止它正確交聯。"},{"en":"To prevent it from doing something means to stop it from happening or functioning in that way.","zh":"prevent it from doing something 指阻止某事發生或阻止它以某方式運作。"},{"en":"A phone case can prevent a phone from cracking when it falls.","zh":"手機殼可以阻止手機跌落時裂開。"},{"en":"If a protein’s shape prevents proper linking, the final material may be weak.","zh":"如果蛋白質形狀阻止正確連接，最終材料可能脆弱。"},{"en":"This phrase shows that one factor blocks an action or result.","zh":"這個片語顯示一個因素阻礙行動或結果。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":11},{"front":"cross-link properly","meaning":"正確交聯","examples":[{"en":"The protein must cross-link properly to become strong.","zh":"蛋白質必須正確交聯才會變得強韌。"},{"en":"To cross-link properly means to form the right molecular connections in the right way.","zh":"cross-link properly 指以正確方式形成正確的分子連接。"},{"en":"Glue must bond properly, or the broken chair will come apart again.","zh":"膠水必須正確黏合，否則破椅子會再次散開。"},{"en":"If silk proteins do not cross-link properly, they may form useless lumps instead of fibres.","zh":"如果絲蛋白沒有正確交聯，它們可能形成無用塊狀物，而不是纖維。"},{"en":"This phrase describes correct molecular joining.","zh":"這個片語描述正確的分子結合。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":11},{"front":"resulting in","meaning":"導致","examples":[{"en":"The failed cross-linking results in hard white lumps.","zh":"交聯失敗導致硬白塊。"},{"en":"Resulting in means causing something to happen as a consequence.","zh":"resulting in 指作為結果造成某事發生。"},{"en":"Heavy rain may flood roads, resulting in bus delays.","zh":"大雨可能淹浸道路，導致巴士延誤。"},{"en":"If protein folding fails, it can result in material that cannot be spun into fibres.","zh":"如果蛋白質摺疊失敗，可能導致材料不能被紡成纖維。"},{"en":"This phrase connects a cause with its outcome.","zh":"這個片語把原因與結果連接起來。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":11},{"front":"hard white lumps","meaning":"硬白塊","examples":[{"en":"Artificial silk protein made in bacteria may form hard white lumps.","zh":"在細菌中製造的人造絲蛋白可能形成硬白塊。"},{"en":"Hard white lumps are solid white pieces that form instead of a smooth or usable material.","zh":"hard white lumps 是形成的白色固體塊，而不是順滑或可用材料。"},{"en":"If flour is not mixed properly, hard lumps may appear in the sauce.","zh":"如果麵粉沒有正確混合，醬汁中可能出現硬塊。"},{"en":"If silk protein forms lumps, it cannot easily be spun into fine thread.","zh":"如果絲蛋白形成塊狀，就難以被紡成細線。"},{"en":"This phrase shows a failed production result.","zh":"這個片語顯示失敗的生產結果。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":11},{"front":"in a manner similar to","meaning":"以類似……的方式","examples":[{"en":"The spider makes protein in a manner similar to mammals making milk.","zh":"蜘蛛以類似哺乳類動物製造乳汁的方式製造蛋白質。"},{"en":"In a manner similar to means in a way that is like another process or action.","zh":"in a manner similar to 指以類似另一過程或行動的方式。"},{"en":"Online teachers may give feedback in a manner similar to face-to-face tutors, but through comments and video calls.","zh":"網上老師可能以類似面授導師的方式給回饋，但透過評語和視像通話。"},{"en":"If two biological systems work similarly, scientists may use one to imitate the other.","zh":"如果兩個生物系統運作相似，科學家可能用其中一個模仿另一個。"},{"en":"This phrase introduces a comparison of methods.","zh":"這個片語引入方法上的比較。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":11},{"front":"the way mammals make milk","meaning":"哺乳類動物製造乳汁的方式","examples":[{"en":"The spider makes protein in a manner similar to the way mammals make milk.","zh":"蜘蛛以類似哺乳類動物製造乳汁的方式製造蛋白質。"},{"en":"The way mammals make milk refers to how animals such as goats or cows produce milk in mammary glands.","zh":"the way mammals make milk 指山羊或牛等動物如何在乳腺中製造乳汁。"},{"en":"Farmers collect milk from cows because mammals naturally produce it to feed their young.","zh":"農夫從牛身上收集牛奶，因為哺乳類動物自然產奶餵養幼崽。"},{"en":"If goats make silk protein in a similar system, the protein may fold more correctly.","zh":"如果山羊在類似系統中製造絲蛋白，蛋白質可能更正確地摺疊。"},{"en":"This phrase compares spider protein production with a familiar animal process.","zh":"這個片語把蜘蛛蛋白質生產與熟悉的動物過程比較。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":11},{"front":"mammary glands","meaning":"乳腺","examples":[{"en":"Researchers hope the protein made in goats’ mammary glands will cross-link properly.","zh":"研究人員希望在山羊乳腺中製造的蛋白質會正確交聯。"},{"en":"Mammary glands are organs in mammals that produce milk.","zh":"mammary glands 是哺乳類動物中產生乳汁的器官。"},{"en":"Cows and goats have mammary glands that farmers use as a milk source.","zh":"牛和山羊有乳腺，農夫利用它們作為乳源。"},{"en":"If silk protein is made in mammary glands, it may behave more like protein produced in a natural gland system.","zh":"如果絲蛋白在乳腺中製造，它可能表現得更像在天然腺體系統中產生的蛋白質。"},{"en":"This phrase belongs to biology and animal physiology.","zh":"這個片語屬於生物學和動物生理學。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":12},{"front":"be extracted from","meaning":"從……提取","examples":[{"en":"The protein must be extracted from the goats’ milk.","zh":"蛋白質必須從山羊奶中提取。"},{"en":"To be extracted from something means to be removed or separated from that source.","zh":"be extracted from something 指從某來源中移除或分離出來。"},{"en":"Juice can be extracted from oranges by squeezing them.","zh":"橙汁可以透過榨橙從橙中提取。"},{"en":"If silk protein is extracted successfully, it can be purified and processed into fibres.","zh":"如果絲蛋白被成功提取，它可以被純化並加工成纖維。"},{"en":"This phrase describes taking a useful substance out of a mixture.","zh":"這個片語描述從混合物中取出有用物質。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":12},{"front":"find a way to","meaning":"找到方法去","examples":[{"en":"The next step is to find a way to spin the protein.","zh":"下一步是找到方法去紡製蛋白質。"},{"en":"To find a way to do something means to discover a method for doing it.","zh":"find a way to do something 指發現做某事的方法。"},{"en":"A student who struggles with vocabulary may find a way to remember words through examples.","zh":"對詞彙吃力的學生可能透過例句找到記字方法。"},{"en":"If scientists cannot find a way to spin the protein, artificial silk remains incomplete.","zh":"如果科學家不能找到方法去紡製蛋白質，人造絲仍不完整。"},{"en":"This phrase shows a problem that still needs a solution.","zh":"這個片語顯示仍需要解決的問題。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":12},{"front":"environmentally friendly ways","meaning":"環保的方式","examples":[{"en":"Spiders make their silk in environmentally friendly ways.","zh":"蜘蛛以環保的方式製造牠們的絲。"},{"en":"Environmentally friendly ways are methods that cause little harm to the environment.","zh":"environmentally friendly ways 是對環境造成較少傷害的方法。"},{"en":"A school can use environmentally friendly ways to reduce waste, such as reusing paper and saving electricity.","zh":"學校可以使用環保方式減少浪費，例如重用紙張和節省電力。"},{"en":"If manufacturing uses water-based methods, it may create less pollution than petroleum-based production.","zh":"如果製造使用水基方法，它可能比石油基生產造成較少污染。"},{"en":"This phrase describes cleaner and more sustainable methods.","zh":"這個片語描述較清潔和更可持續的方法。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":12},{"front":"process proteins","meaning":"加工蛋白質","examples":[{"en":"Spiders process proteins from water-based solutions.","zh":"蜘蛛從水基溶液中加工蛋白質。"},{"en":"To process proteins means to treat or transform proteins into a useful form.","zh":"process proteins 指處理或轉化蛋白質，使其成為有用形式。"},{"en":"A food factory processes milk proteins when making cheese.","zh":"食品工廠製作芝士時會加工牛奶蛋白質。"},{"en":"If spider proteins are processed correctly, they become strong silk fibres.","zh":"如果蜘蛛蛋白質被正確加工，它們就會變成強韌絲纖維。"},{"en":"This phrase describes changing proteins through a biological or manufacturing process.","zh":"這個片語描述透過生物或製造過程改變蛋白質。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":12},{"front":"water-based solutions","meaning":"水基溶液","examples":[{"en":"Spider silk is made from water-based solutions.","zh":"蜘蛛絲由水基溶液製成。"},{"en":"Water-based solutions are liquid mixtures in which water is the main solvent.","zh":"water-based solutions 是以水作為主要溶劑的液體混合物。"},{"en":"Many school paints are water-based solutions because they are easier to clean and safer to use.","zh":"許多學校顏料是水基溶液，因為它們較易清洗且較安全使用。"},{"en":"If fibre production uses water-based solutions, it may avoid harmful organic solvents.","zh":"如果纖維生產使用水基溶液，它可能避免有害有機溶劑。"},{"en":"This phrase contrasts water-based liquids with oil-based or solvent-based ones.","zh":"這個片語把水基液體與油基或溶劑基液體作對比。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":12},{"front":"from a manufacturing point of view","meaning":"從製造角度來看","examples":[{"en":"From a manufacturing point of view, the spider’s method is very attractive.","zh":"從製造角度來看，蜘蛛的方法非常吸引。"},{"en":"From a manufacturing point of view means when considered in terms of production, cost, safety, and practicality.","zh":"from a manufacturing point of view 指從生產、成本、安全和實用性方面考慮。"},{"en":"From a manufacturing point of view, a design that uses fewer parts may be cheaper to produce.","zh":"從製造角度來看，使用較少零件的設計可能較便宜。"},{"en":"If a natural process avoids pollution and expensive chemicals, manufacturers may want to copy it.","zh":"如果天然過程避免污染和昂貴化學品，製造商可能想複製它。"},{"en":"This phrase shifts the focus to practical production concerns.","zh":"這個片語把焦點轉向實際生產考慮。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":12},{"front":"very attractive","meaning":"非常吸引","examples":[{"en":"The spider’s silk-making process is very attractive to manufacturers.","zh":"蜘蛛製絲過程對製造商非常吸引。"},{"en":"Very attractive means highly appealing or useful to someone.","zh":"very attractive 指對某人非常有吸引力或有用。"},{"en":"A flexible work schedule may be very attractive to parents with young children.","zh":"靈活工作時間表可能對有幼兒的父母非常吸引。"},{"en":"If a production method is cheap, clean, and efficient, it becomes very attractive to industry.","zh":"如果生產方法便宜、清潔又有效率，它對產業便非常吸引。"},{"en":"This phrase describes strong interest or appeal.","zh":"這個片語描述強烈興趣或吸引力。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":12},{"front":"synthetic fibres","meaning":"合成纖維","examples":[{"en":"Nylon is one example of a synthetic fibre.","zh":"尼龍是一種合成纖維的例子。"},{"en":"Synthetic fibres are man-made fibres produced through chemical or industrial processes.","zh":"synthetic fibres 是透過化學或工業過程製造的人造纖維。"},{"en":"Polyester and nylon are synthetic fibres commonly used in clothes and bags.","zh":"聚酯和尼龍是衣服和袋中常用的合成纖維。"},{"en":"If synthetic fibres are strong and cheap, manufacturers may choose them over natural fibres.","zh":"如果合成纖維強韌又便宜，製造商可能選擇它們而不是天然纖維。"},{"en":"This phrase contrasts artificial fibres with fibres from plants or animals.","zh":"這個片語把人造纖維與來自植物或動物的纖維作對比。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":12},{"front":"on the other hand","meaning":"另一方面","examples":[{"en":"Synthetic fibres, on the other hand, require petroleum products or organic solvents.","zh":"另一方面，合成纖維需要石油產品或有機溶劑。"},{"en":"On the other hand introduces a contrasting point or different side of an argument.","zh":"on the other hand 引入對比點或論點的另一面。"},{"en":"Online lessons are flexible; on the other hand, some students miss face-to-face discussion.","zh":"網上課堂很靈活；另一方面，一些學生會想念面對面討論。"},{"en":"If natural silk is clean to produce, synthetic fibres may still create pollution problems.","zh":"如果天然絲生產較清潔，合成纖維仍可能造成污染問題。"},{"en":"This phrase helps compare two sides clearly.","zh":"這個片語幫助清楚比較兩面。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":12},{"front":"petroleum products","meaning":"石油產品","examples":[{"en":"Making nylon requires petroleum products.","zh":"製造尼龍需要石油產品。"},{"en":"Petroleum products are materials made from crude oil, such as fuels, plastics, and some chemical ingredients.","zh":"petroleum products 是由原油製成的材料，例如燃料、塑膠和一些化學成分。"},{"en":"Petrol used in cars is one common petroleum product.","zh":"汽車使用的汽油是一種常見石油產品。"},{"en":"If fibre production depends on petroleum products, it may contribute to pollution and fossil-fuel use.","zh":"如果纖維生產依賴石油產品，它可能造成污染並使用化石燃料。"},{"en":"This phrase refers to oil-based industrial materials.","zh":"這個片語指石油基工業材料。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":12},{"front":"organic solvents","meaning":"有機溶劑","examples":[{"en":"The production of synthetic fibres may require organic solvents.","zh":"合成纖維生產可能需要有機溶劑。"},{"en":"Organic solvents are chemical liquids used to dissolve other substances, often in industrial processes.","zh":"organic solvents 是用來溶解其他物質的化學液體，常見於工業過程。"},{"en":"Paint remover may contain organic solvents that should be used with good ventilation.","zh":"除漆劑可能含有有機溶劑，應在通風良好處使用。"},{"en":"If factories use harmful solvents, workers and the environment may face risks.","zh":"如果工廠使用有害溶劑，工人和環境可能面對風險。"},{"en":"This phrase refers to chemical liquids that can create safety and pollution concerns.","zh":"這個片語指可能造成安全和污染問題的化學液體。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":13},{"front":"result in pollution","meaning":"導致污染","examples":[{"en":"The process of making nylon can result in pollution.","zh":"製造尼龍的過程可能導致污染。"},{"en":"To result in pollution means to cause harmful substances to enter the air, water, or land.","zh":"result in pollution 指造成有害物質進入空氣、水或土地。"},{"en":"Poor waste management can result in pollution in rivers and beaches.","zh":"差劣廢物管理可能導致河流和海灘污染。"},{"en":"If fibre production uses harmful chemicals, it may damage the environment.","zh":"如果纖維生產使用有害化學品，可能損害環境。"},{"en":"This phrase links an activity with environmental harm.","zh":"這個片語把某活動與環境傷害連接起來。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":13},{"front":"biotechnologists","meaning":"生物技術學家","examples":[{"en":"Biotechnologists are motivated by the potential of artificial spider silk.","zh":"生物技術學家受人造蜘蛛絲的潛力推動。"},{"en":"Biotechnologists are scientists who use living organisms, cells, or biological systems to create useful products.","zh":"biotechnologists 是使用生物、細胞或生物系統創造有用產品的科學家。"},{"en":"A biotechnologist may work on vaccines, crop improvement, or medical proteins.","zh":"生物技術學家可能研究疫苗、農作物改良或醫療蛋白質。"},{"en":"If spider silk can be made through living systems, biotechnologists play an important role.","zh":"如果蜘蛛絲能透過生物系統製造，生物技術學家就扮演重要角色。"},{"en":"This word refers to experts who apply biology to technology.","zh":"這個詞指把生物學應用於科技的專家。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":13},{"front":"be motivated by","meaning":"受……推動","examples":[{"en":"Biotechnologists are motivated by the practical and economic potential of spider silk.","zh":"生物技術學家受蜘蛛絲的實用及經濟潛力推動。"},{"en":"To be motivated by something means to be encouraged or driven by it.","zh":"be motivated by something 指受到某事鼓勵或驅使。"},{"en":"A student may be motivated by a scholarship to study harder.","zh":"學生可能受獎學金推動而更努力讀書。"},{"en":"If researchers see both scientific challenge and market value, they may work more intensely.","zh":"如果研究人員看到科學挑戰和市場價值，他們可能工作得更投入。"},{"en":"This phrase explains what pushes someone to act.","zh":"這個片語解釋甚麼推動某人行動。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":13},{"front":"practical and economic potential","meaning":"實用及經濟潛力","examples":[{"en":"Artificial spider silk has practical and economic potential.","zh":"人造蜘蛛絲具有實用及經濟潛力。"},{"en":"Practical and economic potential means possible real-world uses and possible financial value.","zh":"practical and economic potential 指可能有現實用途和財務價值。"},{"en":"A new battery with longer life has practical and economic potential for phones and electric cars.","zh":"壽命更長的新電池對手機和電動車有實用及經濟潛力。"},{"en":"If a material can solve real problems and sell well, companies will invest in it.","zh":"如果材料能解決真實問題並有良好銷售，公司會投資它。"},{"en":"This phrase combines usefulness with market value.","zh":"這個片語結合實用性與市場價值。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":13},{"front":"generate artificial spider silk","meaning":"製造人造蜘蛛絲","examples":[{"en":"Researchers hope to generate artificial spider silk.","zh":"研究人員希望製造人造蜘蛛絲。"},{"en":"To generate artificial spider silk means to produce man-made spider-like silk through technology or biology.","zh":"generate artificial spider silk 指透過科技或生物方法生產人造、類似蜘蛛絲的材料。"},{"en":"A lab can generate small samples of a new material before a factory tries mass production.","zh":"實驗室可以先製造新材料的小樣本，再由工廠嘗試大量生產。"},{"en":"If researchers generate enough silk protein, they can test its strength and flexibility.","zh":"如果研究人員製造出足夠絲蛋白，就可以測試其強度和柔韌性。"},{"en":"This phrase describes producing the material, not merely studying it.","zh":"這個片語描述生產材料，而不只是研究它。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":13},{"front":"globally","meaning":"在全球而言","examples":[{"en":"Globally, many clothing threads come from natural fibres.","zh":"在全球而言，許多衣物線材來自天然纖維。"},{"en":"Globally means around the world or in the world as a whole.","zh":"globally 指在世界各地或從全世界整體來看。"},{"en":"Globally, students are using more online tools than they did ten years ago.","zh":"在全球而言，學生比十年前使用更多網上工具。"},{"en":"If a material is used globally, even small improvements can affect many industries.","zh":"如果材料在全球使用，即使小改善也能影響許多行業。"},{"en":"This word frames a statement at the worldwide level.","zh":"這個詞把陳述放在全球層面。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":13},{"front":"as much as 60 per cent","meaning":"多達百分之六十","examples":[{"en":"As much as 60 per cent of clothing threads come from natural fibres.","zh":"多達百分之六十的衣物線材來自天然纖維。"},{"en":"As much as 60 per cent means up to 60 per cent, often suggesting the number is large.","zh":"as much as 60 per cent 指高達百分之六十，常暗示數字很大。"},{"en":"As much as 60 per cent of a student’s mark may come from coursework in some courses.","zh":"在一些課程中，學生分數多達百分之六十可能來自課業。"},{"en":"If 60 per cent of clothing threads are natural, natural fibres remain very important.","zh":"如果百分之六十衣物線材是天然的，天然纖維仍然非常重要。"},{"en":"This phrase emphasises a high proportion.","zh":"這個片語強調高比例。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":13},{"front":"weave clothing","meaning":"織造衣物","examples":[{"en":"Natural fibres are used to weave clothing.","zh":"天然纖維被用來織造衣物。"},{"en":"To weave clothing means to make fabric or garments by crossing threads together.","zh":"weave clothing 指透過交織線材來製作布料或衣物。"},{"en":"A craft worker may weave cloth on a loom to make scarves or shirts.","zh":"工藝師可能在織布機上織布，製作圍巾或襯衫。"},{"en":"If fibres are strong and smooth, they can be woven into comfortable clothing.","zh":"如果纖維強韌又順滑，它們可以被織成舒適衣物。"},{"en":"This phrase describes turning threads into fabric or garments.","zh":"這個片語描述把線材變成布料或衣物。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":13},{"front":"natural fibres","meaning":"天然纖維","examples":[{"en":"Cotton, wool, and silk are natural fibres.","zh":"棉花、羊毛和絲都是天然纖維。"},{"en":"Natural fibres are fibres that come from plants, animals, or other natural sources.","zh":"natural fibres 是來自植物、動物或其他自然來源的纖維。"},{"en":"A cotton T-shirt and a wool sweater are both made from natural fibres.","zh":"棉質 T 恤和羊毛冷衫都由天然纖維製成。"},{"en":"Natural fibres can feel comfortable, but they may shrink, wrinkle, or stretch after washing.","zh":"天然纖維可以感覺舒適，但洗後可能縮水、起皺或變形。"},{"en":"This phrase contrasts plant- or animal-based fibres with synthetic fibres.","zh":"這個片語把植物或動物來源纖維與合成纖維作對比。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":13},{"front":"the aim is to","meaning":"目的是","examples":[{"en":"The aim is to offer substitutes for natural fibres.","zh":"目的是提供天然纖維的替代品。"},{"en":"The aim is to means the purpose or goal is to do something.","zh":"the aim is to 指目的或目標是做某事。"},{"en":"The aim is to help students speak more confidently by practising every lesson.","zh":"目的是透過每堂練習幫助學生更有信心說話。"},{"en":"If the aim is clear, researchers can choose methods that move toward that goal.","zh":"如果目標清楚，研究人員可以選擇朝該目標前進的方法。"},{"en":"This phrase introduces the main objective.","zh":"這個片語引入主要目的。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":13},{"front":"offer substitutes for","meaning":"提供……的替代品","examples":[{"en":"Scientists aim to offer substitutes for natural fibres.","zh":"科學家旨在提供天然纖維的替代品。"},{"en":"To offer substitutes for something means to provide alternatives that can replace it.","zh":"offer substitutes for something 指提供可以取代某物的替代選項。"},{"en":"A school can offer substitutes for sugary drinks, such as water and unsweetened tea.","zh":"學校可以提供含糖飲品的替代品，例如水和無糖茶。"},{"en":"If natural fibres have weaknesses, better alternatives may attract clothing manufacturers.","zh":"如果天然纖維有缺點，更好的替代品可能吸引服裝製造商。"},{"en":"This phrase focuses on providing replacement options.","zh":"這個片語聚焦於提供替代選擇。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":14},{"front":"be free of","meaning":"沒有……的","examples":[{"en":"Researchers want fibres that are free of the problems of natural fibres.","zh":"研究人員想要沒有天然纖維問題的纖維。"},{"en":"To be free of something means not to have that problem, feature, or restriction.","zh":"be free of something 指沒有某個問題、特徵或限制。"},{"en":"A quiet library room should be free of loud phone calls.","zh":"安靜圖書館房間應沒有大聲電話。"},{"en":"If a fibre is free of shrinkage and wrinkling, clothing made from it is easier to care for.","zh":"如果纖維沒有縮水和起皺問題，由它製成的衣物會更容易打理。"},{"en":"This phrase describes absence of an unwanted problem.","zh":"這個片語描述沒有不想要的問題。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":14},{"front":"poor wash-wear performance","meaning":"洗後穿着表現差","examples":[{"en":"Natural fibres may have poor wash-wear performance.","zh":"天然纖維可能有洗後穿着表現差的問題。"},{"en":"Poor wash-wear performance means clothes do not keep their shape or appearance well after washing and wearing.","zh":"poor wash-wear performance 指衣物在洗滌和穿着後不能很好保持形狀或外觀。"},{"en":"A shirt has poor wash-wear performance if it shrinks, wrinkles, and loses shape after one wash.","zh":"如果襯衫洗一次後縮水、起皺和變形，它就是洗後穿着表現差。"},{"en":"If fabric performs poorly after washing, customers may avoid buying it again.","zh":"如果布料洗後表現差，顧客可能避免再次購買。"},{"en":"This phrase describes a practical weakness in clothing materials.","zh":"這個片語描述衣物材料中的實際弱點。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":14},{"front":"stretching, wrinkling and shrinkage","meaning":"變形、起皺和縮水","examples":[{"en":"Natural fibres may suffer from stretching, wrinkling and shrinkage.","zh":"天然纖維可能受變形、起皺和縮水影響。"},{"en":"Stretching, wrinkling and shrinkage are changes where fabric becomes loose, creased, or smaller.","zh":"stretching, wrinkling and shrinkage 是布料變鬆、起皺或變小的變化。"},{"en":"A cotton shirt may show wrinkling after washing and shrinkage after hot drying.","zh":"棉襯衫洗後可能起皺，熱風乾後可能縮水。"},{"en":"If clothing stretches or shrinks, it may no longer fit properly.","zh":"如果衣物變形或縮水，它可能不再合身。"},{"en":"This phrase lists common problems in fabric care.","zh":"這個片語列出布料護理中的常見問題。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":14},{"front":"seek a better-than-natural alternative","meaning":"尋求比天然纖維更好的替代品","examples":[{"en":"Researchers are seeking a better-than-natural alternative fibre.","zh":"研究人員正在尋求比天然纖維更好的替代纖維。"},{"en":"To seek a better-than-natural alternative means to look for something artificial that performs better than the natural version.","zh":"seek a better-than-natural alternative 指尋找一種表現比天然版本更好的人造替代品。"},{"en":"A company may seek a better-than-natural sweetener that tastes good but has fewer calories.","zh":"公司可能尋求比天然糖更好的甜味劑，味道好但熱量較低。"},{"en":"If natural fibres wrinkle and shrink, scientists may search for fibres that avoid those weaknesses.","zh":"如果天然纖維起皺和縮水，科學家可能尋找避免這些弱點的纖維。"},{"en":"This phrase shows an attempt to improve on nature rather than merely copy it.","zh":"這個片語顯示嘗試超越自然，而不只是複製自然。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":14},{"front":"alternative fibre","meaning":"替代纖維","examples":[{"en":"Artificial spider silk could become an alternative fibre.","zh":"人造蜘蛛絲可以成為替代纖維。"},{"en":"An alternative fibre is a different fibre that can be used instead of a more common one.","zh":"alternative fibre 是可以用來取代較常見纖維的另一種纖維。"},{"en":"Bamboo fibre may be used as an alternative fibre in towels and clothing.","zh":"竹纖維可能在毛巾和衣物中作為替代纖維。"},{"en":"If an alternative fibre is stronger or easier to wash, manufacturers may adopt it.","zh":"如果替代纖維更強韌或更易清洗，製造商可能採用它。"},{"en":"This phrase refers to a substitute material for textiles or other products.","zh":"這個片語指用於紡織品或其他產品的替代材料。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":14},{"front":"a major market","meaning":"龐大市場","examples":[{"en":"There is a major market for better fibres.","zh":"更好纖維有龐大市場。"},{"en":"A major market is a large group of customers or industries ready to buy a product.","zh":"major market 是準備購買某產品的大量顧客或行業。"},{"en":"There is a major market for affordable phones because many people need them for work and study.","zh":"平價手機有龐大市場，因為許多人需要它們工作和學習。"},{"en":"If clothing companies need stronger fibres, a successful new material could sell widely.","zh":"如果服裝公司需要更強韌纖維，成功的新材料可能廣泛銷售。"},{"en":"This phrase shows strong commercial demand.","zh":"這個片語顯示強大商業需求。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":14},{"front":"bio-inspired materials","meaning":"仿生物料","examples":[{"en":"Bio-inspired materials are opening new possibilities in fibre production.","zh":"仿生物料正在纖維生產中開拓新可能性。"},{"en":"Bio-inspired materials are materials designed by copying ideas from living organisms or natural systems.","zh":"bio-inspired materials 是透過模仿生物或自然系統的想法而設計的材料。"},{"en":"A waterproof coating inspired by lotus leaves is an example of a bio-inspired material.","zh":"受荷葉啟發的防水塗層就是仿生物料的例子。"},{"en":"If engineers learn from spider silk, they may create fibres that combine strength and flexibility.","zh":"如果工程師向蜘蛛絲學習，他們可能創造結合強度和柔韌性的纖維。"},{"en":"This phrase shows how biology can guide material design.","zh":"這個片語顯示生物學如何引導材料設計。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":14},{"front":"provide a new frontier for","meaning":"為……開拓新領域","examples":[{"en":"Bio-inspired materials are providing a new frontier for the fibre business.","zh":"仿生物料正在為纖維行業開拓新領域。"},{"en":"To provide a new frontier for something means to open a new area for development, discovery, or business.","zh":"provide a new frontier for something 指為某事開拓新的發展、發現或商業領域。"},{"en":"Online learning provided a new frontier for adult education.","zh":"網上學習為成人教育開拓新領域。"},{"en":"If bio-inspired fibres succeed, companies may enter markets that did not exist before.","zh":"如果仿生纖維成功，公司可能進入以前不存在的市場。"},{"en":"This phrase suggests fresh opportunities and unexplored possibilities.","zh":"這個片語暗示新機會和未被充分探索的可能性。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":14},{"front":"the fibre business","meaning":"纖維行業","examples":[{"en":"Spider silk could transform the fibre business.","zh":"蜘蛛絲可以改變纖維行業。"},{"en":"The fibre business is the industry that produces and sells fibres for clothing, textiles, and technical products.","zh":"fibre business 是生產和銷售用於衣物、紡織品和技術產品的纖維行業。"},{"en":"A company in the fibre business may supply fabric makers with cotton, nylon, or polyester.","zh":"纖維行業中的公司可能向布料製造商供應棉、尼龍或聚酯。"},{"en":"If a new fibre performs better than old ones, the whole industry may change.","zh":"如果新纖維比舊纖維表現更好，整個行業可能改變。"},{"en":"This phrase refers to the commercial world of fibre production and sales.","zh":"這個片語指纖維生產和銷售的商業世界。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":14},{"front":"classify the following as","meaning":"把以下項目分類為","examples":[{"en":"Students must classify the following items as relating to one type of silk.","zh":"學生必須把以下項目分類為與某一種絲有關。"},{"en":"To classify the following as something means to sort the listed items into a category.","zh":"classify the following as something 指把列出的項目分入某個類別。"},{"en":"In a science lesson, students may classify the following animals as mammals, birds, or insects.","zh":"在科學課中，學生可能把以下動物分類為哺乳類、鳥類或昆蟲。"},{"en":"If students classify items correctly, they show they understand the differences between categories.","zh":"如果學生正確分類項目，就顯示他們理解類別之間的差異。"},{"en":"This phrase is common in exam instructions and sorting tasks.","zh":"這個片語常見於考試指示和分類任務。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":14},{"front":"relating to","meaning":"與……有關","examples":[{"en":"The question asks which silk each statement is relating to.","zh":"題目問每個陳述與哪種絲有關。"},{"en":"Relating to means connected with or about something.","zh":"relating to 指與某事有連繫或關於某事。"},{"en":"A school notice relating to exams should be read carefully by all students.","zh":"與考試有關的學校通告，所有學生都應仔細閱讀。"},{"en":"If a statement mentions cocoons, it may relate to silkworm silk rather than spider silk.","zh":"如果陳述提到繭，它可能與蠶絲而不是蜘蛛絲有關。"},{"en":"This phrase shows connection between information and a topic.","zh":"這個片語顯示資訊與主題之間的連繫。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":15},{"front":"forms the cocoon","meaning":"形成繭","examples":[{"en":"One type of silk forms the cocoon.","zh":"一種絲形成繭。"},{"en":"Forms the cocoon means creates the protective silk covering around an insect during development.","zh":"forms the cocoon 指在昆蟲發育期間形成保護性絲外殼。"},{"en":"A silkworm forms the cocoon before changing into a moth.","zh":"蠶在變成蛾之前形成繭。"},{"en":"If silk forms a cocoon, it protects the insect while it transforms.","zh":"如果絲形成繭，它就會在昆蟲轉變時保護牠。"},{"en":"This phrase describes a biological use of silk.","zh":"這個片語描述絲的一種生物用途。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":15},{"front":"form the framework of a web","meaning":"形成蛛網框架","examples":[{"en":"Some silk forms the framework of a web.","zh":"一些絲形成蛛網框架。"},{"en":"To form the framework of a web means to create the main supporting lines of a spider web.","zh":"form the framework of a web 指形成蜘蛛網的主要支撐線。"},{"en":"In a tent, poles form the framework that holds the cloth up.","zh":"在帳篷中，支架形成撐起布料的框架。"},{"en":"If the web’s framework is strong, the web can keep its shape and function.","zh":"如果蛛網框架強韌，蛛網就能保持形狀和功能。"},{"en":"This phrase describes structural support in a web.","zh":"這個片語描述蛛網中的結構支撐。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":15},{"front":"the most elastic silk","meaning":"彈性最大的絲","examples":[{"en":"The question asks students to identify the most elastic silk.","zh":"題目要求學生識別彈性最大的絲。"},{"en":"The most elastic silk is the silk type that can stretch the most and return without breaking.","zh":"most elastic silk 是最能伸展並在不斷裂下回復的絲類型。"},{"en":"A rubber band is more elastic than string because it stretches and returns.","zh":"橡筋比繩子更有彈性，因為它能伸展並回復。"},{"en":"If a silk is highly elastic, it can absorb sudden movement from trapped insects.","zh":"如果某種絲高度有彈性，它就能吸收被困昆蟲的突然移動。"},{"en":"This phrase asks for the silk with the greatest stretchiness.","zh":"這個片語要求找出伸展性最大的絲。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":15},{"front":"allow a spider to","meaning":"讓蜘蛛能夠……","examples":[{"en":"One type of silk allows a spider to drop quickly.","zh":"一種絲讓蜘蛛能夠快速向下垂降。"},{"en":"To allow a spider to do something means to make that action possible for the spider.","zh":"allow a spider to do something 指使蜘蛛能夠做某個動作。"},{"en":"A strong thread allows a hanging decoration to stay in place.","zh":"強韌的線讓懸掛裝飾能夠固定在原位。"},{"en":"If dragline silk allows a spider to drop, it helps the spider move and hunt safely.","zh":"如果牽引絲讓蜘蛛能夠向下垂降，它就幫助蜘蛛安全移動和捕獵。"},{"en":"This phrase explains what a type of silk enables.","zh":"這個片語解釋某種絲使甚麼成為可能。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":15},{"front":"a single strand","meaning":"一條單絲","examples":[{"en":"A single strand can be hundreds of metres long.","zh":"一條單絲可以長達數百米。"},{"en":"A single strand is one thin continuous piece of fibre, hair, or thread.","zh":"single strand 是一條幼細而連續的纖維、頭髮或線。"},{"en":"A single strand of hair on a dark jacket can be easy to notice.","zh":"深色外套上的一條頭髮可能很容易被注意到。"},{"en":"If one strand is very long, it can be unwound and used to make fabric.","zh":"如果一條單絲很長，它可以被拆出並用來製作布料。"},{"en":"This phrase emphasises one individual thread-like piece.","zh":"這個片語強調一條個別線狀物。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":15},{"front":"up to 900 metres long","meaning":"最長達九百米","examples":[{"en":"A single strand can be up to 900 metres long.","zh":"一條單絲最長可達九百米。"},{"en":"Up to 900 metres long means the maximum length can reach 900 metres.","zh":"up to 900 metres long 指最大長度可達九百米。"},{"en":"A walking route may be up to 900 metres long if it goes around the whole park.","zh":"如果步行路線繞整個公園一圈，可能最長達九百米。"},{"en":"If one silk strand reaches this length, it provides a surprisingly large amount of fibre.","zh":"如果一條絲達到這個長度，它就提供令人驚訝的大量纖維。"},{"en":"This phrase gives the upper limit of length.","zh":"這個片語給出長度上限。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":15},{"front":"the strongest silk","meaning":"最強韌的絲","examples":[{"en":"The question asks which type is the strongest silk.","zh":"題目問哪一種類型是最強韌的絲。"},{"en":"The strongest silk is the silk type that can resist the greatest force without breaking.","zh":"strongest silk 是最能抵抗巨大力量而不斷裂的絲類型。"},{"en":"A climber would want the strongest rope, not just the lightest one.","zh":"攀石者會想要最強韌的繩索，而不只是最輕的繩索。"},{"en":"If a silk is the strongest, it is likely to be useful in safety and engineering products.","zh":"如果某種絲最強韌，它很可能適用於安全和工程產品。"},{"en":"This phrase asks for the silk with the highest strength.","zh":"這個片語要求找出強度最高的絲。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":15},{"front":"reflect the claims of","meaning":"反映作者的說法","examples":[{"en":"Students decide whether the statements reflect the claims of the writer.","zh":"學生判斷陳述是否反映作者的說法。"},{"en":"To reflect the claims of someone means to match or represent what that person argues or says.","zh":"reflect the claims of someone 指符合或代表某人主張或所說的內容。"},{"en":"A summary should reflect the claims of the article, not the student’s personal opinion.","zh":"摘要應反映文章的說法，而不是學生個人意見。"},{"en":"If a statement changes the writer’s meaning, it does not truly reflect the claim.","zh":"如果陳述改變作者意思，它就不真正反映該說法。"},{"en":"This phrase is common in reading-comprehension tasks.","zh":"這個片語常見於閱讀理解題。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":15},{"front":"agree with the views of","meaning":"與……的看法一致","examples":[{"en":"Students write YES if a statement agrees with the views of the writer.","zh":"如果陳述與作者的看法一致，學生寫 YES。"},{"en":"To agree with the views of someone means to match that person’s opinion or position.","zh":"agree with the views of someone 指符合某人的意見或立場。"},{"en":"If an article supports online learning, a statement praising online learning may agree with the writer’s view.","zh":"如果文章支持網上學習，讚揚網上學習的陳述可能與作者看法一致。"},{"en":"Students should check meaning carefully before deciding that a statement agrees.","zh":"學生在判斷陳述一致前，應仔細檢查意思。"},{"en":"This phrase asks whether a statement matches an opinion, not just a fact.","zh":"這個片語問陳述是否符合看法，而不只是事實。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":15},{"front":"contradict the views of","meaning":"與……的看法相矛盾","examples":[{"en":"Students write NO if a statement contradicts the views of the writer.","zh":"如果陳述與作者的看法相矛盾，學生寫 NO。"},{"en":"To contradict the views of someone means to say the opposite of that person’s opinion.","zh":"contradict the views of someone 指說出與某人意見相反的意思。"},{"en":"If the writer says a material is promising, calling it useless may contradict the writer’s view.","zh":"如果作者說某材料有前景，稱它無用可能與作者看法相矛盾。"},{"en":"A statement can use different words but still contradict the meaning.","zh":"陳述可以使用不同字眼，但仍與意思相矛盾。"},{"en":"This phrase is used when checking disagreement with the writer’s position.","zh":"這個片語用於檢查是否與作者立場不一致。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":15},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"Students write NOT GIVEN if it is impossible to say what the writer thinks.","zh":"如果無法判斷作者怎樣想，學生寫 NOT GIVEN。"},{"en":"Impossible to say means there is not enough information to decide.","zh":"impossible to say 指沒有足夠資料作決定。"},{"en":"If a passage never mentions teacher salaries, it is impossible to say whether they are high.","zh":"如果文章從未提及教師薪酬，就無法判斷薪酬是否高。"},{"en":"In reading tests, students should not guess when the text gives no clear evidence.","zh":"在閱讀測驗中，文本沒有清楚證據時，學生不應猜測。"},{"en":"This phrase signals uncertainty caused by missing information.","zh":"這個片語表示因資料缺失而不確定。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":16},{"front":"secrete silk","meaning":"分泌絲","examples":[{"en":"The statement discusses whether all spiders secrete silk.","zh":"該陳述討論是否所有蜘蛛都分泌絲。"},{"en":"To secrete silk means to produce silk from the body.","zh":"secrete silk 指從身體產生絲。"},{"en":"A silkworm secretes silk when it spins its cocoon.","zh":"蠶吐絲結繭時就是分泌絲。"},{"en":"If an animal secretes silk, researchers may study the glands or organs that produce it.","zh":"如果動物分泌絲，研究人員可能研究產生絲的腺體或器官。"},{"en":"This phrase describes biological production of silk.","zh":"這個片語描述絲的生物生產。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":16},{"front":"occur naturally in","meaning":"天然存在於……之中","examples":[{"en":"The statement asks whether spider silk protein occurs naturally in goats’ milk.","zh":"該陳述問蜘蛛絲蛋白是否天然存在於山羊奶中。"},{"en":"To occur naturally in something means to be found there without human engineering or artificial addition.","zh":"occur naturally in something 指在沒有人工工程或添加下存在於某物中。"},{"en":"Calcium occurs naturally in milk, but added vitamins may not be natural to the original food.","zh":"鈣天然存在於牛奶中，但添加維他命未必是原本食物天然含有的。"},{"en":"If silk protein does not occur naturally in goats’ milk, scientists must add the gene artificially.","zh":"如果絲蛋白不是天然存在於山羊奶中，科學家就必須人工加入基因。"},{"en":"This phrase contrasts natural presence with engineered production.","zh":"這個片語把天然存在與工程生產作對比。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":16},{"front":"lead research efforts","meaning":"領導研究工作","examples":[{"en":"The statement mentions a country leading research efforts in spider silk.","zh":"該陳述提到一個國家領導蜘蛛絲研究工作。"},{"en":"To lead research efforts means to be at the front of scientific work in a field.","zh":"lead research efforts 指在某領域科學工作中處於前列。"},{"en":"A university may lead research efforts in cancer treatment if it publishes important studies.","zh":"如果大學發表重要研究，它可能領導癌症治療研究工作。"},{"en":"If a country leads research efforts, it may receive attention, funding, and talented researchers.","zh":"如果一個國家領導研究工作，它可能得到關注、資金和優秀研究人員。"},{"en":"This phrase describes being a leader in research activity.","zh":"這個片語描述在研究活動中領先。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":16},{"front":"in the area of","meaning":"在……領域","examples":[{"en":"The statement refers to research efforts in the area of spider silk.","zh":"該陳述指在蜘蛛絲領域的研究工作。"},{"en":"In the area of means in the field, topic, or subject of something.","zh":"in the area of 指在某個領域、主題或科目中。"},{"en":"A teacher may receive training in the area of online assessment.","zh":"老師可能接受網上評核領域的培訓。"},{"en":"If researchers work in the area of artificial fibres, spider silk may interest them.","zh":"如果研究人員在人造纖維領域工作，蜘蛛絲可能令他們感興趣。"},{"en":"This phrase identifies the topic or field being discussed.","zh":"這個片語指出正在討論的主題或領域。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":16},{"front":"be produced commercially","meaning":"被商業化生產","examples":[{"en":"The question asks whether spider silk is now being produced commercially.","zh":"題目問蜘蛛絲現在是否正被商業化生產。"},{"en":"To be produced commercially means to be made and sold as a business product.","zh":"be produced commercially 指作為商業產品被製造和銷售。"},{"en":"A medicine may work in the lab years before it is produced commercially.","zh":"一種藥物可能在實驗室有效多年後才被商業化生產。"},{"en":"If spider silk is produced commercially, companies can sell it for clothing, medicine, or safety products.","zh":"如果蜘蛛絲被商業化生產，公司就能把它售作衣物、醫療或安全產品。"},{"en":"This phrase focuses on market production, not just laboratory research.","zh":"這個片語聚焦於市場生產，而不只是實驗室研究。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":16},{"front":"using no more than three words","meaning":"使用不多於三個字","examples":[{"en":"Students must complete the answers using no more than three words.","zh":"學生必須使用不多於三個字完成答案。"},{"en":"Using no more than three words means the answer must contain three words or fewer.","zh":"using no more than three words 指答案必須包含三個或更少英文詞。"},{"en":"If the instruction says no more than three words, writing four words may lose marks.","zh":"如果指示說不多於三個字，寫四個字可能失分。"},{"en":"Students should copy only the necessary words from the passage.","zh":"學生應只從文章中抄取必要字詞。"},{"en":"This phrase sets a strict word limit for exam answers.","zh":"這個片語為考試答案設定嚴格字數限制。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":16},{"front":"complete the following","meaning":"完成以下內容","examples":[{"en":"The task asks students to complete the following table.","zh":"任務要求學生完成以下表格。"},{"en":"Complete the following means fill in the information that comes next in the exercise.","zh":"complete the following 指填寫練習中接下來的資料。"},{"en":"A teacher may ask students to complete the following sentences with words from a passage.","zh":"老師可能要求學生用文章中的字詞完成以下句子。"},{"en":"If students read the instructions carefully, they know what kind of answer is required.","zh":"如果學生仔細閱讀指示，就知道需要哪種答案。"},{"en":"This phrase is a common test instruction.","zh":"這個片語是常見測驗指示。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":16},{"front":"comparison of","meaning":"……的比較","examples":[{"en":"The question table gives a comparison of synthetic and natural fibres.","zh":"題目表格給出合成及天然纖維的比較。"},{"en":"A comparison of two things shows their similarities and differences.","zh":"comparison of two things 顯示兩者的相似和差異。"},{"en":"A teacher may ask for a comparison of online learning and classroom learning.","zh":"老師可能要求比較網上學習和課堂學習。"},{"en":"If students compare fibres, they can see why one may be stronger or easier to wash.","zh":"如果學生比較纖維，就能看出為何某一種可能更強或更易清洗。"},{"en":"This phrase introduces a side-by-side examination.","zh":"這個片語引入並列檢視。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":16},{"front":"synthetic and natural fibres","meaning":"合成及天然纖維","examples":[{"en":"The task compares synthetic and natural fibres.","zh":"任務比較合成及天然纖維。"},{"en":"Synthetic and natural fibres are man-made fibres and fibres from plants, animals, or natural sources.","zh":"synthetic and natural fibres 是人造纖維，以及來自植物、動物或自然來源的纖維。"},{"en":"Nylon is synthetic, while cotton and wool are natural fibres.","zh":"尼龍是合成纖維，而棉花和羊毛是天然纖維。"},{"en":"If students compare both kinds, they can understand their different strengths and weaknesses.","zh":"如果學生比較兩種纖維，就能理解它們不同的優點和弱點。"},{"en":"This phrase contrasts artificial materials with nature-based materials.","zh":"這個片語把人工材料與自然來源材料作對比。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":16},{"front":"main problem in producing","meaning":"生產……的主要問題","examples":[{"en":"The table asks for the main problem in producing synthetic fibres.","zh":"表格問生產合成纖維的主要問題。"},{"en":"The main problem in producing something is the most important difficulty in making it.","zh":"main problem in producing something 指製造某物時最重要的困難。"},{"en":"The main problem in producing cheap housing may be the high cost of land.","zh":"生產廉價房屋的主要問題可能是土地成本高。"},{"en":"If synthetic fibre production causes pollution, that may be the key problem to solve.","zh":"如果合成纖維生產造成污染，那可能是需要解決的關鍵問題。"},{"en":"This phrase asks for the biggest production difficulty.","zh":"這個片語詢問最大的生產困難。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":16},{"front":"disadvantages of natural fibres","meaning":"天然纖維的缺點","examples":[{"en":"The question asks for three disadvantages of natural fibres.","zh":"題目要求寫出天然纖維的三個缺點。"},{"en":"Disadvantages of natural fibres are the weaknesses or problems of fibres from plants or animals.","zh":"disadvantages of natural fibres 是來自植物或動物纖維的弱點或問題。"},{"en":"Wool may feel warm, but one disadvantage is that it can shrink if washed badly.","zh":"羊毛可能很保暖，但其中一個缺點是洗得不好時會縮水。"},{"en":"If natural fibres wrinkle or stretch, clothing made from them may be harder to care for.","zh":"如果天然纖維起皺或變形，由它們製成的衣物可能較難打理。"},{"en":"This phrase asks for negative features of nature-based fibres.","zh":"這個片語要求指出自然來源纖維的負面特徵。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":17},{"front":"proportion of clothing","meaning":"衣物所佔比例","examples":[{"en":"The table asks for the proportion of clothing made from natural fibres.","zh":"表格問由天然纖維製成的衣物所佔比例。"},{"en":"Proportion of clothing means the share or percentage of clothing in a particular category.","zh":"proportion of clothing 指某一類衣物在整體中的份額或百分比。"},{"en":"A shop may calculate the proportion of clothing made from recycled materials.","zh":"商店可能計算由回收材料製成的衣物所佔比例。"},{"en":"If a large proportion of clothing uses natural fibres, improvements in those fibres affect many consumers.","zh":"如果大比例衣物使用天然纖維，改善這些纖維會影響許多消費者。"},{"en":"This phrase focuses on the percentage or part of the whole.","zh":"這個片語聚焦於整體中的百分比或部分。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":17},{"front":"made from natural fibres","meaning":"由天然纖維製成","examples":[{"en":"A large proportion of clothing is made from natural fibres.","zh":"大比例衣物由天然纖維製成。"},{"en":"Made from natural fibres means produced using fibres that come from plants or animals.","zh":"made from natural fibres 指使用來自植物或動物的纖維製造。"},{"en":"A cotton shirt and a wool coat are made from natural fibres.","zh":"棉襯衫和羊毛外套都是由天然纖維製成。"},{"en":"If clothing is made from natural fibres, it may feel comfortable but require careful washing.","zh":"如果衣物由天然纖維製成，它可能感覺舒適，但需要小心清洗。"},{"en":"This phrase identifies the material source of clothing.","zh":"這個片語指出衣物的材料來源。"}],"source":"69 - The race to make spider silk.pdf","sourcePage":17}],"ielts/reading/passage-2/Practice 70":[{"front":"bring about industrialisation","meaning":"帶來工業化；促成工業化","examples":[{"en":"The passage asks whether tea and beer brought about industrialisation.","zh":"文章問茶和啤酒是否促成了工業化。"},{"en":"To bring about industrialisation means to help cause a society to develop factories, machines, and large-scale production.","zh":"To bring about industrialisation 指幫助促成一個社會發展工廠、機器和大規模生產。"},{"en":"Better roads and canals can bring about industrialisation by helping factories move goods cheaply.","zh":"更好的道路和運河可以透過幫助工廠廉價運送貨物來促成工業化。"},{"en":"If a country has labour, energy, transport, and buyers, these conditions may bring about industrialisation.","zh":"如果一個國家有勞動力、能源、交通和買家，這些條件可能促成工業化。"},{"en":"This phrase focuses on the causes that make industrial development happen.","zh":"這個片語著重使工業發展發生的原因。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":1},{"front":"rewrite history","meaning":"改寫歷史","examples":[{"en":"Alan Macfarlane thinks he could rewrite history.","zh":"Alan Macfarlane認為他可以改寫歷史。"},{"en":"To rewrite history means to change the accepted explanation of what happened in the past.","zh":"To rewrite history 指改變人們對過去事件的既有解釋。"},{"en":"A new discovery can rewrite history if it proves that an old belief was wrong.","zh":"如果新發現證明舊看法錯誤，它可以改寫歷史。"},{"en":"If historians find strong evidence, they may rewrite history rather than repeat textbook answers.","zh":"如果歷史學家找到有力證據，他們可能改寫歷史，而不是重複教科書答案。"},{"en":"This phrase suggests a major change in how the past is understood.","zh":"這個片語暗示人們對過去的理解出現重大改變。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":1},{"front":"spend decades trying to","meaning":"花數十年嘗試……","examples":[{"en":"Macfarlane has spent decades trying to understand the Industrial Revolution.","zh":"Macfarlane花了數十年嘗試理解工業革命。"},{"en":"To spend decades trying to do something means to work on it for many tens of years.","zh":"To spend decades trying to do something 指花上很多十年的時間去做某事。"},{"en":"A scientist may spend decades trying to find a cure for a serious disease.","zh":"科學家可能花數十年嘗試尋找嚴重疾病的治療方法。"},{"en":"If a problem is difficult, researchers may spend decades trying to collect enough evidence.","zh":"如果問題困難，研究人員可能花數十年嘗試收集足夠證據。"},{"en":"This phrase shows long, patient effort rather than a quick attempt.","zh":"這個片語顯示長期而耐心的努力，而不是快速嘗試。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":1},{"front":"understand the enigma of","meaning":"理解……的謎團","examples":[{"en":"Historians have tried to understand the enigma of the Industrial Revolution.","zh":"歷史學家一直嘗試理解工業革命的謎團。"},{"en":"To understand the enigma of something means to explain a puzzling or mysterious question about it.","zh":"To understand the enigma of something 指解釋關於某事的困惑或神秘問題。"},{"en":"Doctors may try to understand the enigma of why some patients recover faster than others.","zh":"醫生可能嘗試理解為何有些病人比其他病人康復得更快這個謎團。"},{"en":"When evidence does not fit a simple answer, people need more research to understand the enigma.","zh":"當證據不符合簡單答案，人們需要更多研究來理解謎團。"},{"en":"This phrase is used when something is important but difficult to explain.","zh":"這個片語用於某事重要但難以解釋的情況。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":1},{"front":"the Industrial Revolution","meaning":"工業革命","examples":[{"en":"The Industrial Revolution changed the world.","zh":"工業革命改變了世界。"},{"en":"The Industrial Revolution was the period when machines, factories, and new production methods transformed society.","zh":"工業革命是機器、工廠和新生產方法改造社會的時期。"},{"en":"During the Industrial Revolution, many people moved from farms to growing towns and cities.","zh":"在工業革命期間，許多人從農場搬到不斷增長的城鎮和城市。"},{"en":"The Industrial Revolution increased production, but it also created crowded cities and new social problems.","zh":"工業革命增加了生產，但也造成擁擠城市和新的社會問題。"},{"en":"This phrase refers to a major historical shift from hand production to machine industry.","zh":"這個片語指由人手生產轉向機器工業的重大歷史轉變。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":1},{"front":"a momentous event","meaning":"重大事件","examples":[{"en":"The birth of industry was a momentous event.","zh":"工業的誕生是一件重大事件。"},{"en":"A momentous event is an event that is extremely important and has long-lasting effects.","zh":"Momentous event 是極其重要並有長遠影響的事件。"},{"en":"The invention of the Internet was a momentous event because it changed communication worldwide.","zh":"互聯網的發明是一件重大事件，因為它改變了全球溝通。"},{"en":"When a momentous event happens, life before and after it may look very different.","zh":"當重大事件發生，事件前後的生活可能看起來非常不同。"},{"en":"This phrase describes an event that matters far beyond one person or one day.","zh":"這個片語描述影響遠超一個人或一天的事件。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":1},{"front":"the world-changing birth of industry","meaning":"改變世界的工業誕生","examples":[{"en":"The Industrial Revolution was the world-changing birth of industry.","zh":"工業革命是改變世界的工業誕生。"},{"en":"The world-changing birth of industry means the beginning of modern industry, which transformed many societies.","zh":"The world-changing birth of industry 指現代工業的開始，並改造了許多社會。"},{"en":"The first large factories marked the birth of industry because goods could be produced on a much bigger scale.","zh":"最早的大型工廠標誌着工業誕生，因為商品可以以大得多的規模生產。"},{"en":"When industry was born, work, transport, cities, and family life all began to change.","zh":"當工業誕生，工作、交通、城市和家庭生活都開始改變。"},{"en":"This phrase makes industrialisation sound like the start of a new world.","zh":"這個片語令工業化聽起來像一個新世界的開始。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":1},{"front":"at the end of","meaning":"在……末期","examples":[{"en":"The Industrial Revolution happened in Britain at the end of the 18th century.","zh":"工業革命在18世紀末期於英國發生。"},{"en":"At the end of a period means during its final part.","zh":"At the end of a period 指在某段時間的最後部分。"},{"en":"Students often feel tired at the end of the school term.","zh":"學生在學期末期常感到疲倦。"},{"en":"If a change happens at the end of a century, it occurs before the next century begins.","zh":"如果某變化發生在一個世紀末期，它就是在下一個世紀開始前出現。"},{"en":"This phrase gives the time position of an event.","zh":"這個片語指出事件的時間位置。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":1},{"front":"compare something to a puzzle","meaning":"把某事比作謎題","examples":[{"en":"Macfarlane compares the question to a puzzle.","zh":"Macfarlane把這個問題比作謎題。"},{"en":"To compare something to a puzzle means to say it has many pieces that must fit together before it can be understood.","zh":"To compare something to a puzzle 指說某事有許多部分，必須拼合起來才可理解。"},{"en":"A teacher may compare grammar to a puzzle because words must be placed in the right order.","zh":"老師可能把文法比作謎題，因為詞語必須放在正確次序。"},{"en":"If one piece is missing, a puzzle cannot be solved clearly.","zh":"如果少了一塊拼圖，謎題就不能清楚解開。"},{"en":"This phrase helps explain a complex problem with many connected parts.","zh":"這個片語幫助解釋有許多相連部分的複雜問題。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":1},{"front":"claim that","meaning":"聲稱；認為","examples":[{"en":"He claims that about 20 factors were needed.","zh":"他聲稱大約需要20個因素。"},{"en":"To claim that something is true means to state it as an opinion or argument, often needing evidence.","zh":"To claim that something is true 指把某事作為意見或論點提出，通常需要證據。"},{"en":"A student may claim that homework improves memory, but they should give reasons.","zh":"學生可能聲稱功課改善記憶，但應給出理由。"},{"en":"If a historian claims that one cause changed everything, readers may ask for proof.","zh":"如果歷史學家聲稱一個原因改變了一切，讀者可能要求證據。"},{"en":"This phrase introduces what someone says or argues.","zh":"這個片語引出某人所說或所主張的內容。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":1},{"front":"different factors","meaning":"不同因素","examples":[{"en":"There were about 20 different factors involved in the Industrial Revolution.","zh":"工業革命涉及大約20個不同因素。"},{"en":"Different factors are separate causes or conditions that help produce a result.","zh":"Different factors 是幫助產生結果的不同原因或條件。"},{"en":"A student’s exam result may depend on different factors, such as sleep, practice, and confidence.","zh":"學生考試成績可能取決於不同因素，例如睡眠、練習和信心。"},{"en":"When many different factors work together, it is hard to blame only one cause.","zh":"當許多不同因素共同作用，就很難只怪一個原因。"},{"en":"This phrase reminds learners that big events often have several causes.","zh":"這個片語提醒學習者，大事件通常有多個原因。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":2},{"front":"need to be present","meaning":"需要存在；需要具備","examples":[{"en":"All the factors needed to be present before the revolution could happen.","zh":"在革命能夠發生之前，所有因素都需要具備。"},{"en":"If conditions need to be present, they must exist before something can occur.","zh":"If conditions need to be present，意思是它們必須存在，某事才會發生。"},{"en":"For a school trip to happen, permission, transport, teachers, and safety plans need to be present.","zh":"要讓學校旅行成行，許可、交通、老師和安全計劃都需要具備。"},{"en":"If one important condition is missing, the expected result may not happen.","zh":"如果少了一個重要條件，預期結果可能不會發生。"},{"en":"This phrase is useful for explaining necessary conditions.","zh":"這個片語適合用來解釋必要條件。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":2},{"front":"before the revolution could happen","meaning":"在革命能夠發生之前","examples":[{"en":"Several conditions had to exist before the revolution could happen.","zh":"在革命能夠發生之前，幾個條件必須存在。"},{"en":"Before the revolution could happen means before the major change was possible.","zh":"Before the revolution could happen 指在重大變革成為可能之前。"},{"en":"Before a school reform could happen, teachers first needed training and clear materials.","zh":"在學校改革能夠發生之前，老師首先需要培訓和清晰教材。"},{"en":"If the right conditions are absent, even a good idea may not become a real change.","zh":"如果缺乏合適條件，即使好想法也未必變成真正改變。"},{"en":"This phrase shows that big changes usually require preparation.","zh":"這個片語顯示重大改變通常需要準備。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":2},{"front":"chief conditions","meaning":"主要條件","examples":[{"en":"The chief conditions are usually found in history textbooks.","zh":"主要條件通常可在歷史教科書中找到。"},{"en":"Chief conditions are the main requirements that must exist for something to happen.","zh":"Chief conditions 是某事發生所必須具備的主要要求。"},{"en":"The chief conditions for a successful lesson include clear aims, useful examples, and student attention.","zh":"成功課堂的主要條件包括清晰目標、有用例子和學生注意力。"},{"en":"If chief conditions are missing, a plan may fail even if smaller details are correct.","zh":"如果缺少主要條件，即使小細節正確，計劃也可能失敗。"},{"en":"This phrase points to the most important conditions, not minor ones.","zh":"這個片語指最重要的條件，而不是次要條件。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":2},{"front":"be found in","meaning":"可在……找到","examples":[{"en":"The chief conditions are found in history textbooks.","zh":"主要條件可在歷史教科書中找到。"},{"en":"To be found in a place means to exist or appear there.","zh":"To be found in a place 指存在或出現在某處。"},{"en":"Useful examples can be found in newspapers, films, and everyday conversations.","zh":"有用例子可以在報紙、電影和日常對話中找到。"},{"en":"If an answer can be found in the passage, students should not invent outside information.","zh":"如果答案可在文章中找到，學生不應自創外部資料。"},{"en":"This phrase tells us where something exists or can be located.","zh":"這個片語告訴我們某事存在或可被找到的位置。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":2},{"front":"for industry to take off","meaning":"為了讓工業迅速發展","examples":[{"en":"Several conditions were needed for industry to take off.","zh":"為了讓工業迅速發展，幾個條件是必需的。"},{"en":"For industry to take off means for industry to begin growing quickly and successfully.","zh":"For industry to take off 指工業開始快速而成功地增長。"},{"en":"For a small business to take off, it needs customers, money, and reliable staff.","zh":"為了讓小企業迅速發展，它需要顧客、資金和可靠員工。"},{"en":"If transport improves and energy becomes cheap, industry may take off faster.","zh":"如果交通改善且能源變便宜，工業可能更快迅速發展。"},{"en":"This phrase describes the moment when growth becomes rapid.","zh":"這個片語描述增長變得快速的時刻。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":2},{"front":"technology and power","meaning":"技術和動力","examples":[{"en":"Industry needed technology and power to drive factories.","zh":"工業需要技術和動力來驅動工廠。"},{"en":"Technology and power mean the machines, knowledge, and energy needed for production.","zh":"Technology and power 指生產所需的機器、知識和能源。"},{"en":"A modern hospital needs technology and power to run scanners, computers, and lights.","zh":"現代醫院需要技術和動力來運作掃描器、電腦和照明。"},{"en":"Without enough power, even advanced technology may stop working.","zh":"如果沒有足夠動力，即使先進技術也可能停止運作。"},{"en":"This phrase links tools with the energy needed to use them.","zh":"這個片語把工具與使用它們所需的能源連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":2},{"front":"drive factories","meaning":"驅動工廠；使工廠運作","examples":[{"en":"Power was needed to drive factories.","zh":"工廠需要動力來運作。"},{"en":"To drive factories means to provide the energy that makes factory machines work.","zh":"To drive factories 指提供能源，使工廠機器運作。"},{"en":"Electricity drives factories today by running machines, lights, lifts, and computers.","zh":"今天電力透過運作機器、燈光、升降機和電腦來驅動工廠。"},{"en":"If power supplies fail, factories cannot continue production normally.","zh":"如果電力供應失效，工廠不能正常繼續生產。"},{"en":"This phrase describes the energy behind industrial work.","zh":"這個片語描述工業工作背後的能源。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":2},{"front":"large urban populations","meaning":"龐大的城市人口","examples":[{"en":"Large urban populations provided cheap labour.","zh":"龐大的城市人口提供了廉價勞動力。"},{"en":"Large urban populations are large numbers of people living in towns and cities.","zh":"Large urban populations 是居住在城鎮和城市中的大量人口。"},{"en":"A city with many new workers may have a large urban population ready for factory jobs.","zh":"擁有許多新工人的城市，可能有龐大的城市人口準備從事工廠工作。"},{"en":"When rural people move into cities, urban populations grow quickly.","zh":"當農村人口搬入城市，城市人口會迅速增長。"},{"en":"This phrase connects city growth with available workers.","zh":"這個片語把城市增長與可用工人連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":2},{"front":"provide cheap labour","meaning":"提供廉價勞動力","examples":[{"en":"Large urban populations helped provide cheap labour.","zh":"龐大的城市人口幫助提供廉價勞動力。"},{"en":"To provide cheap labour means to supply workers who can be hired at low wages.","zh":"To provide cheap labour 指提供可用低工資聘請的工人。"},{"en":"A factory may move to a city because it can provide cheap labour.","zh":"工廠可能搬到城市，因為那裡可以提供廉價勞動力。"},{"en":"If many people need jobs, employers may pay lower wages.","zh":"如果許多人需要工作，僱主可能支付較低工資。"},{"en":"This phrase describes labour supply from the employer’s economic point of view.","zh":"這個片語從僱主的經濟角度描述勞動力供應。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":2},{"front":"easy transport","meaning":"便利交通","examples":[{"en":"Easy transport was needed to move goods around.","zh":"運送貨物需要便利交通。"},{"en":"Easy transport means simple, reliable, and affordable ways to move people or goods.","zh":"Easy transport 指簡單、可靠且負擔得起的人員或貨物運輸方式。"},{"en":"Shops need easy transport so fresh food can arrive before it spoils.","zh":"商店需要便利交通，讓新鮮食物在變壞前送達。"},{"en":"If roads, canals, or railways improve, transport becomes easier and trade grows.","zh":"如果道路、運河或鐵路改善，交通會變得更便利，貿易也會增長。"},{"en":"This phrase describes transport that reduces time, cost, and difficulty.","zh":"這個片語描述能減少時間、成本和困難的交通。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":3},{"front":"move goods around","meaning":"運送貨物","examples":[{"en":"Transport systems were needed to move goods around.","zh":"運輸系統是運送貨物所必需的。"},{"en":"To move goods around means to carry products from one place to another.","zh":"To move goods around 指把產品從一個地方運到另一個地方。"},{"en":"Delivery vans move goods around the city every morning.","zh":"送貨車每天早上在城市中運送貨物。"},{"en":"If goods cannot be moved around cheaply, factories may struggle to reach customers.","zh":"如果貨物不能廉價運送，工廠可能難以接觸顧客。"},{"en":"This phrase describes the practical movement of products.","zh":"這個片語描述產品的實際運送。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":3},{"front":"an affluent middle class","meaning":"富裕中產階級","examples":[{"en":"An affluent middle class was willing to buy mass-produced objects.","zh":"富裕中產階級願意購買大量生產的物品。"},{"en":"An affluent middle class is a group of reasonably wealthy people between the very rich and the poor.","zh":"Affluent middle class 是介乎非常富有者與貧窮者之間、相當富裕的一群人。"},{"en":"An affluent middle class may buy better furniture, clothes, books, and household goods.","zh":"富裕中產階級可能購買更好的家具、衣服、書籍和家居用品。"},{"en":"If more families become affluent, demand for manufactured products can increase.","zh":"如果更多家庭變得富裕，對製成品的需求可能增加。"},{"en":"This phrase links social wealth with consumer demand.","zh":"這個片語把社會財富與消費需求連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":3},{"front":"be willing to","meaning":"願意","examples":[{"en":"The middle class was willing to buy mass-produced goods.","zh":"中產階級願意購買大量生產的商品。"},{"en":"To be willing to do something means to be ready or happy to do it.","zh":"To be willing to do something 指準備好或樂意做某事。"},{"en":"A student is willing to practise more if they can see real progress.","zh":"如果學生看見真正進步，他們會願意多練習。"},{"en":"If customers are willing to pay, businesses can produce more confidently.","zh":"如果顧客願意付款，企業便可以更有信心地增加生產。"},{"en":"This phrase describes readiness, not force.","zh":"這個片語描述自願準備，而不是被迫。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":3},{"front":"mass-produced objects","meaning":"大量生產的物品","examples":[{"en":"Factories produced mass-produced objects for consumers.","zh":"工廠為消費者生產大量生產的物品。"},{"en":"Mass-produced objects are items made in large numbers, usually by machines or standard methods.","zh":"Mass-produced objects 是通常由機器或標準方法大量製造的物品。"},{"en":"Pens, cups, shoes, and phone cases are often mass-produced objects.","zh":"筆、杯、鞋和手機殼通常都是大量生產的物品。"},{"en":"Mass production can lower prices because many identical items are made at once.","zh":"大量生產可以降低價格，因為許多相同物品同時被製造。"},{"en":"This phrase contrasts factory-made goods with handmade items.","zh":"這個片語把工廠製品與手工物品作對比。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":3},{"front":"a market-driven economy","meaning":"市場主導經濟","examples":[{"en":"A market-driven economy helped industry develop.","zh":"市場主導經濟幫助工業發展。"},{"en":"A market-driven economy is an economy where demand, prices, and competition strongly influence production.","zh":"Market-driven economy 是需求、價格和競爭強烈影響生產的經濟。"},{"en":"In a market-driven economy, shops sell what customers are willing to buy.","zh":"在市場主導經濟中，商店出售顧客願意購買的東西。"},{"en":"If demand rises, a market-driven economy may encourage businesses to produce more.","zh":"如果需求上升，市場主導經濟可能鼓勵企業增加生產。"},{"en":"This phrase describes an economy shaped mainly by buyers and sellers.","zh":"這個片語描述主要由買家和賣家塑造的經濟。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":3},{"front":"political system","meaning":"政治制度","examples":[{"en":"A suitable political system allowed industrialisation to happen.","zh":"合適的政治制度讓工業化發生。"},{"en":"A political system is the way a country is governed and how power is organised.","zh":"Political system 是一個國家被治理和權力被組織的方式。"},{"en":"A stable political system can make business investment less risky.","zh":"穩定的政治制度可以令商業投資風險較低。"},{"en":"If laws protect property and trade, factories may grow more easily.","zh":"如果法律保護財產和貿易，工廠可能更容易成長。"},{"en":"This phrase connects government structure with economic development.","zh":"這個片語把政府架構與經濟發展連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":3},{"front":"allow something to happen","meaning":"讓某事發生","examples":[{"en":"The political system allowed industrialisation to happen.","zh":"政治制度讓工業化發生。"},{"en":"To allow something to happen means to make it possible or not prevent it.","zh":"To allow something to happen 指令某事成為可能或不阻止它。"},{"en":"Clear school rules can allow group work to happen without chaos.","zh":"清晰校規可以讓小組活動發生而不混亂。"},{"en":"If transport and laws support trade, they allow business growth to happen.","zh":"如果交通和法律支持貿易，它們便讓商業增長發生。"},{"en":"This phrase shows that a condition creates space for an event.","zh":"這個片語顯示某條件為事件創造空間。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":3},{"front":"while this was the case for","meaning":"雖然……情況如此","examples":[{"en":"While this was the case for England, other nations also met some criteria.","zh":"雖然英格蘭情況如此，其他國家也符合其中一些準則。"},{"en":"While this was the case for means although this was true for one example, the wider situation may be different.","zh":"While this was the case for 指雖然這對某例子是真實的，但更廣泛情況可能不同。"},{"en":"While this was the case for one class, another class needed a different teaching method.","zh":"雖然一個班情況如此，另一個班需要不同教學方法。"},{"en":"This phrase helps compare one situation with other similar situations.","zh":"這個片語幫助比較一種情況與其他相似情況。"},{"en":"It is useful when a writer wants to avoid overgeneralising.","zh":"當作者想避免過度概括時，這個片語很有用。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":3},{"front":"meet some criteria","meaning":"符合某些準則","examples":[{"en":"Japan, Holland and France also met some of these criteria.","zh":"日本、荷蘭和法國也符合其中一些準則。"},{"en":"To meet some criteria means to satisfy some of the required standards or conditions.","zh":"To meet some criteria 指符合部分所需標準或條件。"},{"en":"A student may meet some criteria for a scholarship but still miss one important requirement.","zh":"學生可能符合獎學金的某些準則，但仍缺少一項重要要求。"},{"en":"If a country meets only some criteria, it may not be ready for major industrial growth.","zh":"如果一個國家只符合某些準則，它未必準備好迎接重大工業增長。"},{"en":"This phrase shows partial fulfilment, not complete success.","zh":"這個片語顯示部分符合，而不是完全成功。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":3},{"front":"necessary but not sufficient","meaning":"必要但不足夠","examples":[{"en":"These factors were necessary but not sufficient to cause the revolution.","zh":"這些因素是引發革命所必需的，但並不足夠。"},{"en":"Necessary but not sufficient means something is required, but by itself it is not enough.","zh":"Necessary but not sufficient 指某事是必需的，但單靠它並不足夠。"},{"en":"Money is necessary but not sufficient for a good school; teachers and planning also matter.","zh":"金錢對好學校而言是必要但不足夠的；老師和規劃也重要。"},{"en":"If one condition is necessary but not sufficient, more conditions must be added before success is possible.","zh":"如果一個條件必要但不足夠，成功前還必須加入更多條件。"},{"en":"This phrase separates “needed” from “enough”.","zh":"這個片語把「需要」和「足夠」分開。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":4},{"front":"cause the revolution","meaning":"引發革命","examples":[{"en":"The factors alone were not sufficient to cause the revolution.","zh":"單靠這些因素不足以引發革命。"},{"en":"To cause the revolution means to bring about a major change in society, politics, or industry.","zh":"To cause the revolution 指帶來社會、政治或工業上的重大變革。"},{"en":"One angry speech rarely causes a revolution unless deeper problems already exist.","zh":"一場憤怒演說很少會引發革命，除非更深層問題已經存在。"},{"en":"If many pressures build up together, they may cause a revolution.","zh":"如果許多壓力一起累積，它們可能引發革命。"},{"en":"This phrase focuses on the forces that create a major transformation.","zh":"這個片語著重創造重大轉型的力量。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":4},{"front":"everything except","meaning":"除了……之外一切都有","examples":[{"en":"Holland had everything except coal.","zh":"荷蘭除了煤之外一切都有。"},{"en":"Everything except means all the needed things are present apart from one missing item.","zh":"Everything except 指除了缺少一項之外，所有所需東西都存在。"},{"en":"The class had everything except a projector, so the video lesson could not begin.","zh":"課室除了投影機之外一切都有，所以影片課不能開始。"},{"en":"If a factory has workers, machines, and buyers but no power, it has everything except one key condition.","zh":"如果工廠有工人、機器和買家，但沒有動力，它就是除了其中一個關鍵條件之外一切都有。"},{"en":"This phrase highlights the one missing piece.","zh":"這個片語突顯缺失的那一項。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":4},{"front":"most historians","meaning":"大多數歷史學家","examples":[{"en":"Most historians believe that one or two factors were missing.","zh":"大多數歷史學家認為缺少一兩個因素。"},{"en":"Most historians means the majority of people who study and write about history.","zh":"Most historians 指研究和書寫歷史的人中的大多數。"},{"en":"Most historians use documents, records, and evidence before reaching conclusions.","zh":"大多數歷史學家在作結論前會使用文件、記錄和證據。"},{"en":"If most historians agree on a view, it may become the standard explanation.","zh":"如果大多數歷史學家同意某看法，它可能成為標準解釋。"},{"en":"This phrase refers to the dominant opinion among history experts.","zh":"這個片語指歷史專家中的主流意見。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":4},{"front":"be convinced that","meaning":"確信","examples":[{"en":"Most historians are convinced that some missing factors are needed.","zh":"大多數歷史學家確信需要一些缺失因素。"},{"en":"To be convinced that something is true means to strongly believe it because of reasons or evidence.","zh":"To be convinced that something is true 指因理由或證據而強烈相信某事是真的。"},{"en":"A teacher may be convinced that daily reading improves writing after seeing students progress.","zh":"老師看見學生進步後，可能確信每日閱讀能改善寫作。"},{"en":"If people are convinced by evidence, they are less likely to change their view quickly.","zh":"如果人們被證據說服並確信某事，他們較不可能很快改變看法。"},{"en":"This phrase describes strong belief, not a weak guess.","zh":"這個片語描述強烈信念，而不是薄弱猜測。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":4},{"front":"missing factors","meaning":"缺失的因素","examples":[{"en":"Historians are looking for the missing factors in the puzzle.","zh":"歷史學家正在尋找謎題中缺失的因素。"},{"en":"Missing factors are important causes or conditions that have not yet been identified.","zh":"Missing factors 是尚未被找出的重要原因或條件。"},{"en":"If a student fails despite studying hard, sleep or stress may be missing factors.","zh":"如果學生努力溫習仍然不合格，睡眠或壓力可能是缺失的因素。"},{"en":"When an explanation feels incomplete, researchers search for missing factors.","zh":"當解釋感覺不完整，研究人員會尋找缺失的因素。"},{"en":"This phrase describes the pieces needed to complete an argument.","zh":"這個片語描述完成論點所需的部分。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":4},{"front":"solve the puzzle","meaning":"解開謎團","examples":[{"en":"One or two missing factors are needed to solve the puzzle.","zh":"要解開謎團，需要一兩個缺失因素。"},{"en":"To solve the puzzle means to find the answer to a difficult question with several parts.","zh":"To solve the puzzle 指找出一個由多部分組成的困難問題的答案。"},{"en":"A detective solves the puzzle when small clues finally fit together.","zh":"當小線索終於拼合起來，偵探就解開謎團。"},{"en":"If researchers find the missing cause, they may solve the puzzle of why something happened.","zh":"如果研究人員找到缺失原因，他們可能解開某事為何發生的謎團。"},{"en":"This phrase suggests that a confusing problem can become clear.","zh":"這個片語暗示令人困惑的問題可以變得清楚。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":4},{"front":"propose that","meaning":"提出；認為","examples":[{"en":"Macfarlane proposes that the missing factors are tea and beer.","zh":"Macfarlane提出缺失因素是茶和啤酒。"},{"en":"To propose that something is true means to suggest it as an explanation or solution.","zh":"To propose that something is true 指把某事作為解釋或解決方法提出。"},{"en":"A doctor may propose that poor sleep is causing a patient’s headaches.","zh":"醫生可能提出病人的頭痛是由睡眠不足造成。"},{"en":"If someone proposes a new theory, others will examine the evidence.","zh":"如果有人提出新理論，其他人會檢視證據。"},{"en":"This phrase introduces a suggested answer, not necessarily a proven fact.","zh":"這個片語引出建議答案，而不一定是已證明事實。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":4},{"front":"be found in every kitchen cupboard","meaning":"可在每個廚櫃裏找到","examples":[{"en":"The missing factors may be found in every kitchen cupboard.","zh":"缺失因素可能可在每個廚櫃裏找到。"},{"en":"To be found in every kitchen cupboard means to be common and ordinary in daily homes.","zh":"To be found in every kitchen cupboard 指在日常家庭中常見而普通。"},{"en":"Salt, tea, and rice may be found in many kitchen cupboards.","zh":"鹽、茶和米可能可在許多廚櫃裏找到。"},{"en":"If an important clue is found in every kitchen cupboard, the answer may be simpler than expected.","zh":"如果重要線索可在每個廚櫃裏找到，答案可能比預期簡單。"},{"en":"This phrase contrasts an ordinary object with a surprisingly important role.","zh":"這個片語把普通物件與意想不到的重要角色作對比。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":4},{"front":"the nation’s favourite drinks","meaning":"全國最喜愛的飲品","examples":[{"en":"Tea and beer were two of the nation’s favourite drinks.","zh":"茶和啤酒是全國最喜愛的兩種飲品。"},{"en":"The nation’s favourite drinks are drinks loved or consumed by many people across a country.","zh":"The nation’s favourite drinks 是一個國家中許多人喜愛或飲用的飲品。"},{"en":"In some places, coffee is one of the nation’s favourite drinks because people drink it every morning.","zh":"在一些地方，咖啡是全國最喜愛的飲品之一，因為人們每天早上都喝。"},{"en":"When a drink becomes popular across all classes, it can influence everyday health and habits.","zh":"當一種飲品在所有階層中普及，它可以影響日常健康和習慣。"},{"en":"This phrase connects national culture with common drinking habits.","zh":"這個片語把國家文化與常見飲用習慣連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":4},{"front":"drive the revolution","meaning":"推動革命","examples":[{"en":"Macfarlane argues that tea and beer drove the revolution.","zh":"Macfarlane認為茶和啤酒推動了革命。"},{"en":"To drive the revolution means to be one of the forces that pushed a major change forward.","zh":"To drive the revolution 指成為推動重大變革向前發展的力量之一。"},{"en":"Cheap electricity can drive a technology revolution by making new tools affordable.","zh":"廉價電力可以透過令新工具負擔得起來推動科技革命。"},{"en":"If a factor improves health and increases labour supply, it may help drive industrial change.","zh":"如果某因素改善健康並增加勞動力供應，它可能幫助推動工業變革。"},{"en":"This phrase shows an active cause behind a large transformation.","zh":"這個片語顯示大型轉型背後的主動原因。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":5},{"front":"active ingredient","meaning":"活性成分","examples":[{"en":"Tannin is the active ingredient in tea.","zh":"單寧是茶中的活性成分。"},{"en":"An active ingredient is the part of a substance that produces its main effect.","zh":"Active ingredient 是物質中產生主要作用的部分。"},{"en":"In medicine, the active ingredient is the chemical that treats the illness.","zh":"在藥物中，活性成分是治療疾病的化學物質。"},{"en":"If an active ingredient kills bacteria, it can help make a drink safer.","zh":"如果活性成分能殺死細菌，它可以幫助令飲品更安全。"},{"en":"This phrase identifies the part that actually does the work.","zh":"這個片語指出真正發揮作用的部分。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":5},{"front":"hops","meaning":"啤酒花","examples":[{"en":"Hops are used in making beer.","zh":"啤酒花用於製作啤酒。"},{"en":"Hops are flowers from a plant used to flavour and preserve beer.","zh":"Hops 是一種植物的花，用來為啤酒調味和保鮮。"},{"en":"A brewer may add hops to beer to give it a bitter taste and help it last longer.","zh":"釀酒師可能把啤酒花加入啤酒，使其帶苦味並更耐存放。"},{"en":"Because hops can affect bacteria, they may help make beer safer to drink.","zh":"因為啤酒花可以影響細菌，它們可能幫助令啤酒更安全飲用。"},{"en":"This word refers to a plant ingredient closely linked with beer-making.","zh":"這個詞指與釀製啤酒密切相關的植物成分。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":5},{"front":"used in making","meaning":"用於製作……","examples":[{"en":"Hops are used in making beer.","zh":"啤酒花用於製作啤酒。"},{"en":"Used in making means used as a material or part of the process of producing something.","zh":"Used in making 指作為材料或生產過程的一部分來使用。"},{"en":"Flour is used in making bread, while eggs are used in making many cakes.","zh":"麵粉用於製作麵包，而雞蛋用於製作許多蛋糕。"},{"en":"If a material is used in making a product, it may affect the product’s taste, cost, or safety.","zh":"如果某材料用於製作產品，它可能影響產品的味道、成本或安全。"},{"en":"This phrase explains what role an ingredient has in production.","zh":"這個片語解釋某成分在生產中的角色。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":5},{"front":"antiseptic properties","meaning":"抗菌特性","examples":[{"en":"Tannin and hops both have antiseptic properties.","zh":"單寧和啤酒花都有抗菌特性。"},{"en":"Antiseptic properties are qualities that help kill germs or stop them from growing.","zh":"Antiseptic properties 是幫助殺死細菌或阻止其生長的特質。"},{"en":"A cleaning liquid has antiseptic properties if it helps reduce bacteria on a surface.","zh":"如果清潔液能幫助減少表面細菌，它便有抗菌特性。"},{"en":"If a drink has antiseptic properties, it may reduce the risk of disease from dirty water.","zh":"如果飲品有抗菌特性，它可能降低因污水而患病的風險。"},{"en":"This phrase connects a substance with protection against germs.","zh":"這個片語把物質與防止細菌連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":5},{"front":"made with boiled water","meaning":"用煮沸的水製成","examples":[{"en":"Tea and beer are both made with boiled water.","zh":"茶和啤酒都是用煮沸的水製成。"},{"en":"Made with boiled water means prepared using water that has been heated until it boils.","zh":"Made with boiled water 指使用已加熱至沸騰的水來製備。"},{"en":"Baby formula should be made with boiled water in places where water safety is uncertain.","zh":"在食水安全不確定的地方，嬰兒奶粉應用煮沸的水沖調。"},{"en":"Boiling water can kill many germs, so drinks made with boiled water may be safer.","zh":"煮沸水可以殺死許多細菌，所以用煮沸的水製成的飲品可能更安全。"},{"en":"This phrase explains why preparation method can affect health.","zh":"這個片語解釋製備方法如何影響健康。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":5},{"front":"prevent epidemics of","meaning":"預防……流行","examples":[{"en":"Boiled water helped prevent epidemics of waterborne diseases.","zh":"煮沸的水幫助預防水傳播疾病流行。"},{"en":"To prevent epidemics of a disease means to stop large outbreaks from happening.","zh":"To prevent epidemics of a disease 指阻止大型疾病爆發發生。"},{"en":"Clean water systems can prevent epidemics of cholera in crowded cities.","zh":"清潔食水系統可以在擁擠城市中預防霍亂流行。"},{"en":"If people drink safer water, fewer infections spread through a community.","zh":"如果人們飲用更安全的水，較少感染會在社區中傳播。"},{"en":"This phrase focuses on stopping disease before it spreads widely.","zh":"這個片語著重在疾病大規模傳播前阻止它。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":5},{"front":"waterborne diseases","meaning":"水傳播疾病","examples":[{"en":"Boiled water helped prevent waterborne diseases.","zh":"煮沸的水幫助預防水傳播疾病。"},{"en":"Waterborne diseases are illnesses spread through dirty or unsafe water.","zh":"Waterborne diseases 是透過污濁或不安全食水傳播的疾病。"},{"en":"People can get waterborne diseases if sewage enters drinking water.","zh":"如果污水進入飲用水，人們可能感染水傳播疾病。"},{"en":"Boiling water, filtering water, and improving sanitation can reduce waterborne diseases.","zh":"煮沸水、過濾水和改善衛生設施可以減少水傳播疾病。"},{"en":"This phrase connects disease with contaminated water.","zh":"這個片語把疾病與受污染食水連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":5},{"front":"dysentery","meaning":"痢疾","examples":[{"en":"Dysentery was a serious waterborne disease.","zh":"痢疾是一種嚴重的水傳播疾病。"},{"en":"Dysentery is an intestinal disease that can cause severe diarrhoea and dehydration.","zh":"Dysentery 是一種腸道疾病，可引致嚴重腹瀉和脫水。"},{"en":"People may catch dysentery when drinking water is contaminated with human waste.","zh":"當飲用水被人類排泄物污染，人們可能感染痢疾。"},{"en":"In crowded places without clean water, dysentery can spread quickly.","zh":"在沒有清潔食水的擁擠地方，痢疾可以迅速傳播。"},{"en":"This word names a dangerous disease linked with poor sanitation.","zh":"這個詞命名一種與惡劣衛生相關的危險疾病。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":5},{"front":"densely populated urban areas","meaning":"人口稠密的市區","examples":[{"en":"Waterborne diseases spread easily in densely populated urban areas.","zh":"水傳播疾病在人口稠密的市區容易傳播。"},{"en":"Densely populated urban areas are city places where many people live close together.","zh":"Densely populated urban areas 是很多人密集居住的城市地區。"},{"en":"A crowded district with small flats and busy streets is a densely populated urban area.","zh":"擁有細小單位和繁忙街道的擁擠地區，就是人口稠密的市區。"},{"en":"If sanitation is poor, disease can spread faster where people live closely together.","zh":"如果衛生設施差，人們住得近的地方疾病會傳播得更快。"},{"en":"This phrase links crowding in cities with public health risks.","zh":"這個片語把城市擁擠與公共健康風險連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":5},{"front":"require explanation","meaning":"需要解釋","examples":[{"en":"Historians noticed one factor that required explanation.","zh":"歷史學家注意到一個需要解釋的因素。"},{"en":"If something requires explanation, it is unusual or important enough to need a clear reason.","zh":"If something requires explanation，意思是它夠異常或重要，需要清楚理由。"},{"en":"A sudden drop in exam results requires explanation because teachers need to know what changed.","zh":"考試成績突然下降需要解釋，因為老師需要知道發生了甚麼變化。"},{"en":"When data does not match expectations, researchers look for an explanation.","zh":"當數據不符合預期，研究人員會尋找解釋。"},{"en":"This phrase shows that a fact cannot simply be ignored.","zh":"這個片語顯示某事實不能被簡單忽視。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":6},{"front":"around the mid-18th century","meaning":"大約在18世紀中期","examples":[{"en":"Historians noticed a population change around the mid-18th century.","zh":"歷史學家注意到大約在18世紀中期出現人口變化。"},{"en":"Around the mid-18th century means roughly near the middle of the 1700s.","zh":"Around the mid-18th century 指大約在1700年代中期附近。"},{"en":"A historian may say “around the mid-18th century” when the exact year is less important than the period.","zh":"當確切年份不如時期重要時，歷史學家可能說「大約在18世紀中期」。"},{"en":"If a change began around this time, researchers may look for events happening then.","zh":"如果變化大約在這時開始，研究人員可能尋找當時發生的事件。"},{"en":"This phrase gives an approximate historical time.","zh":"這個片語提供近似歷史時間。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":6},{"front":"the population was static","meaning":"人口保持不變","examples":[{"en":"Between about 1650 and 1740, the population was static.","zh":"大約1650年至1740年間，人口保持不變。"},{"en":"If the population was static, the number of people stayed almost the same.","zh":"If the population was static，意思是人口數量幾乎維持相同。"},{"en":"A town’s population may be static if births, deaths, and migration balance each other.","zh":"如果出生、死亡和遷移互相抵消，城鎮人口可能保持不變。"},{"en":"When a static population suddenly starts growing, historians look for causes.","zh":"當保持不變的人口突然開始增長，歷史學家會尋找原因。"},{"en":"This phrase describes little or no population growth.","zh":"這個片語描述人口幾乎沒有增長。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":6},{"front":"a burst in population","meaning":"人口突然增長","examples":[{"en":"After 1740, there was a burst in population.","zh":"1740年後，人口突然增長。"},{"en":"A burst in population is a sudden and noticeable increase in the number of people.","zh":"Burst in population 是人口數量突然而明顯增加。"},{"en":"A small town may see a burst in population after a new factory opens nearby.","zh":"新工廠在附近開設後，小鎮可能出現人口突然增長。"},{"en":"If child deaths fall quickly, a burst in population may follow.","zh":"如果兒童死亡迅速下降，人口突然增長可能隨之而來。"},{"en":"This phrase describes rapid growth rather than slow change.","zh":"這個片語描述快速增長，而不是緩慢變化。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":6},{"front":"infant mortality rate","meaning":"嬰兒死亡率","examples":[{"en":"The infant mortality rate fell sharply.","zh":"嬰兒死亡率急劇下降。"},{"en":"The infant mortality rate is the number of babies who die before reaching a certain young age, usually before one year old.","zh":"Infant mortality rate 是嬰兒在達到某個幼年年齡前死亡的數量，通常指一歲前。"},{"en":"Clean water and better healthcare can reduce the infant mortality rate.","zh":"清潔食水和更好醫療可以降低嬰兒死亡率。"},{"en":"If the infant mortality rate falls, more children survive and the population can grow.","zh":"如果嬰兒死亡率下降，更多兒童存活，人口可以增長。"},{"en":"This phrase is an important measure of public health.","zh":"這個片語是公共健康的重要指標。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":6},{"front":"halve in the space of","meaning":"在……期間減半","examples":[{"en":"The infant mortality rate halved in the space of 20 years.","zh":"嬰兒死亡率在20年間減半。"},{"en":"To halve in the space of a period means to fall to half its original amount within that time.","zh":"To halve in the space of a period 指在該段時間內下降至原本一半。"},{"en":"A school’s printing costs may halve in the space of a year if lessons move online.","zh":"如果課堂轉到網上，學校印刷成本可能在一年內減半。"},{"en":"If disease deaths halve in twenty years, public health has changed dramatically.","zh":"如果疾病死亡在20年間減半，公共健康已大幅改變。"},{"en":"This phrase shows a large reduction within a clear time period.","zh":"這個片語顯示在清晰時間段內的大幅減少。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":6},{"front":"rural areas and cities","meaning":"農村地區和城市","examples":[{"en":"The change happened in both rural areas and cities.","zh":"這種變化在農村地區和城市都發生。"},{"en":"Rural areas and cities means countryside places and urban places together.","zh":"Rural areas and cities 指鄉郊地方和城市地方一起。"},{"en":"A government policy may affect both rural areas and cities, but in different ways.","zh":"政府政策可能同時影響農村地區和城市，但方式不同。"},{"en":"If a change happens in rural areas and cities, it is not limited to one type of place.","zh":"如果變化在農村地區和城市都發生，它就不只限於一種地方。"},{"en":"This phrase helps show how widespread a change is.","zh":"這個片語幫助顯示變化有多廣泛。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":6},{"front":"across all classes","meaning":"跨越所有階層","examples":[{"en":"The fall in infant deaths happened across all classes.","zh":"嬰兒死亡下降跨越所有階層。"},{"en":"Across all classes means among every social class, from poor to rich.","zh":"Across all classes 指在每個社會階層中，從貧窮到富裕都包括。"},{"en":"A health campaign works well if benefits appear across all classes.","zh":"如果健康宣傳的好處出現在所有階層中，它就運作良好。"},{"en":"If a change affects rich and poor families alike, it may be caused by a common factor.","zh":"如果變化同時影響富裕和貧窮家庭，它可能由共同因素造成。"},{"en":"This phrase shows that the effect is not limited to one social group.","zh":"這個片語顯示影響不只限於一個社會群體。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":6},{"front":"possible causes","meaning":"可能原因","examples":[{"en":"Four possible causes have been suggested.","zh":"已有人提出四個可能原因。"},{"en":"Possible causes are explanations that may have produced a result but still need testing.","zh":"Possible causes 是可能造成某結果，但仍需測試的解釋。"},{"en":"If a student suddenly performs badly, possible causes include illness, stress, or lack of revision.","zh":"如果學生突然表現差，可能原因包括生病、壓力或缺乏溫習。"},{"en":"Researchers compare possible causes to see which one best fits the evidence.","zh":"研究人員比較可能原因，以看看哪一個最符合證據。"},{"en":"This phrase is useful when the answer is not yet certain.","zh":"當答案尚未確定時，這個片語很有用。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":6},{"front":"a sudden change in","meaning":"……的突然變化","examples":[{"en":"There may have been a sudden change in viruses and bacteria.","zh":"病毒和細菌可能出現了突然變化。"},{"en":"A sudden change in something is a quick and unexpected shift in its condition or behaviour.","zh":"Sudden change in something 是某事狀態或行為快速而意外的轉變。"},{"en":"A sudden change in weather can ruin an outdoor school event.","zh":"天氣的突然變化可以破壞戶外學校活動。"},{"en":"If there is a sudden change in disease patterns, doctors need to investigate quickly.","zh":"如果疾病模式出現突然變化，醫生需要迅速調查。"},{"en":"This phrase describes change that happens fast, not gradually.","zh":"這個片語描述快速發生的變化，而不是逐漸變化。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":6},{"front":"viruses and bacteria","meaning":"病毒和細菌","examples":[{"en":"A change in viruses and bacteria was unlikely.","zh":"病毒和細菌出現變化的可能性不大。"},{"en":"Viruses and bacteria are tiny organisms or agents that can cause disease.","zh":"Viruses and bacteria 是可以引起疾病的微小生物或病原體。"},{"en":"Doctors study viruses and bacteria to understand how infections spread.","zh":"醫生研究病毒和細菌，以理解感染如何傳播。"},{"en":"If viruses and bacteria enter dirty water, many people may become ill.","zh":"如果病毒和細菌進入污水，許多人可能生病。"},{"en":"This phrase names common causes of infectious disease.","zh":"這個片語命名傳染病的常見成因。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":7},{"front":"present at that time","meaning":"當時存在的","examples":[{"en":"The viruses and bacteria present at that time probably did not change suddenly.","zh":"當時存在的病毒和細菌可能沒有突然改變。"},{"en":"Present at that time means existing during the period being discussed.","zh":"Present at that time 指在所討論時期存在的。"},{"en":"The laws present at that time shaped how businesses were allowed to operate.","zh":"當時存在的法律塑造了企業可如何營運。"},{"en":"If the disease agents present at that time did not change, another cause must be considered.","zh":"如果當時存在的病原體沒有改變，就必須考慮另一個原因。"},{"en":"This phrase helps locate something within a specific historical period.","zh":"這個片語幫助把某事定位於特定歷史時期中。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":7},{"front":"a revolution in medical science","meaning":"醫學革命","examples":[{"en":"There was no revolution in medical science at that time.","zh":"當時並沒有醫學革命。"},{"en":"A revolution in medical science is a major change in medical knowledge, treatment, or practice.","zh":"Revolution in medical science 是醫學知識、治療或實踐上的重大改變。"},{"en":"The discovery of antibiotics was a revolution in medical science because it changed infection treatment.","zh":"抗生素的發現是醫學革命，因為它改變了感染治療。"},{"en":"If there was no medical revolution, falling death rates may need another explanation.","zh":"如果沒有醫學革命，死亡率下降可能需要另一個解釋。"},{"en":"This phrase describes a dramatic advance in medicine.","zh":"這個片語描述醫學上的巨大進步。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":7},{"front":"a century before","meaning":"在……的一個世紀之前","examples":[{"en":"This happened a century before Lister introduced antiseptic surgery.","zh":"這發生在Lister引入消毒外科手術的一個世紀之前。"},{"en":"A century before means one hundred years earlier than another event.","zh":"A century before 指比另一事件早一百年。"},{"en":"Printing became important centuries before computers changed reading habits.","zh":"印刷在電腦改變閱讀習慣之前數個世紀已變得重要。"},{"en":"If something happened a century before a medical discovery, that discovery cannot explain it.","zh":"如果某事發生在某醫學發現的一個世紀之前，該發現就不能解釋它。"},{"en":"This phrase compares two events in time.","zh":"這個片語比較兩個事件的時間。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":7},{"front":"introduce antiseptic surgery","meaning":"引入消毒外科手術","examples":[{"en":"Lister introduced antiseptic surgery much later.","zh":"Lister在很久之後才引入消毒外科手術。"},{"en":"To introduce antiseptic surgery means to begin using germ-killing methods during operations.","zh":"To introduce antiseptic surgery 指開始在手術中使用殺菌方法。"},{"en":"Hospitals introduce new safety procedures when evidence shows they reduce infection.","zh":"當證據顯示新安全程序能減少感染，醫院會引入它們。"},{"en":"If antiseptic surgery is introduced, fewer patients may die from infected wounds.","zh":"如果引入消毒外科手術，較少病人可能死於傷口感染。"},{"en":"This phrase describes bringing a new medical practice into use.","zh":"這個片語描述把新的醫療做法帶入使用。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":7},{"front":"environmental conditions","meaning":"環境條件","examples":[{"en":"Changes in environmental conditions were another possible explanation.","zh":"環境條件的變化是另一個可能解釋。"},{"en":"Environmental conditions are the physical surroundings that affect life, such as water, housing, weather, and sanitation.","zh":"Environmental conditions 是影響生活的實體周圍環境，例如食水、住屋、天氣和衛生。"},{"en":"Poor environmental conditions in a crowded building can make illness spread faster.","zh":"擁擠大廈中的惡劣環境條件可以令疾病更快傳播。"},{"en":"If environmental conditions improve, public health may improve even without new medicine.","zh":"如果環境條件改善，即使沒有新藥，公共健康也可能改善。"},{"en":"This phrase describes the surroundings that shape health and daily life.","zh":"這個片語描述塑造健康和日常生活的周圍環境。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":7},{"front":"improvements in agriculture","meaning":"農業方面的改善","examples":[{"en":"Improvements in agriculture helped wipe out malaria.","zh":"農業方面的改善幫助消滅瘧疾。"},{"en":"Improvements in agriculture are better farming methods, tools, drainage, crops, or land use.","zh":"Improvements in agriculture 是更好的農耕方法、工具、排水、作物或土地使用。"},{"en":"Better irrigation and stronger seeds are improvements in agriculture.","zh":"更好的灌溉和更強壯的種子都是農業方面的改善。"},{"en":"If farming improves, food supply may rise and some disease environments may change.","zh":"如果農業改善，食物供應可能上升，一些疾病環境也可能改變。"},{"en":"This phrase connects farming progress with wider social effects.","zh":"這個片語把農業進步與更廣泛社會影響連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":7},{"front":"wipe out malaria","meaning":"消滅瘧疾","examples":[{"en":"Agricultural improvements helped wipe out malaria.","zh":"農業改善幫助消滅瘧疾。"},{"en":"To wipe out malaria means to remove or eliminate malaria from an area.","zh":"To wipe out malaria 指從某地區清除或消除瘧疾。"},{"en":"Better drainage can help wipe out malaria by reducing mosquito breeding places.","zh":"更好的排水可以透過減少蚊子繁殖地來幫助消滅瘧疾。"},{"en":"If a disease is wiped out, people no longer catch it locally.","zh":"如果疾病被消滅，人們就不再在本地感染它。"},{"en":"This phrase describes complete removal, not just a small reduction.","zh":"這個片語描述完全清除，而不只是小幅減少。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":7},{"front":"small gains","meaning":"小幅收益；輕微改善","examples":[{"en":"The improvements produced only small gains.","zh":"這些改善只帶來小幅收益。"},{"en":"Small gains are limited improvements or benefits.","zh":"Small gains 是有限的改善或好處。"},{"en":"A student may make small gains in vocabulary after one week of reading.","zh":"學生閱讀一星期後，詞彙可能有輕微改善。"},{"en":"If a change produces only small gains, it cannot fully explain a major result.","zh":"如果某變化只帶來小幅收益，它不能完全解釋重大結果。"},{"en":"This phrase shows that progress exists but is not large enough.","zh":"這個片語顯示有進步，但幅度不足夠大。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":7},{"front":"sanitation","meaning":"衞生設施","examples":[{"en":"Sanitation did not become widespread until the 19th century.","zh":"衞生設施直到19世紀才變得普及。"},{"en":"Sanitation means systems and habits that keep human waste, dirty water, and germs away from people.","zh":"Sanitation 指把人類排泄物、污水和細菌遠離人們的制度和習慣。"},{"en":"Toilets, sewers, clean water, and waste collection are parts of sanitation.","zh":"廁所、污水渠、清潔食水和垃圾收集都是衛生設施的一部分。"},{"en":"Poor sanitation can lead to waterborne diseases in crowded communities.","zh":"惡劣衛生設施可以在擁擠社區中導致水傳播疾病。"},{"en":"This word is closely connected with public health and disease prevention.","zh":"這個詞與公共健康和疾病預防密切相關。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":7},{"front":"become widespread","meaning":"變得普及","examples":[{"en":"Sanitation did not become widespread until later.","zh":"衞生設施直到後來才變得普及。"},{"en":"To become widespread means to become common in many places or among many people.","zh":"To become widespread 指在許多地方或許多人之中變得常見。"},{"en":"Online payment became widespread when most shops began accepting it.","zh":"當大多數商店開始接受網上付款，它就變得普及。"},{"en":"If sanitation becomes widespread, fewer people are exposed to dirty water and waste.","zh":"如果衛生設施變得普及，較少人會接觸污水和排泄物。"},{"en":"This phrase describes something spreading from limited use to common use.","zh":"這個片語描述某事由有限使用變成普遍使用。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":8},{"front":"the only option left","meaning":"剩下的唯一可能","examples":[{"en":"The only option left was food.","zh":"剩下的唯一可能是食物。"},{"en":"The only option left means the only possible explanation or choice remaining after others have been rejected.","zh":"The only option left 指其他可能被排除後，剩下的唯一解釋或選擇。"},{"en":"If the bus, train, and taxi are unavailable, walking may be the only option left.","zh":"如果巴士、火車和的士都不可用，步行可能是剩下的唯一選擇。"},{"en":"When several causes fail to explain a result, researchers examine the only option left.","zh":"當幾個原因都不能解釋結果，研究人員會檢視剩下的唯一可能。"},{"en":"This phrase shows that other possibilities have already been considered.","zh":"這個片語顯示其他可能已經被考慮過。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":8},{"front":"height and weight statistics","meaning":"身高和體重統計數據","examples":[{"en":"Height and weight statistics showed a decline.","zh":"身高和體重統計數據顯示下降。"},{"en":"Height and weight statistics are numerical records of how tall and heavy people are.","zh":"Height and weight statistics 是人們身高和體重的數字記錄。"},{"en":"Doctors use height and weight statistics to check whether children are growing healthily.","zh":"醫生使用身高和體重統計數據來檢查兒童是否健康成長。"},{"en":"If height and weight statistics decline, nutrition or health may be getting worse.","zh":"如果身高和體重統計數據下降，營養或健康可能正在變差。"},{"en":"This phrase refers to body measurements used as evidence.","zh":"這個片語指用作證據的身體測量數據。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":8},{"front":"show a decline","meaning":"顯示下降","examples":[{"en":"The statistics showed a decline in health.","zh":"統計數據顯示健康下降。"},{"en":"To show a decline means to indicate that something has become lower, weaker, or worse.","zh":"To show a decline 指顯示某事變低、變弱或變差。"},{"en":"Test results may show a decline if students have missed many lessons.","zh":"如果學生缺席很多課，測驗結果可能顯示下降。"},{"en":"If health statistics show a decline, researchers must ask what caused it.","zh":"如果健康統計數據顯示下降，研究人員必須問原因是甚麼。"},{"en":"This phrase describes evidence of a downward change.","zh":"這個片語描述下降變化的證據。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":8},{"front":"get worse","meaning":"變差","examples":[{"en":"The food got worse during this period.","zh":"這段時期食物變差了。"},{"en":"To get worse means to become poorer in quality, condition, or seriousness.","zh":"To get worse 指在質素、狀況或嚴重程度上變差。"},{"en":"A cold can get worse if a student does not rest.","zh":"如果學生不休息，感冒可能變差。"},{"en":"If food gets worse, people may become weaker and more vulnerable to disease.","zh":"如果食物變差，人們可能變得更虛弱，更容易患病。"},{"en":"This phrase describes deterioration, not improvement.","zh":"這個片語描述惡化，而不是改善。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":8},{"front":"efforts to explain","meaning":"解釋……的努力","examples":[{"en":"Efforts to explain the reduction in child deaths appeared unsuccessful.","zh":"解釋兒童死亡減少的努力似乎不成功。"},{"en":"Efforts to explain something are attempts to find reasons for it.","zh":"Efforts to explain something 是尋找某事原因的嘗試。"},{"en":"Teachers may make efforts to explain why students are losing interest in reading.","zh":"老師可能努力解釋學生為何對閱讀失去興趣。"},{"en":"If efforts to explain a problem fail, researchers need new evidence or a new theory.","zh":"如果解釋問題的努力失敗，研究人員需要新證據或新理論。"},{"en":"This phrase focuses on the attempt to understand a cause.","zh":"這個片語著重理解原因的嘗試。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":8},{"front":"sudden reduction in","meaning":"……的突然減少","examples":[{"en":"Researchers tried to explain the sudden reduction in child deaths.","zh":"研究人員嘗試解釋兒童死亡的突然減少。"},{"en":"A sudden reduction in something is a quick and noticeable decrease.","zh":"Sudden reduction in something 是某事快速而明顯下降。"},{"en":"A sudden reduction in traffic may happen when a new train line opens.","zh":"新鐵路線開通後，交通量可能突然減少。"},{"en":"If there is a sudden reduction in deaths, public health may have changed quickly.","zh":"如果死亡突然減少，公共健康可能迅速改變。"},{"en":"This phrase describes a fast fall that needs explanation.","zh":"這個片語描述需要解釋的快速下降。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":8},{"front":"child deaths","meaning":"兒童死亡","examples":[{"en":"There was a sudden reduction in child deaths.","zh":"兒童死亡突然減少。"},{"en":"Child deaths are deaths of young children, often used as a measure of health conditions.","zh":"Child deaths 是年幼兒童死亡，常用作衡量健康條件的指標。"},{"en":"Clean drinking water can reduce child deaths in communities with poor sanitation.","zh":"在衛生設施差的社區，清潔飲用水可以減少兒童死亡。"},{"en":"If child deaths fall, more families keep their children and population may grow.","zh":"如果兒童死亡下降，更多家庭保住孩子，人口可能增長。"},{"en":"This phrase is serious and usually appears in health, history, or development discussions.","zh":"這個片語較嚴肅，通常出現在健康、歷史或發展討論中。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":8},{"front":"draw a blank","meaning":"找不到答案；毫無結果","examples":[{"en":"Efforts to explain the change appeared to draw a blank.","zh":"解釋這種變化的努力似乎毫無結果。"},{"en":"To draw a blank means to fail to find an answer, result, or useful information.","zh":"To draw a blank 指找不到答案、結果或有用資料。"},{"en":"A student may draw a blank in an exam when they cannot remember anything.","zh":"學生在考試中可能突然腦中一片空白，甚麼也想不起來。"},{"en":"If researchers draw a blank, they may need to ask a different question.","zh":"如果研究人員找不到答案，他們可能需要提出不同問題。"},{"en":"This phrase describes an unsuccessful search for an answer.","zh":"這個片語描述尋找答案失敗。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":8},{"front":"population burst","meaning":"人口突然增長","examples":[{"en":"This population burst provided labour for industry.","zh":"這次人口突然增長為工業提供了勞動力。"},{"en":"A population burst is a sudden increase in the number of people.","zh":"Population burst 是人口數量突然增加。"},{"en":"A new housing area may create a population burst in a once-small town.","zh":"新住宅區可能令曾經很小的城鎮出現人口突然增長。"},{"en":"If more children survive, a population burst can produce more future workers.","zh":"如果更多兒童存活，人口突然增長可以產生更多未來工人。"},{"en":"This phrase links rapid population growth with social and economic change.","zh":"這個片語把快速人口增長與社會和經濟變化連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":8},{"front":"at just the right time","meaning":"正好在適當時候","examples":[{"en":"The population burst happened at just the right time.","zh":"人口突然增長正好在適當時候發生。"},{"en":"At just the right time means exactly when it was most useful or needed.","zh":"At just the right time 指正好在最有用或最需要的時候。"},{"en":"The bus arrived at just the right time, just as the rain began.","zh":"巴士正好在適當時候到達，剛好雨開始下。"},{"en":"If more workers appear just when factories need them, the timing helps industry grow.","zh":"如果更多工人正好在工廠需要他們時出現，這個時機會幫助工業成長。"},{"en":"This phrase stresses perfect or very helpful timing.","zh":"這個片語強調完美或非常有幫助的時機。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":9},{"front":"provide labour for","meaning":"為……提供勞動力","examples":[{"en":"The population increase helped provide labour for the Industrial Revolution.","zh":"人口增加幫助為工業革命提供勞動力。"},{"en":"To provide labour for something means to supply the workers needed for it.","zh":"To provide labour for something 指提供某事所需的工人。"},{"en":"A new hospital needs nearby colleges to provide labour for nursing and support roles.","zh":"新醫院需要附近學院為護理和支援職位提供勞動力。"},{"en":"If a city has many young adults, it can provide labour for growing businesses.","zh":"如果城市有許多年輕成年人，它可以為成長中的企業提供勞動力。"},{"en":"This phrase connects population with available workers.","zh":"這個片語把人口與可用工人連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":9},{"front":"economically efficient","meaning":"經濟上有效率","examples":[{"en":"It was economically efficient to have people crowded together.","zh":"讓人們擠在一起在經濟上有效率。"},{"en":"Economically efficient means using money, labour, time, or resources in a way that reduces waste and increases output.","zh":"Economically efficient 指以減少浪費和增加產出的方式使用金錢、勞動力、時間或資源。"},{"en":"A bus system is economically efficient if it carries many passengers at low cost.","zh":"如果巴士系統以低成本運載許多乘客，它就在經濟上有效率。"},{"en":"Crowded cities may be economically efficient because workers and factories are close together.","zh":"擁擠城市可能在經濟上有效率，因為工人和工廠彼此靠近。"},{"en":"This phrase describes efficiency from an economic viewpoint, not comfort.","zh":"這個片語描述經濟角度的效率，而不是舒適。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":9},{"front":"crowded together","meaning":"擠在一起","examples":[{"en":"People were crowded together in towns and cities.","zh":"人們擠在城鎮和城市中。"},{"en":"Crowded together means many people are packed closely in the same place.","zh":"Crowded together 指許多人密集地擠在同一地方。"},{"en":"Passengers are crowded together on a train during rush hour.","zh":"在繁忙時間，乘客擠在火車中。"},{"en":"If people are crowded together without sanitation, disease can spread more easily.","zh":"如果人們在沒有衛生設施下擠在一起，疾病會更容易傳播。"},{"en":"This phrase describes physical closeness that may create problems.","zh":"這個片語描述可能造成問題的實體密集。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":9},{"front":"form towns and cities","meaning":"形成城鎮和城市","examples":[{"en":"Crowded populations helped form towns and cities.","zh":"擁擠人口幫助形成城鎮和城市。"},{"en":"To form towns and cities means to create or develop settlements where many people live and work.","zh":"To form towns and cities 指創造或發展許多人居住和工作的聚落。"},{"en":"A mining area may form towns when workers and families move nearby.","zh":"當工人和家庭搬到附近，採礦區可能形成城鎮。"},{"en":"If jobs gather in one place, people may move there and form cities.","zh":"如果工作集中在一個地方，人們可能搬到那裡並形成城市。"},{"en":"This phrase connects population concentration with urban development.","zh":"這個片語把人口集中與城市發展連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":9},{"front":"crowded living conditions","meaning":"擁擠的居住環境","examples":[{"en":"Crowded living conditions bring disease.","zh":"擁擠的居住環境會帶來疾病。"},{"en":"Crowded living conditions are situations where too many people live in too little space.","zh":"Crowded living conditions 是太多人住在太少空間中的情況。"},{"en":"A family sharing one small room may experience crowded living conditions.","zh":"一家人共用一個小房間，可能面對擁擠的居住環境。"},{"en":"If many people share water and toilets, crowded living conditions can spread infection.","zh":"如果許多人共用水源和廁所，擁擠居住環境可以傳播感染。"},{"en":"This phrase describes housing conditions that can harm health.","zh":"這個片語描述可能傷害健康的住屋條件。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":9},{"front":"bring disease","meaning":"帶來疾病","examples":[{"en":"Crowded living conditions can bring disease.","zh":"擁擠的居住環境可以帶來疾病。"},{"en":"To bring disease means to create conditions that allow illness to spread.","zh":"To bring disease 指創造讓疾病傳播的條件。"},{"en":"Dirty water can bring disease if people drink it every day.","zh":"如果人們每天飲用污水，它可以帶來疾病。"},{"en":"If waste is not removed, flies and polluted water may bring disease into homes.","zh":"如果排泄物沒有被清走，蒼蠅和污水可能把疾病帶入家中。"},{"en":"This phrase shows how an environment can cause illness.","zh":"這個片語顯示環境如何造成疾病。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":9},{"front":"particularly from","meaning":"尤其來自","examples":[{"en":"Disease came particularly from human waste.","zh":"疾病尤其來自人類排泄物。"},{"en":"Particularly from means especially from one important source.","zh":"Particularly from 指尤其來自某個重要來源。"},{"en":"Noise complaints may come particularly from flats near the main road.","zh":"噪音投訴可能尤其來自靠近大路的單位。"},{"en":"If disease comes particularly from dirty water, cleaning the water supply becomes essential.","zh":"如果疾病尤其來自污水，清潔食水供應就變得必要。"},{"en":"This phrase highlights the main source among several possible sources.","zh":"這個片語在幾個可能來源中突顯主要來源。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":9},{"front":"human waste","meaning":"人類排泄物","examples":[{"en":"Crowded towns suffered from disease caused by human waste.","zh":"擁擠城鎮受到由人類排泄物造成的疾病困擾。"},{"en":"Human waste means urine and faeces produced by people.","zh":"Human waste 指人產生的尿液和糞便。"},{"en":"If human waste enters a river, drinking water may become dangerous.","zh":"如果人類排泄物進入河流，飲用水可能變得危險。"},{"en":"Good sanitation keeps human waste away from homes, wells, and food.","zh":"良好衛生設施會讓人類排泄物遠離住所、水井和食物。"},{"en":"This phrase is often used in public health and sanitation discussions.","zh":"這個片語常用於公共健康和衛生討論。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":9},{"front":"historical records","meaning":"歷史記錄","examples":[{"en":"Some research in the historical records revealed a change.","zh":"對歷史記錄的一些研究揭示了一種變化。"},{"en":"Historical records are old documents, data, letters, registers, or reports that provide evidence about the past.","zh":"Historical records 是提供過去證據的舊文件、數據、信件、登記冊或報告。"},{"en":"Birth records and hospital notes can be historical records for studying health.","zh":"出生記錄和醫院筆記可以是研究健康的歷史記錄。"},{"en":"If historical records show fewer deaths, historians can test possible explanations.","zh":"如果歷史記錄顯示死亡減少，歷史學家可以測試可能解釋。"},{"en":"This phrase refers to evidence preserved from earlier times.","zh":"這個片語指從較早時期保存下來的證據。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":9},{"front":"reveal that","meaning":"揭示；顯示","examples":[{"en":"The historical records revealed that waterborne disease had changed.","zh":"歷史記錄揭示水傳播疾病已經改變。"},{"en":"To reveal that means to show or make known something that was not clear before.","zh":"To reveal that 指顯示或揭露以前不清楚的事情。"},{"en":"Test results may reveal that a student understands ideas but makes grammar mistakes.","zh":"測驗結果可能顯示學生理解概念，但犯文法錯誤。"},{"en":"If records reveal a pattern, researchers can build a stronger explanation.","zh":"如果記錄揭示某模式，研究人員可以建立更有力解釋。"},{"en":"This phrase introduces evidence that uncovers information.","zh":"這個片語引出揭露資訊的證據。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":10},{"front":"a change in the incidence of","meaning":"……發病率的變化","examples":[{"en":"There was a change in the incidence of waterborne disease.","zh":"水傳播疾病的發病率出現變化。"},{"en":"A change in the incidence of something means a change in how often it occurs.","zh":"Change in the incidence of something 指某事發生頻率的變化。"},{"en":"A doctor may notice a change in the incidence of flu during winter.","zh":"醫生可能在冬季注意到流感發病率的變化。"},{"en":"If the incidence of disease falls, fewer people are getting sick.","zh":"如果疾病發病率下降，代表較少人生病。"},{"en":"This phrase is common in health, statistics, and research writing.","zh":"這個片語常見於健康、統計和研究寫作。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":10},{"front":"at that time","meaning":"在當時","examples":[{"en":"The incidence of dysentery changed at that time.","zh":"痢疾的發病率在當時出現變化。"},{"en":"At that time means during the period being discussed.","zh":"At that time 指在所討論的時期。"},{"en":"At that time, many families still relied on wells for drinking water.","zh":"在當時，許多家庭仍依賴水井取得飲用水。"},{"en":"If a change happened at that time, historians compare it with other events from the same period.","zh":"如果變化在當時發生，歷史學家會把它與同一時期的其他事件比較。"},{"en":"This phrase links an event to a particular moment in history.","zh":"這個片語把事件連接到歷史中的特定時刻。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":10},{"front":"deduce that","meaning":"推斷","examples":[{"en":"Macfarlane deduced that British drinks were important.","zh":"Macfarlane推斷英國人的飲品很重要。"},{"en":"To deduce that something is true means to reach a conclusion by reasoning from evidence.","zh":"To deduce that something is true 指根據證據推理得出結論。"},{"en":"A teacher may deduce that students are confused if many make the same mistake.","zh":"如果許多學生犯同一錯誤，老師可能推斷他們感到困惑。"},{"en":"If records show disease falling after tea became common, a historian may deduce a connection.","zh":"如果記錄顯示茶普及後疾病下降，歷史學家可能推斷兩者有關。"},{"en":"This phrase describes logical conclusion, not random guessing.","zh":"這個片語描述合乎邏輯的結論，而不是隨機猜測。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":10},{"front":"whatever someone was drinking","meaning":"某人當時喝的東西","examples":[{"en":"Whatever the British were drinking must have been important.","zh":"英國人當時喝的東西一定很重要。"},{"en":"Whatever someone was drinking means the drink or drinks that person or group consumed, even if the exact one is not yet named.","zh":"Whatever someone was drinking 指某人或某群體所飲用的飲品，即使尚未確定是哪一種。"},{"en":"If several workers became sick after lunch, whatever they were drinking may need to be checked.","zh":"如果幾名工人在午飯後生病，他們當時喝的東西可能需要檢查。"},{"en":"When health changes suddenly, researchers may examine whatever people were drinking or eating.","zh":"當健康突然改變，研究人員可能檢視人們當時喝或吃的東西。"},{"en":"This phrase points to an unknown but important drink.","zh":"這個片語指未知但重要的飲品。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":10},{"front":"controlling disease","meaning":"控制疾病","examples":[{"en":"Drinks may have been important in controlling disease.","zh":"飲品在控制疾病方面可能很重要。"},{"en":"Controlling disease means reducing its spread, frequency, or harmful effects.","zh":"Controlling disease 指減少疾病的傳播、發生頻率或傷害。"},{"en":"Vaccination helps in controlling disease by reducing the number of people who become infected.","zh":"疫苗接種透過減少感染人數來幫助控制疾病。"},{"en":"Clean water and safe food are important in controlling disease in crowded areas.","zh":"在擁擠地區，清潔食水和安全食物對控制疾病很重要。"},{"en":"This phrase focuses on managing disease, not always eliminating it completely.","zh":"這個片語著重管理疾病，而不一定完全消滅疾病。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":10},{"front":"beer and ale","meaning":"啤酒和愛爾啤酒","examples":[{"en":"The British drank beer and ale.","zh":"英國人飲用啤酒和愛爾啤酒。"},{"en":"Beer and ale are alcoholic drinks made from grains, water, and fermentation.","zh":"Beer and ale 是由穀物、水和發酵製成的酒精飲品。"},{"en":"In the past, beer and ale were common daily drinks in some communities.","zh":"在過去，啤酒和愛爾啤酒在一些社區是常見日常飲品。"},{"en":"If beer and ale were made with boiled water, they may have been safer than untreated water.","zh":"如果啤酒和愛爾啤酒用煮沸的水製成，它們可能比未處理食水更安全。"},{"en":"This phrase names traditional drinks central to the passage’s argument.","zh":"這個片語命名文章論點中的核心傳統飲品。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":10},{"front":"for a long time","meaning":"長時間以來","examples":[{"en":"For a long time, the English were protected by hops.","zh":"長時間以來，英格蘭人受到啤酒花保護。"},{"en":"For a long time means during many years or a long period.","zh":"For a long time 指在許多年或很長一段時間內。"},{"en":"A family may keep the same recipe for a long time because everyone likes it.","zh":"一個家庭可能長時間保留同一食譜，因為人人都喜歡。"},{"en":"If a habit continues for a long time, it may affect health or culture deeply.","zh":"如果習慣持續很長時間，它可能深刻影響健康或文化。"},{"en":"This phrase stresses duration.","zh":"這個片語強調持續時間。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":10},{"front":"be protected by","meaning":"受到……保護","examples":[{"en":"The English were protected by the antibacterial agent in hops.","zh":"英格蘭人受到啤酒花中的抗菌劑保護。"},{"en":"To be protected by something means to be kept safer because of it.","zh":"To be protected by something 指因某事而變得較安全。"},{"en":"Cyclists are protected by helmets when they fall.","zh":"騎單車者跌倒時受到頭盔保護。"},{"en":"If a drink contains antibacterial substances, people may be protected from some germs.","zh":"如果飲品含有抗菌物質，人們可能受到保護，免受某些細菌影響。"},{"en":"This phrase shows what reduces danger or harm.","zh":"這個片語顯示甚麼減少危險或傷害。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":10},{"front":"strong antibacterial agent","meaning":"強效抗菌劑","examples":[{"en":"Hops contain a strong antibacterial agent.","zh":"啤酒花含有強效抗菌劑。"},{"en":"A strong antibacterial agent is a substance that can kill bacteria or stop them from growing effectively.","zh":"Strong antibacterial agent 是能有效殺死細菌或阻止細菌生長的物質。"},{"en":"Some cleaning products contain strong antibacterial agents for hospital surfaces.","zh":"一些清潔產品含有用於醫院表面的強效抗菌劑。"},{"en":"If a drink contains an antibacterial agent, it may stay safer for longer.","zh":"如果飲品含有抗菌劑，它可能保持安全更長時間。"},{"en":"This phrase identifies a substance that fights bacteria.","zh":"這個片語指出對抗細菌的物質。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":10},{"front":"be added to","meaning":"被加入……","examples":[{"en":"Hops were added to make beer last.","zh":"啤酒花被加入啤酒中，使啤酒更耐存放。"},{"en":"To be added to something means to be put into it as an extra ingredient or part.","zh":"To be added to something 指被放入某物中，成為額外成分或部分。"},{"en":"Sugar may be added to tea if someone wants a sweeter taste.","zh":"如果有人想茶更甜，可以把糖加入茶中。"},{"en":"If preservatives are added to food, the food may last longer.","zh":"如果防腐劑被加入食物，食物可能更耐存放。"},{"en":"This phrase explains how one thing is included in another.","zh":"這個片語解釋一物如何被加入另一物。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":11},{"front":"make beer last","meaning":"令啤酒更耐存放","examples":[{"en":"Hops were added to make beer last.","zh":"啤酒花被加入以令啤酒更耐存放。"},{"en":"To make beer last means to help beer remain drinkable for a longer time.","zh":"To make beer last 指幫助啤酒在更長時間內保持可飲用。"},{"en":"A fridge can make milk last by slowing the growth of bacteria.","zh":"雪櫃可以透過減慢細菌生長來令牛奶更耐存放。"},{"en":"If hops make beer last, beer can be stored and transported more safely.","zh":"如果啤酒花令啤酒更耐存放，啤酒就可以更安全地儲存和運輸。"},{"en":"This phrase describes preservation, not simply taste.","zh":"這個片語描述保存，而不只是味道。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":11},{"front":"a tax was introduced on","meaning":"對……徵稅","examples":[{"en":"In the late 17th century, a tax was introduced on malt.","zh":"17世紀後期，政府對麥芽徵稅。"},{"en":"If a tax is introduced on something, the government starts charging money on it.","zh":"If a tax is introduced on something，意思是政府開始向某物徵收費用。"},{"en":"A tax may be introduced on plastic bags to reduce waste.","zh":"政府可能對膠袋徵稅，以減少浪費。"},{"en":"When a tax is introduced on a product, its price often rises.","zh":"當某產品被徵稅，其價格通常會上升。"},{"en":"This phrase describes a new government charge.","zh":"這個片語描述新的政府收費。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":11},{"front":"malt","meaning":"麥芽","examples":[{"en":"A tax on malt made beer more expensive.","zh":"對麥芽徵稅令啤酒更昂貴。"},{"en":"Malt is grain, usually barley, prepared for use in making beer or whisky.","zh":"Malt 是經處理後用於製作啤酒或威士忌的穀物，通常是大麥。"},{"en":"Brewers use malt because it provides sugars needed for fermentation.","zh":"釀酒師使用麥芽，因為它提供發酵所需的糖分。"},{"en":"If malt becomes expensive, the cost of producing beer may rise.","zh":"如果麥芽變得昂貴，生產啤酒的成本可能上升。"},{"en":"This word names an important ingredient in beer-making.","zh":"這個詞命名啤酒製作中的重要成分。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":11},{"front":"the poor turned to","meaning":"窮人轉而選擇……","examples":[{"en":"The poor turned to water and gin.","zh":"窮人轉而選擇水和氈酒。"},{"en":"To turn to something means to start using it as an alternative when the usual choice is difficult or unavailable.","zh":"To turn to something 指當原本選擇困難或不可得時，開始使用另一選擇。"},{"en":"When buses stop running, commuters may turn to walking or cycling.","zh":"當巴士停駛，通勤者可能轉而選擇步行或踩單車。"},{"en":"If beer becomes too expensive, poorer people may turn to cheaper drinks.","zh":"如果啤酒變得太貴，較貧窮的人可能轉而選擇較便宜飲品。"},{"en":"This phrase shows a change in behaviour caused by need or pressure.","zh":"這個片語顯示由需要或壓力造成的行為改變。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":11},{"front":"gin","meaning":"氈酒","examples":[{"en":"The poor turned to water and gin.","zh":"窮人轉而選擇水和氈酒。"},{"en":"Gin is a strong alcoholic drink usually flavoured with juniper.","zh":"Gin 是一種烈酒，通常以杜松子調味。"},{"en":"In history, cheap gin was sometimes popular among poor urban communities.","zh":"在歷史上，廉價氈酒有時在貧窮城市社群中流行。"},{"en":"If people replace safer drinks with gin and unsafe water, public health may worsen.","zh":"如果人們以氈酒和不安全食水取代較安全飲品，公共健康可能惡化。"},{"en":"This word names an alcoholic drink that appears in the passage’s health argument.","zh":"這個詞命名文章健康論點中出現的一種酒精飲品。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":11},{"front":"mortality rate","meaning":"死亡率","examples":[{"en":"The mortality rate began to rise again.","zh":"死亡率開始再次上升。"},{"en":"The mortality rate is the rate at which people die in a population during a period.","zh":"Mortality rate 是某段時期內一個人口中人們死亡的比率。"},{"en":"Hospitals track mortality rates to understand whether treatment is improving.","zh":"醫院追蹤死亡率，以理解治療是否改善。"},{"en":"If disease spreads through water, the mortality rate may rise.","zh":"如果疾病透過食水傳播，死亡率可能上升。"},{"en":"This phrase is a measure of death in a group or society.","zh":"這個片語是群體或社會中死亡情況的指標。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":11},{"front":"begin to rise","meaning":"開始上升","examples":[{"en":"The mortality rate began to rise again in the 1720s.","zh":"死亡率在1720年代開始再次上升。"},{"en":"To begin to rise means to start increasing.","zh":"To begin to rise 指開始增加。"},{"en":"Prices may begin to rise when a product becomes scarce.","zh":"當產品變得稀缺，價格可能開始上升。"},{"en":"If deaths begin to rise, doctors and officials need to find the cause quickly.","zh":"如果死亡開始上升，醫生和官員需要快速找出原因。"},{"en":"This phrase describes the start of an upward trend.","zh":"這個片語描述上升趨勢的開始。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":11},{"front":"suddenly drop again","meaning":"突然再次下降","examples":[{"en":"The mortality rate suddenly dropped again.","zh":"死亡率突然再次下降。"},{"en":"To suddenly drop again means to fall quickly after having risen or changed before.","zh":"To suddenly drop again 指在之前上升或變化後快速再次下降。"},{"en":"A shop’s sales may suddenly drop again after a short holiday rush ends.","zh":"假期短暫旺季結束後，商店銷售可能突然再次下降。"},{"en":"If disease deaths suddenly drop again, something may have improved health conditions.","zh":"如果疾病死亡突然再次下降，可能有某事改善了健康條件。"},{"en":"This phrase highlights a rapid second decrease.","zh":"這個片語突顯第二次快速下降。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":11},{"front":"look to","meaning":"參考；把目光轉向","examples":[{"en":"Macfarlane looked to Japan for comparison.","zh":"Macfarlane把目光轉向日本作比較。"},{"en":"To look to a place or example means to examine it for help, evidence, or comparison.","zh":"To look to a place or example 指檢視它，以取得幫助、證據或比較。"},{"en":"A school may look to another school for ideas about improving reading lessons.","zh":"學校可能參考另一間學校，以取得改善閱讀課的想法。"},{"en":"If one country has a similar problem but different results, historians may look to it for comparison.","zh":"如果一個國家有相似問題但結果不同，歷史學家可能把目光轉向它作比較。"},{"en":"This phrase describes using another example to understand something.","zh":"這個片語描述使用另一個例子來理解某事。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":11},{"front":"develop large cities","meaning":"發展大城市","examples":[{"en":"Japan was also developing large cities at about the same time.","zh":"日本大約在同一時間也在發展大城市。"},{"en":"To develop large cities means to grow major urban centres with many people, jobs, and services.","zh":"To develop large cities 指發展有許多人、工作和服務的主要城市中心。"},{"en":"A country may develop large cities when trade, jobs, and transport improve.","zh":"當貿易、工作和交通改善，一個國家可能發展大城市。"},{"en":"If large cities develop without sanitation, disease can become a serious risk.","zh":"如果大城市在沒有衛生設施下發展，疾病可能成為嚴重風險。"},{"en":"This phrase connects urban growth with social change.","zh":"這個片語把城市增長與社會變化連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":12},{"front":"at about the same time","meaning":"大約在同一時間","examples":[{"en":"Japan was developing large cities at about the same time.","zh":"日本大約在同一時間發展大城市。"},{"en":"At about the same time means during roughly the same period.","zh":"At about the same time 指大約在同一時期。"},{"en":"Two students may start learning English at about the same time but progress differently.","zh":"兩名學生可能大約在同一時間開始學英文，但進步不同。"},{"en":"If two countries changed at about the same time, historians may compare them.","zh":"如果兩個國家大約在同一時間改變，歷史學家可能比較它們。"},{"en":"This phrase gives approximate timing for comparison.","zh":"這個片語提供用於比較的近似時間。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":12},{"front":"have no sanitation","meaning":"沒有衞生設施","examples":[{"en":"Japan also had no sanitation.","zh":"日本也沒有衛生設施。"},{"en":"To have no sanitation means to lack proper systems for toilets, sewage, clean water, and waste control.","zh":"To have no sanitation 指缺乏適當的廁所、污水、清潔食水和廢物控制系統。"},{"en":"A crowded camp with no sanitation can become dangerous very quickly.","zh":"沒有衛生設施的擁擠營地可以很快變得危險。"},{"en":"If a city has no sanitation, waste may pollute water and spread disease.","zh":"如果城市沒有衛生設施，排泄物可能污染食水並傳播疾病。"},{"en":"This phrase describes a serious public health problem.","zh":"這個片語描述嚴重公共健康問題。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":12},{"front":"far fewer than","meaning":"遠少於","examples":[{"en":"Waterborne diseases in Japan were far fewer than those in Britain.","zh":"日本的水傳播疾病遠少於英國。"},{"en":"Far fewer than means much smaller in number than another group or amount.","zh":"Far fewer than 指數量比另一群體或數量少得多。"},{"en":"This year, far fewer students were absent than last year.","zh":"今年缺席學生遠少於去年。"},{"en":"If one city has far fewer disease cases, researchers ask what protects it.","zh":"如果一個城市疾病個案遠少於另一個，研究人員會問是甚麼保護了它。"},{"en":"This phrase shows a strong numerical contrast.","zh":"這個片語顯示強烈數量對比。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":12},{"front":"the prevalence of","meaning":"……的普及","examples":[{"en":"Macfarlane considered the prevalence of tea in Japanese culture.","zh":"Macfarlane考慮了茶在日本文化中的普及。"},{"en":"The prevalence of something is how common or widespread it is.","zh":"Prevalence of something 是某事有多常見或多普及。"},{"en":"Doctors study the prevalence of asthma to see how many children are affected.","zh":"醫生研究哮喘的普及程度，以了解有多少兒童受影響。"},{"en":"If the prevalence of tea drinking is high, many people may share the same health habit.","zh":"如果飲茶普及率高，許多人可能有同一健康習慣。"},{"en":"This phrase describes how common something is in a group or society.","zh":"這個片語描述某事在群體或社會中有多常見。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":12},{"front":"the role of","meaning":"……的作用","examples":[{"en":"Macfarlane thought about the role of tea in Britain.","zh":"Macfarlane思考茶在英國的作用。"},{"en":"The role of something means the part it plays in causing, supporting, or explaining a result.","zh":"Role of something 指某事在造成、支持或解釋結果中所扮演的部分。"},{"en":"A teacher may examine the role of sleep in students’ exam performance.","zh":"老師可能檢視睡眠在學生考試表現中的作用。"},{"en":"If tea affected disease, its role in population growth may have been important.","zh":"如果茶影響疾病，它在人口增長中的作用可能很重要。"},{"en":"This phrase asks what function or influence something has.","zh":"這個片語詢問某事有甚麼功能或影響。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":12},{"front":"provide an extraordinary coincidence of dates","meaning":"提供日期上的驚人巧合","examples":[{"en":"The history of tea in Britain provided an extraordinary coincidence of dates.","zh":"英國茶的歷史提供了日期上的驚人巧合。"},{"en":"To provide an extraordinary coincidence of dates means to show that two important events happened at surprisingly similar times.","zh":"To provide an extraordinary coincidence of dates 指顯示兩件重要事件在令人驚訝地相近時間發生。"},{"en":"If a school introduced breakfast and exam results rose the same year, that would be a striking coincidence of dates.","zh":"如果學校推出早餐計劃，而考試成績同年上升，那會是日期上的顯著巧合。"},{"en":"A coincidence of dates can suggest a connection, but it does not prove one by itself.","zh":"日期上的巧合可以暗示關聯，但本身不能證明關聯。"},{"en":"This phrase highlights timing that seems too interesting to ignore.","zh":"這個片語突顯似乎太有趣而不能忽視的時間重合。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":12},{"front":"relatively expensive","meaning":"相對昂貴","examples":[{"en":"Tea was relatively expensive until direct trade with China began.","zh":"在與中國直接貿易開始前，茶相對昂貴。"},{"en":"Relatively expensive means costly compared with other things or compared with a later time.","zh":"Relatively expensive 指與其他東西或較後時期相比較昂貴。"},{"en":"Imported fruit may be relatively expensive if transport costs are high.","zh":"如果運輸成本高，進口水果可能相對昂貴。"},{"en":"If tea becomes less expensive, more ordinary families can afford it.","zh":"如果茶變得不那麼昂貴，更多普通家庭便能負擔。"},{"en":"This phrase describes price in comparison, not absolute cost.","zh":"這個片語描述比較下的價格，而不是絕對成本。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":12},{"front":"direct trade with","meaning":"與……直接貿易","examples":[{"en":"Britain started direct trade with China in the early 18th century.","zh":"英國在18世紀初開始與中國直接貿易。"},{"en":"Direct trade with a country means buying and selling goods with it without going mainly through another country.","zh":"Direct trade with a country 指與該國買賣貨物，而不是主要透過另一國。"},{"en":"A shop may get lower prices through direct trade with farmers.","zh":"商店可能透過與農民直接貿易取得較低價格。"},{"en":"If direct trade begins, goods may become cheaper and more widely available.","zh":"如果直接貿易開始，商品可能變得更便宜和更普及。"},{"en":"This phrase connects trade routes with access to products.","zh":"這個片語把貿易路線與取得產品連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":12},{"front":"by the 1740s","meaning":"到1740年代","examples":[{"en":"By the 1740s, tea had become common.","zh":"到1740年代，茶已變得常見。"},{"en":"By the 1740s means at or before the decade from 1740 to 1749.","zh":"By the 1740s 指在1740年至1749年這個十年期間或之前。"},{"en":"By the 1990s, mobile phones had started to become more familiar to the public.","zh":"到1990年代，手機已開始為公眾所熟悉。"},{"en":"If tea had become common by the 1740s, historians can compare that timing with falling mortality.","zh":"如果茶到1740年代已變得普及，歷史學家可以把這個時間與死亡率下降作比較。"},{"en":"This phrase marks the latest point by which something had happened.","zh":"這個片語標示某事已經發生的最遲時間點。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":12},{"front":"infant mortality was falling","meaning":"嬰兒死亡率正在下降","examples":[{"en":"Infant mortality was falling when tea became common.","zh":"當茶變得常見時，嬰兒死亡率正在下降。"},{"en":"Infant mortality was falling means fewer babies were dying than before.","zh":"Infant mortality was falling 指嬰兒死亡比以前少。"},{"en":"Infant mortality may fall when mothers have cleaner water and better nutrition.","zh":"當母親有更清潔食水和更好營養，嬰兒死亡率可能下降。"},{"en":"If infant mortality is falling at the same time as a new habit spreads, researchers may examine a connection.","zh":"如果嬰兒死亡率在新習慣傳播的同時下降，研究人員可能檢視兩者關聯。"},{"en":"This phrase describes improving survival among babies.","zh":"這個片語描述嬰兒存活情況改善。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":13},{"front":"have to be boiled","meaning":"必須被煮沸","examples":[{"en":"Water had to be boiled before tea could be made.","zh":"水必須被煮沸，茶才可以製成。"},{"en":"If water has to be boiled, it must be heated until it reaches boiling point.","zh":"If water has to be boiled，意思是水必須被加熱至沸點。"},{"en":"In some camps, drinking water has to be boiled before it is safe.","zh":"在一些營地，飲用水必須被煮沸才安全。"},{"en":"Boiling water can kill germs, so water that has to be boiled may become safer to drink.","zh":"煮沸水可以殺死細菌，所以必須被煮沸的水可能變得更安全可飲。"},{"en":"This phrase explains a required preparation step.","zh":"這個片語解釋一個必要的準備步驟。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":13},{"front":"together with","meaning":"加上；連同","examples":[{"en":"Boiled water, together with tea’s properties, may have improved health.","zh":"煮沸的水加上茶的特性，可能改善了健康。"},{"en":"Together with means combined with or along with another factor.","zh":"Together with 指與另一因素結合或連同。"},{"en":"Good sleep, together with regular revision, can improve exam performance.","zh":"良好睡眠加上定期溫習，可以改善考試表現。"},{"en":"If boiled water works together with antibacterial substances, the health effect may be stronger.","zh":"如果煮沸的水連同抗菌物質一起作用，健康效果可能更強。"},{"en":"This phrase shows that two factors act jointly.","zh":"這個片語顯示兩個因素共同作用。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":13},{"front":"stomach-purifying properties","meaning":"淨化腸胃的特性","examples":[{"en":"Tea was believed to have stomach-purifying properties.","zh":"人們相信茶具有淨化腸胃的特性。"},{"en":"Stomach-purifying properties are qualities believed to clean, calm, or improve the stomach.","zh":"Stomach-purifying properties 是被認為能清潔、舒緩或改善腸胃的特質。"},{"en":"Some people drink warm tea because they believe it has stomach-purifying properties.","zh":"有些人喝熱茶，因為他們相信它有淨化腸胃的特性。"},{"en":"If a drink helps reduce stomach problems, people may treat it as protective.","zh":"如果飲品幫助減少腸胃問題，人們可能把它視為有保護作用。"},{"en":"This phrase describes a health-related quality linked with digestion.","zh":"這個片語描述與消化相關的健康特質。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":13},{"front":"eloquently described","meaning":"被生動有力地描述","examples":[{"en":"The properties of tea were eloquently described in Buddhist texts.","zh":"茶的特性在佛教典籍中被生動有力地描述。"},{"en":"Eloquently described means explained in a clear, powerful, and expressive way.","zh":"Eloquently described 指以清晰、有力和富表達力的方式解釋。"},{"en":"A speaker eloquently described the problem by using simple examples and strong evidence.","zh":"演講者透過簡單例子和有力證據，生動有力地描述問題。"},{"en":"If a benefit is eloquently described, readers may understand and remember it better.","zh":"如果好處被生動有力地描述，讀者可能更明白並更記得。"},{"en":"This phrase praises the quality of the explanation.","zh":"這個片語讚揚解釋的質素。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":13},{"front":"Buddhist texts","meaning":"佛教典籍","examples":[{"en":"Buddhist texts described the benefits of tea.","zh":"佛教典籍描述了茶的好處。"},{"en":"Buddhist texts are writings connected with Buddhist teachings, stories, practices, or philosophy.","zh":"Buddhist texts 是與佛教教義、故事、修行或哲學相關的文字。"},{"en":"A student studying religion may read Buddhist texts to understand ideas about suffering and discipline.","zh":"研究宗教的學生可能閱讀佛教典籍，以理解關於痛苦和紀律的思想。"},{"en":"If Buddhist texts praise tea, they may show how tea was connected with health and culture.","zh":"如果佛教典籍讚揚茶，它們可能顯示茶如何與健康和文化連接。"},{"en":"This phrase refers to religious or philosophical writings in Buddhism.","zh":"這個片語指佛教中的宗教或哲學著作。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":13},{"front":"breast milk","meaning":"母乳","examples":[{"en":"Healthier mothers may have produced healthier breast milk.","zh":"較健康的母親可能產生較健康的母乳。"},{"en":"Breast milk is the milk produced by a mother to feed her baby.","zh":"Breast milk 是母親為餵養嬰兒而產生的乳汁。"},{"en":"Babies depend on breast milk for nutrition and protection in early life.","zh":"嬰兒在生命早期依賴母乳獲得營養和保護。"},{"en":"If mothers are healthier, their babies may also become healthier through breast milk.","zh":"如果母親較健康，嬰兒也可能透過母乳變得較健康。"},{"en":"This phrase connects mothers’ health with infant health.","zh":"這個片語把母親健康與嬰兒健康連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":13},{"front":"healthier than it had ever been","meaning":"比以往任何時候都健康","examples":[{"en":"Breast milk may have been healthier than it had ever been.","zh":"母乳可能比以往任何時候都健康。"},{"en":"Healthier than it had ever been means healthier than at any earlier time.","zh":"Healthier than it had ever been 指比任何較早時候都健康。"},{"en":"A school lunch programme may become healthier than it has ever been after sugar is reduced.","zh":"學校午餐計劃在減糖後可能比以往任何時候都健康。"},{"en":"If mothers drink safer water, breast milk may become healthier than before.","zh":"如果母親飲用更安全的水，母乳可能比以前更健康。"},{"en":"This phrase makes a strong comparison with the past.","zh":"這個片語與過去作出強烈比較。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":13},{"front":"no other European nation","meaning":"沒有其他歐洲國家","examples":[{"en":"No other European nation drank tea as often as the British.","zh":"沒有其他歐洲國家像英國人一樣頻繁飲茶。"},{"en":"No other European nation means none of the other countries in Europe.","zh":"No other European nation 指歐洲其他國家中沒有一個。"},{"en":"No other class in the school practised speaking as often as this one.","zh":"學校沒有其他班像這個班一樣頻繁練習口語。"},{"en":"If no other nation had the same tea habit, Britain’s experience may have been unusual.","zh":"如果沒有其他國家有同樣飲茶習慣，英國的經驗可能很不尋常。"},{"en":"This phrase highlights uniqueness in comparison with a whole group.","zh":"這個片語在與整個群體比較時突顯獨特性。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":13},{"front":"as often as","meaning":"像……一樣頻繁","examples":[{"en":"No other European nation drank tea as often as the British.","zh":"沒有其他歐洲國家像英國人一樣頻繁飲茶。"},{"en":"As often as means with the same frequency as another person or group.","zh":"As often as 指頻率與另一人或群體相同。"},{"en":"Few students read newspapers as often as they check messages.","zh":"很少學生像查看訊息一樣頻繁閱讀報紙。"},{"en":"If one group drinks tea as often as another, their habits are similar in frequency.","zh":"如果一群人像另一群人一樣頻繁飲茶，他們的習慣在頻率上相似。"},{"en":"This phrase compares how frequently something happens.","zh":"這個片語比較某事發生得有多頻繁。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":13},{"front":"by Macfarlane’s logic","meaning":"按照Macfarlane的邏輯","examples":[{"en":"By Macfarlane’s logic, tea helped Britain win the industrial race.","zh":"按照Macfarlane的邏輯，茶幫助英國贏得工業競賽。"},{"en":"By someone’s logic means according to that person’s reasoning.","zh":"By someone’s logic 指按照某人的推理。"},{"en":"By the teacher’s logic, regular short practice is better than one long revision session.","zh":"按照老師的邏輯，定期短練習比一次長時間溫習更好。"},{"en":"If we follow Macfarlane’s reasoning, tea becomes a key part of the explanation.","zh":"如果我們跟隨Macfarlane的推理，茶就成為解釋中的關鍵部分。"},{"en":"This phrase shows that a conclusion depends on a particular line of reasoning.","zh":"這個片語顯示結論取決於某條特定推理線。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":14},{"front":"push someone out of the race","meaning":"把某人擠出競賽","examples":[{"en":"Tea pushed other nations out of the race for the Industrial Revolution.","zh":"茶把其他國家擠出工業革命競賽。"},{"en":"To push someone out of the race means to make them unable to compete successfully.","zh":"To push someone out of the race 指令某人無法成功競爭。"},{"en":"High costs can push small shops out of the race against large chains.","zh":"高成本可以把小店擠出與大型連鎖店的競賽。"},{"en":"If one country gains a major advantage, others may be pushed out of the race.","zh":"如果一個國家取得重大優勢，其他國家可能被擠出競賽。"},{"en":"This phrase describes losing a competition because another side becomes too strong.","zh":"這個片語描述因另一方變得太強而失去競爭資格。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":14},{"front":"the race for","meaning":"爭奪……的競賽","examples":[{"en":"Other nations lost the race for the Industrial Revolution.","zh":"其他國家輸掉了爭奪工業革命的競賽。"},{"en":"The race for something is a competition to achieve or obtain it first.","zh":"The race for something 是爭取率先達成或取得某事的競爭。"},{"en":"Several companies are in the race for better battery technology.","zh":"幾間公司正在參與爭奪更好電池技術的競賽。"},{"en":"If one country industrialises first, it may win the race for economic power.","zh":"如果一個國家率先工業化，它可能贏得經濟力量競賽。"},{"en":"This phrase presents progress as a competition.","zh":"這個片語把進步呈現為競爭。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":14},{"front":"a factor in the puzzle","meaning":"謎題中的一個因素","examples":[{"en":"Tea may be a factor in the puzzle.","zh":"茶可能是謎題中的一個因素。"},{"en":"A factor in the puzzle is one important part of a larger, difficult explanation.","zh":"Factor in the puzzle 是較大、較困難解釋中的一個重要部分。"},{"en":"Lack of sleep may be a factor in the puzzle of why students perform badly.","zh":"睡眠不足可能是解釋學生表現差這個謎題中的一個因素。"},{"en":"If one factor fits the evidence, it can help complete the explanation.","zh":"如果一個因素符合證據，它可以幫助完成解釋。"},{"en":"This phrase shows that one cause is part of a wider problem.","zh":"這個片語顯示一個原因是更廣泛問題的一部分。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":14},{"front":"large cities","meaning":"大城市","examples":[{"en":"Japan had large cities in the 17th century.","zh":"日本在17世紀已有大城市。"},{"en":"Large cities are major urban centres with many people, jobs, buildings, and services.","zh":"Large cities 是擁有許多人、工作、建築和服務的主要城市中心。"},{"en":"Large cities often need strong transport, housing, water, and sanitation systems.","zh":"大城市通常需要強大的交通、住屋、食水和衛生系統。"},{"en":"If large cities grow quickly, disease and overcrowding may become serious problems.","zh":"如果大城市快速增長，疾病和擁擠可能成為嚴重問題。"},{"en":"This phrase describes city size and social complexity.","zh":"這個片語描述城市規模和社會複雜性。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":14},{"front":"high literacy rates","meaning":"高識字率","examples":[{"en":"Japan had high literacy rates in the 17th century.","zh":"日本在17世紀已有高識字率。"},{"en":"High literacy rates mean a large proportion of people can read and write.","zh":"High literacy rates 指很大比例的人能閱讀和寫作。"},{"en":"A country with high literacy rates can share written information more easily.","zh":"識字率高的國家可以更容易分享書面資訊。"},{"en":"If literacy rates are high, workers may learn instructions and records more effectively.","zh":"如果識字率高，工人可能更有效學習指示和紀錄。"},{"en":"This phrase describes widespread reading and writing ability.","zh":"這個片語描述廣泛的閱讀和寫作能力。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":14},{"front":"a futures market","meaning":"期貨市場","examples":[{"en":"Japan even had a futures market.","zh":"日本甚至有期貨市場。"},{"en":"A futures market is a market where people agree to buy or sell goods at a future date for a set price.","zh":"Futures market 是人們同意在未來日期以固定價格買賣貨物的市場。"},{"en":"Farmers may use a futures market to reduce risk before harvest.","zh":"農民可能使用期貨市場，在收成前降低風險。"},{"en":"If a society has a futures market, it may have advanced trade and financial systems.","zh":"如果一個社會有期貨市場，它可能有先進的貿易和金融制度。"},{"en":"This phrase describes a specialised form of market trading.","zh":"這個片語描述一種專門的市場交易形式。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":14},{"front":"decide against","meaning":"決定不採取；決定反對","examples":[{"en":"Japan decided against a work-based revolution.","zh":"日本決定不採取以勞動為本的革命。"},{"en":"To decide against something means to choose not to do it.","zh":"To decide against something 指選擇不做某事。"},{"en":"A family may decide against buying a car if public transport is good.","zh":"如果公共交通良好，家庭可能決定不買車。"},{"en":"If a country fears unemployment, it may decide against using labour-saving machines.","zh":"如果一個國家害怕失業，它可能決定不採用省力機器。"},{"en":"This phrase describes rejecting an option after consideration.","zh":"這個片語描述考慮後拒絕某選項。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":14},{"front":"a work-based revolution","meaning":"以勞動為本的革命","examples":[{"en":"Japan decided against a work-based revolution.","zh":"日本決定不採取以勞動為本的革命。"},{"en":"A work-based revolution is a major change centred on labour, human effort, and working methods.","zh":"Work-based revolution 是以勞動、人力努力和工作方法為中心的重大改變。"},{"en":"A school may have a work-based change if teachers redesign how students practise every day.","zh":"如果老師重新設計學生每日練習方式，學校可能有以工作為本的改變。"},{"en":"If a society chooses more human labour instead of machines, it may follow a work-based path.","zh":"如果社會選擇更多人力而不是機器，它可能走上以勞動為本的道路。"},{"en":"This phrase contrasts labour-centred change with machine-centred industrialisation.","zh":"這個片語把以勞動為中心的改變與以機器為中心的工業化作對比。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":14},{"front":"give up","meaning":"放棄","examples":[{"en":"Japan gave up labour-saving devices.","zh":"日本放棄了省力裝置。"},{"en":"To give up something means to stop using it, trying it, or keeping it.","zh":"To give up something 指停止使用、嘗試或保留某事。"},{"en":"A student may give up a bad study habit after seeing poor results.","zh":"學生看見差劣成績後，可能放棄壞學習習慣。"},{"en":"If a society gives up a useful technology, it may be choosing social stability over efficiency.","zh":"如果社會放棄有用科技，它可能是在選擇社會穩定而不是效率。"},{"en":"This phrase describes letting go of something.","zh":"這個片語描述放下某事。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":14},{"front":"labour-saving devices","meaning":"省力裝置","examples":[{"en":"Japan gave up labour-saving devices to avoid unemployment.","zh":"日本為了避免失業而放棄省力裝置。"},{"en":"Labour-saving devices are tools or machines that reduce the amount of human work needed.","zh":"Labour-saving devices 是減少所需人力工作的工具或機器。"},{"en":"A washing machine is a labour-saving device because it reduces hand washing.","zh":"洗衣機是省力裝置，因為它減少手洗衣物。"},{"en":"If factories use labour-saving devices, fewer workers may be needed for the same output.","zh":"如果工廠使用省力裝置，同樣產量可能需要較少工人。"},{"en":"This phrase links technology with reduced human labour.","zh":"這個片語把科技與人力減少連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":15},{"front":"put people out of work","meaning":"令某人失業","examples":[{"en":"Japan avoided using devices that might put people out of work.","zh":"日本避免使用可能令人失業的裝置。"},{"en":"To put people out of work means to make people lose their jobs.","zh":"To put people out of work 指令某些人失去工作。"},{"en":"A shop closing down can put several workers out of work.","zh":"商店倒閉可以令幾名工人失業。"},{"en":"If machines replace workers too quickly, they may put people out of work.","zh":"如果機器太快取代工人，它們可能令人失業。"},{"en":"This phrase focuses on unemployment caused by change.","zh":"這個片語著重由變化造成的失業。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":15},{"front":"astonishingly","meaning":"令人驚訝的是","examples":[{"en":"Astonishingly, Japan almost abandoned the wheel.","zh":"令人驚訝的是，日本幾乎放棄使用輪子。"},{"en":"Astonishingly means in a way that is very surprising or hard to believe.","zh":"Astonishingly 指以非常令人驚訝或難以相信的方式。"},{"en":"Astonishingly, the quiet student gave the best speech in the class.","zh":"令人驚訝的是，那位安靜的學生作出了全班最好的演講。"},{"en":"Writers use this word when a fact strongly challenges what readers expect.","zh":"當事實強烈挑戰讀者預期，作者會使用這個詞。"},{"en":"This word signals surprise and emphasis.","zh":"這個詞標示驚訝和強調。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":15},{"front":"technologically advanced","meaning":"科技先進","examples":[{"en":"Japan is now seen as technologically advanced.","zh":"日本現在被視為科技先進。"},{"en":"Technologically advanced means having highly developed machines, tools, systems, or scientific knowledge.","zh":"Technologically advanced 指擁有高度發展的機器、工具、系統或科學知識。"},{"en":"A technologically advanced hospital may use robots, digital records, and precise scanners.","zh":"科技先進的醫院可能使用機械人、數碼紀錄和精準掃描器。"},{"en":"If a country is technologically advanced, people may expect it to use modern machines widely.","zh":"如果一個國家科技先進，人們可能預期它廣泛使用現代機器。"},{"en":"This phrase describes a high level of technological development.","zh":"這個片語描述高水平科技發展。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":15},{"front":"enter the 19th century","meaning":"進入19世紀","examples":[{"en":"Japan entered the 19th century having almost abandoned the wheel.","zh":"日本進入19世紀時，幾乎已放棄使用輪子。"},{"en":"To enter the 19th century means to reach the period from 1801 to 1900.","zh":"To enter the 19th century 指到達1801年至1900年這段時期。"},{"en":"A country may enter a new century with old habits and new pressures at the same time.","zh":"一個國家可能帶着舊習慣和新壓力同時進入新世紀。"},{"en":"If Japan entered the 19th century without using the wheel widely, its development path was unusual.","zh":"如果日本進入19世紀時沒有廣泛使用輪子，它的發展道路就很不尋常。"},{"en":"This phrase marks the historical period a society moves into.","zh":"這個片語標示社會進入的歷史時期。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":15},{"front":"abandon the wheel","meaning":"放棄使用輪子","examples":[{"en":"Japan almost abandoned the wheel.","zh":"日本幾乎放棄使用輪子。"},{"en":"To abandon the wheel means to stop using wheeled transport or technology in many situations.","zh":"To abandon the wheel 指在許多情況下停止使用帶輪運輸或技術。"},{"en":"A village might abandon carts if narrow mountain paths make them useless.","zh":"如果狹窄山路令車子無用，村莊可能放棄使用手推車。"},{"en":"If people abandon the wheel, they may rely more on human labour or animals.","zh":"如果人們放棄使用輪子，他們可能更依賴人力或動物。"},{"en":"This phrase is surprising because wheels are normally seen as basic technology.","zh":"這個片語令人驚訝，因為輪子通常被視為基本技術。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":15},{"front":"undergo the Industrial Revolution","meaning":"經歷工業革命","examples":[{"en":"Britain was undergoing the Industrial Revolution.","zh":"英國正在經歷工業革命。"},{"en":"To undergo the Industrial Revolution means to experience the major shift to factory-based industrial production.","zh":"To undergo the Industrial Revolution 指經歷轉向工廠式工業生產的重大轉變。"},{"en":"A society undergoing industrialisation may see new factories, crowded towns, and changing jobs.","zh":"正在經歷工業化的社會可能出現新工廠、擁擠城鎮和工作變化。"},{"en":"If a country undergoes an industrial revolution, its economy and daily life can change deeply.","zh":"如果一個國家經歷工業革命，它的經濟和日常生活可能深刻改變。"},{"en":"This phrase describes experiencing a major historical transformation.","zh":"這個片語描述經歷重大歷史轉型。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":15},{"front":"note wryly","meaning":"帶點諷刺地指出","examples":[{"en":"Macfarlane notes wryly that Japan was undergoing an industrious revolution.","zh":"Macfarlane帶點諷刺地指出，日本正在經歷勤勞型革命。"},{"en":"To note wryly means to point something out with dry humour or mild irony.","zh":"To note wryly 指以冷面幽默或輕微諷刺指出某事。"},{"en":"A teacher may note wryly that students who hate writing still send hundreds of messages.","zh":"老師可能帶點諷刺地指出，討厭寫作的學生仍然每天發數百條訊息。"},{"en":"If a fact is ironic, a writer may note it wryly rather than state it plainly.","zh":"如果某事實具有諷刺意味，作者可能帶點諷刺地指出，而不是平淡陳述。"},{"en":"This phrase describes a slightly humorous, ironic observation.","zh":"這個片語描述略帶幽默和諷刺的觀察。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":15},{"front":"an industrious one","meaning":"勤勞型革命","examples":[{"en":"Japan was undergoing an industrious revolution rather than an industrial one.","zh":"日本正在經歷勤勞型革命，而不是工業革命。"},{"en":"An industrious one means a revolution based on hard work and human effort rather than machines.","zh":"An industrious one 指以勤奮工作和人力努力，而不是機器為基礎的革命。"},{"en":"A family business may grow through an industrious approach if everyone works long hours.","zh":"如果每個人都長時間工作，家庭企業可能透過勤勞型方式成長。"},{"en":"If a society avoids machines but increases human effort, its revolution may be industrious rather than industrial.","zh":"如果社會避免機器但增加人力努力，它的革命可能是勤勞型而不是工業型。"},{"en":"This phrase creates a contrast between hard work and machine industry.","zh":"這個片語在勤奮工作和機器工業之間建立對比。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":15},{"front":"consider the mystery solved","meaning":"認為謎團已解開","examples":[{"en":"The Cambridge academic considers the mystery solved.","zh":"這位劍橋學者認為謎團已解開。"},{"en":"To consider the mystery solved means to believe that the answer to a difficult question has been found.","zh":"To consider the mystery solved 指相信困難問題的答案已經找到。"},{"en":"A doctor may consider the mystery solved when tests finally show the cause of a patient’s pain.","zh":"當檢查終於顯示病人疼痛原因，醫生可能認為謎團已解開。"},{"en":"If evidence fits the timing and the pattern, a researcher may think the mystery is solved.","zh":"如果證據符合時間和模式，研究人員可能認為謎團已解開。"},{"en":"This phrase expresses confidence that a puzzling problem has been explained.","zh":"這個片語表達對困惑問題已獲解釋的信心。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":15},{"front":"encourage aid agencies to","meaning":"鼓勵援助機構去……","examples":[{"en":"Macfarlane thinks the UN should encourage aid agencies to distribute tea.","zh":"Macfarlane認為聯合國應鼓勵援助機構分發茶。"},{"en":"To encourage aid agencies to do something means to urge relief organisations to take that action.","zh":"To encourage aid agencies to do something 指敦促救援組織採取該行動。"},{"en":"Governments may encourage aid agencies to provide clean water after floods.","zh":"水災後，政府可能鼓勵援助機構提供清潔食水。"},{"en":"If tea is believed to protect health, someone may encourage aid agencies to include it in supplies.","zh":"如果茶被認為能保護健康，有人可能鼓勵援助機構把它包括在物資中。"},{"en":"This phrase connects advice with humanitarian action.","zh":"這個片語把建議與人道行動連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":16},{"front":"aid agencies","meaning":"援助機構","examples":[{"en":"Aid agencies could take tea to trouble spots.","zh":"援助機構可以把茶帶到動盪地區。"},{"en":"Aid agencies are organisations that provide help, food, medicine, shelter, or support during crises.","zh":"Aid agencies 是在危機中提供幫助、食物、藥物、住所或支援的組織。"},{"en":"Aid agencies often work after wars, earthquakes, floods, or famines.","zh":"援助機構常在戰爭、地震、水災或饑荒後工作。"},{"en":"If a region lacks clean water, aid agencies may bring supplies and medical help.","zh":"如果某地區缺乏清潔食水，援助機構可能帶來物資和醫療幫助。"},{"en":"This phrase refers to organisations that assist people in need.","zh":"這個片語指協助有需要人士的組織。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":16},{"front":"trouble spots","meaning":"動盪地區；問題地區","examples":[{"en":"The UN could send tea to the world’s trouble spots.","zh":"聯合國可以把茶送到世界上的動盪地區。"},{"en":"Trouble spots are places affected by conflict, disaster, poverty, disease, or political instability.","zh":"Trouble spots 是受衝突、災害、貧窮、疾病或政治不穩影響的地方。"},{"en":"Aid workers may travel to trouble spots after floods destroy homes.","zh":"水災摧毀房屋後，援助人員可能前往問題地區。"},{"en":"If a trouble spot lacks safe water, disease can spread quickly.","zh":"如果動盪地區缺乏安全食水，疾病可以迅速傳播。"},{"en":"This phrase describes areas where serious problems need outside help.","zh":"這個片語描述需要外部援助的嚴重問題地區。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":16},{"front":"rehydration sachets","meaning":"口服補液包","examples":[{"en":"Aid agencies often provide rehydration sachets.","zh":"援助機構常提供口服補液包。"},{"en":"Rehydration sachets are small packets of salts and sugar mixed with water to treat dehydration.","zh":"Rehydration sachets 是與水混合，用來治療脫水的小包鹽和糖。"},{"en":"A child with severe diarrhoea may need rehydration sachets to replace lost fluids.","zh":"嚴重腹瀉的兒童可能需要口服補液包來補充流失水分。"},{"en":"In places with dysentery, rehydration sachets can help prevent deaths from dehydration.","zh":"在有痢疾的地方，口服補液包可以幫助防止因脫水而死亡。"},{"en":"This phrase refers to simple medical supplies used in emergencies.","zh":"這個片語指緊急情況中使用的簡單醫療用品。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":16},{"front":"food rations","meaning":"食物配給","examples":[{"en":"Aid agencies may provide food rations in trouble spots.","zh":"援助機構可能在動盪地區提供食物配給。"},{"en":"Food rations are fixed amounts of food given to people during emergencies or shortages.","zh":"Food rations 是在緊急情況或短缺中給人們的固定份量食物。"},{"en":"After a flood, families may receive food rations until shops reopen.","zh":"水災後，家庭可能收到食物配給，直到商店重開。"},{"en":"If food supplies are limited, rations help distribute them more fairly.","zh":"如果食物供應有限，配給有助更公平地分發食物。"},{"en":"This phrase describes controlled food support in difficult situations.","zh":"這個片語描述困難情況中的受控食物支援。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":16},{"front":"the most suitable headings","meaning":"最合適的標題","examples":[{"en":"Students choose the most suitable headings for the paragraphs.","zh":"學生為段落選擇最合適的標題。"},{"en":"The most suitable headings are the titles that best summarise the main ideas of paragraphs.","zh":"The most suitable headings 是最能概括段落主要意思的標題。"},{"en":"In a reading test, a heading is suitable only if it matches the whole paragraph, not one small detail.","zh":"在閱讀測驗中，只有當標題符合整段，而不是一個小細節，它才算合適。"},{"en":"If students choose headings too quickly, they may miss the main point.","zh":"如果學生太快選標題，可能錯過主要觀點。"},{"en":"This phrase is common in paragraph-heading questions.","zh":"這個片語常見於段落標題配對題。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":16},{"front":"from the list of headings below","meaning":"從以下標題列表中","examples":[{"en":"The headings are chosen from the list of headings below.","zh":"標題從以下標題列表中選出。"},{"en":"From the list of headings below means from the answer choices printed underneath the instruction.","zh":"From the list of headings below 指從指示下方印出的答案選項中選擇。"},{"en":"Students should read all options from the list of headings below before matching paragraphs.","zh":"學生配對段落前，應先閱讀以下標題列表中的所有選項。"},{"en":"If there are similar headings, careful comparison is needed.","zh":"如果標題相似，就需要仔細比較。"},{"en":"This phrase gives exam instructions about where to choose answers.","zh":"這個片語提供關於從哪裡選答案的考試指示。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":16},{"front":"appropriate numbers","meaning":"適當號碼","examples":[{"en":"Students write the appropriate numbers for the sections.","zh":"學生為各部分寫上適當號碼。"},{"en":"Appropriate numbers are the correct numbered answers that match each section.","zh":"Appropriate numbers 是與每個部分相符的正確編號答案。"},{"en":"In a matching task, students may write the appropriate numbers beside each paragraph.","zh":"在配對題中，學生可能在每段旁寫上適當號碼。"},{"en":"If the number does not match the main idea, the answer is wrong even if one word appears in the paragraph.","zh":"如果號碼不符合主要意思，即使段落中出現某個字，答案也是錯的。"},{"en":"This phrase refers to correct numbered choices in an exam.","zh":"這個片語指考試中的正確編號選項。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":16},{"front":"more headings than sections","meaning":"標題多於段落","examples":[{"en":"There are more headings than sections.","zh":"標題多於段落。"},{"en":"More headings than sections means there are extra heading options that will not be used.","zh":"More headings than sections 指標題選項有多餘項目，不會全部使用。"},{"en":"In IELTS reading, there may be more headings than paragraphs to make matching harder.","zh":"在IELTS閱讀中，標題可能多於段落，使配對更困難。"},{"en":"If there are extra choices, students should not expect every heading to be used.","zh":"如果有額外選項，學生不應期望每個標題都會被使用。"},{"en":"This phrase warns students to select carefully.","zh":"這個片語提醒學生小心選擇。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":16},{"front":"the significance of","meaning":"……的重要性","examples":[{"en":"One heading refers to the significance of tea drinking.","zh":"其中一個標題提到飲茶的重要性。"},{"en":"The significance of something is its importance or meaning in a situation.","zh":"The significance of something 是某事在某情況中的重要性或意義。"},{"en":"A teacher may explain the significance of clean water in public health.","zh":"老師可能解釋清潔食水在公共健康中的重要性。"},{"en":"If tea affected mortality, the significance of tea drinking would be greater than simple taste.","zh":"如果茶影響死亡率，飲茶的重要性就不只是味道。"},{"en":"This phrase asks why something matters.","zh":"這個片語詢問某事為何重要。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":16},{"front":"tea drinking","meaning":"飲茶","examples":[{"en":"The significance of tea drinking is discussed in the passage.","zh":"文章討論了飲茶的重要性。"},{"en":"Tea drinking means the habit or practice of drinking tea.","zh":"Tea drinking 指飲用茶的習慣或做法。"},{"en":"Tea drinking may be a daily family habit after meals or during breaks.","zh":"飲茶可能是飯後或休息時的日常家庭習慣。"},{"en":"If tea drinking requires boiled water, it may reduce exposure to unsafe water.","zh":"如果飲茶需要煮沸的水，它可能減少接觸不安全食水。"},{"en":"This phrase refers to a cultural habit that may also affect health.","zh":"這個片語指一種文化習慣，也可能影響健康。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":17},{"front":"possible solution to","meaning":"……的可能解答","examples":[{"en":"Tea and beer may offer a possible solution to the puzzle.","zh":"茶和啤酒可能為這個謎題提供可能解答。"},{"en":"A possible solution to a problem is an answer that may explain or fix it.","zh":"Possible solution to a problem 是可能解釋或解決某問題的答案。"},{"en":"Extra reading practice may be a possible solution to weak vocabulary.","zh":"額外閱讀練習可能是詞彙薄弱的可能解答。"},{"en":"If one explanation fits several pieces of evidence, it may be a possible solution.","zh":"如果一個解釋符合幾項證據，它可能是可能解答。"},{"en":"This phrase shows that an answer is promising but not necessarily final.","zh":"這個片語顯示答案有希望，但不一定是最終答案。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":17},{"front":"significant population increase","meaning":"顯著人口增長","examples":[{"en":"The passage discusses a significant population increase.","zh":"文章討論顯著人口增長。"},{"en":"A significant population increase is a large and important rise in the number of people.","zh":"Significant population increase 是人口數量大幅而重要地上升。"},{"en":"A new university may cause a significant population increase in a small town.","zh":"新大學可能令小鎮出現顯著人口增長。"},{"en":"If deaths fall and births remain high, a significant population increase can follow.","zh":"如果死亡下降而出生率保持高，顯著人口增長可能隨之而來。"},{"en":"This phrase describes growth large enough to matter socially or economically.","zh":"這個片語描述足以在社會或經濟上產生影響的增長。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":17},{"front":"the relationship between","meaning":"……之間的關係","examples":[{"en":"The passage explains the relationship between drinks and disease.","zh":"文章解釋飲品與疾病之間的關係。"},{"en":"The relationship between two things is the way they are connected or affect each other.","zh":"Relationship between two things 是兩者如何連接或互相影響。"},{"en":"Students may study the relationship between sleep and exam performance.","zh":"學生可能研究睡眠與考試表現之間的關係。"},{"en":"If drinks change disease rates, the relationship between diet and health becomes important.","zh":"如果飲品改變疾病率，飲食與健康之間的關係就變得重要。"},{"en":"This phrase helps discuss links, causes, or patterns.","zh":"這個片語幫助討論連繫、原因或模式。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":17},{"front":"drinks and disease","meaning":"飲品與疾病","examples":[{"en":"The relationship between drinks and disease is central to the argument.","zh":"飲品與疾病之間的關係是論點的核心。"},{"en":"Drinks and disease refers to how what people drink may affect illness and health.","zh":"Drinks and disease 指人們飲用的東西如何影響疾病和健康。"},{"en":"Dirty water can connect drinks and disease because it carries germs into the body.","zh":"污水可以把飲品與疾病連接起來，因為它把細菌帶入身體。"},{"en":"If tea and beer were safer than water, drinks may have reduced disease.","zh":"如果茶和啤酒比水安全，飲品可能減少疾病。"},{"en":"This phrase links everyday drinking habits with public health.","zh":"這個片語把日常飲用習慣與公共健康連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":17},{"front":"preconditions necessary for","meaning":"……所需的前提條件","examples":[{"en":"The passage lists preconditions necessary for the Industrial Revolution.","zh":"文章列出工業革命所需的前提條件。"},{"en":"Preconditions necessary for something are conditions that must exist before it can happen.","zh":"Preconditions necessary for something 是某事發生前必須存在的條件。"},{"en":"Clear rules and trained teachers are preconditions necessary for a safe school trip.","zh":"清晰規則和受過訓練的老師是安全學校旅行所需的前提條件。"},{"en":"If preconditions are missing, a major plan may fail before it begins.","zh":"如果缺少前提條件，重大計劃可能在開始前已失敗。"},{"en":"This phrase focuses on requirements that come before an event.","zh":"這個片語著重事件發生前的要求。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":17},{"front":"complete the table using","meaning":"使用……完成表格","examples":[{"en":"Students complete the table using words from the passage.","zh":"學生使用文章中的字詞完成表格。"},{"en":"Complete the table using something means fill in missing table information with that source.","zh":"Complete the table using something 指用該來源填寫表格中缺失的資料。"},{"en":"In a reading test, students complete the table using exact words from the text.","zh":"在閱讀測驗中，學生使用文本中的原字完成表格。"},{"en":"If the instruction says to use the passage, outside knowledge should not be added.","zh":"如果指示說使用文章，就不應加入外部知識。"},{"en":"This phrase gives a clear exam-task instruction.","zh":"這個片語提供清晰的考試任務指示。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":17},{"front":"no more than three words","meaning":"不超過三個字","examples":[{"en":"Students should use no more than three words for each answer.","zh":"學生每個答案應使用不超過三個字。"},{"en":"No more than three words means the answer can contain one, two, or three words only.","zh":"No more than three words 指答案只能包含一、二或三個字。"},{"en":"If the answer has four words, it breaks the instruction even if the idea is right.","zh":"如果答案有四個字，即使意思正確，也違反指示。"},{"en":"Students should copy only the necessary words from the passage.","zh":"學生應只從文章中抄寫必要字詞。"},{"en":"This phrase limits the maximum answer length.","zh":"這個片語限制答案的最長長度。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":17},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must come from the passage.","zh":"答案必須從文章中取得。"},{"en":"From the passage means taken directly or clearly based on the reading text.","zh":"From the passage 指直接取自或清楚根據閱讀文本。"},{"en":"If a question asks for words from the passage, students should not use their own synonyms.","zh":"如果題目要求使用文章中的字詞，學生不應使用自己的同義詞。"},{"en":"Answers from the passage are safer because they match the exam source.","zh":"從文章中取得的答案較安全，因為它們符合考試來源。"},{"en":"This phrase tells students where evidence and wording should come from.","zh":"這個片語告訴學生證據和用字應來自哪裡。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":17},{"front":"social change in Britain","meaning":"英國的社會變化","examples":[{"en":"The table summarises social change in Britain.","zh":"表格概述英國的社會變化。"},{"en":"Social change in Britain means changes in British society, such as population, habits, health, or work.","zh":"Social change in Britain 指英國社會中的變化，例如人口、習慣、健康或工作。"},{"en":"A rise in tea drinking is an example of social change if it affects daily family life.","zh":"如果飲茶增加影響日常家庭生活，它就是社會變化的一個例子。"},{"en":"If social change affects health and labour, it may also influence industrial growth.","zh":"如果社會變化影響健康和勞動力，它也可能影響工業增長。"},{"en":"This phrase focuses on changes in society, not only politics or machines.","zh":"這個片語著重社會中的改變，而不只是政治或機器。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":17},{"front":"effect on population","meaning":"對人口的影響","examples":[{"en":"The table asks about the effect on population.","zh":"表格詢問對人口的影響。"},{"en":"Effect on population means how something changes the number, health, growth, or structure of people in a society.","zh":"Effect on population 指某事如何改變社會中人口的數量、健康、增長或結構。"},{"en":"Better healthcare can have a strong effect on population by reducing deaths.","zh":"更好醫療可以透過減少死亡對人口產生強烈影響。"},{"en":"If a drink reduces disease, its effect on population may be population growth.","zh":"如果一種飲品減少疾病，它對人口的影響可能是人口增長。"},{"en":"This phrase asks what happens to people as a group.","zh":"這個片語詢問作為群體的人口發生甚麼變化。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":18},{"front":"main drinks","meaning":"主要飲品","examples":[{"en":"Beer and ale were the main drinks in Britain.","zh":"啤酒和愛爾啤酒是英國的主要飲品。"},{"en":"Main drinks are the drinks most commonly consumed by a group of people.","zh":"Main drinks 是某群體最常飲用的飲品。"},{"en":"In some homes, water and tea are the main drinks served with meals.","zh":"在一些家庭中，水和茶是用餐時提供的主要飲品。"},{"en":"If the main drinks are safe, daily disease risk may be lower.","zh":"如果主要飲品安全，日常疾病風險可能較低。"},{"en":"This phrase identifies the most usual drinks in a society or period.","zh":"這個片語指出某社會或時期中最常見的飲品。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":18},{"front":"no significant change","meaning":"沒有顯著變化","examples":[{"en":"There was no significant change in the population.","zh":"人口沒有顯著變化。"},{"en":"No significant change means no important or noticeable difference.","zh":"No significant change 指沒有重要或明顯差異。"},{"en":"A student may study more but see no significant change in marks after only one day.","zh":"學生可能更努力溫習，但只過一天成績沒有顯著變化。"},{"en":"If population shows no significant change, births and deaths may be balancing each other.","zh":"如果人口沒有顯著變化，出生和死亡可能互相抵消。"},{"en":"This phrase describes stability rather than meaningful movement.","zh":"這個片語描述穩定，而不是有意義的變動。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":18},{"front":"become more popular","meaning":"變得更受歡迎","examples":[{"en":"Gin became more popular among poor people.","zh":"氈酒在窮人之中變得更受歡迎。"},{"en":"To become more popular means to be liked, used, or chosen by more people.","zh":"To become more popular 指被更多人喜愛、使用或選擇。"},{"en":"Online lessons became more popular when students could study from home.","zh":"當學生可以在家學習，網上課堂變得更受歡迎。"},{"en":"If a cheaper drink becomes more popular, people may buy less of the expensive one.","zh":"如果較便宜飲品變得更受歡迎，人們可能較少購買昂貴飲品。"},{"en":"This phrase describes increasing public use or preference.","zh":"這個片語描述公眾使用或偏好的增加。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":18},{"front":"especially with","meaning":"尤其在……之中","examples":[{"en":"Gin became more popular, especially with poor people.","zh":"氈酒變得更受歡迎，尤其在窮人之中。"},{"en":"Especially with means particularly among a certain group.","zh":"Especially with 指尤其在某個群體之中。"},{"en":"Short videos are popular, especially with younger students.","zh":"短片很受歡迎，尤其在年輕學生之中。"},{"en":"If a product is especially popular with poorer consumers, price may be an important reason.","zh":"如果某產品尤其受較貧窮消費者歡迎，價格可能是重要原因。"},{"en":"This phrase highlights the group most strongly connected with a trend.","zh":"這個片語突顯與某趨勢最強烈相關的群體。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":18},{"front":"mortality rate goes up","meaning":"死亡率上升","examples":[{"en":"The mortality rate goes up when disease increases.","zh":"當疾病增加，死亡率上升。"},{"en":"If the mortality rate goes up, more people are dying in a population.","zh":"If the mortality rate goes up，意思是一個人口中有更多人死亡。"},{"en":"The mortality rate may go up during a serious epidemic.","zh":"在嚴重疫症期間，死亡率可能上升。"},{"en":"If unsafe water spreads disease, the mortality rate can go up quickly.","zh":"如果不安全食水傳播疾病，死亡率可以迅速上升。"},{"en":"This phrase describes an increase in deaths.","zh":"這個片語描述死亡增加。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":18},{"front":"start to become widespread","meaning":"開始普及","examples":[{"en":"Tea drinking started to become widespread in the early 18th century.","zh":"飲茶在18世紀初開始普及。"},{"en":"To start to become widespread means to begin spreading to many people or places.","zh":"To start to become widespread 指開始傳播到許多人或地方。"},{"en":"Online payment started to become widespread when small shops began accepting it.","zh":"當小店開始接受網上付款，它就開始普及。"},{"en":"If tea drinking becomes widespread, it can affect the habits of a whole society.","zh":"如果飲茶變得普及，它可以影響整個社會的習慣。"},{"en":"This phrase describes the beginning of broad popularity.","zh":"這個片語描述廣泛流行的開始。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":18},{"front":"mortality rate goes down","meaning":"死亡率下降","examples":[{"en":"The mortality rate goes down when health improves.","zh":"當健康改善，死亡率下降。"},{"en":"If the mortality rate goes down, fewer people are dying in a population.","zh":"If the mortality rate goes down，意思是一個人口中死亡的人較少。"},{"en":"Better hospitals can help the mortality rate go down after serious illness.","zh":"更好的醫院可以幫助嚴重疾病後的死亡率下降。"},{"en":"If boiled water reduces infection, the mortality rate may go down.","zh":"如果煮沸的水減少感染，死亡率可能下降。"},{"en":"This phrase describes a decrease in deaths.","zh":"這個片語描述死亡減少。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":18},{"front":"decline in urban deaths","meaning":"城市死亡人數下降","examples":[{"en":"There was a decline in urban deaths caused by disease.","zh":"由疾病造成的城市死亡人數下降。"},{"en":"A decline in urban deaths means fewer people died in towns and cities.","zh":"Decline in urban deaths 指城鎮和城市中死亡人數減少。"},{"en":"Better waste removal can lead to a decline in urban deaths from disease.","zh":"更好的廢物處理可以導致由疾病造成的城市死亡人數下降。"},{"en":"If city deaths decline, crowded living may have become less dangerous.","zh":"如果城市死亡下降，擁擠居住可能變得較不危險。"},{"en":"This phrase connects public health improvement with city populations.","zh":"這個片語把公共健康改善與城市人口連接起來。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":18},{"front":"antibacterial qualities","meaning":"抗菌特質","examples":[{"en":"Tannin has antibacterial qualities.","zh":"單寧具有抗菌特質。"},{"en":"Antibacterial qualities are features that kill bacteria or slow their growth.","zh":"Antibacterial qualities 是能殺死細菌或減慢細菌生長的特性。"},{"en":"Soap has antibacterial qualities if it helps remove or reduce germs on hands.","zh":"如果肥皂幫助清除或減少手上細菌，它便有抗菌特質。"},{"en":"If tea contains antibacterial qualities, it may help protect people from some infections.","zh":"如果茶含有抗菌特質，它可能幫助保護人免受某些感染。"},{"en":"This phrase describes germ-fighting properties.","zh":"這個片語描述對抗細菌的特性。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":18},{"front":"go down by half","meaning":"下降一半","examples":[{"en":"The infant mortality rate went down by half.","zh":"嬰兒死亡率下降一半。"},{"en":"To go down by half means to decrease to 50 percent of the previous amount.","zh":"To go down by half 指下降至原本數量的50%。"},{"en":"A shop’s electricity bill may go down by half after it installs solar panels.","zh":"商店安裝太陽能板後，電費可能下降一半。"},{"en":"If child deaths go down by half, the improvement is large and important.","zh":"如果兒童死亡下降一半，這改善幅度大而重要。"},{"en":"This phrase describes a major reduction.","zh":"這個片語描述重大減少。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":19},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter from the choices given.","zh":"學生從所給選項中選出正確字母。"},{"en":"Choose the correct letter means select the answer option that best matches the question.","zh":"Choose the correct letter 指選出最符合題目的答案選項。"},{"en":"In a multiple-choice question, students may choose A, B, C, or D.","zh":"在多項選擇題中，學生可能選A、B、C或D。"},{"en":"If students choose the letter by matching only one word, they may miss the meaning.","zh":"如果學生只靠配對一個字來選字母，可能錯過意思。"},{"en":"This phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":19},{"front":"population explosion","meaning":"人口爆炸；人口急增","examples":[{"en":"There was a population explosion in Britain after 1740.","zh":"1740年後，英國出現人口爆炸。"},{"en":"A population explosion is a very rapid and large increase in population.","zh":"Population explosion 是人口非常迅速而大幅增加。"},{"en":"A city may experience a population explosion when many workers move there for jobs.","zh":"當許多工人為工作搬到城市，城市可能經歷人口急增。"},{"en":"If infant mortality falls sharply, a population explosion can follow.","zh":"如果嬰兒死亡率急劇下降，人口爆炸可能隨之而來。"},{"en":"This phrase describes sudden growth that can change society quickly.","zh":"這個片語描述能迅速改變社會的突然增長。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":19},{"front":"large numbers of people","meaning":"大量人士","examples":[{"en":"Large numbers of people moved to cities.","zh":"大量人士搬到城市。"},{"en":"Large numbers of people means many people, usually enough to have a noticeable effect.","zh":"Large numbers of people 指很多人，通常多到足以產生明顯影響。"},{"en":"Large numbers of people use public transport during the morning rush hour.","zh":"大量人士在早上繁忙時間使用公共交通。"},{"en":"If large numbers of people move to cities, housing and sanitation may come under pressure.","zh":"如果大量人士搬到城市，住屋和衛生設施可能承受壓力。"},{"en":"This phrase emphasises the scale of a group.","zh":"這個片語強調群體規模。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":19},{"front":"move to live in cities","meaning":"搬到城市居住","examples":[{"en":"Many people moved to live in cities.","zh":"許多人搬到城市居住。"},{"en":"To move to live in cities means to leave other areas, often rural places, and settle in urban areas.","zh":"To move to live in cities 指離開其他地區，通常是農村，並在城市地區定居。"},{"en":"A young worker may move to live in a city to find a factory job.","zh":"年輕工人可能搬到城市居住，以尋找工廠工作。"},{"en":"If many people move to cities, urban populations grow and towns become crowded.","zh":"如果許多人搬到城市，城市人口會增長，城鎮會變得擁擠。"},{"en":"This phrase describes migration toward urban life.","zh":"這個片語描述向城市生活遷移。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":19},{"front":"larger quantities of","meaning":"更多份量的……","examples":[{"en":"Larger quantities of beer may have been drunk.","zh":"人們可能飲用了更多份量的啤酒。"},{"en":"Larger quantities of something means greater amounts of it.","zh":"Larger quantities of something 指某物更大的數量。"},{"en":"A school may order larger quantities of paper before exam season.","zh":"學校可能在考試季前訂購更多份量的紙。"},{"en":"If larger quantities of a safer drink are consumed, exposure to unsafe water may fall.","zh":"如果人們飲用更多份量的較安全飲品，接觸不安全食水可能減少。"},{"en":"This phrase describes an increase in amount.","zh":"這個片語描述數量增加。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":19},{"front":"health-protecting qualities","meaning":"保護健康的特質","examples":[{"en":"Beer and tea may have had health-protecting qualities.","zh":"啤酒和茶可能具有保護健康的特質。"},{"en":"Health-protecting qualities are features that help keep people healthier or reduce illness.","zh":"Health-protecting qualities 是幫助人們保持較健康或減少疾病的特性。"},{"en":"Clean water has health-protecting qualities because it reduces infection risk.","zh":"清潔食水具有保護健康的特質，因為它減少感染風險。"},{"en":"If tea and beer protected people from germs, their health-protecting qualities mattered historically.","zh":"如果茶和啤酒保護人免受細菌影響，它們保護健康的特質在歷史上就很重要。"},{"en":"This phrase describes qualities that support health.","zh":"這個片語描述支持健康的特質。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":19},{"front":"according to the author","meaning":"根據作者所說","examples":[{"en":"According to the author, Japan avoided industrialisation for social reasons.","zh":"根據作者所說，日本因社會原因避免工業化。"},{"en":"According to the author means based on what the writer says or argues.","zh":"According to the author 指根據作者所說或所主張。"},{"en":"According to the author, the main problem is not technology but how people use it.","zh":"根據作者所說，主要問題不是科技，而是人們如何使用它。"},{"en":"In reading questions, students should answer according to the author, not their own opinion.","zh":"在閱讀題中，學生應根據作者所說作答，而不是根據自己意見。"},{"en":"This phrase points to the source of a claim.","zh":"這個片語指出主張的來源。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":19},{"front":"did not industrialise","meaning":"沒有工業化","examples":[{"en":"Japan did not industrialise in the same way as Britain.","zh":"日本沒有以與英國相同的方式工業化。"},{"en":"Did not industrialise means did not develop large-scale machine industry in that way or at that time.","zh":"Did not industrialise 指沒有以該方式或在該時期發展大規模機器工業。"},{"en":"Some regions did not industrialise quickly because they lacked coal, transport, or investment.","zh":"一些地區因缺乏煤、交通或投資而沒有快速工業化。"},{"en":"If a country chooses labour over machines, it may not industrialise like others.","zh":"如果一個國家選擇人力而不是機器，它可能不像其他國家那樣工業化。"},{"en":"This phrase describes the absence or delay of industrial development.","zh":"這個片語描述工業發展沒有出現或延遲。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":19},{"front":"unemployment","meaning":"失業","examples":[{"en":"Japan avoided devices that might cause unemployment.","zh":"日本避免使用可能造成失業的裝置。"},{"en":"Unemployment is the situation in which people who want work cannot find jobs.","zh":"Unemployment 是想工作的人找不到工作的情況。"},{"en":"A factory closure can create unemployment in a small town.","zh":"工廠關閉可以在小鎮造成失業。"},{"en":"If machines replace workers too quickly, unemployment may rise.","zh":"如果機器太快取代工人，失業可能上升。"},{"en":"This word describes a serious social and economic problem.","zh":"這個詞描述嚴重的社會和經濟問題。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":19},{"front":"discover why","meaning":"發現……的原因","examples":[{"en":"Macfarlane thinks he has discovered why industrialisation happened in Britain.","zh":"Macfarlane認為他已發現工業化為何在英國發生。"},{"en":"To discover why something happened means to find the reason behind it.","zh":"To discover why something happened 指找出某事背後的原因。"},{"en":"A teacher may discover why a class is quiet after speaking privately with students.","zh":"老師私下與學生交談後，可能發現班級安靜的原因。"},{"en":"If researchers discover why death rates fell, they can explain the wider historical change.","zh":"如果研究人員發現死亡率下降的原因，他們便能解釋更廣泛的歷史變化。"},{"en":"This phrase focuses on finding a cause.","zh":"這個片語著重找出原因。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":20},{"front":"when it did","meaning":"在當時發生","examples":[{"en":"He wanted to explain why industrialisation happened in Britain when it did.","zh":"他想解釋為何工業化在當時於英國發生。"},{"en":"When it did means at the particular time when it actually happened.","zh":"When it did 指某事實際發生的特定時間。"},{"en":"A historian may ask why a reform happened when it did, not fifty years earlier.","zh":"歷史學家可能問為何改革在當時發生，而不是早五十年發生。"},{"en":"If tea became common just before mortality fell, the timing may explain why change happened when it did.","zh":"如果茶正好在死亡率下降前變得普及，這個時機可能解釋變化為何在當時發生。"},{"en":"This phrase focuses on timing, not only cause.","zh":"這個片語著重時間，而不只是原因。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":20},{"front":"sanitation was not widespread","meaning":"衞生設施尚未普及","examples":[{"en":"Sanitation was not widespread until the 19th century.","zh":"衞生設施直到19世紀才普及。"},{"en":"Sanitation was not widespread means proper waste and clean-water systems were not common in many places.","zh":"Sanitation was not widespread 指適當的廢物處理和清潔食水系統在許多地方並不常見。"},{"en":"If sanitation is not widespread, people may still drink water polluted by human waste.","zh":"如果衛生設施尚未普及，人們可能仍會飲用被人類排泄物污染的水。"},{"en":"When sanitation was not widespread, boiled drinks may have helped reduce disease risk.","zh":"當衛生設施尚未普及，煮沸飲品可能幫助降低疾病風險。"},{"en":"This phrase explains why public health could be poor even in growing cities.","zh":"這個片語解釋為何即使城市正在成長，公共健康仍可能很差。"}],"source":"70 - Did tea and beer bring about industrialisation?.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 71":[{"front":"homeopathy","meaning":"順勢療法","examples":[{"en":"The passage discusses homeopathy as an alternative system of medicine.","zh":"文章討論順勢療法作為一種另類醫學體系。"},{"en":"Homeopathy is a treatment system based on the idea that a substance causing symptoms in healthy people may be used, in tiny doses, to treat similar symptoms.","zh":"順勢療法是一種治療體系，建基於一種想法：會令健康人士出現症狀的物質，可以用微小劑量治療相似症狀。"},{"en":"A patient interested in homeopathy may first have a long interview about physical and emotional symptoms.","zh":"對順勢療法感興趣的病人，可能先接受一次關於身體和情緒症狀的長時間面談。"},{"en":"Because homeopathy uses highly diluted remedies, it has created debate among doctors and researchers.","zh":"因為順勢療法使用高度稀釋的療劑，它在醫生和研究人員之間引起爭論。"},{"en":"The word refers to a medical approach, not to ordinary herbal tea or simple home care.","zh":"這個字指一種醫學取向，而不是普通草本茶或簡單家居護理。"}],"source":"71 - Homeopathy.pdf","sourcePage":1},{"front":"alternative system of medicine","meaning":"另類醫學體系","examples":[{"en":"Homeopathy is described as an alternative system of medicine.","zh":"順勢療法被描述為一種另類醫學體系。"},{"en":"An alternative system of medicine is a healing approach outside mainstream conventional medicine.","zh":"alternative system of medicine 是主流常規醫學以外的治療方法體系。"},{"en":"Some people visit an alternative system of medicine when ordinary treatment has not met their needs.","zh":"有些人在普通治療未能滿足需要時，會尋求另類醫學體系。"},{"en":"If a treatment belongs to an alternative system of medicine, patients should understand how it differs from hospital-based care.","zh":"如果一種治療屬於另類醫學體系，病人應理解它與醫院式護理有何不同。"},{"en":"The phrase describes a whole medical approach, not just one medicine.","zh":"這個短語描述整套醫學取向，而不只是某一種藥。"}],"source":"71 - Homeopathy.pdf","sourcePage":1},{"front":"founded in","meaning":"創立於","examples":[{"en":"Homeopathy was founded in the early 19th century.","zh":"順勢療法創立於19世紀初。"},{"en":"Founded in a period means first established or created during that time.","zh":"founded in 某時期，意思是在那段時間首次建立或創造。"},{"en":"A school founded in 1950 may have old traditions and a long local history.","zh":"創立於1950年的學校可能有舊傳統和悠久本地歷史。"},{"en":"If an organisation was founded in a difficult period, its early aims may reflect those problems.","zh":"如果組織創立於困難時期，其早期目標可能反映那些問題。"},{"en":"The phrase gives the starting time of an institution, idea, or movement.","zh":"這個短語說明機構、思想或運動的起始時間。"}],"source":"71 - Homeopathy.pdf","sourcePage":1},{"front":"the early 19th century","meaning":"19世紀初","examples":[{"en":"Homeopathy was founded in the early 19th century.","zh":"順勢療法創立於19世紀初。"},{"en":"The early 19th century means the first part of the 1800s.","zh":"the early 19th century 指1800年代初期。"},{"en":"In the early 19th century, many medical ideas were very different from modern medicine.","zh":"在19世紀初，許多醫學觀念與現代醫學非常不同。"},{"en":"If a theory began in the early 19th century, it developed before many modern laboratory methods.","zh":"如果一個理論開始於19世紀初，它是在許多現代實驗室方法出現前發展的。"},{"en":"The phrase places an event near the beginning of the nineteenth century.","zh":"這個短語把事件放在十九世紀開端附近。"}],"source":"71 - Homeopathy.pdf","sourcePage":1},{"front":"German physician","meaning":"德國醫生","examples":[{"en":"Dr Samuel Hahnemann was a German physician.","zh":"Samuel Hahnemann 醫生是一位德國醫生。"},{"en":"A German physician is a doctor from Germany or trained in the German medical tradition.","zh":"German physician 是來自德國或受德國醫學傳統訓練的醫生。"},{"en":"A German physician working in a hospital may treat patients, study symptoms, and prescribe medicine.","zh":"在醫院工作的德國醫生可能治療病人、研究症狀和處方藥物。"},{"en":"If a German physician developed a new theory, his medical background would shape how he explained disease.","zh":"如果一位德國醫生發展出新理論，他的醫學背景會塑造他如何解釋疾病。"},{"en":"The phrase identifies both nationality and profession.","zh":"這個短語同時指出國籍和職業。"}],"source":"71 - Homeopathy.pdf","sourcePage":1},{"front":"experienced a strong resurgence of interest","meaning":"重新受到強烈關注","examples":[{"en":"Homeopathy has experienced a strong resurgence of interest since 1980.","zh":"自1980年以來，順勢療法重新受到強烈關注。"},{"en":"To experience a strong resurgence of interest means to become popular or discussed again after a quieter period.","zh":"experience a strong resurgence of interest 指在較沉寂時期後重新變得受歡迎或被討論。"},{"en":"A traditional craft may experience a strong resurgence of interest when young people start learning it online.","zh":"當年輕人開始在網上學習傳統手藝，它可能重新受到強烈關注。"},{"en":"If people lose confidence in ordinary services, alternative choices may experience renewed interest.","zh":"如果人們對普通服務失去信心，另類選擇可能重新受到關注。"},{"en":"The phrase describes a noticeable return of attention.","zh":"這個短語描述注意力明顯回歸。"}],"source":"71 - Homeopathy.pdf","sourcePage":1},{"front":"resurgence of interest","meaning":"興趣復甦；重新興起","examples":[{"en":"The passage describes a resurgence of interest in homeopathy.","zh":"文章描述人們對順勢療法的興趣復甦。"},{"en":"A resurgence of interest is a renewed increase in attention, popularity, or curiosity.","zh":"resurgence of interest 是注意、受歡迎程度或好奇心重新增加。"},{"en":"There was a resurgence of interest in board games when families wanted screen-free activities.","zh":"當家庭想要無螢幕活動時，桌遊出現興趣復甦。"},{"en":"A resurgence of interest can lead to more books, courses, and public discussion about a topic.","zh":"興趣復甦可以帶來更多書籍、課程和公共討論。"},{"en":"The phrase suggests something old or quiet has become active again.","zh":"這個短語暗示某些舊有或沉寂的事物重新活躍。"}],"source":"71 - Homeopathy.pdf","sourcePage":1},{"front":"North and South America","meaning":"北美洲和南美洲","examples":[{"en":"Homeopathy became more popular in North and South America.","zh":"順勢療法在北美洲和南美洲變得更受歡迎。"},{"en":"North and South America refers to the two large continents in the western hemisphere.","zh":"North and South America 指西半球的兩大洲。"},{"en":"A health trend may spread through North and South America before reaching other regions.","zh":"一種健康潮流可能先在北美洲和南美洲傳播，然後才到達其他地區。"},{"en":"If an idea gains followers in North and South America, it has crossed many countries and cultures.","zh":"如果一個想法在北美洲和南美洲得到追隨者，它已跨越許多國家和文化。"},{"en":"The phrase names a broad geographical area, not one single country.","zh":"這個短語指出廣闊地理區域，而不是單一國家。"}],"source":"71 - Homeopathy.pdf","sourcePage":1},{"front":"as well as","meaning":"以及","examples":[{"en":"Homeopathy has attracted interest in America as well as in Europe.","zh":"順勢療法在美洲以及歐洲都引起興趣。"},{"en":"As well as means in addition to another person, place, or thing.","zh":"as well as 指除了另一個人、地方或事物之外也包括。"},{"en":"A student may study grammar as well as speaking to improve overall English.","zh":"學生可能學文法以及口語，以改善整體英語。"},{"en":"If a service is offered online as well as in person, more people can use it.","zh":"如果服務提供網上以及面授形式，更多人可以使用它。"},{"en":"The phrase adds another item without replacing the first one.","zh":"這個短語加入另一項，而不是取代第一項。"}],"source":"71 - Homeopathy.pdf","sourcePage":1},{"front":"surveys indicate that","meaning":"調查顯示","examples":[{"en":"Surveys indicate that many physicians have used homeopathic remedies.","zh":"調查顯示許多醫生曾使用順勢療法藥物。"},{"en":"Surveys indicate that means collected questionnaire or interview results suggest something.","zh":"surveys indicate that 指問卷或訪問收集到的結果顯示某事。"},{"en":"Surveys indicate that students sleep less before major examinations.","zh":"調查顯示學生在大型考試前睡得較少。"},{"en":"If surveys indicate a change in behaviour, researchers may investigate the reasons behind it.","zh":"如果調查顯示行為有所改變，研究人員可能調查背後原因。"},{"en":"The phrase introduces evidence from survey data.","zh":"這個短語引出來自調查數據的證據。"}],"source":"71 - Homeopathy.pdf","sourcePage":1},{"front":"more than a third of","meaning":"超過三分之一的……","examples":[{"en":"More than a third of French physicians have prescribed homeopathic remedies.","zh":"超過三分之一的法國醫生曾處方順勢療法藥物。"},{"en":"More than a third of a group means over one out of every three people in that group.","zh":"more than a third of 某群體，指該群體中每三人超過一人。"},{"en":"More than a third of the class chose online revision instead of paper worksheets.","zh":"超過三分之一的班級學生選擇網上溫習，而不是紙本工作紙。"},{"en":"If more than a third of customers complain, the company should treat the problem seriously.","zh":"如果超過三分之一的顧客投訴，公司應認真處理問題。"},{"en":"The phrase gives a proportion larger than 33 per cent.","zh":"這個短語表示大於百分之三十三的比例。"}],"source":"71 - Homeopathy.pdf","sourcePage":2},{"front":"French physicians","meaning":"法國醫生","examples":[{"en":"The surveys included French physicians.","zh":"這些調查包括法國醫生。"},{"en":"French physicians are doctors who practise medicine in France or are from France.","zh":"French physicians 是在法國行醫或來自法國的醫生。"},{"en":"French physicians may work in hospitals, clinics, research centres, or private practices.","zh":"法國醫生可能在醫院、診所、研究中心或私人診所工作。"},{"en":"If many French physicians use a treatment, researchers may study why it is accepted there.","zh":"如果許多法國醫生使用某種治療，研究人員可能研究它為何在當地被接受。"},{"en":"The phrase identifies a professional group by country.","zh":"這個短語按國家識別一個專業群體。"}],"source":"71 - Homeopathy.pdf","sourcePage":2},{"front":"prescribe homeopathic remedies","meaning":"處方順勢療法藥物","examples":[{"en":"Some physicians have prescribed homeopathic remedies.","zh":"一些醫生曾處方順勢療法藥物。"},{"en":"To prescribe homeopathic remedies means to tell a patient to use specific homeopathic preparations.","zh":"prescribe homeopathic remedies 指叫病人使用特定順勢療法製劑。"},{"en":"A doctor may prescribe medicine only after asking about symptoms and medical history.","zh":"醫生通常在詢問症狀和病歷後才處方藥物。"},{"en":"If a physician prescribes a remedy, the patient should understand how and when to take it.","zh":"如果醫生處方療劑，病人應理解如何和何時服用。"},{"en":"The phrase describes a medical professional giving a treatment instruction.","zh":"這個短語描述醫療專業人員給出治療指示。"}],"source":"71 - Homeopathy.pdf","sourcePage":2},{"front":"homeopathic remedies","meaning":"順勢療法藥物；順勢療劑","examples":[{"en":"The passage explains how homeopathic remedies are prepared.","zh":"文章解釋順勢療法藥物如何製備。"},{"en":"Homeopathic remedies are preparations used in homeopathy, often made through repeated dilution.","zh":"homeopathic remedies 是順勢療法中使用的製劑，通常透過反覆稀釋製成。"},{"en":"A patient may receive homeopathic remedies in drops, tablets, or small pellets.","zh":"病人可能以滴劑、藥片或小藥丸形式接受順勢療法藥物。"},{"en":"Because homeopathic remedies can be highly diluted, their claimed effects are debated.","zh":"因為順勢療法藥物可以被高度稀釋，其聲稱效果存在爭議。"},{"en":"The phrase refers to the substances used in homeopathic treatment.","zh":"這個短語指順勢療法治療所用的物質。"}],"source":"71 - Homeopathy.pdf","sourcePage":2},{"front":"almost 50 per cent of","meaning":"接近百分之五十的……","examples":[{"en":"Almost 50 per cent of British physicians have referred patients for treatment.","zh":"接近百分之五十的英國醫生曾轉介病人接受治療。"},{"en":"Almost 50 per cent of a group means nearly half of that group.","zh":"almost 50 per cent of 某群體，指該群體中接近一半。"},{"en":"Almost 50 per cent of the students said they preferred evening lessons.","zh":"接近百分之五十的學生表示較喜歡晚間課堂。"},{"en":"If almost 50 per cent of users choose one option, it is clearly important.","zh":"如果接近百分之五十的使用者選擇某選項，它明顯重要。"},{"en":"The phrase gives an approximate proportion close to one half.","zh":"這個短語給出接近一半的大概比例。"}],"source":"71 - Homeopathy.pdf","sourcePage":2},{"front":"British physicians","meaning":"英國醫生","examples":[{"en":"Almost 50 per cent of British physicians have referred patients for homeopathic treatment.","zh":"接近百分之五十的英國醫生曾轉介病人接受順勢療法治療。"},{"en":"British physicians are doctors who practise medicine in Britain or are from Britain.","zh":"British physicians 是在英國行醫或來自英國的醫生。"},{"en":"British physicians may work in public hospitals, private clinics, or research institutions.","zh":"英國醫生可能在公營醫院、私人診所或研究機構工作。"},{"en":"If British physicians refer patients to another treatment, they are directing patients to another service.","zh":"如果英國醫生把病人轉介到另一種治療，他們是在引導病人使用另一服務。"},{"en":"The phrase identifies a group of doctors by country.","zh":"這個短語按國家識別一群醫生。"}],"source":"71 - Homeopathy.pdf","sourcePage":2},{"front":"refer patients for","meaning":"轉介病人接受……","examples":[{"en":"Some physicians have referred patients for homeopathic treatment.","zh":"一些醫生曾轉介病人接受順勢療法治療。"},{"en":"To refer patients for a treatment means to send or direct them to another professional or service.","zh":"refer patients for 某治療，指把病人送往或引導到另一專業人士或服務。"},{"en":"A family doctor may refer patients for blood tests when symptoms need checking.","zh":"當症狀需要檢查時，家庭醫生可能轉介病人接受驗血。"},{"en":"If a doctor cannot provide a service directly, she may refer patients for specialist care.","zh":"如果醫生不能直接提供某服務，她可能轉介病人接受專科護理。"},{"en":"The phrase describes transferring a patient to another form of help.","zh":"這個短語描述把病人轉往另一種協助。"}],"source":"71 - Homeopathy.pdf","sourcePage":2},{"front":"homeopathic treatment","meaning":"順勢療法治療","examples":[{"en":"Some patients were referred for homeopathic treatment.","zh":"一些病人被轉介接受順勢療法治療。"},{"en":"Homeopathic treatment is treatment using the principles and remedies of homeopathy.","zh":"homeopathic treatment 是使用順勢療法原理和療劑的治療。"},{"en":"A homeopathic treatment session may include a long interview before any remedy is chosen.","zh":"順勢療法治療過程可能包括長時間面談，然後才選擇療劑。"},{"en":"Because homeopathic treatment differs from conventional medicine, patients may ask many questions before trying it.","zh":"因為順勢療法治療與常規醫學不同，病人在嘗試前可能會問很多問題。"},{"en":"The phrase describes the treatment process, not only the remedy itself.","zh":"這個短語描述治療過程，而不只是療劑本身。"}],"source":"71 - Homeopathy.pdf","sourcePage":2},{"front":"discovery of the principle","meaning":"原理的發現","examples":[{"en":"Hahnemann’s discovery of the principle of homeopathy was accidental.","zh":"Hahnemann 對順勢療法原理的發現是偶然的。"},{"en":"Discovery of the principle means finding the basic idea behind a system.","zh":"discovery of the principle 指找到一個系統背後的基本想法。"},{"en":"A student’s discovery of the principle behind a grammar rule makes later examples easier.","zh":"學生發現文法規則背後的原理後，之後的例子會更容易。"},{"en":"If the discovery of a principle is accidental, it begins with observation rather than planning.","zh":"如果原理的發現是偶然的，它始於觀察而非計劃。"},{"en":"The phrase focuses on finding the central rule or idea.","zh":"這個短語重點在找到核心規則或想法。"}],"source":"71 - Homeopathy.pdf","sourcePage":2},{"front":"the principle of homeopathy","meaning":"順勢療法原理","examples":[{"en":"The principle of homeopathy was discovered accidentally.","zh":"順勢療法原理是偶然被發現的。"},{"en":"The principle of homeopathy is the idea that “like may be treated by like.”","zh":"the principle of homeopathy 是「以相似者治療相似者」的想法。"},{"en":"In class, students may remember the principle of homeopathy through the phrase “similar treats similar.”","zh":"在課堂中，學生可能透過「相似治相似」這句話記住順勢療法原理。"},{"en":"Because the principle of homeopathy is unusual, it often needs careful explanation.","zh":"因為順勢療法原理不尋常，它常需要仔細解釋。"},{"en":"The phrase refers to the main idea behind the system.","zh":"這個短語指該體系背後的主要想法。"}],"source":"71 - Homeopathy.pdf","sourcePage":2},{"front":"accidental","meaning":"偶然的","examples":[{"en":"Hahnemann’s discovery was accidental.","zh":"Hahnemann 的發現是偶然的。"},{"en":"Accidental means happening by chance, not because it was planned.","zh":"accidental 指偶然發生，不是因計劃而發生。"},{"en":"A student may make an accidental discovery when a wrong calculation reveals a pattern.","zh":"學生可能在錯誤計算中發現一個模式，作出偶然發現。"},{"en":"If a discovery is accidental, careful observation can still turn it into a theory.","zh":"如果發現是偶然的，仔細觀察仍可把它變成理論。"},{"en":"The word describes something unplanned but sometimes important.","zh":"這個字描述無計劃但有時重要的事情。"}],"source":"71 - Homeopathy.pdf","sourcePage":3},{"front":"after taking","meaning":"服用……之後","examples":[{"en":"After taking quinine, Hahnemann noticed unusual symptoms.","zh":"服用奎寧之後，Hahnemann 注意到不尋常症狀。"},{"en":"After taking something means after swallowing, using, or receiving it.","zh":"after taking 某物，指吞服、使用或接受它之後。"},{"en":"After taking a new medicine, a patient should watch for unexpected reactions.","zh":"服用新藥之後，病人應留意意外反應。"},{"en":"If symptoms appear after taking a substance, doctors may ask whether the substance caused them.","zh":"如果症狀在服用某物後出現，醫生可能會問是否由該物質引起。"},{"en":"The phrase connects an action with what happens afterwards.","zh":"這個短語把一個行動與之後發生的事連繫起來。"}],"source":"71 - Homeopathy.pdf","sourcePage":3},{"front":"quinine","meaning":"奎寧","examples":[{"en":"Hahnemann took quinine and developed malaria-like symptoms.","zh":"Hahnemann 服用奎寧後出現類似瘧疾的症狀。"},{"en":"Quinine is a substance historically used to treat malaria.","zh":"quinine 是歷史上用於治療瘧疾的一種物質。"},{"en":"A history of medicine lesson may mention quinine when discussing early malaria treatment.","zh":"醫學史課討論早期瘧疾治療時，可能提到奎寧。"},{"en":"If quinine causes symptoms in a healthy person, that observation can lead to questions about its effects.","zh":"如果奎寧在健康人士身上造成症狀，這種觀察可引出關於其作用的問題。"},{"en":"The word names the substance that triggered Hahnemann’s original observation.","zh":"這個字指出引發 Hahnemann 最初觀察的物質。"}],"source":"71 - Homeopathy.pdf","sourcePage":3},{"front":"malaria-like symptoms","meaning":"類似瘧疾的症狀","examples":[{"en":"He noticed that he developed malaria-like symptoms.","zh":"他注意到自己出現類似瘧疾的症狀。"},{"en":"Malaria-like symptoms are symptoms that resemble those of malaria.","zh":"malaria-like symptoms 是與瘧疾相似的症狀。"},{"en":"A patient with fever, chills, and sweating may show malaria-like symptoms.","zh":"有發燒、發冷和出汗的病人可能出現類似瘧疾的症狀。"},{"en":"If a healthy person develops malaria-like symptoms after taking a substance, researchers may investigate the connection.","zh":"如果健康人士服用某物後出現類似瘧疾的症狀，研究人員可能調查兩者關係。"},{"en":"The phrase means similar to malaria, not necessarily actual malaria.","zh":"這個短語表示與瘧疾相似，不一定是真正瘧疾。"}],"source":"71 - Homeopathy.pdf","sourcePage":3},{"front":"malaria patients","meaning":"瘧疾病人","examples":[{"en":"Malaria patients were treated with quinine.","zh":"瘧疾病人以奎寧治療。"},{"en":"Malaria patients are people suffering from malaria.","zh":"malaria patients 是患有瘧疾的人。"},{"en":"Malaria patients may have fever, chills, sweating, and severe tiredness.","zh":"瘧疾病人可能有發燒、發冷、出汗和嚴重疲倦。"},{"en":"If malaria patients do not receive effective care, the illness can become dangerous.","zh":"如果瘧疾病人沒有得到有效護理，疾病可能變得危險。"},{"en":"The phrase identifies people with a specific disease.","zh":"這個短語指出患有特定疾病的人。"}],"source":"71 - Homeopathy.pdf","sourcePage":3},{"front":"be treated with","meaning":"以……治療","examples":[{"en":"Malaria patients were treated with quinine.","zh":"瘧疾病人以奎寧治療。"},{"en":"To be treated with something means to receive that substance or method as treatment.","zh":"be treated with 某物，指接受該物質或方法作為治療。"},{"en":"A throat infection may be treated with medicine if a doctor thinks it is necessary.","zh":"如果醫生認為有需要，喉嚨感染可能以藥物治療。"},{"en":"If a condition is treated with the wrong method, symptoms may not improve.","zh":"如果病症以錯誤方法治療，症狀可能不會改善。"},{"en":"The phrase links an illness or patient with a treatment.","zh":"這個短語把疾病或病人與治療連繫起來。"}],"source":"71 - Homeopathy.pdf","sourcePage":3},{"front":"speculate that","meaning":"推測","examples":[{"en":"Hahnemann speculated that malaria might be cured by quinine.","zh":"Hahnemann 推測瘧疾可能由奎寧治癒。"},{"en":"To speculate that something is true means to suggest it as a possibility without full proof.","zh":"speculate that 某事為真，指在沒有完整證明下提出它是可能性。"},{"en":"A teacher may speculate that tiredness is causing weaker homework, but she needs evidence.","zh":"老師可能推測疲倦導致功課較差，但她需要證據。"},{"en":"If scientists speculate about a cause, they may later design tests to check it.","zh":"如果科學家推測某個原因，他們之後可能設計測試去驗證。"},{"en":"The phrase introduces a possible explanation, not a confirmed fact.","zh":"這個短語引出可能解釋，而不是已確認事實。"}],"source":"71 - Homeopathy.pdf","sourcePage":3},{"front":"be cured by","meaning":"由……治癒","examples":[{"en":"He speculated that malaria might be cured by quinine.","zh":"他推測瘧疾可能由奎寧治癒。"},{"en":"To be cured by something means to be healed because of that treatment.","zh":"be cured by 某物，指因該治療而康復。"},{"en":"A minor infection may be cured by the right medicine, but only a doctor can advise properly.","zh":"輕微感染可能由合適藥物治癒，但只有醫生能作適當建議。"},{"en":"If a disease is cured by a treatment, the illness disappears rather than only being controlled.","zh":"如果疾病由某治療治癒，病症會消失，而不只是被控制。"},{"en":"The phrase focuses on complete recovery caused by a treatment.","zh":"這個短語重點在由治療造成的完全康復。"}],"source":"71 - Homeopathy.pdf","sourcePage":3},{"front":"healthy people","meaning":"健康人士","examples":[{"en":"Quinine caused malaria-like symptoms in healthy people.","zh":"奎寧在健康人士身上造成類似瘧疾的症狀。"},{"en":"Healthy people are people who do not currently have the illness being discussed.","zh":"healthy people 是目前沒有正在討論疾病的人。"},{"en":"Researchers may compare sick patients with healthy people to understand symptoms.","zh":"研究人員可能比較病人和健康人士，以理解症狀。"},{"en":"If a substance causes symptoms in healthy people, it may have strong effects on the body.","zh":"如果某物質在健康人士身上造成症狀，它可能對身體有強烈作用。"},{"en":"The phrase contrasts people without the disease with patients who have it.","zh":"這個短語把沒有疾病的人與患者作對比。"}],"source":"71 - Homeopathy.pdf","sourcePage":3},{"front":"explore his theory","meaning":"探究他的理論","examples":[{"en":"He decided to explore his theory by testing other substances.","zh":"他決定透過測試其他物質來探究他的理論。"},{"en":"To explore his theory means to investigate whether his idea might be true.","zh":"explore his theory 指調查他的想法是否可能正確。"},{"en":"A student may explore her theory about memory by testing different revision methods.","zh":"學生可能透過測試不同溫習方法，探究自己關於記憶的理論。"},{"en":"If someone wants to explore a theory, observation alone is not enough; tests are needed.","zh":"如果某人想探究理論，單靠觀察並不足夠；需要測試。"},{"en":"The phrase describes turning an idea into investigation.","zh":"這個短語描述把想法轉化為調查。"}],"source":"71 - Homeopathy.pdf","sourcePage":3},{"front":"testing other substances","meaning":"測試其他物質","examples":[{"en":"Hahnemann explored his theory by testing other substances.","zh":"Hahnemann 透過測試其他物質來探究他的理論。"},{"en":"Testing other substances means trying additional materials to observe their effects.","zh":"testing other substances 指嘗試更多材料以觀察其作用。"},{"en":"A science class may test other substances to see which one dissolves fastest.","zh":"科學課可能測試其他物質，看哪一種溶解最快。"},{"en":"If one substance produces a surprising result, testing others can show whether the pattern is general.","zh":"如果一種物質產生意外結果，測試其他物質可顯示該模式是否普遍。"},{"en":"The phrase describes systematic checking beyond the first example.","zh":"這個短語描述超出第一個例子的系統檢查。"}],"source":"71 - Homeopathy.pdf","sourcePage":4},{"front":"substances used as medicine","meaning":"當時用作藥物的物質","examples":[{"en":"He tested substances used as medicine at the time.","zh":"他測試當時用作藥物的物質。"},{"en":"Substances used as medicine are materials taken or applied to treat illness.","zh":"substances used as medicine 是被服用或使用來治療疾病的材料。"},{"en":"Some plants were substances used as medicine before modern tablets were developed.","zh":"在現代藥片發展前，一些植物曾是用作藥物的物質。"},{"en":"If substances used as medicine are strong, they can also cause unwanted symptoms.","zh":"如果用作藥物的物質作用很強，它們也可能造成不想要的症狀。"},{"en":"The phrase refers to medicinal materials, not ordinary household objects.","zh":"這個短語指藥用材料，而不是普通家居物件。"}],"source":"71 - Homeopathy.pdf","sourcePage":4},{"front":"at the time","meaning":"當時","examples":[{"en":"He tested substances used as medicine at the time.","zh":"他測試當時用作藥物的物質。"},{"en":"At the time means during the period being discussed.","zh":"at the time 指在所討論的那段時期。"},{"en":"At the time, many students wrote essays by hand because laptops were uncommon.","zh":"當時許多學生手寫文章，因為手提電腦並不普遍。"},{"en":"If a method was accepted at the time, people in that period may not have questioned it.","zh":"如果一種方法在當時被接受，那個時期的人可能沒有質疑它。"},{"en":"The phrase places an action in its historical context.","zh":"這個短語把行動放在其歷史背景中。"}],"source":"71 - Homeopathy.pdf","sourcePage":4},{"front":"such as","meaning":"例如","examples":[{"en":"He tested substances such as arsenic and belladonna.","zh":"他測試例如砒霜和顛茄等物質。"},{"en":"Such as introduces examples of the thing just mentioned.","zh":"such as 用來引出剛提及事物的例子。"},{"en":"Students need stationery such as pens, notebooks and folders.","zh":"學生需要文具，例如筆、筆記簿和文件夾。"},{"en":"If a list begins with “such as,” it usually gives examples rather than every possible item.","zh":"如果清單以 such as 開始，它通常給出例子，而不是所有可能項目。"},{"en":"The phrase helps make a general idea more concrete.","zh":"這個短語幫助令一般想法更具體。"}],"source":"71 - Homeopathy.pdf","sourcePage":4},{"front":"arsenic and belladonna","meaning":"砒霜和顛茄","examples":[{"en":"Arsenic and belladonna were among the substances he tested.","zh":"砒霜和顛茄是他測試的物質之一。"},{"en":"Arsenic and belladonna are toxic substances historically known for strong effects on the body.","zh":"arsenic and belladonna 是歷史上因對身體有強烈作用而聞名的有毒物質。"},{"en":"A chemistry teacher may mention arsenic and belladonna as examples of dangerous natural or chemical substances.","zh":"化學老師可能提到砒霜和顛茄，作為危險天然或化學物質的例子。"},{"en":"If such substances are tested, strict caution is necessary because they can be poisonous.","zh":"如果測試這類物質，必須非常小心，因為它們可能有毒。"},{"en":"The phrase names two risky substances used in the passage’s historical discussion.","zh":"這個短語指出文章歷史討論中的兩種高風險物質。"}],"source":"71 - Homeopathy.pdf","sourcePage":4},{"front":"conduct tests","meaning":"進行測試","examples":[{"en":"Hahnemann conducted tests on different substances.","zh":"Hahnemann 對不同物質進行測試。"},{"en":"To conduct tests means to carry out planned checks or experiments.","zh":"conduct tests 指進行有計劃的檢查或實驗。"},{"en":"A school nurse may conduct tests to check students’ eyesight.","zh":"學校護士可能進行測試，以檢查學生視力。"},{"en":"If researchers conduct tests carefully, their results are more useful.","zh":"如果研究人員仔細進行測試，其結果會更有用。"},{"en":"The phrase describes organised investigation, not casual guessing.","zh":"這個短語描述有組織的調查，而不是隨便猜測。"}],"source":"71 - Homeopathy.pdf","sourcePage":4},{"front":"either by…or by…","meaning":"要麼透過……要麼透過……","examples":[{"en":"He conducted tests either by taking substances himself or by giving them to volunteers.","zh":"他進行測試，要麼透過自己服用物質，要麼透過把它們給志願者服用。"},{"en":"Either by…or by… shows two possible methods for doing something.","zh":"either by…or by… 顯示做某事的兩種可能方法。"},{"en":"Students can practise vocabulary either by writing sentences or by speaking with a partner.","zh":"學生可以練習詞彙，要麼透過寫句子，要麼透過與伙伴說話。"},{"en":"If a problem can be solved either by saving money or by increasing income, both routes are possible.","zh":"如果問題可以透過儲錢或增加收入解決，兩條路線都可能。"},{"en":"The phrase clearly presents two alternatives.","zh":"這個短語清楚呈現兩個選擇。"}],"source":"71 - Homeopathy.pdf","sourcePage":4},{"front":"administer something to","meaning":"給予某人……","examples":[{"en":"He administered the substances to healthy volunteers.","zh":"他把這些物質給予健康志願者。"},{"en":"To administer something to someone means to give a medicine, test, or treatment to them.","zh":"administer something to someone 指給某人藥物、測試或治療。"},{"en":"A nurse may administer a vaccine to students during a school health programme.","zh":"護士可能在學校健康計劃中為學生接種疫苗。"},{"en":"If a substance is administered to volunteers, researchers must monitor their reactions carefully.","zh":"如果某物質被給予志願者，研究人員必須仔細監察他們的反應。"},{"en":"The phrase is formal and often used in medical or research contexts.","zh":"這個短語較正式，常用於醫學或研究語境。"}],"source":"71 - Homeopathy.pdf","sourcePage":4},{"front":"healthy volunteers","meaning":"健康志願者","examples":[{"en":"The substances were administered to healthy volunteers.","zh":"這些物質被給予健康志願者。"},{"en":"Healthy volunteers are people without the illness who agree to take part in a study.","zh":"healthy volunteers 是沒有該疾病並同意參與研究的人。"},{"en":"Healthy volunteers may join a study so researchers can compare normal reactions with patient reactions.","zh":"健康志願者可能參加研究，讓研究人員比較正常反應和病人反應。"},{"en":"If healthy volunteers experience symptoms, researchers record those changes carefully.","zh":"如果健康志願者出現症狀，研究人員會仔細記錄那些變化。"},{"en":"The phrase identifies participants who are not patients in the study.","zh":"這個短語指出研究中不是病人的參與者。"}],"source":"71 - Homeopathy.pdf","sourcePage":4},{"front":"record symptoms","meaning":"記錄症狀","examples":[{"en":"He recorded all of the symptoms the volunteers experienced.","zh":"他記錄志願者所經歷的所有症狀。"},{"en":"To record symptoms means to write down or document physical or mental changes.","zh":"record symptoms 指寫下或記錄身體或心理變化。"},{"en":"A patient may record symptoms in a diary before visiting a doctor.","zh":"病人看醫生前可能在日記中記錄症狀。"},{"en":"If researchers record symptoms carefully, they can compare patterns later.","zh":"如果研究人員仔細記錄症狀，他們之後可以比較模式。"},{"en":"The phrase describes collecting evidence about how a body reacts.","zh":"這個短語描述收集身體反應的證據。"}],"source":"71 - Homeopathy.pdf","sourcePage":4},{"front":"experience symptoms","meaning":"出現症狀","examples":[{"en":"The volunteers experienced symptoms after taking the substances.","zh":"志願者服用這些物質後出現症狀。"},{"en":"To experience symptoms means to feel signs of illness or physical change.","zh":"experience symptoms 指感到疾病跡象或身體變化。"},{"en":"A student who experiences symptoms such as fever and coughing should rest and seek advice.","zh":"如果學生出現發燒和咳嗽等症狀，應休息並尋求建議。"},{"en":"If people experience symptoms after taking something, the timing may help identify the cause.","zh":"如果人們服用某物後出現症狀，出現時間可能有助找出原因。"},{"en":"The phrase describes what a person feels or notices in the body.","zh":"這個短語描述人在身體上感到或注意到的情況。"}],"source":"71 - Homeopathy.pdf","sourcePage":5},{"front":"continue experiments on","meaning":"繼續對……進行實驗","examples":[{"en":"He continued his experiments on a wide range of natural substances.","zh":"他繼續對廣泛的天然物質進行實驗。"},{"en":"To continue experiments on something means to keep testing or studying it.","zh":"continue experiments on 某物，指繼續測試或研究它。"},{"en":"Scientists may continue experiments on a vaccine after early results look promising.","zh":"如果早期結果看來有希望，科學家可能繼續對疫苗進行實驗。"},{"en":"If researchers continue experiments, they can gather more evidence before making conclusions.","zh":"如果研究人員繼續實驗，他們可以在下結論前收集更多證據。"},{"en":"The phrase shows that investigation does not stop after one test.","zh":"這個短語顯示調查不會在一次測試後停止。"}],"source":"71 - Homeopathy.pdf","sourcePage":5},{"front":"a wide range of","meaning":"廣泛的……","examples":[{"en":"He tested a wide range of natural substances.","zh":"他測試了廣泛的天然物質。"},{"en":"A wide range of something means many different types of it.","zh":"a wide range of 某物，指許多不同種類的該事物。"},{"en":"A library offers a wide range of books for children, teenagers, and adults.","zh":"圖書館提供廣泛書籍，給兒童、青少年和成人閱讀。"},{"en":"If a study tests a wide range of materials, its results cover more possibilities.","zh":"如果研究測試廣泛材料，其結果涵蓋更多可能性。"},{"en":"The phrase stresses variety and breadth.","zh":"這個短語強調種類多和範圍闊。"}],"source":"71 - Homeopathy.pdf","sourcePage":5},{"front":"natural substances","meaning":"天然物質","examples":[{"en":"Many of the tested substances were natural substances.","zh":"許多經測試的物質都是天然物質。"},{"en":"Natural substances are materials that come from nature, such as plants, minerals, or animals.","zh":"natural substances 是來自自然的材料，例如植物、礦物或動物。"},{"en":"Honey, salt, and plant oils are natural substances used in daily life.","zh":"蜂蜜、鹽和植物油都是日常生活中使用的天然物質。"},{"en":"Natural substances can still be powerful or dangerous, so “natural” does not always mean safe.","zh":"天然物質仍可能很強烈或危險，所以「天然」不一定代表安全。"},{"en":"The phrase describes the source of a material, not its risk level.","zh":"這個短語描述材料來源，而不是其風險程度。"}],"source":"71 - Homeopathy.pdf","sourcePage":5},{"front":"often toxic","meaning":"通常有毒","examples":[{"en":"The natural substances were often toxic.","zh":"這些天然物質通常有毒。"},{"en":"Often toxic means frequently poisonous or harmful to the body.","zh":"often toxic 指經常有毒或對身體有害。"},{"en":"Some wild berries are often toxic, so children should not eat unknown plants.","zh":"一些野生莓果通常有毒，所以孩子不應吃不認識的植物。"},{"en":"If a substance is toxic, even a small amount may cause harm.","zh":"如果物質有毒，即使少量也可能造成傷害。"},{"en":"The phrase warns that something can be dangerous despite being natural.","zh":"這個短語提醒人們，即使某物天然，也可能危險。"}],"source":"71 - Homeopathy.pdf","sourcePage":5},{"front":"recorded results","meaning":"記錄下來的結果","examples":[{"en":"The recorded results created drug pictures.","zh":"記錄下來的結果形成了藥物圖像。"},{"en":"Recorded results are findings that have been written down or documented.","zh":"recorded results 是已寫下或記錄的發現。"},{"en":"A teacher uses recorded results from past tests to see whether students are improving.","zh":"老師使用過去測驗中記錄下來的結果，看看學生是否有進步。"},{"en":"If recorded results are detailed, they can be compared with later observations.","zh":"如果記錄下來的結果詳細，就可以與之後觀察比較。"},{"en":"The phrase refers to evidence kept for future use.","zh":"這個短語指為日後使用而保存的證據。"}],"source":"71 - Homeopathy.pdf","sourcePage":5},{"front":"drug pictures","meaning":"藥物圖像；藥物症狀圖","examples":[{"en":"The recorded results created what Hahnemann called drug pictures.","zh":"記錄下來的結果形成了 Hahnemann 所稱的藥物圖像。"},{"en":"Drug pictures are descriptions of the symptoms a substance is said to produce.","zh":"drug pictures 是描述某物質據稱會產生哪些症狀的資料。"},{"en":"In the passage, a drug picture works like a profile of a substance’s effects.","zh":"在文章中，藥物圖像像是某物質作用的檔案。"},{"en":"If a patient’s symptoms match a drug picture, the homeopath may choose that remedy.","zh":"如果病人的症狀與某藥物圖像相符，順勢療法師可能選擇該療劑。"},{"en":"The phrase refers to symptom patterns, not actual drawings of medicines.","zh":"這個短語指症狀模式，而不是藥物的實際圖畫。"}],"source":"71 - Homeopathy.pdf","sourcePage":5},{"front":"form the basis for","meaning":"構成……的基礎","examples":[{"en":"The drug pictures formed the basis for the new system of medicine.","zh":"藥物圖像構成這套新醫學體系的基礎。"},{"en":"To form the basis for something means to provide the main foundation for it.","zh":"form the basis for 某事，指為它提供主要基礎。"},{"en":"A clear syllabus can form the basis for a year of English lessons.","zh":"清晰課程大綱可以構成一年英語課的基礎。"},{"en":"If early observations form the basis for a theory, later work builds on them.","zh":"如果早期觀察構成理論基礎，之後工作就建立在它們之上。"},{"en":"The phrase shows what a system or idea is built upon.","zh":"這個短語顯示系統或想法建基於甚麼。"}],"source":"71 - Homeopathy.pdf","sourcePage":5},{"front":"a new system of medicine","meaning":"一套新的醫學體系","examples":[{"en":"The drug pictures formed the basis for a new system of medicine.","zh":"藥物圖像構成一套新的醫學體系的基礎。"},{"en":"A new system of medicine is a newly organised approach to understanding and treating illness.","zh":"a new system of medicine 是一套新組織起來、用於理解和治療疾病的方法。"},{"en":"A new system of medicine may have its own theories, tests, treatments, and terminology.","zh":"一套新的醫學體系可能有自己的理論、測試、治療和術語。"},{"en":"If a new system of medicine becomes popular, doctors and patients may debate its value.","zh":"如果新的醫學體系變得流行，醫生和病人可能辯論其價值。"},{"en":"The phrase describes a whole medical framework, not just one discovery.","zh":"這個短語描述整個醫學框架，而不只是單一發現。"}],"source":"71 - Homeopathy.pdf","sourcePage":5},{"front":"the next step was to","meaning":"下一步是……","examples":[{"en":"The next step was to give the tested substances to patients.","zh":"下一步是把經測試的物質給病人使用。"},{"en":"The next step was to means the following action in a process was to do something.","zh":"the next step was to 指過程中的下一個行動是做某事。"},{"en":"After collecting survey answers, the next step was to compare the results.","zh":"收集問卷答案後，下一步是比較結果。"},{"en":"If a first test succeeds, the next step may be to try it with more people.","zh":"如果第一次測試成功，下一步可能是在更多人身上嘗試。"},{"en":"The phrase clearly marks movement from one stage to another.","zh":"這個短語清楚標示從一個階段移到另一階段。"}],"source":"71 - Homeopathy.pdf","sourcePage":5},{"front":"tested substances","meaning":"經測試的物質","examples":[{"en":"The tested substances were then given to patients.","zh":"經測試的物質之後被給予病人。"},{"en":"Tested substances are materials that have already been tried or examined.","zh":"tested substances 是已經被試用或檢查過的材料。"},{"en":"In science class, tested substances may be labelled so students know which reactions were observed.","zh":"在科學課中，經測試的物質可能被貼上標籤，讓學生知道觀察到哪些反應。"},{"en":"If tested substances show strong effects, researchers must handle them carefully.","zh":"如果經測試的物質顯示強烈作用，研究人員必須小心處理。"},{"en":"The phrase refers to materials after an experiment, not before it.","zh":"這個短語指實驗後的材料，而不是實驗前的材料。"}],"source":"71 - Homeopathy.pdf","sourcePage":6},{"front":"patients suffering from","meaning":"患有……的病人","examples":[{"en":"The substances were given to patients suffering from similar symptoms.","zh":"這些物質被給予患有相似症狀的病人。"},{"en":"Patients suffering from a condition are people who have that illness or symptom.","zh":"patients suffering from 某病症，是患有該疾病或症狀的人。"},{"en":"Patients suffering from severe headaches may need careful assessment before treatment.","zh":"患有嚴重頭痛的病人在治療前可能需要仔細評估。"},{"en":"If patients are suffering from similar symptoms, a practitioner may compare their cases.","zh":"如果病人患有相似症狀，醫療人員可能比較他們的個案。"},{"en":"The phrase identifies the problem affecting the patients.","zh":"這個短語指出影響病人的問題。"}],"source":"71 - Homeopathy.pdf","sourcePage":6},{"front":"the same group of symptoms","meaning":"同一組症狀","examples":[{"en":"The patients had the same group of symptoms represented by the drug picture.","zh":"病人有藥物圖像所代表的同一組症狀。"},{"en":"The same group of symptoms means an identical or very similar set of signs of illness.","zh":"the same group of symptoms 指相同或非常相似的一組疾病跡象。"},{"en":"If several students have the same group of symptoms, the school nurse may suspect an infection.","zh":"如果幾名學生有同一組症狀，學校護士可能懷疑感染。"},{"en":"Matching the same group of symptoms helps a practitioner choose between possible explanations.","zh":"配對同一組症狀有助醫療人員在可能解釋中作選擇。"},{"en":"The phrase focuses on a pattern of symptoms, not one symptom alone.","zh":"這個短語重點在症狀模式，而不只是單一症狀。"}],"source":"71 - Homeopathy.pdf","sourcePage":6},{"front":"be represented by","meaning":"由……代表","examples":[{"en":"The symptoms were represented by the drug picture.","zh":"這些症狀由藥物圖像代表。"},{"en":"To be represented by something means to be shown, described, or symbolised by it.","zh":"be represented by 某物，指由它顯示、描述或象徵。"},{"en":"A student’s progress may be represented by test scores and teacher comments.","zh":"學生進步可以由測驗分數和老師評語代表。"},{"en":"If a set of symptoms is represented by a chart, doctors can compare cases more easily.","zh":"如果一組症狀由圖表代表，醫生可以更容易比較個案。"},{"en":"The phrase links an idea or pattern with the thing that shows it.","zh":"這個短語把想法或模式與顯示它的事物連繫起來。"}],"source":"71 - Homeopathy.pdf","sourcePage":6},{"front":"incredible results","meaning":"令人難以置信的結果","examples":[{"en":"The passage describes the results as incredible.","zh":"文章把結果描述為令人難以置信。"},{"en":"Incredible results are results that seem extraordinary, surprising, or hard to believe.","zh":"incredible results 是非凡、令人驚訝或難以相信的結果。"},{"en":"A student may get incredible results after months of careful practice and feedback.","zh":"學生經過數月仔細練習和回饋後，可能取得令人難以置信的結果。"},{"en":"If results sound incredible, readers may look for strong evidence before accepting them.","zh":"如果結果聽起來令人難以置信，讀者可能會尋找強力證據才接受。"},{"en":"The phrase expresses amazement, but it can also invite questioning.","zh":"這個短語表達驚訝，但也可能引發質疑。"}],"source":"71 - Homeopathy.pdf","sourcePage":6},{"front":"be cured of diseases","meaning":"疾病被治癒","examples":[{"en":"The passage claims that people were being cured of diseases.","zh":"文章聲稱人們的疾病被治癒。"},{"en":"To be cured of diseases means to recover from illnesses completely.","zh":"be cured of diseases 指從疾病中完全康復。"},{"en":"A patient cured of an infection no longer has the active illness.","zh":"被治癒感染的病人不再有活躍病症。"},{"en":"If a treatment claims people are cured of diseases, researchers may ask for clear evidence.","zh":"如果一種治療聲稱病人的疾病被治癒，研究人員可能要求清楚證據。"},{"en":"The phrase describes complete recovery, not just temporary symptom relief.","zh":"這個短語描述完全康復，而不只是暫時緩解症狀。"}],"source":"71 - Homeopathy.pdf","sourcePage":6},{"front":"condense a theory into","meaning":"將理論濃縮成……","examples":[{"en":"Hahnemann condensed his theory into a single Latin phrase.","zh":"Hahnemann 將他的理論濃縮成一句拉丁語。"},{"en":"To condense a theory into a phrase means to express a complex idea in a short form.","zh":"condense a theory into 一個短語，指用簡短形式表達複雜想法。"},{"en":"A teacher may condense a grammar rule into one simple sentence for beginners.","zh":"老師可能為初學者把文法規則濃縮成一句簡單句子。"},{"en":"If a theory is condensed too much, students may remember it but miss important details.","zh":"如果理論被過度濃縮，學生可能記得它，但錯過重要細節。"},{"en":"The phrase describes shortening an idea while keeping its core meaning.","zh":"這個短語描述縮短想法，同時保留核心意思。"}],"source":"71 - Homeopathy.pdf","sourcePage":6},{"front":"a single Latin phrase","meaning":"一句拉丁語","examples":[{"en":"He condensed his theory into a single Latin phrase.","zh":"他將理論濃縮成一句拉丁語。"},{"en":"A single Latin phrase is one short expression written in Latin.","zh":"a single Latin phrase 是用拉丁語寫成的一個簡短表達。"},{"en":"Old university mottoes often use a single Latin phrase to express a value.","zh":"舊大學校訓常用一句拉丁語表達一種價值。"},{"en":"If a theory is summarised in a single Latin phrase, it may sound memorable and authoritative.","zh":"如果理論被概括成一句拉丁語，它可能聽起來易記而有權威感。"},{"en":"The phrase identifies both the language and the short form used.","zh":"這個短語同時指出語言和所用的簡短形式。"}],"source":"71 - Homeopathy.pdf","sourcePage":6},{"front":"similia similibus curentur","meaning":"以類治類","examples":[{"en":"The Latin phrase similia similibus curentur means “let likes be cured by likes.”","zh":"拉丁語 similia similibus curentur 意思是「以相似者治療相似者」。"},{"en":"Similia similibus curentur is the Latin expression for the homeopathic principle of treating like with like.","zh":"similia similibus curentur 是表示順勢療法「以類治類」原理的拉丁語表達。"},{"en":"Students may remember similia similibus curentur as the motto behind homeopathy.","zh":"學生可以把 similia similibus curentur 記作順勢療法背後的格言。"},{"en":"Because the phrase is Latin, the passage translates it to make the idea clearer.","zh":"因為這個短語是拉丁語，文章把它翻譯出來以令意思更清楚。"},{"en":"The phrase represents the central rule Hahnemann associated with homeopathy.","zh":"這個短語代表 Hahnemann 與順勢療法相連的核心規則。"}],"source":"71 - Homeopathy.pdf","sourcePage":6},{"front":"let likes be cured by likes","meaning":"以相似者治療相似者","examples":[{"en":"The phrase means that like should be cured by like.","zh":"這句話意思是相似者應由相似者治療。"},{"en":"“Let likes be cured by likes” means a symptom should be treated with something that can produce similar symptoms.","zh":"“Let likes be cured by likes” 意思是某種症狀應以能產生相似症狀的東西治療。"},{"en":"In a lesson, this phrase helps students understand the basic logic of homeopathy.","zh":"在課堂中，這句話幫助學生理解順勢療法的基本邏輯。"},{"en":"If learners remember “likes by likes,” they remember the contrast with ordinary symptom suppression.","zh":"如果學習者記得「相似治相似」，就能記住它與普通壓制症狀方法的對比。"},{"en":"The phrase is a slogan-like summary, not a full scientific explanation.","zh":"這個短語是口號式摘要，而不是完整科學解釋。"}],"source":"71 - Homeopathy.pdf","sourcePage":6},{"front":"produce symptoms","meaning":"產生症狀","examples":[{"en":"The medicine produces symptoms in a healthy person.","zh":"該藥物在健康人士身上產生症狀。"},{"en":"To produce symptoms means to cause signs or feelings of illness to appear.","zh":"produce symptoms 指造成疾病跡象或不適感出現。"},{"en":"A food allergy can produce symptoms such as swelling, itching, or stomach pain.","zh":"食物敏感可以產生腫脹、痕癢或胃痛等症狀。"},{"en":"If a substance produces symptoms, doctors may investigate how it affects the body.","zh":"如果某物質產生症狀，醫生可能調查它如何影響身體。"},{"en":"The phrase describes causing symptoms, not treating them.","zh":"這個短語描述造成症狀，而不是治療症狀。"}],"source":"71 - Homeopathy.pdf","sourcePage":7},{"front":"similar to","meaning":"與……相似","examples":[{"en":"The medicine produces symptoms similar to those of the patient.","zh":"該藥物產生與病人症狀相似的症狀。"},{"en":"Similar to means almost the same as, but not exactly identical.","zh":"similar to 指幾乎相同，但不完全一樣。"},{"en":"A student’s mistake may be similar to one made in an earlier essay.","zh":"學生的錯誤可能與早前文章中的一個錯誤相似。"},{"en":"If two patients have similar symptoms, doctors may compare possible causes.","zh":"如果兩名病人有相似症狀，醫生可能比較可能原因。"},{"en":"The phrase is used to show likeness without claiming total sameness.","zh":"這個短語用來顯示相似，而不是聲稱完全相同。"}],"source":"71 - Homeopathy.pdf","sourcePage":7},{"front":"symptoms experienced by the patient","meaning":"病人所經歷的症狀","examples":[{"en":"The medicine produces symptoms similar to those experienced by the patient.","zh":"該藥物產生與病人所經歷的症狀相似的症狀。"},{"en":"Symptoms experienced by the patient are the signs of illness the patient actually feels or shows.","zh":"symptoms experienced by the patient 是病人實際感到或表現出的疾病跡象。"},{"en":"A doctor asks about symptoms experienced by the patient before choosing tests.","zh":"醫生在選擇檢查前，會詢問病人所經歷的症狀。"},{"en":"If reported symptoms are unclear, the practitioner may ask when they started and how long they lasted.","zh":"如果報告的症狀不清楚，醫療人員可能詢問何時開始和持續多久。"},{"en":"The phrase focuses on the patient’s real condition.","zh":"這個短語重點在病人的真實狀況。"}],"source":"71 - Homeopathy.pdf","sourcePage":7},{"front":"process of making remedies","meaning":"製作藥物的過程","examples":[{"en":"The process of making remedies is very precise.","zh":"製作藥物的過程非常精確。"},{"en":"The process of making remedies means the steps used to prepare treatment substances.","zh":"process of making remedies 指準備治療物質所用的步驟。"},{"en":"A pharmacist follows a careful process when making medicines for patients.","zh":"藥劑師為病人製作藥物時會遵循仔細流程。"},{"en":"If the process of making a remedy is not followed, the final product may be inconsistent.","zh":"如果製作療劑的過程沒有被遵守，最終產品可能不一致。"},{"en":"The phrase focuses on preparation, not diagnosis.","zh":"這個短語重點在製備，而不是診斷。"}],"source":"71 - Homeopathy.pdf","sourcePage":7},{"front":"very precise","meaning":"非常精確","examples":[{"en":"The process of making remedies is very precise.","zh":"製作藥物的過程非常精確。"},{"en":"Very precise means exact, careful, and controlled in detail.","zh":"very precise 指精準、仔細並在細節上受控制。"},{"en":"A science experiment needs very precise measurements to produce reliable results.","zh":"科學實驗需要非常精確的量度，才能產生可靠結果。"},{"en":"If instructions are very precise, even a small mistake may change the outcome.","zh":"如果指示非常精確，即使小錯誤也可能改變結果。"},{"en":"The phrase describes accuracy rather than general care.","zh":"這個短語描述準確性，而不只是一般小心。"}],"source":"71 - Homeopathy.pdf","sourcePage":7},{"front":"a single substance","meaning":"單一物質","examples":[{"en":"A homeopathic remedy is normally a single substance.","zh":"順勢療法藥物通常是一種單一物質。"},{"en":"A single substance means one material rather than a mixture of many active materials.","zh":"a single substance 指一種材料，而不是多種活性材料的混合物。"},{"en":"A science teacher may ask students to test a single substance before comparing mixtures.","zh":"科學老師可能要求學生先測試單一物質，再比較混合物。"},{"en":"If a treatment uses a single substance, it may be easier to link effects to that substance.","zh":"如果治療使用單一物質，可能較容易把作用與該物質連繫起來。"},{"en":"The phrase stresses one source or ingredient.","zh":"這個短語強調一個來源或成分。"}],"source":"71 - Homeopathy.pdf","sourcePage":7},{"front":"be made from","meaning":"由……製成","examples":[{"en":"The substances may be made from plants, minerals or animals.","zh":"這些物質可能由植物、礦物或動物製成。"},{"en":"To be made from something means to be produced using that material as the source.","zh":"be made from 某物，指用該材料作來源製造出來。"},{"en":"Paper is made from wood fibres, while glass is made from sand and other materials.","zh":"紙由木纖維製成，而玻璃由沙和其他材料製成。"},{"en":"If a remedy is made from an animal source, its origin should be clearly identified.","zh":"如果療劑由動物來源製成，其來源應清楚標明。"},{"en":"The phrase explains the material origin of something.","zh":"這個短語解釋某物的材料來源。"}],"source":"71 - Homeopathy.pdf","sourcePage":7},{"front":"plants, minerals and animals","meaning":"植物、礦物和動物","examples":[{"en":"Homeopathic substances may come from plants, minerals and animals.","zh":"順勢療法物質可能來自植物、礦物和動物。"},{"en":"Plants, minerals and animals are three broad natural sources of materials.","zh":"plants, minerals and animals 是材料的三大天然來源。"},{"en":"Many traditional remedies use plants, while minerals and animal products may appear in other systems.","zh":"許多傳統療法使用植物，而礦物和動物產品可能出現在其他體系中。"},{"en":"If a product comes from plants, minerals and animals, its ingredients can vary widely.","zh":"如果產品來自植物、礦物和動物，其成分可能非常多樣。"},{"en":"The phrase lists the possible natural origins of a remedy.","zh":"這個短語列出療劑可能的天然來源。"}],"source":"71 - Homeopathy.pdf","sourcePage":7},{"front":"snake venom","meaning":"蛇毒","examples":[{"en":"Snake venom can be used as a source substance.","zh":"蛇毒可以用作來源物質。"},{"en":"Snake venom is poisonous liquid produced by some snakes.","zh":"snake venom 是一些蛇產生的有毒液體。"},{"en":"A biology lesson may discuss snake venom when explaining how animals defend themselves.","zh":"生物課解釋動物如何自我防衛時，可能討論蛇毒。"},{"en":"Because snake venom can be dangerous, any medical use requires strict control and expertise.","zh":"因為蛇毒可以很危險，任何醫療用途都需要嚴格控制和專業知識。"},{"en":"The phrase names an animal-derived source substance.","zh":"這個短語指出一種來自動物的來源物質。"}],"source":"71 - Homeopathy.pdf","sourcePage":7},{"front":"cuttlefish ink","meaning":"墨魚汁","examples":[{"en":"Cuttlefish ink is another example of a source substance.","zh":"墨魚汁是另一個來源物質例子。"},{"en":"Cuttlefish ink is dark liquid produced by cuttlefish, often used for defence in nature.","zh":"cuttlefish ink 是墨魚產生的深色液體，在自然中常用作防衛。"},{"en":"Some cuisines use cuttlefish ink to colour and flavour noodles or rice.","zh":"有些菜式使用墨魚汁為麵或飯染色和增添味道。"},{"en":"If cuttlefish ink is used as a source substance, it comes from an animal origin.","zh":"如果墨魚汁用作來源物質，它就是來自動物來源。"},{"en":"The phrase names a specific natural material from a sea animal.","zh":"這個短語指出來自海洋動物的一種特定天然材料。"}],"source":"71 - Homeopathy.pdf","sourcePage":7},{"front":"raw material","meaning":"原材料","examples":[{"en":"The raw material is dissolved in alcohol and water.","zh":"原材料溶解於酒精和水中。"},{"en":"Raw material is the original substance used to make a product.","zh":"raw material 是用來製造產品的原本物質。"},{"en":"Flour is a raw material for bread, while cotton is a raw material for cloth.","zh":"麵粉是麵包的原材料，而棉花是布料的原材料。"},{"en":"If raw material is contaminated, the final product may be unsafe or unusable.","zh":"如果原材料受污染，最終產品可能不安全或不能使用。"},{"en":"The phrase refers to the starting material before processing.","zh":"這個短語指加工前的起始材料。"}],"source":"71 - Homeopathy.pdf","sourcePage":8},{"front":"be dissolved in","meaning":"溶解於……","examples":[{"en":"The raw material is dissolved in a mixture of alcohol and water.","zh":"原材料溶解於酒精和水的混合物中。"},{"en":"To be dissolved in a liquid means to be mixed into it until it becomes part of the solution.","zh":"be dissolved in 某液體，指被混入其中，直到成為溶液一部分。"},{"en":"Sugar is dissolved in hot tea when it disappears into the drink.","zh":"糖在熱茶中消失並混入飲品時，就是溶解於熱茶中。"},{"en":"If a material cannot be dissolved in water, another liquid may be needed.","zh":"如果材料不能溶解於水，可能需要另一種液體。"},{"en":"The phrase describes a material becoming mixed into a liquid.","zh":"這個短語描述材料混入液體之中。"}],"source":"71 - Homeopathy.pdf","sourcePage":8},{"front":"a mixture of","meaning":"……的混合物","examples":[{"en":"The remedy begins with a mixture of alcohol and water.","zh":"該療劑由酒精和水的混合物開始。"},{"en":"A mixture of things is a combination of two or more materials or elements.","zh":"a mixture of 某些東西，是兩種或以上材料或元素的組合。"},{"en":"A salad is a mixture of vegetables, dressing, and sometimes fruit or nuts.","zh":"沙律是蔬菜、醬汁，有時還有水果或果仁的混合物。"},{"en":"If a medicine begins with a mixture, the proportions of each part may matter.","zh":"如果藥物由混合物開始，各部分比例可能重要。"},{"en":"The phrase shows that several things are combined.","zh":"這個短語顯示幾種東西被結合。"}],"source":"71 - Homeopathy.pdf","sourcePage":8},{"front":"alcohol and water","meaning":"酒精和水","examples":[{"en":"The raw material is mixed with alcohol and water.","zh":"原材料與酒精和水混合。"},{"en":"Alcohol and water are the liquids used together in the first stage described in the passage.","zh":"alcohol and water 是文章所描述第一階段一起使用的液體。"},{"en":"In a laboratory, alcohol and water may be used to dissolve or preserve certain materials.","zh":"在實驗室中，酒精和水可能用來溶解或保存某些材料。"},{"en":"If alcohol and water are mixed in fixed amounts, the solution has a controlled composition.","zh":"如果酒精和水按固定份量混合，溶液就有受控成分。"},{"en":"The phrase names the two liquids in the mixture.","zh":"這個短語指出混合物中的兩種液體。"}],"source":"71 - Homeopathy.pdf","sourcePage":8},{"front":"approximately","meaning":"大約","examples":[{"en":"The mixture contains approximately 90 per cent alcohol.","zh":"混合物含有大約百分之九十酒精。"},{"en":"Approximately means about or nearly, not exactly.","zh":"approximately 指大約或接近，不是完全精確。"},{"en":"The bus journey takes approximately twenty minutes when traffic is light.","zh":"交通暢順時，巴士車程大約二十分鐘。"},{"en":"If a figure is approximate, small differences are expected.","zh":"如果數字是大約值，出現小差異是正常的。"},{"en":"The word gives an estimate rather than a precise number.","zh":"這個字提供估算，而不是精確數字。"}],"source":"71 - Homeopathy.pdf","sourcePage":8},{"front":"respectively","meaning":"分別地","examples":[{"en":"The mixture is about 90 per cent alcohol and 10 per cent water, respectively.","zh":"該混合物分別約為百分之九十酒精和百分之十水。"},{"en":"Respectively means in the same order as the items just mentioned.","zh":"respectively 指按照剛提及項目的相同次序分別對應。"},{"en":"Tom and Anna scored 80 and 90 marks, respectively, meaning Tom scored 80 and Anna scored 90.","zh":"Tom 和 Anna 分別得80和90分，意思是 Tom 得80分，Anna 得90分。"},{"en":"If two percentages are listed respectively, readers must match each number to the correct item.","zh":"如果兩個百分比分別列出，讀者必須把每個數字配對到正確項目。"},{"en":"The word prevents confusion in paired information.","zh":"這個字避免配對資料混亂。"}],"source":"71 - Homeopathy.pdf","sourcePage":8},{"front":"be left to stand","meaning":"靜置","examples":[{"en":"The mixture is left to stand for two to four weeks.","zh":"該混合物被靜置兩至四星期。"},{"en":"To be left to stand means to be allowed to sit without being used or disturbed for a period.","zh":"be left to stand 指讓某物在一段時間內放着，不被使用或打擾。"},{"en":"Bread dough may be left to stand so it can rise before baking.","zh":"麵團可能被靜置，讓它在烘焙前發起。"},{"en":"If a liquid is left to stand, its ingredients may settle or combine over time.","zh":"如果液體被靜置，其成分可能隨時間沉澱或結合。"},{"en":"The phrase describes waiting as part of a preparation process.","zh":"這個短語描述等待作為製備過程的一部分。"}],"source":"71 - Homeopathy.pdf","sourcePage":8},{"front":"two to four weeks","meaning":"兩至四星期","examples":[{"en":"The mixture is left to stand for two to four weeks.","zh":"該混合物被靜置兩至四星期。"},{"en":"Two to four weeks means a period between fourteen and twenty-eight days.","zh":"two to four weeks 指十四至二十八天之間的時間。"},{"en":"A small home repair may take two to four weeks if parts must be ordered.","zh":"如果需要訂購零件，小型家居維修可能需時兩至四星期。"},{"en":"If a process takes two to four weeks, people should not expect immediate results.","zh":"如果一個過程需要兩至四星期，人們不應期待即時結果。"},{"en":"The phrase gives a time range rather than one exact duration.","zh":"這個短語提供時間範圍，而不是單一精確時長。"}],"source":"71 - Homeopathy.pdf","sourcePage":8},{"front":"shaken occasionally","meaning":"偶爾搖晃","examples":[{"en":"The mixture is shaken occasionally before being strained.","zh":"該混合物在被過濾前會偶爾搖晃。"},{"en":"Shaken occasionally means moved or shaken from time to time, not constantly.","zh":"shaken occasionally 指不時被搖晃，而不是一直搖晃。"},{"en":"A bottle of salad dressing may be shaken occasionally so the oil and vinegar mix again.","zh":"沙律醬瓶可能偶爾搖晃，讓油和醋再次混合。"},{"en":"If a mixture is shaken occasionally, its contents may combine more evenly.","zh":"如果混合物被偶爾搖晃，其內容物可能更平均結合。"},{"en":"The phrase describes repeated but not continuous movement.","zh":"這個短語描述重複但非持續的移動。"}],"source":"71 - Homeopathy.pdf","sourcePage":8},{"front":"be strained","meaning":"被過濾","examples":[{"en":"The mixture is then strained.","zh":"然後該混合物被過濾。"},{"en":"To be strained means to be passed through a filter to remove solid pieces.","zh":"be strained 指通過濾器以除去固體碎片。"},{"en":"Soup may be strained to remove bones, seeds, or rough pieces.","zh":"湯可能被過濾，以除去骨頭、籽或粗糙碎塊。"},{"en":"If a liquid is strained carefully, the resulting liquid becomes clearer.","zh":"如果液體被仔細過濾，所得液體會更清澈。"},{"en":"The phrase describes filtering a mixture.","zh":"這個短語描述過濾混合物。"}],"source":"71 - Homeopathy.pdf","sourcePage":8},{"front":"resulting liquid","meaning":"所得液體","examples":[{"en":"The resulting liquid is called a tincture.","zh":"所得液體被稱為酊劑。"},{"en":"The resulting liquid is the liquid produced after a process has been completed.","zh":"resulting liquid 是某過程完成後產生的液體。"},{"en":"After tea leaves are removed, the resulting liquid is the tea people drink.","zh":"茶葉被移除後，所得液體就是人們飲用的茶。"},{"en":"If a mixture is filtered, the resulting liquid may be stored for later use.","zh":"如果混合物被過濾，所得液體可能被儲存以供之後使用。"},{"en":"The phrase points to the product of the previous steps.","zh":"這個短語指前面步驟所產生的產品。"}],"source":"71 - Homeopathy.pdf","sourcePage":9},{"front":"tincture","meaning":"酊劑","examples":[{"en":"The tincture is then diluted according to specific measures.","zh":"然後酊劑按照特定度量被稀釋。"},{"en":"A tincture is a liquid extract made by soaking a substance in alcohol or another liquid.","zh":"tincture 是把某物質浸泡在酒精或另一液體中製成的液體萃取物。"},{"en":"A herbal tincture may be stored in a small dark bottle with a dropper.","zh":"草本酊劑可能儲存在帶滴管的小深色瓶中。"},{"en":"If a tincture is too concentrated, it may be diluted before use.","zh":"如果酊劑太濃，使用前可能會被稀釋。"},{"en":"The word names the liquid extract before later dilution.","zh":"這個字指出之後稀釋前的液體萃取物。"}],"source":"71 - Homeopathy.pdf","sourcePage":9},{"front":"be diluted according to","meaning":"按照……稀釋","examples":[{"en":"The tincture is diluted according to very specific measures.","zh":"酊劑按照非常特定的度量被稀釋。"},{"en":"To be diluted according to measures means to be made weaker by following exact quantities.","zh":"be diluted according to 度量，指按照精確份量把某物稀釋。"},{"en":"Juice may be diluted according to the instructions on the bottle.","zh":"果汁可能按照瓶上指示被稀釋。"},{"en":"If a chemical is diluted according to the wrong ratio, the result may be unsafe or ineffective.","zh":"如果化學品按照錯誤比例稀釋，結果可能不安全或無效。"},{"en":"The phrase connects dilution with fixed rules.","zh":"這個短語把稀釋與固定規則連繫起來。"}],"source":"71 - Homeopathy.pdf","sourcePage":9},{"front":"specific measures","meaning":"特定度量","examples":[{"en":"The tincture is diluted according to specific measures.","zh":"酊劑按照特定度量被稀釋。"},{"en":"Specific measures are exact amounts or steps used in a process.","zh":"specific measures 是過程中使用的精確份量或步驟。"},{"en":"A recipe gives specific measures so the cake tastes the same each time.","zh":"食譜提供特定度量，讓蛋糕每次味道相同。"},{"en":"If specific measures are ignored, the final mixture may change.","zh":"如果特定度量被忽略，最終混合物可能改變。"},{"en":"The phrase stresses exact quantities rather than rough guessing.","zh":"這個短語強調精確份量，而不是粗略估計。"}],"source":"71 - Homeopathy.pdf","sourcePage":9},{"front":"at a ratio of","meaning":"以……比例","examples":[{"en":"The tincture is diluted at a ratio of 1:100.","zh":"酊劑以1比100的比例稀釋。"},{"en":"At a ratio of means in a fixed relationship between two amounts.","zh":"at a ratio of 指兩個份量之間按固定關係。"},{"en":"A cleaner may be mixed with water at a ratio of one part cleaner to ten parts water.","zh":"清潔劑可能以一份清潔劑比十份水的比例與水混合。"},{"en":"If the ratio is wrong, a mixture may become too strong or too weak.","zh":"如果比例錯誤，混合物可能太強或太弱。"},{"en":"The phrase explains how two quantities are compared.","zh":"這個短語解釋兩個數量如何比較。"}],"source":"71 - Homeopathy.pdf","sourcePage":9},{"front":"produce a remedy","meaning":"製作藥物","examples":[{"en":"One drop of tincture is added to the mixture to produce a remedy.","zh":"一滴酊劑被加入混合物中，以製作藥物。"},{"en":"To produce a remedy means to make a preparation intended for treatment.","zh":"produce a remedy 指製作用於治療的製劑。"},{"en":"A pharmacy may combine ingredients carefully to produce a remedy for a patient.","zh":"藥房可能仔細結合成分，為病人製作藥物。"},{"en":"If the preparation steps change, they may produce a different remedy.","zh":"如果製備步驟改變，可能製作出不同療劑。"},{"en":"The phrase focuses on making the final treatment product.","zh":"這個短語重點在製作最終治療產品。"}],"source":"71 - Homeopathy.pdf","sourcePage":9},{"front":"1C potency","meaning":"1C效力","examples":[{"en":"One dilution stage produces a remedy called 1C potency.","zh":"一個稀釋階段製作出稱為1C效力的藥物。"},{"en":"1C potency is the first centesimal dilution level in the homeopathic preparation described.","zh":"1C potency 是文章所描述順勢療法製備中的第一個百分稀釋水平。"},{"en":"A student reading the passage should treat 1C potency as a label for a dilution stage.","zh":"閱讀文章的學生應把1C效力視為某稀釋階段的標籤。"},{"en":"If the dilution process continues, the potency number increases beyond 1C.","zh":"如果稀釋過程繼續，效力數字會超過1C。"},{"en":"The phrase names a specific strength level in the passage’s system.","zh":"這個短語指出文章體系中的特定強度水平。"}],"source":"71 - Homeopathy.pdf","sourcePage":9},{"front":"potency or strength","meaning":"效力；強度","examples":[{"en":"The passage uses potency or strength to describe the remedy.","zh":"文章使用效力或強度來描述該療劑。"},{"en":"Potency or strength means the degree of power a remedy is said to have.","zh":"potency or strength 指某療劑據稱具有的力量程度。"},{"en":"A medicine label may describe strength so patients know how much active ingredient it contains.","zh":"藥物標籤可能描述強度，讓病人知道含有多少有效成分。"},{"en":"In the passage, higher potency is linked with greater dilution, which creates controversy.","zh":"在文章中，較高效力與較高稀釋度相連，這引起爭議。"},{"en":"The phrase explains how the remedy’s power is described.","zh":"這個短語解釋療劑力量如何被描述。"}],"source":"71 - Homeopathy.pdf","sourcePage":9},{"front":"one drop of","meaning":"一滴……","examples":[{"en":"One drop of the tincture is added to 99 drops of alcohol and water.","zh":"一滴酊劑被加入99滴酒精和水中。"},{"en":"One drop of something means a very small amount of liquid.","zh":"one drop of 某物，指非常少量的液體。"},{"en":"One drop of ink can colour a glass of water.","zh":"一滴墨水可以令一杯水染色。"},{"en":"If only one drop is added, measurement must be careful.","zh":"如果只加入一滴，量度必須小心。"},{"en":"The phrase gives a tiny liquid quantity.","zh":"這個短語給出極小液體份量。"}],"source":"71 - Homeopathy.pdf","sourcePage":9},{"front":"be added to","meaning":"被加入……","examples":[{"en":"One drop of tincture is added to 99 drops of alcohol and water.","zh":"一滴酊劑被加入99滴酒精和水中。"},{"en":"To be added to something means to be put into it as an extra part.","zh":"be added to 某物，指作為額外部分被放入其中。"},{"en":"Sugar may be added to tea if someone wants it sweeter.","zh":"如果有人想茶更甜，糖可以被加入茶中。"},{"en":"If too much liquid is added to a recipe, the mixture may become too thin.","zh":"如果太多液體被加入食譜，混合物可能變得太稀。"},{"en":"The phrase describes putting one thing into another.","zh":"這個短語描述把一物放進另一物。"}],"source":"71 - Homeopathy.pdf","sourcePage":9},{"front":"at each stage of dilution","meaning":"在每個稀釋階段","examples":[{"en":"At each stage of dilution, the remedy is shaken vigorously.","zh":"在每個稀釋階段，該療劑都會被用力搖晃。"},{"en":"At each stage of dilution means every time the substance is made more diluted.","zh":"at each stage of dilution 指每次該物質被進一步稀釋時。"},{"en":"In a science experiment, students should label the mixture at each stage of dilution.","zh":"在科學實驗中，學生應在每個稀釋階段標記混合物。"},{"en":"If the same action is done at each stage, the process remains consistent.","zh":"如果每個階段都進行同一動作，過程就保持一致。"},{"en":"The phrase divides a repeated process into steps.","zh":"這個短語把重複過程分成多個步驟。"}],"source":"71 - Homeopathy.pdf","sourcePage":10},{"front":"shaken vigorously","meaning":"用力搖晃","examples":[{"en":"The remedy is shaken vigorously at each stage.","zh":"該療劑在每個階段都被用力搖晃。"},{"en":"Shaken vigorously means shaken with strong, energetic movements.","zh":"shaken vigorously 指以強而有力的動作搖晃。"},{"en":"A bottle of sauce may be shaken vigorously before serving so the ingredients mix evenly.","zh":"醬汁瓶上碟前可能被用力搖晃，讓成分平均混合。"},{"en":"If a mixture is shaken vigorously, air bubbles or stronger mixing may occur.","zh":"如果混合物被用力搖晃，可能產生氣泡或更強混合效果。"},{"en":"The phrase describes forceful movement, not gentle stirring.","zh":"這個短語描述有力移動，而不是輕輕攪拌。"}],"source":"71 - Homeopathy.pdf","sourcePage":10},{"front":"through this process","meaning":"透過這個過程","examples":[{"en":"Hahnemann believed that energy was released through this process.","zh":"Hahnemann 相信能量透過這個過程被釋放。"},{"en":"Through this process means by means of the steps just described.","zh":"through this process 指透過剛描述的那些步驟。"},{"en":"Students improve pronunciation through this process of listening, repeating, and receiving feedback.","zh":"學生透過聆聽、重複和接受回饋這個過程改善發音。"},{"en":"If a result happens through this process, the steps are treated as the cause.","zh":"如果結果透過這個過程發生，那些步驟就被視為原因。"},{"en":"The phrase links an outcome to a sequence of actions.","zh":"這個短語把結果與一連串行動連繫起來。"}],"source":"71 - Homeopathy.pdf","sourcePage":10},{"front":"be released","meaning":"被釋放","examples":[{"en":"Hahnemann believed that the energy of the substance was released.","zh":"Hahnemann 相信物質的能量被釋放。"},{"en":"To be released means to be set free or allowed to come out.","zh":"be released 指被釋放出來或被容許出現。"},{"en":"Steam is released when a kettle boils.","zh":"水壺煮沸時，蒸汽會被釋放。"},{"en":"If information is released too early, people may react before plans are complete.","zh":"如果資訊太早被釋放，人們可能在計劃完成前作出反應。"},{"en":"The phrase describes something becoming free, visible, or available.","zh":"這個短語描述某物變得自由、可見或可用。"}],"source":"71 - Homeopathy.pdf","sourcePage":10},{"front":"beyond a 12C potency","meaning":"超過12C效力","examples":[{"en":"After dilution beyond a 12C potency, the original substance is unlikely to remain.","zh":"稀釋超過12C效力後，原本物質不大可能仍然存在。"},{"en":"Beyond a 12C potency means past the dilution level labelled 12C.","zh":"beyond a 12C potency 指超過標示為12C的稀釋水平。"},{"en":"In the passage, beyond a 12C potency suggests an extremely high level of dilution.","zh":"在文章中，超過12C效力暗示極高稀釋程度。"},{"en":"If dilution continues beyond that point, less original material is expected to remain.","zh":"如果稀釋在該點後繼續，預期留下的原本材料會更少。"},{"en":"The phrase marks a threshold in the dilution process.","zh":"這個短語標示稀釋過程中的一個門檻。"}],"source":"71 - Homeopathy.pdf","sourcePage":10},{"front":"it is unlikely that","meaning":"不大可能","examples":[{"en":"It is unlikely that even a molecule of the original substance remains.","zh":"不大可能連一個原本物質的分子仍然存在。"},{"en":"It is unlikely that means it probably will not happen or is probably not true.","zh":"it is unlikely that 指某事大概不會發生或大概不是真的。"},{"en":"It is unlikely that a student will improve without practice and feedback.","zh":"學生沒有練習和回饋，不大可能進步。"},{"en":"If evidence is weak, it is unlikely that readers will accept the claim.","zh":"如果證據薄弱，讀者不大可能接受該主張。"},{"en":"The phrase expresses low probability.","zh":"這個短語表達低可能性。"}],"source":"71 - Homeopathy.pdf","sourcePage":10},{"front":"a molecule of","meaning":"一個……分子","examples":[{"en":"Even a molecule of the original substance may not remain.","zh":"甚至一個原本物質的分子也可能不會留下。"},{"en":"A molecule of something is one tiny unit of that substance.","zh":"a molecule of 某物，是該物質的一個微小單位。"},{"en":"A chemistry student learns that water is made of molecules.","zh":"化學學生會學到水由分子組成。"},{"en":"If not even a molecule remains, the original material is absent at a microscopic level.","zh":"如果連一個分子都沒有留下，原本材料在微觀層面上已不存在。"},{"en":"The phrase describes an extremely small amount.","zh":"這個短語描述極少量。"}],"source":"71 - Homeopathy.pdf","sourcePage":10},{"front":"original substance","meaning":"原本物質","examples":[{"en":"The original substance may no longer remain after high dilution.","zh":"高度稀釋後，原本物質可能不再存在。"},{"en":"The original substance is the starting material used before dilution or processing.","zh":"original substance 是稀釋或加工前使用的起始材料。"},{"en":"In a cooking experiment, the original substance might be flour before it is mixed into dough.","zh":"在烹飪實驗中，原本物質可能是混入麵團前的麵粉。"},{"en":"If repeated dilution removes the original substance, the final liquid may contain little or none of it.","zh":"如果反覆稀釋移除了原本物質，最終液體可能含有很少甚至沒有它。"},{"en":"The phrase points back to the material used at the beginning.","zh":"這個短語指回一開始使用的材料。"}],"source":"71 - Homeopathy.pdf","sourcePage":10},{"front":"yet ironically","meaning":"但諷刺的是","examples":[{"en":"Yet ironically, the passage says the more dilute remedy is considered stronger.","zh":"但諷刺的是，文章說越稀釋的療劑被認為越強。"},{"en":"Yet ironically means but in a surprising or contradictory way.","zh":"yet ironically 指但以令人意外或矛盾的方式。"},{"en":"The student bought a planner to save time; yet ironically, she spent hours decorating it.","zh":"學生買了計劃本來節省時間；但諷刺的是，她花了數小時裝飾它。"},{"en":"If a remedy contains less original substance yet is said to be stronger, the claim sounds ironic.","zh":"如果療劑含有較少原本物質卻被說成更強，這種主張聽起來帶有諷刺意味。"},{"en":"The phrase introduces a result that goes against expectation.","zh":"這個短語引出違反預期的結果。"}],"source":"71 - Homeopathy.pdf","sourcePage":10},{"front":"the more…, the stronger…","meaning":"越……就越強","examples":[{"en":"The passage states that the more dilute the remedy is, the stronger it is.","zh":"文章指出療劑越稀釋，效力就越強。"},{"en":"The more…, the stronger… shows that as one quality increases, strength also increases.","zh":"the more…, the stronger… 顯示某特質增加時，強度也增加。"},{"en":"The more clearly a teacher explains a rule, the stronger students’ understanding becomes.","zh":"老師越清楚解釋規則，學生的理解就越強。"},{"en":"In ordinary science, the idea that the more diluted something is, the stronger it becomes may seem surprising.","zh":"在普通科學中，某物越被稀釋就越強這想法可能令人意外。"},{"en":"The phrase expresses a proportional relationship.","zh":"這個短語表達比例關係。"}],"source":"71 - Homeopathy.pdf","sourcePage":10},{"front":"make no sense","meaning":"說不通；沒有道理","examples":[{"en":"The passage admits that this idea makes no sense in light of present-day science.","zh":"文章承認，鑑於現代科學，這個想法說不通。"},{"en":"To make no sense means to seem illogical or impossible to understand.","zh":"make no sense 指看似不合邏輯或無法理解。"},{"en":"The timetable makes no sense if two lessons are placed in different rooms at the same time.","zh":"如果兩堂課同時安排在不同課室，時間表就說不通。"},{"en":"If an explanation makes no sense, students need a clearer reason or better evidence.","zh":"如果解釋說不通，學生需要更清楚理由或更好證據。"},{"en":"The phrase expresses strong doubt about logic or meaning.","zh":"這個短語表達對邏輯或意思的強烈懷疑。"}],"source":"71 - Homeopathy.pdf","sourcePage":11},{"front":"in light of","meaning":"鑑於；按照","examples":[{"en":"The claim makes no sense in light of present-day science.","zh":"鑑於現代科學，這個主張說不通。"},{"en":"In light of something means considering that information or evidence.","zh":"in light of 某事，指考慮到該資訊或證據。"},{"en":"In light of the rain warning, the school moved sports day indoors.","zh":"鑑於大雨警告，學校把運動會移到室內。"},{"en":"If a decision changes in light of new evidence, the new facts affected the choice.","zh":"如果決定因新證據而改變，新的事實影響了選擇。"},{"en":"The phrase introduces the context used for judging something.","zh":"這個短語引出判斷某事所用的背景。"}],"source":"71 - Homeopathy.pdf","sourcePage":11},{"front":"present-day science","meaning":"現代科學","examples":[{"en":"Present-day science does not support the idea that greater dilution means greater strength.","zh":"現代科學並不支持稀釋度越高代表效力越強的想法。"},{"en":"Present-day science means the scientific knowledge and methods accepted today.","zh":"present-day science 指今天被接受的科學知識和方法。"},{"en":"Present-day science uses controlled studies, measurement, and repeatable evidence.","zh":"現代科學使用受控研究、量度和可重複證據。"},{"en":"If an old theory conflicts with present-day science, researchers may ask for stronger proof.","zh":"如果舊理論與現代科學衝突，研究人員可能要求更強證據。"},{"en":"The phrase contrasts modern scientific understanding with older ideas.","zh":"這個短語把現代科學理解與較舊想法作對比。"}],"source":"71 - Homeopathy.pdf","sourcePage":11},{"front":"regardless of","meaning":"不管；無論","examples":[{"en":"The passage says the practice continues regardless of what science says is impossible.","zh":"文章說，不管科學認為甚麼是不可能，這種做法仍然繼續。"},{"en":"Regardless of something means without being changed or stopped by it.","zh":"regardless of 某事，指不受它改變或阻止。"},{"en":"Students must follow exam rules regardless of how nervous they feel.","zh":"無論學生多緊張，都必須遵守考試規則。"},{"en":"If a habit continues regardless of criticism, people may be strongly attached to it.","zh":"如果習慣不管批評仍然持續，人們可能對它非常依附。"},{"en":"The phrase shows that one factor does not prevent another action.","zh":"這個短語顯示一個因素不能阻止另一行動。"}],"source":"71 - Homeopathy.pdf","sourcePage":11},{"front":"in practice","meaning":"實際上","examples":[{"en":"The passage claims that, in practice, higher dilution has a stronger effect.","zh":"文章聲稱，實際上，更高稀釋度有更強效果。"},{"en":"In practice means in real use or actual experience, not only in theory.","zh":"in practice 指在實際使用或實際經驗中，而不只是理論上。"},{"en":"A timetable may look simple on paper, but in practice students may have too little time to move rooms.","zh":"時間表在紙上可能看起來簡單，但實際上學生可能沒有足夠時間轉課室。"},{"en":"If an idea works in practice, people may value it even if it sounds unusual.","zh":"如果想法在實際上有效，人們即使覺得它聽起來不尋常，也可能重視它。"},{"en":"The phrase contrasts actual use with theory or expectation.","zh":"這個短語把實際使用與理論或預期作對比。"}],"source":"71 - Homeopathy.pdf","sourcePage":11},{"front":"higher dilution","meaning":"更高稀釋度","examples":[{"en":"The passage claims that higher dilution leads to a stronger effect.","zh":"文章聲稱更高稀釋度會帶來更強效果。"},{"en":"Higher dilution means the original substance has been mixed with more liquid and made weaker in concentration.","zh":"higher dilution 指原本物質與更多液體混合，濃度變得更低。"},{"en":"In chemistry, higher dilution usually means less of the original substance is present in each drop.","zh":"在化學中，更高稀釋度通常指每滴中原本物質更少。"},{"en":"Because higher dilution reduces concentration, claims about stronger effects can be controversial.","zh":"因為更高稀釋度會降低濃度，關於更強效果的主張可能具爭議。"},{"en":"The phrase describes a greater degree of dilution.","zh":"這個短語描述更大的稀釋程度。"}],"source":"71 - Homeopathy.pdf","sourcePage":11},{"front":"longer-lasting effect","meaning":"更持久的效果","examples":[{"en":"The passage claims that higher dilution creates a longer-lasting effect.","zh":"文章聲稱更高稀釋度會產生更持久的效果。"},{"en":"A longer-lasting effect is an effect that continues for more time.","zh":"longer-lasting effect 是持續更長時間的效果。"},{"en":"A good study routine has a longer-lasting effect than one night of memorising.","zh":"良好溫習習慣比一晚死記硬背有更持久效果。"},{"en":"If a treatment is claimed to have a longer-lasting effect, researchers may ask how long the effect actually lasts.","zh":"如果一種治療被聲稱有更持久效果，研究人員可能詢問效果實際持續多久。"},{"en":"The phrase compares duration, not just strength.","zh":"這個短語比較持續時間，而不只是強度。"}],"source":"71 - Homeopathy.pdf","sourcePage":11},{"front":"high dilutions","meaning":"高度稀釋","examples":[{"en":"The use of high dilutions has given rise to controversy.","zh":"使用高度稀釋引起了爭議。"},{"en":"High dilutions are mixtures in which the original substance has been diluted many times.","zh":"high dilutions 是原本物質被多次稀釋的混合物。"},{"en":"In a laboratory, high dilutions may contain very little of the starting material.","zh":"在實驗室中，高度稀釋物可能只含有很少起始材料。"},{"en":"If a remedy uses high dilutions, people may debate whether enough substance remains to have an effect.","zh":"如果療劑使用高度稀釋，人們可能爭論是否仍有足夠物質產生效果。"},{"en":"The phrase refers to repeated, extreme dilution.","zh":"這個短語指反覆而極端的稀釋。"}],"source":"71 - Homeopathy.pdf","sourcePage":11},{"front":"give rise to controversy","meaning":"引起爭議","examples":[{"en":"The use of high dilutions has given rise to controversy.","zh":"使用高度稀釋引起了爭議。"},{"en":"To give rise to controversy means to cause disagreement or public debate.","zh":"give rise to controversy 指造成分歧或公共爭論。"},{"en":"A new school rule may give rise to controversy if parents think it is unfair.","zh":"如果家長認為新校規不公平，它可能引起爭議。"},{"en":"If a medical claim lacks clear evidence, it can give rise to controversy.","zh":"如果醫學主張缺乏清楚證據，它可以引起爭議。"},{"en":"The phrase describes something causing dispute.","zh":"這個短語描述某事造成爭議。"}],"source":"71 - Homeopathy.pdf","sourcePage":11},{"front":"conventional doctors","meaning":"常規醫學醫生","examples":[{"en":"Many conventional doctors question homeopathy.","zh":"許多常規醫學醫生質疑順勢療法。"},{"en":"Conventional doctors are doctors trained in mainstream medical practice.","zh":"conventional doctors 是接受主流醫學訓練的醫生。"},{"en":"Conventional doctors usually rely on clinical evidence, diagnosis, and standard treatments.","zh":"常規醫學醫生通常依靠臨床證據、診斷和標準治療。"},{"en":"If conventional doctors question a treatment, they may be concerned about evidence or safety.","zh":"如果常規醫學醫生質疑某治療，他們可能關注證據或安全。"},{"en":"The phrase contrasts mainstream medical professionals with alternative practitioners.","zh":"這個短語把主流醫療專業人員與另類療法從業者作對比。"}],"source":"71 - Homeopathy.pdf","sourcePage":11},{"front":"claim that","meaning":"聲稱","examples":[{"en":"Many conventional doctors claim that homeopathy functions only as a placebo.","zh":"許多常規醫學醫生聲稱順勢療法只作為安慰劑發揮作用。"},{"en":"To claim that something is true means to state it as a belief or argument.","zh":"claim that 某事為真，指把它作為信念或論點陳述。"},{"en":"A company may claim that its course improves speaking quickly, but students should look for evidence.","zh":"公司可能聲稱其課程能快速改善口語，但學生應尋找證據。"},{"en":"If doctors claim that a treatment is ineffective, supporters may respond with their own evidence.","zh":"如果醫生聲稱某治療無效，支持者可能以自己的證據回應。"},{"en":"The phrase introduces a statement that may be debated.","zh":"這個短語引出可能被爭論的陳述。"}],"source":"71 - Homeopathy.pdf","sourcePage":12},{"front":"function only as","meaning":"只作為……發揮作用","examples":[{"en":"Some doctors claim that homeopathy functions only as a placebo.","zh":"一些醫生聲稱順勢療法只作為安慰劑發揮作用。"},{"en":"To function only as something means to work merely in that role and not in another claimed way.","zh":"function only as 某物，指只以該角色發揮作用，而不是以其他聲稱方式。"},{"en":"A decorative button may function only as decoration and not open anything.","zh":"裝飾鈕扣可能只作為裝飾發揮作用，並不能打開任何東西。"},{"en":"If a treatment functions only as a placebo, its effect depends on belief rather than active medicine.","zh":"如果治療只作為安慰劑發揮作用，其效果取決於信念，而不是活性藥物。"},{"en":"The phrase limits what something is said to do.","zh":"這個短語限制某物據稱能做的事情。"}],"source":"71 - Homeopathy.pdf","sourcePage":12},{"front":"placebo","meaning":"安慰劑","examples":[{"en":"Some doctors describe homeopathic remedies as a placebo.","zh":"一些醫生把順勢療法藥物描述為安慰劑。"},{"en":"A placebo is a treatment with no active medical ingredient, used to test or create expectation effects.","zh":"placebo 是沒有活性醫學成分的治療，用於測試或產生期望效應。"},{"en":"In a clinical study, one group may receive the real medicine while another receives a placebo.","zh":"在臨床研究中，一組人可能接受真正藥物，另一組接受安慰劑。"},{"en":"If patients improve after a placebo, researchers ask whether belief or expectation affected symptoms.","zh":"如果病人在服用安慰劑後改善，研究人員會問信念或期望是否影響了症狀。"},{"en":"The word is important in debates about treatment effectiveness.","zh":"這個字在關於治療成效的爭論中很重要。"}],"source":"71 - Homeopathy.pdf","sourcePage":12},{"front":"dosage","meaning":"劑量","examples":[{"en":"They argue that the dosage is too small to have a medical effect.","zh":"他們主張劑量太小，不能產生醫學效果。"},{"en":"Dosage is the amount of medicine taken at one time or over a period.","zh":"dosage 是一次或一段時間內服用的藥物份量。"},{"en":"A doctor may adjust dosage if a patient is too young, too old, or has side effects.","zh":"如果病人太年幼、太年長或有副作用，醫生可能調整劑量。"},{"en":"If the dosage is too high or too low, treatment may become unsafe or ineffective.","zh":"如果劑量太高或太低，治療可能變得不安全或無效。"},{"en":"The word focuses on the amount of medicine used.","zh":"這個字重點在藥物使用份量。"}],"source":"71 - Homeopathy.pdf","sourcePage":12},{"front":"so small","meaning":"如此細小","examples":[{"en":"The dosage is described as so small that doctors doubt its effect.","zh":"劑量被描述為如此細小，以致醫生懷疑其效果。"},{"en":"So small means extremely small, often small enough to create a result or concern.","zh":"so small 指非常細小，通常小到會造成某種結果或疑慮。"},{"en":"The text on the label was so small that older customers could not read it.","zh":"標籤上的字如此細小，以致年長顧客看不清。"},{"en":"If a dose is so small, people may question whether it can affect the body.","zh":"如果劑量如此細小，人們可能質疑它是否能影響身體。"},{"en":"The phrase often leads to a “that” clause showing the result.","zh":"這個短語常接 that 子句來顯示結果。"}],"source":"71 - Homeopathy.pdf","sourcePage":12},{"front":"clinical experience","meaning":"臨床經驗","examples":[{"en":"The passage refers to the clinical experience of homeopathy.","zh":"文章提到順勢療法的臨床經驗。"},{"en":"Clinical experience is knowledge gained from treating or observing patients.","zh":"clinical experience 是從治療或觀察病人中獲得的知識。"},{"en":"A nurse with clinical experience may notice warning signs that a textbook alone cannot teach.","zh":"有臨床經驗的護士可能注意到單靠教科書不能教到的警號。"},{"en":"If clinical experience supports a claim, researchers may still test it through controlled studies.","zh":"如果臨床經驗支持某主張，研究人員仍可能透過受控研究測試它。"},{"en":"The phrase describes practice-based knowledge in healthcare.","zh":"這個短語描述醫療保健中的實務知識。"}],"source":"71 - Homeopathy.pdf","sourcePage":12},{"front":"tiny dose","meaning":"微小劑量","examples":[{"en":"The passage claims that a tiny dose can be effective.","zh":"文章聲稱微小劑量可以有效。"},{"en":"A tiny dose is a very small amount of a medicine or substance.","zh":"tiny dose 是非常少量的藥物或物質。"},{"en":"Some powerful medicines must be given in a tiny dose to avoid harm.","zh":"一些強效藥物必須以微小劑量給予，以避免傷害。"},{"en":"If a tiny dose is claimed to work, measurement and evidence become important.","zh":"如果微小劑量被聲稱有效，量度和證據就變得重要。"},{"en":"The phrase stresses the very small quantity used.","zh":"這個短語強調所使用的份量非常少。"}],"source":"71 - Homeopathy.pdf","sourcePage":12},{"front":"be effective","meaning":"有效","examples":[{"en":"The passage claims that homeopathy can be effective in some cases.","zh":"文章聲稱順勢療法在某些情況下可以有效。"},{"en":"To be effective means to produce the intended result.","zh":"be effective 指產生預期結果。"},{"en":"A study plan is effective if it helps students remember and use what they learn.","zh":"如果溫習計劃幫助學生記住並使用所學內容，它就是有效的。"},{"en":"If a treatment is effective, symptoms should improve in a clear and measurable way.","zh":"如果治療有效，症狀應以清楚且可量度的方式改善。"},{"en":"The phrase describes success in achieving a purpose.","zh":"這個短語描述成功達到目的。"}],"source":"71 - Homeopathy.pdf","sourcePage":12},{"front":"unconscious people","meaning":"失去知覺的人","examples":[{"en":"The passage claims that homeopathy works on unconscious people.","zh":"文章聲稱順勢療法對失去知覺的人有效。"},{"en":"Unconscious people are people who are not awake and cannot respond normally.","zh":"unconscious people 是沒有清醒意識並不能正常回應的人。"},{"en":"An unconscious person after an accident needs urgent medical attention.","zh":"意外後失去知覺的人需要緊急醫療照顧。"},{"en":"If a claimed treatment is said to affect unconscious people, the passage uses this to argue it is not only expectation.","zh":"如果某聲稱治療被說成能影響失去知覺的人，文章用此來主張它不只是期望作用。"},{"en":"The phrase refers to people without normal awareness at that moment.","zh":"這個短語指當刻沒有正常意識的人。"}],"source":"71 - Homeopathy.pdf","sourcePage":12},{"front":"infants","meaning":"嬰兒","examples":[{"en":"The passage claims that homeopathy works on infants.","zh":"文章聲稱順勢療法對嬰兒有效。"},{"en":"Infants are very young babies.","zh":"infants 是非常年幼的嬰兒。"},{"en":"Infants need careful medical attention because they cannot explain how they feel.","zh":"嬰兒需要仔細醫療照顧，因為他們不能解釋自己的感受。"},{"en":"If a treatment is used with infants, safety and professional guidance become especially important.","zh":"如果治療用於嬰兒，安全和專業指導就尤其重要。"},{"en":"The word refers to babies in the earliest stage of life.","zh":"這個字指人生最早階段的嬰兒。"}],"source":"71 - Homeopathy.pdf","sourcePage":12},{"front":"controlled clinical studies","meaning":"受控臨床研究","examples":[{"en":"The passage refers to controlled clinical studies on homeopathy.","zh":"文章提到關於順勢療法的受控臨床研究。"},{"en":"Controlled clinical studies are medical studies that compare treatment effects under organised conditions.","zh":"controlled clinical studies 是在有組織條件下比較治療效果的醫學研究。"},{"en":"A controlled clinical study may compare one group receiving treatment with another group receiving a placebo.","zh":"受控臨床研究可能比較接受治療的一組和接受安慰劑的另一組。"},{"en":"If a treatment is tested in controlled clinical studies, researchers can reduce bias more effectively.","zh":"如果治療在受控臨床研究中被測試，研究人員能更有效減少偏差。"},{"en":"The phrase describes formal research with comparison and control.","zh":"這個短語描述有比較和控制的正式研究。"}],"source":"71 - Homeopathy.pdf","sourcePage":13},{"front":"performed by","meaning":"由……進行","examples":[{"en":"The studies were performed by medical researchers.","zh":"這些研究由醫學研究人員進行。"},{"en":"Performed by means carried out or done by a person or group.","zh":"performed by 指由某人或某群體執行或完成。"},{"en":"The school survey was performed by teachers who wanted to improve lessons.","zh":"學校調查由想改善課堂的老師進行。"},{"en":"If a test is performed by trained researchers, readers may trust the method more.","zh":"如果測試由受訓研究人員進行，讀者可能更信任方法。"},{"en":"The phrase identifies who carried out an action.","zh":"這個短語指出誰執行某行動。"}],"source":"71 - Homeopathy.pdf","sourcePage":13},{"front":"medical researchers","meaning":"醫學研究人員","examples":[{"en":"Medical researchers performed controlled clinical studies.","zh":"醫學研究人員進行受控臨床研究。"},{"en":"Medical researchers are people who study health, illness, treatments, and patient outcomes.","zh":"medical researchers 是研究健康、疾病、治療和病人結果的人。"},{"en":"Medical researchers may work in universities, hospitals, or laboratories.","zh":"醫學研究人員可能在大學、醫院或實驗室工作。"},{"en":"If medical researchers study a treatment carefully, their findings can guide doctors and patients.","zh":"如果醫學研究人員仔細研究某治療，其發現可以指導醫生和病人。"},{"en":"The phrase identifies professionals who investigate medical questions.","zh":"這個短語指出調查醫學問題的專業人士。"}],"source":"71 - Homeopathy.pdf","sourcePage":13},{"front":"demonstrate that","meaning":"證明；顯示","examples":[{"en":"The passage claims that studies demonstrate the effectiveness of homeopathy.","zh":"文章聲稱研究證明順勢療法的成效。"},{"en":"To demonstrate that something is true means to show it through evidence or example.","zh":"demonstrate that 某事為真，指透過證據或例子顯示它。"},{"en":"A teacher may demonstrate that practice improves writing by comparing early and later essays.","zh":"老師可能透過比較早期和後期文章，證明練習能改善寫作。"},{"en":"If a study demonstrates an effect, readers expect clear data and a fair method.","zh":"如果研究證明某效果，讀者會期待清楚數據和公平方法。"},{"en":"The phrase introduces evidence meant to prove a point.","zh":"這個短語引出用來證明觀點的證據。"}],"source":"71 - Homeopathy.pdf","sourcePage":13},{"front":"method of treatment","meaning":"治療方法","examples":[{"en":"The passage presents homeopathy as a method of treatment.","zh":"文章把順勢療法呈現為一種治療方法。"},{"en":"A method of treatment is a way of trying to manage, reduce, or cure illness.","zh":"method of treatment 是嘗試管理、減輕或治癒疾病的方法。"},{"en":"Exercise may be part of a method of treatment for some long-term health problems.","zh":"對某些長期健康問題而言，運動可能是治療方法的一部分。"},{"en":"If a method of treatment is chosen, patients should understand its purpose and limits.","zh":"如果選擇某治療方法，病人應理解其目的和限制。"},{"en":"The phrase refers to how a health problem is dealt with.","zh":"這個短語指如何處理健康問題。"}],"source":"71 - Homeopathy.pdf","sourcePage":13},{"front":"the most important part of","meaning":"……最重要的部分","examples":[{"en":"The most important part of homeopathic treatment is the interview.","zh":"順勢療法治療最重要的部分是面談。"},{"en":"The most important part of something is the element that matters most to its success.","zh":"the most important part of 某事，是對其成功最重要的元素。"},{"en":"The most important part of exam preparation may be correcting mistakes, not only doing more questions.","zh":"考試準備最重要的部分可能是改正錯誤，而不只是做更多題目。"},{"en":"If one part is the most important, people should spend enough time on it.","zh":"如果某部分最重要，人們應花足夠時間在它上面。"},{"en":"The phrase ranks one element above the others.","zh":"這個短語把一個元素排在其他元素之上。"}],"source":"71 - Homeopathy.pdf","sourcePage":13},{"front":"lie in","meaning":"在於","examples":[{"en":"The most important part of the treatment lies in the lengthy interview.","zh":"治療最重要的部分在於長時間面談。"},{"en":"To lie in something means to be found mainly in that thing.","zh":"lie in 某事，指主要存在於該事物之中。"},{"en":"The value of a good lesson lies in clear explanation and useful practice.","zh":"好課堂的價值在於清楚解釋和有用練習。"},{"en":"If the answer lies in careful listening, rushing to speak may not help.","zh":"如果答案在於仔細聆聽，急着說話未必有幫助。"},{"en":"The phrase identifies where the main importance or solution is found.","zh":"這個短語指出主要重要性或解決方法在哪裏。"}],"source":"71 - Homeopathy.pdf","sourcePage":13},{"front":"lengthy interview","meaning":"長時間面談","examples":[{"en":"The homeopath conducts a lengthy interview with the patient.","zh":"順勢療法師與病人進行長時間面談。"},{"en":"A lengthy interview is a long conversation used to gather detailed information.","zh":"lengthy interview 是用來收集詳細資料的長時間對話。"},{"en":"A school counsellor may conduct a lengthy interview to understand a student’s stress.","zh":"學校輔導員可能進行長時間面談，以理解學生壓力。"},{"en":"If an interview is lengthy, it can reveal patterns that a short question form misses.","zh":"如果面談很長，它可以揭示短問卷錯過的模式。"},{"en":"The phrase suggests detailed discussion, not a quick chat.","zh":"這個短語暗示詳細討論，而不是快速閒聊。"}],"source":"71 - Homeopathy.pdf","sourcePage":13},{"front":"homeopath","meaning":"順勢療法師","examples":[{"en":"The homeopath interviews the patient before choosing a remedy.","zh":"順勢療法師在選擇療劑前會面談病人。"},{"en":"A homeopath is a practitioner who uses homeopathy.","zh":"homeopath 是使用順勢療法的從業者。"},{"en":"A homeopath may ask about sleep, mood, pain, fears, habits, and past illnesses.","zh":"順勢療法師可能詢問睡眠、心情、疼痛、恐懼、習慣和過往疾病。"},{"en":"If a homeopath chooses a remedy, the choice is usually based on a symptom match.","zh":"如果順勢療法師選擇療劑，該選擇通常根據症狀配對。"},{"en":"The word refers to the practitioner, not the treatment itself.","zh":"這個字指從業者，而不是治療本身。"}],"source":"71 - Homeopathy.pdf","sourcePage":13},{"front":"conduct an interview with","meaning":"與……進行面談","examples":[{"en":"The homeopath conducts an interview with the patient.","zh":"順勢療法師與病人進行面談。"},{"en":"To conduct an interview with someone means to ask questions in an organised way.","zh":"conduct an interview with 某人，指有組織地向對方提問。"},{"en":"A manager may conduct an interview with a job applicant before hiring.","zh":"經理可能在聘請前與求職者進行面談。"},{"en":"If a practitioner conducts an interview carefully, she can gather more useful information.","zh":"如果從業者仔細進行面談，她可以收集更多有用資料。"},{"en":"The phrase describes a formal question-and-answer process.","zh":"這個短語描述正式問答過程。"}],"source":"71 - Homeopathy.pdf","sourcePage":13},{"front":"one- to two-hour consultation","meaning":"一至兩小時的診症","examples":[{"en":"The consultation usually lasts one to two hours.","zh":"診症通常持續一至兩小時。"},{"en":"A one- to two-hour consultation is an appointment lasting between one and two hours.","zh":"one- to two-hour consultation 是持續一至兩小時的預約診症或諮詢。"},{"en":"A tutor may offer a one- to two-hour consultation to understand a student’s writing problems.","zh":"導師可能提供一至兩小時諮詢，以了解學生寫作問題。"},{"en":"If a consultation lasts one to two hours, the practitioner can ask detailed questions.","zh":"如果診症持續一至兩小時，從業者可以提出詳細問題。"},{"en":"The phrase gives the usual length of a professional meeting.","zh":"這個短語給出專業會面的通常長度。"}],"source":"71 - Homeopathy.pdf","sourcePage":14},{"front":"build up a history of","meaning":"建立……的病歷","examples":[{"en":"The consultation is used to build up a history of the patient.","zh":"診症用來建立病人的病歷。"},{"en":"To build up a history of someone means to collect detailed background information over time or through questioning.","zh":"build up a history of 某人，指透過時間或提問收集詳細背景資料。"},{"en":"A doctor builds up a history of a patient by asking about past illnesses and family health.","zh":"醫生透過詢問過往疾病和家族健康來建立病人病歷。"},{"en":"If a practitioner builds up a full history, hidden patterns may become clearer.","zh":"如果從業者建立完整病歷，隱藏模式可能變得更清楚。"},{"en":"The phrase describes gradually gathering a case background.","zh":"這個短語描述逐步收集個案背景。"}],"source":"71 - Homeopathy.pdf","sourcePage":14},{"front":"psychological, emotional and physical history","meaning":"心理、情緒和身體病歷","examples":[{"en":"The homeopath builds up a psychological, emotional and physical history of the patient.","zh":"順勢療法師建立病人的心理、情緒和身體病歷。"},{"en":"Psychological, emotional and physical history includes a person’s thoughts, feelings, body symptoms, and past health.","zh":"psychological, emotional and physical history 包括一個人的思想、感受、身體症狀和過往健康。"},{"en":"A counsellor may ask about psychological, emotional and physical history to understand stress fully.","zh":"輔導員可能詢問心理、情緒和身體病歷，以全面理解壓力。"},{"en":"If a patient’s history includes all three areas, the practitioner receives a broader picture.","zh":"如果病歷包括三個範疇，從業者就得到更廣闊圖像。"},{"en":"The phrase shows that the interview covers mind, feelings, and body.","zh":"這個短語顯示面談涵蓋思想、感受和身體。"}],"source":"71 - Homeopathy.pdf","sourcePage":14},{"front":"underlying patterns of disease","meaning":"疾病的潛在模式","examples":[{"en":"The homeopath tries to discover the underlying patterns of disease.","zh":"順勢療法師嘗試發現疾病的潛在模式。"},{"en":"Underlying patterns of disease are deeper repeated links behind a person’s symptoms.","zh":"underlying patterns of disease 是一個人症狀背後更深層、反覆出現的聯繫。"},{"en":"A doctor may look for underlying patterns when headaches, sleep problems and stress appear together.","zh":"當頭痛、睡眠問題和壓力一起出現時，醫生可能尋找潛在模式。"},{"en":"If underlying patterns are missed, treatment may focus only on surface symptoms.","zh":"如果潛在模式被錯過，治療可能只集中表面症狀。"},{"en":"The phrase points to hidden structure beneath visible illness.","zh":"這個短語指出可見疾病之下的隱藏結構。"}],"source":"71 - Homeopathy.pdf","sourcePage":14},{"front":"decide which medicine to prescribe","meaning":"決定處方哪種藥物","examples":[{"en":"The homeopath decides which medicine to prescribe.","zh":"順勢療法師決定處方哪種藥物。"},{"en":"To decide which medicine to prescribe means to choose the treatment substance to recommend to a patient.","zh":"decide which medicine to prescribe 指選擇向病人建議的治療物質。"},{"en":"A doctor decides which medicine to prescribe after considering symptoms, age, allergies and test results.","zh":"醫生在考慮症狀、年齡、過敏和檢查結果後，決定處方哪種藥物。"},{"en":"If symptoms are unclear, deciding which medicine to prescribe becomes more difficult.","zh":"如果症狀不清楚，決定處方哪種藥物會更困難。"},{"en":"The phrase describes a treatment choice made by a practitioner.","zh":"這個短語描述從業者作出的治療選擇。"}],"source":"71 - Homeopathy.pdf","sourcePage":14},{"front":"based on","meaning":"根據","examples":[{"en":"The medicine is chosen based on the closest match of symptoms.","zh":"藥物根據症狀最接近的配對來選擇。"},{"en":"Based on means decided or built using certain information as the reason.","zh":"based on 指以某些資訊作為理由來決定或建立。"},{"en":"A teacher may group students based on their reading level.","zh":"老師可能根據學生閱讀水平分組。"},{"en":"If a decision is based on weak evidence, the result may be unreliable.","zh":"如果決定根據薄弱證據，結果可能不可靠。"},{"en":"The phrase shows the foundation for a choice.","zh":"這個短語顯示選擇的基礎。"}],"source":"71 - Homeopathy.pdf","sourcePage":14},{"front":"closest match between","meaning":"……之間最接近的配對","examples":[{"en":"The treatment is based on the closest match between two sets of symptoms.","zh":"治療根據兩組症狀之間最接近的配對。"},{"en":"Closest match between two things means the strongest similarity found when they are compared.","zh":"closest match between 兩物，指比較時找到的最強相似性。"},{"en":"A teacher may choose a reading book based on the closest match between the text level and the student’s ability.","zh":"老師可能根據文章水平與學生能力之間最接近的配對來選閱讀書。"},{"en":"If the closest match is poor, the chosen option may not fit the problem well.","zh":"如果最接近的配對仍然很差，所選選項可能不太適合問題。"},{"en":"The phrase focuses on careful comparison.","zh":"這個短語重點在仔細比較。"}],"source":"71 - Homeopathy.pdf","sourcePage":14},{"front":"patient’s symptoms","meaning":"病人的症狀","examples":[{"en":"The homeopath compares the patient’s symptoms with known symptoms.","zh":"順勢療法師把病人的症狀與已知症狀比較。"},{"en":"Patient’s symptoms are the signs or feelings of illness reported or shown by a patient.","zh":"patient’s symptoms 是病人報告或表現出的疾病跡象或感受。"},{"en":"A doctor writes down a patient’s symptoms before ordering tests.","zh":"醫生在安排檢查前會寫下病人的症狀。"},{"en":"If the patient’s symptoms change, the treatment plan may need review.","zh":"如果病人的症狀改變，治療計劃可能需要重新檢視。"},{"en":"The phrase focuses on what the patient is experiencing.","zh":"這個短語重點在病人正在經歷甚麼。"}],"source":"71 - Homeopathy.pdf","sourcePage":14},{"front":"known symptoms","meaning":"已知症狀","examples":[{"en":"The known symptoms are those produced by the medicine in a healthy body.","zh":"已知症狀是該藥物在健康身體中產生的症狀。"},{"en":"Known symptoms are symptoms already observed and recorded.","zh":"known symptoms 是已經被觀察和記錄的症狀。"},{"en":"When a virus spreads, doctors compare new cases with known symptoms.","zh":"當病毒傳播時，醫生會把新個案與已知症狀比較。"},{"en":"If known symptoms match a patient’s condition, diagnosis or treatment decisions may become easier.","zh":"如果已知症狀與病人情況相符，診斷或治療決定可能更容易。"},{"en":"The phrase refers to symptoms that are already documented.","zh":"這個短語指已被記錄下來的症狀。"}],"source":"71 - Homeopathy.pdf","sourcePage":14},{"front":"be elicited by","meaning":"由……引發","examples":[{"en":"The symptoms are elicited by the medicine in a healthy body.","zh":"這些症狀由藥物在健康身體中引發。"},{"en":"To be elicited by something means to be brought out or caused by it.","zh":"be elicited by 某物，指由它帶出或造成。"},{"en":"A child’s smile may be elicited by a kind comment from a teacher.","zh":"老師一句善意評語可能引發孩子的微笑。"},{"en":"If symptoms are elicited by a substance, researchers record them as part of its effect.","zh":"如果症狀由某物質引發，研究人員會把它們記錄為其作用一部分。"},{"en":"The phrase is formal and means “caused or drawn out by.”","zh":"這個短語較正式，意思是「由……造成或引出」。"}],"source":"71 - Homeopathy.pdf","sourcePage":14},{"front":"healthy body","meaning":"健康身體","examples":[{"en":"The medicine is tested by observing symptoms in a healthy body.","zh":"藥物透過觀察它在健康身體中引發的症狀來測試。"},{"en":"A healthy body is a body not affected by the illness being studied.","zh":"healthy body 是沒有受到所研究疾病影響的身體。"},{"en":"Exercise, sleep and balanced food help support a healthy body.","zh":"運動、睡眠和均衡飲食有助維持健康身體。"},{"en":"If a substance affects a healthy body, researchers can observe its direct effects more clearly.","zh":"如果某物質影響健康身體，研究人員可以更清楚觀察其直接作用。"},{"en":"The phrase contrasts a normal body with a diseased body.","zh":"這個短語把正常身體與患病身體作對比。"}],"source":"71 - Homeopathy.pdf","sourcePage":15},{"front":"a single dose","meaning":"單一劑量","examples":[{"en":"A single dose is given for the shortest necessary period.","zh":"單一劑量會在所需最短時間內給予。"},{"en":"A single dose means one measured amount of medicine taken or given once.","zh":"a single dose 指一次服用或給予的一個量度好份量。"},{"en":"A doctor may give a single dose of medicine before deciding whether more is needed.","zh":"醫生可能先給一個單一劑量，再決定是否需要更多。"},{"en":"If a single dose is enough, repeated treatment may not be necessary.","zh":"如果單一劑量已足夠，重複治療可能不必要。"},{"en":"The phrase stresses one amount, not repeated use.","zh":"這個短語強調一次份量，而不是反覆使用。"}],"source":"71 - Homeopathy.pdf","sourcePage":15},{"front":"for the shortest period of time necessary","meaning":"在所需的最短時間內","examples":[{"en":"The remedy is given for the shortest period of time necessary.","zh":"該療劑在所需的最短時間內給予。"},{"en":"For the shortest period of time necessary means only as long as needed, and no longer.","zh":"for the shortest period of time necessary 指只在需要的時間內使用，不再延長。"},{"en":"A teacher may keep students after class for the shortest period necessary to explain a missed point.","zh":"老師可能只在所需最短時間內留學生課後，解釋錯過的重點。"},{"en":"If medicine is used only for the shortest necessary period, unnecessary use may be avoided.","zh":"如果藥物只在所需最短時間內使用，就可避免不必要使用。"},{"en":"The phrase stresses minimum duration.","zh":"這個短語強調最短持續時間。"}],"source":"71 - Homeopathy.pdf","sourcePage":15},{"front":"stimulate the body’s healing power","meaning":"刺激身體自癒能力","examples":[{"en":"The remedy is intended to stimulate the body’s healing power.","zh":"該療劑旨在刺激身體自癒能力。"},{"en":"To stimulate the body’s healing power means to encourage the body to repair itself.","zh":"stimulate the body’s healing power 指鼓勵身體自我修復。"},{"en":"Rest and good nutrition can support the body’s healing process after illness.","zh":"生病後休息和良好營養可以支持身體的康復過程。"},{"en":"If a treatment aims to stimulate healing, it is trying to activate the body rather than simply hide symptoms.","zh":"如果治療旨在刺激自癒，它就是嘗試啟動身體，而不是只隱藏症狀。"},{"en":"The phrase describes encouraging recovery from within the body.","zh":"這個短語描述鼓勵身體內部復原。"}],"source":"71 - Homeopathy.pdf","sourcePage":15},{"front":"concept of homeopathy","meaning":"順勢療法的概念","examples":[{"en":"The passage compares the concept of homeopathy with conventional medicine.","zh":"文章把順勢療法的概念與常規醫學比較。"},{"en":"The concept of homeopathy is the basic idea behind how homeopathy understands and treats illness.","zh":"concept of homeopathy 是順勢療法理解和治療疾病背後的基本想法。"},{"en":"Students may explain the concept of homeopathy by contrasting it with symptom-control medicine.","zh":"學生可能透過把它與控制症狀的藥物作對比來解釋順勢療法的概念。"},{"en":"If a concept is unfamiliar, comparison with a known system can make it clearer.","zh":"如果概念不熟悉，與已知體系比較可以令它更清楚。"},{"en":"The phrase refers to the theory, not just the practice.","zh":"這個短語指理論，而不只是做法。"}],"source":"71 - Homeopathy.pdf","sourcePage":15},{"front":"differ from","meaning":"與……不同","examples":[{"en":"Homeopathy differs from conventional medicine.","zh":"順勢療法與常規醫學不同。"},{"en":"To differ from something means to be unlike it in one or more ways.","zh":"differ from 某物，意思是在一個或多個方面與它不同。"},{"en":"Online lessons differ from classroom lessons because students need more self-discipline.","zh":"網課與課室課不同，因為學生需要更多自律。"},{"en":"If two treatments differ from each other, patients should understand the difference before choosing.","zh":"如果兩種治療彼此不同，病人在選擇前應理解分別。"},{"en":"The phrase introduces contrast.","zh":"這個短語引出對比。"}],"source":"71 - Homeopathy.pdf","sourcePage":15},{"front":"conventional medicine","meaning":"常規醫學","examples":[{"en":"The passage contrasts homeopathy with conventional medicine.","zh":"文章把順勢療法與常規醫學作對比。"},{"en":"Conventional medicine is mainstream medical practice based on established diagnosis, drugs, surgery, and clinical evidence.","zh":"conventional medicine 是建基於既定診斷、藥物、手術和臨床證據的主流醫學。"},{"en":"A person with chest pain should seek conventional medical care urgently.","zh":"胸痛的人應緊急尋求常規醫療護理。"},{"en":"If conventional medicine controls symptoms with regular medication, homeopathy is described as aiming at cure.","zh":"如果常規醫學透過定期用藥控制症狀，文章則把順勢療法描述為以治癒為目標。"},{"en":"The phrase refers to standard medicine used by most hospitals and doctors.","zh":"這個短語指大多數醫院和醫生使用的標準醫學。"}],"source":"71 - Homeopathy.pdf","sourcePage":15},{"front":"attempt to stimulate","meaning":"嘗試刺激","examples":[{"en":"Homeopathy attempts to stimulate the body to recover itself.","zh":"順勢療法嘗試刺激身體自我康復。"},{"en":"To attempt to stimulate something means to try to encourage it to become active.","zh":"attempt to stimulate 某物，指嘗試鼓勵它變得活躍。"},{"en":"A teacher may attempt to stimulate discussion by asking students a surprising question.","zh":"老師可能透過問一個令人意外的問題，嘗試刺激討論。"},{"en":"If a treatment attempts to stimulate recovery, it aims to trigger the body’s own response.","zh":"如果治療嘗試刺激康復，它旨在引發身體自身反應。"},{"en":"The phrase describes trying to activate a process.","zh":"這個短語描述嘗試啟動一個過程。"}],"source":"71 - Homeopathy.pdf","sourcePage":15},{"front":"recover itself","meaning":"自我康復","examples":[{"en":"Homeopathy attempts to stimulate the body to recover itself.","zh":"順勢療法嘗試刺激身體自我康復。"},{"en":"To recover itself means to heal or return to health through the body’s own processes.","zh":"recover itself 指身體透過自身過程康復或回復健康。"},{"en":"After rest and fluids, the body may recover itself from a mild cold.","zh":"休息和補充水分後，身體可能從輕微感冒中自我康復。"},{"en":"If the body cannot recover itself, medical help may be necessary.","zh":"如果身體不能自我康復，可能需要醫療協助。"},{"en":"The phrase emphasises self-repair rather than outside control only.","zh":"這個短語強調自我修復，而不只是外在控制。"}],"source":"71 - Homeopathy.pdf","sourcePage":15},{"front":"instead of","meaning":"而不是","examples":[{"en":"Homeopathy views symptoms differently instead of treating them only as problems.","zh":"順勢療法以不同方式看待症狀，而不是只把它們當成問題。"},{"en":"Instead of means in place of one thing or action.","zh":"instead of 指用一事或一行動取代另一事或行動。"},{"en":"A student may revise with example sentences instead of memorising word lists only.","zh":"學生可能用例句溫習，而不是只背詞表。"},{"en":"If a doctor asks questions instead of rushing, the patient may feel better understood.","zh":"如果醫生提問而不是急着處理，病人可能感到更被理解。"},{"en":"The phrase creates a clear contrast between two choices.","zh":"這個短語在兩個選擇之間建立清楚對比。"}],"source":"71 - Homeopathy.pdf","sourcePage":15},{"front":"view symptoms as","meaning":"將症狀視為……","examples":[{"en":"Conventional medicine often views symptoms as signs that something is wrong.","zh":"常規醫學常將症狀視為出了問題的跡象。"},{"en":"To view symptoms as something means to interpret them in that way.","zh":"view symptoms as 某物，指以那種方式理解症狀。"},{"en":"A teacher may view repeated lateness as a sign that a student has transport problems.","zh":"老師可能把反覆遲到視為學生有交通問題的跡象。"},{"en":"If symptoms are viewed only as problems, treatment may focus on removing them quickly.","zh":"如果症狀只被視為問題，治療可能集中於快速消除它們。"},{"en":"The phrase describes how symptoms are understood.","zh":"這個短語描述症狀如何被理解。"}],"source":"71 - Homeopathy.pdf","sourcePage":16},{"front":"signs of","meaning":"……的跡象","examples":[{"en":"The homeopath sees symptoms as signs of the body trying to help itself.","zh":"順勢療法師把症狀看作身體嘗試自助的跡象。"},{"en":"Signs of something are clues showing that something is happening.","zh":"signs of 某事，是顯示某事正在發生的線索。"},{"en":"Dark clouds can be signs of heavy rain.","zh":"烏雲可以是大雨的跡象。"},{"en":"If tiredness is a sign of stress, rest and support may be needed.","zh":"如果疲倦是壓力的跡象，可能需要休息和支援。"},{"en":"The phrase links visible evidence with a hidden condition.","zh":"這個短語把可見證據與隱藏情況連繫起來。"}],"source":"71 - Homeopathy.pdf","sourcePage":16},{"front":"attempt to help itself","meaning":"嘗試自助；嘗試自我修復","examples":[{"en":"The body is seen as attempting to help itself.","zh":"身體被視為正在嘗試自我修復。"},{"en":"To attempt to help itself means to try to repair or protect itself.","zh":"attempt to help itself 指嘗試修復或保護自己。"},{"en":"A cut forms a scab when the skin attempts to help itself heal.","zh":"皮膚嘗試自我修復時，傷口會形成痂。"},{"en":"If symptoms are seen as the body trying to help itself, they are interpreted differently.","zh":"如果症狀被視為身體嘗試自助，它們就會被不同地理解。"},{"en":"The phrase describes self-protection or self-repair.","zh":"這個短語描述自我保護或自我修復。"}],"source":"71 - Homeopathy.pdf","sourcePage":16},{"front":"basic difference between","meaning":"……之間的基本分別","examples":[{"en":"The passage explains a basic difference between homeopathy and conventional therapy.","zh":"文章解釋順勢療法與常規治療之間的基本分別。"},{"en":"A basic difference between two things is a simple but important way they are not the same.","zh":"basic difference between 兩物，是兩者之間簡單但重要的不同之處。"},{"en":"A basic difference between speaking and writing is that writing can be revised before others read it.","zh":"口語和寫作之間的基本分別是寫作可以在別人閱讀前修改。"},{"en":"If students understand the basic difference between two systems, comparison questions become easier.","zh":"如果學生理解兩個系統之間的基本分別，比較題就會更容易。"},{"en":"The phrase introduces a central contrast.","zh":"這個短語引出核心對比。"}],"source":"71 - Homeopathy.pdf","sourcePage":16},{"front":"medical therapy","meaning":"醫學治療","examples":[{"en":"The role of medication differs in conventional medical therapy and homeopathy.","zh":"藥物的作用在常規醫學治療和順勢療法中不同。"},{"en":"Medical therapy is treatment used to manage or cure a health condition.","zh":"medical therapy 是用於管理或治癒健康問題的治療。"},{"en":"Medical therapy for a long-term illness may include medicine, monitoring, and lifestyle advice.","zh":"長期疾病的醫學治療可能包括藥物、監察和生活方式建議。"},{"en":"If medical therapy only controls symptoms, the underlying illness may still remain.","zh":"如果醫學治療只控制症狀，潛在疾病可能仍然存在。"},{"en":"The phrase refers to treatment in a medical context.","zh":"這個短語指醫學語境中的治療。"}],"source":"71 - Homeopathy.pdf","sourcePage":16},{"front":"role of medication","meaning":"藥物的作用","examples":[{"en":"The role of medication is different in the two systems.","zh":"藥物的作用在兩個系統中不同。"},{"en":"The role of medication means what medicine is expected to do in treatment.","zh":"role of medication 指藥物在治療中被期望做甚麼。"},{"en":"In some illnesses, the role of medication is to control pain while the body heals.","zh":"在某些疾病中，藥物的作用是在身體康復時控制痛楚。"},{"en":"If the role of medication is misunderstood, patients may expect more than it can provide.","zh":"如果藥物的作用被誤解，病人可能期待超出其能力的效果。"},{"en":"The phrase focuses on the purpose of medicine.","zh":"這個短語重點在藥物的目的。"}],"source":"71 - Homeopathy.pdf","sourcePage":16},{"front":"be controlled through","meaning":"透過……控制","examples":[{"en":"In conventional therapy, illness may be controlled through regular medication.","zh":"在常規治療中，疾病可能透過定期用藥控制。"},{"en":"To be controlled through something means to be managed by using that method.","zh":"be controlled through 某方法，指透過使用該方法來管理。"},{"en":"Classroom noise can be controlled through clear rules and consistent routines.","zh":"課室噪音可以透過清晰規則和穩定流程控制。"},{"en":"If a disease is controlled through medicine, symptoms may improve while treatment continues.","zh":"如果疾病透過藥物控制，症狀可能在治療持續時改善。"},{"en":"The phrase describes a method of management.","zh":"這個短語描述管理方法。"}],"source":"71 - Homeopathy.pdf","sourcePage":16},{"front":"regular use of","meaning":"定期使用","examples":[{"en":"Some illnesses are controlled through regular use of medical substances.","zh":"一些疾病透過定期使用醫學藥物控制。"},{"en":"Regular use of something means using it repeatedly according to a routine.","zh":"regular use of 某物，指按照固定習慣反覆使用它。"},{"en":"Regular use of a planner can help students remember homework deadlines.","zh":"定期使用計劃本可以幫助學生記住功課期限。"},{"en":"If medicine requires regular use, missing doses may reduce its effect.","zh":"如果藥物需要定期使用，漏服可能減弱效果。"},{"en":"The phrase stresses repeated use, not a one-time action.","zh":"這個短語強調反覆使用，而不是一次性行動。"}],"source":"71 - Homeopathy.pdf","sourcePage":16},{"front":"medical substances","meaning":"醫學藥物","examples":[{"en":"Conventional treatment may rely on medical substances.","zh":"常規治療可能依賴醫學藥物。"},{"en":"Medical substances are materials used as medicines or treatments.","zh":"medical substances 是用作藥物或治療的材料。"},{"en":"A hospital stores medical substances carefully so they remain safe and effective.","zh":"醫院小心儲存醫學藥物，使其保持安全和有效。"},{"en":"If medical substances are used regularly, dosage and side effects must be monitored.","zh":"如果醫學藥物被定期使用，劑量和副作用必須被監察。"},{"en":"The phrase refers to substances used for medical purposes.","zh":"這個短語指用於醫學目的的物質。"}],"source":"71 - Homeopathy.pdf","sourcePage":16},{"front":"be withdrawn","meaning":"被停用","examples":[{"en":"If the medication is withdrawn, the illness may return.","zh":"如果藥物被停用，疾病可能復發。"},{"en":"To be withdrawn means to be stopped, removed, or no longer given.","zh":"be withdrawn 指被停止、移除或不再給予。"},{"en":"A school rule may be withdrawn if it causes more problems than it solves.","zh":"如果校規造成的問題多於解決的問題，它可能被撤回。"},{"en":"If regular medicine is withdrawn suddenly, symptoms may come back or worsen.","zh":"如果定期藥物突然被停用，症狀可能回來或惡化。"},{"en":"The phrase describes stopping something that was previously provided.","zh":"這個短語描述停止先前提供的東西。"}],"source":"71 - Homeopathy.pdf","sourcePage":16},{"front":"high blood pressure","meaning":"高血壓","examples":[{"en":"A person may take a pill every day for high blood pressure.","zh":"一個人可能每天為高血壓服用一粒藥。"},{"en":"High blood pressure is a condition in which blood pushes too strongly against artery walls.","zh":"high blood pressure 是血液對動脈壁壓力過高的情況。"},{"en":"A doctor may check high blood pressure during a routine health examination.","zh":"醫生可能在例行健康檢查中檢查高血壓。"},{"en":"If high blood pressure is not managed, it can increase health risks over time.","zh":"如果高血壓沒有被管理，長遠可能增加健康風險。"},{"en":"The phrase names a common long-term health condition.","zh":"這個短語指出一種常見長期健康狀況。"}],"source":"71 - Homeopathy.pdf","sourcePage":17},{"front":"undergo a cure","meaning":"接受治癒","examples":[{"en":"The passage says that controlling symptoms is not the same as undergoing a cure.","zh":"文章說控制症狀不等於接受治癒。"},{"en":"To undergo a cure means to experience treatment that removes the illness completely.","zh":"undergo a cure 指經歷能完全消除疾病的治療。"},{"en":"A patient may control pain for years without undergoing a cure for the underlying condition.","zh":"病人可能多年控制痛楚，但沒有接受潛在病症的治癒。"},{"en":"If someone undergoes a cure, the illness should no longer need constant control.","zh":"如果某人接受治癒，疾病應不再需要持續控制。"},{"en":"The phrase contrasts cure with symptom management.","zh":"這個短語把治癒與症狀管理作對比。"}],"source":"71 - Homeopathy.pdf","sourcePage":17},{"front":"control symptoms","meaning":"控制症狀","examples":[{"en":"Some medicines control symptoms without curing the illness.","zh":"有些藥物控制症狀，但沒有治癒疾病。"},{"en":"To control symptoms means to reduce or manage signs of illness.","zh":"control symptoms 指減輕或管理疾病跡象。"},{"en":"A painkiller may control symptoms of a headache while the cause remains unclear.","zh":"止痛藥可能控制頭痛症狀，但原因仍不清楚。"},{"en":"If a treatment only controls symptoms, the problem may return when the treatment stops.","zh":"如果治療只控制症狀，治療停止時問題可能回來。"},{"en":"The phrase focuses on managing what the patient feels or shows.","zh":"這個短語重點在管理病人感到或表現出的情況。"}],"source":"71 - Homeopathy.pdf","sourcePage":17},{"front":"aim is the cure","meaning":"目標是治癒","examples":[{"en":"Homeopathy’s stated aim is the cure.","zh":"順勢療法所聲稱的目標是治癒。"},{"en":"If the aim is the cure, the goal is complete recovery rather than temporary control.","zh":"如果 aim is the cure，目標是完全康復，而不是暫時控制。"},{"en":"A school support plan may aim at real improvement, not only hiding poor test results.","zh":"學校支援計劃可能以真正改善為目標，而不只是掩蓋差測驗成績。"},{"en":"If a treatment says its aim is the cure, readers may ask how cure is defined and measured.","zh":"如果一種治療說其目標是治癒，讀者可能會問治癒如何被定義和量度。"},{"en":"The phrase identifies the final goal of treatment.","zh":"這個短語指出治療的最終目標。"}],"source":"71 - Homeopathy.pdf","sourcePage":17},{"front":"complete restoration of","meaning":"完全恢復……","examples":[{"en":"Hahnemann described the aim as the complete restoration of perfect health.","zh":"Hahnemann 把目標描述為完全恢復完美健康。"},{"en":"Complete restoration of something means bringing it fully back to its ideal or previous state.","zh":"complete restoration of 某物，指把它完全恢復到理想或先前狀態。"},{"en":"After a flood, a school may need complete restoration of classrooms, books and equipment.","zh":"水災後，學校可能需要完全恢復課室、書本和設備。"},{"en":"If health is completely restored, the person is not merely feeling slightly better.","zh":"如果健康完全恢復，該人不只是感覺稍微好一點。"},{"en":"The phrase stresses full recovery, not partial repair.","zh":"這個短語強調完全康復，而不是部分修復。"}],"source":"71 - Homeopathy.pdf","sourcePage":17},{"front":"perfect health","meaning":"完美健康","examples":[{"en":"Homeopathy aims at the complete restoration of perfect health.","zh":"順勢療法旨在完全恢復完美健康。"},{"en":"Perfect health means an ideal state of complete physical and mental well-being.","zh":"perfect health 指身體和心理完全良好的理想狀態。"},{"en":"No student can study well forever without rest, because perfect health needs balance.","zh":"沒有學生可以永遠不休息仍學得好，因為完美健康需要平衡。"},{"en":"If a treatment promises perfect health, people should ask what that means in practical terms.","zh":"如果治療承諾完美健康，人們應問這在實際上是甚麼意思。"},{"en":"The phrase describes an ideal, not an everyday condition most people fully reach.","zh":"這個短語描述理想，而不是大多數人完全達到的日常狀態。"}],"source":"71 - Homeopathy.pdf","sourcePage":17},{"front":"make significant progress in","meaning":"在……方面取得重大進展","examples":[{"en":"The passage claims that homeopathy has made significant progress in treating some diseases.","zh":"文章聲稱順勢療法在治療某些疾病方面取得重大進展。"},{"en":"To make significant progress in something means to improve greatly in that area.","zh":"make significant progress in 某方面，指在該方面有重大改善。"},{"en":"A student can make significant progress in writing after months of detailed feedback.","zh":"學生經過數月詳細回饋後，可以在寫作方面取得重大進展。"},{"en":"If researchers make significant progress in treatment, patients may gain better options.","zh":"如果研究人員在治療方面取得重大進展，病人可能得到更好選擇。"},{"en":"The phrase describes meaningful improvement, not a tiny change.","zh":"這個短語描述有意義的改善，而不是小小變化。"}],"source":"71 - Homeopathy.pdf","sourcePage":17},{"front":"treating diseases","meaning":"治療疾病","examples":[{"en":"The passage discusses homeopathy’s role in treating diseases.","zh":"文章討論順勢療法在治療疾病中的角色。"},{"en":"Treating diseases means trying to manage, reduce, or cure illnesses.","zh":"treating diseases 指嘗試管理、減輕或治癒疾病。"},{"en":"Doctors need accurate diagnosis before treating diseases effectively.","zh":"醫生需要準確診斷，才能有效治療疾病。"},{"en":"If diseases are treated late, recovery may become more difficult.","zh":"如果疾病治療得太遲，康復可能變得更困難。"},{"en":"The phrase describes medical action against illness.","zh":"這個短語描述針對疾病的醫療行動。"}],"source":"71 - Homeopathy.pdf","sourcePage":17},{"front":"orthodox medicine","meaning":"正統醫學","examples":[{"en":"The passage contrasts homeopathy with orthodox medicine.","zh":"文章把順勢療法與正統醫學作對比。"},{"en":"Orthodox medicine means mainstream, conventional medical practice.","zh":"orthodox medicine 指主流、常規醫學實踐。"},{"en":"A hospital usually provides orthodox medicine through doctors, nurses, drugs, surgery and tests.","zh":"醫院通常透過醫生、護士、藥物、手術和檢查提供正統醫學。"},{"en":"If orthodox medicine finds a condition difficult to treat, patients may look for additional support.","zh":"如果正統醫學覺得某病難以治療，病人可能尋找額外支援。"},{"en":"The phrase is similar to conventional medicine in this passage.","zh":"在這篇文章中，這個短語與 conventional medicine 相似。"}],"source":"71 - Homeopathy.pdf","sourcePage":17},{"front":"find difficult","meaning":"覺得困難","examples":[{"en":"Homeopathy is said to treat diseases that orthodox medicine finds difficult.","zh":"文章說順勢療法治療正統醫學覺得困難的疾病。"},{"en":"To find something difficult means to experience it as hard to do or solve.","zh":"find something difficult 指覺得某事很難做或解決。"},{"en":"Many students find listening difficult when speakers talk quickly.","zh":"當說話者語速很快，許多學生覺得聆聽困難。"},{"en":"If doctors find a disease difficult to treat, research may focus on better methods.","zh":"如果醫生覺得某疾病難治，研究可能集中於更好方法。"},{"en":"The phrase describes difficulty from the point of view of a person or group.","zh":"這個短語描述某人或某群體角度上的困難。"}],"source":"71 - Homeopathy.pdf","sourcePage":17},{"front":"be best at dealing with","meaning":"最擅長處理……","examples":[{"en":"The passage claims that homeopathy is best at dealing with inflammatory conditions.","zh":"文章聲稱順勢療法最擅長處理炎症性疾病。"},{"en":"To be best at dealing with something means to be most effective or suitable for that problem.","zh":"be best at dealing with 某事，指對該問題最有效或最適合。"},{"en":"Some teachers are best at dealing with nervous beginners because they explain slowly.","zh":"有些老師最擅長處理緊張初學者，因為他們解釋得慢。"},{"en":"If a treatment is best at dealing with one type of condition, it may not suit every illness.","zh":"如果某治療最擅長處理一類病症，它未必適合每種疾病。"},{"en":"The phrase describes a strongest area of usefulness.","zh":"這個短語描述最有用的範疇。"}],"source":"71 - Homeopathy.pdf","sourcePage":18},{"front":"inflammatory conditions","meaning":"炎症性疾病","examples":[{"en":"The passage says homeopathy is used for inflammatory conditions.","zh":"文章說順勢療法用於炎症性疾病。"},{"en":"Inflammatory conditions are health problems involving inflammation, such as swelling, pain or redness.","zh":"inflammatory conditions 是涉及發炎的健康問題，例如腫脹、疼痛或發紅。"},{"en":"A doctor may look for inflammatory conditions when a joint becomes swollen and painful.","zh":"當關節腫脹和疼痛時，醫生可能尋找炎症性疾病。"},{"en":"If inflammatory conditions continue, daily movement and comfort may be affected.","zh":"如果炎症性疾病持續，日常活動和舒適度可能受影響。"},{"en":"The phrase names a broad type of medical problem.","zh":"這個短語指出一大類醫學問題。"}],"source":"71 - Homeopathy.pdf","sourcePage":18},{"front":"arthritis","meaning":"關節炎","examples":[{"en":"Arthritis is listed as an inflammatory condition.","zh":"關節炎被列為一種炎症性疾病。"},{"en":"Arthritis is a condition that causes pain, swelling, or stiffness in the joints.","zh":"arthritis 是造成關節疼痛、腫脹或僵硬的疾病。"},{"en":"A person with arthritis may find stairs or long walks difficult.","zh":"患有關節炎的人可能覺得樓梯或長途步行很困難。"},{"en":"If arthritis worsens, daily tasks such as writing or opening jars may become painful.","zh":"如果關節炎惡化，寫字或開瓶等日常工作可能變得疼痛。"},{"en":"The word names a joint-related health condition.","zh":"這個字指出一種與關節相關的健康問題。"}],"source":"71 - Homeopathy.pdf","sourcePage":18},{"front":"skin conditions","meaning":"皮膚病；皮膚問題","examples":[{"en":"Skin conditions are mentioned as possible targets of homeopathic treatment.","zh":"皮膚病被提及為順勢療法治療的可能對象。"},{"en":"Skin conditions are health problems affecting the skin, such as rashes, itching or inflammation.","zh":"skin conditions 是影響皮膚的健康問題，例如皮疹、痕癢或發炎。"},{"en":"A child with a skin condition may scratch often and need medical advice.","zh":"有皮膚問題的孩子可能經常抓癢，並需要醫療建議。"},{"en":"If skin conditions are visible, patients may feel both physical discomfort and embarrassment.","zh":"如果皮膚病可見，病人可能同時感到身體不適和尷尬。"},{"en":"The phrase covers many different skin problems.","zh":"這個短語涵蓋許多不同皮膚問題。"}],"source":"71 - Homeopathy.pdf","sourcePage":18},{"front":"migraines","meaning":"偏頭痛","examples":[{"en":"Migraines are listed among the conditions discussed.","zh":"偏頭痛被列為文中討論的病症之一。"},{"en":"Migraines are severe headaches that may include nausea, light sensitivity, or visual disturbance.","zh":"migraines 是嚴重頭痛，可能包括噁心、怕光或視覺干擾。"},{"en":"A student with migraines may need a dark quiet room during an attack.","zh":"偏頭痛發作的學生可能需要黑暗安靜的房間。"},{"en":"If migraines happen often, they can affect work, study and family life.","zh":"如果偏頭痛經常發生，它可以影響工作、學習和家庭生活。"},{"en":"The word refers to more than an ordinary mild headache.","zh":"這個字指的不只是普通輕微頭痛。"}],"source":"71 - Homeopathy.pdf","sourcePage":18},{"front":"respiratory problems","meaning":"呼吸系統問題","examples":[{"en":"The passage mentions respiratory problems linked to allergies.","zh":"文章提到與過敏有關的呼吸系統問題。"},{"en":"Respiratory problems are health issues affecting breathing or the lungs.","zh":"respiratory problems 是影響呼吸或肺部的健康問題。"},{"en":"A person with respiratory problems may cough, wheeze, or feel short of breath.","zh":"有呼吸系統問題的人可能咳嗽、喘鳴或氣促。"},{"en":"If respiratory problems become severe, medical care should be sought promptly.","zh":"如果呼吸系統問題變得嚴重，應盡快求醫。"},{"en":"The phrase refers to breathing-related conditions.","zh":"這個短語指與呼吸相關的病症。"}],"source":"71 - Homeopathy.pdf","sourcePage":18},{"front":"linked to allergies","meaning":"與過敏有關","examples":[{"en":"The respiratory problems are linked to allergies.","zh":"這些呼吸系統問題與過敏有關。"},{"en":"Linked to allergies means connected with allergic reactions.","zh":"linked to allergies 指與過敏反應有連繫。"},{"en":"Sneezing and itchy eyes may be linked to allergies during spring.","zh":"春天時打噴嚏和眼睛痕癢可能與過敏有關。"},{"en":"If breathing problems are linked to allergies, doctors may ask about dust, pollen or food triggers.","zh":"如果呼吸問題與過敏有關，醫生可能詢問塵埃、花粉或食物誘因。"},{"en":"The phrase shows a connection, not always a single proven cause.","zh":"這個短語顯示連繫，不一定是單一已證明原因。"}],"source":"71 - Homeopathy.pdf","sourcePage":18},{"front":"prove highly successful at","meaning":"在……方面證明非常成功","examples":[{"en":"The passage claims that homeopathy has proved highly successful at treating asthma.","zh":"文章聲稱順勢療法在治療哮喘方面證明非常成功。"},{"en":"To prove highly successful at something means to show very strong success in that area.","zh":"prove highly successful at 某事，指在該方面顯示非常強的成功。"},{"en":"A reading programme may prove highly successful at helping weaker students gain confidence.","zh":"閱讀計劃可能在幫助較弱學生建立信心方面證明非常成功。"},{"en":"If a method is said to prove highly successful, readers may ask what evidence supports that claim.","zh":"如果某方法被說成證明非常成功，讀者可能詢問有甚麼證據支持。"},{"en":"The phrase describes strong claimed achievement.","zh":"這個短語描述強烈的聲稱成就。"}],"source":"71 - Homeopathy.pdf","sourcePage":18},{"front":"asthma","meaning":"哮喘","examples":[{"en":"Asthma is mentioned as a condition treated by homeopathy.","zh":"哮喘被提及為順勢療法治療的一種病症。"},{"en":"Asthma is a breathing condition in which airways become narrow or inflamed.","zh":"asthma 是氣道變窄或發炎的呼吸病症。"},{"en":"A child with asthma may carry an inhaler for sudden breathing difficulty.","zh":"有哮喘的孩子可能隨身帶吸入器，以應付突然呼吸困難。"},{"en":"If asthma is not managed properly, exercise or dust may trigger serious symptoms.","zh":"如果哮喘沒有被妥善管理，運動或塵埃可能引發嚴重症狀。"},{"en":"The word names a common respiratory condition.","zh":"這個字指出一種常見呼吸系統病症。"}],"source":"71 - Homeopathy.pdf","sourcePage":18},{"front":"appropriate treatment for","meaning":"適合……的治療方法","examples":[{"en":"Homeopathy is not described as an appropriate treatment for degenerative diseases.","zh":"順勢療法並未被描述為適合退化性疾病的治療方法。"},{"en":"An appropriate treatment for a condition is a treatment suitable for that condition.","zh":"appropriate treatment for 某病症，是適合該病症的治療方法。"},{"en":"Rest may be an appropriate treatment for mild tiredness, but not for a serious injury.","zh":"休息可能適合輕微疲倦，但不適合嚴重受傷。"},{"en":"If a treatment is not appropriate for a disease, using it alone may delay better care.","zh":"如果治療不適合某疾病，單獨使用它可能延誤更好護理。"},{"en":"The phrase focuses on suitability.","zh":"這個短語重點在適切性。"}],"source":"71 - Homeopathy.pdf","sourcePage":18},{"front":"degenerative diseases","meaning":"退化性疾病","examples":[{"en":"Homeopathy is not an appropriate treatment for degenerative diseases.","zh":"順勢療法並不是適合退化性疾病的治療方法。"},{"en":"Degenerative diseases are illnesses in which body tissues or functions gradually worsen.","zh":"degenerative diseases 是身體組織或功能逐漸惡化的疾病。"},{"en":"A degenerative disease may slowly reduce a person’s movement, breathing or memory.","zh":"退化性疾病可能慢慢削弱一個人的活動能力、呼吸或記憶。"},{"en":"If a disease destroys tissue over time, restoring full function may be difficult.","zh":"如果疾病隨時間破壞組織，完全恢復功能可能很困難。"},{"en":"The phrase refers to conditions that progressively damage the body.","zh":"這個短語指逐步損害身體的病症。"}],"source":"71 - Homeopathy.pdf","sourcePage":19},{"front":"emphysema","meaning":"肺氣腫","examples":[{"en":"Emphysema is given as an example of a degenerative disease.","zh":"肺氣腫被作為退化性疾病的例子。"},{"en":"Emphysema is a lung disease that damages air sacs and makes breathing difficult.","zh":"emphysema 是一種損害肺泡並令呼吸困難的肺病。"},{"en":"A person with emphysema may become short of breath after walking a short distance.","zh":"患有肺氣腫的人可能走短距離後就氣促。"},{"en":"If emphysema destroys lung tissue, treatment may focus on managing symptoms and slowing damage.","zh":"如果肺氣腫破壞肺組織，治療可能集中於管理症狀和減慢損害。"},{"en":"The word names a serious respiratory disease.","zh":"這個字指出一種嚴重呼吸系統疾病。"}],"source":"71 - Homeopathy.pdf","sourcePage":19},{"front":"destroy tissue","meaning":"破壞組織","examples":[{"en":"Homeopathy cannot treat diseases which destroy tissue.","zh":"順勢療法不能治療會破壞組織的疾病。"},{"en":"To destroy tissue means to damage or break down body cells and structures.","zh":"destroy tissue 指損害或分解身體細胞和結構。"},{"en":"A severe burn can destroy tissue and require urgent medical care.","zh":"嚴重燒傷可以破壞組織，並需要緊急醫療護理。"},{"en":"If a disease destroys tissue, simple symptom relief may not repair the lost structure.","zh":"如果疾病破壞組織，簡單緩解症狀未必能修復已失去的結構。"},{"en":"The phrase describes physical damage inside the body.","zh":"這個短語描述身體內部的實質損害。"}],"source":"71 - Homeopathy.pdf","sourcePage":19},{"front":"be beneficial if","meaning":"如果……仍然有益","examples":[{"en":"The passage says homeopathy can still be beneficial if used with other treatments.","zh":"文章說，如果與其他治療一起使用，順勢療法仍然有益。"},{"en":"To be beneficial if something happens means to be helpful under that condition.","zh":"be beneficial if 某事發生，指在該條件下有幫助。"},{"en":"Extra practice is beneficial if students also receive feedback.","zh":"如果學生也得到回饋，額外練習是有益的。"},{"en":"If a treatment is beneficial only with other care, it should not replace necessary medical help.","zh":"如果治療只有與其他護理一起才有益，它不應取代必要醫療協助。"},{"en":"The phrase links usefulness with a condition.","zh":"這個短語把有用性與條件連繫起來。"}],"source":"71 - Homeopathy.pdf","sourcePage":19},{"front":"in combination with","meaning":"與……結合使用","examples":[{"en":"Homeopathy may be used in combination with other treatments.","zh":"順勢療法可以與其他治療結合使用。"},{"en":"In combination with means together with something else.","zh":"in combination with 指與其他東西一起。"},{"en":"A student may use flashcards in combination with speaking practice to learn vocabulary.","zh":"學生可能把詞卡與口語練習結合使用來學詞彙。"},{"en":"If one treatment is used in combination with another, both roles should be clear.","zh":"如果一種治療與另一種治療結合使用，兩者作用應清楚。"},{"en":"The phrase describes two or more things working together.","zh":"這個短語描述兩件或以上事情共同運作。"}],"source":"71 - Homeopathy.pdf","sourcePage":19},{"front":"main advantages of","meaning":"……的主要優點","examples":[{"en":"The passage lists two main advantages of homeopathy.","zh":"文章列出順勢療法的兩個主要優點。"},{"en":"Main advantages of something are its most important benefits.","zh":"main advantages of 某物，是它最重要的好處。"},{"en":"The main advantages of online lessons are flexibility and saved travel time.","zh":"網課的主要優點是靈活和節省交通時間。"},{"en":"If a product’s main advantages are cost and safety, buyers may compare those points first.","zh":"如果產品的主要優點是成本和安全，買家可能先比較那些方面。"},{"en":"The phrase introduces the strongest positive points.","zh":"這個短語引出最強的正面特點。"}],"source":"71 - Homeopathy.pdf","sourcePage":19},{"front":"low cost of","meaning":"……的低成本","examples":[{"en":"One advantage is the low cost of the medications.","zh":"其中一個優點是藥物的低成本。"},{"en":"Low cost of something means it does not require much money.","zh":"low cost of 某物，指它不需要很多金錢。"},{"en":"The low cost of public libraries makes reading available to many families.","zh":"公共圖書館的低成本令許多家庭都能閱讀。"},{"en":"If the cost of a service is low, more people may be able to try it.","zh":"如果服務成本低，更多人可能能夠嘗試。"},{"en":"The phrase focuses on affordability.","zh":"這個短語重點在負擔能力。"}],"source":"71 - Homeopathy.pdf","sourcePage":19},{"front":"medications","meaning":"藥物","examples":[{"en":"The passage discusses the cost of homeopathic medications.","zh":"文章討論順勢療法藥物的成本。"},{"en":"Medications are medicines used to treat, manage, or prevent health problems.","zh":"medications 是用於治療、管理或預防健康問題的藥物。"},{"en":"A patient should tell a doctor about all medications they are taking.","zh":"病人應告訴醫生自己正在服用的所有藥物。"},{"en":"If medications are used incorrectly, they may cause harm or fail to work.","zh":"如果藥物使用不當，可能造成傷害或無效。"},{"en":"The word is a formal term for medicines.","zh":"這個字是 medicines 的較正式說法。"}],"source":"71 - Homeopathy.pdf","sourcePage":19},{"front":"rarity of adverse reactions","meaning":"不良反應少見","examples":[{"en":"The passage identifies the rarity of adverse reactions as an advantage.","zh":"文章把不良反應少見列為一個優點。"},{"en":"Rarity of adverse reactions means harmful reactions happen only rarely.","zh":"rarity of adverse reactions 指有害反應很少發生。"},{"en":"The rarity of serious side effects can make a treatment feel safer to patients.","zh":"嚴重副作用少見可以令治療對病人感覺較安全。"},{"en":"If adverse reactions are rare, doctors still monitor them because rare does not mean impossible.","zh":"如果不良反應少見，醫生仍會監察，因為少見不等於不可能。"},{"en":"The phrase highlights low frequency of harmful responses.","zh":"這個短語突出有害反應頻率低。"}],"source":"71 - Homeopathy.pdf","sourcePage":19},{"front":"adverse reactions","meaning":"不良反應","examples":[{"en":"Homeopathic remedies are said to have few adverse reactions.","zh":"順勢療法藥物被說成不良反應很少。"},{"en":"Adverse reactions are unwanted or harmful responses to a medicine or treatment.","zh":"adverse reactions 是對藥物或治療的不想要或有害反應。"},{"en":"A rash after taking medicine may be an adverse reaction.","zh":"服藥後出現皮疹可能是不良反應。"},{"en":"If adverse reactions appear, patients should seek medical advice promptly.","zh":"如果不良反應出現，病人應盡快尋求醫療建議。"},{"en":"The phrase is a medical term for negative effects.","zh":"這個短語是負面效果的醫學術語。"}],"source":"71 - Homeopathy.pdf","sourcePage":19},{"front":"inexpensive, safe and easy to use","meaning":"價格低廉、安全且易用","examples":[{"en":"The medicines are described as inexpensive, safe and easy to use.","zh":"這些藥物被描述為價格低廉、安全且易用。"},{"en":"Inexpensive, safe and easy to use means low-cost, low-risk, and simple for ordinary people to handle.","zh":"inexpensive, safe and easy to use 指成本低、風險低，而且普通人容易操作。"},{"en":"A home learning app is attractive if it is inexpensive, safe and easy to use.","zh":"如果家中學習應用程式價格低廉、安全且易用，就會很吸引。"},{"en":"If a treatment is truly inexpensive and easy to use, more people may access it.","zh":"如果治療真的便宜且易用，更多人可能接觸到它。"},{"en":"The phrase lists three practical advantages.","zh":"這個短語列出三個實用優點。"}],"source":"71 - Homeopathy.pdf","sourcePage":20},{"front":"handle common illnesses","meaning":"處理常見疾病","examples":[{"en":"People may learn to handle common illnesses themselves.","zh":"人們可能學會自行處理常見疾病。"},{"en":"To handle common illnesses means to manage ordinary minor health problems.","zh":"handle common illnesses 指管理普通輕微健康問題。"},{"en":"Families may handle common illnesses like mild colds by resting and drinking enough water.","zh":"家庭可能透過休息和飲足夠水來處理輕微感冒等常見疾病。"},{"en":"If people can handle simple illnesses safely, clinics may have more time for serious cases.","zh":"如果人們能安全處理簡單疾病，診所可能有更多時間處理嚴重個案。"},{"en":"The phrase does not mean dealing with emergencies without medical help.","zh":"這個短語不表示在沒有醫療協助下處理緊急情況。"}],"source":"71 - Homeopathy.pdf","sourcePage":20},{"front":"seek medical help","meaning":"求醫；尋求醫療協助","examples":[{"en":"People currently seek medical help for many common illnesses.","zh":"人們目前因許多常見疾病而求醫。"},{"en":"To seek medical help means to ask a doctor or health professional for advice or treatment.","zh":"seek medical help 指向醫生或醫療專業人士尋求建議或治療。"},{"en":"A person with chest pain should seek medical help immediately.","zh":"胸痛的人應立即求醫。"},{"en":"If symptoms worsen or do not improve, seeking medical help is safer than guessing.","zh":"如果症狀惡化或沒有改善，尋求醫療協助比猜測更安全。"},{"en":"The phrase describes actively looking for healthcare support.","zh":"這個短語描述主動尋找醫療支援。"}],"source":"71 - Homeopathy.pdf","sourcePage":20},{"front":"resulting savings in costs","meaning":"由此帶來的成本節省","examples":[{"en":"The resulting savings in costs are described as beneficial.","zh":"由此帶來的成本節省被描述為有益。"},{"en":"Resulting savings in costs are money saved because of a previous action or change.","zh":"resulting savings in costs 是因先前行動或轉變而節省下來的金錢。"},{"en":"A school’s switch to digital notices may create resulting savings in printing costs.","zh":"學校改用電子通告可能帶來印刷成本節省。"},{"en":"If people need fewer clinic visits for minor issues, resulting savings in costs may occur.","zh":"如果人們因輕微問題較少去診所，可能由此帶來成本節省。"},{"en":"The phrase links a change with lower spending.","zh":"這個短語把轉變與較低開支連繫起來。"}],"source":"71 - Homeopathy.pdf","sourcePage":20},{"front":"personal independence","meaning":"個人自主","examples":[{"en":"The passage links homeopathy with an increase in personal independence.","zh":"文章把順勢療法與個人自主增加連繫起來。"},{"en":"Personal independence is the ability to make decisions and manage life without relying too much on others.","zh":"personal independence 是能夠作決定和管理生活，而不過度依賴他人的能力。"},{"en":"Learning to cook gives young adults more personal independence.","zh":"學會煮食讓年輕成年人有更多個人自主。"},{"en":"If people can handle simple problems responsibly, their personal independence may increase.","zh":"如果人們能負責任地處理簡單問題，他們的個人自主可能增加。"},{"en":"The phrase describes self-reliance in daily life.","zh":"這個短語描述日常生活中的自立能力。"}],"source":"71 - Homeopathy.pdf","sourcePage":20},{"front":"represent a significant contribution to","meaning":"對……作出重大貢獻","examples":[{"en":"The savings and independence represent a significant contribution to healthcare.","zh":"成本節省和個人自主對醫療保健作出重大貢獻。"},{"en":"To represent a significant contribution to something means to be an important help or addition to it.","zh":"represent a significant contribution to 某事，指對它提供重要幫助或補充。"},{"en":"Volunteer tutors represent a significant contribution to a community education programme.","zh":"義務導師對社區教育計劃作出重大貢獻。"},{"en":"If a change lowers costs and improves access, it may contribute significantly to public services.","zh":"如果轉變降低成本並改善可及性，它可能對公共服務作出重大貢獻。"},{"en":"The phrase describes a meaningful positive effect.","zh":"這個短語描述有意義的正面影響。"}],"source":"71 - Homeopathy.pdf","sourcePage":20},{"front":"healthcare","meaning":"醫療保健","examples":[{"en":"The passage says these benefits contribute to healthcare.","zh":"文章說這些好處對醫療保健有貢獻。"},{"en":"Healthcare means the services, advice, and treatment used to keep people healthy or treat illness.","zh":"healthcare 是用來保持健康或治療疾病的服務、建議和治療。"},{"en":"Good healthcare includes prevention, diagnosis, treatment and follow-up support.","zh":"良好醫療保健包括預防、診斷、治療和跟進支援。"},{"en":"If healthcare becomes too expensive, some people may delay seeking help.","zh":"如果醫療保健變得太昂貴，有些人可能延遲求助。"},{"en":"The word refers to the whole system of caring for health.","zh":"這個字指照顧健康的整個系統。"}],"source":"71 - Homeopathy.pdf","sourcePage":20},{"front":"reading passage","meaning":"閱讀文章","examples":[{"en":"The reading passage has seven sections.","zh":"閱讀文章有七個部分。"},{"en":"A reading passage is a text used for reading practice or examination questions.","zh":"reading passage 是用於閱讀練習或考試題目的文本。"},{"en":"Students should skim the reading passage before answering detailed questions.","zh":"學生回答細節題前應先略讀閱讀文章。"},{"en":"If a reading passage has headings questions, students need to identify each section’s main idea.","zh":"如果閱讀文章有標題題，學生需要找出每部分主旨。"},{"en":"The phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"71 - Homeopathy.pdf","sourcePage":20},{"front":"seven sections","meaning":"七個部分","examples":[{"en":"The reading passage has seven sections.","zh":"閱讀文章有七個部分。"},{"en":"Seven sections means seven separate parts of a text.","zh":"seven sections 指文本中的七個獨立部分。"},{"en":"A report with seven sections may include background, method, results and conclusion.","zh":"有七個部分的報告可能包括背景、方法、結果和結論。"},{"en":"If a passage has seven sections, headings questions may ask students to match each one.","zh":"如果文章有七個部分，標題配對題可能要求學生逐一配對。"},{"en":"The phrase gives the structure of the text.","zh":"這個短語提供文本結構。"}],"source":"71 - Homeopathy.pdf","sourcePage":20},{"front":"choose the most suitable headings","meaning":"選擇最合適的標題","examples":[{"en":"Candidates choose the most suitable headings for the sections.","zh":"考生為各部分選擇最合適的標題。"},{"en":"To choose the most suitable headings means to select the titles that best match each section’s main idea.","zh":"choose the most suitable headings 指選出最符合各部分主旨的標題。"},{"en":"Students should choose the most suitable headings after reading the whole paragraph, not one word only.","zh":"學生應讀完整段後選擇最合適標題，而不是只看一個字。"},{"en":"If two headings seem similar, the main idea decides which is more suitable.","zh":"如果兩個標題看似相似，主旨決定哪個更合適。"},{"en":"The phrase describes a common IELTS-style reading task.","zh":"這個短語描述常見 IELTS 式閱讀題。"}],"source":"71 - Homeopathy.pdf","sourcePage":20},{"front":"list of headings","meaning":"標題列表","examples":[{"en":"The question provides a list of headings.","zh":"題目提供一個標題列表。"},{"en":"A list of headings is a set of possible paragraph or section titles.","zh":"list of headings 是一組可能的段落或部分標題。"},{"en":"In a reading test, students compare the list of headings with each section’s main point.","zh":"在閱讀測驗中，學生把標題列表與每部分主旨比較。"},{"en":"If there are more headings than sections, some options will not be used.","zh":"如果標題多於段落，有些選項不會使用。"},{"en":"The phrase refers to answer choices for a matching task.","zh":"這個短語指配對題的答案選項。"}],"source":"71 - Homeopathy.pdf","sourcePage":21},{"front":"more headings than sections","meaning":"標題多於段落","examples":[{"en":"There are more headings than sections.","zh":"標題多於段落。"},{"en":"More headings than sections means the number of title options is larger than the number of text parts.","zh":"more headings than sections 指標題選項數量多過文本部分數量。"},{"en":"In an exam, more headings than sections makes guessing less reliable.","zh":"在考試中，標題多於段落會令猜測較不可靠。"},{"en":"If there are more headings than sections, students must leave some headings unused.","zh":"如果標題多於段落，學生必須有些標題不用。"},{"en":"The phrase warns candidates that not every option fits.","zh":"這個短語提醒考生不是每個選項都適合。"}],"source":"71 - Homeopathy.pdf","sourcePage":21},{"front":"will not use all of them","meaning":"不會全部使用","examples":[{"en":"Candidates will not use all of the headings.","zh":"考生不會使用所有標題。"},{"en":"Will not use all of them means some options must be left unused.","zh":"will not use all of them 指有些選項必須留空不用。"},{"en":"In a word bank exercise, students may not use all of the words given.","zh":"在詞庫練習中，學生未必會使用所有給出的詞語。"},{"en":"If candidates try to use every heading, they will make wrong matches.","zh":"如果考生試圖使用每個標題，就會配錯。"},{"en":"The phrase prevents students from forcing all choices into answers.","zh":"這個短語防止學生強行把所有選項放進答案。"}],"source":"71 - Homeopathy.pdf","sourcePage":21},{"front":"the future of homeopathy","meaning":"順勢療法的未來","examples":[{"en":"One heading refers to the future of homeopathy.","zh":"一個標題提到順勢療法的未來。"},{"en":"The future of homeopathy means what may happen to homeopathy later.","zh":"the future of homeopathy 指順勢療法之後可能會怎樣發展。"},{"en":"A discussion of the future of online learning may ask whether schools will keep using digital tools.","zh":"關於網上學習未來的討論，可能問學校是否會繼續使用數碼工具。"},{"en":"If interest keeps growing, the future of homeopathy may involve more debate and research.","zh":"如果興趣持續增長，順勢療法的未來可能涉及更多爭論和研究。"},{"en":"The phrase points to possible later development.","zh":"這個短語指向之後可能的發展。"}],"source":"71 - Homeopathy.pdf","sourcePage":21},{"front":"concerns about","meaning":"對……的憂慮","examples":[{"en":"One heading refers to concerns about homeopathy.","zh":"一個標題提到對順勢療法的憂慮。"},{"en":"Concerns about something are worries or doubts related to it.","zh":"concerns about 某事，是與它有關的擔心或疑問。"},{"en":"Parents may have concerns about a new school bus route if it crosses busy roads.","zh":"如果新校巴路線穿過繁忙道路，家長可能對它有憂慮。"},{"en":"If doctors raise concerns about a treatment, patients may ask for more evidence.","zh":"如果醫生提出對某治療的憂慮，病人可能要求更多證據。"},{"en":"The phrase introduces possible problems or doubts.","zh":"這個短語引出可能問題或疑慮。"}],"source":"71 - Homeopathy.pdf","sourcePage":21},{"front":"comparison with","meaning":"與……比較","examples":[{"en":"The question includes a heading about comparison with traditional Western medicine.","zh":"題目包括一個關於與傳統西醫比較的標題。"},{"en":"Comparison with something means looking at similarities and differences between two things.","zh":"comparison with 某物，指觀察兩者之間的相似和不同。"},{"en":"A comparison with last year’s results helps students see improvement.","zh":"與去年成績比較，有助學生看見進步。"},{"en":"If a passage makes a comparison with another system, readers should notice both contrasts and similarities.","zh":"如果文章與另一體系作比較，讀者應注意對比和相似點。"},{"en":"The phrase signals that two things will be set side by side.","zh":"這個短語表示兩件事會被並列比較。"}],"source":"71 - Homeopathy.pdf","sourcePage":21},{"front":"traditional Western medicine","meaning":"傳統西醫","examples":[{"en":"The passage compares homeopathy with traditional Western medicine.","zh":"文章把順勢療法與傳統西醫比較。"},{"en":"Traditional Western medicine refers to mainstream medical practice developed in Western medical systems.","zh":"traditional Western medicine 指在西方醫學體系中發展的主流醫學實踐。"},{"en":"Hospitals usually rely on traditional Western medicine for diagnosis, surgery and drug treatment.","zh":"醫院通常依靠傳統西醫進行診斷、手術和藥物治療。"},{"en":"If a passage contrasts homeopathy with traditional Western medicine, it may compare their views of symptoms.","zh":"如果文章把順勢療法與傳統西醫對比，它可能比較兩者對症狀的看法。"},{"en":"The phrase is used here to mean conventional medicine.","zh":"這個短語在此指常規醫學。"}],"source":"71 - Homeopathy.pdf","sourcePage":21},{"front":"theoretical and experimental basis","meaning":"理論和實驗基礎","examples":[{"en":"The heading refers to the theoretical and experimental basis of homeopathy.","zh":"這個標題指順勢療法的理論和實驗基礎。"},{"en":"Theoretical and experimental basis means the ideas and tests that support a system.","zh":"theoretical and experimental basis 指支持某系統的想法和測試。"},{"en":"A science project needs a theoretical and experimental basis: an idea to test and evidence from testing.","zh":"科學專題需要理論和實驗基礎：一個要測試的想法和來自測試的證據。"},{"en":"If a system lacks an experimental basis, people may question whether it works.","zh":"如果系統缺乏實驗基礎，人們可能質疑它是否有效。"},{"en":"The phrase combines theory with practical investigation.","zh":"這個短語結合理論和實際調查。"}],"source":"71 - Homeopathy.pdf","sourcePage":21},{"front":"revival of homeopathy","meaning":"順勢療法復興","examples":[{"en":"The heading refers to the revival of homeopathy.","zh":"這個標題指順勢療法復興。"},{"en":"Revival of homeopathy means renewed interest in homeopathy after a period of less attention.","zh":"revival of homeopathy 指順勢療法在一段較少受關注時期後重新引起興趣。"},{"en":"The revival of a traditional festival can bring young people back into community life.","zh":"傳統節日復興可以把年輕人重新帶回社區生活。"},{"en":"If homeopathy experiences a revival, more patients and doctors may discuss it again.","zh":"如果順勢療法復興，更多病人和醫生可能再次討論它。"},{"en":"The phrase describes something becoming active or popular again.","zh":"這個短語描述某事重新活躍或流行。"}],"source":"71 - Homeopathy.pdf","sourcePage":21},{"front":"preparation of medicines","meaning":"藥物製備","examples":[{"en":"One heading concerns the preparation of medicines.","zh":"一個標題涉及藥物製備。"},{"en":"Preparation of medicines means the process of making medicines ready for use.","zh":"preparation of medicines 指使藥物準備好可使用的製作過程。"},{"en":"Pharmacists follow rules for the preparation of medicines to avoid mistakes.","zh":"藥劑師遵守藥物製備規則以避免錯誤。"},{"en":"If preparation of medicines is careless, patients may receive the wrong strength or mixture.","zh":"如果藥物製備粗心，病人可能收到錯誤強度或混合物。"},{"en":"The phrase focuses on making and handling medicines before use.","zh":"這個短語重點在使用前製作和處理藥物。"}],"source":"71 - Homeopathy.pdf","sourcePage":21},{"front":"debate over effectiveness","meaning":"關於成效的爭論","examples":[{"en":"The passage includes debate over the effectiveness of homeopathy.","zh":"文章包括關於順勢療法成效的爭論。"},{"en":"Debate over effectiveness is disagreement about whether something works.","zh":"debate over effectiveness 是關於某事是否有效的分歧。"},{"en":"There may be debate over the effectiveness of a new teaching app until test results are clear.","zh":"在測驗結果清楚前，可能會有關於新教學應用程式成效的爭論。"},{"en":"If evidence is mixed, debate over effectiveness can continue for years.","zh":"如果證據不一致，關於成效的爭論可以持續多年。"},{"en":"The phrase describes argument about real results.","zh":"這個短語描述關於實際結果的爭論。"}],"source":"71 - Homeopathy.pdf","sourcePage":22},{"front":"advantages and limitations","meaning":"優點和限制","examples":[{"en":"The final section discusses advantages and limitations of homeopathy.","zh":"最後一部分討論順勢療法的優點和限制。"},{"en":"Advantages and limitations are the strengths and weaknesses of something.","zh":"advantages and limitations 是某事的強項和弱點。"},{"en":"A teacher may explain the advantages and limitations of online dictionaries.","zh":"老師可能解釋網上字典的優點和限制。"},{"en":"If students know both advantages and limitations, their answer becomes more balanced.","zh":"如果學生知道優點和限制，答案會更平衡。"},{"en":"The phrase reminds readers to consider both positive and negative sides.","zh":"這個短語提醒讀者同時考慮正反兩面。"}],"source":"71 - Homeopathy.pdf","sourcePage":22},{"front":"aspects of treatment","meaning":"治療方面","examples":[{"en":"The heading refers to different aspects of treatment.","zh":"這個標題指治療的不同方面。"},{"en":"Aspects of treatment are different parts of how treatment is given or understood.","zh":"aspects of treatment 是治療如何提供或理解的不同部分。"},{"en":"A doctor may explain aspects of treatment such as dosage, side effects and follow-up visits.","zh":"醫生可能解釋治療方面，例如劑量、副作用和覆診。"},{"en":"If patients understand several aspects of treatment, they can ask better questions.","zh":"如果病人理解幾個治療方面，他們可以提出更好的問題。"},{"en":"The phrase breaks a treatment into its important parts.","zh":"這個短語把治療分成重要部分。"}],"source":"71 - Homeopathy.pdf","sourcePage":22},{"front":"complete the description below","meaning":"完成以下描述","examples":[{"en":"Candidates complete the description below using words from the passage.","zh":"考生使用文章中的字詞完成以下描述。"},{"en":"Complete the description below means fill in missing words in the following explanatory text.","zh":"complete the description below 指在下面的說明文字中填入缺失字詞。"},{"en":"In a reading exam, students complete the description below by finding exact words in the article.","zh":"在閱讀考試中，學生透過在文章中找原字完成以下描述。"},{"en":"If students ignore the word limit, a correct idea may still be marked wrong.","zh":"如果學生忽略字數限制，即使意思正確也可能被判錯。"},{"en":"The phrase is an instruction for a gap-filling task.","zh":"這個短語是填空題指示。"}],"source":"71 - Homeopathy.pdf","sourcePage":22},{"front":"NO MORE THAN THREE WORDS","meaning":"不超過三個詞","examples":[{"en":"Candidates choose no more than three words from the passage.","zh":"考生從文章中選擇不超過三個詞。"},{"en":"NO MORE THAN THREE WORDS means the answer may contain one, two, or three words, but not four.","zh":"NO MORE THAN THREE WORDS 指答案可以有一個、兩個或三個英文詞，但不能有四個。"},{"en":"If the correct answer is “alcohol and water,” it fits the no-more-than-three-words rule.","zh":"如果正確答案是 alcohol and water，它就符合不超過三個詞的規則。"},{"en":"If a student writes extra words, the answer may be wrong even if the key word is included.","zh":"如果學生寫了額外字詞，即使包含關鍵詞也可能錯。"},{"en":"The phrase gives a strict answer-length limit.","zh":"這個短語給出嚴格答案長度限制。"}],"source":"71 - Homeopathy.pdf","sourcePage":22},{"front":"making a homeopathic remedy","meaning":"製作順勢療法藥物","examples":[{"en":"The question describes the stages of making a homeopathic remedy.","zh":"題目描述製作順勢療法藥物的階段。"},{"en":"Making a homeopathic remedy means preparing a remedy according to homeopathic steps such as soaking, straining and dilution.","zh":"making a homeopathic remedy 指按照順勢療法步驟製備藥物，例如浸泡、過濾和稀釋。"},{"en":"A student may draw a flow chart to remember the process of making a homeopathic remedy.","zh":"學生可能畫流程圖來記住製作順勢療法藥物的過程。"},{"en":"If one stage is missed, the described preparation process changes.","zh":"如果漏掉一個階段，所描述的製備過程就會改變。"},{"en":"The phrase focuses on the production process of the remedy.","zh":"這個短語重點在療劑的製作過程。"}],"source":"71 - Homeopathy.pdf","sourcePage":22},{"front":"raw material","meaning":"原材料","examples":[{"en":"The raw material comes from a plant, animal or mineral source.","zh":"原材料來自植物、動物或礦物來源。"},{"en":"Raw material is the starting substance used before processing begins.","zh":"raw material 是加工開始前使用的起始物質。"},{"en":"Wheat is the raw material for flour, and cotton is the raw material for many clothes.","zh":"小麥是麵粉的原材料，而棉花是許多衣物的原材料。"},{"en":"If the raw material is poor quality, the final product may also be poor.","zh":"如果原材料質素差，最終產品也可能差。"},{"en":"The phrase points to what something is made from at the beginning.","zh":"這個短語指出某物一開始由甚麼製成。"}],"source":"71 - Homeopathy.pdf","sourcePage":22},{"front":"plant, animal or mineral source","meaning":"植物、動物或礦物來源","examples":[{"en":"A remedy may come from a plant, animal or mineral source.","zh":"療劑可能來自植物、動物或礦物來源。"},{"en":"A plant, animal or mineral source means the material comes from one of those three natural origins.","zh":"plant, animal or mineral source 指材料來自這三種天然來源之一。"},{"en":"A natural product label may state whether it has a plant, animal or mineral source.","zh":"天然產品標籤可能說明它是否有植物、動物或礦物來源。"},{"en":"If a remedy comes from an animal source, some users may want to know before taking it.","zh":"如果療劑來自動物來源，一些使用者可能想在服用前知道。"},{"en":"The phrase classifies where the raw material comes from.","zh":"這個短語分類原材料來自哪裏。"}],"source":"71 - Homeopathy.pdf","sourcePage":22},{"front":"be mixed with","meaning":"與……混合","examples":[{"en":"The raw material is mixed with alcohol and water.","zh":"原材料與酒精和水混合。"},{"en":"To be mixed with something means to be combined with it.","zh":"be mixed with 某物，指與它結合。"},{"en":"Flour is mixed with water to make dough.","zh":"麵粉與水混合來製作麵團。"},{"en":"If a material is mixed with the wrong liquid, the final result may change.","zh":"如果材料與錯誤液體混合，最終結果可能改變。"},{"en":"The phrase describes combining substances.","zh":"這個短語描述結合物質。"}],"source":"71 - Homeopathy.pdf","sourcePage":22},{"front":"left to stand","meaning":"靜置","examples":[{"en":"The mixture is left to stand for two to four weeks.","zh":"該混合物被靜置兩至四星期。"},{"en":"Left to stand means placed aside and allowed to remain still for a period.","zh":"left to stand 指被放在一旁，並在一段時間內保持不動。"},{"en":"Tea may be left to stand for a few minutes so the flavour becomes stronger.","zh":"茶可能被靜置幾分鐘，讓味道更濃。"},{"en":"If a mixture is left to stand, time becomes part of the preparation process.","zh":"如果混合物被靜置，時間就成為製備過程的一部分。"},{"en":"The phrase describes waiting without active use.","zh":"這個短語描述沒有主動使用的等待。"}],"source":"71 - Homeopathy.pdf","sourcePage":22},{"front":"produce a remedy with","meaning":"製作出具有……的藥物","examples":[{"en":"The process produces a remedy with a potency of 1C.","zh":"該過程製作出具有1C效力的藥物。"},{"en":"To produce a remedy with a certain potency means to make a remedy at that stated strength level.","zh":"produce a remedy with 某效力，指製作出達到該標示強度水平的療劑。"},{"en":"A factory may produce a drink with a lower sugar level for children.","zh":"工廠可能為兒童製作出糖分較低的飲品。"},{"en":"If a process produces a remedy with a labelled potency, the label shows its preparation stage.","zh":"如果過程製作出帶有標示效力的療劑，標籤顯示其製備階段。"},{"en":"The phrase connects production with a specific quality of the product.","zh":"這個短語把製作與產品的特定質素連繫起來。"}],"source":"71 - Homeopathy.pdf","sourcePage":23},{"front":"become more diluted","meaning":"變得更稀釋","examples":[{"en":"As the remedy becomes more diluted, the passage says it becomes stronger.","zh":"隨着療劑變得更稀釋，文章說它變得更強。"},{"en":"To become more diluted means to contain more liquid and less of the original substance in each part.","zh":"become more diluted 指每一部分含有更多液體和更少原本物質。"},{"en":"Juice becomes more diluted when extra water is added.","zh":"加入額外水後，果汁會變得更稀釋。"},{"en":"If a mixture becomes more diluted, its concentration usually becomes lower.","zh":"如果混合物變得更稀釋，其濃度通常會降低。"},{"en":"The phrase describes a change in concentration.","zh":"這個短語描述濃度上的變化。"}],"source":"71 - Homeopathy.pdf","sourcePage":23},{"front":"complete the summary","meaning":"完成摘要","examples":[{"en":"Candidates complete the summary using words from the box.","zh":"考生使用方框中的字詞完成摘要。"},{"en":"Complete the summary means fill in missing words in a short version of the passage.","zh":"complete the summary 指在文章簡短版本中填入缺失字詞。"},{"en":"Students complete the summary by understanding the main ideas, not just matching random words.","zh":"學生完成摘要時要理解主旨，而不是隨機配字。"},{"en":"If grammar does not fit, the chosen word is probably wrong.","zh":"如果文法不合，所選詞語很可能錯。"},{"en":"The phrase describes a common reading gap-fill task.","zh":"這個短語描述常見閱讀填空題。"}],"source":"71 - Homeopathy.pdf","sourcePage":23},{"front":"choose answers from","meaning":"從……選擇答案","examples":[{"en":"Candidates choose their answers from the box below.","zh":"考生從下面方框中選擇答案。"},{"en":"To choose answers from a place means to select responses only from the given options.","zh":"choose answers from 某處，指只從給出的選項中選擇答案。"},{"en":"In a vocabulary exercise, students may choose answers from a word bank.","zh":"在詞彙練習中，學生可能從詞庫中選擇答案。"},{"en":"If answers must come from a box, students should not invent new words.","zh":"如果答案必須來自方框，學生不應自創新詞。"},{"en":"The phrase explains the source of possible answers.","zh":"這個短語解釋可能答案的來源。"}],"source":"71 - Homeopathy.pdf","sourcePage":23},{"front":"view of symptoms","meaning":"對症狀的看法","examples":[{"en":"The summary compares each system’s view of symptoms.","zh":"摘要比較每個系統對症狀的看法。"},{"en":"View of symptoms means the way symptoms are understood or interpreted.","zh":"view of symptoms 指症狀被理解或詮釋的方式。"},{"en":"A doctor’s view of symptoms may change after test results arrive.","zh":"醫生對症狀的看法可能在檢查結果出來後改變。"},{"en":"If two medical systems have different views of symptoms, they may choose different treatments.","zh":"如果兩個醫學系統對症狀有不同看法，它們可能選擇不同治療。"},{"en":"The phrase focuses on interpretation, not the symptoms themselves.","zh":"這個短語重點在詮釋，而不是症狀本身。"}],"source":"71 - Homeopathy.pdf","sourcePage":23},{"front":"indications that","meaning":"……的跡象","examples":[{"en":"Conventional medicine views symptoms as indications that something is wrong.","zh":"常規醫學把症狀視為出了問題的跡象。"},{"en":"Indications that something is true are signs suggesting it is true.","zh":"indications that 某事為真，是暗示它為真的跡象。"},{"en":"Falling attendance may be an indication that students are unhappy with the timetable.","zh":"出席率下降可能是學生不滿時間表的跡象。"},{"en":"If symptoms are indications that something is wrong, they act like warning signals.","zh":"如果症狀是出了問題的跡象，它們就像警號。"},{"en":"The phrase introduces what a sign suggests.","zh":"這個短語引出跡象所暗示的事情。"}],"source":"71 - Homeopathy.pdf","sourcePage":23},{"front":"something is wrong","meaning":"出了問題","examples":[{"en":"Symptoms may be viewed as signs that something is wrong.","zh":"症狀可能被視為出了問題的跡象。"},{"en":"Something is wrong means there is a problem that needs attention.","zh":"something is wrong 指有問題需要注意。"},{"en":"If a child suddenly stops eating, parents may think something is wrong.","zh":"如果孩子突然停止進食，父母可能覺得出了問題。"},{"en":"When warning lights appear on a car dashboard, they suggest something is wrong.","zh":"當汽車儀表板出現警告燈，它們暗示出了問題。"},{"en":"The phrase is a general way to say there is a problem.","zh":"這個短語是表示有問題的一般說法。"}],"source":"71 - Homeopathy.pdf","sourcePage":23},{"front":"regard something as","meaning":"將……視為","examples":[{"en":"Homeopathy regards symptoms as signs that the body is trying to help itself.","zh":"順勢療法將症狀視為身體嘗試自助的跡象。"},{"en":"To regard something as something means to consider or interpret it in that way.","zh":"regard something as 某物，指把它看作或理解為那樣。"},{"en":"A teacher may regard mistakes as useful clues about what students need to learn.","zh":"老師可能將錯誤視為學生需要學甚麼的有用線索。"},{"en":"If symptoms are regarded as helpful signals, the treatment approach may change.","zh":"如果症狀被視為有幫助的訊號，治療方法可能改變。"},{"en":"The phrase introduces a way of seeing or judging something.","zh":"這個短語引出看待或判斷某事的方式。"}],"source":"71 - Homeopathy.pdf","sourcePage":23},{"front":"heal itself","meaning":"自我療癒","examples":[{"en":"Homeopathy regards symptoms as signs that the body is attempting to heal itself.","zh":"順勢療法將症狀視為身體正在嘗試自我療癒的跡象。"},{"en":"To heal itself means to repair and recover through the body’s own processes.","zh":"heal itself 指身體透過自身過程修復和康復。"},{"en":"A small cut may heal itself if it is kept clean and protected.","zh":"小傷口如果保持清潔和受保護，可能會自我療癒。"},{"en":"If the body cannot heal itself, professional medical treatment may be needed.","zh":"如果身體不能自我療癒，可能需要專業醫療治療。"},{"en":"The phrase describes natural recovery from within.","zh":"這個短語描述由內而外的自然康復。"}],"source":"71 - Homeopathy.pdf","sourcePage":23},{"front":"conventional medicines","meaning":"常規藥物","examples":[{"en":"Conventional medicines may control symptoms.","zh":"常規藥物可能控制症狀。"},{"en":"Conventional medicines are standard medicines used in mainstream medical treatment.","zh":"conventional medicines 是主流醫學治療中使用的標準藥物。"},{"en":"A doctor may prescribe conventional medicines for infections, pain, or blood pressure.","zh":"醫生可能為感染、疼痛或血壓處方常規藥物。"},{"en":"If conventional medicines control symptoms, patients may feel better while the medicine is working.","zh":"如果常規藥物控制症狀，病人在藥物發揮作用時可能感覺好些。"},{"en":"The phrase contrasts standard drugs with alternative remedies.","zh":"這個短語把標準藥物與另類療劑作對比。"}],"source":"71 - Homeopathy.pdf","sourcePage":23},{"front":"control symptoms","meaning":"控制症狀","examples":[{"en":"Many conventional medicines control symptoms.","zh":"許多常規藥物控制症狀。"},{"en":"To control symptoms means to reduce, manage, or keep signs of illness under control.","zh":"control symptoms 指減輕、管理或控制疾病跡象。"},{"en":"A cough medicine may control symptoms so a patient can sleep better.","zh":"咳藥可能控制症狀，讓病人睡得更好。"},{"en":"If symptoms are controlled but the cause remains, the illness may return later.","zh":"如果症狀被控制但原因仍存在，疾病之後可能復發。"},{"en":"The phrase describes management rather than necessarily complete cure.","zh":"這個短語描述管理，不一定是完全治癒。"}],"source":"71 - Homeopathy.pdf","sourcePage":24},{"front":"bring about a complete cure","meaning":"帶來完全治癒","examples":[{"en":"Homeopathy aims to bring about a complete cure.","zh":"順勢療法旨在帶來完全治癒。"},{"en":"To bring about a complete cure means to cause full recovery from an illness.","zh":"bring about a complete cure 指造成疾病完全康復。"},{"en":"A treatment that brings about a complete cure removes the illness, not just the discomfort.","zh":"帶來完全治癒的治療會消除疾病，而不只是消除不適。"},{"en":"If a method claims to bring about a complete cure, evidence should show lasting recovery.","zh":"如果某方法聲稱帶來完全治癒，證據應顯示持久康復。"},{"en":"The phrase stresses a full and final result.","zh":"這個短語強調完整而最終的結果。"}],"source":"71 - Homeopathy.pdf","sourcePage":24},{"front":"cost and effects","meaning":"成本和效果","examples":[{"en":"The summary compares cost and effects.","zh":"摘要比較成本和效果。"},{"en":"Cost and effects means how much something costs and what results it produces.","zh":"cost and effects 指某物花費多少以及產生甚麼結果。"},{"en":"Before choosing a course, students may compare cost and effects, such as price and improvement.","zh":"選擇課程前，學生可能比較成本和效果，例如價錢和進步。"},{"en":"If a treatment is cheap but ineffective, its cost and effects must be judged together.","zh":"如果治療便宜但無效，其成本和效果必須一起判斷。"},{"en":"The phrase links price with outcome.","zh":"這個短語把價格與結果連繫起來。"}],"source":"71 - Homeopathy.pdf","sourcePage":24},{"front":"cheaper than","meaning":"比……便宜","examples":[{"en":"Homeopathic remedies are described as cheaper than conventional medicines.","zh":"順勢療法藥物被描述為比常規藥物便宜。"},{"en":"Cheaper than means costing less money than something else.","zh":"cheaper than 指比另一事物花費更少金錢。"},{"en":"Taking the bus is usually cheaper than taking a taxi.","zh":"搭巴士通常比搭的士便宜。"},{"en":"If one treatment is cheaper than another, patients may still need to consider safety and evidence.","zh":"如果一種治療比另一種便宜，病人仍需要考慮安全和證據。"},{"en":"The phrase compares cost.","zh":"這個短語比較成本。"}],"source":"71 - Homeopathy.pdf","sourcePage":24},{"front":"side effects","meaning":"副作用","examples":[{"en":"The summary says homeopathic remedies have fewer side effects.","zh":"摘要說順勢療法藥物有較少副作用。"},{"en":"Side effects are unwanted effects caused by a medicine or treatment.","zh":"side effects 是藥物或治療造成的不想要效果。"},{"en":"Some medicines cause side effects such as sleepiness, dizziness or stomach pain.","zh":"有些藥物會造成嗜睡、頭暈或胃痛等副作用。"},{"en":"If side effects are serious, a patient should contact a medical professional.","zh":"如果副作用嚴重，病人應聯絡醫療專業人士。"},{"en":"The phrase refers to additional effects beyond the intended treatment.","zh":"這個短語指預期治療以外的額外效果。"}],"source":"71 - Homeopathy.pdf","sourcePage":24},{"front":"list of words and phrases","meaning":"詞語及短語列表","examples":[{"en":"The question provides a list of words and phrases.","zh":"題目提供一個詞語及短語列表。"},{"en":"A list of words and phrases is a set of vocabulary items given as answer choices.","zh":"list of words and phrases 是作為答案選項的一組詞彙項目。"},{"en":"In a summary task, students choose from a list of words and phrases to fill blanks.","zh":"在摘要題中，學生從詞語及短語列表中選字填空。"},{"en":"If the list contains similar words, grammar and meaning help students choose correctly.","zh":"如果列表包含相似詞語，文法和意思能幫助學生正確選擇。"},{"en":"The phrase describes the word bank in an exercise.","zh":"這個短語描述練習中的詞庫。"}],"source":"71 - Homeopathy.pdf","sourcePage":24},{"front":"more expensive","meaning":"更昂貴","examples":[{"en":"The option “more expensive” contrasts with “cheaper.”","zh":"選項 more expensive 與 cheaper 形成對比。"},{"en":"More expensive means costing more money than another option.","zh":"more expensive 指比另一選項花費更多金錢。"},{"en":"A private taxi is usually more expensive than a bus ride.","zh":"私人的士通常比巴士車程更昂貴。"},{"en":"If a service becomes more expensive, some customers may stop using it.","zh":"如果服務變得更昂貴，一些顧客可能停止使用它。"},{"en":"The phrase compares price in an upward direction.","zh":"這個短語以較高方向比較價格。"}],"source":"71 - Homeopathy.pdf","sourcePage":24},{"front":"getting better","meaning":"情況好轉","examples":[{"en":"The phrase “getting better” can describe recovery from illness.","zh":"getting better 這個短語可以描述從疾病中康復。"},{"en":"Getting better means improving or becoming healthier.","zh":"getting better 指正在改善或變得更健康。"},{"en":"A student with a cold is getting better when fever drops and energy returns.","zh":"感冒學生退燒並恢復精神時，就是情況好轉。"},{"en":"If symptoms are getting better, the patient may still need rest until fully recovered.","zh":"如果症狀正在好轉，病人可能仍需要休息直到完全康復。"},{"en":"The phrase describes improvement, not necessarily complete cure.","zh":"這個短語描述改善，不一定是完全治癒。"}],"source":"71 - Homeopathy.pdf","sourcePage":24},{"front":"healthy","meaning":"健康的","examples":[{"en":"A healthy person was used to test the effects of a substance.","zh":"健康人士被用來測試某物質的作用。"},{"en":"Healthy means physically or mentally well, or not suffering from the illness being discussed.","zh":"healthy 指身體或心理狀態良好，或沒有患有所討論的疾病。"},{"en":"Healthy students usually have enough energy to learn, play and concentrate.","zh":"健康的學生通常有足夠精力學習、玩耍和集中精神。"},{"en":"If a healthy person develops symptoms after taking a substance, researchers may record the reaction.","zh":"如果健康人士服用某物質後出現症狀，研究人員可能記錄該反應。"},{"en":"The word can describe general well-being or the absence of a specific disease.","zh":"這個字可以描述整體健康，也可以描述沒有某特定疾病。"}],"source":"71 - Homeopathy.pdf","sourcePage":24},{"front":"patients","meaning":"病人","examples":[{"en":"The treatment is given to patients with matching symptoms.","zh":"治療給予有相符症狀的病人。"},{"en":"Patients are people receiving medical care, advice, or treatment.","zh":"patients 是接受醫療護理、建議或治療的人。"},{"en":"Patients in a clinic may wait to see a doctor, nurse, or specialist.","zh":"診所中的病人可能等候見醫生、護士或專科人員。"},{"en":"If patients have different symptoms, they may need different forms of care.","zh":"如果病人有不同症狀，他們可能需要不同形式的護理。"},{"en":"The word refers to people being treated, not the medical staff.","zh":"這個字指被治療的人，而不是醫護人員。"}],"source":"71 - Homeopathy.pdf","sourcePage":24}],"ielts/reading/passage-2/Practice 72":[{"front":"just relax","meaning":"放鬆就好","examples":[{"en":"The hypnotist may ask the subject to just relax.","zh":"催眠師可能會要求受試者放鬆就好。"},{"en":"“Just relax” means stop worrying, loosen your body, and let your mind become calm.","zh":"“Just relax” 指停止擔心，放鬆身體，讓心情平靜下來。"},{"en":"A teacher may tell a nervous student to just relax before giving a short speech.","zh":"老師可能在學生作短講前，叫緊張的學生放鬆就好。"},{"en":"If someone relaxes, they may breathe more slowly and feel less tense.","zh":"如果一個人放鬆下來，呼吸可能會變慢，身體也較不繃緊。"},{"en":"This phrase is often used to comfort someone before a difficult or unfamiliar experience.","zh":"這個短語常用來在困難或陌生經驗前安慰別人。"}],"source":"72 - Just relax ….pdf","sourcePage":1},{"front":"hypnosis","meaning":"催眠","examples":[{"en":"Hypnosis is an intriguing and fascinating process.","zh":"催眠是一個引人入勝而迷人的過程。"},{"en":"Hypnosis is a mental state in which a person becomes highly focused and more responsive to suggestions.","zh":"hypnosis 指一種精神狀態，人在其中高度專注，並對暗示更有反應。"},{"en":"A therapist may use hypnosis to help a patient feel calmer when discussing painful memories.","zh":"治療師可能使用催眠，幫助病人在談及痛苦回憶時較平靜。"},{"en":"Hypnosis works better when the person is willing to cooperate and concentrate.","zh":"當受催眠者願意合作和集中注意力時，催眠效果會較好。"},{"en":"This word refers to a focused mental state, not magical control over another person.","zh":"這個詞指專注的精神狀態，而不是對他人的魔法控制。"}],"source":"72 - Just relax ….pdf","sourcePage":1},{"front":"intriguing and fascinating process","meaning":"引人入勝而迷人的過程","examples":[{"en":"Hypnosis is an intriguing and fascinating process.","zh":"催眠是一個引人入勝而迷人的過程。"},{"en":"An intriguing and fascinating process is a process that strongly attracts interest and curiosity.","zh":"intriguing and fascinating process 指一個能強烈引起興趣和好奇心的過程。"},{"en":"Learning how the brain remembers faces can be an intriguing and fascinating process for students.","zh":"學習大腦如何記住面孔，對學生來說可以是一個引人入勝而迷人的過程。"},{"en":"A process becomes fascinating when people want to understand how and why it works.","zh":"當人們想理解某過程如何及為何運作，它就會變得迷人。"},{"en":"This phrase is used for something that feels both mysterious and worth studying.","zh":"這個短語用於某些帶有神秘感且值得研究的事物。"}],"source":"72 - Just relax ….pdf","sourcePage":1},{"front":"a trance-like mental state","meaning":"類似出神的精神狀態","examples":[{"en":"A trance-like mental state can be induced during hypnosis.","zh":"催眠期間可以引發類似出神的精神狀態。"},{"en":"A trance-like mental state is a focused condition in which a person seems deeply absorbed and less distracted.","zh":"trance-like mental state 指一種高度專注的狀態，人在其中似乎深深投入，較少分心。"},{"en":"A student listening to calming music may enter a trance-like state while studying quietly.","zh":"學生聽着平靜音樂安靜溫習時，可能進入類似出神的狀態。"},{"en":"In such a state, people may pay close attention to one voice or idea.","zh":"在這種狀態下，人們可能會密切注意一把聲音或一個想法。"},{"en":"This phrase describes deep mental focus, not ordinary sleep.","zh":"這個短語描述深層精神專注，而不是普通睡眠。"}],"source":"72 - Just relax ….pdf","sourcePage":1},{"front":"be induced in","meaning":"在……身上被引發","examples":[{"en":"A trance-like mental state is induced in one person by another.","zh":"類似出神的精神狀態由另一人在某人身上引發。"},{"en":"To be induced in someone means to be caused or brought about in that person.","zh":"be induced in someone 指在某人身上被造成或引起。"},{"en":"Calm breathing can induce relaxation in a nervous patient.","zh":"平靜呼吸可以在緊張病人身上引發放鬆。"},{"en":"If fear is induced in a crowd, people may panic and move unsafely.","zh":"如果恐懼在人群中被引發，人們可能恐慌並作出不安全移動。"},{"en":"This phrase shows that a state or reaction is created inside someone.","zh":"這個短語顯示某種狀態或反應在某人內心被創造出來。"}],"source":"72 - Just relax ….pdf","sourcePage":1},{"front":"appear to have the power to","meaning":"看似有能力去……","examples":[{"en":"The hypnotist appears to have the power to command the subject.","zh":"催眠師看似有能力命令受試者。"},{"en":"To appear to have the power to do something means to seem able to do it, even if that may not be fully true.","zh":"appear to have the power to do something 指看起來能做到某事，即使未必完全真實。"},{"en":"A strict teacher may appear to have the power to silence a whole class with one look.","zh":"嚴厲老師可能看似有能力用一個眼神令全班安靜。"},{"en":"Appearances can be misleading because the real situation may involve cooperation or consent.","zh":"表象可能具誤導性，因為真實情況可能涉及合作或同意。"},{"en":"This phrase suggests seeming power, not necessarily real control.","zh":"這個短語表示表面上的力量，而不一定是真正控制。"}],"source":"72 - Just relax ….pdf","sourcePage":1},{"front":"command someone to","meaning":"命令某人去……","examples":[{"en":"The hypnotist appears able to command the subject to obey instructions.","zh":"催眠師看似能命令受試者服從指示。"},{"en":"To command someone to do something means to order them strongly to do it.","zh":"command someone to do something 指強硬地命令某人做某事。"},{"en":"A fire officer may command people to leave a building during an emergency.","zh":"火警期間，消防人員可能命令人們離開建築物。"},{"en":"Commands can create quick action, especially when people trust the person giving them.","zh":"命令可以帶來快速行動，尤其當人們信任發出命令的人。"},{"en":"This phrase is stronger and more formal than simply “ask someone to”.","zh":"這個短語比 ask someone to 語氣更強、更正式。"}],"source":"72 - Just relax ….pdf","sourcePage":1},{"front":"obey instructions without question","meaning":"毫無疑問地服從指示","examples":[{"en":"The subject may seem to obey instructions without question.","zh":"受試者可能看似毫無疑問地服從指示。"},{"en":"To obey instructions without question means to follow directions immediately without doubt or argument.","zh":"obey instructions without question 指毫不懷疑或爭辯地立即跟從指示。"},{"en":"In a fire drill, students may obey instructions without question because safety is urgent.","zh":"在消防演習中，學生可能因安全迫切而毫無疑問地服從指示。"},{"en":"Blind obedience can be risky if the instruction is wrong or harmful.","zh":"盲目服從可能有風險，因為指示可能錯誤或有害。"},{"en":"This phrase describes complete obedience, not careful judgement.","zh":"這個短語描述完全服從，而不是仔細判斷。"}],"source":"72 - Just relax ….pdf","sourcePage":1},{"front":"hypnotic experiences","meaning":"催眠經驗","examples":[{"en":"Hypnotic experiences were described by the ancient Egyptians and Greeks.","zh":"催眠經驗曾由古埃及人和古希臘人描述。"},{"en":"Hypnotic experiences are events or states connected with hypnosis or deep mental focus.","zh":"hypnotic experiences 指與催眠或深層精神專注相關的經歷或狀態。"},{"en":"A person may describe a hypnotic experience as feeling calm, focused, and detached from distractions.","zh":"一個人可能把催眠經驗描述為平靜、專注，並與干擾分離。"},{"en":"Such experiences can seem unusual because attention and awareness may change.","zh":"這類經驗可能顯得不尋常，因為注意力和意識可能改變。"},{"en":"This phrase refers to experiences related to hypnosis, not ordinary daydreaming only.","zh":"這個短語指與催眠相關的經驗，而不只是普通發白日夢。"}],"source":"72 - Just relax ….pdf","sourcePage":1},{"front":"be described by","meaning":"由……描述","examples":[{"en":"Hypnotic experiences were described by ancient civilisations.","zh":"催眠經驗曾由古代文明描述。"},{"en":"To be described by someone means to be explained, recorded, or written about by that person or group.","zh":"be described by someone 指由某人或某群體解釋、記錄或書寫。"},{"en":"A rare illness may be described by doctors before it receives an official name.","zh":"罕見疾病在獲得正式名稱前，可能先由醫生描述。"},{"en":"Descriptions from the past can help later researchers understand old practices.","zh":"過去的描述可以幫助後來研究者理解古老做法。"},{"en":"This phrase identifies who gave an account of something.","zh":"這個短語指出由誰對某事作出說明。"}],"source":"72 - Just relax ….pdf","sourcePage":1},{"front":"the ancient Egyptians and Greeks","meaning":"古埃及人和古希臘人","examples":[{"en":"The ancient Egyptians and Greeks described hypnotic experiences.","zh":"古埃及人和古希臘人描述過催眠經驗。"},{"en":"The ancient Egyptians and Greeks were early civilisations whose writings and practices influenced later knowledge.","zh":"ancient Egyptians and Greeks 指兩個早期文明，其文字和做法影響後世知識。"},{"en":"Students often study the ancient Egyptians and Greeks to understand medicine, religion, art, and philosophy.","zh":"學生常研究古埃及人和古希臘人，以理解醫學、宗教、藝術和哲學。"},{"en":"Ancient records can show that some ideas existed long before modern science named them.","zh":"古代記錄可以顯示某些概念在現代科學命名前已存在很久。"},{"en":"This phrase refers to two important ancient cultures.","zh":"這個短語指兩個重要古代文化。"}],"source":"72 - Just relax ….pdf","sourcePage":2},{"front":"references to","meaning":"對……的提及","examples":[{"en":"References to deep sleep and anaesthesia have been found in ancient texts.","zh":"古代文本中發現了對深度睡眠和麻醉的提及。"},{"en":"References to something are mentions of it in speech, writing, or records.","zh":"references to something 指在說話、文字或記錄中提到某事。"},{"en":"A history book may contain references to old school rules and classroom routines.","zh":"歷史書可能包含對舊校規和課室日常安排的提及。"},{"en":"References help researchers know that an idea or practice existed before.","zh":"提及可以幫助研究人員知道某想法或做法曾經存在。"},{"en":"This phrase points to places where something is mentioned, not fully explained.","zh":"這個短語指出某事被提到的位置，而不一定是完整解釋。"}],"source":"72 - Just relax ….pdf","sourcePage":2},{"front":"deep sleep","meaning":"深度睡眠","examples":[{"en":"References to deep sleep have been found in religious texts.","zh":"宗教文本中發現了對深度睡眠的提及。"},{"en":"Deep sleep is a very restful stage of sleep in which a person is hard to wake.","zh":"deep sleep 指非常深沉的睡眠階段，人較難被喚醒。"},{"en":"A tired worker may fall into deep sleep after several nights of poor rest.","zh":"疲倦工人在幾晚睡得不好後，可能進入深度睡眠。"},{"en":"Deep sleep helps the body recover, but hypnosis is not the same as sleep.","zh":"深度睡眠幫助身體恢復，但催眠並不等同睡眠。"},{"en":"This phrase refers to a strong sleep state, not simple relaxation.","zh":"這個短語指強烈睡眠狀態，而不是簡單放鬆。"}],"source":"72 - Just relax ….pdf","sourcePage":2},{"front":"anaesthesia","meaning":"麻醉","examples":[{"en":"References to anaesthesia have been found in the Bible and the Jewish Talmud.","zh":"《聖經》和《猶太法典》中發現了對麻醉的提及。"},{"en":"Anaesthesia is the loss or blocking of feeling, often used so patients do not feel pain during treatment.","zh":"anaesthesia 指感覺喪失或被阻斷，常用於治療時令病人不感痛楚。"},{"en":"A dentist may use anaesthesia before removing a painful tooth.","zh":"牙醫拔除疼痛牙齒前，可能使用麻醉。"},{"en":"Anaesthesia makes surgery safer and less painful because the patient feels little or no pain.","zh":"麻醉令手術更安全、痛楚更少，因為病人幾乎或完全不感痛楚。"},{"en":"This word refers to pain prevention, not ordinary sleep.","zh":"這個詞指防止痛楚，而不是普通睡眠。"}],"source":"72 - Just relax ….pdf","sourcePage":2},{"front":"in the mid-1700s","meaning":"在十八世紀中期","examples":[{"en":"In the mid-1700s, Franz Mesmer developed his theory of animal magnetism.","zh":"在十八世紀中期，Franz Mesmer 發展出他的動物磁力說。"},{"en":"In the mid-1700s means around the middle of the eighteenth century.","zh":"in the mid-1700s 指大約十八世紀中期。"},{"en":"A museum label may say an object was made in the mid-1700s if it dates from around 1750.","zh":"如果物件約於 1750 年製成，博物館標籤可能寫它來自十八世紀中期。"},{"en":"Time phrases help readers place scientific ideas in historical context.","zh":"時間短語幫助讀者把科學想法放進歷史語境。"},{"en":"This phrase gives an approximate historical period.","zh":"這個短語給出大約歷史時期。"}],"source":"72 - Just relax ….pdf","sourcePage":2},{"front":"Austrian physician","meaning":"奧地利醫生","examples":[{"en":"Franz Mesmer was an Austrian physician.","zh":"Franz Mesmer 是一名奧地利醫生。"},{"en":"An Austrian physician is a medical doctor from Austria.","zh":"Austrian physician 指來自奧地利的醫生。"},{"en":"A hospital biography may describe a doctor as an Austrian physician if he trained or worked in Austria.","zh":"如果醫生在奧地利受訓或工作，醫院簡介可能稱他為奧地利醫生。"},{"en":"Knowing a physician’s background can help readers place their work in history and geography.","zh":"知道醫生背景有助讀者把其工作放在歷史和地理中理解。"},{"en":"This phrase identifies both nationality and profession.","zh":"這個短語同時指出國籍和職業。"}],"source":"72 - Just relax ….pdf","sourcePage":2},{"front":"develop a theory of","meaning":"發展出……的理論","examples":[{"en":"Mesmer developed a theory of animal magnetism.","zh":"Mesmer 發展出動物磁力說的理論。"},{"en":"To develop a theory of something means to create an explanation for how or why it works.","zh":"develop a theory of something 指創造一套解釋某事如何或為何運作的說法。"},{"en":"A scientist may develop a theory of why students remember pictures better than lists.","zh":"科學家可能發展出一個理論，解釋學生為何比起清單更容易記住圖片。"},{"en":"A theory can guide experiments, but it may later be challenged or rejected.","zh":"理論可以引導實驗，但之後也可能被挑戰或推翻。"},{"en":"This phrase focuses on building an explanatory idea.","zh":"這個短語著重建立解釋性想法。"}],"source":"72 - Just relax ….pdf","sourcePage":2},{"front":"animal magnetism","meaning":"動物磁力說","examples":[{"en":"Mesmer developed his theory of animal magnetism in the mid-1700s.","zh":"Mesmer 在十八世紀中期發展出他的動物磁力說。"},{"en":"Animal magnetism was Mesmer’s idea that invisible magnetic forces or fluids affected health.","zh":"animal magnetism 是 Mesmer 的想法，認為看不見的磁力或流體會影響健康。"},{"en":"Doctors once tested ideas like animal magnetism before modern medical evidence became stronger.","zh":"在現代醫學證據變得更強前，醫生曾測試動物磁力說這類想法。"},{"en":"The theory became influential even though later investigators rejected its explanation.","zh":"這套理論曾有影響力，雖然後來調查者否定其解釋。"},{"en":"This phrase names an old medical belief linked with Mesmer.","zh":"這個短語命名一種與 Mesmer 相關的舊醫學信念。"}],"source":"72 - Just relax ….pdf","sourcePage":2},{"front":"the belief that","meaning":"認為……的信念","examples":[{"en":"Animal magnetism was the belief that disease was caused by magnetic fluids.","zh":"動物磁力說是一種信念，認為疾病由磁性流體造成。"},{"en":"The belief that introduces an idea someone accepts as true.","zh":"the belief that 用來引入某人接受為真的想法。"},{"en":"Some parents hold the belief that children learn better with regular sleep.","zh":"有些家長抱有一種信念，認為孩子有規律睡眠會學得更好。"},{"en":"A belief can shape behaviour even before it is scientifically proved.","zh":"即使未經科學證明，信念也可以塑造行為。"},{"en":"This phrase is useful when explaining what people thought or assumed.","zh":"這個短語適合用於解釋人們曾經相信或假設甚麼。"}],"source":"72 - Just relax ….pdf","sourcePage":2},{"front":"the cause of disease","meaning":"疾病成因","examples":[{"en":"Mesmer believed that the cause of disease was an improper distribution of fluids.","zh":"Mesmer 相信疾病成因是流體分布不當。"},{"en":"The cause of disease is the reason or process that makes illness happen.","zh":"cause of disease 指令疾病發生的原因或過程。"},{"en":"Doctors look for the cause of disease before choosing the right treatment.","zh":"醫生在選擇正確治療前，會尋找疾病成因。"},{"en":"If the cause is misunderstood, treatment may fail or even harm the patient.","zh":"如果成因被誤解，治療可能失敗，甚至傷害病人。"},{"en":"This phrase focuses on why an illness occurs.","zh":"這個短語著重疾病為何發生。"}],"source":"72 - Just relax ….pdf","sourcePage":2},{"front":"improper distribution of","meaning":"……分布不當","examples":[{"en":"Mesmer blamed disease on the improper distribution of invisible fluids.","zh":"Mesmer 把疾病歸咎於看不見的流體分布不當。"},{"en":"Improper distribution of something means it is not spread or arranged correctly.","zh":"improper distribution of something 指某物沒有被正確分散或安排。"},{"en":"A poor timetable may cause improper distribution of homework across the week.","zh":"差劣時間表可能導致一星期內功課分布不當。"},{"en":"If resources are improperly distributed, some people receive too much while others receive too little.","zh":"如果資源分布不當，有些人得到太多，而另一些人得到太少。"},{"en":"This phrase describes imbalance or poor arrangement.","zh":"這個短語描述不平衡或安排欠佳。"}],"source":"72 - Just relax ….pdf","sourcePage":3},{"front":"invisible magnetic fluids","meaning":"看不見的磁性流體","examples":[{"en":"Mesmer believed in invisible magnetic fluids in the body.","zh":"Mesmer 相信身體內有看不見的磁性流體。"},{"en":"Invisible magnetic fluids were imagined forces or substances that Mesmer believed moved through the body.","zh":"invisible magnetic fluids 指 Mesmer 相信在身體內流動的想像力量或物質。"},{"en":"Before modern science, people sometimes explained illness through unseen forces.","zh":"在現代科學以前，人們有時用看不見的力量解釋疾病。"},{"en":"If a medical theory depends on invisible substances, it needs strong evidence to be accepted.","zh":"如果醫學理論依賴看不見的物質，就需要強證據才會被接受。"},{"en":"This phrase belongs to an old theory, not modern mainstream medicine.","zh":"這個短語屬於舊理論，而不是現代主流醫學。"}],"source":"72 - Just relax ….pdf","sourcePage":3},{"front":"magnetic wands","meaning":"磁棒","examples":[{"en":"Mesmer used water tubs and magnetic wands to treat patients.","zh":"Mesmer 使用水盆和磁棒來治療病人。"},{"en":"Magnetic wands are stick-like tools believed to carry or direct magnetic force.","zh":"magnetic wands 指被認為能帶有或引導磁力的棒狀工具。"},{"en":"A performer in a stage show might use a wand to create the appearance of special power.","zh":"舞台表演者可能使用魔杖營造特殊力量的感覺。"},{"en":"Mesmer’s magnetic wands mattered because patients believed they were part of the treatment.","zh":"Mesmer 的磁棒重要，是因為病人相信它們是治療的一部分。"},{"en":"This phrase refers to tools used in Mesmer’s old treatment method.","zh":"這個短語指 Mesmer 舊治療方法中使用的工具。"}],"source":"72 - Just relax ….pdf","sourcePage":3},{"front":"direct something to","meaning":"將……引導至","examples":[{"en":"Mesmer used magnetic wands to direct supposed fluids to his patients.","zh":"Mesmer 使用磁棒將所謂的流體引導至病人身上。"},{"en":"To direct something to someone means to guide or send it toward that person.","zh":"direct something to someone 指把某物引導或送往某人。"},{"en":"A teacher may direct extra practice to students who need help with pronunciation.","zh":"老師可能將額外練習引導至需要發音幫助的學生。"},{"en":"Directing resources to the right people can make support more effective.","zh":"將資源引導至合適人士，可以令支援更有效。"},{"en":"This phrase focuses on guiding something toward a target.","zh":"這個短語著重把某物導向目標。"}],"source":"72 - Just relax ….pdf","sourcePage":3},{"front":"supposed fluids","meaning":"所謂的流體","examples":[{"en":"Mesmer tried to direct these supposed fluids to his patients.","zh":"Mesmer 嘗試將這些所謂的流體引導至病人身上。"},{"en":"Supposed fluids are fluids believed or claimed to exist, though not necessarily proved.","zh":"supposed fluids 指被相信或聲稱存在、但未必已證實的流體。"},{"en":"A supposed cure may attract attention before doctors test whether it truly works.","zh":"所謂療法可能在醫生測試是否真正有效前已引起注意。"},{"en":"The word “supposed” signals doubt about whether the thing is real.","zh":"supposed 一詞表示對該事物是否真實存在有懷疑。"},{"en":"This phrase helps show that Mesmer’s explanation was not accepted as fact.","zh":"這個短語幫助顯示 Mesmer 的解釋並未被接受為事實。"}],"source":"72 - Just relax ….pdf","sourcePage":3},{"front":"study someone’s claims","meaning":"研究某人的說法","examples":[{"en":"A French commission studied Mesmer’s claims.","zh":"法國委員會研究了 Mesmer 的說法。"},{"en":"To study someone’s claims means to examine whether what that person says is true.","zh":"study someone’s claims 指檢視某人所說是否真實。"},{"en":"A school may study a student’s complaint before deciding what action to take.","zh":"學校在決定採取甚麼行動前，可能研究學生的投訴說法。"},{"en":"Studying claims carefully helps separate evidence from belief or rumour.","zh":"仔細研究說法有助分辨證據、信念和傳聞。"},{"en":"This phrase is used when statements need investigation.","zh":"這個短語用於某些陳述需要被調查時。"}],"source":"72 - Just relax ….pdf","sourcePage":3},{"front":"conclude that","meaning":"得出結論認為","examples":[{"en":"The commission concluded that Mesmer’s cures were imagined.","zh":"委員會得出結論認為 Mesmer 的治癒效果是想像出來的。"},{"en":"To conclude that means to decide something after considering evidence.","zh":"conclude that 指在考慮證據後作出判斷。"},{"en":"After checking attendance records, a teacher may conclude that many students missed the same lesson.","zh":"檢查出席紀錄後，老師可能得出結論認為許多學生錯過了同一課。"},{"en":"A conclusion is stronger when it is based on careful observation rather than guesswork.","zh":"當結論基於仔細觀察而不是猜測時，會更有力。"},{"en":"This phrase introduces a final judgement.","zh":"這個短語引入最終判斷。"}],"source":"72 - Just relax ….pdf","sourcePage":3},{"front":"be imagined by","meaning":"由……想像出來","examples":[{"en":"The cures were only imagined by the patients.","zh":"這些治癒效果只是由病人想像出來。"},{"en":"To be imagined by someone means to exist in that person’s mind rather than in objective reality.","zh":"be imagined by someone 指存在於某人腦海中，而不是客觀現實中。"},{"en":"A child may hear a noise at night and think a danger is there, though it was imagined by the child.","zh":"孩子晚上聽到聲音，可能以為有危險，但那危險是孩子想像出來的。"},{"en":"Expectations can make people feel improvement even when no real treatment effect exists.","zh":"期望可以令人感到改善，即使沒有真正治療效果。"},{"en":"This phrase suggests that something is mentally created, not physically real.","zh":"這個短語表示某事由心理產生，而不是實際存在。"}],"source":"72 - Just relax ….pdf","sourcePage":3},{"front":"continue to believe in","meaning":"繼續相信","examples":[{"en":"People continued to believe in mesmerism.","zh":"人們繼續相信麥斯麥術。"},{"en":"To continue to believe in something means to keep accepting it as true or valuable.","zh":"continue to believe in something 指繼續接受某事為真或有價值。"},{"en":"Some parents continue to believe in handwritten notes because they help children remember better.","zh":"有些家長繼續相信手寫筆記，因為它們幫助孩子更好記憶。"},{"en":"People may continue to believe in an idea even after experts question it.","zh":"即使專家質疑某想法，人們仍可能繼續相信它。"},{"en":"This phrase shows that belief remains over time.","zh":"這個短語顯示信念隨時間仍然保留。"}],"source":"72 - Just relax ….pdf","sourcePage":3},{"front":"mesmerism","meaning":"麥斯麥術；催眠磁療說","examples":[{"en":"People continued to believe in the process of mesmerism.","zh":"人們繼續相信麥斯麥術這個過程。"},{"en":"Mesmerism is an old practice linked to Mesmer’s ideas about animal magnetism and hypnotic effects.","zh":"mesmerism 指與 Mesmer 關於動物磁力和催眠效果的想法相關的舊做法。"},{"en":"A history lesson on hypnosis may begin with mesmerism before moving to modern research.","zh":"關於催眠的歷史課可能先講麥斯麥術，再轉向現代研究。"},{"en":"Mesmerism became important because it led people to study suggestion and hypnosis more seriously.","zh":"麥斯麥術變得重要，是因為它促使人們更認真研究暗示和催眠。"},{"en":"This word refers to a historical belief system, not modern scientific hypnosis exactly.","zh":"這個詞指歷史信念系統，而不完全等同現代科學催眠。"}],"source":"72 - Just relax ….pdf","sourcePage":3},{"front":"it was soon realised that","meaning":"人們很快意識到","examples":[{"en":"It was soon realised that magnets and water were unnecessary.","zh":"人們很快意識到磁鐵和水並非必要。"},{"en":"It was soon realised that means people quickly came to understand something.","zh":"it was soon realised that 指人們很快理解到某事。"},{"en":"It was soon realised that the meeting room was too small when more parents arrived.","zh":"當更多家長到達時，人們很快意識到會議室太小。"},{"en":"New evidence can make people realise that an earlier explanation was wrong.","zh":"新證據可以令人意識到早前解釋是錯的。"},{"en":"This phrase introduces a later correction or discovery.","zh":"這個短語引入後來的修正或發現。"}],"source":"72 - Just relax ….pdf","sourcePage":4},{"front":"successful results","meaning":"成功效果","examples":[{"en":"Successful results could be achieved without magnets and water.","zh":"即使沒有磁鐵和水，也可以達成成功效果。"},{"en":"Successful results are outcomes that achieve the intended aim.","zh":"successful results 指達到預期目標的結果。"},{"en":"A student gets successful results when regular revision leads to better test scores.","zh":"當定期溫習帶來更好測驗成績，學生就得到成功效果。"},{"en":"Successful results can come from the right method, not from unnecessary tools.","zh":"成功效果可以來自正確方法，而不是不必要工具。"},{"en":"This phrase focuses on whether the outcome worked.","zh":"這個短語著重結果是否有效。"}],"source":"72 - Just relax ….pdf","sourcePage":4},{"front":"be achieved without","meaning":"無需……也可達成","examples":[{"en":"Successful results could be achieved without the need for magnets.","zh":"無需磁鐵也可達成成功效果。"},{"en":"To be achieved without something means to be successfully done even though that thing is not used.","zh":"be achieved without something 指即使不用某物也能成功做到。"},{"en":"Good pronunciation can be achieved without expensive software if students practise carefully.","zh":"如果學生仔細練習，無需昂貴軟件也可達成良好發音。"},{"en":"If a result is achieved without a tool, that tool may not be essential.","zh":"如果結果不用某工具也能達成，該工具可能不是必要。"},{"en":"This phrase shows that something is unnecessary for success.","zh":"這個短語顯示某物對成功並非必要。"}],"source":"72 - Just relax ….pdf","sourcePage":4},{"front":"without the need for","meaning":"無需……","examples":[{"en":"Hypnotic effects could occur without the need for magnets and water.","zh":"催眠效果無需磁鐵和水也可能出現。"},{"en":"Without the need for something means not requiring it.","zh":"without the need for something 指不需要某物。"},{"en":"Students can share documents online without the need for printed copies.","zh":"學生可以在網上分享文件，無需列印副本。"},{"en":"Removing unnecessary requirements can make a process simpler and cheaper.","zh":"移除不必要要求可以令過程更簡單和便宜。"},{"en":"This phrase highlights that something is not needed.","zh":"這個短語突出某物並非必要。"}],"source":"72 - Just relax ….pdf","sourcePage":4},{"front":"the term hypnotism","meaning":"「催眠術」一詞","examples":[{"en":"The term hypnotism was first used by James Braid.","zh":"「催眠術」一詞最先由 James Braid 使用。"},{"en":"The term hypnotism means the word or expression used to name the practice of hypnosis.","zh":"term hypnotism 指用來命名催眠做法的詞語或表達。"},{"en":"A textbook may explain when the term “robot” first entered common use.","zh":"教科書可能解釋 “robot” 一詞何時開始普遍使用。"},{"en":"Knowing when a term appeared helps students understand the history of an idea.","zh":"知道術語何時出現，有助學生理解概念歷史。"},{"en":"This phrase focuses on the name of the practice, not the practice itself only.","zh":"這個短語著重該做法的名稱，而不只是做法本身。"}],"source":"72 - Just relax ….pdf","sourcePage":4},{"front":"was first used by","meaning":"最先由……使用","examples":[{"en":"The term hypnotism was first used by a British physician.","zh":"「催眠術」一詞最先由一名英國醫生使用。"},{"en":"Was first used by someone means that person was the earliest known user of a word or method.","zh":"was first used by someone 指某人是已知最早使用某詞或方法的人。"},{"en":"A new classroom term may be first used by one teacher before other teachers adopt it.","zh":"一個新課堂術語可能先由一位老師使用，然後其他老師採用。"},{"en":"Tracing first use helps explain how an idea spread.","zh":"追溯最早使用有助解釋一個概念如何傳播。"},{"en":"This phrase identifies the earliest known user.","zh":"這個短語指出已知最早使用者。"}],"source":"72 - Just relax ….pdf","sourcePage":4},{"front":"British physician","meaning":"英國醫生","examples":[{"en":"James Braid was a British physician who studied hypnosis.","zh":"James Braid 是一名研究催眠的英國醫生。"},{"en":"A British physician is a medical doctor from Britain.","zh":"British physician 指來自英國的醫生。"},{"en":"A history article may describe a nineteenth-century doctor as a British physician to show his background.","zh":"歷史文章可能把十九世紀醫生描述為英國醫生，以顯示其背景。"},{"en":"Knowing the physician’s role helps readers understand why his medical observations mattered.","zh":"知道該醫生的角色，有助讀者理解他的醫學觀察為何重要。"},{"en":"This phrase gives both nationality and profession.","zh":"這個短語同時提供國籍和職業。"}],"source":"72 - Just relax ….pdf","sourcePage":4},{"front":"suggestion and hypnosis","meaning":"暗示與催眠","examples":[{"en":"James Braid studied suggestion and hypnosis in the mid-1800s.","zh":"James Braid 在十九世紀中期研究暗示與催眠。"},{"en":"Suggestion and hypnosis refer to the use of ideas or instructions together with a hypnotic state.","zh":"suggestion and hypnosis 指把想法或指示與催眠狀態結合使用。"},{"en":"A therapist may study suggestion and hypnosis to understand how words affect behaviour.","zh":"治療師可能研究暗示與催眠，以理解語言如何影響行為。"},{"en":"Suggestion matters because people under hypnosis may respond more strongly to certain instructions.","zh":"暗示重要，因為人在催眠下可能對某些指示反應更強。"},{"en":"This phrase links mental influence with the hypnotic process.","zh":"這個短語把心理影響與催眠過程連繫起來。"}],"source":"72 - Just relax ….pdf","sourcePage":4},{"front":"demonstrate that","meaning":"證明","examples":[{"en":"Braid demonstrated that hypnosis differed from sleep.","zh":"Braid 證明催眠與睡眠不同。"},{"en":"To demonstrate that means to show clearly through evidence, explanation, or experiment.","zh":"demonstrate that 指透過證據、解釋或實驗清楚顯示某事。"},{"en":"A science teacher may demonstrate that plants need light by growing one plant in darkness.","zh":"科學老師可能透過把一棵植物放在黑暗中種植，證明植物需要光。"},{"en":"Demonstration helps turn an opinion into a supported conclusion.","zh":"證明有助把意見變成有支持的結論。"},{"en":"This phrase is useful when evidence proves a point.","zh":"這個短語適合用於證據證實某點時。"}],"source":"72 - Just relax ….pdf","sourcePage":4},{"front":"differ from sleep","meaning":"與睡眠不同","examples":[{"en":"Hypnosis differs from sleep.","zh":"催眠與睡眠不同。"},{"en":"To differ from sleep means to be unlike normal sleep in important ways.","zh":"differ from sleep 指在重要方面不同於正常睡眠。"},{"en":"Daydreaming differs from sleep because the person is still awake and aware.","zh":"發白日夢與睡眠不同，因為人仍然清醒並有意識。"},{"en":"If hypnosis differs from sleep, a hypnotised person may still hear and respond to instructions.","zh":"如果催眠與睡眠不同，受催眠者仍可能聽到並回應指示。"},{"en":"This phrase shows contrast between two mental states.","zh":"這個短語顯示兩種精神狀態之間的對比。"}],"source":"72 - Just relax ….pdf","sourcePage":4},{"front":"physiological response","meaning":"生理反應","examples":[{"en":"Braid showed that hypnosis was a physiological response.","zh":"Braid 顯示催眠是一種生理反應。"},{"en":"A physiological response is a reaction involving the body or its normal functions.","zh":"physiological response 指涉及身體或其正常功能的反應。"},{"en":"Sweating before an exam can be a physiological response to stress.","zh":"考試前出汗可以是對壓力的生理反應。"},{"en":"If hypnosis is a physiological response, it can be studied as a natural body-and-mind reaction.","zh":"如果催眠是生理反應，它就可以被視為自然的身心反應來研究。"},{"en":"This phrase contrasts bodily response with magic or mystery.","zh":"這個短語把身體反應與魔法或神秘感作對比。"}],"source":"72 - Just relax ….pdf","sourcePage":5},{"front":"not the result of","meaning":"並非……的結果","examples":[{"en":"Hypnosis was not the result of secret powers.","zh":"催眠並非神秘力量的結果。"},{"en":"Not the result of something means not caused by that thing.","zh":"not the result of something 指並非由某事造成。"},{"en":"A student’s improvement may be the result of practice, not luck.","zh":"學生進步可能是練習的結果，而不是運氣。"},{"en":"This phrase separates the real cause from a wrong explanation.","zh":"這個短語把真正原因與錯誤解釋分開。"},{"en":"It is useful when correcting a misunderstanding.","zh":"它適合用於修正常見誤解。"}],"source":"72 - Just relax ….pdf","sourcePage":5},{"front":"secret powers","meaning":"神秘力量","examples":[{"en":"Braid argued that hypnosis was not caused by secret powers.","zh":"Braid 主張催眠不是由神秘力量造成。"},{"en":"Secret powers are hidden or mysterious abilities that people imagine someone has.","zh":"secret powers 指人們想像某人擁有的隱藏或神秘能力。"},{"en":"A child may think a magician has secret powers, though the trick uses practice and tools.","zh":"孩子可能以為魔術師有神秘力量，雖然戲法其實使用練習和工具。"},{"en":"Explaining the real method removes the need to believe in mysterious forces.","zh":"解釋真正方法可以令人不必相信神秘力量。"},{"en":"This phrase is often used when rejecting a magical explanation.","zh":"這個短語常用於否定魔法式解釋。"}],"source":"72 - Just relax ….pdf","sourcePage":5},{"front":"during the same period","meaning":"在同一時期","examples":[{"en":"During the same period, James Esdaile used hypnotism in surgery.","zh":"在同一時期，James Esdaile 在手術中使用催眠術。"},{"en":"During the same period means at around the same time in history.","zh":"during the same period 指在歷史上大約同一時間。"},{"en":"During the same period, one school improved its library while another updated its science rooms.","zh":"在同一時期，一所學校改善圖書館，另一所更新科學室。"},{"en":"This phrase helps compare events happening in the same historical window.","zh":"這個短語幫助比較同一歷史時間範圍內發生的事件。"},{"en":"It links two developments by time.","zh":"它透過時間把兩項發展連繫起來。"}],"source":"72 - Just relax ….pdf","sourcePage":5},{"front":"Scottish doctor","meaning":"蘇格蘭醫生","examples":[{"en":"James Esdaile was a Scottish doctor working in India.","zh":"James Esdaile 是一名在印度工作的蘇格蘭醫生。"},{"en":"A Scottish doctor is a medical doctor from Scotland.","zh":"Scottish doctor 指來自蘇格蘭的醫生。"},{"en":"A biography may describe a physician as a Scottish doctor to show his national background.","zh":"傳記可能把某醫生描述為蘇格蘭醫生，以顯示其國籍背景。"},{"en":"Doctors working abroad may bring medical ideas into new cultural and clinical settings.","zh":"在海外工作的醫生可能把醫學想法帶進新的文化和臨床環境。"},{"en":"This phrase identifies both nationality and profession.","zh":"這個短語同時指出國籍和職業。"}],"source":"72 - Just relax ….pdf","sourcePage":5},{"front":"working in India","meaning":"在印度工作","examples":[{"en":"James Esdaile was a Scottish doctor working in India.","zh":"James Esdaile 是一名在印度工作的蘇格蘭醫生。"},{"en":"Working in India means doing one’s job in India.","zh":"working in India 指在印度從事自己的工作。"},{"en":"A teacher working in another country may learn different classroom habits and expectations.","zh":"在另一個國家工作的老師，可能學到不同課室習慣和期望。"},{"en":"Where a person works can affect the cases, patients, or problems they encounter.","zh":"一個人工作的地方會影響他遇到的個案、病人或問題。"},{"en":"This phrase gives the place where someone carried out their professional work.","zh":"這個短語指出某人從事專業工作的地點。"}],"source":"72 - Just relax ….pdf","sourcePage":5},{"front":"use hypnotism as an anaesthetic","meaning":"用催眠作為麻醉方法","examples":[{"en":"Esdaile used hypnotism as an anaesthetic in major operations.","zh":"Esdaile 在大型手術中用催眠作為麻醉方法。"},{"en":"To use hypnotism as an anaesthetic means to use hypnosis to reduce or block pain during treatment.","zh":"use hypnotism as an anaesthetic 指使用催眠來減少或阻斷治療中的痛楚。"},{"en":"A dentist might use relaxation techniques to reduce fear, though this is not the same as full anaesthesia.","zh":"牙醫可能使用放鬆技巧減少恐懼，雖然這不等同完整麻醉。"},{"en":"If hypnosis reduces pain, surgery may be possible with less chemical anaesthetic.","zh":"如果催眠能減痛，手術可能可用較少化學麻醉藥進行。"},{"en":"This phrase shows a medical use of hypnosis.","zh":"這個短語顯示催眠的醫學用途。"}],"source":"72 - Just relax ….pdf","sourcePage":5},{"front":"major surgical operations","meaning":"大型外科手術","examples":[{"en":"Hypnotism was used in over 200 major surgical operations.","zh":"催眠術被用於二百多宗大型外科手術。"},{"en":"Major surgical operations are serious medical procedures that usually involve cutting into the body.","zh":"major surgical operations 指通常涉及切開身體的嚴重醫療程序。"},{"en":"A heart operation is a major surgical operation that requires careful planning and monitoring.","zh":"心臟手術是一種大型外科手術，需要仔細規劃和監察。"},{"en":"Major operations are risky, so pain control and patient safety are essential.","zh":"大型手術有風險，所以止痛和病人安全至關重要。"},{"en":"This phrase refers to serious surgery, not minor treatment.","zh":"這個短語指嚴重手術，而不是小型治療。"}],"source":"72 - Just relax ….pdf","sourcePage":5},{"front":"leg amputations","meaning":"截肢手術","examples":[{"en":"Some of Esdaile’s operations included leg amputations.","zh":"Esdaile 的一些手術包括腿部截肢手術。"},{"en":"Leg amputations are operations in which part or all of a leg is surgically removed.","zh":"leg amputations 指透過手術移除部分或整條腿。"},{"en":"A severe accident may require a leg amputation if the limb cannot be saved.","zh":"如果肢體無法保住，嚴重意外可能需要截肢手術。"},{"en":"Such operations need strong pain control because they are physically traumatic.","zh":"這類手術需要強力止痛，因為對身體創傷很大。"},{"en":"This phrase describes a serious surgical procedure.","zh":"這個短語描述嚴重外科程序。"}],"source":"72 - Just relax ….pdf","sourcePage":5},{"front":"later that century","meaning":"在該世紀較後期","examples":[{"en":"Later that century, Jean Charcot experimented with hypnosis.","zh":"在該世紀較後期，Jean Charcot 用催眠進行實驗。"},{"en":"Later that century means in a later part of the same century already mentioned.","zh":"later that century 指在已提及同一世紀的較後部分。"},{"en":"A writer may say “later that century” after first discussing events in the 1800s.","zh":"作者先討論十九世紀事件後，可能會說 later that century。"},{"en":"This phrase helps keep a historical timeline clear.","zh":"這個短語幫助保持歷史時間線清楚。"},{"en":"It shows that another event happened after an earlier one but within the same century.","zh":"它顯示另一事件在較早事件之後，但仍在同一世紀內發生。"}],"source":"72 - Just relax ….pdf","sourcePage":5},{"front":"French neurologist","meaning":"法國神經科醫生","examples":[{"en":"Jean Charcot was a French neurologist.","zh":"Jean Charcot 是一名法國神經科醫生。"},{"en":"A French neurologist is a doctor from France who studies and treats disorders of the nervous system.","zh":"French neurologist 指來自法國、研究和治療神經系統疾病的醫生。"},{"en":"A neurologist may treat patients with epilepsy, nerve damage, or movement problems.","zh":"神經科醫生可能治療癲癇、神經損傷或動作問題病人。"},{"en":"Neurologists study the brain and nerves, so their work is relevant to hypnosis and mental states.","zh":"神經科醫生研究大腦和神經，所以其工作與催眠和精神狀態相關。"},{"en":"This phrase identifies both nationality and medical specialty.","zh":"這個短語同時指出國籍和醫學專科。"}],"source":"72 - Just relax ….pdf","sourcePage":6},{"front":"experiment with hypnosis","meaning":"用催眠進行實驗","examples":[{"en":"Charcot experimented with hypnosis in his clinic.","zh":"Charcot 在他的診所中用催眠進行實驗。"},{"en":"To experiment with hypnosis means to test or study hypnosis through controlled observation or practice.","zh":"experiment with hypnosis 指透過受控觀察或實踐測試和研究催眠。"},{"en":"A doctor may experiment with a relaxation method to see whether it reduces patient anxiety.","zh":"醫生可能試驗一種放鬆方法，看看它是否減少病人焦慮。"},{"en":"Experiments help researchers move from belief to evidence.","zh":"實驗幫助研究人員由信念走向證據。"},{"en":"This phrase shows active testing rather than casual use.","zh":"這個短語顯示主動測試，而不是隨便使用。"}],"source":"72 - Just relax ….pdf","sourcePage":6},{"front":"clinic for nervous disorders","meaning":"神經疾病診所","examples":[{"en":"Charcot worked with hypnosis in his clinic for nervous disorders.","zh":"Charcot 在他的神經疾病診所中研究催眠。"},{"en":"A clinic for nervous disorders is a medical centre for problems involving the brain, nerves, or mental functioning.","zh":"clinic for nervous disorders 指治療大腦、神經或心理功能問題的醫療中心。"},{"en":"Patients with tremors, seizures, or unexplained symptoms might visit such a clinic.","zh":"有顫抖、抽搐或原因不明症狀的病人可能到這類診所求醫。"},{"en":"Specialist clinics allow doctors to observe similar cases and compare treatments.","zh":"專科診所讓醫生觀察相似個案並比較治療。"},{"en":"This phrase describes a medical setting focused on nervous-system problems.","zh":"這個短語描述專注於神經系統問題的醫療場所。"}],"source":"72 - Just relax ….pdf","sourcePage":6},{"front":"since then","meaning":"自此以後","examples":[{"en":"Since then, scientists have studied hypnosis more systematically.","zh":"自此以後，科學家更有系統地研究催眠。"},{"en":"Since then means from that time until now or until a later time.","zh":"since then 指從那時起直到現在或後來某時。"},{"en":"The school introduced a reading programme in 2020; since then, library visits have increased.","zh":"學校在 2020 年推出閱讀計劃；自此以後，圖書館到訪次數增加。"},{"en":"This phrase links a past event with later developments.","zh":"這個短語把過去事件與後來發展連繫起來。"},{"en":"It helps show change over time.","zh":"它幫助顯示隨時間發生的變化。"}],"source":"72 - Just relax ….pdf","sourcePage":6},{"front":"the state of hypnosis","meaning":"催眠狀態","examples":[{"en":"Scientists have shown that the state of hypnosis is natural.","zh":"科學家已顯示催眠狀態是自然的。"},{"en":"The state of hypnosis is the focused mental condition a person enters during hypnosis.","zh":"state of hypnosis 指人在催眠期間進入的專注精神狀態。"},{"en":"A therapist may guide a patient into a calm state of hypnosis before discussing difficult memories.","zh":"治療師可能先引導病人進入平靜的催眠狀態，再討論困難回憶。"},{"en":"In this state, attention can become narrow and suggestions may feel more powerful.","zh":"在這種狀態下，注意力可以變得狹窄，暗示也可能感覺更有力。"},{"en":"This phrase names the mental condition, not the method used to create it.","zh":"這個短語命名精神狀態，而不是製造該狀態的方法。"}],"source":"72 - Just relax ….pdf","sourcePage":6},{"front":"natural human behaviour","meaning":"自然的人類行為","examples":[{"en":"Hypnosis is a natural human behaviour.","zh":"催眠是一種自然的人類行為。"},{"en":"Natural human behaviour is behaviour that can occur as part of normal human experience.","zh":"natural human behaviour 指可作為正常人類經驗一部分出現的行為。"},{"en":"Daydreaming during a long bus ride is a natural human behaviour, not a strange illness.","zh":"長途巴士上發白日夢是一種自然的人類行為，而不是奇怪疾病。"},{"en":"Calling hypnosis natural helps separate it from magical or supernatural ideas.","zh":"把催眠稱為自然，有助把它與魔法或超自然想法分開。"},{"en":"This phrase suggests something belongs to ordinary human ability.","zh":"這個短語表示某事屬於普通人類能力。"}],"source":"72 - Just relax ….pdf","sourcePage":6},{"front":"psychological, social and physical experiences","meaning":"心理、社交及身體經驗","examples":[{"en":"Hypnosis can affect psychological, social and physical experiences.","zh":"催眠可以影響心理、社交及身體經驗。"},{"en":"Psychological, social and physical experiences involve the mind, relationships with others, and the body.","zh":"psychological, social and physical experiences 涉及心智、與他人的關係，以及身體。"},{"en":"Stress can affect psychological feelings, social behaviour, and physical health at the same time.","zh":"壓力可以同時影響心理感受、社交行為和身體健康。"},{"en":"A change in mental focus may influence mood, communication, and body reactions.","zh":"精神專注的改變可能影響情緒、溝通和身體反應。"},{"en":"This phrase covers several areas of human experience together.","zh":"這個短語同時涵蓋人類經驗的幾個範疇。"}],"source":"72 - Just relax ….pdf","sourcePage":6},{"front":"the effects of hypnotism","meaning":"催眠術的效果","examples":[{"en":"The effects of hypnotism depend on the person being hypnotised.","zh":"催眠術的效果取決於受催眠者。"},{"en":"The effects of hypnotism are the changes or results caused by hypnosis.","zh":"effects of hypnotism 指催眠造成的變化或結果。"},{"en":"One patient may feel deeply relaxed, while another may notice only a small change.","zh":"一名病人可能感到深度放鬆，而另一名病人可能只感到輕微變化。"},{"en":"Effects vary because people differ in willingness, concentration, and response to suggestion.","zh":"效果各有不同，因為人的意願、專注力和對暗示的反應不同。"},{"en":"This phrase focuses on what hypnosis does to a person.","zh":"這個短語著重催眠對人產生甚麼作用。"}],"source":"72 - Just relax ….pdf","sourcePage":6},{"front":"depend on","meaning":"取決於","examples":[{"en":"The effects depend on the subject’s ability, willingness and motivation.","zh":"效果取決於受試者的能力、意願和動機。"},{"en":"To depend on something means to be decided or influenced by it.","zh":"depend on something 指由某事決定或受某事影響。"},{"en":"A student’s progress may depend on practice, sleep, and clear feedback.","zh":"學生進步可能取決於練習、睡眠和清楚回饋。"},{"en":"If success depends on willingness, forcing someone may reduce the result.","zh":"如果成功取決於意願，強迫某人可能降低效果。"},{"en":"This phrase shows that one thing changes according to another factor.","zh":"這個短語顯示一件事會隨另一因素改變。"}],"source":"72 - Just relax ….pdf","sourcePage":6},{"front":"ability, willingness and motivation","meaning":"能力、意願及動機","examples":[{"en":"Hypnosis depends on the ability, willingness and motivation of the subject.","zh":"催眠取決於受試者的能力、意願及動機。"},{"en":"Ability, willingness and motivation mean what a person can do, is prepared to do, and wants to do.","zh":"ability, willingness and motivation 指一個人能做甚麼、願意做甚麼，以及想做甚麼。"},{"en":"A student’s language progress depends on ability, willingness and motivation, not talent alone.","zh":"學生語言進步取決於能力、意願及動機，而不只是天份。"},{"en":"If someone lacks motivation, even a good method may produce weak results.","zh":"如果某人缺乏動機，即使方法好，效果也可能薄弱。"},{"en":"This phrase combines skill, consent, and inner drive.","zh":"這個短語結合技能、同意和內在推動力。"}],"source":"72 - Just relax ….pdf","sourcePage":6},{"front":"the person being hypnotised","meaning":"受催眠者","examples":[{"en":"The person being hypnotised must be willing to respond.","zh":"受催眠者必須願意作出反應。"},{"en":"The person being hypnotised is the subject who is guided into hypnosis.","zh":"person being hypnotised 指被引導進入催眠的受試者。"},{"en":"In therapy, the person being hypnotised should understand the process before it begins.","zh":"在治療中，受催眠者應在開始前理解過程。"},{"en":"Cooperation matters because hypnosis depends partly on the subject’s response.","zh":"合作很重要，因為催眠部分取決於受試者的反應。"},{"en":"This phrase identifies the person receiving hypnosis.","zh":"這個短語指出接受催眠的人。"}],"source":"72 - Just relax ….pdf","sourcePage":7},{"front":"be compared to","meaning":"被比作","examples":[{"en":"Hypnosis has been compared to dreaming and sleepwalking.","zh":"催眠曾被比作做夢和夢遊。"},{"en":"To be compared to something means to be described as similar to it in some way.","zh":"be compared to something 指被描述為在某方面與某事相似。"},{"en":"Online learning is often compared to classroom learning because both involve teaching and practice.","zh":"網上學習常被比作課室學習，因為兩者都涉及教學和練習。"},{"en":"Comparisons help explain unfamiliar ideas by linking them with familiar ones.","zh":"比較透過把陌生概念連繫到熟悉概念，幫助解釋。"},{"en":"This phrase shows similarity, not exact sameness.","zh":"這個短語顯示相似，而不是完全相同。"}],"source":"72 - Just relax ….pdf","sourcePage":7},{"front":"dreaming and sleepwalking","meaning":"做夢和夢遊","examples":[{"en":"Hypnosis is sometimes compared to dreaming and sleepwalking.","zh":"催眠有時被比作做夢和夢遊。"},{"en":"Dreaming and sleepwalking are sleep-related experiences in which normal awareness changes.","zh":"dreaming and sleepwalking 指與睡眠相關、正常意識發生變化的經驗。"},{"en":"A person who sleepwalks may move around without fully waking up.","zh":"夢遊的人可能在未完全醒來時走動。"},{"en":"Hypnosis may look similar to these states, but it is not actually sleep.","zh":"催眠可能看起來像這些狀態，但其實不是睡眠。"},{"en":"This phrase gives familiar comparisons for altered awareness.","zh":"這個短語為意識改變提供熟悉比較。"}],"source":"72 - Just relax ….pdf","sourcePage":7},{"front":"be related to","meaning":"與……有關","examples":[{"en":"Hypnosis is not actually related to sleep.","zh":"催眠其實與睡眠無關。"},{"en":"To be related to something means to be connected with it in cause, nature, or meaning.","zh":"be related to something 指在原因、性質或意思上與某事有關。"},{"en":"A headache may be related to stress, dehydration, or poor sleep.","zh":"頭痛可能與壓力、缺水或睡眠差有關。"},{"en":"If two things look similar, they are not always truly related.","zh":"即使兩件事看起來相似，也不一定真正有關。"},{"en":"This phrase shows connection or lack of connection.","zh":"這個短語顯示有關或無關。"}],"source":"72 - Just relax ….pdf","sourcePage":7},{"front":"active and intense mental concentration","meaning":"主動而高度集中的精神專注","examples":[{"en":"Hypnosis involves active and intense mental concentration.","zh":"催眠涉及主動而高度集中的精神專注。"},{"en":"Active and intense mental concentration means strong, focused attention from the mind.","zh":"active and intense mental concentration 指強烈而集中的心智注意力。"},{"en":"A chess player may need intense concentration to plan several moves ahead.","zh":"棋手可能需要高度專注，才能提前計劃幾步棋。"},{"en":"When attention becomes intense, distractions may fade into the background.","zh":"當注意力變得高度集中，干擾可能退到背景中。"},{"en":"This phrase shows that hypnosis involves mental effort, not passive sleep.","zh":"這個短語顯示催眠涉及精神努力，而不是被動睡眠。"}],"source":"72 - Just relax ….pdf","sourcePage":7},{"front":"on the part of","meaning":"在……方面；由……作出","examples":[{"en":"Hypnosis requires concentration on the part of the person being hypnotised.","zh":"催眠需要受催眠者方面的專注。"},{"en":"On the part of someone means done or provided by that person.","zh":"on the part of someone 指由某人作出或提供。"},{"en":"A group project needs honesty on the part of every student.","zh":"小組項目需要每位學生方面的誠實。"},{"en":"If cooperation is needed on the part of the patient, the doctor cannot succeed alone.","zh":"如果需要病人方面的合作，醫生不能單獨成功。"},{"en":"This phrase identifies who must contribute something.","zh":"這個短語指出誰必須作出貢獻。"}],"source":"72 - Just relax ….pdf","sourcePage":7},{"front":"fully aware of","meaning":"完全知道","examples":[{"en":"Hypnotised people are usually fully aware of what is being said and done.","zh":"受催眠的人通常完全知道正在說和做的事情。"},{"en":"To be fully aware of something means to know and notice it clearly.","zh":"fully aware of something 指清楚知道並注意到某事。"},{"en":"A driver should be fully aware of pedestrians before turning at a crossing.","zh":"司機在斑馬線轉彎前，應完全知道有沒有行人。"},{"en":"Awareness matters because people under hypnosis are not simply unconscious.","zh":"意識很重要，因為催眠中的人並不是單純失去意識。"},{"en":"This phrase describes complete understanding or notice.","zh":"這個短語描述完整理解或察覺。"}],"source":"72 - Just relax ….pdf","sourcePage":7},{"front":"what is being said and done","meaning":"正在說和做的事情","examples":[{"en":"Hypnotised people are aware of what is being said and done.","zh":"受催眠者知道正在說和做的事情。"},{"en":"What is being said and done means the words spoken and the actions happening at that moment.","zh":"what is being said and done 指當刻說出的話和正在發生的行動。"},{"en":"During a meeting, a good note-taker records what is being said and done.","zh":"會議期間，好的記錄員會記下正在說和做的事情。"},{"en":"Being aware of speech and actions helps a person respond appropriately.","zh":"知道言語和行動有助一個人作出適當回應。"},{"en":"This phrase refers to current words and actions.","zh":"這個短語指當前的說話和行動。"}],"source":"72 - Just relax ….pdf","sourcePage":7},{"front":"various techniques","meaning":"各種技巧","examples":[{"en":"There are various techniques used to induce hypnosis.","zh":"有各種技巧用來引發催眠。"},{"en":"Various techniques are several different methods for doing something.","zh":"various techniques 指用來做某事的幾種不同方法。"},{"en":"Teachers use various techniques, such as examples, diagrams, and questions, to explain grammar.","zh":"老師使用例子、圖表和問題等各種技巧來解釋文法。"},{"en":"Having several techniques helps because different people respond in different ways.","zh":"有幾種技巧會有幫助，因為不同人有不同反應。"},{"en":"This phrase introduces a range of methods rather than one fixed method.","zh":"這個短語引入一系列方法，而不是單一固定方法。"}],"source":"72 - Just relax ….pdf","sourcePage":7},{"front":"induce hypnosis","meaning":"引發催眠狀態","examples":[{"en":"Hypnotists use various techniques to induce hypnosis.","zh":"催眠師使用各種技巧引發催眠狀態。"},{"en":"To induce hypnosis means to guide someone into a hypnotic state.","zh":"induce hypnosis 指引導某人進入催眠狀態。"},{"en":"A therapist may use calm words and steady breathing to induce relaxation before treatment.","zh":"治療師可能使用平靜語言和穩定呼吸，在治療前引發放鬆。"},{"en":"Hypnosis is more likely to be induced when the subject focuses and cooperates.","zh":"當受試者專注並合作時，催眠狀態較可能被引發。"},{"en":"This phrase describes starting the hypnotic state.","zh":"這個短語描述催眠狀態的開始。"}],"source":"72 - Just relax ….pdf","sourcePage":7},{"front":"the best-known","meaning":"最著名的","examples":[{"en":"The best-known technique uses repeated suggestions.","zh":"最著名的技巧使用重複暗示。"},{"en":"The best-known method is the one most people have heard of.","zh":"best-known method 指最多人聽過的方法。"},{"en":"The best-known way to learn vocabulary is often repetition with examples.","zh":"最著名的學詞彙方法通常是用例句重複練習。"},{"en":"A method can be well known without being the only method available.","zh":"一種方法可以很著名，但不是唯一可用方法。"},{"en":"This phrase identifies the most familiar example in a group.","zh":"這個短語指出一組之中最熟悉的例子。"}],"source":"72 - Just relax ….pdf","sourcePage":8},{"front":"a series of simple suggestions","meaning":"一連串簡單暗示","examples":[{"en":"The best-known technique is a series of simple suggestions.","zh":"最著名的技巧是一連串簡單暗示。"},{"en":"A series of simple suggestions is a set of easy instructions or ideas given one after another.","zh":"series of simple suggestions 指一組連續給出的簡單指示或想法。"},{"en":"A coach may give a nervous player a series of simple suggestions: breathe, look up, and relax your shoulders.","zh":"教練可能給緊張球員一連串簡單暗示：呼吸、抬頭、放鬆肩膀。"},{"en":"Simple repeated suggestions can guide attention and reduce confusion.","zh":"簡單而重複的暗示可以引導注意力並減少混亂。"},{"en":"This phrase describes step-by-step verbal guidance.","zh":"這個短語描述逐步的語言引導。"}],"source":"72 - Just relax ….pdf","sourcePage":8},{"front":"repeated continuously","meaning":"不斷重複","examples":[{"en":"The suggestions are repeated continuously in the same tone of voice.","zh":"暗示會以同一語調不斷重複。"},{"en":"Repeated continuously means said or done again and again without stopping for a while.","zh":"repeated continuously 指在一段時間內不停地反覆說或做。"},{"en":"A child may remember a phone number if it is repeated continuously several times.","zh":"如果電話號碼被不斷重複幾次，孩子可能會記住它。"},{"en":"Continuous repetition can make a message feel familiar and calming.","zh":"持續重複可以令訊息感覺熟悉而平靜。"},{"en":"This phrase emphasises steady repetition over time.","zh":"這個短語強調隨時間穩定重複。"}],"source":"72 - Just relax ….pdf","sourcePage":8},{"front":"in the same tone of voice","meaning":"以同一語調","examples":[{"en":"The hypnotist repeats suggestions in the same tone of voice.","zh":"催眠師以同一語調重複暗示。"},{"en":"In the same tone of voice means using the same sound, rhythm, or emotional quality when speaking.","zh":"in the same tone of voice 指說話時使用相同聲音、節奏或情感質感。"},{"en":"A teacher may read instructions in the same calm tone of voice to reduce student anxiety.","zh":"老師可能以同一平靜語調讀出指示，以減少學生焦慮。"},{"en":"A steady tone can make speech feel predictable and soothing.","zh":"穩定語調可以令說話感覺可預測和舒緩。"},{"en":"This phrase focuses on how words are spoken.","zh":"這個短語著重話語如何被說出。"}],"source":"72 - Just relax ….pdf","sourcePage":8},{"front":"the subject","meaning":"受試者；被催眠者","examples":[{"en":"The subject is instructed to focus on an object.","zh":"受試者被指示將注意力集中在一件物件上。"},{"en":"The subject is the person taking part in an experiment, test, or hypnotic process.","zh":"subject 指參與實驗、測試或催眠過程的人。"},{"en":"In a memory study, the subject may be asked to look at pictures and answer questions.","zh":"在記憶研究中，受試者可能被要求看圖片並回答問題。"},{"en":"The subject’s cooperation affects what researchers can observe.","zh":"受試者的合作會影響研究人員能觀察到甚麼。"},{"en":"This word identifies the person being studied or guided.","zh":"這個詞指出被研究或被引導的人。"}],"source":"72 - Just relax ….pdf","sourcePage":8},{"front":"be instructed to","meaning":"被指示去","examples":[{"en":"The subject is instructed to focus their attention on a fixed point.","zh":"受試者被指示把注意力集中於固定一點。"},{"en":"To be instructed to do something means to be told clearly to do it.","zh":"be instructed to do something 指被清楚告知要做某事。"},{"en":"During an exam, students are instructed to write answers in black pen.","zh":"考試期間，學生被指示用黑色筆作答。"},{"en":"Clear instructions reduce confusion and make behaviour easier to observe.","zh":"清楚指示可以減少混亂，並令行為較容易被觀察。"},{"en":"This phrase describes formal guidance or direction.","zh":"這個短語描述正式引導或指示。"}],"source":"72 - Just relax ….pdf","sourcePage":8},{"front":"focus their attention on","meaning":"將注意力集中於","examples":[{"en":"The subject focuses their attention on an object.","zh":"受試者將注意力集中於一件物件。"},{"en":"To focus their attention on something means to concentrate on that one thing.","zh":"focus their attention on something 指把注意力集中在某一件事上。"},{"en":"A student may focus attention on one paragraph before answering a reading question.","zh":"學生回答閱讀題前，可能先將注意力集中於一段文字。"},{"en":"Focusing attention reduces distraction and can make the mind calmer.","zh":"集中注意力可以減少分心，並令心智較平靜。"},{"en":"This phrase describes deliberate mental concentration.","zh":"這個短語描述有意識的精神專注。"}],"source":"72 - Just relax ….pdf","sourcePage":8},{"front":"fixed point","meaning":"固定一點","examples":[{"en":"The subject may focus on an object or fixed point.","zh":"受試者可能集中於一件物件或固定一點。"},{"en":"A fixed point is one steady place that does not move.","zh":"fixed point 指一個不移動的穩定位置。"},{"en":"A dancer may look at a fixed point while turning to avoid dizziness.","zh":"舞者轉圈時可能看着固定一點，以避免頭暈。"},{"en":"Focusing on a fixed point can help steady attention and reduce distraction.","zh":"集中於固定一點可以幫助穩定注意力並減少分心。"},{"en":"This phrase refers to a stable visual target.","zh":"這個短語指穩定的視覺目標。"}],"source":"72 - Just relax ….pdf","sourcePage":8},{"front":"breathe deeply","meaning":"深呼吸","examples":[{"en":"The subject is told to relax and breathe deeply.","zh":"受試者被告知要放鬆並深呼吸。"},{"en":"To breathe deeply means to take slow, full breaths into the lungs.","zh":"breathe deeply 指緩慢而充分地把空氣吸入肺部。"},{"en":"A nervous speaker may breathe deeply before walking onto the stage.","zh":"緊張的演講者上台前可能深呼吸。"},{"en":"Deep breathing can slow the body down and reduce tension.","zh":"深呼吸可以令身體慢下來並減少繃緊。"},{"en":"This phrase describes a calming physical action.","zh":"這個短語描述令人平靜的身體動作。"}],"source":"72 - Just relax ….pdf","sourcePage":8},{"front":"allow the eyelids to grow heavy","meaning":"讓眼皮變得沉重","examples":[{"en":"The subject is told to allow the eyelids to grow heavy.","zh":"受試者被告知讓眼皮變得沉重。"},{"en":"To allow the eyelids to grow heavy means to let the eyes feel tired and ready to close.","zh":"allow the eyelids to grow heavy 指讓眼睛感到疲倦並準備閉上。"},{"en":"A person resting after a long day may feel their eyelids grow heavy while listening to soft music.","zh":"忙了一整天的人聽着柔和音樂休息時，可能感到眼皮變得沉重。"},{"en":"Heavy eyelids can make the body feel calmer and less alert.","zh":"沉重的眼皮可以令身體感覺較平靜、較不警覺。"},{"en":"This phrase is often used in relaxation or hypnosis instructions.","zh":"這個短語常用於放鬆或催眠指示。"}],"source":"72 - Just relax ….pdf","sourcePage":8},{"front":"as the person responds","meaning":"隨着該人作出反應","examples":[{"en":"As the person responds, their state of attention changes.","zh":"隨着該人作出反應，其注意力狀態會改變。"},{"en":"As the person responds means while or when the person begins to react.","zh":"as the person responds 指當該人開始回應時。"},{"en":"As a student responds to feedback, their writing may become clearer.","zh":"隨着學生回應回饋，他的寫作可能變得更清晰。"},{"en":"A person’s reaction can change the next step of a lesson, therapy session, or conversation.","zh":"一個人的反應可以改變課堂、治療或對話的下一步。"},{"en":"This phrase links a response with a developing change.","zh":"這個短語把反應與正在發展的變化連繫起來。"}],"source":"72 - Just relax ….pdf","sourcePage":9},{"front":"state of attention","meaning":"注意力狀態","examples":[{"en":"The subject’s state of attention changes during hypnosis.","zh":"受試者的注意力狀態在催眠期間會改變。"},{"en":"State of attention means the way a person’s focus is organised at a particular moment.","zh":"state of attention 指一個人在特定時刻注意力如何組織。"},{"en":"A student’s state of attention may shift when a noisy phone rings in class.","zh":"當課堂上手機響起，學生的注意力狀態可能轉變。"},{"en":"When attention becomes narrow, people may notice one voice and ignore other sounds.","zh":"當注意力變得狹窄，人們可能注意一把聲音而忽略其他聲音。"},{"en":"This phrase describes how focused or distracted the mind is.","zh":"這個短語描述心智有多專注或分心。"}],"source":"72 - Just relax ….pdf","sourcePage":9},{"front":"altered state","meaning":"改變了的狀態","examples":[{"en":"This altered state often leads to other changes.","zh":"這種改變了的狀態常導致其他變化。"},{"en":"An altered state is a condition that is different from a person’s usual state of mind or body.","zh":"altered state 指不同於一個人平常心理或身體狀態的情況。"},{"en":"A person under strong stress may enter an altered state in which time feels slower.","zh":"人在強烈壓力下可能進入改變了的狀態，感覺時間變慢。"},{"en":"Altered states can change attention, memory, feelings, or physical reactions.","zh":"改變了的狀態可以改變注意力、記憶、感受或身體反應。"},{"en":"This phrase describes a changed condition, not necessarily an illness.","zh":"這個短語描述狀態改變，而不一定是疾病。"}],"source":"72 - Just relax ….pdf","sourcePage":9},{"front":"lead to other changes","meaning":"導致其他變化","examples":[{"en":"An altered state of attention can lead to other changes.","zh":"注意力的改變狀態可以導致其他變化。"},{"en":"To lead to other changes means to cause additional effects after the first change.","zh":"lead to other changes 指在第一個變化後造成額外影響。"},{"en":"Better sleep can lead to other changes, such as improved mood and stronger concentration.","zh":"更好睡眠可以導致其他變化，例如心情改善和專注力增強。"},{"en":"One small change in attention may affect memory, emotion, and behaviour.","zh":"注意力的一個小改變可能影響記憶、情緒和行為。"},{"en":"This phrase shows a chain of effects.","zh":"這個短語顯示一連串影響。"}],"source":"72 - Just relax ….pdf","sourcePage":9},{"front":"levels of awareness","meaning":"意識程度","examples":[{"en":"The person may experience different levels of awareness.","zh":"該人可能經歷不同意識程度。"},{"en":"Levels of awareness are different degrees of noticing, understanding, or being conscious of things.","zh":"levels of awareness 指注意、理解或意識到事物的不同程度。"},{"en":"A driver has a high level of awareness when they notice traffic, signs, and pedestrians together.","zh":"司機同時注意交通、標誌和行人時，就有高意識程度。"},{"en":"Low awareness can make people miss important information around them.","zh":"低意識程度可以令人錯過周圍重要資訊。"},{"en":"This phrase describes how conscious or alert someone is.","zh":"這個短語描述某人有多清醒或警覺。"}],"source":"72 - Just relax ….pdf","sourcePage":9},{"front":"consciousness","meaning":"意識","examples":[{"en":"Hypnosis may affect consciousness, imagination and memory.","zh":"催眠可能影響意識、想像力和記憶。"},{"en":"Consciousness is the state of being awake, aware, and able to experience thoughts or surroundings.","zh":"consciousness 指清醒、有知覺，並能經歷思想或周圍環境的狀態。"},{"en":"A patient recovering from anaesthesia gradually returns to full consciousness.","zh":"從麻醉中恢復的病人會逐漸回到完整意識。"},{"en":"Changes in consciousness can affect what people notice and remember.","zh":"意識變化可以影響人注意和記住甚麼。"},{"en":"This word refers to awareness, not simply intelligence.","zh":"這個詞指覺察，而不只是智力。"}],"source":"72 - Just relax ….pdf","sourcePage":9},{"front":"imagination","meaning":"想像力","examples":[{"en":"Hypnosis may affect a person’s imagination.","zh":"催眠可能影響一個人的想像力。"},{"en":"Imagination is the ability to form pictures, ideas, or experiences in the mind.","zh":"imagination 指在腦海中形成圖像、想法或經驗的能力。"},{"en":"Children use imagination when they turn a cardboard box into a spaceship during play.","zh":"孩子玩耍時把紙箱變成太空船，就是在使用想像力。"},{"en":"A strong imagination can make suggested scenes feel vivid and emotionally powerful.","zh":"強想像力可以令被暗示的場景感覺鮮明而情感強烈。"},{"en":"This word refers to mental creation, not factual memory.","zh":"這個詞指心理創造，而不是事實記憶。"}],"source":"72 - Just relax ….pdf","sourcePage":9},{"front":"memory and reasoning","meaning":"記憶與推理能力","examples":[{"en":"Hypnosis may affect memory and reasoning.","zh":"催眠可能影響記憶與推理能力。"},{"en":"Memory and reasoning are the ability to remember information and think logically about it.","zh":"memory and reasoning 指記住資訊並對其作邏輯思考的能力。"},{"en":"A student needs memory and reasoning to recall a formula and decide how to use it.","zh":"學生需要記憶與推理能力來記起公式並決定如何使用。"},{"en":"If memory or reasoning changes, a person may recall details differently or make different conclusions.","zh":"如果記憶或推理改變，一個人可能以不同方式回憶細節或作出不同結論。"},{"en":"This phrase joins remembering with thinking.","zh":"這個短語把記住與思考連結起來。"}],"source":"72 - Just relax ….pdf","sourcePage":9},{"front":"responsive to suggestions","meaning":"對暗示更有反應","examples":[{"en":"The person may become more responsive to suggestions.","zh":"該人可能變得對暗示更有反應。"},{"en":"Responsive to suggestions means likely to react to ideas or instructions offered by another person.","zh":"responsive to suggestions 指較可能對他人提出的想法或指示作出反應。"},{"en":"A student who trusts a teacher may be more responsive to suggestions about study habits.","zh":"信任老師的學生可能更願意回應關於學習習慣的建議。"},{"en":"People become more responsive when they feel calm, safe, and focused.","zh":"當人感到平靜、安全和專注時，可能會更有反應。"},{"en":"This phrase describes readiness to accept guidance, not forced obedience.","zh":"這個短語描述接受引導的準備，而不是被迫服從。"}],"source":"72 - Just relax ….pdf","sourcePage":9},{"front":"additional phenomena","meaning":"額外現象","examples":[{"en":"Additional phenomena may be produced or eliminated.","zh":"額外現象可能被產生或消除。"},{"en":"Additional phenomena are extra effects or events that happen beyond the main process.","zh":"additional phenomena 指主要過程以外出現的額外效果或事件。"},{"en":"Stress may cause additional phenomena such as headaches, sweating, or stomach pain.","zh":"壓力可能造成頭痛、出汗或胃痛等額外現象。"},{"en":"In hypnosis, extra effects may appear because attention and suggestion change bodily responses.","zh":"在催眠中，額外效果可能因注意力和暗示改變身體反應而出現。"},{"en":"This phrase refers to extra observable changes.","zh":"這個短語指額外可觀察的變化。"}],"source":"72 - Just relax ….pdf","sourcePage":9},{"front":"be produced or eliminated","meaning":"被產生或消除","examples":[{"en":"Some physical effects may be produced or eliminated through hypnosis.","zh":"某些身體效果可能透過催眠被產生或消除。"},{"en":"To be produced or eliminated means to be created or removed.","zh":"be produced or eliminated 指被創造出來或被移除。"},{"en":"A medicine may produce sleepiness but eliminate pain.","zh":"藥物可能產生睡意，但消除痛楚。"},{"en":"A treatment is useful when it can create helpful effects and reduce harmful ones.","zh":"當治療能創造有用效果並減少有害效果時，就有價值。"},{"en":"This phrase describes causing or stopping an effect.","zh":"這個短語描述造成或停止某種效果。"}],"source":"72 - Just relax ….pdf","sourcePage":10},{"front":"blushing","meaning":"面紅","examples":[{"en":"Blushing may be produced or eliminated during hypnosis.","zh":"面紅可能在催眠期間被產生或消除。"},{"en":"Blushing is redness in the face caused by emotion, embarrassment, heat, or body reaction.","zh":"blushing 指由情緒、尷尬、熱力或身體反應造成的臉部泛紅。"},{"en":"A shy student may start blushing when asked to speak in front of the class.","zh":"害羞學生被要求在全班面前說話時，可能開始面紅。"},{"en":"Blushing shows that emotional states can affect the body visibly.","zh":"面紅顯示情緒狀態可以明顯影響身體。"},{"en":"This word refers to facial redness, not ordinary skin colour.","zh":"這個詞指臉部泛紅，而不是普通膚色。"}],"source":"72 - Just relax ….pdf","sourcePage":10},{"front":"sweating","meaning":"出汗","examples":[{"en":"Sweating may be affected by hypnotic suggestion.","zh":"出汗可能受催眠暗示影響。"},{"en":"Sweating is the release of moisture from the skin, often because of heat, exercise, or emotion.","zh":"sweating 指皮膚釋放水分，通常因熱、運動或情緒而出現。"},{"en":"A person may start sweating before an interview because they feel nervous.","zh":"一個人在面試前可能因緊張而開始出汗。"},{"en":"Sweating can show that mental stress has a physical effect.","zh":"出汗可以顯示精神壓力對身體有影響。"},{"en":"This word describes a body response, not simply feeling hot.","zh":"這個詞描述身體反應，而不只是感到熱。"}],"source":"72 - Just relax ….pdf","sourcePage":10},{"front":"paralysis","meaning":"麻痺；癱瘓","examples":[{"en":"Paralysis may be produced under hypnosis.","zh":"麻痺可能在催眠下被產生。"},{"en":"Paralysis is the inability to move part or all of the body.","zh":"paralysis 指身體部分或全部無法移動。"},{"en":"A patient with nerve damage may experience paralysis in one arm.","zh":"神經受損病人可能一隻手臂出現麻痺。"},{"en":"In hypnosis, suggested paralysis may make a person feel unable to move temporarily.","zh":"在催眠中，被暗示的麻痺可能令一個人暫時感到無法移動。"},{"en":"This word describes loss of movement, not ordinary tiredness.","zh":"這個詞描述喪失活動能力，而不是普通疲倦。"}],"source":"72 - Just relax ….pdf","sourcePage":10},{"front":"muscle tension","meaning":"肌肉繃緊","examples":[{"en":"Hypnosis can affect muscle tension.","zh":"催眠可以影響肌肉繃緊。"},{"en":"Muscle tension is tightness or stiffness in the muscles.","zh":"muscle tension 指肌肉緊繃或僵硬。"},{"en":"A student may feel muscle tension in the shoulders before an exam.","zh":"學生考試前可能感到肩膀肌肉繃緊。"},{"en":"Relaxation exercises can reduce muscle tension and make the body feel lighter.","zh":"放鬆練習可以減少肌肉繃緊，令身體感覺較輕鬆。"},{"en":"This phrase describes a physical sign often linked with stress.","zh":"這個短語描述常與壓力相關的身體徵象。"}],"source":"72 - Just relax ….pdf","sourcePage":10},{"front":"unique to","meaning":"……獨有的","examples":[{"en":"None of these experiences is unique to hypnosis.","zh":"這些經驗沒有一項是催眠獨有的。"},{"en":"Unique to something means found only in that thing and not elsewhere.","zh":"unique to something 指只存在於某事，而不見於其他地方。"},{"en":"Wearing uniforms is not unique to schools because some workplaces use them too.","zh":"穿制服不是學校獨有的，因為有些工作場所也使用制服。"},{"en":"If a feature is not unique to one situation, it cannot prove that situation by itself.","zh":"如果某特徵不是某情況獨有的，它本身不能證明該情況。"},{"en":"This phrase helps separate exclusive features from common ones.","zh":"這個短語幫助區分獨有特徵和常見特徵。"}],"source":"72 - Just relax ….pdf","sourcePage":10},{"front":"very responsive to hypnosis","meaning":"對催眠很有反應","examples":[{"en":"Some people are very responsive to hypnosis.","zh":"有些人對催眠很有反應。"},{"en":"Very responsive to hypnosis means strongly affected by hypnosis or quick to follow hypnotic suggestions.","zh":"very responsive to hypnosis 指受催眠影響很強，或很快回應催眠暗示。"},{"en":"A patient who relaxes easily may be very responsive to calming instructions.","zh":"容易放鬆的病人可能對平靜指示很有反應。"},{"en":"High responsiveness can make hypnosis happen more quickly for some people.","zh":"高反應度可以令某些人更快進入催眠。"},{"en":"This phrase describes sensitivity to hypnosis, not weakness of character.","zh":"這個短語描述對催眠的敏感度，而不是性格軟弱。"}],"source":"72 - Just relax ….pdf","sourcePage":10},{"front":"when they are not hypnotised","meaning":"在沒有被催眠時","examples":[{"en":"Some people respond to suggestions even when they are not hypnotised.","zh":"有些人在沒有被催眠時也會回應暗示。"},{"en":"When they are not hypnotised means while they are in an ordinary waking state.","zh":"when they are not hypnotised 指他們處於普通清醒狀態時。"},{"en":"A student may follow calming advice even when they are not in any special mental state.","zh":"學生即使沒有處於任何特殊精神狀態，也可能跟從安定情緒的建議。"},{"en":"This shows that suggestion can affect people outside formal hypnosis too.","zh":"這顯示暗示也能在正式催眠以外影響人。"},{"en":"This phrase contrasts hypnotic and non-hypnotic situations.","zh":"這個短語對比催眠與非催眠情況。"}],"source":"72 - Just relax ….pdf","sourcePage":10},{"front":"explain why","meaning":"解釋為何","examples":[{"en":"This responsiveness explains why hypnosis takes only a few seconds for some people.","zh":"這種反應度解釋為何催眠對某些人只需幾秒。"},{"en":"To explain why means to give the reason for something.","zh":"explain why 指給出某事的原因。"},{"en":"A teacher may explain why a grammar answer is wrong by pointing to the verb tense.","zh":"老師可能透過指出動詞時態來解釋為何文法答案錯誤。"},{"en":"Good explanations help people understand causes, not just remember facts.","zh":"好解釋幫助人理解原因，而不只是記住事實。"},{"en":"This phrase introduces the reason behind a result.","zh":"這個短語引入結果背後的原因。"}],"source":"72 - Just relax ….pdf","sourcePage":10},{"front":"take only a few seconds","meaning":"只需幾秒","examples":[{"en":"Hypnosis takes only a few seconds for some people.","zh":"催眠對某些人只需幾秒。"},{"en":"To take only a few seconds means to require a very short amount of time.","zh":"take only a few seconds 指只需要非常短的時間。"},{"en":"Unlocking a phone with a fingerprint takes only a few seconds.","zh":"用指紋解鎖手機只需幾秒。"},{"en":"Some processes happen quickly when the person or system is ready.","zh":"當人或系統已準備好，有些過程會很快發生。"},{"en":"This phrase emphasises speed and ease.","zh":"這個短語強調速度和容易程度。"}],"source":"72 - Just relax ….pdf","sourcePage":10},{"front":"cannot be easily hypnotised","meaning":"不容易被催眠","examples":[{"en":"Some people cannot be easily hypnotised.","zh":"有些人不容易被催眠。"},{"en":"Cannot be easily hypnotised means do not enter hypnosis quickly or strongly.","zh":"cannot be easily hypnotised 指不會快速或強烈地進入催眠。"},{"en":"A person who feels suspicious or distracted may not relax enough for hypnosis to work well.","zh":"感到懷疑或分心的人可能不夠放鬆，令催眠效果不佳。"},{"en":"Low responsiveness can make the hypnotic process slower or less effective.","zh":"低反應度可以令催眠過程較慢或較不有效。"},{"en":"This phrase describes difficulty entering hypnosis, not a personal failure.","zh":"這個短語描述進入催眠有困難，而不是個人失敗。"}],"source":"72 - Just relax ….pdf","sourcePage":11},{"front":"a common misunderstanding","meaning":"常見誤解","examples":[{"en":"It is a common misunderstanding that hypnotists can control people completely.","zh":"催眠師可以完全控制人是一個常見誤解。"},{"en":"A common misunderstanding is a wrong idea that many people believe.","zh":"common misunderstanding 指許多人相信的錯誤想法。"},{"en":"It is a common misunderstanding that quiet students are always less confident.","zh":"安靜學生一定較沒信心是一個常見誤解。"},{"en":"Misunderstandings can spread when movies or public performances exaggerate reality.","zh":"當電影或公開表演誇大現實時，誤解可以傳播。"},{"en":"This phrase introduces an idea that needs correction.","zh":"這個短語引入需要被修正的想法。"}],"source":"72 - Just relax ….pdf","sourcePage":11},{"front":"force people to","meaning":"迫使人們去……","examples":[{"en":"Hypnotists cannot force people to perform acts against their will.","zh":"催眠師不能迫使人們違背意願作出行為。"},{"en":"To force people to do something means to make them do it without free choice.","zh":"force people to do something 指令人們在沒有自由選擇下做某事。"},{"en":"A school should not force students to join a club they strongly dislike.","zh":"學校不應迫使學生加入他們強烈不喜歡的學會。"},{"en":"Forcing people can create resistance, fear, or unfair treatment.","zh":"迫使人們可以造成抗拒、恐懼或不公平對待。"},{"en":"This phrase stresses lack of consent.","zh":"這個短語強調缺乏同意。"}],"source":"72 - Just relax ….pdf","sourcePage":11},{"front":"perform criminal acts","meaning":"作出犯罪行為","examples":[{"en":"Hypnotists cannot force people to perform criminal acts.","zh":"催眠師不能迫使人們作出犯罪行為。"},{"en":"To perform criminal acts means to do actions that break the law.","zh":"perform criminal acts 指做出違反法律的行為。"},{"en":"Stealing money from a shop is a criminal act, even if someone else suggests it.","zh":"從商店偷錢是犯罪行為，即使是別人提出的。"},{"en":"People under hypnosis are not simply tools for illegal behaviour.","zh":"被催眠的人並不是非法行為的工具。"},{"en":"This phrase refers to unlawful actions, not embarrassing stage tricks.","zh":"這個短語指違法行動，而不是令人尷尬的舞台把戲。"}],"source":"72 - Just relax ….pdf","sourcePage":11},{"front":"against their will","meaning":"違背他們的意願","examples":[{"en":"Subjects cannot be forced to act against their will.","zh":"受試者不能被迫違背他們的意願行動。"},{"en":"Against their will means without their agreement or contrary to what they want.","zh":"against their will 指沒有他們同意，或違反他們想法。"},{"en":"A patient should not be treated against their will unless strict legal conditions apply.","zh":"除非有嚴格法律條件，病人不應在違背意願下接受治療。"},{"en":"Respecting free will means people can refuse actions they judge wrong or unacceptable.","zh":"尊重自由意志代表人們可以拒絕他們認為錯誤或不可接受的行動。"},{"en":"This phrase focuses on consent and personal choice.","zh":"這個短語著重同意和個人選擇。"}],"source":"72 - Just relax ….pdf","sourcePage":11},{"front":"in fact","meaning":"事實上","examples":[{"en":"In fact, subjects can resist suggestions.","zh":"事實上，受試者可以抗拒暗示。"},{"en":"In fact introduces information that corrects, strengthens, or clarifies what came before.","zh":"in fact 用來引入修正、加強或澄清前文的資料。"},{"en":"Many people think grammar is only rules; in fact, it helps meaning become clear.","zh":"許多人以為文法只是規則；事實上，它幫助意思變得清楚。"},{"en":"Writers use this phrase when the truth may surprise the reader.","zh":"當真相可能令讀者意外時，作者會使用這個短語。"},{"en":"This phrase often corrects a mistaken impression.","zh":"這個短語常用來修正錯誤印象。"}],"source":"72 - Just relax ….pdf","sourcePage":11},{"front":"resist suggestions","meaning":"抗拒暗示","examples":[{"en":"Subjects can resist suggestions under hypnosis.","zh":"受試者在催眠下也可以抗拒暗示。"},{"en":"To resist suggestions means to refuse or not follow ideas offered by someone else.","zh":"resist suggestions 指拒絕或不跟從他人提出的想法。"},{"en":"A student can resist bad advice from friends and keep studying before an exam.","zh":"學生可以抗拒朋友的壞建議，在考試前繼續溫習。"},{"en":"Resistance shows that the person still has judgement and choice.","zh":"抗拒顯示該人仍有判斷和選擇。"},{"en":"This phrase contrasts response to suggestion with blind obedience.","zh":"這個短語把回應暗示與盲目服從作對比。"}],"source":"72 - Just relax ….pdf","sourcePage":11},{"front":"retain their ability to","meaning":"保留……的能力","examples":[{"en":"Subjects retain their ability to distinguish right from wrong.","zh":"受試者保留分辨是非的能力。"},{"en":"To retain their ability to do something means to keep that ability.","zh":"retain their ability to do something 指保留做某事的能力。"},{"en":"Older adults can retain their ability to learn new words through regular practice.","zh":"長者可以透過定期練習保留學習新詞的能力。"},{"en":"If people retain judgement under hypnosis, they are not completely controlled.","zh":"如果人在催眠下仍保留判斷力，就不是被完全控制。"},{"en":"This phrase focuses on an ability that remains.","zh":"這個短語著重仍然存在的能力。"}],"source":"72 - Just relax ….pdf","sourcePage":11},{"front":"distinguish right from wrong","meaning":"分辨是非","examples":[{"en":"Hypnotised subjects can still distinguish right from wrong.","zh":"受催眠者仍能分辨是非。"},{"en":"To distinguish right from wrong means to know the difference between moral or acceptable and unacceptable behaviour.","zh":"distinguish right from wrong 指知道道德上或行為上可接受與不可接受之間的分別。"},{"en":"A child learns to distinguish right from wrong when adults explain fairness and harm.","zh":"當成年人解釋公平和傷害時，孩子會學會分辨是非。"},{"en":"This ability helps people refuse actions that feel unethical.","zh":"這種能力幫助人拒絕感到不道德的行動。"},{"en":"This phrase refers to moral judgement, not simple preference.","zh":"這個短語指道德判斷，而不是簡單喜好。"}],"source":"72 - Just relax ….pdf","sourcePage":11},{"front":"public performances","meaning":"公開表演","examples":[{"en":"The misunderstanding often comes from public performances.","zh":"這個誤解常來自公開表演。"},{"en":"Public performances are shows given in front of an audience.","zh":"public performances 指在觀眾面前進行的表演。"},{"en":"A magician may create a public performance that looks impossible but uses planned tricks.","zh":"魔術師可能創造看似不可能但使用預先安排技巧的公開表演。"},{"en":"Stage shows can exaggerate hypnosis and make it seem more powerful than it is.","zh":"舞台表演可以誇大催眠，令它看起來比實際更強大。"},{"en":"This phrase refers to entertainment settings, not clinical treatment.","zh":"這個短語指娛樂場合，而不是臨床治療。"}],"source":"72 - Just relax ….pdf","sourcePage":11},{"front":"perform ridiculous actions","meaning":"做出荒謬行為","examples":[{"en":"Some subjects perform ridiculous actions during stage hypnosis.","zh":"有些受試者在舞台催眠中做出荒謬行為。"},{"en":"To perform ridiculous actions means to do silly, strange, or laughable things in front of others.","zh":"perform ridiculous actions 指在他人面前做愚蠢、奇怪或可笑的事情。"},{"en":"A performer may pretend to forget their own name as a ridiculous action in a comedy show.","zh":"表演者可能在喜劇節目中假裝忘記自己名字，作為荒謬行為。"},{"en":"Such actions entertain the audience but can create misleading ideas about hypnosis.","zh":"這類行為娛樂觀眾，但可能造成對催眠的誤解。"},{"en":"This phrase describes behaviour that looks absurd rather than serious.","zh":"這個短語描述看起來荒唐而非嚴肅的行為。"}],"source":"72 - Just relax ….pdf","sourcePage":12},{"front":"highly embarrassing actions","meaning":"非常尷尬的行為","examples":[{"en":"Subjects may perform highly embarrassing actions at the hypnotist’s command.","zh":"受試者可能在催眠師命令下做出非常尷尬的行為。"},{"en":"Highly embarrassing actions are actions that make a person feel very ashamed or awkward.","zh":"highly embarrassing actions 指令一個人感到非常羞恥或尷尬的行動。"},{"en":"Singing loudly in a quiet library would be highly embarrassing for most students.","zh":"在安靜圖書館大聲唱歌，對大多數學生來說會是非常尷尬的行為。"},{"en":"Embarrassing stage behaviour can make hypnosis seem like total control.","zh":"舞台上的尷尬行為可以令催眠看似完全控制。"},{"en":"This phrase describes actions that damage dignity or cause discomfort.","zh":"這個短語描述傷害尊嚴或造成不適的行為。"}],"source":"72 - Just relax ….pdf","sourcePage":12},{"front":"at the command of","meaning":"在……的命令下","examples":[{"en":"Subjects may act at the command of the hypnotist.","zh":"受試者可能在催眠師的命令下行動。"},{"en":"At the command of someone means because that person orders or instructs it.","zh":"at the command of someone 指因某人命令或指示而做某事。"},{"en":"Soldiers may move at the command of an officer during training.","zh":"士兵在訓練中可能在軍官命令下移動。"},{"en":"Acting at someone’s command can look like obedience, but consent may still be involved.","zh":"在某人命令下行動可以看似服從，但仍可能涉及同意。"},{"en":"This phrase connects an action with the person giving the order.","zh":"這個短語把行動與發出命令的人連繫起來。"}],"source":"72 - Just relax ….pdf","sourcePage":12},{"front":"be instructed not to recall","meaning":"被指示不要記起","examples":[{"en":"Subjects are sometimes instructed not to recall their behaviour.","zh":"受試者有時被指示不要記起自己的行為。"},{"en":"To be instructed not to recall something means to be told not to remember it later.","zh":"be instructed not to recall something 指被告知之後不要記起某事。"},{"en":"A therapist might ask a patient not to focus on a painful image until they feel safe.","zh":"治療師可能要求病人在感到安全前，不要集中於痛苦畫面。"},{"en":"Instructions about memory can affect what a person tries to bring back to mind.","zh":"關於記憶的指示可以影響一個人嘗試回想甚麼。"},{"en":"This phrase describes a command related to remembering.","zh":"這個短語描述與記憶相關的命令。"}],"source":"72 - Just relax ….pdf","sourcePage":12},{"front":"re-emerging from the hypnotic state","meaning":"從催眠狀態中恢復過來","examples":[{"en":"Some subjects do not recall their actions after re-emerging from the hypnotic state.","zh":"有些受試者從催眠狀態中恢復過來後，不記得自己的行動。"},{"en":"Re-emerging from the hypnotic state means coming back from hypnosis into ordinary awareness.","zh":"re-emerging from the hypnotic state 指從催眠回到普通意識。"},{"en":"After deep relaxation, a patient may slowly return to normal attention and open their eyes.","zh":"深度放鬆後，病人可能慢慢回到正常注意力並睜開眼睛。"},{"en":"The shift back to ordinary awareness may change what the person remembers.","zh":"回到普通意識的轉變可能影響該人記得甚麼。"},{"en":"This phrase describes leaving hypnosis.","zh":"這個短語描述離開催眠狀態。"}],"source":"72 - Just relax ….pdf","sourcePage":12},{"front":"it appears that","meaning":"看起來似乎","examples":[{"en":"It appears that the subjects were powerless while hypnotised.","zh":"看起來似乎受試者被催眠時無力反抗。"},{"en":"It appears that means it seems so, though the full truth may be different.","zh":"it appears that 指看似如此，雖然完整真相可能不同。"},{"en":"It appears that the shop is closed, but the staff may only be on a break.","zh":"看起來似乎商店關門了，但職員可能只是休息。"},{"en":"This phrase is useful when describing an impression rather than a certain fact.","zh":"這個短語適合用於描述印象，而不是確定事實。"},{"en":"It often prepares the reader for a correction or explanation.","zh":"它常為之後的修正或解釋作準備。"}],"source":"72 - Just relax ….pdf","sourcePage":12},{"front":"powerless while hypnotised","meaning":"被催眠時無力反抗","examples":[{"en":"The subjects may appear powerless while hypnotised.","zh":"受試者被催眠時可能看似無力反抗。"},{"en":"Powerless while hypnotised means seeming unable to resist or control one’s actions during hypnosis.","zh":"powerless while hypnotised 指在催眠期間看似不能抗拒或控制自己的行動。"},{"en":"A stage performer may look powerless, though they have chosen to join the show.","zh":"舞台表演者可能看起來無力反抗，雖然他已選擇參與表演。"},{"en":"This appearance can make audiences misunderstand hypnosis as complete control.","zh":"這種表象可以令觀眾誤解催眠是完全控制。"},{"en":"This phrase describes how it seems, not necessarily what is truly happening.","zh":"這個短語描述看起來如何，而不一定是真實情況。"}],"source":"72 - Just relax ….pdf","sourcePage":12},{"front":"the point to remember","meaning":"要記住的一點","examples":[{"en":"The point to remember is that subjects choose to participate.","zh":"要記住的一點是，受試者選擇參與。"},{"en":"The point to remember is the main idea that readers should keep in mind.","zh":"point to remember 指讀者應記在心中的主要想法。"},{"en":"When learning grammar, the point to remember may be that meaning comes before decoration.","zh":"學文法時，要記住的一點可能是意思先於修飾。"},{"en":"Highlighting one key point helps prevent misunderstanding.","zh":"突出一個關鍵點有助防止誤解。"},{"en":"This phrase introduces the most important takeaway.","zh":"這個短語引入最重要的結論。"}],"source":"72 - Just relax ….pdf","sourcePage":12},{"front":"choose to participate","meaning":"選擇參與","examples":[{"en":"These individuals choose to participate in the performance.","zh":"這些人選擇參與表演。"},{"en":"To choose to participate means to decide freely to take part.","zh":"choose to participate 指自由決定參與。"},{"en":"Students may choose to participate in a debate club because they want speaking practice.","zh":"學生可能選擇參與辯論學會，因為他們想練習說話。"},{"en":"Participation is different when people volunteer rather than being forced.","zh":"當人們自願而不是被迫時，參與的性質不同。"},{"en":"This phrase emphasises personal choice.","zh":"這個短語強調個人選擇。"}],"source":"72 - Just relax ….pdf","sourcePage":12},{"front":"the success of hypnotism","meaning":"催眠術的成功","examples":[{"en":"The success of hypnotism depends on the subject’s willingness.","zh":"催眠術的成功取決於受試者的意願。"},{"en":"The success of hypnotism means whether hypnosis achieves its intended effect.","zh":"success of hypnotism 指催眠是否達到預期效果。"},{"en":"A therapy session may be more successful when the patient feels safe and willing.","zh":"當病人感到安全並願意合作，治療課節可能較成功。"},{"en":"If the subject refuses to cooperate, hypnotism may not work well.","zh":"如果受試者拒絕合作，催眠術可能效果不佳。"},{"en":"This phrase focuses on the conditions that make hypnosis effective.","zh":"這個短語著重使催眠有效的條件。"}],"source":"72 - Just relax ….pdf","sourcePage":12},{"front":"willingness of a person","meaning":"一個人的意願","examples":[{"en":"Hypnotism depends on the willingness of a person to be hypnotised.","zh":"催眠術取決於一個人被催眠的意願。"},{"en":"The willingness of a person is that person’s readiness or agreement to do something.","zh":"willingness of a person 指某人準備好或同意做某事。"},{"en":"A student’s willingness to practise speaking affects how quickly they improve.","zh":"學生練習說話的意願會影響他進步有多快。"},{"en":"Without willingness, even a good teacher or therapist may achieve little.","zh":"沒有意願，即使好老師或治療師也可能成效有限。"},{"en":"This phrase focuses on consent and readiness.","zh":"這個短語著重同意和準備程度。"}],"source":"72 - Just relax ….pdf","sourcePage":13},{"front":"different levels of hypnosis","meaning":"不同程度的催眠","examples":[{"en":"There are different levels of hypnosis that can be achieved.","zh":"可以達到不同程度的催眠。"},{"en":"Different levels of hypnosis are different depths or strengths of the hypnotic state.","zh":"different levels of hypnosis 指催眠狀態的不同深度或強度。"},{"en":"A patient may enter a light level of hypnosis for relaxation but a deeper level for pain control.","zh":"病人可能為放鬆進入較淺層催眠，為止痛進入較深層催眠。"},{"en":"The level matters because different depths can produce different effects.","zh":"程度重要，因為不同深度可以產生不同效果。"},{"en":"This phrase shows that hypnosis is not one single fixed state.","zh":"這個短語顯示催眠不是單一固定狀態。"}],"source":"72 - Just relax ….pdf","sourcePage":13},{"front":"deep hypnosis","meaning":"深度催眠","examples":[{"en":"Deep hypnosis can be induced to provide anaesthesia.","zh":"深度催眠可以被引發以提供麻醉。"},{"en":"Deep hypnosis is a strong hypnotic state that may produce powerful changes in awareness or pain response.","zh":"deep hypnosis 指強烈催眠狀態，可能對意識或痛楚反應產生強大改變。"},{"en":"In medical contexts, deep hypnosis may be considered when ordinary relaxation is not enough.","zh":"在醫療語境中，當普通放鬆不足夠時，可能考慮深度催眠。"},{"en":"Deeper hypnosis can make the body respond differently to pain or sensation.","zh":"更深層催眠可以令身體對痛楚或感覺作出不同反應。"},{"en":"This phrase contrasts with light hypnosis.","zh":"這個短語與淺層催眠形成對比。"}],"source":"72 - Just relax ….pdf","sourcePage":13},{"front":"provide anaesthesia for","meaning":"為……提供麻醉","examples":[{"en":"Deep hypnosis can provide anaesthesia for surgery.","zh":"深度催眠可以為手術提供麻醉。"},{"en":"To provide anaesthesia for something means to reduce or block pain during that procedure.","zh":"provide anaesthesia for something 指在某程序中減少或阻斷痛楚。"},{"en":"Dentists provide anaesthesia for tooth removal so patients do not feel sharp pain.","zh":"牙醫為拔牙提供麻醉，讓病人不感到尖銳痛楚。"},{"en":"Anaesthesia allows doctors to perform painful procedures more safely.","zh":"麻醉讓醫生更安全地進行痛楚程序。"},{"en":"This phrase identifies what the pain control is used for.","zh":"這個短語指出止痛控制用於甚麼。"}],"source":"72 - Just relax ….pdf","sourcePage":13},{"front":"surgery, childbirth or dentistry","meaning":"手術、分娩或牙科治療","examples":[{"en":"Hypnosis may provide anaesthesia for surgery, childbirth or dentistry.","zh":"催眠可以為手術、分娩或牙科治療提供麻醉。"},{"en":"Surgery, childbirth or dentistry are medical situations where pain control may be needed.","zh":"surgery, childbirth or dentistry 指可能需要痛楚控制的醫療情況。"},{"en":"A patient may feel anxious before dentistry because of drilling or injections.","zh":"病人可能因鑽牙或打針而在牙科治療前感到焦慮。"},{"en":"Pain control matters in these situations because the body may experience strong discomfort.","zh":"在這些情況中，痛楚控制很重要，因為身體可能經歷強烈不適。"},{"en":"This phrase lists medical contexts where hypnosis may be used.","zh":"這個短語列出催眠可能被使用的醫療語境。"}],"source":"72 - Just relax ….pdf","sourcePage":13},{"front":"contrast with","meaning":"與……形成對比","examples":[{"en":"Deep hypnosis contrasts with a lighter state of hypnosis.","zh":"深度催眠與較淺層的催眠狀態形成對比。"},{"en":"To contrast with something means to be clearly different from it.","zh":"contrast with something 指與某事明顯不同。"},{"en":"A quiet library contrasts with a noisy school playground.","zh":"安靜圖書館與嘈雜操場形成對比。"},{"en":"Contrast helps readers see differences between two related ideas.","zh":"對比幫助讀者看見兩個相關概念之間的差異。"},{"en":"This phrase is used when comparing opposite or different features.","zh":"這個短語用於比較相反或不同特徵。"}],"source":"72 - Just relax ….pdf","sourcePage":13},{"front":"a lighter state of hypnosis","meaning":"較淺層的催眠狀態","examples":[{"en":"A lighter state of hypnosis deeply relaxes the patient.","zh":"較淺層的催眠狀態會令病人深度放鬆。"},{"en":"A lighter state of hypnosis is a less deep hypnotic condition used mainly for calmness and focus.","zh":"lighter state of hypnosis 指較不深層的催眠狀態，主要用於平靜和專注。"},{"en":"A patient in light hypnosis may still follow simple instructions and speak normally.","zh":"處於淺層催眠的病人仍可能跟從簡單指示並正常說話。"},{"en":"Light hypnosis can help reduce distress without making the person deeply anaesthetised.","zh":"淺層催眠可以幫助減少痛苦，而不令該人進入深度麻醉狀態。"},{"en":"This phrase contrasts with deep hypnosis used for stronger effects.","zh":"這個短語與用於較強效果的深度催眠形成對比。"}],"source":"72 - Just relax ….pdf","sourcePage":13},{"front":"deeply relax the patient","meaning":"令病人深度放鬆","examples":[{"en":"A lighter state of hypnosis deeply relaxes the patient.","zh":"較淺層的催眠狀態會令病人深度放鬆。"},{"en":"To deeply relax the patient means to make the patient feel very calm in body and mind.","zh":"deeply relax the patient 指令病人在身心上都感到非常平靜。"},{"en":"A nurse may use quiet breathing exercises to deeply relax a nervous patient before treatment.","zh":"護士可能在治療前使用安靜呼吸練習，令緊張病人深度放鬆。"},{"en":"Deep relaxation can reduce fear and help patients discuss difficult experiences.","zh":"深度放鬆可以減少恐懼，並幫助病人討論困難經歷。"},{"en":"This phrase focuses on strong calmness, not unconsciousness.","zh":"這個短語著重強烈平靜，而不是失去意識。"}],"source":"72 - Just relax ….pdf","sourcePage":13},{"front":"follow simple directions","meaning":"跟從簡單指示","examples":[{"en":"The patient can follow simple directions under light hypnosis.","zh":"病人在淺層催眠下可以跟從簡單指示。"},{"en":"To follow simple directions means to understand and do basic instructions.","zh":"follow simple directions 指理解並執行基本指示。"},{"en":"A child can follow simple directions such as “sit down” and “open your book”.","zh":"孩子可以跟從「坐下」和「打開書本」等簡單指示。"},{"en":"Following directions shows that the person is still aware enough to respond.","zh":"能跟從指示顯示該人仍有足夠意識去回應。"},{"en":"This phrase describes basic cooperation.","zh":"這個短語描述基本合作。"}],"source":"72 - Just relax ….pdf","sourcePage":13},{"front":"the latter state","meaning":"後者狀態","examples":[{"en":"The latter state may be used to treat mental health problems.","zh":"後者狀態可能被用來治療精神健康問題。"},{"en":"The latter state means the second of two states just mentioned.","zh":"latter state 指剛提到的兩種狀態中的第二種。"},{"en":"If a teacher compares online lessons with classroom lessons, “the latter” means classroom lessons.","zh":"如果老師比較網上課堂和面授課堂，the latter 指面授課堂。"},{"en":"This phrase avoids repeating the full name of the second item.","zh":"這個短語避免重複第二項的完整名稱。"},{"en":"It helps connect a sentence back to a previous comparison.","zh":"它幫助把句子連回前面的比較。"}],"source":"72 - Just relax ….pdf","sourcePage":13},{"front":"mental health problems","meaning":"精神健康問題","examples":[{"en":"Hypnosis may be used to treat mental health problems.","zh":"催眠可能被用來治療精神健康問題。"},{"en":"Mental health problems are difficulties involving mood, thoughts, stress, fear, or emotional wellbeing.","zh":"mental health problems 指涉及情緒、思想、壓力、恐懼或心理健康的困難。"},{"en":"Anxiety before school every day can become a mental health problem if it affects sleep and learning.","zh":"如果每天上學前的焦慮影響睡眠和學習，就可能成為精神健康問題。"},{"en":"Treatment can help people manage symptoms and recover daily functioning.","zh":"治療可以幫助人管理症狀並恢復日常功能。"},{"en":"This phrase refers to psychological difficulties, not personal weakness.","zh":"這個短語指心理困難，而不是個人軟弱。"}],"source":"72 - Just relax ….pdf","sourcePage":14},{"front":"allow patients to","meaning":"讓病人能夠","examples":[{"en":"Light hypnosis allows patients to feel calm.","zh":"淺層催眠讓病人能夠感到平靜。"},{"en":"To allow patients to do something means to make it possible for them to do it.","zh":"allow patients to do something 指令病人能夠做某事。"},{"en":"Clear explanations allow patients to ask better questions before treatment.","zh":"清楚解釋讓病人能夠在治療前提出更好的問題。"},{"en":"When patients feel safe, they may be able to face difficult memories more gently.","zh":"當病人感到安全，他們可能能夠更溫和地面對困難回憶。"},{"en":"This phrase shows what a treatment or condition makes possible.","zh":"這個短語顯示治療或情況使甚麼成為可能。"}],"source":"72 - Just relax ….pdf","sourcePage":14},{"front":"feel calm","meaning":"感到平靜","examples":[{"en":"Patients can feel calm while thinking about distressing memories.","zh":"病人在思考令人痛苦的回憶時，可以感到平靜。"},{"en":"To feel calm means to feel peaceful, steady, and less afraid or upset.","zh":"feel calm 指感到平和、穩定，並較少害怕或不安。"},{"en":"A student may feel calm before an exam after breathing slowly for two minutes.","zh":"學生在考試前慢慢呼吸兩分鐘後，可能感到平靜。"},{"en":"Calmness can help people think more clearly about difficult situations.","zh":"平靜可以幫助人更清楚思考困難情況。"},{"en":"This phrase describes emotional steadiness.","zh":"這個短語描述情緒穩定。"}],"source":"72 - Just relax ….pdf","sourcePage":14},{"front":"while simultaneously thinking about","meaning":"同時思考……","examples":[{"en":"Patients can feel calm while simultaneously thinking about painful memories.","zh":"病人可以感到平靜，同時思考痛苦回憶。"},{"en":"While simultaneously thinking about means at the same time as thinking about something.","zh":"while simultaneously thinking about 指在思考某事的同時。"},{"en":"A student may listen to feedback while simultaneously thinking about how to improve the essay.","zh":"學生可能一邊聽回饋，一邊思考如何改善文章。"},{"en":"Doing two mental actions together can help people face difficult material more safely.","zh":"同時進行兩種心理活動，可以幫助人更安全地面對困難內容。"},{"en":"This phrase emphasises two things happening at once.","zh":"這個短語強調兩件事同時發生。"}],"source":"72 - Just relax ….pdf","sourcePage":14},{"front":"distressing feelings","meaning":"令人痛苦的感受","examples":[{"en":"Patients may think about distressing feelings under hypnosis.","zh":"病人在催眠下可能思考令人痛苦的感受。"},{"en":"Distressing feelings are emotions that cause sadness, fear, anxiety, or pain.","zh":"distressing feelings 指造成悲傷、恐懼、焦慮或痛苦的情緒。"},{"en":"A student may have distressing feelings after being bullied at school.","zh":"學生被欺凌後可能有令人痛苦的感受。"},{"en":"Talking about distressing feelings calmly can help people understand and manage them.","zh":"平靜地談論痛苦感受，可以幫助人理解和管理它們。"},{"en":"This phrase describes emotionally painful feelings.","zh":"這個短語描述情緒上令人痛苦的感受。"}],"source":"72 - Just relax ….pdf","sourcePage":14},{"front":"painful memories","meaning":"痛苦回憶","examples":[{"en":"Hypnosis may help patients deal with painful memories.","zh":"催眠可能幫助病人處理痛苦回憶。"},{"en":"Painful memories are memories that still cause sadness, fear, shame, or emotional pain.","zh":"painful memories 指仍會造成悲傷、恐懼、羞愧或情緒痛楚的記憶。"},{"en":"A person may have painful memories of an accident or a difficult childhood event.","zh":"一個人可能有關於意外或困難童年事件的痛苦回憶。"},{"en":"If painful memories are avoided completely, they may continue to affect daily life.","zh":"如果痛苦回憶被完全迴避，它們可能繼續影響日常生活。"},{"en":"This phrase refers to emotionally difficult past experiences.","zh":"這個短語指情緒上困難的過去經驗。"}],"source":"72 - Just relax ….pdf","sourcePage":14},{"front":"learn new responses to","meaning":"學習對……作出新的反應","examples":[{"en":"Patients can learn new responses to difficult situations.","zh":"病人可以學習對困難情況作出新的反應。"},{"en":"To learn new responses to something means to develop different ways of reacting to it.","zh":"learn new responses to something 指發展出對某事的不同反應方式。"},{"en":"A student can learn new responses to criticism by asking for examples instead of feeling attacked.","zh":"學生可以學習對批評作出新反應，例如要求例子，而不是感到被攻擊。"},{"en":"New responses can reduce fear, anger, or avoidance in familiar situations.","zh":"新反應可以在熟悉情況中減少恐懼、憤怒或逃避。"},{"en":"This phrase focuses on changing reaction patterns.","zh":"這個短語著重改變反應模式。"}],"source":"72 - Just relax ….pdf","sourcePage":14},{"front":"come up with solutions to","meaning":"想出……的解決方法","examples":[{"en":"Patients may come up with solutions to their problems.","zh":"病人可能想出自己問題的解決方法。"},{"en":"To come up with solutions to problems means to think of ways to solve them.","zh":"come up with solutions to problems 指想到解決問題的方法。"},{"en":"A class may come up with solutions to noise by making clearer group-work rules.","zh":"班級可能透過制定更清楚的小組規則，想出解決噪音的方法。"},{"en":"Calm thinking can help people see options they missed when they were upset.","zh":"平靜思考可以幫助人看見情緒激動時錯過的選項。"},{"en":"This phrase describes creating practical answers.","zh":"這個短語描述創造實際答案。"}],"source":"72 - Just relax ….pdf","sourcePage":14},{"front":"help recovery from","meaning":"幫助從……中康復","examples":[{"en":"Hypnosis can help recovery from psychological conditions.","zh":"催眠可以幫助從心理狀況中康復。"},{"en":"To help recovery from something means to support the process of getting better after it.","zh":"help recovery from something 指支援從某事中好轉或恢復的過程。"},{"en":"Rest and physiotherapy can help recovery from a sports injury.","zh":"休息和物理治療可以幫助從運動創傷中康復。"},{"en":"Emotional support can help recovery when a person is dealing with fear or sadness.","zh":"當一個人處理恐懼或悲傷時，情感支援可以幫助康復。"},{"en":"This phrase focuses on assistance during healing.","zh":"這個短語著重康復期間的協助。"}],"source":"72 - Just relax ….pdf","sourcePage":14},{"front":"psychological conditions","meaning":"心理疾病；心理狀況","examples":[{"en":"Hypnosis may help recovery from psychological conditions.","zh":"催眠可能幫助從心理疾病中康復。"},{"en":"Psychological conditions are mental or emotional health problems that affect thoughts, feelings, or behaviour.","zh":"psychological conditions 指影響思想、情緒或行為的心理或情感健康問題。"},{"en":"Anxiety, depression, and phobias are examples of psychological conditions.","zh":"焦慮、抑鬱和恐懼症都是心理狀況的例子。"},{"en":"These conditions may need professional treatment, support, and time.","zh":"這些狀況可能需要專業治療、支援和時間。"},{"en":"This phrase is broader and more formal than “mental problems”.","zh":"這個短語比 mental problems 更廣泛也更正式。"}],"source":"72 - Just relax ….pdf","sourcePage":14},{"front":"anxiety","meaning":"焦慮","examples":[{"en":"Hypnosis may help people suffering from anxiety.","zh":"催眠可能幫助受焦慮困擾的人。"},{"en":"Anxiety is a strong feeling of worry, fear, or nervousness that can affect daily life.","zh":"anxiety 指強烈擔心、恐懼或緊張感，並可能影響日常生活。"},{"en":"A student may feel anxiety before an oral exam even after preparing well.","zh":"學生即使準備充分，也可能在口試前感到焦慮。"},{"en":"Anxiety can cause sweating, fast breathing, and difficulty concentrating.","zh":"焦慮可以造成出汗、呼吸急促和難以集中。"},{"en":"This word describes more than ordinary concern when the worry becomes strong or persistent.","zh":"當擔憂變得強烈或持續時，這個詞不只是普通擔心。"}],"source":"72 - Just relax ….pdf","sourcePage":15},{"front":"depression","meaning":"抑鬱","examples":[{"en":"Hypnosis may help recovery from depression.","zh":"催眠可能幫助從抑鬱中康復。"},{"en":"Depression is a mental health condition involving lasting low mood, loss of interest, and reduced energy.","zh":"depression 指一種精神健康狀況，涉及持續情緒低落、失去興趣和能量下降。"},{"en":"A person with depression may stop enjoying hobbies they once liked.","zh":"抑鬱的人可能不再享受自己曾經喜歡的嗜好。"},{"en":"Depression can affect sleep, appetite, work, and relationships.","zh":"抑鬱可以影響睡眠、食慾、工作和人際關係。"},{"en":"This word refers to a serious condition, not simply a bad day.","zh":"這個詞指嚴重狀況，而不是單純心情差一天。"}],"source":"72 - Just relax ….pdf","sourcePage":15},{"front":"phobias","meaning":"恐懼症","examples":[{"en":"Hypnosis may help patients with phobias.","zh":"催眠可能幫助有恐懼症的病人。"},{"en":"Phobias are strong and irrational fears of particular things, places, or situations.","zh":"phobias 指對特定事物、地方或情況的強烈而非理性恐懼。"},{"en":"A person with a phobia of lifts may avoid tall buildings even when the lift is safe.","zh":"有升降機恐懼症的人，即使升降機安全，也可能避開高樓。"},{"en":"Phobias can limit daily life because fear controls choices.","zh":"恐懼症可以限制日常生活，因為恐懼控制了選擇。"},{"en":"This word describes intense fear, not mild dislike.","zh":"這個詞描述強烈恐懼，而不是輕微不喜歡。"}],"source":"72 - Just relax ….pdf","sourcePage":15},{"front":"traumatic incidents","meaning":"創傷事件","examples":[{"en":"Some people lose memory after traumatic incidents.","zh":"有些人在創傷事件後失去記憶。"},{"en":"Traumatic incidents are shocking or harmful events that cause deep emotional distress.","zh":"traumatic incidents 指令人震驚或受傷、造成深層情緒痛苦的事件。"},{"en":"A serious car accident can be a traumatic incident for both the driver and passengers.","zh":"嚴重車禍可以對司機和乘客都是創傷事件。"},{"en":"Trauma can affect memory because the mind may protect itself from pain.","zh":"創傷可以影響記憶，因為心智可能保護自己免受痛苦。"},{"en":"This phrase refers to events that leave strong psychological impact.","zh":"這個短語指留下強烈心理影響的事件。"}],"source":"72 - Just relax ….pdf","sourcePage":15},{"front":"memory may be blocked","meaning":"記憶可能被封鎖","examples":[{"en":"After traumatic incidents, memory of the events may be blocked.","zh":"創傷事件後，對事件的記憶可能被封鎖。"},{"en":"Memory may be blocked means a person may be unable to recall something, often because it is painful or stressful.","zh":"memory may be blocked 指一個人可能無法回想某事，常因它痛苦或壓力大。"},{"en":"A child may block memory of a frightening accident and remember only small pieces later.","zh":"孩子可能封鎖對可怕意外的記憶，之後只記得小片段。"},{"en":"Blocked memory can protect a person temporarily but may also make recovery harder.","zh":"被封鎖的記憶可以暫時保護一個人，但也可能令康復更困難。"},{"en":"This phrase describes memory becoming inaccessible.","zh":"這個短語描述記憶變得無法取得。"}],"source":"72 - Just relax ….pdf","sourcePage":15},{"front":"develop amnesia","meaning":"患上失憶症","examples":[{"en":"Some soldiers develop amnesia after wartime experiences.","zh":"有些士兵在戰時經歷後患上失憶症。"},{"en":"To develop amnesia means to begin suffering from memory loss.","zh":"develop amnesia 指開始出現記憶喪失問題。"},{"en":"A patient may develop amnesia after a head injury or severe emotional shock.","zh":"病人在頭部受傷或嚴重情緒衝擊後，可能患上失憶症。"},{"en":"Amnesia can make it difficult to remember events, people, or periods of life.","zh":"失憶症可以令人難以記起事件、人物或人生時期。"},{"en":"This phrase describes the onset of memory loss.","zh":"這個短語描述記憶喪失的開始。"}],"source":"72 - Just relax ….pdf","sourcePage":15},{"front":"loss of memory","meaning":"記憶喪失","examples":[{"en":"Amnesia means loss of memory.","zh":"amnesia 的意思是記憶喪失。"},{"en":"Loss of memory is the inability to remember information, events, or experiences.","zh":"loss of memory 指無法記住資訊、事件或經驗。"},{"en":"An elderly person may experience some loss of memory, such as forgetting recent appointments.","zh":"長者可能經歷一些記憶喪失，例如忘記近期約會。"},{"en":"Serious memory loss can affect work, relationships, and personal safety.","zh":"嚴重記憶喪失可以影響工作、人際關係和個人安全。"},{"en":"This phrase explains the basic meaning of amnesia.","zh":"這個短語解釋 amnesia 的基本意思。"}],"source":"72 - Just relax ….pdf","sourcePage":15},{"front":"as a result of","meaning":"由於；作為……的結果","examples":[{"en":"Some soldiers develop amnesia as a result of wartime experiences.","zh":"有些士兵由於戰時經歷而患上失憶症。"},{"en":"As a result of means because of something that happened.","zh":"as a result of 指因某事發生而造成。"},{"en":"A student may miss school as a result of illness.","zh":"學生可能由於生病而缺課。"},{"en":"This phrase clearly links a cause with an effect.","zh":"這個短語清楚把原因與結果連繫起來。"},{"en":"It is often used when explaining why a problem happened.","zh":"它常用於解釋問題為何發生。"}],"source":"72 - Just relax ….pdf","sourcePage":15},{"front":"during wartime","meaning":"在戰時","examples":[{"en":"Some soldiers lose memories as a result of experiences during wartime.","zh":"有些士兵因戰時經歷而失去記憶。"},{"en":"During wartime means in a period when a war is happening.","zh":"during wartime 指在戰爭發生期間。"},{"en":"During wartime, families may face fear, shortages, and separation.","zh":"在戰時，家庭可能面對恐懼、短缺和分離。"},{"en":"Extreme experiences during war can affect both body and mind.","zh":"戰爭中的極端經歷可以影響身體和心智。"},{"en":"This phrase gives the historical situation in which events occur.","zh":"這個短語提供事件發生的歷史情況。"}],"source":"72 - Just relax ….pdf","sourcePage":15},{"front":"through hypnosis","meaning":"透過催眠","examples":[{"en":"Through hypnosis, repressed memories can be retrieved.","zh":"透過催眠，被壓抑的記憶可以被取回。"},{"en":"Through hypnosis means by using hypnosis as the method.","zh":"through hypnosis 指以催眠作為方法。"},{"en":"Through careful counselling, a patient may learn to manage panic attacks.","zh":"透過仔細輔導，病人可能學會管理恐慌發作。"},{"en":"The method matters because different treatments produce different kinds of support.","zh":"方法很重要，因為不同治療提供不同種類支援。"},{"en":"This phrase identifies hypnosis as the route or tool used.","zh":"這個短語指出催眠是所用途徑或工具。"}],"source":"72 - Just relax ….pdf","sourcePage":15},{"front":"repressed memories","meaning":"被壓抑的記憶","examples":[{"en":"Repressed memories can be retrieved and treated through hypnosis.","zh":"被壓抑的記憶可以透過催眠被取回並處理。"},{"en":"Repressed memories are painful memories pushed out of conscious awareness.","zh":"repressed memories 指被推離清醒意識的痛苦記憶。"},{"en":"A person may not remember a frightening childhood event because the memory is repressed.","zh":"一個人可能不記得可怕童年事件，因為該記憶被壓抑。"},{"en":"Repressed memories may continue to affect feelings even when they are not clearly recalled.","zh":"被壓抑的記憶即使未被清楚回想，仍可能影響感受。"},{"en":"This phrase refers to hidden memories linked with distress.","zh":"這個短語指與痛苦相關的隱藏記憶。"}],"source":"72 - Just relax ….pdf","sourcePage":16},{"front":"be retrieved and treated","meaning":"被取回並處理","examples":[{"en":"Repressed memories can be retrieved and treated.","zh":"被壓抑的記憶可以被取回並處理。"},{"en":"To be retrieved and treated means to be brought back to awareness and then dealt with therapeutically.","zh":"be retrieved and treated 指被帶回意識中，然後透過治療處理。"},{"en":"A lost file can be retrieved from a backup, but emotional memories require careful treatment.","zh":"遺失文件可以從備份中取回，但情緒記憶需要小心處理。"},{"en":"Once a painful memory is retrieved, support may help the person process it safely.","zh":"一旦痛苦記憶被取回，支援可能幫助該人安全處理它。"},{"en":"This phrase combines recovery of memory with healing work.","zh":"這個短語結合記憶取回和療癒工作。"}],"source":"72 - Just relax ….pdf","sourcePage":16},{"front":"a variation of this treatment","meaning":"這種治療的一個變化形式","examples":[{"en":"A variation of this treatment involves age regression.","zh":"這種治療的一個變化形式涉及年齡回溯。"},{"en":"A variation of this treatment is a slightly different form of the same general method.","zh":"variation of this treatment 指同一大方法中稍為不同的形式。"},{"en":"A teacher may use a variation of a reading activity for younger students.","zh":"老師可能為較年幼學生使用閱讀活動的一個變化形式。"},{"en":"Variations allow a method to be adjusted for different needs.","zh":"變化形式讓方法可按不同需要調整。"},{"en":"This phrase introduces a related but modified version.","zh":"這個短語引入相關但經修改的版本。"}],"source":"72 - Just relax ….pdf","sourcePage":16},{"front":"age regression","meaning":"年齡回溯","examples":[{"en":"Age regression takes the patient back to a specific age.","zh":"年齡回溯把病人帶回某個特定年齡。"},{"en":"Age regression is a hypnotic technique in which a person is guided to imagine or recall an earlier age.","zh":"age regression 指一種催眠技巧，引導人想像或回憶較早年齡。"},{"en":"A therapist may use age regression to explore memories from childhood.","zh":"治療師可能使用年齡回溯來探索童年記憶。"},{"en":"Returning mentally to an earlier time may help a patient understand old feelings.","zh":"心理上回到較早時間，可能幫助病人理解舊有感受。"},{"en":"This phrase refers to a therapeutic technique, not actual physical youth.","zh":"這個短語指治療技巧，而不是身體真的變年輕。"}],"source":"72 - Just relax ….pdf","sourcePage":16},{"front":"take the patient back to","meaning":"帶病人回到……","examples":[{"en":"The hypnotist takes the patient back to a specific age.","zh":"催眠師帶病人回到某個特定年齡。"},{"en":"To take the patient back to a time means to guide the patient to remember or imagine that period.","zh":"take the patient back to a time 指引導病人記起或想像那個時期。"},{"en":"A photograph may take someone back to their first day at school.","zh":"一張照片可能把某人帶回上學第一天。"},{"en":"Returning mentally to the past can bring old emotions into awareness.","zh":"心理上回到過去可以把舊情緒帶回意識。"},{"en":"This phrase describes guided memory or imagination.","zh":"這個短語描述被引導的記憶或想像。"}],"source":"72 - Just relax ….pdf","sourcePage":16},{"front":"a specific age","meaning":"某個特定年齡","examples":[{"en":"The patient may be taken back to a specific age.","zh":"病人可能被帶回某個特定年齡。"},{"en":"A specific age is one particular age, not a general period of life.","zh":"specific age 指某一個明確年齡，而不是人生中一個籠統時期。"},{"en":"A doctor may ask what symptoms a child had at a specific age, such as age six.","zh":"醫生可能詢問孩子在某個特定年齡，例如六歲時，有甚麼症狀。"},{"en":"Choosing a specific age helps focus memory on one stage of life.","zh":"選擇特定年齡有助把記憶集中於人生某一階段。"},{"en":"This phrase gives a precise point in someone’s past.","zh":"這個短語給出某人過去的一個精確時間點。"}],"source":"72 - Just relax ….pdf","sourcePage":16},{"front":"in this way","meaning":"以這種方式","examples":[{"en":"In this way, patients may remember events from that time.","zh":"以這種方式，病人可能記起當時的事件。"},{"en":"In this way means by using the method just described.","zh":"in this way 指使用剛才描述的方法。"},{"en":"A student can underline key words before reading the options; in this way, they avoid careless mistakes.","zh":"學生可以先畫下關鍵詞再讀選項；以這種方式，他們可避免粗心錯誤。"},{"en":"This phrase connects a method with its result.","zh":"這個短語把方法與結果連繫起來。"},{"en":"It helps show how one step leads to the next.","zh":"它幫助顯示一步如何導致下一步。"}],"source":"72 - Just relax ….pdf","sourcePage":16},{"front":"current well-being","meaning":"目前身心健康","examples":[{"en":"Past events may affect a patient’s current well-being.","zh":"過去事件可能影響病人目前身心健康。"},{"en":"Current well-being is a person’s present state of physical, mental, and emotional health.","zh":"current well-being 指一個人目前的身體、心理和情緒健康狀態。"},{"en":"A student’s current well-being may improve when sleep, friendships, and workload are balanced.","zh":"當睡眠、友誼和工作量平衡時，學生目前身心健康可能改善。"},{"en":"Painful memories can affect present well-being even if they happened long ago.","zh":"痛苦回憶即使很久以前發生，也可以影響目前身心健康。"},{"en":"This phrase focuses on how someone is doing now.","zh":"這個短語著重某人現在的狀態。"}],"source":"72 - Just relax ….pdf","sourcePage":16},{"front":"physicians","meaning":"醫生","examples":[{"en":"Physicians have made use of hypnosis in medical treatment.","zh":"醫生曾在醫療中利用催眠。"},{"en":"Physicians are medical doctors who diagnose and treat illness.","zh":"physicians 指診斷和治療疾病的醫生。"},{"en":"A physician may check symptoms, order tests, and recommend treatment.","zh":"醫生可能檢查症狀、安排檢測並建議治療。"},{"en":"Physicians use evidence and clinical judgement to decide what helps patients.","zh":"醫生使用證據和臨床判斷來決定甚麼能幫助病人。"},{"en":"This word is more formal than “doctors”.","zh":"這個詞比 doctors 更正式。"}],"source":"72 - Just relax ….pdf","sourcePage":16},{"front":"make use of","meaning":"利用","examples":[{"en":"Physicians have made use of the abilities of hypnotised patients.","zh":"醫生利用了受催眠病人的能力。"},{"en":"To make use of something means to use it for a practical purpose.","zh":"make use of something 指為實際目的使用某事物。"},{"en":"A teacher may make use of students’ mistakes to explain a grammar rule.","zh":"老師可能利用學生錯誤來解釋文法規則。"},{"en":"Making good use of an ability can solve a problem more effectively.","zh":"善用某種能力可以更有效解決問題。"},{"en":"This phrase focuses on using something that is available.","zh":"這個短語著重使用已有的東西。"}],"source":"72 - Just relax ….pdf","sourcePage":16},{"front":"remain in a given position","meaning":"保持在指定姿勢","examples":[{"en":"A hypnotised person may remain in a given position for a long time.","zh":"受催眠者可能長時間保持在指定姿勢。"},{"en":"To remain in a given position means to stay in a particular posture or place.","zh":"remain in a given position 指停留在某個特定姿勢或位置。"},{"en":"A patient having an X-ray may need to remain in a given position until the image is taken.","zh":"拍 X 光的病人可能需要保持在指定姿勢，直到影像完成。"},{"en":"Staying still can help doctors carry out delicate treatment safely.","zh":"保持不動可以幫助醫生安全進行精細治療。"},{"en":"This phrase describes controlled stillness.","zh":"這個短語描述受控制的靜止。"}],"source":"72 - Just relax ….pdf","sourcePage":17},{"front":"for long periods of time","meaning":"長時間","examples":[{"en":"Some patients can remain still for long periods of time.","zh":"有些病人可以長時間保持不動。"},{"en":"For long periods of time means for many minutes, hours, days, or longer.","zh":"for long periods of time 指持續許多分鐘、小時、日子或更久。"},{"en":"Office workers who sit for long periods of time may develop back pain.","zh":"長時間坐着的辦公室員工可能出現背痛。"},{"en":"Staying in one position for too long can become uncomfortable without support.","zh":"如果沒有支援，長時間保持同一姿勢可能變得不舒服。"},{"en":"This phrase emphasises extended duration.","zh":"這個短語強調持續時間很長。"}],"source":"72 - Just relax ….pdf","sourcePage":17},{"front":"in one case","meaning":"在一個個案中","examples":[{"en":"In one case, doctors grafted skin onto a patient’s damaged foot.","zh":"在一個個案中，醫生把皮膚移植到病人受損的腳上。"},{"en":"In one case introduces one particular example from a larger set of examples.","zh":"in one case 用來引入較大例子集合中的一個特定例子。"},{"en":"In one case, a school solved lateness by changing the bus timetable.","zh":"在一個個案中，學校透過改變巴士時間表解決遲到問題。"},{"en":"A single case can illustrate how a method works in practice.","zh":"單一個案可以說明方法在實際中如何運作。"},{"en":"This phrase helps move from general discussion to a specific example.","zh":"這個短語幫助由一般討論轉到具體例子。"}],"source":"72 - Just relax ….pdf","sourcePage":17},{"front":"graft skin onto","meaning":"將皮膚移植到……上","examples":[{"en":"Doctors had to graft skin onto a patient’s foot.","zh":"醫生必須將皮膚移植到病人的腳上。"},{"en":"To graft skin onto a body part means to move healthy skin there to repair damaged tissue.","zh":"graft skin onto a body part 指把健康皮膚移到該部位，以修復受損組織。"},{"en":"Burn victims may need doctors to graft skin onto injured areas.","zh":"燒傷者可能需要醫生將皮膚移植到受傷部位。"},{"en":"Skin grafting helps cover wounds and support healing.","zh":"皮膚移植有助覆蓋傷口並支援癒合。"},{"en":"This phrase describes a medical repair procedure.","zh":"這個短語描述醫療修復程序。"}],"source":"72 - Just relax ….pdf","sourcePage":17},{"front":"badly damaged foot","meaning":"嚴重受損的腳","examples":[{"en":"The patient had a badly damaged foot.","zh":"該病人有一隻嚴重受損的腳。"},{"en":"A badly damaged foot is a foot that has been seriously injured or harmed.","zh":"badly damaged foot 指受到嚴重傷害或損壞的腳。"},{"en":"A worker may have a badly damaged foot after a heavy object falls on it.","zh":"重物跌在腳上後，工人可能有一隻嚴重受損的腳。"},{"en":"Serious damage may require surgery, rest, or long-term treatment.","zh":"嚴重損傷可能需要手術、休息或長期治療。"},{"en":"This phrase describes severe injury, not a minor bruise.","zh":"這個短語描述嚴重受傷，而不是輕微瘀傷。"}],"source":"72 - Just relax ….pdf","sourcePage":17},{"front":"the person’s abdomen","meaning":"該人的腹部","examples":[{"en":"Skin from the person’s abdomen was grafted onto his arm.","zh":"來自該人腹部的皮膚被移植到他的手臂上。"},{"en":"The person’s abdomen is the front part of the body between the chest and the hips.","zh":"person’s abdomen 指人體胸部與臀部之間的前方部位。"},{"en":"Doctors may examine the abdomen if a patient reports stomach pain.","zh":"如果病人報稱胃痛，醫生可能檢查腹部。"},{"en":"Skin from the abdomen may be used because it can provide enough tissue for grafting.","zh":"腹部皮膚可能被使用，因為它能提供足夠組織作移植。"},{"en":"This phrase identifies a specific body area.","zh":"這個短語指出特定身體部位。"}],"source":"72 - Just relax ….pdf","sourcePage":17},{"front":"be transferred to","meaning":"被轉移到","examples":[{"en":"The graft was later transferred to the patient’s foot.","zh":"移植物後來被轉移到病人的腳上。"},{"en":"To be transferred to somewhere means to be moved from one place to another.","zh":"be transferred to somewhere 指從一個地方被移到另一個地方。"},{"en":"A student may be transferred to another class if the timetable changes.","zh":"如果時間表改變，學生可能被轉到另一班。"},{"en":"Transferring tissue or material requires careful handling to avoid damage.","zh":"轉移組織或材料需要小心處理，以免損壞。"},{"en":"This phrase focuses on movement from one location to another.","zh":"這個短語著重由一個位置移到另一個位置。"}],"source":"72 - Just relax ….pdf","sourcePage":17},{"front":"hold something tightly in position","meaning":"將……牢牢固定在位置上","examples":[{"en":"The patient held his arm tightly in position.","zh":"病人將手臂牢牢固定在位置上。"},{"en":"To hold something tightly in position means to keep it firmly in the required place.","zh":"hold something tightly in position 指把某物穩固地保持在所需位置。"},{"en":"A nurse may ask a patient to hold a bandage tightly in position to stop bleeding.","zh":"護士可能要求病人將繃帶牢牢固定在位置上以止血。"},{"en":"Holding something steady can prevent movement that might damage healing tissue.","zh":"穩定固定某物可以防止移動損害正在癒合的組織。"},{"en":"This phrase describes firm physical control.","zh":"這個短語描述牢固的身體控制。"}],"source":"72 - Just relax ….pdf","sourcePage":17},{"front":"over his abdomen","meaning":"在他的腹部上方","examples":[{"en":"The patient held his arm over his abdomen for three weeks.","zh":"病人將手臂放在他的腹部上方三星期。"},{"en":"Over his abdomen means above or across the front part of his body between the chest and hips.","zh":"over his abdomen 指在他胸部與臀部之間身體前方的上方或橫跨其上。"},{"en":"A person with stomach pain may hold a hot water bottle over the abdomen.","zh":"胃痛的人可能把熱水袋放在腹部上方。"},{"en":"Keeping an arm over the abdomen for a long time can normally be uncomfortable.","zh":"長時間把手臂放在腹部上方通常可能不舒服。"},{"en":"This phrase gives the position of the arm.","zh":"這個短語給出手臂的位置。"}],"source":"72 - Just relax ….pdf","sourcePage":17},{"front":"at no time","meaning":"從來沒有；在任何時候都沒有","examples":[{"en":"At no time did the patient feel uncomfortable.","zh":"病人在任何時候都沒有感到不適。"},{"en":"At no time means never or not at any moment.","zh":"at no time 指從來沒有，或任何時刻都沒有。"},{"en":"At no time should students leave the exam room without permission.","zh":"學生在任何時候都不應未經許可離開試場。"},{"en":"This phrase is formal and often used for strong emphasis.","zh":"這個短語較正式，常用作強調。"},{"en":"When it begins a sentence, the word order often changes.","zh":"當它放在句首時，英文詞序常會改變。"}],"source":"72 - Just relax ….pdf","sourcePage":17},{"front":"feel uncomfortable","meaning":"感到不適","examples":[{"en":"The patient did not feel uncomfortable while holding the position.","zh":"病人在保持該姿勢時沒有感到不適。"},{"en":"To feel uncomfortable means to feel physical pain, awkwardness, embarrassment, or unease.","zh":"feel uncomfortable 指感到身體痛楚、尷尬、難堪或不安。"},{"en":"A student may feel uncomfortable speaking in front of strangers.","zh":"學生在陌生人面前說話可能感到不適。"},{"en":"Reducing discomfort can help patients stay still and cooperate with treatment.","zh":"減少不適可以幫助病人保持不動並配合治療。"},{"en":"This phrase can refer to body discomfort or emotional discomfort.","zh":"這個短語可以指身體不適或情緒不舒服。"}],"source":"72 - Just relax ….pdf","sourcePage":18},{"front":"occasionally been used with","meaning":"偶爾被用於……","examples":[{"en":"Hypnosis has occasionally been used with witnesses and victims of crime.","zh":"催眠偶爾被用於罪案目擊者和受害人。"},{"en":"Occasionally been used with means used sometimes, but not regularly or usually.","zh":"occasionally been used with 指有時使用，但不是定期或通常使用。"},{"en":"Video interviews have occasionally been used with young children who find courtrooms frightening.","zh":"視像訪問偶爾被用於覺得法庭可怕的年幼兒童。"},{"en":"Occasional use suggests caution or special circumstances.","zh":"偶爾使用表示謹慎或特殊情況。"},{"en":"This phrase shows that a method is not common practice.","zh":"這個短語顯示某方法不是常規做法。"}],"source":"72 - Just relax ….pdf","sourcePage":18},{"front":"witnesses and victims of crime","meaning":"罪案目擊者和受害人","examples":[{"en":"Hypnosis has been used with witnesses and victims of crime.","zh":"催眠曾被用於罪案目擊者和受害人。"},{"en":"Witnesses and victims of crime are people who saw a crime happen or were harmed by it.","zh":"witnesses and victims of crime 指看見罪案發生或被罪案傷害的人。"},{"en":"A witness may remember a car number, while a victim may remember the attacker’s voice.","zh":"目擊者可能記得車牌號碼，而受害人可能記得襲擊者聲音。"},{"en":"Their memories can help investigations, but they may also be affected by fear or trauma.","zh":"他們的記憶可以幫助調查，但也可能受恐懼或創傷影響。"},{"en":"This phrase identifies people involved in criminal cases.","zh":"這個短語指出涉及刑事案件的人。"}],"source":"72 - Just relax ….pdf","sourcePage":18},{"front":"enable people to","meaning":"使人能夠","examples":[{"en":"Hypnosis may enable people to remember important clues.","zh":"催眠可能使人能夠記起重要線索。"},{"en":"To enable people to do something means to make it possible for them to do it.","zh":"enable people to do something 指使人能夠做某事。"},{"en":"Subtitles enable people to understand a film in another language.","zh":"字幕使人能夠理解另一種語言的電影。"},{"en":"A tool is useful when it enables people to do something they could not do easily before.","zh":"當工具使人能夠做以前不容易做到的事，它就有用。"},{"en":"This phrase focuses on making an action possible.","zh":"這個短語著重令行動成為可能。"}],"source":"72 - Just relax ….pdf","sourcePage":18},{"front":"important clues","meaning":"重要線索","examples":[{"en":"Witnesses may remember important clues under hypnosis.","zh":"目擊者可能在催眠下記起重要線索。"},{"en":"Important clues are pieces of information that help solve a problem or investigation.","zh":"important clues 指有助解決問題或調查的資訊片段。"},{"en":"A broken window may be an important clue in finding out how a thief entered a house.","zh":"破窗可能是了解小偷如何入屋的重要線索。"},{"en":"Small details can become important clues when they connect to other evidence.","zh":"當小細節與其他證據連接時，就可以成為重要線索。"},{"en":"This phrase refers to useful signs or details.","zh":"這個短語指有用跡象或細節。"}],"source":"72 - Just relax ….pdf","sourcePage":18},{"front":"physical appearance","meaning":"外貌","examples":[{"en":"A witness may remember a criminal’s physical appearance.","zh":"目擊者可能記起罪犯的外貌。"},{"en":"Physical appearance means what a person looks like, including height, face, hair, and clothing.","zh":"physical appearance 指一個人的樣子，包括身高、臉、頭髮和衣着。"},{"en":"Police may ask a witness about the suspect’s physical appearance.","zh":"警方可能詢問目擊者嫌疑人的外貌。"},{"en":"Appearance details can help identify someone, but memory may be imperfect.","zh":"外貌細節可以幫助識別某人，但記憶可能不完美。"},{"en":"This phrase refers to visible features.","zh":"這個短語指可見特徵。"}],"source":"72 - Just relax ….pdf","sourcePage":18},{"front":"significant details","meaning":"重要細節","examples":[{"en":"Hypnosis may help people remember significant details.","zh":"催眠可能幫助人記起重要細節。"},{"en":"Significant details are important pieces of information that may affect understanding or decisions.","zh":"significant details 指可能影響理解或決定的重要資訊。"},{"en":"In a reading test, a date or number may be a significant detail.","zh":"在閱讀測驗中，日期或數字可能是重要細節。"},{"en":"Remembering significant details can change how an event is interpreted.","zh":"記起重要細節可以改變一件事如何被詮釋。"},{"en":"This phrase means details that matter, not random small facts.","zh":"這個短語指有意義的細節，而不是隨機小事實。"}],"source":"72 - Just relax ….pdf","sourcePage":18},{"front":"solve a crime","meaning":"偵破罪案","examples":[{"en":"Important details may help to solve a crime.","zh":"重要細節可能有助偵破罪案。"},{"en":"To solve a crime means to discover who committed it and how it happened.","zh":"solve a crime 指查明誰犯案以及案件如何發生。"},{"en":"Police may solve a crime by combining witness statements, camera footage, and fingerprints.","zh":"警方可能透過結合目擊者口供、錄影片段和指紋來偵破罪案。"},{"en":"Without reliable evidence, solving a crime becomes much harder.","zh":"沒有可靠證據，偵破罪案會困難得多。"},{"en":"This phrase refers to completing a criminal investigation.","zh":"這個短語指完成刑事調查。"}],"source":"72 - Just relax ….pdf","sourcePage":18},{"front":"legal situations","meaning":"法律情境","examples":[{"en":"The use of hypnotism in legal situations can cause problems.","zh":"在法律情境中使用催眠術可能造成問題。"},{"en":"Legal situations are contexts involving law, courts, police, evidence, or rights.","zh":"legal situations 指涉及法律、法庭、警方、證據或權利的情境。"},{"en":"Giving a witness statement is a legal situation because the information may be used in court.","zh":"作目擊者陳述是一種法律情境，因為資料可能在法庭使用。"},{"en":"Legal settings require especially careful evidence because people’s freedom or safety may be affected.","zh":"法律場合特別需要謹慎證據，因為人的自由或安全可能受影響。"},{"en":"This phrase refers to situations governed by law.","zh":"這個短語指受法律規管的情況。"}],"source":"72 - Just relax ….pdf","sourcePage":18},{"front":"cause serious problems","meaning":"造成嚴重問題","examples":[{"en":"Hypnotism in legal situations can cause serious problems.","zh":"法律情境中的催眠術可能造成嚴重問題。"},{"en":"To cause serious problems means to create difficulties that may have harmful consequences.","zh":"cause serious problems 指造成可能帶來有害後果的困難。"},{"en":"A wrong medical record can cause serious problems if doctors choose the wrong treatment.","zh":"如果醫生選擇錯誤治療，錯誤病歷可以造成嚴重問題。"},{"en":"In law, unreliable memory can affect justice and fairness.","zh":"在法律中，不可靠記憶可以影響公義和公平。"},{"en":"This phrase warns that the result may be important and damaging.","zh":"這個短語提醒結果可能重要且有破壞性。"}],"source":"72 - Just relax ….pdf","sourcePage":18},{"front":"divulge secret information","meaning":"透露秘密資料","examples":[{"en":"Hypnosis cannot make a person divulge secret information.","zh":"催眠不能令人透露秘密資料。"},{"en":"To divulge secret information means to reveal private or hidden facts to others.","zh":"divulge secret information 指向他人揭露私人或隱藏資料。"},{"en":"An employee should not divulge secret information about customers to friends.","zh":"員工不應向朋友透露顧客的秘密資料。"},{"en":"Revealing secrets can damage trust, safety, or legal rights.","zh":"透露秘密可以破壞信任、安全或法律權利。"},{"en":"This phrase is more formal than “tell secrets”.","zh":"這個短語比 tell secrets 更正式。"}],"source":"72 - Just relax ….pdf","sourcePage":19},{"front":"if they don’t want to","meaning":"如果他們不想","examples":[{"en":"People cannot be forced to reveal secrets if they don’t want to.","zh":"如果人們不想，就不能被迫透露秘密。"},{"en":"If they don’t want to means if they are unwilling or refuse.","zh":"if they don’t want to 指如果他們不願意或拒絕。"},{"en":"A student should not be made to share a personal story if they do not want to.","zh":"如果學生不想，就不應被要求分享私人故事。"},{"en":"Willingness matters when information is private or emotionally difficult.","zh":"當資訊私密或情感上困難時，意願很重要。"},{"en":"This phrase stresses personal choice.","zh":"這個短語強調個人選擇。"}],"source":"72 - Just relax ….pdf","sourcePage":19},{"front":"be confirmed by","meaning":"得到……證實","examples":[{"en":"This limitation was confirmed by the American Medical Association.","zh":"這項限制得到美國醫學會證實。"},{"en":"To be confirmed by someone means to be supported or verified by that person or organisation.","zh":"be confirmed by someone 指得到某人或某機構支持或核實。"},{"en":"A school closure may be confirmed by the education department before parents are informed.","zh":"學校停課可能先得到教育部門證實，再通知家長。"},{"en":"Confirmation from an authority makes a claim more credible.","zh":"來自權威機構的證實令說法更可信。"},{"en":"This phrase identifies who verified the point.","zh":"這個短語指出由誰證實該點。"}],"source":"72 - Just relax ….pdf","sourcePage":19},{"front":"Council on Scientific Affairs","meaning":"科學事務委員會","examples":[{"en":"The Council on Scientific Affairs reported on hypnosis and memory.","zh":"科學事務委員會曾就催眠和記憶作出報告。"},{"en":"The Council on Scientific Affairs is a committee concerned with scientific evidence and medical issues.","zh":"Council on Scientific Affairs 指關注科學證據和醫學議題的委員會。"},{"en":"A scientific council may review research before giving advice to doctors or the public.","zh":"科學委員會可能在向醫生或公眾提供建議前審視研究。"},{"en":"Such councils matter because they help separate evidence from popular belief.","zh":"這類委員會重要，因為它們幫助分辨證據與流行信念。"},{"en":"This phrase names an expert body.","zh":"這個短語命名一個專家機構。"}],"source":"72 - Just relax ….pdf","sourcePage":19},{"front":"American Medical Association","meaning":"美國醫學會","examples":[{"en":"The American Medical Association issued a report in 1985.","zh":"美國醫學會在 1985 年發布了一份報告。"},{"en":"The American Medical Association is a major professional organisation connected with doctors and medicine in the United States.","zh":"American Medical Association 是美國一個與醫生和醫學相關的重要專業組織。"},{"en":"Medical associations may publish guidance after reviewing research evidence.","zh":"醫學會可能在審視研究證據後發布指引。"},{"en":"Reports from such organisations can influence how doctors use treatments.","zh":"這類組織的報告可以影響醫生如何使用治療。"},{"en":"This phrase names a recognised medical body.","zh":"這個短語命名一個受認可的醫學機構。"}],"source":"72 - Just relax ….pdf","sourcePage":19},{"front":"reported in 1985 that","meaning":"在1985年報告指出","examples":[{"en":"The association reported in 1985 that hypnotic memories may be inaccurate.","zh":"該協會在 1985 年報告指出，催眠記憶可能不準確。"},{"en":"Reported in 1985 that means stated in a report published in that year.","zh":"reported in 1985 that 指在該年發布的報告中指出某事。"},{"en":"A school may report in 2026 that attendance improved after a new bus route began.","zh":"學校可能在 2026 年報告指出，新巴士路線開始後出席率改善。"},{"en":"The date helps readers place the statement in a historical timeline.","zh":"日期幫助讀者把該說法放在歷史時間線中。"},{"en":"This phrase introduces an officially reported finding.","zh":"這個短語引入正式報告的發現。"}],"source":"72 - Just relax ….pdf","sourcePage":19},{"front":"memories refreshed through hypnosis","meaning":"透過催眠喚起的記憶","examples":[{"en":"Memories refreshed through hypnosis may include inaccurate information.","zh":"透過催眠喚起的記憶可能包含不準確資料。"},{"en":"Memories refreshed through hypnosis are memories that a person tries to bring back with the help of hypnosis.","zh":"memories refreshed through hypnosis 指人在催眠幫助下嘗試重新想起的記憶。"},{"en":"A witness may feel more certain after hypnosis, even if some details are wrong.","zh":"目擊者在催眠後可能感到更確定，即使某些細節錯誤。"},{"en":"Refreshed memories can mix real details with suggestion or imagination.","zh":"被喚起的記憶可能混合真實細節、暗示或想像。"},{"en":"This phrase warns that recovered memory is not always reliable.","zh":"這個短語提醒我們，恢復的記憶不一定可靠。"}],"source":"72 - Just relax ….pdf","sourcePage":19},{"front":"inaccurate information","meaning":"不準確資料","examples":[{"en":"Hypnotic memories may include inaccurate information.","zh":"催眠記憶可能包含不準確資料。"},{"en":"Inaccurate information is information that is wrong, incomplete, or misleading.","zh":"inaccurate information 指錯誤、不完整或具誤導性的資料。"},{"en":"A wrong bus time on a noticeboard is inaccurate information that can make students late.","zh":"告示板上錯誤的巴士時間是不準確資料，可能令學生遲到。"},{"en":"In legal cases, inaccurate information can lead to unfair decisions.","zh":"在法律案件中，不準確資料可以導致不公平決定。"},{"en":"This phrase refers to information that should not be trusted fully.","zh":"這個短語指不應完全信任的資料。"}],"source":"72 - Just relax ….pdf","sourcePage":19},{"front":"false memories","meaning":"虛假記憶","examples":[{"en":"Hypnotic recall may include false memories.","zh":"催眠回憶可能包含虛假記憶。"},{"en":"False memories are memories of events that did not happen or did not happen in the remembered way.","zh":"false memories 指對沒有發生、或並非以記得方式發生的事件的記憶。"},{"en":"A person may develop a false memory after hearing the same mistaken story many times.","zh":"一個人多次聽到同一錯誤故事後，可能形成虛假記憶。"},{"en":"False memories are dangerous in court because they can feel real to the witness.","zh":"虛假記憶在法庭中很危險，因為它們對目擊者來說可能感覺真實。"},{"en":"This phrase describes memory errors that may seem convincing.","zh":"這個短語描述看似可信的記憶錯誤。"}],"source":"72 - Just relax ….pdf","sourcePage":19},{"front":"confabulation","meaning":"虛構性記憶；混合事實與幻想的記憶","examples":[{"en":"Confabulation means fact and fantasy combined.","zh":"confabulation 指事實與幻想混合。"},{"en":"Confabulation is the creation of false or mixed memories without an intention to lie.","zh":"confabulation 指在沒有意圖說謊下創造虛假或混合記憶。"},{"en":"A person with confused memory may fill gaps with details that feel real but are invented.","zh":"記憶混亂的人可能用感覺真實但其實虛構的細節填補空白。"},{"en":"Confabulation can make evidence unreliable because the speaker may believe the story.","zh":"虛構性記憶可以令證據不可靠，因為說話者可能相信該故事。"},{"en":"This word describes memory mixing, not deliberate dishonesty.","zh":"這個詞描述記憶混合，而不是刻意不誠實。"}],"source":"72 - Just relax ….pdf","sourcePage":19},{"front":"fact and fantasy combined","meaning":"事實與幻想混合","examples":[{"en":"Confabulation involves fact and fantasy combined.","zh":"虛構性記憶涉及事實與幻想混合。"},{"en":"Fact and fantasy combined means real details are mixed with imagined details.","zh":"fact and fantasy combined 指真實細節與想像細節混在一起。"},{"en":"A child’s story about a school trip may have fact and fantasy combined if they add a dragon to a real museum visit.","zh":"如果孩子在真實博物館參觀故事中加入龍，該校外旅行故事就是事實與幻想混合。"},{"en":"Mixed memory becomes risky when people cannot tell which parts are true.","zh":"當人們分不清哪些部分真實時，混合記憶會變得有風險。"},{"en":"This phrase describes a blend of reality and imagination.","zh":"這個短語描述現實與想像的混合。"}],"source":"72 - Just relax ….pdf","sourcePage":20},{"front":"the most suitable heading","meaning":"最合適的標題","examples":[{"en":"Students choose the most suitable heading for each section.","zh":"學生為每一節選出最合適的標題。"},{"en":"The most suitable heading is the title that best matches the main idea of a section.","zh":"most suitable heading 指最符合某節主旨的標題。"},{"en":"In a reading test, a heading about medical use should not be chosen for a paragraph about history.","zh":"在閱讀測驗中，關於醫療用途的標題不應選給關於歷史的段落。"},{"en":"Choosing headings requires understanding the whole section, not only one word.","zh":"選標題需要理解整節，而不只是看一個字。"},{"en":"This phrase is common in main-idea reading questions.","zh":"這個短語常見於主旨閱讀題。"}],"source":"72 - Just relax ….pdf","sourcePage":20},{"front":"the appropriate numbers","meaning":"適當的編號","examples":[{"en":"Students write the appropriate numbers for the headings.","zh":"學生為標題寫上適當的編號。"},{"en":"The appropriate numbers are the correct numbered options that match the answers.","zh":"appropriate numbers 指與答案相配的正確編號選項。"},{"en":"A student may understand the heading but lose marks if the wrong number is copied.","zh":"學生可能理解標題，但如果抄錯編號，仍會失分。"},{"en":"Checking numbers carefully prevents answer-sheet errors.","zh":"仔細檢查編號可以防止答題紙錯誤。"},{"en":"This phrase focuses on answer format and accuracy.","zh":"這個短語著重答案格式和準確性。"}],"source":"72 - Just relax ….pdf","sourcePage":20},{"front":"more headings than sections","meaning":"標題多於段落","examples":[{"en":"There are more headings than sections in the question.","zh":"題目中的標題多於段落。"},{"en":"More headings than sections means there are extra heading options that will not all be used.","zh":"more headings than sections 指標題選項有多餘，並非全部都會使用。"},{"en":"In a matching task, students may have six headings for four paragraphs.","zh":"在配對題中，學生可能有六個標題配四段文章。"},{"en":"Extra options make the task harder because some answers are distractors.","zh":"額外選項令題目更難，因為有些答案是干擾項。"},{"en":"This phrase warns students not to use every option.","zh":"這個短語提醒學生不要使用每個選項。"}],"source":"72 - Just relax ….pdf","sourcePage":20},{"front":"will not use all of them","meaning":"不會全部使用","examples":[{"en":"Students will not use all of the headings.","zh":"學生不會全部使用這些標題。"},{"en":"Will not use all of them means some options must be left unused.","zh":"will not use all of them 指有些選項必須留空不用。"},{"en":"In a reading task, students may have ten choices but only six blanks to fill.","zh":"在閱讀題中，學生可能有十個選項，但只有六個空格要填。"},{"en":"Leaving unused options is normal when the task gives extra distractors.","zh":"當題目提供額外干擾項時，留下不用的選項是正常的。"},{"en":"This phrase helps students avoid forcing every option into an answer.","zh":"這個短語幫助學生避免硬把每個選項放進答案。"}],"source":"72 - Just relax ….pdf","sourcePage":20},{"front":"early medical experiments with","meaning":"早期以……進行的醫學實驗","examples":[{"en":"The heading refers to early medical experiments with hypnotism.","zh":"這個標題指早期以催眠術進行的醫學實驗。"},{"en":"Early medical experiments with something are first attempts to test it in healthcare or treatment.","zh":"early medical experiments with something 指在醫療或治療中首次嘗試測試某方法。"},{"en":"Early medical experiments with X-rays helped doctors see inside the body without surgery.","zh":"早期以 X 光進行的醫學實驗，幫助醫生不用手術也能看見身體內部。"},{"en":"Such experiments can open new possibilities but also require caution.","zh":"這類實驗可以開啟新可能，但也需要謹慎。"},{"en":"This phrase links a developing medical method with its first tests.","zh":"這個短語把發展中的醫療方法與其初期測試連繫起來。"}],"source":"72 - Just relax ….pdf","sourcePage":20},{"front":"association of hypnosis with psychology","meaning":"催眠與心理學的關聯","examples":[{"en":"One heading mentions the early association of hypnosis with psychology.","zh":"一個標題提到催眠與心理學的早期關聯。"},{"en":"The association of hypnosis with psychology means the connection between hypnosis and the study of the mind.","zh":"association of hypnosis with psychology 指催眠與心智研究之間的連繫。"},{"en":"A course may discuss the association of stress with sleep problems.","zh":"課程可能討論壓力與睡眠問題的關聯。"},{"en":"Linking hypnosis with psychology helps explain it as mental behaviour rather than magic.","zh":"把催眠與心理學連繫起來，有助把它解釋為心理行為，而不是魔法。"},{"en":"This phrase focuses on a relationship between two fields.","zh":"這個短語著重兩個領域之間的關係。"}],"source":"72 - Just relax ….pdf","sourcePage":20},{"front":"dangers of hypnotism","meaning":"催眠術的危險","examples":[{"en":"The list includes a heading about the dangers of hypnotism.","zh":"列表包括一個關於催眠術危險的標題。"},{"en":"Dangers of hypnotism are possible risks or problems connected with using hypnosis.","zh":"dangers of hypnotism 指使用催眠可能相關的風險或問題。"},{"en":"In legal settings, one danger is that hypnotic memories may be unreliable.","zh":"在法律場合，一個危險是催眠記憶可能不可靠。"},{"en":"A method can be useful and still have dangers if used carelessly.","zh":"一種方法可以有用，但若使用不當仍有危險。"},{"en":"This phrase focuses on risks, not benefits.","zh":"這個短語著重風險，而不是好處。"}],"source":"72 - Just relax ….pdf","sourcePage":20},{"front":"how to hypnotise","meaning":"如何催眠","examples":[{"en":"One heading asks about how to hypnotise a subject.","zh":"一個標題問如何催眠受試者。"},{"en":"How to hypnotise means the method used to guide someone into hypnosis.","zh":"how to hypnotise 指引導某人進入催眠的方法。"},{"en":"A lesson on how to relax may begin with breathing and attention exercises.","zh":"關於如何放鬆的課堂可能由呼吸和注意力練習開始。"},{"en":"The method matters because hypnosis depends on focus, suggestion, and willingness.","zh":"方法很重要，因為催眠取決於專注、暗示和意願。"},{"en":"This phrase introduces procedure or technique.","zh":"這個短語引入程序或技巧。"}],"source":"72 - Just relax ….pdf","sourcePage":20},{"front":"hypnosis and free will","meaning":"催眠與自由意志","examples":[{"en":"The passage discusses hypnosis and free will.","zh":"文章討論催眠與自由意志。"},{"en":"Hypnosis and free will refers to the question of whether a hypnotised person still has choice.","zh":"hypnosis and free will 指受催眠者是否仍有選擇權的問題。"},{"en":"A debate about free will may ask whether people can refuse pressure from others.","zh":"關於自由意志的辯論可能問人是否能拒絕他人壓力。"},{"en":"The passage stresses that subjects can resist suggestions and choose to participate.","zh":"文章強調受試者可以抗拒暗示並選擇參與。"},{"en":"This phrase connects hypnosis with personal control and consent.","zh":"這個短語把催眠與個人控制和同意連繫起來。"}],"source":"72 - Just relax ….pdf","sourcePage":20},{"front":"therapeutic uses of hypnosis","meaning":"催眠的治療用途","examples":[{"en":"Hypnosis has several therapeutic uses.","zh":"催眠有幾種治療用途。"},{"en":"Therapeutic uses of hypnosis are ways hypnosis can be used to support treatment or healing.","zh":"therapeutic uses of hypnosis 指催眠可用來支援治療或康復的方式。"},{"en":"A therapist may use hypnosis to reduce anxiety or help patients revisit painful memories calmly.","zh":"治療師可能使用催眠來減少焦慮，或幫助病人平靜地重訪痛苦回憶。"},{"en":"Therapeutic use requires care because patients may be vulnerable.","zh":"治療用途需要謹慎，因為病人可能較脆弱。"},{"en":"This phrase focuses on healing purposes, not entertainment.","zh":"這個短語著重療癒目的，而不是娛樂。"}],"source":"72 - Just relax ….pdf","sourcePage":21},{"front":"origins of hypnosis","meaning":"催眠的起源","examples":[{"en":"The example heading concerns the origins of hypnosis.","zh":"示例標題關於催眠的起源。"},{"en":"Origins of hypnosis means the earliest history or beginnings of hypnosis-related ideas and practices.","zh":"origins of hypnosis 指與催眠相關的思想和做法的最早歷史或開端。"},{"en":"A history lesson on medicine may begin with the origins of hospitals.","zh":"醫學歷史課可能由醫院的起源開始。"},{"en":"Studying origins helps explain how modern ideas developed from older beliefs.","zh":"研究起源有助解釋現代想法如何由舊信念發展而來。"},{"en":"This phrase focuses on where and how something began.","zh":"這個短語著重某事從哪裡以及如何開始。"}],"source":"72 - Just relax ….pdf","sourcePage":21},{"front":"complete the notes on","meaning":"完成關於……的筆記","examples":[{"en":"Students complete the notes on the history of hypnosis.","zh":"學生完成關於催眠歷史的筆記。"},{"en":"To complete the notes on something means to fill missing information in notes about that topic.","zh":"complete the notes on something 指填寫關於某主題筆記中的缺失資料。"},{"en":"Students may complete the notes on a science video by writing key dates and terms.","zh":"學生可能透過寫下關鍵日期和術語，完成關於科學影片的筆記。"},{"en":"Completing notes helps learners organise information in a shorter form.","zh":"完成筆記幫助學習者以較短形式整理資訊。"},{"en":"This phrase is a common reading or listening task instruction.","zh":"這個短語是常見閱讀或聆聽任務指示。"}],"source":"72 - Just relax ….pdf","sourcePage":21},{"front":"no more than three words","meaning":"不超過三個詞","examples":[{"en":"The answers must use no more than three words from the passage.","zh":"答案必須使用文章中不超過三個詞。"},{"en":"No more than three words means one, two, or three words, but not four.","zh":"no more than three words 指一個、兩個或三個詞，但不是四個。"},{"en":"If the limit is no more than three words, “animal magnetism” is allowed.","zh":"如果限制是不超過三個詞，“animal magnetism” 是可以的。"},{"en":"Students can lose marks if they exceed the word limit, even with the correct idea.","zh":"即使意思正確，學生如果超出字數限制也可能失分。"},{"en":"This phrase gives a strict answer-length rule.","zh":"這個短語給出嚴格答案長度規則。"}],"source":"72 - Just relax ….pdf","sourcePage":21},{"front":"references to hypnosis","meaning":"對催眠的提及","examples":[{"en":"References to hypnosis can be found in ancient texts.","zh":"古代文本中可以找到對催眠的提及。"},{"en":"References to hypnosis are mentions of hypnosis-like states, practices, or ideas in writing or records.","zh":"references to hypnosis 指文字或記錄中提到類似催眠的狀態、做法或想法。"},{"en":"A historian may search old medical books for references to early pain-control methods.","zh":"歷史學家可能在舊醫學書中尋找對早期止痛方法的提及。"},{"en":"Such references show that similar ideas existed before modern terminology.","zh":"這類提及顯示類似想法在現代術語出現前已存在。"},{"en":"This phrase points to mentions, not necessarily complete scientific descriptions.","zh":"這個短語指出提及，而不一定是完整科學描述。"}],"source":"72 - Just relax ….pdf","sourcePage":21},{"front":"even when","meaning":"即使在……的情況下","examples":[{"en":"Successful results occurred even when magnets were not used.","zh":"即使在沒有使用磁鐵的情況下，也出現成功效果。"},{"en":"Even when means despite the fact that a particular condition is true.","zh":"even when 指儘管某一條件成立。"},{"en":"A good student may make mistakes even when they understand the lesson.","zh":"好學生即使在理解課堂的情況下，也可能犯錯。"},{"en":"This phrase highlights that something happens under surprising conditions.","zh":"這個短語突出某事在令人意外的條件下發生。"},{"en":"It is useful for showing contrast between expectation and reality.","zh":"它適合用來顯示預期與現實之間的對比。"}],"source":"72 - Just relax ….pdf","sourcePage":21},{"front":"identify something as","meaning":"將……識別為","examples":[{"en":"Braid identified hypnosis as a physiological response.","zh":"Braid 將催眠識別為一種生理反應。"},{"en":"To identify something as something else means to recognise or define it in that way.","zh":"identify something as something else 指把某事認出或界定為某類事物。"},{"en":"A doctor may identify chest pain as a possible sign of stress after tests rule out heart disease.","zh":"檢查排除心臟病後，醫生可能將胸痛識別為壓力的可能徵象。"},{"en":"Correct identification changes how a problem is explained and treated.","zh":"正確識別會改變問題如何被解釋和處理。"},{"en":"This phrase links recognition with classification.","zh":"這個短語把辨認與分類連繫起來。"}],"source":"72 - Just relax ….pdf","sourcePage":21},{"front":"natural physiological response","meaning":"自然生理反應","examples":[{"en":"Braid identified hypnosis as a natural physiological response.","zh":"Braid 將催眠識別為一種自然生理反應。"},{"en":"A natural physiological response is a normal body-and-mind reaction rather than a supernatural event.","zh":"natural physiological response 指正常的身心反應，而不是超自然事件。"},{"en":"A racing heartbeat before a speech is a natural physiological response to nervousness.","zh":"演講前心跳加速是對緊張的自然生理反應。"},{"en":"Seeing hypnosis this way makes it easier to study scientifically.","zh":"以這種方式看待催眠，令它更容易被科學研究。"},{"en":"This phrase removes the idea of magic from hypnosis.","zh":"這個短語把魔法概念從催眠中移除。"}],"source":"72 - Just relax ….pdf","sourcePage":21},{"front":"magical or mystical","meaning":"魔法或神秘的","examples":[{"en":"Braid did not view hypnosis as magical or mystical.","zh":"Braid 並不把催眠視為魔法或神秘的。"},{"en":"Magical or mystical means connected with supernatural power, mystery, or forces beyond ordinary explanation.","zh":"magical or mystical 指與超自然力量、神秘感或普通解釋以外的力量相關。"},{"en":"A simple science experiment may look magical to children until the teacher explains it.","zh":"簡單科學實驗在老師解釋前，對孩子來說可能看似魔法。"},{"en":"When evidence explains a process, it no longer needs a mystical explanation.","zh":"當證據解釋一個過程，就不再需要神秘解釋。"},{"en":"This phrase contrasts mystery with scientific understanding.","zh":"這個短語把神秘與科學理解作對比。"}],"source":"72 - Just relax ….pdf","sourcePage":21},{"front":"early psychological studies","meaning":"早期心理學研究","examples":[{"en":"Early psychological studies showed the difference between sleep and hypnosis.","zh":"早期心理學研究顯示睡眠與催眠之間的差異。"},{"en":"Early psychological studies are first research efforts in the study of the mind and behaviour.","zh":"early psychological studies 指研究心智和行為的早期研究工作。"},{"en":"Early studies of memory often used simple word lists and recall tasks.","zh":"早期記憶研究常使用簡單詞表和回憶任務。"},{"en":"Such studies helped move hypnosis from mystery toward scientific discussion.","zh":"這類研究幫助催眠由神秘走向科學討論。"},{"en":"This phrase refers to initial research in psychology.","zh":"這個短語指心理學中的初期研究。"}],"source":"72 - Just relax ….pdf","sourcePage":21},{"front":"active concentration","meaning":"主動專注","examples":[{"en":"Successful hypnosis requires the subject’s active concentration.","zh":"成功催眠需要受試者主動專注。"},{"en":"Active concentration is deliberate mental focus, not passive attention.","zh":"active concentration 指有意識的精神集中，而不是被動注意。"},{"en":"A student uses active concentration when they underline key words and think about meaning.","zh":"學生畫下關鍵詞並思考意思時，就是在主動專注。"},{"en":"Without active concentration, a person may become distracted and respond less strongly.","zh":"沒有主動專注，一個人可能分心，反應也較弱。"},{"en":"This phrase stresses effort from the subject.","zh":"這個短語強調受試者方面的努力。"}],"source":"72 - Just relax ….pdf","sourcePage":22},{"front":"consequently","meaning":"因此","examples":[{"en":"Consequently, hypnotised subjects can speak or move around.","zh":"因此，受催眠者可以說話或走動。"},{"en":"Consequently means as a result of what was just explained.","zh":"consequently 指作為剛才所解釋事情的結果。"},{"en":"The bus was delayed; consequently, several students arrived late.","zh":"巴士延誤；因此，幾名學生遲到。"},{"en":"This word connects a cause with a logical result.","zh":"這個詞把原因與邏輯結果連繫起來。"},{"en":"It is more formal than “so”.","zh":"它比 so 更正式。"}],"source":"72 - Just relax ….pdf","sourcePage":22},{"front":"aware of their surroundings","meaning":"知道周圍環境","examples":[{"en":"Hypnotised subjects are aware of their surroundings.","zh":"受催眠者知道周圍環境。"},{"en":"Aware of their surroundings means noticing the people, sounds, and events around them.","zh":"aware of their surroundings 指注意到身邊的人、聲音和事件。"},{"en":"A cyclist must be aware of their surroundings when riding near cars.","zh":"騎單車者在車輛附近行駛時，必須知道周圍環境。"},{"en":"Awareness of surroundings helps people respond to instructions or danger.","zh":"對周圍環境有意識幫助人回應指示或危險。"},{"en":"This phrase shows that hypnotised people are not completely cut off from reality.","zh":"這個短語顯示受催眠者並非完全與現實隔絕。"}],"source":"72 - Just relax ….pdf","sourcePage":22},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students must choose the correct letter from the options.","zh":"學生必須從選項中選出正確字母。"},{"en":"To choose the correct letter means to select the answer marked by the right letter.","zh":"choose the correct letter 指選出由正確字母標示的答案。"},{"en":"In multiple-choice questions, students should check whether the answer is A, B, C, or D.","zh":"在多項選擇題中，學生應檢查答案是 A、B、C 還是 D。"},{"en":"Copying the wrong letter can lose marks even if the student understands the passage.","zh":"即使學生理解文章，抄錯字母也可能失分。"},{"en":"This phrase is an instruction about answer format.","zh":"這個短語是關於答案格式的指示。"}],"source":"72 - Just relax ….pdf","sourcePage":22},{"front":"in order to induce hypnosis","meaning":"為了引發催眠","examples":[{"en":"In order to induce hypnosis, the hypnotist encourages the person to relax.","zh":"為了引發催眠，催眠師鼓勵該人放鬆。"},{"en":"In order to induce hypnosis means for the purpose of guiding someone into hypnosis.","zh":"in order to induce hypnosis 指為了引導某人進入催眠狀態。"},{"en":"A therapist may lower the lights in order to help a patient feel calmer.","zh":"治療師可能調暗燈光，以幫助病人感到更平靜。"},{"en":"The purpose of relaxation is to make focused attention easier.","zh":"放鬆的目的，是令集中注意力更容易。"},{"en":"This phrase links a technique with its goal.","zh":"這個短語把技巧與目標連繫起來。"}],"source":"72 - Just relax ….pdf","sourcePage":22},{"front":"steady, repetitive tone of voice","meaning":"穩定而重複的語調","examples":[{"en":"A hypnotist may use a steady, repetitive tone of voice.","zh":"催眠師可能使用穩定而重複的語調。"},{"en":"A steady, repetitive tone of voice is a calm voice pattern repeated in a regular way.","zh":"steady, repetitive tone of voice 指以規律方式重複的平靜聲音模式。"},{"en":"A teacher reading a bedtime story may use a steady, repetitive voice to calm children.","zh":"老師讀睡前故事時，可能使用穩定而重複的聲音來安撫孩子。"},{"en":"A repeated tone can reduce distraction and make instructions easier to follow.","zh":"重複語調可以減少分心，並令指示更易跟從。"},{"en":"This phrase describes how the hypnotist speaks.","zh":"這個短語描述催眠師如何說話。"}],"source":"72 - Just relax ….pdf","sourcePage":22},{"front":"a specific set of words","meaning":"一組特定字句","examples":[{"en":"The option refers to a specific set of words used by the hypnotist.","zh":"該選項指催眠師使用的一組特定字句。"},{"en":"A specific set of words is a particular group of words chosen for a purpose.","zh":"specific set of words 指為某目的選出的一組特定詞句。"},{"en":"A doctor may use a specific set of words to explain medicine instructions clearly.","zh":"醫生可能使用一組特定字句，清楚解釋用藥指示。"},{"en":"Specific words can guide attention, but hypnosis is not limited to one magic phrase.","zh":"特定字句可以引導注意力，但催眠不只限於一句魔法口訣。"},{"en":"This phrase focuses on exact wording.","zh":"這個短語著重準確措辭。"}],"source":"72 - Just relax ….pdf","sourcePage":22},{"front":"a particular tone of voice","meaning":"某種特定語調","examples":[{"en":"The hypnotist may speak in a particular tone of voice.","zh":"催眠師可能以某種特定語調說話。"},{"en":"A particular tone of voice is a specific way of speaking, such as calm, firm, soft, or repetitive.","zh":"particular tone of voice 指某種特定說話方式，例如平靜、堅定、柔和或重複。"},{"en":"A parent may use a gentle tone of voice to comfort a crying child.","zh":"家長可能使用溫柔語調安慰哭泣的孩子。"},{"en":"Tone can affect how safe, serious, or relaxed a message feels.","zh":"語調可以影響訊息聽起來安全、嚴肅還是放鬆。"},{"en":"This phrase focuses on sound and manner, not just words.","zh":"這個短語著重聲音和方式，而不只是字句。"}],"source":"72 - Just relax ….pdf","sourcePage":22},{"front":"slowly moving object","meaning":"緩慢移動的物件","examples":[{"en":"The option mentions focusing on a slowly moving object.","zh":"該選項提到集中於緩慢移動的物件。"},{"en":"A slowly moving object is something that moves at a gentle, gradual speed.","zh":"slowly moving object 指以溫和、漸進速度移動的東西。"},{"en":"A person may watch a slowly moving pendulum to keep attention steady.","zh":"一個人可能觀看緩慢移動的鐘擺，以保持注意力穩定。"},{"en":"Slow movement can help reduce distraction because the eyes follow one simple target.","zh":"緩慢移動可以幫助減少分心，因為眼睛只跟隨一個簡單目標。"},{"en":"This phrase describes a visual focus used in some relaxation images.","zh":"這個短語描述某些放鬆畫面中使用的視覺焦點。"}],"source":"72 - Just relax ….pdf","sourcePage":22},{"front":"hypnotised subjects","meaning":"受催眠者","examples":[{"en":"Hypnotised subjects can still resist suggestions.","zh":"受催眠者仍然可以抗拒暗示。"},{"en":"Hypnotised subjects are people who have entered a hypnotic state in an experiment, treatment, or performance.","zh":"hypnotised subjects 指在實驗、治療或表演中進入催眠狀態的人。"},{"en":"A hypnotised subject may hear the hypnotist clearly and respond to simple instructions.","zh":"受催眠者可能清楚聽到催眠師說話並回應簡單指示。"},{"en":"Their behaviour can change, but they do not lose all judgement.","zh":"他們的行為可能改變，但不會失去所有判斷力。"},{"en":"This phrase refers to people under hypnosis.","zh":"這個短語指處於催眠狀態的人。"}],"source":"72 - Just relax ….pdf","sourcePage":22},{"front":"be instructed to do","meaning":"被指示去做","examples":[{"en":"Hypnotised subjects can be instructed to do certain actions.","zh":"受催眠者可以被指示去做某些行動。"},{"en":"To be instructed to do something means to be told clearly to perform an action.","zh":"be instructed to do something 指被清楚告知要執行某個行動。"},{"en":"Students may be instructed to close their books before a quiz begins.","zh":"小測開始前，學生可能被指示合上書本。"},{"en":"Instructions can guide behaviour, but people may still refuse harmful actions.","zh":"指示可以引導行為，但人仍可能拒絕有害行動。"},{"en":"This phrase describes being given directions.","zh":"這個短語描述獲得指令。"}],"source":"72 - Just relax ….pdf","sourcePage":23},{"front":"previously said","meaning":"先前說過","examples":[{"en":"The option refers to something the subject has previously said.","zh":"該選項指受試者先前說過的事情。"},{"en":"Previously said means said earlier, before the present moment.","zh":"previously said 指在目前之前早些時候說過。"},{"en":"A teacher may remind a student of what they previously said in a discussion.","zh":"老師可能提醒學生他在討論中先前說過甚麼。"},{"en":"Earlier statements can matter because they show what a person already believed or remembered.","zh":"較早說法可能重要，因為它顯示一個人原本相信或記得甚麼。"},{"en":"This phrase connects present discussion with past speech.","zh":"這個短語把目前討論與過去說話連繫起來。"}],"source":"72 - Just relax ….pdf","sourcePage":23},{"front":"against their wishes","meaning":"違背他們的意願","examples":[{"en":"Subjects should not be forced to act against their wishes.","zh":"受試者不應被迫違背他們的意願行動。"},{"en":"Against their wishes means contrary to what they want or agree to.","zh":"against their wishes 指違反他們想要或同意的事。"},{"en":"A patient should not be photographed against their wishes.","zh":"病人不應在違背意願下被拍照。"},{"en":"Acting against someone’s wishes can violate trust and consent.","zh":"違背某人意願行事可以破壞信任和同意。"},{"en":"This phrase focuses on personal preference and refusal.","zh":"這個短語著重個人意願和拒絕。"}],"source":"72 - Just relax ….pdf","sourcePage":23},{"front":"demonstrate physical strength","meaning":"展現體力","examples":[{"en":"The option mentions subjects demonstrating unusual physical strength.","zh":"該選項提到受試者展現不尋常體力。"},{"en":"To demonstrate physical strength means to show the ability to use the body powerfully.","zh":"demonstrate physical strength 指顯示使用身體力量的能力。"},{"en":"A worker demonstrates physical strength when lifting heavy boxes safely.","zh":"工人安全搬起重箱時，就是展現體力。"},{"en":"Stage performances may make ordinary actions look like signs of special strength.","zh":"舞台表演可能令普通行動看起來像特殊力量的表現。"},{"en":"This phrase focuses on showing bodily power.","zh":"這個短語著重顯示身體力量。"}],"source":"72 - Just relax ….pdf","sourcePage":23},{"front":"would normally not have","meaning":"平時不會有的","examples":[{"en":"The option refers to strength a person would normally not have.","zh":"該選項指一個人平時不會有的力量。"},{"en":"Would normally not have means would not usually possess in ordinary conditions.","zh":"would normally not have 指在普通情況下通常不會擁有。"},{"en":"A tired student would normally not have the energy to study for five more hours.","zh":"疲倦學生平時不會有精力再溫習五小時。"},{"en":"This phrase contrasts ordinary ability with an unusual situation.","zh":"這個短語把普通能力與不尋常情況作對比。"},{"en":"It is often used when discussing surprising or unlikely behaviour.","zh":"它常用於討論令人意外或不太可能的行為。"}],"source":"72 - Just relax ….pdf","sourcePage":23},{"front":"reveal confidential information","meaning":"透露機密資料","examples":[{"en":"Hypnosis cannot force people to reveal confidential information.","zh":"催眠不能迫使人透露機密資料。"},{"en":"To reveal confidential information means to share private information that should be kept secret.","zh":"reveal confidential information 指分享本應保密的私人資料。"},{"en":"A nurse must not reveal confidential information about a patient’s illness.","zh":"護士不得透露病人病情的機密資料。"},{"en":"Protecting confidential information preserves trust and privacy.","zh":"保護機密資料能維持信任和私隱。"},{"en":"This phrase is formal and often used in legal, medical, or workplace contexts.","zh":"這個短語較正式，常用於法律、醫療或工作語境。"}],"source":"72 - Just relax ….pdf","sourcePage":23},{"front":"normally be opposed to doing","meaning":"平時不會反對做的","examples":[{"en":"A subject may do something they would not normally be opposed to doing.","zh":"受試者可能做一些他們平時不會反對做的事情。"},{"en":"Normally be opposed to doing something means usually dislike, reject, or disagree with doing it.","zh":"normally be opposed to doing something 指通常不喜歡、拒絕或不同意做某事。"},{"en":"A shy student may not normally be opposed to singing, but they may avoid singing alone on stage.","zh":"害羞學生平時未必反對唱歌，但可能避免獨自在台上唱。"},{"en":"Hypnosis may encourage behaviour people accept in principle but would usually feel embarrassed to do.","zh":"催眠可能鼓勵人做一些原則上接受、但平時會尷尬的行為。"},{"en":"This phrase focuses on ordinary resistance or acceptance.","zh":"這個短語著重平常的抗拒或接受程度。"}],"source":"72 - Just relax ….pdf","sourcePage":23},{"front":"past events are recalled","meaning":"過去事件被回憶起","examples":[{"en":"Past events are recalled under hypnosis for therapeutic purposes.","zh":"過去事件在催眠下被回憶起，用於治療目的。"},{"en":"Past events are recalled means earlier experiences are brought back into memory.","zh":"past events are recalled 指較早經歷被帶回記憶中。"},{"en":"A person may recall a childhood school trip after seeing an old photograph.","zh":"一個人看見舊照片後，可能回憶起童年校外旅行。"},{"en":"Recalling past events can help people understand present feelings.","zh":"回憶過去事件可以幫助人理解目前感受。"},{"en":"This phrase focuses on remembering earlier experiences.","zh":"這個短語著重記起較早經驗。"}],"source":"72 - Just relax ….pdf","sourcePage":23},{"front":"entertain the hypnotist","meaning":"娛樂催眠師","examples":[{"en":"The option suggests that memories are recalled to entertain the hypnotist.","zh":"該選項表示回憶被喚起是為了娛樂催眠師。"},{"en":"To entertain the hypnotist means to amuse or please the hypnotist, usually for enjoyment rather than treatment.","zh":"entertain the hypnotist 指逗樂或取悅催眠師，通常為享樂而非治療。"},{"en":"A performer may tell jokes to entertain an audience, not to solve a problem.","zh":"表演者可能講笑話娛樂觀眾，而不是解決問題。"},{"en":"Therapy is different from entertainment because its aim is healing or support.","zh":"治療與娛樂不同，因為其目標是療癒或支援。"},{"en":"This phrase contrasts serious treatment with amusement.","zh":"這個短語把嚴肅治療與娛樂作對比。"}],"source":"72 - Just relax ….pdf","sourcePage":23},{"front":"reassess them without distress","meaning":"在沒有痛苦的情況下重新審視","examples":[{"en":"Hypnosis may help subjects reassess memories without distress.","zh":"催眠可能幫助受試者在沒有痛苦的情況下重新審視記憶。"},{"en":"To reassess them without distress means to look again at memories without feeling overwhelming pain or fear.","zh":"reassess them without distress 指在沒有強烈痛苦或恐懼下重新看待記憶。"},{"en":"A student may reassess a past failure calmly after a teacher explains what can be improved.","zh":"老師解釋可改善之處後，學生可能平靜地重新審視過去失敗。"},{"en":"Calm reassessment can help people learn from painful events instead of avoiding them.","zh":"平靜重新審視可以幫助人從痛苦事件中學習，而不是逃避。"},{"en":"This phrase combines review with emotional safety.","zh":"這個短語結合重新檢視與情緒安全。"}],"source":"72 - Just relax ….pdf","sourcePage":23},{"front":"improve their memories","meaning":"改善記憶力","examples":[{"en":"The option suggests that hypnosis helps subjects improve their memories.","zh":"該選項表示催眠幫助受試者改善記憶力。"},{"en":"To improve their memories means to make their ability to remember stronger or more accurate.","zh":"improve their memories 指令他們記住事情的能力更強或更準確。"},{"en":"Students may improve their memory by reviewing vocabulary with examples every week.","zh":"學生可以透過每星期用例句溫習詞彙來改善記憶力。"},{"en":"However, hypnosis does not guarantee that recalled memories are accurate.","zh":"然而，催眠不能保證被喚起的記憶準確。"},{"en":"This phrase refers to memory ability, not emotional healing only.","zh":"這個短語指記憶能力，而不只是情緒療癒。"}],"source":"72 - Just relax ….pdf","sourcePage":24},{"front":"make the subject feel younger","meaning":"令受試者感到更年輕","examples":[{"en":"The option says hypnosis may make the subject feel younger.","zh":"該選項說催眠可能令受試者感到更年輕。"},{"en":"To make the subject feel younger means to make the person feel as if they are at an earlier age.","zh":"make the subject feel younger 指令該人感覺自己處於較早年齡。"},{"en":"Looking at childhood photos may make someone feel younger for a moment.","zh":"看童年照片可能令某人一瞬間感到更年輕。"},{"en":"Feeling younger in hypnosis may relate to recalling earlier experiences.","zh":"在催眠中感到更年輕，可能與回憶較早經歷有關。"},{"en":"This phrase describes a subjective feeling, not actual physical age change.","zh":"這個短語描述主觀感覺，而不是實際生理年齡改變。"}],"source":"72 - Just relax ….pdf","sourcePage":24},{"front":"after surgery","meaning":"手術後","examples":[{"en":"After surgery, hypnosis may help a patient remain still.","zh":"手術後，催眠可能幫助病人保持不動。"},{"en":"After surgery means during the period following an operation.","zh":"after surgery 指手術之後的一段時期。"},{"en":"After surgery, a patient may need rest, pain control, and careful wound care.","zh":"手術後，病人可能需要休息、止痛和小心護理傷口。"},{"en":"The period after surgery matters because movement can affect healing.","zh":"手術後的時期很重要，因為移動可能影響癒合。"},{"en":"This phrase gives the time when recovery or treatment support happens.","zh":"這個短語指出康復或治療支援發生的時間。"}],"source":"72 - Just relax ….pdf","sourcePage":24},{"front":"make drugs unnecessary","meaning":"令藥物變得不必要","examples":[{"en":"The option suggests that hypnosis can make drugs unnecessary.","zh":"該選項表示催眠可以令藥物變得不必要。"},{"en":"To make drugs unnecessary means to remove the need for medicine.","zh":"make drugs unnecessary 指消除對藥物的需要。"},{"en":"Good sleep habits may reduce headaches for some people, but they do not always make drugs unnecessary.","zh":"良好睡眠習慣可能減少某些人的頭痛，但不一定令藥物變得不必要。"},{"en":"A treatment can reduce drug use without replacing medicine completely.","zh":"一種治療可以減少用藥，而不完全取代藥物。"},{"en":"This phrase makes a strong claim about not needing medication.","zh":"這個短語對不需要藥物作出強烈說法。"}],"source":"72 - Just relax ….pdf","sourcePage":24},{"front":"keep the patient mobile","meaning":"讓病人保持活動能力","examples":[{"en":"The option refers to keeping the patient mobile.","zh":"該選項指讓病人保持活動能力。"},{"en":"To keep the patient mobile means to allow the patient to move around.","zh":"keep the patient mobile 指讓病人能夠四處活動。"},{"en":"After some operations, doctors encourage walking to keep the patient mobile and reduce stiffness.","zh":"某些手術後，醫生鼓勵步行，以讓病人保持活動能力並減少僵硬。"},{"en":"Mobility can support recovery, but some treatments require stillness instead.","zh":"活動能力可以支援康復，但有些治療反而需要靜止。"},{"en":"This phrase focuses on movement ability.","zh":"這個短語著重移動能力。"}],"source":"72 - Just relax ….pdf","sourcePage":24},{"front":"forget to move","meaning":"忘記移動","examples":[{"en":"The option suggests that hypnosis makes the patient forget to move.","zh":"該選項表示催眠令病人忘記移動。"},{"en":"To forget to move means to fail to move because the action is not remembered or noticed.","zh":"forget to move 指因沒有記起或注意到動作而沒有移動。"},{"en":"A tired worker may sit for hours and forget to move until their back hurts.","zh":"疲倦工人可能坐了幾小時，直到背痛才發現自己忘記移動。"},{"en":"Forgetting to move is different from choosing to stay still or being guided to remain still.","zh":"忘記移動不同於選擇保持不動或被引導保持靜止。"},{"en":"This phrase describes lack of movement caused by forgetting.","zh":"這個短語描述因忘記而沒有移動。"}],"source":"72 - Just relax ….pdf","sourcePage":24},{"front":"minimise the patient’s discomfort","meaning":"將病人的不適減至最低","examples":[{"en":"Hypnosis may minimise the patient’s discomfort while immobile.","zh":"催眠可能在病人不能移動時將其不適減至最低。"},{"en":"To minimise the patient’s discomfort means to reduce the patient’s pain, awkwardness, or unease as much as possible.","zh":"minimise the patient’s discomfort 指盡可能減少病人的痛楚、尷尬或不安。"},{"en":"Nurses may adjust pillows to minimise a patient’s discomfort during recovery.","zh":"護士可能調整枕頭，以在康復期間將病人不適減至最低。"},{"en":"Reducing discomfort helps patients stay calm and cooperate with treatment.","zh":"減少不適幫助病人保持平靜並配合治療。"},{"en":"This phrase focuses on making suffering smaller, not necessarily removing it completely.","zh":"這個短語著重減少痛苦，而不一定完全消除。"}],"source":"72 - Just relax ….pdf","sourcePage":24},{"front":"while immobile","meaning":"在不能移動時","examples":[{"en":"The patient may remain comfortable while immobile.","zh":"病人在不能移動時仍可能保持舒適。"},{"en":"While immobile means while unable or required not to move.","zh":"while immobile 指在無法移動或被要求不移動時。"},{"en":"A patient in a scan may need to stay calm while immobile for several minutes.","zh":"接受掃描的病人可能需要在不能移動時保持平靜數分鐘。"},{"en":"Remaining still can be difficult if the body becomes stiff or painful.","zh":"如果身體變得僵硬或疼痛，保持不動可能很困難。"},{"en":"This phrase describes a period of no movement.","zh":"這個短語描述沒有移動的一段時間。"}],"source":"72 - Just relax ….pdf","sourcePage":24},{"front":"giving evidence under hypnosis","meaning":"在催眠下作證","examples":[{"en":"Giving evidence under hypnosis may be unreliable.","zh":"在催眠下作證可能不可靠。"},{"en":"Giving evidence under hypnosis means providing legal or investigative information while in or after a hypnotic state.","zh":"giving evidence under hypnosis 指在催眠狀態中或之後提供法律或調查資料。"},{"en":"A witness may speak confidently under hypnosis, but confidence does not prove accuracy.","zh":"目擊者在催眠下可能自信地說話，但自信不證明準確。"},{"en":"This practice is risky because memory can mix fact, suggestion, and imagination.","zh":"這種做法有風險，因為記憶可能混合事實、暗示和想像。"},{"en":"This phrase belongs to legal contexts where reliability is crucial.","zh":"這個短語屬於可靠性至關重要的法律語境。"}],"source":"72 - Just relax ….pdf","sourcePage":24},{"front":"evidence may be unreliable","meaning":"證供可能不可靠","examples":[{"en":"Evidence given under hypnosis may be unreliable.","zh":"在催眠下給出的證供可能不可靠。"},{"en":"Evidence may be unreliable means the information may not be trustworthy enough to depend on.","zh":"evidence may be unreliable 指資料可能不夠可信，不能依賴。"},{"en":"A blurry photo may be unreliable evidence if it cannot clearly show who was present.","zh":"如果模糊照片不能清楚顯示誰在場，它可能是不可靠證據。"},{"en":"Unreliable evidence can lead to unfair or incorrect decisions.","zh":"不可靠證據可以導致不公平或錯誤決定。"},{"en":"This phrase warns that information may look useful but still be unsafe.","zh":"這個短語提醒資料可能看似有用，但仍不安全。"}],"source":"72 - Just relax ….pdf","sourcePage":24},{"front":"secret evidence","meaning":"秘密證據","examples":[{"en":"Hypnosis cannot be used to obtain secret evidence against a person’s will.","zh":"催眠不能用來違背某人意願取得秘密證據。"},{"en":"Secret evidence is hidden or confidential information that someone does not want to reveal.","zh":"secret evidence 指隱藏或機密、某人不想透露的資料。"},{"en":"A password or private conversation could be secret evidence in an investigation.","zh":"密碼或私人對話可能在調查中成為秘密證據。"},{"en":"Legal systems must handle secret evidence carefully because rights and privacy are involved.","zh":"法律制度必須小心處理秘密證據，因為涉及權利和私隱。"},{"en":"This phrase refers to confidential information, not ordinary public facts.","zh":"這個短語指機密資料，而不是普通公開事實。"}],"source":"72 - Just relax ….pdf","sourcePage":25},{"front":"be obtained through hypnosis","meaning":"透過催眠取得","examples":[{"en":"Secret information cannot simply be obtained through hypnosis.","zh":"秘密資料不能簡單地透過催眠取得。"},{"en":"To be obtained through hypnosis means to be gained or discovered by using hypnosis.","zh":"be obtained through hypnosis 指使用催眠來獲得或發現某資料。"},{"en":"A memory recovered through hypnosis may feel vivid, but it still needs careful checking.","zh":"透過催眠取回的記憶可能感覺鮮明，但仍需要仔細核實。"},{"en":"Information obtained through hypnosis may be affected by suggestion or false memory.","zh":"透過催眠取得的資料可能受暗示或虛假記憶影響。"},{"en":"This phrase warns that hypnosis is not a guaranteed way to find truth.","zh":"這個短語提醒我們，催眠並不是尋找真相的保證方法。"}],"source":"72 - Just relax ….pdf","sourcePage":25}],"ielts/reading/passage-2/Practice 73":[{"front":"crop circle phenomenon","meaning":"麥田圈現象","examples":[{"en":"The crop circle phenomenon has puzzled people for many years.","zh":"麥田圈現象多年來一直令人大惑不解。"},{"en":"The crop circle phenomenon refers to mysterious patterns that appear in fields of crops.","zh":"crop circle phenomenon 指出現在農作物田中的神秘圖案現象。"},{"en":"A documentary about the crop circle phenomenon may show farmers discovering strange shapes in wheat fields.","zh":"關於麥田圈現象的紀錄片可能展示農夫在小麥田中發現奇怪形狀。"},{"en":"Because some circles appear suddenly and contain complex designs, the phenomenon has attracted both scientists and ordinary viewers.","zh":"由於有些圓圈突然出現並包含複雜設計，這個現象吸引了科學家和普通觀眾。"},{"en":"The phrase describes the whole mystery, not just one circle in one field.","zh":"這個短語描述整個謎團，而不只是某一塊田中的一個圓圈。"}],"source":"73 - Crop circles.pdf","sourcePage":1},{"front":"puzzled and mystified","meaning":"令人困惑和神秘莫測","examples":[{"en":"The crop circle phenomenon has puzzled and mystified humanity for many years.","zh":"麥田圈現象多年來一直令人類困惑和感到神秘莫測。"},{"en":"Puzzled and mystified means confused and unable to explain something that seems mysterious.","zh":"puzzled and mystified 指感到困惑，並無法解釋某件看似神秘的事。"},{"en":"Students may feel puzzled and mystified when a maths answer appears correct but the teacher marks it wrong.","zh":"當數學答案看起來正確但老師判錯，學生可能感到困惑。"},{"en":"A mystery becomes more powerful when people cannot easily find a cause.","zh":"當人們不能輕易找到原因，謎團就會更有力量。"},{"en":"The phrase suggests both confusion and a sense of wonder.","zh":"這個短語暗示困惑，也暗示驚奇感。"}],"source":"73 - Crop circles.pdf","sourcePage":1},{"front":"for many years","meaning":"多年來","examples":[{"en":"Crop circles have attracted attention for many years.","zh":"麥田圈多年來一直吸引注意。"},{"en":"For many years means over a long period of time.","zh":"for many years 指經過很長一段時間。"},{"en":"A teacher may keep the same notebook for many years because it contains useful examples.","zh":"老師可能多年來都保留同一本筆記，因為它包含有用例子。"},{"en":"When a mystery lasts for many years, more stories and theories usually appear.","zh":"當謎團持續多年，通常會出現更多故事和理論。"},{"en":"The phrase stresses duration rather than one single event.","zh":"這個短語強調持續時間，而不是單一事件。"}],"source":"73 - Crop circles.pdf","sourcePage":1},{"front":"appear in fields of grain","meaning":"出現在穀物田中","examples":[{"en":"The designs appear in fields of grain.","zh":"這些圖案出現在穀物田中。"},{"en":"To appear in fields of grain means to be found in areas where crops such as wheat or oats are growing.","zh":"appear in fields of grain 指在種植小麥或燕麥等作物的田地中出現。"},{"en":"A farmer may notice unusual patterns when walking through a field of grain before harvest.","zh":"農夫可能在收割前走過穀物田時注意到異常圖案。"},{"en":"Because the designs appear in crops, they can damage plants and attract visitors.","zh":"因為這些圖案出現在農作物中，它們可以損害植物並吸引遊客。"},{"en":"The phrase describes where the patterns are seen.","zh":"這個短語描述圖案出現的位置。"}],"source":"73 - Crop circles.pdf","sourcePage":1},{"front":"placed carefully","meaning":"被仔細放置；被精心排列","examples":[{"en":"The designs seem to be placed carefully in the fields.","zh":"這些圖案看似被仔細放置在田中。"},{"en":"Placed carefully means arranged with attention, order, or planning.","zh":"placed carefully 指被有心思、有秩序或有計劃地安排。"},{"en":"A teacher may place chairs carefully before a class debate so every student can see the speaker.","zh":"老師可能在班級辯論前仔細擺放椅子，使每名學生都能看見發言者。"},{"en":"When a pattern looks carefully placed, people may think it was made deliberately.","zh":"當圖案看起來被精心排列，人們可能認為它是刻意製造的。"},{"en":"The phrase suggests order rather than random damage.","zh":"這個短語暗示有秩序，而不是隨機破壞。"}],"source":"73 - Crop circles.pdf","sourcePage":1},{"front":"highly complex in design and construction","meaning":"在設計和結構上非常複雜","examples":[{"en":"Some crop circles are highly complex in design and construction.","zh":"一些麥田圈在設計和結構上非常複雜。"},{"en":"Highly complex in design and construction means difficult to plan and build because many parts fit together carefully.","zh":"highly complex in design and construction 指因許多部分精細配合而難以規劃和建造。"},{"en":"A school science model may be highly complex if it includes lights, moving parts, and labelled sections.","zh":"如果學校科學模型有燈光、活動部件和標籤，它可能在設計上非常複雜。"},{"en":"Complex designs make people wonder whether they could be made quickly or by simple tools.","zh":"複雜設計令人想知道它是否能快速或用簡單工具製成。"},{"en":"The phrase stresses both the pattern and how it was made.","zh":"這個短語同時強調圖案和製作方式。"}],"source":"73 - Crop circles.pdf","sourcePage":1},{"front":"primitive","meaning":"原始的；簡單粗糙的","examples":[{"en":"Other crop circles are smaller and more primitive.","zh":"其他麥田圈較小，也較簡單粗糙。"},{"en":"Primitive means simple, basic, or not technically advanced.","zh":"primitive 指簡單、基本或技術上不先進。"},{"en":"A child’s first drawing of a house may look primitive, but it still shows clear meaning.","zh":"孩子第一次畫房子可能看起來很簡單粗糙，但仍顯示清楚意思。"},{"en":"Primitive designs may be easier to make and less likely to require advanced planning.","zh":"原始設計可能較容易製作，也較不需要高階規劃。"},{"en":"The word can sound slightly critical when it means rough or undeveloped.","zh":"當這個詞指粗糙或未發展時，可能帶輕微批評意味。"}],"source":"73 - Crop circles.pdf","sourcePage":1},{"front":"not circular","meaning":"不是圓形的","examples":[{"en":"Many crop circles are not actually circular.","zh":"許多麥田圈其實不是圓形的。"},{"en":"Not circular means not shaped like a true circle.","zh":"not circular 指形狀不是一個真正的圓。"},{"en":"A table may look round from far away but be not circular when measured closely.","zh":"桌子遠看可能像圓形，但仔細量度後可能不是圓形。"},{"en":"If crop circles include lines and triangles, the name “circle” may be misleading.","zh":"如果麥田圈包括線條和三角形，circle 這個名稱可能有誤導性。"},{"en":"The phrase corrects the assumption created by the word circle.","zh":"這個短語糾正 circle 一詞帶來的假設。"}],"source":"73 - Crop circles.pdf","sourcePage":1},{"front":"elongated abstract designs","meaning":"拉長的抽象圖案","examples":[{"en":"Some crop circles are elongated abstract designs.","zh":"一些麥田圈是拉長的抽象圖案。"},{"en":"Elongated abstract designs are stretched, non-realistic patterns that do not clearly represent everyday objects.","zh":"elongated abstract designs 指被拉長、非寫實、未必清楚代表日常物件的圖案。"},{"en":"A modern painting may use elongated abstract designs made from lines and curves.","zh":"現代畫作可能使用由線條和曲線組成的拉長抽象圖案。"},{"en":"Such shapes can make a pattern look artistic, mysterious, or difficult to interpret.","zh":"這些形狀可以令圖案看起來有藝術感、神秘或難以解讀。"},{"en":"The phrase describes both shape and style.","zh":"這個短語同時描述形狀和風格。"}],"source":"73 - Crop circles.pdf","sourcePage":1},{"front":"resemble insects","meaning":"類似昆蟲","examples":[{"en":"A few crop circles resemble insects.","zh":"少數麥田圈類似昆蟲。"},{"en":"To resemble insects means to look like insects in shape or appearance.","zh":"resemble insects 指在形狀或外觀上看似昆蟲。"},{"en":"A kite may resemble a butterfly if it has wide wings and bright colours.","zh":"如果風箏有寬闊翅膀和鮮艷顏色，它可能類似蝴蝶。"},{"en":"When a pattern resembles a living thing, people may think it was designed intentionally.","zh":"當圖案類似生物，人們可能認為它是刻意設計的。"},{"en":"The phrase describes visual similarity, not actual identity.","zh":"這個短語描述外觀相似，而不是真正身份。"}],"source":"73 - Crop circles.pdf","sourcePage":1},{"front":"known forms","meaning":"已知形態","examples":[{"en":"Some crop circles resemble insects or other known forms.","zh":"一些麥田圈類似昆蟲或其他已知形態。"},{"en":"Known forms are shapes or objects people can recognise from experience.","zh":"known forms 指人們憑經驗可以辨認的形狀或物件。"},{"en":"A cloud may look like a known form, such as a face, dog, or mountain.","zh":"雲朵可能看似某種已知形態，例如臉、狗或山。"},{"en":"When a design resembles a known form, viewers can describe it more easily.","zh":"當設計類似已知形態，觀眾就能更容易描述它。"},{"en":"The phrase contrasts recognisable shapes with purely abstract patterns.","zh":"這個短語把可辨認形狀與純抽象圖案作對比。"}],"source":"73 - Crop circles.pdf","sourcePage":1},{"front":"mixtures of","meaning":"……的混合","examples":[{"en":"Some designs are mixtures of lines, circles and other shapes.","zh":"一些圖案是線條、圓圈和其他形狀的混合。"},{"en":"Mixtures of things are combinations of different elements placed together.","zh":"mixtures of things 指不同元素放在一起的組合。"},{"en":"A student’s poster may use mixtures of photos, drawings, arrows, and short notes.","zh":"學生海報可能使用照片、圖畫、箭嘴和短筆記的混合。"},{"en":"When designs use many mixed elements, they may look more complex and planned.","zh":"當設計使用許多混合元素，它們可能看起來更複雜和有計劃。"},{"en":"The phrase focuses on combination.","zh":"這個短語重點是組合。"}],"source":"73 - Crop circles.pdf","sourcePage":2},{"front":"melded into","meaning":"融合成","examples":[{"en":"Lines, circles and other shapes are melded into intricate patterns.","zh":"線條、圓圈和其他形狀融合成複雜精細的圖案。"},{"en":"Melded into means joined or blended together to form something new.","zh":"melded into 指被結合或混合成新的整體。"},{"en":"In a good group project, different students’ ideas are melded into one clear presentation.","zh":"在好的小組項目中，不同學生的想法會融合成一份清晰簡報。"},{"en":"When many shapes are melded together, the final pattern can become harder to explain.","zh":"當許多形狀融合在一起，最終圖案可能變得更難解釋。"},{"en":"The phrase suggests smooth combination rather than separate pieces.","zh":"這個短語暗示順暢結合，而不是分離部分。"}],"source":"73 - Crop circles.pdf","sourcePage":2},{"front":"intricate patterns","meaning":"複雜精細的圖案","examples":[{"en":"Many crop circles contain intricate patterns.","zh":"許多麥田圈包含複雜精細的圖案。"},{"en":"Intricate patterns are detailed designs with many carefully connected parts.","zh":"intricate patterns 指有許多精心連接部分的細緻設計。"},{"en":"A wedding invitation may have intricate patterns around the edge of the paper.","zh":"婚禮邀請卡的紙邊可能有複雜精細的圖案。"},{"en":"Intricate patterns take time to design and can be difficult to copy accurately.","zh":"複雜精細圖案需要時間設計，也可能難以準確複製。"},{"en":"The phrase stresses fine detail and complexity.","zh":"這個短語強調細節和複雜度。"}],"source":"73 - Crop circles.pdf","sourcePage":2},{"front":"become visible overnight","meaning":"一夜之間變得可見","examples":[{"en":"Most crop circles become visible overnight.","zh":"大多數麥田圈一夜之間變得可見。"},{"en":"Become visible overnight means appear or become noticeable during one night.","zh":"become visible overnight 指在一晚之間出現或變得可被看見。"},{"en":"A street mural may become visible overnight if artists paint it while the neighbourhood is asleep.","zh":"如果藝術家在社區睡覺時完成街頭壁畫，它可能一夜之間變得可見。"},{"en":"Sudden appearance can make people wonder how something was created so quickly.","zh":"突然出現會令人想知道某事如何如此快速被創造。"},{"en":"The phrase stresses speed and surprise.","zh":"這個短語強調速度和驚訝感。"}],"source":"73 - Crop circles.pdf","sourcePage":2},{"front":"it has been claimed that","meaning":"有人聲稱","examples":[{"en":"It has been claimed that some crop circles appeared within half an hour.","zh":"有人聲稱一些麥田圈在半小時內出現。"},{"en":"It has been claimed that means some people have said something, but the writer is not necessarily confirming it.","zh":"it has been claimed that 指有人說某事，但作者不一定確認它是真的。"},{"en":"It has been claimed that a new study method can double memory, but students should check the evidence.","zh":"有人聲稱新學習方法可以令記憶加倍，但學生應查核證據。"},{"en":"The phrase is useful when reporting uncertain or disputed information.","zh":"這個短語適合報告不確定或有爭議資料。"},{"en":"It keeps distance between the writer and the claim.","zh":"它讓作者與該聲稱保持距離。"}],"source":"73 - Crop circles.pdf","sourcePage":2},{"front":"within half an hour","meaning":"在半小時內","examples":[{"en":"Some crop circles reportedly appeared within half an hour.","zh":"據報一些麥田圈在半小時內出現。"},{"en":"Within half an hour means in thirty minutes or less.","zh":"within half an hour 指在三十分鐘或更短時間內。"},{"en":"A student may finish a short vocabulary quiz within half an hour.","zh":"學生可能在半小時內完成短詞彙測驗。"},{"en":"If a complex pattern appears within half an hour, people may find the timing surprising.","zh":"如果複雜圖案在半小時內出現，人們可能覺得時間安排令人驚訝。"},{"en":"The phrase sets a short time limit.","zh":"這個短語設定很短的時間限制。"}],"source":"73 - Crop circles.pdf","sourcePage":2},{"front":"in broad daylight","meaning":"在光天化日之下","examples":[{"en":"A few crop circles are said to have appeared in broad daylight.","zh":"據說少數麥田圈在光天化日之下出現。"},{"en":"In broad daylight means during the day when it is bright and easy to see.","zh":"in broad daylight 指在日間光線充足、容易看見時。"},{"en":"A theft in broad daylight may shock people because witnesses could have seen it.","zh":"光天化日之下發生盜竊可能令人震驚，因為目擊者本來可能看見。"},{"en":"If a mysterious event happens in daylight, it seems harder to explain as something hidden.","zh":"如果神秘事件在日光下發生，它似乎較難被解釋為隱藏行為。"},{"en":"The phrase contrasts openness and visibility with secrecy.","zh":"這個短語把公開可見與秘密作對比。"}],"source":"73 - Crop circles.pdf","sourcePage":2},{"front":"all over the world","meaning":"世界各地","examples":[{"en":"Crop circles have appeared all over the world.","zh":"麥田圈已出現在世界各地。"},{"en":"All over the world means in many countries and regions globally.","zh":"all over the world 指在全球許多國家和地區。"},{"en":"Students all over the world use online videos to learn English.","zh":"世界各地的學生使用網上影片學習英文。"},{"en":"When a phenomenon appears globally, it attracts more public and scientific attention.","zh":"當現象在全球出現，它會吸引更多公眾和科學關注。"},{"en":"The phrase stresses wide geographical spread.","zh":"這個短語強調廣泛地理分布。"}],"source":"73 - Crop circles.pdf","sourcePage":2},{"front":"instances from various countries","meaning":"來自不同國家的個案","examples":[{"en":"About 10,000 instances from various countries have been reported.","zh":"約一萬個來自不同國家的個案已被報告。"},{"en":"Instances from various countries means cases reported in different nations.","zh":"instances from various countries 指在不同國家被報告的案例。"},{"en":"A health report may collect instances of a disease from various countries to compare patterns.","zh":"健康報告可能收集來自不同國家的疾病個案，以比較模式。"},{"en":"When cases come from many places, the issue seems less local and more widespread.","zh":"當個案來自許多地方，問題就顯得不只是本地，而是更廣泛。"},{"en":"The phrase focuses on reported examples across countries.","zh":"這個短語重點是跨國報告例子。"}],"source":"73 - Crop circles.pdf","sourcePage":2},{"front":"in recent years","meaning":"近年來","examples":[{"en":"Many crop circles have been reported in recent years.","zh":"近年來有許多麥田圈被報告。"},{"en":"In recent years means during the last few years or the modern period being discussed.","zh":"in recent years 指在最近幾年或正在討論的現代時期中。"},{"en":"In recent years, many schools have used more online learning tools.","zh":"近年來，許多學校使用更多網上學習工具。"},{"en":"Recent reports can make an old mystery feel active and current.","zh":"近期報告可以令舊謎團感覺仍活躍和貼近現在。"},{"en":"The phrase gives a broad recent time frame.","zh":"這個短語提供廣泛近期時間範圍。"}],"source":"73 - Crop circles.pdf","sourcePage":2},{"front":"the first modern rash of","meaning":"首次現代大規模出現","examples":[{"en":"The first modern rash of crop circles appeared in Australia.","zh":"首次現代大規模麥田圈出現在澳洲。"},{"en":"The first modern rash of something means the first sudden large number of cases in the modern period.","zh":"first modern rash of something 指某事在現代時期首次突然大量出現。"},{"en":"A school may see the first modern rash of online cheating after students begin using new apps.","zh":"學生開始使用新應用程式後，學校可能首次現代大規模出現網上作弊個案。"},{"en":"A rash of reports can make people think a phenomenon is spreading quickly.","zh":"大量報告可以令人認為某現象正在迅速擴散。"},{"en":"The phrase suggests a sudden cluster, not one isolated example.","zh":"這個短語暗示突然出現的一批，而不是孤立例子。"}],"source":"73 - Crop circles.pdf","sourcePage":2},{"front":"a circular imprint","meaning":"圓形印痕","examples":[{"en":"A strange circular imprint appeared in a wheat field.","zh":"一個奇怪的圓形印痕出現在小麥田中。"},{"en":"A circular imprint is a round mark pressed or left on a surface.","zh":"circular imprint 指壓在或留在表面上的圓形痕跡。"},{"en":"A wet cup may leave a circular imprint on a wooden table.","zh":"濕杯子可能在木桌上留下圓形印痕。"},{"en":"An imprint in crops can show where plants were pressed down.","zh":"農作物中的印痕可以顯示植物在哪裡被壓倒。"},{"en":"The phrase describes a visible round mark.","zh":"這個短語描述可見的圓形痕跡。"}],"source":"73 - Crop circles.pdf","sourcePage":3},{"front":"a wheat field","meaning":"小麥田","examples":[{"en":"A circular imprint appeared in a wheat field near Wokurna.","zh":"一個圓形印痕出現在 Wokurna 附近的小麥田中。"},{"en":"A wheat field is farmland where wheat is grown.","zh":"wheat field 指種植小麥的農田。"},{"en":"A farmer may walk through a wheat field to check whether the crop is ready for harvest.","zh":"農夫可能走過小麥田，檢查作物是否準備收割。"},{"en":"If patterns appear in a wheat field, flattened plants can affect the crop and the farmer’s income.","zh":"如果圖案出現在小麥田中，被壓平的植物可能影響作物和農夫收入。"},{"en":"The phrase names the type of crop field.","zh":"這個短語指出農作物田的類型。"}],"source":"73 - Crop circles.pdf","sourcePage":3},{"front":"southeast of","meaning":"在……東南面","examples":[{"en":"Wokurna is southeast of Adelaide.","zh":"Wokurna 位於 Adelaide 東南面。"},{"en":"Southeast of a place means located in the direction between south and east from that place.","zh":"southeast of a place 指位於該地南方和東方之間的方向。"},{"en":"A village southeast of the city may be reached by driving down and to the right on a map.","zh":"城市東南面的村莊，在地圖上可能要向下和向右駕車前往。"},{"en":"Giving direction helps readers locate where an event happened.","zh":"提供方向幫助讀者定位事件發生地點。"},{"en":"The phrase describes geographical position.","zh":"這個短語描述地理位置。"}],"source":"73 - Crop circles.pdf","sourcePage":3},{"front":"swirled circles","meaning":"呈旋渦狀的圓圈","examples":[{"en":"Seven swirled circles appeared in an oat field nearby.","zh":"七個呈旋渦狀的圓圈出現在附近一片燕麥田中。"},{"en":"Swirled circles are round patterns in which material appears twisted or rotated around a centre.","zh":"swirled circles 指材料看似圍繞中心扭動或旋轉的圓形圖案。"},{"en":"A child may draw swirled circles when making a spiral pattern on paper.","zh":"孩子在紙上畫螺旋圖案時，可能畫出旋渦狀圓圈。"},{"en":"Swirling in crops can suggest movement, pressure, or rotation during formation.","zh":"農作物中的旋渦狀可能暗示形成時有移動、壓力或旋轉。"},{"en":"The phrase describes the visual pattern of the circles.","zh":"這個短語描述圓圈的視覺圖案。"}],"source":"73 - Crop circles.pdf","sourcePage":3},{"front":"up to 14 feet in diameter","meaning":"直徑達十四呎","examples":[{"en":"The swirled circles were up to 14 feet in diameter.","zh":"這些旋渦狀圓圈直徑達十四呎。"},{"en":"Up to 14 feet in diameter means the widest circles measured as much as 14 feet across.","zh":"up to 14 feet in diameter 指最大的圓圈橫跨距離達十四呎。"},{"en":"A classroom rug may be up to ten feet in diameter if it covers a large reading area.","zh":"如果課室地氈覆蓋大型閱讀區，它的直徑可能達十呎。"},{"en":"Giving diameter helps readers imagine the physical size of a circle.","zh":"提供直徑幫助讀者想像圓圈實際大小。"},{"en":"The phrase sets a maximum measurement.","zh":"這個短語設定最高量度值。"}],"source":"73 - Crop circles.pdf","sourcePage":3},{"front":"in diameter","meaning":"直徑為","examples":[{"en":"The circles ranged from a few inches to a few feet in diameter.","zh":"這些圓圈直徑由數吋至數呎不等。"},{"en":"In diameter means measured straight across a circle through its centre.","zh":"in diameter 指穿過圓心、由一邊到另一邊的直線量度。"},{"en":"A pizza may be twelve inches in diameter from one edge to the opposite edge.","zh":"薄餅由一邊到對面邊緣可能直徑為十二吋。"},{"en":"Diameter helps compare the sizes of round objects clearly.","zh":"直徑幫助清楚比較圓形物件大小。"},{"en":"The phrase is used for circles and round shapes.","zh":"這個短語用於圓形和圓狀物。"}],"source":"73 - Crop circles.pdf","sourcePage":3},{"front":"an oat field","meaning":"燕麥田","examples":[{"en":"Several circles appeared in an oat field nearby.","zh":"幾個圓圈出現在附近一片燕麥田中。"},{"en":"An oat field is farmland where oats are grown.","zh":"oat field 指種植燕麥的農田。"},{"en":"A farmer may grow oats to make animal feed or breakfast cereal products.","zh":"農夫可能種植燕麥，用來製作動物飼料或早餐穀物產品。"},{"en":"Crop marks in an oat field can be noticed when stalks are flattened or bent.","zh":"當莖被壓平或折彎，燕麥田中的作物痕跡就會被注意到。"},{"en":"The phrase identifies the type of grain field.","zh":"這個短語指出穀物田的類型。"}],"source":"73 - Crop circles.pdf","sourcePage":3},{"front":"an amazing set of circles","meaning":"一組令人驚訝的圓圈","examples":[{"en":"An amazing set of circles appeared west of Melbourne.","zh":"一組令人驚訝的圓圈出現在墨爾本以西。"},{"en":"An amazing set of circles means a group of round patterns that seems surprising or impressive.","zh":"amazing set of circles 指一組令人驚奇或印象深刻的圓形圖案。"},{"en":"A child may arrange stones into an amazing set of circles in a playground.","zh":"孩子可能在操場上把石頭排成一組令人驚訝的圓圈。"},{"en":"When many circles appear together, the sight can feel more remarkable than one simple mark.","zh":"當許多圓圈一起出現，景象可能比一個簡單痕跡更令人注目。"},{"en":"The phrase stresses both number and impact.","zh":"這個短語同時強調數量和效果。"}],"source":"73 - Crop circles.pdf","sourcePage":3},{"front":"ranging from…to…","meaning":"由……至……不等","examples":[{"en":"The circles ranged from a few inches to a few feet in diameter.","zh":"這些圓圈直徑由數吋至數呎不等。"},{"en":"Ranging from A to B means varying between a smaller amount and a larger amount.","zh":"ranging from A to B 指在較小數量和較大數量之間變化。"},{"en":"A class project may include posters ranging from simple drawings to detailed models.","zh":"班級項目可能包括由簡單圖畫至詳細模型不等的作品。"},{"en":"A wide range of sizes can make a phenomenon harder to classify neatly.","zh":"大小範圍很廣可以令現象更難清楚分類。"},{"en":"The phrase shows variety within limits.","zh":"這個短語顯示範圍內的多樣性。"}],"source":"73 - Crop circles.pdf","sourcePage":3},{"front":"the wheat belt","meaning":"小麥種植帶","examples":[{"en":"The circles appeared in the wheat belt west of Melbourne.","zh":"這些圓圈出現在墨爾本以西的小麥種植帶。"},{"en":"The wheat belt is an area where wheat is grown widely.","zh":"wheat belt 指廣泛種植小麥的地區。"},{"en":"A farming report may describe rainfall in the wheat belt because it affects harvests.","zh":"農業報告可能描述小麥種植帶的降雨，因為它影響收成。"},{"en":"If crop circles appear in the wheat belt, many farms may report similar marks.","zh":"如果麥田圈出現在小麥種植帶，許多農場可能報告類似痕跡。"},{"en":"The phrase describes an agricultural region.","zh":"這個短語描述農業地區。"}],"source":"73 - Crop circles.pdf","sourcePage":3},{"front":"as many as","meaning":"多達","examples":[{"en":"As many as 90 crop circles were found.","zh":"發現了多達九十個麥田圈。"},{"en":"As many as means a surprisingly large number up to that amount.","zh":"as many as 指數量多到某個程度，通常令人驚訝。"},{"en":"As many as thirty students may join the debate club if the teacher promotes it well.","zh":"如果老師推廣得好，多達三十名學生可能加入辯論學會。"},{"en":"The phrase often signals that the number is higher than expected.","zh":"這個短語通常表示數量高於預期。"},{"en":"It draws attention to quantity.","zh":"它把注意力放在數量上。"}],"source":"73 - Crop circles.pdf","sourcePage":3},{"front":"the best documented","meaning":"記錄最詳盡的","examples":[{"en":"The best documented spread of crop circles began in southern England.","zh":"記錄最詳盡的麥田圈擴散始於英格蘭南部。"},{"en":"The best documented means supported by the most detailed records or evidence.","zh":"best documented 指有最詳細記錄或證據支持。"},{"en":"A school’s best documented project may include photos, reports, interviews, and data.","zh":"學校記錄最詳盡的項目可能包括照片、報告、訪談和數據。"},{"en":"When something is well documented, researchers can study it more carefully.","zh":"當某事記錄詳盡，研究人員可以更仔細研究它。"},{"en":"The phrase focuses on the quality and amount of records.","zh":"這個短語重點是記錄的質素和數量。"}],"source":"73 - Crop circles.pdf","sourcePage":4},{"front":"the largest modern spread of","meaning":"現代最大規模的……擴散","examples":[{"en":"The largest modern spread of crop circles began in southern England.","zh":"現代最大規模的麥田圈擴散始於英格蘭南部。"},{"en":"The largest modern spread of something means the biggest recent expansion or occurrence of that phenomenon.","zh":"largest modern spread of something 指某現象在現代最大規模的擴展或出現。"},{"en":"A city may experience the largest modern spread of bicycle use after building safe lanes.","zh":"城市建造安全單車徑後，可能經歷現代最大規模的單車使用擴散。"},{"en":"When a phenomenon spreads widely in one period, it becomes easier to notice and record.","zh":"當現象在某時期廣泛擴散，它就更容易被注意和記錄。"},{"en":"The phrase stresses scale in modern times.","zh":"這個短語強調現代時期的規模。"}],"source":"73 - Crop circles.pdf","sourcePage":4},{"front":"by the end of","meaning":"到……結束時","examples":[{"en":"By the end of 1988, 112 new circles had been formed.","zh":"到1988年結束時，已有112個新圓圈形成。"},{"en":"By the end of a period means before or at the time that period finishes.","zh":"by the end of a period 指在某段時期結束前或結束時。"},{"en":"By the end of the school year, students should understand the main grammar rules.","zh":"到學年結束時，學生應理解主要文法規則。"},{"en":"The phrase helps show how much had happened before a deadline or endpoint.","zh":"這個短語幫助顯示在期限或終點前已發生多少事。"},{"en":"It marks a time boundary.","zh":"它標示時間界線。"}],"source":"73 - Crop circles.pdf","sourcePage":4},{"front":"had been formed","meaning":"已經形成","examples":[{"en":"By the end of 1988, 112 new circles had been formed.","zh":"到1988年結束時，已有112個新圓圈形成。"},{"en":"Had been formed means had already been created or had come into existence before a past time.","zh":"had been formed 指在過去某時間點之前已被創造或已經出現。"},{"en":"By the time the teacher arrived, three study groups had been formed.","zh":"老師到達時，三個學習小組已經形成。"},{"en":"This tense shows that the formation happened before another past point.","zh":"這個時態顯示形成發生在另一個過去時間點之前。"},{"en":"The phrase is passive, so it focuses on the circles rather than who made them.","zh":"這個短語是被動語態，因此重點是圓圈，而不是誰製造它們。"}],"source":"73 - Crop circles.pdf","sourcePage":4},{"front":"reported worldwide","meaning":"在全球被報告","examples":[{"en":"By the end of 1989, 305 circles had been reported worldwide.","zh":"到1989年結束時，全球已有305個圓圈被報告。"},{"en":"Reported worldwide means recorded or announced in many parts of the world.","zh":"reported worldwide 指在世界許多地方被記錄或公布。"},{"en":"A product problem may be reported worldwide if customers in many countries complain.","zh":"如果許多國家的顧客投訴，產品問題可能在全球被報告。"},{"en":"Worldwide reports can make a local mystery seem international.","zh":"全球報告可以令本地謎團看似國際現象。"},{"en":"The phrase stresses global reporting, not necessarily global proof.","zh":"這個短語強調全球報告，而不一定是全球證明。"}],"source":"73 - Crop circles.pdf","sourcePage":4},{"front":"grew to an astounding","meaning":"增加至驚人的……","examples":[{"en":"The total grew to an astounding 1,000 newly formed circles in 1990.","zh":"總數在1990年增加至驚人的1,000個新形成圓圈。"},{"en":"Grew to an astounding number means increased to a surprisingly large amount.","zh":"grew to an astounding number 指增加到令人驚訝的大數量。"},{"en":"A school club may grow to an astounding 200 members after one viral video.","zh":"一個學校學會在一段爆紅影片後，可能增加至驚人的200名會員。"},{"en":"Rapid growth can make people wonder what caused the sudden increase.","zh":"迅速增長會令人想知道突然增加的原因。"},{"en":"The phrase emphasises surprise at the final number.","zh":"這個短語強調對最終數字的驚訝。"}],"source":"73 - Crop circles.pdf","sourcePage":4},{"front":"newly formed circles","meaning":"新形成的圓圈","examples":[{"en":"Many newly formed circles were reported in 1990.","zh":"1990年有許多新形成的圓圈被報告。"},{"en":"Newly formed circles are circles that have recently appeared or been created.","zh":"newly formed circles 指最近出現或被創造的圓圈。"},{"en":"Newly formed groups in a class may need time to learn how to work together.","zh":"班中新形成的小組可能需要時間學習如何合作。"},{"en":"Recent formation makes people more likely to investigate before evidence disappears.","zh":"新近形成會令人更可能在證據消失前調查。"},{"en":"The phrase focuses on circles that are new, not old marks.","zh":"這個短語重點是新的圓圈，而不是舊痕跡。"}],"source":"73 - Crop circles.pdf","sourcePage":4},{"front":"have been documented in","meaning":"已在……有記錄","examples":[{"en":"Crop circles have been documented in over 30 countries.","zh":"麥田圈已在三十多個國家有記錄。"},{"en":"Have been documented in means have been recorded with reports, photos, or other evidence in a place.","zh":"have been documented in 指在某地已有報告、照片或其他證據記錄。"},{"en":"Rare birds have been documented in the wetland by scientists and photographers.","zh":"科學家和攝影師已在濕地記錄到稀有鳥類。"},{"en":"Documentation allows researchers to compare cases across places and years.","zh":"記錄讓研究人員比較不同地方和年份的個案。"},{"en":"The phrase focuses on recorded evidence.","zh":"這個短語重點是有紀錄證據。"}],"source":"73 - Crop circles.pdf","sourcePage":4},{"front":"the former Soviet Union","meaning":"前蘇聯","examples":[{"en":"Crop circles were documented in the former Soviet Union.","zh":"麥田圈在前蘇聯也有記錄。"},{"en":"The former Soviet Union refers to the country that existed before it broke into several independent states.","zh":"former Soviet Union 指在解體成多個獨立國家前存在的國家。"},{"en":"A history lesson may discuss the former Soviet Union when explaining twentieth-century politics.","zh":"歷史課解釋二十世紀政治時，可能討論前蘇聯。"},{"en":"Mentioning it helps show that reports came from a wide geographical area.","zh":"提到它有助顯示報告來自廣泛地理範圍。"},{"en":"The phrase is a historical place reference.","zh":"這個短語是歷史地點指稱。"}],"source":"73 - Crop circles.pdf","sourcePage":4},{"front":"nine out of ten","meaning":"十個之中有九個","examples":[{"en":"Nine out of ten circles remain simple.","zh":"十個圓圈之中有九個仍然保持簡單。"},{"en":"Nine out of ten means 90 percent, or most of the group.","zh":"nine out of ten 指百分之九十，或該群體中的大多數。"},{"en":"If nine out of ten students pass a test, only one in ten fails.","zh":"如果十個學生之中有九個通過測驗，只有十分之一不合格。"},{"en":"The phrase helps readers understand proportion without using a percentage sign.","zh":"這個短語幫助讀者不用百分號也理解比例。"},{"en":"It shows that the majority share a feature.","zh":"它顯示大多數都有某特徵。"}],"source":"73 - Crop circles.pdf","sourcePage":4},{"front":"remain simple","meaning":"保持簡單","examples":[{"en":"Most crop circles remain simple.","zh":"大多數麥田圈保持簡單。"},{"en":"Remain simple means continue to be basic and not become complicated.","zh":"remain simple 指繼續保持基本，不變得複雜。"},{"en":"A good classroom rule may remain simple so younger students can remember it.","zh":"好的課室規則可能保持簡單，讓年幼學生記得住。"},{"en":"Simple patterns are easier to explain and reproduce than complex ones.","zh":"簡單圖案比複雜圖案更容易解釋和重現。"},{"en":"The phrase stresses continuing simplicity.","zh":"這個短語強調持續簡單。"}],"source":"73 - Crop circles.pdf","sourcePage":4},{"front":"broken stems","meaning":"折斷的莖","examples":[{"en":"The crop circles contain broken stems flattened to the ground.","zh":"麥田圈包含被壓平到地面的折斷莖。"},{"en":"Broken stems are plant stalks that have snapped, bent, or been damaged.","zh":"broken stems 指斷裂、彎折或受損的植物莖。"},{"en":"After a storm, a farmer may find broken stems across a field.","zh":"風暴後，農夫可能在田間發現折斷的莖。"},{"en":"Broken stems can show that crops were physically pressed or disturbed.","zh":"折斷的莖可以顯示作物曾被實體壓下或干擾。"},{"en":"The phrase describes damage to plant structure.","zh":"這個短語描述植物結構受損。"}],"source":"73 - Crop circles.pdf","sourcePage":5},{"front":"flattened to the ground","meaning":"被壓平到地面","examples":[{"en":"The stems are flattened to the ground.","zh":"這些莖被壓平到地面。"},{"en":"Flattened to the ground means pressed down until lying close to the earth’s surface.","zh":"flattened to the ground 指被壓下直到貼近地面。"},{"en":"Grass may be flattened to the ground after many students sit on it during sports day.","zh":"運動會期間許多學生坐在草地上後，草可能被壓平到地面。"},{"en":"When crops are flattened, the pattern becomes visible from above.","zh":"當農作物被壓平，圖案從上方看就變得可見。"},{"en":"The phrase describes downward physical pressure.","zh":"這個短語描述向下的實體壓力。"}],"source":"73 - Crop circles.pdf","sourcePage":5},{"front":"remain completely erect","meaning":"保持完全直立","examples":[{"en":"The stalks around the circles remain completely erect.","zh":"圓圈周圍的莖仍保持完全直立。"},{"en":"Remain completely erect means continue standing fully upright.","zh":"remain completely erect 指繼續完全直立地站着。"},{"en":"After heavy rain, some flowers fall over while others remain completely erect.","zh":"大雨後，有些花倒下，而另一些仍保持完全直立。"},{"en":"Upright stalks around a flattened area make the circle’s boundary clearer.","zh":"被壓平區域周圍的直立莖令圓圈邊界更清楚。"},{"en":"The phrase contrasts standing plants with flattened plants.","zh":"這個短語把直立植物與被壓平植物作對比。"}],"source":"73 - Crop circles.pdf","sourcePage":5},{"front":"over the years","meaning":"多年來","examples":[{"en":"Over the years, crop circles have become more complex.","zh":"多年來，麥田圈變得更複雜。"},{"en":"Over the years means gradually across a long period of time.","zh":"over the years 指在很長一段時間中逐漸地。"},{"en":"Over the years, a teacher may collect hundreds of useful examples for students.","zh":"多年來，老師可能為學生收集數百個有用例子。"},{"en":"Slow change over many years can reveal a clear trend.","zh":"多年慢慢發生的變化可以揭示清楚趨勢。"},{"en":"The phrase stresses development through time.","zh":"這個短語強調隨時間發展。"}],"source":"73 - Crop circles.pdf","sourcePage":5},{"front":"geometrically intricate","meaning":"幾何上非常精細複雜","examples":[{"en":"Crop circles have become much more geometrically intricate.","zh":"麥田圈在幾何上變得精細複雜得多。"},{"en":"Geometrically intricate means complex in shapes, angles, symmetry, or mathematical design.","zh":"geometrically intricate 指在形狀、角度、對稱或數學設計上複雜。"},{"en":"A mosque floor may have geometrically intricate patterns made of repeating tiles.","zh":"清真寺地板可能有由重複瓷磚組成的精細幾何圖案。"},{"en":"Intricate geometry makes designs look planned and difficult to produce by accident.","zh":"精細幾何令設計看似有計劃，並難以由意外造成。"},{"en":"The phrase combines mathematics with visual complexity.","zh":"這個短語把數學與視覺複雜度結合。"}],"source":"73 - Crop circles.pdf","sourcePage":5},{"front":"patterns have involved","meaning":"圖案包含了","examples":[{"en":"The patterns have involved multiple circles, bars and triangles.","zh":"這些圖案包含了多個圓圈、長條和三角形。"},{"en":"Patterns have involved means the designs have included those elements as parts.","zh":"patterns have involved 指圖案把那些元素包括為組成部分。"},{"en":"A school logo may involve circles, lines, and letters in one design.","zh":"學校標誌可能在一個設計中包含圓圈、線條和字母。"},{"en":"When a pattern involves many elements, it becomes more difficult to describe simply.","zh":"當圖案包含許多元素，它就更難簡單描述。"},{"en":"The phrase introduces components within a design.","zh":"這個短語引入設計中的組件。"}],"source":"73 - Crop circles.pdf","sourcePage":5},{"front":"multiple circles","meaning":"多個圓圈","examples":[{"en":"Some patterns have involved multiple circles.","zh":"一些圖案包含多個圓圈。"},{"en":"Multiple circles means more than one circle.","zh":"multiple circles 指多於一個圓圈。"},{"en":"A teacher may draw multiple circles on the board to explain overlapping ideas.","zh":"老師可能在白板上畫多個圓圈，以解釋重疊概念。"},{"en":"When multiple circles connect or overlap, a design can become more complex.","zh":"當多個圓圈連接或重疊，設計會變得更複雜。"},{"en":"The phrase focuses on number and repetition.","zh":"這個短語重點是數量和重複。"}],"source":"73 - Crop circles.pdf","sourcePage":5},{"front":"bars, triangles, rings and spurs","meaning":"長條、三角形、環形和突出線條","examples":[{"en":"Crop circle patterns may include bars, triangles, rings and spurs.","zh":"麥田圈圖案可能包括長條、三角形、環形和突出線條。"},{"en":"Bars, triangles, rings and spurs are different geometric parts used in a pattern.","zh":"bars, triangles, rings and spurs 指圖案中使用的不同幾何部分。"},{"en":"A playground design may use bars, triangles, rings, and short projecting lines for decoration.","zh":"遊樂場設計可能使用長條、三角形、環形和短突出線條作裝飾。"},{"en":"Combining many shapes can make a design look mathematical and deliberate.","zh":"結合許多形狀可以令設計看似有數學性和刻意性。"},{"en":"The phrase lists specific visual elements.","zh":"這個短語列出具體視覺元素。"}],"source":"73 - Crop circles.pdf","sourcePage":5},{"front":"pictorial imagery","meaning":"圖像式圖案","examples":[{"en":"Pictorial imagery has also appeared in some crop circles.","zh":"一些麥田圈也出現了圖像式圖案。"},{"en":"Pictorial imagery means designs that look like pictures or represent visible objects.","zh":"pictorial imagery 指看似圖畫或代表可見物件的設計。"},{"en":"A poster uses pictorial imagery when it shows people, animals, or scenes instead of only words.","zh":"當海報展示人物、動物或場景而不只是文字，就是使用圖像式圖案。"},{"en":"When crop patterns contain imagery, viewers may search for symbolic meaning.","zh":"當作物圖案包含圖像，觀眾可能尋找象徵意義。"},{"en":"The phrase contrasts picture-like designs with simple geometric shapes.","zh":"這個短語把圖畫式設計與簡單幾何形狀作對比。"}],"source":"73 - Crop circles.pdf","sourcePage":5},{"front":"reliable eyewitnesses","meaning":"可靠目擊者","examples":[{"en":"Reliable eyewitnesses have reported unusual lights near crop circles.","zh":"可靠目擊者報告曾在麥田圈附近看見異常光芒。"},{"en":"Reliable eyewitnesses are people who directly saw an event and seem trustworthy.","zh":"reliable eyewitnesses 指親眼看見事件並看似可信的人。"},{"en":"Police may ask reliable eyewitnesses what happened during an accident.","zh":"警方可能詢問可靠目擊者意外發生時的情況。"},{"en":"Eyewitness reports can support a claim, but they still need careful checking.","zh":"目擊報告可以支持聲稱，但仍需要仔細查核。"},{"en":"The phrase focuses on direct observation from trusted people.","zh":"這個短語重點是可信人士的直接觀察。"}],"source":"73 - Crop circles.pdf","sourcePage":5},{"front":"unusual lights","meaning":"異常光芒","examples":[{"en":"Some eyewitnesses have reported seeing unusual lights.","zh":"一些目擊者報稱曾看見異常光芒。"},{"en":"Unusual lights are lights that look strange, unexpected, or difficult to explain.","zh":"unusual lights 指看起來奇怪、意外或難以解釋的光。"},{"en":"A security guard may report unusual lights moving behind a school at night.","zh":"保安員可能報告晚上學校後方有異常光芒移動。"},{"en":"Strange lights can make people suspect electrical activity, aircraft, or something mysterious.","zh":"奇怪光芒可以令人懷疑是電活動、飛機或神秘事物。"},{"en":"The phrase describes what people saw, not what caused it.","zh":"這個短語描述人們看見了甚麼，而不是其原因。"}],"source":"73 - Crop circles.pdf","sourcePage":5},{"front":"unidentifiable sounds","meaning":"無法辨認的聲音","examples":[{"en":"Some people reported hearing unidentifiable sounds.","zh":"一些人報稱聽到無法辨認的聲音。"},{"en":"Unidentifiable sounds are noises that people cannot recognise or explain.","zh":"unidentifiable sounds 指人們不能辨認或解釋的聲音。"},{"en":"A strange noise in a classroom ceiling may be unidentifiable until a worker checks it.","zh":"課室天花板中的奇怪聲音，在工人檢查前可能無法辨認。"},{"en":"Sounds that cannot be identified can increase fear or curiosity.","zh":"無法辨認的聲音可以增加恐懼或好奇。"},{"en":"The phrase focuses on uncertainty about a noise’s source.","zh":"這個短語重點是對聲音來源的不確定。"}],"source":"73 - Crop circles.pdf","sourcePage":6},{"front":"an early-morning walk","meaning":"清晨散步","examples":[{"en":"Witnesses heard strange sounds during an early-morning walk.","zh":"目擊者在清晨散步時聽到奇怪聲音。"},{"en":"An early-morning walk is a walk taken at the start of the day.","zh":"early-morning walk 指一天開始時進行的散步。"},{"en":"Some people take an early-morning walk before work to feel calm and awake.","zh":"有些人在上班前清晨散步，以感到平靜和清醒。"},{"en":"Quiet morning conditions may make unusual sounds easier to notice.","zh":"安靜的清晨環境可能令異常聲音更容易被注意。"},{"en":"The phrase gives the time and activity of the observation.","zh":"這個短語提供觀察發生的時間和活動。"}],"source":"73 - Crop circles.pdf","sourcePage":6},{"front":"in the countryside","meaning":"在郊外","examples":[{"en":"The crop circle appeared later that day in the countryside.","zh":"麥田圈在當天較後時間出現在郊外。"},{"en":"In the countryside means in rural areas outside towns and cities.","zh":"in the countryside 指在城鎮和城市以外的鄉郊地區。"},{"en":"A family may spend the weekend in the countryside to enjoy quiet fields and fresh air.","zh":"家庭可能週末到郊外享受安靜田野和新鮮空氣。"},{"en":"Crop circles are often linked with countryside settings because they appear in fields.","zh":"麥田圈常與郊外環境有關，因為它們出現在田地中。"},{"en":"The phrase contrasts rural land with urban places.","zh":"這個短語把鄉郊土地與城市地方作對比。"}],"source":"73 - Crop circles.pdf","sourcePage":6},{"front":"high-pitched noises","meaning":"高音調聲音","examples":[{"en":"High-pitched noises have been recorded at some crop circle sites.","zh":"一些麥田圈地點錄得高音調聲音。"},{"en":"High-pitched noises are sounds that are sharp and high in tone.","zh":"high-pitched noises 指尖銳且音調高的聲音。"},{"en":"A smoke alarm makes a high-pitched noise to catch people’s attention quickly.","zh":"煙霧警報器會發出高音調聲音，以快速吸引人注意。"},{"en":"Such noises can feel uncomfortable because the sound is sharp and hard to ignore.","zh":"這些聲音可能令人不舒服，因為聲音尖銳且難以忽視。"},{"en":"The phrase describes sound quality.","zh":"這個短語描述聲音特質。"}],"source":"73 - Crop circles.pdf","sourcePage":6},{"front":"warbling noises","meaning":"顫動的聲音","examples":[{"en":"Warbling noises have been recorded at the site of some crop circles.","zh":"一些麥田圈地點錄得顫動的聲音。"},{"en":"Warbling noises are sounds that rise and fall in a trembling or wavering way.","zh":"warbling noises 指以顫抖或搖動方式高低起伏的聲音。"},{"en":"A bird may make warbling noises outside a bedroom window in the morning.","zh":"清晨時，鳥可能在睡房窗外發出顫動叫聲。"},{"en":"A wavering sound can seem strange when it is heard in an empty field.","zh":"當這種搖動聲在空曠田野中被聽見，它可能顯得奇怪。"},{"en":"The phrase describes a changing, fluttering sound.","zh":"這個短語描述變化、顫動的聲音。"}],"source":"73 - Crop circles.pdf","sourcePage":6},{"front":"at the site of","meaning":"在……地點","examples":[{"en":"Strange noises were recorded at the site of some crop circles.","zh":"奇怪聲音在一些麥田圈地點被錄下。"},{"en":"At the site of something means at the exact place where it happened or exists.","zh":"at the site of something 指在某事發生或存在的確切地方。"},{"en":"Reporters gathered at the site of the accident to learn what happened.","zh":"記者聚集在意外地點，以了解發生了甚麼。"},{"en":"Studying evidence at the site helps researchers avoid relying only on rumours.","zh":"在現場研究證據幫助研究人員避免只依靠傳聞。"},{"en":"The phrase points to a specific location.","zh":"這個短語指出特定位置。"}],"source":"73 - Crop circles.pdf","sourcePage":6},{"front":"on several occasions","meaning":"有幾次","examples":[{"en":"On several occasions, a strange glow was seen in the sky.","zh":"有幾次，人們在天空中看見奇怪光芒。"},{"en":"On several occasions means several different times.","zh":"on several occasions 指在幾個不同時候。"},{"en":"On several occasions, students forgot to submit homework before the deadline.","zh":"有幾次，學生忘記在截止日期前交功課。"},{"en":"Repeated reports can make an observation seem more important than a single case.","zh":"重複報告可以令觀察比單一個案更重要。"},{"en":"The phrase stresses repetition.","zh":"這個短語強調重複。"}],"source":"73 - Crop circles.pdf","sourcePage":6},{"front":"a strange glow","meaning":"奇怪的光芒","examples":[{"en":"A strange glow has been seen over some crop circles.","zh":"一些麥田圈上方曾出現奇怪的光芒。"},{"en":"A strange glow is an unusual soft light that is difficult to explain.","zh":"strange glow 指難以解釋的異常柔和光。"},{"en":"A strange glow from a phone screen may be visible under a bedroom door at night.","zh":"晚上房門下方可能看見手機螢幕發出的奇怪光芒。"},{"en":"Unexplained light can make people connect an event with mystery or energy.","zh":"未解釋的光可以令人把事件與神秘或能量聯繫起來。"},{"en":"The phrase describes visible light, not a confirmed cause.","zh":"這個短語描述可見光，而不是已確認原因。"}],"source":"73 - Crop circles.pdf","sourcePage":6},{"front":"darker colouring","meaning":"較深的顏色","examples":[{"en":"A darker colouring has been seen in the sky over a crop circle.","zh":"麥田圈上空曾出現較深的顏色。"},{"en":"Darker colouring means a shade or colour that appears less bright than usual.","zh":"darker colouring 指比平常較不明亮的色調或顏色。"},{"en":"A wall may show darker colouring where rainwater has soaked into it.","zh":"牆壁被雨水滲入的地方可能顯示較深顏色。"},{"en":"Colour changes in the sky can make witnesses think something unusual is happening.","zh":"天空顏色變化可能令目擊者認為有異常事情發生。"},{"en":"The phrase describes visual appearance.","zh":"這個短語描述視覺外觀。"}],"source":"73 - Crop circles.pdf","sourcePage":6},{"front":"in the sky over","meaning":"在……上空","examples":[{"en":"A strange glow appeared in the sky over the crop circle.","zh":"奇怪光芒出現在麥田圈上空。"},{"en":"In the sky over a place means above that place in the air.","zh":"in the sky over a place 指在某地上方的天空中。"},{"en":"Fireworks appeared in the sky over the harbour during the festival.","zh":"節日期間，煙花出現在海港上空。"},{"en":"Something seen above a location may be linked to that place by witnesses.","zh":"在某地上方被看見的東西，可能被目擊者與該地聯繫起來。"},{"en":"The phrase describes position in the air.","zh":"這個短語描述空中的位置。"}],"source":"73 - Crop circles.pdf","sourcePage":6},{"front":"in more than one instance","meaning":"不止一次","examples":[{"en":"In more than one instance, small planes lost electrical power.","zh":"不止一次，小型飛機失去電力。"},{"en":"In more than one instance means this happened in at least two cases.","zh":"in more than one instance 指至少在兩個個案中發生。"},{"en":"In more than one instance, students reported the same error in the online homework system.","zh":"不止一次，學生報告網上功課系統出現同一錯誤。"},{"en":"When an event happens more than once, people may look for a pattern.","zh":"當事件發生多於一次，人們可能尋找模式。"},{"en":"The phrase stresses repeated cases, not a single accident.","zh":"這個短語強調重複個案，而不是單一意外。"}],"source":"73 - Crop circles.pdf","sourcePage":6},{"front":"electrical power","meaning":"電力","examples":[{"en":"The electrical power of small planes was cut off abruptly.","zh":"小型飛機的電力突然中斷。"},{"en":"Electrical power is the electricity that runs lights, instruments, machines, or systems.","zh":"electrical power 指運行燈光、儀器、機器或系統的電。"},{"en":"A classroom loses electrical power when the lights, fans, and computers suddenly turn off.","zh":"當燈、風扇和電腦突然關掉，課室就失去電力。"},{"en":"Losing electrical power in a plane can be serious because instruments may stop working.","zh":"飛機失去電力可能很嚴重，因為儀器可能停止運作。"},{"en":"The phrase refers to electricity supply.","zh":"這個短語指電力供應。"}],"source":"73 - Crop circles.pdf","sourcePage":7},{"front":"flying overhead","meaning":"在上空飛過","examples":[{"en":"Small planes flying overhead lost electrical power.","zh":"在上空飛過的小型飛機失去電力。"},{"en":"Flying overhead means flying above a place or person.","zh":"flying overhead 指在某地或某人上方飛行。"},{"en":"Students may look up when a helicopter is flying overhead during sports day.","zh":"運動會期間，如果直升機在上空飛過，學生可能抬頭看。"},{"en":"If aircraft overhead experience problems, witnesses may connect the problem with what lies below.","zh":"如果上空飛機出現問題，目擊者可能把問題與下方事物聯繫起來。"},{"en":"The phrase gives the position of the aircraft.","zh":"這個短語提供飛機位置。"}],"source":"73 - Crop circles.pdf","sourcePage":7},{"front":"cut off abruptly","meaning":"突然中斷","examples":[{"en":"The electrical power of small planes was cut off abruptly.","zh":"小型飛機的電力突然中斷。"},{"en":"Cut off abruptly means stopped suddenly and unexpectedly.","zh":"cut off abruptly 指突然且意外地停止。"},{"en":"A video lesson may be cut off abruptly if the internet connection fails.","zh":"如果網絡連接失敗，網上課堂影片可能突然中斷。"},{"en":"Sudden loss of power can create danger because people have little time to react.","zh":"突然失去電力可以造成危險，因為人們幾乎沒有時間反應。"},{"en":"The phrase stresses sudden interruption.","zh":"這個短語強調突然中斷。"}],"source":"73 - Crop circles.pdf","sourcePage":7},{"front":"causative forces","meaning":"成因力量；造成現象的力量","examples":[{"en":"The causative forces do not seem to harm animals.","zh":"造成現象的力量似乎不會傷害動物。"},{"en":"Causative forces are the forces or causes believed to produce an effect.","zh":"causative forces 指被認為產生某效果的力量或原因。"},{"en":"Scientists may study wind, water, and pressure as causative forces behind erosion.","zh":"科學家可能研究風、水和壓力作為侵蝕背後的成因力量。"},{"en":"Identifying causative forces helps explain why a pattern or event happened.","zh":"找出成因力量有助解釋圖案或事件為何發生。"},{"en":"The phrase is formal and focuses on cause.","zh":"這個短語較正式，重點是原因。"}],"source":"73 - Crop circles.pdf","sourcePage":7},{"front":"as far as we can tell","meaning":"就我們所知","examples":[{"en":"As far as we can tell, the forces do not harm animals.","zh":"就我們所知，這些力量不會傷害動物。"},{"en":"As far as we can tell means based on what we currently know or can observe.","zh":"as far as we can tell 指根據我們目前所知或能觀察到的情況。"},{"en":"As far as we can tell, the new timetable is helping students arrive earlier.","zh":"就我們所知，新時間表正在幫助學生更早到達。"},{"en":"The phrase leaves room for uncertainty because more evidence may appear later.","zh":"這個短語保留不確定性，因為日後可能出現更多證據。"},{"en":"It is useful when making a cautious claim.","zh":"它適合用於作出謹慎聲稱。"}],"source":"73 - Crop circles.pdf","sourcePage":7},{"front":"wild creatures","meaning":"野生動物","examples":[{"en":"Wild creatures tend to avoid crop circles.","zh":"野生動物往往避開麥田圈。"},{"en":"Wild creatures are animals that live naturally outside human control.","zh":"wild creatures 指自然生活、不受人類控制的動物。"},{"en":"Deer, foxes, birds, and insects can be wild creatures in the countryside.","zh":"鹿、狐狸、鳥和昆蟲都可以是郊外的野生動物。"},{"en":"Animal behaviour can give clues about changes in an environment.","zh":"動物行為可以提供環境變化的線索。"},{"en":"The phrase refers to wildlife rather than pets or farm animals.","zh":"這個短語指野生生物，而不是寵物或農場動物。"}],"source":"73 - Crop circles.pdf","sourcePage":7},{"front":"tend to avoid","meaning":"往往避開","examples":[{"en":"Wild creatures tend to avoid the circles.","zh":"野生動物往往避開這些圓圈。"},{"en":"Tend to avoid means usually stay away from something.","zh":"tend to avoid 指通常避開某事物。"},{"en":"Students tend to avoid difficult questions when they have not revised enough.","zh":"如果學生溫習不足，他們往往避開困難問題。"},{"en":"If animals usually avoid an area, observers may wonder what they sense there.","zh":"如果動物通常避開某區域，觀察者可能想知道牠們感受到甚麼。"},{"en":"The phrase describes a general pattern, not a fixed rule.","zh":"這個短語描述一般模式，而不是固定規則。"}],"source":"73 - Crop circles.pdf","sourcePage":7},{"front":"flocks of birds","meaning":"鳥群","examples":[{"en":"Flocks of birds have been seen to split apart.","zh":"有人看見鳥群分開。"},{"en":"Flocks of birds are groups of birds flying or moving together.","zh":"flocks of birds 指一起飛行或移動的一群鳥。"},{"en":"A flock of birds may gather near a school field after students leave crumbs behind.","zh":"學生留下麵包屑後，一群鳥可能聚集在學校操場附近。"},{"en":"When a flock suddenly separates, witnesses may think the birds are avoiding something.","zh":"當鳥群突然分散，目擊者可能認為鳥在避開某物。"},{"en":"The phrase describes birds as a group.","zh":"這個短語把鳥描述成一個群體。"}],"source":"73 - Crop circles.pdf","sourcePage":7},{"front":"split apart","meaning":"分開","examples":[{"en":"Flocks of birds split apart near crop circle formations.","zh":"鳥群在麥田圈圖案附近分開。"},{"en":"Split apart means separate into different parts or directions.","zh":"split apart 指分成不同部分或方向。"},{"en":"A group of students may split apart after school when some go home and others join clubs.","zh":"放學後，一群學生可能分開，有些回家，有些參加學會。"},{"en":"If birds split apart near one area, people may think they are avoiding it.","zh":"如果鳥在某區域附近分開，人們可能認為牠們在避開該區。"},{"en":"The phrase describes separation from a group pattern.","zh":"這個短語描述從群體模式中分離。"}],"source":"73 - Crop circles.pdf","sourcePage":7},{"front":"fly around the perimeter","meaning":"繞着邊緣飛行","examples":[{"en":"Birds fly around the perimeter rather than over the formation.","zh":"鳥繞着邊緣飛行，而不是飛越圖案。"},{"en":"To fly around the perimeter means to move through the air around the outer edge of an area.","zh":"fly around the perimeter 指在空中沿着某區域外邊界移動。"},{"en":"A drone may fly around the perimeter of a school field to record the whole boundary.","zh":"無人機可能繞着學校操場邊緣飛行，以拍下整個邊界。"},{"en":"Moving around the edge instead of crossing the centre can suggest avoidance.","zh":"繞着邊緣而不穿過中心，可以暗示避開。"},{"en":"The phrase describes movement around a border.","zh":"這個短語描述圍繞邊界移動。"}],"source":"73 - Crop circles.pdf","sourcePage":7},{"front":"rather than","meaning":"而不是","examples":[{"en":"Birds fly around the perimeter rather than go directly over the crop circle.","zh":"鳥繞着邊緣飛行，而不是直接飛越麥田圈。"},{"en":"Rather than means instead of and shows a clear contrast between two choices.","zh":"rather than 指而不是，清楚對比兩個選擇。"},{"en":"Students should ask for help rather than silently copy answers.","zh":"學生應該求助，而不是默默抄答案。"},{"en":"The phrase helps show what is chosen and what is avoided.","zh":"這個短語幫助顯示選擇了甚麼和避開了甚麼。"},{"en":"It is useful when comparing two possible actions.","zh":"它適合比較兩個可能行動。"}],"source":"73 - Crop circles.pdf","sourcePage":7},{"front":"go directly over","meaning":"直接飛越","examples":[{"en":"Birds avoid going directly over a crop circle formation.","zh":"鳥避免直接飛越麥田圈圖案。"},{"en":"To go directly over something means to pass above it in a straight or central path.","zh":"go directly over something 指以直線或穿過中心的路徑從某物上方經過。"},{"en":"A plane may go directly over a city when following its flight route.","zh":"飛機按航線飛行時，可能直接飛越城市。"},{"en":"Avoiding direct movement over a place may suggest caution or discomfort.","zh":"避免直接越過某地可能暗示謹慎或不安。"},{"en":"The phrase focuses on movement above a location.","zh":"這個短語重點是位於某地上方的移動。"}],"source":"73 - Crop circles.pdf","sourcePage":8},{"front":"crop circle formation","meaning":"麥田圈圖案；麥田圈形成物","examples":[{"en":"Birds often avoid flying over a crop circle formation.","zh":"鳥常避免飛越麥田圈圖案。"},{"en":"A crop circle formation is the pattern or arrangement created in a field of crops.","zh":"crop circle formation 指在農作物田中形成的圖案或排列。"},{"en":"A photographer may use a drone to capture the full crop circle formation from above.","zh":"攝影師可能使用無人機從上方拍攝完整麥田圈圖案。"},{"en":"The formation becomes visible when some plants are flattened while others remain upright.","zh":"當一些植物被壓平而另一些保持直立，圖案就變得可見。"},{"en":"The phrase refers to the whole crop pattern, not just one ring.","zh":"這個短語指整個作物圖案，而不只是單一圓環。"}],"source":"73 - Crop circles.pdf","sourcePage":8},{"front":"a great deal of time","meaning":"大量時間","examples":[{"en":"Researchers have spent a great deal of time investigating crop circles.","zh":"研究人員花了大量時間調查麥田圈。"},{"en":"A great deal of time means a large amount of time.","zh":"a great deal of time 指很多時間。"},{"en":"A student may spend a great deal of time preparing for a speaking exam.","zh":"學生可能花大量時間準備口語考試。"},{"en":"Complex mysteries require time because evidence must be collected, checked, and compared.","zh":"複雜謎團需要時間，因為證據必須被收集、查核和比較。"},{"en":"The phrase stresses serious effort over a long period.","zh":"這個短語強調長時間認真努力。"}],"source":"73 - Crop circles.pdf","sourcePage":8},{"front":"investigating different aspects of","meaning":"研究……的不同方面","examples":[{"en":"Researchers are investigating different aspects of crop circles.","zh":"研究人員正在研究麥田圈的不同方面。"},{"en":"Investigating different aspects of something means studying several parts, features, or questions about it.","zh":"investigating different aspects of something 指研究某事的幾個部分、特徵或問題。"},{"en":"A school may investigate different aspects of student stress, such as sleep, homework, and exams.","zh":"學校可能研究學生壓力的不同方面，例如睡眠、功課和考試。"},{"en":"Studying only one aspect can give an incomplete explanation.","zh":"只研究一個方面可能帶來不完整解釋。"},{"en":"The phrase shows a broad research approach.","zh":"這個短語顯示廣泛研究方法。"}],"source":"73 - Crop circles.pdf","sourcePage":8},{"front":"detect traces of","meaning":"偵測……的痕跡","examples":[{"en":"Researchers try to detect traces of human involvement.","zh":"研究人員嘗試偵測人為參與的痕跡。"},{"en":"To detect traces of something means to find small signs or evidence of it.","zh":"detect traces of something 指找出某事的小跡象或證據。"},{"en":"Police may detect traces of paint on a car after a road accident.","zh":"交通意外後，警方可能在汽車上偵測到油漆痕跡。"},{"en":"Small traces can help investigators decide whether people were involved.","zh":"細小痕跡可以幫助調查者判斷是否有人參與。"},{"en":"The phrase focuses on finding subtle evidence.","zh":"這個短語重點是尋找細微證據。"}],"source":"73 - Crop circles.pdf","sourcePage":8},{"front":"human involvement","meaning":"人為參與","examples":[{"en":"Researchers look for signs of human involvement in circle-making.","zh":"研究人員尋找製造圓圈中有人為參與的跡象。"},{"en":"Human involvement means participation or action by people.","zh":"human involvement 指由人參與或行動。"},{"en":"A broken window may show human involvement if fingerprints are found nearby.","zh":"如果附近找到指紋，破窗可能顯示有人為參與。"},{"en":"If human involvement is proven, a mysterious event may become easier to explain.","zh":"如果人為參與被證明，神秘事件可能變得較容易解釋。"},{"en":"The phrase contrasts human action with natural or unknown causes.","zh":"這個短語把人類行動與自然或未知原因作對比。"}],"source":"73 - Crop circles.pdf","sourcePage":8},{"front":"circle-making","meaning":"製造圓圈","examples":[{"en":"Researchers investigate possible human involvement in circle-making.","zh":"研究人員調查製造圓圈中可能存在的人為參與。"},{"en":"Circle-making means the act or process of creating crop circles.","zh":"circle-making 指創造麥田圈的行動或過程。"},{"en":"A group of artists may practise circle-making on paper before creating a large outdoor design.","zh":"一群藝術家可能先在紙上練習製造圓圈，再創作大型戶外設計。"},{"en":"Understanding the process can help researchers judge whether humans could have made the pattern.","zh":"理解過程可以幫助研究人員判斷人類是否能製造該圖案。"},{"en":"The phrase focuses on the creation of the circles.","zh":"這個短語重點是圓圈的創造。"}],"source":"73 - Crop circles.pdf","sourcePage":8},{"front":"test the area for","meaning":"檢測該區是否有……","examples":[{"en":"Researchers test the area for geophysical anomalies.","zh":"研究人員檢測該區是否有地球物理異常。"},{"en":"To test the area for something means to examine a place to see whether that thing is present.","zh":"test the area for something 指檢查某地是否存在某物。"},{"en":"Health workers may test an area for polluted water after residents become sick.","zh":"居民生病後，衛生人員可能檢測該區是否有受污染食水。"},{"en":"Testing a site can provide evidence instead of relying only on eyewitness reports.","zh":"檢測地點可以提供證據，而不是只依靠目擊報告。"},{"en":"The phrase describes scientific checking of a location.","zh":"這個短語描述對地點作科學檢查。"}],"source":"73 - Crop circles.pdf","sourcePage":8},{"front":"geophysical anomalies","meaning":"地球物理異常","examples":[{"en":"Researchers test crop circle areas for geophysical anomalies.","zh":"研究人員檢測麥田圈地區是否有地球物理異常。"},{"en":"Geophysical anomalies are unusual features in the physical properties of the ground or earth.","zh":"geophysical anomalies 指地面或地球物理特性中的異常特徵。"},{"en":"Scientists may find geophysical anomalies when soil magnetism or radiation differs from normal.","zh":"當土壤磁性或輻射與正常不同，科學家可能發現地球物理異常。"},{"en":"Such anomalies can suggest that something unusual affected the land.","zh":"這些異常可能暗示土地曾受某種不尋常因素影響。"},{"en":"The phrase is scientific and refers to abnormal earth-related measurements.","zh":"這個短語屬科學用語，指與地球相關量度的異常。"}],"source":"73 - Crop circles.pdf","sourcePage":8},{"front":"analyse grain samples","meaning":"分析穀物樣本","examples":[{"en":"Scientists analyse grain samples from within and outside the circles.","zh":"科學家分析圓圈內外的穀物樣本。"},{"en":"To analyse grain samples means to examine pieces of crop material carefully for evidence.","zh":"analyse grain samples 指仔細檢查作物材料樣本以尋找證據。"},{"en":"A laboratory may analyse food samples to check whether they contain harmful chemicals.","zh":"實驗室可能分析食物樣本，以檢查是否含有有害化學物。"},{"en":"Comparing samples can reveal differences that are not visible at first sight.","zh":"比較樣本可以揭示肉眼起初看不見的差異。"},{"en":"The phrase describes scientific study of crop material.","zh":"這個短語描述對作物材料的科學研究。"}],"source":"73 - Crop circles.pdf","sourcePage":8},{"front":"from within and outside","meaning":"從……內外","examples":[{"en":"Researchers compare grain from within and outside the circles.","zh":"研究人員比較來自圓圈內外的穀物。"},{"en":"From within and outside means taken from both inside an area and beyond its boundary.","zh":"from within and outside 指從某區域內部和邊界外部取得。"},{"en":"A doctor may compare air samples from within and outside a hospital room to check cleanliness.","zh":"醫生可能比較病房內外的空氣樣本，以檢查清潔度。"},{"en":"Comparing inside and outside samples helps show whether the circle area is different.","zh":"比較內外樣本有助顯示圓圈區域是否不同。"},{"en":"The phrase sets up a controlled comparison.","zh":"這個短語建立受控比較。"}],"source":"73 - Crop circles.pdf","sourcePage":8},{"front":"searching for differences","meaning":"尋找差異","examples":[{"en":"Researchers analyse the grain, searching for differences.","zh":"研究人員分析穀物，尋找差異。"},{"en":"Searching for differences means looking carefully for ways in which things are not the same.","zh":"searching for differences 指仔細尋找事物之間不相同的地方。"},{"en":"A teacher may compare two essays, searching for differences in structure and vocabulary.","zh":"老師可能比較兩篇作文，尋找結構和詞彙上的差異。"},{"en":"Finding differences can help explain whether one group was affected by a special condition.","zh":"找出差異可以幫助解釋某一組是否受特殊條件影響。"},{"en":"The phrase describes careful comparison.","zh":"這個短語描述仔細比較。"}],"source":"73 - Crop circles.pdf","sourcePage":9},{"front":"grain samples","meaning":"穀物樣本","examples":[{"en":"Dr. Levengood analysed many grain samples.","zh":"Levengood 博士分析了許多穀物樣本。"},{"en":"Grain samples are small amounts of crop material taken for testing.","zh":"grain samples 指取來測試的小量作物材料。"},{"en":"Farmers may send grain samples to a laboratory to check quality before selling a harvest.","zh":"農夫可能在出售收成前把穀物樣本送到實驗室檢查質素。"},{"en":"Samples allow scientists to study a whole field without testing every plant.","zh":"樣本讓科學家不用測試每株植物，也能研究整片田。"},{"en":"The phrase refers to tested pieces of grain crops.","zh":"這個短語指被測試的穀物作物材料。"}],"source":"73 - Crop circles.pdf","sourcePage":9},{"front":"confirmed time after time","meaning":"一次又一次確認","examples":[{"en":"Dr. Levengood confirmed significant changes time after time.","zh":"Levengood 博士一次又一次確認顯著變化。"},{"en":"Confirmed time after time means proved or found the same result repeatedly.","zh":"confirmed time after time 指反覆證明或發現相同結果。"},{"en":"A teacher may confirm time after time that practice improves spelling.","zh":"老師可能一次又一次確認練習能改善串字。"},{"en":"Repeated confirmation makes a result seem more reliable than one isolated finding.","zh":"反覆確認令結果比單一孤立發現更可靠。"},{"en":"The phrase stresses repetition and consistency.","zh":"這個短語強調重複和一致性。"}],"source":"73 - Crop circles.pdf","sourcePage":9},{"front":"significant changes","meaning":"顯著變化","examples":[{"en":"Researchers found significant changes at the cellular level.","zh":"研究人員在細胞層面發現顯著變化。"},{"en":"Significant changes are important differences large enough to matter.","zh":"significant changes 指重要且值得關注的差異。"},{"en":"A student’s writing may show significant changes after months of regular feedback.","zh":"經過數月定期回饋後，學生寫作可能顯示顯著變化。"},{"en":"If plant samples show significant changes, researchers may suspect unusual conditions affected them.","zh":"如果植物樣本顯示顯著變化，研究人員可能懷疑它們受不尋常條件影響。"},{"en":"The phrase focuses on meaningful change, not tiny random variation.","zh":"這個短語重點是有意義變化，而不是微小隨機差異。"}],"source":"73 - Crop circles.pdf","sourcePage":9},{"front":"at the cellular level","meaning":"在細胞層面","examples":[{"en":"Crop circle plants showed changes at the cellular level.","zh":"麥田圈植物在細胞層面顯示變化。"},{"en":"At the cellular level means in the cells that make up living tissue.","zh":"at the cellular level 指在構成生物組織的細胞中。"},{"en":"Doctors study illness at the cellular level to understand how the body is affected.","zh":"醫生在細胞層面研究疾病，以了解身體如何受影響。"},{"en":"Changes at this level may not be visible without laboratory tools.","zh":"這一層面的變化可能沒有實驗室工具就看不見。"},{"en":"The phrase points to microscopic biological detail.","zh":"這個短語指微觀生物細節。"}],"source":"73 - Crop circles.pdf","sourcePage":9},{"front":"elongated cells","meaning":"拉長的細胞","examples":[{"en":"The plants from the circles had elongated cells.","zh":"來自圓圈的植物有拉長的細胞。"},{"en":"Elongated cells are cells that have become longer or stretched in shape.","zh":"elongated cells 指形狀變長或被拉伸的細胞。"},{"en":"A science teacher may show elongated cells under a microscope during a plant lesson.","zh":"科學老師可能在植物課中用顯微鏡展示拉長細胞。"},{"en":"Abnormally stretched cells can suggest that growth or pressure changed the plant tissue.","zh":"異常拉長的細胞可以暗示生長或壓力改變了植物組織。"},{"en":"The phrase describes cell shape.","zh":"這個短語描述細胞形狀。"}],"source":"73 - Crop circles.pdf","sourcePage":9},{"front":"blown-out growth nodes","meaning":"膨脹爆裂的生長節點","examples":[{"en":"Some crop circle plants had blown-out growth nodes.","zh":"一些麥田圈植物有膨脹爆裂的生長節點。"},{"en":"Blown-out growth nodes are plant joints or growth points that appear swollen, burst, or damaged.","zh":"blown-out growth nodes 指看似腫脹、爆裂或受損的植物節點或生長點。"},{"en":"A plant stem has nodes where leaves or branches can grow.","zh":"植物莖上有節點，葉或枝可以從那裡生長。"},{"en":"Damaged growth nodes may suggest heat, pressure, or unusual internal stress.","zh":"受損生長節點可能暗示熱力、壓力或異常內部應力。"},{"en":"The phrase describes a specific physical change in plants.","zh":"這個短語描述植物中的特定物理變化。"}],"source":"73 - Crop circles.pdf","sourcePage":9},{"front":"accelerated growth rates","meaning":"加快的生長速度","examples":[{"en":"Seeds from the circle plants often showed accelerated growth rates.","zh":"來自圓圈植物的種子常顯示加快的生長速度。"},{"en":"Accelerated growth rates are faster-than-normal speeds of growth.","zh":"accelerated growth rates 指比正常更快的生長速度。"},{"en":"Plants may show accelerated growth rates when they receive enough water, light, and nutrients.","zh":"當植物得到足夠水、光和養分，可能顯示加快的生長速度。"},{"en":"If seeds from one area grow faster than others, researchers may compare their conditions.","zh":"如果某一區域的種子比其他種子長得快，研究人員可能比較其條件。"},{"en":"The phrase describes increased speed of development.","zh":"這個短語描述發展速度增加。"}],"source":"73 - Crop circles.pdf","sourcePage":9},{"front":"when they are sown","meaning":"當它們被播種時","examples":[{"en":"Seeds may show accelerated growth rates when they are sown.","zh":"種子被播種時可能顯示加快的生長速度。"},{"en":"When they are sown means when seeds are planted in soil.","zh":"when they are sown 指種子被種入泥土時。"},{"en":"Farmers water seeds after they are sown so they can begin to grow.","zh":"農夫在種子播下後澆水，好讓它們開始生長。"},{"en":"Growth can only be observed after seeds are planted and start developing.","zh":"生長只有在種子被種下並開始發育後才能被觀察。"},{"en":"The phrase refers to the planting stage.","zh":"這個短語指播種階段。"}],"source":"73 - Crop circles.pdf","sourcePage":9},{"front":"different-looking plants","meaning":"外觀不同的植物","examples":[{"en":"In some cases, different-looking plants resulted.","zh":"在一些情況下，結果出現外觀不同的植物。"},{"en":"Different-looking plants are plants that grow with an appearance unlike the normal or expected one.","zh":"different-looking plants 指外觀不同於正常或預期樣子的植物。"},{"en":"A gardener may notice different-looking plants if some leaves are unusually pale or long.","zh":"如果一些葉子異常蒼白或很長，園丁可能注意到外觀不同的植物。"},{"en":"Unusual growth can make scientists ask whether the seeds were affected before planting.","zh":"異常生長會令科學家詢問種子在播種前是否受影響。"},{"en":"The phrase focuses on visible differences in appearance.","zh":"這個短語重點是外觀上的可見差異。"}],"source":"73 - Crop circles.pdf","sourcePage":9},{"front":"in many instances","meaning":"在許多情況下","examples":[{"en":"In many instances, a vortex-like energy seems to affect the plants.","zh":"在許多情況下，類似漩渦的能量似乎影響植物。"},{"en":"In many instances means in many cases or examples.","zh":"in many instances 指在許多個案或例子中。"},{"en":"In many instances, students improve faster when feedback is specific.","zh":"在許多情況下，當回饋具體，學生進步更快。"},{"en":"Repeated cases make a pattern seem more important than a single example.","zh":"重複個案令模式看起來比單一例子更重要。"},{"en":"The phrase introduces a general observation based on many cases.","zh":"這個短語引入基於多個個案的一般觀察。"}],"source":"73 - Crop circles.pdf","sourcePage":9},{"front":"vortex-like energy","meaning":"類似漩渦的能量","examples":[{"en":"A vortex-like energy may cause the plants to swirl down.","zh":"類似漩渦的能量可能令植物旋轉倒下。"},{"en":"Vortex-like energy means a force or movement that seems to rotate like a whirlpool or tornado.","zh":"vortex-like energy 指看似像漩渦或龍捲風般旋轉的力量或運動。"},{"en":"Water going down a drain can show a simple vortex-like movement.","zh":"水流進排水口時，可以顯示簡單的類似漩渦運動。"},{"en":"If plants fall in a swirling pattern, people may imagine a rotating force affected them.","zh":"如果植物以旋轉圖案倒下，人們可能想像有旋轉力量影響它們。"},{"en":"The phrase describes the supposed form of energy, not a proven source.","zh":"這個短語描述假設中的能量形式，而不是已證實來源。"}],"source":"73 - Crop circles.pdf","sourcePage":10},{"front":"swirl down","meaning":"旋轉倒下","examples":[{"en":"The plants appear to swirl down into the crop circle pattern.","zh":"植物看似旋轉倒下，形成麥田圈圖案。"},{"en":"To swirl down means to fall or move downward in a twisting circular motion.","zh":"swirl down 指以扭轉圓形動作向下落或移動。"},{"en":"Leaves may swirl down from a tree when wind turns them in the air.","zh":"風吹動時，樹葉可能從樹上旋轉飄下。"},{"en":"A swirling fall can create a pattern that looks different from simple flattening.","zh":"旋轉倒下可以形成不同於簡單壓平的圖案。"},{"en":"The phrase combines rotation with downward movement.","zh":"這個短語結合旋轉和向下移動。"}],"source":"73 - Crop circles.pdf","sourcePage":10},{"front":"flatten the design into the land","meaning":"把圖案壓進土地中","examples":[{"en":"The energy may flatten the design into the land.","zh":"這種能量可能把圖案壓進土地中。"},{"en":"To flatten the design into the land means to press crops or material down so a visible pattern appears on the ground.","zh":"flatten the design into the land 指把作物或材料壓下，使地面上出現可見圖案。"},{"en":"A heavy object can flatten a shape into sand if it presses down evenly.","zh":"如果重物均勻壓下，它可以把形狀壓進沙中。"},{"en":"Flattening crops creates contrast between lowered plants and upright plants.","zh":"壓平作物會在倒伏植物和直立植物之間形成對比。"},{"en":"The phrase describes how a pattern becomes marked on the field.","zh":"這個短語描述圖案如何被標記在田地上。"}],"source":"73 - Crop circles.pdf","sourcePage":10},{"front":"inhibit growth","meaning":"抑制生長","examples":[{"en":"This energy does not generally inhibit the plants’ growth.","zh":"這種能量通常不會抑制植物生長。"},{"en":"To inhibit growth means to slow down, reduce, or stop something from growing.","zh":"inhibit growth 指減慢、減少或停止某物生長。"},{"en":"Lack of sunlight can inhibit growth in indoor plants.","zh":"缺乏陽光可以抑制室內植物生長。"},{"en":"If crop circle plants continue growing, the cause may not completely damage them.","zh":"如果麥田圈植物繼續生長，成因可能沒有完全損害它們。"},{"en":"The phrase describes a negative effect on development.","zh":"這個短語描述對發育的負面影響。"}],"source":"73 - Crop circles.pdf","sourcePage":10},{"front":"respond normally to","meaning":"對……作出正常反應","examples":[{"en":"The plants continue to respond normally to the sun.","zh":"植物繼續對陽光作出正常反應。"},{"en":"To respond normally to something means to react in the usual expected way.","zh":"respond normally to something 指以通常預期方式作出反應。"},{"en":"Healthy plants respond normally to sunlight by growing towards it.","zh":"健康植物會透過向陽生長來對陽光作出正常反應。"},{"en":"Normal response suggests the plants are still alive and functioning.","zh":"正常反應暗示植物仍然存活並運作。"},{"en":"The phrase focuses on typical reaction.","zh":"這個短語重點是典型反應。"}],"source":"73 - Crop circles.pdf","sourcePage":10},{"front":"rise upright","meaning":"重新直立起來","examples":[{"en":"The plants rise upright over several days.","zh":"植物經過數天重新直立起來。"},{"en":"To rise upright means to lift back into a standing position.","zh":"rise upright 指重新抬起並站直。"},{"en":"Grass may rise upright again after children stop sitting on it.","zh":"孩子停止坐在草地上後，草可能重新直立起來。"},{"en":"If plants rise upright, the damage may be temporary rather than permanent.","zh":"如果植物重新直立，損害可能是暫時而非永久。"},{"en":"The phrase describes recovery of position.","zh":"這個短語描述位置恢復。"}],"source":"73 - Crop circles.pdf","sourcePage":10},{"front":"over several days","meaning":"經過數天","examples":[{"en":"The plants rise upright over several days.","zh":"植物經過數天重新直立。"},{"en":"Over several days means during a period of a few days, not immediately.","zh":"over several days 指在幾天期間，而不是立即。"},{"en":"A student may feel better over several days after resting and drinking enough water.","zh":"學生休息和喝足夠水後，可能經過數天感覺好轉。"},{"en":"Gradual change over several days can show recovery or continuing development.","zh":"經過數天的逐漸變化可以顯示恢復或持續發展。"},{"en":"The phrase describes a short process through time.","zh":"這個短語描述短時間內的過程。"}],"source":"73 - Crop circles.pdf","sourcePage":10},{"front":"following the appearance of","meaning":"在……出現之後","examples":[{"en":"The plants rise upright following the appearance of the circle.","zh":"在圓圈出現之後，植物重新直立起來。"},{"en":"Following the appearance of something means after that thing has appeared.","zh":"following the appearance of something 指在某事物出現之後。"},{"en":"Following the appearance of cracks in a wall, a building manager may call an engineer.","zh":"牆壁出現裂縫之後，大廈管理員可能召喚工程師。"},{"en":"The phrase links one event to what happens afterward.","zh":"這個短語把一件事件與之後發生的事連起來。"},{"en":"It shows sequence, not necessarily cause.","zh":"它顯示先後次序，不一定表示原因。"}],"source":"73 - Crop circles.pdf","sourcePage":10},{"front":"traces of","meaning":"……的痕跡","examples":[{"en":"Michael Chorost found traces of short-lived radionuclides.","zh":"Michael Chorost 發現短壽命放射性核素的痕跡。"},{"en":"Traces of something are very small amounts or signs of it.","zh":"traces of something 指非常小量或跡象。"},{"en":"A doctor may find traces of an infection in a blood test.","zh":"醫生可能在驗血中發現感染痕跡。"},{"en":"Small traces can be important because they may point to a hidden process.","zh":"細小痕跡可能很重要，因為它們可能指向隱藏過程。"},{"en":"The phrase focuses on tiny evidence.","zh":"這個短語重點是微小證據。"}],"source":"73 - Crop circles.pdf","sourcePage":10},{"front":"short-lived radionuclides","meaning":"短壽命放射性核素","examples":[{"en":"Short-lived radionuclides were found in the top layer of soil.","zh":"短壽命放射性核素在表層土壤中被發現。"},{"en":"Short-lived radionuclides are radioactive atoms that decay or disappear relatively quickly.","zh":"short-lived radionuclides 指會相對快速衰變或消失的放射性原子。"},{"en":"Scientists measure radionuclides carefully because they can reveal radiation-related activity.","zh":"科學家仔細量度放射性核素，因為它們可以揭示與輻射相關的活動。"},{"en":"If short-lived radionuclides are found, timing matters because they may not remain for long.","zh":"如果發現短壽命放射性核素，時間很重要，因為它們可能不會存在很久。"},{"en":"The phrase is scientific and refers to temporary radioactive material.","zh":"這個短語屬科學用語，指暫時存在的放射性物質。"}],"source":"73 - Crop circles.pdf","sourcePage":10},{"front":"the top layer of soil","meaning":"表層土壤","examples":[{"en":"Traces were found in the top layer of soil.","zh":"痕跡在表層土壤中被發現。"},{"en":"The top layer of soil is the uppermost part of the ground where plants often grow.","zh":"top layer of soil 指地面最上方、植物常在其中生長的部分。"},{"en":"Gardeners add compost to the top layer of soil to help vegetables grow.","zh":"園丁把堆肥加入表層土壤，以幫助蔬菜生長。"},{"en":"Changes in the top layer can show what recently affected the surface of the land.","zh":"表層變化可以顯示近期有甚麼影響了土地表面。"},{"en":"The phrase refers to the soil nearest the surface.","zh":"這個短語指最接近表面的土壤。"}],"source":"73 - Crop circles.pdf","sourcePage":10},{"front":"crop circle formations","meaning":"麥田圈圖案","examples":[{"en":"Some crop circle formations contained unusual soil traces.","zh":"一些麥田圈圖案含有異常土壤痕跡。"},{"en":"Crop circle formations are the complete patterns or arrangements created in crop fields.","zh":"crop circle formations 指在農作物田中形成的完整圖案或排列。"},{"en":"A researcher may photograph crop circle formations from above to see their full shape.","zh":"研究人員可能從上方拍攝麥田圈圖案，以看見其完整形狀。"},{"en":"Studying the whole formation helps compare plant, soil, and geometric features.","zh":"研究整個圖案有助比較植物、土壤和幾何特徵。"},{"en":"The phrase refers to the pattern as a complete structure.","zh":"這個短語指作為完整結構的圖案。"}],"source":"73 - Crop circles.pdf","sourcePage":11},{"front":"a government laboratory","meaning":"政府實驗室","examples":[{"en":"A British government laboratory found changes in the soil.","zh":"一間英國政府實驗室發現土壤變化。"},{"en":"A government laboratory is an official research facility run or supported by the government.","zh":"government laboratory 指由政府營運或支持的官方研究設施。"},{"en":"A government laboratory may test food, water, soil, or medical samples for public safety.","zh":"政府實驗室可能為公共安全測試食物、水、土壤或醫療樣本。"},{"en":"Findings from an official laboratory may carry more weight than casual observations.","zh":"官方實驗室的發現可能比隨意觀察更有分量。"},{"en":"The phrase identifies the source of scientific testing.","zh":"這個短語指出科學測試來源。"}],"source":"73 - Crop circles.pdf","sourcePage":11},{"front":"diminished nitrogen","meaning":"減少了的氮","examples":[{"en":"The laboratory found diminished nitrogen in the soil.","zh":"實驗室發現土壤中的氮減少。"},{"en":"Diminished nitrogen means a reduced amount of nitrogen compared with normal levels.","zh":"diminished nitrogen 指與正常水平相比氮含量減少。"},{"en":"A farmer may test soil if crops grow poorly because diminished nitrogen can affect plant growth.","zh":"如果作物生長不良，農夫可能測試土壤，因為氮減少可以影響植物生長。"},{"en":"Lower nitrogen levels may change how healthy or fertile soil is.","zh":"較低氮含量可能改變土壤健康或肥沃程度。"},{"en":"The phrase describes a decrease in a soil nutrient.","zh":"這個短語描述土壤養分減少。"}],"source":"73 - Crop circles.pdf","sourcePage":11},{"front":"decreased nematode populations","meaning":"減少了的線蟲數量","examples":[{"en":"The soil showed decreased nematode populations.","zh":"土壤顯示線蟲數量減少。"},{"en":"Decreased nematode populations means fewer tiny worm-like organisms were found in the soil.","zh":"decreased nematode populations 指土壤中發現較少微小蠕蟲狀生物。"},{"en":"Garden soil may contain nematodes that affect plant roots.","zh":"園土可能含有會影響植物根部的線蟲。"},{"en":"A decrease in soil organisms may suggest the environment has changed.","zh":"土壤生物減少可能暗示環境已改變。"},{"en":"The phrase describes a reduction in a biological soil population.","zh":"這個短語描述土壤生物群數量下降。"}],"source":"73 - Crop circles.pdf","sourcePage":11},{"front":"decreased water content","meaning":"減少了的含水量","examples":[{"en":"The soil also showed decreased water content.","zh":"土壤也顯示含水量減少。"},{"en":"Decreased water content means there is less water in a material than usual.","zh":"decreased water content 指某材料中的水分比平常少。"},{"en":"Bread left open overnight may have decreased water content and become dry.","zh":"麵包打開放過夜後，含水量可能減少並變乾。"},{"en":"Soil with less water can affect plant health and root activity.","zh":"含水量較少的土壤可以影響植物健康和根部活動。"},{"en":"The phrase describes reduced moisture.","zh":"這個短語描述水分減少。"}],"source":"73 - Crop circles.pdf","sourcePage":11},{"front":"other anomalies","meaning":"其他異常現象","examples":[{"en":"Researchers discovered other anomalies as well.","zh":"研究人員也發現其他異常現象。"},{"en":"Other anomalies are additional unusual features that do not fit the normal pattern.","zh":"other anomalies 指其他不符合正常模式的不尋常特徵。"},{"en":"A doctor may find other anomalies in a test result after checking the main problem.","zh":"醫生檢查主要問題後，可能在測試結果中發現其他異常。"},{"en":"Multiple anomalies can make a case more difficult to explain simply.","zh":"多個異常可以令個案更難簡單解釋。"},{"en":"The phrase points to further abnormal details.","zh":"這個短語指出更多異常細節。"}],"source":"73 - Crop circles.pdf","sourcePage":11},{"front":"embedded magnetic particles","meaning":"嵌入的磁性粒子","examples":[{"en":"Researchers found curious embedded magnetic particles.","zh":"研究人員發現奇怪的嵌入磁性粒子。"},{"en":"Embedded magnetic particles are tiny magnetic pieces fixed or lodged inside a material.","zh":"embedded magnetic particles 指固定或嵌在某材料中的微小磁性碎粒。"},{"en":"A laboratory may find embedded metal particles in a machine part after it wears down.","zh":"機器部件磨損後，實驗室可能發現嵌入的金屬粒子。"},{"en":"Magnetic particles in soil may suggest unusual heat, force, or contamination.","zh":"土壤中的磁性粒子可能暗示異常熱力、力量或污染。"},{"en":"The phrase describes small magnetic material trapped within something.","zh":"這個短語描述被困在某物內的小型磁性材料。"}],"source":"73 - Crop circles.pdf","sourcePage":11},{"front":"charred tissue","meaning":"燒焦的組織","examples":[{"en":"Some researchers discovered charred tissue in crop circle plants.","zh":"一些研究人員在麥田圈植物中發現燒焦的組織。"},{"en":"Charred tissue is plant or animal material that looks burned or blackened by heat.","zh":"charred tissue 指看似被熱力燒過或變黑的植物或動物組織。"},{"en":"A leaf too close to a candle may develop charred tissue along its edge.","zh":"太靠近蠟燭的葉子可能在邊緣出現燒焦組織。"},{"en":"Charred plant tissue can suggest exposure to heat or burning.","zh":"燒焦的植物組織可以暗示曾接觸熱力或燃燒。"},{"en":"The phrase describes visible burn damage.","zh":"這個短語描述可見燒傷。"}],"source":"73 - Crop circles.pdf","sourcePage":11},{"front":"plant stalks","meaning":"植物莖","examples":[{"en":"Some plant stalks showed signs of microwave heating.","zh":"一些植物莖顯示微波加熱跡象。"},{"en":"Plant stalks are the main stems that support leaves, flowers, or grain heads.","zh":"plant stalks 指支撐葉、花或穀穗的主要莖部。"},{"en":"A farmer checks plant stalks to see whether crops are strong enough before harvest.","zh":"農夫在收割前檢查植物莖，看作物是否足夠強壯。"},{"en":"Damage to stalks can affect whether plants stand upright or fall over.","zh":"莖受損可以影響植物是否直立或倒下。"},{"en":"The phrase refers to the stem-like support parts of plants.","zh":"這個短語指植物中像莖一樣的支撐部分。"}],"source":"73 - Crop circles.pdf","sourcePage":11},{"front":"show evidence of","meaning":"顯示……的證據","examples":[{"en":"Some plant stalks show evidence of rapid microwave heating.","zh":"一些植物莖顯示快速微波加熱的證據。"},{"en":"To show evidence of something means to contain signs that suggest it happened.","zh":"show evidence of something 指含有跡象，暗示某事曾發生。"},{"en":"A student’s notebook may show evidence of careful revision if it has corrections and summaries.","zh":"如果學生筆記有改正和摘要，它可能顯示仔細溫習的證據。"},{"en":"Evidence can make a claim stronger than simple belief.","zh":"證據可以令聲稱比單純相信更有力。"},{"en":"The phrase focuses on visible or measurable signs.","zh":"這個短語重點是可見或可量度跡象。"}],"source":"73 - Crop circles.pdf","sourcePage":11},{"front":"be exposed to","meaning":"接觸到；暴露於","examples":[{"en":"Some stalks seem to have been exposed to rapid microwave heating.","zh":"一些莖似乎曾接觸快速微波加熱。"},{"en":"To be exposed to something means to come into contact with it or be affected by it.","zh":"be exposed to something 指接觸某事或受其影響。"},{"en":"People exposed to strong sunlight may need sunscreen.","zh":"暴露於強烈陽光的人可能需要防曬。"},{"en":"Exposure to heat can change the structure or appearance of plant material.","zh":"接觸熱力可以改變植物材料的結構或外觀。"},{"en":"The phrase describes contact with an influence or condition.","zh":"這個短語描述接觸某種影響或條件。"}],"source":"73 - Crop circles.pdf","sourcePage":11},{"front":"rapid microwave heating","meaning":"快速微波加熱","examples":[{"en":"Some plant stalks show evidence of rapid microwave heating.","zh":"一些植物莖顯示快速微波加熱的證據。"},{"en":"Rapid microwave heating is fast heating caused by microwave energy.","zh":"rapid microwave heating 指由微波能量造成的快速加熱。"},{"en":"Food in a microwave oven undergoes rapid microwave heating when water molecules absorb energy.","zh":"微波爐中的食物在水分子吸收能量時會經歷快速微波加熱。"},{"en":"Quick heating can create pressure inside plant tissue and may change its structure.","zh":"快速加熱可以在植物組織內產生壓力，並可能改變其結構。"},{"en":"The phrase describes a possible heating process.","zh":"這個短語描述一種可能的加熱過程。"}],"source":"73 - Crop circles.pdf","sourcePage":12},{"front":"attempted to explain","meaning":"嘗試解釋","examples":[{"en":"Scientists have attempted to explain crop circles through natural processes.","zh":"科學家嘗試透過自然過程解釋麥田圈。"},{"en":"Attempted to explain means tried to give a reason or account for something.","zh":"attempted to explain 指嘗試為某事提供原因或說法。"},{"en":"A teacher may attempt to explain a difficult grammar rule by using drawings and examples.","zh":"老師可能用圖畫和例子嘗試解釋困難文法規則。"},{"en":"When a mystery lacks a clear cause, people often attempt different explanations.","zh":"當謎團缺乏明確原因，人們通常嘗試不同解釋。"},{"en":"The phrase shows effort, not guaranteed success.","zh":"這個短語顯示努力，而不是保證成功。"}],"source":"73 - Crop circles.pdf","sourcePage":12},{"front":"as a result of","meaning":"作為……的結果；由於","examples":[{"en":"Some scientists explain crop circles as a result of natural processes.","zh":"一些科學家把麥田圈解釋為自然過程的結果。"},{"en":"As a result of means because of or caused by something.","zh":"as a result of 指因為或由某事造成。"},{"en":"A student may miss class as a result of illness.","zh":"學生可能因病缺課。"},{"en":"If crop circles are a result of natural processes, no human maker is needed.","zh":"如果麥田圈是自然過程的結果，就不需要人類製作者。"},{"en":"The phrase links an effect to its cause.","zh":"這個短語把結果與原因連起來。"}],"source":"73 - Crop circles.pdf","sourcePage":12},{"front":"natural processes","meaning":"自然過程","examples":[{"en":"Some theories explain crop circles through natural processes.","zh":"一些理論透過自然過程解釋麥田圈。"},{"en":"Natural processes are events or changes caused by nature rather than by people.","zh":"natural processes 指由自然造成，而不是由人造成的事件或變化。"},{"en":"Wind, erosion, plant growth, and lightning can all be natural processes.","zh":"風、侵蝕、植物生長和閃電都可以是自然過程。"},{"en":"Explaining something through natural processes makes it less mysterious but still scientifically interesting.","zh":"透過自然過程解釋某事會令它較不神秘，但仍有科學趣味。"},{"en":"The phrase contrasts nature-based causes with human action.","zh":"這個短語把自然原因與人類行動作對比。"}],"source":"73 - Crop circles.pdf","sourcePage":12},{"front":"one popular theory","meaning":"一個流行理論","examples":[{"en":"One popular theory is known as the Plasma Vortex Theory.","zh":"一個流行理論被稱為等離子漩渦理論。"},{"en":"One popular theory means one explanation that many people know or support.","zh":"one popular theory 指一個許多人知道或支持的解釋。"},{"en":"One popular theory about poor sleep is that screen use before bed keeps the brain alert.","zh":"關於睡眠差的一個流行理論是睡前使用螢幕會令大腦保持清醒。"},{"en":"A popular theory may attract attention even before all evidence is settled.","zh":"流行理論即使在所有證據確定前，也可能吸引注意。"},{"en":"The phrase introduces a widely discussed explanation.","zh":"這個短語引入廣泛討論的解釋。"}],"source":"73 - Crop circles.pdf","sourcePage":12},{"front":"accepted by","meaning":"被……接受","examples":[{"en":"The theory is accepted by many mainstream scientists and academics.","zh":"該理論被許多主流科學家和學者接受。"},{"en":"Accepted by someone means believed, supported, or regarded as reasonable by that person or group.","zh":"accepted by someone 指被某人或群體相信、支持或視為合理。"},{"en":"A school rule is more easily followed when it is accepted by teachers and students.","zh":"當校規被老師和學生接受，它更容易被遵守。"},{"en":"If a theory is accepted by experts, it gains credibility.","zh":"如果理論被專家接受，它就獲得可信度。"},{"en":"The phrase shows approval or agreement from a group.","zh":"這個短語顯示來自某群體的認可或同意。"}],"source":"73 - Crop circles.pdf","sourcePage":12},{"front":"mainstream scientists and academics","meaning":"主流科學家和學者","examples":[{"en":"Many mainstream scientists and academics support the theory.","zh":"許多主流科學家和學者支持該理論。"},{"en":"Mainstream scientists and academics are researchers and scholars working within generally accepted scientific or university traditions.","zh":"mainstream scientists and academics 指在一般被接受的科學或大學傳統中工作的研究人員和學者。"},{"en":"Mainstream academics usually require evidence before accepting a claim.","zh":"主流學者通常在接受聲稱前要求證據。"},{"en":"Support from mainstream experts can make a theory seem more serious.","zh":"主流專家的支持可以令理論看似更嚴肅。"},{"en":"The phrase contrasts established experts with fringe thinkers or casual observers.","zh":"這個短語把既有專家與邊緣思想者或普通觀察者作對比。"}],"source":"73 - Crop circles.pdf","sourcePage":12},{"front":"known as","meaning":"被稱為","examples":[{"en":"The theory is known as the Plasma Vortex Theory.","zh":"該理論被稱為等離子漩渦理論。"},{"en":"Known as means called or recognised by a particular name.","zh":"known as 指被稱作或以某特定名稱被認識。"},{"en":"A school may be known as “the science school” because many students win science prizes.","zh":"一所學校可能因許多學生贏得科學獎而被稱為「科學學校」。"},{"en":"A clear name helps people refer to a theory or idea easily.","zh":"清楚名稱幫助人們容易提及某理論或想法。"},{"en":"The phrase introduces a label or title.","zh":"這個短語引入標籤或名稱。"}],"source":"73 - Crop circles.pdf","sourcePage":12},{"front":"Plasma Vortex Theory","meaning":"等離子漩渦理論","examples":[{"en":"Plasma Vortex Theory attempts to explain crop circles naturally.","zh":"等離子漩渦理論嘗試自然地解釋麥田圈。"},{"en":"Plasma Vortex Theory is a proposed explanation involving rotating electrified air.","zh":"Plasma Vortex Theory 指一種涉及旋轉帶電空氣的解釋。"},{"en":"A science class might discuss the theory when comparing natural and human explanations for crop circles.","zh":"科學課比較麥田圈的自然和人為解釋時，可能討論該理論。"},{"en":"The theory tries to connect circular crop patterns with vortex-like movement.","zh":"該理論嘗試把圓形作物圖案與類似漩渦的運動連起來。"},{"en":"The phrase names a specific theory, so it should be kept accurate.","zh":"這個短語是一個特定理論名稱，因此應保持準確。"}],"source":"73 - Crop circles.pdf","sourcePage":12},{"front":"developed by","meaning":"由……提出；由……發展","examples":[{"en":"Plasma Vortex Theory was developed by Dr. Terence Mearden.","zh":"等離子漩渦理論由 Terence Mearden 博士提出。"},{"en":"Developed by someone means created, proposed, or improved by that person.","zh":"developed by someone 指由某人創造、提出或改良。"},{"en":"A new reading method may be developed by teachers who notice students’ common mistakes.","zh":"新閱讀方法可能由注意到學生常見錯誤的老師發展出來。"},{"en":"Naming who developed a theory helps readers trace its origin.","zh":"說出誰提出理論，幫助讀者追溯其來源。"},{"en":"The phrase identifies the creator or proposer.","zh":"這個短語指出創立者或提出者。"}],"source":"73 - Crop circles.pdf","sourcePage":12},{"front":"theorises that","meaning":"提出理論認為","examples":[{"en":"The theory theorises that electrified air forms mini-tornadoes.","zh":"該理論提出帶電空氣形成小型龍捲風。"},{"en":"Theorises that means proposes as an explanation, usually without complete proof.","zh":"theorises that 指提出某事作為解釋，通常尚未完全證明。"},{"en":"A psychologist may theorise that students forget answers because stress blocks memory.","zh":"心理學家可能提出理論認為學生忘記答案，是因為壓力阻礙記憶。"},{"en":"A theory can guide research even before every detail is proven.","zh":"即使細節尚未全部證明，理論仍可以引導研究。"},{"en":"The phrase introduces an explanatory idea.","zh":"這個短語引入解釋性想法。"}],"source":"73 - Crop circles.pdf","sourcePage":12},{"front":"electrified air","meaning":"帶電空氣","examples":[{"en":"Electrified air may form mini-tornadoes on the sides of hills.","zh":"帶電空氣可能在山坡上形成小型龍捲風。"},{"en":"Electrified air is air containing electrical charge or affected by electrical energy.","zh":"electrified air 指含有電荷或受電能影響的空氣。"},{"en":"During a thunderstorm, the air may feel charged before lightning appears.","zh":"雷暴期間，閃電出現前空氣可能感覺帶電。"},{"en":"Electrical activity in air can sometimes produce light, sound, or movement.","zh":"空氣中的電活動有時可以產生光、聲音或運動。"},{"en":"The phrase describes air with unusual electrical properties.","zh":"這個短語描述具有異常電特性的空氣。"}],"source":"73 - Crop circles.pdf","sourcePage":13},{"front":"on the sides of hills","meaning":"在山坡上","examples":[{"en":"The theory says that electrified air forms on the sides of hills.","zh":"該理論說帶電空氣在山坡上形成。"},{"en":"On the sides of hills means along the sloping surfaces of hills.","zh":"on the sides of hills 指在山丘的斜坡表面上。"},{"en":"Farmers may plant vines on the sides of hills because the slopes receive good sunlight.","zh":"農夫可能在山坡上種葡萄藤，因為斜坡能得到良好陽光。"},{"en":"Slopes can affect how wind, air, and water move across land.","zh":"斜坡可以影響風、空氣和水如何穿過土地。"},{"en":"The phrase gives the location of the process.","zh":"這個短語提供過程發生的位置。"}],"source":"73 - Crop circles.pdf","sourcePage":13},{"front":"mini-tornadoes","meaning":"小型龍捲風","examples":[{"en":"Mini-tornadoes may spiral down towards the ground.","zh":"小型龍捲風可能盤旋下降至地面。"},{"en":"Mini-tornadoes are small rotating columns of air similar to tornadoes but much smaller.","zh":"mini-tornadoes 指類似龍捲風但小得多的旋轉空氣柱。"},{"en":"A dust devil on a dry playground can look like a mini-tornado.","zh":"乾燥操場上的塵旋風可以看起來像小型龍捲風。"},{"en":"Rotating air can twist light objects and create circular movement.","zh":"旋轉空氣可以扭動輕物件並產生圓形運動。"},{"en":"The phrase describes small whirlwinds.","zh":"這個短語描述小型旋風。"}],"source":"73 - Crop circles.pdf","sourcePage":13},{"front":"spiral down towards","meaning":"盤旋下降至","examples":[{"en":"The mini-tornadoes spiral down towards the ground.","zh":"小型龍捲風盤旋下降至地面。"},{"en":"To spiral down towards something means to move downward in a circular or twisting path.","zh":"spiral down towards something 指以圓形或扭轉路徑向下移向某處。"},{"en":"A leaf may spiral down towards the pavement when caught in a small wind current.","zh":"樹葉被小氣流捲住時，可能盤旋下降至行人路。"},{"en":"Spiral movement can create circular pressure or marks on a surface below.","zh":"盤旋運動可以在下方表面造成圓形壓力或痕跡。"},{"en":"The phrase combines circular motion with downward direction.","zh":"這個短語結合圓形動作和向下方向。"}],"source":"73 - Crop circles.pdf","sourcePage":13},{"front":"create the circles","meaning":"形成圓圈","examples":[{"en":"The mini-tornadoes may create the circles.","zh":"小型龍捲風可能形成圓圈。"},{"en":"To create the circles means to make or form the circular crop patterns.","zh":"create the circles 指製造或形成圓形作物圖案。"},{"en":"A child can create circles in sand by pressing a cup into the surface.","zh":"孩子可以把杯子壓進沙面來形成圓圈。"},{"en":"If rotating air creates the circles, the cause would be natural rather than human.","zh":"如果旋轉空氣形成圓圈，原因就是自然而非人為。"},{"en":"The phrase focuses on the formation of the patterns.","zh":"這個短語重點是圖案形成。"}],"source":"73 - Crop circles.pdf","sourcePage":13},{"front":"the theory also holds that","meaning":"該理論亦認為","examples":[{"en":"The theory also holds that electrified air causes light to appear.","zh":"該理論亦認為帶電空氣使光芒出現。"},{"en":"The theory also holds that means the theory additionally claims or proposes that.","zh":"theory also holds that 指該理論另外聲稱或提出某事。"},{"en":"A learning theory may hold that sleep helps memory, and also that stress reduces recall.","zh":"學習理論可能認為睡眠幫助記憶，也認為壓力降低回憶能力。"},{"en":"This phrase introduces another part of an explanation.","zh":"這個短語引入解釋中的另一部分。"},{"en":"It signals an additional claim within the same theory.","zh":"它表示同一理論中的額外主張。"}],"source":"73 - Crop circles.pdf","sourcePage":13},{"front":"cause a light to appear","meaning":"使光芒出現","examples":[{"en":"Electrified air may cause a light to appear above the circle.","zh":"帶電空氣可能使光芒在圓圈上方出現。"},{"en":"To cause a light to appear means to make visible light show up.","zh":"cause a light to appear 指令可見光出現。"},{"en":"Pressing a switch can cause a light to appear in a dark hallway.","zh":"按下開關可以使光在黑暗走廊中出現。"},{"en":"If electrical energy produces light, witnesses may report strange glowing effects.","zh":"如果電能產生光，目擊者可能報告奇怪發光效果。"},{"en":"The phrase links a cause with a visible result.","zh":"這個短語把原因與可見結果連起來。"}],"source":"73 - Crop circles.pdf","sourcePage":13},{"front":"account for","meaning":"解釋","examples":[{"en":"The theory may account for UFO sightings.","zh":"該理論可能解釋目擊不明飛行物的事件。"},{"en":"To account for something means to explain why it happened or why it exists.","zh":"account for something 指解釋某事為何發生或存在。"},{"en":"A teacher may account for low test scores by noting that students had little time to revise.","zh":"老師可能指出學生溫習時間少，以解釋測驗分數低。"},{"en":"A strong theory should account for several observations, not only one detail.","zh":"強有力理論應能解釋多項觀察，而不只是單一細節。"},{"en":"The phrase focuses on explanation.","zh":"這個短語重點是解釋。"}],"source":"73 - Crop circles.pdf","sourcePage":13},{"front":"UFO sightings","meaning":"目擊不明飛行物的事件","examples":[{"en":"The theory attempts to account for UFO sightings.","zh":"該理論嘗試解釋目擊不明飛行物的事件。"},{"en":"UFO sightings are reports of unidentified flying objects seen in the sky.","zh":"UFO sightings 指人們報告在天空看見不明飛行物。"},{"en":"People may report UFO sightings when they see lights or shapes they cannot identify.","zh":"當人們看見不能辨認的光或形狀時，可能報告目擊不明飛行物。"},{"en":"Some sightings later turn out to be aircraft, weather balloons, or natural light effects.","zh":"有些目擊事件後來證明是飛機、氣象氣球或自然光效應。"},{"en":"The phrase describes reported observations, not confirmed alien activity.","zh":"這個短語描述被報告的觀察，而不是已確認外星活動。"}],"source":"73 - Crop circles.pdf","sourcePage":13},{"front":"considerable support","meaning":"相當多的支持","examples":[{"en":"The theory still has considerable support.","zh":"該理論仍有相當多支持。"},{"en":"Considerable support means a fairly large amount of approval or backing.","zh":"considerable support 指相當大量的認可或支持。"},{"en":"A school policy may have considerable support if most parents and teachers agree with it.","zh":"如果大多數家長和老師同意，學校政策可能有相當多支持。"},{"en":"Support can keep a theory alive even when critics raise objections.","zh":"即使批評者提出反對，支持也可以令理論持續存在。"},{"en":"The phrase suggests meaningful but not necessarily universal support.","zh":"這個短語暗示有意義但不一定是普遍支持。"}],"source":"73 - Crop circles.pdf","sourcePage":13},{"front":"come under fire","meaning":"受到批評；受到抨擊","examples":[{"en":"The theory has come under fire because of complex crop circle patterns.","zh":"該理論因複雜麥田圈圖案而受到批評。"},{"en":"To come under fire means to receive criticism or attack.","zh":"come under fire 指受到批評或攻擊。"},{"en":"A school rule may come under fire if parents think it is unfair.","zh":"如果家長認為校規不公平，該規則可能受到批評。"},{"en":"When new evidence does not fit a theory, the theory may be criticised.","zh":"當新證據不符合某理論，該理論可能被批評。"},{"en":"The phrase is metaphorical and often used for public criticism.","zh":"這個短語是比喻用法，常用於公開批評。"}],"source":"73 - Crop circles.pdf","sourcePage":13},{"front":"highly intricate and complex","meaning":"高度精細複雜","examples":[{"en":"Some crop circle patterns are highly intricate and complex.","zh":"一些麥田圈圖案高度精細複雜。"},{"en":"Highly intricate and complex means very detailed, complicated, and carefully arranged.","zh":"highly intricate and complex 指非常細緻、複雜且精心排列。"},{"en":"A handmade watch may be highly intricate and complex inside.","zh":"手工錶內部可能高度精細複雜。"},{"en":"The more complex a design is, the harder it becomes to explain by simple causes.","zh":"設計越複雜，就越難用簡單原因解釋。"},{"en":"The phrase strongly emphasises difficulty and detail.","zh":"這個短語強烈強調難度和細節。"}],"source":"73 - Crop circles.pdf","sourcePage":14},{"front":"since 1991","meaning":"自一九九一年以來","examples":[{"en":"More complex crop circle patterns have appeared since 1991.","zh":"自1991年以來，更複雜的麥田圈圖案已經出現。"},{"en":"Since 1991 means from the year 1991 until a later time or the present point in the passage.","zh":"since 1991 指從1991年起直到較後時間或文章中的現在時點。"},{"en":"Since 2020, many schools have used more online teaching tools.","zh":"自2020年以來，許多學校使用更多網上教學工具。"},{"en":"The phrase marks the starting point of a continuing trend.","zh":"這個短語標示持續趨勢的起點。"},{"en":"It helps organise events by time.","zh":"它幫助按時間組織事件。"}],"source":"73 - Crop circles.pdf","sourcePage":14},{"front":"hoaxes or practical jokes","meaning":"騙局或惡作劇","examples":[{"en":"Some people believe the circles are hoaxes or practical jokes.","zh":"有些人相信這些圓圈是騙局或惡作劇。"},{"en":"Hoaxes or practical jokes are tricks made to deceive, amuse, or embarrass people.","zh":"hoaxes or practical jokes 指為欺騙、取樂或令人尷尬而設的把戲。"},{"en":"A fake notice about a cancelled exam would be a hoax if it was meant to fool students.","zh":"如果假考試取消通知旨在欺騙學生，它就是騙局。"},{"en":"If crop circles are hoaxes, people made them deliberately rather than by natural forces.","zh":"如果麥田圈是騙局，它們就是由人刻意製造，而不是由自然力量造成。"},{"en":"The phrase suggests deception or playful trickery.","zh":"這個短語暗示欺騙或玩笑式把戲。"}],"source":"73 - Crop circles.pdf","sourcePage":14},{"front":"major support for this theory","meaning":"對此理論的主要支持","examples":[{"en":"Major support for this theory emerged in 1991.","zh":"對此理論的主要支持在1991年出現。"},{"en":"Major support for this theory means important evidence or arguments that seem to back the explanation.","zh":"major support for this theory 指看似支持該解釋的重要證據或論點。"},{"en":"Major support for a school reform may come when exam results improve after the change.","zh":"如果改革後考試成績改善，這可能成為學校改革的主要支持。"},{"en":"Strong support can make a theory appear more believable to the public.","zh":"強有力支持可以令理論對公眾看起來更可信。"},{"en":"The phrase introduces evidence in favour of a theory.","zh":"這個短語引入支持某理論的證據。"}],"source":"73 - Crop circles.pdf","sourcePage":14},{"front":"emerged when","meaning":"在……時出現","examples":[{"en":"Major support emerged when two Englishmen made a claim.","zh":"當兩名英國男子作出聲稱時，主要支持出現了。"},{"en":"Emerged when means appeared or became known at the time something happened.","zh":"emerged when 指在某事發生時出現或變得為人所知。"},{"en":"A problem emerged when students tried to log in before the online exam.","zh":"當學生在網上考試前嘗試登入時，問題出現了。"},{"en":"New information can change a debate when it appears at the right moment.","zh":"新資訊在合適時刻出現，可以改變爭論。"},{"en":"The phrase connects the appearance of something with a specific event.","zh":"這個短語把某事出現與特定事件連起來。"}],"source":"73 - Crop circles.pdf","sourcePage":14},{"front":"claimed to have created","meaning":"聲稱曾經製造","examples":[{"en":"Two Englishmen claimed to have created many crop circles.","zh":"兩名英國男子聲稱曾經製造許多麥田圈。"},{"en":"Claimed to have created means said that they had made something, though the claim may need checking.","zh":"claimed to have created 指說自己曾製造某物，但該聲稱可能需要查核。"},{"en":"A student may claim to have created a website, but the teacher may ask to see the code.","zh":"學生可能聲稱曾製作網站，但老師可能要求查看程式碼。"},{"en":"A claim about making something can support a hoax theory if evidence fits.","zh":"如果證據吻合，關於製造某物的聲稱可以支持騙局理論。"},{"en":"The phrase reports what people said, not necessarily proven truth.","zh":"這個短語報告人們所說內容，不一定是已證實真相。"}],"source":"73 - Crop circles.pdf","sourcePage":14},{"front":"approximately","meaning":"大約","examples":[{"en":"They claimed to have created approximately 250 crop circles.","zh":"他們聲稱曾經製造大約250個麥田圈。"},{"en":"Approximately means about or nearly, not exactly.","zh":"approximately 指大約或接近，不是精確。"},{"en":"Approximately twenty students joined the English club this term.","zh":"本學期大約二十名學生加入英文學會。"},{"en":"Writers use this word when the exact number is not known or not necessary.","zh":"當精確數字未知或不必要時，作者會使用這個詞。"},{"en":"The phrase signals an estimate.","zh":"這個詞表示估算。"}],"source":"73 - Crop circles.pdf","sourcePage":14},{"front":"more rugged than","meaning":"比……更粗糙","examples":[{"en":"Their circles were more rugged than others.","zh":"他們的圓圈比其他圓圈更粗糙。"},{"en":"More rugged than means rougher, less smooth, or less carefully finished than something else.","zh":"more rugged than 指比某物更粗糙、不平滑或較不精細完成。"},{"en":"A handmade wooden table may look more rugged than one made in a factory.","zh":"手製木桌可能比工廠製桌看起來更粗糙。"},{"en":"If a crop circle is rugged, people may suspect it was made with simple tools.","zh":"如果麥田圈粗糙，人們可能懷疑它由簡單工具製造。"},{"en":"The phrase compares roughness or finish.","zh":"這個短語比較粗糙程度或完成度。"}],"source":"73 - Crop circles.pdf","sourcePage":14},{"front":"already suspect","meaning":"已經令人懷疑","examples":[{"en":"Many of those crop circles were already suspect.","zh":"那些麥田圈中有許多已經令人懷疑。"},{"en":"Already suspect means already doubtful or considered likely to be false before new information appeared.","zh":"already suspect 指在新資訊出現前已經可疑或被認為可能是假的。"},{"en":"A student’s excuse may be already suspect if the story has changed twice.","zh":"如果學生的藉口已改變兩次，它可能已經令人懷疑。"},{"en":"If a circle looked rough before a confession, people may already have doubted it.","zh":"如果某圓圈在有人承認前已看起來粗糙，人們可能早已懷疑它。"},{"en":"The phrase describes existing suspicion.","zh":"這個短語描述已有的懷疑。"}],"source":"73 - Crop circles.pdf","sourcePage":14},{"front":"it is irrational to believe that","meaning":"相信……是不理性的","examples":[{"en":"It is irrational to believe that all crop circles are fake.","zh":"相信所有麥田圈都是假的是不理性的。"},{"en":"It is irrational to believe that means it is not reasonable or logical to accept that idea.","zh":"it is irrational to believe that 指接受某想法並不合理或不合邏輯。"},{"en":"It is irrational to believe that one bad test means a student can never improve.","zh":"相信一次測驗差就代表學生永遠不能進步是不理性的。"},{"en":"A belief becomes irrational when it ignores evidence or makes an extreme claim.","zh":"當信念忽視證據或作出極端聲稱，它就變得不理性。"},{"en":"The phrase strongly criticises a conclusion as unreasonable.","zh":"這個短語強烈批評某結論不合理。"}],"source":"73 - Crop circles.pdf","sourcePage":14},{"front":"fake for publicity","meaning":"為宣傳而造假","examples":[{"en":"The writer rejects the idea that all crop circles are fake for publicity.","zh":"作者否定所有麥田圈都是為宣傳而造假的想法。"},{"en":"Fake for publicity means deliberately made false in order to attract attention.","zh":"fake for publicity 指為吸引注意而刻意造假。"},{"en":"A restaurant might stage a fake argument for publicity, but customers may lose trust if they discover it.","zh":"餐廳可能為宣傳而安排假爭吵，但顧客發現後可能失去信任。"},{"en":"Publicity hoaxes can spread quickly because people share strange stories.","zh":"宣傳騙局可以迅速傳播，因為人們會分享奇怪故事。"},{"en":"The phrase links deception with the aim of gaining attention.","zh":"這個短語把欺騙與獲取注意的目的連起來。"}],"source":"73 - Crop circles.pdf","sourcePage":14},{"front":"long before","meaning":"早在……之前","examples":[{"en":"Many crop circles appeared long before the phenomenon became famous.","zh":"許多麥田圈早在該現象成名之前已經出現。"},{"en":"Long before means much earlier than a later event or time.","zh":"long before 指比後來事件或時間早得多。"},{"en":"A teacher may prepare exam materials long before students begin revising.","zh":"老師可能早在學生開始溫習前就準備考試材料。"},{"en":"If something existed long before publicity, it is harder to explain it only as a publicity trick.","zh":"如果某事早在宣傳之前已存在，就較難只用宣傳騙局來解釋。"},{"en":"The phrase emphasises an earlier time gap.","zh":"這個短語強調較早的時間距離。"}],"source":"73 - Crop circles.pdf","sourcePage":15},{"front":"gained widespread recognition","meaning":"獲得廣泛認識","examples":[{"en":"The phenomenon later gained widespread recognition from the public and press.","zh":"該現象後來獲得公眾和傳媒的廣泛認識。"},{"en":"Gained widespread recognition means became widely known or acknowledged by many people.","zh":"gained widespread recognition 指被許多人廣泛知道或承認。"},{"en":"A local singer may gain widespread recognition after a performance video goes viral.","zh":"本地歌手在表演影片爆紅後，可能獲得廣泛認識。"},{"en":"Once a phenomenon gains recognition, more people report, discuss, and investigate it.","zh":"一旦現象獲得認識，更多人會報告、討論和調查它。"},{"en":"The phrase describes growing public awareness.","zh":"這個短語描述公眾意識增長。"}],"source":"73 - Crop circles.pdf","sourcePage":15},{"front":"the public and press","meaning":"公眾和傳媒","examples":[{"en":"The crop circle phenomenon gained attention from the public and press.","zh":"麥田圈現象獲得公眾和傳媒關注。"},{"en":"The public and press means ordinary people and the media.","zh":"public and press 指普通人和媒體。"},{"en":"A school scandal may attract attention from the public and press if it affects many families.","zh":"如果學校醜聞影響許多家庭，它可能吸引公眾和傳媒關注。"},{"en":"Media attention can make a topic spread faster than academic discussion alone.","zh":"媒體關注可以令話題比單靠學術討論傳播得更快。"},{"en":"The phrase combines general society with news organisations.","zh":"這個短語結合一般社會和新聞機構。"}],"source":"73 - Crop circles.pdf","sourcePage":15},{"front":"too many…for them to…","meaning":"太多……以致不可能全部……","examples":[{"en":"Too many crop circles appear each year for them all to be hoaxes.","zh":"每年出現太多麥田圈，以致不可能全部都是騙局。"},{"en":"Too many A for them to B means the number is so large that a certain explanation seems unlikely.","zh":"too many A for them to B 指數量太大，使某解釋看起來不太可能。"},{"en":"Too many students were absent for it to be a normal school day.","zh":"缺席學生太多，以致不可能是普通上課日。"},{"en":"When there are too many cases, a simple explanation may no longer fit them all.","zh":"當個案太多，簡單解釋可能不再適用於全部個案。"},{"en":"The structure shows that quantity makes an idea difficult to accept.","zh":"這個結構顯示數量令某想法難以接受。"}],"source":"73 - Crop circles.pdf","sourcePage":15},{"front":"strange mathematical traits","meaning":"奇特的數學特徵","examples":[{"en":"Many crop circles show strange mathematical traits.","zh":"許多麥田圈顯示奇特的數學特徵。"},{"en":"Strange mathematical traits are unusual numerical, geometric, or proportional features.","zh":"strange mathematical traits 指異常的數字、幾何或比例特徵。"},{"en":"A puzzle may have strange mathematical traits if every answer follows a hidden pattern.","zh":"如果每個答案都跟隨隱藏模式，謎題可能有奇特數學特徵。"},{"en":"Mathematical features can make a design seem planned rather than random.","zh":"數學特徵可以令設計看似有計劃，而不是隨機。"},{"en":"The phrase connects unusual patterns with mathematics.","zh":"這個短語把異常圖案與數學連起來。"}],"source":"73 - Crop circles.pdf","sourcePage":15},{"front":"when analysed","meaning":"在被分析時","examples":[{"en":"Crop circles show strange traits when analysed.","zh":"麥田圈在被分析時顯示奇怪特徵。"},{"en":"When analysed means when examined carefully, often using a method or evidence.","zh":"when analysed 指被仔細檢查時，通常使用方法或證據。"},{"en":"A student’s essay may seem simple, but when analysed, it shows careful organisation.","zh":"學生作文可能看似簡單，但被分析時顯示出仔細組織。"},{"en":"Analysis can reveal details that casual observation misses.","zh":"分析可以揭示隨意觀察錯過的細節。"},{"en":"The phrase introduces what is discovered through study.","zh":"這個短語引入透過研究發現的內容。"}],"source":"73 - Crop circles.pdf","sourcePage":15},{"front":"an enigma","meaning":"謎團","examples":[{"en":"The crop circle phenomenon remains an enigma.","zh":"麥田圈現象仍然是一個謎團。"},{"en":"An enigma is something mysterious and difficult to understand or explain.","zh":"enigma 指神秘且難以理解或解釋的事物。"},{"en":"A locked diary with no owner’s name may become an enigma for a family.","zh":"沒有主人名字的上鎖日記，可能成為家庭中的謎團。"},{"en":"A topic remains an enigma when explanations are incomplete or disputed.","zh":"當解釋不完整或有爭議，某主題就仍然是謎團。"},{"en":"The word suggests a deep puzzle.","zh":"這個詞暗示深層謎題。"}],"source":"73 - Crop circles.pdf","sourcePage":15},{"front":"a great deal of money","meaning":"大量金錢","examples":[{"en":"A great deal of money has been spent on crop circle research.","zh":"大量金錢已花在麥田圈研究上。"},{"en":"A great deal of money means a large amount of money.","zh":"a great deal of money 指很多金錢。"},{"en":"A family may spend a great deal of money on medical treatment if insurance is limited.","zh":"如果保險有限，家庭可能花大量金錢在醫療上。"},{"en":"Expensive research may involve travel, laboratory testing, equipment, and expert time.","zh":"昂貴研究可能涉及旅行、實驗室測試、設備和專家時間。"},{"en":"The phrase stresses high financial cost.","zh":"這個短語強調高財務成本。"}],"source":"73 - Crop circles.pdf","sourcePage":15},{"front":"in an attempt to","meaning":"嘗試去","examples":[{"en":"Researchers have spent money in an attempt to find a solution.","zh":"研究人員花錢嘗試找出答案。"},{"en":"In an attempt to means while trying to do something.","zh":"in an attempt to 指在嘗試做某事時。"},{"en":"A student may rewrite an essay in an attempt to make the argument clearer.","zh":"學生可能重寫作文，嘗試令論點更清楚。"},{"en":"People spend resources on difficult problems when they hope effort will produce answers.","zh":"人們把資源花在困難問題上，是因為希望努力會帶來答案。"},{"en":"The phrase shows purpose and effort, not guaranteed success.","zh":"這個短語顯示目的和努力，而不是保證成功。"}],"source":"73 - Crop circles.pdf","sourcePage":15},{"front":"find a solution to","meaning":"找出……的答案","examples":[{"en":"Researchers want to find a solution to this intriguing puzzle.","zh":"研究人員想找出這個引人入勝謎題的答案。"},{"en":"To find a solution to a problem means to discover an answer or way to deal with it.","zh":"find a solution to a problem 指發現答案或處理問題的方法。"},{"en":"A school may try to find a solution to bullying by improving reporting and support.","zh":"學校可能透過改善舉報和支援來找出欺凌問題的解決方法。"},{"en":"A good solution explains the cause and reduces confusion or harm.","zh":"好的解決方法會解釋原因，並減少困惑或傷害。"},{"en":"The phrase focuses on resolving a problem.","zh":"這個短語重點是解決問題。"}],"source":"73 - Crop circles.pdf","sourcePage":15},{"front":"intriguing puzzle","meaning":"引人入勝的謎題","examples":[{"en":"Crop circles are an intriguing puzzle.","zh":"麥田圈是一個引人入勝的謎題。"},{"en":"An intriguing puzzle is a problem that is interesting because it is difficult to explain.","zh":"intriguing puzzle 指因難以解釋而令人感興趣的問題。"},{"en":"A missing page in an old family album may become an intriguing puzzle.","zh":"舊家庭相簿中失蹤的一頁，可能成為引人入勝的謎題。"},{"en":"A puzzle becomes intriguing when clues exist but do not yet produce a clear answer.","zh":"當有線索但尚未產生清楚答案，謎題就變得吸引。"},{"en":"The phrase suggests mystery that attracts attention.","zh":"這個短語暗示吸引注意的神秘感。"}],"source":"73 - Crop circles.pdf","sourcePage":15},{"front":"continue to haunt humanity","meaning":"繼續困擾人類","examples":[{"en":"This puzzle may continue to haunt humanity.","zh":"這個謎題可能會繼續困擾人類。"},{"en":"To continue to haunt humanity means to keep troubling or fascinating people over time.","zh":"continue to haunt humanity 指隨時間繼續困擾或吸引人類。"},{"en":"Unanswered historical mysteries can continue to haunt society for generations.","zh":"未解答的歷史謎團可以困擾社會數代。"},{"en":"When no explanation satisfies everyone, a question may stay in public imagination.","zh":"當沒有解釋能令所有人滿意，問題可能留在公眾想像中。"},{"en":"The phrase is dramatic and suggests a lasting mental burden.","zh":"這個短語較戲劇化，暗示持久的心理負擔。"}],"source":"73 - Crop circles.pdf","sourcePage":16},{"front":"until an explanation is found","meaning":"直到找到解釋為止","examples":[{"en":"The mystery will continue until an explanation is found.","zh":"這個謎團會繼續，直到找到解釋為止。"},{"en":"Until an explanation is found means up to the time when a reason or answer is discovered.","zh":"until an explanation is found 指直到原因或答案被發現的時候。"},{"en":"A school problem may continue until an explanation is found for why students keep missing lessons.","zh":"學生不斷缺課的問題可能會持續，直到找出原因為止。"},{"en":"Finding an explanation can turn uncertainty into understanding.","zh":"找到解釋可以把不確定轉化成理解。"},{"en":"The phrase sets the condition for an issue to end.","zh":"這個短語設定問題結束的條件。"}],"source":"73 - Crop circles.pdf","sourcePage":16},{"front":"do the following statements reflect","meaning":"以下陳述是否反映……","examples":[{"en":"Students decide whether the statements reflect the writer’s claims.","zh":"學生判斷以下陳述是否反映作者的主張。"},{"en":"Do the following statements reflect means do these statements match or express the same ideas.","zh":"do the following statements reflect 指以下陳述是否符合或表達相同想法。"},{"en":"In a reading test, students must check whether an option reflects the writer’s meaning exactly.","zh":"在閱讀測驗中，學生必須檢查選項是否準確反映作者意思。"},{"en":"A statement may sound related but still fail to reflect the writer’s actual view.","zh":"陳述可能聽起來相關，但仍未能反映作者真正看法。"},{"en":"The phrase asks about agreement with the text.","zh":"這個短語詢問是否與文本一致。"}],"source":"73 - Crop circles.pdf","sourcePage":16},{"front":"the claims of the writer","meaning":"作者的主張","examples":[{"en":"The questions ask about the claims of the writer.","zh":"題目詢問作者的主張。"},{"en":"The claims of the writer are the views, arguments, or statements the writer puts forward.","zh":"claims of the writer 指作者提出的觀點、論點或陳述。"},{"en":"Students should separate the writer’s claims from examples, rumours, and other people’s opinions.","zh":"學生應把作者主張與例子、傳聞和他人意見分開。"},{"en":"Misreading the writer’s claim can lead to wrong YES, NO, or NOT GIVEN answers.","zh":"誤讀作者主張可能導致 YES、NO 或 NOT GIVEN 答錯。"},{"en":"The phrase focuses on what the author is asserting.","zh":"這個短語重點是作者正在聲稱甚麼。"}],"source":"73 - Crop circles.pdf","sourcePage":16},{"front":"agrees with the views of the writer","meaning":"與作者觀點一致","examples":[{"en":"A YES answer means the statement agrees with the writer’s views.","zh":"YES 答案表示該陳述與作者觀點一致。"},{"en":"Agrees with the views of the writer means matches the writer’s opinion or claim.","zh":"agrees with the views of the writer 指與作者意見或主張相符。"},{"en":"If the writer says all explanations are incomplete, a statement saying the mystery remains unsolved may agree.","zh":"如果作者說所有解釋都不完整，而陳述說謎團仍未解開，就可能一致。"},{"en":"Students should choose YES only when the passage clearly supports the statement.","zh":"只有當文章清楚支持陳述時，學生才應選 YES。"},{"en":"The phrase is used in YES, NO, NOT GIVEN questions.","zh":"這個短語用於 YES、NO、NOT GIVEN 題目。"}],"source":"73 - Crop circles.pdf","sourcePage":16},{"front":"contradicts the views of the writer","meaning":"與作者觀點相矛盾","examples":[{"en":"A NO answer means the statement contradicts the writer’s views.","zh":"NO 答案表示該陳述與作者觀點相矛盾。"},{"en":"Contradicts the views of the writer means says the opposite of what the writer believes.","zh":"contradicts the views of the writer 指說出與作者相信內容相反的意思。"},{"en":"If the writer rejects the idea that all crop circles are fake, a statement saying he accepts it contradicts his view.","zh":"如果作者否定所有麥田圈都是假的說法，而陳述說他接受該說法，就是與其觀點矛盾。"},{"en":"Students should choose NO only when there is clear opposition in meaning.","zh":"學生只有在意思明確相反時才應選 NO。"},{"en":"The phrase means disagreement, not missing information.","zh":"這個短語表示不同意，而不是資料缺失。"}],"source":"73 - Crop circles.pdf","sourcePage":16},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"NOT GIVEN means it is impossible to say what the writer thinks.","zh":"NOT GIVEN 表示無法判斷作者怎樣想。"},{"en":"Impossible to say means there is not enough information to decide.","zh":"impossible to say 指資料不足，無法決定。"},{"en":"If a passage mentions crop circles but not farmers’ income, it is impossible to say what the writer thinks about income.","zh":"如果文章提到麥田圈但沒有提到農夫收入，就無法判斷作者對收入的看法。"},{"en":"Students should not guess beyond the text when the information is missing.","zh":"當資料缺失時，學生不應超出文本猜測。"},{"en":"The phrase is a warning against unsupported inference.","zh":"這個短語提醒不要作沒有支持的推論。"}],"source":"73 - Crop circles.pdf","sourcePage":16},{"front":"only appear in","meaning":"只出現在","examples":[{"en":"The statement asks whether crop circles only appear in wheat fields.","zh":"該陳述問麥田圈是否只出現在小麥田。"},{"en":"Only appear in means are found in one place or type of place and nowhere else.","zh":"only appear in 指只在某一地方或類型地方被發現，其他地方沒有。"},{"en":"A rule that only appears in the exam guide may be missed by students who read only class notes.","zh":"如果規則只出現在考試指南中，只讀課堂筆記的學生可能會錯過。"},{"en":"If crop circles appear in oat fields too, they do not only appear in wheat fields.","zh":"如果麥田圈也出現在燕麥田，它們就不是只出現在小麥田。"},{"en":"The phrase tests whether a claim is too narrow.","zh":"這個短語測試聲稱是否過於狹窄。"}],"source":"73 - Crop circles.pdf","sourcePage":16},{"front":"have never been documented in","meaning":"從未在……有記錄","examples":[{"en":"The statement asks whether crop circles have never been documented in tropical countries.","zh":"該陳述問麥田圈是否從未在熱帶國家有記錄。"},{"en":"Have never been documented in means no recorded cases have ever been found in that place.","zh":"have never been documented in 指某地從來沒有被記錄到相關個案。"},{"en":"A rare bird may never have been documented in a city until a photographer records it.","zh":"稀有鳥類可能從未在城市有記錄，直到攝影師拍到它。"},{"en":"Saying never is strong, so students must check whether the passage gives clear evidence.","zh":"說 never 很強，因此學生必須檢查文章是否有清楚證據。"},{"en":"The phrase focuses on absence of records.","zh":"這個短語重點是沒有記錄。"}],"source":"73 - Crop circles.pdf","sourcePage":16},{"front":"tropical countries","meaning":"熱帶國家","examples":[{"en":"The question mentions tropical countries.","zh":"題目提到熱帶國家。"},{"en":"Tropical countries are countries located in warm regions near the equator.","zh":"tropical countries 指位於赤道附近溫暖地區的國家。"},{"en":"Tropical countries often have hot weather, heavy rain, and rich plant life.","zh":"熱帶國家通常有炎熱天氣、大雨和豐富植物生命。"},{"en":"If a passage does not mention tropical countries, students cannot assume anything about them.","zh":"如果文章沒有提到熱帶國家，學生不能假設關於它們的內容。"},{"en":"The phrase describes climate and location.","zh":"這個短語描述氣候和位置。"}],"source":"73 - Crop circles.pdf","sourcePage":16},{"front":"the largest number of","meaning":"最大數量的","examples":[{"en":"The question refers to the largest number of crop circle reports.","zh":"題目提到最大數量的麥田圈報告。"},{"en":"The largest number of something means the greatest amount compared with other groups or times.","zh":"largest number of something 指與其他群體或時間相比最大的數量。"},{"en":"A school may receive the largest number of applications in the year it opens a new programme.","zh":"學校在開辦新課程那年可能收到最大數量的申請。"},{"en":"Comparing numbers helps identify where or when a phenomenon was most common.","zh":"比較數量有助找出現象在哪裡或何時最常見。"},{"en":"The phrase focuses on maximum quantity.","zh":"這個短語重點是最高數量。"}],"source":"73 - Crop circles.pdf","sourcePage":16},{"front":"in a single year","meaning":"在單一年份內","examples":[{"en":"The question asks about crop circle reports in a single year.","zh":"題目詢問單一年份內的麥田圈報告。"},{"en":"In a single year means within one year only.","zh":"in a single year 指只在一年之內。"},{"en":"A student may improve greatly in a single year with steady practice.","zh":"學生透過穩定練習，可能在單一年份內大幅進步。"},{"en":"Counting cases in one year helps show how intense that period was.","zh":"計算一年內的個案有助顯示該時期有多集中。"},{"en":"The phrase limits the time period clearly.","zh":"這個短語清楚限制時間範圍。"}],"source":"73 - Crop circles.pdf","sourcePage":17},{"front":"increasingly complex","meaning":"越來越複雜","examples":[{"en":"The patterns of crop circles have become increasingly complex.","zh":"麥田圈的圖案變得越來越複雜。"},{"en":"Increasingly complex means becoming more and more complicated over time.","zh":"increasingly complex 指隨時間變得越來越複雜。"},{"en":"A student’s essays may become increasingly complex as she learns to use better examples and sentence structures.","zh":"當學生學會使用更好例子和句式，她的作文可能變得越來越複雜。"},{"en":"Greater complexity can make simple explanations less convincing.","zh":"複雜度增加可以令簡單解釋較不令人信服。"},{"en":"The phrase describes a rising level of difficulty or detail.","zh":"這個短語描述難度或細節程度上升。"}],"source":"73 - Crop circles.pdf","sourcePage":17},{"front":"all crop circles are hoaxes","meaning":"所有麥田圈都是騙局","examples":[{"en":"The writer does not accept that all crop circles are hoaxes.","zh":"作者不接受所有麥田圈都是騙局。"},{"en":"All crop circles are hoaxes means every crop circle is a deliberate trick or fake.","zh":"all crop circles are hoaxes 指每一個麥田圈都是刻意把戲或假象。"},{"en":"A teacher should not assume all excuses are lies just because one student lied before.","zh":"老師不應因為一名學生曾說謊，就假設所有藉口都是謊言。"},{"en":"Extreme claims are hard to support when many cases come from different places and times.","zh":"當個案來自不同地方和時間，極端聲稱很難支持。"},{"en":"The phrase presents a total explanation that the writer rejects.","zh":"這個短語呈現作者否定的全面解釋。"}],"source":"73 - Crop circles.pdf","sourcePage":17},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below with words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"To complete the summary below means to fill gaps in a short version of the passage.","zh":"complete the summary below 指填補文章簡短版本中的空格。"},{"en":"Students should read the summary first, then locate matching information in the text.","zh":"學生應先讀摘要，然後在文本中定位相符資料。"},{"en":"Summary completion tests meaning, grammar, and exact word choice.","zh":"摘要填空測試意思、文法和準確用字。"},{"en":"The phrase is an exam instruction.","zh":"這個短語是考試指示。"}],"source":"73 - Crop circles.pdf","sourcePage":17},{"front":"choose no more than three words","meaning":"選擇不多於三個字","examples":[{"en":"Students choose no more than three words from the passage.","zh":"學生從文章中選擇不多於三個字。"},{"en":"Choose no more than three words means write one, two, or three words only.","zh":"choose no more than three words 指只寫一個、兩個或三個詞。"},{"en":"If the answer has four words, it breaks the instruction even if the idea is correct.","zh":"如果答案有四個詞，即使意思正確，也違反指示。"},{"en":"Students should count words carefully before writing the final answer.","zh":"學生在寫最終答案前應仔細數詞數。"},{"en":"The phrase sets a strict answer-length rule.","zh":"這個短語設定嚴格答案長度規則。"}],"source":"73 - Crop circles.pdf","sourcePage":17},{"front":"since the early 1970s","meaning":"自一九七零年代初以來","examples":[{"en":"Since the early 1970s, many crop circles have been reported.","zh":"自1970年代初以來，已有許多麥田圈被報告。"},{"en":"Since the early 1970s means from the first years of the 1970s until a later time.","zh":"since the early 1970s 指從1970年代最初幾年起直到較後時間。"},{"en":"Since the early 2000s, many students have used mobile phones for learning.","zh":"自2000年代初以來，許多學生使用手機學習。"},{"en":"The phrase marks the beginning of a continuing period.","zh":"這個短語標示持續時期的開始。"},{"en":"It helps organise events chronologically.","zh":"它幫助按時間順序組織事件。"}],"source":"73 - Crop circles.pdf","sourcePage":17},{"front":"over ten thousand","meaning":"超過一萬個","examples":[{"en":"Over ten thousand crop circles have been reported around the world.","zh":"世界各地已有超過一萬個麥田圈被報告。"},{"en":"Over ten thousand means more than 10,000.","zh":"over ten thousand 指多於10,000。"},{"en":"A popular online lesson may receive over ten thousand views in one week.","zh":"受歡迎的網上課堂可能一星期內有超過一萬次觀看。"},{"en":"A number this large can make a phenomenon seem widespread and difficult to dismiss.","zh":"如此大的數字可以令現象看起來廣泛且難以忽視。"},{"en":"The phrase stresses quantity beyond a round figure.","zh":"這個短語強調超過一個整數數字的數量。"}],"source":"73 - Crop circles.pdf","sourcePage":17},{"front":"around the world","meaning":"世界各地","examples":[{"en":"Crop circles have been reported around the world.","zh":"麥田圈已在世界各地被報告。"},{"en":"Around the world means in many different countries or regions globally.","zh":"around the world 指在全球許多不同國家或地區。"},{"en":"Children around the world learn English through songs, games, and stories.","zh":"世界各地的孩子透過歌曲、遊戲和故事學英文。"},{"en":"Reports from around the world can make a topic seem international.","zh":"來自世界各地的報告可以令話題顯得國際化。"},{"en":"The phrase emphasises global spread.","zh":"這個短語強調全球分布。"}],"source":"73 - Crop circles.pdf","sourcePage":17},{"front":"the greatest number occurring in","meaning":"最大數量出現在","examples":[{"en":"The summary asks where the greatest number occurred.","zh":"摘要問最大數量出現在哪裡。"},{"en":"The greatest number occurring in a place means the largest amount happened there.","zh":"greatest number occurring in a place 指最大數量在該地發生。"},{"en":"A school report may show the greatest number of absences occurring in winter.","zh":"學校報告可能顯示最多缺席出現在冬季。"},{"en":"Identifying where the greatest number occurred helps locate the centre of a pattern.","zh":"找出最大數量出現在哪裡，有助定位模式中心。"},{"en":"The phrase combines quantity with location or time.","zh":"這個短語結合數量與地點或時間。"}],"source":"73 - Crop circles.pdf","sourcePage":17},{"front":"over one hundred circles","meaning":"超過一百個圓圈","examples":[{"en":"Over one hundred circles appeared in a single year.","zh":"單一年份內出現超過一百個圓圈。"},{"en":"Over one hundred circles means more than 100 circles.","zh":"over one hundred circles 指多於100個圓圈。"},{"en":"A teacher may mark over one hundred essays during an exam season.","zh":"老師在考試季可能批改超過一百篇作文。"},{"en":"More than one hundred cases in one year suggests intense activity or reporting.","zh":"一年內超過一百個個案，暗示活動或報告非常集中。"},{"en":"The phrase highlights a large count.","zh":"這個短語突出大量數目。"}],"source":"73 - Crop circles.pdf","sourcePage":17},{"front":"phenomena such as","meaning":"例如……的現象","examples":[{"en":"Phenomena such as strange lights have occurred near crop circles.","zh":"例如奇怪光芒的現象曾在麥田圈附近發生。"},{"en":"Phenomena such as means examples of events or things of that type include.","zh":"phenomena such as 指某類事件或事物的例子包括。"},{"en":"Weather phenomena such as fog and lightning can affect flights.","zh":"例如霧和閃電的天氣現象可以影響航班。"},{"en":"Giving examples helps readers understand what kind of events are being discussed.","zh":"提供例子幫助讀者理解正在討論哪類事件。"},{"en":"The phrase introduces specific examples from a larger category.","zh":"這個短語從較大類別中引入具體例子。"}],"source":"73 - Crop circles.pdf","sourcePage":17},{"front":"the appearance of strange lights","meaning":"奇怪光芒的出現","examples":[{"en":"The appearance of strange lights sometimes occurs near crop circles.","zh":"奇怪光芒的出現有時發生在麥田圈附近。"},{"en":"The appearance of strange lights means strange lights becoming visible.","zh":"appearance of strange lights 指奇怪光芒變得可見。"},{"en":"The appearance of strange lights in a building at night may make neighbours call security.","zh":"晚上大廈中出現奇怪光芒，可能令鄰居致電保安。"},{"en":"When unusual lights appear near a mystery site, people may connect them with the event.","zh":"當異常光芒出現在神秘地點附近，人們可能把它們與事件聯繫起來。"},{"en":"The phrase focuses on lights becoming seen.","zh":"這個短語重點是光芒變得可見。"}],"source":"73 - Crop circles.pdf","sourcePage":18},{"front":"unusual sounds","meaning":"異常聲音","examples":[{"en":"Unusual sounds have been reported around crop circle sites.","zh":"麥田圈地點周圍曾有異常聲音被報告。"},{"en":"Unusual sounds are noises that are strange, unexpected, or hard to identify.","zh":"unusual sounds 指奇怪、意外或難以辨認的聲音。"},{"en":"A teacher may investigate unusual sounds coming from a classroom ceiling.","zh":"老師可能調查課室天花板傳出的異常聲音。"},{"en":"Strange sounds can make a place feel mysterious or unsafe.","zh":"奇怪聲音可以令地方感覺神秘或不安全。"},{"en":"The phrase describes auditory evidence.","zh":"這個短語描述聽覺證據。"}],"source":"73 - Crop circles.pdf","sourcePage":18},{"front":"occur around the sites of","meaning":"發生在……地點周圍","examples":[{"en":"Strange phenomena sometimes occur around the sites of crop circles.","zh":"奇怪現象有時發生在麥田圈地點周圍。"},{"en":"Occur around the sites of something means happen near the places where that thing is found.","zh":"occur around the sites of something 指在發現某物的地點附近發生。"},{"en":"Traffic problems may occur around the sites of popular concerts.","zh":"受歡迎演唱會地點周圍可能發生交通問題。"},{"en":"Events near a site may be studied to see whether they are connected.","zh":"地點附近的事件可能被研究，以判斷是否有關連。"},{"en":"The phrase links nearby happenings with a specific location.","zh":"這個短語把附近發生的事與特定地點連起來。"}],"source":"73 - Crop circles.pdf","sourcePage":18},{"front":"not affected","meaning":"不受影響","examples":[{"en":"Some animals are not affected by the causative forces.","zh":"一些動物不受成因力量影響。"},{"en":"Not affected means not changed, harmed, or influenced by something.","zh":"not affected 指沒有被改變、傷害或影響。"},{"en":"Some students are not affected by noise if they are used to studying in busy places.","zh":"如果學生習慣在繁忙地方溫習，他們可能不受噪音影響。"},{"en":"If animals are not affected, the force may not be harmful to them.","zh":"如果動物不受影響，該力量可能對牠們無害。"},{"en":"The phrase describes absence of impact.","zh":"這個短語描述沒有影響。"}],"source":"73 - Crop circles.pdf","sourcePage":18},{"front":"it has been observed that","meaning":"有人觀察到","examples":[{"en":"It has been observed that birds avoid flying over crop circles.","zh":"有人觀察到鳥會避免飛越麥田圈。"},{"en":"It has been observed that means people have noticed or recorded that something happens.","zh":"it has been observed that 指有人注意到或記錄到某事發生。"},{"en":"It has been observed that students participate more when examples are familiar.","zh":"有人觀察到當例子熟悉時，學生參與度更高。"},{"en":"Observation can provide useful clues, but it still needs careful interpretation.","zh":"觀察可以提供有用線索，但仍需要仔細解讀。"},{"en":"The phrase reports a noticed pattern.","zh":"這個短語報告被注意到的模式。"}],"source":"73 - Crop circles.pdf","sourcePage":18},{"front":"avoid flying over","meaning":"避免飛越","examples":[{"en":"Birds avoid flying over a crop circle formation.","zh":"鳥避免飛越麥田圈圖案。"},{"en":"To avoid flying over something means to choose not to pass above it.","zh":"avoid flying over something 指選擇不從某物上方飛過。"},{"en":"A pilot may avoid flying over a storm cloud for safety.","zh":"飛行員可能為安全避免飛越暴風雲。"},{"en":"Avoidance can suggest that the area seems risky or uncomfortable to the creature or person.","zh":"避開可以暗示該區域對生物或人而言似乎有風險或不舒服。"},{"en":"The phrase describes deliberate or repeated movement away from an overhead path.","zh":"這個短語描述刻意或重複避開上方路徑。"}],"source":"73 - Crop circles.pdf","sourcePage":18},{"front":"use the information in the text","meaning":"使用文中的資料","examples":[{"en":"Students use the information in the text to match each scientist.","zh":"學生使用文中的資料配對每位科學家。"},{"en":"Use the information in the text means answer based on the passage, not outside knowledge.","zh":"use the information in the text 指根據文章作答，而不是根據外部知識。"},{"en":"In reading tests, students should use the information in the text even if they know extra facts.","zh":"在閱讀測驗中，即使學生知道額外事實，也應使用文中的資料。"},{"en":"This instruction prevents guessing and keeps answers evidence-based.","zh":"這個指示防止猜測，並讓答案以證據為基礎。"},{"en":"The phrase tells students where the answer support must come from.","zh":"這個短語告訴學生答案支持必須來自哪裡。"}],"source":"73 - Crop circles.pdf","sourcePage":18},{"front":"match one scientist with","meaning":"將一位科學家與……配對","examples":[{"en":"Students match one scientist with each area of study.","zh":"學生將一位科學家與每個研究範疇配對。"},{"en":"To match one scientist with something means to choose the scientist connected to that item.","zh":"match one scientist with something 指選出與該項目相關的科學家。"},{"en":"In a classroom activity, students may match each inventor with the correct invention.","zh":"在課堂活動中，學生可能把每位發明家與正確發明配對。"},{"en":"Matching tasks require careful reading because names and details may be separated in the text.","zh":"配對題需要仔細閱讀，因為姓名和細節可能分散在文章中。"},{"en":"The phrase describes a pairing task.","zh":"這個短語描述配對任務。"}],"source":"73 - Crop circles.pdf","sourcePage":18},{"front":"each area of study","meaning":"每個研究範疇","examples":[{"en":"The task lists several areas of study.","zh":"任務列出幾個研究範疇。"},{"en":"Each area of study means each topic or field being researched.","zh":"each area of study 指每個被研究的主題或領域。"},{"en":"In science class, areas of study may include plants, weather, electricity, and animals.","zh":"在科學課中，研究範疇可能包括植物、天氣、電力和動物。"},{"en":"Separating areas of study helps students see which researcher worked on which question.","zh":"分開研究範疇幫助學生看出哪位研究者研究哪個問題。"},{"en":"The phrase refers to different research topics.","zh":"這個短語指不同研究主題。"}],"source":"73 - Crop circles.pdf","sourcePage":18},{"front":"observations of light","meaning":"對光芒的觀察","examples":[{"en":"Dr. Mearden’s theory relates to observations of light.","zh":"Mearden 博士的理論與對光芒的觀察有關。"},{"en":"Observations of light are reports or records of visible light seen in a place.","zh":"observations of light 指在某地看見可見光的報告或記錄。"},{"en":"A security camera may provide observations of light moving outside a building at night.","zh":"保安攝影機可能提供晚上建築物外光芒移動的觀察。"},{"en":"Light observations can support theories involving electricity, weather, or aircraft.","zh":"對光的觀察可以支持涉及電、天氣或飛機的理論。"},{"en":"The phrase focuses on what people saw.","zh":"這個短語重點是人們看見了甚麼。"}],"source":"73 - Crop circles.pdf","sourcePage":18},{"front":"in relation to","meaning":"關於；與……有關","examples":[{"en":"The example concerns light in relation to crop circles.","zh":"這個例子關於與麥田圈有關的光芒。"},{"en":"In relation to means connected with or concerning a particular subject.","zh":"in relation to 指與某特定主題相關或關於某事。"},{"en":"A school may hold a meeting in relation to student safety after an accident.","zh":"意外後，學校可能舉行關於學生安全的會議。"},{"en":"The phrase helps show the topic that a detail is connected to.","zh":"這個短語幫助顯示某細節連接到哪個主題。"},{"en":"It is formal and common in academic writing.","zh":"它較正式，常見於學術寫作。"}],"source":"73 - Crop circles.pdf","sourcePage":18},{"front":"changes in the structure of soil","meaning":"土壤結構的變化","examples":[{"en":"Researchers studied changes in the structure of soil within crop circles.","zh":"研究人員研究麥田圈內土壤結構的變化。"},{"en":"Changes in the structure of soil are alterations in how soil particles, moisture, and organisms are arranged.","zh":"changes in the structure of soil 指土壤粒子、水分和生物排列方式的改變。"},{"en":"Garden soil can change in structure if it is packed down by heavy foot traffic.","zh":"如果花園土壤被大量踩踏壓實，其結構可以改變。"},{"en":"Soil structure affects water movement, root growth, and plant health.","zh":"土壤結構影響水分流動、根部生長和植物健康。"},{"en":"The phrase refers to physical and biological changes in soil.","zh":"這個短語指土壤中的物理和生物變化。"}],"source":"73 - Crop circles.pdf","sourcePage":19},{"front":"within crop circles","meaning":"在麥田圈內","examples":[{"en":"Scientists found unusual features within crop circles.","zh":"科學家在麥田圈內發現異常特徵。"},{"en":"Within crop circles means inside the area covered by the crop circle pattern.","zh":"within crop circles 指在麥田圈圖案覆蓋的區域內。"},{"en":"A researcher may collect plant samples within a circle and compare them with samples outside it.","zh":"研究人員可能在圓圈內收集植物樣本，並與外部樣本比較。"},{"en":"Studying what happens inside the pattern helps identify whether that area is different.","zh":"研究圖案內發生的事，有助辨認該區是否不同。"},{"en":"The phrase focuses on the interior of the formation.","zh":"這個短語重點是圖案內部。"}],"source":"73 - Crop circles.pdf","sourcePage":19},{"front":"accelerated growth of seeds","meaning":"種子加速生長","examples":[{"en":"Dr. Levengood studied the accelerated growth of seeds from crop circles.","zh":"Levengood 博士研究來自麥田圈的種子加速生長。"},{"en":"Accelerated growth of seeds means seeds grow faster than usual after being planted.","zh":"accelerated growth of seeds 指種子播種後比平常更快生長。"},{"en":"Gardeners may notice accelerated seed growth if they use rich soil and enough water.","zh":"如果園丁使用肥沃土壤和足夠水分，可能注意到種子加速生長。"},{"en":"Faster seed growth can make researchers ask what condition affected the seeds.","zh":"種子生長較快可以令研究人員詢問有甚麼條件影響了種子。"},{"en":"The phrase describes unusually quick development after sowing.","zh":"這個短語描述播種後異常快速發育。"}],"source":"73 - Crop circles.pdf","sourcePage":19},{"front":"electrical charges in the air","meaning":"空氣中的電荷","examples":[{"en":"Dr. Mearden’s theory involves electrical charges in the air.","zh":"Mearden 博士的理論涉及空氣中的電荷。"},{"en":"Electrical charges in the air are forms of electrical energy present in the atmosphere.","zh":"electrical charges in the air 指大氣中存在的電能形式。"},{"en":"Before a thunderstorm, people may feel the air is charged because of electrical activity.","zh":"雷暴前，人們可能因電活動而感覺空氣帶電。"},{"en":"Electrical charges can be linked to light, movement, or unusual atmospheric effects.","zh":"電荷可能與光、運動或異常大氣效果有關。"},{"en":"The phrase describes an atmospheric electrical condition.","zh":"這個短語描述大氣中的電力狀態。"}],"source":"73 - Crop circles.pdf","sourcePage":19},{"front":"changes in cell structure","meaning":"細胞結構變化","examples":[{"en":"Dr. Levengood studied changes in cell structure of crop circle plants.","zh":"Levengood 博士研究麥田圈植物的細胞結構變化。"},{"en":"Changes in cell structure are alterations in the shape, size, or condition of cells.","zh":"changes in cell structure 指細胞形狀、大小或狀態的改變。"},{"en":"Biology students study changes in cell structure under a microscope after an experiment.","zh":"生物學生在實驗後用顯微鏡研究細胞結構變化。"},{"en":"Cell-structure changes can suggest that plants experienced heat, pressure, or unusual growth conditions.","zh":"細胞結構變化可以暗示植物經歷過熱力、壓力或異常生長條件。"},{"en":"The phrase focuses on microscopic biological differences.","zh":"這個短語重點是微觀生物差異。"}],"source":"73 - Crop circles.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 74":[{"front":"The Cells from Hell","meaning":"來自地獄的細胞","examples":[{"en":"The passage describes dangerous marine microorganisms as “the cells from hell.”","zh":"篇章把危險的海洋微生物形容為「來自地獄的細胞」。"},{"en":"The Cells from Hell is a dramatic phrase for tiny organisms that can cause serious harm.","zh":"「來自地獄的細胞」是一個戲劇化說法，指能造成嚴重傷害的微小生物。"},{"en":"A documentary might call a deadly virus “a cell from hell” if it spreads quickly and harms many people.","zh":"如果一種致命病毒迅速傳播並傷害很多人，紀錄片可能稱它為「地獄細胞」。"},{"en":"The phrase creates fear because something extremely small is shown as extremely dangerous.","zh":"這個短語製造恐懼感，因為極微小的東西被呈現為極危險。"},{"en":"It is not a scientific name, but a vivid description of frightening microorganisms.","zh":"它不是科學名稱，而是對可怕微生物的生動描述。"}],"source":"74 - The cells from hell.pdf","sourcePage":1},{"front":"an international team of biologists","meaning":"一隊國際生物學家團隊","examples":[{"en":"An international team of biologists met to discuss a global crisis.","zh":"一隊國際生物學家團隊會面討論一場全球危機。"},{"en":"An international team of biologists is a group of biology experts from different countries.","zh":"一隊國際生物學家團隊，是來自不同國家的生物學專家組成的小組。"},{"en":"An international team of biologists may study a disease that affects oceans in many regions.","zh":"一隊國際生物學家團隊可能研究影響多個地區海洋的疾病。"},{"en":"When a problem crosses borders, scientists from several countries may need to work together.","zh":"當問題跨越國界，幾個國家的科學家可能需要合作。"},{"en":"This phrase suggests cooperation across nations in scientific research.","zh":"這個短語暗示科學研究中的跨國合作。"}],"source":"74 - The cells from hell.pdf","sourcePage":1},{"front":"meet to discuss","meaning":"會面討論","examples":[{"en":"The biologists met to discuss a global crisis caused by marine microorganisms.","zh":"生物學家會面討論由海洋微生物造成的全球危機。"},{"en":"To meet to discuss something means to gather in order to talk about it seriously.","zh":"會面討論某事，是指聚在一起認真談論它。"},{"en":"Teachers may meet to discuss how to help students who are falling behind.","zh":"老師可能會面討論如何幫助落後的學生。"},{"en":"People meet to discuss a problem when decisions or shared information are needed.","zh":"當需要作決定或分享資訊，人們會會面討論問題。"},{"en":"This phrase shows that the meeting has a clear purpose.","zh":"這個短語顯示會議有清楚目的。"}],"source":"74 - The cells from hell.pdf","sourcePage":1},{"front":"what they believe is","meaning":"他們認為是……的事","examples":[{"en":"They met to discuss what they believe is a global crisis.","zh":"他們會面討論他們認為是一場全球危機的事。"},{"en":"What they believe is means what they think or judge something to be.","zh":"他們認為是某事，是指他們思考或判斷某情況屬於某性質。"},{"en":"Doctors may warn the public about what they believe is a serious health risk.","zh":"醫生可能警告公眾有關他們認為是嚴重健康風險的事。"},{"en":"The phrase shows opinion or expert judgement, not necessarily final proof.","zh":"這個短語顯示意見或專家判斷，而不一定是最終證明。"},{"en":"It is useful when people are presenting a strong but still arguable view.","zh":"當人們提出強烈但仍可討論的觀點時，這個短語很有用。"}],"source":"74 - The cells from hell.pdf","sourcePage":1},{"front":"a global crisis","meaning":"全球危機","examples":[{"en":"The sudden appearance of strange marine microorganisms may be a global crisis.","zh":"奇怪海洋微生物的突然出現可能是一場全球危機。"},{"en":"A global crisis is a serious problem that affects many countries or the whole world.","zh":"全球危機是影響許多國家或全世界的嚴重問題。"},{"en":"Climate change is often discussed as a global crisis because it affects all regions.","zh":"氣候變化常被討論為全球危機，因為它影響所有地區。"},{"en":"A local problem can become a global crisis if it spreads across borders.","zh":"如果本地問題跨越國界擴散，就可能變成全球危機。"},{"en":"This phrase describes a problem too large for one country to solve alone.","zh":"這個短語描述大到不是單一國家能獨自解決的問題。"}],"source":"74 - The cells from hell.pdf","sourcePage":1},{"front":"be caused by","meaning":"由……造成","examples":[{"en":"The crisis was caused by the sudden appearance of strange microorganisms.","zh":"這場危機由奇怪微生物突然出現造成。"},{"en":"To be caused by something means to happen because of that reason.","zh":"由某事造成，是指因該原因而發生。"},{"en":"A school closure may be caused by severe flooding after heavy rain.","zh":"暴雨後嚴重水浸可能造成學校停課。"},{"en":"Knowing what a problem is caused by helps people choose the right solution.","zh":"知道問題由甚麼造成，有助人們選擇正確解決方法。"},{"en":"This phrase connects an effect with its cause.","zh":"這個短語把結果與原因連接起來。"}],"source":"74 - The cells from hell.pdf","sourcePage":1},{"front":"sudden appearance","meaning":"突然出現","examples":[{"en":"The sudden appearance of strange microorganisms alarmed scientists.","zh":"奇怪微生物的突然出現令科學家感到警覺。"},{"en":"A sudden appearance is when something shows up quickly and unexpectedly.","zh":"突然出現，是指某事快速而出乎意料地出現。"},{"en":"The sudden appearance of smoke in a classroom would make everyone leave immediately.","zh":"課室中突然出現煙霧會令所有人立即離開。"},{"en":"Sudden appearances can cause alarm because people have little time to understand them.","zh":"突然出現會令人警覺，因為人們幾乎沒有時間理解情況。"},{"en":"This phrase emphasises surprise and speed.","zh":"這個短語強調驚訝和速度。"}],"source":"74 - The cells from hell.pdf","sourcePage":1},{"front":"strange marine microorganisms","meaning":"奇怪的海洋微生物","examples":[{"en":"Strange marine microorganisms are capable of poisoning fish and people.","zh":"奇怪的海洋微生物有能力毒害魚類和人類。"},{"en":"Strange marine microorganisms are unusual tiny living things found in the sea.","zh":"奇怪的海洋微生物，是在海中發現的不尋常微小生物。"},{"en":"Scientists may collect water samples to identify strange marine microorganisms after fish die.","zh":"魚類死亡後，科學家可能收集水樣本來識別奇怪海洋微生物。"},{"en":"Some marine microorganisms become dangerous when pollution changes their environment.","zh":"當污染改變環境，有些海洋微生物會變得危險。"},{"en":"This phrase refers to very small sea organisms that behave in worrying ways.","zh":"這個短語指行為令人擔憂的微小海洋生物。"}],"source":"74 - The cells from hell.pdf","sourcePage":1},{"front":"be capable of","meaning":"有能力……","examples":[{"en":"Some marine microorganisms are capable of poisoning fish and people.","zh":"有些海洋微生物有能力毒害魚類和人類。"},{"en":"To be capable of doing something means to have the ability to do it.","zh":"有能力做某事，是指具備做該事的能力。"},{"en":"A strong swimmer is capable of crossing the bay safely.","zh":"強壯的游泳者有能力安全橫渡海灣。"},{"en":"Something tiny can still be capable of causing serious damage.","zh":"極微小的東西仍可能有能力造成嚴重損害。"},{"en":"This phrase describes ability or potential, not certainty.","zh":"這個短語描述能力或潛力，而不是必然發生。"}],"source":"74 - The cells from hell.pdf","sourcePage":1},{"front":"poison not just fish but people too","meaning":"不只毒害魚類，也毒害人類","examples":[{"en":"These microorganisms can poison not just fish but people too.","zh":"這些微生物不只會毒害魚類，也會毒害人類。"},{"en":"Poison not just A but B too means harm both groups, not only the first one mentioned.","zh":"不只毒害 A，也毒害 B，是指傷害兩個群體，而不只是先提到的一方。"},{"en":"Dirty water can poison not just animals but people too if it enters drinking supplies.","zh":"如果污水進入飲用水供應，它不只會毒害動物，也會毒害人類。"},{"en":"The phrase stresses that the danger is wider than expected.","zh":"這個短語強調危險比預期更廣。"},{"en":"It is useful when showing that a problem affects more than one target.","zh":"當要顯示問題影響多於一個對象時，這個短語很有用。"}],"source":"74 - The cells from hell.pdf","sourcePage":1},{"front":"in the mid-1980s","meaning":"在二十世紀八十年代中期","examples":[{"en":"In the mid-1980s, fishermen in North Carolina began complaining about fish kills.","zh":"在二十世紀八十年代中期，北卡羅來納州漁民開始投訴魚類大規模死亡。"},{"en":"In the mid-1980s means around the middle years of the 1980s, such as 1984 to 1986.","zh":"在二十世紀八十年代中期，是指 1980 年代中間年份，例如 1984 至 1986 年左右。"},{"en":"In the mid-1980s, many homes still did not have personal computers.","zh":"在二十世紀八十年代中期，許多家庭仍沒有個人電腦。"},{"en":"This phrase gives an approximate historical time.","zh":"這個短語給出大約歷史時間。"},{"en":"It helps readers place events in a specific period.","zh":"它幫助讀者把事件放在特定時期。"}],"source":"74 - The cells from hell.pdf","sourcePage":1},{"front":"fishermen","meaning":"漁民","examples":[{"en":"Fishermen in North Carolina reported mysterious fish kills.","zh":"北卡羅來納州漁民報告神秘魚類大規模死亡。"},{"en":"Fishermen are people who catch fish for work, food, or sport.","zh":"漁民是為工作、食物或運動而捕魚的人。"},{"en":"Fishermen may notice changes in the sea before officials do because they work there daily.","zh":"漁民每天在海上工作，可能比官員更早注意到海洋變化。"},{"en":"If fishermen see many dead fish, they may suspect pollution or disease.","zh":"如果漁民看見大量死魚，可能懷疑污染或疾病。"},{"en":"This word refers to people closely connected with fishing waters.","zh":"這個詞指與捕魚水域密切相關的人。"}],"source":"74 - The cells from hell.pdf","sourcePage":2},{"front":"North Carolina","meaning":"北卡羅來納州","examples":[{"en":"Fishermen in North Carolina complained about mysterious fish kills.","zh":"北卡羅來納州的漁民投訴神秘魚類大規模死亡。"},{"en":"North Carolina is a state on the eastern coast of the United States.","zh":"北卡羅來納州是美國東岸的一個州。"},{"en":"A coastal state like North Carolina depends on healthy rivers, estuaries, and fishing waters.","zh":"像北卡羅來納州這樣的沿海州份依賴健康河流、河口和漁場。"},{"en":"When fish kills happen in a coastal area, local fishing communities may suffer.","zh":"當沿海地區出現魚類大規模死亡，本地漁業社區可能受害。"},{"en":"This phrase gives the location of the early reports.","zh":"這個短語給出早期報告的地點。"}],"source":"74 - The cells from hell.pdf","sourcePage":2},{"front":"on the eastern coast of","meaning":"在……東岸","examples":[{"en":"North Carolina is on the eastern coast of the United States.","zh":"北卡羅來納州位於美國東岸。"},{"en":"On the eastern coast of a place means located along its east-facing shoreline.","zh":"在某地東岸，是指位於該地面向東方的海岸線上。"},{"en":"A city on the eastern coast may depend heavily on ports and fishing.","zh":"位於東岸的城市可能高度依賴港口和漁業。"},{"en":"Coastal locations can be more exposed to marine pollution and algal blooms.","zh":"沿海地點可能更容易受海洋污染和藻華影響。"},{"en":"This phrase describes geographical position.","zh":"這個短語描述地理位置。"}],"source":"74 - The cells from hell.pdf","sourcePage":2},{"front":"begin complaining about","meaning":"開始投訴……","examples":[{"en":"Fishermen began complaining about mysterious fish kills.","zh":"漁民開始投訴神秘魚類大規模死亡。"},{"en":"To begin complaining about something means to start saying that it is a problem.","zh":"開始投訴某事，是指開始說某事是一個問題。"},{"en":"Parents may begin complaining about school lunches if the food becomes unhealthy.","zh":"如果學校午餐變得不健康，家長可能開始投訴。"},{"en":"Complaints often begin when people notice repeated harm or inconvenience.","zh":"當人們注意到反覆傷害或不便，投訴常會開始。"},{"en":"This phrase shows the first public reaction to a problem.","zh":"這個短語顯示公眾對問題的最初反應。"}],"source":"74 - The cells from hell.pdf","sourcePage":2},{"front":"mysterious fish kills","meaning":"神秘的魚類大規模死亡","examples":[{"en":"The fishermen complained about mysterious fish kills.","zh":"漁民投訴神秘的魚類大規模死亡。"},{"en":"Mysterious fish kills are large numbers of fish dying for reasons that are not yet clear.","zh":"神秘的魚類大規模死亡，是指大量魚類因尚不清楚的原因死亡。"},{"en":"A lake with mysterious fish kills may need urgent water testing.","zh":"出現神秘魚類死亡的湖泊可能需要緊急水質檢測。"},{"en":"Such events can damage fishing jobs and warn scientists that the ecosystem is unhealthy.","zh":"這類事件會損害漁業工作，並警告科學家生態系統不健康。"},{"en":"This phrase combines uncertainty with mass death.","zh":"這個短語結合不確定性和大量死亡。"}],"source":"74 - The cells from hell.pdf","sourcePage":2},{"front":"be convinced that","meaning":"深信","examples":[{"en":"The fishermen were convinced that pollution was responsible.","zh":"漁民深信污染是原因。"},{"en":"To be convinced that something is true means to strongly believe it.","zh":"深信某事為真，是指強烈相信它。"},{"en":"A teacher may be convinced that a student is improving after seeing several better essays.","zh":"老師看到幾篇更好的作文後，可能深信學生正在進步。"},{"en":"People become convinced when repeated evidence seems to point in one direction.","zh":"當反覆證據似乎指向同一方向，人們會變得深信不疑。"},{"en":"This phrase expresses strong belief, even before official confirmation.","zh":"這個短語表達強烈信念，即使尚未得到官方確認。"}],"source":"74 - The cells from hell.pdf","sourcePage":2},{"front":"pollution was responsible","meaning":"污染是原因","examples":[{"en":"The fishermen believed that pollution was responsible for the fish kills.","zh":"漁民相信污染是魚類大規模死亡的原因。"},{"en":"Pollution was responsible means pollution caused the problem.","zh":"污染是原因，是指污染造成了問題。"},{"en":"If dirty factory water enters a river, pollution may be responsible for dead fish.","zh":"如果骯髒工廠污水進入河流，污染可能是死魚的原因。"},{"en":"Finding the responsible cause is important because the solution depends on it.","zh":"找出真正原因很重要，因為解決方法取決於它。"},{"en":"This phrase identifies pollution as the suspected cause.","zh":"這個短語指出污染是被懷疑的原因。"}],"source":"74 - The cells from hell.pdf","sourcePage":2},{"front":"nobody would listen","meaning":"沒有人願意聽","examples":[{"en":"The fishermen complained, but nobody would listen.","zh":"漁民投訴，但沒有人願意聽。"},{"en":"Nobody would listen means people ignored the warning or refused to take it seriously.","zh":"沒有人願意聽，是指人們忽視警告或拒絕認真看待。"},{"en":"A student may report bullying, but nobody would listen until another case appears.","zh":"學生可能報告欺凌，但直到另一宗個案出現前都沒有人願意聽。"},{"en":"Ignoring early warnings can allow a problem to become much worse.","zh":"忽視早期警告會令問題變得嚴重得多。"},{"en":"This phrase shows frustration when concerns are dismissed.","zh":"這個短語顯示關注被否定時的挫敗感。"}],"source":"74 - The cells from hell.pdf","sourcePage":2},{"front":"that changed after","meaning":"在……之後情況改變了","examples":[{"en":"That changed after an accident at a research centre.","zh":"在研究中心的一宗意外之後，情況改變了。"},{"en":"That changed after means the situation became different because of a later event.","zh":"在某事之後情況改變了，是指後來事件令情況變得不同。"},{"en":"The school ignored the broken gate, but that changed after a child was injured.","zh":"學校原本忽視壞掉的大閘，但在一名孩子受傷後情況改變了。"},{"en":"A serious incident can make people pay attention to a problem they dismissed before.","zh":"嚴重事件可以令人注意到先前被忽視的問題。"},{"en":"This phrase marks a turning point.","zh":"這個短語標示轉折點。"}],"source":"74 - The cells from hell.pdf","sourcePage":2},{"front":"an accident at a research centre","meaning":"研究中心的一宗意外","examples":[{"en":"An accident at a research centre drew attention to the problem.","zh":"研究中心的一宗意外引起人們對問題的注意。"},{"en":"An accident at a research centre is an unexpected harmful event in a scientific workplace.","zh":"研究中心的一宗意外，是科學工作場所中出乎意料的有害事件。"},{"en":"A chemical spill at a laboratory would be an accident at a research centre.","zh":"實驗室化學品洩漏就是研究中心的一宗意外。"},{"en":"Such accidents can reveal hidden dangers in experiments or samples.","zh":"這類意外可以揭示實驗或樣本中的隱藏危險。"},{"en":"This phrase explains how the issue became impossible to ignore.","zh":"這個短語解釋問題如何變得不能再被忽視。"}],"source":"74 - The cells from hell.pdf","sourcePage":2},{"front":"tank after tank of fish","meaning":"一缸又一缸的魚","examples":[{"en":"Tank after tank of fish suddenly died at the research centre.","zh":"研究中心一缸又一缸的魚突然死亡。"},{"en":"Tank after tank of fish means many tanks of fish, one after another.","zh":"一缸又一缸的魚，是指很多魚缸中的魚接連出事。"},{"en":"If tank after tank of fish dies in a laboratory, researchers know the problem is serious.","zh":"如果實驗室一缸又一缸的魚死亡，研究人員就知道問題嚴重。"},{"en":"Repeated deaths across many tanks suggest a shared cause in the water or environment.","zh":"許多魚缸反覆死亡，暗示水質或環境中有共同原因。"},{"en":"This phrase emphasises repeated and widespread loss.","zh":"這個短語強調反覆而廣泛的損失。"}],"source":"74 - The cells from hell.pdf","sourcePage":2},{"front":"suddenly died","meaning":"突然死亡","examples":[{"en":"Tank after tank of fish suddenly died.","zh":"一缸又一缸的魚突然死亡。"},{"en":"Suddenly died means died quickly and unexpectedly.","zh":"突然死亡，是指快速且出乎意料地死亡。"},{"en":"If several plants suddenly die after watering, the soil or water may be contaminated.","zh":"如果幾盆植物澆水後突然死亡，泥土或水可能受污染。"},{"en":"Sudden death in many animals can signal poison, disease, or environmental change.","zh":"多隻動物突然死亡可能顯示有毒物、疾病或環境改變。"},{"en":"This phrase stresses shock and lack of warning.","zh":"這個短語強調震驚和沒有預警。"}],"source":"74 - The cells from hell.pdf","sourcePage":3},{"front":"spot an unknown microorganism","meaning":"發現一種未知微生物","examples":[{"en":"Researchers spotted an unknown microorganism in the water.","zh":"研究人員在水中發現一種未知微生物。"},{"en":"To spot an unknown microorganism means to notice a tiny organism that has not been identified.","zh":"發現一種未知微生物，是指注意到一種尚未被識別的微小生物。"},{"en":"A scientist may spot an unknown microorganism under a microscope during water testing.","zh":"科學家在檢測水質時，可能在顯微鏡下發現未知微生物。"},{"en":"Discovering an unknown organism can open a new investigation.","zh":"發現未知生物可以展開新的調查。"},{"en":"This phrase combines observation with scientific uncertainty.","zh":"這個短語結合觀察和科學不確定性。"}],"source":"74 - The cells from hell.pdf","sourcePage":3},{"front":"unknown microorganism","meaning":"未知微生物","examples":[{"en":"An unknown microorganism was found in the water.","zh":"水中發現了一種未知微生物。"},{"en":"An unknown microorganism is a tiny living thing that scientists have not yet identified.","zh":"未知微生物是科學家尚未識別的微小生物。"},{"en":"A hospital may investigate an unknown microorganism if patients show unusual symptoms.","zh":"如果病人出現不尋常症狀，醫院可能調查未知微生物。"},{"en":"Unknown microorganisms can be harmless, useful, or dangerous depending on what they do.","zh":"未知微生物可能無害、有用或危險，取決於其行為。"},{"en":"This phrase shows that the organism is both tiny and not yet understood.","zh":"這個短語顯示該生物既微小又尚未被理解。"}],"source":"74 - The cells from hell.pdf","sourcePage":3},{"front":"be later named","meaning":"後來被命名為","examples":[{"en":"The unknown microorganism was later named Pfiesteria.","zh":"這種未知微生物後來被命名為 Pfiesteria。"},{"en":"To be later named means to receive a name after further study or discovery.","zh":"後來被命名為，是指在進一步研究或發現後得到名稱。"},{"en":"A newly found comet may be later named after the scientist who discovered it.","zh":"新發現的彗星後來可能以發現它的科學家命名。"},{"en":"Scientists often study an organism first and name it later.","zh":"科學家常先研究生物，之後才為它命名。"},{"en":"This phrase describes naming after the initial discovery.","zh":"這個短語描述初次發現之後的命名。"}],"source":"74 - The cells from hell.pdf","sourcePage":3},{"front":"Pfiesteria","meaning":"Pfiesteria（一種藻類微生物）","examples":[{"en":"Pfiesteria was discovered after fish died in research tanks.","zh":"Pfiesteria 是在研究水缸中的魚死亡後被發現的。"},{"en":"Pfiesteria is a harmful marine microorganism linked to fish kills and toxins.","zh":"Pfiesteria 是一種有害海洋微生物，與魚類大規模死亡和毒素有關。"},{"en":"Scientists study Pfiesteria by observing how it behaves near fish.","zh":"科學家透過觀察 Pfiesteria 在魚附近的行為來研究它。"},{"en":"Pfiesteria became alarming because it could change form and attack prey.","zh":"Pfiesteria 令人警覺，因為它能改變形態並攻擊獵物。"},{"en":"This name refers to a specific dangerous microorganism in the passage.","zh":"這個名稱指篇章中的一種特定危險微生物。"}],"source":"74 - The cells from hell.pdf","sourcePage":3},{"front":"belong to","meaning":"屬於","examples":[{"en":"Pfiesteria belongs to a prehistoric group of algae.","zh":"Pfiesteria 屬於一個史前藻類群。"},{"en":"To belong to a group means to be a member or part of that category.","zh":"屬於某群體，是指成為該類別的成員或部分。"},{"en":"Whales belong to mammals, not fish, because they breathe air and feed milk to their young.","zh":"鯨魚屬於哺乳類，而不是魚類，因為牠們呼吸空氣並用乳汁餵幼崽。"},{"en":"Classifying organisms helps scientists understand their features and behaviour.","zh":"把生物分類幫助科學家理解其特徵和行為。"},{"en":"This phrase shows scientific grouping.","zh":"這個短語顯示科學分類。"}],"source":"74 - The cells from hell.pdf","sourcePage":3},{"front":"a prehistoric group of algae","meaning":"史前藻類群","examples":[{"en":"Pfiesteria belongs to a prehistoric group of algae.","zh":"Pfiesteria 屬於一個史前藻類群。"},{"en":"A prehistoric group of algae is a very ancient type of simple aquatic organism.","zh":"史前藻類群是非常古老的簡單水生生物類別。"},{"en":"Some prehistoric organisms still exist today in forms that changed little over time.","zh":"有些史前生物至今仍存在，形態隨時間變化不大。"},{"en":"Knowing that an organism is ancient can help scientists trace its evolutionary features.","zh":"知道某生物很古老，有助科學家追溯其演化特徵。"},{"en":"This phrase links Pfiesteria to an old biological lineage.","zh":"這個短語把 Pfiesteria 與古老生物譜系連接起來。"}],"source":"74 - The cells from hell.pdf","sourcePage":3},{"front":"part plant, part animal","meaning":"半植物半動物","examples":[{"en":"These algae are part plant, part animal.","zh":"這些藻類半植物半動物。"},{"en":"Part plant, part animal means having features of both plants and animals.","zh":"半植物半動物，是指同時具有植物和動物特徵。"},{"en":"A microorganism may act like a plant by photosynthesising and like an animal by hunting.","zh":"微生物可能透過光合作用表現得像植物，又透過獵捕表現得像動物。"},{"en":"Mixed features can make an organism hard to classify and predict.","zh":"混合特徵會令生物難以分類和預測。"},{"en":"This phrase shows that the organism does not fit simple categories.","zh":"這個短語顯示該生物不符合簡單類別。"}],"source":"74 - The cells from hell.pdf","sourcePage":3},{"front":"dinoflagellates","meaning":"甲藻；雙鞭毛藻","examples":[{"en":"Dinoflagellates move through water using tiny flagella.","zh":"甲藻利用細小鞭毛在水中移動。"},{"en":"Dinoflagellates are microscopic algae-like organisms often found in water.","zh":"甲藻是常見於水中的微小類藻生物。"},{"en":"Scientists may study dinoflagellates when investigating harmful algal blooms.","zh":"科學家調查有害藻華時，可能研究甲藻。"},{"en":"Some dinoflagellates can produce toxins that affect fish, shellfish, or people.","zh":"有些甲藻能產生影響魚類、貝類或人類的毒素。"},{"en":"This word names a group of tiny organisms with whip-like structures.","zh":"這個詞命名一類具有鞭狀結構的微小生物。"}],"source":"74 - The cells from hell.pdf","sourcePage":3},{"front":"be called something after","meaning":"因……而被稱為","examples":[{"en":"They are called dinoflagellates after their tiny whips or flagella.","zh":"牠們因細小鞭狀物或鞭毛而被稱為 dinoflagellates。"},{"en":"To be called something after a feature means to receive a name because of that feature.","zh":"因某特徵而被稱為某物，是指因該特徵得到名稱。"},{"en":"A red panda is called that after its reddish fur.","zh":"小熊貓因其紅色皮毛而得名。"},{"en":"Scientific names often come from visible body parts or behaviour.","zh":"科學名稱常來自可見身體部分或行為。"},{"en":"This phrase explains the reason behind a name.","zh":"這個短語解釋名稱背後原因。"}],"source":"74 - The cells from hell.pdf","sourcePage":3},{"front":"tiny whips","meaning":"細小鞭狀物","examples":[{"en":"Dinoflagellates are named after the tiny whips that propel them.","zh":"甲藻因推動牠們移動的細小鞭狀物而得名。"},{"en":"Tiny whips are very small whip-like structures used for movement.","zh":"細小鞭狀物是用於移動的非常小的鞭形結構。"},{"en":"Under a microscope, tiny whips on a microorganism may beat quickly through water.","zh":"在顯微鏡下，微生物上的細小鞭狀物可能在水中快速擺動。"},{"en":"These structures help small organisms move even though they have no legs or fins.","zh":"這些結構幫助沒有腳或鰭的小生物移動。"},{"en":"This phrase gives a simple image of flagella.","zh":"這個短語提供鞭毛的簡單形象。"}],"source":"74 - The cells from hell.pdf","sourcePage":3},{"front":"flagella","meaning":"鞭毛","examples":[{"en":"Flagella propel dinoflagellates through the water.","zh":"鞭毛推動甲藻在水中前進。"},{"en":"Flagella are tiny hair-like or whip-like structures that help cells move.","zh":"鞭毛是幫助細胞移動的細小毛狀或鞭狀結構。"},{"en":"Some bacteria use flagella to swim through liquid.","zh":"有些細菌用鞭毛在液體中游動。"},{"en":"Without flagella, certain microorganisms would move much less effectively.","zh":"沒有鞭毛，某些微生物的移動效率會低得多。"},{"en":"This word refers to movement structures on tiny organisms.","zh":"這個詞指微小生物上的移動結構。"}],"source":"74 - The cells from hell.pdf","sourcePage":4},{"front":"propel something through","meaning":"推動……穿過","examples":[{"en":"Flagella propel these microorganisms through the water.","zh":"鞭毛推動這些微生物穿過水體。"},{"en":"To propel something through a space means to push or drive it forward through that space.","zh":"推動某物穿過某空間，是指使它在該空間中向前移動。"},{"en":"A motor propels a boat through the harbour.","zh":"摩打推動小船穿過港口。"},{"en":"Movement structures let microorganisms reach food, escape danger, or hunt prey.","zh":"移動結構讓微生物到達食物、逃避危險或獵捕獵物。"},{"en":"This phrase describes forceful movement from one place to another.","zh":"這個短語描述從一處到另一處的推進移動。"}],"source":"74 - The cells from hell.pdf","sourcePage":4},{"front":"magnified a thousand times","meaning":"放大一千倍","examples":[{"en":"Magnified a thousand times, they look strange and beautiful.","zh":"放大一千倍後，牠們看起來奇異而美麗。"},{"en":"Magnified a thousand times means made to appear one thousand times larger.","zh":"放大一千倍，是指使某物看起來大一千倍。"},{"en":"A tiny insect wing may reveal delicate patterns when magnified a thousand times.","zh":"細小昆蟲翅膀放大一千倍後，可能顯示精細圖案。"},{"en":"Magnification helps scientists see details invisible to the naked eye.","zh":"放大有助科學家看見肉眼看不到的細節。"},{"en":"This phrase explains how tiny organisms become visible.","zh":"這個短語解釋微小生物如何變得可見。"}],"source":"74 - The cells from hell.pdf","sourcePage":4},{"front":"strange and beautiful creatures","meaning":"奇異而美麗的生物","examples":[{"en":"Dinoflagellates are some of the strangest and most beautiful creatures in the sea.","zh":"甲藻是海中一些最奇異而美麗的生物。"},{"en":"Strange and beautiful creatures are living things that look unusual but visually impressive.","zh":"奇異而美麗的生物，是外形不尋常但視覺上令人印象深刻的生物。"},{"en":"Deep-sea animals often appear strange and beautiful because their shapes and colours are unfamiliar.","zh":"深海動物常顯得奇異而美麗，因為其形狀和顏色令人陌生。"},{"en":"Something can be beautiful to look at but dangerous in its effects.","zh":"某物外表可以美麗，但效果可能危險。"},{"en":"This phrase combines wonder with uncertainty.","zh":"這個短語結合驚奇與不確定感。"}],"source":"74 - The cells from hell.pdf","sourcePage":4},{"front":"at the bottom of the food chain","meaning":"在食物鏈底層","examples":[{"en":"These organisms are at the bottom of the food chain.","zh":"這些生物位於食物鏈底層。"},{"en":"At the bottom of the food chain means forming the basic food source for larger organisms.","zh":"在食物鏈底層，是指構成較大型生物的基本食物來源。"},{"en":"Tiny ocean plants are at the bottom of the food chain because many small animals eat them.","zh":"微小海洋植物位於食物鏈底層，因為許多小動物吃它們。"},{"en":"If organisms at the bottom are poisoned, the effects can move upward through the ecosystem.","zh":"如果底層生物中毒，影響可以沿生態系統向上傳遞。"},{"en":"This phrase describes a low but essential ecological position.","zh":"這個短語描述低層但重要的生態位置。"}],"source":"74 - The cells from hell.pdf","sourcePage":4},{"front":"the food chain","meaning":"食物鏈","examples":[{"en":"Small marine organisms are often at the bottom of the food chain.","zh":"小型海洋生物常位於食物鏈底層。"},{"en":"The food chain is the order in which living things eat and are eaten by one another.","zh":"食物鏈是生物之間互相捕食和被捕食的次序。"},{"en":"Grass, insects, birds, and foxes can form a simple food chain.","zh":"草、昆蟲、鳥和狐狸可以形成簡單食物鏈。"},{"en":"A change at one level of the food chain can affect many other animals.","zh":"食物鏈某一層的改變可以影響許多其他動物。"},{"en":"This phrase explains feeding relationships in nature.","zh":"這個短語解釋自然界中的取食關係。"}],"source":"74 - The cells from hell.pdf","sourcePage":4},{"front":"deter fish from swallowing them","meaning":"阻止魚類吞食牠們","examples":[{"en":"Some algae have evolved toxins to deter fish from swallowing them.","zh":"有些藻類進化出毒素，以阻止魚類吞食牠們。"},{"en":"To deter fish from swallowing them means to stop fish from eating them by making it risky or unpleasant.","zh":"阻止魚類吞食牠們，是指透過令吞食變危險或不愉快來阻止魚吃掉牠們。"},{"en":"Bitter taste can deter children from swallowing unsafe medicine by mistake.","zh":"苦味可以阻止兒童誤吞不安全藥物。"},{"en":"Defensive chemicals protect small organisms from predators.","zh":"防禦性化學物保護小型生物免受捕食者傷害。"},{"en":"This phrase shows how toxins can function as protection.","zh":"這個短語顯示毒素如何作為保護。"}],"source":"74 - The cells from hell.pdf","sourcePage":4},{"front":"evolve powerful toxins","meaning":"進化出強力毒素","examples":[{"en":"Some dinoflagellates have evolved powerful toxins.","zh":"有些甲藻已進化出強力毒素。"},{"en":"To evolve powerful toxins means to develop strong poisonous chemicals over time through evolution.","zh":"進化出強力毒素，是指透過演化逐漸發展出強烈有毒化學物。"},{"en":"Some plants evolve toxins to stop insects from eating their leaves.","zh":"有些植物進化出毒素，以阻止昆蟲吃葉子。"},{"en":"When predators are common, defensive toxins can help a species survive.","zh":"當捕食者常見，防禦毒素可以幫助物種生存。"},{"en":"This phrase links biological change with protection or attack.","zh":"這個短語把生物變化與保護或攻擊連接起來。"}],"source":"74 - The cells from hell.pdf","sourcePage":4},{"front":"powerful toxins","meaning":"強力毒素","examples":[{"en":"Powerful toxins protect some algae from being eaten.","zh":"強力毒素保護某些藻類免被吃掉。"},{"en":"Powerful toxins are strong poisons that can harm or kill living things.","zh":"強力毒素是能傷害或殺死生物的強烈毒物。"},{"en":"A poisonous mushroom may contain powerful toxins that damage the liver.","zh":"有毒蘑菇可能含有會損害肝臟的強力毒素。"},{"en":"Toxins can protect an organism, but they can also harm other animals in the ecosystem.","zh":"毒素可以保護一種生物，但也可能傷害生態系統中的其他動物。"},{"en":"This phrase describes chemicals with serious biological effects.","zh":"這個短語描述具有嚴重生物影響的化學物。"}],"source":"74 - The cells from hell.pdf","sourcePage":4},{"front":"as the researchers were to discover","meaning":"正如研究人員後來發現","examples":[{"en":"As the researchers were to discover, Pfiesteria actively hunts fish.","zh":"正如研究人員後來發現，Pfiesteria 會主動獵捕魚類。"},{"en":"As someone was to discover means as they later found out.","zh":"正如某人後來發現，是指他們之後才知道。"},{"en":"As the teacher was to discover, the quiet student had already solved the hardest problem.","zh":"正如老師後來發現，那位安靜學生已經解出了最難問題。"},{"en":"This phrase creates suspense because the reader knows a discovery is coming.","zh":"這個短語製造懸念，因為讀者知道發現即將出現。"},{"en":"It is often used when later information changes the earlier understanding.","zh":"當後來資訊改變早前理解時，常會使用這個短語。"}],"source":"74 - The cells from hell.pdf","sourcePage":4},{"front":"discourage fish","meaning":"阻嚇魚類","examples":[{"en":"Pfiesteria does not just discourage fish from eating it.","zh":"Pfiesteria 不只是阻嚇魚類吃掉它。"},{"en":"To discourage fish means to make fish less likely to do something, such as eat an organism.","zh":"阻嚇魚類，是指令魚較不可能做某事，例如吃某種生物。"},{"en":"A bad smell can discourage animals from eating spoiled food.","zh":"難聞氣味可以阻嚇動物吃變壞食物。"},{"en":"Defensive toxins discourage predators by making the prey dangerous or unpleasant.","zh":"防禦毒素透過令獵物危險或不好吃來阻嚇捕食者。"},{"en":"This phrase describes prevention, not direct attack.","zh":"這個短語描述防止，而不是直接攻擊。"}],"source":"74 - The cells from hell.pdf","sourcePage":4},{"front":"actively hunt","meaning":"主動獵捕","examples":[{"en":"Pfiesteria actively hunts fish and then eats them.","zh":"Pfiesteria 主動獵捕魚類，然後吃掉牠們。"},{"en":"To actively hunt means to search for and attack prey, not just wait passively.","zh":"主動獵捕，是指尋找並攻擊獵物，而不是被動等待。"},{"en":"A cat may actively hunt insects in a garden.","zh":"貓可能在花園中主動獵捕昆蟲。"},{"en":"Active hunting makes Pfiesteria more frightening because it behaves like a predator.","zh":"主動獵捕令 Pfiesteria 更可怕，因為它表現得像捕食者。"},{"en":"This phrase shows deliberate movement toward prey.","zh":"這個短語顯示朝獵物作出的有意移動。"}],"source":"74 - The cells from hell.pdf","sourcePage":5},{"front":"preferred foods","meaning":"偏好的食物","examples":[{"en":"Fish are one of Pfiesteria’s preferred foods.","zh":"魚類是 Pfiesteria 偏好的食物之一。"},{"en":"Preferred foods are foods that an organism especially likes or chooses often.","zh":"偏好的食物，是某生物特別喜歡或經常選擇的食物。"},{"en":"A child’s preferred foods may be noodles, fruit, and chicken wings.","zh":"孩子偏好的食物可能是麵、果物和雞翼。"},{"en":"Knowing an animal’s preferred foods helps scientists understand its behaviour.","zh":"知道動物偏好的食物，有助科學家理解其行為。"},{"en":"This phrase describes food choice, not just what an organism can eat.","zh":"這個短語描述食物選擇，而不只是能吃甚麼。"}],"source":"74 - The cells from hell.pdf","sourcePage":5},{"front":"one of the intriguing things about","meaning":"……其中一個有趣之處","examples":[{"en":"One of the intriguing things about Pfiesteria is its wide diet.","zh":"Pfiesteria 其中一個有趣之處是其食性很廣。"},{"en":"One of the intriguing things about something means one of its interesting or puzzling features.","zh":"某事其中一個有趣之處，是指其中一個令人感興趣或困惑的特徵。"},{"en":"One of the intriguing things about language is how quickly slang changes.","zh":"語言其中一個有趣之處，是俚語改變得很快。"},{"en":"Scientists use this phrase when a feature makes them want to investigate further.","zh":"當某特徵令人想進一步研究，科學家會使用這個短語。"},{"en":"It points to a detail that is unusual enough to attract attention.","zh":"它指出一個不尋常到足以吸引注意的細節。"}],"source":"74 - The cells from hell.pdf","sourcePage":5},{"front":"from bacteria to dead plant and animal remains","meaning":"從細菌到動植物殘骸","examples":[{"en":"Pfiesteria eats everything from bacteria to dead plant and animal remains.","zh":"Pfiesteria 吃各種東西，從細菌到死去動植物的殘骸。"},{"en":"From A to B means covering a wide range between two extremes.","zh":"從 A 到 B，是指涵蓋兩個極端之間的廣泛範圍。"},{"en":"A school library may have books from picture books to advanced science texts.","zh":"學校圖書館可能有從圖畫書到高階科學書的各類書籍。"},{"en":"A wide diet can help an organism survive in many conditions.","zh":"廣泛食性可以幫助生物在多種環境中生存。"},{"en":"This phrase shows the range of things Pfiesteria can consume.","zh":"這個短語顯示 Pfiesteria 能吃的東西範圍。"}],"source":"74 - The cells from hell.pdf","sourcePage":5},{"front":"dead plant and animal remains","meaning":"死去動植物的殘骸","examples":[{"en":"Pfiesteria can feed on dead plant and animal remains.","zh":"Pfiesteria 可以以死去動植物的殘骸為食。"},{"en":"Dead plant and animal remains are the leftover parts of organisms after they die.","zh":"死去動植物的殘骸，是生物死亡後留下的部分。"},{"en":"Fallen leaves and dead insects are common plant and animal remains in a garden.","zh":"落葉和死昆蟲是花園中常見的動植物殘骸。"},{"en":"Organisms that feed on remains help recycle nutrients in ecosystems.","zh":"以殘骸為食的生物有助在生態系統中循環養分。"},{"en":"This phrase refers to decaying biological material.","zh":"這個短語指正在腐爛的生物材料。"}],"source":"74 - The cells from hell.pdf","sourcePage":5},{"front":"all the way up to","meaning":"一直到……","examples":[{"en":"Its food ranges from bacteria all the way up to mammalian tissues.","zh":"它的食物範圍從細菌一直到哺乳類動物組織。"},{"en":"All the way up to means extending as far as a much larger or more advanced example.","zh":"一直到某物，是指延伸至更大或更高階的例子。"},{"en":"A reading course may include texts from simple notices all the way up to academic articles.","zh":"閱讀課程可能包括從簡單告示一直到學術文章的文本。"},{"en":"The phrase stresses that the range is surprisingly wide.","zh":"這個短語強調範圍出奇地廣。"},{"en":"It shows that Pfiesteria’s diet includes far more than tiny organisms.","zh":"它顯示 Pfiesteria 的食性遠不止微小生物。"}],"source":"74 - The cells from hell.pdf","sourcePage":5},{"front":"mammalian tissues","meaning":"哺乳類動物組織","examples":[{"en":"Pfiesteria can even consume mammalian tissues.","zh":"Pfiesteria 甚至可以消耗哺乳類動物組織。"},{"en":"Mammalian tissues are body materials from mammals, such as skin, muscle, or organs.","zh":"哺乳類動物組織是來自哺乳類的身體材料，例如皮膚、肌肉或器官。"},{"en":"Doctors may examine mammalian tissues under a microscope in medical research.","zh":"醫生可能在醫學研究中用顯微鏡檢查哺乳類動物組織。"},{"en":"If a microorganism can consume mammalian tissues, it may also threaten humans or other mammals.","zh":"如果微生物能消耗哺乳類組織，它也可能威脅人類或其他哺乳類。"},{"en":"This phrase refers to body tissue from warm-blooded animals that feed milk to young.","zh":"這個短語指來自會哺乳幼崽的溫血動物身體組織。"}],"source":"74 - The cells from hell.pdf","sourcePage":5},{"front":"span the entire food web","meaning":"橫跨整個食物網","examples":[{"en":"Its food spans the entire food web of an estuary.","zh":"它的食物橫跨河口的整個食物網。"},{"en":"To span the entire food web means to reach across many feeding levels in an ecosystem.","zh":"橫跨整個食物網，是指觸及生態系統中許多取食層次。"},{"en":"A pollutant can span the food web if it moves from tiny plants to fish and birds.","zh":"如果污染物從微小植物轉移到魚和鳥身上，它就可能橫跨食物網。"},{"en":"When one organism affects many levels, the whole ecosystem may change.","zh":"當一種生物影響許多層次，整個生態系統都可能改變。"},{"en":"This phrase shows very broad ecological impact.","zh":"這個短語顯示非常廣泛的生態影響。"}],"source":"74 - The cells from hell.pdf","sourcePage":5},{"front":"the food web","meaning":"食物網","examples":[{"en":"Pfiesteria’s diet covers much of the food web.","zh":"Pfiesteria 的食性涵蓋食物網的大部分。"},{"en":"The food web is the network of feeding relationships among organisms in an ecosystem.","zh":"食物網是生態系統中生物之間的取食關係網絡。"},{"en":"In a pond food web, algae may feed insects, insects feed fish, and fish feed birds.","zh":"在池塘食物網中，藻類可能供昆蟲取食，昆蟲供魚類取食，魚類供鳥類取食。"},{"en":"Food webs are more complex than simple food chains because many organisms eat several things.","zh":"食物網比簡單食物鏈複雜，因為許多生物吃幾種東西。"},{"en":"This phrase describes connected feeding relationships.","zh":"這個短語描述互相連接的取食關係。"}],"source":"74 - The cells from hell.pdf","sourcePage":5},{"front":"an estuary","meaning":"河口","examples":[{"en":"Pfiesteria can affect the entire food web of an estuary.","zh":"Pfiesteria 可以影響河口的整個食物網。"},{"en":"An estuary is a coastal area where river water mixes with seawater.","zh":"河口是河水與海水混合的沿海地區。"},{"en":"Many fish and birds feed in an estuary because it is rich in nutrients.","zh":"許多魚和鳥在河口覓食，因為那裡養分豐富。"},{"en":"Pollution in an estuary can spread through many organisms that live and feed there.","zh":"河口污染可以透過生活和覓食於該處的多種生物擴散。"},{"en":"This word refers to an important transition zone between river and sea.","zh":"這個詞指河流與海洋之間的重要過渡區。"}],"source":"74 - The cells from hell.pdf","sourcePage":5},{"front":"gradually realise","meaning":"逐漸意識到","examples":[{"en":"The researchers gradually realised that nothing in the water was safe.","zh":"研究人員逐漸意識到水中沒有東西是安全的。"},{"en":"To gradually realise something means to understand it slowly over time.","zh":"逐漸意識到某事，是指隨時間慢慢理解它。"},{"en":"A teacher may gradually realise that a quiet student is struggling with reading.","zh":"老師可能逐漸意識到一名安靜學生在閱讀上有困難。"},{"en":"Repeated evidence can make people slowly change their understanding.","zh":"反覆證據會令人慢慢改變理解。"},{"en":"This phrase shows discovery as a process, not a sudden moment.","zh":"這個短語顯示發現是一個過程，而不是突然一刻。"}],"source":"74 - The cells from hell.pdf","sourcePage":5},{"front":"nothing was safe from","meaning":"沒有東西能避開……","examples":[{"en":"Nothing in the water was safe from Pfiesteria.","zh":"水中沒有東西能避開 Pfiesteria。"},{"en":"Nothing was safe from something means everything could be harmed by it.","zh":"沒有東西能避開某物，是指所有東西都可能被它傷害。"},{"en":"During the flood, nothing stored on the ground floor was safe from the water.","zh":"水浸期間，放在地下樓層的東西沒有一樣能避開洪水。"},{"en":"If no organism is safe from a predator, the ecosystem may be seriously affected.","zh":"如果沒有生物能避開捕食者，生態系統可能受嚴重影響。"},{"en":"This phrase stresses total vulnerability.","zh":"這個短語強調完全脆弱。"}],"source":"74 - The cells from hell.pdf","sourcePage":6},{"front":"harm humans","meaning":"傷害人類","examples":[{"en":"Pfiesteria could harm humans too.","zh":"Pfiesteria 也可能傷害人類。"},{"en":"To harm humans means to injure, poison, or damage people’s health.","zh":"傷害人類，是指損傷、毒害或損害人的健康。"},{"en":"Polluted drinking water can harm humans by causing stomach illness.","zh":"受污染飲用水可以透過引起腸胃病來傷害人類。"},{"en":"Scientists become especially concerned when an environmental threat can harm humans.","zh":"當環境威脅可能傷害人類，科學家會尤其關注。"},{"en":"This phrase shows that the danger is not limited to animals.","zh":"這個短語顯示危險不只限於動物。"}],"source":"74 - The cells from hell.pdf","sourcePage":6},{"front":"misdirected air-conditioning duct","meaning":"安裝方向錯誤的冷氣管道","examples":[{"en":"A misdirected air-conditioning duct nearly killed one researcher.","zh":"一條安裝方向錯誤的冷氣管道差點殺死一名研究人員。"},{"en":"A misdirected air-conditioning duct is an air pipe that sends air in the wrong direction.","zh":"安裝方向錯誤的冷氣管道，是把空氣送往錯誤方向的空氣管道。"},{"en":"A misdirected duct in a laboratory could carry dangerous fumes into an office.","zh":"實驗室中方向錯誤的管道可能把危險氣體送入辦公室。"},{"en":"Wrong airflow can spread toxins or chemicals to places people think are safe.","zh":"錯誤氣流可以把毒素或化學物擴散到人們以為安全的地方。"},{"en":"This phrase shows how a small building fault can become dangerous.","zh":"這個短語顯示小型建築失誤如何變成危險。"}],"source":"74 - The cells from hell.pdf","sourcePage":6},{"front":"a room containing the toxins","meaning":"含有毒素的房間","examples":[{"en":"The air-conditioning duct came from a room containing the toxins.","zh":"冷氣管道來自一間含有毒素的房間。"},{"en":"A room containing the toxins is a room where poisonous substances are present.","zh":"含有毒素的房間，是存在有毒物質的房間。"},{"en":"Workers should not enter a room containing toxic gas without protective equipment.","zh":"工人不應在沒有防護設備下進入含有有毒氣體的房間。"},{"en":"Air from such a room can become dangerous if it spreads to other areas.","zh":"如果這類房間的空氣擴散到其他區域，就會變得危險。"},{"en":"This phrase explains the source of exposure.","zh":"這個短語解釋暴露來源。"}],"source":"74 - The cells from hell.pdf","sourcePage":6},{"front":"nearly killed","meaning":"差點殺死","examples":[{"en":"The toxins nearly killed one of the researchers.","zh":"這些毒素差點殺死其中一名研究人員。"},{"en":"Nearly killed means almost caused someone to die.","zh":"差點殺死，是指幾乎導致某人死亡。"},{"en":"A severe allergic reaction nearly killed the patient before doctors treated him.","zh":"嚴重過敏反應在醫生治療前差點殺死病人。"},{"en":"When an exposure nearly kills someone, safety rules must be reviewed immediately.","zh":"當一次暴露差點致命，安全規則必須立即檢討。"},{"en":"This phrase shows extreme danger without actual death.","zh":"這個短語顯示極端危險，但尚未真正死亡。"}],"source":"74 - The cells from hell.pdf","sourcePage":6},{"front":"suffer a host of symptoms","meaning":"出現大量症狀","examples":[{"en":"The researcher suffered a host of symptoms after exposure to the toxins.","zh":"研究人員接觸毒素後出現大量症狀。"},{"en":"To suffer a host of symptoms means to experience many different signs of illness.","zh":"出現大量症狀，是指經歷許多不同病徵。"},{"en":"After food poisoning, a person may suffer a host of symptoms such as fever, vomiting, and weakness.","zh":"食物中毒後，一個人可能出現發燒、嘔吐和虛弱等大量症狀。"},{"en":"Many symptoms at once can make diagnosis difficult and frightening.","zh":"多種症狀同時出現會令診斷困難且令人害怕。"},{"en":"This phrase emphasises the number and variety of health problems.","zh":"這個短語強調健康問題的數量和多樣性。"}],"source":"74 - The cells from hell.pdf","sourcePage":6},{"front":"a host of symptoms","meaning":"多種症狀","examples":[{"en":"The toxins caused a host of symptoms.","zh":"這些毒素造成多種症狀。"},{"en":"A host of symptoms means many symptoms appearing together or over a short period.","zh":"多種症狀，是指許多病徵同時或在短時間內出現。"},{"en":"A flu patient may have a host of symptoms, including cough, headache, and body aches.","zh":"流感病人可能有多種症狀，包括咳嗽、頭痛和全身酸痛。"},{"en":"A host of symptoms can show that more than one body system is affected.","zh":"多種症狀可以顯示不止一個身體系統受到影響。"},{"en":"This phrase is stronger than saying “a few symptoms.”","zh":"這個短語比「幾個症狀」更強。"}],"source":"74 - The cells from hell.pdf","sourcePage":6},{"front":"ranging from … to …","meaning":"從……到……不等","examples":[{"en":"His symptoms ranged from profuse sweating to memory loss.","zh":"他的症狀從大量出汗到記憶力喪失不等。"},{"en":"Ranging from A to B means including many things between two examples or extremes.","zh":"從 A 到 B 不等，是指包括兩個例子或極端之間的許多事物。"},{"en":"The school offers activities ranging from chess to football.","zh":"學校提供從國際象棋到足球不等的活動。"},{"en":"A wide range of symptoms can show that the toxin affects several parts of the body.","zh":"廣泛症狀可以顯示毒素影響身體多個部分。"},{"en":"This phrase helps describe variety.","zh":"這個短語幫助描述多樣性。"}],"source":"74 - The cells from hell.pdf","sourcePage":6},{"front":"profuse sweating","meaning":"大量出汗","examples":[{"en":"The researcher suffered profuse sweating after exposure to the toxins.","zh":"研究人員接觸毒素後大量出汗。"},{"en":"Profuse sweating means sweating very heavily.","zh":"大量出汗，是指出汗非常嚴重。"},{"en":"A person with heatstroke may experience profuse sweating before becoming weak.","zh":"中暑的人可能在變得虛弱前大量出汗。"},{"en":"Heavy sweating can be a sign that the body is under severe stress.","zh":"大量出汗可能是身體承受嚴重壓力的跡象。"},{"en":"This phrase describes an unusually strong physical symptom.","zh":"這個短語描述異常強烈的身體症狀。"}],"source":"74 - The cells from hell.pdf","sourcePage":6},{"front":"tingling hands and feet","meaning":"手腳麻刺","examples":[{"en":"The symptoms included tingling hands and feet.","zh":"症狀包括手腳麻刺。"},{"en":"Tingling hands and feet means a prickly or numb feeling in the hands and feet.","zh":"手腳麻刺，是指手和腳有刺痛或麻木感。"},{"en":"Sitting in one position too long may cause tingling feet.","zh":"坐姿維持太久可能導致腳部麻刺。"},{"en":"Tingling can happen when nerves are irritated or blood flow is affected.","zh":"當神經受刺激或血流受影響時，可能出現麻刺感。"},{"en":"This phrase describes a sensory symptom.","zh":"這個短語描述感覺方面的症狀。"}],"source":"74 - The cells from hell.pdf","sourcePage":6},{"front":"liver and kidney problems","meaning":"肝臟和腎臟問題","examples":[{"en":"The researcher developed liver and kidney problems.","zh":"研究人員出現肝臟和腎臟問題。"},{"en":"Liver and kidney problems are health issues affecting organs that process waste and chemicals in the body.","zh":"肝臟和腎臟問題，是影響身體處理廢物和化學物的器官的健康問題。"},{"en":"Doctors may order blood tests if they suspect liver and kidney problems.","zh":"如果醫生懷疑肝腎問題，可能安排驗血。"},{"en":"Toxins can damage these organs because they help filter harmful substances.","zh":"毒素會損害這些器官，因為它們幫助過濾有害物質。"},{"en":"This phrase points to serious internal health effects.","zh":"這個短語指出嚴重內部健康影響。"}],"source":"74 - The cells from hell.pdf","sourcePage":6},{"front":"memory loss","meaning":"失憶；記憶力喪失","examples":[{"en":"The researcher suffered memory loss after exposure to the toxins.","zh":"研究人員接觸毒素後出現記憶力喪失。"},{"en":"Memory loss means difficulty remembering information, events, or recent experiences.","zh":"記憶力喪失，是指難以記住資訊、事件或近期經驗。"},{"en":"An elderly patient with memory loss may forget appointments or familiar names.","zh":"有記憶力喪失的長者可能忘記約會或熟悉名字。"},{"en":"Toxins affecting the brain can cause confusion and memory problems.","zh":"影響大腦的毒素可以造成混亂和記憶問題。"},{"en":"This phrase describes a serious cognitive symptom.","zh":"這個短語描述嚴重認知症狀。"}],"source":"74 - The cells from hell.pdf","sourcePage":7},{"front":"as the research intensified","meaning":"隨着研究加強","examples":[{"en":"As the research intensified, startling discoveries were made.","zh":"隨着研究加強，令人震驚的發現出現了。"},{"en":"As the research intensified means as the study became more serious, detailed, or active.","zh":"隨着研究加強，是指研究變得更認真、仔細或活躍。"},{"en":"As the investigation intensified, police interviewed more witnesses and checked more evidence.","zh":"隨着調查加強，警方訪問更多目擊者並檢查更多證據。"},{"en":"More intense research can reveal dangers that early tests missed.","zh":"更深入研究可以揭示早期測試錯過的危險。"},{"en":"This phrase shows that findings increased with deeper investigation.","zh":"這個短語顯示發現隨深入調查而增加。"}],"source":"74 - The cells from hell.pdf","sourcePage":7},{"front":"startling discoveries","meaning":"令人震驚的發現","examples":[{"en":"Researchers made startling discoveries about Pfiesteria.","zh":"研究人員對 Pfiesteria 作出令人震驚的發現。"},{"en":"Startling discoveries are findings that surprise or shock people.","zh":"令人震驚的發現，是令人驚訝或震撼的研究結果。"},{"en":"A doctor may make a startling discovery when a common symptom points to a rare disease.","zh":"當常見症狀指向罕見疾病，醫生可能作出令人震驚的發現。"},{"en":"Startling discoveries can force scientists to change their earlier beliefs.","zh":"令人震驚的發現可以迫使科學家改變早前信念。"},{"en":"This phrase highlights findings that are unexpected and important.","zh":"這個短語突出出乎意料且重要的發現。"}],"source":"74 - The cells from hell.pdf","sourcePage":7},{"front":"be content to behave like","meaning":"樂於表現得像……","examples":[{"en":"In tanks, Pfiesteria was content to behave like a plant.","zh":"在水缸中，Pfiesteria 樂於表現得像植物。"},{"en":"To be content to behave like something means to be willing to act in that way under certain conditions.","zh":"樂於表現得像某物，是指在某些條件下願意以那種方式行動。"},{"en":"A quiet child may be content to behave like an observer until invited to join the game.","zh":"安靜的孩子在被邀請加入遊戲前，可能樂於表現得像旁觀者。"},{"en":"Pfiesteria’s calm behaviour changed when fish were added.","zh":"當魚被加入後，Pfiesteria 平靜的行為改變了。"},{"en":"This phrase suggests temporary behaviour rather than permanent identity.","zh":"這個短語暗示暫時行為，而不是永久身份。"}],"source":"74 - The cells from hell.pdf","sourcePage":7},{"front":"photosynthesise","meaning":"進行光合作用","examples":[{"en":"Pfiesteria can behave like a plant and photosynthesise.","zh":"Pfiesteria 可以表現得像植物並進行光合作用。"},{"en":"To photosynthesise means to use light to make food, as plants and algae do.","zh":"進行光合作用，是指像植物和藻類一樣利用光製造食物。"},{"en":"Green plants photosynthesise when sunlight helps them produce energy from carbon dioxide and water.","zh":"綠色植物在陽光幫助下由二氧化碳和水產生能量，就是在進行光合作用。"},{"en":"If an organism can photosynthesise, it can act like a plant under normal conditions.","zh":"如果生物能進行光合作用，它在正常情況下可以表現得像植物。"},{"en":"This word describes a biological way of making energy.","zh":"這個詞描述一種製造能量的生物方式。"}],"source":"74 - The cells from hell.pdf","sourcePage":7},{"front":"a dramatic transformation","meaning":"戲劇性的轉變","examples":[{"en":"A dramatic transformation occurred when fish were added.","zh":"當魚被加入時，發生了戲劇性的轉變。"},{"en":"A dramatic transformation is a sudden, strong, and noticeable change.","zh":"戲劇性的轉變是突然、強烈且明顯的變化。"},{"en":"A quiet classroom may undergo a dramatic transformation when a fire alarm sounds.","zh":"當火警鐘響起，安靜課室可能發生戲劇性轉變。"},{"en":"In the tank, the presence of fish triggered a major change in Pfiesteria’s behaviour.","zh":"在水缸中，魚的存在觸發 Pfiesteria 行為上的重大改變。"},{"en":"This phrase describes a change too large to miss.","zh":"這個短語描述大到不能忽視的變化。"}],"source":"74 - The cells from hell.pdf","sourcePage":7},{"front":"occur","meaning":"發生","examples":[{"en":"A dramatic transformation occurred in the tank.","zh":"水缸中發生了戲劇性的轉變。"},{"en":"To occur means to happen or take place.","zh":"發生是指出現或進行。"},{"en":"A power cut may occur during a storm.","zh":"暴風雨期間可能發生停電。"},{"en":"Scientists record when changes occur so they can find possible causes.","zh":"科學家記錄變化何時發生，以便找出可能原因。"},{"en":"This word is a formal way to say “happen.”","zh":"這個詞是 “happen” 的正式說法。"}],"source":"74 - The cells from hell.pdf","sourcePage":7},{"front":"switch to attack mode","meaning":"轉入攻擊模式","examples":[{"en":"Pfiesteria switched to attack mode when fish were added.","zh":"當魚被加入時，Pfiesteria 轉入攻擊模式。"},{"en":"To switch to attack mode means to change from a calm state into an aggressive state.","zh":"轉入攻擊模式，是指由平靜狀態轉為攻擊性狀態。"},{"en":"A security dog may switch to attack mode if it senses a threat.","zh":"保安犬如果感到威脅，可能轉入攻擊模式。"},{"en":"The sudden switch shows that Pfiesteria responds strongly to the presence of fish.","zh":"這種突然轉變顯示 Pfiesteria 對魚的存在反應強烈。"},{"en":"This phrase makes the organism sound like a predator.","zh":"這個短語令該生物聽起來像捕食者。"}],"source":"74 - The cells from hell.pdf","sourcePage":7},{"front":"attack mode","meaning":"攻擊模式","examples":[{"en":"Pfiesteria changed shape when it entered attack mode.","zh":"Pfiesteria 進入攻擊模式時改變形狀。"},{"en":"Attack mode is a state in which an organism or system is ready to attack.","zh":"攻擊模式是生物或系統準備攻擊的狀態。"},{"en":"In a video game, a character enters attack mode when enemies appear.","zh":"在電子遊戲中，敵人出現時角色會進入攻擊模式。"},{"en":"When Pfiesteria enters attack mode, it secretes toxins and harms fish.","zh":"當 Pfiesteria 進入攻擊模式，它會分泌毒素並傷害魚類。"},{"en":"This phrase describes a dangerous active state.","zh":"這個短語描述危險的活躍狀態。"}],"source":"74 - The cells from hell.pdf","sourcePage":7},{"front":"in a matter of minutes","meaning":"在短短幾分鐘內","examples":[{"en":"In a matter of minutes, Pfiesteria changed shape and secreted a toxin.","zh":"在短短幾分鐘內，Pfiesteria 改變形狀並分泌毒素。"},{"en":"In a matter of minutes means within only a few minutes.","zh":"在短短幾分鐘內，是指只在幾分鐘之內。"},{"en":"A small kitchen fire can spread through a room in a matter of minutes.","zh":"小型廚房火災可以在短短幾分鐘內蔓延至整個房間。"},{"en":"Rapid changes are frightening because there is little time to react.","zh":"快速變化令人害怕，因為幾乎沒有時間反應。"},{"en":"This phrase emphasises speed and urgency.","zh":"這個短語強調速度和迫切性。"}],"source":"74 - The cells from hell.pdf","sourcePage":7},{"front":"change shape","meaning":"改變形狀","examples":[{"en":"Pfiesteria can change shape before attacking fish.","zh":"Pfiesteria 在攻擊魚類前可以改變形狀。"},{"en":"To change shape means to alter physical form.","zh":"改變形狀，是指改變實體外形。"},{"en":"Some soft toys change shape when children squeeze them.","zh":"有些軟玩具被孩子擠壓時會改變形狀。"},{"en":"Shape change can help a microorganism move, attach, or feed differently.","zh":"形狀改變可以幫助微生物以不同方式移動、附着或進食。"},{"en":"This phrase describes visible physical transformation.","zh":"這個短語描述可見的身體轉變。"}],"source":"74 - The cells from hell.pdf","sourcePage":7},{"front":"secrete a toxin","meaning":"分泌毒素","examples":[{"en":"Pfiesteria secreted a toxin that killed the fish.","zh":"Pfiesteria 分泌了一種殺死魚類的毒素。"},{"en":"To secrete a toxin means to produce and release a poisonous substance.","zh":"分泌毒素，是指產生並釋放有毒物質。"},{"en":"Some insects secrete a bitter chemical to stop birds from eating them.","zh":"有些昆蟲分泌苦味化學物，以阻止鳥類吃掉牠們。"},{"en":"A secreted toxin can spread through water and affect nearby organisms.","zh":"分泌出的毒素可以在水中擴散並影響附近生物。"},{"en":"This phrase describes how poison is released by a living thing.","zh":"這個短語描述生物如何釋放毒物。"}],"source":"74 - The cells from hell.pdf","sourcePage":8},{"front":"become disoriented","meaning":"變得迷失方向；神志混亂","examples":[{"en":"The fish quickly became disoriented after exposure to the toxin.","zh":"魚類接觸毒素後很快變得迷失方向。"},{"en":"To become disoriented means to lose direction, balance, or clear awareness.","zh":"變得迷失方向，是指失去方向、平衡或清晰意識。"},{"en":"A hiker may become disoriented in fog and walk the wrong way.","zh":"行山者在霧中可能迷失方向並走錯路。"},{"en":"Poison can affect the nervous system and make animals unable to move normally.","zh":"毒物可以影響神經系統，使動物無法正常移動。"},{"en":"This phrase describes confusion that affects movement or judgement.","zh":"這個短語描述影響移動或判斷的混亂狀態。"}],"source":"74 - The cells from hell.pdf","sourcePage":8},{"front":"within five minutes","meaning":"在五分鐘內","examples":[{"en":"Within five minutes, all the fish were dead.","zh":"在五分鐘內，所有魚都死了。"},{"en":"Within five minutes means before five minutes had passed.","zh":"在五分鐘內，是指五分鐘過去之前。"},{"en":"The ambulance arrived within five minutes of the emergency call.","zh":"救護車在緊急電話後五分鐘內到達。"},{"en":"If all fish die within minutes, the poison must be extremely powerful.","zh":"如果所有魚在幾分鐘內死亡，毒素一定非常強。"},{"en":"This phrase gives a very short time limit.","zh":"這個短語給出很短的時間限制。"}],"source":"74 - The cells from hell.pdf","sourcePage":8},{"front":"devour them","meaning":"吞噬牠們","examples":[{"en":"Pfiesteria changed shape again and devoured the dead fish.","zh":"Pfiesteria 再次改變形狀，並吞噬死魚。"},{"en":"To devour something means to eat it quickly or completely.","zh":"吞噬某物，是指快速或完全吃掉它。"},{"en":"Hungry students may devour sandwiches after a long sports lesson.","zh":"長時間體育課後，飢餓學生可能迅速吞掉三文治。"},{"en":"In nature, predators or scavengers may devour dead animals for energy.","zh":"在自然界中，捕食者或食腐動物可能吞食死去動物以獲取能量。"},{"en":"This verb gives a strong image of rapid eating.","zh":"這個動詞給出快速進食的強烈畫面。"}],"source":"74 - The cells from hell.pdf","sourcePage":8},{"front":"eat its fill","meaning":"吃飽","examples":[{"en":"Once Pfiesteria had eaten its fill, it vanished.","zh":"一旦 Pfiesteria 吃飽，它就消失了。"},{"en":"To eat its fill means to eat until it is no longer hungry.","zh":"吃飽，是指吃到不再飢餓。"},{"en":"A stray cat may eat its fill when someone leaves out a bowl of food.","zh":"當有人放下一碗食物，流浪貓可能吃飽。"},{"en":"After feeding fully, an organism may stop hunting and become inactive.","zh":"完全進食後，生物可能停止獵捕並變得不活躍。"},{"en":"This phrase describes complete feeding.","zh":"這個短語描述完全進食。"}],"source":"74 - The cells from hell.pdf","sourcePage":8},{"front":"vanish","meaning":"消失","examples":[{"en":"After feeding, Pfiesteria vanished.","zh":"進食後，Pfiesteria 消失了。"},{"en":"To vanish means to disappear suddenly or completely.","zh":"消失，是指突然或完全不見。"},{"en":"The stain vanished after the shirt was washed twice.","zh":"襯衫洗了兩次後，污漬消失了。"},{"en":"If a microorganism vanishes after feeding, it may become harder to detect.","zh":"如果微生物進食後消失，就可能更難被檢測到。"},{"en":"This word suggests disappearance that feels sudden or mysterious.","zh":"這個詞暗示突然或神秘的不見。"}],"source":"74 - The cells from hell.pdf","sourcePage":8},{"front":"No one had ever seen","meaning":"從來沒有人見過","examples":[{"en":"No one had ever seen an organism behave like this before.","zh":"從來沒有人見過生物以前這樣行動。"},{"en":"No one had ever seen means nobody had observed it at any earlier time.","zh":"從來沒有人見過，是指以前沒有人觀察到。"},{"en":"No one had ever seen the river turn bright red until the chemical spill.","zh":"在化學品洩漏之前，從來沒有人見過河水變成鮮紅色。"},{"en":"This phrase highlights how unusual a discovery is.","zh":"這個短語突出發現有多不尋常。"},{"en":"It suggests the event challenged previous scientific experience.","zh":"它暗示事件挑戰了以往科學經驗。"}],"source":"74 - The cells from hell.pdf","sourcePage":8},{"front":"an organism","meaning":"生物體","examples":[{"en":"No one had ever seen an organism do this before.","zh":"從來沒有人見過一個生物體以前這樣做。"},{"en":"An organism is any living thing, such as a plant, animal, bacterium, or fungus.","zh":"生物體是任何活着的東西，例如植物、動物、細菌或真菌。"},{"en":"A single-celled organism may be too small to see without a microscope.","zh":"單細胞生物體可能小到沒有顯微鏡就看不見。"},{"en":"Studying organisms helps scientists understand how life survives and changes.","zh":"研究生物體幫助科學家理解生命如何生存和改變。"},{"en":"This word is a general scientific term for a living thing.","zh":"這個詞是指活物的一般科學術語。"}],"source":"74 - The cells from hell.pdf","sourcePage":8},{"front":"initially","meaning":"起初","examples":[{"en":"Initially, scientists believed this was part of a natural cycle.","zh":"起初，科學家相信這是自然循環的一部分。"},{"en":"Initially means at first or in the beginning.","zh":"起初，是指一開始或最初。"},{"en":"Initially, students may find academic writing difficult, but practice makes it clearer.","zh":"起初，學生可能覺得學術寫作困難，但練習會令它更清楚。"},{"en":"Early explanations can change when more evidence appears.","zh":"當更多證據出現，早期解釋可能改變。"},{"en":"This word helps contrast first impressions with later understanding.","zh":"這個詞幫助對比最初印象與後來理解。"}],"source":"74 - The cells from hell.pdf","sourcePage":8},{"front":"a natural cycle","meaning":"自然循環","examples":[{"en":"Scientists first thought Pfiesteria’s behaviour was part of a natural cycle.","zh":"科學家起初認為 Pfiesteria 的行為是自然循環的一部分。"},{"en":"A natural cycle is a repeated process that happens in nature without human control.","zh":"自然循環是在自然界中重複發生、並非由人控制的過程。"},{"en":"The water cycle is a natural cycle involving evaporation, clouds, and rain.","zh":"水循環是涉及蒸發、雲和雨的自然循環。"},{"en":"If something is part of a natural cycle, it may not be caused by pollution.","zh":"如果某事是自然循環的一部分，它可能不是由污染造成。"},{"en":"This phrase contrasts natural processes with human-caused problems.","zh":"這個短語把自然過程與人為問題作對比。"}],"source":"74 - The cells from hell.pdf","sourcePage":8},{"front":"on closer examination","meaning":"經仔細檢查後","examples":[{"en":"On closer examination, pollution seemed to be to blame.","zh":"經仔細檢查後，污染似乎是罪魁禍首。"},{"en":"On closer examination means after studying something more carefully.","zh":"經仔細檢查後，是指更仔細研究某事之後。"},{"en":"On closer examination, the “broken” computer simply had a loose cable.","zh":"經仔細檢查後，那部「壞掉」的電腦其實只是電線鬆了。"},{"en":"Careful checking can change the first explanation of a problem.","zh":"仔細檢查可以改變對問題的最初解釋。"},{"en":"This phrase introduces a more accurate finding after deeper investigation.","zh":"這個短語引入深入調查後更準確的發現。"}],"source":"74 - The cells from hell.pdf","sourcePage":8},{"front":"be to blame","meaning":"是罪魁禍首","examples":[{"en":"Pollution seemed to be to blame for the fish kills.","zh":"污染似乎是魚類大規模死亡的罪魁禍首。"},{"en":"To be to blame means to be responsible for causing a problem.","zh":"是罪魁禍首，是指要為造成問題負責。"},{"en":"Poor drainage may be to blame if a playground floods after light rain.","zh":"如果操場小雨後也水浸，排水不良可能是罪魁禍首。"},{"en":"Finding what is to blame helps people fix the real cause.","zh":"找出罪魁禍首有助人們修正真正原因。"},{"en":"This phrase identifies responsibility for something bad.","zh":"這個短語指出壞事的責任所在。"}],"source":"74 - The cells from hell.pdf","sourcePage":9},{"front":"water containing the biggest fish kills","meaning":"出現最大規模魚類死亡的水域","examples":[{"en":"Scientists analysed water containing the biggest fish kills.","zh":"科學家分析出現最大規模魚類死亡的水域。"},{"en":"Water containing the biggest fish kills means water from places where the most fish had died.","zh":"出現最大規模魚類死亡的水域，是指最多魚死亡的地方的水。"},{"en":"Investigators test water from the worst affected area first because it may contain the strongest evidence.","zh":"調查人員會先測試受影響最嚴重地區的水，因為那裡可能含有最強證據。"},{"en":"Samples from severe cases can reveal pollution, toxins, or disease more clearly.","zh":"嚴重個案的樣本可以更清楚揭示污染、毒素或疾病。"},{"en":"This phrase identifies the most heavily affected water samples.","zh":"這個短語指出受影響最嚴重的水樣本。"}],"source":"74 - The cells from hell.pdf","sourcePage":9},{"front":"analyse water","meaning":"分析水質","examples":[{"en":"Scientists analysed water from the affected areas.","zh":"科學家分析受影響地區的水質。"},{"en":"To analyse water means to test it carefully to find chemicals, organisms, or pollution.","zh":"分析水質，是指仔細檢測水中化學物、生物或污染。"},{"en":"A city may analyse water after residents report a strange smell from the taps.","zh":"如果居民報告水龍頭有怪味，城市可能分析水質。"},{"en":"Water analysis can reveal hidden dangers that cannot be seen by eye.","zh":"水質分析可以揭示肉眼看不到的隱藏危險。"},{"en":"This phrase describes scientific testing of water quality.","zh":"這個短語描述對水質的科學檢測。"}],"source":"74 - The cells from hell.pdf","sourcePage":9},{"front":"high levels of pollution","meaning":"高水平污染","examples":[{"en":"Scientists found high levels of pollution in the water.","zh":"科學家在水中發現高水平污染。"},{"en":"High levels of pollution means a large amount of harmful substances in the environment.","zh":"高水平污染，是指環境中有大量有害物質。"},{"en":"A river with high levels of pollution may smell bad and harm wildlife.","zh":"高污染河流可能有臭味並傷害野生動物。"},{"en":"High pollution can create conditions in which dangerous organisms grow.","zh":"高污染可以創造危險生物生長的條件。"},{"en":"This phrase signals serious environmental contamination.","zh":"這個短語表示嚴重環境污染。"}],"source":"74 - The cells from hell.pdf","sourcePage":9},{"front":"one of the factors","meaning":"因素之一","examples":[{"en":"Pollution is one of the factors that can boost Pfiesteria’s transformation.","zh":"污染是可以促進 Pfiesteria 轉變的因素之一。"},{"en":"One of the factors means one cause or influence among several.","zh":"因素之一，是指幾個原因或影響中的其中一個。"},{"en":"Sleep is one of the factors that affects exam performance.","zh":"睡眠是影響考試表現的因素之一。"},{"en":"A problem can have many factors, so one cause may not explain everything.","zh":"一個問題可以有很多因素，所以單一原因未必解釋全部。"},{"en":"This phrase shows that the issue is complex.","zh":"這個短語顯示問題很複雜。"}],"source":"74 - The cells from hell.pdf","sourcePage":9},{"front":"boost the transformation","meaning":"促進轉變","examples":[{"en":"Pollution can boost the transformation in Pfiesteria.","zh":"污染可以促進 Pfiesteria 的轉變。"},{"en":"To boost the transformation means to increase or encourage the change.","zh":"促進轉變，是指增加或推動該變化。"},{"en":"Extra sunlight can boost the growth of plants in a classroom garden.","zh":"額外陽光可以促進課室花園植物生長。"},{"en":"Pollution may help turn a harmless-looking organism into a dangerous one.","zh":"污染可能幫助把看似無害的生物變成危險生物。"},{"en":"This phrase shows that a change becomes stronger or more likely.","zh":"這個短語顯示變化變得更強或更可能發生。"}],"source":"74 - The cells from hell.pdf","sourcePage":9},{"front":"large numbers of fish","meaning":"大量魚類","examples":[{"en":"Large numbers of fish feeding together can help create ideal conditions.","zh":"大量魚類一起覓食可以幫助創造理想條件。"},{"en":"Large numbers of fish means many fish in the same area.","zh":"大量魚類，是指許多魚在同一區域。"},{"en":"Large numbers of students in a small classroom can make learning uncomfortable.","zh":"大量學生擠在小課室中會令學習不舒服。"},{"en":"Many fish feeding together can add waste and nutrients to the water.","zh":"許多魚一起覓食可以把廢物和養分加入水中。"},{"en":"This phrase emphasises quantity and crowding.","zh":"這個短語強調數量和擁擠。"}],"source":"74 - The cells from hell.pdf","sourcePage":9},{"front":"travelling and feeding together","meaning":"一起游動和覓食","examples":[{"en":"Large numbers of fish were travelling and feeding together.","zh":"大量魚類一起游動和覓食。"},{"en":"Travelling and feeding together means moving as a group while searching for or eating food.","zh":"一起游動和覓食，是指成群移動並尋找或吃食物。"},{"en":"Birds may travel and feed together when they find a rich food source.","zh":"鳥類找到豐富食物來源時，可能一起移動和覓食。"},{"en":"Group feeding can concentrate waste and attract predators or microorganisms.","zh":"群體覓食會集中廢物，並吸引捕食者或微生物。"},{"en":"This phrase describes coordinated movement and eating.","zh":"這個短語描述協調的移動和進食。"}],"source":"74 - The cells from hell.pdf","sourcePage":9},{"front":"poorly flushed areas","meaning":"水流不暢的地方","examples":[{"en":"Pfiesteria grows well in poorly flushed areas.","zh":"Pfiesteria 在水流不暢的地方生長良好。"},{"en":"Poorly flushed areas are water places where fresh water does not move through quickly enough.","zh":"水流不暢的地方，是新鮮水流動不足或更新太慢的水域。"},{"en":"A small harbour with little water movement may become a poorly flushed area.","zh":"水流少的小港口可能成為水流不暢的地方。"},{"en":"Poor flushing can allow pollution, nutrients, and microorganisms to build up.","zh":"水流不暢會令污染、養分和微生物積聚。"},{"en":"This phrase describes stagnant or weakly circulating water.","zh":"這個短語描述停滯或循環弱的水域。"}],"source":"74 - The cells from hell.pdf","sourcePage":9},{"front":"abundant algae","meaning":"大量藻類","examples":[{"en":"Abundant algae can help create a suitable habitat for Pfiesteria.","zh":"大量藻類可以幫助形成適合 Pfiesteria 的棲息地。"},{"en":"Abundant algae means a large amount of algae growing in the water.","zh":"大量藻類，是指水中生長着很多藻類。"},{"en":"A pond with abundant algae may look green and thick in summer.","zh":"夏天有大量藻類的池塘可能看起來又綠又濃。"},{"en":"Too much algae can reduce oxygen and change the balance of an ecosystem.","zh":"太多藻類會降低氧氣並改變生態系統平衡。"},{"en":"This phrase describes plentiful algal growth.","zh":"這個短語描述豐富藻類生長。"}],"source":"74 - The cells from hell.pdf","sourcePage":9},{"front":"food sources","meaning":"食物來源","examples":[{"en":"Algae and other food sources help create a habitat for Pfiesteria.","zh":"藻類和其他食物來源幫助形成 Pfiesteria 的棲息地。"},{"en":"Food sources are things that provide food for an organism.","zh":"食物來源是為生物提供食物的東西。"},{"en":"A garden with flowers and seeds provides food sources for insects and birds.","zh":"有花和種子的花園為昆蟲和鳥類提供食物來源。"},{"en":"When food sources increase, some organisms can multiply quickly.","zh":"當食物來源增加，有些生物可以快速繁殖。"},{"en":"This phrase refers to available food in an environment.","zh":"這個短語指環境中可用的食物。"}],"source":"74 - The cells from hell.pdf","sourcePage":9},{"front":"the perfect habitat for","meaning":"……的理想棲息地","examples":[{"en":"Poorly flushed areas with abundant food are the perfect habitat for Pfiesteria.","zh":"水流不暢且食物豐富的地方是 Pfiesteria 的理想棲息地。"},{"en":"The perfect habitat for an organism is an environment where it can live and grow very well.","zh":"某生物的理想棲息地，是它能很好生活和生長的環境。"},{"en":"A damp dark corner can be the perfect habitat for mould.","zh":"潮濕陰暗角落可以是霉菌的理想棲息地。"},{"en":"When temperature, food, and water conditions fit, a species can spread quickly.","zh":"當溫度、食物和水環境配合，物種可以快速擴散。"},{"en":"This phrase describes ideal living conditions.","zh":"這個短語描述理想生活條件。"}],"source":"74 - The cells from hell.pdf","sourcePage":10},{"front":"not the only concern","meaning":"並非唯一令人關注的問題","examples":[{"en":"Pfiesteria is not the only concern for researchers.","zh":"Pfiesteria 並非研究人員唯一關注的問題。"},{"en":"Not the only concern means there are other problems to worry about as well.","zh":"並非唯一令人關注的問題，是指還有其他問題需要擔心。"},{"en":"In a hospital, cost is not the only concern; patient safety matters more.","zh":"在醫院中，成本並非唯一關注；病人安全更重要。"},{"en":"When similar algae appear elsewhere, scientists must look beyond one organism.","zh":"當類似藻類在其他地方出現，科學家必須超越單一生物去看問題。"},{"en":"This phrase widens attention to additional risks.","zh":"這個短語把注意力擴展到其他風險。"}],"source":"74 - The cells from hell.pdf","sourcePage":10},{"front":"all around the world","meaning":"世界各地","examples":[{"en":"Similar kinds of algae are appearing all around the world.","zh":"類似種類的藻類正在世界各地出現。"},{"en":"All around the world means in many places across the globe.","zh":"世界各地，是指全球許多地方。"},{"en":"Students all around the world use the internet to learn languages.","zh":"世界各地的學生使用互聯網學習語言。"},{"en":"A problem seen worldwide may require international cooperation.","zh":"在全球出現的問題可能需要國際合作。"},{"en":"This phrase emphasises global spread.","zh":"這個短語強調全球擴散。"}],"source":"74 - The cells from hell.pdf","sourcePage":10},{"front":"similar kinds of algae","meaning":"類似種類的藻類","examples":[{"en":"Similar kinds of algae are now materialising and turning toxic.","zh":"類似種類的藻類現在正在出現並變得有毒。"},{"en":"Similar kinds of algae are related types of algae with comparable features or behaviour.","zh":"類似種類的藻類，是具有相似特徵或行為的相關藻類。"},{"en":"Scientists may compare similar kinds of algae to see whether they produce the same toxins.","zh":"科學家可能比較類似藻類，以了解它們是否產生相同毒素。"},{"en":"If several similar algae become toxic, the problem may not be isolated.","zh":"如果幾種類似藻類都變得有毒，問題可能不是孤立個案。"},{"en":"This phrase points to a wider group, not just one species.","zh":"這個短語指較廣泛群體，而不只是單一物種。"}],"source":"74 - The cells from hell.pdf","sourcePage":10},{"front":"materialise","meaning":"出現","examples":[{"en":"Similar algae are materialising in oceans around the world.","zh":"類似藻類正在世界各地海洋中出現。"},{"en":"To materialise means to appear or become real after not being seen before.","zh":"出現，是指以前未被看到的東西變得可見或成為現實。"},{"en":"A problem may materialise when small cracks in a building suddenly spread.","zh":"當建築物小裂縫突然擴散，問題可能出現。"},{"en":"When toxic algae materialise in new places, authorities may need urgent monitoring.","zh":"當有毒藻類在新地方出現，當局可能需要緊急監測。"},{"en":"This verb suggests something emerging into view.","zh":"這個動詞暗示某物浮現。"}],"source":"74 - The cells from hell.pdf","sourcePage":10},{"front":"turn toxic","meaning":"變得有毒","examples":[{"en":"Some algae are materialising and turning toxic.","zh":"有些藻類正在出現並變得有毒。"},{"en":"To turn toxic means to become poisonous or harmful.","zh":"變得有毒，是指變成有毒或有害。"},{"en":"Food can turn toxic if it is contaminated by dangerous bacteria.","zh":"食物如果被危險細菌污染，就可能變得有毒。"},{"en":"Environmental changes may make normally harmless organisms turn toxic.","zh":"環境變化可能令通常無害的生物變得有毒。"},{"en":"This phrase describes a change from safe to dangerous.","zh":"這個短語描述由安全變成危險。"}],"source":"74 - The cells from hell.pdf","sourcePage":10},{"front":"in the last decade","meaning":"在過去十年","examples":[{"en":"In the last decade, algal blooms caused damage in many regions.","zh":"在過去十年，藻華在許多地區造成損害。"},{"en":"In the last decade means during the most recent ten-year period being discussed.","zh":"在過去十年，是指正在討論的最近十年期間。"},{"en":"In the last decade, many schools have added more online learning tools.","zh":"在過去十年，許多學校加入了更多網上學習工具。"},{"en":"A decade-long pattern helps show that events are not isolated accidents.","zh":"十年模式有助顯示事件不是孤立意外。"},{"en":"This phrase gives a recent historical time frame.","zh":"這個短語給出近期歷史時間範圍。"}],"source":"74 - The cells from hell.pdf","sourcePage":10},{"front":"algal blooms","meaning":"藻華；藻類大量繁殖","examples":[{"en":"Algal blooms have poisoned sea lions and killed fish.","zh":"藻華曾毒害海獅並殺死魚類。"},{"en":"Algal blooms are rapid increases in algae in water, often visible as coloured patches.","zh":"藻華是水中藻類快速增加，常以有色斑塊形式可見。"},{"en":"A lake may turn green during an algal bloom in hot weather.","zh":"炎熱天氣中，湖泊可能因藻華而變綠。"},{"en":"Some algal blooms use up oxygen or produce toxins that harm animals and people.","zh":"有些藻華會耗盡氧氣或產生毒素，傷害動物和人類。"},{"en":"This phrase describes sudden excessive algal growth.","zh":"這個短語描述藻類突然過度生長。"}],"source":"74 - The cells from hell.pdf","sourcePage":10},{"front":"poison sea lions","meaning":"毒害海獅","examples":[{"en":"Algal blooms have poisoned sea lions in California.","zh":"藻華曾在加州毒害海獅。"},{"en":"To poison sea lions means to make sea lions sick or dead through toxins.","zh":"毒害海獅，是指透過毒素令海獅生病或死亡。"},{"en":"Toxic fish can poison sea lions when the animals eat contaminated prey.","zh":"當海獅吃受污染獵物，有毒魚類可能毒害牠們。"},{"en":"Poisoned sea lions may become weak, confused, or unable to swim normally.","zh":"中毒海獅可能變得虛弱、混亂或無法正常游泳。"},{"en":"This phrase shows that toxins move through the marine food web.","zh":"這個短語顯示毒素會穿過海洋食物網。"}],"source":"74 - The cells from hell.pdf","sourcePage":10},{"front":"sea lions","meaning":"海獅","examples":[{"en":"Sea lions in California were poisoned by algal blooms.","zh":"加州海獅被藻華毒害。"},{"en":"Sea lions are marine mammals with flippers that live along coasts and feed on fish.","zh":"海獅是有鰭肢、生活在沿岸並以魚類為食的海洋哺乳動物。"},{"en":"Visitors may see sea lions resting on rocks near a harbour.","zh":"遊客可能在港口附近岩石上看到海獅休息。"},{"en":"If their food becomes contaminated, sea lions can be harmed by toxins indirectly.","zh":"如果牠們的食物受污染，海獅可能間接受到毒素傷害。"},{"en":"This word names a coastal marine animal.","zh":"這個詞命名一種沿海海洋動物。"}],"source":"74 - The cells from hell.pdf","sourcePage":10},{"front":"catastrophic fish kills","meaning":"災難性的魚類大規模死亡","examples":[{"en":"Algal blooms caused catastrophic fish kills in several seas.","zh":"藻華在幾個海域造成災難性的魚類大規模死亡。"},{"en":"Catastrophic fish kills are extremely serious events in which huge numbers of fish die.","zh":"災難性的魚類大規模死亡，是大量魚死亡的極嚴重事件。"},{"en":"A catastrophic fish kill can destroy local fishing income within days.","zh":"一次災難性魚類死亡可以在幾天內摧毀本地漁業收入。"},{"en":"Such events can happen when toxins, low oxygen, or pollution spread through water.","zh":"當毒素、低氧或污染在水中擴散，這類事件可能發生。"},{"en":"This phrase stresses large-scale ecological disaster.","zh":"這個短語強調大規模生態災難。"}],"source":"74 - The cells from hell.pdf","sourcePage":10},{"front":"the Pacific","meaning":"太平洋","examples":[{"en":"Catastrophic fish kills occurred in the Pacific.","zh":"太平洋發生災難性的魚類大規模死亡。"},{"en":"The Pacific is the world’s largest ocean.","zh":"太平洋是世界上最大的海洋。"},{"en":"Many countries border the Pacific, so marine problems there can affect many communities.","zh":"許多國家毗鄰太平洋，因此該處海洋問題會影響許多社區。"},{"en":"Fish kills in the Pacific can harm fishing, tourism, and coastal ecosystems.","zh":"太平洋的魚類死亡會損害漁業、旅遊和沿海生態系統。"},{"en":"This phrase gives one major ocean location.","zh":"這個短語給出一個主要海洋地點。"}],"source":"74 - The cells from hell.pdf","sourcePage":11},{"front":"the Mediterranean","meaning":"地中海","examples":[{"en":"Catastrophic fish kills occurred in the Mediterranean.","zh":"地中海發生災難性的魚類大規模死亡。"},{"en":"The Mediterranean is the sea between southern Europe, northern Africa, and western Asia.","zh":"地中海是位於南歐、北非和西亞之間的海。"},{"en":"The Mediterranean supports fishing, tourism, and coastal communities.","zh":"地中海支持漁業、旅遊和沿海社區。"},{"en":"Pollution or algal blooms there can affect many countries around the same sea.","zh":"當地污染或藻華可以影響同一海域周邊許多國家。"},{"en":"This phrase names a major regional sea.","zh":"這個短語命名一個主要區域海域。"}],"source":"74 - The cells from hell.pdf","sourcePage":11},{"front":"the North Sea","meaning":"北海","examples":[{"en":"Catastrophic fish kills occurred in the North Sea.","zh":"北海發生災難性的魚類大規模死亡。"},{"en":"The North Sea is a sea between Britain, Scandinavia, Germany, the Netherlands, Belgium, and France.","zh":"北海是位於英國、斯堪的納維亞、德國、荷蘭、比利時和法國之間的海域。"},{"en":"The North Sea is important for fishing, shipping, and energy industries.","zh":"北海對漁業、航運和能源產業很重要。"},{"en":"Fish kills there can affect several countries because the sea is shared.","zh":"該處魚類死亡會影響幾個國家，因為這片海域是共享的。"},{"en":"This phrase gives another location where algal damage occurred.","zh":"這個短語提供另一個藻類造成損害的地點。"}],"source":"74 - The cells from hell.pdf","sourcePage":11},{"front":"devastate the shellfish industry","meaning":"重創貝類海產業","examples":[{"en":"Algal blooms devastated the shellfish industry in New Zealand.","zh":"藻華重創紐西蘭貝類海產業。"},{"en":"To devastate the shellfish industry means to cause severe damage to businesses that harvest or farm shellfish.","zh":"重創貝類海產業，是指嚴重損害捕撈或養殖貝類的企業。"},{"en":"A ban on unsafe shellfish can devastate small coastal businesses.","zh":"禁售不安全貝類可以重創小型沿海企業。"},{"en":"Toxic algae can close farms, stop sales, and destroy public confidence in seafood.","zh":"有毒藻類可以令養殖場關閉、銷售停止並破壞公眾對海產的信心。"},{"en":"This phrase shows major economic harm from an environmental event.","zh":"這個短語顯示環境事件造成重大經濟損害。"}],"source":"74 - The cells from hell.pdf","sourcePage":11},{"front":"shellfish industry","meaning":"貝類海產業","examples":[{"en":"The shellfish industry in New Zealand was devastated.","zh":"紐西蘭貝類海產業被重創。"},{"en":"The shellfish industry includes businesses that farm, collect, process, or sell shellfish.","zh":"貝類海產業包括養殖、採集、加工或銷售貝類的企業。"},{"en":"Mussels, oysters, and clams are products of the shellfish industry.","zh":"青口、蠔和蜆都是貝類海產業的產品。"},{"en":"If waters become toxic, the shellfish industry may lose harvests and customers.","zh":"如果水域變得有毒，貝類海產業可能失去收成和顧客。"},{"en":"This phrase refers to an economic sector based on shellfish.","zh":"這個短語指以貝類為基礎的經濟產業。"}],"source":"74 - The cells from hell.pdf","sourcePage":11},{"front":"researchers from forty-seven nations","meaning":"來自四十七個國家的研究人員","examples":[{"en":"Researchers from forty-seven nations met to share information.","zh":"來自四十七個國家的研究人員會面分享資訊。"},{"en":"Researchers from forty-seven nations means scientists or experts from 47 countries.","zh":"來自四十七個國家的研究人員，是指來自 47 個國家的科學家或專家。"},{"en":"Researchers from many nations may gather when a disease affects the global ocean.","zh":"當疾病影響全球海洋，來自許多國家的研究人員可能聚集。"},{"en":"Wide international participation shows that the issue is not local or minor.","zh":"廣泛國際參與顯示問題並非本地或輕微。"},{"en":"This phrase emphasises the global scale of scientific concern.","zh":"這個短語強調科學關注的全球規模。"}],"source":"74 - The cells from hell.pdf","sourcePage":11},{"front":"share the latest information about","meaning":"分享有關……的最新資料","examples":[{"en":"Researchers met to share the latest information about harmful algal blooms.","zh":"研究人員會面分享有關有害藻華的最新資料。"},{"en":"To share the latest information about something means to exchange the newest findings or updates.","zh":"分享有關某事的最新資料，是指交換最新發現或更新。"},{"en":"Doctors may share the latest information about a new virus at a medical conference.","zh":"醫生可能在醫學會議上分享有關新病毒的最新資料。"},{"en":"Sharing updates helps experts respond faster to emerging dangers.","zh":"分享更新有助專家更快回應新興危險。"},{"en":"This phrase describes professional exchange of recent knowledge.","zh":"這個短語描述專業人士交換近期知識。"}],"source":"74 - The cells from hell.pdf","sourcePage":11},{"front":"harmful algal blooms","meaning":"有害藻華","examples":[{"en":"The conference focused on harmful algal blooms.","zh":"會議集中討論有害藻華。"},{"en":"Harmful algal blooms are rapid algal growths that damage animals, people, or ecosystems.","zh":"有害藻華是會傷害動物、人類或生態系統的快速藻類生長。"},{"en":"A harmful algal bloom may make shellfish unsafe to eat.","zh":"有害藻華可能令貝類不宜食用。"},{"en":"These blooms are dangerous because they can produce toxins or reduce oxygen.","zh":"這些藻華危險，因為它們可以產生毒素或降低氧氣。"},{"en":"This phrase refers to algal growth with negative effects.","zh":"這個短語指具有負面影響的藻類生長。"}],"source":"74 - The cells from hell.pdf","sourcePage":11},{"front":"new types of toxins","meaning":"新種類的毒素","examples":[{"en":"Researchers heard about new types of toxins.","zh":"研究人員聽到有關新種類毒素的資料。"},{"en":"New types of toxins are newly discovered or newly recognised poisonous substances.","zh":"新種類的毒素，是新發現或新被認識的有毒物質。"},{"en":"A hospital laboratory may identify new types of toxins after unusual poisoning cases.","zh":"醫院化驗室可能在不尋常中毒個案後識別新種類毒素。"},{"en":"New toxins worry scientists because existing tests may not detect them quickly.","zh":"新毒素令科學家擔心，因為現有檢測可能無法快速發現它們。"},{"en":"This phrase points to emerging chemical dangers.","zh":"這個短語指出新興化學危險。"}],"source":"74 - The cells from hell.pdf","sourcePage":11},{"front":"possible links between","meaning":"……之間可能的關聯","examples":[{"en":"Researchers discussed possible links between toxic algae and whale strandings.","zh":"研究人員討論有毒藻類與鯨魚擱淺之間可能的關聯。"},{"en":"Possible links between two things are possible connections that have not been fully proven.","zh":"兩者之間可能的關聯，是尚未完全證明的可能連繫。"},{"en":"Scientists may study possible links between air pollution and childhood asthma.","zh":"科學家可能研究空氣污染與兒童哮喘之間可能的關聯。"},{"en":"A possible link needs evidence before it becomes a confirmed cause.","zh":"可能關聯需要證據，才會成為已確認原因。"},{"en":"This phrase introduces a cautious scientific connection.","zh":"這個短語引入謹慎的科學連繫。"}],"source":"74 - The cells from hell.pdf","sourcePage":11},{"front":"toxic algae","meaning":"有毒藻類","examples":[{"en":"Toxic algae may be linked to whale strandings.","zh":"有毒藻類可能與鯨魚擱淺有關。"},{"en":"Toxic algae are algae that produce poisonous substances.","zh":"有毒藻類是會產生有毒物質的藻類。"},{"en":"Toxic algae can make fish, shellfish, or marine mammals unsafe or sick.","zh":"有毒藻類可以令魚類、貝類或海洋哺乳動物不安全或生病。"},{"en":"When toxic algae spread, coastal communities may close beaches or fishing areas.","zh":"當有毒藻類擴散，沿海社區可能關閉海灘或漁區。"},{"en":"This phrase identifies algae that are harmful because of toxins.","zh":"這個短語指出因毒素而有害的藻類。"}],"source":"74 - The cells from hell.pdf","sourcePage":11},{"front":"whale strandings","meaning":"鯨魚擱淺","examples":[{"en":"Researchers discussed possible links between toxic algae and whale strandings.","zh":"研究人員討論有毒藻類與鯨魚擱淺之間可能的關聯。"},{"en":"Whale strandings are events in which whales become stuck on beaches or shallow shores.","zh":"鯨魚擱淺，是鯨魚被困在海灘或淺岸上的事件。"},{"en":"Volunteers may try to help during whale strandings by keeping the animals wet.","zh":"鯨魚擱淺時，義工可能嘗試讓動物保持濕潤來幫忙。"},{"en":"Strandings can happen for many reasons, including illness, navigation problems, or toxins.","zh":"擱淺可能由許多原因造成，包括疾病、導航問題或毒素。"},{"en":"This phrase refers to a serious marine animal emergency.","zh":"這個短語指嚴重海洋動物緊急情況。"}],"source":"74 - The cells from hell.pdf","sourcePage":12},{"front":"dominate the proceedings","meaning":"成為會議的焦點","examples":[{"en":"News about toxic algae spreading dominated the proceedings.","zh":"有毒藻類擴散的消息成為會議焦點。"},{"en":"To dominate the proceedings means to become the main topic in a meeting or event.","zh":"成為會議焦點，是指成為會議或活動中的主要話題。"},{"en":"At a school meeting, exam reform may dominate the proceedings if many parents are worried.","zh":"如果許多家長擔心，考試改革可能成為學校會議焦點。"},{"en":"A topic dominates when it receives more attention than everything else.","zh":"當某話題比其他事情得到更多注意，它就主導討論。"},{"en":"This phrase shows what became the focus of discussion.","zh":"這個短語顯示甚麼成為討論焦點。"}],"source":"74 - The cells from hell.pdf","sourcePage":12},{"front":"the proceedings","meaning":"會議過程；議程","examples":[{"en":"The proceedings were dominated by news about toxic algae.","zh":"會議過程被有毒藻類的消息主導。"},{"en":"The proceedings are the events, discussions, or formal activities of a meeting or conference.","zh":"會議過程或議程，是會議或研討會中的事件、討論或正式活動。"},{"en":"The proceedings of a school meeting may include reports, questions, and votes.","zh":"學校會議過程可能包括報告、提問和投票。"},{"en":"If one issue dominates the proceedings, other topics may receive less time.","zh":"如果一個議題主導會議，其他話題可能得到較少時間。"},{"en":"This phrase refers to what happens during an official gathering.","zh":"這個短語指正式聚會中發生的事情。"}],"source":"74 - The cells from hell.pdf","sourcePage":12},{"front":"spread to new shores","meaning":"傳播到新的海岸","examples":[{"en":"Toxic algae are spreading to new shores.","zh":"有毒藻類正在傳播到新的海岸。"},{"en":"To spread to new shores means to move or appear along coastlines where they were not seen before.","zh":"傳播到新的海岸，是指移動或出現在以前未見過的海岸線。"},{"en":"An invasive plant may spread to new shores after seeds are carried by ships.","zh":"入侵植物的種子被船隻帶走後，可能傳播到新的海岸。"},{"en":"When a harmful organism reaches new shores, local species may be unprepared.","zh":"當有害生物到達新海岸，本地物種可能毫無準備。"},{"en":"This phrase describes geographical expansion to new coastal areas.","zh":"這個短語描述向新沿海地區擴張。"}],"source":"74 - The cells from hell.pdf","sourcePage":12},{"front":"ballast water","meaning":"壓艙水","examples":[{"en":"Toxic algae may spread in ballast water carried by ships.","zh":"有毒藻類可能在船隻運載的壓艙水中擴散。"},{"en":"Ballast water is water carried by ships to keep them stable during travel.","zh":"壓艙水是船隻為保持航行穩定而載入的水。"},{"en":"A ship may take in ballast water in one port and release it in another.","zh":"船隻可能在一個港口吸入壓艙水，並在另一個港口排放。"},{"en":"Ballast water can move tiny organisms across oceans unintentionally.","zh":"壓艙水可以無意中把微小生物帶到海洋各地。"},{"en":"This phrase explains one way marine species can spread globally.","zh":"這個短語解釋海洋物種全球擴散的一種方式。"}],"source":"74 - The cells from hell.pdf","sourcePage":12},{"front":"carried by ships","meaning":"由船隻運載","examples":[{"en":"Toxic algae may be carried by ships in ballast water.","zh":"有毒藻類可能由船隻透過壓艙水運載。"},{"en":"Carried by ships means transported on or inside ships from one place to another.","zh":"由船隻運載，是指在船上或船內由一地運到另一地。"},{"en":"Cargo, fuel, and even tiny organisms can be carried by ships across oceans.","zh":"貨物、燃料，甚至微小生物都可以由船隻跨海運載。"},{"en":"When organisms are carried by ships, they may arrive in ecosystems where they do not belong.","zh":"當生物由船隻運載，它們可能到達不屬於自己的生態系統。"},{"en":"This phrase describes transport through shipping.","zh":"這個短語描述透過航運進行的運輸。"}],"source":"74 - The cells from hell.pdf","sourcePage":12},{"front":"that may have already happened","meaning":"那可能已經發生","examples":[{"en":"The spread of toxic algae may have already happened in Australian waters.","zh":"有毒藻類在澳洲水域的擴散可能已經發生。"},{"en":"That may have already happened means the event possibly occurred before people fully realised it.","zh":"那可能已經發生，是指事件可能在人們完全意識到之前已出現。"},{"en":"By the time the leak was found, the damage may have already happened.","zh":"當洩漏被發現時，損害可能已經發生。"},{"en":"This phrase suggests concern that action may be too late.","zh":"這個短語暗示擔心行動可能太遲。"},{"en":"It is used when evidence points to a past event that is not fully confirmed.","zh":"當證據指向尚未完全確認的過去事件時，會使用它。"}],"source":"74 - The cells from hell.pdf","sourcePage":12},{"front":"Australian waters","meaning":"澳洲水域","examples":[{"en":"Chattonella is present in Australian waters.","zh":"Chattonella 存在於澳洲水域。"},{"en":"Australian waters are the seas and coastal waters around Australia.","zh":"澳洲水域是澳洲周圍的海洋和沿海水域。"},{"en":"Scientists may test Australian waters after unusual fish deaths near fish farms.","zh":"魚場附近出現不尋常魚類死亡後，科學家可能檢測澳洲水域。"},{"en":"If a toxic alga enters Australian waters, fishing and aquaculture may be affected.","zh":"如果有毒藻類進入澳洲水域，漁業和水產養殖可能受影響。"},{"en":"This phrase gives the geographical area of concern.","zh":"這個短語給出令人關注的地理區域。"}],"source":"74 - The cells from hell.pdf","sourcePage":12},{"front":"a tuna kill","meaning":"吞拿魚大規模死亡","examples":[{"en":"A tuna kill in 1996 cost fish farmers millions of dollars.","zh":"1996 年一次吞拿魚大規模死亡令養魚戶損失數百萬美元。"},{"en":"A tuna kill is an event in which large numbers of tuna die suddenly.","zh":"吞拿魚大規模死亡，是大量吞拿魚突然死亡的事件。"},{"en":"A fish farm may suffer a tuna kill if toxins enter the water cages.","zh":"如果毒素進入海上魚籠，魚場可能遭遇吞拿魚大規模死亡。"},{"en":"Tuna kills can cause huge financial losses because farmed tuna are valuable.","zh":"吞拿魚大規模死亡會造成巨大財政損失，因為養殖吞拿魚價值很高。"},{"en":"This phrase describes mass death involving tuna.","zh":"這個短語描述涉及吞拿魚的大量死亡。"}],"source":"74 - The cells from hell.pdf","sourcePage":12},{"front":"fish farmers","meaning":"養魚戶","examples":[{"en":"The tuna kill cost fish farmers an estimated $45 million.","zh":"吞拿魚大規模死亡令養魚戶估計損失四千五百萬美元。"},{"en":"Fish farmers are people or businesses that raise fish for food or sale.","zh":"養魚戶是為食用或出售而養殖魚類的人或企業。"},{"en":"Fish farmers may keep tuna, salmon, or shellfish in controlled water areas.","zh":"養魚戶可能在受控水域養殖吞拿魚、三文魚或貝類。"},{"en":"If disease or toxic algae spreads, fish farmers can lose entire stocks.","zh":"如果疾病或有毒藻類擴散，養魚戶可能失去整批魚。"},{"en":"This phrase refers to people in aquaculture, not wild fishing.","zh":"這個短語指水產養殖人士，而不是野外捕魚人士。"}],"source":"74 - The cells from hell.pdf","sourcePage":12},{"front":"an estimated $45 million","meaning":"估計四千五百萬美元","examples":[{"en":"The tuna kill cost fish farmers an estimated $45 million.","zh":"吞拿魚大規模死亡令養魚戶估計損失四千五百萬美元。"},{"en":"An estimated $45 million means about 45 million dollars, based on calculation rather than exact certainty.","zh":"估計四千五百萬美元，是指根據計算約為四千五百萬美元，而非完全確定。"},{"en":"A storm may cause an estimated $2 million in damage before final repairs are counted.","zh":"在最終維修費計算前，風暴可能造成估計二百萬美元損失。"},{"en":"Estimates help people understand scale even before exact figures are known.","zh":"估算幫助人們在準確數字未知前理解規模。"},{"en":"This phrase gives an approximate financial amount.","zh":"這個短語給出大約財務金額。"}],"source":"74 - The cells from hell.pdf","sourcePage":12},{"front":"the official explanation","meaning":"官方解釋","examples":[{"en":"The official explanation was that a storm was to blame.","zh":"官方解釋是風暴是原因。"},{"en":"The official explanation is the reason given by authorities or responsible organisations.","zh":"官方解釋是當局或負責組織給出的原因。"},{"en":"After a train delay, the official explanation may be a signalling fault.","zh":"火車延誤後，官方解釋可能是信號故障。"},{"en":"Official explanations may be accepted, questioned, or changed when new evidence appears.","zh":"當新證據出現，官方解釋可能被接受、質疑或改變。"},{"en":"This phrase refers to the public or authorised account.","zh":"這個短語指公開或獲授權的說法。"}],"source":"74 - The cells from hell.pdf","sourcePage":13},{"front":"a storm was to blame","meaning":"風暴是原因","examples":[{"en":"The official explanation was that a storm was to blame.","zh":"官方解釋是風暴是原因。"},{"en":"A storm was to blame means the storm was said to be the cause of the damage.","zh":"風暴是原因，是指風暴被說成造成損害的原因。"},{"en":"If trees fall after strong winds, people may say a storm was to blame.","zh":"如果強風後樹木倒下，人們可能說風暴是原因。"},{"en":"Blaming a storm can hide other causes if evidence is ignored.","zh":"如果證據被忽視，把責任歸咎於風暴可能掩蓋其他原因。"},{"en":"This phrase identifies weather as the suspected cause.","zh":"這個短語指出天氣是被懷疑的原因。"}],"source":"74 - The cells from hell.pdf","sourcePage":13},{"front":"reports of","meaning":"有關……的報告","examples":[{"en":"There were reports of orange-brown streaks in the water.","zh":"有報告指水中出現橙啡色條紋。"},{"en":"Reports of something are statements or accounts saying that it happened or was seen.","zh":"有關某事的報告，是指說某事發生或被看見的陳述。"},{"en":"There may be reports of smoke before firefighters arrive.","zh":"消防員到達前，可能已有關於煙霧的報告。"},{"en":"Reports help investigators decide where to look for evidence.","zh":"報告幫助調查人員決定在哪裡尋找證據。"},{"en":"This phrase introduces observed information that may need checking.","zh":"這個短語引入可能需要核實的觀察資訊。"}],"source":"74 - The cells from hell.pdf","sourcePage":13},{"front":"orange-brown streaks","meaning":"橙啡色條紋","examples":[{"en":"There were orange-brown streaks in the water.","zh":"水中有橙啡色條紋。"},{"en":"Orange-brown streaks are long narrow marks or lines with an orange-brown colour.","zh":"橙啡色條紋，是橙啡色的狹長痕跡或線條。"},{"en":"Oil or algae may create coloured streaks on the surface of water.","zh":"油污或藻類可能在水面造成有色條紋。"},{"en":"Unusual streaks can warn scientists that something has changed in the water.","zh":"不尋常條紋可以警告科學家水中有變化。"},{"en":"This phrase gives a visible clue of possible contamination or bloom.","zh":"這個短語提供可能污染或藻華的可見線索。"}],"source":"74 - The cells from hell.pdf","sourcePage":13},{"front":"a water sample","meaning":"水樣本","examples":[{"en":"A water sample was examined after the tuna kill.","zh":"吞拿魚大規模死亡後，一個水樣本被檢驗。"},{"en":"A water sample is a small amount of water collected for testing.","zh":"水樣本是收集作檢測的一小部分水。"},{"en":"A laboratory may test a water sample from a river after people report dead fish.","zh":"人們報告死魚後，實驗室可能檢測河流水樣本。"},{"en":"Water samples can reveal toxins, bacteria, or unusual algae.","zh":"水樣本可以揭示毒素、細菌或不尋常藻類。"},{"en":"This phrase refers to evidence collected from the environment.","zh":"這個短語指從環境中收集的證據。"}],"source":"74 - The cells from hell.pdf","sourcePage":13},{"front":"be examined","meaning":"被檢驗","examples":[{"en":"When the water sample was examined, Chattonella was found.","zh":"當水樣本被檢驗時，發現了 Chattonella。"},{"en":"To be examined means to be looked at or tested carefully.","zh":"被檢驗，是指被仔細查看或測試。"},{"en":"A patient’s blood sample may be examined for signs of infection.","zh":"病人的血液樣本可能被檢驗是否有感染跡象。"},{"en":"Careful examination can reveal information that was invisible at first.","zh":"仔細檢驗可以揭示起初看不見的資訊。"},{"en":"This phrase describes detailed checking.","zh":"這個短語描述詳細檢查。"}],"source":"74 - The cells from hell.pdf","sourcePage":13},{"front":"be teeming with","meaning":"充滿","examples":[{"en":"The water sample was teeming with an alga never before seen in Australia.","zh":"水樣本充滿一種以前從未在澳洲見過的藻類。"},{"en":"To be teeming with something means to be full of large numbers of it.","zh":"充滿某物，是指有大量該物。"},{"en":"A market may be teeming with shoppers before a holiday.","zh":"假日前，街市可能擠滿購物者。"},{"en":"If water is teeming with algae, the bloom may be severe.","zh":"如果水中充滿藻類，藻華可能很嚴重。"},{"en":"This phrase describes abundance and crowding.","zh":"這個短語描述豐富和擁擠。"}],"source":"74 - The cells from hell.pdf","sourcePage":13},{"front":"an alga","meaning":"一種藻類","examples":[{"en":"An alga called Chattonella was found in the water sample.","zh":"水樣本中發現一種名為 Chattonella 的藻類。"},{"en":"An alga is a simple water-living organism that may photosynthesise like a plant.","zh":"一種藻類，是一種簡單水生生物，可能像植物一樣進行光合作用。"},{"en":"A pond may contain more than one kind of alga.","zh":"池塘中可能含有不止一種藻類。"},{"en":"Some algae are harmless, but others can produce dangerous toxins.","zh":"有些藻類無害，但有些可以產生危險毒素。"},{"en":"This word is the singular form of algae.","zh":"這個詞是 algae 的單數形式。"}],"source":"74 - The cells from hell.pdf","sourcePage":13},{"front":"never before seen","meaning":"以前從未見過","examples":[{"en":"The alga had never before been seen in Australia.","zh":"這種藻類以前從未在澳洲見過。"},{"en":"Never before seen means not observed or recorded there at any earlier time.","zh":"以前從未見過，是指過去沒有在該處被觀察或記錄。"},{"en":"A bird species never before seen in the city may attract scientists and birdwatchers.","zh":"一種以前從未在城市見過的鳥類可能吸引科學家和觀鳥者。"},{"en":"When a harmful organism appears in a new region, people worry about how it arrived.","zh":"當有害生物在新地區出現，人們會擔心它如何到達。"},{"en":"This phrase highlights novelty and surprise.","zh":"這個短語突出新奇和驚訝。"}],"source":"74 - The cells from hell.pdf","sourcePage":13},{"front":"Chattonella","meaning":"Chattonella（一種有毒藻類）","examples":[{"en":"Chattonella had never before been seen in Australia.","zh":"Chattonella 以前從未在澳洲見過。"},{"en":"Chattonella is a toxic alga linked in the passage to major fish deaths.","zh":"Chattonella 是篇章中與重大魚類死亡有關的一種有毒藻類。"},{"en":"Scientists may test fish tissue to see whether Chattonella toxins are present.","zh":"科學家可能檢測魚類組織，以了解是否存在 Chattonella 毒素。"},{"en":"The discovery of Chattonella raised questions about how the alga reached Australian waters.","zh":"發現 Chattonella 引發了這種藻類如何到達澳洲水域的問題。"},{"en":"This name refers to a specific harmful alga.","zh":"這個名稱指一種特定有害藻類。"}],"source":"74 - The cells from hell.pdf","sourcePage":13},{"front":"half a billion dollars’ worth of fish","meaning":"價值五億美元的魚","examples":[{"en":"Chattonella killed half a billion dollars’ worth of fish in Japan.","zh":"Chattonella 在日本殺死了價值五億美元的魚。"},{"en":"Half a billion dollars’ worth of fish means fish valued at about 500 million dollars.","zh":"價值五億美元的魚，是指價值約五億美元的魚。"},{"en":"A disease outbreak can destroy millions of dollars’ worth of farm animals.","zh":"疾病爆發可以摧毀價值數百萬美元的養殖動物。"},{"en":"Large financial values show why toxic algae are an economic as well as environmental problem.","zh":"巨大財務價值顯示有毒藻類既是環境問題，也是經濟問題。"},{"en":"This phrase emphasises the scale of industry loss.","zh":"這個短語強調產業損失規模。"}],"source":"74 - The cells from hell.pdf","sourcePage":13},{"front":"a toxin produced by this alga","meaning":"由這種藻類產生的毒素","examples":[{"en":"A toxin produced by this alga was found in the dead tuna.","zh":"死去吞拿魚中發現由這種藻類產生的毒素。"},{"en":"A toxin produced by this alga is a poisonous substance made by that alga.","zh":"由這種藻類產生的毒素，是該藻類製造的有毒物質。"},{"en":"If a toxin produced by bacteria is found in food, the food must be recalled.","zh":"如果食物中發現由細菌產生的毒素，該食物必須回收。"},{"en":"Finding the toxin in dead animals can link the organism to the deaths.","zh":"在死去動物體內發現毒素，可以把該生物與死亡連繫起來。"},{"en":"This phrase connects a poison with its biological source.","zh":"這個短語把毒物與其生物來源連接起來。"}],"source":"74 - The cells from hell.pdf","sourcePage":14},{"front":"be present in","meaning":"存在於","examples":[{"en":"The toxin was present in the livers of the dead tuna.","zh":"毒素存在於死去吞拿魚的肝臟中。"},{"en":"To be present in something means to exist or be found there.","zh":"存在於某處，是指在那裡存在或被發現。"},{"en":"Doctors may test whether a virus is present in a patient’s blood.","zh":"醫生可能檢測病毒是否存在於病人血液中。"},{"en":"If a toxin is present in an organ, it may show exposure before death.","zh":"如果毒素存在於器官中，它可能顯示死亡前曾暴露於毒物。"},{"en":"This phrase describes evidence found in a place or material.","zh":"這個短語描述在某地或某材料中發現的證據。"}],"source":"74 - The cells from hell.pdf","sourcePage":14},{"front":"the livers of the dead tuna","meaning":"死去吞拿魚的肝臟","examples":[{"en":"The toxin was present in the livers of the dead tuna.","zh":"毒素存在於死去吞拿魚的肝臟中。"},{"en":"The livers of the dead tuna are the liver organs taken from tuna that had died.","zh":"死去吞拿魚的肝臟，是從已死亡吞拿魚身上取出的肝器官。"},{"en":"Scientists may examine fish livers because toxins often collect in organs that process chemicals.","zh":"科學家可能檢查魚肝，因為毒素常積聚在處理化學物的器官中。"},{"en":"Finding poison in liver tissue can support the idea that toxins caused death.","zh":"在肝組織中發現毒物，可以支持毒素導致死亡的說法。"},{"en":"This phrase points to a specific biological sample.","zh":"這個短語指出一種具體生物樣本。"}],"source":"74 - The cells from hell.pdf","sourcePage":14},{"front":"despite this powerful evidence","meaning":"儘管有這項有力證據","examples":[{"en":"Despite this powerful evidence, the official explanation did not change.","zh":"儘管有這項有力證據，官方解釋仍沒有改變。"},{"en":"Despite this powerful evidence means although the evidence was strong.","zh":"儘管有這項有力證據，是指雖然證據很強。"},{"en":"Despite clear video evidence, the company refused to admit the delivery mistake.","zh":"儘管有清楚影片證據，公司仍拒絕承認送貨錯誤。"},{"en":"Strong evidence does not always change official views if other interests are involved.","zh":"如果涉及其他利益，強力證據不一定改變官方看法。"},{"en":"This phrase shows contrast between evidence and response.","zh":"這個短語顯示證據與回應之間的對比。"}],"source":"74 - The cells from hell.pdf","sourcePage":14},{"front":"powerful evidence","meaning":"有力證據","examples":[{"en":"The toxin in the tuna livers was powerful evidence.","zh":"吞拿魚肝臟中的毒素是有力證據。"},{"en":"Powerful evidence is strong information that supports a conclusion.","zh":"有力證據是強烈支持某結論的資料。"},{"en":"A DNA match can be powerful evidence in a criminal investigation.","zh":"DNA 匹配可以是刑事調查中的有力證據。"},{"en":"Powerful evidence makes an explanation much harder to dismiss.","zh":"有力證據會令一個解釋更難被否定。"},{"en":"This phrase refers to evidence with strong persuasive force.","zh":"這個短語指具有強大說服力的證據。"}],"source":"74 - The cells from hell.pdf","sourcePage":14},{"front":"remain","meaning":"仍然是","examples":[{"en":"The official explanation remains that the storm was the killer.","zh":"官方解釋仍然是風暴才是殺手。"},{"en":"To remain means to continue to be the same.","zh":"仍然是，是指繼續保持相同狀態。"},{"en":"The classroom remains closed until repairs are finished.","zh":"課室在維修完成前仍然關閉。"},{"en":"If an explanation remains unchanged despite evidence, people may question it.","zh":"如果解釋在證據面前仍不改變，人們可能質疑它。"},{"en":"This word shows continuation.","zh":"這個詞顯示延續。"}],"source":"74 - The cells from hell.pdf","sourcePage":14},{"front":"the storm was the killer","meaning":"風暴才是殺手","examples":[{"en":"The official explanation remains that the storm was the killer.","zh":"官方解釋仍然是風暴才是殺手。"},{"en":"The storm was the killer means the storm was blamed for causing the deaths.","zh":"風暴才是殺手，是指風暴被指造成死亡。"},{"en":"If fish die after rough weather, officials may claim the storm was the killer.","zh":"如果魚在惡劣天氣後死亡，官員可能聲稱風暴才是殺手。"},{"en":"The phrase personifies the storm as the cause of death.","zh":"這個短語把風暴擬人化為死亡原因。"},{"en":"It contrasts a weather explanation with a possible toxin explanation.","zh":"它把天氣解釋與可能的毒素解釋作對比。"}],"source":"74 - The cells from hell.pdf","sourcePage":14},{"front":"a prime example of","meaning":"……的典型例子","examples":[{"en":"In Japan, this was a prime example of an algal bloom caused by aquaculture waste.","zh":"在日本，這是由水產養殖廢物造成藻華的典型例子。"},{"en":"A prime example of something is a very clear or typical example of it.","zh":"某事的典型例子，是非常清楚或具代表性的例子。"},{"en":"A crowded bus during rush hour is a prime example of urban transport pressure.","zh":"繁忙時間擁擠巴士是城市交通壓力的典型例子。"},{"en":"Prime examples help people understand a pattern because they show it clearly.","zh":"典型例子清楚展示模式，幫助人理解。"},{"en":"This phrase introduces a strong illustrative case.","zh":"這個短語引入強而有力的說明個案。"}],"source":"74 - The cells from hell.pdf","sourcePage":14},{"front":"be induced by","meaning":"由……誘發","examples":[{"en":"The algal bloom was induced by waste products from the aquaculture industry.","zh":"藻華由水產養殖業的廢棄物誘發。"},{"en":"To be induced by something means to be caused or triggered by it.","zh":"由某事誘發，是指由它造成或觸發。"},{"en":"A headache may be induced by lack of sleep and dehydration.","zh":"頭痛可能由睡眠不足和脫水誘發。"},{"en":"Extra nutrients from waste can induce rapid algal growth.","zh":"廢物中的額外養分可以誘發藻類快速生長。"},{"en":"This phrase describes a cause that sets a process in motion.","zh":"這個短語描述啟動過程的原因。"}],"source":"74 - The cells from hell.pdf","sourcePage":14},{"front":"waste products","meaning":"廢棄物","examples":[{"en":"Waste products from aquaculture can induce algal blooms.","zh":"水產養殖產生的廢棄物可以誘發藻華。"},{"en":"Waste products are unwanted materials left after a process or activity.","zh":"廢棄物是某過程或活動後留下的不需要材料。"},{"en":"A factory must treat waste products before releasing water into a river.","zh":"工廠在把水排入河流前必須處理廢棄物。"},{"en":"Waste products can feed algae if they contain nutrients such as nitrogen or phosphorus.","zh":"如果廢棄物含氮或磷等養分，就可以餵養藻類。"},{"en":"This phrase refers to by-products that may harm the environment.","zh":"這個短語指可能傷害環境的副產品。"}],"source":"74 - The cells from hell.pdf","sourcePage":14},{"front":"the aquaculture industry","meaning":"水產養殖業","examples":[{"en":"The aquaculture industry may produce waste that induces algal blooms.","zh":"水產養殖業可能產生誘發藻華的廢棄物。"},{"en":"The aquaculture industry is the business of farming fish, shellfish, or other aquatic organisms.","zh":"水產養殖業是養殖魚類、貝類或其他水生生物的行業。"},{"en":"Fish farms, oyster farms, and shrimp farms are part of the aquaculture industry.","zh":"魚場、蠔場和蝦場都是水產養殖業的一部分。"},{"en":"If waste is poorly managed, aquaculture can damage surrounding waters.","zh":"如果廢物管理不善，水產養殖會損害周邊水域。"},{"en":"This phrase refers to farming in water.","zh":"這個短語指水中的養殖業。"}],"source":"74 - The cells from hell.pdf","sourcePage":14},{"front":"not something that someone wants to hear","meaning":"並非某人想聽到的事","examples":[{"en":"That is not something that the tuna industry wants to hear.","zh":"那並非吞拿魚產業想聽到的事。"},{"en":"Not something that someone wants to hear means information that is unwelcome or damaging to their interests.","zh":"並非某人想聽到的事，是指對其利益不受歡迎或有損害的資訊。"},{"en":"A restaurant owner may not want to hear that poor hygiene caused customer illness.","zh":"餐廳老闆可能不想聽到衛生差導致顧客生病。"},{"en":"People may resist evidence when it threatens money, reputation, or responsibility.","zh":"當證據威脅金錢、聲譽或責任時，人們可能抗拒它。"},{"en":"This phrase shows uncomfortable truth.","zh":"這個短語顯示令人不舒服的真相。"}],"source":"74 - The cells from hell.pdf","sourcePage":15},{"front":"the tuna industry","meaning":"吞拿魚產業","examples":[{"en":"The tuna industry may not want to hear that aquaculture waste is involved.","zh":"吞拿魚產業可能不想聽到水產養殖廢物涉及其中。"},{"en":"The tuna industry includes businesses that catch, farm, process, sell, or export tuna.","zh":"吞拿魚產業包括捕撈、養殖、加工、銷售或出口吞拿魚的企業。"},{"en":"A disease outbreak can damage the tuna industry by reducing supply and trust.","zh":"疾病爆發會透過減少供應和信任來損害吞拿魚產業。"},{"en":"If pollution from fish farming is involved, the industry may face criticism and regulation.","zh":"如果魚類養殖污染涉及其中，該產業可能面對批評和規管。"},{"en":"This phrase refers to the economic sector built around tuna.","zh":"這個短語指圍繞吞拿魚建立的經濟部門。"}],"source":"74 - The cells from hell.pdf","sourcePage":15},{"front":"it is clear that","meaning":"很明顯","examples":[{"en":"It is clear that Chattonella is present in Australian waters.","zh":"很明顯，Chattonella 存在於澳洲水域。"},{"en":"It is clear that means the evidence makes something easy to see or accept.","zh":"很明顯，是指證據令某事容易看出或接受。"},{"en":"It is clear that the road is unsafe when three accidents happen in one week.","zh":"一星期內發生三宗意外，很明顯該道路不安全。"},{"en":"This phrase presents a conclusion with confidence.","zh":"這個短語以信心呈現結論。"},{"en":"It is useful when evidence strongly supports a point.","zh":"當證據強烈支持某觀點時，它很有用。"}],"source":"74 - The cells from hell.pdf","sourcePage":15},{"front":"little knowledge of","meaning":"對……所知甚少","examples":[{"en":"There is little knowledge of what else may surface.","zh":"人們對還有甚麼可能出現所知甚少。"},{"en":"Little knowledge of something means people know very little about it.","zh":"對某事所知甚少，是指人們了解很少。"},{"en":"There may be little knowledge of a rare disease in a small clinic.","zh":"小型診所可能對罕見疾病所知甚少。"},{"en":"Limited knowledge makes planning difficult because dangers are uncertain.","zh":"知識有限會令規劃困難，因為危險並不確定。"},{"en":"This phrase highlights uncertainty and lack of information.","zh":"這個短語突出不確定性和資訊不足。"}],"source":"74 - The cells from hell.pdf","sourcePage":15},{"front":"what else may surface","meaning":"還有甚麼可能出現","examples":[{"en":"Scientists have little knowledge of what else may surface.","zh":"科學家對還有甚麼可能出現所知甚少。"},{"en":"What else may surface means what other hidden problems or organisms may appear.","zh":"還有甚麼可能出現，是指還有哪些隱藏問題或生物可能浮現。"},{"en":"After one leak is found, engineers worry about what else may surface in the old pipes.","zh":"發現一處漏水後，工程師會擔心舊水管還有甚麼可能出現。"},{"en":"Unknown future discoveries make a situation harder to control.","zh":"未知的未來發現會令情況更難控制。"},{"en":"This phrase suggests more problems may emerge later.","zh":"這個短語暗示之後可能有更多問題出現。"}],"source":"74 - The cells from hell.pdf","sourcePage":15},{"front":"where it may have come from","meaning":"它可能來自哪裏","examples":[{"en":"There is little knowledge of where Chattonella may have come from.","zh":"人們對 Chattonella 可能來自哪裏所知甚少。"},{"en":"Where it may have come from means the possible origin or source of something.","zh":"它可能來自哪裏，是指某事物可能的起源或來源。"},{"en":"If a strange smell appears in a school, staff must find where it may have come from.","zh":"如果學校出現怪味，職員必須找出它可能來自哪裏。"},{"en":"Knowing the source helps people stop the problem from returning.","zh":"知道來源有助人們阻止問題再次出現。"},{"en":"This phrase asks about origin, not present location.","zh":"這個短語詢問來源，而不是現在位置。"}],"source":"74 - The cells from hell.pdf","sourcePage":15},{"front":"of greater concern","meaning":"更令人關注的是","examples":[{"en":"Of greater concern is the reluctance to acknowledge human activity.","zh":"更令人關注的是不願承認人類活動。"},{"en":"Of greater concern means more worrying or more important than what was just mentioned.","zh":"更令人關注的是，是指比剛才提到的事情更令人擔心或更重要。"},{"en":"The broken window is a problem, but of greater concern is the weak security system.","zh":"破窗是一個問題，但更令人關注的是薄弱保安系統。"},{"en":"This phrase shifts attention to the more serious issue.","zh":"這個短語把注意力轉向更嚴重議題。"},{"en":"It is often used to rank problems by importance.","zh":"它常用來按重要性排列問題。"}],"source":"74 - The cells from hell.pdf","sourcePage":15},{"front":"a reluctance to acknowledge","meaning":"不願承認","examples":[{"en":"There is a reluctance to acknowledge that human activity is causing the problem.","zh":"人們不願承認人類活動正在造成問題。"},{"en":"A reluctance to acknowledge something means unwillingness to admit or accept it.","zh":"不願承認某事，是指不想承認或接受它。"},{"en":"A company may show reluctance to acknowledge that its product caused injuries.","zh":"公司可能不願承認其產品造成傷害。"},{"en":"People may avoid admitting a cause when it creates responsibility or cost.","zh":"當承認原因會帶來責任或成本，人們可能逃避承認。"},{"en":"This phrase describes resistance to accepting an uncomfortable truth.","zh":"這個短語描述抗拒接受令人不舒服的真相。"}],"source":"74 - The cells from hell.pdf","sourcePage":15},{"front":"human activity","meaning":"人類活動","examples":[{"en":"Human activity may be triggering dangerous transformations in organisms.","zh":"人類活動可能正在觸發生物的危險轉變。"},{"en":"Human activity means actions done by people, such as farming, industry, transport, or waste disposal.","zh":"人類活動是人們做出的行動，例如農業、工業、運輸或廢物處理。"},{"en":"Building roads and releasing waste are examples of human activity that can change ecosystems.","zh":"建路和排放廢物都是可以改變生態系統的人類活動例子。"},{"en":"Human activity can unintentionally create conditions for harmful organisms to grow.","zh":"人類活動可能無意中創造有害生物生長的條件。"},{"en":"This phrase links environmental change to what people do.","zh":"這個短語把環境變化與人類行為連接起來。"}],"source":"74 - The cells from hell.pdf","sourcePage":15},{"front":"trigger the transformation of","meaning":"觸發……的轉變","examples":[{"en":"Human activity can trigger the transformation of benign organisms.","zh":"人類活動可以觸發無害生物的轉變。"},{"en":"To trigger the transformation of something means to cause it to change into a different form or state.","zh":"觸發某物的轉變，是指造成它變成不同形態或狀態。"},{"en":"Heat can trigger the transformation of ice into water.","zh":"熱力可以觸發冰轉變成水。"},{"en":"Pollution may trigger the transformation of harmless algae into toxic forms.","zh":"污染可能觸發無害藻類轉變成有毒形態。"},{"en":"This phrase shows a cause that starts a major change.","zh":"這個短語顯示啟動重大變化的原因。"}],"source":"74 - The cells from hell.pdf","sourcePage":15},{"front":"normally benign organisms","meaning":"通常無害的生物","examples":[{"en":"Normally benign organisms can become increasingly dangerous.","zh":"通常無害的生物可能變得越來越危險。"},{"en":"Normally benign organisms are living things that are usually harmless.","zh":"通常無害的生物，是一般不造成傷害的生物。"},{"en":"Bacteria on skin are normally benign, but some can cause infection if they enter a wound.","zh":"皮膚上的細菌通常無害，但如果進入傷口，有些可能造成感染。"},{"en":"Environmental stress can make harmless organisms behave in harmful ways.","zh":"環境壓力可以令無害生物以有害方式行動。"},{"en":"This phrase contrasts usual safety with possible danger.","zh":"這個短語把通常安全與可能危險作對比。"}],"source":"74 - The cells from hell.pdf","sourcePage":15},{"front":"benign organisms","meaning":"無害生物","examples":[{"en":"Benign organisms may become dangerous under certain conditions.","zh":"無害生物在某些條件下可能變得危險。"},{"en":"Benign organisms are living things that do not normally cause harm.","zh":"無害生物是通常不造成傷害的生物。"},{"en":"Many bacteria in the human gut are benign organisms that help digestion.","zh":"人體腸道中許多細菌是幫助消化的無害生物。"},{"en":"If conditions change, even benign organisms may multiply or produce harmful effects.","zh":"如果條件改變，即使無害生物也可能繁殖或產生有害影響。"},{"en":"This phrase describes harmless or non-threatening life forms.","zh":"這個短語描述無害或不具威脅的生命形式。"}],"source":"74 - The cells from hell.pdf","sourcePage":16},{"front":"increasingly dangerous forms","meaning":"越來越危險的形態","examples":[{"en":"Some organisms are changing into increasingly dangerous forms.","zh":"有些生物正在變成越來越危險的形態。"},{"en":"Increasingly dangerous forms are forms that become more harmful over time.","zh":"越來越危險的形態，是隨時間變得更有害的形態。"},{"en":"A mild virus may become an increasingly dangerous form if it mutates and spreads faster.","zh":"如果溫和病毒突變並傳播更快，它可能變成越來越危險的形態。"},{"en":"Environmental pressure can push organisms toward more harmful behaviour.","zh":"環境壓力可以推動生物走向更有害的行為。"},{"en":"This phrase shows worsening biological risk.","zh":"這個短語顯示惡化中的生物風險。"}],"source":"74 - The cells from hell.pdf","sourcePage":16},{"front":"continue to mismanage","meaning":"繼續管理不善","examples":[{"en":"If we continue to mismanage pollution, new dangers may appear.","zh":"如果我們繼續管理污染不善，新的危險可能出現。"},{"en":"To continue to mismanage something means to keep handling it badly.","zh":"繼續管理不善，是指持續以差劣方式處理某事。"},{"en":"A school will face more complaints if it continues to mismanage safety problems.","zh":"如果學校繼續管理安全問題不善，就會面對更多投訴。"},{"en":"Poor management repeated over time can turn a small issue into a crisis.","zh":"差劣管理反覆持續，會把小問題變成危機。"},{"en":"This phrase criticises ongoing failure to control a problem.","zh":"這個短語批評持續未能控制問題。"}],"source":"74 - The cells from hell.pdf","sourcePage":16},{"front":"nutrients and pollutants","meaning":"養分和污染物","examples":[{"en":"Nutrients and pollutants are released into the environment.","zh":"養分和污染物被排放到環境中。"},{"en":"Nutrients and pollutants are substances that can feed organisms or harm the environment.","zh":"養分和污染物，是可以餵養生物或傷害環境的物質。"},{"en":"Fertiliser nutrients may help crops, but in rivers they can feed algal blooms.","zh":"肥料養分可以幫助農作物，但在河流中會餵養藻華。"},{"en":"Pollutants can poison water, while extra nutrients can upset ecological balance.","zh":"污染物可以毒害水體，而額外養分可以破壞生態平衡。"},{"en":"This phrase groups helpful and harmful substances that become risky when misplaced.","zh":"這個短語把位置不當時會帶來風險的有用和有害物質放在一起。"}],"source":"74 - The cells from hell.pdf","sourcePage":16},{"front":"be released into the environment","meaning":"被排放到環境中","examples":[{"en":"Nutrients and pollutants are released into the environment.","zh":"養分和污染物被排放到環境中。"},{"en":"To be released into the environment means to enter air, water, or land from human or natural sources.","zh":"被排放到環境中，是指從人為或自然來源進入空氣、水或土地。"},{"en":"Factory chemicals may be released into the environment if waste treatment fails.","zh":"如果廢物處理失效，工廠化學物可能被排放到環境中。"},{"en":"Once substances enter the environment, they may spread beyond the original site.","zh":"一旦物質進入環境，它們可能擴散到原地點以外。"},{"en":"This phrase describes movement from a source into nature.","zh":"這個短語描述由來源進入自然界的移動。"}],"source":"74 - The cells from hell.pdf","sourcePage":16},{"front":"confront new versions of","meaning":"面對新版本的……","examples":[{"en":"We may have to confront new versions of the cells from hell.","zh":"我們可能要面對新版本的「地獄細胞」。"},{"en":"To confront new versions of something means to face newer forms of an existing danger.","zh":"面對某事的新版本，是指面對既有危險的新形態。"},{"en":"Doctors may confront new versions of a virus when it mutates.","zh":"當病毒突變，醫生可能面對新版本的病毒。"},{"en":"If pollution keeps changing ecosystems, new dangerous organisms may emerge.","zh":"如果污染持續改變生態系統，新的危險生物可能出現。"},{"en":"This phrase suggests future challenges caused by changing forms.","zh":"這個短語暗示由變化形態造成的未來挑戰。"}],"source":"74 - The cells from hell.pdf","sourcePage":16},{"front":"new versions of the cells from hell","meaning":"新版本的「地獄細胞」","examples":[{"en":"Human activity may create new versions of the cells from hell.","zh":"人類活動可能創造新版本的「地獄細胞」。"},{"en":"New versions of the cells from hell are new harmful microorganisms similar to the dangerous ones described.","zh":"新版本的「地獄細胞」，是類似文中危險微生物的新有害微生物。"},{"en":"A polluted bay might produce new versions of harmful algae if conditions keep worsening.","zh":"如果情況持續惡化，受污染海灣可能產生新版本的有害藻類。"},{"en":"New versions are frightening because scientists may not know their behaviour yet.","zh":"新版本令人害怕，因為科學家可能尚未知道其行為。"},{"en":"This phrase warns that today’s problem could return in different forms.","zh":"這個短語警告今天的問題可能以不同形態回來。"}],"source":"74 - The cells from hell.pdf","sourcePage":16},{"front":"rapid growth","meaning":"快速生長","examples":[{"en":"An algal bloom is the rapid growth of minute aquatic plants.","zh":"藻華是微小水生植物的快速生長。"},{"en":"Rapid growth means very fast increase in size, number, or amount.","zh":"快速生長，是指大小、數量或數額非常快速增加。"},{"en":"A small business may experience rapid growth after a product goes viral online.","zh":"小企業的產品在網上爆紅後，可能經歷快速增長。"},{"en":"Rapid algal growth can change water quality before people notice the danger.","zh":"藻類快速生長可以在人們注意危險前改變水質。"},{"en":"This phrase stresses speed of increase.","zh":"這個短語強調增加速度。"}],"source":"74 - The cells from hell.pdf","sourcePage":16},{"front":"under specific conditions","meaning":"在特定條件下","examples":[{"en":"Algal blooms occur under specific conditions.","zh":"藻華在特定條件下發生。"},{"en":"Under specific conditions means only when certain factors are present.","zh":"在特定條件下，是指只有當某些因素存在時。"},{"en":"Mould grows under specific conditions, such as dampness and poor ventilation.","zh":"霉菌在潮濕和通風差等特定條件下生長。"},{"en":"If the right conditions appear together, a problem can develop quickly.","zh":"如果合適條件同時出現，問題可以迅速發展。"},{"en":"This phrase shows that an event needs particular circumstances.","zh":"這個短語顯示事件需要特定情況。"}],"source":"74 - The cells from hell.pdf","sourcePage":16},{"front":"minute aquatic plants","meaning":"微小水生植物","examples":[{"en":"An algal bloom involves minute aquatic plants.","zh":"藻華涉及微小水生植物。"},{"en":"Minute aquatic plants are extremely small plant-like organisms that live in water.","zh":"微小水生植物是生活在水中的極細小類植物生物。"},{"en":"A drop of pond water may contain minute aquatic plants visible only under a microscope.","zh":"一滴池塘水可能含有只有顯微鏡才看得到的微小水生植物。"},{"en":"Although tiny, these organisms can multiply enough to change a whole lake or bay.","zh":"雖然很小，這些生物可以大量繁殖到改變整個湖泊或海灣。"},{"en":"This phrase refers to very small water-living plant-like life.","zh":"這個短語指非常細小的水生類植物生命。"}],"source":"74 - The cells from hell.pdf","sourcePage":16},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below with words from the passage.","zh":"學生用篇章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the short text that follows.","zh":"完成以下摘要，是指填寫接下來短文中的缺失字詞。"},{"en":"In a reading test, students complete a summary by finding exact information in the passage.","zh":"在閱讀測驗中，學生透過在篇章中找出準確資料完成摘要。"},{"en":"This task checks whether students understand the main points and details.","zh":"這項任務檢查學生是否理解主旨和細節。"},{"en":"The phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"74 - The cells from hell.pdf","sourcePage":16},{"front":"choose your answers from","meaning":"從……中選擇答案","examples":[{"en":"Students choose their answers from the box below the summary.","zh":"學生從摘要下方的方框中選擇答案。"},{"en":"Choose your answers from means select answers only from the given list or place.","zh":"從某處選擇答案，是指只從指定列表或位置選答案。"},{"en":"In a vocabulary quiz, students may choose their answers from a word bank.","zh":"在詞彙小測中，學生可能從詞庫中選擇答案。"},{"en":"This instruction limits possible answers and prevents students from inventing new words.","zh":"這項指示限制可能答案，防止學生自創新詞。"},{"en":"It tells learners where the answer choices are.","zh":"它告訴學習者答案選項在哪裡。"}],"source":"74 - The cells from hell.pdf","sourcePage":17},{"front":"more words than you need","meaning":"字詞多於所需","examples":[{"en":"There are more words than you need, so not all words will be used.","zh":"字詞多於所需，所以不是所有字詞都會被使用。"},{"en":"More words than you need means the list contains extra options.","zh":"字詞多於所需，是指列表包含額外選項。"},{"en":"A teacher may give more words than students need so they must choose carefully.","zh":"老師可能給出多於所需的字詞，讓學生必須仔細選擇。"},{"en":"Extra words make the task harder because some choices are distractors.","zh":"額外字詞令題目更難，因為有些選項是干擾項。"},{"en":"This phrase warns students not to use every option.","zh":"這個短語提醒學生不要使用每個選項。"}],"source":"74 - The cells from hell.pdf","sourcePage":17},{"front":"not use all of them","meaning":"不會全部使用","examples":[{"en":"Students will not use all of the words in the box.","zh":"學生不會使用方框中所有字詞。"},{"en":"Not use all of them means some options should be left unused.","zh":"不會全部使用，是指有些選項應該留空不用。"},{"en":"In a matching exercise, students may not use all of the headings provided.","zh":"在配對練習中，學生可能不會使用所有提供的標題。"},{"en":"Leaving unused options is correct when the instructions give extra choices.","zh":"當指示給出額外選項，留下不用的選項是正確的。"},{"en":"This phrase prevents students from forcing every word into an answer.","zh":"這個短語防止學生強行把每個字詞放入答案。"}],"source":"74 - The cells from hell.pdf","sourcePage":17},{"front":"unusual characteristics","meaning":"不尋常特徵","examples":[{"en":"Pfiesteria is a microorganism with unusual characteristics.","zh":"Pfiesteria 是一種具有不尋常特徵的微生物。"},{"en":"Unusual characteristics are features that are not normal or expected.","zh":"不尋常特徵，是不正常或不符合預期的特點。"},{"en":"A plant that moves quickly has unusual characteristics compared with ordinary houseplants.","zh":"與普通室內植物相比，會快速移動的植物具有不尋常特徵。"},{"en":"Unusual features make scientists investigate more carefully.","zh":"不尋常特徵會令科學家更仔細調查。"},{"en":"This phrase points to traits that make something stand out.","zh":"這個短語指出令某物突出的特質。"}],"source":"74 - The cells from hell.pdf","sourcePage":17},{"front":"under normal conditions","meaning":"在正常情況下","examples":[{"en":"Under normal conditions, Pfiesteria acts like a plant.","zh":"在正常情況下，Pfiesteria 表現得像植物。"},{"en":"Under normal conditions means when circumstances are ordinary and not stressful or unusual.","zh":"在正常情況下，是指環境普通，沒有壓力或不尋常因素。"},{"en":"Under normal conditions, a school bus arrives at the same time every morning.","zh":"在正常情況下，校巴每天早上同一時間到達。"},{"en":"Behaviour can change when conditions stop being normal.","zh":"當情況不再正常，行為可能改變。"},{"en":"This phrase contrasts ordinary situations with special or dangerous ones.","zh":"這個短語把普通情況與特殊或危險情況作對比。"}],"source":"74 - The cells from hell.pdf","sourcePage":17},{"front":"act like","meaning":"表現得像","examples":[{"en":"Under normal conditions, Pfiesteria acts like a plant.","zh":"在正常情況下，Pfiesteria 表現得像植物。"},{"en":"To act like something means to behave in a similar way to it.","zh":"表現得像某物，是指行為方式與它相似。"},{"en":"A shy student may act like a confident speaker after enough practice.","zh":"害羞學生經足夠練習後，可能表現得像自信講者。"},{"en":"Pfiesteria acts like a plant when it photosynthesises, but not when it attacks fish.","zh":"Pfiesteria 進行光合作用時像植物，但攻擊魚時並不像。"},{"en":"This phrase compares behaviour, not identity.","zh":"這個短語比較行為，而不是身份。"}],"source":"74 - The cells from hell.pdf","sourcePage":17},{"front":"develop powerful toxins","meaning":"發展出強力毒素","examples":[{"en":"Pfiesteria has developed powerful toxins as a defence.","zh":"Pfiesteria 已發展出強力毒素作為防衛。"},{"en":"To develop powerful toxins means to produce strong poisons over time.","zh":"發展出強力毒素，是指隨時間產生強烈毒物。"},{"en":"Some animals develop venom to protect themselves from predators.","zh":"有些動物發展出毒液來保護自己免受捕食者傷害。"},{"en":"Powerful toxins can prevent enemies from eating or attacking an organism.","zh":"強力毒素可以阻止敵人吃掉或攻擊某生物。"},{"en":"This phrase connects biological development with survival.","zh":"這個短語把生物發展與生存連接起來。"}],"source":"74 - The cells from hell.pdf","sourcePage":17},{"front":"as a defence against","meaning":"作為抵禦……的防衛","examples":[{"en":"The toxins act as a defence against being eaten by fish.","zh":"這些毒素作為抵禦被魚類吃掉的防衛。"},{"en":"As a defence against something means serving to protect against that danger.","zh":"作為抵禦某危險的防衛，是指用來保護自己免受該危險。"},{"en":"Sunscreen acts as a defence against sunburn.","zh":"防曬霜作為抵禦曬傷的防衛。"},{"en":"Defensive chemicals help small organisms survive when predators try to eat them.","zh":"當捕食者嘗試吃掉小生物，防禦性化學物幫助牠們生存。"},{"en":"This phrase explains the protective purpose of something.","zh":"這個短語解釋某物的保護目的。"}],"source":"74 - The cells from hell.pdf","sourcePage":17},{"front":"be eaten by fish","meaning":"被魚類吃掉","examples":[{"en":"The toxins prevent Pfiesteria from being eaten by fish.","zh":"毒素防止 Pfiesteria 被魚類吃掉。"},{"en":"To be eaten by fish means to become food for fish.","zh":"被魚類吃掉，是指成為魚類的食物。"},{"en":"Tiny insects that fall into a pond may be eaten by fish.","zh":"掉進池塘的小昆蟲可能被魚類吃掉。"},{"en":"Toxins can help a small organism avoid becoming prey.","zh":"毒素可以幫助小生物避免成為獵物。"},{"en":"This phrase describes a predator-prey relationship.","zh":"這個短語描述捕食者與獵物的關係。"}],"source":"74 - The cells from hell.pdf","sourcePage":17},{"front":"be disabled and killed by","meaning":"被……癱瘓並殺死","examples":[{"en":"The fish are disabled and killed by neurotoxins.","zh":"魚類被神經毒素癱瘓並殺死。"},{"en":"To be disabled and killed by something means to be first weakened or paralysed and then killed by it.","zh":"被某物癱瘓並殺死，是指先被削弱或麻痺，然後被殺死。"},{"en":"Insect pests may be disabled and killed by a strong pesticide.","zh":"害蟲可能被強力農藥癱瘓並殺死。"},{"en":"Neurotoxins can stop animals from moving normally before death occurs.","zh":"神經毒素可以在死亡前阻止動物正常移動。"},{"en":"This phrase describes a two-stage harmful effect.","zh":"這個短語描述兩階段有害效果。"}],"source":"74 - The cells from hell.pdf","sourcePage":17},{"front":"neurotoxins","meaning":"神經毒素","examples":[{"en":"Neurotoxins can disable and kill fish.","zh":"神經毒素可以癱瘓並殺死魚類。"},{"en":"Neurotoxins are poisons that affect the nervous system.","zh":"神經毒素是影響神經系統的毒物。"},{"en":"Some snake venoms contain neurotoxins that stop muscles from working properly.","zh":"有些蛇毒含有會令肌肉無法正常工作的神經毒素。"},{"en":"If fish are exposed to neurotoxins, they may become disoriented and unable to swim.","zh":"如果魚類接觸神經毒素，可能變得迷失方向並無法游泳。"},{"en":"This word refers to toxins that attack nerves and brain function.","zh":"這個詞指攻擊神經和大腦功能的毒素。"}],"source":"74 - The cells from hell.pdf","sourcePage":17},{"front":"afterward","meaning":"之後","examples":[{"en":"The organism disappears afterward.","zh":"該生物之後消失。"},{"en":"Afterward means after that event or time.","zh":"之後，是指在那個事件或時間之後。"},{"en":"Students took the test and discussed the answers afterward.","zh":"學生考試後，之後討論答案。"},{"en":"The word helps show what happens after the main action.","zh":"這個詞幫助顯示主要行動後發生甚麼。"},{"en":"In the passage, it explains what happens after Pfiesteria feeds.","zh":"在篇章中，它解釋 Pfiesteria 進食後發生甚麼。"}],"source":"74 - The cells from hell.pdf","sourcePage":18},{"front":"fill in the blanks","meaning":"填空","examples":[{"en":"Students fill in the blanks using words from the passage.","zh":"學生用篇章中的字詞填空。"},{"en":"Fill in the blanks means write missing words in empty spaces.","zh":"填空是指在空格中寫上缺失字詞。"},{"en":"A grammar worksheet may ask students to fill in the blanks with correct verbs.","zh":"文法工作紙可能要求學生用正確動詞填空。"},{"en":"This task checks whether learners understand meaning and grammar.","zh":"這項任務檢查學習者是否理解意思和文法。"},{"en":"The phrase is common in classroom and exam instructions.","zh":"這個短語常見於課堂和考試指示。"}],"source":"74 - The cells from hell.pdf","sourcePage":18},{"front":"no more than three words","meaning":"不超過三個字","examples":[{"en":"Students should use no more than three words from the passage.","zh":"學生應使用篇章中不超過三個字。"},{"en":"No more than three words means the answer can have one, two, or three words, but not four.","zh":"不超過三個字，是指答案可以有一、兩或三個字，但不能有四個。"},{"en":"If the answer is “high levels of pollution,” it has four words and may break the rule.","zh":"如果答案是 “high levels of pollution”，它有四個字，可能違反規則。"},{"en":"Word limits force students to choose exact wording carefully.","zh":"字數限制迫使學生仔細選擇準確措辭。"},{"en":"This phrase gives a strict answer-length rule.","zh":"這個短語給出嚴格答案長度規則。"}],"source":"74 - The cells from hell.pdf","sourcePage":18},{"front":"conditions which favour","meaning":"有利於……的條件","examples":[{"en":"The question asks about conditions which favour toxic algae.","zh":"題目問有利於有毒藻類的條件。"},{"en":"Conditions which favour something are situations that help it grow, happen, or succeed.","zh":"有利於某事的條件，是幫助它生長、發生或成功的情況。"},{"en":"Warm damp weather creates conditions which favour mould in bathrooms.","zh":"溫暖潮濕天氣會創造有利於浴室霉菌的條件。"},{"en":"When pollution and still water combine, they may favour harmful algal growth.","zh":"當污染和靜止水流結合，它們可能有利於有害藻類生長。"},{"en":"This phrase asks what makes a process more likely.","zh":"這個短語詢問甚麼令過程更可能發生。"}],"source":"74 - The cells from hell.pdf","sourcePage":18},{"front":"favour the growth of","meaning":"有利於……生長","examples":[{"en":"Some conditions favour the growth of toxic algae.","zh":"有些條件有利於有毒藻類生長。"},{"en":"To favour the growth of something means to help it grow more easily.","zh":"有利於某物生長，是指幫助它更容易生長。"},{"en":"Warm soil and regular watering favour the growth of seedlings.","zh":"溫暖泥土和定期澆水有利於幼苗生長。"},{"en":"Nutrient-rich pollution can favour the growth of algae in rivers.","zh":"富含養分的污染可以有利於河流中藻類生長。"},{"en":"This phrase describes supportive conditions for growth.","zh":"這個短語描述支持生長的條件。"}],"source":"74 - The cells from hell.pdf","sourcePage":18},{"front":"high levels of","meaning":"高水平的……","examples":[{"en":"High levels of pollution can favour the growth of toxic algae.","zh":"高水平的污染可以有利於有毒藻類生長。"},{"en":"High levels of something means a large amount or concentration of it.","zh":"高水平的某物，是指其數量或濃度很高。"},{"en":"High levels of stress can affect sleep and memory.","zh":"高水平壓力會影響睡眠和記憶。"},{"en":"When high levels of nutrients enter water, algae may multiply quickly.","zh":"當高水平養分進入水中，藻類可能迅速繁殖。"},{"en":"This phrase describes a large or worrying amount.","zh":"這個短語描述大量或令人擔心的程度。"}],"source":"74 - The cells from hell.pdf","sourcePage":18},{"front":"feeding together","meaning":"一起覓食","examples":[{"en":"Large numbers of fish feeding together can favour Pfiesteria.","zh":"大量魚類一起覓食可以有利於 Pfiesteria。"},{"en":"Feeding together means eating in the same place at the same time.","zh":"一起覓食，是指在同一地方同一時間進食。"},{"en":"Birds feeding together near a market may leave a lot of waste behind.","zh":"鳥類在街市附近一起覓食後，可能留下大量廢物。"},{"en":"Group feeding can concentrate food, waste, and biological activity in one area.","zh":"群體覓食會把食物、廢物和生物活動集中在一個區域。"},{"en":"This phrase describes collective eating behaviour.","zh":"這個短語描述集體進食行為。"}],"source":"74 - The cells from hell.pdf","sourcePage":18},{"front":"research scientists","meaning":"研究科學家","examples":[{"en":"Research scientists learned about toxic algae at the conference.","zh":"研究科學家在會議上了解有毒藻類。"},{"en":"Research scientists are scientists who investigate questions and collect evidence.","zh":"研究科學家是調查問題並收集證據的科學家。"},{"en":"Research scientists may spend years studying one disease or ecosystem.","zh":"研究科學家可能花多年研究一種疾病或生態系統。"},{"en":"Their work helps society understand problems before choosing solutions.","zh":"他們的工作幫助社會在選擇解決方法前理解問題。"},{"en":"This phrase refers to scientists whose main job is investigation.","zh":"這個短語指主要工作是研究調查的科學家。"}],"source":"74 - The cells from hell.pdf","sourcePage":18},{"front":"international conference","meaning":"國際會議","examples":[{"en":"Scientists shared information at an international conference.","zh":"科學家在國際會議上分享資訊。"},{"en":"An international conference is a formal meeting attended by people from different countries.","zh":"國際會議是由來自不同國家的人出席的正式會議。"},{"en":"Doctors may attend an international conference to learn about new treatments.","zh":"醫生可能出席國際會議，以了解新治療方法。"},{"en":"Conferences help experts compare evidence and coordinate responses.","zh":"會議幫助專家比較證據並協調回應。"},{"en":"This phrase describes organised global professional exchange.","zh":"這個短語描述有組織的全球專業交流。"}],"source":"74 - The cells from hell.pdf","sourcePage":18},{"front":"classify the following as","meaning":"將以下項目分類為","examples":[{"en":"Students classify the following as being caused by different microorganisms.","zh":"學生將以下項目分類為由不同微生物造成。"},{"en":"To classify the following as something means to sort the listed items into categories.","zh":"將以下項目分類為某類，是指把列出的項目分入類別。"},{"en":"Students may classify the following animals as mammals, birds, or reptiles.","zh":"學生可能將以下動物分類為哺乳類、鳥類或爬蟲類。"},{"en":"Classification helps learners organise information clearly.","zh":"分類幫助學習者清楚整理資訊。"},{"en":"This phrase is common in exam tasks that require grouping.","zh":"這個短語常見於需要分組的考試題。"}],"source":"74 - The cells from hell.pdf","sourcePage":18},{"front":"caused by","meaning":"由……造成","examples":[{"en":"The illness was caused by exposure to toxins.","zh":"該疾病由接觸毒素造成。"},{"en":"Caused by means happened because of a particular reason.","zh":"由某事造成，是指因某個原因而發生。"},{"en":"A traffic jam may be caused by an accident on the main road.","zh":"交通擠塞可能由主幹道上的意外造成。"},{"en":"Knowing what an illness is caused by helps doctors choose treatment.","zh":"知道疾病由甚麼造成，有助醫生選擇治療。"},{"en":"This phrase identifies the source of a result.","zh":"這個短語指出結果來源。"}],"source":"74 - The cells from hell.pdf","sourcePage":18},{"front":"unidentified microorganism","meaning":"身份未明的微生物","examples":[{"en":"Some events were caused by an unidentified microorganism.","zh":"有些事件由身份未明的微生物造成。"},{"en":"An unidentified microorganism is a tiny living thing that has not yet been named or recognised.","zh":"身份未明的微生物，是尚未被命名或識別的微小生物。"},{"en":"A clinic may send samples to a laboratory if an unidentified microorganism is suspected.","zh":"如果懷疑有身份未明的微生物，診所可能把樣本送到實驗室。"},{"en":"Unknown organisms make investigation harder because standard tests may miss them.","zh":"未知生物令調查更難，因為標準檢測可能找不到它們。"},{"en":"This phrase describes a hidden biological cause.","zh":"這個短語描述隱藏的生物原因。"}],"source":"74 - The cells from hell.pdf","sourcePage":19},{"front":"serious illness","meaning":"嚴重疾病","examples":[{"en":"The researcher suffered serious illness after exposure to toxins.","zh":"研究人員接觸毒素後患上嚴重疾病。"},{"en":"Serious illness is a health condition that is severe and may require urgent care.","zh":"嚴重疾病是嚴重並可能需要緊急護理的健康狀況。"},{"en":"A person with serious illness may need hospital treatment and long recovery time.","zh":"患有嚴重疾病的人可能需要住院治療和長時間康復。"},{"en":"Toxic exposure can cause serious illness if it damages organs or the nervous system.","zh":"如果毒素暴露損害器官或神經系統，就可能造成嚴重疾病。"},{"en":"This phrase describes illness beyond minor discomfort.","zh":"這個短語描述超出輕微不適的疾病。"}],"source":"74 - The cells from hell.pdf","sourcePage":19},{"front":"death of sea lions","meaning":"海獅死亡","examples":[{"en":"The death of sea lions was linked to algal blooms.","zh":"海獅死亡與藻華有關。"},{"en":"Death of sea lions means sea lions died, often in numbers large enough to attract attention.","zh":"海獅死亡，是指海獅死去，通常數量足以引起注意。"},{"en":"Scientists may investigate the death of sea lions by testing their food and tissues.","zh":"科學家可能透過檢測海獅的食物和組織來調查海獅死亡。"},{"en":"If toxins move through fish, they can eventually cause deaths in marine mammals.","zh":"如果毒素透過魚類傳遞，最終可以造成海洋哺乳動物死亡。"},{"en":"This phrase describes a visible impact on wildlife.","zh":"這個短語描述對野生動物的可見影響。"}],"source":"74 - The cells from hell.pdf","sourcePage":19},{"front":"off the coast of","meaning":"在……對開海域","examples":[{"en":"Sea lions died off the coast of California.","zh":"海獅在加州對開海域死亡。"},{"en":"Off the coast of a place means in the sea near that land area.","zh":"在某地對開海域，是指在接近該陸地區域的海中。"},{"en":"Fishermen spotted dolphins off the coast of the island.","zh":"漁民在該島對開海域看到海豚。"},{"en":"Events off the coast can affect beaches, fisheries, and coastal towns.","zh":"對開海域發生的事件會影響海灘、漁業和沿海城鎮。"},{"en":"This phrase describes a location near but not on land.","zh":"這個短語描述靠近但不在陸地上的地點。"}],"source":"74 - The cells from hell.pdf","sourcePage":19},{"front":"industry losses","meaning":"產業損失","examples":[{"en":"The passage describes industry losses caused by algal blooms.","zh":"篇章描述由藻華造成的產業損失。"},{"en":"Industry losses are financial losses suffered by a business sector.","zh":"產業損失是某個商業部門承受的財務損失。"},{"en":"A disease outbreak can cause industry losses in tourism if visitors stop travelling.","zh":"如果遊客停止旅遊，疾病爆發可以造成旅遊業產業損失。"},{"en":"When toxic algae close fisheries, companies and workers lose income.","zh":"當有毒藻類令漁場關閉，公司和工人會失去收入。"},{"en":"This phrase connects environmental damage with economic harm.","zh":"這個短語把環境損害與經濟傷害連接起來。"}],"source":"74 - The cells from hell.pdf","sourcePage":19},{"front":"shellfish industry losses","meaning":"貝類海產業損失","examples":[{"en":"New Zealand suffered shellfish industry losses.","zh":"紐西蘭遭受貝類海產業損失。"},{"en":"Shellfish industry losses are financial losses in businesses that farm, collect, or sell shellfish.","zh":"貝類海產業損失，是養殖、採集或銷售貝類的企業所承受的財務損失。"},{"en":"If oysters become unsafe to eat, shellfish industry losses can happen quickly.","zh":"如果蠔變得不安全食用，貝類海產業損失可以很快發生。"},{"en":"Toxic blooms can stop harvesting and damage consumer confidence.","zh":"有毒藻華可以停止採收並損害消費者信心。"},{"en":"This phrase identifies economic damage in a specific seafood sector.","zh":"這個短語指出特定海產行業中的經濟損害。"}],"source":"74 - The cells from hell.pdf","sourcePage":19},{"front":"tuna industry losses","meaning":"吞拿魚產業損失","examples":[{"en":"Australia suffered tuna industry losses in the 1990s.","zh":"澳洲在 1990 年代遭受吞拿魚產業損失。"},{"en":"Tuna industry losses are financial losses affecting tuna farming, fishing, or sales.","zh":"吞拿魚產業損失，是影響吞拿魚養殖、捕撈或銷售的財務損失。"},{"en":"A sudden tuna kill can create tuna industry losses by destroying valuable fish stocks.","zh":"突然吞拿魚大規模死亡會摧毀高價值魚群，造成產業損失。"},{"en":"If customers fear contamination, losses may continue even after the event ends.","zh":"如果顧客害怕污染，即使事件結束後損失仍可能持續。"},{"en":"This phrase identifies economic harm in the tuna sector.","zh":"這個短語指出吞拿魚行業中的經濟傷害。"}],"source":"74 - The cells from hell.pdf","sourcePage":19},{"front":"fish kill","meaning":"魚類大規模死亡","examples":[{"en":"A fish kill occurred in North Carolina in the 1980s.","zh":"1980 年代北卡羅來納州發生魚類大規模死亡。"},{"en":"A fish kill is an event in which many fish die suddenly in the same area.","zh":"魚類大規模死亡，是同一地區大量魚突然死亡的事件。"},{"en":"A polluted river may suffer a fish kill if oxygen levels fall too low.","zh":"如果氧氣水平太低，受污染河流可能出現魚類大規模死亡。"},{"en":"Fish kills warn scientists that water quality or ecosystem balance has changed.","zh":"魚類大規模死亡警告科學家水質或生態平衡已改變。"},{"en":"This phrase is used for mass fish deaths, not one dead fish.","zh":"這個短語用於大量魚死亡，而不是一條死魚。"}],"source":"74 - The cells from hell.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 75":[{"front":"One Who Hopes","meaning":"懷抱希望的人","examples":[{"en":"The title One Who Hopes refers to the meaning of the pseudonym Esperanto.","zh":"標題 One Who Hopes 指 Esperanto 這個筆名的意思。"},{"en":"One who hopes is a person who believes that something good may happen in the future.","zh":"one who hopes 指相信未來可能有好事發生的人。"},{"en":"A student waiting for exam results can be one who hopes for a better chance.","zh":"等待考試結果的學生可以是懷抱希望、等待更好機會的人。"},{"en":"Hope can keep people working even when success is not guaranteed.","zh":"希望可以令人在成功未有保證時仍繼續努力。"},{"en":"In this passage, the phrase links Esperanto with an idealistic dream of peace.","zh":"在這篇文章中，這個短語把世界語與和平的理想夢想連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":1},{"front":"language lovers","meaning":"語言愛好者","examples":[{"en":"Language lovers enjoy variety just as music lovers do.","zh":"語言愛好者喜歡多元化，正如音樂愛好者一樣。"},{"en":"Language lovers are people who enjoy learning, hearing, comparing, or using languages.","zh":"language lovers 指喜歡學習、聆聽、比較或使用語言的人。"},{"en":"A language lover may enjoy hearing different accents on a train.","zh":"語言愛好者可能喜歡在火車上聽到不同口音。"},{"en":"Because they enjoy variety, language lovers may study several languages over time.","zh":"因為他們喜歡多元化，語言愛好者可能多年來學習幾種語言。"},{"en":"This phrase describes interest and affection, not just exam study.","zh":"這個短語描述興趣和熱愛，而不只是考試學習。"}],"source":"75 - One Who Hopes.pdf","sourcePage":1},{"front":"just like","meaning":"正如；就像","examples":[{"en":"Language lovers, just like music lovers, enjoy variety.","zh":"語言愛好者正如音樂愛好者一樣，喜歡多元化。"},{"en":"Just like means in the same way as someone or something else.","zh":"just like 指與某人或某物以相同方式。"},{"en":"Students need practice, just like athletes need training.","zh":"學生需要練習，就像運動員需要訓練一樣。"},{"en":"This phrase helps compare two similar situations clearly.","zh":"這個短語幫助清楚比較兩個相似情況。"},{"en":"It is common in everyday speech and informal explanation.","zh":"它常見於日常說話和非正式解釋。"}],"source":"75 - One Who Hopes.pdf","sourcePage":1},{"front":"enjoy variety","meaning":"喜歡多元化","examples":[{"en":"Language lovers enjoy variety.","zh":"語言愛好者喜歡多元化。"},{"en":"To enjoy variety means to like having many different types, choices, or experiences.","zh":"enjoy variety 指喜歡有很多不同種類、選擇或經驗。"},{"en":"A child may enjoy variety in lunch, with rice one day and noodles the next.","zh":"孩子可能喜歡午餐多元化，今天吃飯，明天吃麵。"},{"en":"Variety can make learning feel less boring and more flexible.","zh":"多元化可以令學習較不沉悶，也更靈活。"},{"en":"This phrase is useful when someone dislikes doing only one kind of thing.","zh":"當某人不喜歡只做同一類事情時，這個短語很有用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":1},{"front":"the latter","meaning":"後者","examples":[{"en":"For the latter, there are many different kinds of music.","zh":"對後者來說，有很多不同種類的音樂。"},{"en":"The latter means the second of two people or things just mentioned.","zh":"the latter 指剛提到的兩個人或事物中的第二個。"},{"en":"I like tea and coffee, but the latter keeps me awake at night.","zh":"我喜歡茶和咖啡，但後者會令我晚上睡不着。"},{"en":"This phrase helps avoid repeating the second noun.","zh":"這個短語有助避免重複第二個名詞。"},{"en":"Students must check the previous sentence to know what the latter refers to.","zh":"學生必須查看上一句，才知道 the latter 指甚麼。"}],"source":"75 - One Who Hopes.pdf","sourcePage":1},{"front":"the former","meaning":"前者","examples":[{"en":"For the former, there are many different languages.","zh":"對前者來說，有很多不同語言。"},{"en":"The former means the first of two people or things just mentioned.","zh":"the former 指剛提到的兩個人或事物中的第一個。"},{"en":"I considered French and Spanish; the former seemed easier for reading.","zh":"我考慮過法語和西班牙語；前者在閱讀上似乎較容易。"},{"en":"This phrase helps writers refer back neatly to the first item.","zh":"這個短語幫助作者簡潔地指回第一項。"},{"en":"It is often used together with the latter.","zh":"它常與 the latter 一起使用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":1},{"front":"Swahili and Urdu","meaning":"斯瓦希里語和烏爾都語","examples":[{"en":"Swahili and Urdu are among the languages mentioned in the passage.","zh":"斯瓦希里語和烏爾都語是文章提到的語言之一。"},{"en":"Swahili and Urdu are examples of real human languages spoken by communities.","zh":"Swahili and Urdu 是由社群使用的真實人類語言例子。"},{"en":"A language class may introduce Swahili and Urdu to show global diversity.","zh":"語言課可能介紹斯瓦希里語和烏爾都語，以展示全球多樣性。"},{"en":"Mentioning different languages helps readers feel how varied language learning can be.","zh":"提到不同語言有助讀者感受到語言學習可以多麼多元。"},{"en":"This phrase names two languages rather than one language family.","zh":"這個短語指兩種語言，而不是一個語系。"}],"source":"75 - One Who Hopes.pdf","sourcePage":1},{"front":"the list is endless","meaning":"名單無窮無盡","examples":[{"en":"There are many languages, and the list is endless.","zh":"語言有很多，名單無窮無盡。"},{"en":"The list is endless means there are so many examples that one cannot easily finish naming them.","zh":"the list is endless 指例子多到難以逐一說完。"},{"en":"In a supermarket, the list of snack choices can feel endless.","zh":"在超級市場，零食選擇名單可能感覺無窮無盡。"},{"en":"This phrase emphasises abundance rather than an actual infinite number.","zh":"這個短語強調數量豐富，而不一定是真正無限。"},{"en":"It is useful when examples are too numerous to list fully.","zh":"當例子太多不能完整列出時，它很有用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":1},{"front":"overworked students","meaning":"學習負擔過重的學生","examples":[{"en":"Overworked students may find language learning difficult.","zh":"學習負擔過重的學生可能覺得語言學習困難。"},{"en":"Overworked students are students who have too much work and too little rest.","zh":"overworked students 指工作或學習太多、休息太少的學生。"},{"en":"A student with school, tutoring, and part-time work may feel overworked.","zh":"同時有學校、補習和兼職的學生可能感到負擔過重。"},{"en":"When students are overworked, even interesting subjects can become stressful.","zh":"當學生負擔過重，即使有趣科目也可以變得有壓力。"},{"en":"This phrase describes pressure from excessive workload.","zh":"這個短語描述來自過量工作量的壓力。"}],"source":"75 - One Who Hopes.pdf","sourcePage":1},{"front":"find learning difficult","meaning":"覺得學習困難","examples":[{"en":"Some students find learning difficult or confusing languages a drudge.","zh":"有些學生覺得學習困難或令人混淆的語言是一件苦差。"},{"en":"To find learning difficult means to feel that studying something is hard to understand or manage.","zh":"find learning difficult 指覺得學習某事難以理解或處理。"},{"en":"A student may find learning difficult if the teacher moves too quickly.","zh":"如果老師教得太快，學生可能覺得學習困難。"},{"en":"When learning feels difficult, students may need simpler steps and more examples.","zh":"當學習感覺困難，學生可能需要更簡單步驟和更多例子。"},{"en":"This phrase describes the learner’s experience, not the subject alone.","zh":"這個短語描述學習者的感受，而不只是科目本身。"}],"source":"75 - One Who Hopes.pdf","sourcePage":1},{"front":"confusing languages","meaning":"令人混淆的語言","examples":[{"en":"Some students struggle with confusing languages.","zh":"有些學生難以應付令人混淆的語言。"},{"en":"Confusing languages are languages that feel difficult because their rules, sounds, or words are hard to separate.","zh":"confusing languages 指因規則、聲音或詞語難以分辨而令人覺得困難的語言。"},{"en":"Learners may find two similar languages confusing if many words look alike.","zh":"如果兩種相似語言有很多詞看起來相似，學習者可能覺得混淆。"},{"en":"Confusion can slow learning because students keep mixing forms together.","zh":"混淆會拖慢學習，因為學生不斷把形式混在一起。"},{"en":"This phrase describes languages from the learner’s point of view.","zh":"這個短語從學習者角度描述語言。"}],"source":"75 - One Who Hopes.pdf","sourcePage":1},{"front":"a drudge","meaning":"苦差；沉悶費力的工作","examples":[{"en":"Some students find learning difficult languages a drudge.","zh":"有些學生覺得學習困難語言是一件苦差。"},{"en":"A drudge is a boring, tiring, and unpleasant piece of work.","zh":"drudge 指沉悶、疲累而令人不快的工作。"},{"en":"Copying the same sentence one hundred times can feel like a drudge.","zh":"把同一句抄一百次可能感覺像苦差。"},{"en":"When learning becomes a drudge, students may lose motivation.","zh":"當學習變成苦差，學生可能失去動力。"},{"en":"This word is negative and describes work that feels dull and heavy.","zh":"這個詞帶負面意思，描述沉悶而沉重的工作。"}],"source":"75 - One Who Hopes.pdf","sourcePage":2},{"front":"put a smile on someone’s face","meaning":"令某人展露笑容","examples":[{"en":"A simple language might put a smile on students’ faces.","zh":"一種簡單語言可能令學生展露笑容。"},{"en":"To put a smile on someone’s face means to make someone happy or relieved.","zh":"put a smile on someone’s face 指令某人開心或鬆一口氣。"},{"en":"A kind message from a teacher can put a smile on a tired student’s face.","zh":"老師一句善意訊息可以令疲倦學生展露笑容。"},{"en":"When a task becomes easier, it can reduce stress and create satisfaction.","zh":"當任務變得較容易，它可以減少壓力並帶來滿足感。"},{"en":"This phrase is warm and informal.","zh":"這個短語語氣溫暖而較非正式。"}],"source":"75 - One Who Hopes.pdf","sourcePage":2},{"front":"easy-to-learn tongue","meaning":"易學的語言","examples":[{"en":"Esperanto was designed as a simple, easy-to-learn tongue.","zh":"世界語被設計成一種簡單、易學的語言。"},{"en":"An easy-to-learn tongue is a language that learners can pick up with less difficulty.","zh":"easy-to-learn tongue 指學習者可以較輕鬆掌握的語言。"},{"en":"A language with regular grammar may be an easy-to-learn tongue for beginners.","zh":"文法規則整齊的語言，對初學者來說可能是易學語言。"},{"en":"If a tongue is easy to learn, students can spend less time memorising exceptions.","zh":"如果一種語言容易學，學生可以少花時間記例外。"},{"en":"This phrase uses tongue to mean language.","zh":"這個短語中的 tongue 指語言。"}],"source":"75 - One Who Hopes.pdf","sourcePage":2},{"front":"cut study time by years","meaning":"把學習時間縮短多年","examples":[{"en":"A simple language could cut students’ study time by years.","zh":"一種簡單語言可以把學生的學習時間縮短多年。"},{"en":"To cut study time by years means to reduce the time needed for learning by several years.","zh":"cut study time by years 指把所需學習時間減少好幾年。"},{"en":"A clear learning system can cut study time by helping students avoid wasted effort.","zh":"清晰學習系統可以幫助學生避免浪費力氣，從而縮短學習時間。"},{"en":"If grammar is regular, learners may progress faster and need less time.","zh":"如果文法規則整齊，學習者可能進步更快，需要較少時間。"},{"en":"This phrase emphasises a large saving of time.","zh":"這個短語強調大量節省時間。"}],"source":"75 - One Who Hopes.pdf","sourcePage":2},{"front":"it has been around for","meaning":"已經存在了……","examples":[{"en":"Esperanto has been around for more than 120 years.","zh":"世界語已經存在超過120年。"},{"en":"It has been around for means it has existed for a certain period of time.","zh":"it has been around for 指某物已經存在某段時間。"},{"en":"That family restaurant has been around for fifty years.","zh":"那間家庭餐廳已經存在五十年。"},{"en":"When something has been around for a long time, people may trust it more.","zh":"當某物存在很久，人們可能更信任它。"},{"en":"This phrase is common in informal explanation of history.","zh":"這個短語常見於非正式歷史解釋。"}],"source":"75 - One Who Hopes.pdf","sourcePage":2},{"front":"widely spoken","meaning":"廣泛使用的","examples":[{"en":"Esperanto is the most widely spoken constructed international language.","zh":"世界語是最廣泛使用的人工建構國際語言。"},{"en":"Widely spoken means used by many speakers in many places.","zh":"widely spoken 指在許多地方由許多人使用。"},{"en":"English is widely spoken in international business and travel.","zh":"英語在國際商業和旅遊中被廣泛使用。"},{"en":"A widely spoken language can help people communicate across borders.","zh":"廣泛使用的語言可以幫助人們跨越國界溝通。"},{"en":"This phrase describes the spread of language use.","zh":"這個短語描述語言使用的廣泛程度。"}],"source":"75 - One Who Hopes.pdf","sourcePage":2},{"front":"artificially constructed","meaning":"人工創造的","examples":[{"en":"Esperanto is an artificially constructed international language.","zh":"世界語是一種人工創造的國際語言。"},{"en":"Artificially constructed means deliberately created by people rather than naturally developed over centuries.","zh":"artificially constructed 指由人有意創造，而不是經數百年自然發展。"},{"en":"A classroom code made by students is artificially constructed.","zh":"學生自己製作的課室密碼是人工創造的。"},{"en":"Because it was planned, Esperanto can have simpler and more regular rules.","zh":"因為世界語是被規劃的，它可以有較簡單而規則的規則。"},{"en":"This phrase contrasts planned design with natural historical growth.","zh":"這個短語把有計劃設計與自然歷史發展作對比。"}],"source":"75 - One Who Hopes.pdf","sourcePage":2},{"front":"international language","meaning":"國際語言","examples":[{"en":"Esperanto was created as an international language.","zh":"世界語被創造成一種國際語言。"},{"en":"An international language is used or intended for communication between people from different countries.","zh":"international language 指用於或旨在用於不同國家人士之間溝通的語言。"},{"en":"Airports often use an international language to guide travellers from many places.","zh":"機場常使用國際語言指引來自多地的旅客。"},{"en":"Such a language can reduce communication barriers across borders.","zh":"這類語言可以減少跨國溝通障礙。"},{"en":"This phrase focuses on use beyond one nation.","zh":"這個短語聚焦超越單一國家的使用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":2},{"front":"derive from","meaning":"源自；來自","examples":[{"en":"The name Esperanto derives from Doktoro Esperanto.","zh":"Esperanto 這個名稱源自 Doktoro Esperanto。"},{"en":"To derive from something means to come from it as a source or origin.","zh":"derive from something 指源於某來源或起源。"},{"en":"The word school derives from an ancient Greek word.","zh":"school 這個字源自古希臘語。"},{"en":"Knowing where a word derives from can help learners remember it.","zh":"知道一個詞源自哪裏，可以幫助學習者記住它。"},{"en":"This phrase is common in language history and explanation.","zh":"這個短語常見於語言歷史和解釋。"}],"source":"75 - One Who Hopes.pdf","sourcePage":2},{"front":"pseudonym","meaning":"筆名；化名","examples":[{"en":"Doktoro Esperanto was the pseudonym used by L. L. Zamenhof.","zh":"Doktoro Esperanto 是 L. L. Zamenhof 使用的筆名。"},{"en":"A pseudonym is a false or pen name used instead of a person’s real name.","zh":"pseudonym 指代替真名使用的假名或筆名。"},{"en":"A writer may use a pseudonym to protect privacy or create a public identity.","zh":"作家可能使用筆名以保護私隱或創造公眾身份。"},{"en":"If a book is published under a pseudonym, readers may not know the author’s real name at first.","zh":"如果一本書以筆名出版，讀者起初可能不知道作者真名。"},{"en":"This word is common in literature and publishing.","zh":"這個詞常見於文學和出版語境。"}],"source":"75 - One Who Hopes.pdf","sourcePage":2},{"front":"under which","meaning":"以……名義","examples":[{"en":"Doktoro Esperanto was the name under which Zamenhof published Unua Libro.","zh":"Doktoro Esperanto 是 Zamenhof 出版《第一書》時使用的名義。"},{"en":"Under which means using that name, title, rule, or condition.","zh":"under which 指使用該名稱、標題、規則或條件。"},{"en":"A singer may release music under a stage name.","zh":"歌手可能以藝名發行音樂。"},{"en":"Publishing under another name can separate private identity from public work.","zh":"以另一個名稱出版，可以把私人身份與公開作品分開。"},{"en":"This phrase is formal and often refers to names or conditions.","zh":"這個短語較正式，常指名稱或條件。"}],"source":"75 - One Who Hopes.pdf","sourcePage":2},{"front":"first published","meaning":"首次出版","examples":[{"en":"Zamenhof first published Unua Libro in 1887.","zh":"Zamenhof 於1887年首次出版《第一書》。"},{"en":"First published means made available to the public for the first time.","zh":"first published 指首次向公眾發行或公開。"},{"en":"A novel may be first published online before appearing as a printed book.","zh":"小說可能先在網上首次出版，然後才以印刷書形式出現。"},{"en":"The first publication date helps readers place a work in history.","zh":"首次出版日期幫助讀者把作品放入歷史背景。"},{"en":"This phrase is common in books, articles, and research.","zh":"這個短語常見於書籍、文章和研究。"}],"source":"75 - One Who Hopes.pdf","sourcePage":3},{"front":"Unua Libro","meaning":"《第一書》","examples":[{"en":"Zamenhof first published Unua Libro in 1887.","zh":"Zamenhof 於1887年首次出版《第一書》。"},{"en":"Unua Libro was the first book presenting the basic grammar and idea of Esperanto.","zh":"Unua Libro 是介紹世界語基本語法和理念的第一本書。"},{"en":"A first book can introduce a new system before a wider movement begins.","zh":"第一本書可以在更大運動開始前介紹新系統。"},{"en":"Because Unua Libro explained Esperanto, it helped early learners start using the language.","zh":"因為《第一書》解釋世界語，它幫助早期學習者開始使用這種語言。"},{"en":"This title is important because it marks Esperanto’s public beginning.","zh":"這個書名很重要，因為它標誌世界語的公開開始。"}],"source":"75 - One Who Hopes.pdf","sourcePage":3},{"front":"mean one who hopes","meaning":"意思是懷抱希望的人","examples":[{"en":"The pseudonym itself means one who hopes.","zh":"這個筆名本身意思是懷抱希望的人。"},{"en":"To mean one who hopes is to carry the meaning of a person who has hope.","zh":"mean one who hopes 指帶有「懷有希望的人」這個意思。"},{"en":"A name can express a value, such as courage, peace, or hope.","zh":"名字可以表達一種價值，例如勇氣、和平或希望。"},{"en":"Because the name suggests hope, it matches the language’s idealistic purpose.","zh":"因為這個名字暗示希望，它配合這種語言的理想主義目的。"},{"en":"This phrase explains the meaning hidden inside a name.","zh":"這個短語解釋名字中隱含的意思。"}],"source":"75 - One Who Hopes.pdf","sourcePage":3},{"front":"create an easy and flexible language","meaning":"創造一種簡單而靈活的語言","examples":[{"en":"Zamenhof wanted to create an easy and flexible language.","zh":"Zamenhof 想創造一種簡單而靈活的語言。"},{"en":"To create an easy and flexible language means to design a language that is simple to learn and adaptable to use.","zh":"create an easy and flexible language 指設計一種容易學習且可靈活使用的語言。"},{"en":"A teacher may create an easy and flexible learning system for mixed-level students.","zh":"老師可能為程度不同的學生創造一套簡單而靈活的學習系統。"},{"en":"Simplicity helps beginners, while flexibility lets users express many ideas.","zh":"簡單性幫助初學者，而靈活性讓使用者表達許多想法。"},{"en":"This phrase describes both design and purpose.","zh":"這個短語同時描述設計和目的。"}],"source":"75 - One Who Hopes.pdf","sourcePage":3},{"front":"universal second language","meaning":"通用第二語言","examples":[{"en":"Zamenhof designed Esperanto as a universal second language.","zh":"Zamenhof 把世界語設計成一種通用第二語言。"},{"en":"A universal second language is a shared additional language that people from many countries could learn.","zh":"universal second language 指來自許多國家的人都可以學習的共同附加語言。"},{"en":"If everyone learned one common second language, international meetings could become easier.","zh":"如果每個人都學一種共同第二語言，國際會議可以變得更容易。"},{"en":"Such a language would not replace mother tongues but help communication between them.","zh":"這種語言不會取代母語，而是幫助不同母語者之間溝通。"},{"en":"This phrase expresses Esperanto’s global purpose.","zh":"這個短語表達世界語的全球目的。"}],"source":"75 - One Who Hopes.pdf","sourcePage":3},{"front":"promote peace","meaning":"促進和平","examples":[{"en":"Esperanto was intended to promote peace.","zh":"世界語原意是促進和平。"},{"en":"To promote peace means to encourage friendly relations and reduce conflict.","zh":"promote peace 指鼓勵友好關係並減少衝突。"},{"en":"Schools can promote peace by teaching students how to solve arguments calmly.","zh":"學校可以透過教學生冷靜解決爭執來促進和平。"},{"en":"Better communication can reduce misunderstanding, which may lower tension.","zh":"更好的溝通可以減少誤解，從而降低緊張。"},{"en":"This phrase is often used in social, political, and educational contexts.","zh":"這個短語常用於社會、政治和教育語境。"}],"source":"75 - One Who Hopes.pdf","sourcePage":3},{"front":"international understanding","meaning":"國際理解","examples":[{"en":"Esperanto aimed to promote international understanding.","zh":"世界語旨在促進國際理解。"},{"en":"International understanding is the ability of people from different countries to understand one another’s ideas, needs, and cultures.","zh":"international understanding 指不同國家的人理解彼此想法、需要和文化的能力。"},{"en":"Student exchange programmes can build international understanding.","zh":"學生交流計劃可以建立國際理解。"},{"en":"When people understand each other better, stereotypes and conflict may decrease.","zh":"當人們更理解彼此，刻板印象和衝突可能減少。"},{"en":"This phrase links communication with peace and cooperation.","zh":"這個短語把溝通與和平合作連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":3},{"front":"after ten years of developing","meaning":"經過十年的發展","examples":[{"en":"After ten years of developing Esperanto, Zamenhof published its first grammar.","zh":"經過十年發展世界語後，Zamenhof 出版了第一部語法書。"},{"en":"After ten years of developing means after spending a decade creating and improving something.","zh":"after ten years of developing 指花了十年創造和改進某物之後。"},{"en":"After years of developing a course, a teacher may finally publish the materials.","zh":"經過多年發展課程後，老師可能終於出版教材。"},{"en":"Long development can make a system more complete before it reaches users.","zh":"長期發展可以令一個系統在到達使用者前更完整。"},{"en":"This phrase shows time, effort, and preparation before a result.","zh":"這個短語顯示結果之前的時間、努力和準備。"}],"source":"75 - One Who Hopes.pdf","sourcePage":3},{"front":"brainchild","meaning":"心血結晶；構思成果","examples":[{"en":"Esperanto was Zamenhof’s brainchild.","zh":"世界語是 Zamenhof 的心血結晶。"},{"en":"A brainchild is an idea, plan, or creation that comes from someone’s thinking.","zh":"brainchild 指來自某人思考的想法、計劃或創作。"},{"en":"The new reading club was the brainchild of a young librarian.","zh":"新閱讀會是一位年輕圖書館員的構思成果。"},{"en":"When a project is someone’s brainchild, that person is closely linked to its origin.","zh":"當一個項目是某人的 brainchild，那個人與其起源密切相關。"},{"en":"This word is warm and often used for creative inventions.","zh":"這個詞語氣溫和，常用於創意發明。"}],"source":"75 - One Who Hopes.pdf","sourcePage":3},{"front":"from the late 1870s to the early 1880s","meaning":"從1870年代末至1880年代初","examples":[{"en":"Zamenhof developed Esperanto from the late 1870s to the early 1880s.","zh":"Zamenhof 從1870年代末至1880年代初發展世界語。"},{"en":"From the late 1870s to the early 1880s means during the period starting near the end of the 1870s and ending near the start of the 1880s.","zh":"from the late 1870s to the early 1880s 指由1870年代後期開始，到1880年代初期結束的時期。"},{"en":"A family business may have changed greatly from the late 1990s to the early 2000s.","zh":"一間家族企業可能從1990年代末至2000年代初有巨大變化。"},{"en":"A time range helps readers understand how long development took.","zh":"時間範圍幫助讀者理解發展花了多久。"},{"en":"This phrase gives a historical period rather than one exact date.","zh":"這個短語提供歷史時期，而不是單一精確日期。"}],"source":"75 - One Who Hopes.pdf","sourcePage":3},{"front":"the first Esperanto grammar","meaning":"第一部世界語語法書","examples":[{"en":"Zamenhof published the first Esperanto grammar in Warsaw.","zh":"Zamenhof 在華沙出版了第一部世界語語法書。"},{"en":"The first Esperanto grammar was the earliest guide explaining the rules of Esperanto.","zh":"first Esperanto grammar 指最早解釋世界語規則的指南。"},{"en":"A grammar book helps learners know how to form sentences correctly.","zh":"語法書幫助學習者知道如何正確構成句子。"},{"en":"Publishing the grammar allowed more people to learn the language systematically.","zh":"出版語法書讓更多人有系統地學習這種語言。"},{"en":"This phrase refers to a key document in Esperanto’s early history.","zh":"這個短語指世界語早期歷史中的關鍵文件。"}],"source":"75 - One Who Hopes.pdf","sourcePage":3},{"front":"the number of speakers","meaning":"使用者人數","examples":[{"en":"The number of speakers grew rapidly over the next few decades.","zh":"使用者人數在隨後數十年間快速增長。"},{"en":"The number of speakers means how many people can speak a language.","zh":"number of speakers 指能說某種語言的人數。"},{"en":"A language school may count the number of speakers to measure growth.","zh":"語言學校可能統計使用者人數以衡量增長。"},{"en":"When speaker numbers rise, a language community becomes easier to maintain.","zh":"當使用者人數上升，語言社群會更容易維持。"},{"en":"This phrase is common in language statistics.","zh":"這個短語常見於語言統計。"}],"source":"75 - One Who Hopes.pdf","sourcePage":4},{"front":"grow rapidly","meaning":"快速增長","examples":[{"en":"The number of Esperanto speakers grew rapidly.","zh":"世界語使用者人數快速增長。"},{"en":"To grow rapidly means to increase quickly.","zh":"grow rapidly 指快速增加。"},{"en":"A school club may grow rapidly after students share it online.","zh":"學校學會在學生網上分享後可能快速增長。"},{"en":"Rapid growth can create excitement but also pressure on organisation.","zh":"快速增長可以帶來興奮，也可以對組織造成壓力。"},{"en":"This phrase describes fast increase in number or size.","zh":"這個短語描述數量或規模快速增加。"}],"source":"75 - One Who Hopes.pdf","sourcePage":4},{"front":"over the next few decades","meaning":"在隨後數十年間","examples":[{"en":"Esperanto spread over the next few decades.","zh":"世界語在隨後數十年間傳播開去。"},{"en":"Over the next few decades means during the following several periods of ten years.","zh":"over the next few decades 指在之後幾個十年期間。"},{"en":"A city may change greatly over the next few decades.","zh":"一個城市在隨後數十年間可能大幅改變。"},{"en":"This phrase is useful for describing slow but long-term development.","zh":"這個短語適合描述緩慢但長期的發展。"},{"en":"It gives a broad future or historical time frame.","zh":"它提供廣泛的未來或歷史時間框架。"}],"source":"75 - One Who Hopes.pdf","sourcePage":4},{"front":"primarily in","meaning":"主要在……","examples":[{"en":"Esperanto first spread primarily in the Russian Empire and Eastern Europe.","zh":"世界語最初主要在俄羅斯帝國和東歐傳播。"},{"en":"Primarily in means mainly in a particular place or area.","zh":"primarily in 指主要在某個地方或地區。"},{"en":"A shop may sell primarily in local markets before going online.","zh":"商店可能先主要在本地市場銷售，然後才上網。"},{"en":"Saying primarily in leaves room for smaller activity elsewhere.","zh":"說 primarily in 仍容許其他地方有較小規模活動。"},{"en":"This phrase identifies the main location of an action.","zh":"這個短語指出行動的主要地點。"}],"source":"75 - One Who Hopes.pdf","sourcePage":4},{"front":"the Russian Empire","meaning":"俄羅斯帝國","examples":[{"en":"Esperanto first became popular in the Russian Empire and Eastern Europe.","zh":"世界語最初在俄羅斯帝國和東歐流行起來。"},{"en":"The Russian Empire was a historical state that existed before the Soviet Union.","zh":"Russian Empire 指蘇聯之前存在的歷史國家。"},{"en":"A historical empire may contain many languages, ethnic groups, and regions.","zh":"歷史帝國可能包含許多語言、民族和地區。"},{"en":"A multilingual empire can create demand for easier cross-language communication.","zh":"多語帝國可以產生對更容易跨語言溝通的需求。"},{"en":"This phrase gives historical and geographical context.","zh":"這個短語提供歷史和地理背景。"}],"source":"75 - One Who Hopes.pdf","sourcePage":4},{"front":"Eastern Europe","meaning":"東歐","examples":[{"en":"Esperanto first spread in Eastern Europe.","zh":"世界語最初在東歐傳播。"},{"en":"Eastern Europe means the eastern part of Europe.","zh":"Eastern Europe 指歐洲東部。"},{"en":"A travel course may compare Eastern Europe with Western Europe in history and culture.","zh":"旅遊課程可能在歷史和文化上比較東歐與西歐。"},{"en":"Regional labels help readers understand where an event first became important.","zh":"地區標籤幫助讀者理解事件最初在哪裏變得重要。"},{"en":"This phrase gives a broad geographical area.","zh":"這個短語提供廣泛地理區域。"}],"source":"75 - One Who Hopes.pdf","sourcePage":4},{"front":"Western Europe","meaning":"西歐","examples":[{"en":"Esperanto later spread to Western Europe.","zh":"世界語後來傳到西歐。"},{"en":"Western Europe means the western part of Europe.","zh":"Western Europe 指歐洲西部。"},{"en":"Many students visit Western Europe to study languages, art, and history.","zh":"許多學生到西歐學習語言、藝術和歷史。"},{"en":"When an idea spreads to a new region, its audience and influence can grow.","zh":"當一個想法傳到新地區，其受眾和影響可以擴大。"},{"en":"This phrase gives geographical direction and cultural context.","zh":"這個短語提供地理方向和文化背景。"}],"source":"75 - One Who Hopes.pdf","sourcePage":4},{"front":"the Americas","meaning":"美洲","examples":[{"en":"The language later reached the Americas, China and Japan.","zh":"這種語言後來傳到美洲、中國和日本。"},{"en":"The Americas refers to North America, Central America, South America, and nearby regions.","zh":"the Americas 指北美洲、中美洲、南美洲及附近地區。"},{"en":"A language movement reaching the Americas would gain a much wider audience.","zh":"語言運動傳到美洲，就會得到更廣泛受眾。"},{"en":"Global spread shows that a language can move beyond its original region.","zh":"全球傳播顯示語言可以超越原本地區。"},{"en":"This phrase is geographical and plural in form.","zh":"這個短語是地理用語，形式上是複數。"}],"source":"75 - One Who Hopes.pdf","sourcePage":4},{"front":"keep in contact","meaning":"保持聯絡","examples":[{"en":"Early Esperanto speakers kept in contact through letters and magazines.","zh":"早期世界語使用者透過書信和雜誌保持聯絡。"},{"en":"To keep in contact means to continue communicating with someone.","zh":"keep in contact 指繼續與某人溝通。"},{"en":"Friends who move to different cities may keep in contact by messaging weekly.","zh":"搬到不同城市的朋友可以透過每週傳訊息保持聯絡。"},{"en":"Regular contact helps a community stay active even when members live far apart.","zh":"定期聯絡幫助社群即使成員相距很遠仍保持活躍。"},{"en":"This phrase is useful for relationships and networks.","zh":"這個短語適用於關係和網絡。"}],"source":"75 - One Who Hopes.pdf","sourcePage":4},{"front":"primarily through","meaning":"主要透過……","examples":[{"en":"Early speakers kept in contact primarily through correspondence and periodicals.","zh":"早期使用者主要透過書信往來和期刊保持聯絡。"},{"en":"Primarily through means mainly by using a particular method.","zh":"primarily through 指主要使用某種方法。"},{"en":"A remote team may communicate primarily through email and video calls.","zh":"遙距團隊可能主要透過電郵和視像通話溝通。"},{"en":"The main method of contact shapes how quickly information spreads.","zh":"主要聯絡方式會塑造資訊傳播速度。"},{"en":"This phrase identifies the chief channel or means.","zh":"這個短語指出主要渠道或方法。"}],"source":"75 - One Who Hopes.pdf","sourcePage":4},{"front":"correspondence","meaning":"書信往來","examples":[{"en":"Early Esperanto speakers communicated through correspondence.","zh":"早期世界語使用者透過書信往來溝通。"},{"en":"Correspondence means communication by letters, emails, or written messages.","zh":"correspondence 指透過信件、電郵或書面訊息溝通。"},{"en":"A school may keep correspondence with parents through email.","zh":"學校可能透過電郵與家長保持書信往來。"},{"en":"Written correspondence helps people communicate even when they cannot meet.","zh":"書面往來幫助人們即使不能見面也能溝通。"},{"en":"This word is formal and often refers to written exchange.","zh":"這個詞較正式，常指書面交流。"}],"source":"75 - One Who Hopes.pdf","sourcePage":4},{"front":"periodicals","meaning":"期刊","examples":[{"en":"Esperanto speakers kept in contact through periodicals.","zh":"世界語使用者透過期刊保持聯絡。"},{"en":"Periodicals are magazines, journals, or publications released regularly.","zh":"periodicals 指定期出版的雜誌、期刊或刊物。"},{"en":"A monthly school magazine is a periodical.","zh":"每月出版的校刊是一種期刊。"},{"en":"Periodicals help communities share news, ideas, and announcements over time.","zh":"期刊幫助社群長期分享消息、想法和公告。"},{"en":"This word is common in publishing and library contexts.","zh":"這個詞常見於出版和圖書館語境。"}],"source":"75 - One Who Hopes.pdf","sourcePage":5},{"front":"world congresses","meaning":"世界大會","examples":[{"en":"World congresses for Esperanto speakers have been held since 1905.","zh":"世界語使用者的世界大會自1905年以來一直舉行。"},{"en":"World congresses are large international meetings where people gather to discuss shared interests.","zh":"world congresses 指人們聚集討論共同興趣的大型國際會議。"},{"en":"Doctors may attend world congresses to learn about new treatments.","zh":"醫生可能參加世界大會以了解新療法。"},{"en":"Such meetings help scattered communities feel connected and active.","zh":"這類會議幫助分散各地的社群感到連結和活躍。"},{"en":"This phrase suggests organised global participation.","zh":"這個短語暗示有組織的全球參與。"}],"source":"75 - One Who Hopes.pdf","sourcePage":5},{"front":"be held on five continents","meaning":"在五大洲舉行","examples":[{"en":"Esperanto world congresses have been held on five continents.","zh":"世界語世界大會曾在五大洲舉行。"},{"en":"To be held on five continents means to take place in locations across five continents.","zh":"be held on five continents 指在橫跨五大洲的地點舉行。"},{"en":"An international sports event may be held on different continents over many years.","zh":"國際體育賽事可能多年來在不同大洲舉行。"},{"en":"Holding events widely shows that a movement has global reach.","zh":"廣泛舉辦活動顯示一個運動具有全球影響。"},{"en":"This phrase emphasises geographical spread.","zh":"這個短語強調地理擴散。"}],"source":"75 - One Who Hopes.pdf","sourcePage":5},{"front":"except during","meaning":"除了在……期間","examples":[{"en":"The congresses were held every year except during the two world wars.","zh":"這些大會每年舉行，除了在兩次世界大戰期間。"},{"en":"Except during means not in a particular period, although it happens at other times.","zh":"except during 指某事在其他時間發生，但不在某特定時期發生。"},{"en":"The library opens daily except during public holidays.","zh":"圖書館每天開放，除了在公眾假期期間。"},{"en":"This phrase explains an interruption in a regular pattern.","zh":"這個短語解釋規律模式中的中斷。"},{"en":"It is useful when a rule has a clear time-based exception.","zh":"當規則有明確時間例外時，它很有用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":5},{"front":"recent estimates put","meaning":"最近估計……為","examples":[{"en":"Recent estimates put the number of Esperanto speakers at around 2 million.","zh":"最近估計世界語使用者人數約為二百萬。"},{"en":"Recent estimates put means newer calculations suggest a particular number or level.","zh":"recent estimates put 指較新的估算顯示某個數字或水平。"},{"en":"Recent estimates put the cost of the project at about ten million dollars.","zh":"最近估計該項目成本約為一千萬美元。"},{"en":"Estimates are useful when exact counting is difficult.","zh":"當精確點算困難時，估計很有用。"},{"en":"This phrase is formal and common in reports.","zh":"這個短語較正式，常見於報告。"}],"source":"75 - One Who Hopes.pdf","sourcePage":5},{"front":"around 2 million","meaning":"約二百萬","examples":[{"en":"Esperanto has around 2 million speakers.","zh":"世界語約有二百萬使用者。"},{"en":"Around 2 million means approximately two million, not an exact number.","zh":"around 2 million 指大約二百萬，不是精確數字。"},{"en":"A city with around 2 million residents needs strong transport and hospitals.","zh":"約有二百萬居民的城市需要強大的交通和醫院。"},{"en":"Approximate numbers help readers understand scale without claiming perfect precision.","zh":"約數幫助讀者理解規模，而不聲稱完全精確。"},{"en":"This phrase is useful when exact figures are uncertain.","zh":"當確切數字不確定時，這個短語很有用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":5},{"front":"put in percentage terms","meaning":"以百分比來說","examples":[{"en":"Put in percentage terms, the number is about 0.03 per cent of the world’s population.","zh":"以百分比來說，這個數字約佔世界人口的0.03%。"},{"en":"Put in percentage terms means expressed as a percentage rather than a raw number.","zh":"put in percentage terms 指以百分比而不是原始數字表達。"},{"en":"A teacher may put exam results in percentage terms so classes can be compared fairly.","zh":"老師可能以百分比來表達考試結果，以便公平比較不同班級。"},{"en":"Percentages help readers understand size relative to a whole group.","zh":"百分比幫助讀者理解某數量相對於整體群體的大小。"},{"en":"This phrase is useful when large numbers need clearer context.","zh":"當大數字需要更清楚背景時，這個短語很有用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":5},{"front":"the world’s population","meaning":"世界人口","examples":[{"en":"Esperanto speakers make up a small part of the world’s population.","zh":"世界語使用者只佔世界人口的一小部分。"},{"en":"The world’s population means all the people living on Earth.","zh":"world’s population 指生活在地球上的所有人。"},{"en":"A disease affecting even one per cent of the world’s population would involve many people.","zh":"即使一種疾病影響世界人口的百分之一，也會涉及很多人。"},{"en":"Comparing a group with the world’s population shows whether it is large globally.","zh":"把某群體與世界人口比較，可以顯示它在全球層面是否龐大。"},{"en":"This phrase gives the widest possible human scale.","zh":"這個短語提供最廣泛的人類尺度。"}],"source":"75 - One Who Hopes.pdf","sourcePage":5},{"front":"a staggering figure","meaning":"驚人的數字","examples":[{"en":"The number is not a staggering figure, comparatively speaking.","zh":"相對而言，這個數字並不是驚人的數字。"},{"en":"A staggering figure is a number so large or surprising that it impresses or shocks people.","zh":"staggering figure 指大或驚人到令人震撼的數字。"},{"en":"A school repair bill of ten million dollars would be a staggering figure.","zh":"一千萬美元的學校維修費會是一個驚人的數字。"},{"en":"Calling a number staggering shows emotional reaction to its size.","zh":"把數字稱為 staggering 表示對其大小有強烈反應。"},{"en":"In this passage, the phrase is used negatively to show the number is not huge.","zh":"在這篇文章中，這個短語以否定方式使用，表示數字不算巨大。"}],"source":"75 - One Who Hopes.pdf","sourcePage":5},{"front":"comparatively speaking","meaning":"相對而言","examples":[{"en":"The figure is small, comparatively speaking.","zh":"相對而言，這個數字很小。"},{"en":"Comparatively speaking means when compared with something else.","zh":"comparatively speaking 指與其他事物比較時。"},{"en":"This phone is expensive, but comparatively speaking, it is cheaper than a laptop.","zh":"這部手機很貴，但相對而言，它比手提電腦便宜。"},{"en":"Comparison can change whether a number feels large or small.","zh":"比較可以改變一個數字感覺大或小。"},{"en":"This phrase is useful when judging size in relation to a wider context.","zh":"當根據更大背景判斷大小時，這個短語很有用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":5},{"front":"official status","meaning":"官方地位","examples":[{"en":"Esperanto has no official status in any country.","zh":"世界語在任何國家都沒有官方地位。"},{"en":"Official status means formal recognition by a government or institution.","zh":"official status 指由政府或機構正式承認。"},{"en":"A language with official status may be used in courts, schools, and public documents.","zh":"有官方地位的語言可能用於法院、學校和公共文件。"},{"en":"Without official status, a language may still be used by communities but not by the state.","zh":"沒有官方地位的語言仍可由社群使用，但不一定由國家使用。"},{"en":"This phrase is common in law, politics, and language policy.","zh":"這個短語常見於法律、政治和語言政策。"}],"source":"75 - One Who Hopes.pdf","sourcePage":5},{"front":"optional subject","meaning":"選修科目","examples":[{"en":"Esperanto is an optional subject in several education systems.","zh":"世界語在幾個教育制度中是選修科目。"},{"en":"An optional subject is a subject students may choose but do not have to study.","zh":"optional subject 指學生可以選擇但不必修讀的科目。"},{"en":"Art may be an optional subject for senior students.","zh":"藝術可能是高年級學生的選修科目。"},{"en":"Optional subjects allow students to follow interests beyond compulsory courses.","zh":"選修科目讓學生在必修課以外追求興趣。"},{"en":"This phrase is common in school curriculum discussions.","zh":"這個短語常見於學校課程討論。"}],"source":"75 - One Who Hopes.pdf","sourcePage":6},{"front":"on the curriculum","meaning":"在課程之中","examples":[{"en":"Esperanto is on the curriculum of several state education systems.","zh":"世界語在幾個國家教育制度的課程之中。"},{"en":"On the curriculum means included in the official list of subjects or courses taught.","zh":"on the curriculum 指被包括在官方教授科目或課程列表中。"},{"en":"Coding is now on the curriculum in many schools.","zh":"編程現在在許多學校課程之中。"},{"en":"When a subject is on the curriculum, schools may give time and teachers to it.","zh":"當一個科目在課程之中，學校可能分配時間和教師給它。"},{"en":"This phrase is common in education policy.","zh":"這個短語常見於教育政策。"}],"source":"75 - One Who Hopes.pdf","sourcePage":6},{"front":"state education systems","meaning":"國家教育制度","examples":[{"en":"Esperanto is taught in several state education systems.","zh":"世界語在幾個國家教育制度中教授。"},{"en":"State education systems are public education systems run or funded by the government.","zh":"state education systems 指由政府營運或資助的公共教育制度。"},{"en":"A state education system may set national exams and school curricula.","zh":"國家教育制度可能制定全國考試和學校課程。"},{"en":"If a language enters state education systems, more students can access it.","zh":"如果一種語言進入國家教育制度，更多學生可以接觸它。"},{"en":"This phrase refers to public schooling, not private tutoring.","zh":"這個短語指公共教育，而不是私人補習。"}],"source":"75 - One Who Hopes.pdf","sourcePage":6},{"front":"it is widely estimated that","meaning":"人們普遍估計","examples":[{"en":"It is widely estimated that Esperanto can be learned quickly.","zh":"人們普遍估計世界語可以快速學會。"},{"en":"It is widely estimated that means many people or sources estimate something to be true.","zh":"it is widely estimated that 指許多人或來源估計某事為真。"},{"en":"It is widely estimated that regular reading improves vocabulary over time.","zh":"人們普遍估計定期閱讀會隨時間改善詞彙。"},{"en":"This phrase suggests broad agreement but not absolute proof.","zh":"這個短語暗示廣泛同意，但不是絕對證明。"},{"en":"It is useful when exact measurement is difficult.","zh":"當精確測量困難時，它很有用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":6},{"front":"between a quarter and a twentieth of","meaning":"……的四分之一至二十分之一之間","examples":[{"en":"Esperanto may take between a quarter and a twentieth of the time required for other languages.","zh":"世界語所需時間可能是其他語言所需時間的四分之一至二十分之一之間。"},{"en":"Between a quarter and a twentieth of means from one fourth down to one twentieth of a whole amount.","zh":"between a quarter and a twentieth of 指從整體的四分之一到二十分之一之間。"},{"en":"A shortcut may reduce a journey to between a quarter and a half of the usual time.","zh":"捷徑可能把旅程縮短至平時時間的四分之一至一半。"},{"en":"This phrase gives a range rather than one exact figure.","zh":"這個短語提供一個範圍，而不是單一精確數字。"},{"en":"It is useful when estimates vary but still show a large reduction.","zh":"當估計不同但仍顯示大幅減少時，它很有用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":6},{"front":"the time required for","meaning":"……所需的時間","examples":[{"en":"Esperanto may require less time than the time required for other languages.","zh":"世界語可能需要比其他語言所需時間更少的時間。"},{"en":"The time required for something is the amount of time needed to complete it.","zh":"time required for something 指完成某事所需的時間。"},{"en":"The time required for homework depends on difficulty and concentration.","zh":"做功課所需的時間取決於難度和專注程度。"},{"en":"If a task requires less time, learners may feel more motivated to start.","zh":"如果一項任務所需時間較少，學習者可能更有動力開始。"},{"en":"This phrase is useful for comparing effort and efficiency.","zh":"這個短語適合比較努力和效率。"}],"source":"75 - One Who Hopes.pdf","sourcePage":6},{"front":"a constructed language","meaning":"人工語言","examples":[{"en":"Esperanto is a constructed language.","zh":"世界語是一種人工語言。"},{"en":"A constructed language is a language deliberately designed by people instead of developing naturally.","zh":"constructed language 指由人有意設計，而不是自然發展而成的語言。"},{"en":"A writer may create a constructed language for a fantasy novel.","zh":"作家可能為奇幻小說創造人工語言。"},{"en":"Planned languages can have regular rules because their structure is designed.","zh":"計劃語言可以有規則整齊的規則，因為其結構是被設計出來的。"},{"en":"This phrase contrasts artificial design with natural language history.","zh":"這個短語把人工設計與自然語言歷史作對比。"}],"source":"75 - One Who Hopes.pdf","sourcePage":6},{"front":"genealogically related to","meaning":"在語系上與……有關","examples":[{"en":"Esperanto is not genealogically related to any ethnic language.","zh":"世界語在語系上與任何民族語言都沒有關係。"},{"en":"Genealogically related to means belonging to the same historical language family.","zh":"genealogically related to 指屬於同一歷史語言家族。"},{"en":"Spanish and Italian are genealogically related because both developed from Latin.","zh":"西班牙語和意大利語在語系上有關，因為兩者都由拉丁語發展而來。"},{"en":"A constructed language may borrow words without being genealogically descended from one language.","zh":"人工語言可以借用詞語，而不一定在語系上源自某一語言。"},{"en":"This phrase is technical and used in linguistics.","zh":"這個短語較技術性，用於語言學。"}],"source":"75 - One Who Hopes.pdf","sourcePage":6},{"front":"ethnic language","meaning":"民族語言","examples":[{"en":"Esperanto is not tied to any ethnic language.","zh":"世界語不依附任何民族語言。"},{"en":"An ethnic language is a language connected with a particular ethnic group or people.","zh":"ethnic language 指與某特定族群或民族有關的語言。"},{"en":"A community may protect its ethnic language through songs, stories, and home use.","zh":"社群可能透過歌曲、故事和家庭使用來保護其民族語言。"},{"en":"Because Esperanto is not one ethnic language, supporters see it as more neutral.","zh":"因為世界語不是某一民族語言，支持者認為它更中立。"},{"en":"This phrase connects language with group identity.","zh":"這個短語把語言與群體身份連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":6},{"front":"be described as","meaning":"被描述為","examples":[{"en":"Esperanto is described as a language lexically predominantly Romance.","zh":"世界語被描述為一種詞彙上主要屬羅曼語系的語言。"},{"en":"To be described as something means to be explained or characterised in that way.","zh":"be described as something 指被以某方式解釋或定性。"},{"en":"A student may be described as hardworking if she submits every assignment carefully.","zh":"如果學生每份功課都仔細提交，她可能被描述為勤奮。"},{"en":"Descriptions help readers understand the main features of a thing.","zh":"描述幫助讀者理解某事物的主要特徵。"},{"en":"This phrase is useful when reporting another person’s classification.","zh":"這個短語適合報告他人的分類。"}],"source":"75 - One Who Hopes.pdf","sourcePage":6},{"front":"lexically predominantly Romance","meaning":"詞彙上主要屬羅曼語系的","examples":[{"en":"Esperanto is lexically predominantly Romance.","zh":"世界語在詞彙上主要屬羅曼語系。"},{"en":"Lexically predominantly Romance means most of its vocabulary comes from Romance languages.","zh":"lexically predominantly Romance 指其大部分詞彙來自羅曼語系語言。"},{"en":"A language may sound familiar to French or Italian speakers if its words are mostly Romance.","zh":"如果一種語言的詞多數屬羅曼語系，法語或意大利語使用者可能覺得熟悉。"},{"en":"Vocabulary origins can make a language easier for some learners than others.","zh":"詞彙來源可以令某種語言對部分學習者較容易。"},{"en":"This phrase is technical and describes word sources.","zh":"這個短語較技術性，描述詞語來源。"}],"source":"75 - One Who Hopes.pdf","sourcePage":6},{"front":"phonology","meaning":"音系；音韻系統","examples":[{"en":"The phonology of Esperanto is based on Western Indo-European languages.","zh":"世界語的音系基於西方印歐語系語言。"},{"en":"Phonology is the sound system of a language.","zh":"phonology 指一種語言的聲音系統。"},{"en":"Students study phonology when they learn which sounds a language uses.","zh":"學生學習一種語言使用哪些聲音時，就是在學音系。"},{"en":"A simple phonology can make pronunciation easier for beginners.","zh":"簡單音系可以令初學者較容易發音。"},{"en":"This word belongs to linguistics.","zh":"這個詞屬於語言學。"}],"source":"75 - One Who Hopes.pdf","sourcePage":7},{"front":"grammar","meaning":"語法","examples":[{"en":"The grammar of Esperanto is simple and regular.","zh":"世界語的語法簡單而規則。"},{"en":"Grammar is the system of rules that controls how words form sentences.","zh":"grammar 指控制詞語如何構成句子的規則系統。"},{"en":"Students learn grammar when they study tenses, word order, and sentence patterns.","zh":"學生學習時態、詞序和句式時，就是在學語法。"},{"en":"Clear grammar helps speakers express meaning accurately.","zh":"清楚語法幫助說話者準確表達意思。"},{"en":"This word is central to language learning.","zh":"這個詞是語言學習的核心。"}],"source":"75 - One Who Hopes.pdf","sourcePage":7},{"front":"vocabulary","meaning":"詞彙","examples":[{"en":"The vocabulary of Esperanto is partly based on Western European languages.","zh":"世界語的詞彙部分基於西歐語言。"},{"en":"Vocabulary means the words used in a language or known by a person.","zh":"vocabulary 指一種語言使用的詞語，或某人認識的詞語。"},{"en":"A student builds vocabulary by reading, listening, and reviewing useful words.","zh":"學生透過閱讀、聆聽和溫習有用詞語來建立詞彙。"},{"en":"Limited vocabulary can make it hard to express detailed ideas.","zh":"詞彙有限會令人難以表達詳細想法。"},{"en":"This word is common in all language-learning contexts.","zh":"這個詞常見於所有語言學習語境。"}],"source":"75 - One Who Hopes.pdf","sourcePage":7},{"front":"semantics","meaning":"語義學；語義系統","examples":[{"en":"The semantics of Esperanto are based on Western Indo-European languages.","zh":"世界語的語義系統基於西方印歐語系語言。"},{"en":"Semantics is the study or system of meaning in language.","zh":"semantics 指語言中意義的研究或系統。"},{"en":"When students compare similar words, they are studying meaning and semantics.","zh":"當學生比較相似詞語時，他們就在學習意思和語義。"},{"en":"Good semantics helps speakers choose the right word for the right idea.","zh":"良好語義理解幫助說話者為正確想法選擇正確詞語。"},{"en":"This word is technical and belongs to linguistics.","zh":"這個詞較技術性，屬於語言學。"}],"source":"75 - One Who Hopes.pdf","sourcePage":7},{"front":"Western Indo-European languages","meaning":"西方印歐語系語言","examples":[{"en":"Esperanto is based partly on Western Indo-European languages.","zh":"世界語部分基於西方印歐語系語言。"},{"en":"Western Indo-European languages are languages from western branches of the Indo-European language family.","zh":"Western Indo-European languages 指印歐語系西方分支的語言。"},{"en":"English, French, and German are often discussed as Western Indo-European languages.","zh":"英語、法語和德語常被作為西方印歐語系語言討論。"},{"en":"If a learner knows such languages, parts of Esperanto may feel familiar.","zh":"如果學習者懂這類語言，世界語部分內容可能感覺熟悉。"},{"en":"This phrase gives linguistic background for Esperanto’s design.","zh":"這個短語提供世界語設計的語言背景。"}],"source":"75 - One Who Hopes.pdf","sourcePage":7},{"front":"naturally gifted at","meaning":"天生擅長……","examples":[{"en":"Esperanto is useful for people who are not naturally gifted at learning languages.","zh":"世界語對不是天生擅長學語言的人很有用。"},{"en":"To be naturally gifted at something means to have a strong ability without much training.","zh":"naturally gifted at something 指未經太多訓練就有很強能力。"},{"en":"Some children are naturally gifted at music and can copy melodies quickly.","zh":"有些孩子天生擅長音樂，可以很快模仿旋律。"},{"en":"People who are not naturally gifted can still improve with clear systems and practice.","zh":"不是天生擅長的人仍可以透過清楚系統和練習進步。"},{"en":"This phrase describes natural talent, not effort.","zh":"這個短語描述天分，而不是努力。"}],"source":"75 - One Who Hopes.pdf","sourcePage":7},{"front":"easy to learn","meaning":"容易學習","examples":[{"en":"Esperanto is an easy language to learn.","zh":"世界語是一種容易學習的語言。"},{"en":"Easy to learn means not difficult for beginners to understand or practise.","zh":"easy to learn 指對初學者而言不難理解或練習。"},{"en":"A game with clear rules is easy to learn even for young children.","zh":"規則清楚的遊戲即使對小孩子來說也容易學習。"},{"en":"When something is easy to learn, people are more likely to keep trying.","zh":"當某事容易學習，人們更可能繼續嘗試。"},{"en":"This phrase describes low learning difficulty.","zh":"這個短語描述學習難度低。"}],"source":"75 - One Who Hopes.pdf","sourcePage":7},{"front":"conjugate verbs","meaning":"變化動詞形式","examples":[{"en":"Esperanto has one simple way of conjugating all of its verbs.","zh":"世界語有一種簡單方法變化所有動詞形式。"},{"en":"To conjugate verbs means to change verb forms according to tense, person, or number.","zh":"conjugate verbs 指按時態、人稱或數改變動詞形式。"},{"en":"In English, go changes to goes and went, so learners must study verb forms.","zh":"在英語中，go 會變成 goes 和 went，所以學習者必須學動詞形式。"},{"en":"If verb conjugation is simple, students can make sentences more quickly.","zh":"如果動詞變位簡單，學生可以更快造句。"},{"en":"This phrase is common in grammar learning.","zh":"這個短語常見於語法學習。"}],"source":"75 - One Who Hopes.pdf","sourcePage":7},{"front":"be formed from","meaning":"由……構成","examples":[{"en":"Esperanto words are often formed from a limited set of roots.","zh":"世界語詞語常由有限的一組詞根構成。"},{"en":"To be formed from something means to be made using particular parts or materials.","zh":"be formed from something 指用特定部分或材料製成。"},{"en":"Many English words are formed from Latin or Greek roots.","zh":"許多英語詞由拉丁或希臘詞根構成。"},{"en":"If many words are formed from a few roots, learners need to memorise less.","zh":"如果許多詞由少量詞根構成，學習者需要記憶較少。"},{"en":"This phrase explains how something is built.","zh":"這個短語解釋某物如何被建構。"}],"source":"75 - One Who Hopes.pdf","sourcePage":7},{"front":"a limited set of roots","meaning":"有限的一組詞根","examples":[{"en":"Words in Esperanto are often formed from a limited set of roots.","zh":"世界語詞語常由有限的一組詞根構成。"},{"en":"A limited set of roots means a small group of basic word parts used to build many words.","zh":"limited set of roots 指一小組用來建立許多詞語的基本詞根。"},{"en":"Students can learn many related words if they understand a few common roots.","zh":"如果學生理解幾個常見詞根，就可以學會許多相關詞。"},{"en":"A small set of roots reduces memory pressure.","zh":"少量詞根可以減少記憶壓力。"},{"en":"This phrase is useful when explaining word formation.","zh":"解釋構詞時，這個短語很有用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":7},{"front":"reduce the number that","meaning":"減少……的數量","examples":[{"en":"Using a limited set of roots reduces the number that learners must memorise.","zh":"使用有限的一組詞根可以減少學習者必須記住的數量。"},{"en":"To reduce the number that people must memorise means to make the memory load smaller.","zh":"reduce the number that people must memorise 指令記憶負擔變小。"},{"en":"A teacher can reduce the number that students must memorise by teaching word families.","zh":"老師可以透過教授詞族，減少學生必須記住的數量。"},{"en":"When there is less to memorise, learners can focus more on use and meaning.","zh":"當需要記的東西較少，學習者可以更專注於使用和意思。"},{"en":"This phrase explains how a system becomes easier.","zh":"這個短語解釋系統如何變得更容易。"}],"source":"75 - One Who Hopes.pdf","sourcePage":7},{"front":"must memorise","meaning":"必須記住","examples":[{"en":"Learners must memorise fewer words in Esperanto.","zh":"學習者在世界語中必須記住較少詞語。"},{"en":"Must memorise means have to remember something accurately.","zh":"must memorise 指必須準確記住某事。"},{"en":"Students must memorise irregular verbs if they want to use them correctly.","zh":"學生若想正確使用不規則動詞，就必須記住它們。"},{"en":"Too much memorisation can make learning feel heavy and slow.","zh":"太多記憶任務可以令學習感覺沉重而緩慢。"},{"en":"This phrase describes a required memory task.","zh":"這個短語描述必要的記憶任務。"}],"source":"75 - One Who Hopes.pdf","sourcePage":8},{"front":"phonetic","meaning":"表音的","examples":[{"en":"Esperanto is phonetic.","zh":"世界語是表音的。"},{"en":"Phonetic means words are pronounced in a regular way according to their written form.","zh":"phonetic 指詞語按其書寫形式以規則方式發音。"},{"en":"A phonetic spelling system helps learners read new words aloud confidently.","zh":"表音拼寫系統幫助學習者有信心讀出新詞。"},{"en":"If a language is phonetic, students make fewer pronunciation guesses.","zh":"如果一種語言是表音的，學生需要較少猜測發音。"},{"en":"This word is useful when discussing spelling and sound.","zh":"這個詞適合討論拼寫和聲音。"}],"source":"75 - One Who Hopes.pdf","sourcePage":8},{"front":"rules of pronunciation","meaning":"發音規則","examples":[{"en":"The rules of pronunciation in Esperanto are very simple.","zh":"世界語的發音規則非常簡單。"},{"en":"Rules of pronunciation are guidelines for how written letters and words should be spoken.","zh":"rules of pronunciation 指書面字母和詞語應如何讀出的指引。"},{"en":"Clear pronunciation rules help students read aloud without hearing every word first.","zh":"清楚發音規則幫助學生即使未聽過每個詞，也能朗讀。"},{"en":"Complicated pronunciation rules can slow language learning.","zh":"複雜發音規則可以拖慢語言學習。"},{"en":"This phrase is central to speaking and listening practice.","zh":"這個短語是說話和聆聽練習的核心。"}],"source":"75 - One Who Hopes.pdf","sourcePage":8},{"front":"written word","meaning":"書面詞語","examples":[{"en":"Esperanto learners know how to pronounce a written word.","zh":"世界語學習者知道如何讀出書面詞語。"},{"en":"A written word is a word shown in letters on a page or screen.","zh":"written word 指在紙上或屏幕上以字母顯示的詞語。"},{"en":"A child may see a written word before learning how it sounds.","zh":"孩子可能先看到書面詞語，然後才學會它如何發音。"},{"en":"If spelling is regular, a written word gives strong clues to pronunciation.","zh":"如果拼寫規則整齊，書面詞語會提供強烈發音線索。"},{"en":"This phrase contrasts written language with spoken language.","zh":"這個短語把書面語言與口語作對比。"}],"source":"75 - One Who Hopes.pdf","sourcePage":8},{"front":"spoken one","meaning":"口頭詞語","examples":[{"en":"Esperanto learners know how to write a spoken one.","zh":"世界語學習者知道如何寫出一個口頭詞語。"},{"en":"A spoken one means a word that is heard or said aloud.","zh":"spoken one 指被聽到或說出來的詞語。"},{"en":"In a phonetic language, learners can often spell a spoken word correctly.","zh":"在表音語言中，學習者通常可以正確拼寫聽到的詞。"},{"en":"Hearing a word clearly helps learners connect sound with spelling.","zh":"清楚聽到一個詞有助學習者把聲音與拼寫連接起來。"},{"en":"This phrase refers back to word and avoids repeating it.","zh":"這個短語指回 word，避免重複。"}],"source":"75 - One Who Hopes.pdf","sourcePage":8},{"front":"word order","meaning":"詞序","examples":[{"en":"Esperanto word order follows a logical pattern.","zh":"世界語詞序遵循合乎邏輯的模式。"},{"en":"Word order means the arrangement of words in a sentence.","zh":"word order 指句子中詞語的排列方式。"},{"en":"English word order usually puts the subject before the verb.","zh":"英語詞序通常把主語放在動詞前。"},{"en":"Clear word order helps readers understand who does what.","zh":"清楚詞序幫助讀者理解誰做甚麼。"},{"en":"This phrase is a basic grammar term.","zh":"這個短語是基本語法術語。"}],"source":"75 - One Who Hopes.pdf","sourcePage":8},{"front":"standard, logical pattern","meaning":"標準而合乎邏輯的模式","examples":[{"en":"Esperanto word order follows a standard, logical pattern.","zh":"世界語詞序遵循標準而合乎邏輯的模式。"},{"en":"A standard, logical pattern is a normal and sensible order that learners can predict.","zh":"standard, logical pattern 指學習者可以預測的正常而合理順序。"},{"en":"A timetable with a standard pattern is easier for students to follow.","zh":"有標準模式的時間表較容易讓學生跟隨。"},{"en":"Predictable patterns reduce confusion and speed up learning.","zh":"可預測模式可以減少混淆並加快學習。"},{"en":"This phrase describes order that is regular and reasonable.","zh":"這個短語描述規則而合理的秩序。"}],"source":"75 - One Who Hopes.pdf","sourcePage":8},{"front":"prefixing and suffixing","meaning":"加前綴和後綴","examples":[{"en":"Esperanto uses prefixing and suffixing to show word classes.","zh":"世界語使用加前綴和後綴來顯示詞類。"},{"en":"Prefixing and suffixing mean adding word parts to the beginning or end of a root.","zh":"prefixing and suffixing 指在詞根開頭或結尾加入詞素。"},{"en":"In English, unhappy uses prefixing, while helpful uses suffixing.","zh":"在英語中，unhappy 使用前綴，而 helpful 使用後綴。"},{"en":"These changes can help learners recognise meaning and grammar quickly.","zh":"這些變化可以幫助學習者快速辨認意思和語法。"},{"en":"This phrase is common in word-formation study.","zh":"這個短語常見於構詞研究。"}],"source":"75 - One Who Hopes.pdf","sourcePage":8},{"front":"identify words as","meaning":"將詞語識別為……","examples":[{"en":"Esperanto makes it easy to identify words as nouns, verbs or adjectives.","zh":"世界語令人容易將詞語識別為名詞、動詞或形容詞。"},{"en":"To identify words as something means to recognise their grammatical type or role.","zh":"identify words as something 指辨認詞語的語法類型或角色。"},{"en":"Students identify words as verbs when they show actions or states.","zh":"當詞語顯示動作或狀態時，學生會把它們識別為動詞。"},{"en":"Clear endings help learners identify words faster and avoid sentence mistakes.","zh":"清楚字尾幫助學習者更快識別詞語並避免句子錯誤。"},{"en":"This phrase is useful in grammar analysis.","zh":"這個短語適用於語法分析。"}],"source":"75 - One Who Hopes.pdf","sourcePage":8},{"front":"nouns, verbs and adjectives","meaning":"名詞、動詞和形容詞","examples":[{"en":"Esperanto endings show nouns, verbs and adjectives clearly.","zh":"世界語字尾清楚顯示名詞、動詞和形容詞。"},{"en":"Nouns, verbs and adjectives are major word classes in grammar.","zh":"nouns, verbs and adjectives 是語法中的主要詞類。"},{"en":"Cat is a noun, run is a verb, and happy is an adjective.","zh":"cat 是名詞，run 是動詞，而 happy 是形容詞。"},{"en":"Knowing these word classes helps students build correct sentences.","zh":"認識這些詞類幫助學生建立正確句子。"},{"en":"This phrase lists basic parts of speech.","zh":"這個短語列出基本詞性。"}],"source":"75 - One Who Hopes.pdf","sourcePage":8},{"front":"direct objects","meaning":"直接受詞","examples":[{"en":"Esperanto endings can help identify direct objects.","zh":"世界語字尾可以幫助識別直接受詞。"},{"en":"Direct objects are nouns or pronouns that receive the action of a verb.","zh":"direct objects 指承受動詞動作的名詞或代詞。"},{"en":"In “She reads a book,” a book is the direct object.","zh":"在 “She reads a book” 中，a book 是直接受詞。"},{"en":"Clear marking of direct objects can make sentence meaning easier to follow.","zh":"清楚標記直接受詞可以令句子意思更容易理解。"},{"en":"This phrase is important in grammar study.","zh":"這個短語在語法學習中很重要。"}],"source":"75 - One Who Hopes.pdf","sourcePage":8},{"front":"by means of","meaning":"透過；藉着","examples":[{"en":"Esperanto identifies word classes by means of clear endings.","zh":"世界語透過清楚字尾識別詞類。"},{"en":"By means of means by using a particular method or tool.","zh":"by means of 指透過使用某種方法或工具。"},{"en":"Students can improve pronunciation by means of daily listening practice.","zh":"學生可以透過每日聆聽練習改善發音。"},{"en":"This phrase is more formal than by using.","zh":"這個短語比 by using 更正式。"},{"en":"It explains the method through which something is done.","zh":"它解釋某事透過甚麼方法完成。"}],"source":"75 - One Who Hopes.pdf","sourcePage":9},{"front":"easy-to-spot endings","meaning":"容易辨認的字尾","examples":[{"en":"Esperanto uses easy-to-spot endings.","zh":"世界語使用容易辨認的字尾。"},{"en":"Easy-to-spot endings are word endings that learners can recognise quickly.","zh":"easy-to-spot endings 指學習者能快速認出的詞尾。"},{"en":"A coloured label on a file is easy to spot on a crowded desk.","zh":"擁擠書桌上的彩色標籤很容易辨認。"},{"en":"Clear endings reduce confusion because students can see a word’s role immediately.","zh":"清楚字尾減少混淆，因為學生可以立即看出詞語角色。"},{"en":"This phrase describes features that are visually or mentally easy to notice.","zh":"這個短語描述視覺上或心理上容易注意到的特徵。"}],"source":"75 - One Who Hopes.pdf","sourcePage":9},{"front":"make for","meaning":"促成；有助於","examples":[{"en":"Simple grammar and pronunciation make for easy language learning.","zh":"簡單語法和發音有助於輕鬆語言學習。"},{"en":"Make for means help create or lead to a particular result.","zh":"make for 指幫助創造或導致某種結果。"},{"en":"Clear instructions make for a calmer classroom.","zh":"清楚指示有助於建立較平靜的課室。"},{"en":"When rules are simple, they can make for faster progress.","zh":"當規則簡單，它們可以促成更快進步。"},{"en":"This phrase connects a cause with a general outcome.","zh":"這個短語把原因與一般結果連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":9},{"front":"language learning","meaning":"語言學習","examples":[{"en":"Esperanto may make language learning easier.","zh":"世界語可能令語言學習更容易。"},{"en":"Language learning is the process of learning to understand, speak, read, or write a language.","zh":"language learning 指學習理解、說、讀或寫一種語言的過程。"},{"en":"Language learning often requires listening practice, vocabulary review, and speaking attempts.","zh":"語言學習常需要聆聽練習、詞彙溫習和說話嘗試。"},{"en":"Clear rules and regular practice can make language learning less frightening.","zh":"清楚規則和定期練習可以令語言學習不那麼可怕。"},{"en":"This phrase covers both classroom study and real-life use.","zh":"這個短語涵蓋課堂學習和真實使用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":9},{"front":"what’s more","meaning":"此外；而且","examples":[{"en":"What’s more, Esperanto can help people learn other languages.","zh":"此外，世界語可以幫助人學習其他語言。"},{"en":"What’s more introduces an additional point that strengthens the argument.","zh":"what’s more 用來引出加強論點的額外內容。"},{"en":"The course is cheap; what’s more, it includes free speaking practice.","zh":"這個課程便宜；而且，它包括免費口語練習。"},{"en":"This phrase adds another benefit after one has already been given.","zh":"這個短語在已提出一個好處後加入另一個好處。"},{"en":"It is common in spoken and semi-formal writing.","zh":"它常見於口語和半正式寫作。"}],"source":"75 - One Who Hopes.pdf","sourcePage":9},{"front":"research studies demonstrate that","meaning":"研究顯示","examples":[{"en":"Several research studies demonstrate that Esperanto helps later language learning.","zh":"多項研究顯示世界語有助其後語言學習。"},{"en":"Research studies demonstrate that means academic investigations show evidence for a claim.","zh":"research studies demonstrate that 指學術研究顯示某說法有證據支持。"},{"en":"Research studies demonstrate that sleep can affect memory and concentration.","zh":"研究顯示睡眠可以影響記憶和專注。"},{"en":"Evidence from studies makes an argument stronger than personal opinion alone.","zh":"來自研究的證據比單靠個人意見更能加強論點。"},{"en":"This phrase is formal and common in academic writing.","zh":"這個短語較正式，常見於學術寫作。"}],"source":"75 - One Who Hopes.pdf","sourcePage":9},{"front":"studying Esperanto before","meaning":"在學習……之前先學世界語","examples":[{"en":"Studying Esperanto before another foreign language can improve later learning.","zh":"在學習另一門外語之前先學世界語，可以改善之後的學習。"},{"en":"Studying Esperanto before something means learning Esperanto first, before starting another language.","zh":"studying Esperanto before something 指先學世界語，再開始另一種語言。"},{"en":"A student may study basic grammar before writing full essays.","zh":"學生可能在寫完整文章前先學基本文法。"},{"en":"Learning an easier system first can prepare students for harder systems later.","zh":"先學較容易的系統可以為之後較難的系統作準備。"},{"en":"This phrase describes a learning sequence.","zh":"這個短語描述學習次序。"}],"source":"75 - One Who Hopes.pdf","sourcePage":9},{"front":"foreign language","meaning":"外語","examples":[{"en":"Esperanto may help students learn another foreign language.","zh":"世界語可能幫助學生學習另一門外語。"},{"en":"A foreign language is a language that is not a person’s native language.","zh":"foreign language 指不是某人母語的語言。"},{"en":"A Hong Kong student may study Italian as a foreign language.","zh":"香港學生可能把意大利語作為外語學習。"},{"en":"Learning a foreign language can improve travel, work, and cultural understanding.","zh":"學習外語可以改善旅遊、工作和文化理解。"},{"en":"This phrase is common in education and communication.","zh":"這個短語常見於教育和溝通語境。"}],"source":"75 - One Who Hopes.pdf","sourcePage":9},{"front":"speed up and improve","meaning":"加快並改善","examples":[{"en":"Studying Esperanto can speed up and improve the learning of another language.","zh":"學習世界語可以加快並改善另一種語言的學習。"},{"en":"To speed up and improve something means to make it faster and better.","zh":"speed up and improve something 指令某事更快也更好。"},{"en":"Clear feedback can speed up and improve a student’s essay writing.","zh":"清楚回饋可以加快並改善學生的文章寫作。"},{"en":"A good foundation helps later learning become quicker and more accurate.","zh":"良好基礎幫助之後學習變得更快、更準確。"},{"en":"This phrase combines efficiency with quality.","zh":"這個短語結合效率和質素。"}],"source":"75 - One Who Hopes.pdf","sourcePage":9},{"front":"presumably","meaning":"大概；推測起來","examples":[{"en":"This is presumably because later foreign languages are easier to learn.","zh":"這大概是因為其後學習的外語較容易學。"},{"en":"Presumably means probably, based on what seems reasonable.","zh":"presumably 指根據合理情況推測，大概如此。"},{"en":"The classroom is dark, so presumably the lesson has ended.","zh":"課室很暗，所以大概課堂已經結束。"},{"en":"This word signals a likely explanation rather than certain proof.","zh":"這個詞表示可能解釋，而不是確定證明。"},{"en":"It is useful when making a careful inference.","zh":"作謹慎推論時，它很有用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":9},{"front":"subsequent foreign languages","meaning":"其後學習的外語","examples":[{"en":"Learning subsequent foreign languages is easier than learning the first one.","zh":"學習其後的外語比學習第一門外語容易。"},{"en":"Subsequent foreign languages are additional foreign languages learned after the first one.","zh":"subsequent foreign languages 指第一門外語之後再學的其他外語。"},{"en":"A student who has learned French may find subsequent foreign languages less frightening.","zh":"已學過法語的學生可能覺得其後學習的外語較不嚇人。"},{"en":"Earlier language experience can teach study methods that help later learning.","zh":"早期語言經驗可以教會學習方法，幫助之後學習。"},{"en":"This phrase focuses on languages learned later in a sequence.","zh":"這個短語聚焦在次序中較後學習的語言。"}],"source":"75 - One Who Hopes.pdf","sourcePage":9},{"front":"grammatically simple","meaning":"語法簡單的","examples":[{"en":"Esperanto is grammatically simple.","zh":"世界語是語法簡單的。"},{"en":"Grammatically simple means having grammar rules that are easy and regular.","zh":"grammatically simple 指語法規則容易而整齊。"},{"en":"A grammatically simple sentence is easier for beginners to understand.","zh":"語法簡單的句子較容易讓初學者理解。"},{"en":"Simple grammar can reduce mistakes and build confidence.","zh":"簡單語法可以減少錯誤並建立信心。"},{"en":"This phrase describes structure, not vocabulary or pronunciation.","zh":"這個短語描述結構，而不是詞彙或發音。"}],"source":"75 - One Who Hopes.pdf","sourcePage":10},{"front":"culturally flexible","meaning":"文化上靈活的","examples":[{"en":"Esperanto is a culturally flexible language.","zh":"世界語是一種文化上靈活的語言。"},{"en":"Culturally flexible means not tied tightly to one nation, culture, or tradition.","zh":"culturally flexible 指不緊緊依附某一國家、文化或傳統。"},{"en":"A culturally flexible tool can be used by people from many backgrounds.","zh":"文化上靈活的工具可以由不同背景的人使用。"},{"en":"Such flexibility can make communication feel more neutral and inclusive.","zh":"這種靈活性可以令溝通感覺更中立、更包容。"},{"en":"This phrase describes adaptability across cultures.","zh":"這個短語描述跨文化適應能力。"}],"source":"75 - One Who Hopes.pdf","sourcePage":10},{"front":"soften the blow of","meaning":"減輕……的衝擊","examples":[{"en":"Esperanto can soften the blow of learning one’s first foreign language.","zh":"世界語可以減輕學習第一門外語的衝擊。"},{"en":"To soften the blow of something means to make a difficult experience less painful or shocking.","zh":"soften the blow of something 指令困難經歷不那麼痛苦或震撼。"},{"en":"A teacher’s encouragement can soften the blow of a poor test result.","zh":"老師的鼓勵可以減輕測驗成績差的打擊。"},{"en":"If the first language is easier, students may feel less afraid of later languages.","zh":"如果第一門語言較容易，學生可能較不害怕之後的語言。"},{"en":"This phrase is useful when something reduces stress or disappointment.","zh":"當某事減少壓力或失望時，這個短語很有用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":10},{"front":"one’s first foreign language","meaning":"某人的第一門外語","examples":[{"en":"Esperanto may make learning one’s first foreign language easier.","zh":"世界語可能令學習某人的第一門外語更容易。"},{"en":"One’s first foreign language is the first language a person learns after their native language.","zh":"one’s first foreign language 指一個人在母語以外學習的第一種語言。"},{"en":"A child’s first foreign language may shape how confident they feel about future learning.","zh":"孩子的第一門外語可能塑造他對未來學習的信心。"},{"en":"If the first experience is too difficult, students may fear languages later.","zh":"如果第一次經驗太困難，學生之後可能害怕語言。"},{"en":"This phrase focuses on the beginning of language-learning experience.","zh":"這個短語聚焦語言學習經驗的開始。"}],"source":"75 - One Who Hopes.pdf","sourcePage":10},{"front":"a group of European high school students","meaning":"一組歐洲高中生","examples":[{"en":"A group of European high school students studied Esperanto for one year.","zh":"一組歐洲高中生學習世界語一年。"},{"en":"A group of European high school students means several secondary students from Europe.","zh":"group of European high school students 指來自歐洲的幾名中學生。"},{"en":"A study may compare one group of students with another to test learning effects.","zh":"研究可能比較一組學生與另一組，以測試學習效果。"},{"en":"Using a group helps researchers observe patterns rather than one person’s experience.","zh":"使用一組人幫助研究者觀察模式，而不只是個人經驗。"},{"en":"This phrase describes the participants in an educational study.","zh":"這個短語描述教育研究中的參與者。"}],"source":"75 - One Who Hopes.pdf","sourcePage":10},{"front":"end up with","meaning":"最終得到；最後擁有","examples":[{"en":"The students ended up with a better command of French.","zh":"這些學生最終對法語有更好的掌握。"},{"en":"To end up with something means to finally have a result after a process.","zh":"end up with something 指經過一個過程後最終得到某結果。"},{"en":"A student who practises daily may end up with stronger speaking confidence.","zh":"每天練習的學生最終可能得到更強的說話信心。"},{"en":"Final results can be different from what people expected at the start.","zh":"最終結果可以與一開始預期不同。"},{"en":"This phrase focuses on the outcome after time passes.","zh":"這個短語聚焦時間過去後的結果。"}],"source":"75 - One Who Hopes.pdf","sourcePage":10},{"front":"a significantly better command of","meaning":"對……掌握明顯更好","examples":[{"en":"The Esperanto group ended up with a significantly better command of French.","zh":"世界語組最終對法語掌握明顯更好。"},{"en":"A significantly better command of a language means much stronger ability to use it.","zh":"significantly better command of a language 指使用該語言的能力明顯更強。"},{"en":"Students who read daily may gain a better command of written English.","zh":"每天閱讀的學生可能對書面英語有更好掌握。"},{"en":"Better command allows learners to speak and write with more confidence.","zh":"更好掌握讓學習者能更有信心地說和寫。"},{"en":"This phrase is formal and often used for language ability.","zh":"這個短語較正式，常用於語言能力。"}],"source":"75 - One Who Hopes.pdf","sourcePage":10},{"front":"control group","meaning":"對照組","examples":[{"en":"The control group spent all four years studying French.","zh":"對照組四年全部時間都學習法語。"},{"en":"A control group is a comparison group in a study that does not receive the special treatment being tested.","zh":"control group 指研究中的比較組，沒有接受被測試的特殊處理。"},{"en":"In a teaching study, one group may use a new method while the control group uses the old method.","zh":"在教學研究中，一組可能使用新方法，而對照組使用舊方法。"},{"en":"A control group helps researchers judge whether a result comes from the new method.","zh":"對照組幫助研究者判斷結果是否來自新方法。"},{"en":"This phrase is common in experiments and research.","zh":"這個短語常見於實驗和研究。"}],"source":"75 - One Who Hopes.pdf","sourcePage":10},{"front":"Needless to say","meaning":"不用說","examples":[{"en":"Needless to say, Esperanto has its critics.","zh":"不用說，世界語有其批評者。"},{"en":"Needless to say means the point is obvious or expected, so it hardly needs stating.","zh":"needless to say 指某點很明顯或可預期，幾乎不用說。"},{"en":"Needless to say, students should not copy essays from the internet.","zh":"不用說，學生不應從互聯網抄文章。"},{"en":"This phrase often introduces a point the writer assumes readers will understand.","zh":"這個短語常引出作者認為讀者會明白的點。"},{"en":"It can sound slightly ironic depending on context.","zh":"視乎語境，它可以帶有輕微諷刺。"}],"source":"75 - One Who Hopes.pdf","sourcePage":10},{"front":"have its critics","meaning":"有批評者","examples":[{"en":"Esperanto has its critics.","zh":"世界語有其批評者。"},{"en":"To have its critics means to have people who disagree with or criticise it.","zh":"have its critics 指有人不同意或批評某事物。"},{"en":"Online learning has its critics, especially among people who prefer classrooms.","zh":"網上學習有其批評者，尤其是在喜歡課室學習的人之中。"},{"en":"Even a useful idea can have critics if people doubt its effects.","zh":"即使有用的想法也可以有批評者，只要有人懷疑其效果。"},{"en":"This phrase shows that support is not universal.","zh":"這個短語顯示支持並非一致。"}],"source":"75 - One Who Hopes.pdf","sourcePage":10},{"front":"point to","meaning":"指出；提到","examples":[{"en":"Some critics point to the Eastern European features of Esperanto.","zh":"有些批評者指出世界語的東歐特徵。"},{"en":"To point to something means to mention it as evidence or a reason.","zh":"point to something 指把某事作為證據或原因提及。"},{"en":"Teachers may point to weak grammar as a reason for low writing scores.","zh":"老師可能指出文法薄弱是寫作分低的原因。"},{"en":"When people point to evidence, they try to support their argument.","zh":"當人們指出證據，他們是嘗試支持其論點。"},{"en":"This phrase is common in explanation and criticism.","zh":"這個短語常見於解釋和批評。"}],"source":"75 - One Who Hopes.pdf","sourcePage":10},{"front":"Eastern European features","meaning":"東歐特徵","examples":[{"en":"Some critics dislike the Eastern European features of Esperanto.","zh":"有些批評者不喜歡世界語的東歐特徵。"},{"en":"Eastern European features are qualities that seem connected with languages or cultures of Eastern Europe.","zh":"Eastern European features 指看似與東歐語言或文化有關的特質。"},{"en":"A language may have sounds or patterns that remind learners of a particular region.","zh":"一種語言可能有令人想起某特定地區的聲音或模式。"},{"en":"Such features may feel familiar to some learners but difficult to others.","zh":"這些特徵對某些學習者可能熟悉，對其他人則困難。"},{"en":"This phrase describes regional influence in language form.","zh":"這個短語描述語言形式中的地區影響。"}],"source":"75 - One Who Hopes.pdf","sourcePage":11},{"front":"harsh and difficult to pronounce","meaning":"生硬且難以發音","examples":[{"en":"Some critics consider Esperanto harsh and difficult to pronounce.","zh":"有些批評者認為世界語生硬且難以發音。"},{"en":"Harsh and difficult to pronounce means sounding rough and hard for speakers to say clearly.","zh":"harsh and difficult to pronounce 指聲音粗硬，且說話者難以清楚讀出。"},{"en":"A word with many unfamiliar consonants may feel difficult to pronounce.","zh":"有很多陌生子音的詞可能感覺難以發音。"},{"en":"If pronunciation feels harsh, learners may feel less attracted to the language.","zh":"如果發音感覺生硬，學習者可能較不被該語言吸引。"},{"en":"This phrase describes a negative judgement about sound.","zh":"這個短語描述對聲音的負面評價。"}],"source":"75 - One Who Hopes.pdf","sourcePage":11},{"front":"argue that","meaning":"認為；主張","examples":[{"en":"Critics argue that Esperanto has an artificial feel to it.","zh":"批評者認為世界語有一種人造的感覺。"},{"en":"To argue that means to give an opinion or claim with reasons.","zh":"argue that 指以理由提出意見或主張。"},{"en":"Some parents argue that children need more sleep than homework.","zh":"有些家長主張孩子需要更多睡眠，而不是更多功課。"},{"en":"This phrase introduces a position that may be challenged by others.","zh":"這個短語引出可能被他人挑戰的立場。"},{"en":"It is common in essays and debate.","zh":"它常見於文章和辯論。"}],"source":"75 - One Who Hopes.pdf","sourcePage":11},{"front":"have an artificial feel to it","meaning":"有一種人造的感覺","examples":[{"en":"Some critics argue that Esperanto has an artificial feel to it.","zh":"有些批評者認為世界語有一種人造的感覺。"},{"en":"To have an artificial feel to it means to seem unnatural or deliberately made.","zh":"have an artificial feel to it 指顯得不自然或刻意製造。"},{"en":"A copied speech may have an artificial feel if it does not sound like the speaker.","zh":"如果一篇抄來的演講不像講者本人，它可能有一種人造的感覺。"},{"en":"If a language feels artificial, some people may find it less emotionally convincing.","zh":"如果一種語言感覺人造，有些人可能覺得它較缺乏情感說服力。"},{"en":"This phrase describes impression, not necessarily objective weakness.","zh":"這個短語描述印象，而不一定是客觀弱點。"}],"source":"75 - One Who Hopes.pdf","sourcePage":11},{"front":"the flow of a natural tongue","meaning":"自然語言的流暢感","examples":[{"en":"Critics say Esperanto lacks the flow of a natural tongue.","zh":"批評者說世界語缺乏自然語言的流暢感。"},{"en":"The flow of a natural tongue is the smooth rhythm and feeling of a language that developed naturally.","zh":"flow of a natural tongue 指自然發展語言的順暢節奏和感覺。"},{"en":"A poem may sound better when it has natural flow.","zh":"一首詩如果有自然流暢感，可能聽起來更好。"},{"en":"If a language lacks flow, speakers may feel it sounds mechanical.","zh":"如果語言缺乏流暢感，說話者可能覺得它聽起來機械化。"},{"en":"This phrase links language sound with naturalness.","zh":"這個短語把語言聲音與自然性連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":11},{"front":"because of its artificial nature","meaning":"由於其人造性質","examples":[{"en":"Critics say Esperanto lacks emotional depth because of its artificial nature.","zh":"批評者說世界語由於其人造性質而缺乏情感深度。"},{"en":"Because of its artificial nature means due to the fact that it was deliberately constructed.","zh":"because of its artificial nature 指因為它是被有意建構出來的。"},{"en":"Some people distrust a planned community because of its artificial nature.","zh":"有些人因規劃社區的人造性質而不信任它。"},{"en":"If something feels artificial, people may doubt whether it can carry deep emotion.","zh":"如果某物感覺人造，人們可能懷疑它能否承載深層情感。"},{"en":"This phrase explains a criticism based on origin.","zh":"這個短語解釋一種基於起源的批評。"}],"source":"75 - One Who Hopes.pdf","sourcePage":11},{"front":"become emotionally involved with","meaning":"對……投入感情","examples":[{"en":"Some critics say it is impossible to become emotionally involved with Esperanto.","zh":"有些批評者說不可能對世界語投入感情。"},{"en":"To become emotionally involved with something means to feel personally connected to it.","zh":"become emotionally involved with something 指對某事產生個人情感連繫。"},{"en":"Readers may become emotionally involved with a novel’s characters.","zh":"讀者可能對小說人物投入感情。"},{"en":"Emotional involvement can make people loyal to a language, story, or community.","zh":"情感投入可以令人忠於一種語言、故事或社群。"},{"en":"This phrase describes feeling, not just understanding.","zh":"這個短語描述感受，而不只是理解。"}],"source":"75 - One Who Hopes.pdf","sourcePage":11},{"front":"cite its lack of","meaning":"引述其缺乏……","examples":[{"en":"Critics cite its lack of cultural history and indigenous literature.","zh":"批評者指出它缺乏文化歷史和本土文學。"},{"en":"To cite its lack of something means to mention that absence as evidence for criticism.","zh":"cite its lack of something 指把缺少某物作為批評證據提出。"},{"en":"A reviewer may cite a course’s lack of feedback as a major weakness.","zh":"評論者可能指出課程缺乏回饋是主要弱點。"},{"en":"When critics cite a lack, they are pointing to something they think is missing.","zh":"當批評者指出缺乏某物，他們是在指出認為缺失的東西。"},{"en":"This phrase is formal and often used in arguments.","zh":"這個短語較正式，常用於論證。"}],"source":"75 - One Who Hopes.pdf","sourcePage":11},{"front":"cultural history","meaning":"文化歷史","examples":[{"en":"Critics argue that Esperanto lacks cultural history.","zh":"批評者認為世界語缺乏文化歷史。"},{"en":"Cultural history is the record of a community’s traditions, stories, art, language, and shared memory.","zh":"cultural history 指一個社群的傳統、故事、藝術、語言和共同記憶記錄。"},{"en":"Museums help preserve cultural history through objects and personal accounts.","zh":"博物館透過物件和個人敘述幫助保存文化歷史。"},{"en":"A language with long cultural history may feel emotionally rich to its speakers.","zh":"具有悠久文化歷史的語言，對使用者來說可能情感豐富。"},{"en":"This phrase connects culture with time and memory.","zh":"這個短語把文化與時間和記憶連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":11},{"front":"indigenous literature","meaning":"本土文學","examples":[{"en":"Critics say Esperanto lacks indigenous literature.","zh":"批評者說世界語缺乏本土文學。"},{"en":"Indigenous literature is literature native to a particular people, culture, or language tradition.","zh":"indigenous literature 指原屬某民族、文化或語言傳統的文學。"},{"en":"Folk tales and poems in a local language can be indigenous literature.","zh":"用本地語言寫成的民間故事和詩歌可以是本土文學。"},{"en":"Literature gives a language emotional depth, shared memory, and cultural identity.","zh":"文學給語言情感深度、共同記憶和文化身份。"},{"en":"This phrase is used when discussing cultural roots of writing.","zh":"這個短語用於討論寫作的文化根源。"}],"source":"75 - One Who Hopes.pdf","sourcePage":11},{"front":"directly in Esperanto","meaning":"直接用世界語","examples":[{"en":"Critics claim that no one has written a novel directly in Esperanto.","zh":"批評者聲稱沒有人直接用世界語寫小說。"},{"en":"Directly in Esperanto means originally using Esperanto, not translated from another language.","zh":"directly in Esperanto 指原本就使用世界語，而不是從另一種語言翻譯而來。"},{"en":"A poem written directly in a language may feel different from a translation.","zh":"直接用某語言寫成的詩，可能與翻譯作品感覺不同。"},{"en":"Original writing can show whether a language works creatively.","zh":"原創寫作可以顯示一種語言是否能創意地運作。"},{"en":"This phrase contrasts original composition with translation.","zh":"這個短語把原創寫作與翻譯作對比。"}],"source":"75 - One Who Hopes.pdf","sourcePage":11},{"front":"minimal vocabulary","meaning":"極少的詞彙","examples":[{"en":"Some critics complain about Esperanto’s minimal vocabulary.","zh":"有些批評者投訴世界語詞彙極少。"},{"en":"Minimal vocabulary means a very small range of words.","zh":"minimal vocabulary 指詞語範圍非常小。"},{"en":"A beginner with minimal vocabulary may understand simple greetings but not complex ideas.","zh":"詞彙極少的初學者可能明白簡單問候，但不能理解複雜想法。"},{"en":"Limited vocabulary can make expression feel narrow or repetitive.","zh":"詞彙有限可以令表達感覺狹窄或重複。"},{"en":"This phrase is often used as a criticism of expressive power.","zh":"這個短語常用作對表達能力的批評。"}],"source":"75 - One Who Hopes.pdf","sourcePage":12},{"front":"inability to express","meaning":"無法表達……","examples":[{"en":"Critics mention its inability to express complex concepts.","zh":"批評者提到它無法表達複雜概念。"},{"en":"Inability to express something means not being able to communicate it clearly.","zh":"inability to express something 指不能清楚傳達某事。"},{"en":"A child may feel frustrated by an inability to express pain accurately.","zh":"孩子如果無法準確表達痛楚，可能會感到挫敗。"},{"en":"If a language cannot express complex ideas, users may need extra explanation or borrowing.","zh":"如果語言不能表達複雜想法，使用者可能需要額外解釋或借詞。"},{"en":"This phrase describes a limitation in communication.","zh":"這個短語描述溝通上的限制。"}],"source":"75 - One Who Hopes.pdf","sourcePage":12},{"front":"philosophical concepts","meaning":"哲學概念","examples":[{"en":"Critics say Esperanto cannot express all necessary philosophical concepts.","zh":"批評者說世界語不能表達所有必要哲學概念。"},{"en":"Philosophical concepts are abstract ideas about knowledge, reality, morality, or existence.","zh":"philosophical concepts 指關於知識、現實、道德或存在的抽象想法。"},{"en":"Freedom, justice, truth, and identity can be philosophical concepts.","zh":"自由、公義、真理和身份都可以是哲學概念。"},{"en":"Complex concepts need precise language so arguments do not become unclear.","zh":"複雜概念需要精確語言，否則論證會變得不清楚。"},{"en":"This phrase is common in academic and abstract discussion.","zh":"這個短語常見於學術和抽象討論。"}],"source":"75 - One Who Hopes.pdf","sourcePage":12},{"front":"emotional and psychological concepts","meaning":"情感和心理概念","examples":[{"en":"Critics say Esperanto cannot express all emotional and psychological concepts.","zh":"批評者說世界語不能表達所有情感和心理概念。"},{"en":"Emotional and psychological concepts are ideas about feelings, thoughts, personality, and mental states.","zh":"emotional and psychological concepts 指關於感受、想法、性格和心理狀態的概念。"},{"en":"Anxiety, grief, confidence, and memory are emotional or psychological concepts.","zh":"焦慮、悲傷、信心和記憶都是情感或心理概念。"},{"en":"A language needs rich expression to describe inner experience accurately.","zh":"語言需要豐富表達，才能準確描述內在經驗。"},{"en":"This phrase is used when discussing feelings and the mind.","zh":"這個短語用於討論感情和心靈。"}],"source":"75 - One Who Hopes.pdf","sourcePage":12},{"front":"champions of Esperanto","meaning":"世界語支持者","examples":[{"en":"The champions of Esperanto disagree with its critics.","zh":"世界語支持者不同意其批評者。"},{"en":"Champions of Esperanto are strong supporters who defend and promote the language.","zh":"champions of Esperanto 指強烈支持、捍衛和推廣世界語的人。"},{"en":"A champion of a school programme may explain its benefits to parents.","zh":"學校計劃的支持者可能向家長解釋其好處。"},{"en":"Supporters often respond when critics attack something they value.","zh":"當批評者攻擊他們重視的事物，支持者常會回應。"},{"en":"This phrase describes active advocates, not sports winners.","zh":"這個短語描述積極倡議者，而不是運動冠軍。"}],"source":"75 - One Who Hopes.pdf","sourcePage":12},{"front":"Esperantists","meaning":"世界語者；世界語支持者","examples":[{"en":"Esperantists defend Esperanto as a real and useful language.","zh":"世界語者捍衛世界語，認為它是真實而有用的語言。"},{"en":"Esperantists are people who speak, learn, support, or promote Esperanto.","zh":"Esperantists 指說、學習、支持或推廣世界語的人。"},{"en":"Esperantists may attend meetings, read magazines, and write to one another.","zh":"世界語者可能參加會議、閱讀雜誌並互相通信。"},{"en":"A language community survives when its members actively use and defend it.","zh":"語言社群要靠成員積極使用和捍衛才能延續。"},{"en":"This word names supporters or users of Esperanto.","zh":"這個詞指世界語支持者或使用者。"}],"source":"75 - One Who Hopes.pdf","sourcePage":12},{"front":"disagree","meaning":"不同意","examples":[{"en":"Esperantists disagree with the critics.","zh":"世界語者不同意批評者。"},{"en":"To disagree means to have a different opinion from someone else.","zh":"disagree 指與他人有不同意見。"},{"en":"Students may disagree about whether online learning is better than classroom learning.","zh":"學生可能不同意網上學習是否比課室學習更好。"},{"en":"Disagreement can improve discussion if people give reasons calmly.","zh":"如果人們冷靜提出理由，分歧可以改善討論。"},{"en":"This word is useful in debate and opinion writing.","zh":"這個詞適用於辯論和意見寫作。"}],"source":"75 - One Who Hopes.pdf","sourcePage":12},{"front":"claim that","meaning":"聲稱；主張","examples":[{"en":"Esperantists claim that Esperanto has a rich body of translated literature.","zh":"世界語者聲稱世界語有大量豐富翻譯文學。"},{"en":"To claim that means to state something as true, especially when others may question it.","zh":"claim that 指把某事陳述為真，尤其是當別人可能質疑時。"},{"en":"A company may claim that its app helps students learn faster.","zh":"公司可能聲稱其應用程式幫助學生更快學習。"},{"en":"Claims need evidence if they are to persuade careful readers.","zh":"說法若要說服仔細讀者，需要證據。"},{"en":"This phrase is common in arguments and reports.","zh":"這個短語常見於論證和報告。"}],"source":"75 - One Who Hopes.pdf","sourcePage":12},{"front":"a great body of world literature","meaning":"大量世界文學","examples":[{"en":"A great body of world literature has been translated into Esperanto.","zh":"大量世界文學已被翻譯成世界語。"},{"en":"A great body of world literature means a large collection of important literary works from many cultures.","zh":"great body of world literature 指來自許多文化的大量重要文學作品。"},{"en":"A library with novels, poems, and plays from many countries holds a body of world literature.","zh":"收藏多國小說、詩歌和戲劇的圖書館擁有大量世界文學。"},{"en":"Translation can make world literature available to readers of another language.","zh":"翻譯可以讓另一種語言的讀者接觸世界文學。"},{"en":"This phrase emphasises both quantity and cultural value.","zh":"這個短語同時強調數量和文化價值。"}],"source":"75 - One Who Hopes.pdf","sourcePage":12},{"front":"be translated into","meaning":"被翻譯成……","examples":[{"en":"Many works have been translated into Esperanto.","zh":"許多作品已被翻譯成世界語。"},{"en":"To be translated into a language means to be changed from one language into another.","zh":"be translated into a language 指由一種語言轉換成另一種語言。"},{"en":"A children’s book may be translated into several languages for international readers.","zh":"兒童書可能被翻譯成幾種語言，供國際讀者閱讀。"},{"en":"Translation helps ideas travel beyond their original speech community.","zh":"翻譯幫助想法走出原本語言社群。"},{"en":"This phrase is common in literature and communication.","zh":"這個短語常見於文學和溝通。"}],"source":"75 - One Who Hopes.pdf","sourcePage":12},{"front":"literary journals","meaning":"文學期刊","examples":[{"en":"Esperanto includes poetry, novels and literary journals.","zh":"世界語包括詩歌、小說和文學期刊。"},{"en":"Literary journals are magazines or periodicals that publish poems, stories, essays, and criticism.","zh":"literary journals 指刊登詩、故事、文章和評論的雜誌或期刊。"},{"en":"A university may produce a literary journal for student writers.","zh":"大學可能為學生作家出版文學期刊。"},{"en":"Journals help writers share new work with a community.","zh":"期刊幫助作家與社群分享新作品。"},{"en":"This phrase is common in literature and publishing.","zh":"這個短語常見於文學和出版。"}],"source":"75 - One Who Hopes.pdf","sourcePage":12},{"front":"rebut the accusation that","meaning":"反駁……的指控","examples":[{"en":"Esperantists try to rebut the accusation that Esperanto is not a real language.","zh":"世界語者嘗試反駁世界語不是真正語言的指控。"},{"en":"To rebut the accusation that means to argue against a criticism or charge.","zh":"rebut the accusation that 指反駁一項批評或指控。"},{"en":"A school may rebut the accusation that it ignores weaker students by showing support programmes.","zh":"學校可能透過展示支援計劃，反駁它忽視較弱學生的指控。"},{"en":"Rebuttal requires reasons or evidence, not just denial.","zh":"反駁需要理由或證據，而不只是否認。"},{"en":"This phrase is formal and common in debate.","zh":"這個短語較正式，常見於辯論。"}],"source":"75 - One Who Hopes.pdf","sourcePage":13},{"front":"point out that","meaning":"指出","examples":[{"en":"Esperantists point out that Esperanto is used at international meetings.","zh":"世界語者指出世界語在國際會議中使用。"},{"en":"To point out that means to mention a fact clearly because it supports an argument.","zh":"point out that 指清楚提到某事實，因為它支持論點。"},{"en":"A teacher may point out that examples help students remember new words.","zh":"老師可能指出例子有助學生記住新詞。"},{"en":"Pointing out evidence can correct a mistaken impression.","zh":"指出證據可以修正錯誤印象。"},{"en":"This phrase is useful in explanation and persuasion.","zh":"這個短語適合解釋和說服。"}],"source":"75 - One Who Hopes.pdf","sourcePage":13},{"front":"be frequently used at","meaning":"經常在……使用","examples":[{"en":"Esperanto is frequently used at international meetings.","zh":"世界語經常在國際會議中使用。"},{"en":"To be frequently used at a place or event means to be used there often.","zh":"be frequently used at a place or event 指在某地或活動中經常被使用。"},{"en":"English is frequently used at business conferences.","zh":"英語經常在商業會議中使用。"},{"en":"Frequent use can make a language feel practical and alive.","zh":"頻繁使用可以令一種語言感覺實用而有生命力。"},{"en":"This phrase describes regular use in a specific setting.","zh":"這個短語描述特定場合中的常規使用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":13},{"front":"international meetings","meaning":"國際會議","examples":[{"en":"Esperanto is used at international meetings.","zh":"世界語在國際會議中使用。"},{"en":"International meetings are gatherings where people from different countries discuss shared topics.","zh":"international meetings 指來自不同國家的人討論共同主題的聚會。"},{"en":"Climate conferences and academic congresses are international meetings.","zh":"氣候會議和學術大會都是國際會議。"},{"en":"Shared language can make international meetings more efficient and inclusive.","zh":"共同語言可以令國際會議更有效率、更包容。"},{"en":"This phrase is common in diplomacy, business, and scholarship.","zh":"這個短語常見於外交、商業和學術。"}],"source":"75 - One Who Hopes.pdf","sourcePage":13},{"front":"draw hundreds or thousands of participants","meaning":"吸引數百或數千名參加者","examples":[{"en":"Some international meetings draw hundreds or thousands of participants.","zh":"有些國際會議吸引數百或數千名參加者。"},{"en":"To draw hundreds or thousands of participants means to attract many people to attend.","zh":"draw hundreds or thousands of participants 指吸引大量人士出席。"},{"en":"A popular education fair may draw thousands of parents and students.","zh":"受歡迎的教育展可能吸引數千名家長和學生。"},{"en":"Large attendance shows that an event or movement has active interest.","zh":"大量出席顯示活動或運動有活躍興趣。"},{"en":"This phrase is used for events that attract big crowds.","zh":"這個短語用於吸引大批人群的活動。"}],"source":"75 - One Who Hopes.pdf","sourcePage":13},{"front":"on an international scale","meaning":"在國際層面上","examples":[{"en":"On an international scale, Esperanto is useful for neutral communication.","zh":"在國際層面上，世界語有助中立溝通。"},{"en":"On an international scale means across many countries or globally.","zh":"on an international scale 指跨越許多國家或在全球層面。"},{"en":"A health problem on an international scale needs cooperation between governments.","zh":"國際層面的健康問題需要各國政府合作。"},{"en":"Large-scale communication problems require solutions beyond one nation.","zh":"大規模溝通問題需要超越單一國家的解決方案。"},{"en":"This phrase expands the discussion from local to global.","zh":"這個短語把討論由本地擴展到全球。"}],"source":"75 - One Who Hopes.pdf","sourcePage":13},{"front":"neutral communication","meaning":"中立溝通","examples":[{"en":"Esperanto is useful for neutral communication.","zh":"世界語有助中立溝通。"},{"en":"Neutral communication is communication that does not favour one nation, culture, or native-language group.","zh":"neutral communication 指不偏向某一國家、文化或母語群體的溝通。"},{"en":"A meeting may use a neutral language so no one gains an unfair advantage.","zh":"會議可能使用中立語言，使沒有人取得不公平優勢。"},{"en":"Neutral communication can make participants feel more equal.","zh":"中立溝通可以令參與者感到更平等。"},{"en":"This phrase connects language choice with fairness.","zh":"這個短語把語言選擇與公平連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":13},{"front":"give an advantage to","meaning":"給予……優勢","examples":[{"en":"Esperanto does not give an advantage to any particular nation.","zh":"世界語不會給予任何特定國家優勢。"},{"en":"To give an advantage to someone means to make their position stronger or easier.","zh":"give an advantage to someone 指令某人的位置更強或更容易。"},{"en":"A test in one student’s native language may give an advantage to that student.","zh":"以某學生母語進行的測驗可能給予該學生優勢。"},{"en":"If a system gives one group an advantage, others may feel unfairly treated.","zh":"如果制度給予某群體優勢，其他人可能覺得不公平。"},{"en":"This phrase is useful when discussing fairness and competition.","zh":"這個短語適合討論公平和競爭。"}],"source":"75 - One Who Hopes.pdf","sourcePage":13},{"front":"members of any particular nation or culture","meaning":"任何特定國家或文化的成員","examples":[{"en":"Esperanto does not favour members of any particular nation or culture.","zh":"世界語不偏袒任何特定國家或文化的成員。"},{"en":"Members of any particular nation or culture are people belonging to a specific national or cultural group.","zh":"members of any particular nation or culture 指屬於某一特定國家或文化群體的人。"},{"en":"An international exam should not unfairly favour members of one culture.","zh":"國際考試不應不公平地偏袒某一文化的成員。"},{"en":"Neutral design can help people from different backgrounds participate more equally.","zh":"中立設計可以幫助不同背景的人更平等地參與。"},{"en":"This phrase focuses on group membership and fairness.","zh":"這個短語聚焦群體成員身份和公平。"}],"source":"75 - One Who Hopes.pdf","sourcePage":13},{"front":"provide an ethos of","meaning":"提供一種……精神","examples":[{"en":"Esperanto provides an ethos of equality and tolerance.","zh":"世界語提供一種平等和包容的精神。"},{"en":"To provide an ethos of something means to create a guiding spirit or set of values.","zh":"provide an ethos of something 指創造一種指導精神或價值觀。"},{"en":"A school can provide an ethos of respect through fair rules and kind behaviour.","zh":"學校可以透過公平規則和友善行為提供尊重精神。"},{"en":"An ethos shapes how people feel and act within a community.","zh":"精神氛圍會塑造社群中人們的感受和行為。"},{"en":"This phrase is formal and values-based.","zh":"這個短語較正式，與價值觀有關。"}],"source":"75 - One Who Hopes.pdf","sourcePage":13},{"front":"equality of rights","meaning":"權利平等","examples":[{"en":"Esperanto promotes equality of rights.","zh":"世界語促進權利平等。"},{"en":"Equality of rights means all people have the same basic rights and respect.","zh":"equality of rights 指所有人都有相同基本權利和尊重。"},{"en":"A fair classroom supports equality of rights by listening to every student.","zh":"公平課室透過聆聽每位學生來支持權利平等。"},{"en":"If rights are unequal, some people may be silenced or excluded.","zh":"如果權利不平等，有些人可能被噤聲或排除。"},{"en":"This phrase is common in social and political discussion.","zh":"這個短語常見於社會和政治討論。"}],"source":"75 - One Who Hopes.pdf","sourcePage":13},{"front":"tolerance","meaning":"包容","examples":[{"en":"Esperanto supporters associate the language with tolerance.","zh":"世界語支持者把這種語言與包容聯繫起來。"},{"en":"Tolerance means accepting or respecting people who are different from oneself.","zh":"tolerance 指接受或尊重與自己不同的人。"},{"en":"A school shows tolerance when students from different backgrounds feel safe.","zh":"當不同背景的學生感到安全，學校就顯示包容。"},{"en":"Tolerance can reduce conflict because people learn not to reject difference immediately.","zh":"包容可以減少衝突，因為人們學會不立即排斥差異。"},{"en":"This word is central to peaceful community life.","zh":"這個詞是和平社群生活的核心。"}],"source":"75 - One Who Hopes.pdf","sourcePage":14},{"front":"true internationalism","meaning":"真正的國際主義","examples":[{"en":"Esperanto is linked with true internationalism.","zh":"世界語與真正的國際主義有關。"},{"en":"True internationalism is the belief that people from different countries should cooperate equally.","zh":"true internationalism 指相信不同國家的人應平等合作。"},{"en":"A truly international school values many cultures, not only the most powerful one.","zh":"真正國際化的學校重視許多文化，而不只是最強勢的一種。"},{"en":"Internationalism becomes meaningful when no group is treated as naturally superior.","zh":"當沒有群體被視為天生優越，國際主義才變得有意義。"},{"en":"This phrase connects global cooperation with fairness.","zh":"這個短語把全球合作與公平連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":14},{"front":"further claim that","meaning":"進一步聲稱","examples":[{"en":"Esperantists further claim that Esperanto could empower ordinary people.","zh":"世界語者進一步聲稱世界語可以賦權普通人。"},{"en":"Further claim that means add another claim to an existing argument.","zh":"further claim that 指在現有論點上再加入另一個主張。"},{"en":"A teacher may further claim that reading improves both writing and confidence.","zh":"老師可能進一步聲稱閱讀同時改善寫作和信心。"},{"en":"This phrase signals that the argument is continuing with another point.","zh":"這個短語表示論點正在以另一點延續。"},{"en":"It is useful in structured essays and discussions.","zh":"它適用於有結構的文章和討論。"}],"source":"75 - One Who Hopes.pdf","sourcePage":14},{"front":"have the potential to","meaning":"有潛力去……","examples":[{"en":"Esperanto has the potential to improve global communication.","zh":"世界語有潛力改善全球溝通。"},{"en":"To have the potential to do something means to be able to possibly do it in the future.","zh":"have the potential to do something 指將來可能有能力做到某事。"},{"en":"A quiet student may have the potential to become a strong speaker with practice.","zh":"安靜學生透過練習可能有潛力成為出色演講者。"},{"en":"Potential is not a guarantee; it needs conditions and effort to become real.","zh":"潛力不是保證；它需要條件和努力才能實現。"},{"en":"This phrase expresses possibility and promise.","zh":"這個短語表達可能性和前景。"}],"source":"75 - One Who Hopes.pdf","sourcePage":14},{"front":"were it universally taught","meaning":"如果它被普遍教授","examples":[{"en":"Esperanto could be powerful were it universally taught for a year or two.","zh":"如果世界語被普遍教授一兩年，它可能很有力量。"},{"en":"Were it universally taught means if it were taught to everyone or very widely.","zh":"were it universally taught 指如果它被教給所有人或非常廣泛地教授。"},{"en":"Were basic first aid universally taught, more people could help in emergencies.","zh":"如果基本急救被普遍教授，更多人可以在緊急情況中幫忙。"},{"en":"This structure is formal and means if it were.","zh":"這個結構較正式，意思是 if it were。"},{"en":"It introduces a hypothetical condition.","zh":"它引入假設條件。"}],"source":"75 - One Who Hopes.pdf","sourcePage":14},{"front":"throughout the world","meaning":"遍及全球","examples":[{"en":"Esperanto could be taught throughout the world.","zh":"世界語可以在全球各地教授。"},{"en":"Throughout the world means in many or all parts of the world.","zh":"throughout the world 指在世界許多地方或所有地方。"},{"en":"Online courses can reach students throughout the world.","zh":"網上課程可以接觸全球各地的學生。"},{"en":"A global teaching plan would require materials, teachers, and support in many countries.","zh":"全球教學計劃需要許多國家的教材、教師和支援。"},{"en":"This phrase emphasises worldwide spread.","zh":"這個短語強調全球範圍。"}],"source":"75 - One Who Hopes.pdf","sourcePage":14},{"front":"empower ordinary people to","meaning":"使普通人有能力去……","examples":[{"en":"Esperanto could empower ordinary people to communicate worldwide.","zh":"世界語可以使普通人有能力在全球溝通。"},{"en":"To empower ordinary people to do something means to give non-specialists the ability or confidence to do it.","zh":"empower ordinary people to do something 指讓非專家有能力或信心做某事。"},{"en":"Simple legal information can empower ordinary people to understand their rights.","zh":"簡單法律資訊可以使普通人有能力理解自己的權利。"},{"en":"When communication becomes easier, people outside elites can participate more fully.","zh":"當溝通變得更容易，精英以外的人可以更充分參與。"},{"en":"This phrase links access with power.","zh":"這個短語把可及性與力量連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":14},{"front":"communicate effectively worldwide","meaning":"在全球有效溝通","examples":[{"en":"Esperanto could help ordinary people communicate effectively worldwide.","zh":"世界語可以幫助普通人在全球有效溝通。"},{"en":"To communicate effectively worldwide means to exchange ideas clearly with people across the world.","zh":"communicate effectively worldwide 指與世界各地的人清楚交流想法。"},{"en":"A shared language can help scientists communicate effectively worldwide.","zh":"共同語言可以幫助科學家在全球有效溝通。"},{"en":"Effective global communication reduces confusion, delay, and dependence on translators.","zh":"有效全球溝通減少混亂、延誤和對翻譯的依賴。"},{"en":"This phrase focuses on clear communication across countries.","zh":"這個短語聚焦跨國清楚溝通。"}],"source":"75 - One Who Hopes.pdf","sourcePage":14},{"front":"on a scale that","meaning":"以……的規模","examples":[{"en":"Esperanto could improve communication on a scale that is not attainable today.","zh":"世界語可以以今天無法達到的規模改善溝通。"},{"en":"On a scale that means at a size, level, or extent that has a particular quality.","zh":"on a scale that 指以具有某種特質的大小、水平或範圍。"},{"en":"Online education can reach learners on a scale that local classrooms cannot match.","zh":"網上教育可以以本地課室不能相比的規模接觸學習者。"},{"en":"Scale matters because a small solution may not solve a global problem.","zh":"規模很重要，因為小解決方案未必能解決全球問題。"},{"en":"This phrase is useful when discussing large impact.","zh":"討論巨大影響時，這個短語很有用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":14},{"front":"far exceed","meaning":"遠遠超過","examples":[{"en":"Esperanto could far exceed today’s level of global communication.","zh":"世界語可以遠遠超過今天的全球溝通水平。"},{"en":"To far exceed something means to go much beyond it.","zh":"far exceed something 指大幅超越某事。"},{"en":"A student’s final essay may far exceed the quality of her first draft.","zh":"學生的終稿質素可能遠遠超過第一稿。"},{"en":"When results far exceed expectations, people may rethink what is possible.","zh":"當結果遠超預期，人們可能重新思考甚麼是可能的。"},{"en":"This phrase expresses a large difference above a standard.","zh":"這個短語表達遠高於某標準的巨大差異。"}],"source":"75 - One Who Hopes.pdf","sourcePage":14},{"front":"be attainable today","meaning":"今天能夠達到","examples":[{"en":"This level of communication is attainable today only by very gifted language learners.","zh":"這種溝通水平今天只有極有語言天分的學習者才能達到。"},{"en":"To be attainable today means to be possible to reach in the present time.","zh":"be attainable today 指在今天有可能達到。"},{"en":"For many students, fluency is attainable today if they practise consistently.","zh":"對許多學生來說，如果持續練習，流利程度今天是可以達到的。"},{"en":"If something is not widely attainable, only a small group can reach it.","zh":"如果某事不是廣泛可達，只有少數人能達到。"},{"en":"This phrase describes present possibility.","zh":"這個短語描述當前可能性。"}],"source":"75 - One Who Hopes.pdf","sourcePage":14},{"front":"linguistically brilliant","meaning":"語言天分極高的","examples":[{"en":"The privilege is usually limited to the most linguistically brilliant people.","zh":"這種特權通常只限於語言天分極高的人。"},{"en":"Linguistically brilliant means extremely talented at languages.","zh":"linguistically brilliant 指在語言方面極有天分。"},{"en":"A linguistically brilliant student may learn grammar patterns very quickly.","zh":"語言天分極高的學生可能很快學會文法模式。"},{"en":"If only linguistically brilliant people can communicate globally, most people are left out.","zh":"如果只有語言天分極高的人才能全球溝通，大多數人會被排除在外。"},{"en":"This phrase describes exceptional language ability.","zh":"這個短語描述非凡語言能力。"}],"source":"75 - One Who Hopes.pdf","sourcePage":15},{"front":"among us","meaning":"在我們之中","examples":[{"en":"Only the most linguistically brilliant among us can reach that level today.","zh":"今天只有我們之中語言天分最高的人能達到那種水平。"},{"en":"Among us means within our group or among people like us.","zh":"among us 指在我們這個群體或我們這類人之中。"},{"en":"The best singer among us led the school performance.","zh":"我們之中唱歌最好的人帶領學校表演。"},{"en":"This phrase places a person or group inside a larger community.","zh":"這個短語把某人或某群體放在更大社群之內。"},{"en":"It can make a sentence feel inclusive and personal.","zh":"它可以令句子感覺更有包容性和個人感。"}],"source":"75 - One Who Hopes.pdf","sourcePage":15},{"front":"offer the opportunity to","meaning":"提供……的機會","examples":[{"en":"Esperanto offers the opportunity to improve communication.","zh":"世界語提供改善溝通的機會。"},{"en":"To offer the opportunity to do something means to give people a chance to do it.","zh":"offer the opportunity to do something 指給人機會做某事。"},{"en":"A scholarship offers the opportunity to study abroad.","zh":"獎學金提供出國讀書的機會。"},{"en":"Opportunities matter because they open doors that were previously closed.","zh":"機會很重要，因為它打開以前關閉的大門。"},{"en":"This phrase is positive and common in education and policy.","zh":"這個短語帶正面意味，常見於教育和政策。"}],"source":"75 - One Who Hopes.pdf","sourcePage":15},{"front":"improve communication in","meaning":"改善……方面的溝通","examples":[{"en":"Esperanto could improve communication in business, diplomacy and scholarship.","zh":"世界語可以改善商業、外交和學術方面的溝通。"},{"en":"To improve communication in an area means to make exchange of information clearer in that field.","zh":"improve communication in an area 指令某領域中的資訊交流更清楚。"},{"en":"Better signs can improve communication in hospitals.","zh":"更好的標誌可以改善醫院中的溝通。"},{"en":"Clearer communication reduces mistakes and saves time.","zh":"更清楚溝通可以減少錯誤並節省時間。"},{"en":"This phrase connects language with practical fields of work.","zh":"這個短語把語言與實際工作領域連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":15},{"front":"business, diplomacy and scholarship","meaning":"商業、外交和學術","examples":[{"en":"Esperanto could be useful in business, diplomacy and scholarship.","zh":"世界語可以在商業、外交和學術中有用。"},{"en":"Business, diplomacy and scholarship are fields involving trade, international relations, and academic study.","zh":"business, diplomacy and scholarship 指涉及貿易、國際關係和學術研究的領域。"},{"en":"Clear language helps business deals, diplomatic talks, and academic conferences.","zh":"清楚語言有助商業交易、外交談判和學術會議。"},{"en":"Miscommunication in these fields can cost money, trust, or knowledge.","zh":"這些領域中的誤解可能造成金錢、信任或知識損失。"},{"en":"This phrase lists major international communication contexts.","zh":"這個短語列出主要國際溝通語境。"}],"source":"75 - One Who Hopes.pdf","sourcePage":15},{"front":"native languages","meaning":"母語","examples":[{"en":"People who speak different native languages could communicate more easily.","zh":"說不同母語的人可以更容易溝通。"},{"en":"Native languages are the languages people learn first or use from childhood.","zh":"native languages 指人們最先學會或自小使用的語言。"},{"en":"A child’s native language is often the language spoken at home.","zh":"孩子的母語通常是在家中使用的語言。"},{"en":"When people have different native languages, they may need a shared second language.","zh":"當人們有不同母語，他們可能需要共同第二語言。"},{"en":"This phrase is central to language identity and communication.","zh":"這個短語是語言身份和溝通的核心。"}],"source":"75 - One Who Hopes.pdf","sourcePage":15},{"front":"participate fluently in","meaning":"流利地參與……","examples":[{"en":"Esperanto could help people participate fluently in international conferences.","zh":"世界語可以幫助人們流利地參與國際會議。"},{"en":"To participate fluently in something means to take part smoothly and confidently using language.","zh":"participate fluently in something 指用語言順暢而有信心地參與某事。"},{"en":"A student can participate fluently in a discussion if she understands the topic and vocabulary.","zh":"如果學生理解主題和詞彙，她可以流利地參與討論。"},{"en":"Fluency allows people to contribute ideas instead of staying silent.","zh":"流利程度讓人能貢獻想法，而不是保持沉默。"},{"en":"This phrase links language ability with active participation.","zh":"這個短語把語言能力與積極參與連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":15},{"front":"international conferences","meaning":"國際會議","examples":[{"en":"Esperanto could make international conferences more accessible.","zh":"世界語可以令國際會議更容易參與。"},{"en":"International conferences are formal events where people from different countries meet to discuss a topic.","zh":"international conferences 指來自不同國家的人聚集討論某主題的正式活動。"},{"en":"Researchers attend international conferences to present studies and meet colleagues.","zh":"研究人員參加國際會議以發表研究並認識同事。"},{"en":"Language barriers can make conferences harder for non-native speakers.","zh":"語言障礙可以令非母語人士更難參與會議。"},{"en":"This phrase is common in business, science, and diplomacy.","zh":"這個短語常見於商業、科學和外交。"}],"source":"75 - One Who Hopes.pdf","sourcePage":15},{"front":"chat comfortably with","meaning":"與……自在地閒談","examples":[{"en":"Speakers could chat comfortably with each other after presentations.","zh":"講者可以在演講後彼此自在地閒談。"},{"en":"To chat comfortably with someone means to talk casually without stress or difficulty.","zh":"chat comfortably with someone 指輕鬆地與某人閒談，沒有壓力或困難。"},{"en":"Students chat comfortably with classmates when they feel accepted.","zh":"當學生感到被接納，他們會自在地與同學聊天。"},{"en":"Comfortable conversation helps build relationships beyond formal meetings.","zh":"自在對話有助在正式會議以外建立關係。"},{"en":"This phrase describes relaxed social communication.","zh":"這個短語描述輕鬆社交溝通。"}],"source":"75 - One Who Hopes.pdf","sourcePage":15},{"front":"formal presentations","meaning":"正式演講；正式匯報","examples":[{"en":"People could talk after the formal presentations are made.","zh":"人們可以在正式演講結束後交談。"},{"en":"Formal presentations are organised speeches or reports given in a professional or academic setting.","zh":"formal presentations 指在專業或學術場合中有組織的演講或報告。"},{"en":"Students may give formal presentations with slides and prepared notes.","zh":"學生可能用投影片和準備好的筆記作正式匯報。"},{"en":"After formal presentations, informal discussion often helps people build deeper understanding.","zh":"正式演講後，非正式討論常幫助人建立更深入理解。"},{"en":"This phrase contrasts prepared public speaking with casual conversation.","zh":"這個短語把準備好的公開發言與隨意對話作對比。"}],"source":"75 - One Who Hopes.pdf","sourcePage":15},{"front":"that privilege","meaning":"那種特權","examples":[{"en":"That privilege is often restricted to native speakers of English.","zh":"那種特權常限於以英語為母語的人。"},{"en":"That privilege refers to the special advantage just mentioned.","zh":"that privilege 指剛才提到的特殊優勢。"},{"en":"In a meeting, speaking easily in the main language can be a privilege.","zh":"在會議中，能輕鬆使用主要語言發言可以是一種特權。"},{"en":"If only one group has that privilege, others may participate less fully.","zh":"如果只有一個群體有那種特權，其他人可能較難充分參與。"},{"en":"This phrase points back to a benefit already described.","zh":"這個短語指回已描述的好處。"}],"source":"75 - One Who Hopes.pdf","sourcePage":15},{"front":"be restricted to","meaning":"限於……","examples":[{"en":"The privilege is often restricted to native speakers of English.","zh":"這種特權常限於以英語為母語的人。"},{"en":"To be restricted to a group means to be limited to that group only.","zh":"be restricted to a group 指只限於某群體。"},{"en":"Some library rooms are restricted to postgraduate students.","zh":"有些圖書館房間只限研究生使用。"},{"en":"Restrictions can create inequality if access is unfairly limited.","zh":"如果使用權被不公平限制，限制可能造成不平等。"},{"en":"This phrase describes limits on use, access, or benefit.","zh":"這個短語描述使用、接觸或利益上的限制。"}],"source":"75 - One Who Hopes.pdf","sourcePage":16},{"front":"native speakers of English","meaning":"以英語為母語的人","examples":[{"en":"Native speakers of English often have an advantage in international communication.","zh":"以英語為母語的人在國際溝通中常有優勢。"},{"en":"Native speakers of English are people who learned English as their first language.","zh":"native speakers of English 指把英語作為第一語言學會的人。"},{"en":"A native speaker may speak more naturally in an English-language conference.","zh":"母語英語者在英語會議中可能說得更自然。"},{"en":"When English dominates, native speakers may need less preparation than others.","zh":"當英語佔主導，母語英語者可能比其他人需要較少準備。"},{"en":"This phrase identifies a group with possible language advantage.","zh":"這個短語指出可能具有語言優勢的群體。"}],"source":"75 - One Who Hopes.pdf","sourcePage":16},{"front":"special talents and opportunities","meaning":"特殊才能和機會","examples":[{"en":"Some people have special talents and opportunities for learning English.","zh":"有些人有學習英語的特殊才能和機會。"},{"en":"Special talents and opportunities are unusual abilities and chances that help someone succeed.","zh":"special talents and opportunities 指幫助某人成功的不尋常能力和機會。"},{"en":"A student with a good ear for sounds and access to native speakers has special language opportunities.","zh":"對聲音敏銳且能接觸母語者的學生，有特殊語言學習機會。"},{"en":"People without such advantages may need more time and support.","zh":"沒有這些優勢的人可能需要更多時間和支援。"},{"en":"This phrase explains why success is not equally easy for everyone.","zh":"這個短語解釋為何成功對每個人來說並不一樣容易。"}],"source":"75 - One Who Hopes.pdf","sourcePage":16},{"front":"English as a foreign language","meaning":"作為外語的英語","examples":[{"en":"Many people learn English as a foreign language.","zh":"許多人學習作為外語的英語。"},{"en":"English as a foreign language means English learned by people whose native language is not English.","zh":"English as a foreign language 指由母語不是英語的人學習的英語。"},{"en":"A student in Japan may study English as a foreign language at school.","zh":"日本學生可能在學校學習作為外語的英語。"},{"en":"Learning English as a foreign language can require extra effort outside daily life.","zh":"學習作為外語的英語可能需要在日常生活以外額外努力。"},{"en":"This phrase is common in language education.","zh":"這個短語常見於語言教育。"}],"source":"75 - One Who Hopes.pdf","sourcePage":16},{"front":"in concrete terms","meaning":"具體而言","examples":[{"en":"In concrete terms, Esperanto could save billions of dollars.","zh":"具體而言，世界語可以節省數十億美元。"},{"en":"In concrete terms means in a specific, practical, and measurable way.","zh":"in concrete terms 指以具體、實際且可衡量的方式來說。"},{"en":"In concrete terms, sleeping earlier may give a student two extra hours of focus.","zh":"具體而言，早睡可能給學生多兩小時專注力。"},{"en":"This phrase moves from a general idea to a clear real-world effect.","zh":"這個短語把一般想法轉到清楚的現實效果。"},{"en":"It is useful when explaining practical benefits.","zh":"解釋實際好處時，它很有用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":16},{"front":"the potential to save","meaning":"節省……的潛力","examples":[{"en":"Esperanto offers the potential to save large amounts of money.","zh":"世界語提供節省大量金錢的潛力。"},{"en":"The potential to save means the possible ability to reduce costs or avoid waste.","zh":"potential to save 指可能有能力減少成本或避免浪費。"},{"en":"Solar panels may offer the potential to save electricity bills over time.","zh":"太陽能板可能有潛力隨時間節省電費。"},{"en":"Potential savings become real only if the system is widely used.","zh":"潛在節省只有在系統被廣泛使用時才會成真。"},{"en":"This phrase expresses possible financial benefit.","zh":"這個短語表達可能的財務好處。"}],"source":"75 - One Who Hopes.pdf","sourcePage":16},{"front":"billions of dollars","meaning":"數十億美元","examples":[{"en":"Billions of dollars are spent on translation and interpretation.","zh":"數十億美元被花在翻譯和傳譯上。"},{"en":"Billions of dollars means thousands of millions of dollars.","zh":"billions of dollars 指數以十億計的美元。"},{"en":"Governments may spend billions of dollars on healthcare each year.","zh":"政府每年可能在醫療上花費數十億美元。"},{"en":"Large sums can affect public budgets and policy choices.","zh":"巨額款項可以影響公共預算和政策選擇。"},{"en":"This phrase emphasises very large financial scale.","zh":"這個短語強調非常大的財務規模。"}],"source":"75 - One Who Hopes.pdf","sourcePage":16},{"front":"be spent on","meaning":"被花在……上","examples":[{"en":"Large sums are spent on translators and interpreters.","zh":"大筆款項被花在筆譯員和傳譯員上。"},{"en":"To be spent on something means money is used to pay for it.","zh":"be spent on something 指金錢被用來支付某事。"},{"en":"School funds may be spent on books, computers, and repairs.","zh":"學校資金可能被花在書本、電腦和維修上。"},{"en":"If money is spent on one purpose, less may remain for another.","zh":"如果金錢花在一個目的上，留給另一目的的可能較少。"},{"en":"This phrase is common in budgeting and public finance.","zh":"這個短語常見於預算和公共財政。"}],"source":"75 - One Who Hopes.pdf","sourcePage":16},{"front":"translators and interpreters","meaning":"筆譯員和傳譯員","examples":[{"en":"Governments and organisations spend money on translators and interpreters.","zh":"政府和組織把金錢花在筆譯員和傳譯員上。"},{"en":"Translators work with written language, while interpreters work with spoken language.","zh":"translators 處理書面語言，而 interpreters 處理口頭語言。"},{"en":"A hospital may need interpreters to help patients explain symptoms.","zh":"醫院可能需要傳譯員幫助病人解釋症狀。"},{"en":"Without translators and interpreters, international communication can slow down.","zh":"沒有筆譯員和傳譯員，國際溝通可能變慢。"},{"en":"This phrase names two language-service professions.","zh":"這個短語指兩種語言服務職業。"}],"source":"75 - One Who Hopes.pdf","sourcePage":16},{"front":"be freed up to","meaning":"被騰出來用於……","examples":[{"en":"Money spent on translation could be freed up to serve other purposes.","zh":"花在翻譯上的金錢可以被騰出來用於其他目的。"},{"en":"To be freed up to do something means to become available for another use.","zh":"be freed up to do something 指變得可供其他用途使用。"},{"en":"If a school saves money on printing, funds can be freed up to buy books.","zh":"如果學校節省印刷費，資金可以被騰出來買書。"},{"en":"Freeing resources allows organisations to support more urgent needs.","zh":"騰出資源讓機構支援更迫切需要。"},{"en":"This phrase is useful in budgeting and planning.","zh":"這個短語適合預算和規劃語境。"}],"source":"75 - One Who Hopes.pdf","sourcePage":16},{"front":"serve the purposes of","meaning":"服務於……的目的","examples":[{"en":"The money could serve the purposes of governments and organisations.","zh":"這筆錢可以服務於政府和組織的目的。"},{"en":"To serve the purposes of someone means to help meet their aims or needs.","zh":"serve the purposes of someone 指幫助滿足某人的目標或需要。"},{"en":"A community hall can serve the purposes of schools, charities, and local families.","zh":"社區會堂可以服務學校、慈善機構和本地家庭的目的。"},{"en":"Money used well can support several important purposes at once.","zh":"妥善使用的金錢可以同時支持幾個重要目的。"},{"en":"This phrase is formal and purpose-focused.","zh":"這個短語較正式，聚焦目的。"}],"source":"75 - One Who Hopes.pdf","sourcePage":16},{"front":"spend resources doing something","meaning":"花資源做某事","examples":[{"en":"Organisations spend resources translating from one language into another.","zh":"組織花資源把一種語言翻譯成另一種語言。"},{"en":"To spend resources doing something means to use money, time, staff, or energy on that activity.","zh":"spend resources doing something 指把金錢、時間、人手或精力用於某活動。"},{"en":"A school may spend resources training teachers to use new software.","zh":"學校可能花資源培訓教師使用新軟件。"},{"en":"If resources are spent on one task, fewer resources remain for other tasks.","zh":"如果資源花在一項任務上，留給其他任務的資源就較少。"},{"en":"This phrase is useful when discussing efficiency and priorities.","zh":"討論效率和優先次序時，這個短語很有用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":17},{"front":"translate from one language into another","meaning":"從一種語言翻譯成另一種語言","examples":[{"en":"Many organisations translate from one language into another.","zh":"許多組織把一種語言翻譯成另一種語言。"},{"en":"To translate from one language into another means to change meaning from a source language to a target language.","zh":"translate from one language into another 指把意思由來源語言轉換成目標語言。"},{"en":"A school notice may be translated from English into Chinese for parents.","zh":"學校通告可能由英文翻譯成中文給家長閱讀。"},{"en":"Translation helps people understand information they could not otherwise read.","zh":"翻譯幫助人理解原本看不懂的資訊。"},{"en":"This phrase describes written language transfer.","zh":"這個短語描述書面語言轉換。"}],"source":"75 - One Who Hopes.pdf","sourcePage":17},{"front":"take, for example","meaning":"以……為例","examples":[{"en":"Take, for example, the costly procedures of the European Union.","zh":"以歐盟昂貴的程序為例。"},{"en":"Take, for example means consider this as an example.","zh":"take, for example 指把某事作為例子來考慮。"},{"en":"Take, for example, a student who studies daily but never reviews mistakes.","zh":"以一名每天學習但從不檢討錯誤的學生為例。"},{"en":"This phrase introduces a concrete case to support a general point.","zh":"這個短語引出具體個案，以支持一般觀點。"},{"en":"It is useful when moving from claim to evidence.","zh":"從主張轉到證據時，它很有用。"}],"source":"75 - One Who Hopes.pdf","sourcePage":17},{"front":"enormously costly","meaning":"極其昂貴的","examples":[{"en":"European Union procedures can be enormously costly.","zh":"歐盟程序可能極其昂貴。"},{"en":"Enormously costly means extremely expensive.","zh":"enormously costly 指非常昂貴。"},{"en":"Repairing an old hospital can be enormously costly if many systems are broken.","zh":"如果許多系統損壞，維修舊醫院可能極其昂貴。"},{"en":"Very high costs can force organisations to reconsider how they work.","zh":"極高成本可以迫使機構重新考慮運作方式。"},{"en":"This phrase emphasises serious financial burden.","zh":"這個短語強調嚴重財政負擔。"}],"source":"75 - One Who Hopes.pdf","sourcePage":17},{"front":"documentation","meaning":"文件工作","examples":[{"en":"European Union procedures involve conferences, meetings and documentation.","zh":"歐盟程序涉及會議、聚會和文件工作。"},{"en":"Documentation means written records, forms, instructions, reports, or official papers.","zh":"documentation 指書面記錄、表格、指示、報告或官方文件。"},{"en":"Hospitals need accurate documentation when recording patient treatment.","zh":"醫院記錄病人治療時需要準確文件。"},{"en":"Poor documentation can create confusion and delay decisions.","zh":"文件工作欠佳可以造成混亂並延誤決定。"},{"en":"This word is common in administration and organisations.","zh":"這個詞常見於行政和組織語境。"}],"source":"75 - One Who Hopes.pdf","sourcePage":17},{"front":"European Union parliamentary procedures","meaning":"歐盟議會程序","examples":[{"en":"European Union parliamentary procedures require extensive translation.","zh":"歐盟議會程序需要大量翻譯。"},{"en":"European Union parliamentary procedures are formal processes used in the EU’s law-making body.","zh":"European Union parliamentary procedures 指歐盟立法機構使用的正式流程。"},{"en":"Parliamentary procedures often involve debates, documents, votes, and official records.","zh":"議會程序常涉及辯論、文件、投票和官方記錄。"},{"en":"When many languages are involved, procedures can become slower and more expensive.","zh":"當涉及許多語言，程序可能變得更慢、更昂貴。"},{"en":"This phrase refers to formal EU political processes.","zh":"這個短語指歐盟正式政治流程。"}],"source":"75 - One Who Hopes.pdf","sourcePage":17},{"front":"administrative procedures","meaning":"行政程序","examples":[{"en":"Administrative procedures in the European Union involve costly documentation.","zh":"歐盟行政程序涉及昂貴的文件工作。"},{"en":"Administrative procedures are official steps used to manage an organisation or system.","zh":"administrative procedures 指用來管理機構或系統的官方步驟。"},{"en":"A school’s administrative procedures may include enrolment, attendance records, and reports.","zh":"學校行政程序可能包括收生、出席記錄和報告。"},{"en":"Complex procedures can use large amounts of time and money.","zh":"複雜程序可以使用大量時間和金錢。"},{"en":"This phrase is common in government and office work.","zh":"這個短語常見於政府和辦公室工作。"}],"source":"75 - One Who Hopes.pdf","sourcePage":17},{"front":"all funded by taxpayers","meaning":"全部由納稅人資助","examples":[{"en":"These procedures are all funded by taxpayers.","zh":"這些程序全部由納稅人資助。"},{"en":"All funded by taxpayers means paid for using public money collected through taxes.","zh":"all funded by taxpayers 指用透過稅收收集的公共資金支付。"},{"en":"Public schools are largely funded by taxpayers.","zh":"公立學校大多由納稅人資助。"},{"en":"When taxpayers fund something, the public may demand efficiency and fairness.","zh":"當納稅人資助某事，公眾可能要求效率和公平。"},{"en":"This phrase highlights who pays for a public service.","zh":"這個短語突出公共服務由誰付款。"}],"source":"75 - One Who Hopes.pdf","sourcePage":17},{"front":"World Health Organisation","meaning":"世界衞生組織","examples":[{"en":"The World Health Organisation could use more money for health work.","zh":"世界衞生組織可以把更多金錢用於健康工作。"},{"en":"The World Health Organisation is an international body concerned with public health.","zh":"World Health Organisation 是關注公共衞生的國際機構。"},{"en":"A health organisation may fund vaccination, disease control, and emergency response.","zh":"衞生組織可能資助疫苗接種、疾病控制和緊急應變。"},{"en":"More resources for health work can support people in serious need.","zh":"更多健康工作資源可以支援有嚴重需要的人。"},{"en":"This phrase names a global health organisation.","zh":"這個短語指一個全球衞生組織。"}],"source":"75 - One Who Hopes.pdf","sourcePage":17},{"front":"NGOs","meaning":"非政府組織","examples":[{"en":"NGOs often spend large sums on translation and interpretation.","zh":"非政府組織常在翻譯和傳譯上花費大筆款項。"},{"en":"NGOs are non-governmental organisations that work on social, humanitarian, environmental, or community issues.","zh":"NGOs 指處理社會、人道、環境或社區議題的非政府組織。"},{"en":"An NGO may provide food, education, or medical help after a disaster.","zh":"非政府組織可能在災後提供食物、教育或醫療幫助。"},{"en":"NGOs need clear communication when they work across countries and languages.","zh":"非政府組織跨國和跨語言工作時需要清楚溝通。"},{"en":"This abbreviation is common in international affairs.","zh":"這個縮寫常見於國際事務。"}],"source":"75 - One Who Hopes.pdf","sourcePage":17},{"front":"devote enormous sums to","meaning":"投放巨額款項於……","examples":[{"en":"Some organisations devote enormous sums to interpreters and translations.","zh":"有些組織投放巨額款項於傳譯員和翻譯。"},{"en":"To devote enormous sums to something means to spend very large amounts of money on it.","zh":"devote enormous sums to something 指把非常大量金錢投放於某事。"},{"en":"A city may devote enormous sums to building a new railway.","zh":"城市可能投放巨額款項於興建新鐵路。"},{"en":"Large spending can be justified if the need is essential, but it may limit other work.","zh":"如果需要很重要，大筆開支可以合理，但也可能限制其他工作。"},{"en":"This phrase emphasises major financial commitment.","zh":"這個短語強調重大財務投入。"}],"source":"75 - One Who Hopes.pdf","sourcePage":17},{"front":"devote money to improving","meaning":"投放金錢去改善……","examples":[{"en":"Organisations could devote more money to improving public health.","zh":"組織可以投放更多金錢去改善公共衞生。"},{"en":"To devote money to improving something means to use funds to make it better.","zh":"devote money to improving something 指使用資金令某事變得更好。"},{"en":"A school may devote money to improving reading support for weaker students.","zh":"學校可能投放金錢去改善較弱學生的閱讀支援。"},{"en":"Funding improvement can create long-term benefits if it targets real needs.","zh":"如果資金針對真實需要，改善投資可以創造長遠好處。"},{"en":"This phrase links spending with positive change.","zh":"這個短語把花費與正面改變連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":18},{"front":"stricken populations","meaning":"受苦受災的人口","examples":[{"en":"More money could help improve the health of stricken populations.","zh":"更多金錢可以幫助改善受苦受災人口的健康。"},{"en":"Stricken populations are groups of people suffering from serious hardship, disaster, disease, or poverty.","zh":"stricken populations 指遭受嚴重困難、災害、疾病或貧窮的人群。"},{"en":"After a flood, stricken populations may need clean water and medicine.","zh":"水災後，受災人口可能需要清潔食水和藥物。"},{"en":"If aid reaches these groups quickly, suffering can be reduced.","zh":"如果援助快速到達這些群體，痛苦可以減少。"},{"en":"This phrase is serious and often used in humanitarian contexts.","zh":"這個短語語氣嚴肅，常用於人道語境。"}],"source":"75 - One Who Hopes.pdf","sourcePage":18},{"front":"reading passage","meaning":"閱讀篇章","examples":[{"en":"Reading Passage 2 has seven paragraphs.","zh":"閱讀篇章2有七段。"},{"en":"A reading passage is a text used for reading practice or examination questions.","zh":"reading passage 指用於閱讀練習或考試題目的文本。"},{"en":"Students should skim a reading passage before answering detailed questions.","zh":"學生答細節題前應先略讀閱讀篇章。"},{"en":"Understanding the passage structure helps students locate answers faster.","zh":"理解篇章結構幫助學生更快定位答案。"},{"en":"This phrase is common in IELTS-style tasks.","zh":"這個短語常見於 IELTS 類題目。"}],"source":"75 - One Who Hopes.pdf","sourcePage":18},{"front":"choose the correct heading","meaning":"選擇正確標題","examples":[{"en":"Students choose the correct heading for each paragraph.","zh":"學生為每段選擇正確標題。"},{"en":"To choose the correct heading means to select the title that best summarises a paragraph.","zh":"choose the correct heading 指選出最能概括段落的標題。"},{"en":"Students should read the whole paragraph before choosing its heading.","zh":"學生應先讀完整段，再選標題。"},{"en":"A heading may use different words but still match the main idea.","zh":"標題可能使用不同字眼，但仍符合主旨。"},{"en":"This phrase is common in paragraph-heading questions.","zh":"這個短語常見於段落標題題。"}],"source":"75 - One Who Hopes.pdf","sourcePage":18},{"front":"list of headings","meaning":"標題列表","examples":[{"en":"The question provides a list of headings.","zh":"題目提供一個標題列表。"},{"en":"A list of headings is a set of possible paragraph titles.","zh":"list of headings 指一組可能的段落標題。"},{"en":"Students compare each heading with the main idea of a paragraph.","zh":"學生把每個標題與段落主旨比較。"},{"en":"Some headings may be distractors that seem related but do not fit best.","zh":"有些標題可能是干擾項，看似相關但不是最合適。"},{"en":"This phrase is common in reading-test instructions.","zh":"這個短語常見於閱讀測驗指示。"}],"source":"75 - One Who Hopes.pdf","sourcePage":18},{"front":"write the correct number","meaning":"寫上正確編號","examples":[{"en":"Students write the correct number in the spaces provided.","zh":"學生在提供的空格中寫上正確編號。"},{"en":"To write the correct number means to record the number matching the chosen answer.","zh":"write the correct number 指寫下與所選答案相符的編號。"},{"en":"In a heading task, students may write iii instead of copying the whole heading.","zh":"在標題題中，學生可能寫 iii，而不是抄整個標題。"},{"en":"Correct format matters because exam answers are marked by number or letter.","zh":"正確格式很重要，因為考試答案按編號或字母評分。"},{"en":"This phrase reminds students to follow instructions exactly.","zh":"這個短語提醒學生嚴格跟從指示。"}],"source":"75 - One Who Hopes.pdf","sourcePage":18},{"front":"a non-exclusive language","meaning":"非排他性語言","examples":[{"en":"Esperanto is presented as a non-exclusive language.","zh":"世界語被呈現為一種非排他性語言。"},{"en":"A non-exclusive language is a language that does not belong only to one group or nation.","zh":"non-exclusive language 指不只屬於某一群體或國家的語言。"},{"en":"A shared classroom language can be non-exclusive if every student can learn it.","zh":"如果每位學生都能學，一種共同課室語言可以是非排他性的。"},{"en":"Non-exclusive communication helps reduce unfair advantages.","zh":"非排他性溝通有助減少不公平優勢。"},{"en":"This phrase connects language with access and equality.","zh":"這個短語把語言與可及性和平等連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":18},{"front":"fewer languages, more results","meaning":"語言較少，成果更多","examples":[{"en":"The heading fewer languages, more results suggests efficiency in communication.","zh":"標題 fewer languages, more results 暗示溝通效率。"},{"en":"Fewer languages, more results means using fewer language barriers to achieve more practical outcomes.","zh":"fewer languages, more results 指以較少語言障礙取得更多實際成果。"},{"en":"A meeting using one shared language may finish faster than one using ten translations.","zh":"使用一種共同語言的會議可能比使用十種翻譯的會議更快完成。"},{"en":"Reducing language complexity can save time, money, and effort.","zh":"減少語言複雜性可以節省時間、金錢和精力。"},{"en":"This phrase summarises an argument about efficiency.","zh":"這個短語概括關於效率的論點。"}],"source":"75 - One Who Hopes.pdf","sourcePage":18},{"front":"language is personal","meaning":"語言是個人的","examples":[{"en":"The heading language is personal suggests that language is connected with identity and feeling.","zh":"標題 language is personal 暗示語言與身份和感情有關。"},{"en":"Language is personal means language is tied to memory, emotion, family, and self-expression.","zh":"language is personal 指語言與記憶、情感、家庭和自我表達相連。"},{"en":"A person may feel proud when speaking their grandmother’s language.","zh":"一個人說祖母的語言時，可能感到自豪。"},{"en":"Because language is personal, criticism of a language can feel like criticism of its speakers.","zh":"因為語言是個人的，批評一種語言可能感覺像批評其使用者。"},{"en":"This phrase explains why language debates can become emotional.","zh":"這個短語解釋為何語言爭論可以變得情緒化。"}],"source":"75 - One Who Hopes.pdf","sourcePage":18},{"front":"what’s fashionable in language","meaning":"語言潮流","examples":[{"en":"The heading asks what is fashionable in language.","zh":"這個標題詢問語言中甚麼是流行的。"},{"en":"What’s fashionable in language refers to which languages or language habits are popular at a particular time.","zh":"what’s fashionable in language 指某一時期哪些語言或語言習慣流行。"},{"en":"Young people may follow fashionable slang because it feels modern and social.","zh":"年輕人可能使用流行俚語，因為它感覺現代又社交化。"},{"en":"Language fashions change when media, work, and culture change.","zh":"當媒體、工作和文化改變，語言潮流也會改變。"},{"en":"This phrase connects language use with trends.","zh":"這個短語把語言使用與潮流連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":18},{"front":"from the written word to the spoken word","meaning":"從書面語到口語","examples":[{"en":"Esperanto developed from the written word to the spoken word.","zh":"世界語從書面語發展到口語。"},{"en":"From the written word to the spoken word means moving from written form into actual speech.","zh":"from the written word to the spoken word 指從書寫形式轉向實際口頭使用。"},{"en":"A poem may begin on paper and later become powerful when read aloud.","zh":"一首詩可能先在紙上出現，後來朗讀時變得有力量。"},{"en":"A language feels more alive when people speak it, not just write it.","zh":"當人們說一種語言，而不只是書寫它，它會感覺更有生命力。"},{"en":"This phrase contrasts written creation with spoken use.","zh":"這個短語把書面創造與口頭使用作對比。"}],"source":"75 - One Who Hopes.pdf","sourcePage":18},{"front":"a real language","meaning":"真正的語言","examples":[{"en":"Supporters argue that Esperanto is a real language.","zh":"支持者主張世界語是真正的語言。"},{"en":"A real language is a language people can use to communicate genuine ideas and feelings.","zh":"real language 指人們能用來溝通真實想法和感受的語言。"},{"en":"A language used in letters, meetings, poems, and daily conversation can feel real to its speakers.","zh":"用於書信、會議、詩歌和日常對話的語言，對其使用者來說可以是真實的。"},{"en":"Regular use by a community can make a language more than a classroom exercise.","zh":"社群定期使用可以令一種語言不只是課堂練習。"},{"en":"This phrase is important in debates about constructed languages.","zh":"這個短語在人工語言辯論中很重要。"}],"source":"75 - One Who Hopes.pdf","sourcePage":19},{"front":"harmony through language","meaning":"透過語言達至和諧","examples":[{"en":"Esperanto was created to promote harmony through language.","zh":"世界語被創造出來，是為了透過語言促進和諧。"},{"en":"Harmony through language means peace and cooperation made possible by better communication.","zh":"harmony through language 指透過更好溝通帶來和平與合作。"},{"en":"A shared language in a classroom can create harmony by reducing misunderstanding.","zh":"課室中的共同語言可以透過減少誤解創造和諧。"},{"en":"If people can talk more fairly, they may trust one another more.","zh":"如果人們可以更公平地交談，他們可能更信任彼此。"},{"en":"This phrase links language with social peace.","zh":"這個短語把語言與社會和平連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":19},{"front":"the mechanics of a language","meaning":"語言的運作機制","examples":[{"en":"The passage explains the mechanics of a language.","zh":"文章解釋一種語言的運作機制。"},{"en":"The mechanics of a language are the working parts of its grammar, sounds, word formation, and structure.","zh":"mechanics of a language 指語法、聲音、構詞和結構等運作部分。"},{"en":"Students learn the mechanics of English when they study tense and sentence order.","zh":"學生學習時態和句子次序時，就是在學英語的運作機制。"},{"en":"Understanding mechanics helps learners use a language rather than only memorise phrases.","zh":"理解機制幫助學習者使用語言，而不只是背短語。"},{"en":"This phrase treats language like a system that has parts and rules.","zh":"這個短語把語言視為有部分和規則的系統。"}],"source":"75 - One Who Hopes.pdf","sourcePage":19},{"front":"lost in translation","meaning":"翻譯中的障礙；譯中迷失","examples":[{"en":"The heading lost in translation refers to problems and costs caused by translation.","zh":"標題 lost in translation 指翻譯造成的問題和成本。"},{"en":"Lost in translation means meaning, money, time, or feeling is lost when moving between languages.","zh":"lost in translation 指在語言轉換中失去意思、金錢、時間或感覺。"},{"en":"A joke may be lost in translation if the second language lacks the same cultural reference.","zh":"如果第二種語言缺乏相同文化參照，笑話可能在翻譯中失去效果。"},{"en":"Translation problems can slow meetings and increase costs.","zh":"翻譯問題可以拖慢會議並增加成本。"},{"en":"This phrase is often used when language transfer is imperfect.","zh":"這個短語常用於語言轉換不完美的情況。"}],"source":"75 - One Who Hopes.pdf","sourcePage":19},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter from the options.","zh":"學生從選項中選出正確字母。"},{"en":"To choose the correct letter means to select the option letter that matches the answer.","zh":"choose the correct letter 指選出與答案相符的選項字母。"},{"en":"In a reading test, students may choose A, B, C, or D after checking the text.","zh":"在閱讀測驗中，學生查閱文本後可能選 A、B、C 或 D。"},{"en":"A student can understand the idea but lose marks by writing the wrong letter.","zh":"學生可能理解意思，但因寫錯字母而失分。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"75 - One Who Hopes.pdf","sourcePage":19},{"front":"what advantage is there to","meaning":"……有甚麼好處","examples":[{"en":"The question asks what advantage there is to learning Esperanto first.","zh":"題目問先學世界語有甚麼好處。"},{"en":"What advantage is there to means what benefit comes from doing something.","zh":"what advantage is there to 指做某事有甚麼好處。"},{"en":"What advantage is there to planning an essay before writing it?","zh":"寫文章前先規劃有甚麼好處？"},{"en":"Asking this question helps students focus on practical benefit.","zh":"問這個問題幫助學生聚焦實際好處。"},{"en":"This phrase is common in comprehension and discussion questions.","zh":"這個短語常見於理解題和討論題。"}],"source":"75 - One Who Hopes.pdf","sourcePage":19},{"front":"one’s first foreign language","meaning":"某人的第一門外語","examples":[{"en":"Esperanto may be useful as one’s first foreign language.","zh":"世界語作為某人的第一門外語可能很有用。"},{"en":"One’s first foreign language is the first non-native language a person tries to learn.","zh":"one’s first foreign language 指一個人嘗試學習的第一種非母語。"},{"en":"A positive first foreign-language experience can build confidence for later study.","zh":"正面的第一門外語學習經驗可以建立之後學習的信心。"},{"en":"If the first foreign language is too hard, students may believe they are bad at languages.","zh":"如果第一門外語太難，學生可能以為自己不擅長語言。"},{"en":"This phrase highlights the emotional importance of a first learning experience.","zh":"這個短語突出第一次學習經驗的情感重要性。"}],"source":"75 - One Who Hopes.pdf","sourcePage":19},{"front":"pronunciation rules","meaning":"發音規則","examples":[{"en":"Esperanto has simple pronunciation rules.","zh":"世界語有簡單發音規則。"},{"en":"Pronunciation rules are guidelines that tell learners how letters and words should sound.","zh":"pronunciation rules 指告訴學習者字母和詞語應如何發音的指引。"},{"en":"Simple pronunciation rules help students read new words aloud correctly.","zh":"簡單發音規則幫助學生正確讀出新詞。"},{"en":"If pronunciation rules are irregular, learners may need to memorise many exceptions.","zh":"如果發音規則不規則，學習者可能需要記住許多例外。"},{"en":"This phrase is important for speaking and reading aloud.","zh":"這個短語對說話和朗讀很重要。"}],"source":"75 - One Who Hopes.pdf","sourcePage":19},{"front":"follow those of","meaning":"跟隨……的規則","examples":[{"en":"The option asks whether Esperanto pronunciation rules follow those of European languages.","zh":"這個選項問世界語發音規則是否跟隨歐洲語言的規則。"},{"en":"Follow those of means use the same rules or pattern as another thing.","zh":"follow those of 指使用與另一事物相同的規則或模式。"},{"en":"A school’s safety rules may follow those of the education department.","zh":"學校安全規則可能跟隨教育局的規則。"},{"en":"If one system follows another, learners may find familiar patterns.","zh":"如果一個系統跟隨另一個，學習者可能找到熟悉模式。"},{"en":"This phrase compares one set of rules with another set.","zh":"這個短語比較一套規則與另一套規則。"}],"source":"75 - One Who Hopes.pdf","sourcePage":19},{"front":"grammar rules","meaning":"語法規則","examples":[{"en":"The question mentions grammar rules in Esperanto.","zh":"題目提到世界語的語法規則。"},{"en":"Grammar rules are instructions for how words change and combine in sentences.","zh":"grammar rules 指詞語如何變化和組成句子的規則。"},{"en":"Students learn grammar rules such as subject-verb agreement and tense use.","zh":"學生學習主謂一致和時態使用等語法規則。"},{"en":"Clear rules help learners make fewer mistakes.","zh":"清楚規則幫助學習者犯較少錯誤。"},{"en":"This phrase is basic in language study.","zh":"這個短語是語言學習中的基本用語。"}],"source":"75 - One Who Hopes.pdf","sourcePage":19},{"front":"verbs are not conjugated","meaning":"動詞不作變位","examples":[{"en":"The option claims that Esperanto verbs are not conjugated.","zh":"這個選項聲稱世界語動詞不作變位。"},{"en":"Verbs are not conjugated means verbs do not change form for tense, person, or number.","zh":"verbs are not conjugated 指動詞不因時態、人稱或數而改變形式。"},{"en":"In some languages, verbs stay almost the same no matter who performs the action.","zh":"在有些語言中，不論誰做動作，動詞幾乎保持相同。"},{"en":"If verbs are not conjugated, grammar can feel simpler to learners.","zh":"如果動詞不作變位，語法對學習者來說可能較簡單。"},{"en":"This phrase describes a possible grammar feature.","zh":"這個短語描述一種可能的語法特徵。"}],"source":"75 - One Who Hopes.pdf","sourcePage":19},{"front":"critics say of","meaning":"批評者對……的看法","examples":[{"en":"The question asks what critics say of Esperanto.","zh":"題目問批評者對世界語有何看法。"},{"en":"What critics say of something means what negative or doubtful opinions critics express about it.","zh":"what critics say of something 指批評者對某事表達的負面或懷疑意見。"},{"en":"A film review may ask what critics say of a new director’s style.","zh":"電影評論可能問批評者對新導演風格有何看法。"},{"en":"Understanding critics’ views helps readers see both sides of an issue.","zh":"理解批評者觀點幫助讀者看見議題的兩面。"},{"en":"This phrase is common in comprehension questions.","zh":"這個短語常見於理解題。"}],"source":"75 - One Who Hopes.pdf","sourcePage":20},{"front":"artificial situations","meaning":"人為情境","examples":[{"en":"Critics may claim that Esperanto is only used in artificial situations.","zh":"批評者可能聲稱世界語只用於人為情境。"},{"en":"Artificial situations are settings that feel planned, unnatural, or not part of ordinary life.","zh":"artificial situations 指感覺被安排、不自然或不屬於日常生活的場合。"},{"en":"A classroom role-play may feel like an artificial situation compared with real conversation.","zh":"與真實對話相比，課室角色扮演可能感覺像人為情境。"},{"en":"If a language is used only artificially, critics may doubt whether it is truly alive.","zh":"如果語言只在人為情境中使用，批評者可能懷疑它是否真正有生命力。"},{"en":"This phrase is often used in criticism of unrealistic contexts.","zh":"這個短語常用於批評不真實的語境。"}],"source":"75 - One Who Hopes.pdf","sourcePage":20},{"front":"require emotional involvement","meaning":"需要情感投入","examples":[{"en":"The option says that Esperanto requires emotional involvement.","zh":"這個選項說世界語需要情感投入。"},{"en":"To require emotional involvement means to need personal feeling or emotional connection.","zh":"require emotional involvement 指需要個人感受或情感連繫。"},{"en":"Acting in a serious drama may require emotional involvement from performers.","zh":"演出嚴肅戲劇可能需要演員情感投入。"},{"en":"If a language lacks emotional involvement, speakers may not feel attached to it.","zh":"如果語言缺乏情感投入，使用者可能不會依戀它。"},{"en":"This phrase connects action with personal feeling.","zh":"這個短語把行動與個人感受連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":20},{"front":"lack depth of expression","meaning":"缺乏表達深度","examples":[{"en":"Critics say Esperanto lacks depth of expression.","zh":"批評者說世界語缺乏表達深度。"},{"en":"To lack depth of expression means to be unable to express complex or subtle feelings and ideas fully.","zh":"lack depth of expression 指不能充分表達複雜或細膩的感受和想法。"},{"en":"A short text message may lack depth of expression compared with a long letter.","zh":"與長信相比，短訊可能缺乏表達深度。"},{"en":"If expression lacks depth, communication may feel flat or limited.","zh":"如果表達缺乏深度，溝通可能感覺平淡或有限。"},{"en":"This phrase is a criticism of expressive richness.","zh":"這個短語是對表達豐富度的批評。"}],"source":"75 - One Who Hopes.pdf","sourcePage":20},{"front":"on a global level","meaning":"在全球層面上","examples":[{"en":"The question asks how Esperanto could help on a global level.","zh":"題目問世界語如何能在全球層面上提供幫助。"},{"en":"On a global level means in relation to the whole world.","zh":"on a global level 指就整個世界而言。"},{"en":"Climate change must be discussed on a global level because it crosses borders.","zh":"氣候變化必須在全球層面上討論，因為它跨越國界。"},{"en":"A global-level solution needs cooperation from many countries.","zh":"全球層面的解決方案需要許多國家合作。"},{"en":"This phrase expands a topic beyond local or national concerns.","zh":"這個短語把主題擴展到本地或國家關注以外。"}],"source":"75 - One Who Hopes.pdf","sourcePage":20},{"front":"eliminate the need for","meaning":"消除對……的需要","examples":[{"en":"The option asks whether Esperanto would eliminate the need for conferences.","zh":"這個選項問世界語是否會消除對會議的需要。"},{"en":"To eliminate the need for something means to remove the necessity for it.","zh":"eliminate the need for something 指消除某事的必要性。"},{"en":"Online forms can eliminate the need for paper applications.","zh":"網上表格可以消除對紙本申請的需要。"},{"en":"If a tool eliminates a need, people no longer have to spend resources on that thing.","zh":"如果工具消除某需要，人們就不必再在那件事上花資源。"},{"en":"This phrase describes complete removal of a requirement.","zh":"這個短語描述完全移除某項要求。"}],"source":"75 - One Who Hopes.pdf","sourcePage":20},{"front":"aid money","meaning":"援助資金","examples":[{"en":"More aid money could reach those who need it.","zh":"更多援助資金可以到達有需要的人手中。"},{"en":"Aid money is money used to help people, communities, or countries in need.","zh":"aid money 指用來幫助有需要人士、社群或國家的金錢。"},{"en":"After a disaster, aid money may pay for food, medicine, and temporary housing.","zh":"災後，援助資金可能支付食物、藥物和臨時住所。"},{"en":"If less money is spent on administration, more aid money can go directly to people.","zh":"如果較少金錢花在行政上，更多援助資金可以直接給予人民。"},{"en":"This phrase is common in humanitarian and development contexts.","zh":"這個短語常見於人道和發展語境。"}],"source":"75 - One Who Hopes.pdf","sourcePage":20},{"front":"reach those who need it","meaning":"到達有需要的人手中","examples":[{"en":"More aid money could reach those who need it.","zh":"更多援助資金可以到達有需要的人手中。"},{"en":"To reach those who need it means to arrive at the people who genuinely require help.","zh":"reach those who need it 指到達真正需要幫助的人。"},{"en":"School meal support should reach children who cannot afford lunch.","zh":"學校膳食支援應到達負擔不起午餐的孩子手中。"},{"en":"If funds are wasted before reaching people, the real problem remains.","zh":"如果資金在人們收到前被浪費，真正問題仍會存在。"},{"en":"This phrase focuses on effective delivery of support.","zh":"這個短語聚焦支援的有效送達。"}],"source":"75 - One Who Hopes.pdf","sourcePage":20},{"front":"world population","meaning":"世界人口","examples":[{"en":"The option mentions the world population speaking only one language.","zh":"這個選項提到世界人口只說一種語言。"},{"en":"World population means all people living in the world.","zh":"world population 指生活在世界上的所有人。"},{"en":"A tiny percentage of the world population can still mean millions of people.","zh":"世界人口中的很小百分比仍可以代表數百萬人。"},{"en":"Discussing the world population helps show whether an idea is realistic globally.","zh":"討論世界人口有助顯示一個想法在全球是否現實。"},{"en":"This phrase gives the broadest human scale.","zh":"這個短語提供最廣闊的人類尺度。"}],"source":"75 - One Who Hopes.pdf","sourcePage":20},{"front":"funds could be made available for","meaning":"資金可被撥作……用途","examples":[{"en":"More funds could be made available for useful purposes.","zh":"更多資金可被撥作有用用途。"},{"en":"Funds could be made available for something means money could be freed or provided for that use.","zh":"funds could be made available for something 指資金可以被騰出或提供作某用途。"},{"en":"If printing costs fall, funds could be made available for library books.","zh":"如果印刷成本下降，資金可被撥作購買圖書館書籍。"},{"en":"Freeing funds can allow organisations to support more urgent needs.","zh":"騰出資金可以讓機構支援更迫切需要。"},{"en":"This phrase is formal and common in budgeting.","zh":"這個短語較正式，常見於預算語境。"}],"source":"75 - One Who Hopes.pdf","sourcePage":20},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"Students decide whether the following statements agree with the passage.","zh":"學生判斷以下陳述是否與文章一致。"},{"en":"Do the following statements agree with asks whether each statement matches the source text.","zh":"do the following statements agree with 指詢問每個陳述是否與來源文本相符。"},{"en":"In reading exams, students must check evidence before deciding if a statement agrees.","zh":"在閱讀考試中，學生必須先檢查證據，再判斷陳述是否一致。"},{"en":"A statement may sound true but still not match the passage.","zh":"陳述可能聽起來正確，但仍未必符合文章。"},{"en":"This phrase is common in Yes, No, Not Given tasks.","zh":"這個短語常見於 Yes, No, Not Given 題。"}],"source":"75 - One Who Hopes.pdf","sourcePage":20},{"front":"information given in","meaning":"……中提供的資料","examples":[{"en":"The statements should agree with the information given in the passage.","zh":"陳述應與文章中提供的資料一致。"},{"en":"Information given in a passage means facts or ideas stated or supported by that text.","zh":"information given in a passage 指文章中陳述或支持的事實或想法。"},{"en":"Students should answer from the information given in the article, not from personal opinion.","zh":"學生應根據文章中提供的資料作答，而不是個人意見。"},{"en":"If the passage gives no information, the answer may be Not Given.","zh":"如果文章沒有提供資料，答案可能是 Not Given。"},{"en":"This phrase focuses on textual evidence.","zh":"這個短語聚焦文本證據。"}],"source":"75 - One Who Hopes.pdf","sourcePage":21},{"front":"agree with the views of the writer","meaning":"與作者觀點一致","examples":[{"en":"A YES answer means the statement agrees with the views of the writer.","zh":"YES 答案表示該陳述與作者觀點一致。"},{"en":"To agree with the views of the writer means to match the writer’s opinion, not just a fact.","zh":"agree with the views of the writer 指符合作者意見，而不只是符合事實。"},{"en":"Students must identify whether the statement reflects what the writer believes.","zh":"學生必須判斷陳述是否反映作者相信的內容。"},{"en":"Writer-view questions require attention to attitude and argument.","zh":"作者觀點題需要注意態度和論點。"},{"en":"This phrase is common in IELTS reading instructions.","zh":"這個短語常見於 IELTS 閱讀指示。"}],"source":"75 - One Who Hopes.pdf","sourcePage":21},{"front":"contradict the views of the writer","meaning":"與作者觀點相矛盾","examples":[{"en":"A NO answer means the statement contradicts the views of the writer.","zh":"NO 答案表示該陳述與作者觀點相矛盾。"},{"en":"To contradict the views of the writer means to say the opposite of the writer’s opinion.","zh":"contradict the views of the writer 指說出與作者意見相反的意思。"},{"en":"If a writer supports Esperanto and a statement attacks it, the statement may contradict the writer’s view.","zh":"如果作者支持世界語，而陳述攻擊它，該陳述可能與作者觀點相矛盾。"},{"en":"Contradiction is different from missing information because it directly conflicts with the text.","zh":"矛盾不同於沒有資料，因為它直接與文本衝突。"},{"en":"This phrase helps students identify NO answers.","zh":"這個短語幫助學生識別 NO 答案。"}],"source":"75 - One Who Hopes.pdf","sourcePage":21},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"NOT GIVEN means it is impossible to say what the writer thinks.","zh":"NOT GIVEN 表示無法判斷作者怎樣想。"},{"en":"Impossible to say means there is not enough information to decide.","zh":"impossible to say 指沒有足夠資料作判斷。"},{"en":"If a passage discusses language but not the writer’s childhood, it is impossible to say what happened then.","zh":"如果文章討論語言，但沒有談作者童年，就無法判斷當時發生甚麼。"},{"en":"Students should not guess when the text does not provide evidence.","zh":"當文本沒有提供證據，學生不應猜測。"},{"en":"This phrase is important for Not Given answers.","zh":"這個短語對 Not Given 答案很重要。"}],"source":"75 - One Who Hopes.pdf","sourcePage":21},{"front":"supporters of Esperanto","meaning":"世界語支持者","examples":[{"en":"Supporters of Esperanto say it gives everyone an equal voice.","zh":"世界語支持者說它給每個人平等的發言權。"},{"en":"Supporters of Esperanto are people who defend, use, or promote the language.","zh":"supporters of Esperanto 指捍衛、使用或推廣世界語的人。"},{"en":"Supporters may organise meetings, publish articles, and teach beginners.","zh":"支持者可能組織會議、發表文章並教授初學者。"},{"en":"Their support keeps the language active despite criticism.","zh":"他們的支持令這種語言即使面對批評仍保持活躍。"},{"en":"This phrase identifies the pro-Esperanto side of the debate.","zh":"這個短語指出辯論中支持世界語的一方。"}],"source":"75 - One Who Hopes.pdf","sourcePage":21},{"front":"an equal voice","meaning":"平等的發言權","examples":[{"en":"Esperanto may give everyone an equal voice.","zh":"世界語可能給每個人平等的發言權。"},{"en":"An equal voice means the same chance to speak, participate, and be understood.","zh":"equal voice 指相同的發言、參與和被理解機會。"},{"en":"In a fair classroom, every student should have an equal voice.","zh":"在公平課室中，每位學生都應有平等發言權。"},{"en":"If one language dominates, some people may lose their equal voice.","zh":"如果一種語言佔主導，有些人可能失去平等發言權。"},{"en":"This phrase connects communication with fairness and participation.","zh":"這個短語把溝通與公平和參與連接起來。"}],"source":"75 - One Who Hopes.pdf","sourcePage":21},{"front":"artificially constructed language","meaning":"人工創造的語言","examples":[{"en":"Esperanto is an artificially constructed language.","zh":"世界語是一種人工創造的語言。"},{"en":"An artificially constructed language is deliberately designed rather than naturally developed by a community over centuries.","zh":"artificially constructed language 指由人刻意設計，而不是由社群經數百年自然發展的語言。"},{"en":"A film writer may invent an artificially constructed language for a fictional world.","zh":"電影編劇可能為虛構世界創造人工語言。"},{"en":"Constructed languages can be regular because their rules are planned.","zh":"人工語言可以很規則，因為其規則是被規劃的。"},{"en":"This phrase describes Esperanto’s origin and design.","zh":"這個短語描述世界語的起源和設計。"}],"source":"75 - One Who Hopes.pdf","sourcePage":21},{"front":"self-study course","meaning":"自學課程","examples":[{"en":"The question mentions learning Esperanto through a self-study course.","zh":"題目提到透過自學課程學習世界語。"},{"en":"A self-study course is a course people complete on their own without regular classroom teaching.","zh":"self-study course 指人們自行完成、沒有定期課堂教學的課程。"},{"en":"A student may use a self-study course with videos, exercises, and answer keys.","zh":"學生可能使用包含影片、練習和答案的自學課程。"},{"en":"Self-study requires discipline because no teacher is checking progress every lesson.","zh":"自學需要紀律，因為沒有老師每堂檢查進度。"},{"en":"This phrase is common in language learning and online education.","zh":"這個短語常見於語言學習和網上教育。"}],"source":"75 - One Who Hopes.pdf","sourcePage":21},{"front":"formal and casual situations","meaning":"正式和輕鬆場合","examples":[{"en":"Esperanto may be used in formal and casual situations.","zh":"世界語可能用於正式和輕鬆場合。"},{"en":"Formal and casual situations are both serious official settings and relaxed everyday settings.","zh":"formal and casual situations 指嚴肅官方場合和輕鬆日常場合。"},{"en":"A language used in conferences and friendly chats works in both formal and casual situations.","zh":"一種能用於會議和朋友閒談的語言，可用於正式和輕鬆場合。"},{"en":"If a language fits many situations, people may see it as practical and alive.","zh":"如果語言適合多種場合，人們可能視它為實用且有生命力。"},{"en":"This phrase contrasts official use with ordinary social use.","zh":"這個短語把官方使用與普通社交使用作對比。"}],"source":"75 - One Who Hopes.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 76":[{"front":"conditions of participation","meaning":"參加條件","examples":[{"en":"The document explains the conditions of participation for the Special Olympics.","zh":"文件解釋特殊奧運會的參加條件。"},{"en":"Conditions of participation are the rules or requirements someone must meet before joining an activity.","zh":"conditions of participation 指某人參加活動前必須符合的規則或要求。"},{"en":"A school sports day may have conditions of participation, such as wearing suitable shoes.","zh":"學校運動日可能有參加條件，例如穿着合適運動鞋。"},{"en":"If participants do not meet the conditions of participation, organisers may not allow them to join.","zh":"如果參加者不符合參加條件，主辦方可能不允許他們加入。"},{"en":"The phrase is often used in official rules, competitions, and programmes.","zh":"這個片語常用於官方規則、比賽和計劃。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":1},{"front":"be eligible for participation in","meaning":"符合參加……的資格","examples":[{"en":"An athlete must meet certain requirements to be eligible for participation in the Special Olympics.","zh":"運動員必須符合某些要求，才符合參加特殊奧運會的資格。"},{"en":"Be eligible for participation in means have the right qualifications to join a programme or activity.","zh":"be eligible for participation in 指具備加入某計劃或活動的合適資格。"},{"en":"A student may be eligible for participation in a scholarship scheme if their family income is low enough.","zh":"如果學生家庭收入足夠低，可能符合參加獎學金計劃的資格。"},{"en":"If a person does not meet the age or medical requirements, they may not be eligible for participation.","zh":"如果一個人不符合年齡或醫療要求，可能不符合參加資格。"},{"en":"The phrase focuses on whether someone qualifies to take part.","zh":"這個片語集中於某人是否有資格參與。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":1},{"front":"an individual with an intellectual disability","meaning":"有智力障礙的人士","examples":[{"en":"An individual with an intellectual disability may participate in Special Olympics programmes.","zh":"有智力障礙的人士可以參加特殊奧運會計劃。"},{"en":"An individual with an intellectual disability is a person who has limitations in intellectual functioning and adaptive skills.","zh":"an individual with an intellectual disability 指在智力功能和適應技能上有限制的人士。"},{"en":"A school may provide extra support for an individual with an intellectual disability during lessons.","zh":"學校可能在課堂中為有智力障礙的人士提供額外支援。"},{"en":"If activities are well adapted, an individual with an intellectual disability can participate more confidently.","zh":"如果活動經過適當調整，有智力障礙的人士可以更有信心參與。"},{"en":"The phrase is a respectful person-first way to describe the individual.","zh":"這個片語是以人為本、較尊重的描述方式。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":1},{"front":"agree to","meaning":"同意","examples":[{"en":"Participants must agree to follow the SOC Sports Rules.","zh":"參加者必須同意遵守 SOC 體育規則。"},{"en":"Agree to means accept a rule, request, plan, or responsibility.","zh":"agree to 指接受某項規則、要求、計劃或責任。"},{"en":"Students must agree to the library rules before borrowing books.","zh":"學生借書前必須同意圖書館規則。"},{"en":"If someone agrees to a rule, they are expected to follow it afterwards.","zh":"如果某人同意某條規則，之後就被期望遵守。"},{"en":"The phrase shows consent or acceptance.","zh":"這個片語表示同意或接受。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":1},{"front":"observe and abide by","meaning":"遵守並服從","examples":[{"en":"Athletes must observe and abide by the SOC Sports Rules.","zh":"運動員必須遵守並服從 SOC 體育規則。"},{"en":"Observe and abide by means notice, respect, and follow rules properly.","zh":"observe and abide by 指留意、尊重並正確遵守規則。"},{"en":"Drivers must observe and abide by traffic lights and speed limits.","zh":"司機必須遵守交通燈和速度限制。"},{"en":"If players do not observe and abide by competition rules, a match may become unfair.","zh":"如果參賽者不遵守比賽規則，比賽可能變得不公平。"},{"en":"The phrase is formal and often used in official instructions.","zh":"這個片語較正式，常用於官方指示。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":1},{"front":"SOC Sports Rules","meaning":"SOC體育規則","examples":[{"en":"Participants are expected to follow the SOC Sports Rules.","zh":"參加者被期望遵守 SOC 體育規則。"},{"en":"SOC Sports Rules are the official sports rules set by the relevant Special Olympics organisation.","zh":"SOC Sports Rules 指相關特殊奧運組織制定的官方體育規則。"},{"en":"A coach may review the SOC Sports Rules before entering athletes in a competition.","zh":"教練可能在安排運動員參賽前重溫 SOC 體育規則。"},{"en":"If athletes follow the SOC Sports Rules, events can be safer and fairer.","zh":"如果運動員遵守 SOC 體育規則，賽事可以更安全和公平。"},{"en":"The phrase refers to a specific set of official rules.","zh":"這個片語指一套特定官方規則。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":1},{"front":"mental retardation","meaning":"智力障礙的舊稱；已較少使用的臨床用語","examples":[{"en":"The document explains that the term mental retardation is no longer commonly used.","zh":"文件解釋 mental retardation 這個用語已不再常用。"},{"en":"Mental retardation is an older clinical term that has largely been replaced by intellectual disability.","zh":"mental retardation 是較舊的臨床用語，現已大多由 intellectual disability 取代。"},{"en":"In modern educational writing, people usually avoid mental retardation and use more respectful language.","zh":"在現代教育寫作中，人們通常避免使用 mental retardation，並使用較尊重的語言。"},{"en":"If old documents use this term, readers should understand the historical wording without copying it casually.","zh":"如果舊文件使用這個用語，讀者應理解其歷史用法，而不是隨便照用。"},{"en":"The phrase should be handled carefully because current usage has changed.","zh":"這個片語應小心處理，因為現時用法已改變。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":1},{"front":"refer to","meaning":"指的是","examples":[{"en":"The old diagnostic term refers to substantial limitations in present functioning.","zh":"這個舊診斷用語指的是目前功能表現上的重大限制。"},{"en":"Refer to means point to, describe, or mean something specific.","zh":"refer to 指指向、描述或表示某個特定意思。"},{"en":"In a timetable, “Period 1” may refer to the first lesson of the day.","zh":"在時間表中，Period 1 可能指一天中的第一堂課。"},{"en":"If a word refers to a medical condition, its meaning should be explained accurately.","zh":"如果一個詞指的是某醫療情況，其意思應準確解釋。"},{"en":"The phrase helps connect a term with what it means.","zh":"這個片語幫助把用語與其意思連接起來。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":1},{"front":"substantial limitations","meaning":"重大限制","examples":[{"en":"The condition involves substantial limitations in present functioning.","zh":"這種情況涉及目前功能表現上的重大限制。"},{"en":"Substantial limitations are serious restrictions that affect what a person can do.","zh":"substantial limitations 指影響一個人能做甚麼的嚴重限制。"},{"en":"A student with substantial limitations in reading may need extra time and support.","zh":"閱讀方面有重大限制的學生可能需要額外時間和支援。"},{"en":"If limitations are substantial, they can affect school, work, communication, or daily life.","zh":"如果限制是重大的，它們可以影響學校、工作、溝通或日常生活。"},{"en":"The phrase means the difficulties are significant, not minor.","zh":"這個片語表示困難是顯著的，而不是輕微的。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":1},{"front":"present functioning","meaning":"目前功能表現","examples":[{"en":"The definition focuses on substantial limitations in present functioning.","zh":"這個定義集中於目前功能表現上的重大限制。"},{"en":"Present functioning means how a person is currently able to think, learn, communicate, and manage daily life.","zh":"present functioning 指一個人目前在思考、學習、溝通和處理日常生活方面的能力。"},{"en":"A doctor may assess a patient’s present functioning before recommending support.","zh":"醫生可能在建議支援前評估病人的目前功能表現。"},{"en":"If present functioning improves, a person may need less assistance in some areas.","zh":"如果目前功能表現改善，一個人在某些方面可能需要較少協助。"},{"en":"The phrase focuses on current ability, not only past history.","zh":"這個片語集中於現時能力，而不只是過往歷史。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":1},{"front":"be characterised by","meaning":"以……為特徵","examples":[{"en":"The condition is characterised by significantly sub-average intellectual functioning.","zh":"這種情況以明顯低於平均水平的智力功能為特徵。"},{"en":"Be characterised by means have a particular feature that helps define it.","zh":"be characterised by 指具有某個有助定義它的特徵。"},{"en":"A good classroom is characterised by respect, clear routines, and active learning.","zh":"良好課室以尊重、清晰常規和主動學習為特徵。"},{"en":"If a condition is characterised by several signs, assessment should consider all of them.","zh":"如果某情況以幾個徵象為特徵，評估應考慮全部徵象。"},{"en":"The phrase introduces a defining feature.","zh":"這個片語引出定義性特徵。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":2},{"front":"significantly sub-average","meaning":"明顯低於平均水平的","examples":[{"en":"The definition refers to significantly sub-average intellectual functioning.","zh":"這個定義提到明顯低於平均水平的智力功能。"},{"en":"Significantly sub-average means clearly and measurably below the usual level.","zh":"significantly sub-average 指清楚且可量度地低於一般水平。"},{"en":"A test score may be significantly sub-average if it is far below most students’ scores.","zh":"如果測驗分數遠低於大多數學生，可能是明顯低於平均水平。"},{"en":"If performance is significantly sub-average, extra assessment and support may be needed.","zh":"如果表現明顯低於平均水平，可能需要額外評估和支援。"},{"en":"The phrase describes a serious difference, not a small variation.","zh":"這個片語描述嚴重差異，而不是小變化。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":2},{"front":"intellectual functioning","meaning":"智力功能","examples":[{"en":"The assessment considers intellectual functioning and adaptive skills.","zh":"評估會考慮智力功能和適應技能。"},{"en":"Intellectual functioning means abilities related to learning, reasoning, problem-solving, and understanding information.","zh":"intellectual functioning 指與學習、推理、解難和理解資訊有關的能力。"},{"en":"A psychologist may assess intellectual functioning through tasks involving memory and reasoning.","zh":"心理學家可能透過涉及記憶和推理的任務評估智力功能。"},{"en":"If intellectual functioning is limited, a person may need clearer instructions or more time.","zh":"如果智力功能有限，一個人可能需要更清晰指示或更多時間。"},{"en":"The phrase describes thinking and learning ability.","zh":"這個片語描述思考和學習能力。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":2},{"front":"existing concurrently with","meaning":"與……同時存在","examples":[{"en":"The intellectual limitations exist concurrently with related adaptive limitations.","zh":"智力限制與相關適應限制同時存在。"},{"en":"Existing concurrently with means happening or being present at the same time as something else.","zh":"existing concurrently with 指與另一事物同時發生或存在。"},{"en":"A student’s reading difficulty may exist concurrently with anxiety about exams.","zh":"學生的閱讀困難可能與考試焦慮同時存在。"},{"en":"If two limitations exist concurrently, support should address both areas together.","zh":"如果兩種限制同時存在，支援應同時處理兩方面。"},{"en":"The phrase highlights simultaneous conditions.","zh":"這個片語強調同時存在的情況。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":2},{"front":"related limitations","meaning":"相關限制","examples":[{"en":"The definition includes related limitations in adaptive skill areas.","zh":"這個定義包括適應技能範疇中的相關限制。"},{"en":"Related limitations are connected difficulties that appear in areas linked to the main condition.","zh":"related limitations 指與主要情況相關的範疇中出現的連帶困難。"},{"en":"A child with communication difficulties may also have related limitations in social interaction.","zh":"有溝通困難的孩子也可能在社交互動方面有相關限制。"},{"en":"If related limitations are ignored, support may not meet the person’s real needs.","zh":"如果相關限制被忽視，支援可能無法滿足該人的真正需要。"},{"en":"The phrase shows that difficulties can appear together across different areas.","zh":"這個片語顯示困難可在不同範疇同時出現。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":2},{"front":"applicable adaptive skill areas","meaning":"適用的適應技能範疇","examples":[{"en":"The definition lists several applicable adaptive skill areas.","zh":"這個定義列出幾個適用的適應技能範疇。"},{"en":"Applicable adaptive skill areas are the daily-life skill areas relevant to assessing a person’s support needs.","zh":"applicable adaptive skill areas 指與評估一個人支援需要有關的日常生活技能範疇。"},{"en":"A support plan may consider applicable adaptive skill areas such as communication and self-care.","zh":"支援計劃可能考慮溝通和自我照顧等適用適應技能範疇。"},{"en":"If an assessment checks the right adaptive areas, support can be more accurate.","zh":"如果評估檢查正確的適應範疇，支援可以更準確。"},{"en":"The phrase refers to practical life-skill categories used in evaluation.","zh":"這個片語指評估中使用的實用生活技能分類。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":2},{"front":"adaptive skill areas","meaning":"適應技能範疇","examples":[{"en":"Communication and self-care are examples of adaptive skill areas.","zh":"溝通和自我照顧是適應技能範疇的例子。"},{"en":"Adaptive skill areas are practical abilities people use to manage daily life and social situations.","zh":"adaptive skill areas 指人們用來處理日常生活和社交情境的實用能力。"},{"en":"Cooking a simple meal, asking for help, and travelling safely can involve adaptive skills.","zh":"煮簡單一餐、尋求幫助和安全出行都可能涉及適應技能。"},{"en":"If someone has difficulty in several adaptive skill areas, they may need structured support.","zh":"如果某人在幾個適應技能範疇有困難，可能需要有結構的支援。"},{"en":"The phrase focuses on practical functioning, not only academic ability.","zh":"這個片語集中於實際功能，而不只是學術能力。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":2},{"front":"self-care","meaning":"自我照顧","examples":[{"en":"Self-care is one of the adaptive skill areas mentioned in the definition.","zh":"自我照顧是定義中提到的適應技能範疇之一。"},{"en":"Self-care means the ability to look after one’s own basic daily needs.","zh":"self-care 指照顧自己基本日常需要的能力。"},{"en":"Washing, dressing, eating, and taking medicine can all be parts of self-care.","zh":"洗澡、穿衣、進食和服藥都可以是自我照顧的一部分。"},{"en":"If a person struggles with self-care, caregivers may need to provide daily support.","zh":"如果一個人在自我照顧方面有困難，照顧者可能需要提供日常支援。"},{"en":"The phrase describes practical personal-care ability.","zh":"這個片語描述實用的個人照顧能力。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":2},{"front":"home living","meaning":"家居生活能力","examples":[{"en":"Home living is included as an adaptive skill area.","zh":"家居生活能力被列為一個適應技能範疇。"},{"en":"Home living means the ability to manage ordinary tasks and routines at home.","zh":"home living 指處理家中日常任務和常規的能力。"},{"en":"Cleaning a room, preparing simple food, and keeping belongings organised are home-living skills.","zh":"清潔房間、準備簡單食物和整理個人物品都是家居生活能力。"},{"en":"If home living is difficult, a person may need reminders, routines, or support workers.","zh":"如果家居生活有困難，一個人可能需要提醒、常規或支援人員。"},{"en":"The phrase focuses on practical independence in the home.","zh":"這個片語集中於家中的實際獨立能力。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":2},{"front":"social skills","meaning":"社交技巧","examples":[{"en":"Social skills are part of the adaptive skill areas listed in the document.","zh":"社交技巧是文件列出的適應技能範疇之一。"},{"en":"Social skills are abilities used to communicate, cooperate, and behave appropriately with others.","zh":"social skills 指用來與他人溝通、合作和合適相處的能力。"},{"en":"Taking turns, listening, greeting people, and asking politely are social skills.","zh":"輪流、聆聽、打招呼和禮貌提問都是社交技巧。"},{"en":"If social skills are weak, a person may misunderstand others or feel isolated.","zh":"如果社交技巧較弱，一個人可能誤解他人或感到孤立。"},{"en":"The phrase describes practical skills for interacting with people.","zh":"這個片語描述與人互動的實用技巧。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":2},{"front":"community use","meaning":"使用社區資源的能力","examples":[{"en":"Community use is one of the adaptive skill areas in the definition.","zh":"使用社區資源的能力是定義中的適應技能範疇之一。"},{"en":"Community use means the ability to use public places, services, and resources safely and appropriately.","zh":"community use 指安全而合適地使用公共地方、服務和資源的能力。"},{"en":"Taking a bus, visiting a library, and using a clinic are examples of community use.","zh":"乘巴士、到圖書館和使用診所服務都是使用社區資源的例子。"},{"en":"If a person needs help with community use, support may include travel training or guided practice.","zh":"如果一個人需要使用社區資源方面的幫助，支援可包括出行訓練或陪同練習。"},{"en":"The phrase connects daily independence with public services.","zh":"這個片語把日常獨立與公共服務連接起來。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":3},{"front":"self-direction","meaning":"自我指導能力","examples":[{"en":"Self-direction is an adaptive skill area related to independent decision-making.","zh":"自我指導能力是與獨立決策有關的適應技能範疇。"},{"en":"Self-direction means the ability to make choices, set goals, and guide one’s own behaviour.","zh":"self-direction 指作出選擇、設定目標並引導自己行為的能力。"},{"en":"A student shows self-direction when they plan revision without being reminded every day.","zh":"學生不用每天被提醒而自行計劃溫習，就是展現自我指導能力。"},{"en":"If self-direction is limited, a person may need help making safe daily decisions.","zh":"如果自我指導能力有限，一個人可能需要協助作出安全日常決定。"},{"en":"The phrase focuses on independence and personal choice.","zh":"這個片語集中於獨立和個人選擇。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":3},{"front":"health and safety","meaning":"健康與安全","examples":[{"en":"Health and safety is included among the adaptive skill areas.","zh":"健康與安全被列入適應技能範疇之中。"},{"en":"Health and safety means knowing how to protect one’s body, avoid danger, and seek help when needed.","zh":"health and safety 指知道如何保護身體、避免危險並在需要時求助。"},{"en":"Wearing a seat belt and telling an adult about pain are health-and-safety behaviours.","zh":"繫安全帶和告訴成人自己疼痛，都是健康與安全行為。"},{"en":"If someone has difficulty with health and safety, they may need clear routines and supervision.","zh":"如果某人在健康與安全方面有困難，可能需要清晰常規和監督。"},{"en":"The phrase covers both wellbeing and protection from harm.","zh":"這個片語涵蓋健康福祉和免受傷害。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":3},{"front":"functional academics","meaning":"實用學習能力","examples":[{"en":"Functional academics refers to practical learning skills used in daily life.","zh":"functional academics 指日常生活中使用的實用學習能力。"},{"en":"Functional academics means reading, writing, counting, and problem-solving skills used for real-life tasks.","zh":"functional academics 指用於現實任務的閱讀、寫作、計算和解難能力。"},{"en":"Reading a bus timetable or counting change in a shop involves functional academics.","zh":"閱讀巴士時間表或在商店點算找續，都涉及實用學習能力。"},{"en":"If functional academics improve, a person may manage daily tasks more independently.","zh":"如果實用學習能力改善，一個人可能更能獨立處理日常任務。"},{"en":"The phrase focuses on useful learning, not abstract school knowledge only.","zh":"這個片語集中於有用學習，而不只是抽象學校知識。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":3},{"front":"leisure and work","meaning":"閒暇與工作能力","examples":[{"en":"Leisure and work are included in the list of adaptive skill areas.","zh":"閒暇與工作能力被列入適應技能範疇清單。"},{"en":"Leisure and work means skills related to free-time activities and employment or job-like tasks.","zh":"leisure and work 指與閒暇活動、就業或類似工作的任務有關的技能。"},{"en":"Joining a sports club and arriving on time for a job both involve leisure and work skills.","zh":"參加運動會和準時上班，都涉及閒暇與工作能力。"},{"en":"If a person develops leisure and work skills, they may enjoy fuller community life.","zh":"如果一個人發展閒暇與工作能力，可能享有更完整的社區生活。"},{"en":"The phrase connects personal enjoyment with practical responsibility.","zh":"這個片語把個人享受與實際責任連接起來。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":3},{"front":"manifest itself before","meaning":"在……之前顯現出來","examples":[{"en":"The condition manifests itself before the age of 18.","zh":"這種情況在18歲之前顯現出來。"},{"en":"Manifest itself before means become visible or noticeable before a particular time.","zh":"manifest itself before 指在某個時間之前變得可見或可察覺。"},{"en":"Some learning difficulties manifest themselves before a child enters secondary school.","zh":"有些學習困難在孩子升讀中學前顯現出來。"},{"en":"If a condition manifests itself early, assessment and support can begin sooner.","zh":"如果情況早期顯現，評估和支援可以更早開始。"},{"en":"The phrase describes when signs first appear.","zh":"這個片語描述徵象首次出現的時間。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":3},{"front":"before the age of 18","meaning":"18歲之前","examples":[{"en":"The condition must manifest itself before the age of 18.","zh":"這種情況必須在18歲之前顯現出來。"},{"en":"Before the age of 18 means before a person reaches their eighteenth birthday.","zh":"before the age of 18 指在一個人到達18歲生日之前。"},{"en":"Some youth programmes are only open to people before the age of 18.","zh":"有些青年計劃只開放給18歲之前的人士。"},{"en":"If a condition is defined by onset before 18, adult-onset difficulties may be classified differently.","zh":"如果某情況以18歲前出現來界定，成年後才出現的困難可能會被不同分類。"},{"en":"The phrase sets a clear age boundary.","zh":"這個片語設定清晰年齡界線。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":3},{"front":"assumptions are essential to","meaning":"對……來說是必要假設","examples":[{"en":"Four assumptions are essential to the application of the definition.","zh":"四項假設對這個定義的應用來說是必要的。"},{"en":"Assumptions are essential to means certain basic ideas are necessary for using something correctly.","zh":"assumptions are essential to 指某些基本想法對正確使用某事物是必要的。"},{"en":"Clear assumptions are essential to a fair research survey.","zh":"清晰假設對公平研究調查是必要的。"},{"en":"If the assumptions are wrong, the final judgement may also be wrong.","zh":"如果假設錯誤，最終判斷也可能錯誤。"},{"en":"The phrase shows that a decision depends on underlying principles.","zh":"這個片語顯示決定取決於背後原則。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":3},{"front":"application of the definition","meaning":"定義的應用","examples":[{"en":"The assumptions guide the application of the definition.","zh":"這些假設指導定義的應用。"},{"en":"Application of the definition means the way a definition is used in real cases.","zh":"application of the definition 指定義在實際個案中的使用方式。"},{"en":"Teachers need clear examples to understand the application of a grading definition.","zh":"老師需要清晰例子來理解評分定義的應用。"},{"en":"If a definition is applied without context, it may be unfair or inaccurate.","zh":"如果定義在沒有背景下被應用，可能不公平或不準確。"},{"en":"The phrase connects wording with practical use.","zh":"這個片語把文字定義與實際使用連接起來。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":3},{"front":"valid assessment","meaning":"有效評估","examples":[{"en":"Valid assessment considers cultural and linguistic diversity.","zh":"有效評估會考慮文化及語言多樣性。"},{"en":"Valid assessment means evaluation that is fair, accurate, and suitable for the person being assessed.","zh":"valid assessment 指對受評估者公平、準確且合適的評估。"},{"en":"A valid assessment of language ability should not punish a student for an unfamiliar accent alone.","zh":"有效的語言能力評估不應只因學生口音陌生而懲罰他。"},{"en":"If assessment ignores culture or communication needs, the result may not be valid.","zh":"如果評估忽視文化或溝通需要，結果可能無效。"},{"en":"The phrase focuses on fairness and accuracy in evaluation.","zh":"這個片語集中於評估中的公平和準確。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":3},{"front":"cultural and linguistic diversity","meaning":"文化及語言多樣性","examples":[{"en":"Assessment should consider cultural and linguistic diversity.","zh":"評估應考慮文化及語言多樣性。"},{"en":"Cultural and linguistic diversity means differences in people’s cultures, languages, dialects, and communication backgrounds.","zh":"cultural and linguistic diversity 指人們在文化、語言、方言和溝通背景上的差異。"},{"en":"A classroom with students from many countries shows cultural and linguistic diversity.","zh":"一間有來自多個國家的學生的課室，展現文化及語言多樣性。"},{"en":"If diversity is ignored, a test may mistake language difference for lack of ability.","zh":"如果多樣性被忽視，測驗可能把語言差異誤認為能力不足。"},{"en":"The phrase reminds assessors to respect background differences.","zh":"這個片語提醒評估者尊重背景差異。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":4},{"front":"as well as","meaning":"以及","examples":[{"en":"Assessment considers cultural diversity as well as behavioural factors.","zh":"評估會考慮文化多樣性以及行為因素。"},{"en":"As well as means in addition to another thing.","zh":"as well as 指除了另一事物之外也包括。"},{"en":"A good lesson teaches vocabulary as well as grammar.","zh":"好課堂教授詞彙以及文法。"},{"en":"If a form asks for phone number as well as email, both types of contact are needed.","zh":"如果表格要求電話號碼以及電郵，兩種聯絡方式都需要。"},{"en":"The phrase adds another item without replacing the first.","zh":"這個片語加入另一項，而不是取代第一項。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":4},{"front":"communication and behavioural factors","meaning":"溝通及行為因素","examples":[{"en":"Valid assessment takes communication and behavioural factors into account.","zh":"有效評估會考慮溝通及行為因素。"},{"en":"Communication and behavioural factors are features of how a person expresses themselves and acts in different situations.","zh":"communication and behavioural factors 指一個人在不同情境中表達自己和行動方式的特徵。"},{"en":"A child may understand a task but show it differently because of communication or behavioural factors.","zh":"孩子可能明白任務，但因溝通或行為因素而以不同方式表現出來。"},{"en":"If these factors are ignored, assessment results may be misleading.","zh":"如果這些因素被忽視，評估結果可能具誤導性。"},{"en":"The phrase highlights non-academic influences on evaluation.","zh":"這個片語強調影響評估的非學術因素。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":4},{"front":"the existence of limitations","meaning":"限制的存在","examples":[{"en":"The existence of limitations must be understood within the person’s environment.","zh":"限制的存在必須在該人士的環境中理解。"},{"en":"The existence of limitations means the fact that certain difficulties are present.","zh":"the existence of limitations 指某些困難存在這一事實。"},{"en":"A student’s limitations in reading should be understood together with teaching support and language background.","zh":"學生閱讀方面的限制應連同教學支援和語言背景理解。"},{"en":"If limitations appear only in certain settings, the environment may be part of the explanation.","zh":"如果限制只在某些環境中出現，環境可能是解釋的一部分。"},{"en":"The phrase focuses on recognising difficulties without ignoring context.","zh":"這個片語集中於承認困難，同時不忽視背景。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":4},{"front":"occur within the context of","meaning":"發生於……的背景下","examples":[{"en":"Adaptive limitations occur within the context of community environments.","zh":"適應能力限制發生於社區環境的背景下。"},{"en":"Occur within the context of means happen inside a particular situation or background.","zh":"occur within the context of 指在某個特定情況或背景中發生。"},{"en":"A child’s behaviour should be understood within the context of home, school, and health.","zh":"孩子的行為應在家庭、學校和健康背景下理解。"},{"en":"If a difficulty occurs only in noisy places, the context matters.","zh":"如果困難只在嘈雜地方出現，背景就很重要。"},{"en":"The phrase reminds us that problems do not exist in isolation.","zh":"這個片語提醒我們，問題不是孤立存在的。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":4},{"front":"community environments","meaning":"社區環境","examples":[{"en":"The assessment considers community environments typical of the person’s age-peers.","zh":"評估會考慮該人士同齡人典型的社區環境。"},{"en":"Community environments are the ordinary places and settings where people live, learn, work, and socialise.","zh":"community environments 指人們生活、學習、工作和社交的普通地方和情境。"},{"en":"Schools, buses, parks, shops, and sports centres can be community environments.","zh":"學校、巴士、公園、商店和運動中心都可以是社區環境。"},{"en":"If support works only at home but not in community environments, more practice may be needed.","zh":"如果支援只在家中有效，但在社區環境中無效，就可能需要更多練習。"},{"en":"The phrase connects ability with real public life.","zh":"這個片語把能力與真實公共生活連接起來。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":4},{"front":"typical of","meaning":"具有……典型特徵的","examples":[{"en":"The relevant environments are typical of the individual’s age-peers.","zh":"相關環境具有該人士同齡人的典型特徵。"},{"en":"Typical of means having the usual features of a person, group, place, or situation.","zh":"typical of 指具有某人、群體、地方或情況的通常特徵。"},{"en":"It is typical of young children to ask many questions.","zh":"小孩子問很多問題是典型的。"},{"en":"If a task is typical of people the same age, it can be used for fair comparison.","zh":"如果一項任務對同齡人而言是典型的，它可用於公平比較。"},{"en":"The phrase describes what is normal or expected for a group.","zh":"這個片語描述某群體正常或預期的情況。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":4},{"front":"age-peers","meaning":"同齡人士","examples":[{"en":"The definition compares the person with age-peers in similar environments.","zh":"這個定義把該人士與類似環境中的同齡人士比較。"},{"en":"Age-peers are people of about the same age.","zh":"age-peers 指年齡大約相同的人。"},{"en":"A ten-year-old student is usually compared with age-peers, not adults, in school assessments.","zh":"在學校評估中，十歲學生通常與同齡人士比較，而不是與成人比較。"},{"en":"If someone’s skills differ greatly from age-peers, assessors may investigate why.","zh":"如果某人的技能與同齡人士差異很大，評估者可能調查原因。"},{"en":"The phrase helps make comparison fair by using the same age group.","zh":"這個片語透過使用相同年齡群體，使比較更公平。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":4},{"front":"be indexed to","meaning":"按照……衡量","examples":[{"en":"The limitations are indexed to the person’s individualised needs for support.","zh":"這些限制按照該人士的個人化支援需要衡量。"},{"en":"Be indexed to means be measured or linked according to a particular standard or need.","zh":"be indexed to 指按照某個特定標準或需要來量度或連結。"},{"en":"A rent subsidy may be indexed to family income, so poorer families receive more help.","zh":"租金津貼可能按照家庭收入衡量，所以較貧困家庭獲得更多幫助。"},{"en":"If support is indexed to individual needs, people receive help that fits them better.","zh":"如果支援按照個人需要衡量，人們會得到更合適的幫助。"},{"en":"The phrase describes adjustment according to a reference point.","zh":"這個片語描述按照參照點作調整。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":4},{"front":"individualised needs for support","meaning":"個人化支援需要","examples":[{"en":"The assessment considers the person’s individualised needs for support.","zh":"評估會考慮該人士的個人化支援需要。"},{"en":"Individualised needs for support are the specific kinds and levels of help one person requires.","zh":"individualised needs for support 指某個人所需的特定支援種類和程度。"},{"en":"One student may need visual instructions, while another needs extra time; these are individualised needs.","zh":"一名學生可能需要圖像指示，另一名需要額外時間；這些就是個人化需要。"},{"en":"If support matches individualised needs, progress is usually more realistic.","zh":"如果支援配合個人化需要，進展通常更實際。"},{"en":"The phrase reminds us that support should not be one-size-fits-all.","zh":"這個片語提醒我們，支援不應一刀切。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":4},{"front":"specific adaptive limitations","meaning":"特定適應能力限制","examples":[{"en":"Specific adaptive limitations may coexist with strengths.","zh":"特定適應能力限制可能與強項共存。"},{"en":"Specific adaptive limitations are particular difficulties in practical daily-life skills.","zh":"specific adaptive limitations 指實際日常生活技能中的特定困難。"},{"en":"A person may have specific adaptive limitations in travel but strong skills in art or memory.","zh":"一個人可能在出行方面有特定適應能力限制，但在藝術或記憶方面有強項。"},{"en":"If limitations are specific, support can target the exact area of need.","zh":"如果限制是特定的，支援就能針對確切需要。"},{"en":"The phrase avoids treating all abilities as equally limited.","zh":"這個片語避免把所有能力都視為同樣受限。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":5},{"front":"coexist with","meaning":"與……共存","examples":[{"en":"Limitations often coexist with strengths in other adaptive skills.","zh":"限制常與其他適應技能方面的強項共存。"},{"en":"Coexist with means exist at the same time as something else.","zh":"coexist with 指與另一事物同時存在。"},{"en":"A student’s difficulty with spelling may coexist with strong speaking skills.","zh":"學生的拼寫困難可能與強口語能力共存。"},{"en":"If limitations coexist with strengths, assessment should record both.","zh":"如果限制與強項共存，評估應同時記錄兩者。"},{"en":"The phrase helps show a balanced picture of a person.","zh":"這個片語有助呈現一個人的平衡圖像。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":5},{"front":"strengths in","meaning":"在……方面的強項","examples":[{"en":"A person may have strengths in other adaptive skills.","zh":"一個人可能在其他適應技能方面有強項。"},{"en":"Strengths in means abilities or positive qualities in a particular area.","zh":"strengths in 指某個範疇中的能力或正面特質。"},{"en":"A student may have strengths in drawing, teamwork, or remembering routines.","zh":"學生可能在繪畫、團隊合作或記住常規方面有強項。"},{"en":"If teachers recognise strengths in a learner, they can build support around them.","zh":"如果老師認識學習者的強項，就能圍繞強項建立支援。"},{"en":"The phrase focuses on what a person can do well.","zh":"這個片語集中於一個人能做得好的事情。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":5},{"front":"personal capabilities","meaning":"個人能力","examples":[{"en":"Adaptive limitations may coexist with other personal capabilities.","zh":"適應能力限制可能與其他個人能力共存。"},{"en":"Personal capabilities are a person’s abilities, skills, and useful strengths.","zh":"personal capabilities 指一個人的能力、技能和有用強項。"},{"en":"A person’s personal capabilities may include kindness, patience, musical talent, or practical memory.","zh":"一個人的個人能力可能包括善良、耐性、音樂才能或實用記憶。"},{"en":"If support recognises personal capabilities, it can become more respectful and effective.","zh":"如果支援認可個人能力，就可以更尊重和有效。"},{"en":"The phrase highlights ability rather than only difficulty.","zh":"這個片語強調能力，而不只是困難。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":5},{"front":"appropriate support","meaning":"適當支援","examples":[{"en":"With appropriate support, the person’s life functioning may improve.","zh":"有適當支援時，該人士的生活功能可能改善。"},{"en":"Appropriate support is help that fits a person’s needs, abilities, age, and environment.","zh":"appropriate support 指配合一個人的需要、能力、年齡和環境的幫助。"},{"en":"A student who struggles with reading may receive appropriate support through audio books and extra time.","zh":"閱讀有困難的學生可能透過有聲書和額外時間獲得適當支援。"},{"en":"If support is appropriate, it can increase confidence and independence.","zh":"如果支援適當，它可以增加信心和獨立能力。"},{"en":"The phrase means suitable help, not random or excessive help.","zh":"這個片語指合適幫助，而不是隨機或過量幫助。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":5},{"front":"over a sustained period","meaning":"在一段持續時間內","examples":[{"en":"Support should be provided over a sustained period.","zh":"支援應在一段持續時間內提供。"},{"en":"Over a sustained period means continuously or consistently for a long enough time.","zh":"over a sustained period 指在足夠長時間內持續或穩定地進行。"},{"en":"A student improves pronunciation over a sustained period of regular practice.","zh":"學生透過一段持續時間的定期練習改善發音。"},{"en":"If support stops too soon, progress may not become stable.","zh":"如果支援太早停止，進展可能不穩定。"},{"en":"The phrase stresses consistency, not one-time help.","zh":"這個片語強調持續性，而不是一次性幫助。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":5},{"front":"life functioning","meaning":"生活功能","examples":[{"en":"The person’s life functioning will generally improve with support.","zh":"在支援下，該人士的生活功能一般會改善。"},{"en":"Life functioning means how well a person manages daily living, social participation, and practical tasks.","zh":"life functioning 指一個人處理日常生活、社交參與和實際任務的能力。"},{"en":"Better transport training may improve a person’s life functioning by helping them travel independently.","zh":"更好的交通訓練可透過幫助一個人獨立出行來改善其生活功能。"},{"en":"If life functioning improves, a person may need less help in everyday routines.","zh":"如果生活功能改善，一個人在日常常規中可能需要較少幫助。"},{"en":"The phrase describes real-life ability, not only test performance.","zh":"這個片語描述真實生活能力，而不只是測驗表現。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":5},{"front":"generally improve","meaning":"一般會改善","examples":[{"en":"With suitable support, life functioning will generally improve.","zh":"有合適支援時，生活功能一般會改善。"},{"en":"Generally improve means usually become better, though not necessarily in every case or immediately.","zh":"generally improve 指通常變得更好，但不一定每個情況或立即發生。"},{"en":"Students generally improve when practice is regular and feedback is clear.","zh":"當練習定期且回饋清晰，學生一般會改善。"},{"en":"If support fits the person’s needs, progress is more likely over time.","zh":"如果支援配合個人需要，長遠來說更可能有進步。"},{"en":"The phrase expresses a likely trend, not an absolute promise.","zh":"這個片語表達可能趨勢，而不是絕對承諾。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":5},{"front":"diagnostic term","meaning":"診斷用語","examples":[{"en":"The old wording is described as a diagnostic term.","zh":"舊措辭被描述為診斷用語。"},{"en":"A diagnostic term is a medical or professional label used to identify a condition.","zh":"diagnostic term 是用來識別某情況的醫學或專業標籤。"},{"en":"A doctor may use a diagnostic term in a report but explain it in simpler language to a family.","zh":"醫生可能在報告中使用診斷用語，但向家庭用較簡單語言解釋。"},{"en":"If a diagnostic term becomes outdated, professionals may replace it with more respectful wording.","zh":"如果診斷用語變得過時，專業人士可能用較尊重措辭取代。"},{"en":"The phrase refers to formal classification language.","zh":"這個片語指正式分類語言。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":5},{"front":"be used to describe","meaning":"用作描述","examples":[{"en":"The term was used to describe the condition defined in the document.","zh":"該用語曾用作描述文件中界定的情況。"},{"en":"Be used to describe means be chosen as words for explaining or naming something.","zh":"be used to describe 指被選作解釋或命名某事物的文字。"},{"en":"“Quiet” may be used to describe a student who rarely speaks in class.","zh":"quiet 可用作描述很少在課堂說話的學生。"},{"en":"If a word is used to describe people, it should be accurate and respectful.","zh":"如果一個詞用作描述人，應該準確且尊重。"},{"en":"The phrase connects wording with description.","zh":"這個片語把措辭與描述連接起來。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":5},{"front":"the condition defined above","meaning":"上文所界定的情況","examples":[{"en":"The diagnostic term described the condition defined above.","zh":"該診斷用語描述上文所界定的情況。"},{"en":"The condition defined above means the condition explained earlier in the same document.","zh":"the condition defined above 指同一文件較早前解釋的情況。"},{"en":"In a form, “the condition defined above” points readers back to the previous definition.","zh":"在表格中，the condition defined above 會把讀者帶回前文定義。"},{"en":"If readers miss the earlier definition, this phrase may be unclear.","zh":"如果讀者錯過早前定義，這個片語可能不清楚。"},{"en":"The phrase avoids repeating a long definition.","zh":"這個片語避免重複冗長定義。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":6},{"front":"in keeping with","meaning":"與……一致","examples":[{"en":"In keeping with current usage, the preferred term is person with an intellectual disability.","zh":"與現時用法一致，較合適的用語是有智力障礙的人士。"},{"en":"In keeping with means matching or following a standard, practice, or expectation.","zh":"in keeping with 指符合或跟隨某個標準、做法或期望。"},{"en":"In keeping with school policy, students must wear uniforms on formal days.","zh":"與學校政策一致，學生在正式日子必須穿校服。"},{"en":"If language changes, official documents may be updated in keeping with current usage.","zh":"如果語言改變，官方文件可能會按照現時用法更新。"},{"en":"The phrase shows consistency with a rule or trend.","zh":"這個片語顯示與規則或趨勢一致。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":6},{"front":"current usage","meaning":"現時用法","examples":[{"en":"Current usage favours the term person with an intellectual disability.","zh":"現時用法較傾向使用有智力障礙的人士這個用語。"},{"en":"Current usage means the way words are commonly and acceptably used now.","zh":"current usage 指詞語現時常見且可接受的使用方式。"},{"en":"Dictionaries are updated when current usage changes over time.","zh":"當現時用法隨時間改變，字典會更新。"},{"en":"If current usage prefers respectful language, older labels should be avoided.","zh":"如果現時用法偏好尊重語言，就應避免舊標籤。"},{"en":"The phrase focuses on present language practice.","zh":"這個片語集中於當前語言實踐。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":6},{"front":"in the field","meaning":"在該領域內","examples":[{"en":"The term is no longer commonly used in the field.","zh":"該用語在該領域內已不再常用。"},{"en":"In the field means within a particular professional or academic area.","zh":"in the field 指在某個特定專業或學術範疇內。"},{"en":"In the field of education, teachers often discuss assessment and student support.","zh":"在教育領域內，老師常討論評估和學生支援。"},{"en":"If a term is no longer used in the field, professionals may see it as outdated.","zh":"如果某用語在該領域內不再使用，專業人士可能視它為過時。"},{"en":"The phrase identifies the expert area being discussed.","zh":"這個片語指出正在討論的專業範疇。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":6},{"front":"no longer commonly used","meaning":"不再常用","examples":[{"en":"The old diagnostic term is no longer commonly used.","zh":"這個舊診斷用語已不再常用。"},{"en":"No longer commonly used means people do not usually use the word or practice anymore.","zh":"no longer commonly used 指人們通常不再使用某詞或做法。"},{"en":"Some old computer terms are no longer commonly used because technology has changed.","zh":"有些舊電腦術語因科技改變而不再常用。"},{"en":"If a label is no longer commonly used, learners should avoid using it casually.","zh":"如果某標籤已不再常用，學習者應避免隨便使用。"},{"en":"The phrase shows that usage has changed over time.","zh":"這個片語顯示用法隨時間改變。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":6},{"front":"in its place","meaning":"取而代之","examples":[{"en":"In its place, the preferred term is person with an intellectual disability.","zh":"取而代之，較合適的用語是有智力障礙的人士。"},{"en":"In its place means instead of the earlier word, thing, or practice.","zh":"in its place 指代替較早的詞語、事物或做法。"},{"en":"The old form was removed; in its place, the school introduced an online system.","zh":"舊表格被取消；取而代之，學校引入網上系統。"},{"en":"If an outdated term is removed, a respectful term should be used in its place.","zh":"如果過時用語被移除，應以尊重用語取而代之。"},{"en":"The phrase introduces a replacement.","zh":"這個片語引出替代物。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":6},{"front":"absolutely necessary to","meaning":"絕對有必要去","examples":[{"en":"If it is absolutely necessary to use a label, the preferred term should be used.","zh":"如果絕對有必要使用標籤，應使用較合適的用語。"},{"en":"Absolutely necessary to means truly required, not just convenient or habitual.","zh":"absolutely necessary to 指真正必須，而不只是方便或習慣。"},{"en":"It is absolutely necessary to call emergency services if someone cannot breathe.","zh":"如果有人不能呼吸，就絕對有必要致電緊急服務。"},{"en":"If a label is not necessary, avoiding it may be more respectful.","zh":"如果標籤並非必要，避免使用可能更尊重。"},{"en":"The phrase stresses a very strong need.","zh":"這個片語強調非常強烈的需要。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":6},{"front":"use a label","meaning":"使用標籤；使用稱謂","examples":[{"en":"The document advises caution when it is necessary to use a label.","zh":"文件建議在有必要使用標籤時應謹慎。"},{"en":"Use a label means describe someone or something with a category name.","zh":"use a label 指用分類名稱描述某人或某事物。"},{"en":"Teachers should be careful when they use a label for a student’s learning needs.","zh":"老師為學生學習需要使用標籤時應小心。"},{"en":"If a label helps provide support, it should still be used respectfully.","zh":"如果標籤有助提供支援，仍應以尊重方式使用。"},{"en":"The phrase can involve risk because labels may oversimplify people.","zh":"這個片語可能有風險，因為標籤可能過度簡化人。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":6},{"front":"educational setting","meaning":"教育環境","examples":[{"en":"The term may appear in an educational setting.","zh":"該用語可能出現在教育環境中。"},{"en":"An educational setting is a place or situation connected with teaching, learning, or assessment.","zh":"educational setting 指與教學、學習或評估有關的地方或情境。"},{"en":"A classroom, training centre, or online course can be an educational setting.","zh":"課室、訓練中心或網上課程都可以是教育環境。"},{"en":"If a term appears in an educational setting, teachers should explain it carefully.","zh":"如果某用語出現在教育環境中，老師應仔細解釋。"},{"en":"The phrase refers to context, not only a physical school.","zh":"這個片語指情境，而不只是實體學校。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":6},{"front":"technical programme","meaning":"技術課程","examples":[{"en":"The preferred term may be used in a technical programme.","zh":"較合適的用語可用於技術課程中。"},{"en":"A technical programme is a specialised course, system, or official programme with professional language.","zh":"technical programme 指使用專業語言的專門課程、系統或官方計劃。"},{"en":"A nursing school may offer a technical programme on patient care.","zh":"護理學校可能提供病人護理的技術課程。"},{"en":"If a technical programme uses specialist terms, learners may need clear definitions.","zh":"如果技術課程使用專門術語，學習者可能需要清晰定義。"},{"en":"The phrase suggests a structured and specialised setting.","zh":"這個片語暗示有結構且專門的環境。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":6},{"front":"the preferred term","meaning":"較合適的用語","examples":[{"en":"The preferred term is person with an intellectual disability.","zh":"較合適的用語是有智力障礙的人士。"},{"en":"The preferred term is the word or phrase recommended as more accurate or respectful.","zh":"the preferred term 指被建議為更準確或更尊重的詞語或片語。"},{"en":"In a school policy, the preferred term may replace an older expression.","zh":"在學校政策中，較合適用語可能取代舊表達。"},{"en":"If language affects dignity, choosing the preferred term matters.","zh":"如果語言影響尊嚴，選擇較合適用語就很重要。"},{"en":"The phrase points to recommended wording.","zh":"這個片語指出建議用語。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":7},{"front":"a person with an intellectual disability","meaning":"有智力障礙的人士","examples":[{"en":"The preferred term is a person with an intellectual disability.","zh":"較合適的用語是有智力障礙的人士。"},{"en":"A person with an intellectual disability is someone who has intellectual and adaptive limitations and may need support.","zh":"a person with an intellectual disability 指有智力和適應能力限制、可能需要支援的人。"},{"en":"A coach should speak to a person with an intellectual disability with the same respect given to any athlete.","zh":"教練應以對待任何運動員同樣的尊重，與有智力障礙的人士說話。"},{"en":"If support is clear and consistent, a person with an intellectual disability can learn and participate more fully.","zh":"如果支援清晰且持續，有智力障礙的人士可以更充分地學習和參與。"},{"en":"The phrase puts the person before the disability.","zh":"這個片語把人放在障礙之前。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":7},{"front":"be created and developed to","meaning":"被創立及發展以","examples":[{"en":"Special Olympics was created and developed to provide sporting opportunities.","zh":"特殊奧運會被創立及發展，以提供體育機會。"},{"en":"Be created and developed to means be established and improved for a particular purpose.","zh":"be created and developed to 指為某特定目的而設立並逐步完善。"},{"en":"A school app may be created and developed to help parents receive notices quickly.","zh":"學校應用程式可能被創立及發展，以幫助家長快速接收通知。"},{"en":"If a programme is created for inclusion, its rules should support participation.","zh":"如果計劃為共融而創立，其規則應支持參與。"},{"en":"The phrase explains both origin and purpose.","zh":"這個片語同時解釋起源和目的。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":7},{"front":"give someone the opportunity to","meaning":"給予某人……的機會","examples":[{"en":"Special Olympics gives individuals the opportunity to train and compete.","zh":"特殊奧運會給予個人訓練及參賽的機會。"},{"en":"Give someone the opportunity to means allow someone a real chance to do something.","zh":"give someone the opportunity to 指讓某人有真正機會做某事。"},{"en":"A scholarship can give a student the opportunity to study abroad.","zh":"獎學金可以給予學生到海外升學的機會。"},{"en":"If people are given the opportunity to join, they can show abilities others may not expect.","zh":"如果人們獲得參與機會，他們可以展示別人未必預期的能力。"},{"en":"The phrase focuses on access and chance.","zh":"這個片語集中於可及性和機會。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":7},{"front":"train and compete","meaning":"訓練及參賽","examples":[{"en":"Participants have the opportunity to train and compete in sports.","zh":"參加者有機會在體育中訓練及參賽。"},{"en":"Train and compete means practise regularly and take part in contests or events.","zh":"train and compete 指定期練習並參加比賽或活動。"},{"en":"A runner may train after school and compete in races on weekends.","zh":"跑手可能放學後訓練，週末參賽。"},{"en":"If athletes train and compete, they can build skill, confidence, and teamwork.","zh":"如果運動員訓練及參賽，就能建立技能、信心和團隊合作。"},{"en":"The phrase connects preparation with actual performance.","zh":"這個片語把準備和實際表現連接起來。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":7},{"front":"sporting activities","meaning":"體育活動","examples":[{"en":"Special Olympics gives people opportunities to take part in sporting activities.","zh":"特殊奧運會給予人們參與體育活動的機會。"},{"en":"Sporting activities are physical games, exercises, or competitions involving sport.","zh":"sporting activities 指涉及運動的體能遊戲、練習或比賽。"},{"en":"Swimming, running, football, and gymnastics are sporting activities.","zh":"游泳、跑步、足球和體操都是體育活動。"},{"en":"If people join sporting activities, they may improve fitness and social confidence.","zh":"如果人們參加體育活動，可能改善體能和社交信心。"},{"en":"The phrase is broader than formal competitions only.","zh":"這個片語比正式比賽更廣泛。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":7},{"front":"no person shall","meaning":"任何人不得","examples":[{"en":"No person shall be excluded from participation on discriminatory grounds.","zh":"任何人不得基於歧視理由被排除於參與之外。"},{"en":"No person shall means no one is allowed to be treated in the stated way.","zh":"no person shall 指任何人都不允許被以所述方式對待。"},{"en":"A school rule may say no person shall enter the laboratory without safety glasses.","zh":"學校規則可能寫明任何人不得未戴安全眼鏡進入實驗室。"},{"en":"If a policy says no person shall be excluded unfairly, it protects access.","zh":"如果政策寫明任何人不得被不公平排除，它就保護參與權。"},{"en":"The phrase is formal legal-style wording.","zh":"這個片語是正式法律式措辭。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":7},{"front":"on the grounds of","meaning":"基於……理由","examples":[{"en":"No person shall be excluded on the grounds of gender, race or religion.","zh":"任何人不得基於性別、種族或宗教理由被排除。"},{"en":"On the grounds of means because of a particular reason or basis.","zh":"on the grounds of 指因某個特定理由或基礎。"},{"en":"A worker should not be treated unfairly on the grounds of age.","zh":"工人不應基於年齡理由受到不公平對待。"},{"en":"If someone is excluded on discriminatory grounds, the policy is unfair.","zh":"如果某人基於歧視理由被排除，政策就是不公平。"},{"en":"The phrase introduces the reason behind an action.","zh":"這個片語引出行動背後的理由。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":7},{"front":"national origin","meaning":"國籍來源；民族出身","examples":[{"en":"Participants must not be excluded because of national origin.","zh":"參加者不得因國籍來源而被排除。"},{"en":"National origin means the country, nation, or ethnic background a person comes from.","zh":"national origin 指一個人來自的國家、民族或族裔背景。"},{"en":"A job interview should not reject someone because of national origin.","zh":"工作面試不應因某人的國籍來源而拒絕他。"},{"en":"If rules protect people regardless of national origin, they support equal access.","zh":"如果規則不論國籍來源都保護人們，它們就支持平等參與。"},{"en":"The phrase is often used in anti-discrimination policies.","zh":"這個片語常用於反歧視政策。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":7},{"front":"financial constraint","meaning":"財政限制","examples":[{"en":"No one should be excluded because of financial constraint.","zh":"任何人都不應因財政限制而被排除。"},{"en":"Financial constraint means a lack of money that limits what a person can do.","zh":"financial constraint 指缺乏金錢，限制一個人能做的事。"},{"en":"A student may face financial constraints when buying textbooks or paying exam fees.","zh":"學生購買課本或支付考試費時可能面對財政限制。"},{"en":"If fees create financial constraints, some people may be unable to participate.","zh":"如果費用造成財政限制，有些人可能無法參與。"},{"en":"The phrase describes money pressure that restricts opportunity.","zh":"這個片語描述限制機會的金錢壓力。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":7},{"front":"be excluded from participation in","meaning":"被排除於……參與之外","examples":[{"en":"No person shall be excluded from participation in Special Olympics programmes.","zh":"任何人不得被排除於特殊奧運會計劃的參與之外。"},{"en":"Be excluded from participation in means be stopped from joining an activity or programme.","zh":"be excluded from participation in 指被阻止加入某活動或計劃。"},{"en":"A student should not be excluded from participation in a school trip because of a disability without considering support.","zh":"學生不應在未考慮支援下，因殘疾而被排除於學校旅行參與之外。"},{"en":"If someone is excluded unfairly, the organisation may need to change its rules.","zh":"如果某人被不公平排除，機構可能需要修改規則。"},{"en":"The phrase focuses on being denied the chance to take part.","zh":"這個片語集中於被拒絕參與機會。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":8},{"front":"be denied the benefits of","meaning":"被拒絕享有……的好處","examples":[{"en":"No person shall be denied the benefits of Special Olympics programmes.","zh":"任何人不得被拒絕享有特殊奧運會計劃的好處。"},{"en":"Be denied the benefits of means be refused access to the advantages or support something provides.","zh":"be denied the benefits of 指被拒絕取得某事物提供的好處或支援。"},{"en":"A child should not be denied the benefits of education because of family income.","zh":"孩子不應因家庭收入而被拒絕享有教育好處。"},{"en":"If people are denied benefits unfairly, the programme fails to serve them.","zh":"如果人們被不公平拒絕享有好處，該計劃就未能服務他們。"},{"en":"The phrase emphasises losing access to positive outcomes.","zh":"這個片語強調失去正面成果的可及性。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":8},{"front":"be subjected to discrimination","meaning":"受到歧視","examples":[{"en":"No athlete should be subjected to discrimination under any programme.","zh":"任何運動員都不應在任何計劃下受到歧視。"},{"en":"Be subjected to discrimination means be treated unfairly because of identity, background, or personal characteristics.","zh":"be subjected to discrimination 指因身份、背景或個人特徵而受到不公平對待。"},{"en":"A worker may be subjected to discrimination if they are passed over because of race or disability.","zh":"如果工人因種族或殘疾而被忽略晉升，就可能受到歧視。"},{"en":"If athletes face discrimination, their dignity and opportunity are harmed.","zh":"如果運動員面對歧視，其尊嚴和機會都會受損。"},{"en":"The phrase describes unfair treatment imposed on someone.","zh":"這個片語描述被加諸於某人的不公平對待。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":8},{"front":"under any programme or activity","meaning":"在任何計劃或活動下","examples":[{"en":"The rule applies under any programme or activity of Special Olympics.","zh":"該規則適用於特殊奧運會的任何計劃或活動下。"},{"en":"Under any programme or activity means within every official event, service, or organised situation.","zh":"under any programme or activity 指在每項官方活動、服務或有組織情境中。"},{"en":"A school safety rule may apply under any programme or activity held on campus.","zh":"學校安全規則可能適用於校園內任何計劃或活動下。"},{"en":"If a rule applies under any activity, organisers cannot ignore it in special cases.","zh":"如果規則適用於任何活動，主辦方就不能在特殊情況下忽視它。"},{"en":"The phrase broadens the rule to all relevant settings.","zh":"這個片語把規則擴展到所有相關情境。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":8},{"front":"flexibility is left to","meaning":"靈活處理由……負責","examples":[{"en":"Flexibility is left to local Special Olympics organisations.","zh":"靈活處理由本地特殊奧運組織負責。"},{"en":"Flexibility is left to means decision-making freedom is given to a particular group.","zh":"flexibility is left to 指決策上的彈性被交給某個特定群體。"},{"en":"In a school project, flexibility may be left to teachers to adjust deadlines for their classes.","zh":"在學校項目中，老師可能獲得靈活處理權，為自己班級調整期限。"},{"en":"If local conditions differ, flexibility is useful because one rule may not fit every place.","zh":"如果本地情況不同，靈活性很有用，因為一條規則未必適合所有地方。"},{"en":"The phrase shows who has room to adapt the rules.","zh":"這個片語顯示誰有空間調整規則。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":8},{"front":"local organisations","meaning":"本地組織","examples":[{"en":"Local organisations may help determine eligibility.","zh":"本地組織可以幫助決定參加資格。"},{"en":"Local organisations are groups that operate in a particular area or community.","zh":"local organisations 指在特定地區或社區運作的團體。"},{"en":"A local sports organisation may arrange training for young athletes in the neighbourhood.","zh":"本地體育組織可能為社區年輕運動員安排訓練。"},{"en":"If local organisations understand community needs, they can make better practical decisions.","zh":"如果本地組織了解社區需要，就能作出更好的實際決定。"},{"en":"The phrase refers to groups working close to the people affected.","zh":"這個片語指接近受影響人士工作的團體。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":8},{"front":"determine eligibility","meaning":"決定參加資格","examples":[{"en":"Special Olympics organisations help determine eligibility.","zh":"特殊奧運組織幫助決定參加資格。"},{"en":"Determine eligibility means decide whether someone meets the requirements to join or receive something.","zh":"determine eligibility 指決定某人是否符合參加或獲得某物的要求。"},{"en":"A school may check documents to determine eligibility for financial aid.","zh":"學校可能檢查文件來決定助學金資格。"},{"en":"If eligibility is unclear, organisers may need medical, educational, or personal information.","zh":"如果資格不清楚，主辦方可能需要醫療、教育或個人資料。"},{"en":"The phrase focuses on deciding qualification.","zh":"這個片語集中於決定資格。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":8},{"front":"variety of situations and needs","meaning":"各種情況和需要","examples":[{"en":"Flexibility is needed because of the variety of situations and needs.","zh":"由於各種情況和需要，所以需要靈活性。"},{"en":"Variety of situations and needs means many different circumstances and support requirements.","zh":"variety of situations and needs 指許多不同情況和支援要求。"},{"en":"A teacher plans differently because students have a variety of learning needs and family situations.","zh":"由於學生有各種學習需要和家庭情況，老師會以不同方式規劃。"},{"en":"If needs vary widely, a single fixed rule may not work well.","zh":"如果需要差異很大，單一固定規則可能效果不好。"},{"en":"The phrase explains why flexible decision-making is useful.","zh":"這個片語解釋為何靈活決策有用。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":8},{"front":"exist in many localities","meaning":"存在於許多地區","examples":[{"en":"Different needs exist in many localities.","zh":"不同需要存在於許多地區。"},{"en":"Exist in many localities means be present in many different places or communities.","zh":"exist in many localities 指存在於許多不同地方或社區。"},{"en":"Transport problems exist in many localities, but the causes may differ.","zh":"交通問題存在於許多地區，但原因可能不同。"},{"en":"If needs exist in many places, national guidance may still need local adjustment.","zh":"如果需要存在於許多地方，全國指引仍可能需要本地調整。"},{"en":"The phrase highlights geographical variety.","zh":"這個片語強調地理差異。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":8},{"front":"be instituted","meaning":"被設立；被推行","examples":[{"en":"Special Olympics programmes have been instituted in many localities.","zh":"特殊奧運會計劃已在許多地區被設立。"},{"en":"Be instituted means be formally established or put into operation.","zh":"be instituted 指被正式建立或投入運作。"},{"en":"A school may institute a new safety rule after an accident.","zh":"學校可能在意外後推行新的安全規則。"},{"en":"If a programme is instituted locally, people in that area can begin using it.","zh":"如果計劃在本地被設立，該區人士就可以開始使用。"},{"en":"The phrase is formal and often used for policies or programmes.","zh":"這個片語較正式，常用於政策或計劃。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":8},{"front":"inclusion is preferred to exclusion","meaning":"寧可納入而非排除","examples":[{"en":"Inclusion is preferred to exclusion when eligibility is uncertain.","zh":"當資格不確定時，寧可納入而非排除。"},{"en":"Inclusion is preferred to exclusion means it is better to allow participation than to keep someone out when unsure.","zh":"inclusion is preferred to exclusion 指在不確定時，讓人參與比把人排除更好。"},{"en":"A school club may choose inclusion over exclusion when a student needs only minor support.","zh":"當學生只需要輕微支援時，學校學會可能寧可納入而非排除。"},{"en":"If eligibility is unclear, including the person can prevent unfair rejection.","zh":"如果資格不清楚，納入該人士可以避免不公平拒絕。"},{"en":"The phrase expresses a pro-access policy.","zh":"這個片語表達支持參與權的政策。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":9},{"front":"when eligibility is in question","meaning":"當資格存疑時","examples":[{"en":"Inclusion is preferred when eligibility is in question.","zh":"當資格存疑時，較傾向納入。"},{"en":"When eligibility is in question means when it is uncertain whether someone qualifies.","zh":"when eligibility is in question 指不確定某人是否符合資格時。"},{"en":"If a student’s scholarship eligibility is in question, the school may ask for extra documents.","zh":"如果學生獎學金資格存疑，學校可能要求額外文件。"},{"en":"When eligibility is uncertain, a fair process should examine the facts carefully.","zh":"當資格不確定時，公平程序應仔細檢視事實。"},{"en":"The phrase describes a doubtful qualification situation.","zh":"這個片語描述資格有疑問的情況。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":9},{"front":"multiple disabilities","meaning":"多重障礙","examples":[{"en":"Individuals with intellectual disability and multiple disabilities may participate.","zh":"有智力障礙和多重障礙的人士可以參加。"},{"en":"Multiple disabilities means two or more disabilities affecting one person.","zh":"multiple disabilities 指一個人受到兩種或以上障礙影響。"},{"en":"A child with hearing loss and a physical disability may have multiple disabilities.","zh":"有聽力障礙和身體殘疾的孩子可能有多重障礙。"},{"en":"If someone has multiple disabilities, support may need to be coordinated across several areas.","zh":"如果某人有多重障礙，支援可能需要跨幾個範疇協調。"},{"en":"The phrase highlights combined support needs.","zh":"這個片語強調綜合支援需要。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":9},{"front":"participate in programmes and competitions","meaning":"參加計劃及比賽","examples":[{"en":"Eligible individuals may participate in Special Olympics programmes and competitions.","zh":"符合資格人士可以參加特殊奧運會計劃及比賽。"},{"en":"Participate in programmes and competitions means join organised activities and formal contests.","zh":"participate in programmes and competitions 指加入有組織活動和正式比賽。"},{"en":"A student may participate in music programmes and school competitions during the year.","zh":"學生一年中可能參加音樂計劃及學校比賽。"},{"en":"If people participate regularly, they can build routine, skill, and confidence.","zh":"如果人們定期參與，就能建立常規、技能和信心。"},{"en":"The phrase covers both training opportunities and competitive events.","zh":"這個片語涵蓋訓練機會和競賽活動。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":9},{"front":"participation by individuals with Down syndrome","meaning":"唐氏綜合症人士的參與","examples":[{"en":"The section discusses participation by individuals with Down syndrome.","zh":"這一節討論唐氏綜合症人士的參與。"},{"en":"Participation by individuals with Down syndrome means how people with Down syndrome may join activities safely and fairly.","zh":"participation by individuals with Down syndrome 指唐氏綜合症人士如何安全而公平地參加活動。"},{"en":"A sports club may review participation by individuals with Down syndrome before planning certain events.","zh":"體育會在規劃某些項目前，可能檢視唐氏綜合症人士的參與安排。"},{"en":"If an activity creates medical risk, participation may require extra checks.","zh":"如果活動帶來醫療風險，參與可能需要額外檢查。"},{"en":"The phrase focuses on access together with safety.","zh":"這個片語同時集中於參與權和安全。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":9},{"front":"Down syndrome","meaning":"唐氏綜合症","examples":[{"en":"Some individuals with Down syndrome may face risks in certain sports.","zh":"有些唐氏綜合症人士在某些運動中可能面對風險。"},{"en":"Down syndrome is a genetic condition that can affect development, learning, and some health risks.","zh":"Down syndrome 是一種可影響發展、學習和某些健康風險的遺傳情況。"},{"en":"A school may provide learning support for a child with Down syndrome.","zh":"學校可能為有唐氏綜合症的孩子提供學習支援。"},{"en":"If a person with Down syndrome has certain neck instability, some sports may require medical clearance.","zh":"如果唐氏綜合症人士有某種頸部不穩定，部分運動可能需要醫療許可。"},{"en":"The phrase names a condition, but it should not define the whole person.","zh":"這個片語指一種情況，但不應定義整個人。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":9},{"front":"atlantoaxial instability","meaning":"寰樞椎不穩定","examples":[{"en":"Atlantoaxial instability can increase the risk of neck injury.","zh":"寰樞椎不穩定可增加頸部受傷風險。"},{"en":"Atlantoaxial instability is instability between the first two neck vertebrae.","zh":"atlantoaxial instability 指第一和第二頸椎之間不穩定。"},{"en":"A doctor may check for atlantoaxial instability before an athlete joins high-risk sports.","zh":"醫生可能在運動員參加高風險運動前檢查寰樞椎不穩定。"},{"en":"If atlantoaxial instability is present, pressure on the neck can be dangerous.","zh":"如果存在寰樞椎不穩定，頸部受壓可能很危險。"},{"en":"The phrase describes a specific medical risk involving the upper neck.","zh":"這個片語描述涉及上頸部的特定醫療風險。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":9},{"front":"evidence from medical research","meaning":"醫學研究證據","examples":[{"en":"There is evidence from medical research about risks for some athletes.","zh":"有醫學研究證據顯示部分運動員面對風險。"},{"en":"Evidence from medical research means findings from scientific studies about health or treatment.","zh":"evidence from medical research 指關於健康或治療的科學研究結果。"},{"en":"A hospital may change its advice after evidence from medical research becomes stronger.","zh":"當醫學研究證據變得更強，醫院可能改變建議。"},{"en":"If medical research shows a risk, sports rules may include safety restrictions.","zh":"如果醫學研究顯示有風險，體育規則可能包括安全限制。"},{"en":"The phrase signals that a rule is based on health studies.","zh":"這個片語表示規則建基於健康研究。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":9},{"front":"up to 15 per cent of","meaning":"高達百分之十五的……","examples":[{"en":"Up to 15 per cent of individuals with Down syndrome may have the condition.","zh":"高達百分之十五的唐氏綜合症人士可能有這種情況。"},{"en":"Up to 15 per cent of means as many as 15 out of every 100, but possibly fewer.","zh":"up to 15 per cent of 指每100人中最多15人，但也可能較少。"},{"en":"Up to 15 per cent of students may need extra help after a difficult test.","zh":"困難測驗後，高達百分之十五的學生可能需要額外幫助。"},{"en":"If up to 15 per cent of a group faces a risk, screening may be considered.","zh":"如果某群體中高達15%面對風險，可能需要考慮篩查。"},{"en":"The phrase gives a maximum estimated proportion.","zh":"這個片語給出最高估計比例。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":9},{"front":"have a defect in","meaning":"在……有缺陷","examples":[{"en":"Some individuals with Down syndrome have a defect in the cervical vertebrae.","zh":"有些唐氏綜合症人士在頸椎有缺陷。"},{"en":"Have a defect in means have an abnormality or structural problem in a body part or system.","zh":"have a defect in 指在身體部位或系統中有異常或結構問題。"},{"en":"A machine may have a defect in its brake system and need repair.","zh":"機器可能在煞車系統有缺陷，需要維修。"},{"en":"If a person has a defect in the neck vertebrae, certain movements may be risky.","zh":"如果一個人在頸椎有缺陷，某些動作可能有風險。"},{"en":"The phrase identifies the location of a problem.","zh":"這個片語指出問題位置。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":9},{"front":"cervical vertebrae","meaning":"頸椎","examples":[{"en":"The condition involves the cervical vertebrae C-1 and C-2 in the neck.","zh":"這種情況涉及頸部的第一及第二頸椎。"},{"en":"Cervical vertebrae are the bones of the spine in the neck.","zh":"cervical vertebrae 是頸部脊柱中的骨頭。"},{"en":"A doctor may examine the cervical vertebrae after a neck injury.","zh":"頸部受傷後，醫生可能檢查頸椎。"},{"en":"If cervical vertebrae are unstable, sports involving neck pressure may be unsafe.","zh":"如果頸椎不穩定，涉及頸部壓力的運動可能不安全。"},{"en":"The phrase refers to specific bones that support the head and neck.","zh":"這個片語指支撐頭部和頸部的特定骨頭。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":10},{"front":"C-1 and C-2","meaning":"第一及第二頸椎","examples":[{"en":"C-1 and C-2 are cervical vertebrae in the neck.","zh":"C-1 和 C-2 是頸部的頸椎。"},{"en":"C-1 and C-2 are the first two bones at the top of the cervical spine.","zh":"C-1 and C-2 是頸椎最上方的首兩節骨頭。"},{"en":"Doctors may check C-1 and C-2 when assessing upper-neck stability.","zh":"醫生評估上頸穩定性時，可能檢查第一及第二頸椎。"},{"en":"If C-1 and C-2 are unstable, sudden neck movement can increase injury risk.","zh":"如果第一及第二頸椎不穩定，突然頸部動作可增加受傷風險。"},{"en":"The phrase names two specific neck vertebrae.","zh":"這個片語指兩節特定頸椎。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":10},{"front":"expose someone to","meaning":"使某人面對……","examples":[{"en":"The condition exposes individuals to a heightened risk of neck injury.","zh":"這種情況使個人面對較高頸部受傷風險。"},{"en":"Expose someone to means put someone in a situation where they may face danger or influence.","zh":"expose someone to 指把某人置於可能面對危險或影響的情況中。"},{"en":"Leaving food uncovered can expose people to bacteria.","zh":"食物不蓋好可能使人接觸細菌。"},{"en":"If a sport exposes an athlete to neck injury, medical clearance may be needed.","zh":"如果某運動使運動員面對頸部受傷風險，可能需要醫療許可。"},{"en":"The phrase describes creating or increasing contact with risk.","zh":"這個片語描述造成或增加與風險的接觸。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":10},{"front":"a heightened risk of","meaning":"較高的……風險","examples":[{"en":"Some activities create a heightened risk of neck injury.","zh":"某些活動造成較高頸部受傷風險。"},{"en":"A heightened risk of means a greater-than-usual chance of something harmful happening.","zh":"a heightened risk of 指有害事情發生的機會比平常更高。"},{"en":"Wet floors create a heightened risk of slipping in a school corridor.","zh":"濕地板在學校走廊造成較高滑倒風險。"},{"en":"If a medical condition raises risk, rules may restrict certain activities.","zh":"如果醫療情況提高風險，規則可能限制某些活動。"},{"en":"The phrase warns that the danger is higher than normal.","zh":"這個片語警告危險高於正常水平。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":10},{"front":"neck injury","meaning":"頸部受傷","examples":[{"en":"Certain sports may increase the risk of a neck injury.","zh":"某些運動可能增加頸部受傷風險。"},{"en":"Neck injury means damage to the bones, muscles, nerves, or tissues in the neck.","zh":"neck injury 指頸部骨頭、肌肉、神經或組織受損。"},{"en":"A cyclist may suffer a neck injury after a serious fall.","zh":"單車手嚴重跌倒後可能頸部受傷。"},{"en":"If the neck is unstable, sudden bending or pressure may cause injury.","zh":"如果頸部不穩定，突然屈曲或受壓可能造成受傷。"},{"en":"The phrase describes harm to a sensitive body area.","zh":"這個片語描述敏感身體部位受傷。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":10},{"front":"participate in activities that","meaning":"參與會……的活動","examples":[{"en":"Some athletes should avoid activities that put pressure on the neck.","zh":"有些運動員應避免參與會對頸部施壓的活動。"},{"en":"Participate in activities that means take part in activities with a particular feature or effect.","zh":"participate in activities that 指參與具有某特徵或效果的活動。"},{"en":"Students may participate in activities that build teamwork, such as group games.","zh":"學生可以參與會建立團隊合作的活動，例如小組遊戲。"},{"en":"If activities place pressure on the neck, some athletes may need medical advice before joining.","zh":"如果活動會對頸部造成壓力，部分運動員參加前可能需要醫療建議。"},{"en":"The phrase introduces the type of activity being discussed.","zh":"這個片語引出正在討論的活動類型。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":10},{"front":"hyperextend the neck","meaning":"使頸部過度伸展","examples":[{"en":"Certain sports may hyperextend the neck.","zh":"某些運動可能使頸部過度伸展。"},{"en":"Hyperextend the neck means bend the neck backward beyond its normal safe range.","zh":"hyperextend the neck 指把頸部向後彎超出正常安全範圍。"},{"en":"A gymnast may risk hyperextending the neck during a poorly controlled movement.","zh":"體操運動員在控制不佳的動作中可能有頸部過度伸展風險。"},{"en":"If an athlete has neck instability, hyperextension can be especially dangerous.","zh":"如果運動員有頸部不穩定，過度伸展可能特別危險。"},{"en":"The phrase describes an excessive backward neck movement.","zh":"這個片語描述過度向後的頸部動作。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":10},{"front":"radically flex the neck","meaning":"使頸部大幅屈曲","examples":[{"en":"Some activities radically flex the neck or upper spine.","zh":"有些活動會使頸部或上脊椎大幅屈曲。"},{"en":"Radically flex the neck means bend the neck forward sharply or extremely.","zh":"radically flex the neck 指使頸部劇烈或極度向前彎曲。"},{"en":"A risky tumbling move may radically flex the neck if the athlete lands badly.","zh":"如果運動員落地不佳，高風險翻滾動作可能使頸部大幅屈曲。"},{"en":"If the upper neck is unstable, extreme forward bending can increase injury risk.","zh":"如果上頸不穩定，極端向前屈曲可增加受傷風險。"},{"en":"The phrase describes a strong bending movement of the neck.","zh":"這個片語描述頸部強烈彎曲動作。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":10},{"front":"upper spine","meaning":"上脊椎","examples":[{"en":"Direct pressure on the upper spine can be risky.","zh":"對上脊椎造成直接壓力可能有風險。"},{"en":"The upper spine is the top part of the backbone, including the neck area.","zh":"upper spine 是脊柱上部，包括頸部區域。"},{"en":"A doctor may examine the upper spine after a fall or sports injury.","zh":"跌倒或運動受傷後，醫生可能檢查上脊椎。"},{"en":"If the upper spine is placed under strong pressure, nerve or bone injury may result.","zh":"如果上脊椎承受強壓，可能造成神經或骨骼受傷。"},{"en":"The phrase refers to a sensitive part of the spinal column.","zh":"這個片語指脊柱中敏感的部分。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":10},{"front":"temporarily restrict","meaning":"暫時限制","examples":[{"en":"SOC temporarily restricts some individuals from certain activities.","zh":"SOC 暫時限制部分人士參與某些活動。"},{"en":"Temporarily restrict means limit something for a period of time, not permanently.","zh":"temporarily restrict 指在一段時間內限制某事，而不是永久限制。"},{"en":"A school may temporarily restrict playground access after heavy rain.","zh":"大雨後，學校可能暫時限制進入操場。"},{"en":"If a medical check is still pending, participation may be temporarily restricted.","zh":"如果醫療檢查仍未完成，參與可能被暫時限制。"},{"en":"The phrase suggests a safety limit that may later be removed.","zh":"這個片語暗示之後可能解除的安全限制。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":10},{"front":"restrict someone from participation in","meaning":"限制某人參加……","examples":[{"en":"The rules restrict some athletes from participation in certain sports.","zh":"規則限制部分運動員參加某些運動。"},{"en":"Restrict someone from participation in means limit or prevent someone from joining an activity.","zh":"restrict someone from participation in 指限制或阻止某人加入活動。"},{"en":"A doctor may restrict a patient from participation in contact sports after a concussion.","zh":"醫生可能在腦震盪後限制病人參加接觸性運動。"},{"en":"If the risk is temporary, the restriction may end after medical clearance.","zh":"如果風險是暫時的，限制可在取得醫療許可後結束。"},{"en":"The phrase focuses on limiting participation for a stated reason.","zh":"這個片語集中於因特定原因限制參與。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":11},{"front":"certain activities","meaning":"某些活動","examples":[{"en":"Some athletes are temporarily restricted from certain activities.","zh":"有些運動員被暫時限制參與某些活動。"},{"en":"Certain activities means particular activities, not all activities.","zh":"certain activities 指特定活動，而不是所有活動。"},{"en":"A student with an injured wrist may avoid certain activities such as basketball or climbing.","zh":"手腕受傷的學生可能避免籃球或攀爬等某些活動。"},{"en":"If only certain activities are restricted, the person may still join safer alternatives.","zh":"如果只限制某些活動，該人士仍可參加較安全替代活動。"},{"en":"The phrase narrows the rule to selected activities.","zh":"這個片語把規則縮窄至指定活動。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":11},{"front":"Accredited Programmes","meaning":"認可計劃","examples":[{"en":"Accredited Programmes may allow individuals with Down syndrome to continue training.","zh":"認可計劃可允許唐氏綜合症人士繼續訓練。"},{"en":"Accredited Programmes are officially recognised programmes that meet required standards.","zh":"Accredited Programmes 指符合所需標準並獲官方承認的計劃。"},{"en":"A school may choose an accredited programme because parents can trust its quality.","zh":"學校可能選擇認可計劃，因為家長可相信其質素。"},{"en":"If a programme is accredited, it usually follows approved rules and procedures.","zh":"如果計劃獲認可，它通常遵守獲批准的規則和程序。"},{"en":"The phrase refers to programmes with official approval.","zh":"這個片語指獲官方批准的計劃。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":11},{"front":"continue in most activities","meaning":"繼續參與大部分活動","examples":[{"en":"Athletes may continue in most Special Olympics activities.","zh":"運動員可以繼續參與大部分特殊奧運會活動。"},{"en":"Continue in most activities means keep taking part in the majority of activities, even if some are restricted.","zh":"continue in most activities 指即使某些活動受限制，仍可參與大多數活動。"},{"en":"A student with a minor injury may continue in most lessons but skip contact sports.","zh":"輕傷學生可以繼續參與大部分課堂，但暫停接觸性運動。"},{"en":"If restrictions affect only high-risk activities, participation can still remain broad.","zh":"如果限制只影響高風險活動，參與仍可保持廣泛。"},{"en":"The phrase balances safety with inclusion.","zh":"這個片語在安全和共融之間取得平衡。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":11},{"front":"sports training and competition activities","meaning":"體育訓練及比賽活動","examples":[{"en":"Most sports training and competition activities remain open to eligible athletes.","zh":"大部分體育訓練及比賽活動仍向合資格運動員開放。"},{"en":"Sports training and competition activities include practice sessions and formal sporting events.","zh":"sports training and competition activities 包括練習課和正式體育賽事。"},{"en":"A football team’s weekly drills and weekend matches are sports training and competition activities.","zh":"足球隊每週訓練和週末比賽都是體育訓練及比賽活動。"},{"en":"If activities remain open, athletes can keep developing skills and confidence.","zh":"如果活動仍然開放，運動員可以繼續發展技能和信心。"},{"en":"The phrase covers both preparation and actual contests.","zh":"這個片語涵蓋準備和正式比賽。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":11},{"front":"shall not be permitted to","meaning":"不得被允許去","examples":[{"en":"Some individuals shall not be permitted to participate in high-risk activities.","zh":"有些人士不得被允許參與高風險活動。"},{"en":"Shall not be permitted to means will not be allowed to do something under the rules.","zh":"shall not be permitted to 指根據規則不會被允許做某事。"},{"en":"Students shall not be permitted to enter the laboratory without supervision.","zh":"學生在沒有監督下不得被允許進入實驗室。"},{"en":"If an activity is unsafe, rules may state that certain people shall not be permitted to join.","zh":"如果活動不安全，規則可能寫明某些人不得參與。"},{"en":"The phrase is formal and stronger than should not.","zh":"這個片語較正式，比 should not 更強。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":11},{"front":"by their nature","meaning":"就其本質而言","examples":[{"en":"Some sports, by their nature, place stress on the neck.","zh":"某些運動就其本質而言會對頸部造成壓力。"},{"en":"By their nature means because of what they are normally like.","zh":"by their nature 指因為它們本身通常具有的特性。"},{"en":"Swimming pools, by their nature, require careful safety rules around water.","zh":"游泳池就其本質而言，需要圍繞水域制定謹慎安全規則。"},{"en":"If an activity involves jumping or twisting by its nature, injury risk may be higher.","zh":"如果活動本質上涉及跳躍或扭動，受傷風險可能較高。"},{"en":"The phrase explains risk as part of the activity itself.","zh":"這個片語把風險解釋為活動本身的一部分。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":11},{"front":"result in","meaning":"導致","examples":[{"en":"Certain activities result in hyperextension of the neck.","zh":"某些活動會導致頸部過度伸展。"},{"en":"Result in means cause something to happen.","zh":"result in 指造成某事發生。"},{"en":"Poor sleep can result in weak concentration the next day.","zh":"睡眠不足可以導致翌日專注力弱。"},{"en":"If a movement results in neck hyperextension, it may be unsafe for some athletes.","zh":"如果某動作導致頸部過度伸展，對部分運動員可能不安全。"},{"en":"The phrase links an action with its effect.","zh":"這個片語把行動與效果連接起來。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":11},{"front":"hyperextension","meaning":"過度伸展","examples":[{"en":"Hyperextension of the neck can be dangerous for some athletes.","zh":"頸部過度伸展對某些運動員可能危險。"},{"en":"Hyperextension means bending a joint or body part beyond its normal safe range.","zh":"hyperextension 指關節或身體部位彎曲超出正常安全範圍。"},{"en":"A knee may suffer hyperextension if a player lands awkwardly after a jump.","zh":"如果球員跳起後落地不穩，膝蓋可能過度伸展。"},{"en":"If hyperextension happens in the neck, nerves or bones may be at risk.","zh":"如果過度伸展發生在頸部，神經或骨骼可能有風險。"},{"en":"The phrase describes excessive backward or extended movement.","zh":"這個片語描述過度向後或伸展的動作。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":11},{"front":"radical flexion","meaning":"大幅屈曲","examples":[{"en":"Radical flexion of the neck is listed as a risk factor.","zh":"頸部大幅屈曲被列為風險因素。"},{"en":"Radical flexion means extreme bending of a body part, especially forward bending.","zh":"radical flexion 指身體部位極度彎曲，尤其向前彎曲。"},{"en":"A poorly controlled roll may cause radical flexion of the neck.","zh":"控制不佳的翻滾可能造成頸部大幅屈曲。"},{"en":"If radical flexion affects the upper spine, injury risk can increase.","zh":"如果大幅屈曲影響上脊椎，受傷風險可增加。"},{"en":"The phrase describes a strong and potentially unsafe bend.","zh":"這個片語描述強烈且可能不安全的彎曲。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":11},{"front":"direct pressure on","meaning":"對……造成直接壓力","examples":[{"en":"Some activities place direct pressure on the neck or upper spine.","zh":"有些活動會對頸部或上脊椎造成直接壓力。"},{"en":"Direct pressure on means force applied straight onto a body part or surface.","zh":"direct pressure on 指直接施加在身體部位或表面的力量。"},{"en":"A heavy backpack can place direct pressure on a child’s shoulders.","zh":"沉重書包可以對孩子肩膀造成直接壓力。"},{"en":"If direct pressure is placed on an unstable neck, injury may occur.","zh":"如果直接壓力施加在不穩定頸部，可能造成受傷。"},{"en":"The phrase focuses on physical force against a specific area.","zh":"這個片語集中於作用在特定位置的實體力量。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":12},{"front":"butterfly stroke","meaning":"蝶泳","examples":[{"en":"The butterfly stroke is listed among the restricted activities.","zh":"蝶泳被列入受限制活動之中。"},{"en":"Butterfly stroke is a swimming style using both arms together with a wave-like body movement.","zh":"butterfly stroke 是一種雙臂同時動作並配合波浪式身體動作的游泳姿勢。"},{"en":"A swim coach may teach butterfly stroke only after students master basic techniques.","zh":"游泳教練可能在學生掌握基本技巧後才教授蝶泳。"},{"en":"If a stroke places strain on the neck, some athletes may need medical clearance before doing it.","zh":"如果某泳式對頸部造成壓力，部分運動員做之前可能需要醫療許可。"},{"en":"The phrase names a specific swimming event or technique.","zh":"這個片語指特定游泳項目或技巧。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":12},{"front":"diving starts","meaning":"跳水式起步","examples":[{"en":"Diving starts in swimming may place stress on the neck.","zh":"游泳中的跳水式起步可能對頸部造成壓力。"},{"en":"Diving starts are race starts where swimmers dive into the pool from a platform or edge.","zh":"diving starts 是游泳比賽中泳手從跳台或池邊跳入水中的起步方式。"},{"en":"A swimming coach teaches diving starts carefully to avoid head or neck injury.","zh":"游泳教練會小心教授跳水式起步，以避免頭部或頸部受傷。"},{"en":"If an athlete enters the water badly, a diving start can create neck pressure.","zh":"如果運動員入水姿勢不佳，跳水式起步可能造成頸部壓力。"},{"en":"The phrase refers to the starting movement, not the sport of diving alone.","zh":"這個片語指起步動作，而不只是跳水運動。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":12},{"front":"pentathlon","meaning":"五項全能","examples":[{"en":"Pentathlon is included among the restricted activities.","zh":"五項全能被列入受限制活動之中。"},{"en":"Pentathlon is a sports event made up of five different events.","zh":"pentathlon 是由五個不同項目組成的體育賽事。"},{"en":"School athletes may train for a pentathlon by practising several skills, not just one.","zh":"學校運動員準備五項全能時，可能練習多種技能，而不只一種。"},{"en":"If one part of a pentathlon creates neck risk, medical rules may restrict participation.","zh":"如果五項全能其中一部分造成頸部風險，醫療規則可能限制參與。"},{"en":"The word comes from the idea of five events.","zh":"這個詞來自五個項目的概念。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":12},{"front":"high jump","meaning":"跳高","examples":[{"en":"High jump is listed as a restricted activity for some athletes.","zh":"跳高被列為部分運動員的受限制活動。"},{"en":"High jump is a track-and-field event in which athletes jump over a raised bar.","zh":"high jump 是田徑項目，運動員要跳過升高的橫桿。"},{"en":"A coach teaches high jump technique so athletes land safely on the mat.","zh":"教練教授跳高技巧，讓運動員安全落在墊上。"},{"en":"If landing places stress on the neck or spine, some athletes may need restrictions.","zh":"如果落地對頸部或脊椎造成壓力，部分運動員可能需要限制。"},{"en":"The phrase names a specific athletics event.","zh":"這個片語指特定田徑項目。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":12},{"front":"equestrian sports","meaning":"馬術運動","examples":[{"en":"Equestrian sports may involve risks for athletes with neck instability.","zh":"馬術運動對有頸部不穩定的運動員可能涉及風險。"},{"en":"Equestrian sports are sports involving horse riding or horse handling.","zh":"equestrian sports 是涉及騎馬或操控馬匹的運動。"},{"en":"Riders in equestrian sports need balance, control, and safety equipment.","zh":"馬術運動中的騎手需要平衡、控制和安全裝備。"},{"en":"If a rider falls from a horse, the head, neck, or spine may be injured.","zh":"如果騎手從馬上跌下，頭部、頸部或脊椎可能受傷。"},{"en":"The phrase refers to horse-related sports.","zh":"這個片語指與馬有關的運動。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":12},{"front":"artistic gymnastics","meaning":"競技體操","examples":[{"en":"Artistic gymnastics is listed among the restricted sports.","zh":"競技體操被列入受限制運動之中。"},{"en":"Artistic gymnastics is a sport involving routines on apparatus, tumbling, strength, and flexibility.","zh":"artistic gymnastics 是涉及器械套路、翻滾、力量和柔韌性的運動。"},{"en":"Gymnasts practise artistic gymnastics with coaches and mats to reduce injury risk.","zh":"體操運動員在教練和墊子輔助下練習競技體操，以減少受傷風險。"},{"en":"If a routine involves flips or head pressure, neck safety becomes important.","zh":"如果套路涉及翻轉或頭部受壓，頸部安全就很重要。"},{"en":"The phrase names a technical gymnastics discipline.","zh":"這個片語指一項專門體操項目。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":12},{"front":"alpine skiing","meaning":"高山滑雪","examples":[{"en":"Alpine skiing is one of the activities listed in the restriction.","zh":"高山滑雪是限制中列出的活動之一。"},{"en":"Alpine skiing is downhill skiing on snow-covered slopes.","zh":"alpine skiing 是在覆雪斜坡上向下滑行的滑雪運動。"},{"en":"A beginner in alpine skiing learns how to stop, turn, and fall safely.","zh":"高山滑雪初學者會學習如何停止、轉彎和安全跌倒。"},{"en":"If a skier falls at speed, the neck and spine may be at risk.","zh":"如果滑雪者高速跌倒，頸部和脊椎可能有風險。"},{"en":"The phrase names a winter sport involving downhill movement.","zh":"這個片語指一項涉及下坡移動的冬季運動。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":12},{"front":"warm-up exercise","meaning":"熱身運動","examples":[{"en":"Some warm-up exercise may place undue stress on the neck.","zh":"有些熱身運動可能對頸部造成過度壓力。"},{"en":"Warm-up exercise is light physical activity done before sport to prepare the body.","zh":"warm-up exercise 是運動前為準備身體而做的輕量體能活動。"},{"en":"Gentle stretching and slow jogging can be warm-up exercises before a game.","zh":"溫和伸展和慢跑可以是比賽前的熱身運動。"},{"en":"If a warm-up exercise bends the neck too far, it may not be safe for everyone.","zh":"如果熱身運動令頸部彎得太多，未必對所有人安全。"},{"en":"The phrase refers to preparation before main activity.","zh":"這個片語指主要活動前的準備。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":12},{"front":"place undue stress on","meaning":"對……造成過度壓力","examples":[{"en":"Certain exercises place undue stress on the head and neck.","zh":"某些運動對頭部和頸部造成過度壓力。"},{"en":"Place undue stress on means put too much pressure or strain on something.","zh":"place undue stress on 指對某物造成過多壓力或負荷。"},{"en":"A heavy schoolbag can place undue stress on a child’s shoulders.","zh":"沉重書包可以對孩子肩膀造成過度壓力。"},{"en":"If an exercise places undue stress on an injured area, it should be changed.","zh":"如果某運動對受傷部位造成過度壓力，就應改變。"},{"en":"The phrase warns that the pressure is excessive or inappropriate.","zh":"這個片語警告壓力過大或不合適。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":12},{"front":"the head and neck","meaning":"頭部和頸部","examples":[{"en":"Exercises should not place undue stress on the head and neck.","zh":"運動不應對頭部和頸部造成過度壓力。"},{"en":"The head and neck means the upper body area including the skull, throat, and cervical spine.","zh":"the head and neck 指包括頭骨、喉部和頸椎的上身區域。"},{"en":"Helmets are designed to protect the head and neck in some sports.","zh":"頭盔設計用於在某些運動中保護頭部和頸部。"},{"en":"If the head and neck are injured, movement and breathing can be affected.","zh":"如果頭部和頸部受傷，活動和呼吸都可能受影響。"},{"en":"The phrase refers to a sensitive and important body region.","zh":"這個片語指敏感而重要的身體區域。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":13},{"front":"restriction from participation","meaning":"參與限制","examples":[{"en":"Restriction from participation continues until a medical examination is completed.","zh":"參與限制會持續直至醫療檢查完成。"},{"en":"Restriction from participation means a limit that stops someone from joining an activity.","zh":"restriction from participation 指阻止某人加入活動的限制。"},{"en":"A player may face restriction from participation until an injury is checked.","zh":"球員在傷勢檢查前可能面對參與限制。"},{"en":"If the restriction is based on safety, it may end after medical clearance.","zh":"如果限制基於安全，它可能在取得醫療許可後結束。"},{"en":"The phrase describes temporary or official limits on joining.","zh":"這個片語描述暫時或官方的參與限制。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":13},{"front":"above-listed activities","meaning":"上述活動","examples":[{"en":"The above-listed activities require special medical clearance.","zh":"上述活動需要特別醫療許可。"},{"en":"Above-listed activities are the activities already named earlier in the document.","zh":"above-listed activities 指文件前文已列出的活動。"},{"en":"In a school notice, above-listed activities might include swimming, hiking, and football.","zh":"在學校通告中，上述活動可能包括游泳、遠足和足球。"},{"en":"If an activity is above-listed as risky, participants should check the special rules.","zh":"如果某活動在上述清單中被列為有風險，參加者應查看特殊規則。"},{"en":"The phrase avoids repeating the full list.","zh":"這個片語避免重複完整清單。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":13},{"front":"shall continue until","meaning":"將持續直至","examples":[{"en":"The restriction shall continue until the athlete has been examined.","zh":"限制將持續直至運動員接受檢查。"},{"en":"Shall continue until means will remain in force up to a stated point or condition.","zh":"shall continue until 指將維持有效，直到某個指定時間或條件。"},{"en":"A library ban shall continue until the lost book is returned.","zh":"圖書館禁令將持續直至遺失書籍歸還。"},{"en":"If a restriction continues until an examination, the exam result controls what happens next.","zh":"如果限制持續至檢查完成，檢查結果就決定之後安排。"},{"en":"The phrase is formal and sets an endpoint.","zh":"這個片語較正式，並設定終點。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":13},{"front":"be examined by","meaning":"由……檢查","examples":[{"en":"The athlete must be examined by a physician.","zh":"運動員必須由醫生檢查。"},{"en":"Be examined by means be checked or assessed by a qualified person.","zh":"be examined by 指由合資格人士檢查或評估。"},{"en":"A child with a fever may be examined by a doctor at a clinic.","zh":"發燒孩子可能在診所由醫生檢查。"},{"en":"If an athlete is examined by a physician, risks can be identified before competition.","zh":"如果運動員由醫生檢查，風險可在比賽前被識別。"},{"en":"The phrase identifies who carries out the assessment.","zh":"這個片語指出由誰進行評估。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":13},{"front":"physician","meaning":"醫生","examples":[{"en":"A physician must examine the athlete before certain activities are allowed.","zh":"在允許某些活動前，醫生必須檢查運動員。"},{"en":"A physician is a medical doctor who diagnoses and treats illness or injury.","zh":"physician 是診斷和治療疾病或傷害的醫生。"},{"en":"A physician may advise a patient to avoid heavy exercise after a neck injury.","zh":"醫生可能建議頸部受傷後的病人避免劇烈運動。"},{"en":"If a physician gives clearance, an athlete may be allowed to return to sport.","zh":"如果醫生給予許可，運動員可能被允許重返運動。"},{"en":"The word is formal and common in medical documents.","zh":"這個詞較正式，常見於醫療文件。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":13},{"front":"be briefed on","meaning":"聽取關於……的簡介","examples":[{"en":"The physician must be briefed on the nature of atlantoaxial instability.","zh":"醫生必須聽取關於寰樞椎不穩定性質的簡介。"},{"en":"Be briefed on means be given important information about a subject before acting.","zh":"be briefed on 指在行動前獲提供關於某主題的重要資訊。"},{"en":"Teachers are briefed on safety rules before taking students on a trip.","zh":"老師帶學生旅行前會聽取安全規則簡介。"},{"en":"If a doctor is briefed on the specific risk, the examination can be more focused.","zh":"如果醫生已了解特定風險，檢查可以更有焦點。"},{"en":"The phrase describes receiving necessary background information.","zh":"這個片語描述接收必要背景資訊。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":13},{"front":"the nature of","meaning":"……的性質","examples":[{"en":"The physician should understand the nature of the condition.","zh":"醫生應理解該情況的性質。"},{"en":"The nature of something means its basic character, features, or way of working.","zh":"the nature of 指某事物的基本特性、特徵或運作方式。"},{"en":"A teacher must understand the nature of a student’s difficulty before choosing support.","zh":"老師在選擇支援前，必須理解學生困難的性質。"},{"en":"If the nature of a condition is misunderstood, the advice may be unsafe.","zh":"如果情況的性質被誤解，建議可能不安全。"},{"en":"The phrase asks what something really is like.","zh":"這個片語詢問某事物真正是怎樣的。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":13},{"front":"X-ray views","meaning":"X光影像","examples":[{"en":"The examination includes X-ray views of neck extension and flexion.","zh":"檢查包括頸部伸展和屈曲的 X 光影像。"},{"en":"X-ray views are medical images taken with X-rays from particular positions or angles.","zh":"X-ray views 是從特定姿勢或角度拍攝的 X 光醫學影像。"},{"en":"A doctor may request X-ray views after a fall to check for broken bones.","zh":"跌倒後，醫生可能要求拍攝 X 光影像以檢查是否骨折。"},{"en":"If different X-ray views show instability, sports participation may be restricted.","zh":"如果不同 X 光影像顯示不穩定，體育參與可能受限制。"},{"en":"The phrase refers to diagnostic images, not ordinary photographs.","zh":"這個片語指診斷影像，而不是普通照片。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":13},{"front":"full extension and flexion","meaning":"完全伸展及屈曲","examples":[{"en":"The X-ray views show full extension and flexion of the neck.","zh":"X 光影像顯示頸部完全伸展及屈曲。"},{"en":"Full extension and flexion means fully straightening or bending a body part through its range of movement.","zh":"full extension and flexion 指身體部位在活動範圍內完全伸直或彎曲。"},{"en":"A physiotherapist may check full extension and flexion of a knee after injury.","zh":"物理治療師可能在膝傷後檢查膝部完全伸展及屈曲。"},{"en":"If full neck movement shows instability, doctors may advise avoiding certain sports.","zh":"如果完整頸部活動顯示不穩定，醫生可能建議避免某些運動。"},{"en":"The phrase describes complete movement in opposite directions.","zh":"這個片語描述相反方向的完整動作。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":13},{"front":"demonstrate that","meaning":"證明","examples":[{"en":"The examination results must demonstrate that the athlete does not have the condition.","zh":"檢查結果必須證明運動員沒有該情況。"},{"en":"Demonstrate that means show clearly with evidence.","zh":"demonstrate that 指以證據清楚顯示。"},{"en":"A teacher may ask students to demonstrate that they understand a grammar rule by writing examples.","zh":"老師可能要求學生透過寫例句證明他們理解文法規則。"},{"en":"If test results demonstrate safety, restrictions may be removed.","zh":"如果測試結果證明安全，限制可能被取消。"},{"en":"The phrase requires proof, not only opinion.","zh":"這個片語要求證據，而不只是意見。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":14},{"front":"be diagnosed as having","meaning":"被診斷患有","examples":[{"en":"An athlete may be diagnosed as having atlantoaxial instability.","zh":"運動員可能被診斷患有寰樞椎不穩定。"},{"en":"Be diagnosed as having means be officially identified by a medical professional as having a condition.","zh":"be diagnosed as having 指由醫療專業人士正式確認患有某情況。"},{"en":"A patient may be diagnosed as having asthma after breathing tests.","zh":"病人在呼吸測試後可能被診斷患有哮喘。"},{"en":"If an athlete is diagnosed as having a condition, safety planning becomes necessary.","zh":"如果運動員被診斷患有某情況，就需要安全規劃。"},{"en":"The phrase is formal medical wording.","zh":"這個片語是正式醫療用語。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":14},{"front":"examining physician","meaning":"負責檢查的醫生","examples":[{"en":"The examining physician must notify the athlete’s parents or guardians.","zh":"負責檢查的醫生必須通知運動員的父母或監護人。"},{"en":"The examining physician is the doctor who conducts the medical examination.","zh":"examining physician 是進行醫療檢查的醫生。"},{"en":"The examining physician may explain test results to the patient after the check-up.","zh":"負責檢查的醫生可能在檢查後向病人解釋測試結果。"},{"en":"If the examining physician finds a risk, family members may need to be informed.","zh":"如果負責檢查的醫生發現風險，可能需要通知家人。"},{"en":"The phrase identifies the doctor responsible for the examination.","zh":"這個片語指出負責該次檢查的醫生。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":14},{"front":"notify someone of","meaning":"通知某人……","examples":[{"en":"The physician must notify the family of the nature and extent of the condition.","zh":"醫生必須通知家人該情況的性質及程度。"},{"en":"Notify someone of means formally tell someone about important information.","zh":"notify someone of 指正式告知某人重要資訊。"},{"en":"A school should notify parents of any serious accident during a trip.","zh":"學校應通知家長旅行中發生的任何嚴重意外。"},{"en":"If a doctor finds a medical risk, they must notify the relevant people clearly.","zh":"如果醫生發現醫療風險，必須清楚通知相關人士。"},{"en":"The phrase is more formal than simply tell.","zh":"這個片語比 simply tell 更正式。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":14},{"front":"parents or guardians","meaning":"父母或監護人","examples":[{"en":"Parents or guardians must be informed of the athlete’s condition.","zh":"父母或監護人必須獲告知運動員的情況。"},{"en":"Parents or guardians are the adults legally or practically responsible for a child or dependent person.","zh":"parents or guardians 指在法律上或實際上負責兒童或受照顧人士的成人。"},{"en":"A school asks parents or guardians to sign consent forms for trips.","zh":"學校要求父母或監護人簽署旅行同意書。"},{"en":"If a minor faces a medical risk, parents or guardians should receive clear information.","zh":"如果未成年人面對醫療風險，父母或監護人應收到清晰資訊。"},{"en":"The phrase covers both parents and other authorised carers.","zh":"這個片語涵蓋父母和其他獲授權照顧者。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":14},{"front":"nature and extent","meaning":"性質及程度","examples":[{"en":"The physician explains the nature and extent of the condition.","zh":"醫生解釋該情況的性質及程度。"},{"en":"Nature and extent means what the condition is and how serious or wide-ranging it is.","zh":"nature and extent 指情況是甚麼，以及有多嚴重或影響多廣。"},{"en":"After a flood, officials assess the nature and extent of the damage.","zh":"水災後，官員會評估損害的性質及程度。"},{"en":"If families understand the nature and extent of a risk, they can make better decisions.","zh":"如果家庭理解風險的性質及程度，就能作出更好決定。"},{"en":"The phrase combines type and severity.","zh":"這個片語結合類型和嚴重程度。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":14},{"front":"be allowed to participate in","meaning":"被允許參加……","examples":[{"en":"The athlete may be allowed to participate in certain activities after certification.","zh":"運動員提交證明後，可能被允許參加某些活動。"},{"en":"Be allowed to participate in means receive permission to join an activity.","zh":"be allowed to participate in 指獲得許可加入某活動。"},{"en":"A student may be allowed to participate in sports after recovering from an injury.","zh":"學生傷癒後可能被允許參加運動。"},{"en":"If the required documents are submitted, participation may be approved.","zh":"如果提交所需文件，參與可能獲批准。"},{"en":"The phrase focuses on permission to take part.","zh":"這個片語集中於參與許可。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":14},{"front":"submit written certification","meaning":"提交書面證明","examples":[{"en":"The athlete must submit written certification from two physicians.","zh":"運動員必須提交兩名醫生的書面證明。"},{"en":"Submit written certification means provide official written proof or confirmation.","zh":"submit written certification 指提供正式書面證明或確認。"},{"en":"A student may submit written certification from a doctor after missing an exam due to illness.","zh":"學生因病缺考後，可能提交醫生書面證明。"},{"en":"If written certification is required, verbal permission is not enough.","zh":"如果需要書面證明，口頭許可並不足夠。"},{"en":"The phrase refers to formal documented evidence.","zh":"這個片語指正式文件證據。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":14},{"front":"combined with","meaning":"加上；連同","examples":[{"en":"The written certification must be combined with an acknowledgement of the risks.","zh":"書面證明必須連同對風險的確認。"},{"en":"Combined with means joined together with another thing.","zh":"combined with 指與另一事物結合在一起。"},{"en":"Regular exercise combined with enough sleep can improve health.","zh":"定期運動加上足夠睡眠可以改善健康。"},{"en":"If a medical certificate is combined with a risk acknowledgement, both safety and consent are recorded.","zh":"如果醫療證明連同風險確認，安全和同意都會被記錄。"},{"en":"The phrase shows that two things are required together.","zh":"這個片語顯示兩件事需要一起存在。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":14},{"front":"acknowledgement of the risks","meaning":"對風險的確認","examples":[{"en":"The athlete must provide an acknowledgement of the risks.","zh":"運動員必須提供對風險的確認。"},{"en":"Acknowledgement of the risks means written or spoken recognition that possible dangers are understood.","zh":"acknowledgement of the risks 指以書面或口頭承認已理解可能危險。"},{"en":"Before a school hiking trip, parents may sign an acknowledgement of the risks.","zh":"學校遠足前，家長可能簽署對風險的確認。"},{"en":"If people acknowledge risks, they show they understand possible consequences.","zh":"如果人們確認風險，就表示他們理解可能後果。"},{"en":"The phrase records awareness of danger.","zh":"這個片語記錄對危險的認知。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":14},{"front":"signed by","meaning":"由……簽署","examples":[{"en":"The acknowledgement must be signed by the athlete or guardian.","zh":"確認書必須由運動員或監護人簽署。"},{"en":"Signed by means formally marked with a person’s signature to show agreement or responsibility.","zh":"signed by 指由某人簽名，以正式表示同意或責任。"},{"en":"A permission form for a school trip must be signed by a parent.","zh":"學校旅行同意書必須由家長簽署。"},{"en":"If a document is not signed by the required person, it may not be valid.","zh":"如果文件沒有由指定人士簽署，可能無效。"},{"en":"The phrase identifies who must give formal written approval.","zh":"這個片語指出誰必須給予正式書面批准。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":15},{"front":"adult athlete","meaning":"成年運動員","examples":[{"en":"An adult athlete may sign the acknowledgement personally.","zh":"成年運動員可以親自簽署確認書。"},{"en":"An adult athlete is an athlete who is legally an adult.","zh":"adult athlete 指在法律上已成年的運動員。"},{"en":"An adult athlete can usually make certain participation decisions for themselves.","zh":"成年運動員通常可以為自己作出某些參與決定。"},{"en":"If the athlete is an adult, a parent’s signature may not be required.","zh":"如果運動員是成年人，可能不需要家長簽署。"},{"en":"The phrase distinguishes adults from minors in consent rules.","zh":"這個片語在同意規則中區分成年人和未成年人。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":15},{"front":"parent or guardian","meaning":"父母或監護人","examples":[{"en":"A parent or guardian must sign if the athlete is a minor.","zh":"如果運動員是未成年人，父母或監護人必須簽署。"},{"en":"A parent or guardian is an adult responsible for a child’s care or legal decisions.","zh":"parent or guardian 指負責兒童照顧或法律決定的成人。"},{"en":"A school may contact a parent or guardian if a student becomes ill.","zh":"如果學生生病，學校可能聯絡父母或監護人。"},{"en":"If a minor faces medical risk, a parent or guardian may need to give permission.","zh":"如果未成年人面對醫療風險，父母或監護人可能需要給予許可。"},{"en":"The phrase covers both parents and legally recognised carers.","zh":"這個片語涵蓋父母和法律認可照顧者。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":15},{"front":"if the athlete is a minor","meaning":"如果運動員是未成年人","examples":[{"en":"A guardian must sign if the athlete is a minor.","zh":"如果運動員是未成年人，監護人必須簽署。"},{"en":"If the athlete is a minor means if the athlete is under the legal age of adulthood.","zh":"if the athlete is a minor 指如果運動員未達法律成年年齡。"},{"en":"If a student is a minor, the school usually needs parental consent for trips.","zh":"如果學生是未成年人，學校旅行通常需要家長同意。"},{"en":"If the athlete is not an adult, decision-making may involve a parent or guardian.","zh":"如果運動員不是成年人，決策可能涉及父母或監護人。"},{"en":"The phrase sets a condition based on age.","zh":"這個片語設定基於年齡的條件。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":15},{"front":"responsibility of","meaning":"……的責任","examples":[{"en":"It is the responsibility of parents or guardians to monitor the individual.","zh":"監察該人士是父母或監護人的責任。"},{"en":"Responsibility of means the duty belonging to a person or group.","zh":"responsibility of 指屬於某人或某群體的責任。"},{"en":"It is the responsibility of drivers to stop at red lights.","zh":"停在紅燈前是司機的責任。"},{"en":"If a risk is known, the responsible person must watch for warning signs.","zh":"如果風險已知，負責人必須留意警號。"},{"en":"The phrase identifies who must take action.","zh":"這個片語指出誰必須採取行動。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":15},{"front":"monitor the individual","meaning":"監察該人士","examples":[{"en":"Parents or guardians should monitor the individual carefully.","zh":"父母或監護人應仔細監察該人士。"},{"en":"Monitor the individual means watch the person’s condition, behaviour, or symptoms over time.","zh":"monitor the individual 指隨時間觀察該人士的情況、行為或症狀。"},{"en":"A teacher may monitor a student after a fall in the playground.","zh":"學生在操場跌倒後，老師可能監察他。"},{"en":"If symptoms appear, careful monitoring helps adults respond quickly.","zh":"如果症狀出現，仔細監察有助成人迅速回應。"},{"en":"The phrase means active observation, not casual attention.","zh":"這個片語指主動觀察，而不是隨便留意。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":15},{"front":"take appropriate action","meaning":"採取適當行動","examples":[{"en":"Parents or guardians should take appropriate action if symptoms appear.","zh":"如果症狀出現，父母或監護人應採取適當行動。"},{"en":"Take appropriate action means do the right thing for the situation.","zh":"take appropriate action 指根據情況做正確的事。"},{"en":"If a student feels dizzy, a teacher should take appropriate action by seeking medical help.","zh":"如果學生感到頭暈，老師應採取適當行動，尋求醫療協助。"},{"en":"If warning signs are ignored, a small problem may become serious.","zh":"如果警號被忽視，小問題可能變嚴重。"},{"en":"The phrase stresses suitable and timely response.","zh":"這個片語強調合適而及時的回應。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":15},{"front":"neurological symptoms","meaning":"神經系統症狀","examples":[{"en":"Parents should act if neurological symptoms appear.","zh":"如果神經系統症狀出現，父母應採取行動。"},{"en":"Neurological symptoms are signs related to the brain, nerves, or spinal cord.","zh":"neurological symptoms 指與大腦、神經或脊髓有關的徵象。"},{"en":"Numbness, weakness, confusion, or loss of balance can be neurological symptoms.","zh":"麻木、無力、混亂或失去平衡都可以是神經系統症狀。"},{"en":"If neurological symptoms appear after a neck injury, medical help is urgent.","zh":"如果頸部受傷後出現神經系統症狀，就急需醫療協助。"},{"en":"The phrase refers to warning signs from the nervous system.","zh":"這個片語指來自神經系統的警號。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":15},{"front":"terminology note","meaning":"用語說明","examples":[{"en":"The terminology note explains preferred language about intellectual disability.","zh":"用語說明解釋關於智力障礙的較合適語言。"},{"en":"A terminology note is a short explanation about which words should be used and why.","zh":"terminology note 是關於應使用哪些詞語及原因的簡短解釋。"},{"en":"A textbook may include a terminology note when an old word has become outdated.","zh":"當舊詞變得過時，教科書可能加入用語說明。"},{"en":"If terminology changes, a note can help readers use respectful and accurate language.","zh":"如果用語改變，說明可幫助讀者使用尊重且準確的語言。"},{"en":"The phrase refers to guidance on wording.","zh":"這個片語指措辭指引。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":15},{"front":"be used to replace","meaning":"用作取代","examples":[{"en":"The term intellectual disability is used to replace the older clinical term.","zh":"intellectual disability 這個用語被用作取代較舊的臨床用語。"},{"en":"Be used to replace means be chosen instead of an older or less suitable word or thing.","zh":"be used to replace 指被選來代替較舊或較不合適的詞語或事物。"},{"en":"Digital notices may be used to replace paper circulars in a school.","zh":"數碼通知可被用作取代學校紙本通告。"},{"en":"If a term becomes disrespectful or outdated, a better term may replace it.","zh":"如果某用語變得不尊重或過時，較好用語可能取代它。"},{"en":"The phrase shows substitution.","zh":"這個片語表示替代。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":15},{"front":"clinical term","meaning":"臨床用語","examples":[{"en":"The document identifies the old wording as a clinical term.","zh":"文件把舊措辭識別為臨床用語。"},{"en":"A clinical term is a medical or professional word used in diagnosis or treatment.","zh":"clinical term 是診斷或治療中使用的醫學或專業詞語。"},{"en":"Doctors may use clinical terms in reports but explain them simply to patients.","zh":"醫生可能在報告中使用臨床用語，但向病人簡單解釋。"},{"en":"If a clinical term is outdated, professionals may change their wording.","zh":"如果臨床用語過時，專業人士可能改變措辭。"},{"en":"The phrase refers to medical language, not casual speech.","zh":"這個片語指醫學語言，而不是日常說話。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":16},{"front":"not a disease","meaning":"不是疾病","examples":[{"en":"Intellectual disability is not a disease.","zh":"智力障礙不是疾病。"},{"en":"Not a disease means it is not an illness that spreads or is treated like an infection.","zh":"not a disease 指它不是會傳播或像感染一樣治療的病。"},{"en":"Being left-handed is not a disease, even if it affects how someone uses tools.","zh":"左撇子不是疾病，即使它影響某人使用工具的方式。"},{"en":"If a condition is not a disease, people should avoid treating it as something contagious or shameful.","zh":"如果某情況不是疾病，人們應避免把它當作會傳染或可羞恥的東西。"},{"en":"The phrase corrects a common misunderstanding.","zh":"這個片語糾正常見誤解。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":16},{"front":"nor should it be confused with","meaning":"亦不應與……混淆","examples":[{"en":"Intellectual disability should not be confused with mental illness.","zh":"智力障礙不應與精神疾病混淆。"},{"en":"Nor should it be confused with means it also should not be mistaken for another thing.","zh":"nor should it be confused with 指也不應被誤認為另一事物。"},{"en":"Shyness is not rudeness, nor should it be confused with lack of intelligence.","zh":"害羞不是無禮，也不應與缺乏智慧混淆。"},{"en":"If two conditions are different, confusing them may lead to poor support.","zh":"如果兩種情況不同，把它們混淆可能導致支援不當。"},{"en":"The phrase adds a second warning against misunderstanding.","zh":"這個片語加入第二個避免誤解的提醒。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":16},{"front":"mental illness","meaning":"精神疾病","examples":[{"en":"Intellectual disability is different from mental illness.","zh":"智力障礙與精神疾病不同。"},{"en":"Mental illness refers to health conditions affecting mood, thinking, behaviour, or emotional wellbeing.","zh":"mental illness 指影響情緒、思維、行為或心理健康的健康情況。"},{"en":"Depression and anxiety are examples of mental illness that may need treatment and support.","zh":"抑鬱和焦慮是可能需要治療和支援的精神疾病例子。"},{"en":"If people confuse mental illness with intellectual disability, they may misunderstand both groups’ needs.","zh":"如果人們把精神疾病與智力障礙混淆，就可能誤解兩個群體的需要。"},{"en":"The phrase describes health conditions, not intelligence level.","zh":"這個片語描述健康情況，而不是智力水平。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":16},{"front":"a slower rate of learning","meaning":"較慢的學習速度","examples":[{"en":"People with intellectual disabilities may have a slower rate of learning.","zh":"有智力障礙的人士可能有較慢的學習速度。"},{"en":"A slower rate of learning means needing more time, repetition, or support to learn new skills.","zh":"a slower rate of learning 指學習新技能時需要更多時間、重複或支援。"},{"en":"A student with a slower rate of learning may benefit from step-by-step instructions.","zh":"學習速度較慢的學生可能受益於一步一步的指示。"},{"en":"If learning is slower, teaching should be patient and consistent.","zh":"如果學習較慢，教學應有耐性並保持一致。"},{"en":"The phrase describes pace, not worth or potential.","zh":"這個片語描述速度，而不是價值或潛能。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":16},{"front":"limited capacity to learn","meaning":"有限的學習能力","examples":[{"en":"They may have a limited capacity to learn.","zh":"他們可能有有限的學習能力。"},{"en":"Limited capacity to learn means reduced ability to learn certain information or skills without support.","zh":"limited capacity to learn 指在沒有支援下學習某些資訊或技能的能力較有限。"},{"en":"A person with limited capacity to learn may still improve through clear routines and practice.","zh":"有有限學習能力的人仍可透過清晰常規和練習進步。"},{"en":"If learning capacity is limited, goals should be realistic and meaningful.","zh":"如果學習能力有限，目標應現實而有意義。"},{"en":"The phrase should be used carefully and respectfully.","zh":"這個片語應謹慎而尊重地使用。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":16},{"front":"have difficulty managing","meaning":"難以處理","examples":[{"en":"Some people have difficulty managing ordinary daily activities.","zh":"有些人難以處理普通日常活動。"},{"en":"Have difficulty managing means find it hard to handle or organise something successfully.","zh":"have difficulty managing 指難以成功處理或組織某事。"},{"en":"A student may have difficulty managing homework if there are no clear deadlines.","zh":"如果沒有清晰期限，學生可能難以處理功課。"},{"en":"If someone has difficulty managing daily tasks, visual reminders may help.","zh":"如果某人難以處理日常任務，視覺提示可能有幫助。"},{"en":"The phrase focuses on practical struggle, not unwillingness.","zh":"這個片語集中於實際困難，而不是不願意。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":16},{"front":"ordinary activities of daily living","meaning":"日常生活活動","examples":[{"en":"Some people need support with ordinary activities of daily living.","zh":"有些人需要在日常生活活動上獲得支援。"},{"en":"Ordinary activities of daily living are basic everyday tasks such as eating, washing, dressing, and moving around.","zh":"ordinary activities of daily living 指進食、洗澡、穿衣和走動等基本日常任務。"},{"en":"Care workers help older adults with ordinary activities of daily living.","zh":"護理員幫助長者處理日常生活活動。"},{"en":"If these activities become difficult, a person’s independence may decrease.","zh":"如果這些活動變得困難，一個人的獨立能力可能下降。"},{"en":"The phrase refers to practical daily tasks needed for life.","zh":"這個片語指生活所需的實際日常任務。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":16},{"front":"understanding the behaviour of others","meaning":"理解他人的行為","examples":[{"en":"They may have difficulty understanding the behaviour of others.","zh":"他們可能難以理解他人的行為。"},{"en":"Understanding the behaviour of others means recognising what other people are doing, feeling, or intending.","zh":"understanding the behaviour of others 指識別別人在做甚麼、感受甚麼或打算甚麼。"},{"en":"A child may need help understanding why a classmate is upset or angry.","zh":"孩子可能需要幫助理解同學為何不開心或生氣。"},{"en":"If someone misunderstands others’ behaviour, social situations can become confusing.","zh":"如果某人誤解他人行為，社交情境可能變得令人困惑。"},{"en":"The phrase focuses on interpreting people’s actions and reactions.","zh":"這個片語集中於解讀人的行動和反應。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":16},{"front":"determining their own appropriate social responses","meaning":"判斷自己合適的社交反應","examples":[{"en":"They may need support in determining appropriate social responses.","zh":"他們可能需要支援去判斷合適的社交反應。"},{"en":"Determining appropriate social responses means deciding how to react politely and safely in social situations.","zh":"determining appropriate social responses 指在社交情境中決定如何禮貌且安全地回應。"},{"en":"A student may need help deciding how to respond when someone takes their pencil.","zh":"當有人拿走鉛筆時，學生可能需要幫助判斷如何回應。"},{"en":"If social responses are hard to judge, role-play and clear examples can help.","zh":"如果社交反應難以判斷，角色扮演和清晰例子可以幫忙。"},{"en":"The phrase focuses on choosing suitable behaviour with others.","zh":"這個片語集中於選擇與他人相處的合適行為。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":16},{"front":"adaptive behaviour","meaning":"適應行為","examples":[{"en":"Adaptive behaviour includes daily living and social-response skills.","zh":"適應行為包括日常生活和社交反應技能。"},{"en":"Adaptive behaviour means practical behaviour that helps a person manage daily life and social situations.","zh":"adaptive behaviour 指幫助一個人處理日常生活和社交情境的實用行為。"},{"en":"Crossing roads safely and asking for help are examples of adaptive behaviour.","zh":"安全過馬路和尋求幫助都是適應行為的例子。"},{"en":"If adaptive behaviour improves, a person may become more independent.","zh":"如果適應行為改善，一個人可能變得更獨立。"},{"en":"The phrase describes useful real-life functioning.","zh":"這個片語描述有用的真實生活功能。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":17},{"front":"grow into adults with","meaning":"成長為有……的成年人","examples":[{"en":"Children with intellectual disabilities grow into adults with intellectual disabilities.","zh":"有智力障礙的兒童會成長為有智力障礙的成年人。"},{"en":"Grow into adults with means become adults who continue to have a particular condition or characteristic.","zh":"grow into adults with 指成長為仍有某種情況或特徵的成年人。"},{"en":"Children with strong reading habits often grow into adults with a love of books.","zh":"有強閱讀習慣的孩子常成長為熱愛書本的成年人。"},{"en":"If children grow into adults with support needs, services should plan for adulthood too.","zh":"如果兒童會成長為有支援需要的成年人，服務也應為成年期規劃。"},{"en":"The phrase reminds readers that childhood conditions do not make someone an eternal child.","zh":"這個片語提醒讀者，童年情況不代表某人是永遠的小孩。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":17},{"front":"eternal children","meaning":"永遠的小孩","examples":[{"en":"Adults with intellectual disabilities should not be treated as eternal children.","zh":"有智力障礙的成年人不應被視為永遠的小孩。"},{"en":"Eternal children means adults wrongly viewed as if they will always remain children.","zh":"eternal children 指成年人被錯誤看成永遠停留在兒童狀態。"},{"en":"Speaking to an adult in a childish voice can wrongly treat them as an eternal child.","zh":"用幼稚語氣對成年人說話，可能錯誤地把他們當成永遠的小孩。"},{"en":"If adults are treated as eternal children, their dignity and choices may be ignored.","zh":"如果成年人被視為永遠的小孩，其尊嚴和選擇可能被忽視。"},{"en":"The phrase criticises patronising attitudes.","zh":"這個片語批評居高臨下的態度。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":17},{"front":"constitute one of the largest groups of","meaning":"構成……中最大的群體之一","examples":[{"en":"People with intellectual disabilities constitute one of the largest groups of citizens with disabilities.","zh":"有智力障礙的人士構成殘疾公民中最大的群體之一。"},{"en":"Constitute one of the largest groups of means form one of the biggest categories within a wider population.","zh":"constitute one of the largest groups of 指構成更大人口中最大類別之一。"},{"en":"Older adults may constitute one of the largest groups of public healthcare users.","zh":"長者可能構成公共醫療使用者中最大的群體之一。"},{"en":"If a group is large, services and policies must consider its needs seriously.","zh":"如果一個群體龐大，服務和政策必須認真考慮其需要。"},{"en":"The phrase is formal and used for describing population groups.","zh":"這個片語較正式，用於描述人口群體。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":17},{"front":"citizens with disabilities","meaning":"殘疾公民；有殘疾的人士","examples":[{"en":"The passage discusses citizens with disabilities around the world.","zh":"文章討論世界各地有殘疾的人士。"},{"en":"Citizens with disabilities are members of society who have disabilities and rights as citizens.","zh":"citizens with disabilities 指有殘疾並作為公民享有權利的社會成員。"},{"en":"Public buildings should be accessible to citizens with disabilities.","zh":"公共建築應方便殘疾公民使用。"},{"en":"If services ignore citizens with disabilities, equal participation becomes difficult.","zh":"如果服務忽視有殘疾的人士，平等參與就變得困難。"},{"en":"The phrase emphasises both disability and civic belonging.","zh":"這個片語同時強調殘疾和公民身份。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":17},{"front":"an estimated","meaning":"估計有","examples":[{"en":"There are an estimated 156 million individuals with intellectual disabilities.","zh":"估計有1.56億名有智力障礙的人士。"},{"en":"An estimated means approximately calculated, not counted exactly.","zh":"an estimated 指大約計算得出，而不是精確點算。"},{"en":"An estimated 500 students attended the school fair.","zh":"估計有500名學生參加學校市集。"},{"en":"If a number is estimated, it gives a useful scale but may not be exact.","zh":"如果數字是估計，它提供有用規模，但未必精確。"},{"en":"The phrase introduces an approximate figure.","zh":"這個片語引出大約數字。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":17},{"front":"cut across lines of","meaning":"跨越……界線","examples":[{"en":"Intellectual disability cuts across lines of race, education and background.","zh":"智力障礙跨越種族、教育和背景界線。"},{"en":"Cut across lines of means occur across different categories rather than staying within one group.","zh":"cut across lines of 指跨越不同類別出現，而不是只限於一個群體。"},{"en":"Stress can cut across lines of age, income, and job type.","zh":"壓力可以跨越年齡、收入和工作類型界線。"},{"en":"If a condition cuts across social lines, it can affect many kinds of people.","zh":"如果某情況跨越社會界線，它可以影響許多類型的人。"},{"en":"The phrase shows that boundaries do not limit the issue.","zh":"這個片語顯示界線不會限制該問題。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":17},{"front":"social or economic background","meaning":"社會或經濟背景","examples":[{"en":"The condition can occur regardless of social or economic background.","zh":"這種情況可以不論社會或經濟背景而發生。"},{"en":"Social or economic background means a person’s family, community, education, income, and class situation.","zh":"social or economic background 指一個人的家庭、社區、教育、收入和階層情況。"},{"en":"Students from different social or economic backgrounds may need different types of support.","zh":"來自不同社會或經濟背景的學生可能需要不同支援。"},{"en":"If a condition occurs across backgrounds, it should not be blamed on one social group.","zh":"如果某情況跨背景發生，就不應歸咎於某一社會群體。"},{"en":"The phrase describes where people come from socially and financially.","zh":"這個片語描述人們在社會和財政上來自何處。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":17},{"front":"occur in anyone","meaning":"發生於任何人身上","examples":[{"en":"Intellectual disability can occur in anyone.","zh":"智力障礙可以發生於任何人身上。"},{"en":"Occur in anyone means happen to any person, regardless of background.","zh":"occur in anyone 指不論背景，任何人都可能出現某情況。"},{"en":"A learning difficulty can occur in anyone, including students from supportive families.","zh":"學習困難可以發生於任何人身上，包括來自支援良好家庭的學生。"},{"en":"If a condition can occur in anyone, stereotypes about who is affected are misleading.","zh":"如果某情況可以發生於任何人身上，關於受影響者的刻板印象就具誤導性。"},{"en":"The phrase stresses broad possibility.","zh":"這個片語強調廣泛可能性。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":17},{"front":"hereditary components","meaning":"遺傳因素","examples":[{"en":"Hereditary components account for only a fraction of cases.","zh":"遺傳因素只佔一小部分個案。"},{"en":"Hereditary components are genetic factors passed from parents to children.","zh":"hereditary components 指由父母傳給子女的遺傳因素。"},{"en":"A doctor may ask about family history to check hereditary components of a condition.","zh":"醫生可能詢問家族病史，以檢查某情況的遺傳因素。"},{"en":"If hereditary factors explain only some cases, other causes must also be considered.","zh":"如果遺傳因素只解釋部分個案，就也必須考慮其他成因。"},{"en":"The phrase refers to inherited biological factors.","zh":"這個片語指遺傳的生物因素。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":17},{"front":"account for","meaning":"佔；解釋","examples":[{"en":"Hereditary factors account for only a fraction of cases.","zh":"遺傳因素只解釋一小部分個案。"},{"en":"Account for means explain, make up, or be responsible for a particular amount or result.","zh":"account for 指解釋、構成或負責某個數量或結果。"},{"en":"Rent may account for half of a student’s monthly spending.","zh":"租金可能佔學生每月開支的一半。"},{"en":"If one cause accounts for only a small number of cases, other causes remain important.","zh":"如果一個原因只解釋少量個案，其他原因仍然重要。"},{"en":"The phrase connects a cause or category with a proportion.","zh":"這個片語把原因或類別與比例連接起來。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":18},{"front":"only a fraction of","meaning":"只佔一小部分","examples":[{"en":"Inherited causes account for only a fraction of cases.","zh":"遺傳成因只佔一小部分個案。"},{"en":"Only a fraction of means only a small part of the whole.","zh":"only a fraction of 指整體中只有很小一部分。"},{"en":"Only a fraction of students arrived late after the timetable changed.","zh":"時間表改變後，只有一小部分學生遲到。"},{"en":"If only a fraction of cases are inherited, most cases have other or unknown causes.","zh":"如果只有一小部分個案是遺傳的，大多數個案就有其他或未知成因。"},{"en":"The phrase stresses a small proportion.","zh":"這個片語強調小比例。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":18},{"front":"well over","meaning":"遠超過","examples":[{"en":"There are well over 350 causes of intellectual disability.","zh":"智力障礙的成因遠超過350種。"},{"en":"Well over means much more than a stated number.","zh":"well over 指遠多於某個指定數字。"},{"en":"The school library has well over 10,000 books.","zh":"學校圖書館藏書遠超過一萬本。"},{"en":"If there are well over 350 causes, the condition cannot be explained by one simple reason.","zh":"如果成因遠超過350種，這種情況就不能由單一簡單原因解釋。"},{"en":"The phrase emphasises that the number is clearly above the figure given.","zh":"這個片語強調數字明顯高於所給數目。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":18},{"front":"three-quarters of the cases","meaning":"四分之三的個案","examples":[{"en":"In three-quarters of the cases, the specific cause is unknown.","zh":"在四分之三的個案中，具體成因未知。"},{"en":"Three-quarters of the cases means 75 percent of the cases.","zh":"three-quarters of the cases 指75%的個案。"},{"en":"If three-quarters of the class passes, most students have met the standard.","zh":"如果全班四分之三合格，大多數學生已達標。"},{"en":"If three-quarters of cases have unknown causes, certainty is limited.","zh":"如果四分之三個案成因未知，確定性就有限。"},{"en":"The phrase gives a large proportion of a total.","zh":"這個片語給出整體中的大比例。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":18},{"front":"the specific cause","meaning":"具體成因","examples":[{"en":"The specific cause is unknown in many cases.","zh":"許多個案中的具體成因未知。"},{"en":"The specific cause means the exact reason why something happened.","zh":"the specific cause 指某事發生的確切原因。"},{"en":"Doctors may not always know the specific cause of a patient’s symptoms at first.","zh":"醫生起初未必總是知道病人症狀的具體成因。"},{"en":"If the specific cause is unknown, support may focus on needs rather than origin.","zh":"如果具體成因未知，支援可能集中於需要，而不是起源。"},{"en":"The phrase asks for the exact cause, not a general category.","zh":"這個片語詢問確切原因，而不是一般類別。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":18},{"front":"mild disabilities","meaning":"輕度障礙","examples":[{"en":"About 87 per cent of people with intellectual disabilities have mild disabilities.","zh":"約87%的有智力障礙人士有輕度障礙。"},{"en":"Mild disabilities are disabilities that cause some limitations but may allow considerable independence with support.","zh":"mild disabilities 指造成一些限制，但在支援下仍可有相當獨立能力的障礙。"},{"en":"A student with mild disabilities may attend regular classes with suitable adjustments.","zh":"有輕度障礙的學生可能在適當調整下就讀普通課堂。"},{"en":"If a disability is mild, the person may still need understanding and practical support.","zh":"如果障礙是輕度的，該人士仍可能需要理解和實際支援。"},{"en":"The phrase describes degree, not the person’s value.","zh":"這個片語描述程度，而不是人的價值。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":18},{"front":"in many respects","meaning":"在許多方面","examples":[{"en":"In many respects, they are indistinguishable from people without intellectual disabilities.","zh":"在許多方面，他們與沒有智力障礙的人難以區分。"},{"en":"In many respects means in many ways or aspects.","zh":"in many respects 指在許多方面或層面上。"},{"en":"In many respects, online lessons are similar to classroom lessons because both need attention and practice.","zh":"在許多方面，網上課堂與實體課堂相似，因為兩者都需要專注和練習。"},{"en":"If people are similar in many respects, one label should not define everything about them.","zh":"如果人們在許多方面相似，一個標籤不應定義他們的一切。"},{"en":"The phrase shows that comparison has several dimensions.","zh":"這個片語顯示比較有多個層面。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":18},{"front":"indistinguishable from","meaning":"與……難以區分","examples":[{"en":"Many people with mild disabilities are indistinguishable from others in daily life.","zh":"許多有輕度障礙的人在日常生活中與其他人難以區分。"},{"en":"Indistinguishable from means so similar that it is hard to tell the difference.","zh":"indistinguishable from 指非常相似，以致難以分辨差異。"},{"en":"A high-quality copy may be indistinguishable from the original to ordinary viewers.","zh":"高質複製品對普通觀眾而言可能與原件難以區分。"},{"en":"If two students behave similarly in class, one may be indistinguishable from the other in daily routines.","zh":"如果兩名學生在課堂上行為相似，一人在日常常規中可能與另一人難以區分。"},{"en":"The phrase describes visible similarity, not inner identity.","zh":"這個片語描述可見相似，而不是內在身份。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":18},{"front":"agree with the information given in","meaning":"與……中提供的資料一致","examples":[{"en":"The statements must agree with the information given in the reading passage.","zh":"這些陳述必須與閱讀文章中提供的資料一致。"},{"en":"Agree with the information given in means match what the source text clearly says.","zh":"agree with the information given in 指與來源文本清楚說明的內容相符。"},{"en":"In a reading test, an answer must agree with the information given in the passage, not outside knowledge.","zh":"在閱讀測驗中，答案必須與文章中提供的資料一致，而不是外部知識。"},{"en":"If a statement changes a number or condition, it may no longer agree with the text.","zh":"如果陳述改變數字或條件，它可能不再與文本一致。"},{"en":"The phrase is common in TRUE, FALSE, NOT GIVEN questions.","zh":"這個片語常見於 TRUE、FALSE、NOT GIVEN 題。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":18},{"front":"write TRUE if","meaning":"如……則寫TRUE","examples":[{"en":"Students write TRUE if the statement agrees with the information.","zh":"如果陳述與資料一致，學生寫 TRUE。"},{"en":"Write TRUE if means choose TRUE only under a stated condition.","zh":"write TRUE if 指只有在指定條件成立時才選 TRUE。"},{"en":"In a quiz, students write TRUE if the sentence matches the passage exactly.","zh":"在小測中，如果句子與文章完全相符，學生寫 TRUE。"},{"en":"If the passage supports the statement, TRUE is the correct response.","zh":"如果文章支持該陳述，TRUE 就是正確回答。"},{"en":"The phrase gives a clear exam instruction.","zh":"這個片語給出清晰考試指示。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":18},{"front":"contradicts the information","meaning":"與資料矛盾","examples":[{"en":"A statement is false if it contradicts the information in the passage.","zh":"如果陳述與文章資料矛盾，它就是錯誤。"},{"en":"Contradicts the information means says the opposite of what the text states.","zh":"contradicts the information 指說出與文本陳述相反的內容。"},{"en":"If a notice says the event starts at 9, “it starts at 10” contradicts the information.","zh":"如果通告說活動九點開始，「活動十點開始」就與資料矛盾。"},{"en":"If a statement contradicts the passage, students should not choose TRUE.","zh":"如果陳述與文章矛盾，學生不應選 TRUE。"},{"en":"The phrase marks direct conflict with the source.","zh":"這個片語標示與來源直接衝突。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":19},{"front":"there is no information on this","meaning":"文中沒有相關資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果文中沒有相關資料，學生寫 NOT GIVEN。"},{"en":"There is no information on this means the passage does not provide enough detail to decide.","zh":"there is no information on this 指文章沒有提供足夠細節作判斷。"},{"en":"If a passage mentions athletes but not their favourite sports, there is no information on this point.","zh":"如果文章提到運動員但沒有提到他們最喜歡的運動，這一點就沒有相關資料。"},{"en":"When there is no information, students should not guess from common knowledge.","zh":"當沒有資料時，學生不應從常識猜測。"},{"en":"The phrase signals a NOT GIVEN situation.","zh":"這個片語表示 NOT GIVEN 情況。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":19},{"front":"take part in","meaning":"參加","examples":[{"en":"An athlete must meet the conditions to take part in the Special Olympics.","zh":"運動員必須符合條件才能參加特殊奧運會。"},{"en":"Take part in means participate in or join an activity.","zh":"take part in 指參與或加入某活動。"},{"en":"Students may take part in a school debate to practise speaking.","zh":"學生可能參加學校辯論來練習說話。"},{"en":"If someone takes part regularly, they can build confidence and skill.","zh":"如果某人定期參加，就能建立信心和技能。"},{"en":"The phrase is simple and common in school, sport, and community contexts.","zh":"這個片語簡單常見，用於學校、運動和社區情境。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":19},{"front":"below-average intellectual functioning","meaning":"低於平均水平的智力功能","examples":[{"en":"The statement refers to below-average intellectual functioning.","zh":"該陳述提到低於平均水平的智力功能。"},{"en":"Below-average intellectual functioning means intellectual ability measured below the usual range for a person’s age group.","zh":"below-average intellectual functioning 指智力能力被量度為低於同齡人的一般範圍。"},{"en":"A psychologist may assess below-average intellectual functioning through standardised tests and observation.","zh":"心理學家可能透過標準化測驗和觀察評估低於平均水平的智力功能。"},{"en":"If below-average functioning affects daily skills, support may be needed at school or home.","zh":"如果低於平均水平的功能影響日常技能，學校或家庭可能需要支援。"},{"en":"The phrase should be used in an assessment context, not as an insult.","zh":"這個片語應用於評估情境，而不是用作侮辱。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":19},{"front":"limitations in at least two adaptive-skill areas","meaning":"至少兩個適應技能範疇的限制","examples":[{"en":"The definition mentions limitations in at least two adaptive-skill areas.","zh":"該定義提到至少兩個適應技能範疇的限制。"},{"en":"Limitations in at least two adaptive-skill areas means difficulties in two or more practical life-skill categories.","zh":"limitations in at least two adaptive-skill areas 指在兩個或以上實用生活技能類別中有困難。"},{"en":"A person may have limitations in communication and self-care but strengths in memory.","zh":"一個人可能在溝通和自我照顧方面有限制，但在記憶方面有強項。"},{"en":"If limitations appear in several adaptive areas, support planning should be broad enough.","zh":"如果限制出現在幾個適應範疇，支援規劃應足夠全面。"},{"en":"The phrase sets a minimum number of affected skill areas.","zh":"這個片語設定受影響技能範疇的最低數目。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":19},{"front":"need written permission","meaning":"需要書面許可","examples":[{"en":"The statement asks whether all participants need written permission from a guardian.","zh":"該陳述問是否所有參加者都需要監護人的書面許可。"},{"en":"Need written permission means require formal approval in writing before doing something.","zh":"need written permission 指做某事前需要正式書面批准。"},{"en":"Students often need written permission from parents before joining an overnight camp.","zh":"學生參加過夜營前通常需要家長書面許可。"},{"en":"If written permission is missing, organisers may not allow participation.","zh":"如果缺少書面許可，主辦方可能不允許參與。"},{"en":"The phrase focuses on documented consent.","zh":"這個片語集中於文件化同意。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":19},{"front":"parent or guardian","meaning":"父母或監護人","examples":[{"en":"A parent or guardian may need to sign for a minor athlete.","zh":"父母或監護人可能需要為未成年運動員簽署。"},{"en":"A parent or guardian is an adult who has responsibility for a child or dependent person.","zh":"parent or guardian 指對兒童或受照顧人士負有責任的成人。"},{"en":"Schools usually contact a parent or guardian in an emergency.","zh":"學校通常在緊急情況下聯絡父母或監護人。"},{"en":"If an athlete is a minor, a parent or guardian may need to approve high-risk activities.","zh":"如果運動員是未成年人，父母或監護人可能需要批准高風險活動。"},{"en":"The phrase is common in consent forms and official notices.","zh":"這個片語常見於同意書和官方通知。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":19},{"front":"excel in one’s chosen field","meaning":"在自己選擇的領域表現出色","examples":[{"en":"The question asks whether participants with Down syndrome often excel in their chosen field.","zh":"題目問唐氏綜合症參加者是否常在自己選擇的領域表現出色。"},{"en":"Excel in one’s chosen field means perform very well in the activity or area one has selected.","zh":"excel in one’s chosen field 指在自己選擇的活動或範疇中表現非常好。"},{"en":"A student may excel in art even if they struggle with mathematics.","zh":"學生即使數學有困難，也可能在藝術方面表現出色。"},{"en":"If people receive good coaching, they may excel in the field they enjoy most.","zh":"如果人們獲得良好指導，可能在自己最喜歡的領域表現出色。"},{"en":"The phrase focuses on strong achievement in a selected area.","zh":"這個片語集中於在選定範疇中的強表現。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":19},{"front":"athletic activity","meaning":"體育活動","examples":[{"en":"The statement refers to a chosen field of athletic activity.","zh":"該陳述提到自己選擇的體育活動領域。"},{"en":"Athletic activity means physical activity connected with sport, fitness, or competition.","zh":"athletic activity 指與運動、體能或比賽有關的身體活動。"},{"en":"Running, swimming, and jumping are common athletic activities in school sports.","zh":"跑步、游泳和跳躍都是學校運動中常見的體育活動。"},{"en":"If an athletic activity places stress on the neck, medical advice may be needed.","zh":"如果體育活動對頸部造成壓力，可能需要醫療建議。"},{"en":"The phrase refers to physical sport-related activity.","zh":"這個片語指與運動有關的身體活動。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":19},{"front":"swimming events","meaning":"游泳項目","examples":[{"en":"The question asks whether people with Down syndrome cannot participate in any swimming events.","zh":"題目問唐氏綜合症人士是否不能參加任何游泳項目。"},{"en":"Swimming events are sports competitions or activities that take place in water.","zh":"swimming events 指在水中進行的體育比賽或活動。"},{"en":"Freestyle races and relay races are swimming events.","zh":"自由泳比賽和接力賽都是游泳項目。"},{"en":"If only diving starts or butterfly stroke are restricted, not all swimming events are banned.","zh":"如果只限制跳水式起步或蝶泳，並不代表所有游泳項目都被禁止。"},{"en":"The phrase refers to different parts of swimming competitions.","zh":"這個片語指游泳比賽中的不同項目。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":19},{"front":"be at risk of damage","meaning":"有受損風險","examples":[{"en":"An athlete’s neck may be at risk of damage in certain sports.","zh":"運動員的頸部在某些運動中可能有受損風險。"},{"en":"Be at risk of damage means be in a situation where harm or injury may happen.","zh":"be at risk of damage 指處於可能受傷或受損的情況。"},{"en":"A phone is at risk of damage if it is left in heavy rain.","zh":"如果手機被留在大雨中，就有受損風險。"},{"en":"If the neck is at risk of damage, sports rules may restrict certain movements.","zh":"如果頸部有受損風險，體育規則可能限制某些動作。"},{"en":"The phrase warns that harm is possible.","zh":"這個片語警告可能發生傷害。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":20},{"front":"in certain sports","meaning":"在某些運動中","examples":[{"en":"Some medical risks arise in certain sports.","zh":"某些醫療風險出現在某些運動中。"},{"en":"In certain sports means in particular sports, not in all sports.","zh":"in certain sports 指在特定運動中，而不是所有運動中。"},{"en":"Knee injuries are more common in certain sports that involve jumping and turning.","zh":"在涉及跳躍和轉向的某些運動中，膝傷較常見。"},{"en":"If risk appears only in certain sports, athletes may still join safer alternatives.","zh":"如果風險只出現在某些運動中，運動員仍可參加較安全替代項目。"},{"en":"The phrase narrows the discussion to selected sports.","zh":"這個片語把討論縮窄至指定運動。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":20},{"front":"improve communication and social skills","meaning":"改善溝通及社交技巧","examples":[{"en":"The statement asks whether sport improves communication and social skills.","zh":"該陳述問運動是否改善溝通及社交技巧。"},{"en":"Improve communication and social skills means help people express themselves and interact better with others.","zh":"improve communication and social skills 指幫助人們更好表達自己和與他人互動。"},{"en":"Team games can improve communication and social skills because players must listen and cooperate.","zh":"團隊遊戲可以改善溝通及社交技巧，因為參賽者必須聆聽和合作。"},{"en":"If a programme builds confidence, participants may speak more clearly and respond better socially.","zh":"如果計劃建立信心，參加者可能說得更清楚並在社交上回應得更好。"},{"en":"The phrase connects activity with interpersonal development.","zh":"這個片語把活動與人際發展連接起來。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":20},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Candidates must choose the correct letter, A, B, C or D.","zh":"考生必須選出正確字母 A、B、C 或 D。"},{"en":"Choose the correct letter means select the option letter that matches the right answer.","zh":"choose the correct letter 指選出與正確答案相符的選項字母。"},{"en":"In a multiple-choice question, students may know the answer but still need to write the correct letter.","zh":"在多項選擇題中，學生可能知道答案，但仍需寫出正確字母。"},{"en":"If a candidate writes the wrong letter, the answer may be marked wrong even if they understood the idea.","zh":"如果考生寫錯字母，即使理解意思也可能被判錯。"},{"en":"The phrase is a standard exam instruction.","zh":"這個片語是標準考試指示。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":20},{"front":"one objective of","meaning":"……的其中一個目標","examples":[{"en":"The question asks about one objective of the Special Olympics document.","zh":"題目問特殊奧運會文件的其中一個目標。"},{"en":"One objective of means one purpose or goal of something.","zh":"one objective of 指某事物的其中一個目的或目標。"},{"en":"One objective of a school newsletter is to keep parents informed.","zh":"學校通訊的其中一個目標是讓家長知情。"},{"en":"If a document has several objectives, a question may ask for only one of them.","zh":"如果文件有幾個目標，題目可能只問其中一個。"},{"en":"The phrase focuses on purpose.","zh":"這個片語集中於目的。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":20},{"front":"inform the public about","meaning":"向公眾提供關於……的資料","examples":[{"en":"The document may inform the public about participation conditions.","zh":"文件可能向公眾提供關於參加條件的資料。"},{"en":"Inform the public about means give people information on a topic.","zh":"inform the public about 指向人們提供某主題的資訊。"},{"en":"Health posters inform the public about flu symptoms and prevention.","zh":"健康海報向公眾提供關於流感症狀和預防的資料。"},{"en":"If the public is informed clearly, misunderstandings may decrease.","zh":"如果公眾獲得清晰資訊，誤解可能減少。"},{"en":"The phrase describes communication from an organisation to ordinary people.","zh":"這個片語描述機構向普通人傳達資訊。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":20},{"front":"what they are to expect from","meaning":"他們可從……預期甚麼","examples":[{"en":"The option refers to what the public can expect from the Special Olympics.","zh":"該選項指公眾可從特殊奧運會預期甚麼。"},{"en":"What they are to expect from means what people should think will happen or be provided.","zh":"what they are to expect from 指人們應預期會發生或獲提供甚麼。"},{"en":"A course guide tells students what they are to expect from each lesson.","zh":"課程指南告訴學生每堂課可預期甚麼。"},{"en":"If expectations are clear, participants can prepare better.","zh":"如果期望清晰，參加者可以更好準備。"},{"en":"The phrase focuses on expected experience or benefit.","zh":"這個片語集中於預期經驗或好處。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":20},{"front":"provide information for","meaning":"為……提供資料","examples":[{"en":"The document provides information for future candidates.","zh":"文件為未來參加者提供資料。"},{"en":"Provide information for means give useful details to a particular group of people.","zh":"provide information for 指向某特定群體提供有用細節。"},{"en":"A school website provides information for new parents.","zh":"學校網站為新家長提供資料。"},{"en":"If information is provided for applicants, they can decide whether they qualify.","zh":"如果資料提供給申請者，他們就能決定自己是否符合資格。"},{"en":"The phrase identifies who the information is meant to help.","zh":"這個片語指出資料旨在幫助誰。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":20},{"front":"future candidates","meaning":"未來申請者；未來參加者","examples":[{"en":"Future candidates may read the document before applying.","zh":"未來參加者可能在申請前閱讀文件。"},{"en":"Future candidates are people who may apply or take part later.","zh":"future candidates 指日後可能申請或參與的人。"},{"en":"A university brochure gives future candidates information about entry requirements.","zh":"大學小冊子向未來申請者提供入學要求資料。"},{"en":"If future candidates understand the rules early, they can prepare documents properly.","zh":"如果未來申請者及早理解規則，就能妥善準備文件。"},{"en":"The phrase refers to possible applicants or participants.","zh":"這個片語指可能的申請者或參加者。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":20},{"front":"promote awareness","meaning":"提高意識","examples":[{"en":"The option says that the document promotes awareness of disability issues.","zh":"該選項說文件提高人們對殘疾議題的意識。"},{"en":"Promote awareness means help people understand and notice an issue more clearly.","zh":"promote awareness 指幫助人們更清楚理解和注意某議題。"},{"en":"A school campaign may promote awareness of bullying and mental health.","zh":"學校宣傳活動可能提高對欺凌和心理健康的意識。"},{"en":"If awareness increases, people may treat others more fairly and thoughtfully.","zh":"如果意識提高，人們可能更公平和周到地對待他人。"},{"en":"The phrase focuses on public understanding.","zh":"這個片語集中於公眾理解。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":20},{"front":"the general population","meaning":"一般大眾","examples":[{"en":"The option refers to awareness in the general population.","zh":"該選項指一般大眾的意識。"},{"en":"The general population means ordinary people as a whole, not a specialised group.","zh":"the general population 指普通人整體，而不是專門群體。"},{"en":"Public health messages are written for the general population, not only doctors.","zh":"公共健康訊息是寫給一般大眾，而不只是醫生。"},{"en":"If the general population understands disability better, social inclusion may improve.","zh":"如果一般大眾更理解殘疾，社會共融可能改善。"},{"en":"The phrase refers to the wider public.","zh":"這個片語指更廣泛公眾。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":21},{"front":"challenges faced by","meaning":"……所面對的挑戰","examples":[{"en":"The option mentions the challenges faced by people with disabilities.","zh":"該選項提到有殘疾的人士所面對的挑戰。"},{"en":"Challenges faced by means difficulties that a person or group has to deal with.","zh":"challenges faced by 指某人或群體必須處理的困難。"},{"en":"The challenges faced by new teachers include lesson planning and classroom management.","zh":"新老師所面對的挑戰包括備課和課室管理。"},{"en":"If challenges are understood, support can be designed more effectively.","zh":"如果挑戰被理解，支援就能更有效設計。"},{"en":"The phrase identifies who experiences the difficulties.","zh":"這個片語指出誰經歷這些困難。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":21},{"front":"people with disabilities","meaning":"有殘疾的人士","examples":[{"en":"The document discusses participation by people with disabilities.","zh":"文件討論有殘疾的人士的參與。"},{"en":"People with disabilities are individuals who have physical, intellectual, sensory, or other disabilities.","zh":"people with disabilities 指有身體、智力、感官或其他殘疾的人士。"},{"en":"Public transport should be designed so people with disabilities can use it safely.","zh":"公共交通應設計得讓有殘疾的人士安全使用。"},{"en":"If services include people with disabilities, communities become fairer.","zh":"如果服務包含有殘疾的人士，社區會更公平。"},{"en":"The phrase uses person-first language.","zh":"這個片語使用以人為本的語言。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":21},{"front":"list the problems","meaning":"列出問題","examples":[{"en":"The option says that the document lists the problems faced by people with disabilities.","zh":"該選項說文件列出有殘疾的人士所面對的問題。"},{"en":"List the problems means name several difficulties in an organised way.","zh":"list the problems 指有組織地列出幾個困難。"},{"en":"A teacher may ask students to list the problems in a story before suggesting solutions.","zh":"老師可能要求學生先列出故事中的問題，再提出解決方案。"},{"en":"If a report only lists problems, readers may still need advice on what to do next.","zh":"如果報告只列出問題，讀者可能仍需要下一步建議。"},{"en":"The phrase focuses on identifying issues one by one.","zh":"這個片語集中於逐一識別問題。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":21},{"front":"the majority of cases","meaning":"大多數個案","examples":[{"en":"The question asks whether the majority of cases are inherited.","zh":"題目問大多數個案是否屬於遺傳。"},{"en":"The majority of cases means more than half of all cases.","zh":"the majority of cases 指全部個案中超過一半。"},{"en":"In the majority of late submissions, students forgot the deadline rather than misunderstood the task.","zh":"在大多數遲交個案中，學生是忘記期限，而不是誤解任務。"},{"en":"If the majority of cases are not inherited, other explanations must be considered.","zh":"如果大多數個案不是遺傳，就必須考慮其他解釋。"},{"en":"The phrase describes the largest share of cases.","zh":"這個片語描述個案中的最大部分。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":21},{"front":"inherited","meaning":"遺傳的","examples":[{"en":"Only a fraction of intellectual disability cases are inherited.","zh":"只有一小部分智力障礙個案是遺傳的。"},{"en":"Inherited means passed from parents to children through genes.","zh":"inherited 指透過基因由父母傳給子女。"},{"en":"Some eye colours and health risks can be inherited.","zh":"有些眼睛顏色和健康風險可以是遺傳的。"},{"en":"If a condition is inherited, family history may help doctors understand it.","zh":"如果某情況是遺傳的，家族病史可能幫助醫生理解。"},{"en":"The word describes genetic passing, not learned behaviour.","zh":"這個詞描述基因傳遞，而不是後天學到的行為。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":21},{"front":"outnumber","meaning":"數量超過","examples":[{"en":"The option asks whether people with intellectual disabilities outnumber those with physical disabilities.","zh":"該選項問有智力障礙的人士數量是否超過身體殘疾人士。"},{"en":"Outnumber means be greater in number than another group.","zh":"outnumber 指在數量上多於另一群體。"},{"en":"In some classes, students who take the bus outnumber students who walk.","zh":"在一些班級中，乘巴士上學的學生數量超過步行學生。"},{"en":"If one group outnumbers another, it may need more services simply because it is larger.","zh":"如果一個群體數量超過另一群體，單因規模較大就可能需要更多服務。"},{"en":"The phrase compares group size.","zh":"這個片語比較群體大小。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":21},{"front":"physical disabilities","meaning":"身體殘疾","examples":[{"en":"The option compares intellectual disabilities with physical disabilities.","zh":"該選項把智力障礙與身體殘疾作比較。"},{"en":"Physical disabilities are disabilities that affect movement, body function, or physical access.","zh":"physical disabilities 指影響活動、身體功能或實體通達的殘疾。"},{"en":"A person with a physical disability may need ramps, lifts, or adapted equipment.","zh":"有身體殘疾的人可能需要斜道、升降機或改裝設備。"},{"en":"If buildings ignore physical disabilities, access becomes unfair.","zh":"如果建築物忽視身體殘疾，通達就變得不公平。"},{"en":"The phrase refers to bodily or mobility-related disabilities.","zh":"這個片語指與身體或行動能力有關的殘疾。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":21},{"front":"cannot be determined","meaning":"不能被確定","examples":[{"en":"In many cases, the cause cannot be determined.","zh":"在許多個案中，成因不能被確定。"},{"en":"Cannot be determined means cannot be identified or decided with available information.","zh":"cannot be determined 指不能以現有資料識別或決定。"},{"en":"If a student loses a book but no one saw what happened, the exact cause cannot be determined.","zh":"如果學生遺失書本但沒有人看見發生甚麼，確切原因不能被確定。"},{"en":"If a medical cause cannot be determined, support can still focus on current needs.","zh":"如果醫學成因不能被確定，支援仍可集中於目前需要。"},{"en":"The phrase shows uncertainty after investigation.","zh":"這個片語顯示調查後仍有不確定性。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":21},{"front":"be determined by","meaning":"由……決定","examples":[{"en":"The option asks whether the condition is determined by race or background.","zh":"該選項問這種情況是否由種族或背景決定。"},{"en":"Be determined by means be decided, controlled, or caused by something.","zh":"be determined by 指由某事決定、控制或造成。"},{"en":"A student’s final grade may be determined by exams, coursework, and attendance.","zh":"學生最終成績可能由考試、課業和出席率決定。"},{"en":"If a condition is not determined by background, it can occur across social groups.","zh":"如果某情況不是由背景決定，它就可以跨社會群體發生。"},{"en":"The phrase links a result with what controls it.","zh":"這個片語把結果與控制因素連接起來。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":21},{"front":"best describes","meaning":"最能形容","examples":[{"en":"The question asks which word best describes the participation policy.","zh":"題目問哪個詞最能形容參加政策。"},{"en":"Best describes means gives the most accurate or suitable description.","zh":"best describes 指給出最準確或最合適的描述。"},{"en":"In a vocabulary question, students choose the word that best describes the speaker’s feeling.","zh":"在詞彙題中，學生選出最能形容說話者感受的詞。"},{"en":"If several answers seem possible, the best one must match the passage most closely.","zh":"如果幾個答案看似可能，最佳答案必須最貼近文章。"},{"en":"The phrase asks for the most fitting description.","zh":"這個片語要求最合適描述。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":22},{"front":"participation policy","meaning":"參加政策","examples":[{"en":"The passage describes the Special Olympics participation policy.","zh":"文章描述特殊奧運會的參加政策。"},{"en":"A participation policy is a set of rules about who may join and under what conditions.","zh":"participation policy 是關於誰可以參加以及在甚麼條件下參加的一套規則。"},{"en":"A school club’s participation policy may explain age limits, fees, and safety rules.","zh":"學校學會的參加政策可能解釋年齡限制、費用和安全規則。"},{"en":"If a participation policy is fair, it protects access while managing risk.","zh":"如果參加政策公平，它會在管理風險的同時保護參與權。"},{"en":"The phrase refers to official rules for joining.","zh":"這個片語指加入活動的官方規則。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":22},{"front":"inconsistent","meaning":"不一致的","examples":[{"en":"An inconsistent policy applies rules unevenly.","zh":"不一致的政策會不平均地套用規則。"},{"en":"Inconsistent means not staying the same or not applying rules in a steady way.","zh":"inconsistent 指沒有保持相同，或沒有穩定地應用規則。"},{"en":"A teacher is inconsistent if homework is accepted late for some students but not others without reason.","zh":"如果老師無原因地接受部分學生遲交功課卻拒絕其他人，就是不一致。"},{"en":"If a policy is inconsistent, people may feel the process is unfair.","zh":"如果政策不一致，人們可能覺得程序不公平。"},{"en":"The word describes lack of regularity or fairness.","zh":"這個詞描述缺乏規律或公平。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":22},{"front":"ambiguous","meaning":"含糊不清的","examples":[{"en":"An ambiguous policy is unclear or open to different interpretations.","zh":"含糊不清的政策是不清楚或可有不同解讀的。"},{"en":"Ambiguous means having more than one possible meaning or not being clear enough.","zh":"ambiguous 指有多於一個可能意思，或不夠清楚。"},{"en":"An ambiguous exam instruction can make students unsure how many words to write.","zh":"含糊不清的考試指示可令學生不確定要寫多少字。"},{"en":"If rules are ambiguous, different organisers may apply them differently.","zh":"如果規則含糊不清，不同主辦方可能以不同方式應用。"},{"en":"The word describes unclear meaning.","zh":"這個詞描述意思不清楚。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":22},{"front":"controversial","meaning":"具爭議性的","examples":[{"en":"A controversial policy causes disagreement.","zh":"具爭議性的政策會引起分歧。"},{"en":"Controversial means likely to cause public debate or strong disagreement.","zh":"controversial 指可能引起公開討論或強烈分歧。"},{"en":"A school phone ban may be controversial if parents and students disagree about it.","zh":"如果家長和學生對手機禁令意見不同，它可能具爭議性。"},{"en":"If a policy affects rights or safety, it may become controversial.","zh":"如果政策影響權利或安全，它可能變得具爭議性。"},{"en":"The word describes disagreement, not simply difficulty.","zh":"這個詞描述分歧，而不只是困難。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":22},{"front":"non-discriminatory","meaning":"非歧視性的","examples":[{"en":"The policy is intended to be non-discriminatory.","zh":"該政策旨在是非歧視性的。"},{"en":"Non-discriminatory means treating people fairly without excluding them because of identity or background.","zh":"non-discriminatory 指公平對待人們，不因身份或背景而排除他們。"},{"en":"A non-discriminatory school policy gives students equal access regardless of race or disability.","zh":"非歧視性的學校政策會不論種族或殘疾給予學生平等機會。"},{"en":"If a rule is non-discriminatory, it should be applied fairly to all relevant people.","zh":"如果規則是非歧視性的，就應公平適用於所有相關人士。"},{"en":"The word describes fairness and equal treatment.","zh":"這個詞描述公平和平等對待。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":22},{"front":"facts relating to","meaning":"與……有關的事實","examples":[{"en":"The question asks for facts relating to Down syndrome.","zh":"題目要求與唐氏綜合症有關的事實。"},{"en":"Facts relating to means information connected with a particular topic.","zh":"facts relating to 指與某主題有關的資料。"},{"en":"A health leaflet may give facts relating to sleep, exercise, and diet.","zh":"健康單張可能提供與睡眠、運動和飲食有關的事實。"},{"en":"If a question asks for related facts, students should choose details supported by the passage.","zh":"如果題目要求相關事實，學生應選擇文章支持的細節。"},{"en":"The phrase points to relevant information.","zh":"這個片語指相關資訊。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":22},{"front":"one person in every seven","meaning":"每七人中約一人","examples":[{"en":"The option says that about one person in every seven may have the condition.","zh":"該選項說每七人中約一人可能有這種情況。"},{"en":"One person in every seven means roughly one out of seven people.","zh":"one person in every seven 指大約每七人中有一人。"},{"en":"If one person in every seven in a group needs help, support planning must be realistic.","zh":"如果一個群體中每七人約一人需要幫助，支援規劃必須實際。"},{"en":"A ratio like one in seven helps readers understand percentages more easily.","zh":"像七分之一這樣的比例，幫助讀者更容易理解百分比。"},{"en":"The phrase expresses a proportion in everyday language.","zh":"這個片語用日常語言表達比例。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":22},{"front":"winter competitions","meaning":"冬季比賽","examples":[{"en":"The option asks whether a person with Down syndrome cannot participate in winter competitions.","zh":"該選項問唐氏綜合症人士是否不能參加冬季比賽。"},{"en":"Winter competitions are sports events held in winter sports such as skiing or skating.","zh":"winter competitions 指滑雪或滑冰等冬季運動項目。"},{"en":"A school may hold winter competitions indoors if the weather is very cold.","zh":"如果天氣很冷，學校可能在室內舉行冬季比賽。"},{"en":"If only one winter sport is restricted, it does not mean all winter competitions are banned.","zh":"如果只限制一項冬季運動，並不代表所有冬季比賽都被禁止。"},{"en":"The phrase refers to seasonal or winter-sport events.","zh":"這個片語指季節性或冬季運動賽事。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":22},{"front":"minors with","meaning":"有……的未成年人","examples":[{"en":"Minors with atlantoaxial instability may need guardian approval for certain sports.","zh":"有寰樞椎不穩定的未成年人參加某些運動可能需要監護人批准。"},{"en":"Minors with means people under the legal adult age who have a particular condition or feature.","zh":"minors with 指未達法定成年年齡且有某種情況或特徵的人。"},{"en":"Minors with allergies may need special forms before a school trip.","zh":"有過敏的未成年人在學校旅行前可能需要特別表格。"},{"en":"If minors have medical risks, adults responsible for them must be informed.","zh":"如果未成年人有醫療風險，負責他們的成人必須知情。"},{"en":"The phrase combines age status with a condition.","zh":"這個片語結合年齡身份和某種情況。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":22},{"front":"need permission from","meaning":"需要得到……許可","examples":[{"en":"Some minors need permission from a guardian to participate.","zh":"有些未成年人需要得到監護人許可才能參與。"},{"en":"Need permission from means require approval from a particular person or authority.","zh":"need permission from 指需要某個人或權威批准。"},{"en":"Students may need permission from parents before joining an overnight camp.","zh":"學生參加過夜營前可能需要得到家長許可。"},{"en":"If permission is required but not given, participation may not be allowed.","zh":"如果需要許可但未獲批准，可能不允許參與。"},{"en":"The phrase identifies who must approve an action.","zh":"這個片語指出誰必須批准行動。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":23},{"front":"play soccer","meaning":"踢足球","examples":[{"en":"The option discusses whether a minor can play soccer.","zh":"該選項討論未成年人能否踢足球。"},{"en":"Play soccer means take part in the sport of football using feet to move the ball.","zh":"play soccer 指參與用腳控球的足球運動。"},{"en":"Children often play soccer in parks, school fields, or sports clubs.","zh":"孩子常在公園、學校球場或體育會踢足球。"},{"en":"If a sport does not directly stress the neck, it may be treated differently from restricted events.","zh":"如果某運動不直接對頸部造成壓力，它可能與受限制項目不同處理。"},{"en":"The phrase names a common team sport.","zh":"這個片語指一項常見團隊運動。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":23},{"front":"be unable to flex","meaning":"無法屈曲","examples":[{"en":"The option asks whether people with Down syndrome are unable to flex the upper spine.","zh":"該選項問唐氏綜合症人士是否無法屈曲上脊椎。"},{"en":"Be unable to flex means not be able to bend a body part.","zh":"be unable to flex 指不能彎曲某身體部位。"},{"en":"A patient may be unable to flex a knee after a serious injury.","zh":"嚴重受傷後，病人可能無法屈曲膝蓋。"},{"en":"If someone is unable to flex part of the spine, medical assessment is needed.","zh":"如果某人無法屈曲脊椎某部分，就需要醫療評估。"},{"en":"The phrase describes loss or absence of bending ability.","zh":"這個片語描述彎曲能力喪失或不存在。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":23},{"front":"wear a neck brace","meaning":"佩戴頸箍","examples":[{"en":"The option asks whether athletes need to wear a neck brace.","zh":"該選項問運動員是否需要佩戴頸箍。"},{"en":"Wear a neck brace means use a supportive device around the neck to limit movement or protect it.","zh":"wear a neck brace 指使用圍在頸部的支撐裝置，以限制活動或保護頸部。"},{"en":"After a car accident, a patient may wear a neck brace while doctors check for injury.","zh":"車禍後，病人在醫生檢查受傷前可能佩戴頸箍。"},{"en":"If the neck needs support, a brace may reduce movement and pressure.","zh":"如果頸部需要支撐，頸箍可以減少活動和壓力。"},{"en":"The phrase refers to a medical support device.","zh":"這個片語指醫療支撐裝置。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":23},{"front":"take part in sports","meaning":"參加運動","examples":[{"en":"Athletes may take part in sports that do not directly affect the neck.","zh":"運動員可以參加不直接影響頸部的運動。"},{"en":"Take part in sports means join physical activities, games, or competitions.","zh":"take part in sports 指加入體能活動、遊戲或比賽。"},{"en":"Students take part in sports to build fitness, teamwork, and confidence.","zh":"學生參加運動以建立體能、團隊合作和信心。"},{"en":"If a sport is safe for a person’s condition, participation may be encouraged.","zh":"如果某運動對一個人的情況安全，就可能鼓勵參與。"},{"en":"The phrase is a general way to describe sports participation.","zh":"這個片語是描述體育參與的一般說法。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":23},{"front":"directly affect","meaning":"直接影響","examples":[{"en":"Some sports directly affect the neck or spine.","zh":"有些運動會直接影響頸部或脊椎。"},{"en":"Directly affect means have an immediate or clear effect on something.","zh":"directly affect 指對某事物有即時或清楚影響。"},{"en":"Poor sleep can directly affect a student’s concentration the next morning.","zh":"睡眠不足可以在翌日早上直接影響學生專注力。"},{"en":"If a movement directly affects the neck, medical rules may treat it as higher risk.","zh":"如果某動作直接影響頸部，醫療規則可能把它視為較高風險。"},{"en":"The phrase shows a clear connection between cause and effect.","zh":"這個片語顯示原因與效果之間的清楚關係。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":23},{"front":"without any preconditions being fulfilled","meaning":"無須符合任何先決條件","examples":[{"en":"The option asks whether athletes may participate without any preconditions being fulfilled.","zh":"該選項問運動員是否可無須符合任何先決條件而參與。"},{"en":"Without any preconditions being fulfilled means without first meeting required conditions.","zh":"without any preconditions being fulfilled 指沒有先符合所需條件。"},{"en":"A student cannot join an exam without any preconditions being fulfilled, such as registration.","zh":"學生不能無須符合任何先決條件便參加考試，例如必須先報名。"},{"en":"If safety preconditions are not fulfilled, participation may be delayed or refused.","zh":"如果安全先決條件未被符合，參與可能被延遲或拒絕。"},{"en":"The phrase stresses that required steps must come first.","zh":"這個片語強調必要步驟必須先完成。"}],"source":"76 - Special Olympics Conditions of Participation.pdf","sourcePage":23}],"ielts/reading/passage-2/Practice 77":[{"front":"colour blindness","meaning":"色盲","examples":[{"en":"Colour blindness results from problems with certain colour-sensitive cells in the retina.","zh":"色盲由視網膜中某些感色細胞出現問題引起。"},{"en":"Colour blindness is a condition in which a person cannot see some colours in the usual way.","zh":"色盲是一種使人無法以一般方式看見某些顏色的狀況。"},{"en":"A colour-blind student may confuse red and green markers on a classroom chart.","zh":"色盲學生可能混淆課室圖表上的紅色和綠色標記。"},{"en":"If colour blindness affects daily tasks, labels and positions can help reduce mistakes.","zh":"如果色盲影響日常任務，標籤和位置可以幫助減少錯誤。"},{"en":"Colour blindness does not usually mean seeing no colour at all.","zh":"色盲通常不代表完全看不到顏色。"}],"source":"77 - Colour Blindness.pdf","sourcePage":1},{"front":"result from","meaning":"由……引起","examples":[{"en":"Colour blindness results from an absence or malfunction of colour-sensitive cells.","zh":"色盲由感色細胞缺失或功能異常引起。"},{"en":"Result from means be caused by something.","zh":"「result from」意思是由某事造成。"},{"en":"A headache may result from lack of sleep or too much screen time.","zh":"頭痛可能由睡眠不足或看屏幕太久引起。"},{"en":"If a problem results from damaged cells, treatment must deal with the cause.","zh":"如果問題由受損細胞引起，治療就必須處理成因。"},{"en":"This phrase clearly links an effect to its cause.","zh":"這個短語清楚把結果與原因連繫起來。"}],"source":"77 - Colour Blindness.pdf","sourcePage":1},{"front":"an absence or malfunction of","meaning":"……的缺失或功能異常","examples":[{"en":"Colour blindness may be caused by an absence or malfunction of cone cells.","zh":"色盲可能由視錐細胞缺失或功能異常造成。"},{"en":"An absence or malfunction of something means it is missing or not working properly.","zh":"「an absence or malfunction of」某物，意思是它缺失或無法正常運作。"},{"en":"A machine may fail because of an absence or malfunction of a key part.","zh":"機器可能因關鍵零件缺失或功能異常而失效。"},{"en":"If cone cells are absent or malfunctioning, colour signals may not reach the brain correctly.","zh":"如果視錐細胞缺失或功能異常，顏色訊號可能無法正確到達大腦。"},{"en":"The phrase covers both missing parts and faulty parts.","zh":"這個短語同時涵蓋零件缺失和零件故障。"}],"source":"77 - Colour Blindness.pdf","sourcePage":1},{"front":"colour-sensitive cells","meaning":"感色細胞","examples":[{"en":"The retina contains colour-sensitive cells that help us see colour.","zh":"視網膜含有幫助我們看見顏色的感色細胞。"},{"en":"Colour-sensitive cells are cells that respond to different colours of light.","zh":"感色細胞是對不同顏色光線作出反應的細胞。"},{"en":"In the eye, colour-sensitive cells help people tell red from green or blue.","zh":"在眼睛中，感色細胞幫助人分辨紅色、綠色或藍色。"},{"en":"If these cells do not work properly, colours may look different or confusing.","zh":"如果這些細胞無法正常運作，顏色可能看起來不同或令人混淆。"},{"en":"The phrase refers mainly to cone cells in this passage.","zh":"在本文中，這個短語主要指視錐細胞。"}],"source":"77 - Colour Blindness.pdf","sourcePage":1},{"front":"the retina","meaning":"視網膜","examples":[{"en":"The retina is a light-sensitive membrane at the back of the eye.","zh":"視網膜是眼睛後方的感光膜。"},{"en":"The retina is the part of the eye that receives light and sends visual signals to the brain.","zh":"視網膜是接收光線並把視覺訊號傳送到大腦的眼睛部分。"},{"en":"An eye doctor may examine the retina during a detailed eye check.","zh":"眼科醫生可能在詳細眼睛檢查中檢查視網膜。"},{"en":"If the retina is damaged, vision can become blurred or incomplete.","zh":"如果視網膜受損，視力可能變得模糊或不完整。"},{"en":"The phrase names an important inner layer of the eye.","zh":"這個短語指出眼睛內部的重要層。"}],"source":"77 - Colour Blindness.pdf","sourcePage":1},{"front":"a light-sensitive membrane","meaning":"感光膜","examples":[{"en":"The retina is a light-sensitive membrane lining the inside back of the eye.","zh":"視網膜是覆蓋眼睛內部後方的感光膜。"},{"en":"A light-sensitive membrane is a thin layer that reacts to light.","zh":"感光膜是會對光線作出反應的薄層。"},{"en":"A camera sensor is not a membrane, but it also reacts to light to form images.","zh":"相機感應器不是膜，但也會對光線作出反應以形成影像。"},{"en":"If a light-sensitive layer stops working, images cannot be received clearly.","zh":"如果感光層停止運作，影像就不能被清楚接收。"},{"en":"The phrase explains why the retina is essential for seeing.","zh":"這個短語解釋為何視網膜對視覺很重要。"}],"source":"77 - Colour Blindness.pdf","sourcePage":1},{"front":"lining the inside back of","meaning":"覆蓋……內部後方","examples":[{"en":"The retina is a membrane lining the inside back of the eye.","zh":"視網膜是一層覆蓋眼睛內部後方的膜。"},{"en":"Lining the inside back of something means covering its inner rear surface.","zh":"「lining the inside back of」某物，意思是覆蓋其內部後方表面。"},{"en":"Wallpaper can line the inside back of a display box.","zh":"牆紙可以覆蓋展示盒內部後方。"},{"en":"Because the retina lines the back of the eye, light is focused onto it after entering the eye.","zh":"因為視網膜覆蓋眼睛後方，光線進入眼睛後會聚焦在它上面。"},{"en":"The phrase describes position and coverage.","zh":"這個短語描述位置和覆蓋範圍。"}],"source":"77 - Colour Blindness.pdf","sourcePage":1},{"front":"behind the lens","meaning":"在晶狀體後面","examples":[{"en":"The retina lies behind the lens.","zh":"視網膜位於晶狀體後面。"},{"en":"Behind the lens means at the back of the eye’s lens.","zh":"「behind the lens」意思是在眼睛晶狀體的後方。"},{"en":"In a camera, the image sensor is positioned behind the lens.","zh":"在相機中，影像感應器位於鏡頭後面。"},{"en":"Since the retina is behind the lens, light passes through the lens before reaching it.","zh":"由於視網膜在晶狀體後面，光線到達它之前會先穿過晶狀體。"},{"en":"The phrase gives a simple location inside the eye.","zh":"這個短語提供眼睛內部的簡單位置。"}],"source":"77 - Colour Blindness.pdf","sourcePage":1},{"front":"rod cells","meaning":"視桿細胞","examples":[{"en":"Rod cells are active in low light and night vision.","zh":"視桿細胞在弱光和夜間視力中活躍。"},{"en":"Rod cells are eye cells that help people see in dim light but not in colour.","zh":"視桿細胞是幫助人在昏暗光線中看見東西、但不負責色彩的眼細胞。"},{"en":"When you walk in a dark cinema, rod cells help you see seats and steps.","zh":"當你在黑暗戲院行走時，視桿細胞幫助你看見座位和梯級。"},{"en":"If rod cells are weak, seeing at night may become difficult.","zh":"如果視桿細胞較弱，夜間視物可能變得困難。"},{"en":"The phrase contrasts with cone cells, which help with colour vision.","zh":"這個短語與幫助色覺的視錐細胞形成對比。"}],"source":"77 - Colour Blindness.pdf","sourcePage":1},{"front":"be active in low light","meaning":"在弱光下活躍","examples":[{"en":"Rod cells are active in low light but cannot distinguish colour.","zh":"視桿細胞在弱光下活躍，但不能分辨顏色。"},{"en":"To be active in low light means to work when there is little light.","zh":"「be active in low light」意思是在光線很少時仍能運作。"},{"en":"Cats’ eyes are useful in low light because their vision works well in darkness.","zh":"貓眼在弱光下很有用，因為牠們在黑暗中視力良好。"},{"en":"If a cell is active in low light, it helps vision when daylight is weak.","zh":"如果細胞在弱光下活躍，它會在日光不足時幫助視覺。"},{"en":"The phrase describes when something functions best.","zh":"這個短語描述某物何時最能發揮作用。"}],"source":"77 - Colour Blindness.pdf","sourcePage":1},{"front":"night vision","meaning":"夜間視力","examples":[{"en":"Rod cells are important for night vision.","zh":"視桿細胞對夜間視力很重要。"},{"en":"Night vision is the ability to see in darkness or very low light.","zh":"夜間視力是在黑暗或非常弱光中看見東西的能力。"},{"en":"Drivers need good night vision when roads are poorly lit.","zh":"道路照明不足時，司機需要良好夜間視力。"},{"en":"If night vision is weak, moving safely after dark becomes harder.","zh":"如果夜間視力弱，天黑後安全行動會更困難。"},{"en":"The phrase is about seeing in dim conditions, not seeing colours clearly.","zh":"這個短語關於在昏暗環境中看見東西，而不是清楚看見顏色。"}],"source":"77 - Colour Blindness.pdf","sourcePage":1},{"front":"distinguish colour","meaning":"分辨顏色","examples":[{"en":"Rod cells cannot distinguish colour.","zh":"視桿細胞不能分辨顏色。"},{"en":"To distinguish colour means to tell one colour from another.","zh":"「distinguish colour」意思是分辨一種顏色和另一種顏色。"},{"en":"A child learns to distinguish colour when sorting red, blue and yellow blocks.","zh":"孩子分類紅、藍、黃積木時，學會分辨顏色。"},{"en":"If someone cannot distinguish colour, labels or positions may become important clues.","zh":"如果某人不能分辨顏色，標籤或位置可能成為重要提示。"},{"en":"The phrase focuses on telling colours apart.","zh":"這個短語集中於區分顏色。"}],"source":"77 - Colour Blindness.pdf","sourcePage":2},{"front":"cone cells","meaning":"視錐細胞","examples":[{"en":"Cone cells are active in normal daylight and are sensitive to colour.","zh":"視錐細胞在正常日光下活躍，並對顏色敏感。"},{"en":"Cone cells are eye cells that help people see colours and sharp detail.","zh":"視錐細胞是幫助人看見顏色和銳利細節的眼細胞。"},{"en":"When you read a colourful map in daylight, cone cells help identify the colours.","zh":"當你在日光下閱讀彩色地圖時，視錐細胞幫助辨認顏色。"},{"en":"If cone cells are missing or defective, colour vision may be affected.","zh":"如果視錐細胞缺失或有缺陷，色覺可能受影響。"},{"en":"The phrase is central to understanding colour blindness.","zh":"這個短語是理解色盲的核心。"}],"source":"77 - Colour Blindness.pdf","sourcePage":2},{"front":"be active in normal daylight","meaning":"在正常日光下活躍","examples":[{"en":"Cone cells are active in normal daylight.","zh":"視錐細胞在正常日光下活躍。"},{"en":"To be active in normal daylight means to work best under ordinary daytime light.","zh":"「be active in normal daylight」意思是在普通日間光線下最能運作。"},{"en":"Reading a colourful poster outside uses vision that works well in daylight.","zh":"在戶外閱讀彩色海報時，會用到在日光下運作良好的視覺。"},{"en":"If cone cells are active in daylight, they help us see colour during normal daytime activities.","zh":"如果視錐細胞在日光下活躍，它們會幫助我們在日常白天活動中看見顏色。"},{"en":"The phrase contrasts daylight vision with night vision.","zh":"這個短語把日間視覺與夜間視覺作對比。"}],"source":"77 - Colour Blindness.pdf","sourcePage":2},{"front":"be sensitive to","meaning":"對……敏感","examples":[{"en":"Cone cells are sensitive to colour.","zh":"視錐細胞對顏色敏感。"},{"en":"To be sensitive to something means to react to it or notice it easily.","zh":"「be sensitive to」某物，意思是容易對它作出反應或察覺它。"},{"en":"Some people are sensitive to bright light and prefer wearing sunglasses.","zh":"有些人對強光敏感，較喜歡戴太陽眼鏡。"},{"en":"If cells are sensitive to colour, they respond differently to different light wavelengths.","zh":"如果細胞對顏色敏感，它們會對不同光波長作出不同反應。"},{"en":"The phrase describes what something can detect or react to.","zh":"這個短語描述某物能偵測或回應什麼。"}],"source":"77 - Colour Blindness.pdf","sourcePage":2},{"front":"photoreceptors","meaning":"感光受體","examples":[{"en":"Cone cells are also called photoreceptors.","zh":"視錐細胞也被稱為感光受體。"},{"en":"Photoreceptors are cells that receive light and help create visual signals.","zh":"感光受體是接收光線並幫助產生視覺訊號的細胞。"},{"en":"In the eye, photoreceptors turn light into information the brain can use.","zh":"在眼睛中，感光受體把光轉化為大腦可使用的資訊。"},{"en":"If photoreceptors are damaged, vision may become unclear or incomplete.","zh":"如果感光受體受損，視力可能變得不清楚或不完整。"},{"en":"The word literally means light receivers.","zh":"這個詞字面意思是接收光線的受體。"}],"source":"77 - Colour Blindness.pdf","sourcePage":2},{"front":"be concentrated mostly in","meaning":"主要集中在","examples":[{"en":"Cone cells are concentrated mostly in the central part of the retina.","zh":"視錐細胞主要集中在視網膜中央部分。"},{"en":"To be concentrated mostly in a place means to be found mainly there.","zh":"「be concentrated mostly in」某地，意思是主要出現在那裡。"},{"en":"Shops are often concentrated mostly in the centre of a town.","zh":"商店通常主要集中在市鎮中心。"},{"en":"If cone cells are concentrated in one area, that area is especially important for sharp colour vision.","zh":"如果視錐細胞集中在某區域，該區域對清晰色覺尤其重要。"},{"en":"The phrase describes where most of something is located.","zh":"這個短語描述某物大部分位於哪裡。"}],"source":"77 - Colour Blindness.pdf","sourcePage":2},{"front":"the central part of","meaning":"……的中央部分","examples":[{"en":"The macula is in the central part of the retina.","zh":"黃斑位於視網膜的中央部分。"},{"en":"The central part of something is the area near its middle.","zh":"「the central part of」某物，是接近其中間的位置。"},{"en":"A school office is often in the central part of the campus.","zh":"學校辦公室通常位於校園中央部分。"},{"en":"If an important visual area lies in the central part of the retina, damage there can affect detailed vision.","zh":"如果重要視覺區域位於視網膜中央部分，該處受損會影響細節視力。"},{"en":"The phrase gives a middle location.","zh":"這個短語提供中間位置。"}],"source":"77 - Colour Blindness.pdf","sourcePage":2},{"front":"the macula","meaning":"黃斑","examples":[{"en":"Cone cells are concentrated mostly in an area called the macula.","zh":"視錐細胞主要集中在一個稱為黃斑的區域。"},{"en":"The macula is the central part of the retina that helps with sharp, detailed vision.","zh":"黃斑是視網膜中央部分，幫助形成清晰細緻的視覺。"},{"en":"Eye doctors check the macula when patients report trouble reading small print.","zh":"當病人表示難以閱讀細字，眼科醫生會檢查黃斑。"},{"en":"If the macula is damaged, reading and recognising faces can become difficult.","zh":"如果黃斑受損，閱讀和辨認面孔可能變得困難。"},{"en":"The phrase names a small but important retinal area.","zh":"這個短語指出視網膜上一個細小但重要的區域。"}],"source":"77 - Colour Blindness.pdf","sourcePage":2},{"front":"provide clear, sharp colour vision","meaning":"提供清晰銳利的色覺","examples":[{"en":"Cone cells provide clear, sharp colour vision.","zh":"視錐細胞提供清晰銳利的色覺。"},{"en":"To provide clear, sharp colour vision means to help people see colours accurately and in detail.","zh":"「provide clear, sharp colour vision」意思是幫助人準確而細緻地看見顏色。"},{"en":"Clear colour vision helps a student read coloured diagrams in a science textbook.","zh":"清晰色覺幫助學生閱讀科學課本中的彩色圖表。"},{"en":"If cone cells work well, colourful details look clearer and more precise.","zh":"如果視錐細胞運作良好，彩色細節會看起來更清楚和精確。"},{"en":"The phrase describes the main benefit of healthy cone cells.","zh":"這個短語描述健康視錐細胞的主要好處。"}],"source":"77 - Colour Blindness.pdf","sourcePage":2},{"front":"light-sensitive pigments","meaning":"感光色素","examples":[{"en":"The cones contain light-sensitive pigments.","zh":"視錐細胞含有感光色素。"},{"en":"Light-sensitive pigments are substances that react to light.","zh":"感光色素是會對光線作出反應的物質。"},{"en":"Some camera materials are designed to change when exposed to light.","zh":"有些相機材料被設計成接觸光線時會改變。"},{"en":"If these pigments do not work properly, colour signals may be incomplete.","zh":"如果這些色素無法正常運作，顏色訊號可能不完整。"},{"en":"The phrase explains what allows cone cells to respond to light.","zh":"這個短語解釋視錐細胞為何能回應光線。"}],"source":"77 - Colour Blindness.pdf","sourcePage":2},{"front":"be sensitive to specific ranges of","meaning":"對特定範圍的……敏感","examples":[{"en":"These pigments are sensitive to specific ranges of wavelengths.","zh":"這些色素對特定範圍的波長敏感。"},{"en":"To be sensitive to specific ranges of something means to react only to certain parts of it.","zh":"「be sensitive to specific ranges of」某物，意思是只對其中某些部分作出反應。"},{"en":"A radio may receive only specific ranges of signals.","zh":"收音機可能只接收特定範圍的訊號。"},{"en":"If pigments react to different wavelength ranges, the brain can compare signals and see colours.","zh":"如果色素對不同波長範圍作出反應，大腦就能比較訊號並看見顏色。"},{"en":"The phrase shows selective response, not response to everything.","zh":"這個短語顯示選擇性反應，而不是對所有東西都有反應。"}],"source":"77 - Colour Blindness.pdf","sourcePage":2},{"front":"wavelengths","meaning":"波長","examples":[{"en":"Different cone cells respond to different wavelengths of light.","zh":"不同視錐細胞對不同光波長作出反應。"},{"en":"Wavelengths are the distances between waves, and in light they help determine colour.","zh":"波長是波與波之間的距離，而在光線中它們有助決定顏色。"},{"en":"In science class, students learn that blue light and red light have different wavelengths.","zh":"在科學課中，學生學到藍光和紅光有不同波長。"},{"en":"If the eye cannot detect certain wavelengths well, some colours may be confused.","zh":"如果眼睛不能良好偵測某些波長，有些顏色可能被混淆。"},{"en":"The phrase belongs to the physics of light.","zh":"這個短語屬於光的物理學。"}],"source":"77 - Colour Blindness.pdf","sourcePage":3},{"front":"short wavelengths","meaning":"短波長","examples":[{"en":"One type of cone is sensitive to short wavelengths.","zh":"一種視錐細胞對短波長敏感。"},{"en":"Short wavelengths are shorter waves of light, often linked with blue colours.","zh":"短波長是較短的光波，通常與藍色相關。"},{"en":"A science diagram may show short wavelengths near the blue end of the spectrum.","zh":"科學圖表可能把短波長顯示在光譜接近藍色的一端。"},{"en":"If cones for short wavelengths are affected, blue-related colour vision may change.","zh":"如果負責短波長的視錐細胞受影響，與藍色相關的色覺可能改變。"},{"en":"The phrase helps explain why different cones detect different colours.","zh":"這個短語幫助解釋為何不同視錐細胞偵測不同顏色。"}],"source":"77 - Colour Blindness.pdf","sourcePage":3},{"front":"medium wavelengths","meaning":"中波長","examples":[{"en":"One type of cone is sensitive to medium wavelengths.","zh":"一種視錐細胞對中波長敏感。"},{"en":"Medium wavelengths are middle-range waves of light, often linked with green colours.","zh":"中波長是中等範圍的光波，通常與綠色相關。"},{"en":"A colour chart may show medium wavelengths between short blue and long red wavelengths.","zh":"色彩圖表可能把中波長放在短藍波和長紅波之間。"},{"en":"If medium-wavelength cones are defective, green perception may be affected.","zh":"如果中波長視錐細胞有缺陷，綠色感知可能受影響。"},{"en":"The phrase gives one range within visible light.","zh":"這個短語提供可見光中的一個範圍。"}],"source":"77 - Colour Blindness.pdf","sourcePage":3},{"front":"long wavelengths","meaning":"長波長","examples":[{"en":"One type of cone is sensitive to long wavelengths.","zh":"一種視錐細胞對長波長敏感。"},{"en":"Long wavelengths are longer waves of light, often linked with red colours.","zh":"長波長是較長的光波，通常與紅色相關。"},{"en":"In a rainbow diagram, red is usually shown near the long-wavelength end.","zh":"在彩虹圖中，紅色通常顯示在長波長一端。"},{"en":"If long-wavelength cones do not work properly, red perception may be affected.","zh":"如果長波長視錐細胞無法正常運作，紅色感知可能受影響。"},{"en":"The phrase helps explain red-related colour vision.","zh":"這個短語幫助解釋與紅色相關的色覺。"}],"source":"77 - Colour Blindness.pdf","sourcePage":3},{"front":"be perceived as","meaning":"被感知為","examples":[{"en":"Short wavelengths are perceived as blue.","zh":"短波長被感知為藍色。"},{"en":"To be perceived as something means to be seen, understood or experienced in that way.","zh":"「be perceived as」某物，意思是被看見、理解或感受成那樣。"},{"en":"A quiet student may be perceived as unfriendly even when she is only shy.","zh":"安靜的學生可能被看成不友善，即使她只是害羞。"},{"en":"If light signals are processed differently, a colour may be perceived differently.","zh":"如果光線訊號被不同方式處理，顏色可能被感知得不同。"},{"en":"The phrase focuses on how something appears to the mind.","zh":"這個短語集中於某物在心智中如何呈現。"}],"source":"77 - Colour Blindness.pdf","sourcePage":3},{"front":"send information about","meaning":"傳送關於……的資料","examples":[{"en":"These cells send information about colour to the brain.","zh":"這些細胞把關於顏色的資料傳送到大腦。"},{"en":"To send information about something means to pass details about it to another place or system.","zh":"「send information about」某事，意思是把關於它的細節傳到另一地方或系統。"},{"en":"A thermometer sends information about temperature to a display screen.","zh":"溫度計把關於溫度的資料傳送到顯示屏。"},{"en":"If eye cells send incomplete information, the brain may form an unusual colour image.","zh":"如果眼細胞傳送不完整資料，大腦可能形成異常顏色影像。"},{"en":"The phrase describes communication of data.","zh":"這個短語描述資料傳遞。"}],"source":"77 - Colour Blindness.pdf","sourcePage":3},{"front":"via the optic nerve","meaning":"透過視神經","examples":[{"en":"Colour information is sent to the brain via the optic nerve.","zh":"顏色資料透過視神經傳送到大腦。"},{"en":"Via the optic nerve means through the nerve that carries visual information from the eye to the brain.","zh":"「via the optic nerve」意思是透過把視覺資料從眼睛帶到大腦的神經。"},{"en":"A message can be sent via email, while visual signals are sent via nerves.","zh":"訊息可以透過電郵傳送，而視覺訊號則透過神經傳送。"},{"en":"If the optic nerve is damaged, visual information may not reach the brain properly.","zh":"如果視神經受損，視覺資料可能無法正確到達大腦。"},{"en":"The phrase explains the route of visual signals.","zh":"這個短語解釋視覺訊號的路線。"}],"source":"77 - Colour Blindness.pdf","sourcePage":3},{"front":"the optic nerve","meaning":"視神經","examples":[{"en":"The optic nerve connects to the retina near the macula.","zh":"視神經在黃斑附近連接到視網膜。"},{"en":"The optic nerve is the nerve that carries visual information from the eye to the brain.","zh":"視神經是把視覺資料從眼睛帶到大腦的神經。"},{"en":"Eye doctors may check the optic nerve when testing for serious eye disease.","zh":"眼科醫生在檢查嚴重眼疾時，可能檢查視神經。"},{"en":"If the optic nerve cannot send signals clearly, sight may be affected.","zh":"如果視神經不能清楚傳送訊號，視力可能受影響。"},{"en":"The phrase names the eye’s main signal pathway to the brain.","zh":"這個短語指出眼睛通往大腦的主要訊號通道。"}],"source":"77 - Colour Blindness.pdf","sourcePage":3},{"front":"connect to","meaning":"連接到","examples":[{"en":"The optic nerve connects to the retina.","zh":"視神經連接到視網膜。"},{"en":"To connect to something means to join or link with it.","zh":"「connect to」某物，意思是與它接合或連結。"},{"en":"A charger connects to a phone before electricity can flow into it.","zh":"充電器連接到電話後，電力才能流入。"},{"en":"If the optic nerve connects to the retina, signals can travel from the eye to the brain.","zh":"如果視神經連接到視網膜，訊號就能從眼睛傳到大腦。"},{"en":"The phrase describes physical or functional linkage.","zh":"這個短語描述身體上或功能上的連結。"}],"source":"77 - Colour Blindness.pdf","sourcePage":3},{"front":"at a point very close to","meaning":"在非常接近……的位置","examples":[{"en":"The optic nerve connects to the retina at a point very close to the macula.","zh":"視神經在非常接近黃斑的位置連接到視網膜。"},{"en":"At a point very close to something means at a location near it.","zh":"「at a point very close to」某物，意思是在接近它的位置。"},{"en":"The bus stop is at a point very close to the school gate.","zh":"巴士站位於非常接近校門的位置。"},{"en":"If two eye structures are close together, damage in one area may affect nearby vision.","zh":"如果兩個眼部結構很接近，其中一個區域受損可能影響附近視覺。"},{"en":"The phrase gives a precise nearby location.","zh":"這個短語提供精確的鄰近位置。"}],"source":"77 - Colour Blindness.pdf","sourcePage":3},{"front":"normal colour vision","meaning":"正常色覺","examples":[{"en":"People with normal colour vision can match all colours of the spectrum.","zh":"有正常色覺的人可以配對光譜中的所有顏色。"},{"en":"Normal colour vision means seeing colours in the usual way through all three cone systems.","zh":"正常色覺是透過三種視錐系統以一般方式看見顏色。"},{"en":"A person with normal colour vision can usually tell red, green and blue apart easily.","zh":"有正常色覺的人通常能輕易分辨紅、綠、藍。"},{"en":"If colour vision is normal, colour-coded maps and signals are easier to use.","zh":"如果色覺正常，顏色編碼地圖和信號會較容易使用。"},{"en":"The phrase contrasts with colour-deficient vision.","zh":"這個短語與色覺缺陷形成對比。"}],"source":"77 - Colour Blindness.pdf","sourcePage":3},{"front":"be referred to as","meaning":"被稱為","examples":[{"en":"People with normal colour vision are referred to as trichromats.","zh":"有正常色覺的人被稱為三色視者。"},{"en":"To be referred to as something means to be called by that name.","zh":"「be referred to as」某物，意思是被那個名稱稱呼。"},{"en":"Students who study insects may be referred to as young entomologists in a science club.","zh":"在科學社中，研究昆蟲的學生可能被稱為年輕昆蟲學家。"},{"en":"If a group has a technical name, textbooks may refer to them using that term.","zh":"如果一個群體有技術名稱，教科書可能用該術語稱呼他們。"},{"en":"The phrase introduces terminology.","zh":"這個短語引入術語。"}],"source":"77 - Colour Blindness.pdf","sourcePage":4},{"front":"trichromats","meaning":"三色視者","examples":[{"en":"Trichromats can match all colours of the spectrum.","zh":"三色視者可以配對光譜中的所有顏色。"},{"en":"Trichromats are people whose colour vision uses three basic colour sensitivities.","zh":"三色視者是色覺使用三種基本顏色感受能力的人。"},{"en":"Most people with ordinary colour vision are trichromats.","zh":"大多數有普通色覺的人都是三色視者。"},{"en":"Because trichromats use three cone systems, they can perceive many colour combinations.","zh":"因為三色視者使用三種視錐系統，他們可以感知許多顏色組合。"},{"en":"The word literally relates to three-colour vision.","zh":"這個詞字面上與三色視覺有關。"}],"source":"77 - Colour Blindness.pdf","sourcePage":4},{"front":"match all colours of the spectrum","meaning":"配對光譜中的所有顏色","examples":[{"en":"Trichromats can match all colours of the spectrum.","zh":"三色視者可以配對光譜中的所有顏色。"},{"en":"To match all colours of the spectrum means to reproduce or identify colours across the full visible range.","zh":"「match all colours of the spectrum」意思是再現或辨認整個可見範圍中的顏色。"},{"en":"In a colour test, people may be asked to match colours using different lights.","zh":"在色覺測試中，人們可能被要求用不同光線配對顏色。"},{"en":"If all three colour sensitivities work, full colour matching becomes possible.","zh":"如果三種顏色感受能力都正常，完整顏色配對就成為可能。"},{"en":"The phrase describes a broad ability in normal colour vision.","zh":"這個短語描述正常色覺中的廣泛能力。"}],"source":"77 - Colour Blindness.pdf","sourcePage":4},{"front":"the spectrum","meaning":"光譜","examples":[{"en":"Normal colour vision allows people to match all colours of the spectrum.","zh":"正常色覺讓人能配對光譜中的所有顏色。"},{"en":"The spectrum is the range of visible colours produced by different wavelengths of light.","zh":"光譜是由不同光波長產生的可見顏色範圍。"},{"en":"A rainbow shows many colours in the visible spectrum.","zh":"彩虹展示可見光譜中的許多顏色。"},{"en":"If a person cannot see part of the spectrum normally, some colours may be confused.","zh":"如果某人不能正常看見光譜的一部分，有些顏色可能被混淆。"},{"en":"The phrase refers to the full range of visible colour.","zh":"這個短語指可見顏色的完整範圍。"}],"source":"77 - Colour Blindness.pdf","sourcePage":4},{"front":"a combination of","meaning":"……的組合","examples":[{"en":"Normal colour vision uses a combination of three colour sensitivities.","zh":"正常色覺使用三種顏色感受能力的組合。"},{"en":"A combination of things means several things working together.","zh":"「a combination of」幾件事，意思是多個事物一起作用。"},{"en":"A good study plan uses a combination of reading, practice and feedback.","zh":"好學習計劃使用閱讀、練習和回饋的組合。"},{"en":"If three colour systems combine, the brain can create many perceived colours.","zh":"如果三種顏色系統結合，大腦就能產生許多被感知的顏色。"},{"en":"The phrase shows that one result comes from more than one part.","zh":"這個短語顯示一個結果來自不止一個部分。"}],"source":"77 - Colour Blindness.pdf","sourcePage":4},{"front":"fundamental colour sensitivities","meaning":"基本顏色感受能力","examples":[{"en":"Trichromats use three fundamental colour sensitivities.","zh":"三色視者使用三種基本顏色感受能力。"},{"en":"Fundamental colour sensitivities are the basic ways the eye responds to different colour ranges.","zh":"「fundamental colour sensitivities」是眼睛對不同顏色範圍作出反應的基本方式。"},{"en":"A basic colour lesson may begin with the main sensitivities behind red, green and blue vision.","zh":"基礎顏色課可能從紅、綠、藍視覺背後的主要感受能力開始。"},{"en":"If one fundamental sensitivity is weak, colour perception can change.","zh":"如果其中一種基本感受能力較弱，顏色感知可能改變。"},{"en":"The phrase refers to basic building blocks of colour vision.","zh":"這個短語指色覺的基本組成部分。"}],"source":"77 - Colour Blindness.pdf","sourcePage":4},{"front":"hence","meaning":"因此","examples":[{"en":"Hence, the variety of colours we see comes from cone cells’ responses.","zh":"因此，我們看見的大量顏色來自視錐細胞的反應。"},{"en":"Hence means therefore or for this reason.","zh":"「hence」意思是因此或基於這個原因。"},{"en":"The bus was delayed; hence, several students arrived late.","zh":"巴士延誤；因此，幾名學生遲到。"},{"en":"If cone cells respond differently to light, hence the brain can perceive many colours.","zh":"如果視錐細胞對光作出不同反應，因此大腦能感知許多顏色。"},{"en":"The word introduces a logical result.","zh":"這個詞引出邏輯結果。"}],"source":"77 - Colour Blindness.pdf","sourcePage":4},{"front":"the huge variety of","meaning":"大量不同種類的……","examples":[{"en":"The huge variety of colours we perceive comes from different wavelength combinations.","zh":"我們感知到的大量不同顏色來自不同波長組合。"},{"en":"The huge variety of something means the very large number of different kinds of it.","zh":"「the huge variety of」某物，意思是非常多不同種類的它。"},{"en":"A supermarket has a huge variety of snacks, drinks and frozen foods.","zh":"超級市場有大量不同種類的小食、飲品和冷凍食品。"},{"en":"If wavelengths combine in many ways, they can create a huge variety of colours.","zh":"如果波長以許多方式組合，它們可以產生大量不同顏色。"},{"en":"The phrase emphasises diversity and quantity.","zh":"這個短語強調多樣性和數量。"}],"source":"77 - Colour Blindness.pdf","sourcePage":4},{"front":"perceive","meaning":"感知；察覺","examples":[{"en":"The colours we perceive depend on cone cells’ responses.","zh":"我們感知到的顏色取決於視錐細胞的反應。"},{"en":"To perceive something means to see, notice or become aware of it.","zh":"「perceive」某事，意思是看見、注意到或意識到它。"},{"en":"Two people may perceive the same classroom as either quiet or stressful.","zh":"兩個人可能把同一間課室感知為安靜或有壓力。"},{"en":"If the eye sends different signals, the brain may perceive colours differently.","zh":"如果眼睛傳送不同訊號，大腦可能以不同方式感知顏色。"},{"en":"The word focuses on how the mind receives information.","zh":"這個詞集中於心智如何接收資訊。"}],"source":"77 - Colour Blindness.pdf","sourcePage":4},{"front":"stem from","meaning":"源自","examples":[{"en":"The variety of colours we perceive stems from cone cells’ responses.","zh":"我們感知到的各種顏色源自視錐細胞的反應。"},{"en":"To stem from something means to come from it or be caused by it.","zh":"「stem from」某事，意思是來自它或由它造成。"},{"en":"A misunderstanding may stem from unclear instructions.","zh":"誤會可能源自不清楚的指示。"},{"en":"If colour perception stems from cone responses, defective cones can change colour experience.","zh":"如果顏色感知源自視錐反應，有缺陷的視錐細胞就能改變色彩經驗。"},{"en":"The phrase explains origin or cause.","zh":"這個短語解釋來源或原因。"}],"source":"77 - Colour Blindness.pdf","sourcePage":4},{"front":"cone cells’ response to","meaning":"視錐細胞對……的反應","examples":[{"en":"Colour perception depends on the cone cells’ response to wavelengths of light.","zh":"顏色感知取決於視錐細胞對光波長的反應。"},{"en":"Cone cells’ response to something means how cone cells react to it.","zh":"「cone cells’ response to」某物，意思是視錐細胞如何對它作出反應。"},{"en":"A student’s response to feedback may show whether the advice was understood.","zh":"學生對回饋的反應可能顯示他是否理解建議。"},{"en":"If cone cells respond weakly to certain wavelengths, colour vision may be altered.","zh":"如果視錐細胞對某些波長反應較弱，色覺可能改變。"},{"en":"The phrase describes the reaction that creates colour information.","zh":"這個短語描述產生顏色資訊的反應。"}],"source":"77 - Colour Blindness.pdf","sourcePage":4},{"front":"combinations of wavelengths","meaning":"波長組合","examples":[{"en":"Different combinations of wavelengths create different perceived colours.","zh":"不同波長組合產生不同被感知的顏色。"},{"en":"Combinations of wavelengths are mixtures of light waves of different lengths.","zh":"波長組合是不同長度光波的混合。"},{"en":"A screen creates colours by combining different light signals.","zh":"屏幕透過組合不同光訊號產生顏色。"},{"en":"If wavelength combinations change, the colour a person perceives may also change.","zh":"如果波長組合改變，人感知到的顏色也可能改變。"},{"en":"The phrase explains how many colours can come from limited light signals.","zh":"這個短語解釋為何有限光訊號能產生許多顏色。"}],"source":"77 - Colour Blindness.pdf","sourcePage":5},{"front":"wavelengths of light","meaning":"光的波長","examples":[{"en":"The eye responds to different wavelengths of light.","zh":"眼睛對不同光的波長作出反應。"},{"en":"Wavelengths of light are different lengths of light waves that help create colour.","zh":"光的波長是不同長度的光波，有助產生顏色。"},{"en":"Red and blue lights have different wavelengths of light.","zh":"紅光和藍光有不同的光波長。"},{"en":"If the eye cannot respond normally to some wavelengths, colour perception may be unusual.","zh":"如果眼睛不能正常回應某些波長，顏色感知可能不尋常。"},{"en":"The phrase connects physics with vision.","zh":"這個短語把物理學與視覺連繫起來。"}],"source":"77 - Colour Blindness.pdf","sourcePage":5},{"front":"many types of","meaning":"許多種類的……","examples":[{"en":"There are many types of colour blindness.","zh":"色盲有許多種類。"},{"en":"Many types of something means there are several different forms of it.","zh":"「many types of」某物，意思是它有幾種不同形式。"},{"en":"There are many types of learners, so one method may not help everyone.","zh":"學習者有許多種類，所以一種方法未必幫到所有人。"},{"en":"If colour blindness has many types, symptoms can differ from person to person.","zh":"如果色盲有許多種類，症狀可能因人而異。"},{"en":"The phrase warns us not to treat one condition as all the same.","zh":"這個短語提醒我們不要把一種狀況視為全部一樣。"}],"source":"77 - Colour Blindness.pdf","sourcePage":5},{"front":"deficiencies in the cones","meaning":"視錐細胞缺陷","examples":[{"en":"Deficiencies in the cones can cause colour ranges to be seen differently.","zh":"視錐細胞缺陷可以令顏色範圍被看成不同樣子。"},{"en":"Deficiencies in the cones are weaknesses or faults in the eye’s cone cells.","zh":"「deficiencies in the cones」是眼睛視錐細胞中的弱點或故障。"},{"en":"A deficiency in a machine part may make the whole machine work less well.","zh":"機器零件缺陷可能令整部機器運作變差。"},{"en":"If cone deficiencies affect red or green signals, those colours may be confused.","zh":"如果視錐細胞缺陷影響紅色或綠色訊號，那些顏色可能被混淆。"},{"en":"The phrase identifies a biological cause of colour vision problems.","zh":"這個短語指出色覺問題的生物成因。"}],"source":"77 - Colour Blindness.pdf","sourcePage":5},{"front":"whether present at birth or acquired later","meaning":"不論是天生還是後天形成","examples":[{"en":"Colour vision problems may be present at birth or acquired later.","zh":"色覺問題可能出生時已有，也可能後天形成。"},{"en":"Whether present at birth or acquired later means no matter if the condition is inborn or develops afterwards.","zh":"「whether present at birth or acquired later」意思是不論該狀況是天生還是之後形成。"},{"en":"Some health problems are present at birth, while others are acquired after illness or injury.","zh":"有些健康問題出生時已有，另一些則在疾病或受傷後形成。"},{"en":"If a problem is acquired later, doctors may look for a disease or injury as the cause.","zh":"如果問題後天形成，醫生可能尋找疾病或受傷作為成因。"},{"en":"The phrase contrasts inborn and later-developed conditions.","zh":"這個短語對比天生和後天形成的狀況。"}],"source":"77 - Colour Blindness.pdf","sourcePage":5},{"front":"present at birth","meaning":"出生時已有的","examples":[{"en":"Some colour vision problems are present at birth.","zh":"有些色覺問題出生時已有。"},{"en":"Present at birth means existing from the time a person is born.","zh":"「present at birth」意思是從一個人出生時已經存在。"},{"en":"Some babies have medical conditions present at birth that doctors monitor early.","zh":"有些嬰兒出生時已有醫療狀況，醫生會及早監測。"},{"en":"If colour blindness is present at birth, it is often inherited.","zh":"如果色盲出生時已有，它通常是遺傳的。"},{"en":"The phrase describes an inborn condition.","zh":"這個短語描述天生狀況。"}],"source":"77 - Colour Blindness.pdf","sourcePage":5},{"front":"acquired later","meaning":"後天形成的","examples":[{"en":"Some colour vision problems are acquired later in life.","zh":"有些色覺問題在人生較後階段後天形成。"},{"en":"Acquired later means developed after birth because of illness, injury or another cause.","zh":"「acquired later」意思是出生後因疾病、受傷或其他原因形成。"},{"en":"A person may acquire a vision problem later after an eye disease.","zh":"一個人可能因眼疾而後天形成視力問題。"},{"en":"If colour problems are acquired later, treatment may depend on the cause.","zh":"如果色覺問題是後天形成，治療可能視乎成因而定。"},{"en":"The phrase contrasts with conditions present at birth.","zh":"這個短語與出生時已有的狀況形成對比。"}],"source":"77 - Colour Blindness.pdf","sourcePage":5},{"front":"distinguish the particular wavelengths","meaning":"分辨特定波長","examples":[{"en":"Defective cones cannot distinguish the particular wavelengths.","zh":"有缺陷的視錐細胞不能分辨特定波長。"},{"en":"To distinguish the particular wavelengths means to tell specific light-wave ranges apart.","zh":"「distinguish the particular wavelengths」意思是分辨特定光波範圍。"},{"en":"A radio must distinguish particular signals to receive the correct station.","zh":"收音機必須分辨特定訊號，才能接收正確電台。"},{"en":"If cones cannot distinguish certain wavelengths, some colours may look the same.","zh":"如果視錐細胞不能分辨某些波長，有些顏色可能看起來相同。"},{"en":"The phrase explains a technical problem behind colour confusion.","zh":"這個短語解釋顏色混淆背後的技術問題。"}],"source":"77 - Colour Blindness.pdf","sourcePage":5},{"front":"colour range","meaning":"顏色範圍","examples":[{"en":"A colour range may be seen differently when the cones are defective.","zh":"當視錐細胞有缺陷時，某個顏色範圍可能被看成不同樣子。"},{"en":"A colour range is a group of related colours within the spectrum.","zh":"顏色範圍是光譜中一組相關顏色。"},{"en":"A paint shop may display a colour range from pale green to dark green.","zh":"油漆店可能展示由淺綠到深綠的顏色範圍。"},{"en":"If one cone type is defective, a whole colour range may appear changed.","zh":"如果一種視錐細胞有缺陷，整個顏色範圍可能看起來改變。"},{"en":"The phrase refers to a section of colour, not just one shade.","zh":"這個短語指一段顏色，而不只是單一色調。"}],"source":"77 - Colour Blindness.pdf","sourcePage":5},{"front":"be seen differently","meaning":"被看成不同樣子","examples":[{"en":"That colour range is seen differently by people with colour blindness.","zh":"那個顏色範圍會被色盲人士看成不同樣子。"},{"en":"To be seen differently means to appear in a different way to someone.","zh":"「be seen differently」意思是對某人來說呈現出不同樣子。"},{"en":"A classroom may be seen differently by a teacher and a new student.","zh":"同一間課室在老師和新學生眼中可能被看成不同樣子。"},{"en":"If colour signals are changed, the same object may be seen differently by different people.","zh":"如果顏色訊號改變，同一物件可能被不同人看成不同樣子。"},{"en":"The phrase focuses on differences in perception.","zh":"這個短語集中於感知差異。"}],"source":"77 - Colour Blindness.pdf","sourcePage":5},{"front":"defective colour vision","meaning":"有缺陷的色覺","examples":[{"en":"Those with defective colour vision may lack one or more pigments.","zh":"有缺陷的色覺人士可能缺少一種或多種色素。"},{"en":"Defective colour vision means colour vision that does not work in the usual way.","zh":"「defective colour vision」是無法以一般方式運作的色覺。"},{"en":"A person with defective colour vision may choose clothes by labels rather than colour alone.","zh":"有缺陷色覺的人可能靠標籤而不單靠顏色選衣服。"},{"en":"If pigments are missing, colour vision can become defective.","zh":"如果色素缺失，色覺可能變得有缺陷。"},{"en":"The phrase is more technical than simply saying colour blindness.","zh":"這個短語比單純說色盲更技術性。"}],"source":"77 - Colour Blindness.pdf","sourcePage":5},{"front":"have a deficiency in","meaning":"在……方面有缺陷","examples":[{"en":"Some people have a deficiency in one of the pigments.","zh":"有些人在其中一種色素方面有缺陷。"},{"en":"To have a deficiency in something means to lack enough of it or have a weakness in it.","zh":"「have a deficiency in」某物，意思是缺乏足夠的它或在它方面有弱點。"},{"en":"A student may have a deficiency in vocabulary but strong grammar.","zh":"學生可能在詞彙方面有缺陷，但文法很強。"},{"en":"If a person has a deficiency in one cone pigment, some colours may be harder to see normally.","zh":"如果某人在一種視錐色素方面有缺陷，有些顏色可能較難正常看見。"},{"en":"The phrase describes an incomplete or weak part.","zh":"這個短語描述不完整或薄弱的部分。"}],"source":"77 - Colour Blindness.pdf","sourcePage":6},{"front":"deficiency or absence of","meaning":"……的不足或缺失","examples":[{"en":"Colour blindness may involve a deficiency or absence of one or more pigments.","zh":"色盲可能涉及一種或多種色素的不足或缺失。"},{"en":"Deficiency or absence of something means it is weak, insufficient or completely missing.","zh":"「deficiency or absence of」某物，意思是它薄弱、不足或完全缺失。"},{"en":"A deficiency or absence of clear rules can cause confusion in a classroom.","zh":"清楚規則不足或缺失可以在課室造成混亂。"},{"en":"If pigments are deficient or absent, colour signals become less complete.","zh":"如果色素不足或缺失，顏色訊號會變得較不完整。"},{"en":"The phrase includes both partial and total loss.","zh":"這個短語包括部分喪失和完全喪失。"}],"source":"77 - Colour Blindness.pdf","sourcePage":6},{"front":"one or more of","meaning":"一個或多個……","examples":[{"en":"Some people lack one or more of the cone pigments.","zh":"有些人缺少一種或多種視錐色素。"},{"en":"One or more of something means at least one, and possibly several.","zh":"「one or more of」某物，意思是至少一個，也可能是幾個。"},{"en":"A student may miss one or more of the required documents for an application.","zh":"學生申請時可能缺少一份或多份所需文件。"},{"en":"If one or more pigments are missing, the type of colour blindness can differ.","zh":"如果一種或多種色素缺失，色盲類型可能不同。"},{"en":"The phrase keeps the number open.","zh":"這個短語讓數量保持開放。"}],"source":"77 - Colour Blindness.pdf","sourcePage":6},{"front":"the most common type of","meaning":"最常見的……類型","examples":[{"en":"A deficiency in one pigment is the most common type of colour vision problem.","zh":"一種色素不足是最常見的色覺問題類型。"},{"en":"The most common type of something is the form that appears most often.","zh":"「the most common type of」某物，是最常出現的形式。"},{"en":"A cold is one of the most common types of illness among students.","zh":"感冒是學生中最常見的疾病類型之一。"},{"en":"If one-pigment deficiency is most common, doctors and tests often focus on it first.","zh":"如果一種色素不足最常見，醫生和測試通常會先關注它。"},{"en":"The phrase identifies the most frequent category.","zh":"這個短語指出最頻繁出現的類別。"}],"source":"77 - Colour Blindness.pdf","sourcePage":6},{"front":"anomalous trichromats","meaning":"異常三色視者","examples":[{"en":"People with a deficiency in one pigment are called anomalous trichromats.","zh":"在一種色素方面有缺陷的人被稱為異常三色視者。"},{"en":"Anomalous trichromats are people who still use three colour systems, but one works unusually.","zh":"異常三色視者仍使用三種顏色系統，但其中一種運作不尋常。"},{"en":"A person may pass many daily tasks but still have unusual colour matching.","zh":"一個人可能能完成許多日常任務，但仍有不尋常的顏色配對。"},{"en":"If one cone pigment is weak, colour vision is not normal even though three systems remain.","zh":"如果一種視錐色素較弱，即使三個系統仍存在，色覺也不是正常的。"},{"en":"The term describes a mild or partial difference from normal trichromacy.","zh":"這個術語描述與正常三色視有輕微或部分差異。"}],"source":"77 - Colour Blindness.pdf","sourcePage":6},{"front":"cone pigments","meaning":"視錐色素","examples":[{"en":"Colour vision depends on the presence of cone pigments.","zh":"色覺取決於視錐色素是否存在。"},{"en":"Cone pigments are light-sensitive substances inside cone cells.","zh":"視錐色素是視錐細胞內的感光物質。"},{"en":"Eye diagrams may show cone pigments as parts that react to different light wavelengths.","zh":"眼睛圖表可能把視錐色素展示為對不同光波長作反應的部分。"},{"en":"If a cone pigment is missing, certain colour signals cannot be processed normally.","zh":"如果視錐色素缺失，某些顏色訊號不能正常處理。"},{"en":"The phrase names the substances behind colour sensitivity.","zh":"這個短語指出色彩敏感度背後的物質。"}],"source":"77 - Colour Blindness.pdf","sourcePage":6},{"front":"be absent","meaning":"缺失；不存在","examples":[{"en":"When one of the cone pigments is absent, dichromacy occurs.","zh":"當其中一種視錐色素缺失時，二色視就會出現。"},{"en":"To be absent means to be missing or not present.","zh":"「be absent」意思是缺失或不存在。"},{"en":"A student is marked absent when he does not come to school.","zh":"學生沒有上學時會被記為缺席。"},{"en":"If a cone pigment is absent, the colour system loses one important signal source.","zh":"如果一種視錐色素缺失，色覺系統就失去一個重要訊號來源。"},{"en":"The phrase describes complete lack, not just weakness.","zh":"這個短語描述完全缺少，而不只是較弱。"}],"source":"77 - Colour Blindness.pdf","sourcePage":6},{"front":"be reduced to two dimensions","meaning":"被減至兩個維度","examples":[{"en":"When one cone pigment is absent, colour is reduced to two dimensions.","zh":"當一種視錐色素缺失時，顏色被減至兩個維度。"},{"en":"To be reduced to two dimensions means to become limited to two basic sources or directions.","zh":"「be reduced to two dimensions」意思是被限制為兩個基本來源或方向。"},{"en":"A complex discussion may be reduced to two choices if people ignore other details.","zh":"如果人們忽略其他細節，複雜討論可能被簡化成兩個選擇。"},{"en":"If one colour system is missing, colour perception becomes less rich.","zh":"如果一個顏色系統缺失，顏色感知就變得較不豐富。"},{"en":"The phrase shows simplification caused by loss.","zh":"這個短語顯示因喪失而出現的簡化。"}],"source":"77 - Colour Blindness.pdf","sourcePage":6},{"front":"dichromacy","meaning":"二色視","examples":[{"en":"Dichromacy occurs when one of the cone pigments is absent.","zh":"當其中一種視錐色素缺失時，二色視就會出現。"},{"en":"Dichromacy is a type of colour vision in which only two cone colour systems function.","zh":"二色視是一種只有兩個視錐顏色系統運作的色覺。"},{"en":"A person with dichromacy may confuse colours that normal viewers see as clearly different.","zh":"有二色視的人可能混淆正常觀看者看來明顯不同的顏色。"},{"en":"If one pigment is absent, the brain has fewer colour signals to compare.","zh":"如果一種色素缺失，大腦可比較的顏色訊號就較少。"},{"en":"The word literally relates to two-colour vision.","zh":"這個詞字面上與二色視覺有關。"}],"source":"77 - Colour Blindness.pdf","sourcePage":6},{"front":"affect someone’s life on a daily basis","meaning":"每天影響某人的生活","examples":[{"en":"Dichromacy can affect a person’s life on a daily basis.","zh":"二色視可以每天影響一個人的生活。"},{"en":"To affect someone’s life on a daily basis means to influence ordinary activities every day.","zh":"「affect someone’s life on a daily basis」意思是每天影響普通活動。"},{"en":"Poor eyesight can affect a student’s life daily when reading the board is difficult.","zh":"如果看黑板困難，視力差可以每天影響學生生活。"},{"en":"If colour confusion happens often, shopping, driving and cooking may be affected.","zh":"如果顏色混淆經常發生，購物、駕駛和煮食都可能受影響。"},{"en":"The phrase stresses repeated everyday impact.","zh":"這個短語強調重複出現的日常影響。"}],"source":"77 - Colour Blindness.pdf","sourcePage":6},{"front":"on a daily basis","meaning":"每天；日常地","examples":[{"en":"Some colour vision problems affect people on a daily basis.","zh":"有些色覺問題每天影響人們。"},{"en":"On a daily basis means every day or as part of normal daily life.","zh":"「on a daily basis」意思是每天或作為正常日常生活的一部分。"},{"en":"Students use reading skills on a daily basis at school.","zh":"學生在學校每天使用閱讀技巧。"},{"en":"If a problem happens daily, it can become tiring even if it seems small.","zh":"如果問題每天發生，即使看似細小，也會令人疲累。"},{"en":"The phrase describes regular everyday frequency.","zh":"這個短語描述日常規律頻率。"}],"source":"77 - Colour Blindness.pdf","sourcePage":6},{"front":"perceptible difference","meaning":"可察覺的差異","examples":[{"en":"Some people see no perceptible difference between red, orange, yellow and green.","zh":"有些人看不出紅、橙、黃和綠之間有可察覺的差異。"},{"en":"A perceptible difference is a difference that can be noticed.","zh":"「perceptible difference」是可以被注意到的差異。"},{"en":"There may be no perceptible difference between two cheap phone cases until they are used for months.","zh":"兩個便宜手機殼可能要使用幾個月後才有可察覺差異。"},{"en":"If colours show no perceptible difference to someone, they may choose the wrong item.","zh":"如果某人看不出顏色有可察覺差異，他可能選錯物品。"},{"en":"The phrase means noticeable difference, not hidden difference.","zh":"這個短語指看得出的差異，而不是隱藏差異。"}],"source":"77 - Colour Blindness.pdf","sourcePage":7},{"front":"seem so different to","meaning":"對……來說看似很不同","examples":[{"en":"These colours seem so different to the normal viewer.","zh":"這些顏色對正常觀看者來說看似很不同。"},{"en":"Seem so different to someone means appear clearly different from that person’s point of view.","zh":"「seem so different to」某人，意思是從該人的角度看來明顯不同。"},{"en":"Two accents may seem very different to a language teacher but not to a beginner.","zh":"兩種口音對語言老師來說可能很不同，但對初學者來說未必如此。"},{"en":"If colours seem different to one person but not another, perception is not the same.","zh":"如果顏色對一個人來說不同，對另一個人卻不不同，感知就不一樣。"},{"en":"The phrase compares how things appear to different people.","zh":"這個短語比較事物對不同人如何呈現。"}],"source":"77 - Colour Blindness.pdf","sourcePage":7},{"front":"the normal viewer","meaning":"視力正常的觀看者","examples":[{"en":"Colours that look different to the normal viewer may appear the same to colour-blind people.","zh":"對視力正常觀看者看來不同的顏色，在色盲人士看來可能相同。"},{"en":"The normal viewer means a person with ordinary colour vision.","zh":"「the normal viewer」指有普通色覺的人。"},{"en":"A normal viewer can usually separate red signs from green signs easily.","zh":"視力正常的觀看者通常能輕易分辨紅色標誌和綠色標誌。"},{"en":"If a design works only for the normal viewer, colour-blind users may struggle.","zh":"如果設計只適合正常觀看者，色盲使用者可能會吃力。"},{"en":"The phrase is used as a comparison point.","zh":"這個短語用作比較基準。"}],"source":"77 - Colour Blindness.pdf","sourcePage":7},{"front":"appear to them to be","meaning":"在他們看來似乎是","examples":[{"en":"Several colours may appear to them to be the same colour.","zh":"幾種顏色在他們看來似乎是同一種顏色。"},{"en":"Appear to them to be means seem to those people to be a certain way.","zh":"「appear to them to be」意思是對那些人來說似乎是某種樣子。"},{"en":"Two jackets may appear to a shopper to be the same colour under poor lighting.","zh":"在光線差的情況下，兩件外套在購物者看來可能是同一顏色。"},{"en":"If colours appear the same to someone, matching clothes can become difficult.","zh":"如果顏色在某人看來相同，配襯衣服可能變得困難。"},{"en":"The phrase describes a person’s perception, not the object itself.","zh":"這個短語描述人的感知，而不是物件本身。"}],"source":"77 - Colour Blindness.pdf","sourcePage":7},{"front":"be responsible for","meaning":"負責","examples":[{"en":"Some cones are responsible for green and red hues.","zh":"有些視錐細胞負責綠色和紅色色調。"},{"en":"To be responsible for something means to have the job or role of producing or controlling it.","zh":"「be responsible for」某事，意思是有產生、控制或處理它的職責或作用。"},{"en":"A class monitor may be responsible for collecting homework.","zh":"班長可能負責收功課。"},{"en":"If certain cones are responsible for red and green hues, losing them affects those colours.","zh":"如果某些視錐細胞負責紅綠色調，失去它們就會影響那些顏色。"},{"en":"The phrase identifies function or duty.","zh":"這個短語指出功能或職責。"}],"source":"77 - Colour Blindness.pdf","sourcePage":7},{"front":"green and red hues","meaning":"綠色和紅色色調","examples":[{"en":"Missing cones responsible for green and red hues can affect brightness sensitivity.","zh":"負責綠色和紅色色調的視錐細胞缺失，會影響對亮度的敏感度。"},{"en":"Green and red hues are shades or forms of green and red colour.","zh":"「green and red hues」是綠色和紅色的不同色調或形式。"},{"en":"A painter may mix different green and red hues for leaves and flowers.","zh":"畫家可能混合不同綠色和紅色色調來畫葉和花。"},{"en":"If cones for these hues are missing, red-green distinction may become difficult.","zh":"如果負責這些色調的視錐細胞缺失，分辨紅綠可能變得困難。"},{"en":"The phrase refers to colour tones, not only pure red or green.","zh":"這個短語指色調，而不只是純紅或純綠。"}],"source":"77 - Colour Blindness.pdf","sourcePage":7},{"front":"affect the sensitivity to brightness","meaning":"影響對亮度的敏感度","examples":[{"en":"Missing certain cones can affect the sensitivity to brightness.","zh":"某些視錐細胞缺失可以影響對亮度的敏感度。"},{"en":"To affect sensitivity to brightness means to change how strongly someone notices light and dark levels.","zh":"「affect sensitivity to brightness」意思是改變某人察覺明暗程度的能力。"},{"en":"A phone screen setting can affect sensitivity to brightness in a dark room.","zh":"電話屏幕設定可以影響人在黑暗房間中對亮度的敏感度。"},{"en":"If cone loss changes brightness sensitivity, colours may look flatter or less clear.","zh":"如果視錐細胞缺失改變亮度敏感度，顏色可能看起來較平淡或不清晰。"},{"en":"The phrase links colour cells with light-level perception.","zh":"這個短語把感色細胞與明暗感知連繫起來。"}],"source":"77 - Colour Blindness.pdf","sourcePage":7},{"front":"sensitivity to brightness","meaning":"對亮度的敏感度","examples":[{"en":"Colour vision problems can affect sensitivity to brightness.","zh":"色覺問題可以影響對亮度的敏感度。"},{"en":"Sensitivity to brightness is how strongly the eyes react to light intensity.","zh":"「sensitivity to brightness」是眼睛對光線強度作出反應的程度。"},{"en":"Some people wear sunglasses because they have high sensitivity to brightness.","zh":"有些人因對亮度敏感而戴太陽眼鏡。"},{"en":"If brightness sensitivity changes, reading screens or seeing signals may become uncomfortable.","zh":"如果亮度敏感度改變，閱讀屏幕或看信號可能變得不舒服。"},{"en":"The phrase is about light strength, not colour name.","zh":"這個短語關於光線強弱，而不是顏色名稱。"}],"source":"77 - Colour Blindness.pdf","sourcePage":7},{"front":"most cases of","meaning":"大多數……個案","examples":[{"en":"Most cases of colour blindness are inherited.","zh":"大多數色盲個案是遺傳的。"},{"en":"Most cases of something means the majority of examples or patients with that condition.","zh":"「most cases of」某狀況，意思是該狀況的大部分例子或患者。"},{"en":"Most cases of a mild cold improve without special treatment.","zh":"大多數輕微感冒個案不用特別治療也會好轉。"},{"en":"If most cases are inherited, family history becomes relevant.","zh":"如果大多數個案是遺傳的，家族病史就變得相關。"},{"en":"The phrase describes what is usually true, not every case.","zh":"這個短語描述通常情況，而不是每一個案。"}],"source":"77 - Colour Blindness.pdf","sourcePage":7},{"front":"be inherited","meaning":"遺傳的","examples":[{"en":"Most cases of colour blindness are inherited.","zh":"大多數色盲個案是遺傳的。"},{"en":"To be inherited means to be passed from parents to children through genes.","zh":"「be inherited」意思是透過基因由父母傳給子女。"},{"en":"Eye colour can be inherited from parents.","zh":"眼睛顏色可以由父母遺傳。"},{"en":"If colour blindness is inherited, it may appear in several family members.","zh":"如果色盲是遺傳的，它可能出現在多名家庭成員身上。"},{"en":"The phrase describes genetic transmission.","zh":"這個短語描述基因傳遞。"}],"source":"77 - Colour Blindness.pdf","sourcePage":7},{"front":"partial or complete loss of function","meaning":"功能部分或完全喪失","examples":[{"en":"Inherited colour blindness results from partial or complete loss of function in cone systems.","zh":"遺傳性色盲由視錐系統功能部分或完全喪失引起。"},{"en":"Partial or complete loss of function means something works weakly or does not work at all.","zh":"「partial or complete loss of function」意思是某物運作較弱或完全不運作。"},{"en":"A phone may have partial loss of function if the camera works but the speaker fails.","zh":"如果電話相機能用但揚聲器壞掉，它可能有部分功能喪失。"},{"en":"If a cone system partly or completely loses function, colour perception changes.","zh":"如果視錐系統部分或完全失去功能，顏色感知就會改變。"},{"en":"The phrase covers different degrees of failure.","zh":"這個短語涵蓋不同程度的失效。"}],"source":"77 - Colour Blindness.pdf","sourcePage":7},{"front":"cone systems","meaning":"視錐系統","examples":[{"en":"Inherited colour blindness can affect one or more cone systems.","zh":"遺傳性色盲可以影響一個或多個視錐系統。"},{"en":"Cone systems are the groups of cone cells and pigments that respond to colour ranges.","zh":"視錐系統是對顏色範圍作出反應的視錐細胞和色素群。"},{"en":"A science teacher may explain cone systems using red, green and blue light examples.","zh":"科學老師可能用紅、綠、藍光例子解釋視錐系統。"},{"en":"If one cone system is weak, certain colours become harder to distinguish.","zh":"如果一個視錐系統較弱，某些顏色就較難分辨。"},{"en":"The phrase refers to the eye’s colour-detecting systems.","zh":"這個短語指眼睛的顏色偵測系統。"}],"source":"77 - Colour Blindness.pdf","sourcePage":8},{"front":"affect both eyes","meaning":"影響雙眼","examples":[{"en":"Inherited colour blindness usually affects both eyes.","zh":"遺傳性色盲通常影響雙眼。"},{"en":"To affect both eyes means to influence vision in the left and right eyes.","zh":"「affect both eyes」意思是影響左眼和右眼的視覺。"},{"en":"A genetic eye condition may affect both eyes rather than only one.","zh":"遺傳性眼疾可能影響雙眼，而不只是其中一隻眼。"},{"en":"If both eyes are affected, covering one eye will not solve the colour problem.","zh":"如果雙眼都受影響，遮住一隻眼不能解決色覺問題。"},{"en":"The phrase describes the spread of a vision condition across both eyes.","zh":"這個短語描述視覺狀況在雙眼中的影響範圍。"}],"source":"77 - Colour Blindness.pdf","sourcePage":8},{"front":"worsen over time","meaning":"隨時間惡化","examples":[{"en":"Inherited colour blindness does not worsen over time.","zh":"遺傳性色盲不會隨時間惡化。"},{"en":"To worsen over time means to become worse gradually as time passes.","zh":"「worsen over time」意思是隨時間過去逐漸變差。"},{"en":"A small leak may worsen over time if nobody repairs it.","zh":"如果沒有人修理，小漏水可能隨時間惡化。"},{"en":"If a condition does not worsen over time, it usually stays stable.","zh":"如果某狀況不會隨時間惡化，它通常保持穩定。"},{"en":"The phrase describes gradual decline.","zh":"這個短語描述逐漸衰退。"}],"source":"77 - Colour Blindness.pdf","sourcePage":8},{"front":"red-green hereditary disorders","meaning":"紅綠遺傳性障礙","examples":[{"en":"Red-green hereditary disorders are the most common form of colour blindness.","zh":"紅綠遺傳性障礙是最常見的色盲形式。"},{"en":"Red-green hereditary disorders are inherited conditions affecting red and green colour vision.","zh":"紅綠遺傳性障礙是影響紅綠色覺的遺傳狀況。"},{"en":"A family may discover a red-green disorder when a child cannot read colour-coded worksheets.","zh":"當孩子不能閱讀顏色編碼工作紙時，家庭可能發現紅綠障礙。"},{"en":"Because these disorders are inherited, they can run in families.","zh":"因為這些障礙是遺傳的，它們可以在家族中出現。"},{"en":"The phrase names the common genetic form of colour blindness.","zh":"這個短語指出最常見的遺傳性色盲形式。"}],"source":"77 - Colour Blindness.pdf","sourcePage":8},{"front":"genetic photoreceptor disorders","meaning":"遺傳性感光受體障礙","examples":[{"en":"Red-green colour blindness involves genetic photoreceptor disorders.","zh":"紅綠色盲涉及遺傳性感光受體障礙。"},{"en":"Genetic photoreceptor disorders are inherited problems affecting light-receiving cells in the eye.","zh":"遺傳性感光受體障礙是影響眼睛感光細胞的遺傳問題。"},{"en":"A doctor may explain a genetic disorder by looking at family history.","zh":"醫生可能透過查看家族病史來解釋遺傳性障礙。"},{"en":"If photoreceptors are genetically affected, colour signals may be abnormal from birth.","zh":"如果感光受體受遺傳影響，顏色訊號可能從出生起就異常。"},{"en":"The phrase combines genetics with eye-cell function.","zh":"這個短語結合遺傳學和眼細胞功能。"}],"source":"77 - Colour Blindness.pdf","sourcePage":8},{"front":"collectively referred to as","meaning":"統稱為","examples":[{"en":"These disorders are collectively referred to as red-green colour blindness.","zh":"這些障礙統稱為紅綠色盲。"},{"en":"Collectively referred to as means called by one shared name as a group.","zh":"「collectively referred to as」意思是作為一組被一個共同名稱稱呼。"},{"en":"Buses, trains and ferries are collectively referred to as public transport.","zh":"巴士、火車和渡輪統稱為公共交通。"},{"en":"If several related disorders share features, they may be grouped under one term.","zh":"如果幾種相關障礙有共同特徵，它們可能被歸入一個術語下。"},{"en":"The phrase introduces a group label.","zh":"這個短語引入群體標籤。"}],"source":"77 - Colour Blindness.pdf","sourcePage":8},{"front":"red-green colour blindness","meaning":"紅綠色盲","examples":[{"en":"Red-green colour blindness affects many males of European origin.","zh":"紅綠色盲影響許多歐洲血統男性。"},{"en":"Red-green colour blindness is difficulty seeing or distinguishing red and green normally.","zh":"紅綠色盲是難以正常看見或分辨紅色和綠色。"},{"en":"A colour-blind driver may rely on traffic light position rather than colour alone.","zh":"色盲司機可能依賴交通燈位置，而不只依靠顏色。"},{"en":"If red and green appear similar, charts and signals should use shapes or labels too.","zh":"如果紅色和綠色看起來相似，圖表和信號也應使用形狀或標籤。"},{"en":"The phrase names the most common colour-blindness category.","zh":"這個短語指出最常見的色盲類別。"}],"source":"77 - Colour Blindness.pdf","sourcePage":8},{"front":"European origin","meaning":"歐洲血統","examples":[{"en":"The disorder affects 8 per cent of males of European origin.","zh":"該障礙影響百分之八的歐洲血統男性。"},{"en":"European origin means having ancestry from Europe.","zh":"「European origin」意思是祖先來自歐洲。"},{"en":"A medical study may compare rates among people of different ethnic origins.","zh":"醫學研究可能比較不同族裔血統人士的患病率。"},{"en":"If a condition is more common in one origin group, genetic patterns may be relevant.","zh":"如果某狀況在一個血統群體中較常見，基因模式可能相關。"},{"en":"The phrase describes ancestry, not current nationality only.","zh":"這個短語描述祖源，而不只是當前國籍。"}],"source":"77 - Colour Blindness.pdf","sourcePage":8},{"front":"the gene for this","meaning":"造成這情況的基因","examples":[{"en":"The gene for this is carried on the X chromosome.","zh":"造成這情況的基因位於 X 染色體上。"},{"en":"The gene for this means the gene responsible for this condition or trait.","zh":"「the gene for this」意思是造成這種狀況或特徵的基因。"},{"en":"Scientists may look for the gene for a disease by studying affected families.","zh":"科學家可能透過研究受影響家庭來尋找某疾病基因。"},{"en":"If the gene for a condition is on the X chromosome, inheritance patterns differ by sex.","zh":"如果某狀況的基因在 X 染色體上，遺傳模式會因性別而不同。"},{"en":"The phrase points to the genetic cause being discussed.","zh":"這個短語指正在討論的遺傳成因。"}],"source":"77 - Colour Blindness.pdf","sourcePage":8},{"front":"be carried on","meaning":"位於；由……攜帶","examples":[{"en":"The gene for red-green colour blindness is carried on the X chromosome.","zh":"紅綠色盲基因位於 X 染色體上。"},{"en":"To be carried on a chromosome means to be located on that chromosome.","zh":"「be carried on」某染色體，意思是位於該染色體上。"},{"en":"Some traits are carried on specific chromosomes and passed through families.","zh":"有些特徵位於特定染色體上，並透過家族傳遞。"},{"en":"If a gene is carried on the X chromosome, males and females may be affected differently.","zh":"如果基因位於 X 染色體上，男性和女性受影響方式可能不同。"},{"en":"The phrase describes genetic location.","zh":"這個短語描述基因位置。"}],"source":"77 - Colour Blindness.pdf","sourcePage":8},{"front":"the X chromosome","meaning":"X 染色體","examples":[{"en":"The gene for red-green colour blindness is carried on the X chromosome.","zh":"紅綠色盲基因位於 X 染色體上。"},{"en":"The X chromosome is one of the sex chromosomes involved in biological sex and inheritance.","zh":"X 染色體是涉及生物性別和遺傳的性染色體之一。"},{"en":"Females usually have two X chromosomes, while males usually have one X and one Y.","zh":"女性通常有兩條 X 染色體，而男性通常有一條 X 和一條 Y。"},{"en":"If a disorder is linked to the X chromosome, males may be affected more easily.","zh":"如果障礙與 X 染色體相關，男性可能更容易受影響。"},{"en":"The phrase is central to explaining red-green colour-blind inheritance.","zh":"這個短語是解釋紅綠色盲遺傳的核心。"}],"source":"77 - Colour Blindness.pdf","sourcePage":8},{"front":"X-Y pairing","meaning":"X-Y 染色體配對","examples":[{"en":"Males have an X-Y pairing.","zh":"男性有 X-Y 染色體配對。"},{"en":"X-Y pairing means having one X chromosome and one Y chromosome.","zh":"「X-Y pairing」意思是有一條 X 染色體和一條 Y 染色體。"},{"en":"Biology lessons often use X-Y pairing to explain typical male chromosomes.","zh":"生物課常用 X-Y 配對解釋典型男性染色體。"},{"en":"If a male has only one X chromosome, a faulty gene on it may not be balanced by another X.","zh":"如果男性只有一條 X 染色體，其上的故障基因可能沒有另一條 X 來平衡。"},{"en":"The phrase describes a chromosome pattern.","zh":"這個短語描述染色體模式。"}],"source":"77 - Colour Blindness.pdf","sourcePage":9},{"front":"X-X pairing","meaning":"X-X 染色體配對","examples":[{"en":"Females have an X-X pairing.","zh":"女性有 X-X 染色體配對。"},{"en":"X-X pairing means having two X chromosomes.","zh":"「X-X pairing」意思是有兩條 X 染色體。"},{"en":"Biology teachers often use X-X pairing to explain typical female chromosomes.","zh":"生物老師常用 X-X 配對解釋典型女性染色體。"},{"en":"If one X chromosome carries a faulty gene, another X may reduce the effect.","zh":"如果一條 X 染色體攜帶故障基因，另一條 X 可能減少其影響。"},{"en":"The phrase helps explain why some X-linked conditions affect females less often.","zh":"這個短語幫助解釋為何某些 X 連鎖狀況較少影響女性。"}],"source":"77 - Colour Blindness.pdf","sourcePage":9},{"front":"occur much more easily in","meaning":"更容易在……身上出現","examples":[{"en":"Colour blindness can occur much more easily in males.","zh":"色盲更容易在男性身上出現。"},{"en":"To occur much more easily in a group means to happen more often in that group.","zh":"「occur much more easily in」某群體，意思是在該群體中更常發生。"},{"en":"Sunburn may occur more easily in people with very fair skin.","zh":"曬傷可能更容易在皮膚很白的人身上出現。"},{"en":"If a gene is on the X chromosome, the condition may occur more easily in males.","zh":"如果基因位於 X 染色體上，該狀況可能更容易在男性身上出現。"},{"en":"The phrase describes higher likelihood.","zh":"這個短語描述較高可能性。"}],"source":"77 - Colour Blindness.pdf","sourcePage":9},{"front":"be passed to someone by","meaning":"由……遺傳給某人","examples":[{"en":"Colour blindness is typically passed to males by their mothers.","zh":"色盲通常由母親遺傳給男性。"},{"en":"To be passed to someone by someone means to be transmitted from that person to another.","zh":"「be passed to someone by」某人，意思是由那人傳給另一人。"},{"en":"A family recipe may be passed to children by grandparents.","zh":"家庭食譜可能由祖父母傳給孩子。"},{"en":"If a gene is passed by a mother, her son may inherit the condition.","zh":"如果基因由母親傳下來，她的兒子可能遺傳該狀況。"},{"en":"The phrase describes transmission from one person to another.","zh":"這個短語描述由一人傳給另一人。"}],"source":"77 - Colour Blindness.pdf","sourcePage":9},{"front":"in other words","meaning":"換句話說","examples":[{"en":"In other words, females may be carriers of colour blindness.","zh":"換句話說，女性可能是色盲基因攜帶者。"},{"en":"In other words introduces a simpler or clearer way to say the same idea.","zh":"「in other words」用來以更簡單或更清楚的方式說同一個意思。"},{"en":"The lesson starts at 8 a.m.; in other words, students must arrive before breakfast ends.","zh":"課堂早上八時開始；換句話說，學生必須在早餐結束前到達。"},{"en":"If an explanation is technical, “in other words” helps restate it more clearly.","zh":"如果解釋很技術性，in other words 可以幫助更清楚重述。"},{"en":"The phrase signals rephrasing, not a new point.","zh":"這個短語表示重述，而不是新觀點。"}],"source":"77 - Colour Blindness.pdf","sourcePage":9},{"front":"carriers of colour blindness","meaning":"色盲基因攜帶者","examples":[{"en":"Females may be carriers of colour blindness.","zh":"女性可能是色盲基因攜帶者。"},{"en":"Carriers of colour blindness have the gene and can pass it on, even if they may not show the condition.","zh":"色盲基因攜帶者擁有該基因並能傳下去，即使自己未必顯示該狀況。"},{"en":"A person can be a carrier of a genetic trait without having obvious symptoms.","zh":"一個人可以是某遺傳特徵的攜帶者，而沒有明顯症狀。"},{"en":"If a mother is a carrier, her sons may have a higher chance of colour blindness.","zh":"如果母親是攜帶者，她的兒子有色盲的機會可能較高。"},{"en":"The phrase refers to genetic carrying, not physical carrying.","zh":"這個短語指基因攜帶，而不是實體攜帶。"}],"source":"77 - Colour Blindness.pdf","sourcePage":9},{"front":"be commonly affected","meaning":"較常受到影響","examples":[{"en":"Males are more commonly affected by red-green colour blindness.","zh":"男性較常受到紅綠色盲影響。"},{"en":"To be commonly affected means to experience a condition more often than others.","zh":"「be commonly affected」意思是比其他人更常經歷某狀況。"},{"en":"Children are commonly affected by colds during winter.","zh":"兒童在冬天較常受到感冒影響。"},{"en":"If males are more commonly affected, screening may pay special attention to them.","zh":"如果男性較常受影響，篩查可能特別留意他們。"},{"en":"The phrase describes frequency of impact.","zh":"這個短語描述受影響的頻率。"}],"source":"77 - Colour Blindness.pdf","sourcePage":9},{"front":"cannot identify","meaning":"不能辨認","examples":[{"en":"People with this disorder cannot identify red or green when either colour appears alone.","zh":"有這種障礙的人在紅色或綠色單獨出現時不能辨認它。"},{"en":"Cannot identify means cannot recognise or name something correctly.","zh":"「cannot identify」意思是不能正確認出或說出某物。"},{"en":"A student may not identify a word if the handwriting is unclear.","zh":"如果字跡不清，學生可能不能辨認某個字。"},{"en":"If a colour appears alone, people with red-green colour blindness may not recognise it accurately.","zh":"如果顏色單獨出現，紅綠色盲人士可能無法準確認出它。"},{"en":"The phrase focuses on recognition.","zh":"這個短語集中於辨認能力。"}],"source":"77 - Colour Blindness.pdf","sourcePage":9},{"front":"appear alone","meaning":"單獨出現","examples":[{"en":"People may fail to identify red or green when either colour appears alone.","zh":"當紅色或綠色單獨出現時，人們可能無法辨認它。"},{"en":"Appear alone means be shown by itself without other colours nearby.","zh":"「appear alone」意思是單獨顯示，附近沒有其他顏色。"},{"en":"A single warning light appears alone when there are no surrounding colour clues.","zh":"當沒有周圍顏色線索時，單一警示燈就是單獨出現。"},{"en":"If a colour appears alone, colour-blind people may have fewer comparison clues.","zh":"如果顏色單獨出現，色盲人士可能有較少比較線索。"},{"en":"The phrase describes isolation from context.","zh":"這個短語描述與語境分離。"}],"source":"77 - Colour Blindness.pdf","sourcePage":9},{"front":"appear among other colours","meaning":"出現在其他顏色之中","examples":[{"en":"They can identify red or green when it appears among other colours.","zh":"當紅色或綠色出現在其他顏色之中時，他們可以辨認。"},{"en":"To appear among other colours means to be shown together with surrounding colours.","zh":"「appear among other colours」意思是與周圍其他顏色一起顯示。"},{"en":"A red pencil is easier to notice when it appears among blue and yellow pencils.","zh":"當紅色鉛筆出現在藍色和黃色鉛筆之中，它較容易被注意到。"},{"en":"If colours are shown together, comparison may help colour-blind people identify them.","zh":"如果顏色一起顯示，比較可能幫助色盲人士辨認它們。"},{"en":"The phrase highlights the usefulness of context.","zh":"這個短語強調語境的作用。"}],"source":"77 - Colour Blindness.pdf","sourcePage":9},{"front":"other forms of","meaning":"其他形式的……","examples":[{"en":"Other forms of colour blindness are much rarer.","zh":"其他形式的色盲罕見得多。"},{"en":"Other forms of something are different types apart from the main one discussed.","zh":"「other forms of」某物，是除了正在討論的主要類型以外的不同種類。"},{"en":"Other forms of exercise include swimming, walking and cycling.","zh":"其他形式的運動包括游泳、步行和踩單車。"},{"en":"If other forms are rarer, they may be less familiar to the public.","zh":"如果其他形式較罕見，公眾可能較不熟悉。"},{"en":"The phrase expands the discussion beyond one category.","zh":"這個短語把討論擴展到另一類別。"}],"source":"77 - Colour Blindness.pdf","sourcePage":9},{"front":"much rarer","meaning":"罕見得多","examples":[{"en":"Blue-yellow colour problems are much rarer.","zh":"藍黃色覺問題罕見得多。"},{"en":"Much rarer means far less common.","zh":"「much rarer」意思是少見得多。"},{"en":"Snow is much rarer in Hong Kong than heavy rain.","zh":"在香港，下雪比大雨罕見得多。"},{"en":"If a condition is much rarer, fewer people will have direct experience with it.","zh":"如果某狀況罕見得多，較少人會有直接經驗。"},{"en":"The phrase compares frequency strongly.","zh":"這個短語強烈比較出現頻率。"}],"source":"77 - Colour Blindness.pdf","sourcePage":10},{"front":"discriminating blues from yellows","meaning":"分辨藍色和黃色","examples":[{"en":"Some disorders involve difficulty discriminating blues from yellows.","zh":"有些障礙涉及分辨藍色和黃色的困難。"},{"en":"Discriminating blues from yellows means telling blue colours apart from yellow colours.","zh":"「discriminating blues from yellows」意思是把藍色與黃色分辨開來。"},{"en":"A child sorting blocks may need to discriminate blue blocks from yellow ones.","zh":"孩子分類積木時，可能需要分辨藍色積木和黃色積木。"},{"en":"If this ability is weak, signs using blue and yellow may be confusing.","zh":"如果這種能力較弱，使用藍黃兩色的標誌可能令人混淆。"},{"en":"The phrase means distinguishing, not treating unfairly.","zh":"這裡的 discriminate 意思是分辨，而不是歧視。"}],"source":"77 - Colour Blindness.pdf","sourcePage":10},{"front":"be seen as white or grey","meaning":"被看成白色或灰色","examples":[{"en":"Both colours may be seen as white or grey.","zh":"兩種顏色可能被看成白色或灰色。"},{"en":"To be seen as white or grey means to appear white or grey to the viewer.","zh":"「be seen as white or grey」意思是在觀看者眼中呈現為白色或灰色。"},{"en":"Under poor lighting, a pale blue shirt may be seen as grey.","zh":"在光線差的情況下，淺藍色恤衫可能被看成灰色。"},{"en":"If blue and yellow are seen as white or grey, colour labels become useful.","zh":"如果藍色和黃色被看成白色或灰色，顏色標籤就很有用。"},{"en":"The phrase describes perceived colour, not the object’s actual colour.","zh":"這個短語描述被感知的顏色，而不是物件實際顏色。"}],"source":"77 - Colour Blindness.pdf","sourcePage":10},{"front":"occur with equal frequency","meaning":"以相同頻率出現","examples":[{"en":"This disorder occurs with equal frequency in men and women.","zh":"這種障礙在男女中以相同頻率出現。"},{"en":"To occur with equal frequency means to happen just as often in two groups.","zh":"「occur with equal frequency」意思是在兩個群體中同樣常出現。"},{"en":"A school rule applies equally if boys and girls break it with equal frequency.","zh":"如果男生和女生以相同頻率違反校規，該規則就同樣適用。"},{"en":"If a disorder occurs equally in men and women, sex-linked inheritance may not explain it.","zh":"如果某障礙在男女中同樣出現，性連鎖遺傳可能不能解釋它。"},{"en":"The phrase compares how often something happens.","zh":"這個短語比較某事發生的頻率。"}],"source":"77 - Colour Blindness.pdf","sourcePage":10},{"front":"accompany certain physical disorders","meaning":"伴隨某些身體疾病","examples":[{"en":"Blue-yellow colour blindness usually accompanies certain physical disorders.","zh":"藍黃色盲通常伴隨某些身體疾病。"},{"en":"To accompany certain physical disorders means to occur together with particular body conditions.","zh":"「accompany certain physical disorders」意思是與特定身體狀況一起出現。"},{"en":"Headaches may accompany flu when the body is under stress.","zh":"當身體受壓時，頭痛可能伴隨流感。"},{"en":"If colour problems accompany another disease, doctors may investigate the underlying illness.","zh":"如果色覺問題伴隨另一種疾病，醫生可能調查背後疾病。"},{"en":"The phrase shows that one condition appears alongside another.","zh":"這個短語顯示一種狀況與另一種狀況同時出現。"}],"source":"77 - Colour Blindness.pdf","sourcePage":10},{"front":"physical disorders","meaning":"身體疾病","examples":[{"en":"Some forms of colour blindness accompany physical disorders.","zh":"有些形式的色盲伴隨身體疾病。"},{"en":"Physical disorders are medical conditions affecting the body.","zh":"「physical disorders」是影響身體的醫療狀況。"},{"en":"Diabetes and liver disease are examples of physical disorders.","zh":"糖尿病和肝病都是身體疾病的例子。"},{"en":"If a colour problem appears with a physical disorder, it may not be purely inherited.","zh":"如果色覺問題與身體疾病一起出現，它可能不完全是遺傳的。"},{"en":"The phrase refers to body-related health conditions.","zh":"這個短語指與身體相關的健康狀況。"}],"source":"77 - Colour Blindness.pdf","sourcePage":10},{"front":"liver disease","meaning":"肝病","examples":[{"en":"Blue-yellow colour problems may accompany liver disease.","zh":"藍黃色覺問題可能伴隨肝病。"},{"en":"Liver disease is illness or damage affecting the liver.","zh":"肝病是影響肝臟的疾病或損害。"},{"en":"A doctor may order blood tests if liver disease is suspected.","zh":"如果懷疑有肝病，醫生可能安排血液測試。"},{"en":"If colour vision changes appear with liver disease, the cause may be medical rather than inherited.","zh":"如果色覺改變與肝病一起出現，成因可能是醫療問題而非遺傳。"},{"en":"The phrase names one physical disorder linked in the passage.","zh":"這個短語指出本文提到的一種相關身體疾病。"}],"source":"77 - Colour Blindness.pdf","sourcePage":10},{"front":"diabetes","meaning":"糖尿病","examples":[{"en":"Some colour vision problems may accompany diabetes.","zh":"有些色覺問題可能伴隨糖尿病。"},{"en":"Diabetes is a disease in which the body has difficulty controlling blood sugar.","zh":"糖尿病是一種身體難以控制血糖的疾病。"},{"en":"People with diabetes may need regular eye checks.","zh":"糖尿病患者可能需要定期眼睛檢查。"},{"en":"If diabetes affects the eyes, vision changes may appear over time.","zh":"如果糖尿病影響眼睛，視力變化可能隨時間出現。"},{"en":"The phrase names another physical disorder connected with acquired colour problems.","zh":"這個短語指出另一種與後天性色覺問題相關的身體疾病。"}],"source":"77 - Colour Blindness.pdf","sourcePage":10},{"front":"the rarest form of all","meaning":"最罕見的形式","examples":[{"en":"The rarest form of all is total colour blindness.","zh":"最罕見的形式是全色盲。"},{"en":"The rarest form of all means the least common type among every type mentioned.","zh":"「the rarest form of all」意思是在所有提到的類型中最少見的一種。"},{"en":"In a class, the rarest hobby of all may be fencing if only one student does it.","zh":"在班上，如果只有一名學生學劍擊，劍擊可能是最罕見的興趣。"},{"en":"If a condition is the rarest form, very few people experience it.","zh":"如果某狀況是最罕見的形式，經歷它的人非常少。"},{"en":"The phrase identifies the most uncommon category.","zh":"這個短語指出最不常見的類別。"}],"source":"77 - Colour Blindness.pdf","sourcePage":10},{"front":"total colour blindness","meaning":"全色盲","examples":[{"en":"Total colour blindness is also called monochromacy.","zh":"全色盲也稱為單色視。"},{"en":"Total colour blindness is a condition in which a person cannot see colour at all.","zh":"全色盲是一種完全不能看見顏色的狀況。"},{"en":"A person with total colour blindness may see the world in shades of grey.","zh":"全色盲人士可能以灰色深淺看見世界。"},{"en":"If no colour is perceived, daily tasks may depend heavily on brightness and labels.","zh":"如果完全不能感知顏色，日常任務可能高度依賴明暗和標籤。"},{"en":"The phrase refers to complete loss of colour vision.","zh":"這個短語指色覺完全喪失。"}],"source":"77 - Colour Blindness.pdf","sourcePage":10},{"front":"monochromacy","meaning":"單色視","examples":[{"en":"Monochromacy allows a person to see only shades of black, grey and white.","zh":"單色視使人只能看見黑、灰、白的不同深淺。"},{"en":"Monochromacy is a form of vision with only one colour dimension.","zh":"單色視是一種只有一個顏色維度的視覺形式。"},{"en":"A monochrome photo gives a rough idea of seeing without full colour.","zh":"單色照片大致能讓人理解沒有完整色彩的視覺。"},{"en":"If someone has monochromacy, colour-coded signs may be very difficult to use.","zh":"如果某人有單色視，顏色編碼標誌可能非常難用。"},{"en":"The word literally relates to one-colour vision.","zh":"這個詞字面上與單一顏色視覺有關。"}],"source":"77 - Colour Blindness.pdf","sourcePage":10},{"front":"shades of black, grey and white","meaning":"黑、灰、白的不同深淺","examples":[{"en":"People with monochromacy can see only shades of black, grey and white.","zh":"有單色視的人只能看見黑、灰、白的不同深淺。"},{"en":"Shades of black, grey and white are different levels of darkness and lightness without colour.","zh":"「shades of black, grey and white」是沒有顏色的不同明暗層次。"},{"en":"An old black-and-white photograph shows many grey shades between black and white.","zh":"舊黑白照片展示黑白之間許多灰色層次。"},{"en":"If vision is limited to these shades, colour names may not match what the person sees.","zh":"如果視覺只限於這些深淺，顏色名稱可能與此人所見不相符。"},{"en":"The phrase describes vision based on lightness rather than colour.","zh":"這個短語描述基於明度而非顏色的視覺。"}],"source":"77 - Colour Blindness.pdf","sourcePage":11},{"front":"as in","meaning":"就像……一樣","examples":[{"en":"They see only shades of black, grey and white, as in a black-and-white film.","zh":"他們只能看見黑、灰、白的不同深淺，就像黑白電影一樣。"},{"en":"As in means like in a particular example or situation.","zh":"「as in」意思是就像某個例子或情況中一樣。"},{"en":"Students may work in pairs, as in the previous speaking activity.","zh":"學生可以兩人一組活動，就像之前的口語活動一樣。"},{"en":"If a writer says “as in a film,” the example helps readers imagine the experience.","zh":"如果作者說「像電影一樣」，這個例子幫助讀者想像該經驗。"},{"en":"The phrase introduces comparison by example.","zh":"這個短語透過例子引入比較。"}],"source":"77 - Colour Blindness.pdf","sourcePage":11},{"front":"a black-and-white film","meaning":"黑白電影","examples":[{"en":"Monochromacy makes the world look like a black-and-white film.","zh":"單色視令世界看起來像黑白電影。"},{"en":"A black-and-white film is a film shown without colour, using only black, white and grey tones.","zh":"黑白電影是沒有顏色、只使用黑白灰色調的電影。"},{"en":"Old movies were often black-and-white films before colour filming became common.","zh":"在彩色拍攝普及前，舊電影常是黑白電影。"},{"en":"If vision resembles a black-and-white film, colour information is absent.","zh":"如果視覺像黑白電影，顏色資訊就是缺失的。"},{"en":"The phrase gives a familiar image for total colour blindness.","zh":"這個短語為全色盲提供熟悉圖像。"}],"source":"77 - Colour Blindness.pdf","sourcePage":11},{"front":"occur when","meaning":"在……時發生","examples":[{"en":"Monochromacy occurs when two or all three cone pigments are missing.","zh":"當兩種或全部三種視錐色素缺失時，單色視就會發生。"},{"en":"Occur when means happen under a particular condition.","zh":"「occur when」意思是在某特定條件下發生。"},{"en":"Traffic jams often occur when heavy rain slows buses and cars.","zh":"當大雨令巴士和汽車減速時，交通擠塞常會發生。"},{"en":"If a condition occurs when pigments are missing, the missing pigments are the trigger.","zh":"如果某狀況在色素缺失時發生，缺失色素就是觸發因素。"},{"en":"The phrase introduces the situation that causes an event.","zh":"這個短語引入導致事件的情況。"}],"source":"77 - Colour Blindness.pdf","sourcePage":11},{"front":"two or all three of","meaning":"兩種或全部三種……","examples":[{"en":"Monochromacy occurs when two or all three of the cone pigments are missing.","zh":"當兩種或全部三種視錐色素缺失時，單色視就會出現。"},{"en":"Two or all three of something means either two items or the whole set of three.","zh":"「two or all three of」某物，意思是兩項或三項全部。"},{"en":"A student may miss two or all three of the required books.","zh":"學生可能缺少兩本或全部三本所需書籍。"},{"en":"If two or all three pigments are missing, colour vision becomes severely limited.","zh":"如果兩種或全部三種色素缺失，色覺會變得嚴重受限。"},{"en":"The phrase gives two possible quantities.","zh":"這個短語提供兩種可能數量。"}],"source":"77 - Colour Blindness.pdf","sourcePage":11},{"front":"colour and lightness vision","meaning":"色彩與明度視覺","examples":[{"en":"In monochromacy, colour and lightness vision is reduced to one dimension.","zh":"在單色視中，色彩與明度視覺被減至一個維度。"},{"en":"Colour and lightness vision means seeing both colour differences and differences in brightness.","zh":"「colour and lightness vision」意思是同時看見顏色差異和亮度差異。"},{"en":"A black-and-white photo still shows lightness vision even without colour.","zh":"黑白照片即使沒有顏色，仍顯示明度視覺。"},{"en":"If colour vision is lost, lightness differences may remain important.","zh":"如果色覺喪失，明暗差異可能仍然重要。"},{"en":"The phrase combines colour perception with brightness perception.","zh":"這個短語把顏色感知與亮度感知結合起來。"}],"source":"77 - Colour Blindness.pdf","sourcePage":11},{"front":"be reduced to one dimension","meaning":"被減至一個維度","examples":[{"en":"In total colour blindness, vision is reduced to one dimension.","zh":"在全色盲中，視覺被減至一個維度。"},{"en":"To be reduced to one dimension means to become limited to one basic type of information.","zh":"「be reduced to one dimension」意思是被限制為一種基本資訊。"},{"en":"A complex report may be reduced to one number if only the final score is shown.","zh":"如果只顯示最終分數，複雜報告可能被減至一個數字。"},{"en":"If colour and lightness are reduced to one dimension, visual experience becomes much simpler.","zh":"如果色彩和明度被減至一個維度，視覺經驗會變得簡化很多。"},{"en":"The phrase describes severe simplification.","zh":"這個短語描述嚴重簡化。"}],"source":"77 - Colour Blindness.pdf","sourcePage":11},{"front":"another term for","meaning":"……的另一個術語","examples":[{"en":"Another term for total colour blindness is achromatopsia.","zh":"全色盲的另一個術語是 achromatopsia。"},{"en":"Another term for something is another word or phrase with the same or similar meaning.","zh":"「another term for」某物，是與它意思相同或相近的另一個字或短語。"},{"en":"Another term for a doctor is physician in some contexts.","zh":"在某些語境中，doctor 的另一個術語是 physician。"},{"en":"If students learn another term for a condition, they can recognise it in different texts.","zh":"如果學生學會某狀況的另一個術語，他們可以在不同文本中認出它。"},{"en":"The phrase introduces an alternative name.","zh":"這個短語引入另一名稱。"}],"source":"77 - Colour Blindness.pdf","sourcePage":11},{"front":"achromatopsia","meaning":"全色盲；色覺缺失","examples":[{"en":"Achromatopsia means the inability to see colour.","zh":"Achromatopsia 意思是無法看見顏色。"},{"en":"Achromatopsia is total or near-total lack of colour vision.","zh":"Achromatopsia 是完全或接近完全缺乏色覺。"},{"en":"A medical text may use achromatopsia instead of the everyday phrase total colour blindness.","zh":"醫學文本可能使用 achromatopsia，而不是日常說法 total colour blindness。"},{"en":"If someone has achromatopsia, the world may appear in black, white and grey tones.","zh":"如果某人有 achromatopsia，世界可能以黑、白、灰色調呈現。"},{"en":"The word is a technical medical term.","zh":"這個詞是技術性醫學術語。"}],"source":"77 - Colour Blindness.pdf","sourcePage":11},{"front":"the inability to see colour","meaning":"無法看見顏色","examples":[{"en":"Achromatopsia is the inability to see colour.","zh":"Achromatopsia 是無法看見顏色。"},{"en":"The inability to see colour means not being able to perceive colours.","zh":"「the inability to see colour」意思是不能感知顏色。"},{"en":"A person with this inability may rely on brightness, shape and position.","zh":"有這種能力缺失的人可能依賴亮度、形狀和位置。"},{"en":"If colour cannot be seen, colour-coded warnings become less useful.","zh":"如果不能看見顏色，顏色編碼警告就變得較不有用。"},{"en":"The phrase directly explains total colour blindness.","zh":"這個短語直接解釋全色盲。"}],"source":"77 - Colour Blindness.pdf","sourcePage":11},{"front":"inherited colour vision problems","meaning":"遺傳性色覺問題","examples":[{"en":"Inherited colour vision problems cannot be treated or corrected.","zh":"遺傳性色覺問題不能治療或矯正。"},{"en":"Inherited colour vision problems are colour-vision difficulties passed through genes.","zh":"遺傳性色覺問題是透過基因傳遞的色覺困難。"},{"en":"A child may discover an inherited colour problem during a school eye test.","zh":"孩子可能在學校眼睛測試中發現遺傳性色覺問題。"},{"en":"If a problem is inherited, surgery may not change the genetic cause.","zh":"如果問題是遺傳的，手術可能不能改變基因成因。"},{"en":"The phrase contrasts with acquired colour vision problems.","zh":"這個短語與後天性色覺問題形成對比。"}],"source":"77 - Colour Blindness.pdf","sourcePage":11},{"front":"cannot be treated or corrected","meaning":"不能治療或矯正","examples":[{"en":"Inherited colour vision problems cannot be treated or corrected.","zh":"遺傳性色覺問題不能治療或矯正。"},{"en":"Cannot be treated or corrected means there is no medical method to cure or fix it fully.","zh":"「cannot be treated or corrected」意思是沒有醫療方法能完全治癒或修正它。"},{"en":"Some learning differences cannot be removed, but support can help students manage them.","zh":"有些學習差異不能被消除，但支援可以幫助學生應對。"},{"en":"If inherited colour blindness cannot be corrected, practical strategies become important.","zh":"如果遺傳性色盲不能矯正，實用策略就變得重要。"},{"en":"The phrase distinguishes cure from support.","zh":"這個短語把治癒與支援區分開。"}],"source":"77 - Colour Blindness.pdf","sourcePage":12},{"front":"acquired colour vision problems","meaning":"後天性色覺問題","examples":[{"en":"Some acquired colour vision problems can be treated with surgery.","zh":"有些後天性色覺問題可以透過手術治療。"},{"en":"Acquired colour vision problems are colour difficulties that develop after birth.","zh":"後天性色覺問題是出生後形成的色覺困難。"},{"en":"A person may acquire a colour vision problem after eye disease or injury.","zh":"一個人可能在眼疾或受傷後形成色覺問題。"},{"en":"If the cause is treatable, the colour problem may improve.","zh":"如果成因可治療，色覺問題可能改善。"},{"en":"The phrase contrasts with inherited problems.","zh":"這個短語與遺傳性問題形成對比。"}],"source":"77 - Colour Blindness.pdf","sourcePage":12},{"front":"be treated with surgery","meaning":"透過手術治療","examples":[{"en":"Some acquired colour vision problems can be treated with surgery.","zh":"有些後天性色覺問題可以透過手術治療。"},{"en":"To be treated with surgery means to be improved or corrected through an operation.","zh":"「be treated with surgery」意思是透過手術改善或矯正。"},{"en":"A cataract can sometimes be treated with surgery by removing the cloudy lens.","zh":"白內障有時可以透過移除混濁晶狀體的手術治療。"},{"en":"If a colour problem comes from a removable eye condition, surgery may help.","zh":"如果色覺問題來自可移除的眼部狀況，手術可能有幫助。"},{"en":"The phrase describes one possible medical treatment route.","zh":"這個短語描述一種可能的醫療治療途徑。"}],"source":"77 - Colour Blindness.pdf","sourcePage":12},{"front":"the removal of a cataract","meaning":"白內障切除","examples":[{"en":"The removal of a cataract may treat some acquired colour vision problems.","zh":"白內障切除可能治療一些後天性色覺問題。"},{"en":"The removal of a cataract is surgery to take away a cloudy lens in the eye.","zh":"白內障切除是移除眼中混濁晶狀體的手術。"},{"en":"Older patients may have cataract removal when cloudy vision affects daily life.","zh":"當混濁視力影響日常生活，年長病人可能接受白內障切除。"},{"en":"If a cataract changes colour perception, removing it may improve vision.","zh":"如果白內障改變色彩感知，切除它可能改善視力。"},{"en":"The phrase names a specific surgical treatment.","zh":"這個短語指出一種特定手術治療。"}],"source":"77 - Colour Blindness.pdf","sourcePage":12},{"front":"depending on the cause","meaning":"視乎成因而定","examples":[{"en":"Treatment may be possible depending on the cause.","zh":"治療是否可能視乎成因而定。"},{"en":"Depending on the cause means the answer changes according to what created the problem.","zh":"「depending on the cause」意思是答案會根據造成問題的原因而改變。"},{"en":"A stomachache may need different treatment depending on the cause.","zh":"胃痛可能視乎成因而需要不同治療。"},{"en":"If colour problems are caused by disease rather than genes, treatment may be possible.","zh":"如果色覺問題由疾病而非基因造成，治療可能可行。"},{"en":"The phrase reminds us that causes matter.","zh":"這個短語提醒我們成因很重要。"}],"source":"77 - Colour Blindness.pdf","sourcePage":12},{"front":"tinted filters","meaning":"有色濾光片","examples":[{"en":"Tinted filters may help some people distinguish colours better.","zh":"有色濾光片可能幫助一些人更好地分辨顏色。"},{"en":"Tinted filters are coloured lenses or screens that change how light reaches the eye.","zh":"有色濾光片是改變光線到達眼睛方式的彩色鏡片或屏幕。"},{"en":"Some people use tinted glasses to reduce glare from bright screens.","zh":"有些人使用有色眼鏡來減少明亮屏幕的眩光。"},{"en":"If a filter changes contrast, colours may become easier to tell apart.","zh":"如果濾光片改變對比，顏色可能變得較容易分辨。"},{"en":"The phrase refers to a support tool, not a cure.","zh":"這個短語指支援工具，而不是治療方法。"}],"source":"77 - Colour Blindness.pdf","sourcePage":12},{"front":"contact lenses","meaning":"隱形眼鏡","examples":[{"en":"Special contact lenses may help an individual distinguish colours better.","zh":"特別隱形眼鏡可能幫助個人更好地分辨顏色。"},{"en":"Contact lenses are thin lenses worn directly on the eye.","zh":"隱形眼鏡是直接戴在眼睛上的薄鏡片。"},{"en":"Some people wear contact lenses instead of glasses for sports or daily convenience.","zh":"有些人為了運動或日常方便而戴隱形眼鏡代替眼鏡。"},{"en":"If special lenses change colour contrast, they may help some colour-blind users.","zh":"如果特別鏡片改變顏色對比，它們可能幫助一些色盲使用者。"},{"en":"The phrase refers to a vision aid placed on the eye.","zh":"這個短語指放在眼睛上的視力輔助工具。"}],"source":"77 - Colour Blindness.pdf","sourcePage":12},{"front":"help an individual to","meaning":"幫助個人去","examples":[{"en":"Tinted filters may help an individual to distinguish colours better.","zh":"有色濾光片可能幫助個人去更好地分辨顏色。"},{"en":"To help an individual to do something means to support one person in doing it.","zh":"「help an individual to」做某事，意思是支援一個人去完成它。"},{"en":"A tutor can help an individual to improve pronunciation through personal feedback.","zh":"導師可以透過個人回饋幫助個人改善發音。"},{"en":"If a tool helps one individual, it may not work equally well for everyone.","zh":"如果工具幫到某個人，它未必對每個人同樣有效。"},{"en":"The phrase focuses on personal support.","zh":"這個短語集中於個人支援。"}],"source":"77 - Colour Blindness.pdf","sourcePage":12},{"front":"distinguish different colours better","meaning":"更好地分辨不同顏色","examples":[{"en":"Contact lenses may help some people distinguish different colours better.","zh":"隱形眼鏡可能幫助一些人更好地分辨不同顏色。"},{"en":"To distinguish different colours better means to tell colours apart more accurately.","zh":"「distinguish different colours better」意思是更準確地分辨顏色。"},{"en":"A clearer screen can help students distinguish different map colours better.","zh":"更清晰的屏幕可以幫助學生更好地分辨地圖上的不同顏色。"},{"en":"If colours are easier to distinguish, daily mistakes may decrease.","zh":"如果顏色較容易分辨，日常錯誤可能減少。"},{"en":"The phrase describes improvement in colour separation.","zh":"這個短語描述分辨顏色能力的改善。"}],"source":"77 - Colour Blindness.pdf","sourcePage":12},{"front":"computer software","meaning":"電腦軟件","examples":[{"en":"Computer software has been developed to assist people with colour-vision difficulties.","zh":"電腦軟件已被開發來協助有色覺困難的人。"},{"en":"Computer software is a program or app that makes a computer perform tasks.","zh":"電腦軟件是令電腦執行任務的程式或應用程式。"},{"en":"A phone app can change colours on a screen to help users read charts.","zh":"電話應用程式可以改變屏幕顏色，幫助使用者閱讀圖表。"},{"en":"If software labels colours, colour-blind users can understand visual information more easily.","zh":"如果軟件標示顏色，色盲使用者可以更容易理解視覺資訊。"},{"en":"The phrase refers to digital tools rather than physical lenses.","zh":"這個短語指數碼工具，而不是實體鏡片。"}],"source":"77 - Colour Blindness.pdf","sourcePage":12},{"front":"be developed to assist","meaning":"被開發來協助","examples":[{"en":"Software has been developed to assist people with colour-vision difficulties.","zh":"軟件已被開發來協助有色覺困難的人。"},{"en":"To be developed to assist means to be created in order to help.","zh":"「be developed to assist」意思是被創造出來以提供幫助。"},{"en":"A school app may be developed to assist students with homework planning.","zh":"學校應用程式可能被開發來協助學生規劃功課。"},{"en":"If software is developed to assist colour-blind users, it should solve real daily problems.","zh":"如果軟件被開發來協助色盲使用者，它應解決真實日常問題。"},{"en":"The phrase explains the purpose behind creating something.","zh":"這個短語解釋創造某物背後的目的。"}],"source":"77 - Colour Blindness.pdf","sourcePage":12},{"front":"colour-vision difficulties","meaning":"色覺困難","examples":[{"en":"Computer software can assist people with colour-vision difficulties.","zh":"電腦軟件可以協助有色覺困難的人。"},{"en":"Colour-vision difficulties are problems with seeing or distinguishing colours.","zh":"色覺困難是看見或分辨顏色方面的問題。"},{"en":"A student with colour-vision difficulties may struggle with red-green science diagrams.","zh":"有色覺困難的學生可能難以閱讀紅綠色科學圖表。"},{"en":"If colour-vision difficulties are not considered, signs and charts may exclude some users.","zh":"如果不考慮色覺困難，標誌和圖表可能排除部分使用者。"},{"en":"The phrase is a broad, neutral way to describe colour-related visual problems.","zh":"這個短語是描述顏色相關視覺問題的廣義中性說法。"}],"source":"77 - Colour Blindness.pdf","sourcePage":13},{"front":"mild colour deficiencies","meaning":"輕微色覺缺陷","examples":[{"en":"People with mild colour deficiencies can often learn colour associations.","zh":"有輕微色覺缺陷的人通常可以學會顏色聯想。"},{"en":"Mild colour deficiencies are small or less severe problems with colour vision.","zh":"輕微色覺缺陷是較小或較不嚴重的色覺問題。"},{"en":"A person with a mild deficiency may manage daily life by remembering labels and patterns.","zh":"有輕微缺陷的人可能靠記住標籤和圖案來應付日常生活。"},{"en":"If the deficiency is mild, practical learning strategies can work well.","zh":"如果缺陷輕微，實用學習策略可以很有效。"},{"en":"The phrase suggests difficulty, not complete colour loss.","zh":"這個短語暗示困難，而不是完全失去顏色視覺。"}],"source":"77 - Colour Blindness.pdf","sourcePage":13},{"front":"learn to associate","meaning":"學會把……聯繫起來","examples":[{"en":"Some people learn to associate colours with certain objects.","zh":"有些人學會把顏色與某些物件聯繫起來。"},{"en":"To learn to associate one thing with another means to connect them in memory.","zh":"「learn to associate」一物與另一物，意思是在記憶中把它們連接起來。"},{"en":"Children learn to associate a red sign with stopping at a crossing.","zh":"孩子學會把紅色標誌與在過路處停下聯繫起來。"},{"en":"If a colour-blind person associates traffic-light positions with meanings, driving can become easier.","zh":"如果色盲人士把交通燈位置與意思聯繫起來，駕駛會變得較容易。"},{"en":"The phrase describes learning a useful connection.","zh":"這個短語描述學會有用聯繫。"}],"source":"77 - Colour Blindness.pdf","sourcePage":13},{"front":"identify colour","meaning":"辨認顏色","examples":[{"en":"People with mild deficiencies may identify colour in the same way as everyone else.","zh":"有輕微缺陷的人可能以與其他人相同的方式辨認顏色。"},{"en":"To identify colour means to recognise and name the colour correctly.","zh":"「identify colour」意思是正確認出並說出顏色。"},{"en":"A child may identify colour by saying that an apple is red.","zh":"孩子說蘋果是紅色，就是在辨認顏色。"},{"en":"If someone uses context clues, they may identify colour even when perception is imperfect.","zh":"如果某人使用語境線索，即使感知不完美，也可能辨認顏色。"},{"en":"The phrase focuses on naming or recognising colours.","zh":"這個短語集中於說出或認出顏色。"}],"source":"77 - Colour Blindness.pdf","sourcePage":13},{"front":"in the same way as","meaning":"以與……相同的方式","examples":[{"en":"Some people identify colour in the same way as everyone else.","zh":"有些人以與其他人相同的方式辨認顏色。"},{"en":"In the same way as means using the same method or pattern.","zh":"「in the same way as」意思是使用相同方法或模式。"},{"en":"A student may solve a maths problem in the same way as the teacher demonstrated.","zh":"學生可能以老師示範的相同方式解數學題。"},{"en":"If colour-blind people use memory and context, they may act in the same way as others.","zh":"如果色盲人士使用記憶和語境，他們可能以與他人相同的方式行動。"},{"en":"The phrase compares methods or behaviour.","zh":"這個短語比較方法或行為。"}],"source":"77 - Colour Blindness.pdf","sourcePage":13},{"front":"one frequent problem involves","meaning":"一個常見問題涉及","examples":[{"en":"One frequent problem involves traffic lights.","zh":"一個常見問題涉及交通燈。"},{"en":"One frequent problem involves something means a common difficulty is connected with it.","zh":"「one frequent problem involves」某事，意思是一個常見困難與它有關。"},{"en":"One frequent problem in online lessons involves poor internet connection.","zh":"網課中的一個常見問題涉及網絡連線差。"},{"en":"If a problem involves traffic lights, safety can become an issue.","zh":"如果問題涉及交通燈，安全就可能成為問題。"},{"en":"The phrase introduces a common example of difficulty.","zh":"這個短語引入常見困難例子。"}],"source":"77 - Colour Blindness.pdf","sourcePage":13},{"front":"traffic lights","meaning":"交通燈","examples":[{"en":"Colour-blind people generally know the positions of colours on traffic lights.","zh":"色盲人士一般知道交通燈上顏色的位置。"},{"en":"Traffic lights are road signals that use colours to control vehicles and pedestrians.","zh":"交通燈是用顏色控制車輛和行人的道路信號。"},{"en":"Drivers stop at red traffic lights and go when the light turns green.","zh":"司機在紅色交通燈前停下，綠燈時前行。"},{"en":"If colour is difficult to see, the fixed position of traffic lights can help.","zh":"如果顏色難以看見，交通燈的固定位置可以幫忙。"},{"en":"The phrase refers to a common colour-coded public signal.","zh":"這個短語指常見的顏色編碼公共信號。"}],"source":"77 - Colour Blindness.pdf","sourcePage":13},{"front":"worst of all","meaning":"最糟糕的是","examples":[{"en":"Worst of all, warning lights can be difficult for colour-blind people.","zh":"最糟糕的是，警示燈對色盲人士來說可能很難辨認。"},{"en":"Worst of all introduces the most serious or troubling point.","zh":"「worst of all」引出最嚴重或最令人困擾的一點。"},{"en":"The homework was long, the instructions were unclear, and worst of all, the deadline was tomorrow.","zh":"功課很長，指示不清楚，而最糟糕的是，截止日期是明天。"},{"en":"If a colour problem affects warning lights, the result may be dangerous.","zh":"如果色覺問題影響警示燈，結果可能很危險。"},{"en":"The phrase marks the biggest concern in a list.","zh":"這個短語標示清單中最大問題。"}],"source":"77 - Colour Blindness.pdf","sourcePage":13},{"front":"warning lights","meaning":"警示燈","examples":[{"en":"Warning lights present a serious problem for colour-blind people.","zh":"警示燈對色盲人士構成嚴重問題。"},{"en":"Warning lights are lights that signal danger, caution or the need to act.","zh":"警示燈是表示危險、注意或需要行動的燈號。"},{"en":"A car dashboard uses warning lights to show engine or battery problems.","zh":"汽車儀表板使用警示燈顯示引擎或電池問題。"},{"en":"If warning lights rely only on colour, colour-blind people may miss important information.","zh":"如果警示燈只依賴顏色，色盲人士可能錯過重要資訊。"},{"en":"The phrase refers to safety-related light signals.","zh":"這個短語指與安全相關的燈光信號。"}],"source":"77 - Colour Blindness.pdf","sourcePage":13},{"front":"generally know","meaning":"一般知道","examples":[{"en":"Colour-blind people generally know the positions of colours on traffic lights.","zh":"色盲人士一般知道交通燈上顏色的位置。"},{"en":"Generally know means usually know or know in most situations.","zh":"「generally know」意思是通常知道或在大多數情況下知道。"},{"en":"Students generally know school starts at 8 a.m., even if they sometimes arrive late.","zh":"學生一般知道學校八點開始，即使他們有時遲到。"},{"en":"If people generally know the position of traffic-light colours, they can use placement as a clue.","zh":"如果人們一般知道交通燈顏色的位置，他們可以用位置作線索。"},{"en":"The phrase describes common knowledge, not perfect knowledge.","zh":"這個短語描述普遍知道，而不是完美知道。"}],"source":"77 - Colour Blindness.pdf","sourcePage":13},{"front":"the positions of colours","meaning":"顏色的位置","examples":[{"en":"Colour-blind people remember the positions of colours on traffic lights.","zh":"色盲人士記住交通燈上顏色的位置。"},{"en":"The positions of colours are the fixed places where different colours appear.","zh":"顏色的位置是不同顏色出現的固定地方。"},{"en":"On many traffic lights, red, yellow and green have standard positions.","zh":"在許多交通燈上，紅、黃、綠有標準位置。"},{"en":"If colour is hard to identify, position can become a useful substitute clue.","zh":"如果顏色難以辨認，位置可以成為有用替代線索。"},{"en":"The phrase links colour information with location.","zh":"這個短語把顏色資訊與位置連繫起來。"}],"source":"77 - Colour Blindness.pdf","sourcePage":13},{"front":"at the top","meaning":"在頂部","examples":[{"en":"Red is at the top of a traffic light.","zh":"紅色在交通燈頂部。"},{"en":"At the top means in the highest position.","zh":"「at the top」意思是在最高位置。"},{"en":"A school notice may put the most important date at the top of the page.","zh":"學校通告可能把最重要日期放在頁面頂部。"},{"en":"If red is at the top, drivers can recognise it by position even when colour is unclear.","zh":"如果紅色在頂部，司機即使看不清顏色，也可以靠位置辨認它。"},{"en":"The phrase gives a vertical location.","zh":"這個短語提供垂直位置。"}],"source":"77 - Colour Blindness.pdf","sourcePage":14},{"front":"in the centre","meaning":"在中間","examples":[{"en":"Yellow is in the centre of a traffic light.","zh":"黃色在交通燈中間。"},{"en":"In the centre means in the middle position.","zh":"「in the centre」意思是在中間位置。"},{"en":"The title is often placed in the centre of a poster.","zh":"標題常放在海報中間。"},{"en":"If yellow is in the centre, its position helps people identify it.","zh":"如果黃色在中間，其位置能幫助人辨認它。"},{"en":"The phrase describes a middle location.","zh":"這個短語描述中間位置。"}],"source":"77 - Colour Blindness.pdf","sourcePage":14},{"front":"at the bottom","meaning":"在底部","examples":[{"en":"Green is at the bottom of a traffic light.","zh":"綠色在交通燈底部。"},{"en":"At the bottom means in the lowest position.","zh":"「at the bottom」意思是在最低位置。"},{"en":"A signature usually appears at the bottom of a letter.","zh":"簽名通常出現在信件底部。"},{"en":"If green is at the bottom, position can help colour-blind drivers recognise the signal.","zh":"如果綠色在底部，位置可以幫助色盲司機辨認信號。"},{"en":"The phrase gives the lower location.","zh":"這個短語提供下方位置。"}],"source":"77 - Colour Blindness.pdf","sourcePage":14},{"front":"present an entirely different problem","meaning":"帶來完全不同的問題","examples":[{"en":"Warning lights present an entirely different problem.","zh":"警示燈帶來完全不同的問題。"},{"en":"To present an entirely different problem means to create a separate and more distinct difficulty.","zh":"「present an entirely different problem」意思是造成另一個明顯不同的困難。"},{"en":"Online lessons solve travel problems but present an entirely different problem: poor internet.","zh":"網課解決交通問題，但帶來完全不同的問題：網絡差。"},{"en":"If warning lights have no fixed position, colour-blind people lose an important clue.","zh":"如果警示燈沒有固定位置，色盲人士就失去重要線索。"},{"en":"The phrase introduces a new type of difficulty.","zh":"這個短語引入新類型的困難。"}],"source":"77 - Colour Blindness.pdf","sourcePage":14},{"front":"no top or bottom","meaning":"沒有上下之分","examples":[{"en":"A warning light has no top or bottom to help identify its colour.","zh":"警示燈沒有上下之分來幫助辨認其顏色。"},{"en":"No top or bottom means there is no fixed upper or lower position to use as a clue.","zh":"「no top or bottom」意思是沒有固定上方或下方位置可作線索。"},{"en":"A single light on a machine has no top or bottom colour order like a traffic light.","zh":"機器上的單一燈號沒有像交通燈那樣的上下顏色次序。"},{"en":"If there is no position clue, colour alone may be difficult to identify.","zh":"如果沒有位置線索，單靠顏色可能難以辨認。"},{"en":"The phrase explains why warning lights are harder than traffic lights.","zh":"這個短語解釋為何警示燈比交通燈更難。"}],"source":"77 - Colour Blindness.pdf","sourcePage":14},{"front":"no right or left","meaning":"沒有左右之分","examples":[{"en":"A warning light has no right or left position to guide the viewer.","zh":"警示燈沒有左右位置來引導觀看者。"},{"en":"No right or left means there is no side position to help identify meaning.","zh":"「no right or left」意思是沒有側邊位置可幫助辨認意思。"},{"en":"A single round light gives no right-or-left clue like two labelled buttons might.","zh":"單一圓形燈不像兩個有標籤按鈕那樣提供左右線索。"},{"en":"If a signal has no position clue, users must depend more on colour.","zh":"如果信號沒有位置線索，使用者就更要依賴顏色。"},{"en":"The phrase describes missing spatial guidance.","zh":"這個短語描述缺少空間指引。"}],"source":"77 - Colour Blindness.pdf","sourcePage":14},{"front":"have a significant impact on","meaning":"對……有重大影響","examples":[{"en":"Colour vision problems can have a significant impact on a person’s life.","zh":"色覺問題可以對一個人的生活有重大影響。"},{"en":"To have a significant impact on something means to affect it in an important way.","zh":"「have a significant impact on」某事，意思是以重要方式影響它。"},{"en":"Poor sleep can have a significant impact on memory and mood.","zh":"睡眠不足可以對記憶和心情有重大影響。"},{"en":"If colour vision affects learning and work choices, its impact is significant.","zh":"如果色覺影響學習和工作選擇，其影響就是重大的。"},{"en":"The phrase describes a serious effect, not a minor detail.","zh":"這個短語描述嚴重影響，而不是小細節。"}],"source":"77 - Colour Blindness.pdf","sourcePage":14},{"front":"learning abilities","meaning":"學習能力","examples":[{"en":"Colour vision problems can affect learning abilities.","zh":"色覺問題可以影響學習能力。"},{"en":"Learning abilities are the skills people use to understand, remember and apply information.","zh":"學習能力是人用來理解、記憶和應用資訊的技能。"},{"en":"A student’s learning abilities may be affected if classroom materials rely only on colour.","zh":"如果課堂材料只依賴顏色，學生的學習能力可能受影響。"},{"en":"If diagrams are colour-coded without labels, colour-blind learners may miss important information.","zh":"如果圖表用顏色編碼卻沒有標籤，色盲學習者可能錯過重要資訊。"},{"en":"The phrase refers to ability to learn, not intelligence alone.","zh":"這個短語指學習能力，而不只是智力。"}],"source":"77 - Colour Blindness.pdf","sourcePage":14},{"front":"career choices","meaning":"職業選擇","examples":[{"en":"Colour vision problems can affect career choices.","zh":"色覺問題可以影響職業選擇。"},{"en":"Career choices are decisions about the kind of work someone wants to do.","zh":"職業選擇是關於某人想從事哪種工作的決定。"},{"en":"A student may consider eyesight requirements before choosing a transport or design career.","zh":"學生選擇交通或設計行業前，可能考慮視力要求。"},{"en":"If a job depends heavily on colour identification, colour blindness may limit options.","zh":"如果某工作高度依賴辨認顏色，色盲可能限制選項。"},{"en":"The phrase connects personal ability with future work.","zh":"這個短語把個人能力與未來工作連繫起來。"}],"source":"77 - Colour Blindness.pdf","sourcePage":14},{"front":"on an everyday basis","meaning":"在日常生活中","examples":[{"en":"Colour-blind people may face small problems on an everyday basis.","zh":"色盲人士可能在日常生活中面對小問題。"},{"en":"On an everyday basis means regularly in ordinary daily life.","zh":"「on an everyday basis」意思是在普通日常生活中經常地。"},{"en":"People use their phones on an everyday basis for messages and transport information.","zh":"人們在日常生活中使用電話傳訊和查交通資訊。"},{"en":"If small problems happen every day, they can become frustrating over time.","zh":"如果小問題每天發生，隨時間會變得令人挫折。"},{"en":"The phrase stresses ordinary daily frequency.","zh":"這個短語強調普通日常頻率。"}],"source":"77 - Colour Blindness.pdf","sourcePage":14},{"front":"annoyances and frustrations","meaning":"煩惱與挫折","examples":[{"en":"Colour blindness can cause everyday annoyances and frustrations.","zh":"色盲可以造成日常煩惱與挫折。"},{"en":"Annoyances and frustrations are small problems and feelings of irritation caused by difficulty.","zh":"「annoyances and frustrations」是由困難造成的小問題和煩躁感。"},{"en":"Losing your keys before school can create annoyance and frustration.","zh":"上學前遺失鎖匙可以造成煩惱和挫折。"},{"en":"If colour mistakes happen often, daily tasks can become irritating.","zh":"如果顏色錯誤經常發生，日常任務會變得令人煩躁。"},{"en":"The phrase describes repeated minor difficulties, not necessarily danger.","zh":"這個短語描述重複的小困難，不一定是危險。"}],"source":"77 - Colour Blindness.pdf","sourcePage":14},{"front":"differentiate between","meaning":"分辨……之間的差異","examples":[{"en":"Some colour-blind people cannot differentiate between unripe and ripe tomatoes.","zh":"有些色盲人士不能分辨未熟和成熟番茄之間的差異。"},{"en":"To differentiate between two things means to tell them apart.","zh":"「differentiate between」兩件事，意思是把它們分辨開來。"},{"en":"Students learn to differentiate between fact and opinion in reading lessons.","zh":"學生在閱讀課學習分辨事實與意見之間的差異。"},{"en":"If a person cannot differentiate between green and red tomatoes, food preparation may be harder.","zh":"如果某人不能分辨綠色和紅色番茄，準備食物可能更困難。"},{"en":"The phrase means distinguish clearly.","zh":"這個短語意思是清楚區分。"}],"source":"77 - Colour Blindness.pdf","sourcePage":15},{"front":"unripe green tomatoes","meaning":"未熟的綠色番茄","examples":[{"en":"Colour-blind people may confuse unripe green tomatoes with ripe red ones.","zh":"色盲人士可能把未熟的綠色番茄與成熟的紅色番茄混淆。"},{"en":"Unripe green tomatoes are tomatoes that are not yet fully mature and still green.","zh":"未熟的綠色番茄是尚未完全成熟、仍然呈綠色的番茄。"},{"en":"A cook may leave unripe green tomatoes on the counter until they become red.","zh":"廚師可能把未熟的綠色番茄放在桌上，直到它們變紅。"},{"en":"If green and red look similar, judging ripeness by colour becomes unreliable.","zh":"如果綠色和紅色看起來相似，靠顏色判斷成熟度就不可靠。"},{"en":"The phrase describes food before it is ready to eat.","zh":"這個短語描述未準備好食用的食物。"}],"source":"77 - Colour Blindness.pdf","sourcePage":15},{"front":"ripe red ones","meaning":"成熟的紅色番茄","examples":[{"en":"It may be difficult to tell unripe green tomatoes from ripe red ones.","zh":"分辨未熟的綠色番茄和成熟的紅色番茄可能很困難。"},{"en":"Ripe red ones means mature red tomatoes ready to eat.","zh":"「ripe red ones」意思是成熟、可食用的紅色番茄。"},{"en":"In a market, shoppers usually choose ripe red tomatoes for salad.","zh":"在市場中，購物者通常選成熟的紅色番茄做沙律。"},{"en":"If ripe red ones look like green ones to someone, colour is not a reliable clue.","zh":"如果成熟的紅色番茄在某人眼中像綠色番茄，顏色就不是可靠線索。"},{"en":"The phrase refers back to tomatoes without repeating the noun.","zh":"這個短語指回番茄，而不重複名詞。"}],"source":"77 - Colour Blindness.pdf","sourcePage":15},{"front":"when preparing food","meaning":"在準備食物時","examples":[{"en":"Colour blindness may cause problems when preparing food.","zh":"色盲可能在準備食物時造成問題。"},{"en":"When preparing food means while choosing, cooking or arranging food.","zh":"「when preparing food」意思是在選擇、烹調或擺放食物時。"},{"en":"A cook may check smell and firmness when preparing food, not just colour.","zh":"廚師在準備食物時可能檢查氣味和硬度，而不只看顏色。"},{"en":"If colour is hard to judge, it may be harder to tell whether food is ripe or cooked.","zh":"如果顏色難以判斷，就可能較難知道食物是否成熟或煮熟。"},{"en":"The phrase gives a practical daily context.","zh":"這個短語提供實際日常語境。"}],"source":"77 - Colour Blindness.pdf","sourcePage":15},{"front":"buying clothes","meaning":"買衣服","examples":[{"en":"Buying clothes can be difficult for people with colour vision problems.","zh":"對有色覺問題的人來說，買衣服可能很困難。"},{"en":"Buying clothes means choosing and purchasing clothing items.","zh":"「buying clothes」意思是選擇並購買衣物。"},{"en":"A shopper may ask a friend for help when buying clothes for a formal event.","zh":"購物者為正式活動買衣服時，可能請朋友幫忙。"},{"en":"If colours are hard to distinguish, matching shirts and trousers can become difficult.","zh":"如果顏色難以分辨，配襯恤衫和褲子會變得困難。"},{"en":"The phrase gives a common shopping example.","zh":"這個短語提供常見購物例子。"}],"source":"77 - Colour Blindness.pdf","sourcePage":15},{"front":"seem positively garish","meaning":"看起來非常俗艷刺眼","examples":[{"en":"Some clothes may seem positively garish to people with normal colour vision.","zh":"有些衣服對正常色覺人士來說可能看起來非常俗艷刺眼。"},{"en":"To seem positively garish means to look extremely bright, clashing or tasteless.","zh":"「seem positively garish」意思是看起來極度鮮艷、撞色或俗氣。"},{"en":"A neon green jacket with orange trousers may seem garish at a formal dinner.","zh":"螢光綠外套配橙色褲子，在正式晚宴上可能顯得俗艷刺眼。"},{"en":"If a colour-blind person mismatches clothes, others may see the outfit as too loud.","zh":"如果色盲人士配錯衣服，其他人可能覺得穿搭太刺眼。"},{"en":"The phrase is strongly critical of appearance.","zh":"這個短語對外觀有強烈批評意味。"}],"source":"77 - Colour Blindness.pdf","sourcePage":15},{"front":"compensate for","meaning":"彌補","examples":[{"en":"People with colour vision problems usually learn to compensate for their inability.","zh":"有色覺問題的人通常學會彌補自己的能力缺失。"},{"en":"To compensate for something means to make up for a weakness or difficulty.","zh":"「compensate for」某事，意思是彌補某個弱點或困難。"},{"en":"A student with poor hearing may sit near the front to compensate for it.","zh":"聽力較差的學生可能坐在前排來彌補。"},{"en":"If colour is unreliable, people may compensate by using labels, position or memory.","zh":"如果顏色不可靠，人們可能透過標籤、位置或記憶來彌補。"},{"en":"The phrase describes practical adjustment.","zh":"這個短語描述實際調整。"}],"source":"77 - Colour Blindness.pdf","sourcePage":15},{"front":"inability to see colours","meaning":"無法看見顏色的能力缺失","examples":[{"en":"People often compensate for their inability to see colours.","zh":"人們常彌補自己無法看見顏色的能力缺失。"},{"en":"Inability to see colours means not being able to perceive colours normally.","zh":"「inability to see colours」意思是不能正常感知顏色。"},{"en":"A person with this inability may ask others to label coloured objects.","zh":"有這種能力缺失的人可能請別人標示彩色物件。"},{"en":"If someone cannot see colours well, daily systems should not rely only on colour.","zh":"如果某人不能良好看見顏色，日常系統就不應只依賴顏色。"},{"en":"The phrase describes a limitation in colour perception.","zh":"這個短語描述色彩感知上的限制。"}],"source":"77 - Colour Blindness.pdf","sourcePage":15},{"front":"little or no treatment","meaning":"幾乎沒有治療方法","examples":[{"en":"There is little or no treatment for inherited colour blindness.","zh":"遺傳性色盲幾乎沒有治療方法。"},{"en":"Little or no treatment means very few or no effective medical options exist.","zh":"「little or no treatment」意思是有效醫療選項非常少或沒有。"},{"en":"For some long-term conditions, there may be little treatment but many coping strategies.","zh":"對某些長期狀況來說，治療方法可能很少，但有很多應對策略。"},{"en":"If treatment is limited, education and practical support become more important.","zh":"如果治療有限，教育和實用支援就變得更重要。"},{"en":"The phrase shows that medical correction is not usually available.","zh":"這個短語顯示通常沒有醫療矯正方法。"}],"source":"77 - Colour Blindness.pdf","sourcePage":15},{"front":"colour-deficient people","meaning":"色覺缺陷人士","examples":[{"en":"Colour-deficient people may learn to compensate well.","zh":"色覺缺陷人士可能學會很好地彌補。"},{"en":"Colour-deficient people are people whose colour vision is weaker or different from normal.","zh":"色覺缺陷人士是色覺比正常較弱或不同的人。"},{"en":"A colour-deficient student may use written labels on coloured pens.","zh":"色覺缺陷學生可能在彩色筆上使用文字標籤。"},{"en":"If materials are designed well, colour-deficient people can use them more easily.","zh":"如果材料設計良好，色覺缺陷人士可以更容易使用。"},{"en":"The phrase is a neutral way to describe people with colour vision differences.","zh":"這個短語是描述有色覺差異人士的中性說法。"}],"source":"77 - Colour Blindness.pdf","sourcePage":15},{"front":"compensate well for","meaning":"很好地彌補……","examples":[{"en":"Most colour-deficient people compensate well for their defect.","zh":"大多數色覺缺陷人士能很好地彌補其缺陷。"},{"en":"To compensate well for a defect means to manage a weakness effectively.","zh":"「compensate well for」某缺陷，意思是有效地應對某弱點。"},{"en":"A student with poor spelling may compensate well by using careful proofreading tools.","zh":"拼寫較弱的學生可能透過仔細使用校對工具來很好地彌補。"},{"en":"If people develop good routines, a vision defect may cause fewer daily problems.","zh":"如果人們建立良好習慣，視覺缺陷可能造成較少日常問題。"},{"en":"The phrase emphasises successful adaptation.","zh":"這個短語強調成功適應。"}],"source":"77 - Colour Blindness.pdf","sourcePage":15},{"front":"defect","meaning":"缺陷","examples":[{"en":"Colour-deficient people can compensate for their defect.","zh":"色覺缺陷人士可以彌補自己的缺陷。"},{"en":"A defect is a fault, weakness or missing function.","zh":"「defect」是故障、弱點或缺失功能。"},{"en":"A defect in a phone screen may make colours appear strange.","zh":"手機屏幕缺陷可能令顏色顯得奇怪。"},{"en":"If a visual defect cannot be cured, people may learn ways around it.","zh":"如果視覺缺陷不能治癒，人們可能學會繞過它的方法。"},{"en":"The word can sound clinical, so use it carefully when referring to people.","zh":"這個詞可能聽起來較醫學化，所以用來指人時要小心。"}],"source":"77 - Colour Blindness.pdf","sourcePage":16},{"front":"discover instances in which","meaning":"發現某些情況中","examples":[{"en":"Some colour-blind people discover instances in which they can see hidden details.","zh":"有些色盲人士發現某些情況中他們可以看見隱藏細節。"},{"en":"To discover instances in which something happens means to find particular situations where it occurs.","zh":"「discover instances in which」某事發生，意思是找到它發生的特定情況。"},{"en":"A student may discover instances in which drawing helps memory better than writing notes.","zh":"學生可能發現某些情況中畫圖比寫筆記更有助記憶。"},{"en":"If colour-blind people notice hidden patterns, their vision may be useful in special situations.","zh":"如果色盲人士注意到隱藏圖案，他們的視覺可能在特殊情況中有用。"},{"en":"The phrase points to specific examples, not a general rule.","zh":"這個短語指特定例子，而不是一般規則。"}],"source":"77 - Colour Blindness.pdf","sourcePage":16},{"front":"discern details and images","meaning":"辨認細節和圖像","examples":[{"en":"Colour-blind people may discern details and images others miss.","zh":"色盲人士可能辨認出其他人錯過的細節和圖像。"},{"en":"To discern details and images means to notice or recognise small features and shapes.","zh":"「discern details and images」意思是注意到或認出細小特徵和形狀。"},{"en":"A careful reader can discern small clues in a difficult passage.","zh":"細心讀者可以在困難文章中辨認細小線索。"},{"en":"If colour does not distract someone, hidden shapes may become easier to see.","zh":"如果顏色不會分散某人注意，隱藏形狀可能變得較容易看見。"},{"en":"The phrase describes careful visual recognition.","zh":"這個短語描述仔細的視覺辨認。"}],"source":"77 - Colour Blindness.pdf","sourcePage":16},{"front":"escape people with normal colour vision","meaning":"被正常色覺人士忽略","examples":[{"en":"Some details escape people with normal colour vision.","zh":"有些細節會被正常色覺人士忽略。"},{"en":"If details escape someone, they fail to notice them.","zh":"如果 details escape 某人，意思是他沒有注意到那些細節。"},{"en":"Small errors may escape a student who checks homework too quickly.","zh":"如果學生太快檢查功課，細小錯誤可能被他忽略。"},{"en":"If camouflage fools normal colour vision, hidden details may escape normal viewers.","zh":"如果偽裝色彩騙過正常色覺，隱藏細節可能被正常觀看者忽略。"},{"en":"The phrase means “are missed by”, not physically run away.","zh":"這個短語意思是「被忽略」，不是實際逃走。"}],"source":"77 - Colour Blindness.pdf","sourcePage":16},{"front":"at one time","meaning":"曾經；一度","examples":[{"en":"At one time, the US Army found an advantage in colour blindness.","zh":"曾經，美國陸軍發現色盲有一項優勢。"},{"en":"At one time means in the past, but not necessarily now.","zh":"「at one time」意思是在過去某時期，但不一定是現在。"},{"en":"At one time, many students wrote essays entirely by hand.","zh":"曾經，許多學生完全手寫作文。"},{"en":"If something was useful at one time, conditions may have changed later.","zh":"如果某物曾經有用，後來條件可能已改變。"},{"en":"The phrase places an event in an earlier period.","zh":"這個短語把事件放在較早時期。"}],"source":"77 - Colour Blindness.pdf","sourcePage":16},{"front":"the US Army","meaning":"美國陸軍","examples":[{"en":"The US Army found that colour-blind people could spot camouflage colours.","zh":"美國陸軍發現色盲人士有時能識破偽裝色彩。"},{"en":"The US Army is the land warfare branch of the United States military.","zh":"美國陸軍是美國軍隊中的陸戰部門。"},{"en":"The US Army may test soldiers’ vision for different field tasks.","zh":"美國陸軍可能為不同野外任務測試士兵視力。"},{"en":"If colour-blind people can detect camouflage, the army may find practical value in that ability.","zh":"如果色盲人士能偵測迷彩，軍隊可能發現這種能力有實用價值。"},{"en":"The phrase names the organisation in the example.","zh":"這個短語指出例子中的組織。"}],"source":"77 - Colour Blindness.pdf","sourcePage":16},{"front":"spot camouflage colours","meaning":"識破迷彩顏色","examples":[{"en":"Colour-blind people can sometimes spot camouflage colours.","zh":"色盲人士有時能識破迷彩顏色。"},{"en":"To spot camouflage colours means to notice colours used to hide objects or people.","zh":"「spot camouflage colours」意思是注意到用來隱藏物件或人的顏色。"},{"en":"A child may spot a hidden animal in a picture when others only see leaves.","zh":"孩子可能在圖片中認出隱藏動物，而其他人只看見樹葉。"},{"en":"If normal viewers are fooled by colour patterns, colour-blind viewers may notice shape differences.","zh":"如果正常觀看者被色彩圖案迷惑，色盲觀看者可能注意到形狀差異。"},{"en":"The phrase describes detecting something designed to be hidden.","zh":"這個短語描述偵測被設計成隱藏的東西。"}],"source":"77 - Colour Blindness.pdf","sourcePage":16},{"front":"camouflage colours","meaning":"偽裝色彩；迷彩顏色","examples":[{"en":"Camouflage colours may fool people with normal colour vision.","zh":"偽裝色彩可能迷惑有正常色覺的人。"},{"en":"Camouflage colours are colours used to help something blend into its surroundings.","zh":"偽裝色彩是用來幫助某物融入周圍環境的顏色。"},{"en":"Soldiers’ uniforms often use camouflage colours to match forests or deserts.","zh":"士兵制服常使用迷彩顏色來配合森林或沙漠。"},{"en":"If camouflage works well, people may not notice the hidden object.","zh":"如果偽裝效果好，人們可能注意不到隱藏物件。"},{"en":"The phrase refers to colours used for concealment.","zh":"這個短語指用於隱藏的顏色。"}],"source":"77 - Colour Blindness.pdf","sourcePage":16},{"front":"be fooled","meaning":"被蒙騙；被迷惑","examples":[{"en":"People with normal colour vision are sometimes fooled by camouflage colours.","zh":"有正常色覺的人有時會被偽裝色彩迷惑。"},{"en":"To be fooled means to be deceived or misled.","zh":"「be fooled」意思是被欺騙或誤導。"},{"en":"A student may be fooled by a trick question if he reads too quickly.","zh":"如果學生閱讀太快，可能被陷阱題迷惑。"},{"en":"If colours blend into the background, viewers may be fooled and miss the object.","zh":"如果顏色融入背景，觀看者可能被迷惑而看不到物件。"},{"en":"The phrase describes being misled by appearance.","zh":"這個短語描述被外觀誤導。"}],"source":"77 - Colour Blindness.pdf","sourcePage":16},{"front":"complete each sentence with","meaning":"用……完成每句句子","examples":[{"en":"Students complete each sentence with the correct ending.","zh":"學生用正確句尾完成每句句子。"},{"en":"To complete each sentence with something means to finish every sentence by adding the required part.","zh":"「complete each sentence with」某物，意思是加入所需部分來完成每句句子。"},{"en":"In grammar practice, students complete each sentence with the correct verb form.","zh":"在文法練習中，學生用正確動詞形式完成每句句子。"},{"en":"If the ending does not match the grammar or meaning, the sentence is wrong.","zh":"如果句尾不符合文法或意思，句子就是錯的。"},{"en":"The phrase is a common test instruction.","zh":"這個短語是常見測驗指示。"}],"source":"77 - Colour Blindness.pdf","sourcePage":16},{"front":"the correct ending","meaning":"正確句尾","examples":[{"en":"The task asks students to choose the correct ending for each sentence.","zh":"任務要求學生為每句句子選擇正確句尾。"},{"en":"The correct ending is the sentence ending that matches the meaning and grammar.","zh":"正確句尾是符合意思和文法的句子結尾。"},{"en":"Students must choose the correct ending so the sentence makes sense.","zh":"學生必須選擇正確句尾，使句子意思合理。"},{"en":"If two endings seem possible, the passage evidence should decide the answer.","zh":"如果兩個句尾看似可能，文章證據應決定答案。"},{"en":"The phrase refers to the final part of a sentence-completion answer.","zh":"這個短語指句子填充答案的最後部分。"}],"source":"77 - Colour Blindness.pdf","sourcePage":16},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Students write the correct letter in the spaces provided.","zh":"學生在提供的空格中寫上正確字母。"},{"en":"To write the correct letter means to record the option letter that matches the answer.","zh":"「write the correct letter」意思是寫下與答案相符的選項字母。"},{"en":"In a matching task, students may write A, B or C beside each question.","zh":"在配對題中，學生可能在每題旁寫 A、B 或 C。"},{"en":"If the idea is right but the letter is wrong, the answer may not be accepted.","zh":"如果意思正確但字母錯，答案可能不被接受。"},{"en":"The phrase gives a practical exam instruction.","zh":"這個短語給出實際考試指示。"}],"source":"77 - Colour Blindness.pdf","sourcePage":17},{"front":"people who are colour blind","meaning":"色盲人士","examples":[{"en":"People who are colour blind may face problems with warning lights.","zh":"色盲人士可能在警示燈方面遇到問題。"},{"en":"People who are colour blind have difficulty seeing or distinguishing some colours.","zh":"色盲人士在看見或分辨某些顏色方面有困難。"},{"en":"A colour-blind person may ask a friend whether a shirt is green or brown.","zh":"色盲人士可能問朋友一件恤衫是綠色還是啡色。"},{"en":"If public signs use only colour, colour-blind people may miss important information.","zh":"如果公共標誌只使用顏色，色盲人士可能錯過重要資訊。"},{"en":"The phrase describes people with colour vision differences.","zh":"這個短語描述有色覺差異的人。"}],"source":"77 - Colour Blindness.pdf","sourcePage":17},{"front":"hereditary colour blindness","meaning":"遺傳性色盲","examples":[{"en":"People with hereditary colour blindness cannot usually be treated by surgery.","zh":"有遺傳性色盲的人通常不能透過手術治療。"},{"en":"Hereditary colour blindness is colour blindness passed down through genes.","zh":"遺傳性色盲是透過基因傳下來的色盲。"},{"en":"A family may notice hereditary colour blindness when several male relatives have similar colour problems.","zh":"當幾名男性親屬有相似色覺問題時，家庭可能注意到遺傳性色盲。"},{"en":"If the cause is genetic, removing a cataract will not solve it.","zh":"如果成因是基因，切除白內障不能解決它。"},{"en":"The phrase means inherited colour blindness.","zh":"這個短語意思是 inherited colour blindness。"}],"source":"77 - Colour Blindness.pdf","sourcePage":17},{"front":"genetic make-up","meaning":"基因構成","examples":[{"en":"Because of our genetic make-up, colour blindness affects men more often than women.","zh":"由於我們的基因構成，色盲影響男性的頻率高於女性。"},{"en":"Genetic make-up means the set of genes a person has.","zh":"「genetic make-up」是一個人擁有的一套基因。"},{"en":"A person’s genetic make-up can influence eye colour, blood type and some health risks.","zh":"一個人的基因構成可以影響眼睛顏色、血型和某些健康風險。"},{"en":"If a condition is linked to genetic make-up, family patterns may appear.","zh":"如果某狀況與基因構成相關，家族模式可能出現。"},{"en":"The phrase refers to biological inheritance.","zh":"這個短語指生物遺傳。"}],"source":"77 - Colour Blindness.pdf","sourcePage":17},{"front":"affect men much more often than women","meaning":"影響男性的頻率遠高於女性","examples":[{"en":"Colour blindness affects men much more often than women.","zh":"色盲影響男性的頻率遠高於女性。"},{"en":"To affect men much more often than women means to occur in males far more frequently.","zh":"「affect men much more often than women」意思是在男性身上出現得遠比女性頻繁。"},{"en":"Some X-linked traits affect boys more often because boys usually have only one X chromosome.","zh":"有些 X 連鎖特徵較常影響男孩，因為男孩通常只有一條 X 染色體。"},{"en":"If males are affected more often, genetic inheritance patterns may explain the difference.","zh":"如果男性較常受影響，遺傳模式可能解釋這種差異。"},{"en":"The phrase compares frequency between sexes.","zh":"這個短語比較男女之間的出現頻率。"}],"source":"77 - Colour Blindness.pdf","sourcePage":17},{"front":"cannot distinguish certain colours","meaning":"不能分辨某些顏色","examples":[{"en":"Some people cannot distinguish certain colours if they stand alone.","zh":"有些人在某些顏色單獨出現時不能分辨它們。"},{"en":"Cannot distinguish certain colours means cannot tell particular colours apart.","zh":"「cannot distinguish certain colours」意思是不能分辨特定顏色。"},{"en":"A student may confuse purple and blue markers if he cannot distinguish certain colours.","zh":"如果學生不能分辨某些顏色，他可能混淆紫色和藍色筆。"},{"en":"If colours appear alone, there may be fewer clues to help identify them.","zh":"如果顏色單獨出現，幫助辨認的線索可能較少。"},{"en":"The phrase describes a specific colour-recognition difficulty.","zh":"這個短語描述特定顏色辨認困難。"}],"source":"77 - Colour Blindness.pdf","sourcePage":17},{"front":"stand alone","meaning":"單獨出現","examples":[{"en":"Some colours are hard to identify when they stand alone.","zh":"有些顏色在單獨出現時很難辨認。"},{"en":"To stand alone means to appear by itself without comparison or context.","zh":"「stand alone」意思是單獨出現，沒有比較或語境。"},{"en":"A single word may be confusing when it stands alone without a sentence.","zh":"單字沒有句子時單獨出現，可能令人困惑。"},{"en":"If a colour stands alone, people cannot compare it with nearby colours.","zh":"如果顏色單獨出現，人們不能把它與附近顏色比較。"},{"en":"The phrase highlights lack of supporting context.","zh":"這個短語強調缺少支援語境。"}],"source":"77 - Colour Blindness.pdf","sourcePage":17},{"front":"can see no colour at all","meaning":"完全看不到顏色","examples":[{"en":"People with total colour blindness can see no colour at all.","zh":"全色盲人士完全看不到顏色。"},{"en":"Can see no colour at all means cannot perceive any colour.","zh":"「can see no colour at all」意思是不能感知任何顏色。"},{"en":"A black-and-white image gives an idea of seeing no colour at all.","zh":"黑白影像能大概呈現完全看不到顏色的感覺。"},{"en":"If someone can see no colour, brightness and shape become more important.","zh":"如果某人看不到顏色，亮度和形狀會變得更重要。"},{"en":"The phrase describes complete absence of colour vision.","zh":"這個短語描述色覺完全缺失。"}],"source":"77 - Colour Blindness.pdf","sourcePage":17},{"front":"dangerous consequences","meaning":"危險後果","examples":[{"en":"The inability to identify warning lights can have dangerous consequences.","zh":"無法辨認警示燈可能有危險後果。"},{"en":"Dangerous consequences are harmful or risky results.","zh":"「dangerous consequences」是有害或有風險的結果。"},{"en":"Ignoring a fire alarm can have dangerous consequences for everyone in a building.","zh":"忽視火警鐘可能對建築物內所有人帶來危險後果。"},{"en":"If a driver cannot identify warning lights, safety may be at risk.","zh":"如果司機不能辨認警示燈，安全可能受威脅。"},{"en":"The phrase warns that a problem can lead to serious harm.","zh":"這個短語警告問題可能導致嚴重傷害。"}],"source":"77 - Colour Blindness.pdf","sourcePage":17},{"front":"be acquired or inherited","meaning":"可以是後天形成或遺傳的","examples":[{"en":"Colour blindness can be acquired or inherited.","zh":"色盲可以是後天形成或遺傳的。"},{"en":"To be acquired or inherited means to develop after birth or be passed through genes.","zh":"「be acquired or inherited」意思是出生後形成或透過基因傳下來。"},{"en":"Some health conditions are inherited, while others are acquired after illness or injury.","zh":"有些健康狀況是遺傳的，另一些是在疾病或受傷後形成的。"},{"en":"If colour blindness is acquired, doctors may look for a treatable cause.","zh":"如果色盲是後天形成，醫生可能尋找可治療成因。"},{"en":"The phrase gives two possible origins.","zh":"這個短語提供兩種可能來源。"}],"source":"77 - Colour Blindness.pdf","sourcePage":17},{"front":"wear contact lenses","meaning":"戴隱形眼鏡","examples":[{"en":"Some people may wear contact lenses to help distinguish colours.","zh":"有些人可能戴隱形眼鏡來幫助分辨顏色。"},{"en":"To wear contact lenses means to place special lenses directly on the eyes.","zh":"「wear contact lenses」意思是把特別鏡片直接戴在眼睛上。"},{"en":"Athletes may wear contact lenses instead of glasses during sport.","zh":"運動員在運動時可能戴隱形眼鏡代替眼鏡。"},{"en":"If special lenses improve contrast, they may help some users tell colours apart.","zh":"如果特別鏡片改善對比，它們可能幫助一些使用者分辨顏色。"},{"en":"The phrase describes using a physical vision aid.","zh":"這個短語描述使用實體視覺輔助工具。"}],"source":"77 - Colour Blindness.pdf","sourcePage":17},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter from the answer options.","zh":"學生從答案選項中選出正確字母。"},{"en":"To choose the correct letter means to select the option letter that matches the answer.","zh":"「choose the correct letter」意思是選擇與答案相符的選項字母。"},{"en":"In a multiple-choice task, students may choose A, B, C or D.","zh":"在多項選擇題中，學生可能選 A、B、C 或 D。"},{"en":"If the correct idea is matched with the wrong letter, the answer may be marked wrong.","zh":"如果正確意思配上錯誤字母，答案可能被判錯。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"77 - Colour Blindness.pdf","sourcePage":18},{"front":"what causes","meaning":"是甚麼導致","examples":[{"en":"The question asks what causes colour blindness.","zh":"問題問是甚麼導致色盲。"},{"en":"What causes something asks for the reason or source of a problem.","zh":"「what causes」某事，是詢問問題的原因或來源。"},{"en":"A science teacher may ask what causes shadows on the wall.","zh":"科學老師可能問是甚麼導致牆上的影子。"},{"en":"If students know what causes colour blindness, they can understand the role of cone cells.","zh":"如果學生知道是甚麼導致色盲，他們就能理解視錐細胞的作用。"},{"en":"The phrase asks about cause and effect.","zh":"這個短語詢問因果關係。"}],"source":"77 - Colour Blindness.pdf","sourcePage":18},{"front":"the absence of","meaning":"……的缺失","examples":[{"en":"The absence of certain cone cells can cause colour blindness.","zh":"某些視錐細胞的缺失可以導致色盲。"},{"en":"The absence of something means it is missing or not present.","zh":"「the absence of」某物，意思是它缺失或不存在。"},{"en":"The absence of clear instructions can make homework confusing.","zh":"清楚指示的缺失可以令功課令人困惑。"},{"en":"If a necessary cone pigment is absent, colour vision may be incomplete.","zh":"如果必要視錐色素缺失，色覺可能不完整。"},{"en":"The phrase describes missing something important.","zh":"這個短語描述缺少重要東西。"}],"source":"77 - Colour Blindness.pdf","sourcePage":18},{"front":"the malfunction of","meaning":"……的功能異常","examples":[{"en":"The malfunction of cone cells can cause colour blindness.","zh":"視錐細胞的功能異常可以導致色盲。"},{"en":"The malfunction of something means it is present but not working correctly.","zh":"「the malfunction of」某物，意思是它存在但不能正常運作。"},{"en":"The malfunction of a lift can trap people between floors.","zh":"升降機功能異常可能把人困在樓層之間。"},{"en":"If cone cells malfunction, they may send weak or incorrect colour signals.","zh":"如果視錐細胞功能異常，它們可能傳送微弱或錯誤顏色訊號。"},{"en":"The phrase describes faulty operation rather than absence.","zh":"這個短語描述運作故障，而不是缺失。"}],"source":"77 - Colour Blindness.pdf","sourcePage":18},{"front":"inability to detect light","meaning":"無法偵測光線","examples":[{"en":"The question mentions the retina’s inability to detect light.","zh":"問題提到視網膜無法偵測光線。"},{"en":"Inability to detect light means not being able to sense light.","zh":"「inability to detect light」意思是不能感知光線。"},{"en":"A damaged camera sensor may have an inability to detect light clearly.","zh":"受損相機感應器可能無法清楚偵測光線。"},{"en":"If the retina cannot detect light, vision problems would be much broader than colour blindness.","zh":"如果視網膜不能偵測光線，視覺問題會比色盲廣泛得多。"},{"en":"The phrase describes a failure of light detection.","zh":"這個短語描述光線偵測失敗。"}],"source":"77 - Colour Blindness.pdf","sourcePage":18},{"front":"which group is the rarest","meaning":"哪一組最罕見","examples":[{"en":"The question asks which group is the rarest.","zh":"問題問哪一組最罕見。"},{"en":"Which group is the rarest asks which category appears least often.","zh":"「which group is the rarest」是在問哪個類別最少出現。"},{"en":"A survey may ask which club is the rarest choice among students.","zh":"調查可能問哪個社團是學生中最罕見的選擇。"},{"en":"If one form affects very few people, it is the rarest group.","zh":"如果一種形式影響非常少人，它就是最罕見的一組。"},{"en":"The phrase asks for comparison of frequency.","zh":"這個短語詢問出現頻率的比較。"}],"source":"77 - Colour Blindness.pdf","sourcePage":18},{"front":"cannot detect blues from yellows","meaning":"不能分辨藍色和黃色","examples":[{"en":"Some people cannot detect blues from yellows.","zh":"有些人不能分辨藍色和黃色。"},{"en":"Cannot detect blues from yellows means cannot distinguish blue colours from yellow colours.","zh":"「cannot detect blues from yellows」意思是不能把藍色與黃色分辨開來。"},{"en":"A student may confuse blue and yellow chart sections if the colours are hard to detect.","zh":"如果顏色難以辨認，學生可能混淆圖表中的藍色和黃色部分。"},{"en":"If blue-yellow vision is affected, labels and patterns can help.","zh":"如果藍黃色覺受影響，標籤和圖案可以幫忙。"},{"en":"The phrase describes a specific colour-discrimination problem.","zh":"這個短語描述特定顏色分辨問題。"}],"source":"77 - Colour Blindness.pdf","sourcePage":18},{"front":"everyday nuisance","meaning":"日常煩惱","examples":[{"en":"Buying clothes can become an everyday nuisance for colour-blind people.","zh":"對色盲人士來說，買衣服可以成為日常煩惱。"},{"en":"An everyday nuisance is a small but repeated problem in daily life.","zh":"「everyday nuisance」是日常生活中細小但重複的問題。"},{"en":"A slow lift can be an everyday nuisance for people who live on a high floor.","zh":"對住在高層的人來說，慢速升降機可以是日常煩惱。"},{"en":"If choosing matching clothes is difficult every morning, the problem becomes a nuisance.","zh":"如果每天早上配襯衣服都很困難，問題就變成煩惱。"},{"en":"The phrase describes irritation, not a major emergency.","zh":"這個短語描述煩擾，而不是重大緊急情況。"}],"source":"77 - Colour Blindness.pdf","sourcePage":18},{"front":"identify the colour of","meaning":"辨認……的顏色","examples":[{"en":"It can be hard to identify the colour of a warning light.","zh":"辨認警示燈的顏色可能很困難。"},{"en":"To identify the colour of something means to recognise what colour it is.","zh":"「identify the colour of」某物，意思是認出它是甚麼顏色。"},{"en":"A child may identify the colour of a crayon before using it.","zh":"孩子使用蠟筆前可能先辨認蠟筆的顏色。"},{"en":"If a warning light’s colour cannot be identified, the user may not know what action to take.","zh":"如果警示燈顏色無法辨認，使用者可能不知道要採取甚麼行動。"},{"en":"The phrase focuses on recognising colour accurately.","zh":"這個短語集中於準確辨認顏色。"}],"source":"77 - Colour Blindness.pdf","sourcePage":18},{"front":"tell something from something","meaning":"分辨……和……","examples":[{"en":"Some people cannot tell a ripe tomato from an unripe one.","zh":"有些人不能分辨成熟番茄和未熟番茄。"},{"en":"To tell something from something means to distinguish one thing from another.","zh":"「tell something from something」意思是分辨一物和另一物。"},{"en":"A beginner may not tell one bird species from another without a guidebook.","zh":"初學者沒有圖鑑時，可能不能分辨一種鳥和另一種鳥。"},{"en":"If colours look similar, telling ripe fruit from unripe fruit becomes harder.","zh":"如果顏色看起來相似，分辨成熟和未熟水果就更困難。"},{"en":"The phrase means recognise the difference between two things.","zh":"這個短語意思是認出兩者之間的差異。"}],"source":"77 - Colour Blindness.pdf","sourcePage":18},{"front":"matching clothes","meaning":"顏色配襯的衣服","examples":[{"en":"Colour-blind people may have difficulty buying matching clothes.","zh":"色盲人士買顏色配襯的衣服可能有困難。"},{"en":"Matching clothes are clothes whose colours or styles look good together.","zh":"「matching clothes」是顏色或款式搭配得好看的衣服。"},{"en":"A student may choose matching clothes for a school presentation or interview.","zh":"學生可能為學校匯報或面試選擇顏色配襯的衣服。"},{"en":"If colours are difficult to distinguish, matching clothes can become frustrating.","zh":"如果顏色難以分辨，配襯衣服可能變得令人挫折。"},{"en":"The phrase refers to clothes that coordinate well.","zh":"這個短語指配合得好的衣服。"}],"source":"77 - Colour Blindness.pdf","sourcePage":18},{"front":"complete the diagram below","meaning":"完成下方圖表","examples":[{"en":"Students complete the diagram below using words from the passage.","zh":"學生使用篇章中的字詞完成下方圖表。"},{"en":"To complete the diagram below means to fill in missing labels or information in the diagram.","zh":"「complete the diagram below」意思是填入圖表中缺少的標籤或資料。"},{"en":"In biology class, students may complete a diagram of the eye with parts such as retina and lens.","zh":"在生物課中，學生可能完成眼睛圖表，填上視網膜和晶狀體等部分。"},{"en":"If the diagram comes from a reading passage, answers must match the passage wording.","zh":"如果圖表來自閱讀篇章，答案必須符合篇章用字。"},{"en":"The phrase is a common diagram-labelling instruction.","zh":"這個短語是常見圖表標籤題指示。"}],"source":"77 - Colour Blindness.pdf","sourcePage":19},{"front":"no more than two words","meaning":"不多於兩個字","examples":[{"en":"Students should choose no more than two words from the passage.","zh":"學生應從篇章中選擇不多於兩個字。"},{"en":"No more than two words means one or two words only, not three or more.","zh":"「no more than two words」意思是只可一個或兩個字，不可三個或更多。"},{"en":"If the answer is “cone cells”, it fits a no-more-than-two-words rule.","zh":"如果答案是 “cone cells”，它符合不多於兩個字的規則。"},{"en":"If students write extra words, the answer may be marked wrong even if the idea is correct.","zh":"如果學生寫多了字，即使意思正確，答案也可能被判錯。"},{"en":"The phrase sets a strict word limit.","zh":"這個短語設定嚴格字數限制。"}],"source":"77 - Colour Blindness.pdf","sourcePage":19},{"front":"from the passage","meaning":"從篇章中選取","examples":[{"en":"The answers must be taken from the passage.","zh":"答案必須從篇章中選取。"},{"en":"From the passage means using words or information directly from the text.","zh":"「from the passage」意思是使用直接來自文本的字詞或資料。"},{"en":"In a reading test, students should not invent answers from their own knowledge.","zh":"在閱讀測驗中，學生不應用自己的知識創作答案。"},{"en":"If the instruction says “from the passage”, spelling and wording should follow the text closely.","zh":"如果指示說 “from the passage”，串字和用詞應盡量跟隨文本。"},{"en":"The phrase reminds students to base answers on the source.","zh":"這個短語提醒學生根據來源作答。"}],"source":"77 - Colour Blindness.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 78":[{"front":"therapeutic jurisprudence","meaning":"治療法理學","examples":[{"en":"Therapeutic jurisprudence studies the role of the law as a therapeutic agent.","zh":"治療法理學研究法律作為治療媒介的作用。"},{"en":"Therapeutic jurisprudence is an approach that studies how law can affect people’s mental and emotional well-being.","zh":"治療法理學是一種研究法律如何影響人們心理和情緒健康的方法。"},{"en":"A law student may study therapeutic jurisprudence to understand why court procedures can either help or harm vulnerable people.","zh":"法律學生可能研究治療法理學，以理解法院程序為何可以幫助或傷害弱勢人士。"},{"en":"If a legal rule reduces stress and encourages positive behaviour, therapeutic jurisprudence would examine that effect.","zh":"如果一條法律規則減少壓力並鼓勵正面行為，治療法理學會研究這種影響。"},{"en":"The phrase focuses on the human impact of law, not only legal rights and duties.","zh":"這個短語強調法律對人的影響，而不只是法律權利和責任。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":1},{"front":"an overview","meaning":"概述","examples":[{"en":"The article gives an overview of therapeutic jurisprudence.","zh":"文章對治療法理學作出概述。"},{"en":"An overview is a general explanation of the main points of a topic.","zh":"概述是對某個題目的主要重點作一般說明。"},{"en":"A teacher may give an overview of a new course before teaching the first chapter.","zh":"老師可能在教授第一章前，先概述新課程。"},{"en":"If students get an overview first, they can understand where later details fit.","zh":"如果學生先得到概述，就能明白後面的細節放在哪裡。"},{"en":"The phrase suggests a broad introduction, not a full detailed study.","zh":"這個短語暗示廣泛介紹，而不是完整詳細研究。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":1},{"front":"the study of","meaning":"對……的研究","examples":[{"en":"Therapeutic jurisprudence is the study of the role of the law as a therapeutic agent.","zh":"治療法理學是對法律作為治療媒介的作用的研究。"},{"en":"The study of something means the careful examination of that subject.","zh":"“The study of” 某事指對該題目作仔細研究。"},{"en":"The study of language helps teachers understand how students learn grammar and vocabulary.","zh":"對語言的研究幫助老師理解學生如何學習文法和詞彙。"},{"en":"If a field is the study of law’s effects, it asks how legal rules change people’s lives.","zh":"如果一個領域是對法律影響的研究，它會問法律規則如何改變人的生活。"},{"en":"The phrase is often used to define academic subjects.","zh":"這個短語常用來定義學術科目。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":1},{"front":"the role of the law","meaning":"法律的作用","examples":[{"en":"The theory examines the role of the law in people’s emotional lives.","zh":"這個理論研究法律在人們情感生活中的作用。"},{"en":"The role of the law means what law does and how it influences people or society.","zh":"法律的作用指法律做甚麼，以及它如何影響人或社會。"},{"en":"In family disputes, the role of the law may include protecting children and guiding parents.","zh":"在家庭糾紛中，法律的作用可能包括保護兒童和引導父母。"},{"en":"If legal procedures cause fear or trust, the role of the law is not only technical but emotional.","zh":"如果法律程序造成恐懼或信任，法律的作用就不只是技術性的，也有情感層面。"},{"en":"The phrase asks what function law plays in real life.","zh":"這個短語詢問法律在現實生活中發揮甚麼功能。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":1},{"front":"a therapeutic agent","meaning":"治療媒介；有治療作用的因素","examples":[{"en":"The law may sometimes act as a therapeutic agent.","zh":"法律有時可能作為治療媒介。"},{"en":"A therapeutic agent is something that helps improve a person’s mental, emotional, or physical condition.","zh":"治療媒介是幫助改善一個人心理、情緒或身體狀況的事物。"},{"en":"Supportive counselling can act as a therapeutic agent for a student under heavy stress.","zh":"支持性的輔導可以成為承受巨大壓力學生的治療媒介。"},{"en":"If a court process helps someone feel heard and respected, it may have a therapeutic effect.","zh":"如果法院程序幫助某人感到被聆聽和尊重，它可能有治療作用。"},{"en":"The phrase describes something that contributes to healing or well-being.","zh":"這個短語描述有助治癒或提升福祉的事物。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":1},{"front":"examine the law’s impact on","meaning":"研究法律對……的影響","examples":[{"en":"Therapeutic jurisprudence examines the law’s impact on emotional life.","zh":"治療法理學研究法律對情感生活的影響。"},{"en":"To examine the law’s impact on something means to study how law affects that area.","zh":"“Examine the law’s impact on” 某事指研究法律如何影響該範疇。"},{"en":"Researchers may examine the law’s impact on victims who must give evidence in court.","zh":"研究人員可能研究法律對必須在法庭作證的受害者的影響。"},{"en":"If legal procedures increase stress, examining their impact can help improve the system.","zh":"如果法律程序增加壓力，研究其影響可以幫助改善制度。"},{"en":"The phrase focuses on consequences, not only legal wording.","zh":"這個短語強調後果，而不只是法律文字。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":1},{"front":"emotional life","meaning":"情感生活","examples":[{"en":"The law can affect a person’s emotional life.","zh":"法律可以影響一個人的情感生活。"},{"en":"Emotional life means a person’s feelings, worries, hopes, fears, and sense of dignity.","zh":"情感生活指一個人的感受、憂慮、希望、恐懼和尊嚴感。"},{"en":"A long custody case can deeply affect a parent’s emotional life.","zh":"長期的子女管養權案件可以深深影響父母的情感生活。"},{"en":"If people feel ignored in court, their emotional life may be harmed even if the legal result is fair.","zh":"如果人在法庭中感到被忽視，即使法律結果公平，其情感生活也可能受損。"},{"en":"The phrase refers to inner feelings and emotional experiences.","zh":"這個短語指內在感受和情緒經驗。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":1},{"front":"psychological well-being","meaning":"心理健康","examples":[{"en":"The legal process can influence psychological well-being.","zh":"法律程序可以影響心理健康。"},{"en":"Psychological well-being means mental health, emotional balance, and a sense of coping with life.","zh":"心理健康指精神健康、情緒平衡，以及能應付生活的感覺。"},{"en":"A fair workplace can support employees’ psychological well-being by reducing fear and uncertainty.","zh":"公平的工作場所可以透過減少恐懼和不確定，支援員工心理健康。"},{"en":"If a court process is confusing and harsh, it may damage psychological well-being.","zh":"如果法院程序混亂而嚴厲，可能損害心理健康。"},{"en":"The phrase focuses on mental and emotional health.","zh":"這個短語強調精神和情緒健康。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":1},{"front":"therapeutic and antitherapeutic consequences","meaning":"治療性及反治療性的後果","examples":[{"en":"The field studies the therapeutic and antitherapeutic consequences of the law.","zh":"這個領域研究法律的治療性及反治療性後果。"},{"en":"Therapeutic and antitherapeutic consequences are helpful and harmful effects on people’s well-being.","zh":"治療性及反治療性的後果，是對人們福祉有幫助和有害的影響。"},{"en":"A school discipline policy may have therapeutic effects if it teaches repair, but antitherapeutic effects if it only shames students.","zh":"學校紀律政策如果教學生修補關係，可能有治療性效果；如果只是羞辱學生，則可能有反治療性效果。"},{"en":"If a legal rule calms conflict, it may be therapeutic; if it increases trauma, it may be antitherapeutic.","zh":"如果法律規則平息衝突，它可能具治療性；如果增加創傷，它可能具反治療性。"},{"en":"The phrase asks whether law helps or harms people psychologically.","zh":"這個短語詢問法律在心理上是幫助還是傷害人。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":1},{"front":"be applicable to","meaning":"適用於","examples":[{"en":"Therapeutic jurisprudence is applicable to several areas of law.","zh":"治療法理學適用於幾個法律範疇。"},{"en":"To be applicable to something means to be relevant or useful in that situation.","zh":"“Be applicable to” 某事指與該情況相關或有用。"},{"en":"A study method may be applicable to both language learning and science revision.","zh":"一種學習方法可能同時適用於語言學習和科學溫習。"},{"en":"If an idea is applicable to family law, judges can use it when thinking about families’ emotional needs.","zh":"如果一個想法適用於家庭法，法官可以在思考家庭情感需要時使用它。"},{"en":"The phrase shows where a theory or method can be used.","zh":"這個短語顯示理論或方法可在哪裡使用。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":1},{"front":"the fields of","meaning":"……的範疇","examples":[{"en":"It is most applicable to the fields of mental health law and criminal law.","zh":"它最適用於精神健康法律和刑事法的範疇。"},{"en":"The fields of something are its areas, branches, or subjects of work or study.","zh":"“The fields of” 某事指其工作或研究的範疇、分支或科目。"},{"en":"Psychology, education, and medicine are different fields that all study human behaviour.","zh":"心理學、教育和醫學是不同範疇，但都研究人類行為。"},{"en":"If a theory applies to several fields of law, it can affect many kinds of cases.","zh":"如果一個理論適用於多個法律範疇，它就可以影響許多案件。"},{"en":"The phrase helps organise a broad topic into areas.","zh":"這個短語幫助把廣泛題目整理成不同範疇。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":1},{"front":"mental health law","meaning":"精神健康法律","examples":[{"en":"Mental health law is one field where therapeutic jurisprudence is relevant.","zh":"精神健康法律是治療法理學相關的一個範疇。"},{"en":"Mental health law deals with legal issues involving mental illness, treatment, rights, and protection.","zh":"精神健康法律處理涉及精神疾病、治療、權利和保護的法律問題。"},{"en":"A hospital may follow mental health law when deciding whether a patient can be treated without consent.","zh":"醫院在決定病人是否可在未同意下接受治療時，可能需要遵循精神健康法律。"},{"en":"If mental health law ignores dignity, it may harm patients’ psychological well-being.","zh":"如果精神健康法律忽視尊嚴，可能損害病人的心理健康。"},{"en":"The phrase connects law with mental health care and rights.","zh":"這個短語把法律與精神健康照顧和權利連繫起來。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":2},{"front":"criminal law","meaning":"刑事法","examples":[{"en":"Therapeutic jurisprudence is applicable to criminal law.","zh":"治療法理學適用於刑事法。"},{"en":"Criminal law is the area of law that deals with crimes, offenders, punishment, and public safety.","zh":"刑事法是處理犯罪、罪犯、懲罰和公共安全的法律範疇。"},{"en":"A judge uses criminal law when deciding how to sentence someone found guilty of theft.","zh":"法官在決定如何判處被裁定盜竊罪成的人時，會使用刑事法。"},{"en":"If criminal law includes rehabilitation, it may help reduce future offending.","zh":"如果刑事法包括更生，它可能幫助減少日後犯罪。"},{"en":"The phrase refers to law about crime, not private disputes only.","zh":"這個短語指關於犯罪的法律，而不只是私人糾紛。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":2},{"front":"juvenile law","meaning":"青少年法律","examples":[{"en":"Juvenile law deals with legal matters involving young people.","zh":"青少年法律處理涉及年輕人的法律事項。"},{"en":"Juvenile law is the area of law concerning children and teenagers in legal trouble or need of protection.","zh":"青少年法律是關於陷入法律問題或需要保護的兒童和青少年的法律範疇。"},{"en":"A young offender may be handled under juvenile law rather than the ordinary adult court system.","zh":"年輕罪犯可能按青少年法律處理，而不是使用普通成人法院制度。"},{"en":"If juvenile law focuses on rehabilitation, it may help young people change before patterns become fixed.","zh":"如果青少年法律集中於更生，它可能幫助年輕人在行為模式固定前改變。"},{"en":"The phrase refers to law involving minors.","zh":"這個短語指涉及未成年人的法律。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":2},{"front":"family law","meaning":"家庭法","examples":[{"en":"Family law is one area where emotional consequences may be important.","zh":"家庭法是情感後果可能重要的一個範疇。"},{"en":"Family law deals with legal issues such as marriage, divorce, child custody, and family support.","zh":"家庭法處理婚姻、離婚、子女管養權和家庭支援等法律問題。"},{"en":"A court uses family law when deciding where a child should live after parents separate.","zh":"父母分居後，法院在決定孩子應住在哪裡時會使用家庭法。"},{"en":"If family law procedures are respectful, they may reduce stress for parents and children.","zh":"如果家庭法程序尊重當事人，可能減少父母和孩子的壓力。"},{"en":"The phrase refers to law about family relationships and responsibilities.","zh":"這個短語指關於家庭關係和責任的法律。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":2},{"front":"the general aim of","meaning":"……的一般目標","examples":[{"en":"The general aim of therapeutic jurisprudence is to humanise the law.","zh":"治療法理學的一般目標是使法律更人性化。"},{"en":"The general aim of something is its broad main purpose.","zh":"“The general aim of” 某事指其廣泛主要目的。"},{"en":"The general aim of a language course may be to help students communicate more confidently.","zh":"語言課的一般目標可能是幫助學生更有信心地溝通。"},{"en":"If the general aim is clear, smaller actions can be judged by whether they support it.","zh":"如果一般目標清晰，就可以判斷較小行動是否支持它。"},{"en":"The phrase introduces the main purpose rather than every detail.","zh":"這個短語引出主要目的，而不是每個細節。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":2},{"front":"humanise the law","meaning":"使法律更人性化","examples":[{"en":"The general aim of therapeutic jurisprudence is to humanise the law.","zh":"治療法理學的一般目標是使法律更人性化。"},{"en":"To humanise the law means to make legal rules and processes more sensitive to people’s needs, feelings, and dignity.","zh":"“Humanise the law” 指令法律規則和程序更重視人的需要、感受和尊嚴。"},{"en":"A court can humanise the law by explaining decisions clearly to confused defendants.","zh":"法院可以透過向困惑的被告清楚解釋判決，使法律更人性化。"},{"en":"If people feel respected in legal settings, the law may seem less cold and frightening.","zh":"如果人在法律環境中感到被尊重，法律可能顯得不那麼冰冷和可怕。"},{"en":"The phrase does not mean ignoring justice; it means treating people as human beings.","zh":"這個短語不是指忽視公義，而是把人當作人來對待。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":2},{"front":"address the human side of","meaning":"處理……人性化的一面","examples":[{"en":"The approach addresses the human side of the legal process.","zh":"這種方法處理法律程序中人性化的一面。"},{"en":"To address the human side of something means to deal with people’s feelings, needs, fears, and relationships within it.","zh":"“Address the human side of” 某事指處理其中人的感受、需要、恐懼和關係。"},{"en":"A school policy addresses the human side of discipline when it asks why a child misbehaved.","zh":"當學校紀律政策詢問孩子為何行為不當時，就是在處理紀律中人性化的一面。"},{"en":"If courts address the human side of a case, people may feel heard even when the result is difficult.","zh":"如果法院處理案件的人性化一面，即使結果艱難，人們也可能感到被聆聽。"},{"en":"The phrase adds emotional and practical humanity to a formal process.","zh":"這個短語為正式程序加入情感和實際的人性。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":2},{"front":"the emotional and psychological side of","meaning":"……情感及心理層面","examples":[{"en":"Therapeutic jurisprudence considers the emotional and psychological side of the legal process.","zh":"治療法理學考慮法律程序的情感及心理層面。"},{"en":"The emotional and psychological side of something is how it affects feelings, thoughts, stress, and mental health.","zh":"某事的情感及心理層面，是它如何影響感受、想法、壓力和心理健康。"},{"en":"A school exam has an emotional and psychological side because it can create fear or confidence.","zh":"學校考試有情感及心理層面，因為它可以造成恐懼或信心。"},{"en":"If lawyers ignore this side, clients may understand the case legally but still feel overwhelmed.","zh":"如果律師忽視這一面，客戶可能在法律上理解案件，但仍感到不知所措。"},{"en":"The phrase looks beyond facts and rules to inner experience.","zh":"這個短語超越事實和規則，關注內在經驗。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":2},{"front":"the legal process","meaning":"法律程序","examples":[{"en":"The legal process can affect people’s mental and emotional state.","zh":"法律程序可以影響人們的心理和情緒狀態。"},{"en":"The legal process is the series of formal steps used to handle a legal matter.","zh":"法律程序是處理法律事項的一連串正式步驟。"},{"en":"Filing documents, attending hearings, and receiving a judgment are parts of the legal process.","zh":"提交文件、出席聆訊和收到判決都是法律程序的一部分。"},{"en":"If the legal process is slow and confusing, it may increase stress for everyone involved.","zh":"如果法律程序緩慢而混亂，可能增加所有相關人士的壓力。"},{"en":"The phrase refers to how law is carried out in practice.","zh":"這個短語指法律在實際上如何執行。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":2},{"front":"promote the perspective that","meaning":"提倡……的觀點","examples":[{"en":"The theory promotes the perspective that the law is a social force.","zh":"這個理論提倡法律是一種社會力量的觀點。"},{"en":"To promote the perspective that something is true means to encourage people to see it in that way.","zh":"“Promote the perspective that” 某事為真指鼓勵人們以該方式看待它。"},{"en":"A teacher may promote the perspective that mistakes are part of learning.","zh":"老師可能提倡錯誤是學習一部分的觀點。"},{"en":"If scholars promote a new perspective, they want people to rethink old assumptions.","zh":"如果學者提倡新觀點，他們想令人重新思考舊假設。"},{"en":"The phrase introduces a viewpoint being encouraged.","zh":"這個短語引出被鼓勵採納的觀點。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":2},{"front":"a social force","meaning":"社會力量","examples":[{"en":"The law is seen as a social force that produces behaviours and consequences.","zh":"法律被視為一種會產生行為及後果的社會力量。"},{"en":"A social force is something that influences how people act, think, and relate to one another in society.","zh":"社會力量是影響社會中人們如何行動、思考和互相關係的事物。"},{"en":"Social media can be a social force because it changes how young people communicate and compare themselves.","zh":"社交媒體可以是一種社會力量，因為它改變年輕人溝通和比較自己的方式。"},{"en":"If law is a social force, it shapes behaviour beyond courtrooms and legal documents.","zh":"如果法律是一種社會力量，它塑造的行為就超越法庭和法律文件。"},{"en":"The phrase shows that law affects society, not only individual cases.","zh":"這個短語顯示法律影響社會，而不只是個別案件。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":2},{"front":"produce behaviours and consequences","meaning":"產生行為及後果","examples":[{"en":"The law can produce behaviours and consequences.","zh":"法律可以產生行為及後果。"},{"en":"To produce behaviours and consequences means to cause people to act in certain ways and create results.","zh":"“Produce behaviours and consequences” 指令人以某些方式行動，並造成結果。"},{"en":"A school rule can produce better behaviour if students understand its purpose.","zh":"如果學生明白校規目的，校規可以產生較好行為。"},{"en":"If a law threatens harsh punishment, it may produce fear, compliance, or resistance.","zh":"如果法律威脅嚴厲懲罰，它可能產生恐懼、遵從或抗拒。"},{"en":"The phrase connects rules with real human outcomes.","zh":"這個短語把規則與真實人類後果連繫起來。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":3},{"front":"strive to","meaning":"努力去","examples":[{"en":"Therapeutic jurisprudence strives to apply laws in a more therapeutic way.","zh":"治療法理學努力以更具治療性的方式應用法律。"},{"en":"To strive to do something means to make serious effort to achieve it.","zh":"“Strive to” 做某事指認真努力達成它。"},{"en":"A student may strive to improve pronunciation by practising a little every day.","zh":"學生可能透過每天練習一點，努力改善發音。"},{"en":"If courts strive to reduce harm, they need to think carefully about how people experience legal procedures.","zh":"如果法院努力減少傷害，就需要仔細思考人們如何經歷法律程序。"},{"en":"The phrase suggests active and determined effort.","zh":"這個短語暗示積極而堅定的努力。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":3},{"front":"have laws made or applied","meaning":"使法律被制定或應用","examples":[{"en":"The approach strives to have laws made or applied more therapeutically.","zh":"這種方法努力使法律被制定或應用得更具治療性。"},{"en":"To have laws made or applied in a certain way means to influence how laws are created or used.","zh":"“Have laws made or applied” 以某方式進行，指影響法律如何被創造或使用。"},{"en":"Citizens may want laws made or applied fairly so that rich and poor people receive equal treatment.","zh":"市民可能希望法律被公平制定或應用，使富人和窮人得到平等對待。"},{"en":"If laws are applied more therapeutically, they may reduce harm while still respecting justice.","zh":"如果法律被更具治療性地應用，它們可能在尊重公義的同時減少傷害。"},{"en":"The phrase covers both writing laws and using them in real cases.","zh":"這個短語涵蓋制定法律和在真實案件中使用法律。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":3},{"front":"in a more therapeutic way","meaning":"以更具治療性的方式","examples":[{"en":"Laws may be applied in a more therapeutic way.","zh":"法律可以以更具治療性的方式應用。"},{"en":"In a more therapeutic way means in a way that better supports healing, emotional safety, or positive change.","zh":"“In a more therapeutic way” 指以更能支援治癒、情緒安全或正面改變的方式。"},{"en":"A school can discipline students in a more therapeutic way by helping them repair harm instead of only punishing them.","zh":"學校可以透過幫助學生修補傷害，而不是只懲罰他們，以更具治療性的方式處理紀律。"},{"en":"If a judge speaks respectfully, the court process may feel more therapeutic to the defendant.","zh":"如果法官尊重地說話，法院程序對被告來說可能感覺更具治療性。"},{"en":"The phrase suggests improving the human effect of an action.","zh":"這個短語暗示改善某行動對人的影響。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":3},{"front":"so long as","meaning":"只要","examples":[{"en":"Therapeutic goals may be considered so long as justice is respected.","zh":"只要公義得到尊重，治療性目標可以被考慮。"},{"en":"So long as means provided that or only if a condition is met.","zh":"“So long as” 指只要某條件得到滿足。"},{"en":"Students may use laptops in class so long as they do not distract others.","zh":"只要學生不打擾他人，就可以在課堂使用手提電腦。"},{"en":"If therapeutic ideas are used, they are acceptable only so long as legal fairness remains protected.","zh":"如果使用治療性想法，只要法律公平仍受保護，它們才可接受。"},{"en":"The phrase sets a condition or limit.","zh":"這個短語設定條件或界限。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":3},{"front":"other values","meaning":"其他價值","examples":[{"en":"Other values must be respected in the legal process.","zh":"法律程序中必須尊重其他價值。"},{"en":"Other values are additional principles that matter besides the main goal being discussed.","zh":"其他價值是除了正在討論的主要目標之外也重要的原則。"},{"en":"In school discipline, kindness matters, but other values such as fairness and safety also matter.","zh":"在學校紀律中，仁慈很重要，但公平和安全等其他價值也重要。"},{"en":"If therapeutic goals ignore other values, the legal system may become unfair.","zh":"如果治療性目標忽視其他價值，法律制度可能變得不公平。"},{"en":"The phrase reminds readers that one aim should not dominate everything.","zh":"這個短語提醒讀者，一個目標不應主導一切。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":3},{"front":"justice and due process","meaning":"公義及正當法律程序","examples":[{"en":"Justice and due process must be fully respected.","zh":"公義及正當法律程序必須得到充分尊重。"},{"en":"Justice and due process mean fairness and proper legal procedures that protect people’s rights.","zh":"公義及正當法律程序指公平和保護人們權利的正確法律程序。"},{"en":"A defendant should receive justice and due process before any punishment is imposed.","zh":"在任何懲罰被施加前，被告應得到公義及正當法律程序。"},{"en":"If treatment goals ignore due process, the law may become unfair even if intentions are good.","zh":"如果治療目標忽視正當程序，即使出發點良好，法律也可能變得不公平。"},{"en":"The phrase protects legal fairness against shortcuts.","zh":"這個短語保護法律公平，避免走捷徑。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":3},{"front":"be fully respected","meaning":"得到充分尊重","examples":[{"en":"Other legal values can be fully respected.","zh":"其他法律價值可以得到充分尊重。"},{"en":"To be fully respected means to be treated as completely important and not ignored or weakened.","zh":"“Be fully respected” 指被完全重視，而不是被忽視或削弱。"},{"en":"Students’ privacy should be fully respected when schools collect personal information.","zh":"學校收集個人資料時，學生私隱應得到充分尊重。"},{"en":"If due process is fully respected, people can trust the legal outcome more easily.","zh":"如果正當法律程序得到充分尊重，人們更容易信任法律結果。"},{"en":"The phrase stresses complete protection, not partial attention.","zh":"這個短語強調完整保護，而不是部分關注。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":3},{"front":"recognise that","meaning":"認識到","examples":[{"en":"It is important to recognise that therapeutic goals should not override other goals.","zh":"重要的是要認識到治療性目標不應凌駕其他目標。"},{"en":"To recognise that something is true means to understand or accept it clearly.","zh":"“Recognise that” 某事為真指清楚理解或接受它。"},{"en":"A teacher may recognise that a quiet student is struggling even without complaints.","zh":"老師可能認識到安靜學生正在吃力，即使他沒有投訴。"},{"en":"If legal actors recognise limits, they can use therapeutic ideas without damaging fairness.","zh":"如果法律參與者認識到界限，就可以使用治療性想法而不損害公平。"},{"en":"The phrase introduces an important understanding.","zh":"這個短語引出重要理解。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":3},{"front":"does not itself suggest that","meaning":"本身並不表示","examples":[{"en":"Therapeutic jurisprudence does not itself suggest that therapeutic goals should trump other goals.","zh":"治療法理學本身並不表示治療性目標應凌駕其他目標。"},{"en":"Does not itself suggest that means the idea alone does not imply that conclusion.","zh":"“Does not itself suggest that” 指該想法本身並不暗示該結論。"},{"en":"Wanting students to be happy does not itself suggest that exams should disappear.","zh":"希望學生快樂，本身並不表示考試應該消失。"},{"en":"If a theory values well-being, that does not automatically mean it rejects justice.","zh":"如果一個理論重視福祉，這不自動代表它拒絕公義。"},{"en":"The phrase prevents a misunderstanding of an argument.","zh":"這個短語防止對論點的誤解。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":3},{"front":"therapeutic goals","meaning":"治療性目標","examples":[{"en":"Therapeutic goals should not trump justice and due process.","zh":"治療性目標不應凌駕公義及正當法律程序。"},{"en":"Therapeutic goals are aims related to healing, well-being, rehabilitation, or emotional improvement.","zh":"治療性目標是與治癒、福祉、更生或情緒改善有關的目標。"},{"en":"A court may have therapeutic goals when it tries to help an offender avoid future crime.","zh":"當法院嘗試幫助罪犯避免日後犯罪時，可能有治療性目標。"},{"en":"If therapeutic goals ignore legal rights, good intentions can still become harmful.","zh":"如果治療性目標忽視法律權利，良好意圖仍可能變得有害。"},{"en":"The phrase refers to healing-related aims within law or treatment.","zh":"這個短語指法律或治療中與治癒相關的目標。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":3},{"front":"trump other goals","meaning":"凌駕於其他目標之上","examples":[{"en":"Therapeutic goals should not trump other goals.","zh":"治療性目標不應凌駕於其他目標之上。"},{"en":"To trump other goals means to become more important than them and override them.","zh":"“Trump other goals” 指變得比其他目標更重要並壓過它們。"},{"en":"A school’s wish for high exam scores should not trump students’ health and safety.","zh":"學校追求高考試成績的願望不應凌駕學生健康和安全。"},{"en":"If rehabilitation trumps due process, the legal system may lose fairness.","zh":"如果更生凌駕正當程序，法律制度可能失去公平。"},{"en":"The phrase warns that one aim should not defeat other important aims.","zh":"這個短語提醒一個目標不應擊敗其他重要目標。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":4},{"front":"support paternalism","meaning":"支持家長式干預","examples":[{"en":"The approach does not support paternalism.","zh":"這種方法並不支持家長式干預。"},{"en":"To support paternalism means to approve of controlling people for their supposed good without enough respect for their choices.","zh":"“Support paternalism” 指認同為了所謂對某人好而控制他們，卻沒有充分尊重其選擇。"},{"en":"A doctor supports paternalism if he ignores a patient’s wishes and decides everything alone.","zh":"如果醫生忽視病人意願並獨自決定一切，他就是支持家長式干預。"},{"en":"If a legal theory rejects paternalism, it should respect people’s voice and autonomy.","zh":"如果一個法律理論拒絕家長式干預，就應尊重人的聲音和自主。"},{"en":"The phrase warns against treating adults like children.","zh":"這個短語提醒不要把成年人當小孩對待。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":4},{"front":"coercion","meaning":"強制；脅迫","examples":[{"en":"Therapeutic jurisprudence does not support coercion by any means.","zh":"治療法理學並不以任何方式支持強制。"},{"en":"Coercion means forcing someone to do something through pressure, threat, or control.","zh":"強制是透過壓力、威脅或控制迫使某人做某事。"},{"en":"A student who is threatened into joining a club is experiencing coercion, not free choice.","zh":"被威脅加入社團的學生經歷的是強制，而不是自由選擇。"},{"en":"If a legal programme relies on coercion, people may obey outwardly but feel resentful.","zh":"如果法律計劃依賴強制，人們可能表面遵從但心生怨恨。"},{"en":"The word describes forced action rather than voluntary agreement.","zh":"這個詞描述被迫行動，而不是自願同意。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":4},{"front":"by any means","meaning":"以任何方式","examples":[{"en":"It does not support coercion by any means.","zh":"它並不以任何方式支持強制。"},{"en":"By any means means in any way or through any method.","zh":"“By any means” 指以任何方式或透過任何方法。"},{"en":"A teacher should not humiliate students by any means, even to make them work harder.","zh":"老師不應以任何方式羞辱學生，即使是為了令他們更努力。"},{"en":"If fairness is important, justice should not be sacrificed by any means.","zh":"如果公平重要，就不應以任何方式犧牲公義。"},{"en":"The phrase strongly rejects all methods of doing something.","zh":"這個短語強烈拒絕某行為的所有方法。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":4},{"front":"a way of looking at","meaning":"看待……的一種方式","examples":[{"en":"Therapeutic jurisprudence is a way of looking at the law in a richer way.","zh":"治療法理學是一種以更豐富方式看待法律的方法。"},{"en":"A way of looking at something is a perspective or method for understanding it.","zh":"“A way of looking at” 某事是理解它的一種角度或方法。"},{"en":"Seeing mistakes as feedback is a helpful way of looking at learning.","zh":"把錯誤視為回饋，是看待學習的一種有用方式。"},{"en":"If we look at law through emotional effects, we notice issues that legal rules alone may hide.","zh":"如果我們透過情感影響看待法律，就會注意到單靠法律規則可能隱藏的議題。"},{"en":"The phrase introduces a viewpoint, not a physical act of looking.","zh":"這個短語引出觀點，而不是實際觀看動作。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":4},{"front":"in a richer way","meaning":"以更豐富的方式","examples":[{"en":"The theory encourages people to look at the law in a richer way.","zh":"這個理論鼓勵人們以更豐富的方式看待法律。"},{"en":"In a richer way means with more depth, detail, and awareness of different dimensions.","zh":"“In a richer way” 指以更有深度、細節和多角度意識的方式。"},{"en":"Students understand a poem in a richer way when they study its language, history, and emotions.","zh":"當學生研究詩的語言、歷史和情感時，他們會以更豐富的方式理解詩。"},{"en":"If lawyers see clients as people with fears and hopes, they understand cases more fully.","zh":"如果律師把客戶視為有恐懼和希望的人，就能更完整理解案件。"},{"en":"The phrase suggests deeper understanding beyond a narrow view.","zh":"這個短語暗示超越狹窄觀點的深層理解。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":4},{"front":"bring to the table","meaning":"提出來討論","examples":[{"en":"The approach brings previously unnoticed issues to the table.","zh":"這種方法把以往未被注意到的議題提出來討論。"},{"en":"To bring something to the table means to introduce it for discussion or consideration.","zh":"“Bring something to the table” 指把某事提出，以供討論或考慮。"},{"en":"A student council can bring lunch problems to the table during a school meeting.","zh":"學生會可以在學校會議中把午餐問題提出來討論。"},{"en":"If therapeutic jurisprudence brings emotional harm to the table, legal reform can address it.","zh":"如果治療法理學把情感傷害提出來討論，法律改革就可以處理它。"},{"en":"The phrase means making an issue part of the conversation.","zh":"這個短語指令某議題成為討論的一部分。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":4},{"front":"areas and issues","meaning":"範疇和議題","examples":[{"en":"Therapeutic jurisprudence raises areas and issues that were previously ignored.","zh":"治療法理學提出了以往被忽視的範疇和議題。"},{"en":"Areas and issues means different subjects, topics, or problems that need attention.","zh":"“Areas and issues” 指需要關注的不同科目、題目或問題。"},{"en":"A school review may identify areas and issues such as homework pressure, bullying, and parent communication.","zh":"學校檢討可能找出功課壓力、欺凌和家長溝通等範疇和議題。"},{"en":"If new areas and issues are raised, old systems may need to change.","zh":"如果新的範疇和議題被提出，舊制度可能需要改變。"},{"en":"The phrase groups topics and problems together.","zh":"這個短語把題目和問題歸在一起。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":4},{"front":"previously gone unnoticed","meaning":"以往未被注意到","examples":[{"en":"Some emotional consequences of the law had previously gone unnoticed.","zh":"法律的一些情感後果以往未被注意到。"},{"en":"Previously gone unnoticed means not noticed before now.","zh":"“Previously gone unnoticed” 指在現在之前沒有被注意到。"},{"en":"A small leak may have previously gone unnoticed until the wall becomes wet.","zh":"小漏水可能以往未被注意到，直到牆壁變濕。"},{"en":"If emotional harm had gone unnoticed, courts may have repeated harmful practices for years.","zh":"如果情感傷害以往未被注意到，法院可能多年來重複有害做法。"},{"en":"The phrase describes something hidden or ignored in the past.","zh":"這個短語描述過去被隱藏或忽視的事。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":4},{"front":"think about","meaning":"思考","examples":[{"en":"The theory suggests that we think about the therapeutic consequences of the law.","zh":"這個理論建議我們思考法律的治療性後果。"},{"en":"To think about something means to consider it carefully instead of ignoring it.","zh":"“Think about” 某事指仔細考慮它，而不是忽視它。"},{"en":"Before choosing a course, students should think about time, cost, and future goals.","zh":"選擇課程前，學生應思考時間、成本和未來目標。"},{"en":"If judges think about emotional consequences, they may communicate more respectfully.","zh":"如果法官思考情感後果，他們可能更尊重地溝通。"},{"en":"The phrase encourages active consideration.","zh":"這個短語鼓勵主動考慮。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":4},{"front":"therapeutic consequences","meaning":"治療性後果","examples":[{"en":"Legal actors should consider the therapeutic consequences of the law.","zh":"法律參與者應考慮法律的治療性後果。"},{"en":"Therapeutic consequences are effects that improve well-being, healing, rehabilitation, or emotional safety.","zh":"治療性後果是改善福祉、治癒、更生或情緒安全的效果。"},{"en":"A respectful apology process may have therapeutic consequences for both victim and offender.","zh":"尊重的道歉程序可能對受害者和罪犯都有治療性後果。"},{"en":"If a legal decision encourages recovery and responsibility, its therapeutic consequences are important.","zh":"如果法律決定鼓勵復原和責任感，其治療性後果就很重要。"},{"en":"The phrase focuses on positive human effects of law.","zh":"這個短語強調法律的正面人性影響。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":4},{"front":"be factored into","meaning":"被納入……考慮","examples":[{"en":"Therapeutic consequences can be factored into legal decision-making.","zh":"治療性後果可以被納入法律決策考慮。"},{"en":"To be factored into a decision means to be included as one of the things considered.","zh":"“Be factored into” 決定指被列為考慮因素之一。"},{"en":"Travel time should be factored into a student’s choice of tutorial class.","zh":"學生選擇補習班時，交通時間應被納入考慮。"},{"en":"If emotional harm is factored into sentencing, the judge may choose a more constructive order.","zh":"如果情感傷害被納入判刑考慮，法官可能選擇更具建設性的命令。"},{"en":"The phrase means not ignoring an important consideration.","zh":"這個短語表示不忽略重要考慮因素。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":5},{"front":"law-making","meaning":"法律制定；立法","examples":[{"en":"Therapeutic consequences may be factored into law-making.","zh":"治療性後果可能被納入立法考慮。"},{"en":"Law-making is the process of creating, debating, and passing laws.","zh":"法律制定是創造、辯論和通過法律的過程。"},{"en":"Public consultation can be part of law-making when citizens give opinions on a new bill.","zh":"當市民就新法案給予意見時，公眾諮詢可以是立法的一部分。"},{"en":"If lawmakers consider mental health during law-making, new rules may be less harmful.","zh":"如果立法者在法律制定期間考慮精神健康，新規則可能較少傷害。"},{"en":"The phrase refers to creating laws, not enforcing them.","zh":"這個短語指創造法律，而不是執行法律。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":5},{"front":"lawyering","meaning":"律師工作","examples":[{"en":"Therapeutic jurisprudence can influence lawyering and judging.","zh":"治療法理學可以影響律師工作和審判工作。"},{"en":"Lawyering means the work lawyers do, including advising, negotiating, preparing cases, and speaking for clients.","zh":"律師工作指律師所做的工作，包括提供意見、談判、準備案件和代表客戶發言。"},{"en":"Good lawyering includes explaining legal choices in language that clients can understand.","zh":"良好的律師工作包括用客戶明白的語言解釋法律選項。"},{"en":"If lawyering is sensitive to emotions, clients may feel less confused and powerless.","zh":"如果律師工作重視情緒，客戶可能感到較少困惑和無力。"},{"en":"The phrase refers to legal practice by lawyers.","zh":"這個短語指律師的法律實務。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":5},{"front":"judging","meaning":"審判工作","examples":[{"en":"Judging may have therapeutic or antitherapeutic effects.","zh":"審判工作可能有治療性或反治療性效果。"},{"en":"Judging is the work of judges when they hear cases, make decisions, and give reasons.","zh":"審判工作是法官聆訊案件、作出決定和給予理由的工作。"},{"en":"A judge’s tone during sentencing can make judging feel respectful or humiliating.","zh":"法官在判刑時的語氣可以令審判工作感覺尊重或羞辱。"},{"en":"If judging explains consequences clearly, defendants may better understand their responsibilities.","zh":"如果審判工作清楚解釋後果，被告可能更好理解自己的責任。"},{"en":"The phrase refers to court decision-making by judges.","zh":"這個短語指法官在法院中的決策工作。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":5},{"front":"be divided into","meaning":"被分為","examples":[{"en":"The law can be divided into three categories.","zh":"法律可以被分為三個類別。"},{"en":"To be divided into categories means to be separated into groups for clearer understanding.","zh":"“Be divided into” 類別指被分成不同群組，以便更清楚理解。"},{"en":"A teacher may divide grammar mistakes into spelling, tense, and sentence-structure errors.","zh":"老師可能把文法錯誤分為拼字、時態和句子結構錯誤。"},{"en":"If a topic is divided into parts, students can study each part more easily.","zh":"如果題目被分成幾部分，學生可以更容易學習每一部分。"},{"en":"The phrase is useful for classification.","zh":"這個短語適合用於分類。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":5},{"front":"legal rules","meaning":"法律規則","examples":[{"en":"Legal rules are one category of the law.","zh":"法律規則是法律的一個類別。"},{"en":"Legal rules are official rules that tell people what they must, may, or must not do under law.","zh":"法律規則是正式規則，告訴人們在法律下必須、可以或不得做甚麼。"},{"en":"Traffic speed limits are legal rules that guide drivers’ behaviour.","zh":"交通車速限制是引導司機行為的法律規則。"},{"en":"If legal rules are unclear, people may not know how to obey them.","zh":"如果法律規則不清楚，人們可能不知道如何遵守。"},{"en":"The phrase refers to the written standards of law.","zh":"這個短語指法律中的書面標準。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":5},{"front":"legal procedures","meaning":"法律程序","examples":[{"en":"Legal procedures include hearings and trials.","zh":"法律程序包括聆訊及審訊。"},{"en":"Legal procedures are the formal steps used to handle legal cases.","zh":"法律程序是處理法律案件所用的正式步驟。"},{"en":"Filing an application, attending a hearing, and giving evidence are legal procedures.","zh":"提交申請、出席聆訊和作證都是法律程序。"},{"en":"If legal procedures are too confusing, people may feel anxious or excluded.","zh":"如果法律程序太混亂，人們可能感到焦慮或被排除在外。"},{"en":"The phrase refers to how legal matters are processed.","zh":"這個短語指法律事項如何被處理。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":5},{"front":"hearings and trials","meaning":"聆訊及審訊","examples":[{"en":"Hearings and trials are examples of legal procedures.","zh":"聆訊及審訊是法律程序的例子。"},{"en":"Hearings and trials are formal court events where legal issues are discussed or decided.","zh":"聆訊及審訊是討論或裁決法律問題的正式法院活動。"},{"en":"A witness may need to attend hearings and trials to give evidence.","zh":"證人可能需要出席聆訊及審訊作證。"},{"en":"If hearings and trials are delayed, families and defendants may experience long stress.","zh":"如果聆訊及審訊被延誤，家庭和被告可能經歷長期壓力。"},{"en":"The phrase refers to important stages in court cases.","zh":"這個短語指法院案件中的重要階段。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":5},{"front":"legal actors","meaning":"法律參與者","examples":[{"en":"Judges, lawyers and therapists can be legal actors.","zh":"法官、律師和治療師都可以是法律參與者。"},{"en":"Legal actors are people who take part in the legal system and influence legal outcomes or experiences.","zh":"法律參與者是參與法律制度並影響法律結果或經驗的人。"},{"en":"Police officers, judges, lawyers, and probation officers may all be legal actors.","zh":"警員、法官、律師和感化主任都可能是法律參與者。"},{"en":"If legal actors speak respectfully, they can reduce fear during the legal process.","zh":"如果法律參與者尊重地說話，就可以減少法律程序中的恐懼。"},{"en":"The phrase focuses on people who act within law.","zh":"這個短語強調在法律中行事的人。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":5},{"front":"the behaviour of","meaning":"……的行為","examples":[{"en":"The theory examines the behaviour of judges and lawyers.","zh":"這個理論研究法官和律師的行為。"},{"en":"The behaviour of someone means the way that person acts, speaks, and responds.","zh":"“The behaviour of” 某人指該人行動、說話和回應的方式。"},{"en":"A teacher may study the behaviour of students during group work.","zh":"老師可能研究學生在小組活動中的行為。"},{"en":"If the behaviour of judges is cold or unclear, defendants may feel frightened or ignored.","zh":"如果法官的行為冷漠或不清楚，被告可能感到害怕或被忽視。"},{"en":"The phrase focuses on actions, not only official roles.","zh":"這個短語強調行動，而不只是官方角色。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":5},{"front":"acting in a legal context","meaning":"在法律情境中行事","examples":[{"en":"Therapists may act in a legal context.","zh":"治療師可能在法律情境中行事。"},{"en":"Acting in a legal context means working or making decisions within a legal setting or legal process.","zh":"“Acting in a legal context” 指在法律環境或法律程序中工作或作決定。"},{"en":"A counsellor acts in a legal context when preparing a report for court.","zh":"輔導員為法院準備報告時，就是在法律情境中行事。"},{"en":"If therapists act in a legal context, their words may influence a judge’s decision.","zh":"如果治療師在法律情境中行事，他們的說話可能影響法官決定。"},{"en":"The phrase shows that non-lawyers can also affect legal cases.","zh":"這個短語顯示非法律人士也可以影響法律案件。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":5},{"front":"much of what","meaning":"……所做的大部分事情","examples":[{"en":"Much of what legal actors do affects people emotionally.","zh":"法律參與者所做的大部分事情都會在情感上影響人。"},{"en":"Much of what someone does means a large part of their actions or work.","zh":"“Much of what” 某人做的事，指其行動或工作中的很大部分。"},{"en":"Much of what teachers do happens outside lessons, such as planning and marking.","zh":"老師所做的大部分事情發生在課堂以外，例如備課和批改。"},{"en":"If much of what judges say affects emotions, courtroom language matters.","zh":"如果法官所說的大部分話都影響情緒，法庭語言就很重要。"},{"en":"The phrase highlights a large portion of someone’s activity.","zh":"這個短語強調某人活動中的大部分。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":6},{"front":"have an impact on","meaning":"對……有影響","examples":[{"en":"Legal actors can have an impact on psychological well-being.","zh":"法律參與者可以對心理健康有影響。"},{"en":"To have an impact on something means to affect it in some way.","zh":"“Have an impact on” 某事指以某種方式影響它。"},{"en":"A supportive teacher can have an impact on a student’s confidence.","zh":"支持性的老師可以對學生信心有影響。"},{"en":"If a lawyer explains a case clearly, it may have a positive impact on the client’s stress level.","zh":"如果律師清楚解釋案件，可能對客戶的壓力水平有正面影響。"},{"en":"The phrase describes influence or effect.","zh":"這個短語描述影響或效果。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":6},{"front":"persons affected by the law","meaning":"受法律影響的人","examples":[{"en":"Legal actors influence persons affected by the law.","zh":"法律參與者影響受法律影響的人。"},{"en":"Persons affected by the law are people whose lives, rights, duties, or emotions are influenced by legal rules or procedures.","zh":"受法律影響的人，是生活、權利、責任或情緒受法律規則或程序影響的人。"},{"en":"A tenant facing eviction is a person affected by housing law.","zh":"面臨被迫遷的租客就是受住房法律影響的人。"},{"en":"If persons affected by the law feel confused, legal actors should explain the process clearly.","zh":"如果受法律影響的人感到困惑，法律參與者應清楚解釋程序。"},{"en":"The phrase focuses on real people, not abstract legal principles.","zh":"這個短語強調真實的人，而不是抽象法律原則。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":6},{"front":"dialogues that judges have with defendants","meaning":"法官與被告之間的對話","examples":[{"en":"The dialogues that judges have with defendants can affect emotional well-being.","zh":"法官與被告之間的對話可以影響情緒健康。"},{"en":"Dialogues that judges have with defendants are the conversations or exchanges between the court and the accused person.","zh":"法官與被告之間的對話，是法院與被控告者之間的交談或交流。"},{"en":"A judge may ask a defendant questions to understand their situation before sentencing.","zh":"法官可能在判刑前向被告提問，以了解其情況。"},{"en":"If these dialogues are respectful, defendants may feel more responsible and less humiliated.","zh":"如果這些對話尊重被告，被告可能更有責任感，也較少感到羞辱。"},{"en":"The phrase highlights the human effect of courtroom communication.","zh":"這個短語強調法庭溝通對人的影響。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":6},{"front":"defendants","meaning":"被告","examples":[{"en":"Judges often speak directly to defendants in court.","zh":"法官經常在法庭上直接與被告說話。"},{"en":"Defendants are people who are accused of a crime or sued in a legal case.","zh":"被告是被指控犯罪或在法律案件中被起訴的人。"},{"en":"A defendant may need a lawyer to explain the charges and possible outcomes.","zh":"被告可能需要律師解釋控罪和可能結果。"},{"en":"If defendants do not understand the court process, they may feel anxious and powerless.","zh":"如果被告不明白法院程序，可能感到焦慮和無力。"},{"en":"The word refers to people facing legal claims or criminal charges.","zh":"這個詞指面對法律申索或刑事控罪的人。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":6},{"front":"lawyers have with clients","meaning":"律師與客戶之間的對話","examples":[{"en":"The conversations that lawyers have with clients may affect clients emotionally.","zh":"律師與客戶之間的對話可能在情感上影響客戶。"},{"en":"Conversations lawyers have with clients are professional discussions about legal problems, options, and risks.","zh":"律師與客戶之間的對話，是關於法律問題、選項和風險的專業討論。"},{"en":"A lawyer may speak with a client before court to explain what will happen next.","zh":"律師可能在開庭前與客戶交談，解釋接下來會發生甚麼。"},{"en":"If the lawyer speaks clearly and calmly, the client may feel less frightened.","zh":"如果律師清楚而冷靜地說話，客戶可能較少害怕。"},{"en":"The phrase shows that legal advice also has emotional effects.","zh":"這個短語顯示法律意見也有情感影響。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":6},{"front":"especially applicable to","meaning":"尤其適用於","examples":[{"en":"Therapeutic jurisprudence is especially applicable to the role of legal actors.","zh":"治療法理學尤其適用於法律參與者的角色。"},{"en":"Especially applicable to means particularly relevant or useful for a specific area.","zh":"“Especially applicable to” 指對某特定範疇特別相關或有用。"},{"en":"Clear communication training is especially applicable to teachers who work with young children.","zh":"清晰溝通訓練尤其適用於與年幼兒童工作的老師。"},{"en":"If judges and lawyers directly affect people’s emotions, therapeutic jurisprudence is especially relevant to their work.","zh":"如果法官和律師直接影響人的情緒，治療法理學就尤其適用於他們的工作。"},{"en":"The phrase highlights the area where an idea fits best.","zh":"這個短語突出某想法最適合的範疇。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":6},{"front":"a relatively new phenomenon","meaning":"相對較新的現象","examples":[{"en":"Therapeutic jurisprudence is a relatively new phenomenon.","zh":"治療法理學是一個相對較新的現象。"},{"en":"A relatively new phenomenon is something that has appeared recently compared with older ideas or practices.","zh":"相對較新的現象，是相比舊想法或做法而言近期才出現的事物。"},{"en":"Online tutoring is a relatively new phenomenon compared with traditional classroom teaching.","zh":"與傳統課室教學相比，網上補習是相對較新的現象。"},{"en":"If a field is relatively new, researchers may still be developing its concepts and methods.","zh":"如果一個領域相對較新，研究人員可能仍在發展其概念和方法。"},{"en":"The phrase describes recent development in context.","zh":"這個短語在語境中描述近期發展。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":6},{"front":"in the early days of","meaning":"在……的早期","examples":[{"en":"In the early days of law, attitudes were very different.","zh":"在法律的早期，態度非常不同。"},{"en":"In the early days of something means during its first stage or earliest period.","zh":"“In the early days of” 某事指其最初階段或最早時期。"},{"en":"In the early days of a business, the owner may handle sales, accounts, and cleaning alone.","zh":"在生意早期，老闆可能獨自處理銷售、帳目和清潔。"},{"en":"If attitudes were different in the early days, later reforms may show how thinking changed.","zh":"如果早期態度不同，後來改革可能顯示思維如何改變。"},{"en":"The phrase contrasts beginnings with later development.","zh":"這個短語把開始階段與後來發展作對比。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":6},{"front":"attitudes were very different","meaning":"態度非常不同","examples":[{"en":"In the early days of law, attitudes were very different.","zh":"在法律的早期，態度非常不同。"},{"en":"Attitudes were very different means people thought about the issue in a very different way before.","zh":"“Attitudes were very different” 指以前人們對該議題的想法非常不同。"},{"en":"In the past, attitudes to mental health were very different from today’s views.","zh":"過去，人們對精神健康的態度與今天的看法非常不同。"},{"en":"If attitudes change, legal systems may begin to treat people with more dignity.","zh":"如果態度改變，法律制度可能開始更有尊嚴地對待人。"},{"en":"The phrase signals a contrast between past and present thinking.","zh":"這個短語表示過去和現在思維的對比。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":6},{"front":"efforts were focused primarily on","meaning":"努力主要集中於","examples":[{"en":"Early efforts were focused primarily on problems with testimony.","zh":"早期努力主要集中於證供問題。"},{"en":"Efforts were focused primarily on something means most attention and work were directed there.","zh":"“Efforts were focused primarily on” 某事指大部分注意力和工作都放在那裡。"},{"en":"A school’s early efforts may be focused primarily on improving reading scores.","zh":"學校早期努力可能主要集中於改善閱讀成績。"},{"en":"If early legal research focused only on testimony problems, other emotional issues may have been missed.","zh":"如果早期法律研究只集中於證供問題，其他情感議題可能被忽略。"},{"en":"The phrase shows where the main energy was spent.","zh":"這個短語顯示主要精力花在哪裡。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":6},{"front":"various sorts of testimony","meaning":"各種證供","examples":[{"en":"Early legal discussions focused on what was wrong with various sorts of testimony.","zh":"早期法律討論集中於各種證供有甚麼問題。"},{"en":"Various sorts of testimony means different kinds of evidence given by witnesses or experts.","zh":"各種證供指由證人或專家提供的不同種類證據。"},{"en":"A court may hear testimony from victims, police officers, doctors, and family members.","zh":"法院可能聽取受害者、警員、醫生和家庭成員的證供。"},{"en":"If testimony is unreliable, the legal outcome may become unfair.","zh":"如果證供不可靠，法律結果可能變得不公平。"},{"en":"The phrase refers to different forms of spoken or written legal evidence.","zh":"這個短語指不同形式的口頭或書面法律證據。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":7},{"front":"early emphasis","meaning":"早期重點","examples":[{"en":"There were good reasons for that early emphasis.","zh":"那個早期重點有充分理由。"},{"en":"Early emphasis means the main focus placed on something at the beginning.","zh":"早期重點指一開始放在某事上的主要關注。"},{"en":"A language course may place early emphasis on pronunciation before moving to writing.","zh":"語言課可能早期重點放在發音上，之後才轉向寫作。"},{"en":"If early emphasis is too narrow, important later issues may be ignored.","zh":"如果早期重點太狹窄，重要的後續議題可能被忽視。"},{"en":"The phrase identifies what received attention first.","zh":"這個短語指出最初受到注意的事情。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":7},{"front":"an exclusive focus on","meaning":"只集中於……","examples":[{"en":"An exclusive focus on problems can be shortsighted.","zh":"只集中於問題可能是短視的。"},{"en":"An exclusive focus on something means paying attention only to that thing and ignoring others.","zh":"“An exclusive focus on” 某事指只注意該事而忽視其他事情。"},{"en":"An exclusive focus on exam scores may ignore students’ confidence and curiosity.","zh":"只集中於考試分數可能忽視學生的信心和好奇心。"},{"en":"If law focuses only on what goes wrong, it may miss what can be improved or strengthened.","zh":"如果法律只集中於出錯的地方，可能錯過可以改善或強化之處。"},{"en":"The phrase warns against a narrow viewpoint.","zh":"這個短語提醒不要有狹窄觀點。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":7},{"front":"rather than also looking at","meaning":"而不是也看","examples":[{"en":"The field looks at what is right rather than only at what is wrong.","zh":"這個領域看甚麼是正確的，而不是只看甚麼是錯的。"},{"en":"Rather than also looking at means instead of adding another side or perspective to the discussion.","zh":"“Rather than also looking at” 指沒有把另一面或另一角度加入討論，而是偏向某一邊。"},{"en":"A teacher should study what students do well rather than only what they get wrong.","zh":"老師應研究學生做得好的地方，而不是只看他們做錯甚麼。"},{"en":"If reformers look at strengths as well as problems, they can build better systems.","zh":"如果改革者同時看強項和問題，就能建立更好的制度。"},{"en":"The phrase creates a contrast between a narrow focus and a broader one.","zh":"這個短語在狹窄焦點和較廣闊焦點之間形成對比。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":7},{"front":"further developed","meaning":"進一步發展","examples":[{"en":"Positive aspects of the legal process could be further developed.","zh":"法律程序的正面方面可以進一步發展。"},{"en":"Further developed means improved, expanded, or made more complete.","zh":"“Further developed” 指被改善、擴展或變得更完整。"},{"en":"A student’s good idea can be further developed by adding examples and evidence.","zh":"學生的好想法可以透過加入例子和證據進一步發展。"},{"en":"If a court practice already helps people, it can be further developed into a regular programme.","zh":"如果法院做法已經幫助到人，它可以進一步發展成定期計劃。"},{"en":"The phrase suggests building on something that already exists.","zh":"這個短語暗示在現有事物上繼續建立。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":7},{"front":"seriously shortsighted","meaning":"嚴重短視","examples":[{"en":"An exclusive focus on problems is seriously shortsighted.","zh":"只集中於問題是嚴重短視的。"},{"en":"Seriously shortsighted means badly limited because it ignores long-term effects or wider possibilities.","zh":"“Seriously shortsighted” 指因忽視長遠影響或更廣可能性而非常有限。"},{"en":"Cutting all teacher training to save money is seriously shortsighted because teaching quality may fall later.","zh":"為省錢而取消所有教師培訓是嚴重短視，因為教學質素日後可能下降。"},{"en":"If legal reform ignores positive practices, it may miss chances to improve people’s lives.","zh":"如果法律改革忽視正面做法，可能錯失改善人們生活的機會。"},{"en":"The phrase gives a strong criticism of narrow thinking.","zh":"這個短語強烈批評狹窄思維。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":7},{"front":"focus attention on","meaning":"將注意力集中於","examples":[{"en":"Therapeutic jurisprudence focuses attention on an under-appreciated aspect of law.","zh":"治療法理學將注意力集中於法律中一個被低估的方面。"},{"en":"To focus attention on something means to direct people’s notice and thinking toward it.","zh":"“Focus attention on” 某事指把人們的注意和思考引向它。"},{"en":"A school campaign may focus attention on bullying that students were afraid to report.","zh":"學校活動可能將注意力集中於學生害怕舉報的欺凌問題。"},{"en":"If a theory focuses attention on emotional harm, people may start measuring it seriously.","zh":"如果一個理論將注意力集中於情感傷害，人們可能開始認真量度它。"},{"en":"The phrase means making something more visible and important.","zh":"這個短語指令某事更可見和更重要。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":7},{"front":"previously under-appreciated aspect","meaning":"以往被低估的方面","examples":[{"en":"The emotional effect of law was a previously under-appreciated aspect.","zh":"法律的情感影響是以往被低估的方面。"},{"en":"A previously under-appreciated aspect is a part of something that was not valued enough before.","zh":"以往被低估的方面，是某事中以前沒有得到足夠重視的部分。"},{"en":"In education, sleep may be a previously under-appreciated aspect of exam success.","zh":"在教育中，睡眠可能是考試成功中以往被低估的方面。"},{"en":"If emotional effects were under-appreciated, legal systems may have ignored real human suffering.","zh":"如果情感影響被低估，法律制度可能忽略真實的人類痛苦。"},{"en":"The phrase points to something important that people used to overlook.","zh":"這個短語指出以前被忽視的重要事物。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":7},{"front":"encourage someone to","meaning":"鼓勵某人","examples":[{"en":"The approach encourages people to look for promising developments.","zh":"這種方法鼓勵人們尋找有前景的發展。"},{"en":"To encourage someone to do something means to make them more willing or confident to do it.","zh":"“Encourage someone to” 做某事指令某人更願意或更有信心去做它。"},{"en":"A teacher can encourage students to read by choosing stories they enjoy.","zh":"老師可以透過選擇學生喜歡的故事，鼓勵他們閱讀。"},{"en":"If legal scholars are encouraged to borrow ideas, reform may become more creative.","zh":"如果法律學者被鼓勵借鑑想法，改革可能變得更有創意。"},{"en":"The phrase shows support that leads to action.","zh":"這個短語顯示導致行動的支持。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":7},{"front":"look very hard for","meaning":"認真尋找","examples":[{"en":"Therapeutic jurisprudence encourages us to look very hard for promising developments.","zh":"治療法理學鼓勵我們認真尋找有前景的發展。"},{"en":"To look very hard for something means to search carefully and seriously for it.","zh":"“Look very hard for” 某事指仔細而認真地尋找它。"},{"en":"A student should look very hard for evidence before writing an argumentative essay.","zh":"學生在寫議論文前應認真尋找證據。"},{"en":"If legal reformers look hard for useful ideas, they may find help in psychology or education.","zh":"如果法律改革者認真尋找有用想法，他們可能在心理學或教育中找到幫助。"},{"en":"The phrase suggests determined searching, not casual noticing.","zh":"這個短語暗示堅定搜尋，而不是隨意注意。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":7},{"front":"promising developments","meaning":"有前景的發展","examples":[{"en":"Researchers should look for promising developments in other fields.","zh":"研究人員應尋找其他範疇中有前景的發展。"},{"en":"Promising developments are new ideas or methods that seem likely to succeed or help.","zh":"有前景的發展是看似可能成功或有幫助的新想法或方法。"},{"en":"A new reading programme with early positive results is a promising development for schools.","zh":"有早期正面成果的新閱讀計劃，是學校中有前景的發展。"},{"en":"If behavioural science offers promising developments, law may borrow them to improve rehabilitation.","zh":"如果行為科學提供有前景的發展，法律可能借鑑它們來改善更生。"},{"en":"The phrase describes hopeful progress, not guaranteed success.","zh":"這個短語描述有希望的進展，而不是保證成功。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":7},{"front":"borrow from","meaning":"借鑑自","examples":[{"en":"The legal system can borrow from behavioural science literature.","zh":"法律制度可以借鑑自行為科學文獻。"},{"en":"To borrow from a field means to use ideas, methods, or evidence from that field.","zh":"“Borrow from” 某範疇指使用該範疇的想法、方法或證據。"},{"en":"Teachers may borrow from psychology when designing lessons for anxious students.","zh":"老師設計給焦慮學生的課堂時，可能借鑑自心理學。"},{"en":"If law borrows from behavioural science, it may better understand why offenders act as they do.","zh":"如果法律借鑑自行為科學，就可能更好理解罪犯為何如此行動。"},{"en":"The phrase describes learning from another area, not copying blindly.","zh":"這個短語描述向另一範疇學習，而不是盲目複製。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":8},{"front":"behavioural science literature","meaning":"行為科學文獻","examples":[{"en":"Therapeutic jurisprudence borrows from behavioural science literature.","zh":"治療法理學借鑑自行為科學文獻。"},{"en":"Behavioural science literature is research writing about how people think, act, learn, and change behaviour.","zh":"行為科學文獻是關於人如何思考、行動、學習和改變行為的研究文章。"},{"en":"A counsellor may read behavioural science literature to understand habits and motivation.","zh":"輔導員可能閱讀行為科學文獻，以理解習慣和動機。"},{"en":"If law uses this literature, it can design programmes that fit real human behaviour better.","zh":"如果法律使用這些文獻，就能設計更符合真實人類行為的計劃。"},{"en":"The phrase refers to research from psychology, criminology, education, and related fields.","zh":"這個短語指來自心理學、犯罪學、教育和相關領域的研究。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":8},{"front":"have nothing obviously to do with","meaning":"與……表面上沒有明顯關係","examples":[{"en":"Some behavioural science literature has nothing obviously to do with the law.","zh":"一些行為科學文獻與法律表面上沒有明顯關係。"},{"en":"To have nothing obviously to do with something means not to appear directly connected to it at first sight.","zh":"“Have nothing obviously to do with” 某事指乍看之下與它沒有直接關係。"},{"en":"A study about classroom motivation may seem to have nothing obviously to do with criminal courts.","zh":"關於課室動機的研究，表面上可能與刑事法院沒有明顯關係。"},{"en":"If an idea looks unrelated at first, creative thinking may still reveal a useful link.","zh":"如果一個想法起初看似無關，創意思考仍可能揭示有用連繫。"},{"en":"The phrase points to a hidden or indirect connection.","zh":"這個短語指出隱藏或間接關係。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":8},{"front":"think creatively about","meaning":"創意思考","examples":[{"en":"The approach encourages people to think creatively about legal reform.","zh":"這種方法鼓勵人們創意思考法律改革。"},{"en":"To think creatively about something means to look for new, flexible, and original solutions.","zh":"“Think creatively about” 某事指尋找新穎、靈活和原創的解決方案。"},{"en":"A teacher may think creatively about homework by using short voice recordings instead of essays every week.","zh":"老師可能透過使用簡短錄音，而不是每週寫作文，創意思考功課。"},{"en":"If lawyers think creatively, they may design processes that reduce harm and increase responsibility.","zh":"如果律師創意思考，可能設計出減少傷害並增加責任感的程序。"},{"en":"The phrase encourages imagination guided by practical needs.","zh":"這個短語鼓勵由實際需要引導的想像力。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":8},{"front":"from other fields","meaning":"來自其他範疇","examples":[{"en":"Promising developments from other fields may be useful in law.","zh":"來自其他範疇的有前景發展可能在法律中有用。"},{"en":"From other fields means coming from different areas of study, work, or practice.","zh":"“From other fields” 指來自不同研究、工作或實踐範疇。"},{"en":"A business may use ideas from sports coaching to train staff motivation.","zh":"企業可能使用來自運動教練的想法來培訓員工動機。"},{"en":"If law borrows ideas from psychology, it may better support behavioural change.","zh":"如果法律借鑑來自心理學的想法，可能更好支援行為改變。"},{"en":"The phrase encourages cross-disciplinary learning.","zh":"這個短語鼓勵跨學科學習。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":8},{"front":"be brought into","meaning":"被引入","examples":[{"en":"Ideas from other fields might be brought into the legal system.","zh":"來自其他範疇的想法可能被引入法律制度。"},{"en":"To be brought into a system means to be introduced and used there.","zh":"“Be brought into” 某制度指被引入並在那裡使用。"},{"en":"Technology from hospitals can be brought into schools to improve health checks.","zh":"醫院的科技可以被引入學校，以改善健康檢查。"},{"en":"If behavioural ideas are brought into courts, judges may use them during sentencing.","zh":"如果行為學想法被引入法院，法官可能在判刑時使用它們。"},{"en":"The phrase describes transferring an idea into a new setting.","zh":"這個短語描述把想法轉移到新環境中。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":8},{"front":"the legal system","meaning":"法律制度","examples":[{"en":"Therapeutic ideas can be brought into the legal system.","zh":"治療性想法可以被引入法律制度。"},{"en":"The legal system is the organised set of laws, courts, procedures, and legal institutions in a society.","zh":"法律制度是一個社會中由法律、法院、程序和法律機構組成的有組織系統。"},{"en":"Citizens depend on the legal system to resolve disputes and protect rights.","zh":"市民依靠法律制度解決糾紛和保護權利。"},{"en":"If the legal system becomes more humane, people may trust it more.","zh":"如果法律制度變得更人性化，人們可能更信任它。"},{"en":"The phrase refers to the whole structure of law in practice.","zh":"這個短語指法律在實踐中的整體結構。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":8},{"front":"as a result of","meaning":"由於","examples":[{"en":"New programmes have emerged as a result of this multidisciplinary approach.","zh":"由於這種跨學科方法，新計劃已經出現。"},{"en":"As a result of means because of something or caused by it.","zh":"“As a result of” 指由於某事或由它造成。"},{"en":"As a result of better planning, the school trip finished on time.","zh":"由於更好的規劃，學校旅行準時結束。"},{"en":"If law borrows from psychology, new rehabilitation programmes may emerge as a result.","zh":"如果法律借鑑心理學，新的更生計劃可能因此出現。"},{"en":"The phrase links a cause with an outcome.","zh":"這個短語把原因與結果連繫起來。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":8},{"front":"multidisciplinary approach","meaning":"跨學科方法","examples":[{"en":"Therapeutic jurisprudence uses a multidisciplinary approach.","zh":"治療法理學使用跨學科方法。"},{"en":"A multidisciplinary approach uses knowledge from several different fields to understand or solve a problem.","zh":"跨學科方法使用來自幾個不同範疇的知識來理解或解決問題。"},{"en":"A hospital team may use a multidisciplinary approach by involving doctors, nurses, therapists, and social workers.","zh":"醫院團隊可能透過讓醫生、護士、治療師和社工參與來使用跨學科方法。"},{"en":"If law uses psychology and behavioural science, reform may become more practical and humane.","zh":"如果法律使用心理學和行為科學，改革可能變得更實際和人性化。"},{"en":"The phrase describes cooperation across disciplines.","zh":"這個短語描述跨學科合作。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":8},{"front":"certain kinds of","meaning":"某幾類","examples":[{"en":"Certain kinds of rehabilitative programmes look promising.","zh":"某幾類更生計劃看來有前景。"},{"en":"Certain kinds of something means particular types, not all types.","zh":"“Certain kinds of” 某事指某些特定類型，而不是所有類型。"},{"en":"Certain kinds of exercise are better for beginners because they are safer and easier to repeat.","zh":"某幾類運動較適合初學者，因為它們較安全且較容易重複。"},{"en":"If only some programmes work well, researchers must identify which kinds are effective.","zh":"如果只有一些計劃效果好，研究人員必須識別哪些類型有效。"},{"en":"The phrase avoids overgeneralising.","zh":"這個短語避免過度概括。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":8},{"front":"rehabilitative programmes","meaning":"更生計劃","examples":[{"en":"Rehabilitative programmes may help offenders change their behaviour.","zh":"更生計劃可能幫助罪犯改變行為。"},{"en":"Rehabilitative programmes are organised activities designed to help people recover, improve, or avoid harmful behaviour.","zh":"更生計劃是旨在幫助人復原、改善或避免有害行為的有組織活動。"},{"en":"A prison may offer rehabilitative programmes that teach anger control and job skills.","zh":"監獄可能提供教授憤怒控制和工作技能的更生計劃。"},{"en":"If offenders join effective rehabilitative programmes, they may be less likely to re-offend.","zh":"如果罪犯參與有效更生計劃，他們可能較不容易重犯。"},{"en":"The phrase focuses on change and reintegration, not punishment alone.","zh":"這個短語強調改變和重新融入社會，而不只是懲罰。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":8},{"front":"begin to emerge","meaning":"開始出現","examples":[{"en":"Some promising programmes have begun to emerge.","zh":"一些有前景的計劃已開始出現。"},{"en":"To begin to emerge means to start appearing or becoming noticeable.","zh":"“Begin to emerge” 指開始出現或變得可見。"},{"en":"New study habits may begin to emerge after a student keeps a daily routine for a month.","zh":"如果學生保持每日作息一個月，新的學習習慣可能開始出現。"},{"en":"If useful programmes begin to emerge, the legal system has new options to test.","zh":"如果有用計劃開始出現，法律制度就有新選項可測試。"},{"en":"The phrase describes the early stage of appearance.","zh":"這個短語描述出現的早期階段。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":9},{"front":"look rather promising","meaning":"看來頗有前景","examples":[{"en":"Certain kinds of rehabilitative programmes look rather promising.","zh":"某幾類更生計劃看來頗有前景。"},{"en":"Look rather promising means seem likely to be useful or successful, though not yet certain.","zh":"“Look rather promising” 指看似可能有用或成功，但尚未確定。"},{"en":"A new reading app looks rather promising if students use it regularly and improve.","zh":"如果學生定期使用新閱讀應用程式並有進步，它看來頗有前景。"},{"en":"If early results are good but not final, researchers may say the programme looks promising.","zh":"如果早期結果良好但未最終確認，研究人員可能說該計劃有前景。"},{"en":"The phrase expresses cautious optimism.","zh":"這個短語表達謹慎樂觀。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":9},{"front":"cognitive behavioural treatment","meaning":"認知行為治療","examples":[{"en":"Cognitive behavioural treatment can help offenders change their thinking.","zh":"認知行為治療可以幫助罪犯改變思維方式。"},{"en":"Cognitive behavioural treatment is a form of treatment that helps people change harmful thoughts and behaviours.","zh":"認知行為治療是一種幫助人改變有害想法和行為的治療形式。"},{"en":"A counsellor may use cognitive behavioural treatment to help a student manage anger before arguments begin.","zh":"輔導員可能使用認知行為治療，幫助學生在爭執開始前管理憤怒。"},{"en":"If offenders learn to recognise risky thoughts, they may act differently in future situations.","zh":"如果罪犯學會辨認高風險想法，他們日後在類似情況中可能採取不同行動。"},{"en":"The phrase connects thinking patterns with behaviour change.","zh":"這個短語把思維模式與行為改變連繫起來。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":9},{"front":"encourage offenders to","meaning":"鼓勵罪犯去","examples":[{"en":"The treatment encourages offenders to prepare relapse prevention plans.","zh":"這種治療鼓勵罪犯制定預防重犯計劃。"},{"en":"To encourage offenders to do something means to guide or motivate people who have committed crimes to take that action.","zh":"“Encourage offenders to” 做某事指引導或激勵已犯罪的人採取該行動。"},{"en":"A probation officer may encourage offenders to attend counselling regularly.","zh":"感化主任可能鼓勵罪犯定期接受輔導。"},{"en":"If offenders are encouraged to plan ahead, they may handle risky situations better.","zh":"如果罪犯被鼓勵預先計劃，他們可能更好處理高風險情況。"},{"en":"The phrase suggests support for positive behavioural change.","zh":"這個短語暗示對正面行為改變的支援。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":9},{"front":"offenders","meaning":"罪犯","examples":[{"en":"Offenders may be asked to think through the causes of their behaviour.","zh":"罪犯可能被要求仔細思考其行為的原因。"},{"en":"Offenders are people who have committed crimes or broken the law.","zh":"罪犯是犯下罪行或違反法律的人。"},{"en":"Young offenders may receive rehabilitation instead of only punishment.","zh":"年輕罪犯可能得到更生安排，而不只是懲罰。"},{"en":"If offenders understand why they acted wrongly, they may have a better chance of changing.","zh":"如果罪犯明白自己為何錯誤行事，就可能有更好改變機會。"},{"en":"The word refers to people responsible for offences.","zh":"這個詞指對罪行負責的人。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":9},{"front":"relapse prevention plans","meaning":"預防重犯計劃","examples":[{"en":"Offenders prepare relapse prevention plans as part of treatment.","zh":"罪犯制定預防重犯計劃作為治療的一部分。"},{"en":"Relapse prevention plans are plans designed to stop someone from returning to harmful behaviour.","zh":"預防重犯計劃是旨在阻止某人回到有害行為的計劃。"},{"en":"A person trying to stop smoking may make a relapse prevention plan for stressful days.","zh":"嘗試戒煙的人可能為壓力大的日子制定預防復發計劃。"},{"en":"If offenders know their triggers, relapse prevention plans can help them avoid re-offending.","zh":"如果罪犯知道自己的誘因，預防重犯計劃可以幫助他們避免重犯。"},{"en":"The phrase focuses on preventing a return to old patterns.","zh":"這個短語強調防止回到舊模式。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":9},{"front":"require someone to think through","meaning":"要求某人仔細思考","examples":[{"en":"The plans require offenders to think through the chain of events.","zh":"這些計劃要求罪犯仔細思考一連串事件。"},{"en":"To require someone to think through something means to make them carefully examine each step or reason.","zh":"“Require someone to think through” 某事指要求某人仔細檢視每一步或原因。"},{"en":"A teacher may require students to think through every stage of a science experiment.","zh":"老師可能要求學生仔細思考科學實驗的每個階段。"},{"en":"If offenders think through what happens before a crime, they can identify points where they can stop.","zh":"如果罪犯仔細思考犯罪前發生甚麼，就能找出可以停下來的時點。"},{"en":"The phrase stresses careful step-by-step thinking.","zh":"這個短語強調逐步仔細思考。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":9},{"front":"the chain of events","meaning":"一連串事件","examples":[{"en":"Offenders examine the chain of events that leads to criminality.","zh":"罪犯檢視導致犯罪行為的一連串事件。"},{"en":"The chain of events is the connected sequence of things that happen before a result.","zh":"一連串事件是結果出現前互相連接的事情次序。"},{"en":"A teacher may ask students to describe the chain of events that led to a classroom argument.","zh":"老師可能要求學生描述導致課室爭執的一連串事件。"},{"en":"If one event triggers another, understanding the chain can help prevent the final problem.","zh":"如果一件事引發另一件事，理解這條鏈可以幫助防止最終問題。"},{"en":"The phrase shows how actions are linked over time.","zh":"這個短語顯示行動如何隨時間互相連接。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":9},{"front":"lead to criminality","meaning":"導致犯罪行為","examples":[{"en":"The treatment explores the events that lead to criminality.","zh":"這種治療探討導致犯罪行為的事件。"},{"en":"To lead to criminality means to contribute to behaviour that breaks the law.","zh":"“Lead to criminality” 指促成違法行為。"},{"en":"Poor supervision, peer pressure, and anger may lead some young people toward crime.","zh":"缺乏監管、朋輩壓力和憤怒可能令一些年輕人走向犯罪。"},{"en":"If offenders know what situations lead to criminality, they can avoid those situations earlier.","zh":"如果罪犯知道哪些情況會導致犯罪行為，就能更早避開那些情況。"},{"en":"The phrase focuses on causes that move someone toward crime.","zh":"這個短語強調推動某人走向犯罪的原因。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":9},{"front":"reasoning and rehabilitation programmes","meaning":"推理及更生計劃","examples":[{"en":"Reasoning and rehabilitation programmes teach offenders to change their thinking.","zh":"推理及更生計劃教罪犯改變思維方式。"},{"en":"Reasoning and rehabilitation programmes are programmes that teach thinking skills and support behavioural change.","zh":"推理及更生計劃是教授思考技巧並支援行為改變的計劃。"},{"en":"A prison may use reasoning and rehabilitation programmes to help offenders pause before acting.","zh":"監獄可能使用推理及更生計劃，幫助罪犯在行動前停下來。"},{"en":"If offenders learn better reasoning, they may make safer choices in difficult situations.","zh":"如果罪犯學會更好的推理，就可能在困難情況中作出較安全選擇。"},{"en":"The phrase combines mental skill training with rehabilitation.","zh":"這個短語結合心理技巧訓練與更生。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":9},{"front":"change their thinking","meaning":"改變思維方式","examples":[{"en":"Offenders are taught to change their thinking.","zh":"罪犯被教導改變思維方式。"},{"en":"To change their thinking means to develop new ways of understanding situations and making decisions.","zh":"“Change their thinking” 指發展理解情況和作決定的新方式。"},{"en":"A student can change their thinking by seeing mistakes as practice rather than failure.","zh":"學生可以透過把錯誤視為練習而不是失敗來改變思維方式。"},{"en":"If offenders change their thinking, they may stop seeing violence or theft as the only option.","zh":"如果罪犯改變思維方式，他們可能不再把暴力或盜竊視為唯一選項。"},{"en":"The phrase focuses on mental change before behaviour change.","zh":"這個短語強調在行為改變之前的心理改變。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":9},{"front":"stop and consider consequences","meaning":"停下來考慮後果","examples":[{"en":"The programmes teach offenders to stop and consider consequences.","zh":"這些計劃教罪犯停下來考慮後果。"},{"en":"To stop and consider consequences means to pause before acting and think about what may happen next.","zh":"“Stop and consider consequences” 指行動前先停下來思考接下來可能發生甚麼。"},{"en":"A student should stop and consider consequences before posting an angry message online.","zh":"學生在網上發布憤怒訊息前，應停下來考慮後果。"},{"en":"If offenders pause before acting, they may avoid decisions that lead back to court.","zh":"如果罪犯在行動前停一停，就可能避免導致重返法庭的決定。"},{"en":"The phrase teaches careful thinking before action.","zh":"這個短語教人在行動前謹慎思考。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":10},{"front":"anticipate high-risk situations","meaning":"預料高風險情況","examples":[{"en":"Offenders learn to anticipate high-risk situations.","zh":"罪犯學會預料高風險情況。"},{"en":"To anticipate high-risk situations means to predict dangerous or tempting situations before they happen.","zh":"“Anticipate high-risk situations” 指在危險或誘人的情況發生前預測它們。"},{"en":"A student with exam anxiety may anticipate high-risk moments and prepare calming strategies.","zh":"有考試焦慮的學生可能預料高風險時刻，並準備冷靜策略。"},{"en":"If offenders anticipate risky situations, they can plan how to avoid or handle them.","zh":"如果罪犯預料風險情況，就可以計劃如何避開或處理它們。"},{"en":"The phrase focuses on prevention through advance awareness.","zh":"這個短語強調透過預先意識來預防。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":10},{"front":"high-risk situations","meaning":"高風險情況","examples":[{"en":"Offenders identify high-risk situations before they occur.","zh":"罪犯在高風險情況發生前識別它們。"},{"en":"High-risk situations are situations where harmful behaviour is more likely to happen.","zh":"高風險情況是有害行為較可能發生的情況。"},{"en":"For a student who overspends, walking through a shopping mall after payday may be a high-risk situation.","zh":"對容易過度消費的學生來說，出糧後經過商場可能是高風險情況。"},{"en":"If offenders know their high-risk situations, they can make safer plans before trouble begins.","zh":"如果罪犯知道自己的高風險情況，就可以在麻煩開始前制定較安全計劃。"},{"en":"The phrase describes danger points that need preparation.","zh":"這個短語描述需要準備的危險點。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":10},{"front":"avoid or cope with","meaning":"避免或應對","examples":[{"en":"Offenders learn to avoid or cope with high-risk situations.","zh":"罪犯學會避免或應對高風險情況。"},{"en":"To avoid or cope with something means either to stay away from it or manage it safely when it happens.","zh":"“Avoid or cope with” 某事指避開它，或在它發生時安全處理它。"},{"en":"A student may avoid stress by planning early or cope with it by using breathing exercises.","zh":"學生可以透過早作規劃避免壓力，或用呼吸練習應對壓力。"},{"en":"If an offender cannot avoid a risky place, they need skills to cope with it without re-offending.","zh":"如果罪犯不能避開高風險地方，就需要技巧去應對而不重犯。"},{"en":"The phrase gives two practical responses to a problem.","zh":"這個短語給出處理問題的兩種實際回應。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":10},{"front":"so far","meaning":"到目前為止","examples":[{"en":"So far, these programmes seem to be reasonably successful.","zh":"到目前為止，這些計劃看來頗為成功。"},{"en":"So far means up to the present point in time.","zh":"“So far” 指直到目前這個時間點。"},{"en":"So far, the new reading plan has helped most students finish books more confidently.","zh":"到目前為止，新閱讀計劃幫助大多數學生更有信心地讀完書。"},{"en":"If results look good so far, researchers may continue testing before reaching a final conclusion.","zh":"如果到目前為止結果不錯，研究人員可能繼續測試再作最終結論。"},{"en":"The phrase suggests present evidence, not final proof.","zh":"這個短語暗示目前證據，而不是最終證明。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":10},{"front":"reasonably successful","meaning":"頗為成功","examples":[{"en":"The programmes seem to be reasonably successful.","zh":"這些計劃看來頗為成功。"},{"en":"Reasonably successful means fairly successful, though not perfect or guaranteed.","zh":"“Reasonably successful” 指相當成功，但並非完美或保證有效。"},{"en":"A new class routine is reasonably successful if most students follow it most of the time.","zh":"如果大多數學生大部分時間都跟隨新課堂常規，它就頗為成功。"},{"en":"If a rehabilitation programme is reasonably successful, it may help many offenders but still need improvement.","zh":"如果更生計劃頗為成功，它可能幫助許多罪犯，但仍需要改善。"},{"en":"The phrase expresses cautious positive judgement.","zh":"這個短語表達謹慎的正面判斷。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":10},{"front":"from a therapeutic jurisprudence standpoint","meaning":"從治療法理學角度來看","examples":[{"en":"From a therapeutic jurisprudence standpoint, these programmes should be linked to the law.","zh":"從治療法理學角度來看，這些計劃應與法律聯繫起來。"},{"en":"From a therapeutic jurisprudence standpoint means seen from the perspective of law’s therapeutic and psychological effects.","zh":"“From a therapeutic jurisprudence standpoint” 指從法律的治療性和心理影響角度來看。"},{"en":"From a student-welfare standpoint, a school rule should reduce fear as well as maintain order.","zh":"從學生福祉角度來看，校規應在維持秩序之餘減少恐懼。"},{"en":"If programmes improve offenders’ thinking, this standpoint asks how courts can connect them to legal decisions.","zh":"如果計劃改善罪犯思維，這個角度會問法院如何把它們與法律決定連接。"},{"en":"The phrase introduces a particular analytical viewpoint.","zh":"這個短語引出特定分析觀點。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":10},{"front":"in one obvious sense","meaning":"從一個明顯角度來說","examples":[{"en":"In one obvious sense, the programmes can be offered in correctional settings.","zh":"從一個明顯角度來說，這些計劃可以在懲教環境中提供。"},{"en":"In one obvious sense means in one clear and easy-to-see way.","zh":"“In one obvious sense” 指從一種清楚而容易看見的方式來說。"},{"en":"In one obvious sense, online lessons save travel time because students stay at home.","zh":"從一個明顯角度來說，網上課堂節省交通時間，因為學生留在家中。"},{"en":"If offenders are already in correctional facilities, offering programmes there is an obvious link to law.","zh":"如果罪犯已在懲教設施中，在那裡提供計劃就是與法律的明顯連繫。"},{"en":"The phrase introduces a simple, clear point before deeper discussion.","zh":"這個短語在深入討論前引出簡單清楚的一點。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":10},{"front":"problem-solving programmes","meaning":"解難計劃","examples":[{"en":"Problem-solving programmes can be made available to offenders.","zh":"解難計劃可以提供給罪犯。"},{"en":"Problem-solving programmes are structured activities that teach people how to identify problems and choose better responses.","zh":"解難計劃是教授人識別問題並選擇較好回應的結構化活動。"},{"en":"A school may use problem-solving programmes to help students handle conflict without fighting.","zh":"學校可能使用解難計劃，幫助學生不用打架也能處理衝突。"},{"en":"If offenders learn problem-solving skills, they may respond to pressure without committing crimes.","zh":"如果罪犯學會解難技巧，可能在面對壓力時不用犯罪也能回應。"},{"en":"The phrase focuses on practical thinking skills.","zh":"這個短語強調實用思考技巧。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":10},{"front":"rehabilitation-type programmes","meaning":"更生類計劃","examples":[{"en":"Rehabilitation-type programmes may become part of the legal process.","zh":"更生類計劃可能成為法律程序的一部分。"},{"en":"Rehabilitation-type programmes are programmes designed to help people change behaviour and return to society more safely.","zh":"更生類計劃是旨在幫助人改變行為並更安全重返社會的計劃。"},{"en":"A community centre may run rehabilitation-type programmes for former offenders looking for work.","zh":"社區中心可能為尋找工作的前罪犯舉辦更生類計劃。"},{"en":"If these programmes become part of court orders, rehabilitation is connected directly to law.","zh":"如果這些計劃成為法院命令的一部分，更生就直接與法律連繫起來。"},{"en":"The phrase describes programmes focused on improvement rather than punishment only.","zh":"這個短語描述以改善為重點，而不只是懲罰的計劃。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":10},{"front":"be made widely available","meaning":"被廣泛提供","examples":[{"en":"These programmes can be made widely available.","zh":"這些計劃可以被廣泛提供。"},{"en":"To be made widely available means to be offered to many people in many places.","zh":"“Be made widely available” 指在許多地方提供給許多人。"},{"en":"Online learning materials can be made widely available to students who cannot afford private tutoring.","zh":"網上學習材料可以被廣泛提供給負擔不起私人補習的學生。"},{"en":"If rehabilitation programmes are widely available, more offenders can receive help before re-offending.","zh":"如果更生計劃被廣泛提供，更多罪犯可以在重犯前得到幫助。"},{"en":"The phrase stresses broad access.","zh":"這個短語強調廣泛可及性。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":10},{"front":"correctional settings","meaning":"懲教環境","examples":[{"en":"Programmes may be offered in correctional settings.","zh":"計劃可能在懲教環境中提供。"},{"en":"Correctional settings are places connected with punishment, supervision, and rehabilitation, such as prisons or detention centres.","zh":"懲教環境是與懲罰、監管和更生有關的地方，例如監獄或羈留中心。"},{"en":"A prison classroom is a correctional setting where offenders may study or receive treatment.","zh":"監獄課室是一種懲教環境，罪犯可能在那裡學習或接受治療。"},{"en":"If programmes are offered in correctional settings, they reach people already inside the justice system.","zh":"如果計劃在懲教環境中提供，就能接觸已在司法制度中的人。"},{"en":"The phrase refers to institutional environments for offenders.","zh":"這個短語指針對罪犯的制度性環境。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":11},{"front":"community settings","meaning":"社區環境","examples":[{"en":"Rehabilitation programmes may also be offered in community settings.","zh":"更生計劃也可以在社區環境中提供。"},{"en":"Community settings are local non-prison environments such as clinics, schools, centres, or neighbourhood programmes.","zh":"社區環境是本地非監獄環境，例如診所、學校、中心或社區計劃。"},{"en":"A counselling group held in a community centre takes place in a community setting.","zh":"在社區中心舉行的輔導小組，就是在社區環境中進行。"},{"en":"If rehabilitation happens in community settings, offenders can practise change in real daily life.","zh":"如果更生在社區環境中進行，罪犯可以在真實日常生活中練習改變。"},{"en":"The phrase contrasts local public environments with correctional institutions.","zh":"這個短語把本地公共環境與懲教機構作對比。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":11},{"front":"a way of linking","meaning":"將……聯繫起來的方法","examples":[{"en":"One method is a way of linking rehabilitation programmes to the law.","zh":"其中一種方法是將更生計劃與法律聯繫起來的方法。"},{"en":"A way of linking two things is a method for connecting them so they work together.","zh":"將兩件事聯繫起來的方法，是把它們連接起來使其共同運作的方式。"},{"en":"A school app can be a way of linking parents to teachers more directly.","zh":"學校應用程式可以是更直接地將家長與老師聯繫起來的方法。"},{"en":"If courts link rehabilitation to sentencing, treatment becomes part of the legal response.","zh":"如果法院把更生與判刑聯繫起來，治療就成為法律回應的一部分。"},{"en":"The phrase describes a method of connection.","zh":"這個短語描述連接的方法。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":11},{"front":"even more to","meaning":"更加與……","examples":[{"en":"The programmes can be linked even more to the law.","zh":"這些計劃可以更加與法律聯繫起來。"},{"en":"Even more to means to a greater degree than before or than another option.","zh":"“Even more to” 指比以前或比另一選項程度更高。"},{"en":"A school project can be connected even more to daily life by using real community problems.","zh":"學校項目可以透過使用真實社區問題，更加與日常生活連繫起來。"},{"en":"If rehabilitation is made part of sentencing, it is linked even more closely to law.","zh":"如果更生成為判刑的一部分，它就更加緊密地與法律連繫。"},{"en":"The phrase strengthens the degree of connection.","zh":"這個短語加強連接程度。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":11},{"front":"make something part of","meaning":"使某事成為……的一部分","examples":[{"en":"The programmes can be made part of the legal process itself.","zh":"這些計劃可以被使成為法律程序本身的一部分。"},{"en":"To make something part of a process means to include it as a regular element of that process.","zh":"“Make something part of” 某過程指把它納入為該過程的常規元素。"},{"en":"A teacher may make peer feedback part of the writing process.","zh":"老師可能使同儕回饋成為寫作過程的一部分。"},{"en":"If rehabilitation is made part of sentencing, offenders must discuss change before leaving court.","zh":"如果更生成為判刑的一部分，罪犯離開法院前必須討論改變。"},{"en":"The phrase describes formal inclusion.","zh":"這個短語描述正式納入。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":11},{"front":"the legal process itself","meaning":"法律程序本身","examples":[{"en":"Rehabilitation can become part of the legal process itself.","zh":"更生可以成為法律程序本身的一部分。"},{"en":"The legal process itself means the actual formal steps of law, not something outside or after it.","zh":"法律程序本身指法律的實際正式步驟，而不是其外部或之後的事情。"},{"en":"If mediation is built into the legal process itself, parties meet before a full trial.","zh":"如果調解被納入法律程序本身，各方會在正式審訊前會面。"},{"en":"If treatment planning happens during sentencing, rehabilitation is no longer separate from law.","zh":"如果治療規劃在判刑期間發生，更生就不再與法律分開。"},{"en":"The phrase stresses direct integration into legal procedure.","zh":"這個短語強調直接融入法律程序。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":11},{"front":"parole board","meaning":"假釋委員會","examples":[{"en":"A parole board may consider whether an offender should be released.","zh":"假釋委員會可能考慮罪犯是否應獲釋。"},{"en":"A parole board is a group that decides whether prisoners can leave prison early under supervision.","zh":"假釋委員會是一個決定囚犯是否可以在監管下提早離開監獄的組織。"},{"en":"A parole board may look at behaviour, risk, and rehabilitation progress before making a decision.","zh":"假釋委員會在作決定前，可能查看行為、風險和更生進展。"},{"en":"If an offender has a strong prevention plan, the parole board may view release as safer.","zh":"如果罪犯有強大的預防計劃，假釋委員會可能認為釋放較安全。"},{"en":"The phrase refers to a decision-making body in the correctional system.","zh":"這個短語指懲教制度中的決策機構。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":11},{"front":"become familiar with","meaning":"熟悉","examples":[{"en":"A judge may become familiar with cognitive behavioural techniques.","zh":"法官可能熟悉認知行為技巧。"},{"en":"To become familiar with something means to learn enough about it to understand or use it comfortably.","zh":"“Become familiar with” 某事指學到足以舒適理解或使用它。"},{"en":"A new teacher may become familiar with school rules after a few weeks.","zh":"新老師幾週後可能熟悉學校規則。"},{"en":"If judges become familiar with rehabilitation methods, they can discuss them more meaningfully in court.","zh":"如果法官熟悉更生方法，就能在法庭上更有意義地討論它們。"},{"en":"The phrase describes growing understanding through exposure or practice.","zh":"這個短語描述透過接觸或練習逐漸理解。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":11},{"front":"be about to","meaning":"即將","examples":[{"en":"A judge may be about to consider someone for probation.","zh":"法官可能即將考慮讓某人接受感化安排。"},{"en":"To be about to do something means to be going to do it very soon.","zh":"“Be about to” 做某事指很快就要做該事。"},{"en":"A student is about to leave home when the teacher calls with important news.","zh":"學生即將離家時，老師打來電話告知重要消息。"},{"en":"If a judge is about to decide probation, the offender’s plan becomes immediately relevant.","zh":"如果法官即將決定感化安排，罪犯的計劃就立即變得相關。"},{"en":"The phrase points to an action that is close to happening.","zh":"這個短語指即將發生的行動。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":11},{"front":"consider someone for probation","meaning":"考慮讓某人接受感化安排","examples":[{"en":"The judge is about to consider the offender for probation.","zh":"法官即將考慮讓該罪犯接受感化安排。"},{"en":"To consider someone for probation means to decide whether that person should serve a sentence under supervision in the community instead of prison.","zh":"“Consider someone for probation” 指決定某人是否應在社區中受監管服刑，而不是入獄。"},{"en":"A court may consider a young offender for probation if they show willingness to change.","zh":"如果年輕罪犯顯示願意改變，法院可能考慮讓他接受感化安排。"},{"en":"If probation is considered, the judge needs to know whether the person can follow rules safely.","zh":"如果考慮感化安排，法官需要知道該人是否能安全遵守規則。"},{"en":"The phrase refers to weighing probation as a sentencing option.","zh":"這個短語指把感化令作為判刑選項來權衡。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":11},{"front":"probation","meaning":"感化令；感化安排","examples":[{"en":"The offender may be considered for probation.","zh":"該罪犯可能被考慮接受感化安排。"},{"en":"Probation is a court order that lets an offender live in the community under supervision and conditions.","zh":"感化令是法院命令，讓罪犯在監管和條件下留在社區生活。"},{"en":"A person on probation may need to meet an officer, attend treatment, and avoid certain places.","zh":"接受感化安排的人可能需要會見感化主任、接受治療並避開某些地方。"},{"en":"If probation is successful, the offender can remain in society while working on change.","zh":"如果感化安排成功，罪犯可以留在社會中並努力改變。"},{"en":"The phrase refers to supervised community-based punishment and rehabilitation.","zh":"這個短語指受監管的社區式懲罰和更生。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":11},{"front":"come up with","meaning":"想出；提出","examples":[{"en":"The offender is asked to come up with a preliminary plan.","zh":"罪犯被要求想出一個初步計劃。"},{"en":"To come up with something means to think of, create, or propose an idea or solution.","zh":"“Come up with” 某事指想出、創造或提出一個想法或解決方案。"},{"en":"A student may come up with a better essay title after discussing the topic with classmates.","zh":"學生與同學討論題目後，可能想出更好的作文標題。"},{"en":"If offenders come up with their own plans, they may feel more responsible for following them.","zh":"如果罪犯提出自己的計劃，他們可能更有責任感去遵守它。"},{"en":"The phrase focuses on generating an idea.","zh":"這個短語強調產生想法。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":12},{"front":"a preliminary relapse prevention plan","meaning":"初步預防重犯計劃","examples":[{"en":"The offender prepares a preliminary relapse prevention plan.","zh":"罪犯制定初步預防重犯計劃。"},{"en":"A preliminary relapse prevention plan is an early draft of a plan to prevent a return to harmful or criminal behaviour.","zh":"初步預防重犯計劃是防止回到有害或犯罪行為的早期計劃草稿。"},{"en":"A counsellor may ask a client to prepare a preliminary plan before a full treatment session.","zh":"輔導員可能要求來訪者在完整治療節前準備初步計劃。"},{"en":"If the first plan is incomplete, discussion can improve it before it becomes final.","zh":"如果第一份計劃不完整，討論可以在它成為最終版本前改善它。"},{"en":"The phrase describes an initial plan for preventing future failure.","zh":"這個短語描述防止日後失敗的初始計劃。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":12},{"front":"use as a basis for discussion","meaning":"用作討論基礎","examples":[{"en":"The plan will be used as a basis for discussion.","zh":"該計劃將被用作討論基礎。"},{"en":"To use something as a basis for discussion means to use it as the starting point for talking and making decisions.","zh":"“Use something as a basis for discussion” 指把某事用作談話和作決定的起點。"},{"en":"A teacher may use a student’s draft as a basis for discussion about essay structure.","zh":"老師可能把學生草稿用作討論作文結構的基礎。"},{"en":"If an offender’s plan is discussed in court, the judge can test whether it is realistic.","zh":"如果罪犯的計劃在法庭上討論，法官可以測試它是否現實。"},{"en":"The phrase describes using a document or idea to begin meaningful conversation.","zh":"這個短語描述使用文件或想法來開始有意義的對話。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":12},{"front":"figure out why","meaning":"想清楚為甚麼","examples":[{"en":"The offender must figure out why probation should be granted.","zh":"罪犯必須想清楚為甚麼應獲准接受感化安排。"},{"en":"To figure out why means to understand or work out the reason for something.","zh":"“Figure out why” 指理解或推斷某事的原因。"},{"en":"A student may need to figure out why they keep losing marks in writing.","zh":"學生可能需要想清楚為甚麼自己寫作一直失分。"},{"en":"If offenders figure out why probation is appropriate, they must think seriously about their own responsibility.","zh":"如果罪犯想清楚為甚麼感化安排合適，他們就必須認真思考自己的責任。"},{"en":"The phrase describes active reasoning, not being told the answer.","zh":"這個短語描述主動推理，而不是被告知答案。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":12},{"front":"grant someone probation","meaning":"批准某人接受感化安排","examples":[{"en":"The judge may decide whether to grant the offender probation.","zh":"法官可能決定是否批准該罪犯接受感化安排。"},{"en":"To grant someone probation means to officially allow them to serve a supervised sentence in the community.","zh":"“Grant someone probation” 指正式允許某人在社區中接受監管式刑罰。"},{"en":"A judge may grant a first-time offender probation if the risk seems manageable.","zh":"如果風險看似可管理，法官可能批准初犯者接受感化安排。"},{"en":"If probation is granted, the offender must follow court conditions instead of simply going free.","zh":"如果感化安排獲批准，罪犯必須遵守法院條件，而不是單純自由離開。"},{"en":"The phrase describes a formal court decision.","zh":"這個短語描述正式法院決定。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":12},{"front":"feel comfortable that","meaning":"安心相信","examples":[{"en":"The judge needs to feel comfortable that the offender will succeed.","zh":"法官需要安心相信罪犯會成功。"},{"en":"To feel comfortable that something is true means to feel confident and reassured about it.","zh":"“Feel comfortable that” 某事為真指對它感到有信心和放心。"},{"en":"A parent may feel comfortable that a school trip is safe after seeing the detailed plan.","zh":"家長看過詳細計劃後，可能安心相信學校旅行是安全的。"},{"en":"If a judge feels comfortable that an offender has a realistic plan, probation may seem safer.","zh":"如果法官安心相信罪犯有現實計劃，感化安排可能看起來較安全。"},{"en":"The phrase describes confidence before making a decision.","zh":"這個短語描述作決定前的信心。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":12},{"front":"regard as","meaning":"視為","examples":[{"en":"The offender explains what they regard as high-risk situations.","zh":"罪犯解釋他們視為高風險情況的事情。"},{"en":"To regard something as something means to see or consider it in that way.","zh":"“Regard as” 某事指把它看作或認為是某種事物。"},{"en":"A student may regard public speaking as frightening until they practise regularly.","zh":"學生可能把公開演說視為可怕，直到他們定期練習。"},{"en":"If offenders regard Friday nights as risky, they can plan safer activities then.","zh":"如果罪犯把星期五晚上視為高風險，他們可以在那時安排較安全活動。"},{"en":"The phrase shows personal judgement or classification.","zh":"這個短語顯示個人判斷或分類。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":12},{"front":"if that approach is followed","meaning":"如果採用這種做法","examples":[{"en":"If that approach is followed, courts will promote cognitive self-change.","zh":"如果採用這種做法，法庭將會推動認知上的自我改變。"},{"en":"If that approach is followed means if people use that method or act according to that plan.","zh":"“If that approach is followed” 指如果人們使用該方法或按該計劃行事。"},{"en":"If the teacher’s revision approach is followed, students will practise a little every day.","zh":"如果採用老師的溫習方法，學生會每天練習一點。"},{"en":"If courts follow a planning-based approach, offenders may become more involved in their own rehabilitation.","zh":"如果法院採用以規劃為本的方法，罪犯可能更參與自己的更生。"},{"en":"The phrase introduces the result of using a method.","zh":"這個短語引出使用某方法的結果。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":12},{"front":"courts will be promoting","meaning":"法庭將會推動","examples":[{"en":"Courts will be promoting cognitive self-change through sentencing.","zh":"法庭將會透過判刑推動認知上的自我改變。"},{"en":"Courts will be promoting something means courts will be actively encouraging or supporting it.","zh":"“Courts will be promoting” 某事指法院會積極鼓勵或支持它。"},{"en":"Schools promote reading when they give time for quiet reading every day.","zh":"學校每天給予安靜閱讀時間，就是推動閱讀。"},{"en":"If courts ask offenders to plan change, they promote responsibility rather than passive punishment.","zh":"如果法院要求罪犯規劃改變，就是推動責任感，而不是被動懲罰。"},{"en":"The phrase shows that legal institutions can encourage behaviour.","zh":"這個短語顯示法律機構可以鼓勵行為。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":12},{"front":"cognitive self-change","meaning":"認知上的自我改變","examples":[{"en":"Cognitive self-change can become part of the sentencing process.","zh":"認知上的自我改變可以成為判刑程序的一部分。"},{"en":"Cognitive self-change means changing one’s own thinking patterns, decisions, and reactions.","zh":"認知上的自我改變指改變自己的思維模式、決定和反應。"},{"en":"A student practises cognitive self-change when they replace “I always fail” with “I need a better method.”","zh":"當學生把「我總是失敗」改成「我需要更好的方法」時，就是在練習認知上的自我改變。"},{"en":"If offenders change how they think before risky situations, their behaviour may also change.","zh":"如果罪犯在高風險情況前改變思考方式，其行為也可能改變。"},{"en":"The phrase focuses on self-directed mental change.","zh":"這個短語強調由自己主導的心理改變。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":12},{"front":"part and parcel of","meaning":"……不可或缺的一部分","examples":[{"en":"Cognitive self-change becomes part and parcel of the sentencing process.","zh":"認知上的自我改變成為判刑程序不可或缺的一部分。"},{"en":"Part and parcel of something means an essential and inseparable part of it.","zh":"“Part and parcel of” 某事指它是該事必要且不可分割的一部分。"},{"en":"Feedback is part and parcel of learning a language because students need to know what to improve.","zh":"回饋是語言學習不可或缺的一部分，因為學生需要知道應改善甚麼。"},{"en":"If rehabilitation planning is part and parcel of sentencing, it is not treated as an optional extra.","zh":"如果更生規劃是判刑不可或缺的一部分，它就不被視為可選附加項。"},{"en":"The phrase stresses that something belongs naturally inside a process.","zh":"這個短語強調某事自然屬於一個過程之內。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":12},{"front":"the sentencing process","meaning":"判刑程序","examples":[{"en":"The approach becomes part of the sentencing process itself.","zh":"這種做法成為判刑程序本身的一部分。"},{"en":"The sentencing process is the stage in which a court decides the punishment or legal order after guilt is established.","zh":"判刑程序是在罪名成立後，法院決定懲罰或法律命令的階段。"},{"en":"During the sentencing process, a judge may consider risk, harm, responsibility, and rehabilitation.","zh":"在判刑程序中，法官可能考慮風險、傷害、責任和更生。"},{"en":"If rehabilitation planning enters the sentencing process, offenders may have to think about future behaviour immediately.","zh":"如果更生規劃進入判刑程序，罪犯可能必須立即思考未來行為。"},{"en":"The phrase refers to how punishment or orders are decided.","zh":"這個短語指懲罰或命令如何被決定。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":13},{"front":"may operate this way","meaning":"可能以這種方式運作","examples":[{"en":"The process may operate this way in court.","zh":"該程序可能在法庭中以這種方式運作。"},{"en":"May operate this way means may work or function in this manner.","zh":"“May operate this way” 指可能以這種方法工作或發揮功能。"},{"en":"A school complaints system may operate this way: students report problems, teachers investigate, and parents receive updates.","zh":"學校投訴制度可能以這種方式運作：學生報告問題，老師調查，家長收到更新。"},{"en":"If sentencing operates this way, the offender helps create a prevention plan before the judge decides.","zh":"如果判刑以這種方式運作，罪犯會在法官決定前協助制定預防計劃。"},{"en":"The phrase explains how a process might work in practice.","zh":"這個短語解釋程序在實際上可能如何運作。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":13},{"front":"make a statement like","meaning":"作出類似的陳述","examples":[{"en":"An offender may make a statement like this during the discussion.","zh":"罪犯可能在討論期間作出類似的陳述。"},{"en":"To make a statement like something means to say something similar in content or style.","zh":"“Make a statement like” 某話指說出內容或風格相似的話。"},{"en":"A student may make a statement like “I need help before tests” during a counselling session.","zh":"學生可能在輔導節中作出「我在測驗前需要幫助」這類陳述。"},{"en":"If an offender makes a statement about risky habits, the court can discuss practical controls.","zh":"如果罪犯就高風險習慣作出陳述，法院可以討論實際控制方法。"},{"en":"The phrase introduces an example of what someone might say.","zh":"這個短語引出某人可能會說的例子。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":13},{"front":"mess up","meaning":"搞砸；出事","examples":[{"en":"The offender realises that they often mess up on Friday nights.","zh":"罪犯意識到自己經常在星期五晚上出事。"},{"en":"To mess up means to make a mistake, fail, or get into trouble.","zh":"“Mess up” 指犯錯、失敗或惹上麻煩。"},{"en":"A student may mess up an exam if they panic and skip easy questions.","zh":"如果學生驚慌並跳過容易題目，可能把考試搞砸。"},{"en":"If an offender knows when they usually mess up, they can plan to avoid that situation.","zh":"如果罪犯知道自己通常何時出事，就可以計劃避開該情況。"},{"en":"The phrase is informal and often means things go wrong because of poor choices.","zh":"這個短語較口語，通常指因錯誤選擇而出問題。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":13},{"front":"propose that","meaning":"建議；提出","examples":[{"en":"The offender may propose that they stay at home on Friday nights.","zh":"罪犯可能建議自己星期五晚上留在家中。"},{"en":"To propose that something happen means to suggest it as a plan or solution.","zh":"“Propose that” 某事發生指把它建議為計劃或解決方案。"},{"en":"A student may propose that the group meet earlier to finish the project on time.","zh":"學生可能建議小組提早見面，以準時完成項目。"},{"en":"If offenders propose their own safety plans, they may feel more responsible for them.","zh":"如果罪犯提出自己的安全計劃，他們可能對計劃更有責任感。"},{"en":"The phrase introduces a suggested action.","zh":"這個短語引出被建議的行動。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":13},{"front":"impose something on","meaning":"將某事強加於……","examples":[{"en":"The judge is not simply imposing something on the offender.","zh":"法官並不是單純將某事強加於罪犯。"},{"en":"To impose something on someone means to force them to accept it without much choice.","zh":"“Impose something on” 某人指在沒有太多選擇下迫使他接受某事。"},{"en":"A school should not impose a new rule on students without explaining why it is needed.","zh":"學校不應在不解釋原因下，把新規則強加於學生。"},{"en":"If a judge only imposes conditions, the offender may feel passive and less committed.","zh":"如果法官只強加條件，罪犯可能感到被動並較少承擔。"},{"en":"The phrase contrasts forced orders with shared planning.","zh":"這個短語把強制命令與共同規劃作對比。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":13},{"front":"something the offender has developed","meaning":"罪犯自己制定的東西","examples":[{"en":"The plan is something the offender has developed.","zh":"該計劃是罪犯自己制定的東西。"},{"en":"Something the offender has developed means an idea or plan created by the offender rather than simply given by the court.","zh":"“Something the offender has developed” 指由罪犯創造的想法或計劃，而不是單純由法院給予。"},{"en":"A student is more likely to follow a study timetable they have developed themselves.","zh":"學生更有可能跟隨自己制定的溫習時間表。"},{"en":"If offenders develop their own plans, they may see them as fairer and more realistic.","zh":"如果罪犯制定自己的計劃，可能視它們為更公平和更現實。"},{"en":"The phrase stresses personal involvement in planning.","zh":"這個短語強調個人在規劃中的參與。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":13},{"front":"consider it fair","meaning":"認為它公平","examples":[{"en":"The offender should consider the plan fair.","zh":"罪犯應認為該計劃公平。"},{"en":"To consider it fair means to believe that it is reasonable, balanced, and not unjust.","zh":"“Consider it fair” 指相信它合理、平衡且不不公。"},{"en":"Students are more willing to accept a rule when they consider it fair.","zh":"當學生認為規則公平時，會更願意接受它。"},{"en":"If offenders consider a plan fair, they may be more willing to follow it.","zh":"如果罪犯認為計劃公平，可能更願意遵守它。"},{"en":"The phrase describes a personal judgement about fairness.","zh":"這個短語描述對公平性的個人判斷。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":13},{"front":"have a voice in","meaning":"對……有發言權","examples":[{"en":"A person is more committed if they have a voice in their rehabilitation.","zh":"如果一個人對自己的更生有發言權，就會更有承擔。"},{"en":"To have a voice in something means to have a chance to express views and influence decisions.","zh":"“Have a voice in” 某事指有機會表達看法並影響決定。"},{"en":"Students feel more responsible for class rules when they have a voice in making them.","zh":"當學生對制定班規有發言權時，會對班規更有責任感。"},{"en":"If offenders have a voice in rehabilitation, they may see the plan as their own.","zh":"如果罪犯對更生有發言權，他們可能把計劃視為自己的。"},{"en":"The phrase stresses participation rather than passive obedience.","zh":"這個短語強調參與，而不是被動服從。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":13},{"front":"rehabilitation","meaning":"更生；改造","examples":[{"en":"Offenders are more likely to feel committed to their rehabilitation.","zh":"罪犯更有可能對自己的更生感到有承擔。"},{"en":"Rehabilitation is the process of helping someone recover, change harmful behaviour, and return to society more safely.","zh":"更生是幫助某人復原、改變有害行為並更安全重返社會的過程。"},{"en":"After an injury, rehabilitation may include exercises that help a patient walk again.","zh":"受傷後，更生可能包括幫助病人重新走路的練習。"},{"en":"In criminal justice, rehabilitation tries to reduce future offending by changing behaviour and thinking.","zh":"在刑事司法中，更生嘗試透過改變行為和思維來減少日後犯罪。"},{"en":"The word focuses on recovery and positive change.","zh":"這個詞強調復原和正面改變。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":13},{"front":"be more likely to","meaning":"更有可能","examples":[{"en":"Offenders are more likely to comply when they feel involved.","zh":"當罪犯感到參與其中時，他們更有可能遵守。"},{"en":"Be more likely to do something means have a higher chance of doing it.","zh":"“Be more likely to” 做某事指做該事的機會較高。"},{"en":"Students are more likely to finish homework when they understand why it matters.","zh":"當學生明白功課為何重要時，更有可能完成它。"},{"en":"If people help design a plan, they are more likely to follow it.","zh":"如果人們協助設計計劃，他們更有可能遵從它。"},{"en":"The phrase describes increased probability.","zh":"這個短語描述可能性增加。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":13},{"front":"feel a commitment to","meaning":"對……感到有承擔","examples":[{"en":"A person may feel a commitment to a plan they helped create.","zh":"一個人可能對自己協助創造的計劃感到有承擔。"},{"en":"To feel a commitment to something means to feel personally responsible and dedicated to it.","zh":"“Feel a commitment to” 某事指對它感到有個人責任和投入。"},{"en":"A student may feel a commitment to a group project if they helped choose the topic.","zh":"如果學生協助選題，可能對小組項目感到有承擔。"},{"en":"If offenders feel committed to their own plans, compliance may improve.","zh":"如果罪犯對自己的計劃感到有承擔，遵從度可能改善。"},{"en":"The phrase connects involvement with responsibility.","zh":"這個短語把參與與責任連繫起來。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":14},{"front":"with that commitment","meaning":"有了那份承擔","examples":[{"en":"With that commitment, compliance will increase dramatically.","zh":"有了那份承擔，遵從度會大幅增加。"},{"en":"With that commitment means because that sense of responsibility or dedication is present.","zh":"“With that commitment” 指因為那份責任感或投入存在。"},{"en":"With a student’s commitment, a difficult revision plan becomes easier to maintain.","zh":"有了學生的承擔，困難的溫習計劃會較容易維持。"},{"en":"If offenders feel ownership of a plan, that commitment can support long-term change.","zh":"如果罪犯對計劃有主人翁感，那份承擔可以支援長期改變。"},{"en":"The phrase links commitment with better follow-through.","zh":"這個短語把承擔與更好執行連繫起來。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":14},{"front":"presumably","meaning":"大概；相信","examples":[{"en":"With that commitment, presumably, compliance will increase dramatically.","zh":"有了那份承擔，相信遵從度會大幅增加。"},{"en":"Presumably means probably, based on what seems reasonable.","zh":"“Presumably” 指根據合理情況推測，大概如此。"},{"en":"If a student attends every lesson and practises daily, presumably they will improve.","zh":"如果學生每堂都出席並每天練習，相信會進步。"},{"en":"If offenders help make a plan, presumably they will feel more willing to follow it.","zh":"如果罪犯協助制定計劃，相信他們會更願意遵守它。"},{"en":"The word shows a reasonable assumption, not absolute proof.","zh":"這個詞顯示合理假設，而不是絕對證明。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":14},{"front":"compliance","meaning":"遵從；遵守","examples":[{"en":"Compliance may increase when offenders help design their own plans.","zh":"當罪犯協助設計自己的計劃時，遵從度可能增加。"},{"en":"Compliance means obeying rules, orders, agreements, or conditions.","zh":"遵從指遵守規則、命令、協議或條件。"},{"en":"A school improves compliance when students understand the reason behind a rule.","zh":"當學生明白規則背後的原因，學校就能改善遵從度。"},{"en":"If probation conditions feel fair and realistic, compliance may be higher.","zh":"如果感化條件感覺公平而現實，遵從度可能較高。"},{"en":"The word focuses on actual following of requirements.","zh":"這個詞強調實際遵守要求。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":14},{"front":"increase dramatically","meaning":"大幅增加","examples":[{"en":"Compliance may increase dramatically.","zh":"遵從度可能大幅增加。"},{"en":"To increase dramatically means to rise by a large and noticeable amount.","zh":"“Increase dramatically” 指以很大且明顯的幅度上升。"},{"en":"A student’s confidence may increase dramatically after several successful speaking practices.","zh":"學生在幾次成功口語練習後，信心可能大幅增加。"},{"en":"If people feel ownership of a plan, their willingness to follow it may rise strongly.","zh":"如果人們對計劃有主人翁感，跟隨它的意願可能強烈上升。"},{"en":"The phrase describes a major improvement, not a small change.","zh":"這個短語描述重大改善，而不是小改變。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":14},{"front":"complete the notes below","meaning":"完成以下筆記","examples":[{"en":"Students complete the notes below using words from the passage.","zh":"學生使用文章中的詞語完成以下筆記。"},{"en":"Complete the notes below means fill in missing information in the notes under the question.","zh":"“Complete the notes below” 指填寫題目下方筆記中的缺漏資料。"},{"en":"In a reading test, students should check the word limit before completing the notes below.","zh":"在閱讀測驗中，學生完成以下筆記前應檢查字數限制。"},{"en":"If the notes summarise a paragraph, students should find the matching part of the passage first.","zh":"如果筆記概括某段，學生應先找出文章中相應部分。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":14},{"front":"choose no more than one word","meaning":"選擇不超過一個字","examples":[{"en":"Students choose no more than one word for each answer.","zh":"學生為每個答案選擇不超過一個字。"},{"en":"Choose no more than one word means the answer must be exactly one word or left within a one-word limit.","zh":"“Choose no more than one word” 指答案必須是一個字或不超過一字限制。"},{"en":"If the correct answer is “justice,” writing “legal justice” would break the rule.","zh":"如果正確答案是 “justice”，寫 “legal justice” 就違反規則。"},{"en":"Students should copy the word carefully from the passage because spelling matters.","zh":"學生應仔細從文章抄寫該字，因為拼字很重要。"},{"en":"The phrase gives a strict answer limit.","zh":"這個短語給出嚴格答案限制。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":14},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answer must come from the passage.","zh":"答案必須來自文章。"},{"en":"From the passage means using information or exact words found in the reading text.","zh":"“From the passage” 指使用閱讀文本中的資料或準確詞語。"},{"en":"Students should not use outside knowledge when the answer must come from the passage.","zh":"當答案必須來自文章時，學生不應使用外部知識。"},{"en":"If the passage does not contain the word, it may not be accepted in a completion question.","zh":"如果文章沒有包含該字，它在填充題中可能不被接受。"},{"en":"The phrase reminds students to rely on the text.","zh":"這個短語提醒學生依賴文本。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":14},{"front":"at the expense of","meaning":"以犧牲……為代價","examples":[{"en":"Therapeutic goals should not be pursued at the expense of justice.","zh":"治療性目標不應以犧牲公義為代價來追求。"},{"en":"At the expense of something means by sacrificing or harming that thing.","zh":"“At the expense of” 某事指以犧牲或傷害該事為代價。"},{"en":"A student should not improve speed at the expense of accuracy in writing.","zh":"學生不應以犧牲準確度為代價來提高寫作速度。"},{"en":"If rehabilitation is achieved by ignoring due process, it comes at the expense of justice.","zh":"如果更生是透過忽視正當程序達成，它就是以犧牲公義為代價。"},{"en":"The phrase warns that one benefit may damage another value.","zh":"這個短語提醒一項好處可能傷害另一項價值。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":14},{"front":"application","meaning":"應用","examples":[{"en":"The application of therapeutic jurisprudence is especially relevant to legal actors.","zh":"治療法理學的應用對法律參與者尤其相關。"},{"en":"Application means the practical use of an idea, theory, or method.","zh":"應用指某想法、理論或方法的實際使用。"},{"en":"The application of grammar rules becomes easier when students practise real sentences.","zh":"當學生練習真實句子時，文法規則的應用會變得更容易。"},{"en":"If a theory has practical application, people can use it to guide decisions and actions.","zh":"如果理論有實際應用，人們就可以用它指導決定和行動。"},{"en":"The word focuses on using knowledge, not only understanding it.","zh":"這個詞強調使用知識，而不只是理解知識。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":14},{"front":"new attitude","meaning":"新態度","examples":[{"en":"The passage describes a new attitude towards law.","zh":"文章描述了一種對法律的新態度。"},{"en":"A new attitude is a different way of thinking or feeling about something.","zh":"新態度是對某事不同的思考或感受方式。"},{"en":"A school may develop a new attitude towards mistakes by treating them as learning opportunities.","zh":"學校可能透過把錯誤視為學習機會，形成對錯誤的新態度。"},{"en":"If lawyers adopt a new attitude, they may care more about clients’ emotional experience.","zh":"如果律師採納新態度，可能更關心客戶的情感經驗。"},{"en":"The phrase signals a shift in perspective.","zh":"這個短語表示觀點轉變。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":14},{"front":"seek out","meaning":"尋找","examples":[{"en":"The approach asks people to seek out promising developments.","zh":"這種方法要求人們尋找有前景的發展。"},{"en":"To seek out something means to actively look for it.","zh":"“Seek out” 某事指主動尋找它。"},{"en":"A student who wants better feedback may seek out a teacher after class.","zh":"想得到更好回饋的學生可能課後尋找老師幫忙。"},{"en":"If legal reformers seek out ideas from other fields, they may find new solutions.","zh":"如果法律改革者尋找其他範疇的想法，可能找到新解決方案。"},{"en":"The phrase suggests intentional searching.","zh":"這個短語暗示有意識地搜尋。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":15},{"front":"borrow from other fields","meaning":"借鑑其他範疇","examples":[{"en":"Therapeutic jurisprudence encourages people to borrow from other fields.","zh":"治療法理學鼓勵人們借鑑其他範疇。"},{"en":"To borrow from other fields means to use ideas or methods from different areas of study or practice.","zh":"“Borrow from other fields” 指使用來自不同研究或實踐範疇的想法或方法。"},{"en":"A teacher may borrow from theatre training to make speaking lessons more active.","zh":"老師可能借鑑戲劇訓練，使口語課更活躍。"},{"en":"If courts borrow from psychology, they may design better rehabilitation processes.","zh":"如果法院借鑑心理學，可能設計更好的更生程序。"},{"en":"The phrase supports learning across disciplines.","zh":"這個短語支持跨學科學習。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":15},{"front":"complete the sentences","meaning":"完成句子","examples":[{"en":"Students complete the sentences with words from the passage.","zh":"學生使用文章中的詞語完成句子。"},{"en":"Complete the sentences means fill in missing words so each sentence becomes grammatically and logically complete.","zh":"“Complete the sentences” 指填入缺漏詞語，使每句在文法和邏輯上完整。"},{"en":"Students should read the whole sentence before choosing the answer.","zh":"學生應先閱讀整句，再選擇答案。"},{"en":"If the missing word must come from the passage, synonyms may not be accepted.","zh":"如果缺漏詞必須來自文章，同義詞可能不被接受。"},{"en":"The phrase is a common reading-test instruction.","zh":"這個短語是常見閱讀測驗指示。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":15},{"front":"no more than three words","meaning":"不超過三個字","examples":[{"en":"Students should use no more than three words for each answer.","zh":"學生每個答案應使用不超過三個字。"},{"en":"No more than three words means the answer must contain three words or fewer.","zh":"“No more than three words” 指答案必須包含三個字或更少。"},{"en":"If the answer is “high-risk situations,” it follows a three-word limit.","zh":"如果答案是 “high-risk situations”，就符合三字限制。"},{"en":"Students may lose marks if they add an unnecessary extra word.","zh":"如果學生加入不必要的額外字詞，可能會失分。"},{"en":"The phrase gives a strict word limit for exam answers.","zh":"這個短語給出考試答案的嚴格字數限制。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":15},{"front":"one aspect of","meaning":"……的一個方面","examples":[{"en":"One aspect of cognitive behavioural treatment involves planning.","zh":"認知行為治療的一個方面涉及規劃。"},{"en":"One aspect of something means one part or feature of it.","zh":"“One aspect of” 某事指它的一個部分或特徵。"},{"en":"One aspect of good writing is clear organisation.","zh":"良好寫作的一個方面是清晰組織。"},{"en":"If one aspect of treatment is planning, patients or offenders must think ahead.","zh":"如果治療的一個方面是規劃，病人或罪犯就必須預先思考。"},{"en":"The phrase helps discuss one part of a larger subject.","zh":"這個短語幫助討論較大題目中的一部分。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":15},{"front":"the preparation of","meaning":"……的準備；制定","examples":[{"en":"The treatment includes the preparation of relapse prevention plans.","zh":"這種治療包括預防重犯計劃的制定。"},{"en":"The preparation of something means the process of making or getting it ready.","zh":"“The preparation of” 某事指製作或準備好它的過程。"},{"en":"The preparation of a school presentation may include research, notes, and practice.","zh":"學校匯報的準備可能包括研究、筆記和練習。"},{"en":"If offenders prepare prevention plans, they must think seriously about future risks.","zh":"如果罪犯制定預防計劃，就必須認真思考未來風險。"},{"en":"The phrase focuses on planning before action.","zh":"這個短語強調行動前的規劃。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":15},{"front":"consider the chain of events","meaning":"考慮一連串事件","examples":[{"en":"Offenders must consider the chain of events that leads to crime.","zh":"罪犯必須考慮導致犯罪的一連串事件。"},{"en":"To consider the chain of events means to think carefully about the connected steps before a result.","zh":"“Consider the chain of events” 指仔細思考結果前互相連接的步驟。"},{"en":"A teacher may ask students to consider the chain of events that caused a playground fight.","zh":"老師可能要求學生考慮導致操場打架的一連串事件。"},{"en":"If offenders examine the chain, they may find moments where they could choose differently.","zh":"如果罪犯檢視這條事件鏈，可能找出可以作出不同選擇的時刻。"},{"en":"The phrase encourages step-by-step reflection.","zh":"這個短語鼓勵逐步反思。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":15},{"front":"a crime being committed","meaning":"犯罪行為發生","examples":[{"en":"The treatment asks offenders to examine how a crime is committed.","zh":"這種治療要求罪犯檢視犯罪行為如何發生。"},{"en":"A crime being committed means the act of breaking the law is actually happening.","zh":"“A crime being committed” 指違法行為正在實際發生。"},{"en":"A shopkeeper may call the police if they see a theft being committed.","zh":"如果店主看見盜竊行為正在發生，可能報警。"},{"en":"If offenders understand what happens before a crime is committed, they can plan to interrupt the pattern.","zh":"如果罪犯理解犯罪行為發生前有甚麼事，就可以計劃打斷該模式。"},{"en":"The phrase focuses on the process of criminal action.","zh":"這個短語強調犯罪行動的過程。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":15},{"front":"identify something in advance","meaning":"事先識別某事","examples":[{"en":"Offenders learn to identify high-risk situations in advance.","zh":"罪犯學會事先識別高風險情況。"},{"en":"To identify something in advance means to recognise it before it happens or before it becomes urgent.","zh":"“Identify something in advance” 指在某事發生前或變得緊急前認出它。"},{"en":"A student can identify difficult exam topics in advance and revise them early.","zh":"學生可以事先識別困難考試題目，並及早溫習。"},{"en":"If offenders identify danger signs early, they can avoid situations that may lead to crime.","zh":"如果罪犯及早識別危險信號，就可以避開可能導致犯罪的情況。"},{"en":"The phrase stresses preparation before a problem develops.","zh":"這個短語強調問題發展前的準備。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":15},{"front":"in advance","meaning":"事先；預先","examples":[{"en":"Offenders identify high-risk situations in advance.","zh":"罪犯事先識別高風險情況。"},{"en":"In advance means before something happens or before it is needed.","zh":"“In advance” 指在某事發生前或需要前。"},{"en":"Students should prepare questions in advance before meeting a tutor.","zh":"學生在見導師前應預先準備問題。"},{"en":"If risky situations are identified in advance, people have more time to make safer choices.","zh":"如果高風險情況被事先識別，人們就有更多時間作出較安全選擇。"},{"en":"The phrase highlights preparation ahead of time.","zh":"這個短語強調提前準備。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":15},{"front":"agree with the information","meaning":"與資料一致","examples":[{"en":"Students decide whether each statement agrees with the information in the passage.","zh":"學生判斷每項陳述是否與文章資料一致。"},{"en":"To agree with the information means to match what the passage says.","zh":"“Agree with the information” 指與文章所說內容相符。"},{"en":"If a passage says a programme seems promising, a statement saying it is already proven may not agree.","zh":"如果文章說某計劃看來有前景，而陳述說它已被證明有效，就未必一致。"},{"en":"Students should compare every key word with the passage before choosing TRUE.","zh":"學生在選 TRUE 前應把每個關鍵詞與文章比較。"},{"en":"The phrase is used in TRUE/FALSE/NOT GIVEN tasks.","zh":"這個短語用於 TRUE/FALSE/NOT GIVEN 題。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":15},{"front":"contradict the information","meaning":"與資料矛盾","examples":[{"en":"A statement is false if it contradicts the information in the passage.","zh":"如果陳述與文章資料矛盾，它就是 false。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"“Contradict the information” 指說出與文本內容相反的意思。"},{"en":"If the passage says a programme is only “reasonably successful,” a statement saying it has failed completely contradicts it.","zh":"如果文章說某計劃只是「頗為成功」，而陳述說它完全失敗，就與文章矛盾。"},{"en":"A statement can contradict the passage even if most words look similar.","zh":"即使大部分詞語看起來相似，陳述仍可能與文章矛盾。"},{"en":"The phrase helps students identify FALSE answers.","zh":"這個短語幫助學生識別 FALSE 答案。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":16},{"front":"no information on this","meaning":"沒有這方面資料","examples":[{"en":"Students write “NOT GIVEN” if there is no information on this.","zh":"如果沒有這方面資料，學生寫 “NOT GIVEN”。"},{"en":"No information on this means the passage does not say whether the statement is true or false.","zh":"“No information on this” 指文章沒有說明陳述是真還是假。"},{"en":"If a passage discusses rehabilitation but not programme cost, there is no information on cost.","zh":"如果文章討論更生但沒有討論計劃成本，成本方面就沒有資料。"},{"en":"Students should not use common sense when the passage gives no information.","zh":"當文章沒有資料時，學生不應使用常識作答。"},{"en":"The phrase signals that the answer should be NOT GIVEN.","zh":"這個短語表示答案應是 NOT GIVEN。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":16},{"front":"reading passage","meaning":"閱讀文章","examples":[{"en":"The statements refer to information in the reading passage.","zh":"這些陳述涉及閱讀文章中的資料。"},{"en":"A reading passage is the text that students read before answering questions.","zh":"閱讀文章是學生在回答問題前閱讀的文本。"},{"en":"In exams, students should return to the reading passage to check exact wording.","zh":"在考試中，學生應回到閱讀文章檢查準確措辭。"},{"en":"If an answer is not supported by the reading passage, it should not be chosen.","zh":"如果答案沒有得到閱讀文章支持，就不應選擇它。"},{"en":"The phrase refers to the source text in a reading task.","zh":"這個短語指閱讀任務中的來源文本。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":16},{"front":"has been proved to","meaning":"已被證明","examples":[{"en":"The statement claims that rehabilitative programmes have been proved to reduce re-offending.","zh":"該陳述聲稱更生計劃已被證明能減少重犯。"},{"en":"Has been proved to means evidence has shown clearly that something is true.","zh":"“Has been proved to” 指證據已清楚顯示某事為真。"},{"en":"A medicine should not be described as effective unless it has been proved to work in proper studies.","zh":"除非藥物在正式研究中已被證明有效，否則不應被描述為有效。"},{"en":"If a programme merely seems promising, it has not necessarily been proved to reduce crime.","zh":"如果一個計劃只是看似有前景，就不一定已被證明能減少犯罪。"},{"en":"The phrase requires strong evidence, not just hope or early results.","zh":"這個短語需要強證據，而不只是希望或早期結果。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":16},{"front":"greatly reduce the chance of","meaning":"大大減低……的機會","examples":[{"en":"Some programmes may greatly reduce the chance of re-offending.","zh":"一些計劃可能大大減低重犯的機會。"},{"en":"To greatly reduce the chance of something means to make it much less likely to happen.","zh":"“Greatly reduce the chance of” 某事指令它發生的可能性大幅降低。"},{"en":"Wearing a seat belt can greatly reduce the chance of serious injury in a crash.","zh":"扣安全帶可以大大減低撞車時嚴重受傷的機會。"},{"en":"If rehabilitation teaches offenders to avoid high-risk situations, it may reduce re-offending risk.","zh":"如果更生教罪犯避開高風險情況，可能減低重犯風險。"},{"en":"The phrase describes a strong decrease in probability.","zh":"這個短語描述可能性的強烈下降。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":16},{"front":"re-offending","meaning":"重犯","examples":[{"en":"The programme aims to reduce the chance of re-offending.","zh":"該計劃旨在減低重犯的機會。"},{"en":"Re-offending means committing another crime after already having offended before.","zh":"重犯指在已犯罪後再次犯罪。"},{"en":"A young offender who steals again after probation is an example of re-offending.","zh":"接受感化安排後再次偷竊的年輕罪犯，就是重犯的例子。"},{"en":"If rehabilitation changes thinking and habits, re-offending may become less likely.","zh":"如果更生改變思維和習慣，重犯可能變得較不可能。"},{"en":"The phrase focuses on repeated criminal behaviour.","zh":"這個短語強調重複犯罪行為。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":16},{"front":"aims to make","meaning":"旨在使……","examples":[{"en":"Therapeutic jurisprudence aims to make treatment part of the legal process.","zh":"治療法理學旨在使治療成為法律程序的一部分。"},{"en":"Aims to make something happen means has the purpose of causing that result.","zh":"“Aims to make” 某事發生指以造成該結果為目的。"},{"en":"A school reading scheme aims to make books part of students’ daily lives.","zh":"學校閱讀計劃旨在使書本成為學生日常生活的一部分。"},{"en":"If a theory aims to make treatment part of law, it wants rehabilitation built into legal decisions.","zh":"如果一個理論旨在使治療成為法律的一部分，它希望更生被納入法律決定。"},{"en":"The phrase expresses the purpose of an approach or plan.","zh":"這個短語表達方法或計劃的目的。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":16},{"front":"take part in deciding","meaning":"參與決定","examples":[{"en":"Offenders might take part in deciding parts of their rehabilitation plan.","zh":"罪犯可能參與決定其更生計劃的部分內容。"},{"en":"To take part in deciding something means to participate in making the decision.","zh":"“Take part in deciding” 某事指參與作出該決定。"},{"en":"Students may take part in deciding class rules so they feel responsible for them.","zh":"學生可能參與決定班規，因而對它們更有責任感。"},{"en":"If offenders help decide parts of their plan, they may be more committed to following it.","zh":"如果罪犯協助決定計劃部分內容，可能更有承擔去遵守它。"},{"en":"The phrase describes participation in decision-making.","zh":"這個短語描述參與決策。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":16},{"front":"what their punishment should be","meaning":"他們應受甚麼懲罰","examples":[{"en":"The question asks whether offenders help decide what their punishment should be.","zh":"題目問罪犯是否協助決定他們應受甚麼懲罰。"},{"en":"What their punishment should be means the penalty, order, or consequence they ought to receive.","zh":"“What their punishment should be” 指他們應接受的刑罰、命令或後果。"},{"en":"A court decides what a punishment should be after considering harm, responsibility, and legal rules.","zh":"法院在考慮傷害、責任和法律規則後，決定懲罰應是甚麼。"},{"en":"If offenders help plan rehabilitation, that does not necessarily mean they decide their own punishment.","zh":"如果罪犯協助規劃更生，這不一定代表他們決定自己的懲罰。"},{"en":"The phrase focuses on the nature or level of punishment.","zh":"這個短語強調懲罰的性質或程度。"}],"source":"78 - Therapeutic Jurisprudence - An Overview.pdf","sourcePage":16}],"ielts/reading/passage-2/Practice 79":[{"front":"distance learning","meaning":"遙距學習","examples":[{"en":"Distance learning is not a recent innovation in education.","zh":"遙距學習並不是教育中的近期創新。"},{"en":"Distance learning is a way of studying when students and teachers are not in the same physical classroom.","zh":"distance learning 是學生和教師不在同一實體課室中進行學習的方式。"},{"en":"A nurse who works shifts may use distance learning to complete a course from home.","zh":"需要輪班工作的護士可能透過遙距學習在家完成課程。"},{"en":"Distance learning can help people study when travel, work, or family duties make campus attendance difficult.","zh":"當交通、工作或家庭責任令到校上課困難時，遙距學習可以幫助人們讀書。"},{"en":"This phrase focuses on learning across distance, not simply using a computer.","zh":"這個片語聚焦於跨距離學習，而不只是使用電腦。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":1},{"front":"a recent innovation in","meaning":"……中的近期創新","examples":[{"en":"Distance learning is not a recent innovation in education.","zh":"遙距學習並不是教育中的近期創新。"},{"en":"A recent innovation in something is a new development or method introduced not long ago.","zh":"a recent innovation in something 指不久前在某領域引入的新發展或新方法。"},{"en":"Online booking was once a recent innovation in travel, but it is now normal.","zh":"網上訂票曾經是旅遊中的近期創新，但現在已很普通。"},{"en":"If people call something a recent innovation, they suggest it belongs to modern change.","zh":"如果人們稱某事為近期創新，他們暗示它屬於現代變化。"},{"en":"This phrase contrasts new developments with older practices.","zh":"這個片語把新發展與較舊做法作對比。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":1},{"front":"correspondence courses","meaning":"函授課程","examples":[{"en":"Correspondence courses have been used for over 150 years.","zh":"函授課程已被使用超過150年。"},{"en":"Correspondence courses are courses taught through written materials sent between teachers and students, often by post.","zh":"correspondence courses 是透過教師與學生之間寄送文字教材來教授的課程，通常以郵寄方式進行。"},{"en":"Before online lessons, a worker could study accounting through correspondence courses mailed to their home.","zh":"在網上課堂出現之前，工人可以透過寄到家中的函授課程學習會計。"},{"en":"Correspondence courses made education possible for people who lived far from schools.","zh":"函授課程令住得離學校很遠的人也能接受教育。"},{"en":"This phrase refers to an older form of distance learning.","zh":"這個片語指較早期形式的遙距學習。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":1},{"front":"interactive technologies","meaning":"互動科技","examples":[{"en":"New interactive technologies provide new opportunities for teaching.","zh":"新互動科技為教學提供新機會。"},{"en":"Interactive technologies are tools that let users respond, communicate, practise, or receive feedback actively.","zh":"interactive technologies 是讓使用者主動回應、溝通、練習或獲得回饋的工具。"},{"en":"A language app with speaking practice and instant correction is an interactive technology.","zh":"有口語練習和即時改正功能的語言應用程式就是一種互動科技。"},{"en":"Interactive technologies can make online lessons feel less passive because students can answer, click, discuss, and experiment.","zh":"互動科技可以令網上課堂不那麼被動，因為學生可以回答、點擊、討論和實驗。"},{"en":"This phrase describes technology that involves participation, not just watching.","zh":"這個片語描述需要參與的科技，而不只是觀看。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":1},{"front":"provide new opportunities","meaning":"提供新機會","examples":[{"en":"Interactive technologies provide new opportunities for teaching at a distance.","zh":"互動科技為遙距教學提供新機會。"},{"en":"To provide new opportunities means to create fresh chances for people to do something.","zh":"provide new opportunities 指創造新的機會讓人做某事。"},{"en":"A community centre may provide new opportunities for adults to learn computer skills.","zh":"社區中心可能為成年人提供學習電腦技能的新機會。"},{"en":"If technology connects teachers and remote students, it provides learning chances that were not available before.","zh":"如果科技連接教師和偏遠學生，它就提供了以前沒有的學習機會。"},{"en":"This phrase highlights new possibilities created by a change.","zh":"這個片語突出由改變創造的新可能性。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":1},{"front":"strategies for teaching","meaning":"教學策略","examples":[{"en":"New technologies provide strategies for teaching at a distance.","zh":"新科技提供遙距教學策略。"},{"en":"Strategies for teaching are planned methods teachers use to help students learn effectively.","zh":"strategies for teaching 是教師用來幫助學生有效學習的有計劃方法。"},{"en":"A teacher may use quizzes, group work, and examples as strategies for teaching grammar.","zh":"老師可能使用小測、小組活動和例子作為文法教學策略。"},{"en":"If students are online, teachers need different strategies to check understanding and keep attention.","zh":"如果學生在網上學習，教師需要不同策略來檢查理解和維持專注。"},{"en":"This phrase focuses on teaching methods, not only teaching materials.","zh":"這個片語聚焦於教學方法，而不只是教材。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":1},{"front":"teaching at a distance","meaning":"遙距教學","examples":[{"en":"Teachers now have new strategies for teaching at a distance.","zh":"教師現在有新的遙距教學策略。"},{"en":"Teaching at a distance means teaching students who are not physically present in the same classroom.","zh":"teaching at a distance 指教授不在同一實體課室中的學生。"},{"en":"A tutor may teach at a distance by using video calls, shared documents, and online quizzes.","zh":"導師可能透過視像通話、共享文件和網上小測進行遙距教學。"},{"en":"If students live in different towns, teaching at a distance can reduce travel time and cost.","zh":"如果學生住在不同城鎮，遙距教學可以減少交通時間和成本。"},{"en":"This phrase describes the teacher’s side of distance learning.","zh":"這個片語描述遙距學習中教師的一方。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":1},{"front":"face-to-face classrooms","meaning":"面對面課堂","examples":[{"en":"Several studies have compared face-to-face classrooms with distance classrooms.","zh":"幾項研究比較了面對面課堂與遙距課堂。"},{"en":"Face-to-face classrooms are traditional classrooms where teachers and students meet in person.","zh":"face-to-face classrooms 是教師和學生親身見面的傳統課堂。"},{"en":"In a face-to-face classroom, a teacher can notice confusion through students’ expressions.","zh":"在面對面課堂中，老師可以透過學生表情察覺困惑。"},{"en":"Face-to-face classrooms allow immediate discussion, but they require everyone to be in the same place.","zh":"面對面課堂容許即時討論，但要求所有人在同一地點。"},{"en":"This phrase contrasts physical classroom teaching with remote learning.","zh":"這個片語把實體課堂教學與遙距學習作對比。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":1},{"front":"distance classrooms","meaning":"遙距課堂","examples":[{"en":"Researchers compared distance classrooms with face-to-face classrooms.","zh":"研究人員把遙距課堂與面對面課堂作比較。"},{"en":"Distance classrooms are learning settings where students take part from different locations.","zh":"distance classrooms 是學生從不同地點參與的學習環境。"},{"en":"A distance classroom may include live video lessons, discussion boards, and online assignments.","zh":"遙距課堂可能包括直播視像課、討論區和網上作業。"},{"en":"If students cannot travel to campus, distance classrooms can keep them connected to the course.","zh":"如果學生不能前往校園，遙距課堂可以讓他們繼續與課程保持連繫。"},{"en":"This phrase refers to the classroom environment created across distance.","zh":"這個片語指跨距離建立的課堂環境。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":1},{"front":"in order to evaluate","meaning":"為了評估","examples":[{"en":"The studies compared classrooms in order to evaluate differences.","zh":"這些研究比較課堂，是為了評估差異。"},{"en":"In order to evaluate means for the purpose of judging, measuring, or assessing something.","zh":"in order to evaluate 指為了判斷、量度或評估某事。"},{"en":"A school may survey parents in order to evaluate a new homework policy.","zh":"學校可能調查家長，是為了評估新的功課政策。"},{"en":"If researchers want to know whether online teaching works, they compare results in order to evaluate its effectiveness.","zh":"如果研究人員想知道網上教學是否有效，他們會比較結果以評估其成效。"},{"en":"This phrase introduces the purpose of an investigation.","zh":"這個片語引入調查目的。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":1},{"front":"student performance","meaning":"學生表現","examples":[{"en":"The studies evaluated differences in student performance.","zh":"這些研究評估學生表現上的差異。"},{"en":"Student performance means how well students do in learning, tests, assignments, or skills.","zh":"student performance 指學生在學習、測驗、作業或技能方面表現得如何。"},{"en":"Teachers often look at homework, class participation, and exam results to judge student performance.","zh":"教師常查看功課、課堂參與和考試結果來判斷學生表現。"},{"en":"If student performance improves after a new teaching method, the method may be useful.","zh":"如果採用新教學方法後學生表現改善，該方法可能有用。"},{"en":"This phrase focuses on learning results, not just attendance.","zh":"這個片語聚焦於學習結果，而不只是出席率。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":1},{"front":"quality of instruction","meaning":"教學質素","examples":[{"en":"The studies examined student performance and quality of instruction.","zh":"這些研究檢視學生表現和教學質素。"},{"en":"Quality of instruction means how effective, clear, organised, and helpful the teaching is.","zh":"quality of instruction 指教學是否有效、清晰、有組織和有幫助。"},{"en":"A course with clear explanations, useful feedback, and fair assessment has good quality of instruction.","zh":"一個有清楚解釋、有用回饋和公平評核的課程，具有良好教學質素。"},{"en":"If the quality of instruction is poor, students may struggle even when the course materials look attractive.","zh":"如果教學質素差，即使課程材料看起來吸引，學生也可能學得吃力。"},{"en":"This phrase judges the teaching itself.","zh":"這個片語評價教學本身。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":2},{"front":"meta-analysis","meaning":"綜合分析","examples":[{"en":"A meta-analysis of the studies showed strong results for distance learning.","zh":"對這些研究的綜合分析顯示遙距學習有強勁結果。"},{"en":"A meta-analysis is a study that combines and analyses results from many separate studies.","zh":"meta-analysis 是把多項獨立研究結果結合並分析的研究。"},{"en":"Doctors may use a meta-analysis to understand whether a treatment works across many trials.","zh":"醫生可能使用綜合分析來了解某治療是否在多項試驗中有效。"},{"en":"If many studies are combined, a meta-analysis can give a broader picture than one small study.","zh":"如果多項研究被結合，綜合分析可以比一項小研究提供更廣闊圖像。"},{"en":"This phrase refers to research about research results.","zh":"這個片語指關於研究結果的研究。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":2},{"front":"perform equally well","meaning":"表現同樣好","examples":[{"en":"Distance-learning students performed equally well.","zh":"遙距學習學生表現同樣好。"},{"en":"To perform equally well means to achieve the same level of results as another group.","zh":"perform equally well 指達到與另一組相同水平的結果。"},{"en":"Students using online notes may perform equally well as those using printed notes if both groups practise enough.","zh":"如果兩組都練習足夠，使用網上筆記的學生可能與使用印刷筆記的學生表現同樣好。"},{"en":"If distance learners perform equally well, location may not be the main factor in achievement.","zh":"如果遙距學習者表現同樣好，地點可能不是成就的主要因素。"},{"en":"This phrase compares outcomes and says neither group is clearly better.","zh":"這個片語比較結果，表示沒有一組明顯較好。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":2},{"front":"outperform their classroom counterparts","meaning":"表現優於對應的課堂課程","examples":[{"en":"Some distance courses outperformed their classroom counterparts.","zh":"一些遙距課程表現優於對應的課堂課程。"},{"en":"To outperform their classroom counterparts means to do better than similar courses taught in traditional classrooms.","zh":"outperform their classroom counterparts 指表現比傳統課堂教授的相似課程更好。"},{"en":"An online writing class may outperform a classroom class if feedback is faster and more detailed.","zh":"如果回饋更快且更詳細，網上寫作課可能表現優於面授寫作課。"},{"en":"If distance courses outperform classroom versions, technology may be improving learning rather than weakening it.","zh":"如果遙距課程表現優於課堂版本，科技可能正在改善學習，而不是削弱學習。"},{"en":"This phrase compares matching groups or courses and shows one does better.","zh":"這個片語比較對應群體或課程，並顯示其中一方更好。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":2},{"front":"be consistent over","meaning":"在……中保持一致","examples":[{"en":"This result has been consistent over many studies.","zh":"這個結果在許多研究中保持一致。"},{"en":"To be consistent over something means to remain similar or stable across repeated cases or time periods.","zh":"be consistent over something 指在重複個案或時間期間中保持相似或穩定。"},{"en":"A student’s improvement is more convincing if it is consistent over several tests.","zh":"如果學生的進步在幾次測驗中都保持一致，就更有說服力。"},{"en":"If results are consistent over many studies, researchers can trust the pattern more.","zh":"如果結果在許多研究中保持一致，研究人員可以更相信這個模式。"},{"en":"This phrase stresses repeated agreement rather than one lucky result.","zh":"這個片語強調反覆一致，而不是一次幸運結果。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":2},{"front":"across many disciplines","meaning":"跨多個學科","examples":[{"en":"The result was consistent across many disciplines.","zh":"這個結果跨多個學科保持一致。"},{"en":"Across many disciplines means in many different academic subjects or fields of study.","zh":"across many disciplines 指在許多不同學術科目或研究領域中。"},{"en":"Online research skills are useful across many disciplines, from history to biology.","zh":"網上研究技能在多個學科中都有用，從歷史到生物都是如此。"},{"en":"If distance learning works across many disciplines, it may not be limited to one subject.","zh":"如果遙距學習跨多個學科都有效，它可能不只限於某一科目。"},{"en":"This phrase shows that a pattern appears in different fields.","zh":"這個片語顯示某模式出現在不同領域。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":2},{"front":"advances in communication technology","meaning":"通訊科技的進步","examples":[{"en":"Advances in communication technology have changed distance learning.","zh":"通訊科技的進步改變了遙距學習。"},{"en":"Advances in communication technology are improvements in tools that help people send, receive, and share information.","zh":"advances in communication technology 是幫助人們傳送、接收和分享資訊的工具進步。"},{"en":"Video calls and messaging apps are advances that make remote teamwork easier.","zh":"視像通話和訊息應用程式是令遙距團隊合作更容易的進步。"},{"en":"When communication technology improves, teachers can explain, demonstrate, and answer questions from far away.","zh":"當通訊科技改善，教師可以從遠處解釋、示範和回答問題。"},{"en":"This phrase links technological progress with better connection.","zh":"這個片語把科技進步與更好連繫連接起來。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":2},{"front":"innovative methods of delivery","meaning":"創新的傳授方式","examples":[{"en":"Innovative methods of delivery have improved distance education.","zh":"創新的傳授方式改善了遙距教育。"},{"en":"Innovative methods of delivery are new ways of presenting or providing lessons, materials, or services.","zh":"innovative methods of delivery 是呈現或提供課堂、教材或服務的新方法。"},{"en":"A school may use videos, online quizzes, and virtual labs as innovative methods of delivery.","zh":"學校可能使用影片、網上小測和虛擬實驗室作為創新的傳授方式。"},{"en":"If delivery methods become more flexible, students can learn at different times and places.","zh":"如果傳授方式變得更靈活，學生可以在不同時間和地點學習。"},{"en":"This phrase focuses on how teaching reaches learners.","zh":"這個片語聚焦於教學如何接觸學習者。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":2},{"front":"delivery of instruction","meaning":"教學傳授","examples":[{"en":"Technology has changed the delivery of instruction at a distance.","zh":"科技改變了遙距教學傳授。"},{"en":"Delivery of instruction means the way teaching is provided to students.","zh":"delivery of instruction 指教學提供給學生的方式。"},{"en":"A teacher can improve delivery of instruction by combining explanations, examples, and practice tasks.","zh":"教師可以透過結合解釋、例子和練習任務來改善教學傳授。"},{"en":"If instruction is delivered through video and software, students may access it outside normal classroom hours.","zh":"如果教學透過影片和軟件傳授，學生可能在正常課堂時間以外接觸它。"},{"en":"This phrase describes the method of teaching, not the subject itself.","zh":"這個片語描述教學方法，而不是科目本身。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":2},{"front":"challenge the idea that","meaning":"挑戰……的想法","examples":[{"en":"New methods have challenged the idea that laboratory courses require face-to-face teaching.","zh":"新方法挑戰了實驗課程需要面對面教學的想法。"},{"en":"To challenge the idea that something is true means to question or disagree with that belief.","zh":"challenge the idea that something is true 指質疑或不同意某信念。"},{"en":"Online tutoring challenges the idea that language speaking practice must happen in a classroom.","zh":"網上補習挑戰了語言口語練習必須在課室中進行的想法。"},{"en":"If virtual labs work well, they challenge old assumptions about practical science teaching.","zh":"如果虛擬實驗室運作良好，它們便挑戰關於實踐科學教學的舊假設。"},{"en":"This phrase introduces a belief that is being questioned.","zh":"這個片語引入正在被質疑的信念。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":2},{"front":"laboratory courses","meaning":"實驗課程","examples":[{"en":"Laboratory courses can now be delivered through distance learning.","zh":"實驗課程現在可以透過遙距學習提供。"},{"en":"Laboratory courses are courses that include practical experiments, measurements, or hands-on scientific work.","zh":"laboratory courses 是包括實踐實驗、測量或動手科學工作的課程。"},{"en":"A chemistry laboratory course may teach students how to measure reactions safely.","zh":"化學實驗課程可能教學生如何安全量度反應。"},{"en":"If laboratory courses move online, teachers need ways to replace or support physical experiments.","zh":"如果實驗課程轉到網上，教師需要方法取代或支援實體實驗。"},{"en":"This phrase refers to practical science or engineering courses, not only lectures.","zh":"這個片語指實踐科學或工程課程，而不只是講課。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":2},{"front":"face-to-face laboratory setting","meaning":"面對面實驗室環境","examples":[{"en":"Some people believe laboratory courses need a face-to-face laboratory setting.","zh":"有些人相信實驗課程需要面對面實驗室環境。"},{"en":"A face-to-face laboratory setting is a physical lab where students and instructors work together in person.","zh":"face-to-face laboratory setting 是學生和導師親身一起工作的實體實驗室。"},{"en":"In a face-to-face laboratory setting, students can handle real equipment under supervision.","zh":"在面對面實驗室環境中，學生可以在監督下操作真實設備。"},{"en":"If safety matters, some experiments may still require a physical laboratory environment.","zh":"如果安全很重要，一些實驗可能仍需要實體實驗室環境。"},{"en":"This phrase contrasts real lab attendance with remote or virtual laboratory work.","zh":"這個片語把真實到場實驗室與遙距或虛擬實驗室工作作對比。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":3},{"front":"in engineering","meaning":"在工程學方面","examples":[{"en":"In engineering, virtual laboratories have been used to teach experimental courses.","zh":"在工程學方面，虛擬實驗室已被用來教授實驗性課程。"},{"en":"In engineering means within the field of designing, building, testing, and improving machines, structures, or systems.","zh":"in engineering 指在設計、建造、測試和改善機械、結構或系統的領域中。"},{"en":"In engineering, students often learn by solving real problems and testing designs.","zh":"在工程學方面，學生常透過解決真實問題和測試設計來學習。"},{"en":"If virtual labs work in engineering, practical subjects may be easier to teach remotely.","zh":"如果虛擬實驗室在工程學中有效，實踐科目可能更容易遙距教授。"},{"en":"This phrase identifies the academic or professional field being discussed.","zh":"這個片語指出正在討論的學術或專業領域。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":3},{"front":"virtual laboratories","meaning":"虛擬實驗室","examples":[{"en":"Virtual laboratories have been used to teach thermodynamics.","zh":"虛擬實驗室已被用來教授熱力學。"},{"en":"Virtual laboratories are computer-based environments where students can perform or simulate experiments.","zh":"virtual laboratories 是以電腦為基礎、讓學生進行或模擬實驗的環境。"},{"en":"A physics student may use a virtual laboratory to test how force affects motion.","zh":"物理學生可能使用虛擬實驗室測試力如何影響運動。"},{"en":"Virtual laboratories can reduce safety risks and allow students to repeat experiments many times.","zh":"虛擬實驗室可以降低安全風險，並讓學生多次重複實驗。"},{"en":"This phrase refers to simulated lab spaces, not physical rooms.","zh":"這個片語指模擬實驗空間，而不是實體房間。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":3},{"front":"thermodynamics","meaning":"熱力學","examples":[{"en":"Thermodynamics can be taught through virtual laboratories.","zh":"熱力學可以透過虛擬實驗室教授。"},{"en":"Thermodynamics is the study of heat, energy, temperature, and how they move or change.","zh":"thermodynamics 是研究熱、能量、溫度及其如何移動或變化的學科。"},{"en":"An engineering student studies thermodynamics to understand engines, refrigerators, and power systems.","zh":"工程學生學習熱力學，以理解引擎、雪櫃和供電系統。"},{"en":"If students can simulate heat transfer, they may understand thermodynamics without handling dangerous equipment.","zh":"如果學生可以模擬熱傳遞，就可能不需操作危險設備也能理解熱力學。"},{"en":"This word names a technical subject in science and engineering.","zh":"這個詞指科學和工程中的技術科目。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":3},{"front":"electronic circuits","meaning":"電子電路","examples":[{"en":"Virtual laboratories have been used to teach electronic circuits.","zh":"虛擬實驗室已被用來教授電子電路。"},{"en":"Electronic circuits are connected electrical parts that control the flow of electricity in devices.","zh":"electronic circuits 是連接起來、控制裝置中電流流動的電子零件。"},{"en":"A simple electronic circuit may include a battery, wire, switch, and light bulb.","zh":"簡單電子電路可能包括電池、電線、開關和燈泡。"},{"en":"If students build circuits virtually first, they may make fewer mistakes with real components later.","zh":"如果學生先虛擬建立電路，之後操作真實零件時可能少犯錯。"},{"en":"This phrase is common in engineering, physics, and technology courses.","zh":"這個片語常見於工程、物理和科技課程。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":3},{"front":"experimental courses","meaning":"實驗性課程","examples":[{"en":"Distance learning can now be used for experimental courses.","zh":"遙距學習現在可以用於實驗性課程。"},{"en":"Experimental courses are courses that involve experiments, practical testing, or hands-on investigation.","zh":"experimental courses 是涉及實驗、實踐測試或動手調查的課程。"},{"en":"A biology experimental course may ask students to observe plant growth under different conditions.","zh":"生物實驗性課程可能要求學生觀察植物在不同條件下的生長。"},{"en":"If experimental courses are taught remotely, teachers must solve problems of safety, equipment, and assessment.","zh":"如果實驗性課程以遙距方式教授，教師必須解決安全、設備和評核問題。"},{"en":"This phrase refers to courses based on doing and testing, not only reading.","zh":"這個片語指以操作和測試為基礎的課程，而不只是閱讀。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":3},{"front":"programmes in nursing","meaning":"護理課程","examples":[{"en":"Programmes in nursing are beginning to use distance-learning technologies.","zh":"護理課程開始使用遙距學習科技。"},{"en":"Programmes in nursing are educational courses that train people to become nurses or improve nursing skills.","zh":"programmes in nursing 是培訓人成為護士或改善護理技能的教育課程。"},{"en":"A nursing programme may include lessons on patient care, medicine, hygiene, and communication.","zh":"護理課程可能包括病人照顧、藥物、衞生和溝通方面的課堂。"},{"en":"If nursing programmes use distance learning, students in remote areas may access professional training.","zh":"如果護理課程使用遙距學習，偏遠地區學生可能接觸到專業培訓。"},{"en":"This phrase refers to structured nursing education.","zh":"這個片語指有結構的護理教育。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":3},{"front":"deliver courses through","meaning":"透過……提供課程","examples":[{"en":"Universities deliver courses through distance learning.","zh":"大學透過遙距學習提供課程。"},{"en":"To deliver courses through something means to provide teaching by using that method or system.","zh":"deliver courses through something 指使用某方法或系統提供教學。"},{"en":"A college may deliver courses through evening classes for adults who work during the day.","zh":"學院可能透過夜校課程為日間工作的成年人提供課程。"},{"en":"If universities deliver courses through the Internet, students can study without moving to campus.","zh":"如果大學透過互聯網提供課程，學生不用搬到校園也能讀書。"},{"en":"This phrase focuses on the method used to provide education.","zh":"這個片語聚焦於提供教育所使用的方法。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":3},{"front":"reach students in different locations","meaning":"接觸不同地區的學生","examples":[{"en":"Distance learning helps universities reach students in different locations.","zh":"遙距學習幫助大學接觸不同地區的學生。"},{"en":"To reach students in different locations means to make education available to learners who live in many places.","zh":"reach students in different locations 指令住在不同地方的學習者都能接受教育。"},{"en":"A language school can reach students in different locations by offering live online lessons.","zh":"語言學校可以透過直播網課接觸不同地區的學生。"},{"en":"If a course reaches more locations, people who cannot travel can still join.","zh":"如果課程能接觸更多地區，不能出行的人仍然可以參與。"},{"en":"This phrase highlights access across geography.","zh":"這個片語突出跨地域的可及性。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":3},{"front":"boost enrolment","meaning":"提高收生人數","examples":[{"en":"Distance courses can help universities boost enrolment.","zh":"遙距課程可以幫助大學提高收生人數。"},{"en":"To boost enrolment means to increase the number of students who register for a course or institution.","zh":"boost enrolment 指增加註冊某課程或院校的學生人數。"},{"en":"A school may boost enrolment by offering flexible evening classes.","zh":"學校可能透過提供靈活夜間課程來提高收生人數。"},{"en":"If online courses remove travel barriers, more students may sign up.","zh":"如果網上課程消除交通障礙，更多學生可能報名。"},{"en":"This phrase describes increasing student numbers.","zh":"這個片語描述學生人數增加。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":3},{"front":"online distance-learning programmes","meaning":"網上遙距學習課程","examples":[{"en":"A survey examined online distance-learning programmes.","zh":"一項調查檢視了網上遙距學習課程。"},{"en":"Online distance-learning programmes are courses or degree paths delivered remotely through the Internet.","zh":"online distance-learning programmes 是透過互聯網遙距提供的課程或學位路徑。"},{"en":"An online distance-learning programme may include recorded lectures, live tutorials, and digital assignments.","zh":"網上遙距學習課程可能包括錄影講課、直播導修和電子作業。"},{"en":"If online programmes are well designed, students can study from home while still receiving feedback.","zh":"如果網上課程設計良好，學生可以在家學習，同時仍獲得回饋。"},{"en":"This phrase combines online delivery with remote education.","zh":"這個片語結合網上傳授與遙距教育。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":3},{"front":"reveal a large increase in","meaning":"顯示……大幅增加","examples":[{"en":"The survey revealed a large increase in student enrolment.","zh":"調查顯示學生註冊人數大幅增加。"},{"en":"To reveal a large increase in something means to show that it has grown greatly.","zh":"reveal a large increase in something 指顯示某事物大幅增長。"},{"en":"School records may reveal a large increase in library use after new books arrive.","zh":"新書到校後，學校紀錄可能顯示圖書館使用量大幅增加。"},{"en":"If a survey shows enrolment rising sharply, the programme may be attracting new learners.","zh":"如果調查顯示收生人數急升，該課程可能正在吸引新學習者。"},{"en":"This phrase introduces evidence of strong growth.","zh":"這個片語引入強勁增長的證據。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":4},{"front":"student enrolment","meaning":"學生註冊人數；收生人數","examples":[{"en":"Distance-learning programmes have increased student enrolment.","zh":"遙距學習課程增加了學生註冊人數。"},{"en":"Student enrolment means the number of students officially registered for a course, school, or university.","zh":"student enrolment 指正式註冊某課程、學校或大學的學生人數。"},{"en":"A college may check student enrolment before deciding how many teachers to hire.","zh":"學院在決定聘請多少教師前，可能會查看學生註冊人數。"},{"en":"If enrolment rises quickly, the institution may need more support staff and learning resources.","zh":"如果收生人數快速上升，院校可能需要更多支援職員和學習資源。"},{"en":"This phrase refers to registered student numbers.","zh":"這個片語指已註冊學生人數。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":4},{"front":"availability of distance courses","meaning":"遙距課程的可得性","examples":[{"en":"The availability of distance courses has helped some people attend college.","zh":"遙距課程的可得性幫助一些人上大學。"},{"en":"Availability of distance courses means distance courses exist and can be accessed by learners.","zh":"availability of distance courses 指遙距課程存在，並可供學習者接觸。"},{"en":"The availability of evening classes helps workers continue studying after work.","zh":"夜校課程的可得性幫助工人在下班後繼續學習。"},{"en":"If distance courses are available locally or online, people who cannot move away can still study.","zh":"如果遙距課程在本地或網上可得，不能搬走的人仍能讀書。"},{"en":"This phrase focuses on whether learning options are accessible.","zh":"這個片語聚焦於學習選項是否可接觸。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":4},{"front":"make it possible for","meaning":"令某人能夠……","examples":[{"en":"Distance courses have made it possible for some people to attend college.","zh":"遙距課程令一些人能夠上大學。"},{"en":"To make it possible for someone to do something means to remove barriers so they can do it.","zh":"make it possible for someone to do something 指移除障礙，令某人可以做某事。"},{"en":"Online payment makes it possible for small shops to sell to customers far away.","zh":"網上付款令小店能夠把貨品賣給遠方顧客。"},{"en":"If a course is flexible, it may make study possible for parents and full-time workers.","zh":"如果課程靈活，它可能令父母和全職工人能夠讀書。"},{"en":"This phrase shows how one thing creates opportunity for another.","zh":"這個片語顯示一事物如何為另一事物創造機會。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":4},{"front":"attend college","meaning":"上大學","examples":[{"en":"Some people can attend college because of distance courses.","zh":"一些人因為遙距課程而能夠上大學。"},{"en":"To attend college means to study at a college or higher-education institution.","zh":"attend college 指在學院或高等教育院校讀書。"},{"en":"A young parent may attend college part-time while caring for a child.","zh":"年輕父母可能一邊照顧孩子，一邊兼讀上大學。"},{"en":"If college courses are available online, students may attend without living near campus.","zh":"如果大學課程可在網上修讀，學生不用住在校園附近也能上大學。"},{"en":"This phrase refers to taking part in higher education.","zh":"這個片語指參與高等教育。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":4},{"front":"accessible within their locality","meaning":"在本地區內可接觸到","examples":[{"en":"Courses are accessible within students’ locality.","zh":"課程在學生本地區內可接觸到。"},{"en":"Accessible within their locality means available in or near the area where students live.","zh":"accessible within their locality 指可在學生居住地區內或附近取得。"},{"en":"A health clinic is accessible within a family’s locality if they can reach it by a short bus ride.","zh":"如果家庭坐短程巴士便能到達診所，該診所在本地區內可接觸到。"},{"en":"If courses are local or online, students may not need to leave their community to study.","zh":"如果課程在本地或網上可得，學生可能不需要離開社區去讀書。"},{"en":"This phrase focuses on local access and convenience.","zh":"這個片語聚焦於本地可及性和方便。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":4},{"front":"the time of course delivery","meaning":"課程授課時間","examples":[{"en":"The time of course delivery may be convenient for students.","zh":"課程授課時間可能對學生方便。"},{"en":"The time of course delivery means when a course is taught or made available.","zh":"time of course delivery 指課程在甚麼時間教授或提供。"},{"en":"Evening course delivery may suit workers who cannot study during office hours.","zh":"晚間授課時間可能適合不能在辦公時間讀書的工人。"},{"en":"If course delivery happens at flexible times, more students can fit learning around daily life.","zh":"如果課程授課時間靈活，更多學生可以把學習安排進日常生活。"},{"en":"This phrase focuses on scheduling.","zh":"這個片語聚焦於時間安排。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":4},{"front":"be convenient for","meaning":"對……方便","examples":[{"en":"The course schedule is convenient for many students.","zh":"課程時間表對許多學生方便。"},{"en":"To be convenient for someone means to fit their time, needs, or location easily.","zh":"be convenient for someone 指容易配合某人的時間、需要或地點。"},{"en":"A bus stop near home is convenient for children travelling to school.","zh":"家附近有巴士站，對上學的孩子很方便。"},{"en":"If lesson times are convenient, students are more likely to attend regularly.","zh":"如果上課時間方便，學生較有可能定期出席。"},{"en":"This phrase describes practical ease.","zh":"這個片語描述實際便利。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":4},{"front":"opportunity for learning","meaning":"學習機會","examples":[{"en":"This opportunity for learning has attracted both supporters and critics.","zh":"這個學習機會吸引了支持者和批評者。"},{"en":"An opportunity for learning is a chance to gain knowledge, skills, or qualifications.","zh":"opportunity for learning 是獲得知識、技能或資格的機會。"},{"en":"A free workshop can be an opportunity for learning for adults who left school early.","zh":"免費工作坊可以成為早年離校成年人學習的機會。"},{"en":"If new technology creates learning opportunities, more people may join education later in life.","zh":"如果新科技創造學習機會，更多人可能在人生較後階段加入教育。"},{"en":"This phrase focuses on access to education or growth.","zh":"這個片語聚焦於接觸教育或成長的機會。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":4},{"front":"not without its critics","meaning":"並非沒有批評者","examples":[{"en":"This opportunity for learning has not been without its critics.","zh":"這個學習機會並非沒有批評者。"},{"en":"Not without its critics means some people have criticised it, even if others support it.","zh":"not without its critics 指即使有人支持，仍有一些人批評它。"},{"en":"A new school uniform policy may be popular but not without its critics.","zh":"新校服政策可能受歡迎，但並非沒有批評者。"},{"en":"If distance learning grows quickly, critics may question its quality and fairness.","zh":"如果遙距學習快速增長，批評者可能質疑其質素和公平性。"},{"en":"This phrase politely introduces opposition.","zh":"這個片語禮貌地引入反對意見。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":4},{"front":"keep a close eye on","meaning":"密切留意","examples":[{"en":"Critics keep a close eye on the quality of instruction.","zh":"批評者密切留意教學質素。"},{"en":"To keep a close eye on something means to watch or monitor it carefully.","zh":"keep a close eye on something 指仔細觀察或監察某事。"},{"en":"Parents may keep a close eye on a child’s fever during the night.","zh":"父母可能在夜間密切留意孩子的發燒情況。"},{"en":"If a programme expands quickly, universities must monitor teaching quality carefully.","zh":"如果課程快速擴張，大學必須仔細監察教學質素。"},{"en":"This phrase suggests careful attention because problems may appear.","zh":"這個片語暗示因可能出現問題而需要仔細注意。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":4},{"front":"any form of teaching","meaning":"任何形式的教學","examples":[{"en":"Quality should be checked in any form of teaching.","zh":"任何形式的教學都應檢查質素。"},{"en":"Any form of teaching means every type of teaching method or setting.","zh":"any form of teaching 指每一種教學方法或環境。"},{"en":"Feedback matters in any form of teaching, whether online, face-to-face, or blended.","zh":"不論網上、面對面或混合式教學，回饋在任何形式的教學中都重要。"},{"en":"If teaching is poorly planned, students suffer regardless of the format.","zh":"如果教學計劃差，不論形式如何，學生都會受影響。"},{"en":"This phrase shows that quality concerns are not limited to one method.","zh":"這個片語顯示質素關注不限於某一方法。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":5},{"front":"quality issues","meaning":"質素問題","examples":[{"en":"Quality issues are a major concern in distance learning.","zh":"質素問題是遙距學習中的主要關注。"},{"en":"Quality issues are problems or questions about whether something meets acceptable standards.","zh":"quality issues 是關於某事是否達到可接受標準的問題或疑慮。"},{"en":"A restaurant may face quality issues if food tastes different every day.","zh":"如果餐廳食物每天味道不同，它可能面對質素問題。"},{"en":"If online courses lack feedback or support, quality issues may affect student success.","zh":"如果網上課程缺乏回饋或支援，質素問題可能影響學生成功。"},{"en":"This phrase refers to concerns about standards and reliability.","zh":"這個片語指關於標準和可靠性的關注。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":5},{"front":"a major concern for","meaning":"……的主要關注","examples":[{"en":"Quality issues are a major concern for distance-learning students.","zh":"質素問題是遙距學習學生的主要關注。"},{"en":"A major concern for someone is an important worry or problem for that person or group.","zh":"major concern for someone 是對某人或某群體而言重要的憂慮或問題。"},{"en":"Safety is a major concern for parents choosing a school bus service.","zh":"安全是家長選擇校巴服務時的主要關注。"},{"en":"If students pay for a degree online, they may worry whether the teaching is recognised and reliable.","zh":"如果學生付費修讀網上學位，他們可能擔心教學是否受認可和可靠。"},{"en":"This phrase identifies what matters most to a group.","zh":"這個片語指出某群體最重視的問題。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":5},{"front":"intend to pursue","meaning":"打算修讀","examples":[{"en":"Some students intend to pursue degree programmes through distance learning.","zh":"一些學生打算透過遙距學習修讀學位課程。"},{"en":"To intend to pursue something means to plan seriously to study, follow, or work toward it.","zh":"intend to pursue something 指認真計劃修讀、追求或努力達成某事。"},{"en":"A student may intend to pursue nursing after volunteering in a hospital.","zh":"學生在醫院做義工後，可能打算修讀護理。"},{"en":"If learners intend to pursue a degree online, they need reliable courses and clear support.","zh":"如果學習者打算網上修讀學位，他們需要可靠課程和清晰支援。"},{"en":"This phrase shows a planned educational or career goal.","zh":"這個片語顯示有計劃的教育或職業目標。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":5},{"front":"degree programmes","meaning":"學位課程","examples":[{"en":"Some learners pursue degree programmes through distance learning.","zh":"一些學習者透過遙距學習修讀學位課程。"},{"en":"Degree programmes are structured courses of study that lead to an academic degree.","zh":"degree programmes 是通向學術學位的有結構課程。"},{"en":"A university may offer degree programmes in business, nursing, engineering, and education.","zh":"大學可能提供商業、護理、工程和教育方面的學位課程。"},{"en":"If degree programmes are offered online, working adults may continue higher education.","zh":"如果學位課程在網上提供，工作的成年人可能繼續高等教育。"},{"en":"This phrase refers to formal study paths, not short casual courses.","zh":"這個片語指正式學習路徑，而不是短期休閒課程。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":5},{"front":"especially with","meaning":"尤其在……情況下","examples":[{"en":"Quality is a major concern, especially with the proliferation of programmes.","zh":"質素是主要關注，尤其在課程激增的情況下。"},{"en":"Especially with means particularly because of or in the situation involving something.","zh":"especially with 指尤其因為某事，或尤其在涉及某事的情況下。"},{"en":"School safety becomes a concern, especially with many young children arriving at the same time.","zh":"學校安全成為關注，尤其在許多年幼孩子同時抵達的情況下。"},{"en":"If many online courses appear quickly, quality control becomes especially important.","zh":"如果許多網上課程快速出現，質素控制便尤其重要。"},{"en":"This phrase highlights a condition that makes an issue more serious.","zh":"這個片語突出令問題更嚴重的條件。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":5},{"front":"proliferation of","meaning":"……的激增","examples":[{"en":"The proliferation of distance-learning programmes has raised quality concerns.","zh":"遙距學習課程的激增引起了質素關注。"},{"en":"Proliferation of something means a rapid increase in its number or spread.","zh":"proliferation of something 指某物數量或擴散快速增加。"},{"en":"The proliferation of delivery apps has changed how restaurants reach customers.","zh":"外賣應用程式的激增改變了餐廳接觸顧客的方式。"},{"en":"If programmes proliferate quickly, standards may become harder to monitor.","zh":"如果課程快速激增，標準可能變得更難監察。"},{"en":"This phrase often suggests growth that may be difficult to control.","zh":"這個片語常暗示增長可能難以控制。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":5},{"front":"agree on specific standards","meaning":"就具體標準達成共識","examples":[{"en":"Academics find it difficult to agree on specific standards.","zh":"學者發現很難就具體標準達成共識。"},{"en":"To agree on specific standards means to reach shared rules or measures for judging quality.","zh":"agree on specific standards 指達成共同規則或量度準則來判斷質素。"},{"en":"Teachers may need to agree on specific standards before marking essays fairly.","zh":"教師在公平批改文章前，可能需要就具體標準達成共識。"},{"en":"If universities cannot agree on standards, students may not know which online courses are reliable.","zh":"如果大學不能就標準達成共識，學生可能不知道哪些網上課程可靠。"},{"en":"This phrase highlights the need for common criteria.","zh":"這個片語突出共同準則的需要。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":5},{"front":"constitute quality","meaning":"構成質素","examples":[{"en":"Academics debate which standards constitute quality in distance learning.","zh":"學者辯論哪些標準構成遙距學習的質素。"},{"en":"To constitute quality means to be the elements that make something high-quality.","zh":"constitute quality 指成為令某事具有高質素的元素。"},{"en":"In a restaurant, fresh food, clean tables, and good service may constitute quality.","zh":"在餐廳中，新鮮食物、乾淨餐桌和良好服務可能構成質素。"},{"en":"If interaction, resources, and assessment are strong, they may help constitute quality in an online course.","zh":"如果互動、資源和評核都強，它們可能有助構成網上課程質素。"},{"en":"This phrase asks what features truly define quality.","zh":"這個片語詢問哪些特徵真正定義質素。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":5},{"front":"attributes such as","meaning":"例如……等特質","examples":[{"en":"Attributes such as accreditation standards can help measure quality.","zh":"例如認證標準等特質可以幫助量度質素。"},{"en":"Attributes such as means features or qualities like the examples that follow.","zh":"attributes such as 指例如後面所列的特徵或質素。"},{"en":"A good school may have attributes such as caring teachers, safe classrooms, and useful feedback.","zh":"好學校可能有例如關心學生的老師、安全課室和有用回饋等特質。"},{"en":"If a course has clear standards and strong support, these attributes can improve trust.","zh":"如果課程有清晰標準和強大支援，這些特質可以提高信任。"},{"en":"This phrase introduces examples of important features.","zh":"這個片語引入重要特徵的例子。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":5},{"front":"accreditation standards","meaning":"認證標準","examples":[{"en":"Accreditation standards are one criterion for quality.","zh":"認證標準是質素的一項準則。"},{"en":"Accreditation standards are official requirements used to judge whether an institution or programme meets recognised quality levels.","zh":"accreditation standards 是用來判斷院校或課程是否達到認可質素水平的官方要求。"},{"en":"A nursing school may need to meet accreditation standards before its graduates can be recognised.","zh":"護理學校可能需要達到認證標準，其畢業生才會獲認可。"},{"en":"If a course lacks accreditation, students may worry whether employers will accept it.","zh":"如果課程缺乏認證，學生可能擔心僱主是否接受它。"},{"en":"This phrase connects quality with official recognition.","zh":"這個片語把質素與官方認可連接起來。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":5},{"front":"evaluation of students’ experiences","meaning":"對學生經驗的評估","examples":[{"en":"Evaluation of students’ experiences is a valid quality criterion.","zh":"對學生經驗的評估是有效的質素準則。"},{"en":"Evaluation of students’ experiences means assessing how students feel, learn, interact, and receive support in a course.","zh":"evaluation of students’ experiences 指評估學生在課程中的感受、學習、互動和支援情況。"},{"en":"A university may collect surveys to evaluate whether students find online lessons clear and useful.","zh":"大學可能收集問卷，以評估學生是否覺得網上課堂清楚而有用。"},{"en":"If students report confusion or isolation, course designers may need to improve support.","zh":"如果學生反映困惑或孤立，課程設計者可能需要改善支援。"},{"en":"This phrase treats learners’ real experiences as evidence of quality.","zh":"這個片語把學習者真實經驗視為質素證據。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":6},{"front":"teacher-student interaction","meaning":"師生互動","examples":[{"en":"Teacher-student interaction affects the quality of distance learning.","zh":"師生互動影響遙距學習質素。"},{"en":"Teacher-student interaction means communication between teachers and learners, such as questions, feedback, and guidance.","zh":"teacher-student interaction 指教師與學習者之間的溝通，例如提問、回饋和指導。"},{"en":"A teacher replying to a student’s draft with detailed comments is an example of teacher-student interaction.","zh":"老師用詳細評語回覆學生初稿，就是師生互動的例子。"},{"en":"If interaction is weak, students may feel lost even when videos are available.","zh":"如果互動薄弱，即使有影片，學生也可能感到迷失。"},{"en":"This phrase focuses on communication between instructor and learner.","zh":"這個片語聚焦於教師與學習者之間的溝通。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":6},{"front":"student-to-student interaction","meaning":"學生之間的互動","examples":[{"en":"Student-to-student interaction is one quality criterion.","zh":"學生之間的互動是一項質素準則。"},{"en":"Student-to-student interaction means communication and collaboration among learners.","zh":"student-to-student interaction 指學習者之間的溝通和合作。"},{"en":"Students interact with one another when they discuss answers in an online forum.","zh":"學生在網上討論區討論答案時，就是彼此互動。"},{"en":"If learners share ideas and questions, they may feel less isolated in a distance course.","zh":"如果學習者分享想法和問題，他們在遙距課程中可能較不孤立。"},{"en":"This phrase focuses on peer learning and support.","zh":"這個片語聚焦於同儕學習和支援。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":6},{"front":"learning resources","meaning":"學習資源","examples":[{"en":"Learning resources for the learner are important in distance education.","zh":"給學習者的學習資源在遙距教育中很重要。"},{"en":"Learning resources are materials and tools that help students study, practise, and understand a subject.","zh":"learning resources 是幫助學生學習、練習和理解科目的材料和工具。"},{"en":"Videos, textbooks, worksheets, quizzes, and library databases can all be learning resources.","zh":"影片、教科書、工作紙、小測和圖書館資料庫都可以是學習資源。"},{"en":"If students lack learning resources, they may struggle to complete assignments independently.","zh":"如果學生缺乏學習資源，他們可能難以獨立完成作業。"},{"en":"This phrase refers to the support materials students use to learn.","zh":"這個片語指學生用來學習的支援材料。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":6},{"front":"learner assessment and performance","meaning":"學習者評核與表現","examples":[{"en":"Learner assessment and performance help determine quality.","zh":"學習者評核與表現有助決定質素。"},{"en":"Learner assessment and performance means how students are evaluated and how well they actually do.","zh":"learner assessment and performance 指學生如何被評估，以及他們實際表現如何。"},{"en":"A course may assess learners through exams, projects, presentations, and lab reports.","zh":"課程可能透過考試、專題、匯報和實驗報告評估學習者。"},{"en":"If assessment is fair and performance improves, the course is more likely to be judged effective.","zh":"如果評核公平且表現改善，課程較可能被判定有效。"},{"en":"This phrase links testing methods with learning results.","zh":"這個片語把測試方法與學習結果連接起來。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":6},{"front":"instructional resources","meaning":"教學資源","examples":[{"en":"Faculty need instructional resources for effective teaching.","zh":"教員需要教學資源以進行有效教學。"},{"en":"Instructional resources are materials and tools teachers use to design and deliver instruction.","zh":"instructional resources 是教師用來設計和傳授教學的材料和工具。"},{"en":"Lesson plans, slides, lab videos, marking guides, and software can be instructional resources.","zh":"教案、簡報、實驗影片、評分指引和軟件都可以是教學資源。"},{"en":"If teachers lack instructional resources, even knowledgeable teachers may struggle to teach online effectively.","zh":"如果教師缺乏教學資源，即使知識豐富，也可能難以有效進行網上教學。"},{"en":"This phrase refers to resources for teachers, not only students.","zh":"這個片語指給教師使用的資源，而不只是給學生。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":6},{"front":"faculty training","meaning":"教員培訓","examples":[{"en":"Faculty training is one factor in quality distance education.","zh":"教員培訓是優質遙距教育的一個因素。"},{"en":"Faculty training means professional preparation that helps teachers or university staff teach more effectively.","zh":"faculty training 指幫助教師或大學職員更有效教學的專業準備。"},{"en":"A university may offer faculty training on using video tools and designing online assessments.","zh":"大學可能提供關於使用視像工具和設計網上評核的教員培訓。"},{"en":"If faculty are not trained, they may simply upload notes without creating real learning activities.","zh":"如果教員沒有受訓，他們可能只是上載筆記，而沒有創造真正學習活動。"},{"en":"This phrase focuses on preparing teachers for good instruction.","zh":"這個片語聚焦於為良好教學準備教師。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":6},{"front":"learner satisfaction","meaning":"學習者滿意度","examples":[{"en":"Learner satisfaction is a valid criterion for evaluating distance learning.","zh":"學習者滿意度是評估遙距學習的有效準則。"},{"en":"Learner satisfaction means how pleased students are with the course, support, teaching, and learning experience.","zh":"learner satisfaction 指學生對課程、支援、教學和學習經驗的滿意程度。"},{"en":"A student survey can measure learner satisfaction after an online course ends.","zh":"網上課程結束後，學生問卷可以量度學習者滿意度。"},{"en":"If learner satisfaction is low, students may drop out or warn others not to enrol.","zh":"如果學習者滿意度低，學生可能退學或提醒別人不要報讀。"},{"en":"This phrase focuses on students’ judgement of their learning experience.","zh":"這個片語聚焦於學生對學習經驗的評價。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":6},{"front":"valid criteria","meaning":"有效準則","examples":[{"en":"These attributes are valid criteria for judging quality.","zh":"這些特質是判斷質素的有效準則。"},{"en":"Valid criteria are fair and acceptable standards used to judge or measure something.","zh":"valid criteria 是用來判斷或量度某事的公平而可接受標準。"},{"en":"Attendance, progress, and feedback may be valid criteria for evaluating a course.","zh":"出席率、進步和回饋可能是評估課程的有效準則。"},{"en":"If criteria are valid, they measure what truly matters rather than surface appearances.","zh":"如果準則有效，它們量度真正重要的東西，而不是表面外觀。"},{"en":"This phrase refers to standards that can reasonably support a judgement.","zh":"這個片語指能合理支持判斷的標準。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":6},{"front":"determine the quality of","meaning":"決定……的質素","examples":[{"en":"Many factors determine the quality of instruction.","zh":"許多因素決定教學質素。"},{"en":"To determine the quality of something means to decide or strongly influence how good it is.","zh":"determine the quality of something 指決定或強烈影響某事有多好。"},{"en":"Teacher preparation, class size, and feedback can determine the quality of a lesson.","zh":"教師準備、班級大小和回饋可以決定一堂課的質素。"},{"en":"If course design is weak, the quality of instruction may suffer even with good technology.","zh":"如果課程設計薄弱，即使科技良好，教學質素也可能受損。"},{"en":"This phrase identifies what shapes standards or results.","zh":"這個片語指出甚麼塑造標準或結果。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":6},{"front":"both distance and face-to-face classrooms","meaning":"遙距和面對面課堂兩者","examples":[{"en":"Quality matters in both distance and face-to-face classrooms.","zh":"質素在遙距和面對面課堂兩者中都重要。"},{"en":"Both distance and face-to-face classrooms means remote learning settings and physical classroom settings together.","zh":"both distance and face-to-face classrooms 指遙距學習環境和實體課堂環境兩者。"},{"en":"Feedback is important in both distance and face-to-face classrooms because students need to know how to improve.","zh":"回饋在遙距和面對面課堂兩者中都重要，因為學生需要知道如何改善。"},{"en":"If quality is weak, students suffer whether they learn online or in person.","zh":"如果質素薄弱，不論學生網上學習還是親身上課，都會受影響。"},{"en":"This phrase shows that the issue applies to two teaching formats.","zh":"這個片語顯示問題適用於兩種教學形式。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":6},{"front":"laboratory course delivery","meaning":"實驗課程傳授","examples":[{"en":"The passage discusses innovation in laboratory course delivery.","zh":"文章討論實驗課程傳授方面的創新。"},{"en":"Laboratory course delivery means the way practical lab-based courses are provided to students.","zh":"laboratory course delivery 指實踐實驗課程提供給學生的方式。"},{"en":"A university may improve laboratory course delivery by using videos before students enter the lab.","zh":"大學可能透過學生進入實驗室前使用影片來改善實驗課程傳授。"},{"en":"If lab delivery changes, students may gain practical experience through virtual labs, summer schools, or field trips.","zh":"如果實驗課程傳授方式改變，學生可能透過虛擬實驗室、暑期學校或實地考察獲得實踐經驗。"},{"en":"This phrase focuses on how lab teaching is organised and delivered.","zh":"這個片語聚焦於實驗教學如何組織和傳授。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":7},{"front":"a selected UK university","meaning":"一所被選中的英國大學","examples":[{"en":"A selected UK university used several instructional technologies.","zh":"一所被選中的英國大學使用了幾種教學科技。"},{"en":"A selected UK university means one particular university in the United Kingdom chosen for study or discussion.","zh":"selected UK university 指一所被選作研究或討論對象的特定英國大學。"},{"en":"Researchers may examine a selected school to understand how a new teaching method works in practice.","zh":"研究人員可能檢視一所被選中的學校，以了解新教學方法如何在實際中運作。"},{"en":"If one selected university uses many technologies, it can provide a detailed case study.","zh":"如果一所被選中的大學使用多種科技，它可以提供詳細個案研究。"},{"en":"This phrase identifies a specific institution without naming it.","zh":"這個片語指出一所特定院校，但沒有命名。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":7},{"front":"offer laboratory courses","meaning":"提供實驗課程","examples":[{"en":"Five departments offered laboratory courses through distance learning.","zh":"五個學系透過遙距學習提供實驗課程。"},{"en":"To offer laboratory courses means to make practical lab-based courses available to students.","zh":"offer laboratory courses 指向學生提供以實驗為基礎的實踐課程。"},{"en":"A science faculty may offer laboratory courses in chemistry, biology, and physics.","zh":"科學院可能提供化學、生物和物理實驗課程。"},{"en":"If departments offer lab courses remotely, they must plan equipment, safety, and assessment carefully.","zh":"如果學系遙距提供實驗課程，就必須仔細規劃設備、安全和評核。"},{"en":"This phrase describes making practical courses available.","zh":"這個片語描述提供實踐課程。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":7},{"front":"technology and engineering","meaning":"科技和工程學","examples":[{"en":"The courses were in technology and engineering.","zh":"這些課程屬於科技和工程學。"},{"en":"Technology and engineering are fields concerned with tools, systems, machines, design, and practical problem-solving.","zh":"technology and engineering 是關於工具、系統、機械、設計和實踐解難的領域。"},{"en":"A student interested in robots may study technology and engineering at university.","zh":"對機械人有興趣的學生可能在大學修讀科技和工程學。"},{"en":"If courses involve technology and engineering, practical skills and experiments often matter.","zh":"如果課程涉及科技和工程學，實踐技能和實驗通常很重要。"},{"en":"This phrase identifies applied technical subjects.","zh":"這個片語指出應用技術科目。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":7},{"front":"combinations of","meaning":"……的組合","examples":[{"en":"The departments used combinations of various instructional technologies.","zh":"這些學系使用各種教學科技的組合。"},{"en":"Combinations of something are mixtures or groupings of different things used together.","zh":"combinations of something 是幾種不同事物一起使用的混合或配搭。"},{"en":"A teacher may use combinations of videos, worksheets, and discussions in one lesson.","zh":"老師可能在一堂課中使用影片、工作紙和討論的組合。"},{"en":"If one technology cannot meet every need, combinations of tools may support learning better.","zh":"如果一種科技不能滿足所有需要，工具組合可能更好地支援學習。"},{"en":"This phrase shows that several elements are joined.","zh":"這個片語顯示幾個元素被結合起來。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":7},{"front":"various instructional technologies","meaning":"各種教學科技","examples":[{"en":"The university used various instructional technologies.","zh":"這所大學使用了各種教學科技。"},{"en":"Various instructional technologies are different tools used to support teaching and learning.","zh":"various instructional technologies 是用來支援教學和學習的不同工具。"},{"en":"A school may use learning platforms, video lessons, quiz apps, and digital whiteboards as instructional technologies.","zh":"學校可能使用學習平台、影片課堂、小測應用程式和電子白板作為教學科技。"},{"en":"If teachers use several technologies wisely, lessons can become more flexible and interactive.","zh":"如果教師明智使用幾種科技，課堂可以變得更靈活和互動。"},{"en":"This phrase refers to multiple teaching tools, not one device.","zh":"這個片語指多種教學工具，而不是單一裝置。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":7},{"front":"interactive microwave television","meaning":"互動微波電視","examples":[{"en":"Interactive microwave television provided two-way audio and video.","zh":"互動微波電視提供雙向音訊和視像。"},{"en":"Interactive microwave television is a communication system that uses microwave signals to connect teachers and students with audio and video.","zh":"interactive microwave television 是使用微波訊號，以音訊和視像連接教師與學生的通訊系統。"},{"en":"Before modern video calls, some institutions used interactive television to link remote classrooms.","zh":"在現代視像通話之前，一些院校使用互動電視連接遙距課室。"},{"en":"If students can see and hear the teacher live, distance teaching becomes more immediate.","zh":"如果學生能即時看見和聽見老師，遙距教學會變得更即時。"},{"en":"This phrase refers to an older technology for live remote instruction.","zh":"這個片語指用於即時遙距教學的較早期科技。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":7},{"front":"two-way audio and video","meaning":"雙向音訊和視像","examples":[{"en":"The technology allowed two-way audio and video.","zh":"該科技容許雙向音訊和視像。"},{"en":"Two-way audio and video means both sides can hear and see each other.","zh":"two-way audio and video 指雙方都能聽見和看見彼此。"},{"en":"A video call uses two-way audio and video when both teacher and student can speak and appear on screen.","zh":"當老師和學生都能說話並出現在螢幕上，視像通話便使用雙向音訊和視像。"},{"en":"If communication is two-way, students can ask questions instead of only watching passively.","zh":"如果溝通是雙向的，學生可以提問，而不只是被動觀看。"},{"en":"This phrase describes live interaction through sound and image.","zh":"這個片語描述透過聲音和影像進行即時互動。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":7},{"front":"compressed video","meaning":"壓縮視像","examples":[{"en":"Compressed video was one of the technologies used.","zh":"壓縮視像是所使用的科技之一。"},{"en":"Compressed video is video data reduced in size so it can be stored or transmitted more easily.","zh":"compressed video 是被縮小數據量，以便更容易儲存或傳送的視像。"},{"en":"A school may use compressed video so students can watch lessons even with slower Internet.","zh":"學校可能使用壓縮視像，讓學生即使網速較慢也能觀看課堂。"},{"en":"If video files are too large, compression helps deliver them without long delays.","zh":"如果視像檔案太大，壓縮有助在不長時間延誤下傳送。"},{"en":"This phrase refers to video that has been made smaller for practical use.","zh":"這個片語指為實際使用而縮小的視像。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":7},{"front":"computer software","meaning":"電腦軟件","examples":[{"en":"Computer software supported virtual laboratory learning.","zh":"電腦軟件支援虛擬實驗室學習。"},{"en":"Computer software means programs or applications that tell a computer what to do.","zh":"computer software 指告訴電腦做甚麼的程式或應用程式。"},{"en":"Students may use computer software to write essays, draw graphs, or simulate experiments.","zh":"學生可能使用電腦軟件寫文章、繪圖表或模擬實驗。"},{"en":"If software is well designed, it can guide learners through difficult tasks step by step.","zh":"如果軟件設計良好，它可以一步一步引導學習者完成困難任務。"},{"en":"This phrase refers to digital programs, not the physical computer itself.","zh":"這個片語指數碼程式，而不是實體電腦本身。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":7},{"front":"virtual software","meaning":"虛擬軟件","examples":[{"en":"Virtual software was used in laboratory course delivery.","zh":"虛擬軟件被用於實驗課程傳授。"},{"en":"Virtual software is computer software that creates a simulated environment or activity.","zh":"virtual software 是創造模擬環境或活動的電腦軟件。"},{"en":"A driving school may use virtual software to let learners practise road situations safely.","zh":"駕駛學校可能使用虛擬軟件，讓學員安全練習道路情境。"},{"en":"If experiments are dangerous or expensive, virtual software can let students practise before using real equipment.","zh":"如果實驗危險或昂貴，虛擬軟件可以讓學生先練習，再使用真實設備。"},{"en":"This phrase refers to software that imitates real-world experience.","zh":"這個片語指模仿真實世界經驗的軟件。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":7},{"front":"videotapes","meaning":"錄影帶","examples":[{"en":"Videotapes were used as instructional materials.","zh":"錄影帶被用作教學材料。"},{"en":"Videotapes are recorded video materials stored on tape, commonly used before digital video became normal.","zh":"videotapes 是儲存在磁帶上的錄影材料，在數碼影片普及前常被使用。"},{"en":"A school might once have used videotapes to show science demonstrations in class.","zh":"學校以前可能使用錄影帶在課堂展示科學示範。"},{"en":"If a demonstration is recorded on videotape, students can watch it even when the teacher is not present.","zh":"如果示範被錄在錄影帶上，學生即使老師不在場也能觀看。"},{"en":"This phrase refers to an older form of video teaching material.","zh":"這個片語指較舊形式的影片教學材料。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":8},{"front":"interviews were conducted on-site","meaning":"訪問在現場進行","examples":[{"en":"Interviews were conducted on-site with faculty and staff.","zh":"研究人員在現場與教員和職員進行訪問。"},{"en":"Interviews were conducted on-site means the interviews were carried out at the actual location being studied.","zh":"interviews were conducted on-site 指訪問在被研究的實際地點進行。"},{"en":"Researchers may conduct interviews on-site at a hospital to understand nurses’ daily work.","zh":"研究人員可能在醫院現場進行訪問，以了解護士日常工作。"},{"en":"If interviews happen on-site, researchers can also observe the environment directly.","zh":"如果訪問在現場進行，研究人員也可以直接觀察環境。"},{"en":"This phrase describes where the research interviews took place.","zh":"這個片語描述研究訪問發生的地點。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":8},{"front":"faculty and staff","meaning":"教員和職員","examples":[{"en":"Researchers interviewed faculty and staff at the university.","zh":"研究人員訪問了該大學的教員和職員。"},{"en":"Faculty and staff means teaching academics and non-teaching employees who work at an institution.","zh":"faculty and staff 指在院校工作的教學學者和非教學僱員。"},{"en":"A university meeting may include faculty and staff from departments, libraries, and student services.","zh":"大學會議可能包括來自學系、圖書館和學生服務的教員和職員。"},{"en":"If researchers speak to both faculty and staff, they can understand teaching and administration more fully.","zh":"如果研究人員同時訪問教員和職員，他們可以更全面理解教學和行政。"},{"en":"This phrase refers to the people who work inside an institution.","zh":"這個片語指在院校內工作的人。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":8},{"front":"observe a wide range of","meaning":"觀察廣泛的……","examples":[{"en":"Researchers observed a wide range of teaching materials.","zh":"研究人員觀察了廣泛的教學材料。"},{"en":"To observe a wide range of something means to examine many different types or examples of it.","zh":"observe a wide range of something 指檢視某物的許多不同類型或例子。"},{"en":"A school inspector may observe a wide range of lessons before judging teaching quality.","zh":"學校督學在判斷教學質素前，可能觀察廣泛的課堂。"},{"en":"If researchers observe many materials, their findings may be more balanced.","zh":"如果研究人員觀察許多材料，其結果可能更平衡。"},{"en":"This phrase shows that evidence was collected from varied sources.","zh":"這個片語顯示證據來自不同來源。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":8},{"front":"teaching materials","meaning":"教學材料","examples":[{"en":"Researchers examined teaching materials and student portfolios.","zh":"研究人員檢視了教學材料和學生作品集。"},{"en":"Teaching materials are resources used to support instruction, such as notes, slides, videos, worksheets, and lab guides.","zh":"teaching materials 是用來支援教學的資源，例如筆記、簡報、影片、工作紙和實驗指引。"},{"en":"A teacher may prepare teaching materials before class so students can practise immediately.","zh":"老師可能在課前準備教學材料，讓學生可以立即練習。"},{"en":"If teaching materials are unclear, students may struggle even if the teacher explains well.","zh":"如果教學材料不清晰，即使老師解釋得好，學生仍可能學得吃力。"},{"en":"This phrase refers to materials used for teaching and learning.","zh":"這個片語指用於教學和學習的材料。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":8},{"front":"student portfolios","meaning":"學生作品集","examples":[{"en":"Student portfolios were part of the materials observed.","zh":"學生作品集是被觀察材料的一部分。"},{"en":"Student portfolios are collections of a student’s work that show learning, progress, and achievement.","zh":"student portfolios 是收集學生作品，以展示學習、進步和成就的資料集。"},{"en":"An art student’s portfolio may include sketches, finished pieces, and reflections.","zh":"藝術學生的作品集可能包括草圖、完成作品和反思。"},{"en":"If portfolios are reviewed, teachers can see development over time, not just one exam result.","zh":"如果作品集被檢視，教師可以看到隨時間發展的情況，而不只是一次考試結果。"},{"en":"This phrase refers to organised evidence of student work.","zh":"這個片語指有組織的學生作品證據。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":8},{"front":"secure website","meaning":"安全網站","examples":[{"en":"The university used a secure website for course delivery.","zh":"該大學使用安全網站進行課程傳授。"},{"en":"A secure website is a website designed to protect users’ data and control access safely.","zh":"secure website 是設計用來保護使用者資料並安全控制進入權限的網站。"},{"en":"A bank uses a secure website so customers can check accounts without exposing private information.","zh":"銀行使用安全網站，讓客戶可以查看帳戶而不暴露私人資料。"},{"en":"If a course website is secure, students can submit assignments and access materials more safely.","zh":"如果課程網站安全，學生可以更安全地提交作業和取用教材。"},{"en":"This phrase focuses on online safety and restricted access.","zh":"這個片語聚焦於網上安全和受限制的進入權限。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":8},{"front":"in addition to","meaning":"除了……之外","examples":[{"en":"In addition to the Internet, the university used other methods.","zh":"除了互聯網之外，該大學還使用其他方法。"},{"en":"In addition to means as well as or besides something already mentioned.","zh":"in addition to 指除了已提及的某事之外，也包括其他事。"},{"en":"In addition to textbooks, students may use videos and practice quizzes.","zh":"除了教科書之外，學生也可能使用影片和練習小測。"},{"en":"If a course uses several methods in addition to online lessons, it may support more learning styles.","zh":"如果課程除了網上課堂之外使用幾種方法，它可能支援更多學習風格。"},{"en":"This phrase adds another element to a list or idea.","zh":"這個片語在列表或想法中加入另一元素。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":8},{"front":"innovative ways to deliver","meaning":"創新方式去提供……","examples":[{"en":"The university used innovative ways to deliver laboratory courses.","zh":"該大學使用創新方式去提供實驗課程。"},{"en":"Innovative ways to deliver something are new methods for providing it effectively.","zh":"innovative ways to deliver something 是有效提供某事的新方法。"},{"en":"A clinic may use mobile vans as an innovative way to deliver healthcare in remote villages.","zh":"診所可能使用流動車作為創新方式，向偏遠村莊提供醫療服務。"},{"en":"If universities use videos, websites, and residential schools together, they can deliver practical courses more flexibly.","zh":"如果大學結合影片、網站和住宿學校，它們可以更靈活地提供實踐課程。"},{"en":"This phrase highlights new methods of providing a service or course.","zh":"這個片語突出提供服務或課程的新方法。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":8},{"front":"residential and summer schools","meaning":"住宿學校和暑期學校","examples":[{"en":"Residential and summer schools support distance-learning laboratory courses.","zh":"住宿學校和暑期學校支援遙距學習實驗課程。"},{"en":"Residential and summer schools are short periods of in-person study where students attend practical sessions away from normal distance learning.","zh":"residential and summer schools 是短期面授學習時段，學生離開平常遙距學習模式參加實踐課節。"},{"en":"A distance-learning student may attend a summer school to complete lab work with real equipment.","zh":"遙距學習學生可能參加暑期學校，使用真實設備完成實驗工作。"},{"en":"If online study cannot provide every practical experience, residential schools can fill part of the gap.","zh":"如果網上學習不能提供所有實踐經驗，住宿學校可以填補部分缺口。"},{"en":"This phrase refers to temporary face-to-face study periods within distance education.","zh":"這個片語指遙距教育中的臨時面對面學習時段。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":8},{"front":"serve a similar purpose","meaning":"發揮相似作用","examples":[{"en":"Residential and summer schools serve a similar purpose.","zh":"住宿學校和暑期學校發揮相似作用。"},{"en":"To serve a similar purpose means to be used for nearly the same reason or function.","zh":"serve a similar purpose 指被用於差不多相同的原因或功能。"},{"en":"A bus pass and a train card may serve a similar purpose if both help students travel to school.","zh":"如果巴士通行證和火車卡都幫助學生上學，它們可能發揮相似作用。"},{"en":"If two teaching activities both give practical experience, they may serve similar purposes.","zh":"如果兩種教學活動都提供實踐經驗，它們可能發揮相似作用。"},{"en":"This phrase compares functions, not exact form.","zh":"這個片語比較功能，而不是完全相同的形式。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":8},{"front":"the difference is","meaning":"分別在於","examples":[{"en":"The difference is the duration.","zh":"分別在於持續時間。"},{"en":"The difference is means the main thing that separates two items or situations is about to be stated.","zh":"the difference is 指即將說明區分兩件事或兩種情況的主要地方。"},{"en":"Both courses teach grammar; the difference is that one is online and the other is face-to-face.","zh":"兩個課程都教授文法；分別在於一個是網上，一個是面授。"},{"en":"If two programmes serve similar purposes, the difference may lie in time, cost, or location.","zh":"如果兩個課程發揮相似作用，分別可能在時間、成本或地點。"},{"en":"This phrase introduces a clear point of contrast.","zh":"這個片語引入清楚的對比點。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":9},{"front":"duration","meaning":"持續時間","examples":[{"en":"The main difference between the schools is the duration.","zh":"這些學校之間的主要分別是持續時間。"},{"en":"Duration means the length of time something lasts.","zh":"duration 指某事持續多久。"},{"en":"The duration of a lesson may be forty minutes, one hour, or two hours.","zh":"一堂課的持續時間可能是四十分鐘、一小時或兩小時。"},{"en":"If the duration is too short, students may not have enough time to practise.","zh":"如果持續時間太短，學生可能沒有足夠時間練習。"},{"en":"This word focuses on time length.","zh":"這個詞聚焦於時間長度。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":9},{"front":"one week long","meaning":"為期一星期","examples":[{"en":"The summer school is one week long.","zh":"暑期學校為期一星期。"},{"en":"One week long means lasting for seven days or roughly one full week.","zh":"one week long 指持續七天或大約一整星期。"},{"en":"A training camp may be one week long so participants can practise every day.","zh":"培訓營可能為期一星期，讓參加者每天練習。"},{"en":"If a course is only one week long, the schedule may be intensive.","zh":"如果課程只為期一星期，時間表可能很密集。"},{"en":"This phrase describes the duration of an activity.","zh":"這個片語描述活動的持續時間。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":9},{"front":"combine labs, lectures and problem sessions","meaning":"結合實驗、講課和解題課","examples":[{"en":"The summer school combines labs, lectures and problem sessions.","zh":"暑期學校結合實驗、講課和解題課。"},{"en":"To combine labs, lectures and problem sessions means to include practical work, teaching talks, and guided problem-solving in one programme.","zh":"combine labs, lectures and problem sessions 指在一個課程中包括實踐工作、講課和指導式解題。"},{"en":"A science course may combine experiments, teacher explanations, and practice questions.","zh":"科學課程可能結合實驗、教師解釋和練習題。"},{"en":"If a course combines different activities, students can learn concepts and apply them immediately.","zh":"如果課程結合不同活動，學生可以學習概念並立即應用。"},{"en":"This phrase shows a mixed teaching structure.","zh":"這個片語顯示混合式教學結構。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":9},{"front":"key opportunities","meaning":"主要機會","examples":[{"en":"The schools provide four key opportunities for students.","zh":"這些學校為學生提供四個主要機會。"},{"en":"Key opportunities are important chances to do something useful or valuable.","zh":"key opportunities 是做有用或有價值事情的重要機會。"},{"en":"A summer internship may provide key opportunities to meet employers and practise workplace skills.","zh":"暑期實習可能提供認識僱主和練習職場技能的主要機會。"},{"en":"If a school offers lab work and study trips, students gain opportunities they cannot get from videos alone.","zh":"如果學校提供實驗工作和學習考察，學生便得到單靠影片不能提供的機會。"},{"en":"This phrase highlights the most important benefits.","zh":"這個片語突出最重要的好處。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":9},{"front":"undertake experimental work","meaning":"進行實驗工作","examples":[{"en":"Students undertake experimental work during the school.","zh":"學生在學校期間進行實驗工作。"},{"en":"To undertake experimental work means to carry out practical tests, measurements, or investigations.","zh":"undertake experimental work 指進行實踐測試、測量或調查。"},{"en":"A biology student may undertake experimental work by testing how light affects plant growth.","zh":"生物學生可能透過測試光線如何影響植物生長來進行實驗工作。"},{"en":"If students undertake experiments directly, they can learn from mistakes and real observations.","zh":"如果學生直接進行實驗，他們可以從錯誤和真實觀察中學習。"},{"en":"This phrase describes actively doing experiments, not only watching them.","zh":"這個片語描述主動做實驗，而不只是觀看。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":9},{"front":"be considered too hazardous","meaning":"被認為太危險","examples":[{"en":"Some experimental work is considered too hazardous for home study.","zh":"一些實驗工作被認為對家中學習而言太危險。"},{"en":"To be considered too hazardous means to be judged too dangerous to do safely in a certain setting.","zh":"be considered too hazardous 指被判定在某環境中安全進行風險太高。"},{"en":"Mixing strong chemicals may be considered too hazardous for a school club without supervision.","zh":"在沒有監督的學校社團中混合強烈化學品，可能被認為太危險。"},{"en":"If an activity is too hazardous at home, students may need to do it in a supervised lab.","zh":"如果活動在家中太危險，學生可能需要在受監督的實驗室進行。"},{"en":"This phrase links risk with limits on where work can be done.","zh":"這個片語把風險與工作可在哪裡進行的限制連接起來。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":9},{"front":"working at home","meaning":"在家工作；在家學習","examples":[{"en":"Some experiments are too hazardous for a student working at home.","zh":"一些實驗對在家學習的學生而言太危險。"},{"en":"Working at home means doing study or work tasks from one’s home rather than in an institution or workplace.","zh":"working at home 指在家而不是在院校或工作場所完成學習或工作任務。"},{"en":"A student working at home may complete online assignments at the kitchen table.","zh":"在家學習的學生可能在廚房桌上完成網上作業。"},{"en":"If a task needs special equipment or supervision, working at home may not be suitable.","zh":"如果任務需要特殊設備或監督，在家工作或學習可能不合適。"},{"en":"This phrase describes the setting where the person works or studies.","zh":"這個片語描述人工作或學習的地點。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":9},{"front":"undertake lab work","meaning":"進行實驗室工作","examples":[{"en":"Students undertake lab work using sophisticated equipment.","zh":"學生使用先進設備進行實驗室工作。"},{"en":"To undertake lab work means to carry out practical tasks in a laboratory.","zh":"undertake lab work 指在實驗室中進行實踐任務。"},{"en":"Medical students may undertake lab work to learn how to handle samples safely.","zh":"醫科學生可能進行實驗室工作，學習如何安全處理樣本。"},{"en":"If students undertake lab work, they gain practical skills that cannot be fully learned from reading.","zh":"如果學生進行實驗室工作，他們會獲得不能完全從閱讀中學到的實踐技能。"},{"en":"This phrase refers to doing laboratory activities directly.","zh":"這個片語指直接進行實驗室活動。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":9},{"front":"sophisticated equipment","meaning":"先進設備","examples":[{"en":"Students use more sophisticated equipment at the school.","zh":"學生在學校使用更先進的設備。"},{"en":"Sophisticated equipment is advanced, complex, or high-quality equipment designed for specialised tasks.","zh":"sophisticated equipment 是為專門任務設計的先進、複雜或高質素設備。"},{"en":"A hospital uses sophisticated equipment to scan the brain and monitor heart activity.","zh":"醫院使用先進設備掃描腦部和監測心臟活動。"},{"en":"If equipment is sophisticated, students usually need training and supervision before using it.","zh":"如果設備先進，學生通常需要訓練和監督才能使用。"},{"en":"This phrase describes tools that are more advanced than ordinary home equipment.","zh":"這個片語描述比普通家用設備更高級的工具。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":9},{"front":"too expensive to provide at home","meaning":"太昂貴而不能在家提供","examples":[{"en":"Some equipment is too expensive to provide at home.","zh":"一些設備太昂貴而不能在家提供。"},{"en":"Too expensive to provide at home means the cost is too high for students to have the equipment in their own homes.","zh":"too expensive to provide at home 指成本太高，學生無法在自己家中擁有該設備。"},{"en":"A flight simulator may be too expensive to provide at home for every trainee pilot.","zh":"飛行模擬器可能太昂貴，不能為每位見習機師在家提供。"},{"en":"If equipment is costly, universities may ask students to use it during a residential course instead.","zh":"如果設備昂貴，大學可能要求學生在住宿課程期間使用它。"},{"en":"This phrase explains why some practical work still needs shared facilities.","zh":"這個片語解釋為何一些實踐工作仍需要共享設施。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":9},{"front":"assessed lab work","meaning":"計分實驗室工作","examples":[{"en":"Students can undertake assessed lab work during the school.","zh":"學生可以在學校期間進行計分實驗室工作。"},{"en":"Assessed lab work is laboratory work that is marked or evaluated for a course grade.","zh":"assessed lab work 是會被批改或評估並計入課程成績的實驗室工作。"},{"en":"A chemistry student may submit measurements and a report for assessed lab work.","zh":"化學學生可能提交測量數據和報告作為計分實驗室工作。"},{"en":"If lab work is assessed in person, teachers can judge both technique and results directly.","zh":"如果實驗室工作被親身評核，教師可以直接判斷技巧和結果。"},{"en":"This phrase combines practical work with formal evaluation.","zh":"這個片語結合實踐工作與正式評估。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":10},{"front":"work together with fellow students","meaning":"與同學一起工作","examples":[{"en":"The schools allow students to work together with fellow students.","zh":"這些學校容許學生與同學一起工作。"},{"en":"To work together with fellow students means to collaborate with classmates or other learners.","zh":"work together with fellow students 指與同班同學或其他學習者合作。"},{"en":"Students may work together with fellow students on a group experiment or presentation.","zh":"學生可能與同學一起進行小組實驗或匯報。"},{"en":"If distance learners meet in person, teamwork can reduce isolation and improve confidence.","zh":"如果遙距學習者親身見面，團隊合作可以減少孤立感並提升信心。"},{"en":"This phrase highlights peer collaboration.","zh":"這個片語突出同儕合作。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":10},{"front":"arrange to take students on","meaning":"安排帶學生參加……","examples":[{"en":"Some courses arrange to take students on a study trip.","zh":"一些課程安排帶學生參加學習考察。"},{"en":"To arrange to take students on something means to organise an educational visit or activity for students.","zh":"arrange to take students on something 指為學生組織教育性參觀或活動。"},{"en":"A geography teacher may arrange to take students on a field trip to a river.","zh":"地理老師可能安排帶學生參加到河流的實地考察。"},{"en":"If a course arranges visits, students can see real examples outside the classroom.","zh":"如果課程安排參觀，學生可以在課室外看到真實例子。"},{"en":"This phrase focuses on planning a guided student activity.","zh":"這個片語聚焦於規劃有指導的學生活動。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":10},{"front":"study trip","meaning":"考察旅行；學習考察","examples":[{"en":"Some courses take students on a study trip.","zh":"一些課程帶學生參加學習考察。"},{"en":"A study trip is an educational visit where students learn from real places, people, or processes.","zh":"study trip 是學生從真實地方、人物或過程中學習的教育性參觀。"},{"en":"A business class may go on a study trip to a factory to see production in practice.","zh":"商科班可能到工廠學習考察，觀察實際生產。"},{"en":"If students visit a real workplace, they can connect theory with practical experience.","zh":"如果學生參觀真實工作場所，他們可以把理論與實踐經驗連接起來。"},{"en":"This phrase refers to learning outside the normal classroom.","zh":"這個片語指正常課室以外的學習。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":10},{"front":"special processes","meaning":"特殊工序","examples":[{"en":"Students may visit a company with special processes.","zh":"學生可能參觀有特殊工序的公司。"},{"en":"Special processes are unusual, technical, or important procedures used to produce or manage something.","zh":"special processes 是用來生產或管理某事物的不尋常、技術性或重要程序。"},{"en":"A food factory may have special processes for keeping products clean and safe.","zh":"食品工廠可能有保持產品清潔和安全的特殊工序。"},{"en":"If students see special processes in a workplace, they understand how theory is applied in real life.","zh":"如果學生在工作場所看到特殊工序，他們就能理解理論如何在現實中應用。"},{"en":"This phrase refers to processes worth observing because they are distinctive or important.","zh":"這個片語指因獨特或重要而值得觀察的工序。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":10},{"front":"geographic site of interest","meaning":"有研究價值的地理地點","examples":[{"en":"Students may visit a geographic site of interest.","zh":"學生可能參觀有研究價值的地理地點。"},{"en":"A geographic site of interest is a place that is important or useful for studying geography.","zh":"geographic site of interest 是對地理學習重要或有用的地方。"},{"en":"A river bend, cliff, wetland, or volcanic landscape can be a geographic site of interest.","zh":"河曲、峭壁、濕地或火山景觀都可以是有研究價值的地理地點。"},{"en":"If students visit such a site, they can observe landforms and processes directly.","zh":"如果學生參觀這類地點，他們可以直接觀察地貌和過程。"},{"en":"This phrase refers to a real location with educational value in geography.","zh":"這個片語指在地理方面有教育價值的真實地點。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":10},{"front":"demonstration laboratory","meaning":"示範實驗室","examples":[{"en":"The demonstration laboratory introduces students to practical work.","zh":"示範實驗室讓學生認識實踐工作。"},{"en":"A demonstration laboratory is a lab setting where instructors show students how equipment, methods, or experiments work.","zh":"demonstration laboratory 是導師向學生展示設備、方法或實驗如何運作的實驗室環境。"},{"en":"Before handling chemicals, students may watch a teacher in a demonstration laboratory.","zh":"在操作化學品前，學生可能在示範實驗室觀看老師示範。"},{"en":"If students see a demonstration first, they may make fewer dangerous mistakes later.","zh":"如果學生先看示範，他們之後可能少犯危險錯誤。"},{"en":"This phrase refers to a lab used mainly for showing and explaining procedures.","zh":"這個片語指主要用於展示和解釋程序的實驗室。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":10},{"front":"introduce students to","meaning":"讓學生認識……","examples":[{"en":"The demonstration laboratory introduces students to the work they will do.","zh":"示範實驗室讓學生認識他們將要進行的工作。"},{"en":"To introduce students to something means to help them become familiar with it for the first time.","zh":"introduce students to something 指幫助學生第一次熟悉某事。"},{"en":"A teacher may introduce students to essay planning before asking them to write independently.","zh":"老師可能先讓學生認識文章規劃，才要求他們獨立寫作。"},{"en":"If students are introduced to lab methods early, they may feel more confident during practical work.","zh":"如果學生早早認識實驗室方法，他們在實踐工作中可能更有信心。"},{"en":"This phrase describes the first stage of guided learning.","zh":"這個片語描述有指導學習的第一階段。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":10},{"front":"the work they are going to undertake","meaning":"他們將要進行的工作","examples":[{"en":"Students learn about the work they are going to undertake.","zh":"學生了解他們將要進行的工作。"},{"en":"The work they are going to undertake means the tasks or activities students will later carry out.","zh":"the work they are going to undertake 指學生之後會執行的任務或活動。"},{"en":"Before a field trip, students may learn about the observations they are going to undertake.","zh":"在實地考察前，學生可能了解他們將要進行的觀察工作。"},{"en":"If learners understand the work in advance, they can prepare questions and avoid confusion.","zh":"如果學習者預先理解工作，他們可以準備問題並避免困惑。"},{"en":"This phrase points to planned future tasks.","zh":"這個片語指計劃中的未來任務。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":10},{"front":"illustrate how to proceed","meaning":"說明如何進行","examples":[{"en":"The demonstration illustrates how to proceed.","zh":"示範說明如何進行。"},{"en":"To illustrate how to proceed means to show the steps for doing something next.","zh":"illustrate how to proceed 指展示接下來做某事的步驟。"},{"en":"A teacher may solve the first maths question to illustrate how to proceed with the rest.","zh":"老師可能解答第一道數學題，以說明如何繼續完成其餘題目。"},{"en":"If students know how to proceed, they waste less time guessing the next step.","zh":"如果學生知道如何進行，他們就較少浪費時間猜下一步。"},{"en":"This phrase describes showing a method clearly.","zh":"這個片語描述清楚展示方法。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":10},{"front":"make particular types of measurements","meaning":"進行特定類型的測量","examples":[{"en":"The laboratory shows how to make particular types of measurements.","zh":"實驗室展示如何進行特定類型的測量。"},{"en":"To make particular types of measurements means to take specific measurements using suitable tools and methods.","zh":"make particular types of measurements 指使用合適工具和方法取得特定測量數據。"},{"en":"A science student may learn how to measure temperature, pressure, or voltage accurately.","zh":"科學學生可能學習如何準確測量溫度、壓力或電壓。"},{"en":"If measurements are not made correctly, experimental results may become unreliable.","zh":"如果測量沒有正確進行，實驗結果可能變得不可靠。"},{"en":"This phrase focuses on precise practical measurement.","zh":"這個片語聚焦於精確的實踐測量。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":10},{"front":"cover topics","meaning":"涵蓋課題","examples":[{"en":"The demonstration laboratory covers topics that may be dangerous.","zh":"示範實驗室涵蓋可能危險的課題。"},{"en":"To cover topics means to include or teach particular subjects or areas.","zh":"cover topics 指包括或教授特定主題或範疇。"},{"en":"A health class may cover topics such as nutrition, sleep, and exercise.","zh":"健康課可能涵蓋營養、睡眠和運動等課題。"},{"en":"If a topic is dangerous to practise at home, a demonstration can teach it more safely.","zh":"如果某課題在家練習很危險，示範可以更安全地教授它。"},{"en":"This phrase describes what content a lesson or course includes.","zh":"這個片語描述課堂或課程包括甚麼內容。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":11},{"front":"situations in which","meaning":"……的情況","examples":[{"en":"The videos show situations in which equipment is not available.","zh":"影片展示設備不可用的情況。"},{"en":"Situations in which means cases or conditions where something happens.","zh":"situations in which 指某事發生的個案或條件。"},{"en":"A teacher may discuss situations in which students should ask for help immediately.","zh":"老師可能討論學生應立即求助的情況。"},{"en":"If equipment is unavailable, videos can show students what they cannot practise directly.","zh":"如果設備不可用，影片可以向學生展示他們不能直接練習的內容。"},{"en":"This phrase introduces the conditions connected with an event or problem.","zh":"這個片語引入與事件或問題相關的條件。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":11},{"front":"be recorded on video","meaning":"被錄影","examples":[{"en":"Many demonstrations are recorded on video.","zh":"許多示範被錄影。"},{"en":"To be recorded on video means to be filmed so people can watch it later.","zh":"be recorded on video 指被拍攝下來，讓人之後觀看。"},{"en":"A school assembly may be recorded on video for parents who cannot attend.","zh":"學校早會可能被錄影，給不能出席的家長觀看。"},{"en":"If a lab demonstration is recorded, every student can review the same procedure.","zh":"如果實驗示範被錄影，每位學生都可以重溫同一程序。"},{"en":"This phrase focuses on saving visual information for later use.","zh":"這個片語聚焦於保存視覺資訊以供日後使用。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":11},{"front":"standardise the process","meaning":"標準化過程","examples":[{"en":"The videos standardise the process being taught.","zh":"影片標準化正在教授的過程。"},{"en":"To standardise the process means to make the procedure the same for everyone.","zh":"standardise the process 指令程序對所有人都相同。"},{"en":"A restaurant may standardise the cooking process so each branch serves the same dish quality.","zh":"餐廳可能標準化烹調過程，令每間分店提供相同菜品質素。"},{"en":"If a teaching process is standardised, students in different groups receive consistent instruction.","zh":"如果教學過程被標準化，不同組別的學生會得到一致教學。"},{"en":"This phrase describes making procedures uniform and reliable.","zh":"這個片語描述令程序統一和可靠。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":11},{"front":"the process being taught","meaning":"正在教授的過程","examples":[{"en":"The video standardises the process being taught.","zh":"影片標準化正在教授的過程。"},{"en":"The process being taught means the procedure or method that students are learning.","zh":"process being taught 指學生正在學習的程序或方法。"},{"en":"In a cooking class, the process being taught may be how to prepare dough safely.","zh":"在烹飪課中，正在教授的過程可能是如何安全製作麵糰。"},{"en":"If the process is shown clearly, students can repeat it more accurately later.","zh":"如果過程清楚展示，學生之後可以更準確地重複。"},{"en":"This phrase refers to the method currently under instruction.","zh":"這個片語指目前正在教授的方法。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":11},{"front":"across numerous groups of students","meaning":"跨多組學生","examples":[{"en":"The videos keep teaching quality consistent across numerous groups of students.","zh":"影片令教學質素跨多組學生保持一致。"},{"en":"Across numerous groups of students means among many different student groups or classes.","zh":"across numerous groups of students 指在許多不同學生組別或班級之間。"},{"en":"A school may use the same marking guide across numerous groups of students to make grading fairer.","zh":"學校可能跨多組學生使用同一評分指引，以令評分更公平。"},{"en":"If teaching materials are consistent across groups, students receive similar instruction even with different tutors.","zh":"如果教學材料在各組之間一致，即使導師不同，學生也會得到相似教學。"},{"en":"This phrase highlights fairness and consistency across many learners.","zh":"這個片語突出跨多名學習者的公平和一致性。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":11},{"front":"at different levels","meaning":"處於不同程度","examples":[{"en":"The students are at different levels.","zh":"學生處於不同程度。"},{"en":"At different levels means having different abilities, stages, or degrees of progress.","zh":"at different levels 指有不同能力、階段或進度。"},{"en":"In one English class, students may be at different levels of speaking confidence.","zh":"在一個英文班中，學生的口語信心可能處於不同程度。"},{"en":"If students are at different levels, teachers may need flexible materials and extra support.","zh":"如果學生處於不同程度，教師可能需要靈活教材和額外支援。"},{"en":"This phrase describes variation among learners.","zh":"這個片語描述學習者之間的差異。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":11},{"front":"support services","meaning":"支援服務","examples":[{"en":"All departments provide support services to students and faculty.","zh":"所有學系都向學生和教員提供支援服務。"},{"en":"Support services are organised help provided to make study, teaching, or administration easier.","zh":"support services 是為令學習、教學或行政更容易而提供的有組織協助。"},{"en":"A university may offer support services such as counselling, IT help, and library guidance.","zh":"大學可能提供輔導、資訊科技協助和圖書館指引等支援服務。"},{"en":"If distance learners receive strong support services, they may feel less isolated.","zh":"如果遙距學習者得到強大支援服務，他們可能感到較不孤立。"},{"en":"This phrase refers to practical help beyond ordinary lessons.","zh":"這個片語指普通課堂以外的實際協助。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":11},{"front":"be engaged in distance learning","meaning":"參與遙距學習","examples":[{"en":"Students and faculty are engaged in distance learning.","zh":"學生和教員參與遙距學習。"},{"en":"To be engaged in distance learning means to be actively involved in remote teaching or study.","zh":"be engaged in distance learning 指積極參與遙距教學或學習。"},{"en":"A working parent engaged in distance learning may watch lectures after children go to sleep.","zh":"參與遙距學習的在職父母可能在孩子睡覺後觀看講課。"},{"en":"If teachers and students are engaged, online courses become more than just uploaded notes.","zh":"如果教師和學生都投入參與，網上課程就不只是上載筆記。"},{"en":"This phrase describes active participation in remote education.","zh":"這個片語描述對遙距教育的主動參與。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":11},{"front":"graduate assistants","meaning":"研究生助教","examples":[{"en":"Graduate assistants are part of the support services.","zh":"研究生助教是支援服務的一部分。"},{"en":"Graduate assistants are postgraduate students who help with teaching, grading, research, or student support.","zh":"graduate assistants 是協助教學、評分、研究或學生支援的研究生。"},{"en":"A graduate assistant may answer questions in an online discussion board.","zh":"研究生助教可能在網上討論區回答問題。"},{"en":"If a course has many students, graduate assistants can help provide faster feedback.","zh":"如果課程有很多學生，研究生助教可以幫助提供更快回饋。"},{"en":"This phrase refers to student staff who support academic work.","zh":"這個片語指支援學術工作的學生職員。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":11},{"front":"course websites","meaning":"課程網站","examples":[{"en":"Course websites support distance-learning students.","zh":"課程網站支援遙距學習學生。"},{"en":"Course websites are online pages or platforms where students access materials, assignments, announcements, and discussions.","zh":"course websites 是學生取得教材、作業、公告和討論的網頁或平台。"},{"en":"A course website may contain lecture slides, reading lists, quizzes, and submission links.","zh":"課程網站可能包含講課簡報、閱讀清單、小測和提交連結。"},{"en":"If a course website is well organised, students can find what they need without emailing the teacher constantly.","zh":"如果課程網站組織良好，學生可以找到所需資料，而不用不斷電郵老師。"},{"en":"This phrase refers to the online home of a course.","zh":"這個片語指課程的網上主頁。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":11},{"front":"proctors","meaning":"監考員","examples":[{"en":"Proctors help supervise assessments in distance learning.","zh":"監考員幫助監督遙距學習中的評核。"},{"en":"Proctors are people who supervise exams or assessments to make sure rules are followed.","zh":"proctors 是監督考試或評核、確保規則被遵守的人。"},{"en":"A proctor may check a student’s identity before an online exam begins.","zh":"監考員可能在網上考試開始前檢查學生身份。"},{"en":"If assessments need to be fair, proctors help reduce cheating and rule-breaking.","zh":"如果評核需要公平，監考員有助減少作弊和違規。"},{"en":"This word is common in exam administration.","zh":"這個詞常見於考試行政。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":12},{"front":"telephone conferencing","meaning":"電話會議","examples":[{"en":"Telephone conferencing is included among the support services.","zh":"電話會議被包括在支援服務之中。"},{"en":"Telephone conferencing is a meeting or discussion held by phone among several people.","zh":"telephone conferencing 是幾個人透過電話舉行的會議或討論。"},{"en":"A tutor may use telephone conferencing to discuss a project with students in different towns.","zh":"導師可能使用電話會議與不同城鎮的學生討論專題。"},{"en":"If Internet access is weak, telephone conferencing can still allow group communication.","zh":"如果互聯網連接不穩，電話會議仍可以容許小組溝通。"},{"en":"This phrase refers to audio meetings by phone.","zh":"這個片語指透過電話進行的音訊會議。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":12},{"front":"electronic library materials","meaning":"電子圖書館資料","examples":[{"en":"Students can use electronic library materials.","zh":"學生可以使用電子圖書館資料。"},{"en":"Electronic library materials are digital books, articles, journals, videos, databases, or other online library resources.","zh":"electronic library materials 是電子書、文章、期刊、影片、資料庫或其他網上圖書館資源。"},{"en":"A distance-learning student may use electronic library materials to research an essay from home.","zh":"遙距學習學生可能使用電子圖書館資料在家研究文章。"},{"en":"If library materials are electronic, students do not need to visit campus to access key readings.","zh":"如果圖書館資料是電子形式，學生不用到校園也能取得核心閱讀材料。"},{"en":"This phrase refers to library resources in digital form.","zh":"這個片語指數碼形式的圖書館資源。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":12},{"front":"instructional designers","meaning":"教學設計師","examples":[{"en":"Instructional designers work with faculty to develop courses.","zh":"教學設計師與教員合作開發課程。"},{"en":"Instructional designers are specialists who help plan how courses, materials, activities, and assessments should be designed.","zh":"instructional designers 是幫助規劃課程、教材、活動和評核應如何設計的專家。"},{"en":"An instructional designer may help a teacher turn a lecture into an interactive online lesson.","zh":"教學設計師可能幫助老師把講課變成互動網上課堂。"},{"en":"If a course is hard to follow, an instructional designer can improve its structure and presentation.","zh":"如果課程難以跟隨，教學設計師可以改善其結構和呈現。"},{"en":"This phrase refers to experts in course design, not necessarily subject experts.","zh":"這個片語指課程設計專家，不一定是學科內容專家。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":12},{"front":"work with faculty","meaning":"與教員合作","examples":[{"en":"Instructional designers work with faculty to design courses.","zh":"教學設計師與教員合作設計課程。"},{"en":"To work with faculty means to collaborate with university teaching staff or academics.","zh":"work with faculty 指與大學教學人員或學者合作。"},{"en":"Library staff may work with faculty to create reading lists for students.","zh":"圖書館職員可能與教員合作，為學生建立閱讀清單。"},{"en":"If designers work with faculty, courses can combine subject expertise with good learning design.","zh":"如果設計師與教員合作，課程可以結合學科專業知識和良好學習設計。"},{"en":"This phrase highlights cooperation with teachers or academics.","zh":"這個片語突出與教師或學者合作。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":12},{"front":"design and develop courses","meaning":"設計和開發課程","examples":[{"en":"Instructional designers help design and develop courses.","zh":"教學設計師幫助設計和開發課程。"},{"en":"To design and develop courses means to plan the structure, materials, activities, and assessments of a course.","zh":"design and develop courses 指規劃課程的結構、教材、活動和評核。"},{"en":"A school may design and develop a new English course for adults who work full-time.","zh":"學校可能為全職工作的成年人設計和開發新的英語課程。"},{"en":"If a course is designed carefully, students understand the goals and learning steps more clearly.","zh":"如果課程設計仔細，學生會更清楚理解目標和學習步驟。"},{"en":"This phrase describes building a course from idea to usable programme.","zh":"這個片語描述把課程由想法建立成可使用課程的過程。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":12},{"front":"reveal the significant role","meaning":"顯示……的重要角色","examples":[{"en":"Interviews revealed the significant role played by instructional designers.","zh":"訪問顯示教學設計師所扮演的重要角色。"},{"en":"To reveal the significant role of someone means to show that they are important in a process.","zh":"reveal the significant role of someone 指顯示某人在某過程中很重要。"},{"en":"A survey may reveal the significant role of parents in children’s reading habits.","zh":"調查可能顯示家長在孩子閱讀習慣中的重要角色。"},{"en":"If interviews show designers shape course quality, their work should not be ignored.","zh":"如果訪問顯示設計師塑造課程質素，他們的工作就不應被忽視。"},{"en":"This phrase introduces evidence that a person or group matters.","zh":"這個片語引入證據，說明某人或某群體很重要。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":12},{"front":"content experts","meaning":"內容專家","examples":[{"en":"Instructional designers are not the content experts.","zh":"教學設計師不是內容專家。"},{"en":"Content experts are people with deep knowledge of the subject matter being taught.","zh":"content experts 是對所教授學科內容有深入知識的人。"},{"en":"A physics professor is a content expert in physics, while a designer may be an expert in course structure.","zh":"物理教授是物理內容專家，而設計師可能是課程結構專家。"},{"en":"If designers are not content experts, they need to work closely with faculty who know the subject.","zh":"如果設計師不是內容專家，他們需要與熟悉學科的教員緊密合作。"},{"en":"This phrase distinguishes subject knowledge from teaching design.","zh":"這個片語區分學科知識和教學設計。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":12},{"front":"advise faculty on","meaning":"就……向教員提供建議","examples":[{"en":"Instructional designers advise faculty on presentation and format.","zh":"教學設計師就呈現和格式向教員提供建議。"},{"en":"To advise faculty on something means to give teaching staff guidance about that issue.","zh":"advise faculty on something 指就某議題向教學人員提供指導。"},{"en":"An IT officer may advise faculty on how to use a new learning platform.","zh":"資訊科技職員可能就如何使用新學習平台向教員提供建議。"},{"en":"If faculty receive advice on format, course materials may become clearer and more consistent.","zh":"如果教員得到格式方面的建議，課程材料可能變得更清楚和一致。"},{"en":"This phrase describes expert guidance given to teachers.","zh":"這個片語描述向教師提供專業指導。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":12},{"front":"be presented on a website","meaning":"在網站上呈現","examples":[{"en":"They advise how information is presented on a website.","zh":"他們就資訊如何在網站上呈現提供建議。"},{"en":"To be presented on a website means to be shown, arranged, or displayed online.","zh":"be presented on a website 指在網上被展示、安排或顯示。"},{"en":"Course deadlines should be presented on a website in a clear calendar format.","zh":"課程截止日期應以清晰日曆格式在網站上呈現。"},{"en":"If information is poorly presented online, students may miss important instructions.","zh":"如果資訊在網上呈現得差，學生可能錯過重要指示。"},{"en":"This phrase focuses on online display and organisation.","zh":"這個片語聚焦於網上展示和組織。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":12},{"front":"the format in which","meaning":"……的格式","examples":[{"en":"They advise the format in which information is presented.","zh":"他們就資訊呈現的格式提供建議。"},{"en":"The format in which something is presented means the structure, layout, or form used to show it.","zh":"the format in which something is presented 指展示某事所用的結構、版面或形式。"},{"en":"A teacher may choose the format in which homework is submitted, such as PDF or online form.","zh":"老師可能選擇功課提交的格式，例如 PDF 或網上表格。"},{"en":"If the format is consistent, students can find information more easily.","zh":"如果格式一致，學生可以更容易找到資訊。"},{"en":"This phrase focuses on how information is arranged.","zh":"這個片語聚焦於資訊如何安排。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":12},{"front":"maintain a standard format","meaning":"維持標準格式","examples":[{"en":"The purpose is to maintain a standard format.","zh":"目的在於維持標準格式。"},{"en":"To maintain a standard format means to keep the layout or structure consistent across materials.","zh":"maintain a standard format 指在材料之間保持版面或結構一致。"},{"en":"A school may maintain a standard format for all report cards so parents can read them easily.","zh":"學校可能為所有成績表維持標準格式，讓家長容易閱讀。"},{"en":"If course pages use the same format, students spend less time searching for basic information.","zh":"如果課程頁面使用相同格式，學生搜尋基本資訊所需時間會較少。"},{"en":"This phrase describes keeping presentation uniform.","zh":"這個片語描述保持呈現方式統一。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":13},{"front":"print materials","meaning":"印刷教材","examples":[{"en":"The university maintains quality in print materials.","zh":"該大學維持印刷教材的質素。"},{"en":"Print materials are physical written or printed resources, such as textbooks, handouts, worksheets, and manuals.","zh":"print materials 是實體文字或印刷資源，例如教科書、講義、工作紙和手冊。"},{"en":"A distance-learning course may mail print materials to students who have limited Internet access.","zh":"遙距學習課程可能把印刷教材郵寄給互聯網有限的學生。"},{"en":"If print materials are clear, students can study even when they are offline.","zh":"如果印刷教材清楚，學生即使離線也能學習。"},{"en":"This phrase refers to paper-based learning resources.","zh":"這個片語指紙本學習資源。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":13},{"front":"electronic resources","meaning":"電子資源","examples":[{"en":"The university also maintains quality in electronic resources.","zh":"該大學也維持電子資源的質素。"},{"en":"Electronic resources are digital materials such as websites, e-books, videos, databases, and online exercises.","zh":"electronic resources 是網站、電子書、影片、資料庫和網上練習等數碼材料。"},{"en":"Students may use electronic resources to download readings and watch demonstrations.","zh":"學生可能使用電子資源下載閱讀材料和觀看示範。"},{"en":"If electronic resources are poorly organised, online learners may waste time and lose motivation.","zh":"如果電子資源組織得差，網上學習者可能浪費時間並失去動力。"},{"en":"This phrase refers to learning materials in digital form.","zh":"這個片語指數碼形式的學習材料。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":13},{"front":"unique among","meaning":"在……之中獨有","examples":[{"en":"The support service is unique among the institutions in the study.","zh":"該支援服務在這項研究中的院校之中獨有。"},{"en":"Unique among means different from all the others in a particular group.","zh":"unique among 指在某一群體中不同於所有其他成員。"},{"en":"One school may be unique among local schools because it offers free evening classes for parents.","zh":"一間學校可能在本地學校中獨有，因為它為家長提供免費夜間課程。"},{"en":"If a service is unique among institutions, researchers may pay special attention to it.","zh":"如果某服務在院校中獨有，研究人員可能特別留意它。"},{"en":"This phrase highlights distinctiveness within a group.","zh":"這個片語突出群體中的獨特性。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":13},{"front":"institutions in this study","meaning":"這項研究中的院校","examples":[{"en":"The university was unique among the institutions in this study.","zh":"該大學在這項研究中的院校之中獨有。"},{"en":"Institutions in this study means the schools, colleges, universities, or organisations examined by the researchers.","zh":"institutions in this study 指研究人員檢視的學校、學院、大學或組織。"},{"en":"Researchers may compare several institutions in a study to identify different teaching models.","zh":"研究人員可能比較一項研究中的幾所院校，以識別不同教學模式。"},{"en":"If one institution differs from the others, its practices may explain special results.","zh":"如果一所院校不同於其他院校，其做法可能解釋特殊結果。"},{"en":"This phrase refers only to the organisations included in the research.","zh":"這個片語只指研究中包括的組織。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":13},{"front":"staff tutors","meaning":"地區導師","examples":[{"en":"Staff tutors provide the link between faculty and regional students.","zh":"地區導師提供教員與地區學生之間的聯繫。"},{"en":"Staff tutors are university teaching or support staff who guide students and help connect them with the institution.","zh":"staff tutors 是指導學生並幫助他們與院校保持聯繫的大學教學或支援職員。"},{"en":"A staff tutor may answer course questions, support part-time lecturers, and advise regional students.","zh":"地區導師可能回答課程問題、支援兼職講師並向地區學生提供建議。"},{"en":"If students study far from campus, staff tutors can make the university feel closer.","zh":"如果學生在遠離校園的地方學習，地區導師可以令大學感覺更接近。"},{"en":"This phrase refers to a support role in distance education.","zh":"這個片語指遙距教育中的支援角色。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":13},{"front":"regionally based","meaning":"按地區設置","examples":[{"en":"The staff tutors are regionally based.","zh":"地區導師按地區設置。"},{"en":"Regionally based means located in different geographic regions rather than only at a central campus.","zh":"regionally based 指設於不同地理地區，而不是只設於中央校園。"},{"en":"A company may have regionally based managers to support shops in different cities.","zh":"公司可能有按地區設置的經理，以支援不同城市的店舖。"},{"en":"If tutors are regionally based, students can receive support closer to home.","zh":"如果導師按地區設置，學生可以在較近家中地方獲得支援。"},{"en":"This phrase describes a service organised by location.","zh":"這個片語描述按地點組織的服務。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":13},{"front":"provide the link between","meaning":"在……之間建立聯繫","examples":[{"en":"Staff tutors provide the link between university faculty and students.","zh":"地區導師在大學教員與學生之間建立聯繫。"},{"en":"To provide the link between two groups means to connect them and help communication flow.","zh":"provide the link between two groups 指連接兩個群體並幫助溝通流通。"},{"en":"A class representative provides the link between students and teachers.","zh":"班代表在學生和老師之間建立聯繫。"},{"en":"If distance learners rarely visit campus, local tutors can connect them with central academic staff.","zh":"如果遙距學習者很少到訪校園，本地導師可以把他們與中央學術職員連接起來。"},{"en":"This phrase highlights a bridging role.","zh":"這個片語突出橋樑角色。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":13},{"front":"within the regions","meaning":"在各地區內","examples":[{"en":"Staff tutors support students within the regions.","zh":"地區導師在各地區內支援學生。"},{"en":"Within the regions means inside the local geographic areas being served.","zh":"within the regions 指在所服務的本地地理區域內。"},{"en":"A charity may provide food support within the regions most affected by flooding.","zh":"慈善機構可能在受水浸影響最嚴重的地區內提供食物支援。"},{"en":"If support is offered within the regions, students do not always need to contact the central campus.","zh":"如果支援在各地區內提供，學生不一定需要聯絡中央校園。"},{"en":"This phrase focuses on local service areas.","zh":"這個片語聚焦於本地服務區域。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":13},{"front":"have a key role in","meaning":"在……中擔當關鍵角色","examples":[{"en":"Staff tutors have a key role in quality assurance.","zh":"地區導師在質素保證中擔當關鍵角色。"},{"en":"To have a key role in something means to be very important in making it happen or work well.","zh":"have a key role in something 指在令某事發生或運作良好方面非常重要。"},{"en":"Parents have a key role in helping young children build reading habits.","zh":"家長在幫助幼童建立閱讀習慣方面擔當關鍵角色。"},{"en":"If staff tutors monitor teaching locally, they can help maintain course quality.","zh":"如果地區導師在本地監察教學，他們可以幫助維持課程質素。"},{"en":"This phrase identifies an important responsibility.","zh":"這個片語指出重要責任。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":13},{"front":"quality assurance","meaning":"質素保證","examples":[{"en":"Staff tutors help with quality assurance.","zh":"地區導師幫助進行質素保證。"},{"en":"Quality assurance is the process of checking and maintaining standards so a service or course remains reliable.","zh":"quality assurance 是檢查和維持標準，使服務或課程保持可靠的過程。"},{"en":"A school may use lesson observations and student feedback for quality assurance.","zh":"學校可能使用課堂觀察和學生回饋進行質素保證。"},{"en":"If quality assurance is weak, problems may continue unnoticed for a long time.","zh":"如果質素保證薄弱，問題可能長時間未被發現。"},{"en":"This phrase focuses on preventing quality problems before they become serious.","zh":"這個片語聚焦於在質素問題變嚴重前預防它們。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":13},{"front":"facilitate effective teaching","meaning":"促進有效教學","examples":[{"en":"Staff tutors facilitate effective teaching of university courses.","zh":"地區導師促進大學課程的有效教學。"},{"en":"To facilitate effective teaching means to help make teaching easier, clearer, and more successful.","zh":"facilitate effective teaching 指幫助教學變得更容易、更清晰和更成功。"},{"en":"A teaching assistant can facilitate effective teaching by preparing materials and answering student questions.","zh":"教學助理可以透過準備材料和回答學生問題來促進有效教學。"},{"en":"If support staff solve local problems quickly, teachers can focus more on learning.","zh":"如果支援職員快速解決本地問題，教師可以更專注於學習。"},{"en":"This phrase describes helping teaching work better.","zh":"這個片語描述幫助教學運作得更好。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":14},{"front":"be responsible for","meaning":"負責","examples":[{"en":"Staff tutors are responsible for the selection of Associate Lecturers.","zh":"地區導師負責副講師的甄選。"},{"en":"To be responsible for something means to have the duty of managing, doing, or overseeing it.","zh":"be responsible for something 指有責任管理、執行或監督某事。"},{"en":"A class monitor may be responsible for collecting homework before lessons begin.","zh":"班長可能負責在上課前收集功課。"},{"en":"If staff tutors are responsible for lecturer selection, they influence teaching quality directly.","zh":"如果地區導師負責講師甄選，他們便直接影響教學質素。"},{"en":"This phrase identifies duty or accountability.","zh":"這個片語指出責任或問責。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":14},{"front":"selection, monitoring and development of","meaning":"……的甄選、監察和發展","examples":[{"en":"They are responsible for the selection, monitoring and development of part-time lecturers.","zh":"他們負責兼職講師的甄選、監察和發展。"},{"en":"Selection, monitoring and development of someone means choosing them, checking their work, and helping them improve.","zh":"selection, monitoring and development of someone 指選擇某人、檢查其工作並幫助其進步。"},{"en":"A school leader may handle the selection, monitoring and development of new teachers.","zh":"學校領導可能處理新教師的甄選、監察和發展。"},{"en":"If lecturers are selected carefully and supported continuously, teaching quality is more likely to improve.","zh":"如果講師被仔細甄選並持續支援，教學質素較可能改善。"},{"en":"This phrase describes a full management process for staff.","zh":"這個片語描述對職員的完整管理過程。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":14},{"front":"part-time Associate Lecturers","meaning":"兼職副講師","examples":[{"en":"Staff tutors help manage part-time Associate Lecturers.","zh":"地區導師幫助管理兼職副講師。"},{"en":"Part-time Associate Lecturers are lecturers who teach for an institution on a part-time basis.","zh":"part-time Associate Lecturers 是以兼職形式為院校授課的講師。"},{"en":"A part-time Associate Lecturer may teach evening tutorials while also working in industry.","zh":"兼職副講師可能一邊在業界工作，一邊教授晚間導修課。"},{"en":"If part-time lecturers are well supported, students can receive more consistent teaching.","zh":"如果兼職講師得到良好支援，學生可以得到更一致的教學。"},{"en":"This phrase refers to teaching staff who are not full-time university faculty.","zh":"這個片語指並非全職大學教員的教學人員。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":14},{"front":"contribute to faculty research","meaning":"對教員研究作出貢獻","examples":[{"en":"Staff tutors contribute to faculty research.","zh":"地區導師對教員研究作出貢獻。"},{"en":"To contribute to faculty research means to help academic research done by a department or teaching faculty.","zh":"contribute to faculty research 指幫助學系或教學院系進行的學術研究。"},{"en":"A tutor may contribute to research by collecting student feedback or helping analyse teaching data.","zh":"導師可能透過收集學生回饋或幫助分析教學數據來對研究作出貢獻。"},{"en":"If support staff join research, the department can connect practical teaching experience with academic study.","zh":"如果支援職員參與研究，學系可以把實際教學經驗與學術研究連接起來。"},{"en":"This phrase describes adding useful work to research efforts.","zh":"這個片語描述為研究工作加入有用貢獻。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":14},{"front":"development and presentation of courses","meaning":"課程的開發和呈現","examples":[{"en":"They contribute to the development and presentation of courses.","zh":"他們對課程的開發和呈現作出貢獻。"},{"en":"Development and presentation of courses means creating course content and deciding how it is delivered to students.","zh":"development and presentation of courses 指創建課程內容並決定如何向學生傳授。"},{"en":"A teacher may help with course development by writing materials and planning weekly lessons.","zh":"教師可能透過編寫教材和規劃每週課堂來幫助課程開發。"},{"en":"If course presentation is clear, students can follow the learning path more easily.","zh":"如果課程呈現清晰，學生可以更容易跟隨學習路徑。"},{"en":"This phrase includes both building a course and showing it to learners.","zh":"這個片語包括建立課程和向學習者展示課程。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":14},{"front":"highly qualified in their fields","meaning":"在其領域具備高資歷","examples":[{"en":"The staff tutors are highly qualified in their fields.","zh":"地區導師在其領域具備高資歷。"},{"en":"Highly qualified in their fields means having strong education, training, or expertise in their subject areas.","zh":"highly qualified in their fields 指在其學科或專業範疇中具備強大教育、培訓或專業知識。"},{"en":"A doctor highly qualified in surgery has advanced training and experience in that area.","zh":"在外科領域具備高資歷的醫生有該範疇的高級培訓和經驗。"},{"en":"If tutors are highly qualified, they can answer specialised questions and support course quality.","zh":"如果導師具備高資歷，他們可以回答專門問題並支援課程質素。"},{"en":"This phrase stresses professional competence.","zh":"這個片語強調專業能力。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":14},{"front":"bridge the distance gap","meaning":"彌合遙距差距","examples":[{"en":"Staff tutors bridge the distance gap between faculty and students.","zh":"地區導師彌合教員與學生之間的遙距差距。"},{"en":"To bridge the distance gap means to reduce the separation caused by physical distance.","zh":"bridge the distance gap 指減少由實體距離造成的分隔。"},{"en":"Weekly video meetings can bridge the distance gap between remote workers and their manager.","zh":"每週視像會議可以彌合遙距員工與經理之間的距離差距。"},{"en":"If students study far from campus, local tutors can make communication easier and more personal.","zh":"如果學生遠離校園學習，本地導師可以令溝通更容易和更個人化。"},{"en":"This phrase describes connecting people who are separated by location.","zh":"這個片語描述連接被地理位置分隔的人。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":14},{"front":"at different locations","meaning":"在不同地點","examples":[{"en":"Staff tutors support students at different locations.","zh":"地區導師支援在不同地點的學生。"},{"en":"At different locations means in various places rather than one single place.","zh":"at different locations 指在多個地方，而不是單一地點。"},{"en":"A company may train employees at different locations through online workshops.","zh":"公司可能透過網上工作坊培訓在不同地點的員工。"},{"en":"If students are at different locations, support must be organised flexibly.","zh":"如果學生在不同地點，支援就必須靈活組織。"},{"en":"This phrase highlights geographic spread.","zh":"這個片語突出地理分散。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":14},{"front":"using innovative strategies","meaning":"使用創新策略","examples":[{"en":"The university teaches laboratory courses using innovative strategies.","zh":"該大學使用創新策略教授實驗課程。"},{"en":"Using innovative strategies means applying new or creative methods to solve a teaching problem.","zh":"using innovative strategies 指應用新穎或有創意的方法來解決教學問題。"},{"en":"A school may teach grammar using innovative strategies such as games, videos, and real-life tasks.","zh":"學校可能使用遊戲、影片和真實任務等創新策略教授文法。"},{"en":"If traditional methods cannot reach remote students, innovative strategies may keep practical learning possible.","zh":"如果傳統方法不能接觸遙距學生，創新策略可能令實踐學習仍然可行。"},{"en":"This phrase shows how new approaches are used deliberately.","zh":"這個片語顯示新方法被有意識地使用。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":14},{"front":"field trips","meaning":"實地考察","examples":[{"en":"Field trips are one strategy used in distance-learning courses.","zh":"實地考察是遙距學習課程中使用的一種策略。"},{"en":"Field trips are educational visits to real places where students observe, collect information, or learn directly from the environment.","zh":"field trips 是到真實地點進行的教育性參觀，學生在那裡觀察、收集資訊或直接從環境學習。"},{"en":"A geography class may take a field trip to a beach to study erosion.","zh":"地理班可能到海灘實地考察，研究侵蝕。"},{"en":"If students go on field trips, they can connect classroom theory with real-world evidence.","zh":"如果學生參加實地考察，他們可以把課堂理論與現實證據連接起來。"},{"en":"This phrase refers to learning outside the classroom or online platform.","zh":"這個片語指課室或網上平台以外的學習。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":14},{"front":"in combination with","meaning":"與……結合","examples":[{"en":"The university uses residential schools in combination with new technologies.","zh":"該大學把住宿學校與新科技結合使用。"},{"en":"In combination with means together with another thing.","zh":"in combination with 指與另一事物一起使用。"},{"en":"A teacher may use videos in combination with worksheets to support different learners.","zh":"老師可能把影片與工作紙結合使用，以支援不同學習者。"},{"en":"If online tools are combined with short face-to-face sessions, students may gain both flexibility and practical experience.","zh":"如果網上工具與短期面授課節結合，學生可能同時獲得靈活性和實踐經驗。"},{"en":"This phrase shows that two methods are used together.","zh":"這個片語顯示兩種方法一起使用。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":15},{"front":"within and outside the UK","meaning":"在英國境內外","examples":[{"en":"The university teaches students within and outside the UK.","zh":"該大學教授英國境內外的學生。"},{"en":"Within and outside the UK means both inside the United Kingdom and in other countries.","zh":"within and outside the UK 指在英國境內以及其他國家。"},{"en":"A university website may serve learners within and outside the country.","zh":"大學網站可能服務本國境內外的學習者。"},{"en":"If a course reaches students outside the UK, support must work across time zones and locations.","zh":"如果課程接觸英國以外的學生，支援必須跨時區和地點運作。"},{"en":"This phrase marks both domestic and international reach.","zh":"這個片語標示本地和國際覆蓋範圍。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":15},{"front":"be meant to replace","meaning":"旨在取代","examples":[{"en":"Distance learning is not meant to replace face-to-face classrooms.","zh":"遙距學習並非旨在取代面對面課堂。"},{"en":"To be meant to replace something means to be intended to take its place.","zh":"be meant to replace something 指被設計或意圖用來取代某物。"},{"en":"A calculator is not meant to replace understanding; it is meant to help with calculation.","zh":"計算機並非旨在取代理解，而是用來幫助計算。"},{"en":"If distance learning supplements classrooms rather than replaces them, both methods can serve different needs.","zh":"如果遙距學習補充而不是取代課堂，兩種方法可以服務不同需要。"},{"en":"This phrase focuses on purpose or intention.","zh":"這個片語聚焦於目的或意圖。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":15},{"front":"one major way to","meaning":"……的一個主要方法","examples":[{"en":"Distance learning is one major way to make education more accessible.","zh":"遙距學習是令教育更容易接觸的一個主要方法。"},{"en":"One major way to do something means one important method for achieving it.","zh":"one major way to do something 指達成某事的一個重要方法。"},{"en":"Regular reading is one major way to improve vocabulary.","zh":"定期閱讀是改善詞彙的一個主要方法。"},{"en":"If education must reach adults and remote learners, distance learning is an important method.","zh":"如果教育必須接觸成年人和偏遠學習者，遙距學習就是一個重要方法。"},{"en":"This phrase introduces a key solution, not the only solution.","zh":"這個片語引入主要解決方法，而不是唯一方法。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":15},{"front":"make education more accessible","meaning":"令教育更容易接觸","examples":[{"en":"Distance learning can make education more accessible to society.","zh":"遙距學習可以令社會更容易接觸教育。"},{"en":"To make education more accessible means to make it easier for more people to study.","zh":"make education more accessible 指令更多人更容易讀書。"},{"en":"Scholarships make education more accessible for students from low-income families.","zh":"獎學金令低收入家庭學生更容易接觸教育。"},{"en":"If lessons are available online and at flexible times, barriers of distance and schedule become smaller.","zh":"如果課堂可在網上和靈活時間提供，距離和時間表障礙便會變小。"},{"en":"This phrase focuses on widening access to learning.","zh":"這個片語聚焦於擴大學習可及性。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":15},{"front":"advances in communication and digital technology","meaning":"通訊及數碼科技的進步","examples":[{"en":"Advances in communication and digital technology may change practical teaching.","zh":"通訊及數碼科技的進步可能改變實踐教學。"},{"en":"Advances in communication and digital technology are improvements in tools for connecting people and processing information electronically.","zh":"advances in communication and digital technology 是連接人們和以電子方式處理資訊的工具進步。"},{"en":"Faster Internet, video platforms, and simulation software are advances that can support remote learning.","zh":"更快互聯網、視像平台和模擬軟件都是可以支援遙距學習的進步。"},{"en":"If these technologies improve, practical training may become possible for more distance students.","zh":"如果這些科技改善，實踐培訓可能對更多遙距學生變得可行。"},{"en":"This phrase links technology progress with changes in education.","zh":"這個片語把科技進步與教育變化連接起來。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":15},{"front":"continue","meaning":"持續發展","examples":[{"en":"As technology continues, distance education may improve further.","zh":"隨着科技持續發展，遙距教育可能進一步改善。"},{"en":"To continue means to keep going, developing, or happening.","zh":"continue 指繼續進行、發展或發生。"},{"en":"If a student continues practising speaking every week, confidence may grow slowly.","zh":"如果學生每星期持續練習口語，信心可能慢慢增長。"},{"en":"If technology continues to improve, older limits of distance learning may become smaller.","zh":"如果科技持續改善，遙距學習以往的限制可能變得較小。"},{"en":"This word shows an ongoing process rather than a finished event.","zh":"這個詞顯示一個持續過程，而不是已完成事件。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":15},{"front":"someday be replaced with","meaning":"有一天可能被……取代","examples":[{"en":"Residential labs may someday be replaced with comparable experiences.","zh":"住宿實驗室有一天可能被可相比的體驗取代。"},{"en":"Someday be replaced with means may one day be exchanged for or substituted by something else.","zh":"someday be replaced with 指有一天可能被另一事物替換或代替。"},{"en":"Paper notices may someday be replaced with mobile alerts in many schools.","zh":"在許多學校，紙本通告有一天可能被手機通知取代。"},{"en":"If virtual labs become realistic enough, some physical lab sessions may be replaced.","zh":"如果虛擬實驗室變得足夠真實，一些實體實驗課節可能被取代。"},{"en":"This phrase points to a possible future substitution.","zh":"這個片語指向未來可能的替代。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":15},{"front":"comparable experiences","meaning":"可相比的體驗","examples":[{"en":"Distance education may provide comparable experiences.","zh":"遙距教育可能提供可相比的體驗。"},{"en":"Comparable experiences are experiences similar enough in quality, value, or effect to be meaningfully compared.","zh":"comparable experiences 是在質素、價值或效果上足夠相似，可作有意義比較的體驗。"},{"en":"A virtual museum tour may provide a comparable experience for students who cannot travel.","zh":"對不能出行的學生而言，虛擬博物館導覽可能提供可相比的體驗。"},{"en":"If online simulations give students similar practice and feedback, they may be comparable to some lab activities.","zh":"如果網上模擬給學生相似練習和回饋，它們可能與一些實驗活動可相比。"},{"en":"This phrase does not mean identical experiences, but reasonably similar ones.","zh":"這個片語不是指完全相同的體驗，而是合理相似的體驗。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":15},{"front":"provided through distance education","meaning":"透過遙距教育提供","examples":[{"en":"Comparable experiences may be provided through distance education.","zh":"可相比的體驗可能透過遙距教育提供。"},{"en":"Provided through distance education means delivered by remote teaching methods rather than in-person attendance.","zh":"provided through distance education 指透過遙距教學方法提供，而不是透過親身出席提供。"},{"en":"A virtual field trip may be provided through distance education for students in different countries.","zh":"虛擬實地考察可能透過遙距教育提供給不同國家的學生。"},{"en":"If practical experiences are provided remotely, more students can access them without travelling.","zh":"如果實踐體驗可以遙距提供，更多學生不用出行也能接觸它們。"},{"en":"This phrase focuses on how an experience is delivered.","zh":"這個片語聚焦於體驗如何被傳授。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":15},{"front":"contains the following information","meaning":"包含以下資料","examples":[{"en":"Students identify which section contains the following information.","zh":"學生識別哪一部分包含以下資料。"},{"en":"Contains the following information means includes the specific details listed in the question.","zh":"contains the following information 指包括題目列出的特定細節。"},{"en":"In a reading test, students must find the paragraph that contains the required example or reason.","zh":"在閱讀測驗中，學生必須找出包含所需例子或原因的段落。"},{"en":"If students search for meaning rather than only keywords, they are more likely to find the correct section.","zh":"如果學生搜尋意思而不只是關鍵字，他們較可能找到正確部分。"},{"en":"This phrase is a common instruction in information-matching questions.","zh":"這個片語是資訊配對題中的常見指示。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":15},{"front":"some sections may be used more than once","meaning":"某些部分可重複使用","examples":[{"en":"Some sections may be used more than once.","zh":"某些部分可重複使用。"},{"en":"Some sections may be used more than once means the same section can be the answer to several questions.","zh":"some sections may be used more than once 指同一部分可以作為幾題的答案。"},{"en":"In a matching task, one paragraph may match two different pieces of information.","zh":"在配對題中，一段可能配對兩項不同資料。"},{"en":"If students assume each section can be used only once, they may miss correct repeated answers.","zh":"如果學生假設每部分只能使用一次，可能錯過正確的重複答案。"},{"en":"This instruction tells candidates not to eliminate a section after one use.","zh":"這個指示告訴考生不要在使用一次後排除某部分。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":16},{"front":"one aspect of the course","meaning":"課程的一個方面","examples":[{"en":"One aspect of the course is practical experience.","zh":"課程的一個方面是實踐經驗。"},{"en":"One aspect of the course means one part, feature, or element of the course.","zh":"one aspect of the course 指課程的一個部分、特徵或元素。"},{"en":"Assessment is one aspect of a course, while support and materials are other aspects.","zh":"評核是課程的一個方面，而支援和教材是其他方面。"},{"en":"If one aspect of a course is weak, students may still struggle even when other parts are strong.","zh":"如果課程某一方面薄弱，即使其他部分強，學生仍可能吃力。"},{"en":"This phrase helps separate a course into different features.","zh":"這個片語幫助把課程分成不同特徵。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":16},{"front":"gain first-hand experience","meaning":"獲得第一手經驗","examples":[{"en":"Students can gain first-hand experience in a working environment.","zh":"學生可以在工作環境中獲得第一手經驗。"},{"en":"To gain first-hand experience means to learn by directly doing or observing something yourself.","zh":"gain first-hand experience 指透過親身做或觀察某事來學習。"},{"en":"A student can gain first-hand experience of hospital work by shadowing a nurse for a day.","zh":"學生可以透過跟隨護士一天，獲得醫院工作的第一手經驗。"},{"en":"If learners see real equipment and real procedures, they understand more than from reading alone.","zh":"如果學習者看到真實設備和真實程序，他們會比單靠閱讀理解更多。"},{"en":"This phrase stresses direct experience rather than second-hand information.","zh":"這個片語強調直接經驗，而不是二手資訊。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":16},{"front":"working environment","meaning":"工作環境","examples":[{"en":"Study trips can give students experience in a working environment.","zh":"學習考察可以給學生工作環境中的經驗。"},{"en":"A working environment is a real workplace where people carry out professional tasks.","zh":"working environment 是人們進行專業任務的真實工作場所。"},{"en":"A factory, hospital, office, or laboratory can be a working environment.","zh":"工廠、醫院、辦公室或實驗室都可以是工作環境。"},{"en":"If students enter a working environment, they can see how rules, tools, and teamwork operate in practice.","zh":"如果學生進入工作環境，他們可以看到規則、工具和團隊合作如何實際運作。"},{"en":"This phrase refers to the real conditions of work.","zh":"這個片語指真實工作條件。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":16},{"front":"educational excursions","meaning":"教育考察","examples":[{"en":"Some courses include educational excursions.","zh":"一些課程包括教育考察。"},{"en":"Educational excursions are organised trips designed to help students learn outside the classroom.","zh":"educational excursions 是有組織的旅行，旨在幫助學生在課室外學習。"},{"en":"A history class may take an educational excursion to a museum or heritage site.","zh":"歷史班可能到博物館或文物地點進行教育考察。"},{"en":"If excursions are planned well, students connect course ideas with real places and people.","zh":"如果考察規劃良好，學生可以把課程概念與真實地方和人物連接起來。"},{"en":"This phrase is a formal way to say learning trips.","zh":"這個片語是 learning trips 的正式說法。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":16},{"front":"a critical factor","meaning":"關鍵因素","examples":[{"en":"The location of instruction is not a critical factor in achievement.","zh":"教學地點不是成就中的關鍵因素。"},{"en":"A critical factor is an important element that strongly affects the result.","zh":"critical factor 是強烈影響結果的重要元素。"},{"en":"Sleep is a critical factor in exam performance because tired students make more mistakes.","zh":"睡眠是考試表現的關鍵因素，因為疲倦學生會犯更多錯。"},{"en":"If location is not critical, teaching quality and student effort may matter more.","zh":"如果地點不是關鍵，教學質素和學生努力可能更重要。"},{"en":"This phrase identifies something that may decide success or failure.","zh":"這個片語指出可能決定成敗的因素。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":16},{"front":"students’ achievements","meaning":"學生成就","examples":[{"en":"Where instruction takes place may not determine students’ achievements.","zh":"教學在哪裡進行可能不決定學生成就。"},{"en":"Students’ achievements are the learning results, grades, skills, or goals students reach.","zh":"students’ achievements 是學生達到的學習結果、成績、技能或目標。"},{"en":"A student’s achievements may include passing exams, completing projects, and improving confidence.","zh":"學生成就可能包括通過考試、完成專題和提升信心。"},{"en":"If achievements depend more on teaching design than location, distance learning can still be effective.","zh":"如果成就更取決於教學設計而不是地點，遙距學習仍可以有效。"},{"en":"This phrase focuses on what students successfully accomplish.","zh":"這個片語聚焦於學生成功完成的事情。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":16},{"front":"traditional teaching techniques","meaning":"傳統教學技巧","examples":[{"en":"Distance learning is not designed to replace traditional teaching techniques.","zh":"遙距學習並非設計來取代傳統教學技巧。"},{"en":"Traditional teaching techniques are long-established methods such as lectures, classroom discussion, demonstration, and guided practice.","zh":"traditional teaching techniques 是長久建立的方法，例如講課、課堂討論、示範和指導練習。"},{"en":"A teacher using the board to explain grammar is using a traditional teaching technique.","zh":"老師使用白板解釋文法，就是在使用傳統教學技巧。"},{"en":"If distance learning supports rather than replaces traditional techniques, teachers can choose the best method for each task.","zh":"如果遙距學習支援而不是取代傳統技巧，教師可以為每項任務選擇最佳方法。"},{"en":"This phrase refers to established ways of teaching.","zh":"這個片語指既有教學方法。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":16},{"front":"practical instruction sessions","meaning":"實踐教學課節","examples":[{"en":"Technology may reduce the need to attend practical instruction sessions.","zh":"科技可能減少參加實踐教學課節的需要。"},{"en":"Practical instruction sessions are teaching periods where students learn by doing, observing, or practising real skills.","zh":"practical instruction sessions 是學生透過操作、觀察或練習真實技能來學習的教學時段。"},{"en":"A cooking class, lab session, or workshop can be a practical instruction session.","zh":"烹飪課、實驗課或工作坊都可以是實踐教學課節。"},{"en":"If simulations become realistic, students may need fewer in-person practical sessions.","zh":"如果模擬變得真實，學生可能需要較少親身實踐課節。"},{"en":"This phrase refers to hands-on teaching time.","zh":"這個片語指動手教學時間。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":16},{"front":"benefit from the use of","meaning":"受益於使用……","examples":[{"en":"Students benefit from the use of expensive equipment.","zh":"學生受益於使用昂貴設備。"},{"en":"To benefit from the use of something means to gain an advantage by using it.","zh":"benefit from the use of something 指透過使用某物獲得好處。"},{"en":"Patients benefit from the use of modern scanners because doctors can diagnose problems earlier.","zh":"病人受益於使用現代掃描儀，因為醫生可以更早診斷問題。"},{"en":"If students use advanced lab equipment, they can learn skills that are impossible to practise at home.","zh":"如果學生使用先進實驗設備，他們可以學到在家無法練習的技能。"},{"en":"This phrase connects using a tool with receiving a benefit.","zh":"這個片語把使用工具與獲得好處連接起來。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":16},{"front":"not otherwise available to","meaning":"否則不能供……使用","examples":[{"en":"Some equipment is not otherwise available to students.","zh":"一些設備否則不能供學生使用。"},{"en":"Not otherwise available to someone means not accessible to them in any other normal way.","zh":"not otherwise available to someone 指在其他正常方式下不能被某人接觸或使用。"},{"en":"A rare library book may be not otherwise available to students except through a special archive.","zh":"一本稀有圖書可能除了透過特別檔案館外，否則不能供學生使用。"},{"en":"If expensive machines are not available at home, residential schools may provide essential access.","zh":"如果昂貴機器在家中不可用，住宿學校可能提供必要使用機會。"},{"en":"This phrase explains why a special arrangement is needed.","zh":"這個片語解釋為何需要特別安排。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":16},{"front":"one purpose of","meaning":"……的其中一個目的","examples":[{"en":"One purpose of the summer school is direct assessment.","zh":"暑期學校的其中一個目的是直接評核。"},{"en":"One purpose of something means one reason it exists or is done.","zh":"one purpose of something 指某事存在或被進行的一個理由。"},{"en":"One purpose of homework is to let students practise without the teacher’s immediate help.","zh":"功課的其中一個目的是讓學生在沒有老師即時幫助下練習。"},{"en":"If one purpose of a lab school is assessment, teachers can check skills directly.","zh":"如果實驗學校的其中一個目的是評核，教師可以直接檢查技能。"},{"en":"This phrase identifies one function among several.","zh":"這個片語指出多個功能中的其中一個。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":17},{"front":"enable students to be assessed directly","meaning":"使學生能夠被直接評核","examples":[{"en":"The summer school enables students to be assessed directly.","zh":"暑期學校使學生能夠被直接評核。"},{"en":"To enable students to be assessed directly means to make it possible for teachers to evaluate students in person or through direct observation.","zh":"enable students to be assessed directly 指讓教師能夠親身或透過直接觀察評估學生。"},{"en":"A speaking exam enables teachers to assess pronunciation directly.","zh":"口語考試使教師能夠直接評核發音。"},{"en":"If students perform lab work in front of instructors, their technique can be judged immediately.","zh":"如果學生在導師面前進行實驗工作，其技巧可以即時被判斷。"},{"en":"This phrase highlights direct evaluation rather than indirect evidence.","zh":"這個片語突出直接評估，而不是間接證據。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":17},{"front":"undertake simple experiments","meaning":"進行簡單實驗","examples":[{"en":"The option mentions that students may undertake simple experiments.","zh":"這個選項提到學生可能進行簡單實驗。"},{"en":"To undertake simple experiments means to carry out basic practical tests that are not too complex or dangerous.","zh":"undertake simple experiments 指進行不太複雜或危險的基本實踐測試。"},{"en":"A student may undertake a simple experiment by testing which paper towel absorbs the most water.","zh":"學生可能透過測試哪種廚房紙吸水最多來進行簡單實驗。"},{"en":"If experiments are simple, students may be able to do them safely at home with clear instructions.","zh":"如果實驗簡單，學生可能在清楚指示下安全地在家完成。"},{"en":"This phrase describes basic hands-on scientific work.","zh":"這個片語描述基本動手科學工作。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":17},{"front":"familiarise students with","meaning":"使學生熟悉……","examples":[{"en":"The course may familiarise students with laboratory equipment.","zh":"課程可能使學生熟悉實驗室設備。"},{"en":"To familiarise students with something means to help students become used to it and understand how it works.","zh":"familiarise students with something 指幫助學生習慣某物並理解它如何運作。"},{"en":"A teacher may familiarise students with the exam format before the real test.","zh":"老師可能在正式考試前使學生熟悉考試格式。"},{"en":"If students are familiar with equipment, they are less likely to panic or misuse it.","zh":"如果學生熟悉設備，他們較不容易慌張或誤用。"},{"en":"This phrase describes preparation through guided exposure.","zh":"這個片語描述透過有指導接觸進行準備。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":17},{"front":"laboratory equipment","meaning":"實驗室設備","examples":[{"en":"Students may need to become familiar with laboratory equipment.","zh":"學生可能需要熟悉實驗室設備。"},{"en":"Laboratory equipment means the tools and machines used in a lab for experiments and measurements.","zh":"laboratory equipment 指實驗室中用於實驗和測量的工具和機器。"},{"en":"Microscopes, thermometers, circuit boards, and measuring instruments are laboratory equipment.","zh":"顯微鏡、溫度計、電路板和測量儀器都是實驗室設備。"},{"en":"If students do not know the equipment, mistakes can damage results or create safety risks.","zh":"如果學生不了解設備，錯誤可能破壞結果或造成安全風險。"},{"en":"This phrase refers to practical tools used in scientific work.","zh":"這個片語指科學工作中使用的實踐工具。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":17},{"front":"visual display of coursework","meaning":"課程作業的視覺呈現","examples":[{"en":"Instructional designers advise faculty on the visual display of coursework.","zh":"教學設計師就課程作業的視覺呈現向教員提供建議。"},{"en":"Visual display of coursework means how course materials and tasks look on a page, screen, or website.","zh":"visual display of coursework 指課程材料和任務在頁面、螢幕或網站上的外觀。"},{"en":"A clear visual display uses headings, spacing, and simple layout so students can find tasks quickly.","zh":"清晰的視覺呈現使用標題、間距和簡單版面，讓學生快速找到任務。"},{"en":"If coursework is visually confusing, students may miss instructions even when the content is good.","zh":"如果課程作業視覺上混亂，即使內容良好，學生也可能錯過指示。"},{"en":"This phrase focuses on how learning materials are presented visually.","zh":"這個片語聚焦於學習材料如何以視覺方式呈現。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":17},{"front":"suitability of","meaning":"……的合適性","examples":[{"en":"The question asks about the suitability of library material.","zh":"題目問圖書館資料的合適性。"},{"en":"Suitability of something means how appropriate or useful it is for a particular purpose or group.","zh":"suitability of something 指某物對特定目的或群體有多合適或有用。"},{"en":"A teacher may check the suitability of a book before giving it to younger students.","zh":"老師可能在把書給低年級學生前檢查其合適性。"},{"en":"If library materials are too advanced, they may not suit beginners in a distance course.","zh":"如果圖書館資料太深，它們可能不適合遙距課程初學者。"},{"en":"This phrase focuses on whether something fits the need.","zh":"這個片語聚焦於某物是否符合需要。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":17},{"front":"monitoring of students’ progress","meaning":"監察學生進度","examples":[{"en":"The option refers to monitoring students’ progress.","zh":"這個選項指監察學生進度。"},{"en":"Monitoring of students’ progress means regularly checking how students are improving or struggling.","zh":"monitoring students’ progress 指定期檢查學生如何進步或在哪裡遇到困難。"},{"en":"A teacher may monitor progress through quizzes, homework, and short meetings.","zh":"老師可能透過小測、功課和短會議監察進度。"},{"en":"If progress is monitored early, students who fall behind can receive help sooner.","zh":"如果及早監察進度，落後學生可以更快得到幫助。"},{"en":"This phrase focuses on ongoing tracking of learning.","zh":"這個片語聚焦於持續追蹤學習情況。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":17},{"front":"appointment of certain teaching staff","meaning":"任命某些教學人員","examples":[{"en":"Staff tutors are connected with the appointment of certain teaching staff.","zh":"地區導師與任命某些教學人員有關。"},{"en":"Appointment of certain teaching staff means choosing or officially placing particular people into teaching roles.","zh":"appointment of certain teaching staff 指選擇或正式安排特定人士擔任教學職位。"},{"en":"A university may involve senior tutors in the appointment of part-time lecturers.","zh":"大學可能讓資深導師參與任命兼職講師。"},{"en":"If the right teaching staff are appointed, students may receive better guidance.","zh":"如果合適的教學人員被任命，學生可能得到更好指導。"},{"en":"This phrase refers to staffing decisions in education.","zh":"這個片語指教育中的人手任命決定。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":17},{"front":"training of teaching staff","meaning":"教學人員培訓","examples":[{"en":"The option mentions the training of teaching staff.","zh":"這個選項提到教學人員培訓。"},{"en":"Training of teaching staff means preparing teachers or tutors to teach effectively.","zh":"training of teaching staff 指準備教師或導師有效教學。"},{"en":"A school may provide training of teaching staff on online assessment and student feedback.","zh":"學校可能提供關於網上評核和學生回饋的教學人員培訓。"},{"en":"If teaching staff are trained well, students receive clearer instruction and more useful support.","zh":"如果教學人員受訓良好，學生會得到更清晰教學和更有用支援。"},{"en":"This phrase focuses on improving teachers’ skills.","zh":"這個片語聚焦於提升教師技能。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":17},{"front":"increasing number of","meaning":"越來越多的……","examples":[{"en":"The increasing number of distance-learning courses raises quality concerns.","zh":"越來越多的遙距學習課程引起質素關注。"},{"en":"Increasing number of something means more and more of it over time.","zh":"increasing number of something 指某物隨時間越來越多。"},{"en":"The increasing number of electric cars has created more demand for charging stations.","zh":"越來越多的電動車創造了對充電站的更多需求。"},{"en":"If more courses appear quickly, institutions may struggle to keep quality consistent.","zh":"如果更多課程快速出現，院校可能難以保持質素一致。"},{"en":"This phrase describes growth in quantity.","zh":"這個片語描述數量增長。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":17},{"front":"the standard of teaching","meaning":"教學水平","examples":[{"en":"The standard of teaching has become an issue.","zh":"教學水平已成為問題。"},{"en":"The standard of teaching means the level of quality, effectiveness, and professionalism in teaching.","zh":"standard of teaching 指教學在質素、成效和專業程度上的水平。"},{"en":"Parents may question the standard of teaching if students receive little feedback.","zh":"如果學生得到很少回饋，家長可能質疑教學水平。"},{"en":"If teaching standards fall, students may learn less even if enrolment rises.","zh":"如果教學水平下降，即使收生人數上升，學生也可能學得較少。"},{"en":"This phrase evaluates how good the teaching is.","zh":"這個片語評價教學有多好。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":18},{"front":"become an issue","meaning":"成為問題","examples":[{"en":"The standard of teaching has become an issue.","zh":"教學水平已成為問題。"},{"en":"To become an issue means to become a problem or topic of concern.","zh":"become an issue 指變成問題或令人關注的議題。"},{"en":"School transport may become an issue if buses are always late.","zh":"如果巴士總是遲到，校車交通可能成為問題。"},{"en":"If many online programmes appear, teaching quality may become an issue for students and employers.","zh":"如果許多網上課程出現，教學質素可能成為學生和僱主關注的問題。"},{"en":"This phrase shows that something now needs attention.","zh":"這個片語顯示某事現在需要關注。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":18},{"front":"student-to-teacher interaction","meaning":"學生與教師互動","examples":[{"en":"Student-to-teacher interaction remains relevant in distance learning.","zh":"學生與教師互動在遙距學習中仍然相關。"},{"en":"Student-to-teacher interaction means communication from students to teachers and from teachers back to students.","zh":"student-to-teacher interaction 指學生向教師溝通，以及教師回應學生的雙向交流。"},{"en":"A student asking questions by email and receiving comments from a tutor is student-to-teacher interaction.","zh":"學生透過電郵提問並收到導師評語，就是學生與教師互動。"},{"en":"If interaction is strong, distance learners can get guidance before small problems become major difficulties.","zh":"如果互動強，遙距學習者可以在小問題變成大困難前得到指導。"},{"en":"This phrase focuses on two-way communication between learner and instructor.","zh":"這個片語聚焦於學習者與教師之間的雙向溝通。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":18},{"front":"no longer relevant","meaning":"不再相關","examples":[{"en":"The option asks whether interaction is no longer relevant.","zh":"這個選項問互動是否不再相關。"},{"en":"No longer relevant means not important or useful anymore.","zh":"no longer relevant 指不再重要或不再有用。"},{"en":"A printed bus timetable may be no longer relevant if every route has changed.","zh":"如果每條路線都已改變，紙本巴士時間表可能不再相關。"},{"en":"If students still need feedback, teacher interaction is not no longer relevant.","zh":"如果學生仍需要回饋，教師互動就不是不再相關。"},{"en":"This phrase describes something that has lost its importance in a new situation.","zh":"這個片語描述某事在新情況中失去重要性。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":18},{"front":"agree with the information","meaning":"與資料一致","examples":[{"en":"Students decide whether the statements agree with the information.","zh":"學生判斷陳述是否與資料一致。"},{"en":"To agree with the information means to match what the passage says.","zh":"agree with the information 指與文章所說內容相符。"},{"en":"If a passage says distance learners performed equally well, a statement with the same meaning agrees with the information.","zh":"如果文章說遙距學習者表現同樣好，意思相同的陳述便與資料一致。"},{"en":"Students should compare meaning carefully, not just search for the same words.","zh":"學生應仔細比較意思，而不只是搜尋相同字眼。"},{"en":"This phrase is common in TRUE, FALSE, NOT GIVEN questions.","zh":"這個片語常見於 TRUE、FALSE、NOT GIVEN 題。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":18},{"front":"contradicts the information","meaning":"與資料相矛盾","examples":[{"en":"A statement is false if it contradicts the information.","zh":"如果陳述與資料相矛盾，它就是錯誤的。"},{"en":"To contradict the information means to say the opposite of what the passage says.","zh":"contradict the information 指說出與文章所說相反的意思。"},{"en":"If the text says technology supports lab teaching, saying technology has no role contradicts the information.","zh":"如果文本說科技支援實驗教學，說科技沒有角色便與資料相矛盾。"},{"en":"Students should choose FALSE when the passage clearly gives the opposite meaning.","zh":"當文章清楚給出相反意思時，學生應選 FALSE。"},{"en":"This phrase is different from NOT GIVEN because the text provides opposing evidence.","zh":"這個片語不同於 NOT GIVEN，因為文本提供了相反證據。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":18},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有相關資料，學生則寫 NOT GIVEN。"},{"en":"No information on this means the passage does not mention the point clearly enough to judge it.","zh":"no information on this 指文章沒有清楚提及該點，不能判斷。"},{"en":"If a passage discusses course quality but not teacher salaries, there is no information on salaries.","zh":"如果文章討論課程質素但沒有討論教師薪酬，便沒有關於薪酬的相關資料。"},{"en":"Students should not use outside knowledge when the text gives no information.","zh":"當文本沒有提供資料時，學生不應使用外部知識。"},{"en":"This phrase signals that the answer cannot be confirmed from the passage.","zh":"這個片語表示答案不能由文章確認。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":18},{"front":"lack of student-to-student interaction","meaning":"缺乏學生之間的互動","examples":[{"en":"Some students may see a lack of student-to-student interaction as a disadvantage.","zh":"一些學生可能把缺乏學生之間的互動視為不利之處。"},{"en":"Lack of student-to-student interaction means there is little communication or collaboration among learners.","zh":"lack of student-to-student interaction 指學習者之間很少溝通或合作。"},{"en":"A student in an online course may feel lonely if there are no group discussions.","zh":"如果網上課程沒有小組討論，學生可能感到孤獨。"},{"en":"If students cannot share questions with classmates, they may miss peer support.","zh":"如果學生不能與同學分享問題，可能失去同儕支援。"},{"en":"This phrase describes a possible weakness of remote study.","zh":"這個片語描述遙距學習的一個可能弱點。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":18},{"front":"a disadvantage to","meaning":"對……的不利之處","examples":[{"en":"Lack of interaction may be a disadvantage to this method of study.","zh":"缺乏互動可能是這種學習方式的不利之處。"},{"en":"A disadvantage to something is a weakness or problem that makes it less effective or attractive.","zh":"disadvantage to something 是令某事較不有效或較不吸引的弱點或問題。"},{"en":"High rent is a disadvantage to opening a small café in a busy district.","zh":"高租金是在繁忙地區開小咖啡店的不利之處。"},{"en":"If a study method lacks feedback, that disadvantage may reduce motivation.","zh":"如果學習方式缺乏回饋，這個不利之處可能降低動力。"},{"en":"This phrase identifies a negative side of something.","zh":"這個片語指出某事的負面一面。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":18},{"front":"method of study","meaning":"學習方式","examples":[{"en":"Distance learning is a flexible method of study.","zh":"遙距學習是一種靈活的學習方式。"},{"en":"A method of study is a way of learning or organising learning activities.","zh":"method of study 是學習或組織學習活動的方法。"},{"en":"Reading notes aloud can be a useful method of study for language learners.","zh":"大聲朗讀筆記可以是語言學習者有用的學習方式。"},{"en":"If a method of study fits a student’s schedule, they are more likely to continue.","zh":"如果學習方式配合學生時間表，他們較有可能持續下去。"},{"en":"This phrase refers to how someone studies.","zh":"這個片語指某人如何學習。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":18},{"front":"main difference between","meaning":"……之間的主要分別","examples":[{"en":"The main difference between residential and summer schools is their duration.","zh":"住宿學校和暑期學校之間的主要分別是其持續時間。"},{"en":"The main difference between two things is the most important way they are not the same.","zh":"main difference between two things 指兩者最重要的不同之處。"},{"en":"The main difference between a quiz and an exam may be length and importance.","zh":"小測和考試之間的主要分別可能是長度和重要性。"},{"en":"If two programmes serve similar purposes, the main difference may be how long they last.","zh":"如果兩個課程發揮相似作用，主要分別可能是它們持續多久。"},{"en":"This phrase introduces the key contrast.","zh":"這個片語引入關鍵對比。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":18},{"front":"length of the courses","meaning":"課程長度","examples":[{"en":"The question asks about the length of the courses.","zh":"題目問課程長度。"},{"en":"Length of the courses means how long the courses last.","zh":"length of the courses 指課程持續多久。"},{"en":"Students often check the length of a course before deciding whether they can fit it into their schedule.","zh":"學生在決定是否能把課程排入時間表前，常會查看課程長度。"},{"en":"If a course is longer, it may allow more practice but require more commitment.","zh":"如果課程較長，它可能容許更多練習，但需要更多投入。"},{"en":"This phrase focuses on duration, not difficulty.","zh":"這個片語聚焦於持續時間，而不是難度。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":19},{"front":"difficulties exist where","meaning":"在……方面存在困難","examples":[{"en":"The statement asks whether difficulties exist where science teaching involves experiments.","zh":"該陳述問在科學教學涉及實驗方面是否存在困難。"},{"en":"Difficulties exist where something happens means problems appear in situations involving that thing.","zh":"difficulties exist where something happens 指在涉及某事的情況中會出現問題。"},{"en":"Difficulties exist where group projects have no clear roles or deadlines.","zh":"如果小組專題沒有清晰角色或截止日期，便會存在困難。"},{"en":"If science teaching requires experiments, problems may arise with equipment, safety, and assessment.","zh":"如果科學教學需要實驗，設備、安全和評核方面可能出現問題。"},{"en":"This phrase connects a type of situation with possible problems.","zh":"這個片語把某類情況與可能問題連接起來。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":19},{"front":"teaching of science subjects","meaning":"科學科目的教學","examples":[{"en":"The teaching of science subjects may involve laboratory experiments.","zh":"科學科目的教學可能涉及實驗室實驗。"},{"en":"Teaching of science subjects means instruction in subjects such as biology, chemistry, physics, or engineering science.","zh":"teaching of science subjects 指生物、化學、物理或工程科學等科目的教學。"},{"en":"The teaching of science subjects often includes observation, measurement, and explanation of natural processes.","zh":"科學科目的教學常包括觀察、測量和解釋自然過程。"},{"en":"If science teaching moves online, teachers must find ways to replace or simulate practical work.","zh":"如果科學教學轉到網上，教師必須找方法取代或模擬實踐工作。"},{"en":"This phrase refers to how science is taught.","zh":"這個片語指科學如何被教授。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":19},{"front":"involve laboratory experiments","meaning":"涉及實驗室實驗","examples":[{"en":"Science subjects often involve laboratory experiments.","zh":"科學科目常涉及實驗室實驗。"},{"en":"To involve laboratory experiments means to include practical tests or investigations carried out in a lab.","zh":"involve laboratory experiments 指包括在實驗室中進行的實踐測試或調查。"},{"en":"A chemistry course may involve laboratory experiments to show how substances react.","zh":"化學課程可能涉及實驗室實驗，以展示物質如何反應。"},{"en":"If a subject involves experiments, students need equipment, instructions, and safety rules.","zh":"如果某科目涉及實驗，學生需要設備、指示和安全規則。"},{"en":"This phrase shows that practical lab work is part of the course.","zh":"這個片語顯示實踐實驗工作是課程的一部分。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":19},{"front":"receive very high salaries","meaning":"收取很高薪酬","examples":[{"en":"The statement asks whether instructional designers receive very high salaries.","zh":"該陳述問教學設計師是否收取很高薪酬。"},{"en":"To receive very high salaries means to be paid much more than average for one’s work.","zh":"receive very high salaries 指工作獲得遠高於平均水平的薪酬。"},{"en":"Senior doctors or technology executives may receive very high salaries because their skills are in demand.","zh":"資深醫生或科技高層可能因技能需求高而收取很高薪酬。"},{"en":"If a passage does not mention pay, readers cannot assume that instructional designers are highly paid.","zh":"如果文章沒有提及薪酬，讀者不能假設教學設計師薪酬很高。"},{"en":"This phrase focuses on income level, not job importance alone.","zh":"這個片語聚焦於收入水平，而不只是工作重要性。"}],"source":"79 - DISTANCE LEARNING.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 80":[{"front":"Arctic survivors","meaning":"北極生存者","examples":[{"en":"Arctic survivors must tolerate some of the harshest conditions on Earth.","zh":"北極生存者必須忍受地球上一些最嚴酷的環境。"},{"en":"Arctic survivors are animals or people able to live in the extreme cold of the Arctic.","zh":"Arctic survivors 是能在北極極寒環境中生存的動物或人。"},{"en":"A student can imagine Arctic survivors as creatures that stay alive where most animals would freeze.","zh":"學生可以把北極生存者想像成在大多數動物會凍死的地方仍能活下來的生物。"},{"en":"Thick fur, stored energy and body heat help many Arctic survivors endure winter.","zh":"厚毛、儲存能量和體熱幫助許多北極生存者熬過冬天。"},{"en":"The phrase stresses survival in a place where ordinary life is extremely difficult.","zh":"這個短語強調在普通生命極難生存的地方存活。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":1},{"front":"the Arctic","meaning":"北極地區","examples":[{"en":"The Arctic is an area located at the northernmost part of the Earth.","zh":"北極地區是位於地球最北部的區域。"},{"en":"The Arctic is the cold northern region around the North Pole.","zh":"the Arctic 是圍繞北極點的寒冷北方地區。"},{"en":"A geography lesson about the Arctic may include ice, snow, polar night and animal survival.","zh":"關於北極地區的地理課可能包括冰、雪、極夜和動物生存。"},{"en":"Because the Arctic is extremely cold, only specially adapted plants and animals can live there.","zh":"因為北極地區極度寒冷，只有具特殊適應能力的植物和動物能在那裏生存。"},{"en":"The phrase refers to a region, not just one country or one sheet of ice.","zh":"這個短語指一個地區，而不只是一個國家或一片冰。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":1},{"front":"be located at","meaning":"位於……","examples":[{"en":"The Arctic is located at the northernmost part of the Earth.","zh":"北極地區位於地球最北部。"},{"en":"To be located at a place means to be found or positioned there.","zh":"be located at 某地，意思是位處或設於該地方。"},{"en":"The school office is located at the main entrance, so visitors can find help quickly.","zh":"學校辦公室位於正門，訪客可以很快找到協助。"},{"en":"If a hospital is located at the centre of town, more patients can reach it easily.","zh":"如果醫院位於市中心，更多病人可以容易到達。"},{"en":"The phrase is useful for giving the exact position of a place.","zh":"這個短語適合用來說明地方的確切位置。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":1},{"front":"the northernmost part of","meaning":"……最北部","examples":[{"en":"The Arctic lies at the northernmost part of the Earth.","zh":"北極地區位於地球最北部。"},{"en":"The northernmost part of a place is the area farthest north.","zh":"the northernmost part of 某地，指該地最北面的部分。"},{"en":"The northernmost part of a country may be colder than its southern cities.","zh":"一個國家的最北部可能比南部城市更寒冷。"},{"en":"If a village is in the northernmost part of a region, winter may arrive earlier there.","zh":"如果村莊位於某地區最北部，那裏冬天可能更早來臨。"},{"en":"The phrase describes location by comparing north and south.","zh":"這個短語透過南北位置來描述地點。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":1},{"front":"consist of","meaning":"由……組成","examples":[{"en":"The Arctic consists of an ice-covered ocean surrounded by permafrost.","zh":"北極地區由被冰覆蓋的海洋和周圍的永久凍土組成。"},{"en":"To consist of something means to be made up of it.","zh":"consist of 某物，意思是由它組成。"},{"en":"A healthy lunch may consist of rice, vegetables, fish and fruit.","zh":"健康午餐可能由米飯、蔬菜、魚和水果組成。"},{"en":"If a course consists of videos and quizzes, students need both watching and practice time.","zh":"如果課程由影片和小測組成，學生就需要觀看和練習時間。"},{"en":"The phrase explains what parts form a whole.","zh":"這個短語解釋整體由哪些部分形成。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":1},{"front":"an ice-covered ocean","meaning":"被冰覆蓋的海洋","examples":[{"en":"The Arctic consists of an ice-covered ocean.","zh":"北極地區由被冰覆蓋的海洋組成。"},{"en":"An ice-covered ocean is a sea area with ice lying over much of its surface.","zh":"an ice-covered ocean 是表面大部分覆蓋着冰的海洋區域。"},{"en":"In a picture, an ice-covered ocean may look like a flat white field.","zh":"在圖片中，被冰覆蓋的海洋可能看起來像一片平坦白色原野。"},{"en":"If an ocean is ice-covered, ships, animals and people must deal with freezing conditions.","zh":"如果海洋被冰覆蓋，船隻、動物和人都必須面對冰冷環境。"},{"en":"The phrase describes both water and the ice layer above it.","zh":"這個短語同時描述海水和其上的冰層。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":1},{"front":"be surrounded by","meaning":"被……包圍","examples":[{"en":"The ocean is surrounded by treeless permafrost.","zh":"這片海洋被沒有樹木的永久凍土包圍。"},{"en":"To be surrounded by something means to have it all around the outside.","zh":"be surrounded by 某物，意思是外圍四周都有它。"},{"en":"A school may be surrounded by busy roads, so students need safe crossings.","zh":"學校可能被繁忙道路包圍，所以學生需要安全過路處。"},{"en":"If a house is surrounded by trees, it may feel cooler and quieter.","zh":"如果房屋被樹木包圍，可能感覺更涼爽和安靜。"},{"en":"The phrase shows what lies around a place or object.","zh":"這個短語顯示某地方或物件周圍有甚麼。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":1},{"front":"treeless permafrost","meaning":"沒有樹木的永久凍土","examples":[{"en":"The Arctic Ocean is surrounded by treeless permafrost.","zh":"北冰洋被沒有樹木的永久凍土包圍。"},{"en":"Treeless permafrost is permanently frozen ground where trees cannot grow.","zh":"treeless permafrost 是樹木無法生長的永久冰凍土地。"},{"en":"A scientist studying treeless permafrost may see low plants but no forests.","zh":"研究沒有樹木的永久凍土的科學家可能看到矮小植物，但看不到森林。"},{"en":"Because the ground stays frozen, treeless permafrost limits plant roots and growth.","zh":"因為地面長期冰凍，沒有樹木的永久凍土限制植物根部和生長。"},{"en":"The phrase combines a frozen landscape with the absence of trees.","zh":"這個短語結合冰凍地貌和沒有樹木的特徵。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":1},{"front":"be defined as","meaning":"被定義為","examples":[{"en":"The area can be defined as north of the Arctic Circle.","zh":"該地區可被定義為北極圈以北的地方。"},{"en":"To be defined as something means to be explained or described in that exact way.","zh":"be defined as 某物，意思是被清楚解釋或描述為那樣。"},{"en":"In class, plagiarism can be defined as using another person’s work without proper credit.","zh":"在課堂中，抄襲可被定義為沒有適當注明而使用他人的作品。"},{"en":"If a term is clearly defined, students are less likely to misunderstand it.","zh":"如果術語被清楚定義，學生就較不容易誤解。"},{"en":"The phrase is useful when giving a precise meaning or boundary.","zh":"這個短語適合用於給出精確意思或界線。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":1},{"front":"the Arctic Circle","meaning":"北極圈","examples":[{"en":"The Arctic can be defined as the area north of the Arctic Circle.","zh":"北極地區可被定義為北極圈以北的地方。"},{"en":"The Arctic Circle is an imaginary line around the northern part of the Earth.","zh":"the Arctic Circle 是圍繞地球北部的一條想像線。"},{"en":"A map lesson may show the Arctic Circle as a boundary near the far north.","zh":"地圖課可能把北極圈展示為接近極北地區的界線。"},{"en":"North of the Arctic Circle, places may experience the midnight sun and polar night.","zh":"在北極圈以北，某些地方可能經歷午夜太陽和極夜。"},{"en":"The phrase names an important geographical line.","zh":"這個短語指出一條重要地理線。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":1},{"front":"approximate limit of","meaning":"……的大概界線","examples":[{"en":"The Arctic Circle is the approximate limit of the midnight sun.","zh":"北極圈是午夜太陽的大概界線。"},{"en":"The approximate limit of something is the rough boundary where it begins or ends.","zh":"approximate limit of 某事，是它開始或結束的大概邊界。"},{"en":"A school zone sign may show the approximate limit of where drivers should slow down.","zh":"校區標誌可能顯示司機應減速範圍的大概界線。"},{"en":"If a map gives only an approximate limit, the real boundary may vary slightly.","zh":"如果地圖只提供大概界線，真實邊界可能略有變化。"},{"en":"The phrase gives a general boundary, not a perfectly exact one.","zh":"這個短語給出一般界線，而不是完全精確的界線。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":2},{"front":"the midnight sun","meaning":"午夜太陽","examples":[{"en":"The midnight sun can be seen in parts of the Arctic.","zh":"在北極部分地區可以看到午夜太陽。"},{"en":"The midnight sun is the natural event when the sun remains visible at midnight.","zh":"the midnight sun 是太陽在午夜仍然可見的自然現象。"},{"en":"Tourists may travel north to see the midnight sun during summer.","zh":"遊客可能在夏天到北方觀看午夜太陽。"},{"en":"Because of the midnight sun, some Arctic places have long bright days.","zh":"因為有午夜太陽，一些北極地方會有漫長明亮的日子。"},{"en":"The phrase describes sunlight at a time when people usually expect darkness.","zh":"這個短語描述在人們通常預期黑暗的時候仍有陽光。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":2},{"front":"the polar night","meaning":"極夜","examples":[{"en":"The polar night occurs in the Arctic region.","zh":"極夜出現在北極地區。"},{"en":"The polar night is a period when the sun does not rise above the horizon.","zh":"the polar night 是太陽不升到地平線以上的一段時期。"},{"en":"During the polar night, a town may stay dark even at lunchtime.","zh":"在極夜期間，城鎮即使在午餐時間也可能保持黑暗。"},{"en":"Because the polar night brings long darkness, people and animals must adjust their routines.","zh":"因為極夜帶來長時間黑暗，人和動物都必須調整日常規律。"},{"en":"The phrase describes extended darkness in polar regions.","zh":"這個短語描述極地地區的長時間黑暗。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":2},{"front":"average temperature","meaning":"平均氣溫","examples":[{"en":"The average temperature in July is below 10°C.","zh":"七月的平均氣溫低於攝氏10度。"},{"en":"Average temperature means the usual temperature calculated from many measurements.","zh":"average temperature 是由多次測量計算出的通常氣溫。"},{"en":"A city’s average temperature in summer helps people decide what clothes to pack.","zh":"城市夏天的平均氣溫幫助人們決定帶甚麼衣服。"},{"en":"If the average temperature stays low, plants may grow slowly or not at all.","zh":"如果平均氣溫一直很低，植物可能生長緩慢甚至不能生長。"},{"en":"The phrase gives a general climate measure, not one single day’s weather.","zh":"這個短語提供一般氣候量度，而不是某一天的天氣。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":2},{"front":"the warmest month","meaning":"最溫暖的月份","examples":[{"en":"July is the warmest month in the Arctic.","zh":"七月是北極最溫暖的月份。"},{"en":"The warmest month is the month with the highest average temperature in a year.","zh":"the warmest month 是一年中平均氣溫最高的月份。"},{"en":"In some countries, August is the warmest month, so families go swimming then.","zh":"在一些國家，八月是最溫暖的月份，所以家庭會在那時游泳。"},{"en":"If even the warmest month is cold, the whole climate is severe.","zh":"如果連最溫暖的月份都很冷，整個氣候就很嚴酷。"},{"en":"The phrase helps compare temperatures across the year.","zh":"這個短語幫助比較全年氣溫。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":2},{"front":"below 10°C","meaning":"低於攝氏10度","examples":[{"en":"The average temperature in July is below 10°C.","zh":"七月平均氣溫低於攝氏10度。"},{"en":"Below 10°C means lower than ten degrees Celsius.","zh":"below 10°C 指低於攝氏十度。"},{"en":"If a classroom is below 10°C, students may need coats to stay comfortable.","zh":"如果課室低於攝氏10度，學生可能需要穿外套才舒服。"},{"en":"When summer temperatures are below 10°C, many trees cannot grow well.","zh":"當夏季氣溫低於攝氏10度，許多樹木不能良好生長。"},{"en":"The phrase gives a clear temperature limit.","zh":"這個短語給出清楚的氣溫界線。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":2},{"front":"colder summer temperatures","meaning":"較冷的夏季氣溫","examples":[{"en":"Colder summer temperatures affect plant growth in the Arctic.","zh":"較冷的夏季氣溫影響北極植物生長。"},{"en":"Colder summer temperatures are lower-than-usual temperatures during the summer season.","zh":"colder summer temperatures 是夏季期間比一般更低的氣溫。"},{"en":"Farmers may worry about colder summer temperatures because crops need warmth to grow.","zh":"農民可能擔心較冷的夏季氣溫，因為農作物需要溫暖才能生長。"},{"en":"In the Arctic, colder summer temperatures reduce how tall and varied plants can become.","zh":"在北極，較冷的夏季氣溫會限制植物高度和種類。"},{"en":"The phrase explains why summer is still difficult for life.","zh":"這個短語解釋為何夏天對生命仍然困難。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":2},{"front":"cause something to decrease","meaning":"導致……減少","examples":[{"en":"Cold summer temperatures cause the variety of plants to decrease.","zh":"寒冷夏季氣溫導致植物種類減少。"},{"en":"To cause something to decrease means to make it become smaller in number, amount or level.","zh":"cause something to decrease 指令某物在數量、金額或水平上變少。"},{"en":"Fewer buses can cause school attendance to decrease if students cannot travel easily.","zh":"如果學生難以交通往返，巴士減少可能導致上學率下降。"},{"en":"If food prices rise sharply, family spending on non-essential items may decrease.","zh":"如果食物價格急升，家庭在非必需品上的開支可能減少。"},{"en":"The phrase connects a cause with a reduction.","zh":"這個短語把原因與減少連繫起來。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":2},{"front":"size, abundance, productivity and variety","meaning":"大小、數量、生產力和種類","examples":[{"en":"Cold temperatures reduce the size, abundance, productivity and variety of plants.","zh":"寒冷氣溫降低植物的大小、數量、生產力和種類。"},{"en":"Size, abundance, productivity and variety describe how big, common, productive and diverse living things are.","zh":"size, abundance, productivity and variety 描述生物有多大、有多常見、有多高產和有多多樣。"},{"en":"A garden with good soil may show greater size, abundance, productivity and variety.","zh":"土壤良好的花園可能有更大的大小、數量、生產力和種類。"},{"en":"If weather becomes harsher, plants may become smaller, fewer, less productive and less varied.","zh":"如果天氣變得更嚴酷，植物可能更細小、更少、產量更低且種類更少。"},{"en":"The phrase lists several ways plant life can be limited.","zh":"這個短語列出植物生命受限制的幾種方式。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":2},{"front":"cannot grow in","meaning":"不能在……生長","examples":[{"en":"Trees cannot grow in the Arctic.","zh":"樹木不能在北極生長。"},{"en":"Cannot grow in a place means unable to survive and develop there.","zh":"cannot grow in 某地，意思是無法在那裏存活和發展。"},{"en":"Some flowers cannot grow in a dark room because they need sunlight.","zh":"有些花不能在黑暗房間生長，因為它們需要陽光。"},{"en":"If the ground is frozen most of the year, large tree roots cannot grow properly.","zh":"如果地面全年大部分時間冰凍，大樹根就不能正常生長。"},{"en":"The phrase explains why some living things are absent from a place.","zh":"這個短語解釋為何某些生物不會出現在某地方。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":2},{"front":"in its warmest parts","meaning":"在其最溫暖的地區","examples":[{"en":"Shrubs are common in the warmest parts of the Arctic.","zh":"灌木在北極最溫暖的地區很常見。"},{"en":"In its warmest parts means in the areas of a place that have the highest temperatures.","zh":"in its warmest parts 指在某地方氣溫最高的區域。"},{"en":"In the warmest parts of a school garden, flowers may bloom earlier.","zh":"在學校花園最溫暖的地方，花可能較早開。"},{"en":"If plants grow only in the warmest parts, the rest of the region is too cold for them.","zh":"如果植物只在最溫暖的地區生長，該地區其他部分對它們來說就太冷。"},{"en":"The phrase compares different areas within the same region.","zh":"這個短語比較同一地區內的不同區域。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":3},{"front":"shrubs are common","meaning":"灌木很常見","examples":[{"en":"Shrubs are common in the warmest parts of the Arctic.","zh":"灌木在北極最溫暖的地區很常見。"},{"en":"Shrubs are common means small woody plants are often found there.","zh":"shrubs are common 指小型木本植物經常在那裏出現。"},{"en":"Shrubs are common beside some school paths because they are easy to maintain.","zh":"灌木在一些學校小徑旁很常見，因為它們容易打理。"},{"en":"If shrubs are common in one area, the climate there may be mild enough for low plants.","zh":"如果灌木在某區很常見，那裏氣候可能溫和到足以讓低矮植物生長。"},{"en":"The phrase describes what plants are frequently present.","zh":"這個短語描述哪些植物經常存在。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":3},{"front":"reach 2 metres in height","meaning":"高達2米","examples":[{"en":"Shrubs can reach 2 metres in height.","zh":"灌木可以高達2米。"},{"en":"To reach 2 metres in height means to grow until something is two metres tall.","zh":"reach 2 metres in height 指生長到兩米高。"},{"en":"A young tree in a garden may reach 2 metres in height after several years.","zh":"花園裏的小樹幾年後可能高達2米。"},{"en":"If shrubs reach 2 metres in height, they can shelter small animals from wind.","zh":"如果灌木高達2米，它們可以為小動物擋風。"},{"en":"The phrase gives a clear measurement of height.","zh":"這個短語給出清楚的高度量度。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":3},{"front":"a thick blanket of snow","meaning":"厚厚一層雪","examples":[{"en":"A thick blanket of snow lies over the ground.","zh":"厚厚一層雪覆蓋在地面上。"},{"en":"A thick blanket of snow means a deep, continuous layer of snow covering an area.","zh":"a thick blanket of snow 指覆蓋一個地區的深而連續的雪層。"},{"en":"After a heavy snowstorm, a thick blanket of snow may cover cars and roads.","zh":"大雪暴後，厚厚一層雪可能覆蓋汽車和道路。"},{"en":"If a thick blanket of snow covers the ground, small animals may hide beneath it.","zh":"如果厚厚一層雪覆蓋地面，小動物可能藏在下面。"},{"en":"The phrase uses “blanket” to show snow covering everything.","zh":"這個短語用 blanket 來表示雪覆蓋一切。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":3},{"front":"lie several feet deep","meaning":"有數英尺深","examples":[{"en":"Snow lies several feet deep all over the ground.","zh":"雪遍佈地面，有數英尺深。"},{"en":"To lie several feet deep means to cover a surface with a depth of several feet.","zh":"lie several feet deep 指以數英尺深度覆蓋表面。"},{"en":"After a mountain storm, snow may lie several feet deep on the path.","zh":"山區暴風雪後，小徑上的雪可能有數英尺深。"},{"en":"If snow lies several feet deep, walking and driving become difficult.","zh":"如果雪有數英尺深，步行和駕駛都會變困難。"},{"en":"The phrase describes depth, not just light snow on the surface.","zh":"這個短語描述深度，而不只是表面薄雪。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":3},{"front":"all over the ground","meaning":"遍佈地面","examples":[{"en":"A thick blanket of snow lies all over the ground.","zh":"厚厚一層雪遍佈地面。"},{"en":"All over the ground means covering the whole ground area.","zh":"all over the ground 指覆蓋整個地面範圍。"},{"en":"After children finish a craft lesson, paper pieces may be all over the ground.","zh":"孩子完成手工課後，紙碎可能遍佈地面。"},{"en":"If ice is all over the ground, people may slip unless paths are cleared.","zh":"如果冰遍佈地面，除非清理路徑，否則人們可能滑倒。"},{"en":"The phrase shows that something is spread everywhere on the surface.","zh":"這個短語顯示某物散佈在表面各處。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":3},{"front":"a few brief hours","meaning":"短短幾小時","examples":[{"en":"The sun appears for only a few brief hours each day.","zh":"太陽每天只出現短短幾小時。"},{"en":"A few brief hours means a short period of only several hours.","zh":"a few brief hours 指只有幾小時的短時間。"},{"en":"Students may have only a few brief hours to revise after school.","zh":"學生放學後可能只有短短幾小時溫習。"},{"en":"If daylight lasts for only a few brief hours, daily work must be planned carefully.","zh":"如果日光只持續短短幾小時，日常工作就必須小心安排。"},{"en":"The phrase stresses that the time is short.","zh":"這個短語強調時間很短。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":3},{"front":"sink below the horizon","meaning":"沉到地平線以下","examples":[{"en":"The sun sinks below the horizon after only a few hours.","zh":"太陽只出現幾小時後便沉到地平線以下。"},{"en":"To sink below the horizon means to move out of sight below the line where sky meets land or sea.","zh":"sink below the horizon 指移到天空與陸地或海洋相接線以下而看不見。"},{"en":"Families may watch the sun sink below the horizon during a beach holiday.","zh":"家庭在海灘度假時，可能觀看太陽沉到地平線以下。"},{"en":"When the sun sinks below the horizon, light fades and temperatures may fall.","zh":"當太陽沉到地平線以下，光線會變暗，氣溫可能下降。"},{"en":"The phrase describes sunset in a visual way.","zh":"這個短語以視覺方式描述日落。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":3},{"front":"blackness cloaks the land","meaning":"黑暗籠罩大地","examples":[{"en":"Blackness cloaks the land after the sun vanishes.","zh":"太陽消失後，黑暗籠罩大地。"},{"en":"Blackness cloaks the land means darkness covers the whole area.","zh":"blackness cloaks the land 指黑暗覆蓋整個地區。"},{"en":"During a power cut, blackness may cloak a neighbourhood within seconds.","zh":"停電時，黑暗可能在數秒內籠罩整個社區。"},{"en":"If blackness cloaks the land, people and animals must move without daylight.","zh":"如果黑暗籠罩大地，人和動物就必須在沒有日光下活動。"},{"en":"The phrase is slightly poetic but clearly means darkness covers everything.","zh":"這個短語略帶詩意，但清楚表示黑暗覆蓋一切。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":3},{"front":"as it vanishes","meaning":"當它消失時","examples":[{"en":"As the sun vanishes, a bitter chill tightens its grip.","zh":"當太陽消失時，刺骨寒意變得更強烈。"},{"en":"As it vanishes means while it disappears from sight.","zh":"as it vanishes 指當它從視線中消失時。"},{"en":"As the bus vanishes around the corner, the student realises he has missed it.","zh":"當巴士在街角消失時，學生意識到自己錯過了它。"},{"en":"As daylight vanishes, the temperature may drop and visibility becomes worse.","zh":"當日光消失時，氣溫可能下降，能見度也變差。"},{"en":"The phrase connects one action with what happens at the same time.","zh":"這個短語把一個動作與同時發生的事連繫起來。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":3},{"front":"a bitter chill","meaning":"刺骨寒意","examples":[{"en":"A bitter chill tightens its grip over the Arctic.","zh":"刺骨寒意在北極變得更強烈。"},{"en":"A bitter chill is a very sharp and unpleasant coldness.","zh":"a bitter chill 是非常尖銳而令人不舒服的寒冷。"},{"en":"A bitter chill filled the classroom when the heating stopped on a winter morning.","zh":"冬天早上暖氣停止時，刺骨寒意充滿課室。"},{"en":"If a bitter chill arrives, people need coats, gloves and shelter.","zh":"如果刺骨寒意來臨，人們需要外套、手套和遮蔽處。"},{"en":"The phrase describes cold that feels harsh and painful.","zh":"這個短語描述令人感到嚴酷和疼痛的寒冷。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":4},{"front":"tighten its grip","meaning":"加強控制；變得更強烈","examples":[{"en":"The cold tightens its grip as darkness falls.","zh":"黑暗降臨時，寒冷變得更強烈。"},{"en":"To tighten its grip means to become stronger and harder to escape.","zh":"tighten its grip 指變得更強，令人更難擺脫。"},{"en":"Stress may tighten its grip on students when exams get closer.","zh":"當考試臨近，壓力可能對學生加強控制。"},{"en":"If winter tightens its grip, roads freeze and outdoor work becomes harder.","zh":"如果冬天變得更強烈，道路會結冰，戶外工作會更困難。"},{"en":"The phrase describes a force gaining control.","zh":"這個短語描述一股力量逐漸取得控制。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":4},{"front":"in the throes of winter","meaning":"在嚴冬之中","examples":[{"en":"The Arctic is extremely hostile in the throes of winter.","zh":"在嚴冬之中，北極極度不適合生存。"},{"en":"In the throes of winter means during the deepest and harshest part of winter.","zh":"in the throes of winter 指在冬天最深、最嚴酷的時期。"},{"en":"In the throes of winter, a village may close roads because of snow and ice.","zh":"在嚴冬之中，村莊可能因雪和冰而封路。"},{"en":"If a city is in the throes of winter, heating and transport become essential.","zh":"如果城市處於嚴冬之中，暖氣和交通就變得必不可少。"},{"en":"The phrase suggests winter at its most difficult stage.","zh":"這個短語暗示冬天最艱難的階段。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":4},{"front":"be hostile to","meaning":"對……極不友善；不適合……","examples":[{"en":"The Arctic is hostile to almost all animal life.","zh":"北極對幾乎所有動物生命都極不友善。"},{"en":"To be hostile to something means to be dangerous, unfriendly or unsuitable for it.","zh":"be hostile to 某物，指對它危險、不友善或不適合。"},{"en":"A noisy classroom can be hostile to students who need quiet to concentrate.","zh":"嘈吵課室對需要安靜集中精神的學生來說可能很不友善。"},{"en":"If a desert is hostile to plants, only specially adapted species can survive there.","zh":"如果沙漠對植物很不適合，只有特別適應的物種能在那裏生存。"},{"en":"The phrase describes conditions that make life or success difficult.","zh":"這個短語描述令生命或成功變得困難的環境。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":4},{"front":"animal life","meaning":"動物生命","examples":[{"en":"The Arctic is hostile to almost all animal life.","zh":"北極對幾乎所有動物生命都極不友善。"},{"en":"Animal life means the animals living in a place or environment.","zh":"animal life 指生活在某地方或環境中的動物。"},{"en":"A clean river supports animal life such as fish, insects and birds.","zh":"清潔河流支撐魚類、昆蟲和鳥類等動物生命。"},{"en":"If pollution increases, animal life in a lake may decrease quickly.","zh":"如果污染增加，湖中的動物生命可能迅速減少。"},{"en":"The phrase refers to living animals as part of an ecosystem.","zh":"這個短語指作為生態系統一部分的活着動物。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":4},{"front":"amphibians","meaning":"兩棲動物","examples":[{"en":"Amphibians would freeze solid in the Arctic winter.","zh":"兩棲動物會在北極冬季凍成硬塊。"},{"en":"Amphibians are animals such as frogs and toads that often live both in water and on land.","zh":"amphibians 是青蛙和蟾蜍等常在水中和陸上生活的動物。"},{"en":"Children may see amphibians near ponds after rain.","zh":"孩子在下雨後可能在池塘附近看到兩棲動物。"},{"en":"Because amphibians cannot produce enough body heat, extreme cold can kill them quickly.","zh":"因為兩棲動物不能產生足夠體熱，極寒可以很快殺死牠們。"},{"en":"The word names a class of animals that is poorly suited to Arctic winter.","zh":"這個字指出一類很不適合北極冬季的動物。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":4},{"front":"freeze solid","meaning":"凍成硬塊","examples":[{"en":"Amphibians would freeze solid in the extreme cold.","zh":"兩棲動物會在極寒中凍成硬塊。"},{"en":"To freeze solid means to become completely hard because of freezing temperatures.","zh":"freeze solid 指因冰冷氣溫而完全變硬。"},{"en":"A bottle of water may freeze solid if left outside overnight in winter.","zh":"一瓶水如果冬夜放在戶外，可能凍成硬塊。"},{"en":"If an animal freezes solid, its body can no longer function normally.","zh":"如果動物凍成硬塊，牠的身體就不能正常運作。"},{"en":"The phrase describes complete freezing, not just feeling cold.","zh":"這個短語描述完全結冰，而不只是感到寒冷。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":4},{"front":"reptiles","meaning":"爬行動物","examples":[{"en":"Reptiles cannot withstand the extreme cold of the Arctic.","zh":"爬行動物不能抵禦北極的極度寒冷。"},{"en":"Reptiles are animals such as snakes, lizards and turtles.","zh":"reptiles 是蛇、蜥蜴和龜等動物。"},{"en":"Many reptiles need warm surroundings to stay active.","zh":"許多爬行動物需要溫暖環境才能保持活躍。"},{"en":"If reptiles face severe cold, their body processes slow down dangerously.","zh":"如果爬行動物面對嚴寒，牠們的身體運作會危險地變慢。"},{"en":"The word names a class of animals that generally depends on external warmth.","zh":"這個字指出一類通常依賴外界溫暖的動物。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":4},{"front":"withstand the extreme cold","meaning":"抵禦極度寒冷","examples":[{"en":"Reptiles cannot withstand the extreme cold.","zh":"爬行動物不能抵禦極度寒冷。"},{"en":"To withstand the extreme cold means to survive or resist very low temperatures.","zh":"withstand the extreme cold 指在極低溫下生存或抵抗它。"},{"en":"Good winter coats help hikers withstand the extreme cold on snowy mountains.","zh":"良好冬衣幫助遠足者在雪山抵禦極度寒冷。"},{"en":"If a plant cannot withstand the extreme cold, it dies when frost arrives.","zh":"如果植物不能抵禦極度寒冷，霜凍來臨時就會死亡。"},{"en":"The phrase stresses strength against harsh temperature.","zh":"這個短語強調對抗嚴寒的能力。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":4},{"front":"and yet","meaning":"然而","examples":[{"en":"The Arctic is hostile, and yet some animals survive there.","zh":"北極極不適合生存，然而一些動物仍在那裏存活。"},{"en":"And yet means but surprisingly, despite what has just been said.","zh":"and yet 指然而，帶有「儘管剛才所說如此仍然」的意思。"},{"en":"The exam was difficult, and yet many students passed because they prepared well.","zh":"考試很難，然而許多學生因準備充分而合格。"},{"en":"A shop may be small, and yet it can beat larger stores through better service.","zh":"商店可能很小，然而它可以靠更好服務勝過大店。"},{"en":"The phrase introduces a surprising contrast.","zh":"這個短語引出令人意外的對比。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":4},{"front":"exhibit a remarkable tolerance of","meaning":"對……表現出驚人的耐受力","examples":[{"en":"Some animals exhibit a remarkable tolerance of extreme conditions.","zh":"一些動物對極端環境表現出驚人的耐受力。"},{"en":"To exhibit a remarkable tolerance of something means to show an unusually strong ability to endure it.","zh":"exhibit a remarkable tolerance of 某事，指表現出異常強的忍受能力。"},{"en":"Some students exhibit a remarkable tolerance of noise when they study on crowded trains.","zh":"有些學生在擠迫火車上溫習時，對噪音表現出驚人的耐受力。"},{"en":"If animals tolerate severe cold, they can survive where others die.","zh":"如果動物能忍受嚴寒，牠們就能在其他動物死亡的地方生存。"},{"en":"The phrase highlights an impressive ability to endure hardship.","zh":"這個短語突出令人印象深刻的忍耐艱難能力。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":5},{"front":"remarkable tolerance","meaning":"驚人的耐受力","examples":[{"en":"Arctic animals show remarkable tolerance of inhospitable conditions.","zh":"北極動物對惡劣環境表現出驚人的耐受力。"},{"en":"Remarkable tolerance means an unusually strong ability to endure difficulty.","zh":"remarkable tolerance 指異常強的忍受困難能力。"},{"en":"A nurse may show remarkable tolerance during a long and stressful emergency shift.","zh":"護士在漫長而壓力大的急症班中可能表現出驚人的耐受力。"},{"en":"If a species has remarkable tolerance of cold, it can remain active in winter.","zh":"如果一個物種對寒冷有驚人的耐受力，它可以在冬季保持活躍。"},{"en":"The phrase praises endurance that is clearly above normal.","zh":"這個短語讚揚明顯超出平常的忍耐力。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":5},{"front":"inhospitable conditions","meaning":"惡劣得不宜居住的環境","examples":[{"en":"Few animals can survive the most inhospitable conditions on the planet.","zh":"很少動物能在地球上最惡劣得不宜居住的環境中生存。"},{"en":"Inhospitable conditions are environments that are difficult or dangerous to live in.","zh":"inhospitable conditions 是難以或危險地生存的環境。"},{"en":"A desert without water creates inhospitable conditions for most plants.","zh":"沒有水的沙漠為大多數植物造成不宜居住的環境。"},{"en":"If conditions are inhospitable, life needs special adaptations to survive.","zh":"如果環境惡劣得不宜居住，生命就需要特殊適應才能存活。"},{"en":"The phrase describes places that do not support ordinary living easily.","zh":"這個短語描述不容易支持普通生活的地方。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":5},{"front":"on the planet","meaning":"地球上","examples":[{"en":"The Arctic has some of the harshest conditions on the planet.","zh":"北極有地球上一些最嚴酷的環境。"},{"en":"On the planet means on Earth.","zh":"on the planet 指在地球上。"},{"en":"Some of the driest deserts on the planet receive almost no rain.","zh":"地球上一些最乾旱的沙漠幾乎沒有雨。"},{"en":"If a place is among the coldest on the planet, ordinary animals cannot live there easily.","zh":"如果一個地方屬於地球上最寒冷地區之一，普通動物就難以在那裏生活。"},{"en":"The phrase widens the comparison to the whole Earth.","zh":"這個短語把比較範圍擴大到整個地球。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":5},{"front":"beneath the surface of","meaning":"在……表面以下","examples":[{"en":"A lemming moves beneath the surface of the snow.","zh":"旅鼠在雪的表面以下移動。"},{"en":"Beneath the surface of something means under its outer layer.","zh":"beneath the surface of 某物，指在其外層下面。"},{"en":"Fish may swim beneath the surface of a quiet pond.","zh":"魚可能在平靜池塘的表面以下游動。"},{"en":"If animals live beneath the surface of snow, they are protected from wind above.","zh":"如果動物住在雪的表面以下，牠們可免受上方寒風直接侵襲。"},{"en":"The phrase shows a position hidden under the outside.","zh":"這個短語顯示隱藏在外表下面的位置。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":5},{"front":"a furry white creature","meaning":"毛茸茸的白色生物","examples":[{"en":"A furry white creature scurries along a tunnel.","zh":"一隻毛茸茸的白色生物沿着隧道急速小跑。"},{"en":"A furry white creature is a small animal covered with soft white hair.","zh":"a furry white creature 是覆蓋着柔軟白毛的小動物。"},{"en":"A child may describe a pet rabbit as a furry white creature.","zh":"孩子可能把寵物兔形容為毛茸茸的白色生物。"},{"en":"White fur can help a small Arctic creature blend into snowy surroundings.","zh":"白色毛皮可以幫助北極小生物融入雪地環境。"},{"en":"The phrase gives a simple visual description of the animal.","zh":"這個短語給出動物的簡單視覺描述。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":5},{"front":"no bigger than","meaning":"不比……大","examples":[{"en":"The creature is no bigger than a hamster.","zh":"這生物不比倉鼠大。"},{"en":"No bigger than something means not larger than it.","zh":"no bigger than 某物，意思是不比它大。"},{"en":"The new camera is no bigger than a credit card, so it fits in a pocket.","zh":"新相機不比信用卡大，所以可放入口袋。"},{"en":"If an animal is no bigger than a hamster, it can hide in small spaces.","zh":"如果動物不比倉鼠大，就能藏在細小空間裏。"},{"en":"The phrase uses comparison to show small size.","zh":"這個短語用比較顯示細小體型。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":5},{"front":"scurry along","meaning":"急速小跑","examples":[{"en":"The lemming scurries along a tunnel beneath the snow.","zh":"旅鼠在雪下隧道中急速小跑。"},{"en":"To scurry along means to move quickly with short, hurried steps.","zh":"scurry along 指用短而急促的步伐快速移動。"},{"en":"A mouse may scurry along a kitchen wall when the light is turned on.","zh":"開燈時，老鼠可能沿廚房牆邊急速小跑。"},{"en":"If a small animal scurries along, it may be trying to avoid danger.","zh":"如果小動物急速小跑，它可能正在避開危險。"},{"en":"The phrase suggests fast, nervous movement.","zh":"這個短語暗示快速而緊張的移動。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":5},{"front":"a collared lemming","meaning":"領旅鼠","examples":[{"en":"A collared lemming lives under the snow.","zh":"領旅鼠住在雪下。"},{"en":"A collared lemming is a small Arctic rodent with fur adapted for cold conditions.","zh":"a collared lemming 是一種小型北極嚙齒動物，毛皮適應寒冷環境。"},{"en":"In a nature lesson, students may learn how a collared lemming survives under snow.","zh":"在自然課中，學生可能學習領旅鼠如何在雪下生存。"},{"en":"Because it is small, a collared lemming needs shelter and insulation to conserve heat.","zh":"因為體型細小，領旅鼠需要遮蔽和保溫來保存熱量。"},{"en":"The phrase names a specific Arctic animal.","zh":"這個短語指出一種特定北極動物。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":5},{"front":"members of its family","meaning":"其同類成員","examples":[{"en":"The lemming and other members of its family live in the snow field.","zh":"這隻旅鼠和其同類成員住在雪原中。"},{"en":"Members of its family means other animals belonging to the same related group.","zh":"members of its family 指屬於同一相關群體的其他動物。"},{"en":"A puppy and other members of its family may share the same brown fur.","zh":"小狗和其同類成員可能有相同啡色毛皮。"},{"en":"If members of a family live together, they may share shelter and protection.","zh":"如果同類成員一起生活，牠們可能共享住所和保護。"},{"en":"The phrase connects one animal with its relatives or group.","zh":"這個短語把一隻動物與其親屬或群體連繫起來。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":5},{"front":"excavate a complex home","meaning":"挖掘出複雜的居所","examples":[{"en":"The lemmings have excavated a complex home within the snow field.","zh":"旅鼠在雪原之中挖掘出複雜的居所。"},{"en":"To excavate a complex home means to dig out a detailed shelter with many parts.","zh":"excavate a complex home 指挖出有許多部分的精細庇護所。"},{"en":"Children may excavate tunnels in sand when building a detailed beach castle.","zh":"孩子在沙灘建造詳細沙堡時，可能挖出隧道。"},{"en":"If animals excavate a complex home, they can hide, travel and rest safely inside it.","zh":"如果動物挖掘出複雜居所，牠們可以在裏面安全躲藏、移動和休息。"},{"en":"The phrase shows careful digging, not a simple hole.","zh":"這個短語顯示仔細挖掘，而不是簡單洞穴。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":6},{"front":"within the snow field","meaning":"在雪原之中","examples":[{"en":"The lemmings live within the snow field.","zh":"旅鼠住在雪原之中。"},{"en":"Within the snow field means inside the broad area covered by snow.","zh":"within the snow field 指在大片被雪覆蓋的區域內。"},{"en":"Skiers may build markers within the snow field so they do not lose the route.","zh":"滑雪者可能在雪原之中設置標記，以免迷路。"},{"en":"If animals live within the snow field, the snow itself becomes part of their shelter.","zh":"如果動物住在雪原之中，雪本身就成為其庇護的一部分。"},{"en":"The phrase places something inside a snowy area.","zh":"這個短語把某物放在雪地區域內。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":6},{"front":"cost someone a great deal","meaning":"令某人付出很大代價","examples":[{"en":"It costs the lemmings a great deal to survive in the Arctic.","zh":"在北極生存令旅鼠付出很大代價。"},{"en":"To cost someone a great deal means to require much effort, energy, money or sacrifice.","zh":"cost someone a great deal 指需要大量努力、能量、金錢或犧牲。"},{"en":"Passing a difficult exam may cost a student a great deal of time and sleep.","zh":"通過艱難考試可能令學生付出大量時間和睡眠。"},{"en":"If survival costs animals a great deal, they must save energy whenever possible.","zh":"如果生存令動物付出很大代價，牠們就必須盡量保存能量。"},{"en":"The phrase shows that something is expensive in a broad sense.","zh":"這個短語顯示某事在廣義上很昂貴。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":6},{"front":"precious and scarce","meaning":"珍貴而稀少的","examples":[{"en":"The lemmings use their precious and scarce food supply to generate heat.","zh":"旅鼠使用珍貴而稀少的食物供應來產生熱量。"},{"en":"Precious and scarce means valuable because there is very little of it.","zh":"precious and scarce 指因數量很少而十分有價值。"},{"en":"During a water shortage, clean drinking water becomes precious and scarce.","zh":"缺水期間，乾淨飲用水變得珍貴而稀少。"},{"en":"If food is precious and scarce, animals cannot afford to waste energy.","zh":"如果食物珍貴而稀少，動物就不能浪費能量。"},{"en":"The phrase stresses both value and shortage.","zh":"這個短語同時強調價值和短缺。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":6},{"front":"food supply","meaning":"食物供應","examples":[{"en":"The lemmings use part of their food supply to produce heat.","zh":"旅鼠使用部分食物供應來產生熱量。"},{"en":"Food supply is the amount of food available to a person, animal or community.","zh":"food supply 是人、動物或社區可用的食物數量。"},{"en":"A school camp must check its food supply before taking students to a remote area.","zh":"學校營地帶學生到偏遠地區前，必須檢查食物供應。"},{"en":"If the food supply becomes smaller, animals may lose weight or migrate.","zh":"如果食物供應減少，動物可能變瘦或遷移。"},{"en":"The phrase refers to available food, not one meal only.","zh":"這個短語指可用食物，而不只是某一餐。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":6},{"front":"generate heat","meaning":"產生熱量","examples":[{"en":"Arctic animals generate heat within their bodies.","zh":"北極動物在體內產生熱量。"},{"en":"To generate heat means to produce warmth.","zh":"generate heat 指產生溫暖。"},{"en":"Running up stairs can generate heat in the body and make a person sweat.","zh":"跑上樓梯可以在身體內產生熱量，令人流汗。"},{"en":"If an animal can generate heat, it can stay active even when the air is cold.","zh":"如果動物能產生熱量，即使空氣寒冷也能保持活躍。"},{"en":"The phrase describes producing warmth rather than receiving it from outside.","zh":"這個短語描述產生溫暖，而不是從外界接受熱量。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":6},{"front":"within their bodies","meaning":"在牠們體內","examples":[{"en":"The lemmings generate heat within their bodies.","zh":"旅鼠在牠們體內產生熱量。"},{"en":"Within their bodies means inside their own bodies.","zh":"within their bodies 指在牠們自己的身體內部。"},{"en":"People digest food within their bodies to release energy.","zh":"人在體內消化食物以釋放能量。"},{"en":"If animals produce heat within their bodies, they do not depend completely on warm weather.","zh":"如果動物在體內產生熱量，牠們就不完全依賴溫暖天氣。"},{"en":"The phrase points to an internal process.","zh":"這個短語指出內部過程。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":6},{"front":"biochemical processes","meaning":"生化過程","examples":[{"en":"Heat allows their biochemical processes to continue.","zh":"熱量讓牠們的生化過程繼續。"},{"en":"Biochemical processes are chemical activities inside living bodies that keep life working.","zh":"biochemical processes 是生物體內維持生命運作的化學活動。"},{"en":"Digestion is one biochemical process that turns food into usable energy.","zh":"消化是一種把食物轉化為可用能量的生化過程。"},{"en":"If body temperature falls too low, biochemical processes may slow down dangerously.","zh":"如果體溫降得太低，生化過程可能危險地變慢。"},{"en":"The phrase explains the hidden chemistry of life.","zh":"這個短語解釋生命背後隱藏的化學運作。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":6},{"front":"continue to function efficiently","meaning":"繼續有效運作","examples":[{"en":"Their biochemical processes can continue to function efficiently.","zh":"牠們的生化過程可以繼續有效運作。"},{"en":"To continue to function efficiently means to keep working well without wasting too much energy.","zh":"continue to function efficiently 指繼續良好運作，且不浪費太多能量。"},{"en":"A school office can continue to function efficiently if records are organised clearly.","zh":"如果紀錄整理清楚，學校辦公室可以繼續有效運作。"},{"en":"If body processes continue efficiently, an animal can stay alive and active.","zh":"如果身體過程繼續有效運作，動物就能存活並保持活躍。"},{"en":"The phrase stresses steady and effective operation.","zh":"這個短語強調穩定而有效的運作。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":6},{"front":"in order to","meaning":"為了","examples":[{"en":"They conserve energy in order to reduce fuel costs.","zh":"牠們保存能量，為了降低能量消耗。"},{"en":"In order to means for the purpose of doing something.","zh":"in order to 指為了做某事。"},{"en":"Students revise early in order to avoid panic before exams.","zh":"學生提早溫習，為了避免考試前恐慌。"},{"en":"Animals save energy in order to survive when food is limited.","zh":"動物保存能量，為了在食物有限時生存。"},{"en":"The phrase clearly introduces a purpose.","zh":"這個短語清楚引出目的。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":6},{"front":"keep fuel costs to a minimum","meaning":"將能量消耗減至最低","examples":[{"en":"Lemmings must keep fuel costs to a minimum.","zh":"旅鼠必須將能量消耗減至最低。"},{"en":"To keep fuel costs to a minimum means to use as little energy as possible.","zh":"keep fuel costs to a minimum 指盡量少用能量。"},{"en":"A family may keep fuel costs to a minimum by using public transport more often.","zh":"家庭可能透過更多使用公共交通來將燃料成本減至最低。"},{"en":"If small animals waste energy, they need more food to replace it.","zh":"如果小動物浪費能量，就需要更多食物補充。"},{"en":"The phrase is used metaphorically for animals’ body energy.","zh":"這個短語用於動物身體能量時是比喻說法。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":7},{"front":"conserve as much energy as possible","meaning":"盡量保存能量","examples":[{"en":"Arctic mammals must conserve as much energy as possible.","zh":"北極哺乳動物必須盡量保存能量。"},{"en":"To conserve as much energy as possible means to save the greatest amount of energy one can.","zh":"conserve as much energy as possible 指盡一切可能保存最多能量。"},{"en":"Students conserve energy during exam week by sleeping well and avoiding unnecessary late nights.","zh":"學生在考試週透過睡好和避免不必要熬夜來保存精力。"},{"en":"If food is scarce, animals must conserve energy to survive longer.","zh":"如果食物稀少，動物必須保存能量才能活得更久。"},{"en":"The phrase stresses careful saving of limited energy.","zh":"這個短語強調小心保存有限能量。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":7},{"front":"a thick insulating coat","meaning":"厚厚的保溫毛層","examples":[{"en":"A thick insulating coat of fur helps the lemming survive.","zh":"厚厚的保溫毛層幫助旅鼠生存。"},{"en":"A thick insulating coat is a dense outer covering that keeps heat from escaping.","zh":"a thick insulating coat 是防止熱量流失的厚密外層覆蓋物。"},{"en":"A winter jacket acts like a thick insulating coat for a child walking to school.","zh":"冬季外套就像孩子上學時的厚厚保溫層。"},{"en":"If an animal has a thick insulating coat, it loses body heat more slowly.","zh":"如果動物有厚厚保溫毛層，體熱流失會較慢。"},{"en":"The phrase connects thickness with protection from cold.","zh":"這個短語把厚度與防寒保護連繫起來。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":7},{"front":"fine fur","meaning":"細密毛皮","examples":[{"en":"Fine fur covers almost all of the lemming’s body.","zh":"細密毛皮覆蓋旅鼠幾乎全身。"},{"en":"Fine fur is soft, thin and closely packed animal hair.","zh":"fine fur 是柔軟、幼細而排列緊密的動物毛髮。"},{"en":"A warm scarf may feel like fine fur because it is soft and smooth.","zh":"溫暖頸巾可能像細密毛皮一樣柔軟順滑。"},{"en":"If fur is fine and dense, it can trap air close to the skin.","zh":"如果毛皮細密而濃密，就可以把空氣困在靠近皮膚的位置。"},{"en":"The phrase describes the texture and protective quality of hair.","zh":"這個短語描述毛髮的質感和保護作用。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":7},{"front":"covering all but","meaning":"覆蓋除……以外的全部","examples":[{"en":"The fur covers all but the lemming’s eyes.","zh":"毛皮覆蓋旅鼠除眼睛以外的全部地方。"},{"en":"Covering all but something means covering everything except that part.","zh":"covering all but 某部分，指覆蓋所有地方，除了該部分。"},{"en":"A raincoat may cover all but a child’s face and hands.","zh":"雨衣可能覆蓋孩子除臉和手以外的全部身體。"},{"en":"If fur covers all but the eyes, very little skin is exposed to cold air.","zh":"如果毛皮覆蓋除眼睛外的全部地方，很少皮膚會暴露於冷空氣。"},{"en":"The phrase clearly marks the exception.","zh":"這個短語清楚標出例外。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":7},{"front":"achieve this","meaning":"達到這個效果","examples":[{"en":"The insulating coat achieves this by conserving heat.","zh":"保溫毛層透過保存熱量達到這個效果。"},{"en":"To achieve this means to successfully produce the result just mentioned.","zh":"achieve this 指成功產生剛提及的結果。"},{"en":"A teacher may improve reading speed and achieve this through daily short practice.","zh":"老師可能想提升閱讀速度，並透過每日短練習達到這個效果。"},{"en":"If an animal needs warmth, dense fur can achieve this by trapping air.","zh":"如果動物需要保暖，濃密毛皮可以透過困住空氣達到這個效果。"},{"en":"The phrase points back to a goal or result.","zh":"這個短語指回一個目標或結果。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":7},{"front":"the life preserver of the Arctic","meaning":"北極的救生工具","examples":[{"en":"Fur is the life preserver of the Arctic.","zh":"毛皮是北極的救生工具。"},{"en":"The life preserver of the Arctic means the thing that helps animals stay alive there.","zh":"the life preserver of the Arctic 指幫助動物在北極活下來的東西。"},{"en":"In winter hiking, a warm jacket can be a life preserver because it prevents dangerous heat loss.","zh":"在冬季遠足中，保暖外套可以像救生工具，因為它防止危險失溫。"},{"en":"If fur keeps animals warm, it acts like emergency protection against the cold.","zh":"如果毛皮讓動物保持溫暖，它就像對抗寒冷的緊急保護。"},{"en":"The phrase is a metaphor for something essential to survival.","zh":"這個短語是比喻，指生存所必需的東西。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":7},{"front":"one class of animals","meaning":"一類動物","examples":[{"en":"Only one class of animals has fur.","zh":"只有一類動物有毛皮。"},{"en":"One class of animals means one major scientific group of animals.","zh":"one class of animals 指一個主要科學動物分類。"},{"en":"Birds are one class of animals, while mammals are another.","zh":"鳥類是一類動物，而哺乳動物是另一類。"},{"en":"If only one class of animals has a feature, that feature helps identify the group.","zh":"如果只有一類動物有某特徵，該特徵就有助識別該群體。"},{"en":"The phrase is used in biological classification.","zh":"這個短語用於生物分類。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":7},{"front":"mammals","meaning":"哺乳動物","examples":[{"en":"Mammals are the only class of animals with fur.","zh":"哺乳動物是唯一有毛皮的動物類別。"},{"en":"Mammals are animals that usually have hair or fur and feed their young with milk.","zh":"mammals 通常是有毛髮或毛皮並以乳汁餵養幼崽的動物。"},{"en":"Dogs, whales, humans and bats are all mammals.","zh":"狗、鯨魚、人類和蝙蝠都是哺乳動物。"},{"en":"Because mammals can produce body heat, many can survive colder conditions than reptiles.","zh":"因為哺乳動物能產生體熱，許多能比爬行動物承受更冷環境。"},{"en":"The word names a major animal group.","zh":"這個字指出一個主要動物群體。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":7},{"front":"comprise dense layers of","meaning":"由厚密的……層組成","examples":[{"en":"Fur comprises dense layers of hair.","zh":"毛皮由厚密毛髮層組成。"},{"en":"To comprise dense layers of something means to be made up of tightly packed layers.","zh":"comprise dense layers of 某物，指由緊密排列的多層物質組成。"},{"en":"A winter quilt may comprise dense layers of cloth and filling.","zh":"冬季被子可能由厚密布料和填充物層組成。"},{"en":"If fur comprises dense layers of hair, it can trap warm air effectively.","zh":"如果毛皮由厚密毛髮層組成，就能有效困住暖空氣。"},{"en":"The phrase explains structure by naming its parts.","zh":"這個短語透過指出部分來解釋結構。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":7},{"front":"dense layers of hair","meaning":"厚密毛髮層","examples":[{"en":"Fur is made up of dense layers of hair.","zh":"毛皮由厚密毛髮層構成。"},{"en":"Dense layers of hair are thick, closely packed layers of animal hair.","zh":"dense layers of hair 是厚而排列緊密的動物毛髮層。"},{"en":"A dog with dense layers of hair may stay warmer in winter.","zh":"有厚密毛髮層的狗在冬天可能較暖。"},{"en":"If hair layers are dense, less cold air reaches the skin.","zh":"如果毛髮層厚密，較少冷空氣會到達皮膚。"},{"en":"The phrase explains why fur can insulate so well.","zh":"這個短語解釋為何毛皮能很好地保溫。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":8},{"front":"be composed of","meaning":"由……構成","examples":[{"en":"Hair is composed of keratin.","zh":"毛髮由角蛋白構成。"},{"en":"To be composed of something means to be made from it.","zh":"be composed of 某物，意思是由它組成。"},{"en":"A class may be composed of beginners, intermediate students and advanced students.","zh":"一班學生可能由初學者、中級學生和高級學生構成。"},{"en":"If a material is composed of strong fibres, it may be hard to tear.","zh":"如果材料由強韌纖維構成，就可能很難撕破。"},{"en":"The phrase explains what something consists of.","zh":"這個短語解釋某物由甚麼組成。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":8},{"front":"a substance called","meaning":"一種名為……的物質","examples":[{"en":"Hair is composed of a substance called keratin.","zh":"毛髮由一種名為角蛋白的物質構成。"},{"en":"A substance called something means a material with that name.","zh":"a substance called 某物，指一種有該名稱的材料。"},{"en":"Nails contain a substance called keratin, which also appears in hair.","zh":"指甲含有一種名為角蛋白的物質，而毛髮中也有它。"},{"en":"If a product contains a substance called caffeine, it may make people feel more awake.","zh":"如果產品含有一種名為咖啡因的物質，它可能令人較清醒。"},{"en":"The phrase introduces the name of a material.","zh":"這個短語引入某種材料的名稱。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":8},{"front":"keratin","meaning":"角蛋白","examples":[{"en":"Keratin is the substance that makes up hair.","zh":"角蛋白是構成毛髮的物質。"},{"en":"Keratin is a strong protein found in hair, nails and some animal coverings.","zh":"keratin 是存在於毛髮、指甲和一些動物外層覆蓋物中的堅韌蛋白質。"},{"en":"A biology teacher may mention keratin when explaining why hair and nails are tough.","zh":"生物老師解釋頭髮和指甲為何堅韌時，可能會提到角蛋白。"},{"en":"Because hair contains keratin, it can form protective fur in mammals.","zh":"因為毛髮含有角蛋白，它可以在哺乳動物身上形成保護性毛皮。"},{"en":"The word names the material that gives hair structure.","zh":"這個字指出賦予毛髮結構的材料。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":8},{"front":"grow constantly","meaning":"不斷生長","examples":[{"en":"Hair grows constantly from roots in the skin.","zh":"毛髮從皮膚中的根部不斷生長。"},{"en":"To grow constantly means to keep growing again and again over time.","zh":"grow constantly 指隨時間持續地生長。"},{"en":"A child’s hair grows constantly, so it needs regular cutting.","zh":"孩子的頭髮不斷生長，所以需要定期修剪。"},{"en":"If a plant grows constantly, it needs steady water, light and nutrients.","zh":"如果植物不斷生長，它需要穩定的水、光和養分。"},{"en":"The phrase describes continuous growth rather than one short change.","zh":"這個短語描述持續生長，而不是一次短暫變化。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":8},{"front":"roots embedded in the skin","meaning":"嵌在皮膚中的根部","examples":[{"en":"Hair has roots embedded in the skin.","zh":"毛髮有嵌在皮膚中的根部。"},{"en":"Roots embedded in the skin are the parts of hair fixed inside the skin.","zh":"roots embedded in the skin 是固定在皮膚裏面的毛髮部分。"},{"en":"A doctor may explain that hair falls out when roots in the skin are damaged.","zh":"醫生可能解釋，當皮膚中的毛根受損時，毛髮會脫落。"},{"en":"If hair roots are embedded in the skin, the hair can grow from inside the body surface.","zh":"如果毛根嵌在皮膚中，毛髮就能從身體表面內部生長出來。"},{"en":"The phrase describes where hair begins.","zh":"這個短語描述毛髮從哪裏開始。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":8},{"front":"be surrounded by","meaning":"被……包圍","examples":[{"en":"The roots are surrounded by nerve fibres.","zh":"這些根部被神經纖維包圍。"},{"en":"To be surrounded by something means to have it around the outside.","zh":"be surrounded by 某物，意思是外圍有它環繞。"},{"en":"A playground may be surrounded by trees that give shade.","zh":"操場可能被樹木包圍，提供陰影。"},{"en":"If hair roots are surrounded by nerves, movement of the hair can be sensed.","zh":"如果毛根被神經包圍，毛髮的移動就能被感知。"},{"en":"The phrase describes what is around a person, object or body part.","zh":"這個短語描述某人、物件或身體部分周圍有甚麼。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":8},{"front":"nerve fibres","meaning":"神經纖維","examples":[{"en":"Hair roots are surrounded by nerve fibres.","zh":"毛根被神經纖維包圍。"},{"en":"Nerve fibres are thin parts of nerves that carry signals in the body.","zh":"nerve fibres 是神經的細小部分，負責在身體中傳送訊號。"},{"en":"Nerve fibres help people feel touch, pressure or pain.","zh":"神經纖維幫助人感覺觸碰、壓力或痛楚。"},{"en":"If nerve fibres around hair roots are stimulated, an animal can sense movement.","zh":"如果毛根周圍的神經纖維被刺激，動物就能感知移動。"},{"en":"The phrase names tiny body structures involved in sensation.","zh":"這個短語指出與感覺相關的微細身體結構。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":8},{"front":"sense any movement of","meaning":"感知……的任何移動","examples":[{"en":"The animal can sense any movement of the hair.","zh":"動物可以感知毛髮的任何移動。"},{"en":"To sense any movement of something means to feel even small changes in its position.","zh":"sense any movement of 某物，指感覺到其位置即使很小的變化。"},{"en":"A cat can sense movement of its whiskers when they touch a narrow gap.","zh":"貓的鬍鬚碰到狹窄縫隙時，可以感知鬍鬚的移動。"},{"en":"If an animal senses hair movement, it may notice wind, insects or nearby danger.","zh":"如果動物感知到毛髮移動，牠可能察覺風、昆蟲或附近危險。"},{"en":"The phrase describes very sensitive detection.","zh":"這個短語描述非常敏銳的偵測能力。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":8},{"front":"land mammals","meaning":"陸生哺乳動物","examples":[{"en":"Fur gives land mammals the edge needed to survive.","zh":"毛皮給予陸生哺乳動物生存所需的優勢。"},{"en":"Land mammals are mammals that live mainly on land rather than in water.","zh":"land mammals 是主要生活在陸地而不是水中的哺乳動物。"},{"en":"Horses, wolves and foxes are land mammals.","zh":"馬、狼和狐狸都是陸生哺乳動物。"},{"en":"If land mammals live in cold places, fur helps them reduce heat loss.","zh":"如果陸生哺乳動物生活在寒冷地方，毛皮能幫助牠們減少熱量流失。"},{"en":"The phrase separates land-living mammals from marine mammals.","zh":"這個短語把陸地生活的哺乳動物與海洋哺乳動物區分開。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":8},{"front":"give someone the edge","meaning":"給予某人優勢","examples":[{"en":"Fur gives land mammals the edge necessary to survive.","zh":"毛皮給予陸生哺乳動物生存所需的優勢。"},{"en":"To give someone the edge means to give them an advantage over others.","zh":"give someone the edge 指給某人相對其他人的優勢。"},{"en":"Extra speaking practice can give a student the edge in an oral exam.","zh":"額外口語練習可以讓學生在口試中有優勢。"},{"en":"If an animal has better insulation, it gains an edge in freezing conditions.","zh":"如果動物有更好的保溫能力，牠在冰冷環境中就有優勢。"},{"en":"The phrase describes a useful advantage in competition or survival.","zh":"這個短語描述在競爭或生存中的有用優勢。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":9},{"front":"necessary to survive","meaning":"生存所必需的","examples":[{"en":"Fur provides the protection necessary to survive the Arctic winter.","zh":"毛皮提供熬過北極冬季所必需的保護。"},{"en":"Necessary to survive means required in order to stay alive.","zh":"necessary to survive 指為了活下來而必須有的。"},{"en":"Clean water is necessary to survive, especially during illness or extreme heat.","zh":"清潔食水是生存所必需的，尤其在疾病或酷熱期間。"},{"en":"If shelter is necessary to survive a storm, people must find it quickly.","zh":"如果避難處是熬過風暴所必需的，人們就必須迅速找到它。"},{"en":"The phrase highlights something essential, not optional.","zh":"這個短語突出某物是必需，而不是可有可無。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":9},{"front":"the harsh Arctic winter","meaning":"嚴酷的北極冬季","examples":[{"en":"Land mammals need fur to survive the harsh Arctic winter.","zh":"陸生哺乳動物需要毛皮來熬過嚴酷的北極冬季。"},{"en":"The harsh Arctic winter is the extremely cold and difficult winter in the Arctic.","zh":"the harsh Arctic winter 是北極極度寒冷而艱難的冬天。"},{"en":"A documentary may show animals searching for food during the harsh Arctic winter.","zh":"紀錄片可能展示動物在嚴酷的北極冬季尋找食物。"},{"en":"Because the harsh Arctic winter brings darkness and freezing temperatures, survival is difficult.","zh":"因為嚴酷的北極冬季帶來黑暗和冰冷氣溫，生存非常困難。"},{"en":"The phrase describes winter as severe and dangerous.","zh":"這個短語描述冬季嚴峻而危險。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":9},{"front":"without it","meaning":"沒有它的話","examples":[{"en":"Without it, many Arctic mammals would perish.","zh":"沒有它的話，許多北極哺乳動物會死亡。"},{"en":"Without it means if that thing were absent.","zh":"without it 指如果沒有該事物。"},{"en":"A phone needs a battery; without it, the phone cannot turn on.","zh":"手機需要電池；沒有它的話，手機不能開機。"},{"en":"If fur protects mammals from cold, without it they would lose heat quickly.","zh":"如果毛皮保護哺乳動物免受寒冷，沒有它的話，牠們會很快失去熱量。"},{"en":"The phrase points back to something already mentioned.","zh":"這個短語指回前文已提及的事物。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":9},{"front":"wolves, lemmings and arctic foxes alike","meaning":"狼、旅鼠和北極狐都一樣","examples":[{"en":"Wolves, lemmings and arctic foxes alike depend on fur.","zh":"狼、旅鼠和北極狐都一樣依賴毛皮。"},{"en":"Wolves, lemmings and arctic foxes alike means all three kinds of animals, despite their differences.","zh":"wolves, lemmings and arctic foxes alike 指這三類動物雖然不同，但都如此。"},{"en":"Students, teachers and parents alike need clear information during school changes.","zh":"在學校改變期間，學生、老師和家長都一樣需要清楚資訊。"},{"en":"If very different animals alike need fur, fur is a shared survival tool.","zh":"如果非常不同的動物都一樣需要毛皮，毛皮就是共同的生存工具。"},{"en":"The phrase stresses that the statement applies to all listed groups.","zh":"這個短語強調陳述適用於所有列出的群體。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":9},{"front":"surely perish","meaning":"必定死亡","examples":[{"en":"Without fur, Arctic mammals would surely perish.","zh":"沒有毛皮，北極哺乳動物必定死亡。"},{"en":"To surely perish means to almost certainly die or be destroyed.","zh":"surely perish 指幾乎肯定會死亡或被摧毀。"},{"en":"Plants left without water in extreme heat will surely perish.","zh":"植物在酷熱中沒有水，一定會死亡。"},{"en":"If an animal loses its insulation in freezing weather, it may surely perish.","zh":"如果動物在冰冷天氣中失去保溫層，牠可能必定死亡。"},{"en":"The phrase strongly predicts death or destruction.","zh":"這個短語強烈預測死亡或毀滅。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":9},{"front":"insulation provided by","meaning":"由……提供的保溫作用","examples":[{"en":"The insulation provided by fur helps Arctic animals stay warm.","zh":"由毛皮提供的保溫作用幫助北極動物保持溫暖。"},{"en":"Insulation provided by something means the protection from heat loss that it gives.","zh":"insulation provided by 某物，指它提供的防止熱量流失的保護。"},{"en":"The insulation provided by a thick jacket keeps a child warm at a bus stop.","zh":"由厚外套提供的保溫作用讓孩子在巴士站保持溫暖。"},{"en":"If insulation is good, less body heat escapes into the cold air.","zh":"如果保溫作用良好，較少體熱會流失到冷空氣中。"},{"en":"The phrase explains what creates warmth protection.","zh":"這個短語解釋保暖保護來自甚麼。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":9},{"front":"come not from…but from…","meaning":"不是來自……而是來自……","examples":[{"en":"The insulation comes not from the fur itself but from trapped air.","zh":"保溫作用不是來自毛皮本身，而是來自被困住的空氣。"},{"en":"Come not from A but from B means the real source is B, not A.","zh":"come not from A but from B 指真正來源是 B，而不是 A。"},{"en":"A student’s confidence may come not from easy praise but from steady practice.","zh":"學生的信心可能不是來自簡單讚美，而是來自穩定練習。"},{"en":"If warmth comes from trapped air rather than hair itself, the structure of fur is important.","zh":"如果溫暖來自困住的空氣而非毛髮本身，毛皮結構就很重要。"},{"en":"The phrase clearly corrects a possible misunderstanding.","zh":"這個短語清楚糾正可能的誤解。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":9},{"front":"largely from","meaning":"主要來自","examples":[{"en":"The warmth comes largely from the layer of air in the fur.","zh":"溫暖主要來自毛皮中的空氣層。"},{"en":"Largely from means mainly from one source.","zh":"largely from 指主要來自某一來源。"},{"en":"A school’s success may come largely from patient teachers and clear routines.","zh":"學校成功可能主要來自耐心老師和清晰流程。"},{"en":"If heat protection comes largely from trapped air, dense fur must hold that air still.","zh":"如果保暖主要來自被困住的空氣，濃密毛皮就必須固定那層空氣。"},{"en":"The phrase identifies the main cause, not the only cause.","zh":"這個短語指出主要原因，而不是唯一原因。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":9},{"front":"a layer of air","meaning":"一層空氣","examples":[{"en":"A layer of air is trapped within the fur.","zh":"一層空氣被困在毛皮之內。"},{"en":"A layer of air is a thin space of air between two surfaces or materials.","zh":"a layer of air 是兩個表面或材料之間的薄薄空氣空間。"},{"en":"Double-glazed windows use a layer of air to slow heat loss.","zh":"雙層玻璃窗使用一層空氣來減慢熱量流失。"},{"en":"If fur holds a layer of air near the skin, the animal stays warmer.","zh":"如果毛皮把一層空氣固定在皮膚附近，動物就會更暖。"},{"en":"The phrase describes the air barrier that helps insulation.","zh":"這個短語描述有助保溫的空氣屏障。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":9},{"front":"trapped within","meaning":"被困在……之內","examples":[{"en":"Air is trapped within the fur.","zh":"空氣被困在毛皮之內。"},{"en":"Trapped within something means held inside it and unable to move freely.","zh":"trapped within 某物，指被固定在其內部而不能自由移動。"},{"en":"Warm air can be trapped within a sleeping bag on a cold night.","zh":"在寒冷夜晚，暖空氣可以被困在睡袋之內。"},{"en":"If air is trapped within fur, it cannot easily carry heat away.","zh":"如果空氣被困在毛皮之內，它就不容易把熱量帶走。"},{"en":"The phrase describes something held inside a space.","zh":"這個短語描述某物被保留在某空間內。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":10},{"front":"an effective insulator","meaning":"有效的隔熱物","examples":[{"en":"Air is an extremely effective insulator.","zh":"空氣是非常有效的隔熱物。"},{"en":"An effective insulator is a material or layer that slows the movement of heat.","zh":"an effective insulator 是減慢熱量移動的材料或層。"},{"en":"Foam in a lunch box can be an effective insulator that keeps food warm.","zh":"飯盒中的泡沫可以是有效隔熱物，令食物保持溫暖。"},{"en":"If air is held still, it becomes an effective insulator against cold.","zh":"如果空氣被固定不流動，它就成為對抗寒冷的有效隔熱物。"},{"en":"The phrase describes something that helps keep heat in or out.","zh":"這個短語描述幫助保留或阻隔熱量的東西。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":10},{"front":"a poor conductor","meaning":"不良導熱體","examples":[{"en":"Air is a poor conductor of heat.","zh":"空氣是不良導熱體。"},{"en":"A poor conductor is a material that does not transfer heat or electricity easily.","zh":"a poor conductor 是不容易傳導熱或電的材料。"},{"en":"Plastic is a poor conductor, so many pot handles are made from it.","zh":"塑膠是不良導體，所以許多鍋柄由塑膠製成。"},{"en":"If air is a poor conductor, trapped air helps prevent heat loss.","zh":"如果空氣是不良導熱體，被困住的空氣就有助防止熱量流失。"},{"en":"The phrase describes weak transfer ability.","zh":"這個短語描述弱傳導能力。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":10},{"front":"have a limited ability to","meaning":"……能力有限","examples":[{"en":"Air has a limited ability to conduct heat.","zh":"空氣傳導熱量的能力有限。"},{"en":"To have a limited ability to do something means to be able to do it only weakly or partly.","zh":"have a limited ability to do something 指只能微弱或部分做到某事。"},{"en":"A small battery has a limited ability to power a large machine.","zh":"小電池驅動大型機器的能力有限。"},{"en":"If air has limited ability to carry heat, it works well as insulation.","zh":"如果空氣傳熱能力有限，它就能很好地作保溫層。"},{"en":"The phrase shows that the ability exists but is not strong.","zh":"這個短語顯示能力存在，但並不強。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":10},{"front":"conduct heat away from","meaning":"將熱量從……傳走","examples":[{"en":"Air conducts little heat away from a warm surface.","zh":"空氣很少將熱量從溫暖表面傳走。"},{"en":"To conduct heat away from something means to carry heat away from it.","zh":"conduct heat away from 某物，指把熱量從它那裏傳走。"},{"en":"Metal can conduct heat away from a hot drink, making the cup hard to hold.","zh":"金屬可以把熱量從熱飲傳走，令杯子難以拿住。"},{"en":"If trapped air does not conduct heat away, the animal keeps more body warmth.","zh":"如果被困住的空氣不把熱量傳走，動物就能保留更多體熱。"},{"en":"The phrase explains how heat can be lost.","zh":"這個短語解釋熱量如何流失。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":10},{"front":"a warm surface","meaning":"溫暖表面","examples":[{"en":"Air is poor at conducting heat away from a warm surface.","zh":"空氣不善於把熱量從溫暖表面傳走。"},{"en":"A warm surface is an outer area that has heat.","zh":"a warm surface 是帶有熱量的外部表面。"},{"en":"A child may warm hands on the warm surface of a mug.","zh":"孩子可能把手放在杯子的溫暖表面取暖。"},{"en":"If air near a warm surface stays still, less heat is carried away.","zh":"如果溫暖表面附近的空氣保持靜止，較少熱量會被帶走。"},{"en":"The phrase identifies the place from which heat might escape.","zh":"這個短語指出熱量可能從哪裏逃走。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":10},{"front":"studies reveal that","meaning":"研究顯示","examples":[{"en":"Studies reveal that trapped air provides strong insulation.","zh":"研究顯示，被困住的空氣提供強保溫作用。"},{"en":"Studies reveal that means research shows that something is true or likely true.","zh":"studies reveal that 指研究顯示某事是真實或很可能真實。"},{"en":"Studies reveal that students remember words better when examples are clear.","zh":"研究顯示，例子清楚時，學生更容易記住詞彙。"},{"en":"If studies reveal that a method works, schools may be more willing to use it.","zh":"如果研究顯示某方法有效，學校可能更願意使用它。"},{"en":"The phrase introduces evidence from research.","zh":"這個短語引出研究證據。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":10},{"front":"be held in place","meaning":"被固定在原位","examples":[{"en":"A layer of air must be held in place close to the skin.","zh":"一層空氣必須被固定在靠近皮膚的位置。"},{"en":"To be held in place means to be kept in one position.","zh":"be held in place 指被保持在同一位置。"},{"en":"A bandage must be held in place so it does not slip off.","zh":"繃帶必須被固定在原位，才不會滑落。"},{"en":"If warm air is held in place near skin, it protects the body from cold.","zh":"如果暖空氣被固定在皮膚附近，就能保護身體免受寒冷。"},{"en":"The phrase describes preventing movement.","zh":"這個短語描述防止移動。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":10},{"front":"close to the skin","meaning":"靠近皮膚","examples":[{"en":"Trapped air close to the skin provides insulation.","zh":"靠近皮膚的被困空氣提供保溫作用。"},{"en":"Close to the skin means very near the body’s outer surface.","zh":"close to the skin 指非常接近身體外表面。"},{"en":"Thermal underwear works best when worn close to the skin.","zh":"保暖內衣貼近皮膚穿着時效果最好。"},{"en":"If warm air stays close to the skin, less body heat is lost.","zh":"如果暖空氣留在靠近皮膚的位置，較少體熱會流失。"},{"en":"The phrase describes position near the body.","zh":"這個短語描述接近身體的位置。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":10},{"front":"provide the same insulation as","meaning":"提供與……相同的保溫作用","examples":[{"en":"A five-centimetre layer of air would provide the same insulation as winter fur.","zh":"五厘米厚的空氣層會提供與冬季毛皮相同的保溫作用。"},{"en":"To provide the same insulation as something means to give equal protection against heat loss.","zh":"provide the same insulation as 某物，指提供同等防止熱量流失的保護。"},{"en":"A thick blanket may provide the same insulation as two thinner blankets.","zh":"厚被可能提供與兩張薄被相同的保溫作用。"},{"en":"If trapped air gives the same insulation as fur, air is central to warmth.","zh":"如果被困空氣提供與毛皮相同的保溫作用，空氣就是保暖的核心。"},{"en":"The phrase compares protective power.","zh":"這個短語比較保護能力。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":10},{"front":"impressively dense","meaning":"密度驚人的","examples":[{"en":"The arctic fox has an impressively dense winter coat.","zh":"北極狐有密度驚人的冬季毛皮。"},{"en":"Impressively dense means very thick and closely packed in a way that is remarkable.","zh":"impressively dense 指非常厚密、排列緊密，而且令人印象深刻。"},{"en":"A forest may look impressively dense if trees grow close together.","zh":"如果樹木長得很靠近，森林可能看起來密度驚人。"},{"en":"If fur is impressively dense, it can hold more insulating air.","zh":"如果毛皮密度驚人，它可以保留更多隔熱空氣。"},{"en":"The phrase praises how thick and compact something is.","zh":"這個短語讚賞某物的厚密和緊密程度。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":11},{"front":"winter coat","meaning":"冬季毛皮","examples":[{"en":"The winter coat of the arctic fox traps warm air.","zh":"北極狐的冬季毛皮困住暖空氣。"},{"en":"A winter coat is the thick fur or clothing used for protection in cold weather.","zh":"winter coat 是在寒冷天氣中用作保護的厚毛皮或衣服。"},{"en":"A child wears a winter coat to stay warm on the way to school.","zh":"孩子上學途中穿冬季外套以保持溫暖。"},{"en":"If an animal’s winter coat grows thicker, it can survive colder months better.","zh":"如果動物的冬季毛皮變厚，牠可以更好地熬過寒冷月份。"},{"en":"The phrase can refer to clothing or an animal’s seasonal fur.","zh":"這個短語可以指衣服，也可以指動物季節性毛皮。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":11},{"front":"be exposed to","meaning":"暴露於……","examples":[{"en":"An arctic fox may be exposed to an air temperature of minus ten degrees.","zh":"北極狐可能暴露於零下十度的氣溫中。"},{"en":"To be exposed to something means to face it without full protection.","zh":"be exposed to 某事，指在沒有完全保護下直接面對它。"},{"en":"Workers exposed to strong sunlight need hats and water.","zh":"暴露於強烈陽光下的工人需要帽和水。"},{"en":"If an animal is exposed to freezing air, good insulation becomes essential.","zh":"如果動物暴露於冰冷空氣中，良好保溫就變得必不可少。"},{"en":"The phrase describes direct contact with a condition or risk.","zh":"這個短語描述直接接觸某情況或風險。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":11},{"front":"air temperature","meaning":"氣溫","examples":[{"en":"The air temperature can fall to about minus ten degrees.","zh":"氣溫可以降至約零下十度。"},{"en":"Air temperature is how hot or cold the surrounding air is.","zh":"air temperature 是周圍空氣有多熱或多冷。"},{"en":"Weather reports give air temperature so people know what clothes to wear.","zh":"天氣報告提供氣溫，讓人知道應穿甚麼衣服。"},{"en":"If air temperature falls below freezing, roads may become icy.","zh":"如果氣溫跌至冰點以下，道路可能結冰。"},{"en":"The phrase measures the temperature around an object or person.","zh":"這個短語量度物件或人周圍的溫度。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":11},{"front":"minus ten degrees","meaning":"零下十度","examples":[{"en":"The fox may be exposed to minus ten degrees.","zh":"北極狐可能暴露於零下十度。"},{"en":"Minus ten degrees means ten degrees below zero.","zh":"minus ten degrees 指低於零度十度。"},{"en":"At minus ten degrees, water outside can freeze quickly.","zh":"在零下十度，戶外的水可以很快結冰。"},{"en":"If people walk in minus ten degrees, they need proper winter clothing.","zh":"如果人在零下十度行走，就需要合適冬衣。"},{"en":"The phrase gives a very cold temperature.","zh":"這個短語給出非常寒冷的氣溫。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":11},{"front":"near the tips of the fur","meaning":"靠近毛尖的位置","examples":[{"en":"The temperature near the tips of the fur matches the air temperature.","zh":"靠近毛尖的位置的溫度與氣溫一致。"},{"en":"Near the tips of the fur means close to the outer ends of the hair.","zh":"near the tips of the fur 指靠近毛髮外端的位置。"},{"en":"Snow may collect near the tips of a dog’s fur during a winter walk.","zh":"冬天散步時，雪可能積在狗毛尖附近。"},{"en":"If the fur tips are cold but the skin is warm, the fur is insulating well.","zh":"如果毛尖寒冷但皮膚溫暖，毛皮就是保溫良好。"},{"en":"The phrase identifies the outer part of the fur.","zh":"這個短語指出毛皮的外層部分。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":11},{"front":"match the air temperature","meaning":"與氣溫一致","examples":[{"en":"The fur tips match the air temperature outside.","zh":"毛尖與外界氣溫一致。"},{"en":"To match the air temperature means to be the same temperature as the surrounding air.","zh":"match the air temperature 指與周圍空氣溫度相同。"},{"en":"A metal bench may match the air temperature after sitting outside all night.","zh":"金屬長椅放在戶外一整晚後，可能與氣溫一致。"},{"en":"If fur tips match the air temperature, the outer fur may feel very cold.","zh":"如果毛尖與氣溫一致，外層毛皮可能感覺很冷。"},{"en":"The phrase compares an object’s temperature with the air around it.","zh":"這個短語比較物件溫度與周圍空氣溫度。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":11},{"front":"at the surface of the skin","meaning":"在皮膚表面","examples":[{"en":"The temperature at the surface of the skin is much warmer.","zh":"在皮膚表面的溫度溫暖得多。"},{"en":"At the surface of the skin means on the outer layer of the body.","zh":"at the surface of the skin 指在身體外層皮膚上。"},{"en":"A thermometer may measure temperature at the surface of the skin.","zh":"溫度計可能量度皮膚表面的溫度。"},{"en":"If the surface of the skin stays warm, the animal’s body is protected.","zh":"如果皮膚表面保持溫暖，動物身體就受到保護。"},{"en":"The phrase marks the body’s outer boundary.","zh":"這個短語標示身體外部界線。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":11},{"front":"be closer to","meaning":"更接近","examples":[{"en":"The skin temperature will be closer to thirty degrees.","zh":"皮膚溫度會更接近三十度。"},{"en":"To be closer to a number means to be nearer to that number than to another.","zh":"be closer to 某數字，指比起另一數字更接近它。"},{"en":"If a test score is closer to 80 than 70, the student nearly reached a higher band.","zh":"如果考試分數更接近80而不是70，學生就差不多達到更高等級。"},{"en":"If skin temperature is closer to thirty degrees, the body remains much warmer than the air.","zh":"如果皮膚溫度更接近三十度，身體就比空氣暖得多。"},{"en":"The phrase compares approximate values.","zh":"這個短語比較大概數值。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":11},{"front":"represent a temperature difference of","meaning":"代表……的溫差","examples":[{"en":"This represents a temperature difference of around forty degrees.","zh":"這代表約四十度的溫差。"},{"en":"To represent a temperature difference of a number means to show a gap of that many degrees.","zh":"represent a temperature difference of 某數字，指顯示該度數的溫度差距。"},{"en":"A freezer and a kitchen may represent a temperature difference of more than twenty degrees.","zh":"冰箱和廚房可能代表超過二十度的溫差。"},{"en":"If fur creates a large temperature difference, it is working as strong insulation.","zh":"如果毛皮形成很大溫差，它就是強力保溫層。"},{"en":"The phrase explains the size of a temperature gap.","zh":"這個短語解釋溫度差距的大小。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":11},{"front":"around forty degrees","meaning":"約四十度","examples":[{"en":"The insulation creates a difference of around forty degrees.","zh":"保溫作用造成約四十度的差距。"},{"en":"Around forty degrees means approximately forty degrees, not exactly.","zh":"around forty degrees 指大約四十度，而不是精確數字。"},{"en":"A classroom can feel uncomfortable if the indoor and outdoor temperatures differ by around forty degrees.","zh":"如果室內外溫差約四十度，課室可能令人不舒服。"},{"en":"If fur maintains around forty degrees of difference, it protects the skin very well.","zh":"如果毛皮維持約四十度的差距，它就很好地保護皮膚。"},{"en":"The phrase gives an approximate measurement.","zh":"這個短語提供大概量度。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":12},{"front":"such effective insulation","meaning":"如此有效的保溫作用","examples":[{"en":"Such effective insulation depends on trapped air.","zh":"如此有效的保溫作用依賴被困住的空氣。"},{"en":"Such effective insulation means this very successful protection against heat loss.","zh":"such effective insulation 指這種非常成功的防止熱量流失的保護。"},{"en":"A well-made sleeping bag gives such effective insulation that campers stay warm at night.","zh":"製作良好的睡袋提供如此有效的保溫作用，露營者晚上能保持溫暖。"},{"en":"If insulation is effective, less energy is needed to keep the body warm.","zh":"如果保溫作用有效，保持身體溫暖所需能量就較少。"},{"en":"The phrase points to insulation that works extremely well.","zh":"這個短語指出非常有效的保溫作用。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":12},{"front":"be made possible by","meaning":"由……促成；因……而成為可能","examples":[{"en":"This insulation is made possible by trapped air.","zh":"這種保溫作用由被困住的空氣促成。"},{"en":"To be made possible by something means to happen because that thing allows it.","zh":"be made possible by 某物，指因它容許某事發生而成為可能。"},{"en":"Online lessons are made possible by stable Internet connections.","zh":"網課由穩定互聯網連線促成。"},{"en":"If warmth is made possible by trapped air, the fur must hold air still.","zh":"如果溫暖由被困空氣促成，毛皮就必須固定空氣。"},{"en":"The phrase identifies what enables something to happen.","zh":"這個短語指出令某事得以發生的因素。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":12},{"front":"contained within","meaning":"包含在……之內","examples":[{"en":"The trapped air is contained within the fur.","zh":"被困住的空氣包含在毛皮之內。"},{"en":"Contained within something means held inside it.","zh":"contained within 某物，指被保留在其內部。"},{"en":"The medicine is contained within a sealed bottle to keep it clean.","zh":"藥物包含在密封瓶中，以保持清潔。"},{"en":"If warm air is contained within fur, it cannot escape easily.","zh":"如果暖空氣包含在毛皮之內，就不容易逃走。"},{"en":"The phrase describes something kept inside a surrounding material.","zh":"這個短語描述某物被保存在周圍材料內。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":12},{"front":"long, fine and densely packed fur","meaning":"長而細密、排列緊密的毛皮","examples":[{"en":"The trapped air is contained within long, fine and densely packed fur.","zh":"被困住的空氣包含在長而細密、排列緊密的毛皮之內。"},{"en":"Long, fine and densely packed fur is fur with long thin hairs placed close together.","zh":"long, fine and densely packed fur 是由長而幼細、排列緊密的毛髮組成的毛皮。"},{"en":"A winter animal with long, fine and densely packed fur may look fluffy but stay well insulated.","zh":"有長而細密、排列緊密毛皮的冬季動物可能看起來毛茸茸，但保溫良好。"},{"en":"If fur is long, fine and dense, it can trap a stable layer of air.","zh":"如果毛皮長、細而密，就可以困住穩定空氣層。"},{"en":"The phrase describes the structure that makes fur warm.","zh":"這個短語描述令毛皮保暖的結構。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":12},{"front":"have more in their arsenal than","meaning":"除了……還有更多防護手段","examples":[{"en":"Arctic mammals have more in their arsenal than just fur.","zh":"北極哺乳動物除了毛皮外，還有更多防護手段。"},{"en":"To have more in their arsenal than something means to have additional tools or advantages besides it.","zh":"have more in their arsenal than 某物，指除了它之外還有其他工具或優勢。"},{"en":"A good teacher has more in her arsenal than textbooks; she also uses questions and examples.","zh":"好老師除了教科書外，還有更多方法；她也使用問題和例子。"},{"en":"If animals have several survival tools, they are not relying on one protection only.","zh":"如果動物有幾種生存工具，牠們就不是只依賴一種保護。"},{"en":"The phrase uses “arsenal” metaphorically to mean available resources.","zh":"這個短語以 arsenal 作比喻，指可用資源。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":12},{"front":"protect someone from the elements","meaning":"保護某人免受惡劣天氣侵害","examples":[{"en":"Fur helps protect Arctic mammals from the elements.","zh":"毛皮幫助保護北極哺乳動物免受惡劣天氣侵害。"},{"en":"To protect someone from the elements means to shield them from harsh weather.","zh":"protect someone from the elements 指保護某人免受嚴酷天氣影響。"},{"en":"A raincoat protects children from the elements on the way to school.","zh":"雨衣在上學途中保護孩子免受惡劣天氣侵害。"},{"en":"If animals are not protected from wind and snow, they lose heat quickly.","zh":"如果動物沒有受到風雪保護，牠們會很快失去熱量。"},{"en":"The phrase refers to protection from natural weather conditions.","zh":"這個短語指免受自然天氣條件侵害。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":12},{"front":"the elements","meaning":"惡劣天氣；自然環境","examples":[{"en":"Arctic mammals need protection from the elements.","zh":"北極哺乳動物需要免受惡劣天氣侵害的保護。"},{"en":"The elements means natural weather conditions such as wind, rain, snow and cold.","zh":"the elements 指風、雨、雪和寒冷等自然天氣條件。"},{"en":"Hikers carry tents and waterproof jackets to protect themselves from the elements.","zh":"遠足者帶帳篷和防水外套，以保護自己免受惡劣天氣侵害。"},{"en":"If workers spend all day outdoors, the elements can make their job harder.","zh":"如果工人整天在戶外，惡劣天氣會令工作更困難。"},{"en":"The phrase usually refers to harsh outdoor conditions.","zh":"這個短語通常指嚴酷戶外環境。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":12},{"front":"unlike amphibians and reptiles","meaning":"不同於兩棲動物和爬行動物","examples":[{"en":"Unlike amphibians and reptiles, mammals can generate body heat.","zh":"不同於兩棲動物和爬行動物，哺乳動物能產生體熱。"},{"en":"Unlike amphibians and reptiles means different from those two animal groups.","zh":"unlike amphibians and reptiles 指與這兩類動物不同。"},{"en":"Unlike younger children, older students may manage homework without constant reminders.","zh":"不同於年幼孩子，年長學生可能不需不斷提醒也能管理功課。"},{"en":"If mammals can generate heat unlike amphibians and reptiles, they can stay active in colder places.","zh":"如果哺乳動物不同於兩棲動物和爬行動物，能產生熱量，牠們就能在較冷地方保持活躍。"},{"en":"The phrase creates a clear contrast between groups.","zh":"這個短語在群體之間建立清楚對比。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":12},{"front":"classes of animals","meaning":"動物類別","examples":[{"en":"Mammals are one of the main classes of animals.","zh":"哺乳動物是主要動物類別之一。"},{"en":"Classes of animals are major groups used to organise animals scientifically.","zh":"classes of animals 是科學上用來分類動物的主要群體。"},{"en":"In biology, students learn classes of animals such as mammals, birds, reptiles and amphibians.","zh":"在生物課中，學生學習哺乳動物、鳥類、爬行動物和兩棲動物等動物類別。"},{"en":"If animals belong to different classes, they may control body temperature differently.","zh":"如果動物屬於不同類別，牠們調節體溫的方法可能不同。"},{"en":"The phrase is used for classification.","zh":"這個短語用於分類。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":12},{"front":"endotherms","meaning":"內溫動物；恒溫動物","examples":[{"en":"Arctic mammals are endotherms.","zh":"北極哺乳動物是內溫動物。"},{"en":"Endotherms are animals that can produce body heat internally.","zh":"endotherms 是能在體內產生體熱的動物。"},{"en":"Humans are endotherms because our bodies keep warm even when the room is cool.","zh":"人類是內溫動物，因為即使房間寒冷，我們的身體仍能保持溫暖。"},{"en":"If animals are endotherms, they can remain active in colder conditions than many reptiles.","zh":"如果動物是內溫動物，牠們能比許多爬行動物在更冷環境中保持活躍。"},{"en":"The word describes animals that regulate heat from inside the body.","zh":"這個字描述從體內調節熱量的動物。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":13},{"front":"meaning they can","meaning":"意思是牠們能夠","examples":[{"en":"They are endotherms, meaning they can generate their own body heat.","zh":"牠們是內溫動物，意思是牠們能夠產生自身體熱。"},{"en":"Meaning they can introduces an explanation of what the previous term allows them to do.","zh":"meaning they can 用來解釋前一個術語讓牠們能做到甚麼。"},{"en":"The school is bilingual, meaning students can use two languages in lessons.","zh":"學校是雙語學校，意思是學生能在課堂使用兩種語言。"},{"en":"If animals are endotherms, meaning they can produce heat, cold weather is less limiting.","zh":"如果動物是內溫動物，意思是牠們能產生熱量，寒冷天氣對牠們的限制就較少。"},{"en":"The phrase explains a term by giving its practical result.","zh":"這個短語透過實際結果解釋術語。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":13},{"front":"generate their own body heat","meaning":"產生自身體熱","examples":[{"en":"Endotherms can generate their own body heat.","zh":"內溫動物可以產生自身體熱。"},{"en":"To generate their own body heat means to produce warmth inside the body.","zh":"generate their own body heat 指在身體內產生溫暖。"},{"en":"People generate their own body heat when their muscles work and food is burned for energy.","zh":"人類在肌肉活動和食物轉化為能量時產生自身體熱。"},{"en":"If animals generate their own body heat, they do not need sunlight to warm every movement.","zh":"如果動物能產生自身體熱，牠們就不需要靠陽光溫暖每個動作。"},{"en":"The phrase explains a key advantage of mammals.","zh":"這個短語解釋哺乳動物的一個關鍵優勢。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":13},{"front":"defining characteristics","meaning":"定義性特徵","examples":[{"en":"Thermoregulation is one of the defining characteristics of mammals.","zh":"體溫調節是哺乳動物的定義性特徵之一。"},{"en":"Defining characteristics are the main features that make something what it is.","zh":"defining characteristics 是令某物成為其本身的主要特徵。"},{"en":"A school’s defining characteristics may include small classes and close teacher support.","zh":"學校的定義性特徵可能包括小班教學和緊密教師支援。"},{"en":"If fur and body heat are defining characteristics, they help identify mammals.","zh":"如果毛皮和體熱是定義性特徵，它們就有助識別哺乳動物。"},{"en":"The phrase points to essential features, not minor details.","zh":"這個短語指出本質特徵，而不是小細節。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":13},{"front":"mammalian ability","meaning":"哺乳動物的能力","examples":[{"en":"The mammalian ability to generate heat helps Arctic animals survive.","zh":"哺乳動物產生熱量的能力幫助北極動物生存。"},{"en":"Mammalian ability means an ability belonging to mammals.","zh":"mammalian ability 指屬於哺乳動物的能力。"},{"en":"The mammalian ability to feed young with milk helps babies grow after birth.","zh":"哺乳動物以乳汁餵養幼崽的能力幫助幼崽出生後成長。"},{"en":"If a mammalian ability helps produce heat, it becomes important in cold climates.","zh":"如果某種哺乳動物能力有助產生熱量，它在寒冷氣候中就很重要。"},{"en":"The phrase connects a biological skill with mammals.","zh":"這個短語把生物能力與哺乳動物連繫起來。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":13},{"front":"generate heat internally","meaning":"在體內產生熱量","examples":[{"en":"Mammals can generate heat internally.","zh":"哺乳動物可以在體內產生熱量。"},{"en":"To generate heat internally means to produce warmth from inside the body.","zh":"generate heat internally 指從身體內部產生溫暖。"},{"en":"A person generates heat internally when exercise raises body temperature.","zh":"人運動令體溫上升時，就是在體內產生熱量。"},{"en":"If animals generate heat internally, they can stay active without waiting for the sun.","zh":"如果動物在體內產生熱量，牠們不用等待陽光也能保持活躍。"},{"en":"The phrase contrasts internal warmth with heat from the environment.","zh":"這個短語把內部溫暖與環境熱量作對比。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":13},{"front":"enable someone to remain","meaning":"使某人能夠保持……","examples":[{"en":"Internal heat enables the arctic fox to remain warm and active.","zh":"內部熱量使北極狐能夠保持溫暖和活躍。"},{"en":"To enable someone to remain a certain way means to make it possible for them to stay that way.","zh":"enable someone to remain 某狀態，指使某人能夠繼續保持該狀態。"},{"en":"A clear timetable enables students to remain organised during exam week.","zh":"清晰時間表使學生能夠在考試週保持有條理。"},{"en":"If body heat enables an animal to remain active, it can still hunt or move in cold weather.","zh":"如果體熱使動物能夠保持活躍，牠在寒冷天氣中仍能捕獵或移動。"},{"en":"The phrase connects a support with a continuing condition.","zh":"這個短語把支援與持續狀態連繫起來。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":13},{"front":"remain warm and active","meaning":"保持溫暖和活躍","examples":[{"en":"The arctic fox can remain warm and active in cold conditions.","zh":"北極狐可以在寒冷環境中保持溫暖和活躍。"},{"en":"To remain warm and active means to stay warm enough to keep moving and functioning.","zh":"remain warm and active 指保持足夠溫暖，以繼續移動和運作。"},{"en":"Children remain warm and active in winter when they wear proper coats and gloves.","zh":"孩子在冬天穿合適外套和手套時，可以保持溫暖和活躍。"},{"en":"If an animal remains warm and active, it can search for food even in snow.","zh":"如果動物保持溫暖和活躍，即使在雪地也能尋找食物。"},{"en":"The phrase links body temperature with movement and survival.","zh":"這個短語把體溫與活動和生存連繫起來。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":13},{"front":"very cold conditions","meaning":"極寒環境","examples":[{"en":"Arctic mammals remain active in very cold conditions.","zh":"北極哺乳動物在極寒環境中保持活躍。"},{"en":"Very cold conditions are environments with extremely low temperatures.","zh":"very cold conditions 是氣溫極低的環境。"},{"en":"Workers in very cold conditions need protective clothing and warm breaks.","zh":"在極寒環境工作的工人需要防護衣物和暖身休息。"},{"en":"If animals can move in very cold conditions, they have strong survival adaptations.","zh":"如果動物能在極寒環境中移動，牠們就有強大生存適應能力。"},{"en":"The phrase describes a harsh cold environment.","zh":"這個短語描述嚴酷寒冷環境。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":13},{"front":"regulate body temperature","meaning":"調節體溫","examples":[{"en":"Arctic mammals can regulate their body temperature.","zh":"北極哺乳動物可以調節體溫。"},{"en":"To regulate body temperature means to control how warm or cool the body stays.","zh":"regulate body temperature 指控制身體保持多暖或多涼。"},{"en":"People regulate body temperature by sweating when they are too hot.","zh":"人在太熱時透過流汗調節體溫。"},{"en":"If animals regulate body temperature well, they can survive changing weather.","zh":"如果動物能良好調節體溫，就能在變化天氣中生存。"},{"en":"The phrase describes active control of internal warmth.","zh":"這個短語描述對內部溫度的主動控制。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":13},{"front":"independently of","meaning":"獨立於……；不受……左右","examples":[{"en":"Mammals regulate body temperature independently of external conditions.","zh":"哺乳動物調節體溫時不受外在環境左右。"},{"en":"Independently of something means without being controlled by it.","zh":"independently of 某事，指不受它控制。"},{"en":"A student may study independently of classmates by following her own revision plan.","zh":"學生可能按照自己的溫習計劃，獨立於同學學習。"},{"en":"If body temperature is controlled independently of the weather, the animal can stay active in cold air.","zh":"如果體溫不受天氣左右而受控制，動物就能在冷空氣中保持活躍。"},{"en":"The phrase shows separation from outside influence.","zh":"這個短語顯示與外在影響分開。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":14},{"front":"external conditions","meaning":"外在環境","examples":[{"en":"Thermoregulation works independently of external conditions.","zh":"體溫調節不受外在環境左右。"},{"en":"External conditions are the outside factors around a living thing or system.","zh":"external conditions 是生物或系統周圍的外部因素。"},{"en":"External conditions such as noise and heat can affect a student’s concentration.","zh":"噪音和炎熱等外在環境可以影響學生專注力。"},{"en":"If animals can resist external conditions, they are less controlled by weather.","zh":"如果動物能抵抗外在環境，牠們就較少受天氣控制。"},{"en":"The phrase refers to surroundings outside the body or system.","zh":"這個短語指身體或系統外部的周圍環境。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":14},{"front":"be known as","meaning":"被稱為","examples":[{"en":"This process is known as thermoregulation.","zh":"這個過程被稱為體溫調節。"},{"en":"To be known as something means to be called by that name.","zh":"be known as 某物，指被那個名稱稱呼。"},{"en":"A school prize for kindness may be known as the community award.","zh":"學校的善行獎可能被稱為社區獎。"},{"en":"If a process is known as thermoregulation, students can label it correctly in science writing.","zh":"如果一個過程被稱為體溫調節，學生就能在科學寫作中正確命名。"},{"en":"The phrase introduces the accepted name for something.","zh":"這個短語引出某事的公認名稱。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":14},{"front":"thermoregulation","meaning":"體溫調節","examples":[{"en":"Thermoregulation allows mammals to control their body temperature.","zh":"體溫調節讓哺乳動物控制自己的體溫。"},{"en":"Thermoregulation is the process of keeping body temperature within a suitable range.","zh":"thermoregulation 是把體溫保持在合適範圍內的過程。"},{"en":"Humans use thermoregulation when they sweat in heat or shiver in cold.","zh":"人類在炎熱中流汗或在寒冷中顫抖時，就是使用體溫調節。"},{"en":"If thermoregulation fails, the body may become dangerously hot or cold.","zh":"如果體溫調節失效，身體可能變得危險地過熱或過冷。"},{"en":"The word describes the body’s temperature-control system.","zh":"這個字描述身體的溫度控制系統。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":14},{"front":"raise their metabolic rate","meaning":"提高代謝率","examples":[{"en":"When Arctic mammals are cold, they raise their metabolic rate.","zh":"當北極哺乳動物感到寒冷時，牠們會提高代謝率。"},{"en":"To raise their metabolic rate means to increase the speed at which the body uses energy.","zh":"raise their metabolic rate 指提高身體使用能量的速度。"},{"en":"Exercise raises a person’s metabolic rate because muscles need more energy.","zh":"運動會提高人的代謝率，因為肌肉需要更多能量。"},{"en":"If mammals raise their metabolic rate, they can produce more heat.","zh":"如果哺乳動物提高代謝率，牠們就能產生更多熱量。"},{"en":"The phrase explains how bodies respond to cold.","zh":"這個短語解釋身體如何回應寒冷。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":14},{"front":"metabolic rate","meaning":"代謝率","examples":[{"en":"A higher metabolic rate produces more heat.","zh":"較高的代謝率會產生更多熱量。"},{"en":"Metabolic rate is the speed at which the body uses energy.","zh":"metabolic rate 是身體使用能量的速度。"},{"en":"A person’s metabolic rate may rise during exercise or fever.","zh":"人的代謝率可能在運動或發燒時上升。"},{"en":"If an animal’s metabolic rate increases, it burns more fuel from food.","zh":"如果動物的代謝率上升，牠會燃燒更多來自食物的能量。"},{"en":"The phrase links body energy use with heat production.","zh":"這個短語把身體能量使用與產熱連繫起來。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":14},{"front":"produce more heat","meaning":"產生更多熱量","examples":[{"en":"Cold mammals produce more heat by raising their metabolic rate.","zh":"感到寒冷的哺乳動物透過提高代謝率產生更多熱量。"},{"en":"To produce more heat means to create extra warmth.","zh":"produce more heat 指製造額外溫暖。"},{"en":"A heater produces more heat when it is turned to a higher setting.","zh":"暖爐調到較高設定時會產生更多熱量。"},{"en":"If an animal produces more heat, it can keep its body temperature higher in cold air.","zh":"如果動物產生更多熱量，就能在冷空氣中保持較高體溫。"},{"en":"The phrase describes an increase in warmth production.","zh":"這個短語描述產熱量增加。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":14},{"front":"the reverse happens","meaning":"情況相反","examples":[{"en":"When Arctic mammals are warm, the reverse happens.","zh":"當北極哺乳動物感到溫暖時，情況相反。"},{"en":"The reverse happens means the opposite process or result occurs.","zh":"the reverse happens 指相反的過程或結果出現。"},{"en":"If a shop lowers prices, sales may rise; if it raises prices too much, the reverse happens.","zh":"如果商店降價，銷售可能上升；如果加價太多，情況相反。"},{"en":"When an animal is warm, it may reduce heat production instead of increasing it.","zh":"當動物感到溫暖時，牠可能減少產熱，而不是增加。"},{"en":"The phrase points to an opposite situation.","zh":"這個短語指出相反情況。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":14},{"front":"be perfectly equipped to","meaning":"完全具備條件去……","examples":[{"en":"Arctic mammals are perfectly equipped to face extreme conditions.","zh":"北極哺乳動物完全具備條件去面對極端環境。"},{"en":"To be perfectly equipped to do something means to have exactly the tools or features needed for it.","zh":"be perfectly equipped to do something 指正好擁有所需工具或特徵去做某事。"},{"en":"A well-prepared student is perfectly equipped to answer a familiar exam question.","zh":"準備充分的學生完全具備條件回答熟悉的考題。"},{"en":"If animals have fur and thermoregulation, they are well equipped for Arctic cold.","zh":"如果動物有毛皮和體溫調節能力，牠們就很適合應付北極寒冷。"},{"en":"The phrase describes strong readiness for a difficult task.","zh":"這個短語描述對艱難任務的充分準備。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":14},{"front":"face the toughest conditions","meaning":"面對最嚴酷的環境","examples":[{"en":"Fur and thermoregulation help mammals face the toughest conditions.","zh":"毛皮和體溫調節幫助哺乳動物面對最嚴酷的環境。"},{"en":"To face the toughest conditions means to deal with the most difficult environment or situation.","zh":"face the toughest conditions 指應付最困難的環境或情況。"},{"en":"Emergency workers face the toughest conditions during storms and floods.","zh":"緊急救援人員在風暴和水災期間面對最嚴酷的環境。"},{"en":"If animals face the toughest conditions, they need several survival strategies.","zh":"如果動物面對最嚴酷的環境，牠們需要幾種生存策略。"},{"en":"The phrase stresses direct contact with severe difficulty.","zh":"這個短語強調直接面對嚴重困難。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":14},{"front":"throw at them","meaning":"向牠們施加；帶來","examples":[{"en":"The Arctic can throw extremely tough conditions at mammals.","zh":"北極可以向哺乳動物施加極其艱難的環境。"},{"en":"To throw conditions at someone means to force them to face those conditions.","zh":"throw conditions at someone 指迫使某人面對那些情況。"},{"en":"Life can throw unexpected problems at students during exam season.","zh":"生活可能在考試季向學生帶來意想不到的問題。"},{"en":"If the environment throws cold, darkness and hunger at animals, only adapted species survive.","zh":"如果環境向動物施加寒冷、黑暗和飢餓，只有適應了的物種能生存。"},{"en":"The phrase is informal and shows challenges arriving forcefully.","zh":"這個短語較口語，顯示挑戰強力到來。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":15},{"front":"choose the correct answer","meaning":"選出正確答案","examples":[{"en":"Students must choose the correct answer from four options.","zh":"學生必須從四個選項中選出正確答案。"},{"en":"To choose the correct answer means to select the option that best matches the passage or question.","zh":"choose the correct answer 指選出最符合文章或題目的選項。"},{"en":"In a reading test, students should choose the correct answer after checking the evidence.","zh":"在閱讀測驗中，學生應檢查證據後選出正確答案。"},{"en":"If two options look similar, returning to the text helps avoid mistakes.","zh":"如果兩個選項看似相似，回到文本可以避免錯誤。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":15},{"front":"withstand extremely difficult living conditions","meaning":"承受極其艱難的生存環境","examples":[{"en":"Some Arctic animals can withstand extremely difficult living conditions.","zh":"一些北極動物可以承受極其艱難的生存環境。"},{"en":"To withstand extremely difficult living conditions means to survive very harsh environments.","zh":"withstand extremely difficult living conditions 指在非常嚴酷環境中生存。"},{"en":"Mountain villagers may withstand difficult living conditions when roads close in winter.","zh":"山區村民在冬天道路封閉時，可能承受艱難生活環境。"},{"en":"If animals withstand such conditions, they must have strong physical adaptations.","zh":"如果動物能承受這些環境，牠們必須有強大身體適應能力。"},{"en":"The phrase describes survival under severe hardship.","zh":"這個短語描述在嚴重艱難下生存。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":15},{"front":"during winter","meaning":"在冬季期間","examples":[{"en":"Many animals cannot survive in the Arctic during winter.","zh":"許多動物不能在冬季期間於北極生存。"},{"en":"During winter means in the winter season.","zh":"during winter 指在冬天這個季節中。"},{"en":"During winter, schools may close early if roads become icy.","zh":"在冬季期間，如果道路結冰，學校可能提早關閉。"},{"en":"If food is hard to find during winter, animals must store energy beforehand.","zh":"如果冬季期間難以找到食物，動物必須事先儲存能量。"},{"en":"The phrase gives the time when something happens.","zh":"這個短語給出某事發生的時間。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":15},{"front":"mainly reptilian","meaning":"主要是爬行類的","examples":[{"en":"The option incorrectly suggests that Arctic animals are mainly reptilian.","zh":"這個選項錯誤地暗示北極動物主要是爬行類的。"},{"en":"Mainly reptilian means mostly made up of reptiles.","zh":"mainly reptilian 指主要由爬行動物組成。"},{"en":"A zoo section may be mainly reptilian if it contains snakes, lizards and turtles.","zh":"如果動物園某區有蛇、蜥蜴和龜，它可能主要是爬行類的。"},{"en":"The Arctic is not mainly reptilian because reptiles cannot tolerate extreme cold well.","zh":"北極並非主要是爬行類的，因為爬行動物不能很好地忍受極寒。"},{"en":"The phrase describes the main animal type in a group.","zh":"這個短語描述群體中的主要動物類型。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":15},{"front":"frogs or toads","meaning":"青蛙或蟾蜍","examples":[{"en":"Frogs or toads would not survive the extreme Arctic winter.","zh":"青蛙或蟾蜍不能熬過極端北極冬季。"},{"en":"Frogs or toads are amphibians often found near water or damp places.","zh":"frogs or toads 是常在水邊或潮濕地方出現的兩棲動物。"},{"en":"Children may see frogs or toads near ponds after heavy rain.","zh":"孩子在大雨後可能在池塘附近看見青蛙或蟾蜍。"},{"en":"Because frogs or toads lack strong internal heat control, Arctic winter would kill them.","zh":"因為青蛙或蟾蜍缺乏強大的內部控溫能力，北極冬季會殺死牠們。"},{"en":"The phrase gives familiar examples of amphibians.","zh":"這個短語給出兩棲動物的熟悉例子。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":15},{"front":"on the surface of the snow","meaning":"在雪的表面","examples":[{"en":"Lemmings do not live mainly on the surface of the snow.","zh":"旅鼠並不主要生活在雪的表面。"},{"en":"On the surface of the snow means on top of the snow layer.","zh":"on the surface of the snow 指在雪層頂部。"},{"en":"Footprints on the surface of the snow can show where an animal has passed.","zh":"雪的表面上的腳印可以顯示動物走過哪裏。"},{"en":"If animals stay on the surface of the snow, they are exposed to wind and predators.","zh":"如果動物留在雪的表面，牠們會暴露於寒風和捕食者之中。"},{"en":"The phrase describes the visible top layer of snow.","zh":"這個短語描述雪可見的最上層。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":15},{"front":"under the frozen ocean","meaning":"在結冰海洋之下","examples":[{"en":"The option mentions tunnels under the frozen ocean.","zh":"選項提到在結冰海洋之下的隧道。"},{"en":"Under the frozen ocean means below the ice-covered sea.","zh":"under the frozen ocean 指在被冰覆蓋的海洋下面。"},{"en":"Scientists may study life under the frozen ocean using special equipment.","zh":"科學家可能用特殊設備研究結冰海洋之下的生命。"},{"en":"If tunnels were under the frozen ocean, they would be in a very different place from snow tunnels on land.","zh":"如果隧道在結冰海洋之下，它們就與陸地雪下隧道位置很不同。"},{"en":"The phrase describes a location beneath sea ice.","zh":"這個短語描述海冰下的位置。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":15},{"front":"deep underground","meaning":"在地底深處","examples":[{"en":"The option suggests that lemmings live deep underground.","zh":"這個選項暗示旅鼠生活在地底深處。"},{"en":"Deep underground means far below the surface of the earth.","zh":"deep underground 指在地表以下很深的位置。"},{"en":"Some train stations are built deep underground to avoid crowded streets.","zh":"一些火車站建在地底深處，以避開擠迫街道。"},{"en":"If animals live deep underground, they are far below the topsoil and snow.","zh":"如果動物住在地底深處，牠們就在表土和雪層以下很遠。"},{"en":"The phrase describes a position much lower than the surface.","zh":"這個短語描述遠低於表面的位置。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":15},{"front":"about 50 cm below","meaning":"在……以下約50厘米","examples":[{"en":"The lemming moves about 50 cm below the surface of the snow.","zh":"旅鼠在雪面以下約50厘米移動。"},{"en":"About 50 cm below means roughly half a metre underneath something.","zh":"about 50 cm below 指在某物下面大約半米。"},{"en":"A cable may be buried about 50 cm below a garden path.","zh":"電線可能埋在花園小徑以下約50厘米。"},{"en":"If an animal moves about 50 cm below snow, it is protected but still near the surface.","zh":"如果動物在雪下約50厘米移動，牠受到保護但仍接近表面。"},{"en":"The phrase gives an approximate depth.","zh":"這個短語給出大概深度。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":15},{"front":"common to all animal classes","meaning":"所有動物類別共有的","examples":[{"en":"Fur is not common to all animal classes.","zh":"毛皮並非所有動物類別共有的。"},{"en":"Common to all animal classes means found in every major group of animals.","zh":"common to all animal classes 指存在於每一個主要動物群體中。"},{"en":"Movement is common to many animal classes, but fur is not.","zh":"移動能力在許多動物類別中常見，但毛皮並不是。"},{"en":"If a feature is not common to all animal classes, it helps distinguish one group from another.","zh":"如果特徵並非所有動物類別共有，它就有助區分不同群體。"},{"en":"The phrase is useful for comparing biological groups.","zh":"這個短語適合比較生物群體。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":16},{"front":"unhelpful to","meaning":"對……沒有幫助","examples":[{"en":"Fur is not unhelpful to Arctic animals.","zh":"毛皮並非對北極動物沒有幫助。"},{"en":"Unhelpful to someone means not useful or not supportive for them.","zh":"unhelpful to 某人，指對他們沒有用或沒有支援作用。"},{"en":"A noisy study room is unhelpful to students who need concentration.","zh":"嘈吵自修室對需要專注的學生沒有幫助。"},{"en":"If a feature is unhelpful to survival, natural selection may not favour it.","zh":"如果某特徵對生存沒有幫助，自然選擇可能不會偏向它。"},{"en":"The phrase describes something that does not assist a person or animal.","zh":"這個短語描述某物不能幫助人或動物。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":16},{"front":"a good conductor of heat","meaning":"良好的導熱體","examples":[{"en":"A good conductor of heat transfers heat easily.","zh":"良好的導熱體容易傳遞熱量。"},{"en":"A good conductor of heat is a material that allows heat to pass through it quickly.","zh":"a good conductor of heat 是讓熱量快速通過的材料。"},{"en":"Metal is a good conductor of heat, so metal spoons become hot in soup.","zh":"金屬是良好導熱體，所以金屬匙放在湯中會變熱。"},{"en":"If fur trapped a good conductor of heat, body warmth would escape faster.","zh":"如果毛皮困住的是良好導熱體，體熱會更快流失。"},{"en":"The phrase describes strong heat-transfer ability.","zh":"這個短語描述強傳熱能力。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":16},{"front":"a bad conductor of heat","meaning":"不良導熱體","examples":[{"en":"Trapped air is a bad conductor of heat.","zh":"被困住的空氣是不良導熱體。"},{"en":"A bad conductor of heat does not transfer heat easily.","zh":"a bad conductor of heat 不容易傳遞熱量。"},{"en":"Wood is a bad conductor of heat compared with metal.","zh":"與金屬相比，木材是不良導熱體。"},{"en":"If trapped air is a bad conductor of heat, it helps keep body warmth near the skin.","zh":"如果被困住的空氣是不良導熱體，它就有助把體熱保留在皮膚附近。"},{"en":"The phrase explains why trapped air can insulate.","zh":"這個短語解釋為何被困空氣能保溫。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":16},{"front":"absorb heat and cold","meaning":"吸收熱和冷","examples":[{"en":"The option suggests that air absorbs heat and cold very well.","zh":"這個選項暗示空氣很能吸收熱和冷。"},{"en":"To absorb heat and cold means to take in thermal energy or coldness from the surroundings.","zh":"absorb heat and cold 指從周圍吸收熱能或寒冷影響。"},{"en":"Dark pavement may absorb heat from sunlight and feel hot underfoot.","zh":"深色行人路可能吸收陽光熱力，踩上去很熱。"},{"en":"If air absorbed heat too easily, it would not work well as insulation.","zh":"如果空氣太容易吸收熱量，它就不能很好地作保溫層。"},{"en":"The phrase is about taking in temperature effects.","zh":"這個短語關於吸收溫度影響。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":16},{"front":"the tip of the fur","meaning":"毛尖","examples":[{"en":"The temperature at the tip of the fur may be very low.","zh":"毛尖位置的溫度可能很低。"},{"en":"The tip of the fur is the outer end of a strand or layer of fur.","zh":"the tip of the fur 是毛髮或毛皮層的外端。"},{"en":"Snow may freeze on the tip of the fur while the skin underneath stays warm.","zh":"雪可能在毛尖結冰，而下面皮膚仍保持溫暖。"},{"en":"If the fur tip is cold, it shows the outer layer is exposed to the air.","zh":"如果毛尖寒冷，這顯示外層暴露於空氣中。"},{"en":"The phrase points to the fur’s outside edge.","zh":"這個短語指出毛皮的外邊緣。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":16},{"front":"the surface of the skin","meaning":"皮膚表面","examples":[{"en":"The temperature at the surface of the skin remains much warmer.","zh":"皮膚表面的溫度仍然溫暖得多。"},{"en":"The surface of the skin is the outer layer of an animal’s or person’s body.","zh":"the surface of the skin 是動物或人的身體外層。"},{"en":"Doctors may check the surface of the skin for colour, warmth or injury.","zh":"醫生可能檢查皮膚表面的顏色、溫度或傷口。"},{"en":"If the surface of the skin stays warm under fur, insulation is working well.","zh":"如果皮膚表面在毛皮下保持溫暖，保溫作用就運作良好。"},{"en":"The phrase identifies the body’s outside layer.","zh":"這個短語指出身體外層。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":16},{"front":"inside its body","meaning":"在其體內","examples":[{"en":"An endotherm generates heat inside its body.","zh":"內溫動物在其體內產生熱量。"},{"en":"Inside its body means within the animal’s own body, not outside it.","zh":"inside its body 指在動物自己的身體內部，而不是外部。"},{"en":"A bird digests food inside its body to release energy.","zh":"鳥在體內消化食物以釋放能量。"},{"en":"If heat is produced inside its body, an animal can stay warm without lying in the sun.","zh":"如果熱量在其體內產生，動物不用躺在陽光下也能保持溫暖。"},{"en":"The phrase describes an internal biological process.","zh":"這個短語描述內部生物過程。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":16},{"front":"special insulation","meaning":"特殊保溫作用","examples":[{"en":"Fur provides special insulation for Arctic mammals.","zh":"毛皮為北極哺乳動物提供特殊保溫作用。"},{"en":"Special insulation is protection against heat loss that is especially suited to a difficult environment.","zh":"special insulation 是特別適合困難環境的防止熱量流失保護。"},{"en":"A freezer bag uses special insulation to keep food cold during transport.","zh":"冷凍袋使用特殊保溫作用，在運輸途中保持食物寒冷。"},{"en":"If Arctic mammals have special insulation, they can survive freezing air more easily.","zh":"如果北極哺乳動物有特殊保溫作用，牠們就更容易在冰冷空氣中生存。"},{"en":"The phrase highlights protection designed for unusual conditions.","zh":"這個短語突出為特殊環境而有的保護。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":16},{"front":"cope with hot temperatures","meaning":"應付高溫","examples":[{"en":"The option says the animals cope with hot temperatures.","zh":"這個選項說動物應付高溫。"},{"en":"To cope with hot temperatures means to manage or survive in very warm conditions.","zh":"cope with hot temperatures 指處理或在很熱環境中生存。"},{"en":"Workers cope with hot temperatures by drinking water and taking shade breaks.","zh":"工人透過喝水和在陰影休息來應付高溫。"},{"en":"If an animal is built for cold, it may not cope well with hot temperatures.","zh":"如果動物適應寒冷，牠可能不善於應付高溫。"},{"en":"The phrase describes dealing with heat.","zh":"這個短語描述處理炎熱。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":16},{"front":"protect themselves from the elements","meaning":"保護自己免受惡劣天氣侵害","examples":[{"en":"Thermoregulation and fur help mammals protect themselves from the elements.","zh":"體溫調節和毛皮幫助哺乳動物保護自己免受惡劣天氣侵害。"},{"en":"To protect themselves from the elements means to shield their bodies from harsh weather.","zh":"protect themselves from the elements 指保護身體免受嚴酷天氣影響。"},{"en":"Campers protect themselves from the elements with tents, coats and waterproof boots.","zh":"露營者用帳篷、外套和防水靴保護自己免受惡劣天氣侵害。"},{"en":"If animals cannot protect themselves from wind and snow, they may lose heat quickly.","zh":"如果動物不能保護自己免受風雪侵害，牠們可能很快失去熱量。"},{"en":"The phrase focuses on defence against outdoor conditions.","zh":"這個短語重點在抵禦戶外環境。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":17},{"front":"regulate the temperature of their surroundings","meaning":"調節周圍環境的溫度","examples":[{"en":"Animals regulate their body temperature, not the temperature of their surroundings.","zh":"動物調節的是自己的體溫，而不是周圍環境的溫度。"},{"en":"To regulate the temperature of their surroundings means to control how warm or cold the environment is.","zh":"regulate the temperature of their surroundings 指控制環境有多暖或多冷。"},{"en":"An air conditioner regulates the temperature of a classroom’s surroundings, not a student’s body.","zh":"冷氣機調節課室周圍環境的溫度，而不是學生身體的溫度。"},{"en":"Animals can warm themselves internally, but they usually cannot control the air temperature around them.","zh":"動物可以在體內讓自己變暖，但通常不能控制周圍空氣溫度。"},{"en":"The phrase contrasts environmental control with body-temperature control.","zh":"這個短語把環境控制與體溫控制作對比。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":17},{"front":"create a layer of trapped air","meaning":"形成一層困住的空氣","examples":[{"en":"Dense fur helps create a layer of trapped air.","zh":"濃密毛皮幫助形成一層困住的空氣。"},{"en":"To create a layer of trapped air means to hold still air between hairs or materials.","zh":"create a layer of trapped air 指在毛髮或材料之間固定一層靜止空氣。"},{"en":"Double windows create a layer of trapped air that slows heat loss.","zh":"雙層窗形成一層困住的空氣，以減慢熱量流失。"},{"en":"If fur creates trapped air near the skin, the animal stays warmer.","zh":"如果毛皮在皮膚附近形成被困空氣，動物就會更暖。"},{"en":"The phrase explains how insulation is formed.","zh":"這個短語解釋保溫層如何形成。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":17},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students must complete the summary below using words from the passage.","zh":"學生必須使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the short text that follows.","zh":"complete the summary below 指在下面的短文中填入缺失字詞。"},{"en":"In a reading test, students complete the summary below by finding exact words from the article.","zh":"在閱讀測驗中，學生透過從文章找原字來完成以下摘要。"},{"en":"If students ignore grammar, their chosen words may not fit the summary.","zh":"如果學生忽略文法，所選字詞可能不適合摘要。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":17},{"front":"one word only","meaning":"只限一個詞","examples":[{"en":"The instructions require one word only from the passage.","zh":"指示要求只從文章中填一個詞。"},{"en":"One word only means the answer must contain exactly one word.","zh":"one word only 指答案必須只包含一個英文詞。"},{"en":"If the answer is “fur”, it follows a one-word-only instruction.","zh":"如果答案是 fur，它就符合只限一個詞的指示。"},{"en":"If students write two words when only one is allowed, the answer may be marked wrong.","zh":"如果只容許一個詞而學生寫兩個詞，答案可能被判錯。"},{"en":"The phrase gives a strict exam limit.","zh":"這個短語給出嚴格考試限制。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":17},{"front":"from the passage","meaning":"來自文章","examples":[{"en":"The answers must come from the passage.","zh":"答案必須來自文章。"},{"en":"From the passage means taken directly from the reading text.","zh":"from the passage 指直接取自閱讀文本。"},{"en":"In IELTS reading, answers often need words from the passage, not students’ own wording.","zh":"在 IELTS 閱讀中，答案常需要使用文章中的字詞，而不是學生自己的說法。"},{"en":"If the instruction says “from the passage”, guessing from general knowledge is risky.","zh":"如果指示說 from the passage，憑常識猜測就很危險。"},{"en":"The phrase reminds students to use evidence from the text.","zh":"這個短語提醒學生使用文本證據。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":17},{"front":"a select few","meaning":"少數精選；極少數","examples":[{"en":"Only a select few animals can survive the Arctic winter.","zh":"只有極少數動物能熬過北極冬季。"},{"en":"A select few means a very small number chosen or able to qualify.","zh":"a select few 指數量很少、被選中或有資格的人或事物。"},{"en":"Only a select few students may join an advanced class if places are limited.","zh":"如果名額有限，只有少數學生可以加入高階班。"},{"en":"If only a select few species survive, the environment must be extremely harsh.","zh":"如果只有極少數物種能生存，環境必定極度嚴酷。"},{"en":"The phrase stresses rarity and exclusiveness.","zh":"這個短語強調稀少和排他性。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":17},{"front":"show an amazing tolerance of","meaning":"對……表現出驚人耐受力","examples":[{"en":"Some animals show an amazing tolerance of severe winter conditions.","zh":"一些動物對嚴冬環境表現出驚人耐受力。"},{"en":"To show an amazing tolerance of something means to endure it surprisingly well.","zh":"show an amazing tolerance of 某事，指令人驚訝地能很好忍受它。"},{"en":"Some workers show an amazing tolerance of noise when repairing roads beside traffic.","zh":"一些工人在車流旁維修道路時，對噪音表現出驚人耐受力。"},{"en":"If animals tolerate severe winter, they can stay alive where others cannot.","zh":"如果動物能忍受嚴冬，牠們就能在其他動物不能生存的地方活下來。"},{"en":"The phrase praises an unusually strong ability to endure difficulty.","zh":"這個短語讚揚異常強大的忍耐困難能力。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":17},{"front":"severe winter conditions","meaning":"嚴冬環境","examples":[{"en":"Few animals can survive severe winter conditions.","zh":"很少動物能在嚴冬環境中生存。"},{"en":"Severe winter conditions are extremely cold, difficult or dangerous winter environments.","zh":"severe winter conditions 是極度寒冷、困難或危險的冬季環境。"},{"en":"Severe winter conditions may close roads, schools and outdoor markets.","zh":"嚴冬環境可能令道路、學校和戶外市場關閉。"},{"en":"If animals face severe winter conditions, food and warmth become hard to obtain.","zh":"如果動物面對嚴冬環境，食物和溫暖就很難取得。"},{"en":"The phrase describes winter at a dangerous level.","zh":"這個短語描述達到危險程度的冬天。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":17},{"front":"food resources","meaning":"食物資源","examples":[{"en":"Arctic animals use food resources to keep their bodies warm.","zh":"北極動物使用食物資源來保持身體溫暖。"},{"en":"Food resources are the food supplies available for survival and energy.","zh":"food resources 是可供生存和取得能量的食物供應。"},{"en":"A family plans food resources carefully before a long camping trip.","zh":"家庭在長途露營前會仔細計劃食物資源。"},{"en":"If food resources are limited, animals must choose between movement, warmth and growth.","zh":"如果食物資源有限，動物就必須在活動、保暖和生長之間取捨。"},{"en":"The phrase treats food as an important survival resource.","zh":"這個短語把食物視為重要生存資源。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":17},{"front":"keep their body temperature high","meaning":"保持體溫高","examples":[{"en":"The animals use energy to keep their body temperature high.","zh":"動物使用能量來保持體溫高。"},{"en":"To keep their body temperature high means to maintain enough internal warmth.","zh":"keep their body temperature high 指維持足夠內部溫暖。"},{"en":"People wear coats in winter to help keep their body temperature high.","zh":"人們冬天穿外套，以幫助保持體溫高。"},{"en":"If animals cannot keep body temperature high, their organs may not work properly.","zh":"如果動物不能保持體溫高，牠們的器官可能不能正常運作。"},{"en":"The phrase focuses on maintaining warmth inside the body.","zh":"這個短語重點在維持身體內部溫暖。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":18},{"front":"continue to run","meaning":"繼續運作","examples":[{"en":"The body’s biochemical processes continue to run when enough heat is produced.","zh":"當產生足夠熱量時，身體的生化過程會繼續運作。"},{"en":"To continue to run means to keep operating or working.","zh":"continue to run 指繼續運行或工作。"},{"en":"A school computer system can continue to run during a power cut if backup power works.","zh":"如果後備電源運作，學校電腦系統在停電期間可以繼續運作。"},{"en":"If body processes continue to run, an animal stays alive and functional.","zh":"如果身體過程繼續運作，動物就能保持存活和功能正常。"},{"en":"The phrase describes ongoing operation.","zh":"這個短語描述持續運行。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":18},{"front":"consist of thick layers of hair","meaning":"由厚密毛髮層組成","examples":[{"en":"Fur consists of thick layers of hair.","zh":"毛皮由厚密毛髮層組成。"},{"en":"To consist of thick layers of hair means to be made up of dense hair layers.","zh":"consist of thick layers of hair 指由濃密毛髮層構成。"},{"en":"A winter animal’s coat may consist of thick layers of hair that trap warm air.","zh":"冬季動物的毛皮可能由厚密毛髮層組成，以困住暖空氣。"},{"en":"If fur consists of thick layers, cold air has a harder time reaching the skin.","zh":"如果毛皮由厚密層組成，冷空氣就較難到達皮膚。"},{"en":"The phrase explains the structure of fur.","zh":"這個短語解釋毛皮結構。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":18},{"front":"provide insulation for","meaning":"為……提供保溫作用","examples":[{"en":"Fur provides insulation for Arctic mammals.","zh":"毛皮為北極哺乳動物提供保溫作用。"},{"en":"To provide insulation for someone means to give protection against heat loss or cold.","zh":"provide insulation for 某人或某物，指提供防止熱量流失或寒冷的保護。"},{"en":"A padded lunch bag provides insulation for hot food on the way to school.","zh":"加厚午餐袋在上學途中為熱食提供保溫作用。"},{"en":"If fur provides insulation for mammals, they spend less energy staying warm.","zh":"如果毛皮為哺乳動物提供保溫作用，牠們保持溫暖所需能量就較少。"},{"en":"The phrase describes giving warmth protection to someone or something.","zh":"這個短語描述為某人或某物提供保暖保護。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":18},{"front":"not a good conductor of heat","meaning":"不是良好的導熱體","examples":[{"en":"Trapped air is not a good conductor of heat.","zh":"被困住的空氣不是良好的導熱體。"},{"en":"Not a good conductor of heat means not able to transfer heat easily.","zh":"not a good conductor of heat 指不容易傳遞熱量。"},{"en":"Wood is not a good conductor of heat, so wooden handles stay cooler than metal ones.","zh":"木材不是良好的導熱體，所以木柄比金屬柄較不熱。"},{"en":"If trapped air is not a good conductor, it helps keep warmth near the body.","zh":"如果被困空氣不是良好導熱體，它就有助把溫暖保留在身體附近。"},{"en":"The phrase explains why air can insulate.","zh":"這個短語解釋為何空氣能保溫。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":18},{"front":"in the case of","meaning":"在……的情況下","examples":[{"en":"In the case of an Arctic mammal getting cold, its metabolic rate rises.","zh":"在北極哺乳動物變冷的情況下，其代謝率會上升。"},{"en":"In the case of something means when that situation happens.","zh":"in the case of 某事，指當該情況發生時。"},{"en":"In the case of a school fire drill, students must leave by the nearest exit.","zh":"在學校火警演習的情況下，學生必須從最近出口離開。"},{"en":"In the case of cold stress, mammals may produce more heat by using more energy.","zh":"在寒冷壓力的情況下，哺乳動物可能使用更多能量產生更多熱量。"},{"en":"The phrase introduces a specific situation.","zh":"這個短語引出特定情況。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":18},{"front":"deal with it by","meaning":"透過……處理","examples":[{"en":"The mammal deals with cold by increasing its metabolic rate.","zh":"哺乳動物透過提高代謝率來處理寒冷。"},{"en":"To deal with it by doing something means to handle a problem using that method.","zh":"deal with it by doing something 指用某方法處理問題。"},{"en":"A student may deal with exam stress by making a clear revision plan.","zh":"學生可能透過制定清晰溫習計劃來處理考試壓力。"},{"en":"If an animal deals with cold by raising metabolism, it burns more energy to stay warm.","zh":"如果動物透過提高代謝來處理寒冷，牠就會燃燒更多能量保暖。"},{"en":"The phrase links a problem with a solution.","zh":"這個短語把問題與解決方法連繫起來。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":18},{"front":"increasing its metabolic rate","meaning":"提高其代謝率","examples":[{"en":"An Arctic mammal warms itself by increasing its metabolic rate.","zh":"北極哺乳動物透過提高其代謝率讓自己變暖。"},{"en":"Increasing its metabolic rate means making the body use energy faster.","zh":"increasing its metabolic rate 指令身體更快使用能量。"},{"en":"A person increases metabolic rate during exercise because muscles need more fuel.","zh":"人在運動時會提高代謝率，因為肌肉需要更多燃料。"},{"en":"If an animal increases its metabolic rate, it can generate extra heat.","zh":"如果動物提高其代謝率，就能產生額外熱量。"},{"en":"The phrase describes a biological response to cold.","zh":"這個短語描述對寒冷的生物反應。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":18},{"front":"to generate more heat","meaning":"以產生更多熱量","examples":[{"en":"The animal raises its metabolic rate to generate more heat.","zh":"動物提高其代謝率，以產生更多熱量。"},{"en":"To generate more heat means in order to produce extra warmth.","zh":"to generate more heat 指為了產生額外溫暖。"},{"en":"A heater uses more electricity to generate more heat on a freezing night.","zh":"在冰冷夜晚，暖爐使用更多電力以產生更多熱量。"},{"en":"If a mammal needs to generate more heat, it must use more energy from food.","zh":"如果哺乳動物需要產生更多熱量，就必須使用更多來自食物的能量。"},{"en":"The phrase explains the purpose of raising metabolic rate.","zh":"這個短語解釋提高代謝率的目的。"}],"source":"80 - Arctic Survivors.pdf","sourcePage":18}],"ielts/reading/passage-2/Practice 81":[{"front":"Surf’s up","meaning":"有浪了；可以衝浪了","examples":[{"en":"“Surf’s up” is an informal expression used when the waves are good for surfing.","zh":"“Surf’s up” 是一個非正式表達，用於海浪適合滑浪時。"},{"en":"“Surf’s up” means the sea has suitable waves and surfers can go out.","zh":"“Surf’s up” 指海上有合適的浪，滑浪者可以下水。"},{"en":"A friend might shout “Surf’s up!” when they reach the beach and see strong clean waves.","zh":"朋友到達海灘，看見乾淨有力的浪時，可能會喊 “Surf’s up!”。"},{"en":"If the ocean is flat, nobody says “Surf’s up” because there are no waves to ride.","zh":"如果海面平靜，沒有人會說 “Surf’s up”，因為沒有浪可滑。"},{"en":"This phrase is casual and usually belongs to beach or surfing situations.","zh":"這個短語較口語，通常用於海灘或滑浪情境。"}],"source":"81 - Surfs Up.pdf","sourcePage":1},{"front":"major subdivisions of","meaning":"……的主要分支","examples":[{"en":"There are two major subdivisions of surfing.","zh":"滑浪有兩個主要分支。"},{"en":"Major subdivisions of something are the main smaller categories within a larger subject.","zh":"major subdivisions of something 指較大主題中的主要小類別。"},{"en":"A school subject may have major subdivisions such as reading, writing and speaking.","zh":"一個學科可能有閱讀、寫作和說話等主要分支。"},{"en":"Subdivisions help learners understand a broad topic by breaking it into clearer parts.","zh":"分支透過把廣泛主題拆成清楚部分，幫助學習者理解。"},{"en":"This phrase is useful when classifying a large activity or field.","zh":"這個短語適合用於分類大型活動或領域。"}],"source":"81 - Surfs Up.pdf","sourcePage":1},{"front":"surfing","meaning":"滑浪；衝浪","examples":[{"en":"Surfing is divided into longboarding and shortboarding.","zh":"滑浪分為長板滑浪和短板滑浪。"},{"en":"Surfing is a water sport in which people ride ocean waves on a board.","zh":"surfing 是一項水上運動，人們站在板上駕馭海浪。"},{"en":"A beginner may learn surfing at a beach with small waves and a coach nearby.","zh":"初學者可能在有細浪且有教練在旁的海灘學滑浪。"},{"en":"Surfing requires balance, swimming ability and awareness of sea conditions.","zh":"滑浪需要平衡、游泳能力和對海況的警覺。"},{"en":"This word refers to riding waves, not simply swimming in the sea.","zh":"這個詞指駕馭海浪，而不只是單純在海中游泳。"}],"source":"81 - Surfs Up.pdf","sourcePage":1},{"front":"longboarding and shortboarding","meaning":"長板滑浪和短板滑浪","examples":[{"en":"Longboarding and shortboarding are the two main types of surfing.","zh":"長板滑浪和短板滑浪是滑浪的兩個主要種類。"},{"en":"Longboarding and shortboarding are surfing styles based on different board lengths and techniques.","zh":"longboarding and shortboarding 是根據不同滑浪板長度和技巧而分的滑浪方式。"},{"en":"A surf school may start beginners with longboarding before they try shortboarding.","zh":"滑浪學校可能先讓初學者學長板滑浪，再嘗試短板滑浪。"},{"en":"Longboarding is often steadier, while shortboarding allows quicker turns.","zh":"長板滑浪通常較穩定，而短板滑浪容許更快速轉向。"},{"en":"This phrase compares two related but different ways of surfing.","zh":"這個短語比較兩種相關但不同的滑浪方式。"}],"source":"81 - Surfs Up.pdf","sourcePage":1},{"front":"respective names","meaning":"各自的名稱","examples":[{"en":"Their respective names represent differences in the surfboards used.","zh":"它們各自的名稱反映所使用滑浪板的差異。"},{"en":"Respective names means the names belonging separately to each item being discussed.","zh":"respective names 指正在討論的每一項各自所屬的名稱。"},{"en":"In a class list, students and their respective groups are shown side by side.","zh":"在班級名單中，學生和他們各自的小組會並排列出。"},{"en":"The respective names of two courses may reveal their different focus areas.","zh":"兩個課程各自的名稱可能顯示它們不同的重點。"},{"en":"This phrase is used when matching each thing with its own name or detail.","zh":"這個短語用於把每件事物與自己的名稱或細節配對。"}],"source":"81 - Surfs Up.pdf","sourcePage":1},{"front":"represent differences in","meaning":"反映……方面的差異","examples":[{"en":"Their names represent differences in the type of surfboard used.","zh":"它們的名稱反映所使用滑浪板種類方面的差異。"},{"en":"To represent differences in something means to show or stand for the ways things are not the same.","zh":"represent differences in something 指顯示或代表事物不相同的方式。"},{"en":"Different school uniforms may represent differences in year groups or teams.","zh":"不同校服可能反映年級或隊伍方面的差異。"},{"en":"Clear names help people understand differences before they learn the details.","zh":"清楚名稱幫助人們在學習細節前先理解差異。"},{"en":"This phrase links a label with the contrast it shows.","zh":"這個短語把標籤與其顯示的對比連繫起來。"}],"source":"81 - Surfs Up.pdf","sourcePage":1},{"front":"the type of surfboard used","meaning":"所使用的滑浪板種類","examples":[{"en":"The names show differences in the type of surfboard used.","zh":"這些名稱顯示所使用的滑浪板種類上的差異。"},{"en":"The type of surfboard used means the particular kind of board chosen for surfing.","zh":"type of surfboard used 指滑浪時選用的特定板類。"},{"en":"A coach chooses the type of surfboard used according to the learner’s size and skill.","zh":"教練會根據學員身形和技術選擇所使用的滑浪板種類。"},{"en":"The board type affects balance, speed and how sharply the surfer can turn.","zh":"滑浪板種類會影響平衡、速度和滑浪者轉向的急速程度。"},{"en":"This phrase focuses on equipment choice.","zh":"這個短語著重裝備選擇。"}],"source":"81 - Surfs Up.pdf","sourcePage":1},{"front":"as the name suggests","meaning":"顧名思義","examples":[{"en":"Longboards are, as the name suggests, much longer than shortboards.","zh":"長板顧名思義比短板長得多。"},{"en":"As the name suggests means the name itself gives a clue about the meaning.","zh":"as the name suggests 指名稱本身已提供意思線索。"},{"en":"A night school, as the name suggests, usually holds classes in the evening.","zh":"夜校顧名思義通常在晚上上課。"},{"en":"This phrase helps explain a term by pointing to its obvious wording.","zh":"這個短語透過指出名稱的明顯字面意思來解釋術語。"},{"en":"It is often used when the name is simple and descriptive.","zh":"當名稱簡單且具描述性時，常會使用這個短語。"}],"source":"81 - Surfs Up.pdf","sourcePage":1},{"front":"require a different riding style from","meaning":"需要與……不同的騎乘方式","examples":[{"en":"Longboards require a different riding style from shortboards.","zh":"長板需要與短板不同的滑浪方式。"},{"en":"To require a different riding style from something means to need a different way of standing, moving or controlling the board.","zh":"require a different riding style from something 指需要不同站姿、移動或控制板的方法。"},{"en":"A bicycle requires a different riding style from a skateboard because balance and steering are different.","zh":"單車需要與滑板不同的騎乘方式，因為平衡和轉向不同。"},{"en":"Different equipment can change the body movements needed for success.","zh":"不同裝備可以改變成功所需的身體動作。"},{"en":"This phrase clearly compares two methods of riding.","zh":"這個短語清楚比較兩種騎乘方法。"}],"source":"81 - Surfs Up.pdf","sourcePage":1},{"front":"riding style","meaning":"騎乘方式；滑浪方式","examples":[{"en":"Longboards and shortboards require different riding styles.","zh":"長板和短板需要不同的滑浪方式。"},{"en":"A riding style is the way a person balances, moves and controls a board, bike or animal while riding.","zh":"riding style 指人在騎乘滑板、單車或動物時平衡、移動和控制的方式。"},{"en":"A snowboarder’s riding style may be cautious at first and faster after practice.","zh":"滑雪板初學者的騎乘方式起初可能較謹慎，練習後會更快。"},{"en":"Good riding style helps prevent falls and makes movement smoother.","zh":"良好騎乘方式有助防止跌倒，並令動作更順暢。"},{"en":"This phrase describes technique, not fashion.","zh":"這個短語描述技巧，而不是時尚。"}],"source":"81 - Surfs Up.pdf","sourcePage":1},{"front":"were originally made of","meaning":"最初由……製成","examples":[{"en":"Surfboards were originally made of solid wood.","zh":"滑浪板最初由實木製成。"},{"en":"Were originally made of means were first produced using a particular material.","zh":"were originally made of 指最初使用某種材料製造。"},{"en":"Early school desks were originally made of heavy wood before lighter materials became common.","zh":"早期學校書桌最初由重木製成，後來較輕材料才變得常見。"},{"en":"New materials can change how easy an object is to carry or use.","zh":"新材料可以改變物件攜帶或使用的容易程度。"},{"en":"This phrase contrasts the first material with later developments.","zh":"這個短語把最初材料與後來發展作對比。"}],"source":"81 - Surfs Up.pdf","sourcePage":2},{"front":"solid wood","meaning":"實木","examples":[{"en":"Early surfboards were made of solid wood.","zh":"早期滑浪板由實木製成。"},{"en":"Solid wood is real wood, not hollow material, foam or thin imitation wood.","zh":"solid wood 指真正木材，不是中空材料、泡沫或薄仿木板。"},{"en":"A solid wood table is strong but may be heavy and expensive.","zh":"實木桌很堅固，但可能又重又昂貴。"},{"en":"Objects made from solid wood can last long, but they are often harder to move.","zh":"實木製物件可以耐用，但通常較難移動。"},{"en":"This phrase describes a dense natural material.","zh":"這個短語描述密實的天然材料。"}],"source":"81 - Surfs Up.pdf","sourcePage":2},{"front":"large and cumbersome","meaning":"又大又笨重","examples":[{"en":"Early surfboards were large and cumbersome.","zh":"早期滑浪板又大又笨重。"},{"en":"Large and cumbersome means big, heavy and difficult to move or handle.","zh":"large and cumbersome 指體積大、沉重且難以移動或操作。"},{"en":"An old television was large and cumbersome compared with a modern flat screen.","zh":"舊式電視與現代平面電視相比又大又笨重。"},{"en":"Cumbersome equipment can make a task slower and more tiring.","zh":"笨重設備會令任務更慢、更疲累。"},{"en":"This phrase describes something physically awkward to use.","zh":"這個短語描述使用起來很不方便的實物。"}],"source":"81 - Surfs Up.pdf","sourcePage":2},{"front":"weigh in excess of","meaning":"重量超過","examples":[{"en":"Some early surfboards weighed in excess of 100 pounds.","zh":"有些早期滑浪板重量超過一百磅。"},{"en":"To weigh in excess of an amount means to weigh more than that amount.","zh":"weigh in excess of an amount 指重量高於某個數量。"},{"en":"A heavy suitcase may weigh in excess of the airline limit and require an extra fee.","zh":"沉重行李可能重量超過航空公司限制，需要額外付費。"},{"en":"If equipment weighs too much, it becomes harder and less safe to carry.","zh":"如果設備太重，攜帶會更困難且較不安全。"},{"en":"This phrase is formal and often used with measurements.","zh":"這個短語較正式，常與量度數字一起使用。"}],"source":"81 - Surfs Up.pdf","sourcePage":2},{"front":"nowadays","meaning":"現今","examples":[{"en":"Nowadays, surfboards are usually made from lighter materials.","zh":"現今，滑浪板通常由較輕材料製成。"},{"en":"Nowadays means at the present time, compared with the past.","zh":"nowadays 指現時，相對於過去而言。"},{"en":"Nowadays, many students submit homework online rather than on paper.","zh":"現今，許多學生在網上提交功課，而不是用紙本。"},{"en":"This word often introduces a change from older habits or materials.","zh":"這個詞常引入由舊習慣或舊材料而來的轉變。"},{"en":"It helps compare past and present situations.","zh":"它幫助比較過去和現在的情況。"}],"source":"81 - Surfs Up.pdf","sourcePage":2},{"front":"more commonly constructed from","meaning":"較常由……製成","examples":[{"en":"Modern surfboards are more commonly constructed from polyurethane foam.","zh":"現代滑浪板較常由聚氨酯泡沫製成。"},{"en":"More commonly constructed from means more often built or made using a certain material.","zh":"more commonly constructed from 指較常使用某種材料建造或製成。"},{"en":"Modern school chairs are more commonly constructed from plastic and metal than solid wood.","zh":"現代學校椅較常由塑膠和金屬製成，而不是實木。"},{"en":"Materials become common when they are cheaper, lighter or easier to shape.","zh":"當材料較便宜、較輕或較易塑形，就會變得常見。"},{"en":"This phrase describes the usual material used in modern production.","zh":"這個短語描述現代生產中通常使用的材料。"}],"source":"81 - Surfs Up.pdf","sourcePage":2},{"front":"polyurethane foam","meaning":"聚氨酯泡沫","examples":[{"en":"Many modern surfboards are made from polyurethane foam.","zh":"許多現代滑浪板由聚氨酯泡沫製成。"},{"en":"Polyurethane foam is a light synthetic material often used inside surfboards and other products.","zh":"polyurethane foam 是一種輕身人造材料，常用於滑浪板和其他產品內部。"},{"en":"A mattress may contain polyurethane foam because it is soft and light.","zh":"床褥可能含有聚氨酯泡沫，因為它柔軟且輕。"},{"en":"Foam materials can reduce weight, making equipment easier to carry and control.","zh":"泡沫材料可以減輕重量，令設備較易攜帶和控制。"},{"en":"This phrase refers to a manufactured material, not natural wood.","zh":"這個短語指人造材料，而不是天然木材。"}],"source":"81 - Surfs Up.pdf","sourcePage":2},{"front":"making them much lighter","meaning":"令它們輕很多","examples":[{"en":"Polyurethane foam makes surfboards much lighter.","zh":"聚氨酯泡沫令滑浪板輕很多。"},{"en":"Making them much lighter means reducing their weight by a large amount.","zh":"making them much lighter 指大幅減少它們的重量。"},{"en":"Using aluminium instead of steel can make a bicycle much lighter.","zh":"使用鋁而不是鋼，可以令單車輕很多。"},{"en":"Lighter equipment is easier to carry, turn and control.","zh":"較輕設備較易攜帶、轉向和控制。"},{"en":"This phrase explains the result of using a different material.","zh":"這個短語解釋使用不同材料帶來的結果。"}],"source":"81 - Surfs Up.pdf","sourcePage":2},{"front":"better manoeuvrability","meaning":"更好的操控性","examples":[{"en":"Lighter surfboards give surfers better manoeuvrability.","zh":"較輕滑浪板給滑浪者更好的操控性。"},{"en":"Better manoeuvrability means being easier to turn, control and move accurately.","zh":"better manoeuvrability 指較容易轉向、控制和準確移動。"},{"en":"A small shopping trolley has better manoeuvrability in a crowded supermarket.","zh":"小型購物車在擁擠超市中有更好的操控性。"},{"en":"Better manoeuvrability helps people avoid obstacles and change direction quickly.","zh":"更好操控性幫助人避開障礙物並快速改變方向。"},{"en":"This phrase is often used for vehicles, boards and machines.","zh":"這個短語常用於車輛、板類和機器。"}],"source":"81 - Surfs Up.pdf","sourcePage":2},{"front":"especially beneficial for","meaning":"對……尤其有利","examples":[{"en":"Lighter boards are especially beneficial for longboarders.","zh":"較輕滑浪板對長板滑浪者尤其有利。"},{"en":"Especially beneficial for someone means particularly helpful or useful to that person or group.","zh":"especially beneficial for someone 指對某人或某群體特別有幫助或有用。"},{"en":"Online recordings are especially beneficial for students who need to review lessons slowly.","zh":"網上錄影對需要慢慢重溫課堂的學生尤其有利。"},{"en":"A feature may help everyone but be most useful to one specific group.","zh":"某功能可能幫到所有人，但對某特定群體最有用。"},{"en":"This phrase highlights who receives the greatest advantage.","zh":"這個短語突出誰得到最大好處。"}],"source":"81 - Surfs Up.pdf","sourcePage":2},{"front":"measure up to","meaning":"長達","examples":[{"en":"Some longboards can measure up to three metres in length.","zh":"有些長板長度可達三米。"},{"en":"To measure up to an amount means to reach that maximum size or length.","zh":"measure up to an amount 指達到某個最大尺寸或長度。"},{"en":"A classroom table may measure up to two metres if it is built for group work.","zh":"如果課室桌為小組工作而設，長度可能長達兩米。"},{"en":"Larger measurements can make an object more stable but harder to store.","zh":"較大尺寸可以令物件更穩定，但也較難存放。"},{"en":"This phrase gives an upper size limit.","zh":"這個短語給出尺寸上限。"}],"source":"81 - Surfs Up.pdf","sourcePage":3},{"front":"in length","meaning":"長度為","examples":[{"en":"Longboards can be up to three metres in length.","zh":"長板長度可達三米。"},{"en":"In length means measured from one end to the other.","zh":"in length 指從一端到另一端量度。"},{"en":"A school bus may be several metres in length, so it needs space to turn.","zh":"校巴長度可能有數米，因此需要空間轉彎。"},{"en":"Length affects how easy an object is to carry, store or control.","zh":"長度會影響物件攜帶、存放或控制的容易程度。"},{"en":"This phrase specifies that the measurement is about length, not weight or height.","zh":"這個短語指出該量度是關於長度，而不是重量或高度。"}],"source":"81 - Surfs Up.pdf","sourcePage":3},{"front":"successful longboarders","meaning":"成功的長板滑浪者","examples":[{"en":"Successful longboarders must learn difficult manoeuvres.","zh":"成功的長板滑浪者必須學會困難動作。"},{"en":"Successful longboarders are surfers who can control longboards well and perform the required skills.","zh":"successful longboarders 指能良好控制長板並做出所需技巧的滑浪者。"},{"en":"A successful longboarder can walk along the board without losing balance.","zh":"成功的長板滑浪者能在板上走動而不失平衡。"},{"en":"Practice helps longboarders move smoothly and catch waves more effectively.","zh":"練習幫助長板滑浪者更流暢移動並更有效接浪。"},{"en":"This phrase describes skill in a specific surfing style.","zh":"這個短語描述某一滑浪方式中的技巧。"}],"source":"81 - Surfs Up.pdf","sourcePage":3},{"front":"carry out difficult walking manoeuvres","meaning":"做出高難度步行動作","examples":[{"en":"Longboarders must carry out difficult walking manoeuvres on the board.","zh":"長板滑浪者必須在板上做出高難度步行動作。"},{"en":"To carry out difficult walking manoeuvres means to perform hard footwork movements while staying balanced.","zh":"carry out difficult walking manoeuvres 指在保持平衡下做出困難的步法動作。"},{"en":"A gymnast carries out difficult movements on a beam by controlling each step carefully.","zh":"體操運動員透過仔細控制每一步，在平衡木上做出高難度動作。"},{"en":"These manoeuvres require balance because one wrong step can make the surfer fall.","zh":"這些動作需要平衡，因為一步錯就可能令滑浪者跌倒。"},{"en":"This phrase focuses on performing a demanding physical skill.","zh":"這個短語著重執行要求高的身體技巧。"}],"source":"81 - Surfs Up.pdf","sourcePage":3},{"front":"up and down the board","meaning":"在板上前後走動","examples":[{"en":"Longboarders walk up and down the board while surfing.","zh":"長板滑浪者滑浪時會在板上前後走動。"},{"en":"Up and down the board means from one end of the board to the other and back again.","zh":"up and down the board 指從板的一端走到另一端，再走回來。"},{"en":"A child may move up and down a balance beam during practice.","zh":"孩子練習時可能在平衡木上前後走動。"},{"en":"Moving along the board helps surfers find the best balance point.","zh":"沿着板移動幫助滑浪者找到最佳平衡點。"},{"en":"This phrase describes movement along the length of something.","zh":"這個短語描述沿着某物長度移動。"}],"source":"81 - Surfs Up.pdf","sourcePage":3},{"front":"so as to","meaning":"以便；為了","examples":[{"en":"Longboarders move along the board so as to find the best position.","zh":"長板滑浪者沿着板移動，以便找到最佳位置。"},{"en":"So as to means in order to or for the purpose of doing something.","zh":"so as to 指為了做某事或以便達到某目的。"},{"en":"A student may sit near the front so as to hear the teacher clearly.","zh":"學生可能坐近前排，以便清楚聽到老師。"},{"en":"This phrase links an action with its purpose.","zh":"這個短語把行動與目的連繫起來。"},{"en":"It is more formal than simply saying “to”.","zh":"它比簡單說 to 較正式。"}],"source":"81 - Surfs Up.pdf","sourcePage":3},{"front":"set themselves in","meaning":"使自己處於……","examples":[{"en":"Longboarders set themselves in the optimal position for catching waves.","zh":"長板滑浪者使自己處於捕捉海浪的最佳位置。"},{"en":"To set themselves in a position means to place their body carefully in that position.","zh":"set themselves in a position 指仔細把身體放在某個位置。"},{"en":"A runner sets herself in the starting position before the race begins.","zh":"跑手在比賽開始前使自己處於起跑位置。"},{"en":"Correct body position can improve balance, speed and control.","zh":"正確身體位置可以改善平衡、速度和控制。"},{"en":"This phrase focuses on deliberately placing oneself.","zh":"這個短語著重有意識地安置自己。"}],"source":"81 - Surfs Up.pdf","sourcePage":3},{"front":"the optimal position","meaning":"最佳位置","examples":[{"en":"Longboarders try to stand in the optimal position.","zh":"長板滑浪者嘗試站在最佳位置。"},{"en":"The optimal position is the best possible place or body position for a particular purpose.","zh":"optimal position 指對某目的而言最好的地方或身體位置。"},{"en":"A student sits in the optimal position when they can see the board and hear clearly.","zh":"當學生能看清黑板並聽得清楚，就是坐在最佳位置。"},{"en":"Finding the optimal position can make a task easier and more effective.","zh":"找到最佳位置可以令任務更容易和更有效。"},{"en":"This phrase means the most suitable position, not just any comfortable one.","zh":"這個短語指最合適的位置，而不只是任何舒服位置。"}],"source":"81 - Surfs Up.pdf","sourcePage":3},{"front":"catching and riding the wave","meaning":"捕捉並駕馭海浪","examples":[{"en":"Surfers need the right position for catching and riding the wave.","zh":"滑浪者需要正確位置來捕捉並駕馭海浪。"},{"en":"Catching and riding the wave means getting onto a moving wave and staying on it while it carries the surfer forward.","zh":"catching and riding the wave 指追上移動中的海浪，並在它推動滑浪者前進時留在浪上。"},{"en":"A beginner first learns to catch a small wave before trying to ride a bigger one.","zh":"初學者會先學習接住小浪，再嘗試駕馭較大的浪。"},{"en":"Good timing helps surfers catch the wave instead of missing it.","zh":"良好時機幫助滑浪者追上浪，而不是錯過它。"},{"en":"This phrase describes the central action in surfing.","zh":"這個短語描述滑浪的核心動作。"}],"source":"81 - Surfs Up.pdf","sourcePage":3},{"front":"the lighter…, the easier…","meaning":"越……就越容易……","examples":[{"en":"The lighter the board, the easier it becomes to perform manoeuvres.","zh":"板越輕，就越容易做出動作。"},{"en":"The lighter…, the easier… means that as one thing becomes lighter, another action becomes easier.","zh":"the lighter…, the easier… 指某物越輕，另一個動作就越容易。"},{"en":"The lighter the school bag, the easier it is for a child to walk home.","zh":"書包越輕，孩子走路回家就越容易。"},{"en":"This pattern shows a direct relationship between two changes.","zh":"這個句式顯示兩個變化之間的直接關係。"},{"en":"It is useful for comparing cause and effect.","zh":"它適合用來比較原因和結果。"}],"source":"81 - Surfs Up.pdf","sourcePage":3},{"front":"execute such manoeuvres","meaning":"做出這類動作","examples":[{"en":"A lighter board helps surfers execute such manoeuvres.","zh":"較輕的板幫助滑浪者做出這類動作。"},{"en":"To execute such manoeuvres means to perform those difficult movements successfully.","zh":"execute such manoeuvres 指成功完成那些困難動作。"},{"en":"A dancer needs practice to execute complex turns without losing balance.","zh":"舞者需要練習才能在不失平衡下做出複雜轉身。"},{"en":"Lighter equipment can make difficult movements easier to complete.","zh":"較輕裝備可以令困難動作較容易完成。"},{"en":"This phrase is more formal than “do these moves”.","zh":"這個短語比 do these moves 較正式。"}],"source":"81 - Surfs Up.pdf","sourcePage":4},{"front":"benefit from greater manoeuvrability","meaning":"受惠於更高操控性","examples":[{"en":"Shortboarders also benefit from greater manoeuvrability.","zh":"短板滑浪者也受惠於更高操控性。"},{"en":"To benefit from greater manoeuvrability means to gain an advantage because something is easier to control and turn.","zh":"benefit from greater manoeuvrability 指因某物較易控制和轉向而得到好處。"},{"en":"A driver benefits from greater manoeuvrability when a small car fits through narrow streets.","zh":"小車能穿過狹窄街道時，司機就受惠於更高操控性。"},{"en":"Better control lets people react faster to obstacles or changing conditions.","zh":"更好控制讓人更快回應障礙或變化中的情況。"},{"en":"This phrase links improved control with practical advantage.","zh":"這個短語把改善控制與實際好處連繫起來。"}],"source":"81 - Surfs Up.pdf","sourcePage":4},{"front":"turn and adjust more quickly","meaning":"更快轉向和調整","examples":[{"en":"Shortboarders can turn and adjust more quickly on lighter boards.","zh":"短板滑浪者在較輕的板上可以更快轉向和調整。"},{"en":"To turn and adjust more quickly means to change direction and body position faster.","zh":"turn and adjust more quickly 指更快改變方向和身體位置。"},{"en":"A cyclist can turn and adjust more quickly on a lighter bike in busy traffic.","zh":"騎單車者在繁忙交通中，騎較輕單車可以更快轉向和調整。"},{"en":"Quick adjustment helps people avoid danger and keep balance.","zh":"快速調整幫助人避開危險並保持平衡。"},{"en":"This phrase describes faster control in motion.","zh":"這個短語描述移動中的更快控制。"}],"source":"81 - Surfs Up.pdf","sourcePage":4},{"front":"thanks to","meaning":"多虧；由於","examples":[{"en":"Surfers can move more easily thanks to lighter boards.","zh":"多虧較輕滑浪板，滑浪者可以更容易移動。"},{"en":"Thanks to something means because of it, usually with a positive result.","zh":"thanks to something 指因為某事，通常帶有正面結果。"},{"en":"Thanks to online maps, visitors can find the beach more easily.","zh":"多虧網上地圖，訪客可以更容易找到海灘。"},{"en":"Better tools can improve performance thanks to simpler control or lower weight.","zh":"更好的工具可以因控制較簡單或重量較低而改善表現。"},{"en":"This phrase gives credit to the cause of a good outcome.","zh":"這個短語把好結果歸功於其原因。"}],"source":"81 - Surfs Up.pdf","sourcePage":4},{"front":"it is claimed that","meaning":"有人聲稱","examples":[{"en":"It is claimed that surfing was first observed in 1767.","zh":"有人聲稱滑浪最早於 1767 年被觀察到。"},{"en":"It is claimed that means some people say something is true, though the writer may not fully prove it.","zh":"it is claimed that 指有人說某事是真的，但作者未必完全證明它。"},{"en":"It is claimed that a new diet works, but people should still check the evidence.","zh":"有人聲稱某種新飲食有效，但人們仍應檢查證據。"},{"en":"This phrase is useful when reporting an uncertain or debated statement.","zh":"這個短語適合用於報告不確定或有爭議的說法。"},{"en":"It creates distance between the writer and the claim.","zh":"它在作者與該說法之間保持距離。"}],"source":"81 - Surfs Up.pdf","sourcePage":4},{"front":"first observed by","meaning":"最早由……觀察到","examples":[{"en":"Surfing was first observed by European explorers.","zh":"滑浪最早由歐洲探險家觀察到。"},{"en":"First observed by someone means first noticed or recorded by that person or group.","zh":"first observed by someone 指最早由某人或某群體注意或記錄。"},{"en":"A rare bird may be first observed by a local guide during a forest survey.","zh":"稀有鳥類可能在森林調查中最早由本地導遊觀察到。"},{"en":"Being first observed by outsiders does not mean the activity began then.","zh":"由外來者最早觀察到，不代表該活動當時才開始。"},{"en":"This phrase focuses on recorded observation, not invention.","zh":"這個短語著重記錄觀察，而不是發明。"}],"source":"81 - Surfs Up.pdf","sourcePage":4},{"front":"European explorers","meaning":"歐洲探險家","examples":[{"en":"European explorers observed surfing among native Tahitians.","zh":"歐洲探險家在大溪地原住民之中觀察到滑浪。"},{"en":"European explorers were travellers from Europe who went to unfamiliar regions to investigate, trade or map them.","zh":"European explorers 指來自歐洲、前往陌生地區調查、貿易或繪製地圖的旅行者。"},{"en":"European explorers often wrote reports about customs they saw in other places.","zh":"歐洲探險家常撰寫關於他們在其他地方所見習俗的報告。"},{"en":"Their records can be useful, but they may reflect an outsider’s viewpoint.","zh":"他們的記錄可以有用，但可能反映外來者觀點。"},{"en":"This phrase identifies the observers, not the inventors of surfing.","zh":"這個短語指出觀察者，而不是滑浪的發明者。"}],"source":"81 - Surfs Up.pdf","sourcePage":4},{"front":"native Tahitians","meaning":"大溪地原住民","examples":[{"en":"European explorers observed surfing among native Tahitians.","zh":"歐洲探險家在大溪地原住民之中觀察到滑浪。"},{"en":"Native Tahitians are the Indigenous people of Tahiti.","zh":"native Tahitians 指大溪地的原住民。"},{"en":"Visitors should learn about native Tahitian culture through respectful sources and local voices.","zh":"訪客應透過尊重的資料來源和本地聲音了解大溪地原住民文化。"},{"en":"Observing a practice among native people does not mean outsiders created it.","zh":"在原住民之中觀察到某種做法，不代表外來者創造了它。"},{"en":"This phrase refers to the original people of a specific Pacific island.","zh":"這個短語指某個太平洋島嶼的原本居民。"}],"source":"81 - Surfs Up.pdf","sourcePage":4},{"front":"later travellers","meaning":"後來的旅客","examples":[{"en":"Later travellers reported seeing locals surfing near Hawaii.","zh":"後來的旅客報稱看見當地人在夏威夷附近滑浪。"},{"en":"Later travellers are people who visited after an earlier group of visitors or explorers.","zh":"later travellers 指在較早一批訪客或探險家之後到訪的人。"},{"en":"Later travellers may add new details that earlier reports missed.","zh":"後來的旅客可能補充早期報告漏掉的新細節。"},{"en":"Repeated reports from later travellers can strengthen evidence about a custom.","zh":"後來旅客的反覆報告可以加強某習俗的證據。"},{"en":"This phrase places observers in a later time period.","zh":"這個短語把觀察者放在較後的時段。"}],"source":"81 - Surfs Up.pdf","sourcePage":4},{"front":"reported seeing","meaning":"報稱看見","examples":[{"en":"Travellers reported seeing locals amusing themselves in the surf.","zh":"旅客報稱看見當地人在浪中自娛。"},{"en":"Reported seeing means said or wrote that they had seen something.","zh":"reported seeing 指說出或寫下自己曾看見某事。"},{"en":"Residents reported seeing smoke near the station before the fire alarm sounded.","zh":"火警響起前，居民報稱看見車站附近有煙。"},{"en":"A reported sighting may be useful, but it still depends on the observer’s accuracy.","zh":"報稱看見的資料可能有用，但仍取決於觀察者是否準確。"},{"en":"This phrase is used when passing on what someone claimed to observe.","zh":"這個短語用於轉述某人聲稱觀察到的事情。"}],"source":"81 - Surfs Up.pdf","sourcePage":4},{"front":"naked locals","meaning":"赤身裸體的當地人","examples":[{"en":"Travellers reported seeing naked locals surfing near Hawaii.","zh":"旅客報稱看見赤身裸體的當地人在夏威夷附近滑浪。"},{"en":"Naked locals means local people wearing no clothes, as described by the travellers.","zh":"naked locals 指旅客描述中沒有穿衣服的當地人。"},{"en":"Historical travel writing sometimes describes local people in ways that reflect outsider surprise.","zh":"歷史旅行文字有時以反映外來者驚訝的方式描述當地人。"},{"en":"Such descriptions should be read carefully because they may reveal the traveller’s attitude as well as the scene.","zh":"這類描述應謹慎閱讀，因為它們可能既反映場景，也反映旅客態度。"},{"en":"This phrase describes the people observed, not a rule about surfing.","zh":"這個短語描述被觀察的人，而不是滑浪規則。"}],"source":"81 - Surfs Up.pdf","sourcePage":5},{"front":"amusing themselves in the surf","meaning":"在浪中自娛","examples":[{"en":"The locals were amusing themselves in the surf off Hawaii.","zh":"當地人在夏威夷海岸外的浪中自娛。"},{"en":"Amusing themselves in the surf means enjoying themselves by playing or riding in the waves.","zh":"amusing themselves in the surf 指在浪中玩耍或駕浪來娛樂自己。"},{"en":"Children may amuse themselves in shallow water by jumping over small waves.","zh":"孩子可能在淺水中跳過小浪來自娛。"},{"en":"The phrase suggests recreation rather than work or competition.","zh":"這個短語表示娛樂，而不是工作或比賽。"},{"en":"It shows surfing as a form of enjoyment.","zh":"它把滑浪呈現為一種享受。"}],"source":"81 - Surfs Up.pdf","sourcePage":5},{"front":"off the coast of","meaning":"在……海岸外","examples":[{"en":"Travellers saw people surfing off the coast of Hawaii.","zh":"旅客看見人們在夏威夷海岸外滑浪。"},{"en":"Off the coast of a place means in the sea near that place’s shore.","zh":"off the coast of a place 指在某地海岸附近的海上。"},{"en":"Boats may fish off the coast of a small island.","zh":"船隻可能在小島海岸外捕魚。"},{"en":"Weather off the coast can be different from weather inland.","zh":"海岸外的天氣可能與內陸天氣不同。"},{"en":"This phrase locates something in nearby sea water.","zh":"這個短語把某事定位在近岸海域。"}],"source":"81 - Surfs Up.pdf","sourcePage":5},{"front":"one of the reasons why","meaning":"……的其中一個原因","examples":[{"en":"This may be one of the reasons why surfing is linked with Hawaii.","zh":"這可能是滑浪與夏威夷相連的其中一個原因。"},{"en":"One of the reasons why means one cause among several possible causes.","zh":"one of the reasons why 指幾個可能原因中的其中一個。"},{"en":"Good transport is one of the reasons why students choose a particular school.","zh":"良好交通是學生選擇某所學校的其中一個原因。"},{"en":"This phrase avoids claiming that there is only one explanation.","zh":"這個短語避免聲稱只有一個解釋。"},{"en":"It is useful when a result probably has several causes.","zh":"當某結果很可能有多個原因時，這個短語很有用。"}],"source":"81 - Surfs Up.pdf","sourcePage":5},{"front":"be synonymous with","meaning":"與……密不可分；等同於","examples":[{"en":"Surfing is often synonymous with the South Pacific.","zh":"滑浪常與南太平洋密不可分。"},{"en":"To be synonymous with something means to be strongly associated with it or almost represent it.","zh":"be synonymous with something 指與某事強烈相關，或幾乎代表它。"},{"en":"Fast food is often synonymous with quick meals, though not all quick meals are unhealthy.","zh":"快餐常等同於快捷餐點，雖然不是所有快捷餐點都不健康。"},{"en":"A place can become synonymous with a sport when people connect them closely in culture.","zh":"當人們在文化上把某地方與某運動緊密連結，該地方就可能與該運動密不可分。"},{"en":"This phrase does not always mean exact dictionary synonym.","zh":"這個短語不一定指字典上的完全同義詞。"}],"source":"81 - Surfs Up.pdf","sourcePage":5},{"front":"the South Pacific","meaning":"南太平洋","examples":[{"en":"Surfing is closely associated with the South Pacific.","zh":"滑浪與南太平洋密切相關。"},{"en":"The South Pacific is the southern region of the Pacific Ocean, including many island cultures.","zh":"South Pacific 指太平洋南部地區，包括許多島嶼文化。"},{"en":"Travel programmes often show the South Pacific through beaches, islands and ocean traditions.","zh":"旅遊節目常透過海灘、島嶼和海洋傳統展示南太平洋。"},{"en":"A sport can become linked with a region when its history and culture develop there.","zh":"當一項運動的歷史和文化在某地發展，它就會與該地區相連。"},{"en":"This phrase gives a broad geographical and cultural setting.","zh":"這個短語提供廣泛的地理和文化背景。"}],"source":"81 - Surfs Up.pdf","sourcePage":5},{"front":"in particular","meaning":"尤其是","examples":[{"en":"Surfing is associated with Hawaii in particular.","zh":"滑浪尤其與夏威夷相關。"},{"en":"In particular means especially or more specifically.","zh":"in particular 指尤其或更具體地說。"},{"en":"Many students enjoy languages, and English speaking in particular helps them in interviews.","zh":"許多學生喜歡語言，而英語口語尤其在面試中幫到他們。"},{"en":"This phrase narrows a general point to one important example.","zh":"這個短語把一般重點收窄到一個重要例子。"},{"en":"It helps readers see which item deserves special attention.","zh":"它幫助讀者看見哪一項值得特別注意。"}],"source":"81 - Surfs Up.pdf","sourcePage":5},{"front":"the popularity of surfing","meaning":"滑浪的受歡迎程度","examples":[{"en":"The popularity of surfing has spread far beyond Hawaii.","zh":"滑浪的受歡迎程度已遠遠傳播到夏威夷以外。"},{"en":"The popularity of surfing means how widely people enjoy, practise or follow surfing.","zh":"popularity of surfing 指人們多廣泛地喜歡、練習或關注滑浪。"},{"en":"The popularity of a sport can grow when schools, clubs and social media promote it.","zh":"當學校、俱樂部和社交媒體推廣某運動，其受歡迎程度可以上升。"},{"en":"When popularity spreads, more lessons, shops and competitions may appear.","zh":"當受歡迎程度擴散，更多課程、商店和比賽可能出現。"},{"en":"This phrase focuses on how many people are interested in surfing.","zh":"這個短語著重有多少人對滑浪感興趣。"}],"source":"81 - Surfs Up.pdf","sourcePage":5},{"front":"such that","meaning":"到……的程度","examples":[{"en":"The popularity of surfing is such that clubs have appeared almost everywhere.","zh":"滑浪受歡迎到滑浪會幾乎到處出現的程度。"},{"en":"Such that means to the degree that a particular result happens.","zh":"such that 指達到某種程度，以致某結果發生。"},{"en":"The demand for the course was such that the school opened another class.","zh":"課程需求高到學校另開一班的程度。"},{"en":"This phrase links a strong condition with its consequence.","zh":"這個短語把強烈情況與其後果連繫起來。"},{"en":"It is more formal than “so much that”.","zh":"它比 so much that 較正式。"}],"source":"81 - Surfs Up.pdf","sourcePage":5},{"front":"surf clubs","meaning":"滑浪會；滑浪俱樂部","examples":[{"en":"Surf clubs have appeared in many parts of the world.","zh":"滑浪會已出現在世界許多地方。"},{"en":"Surf clubs are groups or organisations where people learn, practise or organise surfing activities.","zh":"surf clubs 指人們學習、練習或組織滑浪活動的團體或組織。"},{"en":"A surf club may lend boards, arrange lessons and warn members about sea conditions.","zh":"滑浪會可能借出滑浪板、安排課堂並提醒會員海況。"},{"en":"Clubs help beginners join a sport safely by giving guidance and community support.","zh":"俱樂部透過提供指導和社群支援，幫助初學者安全參與運動。"},{"en":"This phrase refers to organised surfing groups.","zh":"這個短語指有組織的滑浪團體。"}],"source":"81 - Surfs Up.pdf","sourcePage":5},{"front":"have popped up","meaning":"湧現；突然出現","examples":[{"en":"Surf clubs have popped up almost everywhere.","zh":"滑浪會幾乎到處湧現。"},{"en":"Have popped up means have appeared suddenly or in many places.","zh":"have popped up 指突然出現或在許多地方出現。"},{"en":"New coffee shops have popped up near the station since the area became busy.","zh":"自從該區變得繁忙後，車站附近湧現了新咖啡店。"},{"en":"When an activity becomes popular, related businesses and clubs may pop up quickly.","zh":"當一項活動變得受歡迎，相關商店和俱樂部可能迅速出現。"},{"en":"This phrase is informal and suggests rapid appearance.","zh":"這個短語較口語，表示快速出現。"}],"source":"81 - Surfs Up.pdf","sourcePage":6},{"front":"almost everywhere","meaning":"幾乎到處","examples":[{"en":"Surf clubs have appeared almost everywhere.","zh":"滑浪會幾乎到處出現。"},{"en":"Almost everywhere means in many places, though not literally every place.","zh":"almost everywhere 指在很多地方，但不一定字面上每一個地方。"},{"en":"Smartphones are used almost everywhere, from buses to classrooms.","zh":"智能手機幾乎到處被使用，從巴士到課室都有。"},{"en":"A trend that spreads almost everywhere becomes part of ordinary life.","zh":"當潮流幾乎到處擴散，它就成為日常生活的一部分。"},{"en":"This phrase emphasises wide spread without being completely absolute.","zh":"這個短語強調廣泛擴散，但不是完全絕對。"}],"source":"81 - Surfs Up.pdf","sourcePage":6},{"front":"the windy west coast of Ireland","meaning":"愛爾蘭多風的西岸","examples":[{"en":"Surf clubs can be found on the windy west coast of Ireland.","zh":"愛爾蘭多風的西岸可以找到滑浪會。"},{"en":"The windy west coast of Ireland refers to Ireland’s western shoreline, where strong winds and waves can occur.","zh":"windy west coast of Ireland 指愛爾蘭西部海岸，那裡可能有強風和海浪。"},{"en":"A coastal town on Ireland’s west coast may attract surfers because of rougher sea conditions.","zh":"愛爾蘭西岸的沿海小鎮可能因較洶湧海況而吸引滑浪者。"},{"en":"Windy coasts can create good waves but also more challenging weather.","zh":"多風海岸可以產生好浪，但天氣也更具挑戰。"},{"en":"This phrase gives a specific example of a surfing location outside Hawaii.","zh":"這個短語提供夏威夷以外的滑浪地點例子。"}],"source":"81 - Surfs Up.pdf","sourcePage":6},{"front":"ultrachic Californian beaches","meaning":"極時尚的加州海灘","examples":[{"en":"Surfing is popular on ultrachic Californian beaches.","zh":"滑浪在極時尚的加州海灘很受歡迎。"},{"en":"Ultrachic Californian beaches are very fashionable beaches in California.","zh":"ultrachic Californian beaches 指加州非常時尚的海灘。"},{"en":"A beach with stylish cafés, surf shops and celebrities may be described as ultrachic.","zh":"有時尚咖啡店、滑浪店和名人的海灘，可以被形容為極時尚。"},{"en":"Fashionable places can attract tourists as well as serious surfers.","zh":"時尚地點可以吸引遊客，也可以吸引認真的滑浪者。"},{"en":"This phrase adds a glamorous image to the surfing location.","zh":"這個短語為滑浪地點加入迷人形象。"}],"source":"81 - Surfs Up.pdf","sourcePage":6},{"front":"indeed","meaning":"事實上","examples":[{"en":"Indeed, some of the most famous surfing takes place in Northern California.","zh":"事實上，一些最著名的滑浪活動在北加州進行。"},{"en":"Indeed is used to emphasise or confirm what has just been said.","zh":"indeed 用來強調或確認剛才所說的內容。"},{"en":"The course is useful; indeed, many students improved after one month.","zh":"這課程很有用；事實上，許多學生一個月後進步了。"},{"en":"Writers use indeed when the next point strengthens the previous point.","zh":"當下一點加強前一點時，作者會使用 indeed。"},{"en":"This word often means “in fact” or “actually”.","zh":"這個詞常表示「事實上」或「其實」。"}],"source":"81 - Surfs Up.pdf","sourcePage":6},{"front":"the most famous and glamorous surfing","meaning":"最著名和最有魅力的滑浪活動","examples":[{"en":"The most famous and glamorous surfing takes place in Northern California.","zh":"最著名和最有魅力的滑浪活動在北加州進行。"},{"en":"The most famous and glamorous surfing means surfing events or scenes that are widely known and attract admiration.","zh":"most famous and glamorous surfing 指廣為人知並令人欣賞的滑浪活動或場景。"},{"en":"A glamorous sports event often includes skilled athletes, media attention and a stylish setting.","zh":"有魅力的體育活動常包括高技術運動員、媒體關注和時尚場地。"},{"en":"Fame can attract more visitors, sponsors and learners to a sport.","zh":"名氣可以吸引更多訪客、贊助商和學員參與一項運動。"},{"en":"This phrase describes surfing that is both well-known and attractive.","zh":"這個短語描述既知名又吸引的滑浪活動。"}],"source":"81 - Surfs Up.pdf","sourcePage":6},{"front":"takes place","meaning":"發生；舉行","examples":[{"en":"Famous surfing takes place in Northern California.","zh":"著名滑浪活動在北加州舉行。"},{"en":"Takes place means happens or is held in a particular location or time.","zh":"takes place 指在某個地點或時間發生或舉行。"},{"en":"The school concert takes place in the hall every December.","zh":"學校音樂會每年十二月在禮堂舉行。"},{"en":"Knowing where an event takes place helps people plan transport and timing.","zh":"知道活動在哪裡舉行，有助人們規劃交通和時間。"},{"en":"This phrase is common when describing events or activities.","zh":"這個短語常用於描述活動或事件。"}],"source":"81 - Surfs Up.pdf","sourcePage":6},{"front":"prospective surfer","meaning":"準滑浪者；有意學滑浪的人","examples":[{"en":"A prospective surfer should consider the dangers first.","zh":"有意學滑浪的人應先考慮危險。"},{"en":"A prospective surfer is someone who is thinking about starting surfing.","zh":"prospective surfer 指正在考慮開始滑浪的人。"},{"en":"A prospective student visits a school before deciding whether to enrol.","zh":"準學生在決定是否入讀前會參觀學校。"},{"en":"Prospective surfers need basic safety information before entering the water.","zh":"準滑浪者下水前需要基本安全資訊。"},{"en":"This phrase refers to a future or possible surfer, not an experienced one.","zh":"這個短語指未來或可能成為滑浪者的人，而不是有經驗者。"}],"source":"81 - Surfs Up.pdf","sourcePage":6},{"front":"would be well advised to","meaning":"最好；應該","examples":[{"en":"A prospective surfer would be well advised to consider the risks.","zh":"有意學滑浪的人最好考慮風險。"},{"en":"Would be well advised to means should do something because it is sensible or safer.","zh":"would be well advised to 指應該做某事，因為這樣明智或較安全。"},{"en":"A new driver would be well advised to practise in quiet streets before busy roads.","zh":"新手司機最好先在安靜街道練習，再上繁忙道路。"},{"en":"This phrase gives strong but polite advice.","zh":"這個短語給出強烈但有禮貌的建議。"},{"en":"It often appears before warnings or practical recommendations.","zh":"它常出現在警告或實用建議前。"}],"source":"81 - Surfs Up.pdf","sourcePage":6},{"front":"consider the dangers associated with","meaning":"考慮與……相關的危險","examples":[{"en":"Beginners should consider the dangers associated with surfing.","zh":"初學者應考慮與滑浪相關的危險。"},{"en":"To consider the dangers associated with something means to think carefully about the risks connected to it.","zh":"consider the dangers associated with something 指仔細思考與某事有關的風險。"},{"en":"Parents should consider the dangers associated with children cycling on busy roads.","zh":"家長應考慮與孩子在繁忙道路踏單車相關的危險。"},{"en":"Considering dangers early helps people prepare safety rules and equipment.","zh":"及早考慮危險幫助人準備安全規則和裝備。"},{"en":"This phrase encourages careful risk awareness before action.","zh":"這個短語鼓勵人在行動前有風險意識。"}],"source":"81 - Surfs Up.pdf","sourcePage":6},{"front":"associated with","meaning":"與……相關","examples":[{"en":"There are several dangers associated with surfing.","zh":"有幾種危險與滑浪相關。"},{"en":"Associated with something means connected to it in some way.","zh":"associated with something 指以某種方式與某事相連。"},{"en":"Stress is often associated with poor sleep and weak concentration.","zh":"壓力常與睡眠差和專注力弱相關。"},{"en":"When a risk is associated with an activity, people should prepare for it.","zh":"當風險與某活動相關，人們就應作準備。"},{"en":"This phrase shows connection, not always direct cause.","zh":"這個短語顯示連繫，不一定表示直接原因。"}],"source":"81 - Surfs Up.pdf","sourcePage":7},{"front":"take to the waves","meaning":"下水滑浪；投入海浪","examples":[{"en":"A beginner should understand the risks before taking to the waves.","zh":"初學者在下水滑浪前應了解風險。"},{"en":"To take to the waves means to enter the sea and begin surfing or riding waves.","zh":"take to the waves 指進入海中開始滑浪或駕浪。"},{"en":"A child should learn basic swimming before taking to deep water.","zh":"孩子進入深水前應先學基本游泳。"},{"en":"Preparing before taking to the waves can prevent panic and accidents.","zh":"投入海浪前做好準備可以防止恐慌和意外。"},{"en":"This phrase gives surfing a lively, informal feeling.","zh":"這個短語令滑浪帶有生動、非正式的感覺。"}],"source":"81 - Surfs Up.pdf","sourcePage":7},{"front":"water sports","meaning":"水上運動","examples":[{"en":"Surfing carries risks like other water sports.","zh":"滑浪像其他水上運動一樣帶有風險。"},{"en":"Water sports are sports or activities done in or on water.","zh":"water sports 指在水中或水面上進行的運動或活動。"},{"en":"Swimming, kayaking and sailing are common water sports.","zh":"游泳、划艇和帆船都是常見水上運動。"},{"en":"Water sports require safety awareness because weather and water conditions can change quickly.","zh":"水上運動需要安全意識，因為天氣和水況可能快速改變。"},{"en":"This phrase groups activities connected with water.","zh":"這個短語概括與水相關的活動。"}],"source":"81 - Surfs Up.pdf","sourcePage":7},{"front":"carries with it","meaning":"伴隨着；帶有","examples":[{"en":"Surfing carries with it the inherent danger of drowning.","zh":"滑浪伴隨着溺水的固有危險。"},{"en":"Carries with it means includes or brings a particular risk, result or responsibility.","zh":"carries with it 指包含或帶來某種風險、結果或責任。"},{"en":"Driving carries with it the responsibility to protect passengers and pedestrians.","zh":"駕駛伴隨着保護乘客和行人的責任。"},{"en":"Exciting activities often carry risks that beginners must understand.","zh":"刺激活動常帶有初學者必須理解的風險。"},{"en":"This phrase links an activity with something that comes along with it.","zh":"這個短語把活動與隨之而來的事物連繫起來。"}],"source":"81 - Surfs Up.pdf","sourcePage":7},{"front":"the inherent danger of","meaning":"……的固有危險","examples":[{"en":"Surfing carries the inherent danger of drowning.","zh":"滑浪帶有溺水的固有危險。"},{"en":"The inherent danger of something is a risk that naturally belongs to that activity or situation.","zh":"inherent danger of something 指某活動或情況本身自然帶有的風險。"},{"en":"Mountain climbing has the inherent danger of falling from height.","zh":"登山有從高處墮下的固有危險。"},{"en":"Inherent dangers cannot always be removed, but they can be reduced with preparation.","zh":"固有危險不一定能完全消除，但可以透過準備降低。"},{"en":"This phrase describes a built-in risk.","zh":"這個短語描述內在風險。"}],"source":"81 - Surfs Up.pdf","sourcePage":7},{"front":"drowning","meaning":"溺水","examples":[{"en":"Drowning is one of the main dangers of surfing.","zh":"溺水是滑浪的主要危險之一。"},{"en":"Drowning happens when a person cannot breathe because they are underwater.","zh":"drowning 指人因在水下不能呼吸而出現的危險情況。"},{"en":"Weak swimmers face a higher risk of drowning in rough seas.","zh":"游泳能力弱的人在洶湧海中面對較高溺水風險。"},{"en":"Life jackets, swimming skill and quick rescue can reduce the risk of drowning.","zh":"救生衣、游泳能力和快速救援可以降低溺水風險。"},{"en":"This word refers to a serious water-related danger.","zh":"這個詞指嚴重的水上危險。"}],"source":"81 - Surfs Up.pdf","sourcePage":7},{"front":"the board itself","meaning":"滑浪板本身","examples":[{"en":"The board itself offers buoyancy.","zh":"滑浪板本身提供浮力。"},{"en":"The board itself means the surfboard alone, apart from the surfer or other equipment.","zh":"board itself 指單是滑浪板，而不包括滑浪者或其他裝備。"},{"en":"The bike itself may be light, but bags attached to it can make it heavy.","zh":"單車本身可能很輕，但掛上的袋可以令它變重。"},{"en":"Focusing on the object itself helps separate its direct features from other factors.","zh":"集中於物件本身，幫助把其直接特徵與其他因素分開。"},{"en":"This phrase highlights the surfboard as the subject.","zh":"這個短語突出滑浪板作為主體。"}],"source":"81 - Surfs Up.pdf","sourcePage":7},{"front":"offers buoyancy","meaning":"提供浮力","examples":[{"en":"A surfboard offers buoyancy in the water.","zh":"滑浪板在水中提供浮力。"},{"en":"To offer buoyancy means to help something or someone float.","zh":"offer buoyancy 指幫助某物或某人浮起。"},{"en":"A life jacket offers buoyancy so a swimmer can stay above water.","zh":"救生衣提供浮力，讓游泳者能留在水面上。"},{"en":"Buoyancy can help in water, but it does not remove every danger.","zh":"浮力可以在水中幫忙，但不能消除所有危險。"},{"en":"This phrase describes floating support.","zh":"這個短語描述浮起支援。"}],"source":"81 - Surfs Up.pdf","sourcePage":7},{"front":"be a hindrance","meaning":"成為阻礙","examples":[{"en":"A surfboard can also be a hindrance.","zh":"滑浪板也可以成為阻礙。"},{"en":"To be a hindrance means to make progress, movement or safety more difficult.","zh":"be a hindrance 指令進展、移動或安全變得更困難。"},{"en":"A heavy bag can be a hindrance when running for a bus.","zh":"趕巴士時，沉重袋子可以成為阻礙。"},{"en":"Something helpful in one situation can become a hindrance in another.","zh":"某物在一種情況下有幫助，在另一種情況下可以成為阻礙。"},{"en":"This phrase describes an obstacle or disadvantage.","zh":"這個短語描述障礙或不利因素。"}],"source":"81 - Surfs Up.pdf","sourcePage":7},{"front":"a deadly one at that","meaning":"而且可能是致命的阻礙","examples":[{"en":"A surfboard can be a hindrance, and a deadly one at that.","zh":"滑浪板可以成為阻礙，而且可能是致命的阻礙。"},{"en":"A deadly one at that means not only a problem, but a problem that can cause death.","zh":"deadly one at that 指不只是問題，而且是可能致命的問題。"},{"en":"A loose electrical wire is a danger, and a deadly one at that.","zh":"鬆脫電線是一種危險，而且是可能致命的危險。"},{"en":"This phrase adds strong emphasis after naming a problem.","zh":"這個短語在指出問題後加入強烈強調。"},{"en":"It warns that the risk is more serious than it first sounds.","zh":"它提醒風險比最初聽起來更嚴重。"}],"source":"81 - Surfs Up.pdf","sourcePage":7},{"front":"its leash becomes entangled in","meaning":"其繫繩纏在……上","examples":[{"en":"A surfboard can be dangerous if its leash becomes entangled in a reef.","zh":"如果滑浪板的繫繩纏在礁石上，它可能變得危險。"},{"en":"If its leash becomes entangled in something, the cord is caught or twisted around it.","zh":"its leash becomes entangled in something 指那條繩被某物卡住或纏繞。"},{"en":"A dog’s lead may become entangled in a bicycle wheel if the dog runs too close.","zh":"如果狗跑得太近，狗繩可能纏在單車輪上。"},{"en":"Entanglement can trap movement and turn a useful safety item into a danger.","zh":"纏繞會困住動作，把有用安全物品變成危險。"},{"en":"This phrase describes a cord getting caught.","zh":"這個短語描述繩索被卡住。"}],"source":"81 - Surfs Up.pdf","sourcePage":8},{"front":"a reef","meaning":"礁石","examples":[{"en":"A surfboard leash may become entangled in a reef.","zh":"滑浪板繫繩可能纏在礁石上。"},{"en":"A reef is a line or area of rock or coral under or near the surface of the sea.","zh":"reef 指海面下或海面附近的岩石或珊瑚帶。"},{"en":"Swimmers should avoid shallow reefs because waves can push them onto sharp coral.","zh":"游泳者應避開淺礁，因為海浪可能把他們推向尖銳珊瑚。"},{"en":"Reefs can create good waves but also dangerous collisions or entanglement.","zh":"礁石可以形成好浪，但也可能造成危險碰撞或纏繞。"},{"en":"This word refers to a natural underwater structure.","zh":"這個詞指天然水下結構。"}],"source":"81 - Surfs Up.pdf","sourcePage":8},{"front":"holding the surfer underwater","meaning":"把滑浪者困在水下","examples":[{"en":"A tangled leash may hold the surfer underwater.","zh":"纏住的繫繩可能把滑浪者困在水下。"},{"en":"Holding the surfer underwater means keeping the surfer below the surface so they cannot breathe easily.","zh":"holding the surfer underwater 指把滑浪者留在水面以下，使其難以呼吸。"},{"en":"A trapped rope can hold a swimmer underwater if it catches on a rock.","zh":"如果繩索卡在石頭上，可以把游泳者困在水下。"},{"en":"Being held underwater is dangerous because panic and lack of air can happen quickly.","zh":"被困水下很危險，因為恐慌和缺氧可以迅速發生。"},{"en":"This phrase describes a serious water-safety risk.","zh":"這個短語描述嚴重水上安全風險。"}],"source":"81 - Surfs Up.pdf","sourcePage":8},{"front":"ideal water conditions","meaning":"理想水況","examples":[{"en":"Ideal water conditions for surfing can be physically demanding.","zh":"滑浪的理想水況可能對身體要求很高。"},{"en":"Ideal water conditions are the sea conditions that are best for an activity.","zh":"ideal water conditions 指最適合某活動的海水或水域情況。"},{"en":"Calm clear water may be ideal for beginner swimming lessons.","zh":"平靜清澈的水可能最適合初學游泳課。"},{"en":"Conditions that are ideal for one sport may still require strength and skill.","zh":"對某運動理想的水況仍可能需要力量和技巧。"},{"en":"This phrase describes suitable water, not automatically safe water.","zh":"這個短語描述合適水況，而不代表一定安全。"}],"source":"81 - Surfs Up.pdf","sourcePage":8},{"front":"extremely demanding on the body","meaning":"對身體要求極高","examples":[{"en":"Surfing can be extremely demanding on the body.","zh":"滑浪可能對身體要求極高。"},{"en":"Extremely demanding on the body means requiring a lot of physical strength, energy and control.","zh":"extremely demanding on the body 指需要大量體力、能量和控制。"},{"en":"Carrying heavy boxes all day can be extremely demanding on the body.","zh":"整天搬重箱可以對身體要求極高。"},{"en":"Physically demanding sports can cause injury if people are unprepared.","zh":"對身體要求高的運動，如果沒有準備，可能造成受傷。"},{"en":"This phrase warns that the activity is hard on the body.","zh":"這個短語提醒該活動對身體負擔很大。"}],"source":"81 - Surfs Up.pdf","sourcePage":8},{"front":"competent swimmer","meaning":"游泳能力強的人","examples":[{"en":"A surfer must be a competent swimmer.","zh":"滑浪者必須是游泳能力強的人。"},{"en":"A competent swimmer is someone who can swim safely and confidently in suitable conditions.","zh":"competent swimmer 指能在合適情況下安全而有信心地游泳的人。"},{"en":"A competent swimmer can stay calm, float and return to shore when waves are moderate.","zh":"游泳能力強的人在中等浪況下能保持冷靜、浮起並返回岸邊。"},{"en":"Strong swimming ability reduces risk when a surfer falls off the board.","zh":"強游泳能力可在滑浪者跌下板時降低風險。"},{"en":"This phrase means more than knowing a few basic strokes.","zh":"這個短語不只是指懂幾種基本泳式。"}],"source":"81 - Surfs Up.pdf","sourcePage":8},{"front":"collisions with","meaning":"與……碰撞","examples":[{"en":"Collisions with sandbanks and reefs can be hazardous.","zh":"與沙洲和礁石碰撞可能很危險。"},{"en":"Collisions with something are crashes or hard impacts against it.","zh":"collisions with something 指撞上某物或與某物發生強烈撞擊。"},{"en":"Cyclists can be injured in collisions with car doors or road barriers.","zh":"騎單車者可能因與車門或道路護欄碰撞而受傷。"},{"en":"Collisions in water are dangerous because waves can add force and reduce control.","zh":"水中碰撞很危險，因為海浪會增加力量並降低控制。"},{"en":"This phrase describes physical impact with objects or people.","zh":"這個短語描述與物件或人發生實體撞擊。"}],"source":"81 - Surfs Up.pdf","sourcePage":8},{"front":"sandbanks","meaning":"沙洲","examples":[{"en":"Surfers may collide with sandbanks in shallow water.","zh":"滑浪者可能在淺水中與沙洲碰撞。"},{"en":"Sandbanks are raised areas of sand under shallow water or near a shore.","zh":"sandbanks 指淺水下或近岸處隆起的沙地。"},{"en":"Boats can get stuck on sandbanks if the water level falls.","zh":"如果水位下降，船隻可能擱淺在沙洲上。"},{"en":"Sandbanks can be difficult to see when waves cover them.","zh":"當海浪覆蓋沙洲時，它們可能難以看見。"},{"en":"This word refers to natural sand formations that may become obstacles.","zh":"這個詞指可能成為障礙物的天然沙地形。"}],"source":"81 - Surfs Up.pdf","sourcePage":8},{"front":"extremely hazardous","meaning":"極之危險","examples":[{"en":"Collisions while surfing can be extremely hazardous.","zh":"滑浪時碰撞可能極之危險。"},{"en":"Extremely hazardous means very dangerous and likely to cause harm.","zh":"extremely hazardous 指非常危險，並可能造成傷害。"},{"en":"Driving fast on icy roads is extremely hazardous.","zh":"在結冰道路上高速駕駛極之危險。"},{"en":"Hazardous situations require caution, skill and sometimes protective equipment.","zh":"危險情況需要謹慎、技巧，有時還需要保護裝備。"},{"en":"This phrase gives a strong warning about danger.","zh":"這個短語對危險作出強烈警告。"}],"source":"81 - Surfs Up.pdf","sourcePage":8},{"front":"lead to concussion","meaning":"導致腦震盪","examples":[{"en":"A serious collision can lead to concussion.","zh":"嚴重碰撞可以導致腦震盪。"},{"en":"To lead to concussion means to cause a brain injury after a blow to the head.","zh":"lead to concussion 指頭部受撞擊後造成腦部損傷。"},{"en":"A fall from a bicycle can lead to concussion if the rider hits their head.","zh":"如果騎車者撞到頭部，從單車跌下可以導致腦震盪。"},{"en":"Head injuries in water are especially dangerous because the person may become confused.","zh":"水中的頭部受傷尤其危險，因為人可能變得混亂。"},{"en":"This phrase links a physical impact with a medical result.","zh":"這個短語把身體撞擊與醫療結果連繫起來。"}],"source":"81 - Surfs Up.pdf","sourcePage":8},{"front":"concussion","meaning":"腦震盪","examples":[{"en":"Concussion can be life-threatening in the water.","zh":"腦震盪在水中可能危及生命。"},{"en":"Concussion is a brain injury caused by a hit or sudden movement of the head.","zh":"concussion 指由頭部撞擊或突然晃動造成的腦部損傷。"},{"en":"After a fall, a student with concussion may feel dizzy, confused or sick.","zh":"跌倒後，有腦震盪的學生可能感到頭暈、混亂或想嘔。"},{"en":"Concussion needs attention because symptoms may not appear immediately.","zh":"腦震盪需要留意，因為症狀未必立即出現。"},{"en":"This word describes a serious head injury, not a simple headache.","zh":"這個詞描述嚴重頭部受傷，而不是普通頭痛。"}],"source":"81 - Surfs Up.pdf","sourcePage":9},{"front":"a death sentence","meaning":"死刑；致命情況","examples":[{"en":"Concussion can be a death sentence if the surfer is not rescued quickly.","zh":"如果滑浪者沒有迅速獲救，腦震盪可能成為致命情況。"},{"en":"A death sentence here means a situation that is very likely to become fatal.","zh":"death sentence 在這裡指很可能變成致命的情況。"},{"en":"Being trapped in a burning room without help can become a death sentence.","zh":"被困在無人救援的火場房間中，可能成為致命情況。"},{"en":"This phrase is dramatic and stresses extreme danger.","zh":"這個短語語氣戲劇化，強調極端危險。"},{"en":"It does not mean a legal court sentence in this context.","zh":"在這個語境中，它不是指法律上的死刑判決。"}],"source":"81 - Surfs Up.pdf","sourcePage":9},{"front":"be rescued from the water","meaning":"從水中被救起","examples":[{"en":"A surfer must be rescued from the water quickly after a serious collision.","zh":"嚴重碰撞後，滑浪者必須迅速從水中被救起。"},{"en":"To be rescued from the water means to be helped out of the sea, pool or river when in danger.","zh":"be rescued from the water 指在危險時被人從海、泳池或河中救出。"},{"en":"Lifeguards rescued a tired swimmer from the water before the waves became stronger.","zh":"救生員在海浪變強前，把疲倦泳客從水中救起。"},{"en":"Quick rescue can prevent drowning after injury or exhaustion.","zh":"快速救援可以在受傷或疲勞後防止溺水。"},{"en":"This phrase focuses on emergency help in water.","zh":"這個短語著重水中的緊急救助。"}],"source":"81 - Surfs Up.pdf","sourcePage":9},{"front":"although rarer","meaning":"雖然較罕見","examples":[{"en":"Although rarer, attacks by marine animals can happen.","zh":"雖然較罕見，海洋動物襲擊仍可能發生。"},{"en":"Although rarer means even though something happens less often.","zh":"although rarer 指即使某事發生得較少。"},{"en":"Although rarer, serious allergic reactions can occur after eating common foods.","zh":"雖然較罕見，吃普通食物後也可能出現嚴重過敏反應。"},{"en":"A risk can be uncommon but still worth understanding.","zh":"風險可以不常見，但仍值得理解。"},{"en":"This phrase introduces a less frequent but still possible danger.","zh":"這個短語引入較少見但仍可能的危險。"}],"source":"81 - Surfs Up.pdf","sourcePage":9},{"front":"attacks by marine animals","meaning":"海洋動物襲擊","examples":[{"en":"Attacks by marine animals are a possible danger in surfing.","zh":"海洋動物襲擊是滑浪中的可能危險。"},{"en":"Attacks by marine animals are incidents in which sea animals bite, sting or otherwise harm people.","zh":"attacks by marine animals 指海洋動物咬傷、刺傷或以其他方式傷害人的事件。"},{"en":"Swimmers may face attacks by jellyfish if they enter the water during jellyfish season.","zh":"如果泳客在水母季節下水，可能面對水母襲擊。"},{"en":"Knowing local sea life helps reduce the risk of animal attacks.","zh":"了解當地海洋生物有助降低動物襲擊風險。"},{"en":"This phrase refers to danger from ocean creatures.","zh":"這個短語指來自海洋生物的危險。"}],"source":"81 - Surfs Up.pdf","sourcePage":9},{"front":"not uncommon","meaning":"並非罕見","examples":[{"en":"Attacks by marine animals are not uncommon.","zh":"海洋動物襲擊並非罕見。"},{"en":"Not uncommon means something happens often enough to be noticed, though it may not be very common.","zh":"not uncommon 指某事發生得足以被注意，雖然未必非常常見。"},{"en":"It is not uncommon for students to feel nervous before speaking exams.","zh":"學生在口試前感到緊張並非罕見。"},{"en":"This phrase is softer than saying “common” directly.","zh":"這個短語比直接說 common 語氣較溫和。"},{"en":"It suggests that something should not surprise us.","zh":"它表示某事不應令人太驚訝。"}],"source":"81 - Surfs Up.pdf","sourcePage":9},{"front":"sharks, rays, seals and jellyfish","meaning":"鯊魚、鰩魚、海豹和水母","examples":[{"en":"Sharks, rays, seals and jellyfish can threaten surfers.","zh":"鯊魚、鰩魚、海豹和水母可以威脅滑浪者。"},{"en":"Sharks, rays, seals and jellyfish are examples of marine animals that may injure people in the sea.","zh":"sharks, rays, seals and jellyfish 是可能在海中傷人的海洋動物例子。"},{"en":"Beach signs may warn swimmers if jellyfish or sharks have been seen nearby.","zh":"如果附近曾見到水母或鯊魚，海灘告示可能提醒泳客。"},{"en":"Different sea animals create different risks, such as bites, stings or collisions.","zh":"不同海洋動物造成不同風險，例如咬傷、刺傷或碰撞。"},{"en":"This phrase lists possible dangers from local sea life.","zh":"這個短語列出當地海洋生物可能帶來的危險。"}],"source":"81 - Surfs Up.pdf","sourcePage":9},{"front":"pose the greatest threats","meaning":"構成最大威脅","examples":[{"en":"Sharks and jellyfish pose some of the greatest threats.","zh":"鯊魚和水母構成一些最大威脅。"},{"en":"To pose the greatest threats means to create the most serious dangers.","zh":"pose the greatest threats 指造成最嚴重的危險。"},{"en":"In a kitchen, sharp knives and hot oil may pose the greatest threats to young children.","zh":"在廚房中，鋒利刀具和熱油可能對幼童構成最大威脅。"},{"en":"Identifying the greatest threats helps people prepare for the most serious risks first.","zh":"識別最大威脅幫助人們先準備面對最嚴重風險。"},{"en":"This phrase ranks dangers by seriousness.","zh":"這個短語按嚴重程度排列危險。"}],"source":"81 - Surfs Up.pdf","sourcePage":9},{"front":"a courageous soul","meaning":"勇敢的人","examples":[{"en":"You need to be a courageous soul to surf in dangerous conditions.","zh":"要在危險環境中滑浪，你需要成為一個勇敢的人。"},{"en":"A courageous soul is a brave person who is willing to face fear or danger.","zh":"courageous soul 指願意面對恐懼或危險的勇敢的人。"},{"en":"A courageous soul may speak up when others are afraid to defend a classmate.","zh":"當其他人害怕為同學辯護時，勇敢的人可能會站出來說話。"},{"en":"Courage is useful in risky sports, but it should be balanced with safety.","zh":"勇氣在高風險運動中有用，但應與安全平衡。"},{"en":"This phrase is informal and slightly dramatic.","zh":"這個短語較口語，帶一點戲劇化。"}],"source":"81 - Surfs Up.pdf","sourcePage":9},{"front":"brave the waves","meaning":"勇敢面對海浪","examples":[{"en":"Surfers must be willing to brave the waves.","zh":"滑浪者必須願意勇敢面對海浪。"},{"en":"To brave the waves means to face the sea and its waves despite fear or difficulty.","zh":"brave the waves 指即使害怕或困難，也面對海和海浪。"},{"en":"A sailor may brave rough weather to bring a boat safely back to harbour.","zh":"水手可能冒着惡劣天氣，把船安全帶回港口。"},{"en":"Braving danger does not mean ignoring safety rules.","zh":"勇敢面對危險不代表忽視安全規則。"},{"en":"This phrase shows courage in facing natural forces.","zh":"這個短語顯示面對自然力量的勇氣。"}],"source":"81 - Surfs Up.pdf","sourcePage":9},{"front":"insist on giving it a go","meaning":"堅持一試","examples":[{"en":"Some people still insist on giving surfing a go.","zh":"有些人仍然堅持一試滑浪。"},{"en":"To insist on giving it a go means to be determined to try something.","zh":"insist on giving it a go 指堅決要嘗試某事。"},{"en":"Even after failing once, a student may insist on giving the speech contest another go.","zh":"即使失敗一次，學生仍可能堅持再試演講比賽。"},{"en":"Determination can help people start new activities, but they should still prepare properly.","zh":"決心可以幫助人開始新活動，但仍應做好準備。"},{"en":"This phrase is informal and means “really want to try”.","zh":"這個短語較口語，意思是「很想試一試」。"}],"source":"81 - Surfs Up.pdf","sourcePage":10},{"front":"the rewards can be very gratifying","meaning":"回報可以很令人滿足","examples":[{"en":"The rewards of learning to surf can be very gratifying.","zh":"學習滑浪的回報可以很令人滿足。"},{"en":"The rewards can be very gratifying means the benefits can feel deeply satisfying.","zh":"rewards can be very gratifying 指好處可以令人有深刻滿足感。"},{"en":"Learning a difficult song can be gratifying when you finally play it smoothly.","zh":"當你終於流暢演奏一首困難歌曲時，學習成果可以很令人滿足。"},{"en":"Gratifying rewards often come after effort, practice and patience.","zh":"令人滿足的回報常在努力、練習和耐性後出現。"},{"en":"This phrase focuses on emotional satisfaction, not only money or prizes.","zh":"這個短語著重情感滿足，而不只是金錢或獎項。"}],"source":"81 - Surfs Up.pdf","sourcePage":10},{"front":"not too expensive to","meaning":"不算太昂貴去……","examples":[{"en":"Surfing is not too expensive to get started.","zh":"滑浪起步不算太昂貴。"},{"en":"Not too expensive to do something means the cost is not so high that beginners cannot try it.","zh":"not too expensive to do something 指費用不高到令初學者無法嘗試。"},{"en":"Learning to cook at home is not too expensive to start if you buy basic tools.","zh":"如果購買基本工具，在家學煮食起步不算太昂貴。"},{"en":"Lower starting costs make an activity more accessible to ordinary people.","zh":"較低起始成本令活動更容易被普通人參與。"},{"en":"This phrase compares cost with affordability.","zh":"這個短語比較成本和可負擔程度。"}],"source":"81 - Surfs Up.pdf","sourcePage":10},{"front":"get up and running","meaning":"開始運作；起步","examples":[{"en":"It is not too expensive to get up and running in surfing.","zh":"要開始滑浪，起步費用不算太昂貴。"},{"en":"To get up and running means to start doing an activity or operating a system.","zh":"get up and running 指開始做某活動或讓系統開始運作。"},{"en":"A small shop needs a payment system and basic stock to get up and running.","zh":"小店需要付款系統和基本貨品才能開始運作。"},{"en":"Once the basic equipment is ready, beginners can start practising.","zh":"一旦基本裝備準備好，初學者就可以開始練習。"},{"en":"This phrase focuses on the first practical stage of starting.","zh":"這個短語著重開始時的第一個實際階段。"}],"source":"81 - Surfs Up.pdf","sourcePage":10},{"front":"surf schools","meaning":"滑浪學校","examples":[{"en":"Surf schools offer courses for beginners.","zh":"滑浪學校為初學者提供課程。"},{"en":"Surf schools are places or organisations that teach people how to surf.","zh":"surf schools 指教授人們如何滑浪的地方或機構。"},{"en":"A surf school may provide boards, wetsuits, coaches and safety lessons.","zh":"滑浪學校可能提供滑浪板、防寒衣、教練和安全課。"},{"en":"Learning at a surf school can help beginners avoid unsafe habits.","zh":"在滑浪學校學習可以幫助初學者避免不安全習慣。"},{"en":"This phrase refers to organised instruction in surfing.","zh":"這個短語指有組織的滑浪教學。"}],"source":"81 - Surfs Up.pdf","sourcePage":10},{"front":"popular destinations","meaning":"受歡迎的目的地","examples":[{"en":"Surf schools operate in many popular destinations.","zh":"滑浪學校在許多受歡迎的目的地營運。"},{"en":"Popular destinations are places many people like to visit.","zh":"popular destinations 指很多人喜歡到訪的地方。"},{"en":"A beach town becomes a popular destination when it has clean water, transport and activities.","zh":"當海濱小鎮有乾淨海水、交通和活動，它就會成為受歡迎的目的地。"},{"en":"Popular destinations often develop hotels, lessons and rental services.","zh":"受歡迎的目的地常會發展酒店、課程和租借服務。"},{"en":"This phrase refers to well-liked travel places.","zh":"這個短語指受歡迎的旅遊地方。"}],"source":"81 - Surfs Up.pdf","sourcePage":10},{"front":"multi-day courses","meaning":"多天課程","examples":[{"en":"Surf schools offer multi-day courses.","zh":"滑浪學校提供多天課程。"},{"en":"Multi-day courses are courses that continue for more than one day.","zh":"multi-day courses 指持續多於一天的課程。"},{"en":"A language school may run a multi-day course during the summer holiday.","zh":"語言學校可能在暑假開辦多天課程。"},{"en":"Learning over several days gives students time to practise, rest and improve.","zh":"多天學習讓學生有時間練習、休息和進步。"},{"en":"This phrase contrasts longer courses with one-off lessons.","zh":"這個短語把較長課程與一次性課堂作對比。"}],"source":"81 - Surfs Up.pdf","sourcePage":10},{"front":"beginner and intermediate courses","meaning":"初級和中級課程","examples":[{"en":"Surf schools offer beginner and intermediate courses.","zh":"滑浪學校提供初級和中級課程。"},{"en":"Beginner and intermediate courses are classes for new learners and learners with some basic experience.","zh":"beginner and intermediate courses 指為新學員和已有一些基本經驗的學員而設的課程。"},{"en":"A piano school may offer beginner courses for new students and intermediate courses for those who can already read notes.","zh":"鋼琴學校可能為新學生提供初級課程，為已能讀譜者提供中級課程。"},{"en":"Dividing courses by level helps students learn at the right speed.","zh":"按程度分課程幫助學生以合適速度學習。"},{"en":"This phrase describes teaching levels.","zh":"這個短語描述教學程度。"}],"source":"81 - Surfs Up.pdf","sourcePage":10},{"front":"focus on the fundamentals","meaning":"專注於基礎","examples":[{"en":"Beginner courses focus on the fundamentals of surfing.","zh":"初級課程專注於滑浪基礎。"},{"en":"To focus on the fundamentals means to concentrate on the basic skills or ideas first.","zh":"focus on the fundamentals 指先集中學習基本技能或概念。"},{"en":"A writing class may focus on the fundamentals, such as sentence structure and paragraphing.","zh":"寫作課可能專注於句子結構和段落等基礎。"},{"en":"Strong basics make advanced skills easier to learn later.","zh":"穩固基礎會令日後學習進階技巧更容易。"},{"en":"This phrase stresses learning the foundation before difficult techniques.","zh":"這個短語強調先學根基，再學困難技巧。"}],"source":"81 - Surfs Up.pdf","sourcePage":10},{"front":"five-day courses","meaning":"五天課程","examples":[{"en":"Five-day courses can start from £100.","zh":"五天課程可以由一百英鎊起。"},{"en":"Five-day courses are courses that last for five days.","zh":"five-day courses 指持續五天的課程。"},{"en":"A five-day first-aid course may teach basic treatment, practice and final assessment.","zh":"五天急救課程可能教授基本處理、練習和最終評估。"},{"en":"A longer course can give learners repeated practice and feedback.","zh":"較長課程可以給學員反覆練習和回饋。"},{"en":"This phrase describes the duration of a course.","zh":"這個短語描述課程長度。"}],"source":"81 - Surfs Up.pdf","sourcePage":10},{"front":"start from as little as","meaning":"低至……起","examples":[{"en":"Five-day surfing courses start from as little as £100.","zh":"五天滑浪課程低至一百英鎊起。"},{"en":"Start from as little as means the lowest price begins at a surprisingly low amount.","zh":"start from as little as 指最低價格由一個相對低的金額開始。"},{"en":"Online courses may start from as little as £10 during a discount period.","zh":"網上課程在折扣期間可能低至十英鎊起。"},{"en":"A low starting price can attract beginners, but extra costs may still apply.","zh":"低起價可以吸引初學者，但仍可能有額外費用。"},{"en":"This phrase is often used in advertising or pricing.","zh":"這個短語常用於廣告或定價。"}],"source":"81 - Surfs Up.pdf","sourcePage":11},{"front":"all-inclusive camps","meaning":"全包營","examples":[{"en":"Some surf schools offer all-inclusive camps.","zh":"有些滑浪學校提供全包營。"},{"en":"All-inclusive camps are camps where one price covers most or all main costs.","zh":"all-inclusive camps 指一個價格涵蓋大部分或所有主要費用的營地。"},{"en":"A summer camp may be all-inclusive if the fee covers meals, rooms, lessons and activities.","zh":"如果費用包括膳食、房間、課堂和活動，暑期營可能是全包營。"},{"en":"All-inclusive packages reduce planning because students do not arrange everything separately.","zh":"全包套票減少規劃，因為學生不用逐項安排。"},{"en":"This phrase refers to a package that includes several services.","zh":"這個短語指包含多項服務的套裝。"}],"source":"81 - Surfs Up.pdf","sourcePage":11},{"front":"cover accommodation","meaning":"包括住宿","examples":[{"en":"All-inclusive camps cover accommodation, meals, lessons and equipment.","zh":"全包營包括住宿、膳食、課堂和裝備。"},{"en":"To cover accommodation means to include the cost or arrangement of a place to stay.","zh":"cover accommodation 指包括住宿地點的費用或安排。"},{"en":"A school trip fee may cover accommodation but not personal snacks.","zh":"學校旅行費用可能包括住宿，但不包括個人零食。"},{"en":"When accommodation is covered, travellers do not need to book rooms separately.","zh":"當住宿已包括在內，旅客就不用另外訂房。"},{"en":"This phrase explains what is included in a package.","zh":"這個短語解釋套裝包含甚麼。"}],"source":"81 - Surfs Up.pdf","sourcePage":11},{"front":"accommodation, meals, lessons and equipment","meaning":"住宿、膳食、課堂和裝備","examples":[{"en":"The camp fee covers accommodation, meals, lessons and equipment.","zh":"營費包括住宿、膳食、課堂和裝備。"},{"en":"Accommodation, meals, lessons and equipment are the main services included in some course packages.","zh":"accommodation, meals, lessons and equipment 指某些課程套裝包含的主要服務。"},{"en":"A sports camp may include a bed, food, coaching and gear rental.","zh":"運動營可能包括床位、食物、教練和裝備租借。"},{"en":"Including these items makes the total cost clearer for beginners.","zh":"包括這些項目會令初學者更清楚總費用。"},{"en":"This phrase lists what students receive for the fee.","zh":"這個短語列出學生付費後得到甚麼。"}],"source":"81 - Surfs Up.pdf","sourcePage":11},{"front":"given their superior paddling speed and stability","meaning":"鑑於其較佳划水速度和穩定性","examples":[{"en":"Longboards are used with beginners, given their superior paddling speed and stability.","zh":"鑑於長板有較佳划水速度和穩定性，它們會供初學者使用。"},{"en":"Given their superior paddling speed and stability means because they paddle better and feel steadier.","zh":"given their superior paddling speed and stability 指因為它們划水表現更好，而且較穩定。"},{"en":"Coaches may choose wider beginner skis given their greater stability on gentle slopes.","zh":"鑑於較寬初學者滑雪板在緩坡上有更高穩定性，教練可能選用它們。"},{"en":"Equipment that is stable and easy to move helps beginners feel safer.","zh":"穩定且容易移動的裝備幫助初學者感到更安全。"},{"en":"This phrase explains the reason for choosing longboards.","zh":"這個短語解釋為何選擇長板。"}],"source":"81 - Surfs Up.pdf","sourcePage":11},{"front":"superior paddling speed","meaning":"較佳划水速度","examples":[{"en":"Longboards have superior paddling speed.","zh":"長板有較佳划水速度。"},{"en":"Superior paddling speed means better speed when moving through water by paddling.","zh":"superior paddling speed 指划水前進時速度較好。"},{"en":"A longer kayak may have superior paddling speed on calm water.","zh":"較長獨木舟在平靜水面上可能有較佳划水速度。"},{"en":"Better paddling speed helps surfers reach waves before they pass.","zh":"更好划水速度幫助滑浪者在浪過去前追上它。"},{"en":"This phrase compares how efficiently equipment moves through water.","zh":"這個短語比較裝備在水中移動的效率。"}],"source":"81 - Surfs Up.pdf","sourcePage":11},{"front":"stability","meaning":"穩定性","examples":[{"en":"Longboards offer good stability for beginners.","zh":"長板為初學者提供良好穩定性。"},{"en":"Stability is the quality of staying balanced and not easily tipping over.","zh":"stability 指保持平衡、不容易翻倒的特質。"},{"en":"A wide chair has more stability than a narrow stool.","zh":"寬椅子比窄凳有更高穩定性。"},{"en":"Stability helps beginners practise without falling as often.","zh":"穩定性幫助初學者練習時較少跌倒。"},{"en":"This word is important when learning any balance-based activity.","zh":"學習任何需要平衡的活動時，這個詞都很重要。"}],"source":"81 - Surfs Up.pdf","sourcePage":11},{"front":"usually preferred by coaches","meaning":"通常較受教練青睞","examples":[{"en":"Longboards are usually preferred by coaches.","zh":"長板通常較受教練青睞。"},{"en":"Usually preferred by coaches means coaches normally choose them more often than alternatives.","zh":"usually preferred by coaches 指教練通常較常選擇它們，而不是其他選項。"},{"en":"Teachers may usually prefer simple books for beginners because they build confidence.","zh":"老師通常較青睞簡單書本給初學者，因為它們能建立信心。"},{"en":"Coaches choose equipment that helps learners succeed safely at the start.","zh":"教練會選擇能幫助學員安全起步成功的裝備。"},{"en":"This phrase describes a common professional preference.","zh":"這個短語描述常見專業偏好。"}],"source":"81 - Surfs Up.pdf","sourcePage":11},{"front":"for use with beginners","meaning":"供初學者使用","examples":[{"en":"Longboards are often chosen for use with beginners.","zh":"長板常被選作供初學者使用。"},{"en":"For use with beginners means intended to be used by or for people who are new to an activity.","zh":"for use with beginners 指預定給新學習某活動的人使用。"},{"en":"A language app may offer simple stories for use with beginners.","zh":"語言應用程式可能提供簡單故事供初學者使用。"},{"en":"Beginner-friendly tools reduce fear and help learners build basic skill.","zh":"適合初學者的工具可以減少恐懼，並幫助建立基本技能。"},{"en":"This phrase identifies the target users.","zh":"這個短語指出目標使用者。"}],"source":"81 - Surfs Up.pdf","sourcePage":11},{"front":"typically","meaning":"通常","examples":[{"en":"Typically, surfing courses break down the technique into separate skills.","zh":"通常，滑浪課程會把技巧分拆成個別技能。"},{"en":"Typically means usually or in the normal case.","zh":"typically 指通常或在一般情況下。"},{"en":"Typically, students learn basic grammar before writing long essays.","zh":"通常，學生先學基本文法，再寫長文章。"},{"en":"This word describes what generally happens, not what always happens.","zh":"這個詞描述一般會發生的事，而不是永遠如此。"},{"en":"It helps introduce a common pattern.","zh":"它幫助引入常見模式。"}],"source":"81 - Surfs Up.pdf","sourcePage":11},{"front":"break down the technique into","meaning":"把技巧分拆成……","examples":[{"en":"Coaches break down the technique into separate skills.","zh":"教練把技巧分拆成個別技能。"},{"en":"To break down the technique into parts means to divide a complex skill into smaller learnable steps.","zh":"break down the technique into parts 指把複雜技巧分成較小、可學習的步驟。"},{"en":"A teacher may break down essay writing into planning, topic sentences and editing.","zh":"老師可能把作文技巧分拆成計劃、主題句和修改。"},{"en":"Breaking a skill into parts makes it less confusing for beginners.","zh":"把技巧分拆成部分，會令初學者較不困惑。"},{"en":"This phrase describes a teaching method.","zh":"這個短語描述一種教學方法。"}],"source":"81 - Surfs Up.pdf","sourcePage":12},{"front":"separate skills","meaning":"個別技能","examples":[{"en":"Surfing technique can be taught as separate skills.","zh":"滑浪技巧可以作為個別技能教授。"},{"en":"Separate skills are individual abilities taught or practised one by one.","zh":"separate skills 指逐一教授或練習的個別能力。"},{"en":"In English, listening, speaking, reading and writing can be treated as separate skills.","zh":"在英文中，聽、說、讀、寫可以被視為個別技能。"},{"en":"Learning separate skills first can help students combine them later.","zh":"先學個別技能可以幫助學生之後把它們結合起來。"},{"en":"This phrase shows how a complex activity is divided for teaching.","zh":"這個短語顯示複雜活動如何被分拆來教學。"}],"source":"81 - Surfs Up.pdf","sourcePage":12},{"front":"get into position","meaning":"就位","examples":[{"en":"Beginners first learn how to get into position to catch a wave.","zh":"初學者首先學習如何就位以接浪。"},{"en":"To get into position means to move into the correct place or body posture before acting.","zh":"get into position 指在行動前移到正確地方或身體姿勢。"},{"en":"Players get into position before the football match begins.","zh":"足球比賽開始前，球員會就位。"},{"en":"Correct positioning makes the next action easier and safer.","zh":"正確就位令下一個動作更容易、更安全。"},{"en":"This phrase often comes before a physical task.","zh":"這個短語常出現在身體任務前。"}],"source":"81 - Surfs Up.pdf","sourcePage":12},{"front":"catch a wave","meaning":"追上浪；接浪","examples":[{"en":"Surfers must learn how to catch a wave.","zh":"滑浪者必須學會如何接浪。"},{"en":"To catch a wave means to move onto a wave at the right moment so it carries the surfer forward.","zh":"catch a wave 指在正確時刻進入海浪，讓浪推動滑浪者前進。"},{"en":"Beginners often miss waves until they learn when to paddle.","zh":"初學者在學會何時划水前，常會錯過浪。"},{"en":"Good timing and position help a surfer catch a wave successfully.","zh":"良好時機和位置幫助滑浪者成功接浪。"},{"en":"This phrase describes the first key step in riding a wave.","zh":"這個短語描述駕馭海浪的第一個關鍵步驟。"}],"source":"81 - Surfs Up.pdf","sourcePage":12},{"front":"ride the wave without falling off","meaning":"駕馭海浪而不跌下來","examples":[{"en":"Beginners learn how to ride the wave without falling off.","zh":"初學者學習如何駕馭海浪而不跌下來。"},{"en":"To ride the wave without falling off means to stay balanced on the board while the wave carries you.","zh":"ride the wave without falling off 指在浪推動你時，保持平衡留在滑浪板上。"},{"en":"A child learning a scooter first tries to move forward without falling off.","zh":"孩子學滑板車時，首先嘗試向前移動而不跌下來。"},{"en":"Balance, timing and relaxed knees help a surfer stay on the board.","zh":"平衡、時機和放鬆膝蓋幫助滑浪者留在板上。"},{"en":"This phrase describes successful control during movement.","zh":"這個短語描述移動中的成功控制。"}],"source":"81 - Surfs Up.pdf","sourcePage":12},{"front":"falling off","meaning":"跌下來","examples":[{"en":"Beginners often worry about falling off the board.","zh":"初學者常擔心從滑浪板上跌下來。"},{"en":"Falling off means losing balance and coming down from something you were on.","zh":"falling off 指失去平衡並從原本乘坐或站立的東西上下來。"},{"en":"A child may fear falling off a bicycle during the first lesson.","zh":"孩子第一次學單車時可能害怕跌下來。"},{"en":"Falling off is common when learning a balance-based sport.","zh":"學習需要平衡的運動時，跌下來很常見。"},{"en":"This phrase describes a normal beginner risk.","zh":"這個短語描述正常初學者風險。"}],"source":"81 - Surfs Up.pdf","sourcePage":12},{"front":"balance plays a crucial role","meaning":"平衡起關鍵作用","examples":[{"en":"Balance plays a crucial role in surfing.","zh":"平衡在滑浪中起關鍵作用。"},{"en":"Balance plays a crucial role means balance is extremely important for success.","zh":"balance plays a crucial role 指平衡對成功極為重要。"},{"en":"Time management plays a crucial role in exam preparation.","zh":"時間管理在備考中起關鍵作用。"},{"en":"If balance is weak, a surfer may fall even when the wave is small.","zh":"如果平衡弱，即使浪很小，滑浪者也可能跌倒。"},{"en":"This phrase highlights a key factor in an activity.","zh":"這個短語突出活動中的關鍵因素。"}],"source":"81 - Surfs Up.pdf","sourcePage":12},{"front":"dedicated to","meaning":"用於；專門撥給","examples":[{"en":"A lot of time is dedicated to balance training.","zh":"很多時間專門用於平衡訓練。"},{"en":"Dedicated to something means set aside or used specially for that purpose.","zh":"dedicated to something 指特別留出或用於某目的。"},{"en":"A school may dedicate one afternoon each week to reading practice.","zh":"學校可能每星期專門撥出一個下午作閱讀練習。"},{"en":"When time is dedicated to a skill, learners get repeated practice.","zh":"當時間專門用於某技能，學習者就能反覆練習。"},{"en":"This phrase shows deliberate allocation of time or effort.","zh":"這個短語顯示有意識地分配時間或努力。"}],"source":"81 - Surfs Up.pdf","sourcePage":12},{"front":"balance training exercises","meaning":"平衡訓練練習","examples":[{"en":"Surf schools use balance training exercises with beginners.","zh":"滑浪學校會對初學者使用平衡訓練練習。"},{"en":"Balance training exercises are activities designed to improve the ability to stay steady.","zh":"balance training exercises 指設計用來改善保持穩定能力的活動。"},{"en":"Standing on one leg can be a simple balance training exercise.","zh":"單腳站立可以是一項簡單平衡訓練練習。"},{"en":"Better balance reduces falls and improves control in sports.","zh":"更好平衡可以減少跌倒並改善運動控制。"},{"en":"This phrase refers to practice for physical stability.","zh":"這個短語指身體穩定性的練習。"}],"source":"81 - Surfs Up.pdf","sourcePage":12},{"front":"difficult though it may be to","meaning":"儘管……可能很困難","examples":[{"en":"Difficult though it may be to master surfing, the sport is rewarding.","zh":"儘管掌握滑浪可能很困難，這項運動仍很有回報。"},{"en":"Difficult though it may be to do something means although doing it may be difficult.","zh":"difficult though it may be to do something 指雖然做某事可能困難。"},{"en":"Difficult though it may be to speak in public, practice can make it less frightening.","zh":"儘管公開演說可能很困難，練習可以令它較不嚇人。"},{"en":"This structure admits a challenge while keeping a positive main point.","zh":"這個結構承認挑戰，同時保留正面主旨。"},{"en":"It is a formal way to say “although it may be difficult”.","zh":"它是說 although it may be difficult 的正式方式。"}],"source":"81 - Surfs Up.pdf","sourcePage":12},{"front":"master the art of surfing","meaning":"掌握滑浪技巧","examples":[{"en":"It takes time to master the art of surfing.","zh":"掌握滑浪技巧需要時間。"},{"en":"To master the art of surfing means to become highly skilled at surfing.","zh":"master the art of surfing 指在滑浪方面變得非常熟練。"},{"en":"A pianist may need years to master the art of performing in public.","zh":"鋼琴家可能需要多年才能掌握公開表演技巧。"},{"en":"Mastery comes from practice, feedback and learning from mistakes.","zh":"精通來自練習、回饋和從錯誤中學習。"},{"en":"This phrase describes deep skill, not just basic ability.","zh":"這個短語描述深層技巧，而不只是基本能力。"}],"source":"81 - Surfs Up.pdf","sourcePage":13},{"front":"extremely rewarding","meaning":"非常有滿足感","examples":[{"en":"Surfing can be extremely rewarding.","zh":"滑浪可以非常有滿足感。"},{"en":"Extremely rewarding means giving a strong feeling of satisfaction or achievement.","zh":"extremely rewarding 指帶來強烈滿足感或成就感。"},{"en":"Teaching a child to read can be extremely rewarding when they finish their first book.","zh":"當孩子讀完第一本書，教孩子閱讀可以非常有滿足感。"},{"en":"Difficult activities often feel more rewarding after effort and progress.","zh":"困難活動在努力和進步後常更令人滿足。"},{"en":"This phrase focuses on emotional return.","zh":"這個短語著重情感上的回報。"}],"source":"81 - Surfs Up.pdf","sourcePage":13},{"front":"few feelings to compare with","meaning":"很少感覺可與……相比","examples":[{"en":"There are few feelings to compare with riding your first wave.","zh":"很少感覺可與駕馭你的第一個浪相比。"},{"en":"Few feelings to compare with something means very few experiences feel as special or powerful.","zh":"few feelings to compare with something 指很少經驗能像某事一樣特別或強烈。"},{"en":"There are few feelings to compare with hearing a crowd clap after your first speech.","zh":"很少感覺可與第一次演講後聽到掌聲相比。"},{"en":"This phrase strongly praises an experience by saying it is hard to match.","zh":"這個短語透過說某經驗難以匹敵來強烈讚賞它。"},{"en":"It is used for memorable emotional moments.","zh":"它用於令人難忘的情感時刻。"}],"source":"81 - Surfs Up.pdf","sourcePage":13},{"front":"the exhilaration of","meaning":"……帶來的興奮感","examples":[{"en":"Surfers remember the exhilaration of riding their first wave.","zh":"滑浪者會記得駕馭第一個浪帶來的興奮感。"},{"en":"The exhilaration of something is the strong excitement and joy caused by it.","zh":"exhilaration of something 指某事帶來的強烈興奮和快樂。"},{"en":"A runner may feel the exhilaration of crossing the finish line after months of training.","zh":"跑手經過數月訓練後衝過終點，可能感到興奮。"},{"en":"Exhilaration often comes when fear, effort and success meet.","zh":"興奮感常在恐懼、努力和成功交會時出現。"},{"en":"This phrase describes a powerful positive feeling.","zh":"這個短語描述強烈正面感受。"}],"source":"81 - Surfs Up.pdf","sourcePage":13},{"front":"riding out your first wave","meaning":"成功駕馭你的第一個浪","examples":[{"en":"The exhilaration of riding out your first wave is hard to forget.","zh":"成功駕馭你的第一個浪所帶來的興奮感難以忘記。"},{"en":"Riding out your first wave means successfully staying on the board through your first complete wave.","zh":"riding out your first wave 指第一次完整地留在板上成功駕馭一個浪。"},{"en":"A learner driver remembers the feeling of completing a first smooth journey alone.","zh":"學車者會記得第一次獨自順利完成路程的感覺。"},{"en":"First successful experiences can build confidence for harder challenges.","zh":"第一次成功經驗可以為更難挑戰建立信心。"},{"en":"This phrase describes a first complete success in surfing.","zh":"這個短語描述滑浪中的第一次完整成功。"}],"source":"81 - Surfs Up.pdf","sourcePage":13},{"front":"daredevil adrenaline junkies","meaning":"愛冒險、追求刺激的人","examples":[{"en":"Daredevil adrenaline junkies may enjoy surfing.","zh":"愛冒險、追求刺激的人可能喜歡滑浪。"},{"en":"Daredevil adrenaline junkies are people who enjoy danger, speed and excitement.","zh":"daredevil adrenaline junkies 指喜歡危險、速度和刺激的人。"},{"en":"Some people who love roller coasters are adrenaline junkies because they enjoy the rush.","zh":"有些喜歡過山車的人是追求刺激的人，因為他們享受那種刺激感。"},{"en":"Such people may be attracted to risky sports, but they still need safety training.","zh":"這類人可能被高風險運動吸引，但仍需要安全訓練。"},{"en":"This phrase is informal and describes thrill-seekers.","zh":"這個短語較口語，用來描述追求刺激的人。"}],"source":"81 - Surfs Up.pdf","sourcePage":13},{"front":"fancy having a go","meaning":"想試一試","examples":[{"en":"Some readers may fancy having a go at surfing.","zh":"有些讀者可能想試一試滑浪。"},{"en":"To fancy having a go means to feel like trying something.","zh":"fancy having a go 指想嘗試某事。"},{"en":"After watching a cooking video, a student may fancy having a go at making bread.","zh":"看完煮食影片後，學生可能想試一試做麵包。"},{"en":"This phrase is informal and suggests curiosity rather than firm commitment.","zh":"這個短語較口語，表示好奇，而不是堅定承諾。"},{"en":"It is common in British English.","zh":"它常見於英式英語。"}],"source":"81 - Surfs Up.pdf","sourcePage":13},{"front":"details of","meaning":"……的詳情","examples":[{"en":"Details of a surf club can be found online.","zh":"滑浪會的詳情可以在網上找到。"},{"en":"Details of something are the specific information about it.","zh":"details of something 指關於某事的具體資料。"},{"en":"Details of a course may include price, time, location and teacher name.","zh":"課程詳情可能包括價格、時間、地點和老師姓名。"},{"en":"Clear details help people decide whether to join or apply.","zh":"清楚詳情幫助人們決定是否參加或申請。"},{"en":"This phrase introduces practical information.","zh":"這個短語引入實用資訊。"}],"source":"81 - Surfs Up.pdf","sourcePage":13},{"front":"a surf club near you","meaning":"你附近的滑浪會","examples":[{"en":"You can look for a surf club near you.","zh":"你可以尋找你附近的滑浪會。"},{"en":"A surf club near you is a local surfing group or organisation close to where you live.","zh":"surf club near you 指靠近你居住地方的本地滑浪團體或組織。"},{"en":"A beginner may join a surf club near home to practise regularly.","zh":"初學者可能加入家附近的滑浪會，以便定期練習。"},{"en":"Local clubs can make learning easier because travel time and costs are lower.","zh":"本地俱樂部可以令學習更容易，因為交通時間和成本較低。"},{"en":"This phrase is often used when directing readers to local options.","zh":"這個短語常用於引導讀者尋找本地選項。"}],"source":"81 - Surfs Up.pdf","sourcePage":13},{"front":"can be found on","meaning":"可在……找到","examples":[{"en":"Details of local surf clubs can be found on the association’s website.","zh":"本地滑浪會的詳情可在協會網站找到。"},{"en":"Can be found on means information is available in a particular place or source.","zh":"can be found on 指資料可於某特定地方或來源取得。"},{"en":"Bus times can be found on the transport company’s app.","zh":"巴士時間可在交通公司的應用程式找到。"},{"en":"Telling people where information can be found makes action easier.","zh":"告訴人們資訊在哪裡可以找到，會令行動更容易。"},{"en":"This phrase is useful for giving directions to information.","zh":"這個短語適合用於指示資料來源。"}],"source":"81 - Surfs Up.pdf","sourcePage":13},{"front":"British Surfing Association","meaning":"英國滑浪協會","examples":[{"en":"The British Surfing Association provides information about surf clubs.","zh":"英國滑浪協會提供關於滑浪會的資訊。"},{"en":"The British Surfing Association is an organisation connected with surfing in Britain.","zh":"British Surfing Association 是與英國滑浪相關的組織。"},{"en":"A sports association may list clubs, coaches and safety advice for beginners.","zh":"體育協會可能列出俱樂部、教練和初學者安全建議。"},{"en":"Associations help organise a sport and make information easier to find.","zh":"協會幫助組織一項運動，並令資訊更易找到。"},{"en":"This phrase names a specific surfing organisation.","zh":"這個短語命名一個特定滑浪組織。"}],"source":"81 - Surfs Up.pdf","sourcePage":14},{"front":"try to remember","meaning":"試着記住","examples":[{"en":"Try to remember that shark attacks are rare.","zh":"試着記住鯊魚襲擊很罕見。"},{"en":"Try to remember means make an effort to keep a fact in mind.","zh":"try to remember 指努力把某事記在心中。"},{"en":"Before an exam, students should try to remember to read every instruction carefully.","zh":"考試前，學生應試着記住仔細閱讀每條指示。"},{"en":"Remembering a calming fact can reduce unnecessary fear.","zh":"記住一個令人安心的事實可以減少不必要恐懼。"},{"en":"This phrase gives gentle advice.","zh":"這個短語給出溫和建議。"}],"source":"81 - Surfs Up.pdf","sourcePage":14},{"front":"feet dangle over","meaning":"雙腳懸在……外","examples":[{"en":"Your feet may dangle over the side of the board.","zh":"你的雙腳可能懸在滑浪板邊緣外。"},{"en":"If feet dangle over something, they hang loosely beyond its edge.","zh":"feet dangle over something 指雙腳鬆鬆地垂在某物邊緣外。"},{"en":"A child’s feet may dangle over a high chair if they cannot reach the floor.","zh":"如果孩子腳碰不到地，雙腳可能懸在高椅外。"},{"en":"Dangling feet in water may make beginners imagine danger below them.","zh":"雙腳懸在水中可能令初學者想像下方有危險。"},{"en":"This phrase describes loose hanging movement.","zh":"這個短語描述鬆散垂下的動作。"}],"source":"81 - Surfs Up.pdf","sourcePage":14},{"front":"over the side of the board","meaning":"在滑浪板邊緣外","examples":[{"en":"A surfer’s feet may dangle over the side of the board.","zh":"滑浪者的雙腳可能懸在滑浪板邊緣外。"},{"en":"Over the side of the board means beyond the edge of the surfboard.","zh":"over the side of the board 指超出滑浪板邊緣。"},{"en":"A bag hanging over the side of a chair may fall if someone walks past.","zh":"掛在椅子邊緣外的袋子，如果有人走過可能跌下來。"},{"en":"When body parts go over the edge, they may touch water, ground or nearby objects.","zh":"當身體部分伸出邊緣外，可能接觸水、地面或附近物件。"},{"en":"This phrase gives a precise position.","zh":"這個短語給出精確位置。"}],"source":"81 - Surfs Up.pdf","sourcePage":14},{"front":"Jaws was just a film","meaning":"《大白鯊》只是一部電影","examples":[{"en":"Jaws was just a film, so beginners should not panic.","zh":"《大白鯊》只是一部電影，所以初學者不應恐慌。"},{"en":"“Jaws was just a film” means the famous shark movie should not make people exaggerate real shark risk.","zh":"Jaws was just a film 指那部著名鯊魚電影不應令人誇大真實鯊魚風險。"},{"en":"A scary movie can make a danger feel more common than it really is.","zh":"恐怖電影可以令某種危險感覺比實際更常見。"},{"en":"Remembering that fiction is not reality can help beginners stay calm.","zh":"記住虛構不等於現實，可以幫助初學者保持冷靜。"},{"en":"This phrase is a humorous reassurance about shark attacks.","zh":"這個短語是關於鯊魚襲擊的幽默安慰。"}],"source":"81 - Surfs Up.pdf","sourcePage":14},{"front":"almost certainly","meaning":"幾乎肯定","examples":[{"en":"A shark attack almost certainly will not happen to you.","zh":"鯊魚襲擊幾乎肯定不會發生在你身上。"},{"en":"Almost certainly means very likely, though not completely guaranteed.","zh":"almost certainly 指非常可能，雖然不是百分之百保證。"},{"en":"If you study every week, you will almost certainly understand the basics better.","zh":"如果你每星期學習，幾乎肯定會更理解基礎。"},{"en":"This phrase expresses strong probability without claiming absolute certainty.","zh":"這個短語表達強烈可能性，但不聲稱絕對確定。"},{"en":"It is useful when reassuring someone realistically.","zh":"它適合用於實事求是地安慰別人。"}],"source":"81 - Surfs Up.pdf","sourcePage":14},{"front":"happen to you","meaning":"發生在你身上","examples":[{"en":"The writer jokes that a shark attack probably will not happen to you.","zh":"作者開玩笑說鯊魚襲擊大概不會發生在你身上。"},{"en":"Happen to you means occur in your own experience or affect you personally.","zh":"happen to you 指在你自己的經驗中發生或親自影響你。"},{"en":"A student may worry that a difficult question will happen to them in the exam.","zh":"學生可能擔心困難題目會在考試中發生在自己身上。"},{"en":"People often fear rare events more when they imagine them happening personally.","zh":"當人們想像罕見事件親自發生時，常會更害怕。"},{"en":"This phrase focuses on whether an event affects a particular person.","zh":"這個短語著重事件是否影響某個特定的人。"}],"source":"81 - Surfs Up.pdf","sourcePage":14},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter for each multiple-choice question.","zh":"學生為每條多項選擇題選出正確字母。"},{"en":"To choose the correct letter means to select the option marked by the right letter.","zh":"choose the correct letter 指選出由正確字母標示的選項。"},{"en":"In a test, a student may understand the answer but lose marks by copying the wrong letter.","zh":"在測驗中，學生可能理解答案，但因抄錯字母而失分。"},{"en":"Checking letters carefully prevents careless answer-sheet mistakes.","zh":"仔細檢查字母可以避免答題紙上的粗心錯誤。"},{"en":"This phrase is an instruction about answer format.","zh":"這個短語是關於答案格式的指示。"}],"source":"81 - Surfs Up.pdf","sourcePage":14},{"front":"longboards and shortboards","meaning":"長板和短板","examples":[{"en":"The question compares longboards and shortboards.","zh":"題目比較長板和短板。"},{"en":"Longboards and shortboards are two types of surfboards used for different surfing styles.","zh":"longboards and shortboards 指用於不同滑浪方式的兩種滑浪板。"},{"en":"A beginner may find longboards easier because they are more stable.","zh":"初學者可能覺得長板較容易，因為它們更穩定。"},{"en":"Shortboards can be easier to turn quickly, but they may be harder for beginners.","zh":"短板可能較容易快速轉向，但對初學者可能較難。"},{"en":"This phrase refers to two board types, not two separate sports.","zh":"這個短語指兩種板，而不是兩項完全不同的運動。"}],"source":"81 - Surfs Up.pdf","sourcePage":14},{"front":"often weigh more than","meaning":"經常重逾","examples":[{"en":"The option asks whether modern boards often weigh more than 100 pounds.","zh":"選項問現代滑浪板是否經常重逾一百磅。"},{"en":"Often weigh more than means frequently have a weight above a stated amount.","zh":"often weigh more than 指重量經常高於某個指定數量。"},{"en":"Large suitcases often weigh more than the airline limit if families pack too much.","zh":"如果家庭打包太多，大型行李經常重逾航空公司限制。"},{"en":"If equipment often weighs too much, it becomes harder to carry and use.","zh":"如果裝備經常太重，就更難攜帶和使用。"},{"en":"This phrase compares usual weight with a number.","zh":"這個短語把通常重量與數字比較。"}],"source":"81 - Surfs Up.pdf","sourcePage":14},{"front":"made out of solid wood","meaning":"由實木製成","examples":[{"en":"Early surfboards were made out of solid wood.","zh":"早期滑浪板由實木製成。"},{"en":"Made out of solid wood means built using real, dense wood as the material.","zh":"made out of solid wood 指使用真正密實木材製成。"},{"en":"A handmade table may be made out of solid wood and last for decades.","zh":"手工桌可能由實木製成，並可使用數十年。"},{"en":"Solid wood can be strong, but it often makes objects heavy.","zh":"實木可以很堅固，但通常令物件沉重。"},{"en":"This phrase identifies the material used to make something.","zh":"這個短語指出某物的製作材料。"}],"source":"81 - Surfs Up.pdf","sourcePage":15},{"front":"require surfers to perform","meaning":"要求滑浪者做出","examples":[{"en":"Some boards require surfers to perform difficult manoeuvres.","zh":"有些板要求滑浪者做出困難動作。"},{"en":"Require surfers to perform means make it necessary for surfers to do certain movements or skills.","zh":"require surfers to perform 指使滑浪者必須做出某些動作或技巧。"},{"en":"A narrow balance beam requires gymnasts to perform careful steps.","zh":"窄平衡木要求體操運動員做出小心步法。"},{"en":"Equipment design can affect what actions users must perform.","zh":"裝備設計可以影響使用者必須做甚麼動作。"},{"en":"This phrase links an object with the skill it demands.","zh":"這個短語把物件與它要求的技巧連繫起來。"}],"source":"81 - Surfs Up.pdf","sourcePage":15},{"front":"perform difficult walking manoeuvres","meaning":"做出高難度步行動作","examples":[{"en":"Longboarders perform difficult walking manoeuvres on the board.","zh":"長板滑浪者在板上做出高難度步行動作。"},{"en":"To perform difficult walking manoeuvres means to do challenging walking movements while balancing.","zh":"perform difficult walking manoeuvres 指在保持平衡時做出具挑戰性的步行動作。"},{"en":"A performer may practise difficult walking movements on a narrow stage before a show.","zh":"表演者可能在演出前於狹窄舞台上練習困難步法。"},{"en":"Such manoeuvres require coordination because the surface is moving or narrow.","zh":"這類動作需要協調，因為表面可能在移動或很狹窄。"},{"en":"This phrase describes skilled footwork.","zh":"這個短語描述有技巧的步法。"}],"source":"81 - Surfs Up.pdf","sourcePage":15},{"front":"lighter and more manoeuvrable","meaning":"較輕且較易操控","examples":[{"en":"Modern surfboards are lighter and more manoeuvrable.","zh":"現代滑浪板較輕且較易操控。"},{"en":"Lighter and more manoeuvrable means easier to carry, turn and control.","zh":"lighter and more manoeuvrable 指較易攜帶、轉向和控制。"},{"en":"A lighter suitcase with wheels is more manoeuvrable in a crowded station.","zh":"有輪子的較輕行李箱在擁擠車站中較易操控。"},{"en":"Lower weight often improves control because users can change direction faster.","zh":"較低重量常改善控制，因為使用者可以更快改變方向。"},{"en":"This phrase compares modern equipment with heavier older versions.","zh":"這個短語把現代裝備與較重的舊版本比較。"}],"source":"81 - Surfs Up.pdf","sourcePage":15},{"front":"the sport of surfing","meaning":"滑浪這項運動","examples":[{"en":"The sport of surfing is associated with the South Pacific.","zh":"滑浪這項運動與南太平洋相關。"},{"en":"The sport of surfing means surfing considered as an organised physical activity.","zh":"sport of surfing 指把滑浪視為一項有組織的身體活動。"},{"en":"The sport of swimming includes training, competitions and safety rules.","zh":"游泳這項運動包括訓練、比賽和安全規則。"},{"en":"Calling surfing a sport highlights skill, practice and physical effort.","zh":"把滑浪稱為運動，突出技巧、練習和體力。"},{"en":"This phrase is more formal than simply saying “surfing”.","zh":"這個短語比簡單說 surfing 較正式。"}],"source":"81 - Surfs Up.pdf","sourcePage":15},{"front":"was invented by","meaning":"由……發明","examples":[{"en":"The option asks whether surfing was invented by European explorers.","zh":"選項問滑浪是否由歐洲探險家發明。"},{"en":"Was invented by someone means was first created by that person or group.","zh":"was invented by someone 指最初由某人或某群體創造。"},{"en":"The telephone was invented by people working on communication technology.","zh":"電話由研究通訊科技的人發明。"},{"en":"Observing a practice is different from inventing it.","zh":"觀察某種做法與發明它是不同的。"},{"en":"This phrase focuses on origin and creation.","zh":"這個短語著重起源和創造。"}],"source":"81 - Surfs Up.pdf","sourcePage":15},{"front":"first practised in","meaning":"最早在……進行","examples":[{"en":"Surfing was first practised in the South Pacific.","zh":"滑浪最早在南太平洋進行。"},{"en":"First practised in a place means first done or developed there.","zh":"first practised in a place 指最早在某地進行或發展。"},{"en":"A traditional dance may have been first practised in one village before spreading elsewhere.","zh":"傳統舞蹈可能先在一條村落進行，然後傳到其他地方。"},{"en":"Knowing where an activity was first practised helps explain its cultural roots.","zh":"知道一項活動最早在哪裡進行，有助解釋其文化根源。"},{"en":"This phrase focuses on early use, not later popularity.","zh":"這個短語著重早期使用，而不是後來受歡迎程度。"}],"source":"81 - Surfs Up.pdf","sourcePage":15},{"front":"has become very popular","meaning":"已變得非常受歡迎","examples":[{"en":"Surfing has become very popular around the world.","zh":"滑浪已在世界各地變得非常受歡迎。"},{"en":"Has become very popular means many more people now like or practise it.","zh":"has become very popular 指現在有更多人喜歡或練習它。"},{"en":"Online learning has become very popular because students can study from home.","zh":"網上學習已變得非常受歡迎，因為學生可以在家學習。"},{"en":"When an activity becomes popular, classes, clubs and shops often increase.","zh":"當活動變得受歡迎，課程、俱樂部和商店通常會增加。"},{"en":"This phrase describes a change in public interest.","zh":"這個短語描述公眾興趣的變化。"}],"source":"81 - Surfs Up.pdf","sourcePage":15},{"front":"windy coastal areas","meaning":"多風的沿岸地區","examples":[{"en":"Surfing can be popular in windy coastal areas.","zh":"滑浪可以在多風的沿岸地區受歡迎。"},{"en":"Windy coastal areas are seaside places where wind is common or strong.","zh":"windy coastal areas 指常有風或風力強的海邊地區。"},{"en":"A windy coastal town may attract people who enjoy surfing, sailing or kiteboarding.","zh":"多風沿海小鎮可能吸引喜歡滑浪、帆船或風箏滑浪的人。"},{"en":"Wind can help create waves, but it can also make conditions more difficult.","zh":"風可以幫助形成海浪，但也可以令環境更困難。"},{"en":"This phrase describes a type of seaside environment.","zh":"這個短語描述一種海邊環境。"}],"source":"81 - Surfs Up.pdf","sourcePage":15},{"front":"fashionable west coast","meaning":"時尚的西岸","examples":[{"en":"The option refers to a fashionable west coast.","zh":"選項提到時尚的西岸。"},{"en":"A fashionable west coast is a stylish coastal area on the western side of a country or region.","zh":"fashionable west coast 指某國家或地區西面的時尚海岸區。"},{"en":"A fashionable coast may attract visitors with beaches, cafés and expensive shops.","zh":"時尚海岸可能以海灘、咖啡店和高級商店吸引訪客。"},{"en":"Fashionable locations can shape how a sport is imagined by outsiders.","zh":"時尚地點可以塑造外人如何想像一項運動。"},{"en":"This phrase combines geography with style.","zh":"這個短語結合地理和風格。"}],"source":"81 - Surfs Up.pdf","sourcePage":15},{"front":"all around the world","meaning":"世界各地","examples":[{"en":"Surfing is now popular all around the world.","zh":"滑浪現在在世界各地受歡迎。"},{"en":"All around the world means in many countries and regions globally.","zh":"all around the world 指在全球許多國家和地區。"},{"en":"English songs are listened to all around the world.","zh":"英文歌曲在世界各地被聆聽。"},{"en":"When something spreads worldwide, people adapt it to local conditions.","zh":"當某事傳遍世界，人們會把它適應本地情況。"},{"en":"This phrase emphasises global reach.","zh":"這個短語強調全球範圍。"}],"source":"81 - Surfs Up.pdf","sourcePage":16},{"front":"novice surfer","meaning":"初學滑浪者","examples":[{"en":"A novice surfer should learn about the risks first.","zh":"初學滑浪者應先了解風險。"},{"en":"A novice surfer is someone who is new to surfing and has little experience.","zh":"novice surfer 指剛開始滑浪、經驗很少的人。"},{"en":"A novice driver needs simple roads before driving in heavy traffic.","zh":"新手司機在繁忙交通中駕駛前，需要先練簡單道路。"},{"en":"Novices need guidance because they may not recognise danger quickly.","zh":"新手需要指導，因為他們未必能快速識別危險。"},{"en":"This phrase refers to a beginner.","zh":"這個短語指初學者。"}],"source":"81 - Surfs Up.pdf","sourcePage":16},{"front":"takes to the water","meaning":"下水","examples":[{"en":"A novice surfer should understand the dangers before taking to the water.","zh":"初學滑浪者下水前應了解危險。"},{"en":"Takes to the water means enters the water to begin an activity.","zh":"takes to the water 指進入水中開始活動。"},{"en":"Swimmers take to the water after the lifeguard says conditions are safe.","zh":"救生員表示情況安全後，泳客才下水。"},{"en":"Before taking to the water, people should check weather, waves and safety rules.","zh":"下水前，人們應檢查天氣、海浪和安全規則。"},{"en":"This phrase describes starting a water activity.","zh":"這個短語描述開始水上活動。"}],"source":"81 - Surfs Up.pdf","sourcePage":16},{"front":"check the latest weather report","meaning":"查看最新天氣報告","examples":[{"en":"Beginners may check the latest weather report before entering the sea.","zh":"初學者下海前可能查看最新天氣報告。"},{"en":"To check the latest weather report means to look at the most recent forecast or weather warning.","zh":"check the latest weather report 指查看最新天氣預報或天氣警告。"},{"en":"Hikers should check the latest weather report before walking in the mountains.","zh":"遠足者上山前應查看最新天氣報告。"},{"en":"Weather reports help people avoid storms, strong winds and unsafe conditions.","zh":"天氣報告幫助人避開風暴、強風和不安全情況。"},{"en":"This phrase describes a safety step before outdoor activity.","zh":"這個短語描述戶外活動前的安全步驟。"}],"source":"81 - Surfs Up.pdf","sourcePage":16},{"front":"avoid big waves","meaning":"避開大浪","examples":[{"en":"Novice surfers are often advised to avoid big waves.","zh":"初學滑浪者常被建議避開大浪。"},{"en":"To avoid big waves means to stay away from large or powerful waves.","zh":"avoid big waves 指遠離大型或強力海浪。"},{"en":"Beginner swimmers should avoid deep water until they are confident.","zh":"初學游泳者在有信心前應避開深水。"},{"en":"Avoiding difficult conditions helps learners build skill safely.","zh":"避開困難情況幫助學習者安全建立技能。"},{"en":"This phrase gives protective advice for beginners.","zh":"這個短語給初學者保護性建議。"}],"source":"81 - Surfs Up.pdf","sourcePage":16},{"front":"have good buoyancy","meaning":"有良好浮力","examples":[{"en":"A surfboard can help a surfer have good buoyancy.","zh":"滑浪板可以幫助滑浪者有良好浮力。"},{"en":"To have good buoyancy means to float well in water.","zh":"have good buoyancy 指在水中能良好浮起。"},{"en":"A life jacket helps children have good buoyancy during swimming lessons.","zh":"救生衣幫助孩子在游泳課中有良好浮力。"},{"en":"Good buoyancy can reduce effort and help people stay calm in water.","zh":"良好浮力可以減少力氣消耗，並幫助人在水中保持冷靜。"},{"en":"This phrase describes floating ability.","zh":"這個短語描述浮起能力。"}],"source":"81 - Surfs Up.pdf","sourcePage":16},{"front":"be aware of the risks involved","meaning":"意識到當中的風險","examples":[{"en":"A novice surfer should be aware of the risks involved.","zh":"初學滑浪者應意識到當中的風險。"},{"en":"To be aware of the risks involved means to understand the possible dangers in an activity.","zh":"be aware of the risks involved 指理解某活動中的可能危險。"},{"en":"A cyclist should be aware of the risks involved in riding at night.","zh":"騎單車者應意識到夜間騎行的風險。"},{"en":"Risk awareness helps people prepare instead of panicking later.","zh":"風險意識幫助人預先準備，而不是之後恐慌。"},{"en":"This phrase stresses informed caution.","zh":"這個短語強調有知識的謹慎。"}],"source":"81 - Surfs Up.pdf","sourcePage":16},{"front":"stay buoyant","meaning":"保持浮起","examples":[{"en":"A surfboard can help a surfer stay buoyant.","zh":"滑浪板可以幫助滑浪者保持浮起。"},{"en":"To stay buoyant means to continue floating instead of sinking.","zh":"stay buoyant 指持續浮在水面，而不是下沉。"},{"en":"A swimmer holding a float can stay buoyant while resting.","zh":"泳客拿着浮板休息時，可以保持浮起。"},{"en":"Staying buoyant saves energy and can help someone wait for rescue.","zh":"保持浮起可以節省體力，並幫助人等待救援。"},{"en":"This phrase describes remaining afloat in water.","zh":"這個短語描述在水中保持漂浮。"}],"source":"81 - Surfs Up.pdf","sourcePage":16},{"front":"get in the way of","meaning":"妨礙；阻礙","examples":[{"en":"A surfboard can get in the way of safety in some cases.","zh":"在某些情況下，滑浪板可以妨礙安全。"},{"en":"To get in the way of something means to block or interfere with it.","zh":"get in the way of something 指阻擋或干擾某事。"},{"en":"A chair in a narrow hallway can get in the way of people leaving quickly.","zh":"狹窄走廊中的椅子可能妨礙人們快速離開。"},{"en":"Equipment that helps normally can get in the way during an emergency.","zh":"平時有幫助的裝備在緊急情況下可能成為阻礙。"},{"en":"This phrase describes something becoming an obstacle.","zh":"這個短語描述某物變成障礙。"}],"source":"81 - Surfs Up.pdf","sourcePage":16},{"front":"in some cases","meaning":"在某些情況下","examples":[{"en":"In some cases, a surfboard can become dangerous.","zh":"在某些情況下，滑浪板可能變得危險。"},{"en":"In some cases means in certain situations but not always.","zh":"in some cases 指在某些情況中，但不是永遠如此。"},{"en":"In some cases, online lessons work better than face-to-face lessons.","zh":"在某些情況下，網上課堂比面授課堂更有效。"},{"en":"This phrase limits a statement so it does not sound universal.","zh":"這個短語限制說法，使它不會聽起來像普遍真理。"},{"en":"It is useful when exceptions or special situations matter.","zh":"當例外或特殊情況重要時，這個短語很有用。"}],"source":"81 - Surfs Up.pdf","sourcePage":16},{"front":"dangerous sea life","meaning":"危險海洋生物","examples":[{"en":"Surfers may face dangerous sea life such as sharks or jellyfish.","zh":"滑浪者可能面對鯊魚或水母等危險海洋生物。"},{"en":"Dangerous sea life means marine animals that can injure or threaten people.","zh":"dangerous sea life 指可能傷害或威脅人的海洋動物。"},{"en":"Beach signs may warn visitors about dangerous sea life after jellyfish are seen.","zh":"看見水母後，海灘告示可能提醒訪客有危險海洋生物。"},{"en":"Knowing local sea life helps swimmers avoid risky areas or seasons.","zh":"了解當地海洋生物幫助泳客避開高風險地區或季節。"},{"en":"This phrase refers to hazards from living creatures in the ocean.","zh":"這個短語指來自海洋生物的危害。"}],"source":"81 - Surfs Up.pdf","sourcePage":17},{"front":"prevent concussion or death","meaning":"防止腦震盪或死亡","examples":[{"en":"A surfboard cannot necessarily prevent concussion or death.","zh":"滑浪板不一定能防止腦震盪或死亡。"},{"en":"To prevent concussion or death means to stop head injury or fatal outcome from happening.","zh":"prevent concussion or death 指阻止頭部受傷或致命結果發生。"},{"en":"A helmet can help prevent concussion in cycling, but it cannot remove all danger.","zh":"頭盔可以幫助防止騎單車時腦震盪，但不能消除所有危險。"},{"en":"Safety equipment reduces risk, but serious accidents can still happen.","zh":"安全裝備降低風險，但嚴重意外仍可能發生。"},{"en":"This phrase describes protection against very serious outcomes.","zh":"這個短語描述防止非常嚴重後果的保護。"}],"source":"81 - Surfs Up.pdf","sourcePage":17},{"front":"unless","meaning":"除非","examples":[{"en":"Unless a surfer is rescued quickly, a bad collision can be fatal.","zh":"除非滑浪者迅速獲救，嚴重碰撞可能致命。"},{"en":"Unless means except if or if not.","zh":"unless 指除非，或如果不。"},{"en":"Unless a student checks the timetable, they may go to the wrong classroom.","zh":"除非學生檢查時間表，否則可能去錯課室。"},{"en":"This word introduces the condition needed to avoid a bad result.","zh":"這個詞引入避免壞結果所需的條件。"},{"en":"It is often used in warnings.","zh":"它常用於警告。"}],"source":"81 - Surfs Up.pdf","sourcePage":17},{"front":"pulled from the water quickly","meaning":"迅速從水中拉起","examples":[{"en":"A surfer with concussion must be pulled from the water quickly.","zh":"有腦震盪的滑浪者必須迅速從水中被拉起。"},{"en":"Pulled from the water quickly means removed from the water without delay.","zh":"pulled from the water quickly 指毫不延誤地從水中移出。"},{"en":"Lifeguards pulled a tired swimmer from the water quickly when he stopped moving well.","zh":"當疲倦泳客動作變差時，救生員迅速把他從水中拉起。"},{"en":"Quick removal from water can prevent drowning after injury.","zh":"受傷後迅速離開水面可以防止溺水。"},{"en":"This phrase describes urgent rescue action.","zh":"這個短語描述緊急救援行動。"}],"source":"81 - Surfs Up.pdf","sourcePage":17},{"front":"a bad collision","meaning":"嚴重碰撞","examples":[{"en":"A bad collision can be extremely dangerous for a surfer.","zh":"嚴重碰撞對滑浪者可能極之危險。"},{"en":"A bad collision is a serious crash or impact that can cause injury.","zh":"bad collision 指可能造成受傷的嚴重撞擊或碰撞。"},{"en":"A bad collision between two cyclists may require medical help.","zh":"兩名騎單車者之間的嚴重碰撞可能需要醫療協助。"},{"en":"In surfing, a bad collision can involve reefs, sandbanks or other surfers.","zh":"在滑浪中，嚴重碰撞可能涉及礁石、沙洲或其他滑浪者。"},{"en":"This phrase describes a harmful physical impact.","zh":"這個短語描述有害的身體撞擊。"}],"source":"81 - Surfs Up.pdf","sourcePage":17},{"front":"can prove fatal","meaning":"可能致命","examples":[{"en":"A serious collision can prove fatal.","zh":"嚴重碰撞可能致命。"},{"en":"Can prove fatal means can turn out to cause death.","zh":"can prove fatal 指結果可能造成死亡。"},{"en":"A small mistake on a dangerous road can prove fatal.","zh":"在危險道路上一個小錯誤可能致命。"},{"en":"This phrase is used when a risk may have the worst possible result.","zh":"當風險可能導致最嚴重結果時，會使用這個短語。"},{"en":"It is more formal than “can be deadly”.","zh":"它比 can be deadly 較正式。"}],"source":"81 - Surfs Up.pdf","sourcePage":17},{"front":"choose two letters","meaning":"選出兩個字母","examples":[{"en":"Students choose two letters from the list of options.","zh":"學生從選項列表中選出兩個字母。"},{"en":"Choose two letters means select exactly two answer choices marked by letters.","zh":"choose two letters 指準確選出兩個以字母標示的答案。"},{"en":"If the question says choose two letters, students should not choose three.","zh":"如果題目說選出兩個字母，學生不應選三個。"},{"en":"Careful attention to the number of answers prevents format mistakes.","zh":"仔細注意答案數量可以防止格式錯誤。"},{"en":"This phrase is a test instruction.","zh":"這個短語是測驗指示。"}],"source":"81 - Surfs Up.pdf","sourcePage":17},{"front":"hazards that surfers face","meaning":"滑浪者面對的危險","examples":[{"en":"The question asks about hazards that surfers face.","zh":"題目問滑浪者面對的危險。"},{"en":"Hazards that surfers face are dangers or risks connected with surfing.","zh":"hazards that surfers face 指與滑浪相關的危險或風險。"},{"en":"Surfers face hazards such as strong waves, reefs and sudden weather changes.","zh":"滑浪者面對強浪、礁石和突然天氣變化等危險。"},{"en":"Knowing hazards helps beginners decide when and where to surf safely.","zh":"了解危險幫助初學者決定何時何地安全滑浪。"},{"en":"This phrase focuses on risks experienced by surfers.","zh":"這個短語著重滑浪者經歷的風險。"}],"source":"81 - Surfs Up.pdf","sourcePage":17},{"front":"being held underwater by","meaning":"被……困在水下","examples":[{"en":"A surfer can be held underwater by a tangled leash.","zh":"滑浪者可以被纏住的繫繩困在水下。"},{"en":"Being held underwater by something means being trapped below the water surface because of it.","zh":"being held underwater by something 指因某物而被困在水面以下。"},{"en":"A swimmer can be held underwater by a rope caught on a rock.","zh":"游泳者可能被卡在石頭上的繩索困在水下。"},{"en":"This situation is dangerous because it prevents breathing and can cause panic.","zh":"這種情況很危險，因為它阻止呼吸並可能造成恐慌。"},{"en":"This phrase describes a direct drowning risk.","zh":"這個短語描述直接溺水風險。"}],"source":"81 - Surfs Up.pdf","sourcePage":17},{"front":"the potential for","meaning":"……的可能性","examples":[{"en":"Surfers face the potential for shark attacks.","zh":"滑浪者面對鯊魚襲擊的可能性。"},{"en":"The potential for something means the possibility that it may happen.","zh":"potential for something 指某事可能發生。"},{"en":"A wet floor creates the potential for slips and injuries.","zh":"濕地板會造成滑倒和受傷的可能性。"},{"en":"A risk may be small but still worth noting if the result is serious.","zh":"即使風險很小，如果後果嚴重，仍值得注意。"},{"en":"This phrase focuses on possibility, not certainty.","zh":"這個短語著重可能性，而不是確定性。"}],"source":"81 - Surfs Up.pdf","sourcePage":17},{"front":"shark attacks","meaning":"鯊魚襲擊","examples":[{"en":"Shark attacks are rare but possible.","zh":"鯊魚襲擊很罕見，但有可能發生。"},{"en":"Shark attacks are incidents in which sharks injure or threaten people.","zh":"shark attacks 指鯊魚傷害或威脅人的事件。"},{"en":"Beaches may close temporarily if shark attacks or sightings occur nearby.","zh":"如果附近發生鯊魚襲擊或有人目擊鯊魚，海灘可能暫時關閉。"},{"en":"Fear of shark attacks can be stronger than the actual statistical risk.","zh":"人們對鯊魚襲擊的恐懼可能強於實際統計風險。"},{"en":"This phrase refers to a dramatic but uncommon sea danger.","zh":"這個短語指戲劇化但不常見的海上危險。"}],"source":"81 - Surfs Up.pdf","sourcePage":18},{"front":"frequent encounters with","meaning":"經常遇到……","examples":[{"en":"The option mentions frequent encounters with jellyfish.","zh":"選項提到經常遇到水母。"},{"en":"Frequent encounters with something means meeting or coming across it often.","zh":"frequent encounters with something 指經常遇見或碰到某物。"},{"en":"Hikers may have frequent encounters with mosquitoes in wet forests.","zh":"遠足者在潮濕森林中可能經常遇到蚊子。"},{"en":"Frequent encounters with a hazard can increase the chance of injury.","zh":"經常遇到危險物可以增加受傷機會。"},{"en":"This phrase describes repeated contact with something.","zh":"這個短語描述與某物反覆接觸。"}],"source":"81 - Surfs Up.pdf","sourcePage":18},{"front":"demanding water conditions","meaning":"要求高的水況","examples":[{"en":"Demanding water conditions can make surfing dangerous.","zh":"要求高的水況可以令滑浪變得危險。"},{"en":"Demanding water conditions are water conditions that require strength, skill and attention.","zh":"demanding water conditions 指需要力量、技巧和注意力的水況。"},{"en":"Strong currents and large waves create demanding water conditions for swimmers.","zh":"強水流和大浪會為泳客造成要求高的水況。"},{"en":"Beginners may become exhausted quickly in demanding conditions.","zh":"初學者在要求高的情況下可能很快疲累。"},{"en":"This phrase describes difficult conditions, not simply good waves.","zh":"這個短語描述困難水況，而不只是好浪。"}],"source":"81 - Surfs Up.pdf","sourcePage":18},{"front":"hazardous rescue attempts","meaning":"危險的救援嘗試","examples":[{"en":"The option refers to hazardous rescue attempts.","zh":"選項指危險的救援嘗試。"},{"en":"Hazardous rescue attempts are efforts to save someone that are themselves dangerous.","zh":"hazardous rescue attempts 指本身也有危險的救援行動。"},{"en":"A rescue in rough seas can be hazardous for both the swimmer and the lifeguard.","zh":"在洶湧海面救援對泳客和救生員都可能很危險。"},{"en":"Dangerous rescue attempts require training, equipment and quick judgement.","zh":"危險救援嘗試需要訓練、裝備和快速判斷。"},{"en":"This phrase focuses on risks during rescue, not the original accident alone.","zh":"這個短語著重救援期間的風險，而不只是原本事故。"}],"source":"81 - Surfs Up.pdf","sourcePage":18},{"front":"true about surfing","meaning":"關於滑浪屬實","examples":[{"en":"The question asks which statements are true about surfing.","zh":"題目問哪些陳述關於滑浪屬實。"},{"en":"True about surfing means correct according to the passage or facts about surfing.","zh":"true about surfing 指根據文章或滑浪事實而言正確。"},{"en":"In a reading test, students must choose what is true about the text, not what they already believe.","zh":"在閱讀測驗中，學生必須選擇關於文本屬實的內容，而不是自己已有的想法。"},{"en":"A statement can sound sensible but still not be true about the passage.","zh":"陳述可以聽起來合理，但仍未必對文章屬實。"},{"en":"This phrase is used to check accuracy.","zh":"這個短語用來檢查準確性。"}],"source":"81 - Surfs Up.pdf","sourcePage":18},{"front":"a rewarding career","meaning":"有回報的事業","examples":[{"en":"The option describes surfing as a rewarding career.","zh":"選項把滑浪描述為有回報的事業。"},{"en":"A rewarding career is a job or profession that gives satisfaction, growth or meaningful benefits.","zh":"rewarding career 指帶來滿足、成長或有意義好處的工作或職業。"},{"en":"Teaching can be a rewarding career when students improve and gain confidence.","zh":"當學生進步並建立信心時，教學可以是有回報的事業。"},{"en":"A career may be rewarding emotionally even if it is difficult.","zh":"即使職業困難，它在情感上仍可能有回報。"},{"en":"This phrase refers to work, not simply a hobby.","zh":"這個短語指工作，而不只是嗜好。"}],"source":"81 - Surfs Up.pdf","sourcePage":18},{"front":"see yourself improve","meaning":"看見自己進步","examples":[{"en":"It can be rewarding to see yourself improve.","zh":"看見自己進步可以很有滿足感。"},{"en":"To see yourself improve means to notice that your own skill or performance is getting better.","zh":"see yourself improve 指注意到自己的技能或表現變得更好。"},{"en":"A language learner may feel encouraged when they see themselves improve in speaking.","zh":"語言學習者看見自己口語進步時，可能感到受鼓勵。"},{"en":"Visible progress makes difficult practice feel worthwhile.","zh":"看得見的進步令困難練習感覺值得。"},{"en":"This phrase focuses on personal progress.","zh":"這個短語著重個人進步。"}],"source":"81 - Surfs Up.pdf","sourcePage":18},{"front":"an adrenaline rush","meaning":"腎上腺素飆升；刺激感","examples":[{"en":"Surfing can give people an adrenaline rush.","zh":"滑浪可以令人有腎上腺素飆升的刺激感。"},{"en":"An adrenaline rush is a sudden feeling of excitement and energy caused by fear, speed or challenge.","zh":"adrenaline rush 指由恐懼、速度或挑戰引起的突然興奮和能量感。"},{"en":"Some people feel an adrenaline rush before performing on stage.","zh":"有些人在上台表演前會感到腎上腺素飆升。"},{"en":"Risky sports can create an adrenaline rush because the body prepares for action.","zh":"高風險運動可以產生刺激感，因為身體準備行動。"},{"en":"This phrase describes a strong physical feeling of excitement.","zh":"這個短語描述強烈的身體興奮感。"}],"source":"81 - Surfs Up.pdf","sourcePage":18},{"front":"expensive to start","meaning":"起步費用昂貴","examples":[{"en":"The option asks whether surfing is expensive to start.","zh":"選項問滑浪起步費用是否昂貴。"},{"en":"Expensive to start means requiring a lot of money at the beginning.","zh":"expensive to start 指開始時需要很多金錢。"},{"en":"Golf can be expensive to start if lessons, clubs and course fees are all included.","zh":"如果包括課堂、球桿和場地費，高爾夫球起步費用可能昂貴。"},{"en":"If an activity is not expensive to start, more beginners may try it.","zh":"如果活動起步費用不昂貴，更多初學者可能願意嘗試。"},{"en":"This phrase focuses on initial cost.","zh":"這個短語著重初始成本。"}],"source":"81 - Surfs Up.pdf","sourcePage":18},{"front":"dangerous for swimmers around you","meaning":"對你附近的泳客有危險","examples":[{"en":"The option asks whether surfing is dangerous for swimmers around you.","zh":"選項問滑浪是否對你附近的泳客有危險。"},{"en":"Dangerous for swimmers around you means creating risk for nearby people in the water.","zh":"dangerous for swimmers around you 指對附近水中的人造成風險。"},{"en":"A fast board can be dangerous for swimmers around you if you cannot control it.","zh":"如果你不能控制快速移動的板，它可能對附近泳客有危險。"},{"en":"Awareness of others helps prevent collisions in shared water spaces.","zh":"留意他人有助避免共享水域中的碰撞。"},{"en":"This phrase focuses on danger to nearby swimmers, not only to the surfer.","zh":"這個短語著重對附近泳客的危險，而不只是對滑浪者。"}],"source":"81 - Surfs Up.pdf","sourcePage":18},{"front":"complete the table below","meaning":"完成下表","examples":[{"en":"Students complete the table below using information from the passage.","zh":"學生使用文章中的資料完成下表。"},{"en":"To complete the table below means to fill missing information in the table under the instruction.","zh":"complete the table below 指填寫指示下方表格中的缺失資料。"},{"en":"Students should check headings before completing a table in a reading test.","zh":"學生在閱讀測驗中完成表格前，應檢查標題。"},{"en":"A table answer must fit both the meaning and the required word limit.","zh":"表格答案必須同時符合意思和字數限制。"},{"en":"This phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"81 - Surfs Up.pdf","sourcePage":19},{"front":"no more than two words and/or a number","meaning":"不多於兩個字及／或一個數字","examples":[{"en":"Students write no more than two words and/or a number.","zh":"學生寫下不多於兩個字及／或一個數字。"},{"en":"No more than two words and/or a number means the answer may contain up to two words, plus a number if needed.","zh":"no more than two words and/or a number 指答案可包含最多兩個字，如有需要可加一個數字。"},{"en":"If the limit allows two words and a number, “five-day courses £100” may fit only if the task format allows it.","zh":"如果限制容許兩個字和一個數字，“five-day courses £100” 只有在題目格式容許時才可能合適。"},{"en":"Students lose marks if they exceed the word limit, even when the idea is correct.","zh":"即使意思正確，超過字數限制也會失分。"},{"en":"This phrase gives a strict answer format rule.","zh":"這個短語給出嚴格答案格式規則。"}],"source":"81 - Surfs Up.pdf","sourcePage":19},{"front":"feature","meaning":"特徵；項目","examples":[{"en":"The table lists each feature and its details.","zh":"表格列出每個特徵及其詳情。"},{"en":"A feature is an important characteristic, part or item being described.","zh":"feature 指正在描述的重要特徵、部分或項目。"},{"en":"In a phone review, battery life and camera quality are features.","zh":"在手機評論中，電池壽命和相機質素都是特徵。"},{"en":"Listing features helps readers compare different items clearly.","zh":"列出特徵幫助讀者清楚比較不同項目。"},{"en":"This word often appears in tables and descriptions.","zh":"這個詞常出現在表格和描述中。"}],"source":"81 - Surfs Up.pdf","sourcePage":19},{"front":"details","meaning":"詳情","examples":[{"en":"The details explain each feature in the table.","zh":"詳情解釋表格中的每個特徵。"},{"en":"Details are specific pieces of information about something.","zh":"details 指關於某事的具體資訊。"},{"en":"Course details may include dates, price, location and teacher name.","zh":"課程詳情可能包括日期、價格、地點和老師姓名。"},{"en":"Details help turn a general idea into useful information.","zh":"詳情幫助把一般想法變成有用資訊。"},{"en":"This word refers to the exact information needed for understanding or action.","zh":"這個詞指理解或行動所需的準確資訊。"}],"source":"81 - Surfs Up.pdf","sourcePage":19},{"front":"subdivisions of surfing","meaning":"滑浪的分支","examples":[{"en":"The subdivisions of surfing are longboarding and shortboarding.","zh":"滑浪的分支是長板滑浪和短板滑浪。"},{"en":"Subdivisions of surfing are the main categories into which surfing is divided.","zh":"subdivisions of surfing 指滑浪所分成的主要類別。"},{"en":"A textbook may explain the subdivisions of a subject before giving details.","zh":"教科書可能先解釋某學科的分支，再提供細節。"},{"en":"Dividing a sport into categories helps learners understand different equipment and skills.","zh":"把運動分成類別幫助學習者理解不同裝備和技巧。"},{"en":"This phrase refers to the main types within surfing.","zh":"這個短語指滑浪內部的主要種類。"}],"source":"81 - Surfs Up.pdf","sourcePage":19},{"front":"originated in","meaning":"起源於","examples":[{"en":"The table asks where surfing originated.","zh":"表格問滑浪起源於哪裡。"},{"en":"Originated in means began or first developed in a particular place or period.","zh":"originated in 指在某個地點或時期開始或最早發展。"},{"en":"A local festival may have originated in a farming tradition centuries ago.","zh":"本地節日可能起源於數百年前的農業傳統。"},{"en":"Knowing where something originated helps explain its cultural meaning.","zh":"知道某事起源於哪裡，有助解釋其文化意義。"},{"en":"This phrase focuses on beginnings.","zh":"這個短語著重起源。"}],"source":"81 - Surfs Up.pdf","sourcePage":19},{"front":"common dangers include","meaning":"常見危險包括","examples":[{"en":"Common dangers include drowning, collisions and marine animals.","zh":"常見危險包括溺水、碰撞和海洋動物。"},{"en":"Common dangers include means the usual risks are these examples.","zh":"common dangers include 指一般風險包括這些例子。"},{"en":"Common dangers in a kitchen include burns, cuts and slippery floors.","zh":"廚房中的常見危險包括燙傷、割傷和濕滑地板。"},{"en":"Listing common dangers helps beginners prepare before starting an activity.","zh":"列出常見危險幫助初學者在開始活動前做好準備。"},{"en":"This phrase introduces typical risks.","zh":"這個短語引入典型風險。"}],"source":"81 - Surfs Up.pdf","sourcePage":19},{"front":"local sea life","meaning":"當地海洋生物","examples":[{"en":"Surfers may be attacked by local sea life.","zh":"滑浪者可能被當地海洋生物襲擊。"},{"en":"Local sea life means the marine animals living in a particular coastal area.","zh":"local sea life 指生活在某特定沿海地區的海洋動物。"},{"en":"A beach guide may warn visitors about local sea life such as jellyfish or sea urchins.","zh":"海灘指南可能提醒訪客注意水母或海膽等當地海洋生物。"},{"en":"Understanding local sea life helps people avoid bites, stings and unsafe areas.","zh":"了解當地海洋生物幫助人避免咬傷、刺傷和不安全地區。"},{"en":"This phrase refers to nearby ocean creatures.","zh":"這個短語指附近海洋中的生物。"}],"source":"81 - Surfs Up.pdf","sourcePage":19},{"front":"starting cost","meaning":"起始費用","examples":[{"en":"The table asks for the starting cost of five-day courses.","zh":"表格問五天課程的起始費用。"},{"en":"Starting cost is the lowest or initial amount of money needed to begin something.","zh":"starting cost 指開始某事所需的最低或初始金額。"},{"en":"The starting cost of learning guitar may include a basic instrument and first lessons.","zh":"學結他起始費用可能包括基本樂器和第一批課堂。"},{"en":"Low starting costs can make a hobby more accessible.","zh":"低起始費用可以令嗜好更容易參與。"},{"en":"This phrase focuses on the cost at the beginning.","zh":"這個短語著重開始時的費用。"}],"source":"81 - Surfs Up.pdf","sourcePage":19},{"front":"include accommodation","meaning":"包括住宿","examples":[{"en":"All-inclusive camps include accommodation.","zh":"全包營包括住宿。"},{"en":"Include accommodation means provide or cover a place to stay.","zh":"include accommodation 指提供或涵蓋住宿地點。"},{"en":"A language camp may include accommodation so students can live near the classroom.","zh":"語言營可能包括住宿，讓學生住在課室附近。"},{"en":"Including accommodation makes planning easier for people travelling from far away.","zh":"包括住宿令遠道而來的人較容易規劃。"},{"en":"This phrase tells learners that lodging is part of the package.","zh":"這個短語告訴學習者住宿是套裝的一部分。"}],"source":"81 - Surfs Up.pdf","sourcePage":19},{"front":"meals, lessons and equipment","meaning":"膳食、課堂和裝備","examples":[{"en":"Surf camps may include meals, lessons and equipment.","zh":"滑浪營可能包括膳食、課堂和裝備。"},{"en":"Meals, lessons and equipment are food, teaching sessions and the tools needed for the activity.","zh":"meals, lessons and equipment 指食物、教學課節和活動所需工具。"},{"en":"A sports camp that includes meals, lessons and equipment is easier for beginners to join.","zh":"包括膳食、課堂和裝備的運動營，對初學者較易參加。"},{"en":"Including these items reduces extra spending and planning.","zh":"包括這些項目可以減少額外支出和規劃。"},{"en":"This phrase lists common parts of an all-inclusive course.","zh":"這個短語列出全包課程的常見部分。"}],"source":"81 - Surfs Up.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 82":[{"front":"uncovering the truth about","meaning":"揭開……的真相","examples":[{"en":"The passage focuses on uncovering the truth about Germany’s autobahns.","zh":"文章集中於揭開德國高速公路的真相。"},{"en":"Uncovering the truth about something means finding the real facts behind a story, belief, or rumour.","zh":"uncovering the truth about something 指找出某個故事、信念或傳聞背後的真實事實。"},{"en":"A journalist may spend months uncovering the truth about unsafe food sold in schools.","zh":"記者可能花數月揭開學校售賣不安全食物的真相。"},{"en":"When many people believe a myth, uncovering the truth can change how they understand the issue.","zh":"當許多人相信迷思時，揭開真相可以改變他們對問題的理解。"},{"en":"The phrase suggests careful investigation, not quick guessing.","zh":"這個短語暗示仔細調查，而不是快速猜測。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":1},{"front":"Germany’s autobahns","meaning":"德國高速公路","examples":[{"en":"Germany’s autobahns are famous for their unusual speed rules.","zh":"德國高速公路因其不尋常的速度規則而聞名。"},{"en":"Germany’s autobahns are the country’s federal motorway system.","zh":"Germany’s autobahns 指德國的聯邦高速公路系統。"},{"en":"Many tourists have heard of Germany’s autobahns because some sections have no general speed limit.","zh":"許多遊客聽過德國高速公路，因為部分路段沒有一般速度限制。"},{"en":"The autobahns attract attention because people associate them with very fast driving.","zh":"德國高速公路吸引注意，因為人們把它與高速駕駛聯繫起來。"},{"en":"The phrase refers to German motorways, not ordinary city roads.","zh":"這個短語指德國的高速公路，而不是普通城市道路。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":1},{"front":"officially called","meaning":"官方稱為","examples":[{"en":"The autobahns are officially called the Bundesautobahnen.","zh":"德國高速公路官方稱為 Bundesautobahnen。"},{"en":"Officially called means known by a formal or legal name.","zh":"officially called 指以正式或法律名稱被稱呼。"},{"en":"A school may be officially called “Central College,” even if students use a short nickname.","zh":"一所學校官方可能稱為 “Central College”，即使學生使用簡稱。"},{"en":"Official names matter in laws, signs, maps, and public documents.","zh":"官方名稱在法律、標誌、地圖和公共文件中很重要。"},{"en":"The phrase contrasts formal naming with everyday usage.","zh":"這個短語把正式命名與日常用法作對比。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":1},{"front":"federal expressways","meaning":"聯邦高速公路","examples":[{"en":"The term Bundesautobahnen means federal expressways.","zh":"Bundesautobahnen 這個詞意思是聯邦高速公路。"},{"en":"Federal expressways are major roads managed at national or federal level for fast travel.","zh":"federal expressways 指由國家或聯邦層面管理、用於快速交通的主要道路。"},{"en":"A federal expressway usually connects cities and regions more directly than local roads.","zh":"聯邦高速公路通常比本地道路更直接地連接城市和地區。"},{"en":"Because federal expressways carry long-distance traffic, safety rules and maintenance are important.","zh":"由於聯邦高速公路承載長途交通，安全規則和維修很重要。"},{"en":"The phrase describes a national motorway system.","zh":"這個短語描述全國性的高速公路系統。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":1},{"front":"be known more commonly as","meaning":"較常被稱為","examples":[{"en":"They are known more commonly as the autobahns.","zh":"它們較常被稱為 autobahns。"},{"en":"To be known more commonly as something means most people use that name instead of the formal one.","zh":"be known more commonly as something 指大多數人使用該名稱，而不是正式名稱。"},{"en":"A university may be officially named after a founder but be known more commonly as its short name.","zh":"大學官方可能以創辦人命名，但較常被稱為其簡稱。"},{"en":"Common names spread because they are easier to remember and say.","zh":"常用名稱會流傳，因為它們較容易記住和說出。"},{"en":"The phrase contrasts popular usage with official terminology.","zh":"這個短語把普遍用法與官方術語作對比。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":1},{"front":"impressive system of motorways","meaning":"令人印象深刻的高速公路系統","examples":[{"en":"Germany has an impressive system of motorways.","zh":"德國有一套令人印象深刻的高速公路系統。"},{"en":"An impressive system of motorways is a large, well-designed network of high-speed roads.","zh":"impressive system of motorways 指大型、設計良好的高速道路網絡。"},{"en":"A country with many connected motorways can move people and goods efficiently.","zh":"擁有許多相連高速公路的國家，可以有效運送人員和貨物。"},{"en":"Good motorway systems can reduce travel time, but they also require careful safety planning.","zh":"良好高速公路系統可以減少旅程時間，但也需要仔細安全規劃。"},{"en":"The phrase praises the scale or quality of the road network.","zh":"這個短語讚揚道路網絡的規模或質素。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":1},{"front":"nothing extraordinary about","meaning":"沒有甚麼特別之處","examples":[{"en":"There is nothing extraordinary about the autobahns as roads.","zh":"作為道路而言，德國高速公路沒有甚麼特別之處。"},{"en":"Nothing extraordinary about something means it is not especially unusual or amazing in that respect.","zh":"nothing extraordinary about something 指某方面並不特別不尋常或驚人。"},{"en":"There is nothing extraordinary about a classroom simply because it has desks and chairs.","zh":"一間課室只因有桌椅，並沒有甚麼特別之處。"},{"en":"If something becomes famous for one feature, other parts of it may be ordinary.","zh":"如果某事物因一個特色而聞名，其其他部分可能很普通。"},{"en":"The phrase reduces exaggeration and brings attention back to facts.","zh":"這個短語降低誇張，讓注意力回到事實。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":1},{"front":"fine feats of engineering","meaning":"出色的工程成就","examples":[{"en":"The autobahns may be fine feats of engineering.","zh":"德國高速公路可能是出色的工程成就。"},{"en":"Fine feats of engineering are impressive achievements in design, construction, and technical skill.","zh":"fine feats of engineering 指在設計、建造和技術能力上的令人印象深刻成就。"},{"en":"A bridge that crosses a wide river safely can be a fine feat of engineering.","zh":"一座安全跨越寬闊河流的橋，可以是出色的工程成就。"},{"en":"Strong engineering allows roads to carry heavy traffic and survive difficult weather.","zh":"強大的工程能力讓道路承載繁忙交通並抵受惡劣天氣。"},{"en":"The phrase praises technical achievement.","zh":"這個短語讚揚技術成就。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":1},{"front":"though they may be","meaning":"儘管它們可能是……","examples":[{"en":"Fine feats of engineering though they may be, the roads are famous for another reason.","zh":"儘管它們可能是出色的工程成就，這些道路卻因另一原因聞名。"},{"en":"Though they may be means although they are perhaps or indeed that thing.","zh":"though they may be 指雖然它們或許確實是某種東西。"},{"en":"Useful though phones may be, they can distract students during lessons.","zh":"儘管電話可能有用，它們在課堂上也可能令學生分心。"},{"en":"The phrase admits one point before shifting attention to a more important point.","zh":"這個短語先承認一點，再把注意力轉向更重要的一點。"},{"en":"It is a formal inverted structure used for contrast.","zh":"這是一個較正式的倒裝對比結構。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":1},{"front":"become so well known","meaning":"變得如此有名","examples":[{"en":"The term autobahn has become so well known outside Germany.","zh":"autobahn 這個詞在德國以外變得如此有名。"},{"en":"To become so well known means to become famous or widely recognised.","zh":"become so well known 指變得出名或被廣泛認識。"},{"en":"A small restaurant can become well known if many customers share good reviews online.","zh":"如果許多顧客在網上分享好評，小餐廳可以變得有名。"},{"en":"When a word becomes famous internationally, people may know it even without understanding the full context.","zh":"當一個詞在國際間聞名，人們即使不了解完整背景也可能知道它。"},{"en":"The phrase stresses widespread recognition.","zh":"這個短語強調廣泛認知。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":1},{"front":"the simple answer is that","meaning":"簡單答案是","examples":[{"en":"The simple answer is that people are curious about the speed rules.","zh":"簡單答案是人們對速度規則感到好奇。"},{"en":"The simple answer is that introduces the basic or most direct explanation.","zh":"the simple answer is that 用來引入基本或最直接的解釋。"},{"en":"The simple answer is that students improve when they practise regularly.","zh":"簡單答案是學生定期練習時會進步。"},{"en":"Writers use this phrase when a complicated question has a straightforward first explanation.","zh":"當複雜問題有直接的初步解釋，作者會使用這個短語。"},{"en":"The phrase signals clarity before more details appear.","zh":"這個短語在更多細節出現前先表示清晰答案。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":1},{"front":"outside of Germany","meaning":"在德國以外","examples":[{"en":"People living outside of Germany are curious about the autobahns.","zh":"住在德國以外的人對德國高速公路感到好奇。"},{"en":"Outside of Germany means in places other than Germany.","zh":"outside of Germany 指在德國以外的地方。"},{"en":"A German product may become famous outside of Germany if tourists recommend it.","zh":"如果遊客推薦，德國產品可能在德國以外變得有名。"},{"en":"When people outside a country hear only one unusual fact, they may build myths around it.","zh":"當國外的人只聽到一個不尋常事實，他們可能圍繞它建立迷思。"},{"en":"The phrase contrasts foreign perception with local reality.","zh":"這個短語把外國看法與本地現實作對比。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":2},{"front":"have one’s curiosity tickled","meaning":"勾起某人的好奇心","examples":[{"en":"Drivers have had their curiosity tickled by Germany’s speed rules.","zh":"德國的速度規則勾起了駕駛者的好奇心。"},{"en":"To have one’s curiosity tickled means to become interested or intrigued by something unusual.","zh":"have one’s curiosity tickled 指被某件不尋常的事引起興趣或好奇。"},{"en":"A strange book title may tickle a student’s curiosity and make her read the first page.","zh":"奇怪的書名可能勾起學生好奇心，令她讀第一頁。"},{"en":"Unusual rules can tickle people’s curiosity because they want to know why they exist.","zh":"不尋常規則可以勾起人們的好奇心，因為他們想知道其存在原因。"},{"en":"The phrase suggests light excitement and interest.","zh":"這個短語暗示輕微興奮和興趣。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":2},{"front":"more than a little","meaning":"相當；不只一點點","examples":[{"en":"The autobahns have more than a little tickled people’s curiosity.","zh":"德國高速公路相當勾起了人們的好奇心。"},{"en":"More than a little means quite a lot or to a noticeable degree.","zh":"more than a little 指相當多或達到明顯程度。"},{"en":"A surprise exam may make students more than a little nervous.","zh":"突然測驗可能令學生相當緊張。"},{"en":"If a road has no speed limit, it can make drivers more than a little interested.","zh":"如果道路沒有限速，它可以令駕駛者相當感興趣。"},{"en":"The phrase is understated and often means “rather much.”","zh":"這個短語語氣含蓄，常等於「頗為」。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":2},{"front":"on account of the fact that","meaning":"由於","examples":[{"en":"People are curious on account of the fact that the autobahns are unique.","zh":"人們好奇，是由於德國高速公路十分獨特。"},{"en":"On account of the fact that means because.","zh":"on account of the fact that 指因為。"},{"en":"The outdoor lesson was cancelled on account of the fact that heavy rain was expected.","zh":"戶外課因預計有大雨而取消。"},{"en":"This phrase is formal and wordier than simply saying because.","zh":"這個短語較正式，比 simply saying because 更長。"},{"en":"It introduces the reason behind a situation.","zh":"它引入某情況背後的原因。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":2},{"front":"in one specific way","meaning":"在某一特定方面","examples":[{"en":"Germany’s motorways are unique in one specific way.","zh":"德國高速公路在某一特定方面十分獨特。"},{"en":"In one specific way means in one particular respect, not in every respect.","zh":"in one specific way 指在某一具體方面，而不是所有方面。"},{"en":"A school may be ordinary in most ways but unusual in one specific way: every student learns music.","zh":"一所學校在大多數方面普通，但在某一特定方面不尋常：每名學生都學音樂。"},{"en":"This phrase helps narrow attention to the feature that matters.","zh":"這個短語幫助把注意力收窄到重要特色。"},{"en":"It prevents readers from assuming the whole system is unique.","zh":"它防止讀者以為整個系統都獨特。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":2},{"front":"the longest system in the world","meaning":"世界上最長的系統","examples":[{"en":"The autobahns are not the longest system in the world.","zh":"德國高速公路不是世界上最長的系統。"},{"en":"The longest system in the world means the network with the greatest total length globally.","zh":"longest system in the world 指全球總長度最大的網絡。"},{"en":"A railway may be famous without being the longest system in the world.","zh":"一條鐵路可能很有名，即使它不是世界上最長的系統。"},{"en":"If a system is not the longest, its fame may come from another feature.","zh":"如果一個系統不是最長，其名聲可能來自另一個特色。"},{"en":"The phrase focuses on size measured by length.","zh":"這個短語重點是以長度量度的規模。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":2},{"front":"this plaudit going to","meaning":"這項榮譽屬於","examples":[{"en":"The longest-motorway plaudit goes to America’s Interstate Highway System.","zh":"最長高速公路這項榮譽屬於美國州際公路系統。"},{"en":"This plaudit going to something means that praise or honour belongs to that thing.","zh":"this plaudit going to something 指該讚譽或榮譽屬於某事物。"},{"en":"In a class project, the plaudit for best design may go to the quietest student.","zh":"在班級項目中，最佳設計這項榮譽可能屬於最安靜的學生。"},{"en":"The phrase is often used when correcting who truly deserves recognition.","zh":"這個短語常用於糾正真正值得認可的是誰。"},{"en":"It means the honour is awarded elsewhere, not to the first subject mentioned.","zh":"它表示榮譽頒給別處，而不是最先提到的對象。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":2},{"front":"Interstate Highway System","meaning":"州際公路系統","examples":[{"en":"The Interstate Highway System is longer than Germany’s autobahns.","zh":"州際公路系統比德國高速公路更長。"},{"en":"The Interstate Highway System is the major network of highways connecting states in the United States.","zh":"Interstate Highway System 指連接美國各州的主要公路網絡。"},{"en":"Long-distance drivers use the Interstate Highway System to travel between American cities.","zh":"長途駕駛者使用州際公路系統在美國城市之間旅行。"},{"en":"Because it covers a huge country, the system is longer than many national motorway networks.","zh":"由於它覆蓋一個巨大國家，這個系統比許多國家高速公路網絡更長。"},{"en":"The phrase is a proper name for a US road system.","zh":"這個短語是美國道路系統的專有名稱。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":2},{"front":"rank second or third","meaning":"排名第二或第三","examples":[{"en":"Germany’s motorway system does not rank second or third in length.","zh":"德國高速公路系統在長度上並非排名第二或第三。"},{"en":"To rank second or third means to be placed in the second or third position in a comparison.","zh":"rank second or third 指在比較中位列第二或第三。"},{"en":"A student may rank second in class even if she misses first place by one mark.","zh":"學生即使只差一分，也可能在班中排名第二。"},{"en":"Rankings can show scale, but they do not always explain why something is famous.","zh":"排名可以顯示規模，但不一定解釋某事物為何有名。"},{"en":"The phrase describes position in an ordered list.","zh":"這個短語描述有序列表中的位置。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":2},{"front":"respectively","meaning":"分別地","examples":[{"en":"China and India rank second and third, respectively.","zh":"中國和印度分別排名第二和第三。"},{"en":"Respectively means in the same order as the things just mentioned.","zh":"respectively 指按照剛才提到事物的相同次序。"},{"en":"Anna and Ben scored 90 and 85 respectively, meaning Anna scored 90 and Ben scored 85.","zh":"Anna 和 Ben 分別得90和85分，即 Anna 得90分，Ben 得85分。"},{"en":"The word prevents confusion when two or more items are matched with two or more details.","zh":"當兩個或更多項目要配對兩個或更多細節時，這個詞能避免混亂。"},{"en":"It is useful in formal comparisons.","zh":"它常用於正式比較。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":2},{"front":"come a healthy fourth","meaning":"穩居第四","examples":[{"en":"Germany comes a healthy fourth in motorway length.","zh":"德國在高速公路長度方面穩居第四。"},{"en":"To come a healthy fourth means to rank fourth by a comfortable or respectable margin.","zh":"come a healthy fourth 指以穩定或值得尊重的差距排名第四。"},{"en":"A school team may come a healthy fourth in a city competition and still feel proud.","zh":"學校隊伍在全市比賽中穩居第四，仍可以感到自豪。"},{"en":"The phrase suggests the position is strong even though it is not first.","zh":"這個短語暗示即使不是第一，位置仍很強。"},{"en":"It gives a positive tone to a fourth-place ranking.","zh":"它給第四名帶來正面語氣。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":2},{"front":"in the length stakes","meaning":"在長度排名方面","examples":[{"en":"Germany comes fourth in the length stakes.","zh":"德國在長度排名方面位列第四。"},{"en":"In the length stakes means in the comparison or competition about length.","zh":"in the length stakes 指在關於長度的比較或競爭中。"},{"en":"In the price stakes, the small shop cannot beat the large supermarket.","zh":"在價格比較方面，小店不能擊敗大型超市。"},{"en":"This informal phrase frames comparison as if it were a race or contest.","zh":"這個非正式短語把比較說得像比賽一樣。"},{"en":"It focuses on one criterion only: length.","zh":"它只集中於一個標準：長度。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":3},{"front":"neither here nor there","meaning":"並不重要；無關緊要","examples":[{"en":"The length of the autobahns is really neither here nor there.","zh":"德國高速公路的長度其實並不重要。"},{"en":"Neither here nor there means not important or not relevant to the main point.","zh":"neither here nor there 指不重要或與主要問題無關。"},{"en":"In a writing test, beautiful handwriting is neither here nor there if the answer misses the question.","zh":"在寫作考試中，如果答案離題，字體漂亮也無關緊要。"},{"en":"If people are interested in speed rules, the road system’s length is not the key issue.","zh":"如果人們感興趣的是速度規則，道路系統長度就不是核心問題。"},{"en":"The phrase dismisses a detail as beside the point.","zh":"這個短語把某細節排除為離題內容。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":3},{"front":"what fascinates us about","meaning":"令我們着迷的是","examples":[{"en":"What fascinates us about the autobahns is their speed policy.","zh":"令我們對德國高速公路着迷的是其速度政策。"},{"en":"What fascinates us about something means the feature that strongly attracts our interest.","zh":"what fascinates us about something 指某事物中強烈吸引我們興趣的特點。"},{"en":"What fascinates students about space is often the idea of planets beyond Earth.","zh":"令學生對太空着迷的，常是地球以外行星的概念。"},{"en":"A topic becomes memorable when one unusual feature fascinates people.","zh":"當一個不尋常特色令人着迷，主題就會令人難忘。"},{"en":"The phrase introduces the real source of interest.","zh":"這個短語引入真正興趣來源。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":3},{"front":"have nothing to do with","meaning":"與……無關","examples":[{"en":"The fascination has nothing to do with technical features.","zh":"這種吸引力與技術特色無關。"},{"en":"To have nothing to do with something means to be unrelated to it.","zh":"have nothing to do with something 指與某事沒有關係。"},{"en":"A student’s low mark may have nothing to do with intelligence and everything to do with lack of sleep.","zh":"學生低分可能與智力無關，而完全與睡眠不足有關。"},{"en":"The phrase separates the real cause from a wrong explanation.","zh":"這個短語把真正原因與錯誤解釋分開。"},{"en":"It is useful when correcting misunderstanding.","zh":"它適合用來糾正誤解。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":3},{"front":"technical or design features","meaning":"技術或設計特色","examples":[{"en":"The autobahns are not famous mainly for their technical or design features.","zh":"德國高速公路並非主要因其技術或設計特色而聞名。"},{"en":"Technical or design features are engineering details, structures, layouts, or built characteristics.","zh":"technical or design features 指工程細節、結構、布局或建造特徵。"},{"en":"A bridge’s technical features may include its materials, supports, and safety systems.","zh":"一座橋的技術特色可能包括材料、支撐和安全系統。"},{"en":"A road can be well designed without becoming famous for design alone.","zh":"道路可以設計良好，但不一定單靠設計而聞名。"},{"en":"The phrase refers to how something is built or engineered.","zh":"這個短語指某物如何被建造或工程設計。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":3},{"front":"have a lot to do with","meaning":"與……有很大關係","examples":[{"en":"The fascination has a lot to do with how fast you can drive.","zh":"這種吸引力與你可以開得多快有很大關係。"},{"en":"To have a lot to do with something means to be strongly connected to it.","zh":"have a lot to do with something 指與某事有強烈關連。"},{"en":"A student’s confidence may have a lot to do with how teachers respond to mistakes.","zh":"學生信心可能與老師如何回應錯誤有很大關係。"},{"en":"If people talk about the autobahn, their interest often has a lot to do with speed.","zh":"如果人們談論德國高速公路，他們的興趣通常與速度有很大關係。"},{"en":"The phrase identifies an important factor.","zh":"這個短語指出重要因素。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":3},{"front":"how fast you can go","meaning":"你可以開得多快","examples":[{"en":"The autobahns are famous because of how fast you can go on them.","zh":"德國高速公路因你可以在上面開得多快而聞名。"},{"en":"How fast you can go means the speed you are allowed or able to travel at.","zh":"how fast you can go 指你被允許或能夠以多高速度前進。"},{"en":"On a school running track, how fast you can go depends on fitness and safety rules.","zh":"在學校跑道上，你可以跑得多快取決於體能和安全規則。"},{"en":"On roads, speed depends not only on the vehicle but also on law, traffic, and conditions.","zh":"在道路上，速度不只取決於車輛，也取決於法律、交通和環境。"},{"en":"The phrase focuses on possible speed.","zh":"這個短語重點是可能速度。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":3},{"front":"stretches of motorway","meaning":"高速公路路段","examples":[{"en":"The autobahns include stretches of motorway without a general speed limit.","zh":"德國高速公路包括沒有一般速度限制的路段。"},{"en":"Stretches of motorway are particular sections or lengths of high-speed road.","zh":"stretches of motorway 指高速公路中的特定段落或長度。"},{"en":"A stretch of motorway may be closed if workers are repairing the surface.","zh":"如果工人正在維修路面，某高速公路路段可能封閉。"},{"en":"Different stretches can have different rules, traffic levels, and risks.","zh":"不同路段可以有不同規則、交通流量和風險。"},{"en":"The phrase refers to parts of a motorway, not the whole system.","zh":"這個短語指高速公路的一部分，而不是整個系統。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":3},{"front":"provided that","meaning":"只要；假如","examples":[{"en":"You may drive at any speed, provided that your car is not towing a trailer.","zh":"只要你的車沒有拖着拖架，你可以以任何速度行駛。"},{"en":"Provided that means only if a condition is met.","zh":"provided that 指只有在某條件成立時。"},{"en":"Students may leave early provided that their parents have signed the form.","zh":"只要家長已簽署表格，學生可以提早離開。"},{"en":"A rule can allow freedom while still setting clear conditions.","zh":"規則可以給予自由，同時仍設定清楚條件。"},{"en":"The phrase introduces a condition that must be true.","zh":"這個短語引入必須成立的條件。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":3},{"front":"tow a trailer","meaning":"拖着拖架","examples":[{"en":"A car towing a trailer is subject to stricter speed limits.","zh":"拖着拖架的汽車受更嚴格速度限制約束。"},{"en":"To tow a trailer means to pull a small vehicle or container behind another vehicle.","zh":"tow a trailer 指在另一輛車後面拉着小型車廂或拖架。"},{"en":"A family may tow a trailer when carrying camping equipment for a holiday.","zh":"家庭去露營旅行時，可能拖着拖架載設備。"},{"en":"Vehicles towing trailers are harder to control, so speed rules may be stricter.","zh":"拖着拖架的車較難控制，因此速度規則可能更嚴格。"},{"en":"The phrase describes pulling an attached trailer while driving.","zh":"這個短語描述駕駛時拉着連接的拖架。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":3},{"front":"at any speed you like","meaning":"以你喜歡的任何速度","examples":[{"en":"Some drivers can travel at any speed they like on certain autobahn stretches.","zh":"一些駕駛者可以在某些德國高速公路路段以自己喜歡的任何速度行駛。"},{"en":"At any speed you like means at whatever speed you choose, without a fixed upper limit.","zh":"at any speed you like 指以你選擇的任何速度行駛，沒有固定最高限制。"},{"en":"On private land, a test driver may drive at any speed allowed by the safety team.","zh":"在私人土地上，測試司機可能按安全團隊允許，以任何速度駕駛。"},{"en":"Freedom to choose speed can attract drivers who enjoy powerful cars.","zh":"自由選擇速度可以吸引喜歡高性能車的人。"},{"en":"The phrase sounds free, but real conditions may still limit what is safe.","zh":"這個短語聽起來自由，但真實環境仍可能限制安全速度。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":3},{"front":"an attractive proposition","meaning":"吸引人的提議；誘人選擇","examples":[{"en":"Driving without a speed limit is an attractive proposition for some drivers.","zh":"沒有速度限制地駕駛，對一些司機而言是吸引人的選擇。"},{"en":"An attractive proposition is an idea or option that seems appealing or worth considering.","zh":"attractive proposition 指看起來吸引或值得考慮的想法或選擇。"},{"en":"A job with flexible hours can be an attractive proposition for parents.","zh":"有彈性工作時間的工作，對父母而言可以是誘人選擇。"},{"en":"If an option promises freedom or excitement, people may find it attractive even when it has risks.","zh":"如果某選項承諾自由或刺激，即使有風險，人們也可能覺得吸引。"},{"en":"The phrase focuses on appeal, not guaranteed wisdom.","zh":"這個短語重點是吸引力，而不是保證明智。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":4},{"front":"boy-racers","meaning":"飛車黨；愛飆車的人","examples":[{"en":"The idea appeals to boy-racers who enjoy driving fast.","zh":"這個想法吸引喜歡高速駕駛的飛車黨。"},{"en":"Boy-racers are usually young or reckless drivers who enjoy speeding and showing off.","zh":"boy-racers 通常指年輕或魯莽、喜歡超速和炫耀的駕駛者。"},{"en":"Residents may complain if boy-racers drive noisily through their neighbourhood at night.","zh":"如果飛車黨晚上在社區中嘈吵高速駕駛，居民可能投訴。"},{"en":"When speed becomes a form of showing off, road safety can be put at risk.","zh":"當速度變成炫耀方式，道路安全就可能受威脅。"},{"en":"The phrase is informal and often critical.","zh":"這個短語較非正式，常帶批評意味。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":4},{"front":"salivate at the prospect of","meaning":"對……的前景垂涎三尺","examples":[{"en":"Some drivers would salivate at the prospect of driving as fast as they wanted.","zh":"一些司機會對隨心所欲高速駕駛的前景垂涎三尺。"},{"en":"To salivate at the prospect of something means to feel extremely eager for it.","zh":"salivate at the prospect of something 指對某事極度渴望。"},{"en":"Students may salivate at the prospect of a long holiday after exams.","zh":"考試後，學生可能對長假期的前景垂涎三尺。"},{"en":"The phrase is humorous and exaggerates desire as if someone is hungry.","zh":"這個短語帶幽默和誇張意味，把渴望說得像飢餓一樣。"},{"en":"It suggests strong excitement, not calm interest.","zh":"它暗示強烈興奮，而不是冷靜興趣。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":4},{"front":"at the prospect of","meaning":"面對……的可能性","examples":[{"en":"Many drivers are excited at the prospect of unrestricted speed.","zh":"許多司機面對無限制速度的可能性感到興奮。"},{"en":"At the prospect of something means when thinking about the possibility of it happening.","zh":"at the prospect of something 指想到某事可能發生時。"},{"en":"A student may feel nervous at the prospect of speaking in front of the whole class.","zh":"學生想到要在全班面前演講，可能感到緊張。"},{"en":"Future possibilities can create excitement, fear, or curiosity before anything happens.","zh":"未來可能性可以在事情發生前帶來興奮、恐懼或好奇。"},{"en":"The phrase introduces a reaction to a possible future event.","zh":"這個短語引入對未來可能事件的反應。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":4},{"front":"as fast as they wanted","meaning":"以他們想要的速度","examples":[{"en":"Some drivers dream of driving as fast as they wanted.","zh":"一些司機夢想以他們想要的速度駕駛。"},{"en":"As fast as they wanted means at whatever high speed they chose.","zh":"as fast as they wanted 指以他們選擇的任何高速行駛。"},{"en":"Children may wish they could run as fast as they wanted in a playground, but teachers set rules for safety.","zh":"孩子可能希望在操場上以自己想要的速度奔跑，但老師會為安全設規則。"},{"en":"Freedom to go as fast as one wants can become dangerous when roads are crowded.","zh":"當道路擠迫，想開多快就開多快的自由可能變得危險。"},{"en":"The phrase emphasises unrestricted personal choice.","zh":"這個短語強調不受限制的個人選擇。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":4},{"front":"on that rather scary point","meaning":"就這個頗可怕的一點而言","examples":[{"en":"On that rather scary point, we should ask an obvious question.","zh":"就這個頗可怕的一點而言，我們應該問一個明顯問題。"},{"en":"On that rather scary point means regarding that somewhat frightening issue just mentioned.","zh":"on that rather scary point 指關於剛提到那個有點令人害怕的問題。"},{"en":"On that worrying point, a school should ask whether its safety rules are enough.","zh":"就這個令人擔心的一點而言，學校應問自己的安全規則是否足夠。"},{"en":"Writers use this phrase to pause and examine a risk more directly.","zh":"作者使用這個短語來暫停並更直接檢視風險。"},{"en":"The phrase signals concern before a question or explanation.","zh":"這個短語在問題或解釋前顯示憂慮。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":4},{"front":"what on earth","meaning":"究竟；到底","examples":[{"en":"What on earth were the Germans thinking when they allowed this?","zh":"德國人容許這樣做時，究竟在想甚麼？"},{"en":"What on earth is used to show surprise, confusion, or disbelief in a question.","zh":"what on earth 用於問題中，表示驚訝、困惑或難以置信。"},{"en":"What on earth were you doing outside without a coat in the storm?","zh":"暴風中你不穿外套在外面，到底在做甚麼？"},{"en":"The phrase makes a question sound stronger and more emotional.","zh":"這個短語令問題聽起來更強烈、更有情緒。"},{"en":"It often suggests the speaker thinks the situation seems unreasonable.","zh":"它通常暗示說話者覺得情況似乎不合理。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":4},{"front":"have no speed limit whatsoever","meaning":"完全沒有速度限制","examples":[{"en":"Some autobahn stretches have no speed limit whatsoever for certain vehicles.","zh":"某些德國高速公路路段對某些車輛完全沒有速度限制。"},{"en":"To have no speed limit whatsoever means to have absolutely no upper legal speed limit.","zh":"have no speed limit whatsoever 指完全沒有法律上的最高速度限制。"},{"en":"A private test track may have no speed limit whatsoever during controlled vehicle trials.","zh":"私人測試跑道在受控車輛測試期間可能完全沒有速度限制。"},{"en":"If a road has no limit at all, drivers still need judgment because traffic and weather matter.","zh":"如果道路完全沒有限速，司機仍需要判斷力，因為交通和天氣很重要。"},{"en":"The word whatsoever strongly emphasises total absence.","zh":"whatsoever 這個詞強烈強調完全沒有。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":4},{"front":"a recipe for disaster","meaning":"災難的配方；很可能導致災難","examples":[{"en":"Having no speed limit may sound like a recipe for disaster.","zh":"沒有速度限制聽起來可能很容易導致災難。"},{"en":"A recipe for disaster is a situation likely to cause serious problems.","zh":"recipe for disaster 指很可能造成嚴重問題的情況。"},{"en":"Letting tired students handle sharp tools without supervision is a recipe for disaster.","zh":"讓疲倦學生在無監督下使用鋒利工具，很可能導致災難。"},{"en":"When high speed, poor weather, and crowded roads combine, accidents become more likely.","zh":"當高速、惡劣天氣和擠迫道路結合，意外更可能發生。"},{"en":"The phrase warns that conditions may lead to failure or danger.","zh":"這個短語警告某些條件可能導致失敗或危險。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":4},{"front":"to clarify","meaning":"澄清一下","examples":[{"en":"To clarify, there is a recommended speed limit on German motorways.","zh":"澄清一下，德國高速公路有建議速度限制。"},{"en":"To clarify means to make something clearer or correct a possible misunderstanding.","zh":"to clarify 指使某事更清楚或糾正可能誤解。"},{"en":"To clarify, the homework is due on Friday morning, not Friday night.","zh":"澄清一下，功課是星期五早上交，不是星期五晚上。"},{"en":"Writers use this phrase when readers may have formed the wrong impression.","zh":"當讀者可能形成錯誤印象時，作者會使用這個短語。"},{"en":"It introduces a clearer explanation or correction.","zh":"它引入更清楚的解釋或修正。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":4},{"front":"recommended speed limit","meaning":"建議速度限制","examples":[{"en":"There is a recommended speed limit of 130 km/h on German motorways.","zh":"德國高速公路有每小時130公里的建議速度限制。"},{"en":"A recommended speed limit is a suggested safe speed, not always a strict legal maximum.","zh":"recommended speed limit 指建議的安全速度，不一定是嚴格法律最高速度。"},{"en":"A school driveway may have a recommended speed limit to protect children walking nearby.","zh":"學校車道可能有建議速度限制，以保護附近步行的孩子。"},{"en":"Drivers may be encouraged to follow a recommended limit even when it is not legally binding.","zh":"即使沒有法律約束，司機也可能被鼓勵遵守建議限制。"},{"en":"The phrase differs from a hard legal speed limit.","zh":"這個短語不同於硬性法律速度限制。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":4},{"front":"hard limit","meaning":"硬性限制","examples":[{"en":"A hard limit is imposed on some vehicles.","zh":"一些車輛被施加硬性限制。"},{"en":"A hard limit is a strict maximum that cannot legally be exceeded.","zh":"hard limit 指法律上不能超過的嚴格最高限制。"},{"en":"A library may set a hard limit of five borrowed books per student.","zh":"圖書館可能為每名學生設定最多借五本書的硬性限制。"},{"en":"If a driver breaks a hard speed limit, police can issue a fine.","zh":"如果司機違反硬性速度限制，警方可以發出罰款。"},{"en":"The phrase contrasts strict rules with recommendations.","zh":"這個短語把嚴格規則與建議作對比。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":5},{"front":"be imposed on","meaning":"被施加於","examples":[{"en":"A hard speed limit is imposed on certain vehicles.","zh":"硬性速度限制被施加於某些車輛。"},{"en":"To be imposed on something means to be officially applied or enforced on it.","zh":"be imposed on something 指某規則被正式套用或執行於某物。"},{"en":"Extra homework may be imposed on a class after repeated missed assignments.","zh":"如果班上反覆欠交功課，額外功課可能被施加於全班。"},{"en":"When limits are imposed on heavy vehicles, the aim may be safety and control.","zh":"當限制被施加於重型車輛，目的可能是安全和控制。"},{"en":"The phrase often suggests authority applying a rule.","zh":"這個短語常暗示權威套用規則。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":5},{"front":"buses carrying standing passengers","meaning":"載有站立乘客的巴士","examples":[{"en":"Buses carrying standing passengers cannot go faster than 60 km/h.","zh":"載有站立乘客的巴士不能快過每小時60公里。"},{"en":"Buses carrying standing passengers are buses with people standing instead of seated.","zh":"buses carrying standing passengers 指有乘客站着而不是坐着的巴士。"},{"en":"City buses often carry standing passengers during busy hours.","zh":"城市巴士在繁忙時間常載有站立乘客。"},{"en":"Standing passengers are more vulnerable if a bus brakes suddenly, so speed may be limited.","zh":"如果巴士突然煞車，站立乘客較容易受傷，因此速度可能受限。"},{"en":"The phrase describes a bus condition that affects safety rules.","zh":"這個短語描述會影響安全規則的巴士狀況。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":5},{"front":"motorbikes pulling trailers","meaning":"拖着拖架的電單車","examples":[{"en":"Motorbikes pulling trailers cannot exceed 60 km/h.","zh":"拖着拖架的電單車不能超過每小時60公里。"},{"en":"Motorbikes pulling trailers are motorcycles towing small attached trailers.","zh":"motorbikes pulling trailers 指拖着小型附加拖架的電單車。"},{"en":"A motorbike pulling a trailer may be less stable when turning or braking.","zh":"拖着拖架的電單車在轉彎或煞車時可能較不穩定。"},{"en":"Because trailers affect balance, these vehicles face lower speed limits.","zh":"由於拖架影響平衡，這些車輛面對較低速度限制。"},{"en":"The phrase describes a motorcycle with extra load behind it.","zh":"這個短語描述後方帶額外負載的電單車。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":5},{"front":"go faster than","meaning":"快過……行駛","examples":[{"en":"Some vehicles cannot go faster than 60 km/h.","zh":"一些車輛不能快過每小時60公里行駛。"},{"en":"To go faster than a speed means to travel above that speed.","zh":"go faster than a speed 指以高於某速度行駛。"},{"en":"In a school car park, drivers should not go faster than 10 km/h.","zh":"在學校停車場，司機不應快過每小時10公里。"},{"en":"Going faster than a safe limit increases stopping distance and danger.","zh":"快過安全限制行駛會增加煞停距離和危險。"},{"en":"The phrase is used for comparing actual speed with a limit.","zh":"這個短語用於比較實際速度和限制。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":5},{"front":"passenger cars","meaning":"私家車；乘用車","examples":[{"en":"Passenger cars with trailers are subject to speed limits.","zh":"拖着拖架的私家車受速度限制約束。"},{"en":"Passenger cars are ordinary cars designed mainly to carry people rather than goods.","zh":"passenger cars 指主要用來載人而不是載貨的普通汽車。"},{"en":"A family car used for commuting is a passenger car.","zh":"用於通勤的家庭車就是乘用車。"},{"en":"When passenger cars tow trailers, they may face stricter rules because handling changes.","zh":"當私家車拖着拖架，因操控改變，它們可能面對更嚴格規則。"},{"en":"The phrase contrasts normal cars with trucks, buses, or motorcycles.","zh":"這個短語把普通汽車與貨車、巴士或電單車作對比。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":5},{"front":"trucks with trailers","meaning":"拖着拖架的貨車","examples":[{"en":"Trucks with trailers are not allowed to exceed 80 km/h.","zh":"拖着拖架的貨車不准超過每小時80公里。"},{"en":"Trucks with trailers are heavy goods vehicles pulling attached trailers behind them.","zh":"trucks with trailers 指後方拖着附加拖架的重型貨運車輛。"},{"en":"A delivery company may use trucks with trailers to move large amounts of goods.","zh":"物流公司可能使用拖着拖架的貨車運送大量貨物。"},{"en":"Because heavy trailers need more distance to stop, speed limits are stricter.","zh":"由於重型拖架需要更長煞車距離，速度限制較嚴格。"},{"en":"The phrase describes larger freight vehicles with extra loads.","zh":"這個短語描述帶額外負載的大型貨運車輛。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":5},{"front":"weighing in excess of","meaning":"重量超過","examples":[{"en":"Vehicles weighing in excess of 3.5 tonnes are subject to an 80 km/h limit.","zh":"重量超過3.5噸的車輛受每小時80公里限制約束。"},{"en":"Weighing in excess of a number means weighing more than that amount.","zh":"weighing in excess of a number 指重量超過某數量。"},{"en":"A lift may not carry goods weighing in excess of 500 kilograms.","zh":"升降機可能不能運載重量超過500公斤的貨物。"},{"en":"Heavy vehicles create greater stopping distances, so weight can affect speed rules.","zh":"重型車輛需要更長煞車距離，因此重量可以影響速度規則。"},{"en":"The phrase is formal and common in regulations.","zh":"這個短語較正式，常見於規例。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":5},{"front":"in excess of","meaning":"超過","examples":[{"en":"Some vehicles weighing in excess of 3.5 tonnes cannot exceed 80 km/h.","zh":"一些重量超過3.5噸的車輛不能超過每小時80公里。"},{"en":"In excess of means more than a particular amount.","zh":"in excess of 指超過某特定數量。"},{"en":"A phone bill in excess of 1,000 dollars may surprise a family.","zh":"超過1,000元的電話費可能令家庭驚訝。"},{"en":"When a value is in excess of a limit, extra rules may apply.","zh":"當數值超過限制，可能適用額外規則。"},{"en":"The phrase is formal and often used with numbers.","zh":"這個短語較正式，常與數字連用。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":5},{"front":"not allowed to exceed","meaning":"不准超過","examples":[{"en":"Heavy vehicles are not allowed to exceed 80 km/h.","zh":"重型車輛不准超過每小時80公里。"},{"en":"Not allowed to exceed means legally or officially forbidden to go above a limit.","zh":"not allowed to exceed 指在法律或官方上禁止超過某限制。"},{"en":"Students are not allowed to exceed the word limit in a short-answer test.","zh":"學生在短答題中不准超過字數限制。"},{"en":"If drivers exceed a legal limit, they may face fines or penalties.","zh":"如果司機超過法律限制，他們可能面對罰款或處罰。"},{"en":"The phrase states a strict maximum.","zh":"這個短語說明嚴格最高限度。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":5},{"front":"rare exceptions include","meaning":"少數例外包括","examples":[{"en":"Rare exceptions include buses certified to travel at 100 km/h.","zh":"少數例外包括獲認證可行駛每小時100公里的巴士。"},{"en":"Rare exceptions include means only a few unusual cases are different from the general rule.","zh":"rare exceptions include 指只有少數不尋常情況不同於一般規則。"},{"en":"Most students must attend class; rare exceptions include serious illness or family emergencies.","zh":"大多數學生必須上課；少數例外包括嚴重疾病或家庭緊急情況。"},{"en":"Exceptions need clear approval so rules remain fair and safe.","zh":"例外需要清楚批准，規則才保持公平和安全。"},{"en":"The phrase introduces limited special cases.","zh":"這個短語引入有限的特殊個案。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":5},{"front":"be officially certified to","meaning":"獲官方認證可","examples":[{"en":"Some buses have been officially certified to travel at 100 km/h.","zh":"一些巴士獲官方認證可行駛每小時100公里。"},{"en":"To be officially certified to do something means to receive formal approval for it.","zh":"be officially certified to do something 指獲得正式批准去做某事。"},{"en":"A driver may be officially certified to operate a large bus after passing tests.","zh":"司機通過測試後，可能獲官方認證可駕駛大型巴士。"},{"en":"Certification shows that authorities have checked a requirement or standard.","zh":"認證顯示當局已查核某要求或標準。"},{"en":"The phrase refers to formal permission, not personal confidence.","zh":"這個短語指正式許可，而不是個人信心。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":6},{"front":"receive similar certification","meaning":"獲得類似認證","examples":[{"en":"Some passenger cars carrying trailers have received similar certification.","zh":"一些拖着拖架的乘用車已獲得類似認證。"},{"en":"To receive similar certification means to get the same kind of official approval.","zh":"receive similar certification 指取得同類正式認可。"},{"en":"A new training centre may receive similar certification after meeting the same safety rules.","zh":"新培訓中心在符合相同安全規則後，可能獲得類似認證。"},{"en":"Similar certification allows different groups to qualify under comparable standards.","zh":"類似認證讓不同群體按可比較標準取得資格。"},{"en":"The phrase links one approved case with another.","zh":"這個短語把一個獲認可個案與另一個連起來。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":6},{"front":"nonetheless","meaning":"儘管如此","examples":[{"en":"Nonetheless, many vehicles are not legally bound to the recommended limit.","zh":"儘管如此，許多車輛在法律上不受建議限制約束。"},{"en":"Nonetheless means however or despite what has just been said.","zh":"nonetheless 指然而或儘管剛才所說如此。"},{"en":"The homework was difficult; nonetheless, most students completed it on time.","zh":"功課很難；儘管如此，大多數學生準時完成。"},{"en":"Writers use nonetheless to show contrast after giving a limiting detail.","zh":"作者在提供限制性細節後，會用 nonetheless 表示對比。"},{"en":"The word introduces a point that still remains true.","zh":"這個詞引入仍然成立的一點。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":6},{"front":"the fact remains that","meaning":"事實仍然是","examples":[{"en":"The fact remains that many cars can travel faster than the recommended limit.","zh":"事實仍然是，許多汽車可以比建議限制開得更快。"},{"en":"The fact remains that means this point is still true despite other details.","zh":"the fact remains that 指儘管有其他細節，這一點仍然是真的。"},{"en":"The school has improved; the fact remains that some classrooms are still overcrowded.","zh":"學校已有改善；事實仍然是，一些課室仍然過度擠迫。"},{"en":"This phrase brings attention back to a stubborn or important fact.","zh":"這個短語把注意力帶回一個難以忽視的重要事實。"},{"en":"It often follows a concession or clarification.","zh":"它常跟在讓步或澄清之後。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":6},{"front":"adhere to","meaning":"遵守","examples":[{"en":"Drivers are encouraged to adhere to the recommended speed limit.","zh":"司機被鼓勵遵守建議速度限制。"},{"en":"To adhere to a rule means to follow it carefully.","zh":"adhere to a rule 指仔細遵守某規則。"},{"en":"Students should adhere to exam instructions if they want their answers marked correctly.","zh":"如果學生想答案被正確評分，就應遵守考試指示。"},{"en":"When people adhere to safety advice, accidents may become less likely.","zh":"當人們遵守安全建議，意外可能較不容易發生。"},{"en":"The phrase is formal and often used with rules, limits, or standards.","zh":"這個短語較正式，常與規則、限制或標準連用。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":6},{"front":"by no means","meaning":"絕不；完全不","examples":[{"en":"Many drivers are by no means legally bound to the recommended speed limit.","zh":"許多司機絕不在法律上受建議速度限制約束。"},{"en":"By no means means definitely not or not at all.","zh":"by no means 指絕對不是或完全不。"},{"en":"A small mistake is by no means proof that a student is lazy.","zh":"一個小錯誤絕不證明學生懶惰。"},{"en":"This phrase strongly rejects an idea that someone might assume.","zh":"這個短語強烈否定別人可能假設的想法。"},{"en":"It is more emphatic than simply saying not.","zh":"它比 simply saying not 更強調。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":6},{"front":"be bound to","meaning":"受……約束","examples":[{"en":"Some drivers are not bound to the recommended speed limit.","zh":"一些司機不受建議速度限制約束。"},{"en":"To be bound to a rule means to be required to follow it.","zh":"be bound to a rule 指被要求遵守某規則。"},{"en":"Employees are bound to follow safety procedures in a laboratory.","zh":"員工在實驗室中受安全程序約束。"},{"en":"If drivers are not legally bound to a limit, the limit may function only as advice.","zh":"如果司機在法律上不受某限制約束，該限制可能只是建議。"},{"en":"The phrase often refers to obligation.","zh":"這個短語常指義務。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":6},{"front":"in effect","meaning":"實際上","examples":[{"en":"In effect, some vehicles can travel as fast as they please.","zh":"實際上，一些車輛可以以司機喜歡的速度行駛。"},{"en":"In effect means in practical reality, even if the formal wording is different.","zh":"in effect 指在實際情況中，即使正式措辭不同。"},{"en":"A school rule may not ban phones directly, but in effect it stops students using them in class.","zh":"校規可能沒有直接禁止手機，但實際上阻止學生在課堂使用。"},{"en":"The phrase explains the real result of a policy or situation.","zh":"這個短語解釋政策或情況的真實結果。"},{"en":"It helps distinguish theory from practice.","zh":"它幫助區分理論與實際。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":6},{"front":"as fast as they please","meaning":"以他們喜歡的速度","examples":[{"en":"Some cars can travel as fast as they please on unrestricted stretches.","zh":"一些汽車可以在沒有限速路段以司機喜歡的速度行駛。"},{"en":"As fast as they please means at whatever speed the drivers choose.","zh":"as fast as they please 指以司機選擇的任何速度。"},{"en":"Children cannot run as fast as they please in a crowded corridor because it is unsafe.","zh":"孩子不能在擠迫走廊以自己喜歡的速度奔跑，因為那不安全。"},{"en":"Unlimited freedom can be attractive, but conditions still affect what is sensible.","zh":"無限制自由可以很吸引，但環境仍會影響甚麼才合理。"},{"en":"The phrase emphasises personal choice without a fixed limit.","zh":"這個短語強調沒有固定限制的個人選擇。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":6},{"front":"it is not uncommon to see","meaning":"經常可以看見；並不罕見","examples":[{"en":"It is not uncommon to see a car racing past at high speed.","zh":"經常可以看見汽車高速飛快駛過。"},{"en":"It is not uncommon to see means it happens fairly often.","zh":"it is not uncommon to see 指某事相當常見。"},{"en":"It is not uncommon to see students studying in cafés before exams.","zh":"考試前經常可以看見學生在咖啡店溫習。"},{"en":"Writers use this phrase when something may sound surprising but is actually normal enough.","zh":"當某事聽起來驚人但其實相當正常，作者會使用這個短語。"},{"en":"The phrase means “quite common,” not “rare.”","zh":"這個短語意思是「頗常見」，不是「罕見」。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":6},{"front":"race past","meaning":"飛快駛過","examples":[{"en":"A car may race past you on the autobahn.","zh":"汽車可能在德國高速公路上從你旁邊飛快駛過。"},{"en":"To race past means to move past someone or something very quickly.","zh":"race past 指非常快速地經過某人或某物。"},{"en":"A cyclist may race past pedestrians if the path is too narrow and unsafe.","zh":"如果路太窄且不安全，單車可能從行人旁飛快駛過。"},{"en":"When a vehicle races past, nearby drivers may feel shocked or unsettled.","zh":"當車輛飛快駛過，附近司機可能感到震驚或不安。"},{"en":"The phrase suggests speed and sudden movement.","zh":"這個短語暗示速度和突然移動。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":6},{"front":"travelling in excess of","meaning":"以超過……的速度行駛","examples":[{"en":"Cars may race past travelling in excess of 140 km/h.","zh":"汽車可能以超過每小時140公里的速度飛快駛過。"},{"en":"Travelling in excess of a speed means moving faster than that speed.","zh":"travelling in excess of a speed 指以高於某速度行駛。"},{"en":"A bus travelling in excess of the school-zone limit may receive a fine.","zh":"如果巴士以超過校區限制的速度行駛，可能收到罰款。"},{"en":"Higher speeds make stopping harder and increase the force of a crash.","zh":"更高速度令煞停更困難，並增加撞車力量。"},{"en":"The phrase is formal and used for speed comparisons.","zh":"這個短語較正式，用於速度比較。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":7},{"front":"in such circumstances","meaning":"在這種情況下","examples":[{"en":"In such circumstances, one might expect Germany to have a poor safety record.","zh":"在這種情況下，人們可能預期德國有較差安全紀錄。"},{"en":"In such circumstances means in a situation like the one just described.","zh":"in such circumstances 指在剛描述的那類情況中。"},{"en":"In such circumstances, a school may close early to protect students.","zh":"在這種情況下，學校可能提早關閉以保護學生。"},{"en":"When conditions seem risky, people may expect bad results.","zh":"當情況看似有風險，人們可能預期壞結果。"},{"en":"The phrase connects a situation with a likely reaction or conclusion.","zh":"這個短語把情況與可能反應或結論連起來。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":7},{"front":"it would not be surprising to learn that","meaning":"得知……也不足為奇","examples":[{"en":"It would not be surprising to learn that road safety was poor.","zh":"得知道路安全差也不足為奇。"},{"en":"It would not be surprising to learn that means the information would seem understandable or expected.","zh":"it would not be surprising to learn that 指某資訊會顯得可以理解或可預期。"},{"en":"It would not be surprising to learn that tired students make more careless mistakes.","zh":"得知疲倦學生犯更多粗心錯誤也不足為奇。"},{"en":"If roads allow high speeds, people may expect accident figures to be poor.","zh":"如果道路容許高速行駛，人們可能預期意外數字很差。"},{"en":"The phrase prepares the reader for a reasonable expectation.","zh":"這個短語為讀者準備一個合理預期。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":7},{"front":"an awful record on road safety","meaning":"糟糕的道路安全紀錄","examples":[{"en":"Germany does not have an awful record on road safety.","zh":"德國並沒有糟糕的道路安全紀錄。"},{"en":"An awful record on road safety means a very poor history of accidents or deaths on roads.","zh":"awful record on road safety 指道路意外或死亡方面非常差的歷史表現。"},{"en":"A city with many fatal crashes may have an awful road safety record.","zh":"有許多致命車禍的城市可能有糟糕的道路安全紀錄。"},{"en":"If safety records are not awful despite high speeds, people may ask why the system works.","zh":"如果即使高速行駛，安全紀錄仍不糟糕，人們可能問系統為何有效。"},{"en":"The phrase strongly criticises performance in road safety.","zh":"這個短語強烈批評道路安全表現。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":7},{"front":"road safety record","meaning":"道路安全紀錄","examples":[{"en":"Germany’s road safety record is comparable to that of other countries.","zh":"德國的道路安全紀錄可與其他國家相比。"},{"en":"A road safety record is the history or statistics of road accidents, injuries, and deaths.","zh":"road safety record 指道路意外、受傷和死亡的歷史或統計數字。"},{"en":"Governments use road safety records to decide where to add cameras or speed limits.","zh":"政府使用道路安全紀錄決定在哪裡加裝攝影機或速度限制。"},{"en":"A good safety record can show that rules, design, and enforcement are working.","zh":"良好安全紀錄可以顯示規則、設計和執法正在發揮作用。"},{"en":"The phrase focuses on measurable road safety outcomes.","zh":"這個短語重點是可量度的道路安全結果。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":7},{"front":"be comparable to","meaning":"可與……相比","examples":[{"en":"Germany’s road safety record is comparable to that of other European countries.","zh":"德國的道路安全紀錄可與其他歐洲國家相比。"},{"en":"To be comparable to something means to be similar enough to be fairly compared with it.","zh":"be comparable to something 指與某事相似到可以公平比較。"},{"en":"A student’s score may be comparable to last year’s top results.","zh":"學生分數可能可與去年最高成績相比。"},{"en":"If two systems are comparable, differences between them can be meaningfully discussed.","zh":"如果兩個系統可比較，它們之間的差異就可以有意義地討論。"},{"en":"The phrase does not always mean identical; it means suitable for comparison.","zh":"這個短語不一定指完全相同，而是適合比較。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":7},{"front":"in some cases","meaning":"在某些情況下","examples":[{"en":"In some cases, Germany’s record is superior to that of other countries.","zh":"在某些情況下，德國的紀錄優於其他國家。"},{"en":"In some cases means in certain situations, but not all of them.","zh":"in some cases 指在某些情況中，但不是所有情況。"},{"en":"In some cases, online lessons work better than face-to-face lessons for shy students.","zh":"在某些情況下，網上課堂對害羞學生比面授課更有效。"},{"en":"The phrase limits a claim so it does not sound too broad.","zh":"這個短語限制聲稱，使其不會聽起來太廣泛。"},{"en":"It introduces partial, not universal, truth.","zh":"它引入部分真實，而不是普遍真實。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":7},{"front":"superior to","meaning":"優於","examples":[{"en":"Germany’s safety record is sometimes superior to that of other countries.","zh":"德國的安全紀錄有時優於其他國家。"},{"en":"Superior to means better than something else in quality, performance, or result.","zh":"superior to 指在質素、表現或結果上比另一事物更好。"},{"en":"A train may be superior to a bus if it is faster, cleaner, and more reliable.","zh":"如果火車更快、更乾淨和更可靠，它可能優於巴士。"},{"en":"If one system has fewer deaths per distance travelled, its safety record may be superior.","zh":"如果某系統每行駛距離的死亡人數較少，其安全紀錄可能較優。"},{"en":"The phrase clearly expresses comparison and advantage.","zh":"這個短語清楚表達比較和優勢。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":7},{"front":"industrialised European countries","meaning":"工業化歐洲國家","examples":[{"en":"Germany is compared with other industrialised European countries.","zh":"德國與其他工業化歐洲國家作比較。"},{"en":"Industrialised European countries are European nations with developed industries and modern economies.","zh":"industrialised European countries 指擁有發達工業和現代經濟的歐洲國家。"},{"en":"France, Germany, and the Netherlands are often treated as industrialised European countries in comparisons.","zh":"法國、德國和荷蘭在比較中常被視為工業化歐洲國家。"},{"en":"Comparing similar countries makes safety records more meaningful than comparing very different road systems.","zh":"比較相似國家，會比比較非常不同的道路系統更有意義。"},{"en":"The phrase gives the comparison group.","zh":"這個短語提供比較群體。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":7},{"front":"reward recklessness","meaning":"獎賞魯莽行為","examples":[{"en":"The writer asks whether luck is rewarding recklessness.","zh":"作者問是否運氣正在獎賞魯莽行為。"},{"en":"To reward recklessness means to let dangerous behaviour seem successful or go unpunished.","zh":"reward recklessness 指讓危險行為看似成功或不受懲罰。"},{"en":"If a student guesses answers and gets full marks, the result may seem to reward recklessness.","zh":"如果學生亂猜答案卻拿滿分，結果可能像是在獎賞魯莽。"},{"en":"A system that lets risky drivers avoid consequences may encourage more danger.","zh":"讓冒險司機逃避後果的制度，可能鼓勵更多危險。"},{"en":"The phrase criticises situations where careless risk appears to pay off.","zh":"這個短語批評粗心冒險看似有回報的情況。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":7},{"front":"first of all","meaning":"首先","examples":[{"en":"First of all, speed limits do apply at danger spots.","zh":"首先，速度限制確實適用於危險路段。"},{"en":"First of all introduces the first point in an explanation or argument.","zh":"first of all 引入解釋或論證中的第一點。"},{"en":"First of all, students should read the question before looking for answers.","zh":"首先，學生應先閱讀題目，再尋找答案。"},{"en":"Writers use this phrase to organise several reasons clearly.","zh":"作者使用這個短語來清楚組織多個原因。"},{"en":"The phrase signals that more points may follow.","zh":"這個短語表示後面可能還有更多要點。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":7},{"front":"it is important to concede that","meaning":"必須承認","examples":[{"en":"It is important to concede that speed limits apply in some places.","zh":"必須承認，速度限制在一些地方適用。"},{"en":"To concede that means to admit a point, especially one that limits your argument.","zh":"concede that 指承認某一點，尤其是會限制自己論點的一點。"},{"en":"It is important to concede that online learning helps some students, even if it does not help everyone.","zh":"必須承認，網上學習幫到一些學生，即使不是人人都受益。"},{"en":"Conceding a fair point makes an argument more balanced and credible.","zh":"承認公平的一點，會令論證更平衡可信。"},{"en":"The phrase introduces an admission before the main argument continues.","zh":"這個短語在主要論點繼續前引入承認。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":8},{"front":"speed limits do apply","meaning":"速度限制確實適用","examples":[{"en":"Speed limits do apply at junctions and other danger spots.","zh":"速度限制確實適用於交匯處和其他危險路段。"},{"en":"Speed limits do apply means speed rules really are in force in those places.","zh":"speed limits do apply 指速度規則在那些地方確實生效。"},{"en":"School rules do apply during field trips, even outside the classroom.","zh":"學校規則在校外考察時也確實適用，即使不在課室內。"},{"en":"The word do adds emphasis because readers might wrongly think no limits exist.","zh":"do 這個詞加入強調，因為讀者可能錯誤以為完全沒有限制。"},{"en":"The phrase corrects an over-simple impression.","zh":"這個短語糾正過於簡化的印象。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":8},{"front":"junctions","meaning":"交匯處","examples":[{"en":"Speed limits apply at junctions and danger spots.","zh":"速度限制適用於交匯處和危險路段。"},{"en":"Junctions are places where roads meet or cross.","zh":"junctions 指道路相接或交叉的地方。"},{"en":"Drivers slow down at junctions because cars may enter from different directions.","zh":"司機在交匯處會減速，因為車輛可能從不同方向駛入。"},{"en":"Junctions are risky because drivers must watch signs, lanes, and other vehicles at once.","zh":"交匯處有風險，因為司機必須同時留意標誌、行車線和其他車輛。"},{"en":"The phrase refers to road meeting points.","zh":"這個短語指道路相遇位置。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":8},{"front":"danger spots","meaning":"危險路段","examples":[{"en":"Speed limits apply at junctions and other danger spots.","zh":"速度限制適用於交匯處和其他危險路段。"},{"en":"Danger spots are places where accidents are more likely to happen.","zh":"danger spots 指意外較可能發生的地方。"},{"en":"A sharp bend near a school can be a danger spot for drivers and children.","zh":"學校附近的急彎可以是司機和孩子的危險路段。"},{"en":"Authorities may add signs, lights, or cameras at danger spots to reduce accidents.","zh":"當局可能在危險路段加設標誌、燈號或攝影機以減少意外。"},{"en":"The phrase identifies high-risk locations.","zh":"這個短語指出高風險地點。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":8},{"front":"sections under repair","meaning":"維修中的路段","examples":[{"en":"Lower speed limits apply on sections under repair.","zh":"較低速度限制適用於維修中的路段。"},{"en":"Sections under repair are parts of a road or system being fixed or maintained.","zh":"sections under repair 指正在修理或保養的道路或系統部分。"},{"en":"A train line may run slowly through sections under repair.","zh":"火車線可能在維修中的路段慢速行駛。"},{"en":"Roadworks create workers, barriers, and narrow lanes, so slower speeds are safer.","zh":"道路工程有工人、路障和狹窄行車線，因此較慢速度較安全。"},{"en":"The phrase refers to areas temporarily affected by maintenance.","zh":"這個短語指暫時受維修影響的區域。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":8},{"front":"weather-related speed limits","meaning":"與天氣有關的速度限制","examples":[{"en":"There are weather-related speed limits on some autobahn stretches.","zh":"一些德國高速公路路段有與天氣有關的速度限制。"},{"en":"Weather-related speed limits are speed rules that change because of rain, fog, snow, or other weather conditions.","zh":"weather-related speed limits 指因雨、霧、雪或其他天氣狀況而改變的速度規則。"},{"en":"A road may lower its limit during heavy rain because tyres grip less well.","zh":"道路在大雨期間可能降低限速，因為輪胎抓地力較弱。"},{"en":"Weather can make normal speeds unsafe even on a well-built road.","zh":"即使道路建造良好，天氣也可能令正常速度不安全。"},{"en":"The phrase connects driving rules with weather risk.","zh":"這個短語把駕駛規則與天氣風險連起來。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":8},{"front":"wet lanes","meaning":"濕滑行車線","examples":[{"en":"Lower speed limits are used in cases of wet lanes.","zh":"在濕滑行車線的情況下會使用較低速度限制。"},{"en":"Wet lanes are road lanes covered with water or made slippery by rain.","zh":"wet lanes 指被水覆蓋或因雨而變滑的行車線。"},{"en":"Drivers should slow down on wet lanes because braking distances become longer.","zh":"司機在濕滑行車線上應減速，因為煞車距離變長。"},{"en":"Wet lanes increase the risk of skidding, especially at high speeds.","zh":"濕滑行車線增加打滑風險，尤其是在高速下。"},{"en":"The phrase describes a road condition that affects safety.","zh":"這個短語描述影響安全的道路狀況。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":8},{"front":"fail to point this out","meaning":"未有指出這一點","examples":[{"en":"To fail to point this out would create an unfair picture.","zh":"未有指出這一點會造成不公平的畫面。"},{"en":"To fail to point this out means not to mention an important fact.","zh":"fail to point this out 指沒有提及一個重要事實。"},{"en":"A teacher who praises a student’s essay but fails to point out grammar errors gives incomplete feedback.","zh":"如果老師讚學生作文卻未指出文法錯誤，回饋就不完整。"},{"en":"If important limits are not mentioned, readers may believe the system is more reckless than it is.","zh":"如果重要限制沒有被提及，讀者可能相信制度比實際更魯莽。"},{"en":"The phrase warns that omission can mislead.","zh":"這個短語提醒省略資料可以誤導。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":8},{"front":"paint a picture of","meaning":"描繪出……的畫面","examples":[{"en":"The writer does not want to paint a picture of reckless officials.","zh":"作者不想描繪出魯莽官員的畫面。"},{"en":"To paint a picture of something means to create a particular impression or description of it.","zh":"paint a picture of something 指製造某種印象或描述。"},{"en":"A news report can paint a picture of a school as successful or chaotic.","zh":"新聞報道可以把一所學校描繪成成功或混亂。"},{"en":"If writers leave out safety rules, they may paint an unfair picture of the autobahns.","zh":"如果作者省略安全規則，就可能不公平地描繪德國高速公路。"},{"en":"The phrase is metaphorical and means to describe in a certain way.","zh":"這個短語是比喻用法，意思是以某種方式描述。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":8},{"front":"speed-hungry officials","meaning":"崇尚高速的官員","examples":[{"en":"The writer rejects the idea of speed-hungry officials.","zh":"作者否定有崇尚高速官員這種想法。"},{"en":"Speed-hungry officials would be officials who care too much about speed and excitement.","zh":"speed-hungry officials 指過分重視速度和刺激的官員。"},{"en":"A speed-hungry manager might push drivers to deliver faster even when roads are dangerous.","zh":"崇尚高速的經理可能催促司機更快送貨，即使道路危險。"},{"en":"Describing officials this way suggests they ignore safety for thrills.","zh":"這樣描述官員，暗示他們為刺激而忽視安全。"},{"en":"The phrase is critical and slightly humorous.","zh":"這個短語帶批評和輕微幽默意味。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":8},{"front":"the travelling public","meaning":"道路使用者；出行公眾","examples":[{"en":"Road policy should protect the travelling public.","zh":"道路政策應保護道路使用者。"},{"en":"The travelling public means people who use transport systems, especially roads, trains, or planes.","zh":"travelling public 指使用交通系統的人，尤其是道路、火車或飛機。"},{"en":"Bus passengers, drivers, cyclists, and pedestrians can all be part of the travelling public.","zh":"巴士乘客、司機、單車人士和行人都可以屬於出行公眾。"},{"en":"Safety rules exist because the travelling public includes ordinary people who may be affected by risky behaviour.","zh":"安全規則存在，因為道路使用者包括可能受危險行為影響的普通人。"},{"en":"The phrase is formal and refers to transport users as a group.","zh":"這個短語較正式，指作為群體的交通使用者。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":8},{"front":"put someone in jeopardy","meaning":"令某人陷入危險","examples":[{"en":"Officials are not putting the travelling public in jeopardy.","zh":"官員並沒有令道路使用者陷入危險。"},{"en":"To put someone in jeopardy means to place them in danger or at risk.","zh":"put someone in jeopardy 指使某人處於危險或風險之中。"},{"en":"Ignoring fire exits can put students in jeopardy during an emergency.","zh":"忽視消防出口可能在緊急情況中令學生陷入危險。"},{"en":"If a policy seems risky, people ask whether it puts the public in danger.","zh":"如果政策看似有風險，人們會問它是否令公眾陷入危險。"},{"en":"The phrase is formal and serious.","zh":"這個短語較正式且嚴肅。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":9},{"front":"in order to","meaning":"為了","examples":[{"en":"The roads were not designed in order to gratify thrill-seekers.","zh":"這些道路並不是為了滿足尋求刺激者而設計。"},{"en":"In order to means for the purpose of doing something.","zh":"in order to 指為了做某事。"},{"en":"Students practise past papers in order to understand exam timing.","zh":"學生做歷屆試題，是為了理解考試時間安排。"},{"en":"A policy may be designed in order to improve safety, not to satisfy excitement.","zh":"政策可能是為了改善安全而設計，而不是為了滿足刺激感。"},{"en":"The phrase clearly introduces purpose.","zh":"這個短語清楚引入目的。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":9},{"front":"gratify their own thrill-lust","meaning":"滿足自己的刺激慾望","examples":[{"en":"The policy is not designed to gratify officials’ thrill-lust.","zh":"該政策並不是為了滿足官員自己的刺激慾望。"},{"en":"To gratify thrill-lust means to satisfy a strong desire for excitement or danger.","zh":"gratify thrill-lust 指滿足對刺激或危險的強烈渴望。"},{"en":"A teenager may speed downhill on a bike to gratify thrill-lust, even if it is unsafe.","zh":"青少年可能高速踩單車下坡以滿足刺激慾望，即使不安全。"},{"en":"Public policy should not satisfy personal excitement at the expense of safety.","zh":"公共政策不應為了滿足個人刺激而犧牲安全。"},{"en":"The phrase is critical and suggests irresponsible pleasure-seeking.","zh":"這個短語帶批評意味，暗示不負責任地追求刺激。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":9},{"front":"this is not the case","meaning":"情況並非如此","examples":[{"en":"The writer makes clear that this is not the case.","zh":"作者清楚指出情況並非如此。"},{"en":"This is not the case means the situation just described is not true.","zh":"this is not the case 指剛描述的情況並不是真的。"},{"en":"Some people think all online lessons are easy, but this is not the case.","zh":"有些人認為所有網課都容易，但情況並非如此。"},{"en":"The phrase corrects a mistaken belief or assumption.","zh":"這個短語糾正錯誤信念或假設。"},{"en":"It tells readers to reject the previous idea.","zh":"它告訴讀者要否定前一個想法。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":9},{"front":"safety considerations aside","meaning":"撇除安全考慮","examples":[{"en":"Safety considerations aside, speed limits are also used for other purposes.","zh":"撇除安全考慮，速度限制也用於其他目的。"},{"en":"Safety considerations aside means if we temporarily put safety issues to one side.","zh":"safety considerations aside 指如果我們暫時把安全問題放在一旁。"},{"en":"Cost considerations aside, a school trip may still be difficult because of transport.","zh":"撇除成本考慮，學校旅行仍可能因交通而困難。"},{"en":"Writers use this phrase to show that another factor matters besides the obvious one.","zh":"作者使用這個短語表示除了明顯因素外，還有另一因素重要。"},{"en":"The phrase does not ignore safety forever; it simply shifts focus briefly.","zh":"這個短語不是永遠忽視安全，而是暫時轉移焦點。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":9},{"front":"impose speed limits","meaning":"實施速度限制","examples":[{"en":"Germany has imposed speed limits for safety and environmental reasons.","zh":"德國基於安全和環境原因實施速度限制。"},{"en":"To impose speed limits means to officially set maximum driving speeds.","zh":"impose speed limits 指官方設定最高行車速度。"},{"en":"A city may impose speed limits near schools to protect children.","zh":"城市可能在學校附近實施速度限制以保護兒童。"},{"en":"Speed limits can reduce crashes, noise, and pollution when properly enforced.","zh":"如果妥善執行，速度限制可以減少撞車、噪音和污染。"},{"en":"The phrase shows authorities applying driving rules.","zh":"這個短語顯示當局套用駕駛規則。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":9},{"front":"reduce pollution and noise","meaning":"減少污染和噪音","examples":[{"en":"Some speed limits aim to reduce pollution and noise.","zh":"一些速度限制旨在減少污染和噪音。"},{"en":"To reduce pollution and noise means to lower harmful emissions and unwanted sound.","zh":"reduce pollution and noise 指降低有害排放和不想要的聲音。"},{"en":"Slower traffic near homes can reduce noise and make streets more comfortable.","zh":"住宅附近較慢的交通可以減少噪音，令街道更舒適。"},{"en":"Lower speeds may reduce fuel use, which can reduce air pollution.","zh":"較低速度可能減少燃油使用，從而減少空氣污染。"},{"en":"The phrase connects road policy with environmental quality.","zh":"這個短語把道路政策與環境質素連起來。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":9},{"front":"no crazy speed-fuelled agenda","meaning":"沒有瘋狂追求速度的目的","examples":[{"en":"There is no crazy speed-fuelled agenda behind the policy.","zh":"該政策背後沒有瘋狂追求速度的目的。"},{"en":"No crazy speed-fuelled agenda means there is no hidden plan based on obsession with speed.","zh":"no crazy speed-fuelled agenda 指沒有基於迷戀速度的隱藏計劃。"},{"en":"A school’s sports day is not a crazy competition agenda if teachers mainly want students to enjoy exercise.","zh":"如果老師主要想學生享受運動，學校運動日就不是瘋狂競爭議程。"},{"en":"The phrase rejects the idea that officials are motivated by reckless excitement.","zh":"這個短語否定官員受魯莽刺激驅動的想法。"},{"en":"It is informal and slightly humorous.","zh":"它較非正式，帶輕微幽默。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":9},{"front":"actually seem to think","meaning":"似乎真的認為","examples":[{"en":"The Germans actually seem to think this policy is safe.","zh":"德國人似乎真的認為這項政策是安全的。"},{"en":"Actually seem to think means apparently believe something, perhaps surprisingly.","zh":"actually seem to think 指似乎相信某事，而且可能令人意外。"},{"en":"Some students actually seem to think rereading notes is enough without practice.","zh":"一些學生似乎真的認為只重讀筆記而不練習就足夠。"},{"en":"The word actually signals that the belief may surprise the reader.","zh":"actually 這個詞表示該信念可能令讀者意外。"},{"en":"The phrase introduces someone’s apparent viewpoint.","zh":"這個短語引入某人的表面觀點。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":9},{"front":"back someone up","meaning":"支持某人的說法","examples":[{"en":"The statistics appear to back them up.","zh":"統計數字似乎支持他們的說法。"},{"en":"To back someone up means to support their claim, argument, or account.","zh":"back someone up 指支持某人的聲稱、論點或說法。"},{"en":"A teacher’s comments may be backed up by test scores showing the same weakness.","zh":"如果測驗分數顯示同樣弱點，老師評語就得到支持。"},{"en":"If statistics support a policy, the policy seems less reckless than critics think.","zh":"如果統計數字支持某政策，該政策就比批評者想像中較不魯莽。"},{"en":"The phrase connects evidence with support.","zh":"這個短語把證據與支持連起來。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":9},{"front":"after all","meaning":"畢竟","examples":[{"en":"After all, the statistics support the German approach.","zh":"畢竟，統計數字支持德國做法。"},{"en":"After all introduces a reason that explains or justifies what has just been said.","zh":"after all 引入解釋或合理化剛才所說內容的原因。"},{"en":"You should bring an umbrella; after all, the forecast says it will rain.","zh":"你應該帶傘；畢竟，天氣預報說會下雨。"},{"en":"Writers use this phrase to make a conclusion sound reasonable.","zh":"作者使用這個短語令結論聽起來合理。"},{"en":"It points to supporting evidence or common sense.","zh":"它指向支持證據或常識。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":9},{"front":"road-user fatalities","meaning":"道路使用者死亡人數","examples":[{"en":"The study measured road-user fatalities per billion vehicle kilometres.","zh":"該研究量度每十億車輛公里的道路使用者死亡人數。"},{"en":"Road-user fatalities are deaths of people using roads, including drivers, passengers, cyclists, and pedestrians.","zh":"road-user fatalities 指使用道路的人死亡，包括司機、乘客、單車人士和行人。"},{"en":"Governments track road-user fatalities to judge whether roads are becoming safer.","zh":"政府追蹤道路使用者死亡人數，以判斷道路是否變得更安全。"},{"en":"If fatalities fall, safety measures may be working.","zh":"如果死亡人數下降，安全措施可能正在發揮作用。"},{"en":"The phrase is formal and statistical.","zh":"這個短語較正式，屬統計用語。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":10},{"front":"per billion vehicle kilometres","meaning":"每十億車輛公里","examples":[{"en":"The autobahns have 2.2 fatalities per billion vehicle kilometres.","zh":"德國高速公路每十億車輛公里有2.2宗死亡。"},{"en":"Per billion vehicle kilometres means for every one billion kilometres travelled by vehicles.","zh":"per billion vehicle kilometres 指每十億公里車輛行駛距離。"},{"en":"This measure lets researchers compare road safety across countries with different traffic levels.","zh":"這個衡量標準讓研究人員比較交通量不同國家的道路安全。"},{"en":"A low figure per billion vehicle kilometres suggests fewer deaths for the distance driven.","zh":"每十億車輛公里數字較低，表示每行駛距離的死亡較少。"},{"en":"The phrase is a statistical rate, not a total number.","zh":"這個短語是統計比率，而不是總數。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":10},{"front":"using the same measure","meaning":"使用同一衡量標準","examples":[{"en":"Using the same measure, the United States figure is higher.","zh":"使用同一衡量標準，美國的數字較高。"},{"en":"Using the same measure means applying the same method of calculation or comparison.","zh":"using the same measure 指使用相同計算或比較方法。"},{"en":"Using the same measure, two schools can compare exam results more fairly.","zh":"使用同一衡量標準，兩所學校可以更公平地比較考試結果。"},{"en":"Fair comparison requires the same measure; otherwise numbers may mislead.","zh":"公平比較需要同一衡量標準；否則數字可能誤導。"},{"en":"The phrase stresses consistency in comparison.","zh":"這個短語強調比較一致性。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":10},{"front":"look beyond","meaning":"看穿；不只看到","examples":[{"en":"We need to look beyond the myth of limitless speed.","zh":"我們需要看穿無限速的迷思。"},{"en":"To look beyond something means to see past the surface idea and examine deeper facts.","zh":"look beyond something 指超越表面想法，檢視更深層事實。"},{"en":"Teachers look beyond grades when they consider effort, progress, and confidence.","zh":"老師評估學生時，不只看分數，也考慮努力、進步和信心。"},{"en":"Looking beyond a myth can reveal a more complicated and accurate reality.","zh":"看穿迷思可以揭示更複雜而準確的現實。"},{"en":"The phrase encourages deeper thinking.","zh":"這個短語鼓勵更深入思考。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":10},{"front":"the myth of","meaning":"……的迷思","examples":[{"en":"The myth of the motorway without speed limits is misleading.","zh":"沒有限速高速公路的迷思具誤導性。"},{"en":"The myth of something is a popular but oversimplified or false belief about it.","zh":"myth of something 指關於某事流行但過度簡化或錯誤的信念。"},{"en":"The myth of overnight success ignores years of practice and failure.","zh":"一夜成功的迷思忽略多年練習和失敗。"},{"en":"Myths become powerful when people repeat only the exciting part of a story.","zh":"當人們只重複故事中刺激的部分，迷思就變得有力量。"},{"en":"The phrase introduces a belief that needs correction.","zh":"這個短語引入需要糾正的信念。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":10},{"front":"clock up speeds","meaning":"達到某速度","examples":[{"en":"Some drivers clock up speeds in excess of 200 km/h.","zh":"一些司機達到超過每小時200公里的速度。"},{"en":"To clock up speeds means to reach or record particular speeds.","zh":"clock up speeds 指達到或錄得特定速度。"},{"en":"A runner may clock up a fast time after months of training.","zh":"跑手經過數月訓練後，可能錄得很快時間。"},{"en":"Cars can clock up high speeds only when conditions and engine power allow it.","zh":"汽車只有在環境和引擎性能容許時，才能達到高速。"},{"en":"The phrase is informal and often used with measurable performance.","zh":"這個短語較非正式，常與可量度表現連用。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":10},{"front":"uncover the reality","meaning":"揭示現實","examples":[{"en":"The passage uncovers the more sober reality behind the myth.","zh":"文章揭示迷思背後較冷靜客觀的現實。"},{"en":"To uncover the reality means to reveal what is actually true after removing misunderstanding.","zh":"uncover the reality 指在消除誤解後揭示真正情況。"},{"en":"A budget review may uncover the reality that a project costs more than expected.","zh":"預算檢討可能揭示現實：項目成本比預期高。"},{"en":"When a famous story is exaggerated, investigation can uncover a calmer truth.","zh":"當著名故事被誇張，調查可以揭示較冷靜的真相。"},{"en":"The phrase suggests moving from myth to fact.","zh":"這個短語暗示由迷思走向事實。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":10},{"front":"the more sober reality","meaning":"較冷靜客觀的現實","examples":[{"en":"The more sober reality is that speeds are often regulated.","zh":"較冷靜客觀的現實是速度其實經常受到規管。"},{"en":"The more sober reality is the calmer, more realistic truth after excitement or exaggeration is removed.","zh":"more sober reality 指去除興奮或誇張後較冷靜、較現實的真相。"},{"en":"A school may look glamorous online, but the sober reality is that students still need hard work.","zh":"學校在網上可能看起來很光鮮，但冷靜現實是學生仍需努力。"},{"en":"Sober reality often makes a dramatic story less simple but more accurate.","zh":"冷靜現實通常令戲劇性故事不再簡單，但更準確。"},{"en":"The phrase contrasts hype with balanced facts.","zh":"這個短語把炒作與平衡事實作對比。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":10},{"front":"the German approach","meaning":"德國的做法","examples":[{"en":"The German approach may be more sensible than it first appears.","zh":"德國的做法可能比一開始看起來更合理。"},{"en":"The German approach means Germany’s way of dealing with a policy or problem.","zh":"German approach 指德國處理政策或問題的方式。"},{"en":"A country’s approach to education may combine national exams with vocational training.","zh":"一個國家的教育做法可能結合全國考試和職業訓練。"},{"en":"Understanding the German approach requires looking at rules, enforcement, traffic, and car design together.","zh":"理解德國做法需要同時看規則、執法、交通和汽車設計。"},{"en":"The phrase refers to a method or policy style.","zh":"這個短語指方法或政策風格。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":10},{"front":"not so daft as","meaning":"並不像……那麼愚蠢","examples":[{"en":"The German approach is not so daft as it first seemed.","zh":"德國的做法並不像一開始看起來那麼愚蠢。"},{"en":"Not so daft as means not as foolish as something first appeared.","zh":"not so daft as 指不像某事最初看起來那麼愚蠢。"},{"en":"A strict homework rule may not be so daft as students think if it builds daily practice.","zh":"如果嚴格功課規則建立每日練習，它可能不像學生想像中那麼蠢。"},{"en":"When hidden reasons are explained, a strange policy may seem more sensible.","zh":"當隱藏原因被解釋，奇怪政策可能顯得更合理。"},{"en":"The phrase softens an initial negative judgement.","zh":"這個短語軟化最初的負面判斷。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":10},{"front":"for a start","meaning":"首先；其中一點是","examples":[{"en":"For a start, only a small amount of traffic uses unrestricted stretches.","zh":"首先，只有少量交通使用沒有限速的路段。"},{"en":"For a start introduces the first reason or example in an explanation.","zh":"for a start 引入解釋中的第一個理由或例子。"},{"en":"The plan is useful; for a start, it gives students a clear timetable.","zh":"這個計劃有用；首先，它給學生清楚時間表。"},{"en":"The phrase signals that more supporting points may follow.","zh":"這個短語表示後面可能有更多支持點。"},{"en":"It is conversational and helps organise reasoning.","zh":"它較口語化，有助組織推理。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":10},{"front":"unrestricted stretches of motorway","meaning":"沒有限速的高速公路路段","examples":[{"en":"Only a small amount of traffic regularly travels on unrestricted stretches of motorway.","zh":"只有少量交通經常行駛在沒有限速的高速公路路段。"},{"en":"Unrestricted stretches of motorway are sections where certain vehicles have no general legal speed limit.","zh":"unrestricted stretches of motorway 指某些車輛沒有一般法律速度限制的路段。"},{"en":"Drivers may seek unrestricted stretches if they want to experience faster driving.","zh":"如果司機想體驗較高速駕駛，可能尋找沒有限速路段。"},{"en":"If such stretches have low traffic, the danger may be lower than people imagine.","zh":"如果這些路段交通流量低，危險可能比人們想像中低。"},{"en":"The phrase refers to specific sections, not the whole autobahn system.","zh":"這個短語指特定路段，而不是整個高速公路系統。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":11},{"front":"despite the vast area they cover","meaning":"儘管它們覆蓋範圍廣","examples":[{"en":"Despite the vast area they cover, these stretches carry little traffic.","zh":"儘管這些路段覆蓋範圍廣，它們承載的交通很少。"},{"en":"Despite the vast area they cover means although they extend across a large space.","zh":"despite the vast area they cover 指雖然它們延伸很大空間。"},{"en":"Despite the large campus it owns, a school may have few students in some buildings.","zh":"儘管學校擁有大型校園，一些建築物中可能學生很少。"},{"en":"A large area does not always mean heavy use.","zh":"面積大不一定代表使用量高。"},{"en":"The phrase contrasts size with actual activity.","zh":"這個短語把大小與實際活動作對比。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":11},{"front":"be strategically located","meaning":"策略性地設於","examples":[{"en":"Unrestricted stretches are strategically located in rural areas.","zh":"沒有限速路段策略性地設於鄉郊地區。"},{"en":"To be strategically located means to be placed carefully for a practical purpose.","zh":"be strategically located 指為實際目的而被仔細安排位置。"},{"en":"A school clinic may be strategically located near the sports field.","zh":"學校診所可能策略性地設於運動場附近。"},{"en":"Locating fast roads in low-traffic areas can reduce risk to dense communities.","zh":"把高速道路設於低交通地區，可以減少對密集社區的風險。"},{"en":"The phrase suggests deliberate planning, not random placement.","zh":"這個短語暗示有意規劃，而不是隨機位置。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":11},{"front":"rural areas","meaning":"鄉郊地區","examples":[{"en":"Unrestricted stretches are located in rural areas with low traffic volume.","zh":"沒有限速路段位於交通流量低的鄉郊地區。"},{"en":"Rural areas are countryside places outside towns and cities.","zh":"rural areas 指城鎮和城市以外的鄉村地方。"},{"en":"Farms, small villages, fields, and forests are often found in rural areas.","zh":"農場、小村莊、田野和森林常見於鄉郊地區。"},{"en":"Rural roads may have fewer vehicles, but they still need careful safety rules.","zh":"鄉郊道路可能車輛較少，但仍需要仔細安全規則。"},{"en":"The phrase contrasts countryside settings with urban areas.","zh":"這個短語把鄉村環境與城市地區作對比。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":11},{"front":"low traffic volume","meaning":"低交通流量","examples":[{"en":"The unrestricted stretches usually have low traffic volume.","zh":"沒有限速路段通常交通流量低。"},{"en":"Low traffic volume means a small number of vehicles use a road or area.","zh":"low traffic volume 指使用某道路或地區的車輛數量少。"},{"en":"A quiet village road has low traffic volume compared with a city highway.","zh":"安靜村路與城市高速公路相比交通流量低。"},{"en":"Low traffic volume can reduce accident risk because there are fewer vehicles interacting.","zh":"低交通流量可以降低意外風險，因為互相影響的車輛較少。"},{"en":"The phrase measures how busy a road is.","zh":"這個短語量度道路有多繁忙。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":11},{"front":"do in fact","meaning":"事實上的確","examples":[{"en":"Most vehicles do in fact have their speeds strictly regulated.","zh":"大多數車輛事實上的確受到嚴格速度規管。"},{"en":"Do in fact adds emphasis that something is really true, despite possible doubt.","zh":"do in fact 強調某事確實是真的，即使可能有人懷疑。"},{"en":"Some students think grammar is unimportant, but it does in fact affect clarity.","zh":"有些學生認為文法不重要，但它事實上的確影響清晰度。"},{"en":"The phrase corrects a mistaken impression by stressing the real situation.","zh":"這個短語透過強調真實情況來糾正錯誤印象。"},{"en":"It is useful when readers might expect the opposite.","zh":"當讀者可能預期相反情況時，它很有用。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":11},{"front":"strictly regulated","meaning":"受到嚴格規管","examples":[{"en":"Most vehicles have their speeds strictly regulated.","zh":"大多數車輛的速度受到嚴格規管。"},{"en":"Strictly regulated means controlled by clear and strongly enforced rules.","zh":"strictly regulated 指由清晰且強力執行的規則控制。"},{"en":"Medicines are strictly regulated because wrong use can harm patients.","zh":"藥物受到嚴格規管，因為錯誤使用可能傷害病人。"},{"en":"If vehicle speeds are strictly regulated, drivers have less freedom but roads may be safer.","zh":"如果車速受到嚴格規管，司機自由較少，但道路可能更安全。"},{"en":"The phrase stresses strong control.","zh":"這個短語強調強力控制。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":11},{"front":"heavily enforced","meaning":"嚴格執行","examples":[{"en":"Speed regulations are heavily enforced on German motorways.","zh":"德國高速公路上的速度規定受到嚴格執行。"},{"en":"Heavily enforced means rules are checked and punished strictly and often.","zh":"heavily enforced 指規則被頻繁而嚴格地檢查和懲罰。"},{"en":"Parking rules are heavily enforced near hospitals to keep emergency entrances clear.","zh":"醫院附近的泊車規則受到嚴格執行，以保持急症入口暢通。"},{"en":"Rules only work well when drivers believe they are likely to be caught for breaking them.","zh":"只有當司機相信違規很可能被抓到，規則才會有效。"},{"en":"The phrase stresses active enforcement, not rules on paper only.","zh":"這個短語強調主動執法，而不只是紙上規則。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":11},{"front":"speed cameras","meaning":"測速攝影機","examples":[{"en":"Speed cameras are everywhere on the motorways.","zh":"高速公路上到處都有測速攝影機。"},{"en":"Speed cameras are devices that record vehicles travelling above the legal speed limit.","zh":"speed cameras 指記錄超過法定速度限制車輛的裝置。"},{"en":"A city may install speed cameras near schools to slow drivers down.","zh":"城市可能在學校附近安裝測速攝影機以令司機減速。"},{"en":"Cameras can make enforcement easier because they do not rely only on police stopping cars.","zh":"攝影機可以令執法更容易，因為不只依靠警察截停車輛。"},{"en":"The phrase refers to technology used to detect speeding.","zh":"這個短語指用來偵測超速的科技。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":11},{"front":"be patrolled by","meaning":"由……巡邏","examples":[{"en":"The motorways are patrolled by unmarked police cars.","zh":"高速公路由沒有標記的警車巡邏。"},{"en":"To be patrolled by someone means to be regularly watched or checked by them.","zh":"be patrolled by someone 指由某人定期看守或檢查。"},{"en":"A school corridor may be patrolled by teachers during breaks.","zh":"小息期間，學校走廊可能由老師巡邏。"},{"en":"Patrols can prevent bad behaviour because people know they may be observed.","zh":"巡邏可以防止不良行為，因為人們知道自己可能被觀察。"},{"en":"The phrase describes regular monitoring.","zh":"這個短語描述定期監察。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":11},{"front":"unmarked police cars","meaning":"沒有標記的警車","examples":[{"en":"Unmarked police cars patrol the motorways.","zh":"沒有標記的警車在高速公路上巡邏。"},{"en":"Unmarked police cars are police vehicles without obvious police markings.","zh":"unmarked police cars 指沒有明顯警察標記的警車。"},{"en":"Drivers may not notice an unmarked police car until it signals them to stop.","zh":"司機可能到沒有標記的警車示意停車時才注意到它。"},{"en":"Unmarked cars help police catch drivers who behave well only when marked police cars are visible.","zh":"沒有標記的警車幫助警方抓住只在看見有標記警車時才守規的司機。"},{"en":"The phrase refers to hidden or less obvious police vehicles.","zh":"這個短語指隱蔽或較不明顯的警車。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":11},{"front":"pull over speed offenders","meaning":"截停超速駕駛者","examples":[{"en":"Police cars are ready to pull over speed offenders.","zh":"警車準備截停超速駕駛者。"},{"en":"To pull over speed offenders means to stop drivers who are breaking speed rules.","zh":"pull over speed offenders 指截停違反速度規則的司機。"},{"en":"Police may pull over a driver who races through a school zone.","zh":"警方可能截停在校區高速行駛的司機。"},{"en":"Pulling over offenders allows officers to warn, fine, or investigate them.","zh":"截停違例者讓警員可以警告、罰款或調查他們。"},{"en":"The phrase describes direct roadside enforcement.","zh":"這個短語描述直接道路執法。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":12},{"front":"speed offenders","meaning":"超速違例者","examples":[{"en":"Speed offenders can be stopped by unmarked police cars.","zh":"超速違例者可能被沒有標記的警車截停。"},{"en":"Speed offenders are drivers who break speed rules or limits.","zh":"speed offenders 指違反速度規則或限制的司機。"},{"en":"A driver going 80 km/h in a 50 km/h zone is a speed offender.","zh":"在每小時50公里區域開到80公里的司機就是超速違例者。"},{"en":"Punishing speed offenders can discourage dangerous driving.","zh":"懲罰超速違例者可以阻止危險駕駛。"},{"en":"The phrase identifies people who violate speed laws.","zh":"這個短語指出違反速度法律的人。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":12},{"front":"reckless drivers","meaning":"魯莽駕駛者","examples":[{"en":"Unmarked police cars also target reckless drivers.","zh":"沒有標記的警車也針對魯莽駕駛者。"},{"en":"Reckless drivers are drivers who take careless risks and ignore safety.","zh":"reckless drivers 指冒粗心風險並忽視安全的司機。"},{"en":"A reckless driver may change lanes suddenly without checking mirrors.","zh":"魯莽駕駛者可能不看倒後鏡就突然轉線。"},{"en":"Reckless driving can endanger passengers, pedestrians, and other motorists.","zh":"魯莽駕駛可以危及乘客、行人和其他駕駛者。"},{"en":"The phrase strongly criticises unsafe driving behaviour.","zh":"這個短語強烈批評不安全駕駛行為。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":12},{"front":"take into consideration","meaning":"考慮到","examples":[{"en":"The Germans have taken accident statistics into consideration.","zh":"德國人已考慮到意外統計數字。"},{"en":"To take something into consideration means to think about it when making a decision.","zh":"take something into consideration 指作決定時考慮某事。"},{"en":"A teacher takes students’ workload into consideration before setting homework.","zh":"老師在布置功課前會考慮學生工作量。"},{"en":"Good policy considers evidence, risk, cost, and practical behaviour.","zh":"良好政策會考慮證據、風險、成本和實際行為。"},{"en":"The phrase shows that a factor influenced the decision.","zh":"這個短語顯示某因素影響了決定。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":12},{"front":"very few road accidents occur","meaning":"很少發生交通意外","examples":[{"en":"Very few road accidents occur on low-volume motorways.","zh":"低流量高速公路上很少發生交通意外。"},{"en":"Very few road accidents occur means accidents happen only rarely.","zh":"very few road accidents occur 指意外很少發生。"},{"en":"Very few injuries occur in a well-supervised playground with clear rules.","zh":"在監督良好且規則清楚的操場上，很少發生受傷事故。"},{"en":"Low traffic can reduce the number of vehicle interactions that lead to crashes.","zh":"低交通流量可以減少導致撞車的車輛互動。"},{"en":"The phrase describes a low accident frequency.","zh":"這個短語描述低意外頻率。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":12},{"front":"low-volume traffic","meaning":"低流量交通","examples":[{"en":"Few accidents occur on motorways with low-volume traffic.","zh":"低流量交通的高速公路上很少發生意外。"},{"en":"Low-volume traffic means a small amount of traffic using a road.","zh":"low-volume traffic 指道路上的交通量少。"},{"en":"A country road at dawn may have low-volume traffic compared with a city centre road.","zh":"清晨鄉郊道路與市中心道路相比，可能交通流量低。"},{"en":"Low-volume traffic can make driving conditions calmer, but speed still matters.","zh":"低流量交通可以令駕駛環境較平靜，但速度仍重要。"},{"en":"The phrase describes traffic quantity.","zh":"這個短語描述交通數量。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":12},{"front":"offer up","meaning":"提供","examples":[{"en":"These stretches of motorway offer up some of the safest driving conditions.","zh":"這些高速公路路段提供一些最安全的駕駛環境。"},{"en":"To offer up something means to provide or present it.","zh":"offer up something 指提供或呈現某物。"},{"en":"A library can offer up quiet study rooms during exam season.","zh":"圖書館可以在考試季提供安靜自修室。"},{"en":"Low traffic and good road design can provide safer driving conditions.","zh":"低交通流量和良好道路設計可以提供更安全駕駛環境。"},{"en":"The phrase is slightly more colourful than simply offer.","zh":"這個短語比 simply offer 稍為生動。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":12},{"front":"driving conditions","meaning":"駕駛環境","examples":[{"en":"Rural motorways can offer safe driving conditions.","zh":"鄉郊高速公路可以提供安全駕駛環境。"},{"en":"Driving conditions are the road, weather, traffic, and visibility factors affecting drivers.","zh":"driving conditions 指影響司機的道路、天氣、交通和能見度因素。"},{"en":"Heavy rain, fog, and crowded lanes create difficult driving conditions.","zh":"大雨、霧和擠迫行車線會造成困難駕駛環境。"},{"en":"Good driving conditions can lower risk, but they do not remove the need for care.","zh":"良好駕駛環境可以降低風險，但不代表不需要小心。"},{"en":"The phrase describes the environment in which people drive.","zh":"這個短語描述人們駕駛時所處的環境。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":12},{"front":"statistically speaking","meaning":"從統計角度而言","examples":[{"en":"Statistically speaking, these motorways are among the safest.","zh":"從統計角度而言，這些高速公路屬於最安全之列。"},{"en":"Statistically speaking means based on numbers or data.","zh":"statistically speaking 指根據數字或數據而言。"},{"en":"Statistically speaking, students who sleep enough often perform better in tests.","zh":"從統計角度而言，睡眠充足的學生通常測驗表現較好。"},{"en":"The phrase separates evidence from personal impressions or stories.","zh":"這個短語把證據與個人印象或故事分開。"},{"en":"It introduces a data-based judgement.","zh":"它引入基於數據的判斷。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":12},{"front":"reason that","meaning":"推論；認為","examples":[{"en":"The Germans have reasoned that rural motorways do not need heavy regulation.","zh":"德國人推論鄉郊高速公路不需要大量規管。"},{"en":"To reason that something is true means to reach that conclusion by thinking logically.","zh":"reason that something is true 指透過邏輯思考得出某結論。"},{"en":"A teacher may reason that shorter tasks are better if students are already exhausted.","zh":"如果學生已經很疲倦，老師可能推論較短任務更好。"},{"en":"If accidents are rare in low-traffic areas, officials may decide heavy limits are unnecessary there.","zh":"如果低交通地區意外很少，官員可能認為那裡不需要嚴格限制。"},{"en":"The phrase focuses on logical thinking from evidence.","zh":"這個短語重點是從證據進行邏輯思考。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":12},{"front":"regulate something a great deal","meaning":"大幅規管……","examples":[{"en":"They do not need to regulate rural motorways a great deal.","zh":"他們不需要大幅規管鄉郊高速公路。"},{"en":"To regulate something a great deal means to control it heavily with many rules.","zh":"regulate something a great deal 指用許多規則嚴格控制某事。"},{"en":"A school may regulate exam-room behaviour a great deal to prevent cheating.","zh":"學校可能大幅規管考試室行為，以防作弊。"},{"en":"If a place is already safe, heavy regulation may be unnecessary.","zh":"如果某地方本來已安全，重度規管可能沒有必要。"},{"en":"The phrase describes strong or extensive control.","zh":"這個短語描述強烈或廣泛控制。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":12},{"front":"it would seem","meaning":"看來","examples":[{"en":"It would seem that the Germans are right.","zh":"看來德國人是對的。"},{"en":"It would seem means it appears likely, based on the evidence available.","zh":"it would seem 指根據現有證據看起來可能如此。"},{"en":"It would seem that the new timetable works, because fewer students arrive late.","zh":"看來新時間表有效，因為較少學生遲到。"},{"en":"The phrase sounds cautious rather than absolute.","zh":"這個短語聽起來謹慎，而不是絕對。"},{"en":"It introduces a reasonable conclusion.","zh":"它引入合理結論。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":13},{"front":"the myth of limitless speed","meaning":"無限速的迷思","examples":[{"en":"The myth of limitless speed is quite misleading.","zh":"無限速的迷思頗具誤導性。"},{"en":"The myth of limitless speed is the popular belief that drivers can simply go as fast as they want everywhere.","zh":"myth of limitless speed 指司機可以到處隨心所欲高速行駛的流行信念。"},{"en":"A tourist may believe this myth before learning about weather limits, vehicle limits, and police enforcement.","zh":"遊客在了解天氣限制、車輛限制和警方執法前，可能相信這個迷思。"},{"en":"Myths become misleading when they ignore rules and practical restrictions.","zh":"當迷思忽略規則和實際限制，它就變得誤導。"},{"en":"The phrase challenges an exaggerated idea about the autobahns.","zh":"這個短語挑戰關於德國高速公路的誇張想法。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":13},{"front":"quite misleading","meaning":"頗具誤導性","examples":[{"en":"The idea of limitless speed is quite misleading.","zh":"無限速的想法頗具誤導性。"},{"en":"Quite misleading means likely to give people a wrong impression.","zh":"quite misleading 指很可能給人錯誤印象。"},{"en":"A school advertisement can be quite misleading if it shows only top students and hides weak results.","zh":"如果學校廣告只展示尖子而隱藏較弱結果，就可能頗具誤導性。"},{"en":"A half-truth can mislead people even when it contains some real facts.","zh":"半真半假的說法即使包含一些事實，也可以誤導人。"},{"en":"The phrase warns that an idea is not fully accurate.","zh":"這個短語提醒某想法並不完全準確。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":13},{"front":"in reality","meaning":"事實上","examples":[{"en":"In reality, manufacturers limit the top speed of their cars.","zh":"事實上，製造商限制其汽車的最高速度。"},{"en":"In reality means in the real situation, not in imagination or theory.","zh":"in reality 指在真實情況中，而不是想像或理論中。"},{"en":"Many students think writing is only about vocabulary; in reality, structure matters just as much.","zh":"許多學生以為寫作只關乎詞彙；事實上，結構同樣重要。"},{"en":"The phrase corrects an impression by showing what actually happens.","zh":"這個短語透過顯示實際發生的事來糾正印象。"},{"en":"It often contrasts myth with fact.","zh":"它常把迷思與事實作對比。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":13},{"front":"car manufacturers","meaning":"汽車製造商","examples":[{"en":"German car manufacturers keep to a gentleman’s agreement.","zh":"德國汽車製造商遵守一項君子協定。"},{"en":"Car manufacturers are companies that design and build cars.","zh":"car manufacturers 指設計和製造汽車的公司。"},{"en":"Toyota, BMW, and Volkswagen are examples of car manufacturers.","zh":"Toyota、BMW 和 Volkswagen 都是汽車製造商的例子。"},{"en":"Manufacturers can influence road safety by designing vehicles with limits and safety systems.","zh":"製造商可以透過設計有速度限制和安全系統的車輛影響道路安全。"},{"en":"The phrase refers to vehicle-producing companies.","zh":"這個短語指生產車輛的公司。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":13},{"front":"keep to","meaning":"遵守","examples":[{"en":"Manufacturers keep to a gentleman’s agreement on top speed.","zh":"製造商遵守關於最高速度的君子協定。"},{"en":"To keep to an agreement or rule means to follow it.","zh":"keep to an agreement or rule 指遵守協議或規則。"},{"en":"Students should keep to the exam timetable so no section is left unfinished.","zh":"學生應遵守考試時間安排，才不會有部分未完成。"},{"en":"If companies keep to a voluntary agreement, formal law may be less necessary.","zh":"如果公司遵守自願協議，正式法律可能較不必要。"},{"en":"The phrase stresses continuing to follow a commitment.","zh":"這個短語強調持續遵守承諾。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":13},{"front":"a gentleman’s agreement","meaning":"君子協定","examples":[{"en":"Car manufacturers keep to a gentleman’s agreement about speed limits.","zh":"汽車製造商遵守一項關於速度限制的君子協定。"},{"en":"A gentleman’s agreement is an informal agreement based on trust rather than law.","zh":"gentleman’s agreement 指基於信任而非法例的非正式協議。"},{"en":"Two neighbours may have a gentleman’s agreement to share garden tools.","zh":"兩個鄰居可能有君子協定，共用園藝工具。"},{"en":"Such agreements work only if people or companies voluntarily keep their promise.","zh":"這類協定只有在人或公司自願守諾時才有效。"},{"en":"The phrase contrasts informal self-restraint with legal obligation.","zh":"這個短語把非正式自我約束與法律義務作對比。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":13},{"front":"whereby","meaning":"憑藉該協定；根據該安排","examples":[{"en":"They keep to an agreement whereby they limit the top speed of their cars.","zh":"他們遵守一項協定，根據該安排限制汽車最高速度。"},{"en":"Whereby means by which or through which a process happens.","zh":"whereby 指憑藉某方法或透過某安排。"},{"en":"A school may use a system whereby students book study rooms online.","zh":"學校可能使用一套系統，學生憑藉該系統在網上預訂自修室。"},{"en":"The word introduces the method or arrangement that makes something happen.","zh":"這個詞引入使某事發生的方法或安排。"},{"en":"It is formal and often used in explanations of systems.","zh":"它較正式，常用於解釋制度。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":13},{"front":"limit the top speed of","meaning":"限制……的最高速度","examples":[{"en":"Manufacturers limit the top speed of their cars.","zh":"製造商限制其汽車的最高速度。"},{"en":"To limit the top speed of a vehicle means to set a maximum speed it can reach.","zh":"limit the top speed of a vehicle 指設定車輛可以達到的最高速度。"},{"en":"Parents may limit the top speed of an electric scooter used by a child.","zh":"父母可能限制孩子使用的電動滑板車最高速度。"},{"en":"Limiting top speed can reduce the chance of dangerous mechanical failure.","zh":"限制最高速度可以降低危險機械故障機會。"},{"en":"The phrase focuses on restricting maximum possible speed.","zh":"這個短語重點是限制最高可能速度。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":13},{"front":"for safety reasons","meaning":"基於安全理由","examples":[{"en":"Manufacturers limit top speeds for safety reasons.","zh":"製造商基於安全理由限制最高速度。"},{"en":"For safety reasons means because the aim is to prevent harm or danger.","zh":"for safety reasons 指因為目的是防止傷害或危險。"},{"en":"A school may cancel sports day for safety reasons during a thunderstorm.","zh":"學校可能基於安全理由在雷暴期間取消運動會。"},{"en":"Safety reasons can justify restrictions even when people prefer more freedom.","zh":"即使人們想要更多自由，安全理由也可以合理化限制。"},{"en":"The phrase explains why a rule or decision exists.","zh":"這個短語解釋規則或決定存在的原因。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":13},{"front":"tyre pressure","meaning":"胎壓","examples":[{"en":"Tyre pressure must be optimally maintained at high speeds.","zh":"高速行駛時，胎壓必須維持在最佳狀態。"},{"en":"Tyre pressure is the amount of air pressure inside a vehicle’s tyres.","zh":"tyre pressure 指車輛輪胎內的空氣壓力。"},{"en":"Drivers should check tyre pressure before long journeys.","zh":"司機在長途旅程前應檢查胎壓。"},{"en":"Wrong tyre pressure can reduce control, increase wear, and raise the risk of blowouts.","zh":"錯誤胎壓可以降低控制力、增加磨損並提高爆胎風險。"},{"en":"The phrase refers to a basic but important safety condition.","zh":"這個短語指基本但重要的安全狀況。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":13},{"front":"optimally maintained","meaning":"維持在最佳狀態","examples":[{"en":"Tyre pressure must be optimally maintained for safe high-speed driving.","zh":"為了安全高速駕駛，胎壓必須維持在最佳狀態。"},{"en":"Optimally maintained means kept in the best possible condition.","zh":"optimally maintained 指保持在可能的最佳狀態。"},{"en":"A school computer room works well when machines are optimally maintained.","zh":"當電腦維持在最佳狀態，學校電腦室就運作良好。"},{"en":"At high speeds, small maintenance problems can become serious risks.","zh":"在高速下，小保養問題可以變成嚴重風險。"},{"en":"The phrase stresses careful upkeep at the best level.","zh":"這個短語強調以最佳水平仔細維護。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":14},{"front":"constantly serviced","meaning":"定期保養；持續維修","examples":[{"en":"Cars must be constantly serviced if they travel at very high speeds.","zh":"如果汽車以非常高速度行駛，就必須定期保養。"},{"en":"Constantly serviced means checked and maintained regularly and carefully.","zh":"constantly serviced 指定期而仔細地檢查和維修保養。"},{"en":"A lift in a busy building must be constantly serviced to keep passengers safe.","zh":"繁忙大廈中的升降機必須定期保養，以保障乘客安全。"},{"en":"High-speed use puts stress on machines, so regular servicing reduces failure risk.","zh":"高速使用會對機器造成壓力，因此定期保養降低故障風險。"},{"en":"The phrase stresses repeated maintenance, not one repair.","zh":"這個短語強調反覆維護，而不是一次維修。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":14},{"front":"motor racing","meaning":"賽車運動","examples":[{"en":"Cars in motor racing are carefully serviced for safety.","zh":"賽車運動中的汽車為安全而受到仔細保養。"},{"en":"Motor racing is a sport in which cars or motorcycles compete at high speeds.","zh":"motor racing 指汽車或電單車以高速競賽的運動。"},{"en":"Racing teams check tyres, brakes, engines, and fuel systems before a race.","zh":"賽車隊在比賽前檢查輪胎、煞車、引擎和燃油系統。"},{"en":"Because racing involves extreme speed, maintenance standards are very strict.","zh":"由於賽車涉及極高速度，維修標準非常嚴格。"},{"en":"The phrase refers to competitive high-speed driving.","zh":"這個短語指競技性高速駕駛。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":14},{"front":"travelling at higher speeds","meaning":"以更高速度行駛","examples":[{"en":"Travelling at higher speeds can be extremely risky.","zh":"以更高速度行駛可能極之危險。"},{"en":"Travelling at higher speeds means moving faster than normal or recommended speeds.","zh":"travelling at higher speeds 指比正常或建議速度更快地移動。"},{"en":"A cyclist travelling at higher speeds needs more distance to stop safely.","zh":"以更高速度騎單車的人需要更長距離安全停下。"},{"en":"Higher speeds increase danger because reactions must be faster and mistakes have bigger consequences.","zh":"更高速度增加危險，因為反應必須更快，錯誤後果更大。"},{"en":"The phrase focuses on faster movement and its risks.","zh":"這個短語重點是更快移動及其風險。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":14},{"front":"extremely risky","meaning":"極之危險","examples":[{"en":"Driving above 150 km/h can be extremely risky.","zh":"以超過每小時150公里駕駛可能極之危險。"},{"en":"Extremely risky means very dangerous and likely to cause serious harm if something goes wrong.","zh":"extremely risky 指非常危險，一旦出錯很可能造成嚴重傷害。"},{"en":"Swimming during a storm is extremely risky because lightning and waves can be deadly.","zh":"暴風雨中游泳極之危險，因為閃電和海浪可能致命。"},{"en":"At high speed, a small mechanical failure can become life-threatening.","zh":"在高速下，小機械故障可以變成危及生命。"},{"en":"The phrase strongly warns against danger.","zh":"這個短語強烈警告危險。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":14},{"front":"lead to blowouts","meaning":"導致爆胎","examples":[{"en":"High speeds can lead to blowouts.","zh":"高速可以導致爆胎。"},{"en":"To lead to blowouts means to cause tyres to burst suddenly.","zh":"lead to blowouts 指導致輪胎突然爆裂。"},{"en":"Poor tyre pressure and long high-speed driving can lead to blowouts on highways.","zh":"胎壓不良和長時間高速行駛可以在高速公路上導致爆胎。"},{"en":"A blowout can make a driver lose control within seconds.","zh":"爆胎可以令司機在數秒內失控。"},{"en":"The phrase shows a dangerous result of mechanical stress.","zh":"這個短語顯示機械壓力的危險結果。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":14},{"front":"blowouts","meaning":"爆胎","examples":[{"en":"Blowouts can occur when tyre pressure is not properly maintained.","zh":"當胎壓沒有妥善維持時，可能發生爆胎。"},{"en":"Blowouts are sudden tyre bursts while a vehicle is moving.","zh":"blowouts 指車輛行駛中輪胎突然爆裂。"},{"en":"A blowout on a motorway can be frightening because the car may pull sharply to one side.","zh":"在高速公路上爆胎可能很可怕，因為汽車可能突然偏向一邊。"},{"en":"Proper tyre checks reduce the risk of blowouts during long journeys.","zh":"妥善檢查輪胎可降低長途旅程中爆胎風險。"},{"en":"The word refers to tyre failure, not ordinary slow air loss.","zh":"這個詞指輪胎故障，而不是普通慢性漏氣。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":14},{"front":"physical and mechanical failures","meaning":"物理及機械故障","examples":[{"en":"High-speed driving can cause physical and mechanical failures.","zh":"高速駕駛可以造成物理及機械故障。"},{"en":"Physical and mechanical failures are breakdowns in parts, materials, or machine systems.","zh":"physical and mechanical failures 指部件、材料或機械系統的損壞。"},{"en":"A bus may suffer mechanical failure if its brakes are not maintained.","zh":"如果煞車沒有保養，巴士可能發生機械故障。"},{"en":"At high speeds, failure in a tyre, engine, or steering system can have severe consequences.","zh":"在高速下，輪胎、引擎或轉向系統故障可能造成嚴重後果。"},{"en":"The phrase covers both material damage and machine malfunction.","zh":"這個短語涵蓋材料損壞和機器失靈。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":14},{"front":"have the potential to cause death","meaning":"有可能導致死亡","examples":[{"en":"Mechanical failures at high speed have the potential to cause death.","zh":"高速下的機械故障有可能導致死亡。"},{"en":"To have the potential to cause death means to be capable of causing fatal harm.","zh":"have the potential to cause death 指有能力造成致命傷害。"},{"en":"A gas leak in a kitchen has the potential to cause death if nobody notices it.","zh":"如果沒有人察覺，廚房煤氣洩漏有可能導致死亡。"},{"en":"At high speed, even one equipment failure can become deadly.","zh":"在高速下，即使一項設備故障也可能變得致命。"},{"en":"The phrase warns about serious possible consequences.","zh":"這個短語警告嚴重可能後果。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":14},{"front":"what we might have assumed","meaning":"我們原本可能以為的情況","examples":[{"en":"The situation is different from what we might have assumed.","zh":"情況不同於我們原本可能以為的情況。"},{"en":"What we might have assumed means what we may have believed without checking carefully.","zh":"what we might have assumed 指我們未仔細查核前可能相信的事。"},{"en":"A quiet student may be more confident than we might have assumed.","zh":"安靜的學生可能比我們原本以為更有信心。"},{"en":"When new evidence appears, our first assumptions may need to change.","zh":"當新證據出現，我們最初的假設可能需要改變。"},{"en":"The phrase contrasts initial belief with reality.","zh":"這個短語把初步信念與現實作對比。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":14},{"front":"in theory","meaning":"理論上","examples":[{"en":"There is no official speed limit in theory.","zh":"理論上沒有官方速度限制。"},{"en":"In theory means according to the rule or idea, before considering real conditions.","zh":"in theory 指按照規則或概念而言，未考慮真實情況。"},{"en":"In theory, students can finish the essay in forty minutes, but poor planning makes it harder.","zh":"理論上學生可以在四十分鐘內完成作文，但計劃差會令它更難。"},{"en":"What is true in theory may be different in practice.","zh":"理論上成立的事，實際上可能不同。"},{"en":"The phrase contrasts formal possibility with real-life limits.","zh":"這個短語把正式可能性與現實限制作對比。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":14},{"front":"self-regulate","meaning":"自我規管","examples":[{"en":"Car manufacturers self-regulate for safety reasons.","zh":"汽車製造商基於安全理由自我規管。"},{"en":"To self-regulate means to control one’s own behaviour without being forced by an outside authority.","zh":"self-regulate 指在沒有外部權威強迫下控制自己的行為。"},{"en":"A student self-regulates when he stops using his phone during study time without being told.","zh":"學生不用別人提醒，在溫習時停止使用手機，就是自我規管。"},{"en":"If companies self-regulate seriously, they may prevent the need for stricter laws.","zh":"如果公司認真自我規管，它們可能避免需要更嚴格法律。"},{"en":"The phrase focuses on voluntary control.","zh":"這個短語重點是自願控制。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":15},{"front":"in practice","meaning":"實際上","examples":[{"en":"In practice, a limit has been put in place.","zh":"實際上，一個限制已經被設立。"},{"en":"In practice means in real life or actual use.","zh":"in practice 指在現實生活或實際使用中。"},{"en":"In theory the app saves time, but in practice many users find it confusing.","zh":"理論上這個應用程式省時，但實際上許多用戶覺得困惑。"},{"en":"The phrase shows how reality differs from formal rules or ideas.","zh":"這個短語顯示現實如何不同於正式規則或想法。"},{"en":"It often pairs with in theory.","zh":"它常與 in theory 配對。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":15},{"front":"maximum speed","meaning":"最高速度","examples":[{"en":"Manufacturers limit the maximum speed vehicles can travel at.","zh":"製造商限制車輛可以行駛的最高速度。"},{"en":"Maximum speed is the highest speed a vehicle can reach or is allowed to reach.","zh":"maximum speed 指車輛能達到或被允許達到的最高速度。"},{"en":"An electric scooter may have a maximum speed set by its manufacturer.","zh":"電動滑板車可能有由製造商設定的最高速度。"},{"en":"Limiting maximum speed can reduce the danger of extreme driving.","zh":"限制最高速度可以降低極端駕駛的危險。"},{"en":"The phrase refers to the upper speed limit.","zh":"這個短語指速度上限。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":15},{"front":"be put in place","meaning":"被設立；被實施","examples":[{"en":"A practical limit on maximum speed has been put in place.","zh":"最高速度的實際限制已被設立。"},{"en":"To be put in place means to be established, introduced, or made operational.","zh":"be put in place 指被建立、引入或投入運作。"},{"en":"A new homework system may be put in place after parents complain about confusion.","zh":"家長投訴混亂後，新的功課系統可能被設立。"},{"en":"Once a rule is put in place, people know what standard to follow.","zh":"一旦規則被實施，人們就知道要遵循甚麼標準。"},{"en":"The phrase describes making a system or rule active.","zh":"這個短語描述令制度或規則生效。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":15},{"front":"in addition","meaning":"此外","examples":[{"en":"In addition, few vehicles have the chance to reach very high speeds.","zh":"此外，很少車輛有機會達到非常高速度。"},{"en":"In addition means also or as another point.","zh":"in addition 指此外或另外。"},{"en":"The school offers grammar lessons; in addition, students can join speaking practice.","zh":"學校提供文法課；此外，學生可以參加口語練習。"},{"en":"Writers use this phrase to add another reason or detail.","zh":"作者使用這個短語加入另一個理由或細節。"},{"en":"It helps build an argument step by step.","zh":"它幫助一步步建立論點。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":15},{"front":"be capable of","meaning":"有能力……","examples":[{"en":"Few vehicles are capable of reaching speeds above 150 km/h.","zh":"很少車輛有能力達到每小時150公里以上的速度。"},{"en":"To be capable of doing something means to have the ability to do it.","zh":"be capable of doing something 指有能力做某事。"},{"en":"A strong student may be capable of writing a full essay in thirty minutes.","zh":"能力強的學生可能有能力在三十分鐘內寫完整篇作文。"},{"en":"Capability does not mean the action is always safe or actually done.","zh":"有能力不代表該行動一定安全或實際發生。"},{"en":"The phrase focuses on ability.","zh":"這個短語重點是能力。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":15},{"front":"clock speeds in excess of","meaning":"達到超過……的速度","examples":[{"en":"Some vehicles can clock speeds in excess of 150 km/h.","zh":"一些車輛可以達到超過每小時150公里的速度。"},{"en":"To clock speeds in excess of a number means to reach or record speeds above that number.","zh":"clock speeds in excess of a number 指達到或錄得高於某數字的速度。"},{"en":"A racing bike may clock speeds in excess of 60 km/h on a downhill road.","zh":"賽車單車在下坡路上可能達到超過每小時60公里的速度。"},{"en":"Vehicles capable of such speeds need strong brakes, tyres, and maintenance.","zh":"能達到這種速度的車輛需要強力煞車、輪胎和保養。"},{"en":"The phrase is informal but often used with measured performance.","zh":"這個短語較非正式，但常與可量度表現連用。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":15},{"front":"seldom get the opportunity to","meaning":"很少有機會","examples":[{"en":"Fast cars seldom get the opportunity to build up to such speeds.","zh":"快車很少有機會逐漸加速至這些速度。"},{"en":"Seldom get the opportunity to means rarely have the chance to do something.","zh":"seldom get the opportunity to 指很少有機會做某事。"},{"en":"Students in a crowded class may seldom get the opportunity to speak for long.","zh":"在擠迫班房中，學生很少有機會長時間發言。"},{"en":"Even if a car is powerful, traffic and road space may stop it from reaching top speed.","zh":"即使汽車性能強，交通和道路空間也可能阻止它達到最高速度。"},{"en":"The phrase separates ability from actual chance.","zh":"這個短語把能力與實際機會分開。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":15},{"front":"time and space","meaning":"時間和空間","examples":[{"en":"Drivers need time and space to build up to very high speeds.","zh":"司機需要時間和空間才能逐漸加速至非常高速度。"},{"en":"Time and space means enough duration and physical room for an action to happen safely.","zh":"time and space 指足夠時間和實體空間，讓行動安全發生。"},{"en":"A beginner needs time and space to practise driving without pressure.","zh":"初學者需要時間和空間在沒有壓力下練習駕駛。"},{"en":"Without enough road space, a fast car cannot safely accelerate to extreme speeds.","zh":"沒有足夠道路空間，快車不能安全地加速至極端速度。"},{"en":"The phrase highlights practical conditions.","zh":"這個短語突出實際條件。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":15},{"front":"build up to these speeds","meaning":"逐漸加速至這些速度","examples":[{"en":"Fast cars need space to build up to these speeds.","zh":"快車需要空間逐漸加速至這些速度。"},{"en":"To build up to these speeds means to gradually accelerate until reaching them.","zh":"build up to these speeds 指逐步加速直到達到這些速度。"},{"en":"A runner builds up to full speed after starting slowly.","zh":"跑手慢慢起步後逐漸加速至全速。"},{"en":"Cars need distance to increase speed safely, especially on real roads with other traffic.","zh":"汽車需要距離才能安全增加速度，尤其是在有其他交通的真實道路上。"},{"en":"The phrase describes gradual acceleration, not instant speed.","zh":"這個短語描述逐步加速，而不是瞬間達速。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":15},{"front":"the way someone sees it","meaning":"在某人看來","examples":[{"en":"The way the German government sees it, high-speed drivers should use safer rural motorways.","zh":"在德國政府看來，高速司機應使用較安全的鄉郊高速公路。"},{"en":"The way someone sees it means from that person’s point of view.","zh":"the way someone sees it 指從某人的角度看。"},{"en":"The way my teacher sees it, mistakes are useful if students learn from them.","zh":"在我老師看來，如果學生從錯誤中學習，錯誤就是有用的。"},{"en":"This phrase introduces an opinion or reasoning style.","zh":"這個短語引入某種意見或推理方式。"},{"en":"It helps explain why someone supports a decision.","zh":"它幫助解釋某人為何支持某決定。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":15},{"front":"might as well","meaning":"倒不如；不妨","examples":[{"en":"They might as well be driving that fast on rural motorways.","zh":"他們倒不如在鄉郊高速公路上開得那麼快。"},{"en":"Might as well means it is a reasonable choice because the alternative is no better.","zh":"might as well 指某選擇合理，因為其他選擇沒有更好。"},{"en":"If the bus is delayed for an hour, we might as well walk to the station.","zh":"如果巴士延誤一小時，我們倒不如步行去車站。"},{"en":"If some drivers will speed anyway, officials may prefer they do it where conditions are safer.","zh":"如果一些司機無論如何都會超速，官員可能寧願他們在較安全環境這樣做。"},{"en":"The phrase suggests a practical compromise.","zh":"這個短語暗示實際妥協。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":16},{"front":"rather than","meaning":"而不是","examples":[{"en":"The government would rather drivers speed there rather than in the suburbs.","zh":"政府寧願司機在那裡超速，而不是在市郊超速。"},{"en":"Rather than means instead of; it clearly contrasts two choices.","zh":"rather than 指而不是，清楚對比兩個選擇。"},{"en":"Students should revise a little every day rather than cram the night before the exam.","zh":"學生應每天溫習一點，而不是考試前一晚死記硬背。"},{"en":"The phrase helps show which option is preferred and which is avoided.","zh":"這個短語幫助顯示哪個選項較受偏好，哪個被避免。"},{"en":"It is useful when separating a better choice from a worse one.","zh":"它適合用於分辨較好和較差選擇。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":16},{"front":"in the suburbs","meaning":"在市郊","examples":[{"en":"The government does not want drivers racing in the suburbs.","zh":"政府不希望司機在市郊飆車。"},{"en":"In the suburbs means in residential areas outside the centre of a city.","zh":"in the suburbs 指在城市中心以外的住宅地區。"},{"en":"Families often live in the suburbs because housing may be quieter than downtown.","zh":"家庭常住在市郊，因為住房可能比市中心安靜。"},{"en":"Speeding in the suburbs is dangerous because homes, schools, and pedestrians are nearby.","zh":"在市郊超速很危險，因為附近有住宅、學校和行人。"},{"en":"The phrase describes city-edge residential areas.","zh":"這個短語描述城市邊緣住宅區。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":16},{"front":"let them do it","meaning":"讓他們這樣做","examples":[{"en":"The government appears willing to let them do it in safer areas.","zh":"政府似乎願意讓他們在較安全地區這樣做。"},{"en":"To let them do it means to allow them to do that action.","zh":"let them do it 指容許他們做該行動。"},{"en":"A teacher may let students choose their own books if they still write a report.","zh":"如果學生仍要寫報告，老師可能讓他們自己選書。"},{"en":"Allowing risky behaviour in controlled areas may be safer than letting it happen anywhere.","zh":"在受控地區容許有風險行為，可能比讓它在任何地方發生更安全。"},{"en":"The phrase focuses on permission.","zh":"這個短語重點是准許。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":16},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Students choose the correct heading for each paragraph.","zh":"學生為每段選出正確標題。"},{"en":"To choose the correct heading means to select the title that best matches a paragraph’s main idea.","zh":"choose the correct heading 指選擇最符合段落主旨的標題。"},{"en":"In a reading test, students should read the whole paragraph before choosing the heading.","zh":"在閱讀測驗中，學生應讀完整段後才選標題。"},{"en":"A correct heading captures the main point, not just one small detail.","zh":"正確標題捕捉主要意思，而不是單一小細節。"},{"en":"The phrase is an exam instruction about recognising main ideas.","zh":"這個短語是關於辨認主旨的考試指示。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":16},{"front":"list of headings","meaning":"標題列表","examples":[{"en":"The questions provide a list of headings for the paragraphs.","zh":"題目為各段提供標題列表。"},{"en":"A list of headings is a set of possible paragraph titles in a reading task.","zh":"list of headings 指閱讀任務中一組可能段落標題。"},{"en":"Students should compare all headings before choosing one for a paragraph.","zh":"學生應先比較所有標題，再為段落選一個。"},{"en":"Similar headings can confuse students if they focus only on keywords.","zh":"如果學生只看關鍵詞，相似標題可能令他們混淆。"},{"en":"The phrase refers to answer options for paragraph matching.","zh":"這個短語指段落配對題的答案選項。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":16},{"front":"the fascination explained","meaning":"解釋其吸引力","examples":[{"en":"The heading “The Fascination Explained” refers to why autobahns interest people.","zh":"“The Fascination Explained” 這個標題指解釋高速公路為何吸引人。"},{"en":"The fascination explained means the reason for strong interest is being made clear.","zh":"fascination explained 指強烈興趣背後的原因被說明清楚。"},{"en":"A museum label may explain the fascination with an old object by telling its story.","zh":"博物館標籤可能透過講述故事來解釋舊物件的吸引力。"},{"en":"When a topic seems strange, explaining the fascination helps readers understand its appeal.","zh":"當主題看起來奇怪，解釋其吸引力能幫助讀者理解它為何吸引。"},{"en":"The phrase points to an explanation of attraction.","zh":"這個短語指對吸引力的解釋。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":16},{"front":"speedsters","meaning":"愛高速駕駛的人","examples":[{"en":"Speedsters are drivers who enjoy travelling very fast.","zh":"speedsters 指喜歡非常高速行駛的司機。"},{"en":"Speedsters are people, especially drivers, who like speed and fast movement.","zh":"speedsters 指喜歡速度和快速移動的人，尤其是司機。"},{"en":"Speedsters may prefer sports cars because they enjoy acceleration and performance.","zh":"愛高速駕駛的人可能偏好跑車，因為他們享受加速和性能。"},{"en":"If speedsters drive in crowded areas, they can create serious danger for others.","zh":"如果愛高速駕駛的人在擠迫地區駕駛，他們可能對他人造成嚴重危險。"},{"en":"The word is informal and can sound critical.","zh":"這個詞較非正式，可能帶批評意味。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":16},{"front":"be thwarted by","meaning":"被……阻撓","examples":[{"en":"Speedsters may be thwarted by manufacturers’ speed limits.","zh":"愛高速駕駛的人可能被製造商的速度限制阻撓。"},{"en":"To be thwarted by something means to be prevented or frustrated by it.","zh":"be thwarted by something 指被某事阻止或挫敗。"},{"en":"A student’s plan to study outside may be thwarted by heavy rain.","zh":"學生想在戶外溫習的計劃可能被大雨阻撓。"},{"en":"If car makers limit maximum speed, drivers who want extreme speed may be stopped.","zh":"如果汽車製造商限制最高速度，想極速駕駛的司機可能被阻止。"},{"en":"The phrase shows an obstacle blocking someone’s aim.","zh":"這個短語顯示某障礙阻擋目標。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":16},{"front":"a policy well conceived","meaning":"構思周全的政策","examples":[{"en":"The heading suggests that the policy is well conceived.","zh":"該標題暗示政策構思周全。"},{"en":"A policy well conceived is a policy carefully planned and based on sensible reasoning.","zh":"policy well conceived 指經仔細規劃並基於合理推理的政策。"},{"en":"A school phone policy is well conceived if it protects attention without blocking emergency contact.","zh":"如果學校手機政策保護專注力但不阻礙緊急聯絡，它就是構思周全。"},{"en":"When evidence, behaviour, and risks are considered together, a policy may be well conceived.","zh":"當證據、行為和風險被一同考慮，政策可能構思周全。"},{"en":"The phrase praises the design of a policy.","zh":"這個短語讚揚政策設計。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":16},{"front":"speed limits that are not speed limits","meaning":"並非真正限制的速度限制","examples":[{"en":"The heading refers to recommended limits that are not legally binding.","zh":"該標題指不具法律約束力的建議限制。"},{"en":"Speed limits that are not speed limits are suggested speeds rather than enforceable legal limits.","zh":"speed limits that are not speed limits 指建議速度，而不是可執行的法律限制。"},{"en":"A school may recommend students sleep eight hours, but it cannot legally enforce that recommendation.","zh":"學校可能建議學生睡八小時，但不能以法律執行該建議。"},{"en":"Such limits guide behaviour but do not always create punishment if ignored.","zh":"這類限制引導行為，但忽視它們不一定帶來懲罰。"},{"en":"The phrase is paradoxical and highlights the difference between advice and law.","zh":"這個短語帶矛盾效果，突出建議與法律的差異。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":16},{"front":"recklessness rewarded","meaning":"魯莽行為得到獎賞","examples":[{"en":"The phrase suggests that dangerous behaviour is being rewarded.","zh":"這個短語暗示危險行為正在得到獎賞。"},{"en":"Recklessness rewarded means risky or careless behaviour seems to gain benefits instead of punishment.","zh":"recklessness rewarded 指冒險或粗心行為似乎得到好處而不是懲罰。"},{"en":"If a student never studies but keeps passing by guessing, it may feel like recklessness rewarded.","zh":"如果學生從不溫習卻靠猜測一直合格，就可能像是魯莽得到獎賞。"},{"en":"Policies should avoid making unsafe behaviour look successful.","zh":"政策應避免令不安全行為看起來成功。"},{"en":"The phrase is critical and warns about bad incentives.","zh":"這個短語帶批評意味，警告不良誘因。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":17},{"front":"safety compromised","meaning":"安全受到犧牲","examples":[{"en":"The phrase suggests that safety has been weakened.","zh":"這個短語暗示安全已被削弱。"},{"en":"Safety compromised means safety has been reduced or put at risk.","zh":"safety compromised 指安全被降低或置於風險中。"},{"en":"In a laboratory, safety is compromised if students ignore goggles and gloves.","zh":"在實驗室中，如果學生忽視護目鏡和手套，安全就受到犧牲。"},{"en":"If speed is prioritised over control, road safety may be compromised.","zh":"如果速度優先於控制，道路安全可能受到犧牲。"},{"en":"The phrase warns that protection has been sacrificed.","zh":"這個短語警告保護已被犧牲。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":17},{"front":"not only factor","meaning":"並非唯一因素","examples":[{"en":"Safety is not the only factor driving speed regulation.","zh":"安全並非推動速度規管的唯一因素。"},{"en":"Not the only factor means other causes or considerations also matter.","zh":"not the only factor 指其他原因或考慮也重要。"},{"en":"Price is not the only factor when families choose a school; location and teaching quality matter too.","zh":"家庭選學校時，價格並非唯一因素；位置和教學質素也重要。"},{"en":"Speed rules may be shaped by safety, pollution, noise, and traffic flow together.","zh":"速度規則可能同時由安全、污染、噪音和車流塑造。"},{"en":"The phrase prevents an over-simple explanation.","zh":"這個短語防止過度簡化解釋。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":17},{"front":"speed regulators","meaning":"速度規管者","examples":[{"en":"Speed regulators impose limits for safety, pollution and noise reasons.","zh":"速度規管者基於安全、污染和噪音原因實施限制。"},{"en":"Speed regulators are authorities, rules, or systems that control vehicle speed.","zh":"speed regulators 指控制車速的當局、規則或制度。"},{"en":"A city transport department can act as a speed regulator by setting limits near schools.","zh":"城市交通部門可以透過在學校附近設定限速來充當速度規管者。"},{"en":"Regulators use evidence to decide where drivers must slow down.","zh":"規管者使用證據決定司機在哪裡必須減速。"},{"en":"The phrase refers to those or what controls speed.","zh":"這個短語指控制速度的人或制度。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":17},{"front":"the longest motorways examined","meaning":"審視最長的高速公路","examples":[{"en":"The heading refers to comparing motorway systems by length.","zh":"該標題指按長度比較高速公路系統。"},{"en":"The longest motorways examined means the road systems being compared for total length.","zh":"longest motorways examined 指被拿來比較總長度的道路系統。"},{"en":"A geography class may examine the longest rivers before discussing why length is not the only important feature.","zh":"地理課可能先審視最長河流，再討論為何長度不是唯一重要特色。"},{"en":"Comparing length can give context, but it may not explain public fascination.","zh":"比較長度可以提供背景，但未必解釋公眾着迷原因。"},{"en":"The phrase points to a ranking or comparison task.","zh":"這個短語指排名或比較任務。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":17},{"front":"German road regulations","meaning":"德國道路規例","examples":[{"en":"German road regulations include recommended and hard speed limits.","zh":"德國道路規例包括建議速度限制和硬性速度限制。"},{"en":"German road regulations are the rules that govern how vehicles use roads in Germany.","zh":"German road regulations 指管理車輛如何使用德國道路的規則。"},{"en":"Road regulations may cover speed, vehicle weight, trailers, weather, and repairs.","zh":"道路規例可能涵蓋速度、車重、拖架、天氣和維修。"},{"en":"Clear regulations help drivers know when freedom ends and legal limits begin.","zh":"清晰規例幫助司機知道自由何時結束、法律限制何時開始。"},{"en":"The phrase refers to official road rules.","zh":"這個短語指官方道路規則。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":17},{"front":"state that","meaning":"說明；規定","examples":[{"en":"The question asks what German road regulations state.","zh":"題目問德國道路規例說明甚麼。"},{"en":"To state that means to say something clearly and officially.","zh":"state that 指清楚而正式地說明某事。"},{"en":"The notice states that students must arrive before 8:30.","zh":"告示規定學生必須在八點半前到達。"},{"en":"Rules are easier to follow when they state requirements clearly.","zh":"當規則清楚說明要求，人們更容易遵守。"},{"en":"The phrase introduces what a rule, document, or person says.","zh":"這個短語引入規則、文件或某人所說內容。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":17},{"front":"must adhere to","meaning":"必須遵守","examples":[{"en":"Some vehicles must adhere to strict speed limits.","zh":"一些車輛必須遵守嚴格速度限制。"},{"en":"Must adhere to means must follow a rule or standard carefully.","zh":"must adhere to 指必須仔細遵守規則或標準。"},{"en":"Students must adhere to the word limit in a writing exam.","zh":"學生在寫作考試中必須遵守字數限制。"},{"en":"If heavy vehicles must adhere to lower limits, the law treats them differently for safety.","zh":"如果重型車輛必須遵守較低限制，法律就是基於安全而不同對待它們。"},{"en":"The phrase expresses obligation.","zh":"這個短語表達義務。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":17},{"front":"without prior approval","meaning":"未經事先批准","examples":[{"en":"Some trailer-carrying cars must not exceed 80 km/h without prior approval.","zh":"一些拖着拖架的汽車未經事先批准不得超過每小時80公里。"},{"en":"Without prior approval means without permission given before the action happens.","zh":"without prior approval 指沒有在行動發生前取得許可。"},{"en":"Students should not leave a school trip without prior approval from a teacher.","zh":"學生未經老師事先批准，不應離開學校旅行隊伍。"},{"en":"Prior approval allows authorities to check whether special conditions are safe.","zh":"事先批准讓當局檢查特殊情況是否安全。"},{"en":"The phrase stresses permission before action, not after.","zh":"這個短語強調行動前的許可，而不是事後批准。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":17},{"front":"special motorway speed limits","meaning":"特別高速公路速度限制","examples":[{"en":"Special motorway speed limits apply in certain conditions.","zh":"特別高速公路速度限制適用於某些情況。"},{"en":"Special motorway speed limits are extra or different speed rules used for particular situations.","zh":"special motorway speed limits 指針對特定情況使用的額外或不同速度規則。"},{"en":"A motorway may have special speed limits during fog, repairs, or heavy traffic.","zh":"高速公路在有霧、維修或交通繁忙期間可能有特別速度限制。"},{"en":"Special limits respond to risks that normal limits may not cover.","zh":"特別限制回應正常限制未必涵蓋的風險。"},{"en":"The phrase refers to situation-specific speed control.","zh":"這個短語指特定情況下的速度控制。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":17},{"front":"difficult driving conditions","meaning":"困難駕駛情況","examples":[{"en":"Special speed limits may be imposed in difficult driving conditions.","zh":"在困難駕駛情況下，可能實施特別速度限制。"},{"en":"Difficult driving conditions are road, weather, or traffic situations that make driving harder or less safe.","zh":"difficult driving conditions 指令駕駛更困難或較不安全的道路、天氣或交通情況。"},{"en":"Heavy rain, fog, snow, and roadworks can create difficult driving conditions.","zh":"大雨、霧、雪和道路工程都可以造成困難駕駛情況。"},{"en":"When conditions are difficult, lower speeds give drivers more time to react.","zh":"當情況困難，較低速度給司機更多反應時間。"},{"en":"The phrase explains why normal speed may become unsafe.","zh":"這個短語解釋為何正常速度可能變得不安全。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":17},{"front":"provided they are not","meaning":"只要它們並非……","examples":[{"en":"Some vehicles can travel freely, provided they are not towing trailers.","zh":"一些車輛可以自由行駛，只要它們並非拖着拖架。"},{"en":"Provided they are not means only if they are not in that condition.","zh":"provided they are not 指只有在它們不處於該情況時。"},{"en":"Students may join the trip, provided they are not missing required forms.","zh":"學生可以參加旅行，只要他們沒有欠交必要表格。"},{"en":"The phrase sets a condition that must be absent for permission to apply.","zh":"這個短語設定某條件必須不存在，許可才適用。"},{"en":"It is a formal way to say as long as they are not.","zh":"它是 as long as they are not 的正式說法。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":18},{"front":"towing a trailer","meaning":"拖着拖架","examples":[{"en":"Vehicles towing a trailer face stricter rules.","zh":"拖着拖架的車輛面對更嚴格規則。"},{"en":"Towing a trailer means pulling an attached trailer behind a vehicle.","zh":"towing a trailer 指在車輛後方拉着連接的拖架。"},{"en":"A car towing a trailer may need more distance to turn, brake, and accelerate.","zh":"拖着拖架的汽車可能需要更長距離轉彎、煞車和加速。"},{"en":"Because towing changes vehicle control, speed restrictions often become stricter.","zh":"因為拖架改變車輛控制，速度限制通常會更嚴格。"},{"en":"The phrase describes a vehicle condition that affects safety.","zh":"這個短語描述影響安全的車輛狀況。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":18},{"front":"enforceable in law","meaning":"可依法執行","examples":[{"en":"Some speed limits are enforceable in law.","zh":"一些速度限制可依法執行。"},{"en":"Enforceable in law means a rule can be legally applied and punished if broken.","zh":"enforceable in law 指規則可依法實施，違反時可受懲罰。"},{"en":"A written contract is enforceable in law if courts can require people to follow it.","zh":"如果法院可以要求人們遵守，書面合約就是可依法執行。"},{"en":"If a speed limit is enforceable, police can fine drivers who exceed it.","zh":"如果速度限制可依法執行，警方可以罰超速司機。"},{"en":"The phrase contrasts legal rules with advice.","zh":"這個短語把法律規則與建議作對比。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":18},{"front":"stretches of motorway which need work","meaning":"需要維修的高速公路路段","examples":[{"en":"Speed limits may apply on stretches of motorway which need work.","zh":"速度限制可能適用於需要維修的高速公路路段。"},{"en":"Stretches of motorway which need work are road sections requiring repair or maintenance.","zh":"stretches of motorway which need work 指需要修理或保養的道路段落。"},{"en":"A lane with broken surface or damaged barriers may need work before normal speed is safe.","zh":"路面破損或護欄損壞的行車線，可能需要維修後才適合正常速度。"},{"en":"Repair zones often require lower speed because workers and equipment are nearby.","zh":"維修區通常需要較低速度，因為附近有工人和設備。"},{"en":"The phrase refers to motorway sections needing attention.","zh":"這個短語指需要處理的高速公路路段。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":18},{"front":"no upper speed limit","meaning":"沒有最高速度限制","examples":[{"en":"Some sections have no upper speed limit for certain vehicles.","zh":"一些路段對某些車輛沒有最高速度限制。"},{"en":"No upper speed limit means no legal maximum speed above which a driver is automatically breaking the rule.","zh":"no upper speed limit 指沒有一個法律最高速度，超過它就自動違規。"},{"en":"A test track may have no upper speed limit during controlled experiments.","zh":"測試跑道在受控實驗期間可能沒有最高速度限制。"},{"en":"No upper limit does not mean every speed is wise or safe.","zh":"沒有最高限制不代表任何速度都明智或安全。"},{"en":"The phrase focuses on the absence of a maximum legal limit.","zh":"這個短語重點是沒有法律最高限制。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":18},{"front":"for some vehicles","meaning":"對某些車輛而言","examples":[{"en":"The unrestricted sections apply only to some vehicles.","zh":"沒有限制路段只對某些車輛適用。"},{"en":"For some vehicles means the rule applies to certain vehicle types, not all of them.","zh":"for some vehicles 指規則適用於某些車輛類型，而不是全部。"},{"en":"A bridge may be open for some vehicles but closed to heavy trucks.","zh":"一座橋可能對某些車輛開放，但禁止重型貨車通行。"},{"en":"Different vehicle types need different rules because weight, control, and passenger risk differ.","zh":"不同車輛類型需要不同規則，因為重量、控制和乘客風險不同。"},{"en":"The phrase limits the scope of a rule.","zh":"這個短語限制規則適用範圍。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":18},{"front":"volume of traffic","meaning":"交通流量","examples":[{"en":"The unrestricted sections do not see the highest volume of traffic.","zh":"沒有限速路段並沒有最高交通流量。"},{"en":"Volume of traffic means the amount of vehicles using a road or area.","zh":"volume of traffic 指使用某道路或地區的車輛數量。"},{"en":"A city tunnel may have a high volume of traffic during rush hour.","zh":"城市隧道在繁忙時間可能有高交通流量。"},{"en":"Roads with lower traffic volume usually have fewer vehicle interactions.","zh":"交通流量較低的道路通常車輛互動較少。"},{"en":"The phrase measures how busy a route is.","zh":"這個短語量度路線有多繁忙。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":18},{"front":"as a whole","meaning":"整體而言","examples":[{"en":"The unrestricted parts are only one part of the system as a whole.","zh":"沒有限速部分只是整個系統的一部分。"},{"en":"As a whole means considered together as one complete system or group.","zh":"as a whole 指作為一個完整系統或群體來整體考慮。"},{"en":"A student’s progress should be judged as a whole, not only by one bad test.","zh":"學生進步應整體判斷，而不是只看一次差測驗。"},{"en":"Looking at the system as a whole prevents one unusual feature from misleading us.","zh":"整體看系統，可以防止一個不尋常特色誤導我們。"},{"en":"The phrase encourages a broad view.","zh":"這個短語鼓勵廣泛視角。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":18},{"front":"accounting for","meaning":"佔","examples":[{"en":"The section accounts for a small part of overall traffic.","zh":"該部分佔整體交通的一小部分。"},{"en":"Accounting for means making up or representing a certain share of a total.","zh":"accounting for 指構成或代表總數中的某一比例。"},{"en":"Rent may account for half of a student’s monthly spending.","zh":"租金可能佔學生每月開支的一半。"},{"en":"If unrestricted roads account for little traffic, their effect on overall safety may be limited.","zh":"如果沒有限速道路只佔少量交通，其對整體安全的影響可能有限。"},{"en":"The phrase is used for proportions.","zh":"這個短語用於比例。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":18},{"front":"traffic flow","meaning":"車流","examples":[{"en":"Unmarked police cars monitor traffic flow and driver behaviour.","zh":"沒有標記的警車監察車流和司機行為。"},{"en":"Traffic flow is the movement of vehicles along roads.","zh":"traffic flow 指車輛沿道路移動的情況。"},{"en":"Traffic flow slows down when lanes are closed for roadworks.","zh":"當行車線因道路工程而關閉，車流會慢下來。"},{"en":"Smooth traffic flow can reduce sudden braking and lower accident risk.","zh":"順暢車流可以減少突然煞車並降低意外風險。"},{"en":"The phrase focuses on how vehicles move together.","zh":"這個短語重點是車輛如何一起移動。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":18},{"front":"comparatively small amount","meaning":"相對較少的數量","examples":[{"en":"The unrestricted stretches receive a comparatively small amount of traffic.","zh":"沒有限速路段接收相對較少的交通量。"},{"en":"A comparatively small amount means a smaller amount when compared with something else.","zh":"comparatively small amount 指與其他事物相比數量較少。"},{"en":"A quiet library corner may receive a comparatively small number of students.","zh":"安靜的圖書館角落可能有相對較少學生使用。"},{"en":"Compared with busy urban roads, rural motorway sections may carry fewer vehicles.","zh":"與繁忙城市道路相比，鄉郊高速路段可能承載較少車輛。"},{"en":"The phrase expresses relative quantity.","zh":"這個短語表達相對數量。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":18},{"front":"overall traffic volume","meaning":"整體交通流量","examples":[{"en":"Only a small share of overall traffic volume uses unrestricted stretches.","zh":"只有一小部分整體交通流量使用沒有限速路段。"},{"en":"Overall traffic volume is the total amount of traffic across a whole road system or area.","zh":"overall traffic volume 指整個道路系統或地區的總交通量。"},{"en":"City planners study overall traffic volume before building new roads.","zh":"城市規劃者在建新道路前會研究整體交通流量。"},{"en":"If one road carries little of the overall volume, it may not dominate accident statistics.","zh":"如果某道路只承載少部分整體流量，它未必主導意外統計。"},{"en":"The phrase refers to total traffic, not one small section only.","zh":"這個短語指總交通量，而不只是某小路段。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":19},{"front":"to an extent","meaning":"在某程度上","examples":[{"en":"Manufacturers self-regulate to an extent for safety reasons.","zh":"製造商基於安全理由在某程度上自我規管。"},{"en":"To an extent means partly or to a certain degree.","zh":"to an extent 指部分地或在某個程度上。"},{"en":"Homework helps students, to an extent, but too much can create stress.","zh":"功課在某程度上幫助學生，但太多會造成壓力。"},{"en":"The phrase limits a claim so it does not sound absolute.","zh":"這個短語限制聲稱，使其不會聽起來絕對。"},{"en":"It suggests something is true, but not completely.","zh":"它暗示某事是真的，但不是完全如此。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":19},{"front":"when it comes to","meaning":"在……方面","examples":[{"en":"Manufacturers self-regulate when it comes to safety considerations.","zh":"在安全考慮方面，製造商會自我規管。"},{"en":"When it comes to something means regarding that topic or area.","zh":"when it comes to something 指關於某主題或範疇。"},{"en":"When it comes to exams, careful reading is as important as knowledge.","zh":"在考試方面，仔細閱讀與知識同樣重要。"},{"en":"The phrase introduces the specific subject being discussed.","zh":"這個短語引入正在討論的具體主題。"},{"en":"It is common in speaking and writing.","zh":"它常見於口語和寫作。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":19},{"front":"safety considerations","meaning":"安全考慮","examples":[{"en":"Safety considerations influence manufacturers’ speed policies.","zh":"安全考慮影響製造商的速度政策。"},{"en":"Safety considerations are concerns about preventing harm, accidents, or danger.","zh":"safety considerations 指關於防止傷害、意外或危險的考慮。"},{"en":"A school considers safety when deciding whether students can go hiking in bad weather.","zh":"學校決定學生是否可在惡劣天氣行山時，會考慮安全。"},{"en":"If safety considerations are serious, companies may limit freedom or performance.","zh":"如果安全考慮重大，公司可能限制自由或性能。"},{"en":"The phrase refers to safety-related factors in decisions.","zh":"這個短語指決策中的安全相關因素。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":19},{"front":"implement an unusual practice","meaning":"實施一種不尋常做法","examples":[{"en":"The option mentions manufacturers implementing an unusual practice.","zh":"選項提到製造商實施一種不尋常做法。"},{"en":"To implement an unusual practice means to put a non-standard method into use.","zh":"implement an unusual practice 指把一種非標準方法投入使用。"},{"en":"A school may implement an unusual practice by letting students choose their own timetable.","zh":"學校讓學生自行選擇時間表，就是實施一種不尋常做法。"},{"en":"If car makers voluntarily limit speed, that may seem unusual because it reduces performance.","zh":"如果汽車製造商自願限制速度，這可能顯得不尋常，因為它降低性能。"},{"en":"The phrase focuses on putting a special method into action.","zh":"這個短語重點是把特殊方法付諸實行。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":19},{"front":"fuel consumption","meaning":"燃油消耗","examples":[{"en":"The option refers to limiting vehicles’ fuel consumption.","zh":"選項提到限制車輛燃油消耗。"},{"en":"Fuel consumption is the amount of fuel a vehicle uses.","zh":"fuel consumption 指車輛使用的燃油量。"},{"en":"A car with low fuel consumption costs less to drive and produces fewer emissions.","zh":"燃油消耗低的汽車行駛成本較低，排放也較少。"},{"en":"Driving faster usually increases fuel consumption because the engine works harder.","zh":"開得更快通常會增加燃油消耗，因為引擎運作更吃力。"},{"en":"The phrase is common in discussions of cost and pollution.","zh":"這個短語常見於成本和污染討論。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":19},{"front":"regularly service vehicles","meaning":"定期保養車輛","examples":[{"en":"Vehicles need to be regularly serviced for safe high-speed travel.","zh":"車輛需要定期保養，才能安全高速行駛。"},{"en":"To regularly service vehicles means to inspect and maintain them at repeated intervals.","zh":"regularly service vehicles 指按固定間隔檢查和維護車輛。"},{"en":"A bus company regularly services vehicles to check brakes, tyres, lights, and engines.","zh":"巴士公司定期保養車輛，以檢查煞車、輪胎、車燈和引擎。"},{"en":"Regular servicing reduces the chance of breakdowns during travel.","zh":"定期保養可以降低旅途中故障機會。"},{"en":"The phrase stresses planned maintenance.","zh":"這個短語強調有計劃的維護。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":19},{"front":"the writer’s view of","meaning":"作者對……的看法","examples":[{"en":"The question asks about the writer’s view of German speed regulation.","zh":"題目問作者對德國速度規管的看法。"},{"en":"The writer’s view of something is the opinion or attitude expressed by the author.","zh":"writer’s view of something 指作者表達的意見或態度。"},{"en":"In reading tests, students must distinguish the writer’s view from facts reported by others.","zh":"在閱讀測驗中，學生必須區分作者看法和他人報告的事實。"},{"en":"If the writer says the policy makes sense, his view is not simply negative.","zh":"如果作者說政策合理，他的看法就不只是負面。"},{"en":"The phrase focuses on author attitude.","zh":"這個短語重點是作者態度。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":19},{"front":"speed regulation","meaning":"速度規管","examples":[{"en":"The passage evaluates Germany’s approach to speed regulation.","zh":"文章評估德國的速度規管做法。"},{"en":"Speed regulation is the control of how fast vehicles may travel.","zh":"speed regulation 指控制車輛可行駛速度的制度。"},{"en":"Cities use speed regulation near schools, hospitals, and busy shopping streets.","zh":"城市在學校、醫院和繁忙購物街附近使用速度規管。"},{"en":"Regulation can involve legal limits, cameras, police patrols, and vehicle design.","zh":"規管可以包括法律限制、攝影機、警察巡邏和車輛設計。"},{"en":"The phrase refers to systems that manage driving speed.","zh":"這個短語指管理行車速度的系統。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":19},{"front":"irresponsible and reckless","meaning":"不負責任而魯莽","examples":[{"en":"The writer does not present the policy as simply irresponsible and reckless.","zh":"作者沒有把該政策簡單呈現為不負責任而魯莽。"},{"en":"Irresponsible and reckless means careless, dangerous, and not properly considering consequences.","zh":"irresponsible and reckless 指粗心、危險且沒有妥善考慮後果。"},{"en":"Letting children play near traffic without supervision would be irresponsible and reckless.","zh":"讓孩子在沒有監督下於車流附近玩耍，是不負責任而魯莽的。"},{"en":"A policy may look reckless at first, but evidence can show it is more controlled than expected.","zh":"政策起初可能看似魯莽，但證據可以顯示它比預期更受控制。"},{"en":"The phrase is strongly negative.","zh":"這個短語非常負面。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":19},{"front":"initially appear baffling","meaning":"起初看似令人困惑","examples":[{"en":"The German approach may initially appear baffling.","zh":"德國做法起初可能看似令人困惑。"},{"en":"Initially appear baffling means seem confusing or hard to understand at first.","zh":"initially appear baffling 指一開始看起來令人困惑或難以理解。"},{"en":"A grammar rule may initially appear baffling until students see several examples.","zh":"文法規則在學生看過幾個例子前，可能起初令人困惑。"},{"en":"Some policies look strange before their background and limits are explained.","zh":"一些政策在背景和限制被解釋前看起來奇怪。"},{"en":"The phrase contrasts first impression with later understanding.","zh":"這個短語把第一印象與後來理解作對比。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":19},{"front":"on closer inspection","meaning":"經仔細審視後","examples":[{"en":"On closer inspection, the policy makes more sense.","zh":"經仔細審視後，該政策更合理。"},{"en":"On closer inspection means after examining something more carefully.","zh":"on closer inspection 指更仔細檢視某事後。"},{"en":"A student’s answer may look wrong at first, but on closer inspection it shows clever reasoning.","zh":"學生答案初看可能錯，但仔細審視後可見其推理聰明。"},{"en":"Careful examination can reveal details that first impressions miss.","zh":"仔細檢查可以揭示第一印象錯過的細節。"},{"en":"The phrase introduces a revised judgement after deeper study.","zh":"這個短語引入深入研究後的修正判斷。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":20},{"front":"make a lot of sense","meaning":"很合理","examples":[{"en":"The German approach makes a lot of sense on closer inspection.","zh":"經仔細審視後，德國做法很合理。"},{"en":"To make a lot of sense means to be very reasonable or understandable.","zh":"make a lot of sense 指非常合理或容易理解。"},{"en":"Studying a little every day makes a lot of sense before a major exam.","zh":"大考前每天溫習一點很合理。"},{"en":"A policy makes sense when its reasons, evidence, and results fit together.","zh":"當政策的原因、證據和結果互相配合，它就合理。"},{"en":"The phrase expresses strong approval of logic.","zh":"這個短語強烈肯定其邏輯。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":20},{"front":"inadequate in cities","meaning":"在城市中不足夠","examples":[{"en":"The option suggests that the policy is inadequate in cities.","zh":"選項暗示該政策在城市中不足夠。"},{"en":"Inadequate in cities means not good enough for urban areas.","zh":"inadequate in cities 指對城市地區而言不夠好或不足。"},{"en":"A bus service may be inadequate in cities if people wait too long at every stop.","zh":"如果每個站都要等很久，巴士服務在城市中可能不足夠。"},{"en":"City roads have more pedestrians and vehicles, so weak rules may become dangerous there.","zh":"城市道路有更多行人和車輛，因此薄弱規則在那裡可能變得危險。"},{"en":"The phrase criticises effectiveness in urban settings.","zh":"這個短語批評城市環境中的效用。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":20},{"front":"leave a lot to be desired","meaning":"仍有很多不足之處","examples":[{"en":"The option suggests that the policy leaves a lot to be desired.","zh":"選項暗示該政策仍有很多不足之處。"},{"en":"To leave a lot to be desired means to be unsatisfactory and need much improvement.","zh":"leave a lot to be desired 指令人不滿意，並需要大量改善。"},{"en":"A school cafeteria may leave a lot to be desired if food is expensive and unhealthy.","zh":"如果學校飯堂食物昂貴又不健康，就仍有很多不足之處。"},{"en":"This phrase is a polite but clear criticism.","zh":"這個短語是禮貌但清楚的批評。"},{"en":"It suggests something is not good enough.","zh":"它暗示某事物不夠好。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":20},{"front":"over-reliant on","meaning":"過度依賴","examples":[{"en":"The option suggests the system is over-reliant on self-regulation.","zh":"選項暗示該制度過度依賴自我規管。"},{"en":"Over-reliant on something means depending on it too much.","zh":"over-reliant on something 指過分依靠某事。"},{"en":"A student who is over-reliant on translation apps may struggle to write independently.","zh":"過度依賴翻譯應用程式的學生，可能難以獨立寫作。"},{"en":"If a safety system depends too much on companies policing themselves, critics may worry.","zh":"如果安全制度太依靠公司自我監管，批評者可能擔心。"},{"en":"The phrase criticises excessive dependence.","zh":"這個短語批評過度依賴。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":20},{"front":"self-regulation by manufacturers","meaning":"製造商自我規管","examples":[{"en":"The passage discusses self-regulation by manufacturers.","zh":"文章討論製造商自我規管。"},{"en":"Self-regulation by manufacturers means companies control their own products or behaviour without direct legal force.","zh":"self-regulation by manufacturers 指公司在沒有直接法律強制下控制自己的產品或行為。"},{"en":"Food companies may use self-regulation by reducing sugar before laws require it.","zh":"食品公司可能在法律要求前減糖，作為自我規管。"},{"en":"Manufacturer self-regulation can work when companies have strong incentives to protect safety.","zh":"當公司有強大誘因保護安全，製造商自我規管可能有效。"},{"en":"The phrase focuses on voluntary industry control.","zh":"這個短語重點是業界自願控制。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":20},{"front":"complete the sentences","meaning":"完成句子","examples":[{"en":"Students complete the sentences using words from the passage.","zh":"學生使用文章中的字詞完成句子。"},{"en":"To complete the sentences means to fill in missing words so the sentences become whole.","zh":"complete the sentences 指填上缺失字詞，使句子完整。"},{"en":"In reading tests, students should use exact words from the passage when instructed.","zh":"在閱讀測驗中，如有指示，學生應使用文章中的準確字詞。"},{"en":"Grammar matters because the answer must fit the sentence naturally.","zh":"文法很重要，因為答案必須自然配合句子。"},{"en":"The phrase is an exam instruction.","zh":"這個短語是考試指示。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":20},{"front":"no more than three words","meaning":"不超過三個字","examples":[{"en":"Students choose no more than three words from the passage.","zh":"學生從文章中選擇不超過三個字。"},{"en":"No more than three words means one, two, or three words only.","zh":"no more than three words 指只可一個、兩個或三個詞。"},{"en":"If a student writes four words, the answer breaks the instruction even if the idea is correct.","zh":"如果學生寫四個詞，即使意思正確，也違反指示。"},{"en":"Students should count words carefully before writing the final answer.","zh":"學生在寫最終答案前應仔細數詞數。"},{"en":"The phrase sets a strict answer limit.","zh":"這個短語設定嚴格答案限制。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":20},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must come from the passage.","zh":"答案必須從文章中選出。"},{"en":"From the passage means using words or information found in the reading text.","zh":"from the passage 指使用閱讀文本中的字詞或資料。"},{"en":"Students should not use outside knowledge if the answer must come from the passage.","zh":"如果答案必須從文章中來，學生不應使用外部知識。"},{"en":"This instruction keeps answers tied to evidence in the text.","zh":"這個指示讓答案緊扣文本證據。"},{"en":"The phrase tells learners where the answer source must be.","zh":"這個短語告訴學習者答案來源必須在哪裡。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":20},{"front":"cars operating at high speeds","meaning":"高速行駛的汽車","examples":[{"en":"Cars operating at high speeds require careful maintenance.","zh":"高速行駛的汽車需要仔細保養。"},{"en":"Cars operating at high speeds are vehicles travelling very fast, often under greater mechanical stress.","zh":"cars operating at high speeds 指以非常快速度行駛、通常承受較大機械壓力的車輛。"},{"en":"A sports car used on a track is a car operating at high speeds.","zh":"在賽道上使用的跑車就是高速行駛的汽車。"},{"en":"High-speed operation puts more pressure on tyres, brakes, and engines.","zh":"高速運作對輪胎、煞車和引擎施加更多壓力。"},{"en":"The phrase focuses on vehicles in demanding driving conditions.","zh":"這個短語重點是處於高要求駕駛環境中的車輛。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":20},{"front":"maintain optimal tyre pressure","meaning":"維持最佳胎壓","examples":[{"en":"Drivers should maintain optimal tyre pressure at high speeds.","zh":"司機在高速行駛時應維持最佳胎壓。"},{"en":"To maintain optimal tyre pressure means to keep tyre air pressure at the best safe level.","zh":"maintain optimal tyre pressure 指把輪胎氣壓保持在最佳安全水平。"},{"en":"A driver may check tyre pressure at a petrol station before a long trip.","zh":"司機可能在長途旅程前到油站檢查胎壓。"},{"en":"Correct tyre pressure improves control, braking, and tyre life.","zh":"正確胎壓改善控制、煞車和輪胎壽命。"},{"en":"The phrase describes a key maintenance action for safety.","zh":"這個短語描述重要安全保養行動。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":20},{"front":"ensure that","meaning":"確保","examples":[{"en":"Drivers should ensure that the vehicle is serviced regularly.","zh":"司機應確保車輛定期保養。"},{"en":"To ensure that something happens means to make sure it happens.","zh":"ensure that something happens 指確保某事發生。"},{"en":"A teacher should ensure that every student understands the test instructions.","zh":"老師應確保每名學生明白測驗指示。"},{"en":"Ensuring regular servicing reduces the chance of hidden mechanical problems.","zh":"確保定期保養可以降低隱藏機械問題的機會。"},{"en":"The phrase expresses responsibility for a result.","zh":"這個短語表達對結果的責任。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":21},{"front":"be serviced regularly","meaning":"定期保養","examples":[{"en":"A high-speed vehicle should be serviced regularly.","zh":"高速車輛應定期保養。"},{"en":"To be serviced regularly means to be checked and maintained at fixed intervals.","zh":"be serviced regularly 指按固定間隔接受檢查和維護。"},{"en":"School buses should be serviced regularly because many children depend on them.","zh":"校巴應定期保養，因為許多孩子依靠它們。"},{"en":"Regular servicing can find worn brakes or tyres before they fail.","zh":"定期保養可以在煞車或輪胎失效前發現磨損。"},{"en":"The phrase refers to planned maintenance.","zh":"這個短語指有計劃維護。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":21},{"front":"combat the heightened risk of","meaning":"應對……增加的風險","examples":[{"en":"Regular servicing helps combat the heightened risk of failure.","zh":"定期保養有助應對故障增加的風險。"},{"en":"To combat the heightened risk of something means to reduce or fight a greater-than-usual danger.","zh":"combat the heightened risk of something 指減低或對抗高於平常的危險。"},{"en":"Schools may add supervision to combat the heightened risk of accidents during sports day.","zh":"學校可能增加監督，以應對運動會期間意外增加的風險。"},{"en":"High-speed driving increases mechanical stress, so maintenance helps reduce the added danger.","zh":"高速駕駛增加機械壓力，因此保養有助降低額外危險。"},{"en":"The phrase links preventive action with increased risk.","zh":"這個短語把預防行動與增加風險連起來。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":21},{"front":"heightened risk","meaning":"增加了的風險","examples":[{"en":"High-speed driving creates a heightened risk of mechanical failure.","zh":"高速駕駛造成機械故障增加的風險。"},{"en":"Heightened risk means an increased level of danger.","zh":"heightened risk 指危險程度增加。"},{"en":"There is a heightened risk of illness when many students share a small classroom during flu season.","zh":"流感季節中，許多學生共用小課室會有增加了的患病風險。"},{"en":"When risk is heightened, extra precautions become more important.","zh":"當風險增加，額外預防措施變得更重要。"},{"en":"The phrase describes danger that has become greater than normal.","zh":"這個短語描述比正常更高的危險。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":21},{"front":"due to the practice whereby","meaning":"由於……的做法","examples":[{"en":"Few vehicles can exceed 150 km/h due to the practice whereby manufacturers limit top speeds.","zh":"由於製造商限制最高速度的做法，很少車輛可以超過每小時150公里。"},{"en":"Due to the practice whereby means because of the regular method or arrangement by which something is done.","zh":"due to the practice whereby 指由於某種固定做法或安排。"},{"en":"Students finish homework earlier due to the practice whereby teachers post tasks every morning.","zh":"由於老師每天早上發布任務的做法，學生更早完成功課。"},{"en":"If companies follow a speed-limiting practice, fewer vehicles can reach extreme speeds.","zh":"如果公司遵循限制速度的做法，較少車輛能達到極端速度。"},{"en":"The phrase links a result to an established practice.","zh":"這個短語把結果與既定做法連起來。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":21},{"front":"have the capacity to","meaning":"有能力","examples":[{"en":"Few vehicles have the capacity to exceed 150 km/h.","zh":"很少車輛有能力超過每小時150公里。"},{"en":"To have the capacity to do something means to have the ability, power, or resources to do it.","zh":"have the capacity to do something 指有能力、力量或資源去做某事。"},{"en":"A small classroom may not have the capacity to hold fifty students safely.","zh":"小課室可能沒有能力安全容納五十名學生。"},{"en":"A car may have the capacity to go fast, but rules and traffic may prevent it.","zh":"汽車可能有能力開得快，但規則和交通可能阻止它。"},{"en":"The phrase focuses on potential ability.","zh":"這個短語重點是潛在能力。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":21},{"front":"in excess of 150 km/h","meaning":"超過每小時150公里","examples":[{"en":"Few vehicles can travel in excess of 150 km/h.","zh":"很少車輛可以行駛超過每小時150公里。"},{"en":"In excess of 150 km/h means faster than 150 kilometres per hour.","zh":"in excess of 150 km/h 指快過每小時150公里。"},{"en":"A vehicle travelling in excess of the limit may be stopped by police.","zh":"以超過限制速度行駛的車輛可能被警方截停。"},{"en":"Speeds above 150 km/h increase the need for excellent tyres, brakes, and driver control.","zh":"超過每小時150公里的速度提高了對優良輪胎、煞車和司機控制的需求。"},{"en":"The phrase is formal and numerical.","zh":"這個短語較正式，與數字有關。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":21},{"front":"when it comes to vehicles capable of","meaning":"當談到能夠……的車輛時","examples":[{"en":"The question discusses vehicles capable of travelling at very high speeds.","zh":"題目討論能夠以非常高速度行駛的車輛。"},{"en":"When it comes to vehicles capable of doing something means regarding vehicles that have that ability.","zh":"when it comes to vehicles capable of doing something 指當談到具有該能力的車輛時。"},{"en":"When it comes to students capable of advanced work, teachers should give more challenging tasks.","zh":"當談到能做進階作業的學生時，老師應給予更具挑戰的任務。"},{"en":"Vehicles capable of high speed still need safe roads and proper maintenance.","zh":"能高速行駛的車輛仍需要安全道路和妥善保養。"},{"en":"The phrase narrows the topic to a special group with a particular ability.","zh":"這個短語把話題收窄到具有特定能力的群體。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":21},{"front":"be determined to do so","meaning":"決意這樣做","examples":[{"en":"Some drivers are determined to drive at very high speeds.","zh":"一些司機決意以非常高速度駕駛。"},{"en":"To be determined to do so means to be firmly decided to do it.","zh":"be determined to do so 指堅決決定這樣做。"},{"en":"A student determined to improve may practise speaking every day.","zh":"決意進步的學生可能每天練習口語。"},{"en":"If drivers are determined to speed, policy may try to direct them to safer places.","zh":"如果司機決意超速，政策可能嘗試把他們引導到較安全地方。"},{"en":"The phrase suggests strong intention.","zh":"這個短語暗示強烈意圖。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":21},{"front":"drive excessively fast","meaning":"過度高速駕駛","examples":[{"en":"The government would rather drivers drive excessively fast on safer motorway sections.","zh":"政府寧願司機在較安全高速公路路段過度高速駕駛。"},{"en":"To drive excessively fast means to drive faster than is reasonable or safe.","zh":"drive excessively fast 指以超出合理或安全範圍的速度駕駛。"},{"en":"A driver who races past a school at high speed is driving excessively fast.","zh":"在學校旁高速飛馳的司機就是過度高速駕駛。"},{"en":"Excessive speed gives drivers less time to react and makes crashes more severe.","zh":"過度速度令司機反應時間更少，並使撞車更嚴重。"},{"en":"The phrase criticises speed that goes beyond sensible limits.","zh":"這個短語批評超出合理限制的速度。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":21},{"front":"deems safe","meaning":"認為安全","examples":[{"en":"The government prefers drivers to speed on parts of the motorway it deems safe.","zh":"政府較希望司機在它認為安全的高速公路部分超速。"},{"en":"Deems safe means officially or personally considers safe.","zh":"deems safe 指官方或個人認為安全。"},{"en":"A school may allow outdoor games only in areas it deems safe.","zh":"學校可能只容許學生在其認為安全的區域玩戶外遊戲。"},{"en":"Authorities may judge a road safe because it has low traffic and good visibility.","zh":"當局可能因道路交通量低且能見度好而判斷它安全。"},{"en":"The phrase focuses on judgement or assessment.","zh":"這個短語重點是判斷或評估。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":21},{"front":"anywhere else","meaning":"其他任何地方","examples":[{"en":"The government would rather high-speed driving happen there than anywhere else.","zh":"政府寧願高速駕駛在那裡發生，而不是其他任何地方。"},{"en":"Anywhere else means in any other place.","zh":"anywhere else 指任何其他地方。"},{"en":"If students must make noise, a teacher may prefer they do it in the playground rather than anywhere else.","zh":"如果學生一定會吵，老師可能寧願他們在操場吵，而不是其他任何地方。"},{"en":"Choosing one safer place can reduce danger in more crowded places.","zh":"選擇一個較安全地方，可以減少在更擠迫地方的危險。"},{"en":"The phrase contrasts one preferred location with all other locations.","zh":"這個短語把一個偏好地點與所有其他地點作對比。"}],"source":"82 - UNCOVERING THE TRUTH ABOUT GERMANY’S AUTOBAHNS.pdf","sourcePage":22}],"ielts/reading/passage-2/Practice 83":[{"front":"subtitling strategies","meaning":"字幕翻譯策略","examples":[{"en":"The passage explains several subtitling strategies used in movie translation.","zh":"篇章解釋了電影翻譯中使用的幾種字幕翻譯策略。"},{"en":"Subtitling strategies are methods translators use to make spoken dialogue readable on screen.","zh":"字幕翻譯策略是譯者用來把口頭對白變成螢幕文字的方法。"},{"en":"A translator may choose different subtitling strategies when a joke has no direct equivalent.","zh":"當笑話沒有直接對應說法時，譯者可能選擇不同字幕翻譯策略。"},{"en":"Good subtitling strategies help viewers understand meaning without slowing the film down.","zh":"好的字幕翻譯策略幫助觀眾理解意思，而不拖慢電影節奏。"},{"en":"These strategies balance accuracy, timing, space and cultural understanding.","zh":"這些策略平衡準確度、時間、空間和文化理解。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":1},{"front":"movies made in one language","meaning":"以一種語言製作的電影","examples":[{"en":"Movies made in one language may be shown to speakers of another language.","zh":"以一種語言製作的電影可能會放映給另一種語言的使用者觀看。"},{"en":"Movies made in one language are films whose dialogue is originally spoken in a single language.","zh":"以一種語言製作的電影，是指對白原本以單一語言說出的電影。"},{"en":"A Japanese film made in Japanese may need English subtitles for international viewers.","zh":"一部以日語製作的日本電影，可能需要英文字幕給國際觀眾。"},{"en":"When movies cross borders, language differences can limit understanding.","zh":"當電影跨越國界，語言差異會限制理解。"},{"en":"Translation helps movies made in one language reach wider audiences.","zh":"翻譯幫助以一種語言製作的電影接觸更廣泛觀眾。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":1},{"front":"speakers of another language","meaning":"另一種語言的使用者","examples":[{"en":"Subtitling helps speakers of another language understand the movie.","zh":"字幕翻譯幫助另一種語言的使用者理解電影。"},{"en":"Speakers of another language are people who use a different language from the original film.","zh":"另一種語言的使用者，是指使用不同於電影原語言的人。"},{"en":"Spanish subtitles can help speakers of another language follow an English documentary.","zh":"西班牙語字幕可以幫助另一種語言的使用者理解英文紀錄片。"},{"en":"Without translation, these viewers may miss jokes, emotions and plot details.","zh":"沒有翻譯，這些觀眾可能錯過笑話、情感和情節細節。"},{"en":"This phrase focuses on the audience who needs language support.","zh":"這個短語聚焦需要語言支援的觀眾。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":1},{"front":"resolving the language barrier","meaning":"解決語言障礙","examples":[{"en":"Subtitling and dubbing are two methods of resolving the language barrier.","zh":"加字幕和配音是解決語言障礙的兩種方法。"},{"en":"Resolving the language barrier means removing communication problems caused by different languages.","zh":"解決語言障礙，是指消除由不同語言造成的溝通問題。"},{"en":"A school can resolve a language barrier by providing translated notices for parents.","zh":"學校可以透過提供翻譯通告，解決與家長之間的語言障礙。"},{"en":"In films, subtitles and dubbing let viewers understand dialogue they cannot hear directly.","zh":"在電影中，字幕和配音讓觀眾理解自己不能直接聽懂的對白。"},{"en":"This phrase describes solving a problem of comprehension.","zh":"這個短語描述解決理解上的問題。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":1},{"front":"language barrier","meaning":"語言障礙","examples":[{"en":"Movies in foreign languages can create a language barrier.","zh":"外語電影可能造成語言障礙。"},{"en":"A language barrier is a difficulty in communication caused by not sharing the same language.","zh":"語言障礙是因不使用同一語言而造成的溝通困難。"},{"en":"A tourist may face a language barrier when asking for directions abroad.","zh":"旅客在外國問路時可能面對語言障礙。"},{"en":"A language barrier can lead to confusion, mistakes and missed information.","zh":"語言障礙會導致困惑、錯誤和錯過資訊。"},{"en":"Translation reduces the language barrier by making meaning accessible.","zh":"翻譯透過令意思可理解來減少語言障礙。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":1},{"front":"subtitling","meaning":"加字幕；字幕翻譯","examples":[{"en":"Subtitling provides a written translation of the words spoken in a film.","zh":"字幕翻譯提供電影中所說話語的文字翻譯。"},{"en":"Subtitling means adding translated written text to a screen while the original voices remain.","zh":"加字幕是指在保留原聲的同時，在螢幕上加入翻譯文字。"},{"en":"Viewers can watch a Korean drama with subtitling instead of hearing dubbed voices.","zh":"觀眾可以透過字幕觀看韓劇，而不是聽配音。"},{"en":"Subtitling saves time and money because it does not require recording new voices.","zh":"字幕翻譯節省時間和金錢，因為它不需要錄製新聲音。"},{"en":"Good subtitling must be short enough to read quickly.","zh":"好的字幕必須短到足以讓人快速閱讀。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":1},{"front":"dubbing","meaning":"配音","examples":[{"en":"Dubbing records the voices in the target language.","zh":"配音以目標語言錄製聲音。"},{"en":"Dubbing means replacing the original spoken voices with voices recorded in another language.","zh":"配音是指用另一種語言錄製的聲音取代原本口語聲音。"},{"en":"A cartoon may use dubbing so young children can understand without reading subtitles.","zh":"卡通片可能使用配音，讓年幼孩子不用讀字幕也能理解。"},{"en":"Dubbing can feel unnatural if the new voice does not match the actor’s face.","zh":"如果新聲音不配合演員面孔，配音可能感覺不自然。"},{"en":"This method changes the sound of the film more than subtitling does.","zh":"這種方法比字幕更大程度改變電影聲音。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":1},{"front":"written translation","meaning":"文字翻譯","examples":[{"en":"Subtitling is the written translation of the spoken words.","zh":"字幕翻譯是口頭話語的文字翻譯。"},{"en":"Written translation changes spoken or written meaning into another language in text form.","zh":"文字翻譯是把口語或書面意思以文字形式轉成另一語言。"},{"en":"A museum guide may provide written translation beside each exhibit label.","zh":"博物館導覽可能在每個展品標籤旁提供文字翻譯。"},{"en":"In films, written translation must fit both screen space and reading speed.","zh":"在電影中，文字翻譯必須配合螢幕空間和閱讀速度。"},{"en":"This phrase contrasts text-based translation with recorded voice translation.","zh":"這個短語把文字形式翻譯與錄音聲音翻譯作對比。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":1},{"front":"appear discreetly","meaning":"低調地出現；不顯眼地出現","examples":[{"en":"Subtitles usually appear discreetly at the bottom of the screen.","zh":"字幕通常低調地出現在螢幕底部。"},{"en":"To appear discreetly means to be shown in a quiet, unobtrusive way.","zh":"低調地出現，是指以安靜、不礙眼的方式顯示。"},{"en":"A small notice can appear discreetly in the corner of a webpage.","zh":"一個小通知可以不顯眼地出現在網頁角落。"},{"en":"Subtitles appear discreetly so they do not distract viewers from the images.","zh":"字幕低調地出現，使它們不會令觀眾分心而忽略畫面。"},{"en":"This phrase suggests visibility without drawing too much attention.","zh":"這個短語暗示可見但不過分吸引注意。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":1},{"front":"at the bottom of the screen","meaning":"在螢幕底部","examples":[{"en":"Subtitles usually appear at the bottom of the screen.","zh":"字幕通常出現在螢幕底部。"},{"en":"At the bottom of the screen means in the lowest part of what viewers see.","zh":"在螢幕底部，是指在觀眾所見畫面的最下方。"},{"en":"Video controls often appear at the bottom of the screen during playback.","zh":"影片播放時，控制按鈕常出現在螢幕底部。"},{"en":"Subtitles are placed there so they can be read without covering faces.","zh":"字幕放在那裡，使人能閱讀而不遮住臉部。"},{"en":"This phrase describes a common position in visual media.","zh":"這個短語描述視覺媒體中的常見位置。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":1},{"front":"the recording of voices","meaning":"錄製聲音","examples":[{"en":"Dubbing involves the recording of voices in another language.","zh":"配音涉及以另一種語言錄製聲音。"},{"en":"The recording of voices means capturing spoken speech so it can be used later.","zh":"錄製聲音，是指捕捉口語聲音，以便之後使用。"},{"en":"A podcast requires the recording of voices before editing begins.","zh":"播客在剪輯開始前需要錄製聲音。"},{"en":"In dubbing, voice recording must match the timing and emotion of the film.","zh":"在配音中，錄音必須配合電影的時間和情感。"},{"en":"This phrase refers to producing audio, not writing text.","zh":"這個短語指製作音訊，而不是寫文字。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":1},{"front":"target language","meaning":"目標語言","examples":[{"en":"Dubbing is the recording of voices in the target language.","zh":"配音是以目標語言錄製聲音。"},{"en":"The target language is the language into which something is translated.","zh":"目標語言是某內容被翻譯成的語言。"},{"en":"If a French film is translated into English, English is the target language.","zh":"如果一部法語電影被翻譯成英文，英文就是目標語言。"},{"en":"Translators must choose words that sound natural in the target language.","zh":"譯者必須選擇在目標語言中自然的字詞。"},{"en":"This phrase contrasts with the source language, which is the original language.","zh":"這個短語與原文語言相對，原文語言是原本的語言。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":2},{"front":"seemingly more accessible to","meaning":"表面上對……較易接受","examples":[{"en":"Dubbing is seemingly more accessible to movie watchers.","zh":"配音表面上對電影觀眾較易接受。"},{"en":"Seemingly more accessible to someone means appearing easier for that group to use or understand.","zh":"表面上對某人較易接受，是指看起來對該群體更容易使用或理解。"},{"en":"A video with voice explanation is seemingly more accessible to young children than a long article.","zh":"有聲音講解的影片表面上比長文章更容易讓幼童理解。"},{"en":"Something may seem accessible at first but still have hidden problems.","zh":"某事起初可能看似易接受，但仍有隱藏問題。"},{"en":"This phrase suggests an apparent advantage, not necessarily a perfect one.","zh":"這個短語暗示表面優勢，而不一定是完美優勢。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":2},{"front":"movie watchers","meaning":"電影觀眾","examples":[{"en":"Dubbing may seem easier for movie watchers to follow.","zh":"配音對電影觀眾來說可能較容易跟上。"},{"en":"Movie watchers are people who watch films for entertainment, study or interest.","zh":"電影觀眾是為娛樂、學習或興趣觀看電影的人。"},{"en":"Movie watchers may prefer subtitles when they want to hear the actors’ original voices.","zh":"當電影觀眾想聽演員原聲時，可能較喜歡字幕。"},{"en":"If translation is poor, movie watchers may lose interest in the story.","zh":"如果翻譯差劣，電影觀眾可能對故事失去興趣。"},{"en":"This phrase refers to the audience of a film.","zh":"這個短語指電影的觀眾。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":2},{"front":"come with many disadvantages","meaning":"帶來很多缺點","examples":[{"en":"Dubbing comes with many disadvantages.","zh":"配音帶來很多缺點。"},{"en":"To come with many disadvantages means to have several problems together with its benefits.","zh":"帶來很多缺點，是指在有好處的同時也有幾個問題。"},{"en":"Online classes come with many disadvantages if students lack quiet space and stable internet.","zh":"如果學生缺乏安靜空間和穩定網絡，網課會帶來很多缺點。"},{"en":"A method may be convenient but still create cost, quality or timing problems.","zh":"一種方法可能方便，但仍造成成本、質素或時間問題。"},{"en":"This phrase warns that an attractive option has serious drawbacks.","zh":"這個短語提醒人，看似吸引的選項有嚴重缺點。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":2},{"front":"for a start","meaning":"首先","examples":[{"en":"For a start, dubbing is expensive.","zh":"首先，配音很昂貴。"},{"en":"For a start means first of all, when giving the first reason or example.","zh":"首先，是指給出第一個原因或例子時所用的說法。"},{"en":"For a start, the plan is too costly for a small school.","zh":"首先，這項計劃對小學校來說成本太高。"},{"en":"This phrase often begins a list of criticisms or supporting points.","zh":"這個短語常開始一系列批評或支持點。"},{"en":"It tells readers that more reasons may follow.","zh":"它告訴讀者之後可能還有更多理由。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":2},{"front":"hence","meaning":"因此","examples":[{"en":"Dubbing is expensive; hence, it needs a large audience to justify the cost.","zh":"配音很昂貴；因此，它需要大量觀眾來證明成本合理。"},{"en":"Hence means therefore or for this reason.","zh":"因此是指所以或基於這個原因。"},{"en":"The road is closed; hence, students must take another bus route.","zh":"道路封閉；因此，學生必須乘搭另一條巴士路線。"},{"en":"This word links a cause with a logical result.","zh":"這個詞把原因與邏輯結果連接起來。"},{"en":"It is more formal than “so.”","zh":"它比 “so” 更正式。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":2},{"front":"justify the cost","meaning":"證明成本是合理的","examples":[{"en":"A large audience is needed to justify the cost of dubbing.","zh":"需要大量觀眾才能證明配音成本是合理的。"},{"en":"To justify the cost means to make the spending seem reasonable or worthwhile.","zh":"證明成本合理，是指令開支看起來合理或值得。"},{"en":"A school trip must attract enough students to justify the cost of hiring a coach.","zh":"學校旅行必須有足夠學生參加，才能證明租旅遊巴的成本合理。"},{"en":"If few people watch the film, expensive dubbing may not be financially sensible.","zh":"如果很少人觀看電影，昂貴配音在財務上可能不明智。"},{"en":"This phrase connects expense with expected benefit.","zh":"這個短語把開支與預期好處連接起來。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":2},{"front":"carry no guarantee of","meaning":"不能保證有……","examples":[{"en":"Even big films carry no guarantee of commercial success.","zh":"即使大型電影也不能保證有商業成功。"},{"en":"To carry no guarantee of something means not to ensure that result will happen.","zh":"不能保證有某結果，是指不確保該結果會發生。"},{"en":"A famous university degree carries no guarantee of a happy career.","zh":"名牌大學學位不能保證有快樂事業。"},{"en":"Spending more money on a film does not guarantee that audiences will like it.","zh":"在電影上花更多錢，不保證觀眾會喜歡它。"},{"en":"This phrase warns that an expected result is uncertain.","zh":"這個短語提醒人，預期結果並不確定。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":2},{"front":"commercial success","meaning":"商業成功","examples":[{"en":"Even big films may not achieve commercial success.","zh":"即使大型電影也未必取得商業成功。"},{"en":"Commercial success means making money or attracting enough customers in the market.","zh":"商業成功是指在市場上賺錢或吸引足夠顧客。"},{"en":"A film can win awards but still fail to achieve commercial success.","zh":"一部電影可以贏得獎項，但仍未能取得商業成功。"},{"en":"Poor marketing can prevent a good product from becoming commercially successful.","zh":"差劣市場推廣會阻止好產品取得商業成功。"},{"en":"This phrase measures financial performance, not artistic quality alone.","zh":"這個短語衡量財務表現，而不只是藝術質素。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":2},{"front":"in addition","meaning":"此外","examples":[{"en":"In addition, dubbed voices may seem inappropriate to the characters.","zh":"此外，配音聲音可能顯得不適合角色。"},{"en":"In addition means also or as another point.","zh":"此外是指也、另外一點。"},{"en":"The course teaches grammar; in addition, it gives students speaking practice.","zh":"這個課程教授文法；此外，它給學生口語練習。"},{"en":"This phrase adds one more idea to an argument.","zh":"這個短語為論點加入另一個想法。"},{"en":"It is common in formal writing when building a list of reasons.","zh":"它常見於正式寫作中，用來建立一系列理由。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":2},{"front":"dubbed voices","meaning":"配音聲音","examples":[{"en":"The dubbed voices may seem detached from the characters.","zh":"配音聲音可能顯得與角色脫節。"},{"en":"Dubbed voices are recorded voices added in another language to replace the original speech.","zh":"配音聲音是以另一種語言錄製、用來取代原本說話的新聲音。"},{"en":"In a children’s film, dubbed voices must sound lively and natural.","zh":"在兒童電影中，配音聲音必須聽起來生動自然。"},{"en":"Poorly matched dubbed voices can make serious scenes feel funny or strange.","zh":"不配合的配音聲音會令嚴肅場面感覺滑稽或奇怪。"},{"en":"This phrase refers to the new voices heard in a translated film.","zh":"這個短語指翻譯電影中聽到的新聲音。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":2},{"front":"seem detached","meaning":"顯得不貼合；顯得脫節","examples":[{"en":"The dubbed voices may seem detached from the characters.","zh":"配音聲音可能顯得與角色不貼合。"},{"en":"To seem detached means to appear separate, disconnected or not emotionally fitted.","zh":"顯得脫節，是指看起來分離、不連貫或情感上不配合。"},{"en":"A speech can seem detached if the speaker reads without feeling.","zh":"如果講者毫無感情地讀稿，演講可能顯得脫節。"},{"en":"A mismatched voice can make an actor’s face and words feel disconnected.","zh":"不合適的聲音會令演員面孔和說話感覺不連貫。"},{"en":"This phrase describes a lack of natural connection.","zh":"這個短語描述缺乏自然連接。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":3},{"front":"inappropriate to the characters","meaning":"不適合角色","examples":[{"en":"Some dubbed voices may sound inappropriate to the characters.","zh":"有些配音聲音可能聽起來不適合角色。"},{"en":"Inappropriate to the characters means not fitting their age, class, personality or situation.","zh":"不適合角色，是指不符合角色的年齡、階層、性格或處境。"},{"en":"A child character with a deep adult voice may sound inappropriate to the character.","zh":"兒童角色配上低沉成人聲音，可能聽起來不適合角色。"},{"en":"When voices do not match characters, viewers may stop believing the scene.","zh":"當聲音不配合角色，觀眾可能不再相信場景。"},{"en":"This phrase focuses on suitability between sound and role.","zh":"這個短語聚焦聲音與角色之間的合適程度。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":3},{"front":"the absurdity of","meaning":"……的荒謬之處","examples":[{"en":"The absurdity of certain dubbed lines may affect the audience’s appreciation.","zh":"某些配音台詞的荒謬之處可能影響觀眾的欣賞。"},{"en":"The absurdity of something means how ridiculous, unreasonable or laughably wrong it seems.","zh":"某事的荒謬之處，是指它顯得多麼可笑、不合理或錯得令人發笑。"},{"en":"The absurdity of a teacher speaking like a gangster would distract students.","zh":"老師說話像黑幫的荒謬之處，會令學生分心。"},{"en":"If translation sounds absurd, viewers may laugh at the wrong moment.","zh":"如果翻譯聽起來荒謬，觀眾可能在錯誤時刻發笑。"},{"en":"This phrase highlights something so inappropriate that it becomes hard to accept.","zh":"這個短語突出某事不合適得令人難以接受。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":3},{"front":"undereducated American ruffian","meaning":"受教育程度低的美國粗漢","examples":[{"en":"An undereducated American ruffian may sound ridiculous when speaking formal French.","zh":"一個受教育程度低的美國粗漢說正式法語時，可能聽起來很荒謬。"},{"en":"An undereducated American ruffian is a rough, poorly educated American character.","zh":"受教育程度低的美國粗漢，是指粗魯、教育程度低的美國角色。"},{"en":"If such a character suddenly speaks elegant academic language, the voice may feel wrong.","zh":"如果這類角色突然說優雅學術語言，聲音可能感覺不對。"},{"en":"Translation should match a character’s background, not only the dictionary meaning.","zh":"翻譯應配合角色背景，而不只是字典意思。"},{"en":"This phrase shows how social identity matters in dubbing.","zh":"這個短語顯示社會身份在配音中很重要。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":3},{"front":"become too much","meaning":"變得令人難以接受","examples":[{"en":"The mismatch between voice and character can become too much for the audience.","zh":"聲音與角色之間的不配合可能變得令觀眾難以接受。"},{"en":"Become too much means become excessive, annoying or difficult to accept.","zh":"變得令人難以接受，是指變得過度、煩人或難以忍受。"},{"en":"A film with constant loud music may become too much after half an hour.","zh":"一部電影若不斷播放很大聲的音樂，半小時後可能令人難以接受。"},{"en":"If dubbing keeps sounding wrong, viewers may lose patience.","zh":"如果配音一直聽起來不對，觀眾可能失去耐性。"},{"en":"This phrase describes a problem growing beyond tolerance.","zh":"這個短語描述問題增長到超出忍受範圍。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":3},{"front":"affect the audience’s appreciation of","meaning":"影響觀眾對……的欣賞","examples":[{"en":"Poor dubbing can affect the audience’s appreciation of the film.","zh":"差劣配音會影響觀眾對電影的欣賞。"},{"en":"To affect the audience’s appreciation of something means to change how much viewers enjoy or value it.","zh":"影響觀眾對某事的欣賞，是指改變觀眾享受或重視它的程度。"},{"en":"Bad subtitles can affect the audience’s appreciation of a beautiful foreign film.","zh":"差劣字幕會影響觀眾對一部優美外語電影的欣賞。"},{"en":"If translation distracts viewers, they may notice errors more than the story.","zh":"如果翻譯令觀眾分心，他們可能注意錯誤多於故事。"},{"en":"This phrase links technical choices with viewer enjoyment.","zh":"這個短語把技術選擇與觀眾享受連接起來。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":3},{"front":"increasingly rapid turnover rate","meaning":"越來越快的更新速度","examples":[{"en":"Films and TV programmes now have an increasingly rapid turnover rate.","zh":"電影和電視節目現在有越來越快的更新速度。"},{"en":"An increasingly rapid turnover rate means new items replace old ones faster and faster.","zh":"越來越快的更新速度，是指新項目取代舊項目的速度越來越快。"},{"en":"Streaming platforms have a rapid turnover rate when shows appear and disappear every week.","zh":"當節目每星期出現和消失，串流平台就有很快更新速度。"},{"en":"Fast turnover creates pressure for translators to work quickly.","zh":"快速更新會令譯者承受快速工作的壓力。"},{"en":"This phrase describes speed of replacement in media or business.","zh":"這個短語描述媒體或商業中的替換速度。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":3},{"front":"faster and more practical","meaning":"更快且更實用","examples":[{"en":"Subtitling is faster and more practical than dubbing in many situations.","zh":"在很多情況下，字幕翻譯比配音更快且更實用。"},{"en":"Faster and more practical means quicker to complete and easier to use in real conditions.","zh":"更快且更實用，是指完成速度較快，也更容易在實際情況中使用。"},{"en":"Sending an email is faster and more practical than printing letters for every parent.","zh":"發電郵比為每位家長列印信件更快且更實用。"},{"en":"Subtitling can be practical when many programmes need translation quickly.","zh":"當許多節目需要快速翻譯時，字幕翻譯可以很實用。"},{"en":"This phrase compares efficiency and usefulness.","zh":"這個短語比較效率和實用性。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":3},{"front":"in such situations","meaning":"在這類情況下","examples":[{"en":"Subtitling is more practical in such situations.","zh":"在這類情況下，字幕翻譯更實用。"},{"en":"In such situations means in cases like the ones just described.","zh":"在這類情況下，是指在剛才描述的類似個案中。"},{"en":"If students cannot attend school because of storms, online lessons help in such situations.","zh":"如果學生因暴風雨不能到校，在這類情況下網課有幫助。"},{"en":"This phrase refers back to a condition already mentioned.","zh":"這個短語指回已提到的條件。"},{"en":"It helps avoid repeating the full description of the situation.","zh":"它幫助避免重複完整描述該情況。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":3},{"front":"one should not assume","meaning":"不應假設","examples":[{"en":"One should not assume that subtitling is easier than dubbing.","zh":"人們不應假設字幕翻譯比配音容易。"},{"en":"One should not assume means people should not believe something without evidence.","zh":"不應假設，是指人們不應在沒有證據下相信某事。"},{"en":"One should not assume a quiet student understands everything.","zh":"人們不應假設安靜學生甚麼都明白。"},{"en":"Assumptions can be wrong when a task has hidden difficulties.","zh":"當任務有隱藏困難時，假設可能錯。"},{"en":"This phrase warns readers to think more carefully.","zh":"這個短語提醒讀者更仔細思考。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":3},{"front":"requires careful strategies","meaning":"需要仔細的策略","examples":[{"en":"Subtitling requires careful strategies.","zh":"字幕翻譯需要仔細的策略。"},{"en":"Requires careful strategies means needs planned methods because the task is difficult.","zh":"需要仔細策略，是指因任務困難而需要有計劃的方法。"},{"en":"Teaching shy students requires careful strategies, not just more questions.","zh":"教害羞學生需要仔細策略，而不只是問更多問題。"},{"en":"Without careful strategies, subtitles may become too long, unclear or culturally wrong.","zh":"沒有仔細策略，字幕可能太長、不清楚或文化上錯誤。"},{"en":"This phrase shows that success depends on thoughtful planning.","zh":"這個短語顯示成功取決於周詳規劃。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":3},{"front":"outline some of","meaning":"概述其中一些……","examples":[{"en":"The writer outlines some of the strategies used in subtitling.","zh":"作者概述了字幕翻譯中使用的一些策略。"},{"en":"To outline some of something means to give a brief explanation of several examples.","zh":"概述其中一些，是指簡短解釋幾個例子。"},{"en":"A teacher may outline some of the common mistakes before students start writing.","zh":"老師可能在學生開始寫作前，概述一些常見錯誤。"},{"en":"An outline gives the main points without every small detail.","zh":"概述給出主要重點，而不是每個小細節。"},{"en":"This phrase is useful when introducing a list or overview.","zh":"這個短語適合用於引入列表或總覽。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":4},{"front":"a sample movie","meaning":"一部樣本電影","examples":[{"en":"A sample movie is needed to examine subtitling strategies.","zh":"需要一部樣本電影來考察字幕翻譯策略。"},{"en":"A sample movie is one film chosen as an example for study or analysis.","zh":"樣本電影是被選作研究或分析例子的一部電影。"},{"en":"A class may use a sample movie to study how subtitles handle humour.","zh":"課堂可能使用一部樣本電影來研究字幕如何處理幽默。"},{"en":"Using one sample helps researchers look closely at real translation choices.","zh":"使用一個樣本幫助研究人員仔細觀察真實翻譯選擇。"},{"en":"This phrase refers to an example film, not necessarily a famous one.","zh":"這個短語指作為例子的電影，不一定是著名電影。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":4},{"front":"be subtitled into","meaning":"被加上……字幕","examples":[{"en":"The Italian movie was subtitled into English.","zh":"這部意大利電影被加上英文字幕。"},{"en":"To be subtitled into a language means to have written subtitles added in that language.","zh":"被加上某語言字幕，是指加入以該語言寫成的字幕。"},{"en":"A French documentary may be subtitled into Chinese for local students.","zh":"一部法語紀錄片可能為本地學生加上中文字幕。"},{"en":"Subtitling into another language helps new audiences understand the original speech.","zh":"翻譯成另一語言的字幕幫助新觀眾理解原聲對白。"},{"en":"This phrase describes the direction of subtitle translation.","zh":"這個短語描述字幕翻譯的方向。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":4},{"front":"comprehension of subtitles","meaning":"對字幕的理解","examples":[{"en":"Comprehension of subtitles depends partly on cultural knowledge.","zh":"對字幕的理解部分取決於文化知識。"},{"en":"Comprehension of subtitles means understanding the written translation shown on screen.","zh":"對字幕的理解，是指明白螢幕上顯示的文字翻譯。"},{"en":"Viewers may struggle with subtitle comprehension if jokes depend on local customs.","zh":"如果笑話依賴本地習俗，觀眾可能難以理解字幕。"},{"en":"Cultural gaps can make clear grammar still feel confusing.","zh":"文化差距會令文法清楚的字幕仍然令人困惑。"},{"en":"This phrase focuses on whether viewers truly understand subtitles.","zh":"這個短語聚焦觀眾是否真正理解字幕。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":4},{"front":"be affected by","meaning":"受到……影響","examples":[{"en":"Comprehension of subtitles can be affected by cultural differences.","zh":"對字幕的理解會受到文化差異影響。"},{"en":"To be affected by something means to be changed or influenced by it.","zh":"受到某事影響，是指被它改變或左右。"},{"en":"A student’s concentration can be affected by noise outside the classroom.","zh":"學生的專注力可能受到課室外噪音影響。"},{"en":"Translation quality is affected by time limits, culture and word choice.","zh":"翻譯質素受到時間限制、文化和用詞影響。"},{"en":"This phrase connects a result with an influence.","zh":"這個短語把結果與影響因素連接起來。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":4},{"front":"lack of familiarity with","meaning":"對……缺乏熟悉","examples":[{"en":"Viewers may have a lack of familiarity with another culture’s values.","zh":"觀眾可能對另一文化的價值觀缺乏熟悉。"},{"en":"Lack of familiarity with something means not knowing it well enough.","zh":"對某事缺乏熟悉，是指對它認識不夠。"},{"en":"A tourist may struggle because of a lack of familiarity with local transport rules.","zh":"旅客可能因不熟悉本地交通規則而感到困難。"},{"en":"If viewers lack cultural familiarity, they may misunderstand a character’s behaviour.","zh":"如果觀眾缺乏文化熟悉度，可能誤解角色行為。"},{"en":"This phrase explains confusion caused by limited experience.","zh":"這個短語解釋因經驗有限造成的困惑。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":4},{"front":"values and beliefs","meaning":"價值觀和信念","examples":[{"en":"Subtitlers need to understand the values and beliefs of both cultures.","zh":"字幕譯者需要理解兩種文化的價值觀和信念。"},{"en":"Values and beliefs are ideas about what is important, right or normal.","zh":"價值觀和信念，是關於甚麼重要、正確或正常的想法。"},{"en":"Family values and religious beliefs can affect how people understand a film scene.","zh":"家庭價值觀和宗教信念會影響人們如何理解電影場面。"},{"en":"Translators may choose different words when values differ between cultures.","zh":"當文化之間價值觀不同，譯者可能選擇不同字詞。"},{"en":"This phrase refers to deeper cultural ideas, not just customs.","zh":"這個短語指較深層文化想法，而不只是習俗。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":4},{"front":"interactive differences","meaning":"互動方式上的差異","examples":[{"en":"Interactive differences between cultures can affect subtitle comprehension.","zh":"文化之間互動方式上的差異會影響對字幕的理解。"},{"en":"Interactive differences are differences in how people speak, joke, argue or show respect.","zh":"互動方式上的差異，是指人們說話、開玩笑、爭論或表示尊重方式的差異。"},{"en":"In one culture, silence may show respect; in another, it may seem unfriendly.","zh":"在一種文化中，沉默可能表示尊重；在另一種文化中，可能顯得不友善。"},{"en":"If translators miss interactive differences, subtitles may sound rude or unnatural.","zh":"如果譯者忽略互動差異，字幕可能聽起來粗魯或不自然。"},{"en":"This phrase focuses on cultural differences in communication behaviour.","zh":"這個短語聚焦溝通行為中的文化差異。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":4},{"front":"host and viewing cultures","meaning":"原文化與觀眾文化","examples":[{"en":"Subtitlers compare the host and viewing cultures before translating.","zh":"字幕譯者在翻譯前比較原文化與觀眾文化。"},{"en":"Host and viewing cultures are the original culture of the film and the culture of the audience.","zh":"原文化與觀眾文化，是指電影原本的文化和觀眾所屬文化。"},{"en":"An Italian film shown in Hong Kong involves Italian host culture and Hong Kong viewing culture.","zh":"一部在香港放映的意大利電影，涉及意大利原文化和香港觀眾文化。"},{"en":"Comparing both cultures helps translators avoid confusing or misleading subtitles.","zh":"比較兩種文化幫助譯者避免令人困惑或誤導的字幕。"},{"en":"This phrase separates the culture being shown from the culture watching it.","zh":"這個短語把被呈現的文化與觀看它的文化分開。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":4},{"front":"need to be aware of","meaning":"需要意識到……","examples":[{"en":"Subtitlers need to be aware of cultural differences.","zh":"字幕譯者需要意識到文化差異。"},{"en":"To need to be aware of something means to need to notice and understand it.","zh":"需要意識到某事，是指需要注意並理解它。"},{"en":"Teachers need to be aware of students’ anxiety before oral exams.","zh":"老師需要意識到學生在口試前的焦慮。"},{"en":"If translators are aware of cultural gaps, they can choose clearer wording.","zh":"如果譯者意識到文化差距，就能選擇更清楚措辭。"},{"en":"This phrase stresses careful attention to a possible problem.","zh":"這個短語強調對潛在問題的仔細注意。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":4},{"front":"convey the intended meaning","meaning":"傳達原意","examples":[{"en":"Subtitlers must convey the intended meaning clearly.","zh":"字幕譯者必須清楚傳達原意。"},{"en":"To convey the intended meaning means to communicate what the speaker really means.","zh":"傳達原意，是指傳遞說話者真正想表達的意思。"},{"en":"A polite refusal must convey the intended meaning without sounding rude.","zh":"有禮貌的拒絕必須傳達原意，而不顯得粗魯。"},{"en":"If subtitles convey only literal words, the real tone may be lost.","zh":"如果字幕只傳達字面字詞，真正語氣可能會流失。"},{"en":"This phrase focuses on meaning, not word-for-word matching.","zh":"這個短語聚焦意思，而不是逐字對應。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":4},{"front":"before beginning any work","meaning":"在開始任何工作之前","examples":[{"en":"Before beginning any work, subtitlers should conduct a cultural audit.","zh":"在開始任何工作之前，字幕譯者應進行文化審視。"},{"en":"Before beginning any work means before starting the task at all.","zh":"在開始任何工作之前，是指在真正開始任務以前。"},{"en":"Before beginning any work on a project, students should read the instructions carefully.","zh":"在開始任何項目工作之前，學生應仔細閱讀指示。"},{"en":"Preparation at the start can prevent mistakes later.","zh":"起初準備可以防止之後犯錯。"},{"en":"This phrase emphasises early planning before action.","zh":"這個短語強調行動前的早期規劃。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":5},{"front":"cultural audit","meaning":"文化審視；文化審核","examples":[{"en":"A brief cultural audit is necessary before subtitling begins.","zh":"字幕翻譯開始前，簡短文化審視是必要的。"},{"en":"A cultural audit is a careful check of cultural differences that may affect translation.","zh":"文化審視是仔細檢查可能影響翻譯的文化差異。"},{"en":"A company may conduct a cultural audit before launching an advert abroad.","zh":"公司在海外推出廣告前，可能進行文化審核。"},{"en":"Cultural audits help translators notice values, humour and social habits.","zh":"文化審視幫助譯者注意價值觀、幽默和社交習慣。"},{"en":"This phrase refers to preparation, not final translation.","zh":"這個短語指準備工作，而不是最終翻譯。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":5},{"front":"absolutely necessary","meaning":"絕對必要","examples":[{"en":"A cultural audit is absolutely necessary.","zh":"文化審視絕對必要。"},{"en":"Absolutely necessary means completely required and not optional.","zh":"絕對必要，是指完全需要，並非可有可無。"},{"en":"For a hospital, clean water is absolutely necessary.","zh":"對醫院來說，清潔食水絕對必要。"},{"en":"In cross-cultural translation, preparation is necessary because mistakes can change meaning.","zh":"在跨文化翻譯中，準備是必要的，因為錯誤會改變意思。"},{"en":"This phrase gives very strong emphasis to a requirement.","zh":"這個短語非常強烈地強調需要。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":5},{"front":"involving a comparison of","meaning":"涉及對……的比較","examples":[{"en":"The audit involves a comparison of the two cultures.","zh":"這項審視涉及對兩種文化的比較。"},{"en":"Involving a comparison of something means including careful examination of similarities and differences.","zh":"涉及對某事的比較，是指包括仔細考察相似與差異。"},{"en":"A school report may involve a comparison of online and face-to-face lessons.","zh":"學校報告可能涉及對網課和面授課的比較。"},{"en":"Comparing cultures helps identify meanings that cannot be translated directly.","zh":"比較文化有助找出不能直接翻譯的意思。"},{"en":"This phrase describes a method of analysis.","zh":"這個短語描述分析方法。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":5},{"front":"in relation to","meaning":"就……而言；關於","examples":[{"en":"The two cultures are compared in relation to the storyline.","zh":"兩種文化就電影故事情節而言被比較。"},{"en":"In relation to means connected with or considered according to a particular topic.","zh":"就某事而言，是指與某個主題相關或按該主題考慮。"},{"en":"A teacher may discuss vocabulary in relation to the exam question.","zh":"老師可能就考試題目討論詞彙。"},{"en":"Cultural meaning changes depending on the story and situation.","zh":"文化意思會因故事和情境而改變。"},{"en":"This phrase limits the comparison to a relevant context.","zh":"這個短語把比較限制在相關語境中。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":5},{"front":"storyline of the movie","meaning":"電影故事情節","examples":[{"en":"The cultural audit considers the storyline of the movie.","zh":"文化審視會考慮電影故事情節。"},{"en":"The storyline of the movie is the sequence of events and conflicts in the film.","zh":"電影故事情節是電影中事件和衝突的次序。"},{"en":"A love story and a crime story may require different translation choices.","zh":"愛情故事和犯罪故事可能需要不同翻譯選擇。"},{"en":"Understanding the storyline helps translators know which words carry emotional weight.","zh":"理解故事情節幫助譯者知道哪些字詞承載情感重量。"},{"en":"This phrase refers to the film’s plot and development.","zh":"這個短語指電影的情節和發展。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":5},{"front":"be set in","meaning":"以……為背景","examples":[{"en":"The movie is set in the late 1960s.","zh":"這部電影以 1960 年代末為背景。"},{"en":"To be set in a time or place means the story happens there or then.","zh":"以某時某地為背景，是指故事發生在那個時間或地方。"},{"en":"A novel set in a small village may show rural customs clearly.","zh":"以小村莊為背景的小說可能清楚展示鄉村習俗。"},{"en":"The setting affects language, clothing, values and social behaviour.","zh":"背景會影響語言、服裝、價值觀和社會行為。"},{"en":"This phrase gives the background of a story.","zh":"這個短語給出故事背景。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":5},{"front":"the late 1960s","meaning":"1960年代末","examples":[{"en":"The movie is set in the late 1960s.","zh":"這部電影以 1960 年代末為背景。"},{"en":"The late 1960s means the final years of the 1960s, usually around 1967 to 1969.","zh":"1960 年代末，是指 1960 年代最後幾年，通常約為 1967 至 1969 年。"},{"en":"A film set in the late 1960s may show different clothes, music and social values.","zh":"以 1960 年代末為背景的電影，可能展示不同服裝、音樂和社會價值。"},{"en":"Historical setting affects how characters speak and what they believe.","zh":"歷史背景會影響角色如何說話和相信甚麼。"},{"en":"This phrase gives a specific period in modern history.","zh":"這個短語給出現代歷史中的特定時期。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":5},{"front":"at a time when","meaning":"在……的時候","examples":[{"en":"The film is set at a time when American materialism was very pronounced.","zh":"這部電影以美國物質主義非常明顯的時期為背景。"},{"en":"At a time when means during a period in which something was happening.","zh":"在……的時候，是指在某事正在發生的時期。"},{"en":"The story takes place at a time when many families were moving to cities.","zh":"故事發生在許多家庭搬到城市的時候。"},{"en":"This phrase connects a story with its wider historical background.","zh":"這個短語把故事與更廣泛歷史背景連接起來。"},{"en":"It helps explain why characters behave as they do.","zh":"它幫助解釋角色為何如此行動。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":5},{"front":"wealth and materialism","meaning":"財富與物質主義","examples":[{"en":"The movie contrasts American wealth and materialism with Italian village poverty.","zh":"電影把美國財富與物質主義和意大利鄉村貧窮作對比。"},{"en":"Wealth and materialism mean money, possessions and strong concern with material things.","zh":"財富與物質主義，是指金錢、財物，以及對物質東西的強烈重視。"},{"en":"A story about luxury shopping may criticise wealth and materialism.","zh":"一個關於奢侈購物的故事可能批評財富與物質主義。"},{"en":"Materialism can make characters value money more than relationships.","zh":"物質主義會令角色比人際關係更重視金錢。"},{"en":"This phrase often contrasts rich lifestyles with simpler human values.","zh":"這個短語常把富裕生活方式與較簡樸的人性價值作對比。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":5},{"front":"be very pronounced","meaning":"非常明顯","examples":[{"en":"The wealth and materialism of American society were very pronounced.","zh":"美國社會的財富和物質主義非常明顯。"},{"en":"To be very pronounced means to be very clear, strong or noticeable.","zh":"非常明顯，是指非常清楚、強烈或容易注意到。"},{"en":"The difference between beginner and advanced students is very pronounced in a speaking class.","zh":"在口語班中，初學者和進階學生之間的差異非常明顯。"},{"en":"A pronounced contrast helps viewers understand the film’s message.","zh":"明顯對比幫助觀眾理解電影訊息。"},{"en":"This phrase describes something that stands out clearly.","zh":"這個短語描述清楚突出的事物。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":5},{"front":"in contrast to","meaning":"與……形成對比","examples":[{"en":"American wealth is shown in contrast to Italian village poverty.","zh":"美國財富與意大利鄉村貧窮形成對比。"},{"en":"In contrast to means compared with something very different.","zh":"與某事形成對比，是指與非常不同的事物比較。"},{"en":"In contrast to noisy city life, the village is quiet and slow.","zh":"與嘈雜城市生活形成對比，鄉村安靜而緩慢。"},{"en":"Contrasts help audiences see differences in values and lifestyles.","zh":"對比幫助觀眾看見價值觀和生活方式差異。"},{"en":"This phrase introduces a clear opposition between two things.","zh":"這個短語引入兩件事之間的清楚對立。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":6},{"front":"relative poverty","meaning":"相對貧窮","examples":[{"en":"The movie shows the relative poverty of Italian village life.","zh":"電影展示意大利鄉村生活的相對貧窮。"},{"en":"Relative poverty means being poor compared with another person, group or society.","zh":"相對貧窮，是指與另一個人、群體或社會相比較貧窮。"},{"en":"A family may feel relative poverty when neighbours can afford many things they cannot.","zh":"當鄰居能負擔許多自己不能負擔的東西，家庭可能感到相對貧窮。"},{"en":"In the film, poverty is clearer because it is compared with American wealth.","zh":"在電影中，貧窮因與美國財富比較而更清楚。"},{"en":"This phrase depends on comparison, not only absolute need.","zh":"這個短語取決於比較，而不只是絕對需要。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":6},{"front":"Italian village life","meaning":"意大利鄉村生活","examples":[{"en":"The film contrasts American wealth with Italian village life.","zh":"電影把美國財富與意大利鄉村生活作對比。"},{"en":"Italian village life refers to daily life in a small Italian rural community.","zh":"意大利鄉村生活，是指意大利小型鄉村社區中的日常生活。"},{"en":"Italian village life may involve close neighbours, local traditions and slower routines.","zh":"意大利鄉村生活可能涉及親密鄰里、本地傳統和較慢節奏。"},{"en":"Showing village life can highlight community warmth and material poverty.","zh":"展示鄉村生活可以突出社區溫情和物質貧窮。"},{"en":"This phrase gives the social setting of the film.","zh":"這個短語給出電影的社會背景。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":6},{"front":"the plot tells the story of","meaning":"情節講述……的故事","examples":[{"en":"The plot tells the story of a poor couple who gamble for money.","zh":"情節講述一對貧窮夫婦為金錢賭博的故事。"},{"en":"The plot tells the story of means the main events are about this person or situation.","zh":"情節講述某事的故事，是指主要事件圍繞該人物或情況。"},{"en":"The plot tells the story of a student trying to save a closing library.","zh":"情節講述一名學生嘗試拯救即將關閉圖書館的故事。"},{"en":"This phrase introduces what a film or book is mainly about.","zh":"這個短語引入電影或書主要關於甚麼。"},{"en":"It helps summarise a storyline simply.","zh":"它幫助簡單概括故事情節。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":6},{"front":"dream of winning","meaning":"夢想贏得","examples":[{"en":"The poor couple dream of winning large sums of money.","zh":"這對貧窮夫婦夢想贏得大筆金錢。"},{"en":"To dream of winning means to strongly hope to win something.","zh":"夢想贏得，是指強烈希望贏得某物。"},{"en":"A student may dream of winning a scholarship to study abroad.","zh":"學生可能夢想贏得獎學金到海外升學。"},{"en":"Dreams of winning money can push people to take risks.","zh":"夢想贏得金錢會推動人冒險。"},{"en":"This phrase shows desire, hope and imagined success.","zh":"這個短語顯示渴望、希望和想像中的成功。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":6},{"front":"large sums of money","meaning":"大筆金錢","examples":[{"en":"The couple hope to win large sums of money.","zh":"這對夫婦希望贏得大筆金錢。"},{"en":"Large sums of money means very big amounts of money.","zh":"大筆金錢是指非常大的金額。"},{"en":"A hospital needs large sums of money to buy advanced medical equipment.","zh":"醫院需要大筆金錢購買先進醫療設備。"},{"en":"When people hope for large sums quickly, they may be tempted to gamble.","zh":"當人們希望快速得到大筆金錢，可能被賭博誘惑。"},{"en":"This phrase emphasises the size of the amount.","zh":"這個短語強調金額之大。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":6},{"front":"by gambling","meaning":"透過賭博","examples":[{"en":"The couple hope to become rich by gambling.","zh":"這對夫婦希望透過賭博致富。"},{"en":"By gambling means through betting money on games of chance.","zh":"透過賭博，是指透過在機會遊戲中下注金錢。"},{"en":"Some people lose savings by gambling instead of earning money steadily.","zh":"有些人透過賭博失去積蓄，而不是穩定賺錢。"},{"en":"Gambling can create hope, but it can also increase poverty and debt.","zh":"賭博可以帶來希望，但也可以增加貧窮和債務。"},{"en":"This phrase explains the method used to try to gain money.","zh":"這個短語解釋試圖獲得金錢的方法。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":6},{"front":"a card game","meaning":"紙牌遊戲","examples":[{"en":"The couple gamble in a card game against a wealthy woman.","zh":"這對夫婦在紙牌遊戲中與一位富有女士賭博。"},{"en":"A card game is a game played with a deck of cards.","zh":"紙牌遊戲是使用一副牌玩的遊戲。"},{"en":"Families may play a card game at home for fun without betting money.","zh":"家庭可能在家玩紙牌遊戲作娛樂，而不下注金錢。"},{"en":"If money is involved, a simple card game can become gambling.","zh":"如果涉及金錢，簡單紙牌遊戲就可以變成賭博。"},{"en":"This phrase names the activity at the centre of the film’s conflict.","zh":"這個短語命名電影衝突核心的活動。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":6},{"front":"a wealthy elderly American woman","meaning":"一位富有的美國老婦","examples":[{"en":"The couple play against a wealthy elderly American woman.","zh":"這對夫婦與一位富有的美國老婦對賭。"},{"en":"A wealthy elderly American woman is an older woman from America with a lot of money.","zh":"一位富有的美國老婦，是指來自美國且擁有很多金錢的年長女士。"},{"en":"In a film, such a character may represent power, comfort and material wealth.","zh":"在電影中，這類角色可能代表權力、舒適和物質財富。"},{"en":"Her wealth contrasts strongly with the poverty of the village couple.","zh":"她的財富與鄉村夫婦的貧窮形成強烈對比。"},{"en":"This phrase identifies a character through age, nationality and social status.","zh":"這個短語透過年齡、國籍和社會地位識別角色。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":6},{"front":"just for that purpose","meaning":"正是為了那個目的","examples":[{"en":"The woman occasionally visits Italy just for that purpose.","zh":"那位女士偶爾到訪意大利，正是為了那個目的。"},{"en":"Just for that purpose means only or specifically for that reason.","zh":"正是為了那個目的，是指只為或特別為那個原因。"},{"en":"A teacher may open the classroom early just for that purpose: helping students revise.","zh":"老師可能提早開課室，正是為了幫學生溫習。"},{"en":"The phrase shows that the action has one clear aim.","zh":"這個短語顯示行動有一個清楚目標。"},{"en":"It often emphasises intention and focus.","zh":"它常強調意圖和焦點。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":6},{"front":"final thematic assertion","meaning":"最終的主題主張","examples":[{"en":"The final thematic assertion is that money is not the most important thing.","zh":"最終的主題主張是金錢不是最重要的東西。"},{"en":"A final thematic assertion is the main message a story leaves at the end.","zh":"最終的主題主張，是故事在結尾留下的主要訊息。"},{"en":"A film may end with the assertion that family matters more than success.","zh":"電影可能以「家庭比成功更重要」這一主張結束。"},{"en":"Endings often clarify what the whole story has been trying to say.","zh":"結局常澄清整個故事一直想說甚麼。"},{"en":"This phrase refers to the final statement of meaning, not just the final event.","zh":"這個短語指最終的意義陳述，而不只是最後事件。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":6},{"front":"there are more important things than","meaning":"有比……更重要的東西","examples":[{"en":"The film suggests that there are more important things than money.","zh":"電影暗示有比金錢更重要的東西。"},{"en":"There are more important things than something means another value matters more.","zh":"有比某物更重要的東西，是指另一種價值更重要。"},{"en":"A parent may remind a child that there are more important things than exam marks.","zh":"父母可能提醒孩子，有比考試分數更重要的東西。"},{"en":"This phrase contrasts material success with deeper human values.","zh":"這個短語把物質成功與更深層人性價值作對比。"},{"en":"It is often used to question what people chase too strongly.","zh":"它常用來質疑人們過分追求的事物。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":7},{"front":"reflect the warmth and solidarity of","meaning":"反映……的溫情和團結","examples":[{"en":"The ending reflects the warmth and solidarity of the Italian village.","zh":"結局反映意大利村莊的溫情和團結。"},{"en":"To reflect the warmth and solidarity of a community means to show its kindness and unity.","zh":"反映一個社區的溫情和團結，是指展示其善意和一致支持。"},{"en":"A school charity event can reflect the warmth and solidarity of teachers and students.","zh":"學校慈善活動可以反映師生的溫情和團結。"},{"en":"When people support one another in trouble, their solidarity becomes visible.","zh":"當人們在困難中互相支持，他們的團結就變得可見。"},{"en":"This phrase links a scene with the community values behind it.","zh":"這個短語把場景與其背後社區價值連接起來。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":7},{"front":"solidarity","meaning":"團結","examples":[{"en":"The movie emphasises the solidarity of the village community.","zh":"電影強調村莊社區的團結。"},{"en":"Solidarity means unity and mutual support among people in a group.","zh":"團結是指群體中人們的一致和互相支持。"},{"en":"Workers show solidarity when they support a colleague treated unfairly.","zh":"當工人支持受到不公平對待的同事，就是展現團結。"},{"en":"Solidarity becomes important when people face poverty, danger or injustice together.","zh":"當人們一起面對貧窮、危險或不公，團結變得重要。"},{"en":"This word describes standing together rather than acting alone.","zh":"這個詞描述共同站在一起，而不是單獨行動。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":7},{"front":"in the face of adversity","meaning":"面對逆境","examples":[{"en":"The villagers show warmth and solidarity in the face of adversity.","zh":"村民面對逆境時展現溫情和團結。"},{"en":"In the face of adversity means when dealing with hardship, danger or serious difficulty.","zh":"面對逆境，是指處理艱難、危險或嚴重困難時。"},{"en":"A family may stay united in the face of illness and financial pressure.","zh":"家庭可能在面對疾病和財政壓力時保持團結。"},{"en":"Adversity can reveal whether people support or abandon one another.","zh":"逆境可以揭示人們會互相支持還是彼此放棄。"},{"en":"This phrase describes behaviour during difficult times.","zh":"這個短語描述困難時期中的行為。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":7},{"front":"universal themes","meaning":"普世主題","examples":[{"en":"The film deals with universal themes.","zh":"這部電影處理普世主題。"},{"en":"Universal themes are ideas that many people across cultures can understand.","zh":"普世主題是許多跨文化人士都能理解的想法。"},{"en":"Love, greed, hope, family and fairness are common universal themes.","zh":"愛、貪婪、希望、家庭和公平都是常見普世主題。"},{"en":"Universal themes help a local story speak to international audiences.","zh":"普世主題幫助本地故事與國際觀眾產生連接。"},{"en":"This phrase refers to human concerns beyond one culture.","zh":"這個短語指超越單一文化的人類關注。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":7},{"front":"one could speculate that","meaning":"可以推測","examples":[{"en":"One could speculate that a Western audience might not identify with these themes.","zh":"可以推測西方觀眾未必會認同這些主題。"},{"en":"One could speculate that means one might guess or suggest without complete certainty.","zh":"可以推測，是指在未完全確定下作出猜想或提出可能性。"},{"en":"One could speculate that students prefer videos because they feel easier than textbooks.","zh":"可以推測學生較喜歡影片，因為影片感覺比教科書容易。"},{"en":"Speculation needs caution because it may not be supported by strong evidence.","zh":"推測需要謹慎，因為它可能沒有強力證據支持。"},{"en":"This phrase introduces a possible interpretation, not a proven fact.","zh":"這個短語引入可能解讀，而不是已證明事實。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":7},{"front":"Western audience","meaning":"西方觀眾","examples":[{"en":"A Western audience might not identify strongly with the themes.","zh":"西方觀眾未必會強烈認同這些主題。"},{"en":"A Western audience means viewers from Western countries or Western cultural backgrounds.","zh":"西方觀眾是指來自西方國家或西方文化背景的觀眾。"},{"en":"A Western audience may interpret village poverty differently from local Italian viewers.","zh":"西方觀眾對鄉村貧窮的理解，可能不同於意大利本地觀眾。"},{"en":"Audience background affects how people respond to cultural details.","zh":"觀眾背景會影響人們如何回應文化細節。"},{"en":"This phrase identifies the viewers being considered.","zh":"這個短語指出正在考慮的觀眾。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":7},{"front":"identify with","meaning":"對……產生認同","examples":[{"en":"Some viewers may not identify with the film’s themes.","zh":"有些觀眾可能不會對電影主題產生認同。"},{"en":"To identify with something means to feel that it connects with your own experience or values.","zh":"對某事產生認同，是指感到它與自己的經驗或價值有連接。"},{"en":"Students may identify with a story about exam pressure.","zh":"學生可能對關於考試壓力的故事產生認同。"},{"en":"If viewers cannot identify with characters, emotional impact may be weaker.","zh":"如果觀眾不能認同角色，情感影響可能較弱。"},{"en":"This phrase describes personal connection and recognition.","zh":"這個短語描述個人連繫和共鳴。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":7},{"front":"given the increasing urbanisation","meaning":"鑑於日益加劇的城市化","examples":[{"en":"A Western audience may react differently, given the increasing urbanisation of society.","zh":"鑑於社會日益城市化，西方觀眾可能有不同反應。"},{"en":"Given the increasing urbanisation means considering that more people now live in cities.","zh":"鑑於日益加劇的城市化，是指考慮到越來越多人住在城市。"},{"en":"Given the increasing urbanisation of Hong Kong, village traditions may feel distant to some students.","zh":"鑑於香港日益城市化，鄉村傳統對有些學生可能感到遙遠。"},{"en":"Urbanisation can change what viewers find familiar or meaningful.","zh":"城市化會改變觀眾覺得熟悉或有意義的東西。"},{"en":"This phrase gives a reason based on social change.","zh":"這個短語提供基於社會變化的原因。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":7},{"front":"urbanisation and materialism","meaning":"城市化和物質主義","examples":[{"en":"Urbanisation and materialism may affect how viewers respond to the film.","zh":"城市化和物質主義可能影響觀眾如何回應電影。"},{"en":"Urbanisation and materialism mean city growth and strong focus on possessions or money.","zh":"城市化和物質主義，是指城市增長以及對財物或金錢的強烈重視。"},{"en":"A society shaped by urbanisation and materialism may value speed, comfort and consumption.","zh":"受城市化和物質主義塑造的社會，可能重視速度、舒適和消費。"},{"en":"These forces can make village solidarity feel unfamiliar or less immediate.","zh":"這些力量會令鄉村團結感覺陌生或較不直接。"},{"en":"This phrase connects social change with audience interpretation.","zh":"這個短語把社會變化與觀眾解讀連接起來。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":7},{"front":"immediate translation issue","meaning":"最直接的翻譯問題","examples":[{"en":"The most immediate translation issue relates to the movie’s title.","zh":"最直接的翻譯問題與電影名稱有關。"},{"en":"An immediate translation issue is a problem that appears first or most directly when translating.","zh":"最直接的翻譯問題，是翻譯時最先或最直接出現的問題。"},{"en":"A song title can create an immediate translation issue if it uses wordplay.","zh":"如果歌名使用文字遊戲，它可能造成最直接的翻譯問題。"},{"en":"Titles matter because they shape the audience’s first impression.","zh":"標題很重要，因為它塑造觀眾第一印象。"},{"en":"This phrase points to the first practical problem a translator must handle.","zh":"這個短語指出譯者必須處理的第一個實際問題。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":7},{"front":"relate to","meaning":"與……有關","examples":[{"en":"The translation issue relates to the movie’s title.","zh":"翻譯問題與電影名稱有關。"},{"en":"To relate to something means to be connected with it.","zh":"與某事有關，是指與它有連繫。"},{"en":"The complaint relates to late delivery, not product quality.","zh":"投訴與延遲送貨有關，而不是產品質素。"},{"en":"In translation, a problem may relate to culture, grammar or timing.","zh":"在翻譯中，問題可能與文化、文法或時間有關。"},{"en":"This phrase identifies what a problem is about.","zh":"這個短語指出問題關於甚麼。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":8},{"front":"movie’s title","meaning":"電影名稱","examples":[{"en":"The movie’s title creates a translation problem.","zh":"電影名稱造成翻譯問題。"},{"en":"A movie’s title is the name given to a film.","zh":"電影名稱是給一部電影的名字。"},{"en":"A title with a cultural joke may be difficult to translate.","zh":"含有文化笑話的片名可能難以翻譯。"},{"en":"If the title is unclear, viewers may misunderstand the film before watching it.","zh":"如果片名不清楚，觀眾可能在觀看前已誤解電影。"},{"en":"This phrase refers to the film name, not the whole script.","zh":"這個短語指電影名字，而不是整個劇本。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":8},{"front":"translate as","meaning":"翻譯為","examples":[{"en":"Lo Scopone Scientifico translates as Scientific Scopone.","zh":"Lo Scopone Scientifico 翻譯為 Scientific Scopone。"},{"en":"Translate as means to be rendered in another language using certain words.","zh":"翻譯為，是指用某些字詞轉成另一語言。"},{"en":"The French word bonjour translates as hello in English.","zh":"法文 bonjour 翻譯為英文 hello。"},{"en":"A word may translate literally but still fail culturally.","zh":"一個詞可能能直譯，但在文化上仍失效。"},{"en":"This phrase shows the result of translation.","zh":"這個短語顯示翻譯結果。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":8},{"front":"traditional Italian card game","meaning":"傳統意大利紙牌遊戲","examples":[{"en":"Scopone is a traditional Italian card game.","zh":"Scopone 是一種傳統意大利紙牌遊戲。"},{"en":"A traditional Italian card game is a long-established card game from Italian culture.","zh":"傳統意大利紙牌遊戲，是源自意大利文化且歷史悠久的紙牌遊戲。"},{"en":"Visitors may not understand a traditional card game if they have never seen it played.","zh":"如果旅客從未見過某傳統紙牌遊戲，可能不理解玩法。"},{"en":"Cultural games can be hard to translate because their names carry local knowledge.","zh":"文化遊戲可能難翻譯，因為名稱承載本地知識。"},{"en":"This phrase identifies Scopone as culturally specific.","zh":"這個短語指出 Scopone 具有文化特定性。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":8},{"front":"of great antiquity","meaning":"歷史悠久的","examples":[{"en":"Scopone is a traditional card game of great antiquity.","zh":"Scopone 是一種歷史悠久的傳統紙牌遊戲。"},{"en":"Of great antiquity means very old and historically long-established.","zh":"歷史悠久的，是指非常古老並且長期存在。"},{"en":"A festival of great antiquity may have been celebrated for centuries.","zh":"一個歷史悠久的節日可能已慶祝數百年。"},{"en":"Old cultural practices often carry meanings that outsiders do not immediately understand.","zh":"古老文化做法常承載外人未能立即理解的意思。"},{"en":"This phrase emphasises age and historical depth.","zh":"這個短語強調年代久遠和歷史深度。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":8},{"front":"obscure to","meaning":"對……來說晦澀難明","examples":[{"en":"The name Scopone was obscure to Western viewers.","zh":"Scopone 這個名稱對西方觀眾來說晦澀難明。"},{"en":"Obscure to someone means unclear or difficult for that person to understand.","zh":"對某人來說晦澀難明，是指對那人不清楚或難理解。"},{"en":"A local slang word may be obscure to visitors from another city.","zh":"本地俚語對另一城市的訪客可能晦澀難明。"},{"en":"If a title is obscure to viewers, it may fail to attract them.","zh":"如果片名對觀眾來說晦澀難明，可能無法吸引他們。"},{"en":"This phrase describes difficulty caused by unfamiliar knowledge.","zh":"這個短語描述因不熟悉知識造成的理解困難。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":8},{"front":"Western viewers","meaning":"西方觀眾","examples":[{"en":"The translators avoided a title that would be obscure to Western viewers.","zh":"譯者避免使用會令西方觀眾感到晦澀的片名。"},{"en":"Western viewers are people from Western countries or cultural backgrounds who watch the film.","zh":"西方觀眾是指來自西方國家或文化背景的電影觀眾。"},{"en":"Western viewers may not know the rules of a traditional Italian card game.","zh":"西方觀眾可能不知道傳統意大利紙牌遊戲的規則。"},{"en":"Translators consider viewers’ background so titles do not feel meaningless.","zh":"譯者會考慮觀眾背景，使片名不會感覺沒有意思。"},{"en":"This phrase identifies the target audience of the English version.","zh":"這個短語指出英文版本的目標觀眾。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":8},{"front":"insert a blander term","meaning":"加入較平淡的用詞","examples":[{"en":"The translators inserted a blander term in the English title.","zh":"譯者在英文片名中加入較平淡的用詞。"},{"en":"To insert a blander term means to add a safer, less specific or less vivid word.","zh":"加入較平淡的用詞，是指加入較安全、較不具體或較不生動的字。"},{"en":"A translator may insert a blander term when a cultural word would confuse readers.","zh":"當文化詞會令讀者困惑時，譯者可能加入較平淡用詞。"},{"en":"Bland terms can make a title easier but less colourful.","zh":"平淡用詞可以令標題較容易理解，但較少色彩。"},{"en":"This phrase describes a compromise in translation.","zh":"這個短語描述翻譯中的妥協。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":8},{"front":"less appropriate term","meaning":"較不恰當的用詞","examples":[{"en":"The English title uses a less appropriate term.","zh":"英文片名使用了較不恰當的用詞。"},{"en":"A less appropriate term is a word that fits the situation less well than another possible word.","zh":"較不恰當的用詞，是比另一個可能用詞較不符合情況的字詞。"},{"en":"Calling a serious medical guide a “story book” would be a less appropriate term.","zh":"把嚴肅醫療指南稱為「故事書」會是較不恰當用詞。"},{"en":"Translators may choose a less appropriate term if the accurate one is too obscure.","zh":"如果準確詞語太晦澀，譯者可能選擇較不恰當的用詞。"},{"en":"This phrase shows that a choice may be understandable but imperfect.","zh":"這個短語顯示某選擇可以理解但不完美。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":8},{"front":"subtitling lapse","meaning":"字幕翻譯失誤","examples":[{"en":"The passage gives an example of a subtitling lapse.","zh":"篇章給出一個字幕翻譯失誤的例子。"},{"en":"A subtitling lapse is a mistake or poor decision in subtitle translation.","zh":"字幕翻譯失誤，是字幕翻譯中的錯誤或不佳決定。"},{"en":"A subtitle that translates a joke word for word may be a subtitling lapse.","zh":"把笑話逐字翻譯的字幕可能是字幕翻譯失誤。"},{"en":"Such lapses can confuse viewers or damage the mood of a scene.","zh":"這類失誤會令觀眾困惑或破壞場面氣氛。"},{"en":"This phrase focuses on a failure in subtitle quality.","zh":"這個短語聚焦字幕質素上的失敗。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":8},{"front":"betting","meaning":"下注；賭注","examples":[{"en":"The betting in the film is shown with extremely high figures.","zh":"電影中的下注以極高金額呈現。"},{"en":"Betting means risking money on the result of a game, race or event.","zh":"下注是指把金錢押在遊戲、比賽或事件結果上。"},{"en":"People may place small bets during a card game for excitement.","zh":"人們可能在紙牌遊戲中下小注來增加刺激。"},{"en":"Betting can become dangerous when the sums are too large.","zh":"當金額太大，下注會變得危險。"},{"en":"This word refers to the act of gambling money.","zh":"這個詞指賭金錢的行為。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":8},{"front":"ludicrously high figures","meaning":"荒謬地高的金額","examples":[{"en":"The subtitles use ludicrously high figures.","zh":"字幕使用荒謬地高的金額。"},{"en":"Ludicrously high figures are numbers so large that they seem ridiculous or unbelievable.","zh":"荒謬地高的金額，是大得可笑或難以置信的數字。"},{"en":"A café bill of one million dollars would be a ludicrously high figure.","zh":"一張一百萬美元的咖啡店帳單，就是荒謬地高的金額。"},{"en":"If currency is translated wrongly, ordinary bets may look absurdly huge.","zh":"如果貨幣翻譯錯誤，普通賭注可能看似荒謬巨大。"},{"en":"This phrase shows that numbers can damage realism.","zh":"這個短語顯示數字可以破壞真實感。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":9},{"front":"regularly jump out","meaning":"經常顯得突兀","examples":[{"en":"Subtitles such as Let’s start with a million regularly jump out.","zh":"“Let’s start with a million” 這類字幕經常顯得突兀。"},{"en":"To regularly jump out means to repeatedly catch attention in a strange or distracting way.","zh":"經常顯得突兀，是指反覆以奇怪或令人分心的方式吸引注意。"},{"en":"A spelling mistake on every page will regularly jump out to careful readers.","zh":"每頁都有拼寫錯誤，會讓細心讀者經常覺得突兀。"},{"en":"Strange numbers in subtitles can pull viewers away from the story.","zh":"字幕中奇怪的數字會把觀眾從故事中拉走。"},{"en":"This phrase describes something that feels too noticeable.","zh":"這個短語描述某事過分顯眼。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":9},{"front":"literal translation","meaning":"直譯","examples":[{"en":"The figures are a literal translation from Italian lire.","zh":"這些金額是從意大利里拉直譯而來。"},{"en":"Literal translation means translating words or numbers directly without adjusting meaning or context.","zh":"直譯是指不調整意思或語境，直接翻譯字詞或數字。"},{"en":"A literal translation of an idiom may sound confusing in another language.","zh":"慣用語的直譯在另一語言中可能令人困惑。"},{"en":"Literal translation can be accurate in form but wrong in effect.","zh":"直譯在形式上可能準確，但效果上錯誤。"},{"en":"This phrase contrasts word-for-word translation with meaning-based translation.","zh":"這個短語把逐字翻譯與以意思為本的翻譯作對比。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":9},{"front":"Italian lire","meaning":"意大利里拉","examples":[{"en":"The betting figures are translated literally from Italian lire.","zh":"賭注金額是從意大利里拉直譯而來。"},{"en":"Italian lire were the old currency used in Italy before the euro.","zh":"意大利里拉是意大利在歐元之前使用的舊貨幣。"},{"en":"A large number in Italian lire may represent much less value than the same number in dollars.","zh":"意大利里拉中的大數字，可能代表遠低於相同美元數字的價值。"},{"en":"Translators must consider currency so money amounts feel believable.","zh":"譯者必須考慮貨幣，使金額感覺可信。"},{"en":"This phrase explains why literal figures may mislead viewers.","zh":"這個短語解釋為何直譯數字可能誤導觀眾。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":9},{"front":"English-speaking audience","meaning":"英語觀眾","examples":[{"en":"The English-speaking audience would associate the figures with dollars.","zh":"英語觀眾會把這些數字與美元聯繫起來。"},{"en":"An English-speaking audience is an audience that understands English as a main or working language.","zh":"英語觀眾是以英語作主要或工作語言來理解內容的觀眾。"},{"en":"English-speaking viewers may read large numbers as dollars if no currency is explained.","zh":"如果沒有解釋貨幣，英語觀眾可能把大數字理解為美元。"},{"en":"Audience habits affect how subtitles are interpreted.","zh":"觀眾習慣會影響字幕如何被解讀。"},{"en":"This phrase identifies the viewers for the English subtitles.","zh":"這個短語指出英文字幕的觀眾。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":9},{"front":"associate something with","meaning":"把……與……聯繫起來","examples":[{"en":"Viewers would associate the figures with dollars.","zh":"觀眾會把這些數字與美元聯繫起來。"},{"en":"To associate something with something else means to connect them in the mind.","zh":"把某事與另一事聯繫起來，是指在腦海中把它們連接。"},{"en":"Many people associate exams with stress and late-night revision.","zh":"許多人把考試與壓力和深夜溫習聯繫起來。"},{"en":"If viewers associate a number with dollars, the amount may seem unrealistically large.","zh":"如果觀眾把某數字與美元聯繫起來，金額可能看起來不切實際地大。"},{"en":"This phrase describes mental connection, not physical connection.","zh":"這個短語描述心理連接，而不是實體連接。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":9},{"front":"apparent lack of plausibility","meaning":"表面上缺乏可信性","examples":[{"en":"The result is an apparent lack of plausibility.","zh":"結果是表面上缺乏可信性。"},{"en":"Apparent lack of plausibility means something seems unbelievable or unrealistic.","zh":"表面上缺乏可信性，是指某事看似不可信或不現實。"},{"en":"A story about a child buying a mansion with pocket money has an apparent lack of plausibility.","zh":"一個孩子用零用錢買豪宅的故事，表面上缺乏可信性。"},{"en":"Unrealistic subtitles can make viewers question the scene instead of following it.","zh":"不真實的字幕會令觀眾質疑場面，而不是投入其中。"},{"en":"This phrase describes a surface impression of unbelievability.","zh":"這個短語描述表面上的不可信印象。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":9},{"front":"plausibility","meaning":"可信性","examples":[{"en":"The literal translation reduces the plausibility of the scene.","zh":"直譯降低了該場景的可信性。"},{"en":"Plausibility is the quality of seeming believable or reasonable.","zh":"可信性是看起來可信或合理的特質。"},{"en":"A film loses plausibility if a poor student suddenly owns three sports cars without explanation.","zh":"如果一個貧窮學生突然無解釋地擁有三輛跑車，電影就失去可信性。"},{"en":"Plausibility matters because viewers need to believe the story world.","zh":"可信性很重要，因為觀眾需要相信故事世界。"},{"en":"This word refers to credibility, not factual truth alone.","zh":"這個詞指可信程度，而不只是事實真相。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":9},{"front":"comedic nature of the film","meaning":"電影的喜劇性質","examples":[{"en":"The mistranslated figures change the comedic nature of the film.","zh":"誤譯的金額改變了電影的喜劇性質。"},{"en":"The comedic nature of a film is the way its humour works and makes viewers laugh.","zh":"電影的喜劇性質，是指其幽默如何運作並令觀眾發笑。"},{"en":"A film’s comedic nature may depend on timing, surprise and believable exaggeration.","zh":"電影的喜劇性質可能取決於時間掌握、驚喜和可信誇張。"},{"en":"If subtitles make numbers absurd, viewers may laugh for the wrong reason.","zh":"如果字幕令數字荒謬，觀眾可能因錯誤原因發笑。"},{"en":"This phrase focuses on how humour is created and received.","zh":"這個短語聚焦幽默如何被創造和接收。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":9},{"front":"with respect to","meaning":"關於；就……而言","examples":[{"en":"With respect to the specific strategies used, there are five.","zh":"關於所使用的具體策略，共有五種。"},{"en":"With respect to means regarding or concerning a particular topic.","zh":"關於某事，是指就某個特定主題而言。"},{"en":"With respect to homework, the main problem is quality rather than quantity.","zh":"關於功課，主要問題是質素而不是數量。"},{"en":"This phrase narrows discussion to one aspect of a larger issue.","zh":"這個短語把討論收窄到較大議題中的一個方面。"},{"en":"It is formal and common in academic writing.","zh":"它較正式，常見於學術寫作。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":9},{"front":"specific subtitling strategies","meaning":"具體字幕翻譯策略","examples":[{"en":"The passage discusses five specific subtitling strategies.","zh":"篇章討論五種具體字幕翻譯策略。"},{"en":"Specific subtitling strategies are clearly identified methods used to solve subtitle problems.","zh":"具體字幕翻譯策略，是用來解決字幕問題的清楚命名方法。"},{"en":"Transfer, paraphrasing and condensation can be specific strategies in subtitle translation.","zh":"轉移、意譯和濃縮可以是字幕翻譯中的具體策略。"},{"en":"Choosing the right strategy affects clarity, humour and cultural meaning.","zh":"選擇正確策略會影響清晰度、幽默和文化意思。"},{"en":"This phrase focuses on named translation methods rather than general advice.","zh":"這個短語聚焦已命名的翻譯方法，而不是一般建議。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":9},{"front":"let us begin with","meaning":"讓我們先由……開始","examples":[{"en":"Let us begin with the subtitle The old bag’s here.","zh":"讓我們先由字幕 “The old bag’s here” 開始。"},{"en":"Let us begin with means let us start by discussing this example or point.","zh":"讓我們先由某事開始，是指先討論這個例子或重點。"},{"en":"Let us begin with the easiest question before moving to the difficult ones.","zh":"讓我們先由最容易的問題開始，再進入困難題。"},{"en":"This phrase introduces the first item in an explanation.","zh":"這個短語引入解釋中的第一項。"},{"en":"It is a formal way to guide readers through an analysis.","zh":"它是引導讀者進行分析的正式說法。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":10},{"front":"The old bag’s here.","meaning":"「那個死老太婆來了。」","examples":[{"en":"The subtitle The old bag’s here is idiomatic in English.","zh":"字幕 “The old bag’s here” 在英語中屬慣用語。"},{"en":"The old bag’s here means an insulting way to say that an old woman has arrived.","zh":"“The old bag’s here” 是侮辱性地表示一位老婦到了。"},{"en":"A rude character might whisper, “The old bag’s here,” when a disliked neighbour enters.","zh":"當一位不受歡迎的鄰居進來，粗魯角色可能低聲說：「那個死老太婆來了。」"},{"en":"The phrase can sound harsh because it attacks the person, not just the situation.","zh":"這個短語聽起來刻薄，因為它攻擊人，而不只是描述情況。"},{"en":"This expression is informal and disrespectful.","zh":"這個表達屬非正式且不尊重。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":10},{"front":"idiomatic in English","meaning":"在英語中屬慣用語","examples":[{"en":"The expression is idiomatic in English.","zh":"這個表達在英語中屬慣用語。"},{"en":"Idiomatic in English means natural to English speakers and not translated word for word.","zh":"在英語中屬慣用語，是指對英語使用者自然，而不是逐字理解。"},{"en":"“Spill the beans” is idiomatic in English because it means reveal a secret.","zh":"“Spill the beans” 在英語中屬慣用語，因為它意思是洩露秘密。"},{"en":"Idiomatic phrases can confuse learners if they read each word literally.","zh":"如果學習者逐字閱讀慣用語，可能會感到困惑。"},{"en":"This phrase describes natural language use, not grammar alone.","zh":"這個短語描述自然語言使用，而不只是文法。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":10},{"front":"insulting term","meaning":"侮辱性稱呼","examples":[{"en":"Old bag is an insulting term for an elderly woman.","zh":"Old bag 是對老年女士的侮辱性稱呼。"},{"en":"An insulting term is a word or phrase used to offend or disrespect someone.","zh":"侮辱性稱呼，是用來冒犯或不尊重某人的詞語或短語。"},{"en":"Students should avoid insulting terms when discussing age, race or appearance.","zh":"學生討論年齡、種族或外貌時應避免侮辱性稱呼。"},{"en":"Insulting terms can change the tone of a subtitle immediately.","zh":"侮辱性稱呼可以立即改變字幕語氣。"},{"en":"This phrase focuses on negative social meaning.","zh":"這個短語聚焦負面社會意思。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":10},{"front":"elderly woman","meaning":"老年女士","examples":[{"en":"Old bag is an insulting term for an elderly woman.","zh":"Old bag 是對老年女士的侮辱性稱呼。"},{"en":"An elderly woman is an older adult woman.","zh":"老年女士是年紀較大的成年女性。"},{"en":"A polite subtitle should not use a rude phrase for an elderly woman unless the character is insulting her.","zh":"除非角色正在侮辱她，否則有禮貌的字幕不應用粗魯短語稱呼老年女士。"},{"en":"Age-related words must be translated carefully to avoid unintended disrespect.","zh":"與年齡相關的字詞必須小心翻譯，以免無意冒犯。"},{"en":"This phrase identifies the person being described.","zh":"這個短語指出被描述的人。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":10},{"front":"comprising only two words","meaning":"只由兩個詞組成","examples":[{"en":"The expression is simple, comprising only two words.","zh":"這個表達很簡單，只由兩個詞組成。"},{"en":"Comprising only two words means being made up of just two words.","zh":"只由兩個詞組成，是指只包含兩個詞。"},{"en":"The phrase “good luck” is short, comprising only two words.","zh":"“good luck” 這個短語很短，只由兩個詞組成。"},{"en":"Short expressions can still carry strong cultural meaning.","zh":"短表達仍可以承載強烈文化意思。"},{"en":"This phrase describes the structure or length of an expression.","zh":"這個短語描述表達的結構或長度。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":10},{"front":"literally intended","meaning":"按字面意思使用","examples":[{"en":"The word old is literally intended in the expression.","zh":"在這個表達中，old 這個詞按字面意思使用。"},{"en":"Literally intended means meant in its direct, ordinary sense rather than as a metaphor.","zh":"按字面意思使用，是指以直接、普通意思使用，而不是比喻。"},{"en":"In “old house,” old is literally intended because it means aged.","zh":"在 “old house” 中，old 按字面意思使用，因為它指年久。"},{"en":"Some idioms combine literal words with special meanings.","zh":"有些慣用語結合字面詞語和特殊意思。"},{"en":"This phrase helps separate literal meaning from idiomatic meaning.","zh":"這個短語幫助區分字面意思與慣用意思。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":10},{"front":"the same idiom occurs in","meaning":"同一慣用語出現在……","examples":[{"en":"The writer speculates that the same idiom occurs in Italian.","zh":"作者推測同一慣用語出現在意大利語中。"},{"en":"The same idiom occurs in another language means that language has a similar fixed expression.","zh":"同一慣用語出現在另一語言中，是指該語言有相似固定表達。"},{"en":"The same idiom may occur in two languages if both cultures use a similar image.","zh":"如果兩種文化使用相似意象，同一慣用語可能出現在兩種語言中。"},{"en":"When idioms match, translators can sometimes translate more directly.","zh":"當慣用語相配，譯者有時可以較直接翻譯。"},{"en":"This phrase describes cross-language similarity.","zh":"這個短語描述跨語言相似性。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":10},{"front":"direct translation","meaning":"直接翻譯","examples":[{"en":"The direct translation of old and bag may carry the same idiomatic meaning.","zh":"old 和 bag 的直接翻譯可能帶有相同慣用意思。"},{"en":"Direct translation means translating the words closely from the source language.","zh":"直接翻譯是指緊貼原文語言的字詞來翻譯。"},{"en":"A direct translation works well only when the target language uses the same expression.","zh":"只有當目標語言使用相同表達時，直接翻譯才效果好。"},{"en":"Direct translation can fail if the words sound natural in one language but strange in another.","zh":"如果字詞在一種語言自然但在另一種語言奇怪，直接翻譯會失敗。"},{"en":"This phrase contrasts with paraphrasing or cultural adaptation.","zh":"這個短語與意譯或文化改寫形成對比。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":10},{"front":"carry the same idiomatic meaning","meaning":"帶有相同慣用意思","examples":[{"en":"The Italian words may carry the same idiomatic meaning.","zh":"意大利語詞語可能帶有相同慣用意思。"},{"en":"To carry the same idiomatic meaning means to express the same non-literal idea.","zh":"帶有相同慣用意思，是指表達相同的非字面意思。"},{"en":"Two languages may use different animal words but carry the same idiomatic meaning.","zh":"兩種語言可能使用不同動物詞，但帶有相同慣用意思。"},{"en":"If meaning matches, the subtitle can preserve the original tone more easily.","zh":"如果意思相符，字幕就更容易保留原本語氣。"},{"en":"This phrase focuses on shared idiom function, not identical grammar.","zh":"這個短語聚焦相同慣用功能，而不是相同文法。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":10},{"front":"strategy of Transfer","meaning":"轉移策略","examples":[{"en":"This is the strategy of Transfer.","zh":"這就是轉移策略。"},{"en":"The strategy of Transfer gives the full translated expression directly in the subtitles.","zh":"轉移策略是在字幕中直接給出完整翻譯表達。"},{"en":"A translator may use Transfer when the original expression works clearly in the target language.","zh":"當原文表達在目標語言中清楚有效時，譯者可能使用轉移策略。"},{"en":"Transfer can preserve detail, but it may take more subtitle space.","zh":"轉移可以保留細節，但可能佔用更多字幕空間。"},{"en":"This strategy is useful when time and space allow a fuller version.","zh":"當時間和空間容許較完整版本時，這種策略有用。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":10},{"front":"full expression","meaning":"完整表達","examples":[{"en":"In Transfer, the full expression is given.","zh":"在轉移策略中，會給出完整表達。"},{"en":"A full expression is the complete phrase or sentence, not a shortened version.","zh":"完整表達是完整短語或句子，而不是縮短版本。"},{"en":"A teacher may ask students to write the full expression rather than only keywords.","zh":"老師可能要求學生寫完整表達，而不是只寫關鍵字。"},{"en":"In subtitles, full expressions can improve meaning but may be too long to read.","zh":"在字幕中，完整表達可以改善意思，但可能太長而難以閱讀。"},{"en":"This phrase contrasts complete wording with condensed wording.","zh":"這個短語把完整措辭與濃縮措辭作對比。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":11},{"front":"without consideration of","meaning":"沒有考慮……","examples":[{"en":"The full expression is given without consideration of time or space.","zh":"完整表達被給出，沒有考慮時間或空間。"},{"en":"Without consideration of something means not taking that factor into account.","zh":"沒有考慮某事，是指沒有把該因素納入考量。"},{"en":"A timetable made without consideration of lunch breaks may exhaust students.","zh":"沒有考慮午膳時間的時間表可能令學生疲累。"},{"en":"Subtitles written without considering space may become too crowded.","zh":"沒有考慮空間的字幕可能變得太擠迫。"},{"en":"This phrase criticises ignoring an important limit.","zh":"這個短語批評忽略重要限制。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":11},{"front":"time or space","meaning":"時間或空間","examples":[{"en":"Subtitlers must often consider time or space.","zh":"字幕譯者常常必須考慮時間或空間。"},{"en":"Time or space refers to how long subtitles stay on screen and how much room they occupy.","zh":"時間或空間，是指字幕停留在螢幕上的時間和佔用的畫面位置。"},{"en":"A subtitle may be shortened when there is not enough time or space.","zh":"當時間或空間不足，字幕可能被縮短。"},{"en":"If subtitles are too long, viewers cannot read them before they disappear.","zh":"如果字幕太長，觀眾在字幕消失前讀不完。"},{"en":"This phrase names two major technical limits in subtitling.","zh":"這個短語指出字幕翻譯中的兩個主要技術限制。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":11},{"front":"there could well be","meaning":"很可能有","examples":[{"en":"There could well be a closely aligned idiom in Italian.","zh":"意大利語中很可能有一個十分接近的慣用語。"},{"en":"There could well be means it is quite possible that something exists or happens.","zh":"很可能有，是指某事相當可能存在或發生。"},{"en":"There could well be a simpler explanation for the student’s mistake.","zh":"學生的錯誤很可能有更簡單的解釋。"},{"en":"This phrase expresses likelihood without complete certainty.","zh":"這個短語表達可能性，但不是完全確定。"},{"en":"It is useful when making a careful inference.","zh":"它適合用於作出謹慎推論。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":11},{"front":"closely aligned idiom","meaning":"十分接近的慣用語","examples":[{"en":"There may be a closely aligned idiom in the source language.","zh":"原文語言中可能有一個十分接近的慣用語。"},{"en":"A closely aligned idiom is an idiom in another language with very similar meaning or wording.","zh":"十分接近的慣用語，是另一語言中意思或措辭非常相似的慣用語。"},{"en":"Two languages may share closely aligned idioms about luck, age or money.","zh":"兩種語言可能共享關於運氣、年齡或金錢的相近慣用語。"},{"en":"Closely aligned idioms make translation easier because tone and meaning overlap.","zh":"十分接近的慣用語令翻譯較容易，因為語氣和意思重疊。"},{"en":"This phrase describes a strong match between idiomatic expressions.","zh":"這個短語描述慣用表達之間的高度配合。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":11},{"front":"strategy would be Imitation","meaning":"策略會是模仿","examples":[{"en":"If both languages use similar words, the strategy would be Imitation.","zh":"如果兩種語言使用相似字詞，策略會是模仿。"},{"en":"The strategy would be Imitation means the translator would copy a similar form in both languages.","zh":"策略會是模仿，是指譯者會在兩種語言中複製相似形式。"},{"en":"Imitation may work when a name, phrase or expression already looks similar across languages.","zh":"當名稱、短語或表達在不同語言中本來就相似，模仿可能有效。"},{"en":"Similar wording can help preserve the original flavour.","zh":"相似措辭可以幫助保留原本味道。"},{"en":"This phrase explains how a strategy is chosen from language similarity.","zh":"這個短語解釋如何根據語言相似性選擇策略。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":11},{"front":"similar lexical elements","meaning":"相似的詞彙元素","examples":[{"en":"Imitation involves similar lexical elements between both languages.","zh":"模仿涉及兩種語言之間相似的詞彙元素。"},{"en":"Similar lexical elements are words or word parts that look or function alike in two languages.","zh":"相似的詞彙元素，是在兩種語言中外形或功能相似的詞或詞素。"},{"en":"A translator may notice similar lexical elements in names borrowed from Latin.","zh":"譯者可能在源自拉丁語的名稱中注意到相似詞彙元素。"},{"en":"When lexical elements are similar, imitation can feel natural.","zh":"當詞彙元素相似，模仿可以感覺自然。"},{"en":"This phrase focuses on vocabulary similarity.","zh":"這個短語聚焦詞彙相似性。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":11},{"front":"between both languages","meaning":"在兩種語言之間","examples":[{"en":"The idioms may contain similar lexical elements between both languages.","zh":"這些慣用語在兩種語言之間可能包含相似詞彙元素。"},{"en":"Between both languages means in comparison across the two languages involved.","zh":"在兩種語言之間，是指在涉及的兩種語言之間作比較。"},{"en":"Similar words between both languages can make translation easier for beginners.","zh":"兩種語言之間的相似詞語可以令初學者較容易翻譯。"},{"en":"Differences between both languages can also cause false friends and mistakes.","zh":"兩種語言之間的差異也可能造成假朋友詞和錯誤。"},{"en":"This phrase highlights cross-language comparison.","zh":"這個短語突出跨語言比較。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":11},{"front":"continuing with idioms","meaning":"繼續談慣用語","examples":[{"en":"Continuing with idioms, the passage discusses Catches win matches.","zh":"繼續談慣用語，篇章討論 “Catches win matches”。"},{"en":"Continuing with idioms means staying on the topic of idiomatic expressions.","zh":"繼續談慣用語，是指繼續留在慣用表達這個主題上。"},{"en":"Continuing with grammar, the teacher next explains articles and prepositions.","zh":"繼續談文法，老師接着解釋冠詞和介詞。"},{"en":"This phrase guides readers from one example to another within the same topic.","zh":"這個短語引導讀者在同一主題內由一個例子轉向另一個例子。"},{"en":"It keeps the structure of an explanation clear.","zh":"它令解釋結構保持清楚。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":11},{"front":"Catches win matches.","meaning":"「接球就能贏比賽。」","examples":[{"en":"Catches win matches is an idiom from ball games such as cricket.","zh":"“Catches win matches” 是源自板球等球類運動的慣用語。"},{"en":"Catches win matches means good catching can decide the result of a game.","zh":"“Catches win matches” 意思是良好接球可以決定比賽結果。"},{"en":"A cricket coach may say “Catches win matches” before fielding practice.","zh":"板球教練可能在接球練習前說：「接球就能贏比賽。」"},{"en":"The phrase values one key action because it can change the whole match.","zh":"這個短語重視一個關鍵動作，因為它可以改變整場比賽。"},{"en":"In translation, this idiom may need a different expression with the same effect.","zh":"翻譯時，這個慣用語可能需要換成具有相同效果的不同表達。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":11},{"front":"derive from","meaning":"源自","examples":[{"en":"The phrase derives from certain ball games.","zh":"這個短語源自某些球類運動。"},{"en":"To derive from something means to come from that source or origin.","zh":"源自某事，是指來自該來源或起源。"},{"en":"Many English idioms derive from sports, farming or sea travel.","zh":"許多英語慣用語源自運動、農業或海上旅行。"},{"en":"Knowing where a phrase derives from helps explain its imagery.","zh":"知道短語源自哪裡，有助解釋其意象。"},{"en":"This phrase describes origin.","zh":"這個短語描述來源。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":11},{"front":"ball games","meaning":"球類運動","examples":[{"en":"The idiom comes from certain ball games.","zh":"這個慣用語來自某些球類運動。"},{"en":"Ball games are sports played with a ball.","zh":"球類運動是使用球進行的運動。"},{"en":"Football, basketball, tennis and cricket are all ball games.","zh":"足球、籃球、網球和板球都是球類運動。"},{"en":"Idioms from ball games may be hard to translate for audiences unfamiliar with those sports.","zh":"來自球類運動的慣用語，對不熟悉該運動的觀眾可能難翻譯。"},{"en":"This phrase identifies the sporting background of an expression.","zh":"這個短語指出表達的運動背景。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":12},{"front":"cricket","meaning":"板球","examples":[{"en":"Cricket is one of the sports connected with the idiom.","zh":"板球是與該慣用語有關的運動之一。"},{"en":"Cricket is a bat-and-ball sport played by two teams.","zh":"板球是一種由兩隊進行的球棒和球類運動。"},{"en":"Cricket is popular in countries such as England, India, Australia and Pakistan.","zh":"板球在英國、印度、澳洲和巴基斯坦等國家很受歡迎。"},{"en":"If viewers do not know cricket, the idiom may lose its force.","zh":"如果觀眾不懂板球，該慣用語可能失去力量。"},{"en":"This word names the sport behind the example.","zh":"這個詞命名例子背後的運動。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":12},{"front":"be struck by","meaning":"被……擊中","examples":[{"en":"The ball is struck by the batsman.","zh":"球被擊球員擊中。"},{"en":"To be struck by someone means to be hit by that person or object.","zh":"被某人擊中，是指被那個人或物件打中。"},{"en":"A tennis ball is struck by a racket during a serve.","zh":"網球在發球時被球拍擊中。"},{"en":"In cricket, the batsman strikes the ball before fielders try to catch it.","zh":"在板球中，擊球員擊球後，守備員嘗試接球。"},{"en":"This phrase describes the action that begins the play.","zh":"這個短語描述開始比賽動作的行為。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":12},{"front":"batsman","meaning":"擊球員","examples":[{"en":"The batsman strikes the ball in cricket.","zh":"擊球員在板球中擊球。"},{"en":"A batsman is the player who hits the ball with a bat in cricket.","zh":"擊球員是在板球中用球棒擊球的球員。"},{"en":"A good batsman must judge speed, direction and timing carefully.","zh":"好擊球員必須仔細判斷速度、方向和時間。"},{"en":"If the batsman hits the ball high, fielders may try to catch it.","zh":"如果擊球員把球打高，守備員可能嘗試接球。"},{"en":"This word names a player role in cricket.","zh":"這個詞命名板球中的球員角色。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":12},{"front":"contribute towards","meaning":"有助於","examples":[{"en":"Catching the ball contributes towards winning the game.","zh":"接住球有助於贏得比賽。"},{"en":"To contribute towards something means to help cause or support that result.","zh":"有助於某事，是指幫助造成或支持該結果。"},{"en":"Regular reading contributes towards better vocabulary.","zh":"定期閱讀有助於更好詞彙。"},{"en":"Small actions can contribute towards a large success when they are repeated.","zh":"小行動反覆出現時，可以有助於重大成功。"},{"en":"This phrase shows partial contribution, not the only cause.","zh":"這個短語顯示部分貢獻，而不是唯一原因。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":12},{"front":"no such sports are followed","meaning":"沒有人關注這類運動","examples":[{"en":"No such sports are followed in Italy.","zh":"在意大利，沒有人關注這類運動。"},{"en":"No such sports are followed means people there generally do not watch or care about those sports.","zh":"沒有人關注這類運動，是指那裡的人一般不觀看或不在乎那些運動。"},{"en":"A baseball idiom may fail in a place where no such sports are followed.","zh":"在沒有人關注棒球的地方，棒球慣用語可能失效。"},{"en":"Sports culture affects whether an idiom feels natural.","zh":"運動文化會影響慣用語是否自然。"},{"en":"This phrase explains why a direct sports idiom may not translate well.","zh":"這個短語解釋為何直接使用運動慣用語可能翻譯不好。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":12},{"front":"one can be certain that","meaning":"可以肯定","examples":[{"en":"One can be certain that other words were used in the original Italian.","zh":"可以肯定，意大利原文使用了其他字詞。"},{"en":"One can be certain that means one can feel sure about something.","zh":"可以肯定，是指可以對某事感到確定。"},{"en":"One can be certain that a student who never practises will not improve quickly.","zh":"可以肯定，從不練習的學生不會快速進步。"},{"en":"This phrase expresses strong confidence based on reasoning or evidence.","zh":"這個短語表達基於推理或證據的強烈信心。"},{"en":"It is more formal than saying “we know.”","zh":"它比說 “we know” 更正式。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":12},{"front":"original Italian","meaning":"意大利原文","examples":[{"en":"The original Italian probably used different words.","zh":"意大利原文很可能使用了不同字詞。"},{"en":"Original Italian means the Italian words used before translation.","zh":"意大利原文是指翻譯前使用的意大利語字詞。"},{"en":"A subtitle may sound natural in English even if the original Italian was phrased differently.","zh":"即使意大利原文措辭不同，英文字幕仍可以聽起來自然。"},{"en":"Translators compare the original language with the target language before choosing a strategy.","zh":"譯者選擇策略前，會比較原文語言和目標語言。"},{"en":"This phrase refers to the source text or dialogue.","zh":"這個短語指源文本或原對白。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":12},{"front":"pragmatic effect","meaning":"語用效果","examples":[{"en":"The Italian expression had a similar pragmatic effect.","zh":"意大利語表達有相似語用效果。"},{"en":"Pragmatic effect means the effect an expression has in real communication.","zh":"語用效果是某表達在真實溝通中產生的效果。"},{"en":"A polite phrase may have a rude pragmatic effect if used sarcastically.","zh":"如果以諷刺語氣使用，有禮貌短語可能產生粗魯的語用效果。"},{"en":"Translators must preserve effect, not only dictionary meaning.","zh":"譯者必須保留效果，而不只是字典意思。"},{"en":"This phrase focuses on what the words do to the listener.","zh":"這個短語聚焦字詞對聽者產生甚麼作用。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":12},{"front":"idiomatic nature","meaning":"慣用語性質","examples":[{"en":"The translation keeps the idiomatic nature of the expression.","zh":"翻譯保留了該表達的慣用語性質。"},{"en":"Idiomatic nature means the quality of being a natural fixed expression, not a literal sentence.","zh":"慣用語性質，是指作為自然固定表達而非字面句子的特質。"},{"en":"A translation keeps idiomatic nature when it sounds like something native speakers would actually say.","zh":"當翻譯聽起來像母語者真的會說的話，它就保留慣用語性質。"},{"en":"Losing idiomatic nature can make a subtitle sound stiff or unnatural.","zh":"失去慣用語性質會令字幕聽起來僵硬或不自然。"},{"en":"This phrase focuses on natural expression.","zh":"這個短語聚焦自然表達。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":12},{"front":"Paraphrasing","meaning":"意譯；改述策略","examples":[{"en":"Paraphrasing uses different expressions with a similar meaning.","zh":"意譯使用不同表達來傳達相似意思。"},{"en":"Paraphrasing means saying the same idea in different words.","zh":"意譯是用不同字詞說出相同想法。"},{"en":"A translator may paraphrase a local idiom so foreign viewers understand the point.","zh":"譯者可能意譯本地慣用語，使外國觀眾明白重點。"},{"en":"Paraphrasing helps when direct translation would sound strange.","zh":"當直接翻譯聽起來奇怪時，意譯有幫助。"},{"en":"This strategy protects meaning even when wording changes.","zh":"這種策略在改變措辭時仍保護意思。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":12},{"front":"different expressions","meaning":"不同表達方式","examples":[{"en":"Paraphrasing requires different expressions in the two languages.","zh":"意譯需要兩種語言中不同的表達方式。"},{"en":"Different expressions are different wordings used to communicate an idea.","zh":"不同表達方式，是用來傳達想法的不同措辭。"},{"en":"Two languages may use different expressions for the same feeling of surprise.","zh":"兩種語言可能用不同表達方式表示相同驚訝感。"},{"en":"Different expressions can be necessary when cultures use different images.","zh":"當文化使用不同意象，不同表達方式可能是必要的。"},{"en":"This phrase shows that meaning can remain while words change.","zh":"這個短語顯示字詞改變時意思仍可保留。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":13},{"front":"specific to","meaning":"……特有的","examples":[{"en":"The expressions are specific to the source and target languages.","zh":"這些表達方式是原文語言和目標語言特有的。"},{"en":"Specific to something means belonging especially to that thing or situation.","zh":"某事特有的，是指特別屬於該事物或情況。"},{"en":"Some jokes are specific to school life and may not work in a workplace.","zh":"有些笑話是校園生活特有的，可能不適用於職場。"},{"en":"Language-specific expressions need careful translation because outsiders may not share the context.","zh":"語言特有的表達需要小心翻譯，因為外人未必共享語境。"},{"en":"This phrase highlights uniqueness to a particular group or system.","zh":"這個短語突出某群體或系統的獨特性。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":13},{"front":"source language","meaning":"原文語言","examples":[{"en":"Italian is the source language in this example.","zh":"在這個例子中，意大利語是原文語言。"},{"en":"The source language is the original language from which something is translated.","zh":"原文語言是某內容被翻譯前的原本語言。"},{"en":"If a Chinese article is translated into English, Chinese is the source language.","zh":"如果一篇中文文章被翻譯成英文，中文就是原文語言。"},{"en":"Understanding the source language helps translators avoid losing tone and culture.","zh":"理解原文語言幫助譯者避免失去語氣和文化。"},{"en":"This phrase contrasts with the target language.","zh":"這個短語與目標語言相對。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":13},{"front":"later on","meaning":"後來","examples":[{"en":"Later on, the subtitle A sign of destiny appears.","zh":"後來，字幕 “A sign of destiny” 出現。"},{"en":"Later on means at a later time in the story or explanation.","zh":"後來，是指在故事或解釋中較後的時間。"},{"en":"Later on, the teacher gives harder examples after students understand the basics.","zh":"後來，當學生理解基礎後，老師給出較難例子。"},{"en":"This phrase helps organise events in sequence.","zh":"這個短語幫助按次序組織事件。"},{"en":"It signals that the discussion is moving forward.","zh":"它表示討論正在向前推進。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":13},{"front":"A sign of destiny.","meaning":"「命運的徵兆。」","examples":[{"en":"A sign of destiny appears when several people are speaking at the same time.","zh":"當幾個人同時說話時，“A sign of destiny” 這句字幕出現。"},{"en":"A sign of destiny means something that seems to show what fate has planned.","zh":"命運的徵兆，是指某事看似顯示命運安排了甚麼。"},{"en":"A character may call a lucky meeting “a sign of destiny.”","zh":"角色可能把一次幸運相遇稱為「命運的徵兆」。"},{"en":"The phrase sounds meaningful because it suggests events are not accidental.","zh":"這個短語聽起來有意義，因為它暗示事件並非偶然。"},{"en":"In subtitles, it may represent only the most important line in a crowded scene.","zh":"在字幕中，它可能只代表擁擠場景中最重要的一句話。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":13},{"front":"with equal force","meaning":"以同等力度","examples":[{"en":"Two or three people speak with equal force.","zh":"兩三個人以同等力度說話。"},{"en":"With equal force means with similar strength, loudness or importance.","zh":"以同等力度，是指以相似強度、音量或重要性。"},{"en":"In a heated meeting, several speakers may argue with equal force.","zh":"在激烈會議中，幾位講者可能以同等力度爭論。"},{"en":"When many voices carry equal force, subtitlers cannot translate every line fully.","zh":"當多個聲音具有同等力度，字幕譯者不能完整翻譯每一句。"},{"en":"This phrase describes balanced intensity among speakers.","zh":"這個短語描述說話者之間平衡的強度。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":13},{"front":"at the same time","meaning":"同時","examples":[{"en":"Several people are speaking at the same time.","zh":"幾個人同時說話。"},{"en":"At the same time means simultaneously or during the same moment.","zh":"同時是指在同一刻或同一時間內。"},{"en":"Students should not all answer at the same time because no one can hear clearly.","zh":"學生不應同時回答，因為沒有人能聽清楚。"},{"en":"When speakers talk at the same time, subtitles may need to condense the message.","zh":"當說話者同時說話，字幕可能需要濃縮訊息。"},{"en":"This phrase describes overlapping actions.","zh":"這個短語描述重疊發生的動作。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":13},{"front":"space and time constraints","meaning":"空間和時間限制","examples":[{"en":"Space and time constraints make full translation impossible.","zh":"空間和時間限制令完整翻譯變得不可能。"},{"en":"Space and time constraints are limits on subtitle length and viewing time.","zh":"空間和時間限制，是對字幕長度和觀看時間的限制。"},{"en":"A subtitle cannot include a long paragraph if it stays on screen for only two seconds.","zh":"如果字幕只在螢幕上停留兩秒，就不能包括一整段長文字。"},{"en":"These constraints force translators to choose the most important meaning.","zh":"這些限制迫使譯者選擇最重要意思。"},{"en":"This phrase explains why subtitles are often shorter than speech.","zh":"這個短語解釋為何字幕常比說話短。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":13},{"front":"render it impossible to","meaning":"使……變得不可能","examples":[{"en":"The constraints render it impossible to translate every speaker.","zh":"這些限制使翻譯每位說話者變得不可能。"},{"en":"Render it impossible to do something means make that action unable to be done.","zh":"使做某事變得不可能，是指令該行動不能完成。"},{"en":"Heavy rain may render it impossible to hold sports day outdoors.","zh":"大雨可能使戶外舉行運動會變得不可能。"},{"en":"In subtitling, fast overlapping speech can make full translation impossible.","zh":"在字幕翻譯中，快速重疊說話會令完整翻譯不可能。"},{"en":"This phrase describes a condition that blocks an action completely.","zh":"這個短語描述完全阻礙行動的條件。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":13},{"front":"have them all translated","meaning":"把它們全部翻譯出來","examples":[{"en":"There is not enough space to have them all translated.","zh":"沒有足夠空間把它們全部翻譯出來。"},{"en":"To have them all translated means to translate every item or every speaker.","zh":"把它們全部翻譯出來，是指翻譯每一項或每位說話者。"},{"en":"A teacher may not have all student comments translated during a short meeting.","zh":"在短會議中，老師可能無法把所有學生留言全部翻譯出來。"},{"en":"When space is limited, translators may choose only the central message.","zh":"當空間有限，譯者可能只選擇核心訊息。"},{"en":"This phrase stresses complete translation of several parts.","zh":"這個短語強調多個部分的完整翻譯。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":13},{"front":"quoted subtitle","meaning":"引用的字幕","examples":[{"en":"Only the quoted subtitle appears on screen.","zh":"只有引用的字幕出現在螢幕上。"},{"en":"A quoted subtitle is the exact subtitle being discussed or cited.","zh":"引用的字幕，是正在討論或引用的確切字幕。"},{"en":"In an essay, a student may analyse one quoted subtitle from a film scene.","zh":"在文章中，學生可能分析電影場景中的一句引用字幕。"},{"en":"Quoting one subtitle helps focus the discussion on a specific translation choice.","zh":"引用一句字幕有助把討論集中於具體翻譯選擇。"},{"en":"This phrase refers to the subtitle selected as evidence.","zh":"這個短語指被選作證據的字幕。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":13},{"front":"strategy known as Condensation","meaning":"稱為「濃縮」的策略","examples":[{"en":"The subtitle uses the strategy known as Condensation.","zh":"這句字幕使用稱為「濃縮」的策略。"},{"en":"The strategy known as Condensation is the method of shortening speech into fewer words.","zh":"稱為「濃縮」的策略，是把說話縮短成較少字詞的方法。"},{"en":"A translator uses condensation when a long speech must fit a short subtitle slot.","zh":"當一段長說話必須放入短字幕時間，譯者會使用濃縮。"},{"en":"Condensation keeps the main idea while removing less important details.","zh":"濃縮保留主要意思，同時刪去較不重要細節。"},{"en":"This phrase names a specific subtitling method.","zh":"這個短語命名一種具體字幕翻譯方法。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":14},{"front":"Condensation","meaning":"濃縮策略","examples":[{"en":"Condensation shortens the message because of time or space limits.","zh":"濃縮策略因時間或空間限制而縮短訊息。"},{"en":"Condensation is a subtitling strategy that reduces length while keeping the key meaning.","zh":"濃縮是一種字幕翻譯策略，透過減少長度來保留關鍵意思。"},{"en":"A translator may condense “I really cannot believe what just happened” into “Unbelievable.”","zh":"譯者可能把 “I really cannot believe what just happened” 濃縮成 “Unbelievable.”"},{"en":"Condensation is necessary when viewers cannot read long subtitles quickly.","zh":"當觀眾不能快速讀長字幕時，濃縮是必要的。"},{"en":"This strategy sacrifices some detail to protect understanding.","zh":"這種策略犧牲部分細節，以保護理解。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":14},{"front":"an Italian word referring to","meaning":"指……的意大利詞語","examples":[{"en":"Scopa is an Italian word referring to a variation of the card game.","zh":"Scopa 是指該紙牌遊戲一種變體的意大利詞語。"},{"en":"An Italian word referring to something means an Italian term that names or describes it.","zh":"指某事的意大利詞語，是命名或描述該事物的意大利語術語。"},{"en":"A cooking show may use an Italian word referring to a special kind of pasta.","zh":"烹飪節目可能使用指某種特別意粉的意大利詞語。"},{"en":"Cultural terms can be difficult when the target language has no exact equivalent.","zh":"當目標語言沒有精確對應詞，文化術語就會困難。"},{"en":"This phrase links a foreign word with its meaning.","zh":"這個短語把外語詞與其意思連接起來。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":14},{"front":"a variation of","meaning":"……的一種變體","examples":[{"en":"Scopa is a variation of the central card game.","zh":"Scopa 是主要紙牌遊戲的一種變體。"},{"en":"A variation of something is a different form or version of it.","zh":"某物的一種變體，是其不同形式或版本。"},{"en":"A local bakery may sell a variation of a traditional cake with less sugar.","zh":"本地麵包店可能出售一種少糖版傳統蛋糕。"},{"en":"Variations keep a basic idea while changing details or rules.","zh":"變體保留基本概念，但改變細節或規則。"},{"en":"This phrase describes a related but not identical form.","zh":"這個短語描述相關但不完全相同的形式。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":14},{"front":"central card game","meaning":"主要紙牌遊戲","examples":[{"en":"Scopa is related to the central card game in the movie.","zh":"Scopa 與電影中的主要紙牌遊戲有關。"},{"en":"The central card game is the main card game around which the film’s events revolve.","zh":"主要紙牌遊戲，是電影事件圍繞其展開的核心紙牌遊戲。"},{"en":"In a story about gambling, the central card game can drive the plot.","zh":"在關於賭博的故事中，主要紙牌遊戲可以推動情節。"},{"en":"If viewers understand the game’s role, they understand the stakes better.","zh":"如果觀眾理解遊戲的作用，就更能理解賭注的重要性。"},{"en":"This phrase identifies the key game in the film.","zh":"這個短語指出電影中的關鍵遊戲。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":14},{"front":"unique to","meaning":"……獨有的","examples":[{"en":"The term is unique to Italy.","zh":"這個詞是意大利獨有的。"},{"en":"Unique to something means found only in that place, group or situation.","zh":"某物獨有的，是指只存在於該地方、群體或情況中。"},{"en":"A festival may be unique to one village and unknown elsewhere.","zh":"一個節日可能是某條村獨有，而其他地方不知道。"},{"en":"Terms unique to one culture are often difficult to translate directly.","zh":"某一文化獨有的詞語通常難以直接翻譯。"},{"en":"This phrase highlights cultural specificity.","zh":"這個短語突出文化特定性。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":14},{"front":"equivalent word","meaning":"對應詞","examples":[{"en":"There is no equivalent word in English.","zh":"英語中沒有對應詞。"},{"en":"An equivalent word is a word in another language with the same or very similar meaning.","zh":"對應詞是在另一語言中有相同或非常相似意思的詞。"},{"en":"Some food names have no equivalent word because the dish does not exist elsewhere.","zh":"有些食物名稱沒有對應詞，因為該菜式在其他地方不存在。"},{"en":"Without an equivalent word, translators may explain, borrow or paraphrase.","zh":"沒有對應詞時，譯者可能解釋、借用或意譯。"},{"en":"This phrase focuses on vocabulary matching across languages.","zh":"這個短語聚焦跨語言詞彙配對。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":14},{"front":"Resignation","meaning":"放棄翻譯策略；保留原文策略","examples":[{"en":"Resignation leaves a term in the original language.","zh":"放棄翻譯策略會把詞語保留在原文語言中。"},{"en":"Resignation is a subtitling strategy where the translator does not translate a difficult term.","zh":"放棄翻譯策略，是譯者不翻譯困難詞語的字幕策略。"},{"en":"A subtitle may leave a cultural game name unchanged when no equivalent exists.","zh":"當沒有對應詞，字幕可能保留某文化遊戲名稱不變。"},{"en":"Resignation works only if the context still makes the meaning clear.","zh":"只有當語境仍令意思清楚時，保留原文策略才有效。"},{"en":"This strategy accepts that full translation is not possible.","zh":"這種策略接受完整翻譯不可能。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":14},{"front":"leave the word in the original language","meaning":"保留原文詞語","examples":[{"en":"The subtitler leaves the word in the original language.","zh":"字幕譯者保留原文詞語。"},{"en":"To leave the word in the original language means not to translate it into the target language.","zh":"保留原文詞語，是指不把它翻譯成目標語言。"},{"en":"A menu may leave the word ramen in Japanese because diners recognise it.","zh":"餐牌可能保留日文 ramen，因為食客認得它。"},{"en":"Leaving a word untranslated can preserve local flavour but may confuse viewers.","zh":"保留詞語不翻譯可以保留本地味道，但可能令觀眾困惑。"},{"en":"This phrase describes borrowing rather than translating.","zh":"這個短語描述借用，而不是翻譯。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":14},{"front":"remain obvious from the context","meaning":"從語境中仍然清楚","examples":[{"en":"The meaning remains obvious from the context.","zh":"意思從語境中仍然清楚。"},{"en":"To remain obvious from the context means to stay clear because surrounding information explains it.","zh":"從語境中仍然清楚，是指周圍資訊解釋了它，所以意思仍清楚。"},{"en":"Even if a menu leaves sushi untranslated, the meaning may remain obvious from photos.","zh":"即使餐牌保留 sushi 不翻譯，圖片也可能令意思仍然清楚。"},{"en":"Context can help viewers understand a foreign term without direct translation.","zh":"語境可以幫助觀眾不靠直接翻譯也理解外語詞。"},{"en":"This phrase explains why leaving a word untranslated may still work.","zh":"這個短語解釋為何保留詞語不翻譯仍可能有效。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":14},{"front":"minimal and unlikely situations","meaning":"極少且不大可能出現的情況","examples":[{"en":"Only in minimal and unlikely situations is Resignation acceptable.","zh":"只有在極少且不大可能出現的情況下，放棄翻譯策略才可接受。"},{"en":"Minimal and unlikely situations are rare cases with very limited need for explanation.","zh":"極少且不大可能出現的情況，是很罕見且幾乎不需要解釋的個案。"},{"en":"A translator may leave a word untranslated only when the scene clearly explains it.","zh":"只有當場景清楚解釋詞語時，譯者才可能保留原文不譯。"},{"en":"Because these situations are rare, Resignation cannot be used freely.","zh":"因為這些情況很罕見，放棄翻譯策略不能隨便使用。"},{"en":"This phrase stresses that the strategy has narrow limits.","zh":"這個短語強調該策略限制很窄。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":14},{"front":"become acceptable","meaning":"變得可接受","examples":[{"en":"The strategy becomes acceptable only in limited situations.","zh":"這種策略只有在有限情況下才變得可接受。"},{"en":"To become acceptable means to become suitable or allowed under certain conditions.","zh":"變得可接受，是指在某些條件下變得合適或被容許。"},{"en":"A late submission may become acceptable if a student has a medical reason.","zh":"如果學生有醫療原因，遲交功課可能變得可接受。"},{"en":"In translation, an unusual strategy becomes acceptable when it does not confuse viewers.","zh":"在翻譯中，當不尋常策略不會令觀眾困惑時，它才變得可接受。"},{"en":"This phrase shows that acceptability depends on context.","zh":"這個短語顯示可接受性取決於語境。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":15},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter from the options.","zh":"學生從選項中選出正確字母。"},{"en":"To choose the correct letter means to select the option label that gives the right answer.","zh":"選出正確字母，是指選擇代表正確答案的選項標籤。"},{"en":"In a multiple-choice question, students may choose A, B, C or D.","zh":"在選擇題中，學生可能選 A、B、C 或 D。"},{"en":"The correct letter depends on meaning, not just repeated words.","zh":"正確字母取決於意思，而不只是重複字眼。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":15},{"front":"appeal to larger audiences","meaning":"吸引較大的觀眾群","examples":[{"en":"Dubbing may appeal to larger audiences.","zh":"配音可能吸引較大的觀眾群。"},{"en":"To appeal to larger audiences means to attract more viewers or a wider group of people.","zh":"吸引較大的觀眾群，是指吸引更多觀眾或更廣泛的人。"},{"en":"A film with subtitles and dubbing may appeal to larger audiences than one with no translation.","zh":"同時有字幕和配音的電影，可能比沒有翻譯的電影吸引更大觀眾群。"},{"en":"Easier access can increase audience size.","zh":"更容易接觸可以增加觀眾數量。"},{"en":"This phrase focuses on popularity and reach.","zh":"這個短語聚焦受歡迎程度和接觸範圍。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":15},{"front":"seem silly","meaning":"顯得滑稽；顯得愚蠢","examples":[{"en":"Poor dubbing can seem silly.","zh":"差劣配音可能顯得滑稽。"},{"en":"To seem silly means to appear foolish, ridiculous or not serious.","zh":"顯得滑稽，是指看起來愚蠢、可笑或不嚴肅。"},{"en":"A serious scene may seem silly if the voice acting is exaggerated.","zh":"如果配音演繹過分誇張，嚴肅場面可能顯得滑稽。"},{"en":"If translation choices sound unnatural, viewers may laugh instead of feeling emotion.","zh":"如果翻譯選擇不自然，觀眾可能發笑而不是感受情緒。"},{"en":"This phrase describes an unwanted comic effect.","zh":"這個短語描述不想要的喜劇效果。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":15},{"front":"increase appreciation of","meaning":"增加對……的欣賞","examples":[{"en":"A good translation may increase appreciation of the film.","zh":"好翻譯可能增加觀眾對電影的欣賞。"},{"en":"To increase appreciation of something means to help people value or enjoy it more.","zh":"增加對某事的欣賞，是指幫助人更重視或更享受它。"},{"en":"Clear museum labels can increase appreciation of old paintings.","zh":"清楚博物館標籤可以增加人們對舊畫的欣賞。"},{"en":"Good subtitles make humour, emotion and culture easier to notice.","zh":"好字幕令幽默、情感和文化更容易被注意。"},{"en":"This phrase links explanation with deeper enjoyment.","zh":"這個短語把解釋與更深享受連接起來。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":15},{"front":"cultural audits","meaning":"文化審視；文化審核","examples":[{"en":"Cultural audits help subtitlers understand both cultures.","zh":"文化審視幫助字幕譯者理解兩種文化。"},{"en":"Cultural audits are checks that compare cultural values, habits and meanings before translation.","zh":"文化審視是在翻譯前比較文化價值、習慣和意思的檢查。"},{"en":"An advertising team may use cultural audits before launching a campaign abroad.","zh":"廣告團隊在海外推出宣傳前，可能使用文化審核。"},{"en":"These audits reduce mistakes caused by jokes, customs or social rules.","zh":"這些審核減少由笑話、習俗或社會規則造成的錯誤。"},{"en":"This phrase refers to cultural preparation work.","zh":"這個短語指文化準備工作。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":15},{"front":"look at one culture","meaning":"只審視一種文化","examples":[{"en":"A cultural audit should not look at one culture only.","zh":"文化審視不應只審視一種文化。"},{"en":"To look at one culture means to examine only one cultural side of the translation situation.","zh":"只審視一種文化，是指只考察翻譯情況中的一方文化。"},{"en":"A translator who looks only at Italian culture may forget what English viewers know.","zh":"只審視意大利文化的譯者，可能忘記英語觀眾知道甚麼。"},{"en":"Good subtitle work compares both source and audience cultures.","zh":"好的字幕工作會比較原文化和觀眾文化。"},{"en":"This phrase warns against one-sided cultural analysis.","zh":"這個短語提醒人不要進行單方面文化分析。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":15},{"front":"long and involved","meaning":"冗長而複雜","examples":[{"en":"A cultural audit does not have to be long and involved.","zh":"文化審視不必冗長而複雜。"},{"en":"Long and involved means lengthy, complicated and detailed.","zh":"冗長而複雜，是指篇幅長、程序複雜且細節很多。"},{"en":"A simple checklist may be better than a long and involved report before a small project.","zh":"小項目前，一份簡單清單可能比冗長複雜報告更好。"},{"en":"Preparation can be useful even when it is brief.","zh":"即使準備簡短，也可以有用。"},{"en":"This phrase describes something that takes much time and complexity.","zh":"這個短語描述需要很多時間和複雜性的事物。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":15},{"front":"help comprehension","meaning":"有助理解","examples":[{"en":"Cultural audits help comprehension of subtitles.","zh":"文化審視有助理解字幕。"},{"en":"To help comprehension means to make understanding easier.","zh":"有助理解，是指令理解更容易。"},{"en":"Clear examples help comprehension when students learn new grammar.","zh":"學生學習新文法時，清楚例子有助理解。"},{"en":"Cultural preparation helps viewers understand meaning beyond literal words.","zh":"文化準備幫助觀眾理解字面字詞以外的意思。"},{"en":"This phrase focuses on improving understanding.","zh":"這個短語聚焦改善理解。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":15},{"front":"normally required","meaning":"通常需要","examples":[{"en":"The question asks whether cultural audits are normally required.","zh":"題目問文化審視是否通常需要。"},{"en":"Normally required means usually needed in ordinary practice.","zh":"通常需要，是指在一般做法中通常必要。"},{"en":"A passport is normally required for international travel.","zh":"國際旅行通常需要護照。"},{"en":"If a process is normally required, skipping it may create risk.","zh":"如果某程序通常需要，跳過它可能帶來風險。"},{"en":"This phrase refers to usual expectation, not one rare case.","zh":"這個短語指一般期望，而不是罕見個案。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":15},{"front":"the movie which was examined","meaning":"被研究的電影","examples":[{"en":"The movie which was examined was an Italian film.","zh":"被研究的電影是一部意大利電影。"},{"en":"The movie which was examined means the film chosen for analysis in the study.","zh":"被研究的電影，是指研究中被選作分析的電影。"},{"en":"In class, the movie examined may be used to teach translation strategies.","zh":"在課堂中，被研究的電影可能用來教授翻譯策略。"},{"en":"Choosing one film lets the writer discuss real examples in detail.","zh":"選擇一部電影讓作者能詳細討論真實例子。"},{"en":"This phrase identifies the specific sample being studied.","zh":"這個短語指出被研究的具體樣本。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":15},{"front":"common human themes","meaning":"普遍的人類主題","examples":[{"en":"The movie has common human themes.","zh":"這部電影有普遍的人類主題。"},{"en":"Common human themes are ideas many people can recognise, such as love, greed or hope.","zh":"普遍的人類主題，是許多人都能認出的想法，例如愛、貪婪或希望。"},{"en":"A film about family sacrifice has common human themes across cultures.","zh":"關於家庭犧牲的電影在不同文化中都有普遍人類主題。"},{"en":"These themes help viewers connect with stories from unfamiliar places.","zh":"這些主題幫助觀眾與陌生地方的故事產生連繫。"},{"en":"This phrase is close in meaning to universal themes.","zh":"這個短語意思接近普世主題。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":16},{"front":"surprising ending","meaning":"出人意料的結局","examples":[{"en":"The option mentions a surprising ending.","zh":"該選項提到出人意料的結局。"},{"en":"A surprising ending is a conclusion that viewers do not expect.","zh":"出人意料的結局，是觀眾沒有預期到的收結。"},{"en":"A mystery film may have a surprising ending when the quietest character is guilty.","zh":"推理電影中，如果最安靜的角色是罪犯，就可能有出人意料的結局。"},{"en":"Surprising endings work best when they still feel believable.","zh":"出人意料的結局在仍然可信時效果最好。"},{"en":"This phrase describes the effect of a story’s final part.","zh":"這個短語描述故事最後部分的效果。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":16},{"front":"be set in an Italian city","meaning":"以意大利城市為背景","examples":[{"en":"The option says that the movie is set in an Italian city.","zh":"該選項說電影以意大利城市為背景。"},{"en":"To be set in an Italian city means the story happens in a city in Italy.","zh":"以意大利城市為背景，是指故事發生在意大利的一個城市。"},{"en":"A film set in Rome may show traffic, cafés and historic buildings.","zh":"以羅馬為背景的電影可能展示交通、咖啡店和歷史建築。"},{"en":"Setting matters because city life differs from village life.","zh":"背景很重要，因為城市生活不同於鄉村生活。"},{"en":"This phrase describes location, not nationality of the actors.","zh":"這個短語描述地點，而不是演員國籍。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":16},{"front":"involve two main actors","meaning":"涉及兩位主要演員","examples":[{"en":"The option says that the movie involves two main actors.","zh":"該選項說電影涉及兩位主要演員。"},{"en":"To involve two main actors means to have two central performers in the story.","zh":"涉及兩位主要演員，是指故事有兩位核心表演者。"},{"en":"A small drama may involve two main actors talking in one apartment.","zh":"一部小型劇情片可能涉及兩位主要演員在一間公寓中對話。"},{"en":"The number of actors can affect how a story is structured.","zh":"演員數量會影響故事如何組織。"},{"en":"This phrase describes cast structure.","zh":"這個短語描述演員結構。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":16},{"front":"relatively new game","meaning":"相對較新的遊戲","examples":[{"en":"The option describes Scopone as a relatively new game.","zh":"該選項把 Scopone 描述為相對較新的遊戲。"},{"en":"A relatively new game is a game that has not existed for a long historical period.","zh":"相對較新的遊戲，是指沒有長久歷史的遊戲。"},{"en":"An online mobile game from last year is relatively new compared with chess.","zh":"與國際象棋相比，去年推出的手機遊戲相對較新。"},{"en":"If a game is ancient, calling it relatively new would be inaccurate.","zh":"如果一種遊戲很古老，稱它為相對較新就不準確。"},{"en":"This phrase compares age against older games or traditions.","zh":"這個短語把年齡與較古老遊戲或傳統作比較。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":16},{"front":"known to the Western audience","meaning":"為西方觀眾所熟悉","examples":[{"en":"The option asks whether Scopone is known to the Western audience.","zh":"該選項問 Scopone 是否為西方觀眾所熟悉。"},{"en":"Known to the Western audience means familiar to viewers from Western cultural backgrounds.","zh":"為西方觀眾所熟悉，是指西方文化背景的觀眾認識它。"},{"en":"A local festival may not be known to an overseas audience.","zh":"本地節日可能不為海外觀眾所熟悉。"},{"en":"If a term is not known to viewers, the translator may need explanation or adaptation.","zh":"如果一個詞不為觀眾熟悉，譯者可能需要解釋或改寫。"},{"en":"This phrase concerns audience familiarity.","zh":"這個短語涉及觀眾熟悉程度。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":16},{"front":"a bland term","meaning":"平淡的用詞","examples":[{"en":"The English title uses a bland term.","zh":"英文片名使用平淡的用詞。"},{"en":"A bland term is a word that is plain, safe and not very vivid.","zh":"平淡的用詞，是普通、安全但不太生動的字詞。"},{"en":"Calling a colourful street festival an “event” uses a bland term.","zh":"把色彩豐富的街頭節日稱為 “event”，就是使用平淡用詞。"},{"en":"Bland terms can reduce confusion but also weaken cultural flavour.","zh":"平淡用詞可以減少困惑，但也削弱文化味道。"},{"en":"This phrase describes wording that lacks force or specificity.","zh":"這個短語描述缺乏力量或具體性的措辭。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":16},{"front":"a variation called scopa","meaning":"一種叫 scopa 的變體","examples":[{"en":"Scopone has a variation called scopa.","zh":"Scopone 有一種叫 scopa 的變體。"},{"en":"A variation called scopa means one related version of the game is named scopa.","zh":"一種叫 scopa 的變體，是指該遊戲有一個相關版本名為 scopa。"},{"en":"A board game may have a faster variation called speed mode.","zh":"一種棋盤遊戲可能有一種叫 speed mode 的較快變體。"},{"en":"Naming a variation helps viewers understand that the games are related.","zh":"命名變體幫助觀眾理解這些遊戲彼此相關。"},{"en":"This phrase explains a specific version within a larger game family.","zh":"這個短語解釋較大遊戲系列中的特定版本。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":16},{"front":"write TRUE, FALSE, or NOT GIVEN","meaning":"寫上 TRUE、FALSE 或 NOT GIVEN","examples":[{"en":"Students write TRUE, FALSE, or NOT GIVEN for each statement.","zh":"學生為每項陳述寫上 TRUE、FALSE 或 NOT GIVEN。"},{"en":"Write TRUE, FALSE, or NOT GIVEN means decide whether each statement matches, contradicts or is not stated in the text.","zh":"寫上 TRUE、FALSE 或 NOT GIVEN，是指判斷每項陳述是否與文章一致、矛盾或沒有提及。"},{"en":"In IELTS reading, students must not use outside knowledge for these answers.","zh":"在 IELTS 閱讀中，學生不能用外部知識回答這類題。"},{"en":"This task tests careful comparison between statements and passage information.","zh":"這項任務測試學生仔細比較陳述與篇章資料。"},{"en":"The phrase gives the exact answer format.","zh":"這個短語給出確切答案格式。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":16},{"front":"agree with the information","meaning":"與資料一致","examples":[{"en":"TRUE means the statement agrees with the information.","zh":"TRUE 表示陳述與資料一致。"},{"en":"To agree with the information means to match what the passage says.","zh":"與資料一致，是指符合篇章所說內容。"},{"en":"A statement agrees with the information if it says the same thing in different words.","zh":"如果陳述用不同字眼說出相同意思，它就與資料一致。"},{"en":"Students should choose TRUE only when the text clearly supports the statement.","zh":"只有當文本清楚支持陳述時，學生才應選 TRUE。"},{"en":"This phrase focuses on textual support.","zh":"這個短語聚焦文本支持。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":16},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"FALSE means the statement contradicts the information.","zh":"FALSE 表示陳述與資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the passage says.","zh":"與資料相矛盾，是指說出與篇章相反的內容。"},{"en":"If the passage says the film is Italian, “the film is French” contradicts the information.","zh":"如果篇章說電影是意大利的，「電影是法國的」就與資料相矛盾。"},{"en":"Students should choose FALSE only when there is clear opposition in the text.","zh":"只有當文本有清楚相反內容時，學生才應選 FALSE。"},{"en":"This phrase describes conflict between a statement and the passage.","zh":"這個短語描述陳述與篇章之間的衝突。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":16},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"NOT GIVEN means there is no information on this.","zh":"NOT GIVEN 表示沒有相關資料。"},{"en":"No information on this means the passage does not say enough to decide.","zh":"沒有相關資料，是指篇章沒有提供足夠內容讓人判斷。"},{"en":"If a text names a film but not its ticket sales, there is no information on its profit.","zh":"如果文章提到電影名稱但沒有票房，就沒有關於其盈利的資料。"},{"en":"Students should not guess when the passage gives no information.","zh":"當篇章沒有資料時，學生不應猜測。"},{"en":"This phrase explains when NOT GIVEN is correct.","zh":"這個短語解釋何時應選 NOT GIVEN。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":17},{"front":"an English title","meaning":"英文片名","examples":[{"en":"The English title may create a subtitling problem.","zh":"英文片名可能造成字幕翻譯問題。"},{"en":"An English title is the film name used for English-speaking audiences.","zh":"英文片名是給英語觀眾使用的電影名稱。"},{"en":"A translated English title may be simpler than the original title.","zh":"翻譯後的英文片名可能比原片名簡單。"},{"en":"If an English title loses cultural meaning, viewers may receive a weaker first impression.","zh":"如果英文片名失去文化意思，觀眾得到的第一印象可能較弱。"},{"en":"This phrase refers to the title in the target language.","zh":"這個短語指目標語言中的片名。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":17},{"front":"interesting strategies","meaning":"有趣的策略","examples":[{"en":"The question refers to Transfer and Imitation as strategies.","zh":"題目把轉移和模仿稱為策略。"},{"en":"Interesting strategies are methods worth noticing because they solve problems in different ways.","zh":"有趣的策略，是值得注意的方法，因為它們以不同方式解決問題。"},{"en":"A teacher may show interesting strategies for remembering difficult spelling.","zh":"老師可能展示記住困難拼寫的有趣策略。"},{"en":"In subtitling, different strategies reveal how translators balance meaning and limits.","zh":"在字幕翻譯中，不同策略揭示譯者如何平衡意思和限制。"},{"en":"This phrase points to methods that deserve attention.","zh":"這個短語指出值得注意的方法。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":17},{"front":"often used","meaning":"經常使用","examples":[{"en":"The question asks whether Paraphrasing is often used.","zh":"題目問意譯是否經常使用。"},{"en":"Often used means used frequently or in many cases.","zh":"經常使用，是指頻繁或在許多情況下使用。"},{"en":"In language classes, role-play is often used to practise speaking.","zh":"在語言課堂中，角色扮演經常用來練習口語。"},{"en":"A strategy is often used when it solves a common problem well.","zh":"當一種策略能很好解決常見問題，它就會經常使用。"},{"en":"This phrase describes frequency of use.","zh":"這個短語描述使用頻率。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":17},{"front":"can be used in many situations","meaning":"可在很多情況下使用","examples":[{"en":"The question asks whether Resignation can be used in many situations.","zh":"題目問放棄翻譯策略是否可在很多情況下使用。"},{"en":"Can be used in many situations means suitable across many different contexts.","zh":"可在很多情況下使用，是指適合許多不同語境。"},{"en":"A simple greeting can be used in many situations, but slang cannot.","zh":"簡單問候語可在很多情況下使用，但俚語不一定可以。"},{"en":"Resignation is not broadly useful if viewers may be confused by untranslated words.","zh":"如果觀眾可能被未翻譯詞語弄糊塗，放棄翻譯策略就不算廣泛有用。"},{"en":"This phrase tests whether a method has wide application.","zh":"這個短語測試某方法是否有廣泛應用。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":17},{"front":"match the translation example with","meaning":"將翻譯例子與……配對","examples":[{"en":"Students match the translation example with its associated fact.","zh":"學生將翻譯例子與其相關事實配對。"},{"en":"To match the translation example with something means to pair it with the correct explanation.","zh":"將翻譯例子與某事配對，是指把它與正確解釋相連。"},{"en":"Students may match a subtitle example with the strategy it uses.","zh":"學生可能把字幕例子與其使用的策略配對。"},{"en":"Matching tasks require attention to meaning, not just similar words.","zh":"配對題需要注意意思，而不只是相似字眼。"},{"en":"This phrase describes a classification exercise.","zh":"這個短語描述分類練習。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":17},{"front":"associated fact","meaning":"相關事實","examples":[{"en":"Each translation example has an associated fact.","zh":"每個翻譯例子都有一項相關事實。"},{"en":"An associated fact is a piece of information connected with a particular example.","zh":"相關事實是與某個特定例子相連的資料。"},{"en":"A film title may have an associated fact about its cultural meaning.","zh":"電影片名可能有一項關於其文化意思的相關事實。"},{"en":"Matching the fact correctly shows that students understand the example.","zh":"正確配對事實顯示學生理解例子。"},{"en":"This phrase refers to supporting information linked to an item.","zh":"這個短語指與某項目相關的支持資料。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":17},{"front":"a practical decision","meaning":"實際考慮下的決定","examples":[{"en":"Condensation can be a practical decision when space is limited.","zh":"當空間有限，濃縮可以是實際考慮下的決定。"},{"en":"A practical decision is a choice made because it works under real conditions.","zh":"實際考慮下的決定，是因符合真實條件而作出的選擇。"},{"en":"A teacher may make a practical decision to shorten an activity when time is running out.","zh":"時間快用完時，老師可能作出縮短活動的實際決定。"},{"en":"In subtitling, practical decisions are shaped by reading speed and screen space.","zh":"在字幕翻譯中，實際決定受閱讀速度和螢幕空間影響。"},{"en":"This phrase emphasises usefulness over perfection.","zh":"這個短語強調實用性多於完美。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":17},{"front":"clarified by the situation","meaning":"由情境說明清楚","examples":[{"en":"The meaning of scopa is clarified by the situation.","zh":"scopa 的意思由情境說明清楚。"},{"en":"Clarified by the situation means made clear by what is happening around it.","zh":"由情境說明清楚，是指由周圍正在發生的事令意思變清楚。"},{"en":"A foreign food name may be clarified by the situation if a character is eating it.","zh":"如果角色正在吃某外國食物，該食物名稱可能由情境說明清楚。"},{"en":"Context can explain a word even when no direct translation is given.","zh":"即使沒有直接翻譯，語境也可以解釋詞語。"},{"en":"This phrase shows how meaning can come from the scene.","zh":"這個短語顯示意思如何來自場景。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":17},{"front":"using other words","meaning":"使用其他字眼","examples":[{"en":"Paraphrasing involves using other words with the same meaning.","zh":"意譯涉及使用其他字眼表達相同意思。"},{"en":"Using other words means expressing an idea differently while keeping its meaning.","zh":"使用其他字眼，是指用不同方式表達想法，同時保留其意思。"},{"en":"A student can explain a difficult sentence by using other words.","zh":"學生可以使用其他字眼解釋困難句子。"},{"en":"Translators use other words when direct translation sounds unnatural.","zh":"當直接翻譯不自然，譯者會使用其他字眼。"},{"en":"This phrase describes rewording, not changing the message.","zh":"這個短語描述改寫措辭，而不是改變訊息。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":17},{"front":"with the same meaning","meaning":"意思相同","examples":[{"en":"Different words may be used with the same meaning.","zh":"可以使用不同字詞，但意思相同。"},{"en":"With the same meaning means expressing an idea without changing what it says.","zh":"意思相同，是指表達某想法而不改變其內容。"},{"en":"“Begin” and “start” can often be used with the same meaning.","zh":"“Begin” 和 “start” 常可使用並意思相同。"},{"en":"In translation, different wording may preserve meaning better than literal wording.","zh":"在翻譯中，不同措辭可能比字面措辭更能保留意思。"},{"en":"This phrase focuses on meaning equivalence.","zh":"這個短語聚焦意思等同。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":17},{"front":"probably exists in the source language","meaning":"可能存在於原文語言中","examples":[{"en":"The same idiom probably exists in the source language.","zh":"同一慣用語可能存在於原文語言中。"},{"en":"Probably exists in the source language means it is likely that the original language has that expression.","zh":"可能存在於原文語言中，是指原本語言很可能有該表達。"},{"en":"A translator may guess that a similar proverb probably exists in the source language.","zh":"譯者可能推測相似諺語存在於原文語言中。"},{"en":"If an expression exists in both languages, translation may preserve idiomatic force.","zh":"如果一個表達存在於兩種語言中，翻譯可能保留慣用語力量。"},{"en":"This phrase presents a cautious conclusion about the original language.","zh":"這個短語提出關於原文語言的謹慎結論。"}],"source":"83 - Subtitling - Some Strategies.pdf","sourcePage":18}],"ielts/reading/passage-2/Practice 84":[{"front":"unsung and lowly creatures","meaning":"默默無聞而低等的生物","examples":[{"en":"Darwin praised earthworms as unsung and lowly creatures that transformed the land.","zh":"Darwin 讚揚蚯蚓是默默無聞而低等、卻改造土地的生物。"},{"en":"Unsung and lowly creatures are humble animals that receive little praise even though they are important.","zh":"unsung and lowly creatures 指雖然重要但很少受到讚揚的卑微動物。"},{"en":"Bees, worms, and tiny soil organisms can be unsung creatures because people often ignore their work.","zh":"蜜蜂、蚯蚓和微小土壤生物都可以是默默無聞的生物，因為人們常忽略牠們的工作。"},{"en":"When important work is hidden, people may fail to notice the creatures that support life.","zh":"當重要工作隱藏起來，人們可能沒有注意到支撐生命的生物。"},{"en":"This phrase is useful when something modest or overlooked has a large effect.","zh":"當某物謙卑、被忽視但影響巨大時，這個短語很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":1},{"front":"earthworms","meaning":"蚯蚓","examples":[{"en":"Earthworms play an important role in improving the soil.","zh":"蚯蚓在改善土壤方面發揮重要作用。"},{"en":"Earthworms are long, soft-bodied animals that live in soil and help break down organic matter.","zh":"earthworms 指生活在土壤中、幫助分解有機物的長而柔軟的動物。"},{"en":"Gardeners often welcome earthworms because they help keep soil loose and healthy.","zh":"園丁常歡迎蚯蚓，因為牠們幫助保持土壤鬆軟健康。"},{"en":"When earthworms feed and move, they improve the soil’s structure and nutrients.","zh":"當蚯蚓進食和移動時，牠們會改善土壤結構和養分。"},{"en":"This word is common in biology, farming, gardening, and ecology.","zh":"這個詞常見於生物、農業、園藝和生態語境。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":1},{"front":"be likely to attract much attention","meaning":"可能吸引很多注意","examples":[{"en":"Earthworms are not creatures likely to attract much attention.","zh":"蚯蚓不是可能吸引很多注意的生物。"},{"en":"To be likely to attract much attention means to be expected to make people notice or become interested.","zh":"be likely to attract much attention 指預期會令人注意或感興趣。"},{"en":"A colourful bird is likely to attract much attention in a quiet garden.","zh":"一隻色彩鮮艷的鳥在安靜花園中可能吸引很多注意。"},{"en":"Plain or hidden things may not attract attention even when they are very useful.","zh":"樸素或隱藏的東西即使很有用，也未必吸引注意。"},{"en":"This phrase is useful when discussing how noticeable something is.","zh":"討論某物有多顯眼時，這個短語很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":1},{"front":"secretive, silent and slow-moving","meaning":"隱蔽、沉默而行動緩慢的","examples":[{"en":"Earthworms are secretive, silent and slow-moving creatures.","zh":"蚯蚓是隱蔽、沉默而行動緩慢的生物。"},{"en":"Secretive, silent and slow-moving means hidden, quiet, and moving at a low speed.","zh":"secretive, silent and slow-moving 指隱藏、安靜，而且移動速度慢。"},{"en":"A shy cat under a sofa may seem secretive, silent and slow-moving.","zh":"躲在梳化下的害羞貓可能顯得隱蔽、沉默而行動緩慢。"},{"en":"Such creatures are easy to overlook because they do not make noise or move quickly.","zh":"這類生物容易被忽略，因為牠們不吵鬧，也不快速移動。"},{"en":"This phrase creates an image of quiet, unnoticed behaviour.","zh":"這個短語營造出安靜、 unnoticed 的行為形象。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":1},{"front":"featureless","meaning":"沒有明顯特徵的","examples":[{"en":"Earthworms may seem featureless, but they are biologically important.","zh":"蚯蚓可能看似沒有明顯特徵，但在生物學上很重要。"},{"en":"Featureless means having no obvious or distinctive features.","zh":"featureless 指沒有明顯或獨特特徵。"},{"en":"A plain grey wall may look featureless until someone paints a mural on it.","zh":"一面普通灰牆可能看起來沒有明顯特徵，直到有人在上面畫壁畫。"},{"en":"Something featureless can be underestimated because it does not immediately catch the eye.","zh":"沒有明顯特徵的東西可能被低估，因為它不會立即吸引眼球。"},{"en":"This word describes appearance, not actual importance.","zh":"這個詞描述外觀，而不是實際重要性。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":1},{"front":"think much of","meaning":"看重；重視","examples":[{"en":"Almost no one would think much of earthworms at first.","zh":"起初幾乎沒有人會看重蚯蚓。"},{"en":"To think much of something means to value it or regard it as important.","zh":"think much of something 指重視某物或認為它重要。"},{"en":"A child may not think much of old family photos until hearing the stories behind them.","zh":"孩子可能不太重視舊家庭照片，直到聽到背後故事。"},{"en":"People often fail to think much of small workers or small creatures until their role becomes clear.","zh":"人們常不重視小人物或小生物，直到其作用變得清楚。"},{"en":"This phrase is usually used in negative sentences, such as not think much of.","zh":"這個短語通常用於否定句，例如 not think much of。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":1},{"front":"It may be doubted whether","meaning":"可令人懷疑是否……","examples":[{"en":"It may be doubted whether many animals have played such an important part in the world.","zh":"可令人懷疑是否有很多動物在世界上發揮過如此重要的作用。"},{"en":"It may be doubted whether means it is uncertain or questionable whether something is true.","zh":"It may be doubted whether 指某事是否真實仍不確定或值得質疑。"},{"en":"It may be doubted whether a short course alone can solve deep writing problems.","zh":"可令人懷疑是否單靠短期課程就能解決深層寫作問題。"},{"en":"This phrase introduces careful doubt rather than strong denial.","zh":"這個短語引出謹慎懷疑，而不是強烈否定。"},{"en":"It is formal and often used in academic or reflective writing.","zh":"它較正式，常用於學術或反思性寫作。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":1},{"front":"play an important part in","meaning":"在……中發揮重要作用","examples":[{"en":"Earthworms have played an important part in the history of the world.","zh":"蚯蚓在世界歷史中發揮了重要作用。"},{"en":"To play an important part in something means to have a significant role in it.","zh":"play an important part in something 指在某事中有重要角色。"},{"en":"Teachers play an important part in helping students build confidence.","zh":"老師在幫助學生建立信心方面發揮重要作用。"},{"en":"Small actions can play an important part in producing large long-term changes.","zh":"小行動可以在產生長遠重大變化中發揮重要作用。"},{"en":"This phrase is useful when explaining contribution or influence.","zh":"解釋貢獻或影響時，這個短語很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":1},{"front":"the history of the world","meaning":"世界歷史","examples":[{"en":"Darwin believed that earthworms had affected the history of the world.","zh":"Darwin 相信蚯蚓影響了世界歷史。"},{"en":"The history of the world means the long story of how life, land, people, and societies have changed over time.","zh":"history of the world 指生命、土地、人類和社會如何隨時間改變的漫長故事。"},{"en":"A small invention can affect the history of the world if it changes how people live.","zh":"如果一項小發明改變人類生活，它也可以影響世界歷史。"},{"en":"In Darwin’s view, earthworms mattered because they changed the land itself.","zh":"在 Darwin 看來，蚯蚓重要，因為牠們改變土地本身。"},{"en":"This phrase sounds very broad and serious.","zh":"這個短語聽起來範圍很廣而且很嚴肅。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":1},{"front":"lowly organised creatures","meaning":"結構低等的生物","examples":[{"en":"Darwin described earthworms as lowly organised creatures.","zh":"Darwin 把蚯蚓描述為結構低等的生物。"},{"en":"Lowly organised creatures are animals with simple body structures compared with more complex animals.","zh":"lowly organised creatures 指與較複雜動物相比，身體結構簡單的動物。"},{"en":"Some simple sea animals may be described as lowly organised creatures in older biological writing.","zh":"在較舊的生物學寫作中，一些簡單海洋動物可能被描述為結構低等的生物。"},{"en":"A creature can be structurally simple but still ecologically important.","zh":"生物可以結構簡單，但仍在生態上很重要。"},{"en":"This phrase sounds old-fashioned and scientific.","zh":"這個短語聽起來較舊式和科學化。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":1},{"front":"high praise indeed","meaning":"確實是很高的評價","examples":[{"en":"Darwin’s comment was high praise indeed for such a simple-looking animal.","zh":"Darwin 的評論對如此外表簡單的動物來說，確實是很高的評價。"},{"en":"High praise indeed means very strong praise, especially when it is surprising.","zh":"high praise indeed 指非常高的讚揚，尤其是令人驚訝時。"},{"en":"If a strict teacher says an essay is excellent, that is high praise indeed.","zh":"如果嚴格老師說一篇文章很出色，那確實是很高的評價。"},{"en":"Praise feels stronger when it comes from someone respected or difficult to impress.","zh":"當讚揚來自受尊敬或難以取悅的人，它會顯得更有分量。"},{"en":"This phrase emphasises that the compliment is unusually strong.","zh":"這個短語強調讚美異常強烈。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":1},{"front":"slimy, muscular and moist","meaning":"黏滑、有肌肉而濕潤的","examples":[{"en":"An earthworm is basically a slimy, muscular and moist tube.","zh":"蚯蚓基本上是一條黏滑、有肌肉而濕潤的管。"},{"en":"Slimy, muscular and moist describes something slippery, made of muscle, and wet.","zh":"slimy, muscular and moist 指滑溜、有肌肉，而且濕潤。"},{"en":"A fish can feel slimy and moist when taken out of water.","zh":"魚離水後摸起來可以黏滑而濕潤。"},{"en":"A worm’s moist body helps it move and breathe through its skin.","zh":"蚯蚓濕潤的身體幫助牠移動並透過皮膚呼吸。"},{"en":"This phrase describes physical texture and body structure.","zh":"這個短語描述實體質感和身體結構。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":2},{"front":"segmented tube","meaning":"分節的管狀身體","examples":[{"en":"The body of an earthworm is like a segmented tube.","zh":"蚯蚓的身體像分節的管狀身體。"},{"en":"A segmented tube is a tube-shaped body divided into many small sections.","zh":"segmented tube 指被分成許多小節的管狀身體。"},{"en":"A toy snake made of many linked rings looks like a segmented tube.","zh":"由許多連接環組成的玩具蛇看起來像分節管。"},{"en":"Segments help some animals bend, contract, and move through tight spaces.","zh":"分節幫助某些動物彎曲、收縮並穿過狹窄空間。"},{"en":"This phrase describes the worm’s body form.","zh":"這個短語描述蚯蚓的身體形態。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":2},{"front":"hermaphroditic","meaning":"雌雄同體的","examples":[{"en":"An earthworm is hermaphroditic, with both male and female reproductive parts.","zh":"蚯蚓是雌雄同體的，具有雄性和雌性生殖部位。"},{"en":"Hermaphroditic means having both male and female reproductive organs or functions.","zh":"hermaphroditic 指同時具有雄性和雌性生殖器官或功能。"},{"en":"Some plants and simple animals are hermaphroditic, so one individual has both reproductive roles.","zh":"有些植物和簡單動物是雌雄同體的，因此一個個體具有兩種生殖角色。"},{"en":"This feature can make reproduction easier when individuals are spread out.","zh":"當個體分散時，這種特徵可以令繁殖較容易。"},{"en":"This word is biological and should be used carefully in scientific contexts.","zh":"這個詞屬生物學用語，應在科學語境中謹慎使用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":2},{"front":"meaning that","meaning":"意思是","examples":[{"en":"Earthworms are hermaphroditic, meaning that one creature has both male and female segments.","zh":"蚯蚓是雌雄同體的，意思是一個生物有雄性和雌性節段。"},{"en":"Meaning that introduces an explanation of what the previous phrase means.","zh":"meaning that 用來引出對前面短語意思的解釋。"},{"en":"The class is compulsory, meaning that every student must attend.","zh":"這堂課是 compulsory，意思是每個學生都必須出席。"},{"en":"Writers use this phrase to make technical ideas easier to understand.","zh":"作者使用這個短語令技術性想法更容易理解。"},{"en":"It is useful when a term needs immediate clarification.","zh":"當術語需要即時澄清時，它很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":2},{"front":"male and female segments","meaning":"雄性及雌性節段","examples":[{"en":"An earthworm has both male and female segments in its body.","zh":"蚯蚓身體中有雄性及雌性節段。"},{"en":"Male and female segments are body sections connected with male and female reproductive functions.","zh":"male and female segments 指與雄性和雌性生殖功能有關的身體部分。"},{"en":"In biology class, students may label body parts that have different reproductive roles.","zh":"在生物課中，學生可能標示具有不同生殖角色的身體部分。"},{"en":"These segments help explain why earthworms are described as hermaphroditic.","zh":"這些節段幫助解釋為何蚯蚓被描述為雌雄同體。"},{"en":"This phrase is technical and refers to reproductive anatomy.","zh":"這個短語較技術性，指生殖解剖結構。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":2},{"front":"contain testes","meaning":"含有睪丸","examples":[{"en":"Some segments of an earthworm contain testes.","zh":"蚯蚓的某些節段含有睪丸。"},{"en":"To contain testes means to have male reproductive organs inside.","zh":"contain testes 指內部有雄性生殖器官。"},{"en":"In a biology diagram, certain sections may contain organs used for reproduction.","zh":"在生物圖表中，某些部分可能含有用於繁殖的器官。"},{"en":"Knowing which body parts contain testes helps students understand the reproductive process.","zh":"知道哪些身體部分含有睪丸，有助學生理解繁殖過程。"},{"en":"This phrase is scientific and describes internal anatomy.","zh":"這個短語屬科學用語，描述內部解剖。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":2},{"front":"contain eggs","meaning":"含有卵子","examples":[{"en":"Other segments of an earthworm contain eggs.","zh":"蚯蚓的其他節段含有卵子。"},{"en":"To contain eggs means to have female reproductive cells inside.","zh":"contain eggs 指內部有雌性生殖細胞。"},{"en":"Some animals carry eggs inside their bodies before laying or releasing them.","zh":"有些動物在產卵或釋放卵之前，身體內帶有卵子。"},{"en":"Egg-containing parts are necessary for producing the next generation.","zh":"含有卵子的部分對產生下一代很必要。"},{"en":"This phrase is used in biology and reproduction topics.","zh":"這個短語用於生物和繁殖主題。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":2},{"front":"reproductive fluids","meaning":"生殖液","examples":[{"en":"Worms release, exchange and store reproductive fluids.","zh":"蚯蚓釋放、交換並儲存生殖液。"},{"en":"Reproductive fluids are bodily fluids involved in reproduction.","zh":"reproductive fluids 指參與繁殖的身體液體。"},{"en":"In many animals, reproductive fluids carry cells or substances needed for fertilisation.","zh":"在許多動物中，生殖液攜帶受精所需的細胞或物質。"},{"en":"Exchanging these fluids is part of how earthworms reproduce.","zh":"交換這些液體是蚯蚓繁殖過程的一部分。"},{"en":"This phrase is scientific and should be used in biological contexts.","zh":"這個短語較科學，應用於生物語境。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":2},{"front":"a long complicated process","meaning":"一個漫長而複雜的過程","examples":[{"en":"A long complicated process leads to the formation of an egg case.","zh":"一個漫長而複雜的過程導致卵囊形成。"},{"en":"A long complicated process is a series of steps that takes time and is not simple.","zh":"long complicated process 指需要時間且不簡單的一連串步驟。"},{"en":"Applying to university can be a long complicated process with forms, essays, and interviews.","zh":"申請大學可能是一個漫長而複雜的過程，包括表格、文章和面試。"},{"en":"When a process has many stages, mistakes can delay the final result.","zh":"當過程有許多階段，錯誤可以延遲最終結果。"},{"en":"This phrase emphasises both time and complexity.","zh":"這個短語同時強調時間和複雜性。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":2},{"front":"eventually lead to","meaning":"最終導致","examples":[{"en":"The reproductive process eventually leads to the secretion of an egg case.","zh":"生殖過程最終導致卵囊分泌。"},{"en":"To eventually lead to something means to result in it after some time or several stages.","zh":"eventually lead to something 指經過一段時間或幾個階段後造成某結果。"},{"en":"Daily practice can eventually lead to better speaking confidence.","zh":"每天練習最終可以帶來更好的說話信心。"},{"en":"Small repeated actions often lead to big results over time.","zh":"反覆的小行動常隨時間帶來重大結果。"},{"en":"This phrase shows delayed cause and effect.","zh":"這個短語顯示延遲的因果關係。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":2},{"front":"secretion of an egg case","meaning":"分泌卵囊","examples":[{"en":"The process leads to the secretion of an egg case.","zh":"這個過程導致卵囊分泌。"},{"en":"Secretion of an egg case means the body produces and releases a protective case for eggs.","zh":"secretion of an egg case 指身體產生並釋放保護卵子的外囊。"},{"en":"Some animals protect developing young by producing a covering or case around them.","zh":"有些動物透過在幼體周圍產生覆蓋物或囊來保護牠們。"},{"en":"The egg case helps protect young worms before they emerge.","zh":"卵囊在幼蚯蚓冒出前幫助保護牠們。"},{"en":"This phrase describes a biological reproductive step.","zh":"這個短語描述一個生物繁殖步驟。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":2},{"front":"fully formed","meaning":"發育完整的","examples":[{"en":"Small but fully formed worms emerge from the egg case.","zh":"細小但發育完整的蚯蚓從卵囊中冒出。"},{"en":"Fully formed means complete in structure, though possibly still small.","zh":"fully formed 指結構完整，雖然可能仍然很小。"},{"en":"A fully formed baby bird has the basic body parts needed to grow further.","zh":"發育完整的雛鳥具備進一步成長所需的基本身體部分。"},{"en":"Something can be fully formed but not yet full-sized.","zh":"某物可以發育完整，但尚未達到完整大小。"},{"en":"This phrase describes completeness of development.","zh":"這個短語描述發育的完整程度。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":3},{"front":"emerge","meaning":"出現；冒出","examples":[{"en":"Small worms emerge from the egg case.","zh":"小蚯蚓從卵囊中冒出。"},{"en":"To emerge means to come out, appear, or become visible.","zh":"emerge 指出來、出現或變得可見。"},{"en":"Students emerge from the classroom when the bell rings.","zh":"鐘聲響起時，學生從課室走出來。"},{"en":"Young animals may emerge from eggs, nests, or burrows after they develop enough.","zh":"幼小動物發育足夠後，可能從蛋、巢或洞穴中冒出。"},{"en":"This verb is useful for describing something hidden becoming visible.","zh":"這個動詞適合描述隱藏事物變得可見。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":3},{"front":"reach full size","meaning":"長至完整大小","examples":[{"en":"Young earthworms reach full size in about one year.","zh":"幼蚯蚓約一年內長至完整大小。"},{"en":"To reach full size means to grow to the normal adult size.","zh":"reach full size 指長到正常成年大小。"},{"en":"A puppy may take many months to reach full size.","zh":"小狗可能需要許多個月才長至完整大小。"},{"en":"Growth time matters because young animals may be more vulnerable before reaching full size.","zh":"成長時間很重要，因為幼小動物在長至完整大小前可能較脆弱。"},{"en":"This phrase describes physical development.","zh":"這個短語描述身體發展。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":3},{"front":"rarely seen","meaning":"很少被看見","examples":[{"en":"Earthworms are rarely seen because they spend their lives underground.","zh":"蚯蚓很少被看見，因為牠們一生都在地下度過。"},{"en":"Rarely seen means not often observed or noticed.","zh":"rarely seen 指不常被觀察到或注意到。"},{"en":"A shy neighbour may be rarely seen because she leaves early and returns late.","zh":"害羞的鄰居可能很少被看見，因為她早出晚歸。"},{"en":"Things that are rarely seen can still be very common if they are hidden.","zh":"很少被看見的東西若隱藏起來，仍可能數量很多。"},{"en":"This phrase separates visibility from actual number.","zh":"這個短語把可見程度與實際數量分開。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":3},{"front":"spend one’s whole life underground","meaning":"一生都在地下度過","examples":[{"en":"Earthworms spend their whole lives underground.","zh":"蚯蚓一生都在地下度過。"},{"en":"To spend one’s whole life underground means to live almost entirely below the surface of the earth.","zh":"spend one’s whole life underground 指幾乎完全在地面以下生活。"},{"en":"Some animals spend most of their lives underground to avoid heat and predators.","zh":"有些動物大部分生命都在地下度過，以避開高溫和掠食者。"},{"en":"Living underground can protect worms but also makes them easy for humans to overlook.","zh":"地下生活可以保護蚯蚓，但也令牠們容易被人忽略。"},{"en":"This phrase describes a hidden way of life.","zh":"這個短語描述隱蔽的生活方式。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":3},{"front":"after heavy rains","meaning":"在大雨過後","examples":[{"en":"Earthworms sometimes appear on the surface after heavy rains.","zh":"蚯蚓有時在大雨過後出現在地面上。"},{"en":"After heavy rains means following periods of strong or prolonged rainfall.","zh":"after heavy rains 指強烈或長時間降雨之後。"},{"en":"Streets may flood after heavy rains if drains are blocked.","zh":"如果排水渠堵塞，街道在大雨過後可能水浸。"},{"en":"Rain can change animal behaviour by making soil wet or burrows flooded.","zh":"雨水可以透過令泥土潮濕或地洞被淹而改變動物行為。"},{"en":"This phrase gives the time and condition under which something happens.","zh":"這個短語提供某事發生的時間和條件。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":3},{"front":"on the surface","meaning":"在地面上","examples":[{"en":"Earthworms may be found on the surface after heavy rains.","zh":"蚯蚓可能在大雨過後出現在地面上。"},{"en":"On the surface means on the top or outside layer of something.","zh":"on the surface 指在某物的頂層或外層。"},{"en":"After rain, leaves and rubbish may float on the surface of a puddle.","zh":"下雨後，樹葉和垃圾可能浮在水坑表面。"},{"en":"For earthworms, being on the surface can be risky because sunlight and birds are dangerous.","zh":"對蚯蚓來說，在地面上可能有風險，因為陽光和鳥類很危險。"},{"en":"This phrase often contrasts with being underground or inside.","zh":"這個短語常與地下或內部形成對比。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":3},{"front":"apparently stranded","meaning":"看似擱淺的","examples":[{"en":"After heavy rain, earthworms on the surface may appear apparently stranded.","zh":"大雨過後，地面上的蚯蚓可能看似擱淺。"},{"en":"Apparently stranded means seeming to be stuck somewhere and unable to move away safely.","zh":"apparently stranded 指看起來被困在某處，無法安全離開。"},{"en":"A bicycle with a flat tyre may leave a student apparently stranded far from school.","zh":"單車爆胎可能令學生看似困在離學校很遠的地方。"},{"en":"Earthworms on concrete may look stranded because they cannot burrow back down easily.","zh":"混凝土上的蚯蚓可能看似擱淺，因為牠們難以重新鑽回地下。"},{"en":"This phrase describes how a situation appears, not always what is permanently true.","zh":"這個短語描述情況看起來如何，不一定表示永久如此。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":3},{"front":"hypotheses are put forward","meaning":"提出假設","examples":[{"en":"Three hypotheses are put forward to explain why worms appear after rain.","zh":"有三個假設被提出，用來解釋為何蚯蚓在雨後出現。"},{"en":"When hypotheses are put forward, possible explanations are suggested for a question or problem.","zh":"hypotheses are put forward 指為某個問題提出可能解釋。"},{"en":"In science class, students may put forward hypotheses before doing an experiment.","zh":"在科學課中，學生可能在做實驗前提出假設。"},{"en":"Different hypotheses can be tested to see which best fits the evidence.","zh":"不同假設可以被測試，以看哪一個最符合證據。"},{"en":"This phrase is formal and common in scientific explanation.","zh":"這個短語較正式，常見於科學解釋。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":3},{"front":"stormwater","meaning":"暴雨積水","examples":[{"en":"Stormwater may flood the worms’ burrows.","zh":"暴雨積水可能淹浸蚯蚓的地洞。"},{"en":"Stormwater is rainwater that collects and flows after a storm.","zh":"stormwater 指暴風雨後聚集和流動的雨水。"},{"en":"Stormwater can fill drains, streets, gardens, and low-lying fields.","zh":"暴雨積水可以充滿排水渠、街道、花園和低窪田地。"},{"en":"If stormwater enters animal homes, it may force them to move.","zh":"如果暴雨積水進入動物的住所，可能迫使牠們移動。"},{"en":"This word is common in weather, drainage, and environmental contexts.","zh":"這個詞常見於天氣、排水和環境語境。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":3},{"front":"flood their burrows","meaning":"淹浸牠們的地洞","examples":[{"en":"Stormwater may flood their burrows and force them upwards.","zh":"暴雨積水可能淹浸牠們的地洞，迫使牠們向上移動。"},{"en":"To flood their burrows means to fill their underground tunnels with water.","zh":"flood their burrows 指用水填滿牠們的地下通道。"},{"en":"Heavy rain may flood ant nests and make ants move to higher ground.","zh":"大雨可能淹浸蟻巢，令螞蟻移到較高地方。"},{"en":"When burrows flood, animals may come to the surface to avoid drowning or discomfort.","zh":"當地洞被淹，動物可能到地面以避免溺水或不適。"},{"en":"This phrase describes water entering underground homes.","zh":"這個短語描述水進入地下住所。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":3},{"front":"force them upwards","meaning":"迫使牠們向上移動","examples":[{"en":"Flooded burrows may force earthworms upwards.","zh":"被水淹的地洞可能迫使蚯蚓向上移動。"},{"en":"To force them upwards means to make them move toward the surface.","zh":"force them upwards 指使牠們往地面方向移動。"},{"en":"Smoke in a building may force people upwards if lower floors are blocked.","zh":"如果低層被阻塞，建築物內的煙可能迫使人向上移動。"},{"en":"When underground spaces become unsafe, animals may be forced upwards into open areas.","zh":"當地下空間變得不安全，動物可能被迫向上移到開放地方。"},{"en":"This phrase shows movement caused by pressure or danger.","zh":"這個短語顯示由壓力或危險造成的移動。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":4},{"front":"alternatively","meaning":"或者；另一種可能是","examples":[{"en":"Alternatively, worms may use wet conditions to travel more quickly.","zh":"或者，蚯蚓可能利用潮濕環境更快移動。"},{"en":"Alternatively means another possible explanation or choice is being offered.","zh":"alternatively 指提出另一個可能解釋或選擇。"},{"en":"We can take the bus; alternatively, we can walk if the weather is good.","zh":"我們可以乘巴士；或者，如果天氣好，我們可以步行。"},{"en":"This word helps writers present a second option without rejecting the first immediately.","zh":"這個詞幫助作者提出第二個選項，而不立即否定第一個。"},{"en":"It is common in explanations with several possible causes.","zh":"它常見於有幾個可能原因的解釋中。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":4},{"front":"take advantage of","meaning":"利用","examples":[{"en":"Worms may take advantage of wet conditions to move across the surface.","zh":"蚯蚓可能利用潮濕環境在地面上移動。"},{"en":"To take advantage of something means to use a situation for benefit.","zh":"take advantage of something 指利用某情況取得好處。"},{"en":"Students can take advantage of free library resources before exams.","zh":"學生可以在考試前利用免費圖書館資源。"},{"en":"Wet ground can create a short opportunity for worms to travel safely above ground.","zh":"潮濕地面可以為蚯蚓創造短暫機會，在地面上較安全地移動。"},{"en":"This phrase can be positive or negative depending on context.","zh":"這個短語可正面也可負面，視乎語境。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":4},{"front":"wet conditions","meaning":"潮濕環境","examples":[{"en":"Wet conditions may help earthworms travel more quickly.","zh":"潮濕環境可能幫助蚯蚓更快移動。"},{"en":"Wet conditions are situations where the ground or environment contains much moisture.","zh":"wet conditions 指地面或環境含有大量水分的情況。"},{"en":"Wet conditions after rain can make grass slippery and soil soft.","zh":"雨後潮濕環境可以令草地濕滑、泥土柔軟。"},{"en":"For earthworms, moisture can reduce the risk of drying out while moving.","zh":"對蚯蚓來說，水分可以降低移動時乾死的風險。"},{"en":"This phrase is common in weather, farming, and outdoor activity contexts.","zh":"這個短語常見於天氣、農業和戶外活動語境。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":4},{"front":"through the open air","meaning":"穿過露天空氣中","examples":[{"en":"Earthworms may travel through the open air after rain.","zh":"蚯蚓可能在雨後穿過露天空氣中移動。"},{"en":"Through the open air means across an exposed space above ground, not through soil or a tunnel.","zh":"through the open air 指穿過地面以上暴露的空間，而不是穿過土壤或隧道。"},{"en":"A smell can travel through the open air from a kitchen to the street.","zh":"氣味可以從廚房穿過露天空氣傳到街上。"},{"en":"For earthworms, moving through open air is faster but riskier than burrowing.","zh":"對蚯蚓來說，穿過露天空氣移動較快，但也較危險。"},{"en":"This phrase contrasts exposed movement with hidden movement.","zh":"這個短語把暴露移動與隱蔽移動作對比。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":4},{"front":"compared with","meaning":"與……相比","examples":[{"en":"Travelling above ground may be quicker compared with burrowing below ground.","zh":"與在地下鑽洞相比，在地面上移動可能更快。"},{"en":"Compared with means considered next to another thing to show difference.","zh":"compared with 指把某事與另一事放在一起考慮，以顯示差異。"},{"en":"Cycling is often faster compared with walking for short city journeys.","zh":"對短途城市旅程而言，踩單車與步行相比通常更快。"},{"en":"Comparisons help readers understand why one option may be chosen over another.","zh":"比較幫助讀者理解為何選擇一個選項而不是另一個。"},{"en":"This phrase is useful when showing contrast in speed, cost, size, or effect.","zh":"顯示速度、成本、大小或效果差異時，這個短語很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":4},{"front":"burrow beneath the ground","meaning":"在地下鑽洞","examples":[{"en":"Earthworms usually burrow beneath the ground.","zh":"蚯蚓通常在地下鑽洞。"},{"en":"To burrow beneath the ground means to dig or move through soil under the surface.","zh":"burrow beneath the ground 指在地面下挖掘或穿過土壤移動。"},{"en":"Rabbits may burrow beneath the ground to make safe homes.","zh":"兔子可能在地下鑽洞，建造安全住所。"},{"en":"Burrowing protects animals from heat, light, and predators.","zh":"鑽洞可以保護動物免受高溫、光線和掠食者威脅。"},{"en":"This phrase describes underground movement or digging.","zh":"這個短語描述地下移動或挖掘。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":4},{"front":"meet and mate","meaning":"相遇並交配","examples":[{"en":"Wet conditions may help earthworms meet and mate.","zh":"潮濕環境可能幫助蚯蚓相遇並交配。"},{"en":"To meet and mate means to find another individual and reproduce with it.","zh":"meet and mate 指找到另一個個體並與其繁殖。"},{"en":"Some frogs come out after rain to meet and mate in ponds.","zh":"有些青蛙在雨後出來，到池塘相遇並交配。"},{"en":"Moist conditions may increase movement, which makes meeting a partner easier.","zh":"潮濕環境可能增加移動，使尋找配偶更容易。"},{"en":"This phrase describes a basic reproductive behaviour.","zh":"這個短語描述基本繁殖行為。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":4},{"front":"whatever the case","meaning":"無論情況如何","examples":[{"en":"Whatever the case, worms can become trapped on hard surfaces.","zh":"無論情況如何，蚯蚓都可能被困在堅硬表面上。"},{"en":"Whatever the case means no matter which explanation is true.","zh":"whatever the case 指不論哪個解釋是真的。"},{"en":"The bus may be late because of traffic or weather; whatever the case, we should leave early.","zh":"巴士可能因交通或天氣而遲到；無論情況如何，我們都應早點出門。"},{"en":"This phrase helps move from uncertain causes to a clear conclusion.","zh":"這個短語幫助從不確定原因轉到清楚結論。"},{"en":"It is useful when several possibilities lead to the same result.","zh":"當幾種可能性都導致同一結果時，它很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":4},{"front":"find themselves on","meaning":"發現自己處於……","examples":[{"en":"Earthworms may find themselves on concrete after heavy rain.","zh":"蚯蚓可能在大雨後發現自己處於混凝土上。"},{"en":"To find themselves on something means to suddenly or unexpectedly be in that place or situation.","zh":"find themselves on something 指突然或意外地身處某地或某情況。"},{"en":"A student may find herself on the wrong bus after reading the sign carelessly.","zh":"學生若粗心看錯標示，可能發現自己坐上錯巴士。"},{"en":"When animals move after rain, they may end up on surfaces they cannot dig into.","zh":"動物雨後移動時，可能最終到了不能鑽入的表面上。"},{"en":"This phrase often suggests an unwanted or unexpected situation.","zh":"這個短語常暗示不想要或意外的情況。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":4},{"front":"hardened earth","meaning":"硬化的泥土","examples":[{"en":"Earthworms can become trapped on hardened earth.","zh":"蚯蚓可能被困在硬化的泥土上。"},{"en":"Hardened earth is soil that has become hard and difficult to dig into.","zh":"hardened earth 指變硬且難以挖入的泥土。"},{"en":"After many dry days, a garden path may turn into hardened earth.","zh":"連續多日乾燥後，花園小路可能變成硬化的泥土。"},{"en":"If soil becomes hardened, worms may not be able to burrow back underground quickly.","zh":"如果泥土變硬，蚯蚓可能無法快速鑽回地下。"},{"en":"This phrase describes soil condition.","zh":"這個短語描述土壤狀態。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":4},{"front":"effectively trapped","meaning":"實際上被困住","examples":[{"en":"On concrete or rock, earthworms are effectively trapped.","zh":"在混凝土或岩石上，蚯蚓實際上被困住。"},{"en":"Effectively trapped means trapped in practical terms, even if there is no cage or wall.","zh":"effectively trapped 指實際上被困，即使沒有籠或牆。"},{"en":"A lift that stops between floors can leave passengers effectively trapped.","zh":"停在兩層之間的電梯可以令乘客實際上被困住。"},{"en":"A worm on concrete may be unable to escape because it cannot dig down.","zh":"混凝土上的蚯蚓可能無法逃脫，因為牠不能往下鑽。"},{"en":"This phrase describes a real result, not necessarily a visible prison.","zh":"這個短語描述實際結果，而不一定是可見的監禁。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":5},{"front":"at dawn","meaning":"在黎明時","examples":[{"en":"Earthworms may die quickly if they are trapped at dawn.","zh":"如果蚯蚓在黎明時被困，牠們可能很快死亡。"},{"en":"At dawn means at the time when daylight first appears in the morning.","zh":"at dawn 指早上日光剛出現的時候。"},{"en":"Farmers often begin work at dawn to avoid the midday heat.","zh":"農夫常在黎明時開始工作，以避開正午炎熱。"},{"en":"For worms, dawn can be dangerous because sunlight and birds soon appear.","zh":"對蚯蚓來說，黎明可能危險，因為陽光和鳥類很快出現。"},{"en":"This phrase gives a precise time of day.","zh":"這個短語提供一天中的精確時間。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":5},{"front":"during high summer","meaning":"在盛夏期間","examples":[{"en":"Earthworms can die quickly on hard surfaces during high summer.","zh":"在盛夏期間，蚯蚓在堅硬表面上可能很快死亡。"},{"en":"During high summer means in the hottest or most intense part of summer.","zh":"during high summer 指在夏季最炎熱或最強烈的時段。"},{"en":"During high summer, people may avoid outdoor exercise at noon.","zh":"在盛夏期間，人們可能避免中午戶外運動。"},{"en":"Strong heat can dry out soft-bodied animals very quickly.","zh":"強烈高溫可以令柔軟身體的動物很快乾掉。"},{"en":"This phrase highlights seasonal heat and risk.","zh":"這個短語強調季節性高溫和風險。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":5},{"front":"in daylight","meaning":"在日光下","examples":[{"en":"Earthworms are vulnerable when they are trapped in daylight.","zh":"蚯蚓在日光下被困時很脆弱。"},{"en":"In daylight means during the time when the sun is up and there is natural light.","zh":"in daylight 指太陽升起、有自然光的時候。"},{"en":"Some animals hide in daylight and feed at night.","zh":"有些動物在日光下躲藏，夜間進食。"},{"en":"Daylight exposes worms to heat, drying, and predators.","zh":"日光令蚯蚓暴露於熱力、乾燥和掠食者之下。"},{"en":"This phrase contrasts with darkness or night-time.","zh":"這個短語與黑暗或夜間形成對比。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":5},{"front":"die due to","meaning":"因……而死亡","examples":[{"en":"Earthworms may die due to bird predation or dehydration.","zh":"蚯蚓可能因鳥類捕食或脫水而死亡。"},{"en":"To die due to something means to die because of that cause.","zh":"die due to something 指因某原因而死亡。"},{"en":"Plants may die due to lack of water during a heatwave.","zh":"植物可能在熱浪期間因缺水而死亡。"},{"en":"Identifying the cause of death helps people understand how to prevent it.","zh":"找出死亡原因有助人們理解如何預防。"},{"en":"This phrase is common in science, health, and environmental writing.","zh":"這個短語常見於科學、健康和環境寫作。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":5},{"front":"bird predation","meaning":"鳥類捕食","examples":[{"en":"Earthworms on the surface may die because of bird predation.","zh":"地面上的蚯蚓可能因鳥類捕食而死亡。"},{"en":"Bird predation means birds hunting and eating other animals.","zh":"bird predation 指鳥類捕獵並吃掉其他動物。"},{"en":"Garden birds may pull worms from wet soil after rain.","zh":"雨後，花園鳥類可能從濕泥中拉出蚯蚓。"},{"en":"When worms are exposed on paths, bird predation becomes more likely.","zh":"當蚯蚓暴露在小路上，鳥類捕食更可能發生。"},{"en":"This phrase describes a predator-prey relationship involving birds.","zh":"這個短語描述涉及鳥類的掠食者與獵物關係。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":5},{"front":"dehydration","meaning":"脫水","examples":[{"en":"Earthworms may die from dehydration if they remain on dry surfaces.","zh":"如果蚯蚓留在乾燥表面上，可能因脫水而死亡。"},{"en":"Dehydration is the dangerous loss of too much water from the body.","zh":"dehydration 指身體失去過多水分的危險狀態。"},{"en":"A runner may suffer dehydration if she exercises in heat without drinking water.","zh":"跑步者若在高溫下運動而不喝水，可能脫水。"},{"en":"Soft-bodied animals dry out quickly when exposed to sun and air.","zh":"身體柔軟的動物暴露於陽光和空氣中時很快乾掉。"},{"en":"This word is common in health and biology.","zh":"這個詞常見於健康和生物語境。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":5},{"front":"go about their hidden business","meaning":"默默進行牠們隱蔽的活動","examples":[{"en":"Worms normally go about their hidden business underground.","zh":"蚯蚓通常在地下默默進行牠們隱蔽的活動。"},{"en":"To go about their hidden business means to carry on their usual activities quietly and unseen.","zh":"go about their hidden business 指安靜而不被看見地進行日常活動。"},{"en":"Night cleaners go about their hidden business after most office workers have left.","zh":"夜間清潔工在大多數辦公室員工離開後默默工作。"},{"en":"Hidden work may be unnoticed, but it can keep a system running smoothly.","zh":"隱藏工作可能不被注意，但可以令系統順利運作。"},{"en":"This phrase suggests quiet, routine activity away from public attention.","zh":"這個短語暗示遠離公眾注意的安靜日常活動。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":5},{"front":"lead to an underestimation of","meaning":"導致對……低估","examples":[{"en":"The hidden lives of worms lead to an underestimation of their numbers.","zh":"蚯蚓隱蔽的生活導致人們低估牠們的數量。"},{"en":"To lead to an underestimation of something means to cause people to think it is smaller or less important than it really is.","zh":"lead to an underestimation of something 指令人以為某事比實際更少或更不重要。"},{"en":"Quiet students may lead teachers to underestimate how much they understand.","zh":"安靜學生可能令老師低估他們理解了多少。"},{"en":"If something is hidden, people may count or value it incorrectly.","zh":"如果某事隱藏起來，人們可能錯誤計算或評價它。"},{"en":"This phrase describes a cause of mistaken low judgement.","zh":"這個短語描述錯誤低估的原因。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":5},{"front":"actual numbers","meaning":"實際數量","examples":[{"en":"The actual numbers of earthworms are much higher than many people imagine.","zh":"蚯蚓的實際數量比許多人想像的高得多。"},{"en":"Actual numbers are the real quantities, not guesses or impressions.","zh":"actual numbers 指真正數量，而不是猜測或印象。"},{"en":"A teacher may check actual numbers before deciding whether attendance is falling.","zh":"老師可能先查看實際數量，再判斷出席率是否下降。"},{"en":"Actual numbers can correct misleading impressions based on what people see.","zh":"實際數量可以修正基於所見而產生的誤導印象。"},{"en":"This phrase is useful when reality differs from expectation.","zh":"當現實與預期不同時，這個短語很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":5},{"front":"arable land","meaning":"可耕地","examples":[{"en":"Darwin estimated how many worms lived in arable land.","zh":"Darwin 估計有多少蚯蚓生活在可耕地中。"},{"en":"Arable land is land suitable for growing crops.","zh":"arable land 指適合種植農作物的土地。"},{"en":"Farmers protect arable land because poor soil can reduce harvests.","zh":"農民保護可耕地，因為貧瘠土壤會減少收成。"},{"en":"Earthworms are important in arable land because crops depend on healthy soil.","zh":"蚯蚓在可耕地中很重要，因為作物依賴健康土壤。"},{"en":"This phrase is common in farming, geography, and environmental studies.","zh":"這個短語常見於農業、地理和環境研究。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":5},{"front":"per acre","meaning":"每英畝","examples":[{"en":"Darwin thought arable land contained about 50,000 worms per acre.","zh":"Darwin 認為可耕地每英畝約有50,000條蚯蚓。"},{"en":"Per acre means for each acre of land.","zh":"per acre 指每一英畝土地。"},{"en":"A farm may produce two tonnes of wheat per acre in a good year.","zh":"農場在好年份每英畝可能生產兩噸小麥。"},{"en":"Measurements per acre help compare land productivity or animal numbers fairly.","zh":"每英畝的量度有助公平比較土地產量或動物數量。"},{"en":"This phrase is used when discussing land area.","zh":"討論土地面積時，會使用這個短語。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":6},{"front":"modern research has suggested that","meaning":"現代研究顯示","examples":[{"en":"Modern research has suggested that worm numbers may be far higher.","zh":"現代研究顯示蚯蚓數量可能高得多。"},{"en":"Modern research has suggested that means recent studies indicate something may be true.","zh":"modern research has suggested that 指近期研究顯示某事可能為真。"},{"en":"Modern research has suggested that sleep affects memory more strongly than people once thought.","zh":"現代研究顯示睡眠對記憶的影響可能比人們以往認為的更強。"},{"en":"Research can update older estimates when better methods become available.","zh":"當更好方法出現，研究可以更新舊估計。"},{"en":"This phrase is cautious because suggested is not as strong as proved.","zh":"這個短語較謹慎，因為 suggested 不如 proved 強。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":6},{"front":"reach as high as","meaning":"高達","examples":[{"en":"The number of worms per acre could reach as high as almost two million.","zh":"每英畝蚯蚓數量可能高達接近二百萬。"},{"en":"To reach as high as means to rise to a very large maximum figure.","zh":"reach as high as 指上升到非常高的最高數字。"},{"en":"Summer temperatures in some cities can reach as high as 40 degrees.","zh":"有些城市夏季氣溫可以高達40度。"},{"en":"Such a phrase emphasises the surprising upper limit of a number.","zh":"這個短語強調令人驚訝的上限。"},{"en":"It is useful when the maximum is impressive or unexpected.","zh":"當最高數字令人印象深刻或意外時，它很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":6},{"front":"putting this another way","meaning":"換句話說","examples":[{"en":"Putting this another way, worms may weigh more than animals grazing above them.","zh":"換句話說，蚯蚓的重量可能超過在牠們上方吃草的動物。"},{"en":"Putting this another way means explaining the same idea in a different form.","zh":"putting this another way 指以另一種形式解釋同一想法。"},{"en":"A teacher may say, “Putting this another way, the problem is not speed but accuracy.”","zh":"老師可能說：「換句話說，問題不在速度，而在準確性。」"},{"en":"Rephrasing can make a difficult idea easier to understand.","zh":"重新表述可以令困難想法更容易理解。"},{"en":"This phrase is useful when translating numbers into a clearer comparison.","zh":"當把數字轉化為更清楚比較時，這個短語很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":6},{"front":"beneath the soil","meaning":"在泥土之下","examples":[{"en":"Earthworms live and feed beneath the soil.","zh":"蚯蚓在泥土之下生活和進食。"},{"en":"Beneath the soil means under the surface layer of the ground.","zh":"beneath the soil 指在地面表層之下。"},{"en":"Plant roots spread beneath the soil to find water and minerals.","zh":"植物根部在泥土之下伸展，以尋找水和礦物質。"},{"en":"Many important processes happen beneath the soil where people cannot see them.","zh":"許多重要過程在人們看不見的泥土之下發生。"},{"en":"This phrase contrasts hidden underground activity with visible surface activity.","zh":"這個短語把隱藏的地下活動與可見地表活動作對比。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":6},{"front":"greater than that of","meaning":"大於……的","examples":[{"en":"The weight of earthworms may be greater than that of grazing animals.","zh":"蚯蚓的重量可能大於吃草動物的重量。"},{"en":"Greater than that of means larger than the amount, weight, or level belonging to another thing.","zh":"greater than that of 指比另一事物的數量、重量或水平更大。"},{"en":"The cost of repairs may be greater than that of buying a new phone.","zh":"維修費用可能大於購買新手機的費用。"},{"en":"This phrase allows comparison without repeating the same noun.","zh":"這個短語讓人作比較時不用重複同一名詞。"},{"en":"It is common in formal comparison sentences.","zh":"它常見於正式比較句。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":6},{"front":"grazing upon its surface","meaning":"在其表面吃草","examples":[{"en":"Cows, horses and sheep may be grazing upon the surface of the soil.","zh":"牛、馬和羊可能在土壤表面吃草。"},{"en":"Grazing upon its surface means feeding on grass or plants growing on top of the land.","zh":"grazing upon its surface 指吃生長在土地表面的草或植物。"},{"en":"Sheep grazing on a hillside slowly move from one patch of grass to another.","zh":"山坡上吃草的羊會慢慢從一片草地移到另一片。"},{"en":"Grazing animals are visible above ground, while worms feed hidden below.","zh":"吃草動物在地面上可見，而蚯蚓在地下隱藏進食。"},{"en":"This phrase contrasts surface feeding with underground feeding.","zh":"這個短語把地表進食與地下進食作對比。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":6},{"front":"just as hungry","meaning":"同樣飢餓；食量同樣大","examples":[{"en":"Earthworms are just as hungry as the animals above them.","zh":"蚯蚓和牠們上方的動物同樣飢餓。"},{"en":"Just as hungry means equally hungry or equally active in needing food.","zh":"just as hungry 指同樣飢餓，或同樣需要食物。"},{"en":"A quiet student may be just as hungry for praise as a confident student.","zh":"安靜學生可能和自信學生同樣渴望讚賞。"},{"en":"The phrase shows that hidden creatures may consume a lot even if they look inactive.","zh":"這個短語顯示隱藏生物即使看似不活躍，也可能消耗很多。"},{"en":"This comparison helps readers take earthworms seriously.","zh":"這個比較幫助讀者認真看待蚯蚓。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":6},{"front":"digestive system","meaning":"消化系統","examples":[{"en":"An earthworm has a simple but effective digestive system.","zh":"蚯蚓有簡單但有效的消化系統。"},{"en":"A digestive system is the set of body parts that breaks down food and absorbs nutrients.","zh":"digestive system 指分解食物並吸收營養的一組身體部位。"},{"en":"In humans, the mouth, stomach, and intestines are parts of the digestive system.","zh":"在人體中，口、胃和腸都是消化系統的一部分。"},{"en":"A working digestive system turns food into energy and waste.","zh":"正常運作的消化系統會把食物轉化為能量和廢物。"},{"en":"This phrase is central to biology and health.","zh":"這個短語是生物和健康的核心。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":6},{"front":"similar to those of","meaning":"與……的相似","examples":[{"en":"The worm’s digestive system is similar to those of larger animals.","zh":"蚯蚓的消化系統與較大型動物的消化系統相似。"},{"en":"Similar to those of means like the ones belonging to another group.","zh":"similar to those of 指與另一群體所擁有的那些相似。"},{"en":"A small school’s rules may be similar to those of larger schools.","zh":"小學校的規則可能與較大型學校的規則相似。"},{"en":"This phrase helps compare features across different subjects without repeating the noun.","zh":"這個短語幫助比較不同對象的特徵，而不用重複名詞。"},{"en":"It is useful in formal comparison.","zh":"它適合正式比較。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":6},{"front":"be sucked into","meaning":"被吸入","examples":[{"en":"Food is sucked into the body through the worm’s mouth.","zh":"食物透過蚯蚓的口被吸入身體。"},{"en":"To be sucked into something means to be pulled inside by suction or force.","zh":"be sucked into something 指被吸力或力量拉進內部。"},{"en":"Dust is sucked into a vacuum cleaner when it is switched on.","zh":"吸塵機開啟時，灰塵會被吸入其中。"},{"en":"In feeding, suction can move food into an animal’s body.","zh":"在進食時，吸力可以把食物移入動物身體。"},{"en":"This phrase describes movement inward.","zh":"這個短語描述向內移動。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":6},{"front":"along the length of","meaning":"沿着……的長度","examples":[{"en":"Food is pushed along the length of the worm.","zh":"食物沿着蚯蚓身體的長度被推動。"},{"en":"Along the length of something means from one end to the other through its long dimension.","zh":"along the length of something 指沿着某物的長向從一端到另一端。"},{"en":"A crack may run along the length of a table.","zh":"裂縫可能沿着桌子的長度延伸。"},{"en":"In a worm, food moves through the body from mouth to anus.","zh":"在蚯蚓體內，食物從口部通過身體到肛門。"},{"en":"This phrase describes direction through a long object.","zh":"這個短語描述穿過長形物件的方向。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":7},{"front":"through muscular action","meaning":"透過肌肉活動","examples":[{"en":"Food moves through the worm’s body through muscular action.","zh":"食物透過肌肉活動在蚯蚓身體中移動。"},{"en":"Through muscular action means by the movement and contraction of muscles.","zh":"through muscular action 指透過肌肉移動和收縮。"},{"en":"Food moves through the human gut through muscular action too.","zh":"食物也透過肌肉活動在人類腸道中移動。"},{"en":"Muscle contractions can push material along even without conscious control.","zh":"肌肉收縮可以在沒有意識控制下推動物質前進。"},{"en":"This phrase explains the physical mechanism behind movement.","zh":"這個短語解釋移動背後的身體機制。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":7},{"front":"crop","meaning":"嗉囊","examples":[{"en":"Food passes through the crop before reaching the gizzard.","zh":"食物在到達砂囊之前先通過嗉囊。"},{"en":"A crop is a storage part of the digestive system in some animals.","zh":"crop 在此指某些動物消化系統中的儲存部分。"},{"en":"Some birds store food temporarily in the crop before digestion continues.","zh":"有些鳥會在消化繼續前暫時把食物儲存在嗉囊。"},{"en":"The crop helps hold food before it is processed further.","zh":"嗉囊幫助暫存食物，然後再進一步處理。"},{"en":"This word is biological here, not the same as crops grown on farms.","zh":"這個詞在此是生物學用語，不同於農作物 crops。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":7},{"front":"gizzard","meaning":"砂囊","examples":[{"en":"The gizzard helps grind food inside the worm.","zh":"砂囊幫助在蚯蚓體內磨碎食物。"},{"en":"A gizzard is a muscular digestive organ that grinds food.","zh":"gizzard 指一種有肌肉、用來磨碎食物的消化器官。"},{"en":"Chickens use a gizzard to help break down grain and small stones may assist the grinding.","zh":"雞用砂囊幫助分解穀物，小石子也可能協助磨碎。"},{"en":"Grinding food makes it easier for digestion to continue.","zh":"磨碎食物令消化更容易繼續。"},{"en":"This word is common in animal anatomy.","zh":"這個詞常見於動物解剖。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":7},{"front":"intestine","meaning":"腸道","examples":[{"en":"Food passes through the intestine before leaving the body.","zh":"食物在離開身體前通過腸道。"},{"en":"The intestine is the long tube in the digestive system where nutrients are absorbed and waste moves onward.","zh":"intestine 指消化系統中的長管，營養在其中被吸收，廢物繼續移動。"},{"en":"In humans, the intestine is important for taking nutrients from food.","zh":"在人體中，腸道對從食物吸收營養很重要。"},{"en":"After food passes through the intestine, waste can be removed from the body.","zh":"食物通過腸道後，廢物可以被排出身體。"},{"en":"This word is common in biology and health.","zh":"這個詞常見於生物和健康。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":7},{"front":"anus","meaning":"肛門","examples":[{"en":"Waste finally leaves the worm’s body through the anus.","zh":"廢物最終透過肛門離開蚯蚓身體。"},{"en":"The anus is the opening through which waste leaves the digestive system.","zh":"anus 指廢物離開消化系統的開口。"},{"en":"In many animals, the anus is the final part of the digestive tract.","zh":"在許多動物中，肛門是消化道的最後部分。"},{"en":"This body part allows digested waste to be removed.","zh":"這個身體部位讓已消化廢物被排出。"},{"en":"This word is anatomical and should be used in biological contexts.","zh":"這個詞屬解剖學用語，應用於生物語境。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":7},{"front":"perhaps surprisingly","meaning":"也許令人驚訝的是","examples":[{"en":"Perhaps surprisingly, earthworms’ constant eating improves the soil.","zh":"也許令人驚訝的是，蚯蚓持續進食會改善土壤。"},{"en":"Perhaps surprisingly means the fact may be unexpected to many readers.","zh":"perhaps surprisingly 指這個事實對許多讀者來說可能出乎意料。"},{"en":"Perhaps surprisingly, quiet students sometimes write the strongest essays.","zh":"也許令人驚訝的是，安靜學生有時寫出最強的文章。"},{"en":"This phrase prepares readers for information that goes against first impressions.","zh":"這個短語讓讀者準備接受違反第一印象的資訊。"},{"en":"It is useful when a small or plain thing has an important effect.","zh":"當小或不起眼的事物有重要影響時，它很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":7},{"front":"constant eating","meaning":"持續進食","examples":[{"en":"The constant eating of earthworms benefits the chemistry of the soil.","zh":"蚯蚓的持續進食有益於土壤化學成分。"},{"en":"Constant eating means eating repeatedly or almost continuously.","zh":"constant eating 指反覆或幾乎不斷進食。"},{"en":"A growing teenager’s constant eating may surprise the whole family.","zh":"正在成長的青少年持續進食可能令全家驚訝。"},{"en":"For worms, constant eating turns plant waste and soil particles into useful material.","zh":"對蚯蚓來說，持續進食會把植物廢料和土壤微粒轉化成有用物質。"},{"en":"This phrase shows repeated action over time.","zh":"這個短語顯示長時間重複的行動。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":7},{"front":"benefit the chemistry of the soil","meaning":"改善土壤的化學成分","examples":[{"en":"Earthworms benefit the chemistry of the soil through their feeding.","zh":"蚯蚓透過進食改善土壤的化學成分。"},{"en":"To benefit the chemistry of the soil means to improve the nutrients and chemical balance in soil.","zh":"benefit the chemistry of the soil 指改善土壤中的養分和化學平衡。"},{"en":"Compost can benefit the chemistry of garden soil by adding organic nutrients.","zh":"堆肥可以透過增加有機養分來改善花園土壤的化學成分。"},{"en":"Better soil chemistry helps plants grow stronger and healthier.","zh":"更好的土壤化學成分幫助植物長得更強壯健康。"},{"en":"This phrase connects biological activity with soil quality.","zh":"這個短語把生物活動與土壤質素連接起來。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":7},{"front":"feed on","meaning":"以……為食","examples":[{"en":"Earthworms feed on undecayed leaf litter and organic matter.","zh":"蚯蚓以未腐爛的落葉層和有機物質為食。"},{"en":"To feed on something means to eat it as food.","zh":"feed on something 指以某物作為食物。"},{"en":"Bees feed on nectar from flowers.","zh":"蜜蜂以花蜜為食。"},{"en":"What an animal feeds on affects where it lives and how it helps the environment.","zh":"動物以甚麼為食會影響牠住在哪裏，以及牠如何幫助環境。"},{"en":"This phrase is common in biology and ecology.","zh":"這個短語常見於生物和生態語境。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":7},{"front":"undecayed leaf litter","meaning":"未腐爛的落葉層","examples":[{"en":"Earthworms consume undecayed leaf litter.","zh":"蚯蚓吃掉未腐爛的落葉層。"},{"en":"Undecayed leaf litter is fallen leaves that have not yet fully decomposed.","zh":"undecayed leaf litter 指尚未完全分解的落葉。"},{"en":"In autumn, gardens may be covered with undecayed leaf litter before it breaks down.","zh":"秋天時，花園在落葉分解前可能覆蓋着未腐爛的落葉層。"},{"en":"Worms help turn this plant material into smaller, more useful soil matter.","zh":"蚯蚓幫助把這些植物材料轉化成更細小、更有用的土壤物質。"},{"en":"This phrase describes an early stage of natural recycling.","zh":"這個短語描述自然循環的早期階段。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":7},{"front":"organic matter","meaning":"有機物質","examples":[{"en":"Earthworms feed on organic matter in the soil.","zh":"蚯蚓以土壤中的有機物質為食。"},{"en":"Organic matter is material from living or once-living things, such as leaves, roots, and dead organisms.","zh":"organic matter 指來自生物或曾經有生命的東西的材料，例如葉、根和死亡生物。"},{"en":"Compost adds organic matter to garden soil.","zh":"堆肥會為花園土壤添加有機物質。"},{"en":"Organic matter improves soil because it provides nutrients and supports micro-organisms.","zh":"有機物質改善土壤，因為它提供養分並支援微生物。"},{"en":"This phrase is important in farming, gardening, and ecology.","zh":"這個短語在農業、園藝和生態中很重要。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":8},{"front":"pull pieces down into","meaning":"把碎片拉進……","examples":[{"en":"Earthworms pull pieces of leaf litter down into their burrows.","zh":"蚯蚓把落葉碎片拉進牠們的地洞。"},{"en":"To pull pieces down into something means to drag small parts into a lower or inner place.","zh":"pull pieces down into something 指把小碎片拖進較低或內部的位置。"},{"en":"A child may pull toys down into a box when tidying the floor.","zh":"孩子收拾地板時，可能把玩具拉進箱子裏。"},{"en":"Worms pulling leaves into burrows help mix surface material with soil below.","zh":"蚯蚓把葉子拉進地洞，有助把地表材料與下方土壤混合。"},{"en":"This phrase describes downward movement caused by pulling.","zh":"這個短語描述由拉動造成的向下移動。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":8},{"front":"shred something into smaller parts","meaning":"把……撕碎成較小部分","examples":[{"en":"Earthworms shred leaf litter into smaller parts.","zh":"蚯蚓把落葉層撕碎成較小部分。"},{"en":"To shred something into smaller parts means to tear or break it into small pieces.","zh":"shred something into smaller parts 指把某物撕開或弄成小片。"},{"en":"A cook may shred lettuce into smaller parts for a salad.","zh":"廚師可能把生菜撕碎成較小部分來做沙律。"},{"en":"Breaking material into smaller pieces makes it easier to digest or decompose.","zh":"把材料分成較小部分會令消化或分解更容易。"},{"en":"This phrase describes physical breakdown.","zh":"這個短語描述物理分解。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":8},{"front":"consume","meaning":"吃掉；消耗","examples":[{"en":"Earthworms consume leaf litter and soil particles.","zh":"蚯蚓吃掉落葉層和土壤微粒。"},{"en":"To consume means to eat, use up, or take in something.","zh":"consume 指吃掉、用掉或吸收某物。"},{"en":"A family may consume more electricity during a very hot summer.","zh":"家庭在非常炎熱的夏天可能消耗更多電力。"},{"en":"When worms consume plant material, they change it into material useful for soil.","zh":"當蚯蚓吃掉植物材料，牠們會把它變成對土壤有用的物質。"},{"en":"This word can refer to eating or using resources.","zh":"這個詞可以指進食，也可以指使用資源。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":8},{"front":"along with","meaning":"連同","examples":[{"en":"Earthworms eat leaf litter along with small soil particles.","zh":"蚯蚓吃落葉層，連同細小土壤微粒一起吃下。"},{"en":"Along with means together with or in addition to something else.","zh":"along with 指與某物一起，或除了某物之外。"},{"en":"A student should bring a pen along with an ID card for the exam.","zh":"學生考試時應帶筆，連同身份證。"},{"en":"Worms do not eat only leaves; they also take in soil particles with them.","zh":"蚯蚓不只吃葉子；牠們也連同土壤微粒一起吞下。"},{"en":"This phrase adds another item to the same action.","zh":"這個短語把另一項目加入同一行動。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":8},{"front":"soil particles","meaning":"土壤微粒","examples":[{"en":"Earthworms consume small soil particles with organic matter.","zh":"蚯蚓連同有機物質一起吃掉細小土壤微粒。"},{"en":"Soil particles are tiny pieces of mineral or organic material in soil.","zh":"soil particles 指土壤中礦物或有機材料的細小顆粒。"},{"en":"Sand, clay, and silt are different kinds of soil particles.","zh":"沙、黏土和粉砂都是不同種類的土壤微粒。"},{"en":"The size and mixture of soil particles affect drainage, air, and plant growth.","zh":"土壤微粒的大小和組合會影響排水、空氣和植物生長。"},{"en":"This phrase is common in soil science and farming.","zh":"這個短語常見於土壤科學和農業。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":8},{"front":"in a worm’s gut","meaning":"在蚯蚓的腸道內","examples":[{"en":"In a worm’s gut, organic matter is ground into a fine paste.","zh":"在蚯蚓的腸道內，有機物質被磨成幼細糊狀物。"},{"en":"In a worm’s gut means inside the worm’s digestive tract.","zh":"in a worm’s gut 指在蚯蚓的消化道內。"},{"en":"In a bird’s gut, food is broken down before nutrients are absorbed.","zh":"在鳥的腸道內，食物會在營養被吸收前分解。"},{"en":"What happens inside the gut changes food into forms the body or soil can use.","zh":"腸道內發生的事情會把食物轉化成身體或土壤可用的形式。"},{"en":"This phrase locates a process inside the digestive system.","zh":"這個短語指出過程發生在消化系統內。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":8},{"front":"be ground into a fine paste","meaning":"被磨成幼細糊狀物","examples":[{"en":"Food is ground into a fine paste inside the worm.","zh":"食物在蚯蚓體內被磨成幼細糊狀物。"},{"en":"To be ground into a fine paste means to be crushed until it becomes a smooth, soft mixture.","zh":"be ground into a fine paste 指被壓碎或磨碎，直到變成柔滑軟糊。"},{"en":"Nuts can be ground into a fine paste to make peanut butter.","zh":"花生可以被磨成幼細糊狀物來製成花生醬。"},{"en":"Grinding material makes it easier for chemicals or nutrients to be released.","zh":"磨碎材料會令化學物或養分更容易被釋放。"},{"en":"This phrase describes a strong physical breakdown.","zh":"這個短語描述強烈的物理分解。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":8},{"front":"be excreted","meaning":"被排出","examples":[{"en":"The digested material is eventually excreted.","zh":"已消化的物質最終被排出。"},{"en":"To be excreted means to be passed out of the body as waste.","zh":"be excreted 指作為廢物被排出體外。"},{"en":"After digestion, waste is excreted through the body’s waste system.","zh":"消化後，廢物透過身體的排泄系統被排出。"},{"en":"In earthworms, excreted material can improve soil rather than simply disappear.","zh":"在蚯蚓身上，被排出的物質可以改善土壤，而不只是消失。"},{"en":"This word is biological and describes waste removal.","zh":"這個詞屬生物用語，描述廢物排出。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":8},{"front":"release essential minerals","meaning":"釋放必需礦物質","examples":[{"en":"The excreted paste releases essential minerals into the soil.","zh":"被排出的糊狀物把必需礦物質釋放到土壤中。"},{"en":"To release essential minerals means to make important mineral nutrients available.","zh":"release essential minerals 指令重要礦物養分變得可用。"},{"en":"Compost can release minerals that help vegetables grow.","zh":"堆肥可以釋放幫助蔬菜生長的礦物質。"},{"en":"When minerals are released into soil, plant roots can absorb them more easily.","zh":"當礦物質被釋放到土壤中，植物根部可以更容易吸收。"},{"en":"This phrase connects decomposition with plant nutrition.","zh":"這個短語把分解與植物營養連接起來。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":8},{"front":"in an easily accessible form","meaning":"以容易吸收的形式","examples":[{"en":"Earthworms release minerals in an easily accessible form.","zh":"蚯蚓以容易吸收的形式釋放礦物質。"},{"en":"In an easily accessible form means in a state that can be reached, used, or absorbed without difficulty.","zh":"in an easily accessible form 指以容易取得、使用或吸收的狀態存在。"},{"en":"A teacher gives notes in an easily accessible form when they are clear, short, and well organised.","zh":"老師提供清楚、簡短且整理良好的筆記，就是以容易取得的形式提供資料。"},{"en":"Plants benefit when minerals are available in a form their roots can absorb.","zh":"當礦物質以根部可吸收的形式存在，植物會受益。"},{"en":"This phrase is useful when explaining why availability matters.","zh":"解釋可用性為何重要時，這個短語很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":8},{"front":"digested paste","meaning":"已消化的糊狀物","examples":[{"en":"A single worm may produce several kilograms of digested paste each year.","zh":"一條蚯蚓每年可能產生數公斤已消化的糊狀物。"},{"en":"Digested paste is soft material produced after food has been processed inside the worm.","zh":"digested paste 指食物在蚯蚓體內處理後產生的柔軟物質。"},{"en":"In compost, broken-down material can become a soft paste-like mixture rich in nutrients.","zh":"在堆肥中，被分解的材料可以變成富含養分的軟糊狀混合物。"},{"en":"Worms’ digested paste helps return minerals to the soil.","zh":"蚯蚓的已消化糊狀物幫助把礦物質送回土壤。"},{"en":"This phrase refers to processed organic material, not ordinary mud.","zh":"這個短語指經處理的有機物質，而不是普通泥土。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":9},{"front":"multiply that by","meaning":"將……乘以","examples":[{"en":"Multiply that by a million worms, and the effect becomes enormous.","zh":"將那個數量乘以一百萬條蚯蚓，效果就變得巨大。"},{"en":"Multiply that by means imagine the same amount repeated by a certain number.","zh":"multiply that by 指想像同一數量被某個數字重複。"},{"en":"If one student saves one bottle a day, multiply that by a thousand students and the waste reduction is large.","zh":"如果一名學生每天節省一個膠樽，將它乘以一千名學生，減廢量就很大。"},{"en":"Small individual effects can become huge when repeated many times.","zh":"小小個體效果在重複許多次後可以變得巨大。"},{"en":"This phrase helps readers understand scale.","zh":"這個短語幫助讀者理解規模。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":9},{"front":"unsung creatures","meaning":"默默無聞的生物","examples":[{"en":"Darwin described earthworms as unsung creatures.","zh":"Darwin 把蚯蚓描述為默默無聞的生物。"},{"en":"Unsung creatures are living things that do important work without receiving much praise.","zh":"unsung creatures 指做着重要工作但很少受到讚揚的生物。"},{"en":"Soil bacteria are unsung creatures because most people never see them but plants depend on them.","zh":"土壤細菌是默默無聞的生物，因為大多數人看不到它們，但植物依賴它們。"},{"en":"When society overlooks quiet contributors, their value may be recognised only after problems appear.","zh":"當社會忽略安靜貢獻者，人們可能要到問題出現後才認識其價值。"},{"en":"This phrase praises hidden importance.","zh":"這個短語讚揚隱藏的重要性。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":9},{"front":"in their untold millions","meaning":"數量多得難以計算地","examples":[{"en":"Earthworms, in their untold millions, transform the land.","zh":"蚯蚓數量多得難以計算地改造土地。"},{"en":"In their untold millions means in numbers so huge they are difficult to count.","zh":"in their untold millions 指數量巨大到難以計算。"},{"en":"Insects, in their untold millions, support many food chains.","zh":"昆蟲數量多得難以計算，支撐許多食物鏈。"},{"en":"A huge number of small creatures can change an environment over time.","zh":"大量小生物可以隨時間改變環境。"},{"en":"This phrase emphasises vast quantity.","zh":"這個短語強調龐大數量。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":9},{"front":"transform the land","meaning":"改造土地","examples":[{"en":"Earthworms help transform the land through their activity.","zh":"蚯蚓透過牠們的活動幫助改造土地。"},{"en":"To transform the land means to change the condition, structure, or fertility of an area of ground.","zh":"transform the land 指改變某片土地的狀態、結構或肥力。"},{"en":"Farmers can transform dry land by adding water systems and improving soil.","zh":"農民可以透過增加灌溉系統和改善土壤來改造乾旱土地。"},{"en":"Earthworms transform land slowly by mixing soil, moving air, and releasing nutrients.","zh":"蚯蚓透過混合土壤、移動空氣和釋放養分，慢慢改造土地。"},{"en":"This phrase describes deep environmental change.","zh":"這個短語描述深層環境變化。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":9},{"front":"relate to","meaning":"與……有關","examples":[{"en":"The other great benefit relates to earthworms’ search for food.","zh":"另一項巨大好處與蚯蚓尋找食物有關。"},{"en":"To relate to something means to be connected with it.","zh":"relate to something 指與某事有連繫。"},{"en":"A student’s tiredness may relate to lack of sleep rather than laziness.","zh":"學生疲倦可能與睡眠不足有關，而不是懶惰。"},{"en":"Understanding what a benefit relates to helps explain its cause.","zh":"理解某項好處與甚麼有關，有助解釋其原因。"},{"en":"This phrase is common in formal explanation.","zh":"這個短語常見於正式解釋。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":9},{"front":"search for food","meaning":"尋找食物","examples":[{"en":"Earthworms move through the soil in their search for food.","zh":"蚯蚓在尋找食物時穿過土壤移動。"},{"en":"A search for food is the activity of looking for something to eat.","zh":"search for food 指尋找可吃東西的活動。"},{"en":"Birds may fly across a park in their search for food.","zh":"鳥類可能為尋找食物而飛過公園。"},{"en":"Animals often move, dig, or travel because food is not found in one fixed place.","zh":"動物常因食物不在固定位置而移動、挖掘或旅行。"},{"en":"This phrase explains why movement happens.","zh":"這個短語解釋移動為何發生。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":9},{"front":"it might surprise many to know that","meaning":"很多人可能會驚訝地知道","examples":[{"en":"It might surprise many to know that earthworms are very mobile.","zh":"很多人可能會驚訝地知道蚯蚓活動能力很高。"},{"en":"It might surprise many to know that introduces a fact many people would not expect.","zh":"it might surprise many to know that 用來引出許多人不預期的事實。"},{"en":"It might surprise many to know that small habits can change exam results over time.","zh":"很多人可能會驚訝地知道小習慣可以隨時間改變考試結果。"},{"en":"This phrase prepares readers for a surprising correction to their assumptions.","zh":"這個短語讓讀者準備接受對其假設的驚人修正。"},{"en":"It is useful when the truth is different from first impressions.","zh":"當真相與第一印象不同時，它很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":9},{"front":"very mobile","meaning":"活動能力很高的","examples":[{"en":"Earthworms are very mobile despite their slow appearance.","zh":"蚯蚓雖然看起來慢，但活動能力很高。"},{"en":"Very mobile means able to move around a lot or move through an area effectively.","zh":"very mobile 指能大量移動或有效穿過一個區域。"},{"en":"A nurse in a busy hospital needs to be very mobile during a shift.","zh":"忙碌醫院中的護士在值班期間需要活動能力很高。"},{"en":"Earthworms may look slow, but they move up, down, and across soil regularly.","zh":"蚯蚓看起來慢，但會定期在土壤中上下和橫向移動。"},{"en":"This phrase describes ability to move, not speed alone.","zh":"這個短語描述移動能力，而不只是速度。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":9},{"front":"safer depths","meaning":"較安全的深處","examples":[{"en":"Earthworms move down into safer depths during the day.","zh":"蚯蚓在白天向下移到較安全的深處。"},{"en":"Safer depths are deeper layers where danger from light, heat, or predators is lower.","zh":"safer depths 指較深、來自光線、熱力或掠食者的危險較低的層次。"},{"en":"Fish may swim to safer depths when the surface water becomes too warm.","zh":"當表層水太暖，魚可能游到較安全的深處。"},{"en":"Moving deeper can protect animals from harsh surface conditions.","zh":"移到更深處可以保護動物免受惡劣地表條件影響。"},{"en":"This phrase links depth with protection.","zh":"這個短語把深度與保護連接起來。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":9},{"front":"on a daily basis","meaning":"每日；每天","examples":[{"en":"Earthworms move up and down through the soil on a daily basis.","zh":"蚯蚓每天在土壤中上下移動。"},{"en":"On a daily basis means every day or as part of a daily routine.","zh":"on a daily basis 指每日或作為日常習慣的一部分。"},{"en":"Students should review vocabulary on a daily basis to remember it well.","zh":"學生應每天溫習詞彙，才能記得牢。"},{"en":"Repeated daily action can create large effects over time.","zh":"每日重複行動可以隨時間產生巨大效果。"},{"en":"This phrase is more formal than every day.","zh":"這個短語比 every day 更正式。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":9},{"front":"aided by","meaning":"在……幫助下","examples":[{"en":"Earthworms move through soil aided by lubricating mucus.","zh":"蚯蚓在潤滑黏液幫助下穿過土壤。"},{"en":"Aided by means helped by something.","zh":"aided by 指在某物幫助下。"},{"en":"A student may improve faster aided by clear feedback from a teacher.","zh":"學生在老師清楚回饋幫助下可能進步更快。"},{"en":"Tools, substances, or people can make a difficult action easier.","zh":"工具、物質或人可以令困難行動更容易。"},{"en":"This phrase is formal and focuses on assistance.","zh":"這個短語較正式，聚焦協助。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":10},{"front":"secretion of lubricating mucus","meaning":"分泌潤滑黏液","examples":[{"en":"The secretion of lubricating mucus helps worms move through soil.","zh":"分泌潤滑黏液幫助蚯蚓穿過土壤。"},{"en":"Secretion of lubricating mucus means producing a slippery substance that reduces friction.","zh":"secretion of lubricating mucus 指產生減少摩擦的滑溜物質。"},{"en":"A snail leaves mucus that helps it slide over rough surfaces.","zh":"蝸牛留下黏液，幫助牠滑過粗糙表面。"},{"en":"Lubrication makes movement easier when an animal pushes through tight spaces.","zh":"當動物推動自己穿過狹窄空間時，潤滑令移動更容易。"},{"en":"This phrase describes a biological aid to movement.","zh":"這個短語描述生物學上的移動輔助。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":10},{"front":"push themselves through","meaning":"推動自己穿過","examples":[{"en":"Earthworms push themselves through the soil.","zh":"蚯蚓推動自己穿過土壤。"},{"en":"To push themselves through something means to move forward by pressing the body against it.","zh":"push themselves through something 指用身體壓向某物來向前移動。"},{"en":"A swimmer pushes herself through water with arms and legs.","zh":"游泳者用手臂和雙腿推動自己穿過水。"},{"en":"Worms push through soil by contracting and lengthening their bodies.","zh":"蚯蚓透過收縮和伸長身體推動自己穿過土壤。"},{"en":"This phrase describes effortful movement through a medium.","zh":"這個短語描述穿過某種介質的用力移動。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":10},{"front":"waves of bodily contractions","meaning":"一波波身體收縮","examples":[{"en":"Earthworms move by using waves of bodily contractions.","zh":"蚯蚓透過一波波身體收縮來移動。"},{"en":"Waves of bodily contractions are repeated muscle movements that pass along the body.","zh":"waves of bodily contractions 指沿着身體傳遞的重複肌肉收縮。"},{"en":"The human intestine also uses wave-like contractions to move food along.","zh":"人類腸道也使用波浪式收縮來推動食物前進。"},{"en":"These waves let soft-bodied animals move without legs.","zh":"這些波動讓身體柔軟的動物不用腳也能移動。"},{"en":"This phrase explains the motion mechanism.","zh":"這個短語解釋移動機制。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":10},{"front":"alternately shorten and lengthen","meaning":"交替縮短和伸長","examples":[{"en":"Their bodies alternately shorten and lengthen as they move.","zh":"牠們移動時，身體會交替縮短和伸長。"},{"en":"Alternately shorten and lengthen means become shorter, then longer, again and again.","zh":"alternately shorten and lengthen 指反覆變短，然後變長。"},{"en":"A spring may alternately shorten and lengthen when it is pressed and released.","zh":"彈簧被按下和放開時，可能交替縮短和伸長。"},{"en":"This repeated change helps worms grip the soil and move forward.","zh":"這種重複變化幫助蚯蚓抓住泥土並向前移動。"},{"en":"This phrase describes a rhythmic pattern of movement.","zh":"這個短語描述有節奏的移動模式。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":10},{"front":"the point is that","meaning":"關鍵是","examples":[{"en":"The point is that water can move through worm tunnels.","zh":"關鍵是水可以穿過蚯蚓隧道流動。"},{"en":"The point is that introduces the main idea the speaker wants to emphasise.","zh":"the point is that 用來引出說話者想強調的主要意思。"},{"en":"The point is that studying every day is better than rushing the night before.","zh":"關鍵是每天學習比考前一晚趕工更好。"},{"en":"This phrase helps focus attention after details or examples.","zh":"這個短語在細節或例子之後幫助集中注意。"},{"en":"It is useful when clarifying the key message.","zh":"澄清核心訊息時，它很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":10},{"front":"move through tunnels","meaning":"穿過隧道流動","examples":[{"en":"Water can move through tunnels made by earthworms.","zh":"水可以穿過蚯蚓製造的隧道流動。"},{"en":"To move through tunnels means to pass along narrow underground passages.","zh":"move through tunnels 指沿着狹窄地下通道通過。"},{"en":"Rainwater can move through drainage pipes after a storm.","zh":"暴風雨後，雨水可以穿過排水管流動。"},{"en":"Worm tunnels help water enter soil instead of staying on the surface.","zh":"蚯蚓隧道幫助水進入土壤，而不是留在地表。"},{"en":"This phrase describes passage through channels.","zh":"這個短語描述穿過通道。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":10},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, worms help move air through the soil.","zh":"更重要的是，蚯蚓幫助空氣在土壤中流動。"},{"en":"More importantly introduces a point that matters even more than the previous one.","zh":"more importantly 用來引出比前一點更重要的內容。"},{"en":"A school trip is fun; more importantly, it helps students learn outside the classroom.","zh":"學校旅行很有趣；更重要的是，它幫助學生在課室外學習。"},{"en":"This phrase ranks ideas by importance.","zh":"這個短語按重要性排列想法。"},{"en":"It is useful when adding a stronger reason.","zh":"加入更強理由時，它很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":10},{"front":"as the worms travel","meaning":"當蚯蚓移動時","examples":[{"en":"As the worms travel, they push air in and out of the soil.","zh":"當蚯蚓移動時，牠們把空氣推進推出土壤。"},{"en":"As the worms travel means while the worms are moving.","zh":"as the worms travel 指當蚯蚓正在移動時。"},{"en":"As students walk to school, they may talk and review vocabulary together.","zh":"當學生步行上學時，他們可能一起聊天和溫習詞彙。"},{"en":"The phrase links one action happening during another action.","zh":"這個短語把一個行動與另一個正在發生的行動連接起來。"},{"en":"In this context, worm movement produces soil aeration.","zh":"在這個語境中，蚯蚓移動會產生土壤通氣。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":10},{"front":"push air in and out of","meaning":"把空氣推進推出……","examples":[{"en":"Earthworms push air in and out of the soil.","zh":"蚯蚓把空氣推進推出土壤。"},{"en":"To push air in and out of something means to move air into it and then out again.","zh":"push air in and out of something 指把空氣推入某物，再推回外面。"},{"en":"Opening and closing a door can push air in and out of a room.","zh":"開關門可以把空氣推進推出房間。"},{"en":"Air movement in soil helps roots and micro-organisms survive.","zh":"土壤中的空氣流動幫助根部和微生物生存。"},{"en":"This phrase describes circulation of air.","zh":"這個短語描述空氣循環。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":10},{"front":"on a continuous basis","meaning":"持續地","examples":[{"en":"Earthworms aerate the soil on a continuous basis.","zh":"蚯蚓持續地為土壤通氣。"},{"en":"On a continuous basis means regularly and without long interruption.","zh":"on a continuous basis 指定期且沒有長時間中斷地。"},{"en":"A hospital must clean equipment on a continuous basis to prevent infection.","zh":"醫院必須持續清潔設備，以防感染。"},{"en":"Continuous small actions can create large long-term benefits.","zh":"持續的小行動可以創造巨大長遠好處。"},{"en":"This phrase is formal and stresses ongoing activity.","zh":"這個短語較正式，強調持續活動。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":10},{"front":"in the same way that","meaning":"正如……一樣","examples":[{"en":"In the same way that animals need oxygen, soil organisms need it too.","zh":"正如動物需要氧氣一樣，土壤生物也需要氧氣。"},{"en":"In the same way that introduces a comparison showing two things work similarly.","zh":"in the same way that 用來引出比較，顯示兩件事以相似方式運作。"},{"en":"In the same way that students need feedback, workers need clear guidance.","zh":"正如學生需要回饋一樣，員工也需要清楚指引。"},{"en":"This phrase helps explain an unfamiliar idea through a familiar one.","zh":"這個短語透過熟悉想法解釋陌生想法。"},{"en":"It is useful for analogy.","zh":"它適合用於類比。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":11},{"front":"so too do","meaning":"……也是如此","examples":[{"en":"Animals need oxygen, and so too do micro-organisms in the soil.","zh":"動物需要氧氣，土壤中的微生物也是如此。"},{"en":"So too do means the second group also does the same thing.","zh":"so too do 指第二個群體也做同樣事情。"},{"en":"Children need rest, and so too do adults after a long week.","zh":"孩子需要休息，成年人在漫長一週後也是如此。"},{"en":"This structure creates a formal parallel between two subjects.","zh":"這個結構在兩個主語之間創造正式平行。"},{"en":"It is useful when showing that a need or action applies to another group as well.","zh":"顯示某需要或行動也適用於另一群體時，它很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":11},{"front":"myriad micro-organisms","meaning":"無數微生物","examples":[{"en":"Myriad micro-organisms in the soil need oxygen.","zh":"土壤中的無數微生物需要氧氣。"},{"en":"Myriad micro-organisms means countless tiny living things, such as bacteria and fungi.","zh":"myriad micro-organisms 指無數微小生物，例如細菌和真菌。"},{"en":"A spoonful of healthy soil may contain myriad micro-organisms.","zh":"一匙健康土壤可能含有無數微生物。"},{"en":"These tiny organisms help break down organic matter and support plant growth.","zh":"這些微小生物幫助分解有機物並支援植物生長。"},{"en":"This phrase emphasises both small size and huge number.","zh":"這個短語同時強調體積微小和數量巨大。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":11},{"front":"waterlogged","meaning":"積水的","examples":[{"en":"Without worms, the ground could become waterlogged.","zh":"沒有蚯蚓，地面可能變得積水。"},{"en":"Waterlogged means filled with too much water, so air cannot move properly.","zh":"waterlogged 指充滿過多水分，以致空氣不能正常流動。"},{"en":"A football field may become waterlogged after several days of heavy rain.","zh":"連續幾天大雨後，足球場可能變得積水。"},{"en":"Waterlogged soil can damage plant roots because they cannot get enough oxygen.","zh":"積水土壤會損害植物根部，因為它們得不到足夠氧氣。"},{"en":"This word is common in farming, gardening, and weather reports.","zh":"這個詞常見於農業、園藝和天氣報告。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":11},{"front":"airless","meaning":"缺乏空氣的","examples":[{"en":"Without worms, soil would become airless and less productive.","zh":"沒有蚯蚓，土壤會變得缺乏空氣且產量較低。"},{"en":"Airless means lacking enough air or oxygen.","zh":"airless 指缺乏足夠空氣或氧氣。"},{"en":"A sealed room can feel airless if the windows never open.","zh":"如果窗戶從不打開，密封房間可能感覺缺乏空氣。"},{"en":"Airless soil is unhealthy because roots and micro-organisms need oxygen.","zh":"缺乏空氣的土壤不健康，因為根部和微生物需要氧氣。"},{"en":"This word describes a condition where breathing or biological activity becomes harder.","zh":"這個詞描述令呼吸或生物活動更困難的狀態。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":11},{"front":"less productive for","meaning":"對……來說產量較低","examples":[{"en":"Airless soil is less productive for farming purposes.","zh":"缺乏空氣的土壤對農業用途來說產量較低。"},{"en":"Less productive for something means producing fewer useful results for that purpose.","zh":"less productive for something 指對某目的而言產生較少有用結果。"},{"en":"A noisy classroom is less productive for careful reading.","zh":"嘈吵課室對仔細閱讀來說效率較低。"},{"en":"Soil with poor air and nutrients produces weaker crops.","zh":"空氣和養分不足的土壤會產生較弱作物。"},{"en":"This phrase connects poor conditions with weaker results.","zh":"這個短語把差劣條件與較弱結果連接起來。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":11},{"front":"farming purposes","meaning":"農業用途","examples":[{"en":"Earthworms help keep soil useful for farming purposes.","zh":"蚯蚓幫助保持土壤對農業用途有用。"},{"en":"Farming purposes means uses connected with growing crops or raising animals.","zh":"farming purposes 指與種植作物或飼養動物有關的用途。"},{"en":"Land may be tested for farming purposes before crops are planted.","zh":"土地在種植作物前可能為農業用途而被測試。"},{"en":"Soil quality matters for farming because weak soil reduces harvests.","zh":"土壤質素對農業很重要，因為貧瘠土壤會減少收成。"},{"en":"This phrase identifies the practical agricultural use of something.","zh":"這個短語指出某物的實際農業用途。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":11},{"front":"form the base of","meaning":"構成……的基礎","examples":[{"en":"Earthworms form the base of many food chains.","zh":"蚯蚓構成許多食物鏈的基礎。"},{"en":"To form the base of something means to be the foundation that supports the rest.","zh":"form the base of something 指成為支撐其餘部分的基礎。"},{"en":"Basic grammar forms the base of clear writing.","zh":"基本文法構成清晰寫作的基礎。"},{"en":"If the base is weak, the whole system built on it may suffer.","zh":"如果基礎薄弱，建立在其上的整個系統可能受損。"},{"en":"This phrase is useful when explaining foundations in systems.","zh":"解釋系統基礎時，這個短語很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":11},{"front":"food chains","meaning":"食物鏈","examples":[{"en":"Many food chains depend on earthworms.","zh":"許多食物鏈依賴蚯蚓。"},{"en":"Food chains are sequences showing how energy passes from one living thing to another through feeding.","zh":"food chains 指能量如何透過進食從一種生物傳到另一種生物的序列。"},{"en":"Grass, rabbits, and foxes can form a simple food chain.","zh":"草、兔子和狐狸可以形成一條簡單食物鏈。"},{"en":"If one part of a food chain disappears, other animals may lose food.","zh":"如果食物鏈中的一部分消失，其他動物可能失去食物。"},{"en":"This phrase is central to ecology.","zh":"這個短語是生態學的核心。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":11},{"front":"not only…but also…","meaning":"不但……而且……","examples":[{"en":"Not only birds but also many mammals feed on earthworms.","zh":"不但鳥類，而且許多哺乳動物都以蚯蚓為食。"},{"en":"Not only…but also… means both the first thing and the second thing are true.","zh":"not only…but also… 指第一件事和第二件事都是真的。"},{"en":"Reading helps not only vocabulary but also writing structure.","zh":"閱讀不但幫助詞彙，而且幫助寫作結構。"},{"en":"This structure adds a second point and often makes the sentence stronger.","zh":"這個結構加入第二點，常令句子更有力。"},{"en":"It is useful when expanding an idea.","zh":"擴展想法時，它很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":11},{"front":"mammals","meaning":"哺乳動物","examples":[{"en":"Some mammals actively dig for earthworms.","zh":"有些哺乳動物會主動挖掘蚯蚓。"},{"en":"Mammals are warm-blooded animals that usually have hair and feed their young with milk.","zh":"mammals 指通常有毛、以乳汁餵養幼崽的溫血動物。"},{"en":"Dogs, whales, bats, and humans are all mammals.","zh":"狗、鯨魚、蝙蝠和人類都是哺乳動物。"},{"en":"Many mammals depend on smaller animals for food.","zh":"許多哺乳動物依賴較小動物作食物。"},{"en":"This word is a basic biological classification.","zh":"這個詞是基本生物分類。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":11},{"front":"such as","meaning":"例如","examples":[{"en":"Mammals such as hedgehogs and moles eat earthworms.","zh":"例如刺蝟和鼴鼠等哺乳動物會吃蚯蚓。"},{"en":"Such as introduces examples of a larger group.","zh":"such as 用來引出較大類別中的例子。"},{"en":"Students need basic tools such as pens, notebooks, and a dictionary.","zh":"學生需要基本工具，例如筆、筆記簿和字典。"},{"en":"Examples after such as help readers understand the category more clearly.","zh":"such as 後面的例子幫助讀者更清楚理解類別。"},{"en":"This phrase is common in definitions and explanations.","zh":"這個短語常見於定義和解釋。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":12},{"front":"hedgehogs","meaning":"刺蝟","examples":[{"en":"Hedgehogs may dig into the ground for worms.","zh":"刺蝟可能挖進地面尋找蚯蚓。"},{"en":"Hedgehogs are small mammals with spines on their backs.","zh":"hedgehogs 指背上有刺的小型哺乳動物。"},{"en":"A hedgehog may curl into a ball when it feels threatened.","zh":"刺蝟感到受威脅時可能蜷縮成球。"},{"en":"Hedgehogs eat insects, worms, and other small creatures, helping control garden pests.","zh":"刺蝟吃昆蟲、蚯蚓和其他小生物，有助控制花園害蟲。"},{"en":"This word names a specific mammal often found in gardens or countryside.","zh":"這個詞指一種常見於花園或郊野的特定哺乳動物。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":12},{"front":"moles","meaning":"鼴鼠","examples":[{"en":"Moles actively dig into the ground for worms.","zh":"鼴鼠會主動挖進地面尋找蚯蚓。"},{"en":"Moles are small mammals that live underground and dig tunnels.","zh":"moles 指生活在地下並挖掘隧道的小型哺乳動物。"},{"en":"A mole may leave small piles of soil on a lawn.","zh":"鼴鼠可能在草坪上留下小土堆。"},{"en":"Moles hunt worms and insects, so healthy soil can attract them.","zh":"鼴鼠捕食蚯蚓和昆蟲，因此健康土壤可能吸引牠們。"},{"en":"This word names an underground animal, not the skin mark in this context.","zh":"在這個語境中，這個詞指地下動物，不是皮膚上的痣。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":12},{"front":"actively dig into","meaning":"主動挖進……","examples":[{"en":"Some animals actively dig into the ground for worms.","zh":"有些動物會主動挖進地面尋找蚯蚓。"},{"en":"To actively dig into something means to deliberately dig into it with effort.","zh":"actively dig into something 指有意識並用力地挖入某物。"},{"en":"A dog may actively dig into a flowerbed to hide a toy.","zh":"狗可能主動挖進花槽，把玩具藏起來。"},{"en":"Animals dig into soil when food, shelter, or safety lies below the surface.","zh":"當食物、住所或安全位於地表之下，動物會挖進土壤。"},{"en":"This phrase stresses purposeful action.","zh":"這個短語強調有目的的行動。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":12},{"front":"such predation","meaning":"這種捕食","examples":[{"en":"Such predation has little effect on worm populations.","zh":"這種捕食對蚯蚓數量影響很小。"},{"en":"Such predation refers to the kind of hunting or feeding just mentioned.","zh":"such predation 指剛才提到的那種捕獵或進食行為。"},{"en":"Birds eating insects is predation, and such predation can help control pest numbers.","zh":"鳥吃昆蟲是捕食，這種捕食可以幫助控制害蟲數量。"},{"en":"If prey reproduce quickly, predation may not greatly reduce their population.","zh":"如果獵物繁殖很快，捕食未必大幅減少其數量。"},{"en":"This phrase connects a specific example of hunting to its effect.","zh":"這個短語把特定捕獵例子與其影響連接起來。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":12},{"front":"have little effect on","meaning":"對……影響很小","examples":[{"en":"Natural predation has little effect on worm populations.","zh":"自然捕食對蚯蚓數量影響很小。"},{"en":"To have little effect on something means to change it only slightly or not much.","zh":"have little effect on something 指只稍微改變某事，或幾乎沒有影響。"},{"en":"One missed lesson may have little effect on a strong student who catches up quickly.","zh":"缺席一堂課對能快速追回進度的強學生可能影響很小。"},{"en":"A small pressure may not matter if the system can recover easily.","zh":"如果系統容易恢復，小壓力可能不太重要。"},{"en":"This phrase describes a weak impact.","zh":"這個短語描述微弱影響。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":12},{"front":"worm populations","meaning":"蚯蚓數量","examples":[{"en":"Certain chemicals can reduce worm populations.","zh":"某些化學物質可以減少蚯蚓數量。"},{"en":"Worm populations are the numbers or groups of worms living in a particular area.","zh":"worm populations 指生活在某特定地區的蚯蚓數量或群體。"},{"en":"A garden with healthy soil may have large worm populations.","zh":"土壤健康的花園可能有大量蚯蚓。"},{"en":"When worm populations fall, soil may become less fertile and less aerated.","zh":"當蚯蚓數量下降，土壤可能變得較不肥沃、通氣較差。"},{"en":"This phrase is common in ecology and farming.","zh":"這個短語常見於生態和農業。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":12},{"front":"a different case","meaning":"另一回事","examples":[{"en":"The use of certain fertilisers is a different case.","zh":"使用某些肥料是另一回事。"},{"en":"A different case means a separate situation that should be judged differently.","zh":"different case 指應另行判斷的不同情況。"},{"en":"Missing one class is one thing; failing every assignment is a different case.","zh":"缺席一堂課是一回事；每份作業都不及格則是另一回事。"},{"en":"This phrase helps contrast a mild situation with a more serious one.","zh":"這個短語幫助把輕微情況與較嚴重情況作對比。"},{"en":"It is useful when changing from one example to another.","zh":"從一個例子轉到另一個例子時，它很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":12},{"front":"the use of certain fertilisers","meaning":"使用某些肥料","examples":[{"en":"The use of certain fertilisers can harm earthworms.","zh":"使用某些肥料可以傷害蚯蚓。"},{"en":"The use of certain fertilisers means applying particular chemical or nutrient products to soil.","zh":"use of certain fertilisers 指把特定化學或養分產品施用到土壤。"},{"en":"Farmers may use fertilisers to help crops grow faster.","zh":"農民可能使用肥料幫助作物更快生長。"},{"en":"Some fertilisers can improve plant growth but damage soil organisms if used carelessly.","zh":"有些肥料可以改善植物生長，但若使用不慎會傷害土壤生物。"},{"en":"This phrase points to a farming practice with possible ecological effects.","zh":"這個短語指出一種可能有生態影響的農業做法。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":12},{"front":"depend on","meaning":"依賴；取決於","examples":[{"en":"Earthworms depend on the condition of the soil.","zh":"蚯蚓依賴土壤狀況。"},{"en":"To depend on something means to need it or be affected by it.","zh":"depend on something 指需要某物或受某物影響。"},{"en":"Students’ progress can depend on sleep, practice, and good feedback.","zh":"學生進步可以取決於睡眠、練習和良好回饋。"},{"en":"If soil conditions change, the animals living in it may also change.","zh":"如果土壤條件改變，生活在其中的動物也可能改變。"},{"en":"This phrase shows reliance or conditional relationship.","zh":"這個短語顯示依賴或條件關係。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":12},{"front":"moisture content","meaning":"含水量","examples":[{"en":"Earthworms are affected by the moisture content of the soil.","zh":"蚯蚓受土壤含水量影響。"},{"en":"Moisture content is the amount of water contained in a material.","zh":"moisture content 指材料中所含水分的多少。"},{"en":"Bakers check the moisture content of dough because it affects texture.","zh":"麵包師會檢查麵團含水量，因為它影響口感。"},{"en":"Soil with too little moisture can dry out worms, while too much water can flood burrows.","zh":"含水量太低的土壤會令蚯蚓乾掉，而太多水會淹浸地洞。"},{"en":"This phrase is common in farming, food, and environmental science.","zh":"這個短語常見於農業、食物和環境科學。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":12},{"front":"be sensitive to","meaning":"對……敏感","examples":[{"en":"Earthworms are most sensitive to soil acidity.","zh":"蚯蚓對土壤酸度最敏感。"},{"en":"To be sensitive to something means to be easily affected by it.","zh":"be sensitive to something 指容易受某事影響。"},{"en":"Some people are sensitive to strong perfume and may get headaches.","zh":"有些人對濃烈香水敏感，可能會頭痛。"},{"en":"If an organism is sensitive to a condition, small changes can cause big effects.","zh":"如果生物對某條件敏感，小改變可以造成大影響。"},{"en":"This phrase is useful in health, biology, and environmental contexts.","zh":"這個短語適用於健康、生物和環境語境。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":13},{"front":"acidity","meaning":"酸度","examples":[{"en":"Soil acidity can seriously affect earthworms.","zh":"土壤酸度可以嚴重影響蚯蚓。"},{"en":"Acidity is the level of acid in a substance.","zh":"acidity 指物質中的酸性水平。"},{"en":"Lemon juice has high acidity, which gives it a sharp taste.","zh":"檸檬汁酸度高，因此味道尖銳。"},{"en":"If soil acidity becomes too high, some plants and animals may struggle to survive.","zh":"如果土壤酸度太高，有些植物和動物可能難以生存。"},{"en":"This word is common in chemistry, food, and soil science.","zh":"這個詞常見於化學、食物和土壤科學。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":13},{"front":"nitrogenous fertilisers","meaning":"含氮肥料","examples":[{"en":"Nitrogenous fertilisers can harm earthworm populations.","zh":"含氮肥料可以傷害蚯蚓數量。"},{"en":"Nitrogenous fertilisers are fertilisers that contain nitrogen compounds to help plants grow.","zh":"nitrogenous fertilisers 指含有氮化合物、用來幫助植物生長的肥料。"},{"en":"Farmers may use nitrogenous fertilisers when crops need more nitrogen.","zh":"當作物需要更多氮，農民可能使用含氮肥料。"},{"en":"These fertilisers can increase plant growth but may also change soil acidity.","zh":"這些肥料可以增加植物生長，但也可能改變土壤酸度。"},{"en":"This phrase is technical and belongs to agriculture and soil chemistry.","zh":"這個短語較技術性，屬於農業和土壤化學。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":13},{"front":"raise something to levels fatal to","meaning":"把……提高至對……致命的水平","examples":[{"en":"Nitrogenous fertilisers can raise acidity to levels fatal to earthworms.","zh":"含氮肥料可以把酸度提高至對蚯蚓致命的水平。"},{"en":"To raise something to levels fatal to a creature means to increase it until it can kill that creature.","zh":"raise something to levels fatal to a creature 指把某物提高到能殺死該生物的水平。"},{"en":"Pollution can raise chemical levels in water to levels fatal to fish.","zh":"污染可以把水中化學物水平提高至對魚類致命的水平。"},{"en":"A helpful substance can become dangerous when its level rises too high.","zh":"有用物質在水平過高時可以變得危險。"},{"en":"This phrase describes harmful increase beyond a survival limit.","zh":"這個短語描述超出生存限度的有害增加。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":13},{"front":"fatal to","meaning":"對……致命","examples":[{"en":"High acidity can be fatal to earthworms.","zh":"高酸度可能對蚯蚓致命。"},{"en":"Fatal to something means able to cause death or complete failure.","zh":"fatal to something 指能造成死亡或徹底失敗。"},{"en":"A lack of oxygen can be fatal to fish in a polluted river.","zh":"缺氧可能對污染河流中的魚類致命。"},{"en":"Conditions that are fatal to one species may be harmless to another.","zh":"對某物種致命的條件，對另一物種可能無害。"},{"en":"This phrase is strong and describes severe danger.","zh":"這個短語語氣強，描述嚴重危險。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":13},{"front":"disastrous drops in numbers","meaning":"數量災難性下降","examples":[{"en":"Certain fertilisers can cause disastrous drops in worm numbers.","zh":"某些肥料可以造成蚯蚓數量災難性下降。"},{"en":"Disastrous drops in numbers are severe and harmful decreases in a population or amount.","zh":"disastrous drops in numbers 指某群體或數量嚴重且有害地減少。"},{"en":"A disease can cause disastrous drops in bee numbers.","zh":"疾病可以造成蜜蜂數量災難性下降。"},{"en":"When numbers drop sharply, the whole ecosystem may be affected.","zh":"當數量急劇下降，整個生態系統可能受影響。"},{"en":"This phrase emphasises both the size and seriousness of a decline.","zh":"這個短語同時強調下降幅度和嚴重性。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":13},{"front":"ecologically aware farmer","meaning":"有生態意識的農夫","examples":[{"en":"An ecologically aware farmer avoids chemicals that harm worms.","zh":"有生態意識的農夫避免使用傷害蚯蚓的化學物。"},{"en":"An ecologically aware farmer understands how farming choices affect soil, wildlife, and ecosystems.","zh":"ecologically aware farmer 指理解農業選擇如何影響土壤、野生動物和生態系統的農夫。"},{"en":"Such a farmer may protect hedges, reduce harmful chemicals, and add organic matter.","zh":"這樣的農夫可能保護樹籬、減少有害化學物並添加有機物質。"},{"en":"Ecological awareness can help farms remain productive without damaging natural systems.","zh":"生態意識可以幫助農場保持生產力，而不損害自然系統。"},{"en":"This phrase describes both knowledge and responsible action.","zh":"這個短語同時描述知識和負責任行動。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":13},{"front":"avoid such chemicals","meaning":"避免使用這類化學物質","examples":[{"en":"Ecologically aware farmers avoid such chemicals.","zh":"有生態意識的農夫避免使用這類化學物質。"},{"en":"To avoid such chemicals means not to use the harmful substances just mentioned.","zh":"avoid such chemicals 指不使用剛才提到的有害物質。"},{"en":"Parents may avoid harsh cleaning chemicals when small children are at home.","zh":"家中有幼兒時，家長可能避免使用強烈清潔化學品。"},{"en":"Avoiding harmful chemicals can protect soil organisms, water, and human health.","zh":"避免有害化學物可以保護土壤生物、水源和人類健康。"},{"en":"This phrase shows a preventive choice.","zh":"這個短語顯示一種預防性選擇。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":13},{"front":"regularly add","meaning":"定期添加","examples":[{"en":"A careful farmer regularly adds organic matter to the soil.","zh":"細心農夫會定期添加有機物質到土壤中。"},{"en":"To regularly add something means to put it in repeatedly as part of a routine.","zh":"regularly add something 指作為習慣反覆加入某物。"},{"en":"A student regularly adds new words to a vocabulary notebook.","zh":"學生定期把新詞加入詞彙筆記本。"},{"en":"Repeated additions can slowly improve a system over time.","zh":"反覆添加可以隨時間慢慢改善一個系統。"},{"en":"This phrase stresses consistent action.","zh":"這個短語強調持續一致的行動。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":13},{"front":"surface mulch","meaning":"表層覆蓋物","examples":[{"en":"Surface mulch can increase worm numbers naturally.","zh":"表層覆蓋物可以自然增加蚯蚓數量。"},{"en":"Surface mulch is a layer of organic material placed on top of soil.","zh":"surface mulch 指放在土壤表面的有機材料層。"},{"en":"Gardeners may use leaves, straw, or compost as surface mulch.","zh":"園丁可能使用樹葉、稻草或堆肥作表層覆蓋物。"},{"en":"Mulch keeps soil moist and provides food for worms and micro-organisms.","zh":"覆蓋物保持土壤潮濕，並為蚯蚓和微生物提供食物。"},{"en":"This phrase is common in gardening and sustainable farming.","zh":"這個短語常見於園藝和可持續農業。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":13},{"front":"raise worm numbers","meaning":"增加蚯蚓數量","examples":[{"en":"Adding organic mulch can raise worm numbers.","zh":"添加有機覆蓋物可以增加蚯蚓數量。"},{"en":"To raise worm numbers means to increase the population of worms in an area.","zh":"raise worm numbers 指增加某地區蚯蚓的數量。"},{"en":"A gardener can raise worm numbers by adding compost and avoiding harsh chemicals.","zh":"園丁可以透過添加堆肥和避免強烈化學品來增加蚯蚓數量。"},{"en":"More worms can improve soil structure, nutrients, and drainage.","zh":"更多蚯蚓可以改善土壤結構、養分和排水。"},{"en":"This phrase connects a farming practice with ecological improvement.","zh":"這個短語把農業做法與生態改善連接起來。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":13},{"front":"natural benefit","meaning":"自然益處","examples":[{"en":"Earthworms provide a natural benefit to the soil.","zh":"蚯蚓為土壤提供自然益處。"},{"en":"A natural benefit is a helpful effect produced by nature rather than by artificial methods.","zh":"natural benefit 指由大自然而非人工方法產生的有益效果。"},{"en":"Trees provide a natural benefit by cooling streets and cleaning air.","zh":"樹木透過降低街道溫度和淨化空氣提供自然益處。"},{"en":"Natural benefits can reduce the need for expensive human-made solutions.","zh":"自然益處可以減少對昂貴人工解決方案的需要。"},{"en":"This phrase highlights useful ecological services.","zh":"這個短語突出有用的生態服務。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":14},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Candidates choose the correct letter for each question.","zh":"考生為每條問題選出正確字母。"},{"en":"To choose the correct letter means to select the option letter that matches the answer.","zh":"choose the correct letter 指選出與答案相符的選項字母。"},{"en":"In a reading test, students may choose A, B, C, or D after checking the passage.","zh":"在閱讀測驗中，學生查閱文章後可能選 A、B、C 或 D。"},{"en":"A student can understand the idea but lose marks by writing the wrong letter.","zh":"學生可能理解意思，但因寫錯字母而失分。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":14},{"front":"Charles Darwin thought that","meaning":"Charles Darwin 認為","examples":[{"en":"The question asks what Charles Darwin thought about worms.","zh":"題目問 Charles Darwin 對蚯蚓有何看法。"},{"en":"Charles Darwin thought that introduces an idea or opinion attributed to Darwin.","zh":"Charles Darwin thought that 用來引出歸屬於 Darwin 的想法或意見。"},{"en":"A history question may ask what a scientist thought about a discovery.","zh":"歷史題可能問某科學家對一項發現有何看法。"},{"en":"Students must answer from the passage, not from general knowledge about Darwin.","zh":"學生必須根據文章作答，而不是根據關於 Darwin 的常識。"},{"en":"This phrase is used to identify a person’s viewpoint.","zh":"這個短語用來指出某人的觀點。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":14},{"front":"only moderately important","meaning":"只是中等重要","examples":[{"en":"The option suggests that worms were only moderately important.","zh":"這個選項暗示蚯蚓只是中等重要。"},{"en":"Only moderately important means important to a limited or medium degree, not greatly important.","zh":"only moderately important 指重要程度有限或中等，而不是非常重要。"},{"en":"A small quiz may be only moderately important if the final exam counts much more.","zh":"如果期末考佔分更重，小測可能只是中等重要。"},{"en":"If something is only moderately important, it matters but is not central.","zh":"如果某事只是中等重要，它有作用但不是核心。"},{"en":"This phrase is useful for judging strength of importance.","zh":"評估重要程度時，這個短語很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":14},{"front":"number in the many millions","meaning":"數以百萬計","examples":[{"en":"The option suggests that worms may number in the many millions.","zh":"這個選項暗示蚯蚓可能數以百萬計。"},{"en":"To number in the many millions means to exist in quantities of many millions.","zh":"number in the many millions 指以許多百萬的數量存在。"},{"en":"Insects in a forest may number in the many millions.","zh":"森林中的昆蟲可能數以百萬計。"},{"en":"Huge numbers of small organisms can have enormous ecological effects.","zh":"大量小生物可以產生巨大生態影響。"},{"en":"This phrase is formal and emphasises very large quantity.","zh":"這個短語較正式，強調非常龐大的數量。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":14},{"front":"a single worm","meaning":"一條蚯蚓","examples":[{"en":"The question asks what is true of a single worm.","zh":"題目問一條蚯蚓有甚麼是正確的。"},{"en":"A single worm means one individual worm, not a whole population.","zh":"single worm 指一個蚯蚓個體，而不是整個群體。"},{"en":"A single worm can still affect soil by eating and producing casts.","zh":"一條蚯蚓仍可以透過進食和產生蚓糞影響土壤。"},{"en":"Looking at one worm helps students understand the body structure before thinking about millions of worms.","zh":"先看一條蚯蚓，有助學生理解身體結構，再思考數以百萬計的蚯蚓。"},{"en":"This phrase narrows attention from a group to one individual.","zh":"這個短語把注意力從群體收窄到單一個體。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":14},{"front":"either male or female","meaning":"不是雄性就是雌性","examples":[{"en":"The option says that a worm is either male or female.","zh":"這個選項說蚯蚓不是雄性就是雌性。"},{"en":"Either male or female means belonging to one sex or the other, but not both.","zh":"either male or female 指屬於其中一種性別，而不是兩者皆有。"},{"en":"Many mammals are either male or female in reproductive anatomy.","zh":"許多哺乳動物在生殖解剖上不是雄性就是雌性。"},{"en":"Earthworms are different because they have both male and female reproductive parts.","zh":"蚯蚓不同，因為牠們同時有雄性和雌性生殖部位。"},{"en":"This phrase is useful when contrasting separate sexes with hermaphroditic organisms.","zh":"對比雌雄分開和雌雄同體生物時，這個短語很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":14},{"front":"a complicated organism","meaning":"複雜的生物體","examples":[{"en":"The option describes a worm as a complicated organism.","zh":"這個選項把蚯蚓描述為複雜的生物體。"},{"en":"A complicated organism is a living thing with many complex structures or systems.","zh":"complicated organism 指具有許多複雜結構或系統的生物。"},{"en":"A human is a complicated organism with specialised organs and body systems.","zh":"人類是有專門器官和身體系統的複雜生物體。"},{"en":"Earthworms may look simple, but their reproduction and movement can still be surprisingly detailed.","zh":"蚯蚓看似簡單，但牠們的繁殖和移動仍可以相當細緻。"},{"en":"This phrase describes biological complexity.","zh":"這個短語描述生物複雜性。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":14},{"front":"stormwater may possibly","meaning":"暴雨積水可能","examples":[{"en":"The question asks what stormwater may possibly do.","zh":"題目問暴雨積水可能會做甚麼。"},{"en":"Stormwater may possibly means rainwater after a storm might do something, though it is not certain.","zh":"stormwater may possibly 指暴雨後的積水或許會造成某事，但並不確定。"},{"en":"Stormwater may possibly flood a basement if the drains are blocked.","zh":"如果排水渠堵塞，暴雨積水可能淹浸地下室。"},{"en":"Possibly signals that this is one hypothesis, not a proven fact.","zh":"possibly 表示這是一個假設，而不是已證實事實。"},{"en":"This phrase is useful when discussing uncertain causes.","zh":"討論不確定原因時，這個短語很有用。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":14},{"front":"clean out worm burrows","meaning":"清理蚯蚓地洞","examples":[{"en":"The option says that stormwater may clean out worm burrows.","zh":"這個選項說暴雨積水可能清理蚯蚓地洞。"},{"en":"To clean out worm burrows means to wash material out of the tunnels where worms live.","zh":"clean out worm burrows 指把蚯蚓居住隧道中的材料沖走。"},{"en":"Heavy rain can clean out a drain by pushing leaves and dirt away.","zh":"大雨可以透過沖走樹葉和污垢來清理排水渠。"},{"en":"In the passage, the issue is flooding burrows, not necessarily cleaning them.","zh":"在文章中，問題是淹浸地洞，而不一定是清理地洞。"},{"en":"This phrase describes water removing material from a space.","zh":"這個短語描述水從空間中移除材料。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":14},{"front":"slow down","meaning":"使……減慢","examples":[{"en":"The option suggests that stormwater may slow down worms.","zh":"這個選項暗示暴雨積水可能使蚯蚓減慢。"},{"en":"To slow down means to reduce speed or make movement slower.","zh":"slow down 指降低速度或令移動變慢。"},{"en":"Heavy traffic can slow down a bus journey.","zh":"嚴重交通擠塞可以使巴士旅程變慢。"},{"en":"Wet conditions may sometimes help movement, while obstacles can slow it down.","zh":"潮濕環境有時可能幫助移動，而障礙則會使其減慢。"},{"en":"This phrase is common in daily, transport, and biological contexts.","zh":"這個短語常見於日常、交通和生物語境。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":14},{"front":"help worms encounter others","meaning":"幫助蚯蚓遇上其他同類","examples":[{"en":"Wet conditions may help worms encounter others.","zh":"潮濕環境可能幫助蚯蚓遇上其他同類。"},{"en":"To help worms encounter others means to make it easier for worms to meet other worms.","zh":"help worms encounter others 指令蚯蚓更容易遇見其他蚯蚓。"},{"en":"A school club helps students encounter others who share the same interest.","zh":"學校學會幫助學生遇見有相同興趣的人。"},{"en":"When worms can move across wet surfaces, they may find mates more easily.","zh":"當蚯蚓能在潮濕表面移動，牠們可能更容易找到配偶。"},{"en":"This phrase connects movement conditions with meeting.","zh":"這個短語把移動條件與相遇連接起來。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":15},{"front":"harden the earth","meaning":"使泥土硬化","examples":[{"en":"The option says that stormwater may harden the earth.","zh":"這個選項說暴雨積水可能使泥土硬化。"},{"en":"To harden the earth means to make soil firm, dry, or difficult to dig into.","zh":"harden the earth 指令泥土變硬、變乾或難以挖入。"},{"en":"Strong sun after rain can harden the earth into a crust.","zh":"雨後強烈陽光可以使泥土硬化成硬殼。"},{"en":"Hardened soil can trap worms on the surface because they cannot burrow down.","zh":"硬化土壤可能把蚯蚓困在地面，因為牠們不能往下鑽。"},{"en":"This phrase describes a change in soil texture.","zh":"這個短語描述土壤質地改變。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":15},{"front":"grazing animals","meaning":"吃草的動物","examples":[{"en":"Grazing animals may weigh less than the worms beneath the soil.","zh":"吃草的動物重量可能少於土壤下方的蚯蚓。"},{"en":"Grazing animals are animals that feed on grass or low plants.","zh":"grazing animals 指以草或低矮植物為食的動物。"},{"en":"Cows, sheep, goats, and horses are common grazing animals.","zh":"牛、羊、山羊和馬都是常見吃草動物。"},{"en":"Grazing animals are easy to see, while worms below them may be hidden but numerous.","zh":"吃草的動物容易看見，而牠們下方的蚯蚓可能隱藏但數量很多。"},{"en":"This phrase is common in farming and ecology.","zh":"這個短語常見於農業和生態。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":15},{"front":"weigh less than","meaning":"比……重量少","examples":[{"en":"The question compares whether grazing animals weigh less than worms.","zh":"題目比較吃草動物是否比蚯蚓重量少。"},{"en":"Weigh less than means have a smaller weight than another thing.","zh":"weigh less than 指重量小於另一物。"},{"en":"A schoolbag should weigh less than a child can carry safely.","zh":"書包重量應少於孩子能安全背負的重量。"},{"en":"The phrase helps compare hidden worm mass with visible animal mass.","zh":"這個短語幫助比較隱藏蚯蚓總重量與可見動物重量。"},{"en":"This phrase is used for weight comparison.","zh":"這個短語用於重量比較。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":15},{"front":"digestive systems","meaning":"消化系統","examples":[{"en":"The question compares the digestive systems of worms and grazing animals.","zh":"題目比較蚯蚓和吃草動物的消化系統。"},{"en":"Digestive systems are the body systems that process food and remove waste.","zh":"digestive systems 指處理食物並排出廢物的身體系統。"},{"en":"Different animals have digestive systems suited to their diets.","zh":"不同動物有適合其飲食的消化系統。"},{"en":"Comparing digestive systems helps students see similarities across very different animals.","zh":"比較消化系統幫助學生看見非常不同動物之間的相似性。"},{"en":"This phrase is a plural form used when comparing more than one organism.","zh":"這個短語是複數形式，用於比較多個生物。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":15},{"front":"very different from","meaning":"與……很不同","examples":[{"en":"The option says that worms have digestive systems very different from those of animals.","zh":"這個選項說蚯蚓的消化系統與動物的很不同。"},{"en":"Very different from means not similar to something else in important ways.","zh":"very different from 指在重要方面與另一事物不相似。"},{"en":"Learning online can feel very different from learning in a classroom.","zh":"網上學習可能感覺與課室學習很不同。"},{"en":"In the passage, the worm’s digestive system is described as similar, not very different.","zh":"在文章中，蚯蚓的消化系統被描述為相似，而不是很不同。"},{"en":"This phrase is useful for strong contrast.","zh":"這個短語適合強烈對比。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":15},{"front":"simpler than","meaning":"比……簡單","examples":[{"en":"The option asks whether animal digestive systems are simpler than those of worms.","zh":"這個選項問動物消化系統是否比蚯蚓的簡單。"},{"en":"Simpler than means less complicated than another thing.","zh":"simpler than 指比另一事物較不複雜。"},{"en":"A checklist is simpler than a long instruction manual.","zh":"清單比長篇說明書簡單。"},{"en":"Comparing complexity helps students understand which system has more parts or stages.","zh":"比較複雜程度有助學生理解哪個系統有更多部分或階段。"},{"en":"This phrase is used when judging relative simplicity.","zh":"判斷相對簡單程度時，會使用這個短語。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":15},{"front":"complete the diagram","meaning":"完成圖表","examples":[{"en":"Candidates complete the diagram using words from the passage.","zh":"考生使用文章中的詞語完成圖表。"},{"en":"To complete the diagram means to fill in missing labels or steps in a visual task.","zh":"complete the diagram 指填入視覺題目中缺失的標籤或步驟。"},{"en":"In a biology exam, students may complete a diagram of the digestive system.","zh":"在生物考試中，學生可能完成消化系統圖表。"},{"en":"This task checks whether students understand both vocabulary and process order.","zh":"這項任務檢查學生是否理解詞彙和過程次序。"},{"en":"This phrase is common in IELTS-style reading questions.","zh":"這個短語常見於 IELTS 類閱讀題。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":15},{"front":"choose no more than two words from","meaning":"從……選出不多於兩個字","examples":[{"en":"Candidates choose no more than two words from the passage.","zh":"考生從文章中選出不多於兩個字。"},{"en":"Choose no more than two words from means use one or two exact words from the source text.","zh":"choose no more than two words from 指從來源文本使用一個或兩個確切詞語。"},{"en":"If the answer is soil particles, it follows the rule of no more than two words.","zh":"如果答案是 soil particles，就符合不多於兩個字的規則。"},{"en":"Writing three words can lose marks even if the idea is correct.","zh":"即使意思正確，寫三個字也可能失分。"},{"en":"This phrase controls answer length in reading tests.","zh":"這個短語控制閱讀測驗中的答案長度。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":15},{"front":"complete the sentences","meaning":"完成句子","examples":[{"en":"Candidates complete the sentences with words from the passage.","zh":"考生用文章中的詞語完成句子。"},{"en":"To complete the sentences means to fill in missing words so the sentences make sense.","zh":"complete the sentences 指填入缺失詞語，使句子意思完整。"},{"en":"Students complete sentences by checking grammar and locating the correct phrase in the text.","zh":"學生透過檢查文法並在文本中定位正確短語來完成句子。"},{"en":"This task tests meaning, word form, and careful reading.","zh":"這項任務測試意思、詞形和仔細閱讀。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":15},{"front":"worm numbers will fall","meaning":"蚯蚓數量會下降","examples":[{"en":"Worm numbers will fall when soil conditions become harmful.","zh":"當土壤條件變得有害，蚯蚓數量會下降。"},{"en":"Worm numbers will fall means the population of worms will decrease.","zh":"worm numbers will fall 指蚯蚓群體數量會減少。"},{"en":"Bird numbers may fall if their habitat is destroyed.","zh":"如果棲息地被破壞，鳥類數量可能下降。"},{"en":"If soil becomes too acidic, fewer worms can survive and reproduce.","zh":"如果土壤變得太酸，較少蚯蚓能生存和繁殖。"},{"en":"This phrase describes population decline.","zh":"這個短語描述族群下降。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":15},{"front":"especially when","meaning":"尤其當……","examples":[{"en":"Worm numbers fall especially when the soil becomes too acidic.","zh":"蚯蚓數量會下降，尤其當土壤變得太酸。"},{"en":"Especially when means particularly in the situation where something happens.","zh":"especially when 指特別是在某情況發生時。"},{"en":"Students make careless mistakes especially when they are tired.","zh":"學生尤其在疲倦時會犯粗心錯誤。"},{"en":"This phrase highlights the condition where the effect is strongest.","zh":"這個短語突出效果最強的條件。"},{"en":"It is useful for identifying the most important circumstance.","zh":"它適合用來指出最重要的情況。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":16},{"front":"high acidity","meaning":"高酸度","examples":[{"en":"Worm numbers will fall when the soil has high acidity.","zh":"當土壤有高酸度時，蚯蚓數量會下降。"},{"en":"High acidity means a high level of acid in soil, water, or another substance.","zh":"high acidity 指土壤、水或其他物質中酸性水平高。"},{"en":"High acidity in a drink can make it taste sharp or sour.","zh":"飲品高酸度會令味道尖銳或酸。"},{"en":"In soil, high acidity can harm organisms that cannot tolerate acid conditions.","zh":"在土壤中，高酸度可以傷害不能忍受酸性環境的生物。"},{"en":"This phrase is common in chemistry and soil science.","zh":"這個短語常見於化學和土壤科學。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":16},{"front":"adding mulch to the soil","meaning":"給土壤添加覆蓋物","examples":[{"en":"Adding mulch to the soil can increase worm numbers.","zh":"給土壤添加覆蓋物可以增加蚯蚓數量。"},{"en":"Adding mulch to the soil means placing organic covering material on or into soil.","zh":"adding mulch to the soil 指把有機覆蓋材料放在土壤表面或加入土壤中。"},{"en":"Gardeners add mulch to the soil to keep it moist and reduce weeds.","zh":"園丁給土壤添加覆蓋物，以保持濕潤並減少雜草。"},{"en":"Mulch provides food and shelter, which can help worm populations grow.","zh":"覆蓋物提供食物和棲身處，可以幫助蚯蚓數量增長。"},{"en":"This phrase describes a practical gardening or farming action.","zh":"這個短語描述實用的園藝或農業行動。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":16},{"front":"shows ecological awareness","meaning":"顯示生態意識","examples":[{"en":"Adding organic mulch shows ecological awareness.","zh":"添加有機覆蓋物顯示生態意識。"},{"en":"Shows ecological awareness means demonstrates understanding of how actions affect the environment.","zh":"shows ecological awareness 指展示出理解行動如何影響環境。"},{"en":"A restaurant shows ecological awareness when it reduces food waste and avoids harmful packaging.","zh":"餐廳減少食物浪費並避免有害包裝時，就是顯示生態意識。"},{"en":"Farmers show ecological awareness by protecting soil organisms, not only crops.","zh":"農民保護土壤生物而不只是作物，就是顯示生態意識。"},{"en":"This phrase connects responsible choices with environmental understanding.","zh":"這個短語把負責任選擇與環境理解連接起來。"}],"source":"84 - Unsung and Lowly Creatures.pdf","sourcePage":16}],"ielts/reading/passage-2/Practice 85":[{"front":"single-gender education","meaning":"單一性別教育","examples":[{"en":"The passage discusses whether single-gender education helps or harms students.","zh":"文章討論單一性別教育是幫助還是傷害學生。"},{"en":"Single-gender education is education in which boys and girls are taught separately.","zh":"單一性別教育是指男生和女生分開接受教育。"},{"en":"Some parents choose single-gender education because they think their child will feel less distracted.","zh":"有些家長選擇單一性別教育，因為他們認為孩子會較少分心。"},{"en":"Single-gender education may affect confidence, friendships, and academic results in different ways.","zh":"單一性別教育可能以不同方式影響自信、友誼和學業成績。"},{"en":"Single-gender education should be judged by evidence, not only by tradition or personal preference.","zh":"單一性別教育應根據證據判斷，而不應只根據傳統或個人喜好。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":1},{"front":"a case made","meaning":"理據是否成立","examples":[{"en":"The title asks whether a convincing case has been made for single-gender education.","zh":"標題問是否已有令人信服的理據支持單一性別教育。"},{"en":"A case made means that enough reasons or evidence have been given to support an argument.","zh":"理據成立是指已提出足夠理由或證據來支持某個論點。"},{"en":"In a school debate, a case is made when students explain their view clearly and support it with examples.","zh":"在校內辯論中，當學生清楚解釋觀點並用例子支持時，理據就較能成立。"},{"en":"If the evidence is weak, listeners may feel that the case has not really been made.","zh":"如果證據薄弱，聽眾可能會覺得理據其實並未成立。"},{"en":"A case made is stronger when it answers possible objections, not just when it sounds confident.","zh":"理據若能回應可能的反駁，而不只是聽起來有信心，就會更有力。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":1},{"front":"modern democracies","meaning":"現代民主國家","examples":[{"en":"Modern democracies often value freedom and equality.","zh":"現代民主國家通常重視自由和平等。"},{"en":"Modern democracies are political systems today in which citizens have rights and can choose leaders.","zh":"現代民主國家是指今日讓公民享有權利並能選擇領袖的政治制度。"},{"en":"In modern democracies, people usually expect schools, laws, and workplaces to treat citizens fairly.","zh":"在現代民主國家，人們通常期望學校、法律和工作場所公平對待公民。"},{"en":"Modern democracies can face tension when freedom of choice conflicts with equality.","zh":"當選擇自由與平等產生衝突時，現代民主國家可能面對矛盾。"},{"en":"Modern democracies are not perfect, but they usually claim to protect basic rights.","zh":"現代民主國家並不完美，但通常聲稱保障基本權利。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":1},{"front":"be instilled with","meaning":"被灌輸；深受……影響","examples":[{"en":"Modern democracies are instilled with the ethics of freedom and equality.","zh":"現代民主國家深受自由和平等的倫理觀影響。"},{"en":"To be instilled with an idea means to be strongly taught or influenced by it over time.","zh":"be instilled with 某種想法，意思是長時間被教導或深受該想法影響。"},{"en":"Children may be instilled with respect for others through family rules and school lessons.","zh":"孩子可能透過家庭規則和學校課堂被灌輸尊重他人的觀念。"},{"en":"If students are instilled with confidence early, they may be more willing to speak in class.","zh":"如果學生從小被灌輸自信，他們可能更願意在課堂發言。"},{"en":"A society instilled with fairness will usually question rules that seem unequal.","zh":"一個深受公平觀念影響的社會，通常會質疑看似不平等的規則。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":1},{"front":"the ethics of","meaning":"……的倫理觀","examples":[{"en":"The education debate is shaped by the ethics of freedom and equality.","zh":"這場教育爭論受到自由和平等的倫理觀影響。"},{"en":"The ethics of something are the moral ideas about what is right, fair, or responsible in that area.","zh":"the ethics of something 指某個範疇中關於對錯、公平或責任的道德觀念。"},{"en":"The ethics of business include honesty, fair pay, and respect for customers.","zh":"商業倫理包括誠實、公平薪酬和尊重顧客。"},{"en":"When people discuss the ethics of education, they ask what schools should do for students morally.","zh":"當人們討論教育倫理時，他們是在問學校在道德上應為學生做甚麼。"},{"en":"The ethics of a policy matter because a rule can be legal but still unfair.","zh":"某項政策的倫理觀很重要，因為一條規則可以合法但仍不公平。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":1},{"front":"equality of the sexes","meaning":"性別平等","examples":[{"en":"Modern democracies support equality of the sexes.","zh":"現代民主國家支持性別平等。"},{"en":"Equality of the sexes means men and women should have equal rights, respect, and opportunities.","zh":"性別平等是指男性和女性應享有平等權利、尊重和機會。"},{"en":"Schools support equality of the sexes when boys and girls can choose the same subjects.","zh":"當男生和女生都能選擇同樣科目時，學校就是在支持性別平等。"},{"en":"Without equality of the sexes, talented people may be blocked because of gender.","zh":"如果沒有性別平等，有才能的人可能因性別而被阻礙。"},{"en":"Equality of the sexes does not mean everyone is identical; it means gender should not limit opportunity.","zh":"性別平等不代表所有人完全一樣；它代表性別不應限制機會。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":1},{"front":"nevertheless","meaning":"然而；儘管如此","examples":[{"en":"Modern democracies value equality; nevertheless, they still offer single-sex education.","zh":"現代民主國家重視平等；然而，它們仍提供單性別教育。"},{"en":"Nevertheless means “however” and introduces a surprising contrast.","zh":"nevertheless 意思是「然而」，用來帶出令人意外的對比。"},{"en":"The exam was difficult; nevertheless, many students passed because they had practised well.","zh":"考試很難；儘管如此，許多學生因為練習充分而合格。"},{"en":"A shop may be expensive; nevertheless, customers return if the service is excellent.","zh":"一間店可能很貴；然而，如果服務出色，顧客仍會回來。"},{"en":"Use nevertheless when the second idea goes against what the first idea makes us expect.","zh":"當第二個意思與第一個意思造成的預期相反時，可以使用 nevertheless。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":1},{"front":"offer the option of","meaning":"提供……的選擇","examples":[{"en":"Many countries still offer the option of single-sex education.","zh":"許多國家仍然提供單性別教育的選擇。"},{"en":"To offer the option of something means to give people a choice to use or choose it.","zh":"offer the option of something 意思是給人使用或選擇某事物的機會。"},{"en":"A school may offer the option of online lessons for students who live far away.","zh":"學校可能為住得遠的學生提供網上課堂的選擇。"},{"en":"Offering the option of flexible work can help parents manage family responsibilities.","zh":"提供彈性工作的選擇，可以幫助父母處理家庭責任。"},{"en":"Offering an option is different from forcing everyone to take it.","zh":"提供一個選擇，並不等於強迫所有人接受它。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":1},{"front":"single-sex education","meaning":"單性別教育","examples":[{"en":"Single-sex education separates boys and girls into different learning environments.","zh":"單性別教育把男生和女生分到不同的學習環境。"},{"en":"Single-sex education means education in which students learn only with classmates of the same sex.","zh":"單性別教育是指學生只與同性同學一起學習的教育模式。"},{"en":"A girls’ school and a boys’ school are both examples of single-sex education.","zh":"女校和男校都是單性別教育的例子。"},{"en":"Supporters say single-sex education can reduce distraction, while critics say it may strengthen stereotypes.","zh":"支持者說單性別教育可以減少分心，而批評者說它可能強化定型觀念。"},{"en":"Single-sex education may work differently depending on teachers, resources, and school culture.","zh":"單性別教育的效果可能因教師、資源和校園文化而不同。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":1},{"front":"separate the genders","meaning":"把不同性別分開","examples":[{"en":"Single-sex education separates the genders into their own classrooms.","zh":"單性別教育把不同性別分到各自的課室。"},{"en":"To separate the genders means to put boys and girls into different groups or places.","zh":"separate the genders 意思是把男生和女生分成不同群體或安排到不同地方。"},{"en":"Some sports lessons separate the genders when activities involve privacy or safety concerns.","zh":"有些體育課在涉及私隱或安全考慮時，會把不同性別分開。"},{"en":"Separating the genders may reduce some problems but create fewer chances for normal interaction.","zh":"把不同性別分開可能減少某些問題，但也會減少正常互動機會。"},{"en":"A school should explain clearly why it wants to separate the genders.","zh":"學校若想把不同性別分開，應清楚解釋原因。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":1},{"front":"traditionally","meaning":"傳統上；以往","examples":[{"en":"Traditionally, women had to fight for equal educational opportunities.","zh":"以往，女性必須為平等教育機會而奮鬥。"},{"en":"Traditionally means in the way something was usually done in the past.","zh":"traditionally 指某事物在過去通常的做法。"},{"en":"Traditionally, many families ate together at home instead of ordering takeaway.","zh":"以往，許多家庭會在家一起吃飯，而不是叫外賣。"},{"en":"A practice may continue traditionally because older people pass it to the next generation.","zh":"一種做法可能因長者傳給下一代而傳統上延續下來。"},{"en":"Traditionally does not always mean correctly; some old customs may need to change.","zh":"traditionally 不一定代表正確；有些舊習俗可能需要改變。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":1},{"front":"fight hard and long","meaning":"長期艱苦奮鬥","examples":[{"en":"Women had to fight hard and long to achieve equality in education.","zh":"女性必須長期艱苦奮鬥，才能在教育上取得平等。"},{"en":"To fight hard and long means to struggle with great effort over a long period.","zh":"fight hard and long 意思是長時間付出很大努力去抗爭。"},{"en":"Workers may fight hard and long for safer conditions if employers ignore accidents.","zh":"如果僱主忽視意外，工人可能會為更安全的環境長期艱苦奮鬥。"},{"en":"A community may fight hard and long before the government finally improves public transport.","zh":"一個社區可能長期艱苦爭取，政府才終於改善公共交通。"},{"en":"People usually fight hard and long when the problem is serious and change is slow.","zh":"當問題嚴重而改變緩慢時，人們通常才需要長期艱苦奮鬥。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":2},{"front":"achieve equal opportunities","meaning":"取得平等機會","examples":[{"en":"Women fought to achieve equal opportunities in education.","zh":"女性為在教育中取得平等機會而奮鬥。"},{"en":"To achieve equal opportunities means to create a situation where people have the same fair chances.","zh":"achieve equal opportunities 意思是建立一種人人都有同等公平機會的情況。"},{"en":"Schools help students achieve equal opportunities when poor families can still access good resources.","zh":"當貧困家庭仍能獲得良好資源時，學校就是幫助學生取得平等機會。"},{"en":"Equal opportunities are harder to achieve if some children lack books, internet access, or support.","zh":"如果有些孩子缺乏書本、網絡或支援，平等機會就更難實現。"},{"en":"Achieving equal opportunities is not just opening the door; people must be able to succeed after entering.","zh":"取得平等機會不只是打開門；人們進入後也必須能夠成功。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":2},{"front":"equal opportunities in education","meaning":"教育上的平等機會","examples":[{"en":"The debate is connected to equal opportunities in education.","zh":"這場爭論與教育上的平等機會有關。"},{"en":"Equal opportunities in education mean all students should have a fair chance to learn and succeed.","zh":"教育上的平等機會是指所有學生都應有公平學習和成功的機會。"},{"en":"Free textbooks and support lessons can improve equal opportunities in education.","zh":"免費課本和支援課堂可以改善教育上的平等機會。"},{"en":"Without equal opportunities in education, family income may decide a child’s future too strongly.","zh":"如果沒有教育上的平等機會，家庭收入可能過度決定孩子的未來。"},{"en":"Equal opportunities in education require fair rules, good teachers, and enough learning resources.","zh":"教育上的平等機會需要公平規則、好老師和足夠學習資源。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":2},{"front":"single-gender controversy","meaning":"單一性別教育爭議","examples":[{"en":"The single-gender controversy largely concerns women.","zh":"單一性別教育爭議主要關乎女性。"},{"en":"A single-gender controversy is a debate about whether separating boys and girls in education is helpful or harmful.","zh":"single-gender controversy 是關於在教育中分隔男生和女生是否有益或有害的爭論。"},{"en":"Parents may join the single-gender controversy when choosing between a mixed school and a girls’ school.","zh":"家長在男女校和女校之間選擇時，可能會參與這場單一性別教育爭議。"},{"en":"The controversy continues because research, values, and personal experiences often point in different directions.","zh":"這場爭議持續，是因為研究、價值觀和個人經驗常指向不同方向。"},{"en":"A controversy becomes more difficult when both sides have some reasonable concerns.","zh":"當雙方都有一些合理關注時，爭議就會變得更難解決。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":2},{"front":"largely concerns","meaning":"主要關乎","examples":[{"en":"The controversy largely concerns whether girls benefit from separation.","zh":"這場爭議主要關乎女生是否因分隔而受益。"},{"en":"Largely concerns means mainly relates to or is mostly about something.","zh":"largely concerns 意思是主要涉及或大多關於某事。"},{"en":"The meeting largely concerns school safety, although exam results will also be mentioned.","zh":"會議主要關乎校園安全，雖然也會提到考試成績。"},{"en":"If a complaint largely concerns noise, the solution should focus first on sound control.","zh":"如果投訴主要關乎噪音，解決方法應先集中在控制聲音。"},{"en":"Largely concerns helps show the main issue without saying it is the only issue.","zh":"largely concerns 用來指出主要問題，但不表示它是唯一問題。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":2},{"front":"advance their cause","meaning":"推動她們的目標","examples":[{"en":"Supporters ask whether single-gender education advances women’s cause.","zh":"支持者問單一性別教育是否推動女性的目標。"},{"en":"To advance someone’s cause means to help their goal, rights, or movement make progress.","zh":"advance someone’s cause 意思是幫助某人的目標、權利或運動取得進展。"},{"en":"Scholarships can advance the cause of poor students by giving them access to university.","zh":"獎學金可以讓貧困學生進入大學，從而推動他們的目標。"},{"en":"Public support may advance a cause because leaders feel pressure to act.","zh":"公眾支持可能推動一項理念，因為領袖會感到行動壓力。"},{"en":"A policy does not advance a cause if it sounds helpful but creates new barriers.","zh":"如果一項政策聽起來有幫助但造成新障礙，它就沒有真正推動該目標。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":2},{"front":"retard their cause","meaning":"阻礙她們的目標","examples":[{"en":"Critics ask whether single-gender education retards women’s cause.","zh":"批評者問單一性別教育是否阻礙女性的目標。"},{"en":"To retard a cause means to slow down or hold back progress toward a goal.","zh":"retard a cause 意思是拖慢或阻礙某個目標的進展。"},{"en":"Unfair hiring rules can retard the cause of workplace equality.","zh":"不公平的招聘規則可能阻礙職場平等的目標。"},{"en":"If students are told some subjects are not for them, this can retard their confidence and ambition.","zh":"如果學生被告知某些科目不適合他們，這可能阻礙他們的自信和抱負。"},{"en":"A policy may retard a cause even when it claims to protect the people involved.","zh":"一項政策即使聲稱保護相關人士，也可能阻礙其目標。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":2},{"front":"supporters on both sides","meaning":"雙方都有支持者","examples":[{"en":"There are supporters on both sides of the debate.","zh":"這場辯論雙方都有支持者。"},{"en":"Supporters on both sides are people who back two opposing opinions in an argument.","zh":"supporters on both sides 指在爭論中支持兩種相反觀點的人。"},{"en":"In a school uniform debate, there may be supporters on both sides with sensible reasons.","zh":"在校服爭論中，雙方都可能有支持者，並各自有合理理由。"},{"en":"When there are supporters on both sides, a decision should consider evidence carefully.","zh":"當雙方都有支持者時，決策應仔細考慮證據。"},{"en":"Supporters on both sides can be sincere even when they strongly disagree.","zh":"雙方支持者即使強烈不同意，也可以是真誠的。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":2},{"front":"be convinced that","meaning":"相信；深信","examples":[{"en":"Each side is convinced that its case is made.","zh":"每一方都深信自己的理據已經成立。"},{"en":"To be convinced that something is true means to strongly believe it because of reasons or experience.","zh":"be convinced that something is true 意思是因理由或經驗而強烈相信某事為真。"},{"en":"A teacher may be convinced that a student can improve after seeing steady effort.","zh":"老師看見學生持續努力後，可能深信該學生能進步。"},{"en":"People become convinced when evidence, examples, and personal experience point the same way.","zh":"當證據、例子和個人經驗都指向同一方向時，人們會變得深信不疑。"},{"en":"Being convinced does not always mean being correct; strong belief still needs evidence.","zh":"深信某事並不一定代表正確；強烈信念仍需要證據。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":2},{"front":"the case is made","meaning":"理據已經成立","examples":[{"en":"Each side believes that the case is made.","zh":"每一方都相信理據已經成立。"},{"en":"The case is made means the argument has been explained well enough to seem convincing.","zh":"the case is made 意思是論點已被解釋得足夠清楚，聽起來有說服力。"},{"en":"In a complaint letter, the case is made when the writer gives dates, details, and clear harm.","zh":"在投訴信中，當作者提供日期、細節和清楚損害時，理據就較能成立。"},{"en":"If important evidence is missing, the case is not fully made.","zh":"如果缺少重要證據，理據就未完全成立。"},{"en":"People may think the case is made too early if they only hear one side.","zh":"如果人們只聽到一方，他們可能太早以為理據已經成立。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":2},{"front":"given that","meaning":"鑑於","examples":[{"en":"Given that segregation has negative connotations, interest in single-gender schooling is surprising.","zh":"鑑於隔離有負面含意，人們對單一性別學校教育感興趣是令人意外的。"},{"en":"Given that means considering the fact that something is true.","zh":"given that 意思是考慮到某個事實。"},{"en":"Given that the train is delayed, we should leave more time for the journey.","zh":"鑑於火車延誤，我們應為旅程預留更多時間。"},{"en":"Given that students have different levels, one lesson plan may not suit everyone.","zh":"鑑於學生程度不同，一份教案未必適合所有人。"},{"en":"Given that introduces important background before a judgement or decision.","zh":"given that 會在判斷或決定前帶出重要背景。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":2},{"front":"negative connotations","meaning":"負面含意","examples":[{"en":"The word “segregation” has negative connotations.","zh":"「segregation」這個詞有負面含意。"},{"en":"Negative connotations are bad or unpleasant feelings connected with a word or idea.","zh":"negative connotations 是指某個詞語或概念令人聯想到不好或不愉快的感覺。"},{"en":"The word cheap can have negative connotations if it suggests poor quality.","zh":"cheap 這個字如果暗示質素差，就可能有負面含意。"},{"en":"A policy name may fail if it carries negative connotations from past unfair treatment.","zh":"如果某個政策名稱令人聯想到過去的不公平待遇，它可能因負面含意而失敗。"},{"en":"Negative connotations can shape how people react before they hear the details.","zh":"負面含意會在人們聽到細節前，已經影響他們的反應。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":3},{"front":"current interest in","meaning":"目前對……的興趣","examples":[{"en":"The current interest in single-gender schooling is somewhat surprising.","zh":"目前對單一性別學校教育的興趣有點令人意外。"},{"en":"Current interest in something means the attention people are giving it now.","zh":"current interest in something 指人們現在對某事的關注。"},{"en":"The current interest in electric cars has grown because fuel costs are high.","zh":"目前人們對電動車的興趣增加，是因為燃油成本高。"},{"en":"Current interest in mental health can lead schools to provide better counselling.","zh":"目前對心理健康的關注，可以促使學校提供更好的輔導。"},{"en":"Current interest may fade if people do not see real results.","zh":"如果人們看不到實際效果，目前的興趣可能會減退。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":3},{"front":"single-gender schooling","meaning":"單一性別學校教育","examples":[{"en":"Single-gender schooling has attracted renewed public interest.","zh":"單一性別學校教育重新引起公眾興趣。"},{"en":"Single-gender schooling means schooling where boys and girls are educated separately.","zh":"single-gender schooling 是指男生和女生分開接受學校教育。"},{"en":"Some families consider single-gender schooling when they want a particular school culture.","zh":"有些家庭在想要某種校園文化時，會考慮單一性別學校教育。"},{"en":"Single-gender schooling may seem attractive if people believe mixed classrooms create pressure.","zh":"如果人們相信男女混合課室會造成壓力，單一性別學校教育可能顯得有吸引力。"},{"en":"The value of single-gender schooling depends on more than separation itself.","zh":"單一性別學校教育的價值不只取決於分隔本身。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":3},{"front":"somewhat surprising","meaning":"有點令人意外","examples":[{"en":"The interest in single-gender schooling is somewhat surprising.","zh":"人們對單一性別學校教育的興趣有點令人意外。"},{"en":"Somewhat surprising means a little unexpected, but not completely shocking.","zh":"somewhat surprising 意思是有點出乎意料，但不是完全震驚。"},{"en":"It is somewhat surprising that the small shop survived while larger stores closed.","zh":"小店生存下來而較大的商店倒閉，這有點令人意外。"},{"en":"A result can be somewhat surprising when it goes against common expectations.","zh":"當結果與普遍預期相反時，它可能有點令人意外。"},{"en":"Somewhat surprising is softer than extremely surprising.","zh":"somewhat surprising 的語氣比 extremely surprising 較溫和。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":3},{"front":"in the same way that","meaning":"正如……一樣","examples":[{"en":"In the same way that racial segregation seems wrong, gender segregation may seem wrong.","zh":"正如種族隔離看似錯誤一樣，性別隔離也可能看似錯誤。"},{"en":"In the same way that introduces a comparison between two similar situations.","zh":"in the same way that 用來帶出兩個相似情況之間的比較。"},{"en":"In the same way that exercise strengthens the body, reading can strengthen the mind.","zh":"正如運動強健身體一樣，閱讀也可以鍛鍊心智。"},{"en":"A teacher may explain a new idea in the same way that students already understand an old one.","zh":"老師可能正如解釋學生已懂的舊概念一樣，去解釋新概念。"},{"en":"This phrase helps readers see one situation through another familiar situation.","zh":"這個短語幫助讀者透過一個熟悉情況理解另一個情況。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":3},{"front":"a progressive society","meaning":"進步社會","examples":[{"en":"A progressive society would not support unfair segregation.","zh":"進步社會不會支持不公平的隔離。"},{"en":"A progressive society is a society that tries to become fairer, more open, and more equal.","zh":"progressive society 是指努力變得更公平、更開放和更平等的社會。"},{"en":"A progressive society may protect disabled people by improving public buildings.","zh":"進步社會可能透過改善公共建築來保障殘疾人士。"},{"en":"A society becomes more progressive when it questions old rules that cause harm.","zh":"當一個社會質疑造成傷害的舊規則時，它就變得更進步。"},{"en":"A progressive society still needs evidence before changing important institutions.","zh":"進步社會在改變重要制度前仍需要證據。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":3},{"front":"on the basis of","meaning":"基於","examples":[{"en":"A progressive society would not separate people on the basis of skin colour.","zh":"進步社會不會基於膚色把人分開。"},{"en":"On the basis of means because of or according to a particular factor.","zh":"on the basis of 意思是因為或根據某個特定因素。"},{"en":"Students should not be judged only on the basis of one exam result.","zh":"學生不應只基於一次考試成績被評價。"},{"en":"A company may hire staff on the basis of skills rather than personal connections.","zh":"公司可以基於技能而不是私人關係聘請員工。"},{"en":"When a decision is made on the basis of unfair factors, people lose trust.","zh":"當決定基於不公平因素而作出時，人們會失去信任。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":3},{"front":"skin colour","meaning":"膚色","examples":[{"en":"Segregation on the basis of skin colour would be unacceptable.","zh":"基於膚色的隔離是不可接受的。"},{"en":"Skin colour refers to the natural colour of a person’s skin.","zh":"skin colour 指一個人皮膚的自然顏色。"},{"en":"People should not be treated differently at school because of skin colour.","zh":"人們不應在學校因膚色而受到不同對待。"},{"en":"Judging someone by skin colour can lead to discrimination and social division.","zh":"根據膚色判斷別人可能導致歧視和社會分裂。"},{"en":"Skin colour tells us nothing about a person’s ability, kindness, or character.","zh":"膚色不能告訴我們一個人的能力、善良或品格。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":3},{"front":"income","meaning":"收入","examples":[{"en":"Schools should not separate students purely on the basis of income.","zh":"學校不應純粹基於收入把學生分開。"},{"en":"Income is the money a person or family earns from work, business, or other sources.","zh":"income 是指個人或家庭從工作、生意或其他來源賺取的金錢。"},{"en":"A student from a low-income family may need financial support for books and transport.","zh":"低收入家庭的學生可能需要書本和交通方面的經濟支援。"},{"en":"If education depends too much on income, rich families gain unfair advantages.","zh":"如果教育過度取決於收入，富裕家庭會得到不公平優勢。"},{"en":"Income can affect opportunities, but it should not decide a student’s worth.","zh":"收入可以影響機會，但不應決定學生的價值。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":3},{"front":"innately wrong","meaning":"本質上錯誤的","examples":[{"en":"Some people feel that gender segregation is innately wrong.","zh":"有些人覺得性別隔離本質上是錯誤的。"},{"en":"Innately wrong means wrong by its basic nature, not only because of its results.","zh":"innately wrong 意思是某事按其本質就是錯的，而不只是因結果不好。"},{"en":"Some people believe cheating is innately wrong even if no one finds out.","zh":"有些人認為作弊本質上是錯的，即使沒有人發現。"},{"en":"A rule may seem innately wrong when it treats people as less valuable from the start.","zh":"當一條規則一開始就把人看得較低，它可能看似本質上錯誤。"},{"en":"Calling something innately wrong is a strong moral judgement.","zh":"稱某事 innately wrong 是一種強烈的道德判斷。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":3},{"front":"in the real world","meaning":"在現實世界中","examples":[{"en":"In the real world, some form of segregation happens all the time.","zh":"在現實世界中，某種形式的隔離一直都在發生。"},{"en":"In the real world means in actual life, not only in theory or imagination.","zh":"in the real world 意思是在實際生活中，而不只是在理論或想像中。"},{"en":"In the real world, students need more than exam skills; they need communication skills too.","zh":"在現實世界中，學生需要的不只是考試技巧，也需要溝通能力。"},{"en":"A plan may sound perfect on paper but fail in the real world.","zh":"一個計劃在紙上可能聽起來完美，但在現實世界中失敗。"},{"en":"This phrase reminds us to test ideas against everyday reality.","zh":"這個短語提醒我們要用日常現實檢驗想法。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":3},{"front":"the society in which we live","meaning":"我們所生活的社會","examples":[{"en":"Segregation occurs in the society in which we live.","zh":"隔離出現在我們所生活的社會中。"},{"en":"The society in which we live means the real community, country, and social environment around us.","zh":"the society in which we live 指我們身處的真實社區、國家和社會環境。"},{"en":"The society in which we live shapes what we think is normal or strange.","zh":"我們所生活的社會會塑造我們覺得甚麼是正常或奇怪。"},{"en":"If the society in which we live values money too much, young people may feel constant pressure.","zh":"如果我們所生活的社會過度重視金錢，年輕人可能感到持續壓力。"},{"en":"This phrase is useful when connecting an argument to everyday social reality.","zh":"這個短語適合用來把論點連繫到日常社會現實。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":4},{"front":"segregation of some sort","meaning":"某種形式的隔離","examples":[{"en":"Segregation of some sort happens in everyday life.","zh":"日常生活中會出現某種形式的隔離。"},{"en":"Segregation of some sort means some kind of separation between groups, even if it is not official.","zh":"segregation of some sort 指群體之間某種程度的分隔，即使不是正式安排。"},{"en":"In a canteen, segregation of some sort may happen when students always sit with the same group.","zh":"在飯堂裡，如果學生總是和同一群人坐在一起，就可能出現某種形式的隔離。"},{"en":"Segregation of some sort can create comfort within a group but distance between groups.","zh":"某種形式的隔離可以在群體內帶來舒適感，但也會在群體之間造成距離。"},{"en":"The phrase is softer than saying complete segregation.","zh":"這個短語比 complete segregation 語氣較溫和。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":4},{"front":"happen all the time","meaning":"經常發生","examples":[{"en":"Social grouping happens all the time.","zh":"社交分組經常發生。"},{"en":"Happen all the time means happen very often or regularly.","zh":"happen all the time 意思是非常經常或定期發生。"},{"en":"Small misunderstandings happen all the time when people communicate by short text messages.","zh":"人們用簡短訊息溝通時，小誤會經常發生。"},{"en":"If mistakes happen all the time, the system probably needs improvement.","zh":"如果錯誤經常發生，系統很可能需要改善。"},{"en":"The phrase is common in speaking when we want to say something is normal or frequent.","zh":"這個短語常用於口語，表示某事很正常或很頻繁。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":4},{"front":"inevitably form","meaning":"不可避免地形成","examples":[{"en":"Clubs and social groups inevitably form among people with similar interests.","zh":"社團和社交群體會在有相似興趣的人之間不可避免地形成。"},{"en":"Inevitably form means naturally develop and be almost impossible to avoid.","zh":"inevitably form 意思是自然發展，幾乎無法避免地形成。"},{"en":"Study groups inevitably form before exams because students want support.","zh":"考試前讀書小組會不可避免地形成，因為學生想得到支援。"},{"en":"When people work together every day, small friendships may inevitably form.","zh":"當人們每天一起工作，小友誼可能不可避免地形成。"},{"en":"Something that inevitably forms is not always planned; it may happen because of human habits.","zh":"不可避免地形成的東西不一定是有計劃的；它可能源於人的習慣。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":4},{"front":"clerical workers","meaning":"文職人員","examples":[{"en":"Clubs may form among clerical workers.","zh":"文職人員之間可能會形成社團。"},{"en":"Clerical workers are office workers who handle documents, records, emails, and administrative tasks.","zh":"clerical workers 是處理文件、紀錄、電郵和行政工作的辦公室人員。"},{"en":"Clerical workers in a school office may answer calls and prepare student files.","zh":"學校辦公室的文職人員可能接聽電話和準備學生檔案。"},{"en":"If there are too few clerical workers, paperwork may pile up and services may slow down.","zh":"如果文職人員太少，文書工作可能堆積，服務也可能變慢。"},{"en":"Clerical workers are important because many organisations depend on accurate daily administration.","zh":"文職人員很重要，因為許多機構依賴準確的日常行政工作。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":4},{"front":"the academically gifted","meaning":"學業資優人士","examples":[{"en":"Special groups may form for the academically gifted.","zh":"學業資優人士可能會形成特別小組。"},{"en":"The academically gifted are students or people who show unusually strong ability in learning or school subjects.","zh":"the academically gifted 指在學習或學科方面表現出特別強能力的學生或人士。"},{"en":"A school may offer extra maths lessons for the academically gifted.","zh":"學校可能為學業資優學生提供額外數學課。"},{"en":"If the academically gifted are not challenged, they may feel bored or lose motivation.","zh":"如果學業資優人士沒有受到足夠挑戰，他們可能感到沉悶或失去動力。"},{"en":"Supporting the academically gifted should not mean ignoring students who struggle.","zh":"支援學業資優人士不應代表忽視學習有困難的學生。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":4},{"front":"those skilled in","meaning":"擅長……的人","examples":[{"en":"Groups may form among those skilled in music or the arts.","zh":"擅長音樂或藝術的人之間可能會形成群體。"},{"en":"Those skilled in something are people who have strong ability in that activity or subject.","zh":"those skilled in something 指在某項活動或科目上有強能力的人。"},{"en":"Those skilled in cooking may help prepare food for a school event.","zh":"擅長烹飪的人可能幫忙為學校活動準備食物。"},{"en":"When those skilled in technology share their knowledge, the whole team can work better.","zh":"當擅長科技的人分享知識，整個團隊可以運作得更好。"},{"en":"This phrase is useful when describing people by ability rather than job title.","zh":"這個短語適合用能力而不是職銜來描述人。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":4},{"front":"the arts","meaning":"藝術","examples":[{"en":"Some students are especially skilled in music or the arts.","zh":"有些學生特別擅長音樂或藝術。"},{"en":"The arts include creative subjects such as music, painting, drama, dance, and literature.","zh":"the arts 包括音樂、繪畫、戲劇、舞蹈和文學等創意科目。"},{"en":"Schools support the arts when they provide studios, instruments, and performance opportunities.","zh":"當學校提供工作室、樂器和表演機會時，就是在支持藝術。"},{"en":"The arts can help students express feelings that are difficult to explain directly.","zh":"藝術可以幫助學生表達難以直接解釋的感受。"},{"en":"The arts are not only hobbies; they can shape culture and identity.","zh":"藝術不只是興趣；它們可以塑造文化和身份。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":4},{"front":"exclusionary cliques","meaning":"排他的朋黨；小圈子","examples":[{"en":"Exclusionary cliques are part of everyday life.","zh":"排他的小圈子是日常生活的一部分。"},{"en":"Exclusionary cliques are small groups that keep others out and make them feel unwelcome.","zh":"exclusionary cliques 是把其他人排除在外、令他們感到不受歡迎的小群體。"},{"en":"In school, an exclusionary clique may refuse to let new students join lunch conversations.","zh":"在學校，排他的小圈子可能拒絕讓新同學加入午餐談話。"},{"en":"Exclusionary cliques can cause loneliness because people feel judged or ignored.","zh":"排他的小圈子可能造成孤獨，因為人們感到被評價或被忽視。"},{"en":"Friendship groups are normal, but they become harmful when they are exclusionary cliques.","zh":"朋友圈很正常，但當它們變成排他的小圈子時，就會有害。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":4},{"front":"classes and in-groups","meaning":"階層及圈內群體","examples":[{"en":"Classes and in-groups form naturally in society.","zh":"階層及圈內群體在社會中自然形成。"},{"en":"Classes and in-groups are social divisions and close groups that people feel they belong to.","zh":"classes and in-groups 指社會階層和人們覺得自己屬於的親密群體。"},{"en":"In a workplace, in-groups may form among employees who share the same department.","zh":"在工作場所，同一部門的員工之間可能形成圈內群體。"},{"en":"Classes and in-groups can give people identity but also create distance from outsiders.","zh":"階層及圈內群體可以給人身份感，但也可能與外人造成距離。"},{"en":"Understanding classes and in-groups helps explain why people do not always mix freely.","zh":"理解階層及圈內群體，有助解釋為何人們不一定會自由混合。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":4},{"front":"part of everyday life","meaning":"日常生活的一部分","examples":[{"en":"Social grouping is part of everyday life.","zh":"社交分組是日常生活的一部分。"},{"en":"Part of everyday life means something happens normally and commonly in daily situations.","zh":"part of everyday life 意思是某事在日常情況中正常而常見地發生。"},{"en":"Using a phone to pay for transport has become part of everyday life in many cities.","zh":"在許多城市，用手機支付交通費已成為日常生活的一部分。"},{"en":"When something becomes part of everyday life, people may stop noticing it.","zh":"當某事成為日常生活的一部分，人們可能不再留意它。"},{"en":"A problem can be serious even if it is part of everyday life.","zh":"一個問題即使是日常生活的一部分，也仍然可能很嚴重。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":4},{"front":"idealistic illusion","meaning":"理想化的錯覺","examples":[{"en":"It may be an idealistic illusion to condemn single-gender settings on that basis alone.","zh":"單憑那一點譴責單一性別環境，可能是一種理想化的錯覺。"},{"en":"An idealistic illusion is a hopeful belief that sounds morally attractive but may ignore reality.","zh":"idealistic illusion 是聽起來道德上吸引、但可能忽視現實的樂觀信念。"},{"en":"Believing that every argument can be solved by one polite conversation may be an idealistic illusion.","zh":"相信每場爭論都可以靠一次禮貌對話解決，可能是理想化的錯覺。"},{"en":"An idealistic illusion can lead people to design policies that fail in real classrooms.","zh":"理想化的錯覺可能令人設計出在真實課室中失敗的政策。"},{"en":"The phrase is critical: it suggests that a beautiful idea may not be practical.","zh":"這個短語帶有批評意味：它暗示美好的想法未必實際。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":5},{"front":"condemn something on that basis alone","meaning":"單憑那一點譴責……","examples":[{"en":"It may be unfair to condemn single-gender settings on that basis alone.","zh":"單憑那一點譴責單一性別環境，可能是不公平的。"},{"en":"To condemn something on that basis alone means to strongly criticise it because of only one reason.","zh":"condemn something on that basis alone 意思是只因一個理由就強烈批評某事。"},{"en":"It is unfair to condemn a student on that basis alone if one exam result was poor.","zh":"如果學生只有一次考試成績差，單憑那一點譴責他是不公平的。"},{"en":"Condemning a policy on that basis alone may ignore benefits, context, or other evidence.","zh":"單憑那一點譴責一項政策，可能忽視好處、背景或其他證據。"},{"en":"This phrase warns us not to judge too quickly from a single point.","zh":"這個短語提醒我們不要因單一理由太快下判斷。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":5},{"front":"single-gender settings","meaning":"單一性別環境","examples":[{"en":"Single-gender settings may exist in schools or classrooms.","zh":"單一性別環境可能存在於學校或課室中。"},{"en":"Single-gender settings are places or situations where only one gender is present or included.","zh":"single-gender settings 指只有一種性別在場或被包括的地方或情況。"},{"en":"A girls-only coding class is an example of a single-gender setting.","zh":"女生專屬編程班就是單一性別環境的一個例子。"},{"en":"Single-gender settings may make some students feel safer but may reduce mixed interaction.","zh":"單一性別環境可能令部分學生感到較安全，但可能減少男女混合互動。"},{"en":"The effect of single-gender settings depends on why they are used and how they are managed.","zh":"單一性別環境的效果取決於使用原因和管理方式。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":5},{"front":"co-educational advocates","meaning":"男女校教育倡議者","examples":[{"en":"Many co-educational advocates oppose single-gender schooling.","zh":"許多男女校教育倡議者反對單一性別學校教育。"},{"en":"Co-educational advocates are people who support educating boys and girls together.","zh":"co-educational advocates 是支持男生和女生一起受教育的人。"},{"en":"Co-educational advocates may argue that mixed schools prepare students for real society.","zh":"男女校教育倡議者可能主張混合學校讓學生為真實社會作準備。"},{"en":"If co-educational advocates want to persuade parents, they need more than idealistic language.","zh":"如果男女校教育倡議者想說服家長，他們需要的不只是理想化語言。"},{"en":"Co-educational advocates can still accept that mixed schools also have problems.","zh":"男女校教育倡議者也可以承認男女校同樣有問題。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":5},{"front":"necessarily be condemned","meaning":"必然受到譴責","examples":[{"en":"Single-gender education may need to be condemned on other grounds.","zh":"單一性別教育可能需要基於其他理由受到譴責。"},{"en":"Necessarily be condemned means have to be strongly criticised because of unavoidable reasons.","zh":"necessarily be condemned 指因不可避免的理由而必須受到強烈批評。"},{"en":"A policy should not necessarily be condemned just because it is unfamiliar.","zh":"一項政策不應只因陌生就必然受到譴責。"},{"en":"If a rule clearly harms students, it may necessarily be condemned even if it has supporters.","zh":"如果一條規則明顯傷害學生，即使有人支持，也可能必然受到譴責。"},{"en":"The word necessarily asks whether criticism must follow, or whether more evidence is needed.","zh":"necessarily 這個字是在問批評是否必然成立，還是需要更多證據。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":5},{"front":"on other grounds","meaning":"基於其他理由","examples":[{"en":"The system must be judged on other grounds.","zh":"這個制度必須基於其他理由來判斷。"},{"en":"On other grounds means for different reasons or according to different considerations.","zh":"on other grounds 意思是因不同理由或根據不同考慮。"},{"en":"A school may reject an application on other grounds, such as missing documents.","zh":"學校可能基於其他理由拒絕申請，例如文件不齊。"},{"en":"If test scores are unclear, a teacher may judge progress on other grounds, such as effort.","zh":"如果考試分數不清楚，老師可能基於其他理由判斷進步，例如努力程度。"},{"en":"This phrase helps shift an argument from one reason to another.","zh":"這個短語有助把論點從一個理由轉到另一個理由。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":5},{"front":"the issue is complicated","meaning":"問題很複雜","examples":[{"en":"The issue is complicated because the evidence is mixed.","zh":"由於證據混雜，問題很複雜。"},{"en":"The issue is complicated means the problem is not simple and has many connected parts.","zh":"the issue is complicated 意思是問題並不簡單，而是有許多互相關連的部分。"},{"en":"Choosing a school is complicated because cost, distance, teaching quality, and friendships all matter.","zh":"選擇學校很複雜，因為費用、距離、教學質素和友誼都重要。"},{"en":"An issue becomes complicated when reasonable people disagree for different good reasons.","zh":"當合理的人基於不同好理由而意見不合時，問題就會變得複雜。"},{"en":"Saying the issue is complicated prepares readers for a balanced discussion.","zh":"說問題很複雜，可以讓讀者準備閱讀一個平衡討論。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":5},{"front":"sink into","meaning":"陷入","examples":[{"en":"Research can sink into a morass of conflicting data.","zh":"研究可能陷入一團互相矛盾的數據之中。"},{"en":"Sink into means gradually fall into a bad, confused, or difficult state.","zh":"sink into 意思是逐漸陷入糟糕、混亂或困難的狀態。"},{"en":"A meeting can sink into argument if no one controls the discussion.","zh":"如果沒有人控制討論，會議可能陷入爭吵。"},{"en":"A project may sink into delay when responsibilities are unclear.","zh":"當責任不清楚時，項目可能陷入延誤。"},{"en":"This phrase often suggests a slow movement from order into disorder.","zh":"這個短語常暗示從有秩序慢慢變成混亂。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":5},{"front":"a morass of","meaning":"一團混亂的……","examples":[{"en":"The debate has become a morass of conflicting data.","zh":"這場爭論已變成一團互相矛盾的數據。"},{"en":"A morass of something is a confusing mass of problems, details, or information.","zh":"a morass of something 指一大堆令人混亂的問題、細節或資訊。"},{"en":"A student may feel lost in a morass of grammar rules before seeing clear examples.","zh":"學生在看到清楚例子前，可能迷失在一團文法規則之中。"},{"en":"Poor organisation can turn a simple project into a morass of emails and missed deadlines.","zh":"組織差可以把簡單項目變成一團電郵和錯過期限的混亂。"},{"en":"The phrase usually suggests that the situation is hard to escape or understand.","zh":"這個短語通常暗示情況難以擺脫或理解。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":5},{"front":"conflicting data","meaning":"互相矛盾的數據","examples":[{"en":"Research on single-gender schooling often produces conflicting data.","zh":"關於單一性別學校教育的研究常產生互相矛盾的數據。"},{"en":"Conflicting data are pieces of information or results that seem to disagree with one another.","zh":"conflicting data 是看似彼此不一致的資料或結果。"},{"en":"Two surveys may give conflicting data about how much students enjoy online learning.","zh":"兩項調查可能對學生有多喜歡網上學習給出互相矛盾的數據。"},{"en":"Conflicting data make decisions harder because each side can point to different evidence.","zh":"互相矛盾的數據令決策更困難，因為每一方都可以指出不同證據。"},{"en":"When data conflict, researchers should check methods before drawing conclusions.","zh":"當數據互相矛盾時，研究者應先檢查方法再下結論。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":5},{"front":"emotional argument","meaning":"情緒化論點","examples":[{"en":"The debate sometimes involves emotional argument rather than evidence.","zh":"這場辯論有時涉及情緒化論點，而不是證據。"},{"en":"Emotional argument relies mainly on feelings such as fear, anger, pride, or sympathy.","zh":"emotional argument 主要依賴恐懼、憤怒、驕傲或同情等情感。"},{"en":"A parent may make an emotional argument if they describe only their own child’s painful experience.","zh":"如果家長只描述自己孩子的痛苦經歷，就可能提出情緒化論點。"},{"en":"Emotional argument can attract attention, but it may hide weak evidence.","zh":"情緒化論點可以吸引注意，但可能掩蓋薄弱證據。"},{"en":"Good discussion can include emotion, but it should not replace facts.","zh":"好的討論可以包含情感，但情感不應取代事實。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":5},{"front":"come out with","meaning":"提出；發表","examples":[{"en":"One study may come out with strong proof of single-gender schooling.","zh":"一項研究可能提出支持單一性別學校教育的有力證據。"},{"en":"Come out with means produce, announce, or present something, especially a result or statement.","zh":"come out with 意思是產生、宣布或提出某事，尤其是結果或說法。"},{"en":"A company may come out with a new phone after months of rumours.","zh":"一家公司可能在幾個月傳聞後推出新手機。"},{"en":"If a report comes out with surprising findings, people may change their opinions quickly.","zh":"如果一份報告發表令人意外的發現，人們可能很快改變看法。"},{"en":"Come out with can sound casual, so use it carefully in formal writing.","zh":"come out with 語氣可以較口語，所以正式寫作時要小心使用。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":6},{"front":"strong proof of","meaning":"……的有力證據","examples":[{"en":"Some studies claim strong proof of the efficacy of single-gender schooling.","zh":"有些研究聲稱有單一性別學校教育成效的有力證據。"},{"en":"Strong proof of something means convincing evidence that something is true or effective.","zh":"strong proof of something 指某事真實或有效的有說服力證據。"},{"en":"A clear video may provide strong proof of what happened in an accident.","zh":"清楚影片可能提供事故經過的有力證據。"},{"en":"Without strong proof of improvement, parents may not support a new school policy.","zh":"如果沒有改善的有力證據，家長可能不支持新的學校政策。"},{"en":"Strong proof should be based on reliable evidence, not only personal stories.","zh":"有力證據應基於可靠證據，而不只是個人故事。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":6},{"front":"the efficacy of","meaning":"……的成效","examples":[{"en":"Researchers disagree about the efficacy of single-gender schooling.","zh":"研究者對單一性別學校教育的成效意見不一。"},{"en":"The efficacy of something means how effective it is in producing the intended result.","zh":"the efficacy of something 指某事在產生預期結果方面有多有效。"},{"en":"Doctors test the efficacy of a medicine before recommending it widely.","zh":"醫生會在廣泛建議一種藥物前測試其成效。"},{"en":"The efficacy of a teaching method depends on whether students actually learn better.","zh":"一種教學方法的成效取決於學生是否真的學得更好。"},{"en":"Discussing efficacy focuses on results, not just intentions.","zh":"討論 efficacy 是集中在結果，而不只是意圖。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":6},{"front":"cause a resurgence of interest","meaning":"引起興趣復甦","examples":[{"en":"A positive study can cause a resurgence of interest in single-gender schooling.","zh":"一項正面研究可以引起人們對單一性別學校教育的興趣復甦。"},{"en":"To cause a resurgence of interest means to make people become interested in something again.","zh":"cause a resurgence of interest 意思是令大家重新對某事感興趣。"},{"en":"A successful film can cause a resurgence of interest in an old book.","zh":"一部成功電影可以引起人們對一本舊書的興趣復甦。"},{"en":"New evidence may cause a resurgence of interest in a teaching method once considered outdated.","zh":"新證據可能令人重新對曾被視為過時的教學方法感興趣。"},{"en":"A resurgence of interest may be temporary if later results are disappointing.","zh":"如果之後的結果令人失望，興趣復甦可能只是暫時的。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":6},{"front":"positive public sentiment","meaning":"正面的公眾情緒","examples":[{"en":"Strong research claims can create positive public sentiment.","zh":"強烈的研究說法可以創造正面的公眾情緒。"},{"en":"Positive public sentiment means favourable feelings or attitudes among ordinary people.","zh":"positive public sentiment 指普通大眾的支持性情感或態度。"},{"en":"A school may gain positive public sentiment after helping students during a crisis.","zh":"學校在危機中幫助學生後，可能獲得正面的公眾情緒。"},{"en":"Positive public sentiment can pressure leaders to support a policy.","zh":"正面的公眾情緒可以向領袖施壓，令他們支持某項政策。"},{"en":"Public sentiment can be positive even before all evidence is fully checked.","zh":"即使所有證據尚未完全核實，公眾情緒也可能已經很正面。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":6},{"front":"only to be met later by","meaning":"隨後卻遭到……","examples":[{"en":"A supportive study may appear, only to be met later by harsh criticism.","zh":"一項支持性研究可能出現，隨後卻遭到嚴厲批評。"},{"en":"Only to be met later by means that something is followed unexpectedly by a negative reaction or opposite result.","zh":"only to be met later by 意思是某事後來意外地遭遇負面反應或相反結果。"},{"en":"A new rule was welcomed at first, only to be met later by complaints from parents.","zh":"一條新規則起初受到歡迎，隨後卻遭到家長投訴。"},{"en":"A product may sell well in the first week, only to be met later by poor reviews.","zh":"一件產品第一週可能賣得很好，隨後卻遭到差評。"},{"en":"This phrase is useful for showing a sharp turn after an earlier expectation.","zh":"這個短語適合用來顯示早前預期之後的急轉彎。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":6},{"front":"harshly titled article","meaning":"標題尖銳的文章","examples":[{"en":"A harshly titled article attacked the claims about single-sex schooling.","zh":"一篇標題尖銳的文章攻擊了關於單性別學校教育的說法。"},{"en":"A harshly titled article has a title that uses strong, critical, or severe language.","zh":"harshly titled article 指標題使用強烈、批判或嚴厲語言的文章。"},{"en":"A harshly titled article about school meals may immediately make readers expect criticism.","zh":"一篇關於學校膳食而標題尖銳的文章，可能立即令讀者預期它會批評。"},{"en":"Harsh titles can attract attention but may make a debate more emotional.","zh":"尖銳標題可以吸引注意，但可能令辯論更情緒化。"},{"en":"A harshly titled article is not always wrong, but its tone may be aggressive.","zh":"標題尖銳的文章不一定錯，但語氣可能具攻擊性。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":6},{"front":"pseudoscience","meaning":"偽科學","examples":[{"en":"Critics described some claims about single-sex schooling as pseudoscience.","zh":"批評者把某些關於單性別學校教育的說法形容為偽科學。"},{"en":"Pseudoscience is something that sounds scientific but is not supported by reliable scientific methods.","zh":"pseudoscience 指聽起來像科學、但沒有可靠科學方法支持的東西。"},{"en":"A health product may be pseudoscience if it promises cures without proper testing.","zh":"如果一種健康產品沒有正式測試卻承諾治療效果，它可能是偽科學。"},{"en":"Pseudoscience can spread quickly when people trust confident language more than evidence.","zh":"當人們相信自信語言多於證據時，偽科學可以迅速傳播。"},{"en":"Calling an argument pseudoscience is a serious criticism of its evidence and methods.","zh":"稱某論點為偽科學，是對其證據和方法的嚴重批評。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":6},{"front":"be published and endorsed by","meaning":"由……刊登並支持","examples":[{"en":"The article was published and endorsed by several respected magazines.","zh":"那篇文章由數本受尊重的雜誌刊登並支持。"},{"en":"To be published and endorsed by someone means to be printed or released and publicly supported by them.","zh":"be published and endorsed by someone 指由某方刊登或發布，並得到其公開支持。"},{"en":"A report may be published and endorsed by a university if experts consider it reliable.","zh":"如果專家認為一份報告可靠，它可能由大學刊登並支持。"},{"en":"When advice is published and endorsed by a trusted organisation, people are more likely to accept it.","zh":"當建議由可信機構刊登並支持時，人們較可能接受。"},{"en":"Publication gives access; endorsement gives approval.","zh":"刊登帶來接觸機會；支持則帶來認可。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":6},{"front":"respected magazines","meaning":"受尊重的雜誌","examples":[{"en":"Several respected magazines endorsed the critical article.","zh":"數本受尊重的雜誌支持了那篇批評文章。"},{"en":"Respected magazines are magazines trusted by readers because of their quality, history, or careful standards.","zh":"respected magazines 是因質素、歷史或嚴謹標準而受到讀者信任的雜誌。"},{"en":"A respected magazine can influence public opinion by choosing which stories to publish.","zh":"受尊重的雜誌可以透過選擇刊登哪些故事來影響公眾意見。"},{"en":"If respected magazines support an argument, readers may treat it more seriously.","zh":"如果受尊重的雜誌支持一個論點，讀者可能會更認真看待它。"},{"en":"Respected magazines can still make mistakes, so evidence should still be checked.","zh":"受尊重的雜誌仍可能犯錯，所以證據仍應被核查。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":6},{"front":"arguments on both sides","meaning":"雙方的論點","examples":[{"en":"Arguments on both sides often seem persuasive.","zh":"雙方的論點常看似有說服力。"},{"en":"Arguments on both sides are reasons given by people who support opposite positions.","zh":"arguments on both sides 指支持相反立場的人提出的理由。"},{"en":"In the homework debate, arguments on both sides may include stress, learning, family time, and discipline.","zh":"在功課爭論中，雙方的論點可能包括壓力、學習、家庭時間和紀律。"},{"en":"When arguments on both sides sound reasonable, evidence becomes especially important.","zh":"當雙方的論點聽起來都合理時，證據就特別重要。"},{"en":"Understanding arguments on both sides helps students write more balanced essays.","zh":"理解雙方的論點有助學生寫出更平衡的文章。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":6},{"front":"apparent validity","meaning":"表面上的合理性","examples":[{"en":"The arguments have apparent validity.","zh":"這些論點具有表面上的合理性。"},{"en":"Apparent validity means something seems reasonable or true at first sight.","zh":"apparent validity 指某事初看似乎合理或真實。"},{"en":"A complaint may have apparent validity if many people report the same problem.","zh":"如果很多人報告同一問題，投訴可能具有表面上的合理性。"},{"en":"Apparent validity can disappear when the details are checked carefully.","zh":"當細節被仔細檢查後，表面上的合理性可能消失。"},{"en":"The word apparent warns us that something may only seem valid on the surface.","zh":"apparent 這個字提醒我們，某事可能只是表面上有效。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":7},{"front":"accord with","meaning":"與……一致","examples":[{"en":"Many arguments accord with common sense.","zh":"許多論點與常識一致。"},{"en":"Accord with means match, agree with, or fit something.","zh":"accord with 意思是與某事相符、一致或吻合。"},{"en":"A school rule should accord with basic fairness if it affects all students.","zh":"如果校規影響所有學生，它應與基本公平一致。"},{"en":"If a claim does not accord with the facts, it should be questioned.","zh":"如果一個說法與事實不一致，就應受到質疑。"},{"en":"An idea may accord with common sense but still need evidence.","zh":"一個想法可能與常識一致，但仍需要證據。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":7},{"front":"on the surface","meaning":"表面上","examples":[{"en":"On the surface, both sides seem to have valid arguments.","zh":"表面上，雙方似乎都有有效論點。"},{"en":"On the surface means when first looked at, before deeper examination.","zh":"on the surface 意思是初步看來，尚未深入檢查之前。"},{"en":"On the surface, the job looks easy, but it requires careful planning.","zh":"表面上，這份工作看起來容易，但它需要仔細規劃。"},{"en":"A policy may look fair on the surface while hiding unequal effects.","zh":"一項政策表面上可能看似公平，卻隱藏不平等影響。"},{"en":"This phrase signals that the deeper truth may be different.","zh":"這個短語暗示更深層的真相可能不同。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":7},{"front":"common sense","meaning":"常識","examples":[{"en":"The arguments often accord with common sense.","zh":"這些論點常與常識一致。"},{"en":"Common sense is practical judgement based on everyday experience.","zh":"common sense 是基於日常經驗的實際判斷。"},{"en":"Common sense tells us not to cross a busy road without looking.","zh":"常識告訴我們，不應不看路就橫過繁忙馬路。"},{"en":"Common sense can help with simple decisions, but complex problems still need evidence.","zh":"常識可以幫助簡單決策，但複雜問題仍需要證據。"},{"en":"An argument may sound like common sense because it feels familiar, not because it is proven.","zh":"一個論點可能因聽起來熟悉而像常識，並不一定因為它已被證明。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":7},{"front":"personal observation","meaning":"個人觀察","examples":[{"en":"Some claims are based on personal observation rather than firm evidence.","zh":"有些說法基於個人觀察，而不是堅實證據。"},{"en":"Personal observation is what someone notices from their own experience.","zh":"personal observation 是某人從自身經驗中注意到的事情。"},{"en":"A teacher’s personal observation may help identify a student who feels lonely.","zh":"老師的個人觀察可能幫助發現感到孤獨的學生。"},{"en":"Personal observation can be useful, but it may not represent everyone’s experience.","zh":"個人觀察可以有用，但未必代表所有人的經驗。"},{"en":"Research becomes stronger when personal observation is tested against wider data.","zh":"當個人觀察與更廣泛數據互相檢驗時，研究會更有力。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":7},{"front":"proponents of","meaning":"……的支持者","examples":[{"en":"Proponents of single-gender education argue that it improves results.","zh":"單一性別教育的支持者主張它能改善成績。"},{"en":"Proponents of something are people who support it and argue in favour of it.","zh":"proponents of something 指支持某事並為其辯護的人。"},{"en":"Proponents of public transport say it can reduce traffic and pollution.","zh":"公共交通的支持者說它可以減少交通和污染。"},{"en":"Proponents of a policy usually try to show its benefits and answer criticism.","zh":"一項政策的支持者通常會嘗試展示其好處並回應批評。"},{"en":"The word proponents is more formal than supporters.","zh":"proponents 這個字比 supporters 較正式。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":7},{"front":"separating the genders","meaning":"分隔不同性別","examples":[{"en":"Proponents of separating the genders claim that students learn better.","zh":"分隔不同性別的支持者聲稱學生會學得更好。"},{"en":"Separating the genders means placing boys and girls in different groups or learning spaces.","zh":"separating the genders 意思是把男生和女生放在不同群組或學習空間。"},{"en":"A school may consider separating the genders for certain sports or health lessons.","zh":"學校可能在某些體育或健康課中考慮分隔不同性別。"},{"en":"Separating the genders may change classroom behaviour, but it may also reduce normal cooperation.","zh":"分隔不同性別可能改變課堂行為，但也可能減少正常合作。"},{"en":"The phrase focuses on the action of division, not the whole school system.","zh":"這個短語集中在分隔這個動作，而不是整個學校制度。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":7},{"front":"promote better educational results","meaning":"促進更好的教育成果","examples":[{"en":"Supporters argue that single-gender education promotes better educational results.","zh":"支持者主張單一性別教育能促進更好的教育成果。"},{"en":"To promote better educational results means to help students learn more successfully.","zh":"promote better educational results 意思是幫助學生更成功地學習。"},{"en":"Smaller classes may promote better educational results because teachers can give more attention.","zh":"小班教學可能促進更好的教育成果，因為老師可以給予更多關注。"},{"en":"Better educational results may come from feedback, practice, and support, not only school structure.","zh":"更好的教育成果可能來自回饋、練習和支援，而不只是學校結構。"},{"en":"A method should be measured carefully before we say it promotes better educational results.","zh":"在說某方法能促進更好的教育成果前，應仔細衡量它。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":7},{"front":"raw academic scores","meaning":"原始學業成績","examples":[{"en":"Supporters refer not only to raw academic scores but also to behaviour.","zh":"支持者不只提到原始學業成績，也提到行為。"},{"en":"Raw academic scores are simple marks or grades before deeper explanation or adjustment.","zh":"raw academic scores 是未經深入解釋或調整的簡單分數或成績。"},{"en":"A student’s raw academic scores may rise, but confidence and curiosity may still fall.","zh":"學生的原始學業成績可能上升，但自信和好奇心仍可能下降。"},{"en":"Raw academic scores can be misleading if one school admits stronger students from the start.","zh":"如果一間學校一開始就收取較強學生，原始學業成績可能具誤導性。"},{"en":"Education should consider raw academic scores, but not only raw academic scores.","zh":"教育應考慮原始學業成績，但不應只考慮原始學業成績。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":7},{"front":"in behaviour","meaning":"在行為方面","examples":[{"en":"Some supporters claim that single-gender schooling improves behaviour.","zh":"有些支持者聲稱單一性別學校教育在行為方面有所改善。"},{"en":"In behaviour means in the way people act, respond, or treat others.","zh":"in behaviour 指在人們行動、回應或對待他人的方式方面。"},{"en":"A tired child may show changes in behaviour, such as anger or silence.","zh":"疲倦的孩子可能在行為方面出現變化，例如憤怒或沉默。"},{"en":"If a classroom rule improves behaviour, students may listen more and interrupt less.","zh":"如果一條課室規則改善行為，學生可能更常聆聽、較少打斷。"},{"en":"Changes in behaviour are important because learning depends partly on how students act together.","zh":"行為方面的改變很重要，因為學習部分取決於學生如何一起相處。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":7},{"front":"the standard support for","meaning":"對……的標準支持理據","examples":[{"en":"The standard support for this claim is the idea of innate gender differences.","zh":"對這個說法的標準支持理據，是天生性別差異這個想法。"},{"en":"The standard support for a claim is the usual reason people give to defend it.","zh":"the standard support for a claim 指人們通常用來支持某說法的理由。"},{"en":"The standard support for school uniforms is that they reduce visible income differences.","zh":"支持校服的標準理據是它們能減少可見的收入差異。"},{"en":"If the standard support is weak, the whole argument may need new evidence.","zh":"如果標準支持理據薄弱，整個論點可能需要新證據。"},{"en":"This phrase helps identify the common reasoning behind an opinion.","zh":"這個短語有助指出某觀點背後常見的推理。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":7},{"front":"innate gender differences","meaning":"天生的性別差異","examples":[{"en":"Supporters often claim that innate gender differences affect learning.","zh":"支持者常聲稱天生的性別差異會影響學習。"},{"en":"Innate gender differences are differences between males and females that people believe are natural from birth.","zh":"innate gender differences 指人們認為男性和女性與生俱來的差異。"},{"en":"Some people claim innate gender differences explain why boys and girls choose different subjects.","zh":"有些人聲稱天生的性別差異解釋了為何男生和女生選擇不同科目。"},{"en":"Claims about innate gender differences can be harmful if they turn into stereotypes.","zh":"關於天生性別差異的說法，如果變成定型觀念，就可能有害。"},{"en":"Such claims need strong evidence because culture and experience also shape behaviour.","zh":"這類說法需要有力證據，因為文化和經驗也會塑造行為。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":8},{"front":"the manner in which","meaning":"……的方式","examples":[{"en":"They discuss the manner in which boys and girls learn.","zh":"他們討論男生和女生學習的方式。"},{"en":"The manner in which means the way in which something happens or is done.","zh":"the manner in which 意思是某事發生或被完成的方式。"},{"en":"The manner in which a teacher gives feedback can affect a student’s confidence.","zh":"老師給予回饋的方式可以影響學生自信。"},{"en":"If the manner in which rules are enforced feels unfair, students may resist them.","zh":"如果執行規則的方式令人覺得不公平，學生可能會抗拒。"},{"en":"This phrase is formal and useful in academic writing.","zh":"這個短語較正式，適合學術寫作使用。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":8},{"front":"educational settings","meaning":"教育環境","examples":[{"en":"Boys and girls may behave differently in educational settings.","zh":"男生和女生在教育環境中可能表現不同。"},{"en":"Educational settings are places or situations where learning happens, such as schools, classrooms, or training centres.","zh":"educational settings 是學習發生的地方或情境，例如學校、課室或培訓中心。"},{"en":"A quiet library and a noisy workshop are very different educational settings.","zh":"安靜圖書館和嘈雜工作坊是非常不同的教育環境。"},{"en":"Educational settings can affect whether students feel safe, active, or embarrassed.","zh":"教育環境可以影響學生是否感到安全、主動或尷尬。"},{"en":"Good teachers adjust their methods to suit different educational settings.","zh":"好老師會調整方法以配合不同教育環境。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":8},{"front":"allow someone to be taught","meaning":"讓某人接受……方式的教學","examples":[{"en":"Separation allows boys to be taught in a so-called male way.","zh":"分隔讓男生接受所謂男性方式的教學。"},{"en":"To allow someone to be taught means to make it possible for a person to receive teaching in a certain way.","zh":"allow someone to be taught 意思是讓某人能以某種方式接受教學。"},{"en":"Online lessons allow sick students to be taught from home.","zh":"網上課堂讓生病學生可以在家接受教學。"},{"en":"Small classes allow students to be taught with more individual attention.","zh":"小班教學讓學生能接受更多個別關注的教學。"},{"en":"This phrase focuses on what a system makes possible for learners.","zh":"這個短語集中於制度令學習者能夠得到甚麼。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":8},{"front":"in accordance with","meaning":"按照；符合","examples":[{"en":"Some claim boys should be taught in accordance with a male developmental path.","zh":"有些人聲稱男生應按照男性發展路徑接受教學。"},{"en":"In accordance with means according to or in a way that matches something.","zh":"in accordance with 意思是根據某事，或以符合某事的方式。"},{"en":"Medicine should be taken in accordance with the doctor’s instructions.","zh":"藥物應按照醫生指示服用。"},{"en":"Schools must act in accordance with safety rules during emergencies.","zh":"學校在緊急情況中必須按照安全規則行事。"},{"en":"This phrase is formal and often used for rules, plans, or principles.","zh":"這個短語較正式，常用於規則、計劃或原則。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":8},{"front":"developmental path","meaning":"發展路徑","examples":[{"en":"Supporters argue that boys and girls follow different developmental paths.","zh":"支持者主張男生和女生遵循不同發展路徑。"},{"en":"A developmental path is the way a person grows, changes, and gains abilities over time.","zh":"developmental path 是一個人隨時間成長、改變和獲得能力的方式。"},{"en":"Children may follow different developmental paths in language, confidence, and social skills.","zh":"孩子在語言、自信和社交技巧方面可能遵循不同發展路徑。"},{"en":"If teachers misunderstand a child’s developmental path, they may expect too much too early.","zh":"如果老師誤解孩子的發展路徑，可能太早期望過高。"},{"en":"A developmental path is not fixed; support and environment can change it.","zh":"發展路徑不是固定的；支援和環境可以改變它。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":8},{"front":"such claims","meaning":"這類說法","examples":[{"en":"Such claims demand hard evidence.","zh":"這類說法需要確鑿證據。"},{"en":"Such claims means claims of this kind or the claims just mentioned.","zh":"such claims 指這種說法，或剛才提到的說法。"},{"en":"Such claims about health should be tested before people believe them.","zh":"這類關於健康的說法應在被相信前受到測試。"},{"en":"If such claims spread online without evidence, they can mislead parents and students.","zh":"如果這類說法在網上沒有證據地傳播，就可能誤導家長和學生。"},{"en":"The phrase helps refer back to earlier arguments without repeating them.","zh":"這個短語可以指回前面的論點，而不用重複它們。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":8},{"front":"demand hard evidence","meaning":"需要確鑿證據","examples":[{"en":"Claims about gender differences demand hard evidence.","zh":"關於性別差異的說法需要確鑿證據。"},{"en":"To demand hard evidence means to require strong, reliable proof before accepting a claim.","zh":"demand hard evidence 意思是在接受某說法前，需要有力而可靠的證明。"},{"en":"A claim that a medicine cures disease should demand hard evidence.","zh":"聲稱某藥能治病，就需要確鑿證據。"},{"en":"Serious school reforms demand hard evidence because they affect many children.","zh":"嚴肅的學校改革需要確鑿證據，因為它們影響許多孩子。"},{"en":"This phrase reminds readers that confident opinions are not enough.","zh":"這個短語提醒讀者，自信的意見並不足夠。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":8},{"front":"difficult to come by","meaning":"難以獲得","examples":[{"en":"Reliable evidence is difficult to come by.","zh":"可靠證據難以獲得。"},{"en":"Difficult to come by means hard to find or obtain.","zh":"difficult to come by 意思是難以找到或得到。"},{"en":"Affordable housing is difficult to come by in many large cities.","zh":"在許多大城市，負擔得起的住房難以獲得。"},{"en":"Reliable data may be difficult to come by if schools measure results in different ways.","zh":"如果學校用不同方式衡量結果，可靠數據可能難以獲得。"},{"en":"When something is difficult to come by, people should be careful before making strong claims.","zh":"當某事難以獲得時，人們在提出強烈說法前應更謹慎。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":8},{"front":"notoriously unreliable","meaning":"眾所周知地不可靠","examples":[{"en":"Statistics in this area are notoriously unreliable.","zh":"這個範疇的統計數字眾所周知地不可靠。"},{"en":"Notoriously unreliable means widely known for not being trustworthy.","zh":"notoriously unreliable 意思是以不可信而廣為人知。"},{"en":"Online reviews can be notoriously unreliable if companies pay people to write them.","zh":"如果公司付錢叫人寫評論，網上評價可能眾所周知地不可靠。"},{"en":"If attendance records are notoriously unreliable, they cannot prove student behaviour clearly.","zh":"如果出席紀錄眾所周知地不可靠，它就不能清楚證明學生行為。"},{"en":"The word notoriously suggests the problem is well known, not just occasional.","zh":"notoriously 暗示問題廣為人知，而不只是偶爾發生。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":8},{"front":"subject to varying interpretations","meaning":"可作不同詮釋","examples":[{"en":"Statistics are subject to varying interpretations.","zh":"統計數字可作不同詮釋。"},{"en":"Subject to varying interpretations means people can understand or explain the same thing in different ways.","zh":"subject to varying interpretations 意思是同一件事可被人以不同方式理解或解釋。"},{"en":"A student’s silence may be subject to varying interpretations: shyness, boredom, or careful thinking.","zh":"學生的沉默可作不同詮釋：害羞、沉悶或仔細思考。"},{"en":"When data are subject to varying interpretations, writers should explain their reasoning clearly.","zh":"當數據可作不同詮釋時，作者應清楚解釋推理。"},{"en":"This phrase is useful when evidence is not simple or final.","zh":"這個短語適合用於證據並不簡單或並非定論的情況。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":8},{"front":"key factors","meaning":"關鍵因素","examples":[{"en":"The key factors behind superior performance may not be gender separation.","zh":"較佳表現背後的關鍵因素可能不是性別分隔。"},{"en":"Key factors are the most important causes or influences in a situation.","zh":"key factors 是一個情況中最重要的原因或影響。"},{"en":"Sleep, practice, and feedback are key factors in language improvement.","zh":"睡眠、練習和回饋是語言進步的關鍵因素。"},{"en":"If key factors are ignored, people may blame the wrong cause.","zh":"如果關鍵因素被忽視，人們可能怪錯原因。"},{"en":"Identifying key factors helps turn a confusing problem into a clearer explanation.","zh":"找出關鍵因素有助把混亂問題變成更清楚的解釋。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":9},{"front":"lead to superior performance","meaning":"帶來較佳表現","examples":[{"en":"Better teachers and resources may lead to superior performance.","zh":"更好的教師和資源可能帶來較佳表現。"},{"en":"To lead to superior performance means to cause better results or higher achievement.","zh":"lead to superior performance 意思是造成更好結果或更高成就。"},{"en":"Regular feedback can lead to superior performance because students know what to improve.","zh":"定期回饋可以帶來較佳表現，因為學生知道要改善甚麼。"},{"en":"Extra resources may lead to superior performance, but only if students use them well.","zh":"額外資源可能帶來較佳表現，但前提是學生善用它們。"},{"en":"We should not assume one factor alone leads to superior performance.","zh":"我們不應假設單一因素就能帶來較佳表現。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":9},{"front":"superior performance","meaning":"較佳表現","examples":[{"en":"Single-gender schools often show superior performance for reasons unrelated to gender.","zh":"單一性別學校常因與性別無關的原因顯示較佳表現。"},{"en":"Superior performance means better results than others in the same area.","zh":"superior performance 指在同一範疇中比其他人更好的結果。"},{"en":"A student may show superior performance after receiving strong support at home and school.","zh":"學生在家庭和學校得到強力支援後，可能表現較佳。"},{"en":"Superior performance can come from better preparation, not necessarily natural ability.","zh":"較佳表現可以來自更好準備，而不一定是天生能力。"},{"en":"Before praising superior performance, we should ask what advantages helped produce it.","zh":"在稱讚較佳表現前，我們應問是哪些優勢幫助產生它。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":9},{"front":"higher quality of the teachers","meaning":"教師質素較高","examples":[{"en":"The higher quality of the teachers may explain better results.","zh":"教師質素較高可能解釋較好的結果。"},{"en":"Higher quality of the teachers means teachers are better trained, more skilled, or more effective.","zh":"higher quality of the teachers 指教師受訓更好、技能更強或教學更有效。"},{"en":"A school with higher quality of the teachers may give clearer explanations and better feedback.","zh":"教師質素較高的學校，可能提供更清楚解釋和更好回饋。"},{"en":"Higher teacher quality can raise results even without changing the school type.","zh":"即使不改變學校類型，較高教師質素也可以提升成績。"},{"en":"When comparing schools, teacher quality must be considered before crediting one policy.","zh":"比較學校時，在把成果歸功於某政策前，必須考慮教師質素。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":9},{"front":"better resources at hand","meaning":"手上有更好的資源","examples":[{"en":"Students may benefit from better resources at hand.","zh":"學生可能因手上有更好的資源而受益。"},{"en":"Better resources at hand means better materials, tools, or support are easily available.","zh":"better resources at hand 指更好的材料、工具或支援容易取得。"},{"en":"A student with good books and internet access has better resources at hand.","zh":"有好書和網絡的學生，就是手上有更好的資源。"},{"en":"Better resources at hand can improve learning because students can practise and check answers more easily.","zh":"手上有更好的資源可以改善學習，因為學生更容易練習和查答案。"},{"en":"Results may reflect better resources at hand rather than the teaching model itself.","zh":"成績可能反映手上有更好的資源，而不是教學模式本身。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":9},{"front":"motivated students","meaning":"有動力的學生","examples":[{"en":"Single-gender schools often attract more motivated students.","zh":"單一性別學校常吸引更有動力的學生。"},{"en":"Motivated students are students who have strong reasons and willingness to learn.","zh":"motivated students 是有強烈理由和意願去學習的學生。"},{"en":"Motivated students may ask questions, review mistakes, and continue practising after class.","zh":"有動力的學生可能會提問、檢討錯誤，並在課後繼續練習。"},{"en":"A class with motivated students often moves faster because learners take responsibility.","zh":"有動力學生多的班級通常進度較快，因為學習者會承擔責任。"},{"en":"Motivation can come from goals, encouragement, interest, or family expectations.","zh":"動力可以來自目標、鼓勵、興趣或家庭期望。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":9},{"front":"privileged backgrounds","meaning":"優越背景","examples":[{"en":"Many students at prestigious schools come from privileged backgrounds.","zh":"許多名牌學校的學生來自優越背景。"},{"en":"Privileged backgrounds are family or social situations with advantages such as money, education, or connections.","zh":"privileged backgrounds 是擁有金錢、教育或人脈等優勢的家庭或社會背景。"},{"en":"Students from privileged backgrounds may have private tutors, quiet study spaces, and supportive parents.","zh":"來自優越背景的學生可能有私人補習、安靜學習空間和支持他們的父母。"},{"en":"Privileged backgrounds can make school results look better than the school effect alone.","zh":"優越背景可能令學校成績看起來比學校本身的效果更好。"},{"en":"Recognising privilege helps people compare educational results more fairly.","zh":"認識特權有助人們更公平地比較教育成果。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":9},{"front":"prestigious","meaning":"有聲望的；名牌的","examples":[{"en":"Single-gender schools are often among the most prestigious in society.","zh":"單一性別學校常是社會中最有聲望的學校之一。"},{"en":"Prestigious means respected and admired because of high status, history, or success.","zh":"prestigious 指因地位、歷史或成功而受到尊重和仰慕。"},{"en":"A prestigious university may attract students because employers recognise its name.","zh":"有聲望的大學可能因僱主認得其名稱而吸引學生。"},{"en":"Prestigious schools often receive more attention, money, and applications.","zh":"名牌學校通常獲得更多關注、資金和申請。"},{"en":"Prestigious does not always mean best for every individual student.","zh":"prestigious 不一定代表最適合每一個學生。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":9},{"front":"demand the highest entry marks","meaning":"要求最高入學成績","examples":[{"en":"Prestigious schools often demand the highest entry marks from new students.","zh":"名牌學校通常要求新生達到最高入學成績。"},{"en":"To demand the highest entry marks means to require very high scores before admitting students.","zh":"demand the highest entry marks 意思是在取錄學生前要求非常高的分數。"},{"en":"A selective programme may demand the highest entry marks because many students apply.","zh":"因為很多學生申請，精英課程可能要求最高入學成績。"},{"en":"If a school demands the highest entry marks, its students may already be strong before teaching begins.","zh":"如果學校要求最高入學成績，學生在教學開始前可能已經很強。"},{"en":"High entry marks can make later school results difficult to interpret.","zh":"高入學成績可能令之後的學校成果難以解讀。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":9},{"front":"entry marks","meaning":"入學成績","examples":[{"en":"Entry marks can affect which students enter a school.","zh":"入學成績可以影響哪些學生進入一間學校。"},{"en":"Entry marks are the scores students need or have when applying to enter a school or programme.","zh":"entry marks 是學生申請進入學校或課程時所需或擁有的分數。"},{"en":"A student may miss a course if their entry marks are just below the requirement.","zh":"如果學生的入學成績剛低於要求，可能無法入讀某課程。"},{"en":"High entry marks can create a group of students who were already academically strong.","zh":"高入學成績可以形成一群本來學業已很強的學生。"},{"en":"Entry marks are useful for selection, but they do not measure every kind of ability.","zh":"入學成績有助選拔，但不能衡量每一種能力。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":9},{"front":"in turn","meaning":"反過來；繼而","examples":[{"en":"Students at prestigious schools, in turn, receive more respect from society.","zh":"名牌學校的學生繼而從社會獲得更多尊重。"},{"en":"In turn means as a result of the previous thing, or in the next step of a chain.","zh":"in turn 意思是作為前一件事的結果，或在連鎖反應中的下一步。"},{"en":"Better sleep improves attention, which in turn helps students learn faster.","zh":"更好睡眠改善注意力，繼而幫助學生學得更快。"},{"en":"Good public transport reduces car use, which in turn lowers pollution.","zh":"良好公共交通減少私家車使用，繼而降低污染。"},{"en":"This phrase shows a cause-and-effect chain.","zh":"這個短語用來顯示因果連鎖。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":9},{"front":"receive more deference and respect","meaning":"獲得更多敬重和尊重","examples":[{"en":"Students from prestigious schools often receive more deference and respect.","zh":"來自名牌學校的學生常獲得更多敬重和尊重。"},{"en":"To receive more deference and respect means to be treated with more politeness, honour, or social approval.","zh":"receive more deference and respect 意思是受到更多禮貌、敬意或社會認可。"},{"en":"A famous doctor may receive more deference and respect when speaking about health.","zh":"著名醫生談論健康時，可能獲得更多敬重和尊重。"},{"en":"If people receive more respect because of school name, others without that label may be unfairly ignored.","zh":"如果人們因校名而獲得更多尊重，沒有該標籤的人可能被不公平地忽視。"},{"en":"Deference can influence how people judge someone’s ability before seeing their work.","zh":"敬重會在人們看到某人的作品前，已影響他們對其能力的判斷。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":10},{"front":"deference","meaning":"尊重；敬意","examples":[{"en":"Prestigious school students may receive deference from society.","zh":"名牌學校學生可能從社會獲得敬意。"},{"en":"Deference is polite respect shown to someone because of their age, position, knowledge, or status.","zh":"deference 是因某人的年齡、職位、知識或地位而表現出的禮貌尊重。"},{"en":"Young staff may show deference to an experienced manager during a meeting.","zh":"年輕員工在會議中可能對有經驗的經理表示敬意。"},{"en":"Too much deference can stop people from questioning bad decisions.","zh":"過多敬意可能令人不敢質疑錯誤決定。"},{"en":"Deference is about respect, but it can become unfair if status matters more than truth.","zh":"deference 關乎尊重，但如果地位比真相更重要，它可能變得不公平。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":10},{"front":"be taken into account","meaning":"被考慮在內","examples":[{"en":"When these factors are taken into account, the results look less convincing.","zh":"當這些因素被考慮在內時，結果看起來較不令人信服。"},{"en":"To be taken into account means to be considered when making a judgement or decision.","zh":"be taken into account 意思是在作出判斷或決定時被考慮。"},{"en":"A student’s health problems should be taken into account when judging attendance.","zh":"評估出席率時，學生的健康問題應被考慮在內。"},{"en":"If family income is not taken into account, school comparisons may be unfair.","zh":"如果家庭收入沒有被考慮在內，學校比較可能不公平。"},{"en":"Taking more factors into account often makes an argument more accurate.","zh":"把更多因素考慮在內，通常會令論點更準確。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":10},{"front":"large-scale studies","meaning":"大型研究","examples":[{"en":"Large-scale studies do not support claims of superior results.","zh":"大型研究不支持較佳結果的說法。"},{"en":"Large-scale studies are research projects that include many people, schools, cases, or data points.","zh":"large-scale studies 是包括許多人、學校、案例或數據點的研究項目。"},{"en":"A large-scale study of reading habits may survey thousands of students across many districts.","zh":"一項關於閱讀習慣的大型研究，可能調查多個地區數千名學生。"},{"en":"Large-scale studies can reduce the risk of relying on one unusual case.","zh":"大型研究可以降低依賴單一異常案例的風險。"},{"en":"Large-scale studies are useful, but their methods still need careful checking.","zh":"大型研究有用，但其方法仍需仔細檢查。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":10},{"front":"support claims of","meaning":"支持……的說法","examples":[{"en":"The latest studies do not support claims of persistent gender differences.","zh":"最新研究不支持持久性別差異的說法。"},{"en":"To support claims of something means to provide evidence that makes those claims seem true.","zh":"support claims of something 意思是提供證據，使這些說法看似真實。"},{"en":"Test results may support claims of improvement if students do better over time.","zh":"如果學生隨時間表現更好，測驗結果可能支持有進步的說法。"},{"en":"A few personal stories do not strongly support claims of a general pattern.","zh":"少數個人故事不能有力支持一般模式的說法。"},{"en":"Evidence should be strong before it is used to support claims of major differences.","zh":"在用證據支持重大差異的說法前，證據應足夠有力。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":10},{"front":"latest findings","meaning":"最新研究結果","examples":[{"en":"The latest findings of neuroscientists challenge common beliefs.","zh":"神經科學家的最新研究結果挑戰了常見信念。"},{"en":"Latest findings are the newest results or discoveries from research.","zh":"latest findings 指研究中最新的結果或發現。"},{"en":"The latest findings on sleep show why late-night phone use can harm students.","zh":"關於睡眠的最新研究結果顯示深夜使用手機為何會傷害學生。"},{"en":"Latest findings can change public opinion when they challenge old assumptions.","zh":"當最新研究結果挑戰舊假設時，可能改變公眾意見。"},{"en":"Latest findings should be checked against earlier research before people overreact.","zh":"人們在過度反應前，應把最新研究結果與早前研究比較。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":10},{"front":"neuroscientists","meaning":"神經科學家","examples":[{"en":"Neuroscientists do not support claims of persistent gender differences.","zh":"神經科學家不支持持久性別差異的說法。"},{"en":"Neuroscientists are scientists who study the brain and nervous system.","zh":"neuroscientists 是研究大腦和神經系統的科學家。"},{"en":"Neuroscientists may study how memory changes when people sleep well or badly.","zh":"神經科學家可能研究睡眠好壞如何改變記憶。"},{"en":"When neuroscientists examine learning, they look for evidence in the brain and behaviour.","zh":"當神經科學家研究學習時，他們會在大腦和行為中尋找證據。"},{"en":"Neuroscientists can inform education debates, but schools must also consider social factors.","zh":"神經科學家可以為教育爭論提供資訊，但學校也必須考慮社會因素。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":10},{"front":"persistent gender differences","meaning":"持久的性別差異","examples":[{"en":"The latest findings do not support claims of persistent gender differences.","zh":"最新研究結果不支持持久性別差異的說法。"},{"en":"Persistent gender differences are differences between genders that continue over time and appear stable.","zh":"persistent gender differences 指性別之間隨時間持續並看似穩定的差異。"},{"en":"Some people wrongly assume persistent gender differences explain every classroom behaviour.","zh":"有些人錯誤地假設持久性別差異解釋了每種課堂行為。"},{"en":"Claims of persistent gender differences can limit students if they suggest fixed abilities.","zh":"如果持久性別差異的說法暗示能力固定，可能限制學生。"},{"en":"Researchers must separate real persistent differences from habits shaped by culture.","zh":"研究者必須把真正持久差異與文化塑造的習慣分開。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":10},{"front":"be accused of","meaning":"被指責","examples":[{"en":"Some supporters are accused of emphasising favourable data.","zh":"有些支持者被指責強調有利數據。"},{"en":"To be accused of something means to be blamed or said to have done something wrong.","zh":"be accused of something 意思是被責怪或被指做了錯事。"},{"en":"A company may be accused of hiding costs if prices are unclear.","zh":"如果價格不清楚，公司可能被指責隱藏成本。"},{"en":"If researchers select only helpful results, they may be accused of bias.","zh":"如果研究者只選擇有利結果，他們可能被指責有偏見。"},{"en":"Being accused of something does not prove guilt, but it raises a serious question.","zh":"被指責某事不代表罪名成立，但會提出嚴重問題。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":10},{"front":"favourable data","meaning":"有利數據","examples":[{"en":"Critics say some people emphasise favourable data.","zh":"批評者說有些人強調有利數據。"},{"en":"Favourable data are information or results that support a person’s view or desired conclusion.","zh":"favourable data 是支持某人觀點或期望結論的資訊或結果。"},{"en":"A school may highlight favourable data, such as high exam scores, while ignoring student stress.","zh":"學校可能突出高考試成績等有利數據，同時忽視學生壓力。"},{"en":"Using only favourable data can make an argument look stronger than it really is.","zh":"只使用有利數據會令論點看起來比實際更強。"},{"en":"Fair research considers both favourable and unfavourable data.","zh":"公平研究會同時考慮有利和不利數據。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":10},{"front":"draw conclusions based on","meaning":"根據……得出結論","examples":[{"en":"They are accused of drawing conclusions based on anecdotal evidence.","zh":"他們被指責根據軼事證據得出結論。"},{"en":"To draw conclusions based on something means to form a judgement using that evidence or information.","zh":"draw conclusions based on something 意思是用某些證據或資訊形成判斷。"},{"en":"Teachers should not draw conclusions based on one quiet lesson alone.","zh":"老師不應只根據一堂沉默的課得出結論。"},{"en":"If people draw conclusions based on rumours, they may treat others unfairly.","zh":"如果人們根據謠言得出結論，可能不公平地對待他人。"},{"en":"Strong conclusions should be based on wide and reliable evidence.","zh":"強而有力的結論應基於廣泛而可靠的證據。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":10},{"front":"anecdotal evidence","meaning":"軼事證據；個別經驗證據","examples":[{"en":"Anecdotal evidence is weaker than large-scale research.","zh":"軼事證據比大型研究弱。"},{"en":"Anecdotal evidence is evidence based on personal stories rather than systematic research.","zh":"anecdotal evidence 是基於個人故事而不是系統研究的證據。"},{"en":"One parent’s success story is anecdotal evidence, not proof that a method works for everyone.","zh":"一位家長的成功故事是軼事證據，並不能證明某方法適合所有人。"},{"en":"Anecdotal evidence can suggest a question, but it should not settle a debate.","zh":"軼事證據可以提出問題，但不應終結爭論。"},{"en":"Researchers use wider data to test whether anecdotal evidence reflects a general pattern.","zh":"研究者使用更廣泛數據來測試軼事證據是否反映一般模式。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":11},{"front":"gender stereotyping","meaning":"性別定型","examples":[{"en":"Some claims are based more on gender stereotyping than science.","zh":"有些說法更多基於性別定型，而不是科學。"},{"en":"Gender stereotyping means making fixed assumptions about people because they are male or female.","zh":"gender stereotyping 是因某人是男性或女性而作出固定假設。"},{"en":"Saying boys are always better at maths is an example of gender stereotyping.","zh":"說男生一定較擅長數學，就是性別定型的一個例子。"},{"en":"Gender stereotyping can stop students from trying subjects they might enjoy.","zh":"性別定型可能阻止學生嘗試他們可能喜歡的科目。"},{"en":"Reducing gender stereotyping helps children see more choices for their future.","zh":"減少性別定型有助孩子看見更多未來選擇。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":11},{"front":"advocates of","meaning":"……的倡議者","examples":[{"en":"Advocates of single-sex education put forward other arguments.","zh":"單性別教育的倡議者提出其他論點。"},{"en":"Advocates of something are people who publicly support and defend it.","zh":"advocates of something 是公開支持並為某事辯護的人。"},{"en":"Advocates of cycling may ask the government to build safer bike lanes.","zh":"單車出行的倡議者可能要求政府建造更安全的單車徑。"},{"en":"Advocates often present benefits, answer criticism, and try to persuade others.","zh":"倡議者通常會提出好處、回應批評並嘗試說服他人。"},{"en":"Advocate is more active than supporter because it suggests speaking or acting for a cause.","zh":"advocate 比 supporter 更主動，因為它暗示為某理念發聲或行動。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":11},{"front":"put forward arguments","meaning":"提出論點","examples":[{"en":"Advocates put forward arguments in favour of single-sex education.","zh":"倡議者提出支持單性別教育的論點。"},{"en":"To put forward arguments means to present reasons for people to consider.","zh":"put forward arguments 意思是提出理由讓人考慮。"},{"en":"Students put forward arguments when they explain why the school library should stay open later.","zh":"學生解釋學校圖書館為何應延長開放時間時，就是在提出論點。"},{"en":"Strong arguments are easier to accept when they include examples and evidence.","zh":"當論點包含例子和證據時，就較容易被接受。"},{"en":"Putting forward arguments is different from simply stating an opinion.","zh":"提出論點不同於只是陳述意見。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":11},{"front":"in its favour","meaning":"支持它","examples":[{"en":"Supporters put forward arguments in its favour.","zh":"支持者提出支持它的論點。"},{"en":"In its favour means supporting it or showing why it may be good.","zh":"in its favour 意思是支持它，或顯示它為何可能是好的。"},{"en":"A city may build a park if residents present strong reasons in its favour.","zh":"如果居民提出支持建公園的有力理由，城市可能會興建公園。"},{"en":"Evidence in its favour can make a policy more acceptable to the public.","zh":"支持它的證據可以令一項政策更容易被公眾接受。"},{"en":"When writing essays, balance arguments in its favour with arguments against it.","zh":"寫文章時，應把支持它的論點與反對它的論點作平衡。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":11},{"front":"free from the worry of","meaning":"免受……的憂慮","examples":[{"en":"Girls may be free from the worry of sexual harassment.","zh":"女生可能免受性騷擾的憂慮。"},{"en":"Free from the worry of something means not having to fear or be anxious about it.","zh":"free from the worry of something 意思是不必害怕或擔心某事。"},{"en":"Students learn better when they are free from the worry of being laughed at.","zh":"當學生免受被嘲笑的憂慮時，他們會學得更好。"},{"en":"Clear rules can make workers free from the worry of unfair punishment.","zh":"清楚規則可以令員工免受不公平懲罰的憂慮。"},{"en":"Being free from worry can create space for confidence and learning.","zh":"免受憂慮可以為自信和學習創造空間。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":11},{"front":"sexual harassment","meaning":"性騷擾","examples":[{"en":"Some supporters argue that girls are safer from sexual harassment in single-sex schools.","zh":"有些支持者主張女生在單性別學校較能免受性騷擾。"},{"en":"Sexual harassment means unwanted sexual comments, attention, pressure, or behaviour that makes someone feel unsafe or uncomfortable.","zh":"sexual harassment 指不受歡迎的性相關言語、注意、壓力或行為，令某人感到不安全或不舒服。"},{"en":"Schools need clear rules so students know sexual harassment is never acceptable.","zh":"學校需要清楚規則，讓學生知道性騷擾永遠不可接受。"},{"en":"Sexual harassment can harm confidence, attendance, and mental health.","zh":"性騷擾可以傷害自信、出席率和心理健康。"},{"en":"Preventing sexual harassment requires education, reporting systems, and serious consequences.","zh":"防止性騷擾需要教育、舉報制度和嚴肅後果。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":11},{"front":"originate from","meaning":"源自","examples":[{"en":"Some negative behaviour may originate from the presence of boys.","zh":"某些負面行為可能源自男生的存在。"},{"en":"Originate from means begin from, come from, or have a source in something.","zh":"originate from 意思是起源於、來自或以某事作為來源。"},{"en":"A misunderstanding may originate from one unclear message.","zh":"誤會可能源自一則不清楚的訊息。"},{"en":"If stress originates from homework overload, reducing one assignment may help.","zh":"如果壓力源自功課過多，減少一份作業可能有幫助。"},{"en":"Finding where a problem originates from helps people choose the right solution.","zh":"找出問題源自何處，有助人們選擇正確解決方法。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":11},{"front":"the presence of","meaning":"……的存在","examples":[{"en":"Some girls may feel pressure because of the presence of boys.","zh":"有些女生可能因男生的存在而感到壓力。"},{"en":"The presence of someone or something means that they are there in a place or situation.","zh":"the presence of someone or something 指某人或某物在某個地方或情況中存在。"},{"en":"The presence of a teacher may make students behave more carefully.","zh":"老師的存在可能令學生行為更謹慎。"},{"en":"The presence of cameras can reduce crime but may also raise privacy concerns.","zh":"攝影機的存在可以減少犯罪，但也可能引起私隱憂慮。"},{"en":"This phrase focuses on the effect created simply by someone or something being there.","zh":"這個短語集中於某人或某物單純在場造成的影響。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":11},{"front":"develop greater self-confidence","meaning":"建立更大自信","examples":[{"en":"Girls are said to develop greater self-confidence in single-sex schools.","zh":"據說女生在單性別學校能建立更大自信。"},{"en":"To develop greater self-confidence means to become more willing to trust one’s own ability.","zh":"develop greater self-confidence 意思是更願意相信自己的能力。"},{"en":"Students may develop greater self-confidence after speaking successfully in front of a class.","zh":"學生在全班面前成功發言後，可能建立更大自信。"},{"en":"Supportive feedback can help shy learners develop greater self-confidence over time.","zh":"支持性的回饋可以幫助害羞學習者逐漸建立更大自信。"},{"en":"Greater self-confidence does not mean arrogance; it means feeling able to try.","zh":"更大自信不代表自大；它代表覺得自己能夠嘗試。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":11},{"front":"a willingness to","meaning":"願意……","examples":[{"en":"Girls may develop a willingness to study engineering and mathematics.","zh":"女生可能建立願意修讀工程和數學的意願。"},{"en":"A willingness to do something is a readiness or openness to do it.","zh":"a willingness to do something 指準備好或開放地去做某事。"},{"en":"A student shows a willingness to improve when they ask for feedback.","zh":"當學生主動尋求回饋時，就是表現出願意改善。"},{"en":"Encouragement can create a willingness to try difficult subjects.","zh":"鼓勵可以令人願意嘗試困難科目。"},{"en":"Willingness matters because people rarely improve in areas they refuse to enter.","zh":"意願很重要，因為人們很少會在拒絕接觸的範疇中進步。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":11},{"front":"the exclusive province of","meaning":"……的專屬領域","examples":[{"en":"Engineering was once seen as the exclusive province of males.","zh":"工程曾被視為男性的專屬領域。"},{"en":"The exclusive province of a group means an area believed to belong only to that group.","zh":"the exclusive province of a group 指被認為只屬於某群體的範疇。"},{"en":"Cooking should not be treated as the exclusive province of women.","zh":"烹飪不應被視為女性的專屬領域。"},{"en":"If science is seen as the exclusive province of top students, others may feel shut out.","zh":"如果科學被視為尖子學生的專屬領域，其他人可能感到被排除。"},{"en":"This phrase often criticises unfair ownership of a field or activity.","zh":"這個短語常用來批評某個領域或活動被不公平地佔有。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":12},{"front":"conversely","meaning":"相反地","examples":[{"en":"Conversely, boys may feel freer to show interest in the arts.","zh":"相反地，男生可能更自由地表現出對藝術的興趣。"},{"en":"Conversely means in the opposite way or from the other side of the argument.","zh":"conversely 意思是以相反方式，或從論點的另一面來看。"},{"en":"Some students enjoy group work; conversely, others learn better alone.","zh":"有些學生喜歡小組學習；相反地，其他學生獨自學習較好。"},{"en":"A policy may help older people; conversely, it may create costs for younger workers.","zh":"一項政策可能幫助長者；相反地，它可能為年輕工人帶來成本。"},{"en":"Use conversely when you want to present a clear opposite point.","zh":"當你想提出清楚相反觀點時，可以使用 conversely。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":12},{"front":"express a greater interest in","meaning":"表現出更大興趣","examples":[{"en":"Boys may express a greater interest in the arts.","zh":"男生可能表現出對藝術的更大興趣。"},{"en":"To express a greater interest in something means to show stronger curiosity, attention, or desire to take part.","zh":"express a greater interest in something 意思是表現出更強的好奇、關注或參與意願。"},{"en":"Students may express a greater interest in science after doing hands-on experiments.","zh":"學生在做實驗後，可能表現出對科學的更大興趣。"},{"en":"If children see role models, they may express a greater interest in careers they had never considered.","zh":"如果孩子看見榜樣，可能對從未考慮過的職業表現出更大興趣。"},{"en":"Expressing interest is often the first step before deeper learning.","zh":"表現出興趣通常是深入學習前的第一步。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":12},{"front":"without the possible jibe","meaning":"沒有可能出現的嘲笑","examples":[{"en":"Boys may study the arts without the possible jibe that it is a girl’s subject.","zh":"男生可以學習藝術，而沒有「那是女生科目」這種可能出現的嘲笑。"},{"en":"Without the possible jibe means without the risk of being mocked or insulted by a particular comment.","zh":"without the possible jibe 意思是沒有因某句話被嘲弄或侮辱的風險。"},{"en":"A student may join drama club without the possible jibe that serious students should only study.","zh":"學生可以加入戲劇社，而沒有「認真的學生只應讀書」這種可能出現的嘲笑。"},{"en":"Fear of possible jibes can stop young people from trying activities they enjoy.","zh":"害怕可能出現的嘲笑，會阻止年輕人嘗試喜歡的活動。"},{"en":"This phrase shows how teasing can shape choices.","zh":"這個短語顯示取笑如何塑造選擇。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":12},{"front":"a girl’s subject","meaning":"女生科目","examples":[{"en":"Some people wrongly treat the arts as a girl’s subject.","zh":"有些人錯誤地把藝術當成女生科目。"},{"en":"A girl’s subject means a school subject unfairly labelled as suitable mainly for girls.","zh":"a girl’s subject 指被不公平標籤為主要適合女生的學科。"},{"en":"Calling literature a girl’s subject may stop boys from enjoying reading and writing.","zh":"把文學稱為女生科目，可能阻止男生享受閱讀和寫作。"},{"en":"Labelling a subject by gender can limit both boys and girls.","zh":"用性別標籤學科可以限制男生和女生。"},{"en":"A subject should be judged by interest and ability, not by gender stereotypes.","zh":"科目應按興趣和能力判斷，而不是按性別定型。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":12},{"front":"one senses that","meaning":"人們會覺得","examples":[{"en":"One senses that stereotyping could still occur in single-gender settings.","zh":"人們會覺得定型觀念仍可能在單一性別環境中出現。"},{"en":"One senses that means one gets the impression or feeling that something is true.","zh":"one senses that 意思是人們得到某事為真的印象或感覺。"},{"en":"One senses that the class is nervous when no one answers the first question.","zh":"當沒有人回答第一條問題時，人們會覺得全班很緊張。"},{"en":"A reader may sense that an argument is weak when it avoids evidence.","zh":"當一個論點避開證據時，讀者可能會覺得它薄弱。"},{"en":"This phrase is cautious because it presents an impression, not a proven fact.","zh":"這個短語較謹慎，因為它表達的是印象，而不是已證明事實。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":12},{"front":"such stereotyping","meaning":"這種定型觀念","examples":[{"en":"Such stereotyping could equally occur in single-gender settings.","zh":"這種定型觀念同樣可能在單一性別環境中出現。"},{"en":"Such stereotyping means the kind of fixed gender assumption just mentioned.","zh":"such stereotyping 指剛才提到的那種固定性別假設。"},{"en":"Such stereotyping appears when people say boys should not cry or girls should not lead.","zh":"當人們說男生不應哭或女生不應領導時，這種定型觀念就出現了。"},{"en":"Such stereotyping can survive even when boys and girls are placed in separate schools.","zh":"即使男生和女生被分到不同學校，這種定型觀念也可能存在。"},{"en":"The phrase helps connect the present sentence to earlier examples of bias.","zh":"這個短語有助把現在的句子連繫到前面關於偏見的例子。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":12},{"front":"could equally occur","meaning":"同樣可能發生","examples":[{"en":"Stereotyping could equally occur in single-gender schools.","zh":"定型觀念同樣可能在單一性別學校中發生。"},{"en":"Could equally occur means could happen in the other situation too, not only in the first one.","zh":"could equally occur 意思是某事也可能在另一種情況中發生，而不只在第一種情況。"},{"en":"Bullying could equally occur online, not just in the classroom.","zh":"欺凌同樣可能在網上發生，而不只是在課室中。"},{"en":"If pressure could equally occur in both school types, separation alone is not a full solution.","zh":"如果壓力在兩種學校類型中同樣可能發生，單靠分隔並不是完整解決方法。"},{"en":"This phrase prevents readers from blaming only one setting.","zh":"這個短語防止讀者只責怪一種環境。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":12},{"front":"outside of school","meaning":"校外","examples":[{"en":"Society outside of school has a major influence on students.","zh":"校外社會對學生有重大影響。"},{"en":"Outside of school means beyond the classroom or school environment.","zh":"outside of school 意思是在課室或學校環境以外。"},{"en":"Students learn many habits outside of school from family, friends, media, and neighbourhoods.","zh":"學生在校外從家庭、朋友、媒體和社區學到許多習慣。"},{"en":"If stereotypes are strong outside of school, lessons alone may not remove them.","zh":"如果校外的定型觀念很強，單靠課堂未必能消除它們。"},{"en":"Education continues outside of school, even when no teacher is present.","zh":"即使沒有老師在場，教育仍會在校外繼續。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":12},{"front":"related expectations","meaning":"相關期望","examples":[{"en":"Gender roles are shaped by society and its related expectations.","zh":"性別角色由社會及其相關期望塑造。"},{"en":"Related expectations are beliefs about what people should do because of a connected role or situation.","zh":"related expectations 是因某個相關角色或情況而形成的「人應該怎樣做」的信念。"},{"en":"A new employee may face related expectations about being polite, punctual, and careful.","zh":"新員工可能面對關於有禮、準時和謹慎的相關期望。"},{"en":"Gender-related expectations can pressure boys and girls to behave in limited ways.","zh":"與性別相關的期望可能迫使男生和女生以受限方式行事。"},{"en":"Related expectations may feel normal because people hear them repeatedly from childhood.","zh":"相關期望可能感覺正常，因為人們從小反覆聽到它們。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":12},{"front":"have the greatest influence","meaning":"影響最大","examples":[{"en":"The society outside school may have the greatest influence.","zh":"校外社會可能影響最大。"},{"en":"To have the greatest influence means to affect something more strongly than other factors do.","zh":"have the greatest influence 意思是比其他因素更強烈地影響某事。"},{"en":"Parents may have the greatest influence on a child’s early language habits.","zh":"父母可能對孩子早期語言習慣影響最大。"},{"en":"If social media has the greatest influence, school lessons may struggle to change attitudes.","zh":"如果社交媒體影響最大，學校課堂可能難以改變態度。"},{"en":"Finding what has the greatest influence helps people focus their efforts.","zh":"找出甚麼影響最大，有助人們集中努力。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":12},{"front":"among this welter of","meaning":"在這一大堆……之中","examples":[{"en":"Among this welter of conflicting arguments, one certainty remains.","zh":"在這一大堆互相矛盾的論點之中，仍有一個確定事實。"},{"en":"Among this welter of means in the middle of a large, confused mass of things.","zh":"among this welter of 意思是在一大堆混亂事物之中。"},{"en":"Among this welter of online advice, students need one clear study plan.","zh":"在這一大堆網上建議之中，學生需要一個清楚的學習計劃。"},{"en":"A simple fact can be easy to miss among this welter of opinions and data.","zh":"在這一大堆意見和數據之中，一個簡單事實可能很容易被忽略。"},{"en":"This phrase suggests the writer is trying to find clarity inside confusion.","zh":"這個短語暗示作者正嘗試在混亂中找出清晰之處。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":13},{"front":"a welter of","meaning":"大量混亂的……","examples":[{"en":"The debate contains a welter of conflicting arguments.","zh":"這場辯論包含大量混亂而互相矛盾的論點。"},{"en":"A welter of something is a large, confused collection of information, problems, or opinions.","zh":"a welter of something 指大量混雜的資訊、問題或意見。"},{"en":"New students may face a welter of rules, forms, passwords, and deadlines.","zh":"新生可能面對大量混亂的規則、表格、密碼和期限。"},{"en":"A welter of choices can make decision-making harder rather than easier.","zh":"大量混亂的選擇可能令決策更困難，而不是更容易。"},{"en":"This phrase is useful when there are too many mixed details to handle easily.","zh":"當細節太多太雜而不易處理時，這個短語很有用。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":13},{"front":"fall back on","meaning":"依靠；退而求其次依據","examples":[{"en":"We can fall back on one certainty: the real world is co-gendered.","zh":"我們可以依靠一個確定事實：現實世界是男女共存的。"},{"en":"To fall back on something means to rely on it when other ideas are uncertain or fail.","zh":"fall back on something 意思是在其他想法不確定或失敗時依靠某事。"},{"en":"If the internet fails, a teacher can fall back on printed worksheets.","zh":"如果網絡失靈，老師可以退而使用印刷工作紙。"},{"en":"When evidence is confusing, writers may fall back on one clear principle.","zh":"當證據混亂時，作者可能依靠一個清楚原則。"},{"en":"Falling back on something is useful only if that support is reliable.","zh":"依靠某事只有在該支持可靠時才有用。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":13},{"front":"one certainty","meaning":"一個確定事實","examples":[{"en":"One certainty is that the real world is co-gendered.","zh":"一個確定事實是現實世界是男女共存的。"},{"en":"One certainty is one fact that seems clear even when other things are uncertain.","zh":"one certainty 指即使其他事情不確定，仍然清楚的一個事實。"},{"en":"In a difficult exam, one certainty is that careful reading prevents many mistakes.","zh":"在困難考試中，一個確定事實是仔細閱讀可以避免許多錯誤。"},{"en":"When a plan changes often, one certainty may help the team stay focused.","zh":"當計劃經常改變時，一個確定事實可能幫助團隊保持焦點。"},{"en":"This phrase is useful when a writer wants to move from confusion to a firm point.","zh":"這個短語適合用於作者想從混亂轉向堅定觀點時。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":13},{"front":"the real world is co-gendered","meaning":"現實世界是男女共存的","examples":[{"en":"The real world is co-gendered, so students must learn to interact.","zh":"現實世界是男女共存的，所以學生必須學會互動。"},{"en":"The real world is co-gendered means men and women live, work, study, and cooperate together in normal society.","zh":"the real world is co-gendered 意思是男性和女性在正常社會中一起生活、工作、學習和合作。"},{"en":"Most workplaces are co-gendered because people of different genders share tasks and responsibilities.","zh":"大多數工作場所都是男女共存的，因為不同性別的人共享任務和責任。"},{"en":"If school does not prepare students for a co-gendered world, later interaction may feel harder.","zh":"如果學校沒有讓學生為男女共存的世界作準備，日後互動可能更困難。"},{"en":"This idea is often used to support mixed education.","zh":"這個想法常被用來支持男女校教育。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":13},{"front":"misunderstand the other","meaning":"誤解對方","examples":[{"en":"Each gender often misunderstands the other.","zh":"每個性別常常誤解對方。"},{"en":"To misunderstand the other means to wrongly understand people from the other group.","zh":"misunderstand the other 意思是錯誤理解另一個群體的人。"},{"en":"Students may misunderstand the other gender if they rarely work together.","zh":"如果學生很少一起合作，他們可能誤解另一性別。"},{"en":"Misunderstanding the other can create fear, jokes, or unfair assumptions.","zh":"誤解對方可以造成恐懼、玩笑或不公平假設。"},{"en":"Regular respectful interaction can reduce the chance of misunderstanding the other.","zh":"定期而尊重的互動可以減少誤解對方的機會。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":13},{"front":"supporters of co-education","meaning":"男女校教育支持者","examples":[{"en":"Supporters of co-education argue that mixed schooling reduces gender divisions.","zh":"男女校教育支持者主張混合學校教育能減少性別分歧。"},{"en":"Supporters of co-education are people who believe boys and girls should be educated together.","zh":"supporters of co-education 是相信男生和女生應一起受教育的人。"},{"en":"Supporters of co-education may say mixed schools prepare students for university and work.","zh":"男女校教育支持者可能說混合學校讓學生為大學和工作作準備。"},{"en":"If supporters of co-education ignore classroom problems, their argument may sound too idealistic.","zh":"如果男女校教育支持者忽視課堂問題，他們的論點可能聽起來太理想化。"},{"en":"Strong supporters still need evidence, not only good intentions.","zh":"強烈支持者仍需要證據，而不只是好意。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":13},{"front":"co-education","meaning":"男女校教育","examples":[{"en":"Co-education places boys and girls in the same learning environment.","zh":"男女校教育把男生和女生放在同一學習環境中。"},{"en":"Co-education means educating male and female students together in the same school or classroom.","zh":"co-education 是指男女學生在同一學校或課室一起受教育。"},{"en":"Most public schools use co-education because students learn and socialise together.","zh":"大多數公立學校採用男女校教育，因為學生一起學習和社交。"},{"en":"Co-education can create opportunities for cooperation, but it also requires good classroom management.","zh":"男女校教育可以創造合作機會，但也需要良好課室管理。"},{"en":"Co-education reflects the mixed-gender nature of most real communities.","zh":"男女校教育反映大多數真實社區男女共存的性質。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":13},{"front":"positive and co-operative interaction","meaning":"正面而合作的互動","examples":[{"en":"Positive and co-operative interaction can reduce divisions between genders.","zh":"正面而合作的互動可以減少性別之間的分歧。"},{"en":"Positive and co-operative interaction means people work together respectfully and helpfully.","zh":"positive and co-operative interaction 指人們以尊重和有幫助的方式一起合作。"},{"en":"Group projects can create positive and co-operative interaction when roles are clear.","zh":"當角色清楚時，小組項目可以創造正面而合作的互動。"},{"en":"Positive interaction can build trust, while poor interaction can deepen misunderstanding.","zh":"正面互動可以建立信任，而差劣互動可以加深誤解。"},{"en":"Schools should not assume interaction is positive; they must teach students how to cooperate.","zh":"學校不應假設互動一定正面；它們必須教學生如何合作。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":13},{"front":"reduce such divisions","meaning":"減少這類分歧","examples":[{"en":"Co-education may reduce such divisions between boys and girls.","zh":"男女校教育可能減少男生和女生之間的這類分歧。"},{"en":"To reduce such divisions means to make these separations, tensions, or differences less strong.","zh":"reduce such divisions 意思是令這些分隔、緊張或差異減弱。"},{"en":"Mixed sports teams may reduce such divisions by helping students see each other as teammates.","zh":"混合性別運動隊可以透過讓學生視彼此為隊友，減少這類分歧。"},{"en":"Honest discussion can reduce divisions because people understand one another’s fears.","zh":"誠實討論可以減少分歧，因為人們理解彼此的恐懼。"},{"en":"Reducing divisions requires repeated contact, not just one shared activity.","zh":"減少分歧需要重複接觸，而不只是一項共同活動。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":13},{"front":"de-emphasise gender","meaning":"淡化性別的重要性","examples":[{"en":"Co-education may de-emphasise gender as a factor of concern.","zh":"男女校教育可能淡化性別作為關注因素的重要性。"},{"en":"To de-emphasise gender means to make gender seem less important in a situation.","zh":"de-emphasise gender 意思是令性別在某情況中顯得較不重要。"},{"en":"A teacher can de-emphasise gender by giving leadership roles to all students fairly.","zh":"老師可以透過公平分配領導角色給所有學生，來淡化性別的重要性。"},{"en":"When schools de-emphasise gender, students may focus more on interests and abilities.","zh":"當學校淡化性別，學生可能更集中於興趣和能力。"},{"en":"De-emphasising gender does not mean ignoring unfair treatment when it occurs.","zh":"淡化性別不代表在不公平待遇出現時視而不見。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":13},{"front":"a factor of concern","meaning":"受關注的因素","examples":[{"en":"Gender may become less of a factor of concern in co-educational settings.","zh":"在男女校環境中，性別可能較少成為受關注的因素。"},{"en":"A factor of concern is something that people worry about or consider important in a situation.","zh":"a factor of concern 是人們在某情況中擔心或認為重要的因素。"},{"en":"Cost is a factor of concern when families choose private lessons.","zh":"家庭選擇私人課堂時，費用是一個受關注的因素。"},{"en":"Safety becomes a factor of concern when students travel home late.","zh":"當學生很晚回家時，安全就成為受關注的因素。"},{"en":"If gender is no longer a major factor of concern, students may interact more naturally.","zh":"如果性別不再是主要受關注因素，學生可能更自然地互動。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":14},{"front":"in theory","meaning":"理論上","examples":[{"en":"In theory, stereotypes are broken down in co-educational schools.","zh":"理論上，男女校會打破定型觀念。"},{"en":"In theory means according to an idea or plan, though reality may be different.","zh":"in theory 意思是按想法或計劃來說，雖然現實可能不同。"},{"en":"In theory, online learning saves travel time, but students may still feel isolated.","zh":"理論上，網上學習節省交通時間，但學生仍可能感到孤立。"},{"en":"A rule may work in theory but fail when real people ignore it.","zh":"一條規則理論上可行，但在真人不遵守時可能失敗。"},{"en":"Use in theory when you want to separate an ideal from actual practice.","zh":"當你想把理想與實際做法分開時，可以使用 in theory。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":14},{"front":"break down stereotypes","meaning":"打破定型觀念","examples":[{"en":"Co-education may help break down stereotypes.","zh":"男女校教育可能有助打破定型觀念。"},{"en":"To break down stereotypes means to weaken fixed and unfair ideas about groups of people.","zh":"break down stereotypes 意思是削弱對某些群體固定而不公平的看法。"},{"en":"Boys and girls working together in science projects can break down stereotypes about ability.","zh":"男生和女生一起做科學項目，可以打破關於能力的定型觀念。"},{"en":"Stories about different families can break down stereotypes by showing real variety.","zh":"關於不同家庭的故事可以透過展示真實多樣性來打破定型觀念。"},{"en":"Stereotypes are broken down slowly through repeated evidence and contact.","zh":"定型觀念會透過重複證據和接觸慢慢被打破。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":14},{"front":"inclusion is emphasised","meaning":"強調包容","examples":[{"en":"In co-educational settings, inclusion is emphasised.","zh":"在男女校環境中，包容受到強調。"},{"en":"Inclusion is emphasised means people give strong attention to making everyone feel accepted and involved.","zh":"inclusion is emphasised 意思是人們強烈重視讓每個人感到被接納和參與其中。"},{"en":"In a good classroom, inclusion is emphasised when quiet students are invited to contribute safely.","zh":"在良好課室中，當安靜學生被安全地邀請參與時，就是在強調包容。"},{"en":"If inclusion is emphasised, schools may design activities that do not leave anyone out.","zh":"如果強調包容，學校可能設計不排除任何人的活動。"},{"en":"Emphasising inclusion requires action, not just friendly words.","zh":"強調包容需要行動，而不只是友善說話。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":14},{"front":"provide benefits for society as a whole","meaning":"為整個社會帶來好處","examples":[{"en":"Co-education may provide benefits for society as a whole.","zh":"男女校教育可能為整個社會帶來好處。"},{"en":"To provide benefits for society as a whole means to help the wider community, not only individuals.","zh":"provide benefits for society as a whole 意思是幫助更廣泛社群，而不只是幫助個人。"},{"en":"Better public transport can provide benefits for society as a whole by reducing pollution and traffic.","zh":"更好的公共交通可以透過減少污染和交通擠塞，為整個社會帶來好處。"},{"en":"If students learn cooperation early, this may provide benefits for society as a whole later.","zh":"如果學生從小學會合作，日後可能為整個社會帶來好處。"},{"en":"This phrase is useful when moving from personal effects to social effects.","zh":"這個短語適合用於從個人影響轉向社會影響。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":14},{"front":"such sentiments","meaning":"這類看法；這些情感","examples":[{"en":"Such sentiments may sound like self-promotional propaganda.","zh":"這類看法可能聽起來像自我宣傳式說辭。"},{"en":"Such sentiments means feelings, opinions, or views of the kind just mentioned.","zh":"such sentiments 指剛才提到的那類感受、意見或看法。"},{"en":"Such sentiments about teamwork sound positive, but they need real examples.","zh":"這類關於團隊合作的看法聽起來正面，但需要真實例子。"},{"en":"If such sentiments are repeated without evidence, people may treat them as empty slogans.","zh":"如果這類看法沒有證據地反覆出現，人們可能把它們視為空洞口號。"},{"en":"The phrase can sound slightly critical when the writer doubts the sincerity or reality of the views.","zh":"當作者懷疑這些看法的真誠或現實性時，這個短語可帶有輕微批評意味。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":14},{"front":"admittedly","meaning":"誠然","examples":[{"en":"Admittedly, these claims may sound unrealistic.","zh":"誠然，這些說法可能聽起來不切實際。"},{"en":"Admittedly means the writer accepts a point before continuing the argument.","zh":"admittedly 意思是作者先承認一點，再繼續論證。"},{"en":"Admittedly, the plan is expensive, but it may save money in the long term.","zh":"誠然，這個計劃很昂貴，但長遠可能省錢。"},{"en":"Admittedly, online learning is convenient, but not every student can concentrate at home.","zh":"誠然，網上學習很方便，但不是每個學生都能在家集中。"},{"en":"Use admittedly to show fairness before explaining a different or stronger point.","zh":"使用 admittedly 可以先顯示公平，再解釋不同或更強的觀點。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":14},{"front":"retreat into","meaning":"退回到；陷入","examples":[{"en":"These claims may sound as if advocates are retreating into propaganda.","zh":"這些說法可能聽起來像倡議者退回到宣傳說辭。"},{"en":"To retreat into something means to move back into a safer but less honest or less useful position.","zh":"retreat into something 意思是退回到較安全但較不誠實或較無用的位置。"},{"en":"A manager may retreat into excuses when asked about real workplace problems.","zh":"經理被問到真實職場問題時，可能退回到藉口之中。"},{"en":"If a debate becomes difficult, people may retreat into slogans instead of evidence.","zh":"如果辯論變得困難，人們可能退回到口號，而不是證據。"},{"en":"The phrase often criticises avoidance of the real issue.","zh":"這個短語常批評人們迴避真正問題。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":14},{"front":"self-promotional propaganda","meaning":"自我宣傳式說辭","examples":[{"en":"Some claims about co-education sound like self-promotional propaganda.","zh":"有些關於男女校教育的說法聽起來像自我宣傳式說辭。"},{"en":"Self-promotional propaganda is language that mainly praises one’s own idea, group, or system instead of proving it fairly.","zh":"self-promotional propaganda 是主要讚揚自己的想法、群體或制度，而不是公平證明它的語言。"},{"en":"A school brochure becomes self-promotional propaganda if it only boasts and gives no honest details.","zh":"如果學校小冊子只吹噓而沒有誠實細節，它就變成自我宣傳式說辭。"},{"en":"Self-promotional propaganda can make people suspicious because it sounds too perfect.","zh":"自我宣傳式說辭會令人懷疑，因為它聽起來太完美。"},{"en":"Real evidence is stronger than self-promotional propaganda.","zh":"真實證據比自我宣傳式說辭更有力。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":14},{"front":"in other words","meaning":"換句話說","examples":[{"en":"In other words, these statements may be too glib.","zh":"換句話說，這些陳述可能太流於表面。"},{"en":"In other words introduces a simpler or clearer way to say the same idea.","zh":"in other words 用來以較簡單或較清楚的方式重述同一想法。"},{"en":"The class is fully booked; in other words, no more students can join.","zh":"課堂已滿額；換句話說，沒有更多學生可以加入。"},{"en":"If a policy helps only rich families, in other words, it is not truly fair.","zh":"如果一項政策只幫助富裕家庭，換句話說，它並不真正公平。"},{"en":"This phrase is useful when explaining a difficult point again more directly.","zh":"這個短語適合用來把困難觀點再次更直接地解釋。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":14},{"front":"glib and unreal assertions","meaning":"流於表面且不切實際的斷言","examples":[{"en":"The author warns that some claims are glib and unreal assertions.","zh":"作者警告，有些說法是流於表面且不切實際的斷言。"},{"en":"Glib and unreal assertions are claims that sound smooth but are too easy, shallow, or unrealistic.","zh":"glib and unreal assertions 是聽起來順口，但過於簡單、膚淺或不現實的說法。"},{"en":"Saying “all students will cooperate naturally” may be a glib and unreal assertion.","zh":"說「所有學生自然會合作」可能是流於表面且不切實際的斷言。"},{"en":"Glib assertions can hide classroom difficulties by making problems sound already solved.","zh":"流於表面的斷言會把問題說得像已經解決，從而掩蓋課室困難。"},{"en":"Good writing avoids glib and unreal assertions by using examples and evidence.","zh":"好寫作會用例子和證據避免流於表面且不切實際的斷言。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":14},{"front":"rather than","meaning":"而不是","examples":[{"en":"The statements may be propaganda rather than a reflection of classroom reality.","zh":"這些陳述可能是宣傳說辭，而不是課室現實的反映。"},{"en":"Rather than shows contrast and means instead of or not one thing but another.","zh":"rather than 表示對比，意思是「而不是」或「不是這個，而是那個」。"},{"en":"Students need useful feedback rather than empty praise.","zh":"學生需要有用回饋，而不是空洞讚美。"},{"en":"A school should solve bullying rather than simply hide it from parents.","zh":"學校應解決欺凌，而不是只是向家長隱瞞它。"},{"en":"This phrase helps separate the real issue from the wrong focus.","zh":"這個短語有助把真正問題與錯誤焦點分開。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":15},{"front":"a reflection of","meaning":"……的反映","examples":[{"en":"The claims may not be a reflection of what happens in real classrooms.","zh":"這些說法未必是真實課室情況的反映。"},{"en":"A reflection of something is a sign, expression, or result that shows what it is really like.","zh":"a reflection of something 指顯示某事真實情況的跡象、表達或結果。"},{"en":"A student’s final grade may be a reflection of effort, support, health, and exam skill.","zh":"學生的最終成績可能是努力、支援、健康和應試技巧的反映。"},{"en":"Complaints from many parents may be a reflection of deeper problems in communication.","zh":"許多家長的投訴可能是溝通深層問題的反映。"},{"en":"Not every statistic is a full reflection of reality.","zh":"不是每個統計數字都能完整反映現實。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":15},{"front":"what actually happens","meaning":"實際發生的事","examples":[{"en":"The author questions what actually happens in co-educational classrooms.","zh":"作者質疑男女校課室中實際發生的事。"},{"en":"What actually happens means the real events or behaviour, not what people imagine or claim.","zh":"what actually happens 指真實事件或行為，而不是人們想像或聲稱的情況。"},{"en":"A school should observe what actually happens during group work before praising it.","zh":"學校在稱讚小組活動前，應觀察當中實際發生的事。"},{"en":"What actually happens may differ from the official policy written on paper.","zh":"實際發生的事可能與紙上的官方政策不同。"},{"en":"This phrase asks us to look at reality instead of slogans.","zh":"這個短語要求我們看現實，而不是看口號。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":15},{"front":"co-educational classroom","meaning":"男女校課室","examples":[{"en":"The real test is what happens in the co-educational classroom.","zh":"真正考驗是男女校課室中發生甚麼。"},{"en":"A co-educational classroom is a classroom where boys and girls learn together.","zh":"co-educational classroom 是男生和女生一起學習的課室。"},{"en":"In a co-educational classroom, teachers must manage interaction fairly.","zh":"在男女校課室中，老師必須公平管理互動。"},{"en":"A co-educational classroom can reduce stereotypes if students cooperate respectfully.","zh":"如果學生尊重地合作，男女校課室可以減少定型觀念。"},{"en":"The success of a co-educational classroom depends on teaching quality, rules, and student culture.","zh":"男女校課室的成功取決於教學質素、規則和學生文化。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":15},{"front":"the key point is whether","meaning":"關鍵在於是否","examples":[{"en":"The key point is whether interaction in co-educational settings is positive.","zh":"關鍵在於男女校環境中的互動是否正面。"},{"en":"The key point is whether means the most important question is whether something is true.","zh":"the key point is whether 意思是最重要的問題在於某事是否為真。"},{"en":"The key point is whether students actually learn better, not whether the method sounds modern.","zh":"關鍵在於學生是否真的學得更好，而不是方法聽起來是否現代。"},{"en":"In choosing a tutor, the key point is whether the student improves and feels supported.","zh":"選擇補習老師時，關鍵在於學生是否進步並感到受支持。"},{"en":"This phrase helps focus a discussion on the central issue.","zh":"這個短語有助把討論集中在核心問題上。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":15},{"front":"interaction in co-educational settings","meaning":"男女校環境中的互動","examples":[{"en":"Interaction in co-educational settings can be positive or negative.","zh":"男女校環境中的互動可以是正面或負面的。"},{"en":"Interaction in co-educational settings means how boys and girls communicate and work together in mixed schools.","zh":"interaction in co-educational settings 指男女生在混合學校中如何溝通和合作。"},{"en":"Group tasks show whether interaction in co-educational settings is respectful and useful.","zh":"小組任務能顯示男女校環境中的互動是否尊重而有用。"},{"en":"Poor interaction in co-educational settings can create teasing, silence, or unequal participation.","zh":"男女校環境中的差劣互動可能造成取笑、沉默或參與不均。"},{"en":"Good interaction needs guidance; it does not always happen automatically.","zh":"良好互動需要引導；它不一定自動發生。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":15},{"front":"indeed positive and co-operative","meaning":"確實正面而合作","examples":[{"en":"The author questions whether such interaction is indeed positive and co-operative.","zh":"作者質疑這種互動是否確實正面而合作。"},{"en":"Indeed positive and co-operative means truly helpful, respectful, and willing to work together.","zh":"indeed positive and co-operative 意思是真正有幫助、尊重並願意一起合作。"},{"en":"A group project is indeed positive and co-operative when all members listen and contribute.","zh":"當所有成員都聆聽並貢獻時，小組項目才是確實正面而合作。"},{"en":"Interaction may look friendly but not be indeed positive if one student does all the work.","zh":"互動可能看起來友善，但如果只有一個學生做所有工作，就不算確實正面。"},{"en":"The word indeed asks whether the ideal description is actually true.","zh":"indeed 這個字是在問理想描述是否真的成立。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":15},{"front":"it could equally be the opposite","meaning":"同樣可能相反","examples":[{"en":"Some would say the interaction could equally be the opposite.","zh":"有些人會說，這種互動同樣可能相反。"},{"en":"It could equally be the opposite means the reverse result is just as possible.","zh":"it could equally be the opposite 意思是相反結果同樣可能發生。"},{"en":"A new rule may improve discipline, but it could equally be the opposite if students feel unfairly treated.","zh":"新規則可能改善紀律，但如果學生覺得受不公平對待，同樣可能相反。"},{"en":"If mixed classrooms are poorly managed, cooperation may not grow; it could equally be the opposite.","zh":"如果混合課室管理不善，合作未必增加；情況同樣可能相反。"},{"en":"This phrase challenges an overly confident assumption.","zh":"這個短語挑戰過於自信的假設。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":15},{"front":"abandon the rosy picture","meaning":"放棄過於樂觀的圖像","examples":[{"en":"We should abandon the rosy picture of perfect co-education.","zh":"我們應放棄完美男女校教育的過於樂觀圖像。"},{"en":"To abandon the rosy picture means to stop believing an overly positive and unrealistic view.","zh":"abandon the rosy picture 意思是停止相信過度正面而不現實的看法。"},{"en":"A city must abandon the rosy picture that tourism brings only money and no problems.","zh":"城市必須放棄「旅遊只帶來金錢而沒有問題」的過於樂觀圖像。"},{"en":"When real classroom conflicts appear, people may need to abandon the rosy picture of easy cooperation.","zh":"當真實課室衝突出現時，人們可能需要放棄容易合作的過於樂觀圖像。"},{"en":"This phrase encourages a more realistic judgement.","zh":"這個短語鼓勵更現實的判斷。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":15},{"front":"the rosy picture","meaning":"過於樂觀的圖像","examples":[{"en":"The previous paragraph paints a rosy picture of co-education.","zh":"上一段描繪了男女校教育的過於樂觀圖像。"},{"en":"The rosy picture is an overly positive description that makes something seem easier or better than it is.","zh":"the rosy picture 指過度正面的描述，令某事看起來比實際更容易或更好。"},{"en":"A school advertisement may present a rosy picture of student life by showing only happy scenes.","zh":"學校廣告可能只展示快樂場景，呈現學生生活的過於樂觀圖像。"},{"en":"A rosy picture can hide stress, inequality, or conflict.","zh":"過於樂觀的圖像可能掩蓋壓力、不平等或衝突。"},{"en":"Writers often mention a rosy picture before correcting it with reality.","zh":"作者常先提到過於樂觀的圖像，再用現實修正它。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":15},{"front":"painted in the previous paragraph","meaning":"在上一段描繪的","examples":[{"en":"The rosy picture painted in the previous paragraph may be unrealistic.","zh":"在上一段描繪的過於樂觀圖像可能不切實際。"},{"en":"Painted in the previous paragraph means described or presented in the paragraph before this one.","zh":"painted in the previous paragraph 意思是在前一段中被描述或呈現。"},{"en":"The problem painted in the previous paragraph becomes clearer when the writer gives examples.","zh":"當作者提供例子時，上一段描繪的問題會變得更清楚。"},{"en":"If an ideal scene is painted in the previous paragraph, the next paragraph may challenge it.","zh":"如果上一段描繪了一個理想情景，下一段可能會挑戰它。"},{"en":"This phrase helps readers follow the structure of an argument.","zh":"這個短語幫助讀者跟上論證結構。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":15},{"front":"academically enhancing","meaning":"有助學業提升的","examples":[{"en":"Some interaction may be academically enhancing.","zh":"有些互動可能有助學業提升。"},{"en":"Academically enhancing means helping students learn better or improve their academic performance.","zh":"academically enhancing 指幫助學生學得更好或提升學業表現。"},{"en":"A mixed study group can be academically enhancing if students explain ideas clearly to one another.","zh":"如果學生互相清楚解釋概念，混合學習小組可以有助學業提升。"},{"en":"Feedback is academically enhancing when it helps students correct mistakes and understand why.","zh":"當回饋幫助學生改正錯誤並理解原因時，它就有助學業提升。"},{"en":"Not every activity is academically enhancing just because it happens in school.","zh":"不是每項活動只因在學校發生，就一定有助學業提升。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":16},{"front":"academically retarding","meaning":"阻礙學業發展的","examples":[{"en":"Some interaction may be academically retarding.","zh":"有些互動可能阻礙學業發展。"},{"en":"Academically retarding means slowing down or harming students’ learning progress.","zh":"academically retarding 指拖慢或傷害學生的學習進展。"},{"en":"Constant teasing in class can be academically retarding because students stop asking questions.","zh":"課堂中持續取笑可能阻礙學業發展，因為學生不再提問。"},{"en":"A noisy group project may be academically retarding if no one focuses on the task.","zh":"如果無人集中任務，嘈雜的小組項目可能阻礙學業發展。"},{"en":"This phrase is the opposite of academically enhancing.","zh":"這個短語是 academically enhancing 的相反。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":16},{"front":"constitute education of a vital nature","meaning":"構成極其重要的教育","examples":[{"en":"Even difficult interaction constitutes education of a vital nature.","zh":"即使困難的互動也構成極其重要的教育。"},{"en":"To constitute education of a vital nature means to be an extremely important form of learning.","zh":"constitute education of a vital nature 意思是構成一種極其重要的學習。"},{"en":"Learning how to disagree respectfully constitutes education of a vital nature for adult life.","zh":"學會如何尊重地不同意，構成成人生活中極其重要的教育。"},{"en":"Handling failure can constitute education of a vital nature because it teaches resilience.","zh":"處理失敗可以構成極其重要的教育，因為它教會人韌性。"},{"en":"This phrase suggests that valuable education is not always comfortable or academic.","zh":"這個短語暗示有價值的教育不一定舒適或純學術。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":16},{"front":"of a vital nature","meaning":"極其重要的","examples":[{"en":"Learning to interact with others is of a vital nature.","zh":"學會與他人互動是極其重要的。"},{"en":"Of a vital nature means extremely important or necessary.","zh":"of a vital nature 意思是極其重要或必要。"},{"en":"Clear communication is of a vital nature in hospitals because mistakes can harm patients.","zh":"清楚溝通在醫院中極其重要，因為錯誤可能傷害病人。"},{"en":"Safety training is of a vital nature before students use laboratory equipment.","zh":"學生使用實驗室設備前，安全訓練是極其重要的。"},{"en":"This phrase is formal and stronger than simply saying important.","zh":"這個短語較正式，語氣比 simply saying important 更強。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":16},{"front":"present the same set of challenges","meaning":"呈現同一套挑戰","examples":[{"en":"Co-educational interaction presents the same set of challenges students will face later.","zh":"男女校互動呈現學生日後會面對的同一套挑戰。"},{"en":"To present the same set of challenges means to give people problems similar to those they will meet elsewhere.","zh":"present the same set of challenges 意思是給人們與其他地方會遇到的問題相似的一組挑戰。"},{"en":"Group work presents the same set of challenges students may face in the workplace.","zh":"小組工作呈現學生在職場可能面對的同一套挑戰。"},{"en":"If school presents the same set of challenges as real life, students can practise safely.","zh":"如果學校呈現與現實生活相同的一套挑戰，學生就能安全地練習。"},{"en":"This phrase explains why difficult situations can still be useful training.","zh":"這個短語解釋為何困難情況仍可以是有用訓練。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":16},{"front":"ultimately have to deal with","meaning":"最終必須處理","examples":[{"en":"Students will ultimately have to deal with gender interaction in the real world.","zh":"學生最終必須在現實世界中處理性別互動。"},{"en":"Ultimately have to deal with means finally must face, manage, or solve something.","zh":"ultimately have to deal with 意思是最終必須面對、處理或解決某事。"},{"en":"Young adults ultimately have to deal with money, time, work, and relationships.","zh":"年輕成年人最終必須處理金錢、時間、工作和關係。"},{"en":"If students avoid all disagreement, they will ultimately have to deal with it later without practice.","zh":"如果學生避開所有分歧，他們日後最終必須在沒有練習的情況下處理它。"},{"en":"This phrase points to an unavoidable future responsibility.","zh":"這個短語指向不可避免的未來責任。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":16},{"front":"determine which educational setting","meaning":"決定哪種教育環境","examples":[{"en":"This point would determine which educational setting the author would choose.","zh":"這一點會決定作者會選擇哪種教育環境。"},{"en":"To determine which educational setting means to decide which learning environment is best or most suitable.","zh":"determine which educational setting 意思是決定哪種學習環境最好或最合適。"},{"en":"A child’s needs may determine which educational setting will help them most.","zh":"孩子的需要可能決定哪種教育環境最能幫助他。"},{"en":"If safety is the main concern, it may determine which educational setting parents prefer.","zh":"如果安全是主要關注，這可能決定家長偏好哪種教育環境。"},{"en":"This phrase connects a key principle to a practical school choice.","zh":"這個短語把一個核心原則連繫到實際學校選擇。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":16},{"front":"choose for my children","meaning":"為我的孩子選擇","examples":[{"en":"The author says this would determine the school type he would choose for his children.","zh":"作者說這會決定他會為自己的孩子選擇哪種學校類型。"},{"en":"To choose for my children means to make a decision on behalf of one’s own children.","zh":"choose for my children 意思是代表自己的孩子作出決定。"},{"en":"Parents choose schools for their children by considering safety, learning style, and distance.","zh":"父母會考慮安全、學習方式和距離，為孩子選擇學校。"},{"en":"If a parent chooses for their children without listening to them, the choice may create stress.","zh":"如果父母不聽孩子意見就為他們選擇，這個選擇可能造成壓力。"},{"en":"This phrase shows that the debate has personal consequences, not only academic ones.","zh":"這個短語顯示這場爭論不只有學術意義，也有個人後果。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":16},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Students must choose the correct heading for each paragraph.","zh":"學生必須為每段選出正確標題。"},{"en":"To choose the correct heading means to select the title that best matches the main idea of a paragraph.","zh":"choose the correct heading 意思是選出最符合段落主旨的標題。"},{"en":"In a reading test, students should read the whole paragraph before choosing the correct heading.","zh":"在閱讀考試中，學生應先讀完整段，再選出正確標題。"},{"en":"Choosing the wrong heading often happens when students focus on one small detail.","zh":"學生只集中於一個小細節時，常會選錯標題。"},{"en":"A correct heading usually summarises the paragraph, not just one example inside it.","zh":"正確標題通常概括整段，而不只是段內一個例子。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":16},{"front":"list of headings","meaning":"標題列表","examples":[{"en":"The question provides a list of headings.","zh":"題目提供了一個標題列表。"},{"en":"A list of headings is a group of possible paragraph titles in a reading task.","zh":"list of headings 是閱讀題中一組可能的段落標題。"},{"en":"Students should compare the list of headings with paragraph main ideas, not with single words only.","zh":"學生應把標題列表與段落主旨比較，而不應只比較單字。"},{"en":"A long list of headings can confuse students if several titles sound similar.","zh":"如果多個標題聽起來相似，長長的標題列表可能令學生混亂。"},{"en":"Crossing out used headings can make the task easier.","zh":"劃走已使用的標題可以令任務更容易。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":16},{"front":"write the correct number","meaning":"寫上正確編號","examples":[{"en":"Students should write the correct number for each answer.","zh":"學生應為每個答案寫上正確編號。"},{"en":"To write the correct number means to put the number that matches the chosen option.","zh":"write the correct number 意思是填上與所選選項相配的編號。"},{"en":"In matching questions, students may write the correct number beside each paragraph letter.","zh":"在配對題中，學生可能要在每個段落字母旁寫上正確編號。"},{"en":"Writing the wrong number can lose marks even if the student understood the paragraph.","zh":"即使學生理解段落，寫錯編號也可能失分。"},{"en":"Always check whether the answer should be a letter, word, or number.","zh":"一定要檢查答案應填字母、單字還是數字。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":16},{"front":"another argument in favour","meaning":"另一個支持論點","examples":[{"en":"The heading refers to another argument in favour of single-sex education.","zh":"這個標題指另一個支持單性別教育的論點。"},{"en":"Another argument in favour means one more reason that supports a particular view.","zh":"another argument in favour 指另一個支持某觀點的理由。"},{"en":"Another argument in favour of school libraries is that they give quiet space to students.","zh":"支持學校圖書館的另一個論點是它們給學生安靜空間。"},{"en":"Writers use another argument in favour when adding support after a first reason.","zh":"作者在第一個理由之後加入支持時，會使用另一個支持論點。"},{"en":"This phrase helps build a case step by step.","zh":"這個短語有助一步一步建立理據。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":17},{"front":"conflicting evidence","meaning":"互相矛盾的證據","examples":[{"en":"The passage presents conflicting evidence about single-gender schooling.","zh":"文章呈現關於單一性別學校教育的互相矛盾的證據。"},{"en":"Conflicting evidence is evidence that points in different or opposite directions.","zh":"conflicting evidence 是指向不同或相反方向的證據。"},{"en":"One study may say homework helps, while another gives conflicting evidence.","zh":"一項研究可能說功課有幫助，而另一項給出互相矛盾的證據。"},{"en":"Conflicting evidence makes it difficult to decide which policy is best.","zh":"互相矛盾的證據令判斷哪項政策最好變得困難。"},{"en":"When evidence conflicts, students should compare research methods and sample sizes.","zh":"當證據互相矛盾時，學生應比較研究方法和樣本大小。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":17},{"front":"negatives are positives","meaning":"負面因素變成正面因素","examples":[{"en":"The heading suggests that some negative experiences may become positive learning.","zh":"這個標題暗示有些負面經驗可能變成正面學習。"},{"en":"Negatives are positives means things that seem bad may bring useful benefits or lessons.","zh":"negatives are positives 意思是看似不好的事情可能帶來有用好處或教訓。"},{"en":"A difficult group project may show that negatives are positives if students learn patience.","zh":"如果學生學會耐性，一個困難小組項目可能顯示負面因素變成正面因素。"},{"en":"Conflict can become positive when it teaches people how to communicate better.","zh":"當衝突教會人更好溝通時，它可以變成正面。"},{"en":"This idea does not deny problems; it asks whether problems can educate people.","zh":"這個想法不是否認問題；它是在問問題能否教育人。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":17},{"front":"an emotional argument","meaning":"情緒化論點","examples":[{"en":"The debate can sometimes become an emotional argument.","zh":"這場辯論有時可能變成情緒化論點。"},{"en":"An emotional argument is an argument driven mainly by feelings rather than careful evidence.","zh":"an emotional argument 是主要由情感而不是仔細證據推動的論點。"},{"en":"A speech about bullying may become an emotional argument if it focuses only on fear and anger.","zh":"如果一篇關於欺凌的演說只集中於恐懼和憤怒，它可能變成情緒化論點。"},{"en":"Emotional arguments can move people, but they may not answer practical questions.","zh":"情緒化論點可以打動人，但未必回答實際問題。"},{"en":"A strong essay can use emotion, but it should still include logic and evidence.","zh":"有力文章可以使用情感，但仍應包含邏輯和證據。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":17},{"front":"does it help or not","meaning":"是否有幫助","examples":[{"en":"The central question is whether single-gender education helps or not.","zh":"核心問題是單一性別教育是否有幫助。"},{"en":"Does it help or not asks whether something is useful, effective, or beneficial.","zh":"does it help or not 是問某事是否有用、有效或有益。"},{"en":"When judging a study app, the question is simple: does it help or not?","zh":"評估學習應用程式時，問題很簡單：它是否有幫助？"},{"en":"A policy may sound modern, but the real question is whether it helps or not.","zh":"一項政策可能聽起來現代，但真正問題是它是否有幫助。"},{"en":"This phrase brings a complicated debate back to practical results.","zh":"這個短語把複雜爭論帶回實際結果。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":17},{"front":"looking at the other side","meaning":"從另一方角度看","examples":[{"en":"The passage also looks at the other side of the debate.","zh":"文章也從這場辯論的另一方角度看問題。"},{"en":"Looking at the other side means considering the opposite view or alternative argument.","zh":"looking at the other side 意思是考慮相反觀點或另一種論點。"},{"en":"In an essay, looking at the other side helps show balance and fairness.","zh":"在文章中，從另一方角度看有助顯示平衡和公平。"},{"en":"Looking at the other side can reveal weaknesses in your own first opinion.","zh":"從另一方角度看，可以揭示自己最初觀點的弱點。"},{"en":"This phrase is useful when moving from supporters’ claims to critics’ claims.","zh":"這個短語適合用於從支持者說法轉向批評者說法。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":17},{"front":"a counter-argument","meaning":"反駁論點","examples":[{"en":"A counter-argument challenges the claims made by supporters.","zh":"反駁論點挑戰支持者提出的說法。"},{"en":"A counter-argument is an argument that opposes or responds to another argument.","zh":"counter-argument 是反對或回應另一個論點的論點。"},{"en":"If someone says homework improves learning, a counter-argument may be that it increases stress.","zh":"如果有人說功課改善學習，反駁論點可能是它增加壓力。"},{"en":"Good writers include a counter-argument to show they understand both sides.","zh":"好作者會加入反駁論點，以顯示自己理解雙方。"},{"en":"A counter-argument is strongest when it answers the main claim, not a weak version of it.","zh":"反駁論點在回應主要說法，而不是弱化版本時最有力。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":17},{"front":"it’s happening anyway","meaning":"反正正在發生","examples":[{"en":"The heading suggests that social grouping is happening anyway.","zh":"這個標題暗示社交分組反正正在發生。"},{"en":"It’s happening anyway means something is already occurring even without official action.","zh":"it’s happening anyway 意思是某事即使沒有正式行動也已經在發生。"},{"en":"Students may form friendship groups naturally; in other words, it’s happening anyway.","zh":"學生可能自然形成朋友圈；換句話說，這反正正在發生。"},{"en":"If separation is happening anyway, schools may need to manage it rather than pretend it does not exist.","zh":"如果分隔反正正在發生，學校可能需要管理它，而不是假裝它不存在。"},{"en":"This phrase can weaken an objection by saying the criticised thing already exists.","zh":"這個短語可透過指出被批評的事情已存在，來削弱反對意見。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":17},{"front":"the problems with genders","meaning":"性別之間的問題","examples":[{"en":"The passage discusses the problems with gender relations.","zh":"文章討論性別關係中的問題。"},{"en":"The problems with genders refers to difficulties in how boys and girls, or men and women, understand and treat one another.","zh":"the problems with genders 指男生和女生、或男性和女性如何理解和對待彼此時出現的困難。"},{"en":"The problems with genders may appear as teasing, pressure, fear, or unfair expectations.","zh":"性別之間的問題可能表現為取笑、壓力、恐懼或不公平期望。"},{"en":"Schools need to address the problems with genders instead of assuming students will solve them alone.","zh":"學校需要處理性別之間的問題，而不是假設學生會自己解決。"},{"en":"This phrase is informal; in formal writing, gender relations is usually better.","zh":"這個短語較口語；正式寫作中通常用 gender relations 較好。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":17},{"front":"an argument in favour","meaning":"支持論點","examples":[{"en":"One paragraph gives an argument in favour of single-sex education.","zh":"其中一段提出支持單性別教育的論點。"},{"en":"An argument in favour is a reason that supports a view, policy, or decision.","zh":"an argument in favour 是支持某觀點、政策或決定的理由。"},{"en":"An argument in favour of longer library hours is that students need quiet study space.","zh":"支持延長圖書館開放時間的一個論點是學生需要安靜學習空間。"},{"en":"A strong argument in favour explains both benefit and evidence.","zh":"有力的支持論點會解釋好處和證據。"},{"en":"This phrase is common in balanced essays and reading headings.","zh":"這個短語常見於平衡文章和閱讀標題。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":17},{"front":"complete the sentences with","meaning":"用……完成句子","examples":[{"en":"Students must complete the sentences with the correct ending.","zh":"學生必須用正確句尾完成句子。"},{"en":"Complete the sentences with means fill in the missing part using the given word, phrase, or ending.","zh":"complete the sentences with 意思是用指定單字、短語或句尾填上缺失部分。"},{"en":"In grammar practice, students complete the sentences with the correct verb form.","zh":"在文法練習中，學生用正確動詞形式完成句子。"},{"en":"If students do not read the whole sentence, they may complete it with a grammatically wrong ending.","zh":"如果學生沒有讀完整句，可能會用文法錯誤的句尾完成句子。"},{"en":"This instruction asks students to make the sentence whole and accurate.","zh":"這個指示要求學生令句子完整而準確。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":17},{"front":"the correct ending","meaning":"正確句尾","examples":[{"en":"Each sentence must be matched with the correct ending.","zh":"每個句子都必須配對正確句尾。"},{"en":"The correct ending is the option that completes a sentence logically and grammatically.","zh":"the correct ending 是在邏輯和文法上完成句子的選項。"},{"en":"In reading tasks, the correct ending must match the passage, not just common sense.","zh":"在閱讀題中，正確句尾必須符合文章，而不只是符合常識。"},{"en":"A wrong ending may use familiar words but change the meaning of the sentence.","zh":"錯誤句尾可能使用熟悉詞語，但改變句子意思。"},{"en":"To find the correct ending, check grammar, meaning, and evidence together.","zh":"要找出正確句尾，應同時檢查文法、意思和證據。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":18},{"front":"have some strong views","meaning":"有強烈看法","examples":[{"en":"The magazines have some strong views on single-sex schooling.","zh":"這些雜誌對單性別學校教育有強烈看法。"},{"en":"To have some strong views means to hold firm opinions, often with clear approval or criticism.","zh":"have some strong views 意思是持有堅定意見，通常帶有清楚支持或批評。"},{"en":"Parents may have strong views about homework because it affects family life.","zh":"家長可能對功課有強烈看法，因為它影響家庭生活。"},{"en":"Strong views can make debate lively, but they can also make compromise harder.","zh":"強烈看法可以令辯論活躍，但也可能令妥協更困難。"},{"en":"Having strong views is acceptable if people still listen to evidence.","zh":"有強烈看法可以接受，前提是人們仍願意聽證據。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":18},{"front":"think boys and girls are similar","meaning":"認為男孩和女孩相似","examples":[{"en":"Neuroscientists may think boys and girls are similar in key ways.","zh":"神經科學家可能認為男孩和女孩在關鍵方面相似。"},{"en":"To think boys and girls are similar means to believe the two groups are not fundamentally different in some important areas.","zh":"think boys and girls are similar 意思是相信兩個群體在某些重要方面並沒有根本差異。"},{"en":"A teacher may think boys and girls are similar in their need for encouragement and clear feedback.","zh":"老師可能認為男孩和女孩在需要鼓勵和清楚回饋方面相似。"},{"en":"If research shows similarity, it may challenge claims about fixed gender learning styles.","zh":"如果研究顯示相似性，可能挑戰固定性別學習方式的說法。"},{"en":"Similar does not mean identical; it means the differences may be smaller than people assume.","zh":"相似不代表完全一樣；它代表差異可能比人們假設的小。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":18},{"front":"often have idealistic views","meaning":"經常有理想化看法","examples":[{"en":"Supporters of co-education often have idealistic views.","zh":"男女校教育支持者經常有理想化看法。"},{"en":"To often have idealistic views means to regularly hold hopeful beliefs that may ignore practical difficulties.","zh":"often have idealistic views 意思是經常持有充滿希望但可能忽視實際困難的信念。"},{"en":"New teachers may often have idealistic views before facing large classes and limited time.","zh":"新老師在面對大班和有限時間前，可能經常有理想化看法。"},{"en":"Idealistic views can inspire change, but they need practical plans.","zh":"理想化看法可以激發改變，但需要實際計劃。"},{"en":"This phrase can be mildly critical if the views seem too far from reality.","zh":"如果這些看法看似太遠離現實，這個短語可以帶有輕微批評意味。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":18},{"front":"are surprising in some ways","meaning":"在某些方面令人意外","examples":[{"en":"Some features of the single-gender debate are surprising in some ways.","zh":"單一性別辯論的某些特點在某些方面令人意外。"},{"en":"Are surprising in some ways means are unexpected from certain angles, though not completely shocking.","zh":"are surprising in some ways 意思是從某些角度看出乎意料，但不是完全震驚。"},{"en":"The popularity of handwritten notes is surprising in some ways because students use so much technology.","zh":"手寫筆記仍受歡迎在某些方面令人意外，因為學生使用很多科技。"},{"en":"A result may be surprising in some ways when it conflicts with modern values.","zh":"當結果與現代價值觀衝突時，它在某些方面可能令人意外。"},{"en":"This phrase gives a careful, moderate judgement rather than an extreme one.","zh":"這個短語給出謹慎而適中的判斷，而不是極端判斷。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":18},{"front":"often receive much respect","meaning":"經常得到很多尊重","examples":[{"en":"Students from single-gender schools often receive much respect.","zh":"來自單一性別學校的學生經常得到很多尊重。"},{"en":"Often receive much respect means are frequently treated with admiration or high social regard.","zh":"often receive much respect 意思是經常受到欽佩或高度社會重視。"},{"en":"Graduates from famous universities often receive much respect before employers know their real ability.","zh":"名牌大學畢業生在僱主知道其真正能力前，經常得到很多尊重。"},{"en":"Receiving respect can open doors, but it can also reflect social privilege.","zh":"得到尊重可以打開機會，但也可能反映社會特權。"},{"en":"Respect based only on school name may not be fair to others.","zh":"只基於校名的尊重，對其他人可能不公平。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":18},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students must choose the correct letter from the options.","zh":"學生必須從選項中選出正確字母。"},{"en":"To choose the correct letter means to select the option label that matches the answer.","zh":"choose the correct letter 意思是選出與答案相符的選項字母。"},{"en":"In multiple-choice questions, students choose the correct letter after eliminating wrong choices.","zh":"在選擇題中，學生會排除錯誤選項後選出正確字母。"},{"en":"Choosing the correct letter requires understanding the passage, not just spotting repeated words.","zh":"選出正確字母需要理解文章，而不只是看到重複詞語。"},{"en":"Always copy the correct letter carefully onto the answer sheet.","zh":"一定要小心把正確字母抄到答題紙上。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":18},{"front":"clear statistical support","meaning":"明確的統計支持","examples":[{"en":"The author does not claim that co-education has clear statistical support.","zh":"作者沒有聲稱男女校教育有明確的統計支持。"},{"en":"Clear statistical support means numbers or data clearly back up a claim.","zh":"clear statistical support 指數字或數據清楚支持某個說法。"},{"en":"A teaching method has clear statistical support if many studies show higher scores after using it.","zh":"如果多項研究顯示使用某教學方法後成績提高，它就有明確的統計支持。"},{"en":"Without clear statistical support, a policy may still sound attractive but remain uncertain.","zh":"沒有明確的統計支持，一項政策可能仍聽起來吸引，但仍不確定。"},{"en":"Statistical support should be clear, reliable, and relevant to the claim being made.","zh":"統計支持應清楚、可靠，並與所提出的說法相關。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":18},{"front":"less stereotyping","meaning":"較少性別定型","examples":[{"en":"Some people believe co-education may lead to less stereotyping.","zh":"有些人相信男女校教育可能帶來較少性別定型。"},{"en":"Less stereotyping means fewer fixed and unfair assumptions about groups of people.","zh":"less stereotyping 意思是對群體較少作出固定而不公平的假設。"},{"en":"Mixed teamwork may lead to less stereotyping if students see each other’s real abilities.","zh":"如果學生看見彼此的真實能力，混合團隊合作可能帶來較少定型觀念。"},{"en":"Less stereotyping can help children choose subjects based on interest, not gender labels.","zh":"較少性別定型可以幫助孩子按興趣選科，而不是按性別標籤。"},{"en":"Less stereotyping requires repeated experience that challenges old assumptions.","zh":"較少定型觀念需要反覆經驗來挑戰舊假設。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":18},{"front":"positive interaction","meaning":"正面互動","examples":[{"en":"The value of co-education depends on positive interaction.","zh":"男女校教育的價值取決於正面互動。"},{"en":"Positive interaction means communication or contact that is respectful, helpful, and constructive.","zh":"positive interaction 指尊重、有幫助和具建設性的溝通或接觸。"},{"en":"Positive interaction in class includes listening, sharing tasks, and giving fair feedback.","zh":"課堂中的正面互動包括聆聽、分擔任務和給予公平回饋。"},{"en":"Without positive interaction, mixed classrooms may not reduce gender divisions.","zh":"沒有正面互動，混合課室未必能減少性別分歧。"},{"en":"Positive interaction is something schools must teach and protect.","zh":"正面互動是學校必須教導和保護的東西。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":18},{"front":"lower-quality teaching","meaning":"較低質素的教學","examples":[{"en":"The question option mentions lower-quality teaching in co-educational schools.","zh":"題目選項提到男女校中較低質素的教學。"},{"en":"Lower-quality teaching means teaching that is less clear, less supportive, or less effective.","zh":"lower-quality teaching 指較不清楚、較少支援或較無效的教學。"},{"en":"Students may suffer from lower-quality teaching if lessons are rushed and feedback is weak.","zh":"如果課堂匆忙而回饋薄弱，學生可能受較低質素的教學影響。"},{"en":"Lower-quality teaching can lower results even when students are motivated.","zh":"即使學生有動力，較低質素的教學也可以拉低成績。"},{"en":"When comparing schools, teaching quality may matter more than whether the school is mixed or single-sex.","zh":"比較學校時，教學質素可能比學校是男女校還是單性別學校更重要。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":18},{"front":"compared to","meaning":"與……相比","examples":[{"en":"The option compares co-education to single-gender schooling.","zh":"這個選項把男女校教育與單一性別學校教育相比。"},{"en":"Compared to means looked at in relation to another thing to show similarities or differences.","zh":"compared to 意思是把某事與另一事物相關地看，以顯示相似或差異。"},{"en":"Compared to driving, taking the train may be cheaper and less stressful.","zh":"與駕車相比，乘火車可能較便宜且壓力較少。"},{"en":"A school may look successful compared to others because it admits stronger students.","zh":"一間學校與其他學校相比可能看似成功，因為它收取較強學生。"},{"en":"When using compared to, make sure the two things are fairly comparable.","zh":"使用 compared to 時，要確保兩件事可以公平比較。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":19},{"front":"co-educational schooling","meaning":"男女校教育","examples":[{"en":"The author suggests that co-educational schooling is preferable.","zh":"作者暗示男女校教育較可取。"},{"en":"Co-educational schooling means a school system where boys and girls are educated together.","zh":"co-educational schooling 指男生和女生一起受教育的學校制度。"},{"en":"Co-educational schooling can help students practise communication with different genders.","zh":"男女校教育可以幫助學生練習與不同性別溝通。"},{"en":"Co-educational schooling may fail if teachers do not manage respect and participation well.","zh":"如果老師沒有妥善管理尊重和參與，男女校教育可能失敗。"},{"en":"The author prefers it mainly because real life is mixed-gender.","zh":"作者偏好它，主要因為現實生活是男女共存的。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":19},{"front":"preferable","meaning":"較可取的","examples":[{"en":"Co-educational schooling seems preferable to the author.","zh":"對作者來說，男女校教育似乎較可取。"},{"en":"Preferable means better or more suitable than another choice.","zh":"preferable 指比另一個選擇更好或更合適。"},{"en":"For a tired student, a short focused lesson may be preferable to three hours of unfocused study.","zh":"對疲倦學生來說，短而集中的課堂可能比三小時不集中的學習更可取。"},{"en":"A safer route is preferable even if it takes slightly longer.","zh":"較安全的路線即使稍長，也較可取。"},{"en":"Preferable does not mean perfect; it means better among the available options.","zh":"preferable 不代表完美；它代表在可用選項中較好。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":19},{"front":"cannot say which sort of","meaning":"不能判斷哪一種……","examples":[{"en":"Some people argue that we cannot say which sort of schooling is better.","zh":"有些人主張我們不能判斷哪一種學校教育較好。"},{"en":"Cannot say which sort of means cannot confidently decide which type or kind is correct or better.","zh":"cannot say which sort of 意思是不能有信心地決定哪一類或哪一種較正確或較好。"},{"en":"Without knowing the child’s needs, we cannot say which sort of class will help most.","zh":"如果不知道孩子的需要，我們不能判斷哪一種課堂最有幫助。"},{"en":"If evidence is mixed, researchers cannot say which sort of policy works best.","zh":"如果證據混雜，研究者不能判斷哪一種政策最有效。"},{"en":"This phrase shows uncertainty and avoids overclaiming.","zh":"這個短語表達不確定，並避免過度聲稱。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":19},{"front":"more evidence is needed","meaning":"需要更多證據","examples":[{"en":"The debate may continue because more evidence is needed.","zh":"這場爭論可能會持續，因為需要更多證據。"},{"en":"More evidence is needed means there is not yet enough proof to make a confident conclusion.","zh":"more evidence is needed 意思是目前還沒有足夠證明讓人有信心下結論。"},{"en":"Before changing the timetable, the school may decide that more evidence is needed.","zh":"在更改時間表前，學校可能認為需要更多證據。"},{"en":"More evidence is needed when different studies produce different results.","zh":"當不同研究產生不同結果時，就需要更多證據。"},{"en":"This phrase is useful for a cautious conclusion in academic writing.","zh":"這個短語適合用於學術寫作中的謹慎結論。"}],"source":"85 - Single-Gender Education A Case Made?.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 86":[{"front":"the deadliest insect","meaning":"最致命的昆蟲","examples":[{"en":"The passage asks readers to identify the deadliest insect in the world.","zh":"文章要求讀者辨認世界上最致命的昆蟲。"},{"en":"The deadliest insect is the insect that causes the most human deaths.","zh":"the deadliest insect 指造成最多人類死亡的昆蟲。"},{"en":"A quiz about public health may ask students to name the deadliest insect.","zh":"公共健康小測可能要求學生說出最致命的昆蟲。"},{"en":"If an insect spreads fatal diseases to many people, it may be considered the deadliest.","zh":"如果一種昆蟲向許多人傳播致命疾病，它可能被視為最致命。"},{"en":"The phrase focuses on death toll, not on size or scary appearance.","zh":"這個片語集中於死亡人數，而不是體型或可怕外表。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":1},{"front":"search their minds for","meaning":"在腦海中搜尋","examples":[{"en":"Most people would search their minds for dangerous-looking creatures.","zh":"大多數人會在腦海中搜尋外表危險的生物。"},{"en":"Search their minds for means try hard to remember or think of something.","zh":"search their minds for 指努力回想或思考某事。"},{"en":"In an exam, students may search their minds for the correct grammar rule.","zh":"在考試中，學生可能在腦海中搜尋正確文法規則。"},{"en":"If a question is surprising, people search their minds before answering.","zh":"如果問題令人意外，人們回答前會在腦海中搜尋。"},{"en":"The phrase describes mental searching, not looking with the eyes.","zh":"這個片語描述心理搜尋，而不是用眼睛尋找。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":1},{"front":"sinister-looking spiders","meaning":"外表陰森可怕的蜘蛛","examples":[{"en":"Some people might think of sinister-looking spiders.","zh":"有些人可能會想到外表陰森可怕的蜘蛛。"},{"en":"Sinister-looking spiders are spiders that look frightening, dark, or threatening.","zh":"sinister-looking spiders 指看起來可怕、陰暗或具威脅感的蜘蛛。"},{"en":"A child may avoid a corner after seeing sinister-looking spiders on the wall.","zh":"孩子看到牆上有外表陰森可怕的蜘蛛後，可能避開角落。"},{"en":"If an animal looks sinister, people may fear it even before knowing whether it is dangerous.","zh":"如果動物看起來陰森，人們即使不知道它是否危險也可能害怕。"},{"en":"The phrase describes appearance, not necessarily actual danger.","zh":"這個片語描述外表，而不一定是真正危險。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":1},{"front":"scorpions","meaning":"蠍子","examples":[{"en":"Some people might think of scorpions rather than mosquitoes.","zh":"有些人可能會想到蠍子，而不是蚊子。"},{"en":"Scorpions are small arachnids with pincers and a tail that can sting.","zh":"scorpions 是有鉗和可刺尾巴的小型蛛形動物。"},{"en":"Travellers in deserts may check shoes before wearing them in case scorpions are inside.","zh":"沙漠旅客穿鞋前可能檢查鞋內是否有蠍子。"},{"en":"If people judge danger by appearance, scorpions may seem deadlier than mosquitoes.","zh":"如果人們按外表判斷危險，蠍子可能看起來比蚊子更致命。"},{"en":"The word refers to a venomous-looking creature, not an insect.","zh":"這個詞指一種看似有毒的生物，而不是昆蟲。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":1},{"front":"exotic garden pests","meaning":"外來園藝害蟲","examples":[{"en":"People may imagine exotic garden pests when asked about deadly insects.","zh":"當被問到致命昆蟲時，人們可能想像外來園藝害蟲。"},{"en":"Exotic garden pests are unusual non-local creatures that damage plants in gardens.","zh":"exotic garden pests 是會損害花園植物的不尋常外來生物。"},{"en":"A gardener may worry about exotic garden pests after finding strange insects on leaves.","zh":"園丁在葉上發現奇怪昆蟲後，可能擔心外來園藝害蟲。"},{"en":"If pests arrive from another region, local plants may have little resistance to them.","zh":"如果害蟲來自另一地區，本地植物可能對它們缺乏抵抗力。"},{"en":"The phrase suggests unfamiliar plant-damaging creatures.","zh":"這個片語暗示陌生而會破壞植物的生物。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":1},{"front":"define something in terms of","meaning":"從……角度定義……","examples":[{"en":"The passage defines “deadly” in terms of the number of people killed.","zh":"文章從死亡人數角度定義「致命」。"},{"en":"Define something in terms of means explain it using a particular measure or angle.","zh":"define something in terms of 指用某個特定標準或角度解釋某事。"},{"en":"A teacher may define success in terms of progress, not only exam marks.","zh":"老師可能從進步角度定義成功，而不只看考試分數。"},{"en":"If danger is defined in terms of deaths, small insects can seem more dangerous than large animals.","zh":"如果危險從死亡人數角度定義，小昆蟲可能比大型動物更危險。"},{"en":"The phrase shows the standard used for judging meaning.","zh":"這個片語顯示用來判斷意思的標準。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":1},{"front":"die directly as a result of","meaning":"直接因……而死亡","examples":[{"en":"The passage considers how many people die directly as a result of an insect.","zh":"文章考慮有多少人直接因昆蟲而死亡。"},{"en":"Die directly as a result of means die because of one clear cause without an indirect chain.","zh":"die directly as a result of 指因一個清楚原因死亡，而不是間接連鎖造成。"},{"en":"A patient may die directly as a result of a severe allergic reaction.","zh":"病人可能直接因嚴重過敏反應而死亡。"},{"en":"If people die directly as a result of a disease, that disease has an immediate fatal effect.","zh":"如果人們直接因疾病死亡，該疾病就有即時致命影響。"},{"en":"The phrase focuses on direct cause of death.","zh":"這個片語集中於直接死因。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":1},{"front":"lead the field","meaning":"遙遙領先","examples":[{"en":"The mosquito leads the field among deadly insects.","zh":"蚊子在致命昆蟲之中遙遙領先。"},{"en":"Lead the field means be the top or most important example in a group.","zh":"lead the field 指在某群體中位居第一或最重要。"},{"en":"A school may lead the field in science education if its students win many awards.","zh":"如果一間學校的學生贏得許多獎項，它可能在科學教育方面遙遙領先。"},{"en":"If one company sells far more than all others, it leads the field.","zh":"如果一間公司銷量遠高於其他所有公司，它就遙遙領先。"},{"en":"The phrase describes being clearly ahead of competitors or examples.","zh":"這個片語描述在競爭者或例子中明顯領先。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":1},{"front":"by far","meaning":"遠遠；明顯地","examples":[{"en":"The mosquito is, by far, the most dangerous insect.","zh":"蚊子遠遠是最危險的昆蟲。"},{"en":"By far means clearly and by a large margin.","zh":"by far 指明顯地，而且差距很大。"},{"en":"This is by far the cheapest route to school.","zh":"這條路線遠遠是去學校最便宜的。"},{"en":"If one answer is by far the best, the other options are much weaker.","zh":"如果一個答案明顯最好，其他選項就弱得多。"},{"en":"The phrase strongly emphasises difference.","zh":"這個片語強烈強調差距。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":1},{"front":"blood-sucking pest","meaning":"吸血害蟲","examples":[{"en":"The mosquito is described as a blood-sucking pest.","zh":"蚊子被描述為吸血害蟲。"},{"en":"A blood-sucking pest is a troublesome creature that feeds on blood.","zh":"blood-sucking pest 指以血液為食並帶來滋擾的生物。"},{"en":"Fleas can be blood-sucking pests when they bite pets and people.","zh":"跳蚤叮咬寵物和人時，可以是吸血害蟲。"},{"en":"If a pest sucks blood, it may also spread disease between hosts.","zh":"如果害蟲吸血，它也可能在宿主之間傳播疾病。"},{"en":"The phrase sounds negative because it combines irritation and danger.","zh":"這個片語聽起來負面，因為它結合滋擾和危險。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":1},{"front":"transmit diseases to","meaning":"將疾病傳播給……","examples":[{"en":"Mosquitoes transmit diseases to over 700 million people a year.","zh":"蚊子每年將疾病傳播給超過七億人。"},{"en":"Transmit diseases to means pass infections from one host to another.","zh":"transmit diseases to 指把感染從一個宿主傳給另一個宿主。"},{"en":"Dirty needles can transmit diseases to patients if they are reused.","zh":"如果重用骯髒針筒，它們可以將疾病傳播給病人。"},{"en":"If insects transmit diseases to humans, controlling them becomes a public health priority.","zh":"如果昆蟲將疾病傳播給人類，控制它們就成為公共健康優先事項。"},{"en":"The phrase describes disease spread from a carrier to a victim.","zh":"這個片語描述疾病由攜帶者傳到受害者。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":2},{"front":"a fair proportion of","meaning":"相當一部分的……","examples":[{"en":"Mosquitoes kill a fair proportion of the people they infect.","zh":"蚊子殺死牠們感染的人中相當一部分。"},{"en":"A fair proportion of means quite a large part of a group.","zh":"a fair proportion of 指一個群體中相當大的部分。"},{"en":"A fair proportion of students may need extra help before a difficult exam.","zh":"困難考試前，相當一部分學生可能需要額外幫助。"},{"en":"If a fair proportion of infected people die, the disease is very serious.","zh":"如果相當一部分感染者死亡，該疾病就非常嚴重。"},{"en":"The phrase suggests a noticeable amount, not just a few.","zh":"這個片語暗示數量明顯，而不只是少數。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":2},{"front":"in the process","meaning":"在過程中","examples":[{"en":"Mosquitoes transmit disease and kill many people in the process.","zh":"蚊子傳播疾病，並在過程中殺死許多人。"},{"en":"In the process means while doing something else or as part of that action.","zh":"in the process 指在做另一件事期間，或作為該行動的一部分。"},{"en":"A student may learn new vocabulary and improve grammar in the process.","zh":"學生可能學到新詞彙，並在過程中改善文法。"},{"en":"If a machine saves time and reduces waste in the process, it has two benefits.","zh":"如果機器節省時間並在過程中減少浪費，它就有兩個好處。"},{"en":"The phrase shows an additional result happening during an action.","zh":"這個片語顯示某行動期間發生額外結果。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":2},{"front":"come even close to","meaning":"接近……的程度","examples":[{"en":"No other insect comes even close to the mosquito’s death toll.","zh":"沒有其他昆蟲接近蚊子的死亡人數。"},{"en":"Come even close to means nearly reach the same level as something, often in a comparison.","zh":"come even close to 指幾乎達到與某事物相同水平，常用於比較。"},{"en":"No other student came even close to her score in the spelling competition.","zh":"在串字比賽中，沒有其他學生接近她的分數。"},{"en":"If no rival comes close, the leading example is far ahead.","zh":"如果沒有競爭者接近，領先例子就遠遠在前。"},{"en":"The phrase emphasises a very large gap.","zh":"這個片語強調非常大的差距。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":2},{"front":"nectar feeders","meaning":"吸食花蜜的動物","examples":[{"en":"All mosquitoes are nectar feeders.","zh":"所有蚊子都是吸食花蜜的動物。"},{"en":"Nectar feeders are animals that feed on sweet liquid from flowers.","zh":"nectar feeders 指以花朵中的甜液為食的動物。"},{"en":"Bees and butterflies are common nectar feeders in gardens.","zh":"蜜蜂和蝴蝶是花園中常見的吸食花蜜動物。"},{"en":"If mosquitoes feed on nectar, not all of their feeding is blood-related.","zh":"如果蚊子吸食花蜜，就不是所有進食都與吸血有關。"},{"en":"The phrase describes diet, not danger.","zh":"這個片語描述飲食，而不是危險性。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":2},{"front":"blood meal","meaning":"血餐；吸血所得的養分","examples":[{"en":"Female mosquitoes need protein from a blood meal.","zh":"雌蚊需要來自血餐的蛋白質。"},{"en":"A blood meal is blood taken by an insect or parasite for nutrition.","zh":"blood meal 指昆蟲或寄生蟲吸取的血液養分。"},{"en":"A mosquito may seek a blood meal before laying eggs.","zh":"蚊子可能在產卵前尋找血餐。"},{"en":"If a mosquito takes a blood meal from an infected person, it may carry disease onward.","zh":"如果蚊子從感染者身上吸取血餐，它可能繼續攜帶疾病。"},{"en":"The phrase is biological and refers to feeding on blood.","zh":"這個片語屬生物用語，指吸食血液。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":2},{"front":"produce eggs","meaning":"產卵","examples":[{"en":"Female mosquitoes need blood in order to produce eggs.","zh":"雌蚊需要血液才能產卵。"},{"en":"Produce eggs means create eggs for reproduction.","zh":"produce eggs 指製造用於繁殖的卵。"},{"en":"Chickens produce eggs regularly when they are healthy and well fed.","zh":"雞隻健康且飼養良好時會定期產卵。"},{"en":"If female mosquitoes cannot get enough protein, they may produce fewer eggs.","zh":"如果雌蚊得不到足夠蛋白質，可能產下較少卵。"},{"en":"The phrase describes reproductive output.","zh":"這個片語描述繁殖產出。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":2},{"front":"keen sense of smell","meaning":"靈敏的嗅覺","examples":[{"en":"Mosquitoes use a keen sense of smell to find blood.","zh":"蚊子使用靈敏的嗅覺尋找血液。"},{"en":"A keen sense of smell is a strong ability to detect scents.","zh":"keen sense of smell 指偵測氣味的強大能力。"},{"en":"Dogs have a keen sense of smell and can find hidden food or drugs.","zh":"狗有靈敏的嗅覺，可以找到藏起來的食物或毒品。"},{"en":"If an animal has a keen sense of smell, it can locate targets from far away.","zh":"如果動物有靈敏嗅覺，就能從遠處定位目標。"},{"en":"The phrase describes powerful scent detection.","zh":"這個片語描述強大的氣味偵測能力。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":2},{"front":"detect sweat","meaning":"偵測汗味","examples":[{"en":"Mosquitoes can detect sweat from mammals.","zh":"蚊子能偵測哺乳動物的汗味。"},{"en":"Detect sweat means sense chemicals or smell from perspiration.","zh":"detect sweat 指感知汗液中的化學物或氣味。"},{"en":"A fitness tracker cannot smell sweat, but animals may detect sweat through scent.","zh":"健身手錶不能聞到汗味，但動物可能透過氣味偵測汗味。"},{"en":"If mosquitoes detect sweat, active people may attract them after exercise.","zh":"如果蚊子能偵測汗味，運動後的人可能吸引牠們。"},{"en":"The phrase describes sensing a body signal.","zh":"這個片語描述感知身體訊號。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":2},{"front":"carbon dioxide","meaning":"二氧化碳","examples":[{"en":"Mosquitoes detect carbon dioxide emitted by mammals.","zh":"蚊子偵測哺乳動物釋放的二氧化碳。"},{"en":"Carbon dioxide is a gas that people and animals breathe out.","zh":"carbon dioxide 是人和動物呼出的氣體。"},{"en":"Plants use carbon dioxide during photosynthesis.","zh":"植物在光合作用中使用二氧化碳。"},{"en":"If mosquitoes sense carbon dioxide, they can follow breathing animals.","zh":"如果蚊子感知二氧化碳，就能追蹤正在呼吸的動物。"},{"en":"The phrase names an important gas in breathing and climate.","zh":"這個片語指呼吸和氣候中的重要氣體。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":2},{"front":"organic compounds","meaning":"有機化合物","examples":[{"en":"Mosquitoes can detect organic compounds from mammals.","zh":"蚊子能偵測來自哺乳動物的有機化合物。"},{"en":"Organic compounds are chemical substances containing carbon, often produced by living things.","zh":"organic compounds 是含碳的化學物質，常由生物產生。"},{"en":"Food smells come from organic compounds released during cooking.","zh":"食物氣味來自烹調期間釋放的有機化合物。"},{"en":"If mosquitoes detect organic compounds from skin, they can locate people more easily.","zh":"如果蚊子偵測到皮膚釋放的有機化合物，就能更容易找到人。"},{"en":"The phrase refers to chemical signals from living bodies.","zh":"這個片語指來自生物身體的化學訊號。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":3},{"front":"emitted by mammals","meaning":"由哺乳動物釋放","examples":[{"en":"Mosquitoes follow compounds emitted by mammals.","zh":"蚊子追蹤由哺乳動物釋放的化合物。"},{"en":"Emitted by mammals means released from the bodies of warm-blooded animals that feed their young with milk.","zh":"emitted by mammals 指由以乳汁哺育幼兒的溫血動物身體釋放。"},{"en":"Carbon dioxide emitted by mammals can signal that a living host is nearby.","zh":"由哺乳動物釋放的二氧化碳可以顯示附近有活宿主。"},{"en":"If a smell is emitted by mammals, insects may use it to locate blood meals.","zh":"如果氣味由哺乳動物釋放，昆蟲可能用它尋找血餐。"},{"en":"The phrase identifies the source of a substance.","zh":"這個片語指出物質的來源。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":3},{"front":"scientific tests have shown that","meaning":"科學測試顯示","examples":[{"en":"Scientific tests have shown that some people attract more mosquitoes than others.","zh":"科學測試顯示，有些人比其他人更吸引蚊子。"},{"en":"Scientific tests have shown that means research evidence has demonstrated something.","zh":"scientific tests have shown that 指研究證據已證明某事。"},{"en":"Scientific tests have shown that handwashing can reduce the spread of many infections.","zh":"科學測試顯示，洗手可以減少許多感染傳播。"},{"en":"If tests show a pattern, personal experience is no longer the only evidence.","zh":"如果測試顯示某種模式，個人經驗就不再是唯一證據。"},{"en":"The phrase introduces a claim supported by experiments or studies.","zh":"這個片語引出由實驗或研究支持的主張。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":3},{"front":"presumably because","meaning":"大概是因為","examples":[{"en":"Some people attract more mosquitoes, presumably because of their scent profile.","zh":"有些人更吸引蚊子，大概是因為他們的氣味特徵。"},{"en":"Presumably because means probably because, although the writer is not completely certain.","zh":"presumably because 指大概是因為，但作者不是完全確定。"},{"en":"The bus is late, presumably because traffic is heavy.","zh":"巴士遲到，大概是因為交通繁忙。"},{"en":"If mosquitoes prefer one person, it is presumably because their smell is more attractive.","zh":"如果蚊子偏好某個人，大概是因為他的氣味更吸引。"},{"en":"The phrase gives a likely explanation with some caution.","zh":"這個片語以較謹慎方式給出可能解釋。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":3},{"front":"scent profile","meaning":"氣味特徵","examples":[{"en":"Some people may have a more attractive scent profile.","zh":"有些人可能有更吸引蚊子的氣味特徵。"},{"en":"A scent profile is the particular mixture of smells a person, object, or place gives off.","zh":"scent profile 指人、物件或地方散發出的特定氣味組合。"},{"en":"A perfume shop describes each perfume’s scent profile using words like floral or woody.","zh":"香水店會用花香或木香等詞描述每款香水的氣味特徵。"},{"en":"If a person’s scent profile attracts mosquitoes, they may be bitten more often.","zh":"如果某人的氣味特徵吸引蚊子，他可能更常被叮。"},{"en":"The phrase describes a pattern of smell.","zh":"這個片語描述氣味模式。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":3},{"front":"be adept at","meaning":"擅長於","examples":[{"en":"Female mosquitoes are adept at following scent trails.","zh":"雌蚊擅長追蹤氣味痕跡。"},{"en":"Be adept at means be very skilled at doing something.","zh":"be adept at 指非常擅長做某事。"},{"en":"A good teacher is adept at explaining difficult ideas with simple examples.","zh":"好老師擅長用簡單例子解釋困難概念。"},{"en":"If mosquitoes are adept at following smells, hiding indoors may not fully protect a person.","zh":"如果蚊子擅長追蹤氣味，躲在室內未必完全保護到人。"},{"en":"The phrase describes strong ability gained by nature, practice, or experience.","zh":"這個片語描述由天性、練習或經驗帶來的強能力。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":3},{"front":"follow trails","meaning":"追蹤痕跡","examples":[{"en":"Mosquitoes can follow scent trails towards their victims.","zh":"蚊子可以追蹤氣味痕跡，移向受害者。"},{"en":"Follow trails means track a path or sign left behind by someone or something.","zh":"follow trails 指追蹤某人或某物留下的路徑或跡象。"},{"en":"Hikers follow trails marked with signs through a forest.","zh":"遠足者沿着有標記的小徑穿過森林。"},{"en":"If insects follow scent trails, they can move toward food or hosts.","zh":"如果昆蟲追蹤氣味痕跡，就能移向食物或宿主。"},{"en":"The phrase describes moving by using clues.","zh":"這個片語描述利用線索前進。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":3},{"front":"infiltrate buildings","meaning":"潛入建築物","examples":[{"en":"Mosquitoes can infiltrate buildings through narrow openings.","zh":"蚊子可以透過狹窄開口潛入建築物。"},{"en":"Infiltrate buildings means enter buildings secretly or gradually through small ways.","zh":"infiltrate buildings 指透過細小通道秘密或逐漸進入建築物。"},{"en":"Rainwater can infiltrate buildings through cracks in the roof.","zh":"雨水可以透過屋頂裂縫滲入建築物。"},{"en":"If mosquitoes infiltrate homes, people may be bitten even indoors.","zh":"如果蚊子潛入住所，人們即使在室內也可能被叮。"},{"en":"The phrase suggests unwanted entry into a protected space.","zh":"這個片語暗示不受歡迎地進入受保護空間。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":3},{"front":"pipeways","meaning":"管道","examples":[{"en":"Mosquitoes can enter buildings through pipeways.","zh":"蚊子可以透過管道進入建築物。"},{"en":"Pipeways are spaces or passages where pipes run through a building.","zh":"pipeways 是建築物中管線穿過的空間或通道。"},{"en":"Maintenance workers may inspect pipeways when checking leaks.","zh":"維修工人檢查漏水時可能查看管道。"},{"en":"If pipeways have gaps, insects may use them as hidden routes indoors.","zh":"如果管道有縫隙，昆蟲可能把它們當作入屋暗道。"},{"en":"The word refers to narrow service passages, not ordinary hallways.","zh":"這個詞指狹窄服務通道，而不是普通走廊。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":3},{"front":"air-conditioning ducts","meaning":"冷氣管道","examples":[{"en":"Mosquitoes can move through air-conditioning ducts.","zh":"蚊子可以經冷氣管道移動。"},{"en":"Air-conditioning ducts are channels that carry cooled or heated air through a building.","zh":"air-conditioning ducts 是把冷氣或暖氣送過建築物的管道。"},{"en":"Dust can collect inside air-conditioning ducts if they are not cleaned.","zh":"如果沒有清潔，灰塵可能積聚在冷氣管道內。"},{"en":"If insects enter air-conditioning ducts, they may reach rooms far from windows.","zh":"如果昆蟲進入冷氣管道，它們可能到達遠離窗戶的房間。"},{"en":"The phrase refers to hidden air passages in buildings.","zh":"這個片語指建築物中的隱藏空氣通道。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":3},{"front":"move inexorably towards","meaning":"不可阻擋地移向……","examples":[{"en":"Mosquitoes move inexorably towards their victims.","zh":"蚊子不可阻擋地移向受害者。"},{"en":"Move inexorably towards means move steadily toward something in a way that seems impossible to stop.","zh":"move inexorably towards 指穩定地朝某物前進，看似無法阻止。"},{"en":"Deadline pressure can move inexorably towards students who keep delaying revision.","zh":"如果學生一直拖延溫習，截止日期壓力會不可阻擋地逼近。"},{"en":"If mosquitoes follow scent signals strongly, they may move inexorably toward a sleeping person.","zh":"如果蚊子強烈追蹤氣味訊號，就可能不可阻擋地飛向熟睡的人。"},{"en":"The phrase suggests steady and unstoppable movement.","zh":"這個片語暗示穩定而難以阻止的移動。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":4},{"front":"upon biting","meaning":"咬下去時","examples":[{"en":"Upon biting, mosquitoes inject saliva into the flesh.","zh":"咬下去時，蚊子把唾液注入皮肉。"},{"en":"Upon biting means at the moment when the bite happens.","zh":"upon biting 指叮咬發生的那一刻。"},{"en":"Upon entering the classroom, students should put their phones away.","zh":"進入課室時，學生應把手機收起。"},{"en":"Upon biting a host, a mosquito begins the process that may transmit disease.","zh":"咬到宿主時，蚊子開始可能傳播疾病的過程。"},{"en":"The phrase is formal and means when something happens.","zh":"這個片語較正式，意思是當某事發生時。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":4},{"front":"inject something into","meaning":"將……注入……","examples":[{"en":"Mosquitoes inject anticoagulant saliva into the flesh.","zh":"蚊子將抗凝血唾液注入皮肉。"},{"en":"Inject something into means put a liquid or substance into a body or material using force or a needle-like part.","zh":"inject something into 指用力量或針狀部位把液體或物質放入身體或材料中。"},{"en":"A nurse may inject medicine into a patient’s arm.","zh":"護士可能將藥物注入病人手臂。"},{"en":"If a mosquito injects saliva into skin, the body may react with itching.","zh":"如果蚊子將唾液注入皮膚，身體可能以痕癢作反應。"},{"en":"The phrase describes putting something inside another thing.","zh":"這個片語描述把某物放入另一物之內。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":4},{"front":"anticoagulant saliva","meaning":"抗凝血唾液","examples":[{"en":"Mosquitoes inject anticoagulant saliva when they bite.","zh":"蚊子叮咬時會注入抗凝血唾液。"},{"en":"Anticoagulant saliva is saliva that stops blood from clotting quickly.","zh":"anticoagulant saliva 是阻止血液快速凝固的唾液。"},{"en":"Doctors use anticoagulant drugs to reduce dangerous blood clots in some patients.","zh":"醫生使用抗凝血藥物減少某些病人的危險血栓。"},{"en":"If mosquito saliva keeps blood flowing, the insect can feed more easily.","zh":"如果蚊子唾液令血液保持流動，昆蟲就能更容易吸血。"},{"en":"The phrase explains why a bite can continue to bleed or itch.","zh":"這個片語解釋為何叮咬可以繼續流血或痕癢。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":4},{"front":"into the flesh","meaning":"注入皮肉","examples":[{"en":"The mosquito injects saliva into the flesh.","zh":"蚊子把唾液注入皮肉。"},{"en":"Into the flesh means into the soft tissue of a person’s or animal’s body.","zh":"into the flesh 指進入人或動物身體的柔軟組織。"},{"en":"A thorn may go into the flesh if someone walks barefoot in a garden.","zh":"如果有人赤腳在花園走，刺可能扎入皮肉。"},{"en":"If something enters the flesh, the immune system may react.","zh":"如果某物進入皮肉，免疫系統可能作出反應。"},{"en":"The phrase sounds physical and direct.","zh":"這個片語聽起來具體而直接。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":4},{"front":"a range of","meaning":"一系列","examples":[{"en":"The fluid may contain a range of viral and parasitic nasties.","zh":"這種液體可能含有一系列病毒和寄生蟲等有害東西。"},{"en":"A range of means several different kinds of something.","zh":"a range of 指幾種不同類型的某物。"},{"en":"A supermarket sells a range of fruits, drinks, and household products.","zh":"超市出售一系列水果、飲品和家居用品。"},{"en":"If a bite carries a range of germs, the health risk becomes more complicated.","zh":"如果叮咬攜帶一系列病菌，健康風險就更複雜。"},{"en":"The phrase emphasises variety.","zh":"這個片語強調種類。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":4},{"front":"viral and parasitic nasties","meaning":"病毒和寄生蟲等有害東西","examples":[{"en":"Mosquito saliva may contain viral and parasitic nasties.","zh":"蚊子唾液可能含有病毒和寄生蟲等有害東西。"},{"en":"Viral and parasitic nasties are harmful viruses or parasites that can cause disease.","zh":"viral and parasitic nasties 指可造成疾病的有害病毒或寄生蟲。"},{"en":"Dirty water may contain bacterial and parasitic nasties that make people ill.","zh":"骯髒食水可能含有細菌和寄生蟲等有害東西，使人生病。"},{"en":"If mosquitoes carry such nasties, a small bite can become dangerous.","zh":"如果蚊子攜帶這些有害東西，小小叮咬也可能變危險。"},{"en":"The phrase is informal and makes disease agents sound unpleasant.","zh":"這個片語較口語，令病原體聽起來令人厭惡。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":4},{"front":"be notorious for","meaning":"因……而臭名昭著","examples":[{"en":"Mosquitoes are notorious for spreading diseases.","zh":"蚊子因傳播疾病而臭名昭著。"},{"en":"Be notorious for means be widely known for something bad.","zh":"be notorious for 指因壞事而廣為人知。"},{"en":"The road is notorious for accidents because drivers often speed there.","zh":"這條路因意外而臭名昭著，因為司機常在那裡超速。"},{"en":"If a place is notorious for mosquitoes, travellers may bring repellent.","zh":"如果某地方因蚊子而臭名昭著，旅客可能帶備驅蚊劑。"},{"en":"The phrase is negative and stronger than famous for.","zh":"這個片語是負面的，比 famous for 更強烈。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":4},{"front":"even without","meaning":"即使沒有","examples":[{"en":"Even without such diseases, mosquitoes are an irritating nuisance.","zh":"即使沒有這類疾病，蚊子仍是令人煩厭的滋擾。"},{"en":"Even without means still true although something is absent.","zh":"even without 指即使缺少某事，情況仍然成立。"},{"en":"Even without heavy rain, the road can become slippery.","zh":"即使沒有大雨，這條路也可能變得濕滑。"},{"en":"If mosquitoes do not spread disease, they can still disturb sleep and comfort.","zh":"如果蚊子不傳播疾病，牠們仍可打擾睡眠和舒適。"},{"en":"The phrase shows that one problem remains without another.","zh":"這個片語顯示即使沒有另一問題，某問題仍存在。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":4},{"front":"irritating nuisance","meaning":"令人煩厭的滋擾","examples":[{"en":"Mosquitoes are an irritating nuisance even when they do not spread disease.","zh":"即使蚊子不傳播疾病，牠們仍是令人煩厭的滋擾。"},{"en":"An irritating nuisance is something annoying that repeatedly disturbs people.","zh":"irritating nuisance 指反覆打擾人的煩厭事物。"},{"en":"A dripping tap can be an irritating nuisance at night.","zh":"夜間滴水的水龍頭可以是令人煩厭的滋擾。"},{"en":"If small problems happen constantly, they can become a major nuisance.","zh":"如果小問題不斷發生，它們可以變成重大滋擾。"},{"en":"The phrase describes annoyance rather than serious danger.","zh":"這個片語描述煩擾，而不是嚴重危險。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":4},{"front":"cause serious injury","meaning":"造成嚴重傷害","examples":[{"en":"Mosquito bites can occasionally cause serious injury.","zh":"蚊叮有時可以造成嚴重傷害。"},{"en":"Cause serious injury means lead to major physical harm.","zh":"cause serious injury 指導致重大的身體傷害。"},{"en":"A fall from a bicycle can cause serious injury if a rider hits their head.","zh":"如果騎單車者撞到頭，跌倒可以造成嚴重傷害。"},{"en":"If a bite becomes infected, it may cause more damage than expected.","zh":"如果叮咬受感染，它造成的傷害可能超出預期。"},{"en":"The phrase describes harmful consequences to the body.","zh":"這個片語描述對身體的有害後果。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":5},{"front":"upon being bitten","meaning":"被叮咬時","examples":[{"en":"Upon being bitten, the body’s immune system is activated.","zh":"被叮咬時，身體的免疫系統會被啟動。"},{"en":"Upon being bitten means when a person or animal is bitten.","zh":"upon being bitten 指人或動物被咬或叮的時候。"},{"en":"Upon being bitten by a dog, a child should receive medical attention.","zh":"孩子被狗咬時，應接受醫療處理。"},{"en":"If the body reacts upon being bitten, swelling or itching may follow.","zh":"如果身體在被叮咬時作出反應，之後可能腫脹或痕癢。"},{"en":"The phrase is formal and introduces the moment of the bite.","zh":"這個片語較正式，引出被咬的一刻。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":5},{"front":"immune system","meaning":"免疫系統","examples":[{"en":"The body’s immune system reacts to mosquito bites.","zh":"身體的免疫系統會對蚊叮作出反應。"},{"en":"The immune system is the body’s defence system against infection and harmful substances.","zh":"immune system 是身體抵抗感染和有害物質的防禦系統。"},{"en":"Good sleep and nutrition help support the immune system.","zh":"良好睡眠和營養有助支持免疫系統。"},{"en":"If the immune system overreacts, a small bite may become very swollen.","zh":"如果免疫系統反應過度，小小叮咬也可能腫得很厲害。"},{"en":"The phrase refers to the body’s protective response.","zh":"這個片語指身體的保護反應。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":5},{"front":"be activated","meaning":"被啟動","examples":[{"en":"The immune system is activated after a mosquito bite.","zh":"蚊叮後，免疫系統會被啟動。"},{"en":"Be activated means be switched on or made to start working.","zh":"be activated 指被開啟或被促使開始運作。"},{"en":"A school alarm is activated when smoke is detected.","zh":"偵測到煙霧時，學校警報會被啟動。"},{"en":"If the immune system is activated, redness and swelling may appear.","zh":"如果免疫系統被啟動，可能出現紅腫。"},{"en":"The phrase describes something beginning to function.","zh":"這個片語描述某物開始發揮功能。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":5},{"front":"subsequent bites","meaning":"其後的叮咬","examples":[{"en":"Subsequent bites may trigger a stronger reaction.","zh":"其後的叮咬可能觸發更強反應。"},{"en":"Subsequent bites are bites that happen later, after earlier ones.","zh":"subsequent bites 指早前叮咬之後發生的叮咬。"},{"en":"A child may ignore the first insect bite but react badly to subsequent bites.","zh":"孩子可能忽略第一個昆蟲叮咬，但對其後叮咬反應嚴重。"},{"en":"If the body becomes sensitive, later bites can cause more itching.","zh":"如果身體變得敏感，後來叮咬可以造成更多痕癢。"},{"en":"The phrase focuses on what happens after the first bite.","zh":"這個片語集中於第一次叮咬之後發生的事情。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":5},{"front":"trigger antibodies","meaning":"觸發抗體","examples":[{"en":"Subsequent bites trigger antibodies in the body.","zh":"其後的叮咬會觸發身體中的抗體。"},{"en":"Trigger antibodies means cause the body to produce or activate immune proteins.","zh":"trigger antibodies 指促使身體產生或啟動免疫蛋白。"},{"en":"A vaccine can trigger antibodies that help fight future infection.","zh":"疫苗可以觸發抗體，幫助對抗未來感染。"},{"en":"If repeated bites trigger antibodies, the body may react more strongly each time.","zh":"如果反覆叮咬觸發抗體，身體每次反應可能更強。"},{"en":"The phrase describes an immune response being started.","zh":"這個片語描述免疫反應被啟動。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":5},{"front":"inflammation and itching","meaning":"發炎和痕癢","examples":[{"en":"Mosquito bites can cause inflammation and itching.","zh":"蚊叮可以造成發炎和痕癢。"},{"en":"Inflammation and itching mean swelling, redness, heat, and an urge to scratch.","zh":"inflammation and itching 指腫脹、發紅、發熱和想抓的感覺。"},{"en":"A skin allergy may cause inflammation and itching after contact with soap.","zh":"皮膚敏感接觸肥皂後可能造成發炎和痕癢。"},{"en":"If bites cause inflammation and itching, scratching can make the skin worse.","zh":"如果叮咬造成發炎和痕癢，抓損會令皮膚更差。"},{"en":"The phrase describes common skin reactions.","zh":"這個片語描述常見皮膚反應。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":5},{"front":"particularly in","meaning":"尤其在……之中","examples":[{"en":"Inflammation and itching may be worse, particularly in young children.","zh":"發炎和痕癢可能更嚴重，尤其在幼童之中。"},{"en":"Particularly in means especially among or within a certain group.","zh":"particularly in 指尤其在某個群體或範圍之中。"},{"en":"Flu can spread quickly, particularly in crowded classrooms.","zh":"流感可以迅速傳播，尤其在擠迫課室中。"},{"en":"If a problem is worse particularly in children, adults should watch symptoms carefully.","zh":"如果問題尤其在兒童中更嚴重，成人應仔細留意症狀。"},{"en":"The phrase highlights a group where something is especially true.","zh":"這個片語突出某事特別成立的群體。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":5},{"front":"increase sensitivity","meaning":"增加敏感程度","examples":[{"en":"More bites can increase sensitivity to mosquito saliva.","zh":"更多叮咬可以增加對蚊子唾液的敏感程度。"},{"en":"Increase sensitivity means make the body react more strongly to something.","zh":"increase sensitivity 指令身體對某物反應更強。"},{"en":"Repeated skin contact with a harsh soap can increase sensitivity.","zh":"皮膚反覆接觸刺激性肥皂可以增加敏感程度。"},{"en":"If sensitivity increases, a small bite may cause a larger reaction.","zh":"如果敏感程度增加，小小叮咬也可能造成較大反應。"},{"en":"The phrase describes becoming more reactive.","zh":"這個片語描述變得更易反應。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":5},{"front":"result in","meaning":"導致","examples":[{"en":"Repeated bites can result in swelling and blistering.","zh":"反覆叮咬可以導致腫脹和起水泡。"},{"en":"Result in means cause something to happen.","zh":"result in 指造成某事發生。"},{"en":"Poor sleep can result in weak concentration the next day.","zh":"睡眠不足可以導致翌日專注力差。"},{"en":"If bites result in swelling, the skin may feel tight and painful.","zh":"如果叮咬導致腫脹，皮膚可能感到繃緊和疼痛。"},{"en":"The phrase links cause and effect.","zh":"這個片語連接原因和結果。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":5},{"front":"pronounced swelling","meaning":"明顯腫脹","examples":[{"en":"Mosquito bites may result in pronounced swelling.","zh":"蚊叮可能導致明顯腫脹。"},{"en":"Pronounced swelling is swelling that is clear, strong, and easy to see.","zh":"pronounced swelling 是清楚、強烈且容易看見的腫脹。"},{"en":"After a sprained ankle, pronounced swelling may make walking difficult.","zh":"扭傷腳踝後，明顯腫脹可能令走路困難。"},{"en":"If a bite causes pronounced swelling, medical advice may be needed.","zh":"如果叮咬造成明顯腫脹，可能需要醫療建議。"},{"en":"The phrase describes swelling that is more than mild.","zh":"這個片語描述不只是輕微的腫脹。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":6},{"front":"blistering","meaning":"起水泡","examples":[{"en":"Some mosquito bites can lead to blistering.","zh":"有些蚊叮可以導致起水泡。"},{"en":"Blistering means the formation of small fluid-filled bubbles on the skin.","zh":"blistering 指皮膚上形成充滿液體的小泡。"},{"en":"New shoes can cause blistering on the heel after a long walk.","zh":"長時間步行後，新鞋可以令腳跟起水泡。"},{"en":"If skin blisters after a bite, the area should be kept clean.","zh":"如果皮膚被叮後起水泡，該部位應保持清潔。"},{"en":"The word describes a visible skin reaction.","zh":"這個詞描述可見的皮膚反應。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":6},{"front":"wounds","meaning":"傷口","examples":[{"en":"Blistering can create wounds that may become infected.","zh":"起水泡可以造成可能受感染的傷口。"},{"en":"Wounds are injuries where skin or tissue is broken.","zh":"wounds 是皮膚或組織破損的傷害。"},{"en":"A small kitchen cut is a wound that should be washed properly.","zh":"廚房中的小割傷是應妥善清洗的傷口。"},{"en":"If wounds are scratched or dirty, infection becomes more likely.","zh":"如果傷口被抓損或弄髒，就更可能感染。"},{"en":"The word refers to damaged body tissue.","zh":"這個詞指受損的身體組織。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":6},{"front":"become infected","meaning":"受感染","examples":[{"en":"Wounds can occasionally become infected when scratched.","zh":"傷口被抓損時偶爾會受感染。"},{"en":"Become infected means germs enter and cause illness or inflammation.","zh":"become infected 指病菌進入並造成疾病或發炎。"},{"en":"A cut can become infected if it is not cleaned and covered.","zh":"如果割傷沒有清洗和包好，可能受感染。"},{"en":"If a mosquito bite becomes infected, it may become painful, red, or swollen.","zh":"如果蚊叮受感染，它可能變得疼痛、發紅或腫脹。"},{"en":"The phrase describes a wound changing from minor to medically risky.","zh":"這個片語描述傷口由輕微變成有醫療風險。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":6},{"front":"when scratched","meaning":"被抓損時","examples":[{"en":"Wounds may become infected when scratched.","zh":"傷口被抓損時可能受感染。"},{"en":"When scratched means when someone rubs or tears the skin with nails or a rough surface.","zh":"when scratched 指用指甲或粗糙表面摩擦或弄破皮膚時。"},{"en":"A rash may bleed when scratched too hard.","zh":"如果皮疹被太用力抓損，可能流血。"},{"en":"If mosquito bites are scratched, bacteria can enter broken skin.","zh":"如果蚊叮被抓損，細菌可以進入破皮。"},{"en":"The phrase explains a condition that can make infection more likely.","zh":"這個片語解釋令感染更可能發生的情況。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":6},{"front":"famous victims of","meaning":"……的著名受害者","examples":[{"en":"Lord Carnarvon and Rupert Brooke were famous victims of infected mosquito bites.","zh":"Lord Carnarvon 和 Rupert Brooke 是受感染蚊叮的著名受害者。"},{"en":"Famous victims of means well-known people harmed or killed by something.","zh":"famous victims of 指因某事受害或死亡的知名人物。"},{"en":"History lessons sometimes mention famous victims of wars, disasters, or diseases.","zh":"歷史課有時會提及戰爭、災難或疾病的著名受害者。"},{"en":"If a disease has famous victims, people may remember its danger more easily.","zh":"如果疾病有著名受害者，人們可能更容易記住其危險。"},{"en":"The phrase links well-known names with a harmful cause.","zh":"這個片語把知名名字與有害原因連接起來。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":6},{"front":"infected mosquito bites","meaning":"受感染的蚊叮","examples":[{"en":"Infected mosquito bites killed two famous historical figures.","zh":"受感染的蚊叮殺死了兩位著名歷史人物。"},{"en":"Infected mosquito bites are bites that have become contaminated with germs.","zh":"infected mosquito bites 是被病菌污染的蚊叮傷口。"},{"en":"A scratched mosquito bite can become infected if bacteria enter the skin.","zh":"如果細菌進入皮膚，被抓損的蚊叮可以受感染。"},{"en":"If infected bites are untreated, they may cause serious complications.","zh":"如果受感染叮咬沒有治療，可能造成嚴重併發症。"},{"en":"The phrase describes a bite that has become medically dangerous.","zh":"這個片語描述變得有醫療危險的叮咬。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":6},{"front":"Egyptologist","meaning":"埃及學家","examples":[{"en":"Lord Carnarvon was an Egyptologist.","zh":"Lord Carnarvon 是一位埃及學家。"},{"en":"An Egyptologist is a scholar who studies ancient Egypt.","zh":"Egyptologist 是研究古埃及的學者。"},{"en":"An Egyptologist may study tombs, hieroglyphs, temples, and mummies.","zh":"埃及學家可能研究陵墓、象形文字、神廟和木乃伊。"},{"en":"If an Egyptologist joins an excavation, they help interpret ancient objects.","zh":"如果埃及學家參與考古發掘，他們幫助解讀古物。"},{"en":"The word refers to an academic specialist.","zh":"這個詞指學術專家。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":6},{"front":"play a role in","meaning":"在……中扮演角色","examples":[{"en":"Lord Carnarvon played a role in the discovery of Tutankhamun’s tomb.","zh":"Lord Carnarvon 在圖坦卡門陵墓的發現中扮演角色。"},{"en":"Play a role in means contribute to or be involved in something.","zh":"play a role in 指對某事作出貢獻或參與其中。"},{"en":"Parents play a role in helping children build study habits.","zh":"家長在幫助孩子建立學習習慣中扮演角色。"},{"en":"If mosquitoes play a role in disease spread, controlling them matters.","zh":"如果蚊子在疾病傳播中扮演角色，控制牠們就很重要。"},{"en":"The phrase describes participation or influence.","zh":"這個片語描述參與或影響。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":6},{"front":"the discovery of","meaning":"……的發現","examples":[{"en":"He played a role in the discovery of Tutankhamun’s tomb.","zh":"他在圖坦卡門陵墓的發現中扮演角色。"},{"en":"The discovery of something is the act of finding it for the first time or making it known.","zh":"the discovery of 指首次找到某物或使其為人所知的行動。"},{"en":"The discovery of a new medicine can change hospital treatment.","zh":"新藥的發現可以改變醫院治療。"},{"en":"If a discovery is important, it may attract scientists, historians, or reporters.","zh":"如果一項發現很重要，它可能吸引科學家、歷史學家或記者。"},{"en":"The phrase focuses on finding or revealing something.","zh":"這個片語集中於找到或揭示某事物。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":6},{"front":"respectively","meaning":"分別地","examples":[{"en":"They died in Egypt and Greece, respectively.","zh":"他們分別死於埃及和希臘。"},{"en":"Respectively means in the same order as the people or things just mentioned.","zh":"respectively 指按照剛提及的人或事物的相同次序。"},{"en":"Anna and Ben scored 80 and 90 respectively.","zh":"Anna 和 Ben 分別取得80分和90分。"},{"en":"If two names and two places are listed respectively, the first place belongs to the first name.","zh":"如果兩個名字和兩個地方按 respectively 列出，第一個地方屬於第一個名字。"},{"en":"The word prevents confusion in paired information.","zh":"這個詞防止配對資料混亂。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":7},{"front":"the real danger","meaning":"真正的危險","examples":[{"en":"The real danger is mosquito-borne disease.","zh":"真正的危險是蚊媒疾病。"},{"en":"The real danger means the most serious risk, not the obvious or minor problem.","zh":"the real danger 指最嚴重風險，而不是明顯或較小問題。"},{"en":"In a fire, the real danger may be smoke, not flames alone.","zh":"在火災中，真正的危險可能是煙，而不只是火焰。"},{"en":"If mosquitoes are annoying, the real danger is still the diseases they carry.","zh":"即使蚊子令人煩厭，真正危險仍是牠們攜帶的疾病。"},{"en":"The phrase redirects attention to the main threat.","zh":"這個片語把注意力轉向主要威脅。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":7},{"front":"mosquito-borne diseases","meaning":"蚊媒疾病","examples":[{"en":"Mosquito-borne diseases are the greatest threat.","zh":"蚊媒疾病是最大的威脅。"},{"en":"Mosquito-borne diseases are illnesses spread through mosquito bites.","zh":"mosquito-borne diseases 是透過蚊叮傳播的疾病。"},{"en":"Travellers may need vaccines or medicine before visiting areas with mosquito-borne diseases.","zh":"旅客到訪有蚊媒疾病地區前，可能需要疫苗或藥物。"},{"en":"If mosquitoes increase after heavy rain, mosquito-borne disease risk may rise.","zh":"如果大雨後蚊子增加，蚊媒疾病風險可能上升。"},{"en":"The phrase identifies diseases carried by mosquitoes.","zh":"這個片語指出由蚊子攜帶的疾病。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":7},{"front":"Dengue fever","meaning":"登革熱","examples":[{"en":"Dengue fever is a mosquito-borne disease.","zh":"登革熱是一種蚊媒疾病。"},{"en":"Dengue fever is a viral illness spread by certain mosquitoes.","zh":"Dengue fever 是由某些蚊子傳播的病毒性疾病。"},{"en":"Public health notices may warn residents about Dengue fever after heavy rain.","zh":"大雨後，公共健康通知可能警告居民登革熱風險。"},{"en":"If standing water is not removed, the risk of Dengue fever can increase.","zh":"如果積水沒有清除，登革熱風險可能增加。"},{"en":"The phrase names a serious tropical disease.","zh":"這個片語指一種嚴重熱帶疾病。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":7},{"front":"West Nile virus","meaning":"西尼羅河病毒","examples":[{"en":"West Nile virus is one of the diseases spread by mosquitoes.","zh":"西尼羅河病毒是蚊子傳播的疾病之一。"},{"en":"West Nile virus is a virus that can infect humans through mosquito bites.","zh":"West Nile virus 是可透過蚊叮感染人類的病毒。"},{"en":"Health departments may test mosquitoes for West Nile virus in summer.","zh":"衞生部門可能在夏季檢測蚊子是否帶有西尼羅河病毒。"},{"en":"If infected mosquitoes bite people, West Nile virus may spread in a community.","zh":"如果受感染蚊子叮咬人，西尼羅河病毒可能在社區傳播。"},{"en":"The phrase names a mosquito-borne virus.","zh":"這個片語指一種蚊媒病毒。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":7},{"front":"encephalitis-type diseases","meaning":"腦炎類疾病","examples":[{"en":"Several encephalitis-type diseases are modern-day killers.","zh":"幾種腦炎類疾病是現代殺手。"},{"en":"Encephalitis-type diseases are illnesses involving inflammation of the brain or similar serious nervous-system effects.","zh":"encephalitis-type diseases 指涉及腦部發炎或類似嚴重神經系統影響的疾病。"},{"en":"Doctors treat encephalitis-type diseases urgently because brain swelling can be dangerous.","zh":"醫生會緊急治療腦炎類疾病，因為腦部腫脹可能很危險。"},{"en":"If mosquitoes spread encephalitis-type diseases, bites can lead to severe illness.","zh":"如果蚊子傳播腦炎類疾病，叮咬可能導致重病。"},{"en":"The phrase describes brain-related infectious diseases.","zh":"這個片語描述與腦部相關的傳染病。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":7},{"front":"modern-day killers","meaning":"現代殺手","examples":[{"en":"Dengue fever and West Nile virus are modern-day killers.","zh":"登革熱和西尼羅河病毒是現代殺手。"},{"en":"Modern-day killers are present-day diseases or dangers that still cause deaths.","zh":"modern-day killers 指今日仍造成死亡的疾病或危險。"},{"en":"Road accidents are modern-day killers in many busy cities.","zh":"在許多繁忙城市，道路意外是現代殺手。"},{"en":"If a disease remains a modern-day killer, prevention still matters today.","zh":"如果疾病仍是現代殺手，今日仍需要預防。"},{"en":"The phrase stresses that the danger is not only historical.","zh":"這個片語強調危險不只是歷史性的。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":7},{"front":"less deadly but more insidious","meaning":"較不致命但更隱伏難察","examples":[{"en":"Filariasis is less deadly but more insidious.","zh":"絲蟲病較不致命但更隱伏難察。"},{"en":"Less deadly but more insidious means it kills fewer people but causes hidden, slow, or long-term harm.","zh":"less deadly but more insidious 指死亡人數較少，但造成隱藏、緩慢或長期傷害。"},{"en":"A quiet workplace problem may be less dramatic but more insidious than one open argument.","zh":"安靜的職場問題可能比公開爭吵較不戲劇化，但更隱伏難察。"},{"en":"If a disease damages slowly, people may ignore it until it becomes severe.","zh":"如果疾病緩慢傷害，人們可能忽視它，直到變得嚴重。"},{"en":"The phrase contrasts immediate death with hidden harm.","zh":"這個片語把即時死亡與隱藏傷害作對比。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":7},{"front":"filariasis","meaning":"絲蟲病","examples":[{"en":"Filariasis can cause severe swelling of body parts.","zh":"絲蟲病可以造成身體部位嚴重腫脹。"},{"en":"Filariasis is a parasitic disease spread by mosquitoes and affecting the lymphatic system.","zh":"filariasis 是由蚊子傳播、影響淋巴系統的寄生蟲病。"},{"en":"Health workers may teach communities how to prevent filariasis by reducing mosquito bites.","zh":"衞生工作者可能教社區如何透過減少蚊叮預防絲蟲病。"},{"en":"If filariasis damages lymph flow, limbs can become badly swollen.","zh":"如果絲蟲病損害淋巴流動，四肢可能嚴重腫脹。"},{"en":"The word names a disease that can cause long-term disability.","zh":"這個詞指一種可造成長期殘疾的疾病。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":7},{"front":"be named after","meaning":"以……命名","examples":[{"en":"Filariasis is named after thread-like parasites.","zh":"絲蟲病以線狀寄生蟲命名。"},{"en":"Be named after means receive a name because of a person, place, feature, or cause.","zh":"be named after 指因某人、地方、特徵或原因而得到名稱。"},{"en":"A school may be named after a respected teacher.","zh":"學校可能以一位受尊敬老師命名。"},{"en":"If a disease is named after its parasite, the name gives a clue to its cause.","zh":"如果疾病以其寄生蟲命名，名稱就提供病因線索。"},{"en":"The phrase explains the origin of a name.","zh":"這個片語解釋名稱來源。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":7},{"front":"thread-like parasites","meaning":"線狀寄生蟲","examples":[{"en":"Filariasis is caused by thread-like parasites.","zh":"絲蟲病由線狀寄生蟲造成。"},{"en":"Thread-like parasites are thin worm-like organisms that live in or on another organism.","zh":"thread-like parasites 是細長如線、寄生在其他生物體內或表面的生物。"},{"en":"Doctors may look for thread-like parasites under a microscope.","zh":"醫生可能在顯微鏡下尋找線狀寄生蟲。"},{"en":"If parasites are thread-like, they may move through narrow parts of the body.","zh":"如果寄生蟲呈線狀，它們可能穿過身體狹窄部位。"},{"en":"The phrase describes shape and biological behaviour.","zh":"這個片語描述形狀和生物行為。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":8},{"front":"migrate to","meaning":"遷移至","examples":[{"en":"The parasites migrate to the body’s lymphatic system.","zh":"寄生蟲遷移至身體的淋巴系統。"},{"en":"Migrate to means move from one place to another, often gradually or seasonally.","zh":"migrate to 指從一個地方移到另一個地方，常是逐步或季節性。"},{"en":"Birds migrate to warmer regions in winter.","zh":"鳥類冬天會遷移至較暖地區。"},{"en":"If parasites migrate to a body system, they can damage it from inside.","zh":"如果寄生蟲遷移至身體系統，就可從內部造成損害。"},{"en":"The phrase describes movement toward a destination.","zh":"這個片語描述向目的地移動。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":8},{"front":"lymphatic system","meaning":"淋巴系統","examples":[{"en":"The parasites move to the body’s lymphatic system.","zh":"寄生蟲移到身體的淋巴系統。"},{"en":"The lymphatic system is a body system that helps move fluid and support immunity.","zh":"lymphatic system 是幫助運送體液並支持免疫功能的身體系統。"},{"en":"Doctors may check the lymphatic system when a patient has swollen glands.","zh":"當病人淋巴腺腫脹時，醫生可能檢查淋巴系統。"},{"en":"If the lymphatic system is blocked, body parts can swell.","zh":"如果淋巴系統被阻塞，身體部位可能腫脹。"},{"en":"The phrase refers to an important fluid and immune network.","zh":"這個片語指重要的體液和免疫網絡。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":8},{"front":"permanently swell","meaning":"永久腫脹","examples":[{"en":"Filariasis can cause parts of the body to permanently swell.","zh":"絲蟲病可使身體部位永久腫脹。"},{"en":"Permanently swell means become enlarged and stay that way for a long time or forever.","zh":"permanently swell 指變大並長期或永久保持腫脹。"},{"en":"A badly injured joint may permanently swell if it does not heal properly.","zh":"如果嚴重受傷的關節沒有正常康復，可能永久腫脹。"},{"en":"If lymph flow is blocked, an arm or leg may remain swollen.","zh":"如果淋巴流動受阻，手臂或腿可能持續腫脹。"},{"en":"The phrase describes lasting physical enlargement.","zh":"這個片語描述持久的身體增大。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":8},{"front":"grotesque proportions","meaning":"畸形可怕的程度","examples":[{"en":"Some body parts may swell to grotesque proportions.","zh":"有些身體部位可能腫脹至畸形可怕的程度。"},{"en":"Grotesque proportions means an unnatural, shocking, or disturbing size.","zh":"grotesque proportions 指不自然、驚人或令人不安的大小。"},{"en":"A cartoon may draw a villain’s head in grotesque proportions for effect.","zh":"卡通可能把反派頭部畫成畸形可怕的比例以製造效果。"},{"en":"If disease causes swelling to grotesque proportions, daily movement can become difficult.","zh":"如果疾病造成畸形程度的腫脹，日常活動可能變得困難。"},{"en":"The phrase describes extreme and unpleasant size.","zh":"這個片語描述極端而令人不適的大小。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":8},{"front":"as distressing as","meaning":"儘管……令人痛苦","examples":[{"en":"As distressing as filariasis is, malaria has a higher death toll.","zh":"儘管絲蟲病令人痛苦，瘧疾的死亡人數更高。"},{"en":"As distressing as means although something is very upsetting or painful.","zh":"as distressing as 指雖然某事非常令人難過或痛苦。"},{"en":"As distressing as a failed exam is, it can still become a chance to improve.","zh":"儘管考試失敗令人痛苦，它仍可成為進步機會。"},{"en":"If one illness is distressing but another kills more people, the comparison changes focus.","zh":"如果一種病令人痛苦，但另一種殺死更多人，比較焦點就會改變。"},{"en":"The phrase admits one serious point before making another.","zh":"這個片語先承認一個嚴重點，再提出另一點。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":8},{"front":"in terms of its death toll","meaning":"就死亡人數而言","examples":[{"en":"In terms of its death toll, malaria is the worst mosquito-borne disease.","zh":"就死亡人數而言，瘧疾是最嚴重的蚊媒疾病。"},{"en":"In terms of its death toll means judging by the number of deaths it causes.","zh":"in terms of its death toll 指按其造成的死亡人數判斷。"},{"en":"In terms of cost, the bus is better than the taxi.","zh":"就成本而言，巴士比的士更好。"},{"en":"If diseases are compared by death toll, the most fatal one ranks highest.","zh":"如果按死亡人數比較疾病，最致命者排名最高。"},{"en":"The phrase states the measure used for comparison.","zh":"這個片語說明比較所用的標準。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":8},{"front":"undoubtedly","meaning":"毫無疑問地","examples":[{"en":"Malaria is undoubtedly the worst disease spread by mosquitoes.","zh":"瘧疾毫無疑問是蚊子傳播的最嚴重疾病。"},{"en":"Undoubtedly means without doubt or almost certainly.","zh":"undoubtedly 指沒有疑問或幾乎肯定。"},{"en":"She is undoubtedly the most experienced teacher in the department.","zh":"她毫無疑問是部門中最有經驗的老師。"},{"en":"If evidence is overwhelming, a writer may use undoubtedly to show strong confidence.","zh":"如果證據壓倒性，作者可能使用 undoubtedly 表示強烈信心。"},{"en":"The word signals certainty.","zh":"這個詞標示確定性。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":8},{"front":"malaria","meaning":"瘧疾","examples":[{"en":"Malaria is carried by the Anopheles mosquito.","zh":"瘧疾由按蚊攜帶。"},{"en":"Malaria is a serious disease caused by parasites and spread by mosquitoes.","zh":"malaria 是由寄生蟲造成並由蚊子傳播的嚴重疾病。"},{"en":"Travellers to malaria-risk areas may need preventive medicine.","zh":"前往瘧疾高風險地區的旅客可能需要預防藥物。"},{"en":"If malaria is not treated, it can become fatal.","zh":"如果瘧疾沒有治療，可能致命。"},{"en":"The word names one of the most dangerous mosquito-borne diseases.","zh":"這個詞指最危險的蚊媒疾病之一。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":8},{"front":"carried by","meaning":"由……攜帶","examples":[{"en":"Malaria is carried by the Anopheles mosquito.","zh":"瘧疾由按蚊攜帶。"},{"en":"Carried by means transported or spread by a person, animal, insect, or object.","zh":"carried by 指由人、動物、昆蟲或物件攜帶或傳播。"},{"en":"Some infections are carried by dirty water.","zh":"有些感染由骯髒食水攜帶。"},{"en":"If a disease is carried by mosquitoes, preventing bites can reduce infection.","zh":"如果疾病由蚊子攜帶，預防叮咬可以減少感染。"},{"en":"The phrase identifies the carrier of a disease or substance.","zh":"這個片語指出疾病或物質的攜帶者。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":8},{"front":"Anopheles mosquito","meaning":"按蚊","examples":[{"en":"The Anopheles mosquito carries the malaria parasite.","zh":"按蚊攜帶瘧疾寄生蟲。"},{"en":"Anopheles mosquito is a type of mosquito that can transmit malaria.","zh":"Anopheles mosquito 是可傳播瘧疾的一類蚊子。"},{"en":"Health workers monitor Anopheles mosquitoes in areas where malaria is common.","zh":"在瘧疾常見地區，衞生工作者會監察按蚊。"},{"en":"If Anopheles mosquitoes breed near homes, malaria risk may increase.","zh":"如果按蚊在住宅附近繁殖，瘧疾風險可能增加。"},{"en":"The phrase names the mosquito group linked to malaria.","zh":"這個片語指與瘧疾相關的蚊子類群。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":9},{"front":"parasite","meaning":"寄生蟲","examples":[{"en":"The malaria parasite can cause fever and joint pains.","zh":"瘧疾寄生蟲可以造成發燒和關節痛。"},{"en":"A parasite is an organism that lives on or inside another organism and takes resources from it.","zh":"parasite 是生活在另一生物體表或體內並從其取得資源的生物。"},{"en":"Fleas are parasites because they feed on the blood of animals.","zh":"跳蚤是寄生蟲，因為牠們吸食動物血液。"},{"en":"If a parasite enters the body, it may damage tissues or cause illness.","zh":"如果寄生蟲進入身體，可能損害組織或造成疾病。"},{"en":"The word describes a living organism that depends on a host.","zh":"這個詞描述依賴宿主生活的生物。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":9},{"front":"fever and shivering","meaning":"發燒和發冷","examples":[{"en":"Malaria can cause fever and shivering.","zh":"瘧疾可以造成發燒和發冷。"},{"en":"Fever and shivering mean high body temperature together with shaking from chills.","zh":"fever and shivering 指體溫高並因寒冷感而顫抖。"},{"en":"A child with flu may have fever and shivering during the night.","zh":"患流感的孩子夜間可能發燒和發冷。"},{"en":"If fever and shivering appear after travel, doctors may ask about mosquito exposure.","zh":"如果旅行後出現發燒和發冷，醫生可能詢問是否接觸過蚊子。"},{"en":"The phrase describes common signs of infection.","zh":"這個片語描述感染的常見徵狀。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":9},{"front":"joint pains","meaning":"關節痛","examples":[{"en":"Malaria can cause joint pains and vomiting.","zh":"瘧疾可以造成關節痛和嘔吐。"},{"en":"Joint pains are aches or discomfort in places where bones meet, such as knees or elbows.","zh":"joint pains 是膝蓋或手肘等骨頭連接處的疼痛或不適。"},{"en":"After a long hike, a person may feel joint pains in the knees.","zh":"長途遠足後，一個人可能感到膝蓋關節痛。"},{"en":"If a disease causes joint pains, movement may become uncomfortable.","zh":"如果疾病造成關節痛，活動可能變得不舒服。"},{"en":"The phrase describes pain in body joints.","zh":"這個片語描述身體關節疼痛。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":9},{"front":"vomiting","meaning":"嘔吐","examples":[{"en":"Vomiting is one of the symptoms of malaria.","zh":"嘔吐是瘧疾的症狀之一。"},{"en":"Vomiting means forcing food or liquid out of the stomach through the mouth.","zh":"vomiting 指食物或液體從胃部經口中被迫排出。"},{"en":"Food poisoning can cause vomiting within a few hours.","zh":"食物中毒可在數小時內造成嘔吐。"},{"en":"If vomiting continues, a patient may become dehydrated.","zh":"如果嘔吐持續，病人可能脫水。"},{"en":"The word describes a physical symptom, not just feeling sick.","zh":"這個詞描述身體症狀，而不只是覺得不舒服。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":9},{"front":"if left untreated","meaning":"如不治療","examples":[{"en":"If left untreated, malaria can lead to a painful death.","zh":"如不治療，瘧疾可以導致痛苦死亡。"},{"en":"If left untreated means if no medical treatment is given.","zh":"if left untreated 指如果沒有接受醫療處理。"},{"en":"A small wound can become infected if left untreated.","zh":"小傷口如不治療，可能受感染。"},{"en":"If a serious disease is left untreated, the risk of death may rise.","zh":"如果嚴重疾病不治療，死亡風險可能上升。"},{"en":"The phrase warns about what happens without care.","zh":"這個片語警告缺乏護理的後果。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":9},{"front":"painful death","meaning":"痛苦的死亡","examples":[{"en":"Untreated malaria can cause a painful death.","zh":"未經治療的瘧疾可以造成痛苦的死亡。"},{"en":"A painful death is a death involving severe suffering before dying.","zh":"painful death 指死亡前伴隨嚴重痛苦的死亡。"},{"en":"Doctors try to prevent painful death by treating serious illnesses early.","zh":"醫生透過及早治療嚴重疾病來防止痛苦死亡。"},{"en":"If a disease causes fever, organ failure, and suffering, death may be painful.","zh":"如果疾病造成發燒、器官衰竭和痛苦，死亡可能很痛苦。"},{"en":"The phrase emphasises suffering as well as death.","zh":"這個片語不只強調死亡，也強調痛苦。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":9},{"front":"infect over two million people","meaning":"感染超過二百萬人","examples":[{"en":"The passage states that malaria infects over two million people a year.","zh":"文章指出，瘧疾每年感染超過二百萬人。"},{"en":"Infect over two million people means spread disease to more than two million individuals.","zh":"infect over two million people 指把疾病傳染給超過二百萬人。"},{"en":"A virus can infect many people quickly if it spreads in crowded places.","zh":"如果病毒在擠迫地方傳播，可以迅速感染許多人。"},{"en":"If a disease infects millions each year, public health systems face heavy pressure.","zh":"如果疾病每年感染數百萬人，公共健康系統會承受沉重壓力。"},{"en":"The phrase describes a very large scale of infection.","zh":"這個片語描述非常大規模的感染。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":9},{"front":"most of them children","meaning":"當中大多數是兒童","examples":[{"en":"Many people infected by malaria are children.","zh":"許多感染瘧疾的人是兒童。"},{"en":"Most of them children means the majority of the people in that group are children.","zh":"most of them children 指該群人中大多數是兒童。"},{"en":"The clinic treated many patients after the flood, most of them children.","zh":"水災後診所治療了許多病人，當中大多數是兒童。"},{"en":"If most victims are children, prevention programmes often focus on families and schools.","zh":"如果大多數受害者是兒童，預防計劃通常集中於家庭和學校。"},{"en":"The phrase identifies the main age group affected.","zh":"這個片語指出主要受影響的年齡群體。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":9},{"front":"killing over one quarter","meaning":"殺死超過四分之一","examples":[{"en":"The passage states that malaria kills over one quarter of those infected.","zh":"文章指出，瘧疾殺死感染者中超過四分之一。"},{"en":"Killing over one quarter means causing death in more than 25 percent of a group.","zh":"killing over one quarter 指造成某群體中超過25%死亡。"},{"en":"If a disease killed over one quarter of patients, doctors would treat it as extremely dangerous.","zh":"如果疾病殺死超過四分之一病人，醫生會把它視為極度危險。"},{"en":"A high death rate can make prevention as important as treatment.","zh":"高死亡率可令預防與治療同樣重要。"},{"en":"The phrase expresses a very serious mortality level.","zh":"這個片語表達非常嚴重的死亡水平。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":9},{"front":"Aedes aegypti mosquito","meaning":"埃及斑蚊","examples":[{"en":"The Aedes aegypti mosquito spreads yellow fever.","zh":"埃及斑蚊傳播黃熱病。"},{"en":"Aedes aegypti mosquito is a mosquito species known for spreading several viral diseases.","zh":"Aedes aegypti mosquito 是一種以傳播多種病毒性疾病聞名的蚊子。"},{"en":"Public health teams may target Aedes aegypti mosquitoes in urban areas.","zh":"公共健康團隊可能在市區針對埃及斑蚊。"},{"en":"If Aedes aegypti breeds near homes, disease risk can increase.","zh":"如果埃及斑蚊在住宅附近繁殖，疾病風險可能上升。"},{"en":"The phrase names a specific disease-spreading mosquito.","zh":"這個片語指一種特定傳病蚊子。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":10},{"front":"species responsible for","meaning":"導致……的物種","examples":[{"en":"This mosquito is the species responsible for yellow fever.","zh":"這種蚊子是導致黃熱病的物種。"},{"en":"Species responsible for means the particular species that causes or spreads something.","zh":"species responsible for 指造成或傳播某事的特定物種。"},{"en":"Scientists may identify the species responsible for damaging crops.","zh":"科學家可能識別導致農作物受損的物種。"},{"en":"If one mosquito species is responsible for a disease, control efforts can target it.","zh":"如果一種蚊子負責傳播疾病，控制工作就可針對它。"},{"en":"The phrase identifies the main biological cause.","zh":"這個片語指出主要生物原因。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":10},{"front":"other great killer","meaning":"另一大殺手","examples":[{"en":"Yellow fever is described as the other great killer.","zh":"黃熱病被描述為另一大殺手。"},{"en":"Other great killer means another major cause of death besides the one already mentioned.","zh":"other great killer 指除了已提及者外，另一個重大死因。"},{"en":"After heart disease, stroke may be described as another great killer in some health reports.","zh":"在一些健康報告中，繼心臟病後，中風可能被描述為另一大殺手。"},{"en":"If one disease kills many people, another great killer still deserves attention.","zh":"如果一種疾病殺死很多人，另一大殺手仍值得注意。"},{"en":"The phrase adds a second serious danger.","zh":"這個片語加入第二個嚴重危險。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":10},{"front":"yellow fever","meaning":"黃熱病","examples":[{"en":"Yellow fever is a viral disease spread by mosquitoes.","zh":"黃熱病是由蚊子傳播的病毒性疾病。"},{"en":"Yellow fever is an infectious disease that can cause fever, liver damage, and yellowing skin.","zh":"yellow fever 是可造成發燒、肝臟損害和皮膚變黃的傳染病。"},{"en":"Travellers to some tropical areas may need a yellow fever vaccine.","zh":"前往某些熱帶地區的旅客可能需要黃熱病疫苗。"},{"en":"If yellow fever spreads in a community, vaccination becomes very important.","zh":"如果黃熱病在社區傳播，疫苗接種就非常重要。"},{"en":"The phrase names a serious mosquito-borne disease.","zh":"這個片語指一種嚴重蚊媒疾病。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":10},{"front":"viral disease","meaning":"病毒性疾病","examples":[{"en":"Yellow fever is a viral disease.","zh":"黃熱病是一種病毒性疾病。"},{"en":"A viral disease is an illness caused by a virus.","zh":"viral disease 是由病毒造成的疾病。"},{"en":"Flu is a common viral disease that can spread through coughs and sneezes.","zh":"流感是常見病毒性疾病，可透過咳嗽和噴嚏傳播。"},{"en":"If a disease is viral, antibiotics will not directly kill the virus.","zh":"如果疾病是病毒性的，抗生素不會直接殺死病毒。"},{"en":"The phrase identifies the type of disease cause.","zh":"這個片語指出疾病成因類型。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":10},{"front":"be limited to","meaning":"限於","examples":[{"en":"Yellow fever is limited to tropical areas.","zh":"黃熱病限於熱帶地區。"},{"en":"Be limited to means exist only within a particular place, group, or range.","zh":"be limited to 指只存在於特定地方、群體或範圍內。"},{"en":"The discount is limited to students with valid ID cards.","zh":"折扣只限於持有效學生證的學生。"},{"en":"If a disease is limited to certain areas, travellers can assess risk by destination.","zh":"如果疾病限於某些地區，旅客可按目的地評估風險。"},{"en":"The phrase describes restriction.","zh":"這個片語描述限制。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":10},{"front":"tropical areas","meaning":"熱帶地區","examples":[{"en":"Yellow fever mainly occurs in tropical areas.","zh":"黃熱病主要出現在熱帶地區。"},{"en":"Tropical areas are hot regions near the equator, often with warm weather all year.","zh":"tropical areas 是赤道附近炎熱地區，通常全年溫暖。"},{"en":"Mosquitoes often breed well in warm, wet tropical areas.","zh":"蚊子常在溫暖潮濕的熱帶地區繁殖良好。"},{"en":"If travellers visit tropical areas, they may need protection from insect-borne diseases.","zh":"如果旅客到訪熱帶地區，可能需要預防昆蟲傳播疾病。"},{"en":"The phrase refers to climate and geography.","zh":"這個片語指氣候和地理。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":10},{"front":"primarily in","meaning":"主要在……","examples":[{"en":"Yellow fever occurs primarily in Africa.","zh":"黃熱病主要在非洲出現。"},{"en":"Primarily in means mainly or mostly in a particular place or group.","zh":"primarily in 指主要或大多在某地方或群體之中。"},{"en":"The programme is used primarily in secondary schools.","zh":"該計劃主要在中學使用。"},{"en":"If a disease occurs primarily in one region, health campaigns may focus there.","zh":"如果疾病主要在某地區出現，健康宣傳可能集中於該地。"},{"en":"The phrase highlights the main location or group.","zh":"這個片語突出主要地點或群體。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":10},{"front":"Central and South America","meaning":"中美洲和南美洲","examples":[{"en":"Yellow fever also occurs in Central and South America.","zh":"黃熱病也出現在中美洲和南美洲。"},{"en":"Central and South America refers to the regions south of North America, including many tropical countries.","zh":"Central and South America 指北美以南的地區，包括許多熱帶國家。"},{"en":"Travellers may check health advice before visiting Central and South America.","zh":"旅客到訪中美洲和南美洲前可能查看健康建議。"},{"en":"If a disease occurs in these regions, vaccination rules may affect travel plans.","zh":"如果疾病出現在這些地區，疫苗規定可能影響旅行計劃。"},{"en":"The phrase identifies a broad geographical area.","zh":"這個片語指出廣闊地理區域。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":10},{"front":"high fever","meaning":"高燒","examples":[{"en":"Yellow fever begins with high fever.","zh":"黃熱病以高燒開始。"},{"en":"High fever means a body temperature much higher than normal.","zh":"high fever 指體溫遠高於正常水平。"},{"en":"A child with high fever should be watched carefully and may need medical care.","zh":"高燒的孩子應被仔細觀察，並可能需要醫療照顧。"},{"en":"If high fever appears suddenly, infection may be one possible cause.","zh":"如果突然出現高燒，感染可能是一個原因。"},{"en":"The phrase describes a serious symptom.","zh":"這個片語描述嚴重症狀。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":10},{"front":"nausea","meaning":"噁心","examples":[{"en":"Nausea is one of the symptoms of yellow fever.","zh":"噁心是黃熱病的症狀之一。"},{"en":"Nausea is the feeling that one may vomit.","zh":"nausea 是感到可能會嘔吐的感覺。"},{"en":"Some people feel nausea when travelling on a rough sea.","zh":"有些人在海面顛簸旅行時會感到噁心。"},{"en":"If nausea continues with fever, a doctor may check for infection.","zh":"如果噁心伴隨發燒持續，醫生可能檢查是否感染。"},{"en":"The word describes feeling sick in the stomach.","zh":"這個詞描述胃部不適想嘔的感覺。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":11},{"front":"attack the liver","meaning":"攻擊肝臟","examples":[{"en":"The virus attacks the liver.","zh":"病毒攻擊肝臟。"},{"en":"Attack the liver means damage or infect the liver.","zh":"attack the liver 指損害或感染肝臟。"},{"en":"Some diseases attack the lungs, while others attack the liver or brain.","zh":"有些疾病攻擊肺部，另一些則攻擊肝臟或大腦。"},{"en":"If a virus attacks the liver, the body may struggle to process toxins properly.","zh":"如果病毒攻擊肝臟，身體可能難以正常處理毒素。"},{"en":"The phrase describes harm to a specific organ.","zh":"這個片語描述對特定器官的傷害。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":11},{"front":"host’s skin","meaning":"宿主的皮膚","examples":[{"en":"The host’s skin may turn yellow.","zh":"宿主的皮膚可能變黃。"},{"en":"Host’s skin means the skin of the person or animal carrying an infection.","zh":"host’s skin 指攜帶感染的人或動物的皮膚。"},{"en":"A doctor may examine a host’s skin for rashes, swelling, or colour changes.","zh":"醫生可能檢查宿主皮膚是否有皮疹、腫脹或顏色變化。"},{"en":"If a disease affects the liver, the host’s skin may change colour.","zh":"如果疾病影響肝臟，宿主皮膚可能變色。"},{"en":"The phrase links the infected body with a visible sign.","zh":"這個片語把受感染身體與可見徵象連接起來。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":11},{"front":"turn yellow","meaning":"變黃","examples":[{"en":"The host’s skin turns yellow after the liver is affected.","zh":"肝臟受影響後，宿主皮膚會變黃。"},{"en":"Turn yellow means change colour and become yellow.","zh":"turn yellow 指改變顏色並變成黃色。"},{"en":"Leaves turn yellow when a plant lacks water or nutrients.","zh":"植物缺水或缺營養時，葉子會變黃。"},{"en":"If a person’s skin turns yellow, doctors may check the liver.","zh":"如果人的皮膚變黃，醫生可能檢查肝臟。"},{"en":"The phrase describes a visible colour change.","zh":"這個片語描述可見顏色變化。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":11},{"front":"hence the name","meaning":"因此得名","examples":[{"en":"The disease is called yellow fever because the skin turns yellow, hence the name.","zh":"這種疾病因皮膚變黃而稱為黃熱病，因此得名。"},{"en":"Hence the name means this is the reason for the name.","zh":"hence the name 指這就是名稱的由來。"},{"en":"The shop sells only books at night, hence the name “Night Library”.","zh":"那間店只在晚上賣書，因此得名「夜間圖書館」。"},{"en":"If a disease causes yellow skin, the name yellow fever becomes understandable.","zh":"如果疾病造成皮膚變黃，「黃熱病」這名稱就容易理解。"},{"en":"The phrase explains naming logic.","zh":"這個片語解釋命名邏輯。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":11},{"front":"death following","meaning":"隨後死亡","examples":[{"en":"After the skin turns yellow, death may follow some days later.","zh":"皮膚變黃後，可能在數日後死亡。"},{"en":"Death following means death happens after a previous symptom or event.","zh":"death following 指死亡在先前症狀或事件之後發生。"},{"en":"In severe poisoning, vomiting may appear first, with death following later if no treatment is given.","zh":"在嚴重中毒中，可能先出現嘔吐；如不治療，隨後可能死亡。"},{"en":"If organ damage is serious, death may follow within days.","zh":"如果器官損害嚴重，死亡可能在數日內隨之而來。"},{"en":"The phrase shows a sequence from symptom to fatal result.","zh":"這個片語顯示從症狀到致命結果的次序。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":11},{"front":"its toll","meaning":"其傷亡人數","examples":[{"en":"Yellow fever’s toll is smaller than malaria’s.","zh":"黃熱病的傷亡人數比瘧疾少。"},{"en":"Its toll means the number of deaths or suffering caused by it.","zh":"its toll 指某事造成的死亡或痛苦數量。"},{"en":"A storm’s toll may include deaths, injuries, and destroyed homes.","zh":"風暴的傷亡損失可能包括死亡、受傷和房屋被毀。"},{"en":"If a disease’s toll falls after vaccination, the programme may be working.","zh":"如果疾病的傷亡人數在接種疫苗後下降，計劃可能有效。"},{"en":"The phrase measures damage caused by a disaster or disease.","zh":"這個片語衡量災難或疾病造成的損害。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":11},{"front":"much smaller than","meaning":"比……小得多","examples":[{"en":"Yellow fever’s toll is much smaller than malaria’s.","zh":"黃熱病的傷亡人數比瘧疾小得多。"},{"en":"Much smaller than means far less in size, number, or amount.","zh":"much smaller than 指在大小、數量或程度上少得多。"},{"en":"My old phone is much smaller than my new tablet.","zh":"我的舊手機比新平板小得多。"},{"en":"If one disease’s toll is much smaller, it still may be serious but kills fewer people.","zh":"如果一種疾病的傷亡人數小得多，它仍可能嚴重，但殺死人較少。"},{"en":"The phrase makes a strong comparison of size or amount.","zh":"這個片語作出強烈大小或數量比較。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":11},{"front":"can be prevented with","meaning":"可透過……預防","examples":[{"en":"Yellow fever can be prevented with a vaccine.","zh":"黃熱病可透過疫苗預防。"},{"en":"Can be prevented with means can be stopped or avoided by using something.","zh":"can be prevented with 指可用某物阻止或避免。"},{"en":"Tooth decay can be prevented with brushing, fluoride, and regular check-ups.","zh":"蛀牙可透過刷牙、氟化物和定期檢查預防。"},{"en":"If a disease can be prevented with a vaccine, vaccination can save lives.","zh":"如果疾病可透過疫苗預防，接種疫苗可以救命。"},{"en":"The phrase links prevention with a method.","zh":"這個片語把預防與方法連接起來。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":11},{"front":"vaccine","meaning":"疫苗","examples":[{"en":"There is a vaccine for yellow fever.","zh":"有一種黃熱病疫苗。"},{"en":"A vaccine is a medical preparation that helps the immune system protect against a disease.","zh":"vaccine 是幫助免疫系統預防疾病的醫學製劑。"},{"en":"Children receive vaccines to prevent serious infections.","zh":"兒童接種疫苗以預防嚴重感染。"},{"en":"If many people receive a vaccine, disease spread may decrease.","zh":"如果很多人接種疫苗，疾病傳播可能下降。"},{"en":"The word refers to preventive medicine, not treatment after severe illness.","zh":"這個詞指預防性醫學，而不是重病後的治療。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":11},{"front":"extensive vaccination programmes","meaning":"大規模疫苗接種計劃","examples":[{"en":"Extensive vaccination programmes have had some success.","zh":"大規模疫苗接種計劃取得了一定成效。"},{"en":"Extensive vaccination programmes are large organised efforts to vaccinate many people.","zh":"extensive vaccination programmes 是有組織地為許多人接種疫苗的大型工作。"},{"en":"A government may run extensive vaccination programmes in schools and clinics.","zh":"政府可能在學校和診所推行大規模疫苗接種計劃。"},{"en":"If vaccination programmes reach enough people, disease outbreaks may become rarer.","zh":"如果疫苗接種計劃接觸到足夠多人，疾病爆發可能變得較少。"},{"en":"The phrase describes large-scale public health action.","zh":"這個片語描述大規模公共健康行動。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":12},{"front":"sponsored by","meaning":"由……贊助","examples":[{"en":"Vaccination programmes have been sponsored by the WHO.","zh":"疫苗接種計劃由世界衞生組織贊助。"},{"en":"Sponsored by means funded, supported, or officially backed by an organisation or person.","zh":"sponsored by 指由某機構或個人資助、支持或正式背書。"},{"en":"A school sports day may be sponsored by local businesses.","zh":"學校運動會可能由本地商戶贊助。"},{"en":"If a health programme is sponsored by a major organisation, it may gain resources and trust.","zh":"如果健康計劃由大型組織贊助，它可能獲得資源和信任。"},{"en":"The phrase identifies the supporter behind an activity.","zh":"這個片語指出活動背後的支持者。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":12},{"front":"the WHO","meaning":"世界衞生組織","examples":[{"en":"The WHO has sponsored yellow fever vaccination programmes.","zh":"世界衞生組織贊助了黃熱病疫苗接種計劃。"},{"en":"The WHO is the World Health Organization, an international body concerned with global health.","zh":"WHO 是 World Health Organization，即關注全球健康的國際機構。"},{"en":"The WHO may issue advice during disease outbreaks.","zh":"世界衞生組織可能在疾病爆發期間發出建議。"},{"en":"If the WHO supports a programme, countries may follow its public health guidance.","zh":"如果世界衞生組織支持某計劃，各國可能跟隨其公共健康指引。"},{"en":"The phrase refers to a major international health organisation.","zh":"這個片語指一個主要國際衞生組織。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":12},{"front":"have some success","meaning":"取得一定成效","examples":[{"en":"Vaccination programmes have had some success.","zh":"疫苗接種計劃取得了一定成效。"},{"en":"Have some success means achieve useful results, though not complete success.","zh":"have some success 指取得有用成果，但不是完全成功。"},{"en":"A new study plan may have some success if students make fewer grammar mistakes.","zh":"如果學生文法錯誤減少，新的學習計劃可能取得一定成效。"},{"en":"If a programme has some success, it may be improved and expanded.","zh":"如果計劃取得一定成效，就可能被改善和擴展。"},{"en":"The phrase suggests partial but real progress.","zh":"這個片語暗示部分但真實的進展。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":12},{"front":"disease-prone areas","meaning":"疾病高發地區","examples":[{"en":"Travellers to disease-prone areas are usually protected.","zh":"前往疾病高發地區的旅客通常受到保護。"},{"en":"Disease-prone areas are places where certain diseases are likely to occur.","zh":"disease-prone areas 是某些疾病較可能出現的地方。"},{"en":"People visiting disease-prone areas may need vaccines, medicine, or mosquito nets.","zh":"到訪疾病高發地區的人可能需要疫苗、藥物或蚊帳。"},{"en":"If an area is disease-prone, public health planning becomes especially important.","zh":"如果一個地區疾病高發，公共健康規劃就特別重要。"},{"en":"The phrase describes places with higher disease risk.","zh":"這個片語描述疾病風險較高的地方。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":12},{"front":"similarly protected","meaning":"同樣受到保護","examples":[{"en":"Travellers are usually similarly protected by vaccination.","zh":"旅客通常透過疫苗接種同樣受到保護。"},{"en":"Similarly protected means protected in the same or comparable way.","zh":"similarly protected 指以相同或相近方式受到保護。"},{"en":"If one classroom has air filters, nearby classrooms should be similarly protected.","zh":"如果一間課室有空氣過濾器，附近課室也應同樣受到保護。"},{"en":"If local people are vaccinated, travellers may be similarly protected before arrival.","zh":"如果本地人已接種疫苗，旅客出發前也可能同樣受到保護。"},{"en":"The phrase compares protection between groups.","zh":"這個片語比較不同群體的保護。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":12},{"front":"with such a death toll","meaning":"鑑於如此高的死亡人數","examples":[{"en":"With such a death toll, the mosquito’s link to disease should have been obvious.","zh":"鑑於如此高的死亡人數，蚊子與疾病的關係本應顯而易見。"},{"en":"With such a death toll means given that so many people died.","zh":"with such a death toll 指鑑於有如此多人死亡。"},{"en":"With such a high accident toll, the road clearly needs safety measures.","zh":"鑑於如此高的意外死亡人數，這條路顯然需要安全措施。"},{"en":"If deaths are numerous, people expect the cause to be recognised quickly.","zh":"如果死亡人數眾多，人們會預期原因很快被認識到。"},{"en":"The phrase introduces reasoning based on severe loss of life.","zh":"這個片語引出基於嚴重死亡損失的推理。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":12},{"front":"take a surprisingly long time","meaning":"花了出奇長時間","examples":[{"en":"It took a surprisingly long time to realise the link between mosquitoes and disease.","zh":"人們花了出奇長時間才意識到蚊子與疾病之間的關係。"},{"en":"Take a surprisingly long time means require more time than people would expect.","zh":"take a surprisingly long time 指需要比人們預期更長的時間。"},{"en":"It took a surprisingly long time for the school to fix a simple timetable mistake.","zh":"學校花了出奇長時間才修正一個簡單時間表錯誤。"},{"en":"If evidence seems obvious later, people may wonder why discovery took so long.","zh":"如果證據日後看似明顯，人們可能疑惑為何發現花了那麼久。"},{"en":"The phrase expresses surprise about delay.","zh":"這個片語表達對延誤的驚訝。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":12},{"front":"the link between…and…","meaning":"……與……之間的關係","examples":[{"en":"Scientists eventually realised the link between mosquitoes and disease.","zh":"科學家最終意識到蚊子與疾病之間的關係。"},{"en":"The link between two things is the connection or relationship joining them.","zh":"the link between two things 指連接兩者的關聯或關係。"},{"en":"Teachers often explain the link between sleep and learning.","zh":"老師常解釋睡眠與學習之間的關係。"},{"en":"If researchers find a link between insects and illness, prevention can become more focused.","zh":"如果研究人員發現昆蟲與疾病之間的關係，預防工作就能更集中。"},{"en":"The phrase identifies a relationship that matters.","zh":"這個片語指出重要關係。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":12},{"front":"be realised","meaning":"被意識到；被認識到","examples":[{"en":"The link between mosquitoes and disease was eventually realised.","zh":"蚊子與疾病之間的關係最終被認識到。"},{"en":"Be realised means become understood, recognised, or noticed.","zh":"be realised 指被理解、認識或注意到。"},{"en":"The mistake was realised only after the exam papers had been printed.","zh":"錯誤直到試卷印好後才被意識到。"},{"en":"If a health risk is realised late, many people may suffer before action is taken.","zh":"如果健康風險很晚才被認識到，許多人可能在採取行動前受害。"},{"en":"The phrase describes understanding finally happening.","zh":"這個片語描述理解終於發生。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":12},{"front":"be exemplified in","meaning":"在……中得到體現","examples":[{"en":"This delay is exemplified in the construction of the Panama Canal.","zh":"這種延誤在巴拿馬運河的建造中得到體現。"},{"en":"Be exemplified in means be shown clearly by a particular example.","zh":"be exemplified in 指由某個特定例子清楚顯示。"},{"en":"Poor planning is exemplified in the school trip that forgot to book buses.","zh":"規劃不善在忘記預訂巴士的學校旅行中得到體現。"},{"en":"If a broad problem is exemplified in one case, that case helps explain the whole issue.","zh":"如果一個廣泛問題在某案例中得到體現，該案例就有助解釋整個議題。"},{"en":"The phrase introduces a clear illustration.","zh":"這個片語引出清楚例證。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":13},{"front":"construction of the Panama Canal","meaning":"巴拿馬運河的建造","examples":[{"en":"The construction of the Panama Canal shows the danger of mosquito-borne disease.","zh":"巴拿馬運河的建造顯示蚊媒疾病的危險。"},{"en":"Construction of the Panama Canal means the building of the waterway through Panama.","zh":"construction of the Panama Canal 指穿過巴拿馬的水道建設。"},{"en":"History students may study the construction of the Panama Canal as an engineering and health story.","zh":"歷史學生可能把巴拿馬運河建造作為工程和健康故事來研究。"},{"en":"If disease kills many workers during construction, health control becomes part of engineering success.","zh":"如果疾病在施工期間殺死許多工人，健康控制就成為工程成功的一部分。"},{"en":"The phrase names a major historical building project.","zh":"這個片語指一項重大歷史建設工程。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":13},{"front":"ambitious project","meaning":"雄心勃勃的工程","examples":[{"en":"The Panama Canal was an ambitious project.","zh":"巴拿馬運河是一項雄心勃勃的工程。"},{"en":"An ambitious project is a large and difficult plan that aims to achieve something important.","zh":"ambitious project 是旨在達成重要目標的大型困難計劃。"},{"en":"Building a new hospital in one year would be an ambitious project.","zh":"一年內建成新醫院會是一項雄心勃勃的工程。"},{"en":"If a project is ambitious, it usually needs money, planning, and skilled workers.","zh":"如果項目雄心勃勃，通常需要金錢、規劃和熟練工人。"},{"en":"The phrase suggests scale, difficulty, and high goals.","zh":"這個片語暗示規模、難度和高目標。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":13},{"front":"excavate a passageway","meaning":"開挖一條通道","examples":[{"en":"The project aimed to excavate a passageway for ships.","zh":"該工程旨在為船隻開挖一條通道。"},{"en":"Excavate a passageway means dig out earth or rock to create a route through.","zh":"excavate a passageway 指挖走泥土或岩石以開出通道。"},{"en":"Workers may excavate a passageway for an underground railway.","zh":"工人可能為地下鐵路開挖一條通道。"},{"en":"If engineers excavate through difficult land, safety and drainage become important.","zh":"如果工程師在困難地形中開挖，安全和排水就變得重要。"},{"en":"The phrase describes digging to create access.","zh":"這個片語描述透過挖掘創造通路。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":13},{"front":"narrow Central American nation","meaning":"狹長的中美洲國家","examples":[{"en":"The canal crossed a narrow Central American nation.","zh":"運河穿過一個狹長的中美洲國家。"},{"en":"A narrow Central American nation means a thin-shaped country in Central America.","zh":"narrow Central American nation 指位於中美洲、形狀狹長的國家。"},{"en":"Panama is a narrow country connecting North and South America.","zh":"巴拿馬是一個連接北美和南美的狹長國家。"},{"en":"If a country is narrow, a canal across it can shorten sea travel greatly.","zh":"如果一個國家狹長，穿過它的運河可以大幅縮短海上旅程。"},{"en":"The phrase describes geography and location.","zh":"這個片語描述地理和位置。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":13},{"front":"struggle for eight years","meaning":"奮戰八年","examples":[{"en":"The French struggled for eight years in the jungle.","zh":"法國人在叢林中奮戰八年。"},{"en":"Struggle for eight years means face serious difficulty for a period of eight years.","zh":"struggle for eight years 指在八年期間面對嚴重困難。"},{"en":"A family may struggle for years to pay medical bills.","zh":"一個家庭可能多年為支付醫療費用而掙扎。"},{"en":"If workers struggle for many years without success, a project may be abandoned.","zh":"如果工人多年奮戰仍未成功，項目可能被放棄。"},{"en":"The phrase emphasises long-lasting difficulty.","zh":"這個片語強調持久困難。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":13},{"front":"insect-infested jungle","meaning":"蟲患嚴重的叢林","examples":[{"en":"The workers struggled in an insect-infested jungle.","zh":"工人在蟲患嚴重的叢林中奮戰。"},{"en":"An insect-infested jungle is a jungle full of troublesome or dangerous insects.","zh":"insect-infested jungle 指充滿滋擾或危險昆蟲的叢林。"},{"en":"Campers may avoid insect-infested areas without nets or repellent.","zh":"露營者沒有蚊帳或驅蟲劑時，可能避開蟲患嚴重地區。"},{"en":"If workers live in an insect-infested jungle, mosquito-borne disease risk rises.","zh":"如果工人住在蟲患嚴重的叢林，蚊媒疾病風險會上升。"},{"en":"The phrase describes a place heavily affected by insects.","zh":"這個片語描述嚴重受昆蟲影響的地方。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":13},{"front":"death toll from","meaning":"由……造成的死亡人數","examples":[{"en":"The death toll from malaria and yellow fever was high.","zh":"由瘧疾和黃熱病造成的死亡人數很高。"},{"en":"Death toll from means the number of deaths caused by a particular event or disease.","zh":"death toll from 指由某事件或疾病造成的死亡人數。"},{"en":"News reports often give the death toll from floods or earthquakes.","zh":"新聞報道常提供由水災或地震造成的死亡人數。"},{"en":"If the death toll from disease rises, authorities must act quickly.","zh":"如果疾病造成的死亡人數上升，當局必須迅速行動。"},{"en":"The phrase links deaths to their cause.","zh":"這個片語把死亡與原因連接起來。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":13},{"front":"maintain an experienced workforce","meaning":"維持有經驗的勞動隊伍","examples":[{"en":"Disease made it difficult to maintain an experienced workforce.","zh":"疾病令維持有經驗的勞動隊伍變得困難。"},{"en":"Maintain an experienced workforce means keep enough skilled workers available over time.","zh":"maintain an experienced workforce 指長期保持足夠熟練工人。"},{"en":"A hospital must maintain an experienced workforce to provide safe care.","zh":"醫院必須維持有經驗的員工隊伍，以提供安全護理。"},{"en":"If many workers fall ill or leave, a project loses knowledge and efficiency.","zh":"如果許多工人生病或離職，項目就會失去知識和效率。"},{"en":"The phrase connects worker health with project stability.","zh":"這個片語把工人健康與項目穩定連接起來。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":13},{"front":"after the loss of","meaning":"在失去……之後","examples":[{"en":"Work was abandoned after the loss of 22,000 lives.","zh":"在失去22,000條生命之後，工程被放棄。"},{"en":"After the loss of means following the death, disappearance, or removal of something important.","zh":"after the loss of 指在死亡、消失或失去重要事物之後。"},{"en":"A school trip was cancelled after the loss of key safety documents.","zh":"在遺失關鍵安全文件之後，學校旅行被取消。"},{"en":"If thousands of lives are lost, public support for a project may collapse.","zh":"如果失去數以千計生命，公眾對項目的支持可能崩潰。"},{"en":"The phrase introduces a serious event that causes later action.","zh":"這個片語引出導致後續行動的嚴重事件。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":13},{"front":"work was abandoned","meaning":"工程被放棄","examples":[{"en":"Work on the canal was abandoned after many deaths.","zh":"許多人死亡後，運河工程被放棄。"},{"en":"Work was abandoned means the project was stopped and not continued.","zh":"work was abandoned 指項目被停止並不再繼續。"},{"en":"Construction work was abandoned when the building was found unsafe.","zh":"當建築物被發現不安全，建築工程被放棄。"},{"en":"If workers keep dying, leaders may abandon the work rather than continue.","zh":"如果工人持續死亡，領導者可能放棄工程而不是繼續。"},{"en":"The phrase describes stopping a project.","zh":"這個片語描述停止一項工程。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":14},{"front":"shortly afterwards","meaning":"不久之後","examples":[{"en":"Shortly afterwards, Ronald Ross discovered how malaria was transmitted.","zh":"不久之後，Ronald Ross 發現瘧疾如何傳播。"},{"en":"Shortly afterwards means a short time after that event.","zh":"shortly afterwards 指在那件事後不久。"},{"en":"The fire alarm rang, and shortly afterwards, students left the building.","zh":"火警鐘響起，不久之後學生離開大樓。"},{"en":"If a discovery happens shortly afterwards, it may change how people understand the earlier failure.","zh":"如果不久之後出現發現，它可能改變人們對早前失敗的理解。"},{"en":"The phrase marks close timing after an event.","zh":"這個片語標記某事件後的相近時間。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":14},{"front":"deduce the means of","meaning":"推斷出……的方法","examples":[{"en":"Ronald Ross deduced the means of disease transmission.","zh":"Ronald Ross 推斷出疾病傳播的方法。"},{"en":"Deduce the means of means work out how something happens by using evidence and reasoning.","zh":"deduce the means of 指用證據和推理弄清某事如何發生。"},{"en":"A detective may deduce the means of entry by studying broken locks.","zh":"偵探可能透過研究破壞的門鎖推斷入屋方法。"},{"en":"If scientists deduce how a disease spreads, they can design better prevention.","zh":"如果科學家推斷出疾病如何傳播，就能設計更好預防方法。"},{"en":"The phrase describes reasoning from clues to mechanism.","zh":"這個片語描述從線索推理出機制。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":14},{"front":"disease transmission","meaning":"疾病傳播","examples":[{"en":"Ross studied the means of disease transmission.","zh":"Ross 研究疾病傳播的方法。"},{"en":"Disease transmission is the process by which an illness spreads from one host to another.","zh":"disease transmission 是疾病從一個宿主傳到另一個宿主的過程。"},{"en":"Washing hands reduces disease transmission in schools and hospitals.","zh":"洗手可以減少學校和醫院中的疾病傳播。"},{"en":"If mosquitoes are part of disease transmission, water control can reduce risk.","zh":"如果蚊子是疾病傳播的一部分，水源控制可以降低風險。"},{"en":"The phrase describes how infection moves through a population.","zh":"這個片語描述感染如何在人群中移動。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":14},{"front":"identify the malaria parasite","meaning":"找出瘧疾寄生蟲","examples":[{"en":"Ross identified the malaria parasite in mosquitoes.","zh":"Ross 在蚊子中找出瘧疾寄生蟲。"},{"en":"Identify the malaria parasite means find and recognise the organism that causes malaria.","zh":"identify the malaria parasite 指找到並識別造成瘧疾的生物。"},{"en":"A laboratory can identify a parasite by examining blood under a microscope.","zh":"實驗室可以透過顯微鏡檢查血液來識別寄生蟲。"},{"en":"If scientists identify the parasite inside mosquitoes, they can prove how the disease spreads.","zh":"如果科學家在蚊子體內找出寄生蟲，就能證明疾病如何傳播。"},{"en":"The phrase describes a key scientific discovery.","zh":"這個片語描述關鍵科學發現。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":14},{"front":"gastrointestinal tract","meaning":"胃腸道","examples":[{"en":"The malaria parasite was found in the gastrointestinal tract of mosquitoes.","zh":"瘧疾寄生蟲在蚊子的胃腸道中被發現。"},{"en":"The gastrointestinal tract is the digestive passage through which food moves.","zh":"gastrointestinal tract 是食物通過的消化通道。"},{"en":"Doctors may examine the gastrointestinal tract when a patient has stomach problems.","zh":"當病人有胃部問題時，醫生可能檢查胃腸道。"},{"en":"If a parasite lives in the gastrointestinal tract, it may be found during dissection or testing.","zh":"如果寄生蟲生活在胃腸道中，可能在解剖或測試中被發現。"},{"en":"The phrase refers to the stomach-and-intestine system.","zh":"這個片語指胃和腸的系統。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":14},{"front":"mosquito numbers","meaning":"蚊子數量","examples":[{"en":"Mosquito numbers can be reduced by limiting access to water.","zh":"蚊子數量可以透過限制接觸水源而減少。"},{"en":"Mosquito numbers means the number of mosquitoes in an area.","zh":"mosquito numbers 指某地區中的蚊子數目。"},{"en":"A housing estate may track mosquito numbers after heavy rain.","zh":"屋苑可能在大雨後追蹤蚊子數量。"},{"en":"If mosquito numbers fall, the chance of being bitten also falls.","zh":"如果蚊子數量下降，被叮咬的機會也會下降。"},{"en":"The phrase is used when discussing population control.","zh":"這個片語用於討論族群控制。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":14},{"front":"limit access to water","meaning":"限制接觸水源","examples":[{"en":"Ross realised that mosquito numbers could be reduced by limiting their access to water.","zh":"Ross 意識到可以透過限制蚊子接觸水源來減少蚊子數量。"},{"en":"Limit access to water means stop or reduce opportunities to reach water.","zh":"limit access to water 指阻止或減少接觸水的機會。"},{"en":"Covering tanks can limit mosquitoes’ access to water.","zh":"蓋好水箱可以限制蚊子接觸水源。"},{"en":"If mosquitoes cannot reach standing water, they cannot breed as easily.","zh":"如果蚊子不能接觸積水，就不易繁殖。"},{"en":"The phrase describes preventing contact with a needed resource.","zh":"這個片語描述阻止接觸必要資源。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":14},{"front":"crucial insights","meaning":"關鍵見解","examples":[{"en":"Ross provided two crucial insights into controlling the disease.","zh":"Ross 提供了兩項控制疾病的關鍵見解。"},{"en":"Crucial insights are very important understandings that help solve a problem.","zh":"crucial insights 是幫助解決問題的非常重要理解。"},{"en":"A teacher’s feedback may give students crucial insights into why their writing is unclear.","zh":"老師的回饋可能給學生關於作文為何不清楚的關鍵見解。"},{"en":"If scientists gain crucial insights into transmission, disease control improves.","zh":"如果科學家對傳播方式取得關鍵見解，疾病控制就會改善。"},{"en":"The phrase refers to key understanding, not just facts.","zh":"這個片語指關鍵理解，而不只是事實。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":14},{"front":"lay the foundations for","meaning":"為……奠定基礎","examples":[{"en":"His discoveries laid the foundations for controlling malaria.","zh":"他的發現為控制瘧疾奠定基礎。"},{"en":"Lay the foundations for means create the basic knowledge or structure needed for later success.","zh":"lay the foundations for 指建立日後成功所需的基本知識或結構。"},{"en":"Early phonics lessons lay the foundations for fluent reading.","zh":"早期拼音課為流利閱讀奠定基礎。"},{"en":"If a discovery lays the foundation for treatment, later doctors can build on it.","zh":"如果發現為治療奠定基礎，後來醫生可以在其上發展。"},{"en":"The phrase describes preparing the base for future progress.","zh":"這個片語描述為未來進展準備基礎。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":14},{"front":"controlling the disease","meaning":"控制疾病","examples":[{"en":"The discoveries helped lay the foundations for controlling the disease.","zh":"這些發現幫助為控制疾病奠定基礎。"},{"en":"Controlling the disease means reducing its spread, severity, or impact.","zh":"controlling the disease 指減少疾病的傳播、嚴重程度或影響。"},{"en":"Schools control flu by encouraging sick students to stay home.","zh":"學校透過鼓勵生病學生留家來控制流感。"},{"en":"If mosquito breeding sites are removed, controlling mosquito-borne disease becomes easier.","zh":"如果清除蚊子繁殖地，控制蚊媒疾病就更容易。"},{"en":"The phrase focuses on managing a disease, not necessarily eliminating it completely.","zh":"這個片語集中於管理疾病，而不一定是完全消滅它。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":15},{"front":"resume work on","meaning":"恢復……工程","examples":[{"en":"The Americans resumed work on the Panama Canal in 1904.","zh":"美國人在1904年恢復巴拿馬運河工程。"},{"en":"Resume work on means start working again after a pause or failure.","zh":"resume work on 指在暫停或失敗後重新開始工作。"},{"en":"Builders resumed work on the school hall after the storm damage was repaired.","zh":"風暴損毀修復後，建築工人恢復學校禮堂工程。"},{"en":"If disease control improves, workers may safely resume a project.","zh":"如果疾病控制改善，工人可能安全恢復項目。"},{"en":"The phrase marks a return to unfinished work.","zh":"這個片語標示回到未完成工作。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":15},{"front":"institute a programme","meaning":"推行一項計劃","examples":[{"en":"The Americans instituted a mosquito-abatement programme.","zh":"美國人推行了一項滅蚊計劃。"},{"en":"Institute a programme means formally start and organise a planned set of actions.","zh":"institute a programme 指正式開始並組織一套計劃行動。"},{"en":"A school may institute a reading programme to improve literacy.","zh":"學校可能推行閱讀計劃以改善讀寫能力。"},{"en":"If authorities institute a health programme, they create rules, funding, and actions.","zh":"如果當局推行健康計劃，就會建立規則、資金和行動。"},{"en":"The phrase suggests official organised action.","zh":"這個片語暗示官方而有組織的行動。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":15},{"front":"multi-million dollar","meaning":"數百萬美元的","examples":[{"en":"The programme was a multi-million dollar project.","zh":"該計劃是一個數百萬美元的項目。"},{"en":"Multi-million dollar means costing several million dollars.","zh":"multi-million dollar 指花費數百萬美元。"},{"en":"A new hospital wing may be a multi-million dollar project.","zh":"新醫院翼樓可能是一個數百萬美元的項目。"},{"en":"If disease control requires a multi-million dollar programme, the problem is large and serious.","zh":"如果疾病控制需要數百萬美元計劃，問題就龐大而嚴重。"},{"en":"The phrase shows high financial scale.","zh":"這個片語顯示高財務規模。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":15},{"front":"mosquito-abatement programme","meaning":"滅蚊計劃","examples":[{"en":"The Americans instituted a mosquito-abatement programme.","zh":"美國人推行了一項滅蚊計劃。"},{"en":"A mosquito-abatement programme is an organised plan to reduce mosquito numbers.","zh":"mosquito-abatement programme 是有組織地減少蚊子數量的計劃。"},{"en":"A city may run a mosquito-abatement programme after repeated dengue cases.","zh":"城市在反覆出現登革熱個案後，可能推行滅蚊計劃。"},{"en":"If a programme removes breeding sites, mosquito numbers can fall quickly.","zh":"如果計劃清除繁殖地，蚊子數量可以迅速下降。"},{"en":"The phrase describes public action against mosquitoes.","zh":"這個片語描述針對蚊子的公共行動。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":15},{"front":"consist of","meaning":"由……組成","examples":[{"en":"The programme consisted of many strategies.","zh":"該計劃由許多策略組成。"},{"en":"Consist of means be made up of particular parts.","zh":"consist of 指由特定部分組成。"},{"en":"A good revision plan may consist of reading, practice questions, and error checking.","zh":"良好溫習計劃可由閱讀、練習題和錯誤檢查組成。"},{"en":"If a programme consists of several methods, it can attack a problem from different angles.","zh":"如果計劃由幾種方法組成，就能從不同角度處理問題。"},{"en":"The phrase explains what something includes.","zh":"這個片語解釋某物包括甚麼。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":15},{"front":"screens on the windows","meaning":"窗戶上的紗網","examples":[{"en":"Workers’ houses were built with screens on the windows.","zh":"工人住房建有窗戶上的紗網。"},{"en":"Screens on the windows are mesh coverings that let air in but keep insects out.","zh":"screens on the windows 是讓空氣進入但阻隔昆蟲的網狀覆蓋物。"},{"en":"A family may install screens on windows to sleep with fresh air safely.","zh":"家庭可能在窗戶安裝紗網，以安全地開窗睡覺。"},{"en":"If windows have screens, mosquitoes are less likely to enter rooms.","zh":"如果窗戶有紗網，蚊子較不容易進入房間。"},{"en":"The phrase describes a simple physical barrier.","zh":"這個片語描述簡單的實體屏障。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":15},{"front":"harbour mosquitoes","meaning":"藏有蚊子","examples":[{"en":"Buildings harbouring mosquitoes were fumigated.","zh":"藏有蚊子的建築物被煙熏消毒。"},{"en":"Harbour mosquitoes means provide places where mosquitoes hide, rest, or breed.","zh":"harbour mosquitoes 指提供蚊子躲藏、停留或繁殖的地方。"},{"en":"A dark wet storeroom may harbour mosquitoes if water collects there.","zh":"如果有積水，陰暗潮濕的儲物室可能藏有蚊子。"},{"en":"If buildings harbour mosquitoes, residents may be bitten indoors.","zh":"如果建築物藏有蚊子，居民可能在室內被叮。"},{"en":"The phrase describes giving shelter to unwanted insects.","zh":"這個片語描述為不受歡迎昆蟲提供藏身處。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":15},{"front":"be fumigated","meaning":"被煙熏消毒","examples":[{"en":"Buildings harbouring mosquitoes were fumigated.","zh":"藏有蚊子的建築物被煙熏消毒。"},{"en":"Be fumigated means be treated with chemical smoke or gas to kill pests.","zh":"be fumigated 指用化學煙霧或氣體處理以殺死害蟲。"},{"en":"A warehouse may be fumigated if insects damage stored food.","zh":"如果昆蟲損害儲存食物，倉庫可能被煙熏消毒。"},{"en":"If a building is fumigated, people may need to leave until it is safe.","zh":"如果建築物被煙熏消毒，人們可能需要離開直到安全。"},{"en":"The phrase describes pest control using gas or smoke.","zh":"這個片語描述使用氣體或煙霧進行害蟲控制。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":15},{"front":"be isolated behind nets","meaning":"被隔離在蚊帳後","examples":[{"en":"Sick workers were isolated behind nets.","zh":"生病工人被隔離在蚊帳後。"},{"en":"Be isolated behind nets means be kept separate and protected by netting to stop mosquito contact.","zh":"be isolated behind nets 指被分隔並由網保護，以阻止蚊子接觸。"},{"en":"A patient with a mosquito-borne disease may sleep behind a net to prevent further bites.","zh":"患蚊媒疾病的病人可能在蚊帳後睡覺，以防止再被叮。"},{"en":"If sick people are isolated behind nets, mosquitoes are less likely to spread infection from them.","zh":"如果病人被隔離在蚊帳後，蚊子就較不可能從他們身上傳播感染。"},{"en":"The phrase combines separation with physical protection.","zh":"這個片語結合隔離和實體保護。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":15},{"front":"stagnant pools of water","meaning":"死水池；積水","examples":[{"en":"Stagnant pools of water are places where mosquitoes breed.","zh":"死水池是蚊子繁殖的地方。"},{"en":"Stagnant pools of water are still pools of water that do not flow.","zh":"stagnant pools of water 是不流動的積水。"},{"en":"Rainwater left in a bucket can become a stagnant pool of water.","zh":"留在桶中的雨水可以變成死水池。"},{"en":"If stagnant water remains for days, mosquitoes may lay eggs there.","zh":"如果積水停留數天，蚊子可能在那裡產卵。"},{"en":"The phrase describes an important mosquito breeding site.","zh":"這個片語描述重要的蚊子繁殖地。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":16},{"front":"where mosquitoes breed","meaning":"蚊子繁殖的地方","examples":[{"en":"Stagnant water is where mosquitoes breed.","zh":"死水是蚊子繁殖的地方。"},{"en":"Where mosquitoes breed means the place where mosquitoes lay eggs and produce young.","zh":"where mosquitoes breed 指蚊子產卵並繁殖幼蟲的地方。"},{"en":"Flowerpots and blocked drains can become places where mosquitoes breed.","zh":"花盆和堵塞去水口可以成為蚊子繁殖的地方。"},{"en":"If breeding sites are removed, fewer mosquitoes develop into adults.","zh":"如果清除繁殖地，較少蚊子會長成成蟲。"},{"en":"The phrase identifies the source of mosquito population growth.","zh":"這個片語指出蚊子數量增長的來源。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":16},{"front":"be sprayed with","meaning":"被噴灑……","examples":[{"en":"Stagnant pools were sprayed with oil and insecticide.","zh":"死水池被噴灑油和殺蟲劑。"},{"en":"Be sprayed with means have liquid applied over a surface in small droplets.","zh":"be sprayed with 指表面被細小液滴覆蓋。"},{"en":"Plants may be sprayed with water during hot weather.","zh":"天氣炎熱時，植物可能被噴水。"},{"en":"If stagnant water is sprayed with insecticide, mosquito larvae may die.","zh":"如果積水被噴灑殺蟲劑，蚊子幼蟲可能死亡。"},{"en":"The phrase describes applying a liquid treatment.","zh":"這個片語描述施加液體處理。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":16},{"front":"oil and insecticide","meaning":"油和殺蟲劑","examples":[{"en":"Stagnant pools were treated with oil and insecticide.","zh":"死水池用油和殺蟲劑處理。"},{"en":"Oil and insecticide are substances used to kill or block insects in water or on surfaces.","zh":"oil and insecticide 是用於水中或表面以殺死或阻隔昆蟲的物質。"},{"en":"Pest-control workers may use insecticide carefully around drains.","zh":"滅蟲人員可能在渠口附近小心使用殺蟲劑。"},{"en":"If oil covers stagnant water, mosquito larvae may be unable to breathe.","zh":"如果油覆蓋積水，蚊子幼蟲可能無法呼吸。"},{"en":"The phrase names materials used in mosquito control.","zh":"這個片語指出滅蚊所用材料。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":16},{"front":"roads were paved","meaning":"道路被鋪設","examples":[{"en":"Roads were paved to eliminate puddles.","zh":"道路被鋪設以消除水坑。"},{"en":"Roads were paved means roads were covered with a hard surface such as stone, concrete, or asphalt.","zh":"roads were paved 指道路被石、混凝土或瀝青等硬表面覆蓋。"},{"en":"A village road may be paved so buses can travel safely after rain.","zh":"村路可能被鋪設，好讓巴士雨後安全行駛。"},{"en":"If roads are paved, fewer muddy holes may collect standing water.","zh":"如果道路被鋪設，較少泥坑會積聚死水。"},{"en":"The phrase describes improving road surfaces.","zh":"這個片語描述改善路面。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":16},{"front":"eliminate puddles","meaning":"消除水坑","examples":[{"en":"Paving roads helped eliminate puddles.","zh":"鋪設道路有助消除水坑。"},{"en":"Eliminate puddles means remove small pools of standing water.","zh":"eliminate puddles 指清除小型積水。"},{"en":"A caretaker may sweep water away to eliminate puddles near a school entrance.","zh":"管理員可能掃走學校入口附近的水，以消除水坑。"},{"en":"If puddles are eliminated, mosquitoes have fewer places to breed.","zh":"如果水坑被消除，蚊子就有較少地方繁殖。"},{"en":"The phrase describes removing small water collections.","zh":"這個片語描述清除小型積水。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":16},{"front":"for this same reason","meaning":"出於同樣原因","examples":[{"en":"For this same reason, swamps were drained.","zh":"出於同樣原因，沼澤被排乾。"},{"en":"For this same reason means because of the same cause just mentioned.","zh":"for this same reason 指因為剛提到的同一原因。"},{"en":"The windows were closed to keep out insects; for this same reason, the doors were fitted with screens.","zh":"窗戶被關上以阻隔昆蟲；出於同樣原因，門裝上紗網。"},{"en":"If puddles are removed to stop breeding, swamps may be drained for the same reason.","zh":"如果清除水坑是為了阻止繁殖，沼澤也可能出於同樣原因被排乾。"},{"en":"The phrase links two actions to one shared purpose.","zh":"這個片語把兩個行動連接到同一目的。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":16},{"front":"swamps were drained","meaning":"沼澤被排乾","examples":[{"en":"Swamps were drained to reduce mosquito breeding sites.","zh":"沼澤被排乾以減少蚊子繁殖地。"},{"en":"Swamps were drained means water was removed from wetland areas.","zh":"swamps were drained 指濕地地區的水被移走。"},{"en":"Farmers sometimes drained swamps in the past to create farmland.","zh":"過去農民有時會排乾沼澤以開闢農田。"},{"en":"If swamps are drained, mosquitoes may lose breeding areas, but wetlands may also be damaged.","zh":"如果沼澤被排乾，蚊子可能失去繁殖地，但濕地也可能受損。"},{"en":"The phrase describes removing water from marshy land.","zh":"這個片語描述從沼澤地移除水分。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":16},{"front":"proper piping","meaning":"適當的管道","examples":[{"en":"Proper piping was used for drinking water and wastewater.","zh":"食水和污水使用了適當的管道。"},{"en":"Proper piping means safe, well-designed pipes for carrying water or waste.","zh":"proper piping 指用來輸送水或廢物的安全而設計良好的管道。"},{"en":"A building needs proper piping to avoid leaks and dirty water.","zh":"建築物需要適當管道以避免漏水和污水問題。"},{"en":"If proper piping is installed, standing water and sewage problems can decrease.","zh":"如果安裝適當管道，積水和污水問題可以減少。"},{"en":"The phrase refers to good water infrastructure.","zh":"這個片語指良好供排水基建。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":16},{"front":"drinking water and wastewater","meaning":"食水和污水","examples":[{"en":"Proper piping was used for drinking water and wastewater.","zh":"食水和污水使用了適當管道。"},{"en":"Drinking water and wastewater means clean water for use and dirty water that must be removed.","zh":"drinking water and wastewater 指可用的清潔食水和必須移走的污水。"},{"en":"Cities need separate systems for drinking water and wastewater.","zh":"城市需要分開處理食水和污水的系統。"},{"en":"If wastewater leaks into drinking water, disease can spread quickly.","zh":"如果污水滲入食水，疾病可以迅速傳播。"},{"en":"The phrase contrasts safe water supply with waste removal.","zh":"這個片語把安全供水與廢水排放作對比。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":16},{"front":"construction phase","meaning":"施工階段","examples":[{"en":"Deaths were reduced during the ten-year construction phase.","zh":"在十年施工階段期間，死亡人數減少。"},{"en":"Construction phase means the period when something is being built.","zh":"construction phase 指某物正在建造的時期。"},{"en":"During the construction phase of a school, students may use temporary classrooms.","zh":"在學校施工階段，學生可能使用臨時課室。"},{"en":"If safety improves during the construction phase, fewer workers are injured.","zh":"如果施工階段安全改善，受傷工人會較少。"},{"en":"The phrase marks one stage of a building project.","zh":"這個片語標示建設項目的其中一個階段。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":17},{"front":"a considerable number","meaning":"相當大的數目","examples":[{"en":"Less than 6,000 deaths was still a considerable number.","zh":"少於6,000人死亡仍是相當大的數目。"},{"en":"A considerable number means a large or noticeable amount.","zh":"a considerable number 指很大或明顯的數量。"},{"en":"A considerable number of students joined the weekend workshop.","zh":"相當多學生參加了週末工作坊。"},{"en":"If even a reduced death toll remains considerable, the danger is still serious.","zh":"如果減少後的死亡人數仍相當大，危險仍然嚴重。"},{"en":"The phrase means more than just a few.","zh":"這個片語表示不只是少數。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":17},{"front":"a major success","meaning":"重大成功","examples":[{"en":"The reduced death toll was considered a major success.","zh":"死亡人數下降被視為重大成功。"},{"en":"A major success is an important achievement with clear positive results.","zh":"a major success 是有清楚正面成果的重要成就。"},{"en":"A reading programme is a major success if many students improve by two levels.","zh":"如果許多學生提升兩個級別，閱讀計劃就是重大成功。"},{"en":"If deaths fall sharply, a health programme may be seen as a major success.","zh":"如果死亡人數大幅下降，健康計劃可能被視為重大成功。"},{"en":"The phrase describes a strong positive outcome.","zh":"這個片語描述強烈正面結果。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":17},{"front":"to this day","meaning":"直到今天","examples":[{"en":"To this day, removing stagnant water remains effective.","zh":"直到今天，清除積水仍然有效。"},{"en":"To this day means still true now, even after a long time.","zh":"to this day 指即使過了很久，現在仍然成立。"},{"en":"To this day, many families still keep old festival traditions.","zh":"直到今天，許多家庭仍保留舊節日傳統。"},{"en":"If a method works to this day, it has remained useful across generations.","zh":"如果方法直到今天仍有效，它就跨越多代仍有用。"},{"en":"The phrase connects past practice with present relevance.","zh":"這個片語把過去做法與現在相關性連接起來。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":17},{"front":"however small","meaning":"無論多小","examples":[{"en":"Stagnant pools of water remain dangerous, however small they are.","zh":"死水池無論多小仍然危險。"},{"en":"However small means no matter how small something is.","zh":"however small 指不論某物有多小。"},{"en":"A leak should be fixed, however small, before it damages the wall.","zh":"漏水無論多小，都應在損壞牆身前修好。"},{"en":"If a pool of water is small but stagnant, mosquitoes may still use it.","zh":"如果一灘水雖小但不流動，蚊子仍可能使用它。"},{"en":"The phrase warns that size does not remove risk.","zh":"這個片語警告大小不會消除風險。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":17},{"front":"cost-effective","meaning":"具成本效益","examples":[{"en":"Removing stagnant water is very cost-effective.","zh":"清除積水非常具成本效益。"},{"en":"Cost-effective means giving good results for the money spent.","zh":"cost-effective 指花費的金錢能帶來良好效果。"},{"en":"Online notices can be a cost-effective way for schools to contact parents.","zh":"網上通知可以是學校聯絡家長的具成本效益方法。"},{"en":"If a cheap action greatly reduces disease, it is cost-effective.","zh":"如果便宜行動大幅減少疾病，它就具成本效益。"},{"en":"The phrase compares benefit with cost.","zh":"這個片語比較好處和成本。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":17},{"front":"combating mosquito-borne diseases","meaning":"對抗蚊媒疾病","examples":[{"en":"Removing stagnant water helps in combating mosquito-borne diseases.","zh":"清除積水有助對抗蚊媒疾病。"},{"en":"Combating mosquito-borne diseases means fighting illnesses spread by mosquitoes.","zh":"combating mosquito-borne diseases 指對抗由蚊子傳播的疾病。"},{"en":"Health workers combat mosquito-borne diseases by using nets, vaccines, and water control.","zh":"衞生工作者透過蚊帳、疫苗和水源控制對抗蚊媒疾病。"},{"en":"If breeding sites are removed, disease transmission may decrease.","zh":"如果繁殖地被清除，疾病傳播可能下降。"},{"en":"The phrase describes active public health action.","zh":"這個片語描述主動公共健康行動。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":17},{"front":"urban areas","meaning":"市區","examples":[{"en":"Removing stagnant water is useful in urban areas.","zh":"清除積水在市區很有用。"},{"en":"Urban areas are towns and cities with many buildings, roads, and people.","zh":"urban areas 是有許多建築、道路和人口的城鎮和城市。"},{"en":"In urban areas, small containers can collect rainwater behind shops or flats.","zh":"在市區，小容器可能在商店或單位後方積聚雨水。"},{"en":"If mosquitoes breed in urban areas, many people may be exposed quickly.","zh":"如果蚊子在市區繁殖，許多人可能很快暴露於風險。"},{"en":"The phrase contrasts city environments with rural places.","zh":"這個片語把城市環境與鄉郊地區作對比。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":17},{"front":"dangerous species","meaning":"危險物種","examples":[{"en":"Many dangerous species breed in small pools of water.","zh":"許多危險物種在小水池中繁殖。"},{"en":"Dangerous species are kinds of organisms that can harm people, animals, or ecosystems.","zh":"dangerous species 是會傷害人、動物或生態系統的生物種類。"},{"en":"A beach notice may warn swimmers about dangerous species in the water.","zh":"海灘告示可能警告泳客水中有危險物種。"},{"en":"If dangerous mosquito species breed nearby, disease risk rises.","zh":"如果危險蚊種在附近繁殖，疾病風險會上升。"},{"en":"The phrase identifies harmful types of living things.","zh":"這個片語指出有害生物種類。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":17},{"front":"incidental ditches","meaning":"偶然形成的溝渠","examples":[{"en":"Some mosquitoes breed in incidental ditches.","zh":"有些蚊子在偶然形成的溝渠中繁殖。"},{"en":"Incidental ditches are small, unintended channels or holes where water may collect.","zh":"incidental ditches 是可能積水的小型、非刻意形成的渠道或坑洞。"},{"en":"Road repairs can leave incidental ditches beside the pavement.","zh":"道路維修可能在行人路旁留下偶然形成的溝渠。"},{"en":"If incidental ditches hold rainwater, they may become mosquito breeding sites.","zh":"如果這些溝渠積聚雨水，就可能成為蚊子繁殖地。"},{"en":"The phrase describes accidental drainage-like spaces.","zh":"這個片語描述意外形成的排水狀空間。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":17},{"front":"flowerpots","meaning":"花盆","examples":[{"en":"Rainwater may collect in flowerpots.","zh":"雨水可能積聚在花盆中。"},{"en":"Flowerpots are containers used for growing plants.","zh":"flowerpots 是用來種植植物的容器。"},{"en":"A balcony may have several flowerpots that need regular watering.","zh":"陽台可能有幾個需要定期澆水的花盆。"},{"en":"If water stays in flowerpots, mosquitoes may breed there.","zh":"如果水留在花盆中，蚊子可能在那裡繁殖。"},{"en":"The word names a common household container that can hold water.","zh":"這個詞指常見且可能積水的家居容器。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":18},{"front":"discarded containers","meaning":"被丟棄的容器","examples":[{"en":"Mosquitoes may breed in discarded containers.","zh":"蚊子可能在被丟棄的容器中繁殖。"},{"en":"Discarded containers are thrown-away items such as cups, tins, bottles, or boxes.","zh":"discarded containers 是被丟掉的杯、罐、瓶或盒等物品。"},{"en":"After a picnic, discarded containers may collect rainwater in a park.","zh":"野餐後，被丟棄的容器可能在公園積聚雨水。"},{"en":"If containers are left outdoors, they can become breeding sites for mosquitoes.","zh":"如果容器被留在戶外，它們可以成為蚊子繁殖地。"},{"en":"The phrase connects litter with public health risk.","zh":"這個片語把垃圾與公共健康風險連接起來。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":18},{"front":"rainwater has pooled","meaning":"雨水積聚","examples":[{"en":"Mosquitoes breed where rainwater has pooled.","zh":"蚊子在雨水積聚的地方繁殖。"},{"en":"Rainwater has pooled means rainwater has collected and stayed in one place.","zh":"rainwater has pooled 指雨水聚集並停留在一處。"},{"en":"After a storm, rainwater may have pooled on a flat roof.","zh":"暴風雨後，雨水可能在平屋頂上積聚。"},{"en":"If rainwater has pooled in containers, mosquitoes may lay eggs there.","zh":"如果雨水積聚在容器中，蚊子可能在那裡產卵。"},{"en":"The phrase describes standing water after rain.","zh":"這個片語描述雨後停留的積水。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":18},{"front":"eliminate such sites","meaning":"清除這類地方","examples":[{"en":"Eliminating such sites reduces mosquito numbers.","zh":"清除這類地方會減少蚊子數量。"},{"en":"Eliminate such sites means remove places like these where mosquitoes can breed.","zh":"eliminate such sites 指移除這些蚊子可繁殖的地方。"},{"en":"A housing estate can eliminate such sites by emptying buckets and clearing drains.","zh":"屋苑可以透過倒空水桶和清理渠口來清除這類地方。"},{"en":"If breeding sites are eliminated, fewer mosquitoes survive to bite people.","zh":"如果繁殖地被清除，較少蚊子能存活並叮咬人。"},{"en":"The phrase describes removing sources of a problem.","zh":"這個片語描述移除問題來源。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":18},{"front":"fall greatly","meaning":"大幅下降","examples":[{"en":"The insects’ numbers fall greatly when breeding sites are removed.","zh":"當繁殖地被移除，昆蟲數量會大幅下降。"},{"en":"Fall greatly means decrease by a large amount.","zh":"fall greatly 指大幅減少。"},{"en":"Electricity bills may fall greatly after a family installs efficient appliances.","zh":"家庭安裝高效電器後，電費可能大幅下降。"},{"en":"If mosquito breeding sites disappear, mosquito numbers can fall greatly.","zh":"如果蚊子繁殖地消失，蚊子數量可以大幅下降。"},{"en":"The phrase describes a strong reduction.","zh":"這個片語描述強烈減少。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":18},{"front":"limit bites to","meaning":"將叮咬限制於……","examples":[{"en":"Removing local breeding sites limits bites to mosquitoes from further afield.","zh":"清除本地繁殖地會將叮咬限制於來自較遠地方的蚊子。"},{"en":"Limit bites to means reduce bites so that only a particular source remains.","zh":"limit bites to 指減少叮咬，使只剩某一特定來源。"},{"en":"Cleaning a bedroom may limit insect bites to bugs entering from outside.","zh":"清潔睡房可能將昆蟲叮咬限制於從外面進入的蟲。"},{"en":"If local mosquitoes are removed, remaining bites may come only from farther areas.","zh":"如果本地蚊子被清除，剩下的叮咬可能只來自較遠地區。"},{"en":"The phrase narrows the source of a problem.","zh":"這個片語縮窄問題來源。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":18},{"front":"further afield","meaning":"較遠地方","examples":[{"en":"Some mosquitoes come from further afield.","zh":"有些蚊子來自較遠地方。"},{"en":"Further afield means from a more distant place.","zh":"further afield 指來自更遠的地方。"},{"en":"Students may look further afield for university options outside their city.","zh":"學生可能到較遠地方尋找本市以外的大學選項。"},{"en":"If local breeding sites are gone, mosquitoes from further afield may still occasionally arrive.","zh":"如果本地繁殖地消失，來自較遠地方的蚊子仍可能偶爾出現。"},{"en":"The phrase refers to places beyond the immediate area.","zh":"這個片語指眼前地區以外的地方。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":18},{"front":"the likelihood of being bitten","meaning":"被叮咬的可能性","examples":[{"en":"The likelihood of being bitten is greatly reduced.","zh":"被叮咬的可能性大大降低。"},{"en":"The likelihood of being bitten means the chance that a person will be bitten.","zh":"the likelihood of being bitten 指一個人被叮咬的機會。"},{"en":"Wearing long sleeves can reduce the likelihood of being bitten outdoors.","zh":"穿長袖可以減少在戶外被叮咬的可能性。"},{"en":"If mosquito numbers fall, the likelihood of being bitten also falls.","zh":"如果蚊子數量下降，被叮咬的可能性也下降。"},{"en":"The phrase describes risk or probability.","zh":"這個片語描述風險或概率。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":18},{"front":"be greatly reduced","meaning":"大大降低","examples":[{"en":"The risk of infection is greatly reduced.","zh":"感染風險大大降低。"},{"en":"Be greatly reduced means be made much lower.","zh":"be greatly reduced 指被大幅降低。"},{"en":"Waiting time can be greatly reduced if appointments are booked online.","zh":"如果網上預約，等候時間可以大大降低。"},{"en":"If mosquito bites are prevented, infection risk is greatly reduced.","zh":"如果蚊叮被預防，感染風險就大大降低。"},{"en":"The phrase describes a large decrease.","zh":"這個片語描述大幅減少。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":18},{"front":"agree with the information","meaning":"與資料一致","examples":[{"en":"Students decide whether each statement agrees with the information in the passage.","zh":"學生判斷每項陳述是否與文章資料一致。"},{"en":"Agree with the information means match what the text clearly says.","zh":"agree with the information 指與文本清楚說明的內容相符。"},{"en":"In a reading test, an answer agrees with the information only if the passage supports it.","zh":"在閱讀測驗中，只有文章支持答案，它才與資料一致。"},{"en":"If a statement changes a key detail, it may no longer agree with the information.","zh":"如果陳述改變關鍵細節，它可能不再與資料一致。"},{"en":"The phrase is common in TRUE, FALSE, NOT GIVEN tasks.","zh":"這個片語常見於 TRUE、FALSE、NOT GIVEN 題。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":18},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A statement is false if it contradicts the information.","zh":"如果陳述與資料相矛盾，它就是錯誤。"},{"en":"Contradict the information means say the opposite of what the passage states.","zh":"contradict the information 指說出與文章陳述相反的內容。"},{"en":"If a notice says the clinic opens at nine, “it opens at ten” contradicts the information.","zh":"如果告示說診所九點開門，「它十點開門」就與資料相矛盾。"},{"en":"If a statement contradicts the text, students should choose FALSE.","zh":"如果陳述與文本相矛盾，學生應選 FALSE。"},{"en":"The phrase is different from information that is simply not mentioned.","zh":"這個片語不同於資料沒有提及。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":19},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"Students choose NOT GIVEN if there is no information on this.","zh":"如果沒有相關資料，學生選 NOT GIVEN。"},{"en":"No information on this means the passage does not provide enough detail to decide.","zh":"no information on this 指文章沒有提供足夠細節作判斷。"},{"en":"If an article mentions mosquitoes but not their eyesight, there is no information on this point.","zh":"如果文章提到蚊子但沒有提到視力，就沒有這方面資料。"},{"en":"When there is no information, students should not use outside knowledge.","zh":"當沒有資料時，學生不應使用外部知識。"},{"en":"The phrase signals a NOT GIVEN answer.","zh":"這個片語表示答案是 NOT GIVEN。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":19},{"front":"mosquito blood","meaning":"蚊子的血液","examples":[{"en":"The question asks whether mosquito blood transmits disease.","zh":"題目問蚊子的血液是否傳播疾病。"},{"en":"Mosquito blood means blood inside or associated with a mosquito, though the passage focuses on saliva and parasites.","zh":"mosquito blood 指蚊子體內或與蚊子有關的血液，但文章重點在唾液和寄生蟲。"},{"en":"A student should not assume mosquito blood is the cause unless the passage says so.","zh":"除非文章這樣說，學生不應假設蚊子的血液是原因。"},{"en":"If a question mentions mosquito blood, careful readers check whether the text actually mentions it.","zh":"如果題目提到蚊子的血液，細心讀者會檢查文本是否真的提及。"},{"en":"The phrase is used here as a test detail, not as the passage’s main explanation.","zh":"這個片語在此作為測試細節，而不是文章主要解釋。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":19},{"front":"transmit disease","meaning":"傳播疾病","examples":[{"en":"The question asks whether mosquito blood can transmit disease.","zh":"題目問蚊子的血液能否傳播疾病。"},{"en":"Transmit disease means pass an illness from one organism to another.","zh":"transmit disease 指把疾病從一個生物傳給另一個生物。"},{"en":"Coughing can transmit disease if droplets reach other people.","zh":"如果飛沫傳到其他人，咳嗽可以傳播疾病。"},{"en":"If mosquitoes transmit disease through bites, preventing bites reduces risk.","zh":"如果蚊子透過叮咬傳播疾病，預防叮咬就降低風險。"},{"en":"The phrase describes spreading infection.","zh":"這個片語描述傳播感染。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":19},{"front":"good vision","meaning":"良好視力","examples":[{"en":"The statement asks whether mosquitoes have good vision.","zh":"該陳述問蚊子是否有良好視力。"},{"en":"Good vision means a strong ability to see clearly.","zh":"good vision 指清楚看見事物的強能力。"},{"en":"A driver needs good vision to notice pedestrians and road signs.","zh":"司機需要良好視力以注意行人和路牌。"},{"en":"If an animal relies more on smell than sight, good vision may not be the key issue.","zh":"如果動物更依賴嗅覺而不是視覺，良好視力未必是關鍵。"},{"en":"The phrase describes eyesight quality.","zh":"這個片語描述視力質素。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":19},{"front":"answer the questions","meaning":"回答問題","examples":[{"en":"Candidates answer the questions using words from the passage.","zh":"考生使用文章中的字詞回答問題。"},{"en":"Answer the questions means give the required responses to exam or study prompts.","zh":"answer the questions 指為考試或練習提示提供所需回答。"},{"en":"Students should read the instructions before they answer the questions.","zh":"學生回答問題前應閱讀指示。"},{"en":"If candidates answer from memory rather than the passage, they may lose marks.","zh":"如果考生憑記憶而不是文章作答，可能失分。"},{"en":"The phrase describes the basic task in an exercise.","zh":"這個片語描述練習中的基本任務。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":19},{"front":"one word only","meaning":"只選一個詞","examples":[{"en":"Candidates choose one word only from the passage.","zh":"考生只從文章中選一個詞。"},{"en":"One word only means the answer must contain exactly one word.","zh":"one word only 指答案必須只包含一個詞。"},{"en":"If the answer is “liver”, it follows the one word only rule.","zh":"如果答案是 liver，就符合只限一個詞的規則。"},{"en":"If candidates write two words, the answer may be marked wrong even if the idea is correct.","zh":"如果考生寫兩個詞，即使意思正確，也可能被判錯。"},{"en":"The phrase gives a strict exam word limit.","zh":"這個片語給出嚴格考試字數限制。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":19},{"front":"become inflamed","meaning":"發炎","examples":[{"en":"Mosquito bites can become inflamed.","zh":"蚊叮可能發炎。"},{"en":"Become inflamed means become red, swollen, painful, or irritated.","zh":"become inflamed 指變紅、腫脹、疼痛或受刺激。"},{"en":"A cut may become inflamed if dirt enters it.","zh":"如果污垢進入傷口，割傷可能發炎。"},{"en":"If a bite becomes inflamed, scratching can make it worse.","zh":"如果叮咬發炎，抓損會令它更嚴重。"},{"en":"The phrase describes a body reaction to injury or infection.","zh":"這個片語描述身體對傷害或感染的反應。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":19},{"front":"change shape","meaning":"改變形狀","examples":[{"en":"The question asks which disease causes the body to change shape.","zh":"題目問哪種疾病造成身體改變形狀。"},{"en":"Change shape means become physically different in form or outline.","zh":"change shape 指在形態或輪廓上變得不同。"},{"en":"A balloon changes shape when air is blown into it.","zh":"氣球被吹氣時會改變形狀。"},{"en":"If a disease causes swelling, a body part may change shape.","zh":"如果疾病造成腫脹，身體部位可能改變形狀。"},{"en":"The phrase describes visible physical change.","zh":"這個片語描述可見的身體變化。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":19},{"front":"affect an organ","meaning":"影響器官","examples":[{"en":"The question asks which organ yellow fever affects.","zh":"題目問黃熱病影響哪個器官。"},{"en":"Affect an organ means harm, damage, or change the function of a body part such as the liver or heart.","zh":"affect an organ 指傷害、損害或改變肝臟、心臟等身體部位的功能。"},{"en":"High blood pressure can affect an organ like the kidney over time.","zh":"高血壓隨時間可能影響腎臟等器官。"},{"en":"If a virus affects the liver, skin colour may change.","zh":"如果病毒影響肝臟，皮膚顏色可能改變。"},{"en":"The phrase links disease with a specific body part.","zh":"這個片語把疾病與特定身體部位連接起來。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":19},{"front":"exposed water","meaning":"外露積水","examples":[{"en":"Removing exposed water can reduce mosquito numbers.","zh":"清除外露積水可以減少蚊子數量。"},{"en":"Exposed water is uncovered water that insects can reach.","zh":"exposed water 是沒有蓋住、昆蟲能接觸到的水。"},{"en":"Water in an open bucket is exposed water.","zh":"開口水桶中的水就是外露積水。"},{"en":"If exposed water remains after rain, mosquitoes may use it for breeding.","zh":"如果雨後外露積水仍存在，蚊子可能用它繁殖。"},{"en":"The phrase describes water that is accessible and therefore risky.","zh":"這個片語描述可接觸而因此有風險的水。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":20},{"front":"particularly cheap way to","meaning":"特別便宜的方法去……","examples":[{"en":"Removing exposed water is a particularly cheap way to reduce mosquito numbers.","zh":"清除外露積水是減少蚊子數量的特別便宜方法。"},{"en":"Particularly cheap way to means an especially low-cost method for doing something.","zh":"particularly cheap way to 指做某事成本特別低的方法。"},{"en":"Turning off unused lights is a particularly cheap way to save electricity.","zh":"關掉不用的燈是節省電力的特別便宜方法。"},{"en":"If a cheap method works well, communities can use it widely.","zh":"如果便宜方法效果好，社區就能廣泛使用。"},{"en":"The phrase highlights low cost as a major advantage.","zh":"這個片語突出低成本這一主要優點。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":20},{"front":"reduce mosquito numbers","meaning":"減少蚊子數量","examples":[{"en":"Removing exposed water can reduce mosquito numbers.","zh":"清除外露積水可以減少蚊子數量。"},{"en":"Reduce mosquito numbers means lower the number of mosquitoes in an area.","zh":"reduce mosquito numbers 指降低某地區蚊子的數量。"},{"en":"Cleaning drains and emptying containers can reduce mosquito numbers near homes.","zh":"清理渠口和倒空容器可以減少住宅附近蚊子數量。"},{"en":"If mosquito numbers fall, fewer people are bitten.","zh":"如果蚊子數量下降，較少人會被叮。"},{"en":"The phrase describes a key goal of mosquito control.","zh":"這個片語描述滅蚊工作的關鍵目標。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":20},{"front":"complete the summary","meaning":"完成摘要","examples":[{"en":"Candidates complete the summary using words from the passage.","zh":"考生使用文章中的字詞完成摘要。"},{"en":"Complete the summary means fill in missing words in a shortened version of the text.","zh":"complete the summary 指在文本簡短版本中填入缺失字詞。"},{"en":"In reading practice, students complete the summary by locating key details.","zh":"在閱讀練習中，學生透過定位關鍵細節完成摘要。"},{"en":"If the word limit is ignored, a correct idea may still be marked wrong.","zh":"如果忽視字數限制，意思正確仍可能被判錯。"},{"en":"The phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":20},{"front":"large undertaking","meaning":"大型工程","examples":[{"en":"The Panama Canal was a large undertaking.","zh":"巴拿馬運河是一項大型工程。"},{"en":"A large undertaking is a big, difficult project requiring serious effort and resources.","zh":"large undertaking 是需要大量努力和資源的大型困難項目。"},{"en":"Moving a whole school to a new campus is a large undertaking.","zh":"把整間學校搬到新校園是一項大型工程。"},{"en":"If an undertaking is large, poor health or safety planning can delay it badly.","zh":"如果工程規模龐大，健康或安全規劃差可以嚴重延誤它。"},{"en":"The phrase stresses scale and difficulty.","zh":"這個片語強調規模和難度。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":20},{"front":"full of insects","meaning":"充滿昆蟲","examples":[{"en":"The Panama Canal project took place in an area full of insects.","zh":"巴拿馬運河工程在一個充滿昆蟲的地區進行。"},{"en":"Full of insects means containing many insects.","zh":"full of insects 指含有大量昆蟲。"},{"en":"A rubbish area after rain may be full of insects.","zh":"雨後的垃圾區可能充滿昆蟲。"},{"en":"If a workplace is full of insects, workers may face bites and disease risk.","zh":"如果工作場所充滿昆蟲，工人可能面對叮咬和疾病風險。"},{"en":"The phrase describes heavy insect presence.","zh":"這個片語描述昆蟲大量存在。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":20},{"front":"greatly reduced by disease","meaning":"因疾病而大幅減少","examples":[{"en":"The number of workers was greatly reduced by disease.","zh":"工人數量因疾病而大幅減少。"},{"en":"Greatly reduced by disease means made much smaller because many people became ill or died.","zh":"greatly reduced by disease 指因許多人患病或死亡而大幅減少。"},{"en":"A football team may be greatly reduced by illness before an important match.","zh":"重要比賽前，足球隊可能因疾病而人手大減。"},{"en":"If a workforce is reduced by disease, progress slows and expertise is lost.","zh":"如果勞動隊伍因疾病而減少，進度會放慢，經驗也會流失。"},{"en":"The phrase shows disease as the cause of a major decrease.","zh":"這個片語顯示疾病是大幅減少的原因。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":20},{"front":"breeding sites","meaning":"繁殖地","examples":[{"en":"Exposed water was removed to deny mosquitoes breeding sites.","zh":"外露積水被清除，以不讓蚊子有繁殖地。"},{"en":"Breeding sites are places where animals or insects reproduce.","zh":"breeding sites 是動物或昆蟲繁殖的地方。"},{"en":"Old tyres filled with rainwater can become mosquito breeding sites.","zh":"積滿雨水的舊輪胎可以成為蚊子繁殖地。"},{"en":"If breeding sites are removed, fewer young mosquitoes survive.","zh":"如果繁殖地被清除，較少幼蚊能存活。"},{"en":"The phrase identifies the places that allow population growth.","zh":"這個片語指出讓族群增長的地方。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":20},{"front":"relatively low number of deaths","meaning":"相對較低的死亡人數","examples":[{"en":"The programme led to a relatively low number of deaths.","zh":"該計劃導致相對較低的死亡人數。"},{"en":"Relatively low number of deaths means fewer deaths compared with another case or expectation.","zh":"relatively low number of deaths 指與另一情況或預期相比死亡較少。"},{"en":"A safer road design may lead to a relatively low number of accidents.","zh":"更安全的道路設計可能帶來相對較低的意外數量。"},{"en":"If earlier work killed many people, a lower later death toll may be seen as success.","zh":"如果早期工程殺死很多人，後來較低死亡人數可能被視為成功。"},{"en":"The phrase compares death numbers rather than saying there were no deaths.","zh":"這個片語比較死亡數字，而不是說沒有死亡。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":20},{"front":"be attributed to","meaning":"歸因於……","examples":[{"en":"The lower death toll was attributed to the control strategies.","zh":"較低死亡人數被歸因於控制策略。"},{"en":"Be attributed to means be explained as being caused by something.","zh":"be attributed to 指被解釋為由某事造成。"},{"en":"A student’s improvement may be attributed to regular practice and better feedback.","zh":"學生的進步可能歸因於定期練習和更好回饋。"},{"en":"If deaths fall after mosquito control, the improvement may be attributed to those measures.","zh":"如果滅蚊後死亡人數下降，改善可能被歸因於那些措施。"},{"en":"The phrase links an outcome with its likely cause.","zh":"這個片語把結果與可能原因連接起來。"}],"source":"86 - The Most Dangerous Insect in the World.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 87":[{"front":"Esperanto","meaning":"世界語","examples":[{"en":"Esperanto remains the most widely spoken constructed auxiliary language.","zh":"世界語仍然是最廣泛使用的人造輔助語言。"},{"en":"Esperanto is an artificial language created to help people from different language backgrounds communicate.","zh":"世界語是一種人工語言，旨在幫助來自不同語言背景的人溝通。"},{"en":"A student interested in world cultures may learn Esperanto to meet speakers from many countries.","zh":"對世界文化感興趣的學生可能學習世界語，以認識來自許多國家的使用者。"},{"en":"Because Esperanto was designed with regular grammar, some learners find it easier than many national languages.","zh":"因為世界語被設計成有規則文法，一些學習者覺得它比許多民族語言更容易。"},{"en":"The word refers to the language itself, not to the community or movement only.","zh":"這個詞指該語言本身，而不只是其社群或運動。"}],"source":"87 - Esperanto.pdf","sourcePage":1},{"front":"Ĉu vi parolas Esperanton?","meaning":"你會說世界語嗎？","examples":[{"en":"“Ĉu vi parolas Esperanton?” means “Do you speak Esperanto?”","zh":"“Ĉu vi parolas Esperanton?” 的意思是「你會說世界語嗎？」"},{"en":"“Ĉu vi parolas Esperanton?” is a basic question used to ask whether someone can speak Esperanto.","zh":"“Ĉu vi parolas Esperanton?” 是用來詢問某人是否會說世界語的基本問題。"},{"en":"A traveller at an Esperanto meeting might begin a conversation by asking, “Ĉu vi parolas Esperanton?”","zh":"旅客在世界語聚會中可能以 “Ĉu vi parolas Esperanton?” 開始對話。"},{"en":"If the other person understands the question, they may reply in Esperanto and continue the conversation.","zh":"如果對方明白這個問題，他們可能用世界語回覆並繼續對話。"},{"en":"The phrase is useful because it shows Esperanto as a real language for communication.","zh":"這個短語很有用，因為它顯示世界語是一種真正用於溝通的語言。"}],"source":"87 - Esperanto.pdf","sourcePage":1},{"front":"be expected to","meaning":"被期望去……","examples":[{"en":"Should ordinary readers be expected to understand Esperanto?","zh":"普通讀者是否應被期望去理解世界語？"},{"en":"To be expected to do something means people think you should be able or willing to do it.","zh":"“Be expected to” 做某事指別人認為你應該能夠或願意做該事。"},{"en":"Students are expected to bring their books to class every day.","zh":"學生被期望每天帶書上課。"},{"en":"If a language is not widely taught, ordinary readers cannot be expected to understand it.","zh":"如果一種語言沒有被廣泛教授，就不能期望普通讀者理解它。"},{"en":"The phrase often shows a social or practical expectation.","zh":"這個短語常顯示社會或實際期望。"}],"source":"87 - Esperanto.pdf","sourcePage":1},{"front":"depending on who you ask","meaning":"視乎你問誰而定","examples":[{"en":"Depending on who you ask, the number of Esperanto speakers varies greatly.","zh":"視乎你問誰而定，世界語使用者人數差異很大。"},{"en":"Depending on who you ask means the answer changes according to the person giving the information.","zh":"“Depending on who you ask” 指答案會根據提供資料的人而改變。"},{"en":"Depending on who you ask, a restaurant may be described as cheap, expensive or fairly priced.","zh":"視乎你問誰而定，一間餐廳可能被形容為便宜、昂貴或價錢合理。"},{"en":"If experts use different definitions, the estimate of speaker numbers may change greatly.","zh":"如果專家使用不同定義，使用者人數估計可能大幅改變。"},{"en":"The phrase warns that an answer is uncertain or influenced by perspective.","zh":"這個短語提醒答案不確定，或受觀點影響。"}],"source":"87 - Esperanto.pdf","sourcePage":1},{"front":"between…and…","meaning":"介乎……與……之間","examples":[{"en":"Between 10,000 and two million people may understand Esperanto.","zh":"可能有介乎一萬與二百萬之間的人理解世界語。"},{"en":"Between one number and another gives a range with a lower and upper limit.","zh":"“Between…and…” 給出一個有下限和上限的範圍。"},{"en":"A small language class may have between ten and fifteen students.","zh":"小型語言班可能有介乎十至十五名學生。"},{"en":"If estimates are between 10,000 and two million, the exact number is clearly uncertain.","zh":"如果估計介乎一萬與二百萬之間，準確數字明顯不確定。"},{"en":"The phrase is useful when figures cannot be given precisely.","zh":"當數字不能精確給出時，這個短語很有用。"}],"source":"87 - Esperanto.pdf","sourcePage":1},{"front":"in places all over the world","meaning":"在世界各地","examples":[{"en":"Esperanto speakers can be found in places all over the world.","zh":"世界語使用者可以在世界各地找到。"},{"en":"In places all over the world means in many different countries or regions globally.","zh":"“In places all over the world” 指在全球許多不同國家或地區。"},{"en":"English learners can be found in places all over the world, from cities to small towns.","zh":"英語學習者可以在世界各地找到，從城市到小鎮都有。"},{"en":"If speakers live in places all over the world, the language has an international community.","zh":"如果使用者生活在世界各地，該語言就有國際社群。"},{"en":"The phrase stresses wide geographical spread, not necessarily large numbers.","zh":"這個短語強調地理分布廣泛，不一定表示人數很多。"}],"source":"87 - Esperanto.pdf","sourcePage":1},{"front":"presumably","meaning":"大概；想必","examples":[{"en":"Some people could understand the sentence and presumably reply in Esperanto.","zh":"有些人能理解這句話，並大概能用世界語回覆。"},{"en":"Presumably means probably, based on what seems reasonable or likely.","zh":"“Presumably” 指根據合理或可能的情況推測，大概如此。"},{"en":"If the lights are off and the door is locked, the shop is presumably closed.","zh":"如果燈關了而門鎖上了，店舖大概已關門。"},{"en":"If someone understands Esperanto, they can presumably answer a simple Esperanto question.","zh":"如果某人理解世界語，想必能回答一條簡單的世界語問題。"},{"en":"The word shows a reasonable guess, not absolute certainty.","zh":"這個詞表示合理猜測，而不是絕對確定。"}],"source":"87 - Esperanto.pdf","sourcePage":1},{"front":"reply in the same language","meaning":"用同一種語言回覆","examples":[{"en":"Esperanto speakers could reply in the same language.","zh":"世界語使用者可以用同一種語言回覆。"},{"en":"To reply in the same language means to answer using the language that was used first.","zh":"“Reply in the same language” 指使用對方最初使用的語言回答。"},{"en":"If a customer asks a question in English, the assistant may reply in the same language.","zh":"如果顧客用英語提問，店員可能用同一種語言回覆。"},{"en":"When both speakers use the same language, communication usually becomes smoother.","zh":"當雙方使用同一種語言，溝通通常更順暢。"},{"en":"The phrase describes matching the language of the first speaker.","zh":"這個短語描述配合第一位說話者的語言。"}],"source":"87 - Esperanto.pdf","sourcePage":1},{"front":"evolve through","meaning":"透過……演變","examples":[{"en":"Esperanto did not evolve through any natural process.","zh":"世界語並非透過任何自然過程演變而來。"},{"en":"To evolve through a process means to develop gradually by passing through that process.","zh":"“Evolve through” 某過程指透過該過程逐漸發展。"},{"en":"A local dialect may evolve through daily use by many generations of speakers.","zh":"本地方言可能透過幾代人的日常使用而演變。"},{"en":"Esperanto did not evolve through normal community use at first; it was deliberately designed.","zh":"世界語起初不是透過普通社群使用演變而來，而是被刻意設計出來。"},{"en":"The phrase is useful when explaining how something develops over time.","zh":"這個短語適合解釋某事如何隨時間發展。"}],"source":"87 - Esperanto.pdf","sourcePage":1},{"front":"natural process","meaning":"自然過程","examples":[{"en":"Esperanto did not develop through a natural process.","zh":"世界語並非透過自然過程發展而來。"},{"en":"A natural process is something that develops gradually without deliberate human design.","zh":"自然過程是沒有刻意人為設計而逐漸發展的事情。"},{"en":"Children’s accents often change through the natural process of hearing people around them.","zh":"兒童口音常透過聆聽身邊人的自然過程而改變。"},{"en":"If a language grows through daily use over centuries, that is a natural process.","zh":"如果一種語言經過數百年的日常使用而成長，那就是自然過程。"},{"en":"The phrase contrasts natural development with planned invention.","zh":"這個短語把自然發展與有計劃發明作對比。"}],"source":"87 - Esperanto.pdf","sourcePage":1},{"front":"to give it its technical name","meaning":"用其專業名稱來說","examples":[{"en":"To give it its technical name, Esperanto is a constructed auxiliary language.","zh":"用其專業名稱來說，世界語是一種人造輔助語言。"},{"en":"To give something its technical name means to use the formal specialist term for it.","zh":"“To give something its technical name” 指使用某事的正式專業術語。"},{"en":"To give it its technical name, a fear of spiders is called arachnophobia.","zh":"用其專業名稱來說，怕蜘蛛稱為 arachnophobia。"},{"en":"If a writer uses a technical name, readers may understand the concept more precisely.","zh":"如果作者使用專業名稱，讀者可能更精確地理解概念。"},{"en":"The phrase introduces a more formal or academic label.","zh":"這個短語引出較正式或學術的標籤。"}],"source":"87 - Esperanto.pdf","sourcePage":1},{"front":"technical name","meaning":"專業名稱","examples":[{"en":"The technical name for Esperanto is a constructed auxiliary language.","zh":"世界語的專業名稱是人造輔助語言。"},{"en":"A technical name is the formal term used by specialists for a thing or idea.","zh":"專業名稱是專家用來稱呼某物或概念的正式術語。"},{"en":"The technical name for a “heart attack” is myocardial infarction.","zh":"“Heart attack” 的專業名稱是 myocardial infarction。"},{"en":"If students learn the technical name, they can discuss the topic more accurately.","zh":"如果學生學會專業名稱，就能更準確地討論題目。"},{"en":"The phrase contrasts everyday language with specialist terminology.","zh":"這個短語把日常語言與專業術語作對比。"}],"source":"87 - Esperanto.pdf","sourcePage":2},{"front":"constructed auxiliary language","meaning":"人造輔助語言","examples":[{"en":"Esperanto is a constructed auxiliary language.","zh":"世界語是一種人造輔助語言。"},{"en":"A constructed auxiliary language is a planned language created to help people communicate across language boundaries.","zh":"人造輔助語言是被計劃創造出來，用來幫助人跨越語言界限溝通的語言。"},{"en":"A constructed auxiliary language may have regular grammar to make learning easier.","zh":"人造輔助語言可能有規則文法，使學習更容易。"},{"en":"If people from different countries use such a language, it can act as a neutral second language.","zh":"如果來自不同國家的人使用這種語言，它可以作為中立第二語言。"},{"en":"The phrase combines design, communication and international use.","zh":"這個短語結合設計、溝通和國際用途。"}],"source":"87 - Esperanto.pdf","sourcePage":2},{"front":"more specifically","meaning":"更準確地說","examples":[{"en":"More specifically, the language is Esperanto.","zh":"更準確地說，這種語言是世界語。"},{"en":"More specifically means giving a more exact or detailed description.","zh":"“More specifically” 指給出更精確或更詳細的描述。"},{"en":"I study science; more specifically, I study marine biology.","zh":"我讀科學；更準確地說，我讀海洋生物學。"},{"en":"If a general term is unclear, “more specifically” helps narrow it down.","zh":"如果一般詞語不夠清楚，“more specifically” 可以幫助收窄意思。"},{"en":"The phrase moves from a broad idea to a precise one.","zh":"這個短語由廣泛想法轉向精確說法。"}],"source":"87 - Esperanto.pdf","sourcePage":2},{"front":"out of the several attempts to","meaning":"在多次嘗試……之中","examples":[{"en":"Out of several attempts to create artificial languages, Esperanto is the most widely spoken.","zh":"在多次創造人工語言的嘗試之中，世界語是最廣泛使用的。"},{"en":"Out of several attempts to do something means among the different efforts made to achieve it.","zh":"“Out of several attempts to” 做某事指在為達成該事而作出的不同努力之中。"},{"en":"Out of several attempts to open a café, only one became profitable.","zh":"在多次開咖啡店的嘗試之中，只有一次變得有利可圖。"},{"en":"If many people tried to create artificial languages, Esperanto stands out as the most successful.","zh":"如果許多人嘗試創造人工語言，世界語作為最成功者顯得突出。"},{"en":"The phrase compares one result with several similar efforts.","zh":"這個短語把一個結果與幾個相似努力作比較。"}],"source":"87 - Esperanto.pdf","sourcePage":2},{"front":"throughout modern history","meaning":"在整個現代歷史中","examples":[{"en":"Several artificial languages have been created throughout modern history.","zh":"在整個現代歷史中，有幾種人工語言被創造出來。"},{"en":"Throughout modern history means during many different periods in recent centuries.","zh":"“Throughout modern history” 指在近幾個世紀的許多不同時期。"},{"en":"Throughout modern history, people have invented new tools to improve communication.","zh":"在整個現代歷史中，人們發明了新工具來改善溝通。"},{"en":"If an idea appears throughout modern history, it has attracted repeated interest over time.","zh":"如果一個想法在整個現代歷史中出現，它就長期反覆吸引興趣。"},{"en":"The phrase refers to a long span, not one single date.","zh":"這個短語指長時間跨度，而不是單一日期。"}],"source":"87 - Esperanto.pdf","sourcePage":2},{"front":"create artificial languages","meaning":"創造人工語言","examples":[{"en":"Many people have attempted to create artificial languages.","zh":"許多人曾嘗試創造人工語言。"},{"en":"To create artificial languages means to design new languages deliberately rather than inherit them naturally.","zh":"“Create artificial languages” 指刻意設計新語言，而不是自然繼承語言。"},{"en":"A linguist may create an artificial language for a film, game or international project.","zh":"語言學家可能為電影、遊戲或國際項目創造人工語言。"},{"en":"If people create artificial languages, they can make grammar more regular than in natural languages.","zh":"如果人們創造人工語言，他們可以令文法比自然語言更有規則。"},{"en":"The phrase describes planned language invention.","zh":"這個短語描述有計劃的語言發明。"}],"source":"87 - Esperanto.pdf","sourcePage":2},{"front":"artificial languages","meaning":"人工語言","examples":[{"en":"Esperanto is one of several artificial languages.","zh":"世界語是幾種人工語言之一。"},{"en":"Artificial languages are languages deliberately invented by people rather than developed naturally by communities.","zh":"人工語言是由人刻意發明，而不是由社群自然發展出來的語言。"},{"en":"Some artificial languages are made for stories, while others are made for international communication.","zh":"一些人工語言為故事而製作，另一些則為國際溝通而製作。"},{"en":"If an artificial language has regular rules, learners may find it easier to start.","zh":"如果人工語言有規則文法，學習者可能覺得較容易開始。"},{"en":"The phrase contrasts invented languages with natural languages.","zh":"這個短語把被發明的語言與自然語言作對比。"}],"source":"87 - Esperanto.pdf","sourcePage":2},{"front":"the most widely spoken","meaning":"最廣泛使用的","examples":[{"en":"Esperanto remains the most widely spoken artificial language.","zh":"世界語仍然是最廣泛使用的人工語言。"},{"en":"The most widely spoken means used by more speakers than others in the same group.","zh":"“The most widely spoken” 指在同類中由最多使用者使用。"},{"en":"English is one of the most widely spoken languages in international business.","zh":"英語是國際商業中最廣泛使用的語言之一。"},{"en":"If Esperanto is the most widely spoken artificial language, it has more users than rival planned languages.","zh":"如果世界語是最廣泛使用的人工語言，它就比競爭的人造語言有更多使用者。"},{"en":"The phrase compares speaker numbers within a category.","zh":"這個短語比較同一類別中的使用者數量。"}],"source":"87 - Esperanto.pdf","sourcePage":2},{"front":"a relative term","meaning":"相對而言的說法","examples":[{"en":"“Widely spoken” is a relative term here.","zh":"在這裏，“widely spoken” 是相對而言的說法。"},{"en":"A relative term is a word or phrase whose meaning depends on comparison or context.","zh":"相對而言的說法，是意思取決於比較或語境的詞語或短語。"},{"en":"“Expensive” is a relative term because a meal may be costly to one person but cheap to another.","zh":"“Expensive” 是相對而言的說法，因為一餐對某人可能昂貴，對另一人卻便宜。"},{"en":"If Esperanto is widely spoken only compared with other artificial languages, the phrase needs context.","zh":"如果世界語只是相比其他人工語言而言使用廣泛，這個說法就需要語境。"},{"en":"The phrase warns readers not to take a description too absolutely.","zh":"這個短語提醒讀者不要把描述理解得太絕對。"}],"source":"87 - Esperanto.pdf","sourcePage":2},{"front":"compared to","meaning":"與……相比","examples":[{"en":"Compared to any natural language, Esperanto has few speakers.","zh":"與任何自然語言相比，世界語使用者很少。"},{"en":"Compared to means when measured or judged against something else.","zh":"“Compared to” 指與另一事物衡量或判斷時。"},{"en":"Compared to a car, a bicycle is cheaper to buy and easier to park.","zh":"與汽車相比，單車購買較便宜，也較容易泊車。"},{"en":"If Esperanto is compared to English or Spanish, its speaker base seems very small.","zh":"如果世界語與英語或西班牙語相比，其使用者基礎顯得很小。"},{"en":"The phrase introduces a comparison standard.","zh":"這個短語引入比較標準。"}],"source":"87 - Esperanto.pdf","sourcePage":2},{"front":"natural language","meaning":"自然語言","examples":[{"en":"Esperanto has fewer speakers than any major natural language.","zh":"世界語使用者比任何主要自然語言都少。"},{"en":"A natural language is a language that developed through normal use by a community over time.","zh":"自然語言是由社群長期正常使用而發展出來的語言。"},{"en":"Cantonese, English and Italian are natural languages because they were not invented by one designer.","zh":"粵語、英語和意大利語都是自然語言，因為它們不是由一位設計者發明的。"},{"en":"Natural languages often have irregular grammar because they evolved through history.","zh":"自然語言常有不規則文法，因為它們經歷歷史演變。"},{"en":"The phrase contrasts with constructed or artificial languages.","zh":"這個短語與人造或人工語言形成對比。"}],"source":"87 - Esperanto.pdf","sourcePage":2},{"front":"pitiably small","meaning":"少得可憐","examples":[{"en":"The number of Esperanto speakers remains pitiably small.","zh":"世界語使用者人數仍然少得可憐。"},{"en":"Pitiably small means extremely small in a way that seems disappointing or unfortunate.","zh":"“Pitiably small” 指小到令人失望或可惜。"},{"en":"A charity event may receive a pitiably small number of donations if nobody hears about it.","zh":"如果沒有人知道慈善活動，它收到的捐款數量可能少得可憐。"},{"en":"If a language aims to be global but has few speakers, its speaker base may seem pitiably small.","zh":"如果一種語言目標是全球通用，但使用者很少，其使用者基礎可能顯得少得可憐。"},{"en":"The phrase expresses judgement, not just a neutral number.","zh":"這個短語表達評價，而不只是中性數字。"}],"source":"87 - Esperanto.pdf","sourcePage":3},{"front":"a far cry from","meaning":"與……相差甚遠","examples":[{"en":"The current number of speakers is a far cry from Zamenhof’s hopes.","zh":"目前使用者人數與 Zamenhof 的期望相差甚遠。"},{"en":"A far cry from something means very different from it, usually much less successful or impressive.","zh":"“A far cry from” 某事指與它非常不同，通常遠不如它成功或令人印象深刻。"},{"en":"A small classroom performance is a far cry from a professional concert hall production.","zh":"小型課室表演與專業音樂廳製作相差甚遠。"},{"en":"If Esperanto aimed to unite the world but remains marginal, reality is a far cry from the dream.","zh":"如果世界語旨在團結世界，但仍然邊緣化，現實就與夢想相差甚遠。"},{"en":"The phrase highlights a large gap between expectation and reality.","zh":"這個短語強調期望與現實之間的巨大差距。"}],"source":"87 - Esperanto.pdf","sourcePage":3},{"front":"high hopes","meaning":"厚望；很高期望","examples":[{"en":"Zamenhof had high hopes for Esperanto.","zh":"Zamenhof 對世界語寄予厚望。"},{"en":"High hopes are strong expectations that something will succeed or improve the future.","zh":"厚望是對某事會成功或改善未來的強烈期待。"},{"en":"Parents may have high hopes when their child begins a new school.","zh":"當孩子入讀新學校，父母可能抱有很高期望。"},{"en":"If people have high hopes for a project, disappointment can be strong when results are small.","zh":"如果人們對項目寄予厚望，而結果很小，失望可能很強烈。"},{"en":"The phrase shows optimism and expectation.","zh":"這個短語顯示樂觀和期待。"}],"source":"87 - Esperanto.pdf","sourcePage":3},{"front":"inventor","meaning":"發明者","examples":[{"en":"Dr Ludwig Zamenhof was the inventor of Esperanto.","zh":"Ludwig Zamenhof 醫生是世界語的發明者。"},{"en":"An inventor is someone who creates something new, such as a device, system or idea.","zh":"發明者是創造新事物的人，例如裝置、系統或想法。"},{"en":"The inventor of a useful app may spend years testing and improving it.","zh":"一個實用應用程式的發明者可能花多年測試和改良它。"},{"en":"If an inventor designs a language, the language begins as a planned creation.","zh":"如果發明者設計一種語言，該語言最初就是有計劃的創造物。"},{"en":"The word identifies the person who first created something.","zh":"這個詞指出最初創造某物的人。"}],"source":"87 - Esperanto.pdf","sourcePage":3},{"front":"eye doctor","meaning":"眼科醫生","examples":[{"en":"Zamenhof was an eye doctor from Eastern Europe.","zh":"Zamenhof 是來自東歐的眼科醫生。"},{"en":"An eye doctor is a medical professional who treats problems with eyes and vision.","zh":"眼科醫生是治療眼睛和視力問題的醫療專業人士。"},{"en":"A child may visit an eye doctor if they cannot see the board clearly.","zh":"如果孩子看不清楚黑板，可能要去看眼科醫生。"},{"en":"If an eye doctor creates a language, it shows the inventor was not only a language specialist.","zh":"如果眼科醫生創造一種語言，這顯示發明者不只是語言專家。"},{"en":"The phrase refers to Zamenhof’s profession.","zh":"這個短語指 Zamenhof 的職業。"}],"source":"87 - Esperanto.pdf","sourcePage":3},{"front":"grow up in","meaning":"在……長大","examples":[{"en":"Zamenhof grew up in the town of Bialystok.","zh":"Zamenhof 在 Bialystok 鎮長大。"},{"en":"To grow up in a place means to spend one’s childhood or youth there.","zh":"“Grow up in” 某地指在該地度過童年或青年時期。"},{"en":"A person who grows up in a multilingual city may hear several languages every day.","zh":"在多語城市長大的人每天可能聽到幾種語言。"},{"en":"If Zamenhof grew up among divided communities, that experience may have shaped his language ideals.","zh":"如果 Zamenhof 在分裂社群中長大，這種經驗可能塑造他的語言理想。"},{"en":"The phrase connects childhood environment with later development.","zh":"這個短語把童年環境與後來發展連繫起來。"}],"source":"87 - Esperanto.pdf","sourcePage":3},{"front":"racially divided","meaning":"種族分化的","examples":[{"en":"Zamenhof grew up in a racially divided town.","zh":"Zamenhof 在一個種族分化的城鎮長大。"},{"en":"Racially divided means separated by ethnic or racial identity, often with tension or conflict.","zh":"“Racially divided” 指按族裔或種族身份分隔，通常伴隨緊張或衝突。"},{"en":"A racially divided neighbourhood may have groups who rarely mix or trust one another.","zh":"種族分化的社區可能有很少互相交流或信任的群體。"},{"en":"If a town is racially divided, language differences may deepen social separation.","zh":"如果城鎮種族分化，語言差異可能加深社會分隔。"},{"en":"The phrase describes social division based on identity.","zh":"這個短語描述基於身份的社會分裂。"}],"source":"87 - Esperanto.pdf","sourcePage":3},{"front":"Eastern European town","meaning":"東歐城鎮","examples":[{"en":"Bialystok was an Eastern European town.","zh":"Bialystok 是一個東歐城鎮。"},{"en":"An Eastern European town is a town located in the eastern part of Europe.","zh":"東歐城鎮是位於歐洲東部的城鎮。"},{"en":"An Eastern European town may have histories shaped by several empires, languages and communities.","zh":"東歐城鎮的歷史可能受幾個帝國、語言和社群塑造。"},{"en":"If a town lies between different cultural groups, its residents may speak many languages.","zh":"如果城鎮位於不同文化群體之間，居民可能說多種語言。"},{"en":"The phrase gives geographical and historical setting.","zh":"這個短語提供地理和歷史背景。"}],"source":"87 - Esperanto.pdf","sourcePage":3},{"front":"complex and uneasy mixture","meaning":"複雜而緊張的混合","examples":[{"en":"Bialystok contained a complex and uneasy mixture of ethnic groups.","zh":"Bialystok 包含複雜而緊張的族裔群體混合。"},{"en":"A complex and uneasy mixture is a combination of different groups or elements that creates tension or difficulty.","zh":"複雜而緊張的混合，是不同群體或元素結合而造成緊張或困難。"},{"en":"A school with many new policies may face a complex and uneasy mixture of expectations.","zh":"有許多新政策的學校可能面對複雜而緊張的期望混合。"},{"en":"If several communities share one town but mistrust one another, daily life can feel uneasy.","zh":"如果幾個社群共處一城卻互不信任，日常生活可能感到不安。"},{"en":"The phrase suggests diversity together with discomfort.","zh":"這個短語暗示多樣性與不安同時存在。"}],"source":"87 - Esperanto.pdf","sourcePage":3},{"front":"Poles, Jews, Russians, and Germans","meaning":"波蘭人、猶太人、俄羅斯人和德國人","examples":[{"en":"Poles, Jews, Russians, and Germans lived in Zamenhof’s hometown.","zh":"波蘭人、猶太人、俄羅斯人和德國人住在 Zamenhof 的家鄉。"},{"en":"Poles, Jews, Russians, and Germans names four ethnic or national groups in the town.","zh":"波蘭人、猶太人、俄羅斯人和德國人指該城鎮中的四個族裔或民族群體。"},{"en":"A history lesson may discuss Poles, Jews, Russians and Germans to explain Eastern Europe’s diversity.","zh":"歷史課可能討論波蘭人、猶太人、俄羅斯人和德國人，以解釋東歐的多元性。"},{"en":"If these groups spoke different languages, communication in the town could become difficult.","zh":"如果這些群體說不同語言，城鎮中的溝通可能變得困難。"},{"en":"The phrase identifies the communities that shaped Zamenhof’s early environment.","zh":"這個短語指出塑造 Zamenhof 早年環境的社群。"}],"source":"87 - Esperanto.pdf","sourcePage":3},{"front":"each speaking their own language","meaning":"各自說自己的語言","examples":[{"en":"The groups lived together, each speaking their own language.","zh":"這些群體共同生活，各自說自己的語言。"},{"en":"Each speaking their own language means every group used its separate language rather than a shared one.","zh":"“Each speaking their own language” 指每個群體使用自己的語言，而不是共同語言。"},{"en":"In an international hostel, travellers may sit together, each speaking their own language.","zh":"在國際青年旅舍中，旅客可能坐在一起，各自說自己的語言。"},{"en":"If neighbours each speak their own language, misunderstandings may become more likely.","zh":"如果鄰居各自說自己的語言，誤解可能更容易出現。"},{"en":"The phrase highlights coexistence without shared communication.","zh":"這個短語強調共處但沒有共同溝通工具。"}],"source":"87 - Esperanto.pdf","sourcePage":3},{"front":"idealistic","meaning":"理想主義的","examples":[{"en":"The idealistic Zamenhof wanted to create a neutral language.","zh":"理想主義的 Zamenhof 想創造一種中立語言。"},{"en":"Idealistic means guided by high hopes about how the world should be improved.","zh":"“Idealistic” 指受改善世界的崇高期望引導。"},{"en":"An idealistic student may start a recycling club because she believes the school can change.","zh":"理想主義的學生可能創立回收社，因為她相信學校可以改變。"},{"en":"If someone is idealistic, they may work for a goal that others think is unrealistic.","zh":"如果某人理想主義，他可能為別人認為不現實的目標努力。"},{"en":"The word can be positive, but it may also suggest too much optimism.","zh":"這個詞可以是正面的，但也可能暗示過度樂觀。"}],"source":"87 - Esperanto.pdf","sourcePage":4},{"front":"lamented how","meaning":"慨嘆……如何","examples":[{"en":"Zamenhof lamented how language divided the city’s residents.","zh":"Zamenhof 慨嘆語言如何分化城市居民。"},{"en":"To lament how something happens means to express sadness or regret about the way it happens.","zh":"“Lament how” 某事發生指對其發生方式表達悲傷或遺憾。"},{"en":"A teacher may lament how phones distract students during lessons.","zh":"老師可能慨嘆手機如何在課堂上分散學生注意力。"},{"en":"If Zamenhof lamented language division, he saw language as a cause of social pain.","zh":"如果 Zamenhof 慨嘆語言分化，他就把語言視為社會痛苦的原因。"},{"en":"The phrase expresses regret, not just neutral description.","zh":"這個短語表達遺憾，而不只是中性描述。"}],"source":"87 - Esperanto.pdf","sourcePage":4},{"front":"categorise someone into","meaning":"將某人分類為……","examples":[{"en":"Different languages categorised residents into different groups.","zh":"不同語言把居民分類為不同群體。"},{"en":"To categorise someone into a group means to place them in a class or identity group.","zh":"“Categorise someone into” 某群體指把某人放入某一類別或身份群體。"},{"en":"Schools should not categorise students into “good” and “bad” learners too quickly.","zh":"學校不應太快把學生分類為「好」和「差」的學習者。"},{"en":"If language categorises people into hostile groups, it may deepen social division.","zh":"如果語言把人分類為敵對群體，它可能加深社會分裂。"},{"en":"The phrase shows how labels can separate people.","zh":"這個短語顯示標籤如何把人分開。"}],"source":"87 - Esperanto.pdf","sourcePage":4},{"front":"residents","meaning":"居民","examples":[{"en":"The city’s residents spoke different languages.","zh":"該城市的居民說不同語言。"},{"en":"Residents are people who live in a particular place.","zh":"居民是住在某個特定地方的人。"},{"en":"Residents of an apartment building may meet to discuss lift repairs.","zh":"住宅大廈的居民可能開會討論升降機維修。"},{"en":"If residents do not share a common language, community decisions may become harder.","zh":"如果居民沒有共同語言，社區決策可能變得更困難。"},{"en":"The word refers to local people living there, not visitors.","zh":"這個詞指住在當地的人，而不是訪客。"}],"source":"87 - Esperanto.pdf","sourcePage":4},{"front":"hostile groups","meaning":"敵對群體","examples":[{"en":"The residents were often divided into hostile groups.","zh":"居民經常被分成敵對群體。"},{"en":"Hostile groups are groups that feel unfriendly, suspicious or aggressive towards one another.","zh":"敵對群體是彼此感到不友善、猜疑或具攻擊性的群體。"},{"en":"In a school, rival groups may become hostile if rumours spread online.","zh":"在學校中，如果網上謠言傳播，對立小圈子可能變成敵對群體。"},{"en":"If language separates people into hostile groups, peaceful cooperation becomes harder.","zh":"如果語言把人分成敵對群體，和平合作會變得更困難。"},{"en":"The phrase describes serious social tension between groups.","zh":"這個短語描述群體之間嚴重社會緊張。"}],"source":"87 - Esperanto.pdf","sourcePage":4},{"front":"resolve to","meaning":"決心","examples":[{"en":"Zamenhof resolved to create an easily learnt language.","zh":"Zamenhof 決心創造一種容易學會的語言。"},{"en":"To resolve to do something means to make a firm decision to do it.","zh":"“Resolve to” 做某事指下定決心去做它。"},{"en":"A student may resolve to practise speaking English for ten minutes every day.","zh":"學生可能決心每天練習說英語十分鐘。"},{"en":"If someone resolves to solve a problem, they are no longer just thinking about it.","zh":"如果某人決心解決問題，他就不再只是想想而已。"},{"en":"The phrase shows strong determination.","zh":"這個短語顯示強烈決心。"}],"source":"87 - Esperanto.pdf","sourcePage":4},{"front":"easily learnt","meaning":"容易學會的","examples":[{"en":"Zamenhof wanted Esperanto to be an easily learnt language.","zh":"Zamenhof 希望世界語是一種容易學會的語言。"},{"en":"Easily learnt means simple enough for people to learn without extreme difficulty.","zh":"“Easily learnt” 指簡單到人們不需極大困難也能學會。"},{"en":"A game with clear rules is easily learnt by children and adults.","zh":"規則清晰的遊戲對兒童和成人來說都容易學會。"},{"en":"If a language is easily learnt, more people may try it as a second language.","zh":"如果一種語言容易學會，更多人可能嘗試把它作為第二語言。"},{"en":"The phrase stresses ease of learning.","zh":"這個短語強調學習容易。"}],"source":"87 - Esperanto.pdf","sourcePage":4},{"front":"politically neutral","meaning":"政治中立的","examples":[{"en":"Esperanto was intended to be politically neutral.","zh":"世界語本意是政治中立的。"},{"en":"Politically neutral means not connected to one government, nation or political side.","zh":"“Politically neutral” 指不與某一政府、國家或政治立場相連。"},{"en":"A school debate chair should stay politically neutral and give both sides time to speak.","zh":"學校辯論主持應保持政治中立，給雙方發言時間。"},{"en":"If a language is politically neutral, people may feel it does not favour one powerful country.","zh":"如果一種語言政治中立，人們可能覺得它不偏向某個強國。"},{"en":"The phrase describes fairness in political identity.","zh":"這個短語描述政治身份上的公平。"}],"source":"87 - Esperanto.pdf","sourcePage":4},{"front":"transcend nationality","meaning":"超越國籍","examples":[{"en":"Zamenhof wanted Esperanto to transcend nationality.","zh":"Zamenhof 希望世界語超越國籍。"},{"en":"To transcend nationality means to go beyond national identity or borders.","zh":"“Transcend nationality” 指超越民族身份或國界。"},{"en":"Music can sometimes transcend nationality because people from many countries enjoy the same song.","zh":"音樂有時可以超越國籍，因為許多國家的人都喜歡同一首歌。"},{"en":"If a language transcends nationality, it may help people communicate without feeling dominated by one nation.","zh":"如果一種語言超越國籍，它可能幫助人們溝通，而不感到被某一國家支配。"},{"en":"The phrase suggests rising above national divisions.","zh":"這個短語暗示超越國家分歧。"}],"source":"87 - Esperanto.pdf","sourcePage":4},{"front":"ethnicity","meaning":"族裔","examples":[{"en":"The language was designed to transcend nationality and ethnicity.","zh":"這種語言被設計成超越國籍和族裔。"},{"en":"Ethnicity means a person’s cultural or ancestral group identity.","zh":"族裔指一個人的文化或祖先群體身份。"},{"en":"A city may include people of different ethnicities, languages and traditions.","zh":"一個城市可能包括不同族裔、語言和傳統的人。"},{"en":"If a common language goes beyond ethnicity, it may reduce barriers between groups.","zh":"如果共同語言超越族裔，它可能減少群體之間的障礙。"},{"en":"The word refers to group identity, not simply citizenship.","zh":"這個詞指群體身份，而不只是公民身份。"}],"source":"87 - Esperanto.pdf","sourcePage":4},{"front":"race, colour, and creed","meaning":"種族、膚色和信仰","examples":[{"en":"Esperanto was meant to transcend race, colour, and creed.","zh":"世界語本意是超越種族、膚色和信仰。"},{"en":"Race, colour, and creed refers to racial identity, skin colour and religious belief.","zh":"“Race, colour, and creed” 指種族身份、膚色和宗教信仰。"},{"en":"A fair public service should treat people equally regardless of race, colour or creed.","zh":"公平公共服務應不分種族、膚色或信仰平等對待人。"},{"en":"If a language is meant to transcend race, colour and creed, it aims to include everyone.","zh":"如果一種語言旨在超越種族、膚色和信仰，它就是希望包容所有人。"},{"en":"The phrase is often used when discussing equality and social inclusion.","zh":"這個短語常用於討論平等和社會包容。"}],"source":"87 - Esperanto.pdf","sourcePage":4},{"front":"universal second language","meaning":"全球通用第二語言","examples":[{"en":"Zamenhof hoped Esperanto would become a universal second language.","zh":"Zamenhof 希望世界語成為全球通用第二語言。"},{"en":"A universal second language is a language learned by people everywhere to communicate across native languages.","zh":"全球通用第二語言是世界各地的人學來跨越母語溝通的語言。"},{"en":"A universal second language would help travellers, students and workers communicate internationally.","zh":"全球通用第二語言會幫助旅客、學生和工人進行國際溝通。"},{"en":"If no country owns the language, supporters may see it as fairer for global use.","zh":"如果沒有國家擁有該語言，支持者可能視它為更公平的全球用途語言。"},{"en":"The phrase describes an ambitious goal for worldwide communication.","zh":"這個短語描述世界溝通的宏大目標。"}],"source":"87 - Esperanto.pdf","sourcePage":5},{"front":"detail an idea","meaning":"詳述一個構想","examples":[{"en":"Zamenhof’s first book detailed his idea for Esperanto.","zh":"Zamenhof 的第一本書詳述了他對世界語的構想。"},{"en":"To detail an idea means to explain it carefully with important features and examples.","zh":"“Detail an idea” 指仔細解釋一個想法的重要特點和例子。"},{"en":"A student may detail an idea for a school club in a proposal.","zh":"學生可能在建議書中詳述一個學校社團構想。"},{"en":"If a book details a language plan, readers can understand its grammar and purpose.","zh":"如果一本書詳述語言計劃，讀者就能理解其文法和目的。"},{"en":"The phrase describes giving full explanation rather than only naming an idea.","zh":"這個短語描述完整解釋，而不只是說出想法名稱。"}],"source":"87 - Esperanto.pdf","sourcePage":5},{"front":"be published in","meaning":"於……出版","examples":[{"en":"Zamenhof’s first book was published in 1887.","zh":"Zamenhof 的第一本書於1887年出版。"},{"en":"To be published in a year means to be officially printed or released in that year.","zh":"“Be published in” 某年指在該年正式印刷或發行。"},{"en":"A novel published in 2020 may reflect the concerns of that period.","zh":"於2020年出版的小說可能反映該時期的憂慮。"},{"en":"If a book is published, its ideas can reach readers beyond the author’s friends.","zh":"如果一本書出版，其想法就可以接觸作者朋友以外的讀者。"},{"en":"The phrase gives the release date of written work.","zh":"這個短語給出書面作品的發行日期。"}],"source":"87 - Esperanto.pdf","sourcePage":5},{"front":"surprisingly perhaps","meaning":"也許令人驚訝的是","examples":[{"en":"Surprisingly perhaps, Esperanto quickly gained acceptance.","zh":"也許令人驚訝的是，世界語很快獲得接受。"},{"en":"Surprisingly perhaps means the writer thinks the fact may be unexpected to readers.","zh":"“Surprisingly perhaps” 指作者認為該事實對讀者可能出乎意料。"},{"en":"Surprisingly perhaps, some quiet students do best in public speaking after practice.","zh":"也許令人驚訝的是，一些安靜學生在練習後最擅長公開演說。"},{"en":"If a new invented language gains support quickly, readers may find it surprising.","zh":"如果一種新發明語言很快獲得支持，讀者可能覺得驚訝。"},{"en":"The phrase gently signals that the next fact may go against expectation.","zh":"這個短語溫和地提示下一個事實可能與預期相反。"}],"source":"87 - Esperanto.pdf","sourcePage":5},{"front":"the concept","meaning":"這個概念","examples":[{"en":"The concept quickly gained acceptance and a loyal following.","zh":"這個概念很快獲得接受和忠實支持者。"},{"en":"The concept means the main idea or plan being discussed.","zh":"“The concept” 指正在討論的主要想法或計劃。"},{"en":"The concept of online lessons became familiar to many families during school closures.","zh":"在停課期間，網上課堂這個概念對許多家庭變得熟悉。"},{"en":"If a concept is simple and useful, people may accept it quickly.","zh":"如果一個概念簡單而有用，人們可能很快接受它。"},{"en":"The phrase refers to the idea itself, not only its practical result.","zh":"這個短語指想法本身，而不只是其實際結果。"}],"source":"87 - Esperanto.pdf","sourcePage":5},{"front":"gain acceptance","meaning":"獲得接受","examples":[{"en":"Esperanto quickly gained acceptance in Eastern Europe.","zh":"世界語很快在東歐獲得接受。"},{"en":"To gain acceptance means to become approved, supported or treated as reasonable by people.","zh":"“Gain acceptance” 指變得被人認可、支持或視為合理。"},{"en":"A new school rule may gain acceptance if students see that it is fair.","zh":"如果學生看見新校規公平，它可能獲得接受。"},{"en":"If a language gains acceptance, more people are willing to learn and use it.","zh":"如果一種語言獲得接受，更多人會願意學習和使用它。"},{"en":"The phrase describes a shift from unfamiliarity to support.","zh":"這個短語描述由陌生轉向支持。"}],"source":"87 - Esperanto.pdf","sourcePage":5},{"front":"a loyal following","meaning":"忠實支持者","examples":[{"en":"Esperanto gained a loyal following after its creation.","zh":"世界語創立後獲得了一批忠實支持者。"},{"en":"A loyal following is a group of supporters who remain interested and committed over time.","zh":"忠實支持者是一群長時間保持興趣和投入的人。"},{"en":"A small local café may build a loyal following if customers trust its quality.","zh":"如果小型本地咖啡店讓顧客信任其品質，可能建立忠實支持者。"},{"en":"If a language has a loyal following, it can survive even without official status.","zh":"如果一種語言有忠實支持者，即使沒有官方地位也能生存。"},{"en":"The phrase stresses commitment, not just temporary popularity.","zh":"這個短語強調投入，而不只是短暫流行。"}],"source":"87 - Esperanto.pdf","sourcePage":5},{"front":"linguistically divided","meaning":"語言上分裂的","examples":[{"en":"Esperanto spread in a linguistically divided Eastern Europe.","zh":"世界語在語言上分裂的東歐傳播。"},{"en":"Linguistically divided means separated by different languages or language communities.","zh":"“Linguistically divided” 指被不同語言或語言社群分隔。"},{"en":"A workplace can be linguistically divided if staff cannot understand one another’s language.","zh":"如果員工不能理解彼此語言，工作場所可能在語言上分裂。"},{"en":"If a region is linguistically divided, a neutral shared language may seem useful.","zh":"如果地區在語言上分裂，中立共同語言可能顯得有用。"},{"en":"The phrase describes division caused by language differences.","zh":"這個短語描述由語言差異造成的分裂。"}],"source":"87 - Esperanto.pdf","sourcePage":5},{"front":"possess the same idealism","meaning":"擁有同樣的理想主義","examples":[{"en":"Many people possessed the same idealism as Zamenhof.","zh":"許多人擁有與 Zamenhof 同樣的理想主義。"},{"en":"To possess the same idealism means to share the same hopeful belief in improving the world.","zh":"“Possess the same idealism” 指共有改善世界的同樣希望信念。"},{"en":"Volunteers may possess the same idealism when they work together for free education.","zh":"義工一起為免費教育工作時，可能擁有同樣的理想主義。"},{"en":"If early supporters shared Zamenhof’s idealism, they were moved by more than language study.","zh":"如果早期支持者與 Zamenhof 共有理想主義，他們受感召的不只是語言學習。"},{"en":"The phrase describes a shared moral or social vision.","zh":"這個短語描述共同的道德或社會願景。"}],"source":"87 - Esperanto.pdf","sourcePage":5},{"front":"drive someone","meaning":"推動某人","examples":[{"en":"Idealism drove Zamenhof to create Esperanto.","zh":"理想主義推動 Zamenhof 創造世界語。"},{"en":"To drive someone means to strongly motivate them to act.","zh":"“Drive someone” 指強烈激勵某人採取行動。"},{"en":"Concern for students may drive a teacher to prepare better lessons.","zh":"對學生的關心可能推動老師準備更好的課堂。"},{"en":"If personal experience drives someone, their project often carries deep meaning.","zh":"如果個人經驗推動某人，其項目通常帶有深層意義。"},{"en":"The phrase explains the force behind a person’s action.","zh":"這個短語解釋某人行動背後的力量。"}],"source":"87 - Esperanto.pdf","sourcePage":5},{"front":"spread to","meaning":"傳播至","examples":[{"en":"Esperanto spread to the West and then into the Americas and Asia.","zh":"世界語傳播至西方，然後進入美洲和亞洲。"},{"en":"To spread to a place means to move, grow or become known there.","zh":"“Spread to” 某地指移動、增長或在該地為人所知。"},{"en":"A new teaching method may spread to other schools after one school succeeds with it.","zh":"如果一間學校成功使用新教學方法，它可能傳播至其他學校。"},{"en":"If a language spreads to new regions, its community becomes more international.","zh":"如果一種語言傳播至新地區，其社群會變得更國際化。"},{"en":"The phrase describes movement from one place to another.","zh":"這個短語描述由一地移向另一地。"}],"source":"87 - Esperanto.pdf","sourcePage":5},{"front":"the West","meaning":"西方","examples":[{"en":"Esperanto spread from Eastern Europe to the West.","zh":"世界語由東歐傳播至西方。"},{"en":"The West usually refers to Western Europe, North America or societies culturally linked to them.","zh":"西方通常指西歐、北美或與它們有文化連繫的社會。"},{"en":"Many political ideas from the West influenced education and business in other regions.","zh":"許多來自西方的政治思想影響其他地區的教育和商業。"},{"en":"If Esperanto spread to the West, it reached beyond its Eastern European origins.","zh":"如果世界語傳播至西方，它就超越了其東歐起源。"},{"en":"The phrase is broad and depends on historical and cultural context.","zh":"這個短語很廣泛，取決於歷史和文化語境。"}],"source":"87 - Esperanto.pdf","sourcePage":6},{"front":"the Americas","meaning":"美洲","examples":[{"en":"Esperanto later spread into the Americas.","zh":"世界語後來傳播到美洲。"},{"en":"The Americas refers to North America, Central America, South America and nearby islands.","zh":"美洲指北美洲、中美洲、南美洲及附近島嶼。"},{"en":"Languages from Europe spread into the Americas through migration, trade and colonisation.","zh":"歐洲語言透過移民、貿易和殖民傳播至美洲。"},{"en":"If Esperanto reached the Americas, its movement became more geographically diverse.","zh":"如果世界語到達美洲，其運動在地理上變得更多元。"},{"en":"The phrase names a broad region, not just the United States.","zh":"這個短語指廣闊地區，而不只是美國。"}],"source":"87 - Esperanto.pdf","sourcePage":6},{"front":"Esperanto journals","meaning":"世界語期刊","examples":[{"en":"Esperanto journals were created by early supporters.","zh":"世界語期刊由早期支持者創立。"},{"en":"Esperanto journals are magazines or periodicals written in or about Esperanto.","zh":"世界語期刊是以世界語撰寫或關於世界語的雜誌或定期刊物。"},{"en":"A language community may publish journals to share news, poems and learning advice.","zh":"語言社群可能出版期刊，以分享新聞、詩歌和學習建議。"},{"en":"If Esperanto journals circulate widely, speakers can feel part of a larger movement.","zh":"如果世界語期刊廣泛流通，使用者可以感到自己是較大運動的一部分。"},{"en":"The phrase shows how a language community records and spreads ideas.","zh":"這個短語顯示語言社群如何記錄和傳播想法。"}],"source":"87 - Esperanto.pdf","sourcePage":6},{"front":"Esperanto magazines and clubs","meaning":"世界語雜誌及俱樂部","examples":[{"en":"Esperanto magazines and clubs were formed.","zh":"世界語雜誌及俱樂部成立了。"},{"en":"Esperanto magazines and clubs are publications and social groups created for people interested in Esperanto.","zh":"世界語雜誌及俱樂部是為對世界語感興趣的人創立的刊物和社交組織。"},{"en":"A learner may join an Esperanto club to practise speaking with others.","zh":"學習者可能加入世界語俱樂部，與他人練習說話。"},{"en":"If magazines and clubs grow, a language can survive beyond private study.","zh":"如果雜誌和俱樂部發展，語言就能超越私人學習而生存。"},{"en":"The phrase shows the social side of language learning.","zh":"這個短語顯示語言學習的社交面。"}],"source":"87 - Esperanto.pdf","sourcePage":6},{"front":"ultimately lead to","meaning":"最終導致","examples":[{"en":"Esperanto clubs ultimately led to the first world congress.","zh":"世界語俱樂部最終導致第一屆世界大會。"},{"en":"To ultimately lead to something means to eventually cause or produce that result.","zh":"“Ultimately lead to” 某事指最終造成或產生該結果。"},{"en":"Regular small meetings can ultimately lead to a strong community project.","zh":"定期小型會議可以最終促成強大的社區項目。"},{"en":"If clubs connect learners across regions, they may ultimately lead to international events.","zh":"如果俱樂部連接不同地區的學習者，它們最終可能帶來國際活動。"},{"en":"The phrase links earlier steps with a later final outcome.","zh":"這個短語把早期步驟與後來最終結果連繫起來。"}],"source":"87 - Esperanto.pdf","sourcePage":6},{"front":"world congress","meaning":"世界大會","examples":[{"en":"The first world congress of Esperanto speakers was held in France.","zh":"第一屆世界語使用者世界大會在法國舉行。"},{"en":"A world congress is a large international meeting for people who share a field, interest or movement.","zh":"世界大會是為共享某領域、興趣或運動的人舉行的大型國際會議。"},{"en":"Doctors may attend a world congress to discuss new research and treatments.","zh":"醫生可能參加世界大會，討論新研究和治療。"},{"en":"If Esperanto speakers hold a world congress, the language is being used in organised international life.","zh":"如果世界語使用者舉行世界大會，該語言就正在有組織的國際生活中使用。"},{"en":"The phrase suggests a formal global gathering.","zh":"這個短語暗示正式的全球聚會。"}],"source":"87 - Esperanto.pdf","sourcePage":6},{"front":"apart from when","meaning":"除了……的時候","examples":[{"en":"The congresses have been held every year, apart from when wars delayed them.","zh":"這些大會每年舉行，除了戰爭令它們延誤的時候。"},{"en":"Apart from when means except during the times when a particular condition happened.","zh":"“Apart from when” 指除了某特定情況發生的時候。"},{"en":"The library is open every day, apart from when public holidays close it.","zh":"圖書館每天開放，除了公眾假期令它關閉的時候。"},{"en":"If meetings happen yearly apart from wartime delays, the tradition is fairly strong.","zh":"如果會議除了戰時延誤外每年舉行，這個傳統相當穩固。"},{"en":"The phrase introduces an exception based on time.","zh":"這個短語引出基於時間的例外。"}],"source":"87 - Esperanto.pdf","sourcePage":6},{"front":"world wars","meaning":"世界大戰","examples":[{"en":"World wars delayed some Esperanto congresses.","zh":"世界大戰延誤了一些世界語大會。"},{"en":"World wars are large wars involving many countries across the world.","zh":"世界大戰是涉及世界許多國家的大型戰爭。"},{"en":"World wars interrupted travel, education and international meetings.","zh":"世界大戰中斷了旅行、教育和國際會議。"},{"en":"If world wars delay a movement’s events, politics can affect even language communities.","zh":"如果世界大戰延誤某運動的活動，政治就連語言社群也會影響。"},{"en":"The phrase usually refers to the First and Second World Wars.","zh":"這個短語通常指第一次和第二次世界大戰。"}],"source":"87 - Esperanto.pdf","sourcePage":6},{"front":"delay proceedings","meaning":"延誤會議進程","examples":[{"en":"World wars delayed proceedings at Esperanto congresses.","zh":"世界大戰延誤了世界語大會的會議進程。"},{"en":"To delay proceedings means to make formal meetings or events happen later than planned.","zh":"“Delay proceedings” 指令正式會議或活動比原定時間更遲進行。"},{"en":"A power cut may delay proceedings at a school ceremony.","zh":"停電可能延誤學校典禮的進程。"},{"en":"If travel becomes impossible, international conference proceedings may be delayed.","zh":"如果旅行變得不可能，國際會議進程可能被延誤。"},{"en":"The phrase is formal and usually refers to organised events.","zh":"這個短語較正式，通常指有組織活動。"}],"source":"87 - Esperanto.pdf","sourcePage":6},{"front":"still present","meaning":"仍然存在","examples":[{"en":"Esperanto is still present today.","zh":"世界語今天仍然存在。"},{"en":"Still present means continuing to exist or be noticeable now.","zh":"“Still present” 指現在仍然存在或仍能被注意到。"},{"en":"Old village customs may be still present in festival songs and family meals.","zh":"舊村落習俗可能仍然存在於節日歌曲和家庭飯局中。"},{"en":"If a language is still present after many decades, it has not disappeared.","zh":"如果一種語言多年後仍然存在，它就沒有消失。"},{"en":"The phrase stresses survival over time.","zh":"這個短語強調隨時間生存下來。"}],"source":"87 - Esperanto.pdf","sourcePage":6},{"front":"under the radar","meaning":"不太受注意；低調地","examples":[{"en":"Esperanto is still present, although very much under the radar.","zh":"世界語仍然存在，雖然非常不受注意。"},{"en":"Under the radar means existing quietly without much public attention.","zh":"“Under the radar” 指低調存在，沒有太多公眾注意。"},{"en":"A small charity may work under the radar while helping many local families.","zh":"小型慈善機構可能低調地工作，同時幫助許多本地家庭。"},{"en":"If a movement is under the radar, only interested people may notice it.","zh":"如果一場運動不太受注意，可能只有有興趣的人才會留意到它。"},{"en":"The phrase describes low visibility, not non-existence.","zh":"這個短語描述能見度低，而不是不存在。"}],"source":"87 - Esperanto.pdf","sourcePage":6},{"front":"achieve official-language status","meaning":"取得官方語言地位","examples":[{"en":"Esperanto has not achieved official-language status in any state.","zh":"世界語沒有在任何國家取得官方語言地位。"},{"en":"To achieve official-language status means to be legally recognised as an official language by a government.","zh":"“Achieve official-language status” 指被政府依法承認為官方語言。"},{"en":"A regional language may seek official-language status so citizens can use it in public services.","zh":"地區語言可能尋求官方語言地位，讓市民能在公共服務中使用它。"},{"en":"If Esperanto lacks official status, governments do not use it as a normal state language.","zh":"如果世界語缺乏官方地位，政府就不會把它作為正常國家語言使用。"},{"en":"The phrase describes formal legal recognition.","zh":"這個短語描述正式法律承認。"}],"source":"87 - Esperanto.pdf","sourcePage":7},{"front":"official-language status","meaning":"官方語言地位","examples":[{"en":"Esperanto lacks official-language status.","zh":"世界語缺乏官方語言地位。"},{"en":"Official-language status is legal recognition that a language can be used in government and public administration.","zh":"官方語言地位是法律承認某語言可在政府和公共行政中使用。"},{"en":"A language with official-language status may appear on forms, signs and public documents.","zh":"擁有官方語言地位的語言可能出現在表格、標誌和公共文件上。"},{"en":"Without official-language status, a language may depend mainly on volunteers and communities.","zh":"沒有官方語言地位時，一種語言可能主要依靠志願者和社群。"},{"en":"The phrase refers to legal position, not speaker numbers only.","zh":"這個短語指法律位置，而不只是使用者數量。"}],"source":"87 - Esperanto.pdf","sourcePage":7},{"front":"governing body","meaning":"管治機構","examples":[{"en":"No governing body has made Esperanto an official language.","zh":"沒有管治機構把世界語定為官方語言。"},{"en":"A governing body is an organisation or authority that has the power to make official decisions.","zh":"管治機構是有權作出正式決定的組織或權威。"},{"en":"A school board is a governing body that can decide policies for schools.","zh":"校董會是可以決定學校政策的管治機構。"},{"en":"If no governing body recognises a language officially, it remains outside formal state use.","zh":"如果沒有管治機構正式承認某語言，它就仍在正式國家用途之外。"},{"en":"The phrase refers to an authority, not ordinary speakers.","zh":"這個短語指權威機構，而不是普通使用者。"}],"source":"87 - Esperanto.pdf","sourcePage":7},{"front":"educational institutions","meaning":"教育機構","examples":[{"en":"Esperanto is occasionally taught at schools and educational institutions.","zh":"世界語偶爾在學校和教育機構教授。"},{"en":"Educational institutions are places or organisations that provide teaching and learning.","zh":"教育機構是提供教學和學習的地方或組織。"},{"en":"Universities, language centres and schools are educational institutions.","zh":"大學、語言中心和學校都是教育機構。"},{"en":"If a language is taught in educational institutions, learners can study it more systematically.","zh":"如果一種語言在教育機構教授，學習者就能更有系統地學習它。"},{"en":"The phrase covers more than ordinary schools.","zh":"這個短語涵蓋的不只是普通學校。"}],"source":"87 - Esperanto.pdf","sourcePage":7},{"front":"on an informal basis","meaning":"以非正式方式","examples":[{"en":"Esperanto is sometimes taught on an informal basis.","zh":"世界語有時以非正式方式教授。"},{"en":"On an informal basis means in a casual or unofficial way, without a formal programme.","zh":"“On an informal basis” 指以隨意或非官方方式，而不是正式課程方式。"},{"en":"A retired teacher may teach neighbours English on an informal basis.","zh":"退休老師可能以非正式方式教鄰居英語。"},{"en":"If Esperanto is taught informally, learners may depend on clubs, friends or online groups.","zh":"如果世界語以非正式方式教授，學習者可能依靠俱樂部、朋友或網上群組。"},{"en":"The phrase contrasts with official or structured teaching.","zh":"這個短語與官方或有結構教學形成對比。"}],"source":"87 - Esperanto.pdf","sourcePage":7},{"front":"on an experimental basis","meaning":"以試驗性方式","examples":[{"en":"Some institutions teach Esperanto on an experimental basis.","zh":"一些機構以試驗性方式教授世界語。"},{"en":"On an experimental basis means as a trial to see whether something works.","zh":"“On an experimental basis” 指作為試驗，以查看某事是否有效。"},{"en":"A school may teach a new timetable on an experimental basis for one term.","zh":"學校可能以試驗性方式推行新時間表一個學期。"},{"en":"If a course is offered experimentally, it may stop if results are weak.","zh":"如果課程以試驗方式提供，效果不佳時可能停止。"},{"en":"The phrase describes testing before full adoption.","zh":"這個短語描述全面採用前的測試。"}],"source":"87 - Esperanto.pdf","sourcePage":7},{"front":"keep something going","meaning":"令……持續下去","examples":[{"en":"The motivation of learners keeps Esperanto going.","zh":"學習者的動機令世界語持續下去。"},{"en":"To keep something going means to help it continue and not disappear.","zh":"“Keep something going” 指幫助某事繼續而不消失。"},{"en":"Volunteers keep a community library going by opening it every weekend.","zh":"義工每週末開放社區圖書館，令它持續運作。"},{"en":"If learners keep using Esperanto, the language community can survive without state support.","zh":"如果學習者持續使用世界語，語言社群沒有國家支持也能生存。"},{"en":"The phrase stresses continued effort.","zh":"這個短語強調持續努力。"}],"source":"87 - Esperanto.pdf","sourcePage":7},{"front":"motivation","meaning":"動機；推動力","examples":[{"en":"Motivation is what keeps Esperanto alive.","zh":"動機是令世界語保持生命力的東西。"},{"en":"Motivation is the reason or desire that makes people act or continue.","zh":"動機是令人行動或持續下去的原因或渴望。"},{"en":"A student’s motivation may increase when they see real improvement in speaking.","zh":"當學生看見口語真正進步，動機可能增加。"},{"en":"If a language has motivated learners, they may create books, clubs and online lessons.","zh":"如果一種語言有充滿動機的學習者，他們可能創作書籍、俱樂部和網上課堂。"},{"en":"The word explains why people keep doing something difficult.","zh":"這個詞解釋人們為何持續做困難的事。"}],"source":"87 - Esperanto.pdf","sourcePage":7},{"front":"become interested","meaning":"產生興趣","examples":[{"en":"Some people become interested in Esperanto and keep learning it.","zh":"有些人對世界語產生興趣，並繼續學習它。"},{"en":"To become interested in something means to start wanting to know more about it.","zh":"“Become interested in” 某事指開始想更了解它。"},{"en":"A child may become interested in astronomy after seeing the moon through a telescope.","zh":"孩子透過望遠鏡看見月亮後，可能對天文產生興趣。"},{"en":"If people become interested in Esperanto, they may look for books, videos and speaking groups.","zh":"如果人們對世界語產生興趣，可能尋找書籍、影片和口語群組。"},{"en":"The phrase describes the beginning of curiosity or engagement.","zh":"這個短語描述好奇心或投入的開始。"}],"source":"87 - Esperanto.pdf","sourcePage":7},{"front":"language books","meaning":"語言書籍","examples":[{"en":"Language books are available for Esperanto learners.","zh":"世界語學習者可以找到語言書籍。"},{"en":"Language books are books that teach grammar, vocabulary, pronunciation or practice exercises.","zh":"語言書籍是教授文法、詞彙、發音或練習題的書。"},{"en":"A beginner may use language books to learn basic sentence patterns at home.","zh":"初學者可能使用語言書籍在家學習基本句式。"},{"en":"If language books are easy to find, self-study becomes more possible.","zh":"如果語言書籍容易找到，自學就變得更可行。"},{"en":"The phrase refers to learning materials for a language.","zh":"這個短語指語言學習材料。"}],"source":"87 - Esperanto.pdf","sourcePage":7},{"front":"various online technologies","meaning":"各種網上科技","examples":[{"en":"Various online technologies support Esperanto self-learning.","zh":"各種網上科技支援世界語自學。"},{"en":"Various online technologies are different digital tools or platforms available on the internet.","zh":"各種網上科技是互聯網上不同的數碼工具或平台。"},{"en":"Language apps, video calls and online dictionaries are various online technologies for learners.","zh":"語言應用程式、視像通話和網上字典都是學習者可用的各種網上科技。"},{"en":"If learners live far apart, online technologies can connect them for practice.","zh":"如果學習者住得很遠，網上科技可以連接他們練習。"},{"en":"The phrase highlights digital support from more than one tool.","zh":"這個短語強調來自多種工具的數碼支援。"}],"source":"87 - Esperanto.pdf","sourcePage":7},{"front":"video-based self-learning technologies","meaning":"影片式自學科技","examples":[{"en":"Video-based self-learning technologies help people learn Esperanto.","zh":"影片式自學科技幫助人們學習世界語。"},{"en":"Video-based self-learning technologies are digital tools that use videos for independent study.","zh":"影片式自學科技是使用影片進行獨立學習的數碼工具。"},{"en":"A student may use video-based lessons to practise pronunciation after school.","zh":"學生可能在放學後使用影片式課堂練習發音。"},{"en":"If lessons are video-based, learners can pause, repeat and study at their own speed.","zh":"如果課堂以影片為本，學習者可以暫停、重播並按自己的速度學習。"},{"en":"The phrase refers to online self-study through video materials.","zh":"這個短語指透過影片材料進行網上自學。"}],"source":"87 - Esperanto.pdf","sourcePage":8},{"front":"active speaking community","meaning":"活躍的語言社群","examples":[{"en":"Esperanto has an active speaking community.","zh":"世界語有一個活躍的語言社群。"},{"en":"An active speaking community is a group of people who regularly use a language to communicate.","zh":"活躍的語言社群是一群定期使用某語言溝通的人。"},{"en":"A small language can survive if it has an active speaking community online and offline.","zh":"如果小語言在網上和線下有活躍的語言社群，就可以生存。"},{"en":"If speakers meet, write and teach in Esperanto, the language remains alive.","zh":"如果使用者用世界語見面、寫作和教學，該語言就保持生命力。"},{"en":"The phrase stresses real use, not just grammar books.","zh":"這個短語強調真實使用，而不只是文法書。"}],"source":"87 - Esperanto.pdf","sourcePage":8},{"front":"the key question remains whether","meaning":"關鍵問題仍然是是否……","examples":[{"en":"The key question remains whether Esperanto is worth learning.","zh":"關鍵問題仍然是世界語是否值得學習。"},{"en":"The key question remains whether means the most important unresolved issue is whether something is true or worthwhile.","zh":"“The key question remains whether” 指最重要且尚未解決的問題是某事是否真實或值得。"},{"en":"The key question remains whether online lessons can help weak speakers improve confidence.","zh":"關鍵問題仍然是網上課堂是否能幫助口語較弱者提升信心。"},{"en":"If many details are debated, this phrase brings attention back to the central issue.","zh":"如果許多細節存在爭議，這個短語把注意力帶回核心問題。"},{"en":"The phrase introduces the main question still needing an answer.","zh":"這個短語引出仍需回答的主要問題。"}],"source":"87 - Esperanto.pdf","sourcePage":8},{"front":"be worth investing the time in","meaning":"值得花時間去……","examples":[{"en":"Some people ask whether Esperanto is worth investing the time in.","zh":"有些人問世界語是否值得花時間學習。"},{"en":"To be worth investing the time in means to be useful enough to justify the time needed to learn or do it.","zh":"“Be worth investing the time in” 指某事足夠有用，值得投入所需時間去學習或完成。"},{"en":"A difficult exam course is worth investing the time in if it opens important career doors.","zh":"如果困難考試課程能打開重要職業大門，它就值得花時間投入。"},{"en":"If Esperanto gives few practical opportunities, some learners may question the time investment.","zh":"如果世界語提供很少實際機會，一些學習者可能質疑時間投入是否值得。"},{"en":"The phrase weighs effort against benefit.","zh":"這個短語衡量努力與好處。"}],"source":"87 - Esperanto.pdf","sourcePage":8},{"front":"acquire the language","meaning":"掌握該語言","examples":[{"en":"Learners need time to acquire the language.","zh":"學習者需要時間掌握該語言。"},{"en":"To acquire the language means to gain the ability to understand and use it.","zh":"“Acquire the language” 指獲得理解和使用該語言的能力。"},{"en":"Children acquire language naturally by hearing it every day at home.","zh":"兒童透過每天在家聽到語言，自然掌握語言。"},{"en":"If adults want to acquire a new language, they need practice, input and time.","zh":"如果成人想掌握新語言，就需要練習、輸入和時間。"},{"en":"The phrase is more about developing ability than memorising isolated words.","zh":"這個短語更關乎發展能力，而不是記住孤立詞語。"}],"source":"87 - Esperanto.pdf","sourcePage":8},{"front":"in other words","meaning":"換句話說","examples":[{"en":"In other words, does Esperanto offer any real advantage?","zh":"換句話說，世界語是否提供任何真正優勢？"},{"en":"In other words means the same idea is being expressed more clearly or simply.","zh":"“In other words” 指用更清楚或簡單的方式表達同一想法。"},{"en":"The course is asynchronous; in other words, students do not need to attend live lessons.","zh":"這課程是非同步的；換句話說，學生不需要參加直播課。"},{"en":"If a writer says “in other words,” they are usually clarifying the point.","zh":"如果作者說 “in other words”，通常是在澄清重點。"},{"en":"The phrase helps restate an idea.","zh":"這個短語幫助重新表述想法。"}],"source":"87 - Esperanto.pdf","sourcePage":8},{"front":"innate advantages","meaning":"內在優勢","examples":[{"en":"Supporters claim that Esperanto has innate advantages over other languages.","zh":"支持者聲稱世界語相比其他語言有內在優勢。"},{"en":"Innate advantages are strengths built into something from the beginning.","zh":"內在優勢是某事從一開始就具備的強項。"},{"en":"A simple app may have innate advantages if its design is easy for beginners.","zh":"如果簡單應用程式的設計對初學者容易，它可能有內在優勢。"},{"en":"If Esperanto has regular grammar, supporters may see that as an innate advantage.","zh":"如果世界語有規則文法，支持者可能把這視為內在優勢。"},{"en":"The phrase refers to built-in benefits, not later popularity.","zh":"這個短語指內建好處，而不是後來的流行程度。"}],"source":"87 - Esperanto.pdf","sourcePage":8},{"front":"equip someone with","meaning":"使某人具備……","examples":[{"en":"A language may equip its speakers with a useful skill.","zh":"一種語言可能使其使用者具備一項實用技能。"},{"en":"To equip someone with something means to give them the ability, tool or knowledge they need.","zh":"“Equip someone with” 某物指給予某人所需能力、工具或知識。"},{"en":"A first-aid course can equip students with skills to help in emergencies.","zh":"急救課程可以使學生具備在緊急情況中幫忙的技能。"},{"en":"If learning a language equips people with confidence, they may communicate more freely.","zh":"如果學習語言使人具備信心，他們可能更自由地溝通。"},{"en":"The phrase focuses on providing practical ability.","zh":"這個短語強調提供實際能力。"}],"source":"87 - Esperanto.pdf","sourcePage":8},{"front":"useful skill in life","meaning":"生活中的實用技能","examples":[{"en":"Learning Esperanto may equip speakers with a useful skill in life.","zh":"學習世界語可能使使用者具備生活中的實用技能。"},{"en":"A useful skill in life is an ability that helps people in real situations.","zh":"生活中的實用技能是在真實情況中幫助人的能力。"},{"en":"Cooking simple meals is a useful skill in life because it supports health and independence.","zh":"烹調簡單餐點是生活中的實用技能，因為它支援健康和獨立。"},{"en":"If a language helps people travel, study or make friends, it may be a useful life skill.","zh":"如果一種語言幫助人旅行、學習或交朋友，它可能是生活中的實用技能。"},{"en":"The phrase asks whether learning has practical value beyond the classroom.","zh":"這個短語詢問學習是否具有課室以外的實際價值。"}],"source":"87 - Esperanto.pdf","sourcePage":8},{"front":"promptly answered","meaning":"可迅速回答","examples":[{"en":"The first question can be promptly answered.","zh":"第一個問題可以迅速回答。"},{"en":"Promptly answered means answered quickly and without much delay.","zh":"“Promptly answered” 指快速且沒有太多延誤地回答。"},{"en":"A simple email can be promptly answered if the information is already available.","zh":"如果資料已經齊備，簡單電郵可以迅速回覆。"},{"en":"If a question has clear evidence, it can be answered promptly.","zh":"如果問題有清晰證據，就可以迅速回答。"},{"en":"The phrase suggests speed and confidence in responding.","zh":"這個短語暗示回應迅速且有信心。"}],"source":"87 - Esperanto.pdf","sourcePage":8},{"front":"proponents","meaning":"支持者","examples":[{"en":"Proponents argue that Esperanto is easy to learn.","zh":"支持者認為世界語容易學習。"},{"en":"Proponents are people who support an idea, plan or movement.","zh":"支持者是支持某想法、計劃或運動的人。"},{"en":"Proponents of public transport may argue that trains reduce traffic and pollution.","zh":"公共交通支持者可能認為火車能減少交通和污染。"},{"en":"If proponents defend Esperanto, they usually emphasise its simplicity and neutrality.","zh":"如果支持者為世界語辯護，他們通常強調其簡單和中立。"},{"en":"The word refers to supporters in a debate.","zh":"這個詞指辯論中的支持者。"}],"source":"87 - Esperanto.pdf","sourcePage":8},{"front":"internally consistent","meaning":"內部規則一致的","examples":[{"en":"Esperanto is simple and internally consistent.","zh":"世界語簡單且內部規則一致。"},{"en":"Internally consistent means the parts of a system follow the same rules without contradiction.","zh":"“Internally consistent” 指系統內各部分遵循相同規則，沒有矛盾。"},{"en":"A school policy is internally consistent if all rules treat similar cases in the same way.","zh":"如果校規對相似情況都以同樣方式處理，它就是內部一致的。"},{"en":"If a language is internally consistent, learners can predict forms more easily.","zh":"如果語言內部規則一致，學習者就更容易預測形式。"},{"en":"The phrase describes logical order within a system.","zh":"這個短語描述系統內的邏輯秩序。"}],"source":"87 - Esperanto.pdf","sourcePage":9},{"front":"easy to learn","meaning":"容易學習","examples":[{"en":"Esperanto is said to be easy to learn.","zh":"世界語據說容易學習。"},{"en":"Easy to learn means not very difficult for beginners to understand and practise.","zh":"“Easy to learn” 指對初學者來說不太難理解和練習。"},{"en":"A board game with clear rules is easy to learn even if it becomes harder later.","zh":"規則清晰的棋盤遊戲容易學習，即使之後可能變得更難。"},{"en":"If a language is easy to learn, students may reach basic communication more quickly.","zh":"如果一種語言容易學習，學生可能更快達到基本溝通。"},{"en":"The phrase focuses on learning difficulty.","zh":"這個短語強調學習難度。"}],"source":"87 - Esperanto.pdf","sourcePage":9},{"front":"be mastered in","meaning":"可在……內掌握","examples":[{"en":"Esperanto can be mastered in less time than conventional languages.","zh":"世界語可在比傳統語言更短的時間內掌握。"},{"en":"To be mastered in a period of time means to be learned well within that time.","zh":"“Be mastered in” 某段時間指在該時間內學好某技能。"},{"en":"Basic spreadsheet skills can be mastered in a few weeks with daily practice.","zh":"基本試算表技巧可以透過每日練習在幾週內掌握。"},{"en":"If Esperanto can be mastered faster, learners may see it as efficient.","zh":"如果世界語可以更快掌握，學習者可能視它為有效率。"},{"en":"The phrase connects skill learning with a time frame.","zh":"這個短語把技能學習與時間框架連繫起來。"}],"source":"87 - Esperanto.pdf","sourcePage":9},{"front":"a fraction of the time","meaning":"只需一小部分時間","examples":[{"en":"Esperanto can be mastered in a fraction of the time needed for other languages.","zh":"世界語只需其他語言所需時間的一小部分便可掌握。"},{"en":"A fraction of the time means only a small part of the time usually required.","zh":"“A fraction of the time” 指只需通常所需時間的一小部分。"},{"en":"With a clear template, a report can be written in a fraction of the time.","zh":"有清晰範本時，報告可以用一小部分時間寫好。"},{"en":"If Esperanto needs only a fraction of the learning time, it may appeal to busy adults.","zh":"如果世界語只需一小部分學習時間，它可能吸引忙碌成年人。"},{"en":"The phrase emphasises strong time savings.","zh":"這個短語強調大量節省時間。"}],"source":"87 - Esperanto.pdf","sourcePage":9},{"front":"conventional language","meaning":"傳統語言；常規語言","examples":[{"en":"Esperanto may be easier than a conventional language.","zh":"世界語可能比傳統語言更容易。"},{"en":"A conventional language is an ordinary natural language used by a speech community.","zh":"傳統語言是由語言社群使用的普通自然語言。"},{"en":"French, Korean and Arabic are conventional languages that developed through real communities.","zh":"法語、韓語和阿拉伯語都是透過真實社群發展出來的傳統語言。"},{"en":"Compared with a conventional language, Esperanto may have fewer irregular forms.","zh":"與傳統語言相比，世界語可能有較少不規則形式。"},{"en":"The phrase contrasts ordinary natural languages with planned languages.","zh":"這個短語把普通自然語言與人造語言作對比。"}],"source":"87 - Esperanto.pdf","sourcePage":9},{"front":"while we may accept that","meaning":"雖然我們可以接受這一點","examples":[{"en":"While we may accept that Esperanto is easy, its usefulness is debatable.","zh":"雖然我們可以接受世界語容易，其實用性仍有爭議。"},{"en":"While we may accept that means even if we agree with one point, another issue remains.","zh":"“While we may accept that” 指即使我們同意某一點，另一問題仍然存在。"},{"en":"While we may accept that online lessons are convenient, they still require self-discipline.","zh":"雖然我們可以接受網上課堂方便，它們仍需要自律。"},{"en":"If a language is easy, that does not automatically mean it is useful.","zh":"如果一種語言容易，這不自動代表它有用。"},{"en":"The phrase introduces a concession before a contrast.","zh":"這個短語在對比前引出讓步。"}],"source":"87 - Esperanto.pdf","sourcePage":9},{"front":"far more problematic","meaning":"問題大得多","examples":[{"en":"The second question is far more problematic.","zh":"第二個問題大得多。"},{"en":"Far more problematic means much more difficult, complicated or troubling.","zh":"“Far more problematic” 指困難、複雜或令人困擾得多。"},{"en":"Choosing a restaurant is simple, but dividing the bill fairly can be far more problematic.","zh":"選餐廳很簡單，但公平分帳可能問題大得多。"},{"en":"Whether Esperanto is useful is far more problematic than whether it is easy.","zh":"世界語是否有用，比它是否容易更成問題。"},{"en":"The phrase compares levels of difficulty.","zh":"這個短語比較困難程度。"}],"source":"87 - Esperanto.pdf","sourcePage":9},{"front":"raise further issues","meaning":"引發進一步問題","examples":[{"en":"The usefulness of Esperanto raises further issues.","zh":"世界語的實用性引發進一步問題。"},{"en":"To raise further issues means to bring up additional questions or problems.","zh":"“Raise further issues” 指提出額外問題或困難。"},{"en":"A new school timetable may raise further issues about transport and lunch time.","zh":"新學校時間表可能引發關於交通和午膳時間的進一步問題。"},{"en":"If Esperanto is useful only to a small community, further questions about funding arise.","zh":"如果世界語只對小社群有用，就會出現關於資金的進一步問題。"},{"en":"The phrase shows that one discussion leads to more discussion.","zh":"這個短語顯示一場討論帶出更多討論。"}],"source":"87 - Esperanto.pdf","sourcePage":9},{"front":"the main one being whether","meaning":"主要問題是是否……","examples":[{"en":"The main issue is whether Esperanto is even necessary.","zh":"主要問題是世界語是否甚至有必要。"},{"en":"The main one being whether means the most important issue is the question of whether something is true or needed.","zh":"“The main one being whether” 指最重要的問題是某事是否真實或需要。"},{"en":"There are several problems with the plan, the main one being whether families can afford it.","zh":"該計劃有幾個問題，主要問題是家庭是否負擔得起。"},{"en":"If English already serves international communication, the main issue becomes whether Esperanto is necessary.","zh":"如果英語已服務國際溝通，主要問題就變成世界語是否有必要。"},{"en":"The phrase highlights the central question among several issues.","zh":"這個短語突出多個問題中的核心問題。"}],"source":"87 - Esperanto.pdf","sourcePage":9},{"front":"international communication","meaning":"國際溝通","examples":[{"en":"Esperanto was designed to improve international communication.","zh":"世界語被設計用來改善國際溝通。"},{"en":"International communication is communication between people, organisations or countries across borders.","zh":"國際溝通是跨越國界的人、組織或國家之間的溝通。"},{"en":"International communication is important in trade, travel, science and diplomacy.","zh":"國際溝通在貿易、旅行、科學和外交中很重要。"},{"en":"If people do not share a language, international communication can become slow and unequal.","zh":"如果人們沒有共同語言，國際溝通可能變得緩慢且不平等。"},{"en":"The phrase focuses on communication beyond one country.","zh":"這個短語強調一國以外的溝通。"}],"source":"87 - Esperanto.pdf","sourcePage":9},{"front":"indeed","meaning":"確實；真的","examples":[{"en":"Would international communication indeed be better with Esperanto?","zh":"國際溝通有世界語是否真的會更好？"},{"en":"Indeed means really or truly, often used to question or confirm a claim.","zh":"“Indeed” 指真的或確實，常用來質疑或確認一項主張。"},{"en":"Is this medicine indeed safer than the old one?","zh":"這種藥是否真的比舊藥更安全？"},{"en":"If supporters claim Esperanto improves communication, critics ask whether it indeed does so.","zh":"如果支持者聲稱世界語改善溝通，批評者會問它是否真的如此。"},{"en":"The word can add emphasis or careful doubt.","zh":"這個詞可以增加強調或謹慎懷疑。"}],"source":"87 - Esperanto.pdf","sourcePage":9},{"front":"other factors involved","meaning":"牽涉其他因素","examples":[{"en":"There may be other factors involved in international communication.","zh":"國際溝通中可能牽涉其他因素。"},{"en":"Other factors involved are additional causes or conditions that affect a situation.","zh":"“Other factors involved” 指影響情況的額外原因或條件。"},{"en":"Exam results depend on study time, but there are other factors involved, such as sleep and stress.","zh":"考試成績取決於溫習時間，但也牽涉其他因素，例如睡眠和壓力。"},{"en":"If communication fails, language may not be the only issue; politics and trust may also matter.","zh":"如果溝通失敗，語言未必是唯一問題；政治和信任也可能重要。"},{"en":"The phrase warns against explaining a problem too simply.","zh":"這個短語提醒不要過於簡化地解釋問題。"}],"source":"87 - Esperanto.pdf","sourcePage":10},{"front":"take that role","meaning":"承擔那個角色","examples":[{"en":"English virtually takes the role of international language.","zh":"英語實際上承擔了國際語言的角色。"},{"en":"To take that role means to perform or occupy that function.","zh":"“Take that role” 指執行或佔據該功能。"},{"en":"In a group project, one student may take the role of organiser.","zh":"在小組項目中，一名學生可能承擔組織者的角色。"},{"en":"If English takes the role of global second language, Esperanto has less practical space.","zh":"如果英語承擔全球第二語言的角色，世界語的實際空間就較少。"},{"en":"The phrase describes assuming a function or position.","zh":"這個短語描述承擔功能或位置。"}],"source":"87 - Esperanto.pdf","sourcePage":10},{"front":"virtually","meaning":"幾乎；實際上","examples":[{"en":"English has virtually become the global second language.","zh":"英語幾乎已成為全球第二語言。"},{"en":"Virtually means almost or in practice, even if not officially.","zh":"“Virtually” 指幾乎或實際上如此，即使不是正式如此。"},{"en":"The town centre is virtually empty after midnight.","zh":"午夜後，市中心幾乎空無一人。"},{"en":"If English is virtually the global second language, it functions that way in many situations.","zh":"如果英語實際上是全球第二語言，它在許多情況中都發揮這種功能。"},{"en":"The word describes practical reality rather than formal status.","zh":"這個詞描述實際現實，而不是正式地位。"}],"source":"87 - Esperanto.pdf","sourcePage":10},{"front":"divert state funds to","meaning":"將政府資金調撥至……","examples":[{"en":"Critics ask why governments should divert state funds to Esperanto.","zh":"批評者問為何政府應將政府資金調撥至世界語。"},{"en":"To divert state funds to something means to move government money away from other uses and spend it there.","zh":"“Divert state funds to” 某事指把政府金錢從其他用途轉移到該處使用。"},{"en":"A city may divert state funds to emergency housing after a storm.","zh":"風暴後，城市可能將政府資金調撥至緊急住房。"},{"en":"If funds are diverted to Esperanto, critics may ask what public benefit is gained.","zh":"如果資金被調撥至世界語，批評者可能詢問會得到甚麼公共利益。"},{"en":"The phrase raises questions about government spending priorities.","zh":"這個短語引出政府開支優先次序的問題。"}],"source":"87 - Esperanto.pdf","sourcePage":10},{"front":"state funds","meaning":"政府資金","examples":[{"en":"Some people question the use of state funds to support Esperanto.","zh":"有些人質疑使用政府資金支持世界語。"},{"en":"State funds are money controlled or provided by the government.","zh":"政府資金是由政府控制或提供的金錢。"},{"en":"Schools, hospitals and roads are often paid for with state funds.","zh":"學校、醫院和道路通常由政府資金支付。"},{"en":"If state funds support a small language community, taxpayers may ask whether it is fair.","zh":"如果政府資金支持小型語言社群，納稅人可能問這是否公平。"},{"en":"The phrase refers to public money, not private donations.","zh":"這個短語指公共金錢，而不是私人捐款。"}],"source":"87 - Esperanto.pdf","sourcePage":10},{"front":"support a speech community","meaning":"支持某個語言社群","examples":[{"en":"Governments may not want to support a marginalised speech community.","zh":"政府可能不想支持一個被邊緣化的語言社群。"},{"en":"To support a speech community means to provide help, funding or recognition to a group of language users.","zh":"“Support a speech community” 指向一群語言使用者提供幫助、資金或承認。"},{"en":"A school can support a speech community by offering classes in a minority language.","zh":"學校可以透過提供少數族裔語言課程來支持語言社群。"},{"en":"If governments support a language community, the language may gain teaching materials and public visibility.","zh":"如果政府支持語言社群，該語言可能獲得教材和公共能見度。"},{"en":"The phrase connects policy support with language survival.","zh":"這個短語把政策支援與語言生存連繫起來。"}],"source":"87 - Esperanto.pdf","sourcePage":10},{"front":"marginalised speech community","meaning":"被邊緣化的語言社群","examples":[{"en":"Esperanto may remain a marginalised speech community.","zh":"世界語可能仍是一個被邊緣化的語言社群。"},{"en":"A marginalised speech community is a group of language users with little power, recognition or public support.","zh":"被邊緣化的語言社群，是權力、承認或公共支援很少的語言使用者群體。"},{"en":"Speakers of a minority dialect may form a marginalised speech community if schools ignore their language.","zh":"如果學校忽視少數方言，其使用者可能形成被邊緣化的語言社群。"},{"en":"If a speech community is marginalised, its members may depend on volunteers rather than institutions.","zh":"如果語言社群被邊緣化，其成員可能依靠志願者而不是機構。"},{"en":"The phrase describes social and political weakness of a language group.","zh":"這個短語描述語言群體在社會和政治上的弱勢。"}],"source":"87 - Esperanto.pdf","sourcePage":10},{"front":"offering far greater utility","meaning":"提供更大實用價值","examples":[{"en":"Many natural languages offer far greater utility than Esperanto.","zh":"許多自然語言比世界語提供更大實用價值。"},{"en":"Offering far greater utility means providing much more practical usefulness.","zh":"“Offering far greater utility” 指提供多得多的實際用途。"},{"en":"Learning English may offer far greater utility for international business than learning a small hobby language.","zh":"學習英語對國際商業的實用價值，可能遠高於學習小眾興趣語言。"},{"en":"If a language is used in jobs, travel and media, it offers greater practical value.","zh":"如果一種語言用於工作、旅行和媒體，它就提供更大實用價值。"},{"en":"The phrase compares usefulness in real life.","zh":"這個短語比較現實生活中的有用程度。"}],"source":"87 - Esperanto.pdf","sourcePage":10},{"front":"emotional, complex, and confusing","meaning":"情感化、複雜而令人困惑","examples":[{"en":"The answers are emotional, complex, and confusing.","zh":"答案是情感化、複雜而令人困惑的。"},{"en":"Emotional, complex, and confusing means involving strong feelings, many factors and unclear conclusions.","zh":"“Emotional, complex, and confusing” 指涉及強烈感受、許多因素和不清晰結論。"},{"en":"Family arguments about money can become emotional, complex and confusing.","zh":"家庭關於金錢的爭論可能變得情感化、複雜而令人困惑。"},{"en":"Debates about language can be emotional because they involve identity and belonging.","zh":"語言辯論可能情感化，因為它涉及身份和歸屬感。"},{"en":"The phrase shows that the issue is not easy to settle.","zh":"這個短語顯示議題不容易解決。"}],"source":"87 - Esperanto.pdf","sourcePage":10},{"front":"one problem with","meaning":"……的一個問題","examples":[{"en":"One problem with Esperanto is that it is culturally European.","zh":"世界語的一個問題是它在文化上偏歐洲。"},{"en":"One problem with something means one weakness or difficulty connected with it.","zh":"“One problem with” 某事指與它有關的一個弱點或困難。"},{"en":"One problem with online learning is that students may feel isolated.","zh":"網上學習的一個問題是學生可能感到孤立。"},{"en":"If one problem with a language is cultural bias, some learners may find it less neutral.","zh":"如果一種語言的一個問題是文化偏向，一些學習者可能覺得它不夠中立。"},{"en":"The phrase introduces a specific criticism.","zh":"這個短語引出具體批評。"}],"source":"87 - Esperanto.pdf","sourcePage":10},{"front":"culturally European","meaning":"文化上偏歐洲的","examples":[{"en":"Esperanto is culturally European in its vocabulary and structure.","zh":"世界語在詞彙和結構上文化偏歐洲。"},{"en":"Culturally European means shaped mainly by European languages, ideas or patterns.","zh":"“Culturally European” 指主要由歐洲語言、思想或模式塑造。"},{"en":"A textbook may feel culturally European if all its examples come from European history and daily life.","zh":"如果教科書所有例子都來自歐洲歷史和日常生活，它可能感覺文化上偏歐洲。"},{"en":"If Esperanto is culturally European, Asian learners may not find it equally familiar.","zh":"如果世界語文化上偏歐洲，亞洲學習者可能不會覺得它同樣熟悉。"},{"en":"The phrase describes cultural influence, not just geography.","zh":"這個短語描述文化影響，而不只是地理。"}],"source":"87 - Esperanto.pdf","sourcePage":10},{"front":"vocabulary and internal rules","meaning":"詞彙和內部規則","examples":[{"en":"Esperanto’s vocabulary and internal rules derive from European languages.","zh":"世界語的詞彙和內部規則源自歐洲語言。"},{"en":"Vocabulary and internal rules are the words of a language and the grammar system that organises them.","zh":"詞彙和內部規則是語言中的詞語，以及組織它們的文法系統。"},{"en":"A language course must teach both vocabulary and internal rules so students can make sentences.","zh":"語言課必須教授詞彙和內部規則，讓學生能組成句子。"},{"en":"If vocabulary and rules come from Europe, learners with European languages may have an advantage.","zh":"如果詞彙和規則來自歐洲，擁有歐洲語言背景的學習者可能有優勢。"},{"en":"The phrase combines word choice with grammatical structure.","zh":"這個短語結合詞語選擇與文法結構。"}],"source":"87 - Esperanto.pdf","sourcePage":11},{"front":"rules of construction","meaning":"構詞規則","examples":[{"en":"The rules of construction in Esperanto derive from European languages.","zh":"世界語的構詞規則源自歐洲語言。"},{"en":"Rules of construction are the rules for building words, phrases or sentences.","zh":"構詞規則是建立詞語、短語或句子的規則。"},{"en":"In English, rules of construction help students know where adjectives and verbs should go.","zh":"在英語中，構詞和句子規則幫助學生知道形容詞和動詞應放在哪裡。"},{"en":"If rules of construction are unfamiliar, learners may find a language harder.","zh":"如果構詞規則不熟悉，學習者可能覺得語言更難。"},{"en":"The phrase refers to how language forms are built.","zh":"這個短語指語言形式如何被建立。"}],"source":"87 - Esperanto.pdf","sourcePage":11},{"front":"derive from","meaning":"源自","examples":[{"en":"Esperanto’s vocabulary derives from European languages.","zh":"世界語的詞彙源自歐洲語言。"},{"en":"To derive from something means to come from or be based on it.","zh":"“Derive from” 某事指來自或建基於它。"},{"en":"Many English words derive from Latin and French.","zh":"許多英語詞源自拉丁語和法語。"},{"en":"If a word derives from a familiar language, learners may remember it more easily.","zh":"如果一個詞源自熟悉語言，學習者可能更容易記住它。"},{"en":"The phrase explains origin.","zh":"這個短語解釋來源。"}],"source":"87 - Esperanto.pdf","sourcePage":11},{"front":"make it difficult for","meaning":"令……對某人來說困難","examples":[{"en":"European structures may make Esperanto difficult for Asian learners.","zh":"歐洲結構可能令世界語對亞洲學習者來說困難。"},{"en":"To make it difficult for someone means to create obstacles that make a task harder for them.","zh":"“Make it difficult for” 某人指造成障礙，使任務對他們更難。"},{"en":"A noisy classroom can make it difficult for students to concentrate.","zh":"嘈雜課室可以令學生難以集中。"},{"en":"If a language’s structure is unfamiliar, it may make learning difficult for some groups.","zh":"如果語言結構不熟悉，它可能令某些群體學習困難。"},{"en":"The phrase connects a cause with difficulty for a person or group.","zh":"這個短語把原因與某人或某群體的困難連繫起來。"}],"source":"87 - Esperanto.pdf","sourcePage":11},{"front":"Asian learners","meaning":"亞洲學習者","examples":[{"en":"Esperanto can be difficult for Asian learners.","zh":"世界語對亞洲學習者來說可能困難。"},{"en":"Asian learners are students from Asian language backgrounds or countries.","zh":"亞洲學習者是來自亞洲語言背景或國家的學生。"},{"en":"Asian learners of European languages may need extra practice with unfamiliar grammar patterns.","zh":"學習歐洲語言的亞洲學習者可能需要額外練習不熟悉的文法模式。"},{"en":"If Esperanto is based mainly on European vocabulary, Asian learners may not gain the same advantage.","zh":"如果世界語主要建基於歐洲詞彙，亞洲學習者可能得不到同樣優勢。"},{"en":"The phrase identifies a learner group by regional language background.","zh":"這個短語按地區語言背景指出學習者群體。"}],"source":"87 - Esperanto.pdf","sourcePage":11},{"front":"large and imposing vocabulary","meaning":"龐大而令人卻步的詞彙量","examples":[{"en":"Esperanto has a large and imposing vocabulary.","zh":"世界語有龐大而令人卻步的詞彙量。"},{"en":"A large and imposing vocabulary is a set of words that feels big, difficult or intimidating to learners.","zh":"龐大而令人卻步的詞彙量，是令學習者感到很多、困難或害怕的一組詞語。"},{"en":"A medical textbook may have a large and imposing vocabulary for beginners.","zh":"醫學教科書對初學者來說可能有龐大而令人卻步的詞彙量。"},{"en":"If a language has many unfamiliar words, students may feel discouraged before they start.","zh":"如果一種語言有許多不熟悉詞語，學生可能在開始前已感到氣餒。"},{"en":"The phrase suggests vocabulary size can make learning feel harder.","zh":"這個短語暗示詞彙量大小可以令學習感覺更難。"}],"source":"87 - Esperanto.pdf","sourcePage":11},{"front":"nouns","meaning":"名詞","examples":[{"en":"Many Esperanto nouns were chosen idiosyncratically.","zh":"許多世界語名詞是以獨特方式選擇的。"},{"en":"Nouns are words that name people, places, things or ideas.","zh":"名詞是命名人物、地方、事物或想法的詞語。"},{"en":"In the sentence “The student reads a book,” “student” and “book” are nouns.","zh":"在句子 “The student reads a book” 中，“student” 和 “book” 是名詞。"},{"en":"If many nouns in a language are unfamiliar, learners may need more memorisation.","zh":"如果一種語言中許多名詞不熟悉，學習者可能需要更多記憶。"},{"en":"The word refers to a basic part of speech.","zh":"這個詞指基本詞類。"}],"source":"87 - Esperanto.pdf","sourcePage":11},{"front":"idiosyncratically chosen","meaning":"以獨特而不尋常的方式選擇","examples":[{"en":"Some Esperanto nouns were idiosyncratically chosen.","zh":"一些世界語名詞是以獨特而不尋常的方式選擇的。"},{"en":"Idiosyncratically chosen means selected in an unusual, personal or not easily predictable way.","zh":"“Idiosyncratically chosen” 指以不尋常、個人化或不容易預測的方式選出。"},{"en":"A teacher’s idiosyncratically chosen examples may be memorable but sometimes confusing.","zh":"老師以獨特方式選擇的例子可能令人難忘，但有時令人困惑。"},{"en":"If words are chosen idiosyncratically, learners cannot always guess them from clear rules.","zh":"如果詞語以不尋常方式選擇，學習者不一定能從清晰規則猜出它們。"},{"en":"The phrase suggests personal choice rather than systematic design.","zh":"這個短語暗示個人選擇，而不是系統性設計。"}],"source":"87 - Esperanto.pdf","sourcePage":11},{"front":"unnecessary complexity","meaning":"不必要的複雜性","examples":[{"en":"Esperanto contains a certain unnecessary complexity.","zh":"世界語包含某種不必要的複雜性。"},{"en":"Unnecessary complexity means difficulty that is not needed and could have been avoided.","zh":"不必要的複雜性是本來不需要且可以避免的困難。"},{"en":"A form with ten extra questions may create unnecessary complexity for applicants.","zh":"有十條額外問題的表格可能為申請人造成不必要的複雜性。"},{"en":"If a language rule adds difficulty without clear benefit, learners may see it as unnecessary complexity.","zh":"如果語言規則增加困難卻沒有清晰好處，學習者可能視它為不必要的複雜性。"},{"en":"The phrase criticises a system for being more complicated than it needs to be.","zh":"這個短語批評系統比需要的更複雜。"}],"source":"87 - Esperanto.pdf","sourcePage":11},{"front":"professional linguist","meaning":"專業語言學家","examples":[{"en":"Zamenhof was not a professional linguist.","zh":"Zamenhof 不是專業語言學家。"},{"en":"A professional linguist is a trained specialist who studies language scientifically.","zh":"專業語言學家是受過訓練、以科學方式研究語言的專家。"},{"en":"A professional linguist may study grammar, sounds, meaning or language change.","zh":"專業語言學家可能研究文法、聲音、意思或語言變化。"},{"en":"If a language inventor is not a professional linguist, some design problems may be missed.","zh":"如果語言發明者不是專業語言學家，一些設計問題可能被忽略。"},{"en":"The phrase identifies expertise in the scientific study of language.","zh":"這個短語指出在語言科學研究方面的專業知識。"}],"source":"87 - Esperanto.pdf","sourcePage":11},{"front":"recognise","meaning":"意識到；認出","examples":[{"en":"Zamenhof did not recognise some unnecessary complexity in Esperanto.","zh":"Zamenhof 沒有意識到世界語中某些不必要的複雜性。"},{"en":"To recognise something means to notice, identify or understand it.","zh":"“Recognise” 某事指注意到、辨認出或理解它。"},{"en":"A teacher may recognise a student’s anxiety even when the student stays quiet.","zh":"即使學生保持安靜，老師也可能意識到他的焦慮。"},{"en":"If an inventor fails to recognise a problem, the design may keep that weakness.","zh":"如果發明者未能意識到問題，設計可能保留該弱點。"},{"en":"The word can mean seeing something clearly as what it is.","zh":"這個詞可以指清楚看出某事本質。"}],"source":"87 - Esperanto.pdf","sourcePage":11},{"front":"reformed Esperanto","meaning":"改革版世界語","examples":[{"en":"Zamenhof suggested a reformed Esperanto in 1894.","zh":"Zamenhof 於1894年提出改革版世界語。"},{"en":"Reformed Esperanto means a revised version of Esperanto with proposed changes.","zh":"改革版世界語指帶有建議改動的修訂版世界語。"},{"en":"A reformed school timetable may remove long gaps and shorten waiting time.","zh":"改革版學校時間表可能移除長空檔並縮短等候時間。"},{"en":"If Esperanto had been reformed, some difficult rules or words might have changed.","zh":"如果世界語曾被改革，一些困難規則或詞語可能已改變。"},{"en":"The phrase refers to an attempted improvement of the original language.","zh":"這個短語指對原本語言的嘗試改良。"}],"source":"87 - Esperanto.pdf","sourcePage":12},{"front":"be loath to","meaning":"不願意","examples":[{"en":"Esperanto speakers were loath to alter the language.","zh":"世界語使用者不願意改變該語言。"},{"en":"To be loath to do something means to be unwilling or reluctant to do it.","zh":"“Be loath to” 做某事指不願意或勉強去做。"},{"en":"A student may be loath to delete a paragraph after spending hours writing it.","zh":"學生花了幾小時寫一段後，可能不願意刪除它。"},{"en":"If speakers have already mastered a language, they may be loath to change its rules.","zh":"如果使用者已經掌握一種語言，他們可能不願意改變其規則。"},{"en":"The phrase shows hesitation or resistance.","zh":"這個短語顯示猶豫或抗拒。"}],"source":"87 - Esperanto.pdf","sourcePage":12},{"front":"alter a language","meaning":"改變一種語言","examples":[{"en":"The speakers did not want to alter a language they had mastered.","zh":"使用者不想改變一種他們已掌握的語言。"},{"en":"To alter a language means to change its words, grammar or writing system.","zh":"“Alter a language” 指改變其詞語、文法或書寫系統。"},{"en":"A committee may alter a language course by removing outdated vocabulary.","zh":"委員會可能透過移除過時詞彙來改變語言課程。"},{"en":"If learners have memorised old rules, altering the language may frustrate them.","zh":"如果學習者已記住舊規則，改變該語言可能令他們沮喪。"},{"en":"The phrase describes changing the language itself, not just learning it differently.","zh":"這個短語描述改變語言本身，而不只是用不同方式學習它。"}],"source":"87 - Esperanto.pdf","sourcePage":12},{"front":"reject proposals","meaning":"拒絕建議","examples":[{"en":"Esperanto speakers rejected Zamenhof’s proposals.","zh":"世界語使用者拒絕了 Zamenhof 的建議。"},{"en":"To reject proposals means to refuse to accept suggested plans or changes.","zh":"“Reject proposals” 指拒絕接受被提出的計劃或改動。"},{"en":"A school may reject proposals for longer lessons if students and teachers oppose them.","zh":"如果學生和老師反對，學校可能拒絕延長課堂的建議。"},{"en":"If a community rejects reform proposals, the original system remains in place.","zh":"如果社群拒絕改革建議，原本制度就會保留下來。"},{"en":"The phrase describes formal or collective refusal.","zh":"這個短語描述正式或集體拒絕。"}],"source":"87 - Esperanto.pdf","sourcePage":12},{"front":"special French committee","meaning":"法國特別委員會","examples":[{"en":"A special French committee discussed an international language.","zh":"一個法國特別委員會討論了一種國際語言。"},{"en":"A special French committee is a particular committee in France formed to examine an issue.","zh":"法國特別委員會是在法國成立、用來研究某議題的特定委員會。"},{"en":"A special committee may be created when ordinary meetings cannot solve a difficult problem.","zh":"當普通會議無法解決困難問題時，可能成立特別委員會。"},{"en":"If such a committee discusses language, the issue has gained official or intellectual attention.","zh":"如果這類委員會討論語言，該議題就獲得官方或知識界注意。"},{"en":"The phrase identifies a formal group with a specific task.","zh":"這個短語指出具有特定任務的正式群體。"}],"source":"87 - Esperanto.pdf","sourcePage":12},{"front":"discuss the adoption of","meaning":"討論採納……","examples":[{"en":"The committee discussed the adoption of a standard international language.","zh":"該委員會討論採納一種標準國際語言。"},{"en":"To discuss the adoption of something means to talk about whether it should be officially accepted or used.","zh":"“Discuss the adoption of” 某事指討論是否應正式接受或使用它。"},{"en":"A school may discuss the adoption of a new textbook before the next term begins.","zh":"學校可能在下學期開始前討論採納新教科書。"},{"en":"If a committee discusses adoption of a language, it is considering formal use.","zh":"如果委員會討論採納某語言，就是在考慮正式使用。"},{"en":"The phrase connects debate with possible official acceptance.","zh":"這個短語把討論與可能的正式接受連繫起來。"}],"source":"87 - Esperanto.pdf","sourcePage":12},{"front":"standard international language","meaning":"標準國際語言","examples":[{"en":"The committee considered a standard international language.","zh":"該委員會考慮了一種標準國際語言。"},{"en":"A standard international language is a shared language intended for communication between people from different countries.","zh":"標準國際語言是旨在讓不同國家的人溝通的共同語言。"},{"en":"A standard international language would need clear rules and wide acceptance.","zh":"標準國際語言需要清晰規則和廣泛接受。"},{"en":"If governments supported one standard language, international communication might become more uniform.","zh":"如果政府支持一種標準語言，國際溝通可能變得更統一。"},{"en":"The phrase describes a planned common language for global use.","zh":"這個短語描述為全球使用而計劃的共同語言。"}],"source":"87 - Esperanto.pdf","sourcePage":12},{"front":"in the meantime","meaning":"與此同時","examples":[{"en":"In the meantime, another artificial language had emerged.","zh":"與此同時，另一種人工語言已經出現。"},{"en":"In the meantime means during the same period while something else is happening.","zh":"“In the meantime” 指在另一件事發生的同一時期。"},{"en":"The teacher checked homework; in the meantime, students read quietly.","zh":"老師檢查功課；與此同時，學生安靜閱讀。"},{"en":"If Esperanto supporters debated reform, another language could appear during that period.","zh":"如果世界語支持者辯論改革，另一種語言可能在那段期間出現。"},{"en":"The phrase connects two events happening around the same time.","zh":"這個短語連接大約同時發生的兩件事。"}],"source":"87 - Esperanto.pdf","sourcePage":12},{"front":"emerge","meaning":"出現；興起","examples":[{"en":"Another artificial language emerged after Esperanto.","zh":"另一種人工語言在世界語之後出現。"},{"en":"To emerge means to appear, become known or come into existence.","zh":"“Emerge” 指出現、為人所知或開始存在。"},{"en":"A new student leader may emerge after classmates see her organise a project well.","zh":"當同學看見某學生成功組織項目後，新的學生領袖可能出現。"},{"en":"If a rival language emerges, supporters may have to choose between alternatives.","zh":"如果競爭語言興起，支持者可能需要在不同選項中選擇。"},{"en":"The word describes something coming into public view.","zh":"這個詞描述某事進入公眾視野。"}],"source":"87 - Esperanto.pdf","sourcePage":12},{"front":"Ido","meaning":"伊多語","examples":[{"en":"Ido was another artificial language based on proposed reforms.","zh":"伊多語是另一種基於改革建議的人工語言。"},{"en":"Ido is a constructed language that developed from proposed changes to Esperanto.","zh":"伊多語是一種由世界語改革建議發展出來的人造語言。"},{"en":"A language history class may compare Esperanto and Ido to show how reform can split a movement.","zh":"語言史課可能比較世界語和伊多語，以顯示改革如何分裂運動。"},{"en":"If supporters move from Esperanto to Ido, the original community loses some strength.","zh":"如果支持者從世界語轉向伊多語，原本社群就失去部分力量。"},{"en":"The word names a rival planned language.","zh":"這個詞指一種競爭性人造語言。"}],"source":"87 - Esperanto.pdf","sourcePage":12},{"front":"a product of","meaning":"……的產物","examples":[{"en":"Ido was a product of various academics.","zh":"伊多語是多位學者的產物。"},{"en":"A product of something means the result created by a particular person, group or process.","zh":"“A product of” 某事指由特定人物、群體或過程創造出的結果。"},{"en":"A school festival may be a product of months of student teamwork.","zh":"學校節日可能是學生數月團隊合作的產物。"},{"en":"If Ido was a product of academics, it was shaped by committee-like intellectual work.","zh":"如果伊多語是學者的產物，它就是由類似委員會的知識工作塑造。"},{"en":"The phrase explains origin or cause.","zh":"這個短語解釋來源或原因。"}],"source":"87 - Esperanto.pdf","sourcePage":12},{"front":"various academics","meaning":"多位學者","examples":[{"en":"Ido was created by various academics.","zh":"伊多語由多位學者創造。"},{"en":"Various academics means several scholars or university-level experts from different backgrounds.","zh":"“Various academics” 指來自不同背景的幾位學者或大學級專家。"},{"en":"Various academics may work together on a research project about education policy.","zh":"多位學者可能一起研究教育政策項目。"},{"en":"If various academics design a language, the result may reflect many opinions.","zh":"如果多位學者設計一種語言，結果可能反映許多意見。"},{"en":"The phrase highlights multiple expert contributors.","zh":"這個短語強調多名專家貢獻者。"}],"source":"87 - Esperanto.pdf","sourcePage":13},{"front":"embed the changes","meaning":"融入改動","examples":[{"en":"The creators of Ido embedded changes that Esperanto was thought to need.","zh":"伊多語創造者融入了世界語被認為需要的改動。"},{"en":"To embed the changes means to build the changes into the system itself.","zh":"“Embed the changes” 指把改動建入系統本身。"},{"en":"A school may embed new safety rules into its daily routine.","zh":"學校可能把新的安全規則融入日常流程。"},{"en":"If reforms are embedded in a new language, users do not treat them as optional additions.","zh":"如果改革被融入新語言，使用者就不會把它們視為可選附加項。"},{"en":"The phrase shows that changes become part of the structure.","zh":"這個短語顯示改動成為結構的一部分。"}],"source":"87 - Esperanto.pdf","sourcePage":13},{"front":"was thought to need","meaning":"被認為需要","examples":[{"en":"Ido included changes that Esperanto was thought to need.","zh":"伊多語包含世界語被認為需要的改動。"},{"en":"Was thought to need means people believed something required those changes or improvements.","zh":"“Was thought to need” 指人們相信某事需要那些改動或改善。"},{"en":"The old timetable was thought to need shorter breaks and clearer room changes.","zh":"舊時間表被認為需要更短休息和更清晰課室轉換。"},{"en":"If Esperanto was thought to need reform, some users saw weaknesses in the original design.","zh":"如果世界語被認為需要改革，一些使用者就看見原本設計中的弱點。"},{"en":"The phrase reports a belief about what improvement is necessary.","zh":"這個短語報告關於必要改善的看法。"}],"source":"87 - Esperanto.pdf","sourcePage":13},{"front":"lofty goals","meaning":"崇高目標","examples":[{"en":"Ido shared the same lofty goals as Esperanto.","zh":"伊多語與世界語有同樣的崇高目標。"},{"en":"Lofty goals are high, ambitious and morally serious aims.","zh":"崇高目標是高遠、雄心勃勃且具道德意義的目標。"},{"en":"A charity may have lofty goals of ending hunger in every school.","zh":"慈善機構可能有消除每間學校飢餓問題的崇高目標。"},{"en":"If a movement has lofty goals, it may inspire supporters even when success is unlikely.","zh":"如果運動有崇高目標，即使成功機會不大，也可能激勵支持者。"},{"en":"The phrase suggests noble ambition.","zh":"這個短語暗示高尚抱負。"}],"source":"87 - Esperanto.pdf","sourcePage":13},{"front":"support base","meaning":"支持基礎","examples":[{"en":"Ido divided the support base of Esperanto.","zh":"伊多語分裂了世界語的支持基礎。"},{"en":"A support base is the group of people who support a movement, leader or idea.","zh":"支持基礎是支持某運動、領袖或想法的一群人。"},{"en":"A political party may lose its support base if voters feel ignored.","zh":"如果選民覺得被忽視，政黨可能失去支持基礎。"},{"en":"If a rival language divides the support base, the original movement becomes weaker.","zh":"如果競爭語言分裂支持基礎，原本運動會變弱。"},{"en":"The phrase describes the foundation of public or community support.","zh":"這個短語描述公眾或社群支持的基礎。"}],"source":"87 - Esperanto.pdf","sourcePage":13},{"front":"defect to","meaning":"轉投","examples":[{"en":"A large number of Esperanto supporters defected to Ido.","zh":"大量世界語支持者轉投伊多語。"},{"en":"To defect to another side means to leave one group and join a rival group.","zh":"“Defect to” 另一方指離開原本群體並加入競爭群體。"},{"en":"A player may defect to another team if they feel undervalued.","zh":"如果球員覺得不被重視，可能轉投另一隊。"},{"en":"If many supporters defect to a new language, the old movement loses people and energy.","zh":"如果許多支持者轉投新語言，舊運動就失去人手和能量。"},{"en":"The phrase often suggests a dramatic change of loyalty.","zh":"這個短語常暗示忠誠的重大轉變。"}],"source":"87 - Esperanto.pdf","sourcePage":13},{"front":"undergo further changes","meaning":"經歷進一步改動","examples":[{"en":"Ido underwent further changes through committees.","zh":"伊多語透過委員會經歷進一步改動。"},{"en":"To undergo further changes means to experience additional modifications.","zh":"“Undergo further changes” 指經歷額外修改。"},{"en":"A school plan may undergo further changes after parents give feedback.","zh":"學校計劃在家長給予回饋後，可能經歷進一步改動。"},{"en":"If a language undergoes repeated changes, learners may feel uncertain about which version to use.","zh":"如果一種語言反覆經歷改動，學習者可能不確定應使用哪個版本。"},{"en":"The phrase describes continuing development or revision.","zh":"這個短語描述持續發展或修訂。"}],"source":"87 - Esperanto.pdf","sourcePage":13},{"front":"committee after committee","meaning":"一個又一個委員會","examples":[{"en":"Ido was changed by committee after committee.","zh":"伊多語被一個又一個委員會改動。"},{"en":"Committee after committee means many committees one after another.","zh":"“Committee after committee” 指許多委員會一個接一個。"},{"en":"A building project may be delayed if committee after committee asks for revisions.","zh":"如果一個又一個委員會要求修改，建築項目可能被延誤。"},{"en":"If a language is changed by committee after committee, its rules may become unstable.","zh":"如果一種語言被一個又一個委員會改動，其規則可能變得不穩定。"},{"en":"The phrase can imply excessive bureaucracy or repeated review.","zh":"這個短語可以暗示過度官僚或反覆審查。"}],"source":"87 - Esperanto.pdf","sourcePage":13},{"front":"eventually leading to","meaning":"最終導致","examples":[{"en":"The changes eventually led to the formation of an academy.","zh":"這些改動最終導致一所學院的成立。"},{"en":"Eventually leading to means finally causing a later result after a process.","zh":"“Eventually leading to” 指經過一個過程後最終造成後來的結果。"},{"en":"Small disagreements in a club may eventually lead to a new set of rules.","zh":"社團中的小分歧可能最終導致一套新規則。"},{"en":"If language reforms continue, they may eventually lead to a formal institution.","zh":"如果語言改革持續，它們可能最終導致正式機構成立。"},{"en":"The phrase links a chain of events to its outcome.","zh":"這個短語把一連串事件與結果連繫起來。"}],"source":"87 - Esperanto.pdf","sourcePage":13},{"front":"formation of","meaning":"……的成立","examples":[{"en":"The process led to the formation of an independent academy.","zh":"該過程導致一所獨立學院的成立。"},{"en":"Formation of something means the creation or establishment of it.","zh":"“Formation of” 某事指其創立或建立。"},{"en":"The formation of a student council gives pupils a clearer voice in school.","zh":"學生會的成立令學生在學校中有更清晰的聲音。"},{"en":"If repeated meetings lead to formation of an academy, the movement becomes more organised.","zh":"如果反覆會議導致學院成立，該運動就變得更有組織。"},{"en":"The phrase describes the beginning of a group or institution.","zh":"這個短語描述群體或機構的開始。"}],"source":"87 - Esperanto.pdf","sourcePage":13},{"front":"independent academy","meaning":"獨立學院","examples":[{"en":"Ido eventually formed an independent academy.","zh":"伊多語最終形成一所獨立學院。"},{"en":"An independent academy is a separate institution that manages or studies a field without direct control by another body.","zh":"獨立學院是一個不受另一機構直接控制、管理或研究某領域的獨立機構。"},{"en":"An independent academy may set standards, publish reports and organise experts.","zh":"獨立學院可能制定標準、出版報告和組織專家。"},{"en":"If a language creates an independent academy, it may try to control rules more formally.","zh":"如果一種語言創立獨立學院，它可能嘗試更正式地管理規則。"},{"en":"The phrase suggests organised authority outside the original movement.","zh":"這個短語暗示原本運動以外的有組織權威。"}],"source":"87 - Esperanto.pdf","sourcePage":13},{"front":"suffer a substantial decline","meaning":"大幅衰落","examples":[{"en":"Ido suffered a substantial decline after losing its advocate.","zh":"伊多語失去其支持者後大幅衰落。"},{"en":"To suffer a substantial decline means to experience a large fall in support, use or success.","zh":"“Suffer a substantial decline” 指在支持、使用或成功方面經歷大幅下降。"},{"en":"A shop may suffer a substantial decline in customers after a new mall opens nearby.","zh":"新商場在附近開業後，小店可能經歷顧客大幅下降。"},{"en":"If a language loses its main supporters, its movement may decline quickly.","zh":"如果一種語言失去主要支持者，其運動可能迅速衰落。"},{"en":"The phrase describes a serious downward change.","zh":"這個短語描述嚴重的下跌變化。"}],"source":"87 - Esperanto.pdf","sourcePage":14},{"front":"following the death of","meaning":"在……去世之後","examples":[{"en":"Ido declined following the death of its best-known advocate.","zh":"伊多語在其最著名支持者去世之後衰落。"},{"en":"Following the death of someone means after that person died.","zh":"“Following the death of” 某人指在該人去世之後。"},{"en":"Following the death of a school founder, a new principal may continue the mission.","zh":"在學校創辦人去世之後，新校長可能繼續其使命。"},{"en":"If a movement declines after a leader dies, it may have depended heavily on that person.","zh":"如果運動在領袖去世後衰落，它可能曾高度依賴該人。"},{"en":"The phrase connects a later event with someone’s death.","zh":"這個短語把後來事件與某人的死亡連繫起來。"}],"source":"87 - Esperanto.pdf","sourcePage":14},{"front":"best-known advocate","meaning":"最著名的支持者","examples":[{"en":"Ido’s best-known advocate died in a car accident.","zh":"伊多語最著名的支持者在車禍中去世。"},{"en":"A best-known advocate is the most famous person publicly supporting a cause or idea.","zh":"最著名的支持者是公開支持某事業或想法的最有名人物。"},{"en":"A charity’s best-known advocate may attract media attention and donations.","zh":"慈善機構最著名的支持者可能吸引媒體注意和捐款。"},{"en":"If a movement loses its best-known advocate, public interest may fall.","zh":"如果運動失去最著名的支持者，公眾興趣可能下降。"},{"en":"The phrase identifies a famous supporter, not necessarily the founder.","zh":"這個短語指出著名支持者，不一定是創辦人。"}],"source":"87 - Esperanto.pdf","sourcePage":14},{"front":"car accident","meaning":"車禍","examples":[{"en":"The advocate died in a car accident.","zh":"該支持者死於車禍。"},{"en":"A car accident is an unexpected crash or collision involving a car.","zh":"車禍是涉及汽車的意外撞車或碰撞。"},{"en":"A car accident near school can delay buses and worry parents.","zh":"學校附近的車禍可能延誤巴士並令家長擔心。"},{"en":"If a key supporter dies in a car accident, a movement may lose leadership suddenly.","zh":"如果重要支持者死於車禍，運動可能突然失去領導。"},{"en":"The phrase refers to a road accident involving a vehicle.","zh":"這個短語指涉及車輛的道路意外。"}],"source":"87 - Esperanto.pdf","sourcePage":14},{"front":"the advent of","meaning":"……的來臨","examples":[{"en":"Ido declined after the advent of World War One.","zh":"伊多語在第一次世界大戰來臨後衰落。"},{"en":"The advent of something means the arrival or beginning of an important event or period.","zh":"“The advent of” 某事指重要事件或時期的到來或開始。"},{"en":"The advent of smartphones changed how students communicate and study.","zh":"智能手機的來臨改變了學生溝通和學習的方式。"},{"en":"If a movement weakens after the advent of war, outside history has disrupted it.","zh":"如果一場運動在戰爭來臨後變弱，外部歷史就打斷了它。"},{"en":"The phrase is formal and often used for major changes.","zh":"這個短語較正式，常用於重大變化。"}],"source":"87 - Esperanto.pdf","sourcePage":14},{"front":"World War One","meaning":"第一次世界大戰","examples":[{"en":"The advent of World War One damaged the Ido movement.","zh":"第一次世界大戰的來臨損害了伊多語運動。"},{"en":"World War One was a major global conflict that began in 1914 and involved many countries.","zh":"第一次世界大戰是一場始於1914年、涉及許多國家的重大全球衝突。"},{"en":"World War One disrupted travel, education, publishing and international meetings.","zh":"第一次世界大戰打亂了旅行、教育、出版和國際會議。"},{"en":"If an international language movement depends on cross-border contact, war can harm it badly.","zh":"如果國際語言運動依賴跨境接觸，戰爭可以嚴重傷害它。"},{"en":"The phrase names a historical event that affected language movements.","zh":"這個短語指影響語言運動的歷史事件。"}],"source":"87 - Esperanto.pdf","sourcePage":14},{"front":"most vocal proponent","meaning":"最積極發聲的支持者","examples":[{"en":"Ido’s most vocal proponent later created Novial.","zh":"伊多語最積極發聲的支持者後來創造了諾維亞語。"},{"en":"A most vocal proponent is the supporter who speaks most publicly and actively for an idea.","zh":"最積極發聲的支持者，是最公開和積極為某想法說話的人。"},{"en":"A school reform’s most vocal proponent may write articles and attend meetings to defend it.","zh":"學校改革最積極發聲的支持者可能寫文章和參加會議來捍衛它。"},{"en":"If the most vocal supporter changes direction, others may feel confused or follow him.","zh":"如果最積極支持者改變方向，其他人可能感到困惑或跟隨他。"},{"en":"The phrase highlights public advocacy and loud support.","zh":"這個短語強調公開倡議和有力支持。"}],"source":"87 - Esperanto.pdf","sourcePage":14},{"front":"publish his own constructed language","meaning":"發表自己的人工語言","examples":[{"en":"The proponent published his own constructed language after the war.","zh":"該支持者在戰後發表自己的人工語言。"},{"en":"To publish his own constructed language means to release a planned language that he personally designed.","zh":"“Publish his own constructed language” 指發表他個人設計的人造語言。"},{"en":"A writer may publish his own fantasy language in a novel appendix.","zh":"作家可能在小說附錄中發表自己的幻想語言。"},{"en":"If a supporter publishes a new language, the older movement may become even more divided.","zh":"如果支持者發表新語言，較舊的運動可能變得更加分裂。"},{"en":"The phrase describes making a personal language design public.","zh":"這個短語描述把個人語言設計公開。"}],"source":"87 - Esperanto.pdf","sourcePage":14},{"front":"Novial","meaning":"諾維亞語","examples":[{"en":"Novial was another constructed language created after the war.","zh":"諾維亞語是戰後創造的另一種人工語言。"},{"en":"Novial is a constructed language created as another proposed international auxiliary language.","zh":"諾維亞語是一種人造語言，被創造為另一種國際輔助語言方案。"},{"en":"A student studying planned languages may compare Esperanto, Ido and Novial.","zh":"研究人造語言的學生可能比較世界語、伊多語和諾維亞語。"},{"en":"If Novial appeared after Ido, the artificial-language movement became more fragmented.","zh":"如果諾維亞語在伊多語之後出現，人工語言運動就變得更分裂。"},{"en":"The word names a later rival in the history of constructed languages.","zh":"這個詞指人造語言歷史中較後出現的競爭語言。"}],"source":"87 - Esperanto.pdf","sourcePage":14},{"front":"make the schism confusing","meaning":"令分裂變得非常混亂","examples":[{"en":"The creation of Novial made the schism all too confusing.","zh":"諾維亞語的創造令分裂變得非常混亂。"},{"en":"To make the schism confusing means to make a split between groups harder to understand.","zh":"“Make the schism confusing” 指令群體之間的分裂更難理解。"},{"en":"A club split becomes confusing if a third group forms with almost the same goals.","zh":"如果第三個目標幾乎相同的小組成立，社團分裂就會變得混亂。"},{"en":"If each reform group creates a new language, supporters may not know which one to follow.","zh":"如果每個改革群體都創造新語言，支持者可能不知道應跟隨哪一個。"},{"en":"The phrase describes added confusion in an already divided movement.","zh":"這個短語描述已分裂運動中的額外混亂。"}],"source":"87 - Esperanto.pdf","sourcePage":14},{"front":"all too confusing","meaning":"非常令人混亂","examples":[{"en":"The split among artificial languages became all too confusing.","zh":"人工語言之間的分裂變得非常令人混亂。"},{"en":"All too confusing means extremely confusing, often more confusing than expected or acceptable.","zh":"“All too confusing” 指極其令人困惑，通常比預期或可接受程度更混亂。"},{"en":"The timetable became all too confusing when three versions were sent to parents.","zh":"當三個版本的時間表發給家長，時間表變得非常令人混亂。"},{"en":"If a movement has too many similar alternatives, its message can become all too confusing.","zh":"如果一場運動有太多相似替代方案，其信息可能變得非常令人混亂。"},{"en":"The phrase emphasises excessive confusion.","zh":"這個短語強調過度混亂。"}],"source":"87 - Esperanto.pdf","sourcePage":14},{"front":"the original Esperanto","meaning":"原本的世界語","examples":[{"en":"The original Esperanto quickly became the predominant language of its type.","zh":"原本的世界語很快成為同類之中的主導語言。"},{"en":"The original Esperanto means the first version of Esperanto before later rival reforms.","zh":"原本的世界語指後來競爭性改革版本出現前的最初版本世界語。"},{"en":"A teacher may compare the original textbook with a revised version to show what changed.","zh":"老師可能比較原本教科書與修訂版本，以顯示有甚麼改變。"},{"en":"If the original Esperanto survived rivals, it kept stronger support than the reformed versions.","zh":"如果原本的世界語在競爭語言中生存下來，它就比改革版本保留更強支持。"},{"en":"The phrase contrasts the first version with later alternatives.","zh":"這個短語把最初版本與後來替代品作對比。"}],"source":"87 - Esperanto.pdf","sourcePage":15},{"front":"predominant language","meaning":"主導語言","examples":[{"en":"Esperanto became the predominant language of its type.","zh":"世界語成為同類中的主導語言。"},{"en":"A predominant language is the language that is strongest, most common or most influential in a group.","zh":"主導語言是在某群體中最強、最常見或最有影響力的語言。"},{"en":"English is the predominant language in many international business meetings.","zh":"英語在許多國際商業會議中是主導語言。"},{"en":"If Esperanto is predominant among artificial languages, rival planned languages have smaller communities.","zh":"如果世界語在人造語言中佔主導地位，競爭人造語言的社群就較小。"},{"en":"The phrase describes leading position within a category.","zh":"這個短語描述某類別中的領先位置。"}],"source":"87 - Esperanto.pdf","sourcePage":15},{"front":"of its type","meaning":"同類之中","examples":[{"en":"Esperanto became the leading language of its type.","zh":"世界語成為同類之中的領先語言。"},{"en":"Of its type means among things in the same category.","zh":"“Of its type” 指在同一類別的事物之中。"},{"en":"This small camera is expensive, but it is one of the best of its type.","zh":"這部小型相機很貴，但它是同類之中最好的之一。"},{"en":"If Esperanto leads languages of its type, it leads constructed auxiliary languages, not all languages.","zh":"如果世界語在同類語言中領先，它是在人工輔助語言中領先，而不是所有語言。"},{"en":"The phrase limits the comparison to a specific group.","zh":"這個短語把比較限制在特定群體中。"}],"source":"87 - Esperanto.pdf","sourcePage":15},{"front":"lead the field","meaning":"在該領域領先","examples":[{"en":"Esperanto may lead the field among artificial languages.","zh":"世界語可能在人造語言領域領先。"},{"en":"To lead the field means to be the most successful or important in a particular area.","zh":"“Lead the field” 指在某特定範疇中最成功或最重要。"},{"en":"A university may lead the field in medical research if its discoveries shape global practice.","zh":"如果一所大學的發現塑造全球實踐，它可能在醫學研究領域領先。"},{"en":"If Esperanto leads the field, it has more influence than other constructed languages.","zh":"如果世界語在該領域領先，它就比其他人造語言更有影響力。"},{"en":"The phrase describes being ahead of competitors.","zh":"這個短語描述領先競爭者。"}],"source":"87 - Esperanto.pdf","sourcePage":15},{"front":"fall far short of","meaning":"遠未達到","examples":[{"en":"Esperanto falls far short of its creator’s aim.","zh":"世界語遠未達到其創造者的目標。"},{"en":"To fall far short of something means to fail to reach a goal by a large amount.","zh":"“Fall far short of” 某事指大幅未能達到目標。"},{"en":"A project may fall far short of expectations if only ten people join instead of hundreds.","zh":"如果本應有數百人參加的項目只有十人參加，它可能遠未達到期望。"},{"en":"If Esperanto was meant to become universal but remains small, it falls far short of the aim.","zh":"如果世界語本應成為全球通用語卻仍然小眾，它就遠未達到目標。"},{"en":"The phrase stresses a large gap between goal and result.","zh":"這個短語強調目標與結果之間的巨大差距。"}],"source":"87 - Esperanto.pdf","sourcePage":15},{"front":"aim","meaning":"目標","examples":[{"en":"Esperanto has not achieved the aim of becoming a global second language.","zh":"世界語尚未達成成為全球第二語言的目標。"},{"en":"An aim is a goal or purpose that someone wants to achieve.","zh":"目標是某人想達成的目的或方向。"},{"en":"The aim of a reading class may be to help students understand difficult passages faster.","zh":"閱讀課的目標可能是幫助學生更快理解困難文章。"},{"en":"If a project lacks a clear aim, people may not know what success looks like.","zh":"如果項目缺乏清晰目標，人們可能不知道成功是甚麼樣子。"},{"en":"The word focuses on intended purpose.","zh":"這個詞強調預期目的。"}],"source":"87 - Esperanto.pdf","sourcePage":15},{"front":"creator","meaning":"創造者","examples":[{"en":"Zamenhof was the creator of Esperanto.","zh":"Zamenhof 是世界語的創造者。"},{"en":"A creator is the person who makes or designs something new.","zh":"創造者是製作或設計新事物的人。"},{"en":"The creator of an educational game must think about both fun and learning.","zh":"教育遊戲的創造者必須同時考慮趣味和學習。"},{"en":"If a creator has a strong social vision, the invention may carry moral meaning.","zh":"如果創造者有強烈社會願景，該發明可能帶有道德意義。"},{"en":"The word identifies the person behind a creation.","zh":"這個詞指出創造物背後的人。"}],"source":"87 - Esperanto.pdf","sourcePage":15},{"front":"truly global second language","meaning":"真正全球通用的第二語言","examples":[{"en":"Esperanto has not become a truly global second language.","zh":"世界語尚未成為真正全球通用的第二語言。"},{"en":"A truly global second language would be widely learned and used by people across the world after their mother tongue.","zh":"真正全球通用的第二語言，是世界各地的人在母語之外廣泛學習和使用的語言。"},{"en":"A language used only by a small community cannot easily be called truly global.","zh":"只由小社群使用的語言，不容易被稱為真正全球通用。"},{"en":"If Esperanto lacks official support and mass use, it has not reached that global role.","zh":"如果世界語缺乏官方支援和大量使用，它就未達到那個全球角色。"},{"en":"The phrase describes worldwide practical use, not just international ideals.","zh":"這個短語描述全球實際使用，而不只是國際理想。"}],"source":"87 - Esperanto.pdf","sourcePage":15},{"front":"unite all in mutual understanding","meaning":"讓所有人在相互理解中團結起來","examples":[{"en":"Zamenhof hoped Esperanto would unite all in mutual understanding.","zh":"Zamenhof 希望世界語能讓所有人在相互理解中團結起來。"},{"en":"To unite all in mutual understanding means to bring people together through shared comprehension and respect.","zh":"“Unite all in mutual understanding” 指透過共同理解和尊重把人們連結起來。"},{"en":"A school exchange programme can unite students in mutual understanding when they listen to one another’s lives.","zh":"當學生聆聽彼此生活時，學校交流計劃可以讓學生在相互理解中團結起來。"},{"en":"If a shared language reduces suspicion, it may help communities understand one another better.","zh":"如果共同語言減少猜疑，它可能幫助社群更好地互相理解。"},{"en":"The phrase expresses a peaceful and idealistic goal.","zh":"這個短語表達和平而理想主義的目標。"}],"source":"87 - Esperanto.pdf","sourcePage":15},{"front":"commitment to","meaning":"對……的投入","examples":[{"en":"Commitment to the original goal has mellowed among many followers.","zh":"許多支持者對原本目標的投入已變得溫和。"},{"en":"Commitment to something is strong dedication or loyalty to it.","zh":"對某事的投入是對它的強烈奉獻或忠誠。"},{"en":"A teacher’s commitment to students can be seen in careful feedback and extra support.","zh":"老師對學生的投入可以從仔細回饋和額外支援中看見。"},{"en":"If commitment to a goal weakens, people may still enjoy the activity but stop pursuing the dream seriously.","zh":"如果對某目標的投入減弱，人們可能仍享受活動，但不再認真追求夢想。"},{"en":"The phrase describes emotional and practical dedication.","zh":"這個短語描述情感和實際上的奉獻。"}],"source":"87 - Esperanto.pdf","sourcePage":15},{"front":"high-minded goal","meaning":"崇高目標","examples":[{"en":"The early Esperantists shared a high-minded goal.","zh":"早期世界語者共有一個崇高目標。"},{"en":"A high-minded goal is a noble aim based on moral values rather than selfish interest.","zh":"崇高目標是基於道德價值，而不是私利的高尚目的。"},{"en":"A charity may have the high-minded goal of providing free education for every child.","zh":"慈善機構可能有為每個孩子提供免費教育的崇高目標。"},{"en":"If supporters share a high-minded goal, they may work hard despite limited rewards.","zh":"如果支持者共有崇高目標，即使回報有限，他們也可能努力工作。"},{"en":"The phrase suggests idealism and moral seriousness.","zh":"這個短語暗示理想主義和道德嚴肅性。"}],"source":"87 - Esperanto.pdf","sourcePage":15},{"front":"almost universally shared","meaning":"幾乎人人共有的","examples":[{"en":"The goal was almost universally shared in the early days.","zh":"在早期，這個目標幾乎人人共有。"},{"en":"Almost universally shared means accepted by nearly everyone in a group.","zh":"“Almost universally shared” 指幾乎被群體中所有人接受。"},{"en":"In a class, the wish for fair marking may be almost universally shared.","zh":"在班中，對公平評分的願望可能幾乎人人共有。"},{"en":"If a goal is almost universally shared, disagreement is rare at that stage.","zh":"如果一個目標幾乎人人共有，該階段分歧很少。"},{"en":"The phrase shows very broad agreement, though not absolute unanimity.","zh":"這個短語顯示非常廣泛的一致，但不是絕對全體一致。"}],"source":"87 - Esperanto.pdf","sourcePage":16},{"front":"in the early days","meaning":"在早期","examples":[{"en":"Esperanto supporters were more idealistic in the early days.","zh":"世界語支持者在早期更加理想主義。"},{"en":"In the early days means during the first period after something began.","zh":"“In the early days” 指某事開始後的最初時期。"},{"en":"In the early days of a business, the owner may do every job alone.","zh":"在生意早期，老闆可能獨自做每一項工作。"},{"en":"If a movement is young, supporters in the early days often have strong hopes.","zh":"如果運動仍年輕，早期支持者通常抱有強烈希望。"},{"en":"The phrase contrasts the beginning with later development.","zh":"這個短語把開始階段與後來發展作對比。"}],"source":"87 - Esperanto.pdf","sourcePage":16},{"front":"mellow among","meaning":"在……之中變得溫和","examples":[{"en":"The commitment has mellowed among many followers.","zh":"這份投入在許多支持者之中變得溫和。"},{"en":"To mellow among a group means to become softer, calmer or less intense within that group.","zh":"“Mellow among” 某群體指在該群體中變得較柔和、平靜或不那麼強烈。"},{"en":"Anger about a school rule may mellow among students after the rule is explained clearly.","zh":"當校規得到清楚解釋後，學生對它的憤怒可能變得溫和。"},{"en":"If commitment mellows, supporters may still care but no longer push as strongly.","zh":"如果投入變得溫和，支持者可能仍然在意，但不再那麼強烈推動。"},{"en":"The phrase describes emotional intensity becoming gentler.","zh":"這個短語描述情緒強度變得較柔和。"}],"source":"87 - Esperanto.pdf","sourcePage":16},{"front":"followers","meaning":"追隨者；支持者","examples":[{"en":"Many followers now enjoy Esperanto as a special culture.","zh":"許多支持者現在把世界語作為一種特殊文化來享受。"},{"en":"Followers are people who support, join or continue a movement, leader or idea.","zh":"追隨者是支持、加入或延續某運動、領袖或想法的人。"},{"en":"A popular teacher may have followers who use her study method for years.","zh":"受歡迎老師可能有多年使用其學習方法的追隨者。"},{"en":"If followers keep meeting and learning, a movement can survive even when its original goal changes.","zh":"如果支持者持續見面和學習，即使原本目標改變，運動仍能生存。"},{"en":"The word describes supporters who remain connected to a cause.","zh":"這個詞描述仍與某事業相連的支持者。"}],"source":"87 - Esperanto.pdf","sourcePage":16},{"front":"be content simply to","meaning":"只滿足於……","examples":[{"en":"Many followers are content simply to participate in the community.","zh":"許多支持者只滿足於參與該社群。"},{"en":"To be content simply to do something means to be satisfied with doing only that thing.","zh":"“Be content simply to” 做某事指只做該事已感到滿足。"},{"en":"Some club members are content simply to meet friends rather than win competitions.","zh":"一些社團成員只滿足於見朋友，而不是贏比賽。"},{"en":"If Esperantists are content simply to enjoy the culture, they may no longer expect global victory.","zh":"如果世界語者只滿足於享受其文化，他們可能不再期望全球勝利。"},{"en":"The phrase shows modest satisfaction.","zh":"這個短語顯示較低調的滿足。"}],"source":"87 - Esperanto.pdf","sourcePage":16},{"front":"linguistic culture and community","meaning":"語言文化和社群","examples":[{"en":"Esperanto now supports a special linguistic culture and community.","zh":"世界語現在支撐一種特殊的語言文化和社群。"},{"en":"Linguistic culture and community means the shared habits, values and relationships built around a language.","zh":"語言文化和社群是圍繞一種語言建立的共同習慣、價值和關係。"},{"en":"A local dialect can create linguistic culture through jokes, songs and family expressions.","zh":"本地方言可以透過笑話、歌曲和家庭表達創造語言文化。"},{"en":"If Esperanto users share books, meetings and traditions, they form more than a language class.","zh":"如果世界語使用者共享書籍、聚會和傳統，他們形成的不只是語言班。"},{"en":"The phrase connects language with social life.","zh":"這個短語把語言與社交生活連繫起來。"}],"source":"87 - Esperanto.pdf","sourcePage":16},{"front":"unlikelihood of","meaning":"……不大可能","examples":[{"en":"The unlikelihood of global success was admitted at a convention.","zh":"世界語不大可能取得全球成功一事在大會上被承認。"},{"en":"The unlikelihood of something means the low chance that it will happen.","zh":"“The unlikelihood of” 某事指它發生的機會很低。"},{"en":"The unlikelihood of finishing a huge project in one day should make the team plan realistically.","zh":"一天內完成大型項目不大可能，這應令團隊現實地規劃。"},{"en":"If supporters admit the unlikelihood of worldwide success, they may adjust their goals.","zh":"如果支持者承認全球成功不大可能，他們可能調整目標。"},{"en":"The phrase focuses on low probability.","zh":"這個短語強調低可能性。"}],"source":"87 - Esperanto.pdf","sourcePage":16},{"front":"achieve more than this","meaning":"達成比這更多的事","examples":[{"en":"Some Esperantists admit that the movement may not achieve more than this.","zh":"一些世界語者承認該運動可能無法達成比這更多的事。"},{"en":"To achieve more than this means to succeed beyond the current level or result.","zh":"“Achieve more than this” 指取得超過目前水平或結果的成功。"},{"en":"A small club may not achieve more than regular meetings if it lacks funding.","zh":"如果缺乏資金，小社團可能無法達成比定期聚會更多的事。"},{"en":"If Esperanto mainly remains a community culture, it may not achieve worldwide official use.","zh":"如果世界語主要仍是社群文化，它可能無法達成全球官方使用。"},{"en":"The phrase compares present success with greater ambitions.","zh":"這個短語比較目前成功與更大抱負。"}],"source":"87 - Esperanto.pdf","sourcePage":16},{"front":"admit","meaning":"承認","examples":[{"en":"The unlikelihood of wider success was admitted at a convention.","zh":"更廣泛成功不大可能一事在大會上被承認。"},{"en":"To admit something means to accept or state that it is true, often reluctantly.","zh":"“Admit” 某事指接受或說出它是真的，通常帶有不情願。"},{"en":"A student may admit that they did not revise enough after a poor test result.","zh":"學生可能在測驗成績差後承認自己溫習不足。"},{"en":"If supporters admit a weakness, they may become more realistic about their goal.","zh":"如果支持者承認弱點，他們可能對目標變得更現實。"},{"en":"The word shows acknowledgement rather than denial.","zh":"這個詞顯示承認，而不是否認。"}],"source":"87 - Esperanto.pdf","sourcePage":16},{"front":"convention","meaning":"大會；會議","examples":[{"en":"An Esperanto convention in 1980 discussed the movement’s limits.","zh":"1980年的世界語大會討論了該運動的限制。"},{"en":"A convention is a formal meeting where people with a shared interest gather and discuss issues.","zh":"大會是有共同興趣的人聚集並討論議題的正式會議。"},{"en":"Teachers may attend an education convention to learn new classroom methods.","zh":"老師可能參加教育大會，學習新的課堂方法。"},{"en":"If a language movement holds a convention, members can debate goals and problems together.","zh":"如果語言運動舉行大會，成員可以一起辯論目標和問題。"},{"en":"The word refers to an organised gathering, not a casual meeting.","zh":"這個詞指有組織的聚會，而不是隨意會面。"}],"source":"87 - Esperanto.pdf","sourcePage":16},{"front":"cling to","meaning":"堅持；緊抱不放","examples":[{"en":"Many Esperantists still cling to the original goal.","zh":"許多世界語者仍然堅持原本目標。"},{"en":"To cling to something means to hold onto it strongly and refuse to let it go.","zh":"“Cling to” 某事指緊緊抓住它並拒絕放手。"},{"en":"A student may cling to an old study method even when it no longer works.","zh":"學生可能堅持舊溫習方法，即使它已不再有效。"},{"en":"If supporters cling to an original dream, they may resist more modest goals.","zh":"如果支持者堅持原本夢想，可能抗拒較溫和目標。"},{"en":"The phrase suggests emotional attachment and persistence.","zh":"這個短語暗示情感依附和持續堅持。"}],"source":"87 - Esperanto.pdf","sourcePage":16},{"front":"pracelo","meaning":"原初目標","examples":[{"en":"The word pracelo refers to the original goal of Esperanto.","zh":"“Pracelo” 這個詞指世界語的原初目標。"},{"en":"Pracelo is an Esperanto term meaning the original or primary goal.","zh":"“Pracelo” 是世界語詞語，意思是原本或首要目標。"},{"en":"In a club, members may speak about the pracelo when they discuss why the club was founded.","zh":"在社團中，成員討論社團成立原因時，可能談到其原初目標。"},{"en":"If Esperantists cling to the pracelo, they still hope for worldwide use and official status.","zh":"如果世界語者堅持 pracelo，他們仍希望世界語得到全球使用和官方地位。"},{"en":"The word names the movement’s founding aim.","zh":"這個詞指出該運動的創立目標。"}],"source":"87 - Esperanto.pdf","sourcePage":17},{"front":"original goal","meaning":"原本目標","examples":[{"en":"Some supporters still cling to the original goal.","zh":"一些支持者仍然堅持原本目標。"},{"en":"An original goal is the first aim that guided a project or movement when it began.","zh":"原本目標是一個項目或運動開始時指引它的最初目的。"},{"en":"A school club’s original goal may be to help younger students enjoy reading.","zh":"學校社團的原本目標可能是幫助低年級學生享受閱讀。"},{"en":"If a movement changes over time, some members may still remember the original goal.","zh":"如果運動隨時間改變，一些成員可能仍記得原本目標。"},{"en":"The phrase contrasts the first aim with later, more modest aims.","zh":"這個短語把最初目標與後來較溫和目標作對比。"}],"source":"87 - Esperanto.pdf","sourcePage":17},{"front":"official status","meaning":"官方地位","examples":[{"en":"Many Esperantists still hope for official status.","zh":"許多世界語者仍然希望取得官方地位。"},{"en":"Official status means formal recognition by an authority, government or institution.","zh":"官方地位是由權威、政府或機構作出的正式承認。"},{"en":"A language with official status may be used in courts, schools or public documents.","zh":"擁有官方地位的語言可能用於法院、學校或公共文件。"},{"en":"If Esperanto gained official status, it would have more institutional support.","zh":"如果世界語取得官方地位，它會有更多制度支援。"},{"en":"The phrase refers to formal recognition, not only popularity.","zh":"這個短語指正式承認，而不只是受歡迎。"}],"source":"87 - Esperanto.pdf","sourcePage":17},{"front":"worldwide use","meaning":"全球使用","examples":[{"en":"The original goal included worldwide use of Esperanto.","zh":"原本目標包括世界語的全球使用。"},{"en":"Worldwide use means use across many countries and regions around the world.","zh":"全球使用指在世界許多國家和地區使用。"},{"en":"A payment app has worldwide use if travellers can pay with it in many countries.","zh":"如果旅客在許多國家都能用某付款應用程式付款，它就達到全球使用。"},{"en":"If Esperanto achieved worldwide use, people everywhere would learn it as a common second language.","zh":"如果世界語達成全球使用，世界各地的人都會把它學作共同第二語言。"},{"en":"The phrase describes broad global adoption.","zh":"這個短語描述廣泛全球採用。"}],"source":"87 - Esperanto.pdf","sourcePage":17},{"front":"Will this ever be achieved?","meaning":"這會否有一天實現？","examples":[{"en":"The writer asks whether worldwide use will ever be achieved.","zh":"作者問全球使用會否有一天實現。"},{"en":"“Will this ever be achieved?” asks whether a goal will happen at any time in the future.","zh":"“Will this ever be achieved?” 是問某目標是否會在未來任何時間發生。"},{"en":"A student may ask whether perfect pronunciation will ever be achieved after years of practice.","zh":"學生練習多年後，可能問完美發音會否有一天實現。"},{"en":"If a goal has remained distant for decades, people may doubt whether it will ever happen.","zh":"如果目標數十年來仍然遙遠，人們可能懷疑它是否有一天會發生。"},{"en":"The question expresses uncertainty about future success.","zh":"這個問題表達對未來成功的不確定。"}],"source":"87 - Esperanto.pdf","sourcePage":17},{"front":"estus agrable pensi tiel","meaning":"這樣想會令人高興","examples":[{"en":"The phrase “estus agrable pensi tiel” means it would be nice to think so.","zh":"“Estus agrable pensi tiel” 的意思是「這樣想會令人高興」。"},{"en":"“Estus agrable pensi tiel” is an Esperanto expression suggesting that a hopeful idea would be pleasant, even if unlikely.","zh":"“Estus agrable pensi tiel” 是世界語表達，暗示某個充滿希望的想法令人愉快，即使不大可能。"},{"en":"A supporter might say “it would be nice to think so” when asked whether a dream will come true.","zh":"當被問及夢想是否會成真，支持者可能說「這樣想會令人高興」。"},{"en":"If the writer uses this phrase, the tone is gentle but sceptical.","zh":"如果作者使用這個短語，語氣是溫和但懷疑的。"},{"en":"The phrase closes the discussion with a hopeful feeling and a doubtful judgement.","zh":"這個短語以希望感和懷疑判斷結束討論。"}],"source":"87 - Esperanto.pdf","sourcePage":17},{"front":"almost certainly not","meaning":"幾乎肯定不會","examples":[{"en":"The writer believes Esperanto will almost certainly not become universal.","zh":"作者認為世界語幾乎肯定不會變成全球通用。"},{"en":"Almost certainly not means very probably not, with only a small possibility remaining.","zh":"“Almost certainly not” 指很可能不會，只剩很小可能性。"},{"en":"If a student has not studied all term, they will almost certainly not pass with top marks.","zh":"如果學生整個學期都沒有溫習，他幾乎肯定不會以最高分通過。"},{"en":"If Esperanto has not become universal after many decades, the writer sees future success as very unlikely.","zh":"如果世界語多年後仍未全球通用，作者就認為未來成功非常不可能。"},{"en":"The phrase expresses strong doubt.","zh":"這個短語表達強烈懷疑。"}],"source":"87 - Esperanto.pdf","sourcePage":17},{"front":"write TRUE, FALSE, or NOT GIVEN","meaning":"寫上 TRUE、FALSE 或 NOT GIVEN","examples":[{"en":"Students must write TRUE, FALSE, or NOT GIVEN.","zh":"學生必須寫上 TRUE、FALSE 或 NOT GIVEN。"},{"en":"Write TRUE, FALSE, or NOT GIVEN means decide whether a statement matches, contradicts, or is not covered by the passage.","zh":"“Write TRUE, FALSE, or NOT GIVEN” 指判斷陳述是否與文章一致、相矛盾或沒有提及。"},{"en":"In a reading test, students should use the text only when writing TRUE, FALSE, or NOT GIVEN.","zh":"在閱讀測驗中，學生寫 TRUE、FALSE 或 NOT GIVEN 時應只使用文本。"},{"en":"If the passage gives no evidence for a statement, the answer should not be guessed from common knowledge.","zh":"如果文章沒有為陳述提供證據，答案不應從常識猜測。"},{"en":"The phrase is a standard IELTS-style instruction.","zh":"這個短語是 IELTS 類標準指示。"}],"source":"87 - Esperanto.pdf","sourcePage":17},{"front":"agree with the information","meaning":"與資料一致","examples":[{"en":"A TRUE statement agrees with the information in the passage.","zh":"TRUE 陳述與文章資料一致。"},{"en":"To agree with the information means to match what the text says.","zh":"“Agree with the information” 指與文本所說內容相符。"},{"en":"If a passage says a book was published in 1887, that same statement agrees with the information.","zh":"如果文章說一本書於1887年出版，相同陳述就與資料一致。"},{"en":"If one word changes the meaning, the statement may no longer agree with the passage.","zh":"如果一個詞改變意思，該陳述可能不再與文章一致。"},{"en":"The phrase is used in TRUE/FALSE/NOT GIVEN questions.","zh":"這個短語用於 TRUE/FALSE/NOT GIVEN 題。"}],"source":"87 - Esperanto.pdf","sourcePage":17},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A FALSE statement contradicts the information in the passage.","zh":"FALSE 陳述與文章資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"“Contradict the information” 指說出與文本內容相反的意思。"},{"en":"If the passage says Esperanto has no official status, a statement saying it is official in many states contradicts it.","zh":"如果文章說世界語沒有官方地位，而陳述說它在許多國家是官方語言，就與資料相矛盾。"},{"en":"A statement can be false even if only one key detail is opposite to the passage.","zh":"即使只有一個關鍵細節與文章相反，陳述也可能是 FALSE。"},{"en":"The phrase helps students identify FALSE answers.","zh":"這個短語幫助學生識別 FALSE 答案。"}],"source":"87 - Esperanto.pdf","sourcePage":17},{"front":"no information on this","meaning":"沒有這方面的資料","examples":[{"en":"Write NOT GIVEN if there is no information on this.","zh":"如果沒有這方面的資料，就寫 NOT GIVEN。"},{"en":"No information on this means the passage does not say whether the statement is true or false.","zh":"“No information on this” 指文章沒有說明該陳述是真還是假。"},{"en":"If the text discusses Zamenhof’s town but not his favourite food, there is no information on that point.","zh":"如果文本討論 Zamenhof 的城鎮，但沒有提到他最喜歡的食物，這方面就沒有資料。"},{"en":"Students should not use outside knowledge when the passage gives no information.","zh":"當文章沒有資料時，學生不應使用外部知識。"},{"en":"The phrase signals a NOT GIVEN situation.","zh":"這個短語表示 NOT GIVEN 情況。"}],"source":"87 - Esperanto.pdf","sourcePage":17},{"front":"the number of Esperanto speakers","meaning":"世界語使用者人數","examples":[{"en":"The number of Esperanto speakers is difficult to estimate.","zh":"世界語使用者人數難以估計。"},{"en":"The number of Esperanto speakers means how many people can speak or understand Esperanto.","zh":"世界語使用者人數指有多少人能說或理解世界語。"},{"en":"A survey may try to count the number of language learners in a country.","zh":"調查可能嘗試計算一個國家的語言學習者人數。"},{"en":"If definitions of “speaker” differ, the number of Esperanto speakers can vary widely.","zh":"如果「使用者」定義不同，世界語使用者人數可能差異很大。"},{"en":"The phrase focuses on estimated users of the language.","zh":"這個短語強調該語言使用者的估計數量。"}],"source":"87 - Esperanto.pdf","sourcePage":18},{"front":"quite large","meaning":"相當多","examples":[{"en":"The statement claims that the number of Esperanto speakers is quite large.","zh":"該陳述聲稱世界語使用者人數相當多。"},{"en":"Quite large means fairly big in size, amount or number.","zh":"“Quite large” 指在大小、數量或數目上相當大。"},{"en":"A class of forty students is quite large for a speaking lesson.","zh":"對口語課來說，四十人的班級相當大。"},{"en":"If the number is quite large compared with one group but small compared with another, context matters.","zh":"如果數字相對某群體很大，但相對另一群體很小，語境就很重要。"},{"en":"The phrase is relative and depends on comparison.","zh":"這個短語是相對的，取決於比較。"}],"source":"87 - Esperanto.pdf","sourcePage":18},{"front":"spoke many languages","meaning":"會說很多種語言","examples":[{"en":"The question asks whether Zamenhof spoke many languages.","zh":"題目問 Zamenhof 是否會說很多種語言。"},{"en":"Spoke many languages means was able to use several languages in speech or communication.","zh":"“Spoke many languages” 指能夠用幾種語言說話或溝通。"},{"en":"A tour guide who speaks many languages can help visitors from different countries.","zh":"會說很多種語言的導遊可以幫助來自不同國家的旅客。"},{"en":"If Zamenhof grew up in a multilingual town, readers may wonder whether he spoke many languages himself.","zh":"如果 Zamenhof 在多語城鎮長大，讀者可能想知道他本人是否會說很多種語言。"},{"en":"The phrase focuses on language ability.","zh":"這個短語強調語言能力。"}],"source":"87 - Esperanto.pdf","sourcePage":18},{"front":"easier to learn than","meaning":"比……更容易學習","examples":[{"en":"Esperanto is said to be easier to learn than other languages.","zh":"世界語據說比其他語言更容易學習。"},{"en":"Easier to learn than means requiring less time, effort or difficulty than another thing.","zh":"“Easier to learn than” 指比另一事物需要較少時間、努力或困難。"},{"en":"A song with repeated lines may be easier to learn than a long poem.","zh":"有重複句子的歌曲可能比長詩更容易學習。"},{"en":"If Esperanto has regular rules, it may be easier to learn than languages with many irregular forms.","zh":"如果世界語有規則文法，它可能比有許多不規則形式的語言更容易學習。"},{"en":"The phrase compares learning difficulty.","zh":"這個短語比較學習難度。"}],"source":"87 - Esperanto.pdf","sourcePage":18},{"front":"World Congresses","meaning":"世界大會","examples":[{"en":"Esperanto World Congresses began in France in 1905.","zh":"世界語世界大會於1905年在法國開始。"},{"en":"World Congresses are large international meetings held for members of a movement or field.","zh":"世界大會是為某運動或領域成員舉行的大型國際會議。"},{"en":"A professional association may organise World Congresses for doctors or teachers.","zh":"專業協會可能為醫生或教師組織世界大會。"},{"en":"If Esperanto holds World Congresses, speakers have formal opportunities to meet and use the language.","zh":"如果世界語舉行世界大會，使用者就有正式機會見面和使用該語言。"},{"en":"The phrase refers to repeated global gatherings.","zh":"這個短語指反覆舉行的全球聚會。"}],"source":"87 - Esperanto.pdf","sourcePage":18},{"front":"complete the sentences","meaning":"完成句子","examples":[{"en":"Students must complete the sentences using words from the passage.","zh":"學生必須使用文章中的詞語完成句子。"},{"en":"Complete the sentences means fill in missing words so the sentences become whole and correct.","zh":"“Complete the sentences” 指填入缺漏詞語，使句子完整且正確。"},{"en":"In reading exams, students should check grammar before completing the sentences.","zh":"在閱讀考試中，學生完成句子前應檢查文法。"},{"en":"If the answer limit is two words, students must not copy a longer phrase.","zh":"如果答案限制是兩個詞，學生不得抄寫更長短語。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"87 - Esperanto.pdf","sourcePage":18},{"front":"no more than two words","meaning":"不超過兩個詞","examples":[{"en":"The answers must use no more than two words from the passage.","zh":"答案必須使用文章中不超過兩個詞。"},{"en":"No more than two words means the answer must contain two words or fewer.","zh":"“No more than two words” 指答案必須包含兩個詞或更少。"},{"en":"If the answer is “state funds,” it follows the no-more-than-two-words rule.","zh":"如果答案是 “state funds”，它符合不超過兩個詞的規則。"},{"en":"Students may lose marks if they write three words even when the meaning is correct.","zh":"即使意思正確，如果學生寫三個詞，也可能失分。"},{"en":"The phrase gives a strict word limit.","zh":"這個短語給出嚴格字數限制。"}],"source":"87 - Esperanto.pdf","sourcePage":18},{"front":"ethnic groups","meaning":"族裔群體","examples":[{"en":"Different ethnic groups lived in Zamenhof’s hometown.","zh":"不同族裔群體住在 Zamenhof 的家鄉。"},{"en":"Ethnic groups are communities of people who share ancestry, culture, language or history.","zh":"族裔群體是共享祖先、文化、語言或歷史的人群。"},{"en":"A city with many ethnic groups may have diverse food, festivals and languages.","zh":"有許多族裔群體的城市可能有多元食物、節日和語言。"},{"en":"If ethnic groups do not trust one another, social conflict may develop.","zh":"如果族裔群體互不信任，社會衝突可能出現。"},{"en":"The phrase describes group identity within a population.","zh":"這個短語描述人口中的群體身份。"}],"source":"87 - Esperanto.pdf","sourcePage":18},{"front":"hometown","meaning":"家鄉","examples":[{"en":"Zamenhof’s hometown was racially divided.","zh":"Zamenhof 的家鄉種族分化。"},{"en":"A hometown is the town or city where someone was born or grew up.","zh":"家鄉是某人出生或長大的城鎮或城市。"},{"en":"A student studying abroad may miss the food and streets of their hometown.","zh":"留學生可能想念家鄉的食物和街道。"},{"en":"If a person’s hometown is divided, that experience may shape their later beliefs.","zh":"如果一個人的家鄉分裂，這種經驗可能塑造其後來信念。"},{"en":"The word connects identity with early place.","zh":"這個詞把身份與早期地方連繫起來。"}],"source":"87 - Esperanto.pdf","sourcePage":18},{"front":"frequently hostile","meaning":"經常敵對","examples":[{"en":"The different groups in Zamenhof’s hometown were often hostile.","zh":"Zamenhof 家鄉中的不同群體經常敵對。"},{"en":"Frequently hostile means often unfriendly, tense or aggressive.","zh":"“Frequently hostile” 指經常不友善、緊張或具攻擊性。"},{"en":"Two sports teams may become frequently hostile if fans spread insults online.","zh":"如果球迷在網上互相侮辱，兩隊可能變得經常敵對。"},{"en":"If communities are frequently hostile, everyday communication becomes stressful.","zh":"如果社群經常敵對，日常溝通會變得有壓力。"},{"en":"The phrase describes repeated tension, not a single argument.","zh":"這個短語描述反覆緊張，而不是單一爭執。"}],"source":"87 - Esperanto.pdf","sourcePage":18},{"front":"first Esperanto speakers","meaning":"第一批世界語使用者","examples":[{"en":"The first Esperanto speakers shared Zamenhof’s idealism.","zh":"第一批世界語使用者與 Zamenhof 有共同理想。"},{"en":"First Esperanto speakers were the early people who learned and used Esperanto after it was created.","zh":"第一批世界語使用者，是世界語創造後早期學習和使用它的人。"},{"en":"Early members of a new language club may become the first regular speakers in a city.","zh":"新語言俱樂部的早期成員可能成為城市中第一批定期使用者。"},{"en":"If the first speakers shared an ideal, they helped build a movement, not just a language course.","zh":"如果第一批使用者共有理想，他們建立的是運動，而不只是語言課。"},{"en":"The phrase refers to the earliest user community.","zh":"這個短語指最早的使用者社群。"}],"source":"87 - Esperanto.pdf","sourcePage":18},{"front":"shared someone’s idealism","meaning":"與某人有共同理想","examples":[{"en":"The first Esperanto speakers shared Zamenhof’s idealism.","zh":"第一批世界語使用者與 Zamenhof 有共同理想。"},{"en":"To share someone’s idealism means to believe in the same hopeful vision as that person.","zh":"“Share someone’s idealism” 指相信與某人相同的希望願景。"},{"en":"Volunteers may share a founder’s idealism when they work for free community education.","zh":"義工為免費社區教育工作時，可能與創辦人有共同理想。"},{"en":"If learners shared Zamenhof’s idealism, they saw Esperanto as a tool for peace.","zh":"如果學習者與 Zamenhof 有共同理想，他們就把世界語視為和平工具。"},{"en":"The phrase describes a common belief in a better future.","zh":"這個短語描述對更好未來的共同信念。"}],"source":"87 - Esperanto.pdf","sourcePage":19},{"front":"essentially provides","meaning":"基本上提供","examples":[{"en":"English now essentially provides the means of international communication.","zh":"英語現在基本上提供了國際溝通的方式。"},{"en":"Essentially provides means in practical terms gives or supplies what is needed.","zh":"“Essentially provides” 指在實際上提供所需的東西。"},{"en":"A library essentially provides free access to books, study space and information.","zh":"圖書館基本上提供免費書籍、學習空間和資訊。"},{"en":"If English essentially provides global communication, another planned language may seem less necessary.","zh":"如果英語基本上提供全球溝通，另一種人造語言可能顯得較不必要。"},{"en":"The phrase focuses on practical function rather than official theory.","zh":"這個短語強調實際功能，而不是官方理論。"}],"source":"87 - Esperanto.pdf","sourcePage":19},{"front":"means of international communication","meaning":"國際溝通的方式","examples":[{"en":"English now provides the means of international communication.","zh":"英語現在提供國際溝通的方式。"},{"en":"Means of international communication are tools or languages used for communication across countries.","zh":"國際溝通的方式，是用於跨國溝通的工具或語言。"},{"en":"Translation apps, interpreters and shared languages can be means of international communication.","zh":"翻譯應用程式、傳譯員和共同語言都可以是國際溝通的方式。"},{"en":"If English provides this means, travellers and businesses often choose it first.","zh":"如果英語提供這種方式，旅客和企業通常首先選擇它。"},{"en":"The phrase describes how people communicate globally.","zh":"這個短語描述人們如何在全球溝通。"}],"source":"87 - Esperanto.pdf","sourcePage":19},{"front":"official support","meaning":"官方支持","examples":[{"en":"Official support of Esperanto may be considered a waste of money.","zh":"對世界語的官方支持可能被視為浪費金錢。"},{"en":"Official support is help, recognition or funding from a government or institution.","zh":"官方支持是來自政府或機構的幫助、承認或資金。"},{"en":"A minority language may survive better if it receives official support in schools.","zh":"如果少數語言在學校得到官方支持，可能更容易生存。"},{"en":"If official support costs public money, critics may ask whether the benefit is large enough.","zh":"如果官方支持需要公共金錢，批評者可能問好處是否足夠大。"},{"en":"The phrase refers to institutional backing.","zh":"這個短語指制度性支持。"}],"source":"87 - Esperanto.pdf","sourcePage":19},{"front":"be considered a waste of","meaning":"被視為浪費……","examples":[{"en":"Official support of Esperanto could be considered a waste of state funds.","zh":"對世界語的官方支持可能被視為浪費政府資金。"},{"en":"To be considered a waste of something means to be judged as using that resource badly.","zh":"“Be considered a waste of” 某資源指被判斷為不善用該資源。"},{"en":"Buying equipment that nobody uses may be considered a waste of school money.","zh":"購買沒有人使用的設備可能被視為浪費學校金錢。"},{"en":"If Esperanto offers limited public benefit, funding it may be seen as a waste by critics.","zh":"如果世界語提供有限公共利益，批評者可能視資助它為浪費。"},{"en":"The phrase expresses a negative judgement about resource use.","zh":"這個短語表達對資源使用的負面判斷。"}],"source":"87 - Esperanto.pdf","sourcePage":19},{"front":"answer the questions","meaning":"回答問題","examples":[{"en":"Students must answer the questions using the correct letters.","zh":"學生必須使用正確字母回答問題。"},{"en":"Answer the questions means respond to the tasks or prompts given in the exercise.","zh":"“Answer the questions” 指回應練習中給出的任務或問題。"},{"en":"In reading exams, students should answer the questions using evidence from the passage.","zh":"在閱讀考試中，學生應使用文章證據回答問題。"},{"en":"If students misunderstand the instruction, they may answer in the wrong format.","zh":"如果學生誤解指示，可能以錯誤格式作答。"},{"en":"The phrase is a basic exam direction.","zh":"這個短語是基本考試指示。"}],"source":"87 - Esperanto.pdf","sourcePage":19},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter for each language.","zh":"學生為每種語言選出正確字母。"},{"en":"Choose the correct letter means select the answer option marked by the right letter.","zh":"“Choose the correct letter” 指選出由正確字母標示的答案選項。"},{"en":"In matching questions, students may need to choose A, B, C or D for each item.","zh":"在配對題中，學生可能需要為每項選擇 A、B、C 或 D。"},{"en":"If the correct idea is found but the wrong letter is written, the mark may be lost.","zh":"如果找到正確意思但寫錯字母，可能會失分。"},{"en":"The phrase is common in multiple-choice and matching tasks.","zh":"這個短語常見於選擇題和配對題。"}],"source":"87 - Esperanto.pdf","sourcePage":19},{"front":"had many stages in its development","meaning":"在發展過程中經歷多個階段","examples":[{"en":"Ido had many stages in its development.","zh":"伊多語在發展過程中經歷多個階段。"},{"en":"Had many stages in its development means changed through several steps before reaching a later form.","zh":"“Had many stages in its development” 指在達到後來形式前，經過幾個步驟改變。"},{"en":"A school project may have many stages in its development, from planning to testing to launch.","zh":"學校項目在發展過程中可能經歷多個階段，由規劃到測試再到推出。"},{"en":"If a language has many stages in development, its rules may change more than once.","zh":"如果一種語言在發展中有多個階段，其規則可能不止一次改變。"},{"en":"The phrase describes a process with repeated phases.","zh":"這個短語描述有反覆階段的過程。"}],"source":"87 - Esperanto.pdf","sourcePage":19},{"front":"have development affected by","meaning":"發展受到……影響","examples":[{"en":"Ido had its development affected by World War One.","zh":"伊多語的發展受到第一次世界大戰影響。"},{"en":"To have development affected by something means that progress or growth was changed by that event or factor.","zh":"“Have development affected by” 某事指進展或成長被該事件或因素改變。"},{"en":"A child’s learning development may be affected by long school closures.","zh":"兒童的學習發展可能受到長期停課影響。"},{"en":"If war affects a language movement, meetings, publications and travel may all be disrupted.","zh":"如果戰爭影響語言運動，會議、出版和旅行都可能被打亂。"},{"en":"The phrase connects external events with a process of growth.","zh":"這個短語把外部事件與成長過程連繫起來。"}],"source":"87 - Esperanto.pdf","sourcePage":19},{"front":"strange words","meaning":"奇怪的詞語","examples":[{"en":"Esperanto has some strange words chosen idiosyncratically.","zh":"世界語有一些以獨特方式選擇的奇怪詞語。"},{"en":"Strange words are words that seem unusual, unfamiliar or hard to explain.","zh":"奇怪的詞語是看起來不尋常、不熟悉或難以解釋的詞語。"},{"en":"A beginner may find legal English full of strange words at first.","zh":"初學者起初可能覺得法律英語充滿奇怪詞語。"},{"en":"If a language contains many strange words, learners may need more memory work.","zh":"如果一種語言包含許多奇怪詞語，學習者可能需要更多記憶工作。"},{"en":"The phrase describes words that do not feel ordinary to learners.","zh":"這個短語描述對學習者來說不普通的詞語。"}],"source":"87 - Esperanto.pdf","sourcePage":19},{"front":"be designed by many people","meaning":"由多人設計","examples":[{"en":"Ido was designed by many academics.","zh":"伊多語由多位學者設計。"},{"en":"To be designed by many people means to be planned and created by a group rather than one person.","zh":"“Be designed by many people” 指由一群人而不是一個人規劃和創造。"},{"en":"A new school curriculum may be designed by many teachers and advisers.","zh":"新學校課程可能由許多老師和顧問設計。"},{"en":"If a language is designed by many people, it may reflect compromise and committee decisions.","zh":"如果一種語言由多人設計，它可能反映妥協和委員會決定。"},{"en":"The phrase contrasts collective design with individual invention.","zh":"這個短語把集體設計與個人發明作對比。"}],"source":"87 - Esperanto.pdf","sourcePage":19},{"front":"never achieve its aim","meaning":"從未達成其目標","examples":[{"en":"Esperanto has never achieved its original aim.","zh":"世界語從未達成其原本目標。"},{"en":"To never achieve its aim means to fail permanently or so far to reach the goal it was created for.","zh":"“Never achieve its aim” 指永久或至今未能達到其被創造時的目標。"},{"en":"A project may never achieve its aim if it lacks users, funding and clear support.","zh":"如果項目缺乏使用者、資金和清晰支持，可能永遠無法達成目標。"},{"en":"If Esperanto was meant to be universal but remains marginal, critics say it has not achieved its aim.","zh":"如果世界語本意是全球通用卻仍然邊緣化，批評者會說它未達成其目標。"},{"en":"The phrase highlights failure to reach an intended goal.","zh":"這個短語強調未能達到原定目標。"}],"source":"87 - Esperanto.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 88":[{"front":"A Meat-Eater’s Counter","meaning":"肉食者的反駁","examples":[{"en":"The passage is written as a meat-eater’s counter to vegetarian arguments.","zh":"這篇文章是肉食者對素食論點的反駁。"},{"en":"A meat-eater’s counter is a reply or argument made by someone who defends eating meat.","zh":"a meat-eater’s counter 指由支持吃肉的人提出的回應或論點。"},{"en":"In a class debate, one student may present a meat-eater’s counter after others argue for vegetarianism.","zh":"在課堂辯論中，其他人支持素食後，一名學生可能提出肉食者的反駁。"},{"en":"A counter argument is used when a writer wants to challenge a view rather than simply describe it.","zh":"counter argument 用於作者想挑戰某看法，而不只是描述它。"},{"en":"This phrase shows that the passage takes a defensive position against vegetarian claims.","zh":"這個片語顯示文章採取防守立場，反駁素食主張。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":1},{"front":"might be forgiven for thinking","meaning":"可能會被原諒有這種想法","examples":[{"en":"You might be forgiven for thinking that vegetarians are often seen as morally superior.","zh":"如果你以為素食者常被視為道德上較優越，這種想法也可以理解。"},{"en":"Might be forgiven for thinking means it is understandable if someone forms that impression.","zh":"might be forgiven for thinking 指某人形成某種印象是可以理解的。"},{"en":"You might be forgiven for thinking the shop is closed if all the lights are off.","zh":"如果店舖所有燈都關了，你以為它關門也可以理解。"},{"en":"If the media praises one lifestyle constantly, readers might be forgiven for thinking it is morally better.","zh":"如果媒體不斷讚揚某種生活方式，讀者以為它在道德上較好也可以理解。"},{"en":"This phrase softens a judgement by saying the mistake or impression is reasonable.","zh":"這個片語透過表示某種錯誤或印象合理，來柔化判斷。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":1},{"front":"vegetarians","meaning":"素食者","examples":[{"en":"Vegetarians do not eat meat.","zh":"素食者不吃肉。"},{"en":"Vegetarians are people who avoid meat, though some may still eat eggs or dairy products.","zh":"vegetarians 是避免吃肉的人，不過有些仍可能吃雞蛋或奶製品。"},{"en":"A school canteen may offer pasta, vegetables, and tofu for vegetarians.","zh":"學校飯堂可能為素食者提供意粉、蔬菜和豆腐。"},{"en":"If more vegetarians attend an event, organisers need to prepare non-meat dishes.","zh":"如果更多素食者參加活動，主辦方需要準備非肉類菜式。"},{"en":"This word describes a dietary choice, not necessarily a complete lifestyle or belief system.","zh":"這個詞描述飲食選擇，不一定代表完整生活方式或信仰體系。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":1},{"front":"somehow superior","meaning":"不知怎的較優越","examples":[{"en":"The writer suggests that vegetarians are sometimes treated as somehow superior.","zh":"作者暗示素食者有時被視為不知怎的較優越。"},{"en":"Somehow superior means better in a vague or not clearly explained way.","zh":"somehow superior 指以含糊或未清楚解釋的方式被認為較好。"},{"en":"A student with expensive notes may be treated as somehow superior, even if they have not studied harder.","zh":"擁有昂貴筆記的學生可能被視為不知怎的較優越，即使他沒有更努力溫習。"},{"en":"If people praise one diet too strongly, others may feel judged as inferior.","zh":"如果人們過度讚揚某種飲食，其他人可能感到自己被判定較低等。"},{"en":"This phrase often suggests doubt about whether the supposed superiority is fair.","zh":"這個片語常暗示所謂優越是否公平值得懷疑。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":1},{"front":"superior human beings","meaning":"較優越的人","examples":[{"en":"The passage questions the idea that vegetarians are superior human beings.","zh":"文章質疑素食者是較優越的人這種想法。"},{"en":"Superior human beings are people treated as morally, intellectually, or personally better than others.","zh":"superior human beings 指被視為在道德、智力或個人質素上比他人更好的人。"},{"en":"No student should be treated as a superior human being simply because they get higher marks.","zh":"不應只因學生分數較高，就把他視為較優越的人。"},{"en":"If one group is described as superior, another group may feel unfairly judged.","zh":"如果一個群體被描述為較優越，另一個群體可能感到被不公平評判。"},{"en":"This phrase is often used critically when someone rejects moral arrogance.","zh":"這個片語常帶批評意味，用於反對道德優越感。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":1},{"front":"in today’s climate of","meaning":"在現今……的氣氛下","examples":[{"en":"In today’s climate of environmental concern, many people question meat-eating.","zh":"在現今環境關注的氣氛下，許多人質疑吃肉。"},{"en":"In today’s climate of something means in the current social mood or atmosphere surrounding an issue.","zh":"in today’s climate of something 指在目前圍繞某議題的社會情緒或氣氛下。"},{"en":"In today’s climate of exam pressure, many students feel guilty when they rest.","zh":"在現今考試壓力的氣氛下，許多學生休息時會感到內疚。"},{"en":"If environmental concern is strong, ordinary food choices may become moral debates.","zh":"如果環境關注強烈，普通飲食選擇可能變成道德辯論。"},{"en":"This phrase describes the wider public feeling that shapes people’s views.","zh":"這個片語描述塑造人們看法的更廣泛公共氣氛。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":1},{"front":"New Age spiritualism","meaning":"新紀元靈性主義","examples":[{"en":"New Age spiritualism is mentioned as part of the modern climate.","zh":"新紀元靈性主義被提及為現代氣氛的一部分。"},{"en":"New Age spiritualism refers to modern spiritual beliefs that often mix nature, personal growth, healing, and alternative practices.","zh":"New Age spiritualism 指現代靈性信念，常混合自然、個人成長、療癒和另類做法。"},{"en":"A person interested in crystals, meditation, and energy healing may be drawn to New Age spiritualism.","zh":"對水晶、冥想和能量療癒感興趣的人，可能受新紀元靈性主義吸引。"},{"en":"If spiritual ideas influence diet, people may connect food choices with purity or harmony.","zh":"如果靈性想法影響飲食，人們可能把食物選擇與純淨或和諧連接起來。"},{"en":"This phrase names a cultural trend rather than one fixed religion.","zh":"這個片語指一種文化潮流，而不是單一固定宗教。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":1},{"front":"animal rights","meaning":"動物權益","examples":[{"en":"Animal rights arguments are often used against eating meat.","zh":"動物權益論點常被用來反對吃肉。"},{"en":"Animal rights are the idea that animals deserve moral consideration and protection from unnecessary suffering.","zh":"animal rights 是動物值得道德考慮，並應受保護免受不必要痛苦的想法。"},{"en":"A campaign for animal rights may ask shops to stop selling products tested on animals.","zh":"動物權益運動可能要求商店停止售賣經動物測試的產品。"},{"en":"If people believe strongly in animal rights, they may reject farming practices that cause pain.","zh":"如果人們強烈相信動物權益，可能拒絕造成痛苦的農業做法。"},{"en":"This phrase is often used in ethical debates about food, testing, and entertainment.","zh":"這個片語常用於關於食物、測試和娛樂的倫理辯論。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":1},{"front":"Mother Earth naturalism","meaning":"大地之母式自然主義","examples":[{"en":"Mother Earth naturalism is linked with respect for nature.","zh":"大地之母式自然主義與尊重自然有關。"},{"en":"Mother Earth naturalism is a belief or attitude that treats nature as sacred, nurturing, and morally important.","zh":"Mother Earth naturalism 是把自然視為神聖、滋養生命並具有道德重要性的信念或態度。"},{"en":"A community garden may reflect Mother Earth naturalism if people see soil, plants, and animals as part of one living whole.","zh":"如果人們把泥土、植物和動物視為一個生命整體，社區花園可能反映大地之母式自然主義。"},{"en":"If people adopt this view, they may judge industrial farming as unnatural or harmful.","zh":"如果人們採納這種看法，可能把工業化畜牧評為不自然或有害。"},{"en":"This phrase suggests a spiritual or emotional respect for the natural world.","zh":"這個片語暗示對自然世界的靈性或情感尊重。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":1},{"front":"confirmed meat-eaters","meaning":"堅定肉食者","examples":[{"en":"Confirmed meat-eaters may feel criticised by extreme vegetarian arguments.","zh":"堅定肉食者可能感到被極端素食論點批評。"},{"en":"Confirmed meat-eaters are people who firmly eat meat and are unlikely to change that habit.","zh":"confirmed meat-eaters 是堅定吃肉並不太可能改變這種習慣的人。"},{"en":"A confirmed meat-eater may choose steak even when several vegetarian dishes are available.","zh":"堅定肉食者即使面前有幾款素食菜式，也可能選擇牛扒。"},{"en":"If public debate becomes moralising, confirmed meat-eaters may feel personally attacked.","zh":"如果公共辯論變得道德化，堅定肉食者可能感到被個人攻擊。"},{"en":"This phrase describes a strong and settled dietary preference.","zh":"這個片語描述強烈而固定的飲食偏好。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":1},{"front":"be categorised as","meaning":"被歸類為","examples":[{"en":"Meat-eaters are sometimes categorised as selfish.","zh":"肉食者有時被歸類為自私。"},{"en":"To be categorised as something means to be put into a particular group or labelled in a certain way.","zh":"be categorised as something 指被放入某個類別，或被貼上某種標籤。"},{"en":"A quiet student should not automatically be categorised as lazy or uninterested.","zh":"安靜學生不應自動被歸類為懶惰或沒興趣。"},{"en":"If people are categorised unfairly, debate becomes personal rather than reasonable.","zh":"如果人們被不公平分類，辯論會變得個人化而非理性。"},{"en":"This phrase often appears when discussing labels and stereotypes.","zh":"這個片語常見於討論標籤和刻板印象時。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":1},{"front":"environmentally irresponsible","meaning":"對環境不負責任的","examples":[{"en":"The writer says meat-eaters may be viewed as environmentally irresponsible.","zh":"作者說肉食者可能被視為對環境不負責任。"},{"en":"Environmentally irresponsible means acting in ways that harm the environment or ignore environmental consequences.","zh":"environmentally irresponsible 指行為會傷害環境或忽視環境後果。"},{"en":"A company that dumps chemicals into a river is environmentally irresponsible.","zh":"把化學品倒入河流的公司是對環境不負責任的。"},{"en":"If consumers waste food and energy, their habits may damage the planet over time.","zh":"如果消費者浪費食物和能源，其習慣可能隨時間傷害地球。"},{"en":"This phrase is used to criticise behaviour that neglects environmental duty.","zh":"這個片語用來批評忽視環境責任的行為。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":2},{"front":"spiritually deprived","meaning":"靈性貧乏的","examples":[{"en":"Some critics describe meat-eaters as spiritually deprived.","zh":"一些批評者把肉食者描述為靈性貧乏。"},{"en":"Spiritually deprived means lacking spiritual awareness, depth, or connection with higher values.","zh":"spiritually deprived 指缺乏靈性覺知、深度或與更高價值的連繫。"},{"en":"A person may feel spiritually deprived if work, money, and routine leave no time for reflection.","zh":"如果工作、金錢和日常安排令人沒有時間反思，一個人可能感到靈性貧乏。"},{"en":"If a critic calls others spiritually deprived, the criticism may sound morally superior.","zh":"如果批評者稱別人靈性貧乏，批評可能聽起來有道德優越感。"},{"en":"This phrase judges someone’s inner life, so it can sound harsh.","zh":"這個片語評判人的內在生命，因此可能聽起來嚴厲。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":2},{"front":"gluttons","meaning":"貪吃的人；貪食鬼","examples":[{"en":"The writer objects to meat-eaters being labelled as gluttons.","zh":"作者反對肉食者被標籤為貪吃的人。"},{"en":"Gluttons are people who eat or consume too much, especially with little self-control.","zh":"gluttons 是吃得或消耗得太多的人，尤其是缺乏自制的人。"},{"en":"A child who eats all the cakes before guests arrive may be jokingly called a glutton.","zh":"如果孩子在客人到達前吃光所有蛋糕，可能被開玩笑地稱為貪食鬼。"},{"en":"If meat-eaters are called gluttons, the label suggests greed rather than ordinary eating habits.","zh":"如果肉食者被稱為貪吃的人，這個標籤暗示貪婪，而不是普通飲食習慣。"},{"en":"This word is negative and should be used carefully.","zh":"這個詞帶負面意味，應謹慎使用。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":2},{"front":"dietary desire","meaning":"飲食慾望","examples":[{"en":"The passage discusses the dietary desire for meat.","zh":"文章討論對肉類的飲食慾望。"},{"en":"Dietary desire means a wish or appetite for a particular kind of food.","zh":"dietary desire 指對某種食物的渴望或食慾。"},{"en":"A person may have a strong dietary desire for sweet food after a stressful day.","zh":"一個人在壓力大的一天後，可能對甜食有強烈飲食慾望。"},{"en":"If a dietary desire becomes excessive, it may influence health or spending habits.","zh":"如果飲食慾望變得過度，它可能影響健康或消費習慣。"},{"en":"This phrase focuses on food-related wants rather than general emotion.","zh":"這個片語聚焦於與食物相關的慾望，而不是一般情緒。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":2},{"front":"akin to","meaning":"類似於","examples":[{"en":"Some extreme critics treat eating meat as akin to cannibalism.","zh":"一些極端批評者把吃肉視為類似食人行為。"},{"en":"Akin to means similar to or comparable with something.","zh":"akin to 指與某事相似或可比較。"},{"en":"Ignoring safety rules in a hospital can be akin to putting patients at risk deliberately.","zh":"在醫院忽視安全規則，可能類似於故意把病人置於風險中。"},{"en":"If one action is described as akin to another, the writer wants readers to see a strong similarity.","zh":"如果某行為被描述為類似另一行為，作者希望讀者看見強烈相似性。"},{"en":"This phrase is formal and often used in serious comparisons.","zh":"這個片語較正式，常用於嚴肅比較。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":2},{"front":"cannibalism","meaning":"食人行為","examples":[{"en":"The writer rejects the idea that meat-eating is like cannibalism.","zh":"作者拒絕吃肉像食人行為這種想法。"},{"en":"Cannibalism means humans eating human flesh, or animals eating members of their own species.","zh":"cannibalism 指人吃人肉，或動物吃同類。"},{"en":"In most societies, cannibalism is treated as a strong moral taboo.","zh":"在大多數社會，食人行為被視為強烈道德禁忌。"},{"en":"If eating meat is compared with cannibalism, the comparison is meant to shock readers.","zh":"如果吃肉被拿來與食人行為比較，這種比較意在震驚讀者。"},{"en":"This word describes an extreme act, so it carries heavy emotional force.","zh":"這個詞描述極端行為，因此帶有強烈情感力量。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":2},{"front":"lamb chop","meaning":"羊扒","examples":[{"en":"A lamb chop is used as an example of meat in the passage.","zh":"羊扒在文章中被用作肉類的例子。"},{"en":"A lamb chop is a cut of meat from a young sheep, often cooked by grilling or frying.","zh":"lamb chop 是來自幼羊的一塊肉，常以燒烤或煎煮方式烹調。"},{"en":"A restaurant may serve lamb chops with potatoes and vegetables.","zh":"餐廳可能供應配薯仔和蔬菜的羊扒。"},{"en":"If someone avoids meat, they would not order a lamb chop.","zh":"如果某人避免吃肉，就不會點羊扒。"},{"en":"This phrase names a specific meat dish rather than meat in general.","zh":"這個片語指特定肉類菜式，而不是泛指肉。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":2},{"front":"roast beef","meaning":"燒牛肉","examples":[{"en":"A serving of roast beef is presented as an example of meat-eating.","zh":"一份燒牛肉被呈現為吃肉的例子。"},{"en":"Roast beef is beef cooked by roasting, often sliced and served hot or cold.","zh":"roast beef 是以烤焗方式烹調的牛肉，常切片熱食或冷食。"},{"en":"A family may eat roast beef at a Sunday dinner with vegetables and gravy.","zh":"家庭可能在星期日晚餐吃配蔬菜和肉汁的燒牛肉。"},{"en":"If roast beef is part of a meal, the meal is not vegetarian.","zh":"如果一餐包含燒牛肉，這餐就不是素食。"},{"en":"This phrase refers to a common cooked meat dish.","zh":"這個片語指常見熟肉菜式。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":2},{"front":"chicken drumstick","meaning":"雞槌；雞腿","examples":[{"en":"A chicken drumstick is mentioned as a common meat dish.","zh":"雞槌被提及為常見肉類菜式。"},{"en":"A chicken drumstick is the lower part of a chicken leg, often eaten roasted, fried, or grilled.","zh":"chicken drumstick 是雞腿下半部分，常被烤、炸或燒來吃。"},{"en":"Children may eat chicken drumsticks at a picnic because they are easy to hold.","zh":"孩子可能在野餐時吃雞槌，因為它容易拿着。"},{"en":"If a school meal includes chicken drumsticks, vegetarian students need another option.","zh":"如果學校膳食包括雞槌，素食學生便需要另一個選擇。"},{"en":"This phrase names a familiar piece of chicken meat.","zh":"這個片語指熟悉的一塊雞肉。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":2},{"front":"signifies","meaning":"象徵；表示","examples":[{"en":"Each meat dish is said to signify the death of an animal.","zh":"每道肉類菜式都被說成象徵一隻動物的死亡。"},{"en":"Signifies means represents, shows, or stands for something.","zh":"signifies 指代表、顯示或象徵某事。"},{"en":"A red traffic light signifies that drivers must stop.","zh":"紅色交通燈表示司機必須停車。"},{"en":"If a trophy signifies success, people may treat it as more than just metal and plastic.","zh":"如果獎盃象徵成功，人們可能把它視為不只是金屬和塑膠。"},{"en":"This word links an object or action with a deeper meaning.","zh":"這個詞把物件或行動與更深層意思連接起來。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":2},{"front":"a brutal execution","meaning":"殘酷處死","examples":[{"en":"The passage describes the killing of animals as a brutal execution from a vegetarian viewpoint.","zh":"從素食者角度，文章把殺死動物描述為殘酷處死。"},{"en":"A brutal execution is a cruel and violent killing, especially when the victim is powerless.","zh":"brutal execution 是殘忍而暴力的殺戮，尤其是受害者無力反抗時。"},{"en":"A writer may describe a harsh punishment as a brutal execution to shock readers.","zh":"作者可能把嚴厲懲罰描述為殘酷處死，以震撼讀者。"},{"en":"If animal slaughter is framed as a brutal execution, eating meat becomes a moral issue.","zh":"如果動物屠宰被框定為殘酷處死，吃肉便成為道德問題。"},{"en":"This phrase is emotionally strong and deliberately severe.","zh":"這個片語情感強烈，語氣刻意嚴厲。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":2},{"front":"a sentient animal","meaning":"有感知能力的動物","examples":[{"en":"A sentient animal can feel pain and suffering.","zh":"有感知能力的動物能感到痛楚和痛苦。"},{"en":"A sentient animal is an animal that can experience feelings such as pain, fear, or pleasure.","zh":"sentient animal 是能經歷痛楚、恐懼或快樂等感受的動物。"},{"en":"A dog is a sentient animal because it can feel fear, comfort, and distress.","zh":"狗是有感知能力的動物，因為牠能感到恐懼、舒適和痛苦。"},{"en":"If animals are sentient, people may feel a stronger moral duty to reduce their suffering.","zh":"如果動物有感知能力，人們可能感到更強的道德責任去減少其痛苦。"},{"en":"This phrase is important in ethical discussions about animal treatment.","zh":"這個片語在關於動物待遇的倫理討論中很重要。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":3},{"front":"to whose suffering","meaning":"對其痛苦","examples":[{"en":"The writer refers to animals to whose suffering people may seem indifferent.","zh":"作者提到人們似乎對其痛苦漠不關心的動物。"},{"en":"To whose suffering means to the pain or distress experienced by those beings.","zh":"to whose suffering 指對那些生物所經歷的痛楚或痛苦。"},{"en":"Refugees to whose suffering the public becomes blind may receive too little help.","zh":"如果公眾對難民的痛苦變得麻木，他們可能得到太少幫助。"},{"en":"If people ignore animals’ suffering, critics may accuse them of moral carelessness.","zh":"如果人們忽視動物痛苦，批評者可能指責他們道德上粗心。"},{"en":"This phrase is formal and links concern to the suffering of a particular group.","zh":"這個片語較正式，把關注與某一群體的痛苦連接起來。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":3},{"front":"callously indifferent","meaning":"冷酷漠視的","examples":[{"en":"The passage suggests that meat-eaters are accused of being callously indifferent to animal suffering.","zh":"文章暗示肉食者被指對動物痛苦冷酷漠視。"},{"en":"Callously indifferent means coldly unconcerned about other people’s or animals’ pain.","zh":"callously indifferent 指冷酷地不關心他人或動物的痛苦。"},{"en":"A manager who ignores injured workers may seem callously indifferent.","zh":"忽視受傷工人的經理可能顯得冷酷漠視。"},{"en":"If someone appears callously indifferent, others may judge them as cruel or selfish.","zh":"如果某人看似冷酷漠視，其他人可能判定他殘忍或自私。"},{"en":"This phrase is strongly negative and criticises lack of compassion.","zh":"這個片語非常負面，批評缺乏同情心。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":3},{"front":"offer arguments to counter","meaning":"提出論點反駁","examples":[{"en":"The writer offers arguments to counter extreme vegetarian claims.","zh":"作者提出論點反駁極端素食主張。"},{"en":"To offer arguments to counter something means to present reasons against it.","zh":"offer arguments to counter something 指提出理由反對某事。"},{"en":"A student may offer arguments to counter the idea that homework should be banned completely.","zh":"學生可能提出論點反駁應完全禁止功課的想法。"},{"en":"If a claim is extreme, counterarguments may try to show that it ignores important facts.","zh":"如果主張極端，反駁論點可能試圖顯示它忽視重要事實。"},{"en":"This phrase describes reasoned opposition in a debate.","zh":"這個片語描述辯論中的理性反對。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":3},{"front":"extreme claims","meaning":"極端主張","examples":[{"en":"The passage challenges the more extreme claims made against meat-eating.","zh":"文章挑戰反對吃肉的較極端主張。"},{"en":"Extreme claims are strong statements that go far beyond a moderate or balanced position.","zh":"extreme claims 是遠超溫和或平衡立場的強烈說法。"},{"en":"Saying that all exams are useless is an extreme claim that needs strong evidence.","zh":"說所有考試都沒有用，是需要有力證據支持的極端主張。"},{"en":"If a claim sounds extreme, readers may expect the writer to challenge it.","zh":"如果某主張聽起來極端，讀者可能預期作者會挑戰它。"},{"en":"This phrase often describes views that are forceful but possibly unfair.","zh":"這個片語常描述強硬但可能不公平的看法。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":3},{"front":"the bean-sprout crowd","meaning":"芽菜族；對素食者的戲謔稱呼","examples":[{"en":"The writer uses the phrase “the bean-sprout crowd” to refer mockingly to vegetarians.","zh":"作者使用 “the bean-sprout crowd” 這個片語來戲謔地指素食者。"},{"en":"The bean-sprout crowd is a joking or mocking label for people associated with vegetarian or very healthy eating.","zh":"the bean-sprout crowd 是對與素食或非常健康飲食相關的人作出的玩笑或嘲諷稱呼。"},{"en":"A writer may use a playful label like this to show irritation with a group’s moral tone.","zh":"作者可能使用這種玩笑標籤，顯示對某群體道德語氣的不滿。"},{"en":"If a phrase mocks a group, it reveals the writer’s attitude as well as the topic.","zh":"如果片語嘲笑某群體，它既揭示作者態度，也揭示主題。"},{"en":"This phrase is informal and should not be used in neutral academic writing.","zh":"這個片語較口語，不應用於中立學術寫作。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":3},{"front":"first justification","meaning":"第一個理據","examples":[{"en":"The vegetarians’ first justification is that eating meat is cruel.","zh":"素食者的第一個理據是吃肉對動物殘忍。"},{"en":"A first justification is the first reason given to defend or explain a position.","zh":"first justification 是用來辯護或解釋某立場的第一個理由。"},{"en":"A student’s first justification for being late may be that the bus broke down.","zh":"學生遲到的第一個理由可能是巴士壞了。"},{"en":"If the first justification is weak, readers may doubt the argument from the beginning.","zh":"如果第一個理據薄弱，讀者可能從一開始就懷疑論點。"},{"en":"This phrase marks the first supporting reason in an argument.","zh":"這個片語標示論證中的第一個支持理由。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":3},{"front":"eating meat is cruel to animals","meaning":"吃肉對動物殘忍","examples":[{"en":"Many vegetarians argue that eating meat is cruel to animals.","zh":"許多素食者主張吃肉對動物殘忍。"},{"en":"Eating meat is cruel to animals means meat consumption causes unnecessary suffering or death to animals.","zh":"eating meat is cruel to animals 指肉類消費對動物造成不必要痛苦或死亡。"},{"en":"A debate club may discuss whether modern farming makes eating meat cruel to animals.","zh":"辯論學會可能討論現代農業是否令吃肉對動物殘忍。"},{"en":"If animals are kept in poor conditions, critics may see meat-eating as morally wrong.","zh":"如果動物被飼養在惡劣環境中，批評者可能把吃肉視為道德錯誤。"},{"en":"This phrase states the ethical objection behind many vegetarian arguments.","zh":"這個片語表明許多素食論點背後的倫理反對。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":3},{"front":"when pondering cruelty","meaning":"在思考殘忍時","examples":[{"en":"When pondering cruelty, the writer compares farm animals with wild animals.","zh":"在思考殘忍時，作者把家畜與野生動物作比較。"},{"en":"When pondering cruelty means when thinking carefully about what counts as cruel treatment.","zh":"when pondering cruelty 指仔細思考甚麼算是殘忍對待時。"},{"en":"When pondering cruelty in schools, people may compare strict discipline with genuine abuse.","zh":"在思考學校中的殘忍時，人們可能比較嚴格紀律與真正虐待。"},{"en":"If we think about cruelty, we need to consider pain, fear, intention, and alternatives.","zh":"如果我們思考殘忍，就需要考慮痛楚、恐懼、意圖和替代選擇。"},{"en":"This phrase introduces careful moral reflection.","zh":"這個片語引入仔細的道德反思。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":3},{"front":"it may pay to reflect on","meaning":"值得思考","examples":[{"en":"It may pay to reflect on how animals live in the wild.","zh":"值得思考動物在野外如何生活。"},{"en":"It may pay to reflect on something means it may be useful to think carefully about it.","zh":"it may pay to reflect on something 指仔細思考某事可能有用。"},{"en":"Before choosing a university, it may pay to reflect on cost, distance, and career goals.","zh":"在選擇大學前，值得思考費用、距離和職業目標。"},{"en":"If people debate food ethics, reflecting on natural animal suffering may change the discussion.","zh":"如果人們辯論飲食倫理，思考自然界中的動物痛苦可能改變討論。"},{"en":"This phrase suggests careful thought could bring insight or benefit.","zh":"這個片語暗示仔細思考可以帶來洞見或好處。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":3},{"front":"how animals fare","meaning":"動物過得怎樣","examples":[{"en":"The writer asks readers to consider how animals fare in the wild.","zh":"作者要求讀者考慮動物在野外過得怎樣。"},{"en":"How animals fare means how well or badly animals live, survive, or cope.","zh":"how animals fare 指動物生活、生存或應對得好不好。"},{"en":"A vet may study how stray dogs fare during a very cold winter.","zh":"獸醫可能研究流浪狗在嚴寒冬天過得怎樣。"},{"en":"If animals fare badly in the wild, the writer may argue that farm life is not always worse.","zh":"如果動物在野外過得很差，作者可能主張農場生活不一定更差。"},{"en":"This phrase focuses on actual living conditions and outcomes.","zh":"這個片語聚焦於實際生活條件和結果。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":3},{"front":"in the wild","meaning":"在野外","examples":[{"en":"Animals in the wild often face danger and suffering.","zh":"野外動物常面對危險和痛苦。"},{"en":"In the wild means living in natural conditions, not kept by humans.","zh":"in the wild 指生活在自然環境中，而不是由人類飼養。"},{"en":"A bird in the wild must find its own food and avoid predators.","zh":"在野外的鳥必須自己覓食並避開掠食者。"},{"en":"If an animal lives in the wild, illness and injury may go untreated.","zh":"如果動物生活在野外，疾病和受傷可能得不到治療。"},{"en":"This phrase contrasts natural freedom with human care or control.","zh":"這個片語對比自然自由與人類照料或控制。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":4},{"front":"a documentary concerning","meaning":"一部關於……的紀錄片","examples":[{"en":"The writer watched a documentary concerning herbivores on the African plains.","zh":"作者看了一部關於非洲平原草食動物的紀錄片。"},{"en":"A documentary concerning something is a factual film or programme about that topic.","zh":"a documentary concerning something 是關於某主題的事實影片或節目。"},{"en":"A documentary concerning school stress may interview students, parents, and teachers.","zh":"一部關於學業壓力的紀錄片可能訪問學生、家長和老師。"},{"en":"If a documentary shows real suffering, viewers may rethink simple ideas about nature.","zh":"如果紀錄片展示真實痛苦，觀眾可能重新思考關於自然的簡單想法。"},{"en":"This phrase is formal and means a documentary about.","zh":"這個片語較正式，意思是關於某事的紀錄片。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":4},{"front":"herbivores","meaning":"草食動物","examples":[{"en":"Herbivores are animals that eat plants.","zh":"草食動物是吃植物的動物。"},{"en":"Herbivores feed mainly on grass, leaves, fruit, or other plant material.","zh":"herbivores 主要以草、葉、水果或其他植物材料為食。"},{"en":"Cows, deer, rabbits, and zebras are common examples of herbivores.","zh":"牛、鹿、兔和斑馬都是常見草食動物例子。"},{"en":"If herbivores disappear from an ecosystem, predators may lose an important food source.","zh":"如果草食動物從生態系統中消失，掠食者可能失去重要食物來源。"},{"en":"This word contrasts with carnivores, which eat other animals.","zh":"這個詞與吃其他動物的 carnivores 形成對比。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":4},{"front":"the African plains","meaning":"非洲平原","examples":[{"en":"Herbivores on the African plains face many predators.","zh":"非洲平原上的草食動物面對許多掠食者。"},{"en":"The African plains are wide open grassland areas in Africa where many wild animals live.","zh":"African plains 是非洲廣闊開放的草原地區，許多野生動物在那裡生活。"},{"en":"Wildlife documentaries often show lions, zebras, and antelopes on the African plains.","zh":"野生動物紀錄片常展示非洲平原上的獅子、斑馬和羚羊。"},{"en":"If animals live on open plains, predators may spot them from far away.","zh":"如果動物生活在開闊平原上，掠食者可能從遠處發現牠們。"},{"en":"This phrase gives a natural setting associated with large wild herds.","zh":"這個片語提供一個與大型野生獸群相關的自然場景。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":4},{"front":"parasite- and insect-tormented herds","meaning":"受寄生蟲和昆蟲折磨的獸群","examples":[{"en":"The documentary showed parasite- and insect-tormented herds.","zh":"紀錄片展示受寄生蟲和昆蟲折磨的獸群。"},{"en":"Parasite- and insect-tormented herds are groups of animals suffering because parasites and insects bite, irritate, or weaken them.","zh":"parasite- and insect-tormented herds 指因寄生蟲和昆蟲叮咬、刺激或削弱而受苦的動物群。"},{"en":"Cattle without proper care may become insect-tormented during a hot wet season.","zh":"在炎熱潮濕季節，沒有適當照料的牛群可能被昆蟲折磨。"},{"en":"If animals are constantly bitten, they may lose energy and become more vulnerable.","zh":"如果動物不斷被叮咬，牠們可能失去能量並變得更脆弱。"},{"en":"This phrase shows that wild life can involve ongoing discomfort, not only freedom.","zh":"這個片語顯示野外生活可以包含持續不適，而不只是自由。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":4},{"front":"lead lives of","meaning":"過着……的生活","examples":[{"en":"Wild herbivores lead lives of constant fear and movement.","zh":"野生草食動物過着持續恐懼和移動的生活。"},{"en":"To lead lives of something means to live in a way strongly marked by that condition.","zh":"lead lives of something 指生活方式強烈受某種狀況標記。"},{"en":"Some students lead lives of pressure if every hour is filled with lessons and homework.","zh":"如果每小時都排滿課堂和功課，有些學生會過着充滿壓力的生活。"},{"en":"If animals are always hunted, they may lead lives of fear rather than peace.","zh":"如果動物總是被獵捕，牠們可能過着恐懼而不是平靜的生活。"},{"en":"This phrase describes the overall pattern of someone’s life.","zh":"這個片語描述某人生活的整體模式。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":4},{"front":"hair-raising","meaning":"令人毛骨悚然的","examples":[{"en":"The animals experience hair-raising escapes from predators.","zh":"這些動物經歷令人毛骨悚然的逃避掠食者場面。"},{"en":"Hair-raising means extremely frightening, exciting, or alarming.","zh":"hair-raising 指極其可怕、刺激或令人警覺。"},{"en":"A hair-raising bus ride down a narrow mountain road may leave passengers silent.","zh":"巴士沿狹窄山路下坡的驚險旅程，可能令乘客沉默。"},{"en":"If an animal barely escapes a lion, the scene can feel hair-raising to viewers.","zh":"如果動物僅僅逃過獅子追捕，畫面會令觀眾毛骨悚然。"},{"en":"This word describes a moment that makes people tense or scared.","zh":"這個詞描述令人緊張或害怕的時刻。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":4},{"front":"nerve-jittering","meaning":"令人神經緊張的","examples":[{"en":"Their lives include nerve-jittering bolts and dashes.","zh":"牠們的生活包括令人神經緊張的猛衝和逃竄。"},{"en":"Nerve-jittering means making someone feel extremely nervous or tense.","zh":"nerve-jittering 指令人極度緊張或焦慮。"},{"en":"Waiting for medical test results can be a nerve-jittering experience.","zh":"等待醫療檢查結果可以是令人神經緊張的經歷。"},{"en":"If animals must suddenly run for their lives, their movements can look nerve-jittering.","zh":"如果動物必須突然逃命，牠們的動作可能看起來令人神經緊張。"},{"en":"This word stresses anxiety and tension.","zh":"這個詞強調焦慮和緊張。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":4},{"front":"bolts and dashes","meaning":"猛衝和逃竄","examples":[{"en":"Wild animals survive through sudden bolts and dashes.","zh":"野生動物透過突然猛衝和逃竄來生存。"},{"en":"Bolts and dashes are quick sudden runs, usually to escape danger.","zh":"bolts and dashes 是快速突然的奔跑，通常為了逃避危險。"},{"en":"A child may make a quick dash across the playground when the rain starts.","zh":"下雨時，孩子可能快速衝過操場。"},{"en":"If animals sense a predator, sudden bolts can save their lives.","zh":"如果動物感覺到掠食者，突然猛衝可以救牠們一命。"},{"en":"This phrase suggests fast, urgent movement rather than calm walking.","zh":"這個片語暗示快速而迫切的移動，而不是平靜步行。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":4},{"front":"constantly stalked by","meaning":"不斷被……跟蹤","examples":[{"en":"The herds are constantly stalked by predators.","zh":"這些獸群不斷被掠食者跟蹤。"},{"en":"Constantly stalked by means repeatedly and quietly followed by someone or something dangerous.","zh":"constantly stalked by 指反覆而悄悄地被危險的人或物跟隨。"},{"en":"A mouse may be constantly stalked by a cat in a garden.","zh":"老鼠可能在花園中不斷被貓跟蹤。"},{"en":"If animals are constantly stalked, they cannot rest without fear.","zh":"如果動物不斷被跟蹤，牠們就不能無懼地休息。"},{"en":"This phrase describes ongoing hidden danger.","zh":"這個片語描述持續存在的隱藏危險。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":4},{"front":"a range of predators","meaning":"一系列掠食者","examples":[{"en":"Herbivores are hunted by a range of predators.","zh":"草食動物被一系列掠食者獵捕。"},{"en":"A range of predators means several different kinds of animals that hunt other animals.","zh":"a range of predators 指幾種不同捕獵其他動物的動物。"},{"en":"Small fish may face a range of predators, including birds, larger fish, and snakes.","zh":"小魚可能面對一系列掠食者，包括鳥、大魚和蛇。"},{"en":"If many predators hunt the same prey, the prey must stay alert constantly.","zh":"如果許多掠食者捕獵同一獵物，獵物必須時刻警覺。"},{"en":"This phrase shows variety in danger.","zh":"這個片語顯示危險的多樣性。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":4},{"front":"compare this to","meaning":"將這與……比較","examples":[{"en":"The writer compares this to animals living in domestic pastures.","zh":"作者將這與生活在家畜牧場的動物比較。"},{"en":"To compare this to something means to look at two things together to notice similarities or differences.","zh":"compare this to something 指把兩件事放在一起看，以注意相似或差異。"},{"en":"A teacher may compare city life to village life to explain urbanisation.","zh":"老師可能把城市生活與鄉村生活比較，以解釋城市化。"},{"en":"If we compare wild danger to farm care, the moral argument becomes more complicated.","zh":"如果我們把野外危險與農場照料比較，道德論點會變得更複雜。"},{"en":"This phrase introduces a contrast or comparison.","zh":"這個片語引入對比或比較。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":5},{"front":"munching grass","meaning":"咀嚼青草","examples":[{"en":"Domestic animals are described as peacefully munching grass.","zh":"家畜被描述為平靜地咀嚼青草。"},{"en":"Munching grass means eating grass slowly and steadily, often with a relaxed image.","zh":"munching grass 指慢慢而穩定地吃草，常帶有放鬆意象。"},{"en":"Cows may stand in a field munching grass on a quiet afternoon.","zh":"牛可能在寧靜午後站在田野中咀嚼青草。"},{"en":"If animals are calmly munching grass, the writer wants to show their life as peaceful.","zh":"如果動物平靜地咀嚼青草，作者想把牠們的生活呈現為安詳。"},{"en":"This phrase gives a gentle picture of grazing animals.","zh":"這個片語給出放牧動物的溫和畫面。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":5},{"front":"domestic pastures","meaning":"家畜牧場","examples":[{"en":"Farm animals live in domestic pastures rather than in the wild.","zh":"農場動物生活在家畜牧場，而不是野外。"},{"en":"Domestic pastures are fields managed by humans where farm animals graze.","zh":"domestic pastures 是由人類管理、供農場動物放牧的田野。"},{"en":"Sheep in domestic pastures may have fences, water troughs, and regular care.","zh":"在家畜牧場中的羊可能有圍欄、水槽和定期照料。"},{"en":"If animals live in domestic pastures, they may be safer from predators than wild animals.","zh":"如果動物生活在家畜牧場，牠們可能比野生動物更安全，不受掠食者威脅。"},{"en":"This phrase contrasts managed farm land with natural wilderness.","zh":"這個片語把受管理農地與自然荒野作對比。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":5},{"front":"four-legged friends","meaning":"四腳朋友；動物朋友","examples":[{"en":"The writer jokingly calls farm animals our four-legged friends.","zh":"作者戲謔地稱農場動物為我們的四腳朋友。"},{"en":"Four-legged friends is a warm or humorous way to refer to animals with four legs.","zh":"four-legged friends 是親切或幽默地指四足動物的說法。"},{"en":"A family may call their dog a four-legged friend because it feels like part of the household.","zh":"家庭可能稱自己的狗為四腳朋友，因為牠感覺像家庭一員。"},{"en":"If a writer uses this phrase for farm animals, the tone becomes playful rather than purely scientific.","zh":"如果作者用這個片語指農場動物，語氣會變得俏皮，而不是純科學。"},{"en":"This phrase personifies animals and makes them sound familiar.","zh":"這個片語把動物擬人化，令牠們聽起來熟悉。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":5},{"front":"watered and well-fed","meaning":"有水喝且吃得飽的","examples":[{"en":"Domestic animals are watered and well-fed.","zh":"家畜有水喝且吃得飽。"},{"en":"Watered and well-fed means given enough water and food.","zh":"watered and well-fed 指獲得足夠水和食物。"},{"en":"A pet should be watered and well-fed before its owner leaves for work.","zh":"主人上班前應確保寵物有水喝且吃得飽。"},{"en":"If farm animals are watered and well-fed, they may avoid hunger and dehydration.","zh":"如果農場動物有水喝且吃得飽，牠們可能避免飢餓和脫水。"},{"en":"This phrase describes basic care for animals.","zh":"這個片語描述對動物的基本照料。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":5},{"front":"attended to when sick","meaning":"生病時得到照料","examples":[{"en":"Farm animals are attended to when sick.","zh":"農場動物生病時得到照料。"},{"en":"Attended to when sick means cared for or treated when ill.","zh":"attended to when sick 指生病時得到照顧或治療。"},{"en":"A child should be attended to when sick, especially if a fever continues.","zh":"孩子生病時應得到照料，尤其是發燒持續時。"},{"en":"If animals are attended to when sick, they may recover faster than animals left alone in the wild.","zh":"如果動物生病時得到照料，牠們可能比野外無人照顧的動物康復得更快。"},{"en":"This phrase highlights human care during illness.","zh":"這個片語突出患病期間的人類照料。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":5},{"front":"essentially stress-free","meaning":"基本上沒有壓力的","examples":[{"en":"The writer claims that domestic animals have an essentially stress-free existence.","zh":"作者聲稱家畜有基本上沒有壓力的生活。"},{"en":"Essentially stress-free means mostly free from fear, pressure, or anxiety.","zh":"essentially stress-free 指大致沒有恐懼、壓力或焦慮。"},{"en":"A well-planned exam timetable can make revision essentially stress-free for organised students.","zh":"安排良好的考試時間表可以令有組織的學生溫習時基本上沒有壓力。"},{"en":"If animals have food, water, shelter, and protection, their lives may seem less stressful.","zh":"如果動物有食物、水、庇護和保護，牠們的生活可能看起來較少壓力。"},{"en":"This phrase allows for small problems but suggests the overall condition is calm.","zh":"這個片語容許有小問題，但暗示整體狀況平靜。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":5},{"front":"an easy existence","meaning":"安逸的生活","examples":[{"en":"Domestic animals are described as having an easy existence.","zh":"家畜被描述為過着安逸的生活。"},{"en":"An easy existence is a life with few difficulties, dangers, or pressures.","zh":"an easy existence 是困難、危險或壓力很少的生活。"},{"en":"A house cat may have an easy existence if it has food, warmth, and care every day.","zh":"如果家貓每天有食物、溫暖和照顧，它可能過着安逸的生活。"},{"en":"If an animal’s needs are met by humans, its existence may be easier than life in the wild.","zh":"如果動物的需要由人類滿足，其生活可能比野外生活更安逸。"},{"en":"This phrase describes comfort and lack of hardship.","zh":"這個片語描述舒適和少艱辛。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":5},{"front":"slaughterhouses","meaning":"屠房","examples":[{"en":"Vegetarians criticise the way animals die in slaughterhouses.","zh":"素食者批評動物在屠房中死亡的方式。"},{"en":"Slaughterhouses are places where animals are killed and processed for meat.","zh":"slaughterhouses 是動物被宰殺並加工成肉類的地方。"},{"en":"Meat sold in supermarkets usually comes from animals killed in slaughterhouses.","zh":"超級市場售賣的肉通常來自屠房中宰殺的動物。"},{"en":"If slaughterhouses are poorly regulated, animal suffering may increase.","zh":"如果屠房監管差，動物痛苦可能增加。"},{"en":"This word is central to ethical debates about meat production.","zh":"這個詞是關於肉類生產倫理辯論的核心。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":5},{"front":"deal out brutal deaths","meaning":"施以殘酷死亡","examples":[{"en":"Vegetarians claim that slaughterhouses deal out brutal deaths.","zh":"素食者聲稱屠房施以殘酷死亡。"},{"en":"To deal out brutal deaths means to cause or deliver cruel and violent deaths.","zh":"deal out brutal deaths 指造成或施加殘忍而暴力的死亡。"},{"en":"A harsh critic may say unsafe workplaces deal out slow deaths through neglect.","zh":"嚴厲批評者可能說不安全工作場所透過忽視施以慢性死亡。"},{"en":"If a system is described this way, the writer wants readers to see it as morally shocking.","zh":"如果一個系統被這樣描述，作者希望讀者把它視為道德上震撼。"},{"en":"This phrase is emotionally forceful and highly critical.","zh":"這個片語情感強烈，批評意味很重。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":5},{"front":"reflect again on","meaning":"再次思考","examples":[{"en":"The writer asks readers to reflect again on nature.","zh":"作者要求讀者再次思考自然。"},{"en":"To reflect again on something means to think carefully about it once more.","zh":"reflect again on something 指再次仔細思考某事。"},{"en":"After receiving feedback, a student may reflect again on the main argument of an essay.","zh":"收到回饋後，學生可能再次思考文章的主要論點。"},{"en":"If new evidence appears, people may need to reflect again on an opinion they held firmly.","zh":"如果新證據出現，人們可能需要再次思考自己原本堅信的看法。"},{"en":"This phrase suggests reconsideration.","zh":"這個片語暗示重新考慮。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":5},{"front":"at one point","meaning":"在某一刻","examples":[{"en":"At one point, the documentary showed an injured zebra.","zh":"在某一刻，紀錄片展示了一隻受傷斑馬。"},{"en":"At one point means at a particular moment in a story, film, or process.","zh":"at one point 指在故事、影片或過程中的某個特定時刻。"},{"en":"At one point during the lesson, the teacher stopped to explain a difficult word.","zh":"在課堂某一刻，老師停下來解釋一個困難詞語。"},{"en":"If a documentary shows a shocking scene at one point, viewers may remember it strongly.","zh":"如果紀錄片在某一刻展示震撼畫面，觀眾可能印象深刻。"},{"en":"This phrase marks one moment within a longer sequence.","zh":"這個片語標示較長序列中的某一時刻。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":6},{"front":"an injured zebra","meaning":"受傷的斑馬","examples":[{"en":"An injured zebra was quickly spotted by hyenas.","zh":"一隻受傷的斑馬很快被鬣狗發現。"},{"en":"An injured zebra is a zebra that has been hurt and may be weaker or slower than others.","zh":"injured zebra 是受了傷、可能比其他斑馬更弱或更慢的斑馬。"},{"en":"In a wildlife film, an injured zebra may struggle to keep up with the herd.","zh":"在野生動物影片中，受傷的斑馬可能難以跟上獸群。"},{"en":"If a zebra is injured, predators may target it because it is easier to catch.","zh":"如果斑馬受傷，掠食者可能鎖定牠，因為牠較容易捕捉。"},{"en":"This phrase gives a concrete example of vulnerability in the wild.","zh":"這個片語提供野外脆弱性的具體例子。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":6},{"front":"spotted by","meaning":"被……發現","examples":[{"en":"The injured zebra was spotted by a pack of hyenas.","zh":"受傷斑馬被一群鬣狗發現。"},{"en":"Spotted by means seen or noticed by someone or something.","zh":"spotted by 指被某人或某物看見或注意到。"},{"en":"A lost child was spotted by a bus driver near the station.","zh":"失蹤孩子在車站附近被巴士司機發現。"},{"en":"If a weak animal is spotted by predators, it may quickly become a target.","zh":"如果弱小動物被掠食者發現，它可能很快成為目標。"},{"en":"This phrase often introduces the moment when hidden danger begins.","zh":"這個片語常引入隱藏危險開始的時刻。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":6},{"front":"a pack of hyenas","meaning":"一群鬣狗","examples":[{"en":"A pack of hyenas attacked the injured zebra.","zh":"一群鬣狗襲擊了受傷斑馬。"},{"en":"A pack of hyenas is a group of hyenas hunting, travelling, or living together.","zh":"a pack of hyenas 是一起狩獵、移動或生活的一群鬣狗。"},{"en":"In a documentary, a pack of hyenas may surround a weak animal before attacking.","zh":"在紀錄片中，一群鬣狗可能先包圍弱小動物再攻擊。"},{"en":"If predators hunt in a pack, their prey has fewer chances to escape.","zh":"如果掠食者成群狩獵，獵物逃脫機會較少。"},{"en":"This phrase shows danger from a group, not a single animal.","zh":"這個片語顯示來自群體而不是單一動物的危險。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":6},{"front":"a display of cruelty and barbarity","meaning":"殘忍和野蠻的展示","examples":[{"en":"The attack was described as a display of cruelty and barbarity.","zh":"這次攻擊被描述為殘忍和野蠻的展示。"},{"en":"A display of cruelty and barbarity is an act that visibly shows harshness, violence, and lack of mercy.","zh":"a display of cruelty and barbarity 是明顯展現嚴酷、暴力和無情的行為。"},{"en":"A violent bullying video may be seen as a display of cruelty and barbarity.","zh":"暴力欺凌影片可能被視為殘忍和野蠻的展示。"},{"en":"If nature is shown this way, the writer challenges the idea that nature is always gentle.","zh":"如果自然以這種方式呈現，作者便挑戰自然總是溫和的想法。"},{"en":"This phrase is very strong and morally charged.","zh":"這個片語非常強烈，帶有道德評判。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":6},{"front":"make someone think twice","meaning":"令某人三思","examples":[{"en":"The scene would make vegetarians think twice about nature.","zh":"這個場景會令素食者對自然三思。"},{"en":"To make someone think twice means to make them reconsider an opinion or decision carefully.","zh":"make someone think twice 指令某人仔細重新考慮某個看法或決定。"},{"en":"A high repair bill may make a driver think twice about buying an old car.","zh":"高昂維修費可能令司機三思是否購買舊車。"},{"en":"If a documentary shows natural cruelty, viewers may rethink simple beliefs about the wild.","zh":"如果紀錄片展示自然界殘酷，觀眾可能重新思考對野外的簡單信念。"},{"en":"This phrase suggests doubt after new information.","zh":"這個片語暗示因新資訊而產生懷疑。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":6},{"front":"intone the mantra that","meaning":"反覆念誦……的口號","examples":[{"en":"The writer criticises people who intone the mantra that nature is good.","zh":"作者批評那些反覆念誦「大自然是美好的」這句口號的人。"},{"en":"To intone the mantra that something is true means to repeat a belief solemnly or mechanically as if it cannot be questioned.","zh":"intone the mantra that something is true 指莊重或機械地重複某種信念，彷彿它不可質疑。"},{"en":"A manager may intone the mantra that hard work always succeeds, even when resources are unfair.","zh":"經理可能反覆念誦努力工作必然成功這句口號，即使資源不公平。"},{"en":"If people repeat a slogan without evidence, it may stop real discussion.","zh":"如果人們不靠證據反覆重複口號，可能阻礙真正討論。"},{"en":"This phrase is critical and suggests empty repetition.","zh":"這個片語帶批評意味，暗示空洞重複。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":6},{"front":"nature is good","meaning":"大自然是美好的","examples":[{"en":"The phrase “nature is good” is questioned by the writer.","zh":"作者質疑「大自然是美好的」這句話。"},{"en":"Nature is good means the natural world is assumed to be pure, kind, or morally better than human systems.","zh":"nature is good 指人們假定自然世界純潔、仁慈或在道德上比人類制度更好。"},{"en":"A child may think nature is good after seeing flowers, but a documentary about predators gives another picture.","zh":"孩子看見花朵後可能認為大自然是美好的，但關於掠食者的紀錄片給出另一幅畫面。"},{"en":"If people idealise nature, they may overlook disease, hunger, and violent death in the wild.","zh":"如果人們理想化自然，可能忽略野外的疾病、飢餓和暴力死亡。"},{"en":"This phrase is simple, but the passage treats it as too simplistic.","zh":"這個片語很簡單，但文章把它視為過分簡化。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":6},{"front":"viciously torn to pieces","meaning":"被殘忍撕成碎片","examples":[{"en":"Many wild animals are viciously torn to pieces by predators.","zh":"許多野生動物被掠食者殘忍撕成碎片。"},{"en":"Viciously torn to pieces means violently ripped apart in a cruel or savage way.","zh":"viciously torn to pieces 指以殘酷或野蠻方式被暴力撕裂。"},{"en":"A newspaper might describe a toy as torn to pieces after a dog destroys it completely.","zh":"如果狗把玩具徹底咬爛，報紙可能形容它被撕成碎片。"},{"en":"If prey animals are torn apart by predators, their deaths are far from peaceful.","zh":"如果獵物被掠食者撕裂，其死亡絕不平靜。"},{"en":"This phrase is graphic and emotionally intense.","zh":"這個片語畫面感強，情緒強烈。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":6},{"front":"snapping jaws","meaning":"猛咬的顎","examples":[{"en":"Wild animals may be killed by snapping jaws.","zh":"野生動物可能被猛咬的顎殺死。"},{"en":"Snapping jaws are jaws that bite suddenly and forcefully.","zh":"snapping jaws 是突然且有力咬合的顎。"},{"en":"A crocodile’s snapping jaws can close quickly on fish or birds.","zh":"鱷魚猛咬的顎可以迅速咬住魚或鳥。"},{"en":"If an animal is caught in snapping jaws, escape may be impossible.","zh":"如果動物被猛咬的顎抓住，逃脫可能不可能。"},{"en":"This phrase creates a vivid image of violent predation.","zh":"這個片語創造暴力捕食的鮮明畫面。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":6},{"front":"more or less","meaning":"差不多；大致上","examples":[{"en":"Being killed by predators is more or less inevitable for many wild animals.","zh":"對許多野生動物而言，被掠食者殺死差不多是不可避免的。"},{"en":"More or less means almost, approximately, or generally true with small exceptions.","zh":"more or less 指幾乎、大約或大致上成立，但可能有小例外。"},{"en":"The classroom is more or less ready, although a few chairs are still missing.","zh":"課室大致上準備好了，雖然仍少了幾張椅子。"},{"en":"If a weak animal cannot run, capture may be more or less certain.","zh":"如果弱小動物不能奔跑，被捕獲可能差不多是確定的。"},{"en":"This phrase softens a statement without changing its main meaning.","zh":"這個片語柔化說法，但不改變主要意思。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":6},{"front":"the inevitable end of","meaning":"……不可避免的結局","examples":[{"en":"A violent death is the inevitable end of many animals in the wild.","zh":"暴力死亡是許多野生動物不可避免的結局。"},{"en":"The inevitable end of something is the final result that cannot easily be avoided.","zh":"the inevitable end of something 指難以避免的最終結果。"},{"en":"If a student never sleeps and never revises, failure may become the inevitable end of the term.","zh":"如果學生從不睡覺也不溫習，失敗可能成為學期不可避免的結局。"},{"en":"If wild animals are old, weak, or injured, predation may become unavoidable.","zh":"如果野生動物年老、虛弱或受傷，被捕食可能變得無法避免。"},{"en":"This phrase stresses that a result is expected and hard to escape.","zh":"這個片語強調結果是預期中且難以逃避的。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":7},{"front":"expire peacefully","meaning":"平靜死去","examples":[{"en":"Most animals in the wild do not expire peacefully.","zh":"大多數野生動物並不會平靜死去。"},{"en":"To expire peacefully means to die calmly and without violence or severe distress.","zh":"expire peacefully 指平靜地、沒有暴力或嚴重痛苦地死去。"},{"en":"A very old pet may expire peacefully in its sleep after a long life.","zh":"一隻很老的寵物可能在漫長生命後於睡夢中平靜死去。"},{"en":"If animals are hunted or starve, they do not die in a gentle way.","zh":"如果動物被獵捕或餓死，牠們並不是以溫和方式死亡。"},{"en":"This phrase is formal and softer than simply saying die.","zh":"這個片語較正式，比 simply saying die 更委婉。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":7},{"front":"brutalising and painful exits","meaning":"殘酷而痛苦的死亡","examples":[{"en":"Wild animals often face brutalising and painful exits.","zh":"野生動物常面對殘酷而痛苦的死亡。"},{"en":"Brutalising and painful exits are harsh, violent, and suffering-filled deaths.","zh":"brutalising and painful exits 是嚴酷、暴力且充滿痛苦的死亡。"},{"en":"A writer may use this phrase to make readers imagine how frightening an animal’s final moments are.","zh":"作者可能使用這個片語，令讀者想像動物最後時刻有多可怕。"},{"en":"If death comes through hunger, injury, or predators, it may be painful rather than peaceful.","zh":"如果死亡來自飢餓、受傷或掠食者，它可能是痛苦而非平靜的。"},{"en":"This phrase uses “exits” as a metaphor for death.","zh":"這個片語用 “exits” 作死亡的比喻。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":7},{"front":"become another animal’s dinner","meaning":"成為另一隻動物的食物","examples":[{"en":"A weak animal may become another animal’s dinner.","zh":"虛弱動物可能成為另一隻動物的食物。"},{"en":"To become another animal’s dinner means to be killed and eaten by a predator.","zh":"become another animal’s dinner 指被掠食者殺死並吃掉。"},{"en":"A small fish may become another animal’s dinner if it swims too close to a bird.","zh":"如果小魚游得太靠近鳥，可能成為另一隻動物的食物。"},{"en":"If an animal is injured, its chance of becoming prey increases.","zh":"如果動物受傷，成為獵物的機會會增加。"},{"en":"This phrase is informal and darkly humorous.","zh":"這個片語較口語，帶黑色幽默。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":7},{"front":"starve to death","meaning":"餓死","examples":[{"en":"Some animals starve to death in the wild.","zh":"一些動物在野外餓死。"},{"en":"To starve to death means to die because there is not enough food.","zh":"starve to death 指因沒有足夠食物而死亡。"},{"en":"A neglected pet could starve to death if no one feeds it for many days.","zh":"如果被忽視的寵物很多天沒有人餵食，可能餓死。"},{"en":"If drought destroys grass, herbivores may starve and predators may suffer too.","zh":"如果旱災摧毀草地，草食動物可能餓死，掠食者也可能受苦。"},{"en":"This phrase describes a slow and painful kind of death.","zh":"這個片語描述緩慢而痛苦的死亡。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":7},{"front":"victims of floods and droughts","meaning":"洪水和旱災的受害者","examples":[{"en":"Wild animals may become victims of floods and droughts.","zh":"野生動物可能成為洪水和旱災的受害者。"},{"en":"Victims of floods and droughts are living things harmed or killed by too much water or too little water.","zh":"victims of floods and droughts 是因水太多或水太少而受傷害或死亡的生物。"},{"en":"Farmers can become victims of droughts when crops fail and wells dry up.","zh":"當農作物失收、水井乾涸，農民可以成為旱災受害者。"},{"en":"If floods destroy nests or droughts remove drinking water, animals may die or move away.","zh":"如果洪水摧毀鳥巢，或旱災移除飲水來源，動物可能死亡或遷走。"},{"en":"This phrase shows that nature itself can be dangerous.","zh":"這個片語顯示自然本身也可以危險。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":7},{"front":"merciless acts of nature","meaning":"無情的大自然行為","examples":[{"en":"Floods and droughts are described as merciless acts of nature.","zh":"洪水和旱災被描述為無情的大自然行為。"},{"en":"Merciless acts of nature are natural events that cause suffering without pity or fairness.","zh":"merciless acts of nature 是造成痛苦而沒有憐憫或公平可言的自然事件。"},{"en":"A typhoon that destroys homes can feel like a merciless act of nature.","zh":"摧毀家園的颱風可能感覺像無情的大自然行為。"},{"en":"If animals die from drought, the suffering is not caused by humans but is still severe.","zh":"如果動物因旱災死亡，痛苦不是由人類造成，但仍然嚴重。"},{"en":"This phrase presents nature as harsh rather than gentle.","zh":"這個片語把自然呈現為嚴酷，而非溫和。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":7},{"front":"compared to this","meaning":"與此相比","examples":[{"en":"Compared to this, slaughter by humans is described as relatively quick.","zh":"與此相比，人類屠宰被描述為相對快速。"},{"en":"Compared to this means when this situation is used as the standard for comparison.","zh":"compared to this 指以這種情況作為比較標準時。"},{"en":"Compared to a three-hour commute, a forty-minute journey feels short.","zh":"與三小時通勤相比，四十分鐘車程感覺很短。"},{"en":"If wild deaths are slow and violent, slaughter may be presented as less cruel by comparison.","zh":"如果野外死亡緩慢而暴力，屠宰在比較下可能被呈現為較不殘忍。"},{"en":"This phrase introduces a judgement based on contrast.","zh":"這個片語引入基於對比的判斷。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":7},{"front":"relatively quick and clean","meaning":"相對快速而乾淨的","examples":[{"en":"The writer describes slaughter by humans as relatively quick and clean.","zh":"作者把人類屠宰描述為相對快速而乾淨。"},{"en":"Relatively quick and clean means faster and less messy or painful compared with another situation.","zh":"relatively quick and clean 指與另一情況相比更快、較少混亂或痛苦。"},{"en":"A modern medical test may be relatively quick and clean compared with older procedures.","zh":"與舊程序相比，現代醫療測試可能相對快速而乾淨。"},{"en":"If the alternative is a slow death in the wild, the writer argues that slaughter may seem less brutal.","zh":"如果替代情況是在野外慢慢死亡，作者便主張屠宰可能顯得較不殘酷。"},{"en":"This phrase depends on comparison, not absolute approval.","zh":"這個片語取決於比較，而不是絕對認同。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":7},{"front":"deliver to","meaning":"給予；施加於","examples":[{"en":"The writer says humans deliver a quick death to farm animals.","zh":"作者說人類給予農場動物快速死亡。"},{"en":"To deliver something to someone means to give, provide, or bring it to them.","zh":"deliver something to someone 指把某物給予、提供或帶給某人。"},{"en":"A nurse may deliver medicine to patients at the correct time.","zh":"護士可能在正確時間把藥送給病人。"},{"en":"If a system delivers a result quickly, people may compare it with slower alternatives.","zh":"如果系統快速造成某結果，人們可能把它與較慢替代方案比較。"},{"en":"This phrase can describe giving something physical or causing a result.","zh":"這個片語可以描述給予實物，也可以描述造成結果。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":7},{"front":"cud-chewing cousins","meaning":"反芻的動物親戚；指牛羊","examples":[{"en":"The writer humorously calls sheep and cattle our cud-chewing cousins.","zh":"作者幽默地稱羊和牛為我們反芻的動物親戚。"},{"en":"Cud-chewing cousins is a joking phrase for ruminant farm animals such as sheep and cattle.","zh":"cud-chewing cousins 是對羊和牛等反芻家畜的玩笑說法。"},{"en":"A farmer may watch cows chewing cud slowly after feeding.","zh":"農夫可能看着牛吃完後慢慢反芻。"},{"en":"If a writer calls animals cousins, the tone becomes playful and familiar.","zh":"如果作者把動物稱為親戚，語氣會變得俏皮而熟悉。"},{"en":"This phrase is humorous and should not be taken literally.","zh":"這個片語帶幽默意味，不應按字面理解。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":7},{"front":"a privileged way to go","meaning":"較優待的死亡方式","examples":[{"en":"The writer argues that a quick death is a privileged way to go.","zh":"作者主張快速死亡是一種較優待的死亡方式。"},{"en":"A privileged way to go means a comparatively fortunate or less painful way to die.","zh":"a privileged way to go 指相比之下較幸運或較少痛苦的死亡方式。"},{"en":"A peaceful death at home may be seen as a privileged way to go compared with a violent accident.","zh":"與暴力意外相比，在家平靜死亡可能被視為較優待的死亡方式。"},{"en":"If wild animals often die painfully, the writer claims farm animals receive a better ending.","zh":"如果野生動物常痛苦死亡，作者便聲稱農場動物得到較好結局。"},{"en":"This phrase is provocative because it discusses death as if some forms are more fortunate.","zh":"這個片語具挑釁性，因為它把死亡方式分成較幸運與否。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":8},{"front":"at least","meaning":"至少","examples":[{"en":"Eating meat is not cruel, at least compared with the natural world.","zh":"吃肉並不殘忍，至少與自然世界相比是如此。"},{"en":"At least means something is true in a limited way, even if not completely true.","zh":"at least 指某事在有限意義上成立，即使不完全成立。"},{"en":"The room is not perfect, but at least it is clean and quiet.","zh":"房間並不完美，但至少乾淨安靜。"},{"en":"If one argument is weak, the writer may still claim it works under certain comparisons.","zh":"如果某論點薄弱，作者仍可能聲稱它在某些比較下成立。"},{"en":"This phrase limits a statement and makes it more cautious.","zh":"這個片語限制說法，使其更謹慎。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":8},{"front":"the natural world","meaning":"自然世界","examples":[{"en":"The writer compares farm life with the natural world.","zh":"作者把農場生活與自然世界比較。"},{"en":"The natural world means the world of plants, animals, weather, landscapes, and ecosystems outside human-made systems.","zh":"natural world 指人造系統以外，由植物、動物、天氣、地貌和生態系統組成的世界。"},{"en":"Children learn about the natural world by observing insects, trees, clouds, and birds.","zh":"孩子透過觀察昆蟲、樹木、雲和鳥類學習自然世界。"},{"en":"If people romanticise the natural world, they may forget that animals face hunger and predation.","zh":"如果人們浪漫化自然世界，可能忘記動物面對飢餓和捕食。"},{"en":"This phrase refers to nature broadly, not only beautiful scenery.","zh":"這個片語廣泛指自然，而不只是美麗風景。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":8},{"front":"in fact","meaning":"事實上","examples":[{"en":"In fact, the writer argues that farm animals may enjoy some quality of life.","zh":"事實上，作者主張農場動物可能享有某程度的生活質素。"},{"en":"In fact introduces a point that strengthens, corrects, or contrasts with what came before.","zh":"in fact 引入一個加強、修正或對比前文的重點。"},{"en":"Many students think grammar is only rules; in fact, it helps meaning become clearer.","zh":"許多學生以為文法只是規則；事實上，它幫助意思變得更清晰。"},{"en":"If a writer says “in fact,” they often want to surprise or correct the reader.","zh":"如果作者說 in fact，他們常想令讀者意外或修正讀者想法。"},{"en":"This phrase adds emphasis to the next statement.","zh":"這個片語加強下一個陳述。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":8},{"front":"the animals in question","meaning":"所談及的動物","examples":[{"en":"The animals in question are those raised for food.","zh":"所談及的動物是那些被飼養作食物的動物。"},{"en":"The animals in question means the specific animals being discussed.","zh":"the animals in question 指正在被討論的特定動物。"},{"en":"In a school complaint, the student in question is the student involved in that case.","zh":"在學校投訴中，所談及的學生就是涉及該個案的學生。"},{"en":"If we talk about farm animals, the animals in question are not wild lions or birds.","zh":"如果我們談論農場動物，所談及的動物就不是野生獅子或鳥類。"},{"en":"This phrase helps narrow the topic clearly.","zh":"這個片語幫助清楚收窄話題。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":8},{"front":"a certain quality of life","meaning":"某程度的生活質素","examples":[{"en":"Farm animals may have a certain quality of life.","zh":"農場動物可能有某程度的生活質素。"},{"en":"A certain quality of life means some level of comfort, safety, health, or well-being.","zh":"a certain quality of life 指某種程度的舒適、安全、健康或幸福。"},{"en":"An elderly person may still have a certain quality of life if they have care, company, and freedom.","zh":"如果老人有照顧、陪伴和自由，仍可能有某程度的生活質素。"},{"en":"If animals are fed, sheltered, and treated when sick, the writer argues their lives are not pure misery.","zh":"如果動物有食物、庇護並在生病時得到治療，作者便主張牠們的生活不是純粹痛苦。"},{"en":"This phrase is cautious because it does not claim perfect happiness.","zh":"這個片語較謹慎，因為它沒有聲稱完美快樂。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":8},{"front":"almost certainly never","meaning":"幾乎肯定永遠不會","examples":[{"en":"Wild animals would almost certainly never enjoy such an easy life.","zh":"野生動物幾乎肯定永遠不會享有如此安逸的生活。"},{"en":"Almost certainly never means very probably not at any time.","zh":"almost certainly never 指在任何時候都非常可能不會。"},{"en":"A student who never practises will almost certainly never become fluent by watching videos alone.","zh":"從不練習的學生幾乎肯定永遠不會單靠看影片變得流利。"},{"en":"If wild animals face predators, disease, and hunger, they are very unlikely to live completely comfortably.","zh":"如果野生動物面對掠食者、疾病和飢餓，牠們非常不可能生活得完全舒適。"},{"en":"This phrase expresses strong probability, not mathematical certainty.","zh":"這個片語表達強烈可能性，而不是數學上的確定。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":8},{"front":"the human species","meaning":"人類物種","examples":[{"en":"The human species has developed a higher awareness.","zh":"人類物種已發展出較高覺悟。"},{"en":"The human species means human beings considered as one type of living organism.","zh":"human species 指被視為一種生物的人類整體。"},{"en":"The human species depends on food, water, shelter, and social cooperation to survive.","zh":"人類物種依靠食物、水、庇護和社會合作生存。"},{"en":"If the human species has moral awareness, people may feel responsible for their choices.","zh":"如果人類物種有道德覺悟，人們可能對自己的選擇感到有責任。"},{"en":"This phrase sounds scientific and refers to humans collectively.","zh":"這個片語聽起來較科學，指人類整體。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":8},{"front":"have a higher awareness","meaning":"有較高覺悟","examples":[{"en":"Vegetarians argue that humans have a higher awareness.","zh":"素食者主張人類有較高覺悟。"},{"en":"To have a higher awareness means to possess greater understanding, moral judgement, or consciousness.","zh":"have a higher awareness 指擁有更高理解、道德判斷或意識。"},{"en":"Older students may have a higher awareness of how their words affect younger classmates.","zh":"高年級學生可能更清楚自己的說話如何影響低年級同學。"},{"en":"If humans have higher awareness, critics argue they should make more ethical food choices.","zh":"如果人類有較高覺悟，批評者便主張他們應作出更合乎倫理的飲食選擇。"},{"en":"This phrase links intelligence or consciousness with responsibility.","zh":"這個片語把智慧或意識與責任連接起來。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":8},{"front":"avail ourselves of","meaning":"利用；使用","examples":[{"en":"Humans can avail ourselves of other forms of food.","zh":"人類可以利用其他形式的食物。"},{"en":"To avail ourselves of something means to use or take advantage of it.","zh":"avail ourselves of something 指使用或利用某物。"},{"en":"Students should avail themselves of library resources before writing research essays.","zh":"學生寫研究文章前應善用圖書館資源。"},{"en":"If people can use plant-based nutrition, critics may say they do not need meat.","zh":"如果人們可以使用植物性營養，批評者可能說他們不需要肉。"},{"en":"This phrase is formal and means make use of.","zh":"這個片語較正式，意思是利用。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":8},{"front":"other forms of food","meaning":"其他形式的食物","examples":[{"en":"Some people argue that humans should choose other forms of food.","zh":"一些人主張人類應選擇其他形式的食物。"},{"en":"Other forms of food means food choices different from the one being discussed.","zh":"other forms of food 指不同於正在討論食物的其他食物選擇。"},{"en":"A person who avoids dairy may choose other forms of food, such as soy milk or nuts.","zh":"避免乳製品的人可能選擇其他形式的食物，例如豆奶或堅果。"},{"en":"If meat is unavailable or rejected, people may depend on grains, beans, vegetables, and fruit.","zh":"如果肉類不可得或被拒絕，人們可能依賴穀物、豆類、蔬菜和水果。"},{"en":"This phrase introduces alternatives in diet.","zh":"這個片語引入飲食上的替代選擇。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":8},{"front":"rather than","meaning":"而不是","examples":[{"en":"Humans can choose plant-based food rather than causing animal deaths.","zh":"人類可以選擇植物性食物，而不是造成動物死亡。"},{"en":"Rather than means instead of one thing, another thing is chosen or emphasised.","zh":"rather than 指不是選擇或強調某事，而是另一事。"},{"en":"A student may revise mistakes rather than simply reread notes.","zh":"學生可以複習錯誤，而不是只是重讀筆記。"},{"en":"If people choose beans rather than beef, they avoid one form of animal killing.","zh":"如果人們選擇豆類而不是牛肉，就避免了一種動物殺戮。"},{"en":"This phrase clearly contrasts two choices.","zh":"這個片語清楚對比兩個選擇。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":9},{"front":"living creatures","meaning":"生物","examples":[{"en":"Vegetarians object to causing the deaths of living creatures.","zh":"素食者反對造成生物死亡。"},{"en":"Living creatures are animals, plants, or organisms that are alive.","zh":"living creatures 是活着的動物、植物或生物體。"},{"en":"Children learn to respect living creatures when they care for classroom plants or pets.","zh":"孩子照顧課室植物或寵物時，會學習尊重生物。"},{"en":"If an action harms living creatures unnecessarily, people may object on moral grounds.","zh":"如果某行動不必要地傷害生物，人們可能基於道德理由反對。"},{"en":"This phrase is broad and emotionally warmer than organisms.","zh":"這個片語範圍廣，情感上比 organisms 較溫暖。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":9},{"front":"it is worth realising that","meaning":"值得意識到","examples":[{"en":"It is worth realising that humans did not always have a choice.","zh":"值得意識到，人類並非一直都有選擇。"},{"en":"It is worth realising that means people should notice or understand an important point.","zh":"it is worth realising that 指人們應注意或理解某個重要重點。"},{"en":"It is worth realising that not every student has a quiet place to study.","zh":"值得意識到，不是每個學生都有安靜地方溫習。"},{"en":"If we judge past behaviour, we should consider the limits people faced at the time.","zh":"如果我們評判過去行為，應考慮當時人們面對的限制。"},{"en":"This phrase introduces a point that may change how readers judge the issue.","zh":"這個片語引入可能改變讀者判斷的重點。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":9},{"front":"tens of thousands of years","meaning":"數萬年","examples":[{"en":"For tens of thousands of years, humans relied on animals for food.","zh":"數萬年來，人類依靠動物作食物。"},{"en":"Tens of thousands of years means many periods of ten thousand years, an extremely long time.","zh":"tens of thousands of years 指許多個一萬年，是極長時間。"},{"en":"Human tools and diets have changed over tens of thousands of years.","zh":"人類工具和飲食在數萬年間改變。"},{"en":"If a practice existed for tens of thousands of years, it may have deep survival roots.","zh":"如果某做法存在了數萬年，它可能有深厚生存根源。"},{"en":"This phrase gives a very long historical scale.","zh":"這個片語給出非常長的歷史尺度。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":9},{"front":"the luxury of choice","meaning":"選擇的奢侈","examples":[{"en":"Many earlier humans did not have the luxury of choice.","zh":"許多早期人類沒有選擇的奢侈。"},{"en":"The luxury of choice means the fortunate ability to choose among different options.","zh":"luxury of choice 指能在不同選項之間選擇的幸運能力。"},{"en":"A student with many university offers has the luxury of choice.","zh":"擁有許多大學取錄的學生享有選擇的奢侈。"},{"en":"If food is scarce, people may eat what is available rather than what is ethically ideal.","zh":"如果食物稀缺，人們可能吃可得到的東西，而不是倫理上理想的東西。"},{"en":"This phrase suggests that choice depends on wealth, safety, or resources.","zh":"這個片語暗示選擇取決於財富、安全或資源。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":9},{"front":"essential to staying alive","meaning":"對維持生命至關重要","examples":[{"en":"Killing animals was once essential to staying alive.","zh":"殺死動物曾經對維持生命至關重要。"},{"en":"Essential to staying alive means necessary for survival.","zh":"essential to staying alive 指對生存而言必要。"},{"en":"Clean water is essential to staying alive, especially after a natural disaster.","zh":"清潔食水對維持生命至關重要，尤其是在自然災害後。"},{"en":"If people lived where crops failed, hunting animals may have been necessary for survival.","zh":"如果人們生活在農作物失收的地方，捕獵動物可能是生存所必需。"},{"en":"This phrase describes something as a basic life-or-death need.","zh":"這個片語把某事描述為基本生死需要。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":9},{"front":"in terms of human history","meaning":"就人類歷史而言","examples":[{"en":"In terms of human history, vegetarian abundance is a recent development.","zh":"就人類歷史而言，素食食物充足是近期發展。"},{"en":"In terms of human history means when judged against the long timeline of human existence.","zh":"in terms of human history 指以人類存在的漫長時間線來判斷。"},{"en":"In terms of human history, smartphones are extremely new.","zh":"就人類歷史而言，智能電話非常新。"},{"en":"If we look over thousands of years, modern food choice is a recent luxury.","zh":"如果我們放眼數千年，現代食物選擇是近期奢侈。"},{"en":"This phrase sets an issue inside a broad historical perspective.","zh":"這個片語把議題放入廣闊歷史角度。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":9},{"front":"reach a stage of affluence","meaning":"達到富裕階段","examples":[{"en":"Some societies have reached a stage of affluence.","zh":"一些社會已達到富裕階段。"},{"en":"To reach a stage of affluence means to become wealthy enough to have many choices and comforts.","zh":"reach a stage of affluence 指變得足夠富裕，可以擁有許多選擇和舒適。"},{"en":"A family reaches a stage of affluence when it can afford not only food but also travel and private lessons.","zh":"當家庭不只負擔得起食物，也能負擔旅行和私人課程，就達到某種富裕階段。"},{"en":"If a society becomes affluent, people may start judging diet as a moral choice rather than a survival need.","zh":"如果社會變得富裕，人們可能開始把飲食判斷為道德選擇，而不是生存需要。"},{"en":"This phrase connects wealth with expanded options.","zh":"這個片語把財富與擴大的選項連接起來。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":9},{"front":"whereby","meaning":"藉此；在這情況下","examples":[{"en":"Society has reached a stage whereby non-animal nutrition can be obtained.","zh":"社會已達到一個階段，在這情況下非動物性營養可以獲得。"},{"en":"Whereby means by which or in which situation something happens.","zh":"whereby 指藉此或在某情況下某事發生。"},{"en":"A school may create a system whereby students get feedback within one week.","zh":"學校可能建立一個制度，藉此學生在一星期內得到回饋。"},{"en":"If a country has enough wealth and transport, people may access many kinds of food.","zh":"如果國家有足夠財富和交通，人們便可能取得多種食物。"},{"en":"This word is formal and links a condition with a result.","zh":"這個詞較正式，把條件與結果連接起來。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":9},{"front":"a sufficient quantity of","meaning":"足夠數量的","examples":[{"en":"Only some people can obtain a sufficient quantity of non-animal nutrition.","zh":"只有一些人能取得足夠數量的非動物性營養。"},{"en":"A sufficient quantity of something means enough of it for a particular need.","zh":"sufficient quantity of something 指足以滿足某特定需要的數量。"},{"en":"A student needs a sufficient quantity of sleep before an important exam.","zh":"學生在重要考試前需要足夠睡眠。"},{"en":"If people cannot get enough nutritious food, diet choice becomes a question of survival.","zh":"如果人們無法取得足夠有營養食物，飲食選擇便成為生存問題。"},{"en":"This phrase focuses on having enough amount, not just having some.","zh":"這個片語聚焦於數量足夠，而不只是有一些。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":9},{"front":"non-animal nutrition","meaning":"非動物性營養","examples":[{"en":"Non-animal nutrition is not equally available everywhere.","zh":"非動物性營養並非在各地都同樣可得。"},{"en":"Non-animal nutrition means nutrients obtained from plants, grains, beans, nuts, or other non-animal sources.","zh":"non-animal nutrition 指從植物、穀物、豆類、堅果或其他非動物來源取得的營養。"},{"en":"A vegetarian meal with beans, rice, vegetables, and nuts can provide non-animal nutrition.","zh":"有豆類、米飯、蔬菜和堅果的素食餐可以提供非動物性營養。"},{"en":"If non-animal nutrition is expensive or scarce, not everyone can avoid meat easily.","zh":"如果非動物性營養昂貴或稀缺，不是每個人都能輕易避免吃肉。"},{"en":"This phrase refers to nutrition, not only personal preference.","zh":"這個片語指營養，而不只是個人偏好。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":9},{"front":"can be obtained","meaning":"可以獲得","examples":[{"en":"Sufficient non-animal nutrition can be obtained only by some people.","zh":"足夠的非動物性營養只有一些人可以獲得。"},{"en":"Can be obtained means can be got, found, bought, or acquired.","zh":"can be obtained 指可以得到、找到、購買或取得。"},{"en":"Clean drinking water can be obtained from a public fountain in some cities.","zh":"在一些城市，清潔飲用水可以從公共飲水機獲得。"},{"en":"If a food cannot be obtained locally, people may depend on what is available.","zh":"如果某食物不能在本地獲得，人們可能依賴可得到的東西。"},{"en":"This phrase focuses on access.","zh":"這個片語聚焦於取得途徑。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":10},{"front":"a privileged percentage of","meaning":"享有特權的一小部分","examples":[{"en":"Only a privileged percentage of the world’s population has this choice.","zh":"只有世界人口中享有特權的一小部分擁有這種選擇。"},{"en":"A privileged percentage of a group means a relatively small part with more advantages or resources than others.","zh":"privileged percentage of a group 指某群體中擁有比其他人更多優勢或資源的相對小部分。"},{"en":"Only a privileged percentage of students can afford private tutors every day.","zh":"只有享有特權的一小部分學生能負擔每天私人補習。"},{"en":"If only wealthy people can choose a special diet, moral judgement becomes more complicated.","zh":"如果只有富裕人士能選擇特殊飲食，道德判斷就變得更複雜。"},{"en":"This phrase highlights inequality in access.","zh":"這個片語突出取得途徑上的不平等。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":10},{"front":"moral high ground","meaning":"道德高地","examples":[{"en":"The writer questions the argument from moral high ground.","zh":"作者質疑來自道德高地的論點。"},{"en":"Moral high ground is the position of seeming more ethical or morally right than others.","zh":"moral high ground 是看似比他人更合乎倫理或道德正確的位置。"},{"en":"A person may claim the moral high ground by saying they recycle while others do not.","zh":"一個人可能透過說自己回收而別人沒有，聲稱佔據道德高地。"},{"en":"If someone uses moral high ground too aggressively, others may feel judged rather than persuaded.","zh":"如果某人過度強硬地使用道德高地，其他人可能感到被評判，而不是被說服。"},{"en":"This phrase often appears in debates about values and behaviour.","zh":"這個片語常見於關於價值和行為的辯論。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":10},{"front":"at best","meaning":"充其量","examples":[{"en":"The moral argument is, at best, arbitrary.","zh":"這個道德論點充其量是武斷的。"},{"en":"At best means even in the most favourable interpretation.","zh":"at best 指即使在最有利的解讀下。"},{"en":"The plan is, at best, incomplete because it ignores cost and time.","zh":"這個計劃充其量是不完整的，因為它忽視成本和時間。"},{"en":"If an argument works only under generous assumptions, the writer may say it is weak at best.","zh":"如果一個論點只在寬鬆假設下成立，作者可能說它充其量也很弱。"},{"en":"This phrase often introduces a critical judgement.","zh":"這個片語常引入批判性判斷。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":10},{"front":"an arbitrary one","meaning":"武斷的說法","examples":[{"en":"The writer calls the moral argument an arbitrary one.","zh":"作者稱這個道德論點為武斷的說法。"},{"en":"An arbitrary one means a judgement or rule based on personal choice rather than clear reason.","zh":"arbitrary one 指基於個人選擇而非清楚理由的判斷或規則。"},{"en":"A school rule banning blue pens but allowing black pens may seem arbitrary if no reason is given.","zh":"如果學校禁止藍筆但允許黑筆，卻沒有給原因，這條規則可能顯得武斷。"},{"en":"If a moral line is drawn without consistent logic, critics may call it arbitrary.","zh":"如果道德界線沒有一致邏輯地劃出，批評者可能稱其武斷。"},{"en":"This phrase questions the fairness or reasoning behind a claim.","zh":"這個片語質疑某主張背後的公平性或推理。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":10},{"front":"come out with","meaning":"提出；說出","examples":[{"en":"The vegetarians then come out with another claim.","zh":"素食者接着提出另一個主張。"},{"en":"To come out with something means to say or present it, often suddenly or boldly.","zh":"come out with something 指說出或提出某事，常帶突然或大膽意味。"},{"en":"A student may come out with a surprising answer that changes the discussion.","zh":"學生可能突然說出一個令人意外的答案，改變討論。"},{"en":"If someone comes out with a strong claim, others may ask for evidence.","zh":"如果某人提出強烈主張，其他人可能要求證據。"},{"en":"This phrase is informal and can sound slightly critical.","zh":"這個片語較口語，可能略帶批評意味。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":10},{"front":"core claim to superiority","meaning":"聲稱優越的核心主張","examples":[{"en":"Their next core claim to superiority is that their diet is healthier.","zh":"他們下一個聲稱優越的核心主張是其飲食更健康。"},{"en":"A core claim to superiority is the main reason someone gives for saying one group or choice is better.","zh":"core claim to superiority 是某人用來說一個群體或選擇更好的主要理由。"},{"en":"A school’s core claim to superiority may be that its students receive more individual support.","zh":"學校聲稱優越的核心主張可能是學生得到更多個別支援。"},{"en":"If a diet’s main claim is better health, statistics must support that claim fairly.","zh":"如果某種飲食的主要主張是更健康，統計數據必須公平支持該主張。"},{"en":"This phrase identifies the central argument behind a feeling of being better.","zh":"這個片語指出優越感背後的核心論點。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":10},{"front":"nasty consequences for","meaning":"對……有惡劣後果","examples":[{"en":"Too much meat may have nasty consequences for the body.","zh":"吃太多肉可能對身體有惡劣後果。"},{"en":"Nasty consequences for something are unpleasant or harmful results affecting it.","zh":"nasty consequences for something 是影響某物的不愉快或有害結果。"},{"en":"Too little sleep can have nasty consequences for memory, mood, and concentration.","zh":"睡眠太少可以對記憶、心情和專注力有惡劣後果。"},{"en":"If a person eats too much processed food, their health may suffer over time.","zh":"如果一個人吃太多加工食品，其健康可能隨時間受損。"},{"en":"This phrase warns that an action can lead to serious negative effects.","zh":"這個片語警告某行動可能帶來嚴重負面影響。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":10},{"front":"immune system","meaning":"免疫系統","examples":[{"en":"The immune system protects the body from illness.","zh":"免疫系統保護身體免受疾病侵害。"},{"en":"The immune system is the body’s defence system against infections and disease.","zh":"immune system 是身體對抗感染和疾病的防禦系統。"},{"en":"Sleep, nutrition, and hygiene can affect how well the immune system works.","zh":"睡眠、營養和衞生可以影響免疫系統運作得好不好。"},{"en":"If the immune system is weak, a person may get sick more easily.","zh":"如果免疫系統較弱，人可能較容易生病。"},{"en":"This phrase is common in health discussions.","zh":"這個片語常見於健康討論。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":10},{"front":"end up in an early grave","meaning":"早死；早入墳墓","examples":[{"en":"The writer questions the claim that meat-eaters will end up in an early grave.","zh":"作者質疑肉食者會早死這種主張。"},{"en":"To end up in an early grave means to die younger than expected, often because of unhealthy habits.","zh":"end up in an early grave 指比預期更年輕時死亡，常因不健康習慣。"},{"en":"A doctor may warn that heavy smoking can send someone to an early grave.","zh":"醫生可能警告重度吸煙會令人早入墳墓。"},{"en":"If a claim says one food choice causes early death, it needs strong evidence.","zh":"如果某主張說一種食物選擇導致早死，它需要有力證據。"},{"en":"This phrase is dramatic and informal.","zh":"這個片語語氣戲劇化且較口語。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":10},{"front":"eat too much meat","meaning":"吃太多肉","examples":[{"en":"Eating too much meat may be unhealthy.","zh":"吃太多肉可能不健康。"},{"en":"To eat too much meat means to consume meat in amounts that may harm health or crowd out other foods.","zh":"eat too much meat 指攝取可能傷害健康或排擠其他食物的過量肉類。"},{"en":"A person who eats meat at every meal may be eating too much meat if vegetables and grains are ignored.","zh":"如果一個人每餐都吃肉，卻忽視蔬菜和穀物，就可能是吃太多肉。"},{"en":"If meat intake is excessive, a balanced diet may become harder to maintain.","zh":"如果肉類攝取過量，維持均衡飲食可能變得更困難。"},{"en":"This phrase criticises excess, not necessarily all meat-eating.","zh":"這個片語批評過量，而不一定批評所有吃肉行為。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":10},{"front":"eat meat in moderation","meaning":"適量吃肉","examples":[{"en":"Some people eat meat in moderation as part of a balanced diet.","zh":"一些人把適量吃肉作為均衡飲食的一部分。"},{"en":"To eat meat in moderation means to eat meat in reasonable, limited amounts.","zh":"eat meat in moderation 指以合理而有限的份量吃肉。"},{"en":"A family may eat meat in moderation by serving small portions with plenty of vegetables.","zh":"家庭可以透過小份肉類配大量蔬菜來適量吃肉。"},{"en":"If people eat meat moderately, health risks may differ from those of heavy meat consumption.","zh":"如果人們適量吃肉，健康風險可能不同於大量吃肉的人。"},{"en":"This phrase suggests balance rather than complete avoidance.","zh":"這個片語暗示平衡，而不是完全避免。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":11},{"front":"as part of","meaning":"作為……的一部分","examples":[{"en":"Meat can be eaten as part of an otherwise balanced diet.","zh":"肉可以作為其他方面均衡飲食的一部分來食用。"},{"en":"As part of means included within a larger whole.","zh":"as part of 指被包括在一個較大整體之中。"},{"en":"Reading aloud can be used as part of a speaking lesson.","zh":"朗讀可以作為口語課的一部分使用。"},{"en":"If meat is only one part of a varied diet, its health effect may differ from an all-meat pattern.","zh":"如果肉只是多樣飲食中的一部分，其健康影響可能不同於全肉飲食模式。"},{"en":"This phrase shows that something belongs within a bigger system.","zh":"這個片語顯示某事屬於更大系統之中。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":11},{"front":"an otherwise balanced diet","meaning":"其他方面均衡的飲食","examples":[{"en":"The writer discusses eating meat as part of an otherwise balanced diet.","zh":"作者討論把吃肉作為其他方面均衡飲食的一部分。"},{"en":"An otherwise balanced diet is a diet that is balanced in other respects, even if one element is being questioned.","zh":"otherwise balanced diet 指即使某一元素被質疑，其他方面仍均衡的飲食。"},{"en":"A person may eat dessert occasionally as part of an otherwise balanced diet.","zh":"一個人可以偶爾吃甜品，作為其他方面均衡飲食的一部分。"},{"en":"If someone eats vegetables, grains, fruit, and moderate protein, one food item may not define the whole diet.","zh":"如果某人吃蔬菜、穀物、水果和適量蛋白質，單一食物不一定定義整體飲食。"},{"en":"This phrase helps avoid judging a diet by one ingredient alone.","zh":"這個片語幫助避免只按一種食材評判飲食。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":11},{"front":"dubious facts and figures","meaning":"可疑的事實和數字","examples":[{"en":"The writer criticises the use of dubious facts and figures.","zh":"作者批評使用可疑的事實和數字。"},{"en":"Dubious facts and figures are statistics or claims that seem doubtful, unreliable, or poorly supported.","zh":"dubious facts and figures 是看似可疑、不可靠或缺乏充分支持的統計或主張。"},{"en":"A social media post with no source may contain dubious facts and figures.","zh":"沒有來源的社交媒體帖文可能包含可疑的事實和數字。"},{"en":"If data are dubious, they can make an argument look scientific without being trustworthy.","zh":"如果數據可疑，它們可以令論點看似科學，但其實不可信。"},{"en":"This phrase warns readers to question numbers.","zh":"這個片語提醒讀者質疑數字。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":11},{"front":"prove someone’s viewpoint","meaning":"證明某人的觀點","examples":[{"en":"Statistics are sometimes used to prove someone’s viewpoint.","zh":"統計數字有時被用來證明某人的觀點。"},{"en":"To prove someone’s viewpoint means to show that their opinion is correct or reasonable.","zh":"prove someone’s viewpoint 指顯示某人的意見正確或合理。"},{"en":"A student may use survey results to prove a viewpoint about school lunches.","zh":"學生可能使用調查結果來證明關於學校午餐的觀點。"},{"en":"If statistics are poorly chosen, they may support a viewpoint unfairly.","zh":"如果統計數字選得不好，它們可能不公平地支持某觀點。"},{"en":"This phrase connects evidence with persuasion.","zh":"這個片語把證據與說服連接起來。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":11},{"front":"recommend a quick read of","meaning":"建議快速讀一下","examples":[{"en":"The writer recommends a quick read of a book about statistics.","zh":"作者建議快速讀一下關於統計的書。"},{"en":"To recommend a quick read of something means to suggest reading it briefly because it is useful.","zh":"recommend a quick read of something 指建議簡短閱讀某物，因為它有用。"},{"en":"A teacher may recommend a quick read of the exam rules before students start.","zh":"老師可能建議學生開始前快速讀一下考試規則。"},{"en":"If people misuse statistics, a basic guide may help them spot weak evidence.","zh":"如果人們誤用統計，基本指南可以幫助他們識別薄弱證據。"},{"en":"This phrase is informal and practical.","zh":"這個片語較口語且實用。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":11},{"front":"entitled","meaning":"名為","examples":[{"en":"The writer mentions a book entitled “How to Lie with Statistics.”","zh":"作者提到一本名為《如何用統計數字說謊》的書。"},{"en":"Entitled means having the title or name.","zh":"entitled 指名為或題為。"},{"en":"A teacher may assign an article entitled “The Future of Work.”","zh":"老師可能指定一篇名為《工作的未來》的文章。"},{"en":"If a book is entitled in a provocative way, readers may remember it more easily.","zh":"如果書名具挑釁性，讀者可能更容易記住它。"},{"en":"This word is used to introduce the title of a book, article, film, or report.","zh":"這個詞用來引入書、文章、電影或報告的標題。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":11},{"front":"How to Lie with Statistics","meaning":"《如何用統計數字說謊》","examples":[{"en":"“How to Lie with Statistics” is cited as a book about misleading numbers.","zh":"《如何用統計數字說謊》被引用為一本關於誤導性數字的書。"},{"en":"How to Lie with Statistics is a title suggesting that numbers can be used to mislead people.","zh":"How to Lie with Statistics 這個書名暗示數字可以被用來誤導人。"},{"en":"A student reading such a book may learn why sample size and hidden variables matter.","zh":"閱讀這類書的學生可能學到為何樣本大小和隱藏變數重要。"},{"en":"If statistics are presented selectively, they can support a false impression.","zh":"如果統計被選擇性呈現，它們可以支持錯誤印象。"},{"en":"This title reminds readers that numbers are not automatically trustworthy.","zh":"這個書名提醒讀者，數字不會自動可信。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":11},{"front":"emphasises","meaning":"強調","examples":[{"en":"The book emphasises two foundations for statistical validity.","zh":"這本書強調統計有效性的兩個基礎。"},{"en":"Emphasises means gives special importance or attention to something.","zh":"emphasises 指特別重視或關注某事。"},{"en":"A teacher emphasises planning because good essays need clear structure.","zh":"老師強調計劃，因為好文章需要清晰結構。"},{"en":"If a report emphasises sample quality, readers should check how the data were collected.","zh":"如果報告強調樣本質素，讀者應檢查數據如何收集。"},{"en":"This word shows what the writer wants readers to notice most.","zh":"這個詞顯示作者最希望讀者注意甚麼。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":11},{"front":"foundations for statistical validity","meaning":"統計有效性的基礎","examples":[{"en":"Representative samples are foundations for statistical validity.","zh":"具代表性的樣本是統計有效性的基礎。"},{"en":"Foundations for statistical validity are basic requirements that make statistical conclusions trustworthy.","zh":"foundations for statistical validity 是令統計結論可信的基本要求。"},{"en":"A survey needs a fair sample and clear questions as foundations for statistical validity.","zh":"調查需要公平樣本和清楚問題作為統計有效性的基礎。"},{"en":"If these foundations are weak, the final numbers may mislead readers.","zh":"如果這些基礎薄弱，最終數字可能誤導讀者。"},{"en":"This phrase explains what statistics must have before they can be trusted.","zh":"這個片語解釋統計在可信前必須具備甚麼。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":11},{"front":"representative samples","meaning":"具代表性的樣本","examples":[{"en":"Reliable statistics require representative samples.","zh":"可靠統計需要具代表性的樣本。"},{"en":"Representative samples are groups chosen so they fairly reflect the larger population.","zh":"representative samples 是經選取後能公平反映更大人口的群體。"},{"en":"A school survey should include students from different forms, not only top students.","zh":"學校調查應包括不同年級學生，而不只是尖子學生。"},{"en":"If a sample is not representative, the results may favour one group unfairly.","zh":"如果樣本不具代表性，結果可能不公平地偏向某一群體。"},{"en":"This phrase is essential for judging whether statistics are trustworthy.","zh":"這個片語對判斷統計是否可信非常重要。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":11},{"front":"eliminating outside variables","meaning":"排除外在變數","examples":[{"en":"Good statistics require eliminating outside variables.","zh":"良好統計需要排除外在變數。"},{"en":"Eliminating outside variables means removing other factors that could affect the result.","zh":"eliminating outside variables 指移除可能影響結果的其他因素。"},{"en":"To test a study method fairly, a teacher should control for sleep, lesson time, and prior ability.","zh":"要公平測試學習方法，老師應控制睡眠、課堂時間和原有能力。"},{"en":"If outside variables remain, researchers may mistake one cause for another.","zh":"如果外在變數仍存在，研究人員可能把一個原因誤認為另一個。"},{"en":"This phrase explains how to make comparisons fairer.","zh":"這個片語解釋如何令比較更公平。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":12},{"front":"outside variables","meaning":"外在變數；干擾變數","examples":[{"en":"Outside variables can affect statistical conclusions.","zh":"外在變數可以影響統計結論。"},{"en":"Outside variables are extra factors not being studied directly but still influencing the result.","zh":"outside variables 是沒有被直接研究但仍影響結果的額外因素。"},{"en":"If one class has a better teacher, that is an outside variable in a study of homework length.","zh":"如果某班有更好的老師，這就是研究功課長度時的外在變數。"},{"en":"If outside variables are ignored, a conclusion may look stronger than it really is.","zh":"如果外在變數被忽視，結論可能看起來比實際更強。"},{"en":"This phrase helps explain why simple comparisons can be misleading.","zh":"這個片語幫助解釋為何簡單比較可能誤導。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":12},{"front":"the green-eaters","meaning":"吃菜族；對素食者的戲謔稱呼","examples":[{"en":"The writer uses “the green-eaters” as another mocking term for vegetarians.","zh":"作者使用 “the green-eaters” 作為另一個對素食者的戲謔稱呼。"},{"en":"The green-eaters is a humorous or mocking label for people who eat mainly vegetables.","zh":"the green-eaters 是對主要吃蔬菜的人作出的幽默或嘲諷標籤。"},{"en":"A writer may say “the green-eaters” to sound playful but also dismissive.","zh":"作者可能說 “the green-eaters” 令語氣顯得俏皮但也帶輕視。"},{"en":"If a label reduces people to what they eat, it may reveal the writer’s bias.","zh":"如果標籤把人簡化成他們吃甚麼，它可能揭示作者偏見。"},{"en":"This phrase is informal and should be avoided in neutral writing.","zh":"這個片語較口語，應避免用於中立寫作。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":12},{"front":"the second point","meaning":"第二點","examples":[{"en":"The writer wants to look at the second point about statistics.","zh":"作者想看看關於統計的第二點。"},{"en":"The second point means the next argument or issue after the first one.","zh":"the second point 指第一個論點或問題之後的下一個論點。"},{"en":"In an essay, the second point may discuss cost after the first point discusses safety.","zh":"在文章中，第二點可能在第一點討論安全後討論成本。"},{"en":"If the first argument concerns cruelty, the second point may shift to health evidence.","zh":"如果第一個論點關於殘忍，第二點可能轉向健康證據。"},{"en":"This phrase helps organise a discussion.","zh":"這個片語幫助組織討論。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":12},{"front":"lean and fit","meaning":"精瘦而健壯的","examples":[{"en":"The example compares a lean and fit vegetarian with an unhealthy meat-eater.","zh":"這個例子把一位精瘦而健壯的素食者與一位不健康肉食者比較。"},{"en":"Lean and fit means slim, healthy, and physically strong.","zh":"lean and fit 指身形精瘦、健康而體能良好。"},{"en":"A runner who trains regularly and eats carefully may look lean and fit.","zh":"定期訓練並小心飲食的跑手可能看起來精瘦而健壯。"},{"en":"If a person is lean and fit, their long life may be linked to many lifestyle habits, not diet alone.","zh":"如果一個人精瘦而健壯，其長壽可能與許多生活習慣有關，而不只是飲食。"},{"en":"This phrase describes physical condition, not moral value.","zh":"這個片語描述身體狀態，而不是道德價值。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":12},{"front":"health-conscious","meaning":"注重健康的","examples":[{"en":"A health-conscious person makes careful lifestyle choices.","zh":"注重健康的人會作出謹慎的生活方式選擇。"},{"en":"Health-conscious means aware of health and trying to make healthy choices.","zh":"health-conscious 指有健康意識並嘗試作出健康選擇。"},{"en":"A health-conscious student may bring water and fruit instead of sugary drinks.","zh":"注重健康的學生可能帶水和水果，而不是含糖飲品。"},{"en":"If a person is health-conscious, they may exercise, sleep well, and avoid smoking.","zh":"如果一個人注重健康，他可能運動、睡得好並避免吸煙。"},{"en":"This phrase describes an attitude toward health, not one specific diet.","zh":"這個片語描述對健康的態度，而不是某一種特定飲食。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":12},{"front":"daily yoga","meaning":"每日瑜伽","examples":[{"en":"The writer describes a vegetarian doing daily yoga.","zh":"作者描述一位素食者每天做瑜伽。"},{"en":"Daily yoga means practising yoga every day.","zh":"daily yoga 指每天練習瑜伽。"},{"en":"A worker may do daily yoga to reduce back pain and stress after sitting all day.","zh":"久坐一整天的員工可能每天做瑜伽，以減少背痛和壓力。"},{"en":"If someone does daily yoga, their health may improve because of exercise and relaxation.","zh":"如果某人每天做瑜伽，其健康可能因運動和放鬆而改善。"},{"en":"This phrase describes a regular habit, not a single activity.","zh":"這個片語描述定期習慣，而不是一次活動。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":12},{"front":"nightly guitar-strumming","meaning":"每晚彈結他","examples":[{"en":"The passage humorously mentions nightly guitar-strumming.","zh":"文章幽默地提到每晚彈結他。"},{"en":"Nightly guitar-strumming means playing the guitar casually every night.","zh":"nightly guitar-strumming 指每晚隨意彈結他。"},{"en":"A university student may relax after study with nightly guitar-strumming in the dormitory.","zh":"大學生可能在宿舍中每晚彈結他，以在溫習後放鬆。"},{"en":"If someone has calm evening habits, those habits may contribute to well-being.","zh":"如果某人有平靜的晚間習慣，這些習慣可能有助身心健康。"},{"en":"This phrase is humorous and paints a relaxed lifestyle picture.","zh":"這個片語帶幽默感，描繪放鬆生活方式。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":12},{"front":"live much longer","meaning":"活得長得多","examples":[{"en":"A healthy vegetarian may live much longer than an unhealthy meat-eater.","zh":"健康素食者可能比不健康肉食者活得長得多。"},{"en":"To live much longer means to have a far longer life than someone else or than expected.","zh":"live much longer 指比別人或比預期有長得多的壽命。"},{"en":"People who exercise and avoid smoking often live much longer than those with risky habits.","zh":"運動並避免吸煙的人，通常比有高風險習慣的人活得長得多。"},{"en":"If one group lives longer, researchers must ask whether diet or other habits explain it.","zh":"如果某群體活得較長，研究人員必須問是飲食還是其他習慣解釋這點。"},{"en":"This phrase describes lifespan, not daily energy alone.","zh":"這個片語描述壽命，而不只是每日精力。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":12},{"front":"on average","meaning":"平均而言","examples":[{"en":"Health-conscious people may live longer on average.","zh":"注重健康的人平均而言可能活得較長。"},{"en":"On average means generally, when all cases are considered together.","zh":"on average 指整體考慮所有個案時，一般而言。"},{"en":"Students who revise weekly may score higher on average than students who revise only the night before.","zh":"每週溫習的學生平均而言可能比只在考試前一晚溫習的學生得分更高。"},{"en":"If a group lives longer on average, individual cases may still vary greatly.","zh":"如果某群體平均而言活得較長，個別情況仍可能差異很大。"},{"en":"This phrase describes a general pattern, not every person.","zh":"這個片語描述一般模式，而不是每個人。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":12},{"front":"chain-smoking","meaning":"煙不離手的","examples":[{"en":"A chain-smoking person smokes continuously.","zh":"煙不離手的人會連續吸煙。"},{"en":"Chain-smoking means smoking cigarettes one after another with little break.","zh":"chain-smoking 指一支接一支吸煙，幾乎沒有停頓。"},{"en":"A chain-smoking worker may cough often and smell strongly of smoke.","zh":"煙不離手的員工可能常咳嗽，身上有很重煙味。"},{"en":"If someone chain-smokes for years, their risk of serious illness may rise.","zh":"如果某人多年煙不離手，患嚴重疾病的風險可能上升。"},{"en":"This word describes a heavy and unhealthy smoking habit.","zh":"這個詞描述沉重而不健康的吸煙習慣。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":12},{"front":"beer-swilling","meaning":"狂飲啤酒的","examples":[{"en":"The writer describes an unhealthy person as beer-swilling.","zh":"作者把不健康的人描述為狂飲啤酒的。"},{"en":"Beer-swilling means drinking large amounts of beer in an uncontrolled or unattractive way.","zh":"beer-swilling 指以失控或不雅方式大量喝啤酒。"},{"en":"A beer-swilling sports fan may spend the whole evening drinking instead of watching the game clearly.","zh":"狂飲啤酒的球迷可能整晚喝酒，而不是清楚觀看比賽。"},{"en":"If someone drinks heavily every night, alcohol may damage sleep, mood, and health.","zh":"如果某人每晚大量飲酒，酒精可能傷害睡眠、心情和健康。"},{"en":"This word is informal, critical, and slightly mocking.","zh":"這個詞較口語、帶批評和少許嘲諷。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":13},{"front":"doughnut-chomping","meaning":"大口吃冬甩的","examples":[{"en":"The passage mocks the unhealthy person as doughnut-chomping.","zh":"文章嘲諷不健康的人為大口吃冬甩的。"},{"en":"Doughnut-chomping means eating doughnuts greedily or heavily.","zh":"doughnut-chomping 指貪吃或大量吃冬甩。"},{"en":"A doughnut-chomping office worker may snack all afternoon without noticing how much sugar they eat.","zh":"大口吃冬甩的辦公室員工可能整個下午吃零食，卻沒注意吃了多少糖。"},{"en":"If someone eats sugary snacks constantly, weight and health problems may follow.","zh":"如果某人不斷吃含糖零食，體重和健康問題可能隨之而來。"},{"en":"This phrase is informal and comic rather than neutral.","zh":"這個片語較口語和滑稽，而不是中立。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":13},{"front":"couch potato","meaning":"梳化薯仔；懶散少動的人","examples":[{"en":"A couch potato spends too much time sitting and doing little exercise.","zh":"梳化薯仔花太多時間坐着，並且很少運動。"},{"en":"A couch potato is a lazy or inactive person who watches television or sits around for long periods.","zh":"couch potato 是懶散或不活躍的人，長時間看電視或坐着不動。"},{"en":"A student may become a couch potato during holidays if they only watch videos and never go outside.","zh":"如果學生假期只看影片而不外出，可能變成梳化薯仔。"},{"en":"If someone is a couch potato, poor fitness may be caused by inactivity rather than diet alone.","zh":"如果某人是梳化薯仔，體能差可能由缺乏活動造成，而不只是飲食。"},{"en":"This phrase is informal and slightly humorous.","zh":"這個片語較口語，略帶幽默。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":13},{"front":"in any way related to","meaning":"以任何方式與……有關","examples":[{"en":"The longer life may not be in any way related to avoiding meat.","zh":"較長壽命可能並非以任何方式與戒肉有關。"},{"en":"In any way related to means connected with something at all.","zh":"in any way related to 指與某事有任何程度上的關聯。"},{"en":"A student’s headache may not be in any way related to the test; it may simply be lack of sleep.","zh":"學生頭痛可能完全與測驗無關，而只是睡眠不足。"},{"en":"If longer life is caused by exercise and not diet, vegetarianism may not be the real reason.","zh":"如果較長壽命由運動而非飲食造成，素食主義可能不是真正原因。"},{"en":"This phrase strongly denies or questions a connection.","zh":"這個片語強烈否定或質疑關聯。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":13},{"front":"the former’s abstinence from meat","meaning":"前者戒肉","examples":[{"en":"The writer questions whether the former’s abstinence from meat is the real cause.","zh":"作者質疑前者戒肉是否真正原因。"},{"en":"The former’s abstinence from meat means the first-mentioned person’s choice not to eat meat.","zh":"the former’s abstinence from meat 指前面提到的那個人不吃肉的選擇。"},{"en":"If two students differ in sleep, exercise, and diet, the former’s abstinence from sugar may not explain better grades.","zh":"如果兩名學生在睡眠、運動和飲食上都不同，前者戒糖未必能解釋較好成績。"},{"en":"When several lifestyle differences exist, one habit should not be treated as the only cause.","zh":"當存在多種生活方式差異，不應把一個習慣視為唯一原因。"},{"en":"This phrase is formal and refers back to the first of two people or groups.","zh":"這個片語較正式，回指兩人或兩組中的前者。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":13},{"front":"it is not hard to deduce that","meaning":"不難推斷","examples":[{"en":"It is not hard to deduce that smoking and drinking harm health.","zh":"不難推斷吸煙和飲酒會損害健康。"},{"en":"It is not hard to deduce that means it is easy to reason from evidence to a conclusion.","zh":"it is not hard to deduce that 指很容易從證據推理出結論。"},{"en":"If a student never attends class, it is not hard to deduce that they may struggle in the exam.","zh":"如果學生從不上課，不難推斷他考試可能會吃力。"},{"en":"If many unhealthy habits exist, we can infer they may reduce life expectancy.","zh":"如果存在許多不健康習慣，我們可以推斷它們可能縮短預期壽命。"},{"en":"This phrase introduces a conclusion that seems obvious from the facts.","zh":"這個片語引入從事實看來明顯的結論。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":13},{"front":"sedentary lifestyle","meaning":"久坐不動的生活方式","examples":[{"en":"A sedentary lifestyle can reduce life expectancy.","zh":"久坐不動的生活方式可以縮短預期壽命。"},{"en":"A sedentary lifestyle is a way of life with too much sitting and too little physical activity.","zh":"sedentary lifestyle 是坐得太多、身體活動太少的生活方式。"},{"en":"Office workers may develop a sedentary lifestyle if they sit all day and never exercise.","zh":"如果辦公室員工整天坐着而從不運動，可能形成久坐不動的生活方式。"},{"en":"If people move very little, they may gain weight and lose fitness over time.","zh":"如果人們很少活動，可能隨時間增重並失去體能。"},{"en":"This phrase is often used in health discussions about inactivity.","zh":"這個片語常用於關於缺乏活動的健康討論。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":13},{"front":"responsible for","meaning":"對……負責；導致","examples":[{"en":"Smoking and inactivity may be responsible for early death.","zh":"吸煙和缺乏活動可能導致早死。"},{"en":"Responsible for means being the cause of something or having duty for something.","zh":"responsible for 指作為某事原因，或對某事負有責任。"},{"en":"A broken pipe may be responsible for water damage in a classroom.","zh":"破裂水管可能是課室水浸損壞的原因。"},{"en":"If several habits are responsible for poor health, diet alone should not be blamed.","zh":"如果幾種習慣導致健康差，就不應只責怪飲食。"},{"en":"This phrase can indicate cause or duty, depending on context.","zh":"這個片語可表示原因或責任，視乎語境。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":13},{"front":"diminished life expectancy","meaning":"縮短的預期壽命","examples":[{"en":"An unhealthy lifestyle can cause diminished life expectancy.","zh":"不健康生活方式可以導致預期壽命縮短。"},{"en":"Diminished life expectancy means a reduced expected length of life.","zh":"diminished life expectancy 指預期壽命減少。"},{"en":"Long-term smoking may lead to diminished life expectancy compared with healthier habits.","zh":"長期吸煙相比更健康習慣可能導致預期壽命縮短。"},{"en":"If a group has lower life expectancy, researchers must ask which factors caused the difference.","zh":"如果某群體預期壽命較低，研究人員必須問哪些因素造成差異。"},{"en":"This phrase is formal and common in health statistics.","zh":"這個片語較正式，常見於健康統計。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":13},{"front":"a true comparison","meaning":"真正公平的比較","examples":[{"en":"A true comparison must compare similar groups.","zh":"真正公平的比較必須比較相似群體。"},{"en":"A true comparison is a fair comparison that controls for important differences.","zh":"true comparison 是控制重要差異後的公平比較。"},{"en":"To compare two study methods fairly, students should have similar ability and study time.","zh":"要公平比較兩種學習方法，學生應有相似能力和溫習時間。"},{"en":"If one group exercises daily and the other smokes heavily, diet is not the only difference.","zh":"如果一組每天運動，另一組大量吸煙，飲食就不是唯一差異。"},{"en":"This phrase warns against misleading comparisons.","zh":"這個片語警告不要作誤導性比較。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":13},{"front":"non-vegetarians","meaning":"非素食者","examples":[{"en":"Health-conscious non-vegetarians may also live long lives.","zh":"注重健康的非素食者也可能長壽。"},{"en":"Non-vegetarians are people who do eat meat or animal products.","zh":"non-vegetarians 是會吃肉或動物產品的人。"},{"en":"A non-vegetarian may still eat plenty of vegetables and exercise regularly.","zh":"非素食者仍可能吃大量蔬菜並定期運動。"},{"en":"If non-vegetarians live healthily, their results may challenge simple diet-based claims.","zh":"如果非素食者生活健康，其結果可能挑戰單純基於飲食的主張。"},{"en":"This word describes what someone does not exclude from their diet.","zh":"這個詞描述某人飲食中沒有排除甚麼。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":13},{"front":"the latter group","meaning":"後者一組","examples":[{"en":"The latter group includes people who eat moderate amounts of meat.","zh":"後者一組包括適量吃肉的人。"},{"en":"The latter group means the second group mentioned out of two groups.","zh":"latter group 指兩組中後面提到的那一組。"},{"en":"If we compare teachers and students, the latter group refers to students.","zh":"如果我們比較老師和學生，後者一組指學生。"},{"en":"If the latter group is also health-conscious, the comparison with vegetarians becomes fairer.","zh":"如果後者一組也注重健康，與素食者的比較就更公平。"},{"en":"This phrase is formal and depends on the order of earlier information.","zh":"這個片語較正式，取決於前文資訊的順序。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":14},{"front":"moderate amounts of meat","meaning":"適量的肉類","examples":[{"en":"Some healthy non-vegetarians include moderate amounts of meat in their diets.","zh":"一些健康的非素食者在飲食中包括適量肉類。"},{"en":"Moderate amounts of meat are reasonable portions that are not excessive.","zh":"moderate amounts of meat 是合理而不過量的肉類份量。"},{"en":"A family may eat moderate amounts of meat by serving small pieces with rice and vegetables.","zh":"家庭可以透過小份肉配米飯和蔬菜來吃適量肉類。"},{"en":"If meat is eaten moderately, it may fit within a balanced diet.","zh":"如果肉類被適量食用，它可能融入均衡飲食。"},{"en":"This phrase focuses on quantity and balance.","zh":"這個片語聚焦於份量和平衡。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":14},{"front":"this is the point","meaning":"這正是重點","examples":[{"en":"This is the point the writer wants to make about statistics.","zh":"這正是作者想就統計提出的重點。"},{"en":"This is the point means this is the main idea or lesson being emphasised.","zh":"this is the point 指這是被強調的主要想法或教訓。"},{"en":"If a teacher says “this is the point,” students should listen for the key message.","zh":"如果老師說「這正是重點」，學生應留意關鍵訊息。"},{"en":"If many variables affect health, the point is that simple statistics may mislead.","zh":"如果許多變數影響健康，重點就是簡單統計可能誤導。"},{"en":"This phrase signals the core message.","zh":"這個片語標示核心訊息。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":14},{"front":"complex, mixed, and multifaceted","meaning":"複雜、混雜且多方面的","examples":[{"en":"Modern society is complex, mixed, and multifaceted.","zh":"現代社會是複雜、混雜且多方面的。"},{"en":"Complex, mixed, and multifaceted means having many different parts, influences, and angles.","zh":"complex, mixed, and multifaceted 指有許多不同部分、影響和角度。"},{"en":"A student’s exam result may be complex and multifaceted because sleep, teaching, practice, and stress all matter.","zh":"學生考試結果可能複雜且多方面，因為睡眠、教學、練習和壓力都重要。"},{"en":"If society is multifaceted, one simple cause rarely explains a health trend.","zh":"如果社會是多方面的，一個簡單原因很少能解釋健康趨勢。"},{"en":"This phrase warns against oversimplification.","zh":"這個片語警告不要過度簡化。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":14},{"front":"modern society","meaning":"現代社會","examples":[{"en":"Modern society makes simple comparisons difficult.","zh":"現代社會令簡單比較變得困難。"},{"en":"Modern society means the present-day social world, with its institutions, habits, technology, and lifestyles.","zh":"modern society 指當代社會世界，包括制度、習慣、科技和生活方式。"},{"en":"In modern society, people’s health is affected by work, diet, transport, stress, and medicine.","zh":"在現代社會中，人們健康受工作、飲食、交通、壓力和醫療影響。"},{"en":"If many factors shape behaviour, statistics must be interpreted carefully.","zh":"如果許多因素塑造行為，統計就必須謹慎解讀。"},{"en":"This phrase gives a broad context for social arguments.","zh":"這個片語為社會論點提供廣闊背景。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":14},{"front":"constitute","meaning":"構成","examples":[{"en":"Enough people must constitute a representative sample.","zh":"足夠的人必須構成具代表性的樣本。"},{"en":"Constitute means form, make up, or count as something.","zh":"constitute 指形成、組成或算作某事物。"},{"en":"Ten students do not constitute a fair sample of an entire school.","zh":"十名學生不能構成整間學校的公平樣本。"},{"en":"If the people chosen do not reflect the population, they cannot constitute reliable evidence.","zh":"如果被選的人不能反映整體人口，他們就不能構成可靠證據。"},{"en":"This word is formal and often used in arguments about classification or evidence.","zh":"這個詞較正式，常用於關於分類或證據的論證。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":14},{"front":"a truly representative sample","meaning":"真正具代表性的樣本","examples":[{"en":"It is difficult to find a truly representative sample.","zh":"要找到真正具代表性的樣本很困難。"},{"en":"A truly representative sample is a group that accurately reflects the larger population being studied.","zh":"truly representative sample 是能準確反映被研究整體人口的群體。"},{"en":"A survey of only gym members is not a truly representative sample of all adults.","zh":"只調查健身室會員，並不是真正具代表性的全體成年人樣本。"},{"en":"If a sample excludes poor, busy, or elderly people, its results may be biased.","zh":"如果樣本排除貧窮、忙碌或年長人士，其結果可能有偏差。"},{"en":"This phrase is central to fair statistical comparison.","zh":"這個片語是公平統計比較的核心。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":14},{"front":"anyone asserting that","meaning":"任何聲稱……的人","examples":[{"en":"Anyone asserting that statistics prove vegetarianism must consider other factors.","zh":"任何聲稱統計證明素食主義的人，都必須考慮其他因素。"},{"en":"Anyone asserting that something is true is anyone who claims it strongly.","zh":"anyone asserting that something is true 指任何強烈聲稱某事為真的人。"},{"en":"Anyone asserting that homework is useless should explain what evidence supports the claim.","zh":"任何聲稱功課無用的人，都應解釋有甚麼證據支持該主張。"},{"en":"If someone asserts a health claim, they must account for lifestyle, age, income, and other variables.","zh":"如果有人提出健康主張，就必須考慮生活方式、年齡、收入和其他變數。"},{"en":"This phrase introduces a challenge to people making strong claims.","zh":"這個片語引入對強烈聲稱者的挑戰。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":14},{"front":"compared with","meaning":"與……相比","examples":[{"en":"Compared with unhealthy people, health-conscious vegetarians may live longer.","zh":"與不健康人士相比，注重健康的素食者可能活得較長。"},{"en":"Compared with means judged beside something else to show similarity or difference.","zh":"compared with 指與某物並列判斷，以顯示相似或差異。"},{"en":"Compared with handwritten notes, digital notes are easier to search.","zh":"與手寫筆記相比，電子筆記較容易搜尋。"},{"en":"If one group has many healthy habits, it may look better compared with an unhealthy group.","zh":"如果一組有許多健康習慣，與不健康組相比可能看起來更好。"},{"en":"This phrase sets up a comparison and needs a fair basis.","zh":"這個片語建立比較，並需要公平基礎。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":14},{"front":"sofa sprouts","meaning":"梳化懶人；懶散一族","examples":[{"en":"The writer uses “sofa sprouts” to refer humorously to lazy or inactive people.","zh":"作者使用 “sofa sprouts” 幽默地指懶散或不活躍的人。"},{"en":"Sofa sprouts is a joking phrase for people who sit around too much and do little exercise.","zh":"sofa sprouts 是對坐得太多、很少運動的人的玩笑說法。"},{"en":"During long holidays, students may become sofa sprouts if they only watch videos all day.","zh":"長假期間，如果學生整天只看影片，可能變成梳化懶人。"},{"en":"If sofa sprouts have poor health, inactivity may explain it better than diet alone.","zh":"如果梳化懶人健康差，缺乏活動可能比飲食本身更能解釋原因。"},{"en":"This phrase is playful and not suitable for formal medical writing.","zh":"這個片語俏皮，不適合正式醫學寫作。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":14},{"front":"rigorous","meaning":"嚴謹的；嚴格的","examples":[{"en":"Vegetarians may have made a rigorous lifestyle change.","zh":"素食者可能作出了嚴謹的生活方式改變。"},{"en":"Rigorous means strict, careful, and thorough.","zh":"rigorous 指嚴格、仔細和徹底。"},{"en":"A rigorous study plan includes practice, feedback, rest, and regular review.","zh":"嚴謹的學習計劃包括練習、回饋、休息和定期複習。"},{"en":"If a person makes a rigorous health change, many habits may improve at the same time.","zh":"如果一個人作出嚴格健康改變，許多習慣可能同時改善。"},{"en":"This word suggests discipline and seriousness.","zh":"這個詞暗示自律和認真。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":14},{"front":"disciplined","meaning":"自律的","examples":[{"en":"A disciplined lifestyle may improve health.","zh":"自律的生活方式可能改善健康。"},{"en":"Disciplined means controlled, organised, and able to follow good habits consistently.","zh":"disciplined 指有控制、有組織，並能持續遵守良好習慣。"},{"en":"A disciplined student studies regularly instead of waiting until the night before the exam.","zh":"自律的學生會定期溫習，而不是等到考試前一晚。"},{"en":"If someone is disciplined with food, sleep, and exercise, their health may improve.","zh":"如果某人在飲食、睡眠和運動方面自律，健康可能改善。"},{"en":"This word describes self-control in action.","zh":"這個詞描述行動中的自我控制。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":15},{"front":"health-enhancing","meaning":"有助健康的","examples":[{"en":"A health-enhancing lifestyle can affect life expectancy.","zh":"有助健康的生活方式可以影響預期壽命。"},{"en":"Health-enhancing means improving or supporting health.","zh":"health-enhancing 指改善或支持健康的。"},{"en":"Walking to school, sleeping well, and eating fruit are health-enhancing habits.","zh":"步行上學、睡得好和吃水果都是有助健康的習慣。"},{"en":"If vegetarianism is accompanied by many health-enhancing choices, those choices may explain longer life.","zh":"如果素食主義伴隨許多有助健康的選擇，這些選擇可能解釋較長壽命。"},{"en":"This phrase describes something that helps health, not just something that sounds healthy.","zh":"這個片語描述真正幫助健康的東西，而不只是聽起來健康。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":15},{"front":"lifestyle change","meaning":"生活方式改變","examples":[{"en":"Vegetarianism may be part of a broader lifestyle change.","zh":"素食主義可能是一種更廣泛生活方式改變的一部分。"},{"en":"Lifestyle change means a change in daily habits, routines, diet, exercise, or behaviour.","zh":"lifestyle change 指日常習慣、作息、飲食、運動或行為的改變。"},{"en":"A person may make a lifestyle change by sleeping earlier and walking to work.","zh":"一個人可能透過早睡和步行上班作出生活方式改變。"},{"en":"If many habits change together, it is hard to know which one caused better health.","zh":"如果許多習慣一起改變，就很難知道哪一項造成健康改善。"},{"en":"This phrase is broader than a single diet choice.","zh":"這個片語比單一飲食選擇更廣泛。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":15},{"front":"accompanied by","meaning":"伴隨","examples":[{"en":"A diet change may be accompanied by other healthy choices.","zh":"飲食改變可能伴隨其他健康選擇。"},{"en":"Accompanied by means happening together with something else.","zh":"accompanied by 指與另一事物一起發生。"},{"en":"A school trip may be accompanied by a worksheet so students observe more carefully.","zh":"學校旅行可能伴隨工作紙，讓學生更仔細觀察。"},{"en":"If vegetarianism is accompanied by exercise and no smoking, health results may not come from diet alone.","zh":"如果素食主義伴隨運動和不吸煙，健康結果未必單靠飲食造成。"},{"en":"This phrase shows that one thing comes with another.","zh":"這個片語顯示一事物與另一事物同時出現。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":15},{"front":"similar choices","meaning":"類似選擇","examples":[{"en":"Other similar choices may explain better health.","zh":"其他類似選擇可能解釋更好健康。"},{"en":"Similar choices are other decisions of the same kind or with similar effects.","zh":"similar choices 是其他同類或有相似效果的決定。"},{"en":"A student who studies regularly may also make similar choices, such as sleeping early and avoiding distractions.","zh":"定期溫習的學生可能也作出類似選擇，例如早睡和避免分心。"},{"en":"If healthy people make many similar choices, researchers must separate their effects.","zh":"如果健康人士作出許多類似選擇，研究人員必須分開其影響。"},{"en":"This phrase refers to related decisions, not one isolated action.","zh":"這個片語指相關決定，而不是孤立行動。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":15},{"front":"the real cause of","meaning":"……的真正原因","examples":[{"en":"The writer argues that lifestyle choices are the real cause of statistical trends.","zh":"作者主張生活方式選擇是統計趨勢的真正原因。"},{"en":"The real cause of something is the actual reason it happens, not the reason people first assume.","zh":"real cause of something 是某事發生的實際原因，而不是人們最初假設的原因。"},{"en":"A student’s low mark may have lack of sleep as the real cause, not lack of intelligence.","zh":"學生低分的真正原因可能是睡眠不足，而不是不聰明。"},{"en":"If exercise and non-smoking explain longer life, vegetarianism may not be the real cause.","zh":"如果運動和不吸煙解釋較長壽命，素食主義可能不是真正原因。"},{"en":"This phrase asks readers to look beyond surface explanations.","zh":"這個片語要求讀者看穿表面解釋。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":15},{"front":"statistical trends","meaning":"統計趨勢","examples":[{"en":"Statistical trends may be caused by lifestyle differences.","zh":"統計趨勢可能由生活方式差異造成。"},{"en":"Statistical trends are patterns shown by numbers collected over many cases or over time.","zh":"statistical trends 是由許多個案或長時間收集的數字顯示出的模式。"},{"en":"A school may notice statistical trends in attendance after changing lesson times.","zh":"學校改變上課時間後，可能注意到出席率的統計趨勢。"},{"en":"If a trend appears in health data, researchers must ask what variables created it.","zh":"如果健康數據中出現趨勢，研究人員必須問哪些變數造成它。"},{"en":"This phrase refers to patterns in data, not individual stories.","zh":"這個片語指數據中的模式，而不是個別故事。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":15},{"front":"factor these into the equation","meaning":"把這些因素納入考慮","examples":[{"en":"Researchers must factor these lifestyle choices into the equation.","zh":"研究人員必須把這些生活方式選擇納入考慮。"},{"en":"To factor these into the equation means to include these elements when analysing a situation.","zh":"factor these into the equation 指在分析情況時包括這些元素。"},{"en":"A student planning a study timetable should factor sleep and transport time into the equation.","zh":"學生規劃溫習時間表時，應把睡眠和交通時間納入考慮。"},{"en":"If statistics ignore exercise, smoking, and stress, the conclusion may be incomplete.","zh":"如果統計忽視運動、吸煙和壓力，結論可能不完整。"},{"en":"This phrase means consider important variables before deciding.","zh":"這個片語指在決定前考慮重要變數。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":15},{"front":"so far","meaning":"到目前為止","examples":[{"en":"So far, the writer sees no convincing statistical evidence.","zh":"到目前為止，作者看不到具說服力的統計證據。"},{"en":"So far means up to this point in time.","zh":"so far 指直到目前這一刻。"},{"en":"So far, the new study plan has helped the student finish homework earlier.","zh":"到目前為止，新的學習計劃幫助學生更早完成功課。"},{"en":"If evidence is weak so far, the writer may refuse to accept a strong conclusion.","zh":"如果到目前為止證據薄弱，作者可能拒絕接受強烈結論。"},{"en":"This phrase leaves open the possibility that things may change later.","zh":"這個片語保留日後情況可能改變的可能性。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":15},{"front":"convincing statistical evidence","meaning":"具說服力的統計證據","examples":[{"en":"The writer says there is no convincing statistical evidence for the health claim.","zh":"作者說沒有具說服力的統計證據支持這個健康主張。"},{"en":"Convincing statistical evidence is numerical evidence strong enough to support a conclusion.","zh":"convincing statistical evidence 是強到足以支持結論的數字證據。"},{"en":"A school needs convincing statistical evidence before changing every class timetable.","zh":"學校在改變所有班級時間表前需要具說服力的統計證據。"},{"en":"If samples are biased or variables are ignored, the statistics are not convincing.","zh":"如果樣本有偏差或變數被忽視，統計就不具說服力。"},{"en":"This phrase combines numbers with trustworthiness.","zh":"這個片語把數字與可信度結合起來。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":15},{"front":"vegetarianism","meaning":"素食主義","examples":[{"en":"The passage debates whether vegetarianism is better for health.","zh":"文章辯論素食主義是否對健康更好。"},{"en":"Vegetarianism is the practice or belief of not eating meat.","zh":"vegetarianism 是不吃肉的做法或信念。"},{"en":"Some people choose vegetarianism for health, religion, animal welfare, or environmental reasons.","zh":"有些人因健康、宗教、動物福利或環境原因選擇素食主義。"},{"en":"If vegetarianism is combined with poor nutrition, it may not automatically improve health.","zh":"如果素食主義伴隨營養不良，它不一定自動改善健康。"},{"en":"This word refers to a diet and sometimes a moral or lifestyle position.","zh":"這個詞指飲食，有時也指道德或生活方式立場。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":15},{"front":"better for health","meaning":"對健康更好","examples":[{"en":"The writer questions whether vegetarianism is better for health.","zh":"作者質疑素食主義是否對健康更好。"},{"en":"Better for health means more likely to improve or protect physical well-being.","zh":"better for health 指較有可能改善或保護身體健康。"},{"en":"Walking daily is usually better for health than sitting for hours without movement.","zh":"每天步行通常比長時間坐着不動對健康更好。"},{"en":"If one diet is claimed to be healthier, researchers must compare similar people fairly.","zh":"如果某飲食被稱為更健康，研究人員必須公平比較相似人士。"},{"en":"This phrase needs evidence because health depends on many factors.","zh":"這個片語需要證據，因為健康取決於許多因素。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":16},{"front":"Reading Passage Two","meaning":"閱讀篇章二","examples":[{"en":"Reading Passage Two has seven paragraphs.","zh":"閱讀篇章二有七段。"},{"en":"Reading Passage Two means the second reading text in an exam or exercise.","zh":"Reading Passage Two 指考試或練習中的第二篇閱讀文章。"},{"en":"Students should read Reading Passage Two carefully before answering heading questions.","zh":"學生回答標題題前應仔細閱讀閱讀篇章二。"},{"en":"If a passage has seven paragraphs, candidates must track ideas paragraph by paragraph.","zh":"如果文章有七段，考生必須逐段追蹤意思。"},{"en":"This phrase is an exam label, not part of the article’s argument.","zh":"這個片語是考試標籤，而不是文章論點的一部分。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":16},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Students choose the correct heading for each paragraph.","zh":"學生為每段選出正確標題。"},{"en":"To choose the correct heading means to select the title that best summarises a paragraph.","zh":"choose the correct heading 指選擇最能概括某段的標題。"},{"en":"In IELTS reading, students should choose the heading after identifying the paragraph’s main idea.","zh":"在 IELTS 閱讀中，學生應先找出段落主旨，再選標題。"},{"en":"If a heading mentions only a small detail, it may not be the correct one.","zh":"如果標題只提及小細節，它可能不是正確標題。"},{"en":"This phrase is a common reading-test instruction.","zh":"這個片語是常見閱讀測驗指示。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":16},{"front":"from the list of headings","meaning":"從標題列表中","examples":[{"en":"The correct heading is chosen from the list of headings.","zh":"正確標題從標題列表中選出。"},{"en":"From the list of headings means using only the headings provided in the question.","zh":"from the list of headings 指只使用題目提供的標題。"},{"en":"Students should not invent a new title if the answer must come from the list of headings.","zh":"如果答案必須來自標題列表，學生不應自行創作新標題。"},{"en":"If two headings look similar, the paragraph’s main purpose decides which one fits better.","zh":"如果兩個標題看似相似，段落主要目的決定哪個更合適。"},{"en":"This phrase limits the answer choices.","zh":"這個片語限制答案選項。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":16},{"front":"write the correct number","meaning":"寫下正確編號","examples":[{"en":"Students write the correct number for each answer.","zh":"學生為每個答案寫下正確編號。"},{"en":"To write the correct number means to record the number that matches the chosen option.","zh":"write the correct number 指記下與所選選項相符的編號。"},{"en":"In heading questions, students may write Roman numerals instead of words.","zh":"在標題題中，學生可能要寫羅馬數字而不是文字。"},{"en":"If a student chooses the right heading but writes the wrong number, the answer may be marked wrong.","zh":"如果學生選對標題但寫錯編號，答案可能被判錯。"},{"en":"This phrase reminds candidates to follow the required answer format.","zh":"這個片語提醒考生遵守指定答案格式。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":16},{"front":"needless killing","meaning":"不必要的殺戮","examples":[{"en":"The heading “Needless killing countered” refers to an argument against unnecessary killing.","zh":"標題 “Needless killing countered” 指反對不必要殺戮的論點。"},{"en":"Needless killing means killing that is not necessary for survival or a serious purpose.","zh":"needless killing 指不是為生存或重要目的所必需的殺戮。"},{"en":"Killing insects for no reason may be seen as needless killing by animal lovers.","zh":"無故殺死昆蟲可能被動物愛護者視為不必要的殺戮。"},{"en":"If humans have enough alternative food, some people argue that animal slaughter is needless.","zh":"如果人類有足夠替代食物，一些人主張宰殺動物是不必要的。"},{"en":"This phrase focuses on whether death could have been avoided.","zh":"這個片語聚焦於死亡是否本可避免。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":16},{"front":"countered","meaning":"被反駁；加以反駁","examples":[{"en":"The writer countered several vegetarian arguments.","zh":"作者反駁了幾個素食論點。"},{"en":"Countered means answered or opposed an argument with another argument.","zh":"countered 指用另一個論點回應或反對某論點。"},{"en":"A student countered the teacher’s criticism by showing evidence from the passage.","zh":"學生透過展示文章證據反駁老師的批評。"},{"en":"If a claim is countered effectively, readers may question it more carefully.","zh":"如果某主張被有效反駁，讀者可能更仔細地質疑它。"},{"en":"This word is common in debate and argument writing.","zh":"這個詞常見於辯論和議論寫作。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":16},{"front":"a need for statistics","meaning":"對統計數據的需要","examples":[{"en":"The passage discusses a need for statistics when judging health claims.","zh":"文章討論判斷健康主張時對統計數據的需要。"},{"en":"A need for statistics means reliable numbers are necessary to support a claim.","zh":"need for statistics 指需要可靠數字來支持某主張。"},{"en":"A school needs statistics before deciding whether a new timetable improves attendance.","zh":"學校在判斷新時間表是否改善出席率前，需要統計數據。"},{"en":"If people make health claims without data, their argument may rest only on opinion.","zh":"如果人們沒有數據便提出健康主張，其論點可能只建基於意見。"},{"en":"This phrase points to evidence-based judgement.","zh":"這個片語指向以證據為本的判斷。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":16},{"front":"the real cause of longer lives","meaning":"壽命較長的真正原因","examples":[{"en":"The heading asks about the real cause of longer lives.","zh":"標題問壽命較長的真正原因。"},{"en":"The real cause of longer lives means the actual reason why some people live longer.","zh":"real cause of longer lives 指某些人活得較長的實際原因。"},{"en":"Longer lives may result from exercise, sleep, income, medical care, and diet together.","zh":"壽命較長可能由運動、睡眠、收入、醫療和飲食共同造成。"},{"en":"If researchers ignore other habits, they may wrongly credit vegetarianism alone.","zh":"如果研究人員忽視其他習慣，可能錯誤地只歸功於素食主義。"},{"en":"This phrase asks readers to separate cause from mere association.","zh":"這個片語要求讀者把原因與單純關聯分開。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":16},{"front":"untrustworthy numbers","meaning":"不可靠的數字","examples":[{"en":"The writer warns against untrustworthy numbers.","zh":"作者警告不要相信不可靠的數字。"},{"en":"Untrustworthy numbers are statistics that should not be relied on because they may be biased, incomplete, or misleading.","zh":"untrustworthy numbers 是不應依賴的統計，因為它們可能有偏差、不完整或誤導。"},{"en":"A survey of only ten friends gives untrustworthy numbers about a whole school.","zh":"只調查十個朋友，得出的關於全校的數字並不可靠。"},{"en":"If numbers come from a poor sample, they can support the wrong conclusion.","zh":"如果數字來自差劣樣本，它們可以支持錯誤結論。"},{"en":"This phrase warns students not to accept statistics automatically.","zh":"這個片語提醒學生不要自動接受統計。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":16},{"front":"cruel killing","meaning":"殘酷殺戮","examples":[{"en":"The heading “Cruel killing countered” refers to the argument about animal slaughter.","zh":"標題 “Cruel killing countered” 指關於動物屠宰的論點。"},{"en":"Cruel killing means killing that causes unnecessary pain, fear, or suffering.","zh":"cruel killing 指造成不必要痛楚、恐懼或痛苦的殺戮。"},{"en":"A story about animals being killed slowly may be used as an example of cruel killing.","zh":"關於動物被慢慢殺死的故事，可能被用作殘酷殺戮的例子。"},{"en":"If killing is quick and regulated, some people may argue it is less cruel than wild predation.","zh":"如果殺戮快速且受規管，一些人可能主張它比野外捕食較不殘忍。"},{"en":"This phrase focuses on the manner of death.","zh":"這個片語聚焦於死亡方式。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":16},{"front":"comparing lives","meaning":"比較生活狀況","examples":[{"en":"The passage compares the lives of wild animals and domestic animals.","zh":"文章比較野生動物和家畜的生活狀況。"},{"en":"Comparing lives means looking at how different groups live and what conditions they face.","zh":"comparing lives 指觀察不同群體如何生活，以及面對甚麼條件。"},{"en":"A social studies class may compare the lives of city children and village children.","zh":"社會科課堂可能比較城市孩子和鄉村孩子的生活。"},{"en":"If we compare lives fairly, we must consider food, safety, illness, and freedom.","zh":"如果我們公平比較生活狀況，必須考慮食物、安全、疾病和自由。"},{"en":"This phrase helps examine whether one life is easier or harder than another.","zh":"這個片語幫助檢視一種生活是否比另一種更容易或更艱難。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":17},{"front":"quick efficient killing","meaning":"快速有效的殺戮","examples":[{"en":"The writer presents slaughter as a quick efficient killing compared with wild deaths.","zh":"作者把屠宰呈現為相比野外死亡更快速有效的殺戮。"},{"en":"Quick efficient killing means killing that is fast and carried out with little delay or struggle.","zh":"quick efficient killing 指快速完成、幾乎沒有延誤或掙扎的殺戮。"},{"en":"A critic may still object to quick efficient killing because speed does not answer every moral question.","zh":"批評者仍可能反對快速有效的殺戮，因為速度不能回答所有道德問題。"},{"en":"If the alternative is prolonged suffering, some may argue that speed matters morally.","zh":"如果替代情況是長時間痛苦，有些人可能主張速度在道德上重要。"},{"en":"This phrase is controversial because it joins efficiency with death.","zh":"這個片語具爭議，因為它把效率與死亡連在一起。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":17},{"front":"complete the table","meaning":"完成表格","examples":[{"en":"Students complete the table using words from the passage.","zh":"學生使用文章中的字詞完成表格。"},{"en":"To complete the table means to fill in missing information in a table.","zh":"complete the table 指填寫表格中缺少的資料。"},{"en":"In a reading test, students may complete a table with names, dates, or short phrases.","zh":"在閱讀測驗中，學生可能用姓名、日期或短片語完成表格。"},{"en":"If the answer must come from the passage, students should copy the exact words needed.","zh":"如果答案必須來自文章，學生應抄下所需的確切字詞。"},{"en":"This phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":17},{"front":"choose no more than three words","meaning":"選擇不多於三個字","examples":[{"en":"Students choose no more than three words from the passage.","zh":"學生從文章中選擇不多於三個字。"},{"en":"Choose no more than three words means the answer must contain three words or fewer.","zh":"choose no more than three words 指答案必須包含三個或更少英文詞。"},{"en":"If the instruction says no more than three words, writing four words may lose marks.","zh":"如果指示說不多於三個字，寫四個字可能失分。"},{"en":"Students should remove unnecessary articles if the grammar still works.","zh":"如果文法仍成立，學生應刪去不必要冠詞。"},{"en":"This phrase sets a strict word limit.","zh":"這個片語設定嚴格字數限制。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":17},{"front":"domestic animals","meaning":"家畜；馴養動物","examples":[{"en":"Domestic animals are compared with wild animals.","zh":"家畜與野生動物被作比較。"},{"en":"Domestic animals are animals kept, bred, or cared for by humans.","zh":"domestic animals 是由人類飼養、繁殖或照顧的動物。"},{"en":"Cows, sheep, dogs, and chickens are common domestic animals.","zh":"牛、羊、狗和雞都是常見家畜或馴養動物。"},{"en":"If domestic animals receive food and medical care, their lives may differ greatly from wild animals’ lives.","zh":"如果家畜得到食物和醫療照顧，其生活可能與野生動物大不相同。"},{"en":"This phrase contrasts human-managed animals with animals living freely in nature.","zh":"這個片語把人類管理的動物與自然中自由生活的動物作對比。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":17},{"front":"wild animals","meaning":"野生動物","examples":[{"en":"Wild animals often face predators and harsh conditions.","zh":"野生動物常面對掠食者和嚴酷條件。"},{"en":"Wild animals are animals that live in natural environments without regular human care.","zh":"wild animals 是生活在自然環境中、沒有定期人類照顧的動物。"},{"en":"Foxes, deer, lions, and eagles are examples of wild animals.","zh":"狐狸、鹿、獅子和鷹都是野生動物例子。"},{"en":"If wild animals are injured, they may not receive treatment and may become prey.","zh":"如果野生動物受傷，可能得不到治療，並可能成為獵物。"},{"en":"This phrase contrasts natural independence with the safety of human care.","zh":"這個片語把自然獨立與人類照顧下的安全作對比。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":17},{"front":"threatened by numerous","meaning":"受眾多……威脅","examples":[{"en":"Wild animals are threatened by numerous dangers.","zh":"野生動物受眾多危險威脅。"},{"en":"Threatened by numerous things means facing many different risks or dangers.","zh":"threatened by numerous things 指面對許多不同風險或危險。"},{"en":"Small shops may be threatened by numerous problems, including rent, competition, and weak sales.","zh":"小店可能受眾多問題威脅，包括租金、競爭和銷售疲弱。"},{"en":"If animals face predators, hunger, disease, and drought, their survival is uncertain.","zh":"如果動物面對掠食者、飢餓、疾病和旱災，其生存並不確定。"},{"en":"This phrase stresses that danger comes from many sources.","zh":"這個片語強調危險來自許多來源。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":17},{"front":"have some quality of life","meaning":"有某程度的生活質素","examples":[{"en":"Domestic animals may have some quality of life.","zh":"家畜可能有某程度的生活質素。"},{"en":"To have some quality of life means to have a certain level of comfort, safety, or well-being.","zh":"have some quality of life 指有一定程度的舒適、安全或幸福。"},{"en":"An elderly patient may still have some quality of life if pain is controlled and family visits often.","zh":"如果老人病人的痛楚受控制且家人常探望，他仍可能有某程度的生活質素。"},{"en":"If farm animals are fed and protected, the writer argues they are not suffering all the time.","zh":"如果農場動物有食物和保護，作者便主張牠們不是一直受苦。"},{"en":"This phrase is cautious and does not claim a perfect life.","zh":"這個片語較謹慎，並沒有聲稱完美生活。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":17},{"front":"unlikely to have","meaning":"不大可能有","examples":[{"en":"Wild animals are unlikely to have an easy existence.","zh":"野生動物不大可能有安逸的生活。"},{"en":"Unlikely to have means probably do not have.","zh":"unlikely to have 指很可能沒有。"},{"en":"A student who never sleeps enough is unlikely to have strong concentration in morning lessons.","zh":"從不睡夠的學生不大可能在早課有強專注力。"},{"en":"If animals face constant danger, they are unlikely to have peaceful lives.","zh":"如果動物面對持續危險，牠們不大可能有平靜生活。"},{"en":"This phrase expresses probability rather than certainty.","zh":"這個片語表達可能性，而不是確定性。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":17},{"front":"complete the table below","meaning":"完成下表","examples":[{"en":"Students complete the table below with terms from the text.","zh":"學生用文本中的用語完成下表。"},{"en":"Complete the table below means fill in the missing parts of the table that follows.","zh":"complete the table below 指填寫下面表格中缺少的部分。"},{"en":"Students should complete the table below only after locating the relevant sentences in the passage.","zh":"學生應先定位文章中的相關句子，再完成下表。"},{"en":"If the table asks for terms, candidates should copy the exact wording from the text.","zh":"如果表格要求用語，考生應從文本中抄下確切措辭。"},{"en":"This phrase is a standard instruction in reading exercises.","zh":"這個片語是閱讀練習中的標準指示。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":17},{"front":"no more than two words","meaning":"不多於兩個字","examples":[{"en":"The answer must contain no more than two words.","zh":"答案必須包含不多於兩個字。"},{"en":"No more than two words means the answer can have one or two words only.","zh":"no more than two words 指答案只能有一個或兩個英文詞。"},{"en":"If the correct idea is “domestic animals,” writing “the domestic animals” may break the word limit.","zh":"如果正確意思是 “domestic animals”，寫 “the domestic animals” 可能超出字數限制。"},{"en":"Students should count words carefully before writing the final answer.","zh":"學生寫下最終答案前應仔細數字數。"},{"en":"This phrase sets a strict maximum length for exam answers.","zh":"這個片語為考試答案設定嚴格最高長度。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":17},{"front":"find two interesting terms","meaning":"找出兩個有趣用語","examples":[{"en":"Students find two interesting terms used in the text.","zh":"學生找出文中使用的兩個有趣用語。"},{"en":"To find two interesting terms means to locate two notable words or phrases in the passage.","zh":"find two interesting terms 指在文章中定位兩個值得注意的詞語或片語。"},{"en":"In a vocabulary task, students may find two interesting terms that show the writer’s attitude.","zh":"在詞彙題中，學生可能找出兩個顯示作者態度的有趣用語。"},{"en":"If a term is humorous or mocking, it may reveal more than a neutral word would.","zh":"如果用語幽默或嘲諷，它可能比中性詞揭示更多。"},{"en":"This phrase asks students to notice language choice, not just meaning.","zh":"這個片語要求學生注意語言選擇，而不只是意思。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":18},{"front":"used in the text to refer to","meaning":"在文中用來指","examples":[{"en":"The terms are used in the text to refer to different groups.","zh":"這些用語在文中用來指不同群體。"},{"en":"Used in the text to refer to means the passage uses the words to name or describe something.","zh":"used in the text to refer to 指文章使用某些字詞來命名或描述某事物。"},{"en":"A passage may use “young minds” to refer to students.","zh":"文章可能使用 “young minds” 來指學生。"},{"en":"If a term refers to a group mockingly, students should notice the writer’s tone.","zh":"如果用語以嘲諷方式指某群體，學生應注意作者語氣。"},{"en":"This phrase asks candidates to connect wording with reference.","zh":"這個片語要求考生把措辭與所指對象連接起來。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":18},{"front":"one term","meaning":"一個用語","examples":[{"en":"The table gives one term and asks for another.","zh":"表格給出一個用語，並要求另一個。"},{"en":"One term means one word or phrase used for a particular idea or group.","zh":"one term 指用來表達某個概念或群體的一個詞或片語。"},{"en":"In a vocabulary list, one term may have several possible translations depending on context.","zh":"在詞彙表中，一個用語可能因語境而有幾個可能譯法。"},{"en":"If a question gives one term, students may need to find another term with the same reference.","zh":"如果題目給出一個用語，學生可能需要找出另一個指向相同對象的用語。"},{"en":"This phrase focuses on vocabulary items, not whole sentences.","zh":"這個片語聚焦於詞彙項目，而不是整句。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":18},{"front":"another term","meaning":"另一個用語","examples":[{"en":"Students must find another term with a similar reference.","zh":"學生必須找出另一個有相似所指的用語。"},{"en":"Another term means a different word or phrase used to express a similar idea.","zh":"another term 指用來表達相似概念的另一個詞或片語。"},{"en":"A passage may use “teenagers” and another term such as “young people.”","zh":"文章可能使用 “teenagers” 和另一個用語，例如 “young people”。"},{"en":"If writers use several terms for one group, students must track the reference carefully.","zh":"如果作者用幾個用語指同一群體，學生必須仔細追蹤所指。"},{"en":"This phrase is useful in vocabulary and reference questions.","zh":"這個片語適用於詞彙和指代題。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":18},{"front":"sheep and cattle","meaning":"羊和牛","examples":[{"en":"Sheep and cattle are referred to humorously in the passage.","zh":"羊和牛在文章中被幽默地提及。"},{"en":"Sheep and cattle are farm animals commonly raised for meat, milk, wool, or leather.","zh":"sheep and cattle 是常被飼養以取得肉、奶、羊毛或皮革的農場動物。"},{"en":"A farmer may keep sheep on hillsides and cattle in lower pastures.","zh":"農夫可能在山坡養羊，在較低牧場養牛。"},{"en":"If sheep and cattle are described as “cud-chewing cousins,” the writer is using humour.","zh":"如果羊和牛被描述為「反芻的親戚」，作者就是在使用幽默。"},{"en":"This phrase groups two familiar kinds of farm animals.","zh":"這個片語把兩種熟悉農場動物歸為一組。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":18},{"front":"lazy people","meaning":"懶散的人","examples":[{"en":"The question asks for terms used to refer to lazy people.","zh":"題目要求找出用來指懶散的人的用語。"},{"en":"Lazy people are people who avoid effort, work, or physical activity.","zh":"lazy people 是避免努力、工作或身體活動的人。"},{"en":"A lazy student may leave homework until the last minute and then copy answers.","zh":"懶散學生可能把功課拖到最後一刻，然後抄答案。"},{"en":"If people sit all day and never exercise, a writer may jokingly call them couch potatoes.","zh":"如果人們整天坐着並從不運動，作者可能開玩笑稱他們為梳化薯仔。"},{"en":"This phrase describes behaviour, but it can sound judgemental.","zh":"這個片語描述行為，但可能聽起來帶評判。"}],"source":"88 - A Meat-Eater’s Counter.pdf","sourcePage":18}],"ielts/reading/passage-2/Practice 89":[{"front":"The War of Currents","meaning":"電流之戰","examples":[{"en":"The War of Currents was a bitter feud between supporters of AC and DC electricity.","zh":"電流之戰是交流電和直流電支持者之間的激烈爭鬥。"},{"en":"The War of Currents was a conflict over whether alternating current or direct current should dominate electricity supply.","zh":"電流之戰是一場關於交流電還是直流電應主導供電的衝突。"},{"en":"A business can have its own war of currents when two teams strongly support different systems.","zh":"當兩個團隊強烈支持不同系統時，一間公司也可能有自己的「電流之戰」。"},{"en":"Because Edison backed DC and Westinghouse backed AC, the debate became a public and commercial battle.","zh":"因為愛迪生支持直流電，而 Westinghouse 支持交流電，這場辯論變成公開而商業性的鬥爭。"},{"en":"The phrase describes not a real military war, but a fierce technological rivalry.","zh":"這個短語描述的不是實際軍事戰爭，而是激烈的科技競爭。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":1},{"front":"be delivered in","meaning":"以……形式輸送","examples":[{"en":"Electricity can be delivered in either alternating current or direct current.","zh":"電力可以交流電或直流電形式輸送。"},{"en":"To be delivered in a form means to be supplied or sent using that form.","zh":"be delivered in 某形式，指以該形式供應或送出。"},{"en":"A lesson can be delivered in person, online, or through recorded videos.","zh":"課堂可以面授、網上或錄影片段形式提供。"},{"en":"If information is delivered in a simple format, students understand it more easily.","zh":"如果資訊以簡單形式傳遞，學生會更容易理解。"},{"en":"The phrase focuses on the form or method used to send something.","zh":"這個短語重點在於輸送某物所用的形式或方法。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":1},{"front":"alternating current","meaning":"交流電","examples":[{"en":"Alternating current became the dominant system for electricity delivery.","zh":"交流電成為電力輸送的主導系統。"},{"en":"Alternating current is electric current that repeatedly changes direction.","zh":"alternating current 是會反覆改變方向的電流。"},{"en":"Most homes use alternating current because it can be transmitted efficiently over long distances.","zh":"大多數家庭使用交流電，因為它可以高效地遠距離傳輸。"},{"en":"Because alternating current can be transformed to different voltages, it became useful for power grids.","zh":"因為交流電可以轉換成不同電壓，它對電網變得有用。"},{"en":"The phrase is often shortened to AC.","zh":"這個短語常縮寫為 AC。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":1},{"front":"direct current","meaning":"直流電","examples":[{"en":"Thomas Edison heavily favoured direct current from the start.","zh":"Thomas Edison 從一開始就非常支持直流電。"},{"en":"Direct current is electric current that flows in one constant direction.","zh":"direct current 是只向一個固定方向流動的電流。"},{"en":"Batteries usually provide direct current to devices such as torches and remote controls.","zh":"電池通常向電筒和遙控器等裝置提供直流電。"},{"en":"Because direct current was hard to transform cheaply, it was less suitable for long-distance supply.","zh":"因為直流電難以低成本轉換電壓，所以較不適合遠距離供電。"},{"en":"The phrase is often shortened to DC.","zh":"這個短語常縮寫為 DC。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":1},{"front":"in the late 1880s","meaning":"在十九世紀八十年代後期","examples":[{"en":"In the late 1880s, electricity delivery was still developing in America.","zh":"在十九世紀八十年代後期，美國的電力輸送仍在發展中。"},{"en":"In the late 1880s means during the final years of the 1880s decade.","zh":"in the late 1880s 指1880年代最後幾年。"},{"en":"In the late 1880s, many cities were still learning how to use electricity safely.","zh":"在十九世紀八十年代後期，許多城市仍在學習如何安全使用電力。"},{"en":"If a technology was new in the late 1880s, people often debated how it should be controlled.","zh":"如果一項科技在十九世紀八十年代後期仍很新，人們常會辯論應如何規管它。"},{"en":"The phrase places an event near the end of the nineteenth century.","zh":"這個短語把事件放在十九世紀接近末段的位置。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":1},{"front":"with something in its infancy","meaning":"在……仍處於起步階段時","examples":[{"en":"With electricity delivery in its infancy, many people debated which system was better.","zh":"在電力輸送仍處於起步階段時，許多人辯論哪個系統較好。"},{"en":"With something in its infancy means while it is still at an early stage of development.","zh":"with something in its infancy 指某事仍處於早期發展階段時。"},{"en":"With online learning in its infancy, many schools made mistakes with platforms and timetables.","zh":"在網上學習仍處於起步階段時，許多學校在平台和時間表上都犯錯。"},{"en":"When a technology is in its infancy, standards are unclear and experiments are common.","zh":"當一項科技處於起步階段，標準通常不清晰，實驗也很常見。"},{"en":"The phrase suggests something is young, undeveloped, and still changing.","zh":"這個短語暗示某事年輕、未成熟，仍在變化。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":1},{"front":"in its infancy","meaning":"處於起步階段","examples":[{"en":"Electricity delivery was still in its infancy in the late 1880s.","zh":"在十九世紀八十年代後期，電力輸送仍處於起步階段。"},{"en":"In its infancy means at the beginning of development.","zh":"in its infancy 指處於發展的開始階段。"},{"en":"The project is still in its infancy, so the team is testing basic ideas.","zh":"這個項目仍處於起步階段，所以團隊正在測試基本想法。"},{"en":"If a business is in its infancy, it may not yet have stable customers or income.","zh":"如果一間企業處於起步階段，它可能尚未有穩定顧客或收入。"},{"en":"The phrase describes an early stage, not a literal baby.","zh":"這個短語描述早期階段，而不是字面上的嬰兒。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":1},{"front":"initially seemed clear","meaning":"起初看似很清楚","examples":[{"en":"It initially seemed clear which electricity system was superior.","zh":"起初看似很清楚哪個電力系統較優勝。"},{"en":"Initially seemed clear means appeared obvious at first, before later evidence made things less simple.","zh":"initially seemed clear 指起初似乎很明顯，但後來證據令事情變得不再簡單。"},{"en":"It initially seemed clear that the cheaper phone was better, until its battery failed quickly.","zh":"起初看似很清楚較便宜的手機更好，直到它的電池很快壞掉。"},{"en":"If a solution initially seems clear, people may still need to test it carefully.","zh":"如果一個解決方法起初看似很清楚，人們仍可能需要仔細測試。"},{"en":"The phrase often introduces a first impression that may later change.","zh":"這個短語常引出一個後來可能改變的第一印象。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":1},{"front":"which system was superior","meaning":"哪個系統較優勝","examples":[{"en":"Engineers debated which system was superior.","zh":"工程師辯論哪個系統較優勝。"},{"en":"Which system was superior means which system was better, stronger, or more effective.","zh":"which system was superior 指哪個系統更好、更強或更有效。"},{"en":"Students may compare two revision methods to decide which system is superior.","zh":"學生可能比較兩種溫習方法，以決定哪個系統較優勝。"},{"en":"If one system saves more money and works more reliably, people may judge it superior.","zh":"如果一個系統更省錢且更可靠，人們可能判斷它較優勝。"},{"en":"The phrase is used when comparing competing methods or designs.","zh":"這個短語用於比較互相競爭的方法或設計。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":1},{"front":"home-grown American inventor","meaning":"土生土長的美國發明家","examples":[{"en":"Thomas Edison was a home-grown American inventor.","zh":"Thomas Edison 是土生土長的美國發明家。"},{"en":"A home-grown American inventor is an inventor developed within America rather than arriving from abroad.","zh":"home-grown American inventor 指在美國本土成長起來，而不是從外國來的發明家。"},{"en":"A home-grown designer may understand local habits better than an overseas consultant.","zh":"土生土長的設計師可能比海外顧問更理解本地習慣。"},{"en":"Because Edison was home-grown, Americans often saw him as a national success story.","zh":"因為愛迪生是土生土長的美國人，美國人常把他視為國家成功故事。"},{"en":"The phrase stresses local origin and national identity.","zh":"這個短語強調本地來源和國家身份。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":1},{"front":"heavily favour","meaning":"非常支持","examples":[{"en":"Edison heavily favoured DC from the start.","zh":"愛迪生從一開始就非常支持直流電。"},{"en":"To heavily favour something means to strongly prefer or support it.","zh":"heavily favour 某事，意思是強烈偏好或支持它。"},{"en":"A school may heavily favour small classes because teachers can give more feedback.","zh":"學校可能非常支持小班教學，因為老師可以給更多回饋。"},{"en":"If managers heavily favour one plan, other ideas may receive less attention.","zh":"如果管理層非常支持一個計劃，其他想法可能得到較少注意。"},{"en":"The phrase suggests strong preference, not mild interest.","zh":"這個短語暗示強烈偏好，而不是輕微興趣。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":2},{"front":"from the start","meaning":"從一開始","examples":[{"en":"Edison supported direct current from the start.","zh":"愛迪生從一開始就支持直流電。"},{"en":"From the start means from the beginning of a process or situation.","zh":"from the start 指從一個過程或情況的開始。"},{"en":"A teacher should explain the rules from the start so students know what to expect.","zh":"老師應從一開始解釋規則，讓學生知道會發生甚麼。"},{"en":"If a team disagrees from the start, the project may need clearer leadership.","zh":"如果團隊從一開始就意見不合，項目可能需要更清晰領導。"},{"en":"The phrase marks the earliest point in time.","zh":"這個短語標示最早時間點。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":2},{"front":"the limitations of","meaning":"……的限制","examples":[{"en":"The limitations of Edison’s system became increasingly obvious.","zh":"愛迪生系統的限制變得越來越明顯。"},{"en":"The limitations of something are the weaknesses or boundaries that stop it from working well.","zh":"the limitations of 某物，是阻止它良好運作的弱點或界限。"},{"en":"The limitations of a small classroom become clear when thirty students need group work.","zh":"當三十名學生需要小組活動，小課室的限制就會變得清楚。"},{"en":"If the limitations of a plan are ignored, problems may appear later.","zh":"如果計劃的限制被忽視，問題可能稍後出現。"},{"en":"The phrase helps explain why a system may not be enough.","zh":"這個短語幫助解釋為何一個系統可能不足夠。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":2},{"front":"become increasingly obvious","meaning":"變得越來越明顯","examples":[{"en":"The advantages of AC became increasingly obvious over time.","zh":"交流電的優勢隨時間變得越來越明顯。"},{"en":"To become increasingly obvious means to become clearer and easier to notice gradually.","zh":"become increasingly obvious 指逐漸變得更清楚、更容易注意到。"},{"en":"After several late assignments, the student’s time-management problem became increasingly obvious.","zh":"交了幾次遲功課後，學生的時間管理問題變得越來越明顯。"},{"en":"If costs keep rising, the need for a new budget becomes increasingly obvious.","zh":"如果成本持續上升，制定新預算的需要會變得越來越明顯。"},{"en":"The phrase shows that evidence builds up over time.","zh":"這個短語顯示證據隨時間累積。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":2},{"front":"the advantages of","meaning":"……的優勢","examples":[{"en":"The advantages of AC eventually became clear.","zh":"交流電的優勢最終變得清楚。"},{"en":"The advantages of something are the benefits or strong points it offers.","zh":"the advantages of 某物，是它提供的好處或強項。"},{"en":"The advantages of online lessons include saved travel time and easier access to recordings.","zh":"網課的優勢包括節省交通時間和更容易取得錄影片段。"},{"en":"If the advantages of a system outweigh its problems, people may adopt it widely.","zh":"如果一個系統的優勢大於其問題，人們可能廣泛採用它。"},{"en":"The phrase is used when explaining why one choice is useful.","zh":"這個短語用於解釋為何某選擇有用。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":2},{"front":"despite someone’s best efforts","meaning":"儘管某人盡了最大努力","examples":[{"en":"Despite Edison’s best efforts, his campaign for DC failed.","zh":"儘管愛迪生盡了最大努力，他支持直流電的運動仍然失敗。"},{"en":"Despite someone’s best efforts means although that person tried very hard.","zh":"despite someone’s best efforts 指雖然某人非常努力。"},{"en":"Despite the teacher’s best efforts, some students still forgot their homework.","zh":"儘管老師盡了最大努力，一些學生仍忘記交功課。"},{"en":"If a plan fails despite everyone’s best efforts, the problem may be deeper than effort alone.","zh":"如果計劃在大家盡最大努力後仍失敗，問題可能比努力不足更深。"},{"en":"The phrase contrasts hard work with an unsuccessful result.","zh":"這個短語把努力與不成功結果作對比。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":2},{"front":"crusade","meaning":"運動；堅定的行動","examples":[{"en":"Edison’s crusade against AC would ultimately be lost.","zh":"愛迪生反對交流電的運動最終會失敗。"},{"en":"A crusade is a strong, determined campaign for or against something.","zh":"crusade 是支持或反對某事的強烈而堅定的運動。"},{"en":"A parent may begin a crusade for safer roads after an accident near school.","zh":"學校附近發生意外後，家長可能展開爭取更安全道路的運動。"},{"en":"If a crusade becomes too emotional, people may ignore evidence from the other side.","zh":"如果一場運動變得太情緒化，人們可能忽略另一方的證據。"},{"en":"The word suggests a long and passionate struggle.","zh":"這個字暗示長期而熱烈的鬥爭。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":2},{"front":"ultimately be lost","meaning":"最終失敗","examples":[{"en":"Edison’s crusade against AC would ultimately be lost.","zh":"愛迪生反對交流電的運動最終會失敗。"},{"en":"To ultimately be lost means to fail in the end after a struggle or process.","zh":"ultimately be lost 指經過鬥爭或過程後，最終失敗。"},{"en":"A court case may ultimately be lost if there is not enough evidence.","zh":"如果證據不足，一宗官司可能最終失敗。"},{"en":"If a company refuses to change, its market battle may ultimately be lost.","zh":"如果公司拒絕改變，它的市場戰可能最終失敗。"},{"en":"The phrase focuses on the final result, not temporary progress.","zh":"這個短語重點在最終結果，而不是短暫進展。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":2},{"front":"Edison’s team","meaning":"愛迪生的團隊","examples":[{"en":"Edison’s team at Menlo Park improved the electric light bulb.","zh":"愛迪生在門洛帕克的團隊改良了電燈泡。"},{"en":"Edison’s team refers to the group of workers and inventors who worked with Edison.","zh":"Edison’s team 指與愛迪生一起工作的工人和發明家群體。"},{"en":"A teacher’s team may include assistants, tutors and curriculum designers.","zh":"老師的團隊可能包括助教、導師和課程設計者。"},{"en":"Because Edison’s team worked together, they could test many ideas quickly.","zh":"因為愛迪生的團隊一起工作，他們可以快速測試許多想法。"},{"en":"The phrase reminds us that invention often involves groups, not only one person.","zh":"這個短語提醒我們，發明常涉及團隊，而不只是個人。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":2},{"front":"Menlo Park","meaning":"門洛帕克","examples":[{"en":"Edison’s team worked at Menlo Park.","zh":"愛迪生的團隊在門洛帕克工作。"},{"en":"Menlo Park was the place where Edison and his team carried out important experiments.","zh":"Menlo Park 是愛迪生和其團隊進行重要實驗的地方。"},{"en":"A research centre can become famous like Menlo Park if many useful inventions are developed there.","zh":"如果一個研究中心發展出許多有用發明，它也可能像門洛帕克一樣出名。"},{"en":"Because work at Menlo Park was organised, Edison’s team could improve devices systematically.","zh":"因為門洛帕克的工作有組織，愛迪生的團隊能有系統地改良裝置。"},{"en":"The phrase names a place strongly linked with Edison’s inventions.","zh":"這個短語指出一個與愛迪生發明密切相關的地方。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":2},{"front":"improve the electric light bulb","meaning":"改良電燈泡","examples":[{"en":"Edison’s team improved the electric light bulb in 1879.","zh":"愛迪生的團隊在1879年改良了電燈泡。"},{"en":"To improve the electric light bulb means to make the bulb work better, longer, or more reliably.","zh":"improve the electric light bulb 指令電燈泡運作得更好、更持久或更可靠。"},{"en":"Engineers improve a classroom projector when they make it brighter and less likely to overheat.","zh":"工程師令課室投影機更光亮且較不易過熱時，就是在改良它。"},{"en":"If inventors improve a common device, it can become useful for many more people.","zh":"如果發明家改良常見裝置，它就能對更多人有用。"},{"en":"The phrase focuses on making an existing invention more practical.","zh":"這個短語重點在令現有發明更實用。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":3},{"front":"electric light bulb","meaning":"電燈泡","examples":[{"en":"The electric light bulb required a reliable electricity supply.","zh":"電燈泡需要可靠的電力供應。"},{"en":"An electric light bulb is a device that produces light when electricity passes through it.","zh":"electric light bulb 是通電時產生光的裝置。"},{"en":"A classroom needs electric light bulbs so students can read clearly on dark days.","zh":"課室需要電燈泡，讓學生在天色昏暗時也能清楚閱讀。"},{"en":"If electric light bulbs became common, homes and streets could be lit after sunset.","zh":"如果電燈泡變得普及，家庭和街道就能在日落後照明。"},{"en":"The phrase names a basic device that helped change daily life.","zh":"這個短語指出一種改變日常生活的基本裝置。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":3},{"front":"electricity distribution system","meaning":"配電系統","examples":[{"en":"Edison needed an efficient electricity distribution system.","zh":"愛迪生需要一個高效配電系統。"},{"en":"An electricity distribution system carries electricity from a source to users.","zh":"electricity distribution system 把電力由來源輸送到用戶。"},{"en":"A city’s electricity distribution system includes wires, stations and connections to homes.","zh":"城市的配電系統包括電線、電站和連接到住戶的線路。"},{"en":"If the distribution system is weak, power may not reach customers reliably.","zh":"如果配電系統薄弱，電力可能無法可靠地到達用戶。"},{"en":"The phrase focuses on how electricity is delivered, not how it is used.","zh":"這個短語重點在電力如何被輸送，而不是如何被使用。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":3},{"front":"efficient electricity distribution system","meaning":"高效配電系統","examples":[{"en":"Edison needed an efficient electricity distribution system to profit from the light bulb.","zh":"愛迪生需要高效配電系統，才能從電燈泡獲利。"},{"en":"An efficient electricity distribution system delivers power with little waste, delay, or loss.","zh":"efficient electricity distribution system 指以少浪費、少延誤、少損耗方式輸送電力的系統。"},{"en":"A school needs an efficient system if many classrooms use computers at the same time.","zh":"如果許多課室同時使用電腦，學校就需要高效系統。"},{"en":"If distribution is efficient, less energy is lost before electricity reaches users.","zh":"如果配電高效，電力到達用戶前損失較少。"},{"en":"The phrase links good engineering with practical and financial success.","zh":"這個短語把良好工程與實際和財務成功連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":3},{"front":"capitalise on","meaning":"利用……獲利；把握……的商機","examples":[{"en":"Edison needed a distribution system to capitalise on the electric light bulb.","zh":"愛迪生需要一個配電系統，才能利用電燈泡獲利。"},{"en":"To capitalise on something means to use an opportunity to gain benefit or profit.","zh":"capitalise on 某事，指利用機會取得好處或利潤。"},{"en":"A shop may capitalise on a festival by selling special food and decorations.","zh":"商店可能透過出售節日食品和裝飾，把握節日商機。"},{"en":"If a company cannot deliver its product, it cannot capitalise on public interest.","zh":"如果公司無法交付產品，它就不能利用公眾興趣獲利。"},{"en":"The phrase shows using an advantage before the chance disappears.","zh":"這個短語表示在機會消失前善用優勢。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":3},{"front":"found a company","meaning":"創辦公司","examples":[{"en":"Edison founded the Edison Illuminating Company in 1880.","zh":"愛迪生在1880年創辦了愛迪生照明公司。"},{"en":"To found a company means to start or establish a business.","zh":"found a company 指創立或建立一間企業。"},{"en":"A teacher may found a small education company after years of tutoring students.","zh":"老師在多年補習經驗後，可能創辦一間小型教育公司。"},{"en":"If someone founds a company, they must arrange money, staff and customers.","zh":"如果某人創辦公司，就必須安排資金、人手和顧客。"},{"en":"The phrase focuses on creating a business from the beginning.","zh":"這個短語重點在從零開始建立企業。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":3},{"front":"Edison Illuminating Company","meaning":"愛迪生照明公司","examples":[{"en":"Edison founded the Edison Illuminating Company in 1880.","zh":"愛迪生在1880年創辦了愛迪生照明公司。"},{"en":"The Edison Illuminating Company was Edison’s company for supplying electric light and power.","zh":"Edison Illuminating Company 是愛迪生供應電燈和電力的公司。"},{"en":"A company like the Edison Illuminating Company needed customers close enough to receive electricity.","zh":"像愛迪生照明公司這樣的企業，需要距離足夠近的客戶接收電力。"},{"en":"Because electricity delivery was new, the company had to prove that electric lighting could work reliably.","zh":"因為電力輸送仍很新，公司必須證明電力照明能可靠運作。"},{"en":"The phrase names a business linked with Edison’s electricity system.","zh":"這個短語指出一間與愛迪生電力系統相關的公司。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":3},{"front":"construct a generating station","meaning":"建造發電站","examples":[{"en":"Edison constructed a generating station providing direct current.","zh":"愛迪生建造了一座提供直流電的發電站。"},{"en":"To construct a generating station means to build a facility that produces electricity.","zh":"construct a generating station 指建造一個生產電力的設施。"},{"en":"A town may construct a generating station if it needs a local power supply.","zh":"如果小鎮需要本地電力供應，它可能建造發電站。"},{"en":"If a generating station is built near customers, less electricity is lost during delivery.","zh":"如果發電站建在客戶附近，輸送期間損失的電力會較少。"},{"en":"The phrase describes building the source of electrical power.","zh":"這個短語描述建造電力來源。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":3},{"front":"generating station","meaning":"發電站","examples":[{"en":"The generating station provided 110 volts of direct current.","zh":"該發電站提供110伏特直流電。"},{"en":"A generating station is a place where electricity is produced before being sent to users.","zh":"generating station 是電力送往用戶前被生產的地方。"},{"en":"A city may depend on several generating stations to keep homes and hospitals powered.","zh":"城市可能依賴幾座發電站，讓住戶和醫院保持供電。"},{"en":"If a generating station fails, nearby users may lose electricity.","zh":"如果發電站故障，附近用戶可能停電。"},{"en":"The phrase refers to a power-production facility.","zh":"這個短語指生產電力的設施。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":3},{"front":"provide 110 volts of","meaning":"提供110伏特的……","examples":[{"en":"The station provided 110 volts of direct current.","zh":"該發電站提供110伏特直流電。"},{"en":"To provide 110 volts of electricity means to supply electricity at that voltage level.","zh":"provide 110 volts of electricity 指以該電壓水平供應電力。"},{"en":"A charger must provide the correct voltage so a device does not break.","zh":"充電器必須提供正確電壓，裝置才不會損壞。"},{"en":"If a system provides too low a voltage, machines may not work properly.","zh":"如果系統提供的電壓太低，機器可能不能正常運作。"},{"en":"The phrase states the amount and type of electrical supply.","zh":"這個短語說明電力供應的數量和種類。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":3},{"front":"have drawbacks","meaning":"有缺點","examples":[{"en":"Edison’s direct-current system had several drawbacks.","zh":"愛迪生的直流電系統有幾個缺點。"},{"en":"To have drawbacks means to have disadvantages or problems.","zh":"have drawbacks 指有缺點或問題。"},{"en":"Online learning has drawbacks if students lack quiet space at home.","zh":"如果學生家中沒有安靜空間，網上學習就有缺點。"},{"en":"If a cheap product has many drawbacks, customers may choose a more expensive but reliable one.","zh":"如果便宜產品有許多缺點，顧客可能選擇較貴但可靠的產品。"},{"en":"The phrase helps show that something useful is not perfect.","zh":"這個短語幫助說明有用的東西並不完美。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":4},{"front":"low voltage","meaning":"低電壓","examples":[{"en":"Low voltage created problems for Edison’s system.","zh":"低電壓為愛迪生的系統造成問題。"},{"en":"Low voltage means a relatively small electrical pressure pushing current through a circuit.","zh":"low voltage 指推動電流通過電路的電壓相對較低。"},{"en":"Some small household devices use low voltage for safety.","zh":"一些小型家用裝置使用低電壓以保障安全。"},{"en":"If voltage is too low for long-distance transmission, much energy may be lost.","zh":"如果電壓對長距離輸電來說太低，許多能量可能流失。"},{"en":"The phrase is important when discussing electrical safety and power delivery.","zh":"這個短語在討論電力安全和電力輸送時很重要。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":4},{"front":"correspondingly higher current","meaning":"相應較高的電流","examples":[{"en":"Because of the low voltage, a correspondingly higher current flowed.","zh":"由於電壓低，流動的是相應較高的電流。"},{"en":"Correspondingly higher current means the current becomes higher as a related result of another change.","zh":"correspondingly higher current 指電流因另一項相關變化而相應變高。"},{"en":"If a classroom has fewer teachers, each teacher may face a correspondingly higher workload.","zh":"如果課室教師較少，每位老師可能面對相應較高的工作量。"},{"en":"When voltage is low, a higher current may be needed to deliver the same power.","zh":"當電壓低時，可能需要較高電流來輸送同樣功率。"},{"en":"The phrase shows a matching increase caused by another factor.","zh":"這個短語顯示由另一因素造成的相應增加。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":4},{"front":"electrical resistance","meaning":"電阻","examples":[{"en":"Electrical resistance in the wires reduced the voltage over distance.","zh":"電線中的電阻隨距離降低電壓。"},{"en":"Electrical resistance is the opposition that slows the flow of electric current.","zh":"electrical resistance 是阻礙電流流動的阻力。"},{"en":"A thin wire may have more electrical resistance than a thicker wire.","zh":"較幼的電線可能比較粗的電線有更高電阻。"},{"en":"If electrical resistance is high, energy can be lost as heat.","zh":"如果電阻很高，能量可能以熱的形式流失。"},{"en":"The phrase explains why electricity can weaken as it travels.","zh":"這個短語解釋為何電力在傳輸時會減弱。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":4},{"front":"transmission wires","meaning":"輸電線","examples":[{"en":"The electrical resistance of the transmission wires reduced the voltage.","zh":"輸電線的電阻降低了電壓。"},{"en":"Transmission wires are wires that carry electricity from one place to another.","zh":"transmission wires 是把電力從一地送到另一地的電線。"},{"en":"Transmission wires connect power stations with towns, homes and factories.","zh":"輸電線把發電站與城鎮、住戶和工廠連接起來。"},{"en":"If transmission wires are too long or thin, more power may be lost.","zh":"如果輸電線太長或太幼，可能有更多電力流失。"},{"en":"The phrase refers to wires used for delivery, not small wires inside a device.","zh":"這個短語指用於輸送的電線，而不是裝置內的小電線。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":4},{"front":"significantly reduce","meaning":"顯著降低","examples":[{"en":"The resistance of the wires significantly reduced the voltage.","zh":"電線的電阻顯著降低了電壓。"},{"en":"To significantly reduce something means to lower it by a large or important amount.","zh":"significantly reduce 某物，指大幅或重要地降低它。"},{"en":"Better street lighting can significantly reduce accidents at dangerous crossings.","zh":"更好的街燈可以顯著降低危險路口的意外。"},{"en":"If a new method significantly reduces costs, many companies may adopt it.","zh":"如果新方法顯著降低成本，許多公司可能採用它。"},{"en":"The phrase shows a change that is large enough to matter.","zh":"這個短語顯示變化大到有意義。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":4},{"front":"reduce the voltage","meaning":"降低電壓","examples":[{"en":"The transmission wires reduced the voltage over distance.","zh":"輸電線隨距離降低電壓。"},{"en":"To reduce the voltage means to lower the electrical pressure in a system.","zh":"reduce the voltage 指降低系統中的電壓。"},{"en":"A transformer can reduce the voltage before electricity enters a home.","zh":"變壓器可以在電力進入家庭前降低電壓。"},{"en":"If voltage is reduced too much, electrical devices may not work properly.","zh":"如果電壓降低太多，電器可能無法正常運作。"},{"en":"The phrase describes a decrease in electrical level.","zh":"這個短語描述電力水平下降。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":4},{"front":"over distance","meaning":"隨距離增加","examples":[{"en":"The voltage was reduced over distance.","zh":"電壓隨距離增加而降低。"},{"en":"Over distance means as something travels farther from its starting point.","zh":"over distance 指某物離開起點越遠時。"},{"en":"A runner’s speed may fall over distance during a long race.","zh":"在長跑中，跑手速度可能隨距離增加而下降。"},{"en":"If sound travels over distance, it becomes quieter before reaching the listener.","zh":"如果聲音傳過距離，到達聽者前會變得較細。"},{"en":"The phrase links change with increasing distance.","zh":"這個短語把變化與距離增加連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":4},{"front":"whatever thickness of wire is used","meaning":"無論使用多粗的電線","examples":[{"en":"Whatever thickness of wire is used, DC has a distance limitation.","zh":"無論使用多粗的電線，直流電都有距離限制。"},{"en":"Whatever thickness of wire is used means no matter how thick or thin the wire is.","zh":"whatever thickness of wire is used 指不論電線有多粗或多幼。"},{"en":"Whatever size of classroom is used, a noisy class still needs clear rules.","zh":"無論使用多大的課室，嘈吵班級仍需要清楚規則。"},{"en":"If a problem remains whatever method is used, the cause may be built into the system.","zh":"如果無論使用哪種方法問題仍存在，原因可能在系統本身。"},{"en":"The phrase shows that changing one detail does not solve the problem.","zh":"這個短語顯示改變一個細節不能解決問題。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":4},{"front":"a natural limitation","meaning":"自然限制","examples":[{"en":"There is a natural limitation in how far DC can be transmitted economically.","zh":"直流電可以符合經濟效益地傳輸多遠，有其自然限制。"},{"en":"A natural limitation is a built-in limit that comes from the nature of a system.","zh":"a natural limitation 是來自系統本身性質的內在限制。"},{"en":"There is a natural limitation to how long students can concentrate without rest.","zh":"學生不休息可以集中多久有其自然限制。"},{"en":"If a tool has a natural limitation, better planning may help but cannot remove it completely.","zh":"如果工具有自然限制，更好規劃可能有幫助，但不能完全消除它。"},{"en":"The phrase describes a limit that is not caused by laziness or poor effort.","zh":"這個短語描述不是由懶惰或努力不足造成的限制。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":4},{"front":"the distance over which","meaning":"……可傳送的距離","examples":[{"en":"There is a limit to the distance over which electricity can be transmitted.","zh":"電力可傳送的距離有一個限制。"},{"en":"The distance over which something happens means the range across which it can occur.","zh":"the distance over which 某事發生，指它可以發生或覆蓋的範圍。"},{"en":"The distance over which a school bus travels affects fuel cost and timetable design.","zh":"校巴可行駛的距離會影響燃油成本和時間表設計。"},{"en":"If the distance over which a signal travels is too long, the message may weaken.","zh":"如果訊號可傳送的距離太長，訊息可能變弱。"},{"en":"The phrase connects an action with the distance it can cover.","zh":"這個短語把一個動作與它能覆蓋的距離連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":5},{"front":"economically transmitted","meaning":"以符合經濟效益的方式傳輸","examples":[{"en":"DC electricity could not be economically transmitted over long distances.","zh":"直流電不能以符合經濟效益的方式長距離傳輸。"},{"en":"Economically transmitted means sent in a way that is financially practical and not too wasteful.","zh":"economically transmitted 指以財務上可行且不太浪費的方式傳送。"},{"en":"Food can be economically transported if the route is short and fuel costs are low.","zh":"如果路線短且燃油成本低，食物可以被符合經濟效益地運輸。"},{"en":"If electricity cannot be economically transmitted, customers far away become too expensive to serve.","zh":"如果電力不能以符合經濟效益的方式傳輸，遠方客戶的服務成本就會太高。"},{"en":"The phrase links technical delivery with cost.","zh":"這個短語把技術輸送與成本連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":5},{"front":"benefits to using","meaning":"使用……的好處","examples":[{"en":"There are benefits to using direct current.","zh":"使用直流電有好處。"},{"en":"Benefits to using something are the advantages gained from choosing it.","zh":"benefits to using 某物，是選擇它所得到的優勢。"},{"en":"There are benefits to using public transport, such as lower cost and less parking trouble.","zh":"使用公共交通有好處，例如成本較低和較少泊車問題。"},{"en":"If the benefits to using a system are clear, people may accept its weaknesses.","zh":"如果使用某系統的好處清楚，人們可能接受它的弱點。"},{"en":"The phrase introduces reasons why a choice may be useful.","zh":"這個短語引出某選擇有用的原因。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":5},{"front":"storage batteries","meaning":"蓄電池","examples":[{"en":"Storage batteries can be directly connected to a DC electricity grid.","zh":"蓄電池可以直接連接到直流電網。"},{"en":"Storage batteries store electrical energy for later use.","zh":"storage batteries 儲存電能以供之後使用。"},{"en":"A school may use storage batteries to keep emergency lights on during a power cut.","zh":"學校可能使用蓄電池，在停電時維持緊急照明。"},{"en":"If demand suddenly rises, storage batteries can supply extra power quickly.","zh":"如果需求突然上升，蓄電池可以快速供應額外電力。"},{"en":"The phrase refers to batteries used as part of a power system.","zh":"這個短語指作為電力系統一部分使用的電池。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":5},{"front":"be directly connected to","meaning":"直接連接到……","examples":[{"en":"Storage batteries can be directly connected to the electricity grid.","zh":"蓄電池可以直接連接到電網。"},{"en":"To be directly connected to something means to be joined to it without an extra middle system.","zh":"be directly connected to 某物，指不用額外中間系統而與它連接。"},{"en":"A printer can be directly connected to a computer with a cable.","zh":"打印機可以用電線直接連接到電腦。"},{"en":"If a device is directly connected to the grid, it can exchange power more quickly.","zh":"如果裝置直接連接到電網，它可以更快交換電力。"},{"en":"The phrase stresses a straight connection.","zh":"這個短語強調直接連接。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":5},{"front":"electricity grid","meaning":"電網","examples":[{"en":"Storage batteries can provide extra power to the electricity grid.","zh":"蓄電池可以向電網提供額外電力。"},{"en":"The electricity grid is the network that carries electricity from producers to users.","zh":"electricity grid 是把電力由生產者送到用戶的網絡。"},{"en":"Homes, hospitals and schools all depend on the electricity grid every day.","zh":"家庭、醫院和學校每天都依賴電網。"},{"en":"If the electricity grid is overloaded, power cuts may happen.","zh":"如果電網超負荷，可能發生停電。"},{"en":"The phrase refers to the shared power network, not one single wire.","zh":"這個短語指共用供電網絡，而不是單一電線。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":5},{"front":"give extra power","meaning":"提供額外電力","examples":[{"en":"Storage batteries give extra power during peaks of demand.","zh":"蓄電池在需求高峰時提供額外電力。"},{"en":"To give extra power means to supply additional electricity when normal supply is not enough.","zh":"give extra power 指在正常供應不足時供應額外電力。"},{"en":"A backup battery can give extra power to a laptop during a long journey.","zh":"後備電池可以在長途旅程中為手提電腦提供額外電力。"},{"en":"If many people use air conditioners at once, batteries can give extra power to the grid.","zh":"如果許多人同時使用冷氣，電池可以向電網提供額外電力。"},{"en":"The phrase describes support during high demand.","zh":"這個短語描述在高需求期間的支援。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":5},{"front":"meet sudden short-term peaks of demand","meaning":"應付突發的短期需求高峰","examples":[{"en":"Storage batteries can help meet sudden short-term peaks of demand.","zh":"蓄電池可以幫助應付突發的短期需求高峰。"},{"en":"To meet sudden short-term peaks of demand means to supply enough when demand quickly rises for a short time.","zh":"meet sudden short-term peaks of demand 指在需求短時間快速上升時提供足夠供應。"},{"en":"A café needs extra staff to meet sudden short-term peaks of demand during lunch.","zh":"咖啡店午餐時間需要額外員工來應付突發的短期需求高峰。"},{"en":"If power demand jumps during a heatwave, batteries can help prevent blackouts.","zh":"如果熱浪期間電力需求突然上升，電池可以幫助防止停電。"},{"en":"The phrase describes handling brief but intense demand.","zh":"這個短語描述處理短暫但強烈的需求。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":5},{"front":"short-term peaks of demand","meaning":"短期需求高峰","examples":[{"en":"The grid needed extra power during short-term peaks of demand.","zh":"電網在短期需求高峰期間需要額外電力。"},{"en":"Short-term peaks of demand are brief periods when many users need something at the same time.","zh":"short-term peaks of demand 是許多用戶同時需要某物的短暫時期。"},{"en":"A bus company faces short-term peaks of demand when school ends each day.","zh":"巴士公司每天放學時都面對短期需求高峰。"},{"en":"If businesses cannot handle short-term peaks of demand, customers may wait too long.","zh":"如果企業不能處理短期需求高峰，顧客可能等太久。"},{"en":"The phrase focuses on temporary spikes, not permanent growth.","zh":"這個短語重點在暫時急升，而不是永久增長。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":5},{"front":"backup during a breakdown in supply","meaning":"供電中斷時的後備電力","examples":[{"en":"Storage batteries can provide backup during a breakdown in supply.","zh":"蓄電池可以在供電中斷時提供後備電力。"},{"en":"Backup during a breakdown in supply means support when the normal supply stops working.","zh":"backup during a breakdown in supply 指正常供應停止時提供支援。"},{"en":"A hospital needs backup during a breakdown in electricity supply to protect patients.","zh":"醫院需要在供電中斷時有後備電力，以保護病人。"},{"en":"If backup is available, essential services can continue during a supply failure.","zh":"如果有後備支援，基本服務可以在供應故障期間繼續。"},{"en":"The phrase connects emergency support with interruption.","zh":"這個短語把緊急支援與中斷連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":5},{"front":"breakdown in supply","meaning":"供應中斷","examples":[{"en":"A breakdown in supply can interrupt electricity delivery.","zh":"供應中斷可以打斷電力輸送。"},{"en":"A breakdown in supply is a failure or interruption in the normal supply of something.","zh":"breakdown in supply 是某物正常供應出現故障或中斷。"},{"en":"A breakdown in water supply can force schools to close toilets temporarily.","zh":"食水供應中斷可能迫使學校暫時關閉洗手間。"},{"en":"If there is a breakdown in food supply, supermarkets may run out of basic goods.","zh":"如果食物供應中斷，超級市場可能缺乏基本貨品。"},{"en":"The phrase describes a serious interruption, not a small delay only.","zh":"這個短語描述嚴重中斷，而不只是小延誤。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":6},{"front":"furthermore","meaning":"此外","examples":[{"en":"Furthermore, there were no practical AC motors during Edison’s time.","zh":"此外，在愛迪生的時代沒有實用的交流電摩打。"},{"en":"Furthermore means in addition to what has already been said.","zh":"furthermore 指除了剛才所說之外。"},{"en":"The course is useful; furthermore, it is free for low-income students.","zh":"這個課程很有用；此外，它對低收入學生免費。"},{"en":"If an argument has several reasons, furthermore introduces another supporting point.","zh":"如果論點有幾個理由，furthermore 會引出另一個支持點。"},{"en":"The word helps add information in a formal way.","zh":"這個字幫助以正式方式補充資訊。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":6},{"front":"practical AC motors","meaning":"實用的交流電摩打","examples":[{"en":"There were no practical AC motors during Edison’s time.","zh":"在愛迪生的時代沒有實用的交流電摩打。"},{"en":"Practical AC motors are alternating-current motors that work reliably enough for real use.","zh":"practical AC motors 是可靠到足以實際使用的交流電摩打。"},{"en":"A factory needs practical motors, not experimental machines that fail every day.","zh":"工廠需要實用摩打，而不是每天故障的實驗機器。"},{"en":"Without practical AC motors, many machines could not easily run on alternating current.","zh":"沒有實用的交流電摩打，許多機器就難以用交流電運行。"},{"en":"The phrase stresses usefulness in real situations, not only theory.","zh":"這個短語強調真實情況中的用途，而不只是理論。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":6},{"front":"most of the load","meaning":"大部分用電負荷","examples":[{"en":"Most of the load consisted of incandescent light bulbs.","zh":"大部分用電負荷由白熾燈泡組成。"},{"en":"Most of the load means the largest part of the electricity being used.","zh":"most of the load 指正在使用電力中的最大部分。"},{"en":"In a school, most of the electrical load may come from air conditioners in summer.","zh":"在學校，夏天大部分用電負荷可能來自冷氣機。"},{"en":"If most of the load is lighting, the system is designed mainly to support lights.","zh":"如果大部分用電負荷是照明，系統就主要為支援燈具而設計。"},{"en":"The phrase refers to demand placed on an electrical system.","zh":"這個短語指放在電力系統上的需求。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":6},{"front":"consist of","meaning":"由……組成","examples":[{"en":"The load consisted mainly of incandescent light bulbs.","zh":"用電負荷主要由白熾燈泡組成。"},{"en":"To consist of something means to be made up of it.","zh":"consist of 某物，意思是由它組成。"},{"en":"A healthy lunch may consist of rice, vegetables, fish and fruit.","zh":"健康午餐可能由米飯、蔬菜、魚和水果組成。"},{"en":"If a class consists of beginners, the teacher should avoid advanced grammar at first.","zh":"如果一班由初學者組成，老師起初應避免高階文法。"},{"en":"The phrase describes what parts form a whole.","zh":"這個短語描述整體由哪些部分形成。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":6},{"front":"incandescent light bulbs","meaning":"白熾燈泡","examples":[{"en":"Incandescent light bulbs ran well on DC.","zh":"白熾燈泡在直流電下運作良好。"},{"en":"Incandescent light bulbs produce light by heating a thin wire until it glows.","zh":"incandescent light bulbs 透過加熱幼金屬絲至發光來產生光。"},{"en":"Older homes often used incandescent light bulbs before LED lights became common.","zh":"在 LED 燈普及前，舊式住宅常使用白熾燈泡。"},{"en":"Because incandescent bulbs could run on DC, Edison’s system worked well for lighting.","zh":"因為白熾燈泡可以用直流電運行，愛迪生的系統很適合照明。"},{"en":"The phrase refers to an older type of electric lamp.","zh":"這個短語指較舊式的電燈。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":6},{"front":"run well on","meaning":"在……下運作良好","examples":[{"en":"Incandescent light bulbs ran well on direct current.","zh":"白熾燈泡在直流電下運作良好。"},{"en":"To run well on something means to operate properly using that power source or system.","zh":"run well on 某物，指使用該動力來源或系統時正常運作。"},{"en":"Some apps run well on older phones because they do not need much memory.","zh":"有些應用程式在舊手機上運作良好，因為不需要太多記憶體。"},{"en":"If a machine runs well on one system, owners may not want to replace it.","zh":"如果機器在某系統下運作良好，擁有者可能不想更換它。"},{"en":"The phrase links good performance with a particular support system.","zh":"這個短語把良好表現與特定支援系統連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":6},{"front":"most importantly","meaning":"最重要的是","examples":[{"en":"Most importantly, Edison had patents for many DC devices.","zh":"最重要的是，愛迪生擁有許多直流電裝置的專利。"},{"en":"Most importantly introduces the most important point in a list or argument.","zh":"most importantly 用來引出清單或論證中最重要的一點。"},{"en":"The school is close and affordable; most importantly, the teachers are supportive.","zh":"這間學校近而且負擔得起；最重要的是，老師很支持學生。"},{"en":"If several reasons matter, most importantly tells the reader which one matters most.","zh":"如果幾個原因都重要，most importantly 告訴讀者哪一個最重要。"},{"en":"The phrase helps organise an explanation by priority.","zh":"這個短語透過優先次序幫助組織解釋。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":6},{"front":"patents","meaning":"專利","examples":[{"en":"Edison held patents for many associated DC devices.","zh":"愛迪生持有許多相關直流電裝置的專利。"},{"en":"Patents are legal rights that protect inventions from being copied without permission.","zh":"patents 是保護發明不被未經許可複製的法律權利。"},{"en":"A company may apply for patents before selling a new medical device.","zh":"公司在出售新醫療裝置前，可能申請專利。"},{"en":"If an inventor owns patents, others may need to pay to use the invention.","zh":"如果發明家擁有專利，其他人可能需要付費才能使用該發明。"},{"en":"The word connects invention with law and business.","zh":"這個字把發明與法律和商業連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":6},{"front":"legal rights","meaning":"法律權利","examples":[{"en":"Patents are legal rights over inventions.","zh":"專利是對發明的法律權利。"},{"en":"Legal rights are protections or permissions recognised by law.","zh":"legal rights 是法律承認的保障或許可。"},{"en":"Workers have legal rights to safe conditions and fair pay.","zh":"工人有享有安全環境和公平薪酬的法律權利。"},{"en":"If people do not know their legal rights, they may accept unfair treatment.","zh":"如果人們不知道自己的法律權利，可能會接受不公平待遇。"},{"en":"The phrase describes rights supported by law, not just moral claims.","zh":"這個短語描述受法律支持的權利，而不只是道德主張。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":6},{"front":"associated DC devices","meaning":"相關直流電裝置","examples":[{"en":"Edison owned patents for many associated DC devices.","zh":"愛迪生擁有許多相關直流電裝置的專利。"},{"en":"Associated DC devices are machines or tools connected with direct-current technology.","zh":"associated DC devices 是與直流電技術相關的機器或工具。"},{"en":"A company selling printers may also sell associated devices such as scanners and cables.","zh":"出售打印機的公司也可能出售掃描器和電線等相關裝置。"},{"en":"If DC became popular, associated DC devices could bring more money to Edison.","zh":"如果直流電變得流行，相關直流電裝置可以為愛迪生帶來更多收入。"},{"en":"The phrase means related equipment, not random devices.","zh":"這個短語指相關設備，而不是隨機裝置。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":7},{"front":"telegraphic devices","meaning":"電報裝置","examples":[{"en":"Edison’s patents included telegraphic devices.","zh":"愛迪生的專利包括電報裝置。"},{"en":"Telegraphic devices are tools used to send messages by electrical signals over distance.","zh":"telegraphic devices 是用電訊號遠距離傳送訊息的工具。"},{"en":"Before telephones became common, telegraphic devices helped people send urgent news.","zh":"在電話普及前，電報裝置幫助人們傳送緊急消息。"},{"en":"If telegraphic devices were improved, businesses could communicate faster across cities.","zh":"如果電報裝置被改良，企業就能更快在城市之間溝通。"},{"en":"The phrase refers to communication technology before modern phones and email.","zh":"這個短語指現代電話和電郵出現前的通訊科技。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":7},{"front":"household machinery","meaning":"家用機械","examples":[{"en":"Edison’s inventions included household machinery.","zh":"愛迪生的發明包括家用機械。"},{"en":"Household machinery means machines used in homes for daily tasks.","zh":"household machinery 指在家中用於日常工作的機器。"},{"en":"Washing machines and vacuum cleaners are common examples of household machinery.","zh":"洗衣機和吸塵機是常見家用機械例子。"},{"en":"If electricity reaches more homes, household machinery becomes more useful and popular.","zh":"如果電力到達更多家庭，家用機械就變得更有用和更流行。"},{"en":"The phrase links domestic life with technology.","zh":"這個短語把家庭生活與科技連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":7},{"front":"widespread adoption of","meaning":"……的廣泛採用","examples":[{"en":"The widespread adoption of DC would benefit Edison financially.","zh":"直流電的廣泛採用會在財務上令愛迪生受益。"},{"en":"Widespread adoption of something means many people or organisations start using it.","zh":"widespread adoption of 某物，指許多人或機構開始使用它。"},{"en":"The widespread adoption of mobile payment changed how small shops handle money.","zh":"流動支付的廣泛採用改變了小店處理金錢的方式。"},{"en":"If a technology sees widespread adoption, related businesses can earn large profits.","zh":"如果一項科技被廣泛採用，相關企業可以賺取大量利潤。"},{"en":"The phrase describes broad use, not just early testing.","zh":"這個短語描述廣泛使用，而不只是早期測試。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":7},{"front":"gain considerably from","meaning":"從……中獲得可觀收益","examples":[{"en":"Edison would gain considerably from patent royalties.","zh":"愛迪生會從專利使用費中獲得可觀收益。"},{"en":"To gain considerably from something means to receive a large benefit from it.","zh":"gain considerably from 某事，指從中得到很大的好處。"},{"en":"A school may gain considerably from a new library if students use it every day.","zh":"如果學生每天使用新圖書館，學校可以從中獲得可觀好處。"},{"en":"If a company owns valuable patents, it can gain considerably from licensing them.","zh":"如果公司擁有有價值專利，它可以透過授權使用獲得可觀收益。"},{"en":"The phrase stresses a major benefit, often financial.","zh":"這個短語強調重大好處，通常是財務上的。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":7},{"front":"patent royalties","meaning":"專利使用費","examples":[{"en":"Edison could earn patent royalties from DC devices.","zh":"愛迪生可以從直流電裝置賺取專利使用費。"},{"en":"Patent royalties are payments made to an inventor or owner for using a patented invention.","zh":"patent royalties 是使用受專利保護發明時支付給發明者或擁有者的費用。"},{"en":"A designer may receive patent royalties when companies use her medical device design.","zh":"當公司使用某設計師的醫療裝置設計，她可能收到專利使用費。"},{"en":"If a technology becomes popular, patent royalties can become a steady income source.","zh":"如果一項科技變得流行，專利使用費可以成為穩定收入來源。"},{"en":"The phrase connects invention ownership with ongoing payment.","zh":"這個短語把發明擁有權與持續付款連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":7},{"front":"all such inventions","meaning":"所有這類發明","examples":[{"en":"All such inventions were less useful if electricity could not travel far.","zh":"如果電力不能遠距離傳送，所有這類發明都變得較不有用。"},{"en":"All such inventions means all inventions of the kind just mentioned.","zh":"all such inventions 指剛才提及那類所有發明。"},{"en":"If a school lacks Internet access, all such digital tools become harder to use.","zh":"如果學校沒有互聯網，所有這類數碼工具都會較難使用。"},{"en":"If the support system fails, all such devices may lose much of their value.","zh":"如果支援系統失效，所有這類裝置可能失去大部分價值。"},{"en":"The phrase groups related examples together.","zh":"這個短語把相關例子歸在一起。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":7},{"front":"somewhat useless","meaning":"有點無用","examples":[{"en":"The inventions were somewhat useless without long-distance electricity delivery.","zh":"沒有長距離電力輸送，這些發明有點無用。"},{"en":"Somewhat useless means partly or rather useless, though not completely worthless.","zh":"somewhat useless 指部分或相當無用，但不是完全沒有價值。"},{"en":"A phone is somewhat useless on a trip if its battery dies quickly.","zh":"如果手機在旅途中很快沒電，它就有點無用。"},{"en":"If software needs the Internet but the school has no Wi-Fi, it becomes somewhat useless.","zh":"如果軟件需要互聯網，但學校沒有 Wi-Fi，它就變得有點無用。"},{"en":"The phrase softens the criticism while still showing a serious weakness.","zh":"這個短語緩和批評，但仍顯示嚴重弱點。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":7},{"front":"be delivered to customers","meaning":"被輸送給用戶","examples":[{"en":"DC electricity could only be delivered to nearby customers.","zh":"直流電只能被輸送給附近用戶。"},{"en":"To be delivered to customers means to be supplied or sent to the people who use or buy it.","zh":"be delivered to customers 指被供應或送到使用或購買它的人手中。"},{"en":"Fresh food must be delivered to customers quickly before it spoils.","zh":"新鮮食物必須快速送到顧客手中，以免變壞。"},{"en":"If electricity can only be delivered to nearby customers, the business cannot cover a wide area.","zh":"如果電力只能輸送給附近用戶，企業就不能覆蓋廣大地區。"},{"en":"The phrase focuses on reaching users.","zh":"這個短語重點在接觸用戶。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":7},{"front":"within a few kilometres of","meaning":"在……數公里範圍內","examples":[{"en":"Customers had to be within a few kilometres of the generating source.","zh":"用戶必須在發電源數公里範圍內。"},{"en":"Within a few kilometres of something means not far from it, usually only several kilometres away.","zh":"within a few kilometres of 某地，指距離它不遠，通常只有幾公里。"},{"en":"Students living within a few kilometres of school may walk or cycle there.","zh":"住在學校數公里範圍內的學生可能步行或踩單車上學。"},{"en":"If customers must be within a few kilometres of a station, remote areas cannot be served easily.","zh":"如果用戶必須在電站數公里範圍內，偏遠地區就難以服務。"},{"en":"The phrase marks a short geographical range.","zh":"這個短語標示短距離地理範圍。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":7},{"front":"generating source","meaning":"發電源","examples":[{"en":"DC customers had to live near the generating source.","zh":"直流電用戶必須住在發電源附近。"},{"en":"A generating source is the place or equipment where electricity is produced.","zh":"generating source 是生產電力的地方或設備。"},{"en":"A solar farm can be a generating source for nearby homes.","zh":"太陽能農場可以成為附近住戶的發電源。"},{"en":"If users are far from the generating source, electricity may need stronger transmission systems.","zh":"如果用戶離發電源很遠，電力可能需要更強的輸送系統。"},{"en":"The phrase refers to the origin of power supply.","zh":"這個短語指電力供應的來源。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":8},{"front":"overcome this problem","meaning":"克服這個問題","examples":[{"en":"Engineers needed to transform voltage to overcome this problem.","zh":"工程師需要轉換電壓來克服這個問題。"},{"en":"To overcome this problem means to solve or get past this difficulty.","zh":"overcome this problem 指解決或跨過這個困難。"},{"en":"A student may overcome this problem of poor memory by using revision cards.","zh":"學生可能透過使用溫習卡來克服記憶差這個問題。"},{"en":"If distance causes power loss, changing voltage can help overcome this problem.","zh":"如果距離造成電力損失，改變電壓可以幫助克服這個問題。"},{"en":"The phrase is used when a barrier needs a practical solution.","zh":"這個短語用於需要實際解決方案的障礙。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":8},{"front":"transform the voltage","meaning":"轉換電壓","examples":[{"en":"The best answer was to transform the voltage for transmission.","zh":"最佳答案是為了輸送而轉換電壓。"},{"en":"To transform the voltage means to change electricity from one voltage level to another.","zh":"transform the voltage 指把電力從一個電壓水平改成另一個。"},{"en":"A charger transforms voltage so a phone can use power safely.","zh":"充電器會轉換電壓，讓手機安全用電。"},{"en":"If voltage is transformed upward, electricity can travel farther with less loss.","zh":"如果電壓被升高，電力可以以較少損耗傳得更遠。"},{"en":"The phrase describes changing electrical level for a purpose.","zh":"這個短語描述為某目的改變電力水平。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":8},{"front":"step up the voltage","meaning":"提高電壓","examples":[{"en":"Engineers could step up the voltage to very high levels.","zh":"工程師可以把電壓提高到非常高的水平。"},{"en":"To step up the voltage means to increase the voltage.","zh":"step up the voltage 指提高電壓。"},{"en":"A transformer can step up the voltage before electricity travels across long power lines.","zh":"變壓器可以在電力經長輸電線傳送前提高電壓。"},{"en":"If voltage is stepped up, less current is needed for the same power transmission.","zh":"如果電壓被提高，同樣功率傳輸所需的電流會較少。"},{"en":"The phrase is the opposite of stepping down the voltage.","zh":"這個短語與降低電壓相反。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":8},{"front":"very high levels","meaning":"非常高的水平","examples":[{"en":"The voltage had to be raised to very high levels for transmission.","zh":"為了輸送，電壓必須升至非常高的水平。"},{"en":"Very high levels means amounts that are much higher than normal.","zh":"very high levels 指遠高於正常的數量或程度。"},{"en":"Noise can reach very high levels near a construction site.","zh":"建築地盤附近的噪音可以達到非常高的水平。"},{"en":"If demand reaches very high levels, a service may need extra staff or equipment.","zh":"如果需求達到非常高的水平，服務可能需要額外人手或設備。"},{"en":"The phrase stresses intensity or quantity far above usual.","zh":"這個短語強調遠高於平常的強度或數量。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":8},{"front":"for transmission","meaning":"為了輸送","examples":[{"en":"Electricity was transformed to high voltage for transmission.","zh":"電力為了輸送而被轉換成高電壓。"},{"en":"For transmission means for the purpose of sending something from one place to another.","zh":"for transmission 指為了把某物從一地送到另一地。"},{"en":"A video may be compressed for transmission over a slow Internet connection.","zh":"影片可能為了透過慢速互聯網傳送而被壓縮。"},{"en":"If electricity is prepared for transmission, engineers choose a form that reduces loss.","zh":"如果電力為了輸送而被處理，工程師會選擇能減少損耗的形式。"},{"en":"The phrase explains the purpose of changing or preparing something.","zh":"這個短語解釋改變或準備某物的目的。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":8},{"front":"transform it down","meaning":"把它降壓","examples":[{"en":"The voltage had to be transformed down for customer use.","zh":"電壓必須為用戶使用而被降壓。"},{"en":"To transform it down means to reduce the voltage to a lower level.","zh":"transform it down 指把電壓降低到較低水平。"},{"en":"A power system transforms voltage down before electricity enters homes.","zh":"電力系統會在電力進入家庭前把電壓降壓。"},{"en":"If high voltage is not transformed down, it may be unsafe for ordinary users.","zh":"如果高電壓沒有被降壓，對普通用戶可能不安全。"},{"en":"The phrase describes making electricity suitable for use.","zh":"這個短語描述使電力適合使用。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":8},{"front":"safe levels","meaning":"安全水平","examples":[{"en":"The voltage was transformed down to safe levels for customers.","zh":"電壓被降至用戶可用的安全水平。"},{"en":"Safe levels are amounts low or controlled enough not to cause likely harm.","zh":"safe levels 是低到或受控到不太可能造成傷害的水平。"},{"en":"A swimming pool must keep chlorine at safe levels for children.","zh":"游泳池必須把氯保持在兒童安全水平。"},{"en":"If electricity is not reduced to safe levels, people and appliances may be damaged.","zh":"如果電力沒有降至安全水平，人和電器可能受損。"},{"en":"The phrase is often used in safety, health and engineering contexts.","zh":"這個短語常用於安全、健康和工程語境。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":8},{"front":"customer use","meaning":"用戶使用","examples":[{"en":"Electricity had to be supplied at safe levels for customer use.","zh":"電力必須以安全水平供應，讓用戶使用。"},{"en":"Customer use means use by ordinary buyers or users of a service.","zh":"customer use 指普通購買者或服務使用者的使用。"},{"en":"A medicine bottle should give clear instructions for customer use.","zh":"藥瓶應提供清晰說明供用戶使用。"},{"en":"If a product is not safe for customer use, it should not be sold.","zh":"如果產品不適合用戶安全使用，就不應出售。"},{"en":"The phrase focuses on practical use by end users.","zh":"這個短語重點在最終用戶的實際使用。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":8},{"front":"thinner and less expensive wires","meaning":"較幼而較便宜的電線","examples":[{"en":"AC allowed thinner and less expensive wires.","zh":"交流電容許使用較幼而較便宜的電線。"},{"en":"Thinner and less expensive wires are wires that use less material and cost less money.","zh":"thinner and less expensive wires 是使用較少材料並成本較低的電線。"},{"en":"A school may prefer thinner and less expensive cables if they are still safe and reliable.","zh":"如果較幼而較便宜的電線仍安全可靠，學校可能較喜歡使用它們。"},{"en":"If higher voltage allows thinner wires, building a network becomes cheaper.","zh":"如果較高電壓容許使用較幼電線，建立網絡就會較便宜。"},{"en":"The phrase links engineering design with lower cost.","zh":"這個短語把工程設計與較低成本連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":8},{"front":"low-cost technology","meaning":"低成本技術","examples":[{"en":"There was no low-cost technology to transform DC voltage.","zh":"當時沒有低成本技術來轉換直流電電壓。"},{"en":"Low-cost technology is technology that can be used or produced cheaply.","zh":"low-cost technology 是可以低成本使用或生產的科技。"},{"en":"Low-cost technology helps small schools offer better lessons without huge budgets.","zh":"低成本技術幫助小型學校在沒有巨額預算下提供更好課堂。"},{"en":"If a solution lacks low-cost technology, only rich customers may be able to use it.","zh":"如果解決方案缺乏低成本技術，可能只有富裕顧客能使用。"},{"en":"The phrase stresses affordability as well as technical function.","zh":"這個短語強調負擔能力以及技術功能。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":9},{"front":"unless one used AC","meaning":"除非使用交流電","examples":[{"en":"Voltage could be transformed cheaply only if one used AC.","zh":"電壓只有在使用交流電時才可低成本轉換。"},{"en":"Unless one used AC means except in the case where alternating current was used.","zh":"unless one used AC 指除了使用交流電這種情況之外。"},{"en":"A video could not be watched smoothly unless one used a faster Internet connection.","zh":"除非使用更快的互聯網連線，影片不能順暢播放。"},{"en":"If long-distance transmission was costly unless one used AC, AC had a major advantage.","zh":"如果除非使用交流電，長距離輸電都很昂貴，交流電就有重大優勢。"},{"en":"The phrase introduces the condition needed for something to work.","zh":"這個短語引出某事能運作所需的條件。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":9},{"front":"brilliant physicist","meaning":"傑出的物理學家","examples":[{"en":"Nikola Tesla was a brilliant physicist and prolific inventor.","zh":"Nikola Tesla 是傑出的物理學家和多產的發明家。"},{"en":"A brilliant physicist is a very intelligent scientist who studies matter, energy and physical laws.","zh":"brilliant physicist 是研究物質、能量和物理規律的非常聰明的科學家。"},{"en":"A brilliant physicist may design experiments that explain how electricity behaves.","zh":"傑出的物理學家可能設計實驗來解釋電力如何運作。"},{"en":"If a brilliant physicist understands theory deeply, he may predict useful new machines.","zh":"如果傑出的物理學家深入理解理論，他可能預測有用的新機器。"},{"en":"The phrase praises both scientific ability and intelligence.","zh":"這個短語讚揚科學能力和智慧。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":9},{"front":"prolific inventor","meaning":"多產的發明家","examples":[{"en":"Tesla was a prolific inventor who researched AC.","zh":"特斯拉是一位廣泛研究交流電的多產發明家。"},{"en":"A prolific inventor creates many inventions or ideas.","zh":"prolific inventor 指創造許多發明或想法的發明家。"},{"en":"A prolific writer produces many books, while a prolific inventor produces many devices or designs.","zh":"多產作家創作許多書；多產發明家則創造許多裝置或設計。"},{"en":"If an inventor is prolific, companies may compete to use his patents.","zh":"如果發明家很多產，公司可能競相使用他的專利。"},{"en":"The phrase stresses high output, not just one famous invention.","zh":"這個短語強調高產量，而不只是單一著名發明。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":9},{"front":"extensively research","meaning":"廣泛研究","examples":[{"en":"Tesla had extensively researched alternating current.","zh":"特斯拉已廣泛研究交流電。"},{"en":"To extensively research something means to study it in great detail and over a wide range.","zh":"extensively research 某事，指深入而廣泛地研究它。"},{"en":"A doctor may extensively research a rare disease before choosing treatment.","zh":"醫生在選擇治療前，可能廣泛研究一種罕見疾病。"},{"en":"If engineers extensively research a problem, they are more likely to find a reliable solution.","zh":"如果工程師廣泛研究一個問題，他們較有可能找到可靠解決方案。"},{"en":"The phrase suggests deep and careful investigation.","zh":"這個短語暗示深入而仔細的調查。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":9},{"front":"penniless immigrant","meaning":"身無分文的移民","examples":[{"en":"Tesla arrived as a penniless immigrant from Serbia.","zh":"特斯拉作為一名來自塞爾維亞、身無分文的移民抵達。"},{"en":"A penniless immigrant is a person who moves to another country with little or no money.","zh":"penniless immigrant 是帶着很少或沒有金錢移居另一國的人。"},{"en":"A penniless immigrant may accept hard work at first just to pay rent and food.","zh":"身無分文的移民起初可能接受辛苦工作，只為支付租金和食物。"},{"en":"If someone arrives penniless, talent alone may not immediately protect them from hardship.","zh":"如果某人身無分文地抵達，單靠才華未必能立即保護他免受艱難。"},{"en":"The phrase highlights both migration and poverty.","zh":"這個短語同時突出移民和貧困。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":9},{"front":"work for a year at","meaning":"在……工作了一年","examples":[{"en":"Tesla worked for a year at Edison’s Menlo lab.","zh":"特斯拉在愛迪生的門洛實驗室工作了一年。"},{"en":"To work for a year at a place means to spend one year employed or working there.","zh":"work for a year at 某地，指在那裏工作一年。"},{"en":"A graduate may work for a year at a hospital before applying to medical school.","zh":"畢業生可能在醫院工作一年，才申請醫學院。"},{"en":"If someone works for a year at a famous lab, they may gain valuable experience.","zh":"如果某人在著名實驗室工作一年，可能獲得寶貴經驗。"},{"en":"The phrase gives both duration and workplace.","zh":"這個短語同時提供時間長度和工作地點。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":9},{"front":"Menlo lab","meaning":"門洛實驗室","examples":[{"en":"Tesla worked at Edison’s Menlo lab.","zh":"特斯拉在愛迪生的門洛實驗室工作。"},{"en":"Menlo lab refers to Edison’s laboratory at Menlo Park.","zh":"Menlo lab 指愛迪生在門洛帕克的實驗室。"},{"en":"A young engineer might join a famous lab to learn from experienced inventors.","zh":"年輕工程師可能加入著名實驗室，向有經驗發明家學習。"},{"en":"If a lab gathers skilled people, new ideas can be tested quickly.","zh":"如果實驗室聚集有技能的人，新想法就可以快速測試。"},{"en":"The phrase names the workplace where Tesla briefly worked for Edison.","zh":"這個短語指出特斯拉曾短暫為愛迪生工作的地方。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":9},{"front":"propose the AC system to","meaning":"向……提出交流電系統","examples":[{"en":"Tesla proposed the AC system to Edison.","zh":"特斯拉向愛迪生提出交流電系統。"},{"en":"To propose the AC system to someone means to present the alternating-current system as an idea for them to consider.","zh":"propose the AC system to someone 指把交流電系統作為想法提出，讓對方考慮。"},{"en":"A student may propose a new timetable to the class teacher.","zh":"學生可能向班主任提出新時間表。"},{"en":"If an idea is proposed to a leader, the leader can accept, reject or ignore it.","zh":"如果想法被提出給領導者，對方可以接受、拒絕或不理會。"},{"en":"The phrase focuses on offering a plan to another person.","zh":"這個短語重點在向另一人提出計劃。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":9},{"front":"empirical experimenter","meaning":"重視實證的實驗者","examples":[{"en":"Edison was an empirical experimenter with little formal education.","zh":"愛迪生是重視實證的實驗者，正規教育不多。"},{"en":"An empirical experimenter learns mainly by testing and observing results.","zh":"empirical experimenter 主要透過測試和觀察結果來學習。"},{"en":"A cook who changes a recipe by tasting each version is an empirical experimenter.","zh":"廚師每次試味後改變食譜，就是重視實證的實驗者。"},{"en":"If someone relies on empirical experiments, they may distrust theories that lack visible proof.","zh":"如果某人依賴實證實驗，他可能不信任缺乏可見證據的理論。"},{"en":"The phrase stresses practical testing rather than abstract theory.","zh":"這個短語強調實際測試，而不是抽象理論。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":9},{"front":"formal education","meaning":"正規教育","examples":[{"en":"Edison had little formal education.","zh":"愛迪生接受的正規教育不多。"},{"en":"Formal education is organised schooling or training provided by schools, colleges or universities.","zh":"formal education 是由學校、學院或大學提供的有組織教育或訓練。"},{"en":"A person may have little formal education but still learn skills through work experience.","zh":"一個人可能正規教育不多，但仍能透過工作經驗學會技能。"},{"en":"If a job requires formal education, applicants may need certificates or degrees.","zh":"如果工作要求正規教育，申請者可能需要證書或學位。"},{"en":"The phrase contrasts school-based learning with self-learning or practical experience.","zh":"這個短語把學校教育與自學或實務經驗作對比。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":10},{"front":"dismiss something as impractical","meaning":"認為……不切實際而不予理會","examples":[{"en":"Edison dismissed Tesla’s AC system as impractical.","zh":"愛迪生認為特斯拉的交流電系統不切實際而不予理會。"},{"en":"To dismiss something as impractical means to reject it because it seems unrealistic or unusable.","zh":"dismiss something as impractical 指因某事看似不現實或不可用而拒絕它。"},{"en":"A manager may dismiss a four-day school week as impractical if transport cannot be arranged.","zh":"如果交通無法安排，經理可能認為四天上課週不切實際而不採用。"},{"en":"If people dismiss an idea too quickly, they may miss a useful solution.","zh":"如果人們太快否定一個想法，可能錯過有用解決方案。"},{"en":"The phrase shows rejection based on practical concerns.","zh":"這個短語顯示基於實際考慮的拒絕。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":10},{"front":"mathematical training","meaning":"數學訓練","examples":[{"en":"Tesla had mathematical training and theoretical knowledge.","zh":"特斯拉有數學訓練和理論知識。"},{"en":"Mathematical training is education in using numbers, formulas and logical reasoning.","zh":"mathematical training 是使用數字、公式和邏輯推理的教育。"},{"en":"Engineering students need mathematical training to calculate forces, costs and risks.","zh":"工程學生需要數學訓練來計算力量、成本和風險。"},{"en":"If someone has strong mathematical training, they may understand systems before building them.","zh":"如果某人有強大數學訓練，他可能在建造系統前先理解它。"},{"en":"The phrase links technical skill with formal reasoning.","zh":"這個短語把技術能力與正規推理連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":10},{"front":"formal theoretical knowledge","meaning":"正規理論知識","examples":[{"en":"Tesla had formal theoretical knowledge that Edison lacked.","zh":"特斯拉有愛迪生缺乏的正規理論知識。"},{"en":"Formal theoretical knowledge is organised understanding of principles learned through study.","zh":"formal theoretical knowledge 是透過學習獲得的、有組織的原理理解。"},{"en":"A nurse needs practical skill, but formal theoretical knowledge helps explain why treatments work.","zh":"護士需要實用技能，但正規理論知識有助解釋治療為何有效。"},{"en":"If workers lack theoretical knowledge, they may know what works but not why it works.","zh":"如果工人缺乏理論知識，他們可能知道甚麼有效，但不知道為何有效。"},{"en":"The phrase contrasts studied principles with hands-on experience.","zh":"這個短語把學習得來的原理與實務經驗作對比。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":10},{"front":"understand something’s potential","meaning":"明白……的潛力","examples":[{"en":"Tesla understood AC’s potential.","zh":"特斯拉明白交流電的潛力。"},{"en":"To understand something’s potential means to recognise what it could achieve in the future.","zh":"understand something’s potential 指認出某物將來可能達成甚麼。"},{"en":"A teacher may understand a quiet student’s potential before classmates notice it.","zh":"老師可能在同學注意到前，已明白安靜學生的潛力。"},{"en":"If investors understand a technology’s potential early, they may support it before others do.","zh":"如果投資者早日明白科技的潛力，他們可能比其他人更早支持它。"},{"en":"The phrase focuses on seeing future value.","zh":"這個短語重點在看見未來價值。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":10},{"front":"AC polyphase electric induction motor","meaning":"交流多相感應電動機","examples":[{"en":"Tesla invented an AC polyphase electric induction motor.","zh":"特斯拉發明了交流多相感應電動機。"},{"en":"An AC polyphase electric induction motor is a motor powered by alternating current using several phases.","zh":"AC polyphase electric induction motor 是使用多個相位交流電驅動的摩打。"},{"en":"Factories need reliable motors to run machines, pumps and fans.","zh":"工廠需要可靠摩打來運行機器、水泵和風扇。"},{"en":"Because Tesla’s motor made AC useful for machinery, it strengthened the case for AC power.","zh":"因為特斯拉的摩打令交流電可用於機械，它加強了支持交流電的理據。"},{"en":"The phrase names a technical invention central to Tesla’s work.","zh":"這個短語指出特斯拉工作中的核心技術發明。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":10},{"front":"induction motor","meaning":"感應電動機","examples":[{"en":"Tesla invented an electric induction motor.","zh":"特斯拉發明了感應電動機。"},{"en":"An induction motor is an electric motor that uses electromagnetic induction to create motion.","zh":"induction motor 是使用電磁感應產生運動的電動機。"},{"en":"Many machines use induction motors because they are reliable and efficient.","zh":"許多機器使用感應電動機，因為它們可靠而高效。"},{"en":"If an induction motor works well with AC, factories can use AC for more than lighting.","zh":"如果感應電動機能良好使用交流電，工廠就能把交流電用於照明以外的用途。"},{"en":"The phrase refers to a motor design, not a general engine.","zh":"這個短語指一種摩打設計，而不是一般引擎。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":10},{"front":"due credit","meaning":"應有的功勞","examples":[{"en":"Tesla felt he was not being given due credit.","zh":"特斯拉覺得自己沒有得到應有的功勞。"},{"en":"Due credit is the proper recognition someone deserves for their work or idea.","zh":"due credit 是某人因其工作或想法應得到的恰當認可。"},{"en":"A student should receive due credit if her research helped the group project succeed.","zh":"如果學生的研究幫助小組項目成功，她應得到應有的功勞。"},{"en":"If workers do not receive due credit, they may feel angry or leave the company.","zh":"如果工人沒有得到應有功勞，他們可能感到憤怒或離職。"},{"en":"The phrase is about fair recognition, not money only.","zh":"這個短語關於公平認可，而不只是金錢。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":10},{"front":"financial compensation","meaning":"金錢補償","examples":[{"en":"Tesla wanted enough financial compensation for his work.","zh":"特斯拉希望為自己的工作得到足夠金錢補償。"},{"en":"Financial compensation is money paid to someone for work, loss, injury or contribution.","zh":"financial compensation 是因工作、損失、受傷或貢獻而支付給某人的金錢。"},{"en":"A worker may ask for financial compensation after being injured at work.","zh":"工人在工作中受傷後，可能要求金錢補償。"},{"en":"If people feel their contribution is unpaid, they may demand financial compensation.","zh":"如果人們覺得自己的貢獻沒有得到報酬，他們可能要求金錢補償。"},{"en":"The phrase focuses on payment as recognition or repair.","zh":"這個短語重點在以金錢作為認可或補償。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":10},{"front":"direct confrontation","meaning":"直接衝突","examples":[{"en":"A direct confrontation led Tesla to resign immediately.","zh":"一次直接衝突導致特斯拉立即辭職。"},{"en":"A direct confrontation is an open and face-to-face conflict or disagreement.","zh":"direct confrontation 是公開而面對面的衝突或分歧。"},{"en":"A direct confrontation between a teacher and parent may happen if both sides are angry.","zh":"如果老師和家長雙方都很憤怒，可能出現直接衝突。"},{"en":"If a problem is handled through direct confrontation, emotions may rise quickly.","zh":"如果問題透過直接衝突處理，情緒可能迅速升高。"},{"en":"The phrase suggests open conflict, not quiet disagreement.","zh":"這個短語暗示公開衝突，而不是安靜分歧。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":10},{"front":"lead someone to resign","meaning":"導致某人辭職","examples":[{"en":"A confrontation led Tesla to resign from Edison’s company.","zh":"一次衝突導致特斯拉從愛迪生的公司辭職。"},{"en":"To lead someone to resign means to cause someone to leave a job formally.","zh":"lead someone to resign 指造成某人正式離開工作。"},{"en":"Unfair treatment may lead a teacher to resign from a school.","zh":"不公平待遇可能導致老師從學校辭職。"},{"en":"If repeated conflicts lead someone to resign, the workplace may lose valuable talent.","zh":"如果反覆衝突導致某人辭職，工作場所可能失去寶貴人才。"},{"en":"The phrase connects a cause with someone’s decision to quit.","zh":"這個短語把原因與某人辭職的決定連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":11},{"front":"resign immediately","meaning":"立即辭職","examples":[{"en":"Tesla resigned immediately after the confrontation.","zh":"特斯拉在衝突後立即辭職。"},{"en":"To resign immediately means to leave a job at once.","zh":"resign immediately 指立刻離開工作。"},{"en":"A manager may resign immediately if a scandal makes it impossible to continue.","zh":"如果醜聞令經理無法繼續，他可能立即辭職。"},{"en":"If someone resigns immediately, the company may need a replacement quickly.","zh":"如果某人立即辭職，公司可能需要迅速找替代人選。"},{"en":"The phrase stresses speed and seriousness.","zh":"這個短語強調速度和嚴重性。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":11},{"front":"be reduced to working as","meaning":"淪落到做……","examples":[{"en":"Tesla was reduced to working as a labourer.","zh":"特斯拉淪落到做勞工。"},{"en":"To be reduced to working as something means to fall to a lower-status or less desired job.","zh":"be reduced to working as 某職位，指跌落到較低地位或較不理想的工作。"},{"en":"A trained chef may be reduced to working as a cleaner if no kitchen jobs are available.","zh":"如果沒有廚房職位，受訓廚師可能淪落到做清潔工。"},{"en":"If talent is not recognised, a skilled person may be reduced to low-paid work.","zh":"如果才華不被認可，有技能的人可能淪落到做低薪工作。"},{"en":"The phrase suggests hardship and loss of status.","zh":"這個短語暗示艱難和地位下降。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":11},{"front":"labourer","meaning":"勞工","examples":[{"en":"Tesla worked as a labourer for a few years.","zh":"特斯拉做了幾年勞工。"},{"en":"A labourer is a worker who does physical work, often without high status or specialised authority.","zh":"labourer 是從事體力工作的人，通常沒有高地位或專門權力。"},{"en":"Labourers on a building site carry materials, clean areas and support skilled workers.","zh":"建築地盤上的勞工搬運材料、清理地方並支援熟練工人。"},{"en":"If a trained inventor works as a labourer, his skills may be underused.","zh":"如果受訓發明家做勞工，他的技能可能未被充分使用。"},{"en":"The word usually refers to manual work.","zh":"這個字通常指體力工作者。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":11},{"front":"make ends meet","meaning":"勉強維持生計","examples":[{"en":"Tesla worked as a labourer to make ends meet.","zh":"特斯拉做勞工以勉強維持生計。"},{"en":"To make ends meet means to earn just enough money to pay basic living costs.","zh":"make ends meet 指賺到剛好足夠支付基本生活開支的錢。"},{"en":"A student may work part-time to make ends meet while paying rent.","zh":"學生可能做兼職，以在交租時勉強維持生計。"},{"en":"If prices rise but wages do not, families may struggle to make ends meet.","zh":"如果物價上升但工資不升，家庭可能難以維持生計。"},{"en":"The phrase describes financial survival, not comfort.","zh":"這個短語描述財務上的生存，而不是舒適生活。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":11},{"front":"advocate AC","meaning":"支持交流電","examples":[{"en":"Tesla was not the first person to advocate AC.","zh":"特斯拉不是第一個支持交流電的人。"},{"en":"To advocate AC means to publicly support alternating current.","zh":"advocate AC 指公開支持交流電。"},{"en":"A doctor may advocate exercise because it improves health.","zh":"醫生可能支持運動，因為它改善健康。"},{"en":"If many engineers advocate a system, investors may take it more seriously.","zh":"如果許多工程師支持一個系統，投資者可能更認真看待它。"},{"en":"The phrase describes active support, not private preference only.","zh":"這個短語描述主動支持，而不只是私人偏好。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":11},{"front":"be trialled","meaning":"被試用","examples":[{"en":"The AC system was being trialled in many European countries.","zh":"交流電系統正在許多歐洲國家被試用。"},{"en":"To be trialled means to be tested before wider use.","zh":"be trialled 指在廣泛使用前被測試。"},{"en":"A new bus route may be trialled for three months before becoming permanent.","zh":"新巴士路線可能試用三個月，然後才成為永久路線。"},{"en":"If a system is trialled successfully, more cities may adopt it.","zh":"如果系統試用成功，更多城市可能採用它。"},{"en":"The phrase refers to practical testing in real conditions.","zh":"這個短語指在真實條件下進行實際測試。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":11},{"front":"with considerable success","meaning":"並取得相當成功","examples":[{"en":"AC was being trialled with considerable success.","zh":"交流電正在被試用，並取得相當成功。"},{"en":"With considerable success means with a large or noticeable degree of success.","zh":"with considerable success 指取得很大或明顯程度的成功。"},{"en":"The school introduced reading groups with considerable success because test scores improved.","zh":"學校推行閱讀小組並取得相當成功，因為考試成績提高了。"},{"en":"If a trial works with considerable success, supporters gain stronger evidence.","zh":"如果試驗取得相當成功，支持者就得到更強證據。"},{"en":"The phrase suggests results were clearly positive.","zh":"這個短語暗示結果明顯正面。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":11},{"front":"convert to the cause","meaning":"轉而支持某事的人","examples":[{"en":"Westinghouse became one of the converts to the cause of AC.","zh":"Westinghouse 成為交流電事業的支持者之一。"},{"en":"A convert to the cause is someone who changes and begins to support a movement or idea.","zh":"convert to the cause 是改變立場並開始支持某運動或想法的人。"},{"en":"A parent may become a convert to online homework after seeing their child improve.","zh":"家長看見孩子進步後，可能轉而支持網上功課。"},{"en":"If respected engineers convert to a cause, other people may follow them.","zh":"如果受尊重的工程師轉而支持某事，其他人可能跟隨他們。"},{"en":"The phrase describes a person won over to a side.","zh":"這個短語描述被說服而支持某一方的人。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":11},{"front":"university-trained electrical engineer","meaning":"受過大學訓練的電機工程師","examples":[{"en":"George Westinghouse was a university-trained electrical engineer.","zh":"George Westinghouse 是受過大學訓練的電機工程師。"},{"en":"A university-trained electrical engineer is an engineer educated at university in electrical systems.","zh":"university-trained electrical engineer 是在大學接受電力系統教育的工程師。"},{"en":"A university-trained engineer may design safer wiring for schools and hospitals.","zh":"受過大學訓練的工程師可能為學校和醫院設計更安全的電線系統。"},{"en":"If someone is university-trained, clients may trust their technical knowledge more easily.","zh":"如果某人受過大學訓練，客戶可能更容易信任其技術知識。"},{"en":"The phrase stresses formal technical education.","zh":"這個短語強調正規技術教育。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":11},{"front":"electrical engineer","meaning":"電機工程師","examples":[{"en":"Westinghouse was an electrical engineer who supported AC.","zh":"Westinghouse 是一名支持交流電的電機工程師。"},{"en":"An electrical engineer designs, studies or manages electrical systems and devices.","zh":"electrical engineer 設計、研究或管理電力系統和裝置。"},{"en":"An electrical engineer may help a hospital plan safe backup power.","zh":"電機工程師可能幫助醫院規劃安全後備電力。"},{"en":"If an electrical engineer supports a system, their technical judgment may influence investors.","zh":"如果電機工程師支持某系統，其技術判斷可能影響投資者。"},{"en":"The phrase refers to a trained engineering profession.","zh":"這個短語指受訓的工程專業。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":12},{"front":"be willing to invest in","meaning":"願意投資於……","examples":[{"en":"Westinghouse was willing to invest in the AC system.","zh":"Westinghouse 願意投資於交流電系統。"},{"en":"To be willing to invest in something means to be ready to put money or resources into it.","zh":"be willing to invest in 某事，指準備把金錢或資源投入其中。"},{"en":"A school may be willing to invest in tablets if they improve learning.","zh":"如果平板電腦能改善學習，學校可能願意投資於它們。"},{"en":"If investors are willing to invest in a technology, development can move faster.","zh":"如果投資者願意投資於一項科技，發展可以更快。"},{"en":"The phrase shows readiness to support something financially.","zh":"這個短語顯示在財務上支持某事的意願。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":12},{"front":"form a company","meaning":"成立公司","examples":[{"en":"Westinghouse formed a company to develop AC technology.","zh":"Westinghouse 成立公司來發展交流電技術。"},{"en":"To form a company means to create a business organisation.","zh":"form a company 指建立一個商業組織。"},{"en":"Two friends may form a company after their tutoring service attracts many students.","zh":"兩位朋友的補習服務吸引許多學生後，可能成立公司。"},{"en":"If a company is formed around a new technology, it can hire staff and seek investment.","zh":"如果公司圍繞新科技成立，它就能聘請員工和尋求投資。"},{"en":"The phrase focuses on setting up a business structure.","zh":"這個短語重點在建立商業結構。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":12},{"front":"purchase the patents for","meaning":"購買……的專利","examples":[{"en":"Westinghouse purchased the patents for AC-based transformer technology.","zh":"Westinghouse 購買了以交流電為基礎的變壓器技術專利。"},{"en":"To purchase the patents for something means to buy the legal rights to use or control an invention.","zh":"purchase the patents for 某物，指購買使用或控制某發明的法律權利。"},{"en":"A company may purchase the patents for a medical device before producing it widely.","zh":"公司可能在大規模生產醫療裝置前，購買該裝置的專利。"},{"en":"If a business purchases useful patents, it can stop competitors from using the same idea freely.","zh":"如果企業購買有用專利，就可以阻止競爭者自由使用同一想法。"},{"en":"The phrase connects buying with legal control of technology.","zh":"這個短語把購買與技術的法律控制連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":12},{"front":"AC-based transformer technology","meaning":"以交流電為基礎的變壓器技術","examples":[{"en":"Westinghouse bought patents for AC-based transformer technology.","zh":"Westinghouse 購買了以交流電為基礎的變壓器技術專利。"},{"en":"AC-based transformer technology is technology that changes AC voltage to higher or lower levels.","zh":"AC-based transformer technology 是把交流電電壓升高或降低的技術。"},{"en":"Power companies use transformer technology so electricity can travel far and then enter homes safely.","zh":"電力公司使用變壓器技術，讓電力能遠距離傳輸並安全進入家庭。"},{"en":"Because AC-based transformers worked well, long-distance AC transmission became practical.","zh":"因為以交流電為基礎的變壓器運作良好，長距離交流電傳輸變得實用。"},{"en":"The phrase names a key technology behind AC’s success.","zh":"這個短語指出交流電成功背後的關鍵技術。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":12},{"front":"transformer technology","meaning":"變壓器技術","examples":[{"en":"Transformer technology made long-distance AC transmission practical.","zh":"變壓器技術令長距離交流電傳輸變得實用。"},{"en":"Transformer technology changes voltage levels so electricity can be sent and used safely.","zh":"transformer technology 改變電壓水平，讓電力可以安全輸送和使用。"},{"en":"A neighbourhood transformer lowers voltage before electricity reaches homes.","zh":"社區變壓器會在電力到達家庭前降低電壓。"},{"en":"If transformer technology is reliable, power grids can cover wider areas.","zh":"如果變壓器技術可靠，電網就能覆蓋更廣地區。"},{"en":"The phrase refers to equipment that makes voltage control possible.","zh":"這個短語指令電壓控制成為可能的設備技術。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":12},{"front":"European inventors","meaning":"歐洲發明家","examples":[{"en":"Westinghouse purchased patents from European inventors.","zh":"Westinghouse 從歐洲發明家手中購買專利。"},{"en":"European inventors are inventors from European countries.","zh":"European inventors 是來自歐洲國家的發明家。"},{"en":"A company may buy ideas from European inventors if their designs solve practical problems.","zh":"如果歐洲發明家的設計能解決實際問題，公司可能購買他們的想法。"},{"en":"If inventors in different countries work on the same issue, technology can develop faster.","zh":"如果不同國家的發明家研究同一問題，科技可以更快發展。"},{"en":"The phrase identifies the geographical origin of the inventors.","zh":"這個短語指出發明家的地理來源。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":12},{"front":"among others","meaning":"以及其他","examples":[{"en":"Westinghouse bought Tesla’s motor patents, among others.","zh":"Westinghouse 購買了特斯拉的摩打專利，以及其他專利。"},{"en":"Among others means including other people or things not listed individually.","zh":"among others 指包括其他未逐一列出的人或事物。"},{"en":"The school invited parents, teachers and local doctors, among others, to the meeting.","zh":"學校邀請家長、老師和本地醫生以及其他人士出席會議。"},{"en":"If a list includes “among others”, readers know there are more examples.","zh":"如果清單包含 among others，讀者知道還有更多例子。"},{"en":"The phrase avoids giving a complete list.","zh":"這個短語避免列出完整清單。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":12},{"front":"lead someone to hire","meaning":"促使某人聘請","examples":[{"en":"The patent purchase eventually led Westinghouse to hire Tesla.","zh":"購買專利最終促使 Westinghouse 聘請特斯拉。"},{"en":"To lead someone to hire a person means to cause them to employ that person.","zh":"lead someone to hire 某人，指促使對方僱用該人。"},{"en":"A strong interview may lead a school to hire a new teacher.","zh":"出色面試可能促使學校聘請一位新老師。"},{"en":"If a company sees value in someone’s invention, it may lead them to hire the inventor.","zh":"如果公司看見某人發明的價值，這可能促使它聘請該發明者。"},{"en":"The phrase links a reason with a hiring decision.","zh":"這個短語把原因與聘請決定連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":12},{"front":"commercialise AC","meaning":"將交流電商業化","examples":[{"en":"Westinghouse hired Tesla to help commercialise AC.","zh":"Westinghouse 聘請特斯拉協助將交流電商業化。"},{"en":"To commercialise AC means to turn alternating-current technology into a marketable business system.","zh":"commercialise AC 指把交流電技術變成可銷售的商業系統。"},{"en":"A university may commercialise a medical discovery by working with a company.","zh":"大學可能透過與公司合作，把醫學發現商業化。"},{"en":"If technology is commercialised successfully, it moves from the lab to paying customers.","zh":"如果科技成功商業化，它就從實驗室走向付費客戶。"},{"en":"The phrase connects invention with real business use.","zh":"這個短語把發明與實際商業用途連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":12},{"front":"promote something as","meaning":"把……宣傳為","examples":[{"en":"Westinghouse promoted AC as a better system.","zh":"Westinghouse 把交流電宣傳為更好的系統。"},{"en":"To promote something as something means to present or advertise it in that way.","zh":"promote something as 某物，指以那種方式介紹或宣傳它。"},{"en":"A school may promote its summer course as a chance to improve speaking confidence.","zh":"學校可能把暑期課程宣傳為提升口語信心的機會。"},{"en":"If a product is promoted as safer, customers will expect evidence of safety.","zh":"如果產品被宣傳為更安全，顧客會期待安全證據。"},{"en":"The phrase focuses on public presentation and persuasion.","zh":"這個短語重點在公開呈現和說服。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":13},{"front":"a better system","meaning":"更好的系統","examples":[{"en":"Westinghouse promoted AC as a better system than DC.","zh":"Westinghouse 把交流電宣傳為比直流電更好的系統。"},{"en":"A better system is a method or arrangement that works more effectively than another.","zh":"a better system 是比另一方法或安排更有效運作的系統。"},{"en":"A better booking system can reduce waiting time at a clinic.","zh":"更好的預約系統可以減少診所等候時間。"},{"en":"If a better system saves money and reaches more users, people may switch to it.","zh":"如果更好的系統節省金錢並接觸更多用戶，人們可能轉用它。"},{"en":"The phrase is used when comparing practical performance.","zh":"這個短語用於比較實際表現。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":13},{"front":"bitter feud","meaning":"激烈爭鬥","examples":[{"en":"A bitter feud known as the War of Currents was set to begin.","zh":"一場被稱為電流之戰的激烈爭鬥即將開始。"},{"en":"A bitter feud is a long and angry conflict between people or groups.","zh":"bitter feud 是人或群體之間長期而憤怒的衝突。"},{"en":"Two neighbours may enter a bitter feud over noise, parking and shared walls.","zh":"兩個鄰居可能因噪音、泊車和共用牆壁而陷入激烈爭鬥。"},{"en":"If a business feud becomes bitter, both sides may spend more energy attacking than improving.","zh":"如果商業爭鬥變得激烈，雙方可能把更多精力花在攻擊而非改善上。"},{"en":"The phrase suggests deep hostility, not a small disagreement.","zh":"這個短語暗示深刻敵意，而不是小分歧。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":13},{"front":"be known as","meaning":"被稱為","examples":[{"en":"The bitter feud became known as the War of Currents.","zh":"這場激烈爭鬥被稱為電流之戰。"},{"en":"To be known as something means to be called or recognised by that name.","zh":"be known as 某物，指被那個名稱稱呼或認識。"},{"en":"A street full of bookshops may be known as the book district.","zh":"一條滿是書店的街道可能被稱為書店區。"},{"en":"If an event is known as a disaster, people remember it mainly for its failure.","zh":"如果一件事被稱為災難，人們主要會因其失敗而記得它。"},{"en":"The phrase introduces a recognised name or label.","zh":"這個短語引出被認可的名稱或標籤。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":13},{"front":"be set to begin","meaning":"即將開始","examples":[{"en":"The War of Currents was set to begin.","zh":"電流之戰即將開始。"},{"en":"To be set to begin means to be about to start.","zh":"be set to begin 指即將開始。"},{"en":"The school concert is set to begin after the final rehearsal.","zh":"學校音樂會在最後綵排後即將開始。"},{"en":"If two companies prepare attacks against each other, a public battle may be set to begin.","zh":"如果兩間公司準備互相攻擊，一場公開鬥爭可能即將開始。"},{"en":"The phrase shows that an event is ready or expected to start soon.","zh":"這個短語顯示事件已準備好或預期很快開始。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":13},{"front":"first strike","meaning":"第一擊；第一招","examples":[{"en":"Edison’s first strike was to attack high-voltage systems.","zh":"愛迪生的第一招是攻擊高電壓系統。"},{"en":"A first strike is the first action taken in a conflict or campaign.","zh":"first strike 是衝突或運動中採取的第一個行動。"},{"en":"In a debate, a student’s first strike may be to question the opponent’s evidence.","zh":"在辯論中，學生的第一招可能是質疑對手證據。"},{"en":"If the first strike is powerful, it can shape how the public sees the whole conflict.","zh":"如果第一擊很有力，它可以塑造公眾如何看整場衝突。"},{"en":"The phrase suggests an opening move in a battle or argument.","zh":"這個短語暗示戰鬥或論爭中的開場行動。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":13},{"front":"claim that","meaning":"聲稱","examples":[{"en":"Edison claimed that high-voltage systems were too dangerous.","zh":"愛迪生聲稱高電壓系統太危險。"},{"en":"To claim that something is true means to state it as a fact, often needing evidence.","zh":"claim that 某事是真的，指把它作為事實陳述，通常需要證據。"},{"en":"A company may claim that its product saves energy, but customers may ask for proof.","zh":"公司可能聲稱其產品節省能源，但顧客可能要求證明。"},{"en":"If someone claims that a method is unsafe, the public may become worried.","zh":"如果有人聲稱某方法不安全，公眾可能變得憂慮。"},{"en":"The phrase introduces a statement or argument.","zh":"這個短語引出陳述或論點。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":13},{"front":"high-voltage systems","meaning":"高電壓系統","examples":[{"en":"Edison argued that high-voltage systems were dangerous.","zh":"愛迪生主張高電壓系統很危險。"},{"en":"High-voltage systems use electricity at very high voltage levels.","zh":"high-voltage systems 使用非常高電壓水平的電力。"},{"en":"High-voltage systems need careful insulation and safety rules to protect workers.","zh":"高電壓系統需要仔細絕緣和安全規則來保護工人。"},{"en":"If high-voltage systems are handled badly, accidents can be severe.","zh":"如果高電壓系統處理不當，意外可能很嚴重。"},{"en":"The phrase refers to powerful electrical systems, not ordinary household wiring.","zh":"這個短語指強大的電力系統，而不是普通家用電線。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":13},{"front":"too dangerous to use","meaning":"太危險而不能使用","examples":[{"en":"Edison said AC was too dangerous to use.","zh":"愛迪生說交流電太危險而不能使用。"},{"en":"Too dangerous to use means unsafe enough that people should not use it.","zh":"too dangerous to use 指危險到人們不應使用。"},{"en":"A cracked phone charger may be too dangerous to use near a bed.","zh":"裂開的手機充電器可能太危險，不應在床邊使用。"},{"en":"If a machine is too dangerous to use, managers should repair or replace it.","zh":"如果機器太危險而不能使用，管理層應維修或更換它。"},{"en":"The phrase explains why something should be avoided.","zh":"這個短語解釋為何某物應避免使用。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":13},{"front":"counter that","meaning":"反駁說","examples":[{"en":"Westinghouse countered that the risks could be minimised.","zh":"Westinghouse 反駁說風險可以減至最低。"},{"en":"To counter that means to reply with an opposing argument.","zh":"counter that 指用相反論點回應。"},{"en":"A student may counter that homework is useful if it is short and meaningful.","zh":"學生可能反駁說，如果功課短而有意義，它是有用的。"},{"en":"If one side says a plan is risky, the other may counter that training can reduce the risk.","zh":"如果一方說計劃有風險，另一方可能反駁說培訓可以降低風險。"},{"en":"The phrase introduces a response that challenges a claim.","zh":"這個短語引出挑戰某主張的回應。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":13},{"front":"risks could be minimised","meaning":"風險可以減至最低","examples":[{"en":"Westinghouse argued that the risks could be minimised.","zh":"Westinghouse 主張風險可以減至最低。"},{"en":"Risks could be minimised means dangers could be reduced to a low level.","zh":"risks could be minimised 指危險可以被降低到很低水平。"},{"en":"School-trip risks can be minimised by planning routes and checking student numbers.","zh":"透過規劃路線和點算學生人數，學校旅行風險可以減至最低。"},{"en":"If safety rules are followed, many workplace risks can be minimised.","zh":"如果遵守安全規則，許多工作場所風險可以減至最低。"},{"en":"The phrase does not mean risk disappears completely.","zh":"這個短語不代表風險完全消失。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":14},{"front":"be considerably outweighed by","meaning":"被……大大超過","examples":[{"en":"The risks were considerably outweighed by the benefits.","zh":"這些風險被好處大大超過。"},{"en":"To be considerably outweighed by something means to be much less important than it.","zh":"be considerably outweighed by 某物，指重要性遠低於它。"},{"en":"The cost of a library may be considerably outweighed by its benefits to students.","zh":"圖書館的成本可能被它對學生的好處大大超過。"},{"en":"If small risks are outweighed by major benefits, people may support the project.","zh":"如果小風險被重大好處超過，人們可能支持該項目。"},{"en":"The phrase compares two sides and says one is clearly stronger.","zh":"這個短語比較兩方，並指出其中一方明顯更強。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":14},{"front":"use one’s influence on","meaning":"利用某人對……的影響力","examples":[{"en":"Edison used his influence on state governments.","zh":"愛迪生利用他對州政府的影響力。"},{"en":"To use one’s influence on someone means to use power, reputation or connections to affect their decisions.","zh":"use one’s influence on 某人，指利用權力、名聲或關係影響其決定。"},{"en":"A respected doctor may use her influence on officials to improve hospital safety.","zh":"受尊重的醫生可能利用她對官員的影響力來改善醫院安全。"},{"en":"If a businessman uses influence on politicians, public policy may be shaped by private interests.","zh":"如果商人利用對政客的影響力，公共政策可能被私人利益塑造。"},{"en":"The phrase shows social or political pressure.","zh":"這個短語顯示社會或政治壓力。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":14},{"front":"state governments","meaning":"州政府","examples":[{"en":"Edison tried to influence American state governments.","zh":"愛迪生試圖影響美國州政府。"},{"en":"State governments are the governments of individual states within a country such as the United States.","zh":"state governments 是美國等國家內個別州的政府。"},{"en":"State governments can make rules about roads, schools and public safety.","zh":"州政府可以制定關於道路、學校和公共安全的規則。"},{"en":"If state governments restrict a technology, companies may struggle to expand.","zh":"如果州政府限制某科技，公司可能難以擴張。"},{"en":"The phrase refers to regional government authority.","zh":"這個短語指地區政府權力。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":14},{"front":"limit power transmission to","meaning":"把電力傳輸限制在……","examples":[{"en":"Edison wanted to limit power transmission to low voltages.","zh":"愛迪生想把電力傳輸限制在低電壓。"},{"en":"To limit power transmission to something means to restrict electricity delivery to that condition or level.","zh":"limit power transmission to 某水平，指把電力輸送限制在該條件或水平。"},{"en":"A school may limit access to the lab to trained students only.","zh":"學校可能把實驗室使用限制在受訓學生。"},{"en":"If power transmission is limited to low voltages, long-distance AC becomes less useful.","zh":"如果電力傳輸被限制在低電壓，長距離交流電就變得較不有用。"},{"en":"The phrase describes placing a rule or boundary on electricity delivery.","zh":"這個短語描述對電力輸送設定規則或界限。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":14},{"front":"low voltages","meaning":"低電壓","examples":[{"en":"Edison tried to restrict transmission to low voltages.","zh":"愛迪生試圖把輸電限制在低電壓。"},{"en":"Low voltages are relatively low electrical pressure levels.","zh":"low voltages 是相對較低的電壓水平。"},{"en":"Low voltages are often safer for small devices and classroom experiments.","zh":"低電壓通常對小型裝置和課室實驗較安全。"},{"en":"If transmission is forced to use low voltages, power may not travel far economically.","zh":"如果輸電被迫使用低電壓，電力可能無法符合經濟效益地傳得很遠。"},{"en":"The phrase is the plural form used for several low-voltage levels or systems.","zh":"這個短語是複數形式，指多個低電壓水平或系統。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":14},{"front":"effectively eliminate","meaning":"實際上淘汰","examples":[{"en":"Low-voltage rules would effectively eliminate AC from the competition.","zh":"低電壓規則會實際上把交流電從競爭中淘汰。"},{"en":"To effectively eliminate something means to remove it in practice, even if not directly stated.","zh":"effectively eliminate 某物，指在實際上移除它，即使沒有直接說明。"},{"en":"A rule requiring expensive licences may effectively eliminate small food stalls.","zh":"要求昂貴牌照的規則可能實際上淘汰小食攤。"},{"en":"If a system cannot meet new rules, it may be effectively eliminated from the market.","zh":"如果系統不能符合新規則，它可能被實際上淘汰出市場。"},{"en":"The phrase describes practical removal through conditions or rules.","zh":"這個短語描述透過條件或規則造成的實際移除。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":14},{"front":"from the competition","meaning":"從競爭中","examples":[{"en":"Edison wanted to eliminate AC from the competition.","zh":"愛迪生想把交流電從競爭中淘汰。"},{"en":"From the competition means from the contest, market or rivalry being discussed.","zh":"from the competition 指從所討論的比賽、市場或競爭中。"},{"en":"A weak team may be removed from the competition after losing several matches.","zh":"弱隊連輸幾場後，可能被逐出競爭。"},{"en":"If rules exclude one product from the competition, customers have fewer choices.","zh":"如果規則把某產品排除在競爭之外，顧客就有較少選擇。"},{"en":"The phrase shows removal from a contest or rival situation.","zh":"這個短語顯示從比賽或競爭情境中移除。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":14},{"front":"be prepared to conduct","meaning":"準備進行","examples":[{"en":"Edison was prepared to conduct public electrocutions of animals.","zh":"愛迪生準備進行公開動物電刑示範。"},{"en":"To be prepared to conduct something means to be ready and willing to carry it out.","zh":"be prepared to conduct 某事，指準備好並願意執行它。"},{"en":"A school may be prepared to conduct extra lessons before important exams.","zh":"學校可能準備在重要考試前進行額外課堂。"},{"en":"If someone is prepared to conduct shocking demonstrations, they are strongly committed to their campaign.","zh":"如果某人準備進行震撼示範，他就是非常投入自己的運動。"},{"en":"The phrase shows readiness to perform an action.","zh":"這個短語顯示執行行動的準備。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":14},{"front":"public electrocutions","meaning":"公開電刑示範","examples":[{"en":"Edison conducted public electrocutions to frighten people.","zh":"愛迪生進行公開電刑示範來嚇怕人們。"},{"en":"Public electrocutions are killings or demonstrations using electricity in front of an audience.","zh":"public electrocutions 是在觀眾面前使用電力殺死生命或作示範。"},{"en":"A public safety demonstration should educate people, not shock them cruelly.","zh":"公共安全示範應教育人們，而不是殘忍地震撼他們。"},{"en":"If public electrocutions are used as propaganda, fear can replace honest debate.","zh":"如果公開電刑示範被用作宣傳，恐懼可能取代誠實辯論。"},{"en":"The phrase is disturbing and linked with attempts to influence public opinion.","zh":"這個短語令人不安，並與影響公眾輿論的企圖相關。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":14},{"front":"rogue elephant","meaning":"失控的大象","examples":[{"en":"Edison even used AC on a rogue elephant.","zh":"愛迪生甚至用交流電對付一頭失控的大象。"},{"en":"A rogue elephant is an elephant considered dangerous, uncontrollable or separated from normal control.","zh":"rogue elephant 是被視為危險、難以控制或脫離正常控制的大象。"},{"en":"A zoo would need expert help if a large animal became rogue and threatened visitors.","zh":"如果大型動物失控並威脅遊客，動物園需要專家協助。"},{"en":"If a rogue elephant is used in a public demonstration, the event can attract strong attention.","zh":"如果失控大象被用於公開示範，事件可以吸引強烈注意。"},{"en":"The phrase describes a dangerous animal, not a person here.","zh":"這個短語在此描述危險動物，而不是人。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":15},{"front":"circus owners","meaning":"馬戲團主人","examples":[{"en":"The rogue elephant was no longer wanted by its circus owners.","zh":"這頭失控的大象不再被馬戲團主人需要。"},{"en":"Circus owners are people or companies that own and manage a circus.","zh":"circus owners 是擁有和管理馬戲團的人或公司。"},{"en":"Circus owners are responsible for performers, animals, equipment and audience safety.","zh":"馬戲團主人負責表演者、動物、設備和觀眾安全。"},{"en":"If circus owners cannot control an animal, they may see it as a danger or cost.","zh":"如果馬戲團主人無法控制動物，他們可能把它視為危險或成本。"},{"en":"The phrase identifies who owned the elephant.","zh":"這個短語指出誰擁有那頭大象。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":15},{"front":"public opinion","meaning":"公眾輿論","examples":[{"en":"Edison tried to win the battle of public opinion.","zh":"愛迪生試圖贏得公眾輿論之戰。"},{"en":"Public opinion is what many ordinary people think about an issue.","zh":"public opinion 是許多普通人對某議題的看法。"},{"en":"Public opinion can change quickly after a powerful news report.","zh":"有力新聞報道後，公眾輿論可以迅速改變。"},{"en":"If public opinion turns against a company, customers may stop trusting it.","zh":"如果公眾輿論轉向反對公司，顧客可能停止信任它。"},{"en":"The phrase refers to society’s general view, not expert judgment only.","zh":"這個短語指社會整體看法，而不只是專家判斷。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":15},{"front":"battle of public opinion","meaning":"輿論戰","examples":[{"en":"The electrocutions were part of the battle of public opinion.","zh":"這些電刑示範是輿論戰的一部分。"},{"en":"A battle of public opinion is a struggle to persuade the public to support one side.","zh":"battle of public opinion 是說服公眾支持某一方的鬥爭。"},{"en":"Companies may fight a battle of public opinion after a product safety scandal.","zh":"產品安全醜聞後，公司可能打一場輿論戰。"},{"en":"If one side controls the story, it may win the battle of public opinion.","zh":"如果一方控制故事，它可能贏得輿論戰。"},{"en":"The phrase describes persuasion, reputation and media influence.","zh":"這個短語描述說服、名聲和媒體影響。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":15},{"front":"be filmed","meaning":"被拍攝下來","examples":[{"en":"The electrocution was filmed to influence public opinion.","zh":"這次電刑被拍攝下來，以影響公眾輿論。"},{"en":"To be filmed means to be recorded with a movie camera or video camera.","zh":"be filmed 指被電影攝影機或錄影機記錄下來。"},{"en":"A school performance may be filmed so parents can watch it later.","zh":"學校表演可能被拍攝下來，讓家長之後觀看。"},{"en":"If an event is filmed, the recording can be shown to people who were not there.","zh":"如果事件被拍攝下來，錄像可以播放給不在場的人看。"},{"en":"The phrase focuses on making a visual record.","zh":"這個短語重點在製作視覺紀錄。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":15},{"front":"the next logical step","meaning":"下一個合理步驟","examples":[{"en":"The next logical step was to show AC’s danger to people.","zh":"下一個合理步驟是向人們展示交流電的危險。"},{"en":"The next logical step is the action that seems to follow naturally from what came before.","zh":"the next logical step 是看似自然跟隨之前情況而來的行動。"},{"en":"After students learn basic vocabulary, the next logical step is to use it in sentences.","zh":"學生學會基本詞彙後，下一個合理步驟是在句子中使用它。"},{"en":"If a trial works well, the next logical step may be a larger test.","zh":"如果試驗效果良好，下一個合理步驟可能是更大規模測試。"},{"en":"The phrase suggests a reasonable sequence of action.","zh":"這個短語暗示合理的行動次序。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":15},{"front":"deadliness","meaning":"致命性","examples":[{"en":"Edison wanted to show AC’s deadliness to human beings.","zh":"愛迪生想向人類展示交流電的致命性。"},{"en":"Deadliness is the ability to cause death.","zh":"deadliness 是造成死亡的能力。"},{"en":"The deadliness of a poison depends on dose, exposure and the person’s health.","zh":"毒物的致命性取決於劑量、接觸程度和人的健康。"},{"en":"If people believe a technology has high deadliness, they may reject it out of fear.","zh":"如果人們相信某科技有高度致命性，他們可能因恐懼而拒絕它。"},{"en":"The word describes lethal danger.","zh":"這個字描述致命危險。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":15},{"front":"human beings themselves","meaning":"人類本身","examples":[{"en":"Edison tried to show that AC could kill human beings themselves.","zh":"愛迪生試圖展示交流電可以殺死人類本身。"},{"en":"Human beings themselves means people directly, not animals or objects.","zh":"human beings themselves 指人類直接受到影響，而不是動物或物件。"},{"en":"A safety rule matters most when human beings themselves could be harmed.","zh":"當人類本身可能受傷害時，安全規則最為重要。"},{"en":"If a danger affects human beings themselves, public reaction may become stronger.","zh":"如果危險影響人類本身，公眾反應可能變得更強。"},{"en":"The phrase stresses that people, not only test subjects, are involved.","zh":"這個短語強調涉及的是人，而不只是測試對象。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":15},{"front":"realise that","meaning":"意識到","examples":[{"en":"Edison realised that he was losing the war.","zh":"愛迪生意識到自己正在輸掉這場戰爭。"},{"en":"To realise that means to become aware of a fact or situation.","zh":"realise that 指開始明白某個事實或情況。"},{"en":"A student may realise that careless grammar is costing many marks.","zh":"學生可能意識到粗心文法正在令自己失去許多分數。"},{"en":"If managers realise that customers are leaving, they may change strategy quickly.","zh":"如果管理層意識到顧客正在離開，他們可能迅速改變策略。"},{"en":"The phrase marks a moment of understanding.","zh":"這個短語標示理解的一刻。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":15},{"front":"lose the war","meaning":"輸掉戰爭","examples":[{"en":"Edison realised that he was losing the war against AC.","zh":"愛迪生意識到自己正在輸掉對抗交流電的戰爭。"},{"en":"To lose the war means to fail in a major conflict or competition.","zh":"lose the war 指在重大衝突或競爭中失敗。"},{"en":"A company may lose the price war if it cannot keep lowering prices.","zh":"如果公司無法繼續降價，它可能輸掉價格戰。"},{"en":"If public opinion turns against one side, that side may lose the war of reputation.","zh":"如果公眾輿論轉向反對某一方，該方可能輸掉名譽戰。"},{"en":"The phrase can be literal or metaphorical.","zh":"這個短語可以是字面，也可以是比喻。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":15},{"front":"promote the use of","meaning":"推動使用……","examples":[{"en":"Edison promoted the use of AC for executions.","zh":"愛迪生推動使用交流電作處決用途。"},{"en":"To promote the use of something means to encourage people or authorities to use it.","zh":"promote the use of 某物，指鼓勵人們或當局使用它。"},{"en":"A school may promote the use of dictionaries during reading lessons.","zh":"學校可能推動在閱讀課使用字典。"},{"en":"If a company promotes the use of a product, it wants the public to accept it.","zh":"如果公司推動使用某產品，它希望公眾接受它。"},{"en":"The phrase describes encouraging adoption.","zh":"這個短語描述鼓勵採用。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":16},{"front":"execution of prisoners","meaning":"處決囚犯","examples":[{"en":"Edison promoted AC for the execution of prisoners.","zh":"愛迪生推動用交流電處決囚犯。"},{"en":"Execution of prisoners means legally killing prisoners as punishment.","zh":"execution of prisoners 指以法律懲罰形式殺死囚犯。"},{"en":"Discussions about the execution of prisoners often involve law, ethics and human rights.","zh":"關於處決囚犯的討論常涉及法律、倫理和人權。"},{"en":"If a technology is linked to executions, its public image may become darker.","zh":"如果一項科技與處決連繫起來，其公眾形象可能變得更陰暗。"},{"en":"The phrase refers to capital punishment.","zh":"這個短語指死刑。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":16},{"front":"electric chair","meaning":"電椅","examples":[{"en":"The first electric chair was constructed in 1890.","zh":"第一張電椅於1890年建造。"},{"en":"An electric chair is a device used to execute prisoners by electricity.","zh":"electric chair 是用電處決囚犯的裝置。"},{"en":"The electric chair became a symbol of electricity’s frightening power.","zh":"電椅成為電力可怕力量的象徵。"},{"en":"If a technology is associated with the electric chair, people may fear it more.","zh":"如果一項科技與電椅相關，人們可能更害怕它。"},{"en":"The phrase refers to a specific execution device.","zh":"這個短語指特定處決裝置。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":16},{"front":"be constructed in anticipation of","meaning":"為預備……而建造","examples":[{"en":"The electric chair was constructed in anticipation of a death sentence.","zh":"電椅是為預備一項死刑判決而建造的。"},{"en":"To be constructed in anticipation of something means to be built because that event is expected.","zh":"be constructed in anticipation of 某事，指因預期該事發生而建造。"},{"en":"Extra classrooms may be constructed in anticipation of more students next year.","zh":"學校可能為預備明年更多學生而建造額外課室。"},{"en":"If equipment is built in anticipation of an event, planners believe the event will happen soon.","zh":"如果設備是為預備某事件而建造，規劃者相信該事件很快會發生。"},{"en":"The phrase links construction with expectation.","zh":"這個短語把建造與預期連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":16},{"front":"impending death sentence","meaning":"即將執行的死刑","examples":[{"en":"The electric chair was prepared for an impending death sentence.","zh":"電椅是為即將執行的死刑而準備的。"},{"en":"An impending death sentence is a death penalty that is expected to be carried out soon.","zh":"impending death sentence 是預期很快執行的死刑。"},{"en":"Impending means something is about to happen, usually something serious or unpleasant.","zh":"impending 指某事即將發生，通常是嚴重或不愉快的事。"},{"en":"If an impending sentence is near, lawyers may make urgent appeals.","zh":"如果即將執行的判決臨近，律師可能提出緊急上訴。"},{"en":"The phrase creates a sense of seriousness and approaching consequence.","zh":"這個短語營造嚴重和後果逼近的感覺。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":16},{"front":"hire the best lawyers","meaning":"聘請最好的律師","examples":[{"en":"Westinghouse hired the best lawyers of the day.","zh":"Westinghouse 聘請了當時最好的律師。"},{"en":"To hire the best lawyers means to employ highly skilled legal professionals.","zh":"hire the best lawyers 指僱用非常有能力的法律專業人士。"},{"en":"A company may hire the best lawyers when a court case could damage its future.","zh":"當官司可能損害公司未來，公司可能聘請最好的律師。"},{"en":"If a case is important, hiring strong lawyers can improve the chance of success.","zh":"如果案件重要，聘請強大律師可以提高成功機會。"},{"en":"The phrase shows that the legal battle was serious.","zh":"這個短語顯示法律戰十分嚴重。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":16},{"front":"of the day","meaning":"當時的","examples":[{"en":"Westinghouse hired the best lawyers of the day.","zh":"Westinghouse 聘請了當時最好的律師。"},{"en":"Of the day means of that time or period.","zh":"of the day 指當時或那個時期的。"},{"en":"The best doctors of the day had fewer tools than modern doctors.","zh":"當時最好的醫生擁有的工具比現代醫生少。"},{"en":"If someone was famous among scientists of the day, their reputation was strong in that period.","zh":"如果某人在當時的科學家中很出名，其聲望在該時期很強。"},{"en":"The phrase places people or ideas in their historical moment.","zh":"這個短語把人物或想法放在其歷史時刻中。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":16},{"front":"defend the prisoner","meaning":"為囚犯辯護","examples":[{"en":"The lawyers were hired to defend the prisoner.","zh":"這些律師被聘請來為囚犯辯護。"},{"en":"To defend the prisoner means to represent and protect the prisoner in court.","zh":"defend the prisoner 指在法庭上代表並保護囚犯。"},{"en":"A lawyer must defend the prisoner by questioning evidence and presenting legal arguments.","zh":"律師必須透過質疑證據和提出法律論點來為囚犯辯護。"},{"en":"If a prisoner is not defended properly, the trial may be unfair.","zh":"如果囚犯沒有得到適當辯護，審訊可能不公平。"},{"en":"The phrase refers to legal defence, not physical protection only.","zh":"這個短語指法律辯護，而不只是實際保護。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":16},{"front":"in question","meaning":"所涉的；有關的","examples":[{"en":"The lawyers defended the prisoner in question.","zh":"律師為所涉囚犯辯護。"},{"en":"In question means the particular person or thing being discussed.","zh":"in question 指正在討論的特定人或物。"},{"en":"The teacher asked to see the homework in question before judging it.","zh":"老師在判斷前要求看有關功課。"},{"en":"If the device in question is faulty, customers should stop using it.","zh":"如果所涉裝置有故障，顧客應停止使用它。"},{"en":"The phrase identifies the specific case being referred to.","zh":"這個短語指出正在提及的特定個案。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":16},{"front":"as well as to prevent","meaning":"以及防止","examples":[{"en":"Westinghouse hired lawyers to defend the prisoner as well as to prevent AC executions.","zh":"Westinghouse 聘請律師為囚犯辯護，以及防止交流電被用於處決。"},{"en":"As well as to prevent means and also to stop something from happening.","zh":"as well as to prevent 指同時也為了阻止某事發生。"},{"en":"A school may add guards to protect students as well as to prevent strangers entering.","zh":"學校可能增加保安來保護學生，以及防止陌生人進入。"},{"en":"If one action has two aims, “as well as” connects both purposes.","zh":"如果一個行動有兩個目的，as well as 會連接兩者。"},{"en":"The phrase adds a second purpose to the first.","zh":"這個短語在第一目的之外加入第二目的。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":16},{"front":"be used for execution","meaning":"被用於處決","examples":[{"en":"Westinghouse tried to prevent AC from being used for execution.","zh":"Westinghouse 試圖防止交流電被用於處決。"},{"en":"To be used for execution means to serve as the method for carrying out a death sentence.","zh":"be used for execution 指被用作執行死刑的方法。"},{"en":"Many people object when technology is used for punishment rather than public benefit.","zh":"當科技被用於懲罰而不是公共利益，許多人會反對。"},{"en":"If AC was used for execution, its reputation could be damaged.","zh":"如果交流電被用於處決，其聲譽可能受損。"},{"en":"The phrase connects a tool with the act of capital punishment.","zh":"這個短語把工具與死刑行為連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":17},{"front":"fail in both respects","meaning":"在兩方面都失敗","examples":[{"en":"Westinghouse failed in both respects.","zh":"Westinghouse 在兩方面都失敗。"},{"en":"To fail in both respects means to fail in two different aims or areas.","zh":"fail in both respects 指在兩個不同目標或方面都失敗。"},{"en":"A student may fail in both respects if an essay is late and poorly written.","zh":"如果文章遲交且寫得差，學生可能在兩方面都失敗。"},{"en":"If a plan is meant to save money and improve service but does neither, it fails in both respects.","zh":"如果計劃原本要省錢和改善服務，但兩者都做不到，它就在兩方面都失敗。"},{"en":"The phrase points to two separate failures.","zh":"這個短語指出兩個分開的失敗。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":17},{"front":"the results were unexpected","meaning":"結果出乎意料","examples":[{"en":"The results of the execution campaign were unexpected.","zh":"處決宣傳運動的結果出乎意料。"},{"en":"The results were unexpected means the outcome was not what people predicted.","zh":"the results were unexpected 指結果不是人們預測的那樣。"},{"en":"The results of the school survey were unexpected because younger students liked longer reading time.","zh":"學校調查結果出乎意料，因為較年幼學生喜歡更長閱讀時間。"},{"en":"If results are unexpected, people may need to rethink their assumptions.","zh":"如果結果出乎意料，人們可能需要重新思考假設。"},{"en":"The phrase highlights surprise after an action or experiment.","zh":"這個短語突出行動或實驗後的驚訝。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":17},{"front":"botched execution","meaning":"失敗而可怕的處決","examples":[{"en":"The first electric-chair execution was a botched execution.","zh":"第一次電椅處決是一次失敗而可怕的處決。"},{"en":"A botched execution is an execution carried out badly, causing extra suffering or failure.","zh":"botched execution 是執行得很差、造成額外痛苦或失敗的處決。"},{"en":"A botched medical procedure is one done so poorly that it harms the patient.","zh":"失敗的醫療程序是做得很差並傷害病人的程序。"},{"en":"If an execution is botched, public horror may increase rather than support the method.","zh":"如果處決失敗而可怕，公眾恐懼可能增加，而不是支持該方法。"},{"en":"The phrase describes a serious and disturbing failure.","zh":"這個短語描述嚴重而令人不安的失敗。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":17},{"front":"the horror of the spectators","meaning":"旁觀者的恐懼","examples":[{"en":"The horror of the spectators did not destroy AC’s reputation.","zh":"旁觀者的恐懼並沒有摧毀交流電的名聲。"},{"en":"The horror of the spectators means the fear and shock felt by people watching an event.","zh":"the horror of the spectators 指觀看事件的人感到的恐懼和震驚。"},{"en":"The horror of spectators grew when a stage accident happened during a performance.","zh":"當表演期間發生舞台意外，旁觀者的恐懼加劇。"},{"en":"If spectators react with horror, the event may be remembered as cruel or unsafe.","zh":"如果旁觀者以恐懼反應，事件可能被記得為殘忍或不安全。"},{"en":"The phrase focuses on emotional reaction from witnesses.","zh":"這個短語重點在目擊者的情緒反應。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":17},{"front":"be stigmatised as","meaning":"被污名化為","examples":[{"en":"AC was not stigmatised as the killer Edison had hoped.","zh":"交流電沒有被污名化為愛迪生希望塑造的殺手形象。"},{"en":"To be stigmatised as something means to be unfairly labelled with a negative identity.","zh":"be stigmatised as 某物，指被不公平地貼上負面身份標籤。"},{"en":"Students should not be stigmatised as lazy simply because they learn more slowly.","zh":"學生不應只因學得較慢而被污名化為懶惰。"},{"en":"If a technology is stigmatised as dangerous, people may reject it before understanding it.","zh":"如果科技被污名化為危險，人們可能在理解前就拒絕它。"},{"en":"The phrase describes damaging social labelling.","zh":"這個短語描述有害的社會標籤。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":17},{"front":"the killer Edison had hoped","meaning":"愛迪生希望塑造的殺手形象","examples":[{"en":"AC did not become the killer Edison had hoped it would be seen as.","zh":"交流電沒有成為愛迪生希望公眾看見的殺手形象。"},{"en":"The killer Edison had hoped means the deadly image Edison wanted the public to associate with AC.","zh":"the killer Edison had hoped 指愛迪生希望公眾與交流電聯想起來的致命形象。"},{"en":"A rival may try to make a product look like the danger he hopes people will fear.","zh":"競爭者可能試圖把產品塑造成他希望人們害怕的危險形象。"},{"en":"If the public does not accept the negative image, the campaign fails.","zh":"如果公眾不接受負面形象，宣傳運動就失敗。"},{"en":"The phrase shows Edison’s intended framing of AC.","zh":"這個短語顯示愛迪生想如何框定交流電。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":17},{"front":"meanwhile","meaning":"與此同時","examples":[{"en":"Meanwhile, AC’s range and efficiency brought Westinghouse major projects.","zh":"與此同時，交流電的傳輸距離和效率為 Westinghouse 帶來重大項目。"},{"en":"Meanwhile means at the same time or during the same period.","zh":"meanwhile 指同一時間或同一時期內。"},{"en":"The students revised for exams; meanwhile, teachers prepared extra practice papers.","zh":"學生溫習考試；與此同時，老師準備額外練習卷。"},{"en":"If one company attacks a rival while the rival wins contracts, “meanwhile” shows the contrast.","zh":"如果一間公司攻擊對手，而對手同時贏得合約，meanwhile 就顯示對比。"},{"en":"The word links events happening side by side.","zh":"這個字連接並行發生的事件。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":17},{"front":"range and efficiency","meaning":"傳輸距離和效率","examples":[{"en":"AC’s range and efficiency made it attractive for major projects.","zh":"交流電的傳輸距離和效率令它對重大項目有吸引力。"},{"en":"Range and efficiency mean how far something can work and how well it uses resources.","zh":"range and efficiency 指某物能運作多遠，以及它如何有效使用資源。"},{"en":"A bus service with good range and efficiency reaches many areas without wasting fuel.","zh":"有良好覆蓋範圍和效率的巴士服務能到達許多地區，而不浪費燃油。"},{"en":"If a power system has better range and efficiency, it can serve distant customers at lower cost.","zh":"如果電力系統有更好的傳輸距離和效率，它就能以較低成本服務遠方客戶。"},{"en":"The phrase combines distance capability with practical performance.","zh":"這個短語結合距離能力與實際表現。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":17},{"front":"lead to someone being awarded","meaning":"導致某人獲得","examples":[{"en":"AC’s advantages led to Westinghouse being awarded major projects.","zh":"交流電的優勢導致 Westinghouse 獲得重大項目。"},{"en":"To lead to someone being awarded something means to cause that person or company to receive it officially.","zh":"lead to someone being awarded 某物，指造成某人或公司正式獲得它。"},{"en":"Strong exam results may lead to a student being awarded a scholarship.","zh":"優秀考試成績可能導致學生獲得獎學金。"},{"en":"If a company proves its system works, it may be awarded an important contract.","zh":"如果公司證明其系統有效，它可能獲得重要合約。"},{"en":"The phrase connects success with official recognition or selection.","zh":"這個短語把成功與官方認可或選中連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":17},{"front":"high-prestige engineering projects","meaning":"享有盛譽的工程項目","examples":[{"en":"Westinghouse was awarded high-prestige engineering projects.","zh":"Westinghouse 獲得享有盛譽的工程項目。"},{"en":"High-prestige engineering projects are important technical projects that bring honour and public recognition.","zh":"high-prestige engineering projects 是帶來榮譽和公眾認可的重要技術項目。"},{"en":"Building a city’s new railway can be a high-prestige engineering project.","zh":"建造城市新鐵路可以是享有盛譽的工程項目。"},{"en":"If a company wins high-prestige projects, its reputation can rise quickly.","zh":"如果公司贏得享有盛譽的項目，其聲譽可以快速上升。"},{"en":"The phrase stresses both technical importance and public status.","zh":"這個短語同時強調技術重要性和公眾地位。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":18},{"front":"Ames Hydro-electric Generating Plant","meaning":"艾姆斯水力發電廠","examples":[{"en":"The Ames Hydro-electric Generating Plant was an important AC project.","zh":"艾姆斯水力發電廠是一個重要的交流電項目。"},{"en":"The Ames Hydro-electric Generating Plant was a power plant that used water power to generate electricity.","zh":"Ames Hydro-electric Generating Plant 是使用水力發電的發電廠。"},{"en":"A hydro-electric plant uses moving water, often from rivers or falls, to produce electricity.","zh":"水力發電廠使用流動的水，通常來自河流或瀑布，來生產電力。"},{"en":"If an AC project works at a hydro-electric plant, it can prove the system’s practical value.","zh":"如果交流電項目在水力發電廠運作成功，就能證明該系統的實際價值。"},{"en":"The phrase names a specific engineering project in the AC story.","zh":"這個短語指出交流電故事中的特定工程項目。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":18},{"front":"Niagara Falls","meaning":"尼亞加拉瀑布","examples":[{"en":"Westinghouse also worked on a major project at Niagara Falls.","zh":"Westinghouse 也參與了尼亞加拉瀑布的一個重大項目。"},{"en":"Niagara Falls is a famous waterfall area used as a major source of hydro-electric power.","zh":"Niagara Falls 是著名瀑布區，也被用作重要水力發電來源。"},{"en":"Tourists visit Niagara Falls for scenery, but engineers also value its water power.","zh":"遊客到尼亞加拉瀑布欣賞景色，但工程師也重視其水力。"},{"en":"If electricity can be generated at Niagara Falls, water energy can be turned into useful power.","zh":"如果電力可以在尼亞加拉瀑布產生，水能就可以轉化為有用電力。"},{"en":"The phrase names a place linked with both nature and engineering.","zh":"這個短語指出一個同時與自然和工程相關的地方。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":18},{"front":"culminate in","meaning":"以……作為高潮；最終達到","examples":[{"en":"Westinghouse’s success culminated in a major public relations victory.","zh":"Westinghouse 的成功最終達到一次重大公關勝利。"},{"en":"To culminate in something means to reach a final or most important result.","zh":"culminate in 某事，指達到最終或最重要的結果。"},{"en":"Months of revision may culminate in a final exam.","zh":"數月溫習可能以期末考試作為高潮。"},{"en":"If a campaign culminates in a public win, earlier efforts appear worthwhile.","zh":"如果運動最終達到公開勝利，早前努力就顯得值得。"},{"en":"The phrase points to the climax or end result of a process.","zh":"這個短語指出過程的高潮或最終結果。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":18},{"front":"public relations victory","meaning":"公關勝利","examples":[{"en":"The Chicago contract was a great public relations victory for AC.","zh":"芝加哥合約是交流電的一次重大公關勝利。"},{"en":"A public relations victory is a success that improves public image and reputation.","zh":"public relations victory 是改善公眾形象和聲譽的成功。"},{"en":"A school wins a public relations victory when a student project receives national praise.","zh":"當學生項目獲得全國讚賞，學校就贏得一次公關勝利。"},{"en":"If a company proves its product publicly, it may gain a public relations victory.","zh":"如果公司公開證明其產品有效，它可能取得公關勝利。"},{"en":"The phrase is about reputation, not only technical success.","zh":"這個短語關於聲譽，而不只是技術成功。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":18},{"front":"contract to illuminate","meaning":"照明合約","examples":[{"en":"Westinghouse won the contract to illuminate the Columbian Exposition.","zh":"Westinghouse 贏得照亮哥倫布世界博覽會的合約。"},{"en":"A contract to illuminate a place is an agreement to provide lighting for it.","zh":"contract to illuminate 某地，是為該地提供照明的協議。"},{"en":"A company may win a contract to illuminate a stadium for night games.","zh":"公司可能贏得為體育場夜間比賽照明的合約。"},{"en":"If a firm wins a lighting contract for a famous event, its technology gains public attention.","zh":"如果企業贏得著名活動的照明合約，其科技會得到公眾關注。"},{"en":"The phrase connects a business agreement with lighting work.","zh":"這個短語把商業協議與照明工作連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":18},{"front":"Columbian Exposition","meaning":"哥倫布世界博覽會","examples":[{"en":"The Columbian Exposition in Chicago helped demonstrate AC power.","zh":"芝加哥的哥倫布世界博覽會幫助展示交流電力。"},{"en":"The Columbian Exposition was a major public exhibition where new technologies could be displayed.","zh":"Columbian Exposition 是一個可展示新科技的大型公共展覽。"},{"en":"A world exhibition can show visitors new machines, buildings and inventions.","zh":"世界博覽會可以向訪客展示新機器、建築和發明。"},{"en":"If AC worked well at the Columbian Exposition, many people could see its value directly.","zh":"如果交流電在哥倫布世界博覽會中運作良好，許多人就能直接看見其價值。"},{"en":"The phrase names the event that helped AC gain attention.","zh":"這個短語指出幫助交流電獲得關注的事件。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":18},{"front":"show the wonders of","meaning":"展示……的奇妙之處","examples":[{"en":"Tesla and Westinghouse showed the wonders of AC power.","zh":"特斯拉和 Westinghouse 展示了交流電力的奇妙之處。"},{"en":"To show the wonders of something means to demonstrate its impressive abilities.","zh":"show the wonders of 某物，指展示其令人驚嘆的能力。"},{"en":"A science fair can show the wonders of robotics to young students.","zh":"科學展可以向年輕學生展示機械人的奇妙之處。"},{"en":"If an exhibition shows the wonders of a technology, visitors may become supporters.","zh":"如果展覽展示某科技的奇妙之處，訪客可能成為支持者。"},{"en":"The phrase suggests amazement and public demonstration.","zh":"這個短語暗示驚嘆和公開展示。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":18},{"front":"AC power","meaning":"交流電力","examples":[{"en":"The Columbian Exposition demonstrated the power of AC.","zh":"哥倫布世界博覽會展示了交流電力。"},{"en":"AC power is electrical power supplied as alternating current.","zh":"AC power 是以交流電形式供應的電力。"},{"en":"AC power runs most household appliances through the normal electricity supply.","zh":"交流電力透過正常電力供應運行大多數家用電器。"},{"en":"If AC power can be transmitted far and used safely, it becomes suitable for cities.","zh":"如果交流電力可以遠距離傳輸並安全使用，它就適合城市使用。"},{"en":"The phrase refers to electricity delivered through alternating current.","zh":"這個短語指以交流電輸送的電力。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":18},{"front":"electrical exhibits","meaning":"電力展品","examples":[{"en":"The exhibition included various electrical exhibits.","zh":"展覽包括各種電力展品。"},{"en":"Electrical exhibits are displays that show electrical devices, systems or experiments.","zh":"electrical exhibits 是展示電力裝置、系統或實驗的展品。"},{"en":"A museum may use electrical exhibits to teach children how circuits work.","zh":"博物館可能使用電力展品教孩子電路如何運作。"},{"en":"If electrical exhibits are impressive, they can change public attitudes toward a technology.","zh":"如果電力展品令人印象深刻，它們可以改變公眾對科技的態度。"},{"en":"The phrase refers to displayed examples of electrical technology.","zh":"這個短語指被展示的電力科技例子。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":18},{"front":"fluorescent lamps","meaning":"光管；熒光燈","examples":[{"en":"Fluorescent lamps were shown at the exhibition.","zh":"光管在展覽中展出。"},{"en":"Fluorescent lamps are lights that use gas and electricity to produce bright light.","zh":"fluorescent lamps 是使用氣體和電力產生明亮光線的燈。"},{"en":"Older classrooms often used fluorescent lamps before LED lighting became common.","zh":"在 LED 照明普及前，舊課室常使用光管。"},{"en":"If fluorescent lamps are displayed at an exhibition, visitors can see new lighting possibilities.","zh":"如果光管在展覽中展出，訪客可以看見新的照明可能性。"},{"en":"The phrase refers to a type of electric lamp.","zh":"這個短語指一種電燈。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":19},{"front":"awestruck audience","meaning":"驚嘆不已的觀眾","examples":[{"en":"Tesla and Westinghouse impressed an awestruck audience.","zh":"特斯拉和 Westinghouse 令驚嘆不已的觀眾留下深刻印象。"},{"en":"An awestruck audience is a group of viewers filled with wonder and amazement.","zh":"awestruck audience 是充滿驚奇和讚嘆的觀眾。"},{"en":"A school choir may leave the audience awestruck if the performance is unexpectedly powerful.","zh":"如果學校合唱團的表演出乎意料地有力，觀眾可能驚嘆不已。"},{"en":"If technology amazes an awestruck audience, public support can grow quickly.","zh":"如果科技令觀眾驚嘆不已，公眾支持可以迅速增加。"},{"en":"The phrase describes strong admiration and surprise.","zh":"這個短語描述強烈欣賞和驚訝。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":19},{"front":"widespread press attention","meaning":"廣泛傳媒關注","examples":[{"en":"The AC exhibits received widespread press attention.","zh":"交流電展品獲得廣泛傳媒關注。"},{"en":"Widespread press attention means many newspapers or media outlets reported on something.","zh":"widespread press attention 指許多報章或媒體報道某事。"},{"en":"A student invention may receive widespread press attention after winning an international prize.","zh":"學生發明贏得國際獎項後，可能獲得廣泛傳媒關注。"},{"en":"If a project receives widespread press attention, more people learn about it quickly.","zh":"如果項目獲得廣泛傳媒關注，更多人會快速認識它。"},{"en":"The phrase links publicity with media coverage.","zh":"這個短語把宣傳與媒體報道連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":19},{"front":"effectively won","meaning":"實際上獲勝","examples":[{"en":"After the exhibition, the war was effectively won.","zh":"展覽後，這場戰爭實際上已獲勝。"},{"en":"Effectively won means won in practical terms, even if not formally declared.","zh":"effectively won 指在實際上已贏得，即使未正式宣布。"},{"en":"A team may have effectively won the match before the final whistle if it leads by many points.","zh":"如果一隊大幅領先，即使終場哨未響，也可能實際上已贏得比賽。"},{"en":"If public opinion and major contracts support one side, the competition may be effectively won.","zh":"如果公眾輿論和重大合約都支持一方，競爭可能實際上已獲勝。"},{"en":"The phrase focuses on practical reality rather than official wording.","zh":"這個短語重點在實際情況，而不是官方措辭。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":19},{"front":"take over almost completely","meaning":"幾乎完全取代","examples":[{"en":"AC would take over almost completely.","zh":"交流電將幾乎完全取代其他系統。"},{"en":"To take over almost completely means to become dominant and replace most alternatives.","zh":"take over almost completely 指成為主導並取代大多數替代方案。"},{"en":"Online booking has taken over almost completely in some travel businesses.","zh":"在一些旅遊企業中，網上預訂已幾乎完全取代其他方式。"},{"en":"If one system is cheaper and more efficient, it may take over almost completely.","zh":"如果一個系統更便宜和更高效，它可能幾乎完全取代其他系統。"},{"en":"The phrase suggests near-total dominance, not just popularity.","zh":"這個短語暗示近乎完全主導，而不只是流行。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":19},{"front":"complete the table","meaning":"完成表格","examples":[{"en":"Students complete the table using words from the passage.","zh":"學生使用文章中的字詞完成表格。"},{"en":"To complete the table means to fill in missing information in a table.","zh":"complete the table 指在表格中填入缺失資料。"},{"en":"In a science worksheet, students complete the table by writing results from an experiment.","zh":"在科學工作紙中，學生透過填寫實驗結果完成表格。"},{"en":"If students do not read the headings carefully, they may put answers in the wrong part of the table.","zh":"如果學生沒有仔細閱讀標題，可能把答案放錯表格位置。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":19},{"front":"no more than two words","meaning":"不超過兩個字","examples":[{"en":"Students should choose no more than two words from the passage.","zh":"學生應從文章中選擇不超過兩個字。"},{"en":"No more than two words means the answer can contain one or two words, but not three.","zh":"no more than two words 指答案可以有一個或兩個英文詞，但不能有三個。"},{"en":"If the answer is “storage batteries”, it follows the no-more-than-two-words rule.","zh":"如果答案是 storage batteries，就符合不超過兩個字的規則。"},{"en":"If students write extra words, the answer may be marked wrong even if the idea is correct.","zh":"如果學生寫額外字詞，即使意思正確，答案也可能被判錯。"},{"en":"The phrase gives a strict word limit.","zh":"這個短語給出嚴格字數限制。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":19},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must come from the passage.","zh":"答案必須來自文章。"},{"en":"From the passage means using words or information taken directly from the reading text.","zh":"from the passage 指使用直接來自閱讀文本的字詞或資料。"},{"en":"In IELTS reading, students should copy answers from the passage when the instruction says so.","zh":"在 IELTS 閱讀中，如果指示如此要求，學生應從文章中抄出答案。"},{"en":"If an answer comes from memory but not from the passage, it may not be accepted.","zh":"如果答案來自記憶而不是文章，可能不被接受。"},{"en":"The phrase reminds students not to invent their own wording.","zh":"這個短語提醒學生不要自創措辭。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":19},{"front":"supply can be supplemented with","meaning":"供電可由……補充","examples":[{"en":"The electricity supply can be supplemented with storage batteries.","zh":"供電可由蓄電池補充。"},{"en":"Supply can be supplemented with something means extra support can be added to the main supply.","zh":"supply can be supplemented with 某物，指可加入額外支援來補充主要供應。"},{"en":"A school lunch supply can be supplemented with fruit donations from parents.","zh":"學校午餐供應可由家長捐贈水果補充。"},{"en":"If demand rises suddenly, the normal supply can be supplemented with stored resources.","zh":"如果需求突然上升，正常供應可由儲備資源補充。"},{"en":"The phrase shows adding support rather than replacing the original supply.","zh":"這個短語顯示增加支援，而不是取代原本供應。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":19},{"front":"wire resistance","meaning":"電線電阻","examples":[{"en":"Wire resistance lowers the voltage over distance.","zh":"電線電阻隨距離增加降低電壓。"},{"en":"Wire resistance is the resistance in wires that opposes electric current.","zh":"wire resistance 是電線中阻礙電流的阻力。"},{"en":"Thin wires may create more wire resistance than thick wires.","zh":"幼電線可能比粗電線產生更高電線電阻。"},{"en":"If wire resistance is high, electricity loses strength before reaching users.","zh":"如果電線電阻高，電力在到達用戶前會失去強度。"},{"en":"The phrase explains one cause of voltage loss.","zh":"這個短語解釋電壓損失的一個原因。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":19},{"front":"lower the voltage","meaning":"降低電壓","examples":[{"en":"Wire resistance can lower the voltage.","zh":"電線電阻可以降低電壓。"},{"en":"To lower the voltage means to reduce the electrical pressure.","zh":"lower the voltage 指減少電壓。"},{"en":"A transformer can lower the voltage before electricity enters a home.","zh":"變壓器可以在電力進入家庭前降低電壓。"},{"en":"If voltage is lowered too far, equipment may not receive enough power.","zh":"如果電壓降低得太多，設備可能收不到足夠電力。"},{"en":"The phrase describes making voltage smaller.","zh":"這個短語描述令電壓變小。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":20},{"front":"could power","meaning":"能夠驅動","examples":[{"en":"Direct current could power DC motors.","zh":"直流電能夠驅動直流電摩打。"},{"en":"Could power means was able to provide energy for something to work.","zh":"could power 指能夠為某物運作提供能量。"},{"en":"A small battery could power a torch for several hours.","zh":"小電池可以驅動電筒數小時。"},{"en":"If a system could power many machines, factories would find it useful.","zh":"如果一個系統能夠驅動許多機器，工廠就會覺得它有用。"},{"en":"The phrase links an energy source with the device it runs.","zh":"這個短語把能源來源與其運行的裝置連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":20},{"front":"the only kind available then","meaning":"當時唯一可用的種類","examples":[{"en":"DC motors were the only kind available then.","zh":"直流電摩打是當時唯一可用的種類。"},{"en":"The only kind available then means the only type people could use at that time.","zh":"the only kind available then 指當時人們唯一可以使用的種類。"},{"en":"Before smartphones, basic mobile phones were the only kind available then for many users.","zh":"在智能手機出現前，對許多用戶而言，基本手機是當時唯一可用的種類。"},{"en":"If only one kind is available, people may choose it even if it has limitations.","zh":"如果只有一種可用，人們即使知道它有限制也可能選擇它。"},{"en":"The phrase explains a choice by historical availability.","zh":"這個短語透過歷史可用性解釋選擇。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":20},{"front":"generated income for","meaning":"為……帶來收入","examples":[{"en":"Patent royalties generated income for Edison.","zh":"專利使用費為愛迪生帶來收入。"},{"en":"To generate income for someone means to produce money for them.","zh":"generate income for 某人，指為他產生金錢收入。"},{"en":"A rented apartment can generate income for its owner every month.","zh":"出租單位可以每月為業主帶來收入。"},{"en":"If a patent becomes widely used, it can generate income for the inventor.","zh":"如果專利被廣泛使用，它可以為發明者帶來收入。"},{"en":"The phrase connects an activity or asset with earning money.","zh":"這個短語把活動或資產與賺錢連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":20},{"front":"choose three answers from","meaning":"從……中選擇三個答案","examples":[{"en":"Students choose three answers from the list.","zh":"學生從列表中選擇三個答案。"},{"en":"Choose three answers from a list means select exactly three options from the choices given.","zh":"choose three answers from a list 指從給出的選項中剛好選三個。"},{"en":"In a reading task, students may choose three answers from six possible statements.","zh":"在閱讀題中，學生可能從六個陳述中選三個答案。"},{"en":"If the instruction says three answers, choosing two or four can lose marks.","zh":"如果指示說三個答案，選兩個或四個都可能失分。"},{"en":"The phrase gives both the number and source of answers.","zh":"這個短語同時提供答案數量和來源。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":20},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Students write the correct letter next to each question.","zh":"學生在每題旁寫上正確字母。"},{"en":"To write the correct letter means to record the letter that matches the right option.","zh":"write the correct letter 指寫下與正確選項相配的字母。"},{"en":"In a multiple-choice test, students write the correct letter instead of the full answer.","zh":"在選擇題中，學生寫上正確字母，而不是完整答案。"},{"en":"If students choose the right idea but write the wrong letter, the answer may be marked wrong.","zh":"如果學生選對意思但寫錯字母，答案可能被判錯。"},{"en":"The phrase is an exam-format instruction.","zh":"這個短語是考試格式指示。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":20},{"front":"which three strategies","meaning":"哪三種策略","examples":[{"en":"The question asks which three strategies Edison used.","zh":"題目問愛迪生使用了哪三種策略。"},{"en":"Which three strategies means which three planned methods or actions were chosen.","zh":"which three strategies 指哪三種有計劃的方法或行動。"},{"en":"A teacher may ask which three strategies help students remember vocabulary best.","zh":"老師可能問哪三種策略最能幫助學生記住詞彙。"},{"en":"If a company uses several strategies, students must identify the exact three mentioned.","zh":"如果公司使用幾種策略，學生必須找出文中提及的確切三種。"},{"en":"The phrase asks for selected methods, not general opinions.","zh":"這個短語要求選出方法，而不是一般意見。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":20},{"front":"discredit AC current","meaning":"抹黑交流電","examples":[{"en":"Edison tried to discredit AC current.","zh":"愛迪生試圖抹黑交流電。"},{"en":"To discredit AC current means to damage public trust in alternating current.","zh":"discredit AC current 指破壞公眾對交流電的信任。"},{"en":"A rival company may try to discredit a product by exaggerating its weaknesses.","zh":"競爭公司可能透過誇大產品弱點來抹黑它。"},{"en":"If a technology is discredited, customers may avoid it even when evidence supports it.","zh":"如果科技被抹黑，即使證據支持它，顧客也可能避開它。"},{"en":"The phrase describes attacking reputation rather than proving a better alternative.","zh":"這個短語描述攻擊名聲，而不是證明更好替代方案。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":20},{"front":"hire lawyers","meaning":"聘請律師","examples":[{"en":"Westinghouse hired lawyers to prevent AC executions.","zh":"Westinghouse 聘請律師來防止交流電被用於處決。"},{"en":"To hire lawyers means to employ legal professionals for advice or representation.","zh":"hire lawyers 指聘用法律專業人士提供意見或代表。"},{"en":"A family may hire lawyers when a contract dispute becomes serious.","zh":"當合約糾紛變得嚴重，家庭可能聘請律師。"},{"en":"If a company hires lawyers, the issue may involve legal risk or court action.","zh":"如果公司聘請律師，該問題可能涉及法律風險或法庭行動。"},{"en":"The phrase shows seeking legal help.","zh":"這個短語顯示尋求法律協助。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":20},{"front":"pressure politicians","meaning":"向政客施壓","examples":[{"en":"Edison pressured politicians to limit power transmission.","zh":"愛迪生向政客施壓，要求限制電力傳輸。"},{"en":"To pressure politicians means to push elected officials to make a particular decision.","zh":"pressure politicians 指推動民選官員作出特定決定。"},{"en":"Parents may pressure politicians to improve school bus safety.","zh":"家長可能向政客施壓，要求改善校巴安全。"},{"en":"If businesses pressure politicians, laws may favour one industry group over another.","zh":"如果企業向政客施壓，法律可能偏向某個行業群體。"},{"en":"The phrase describes political influence and lobbying.","zh":"這個短語描述政治影響和游說。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":20},{"front":"invent DC devices","meaning":"發明直流電裝置","examples":[{"en":"Edison invented many DC devices.","zh":"愛迪生發明了許多直流電裝置。"},{"en":"To invent DC devices means to create machines or tools designed for direct current.","zh":"invent DC devices 指創造為直流電設計的機器或工具。"},{"en":"An engineer may invent medical devices that run on battery power.","zh":"工程師可能發明以電池供電的醫療裝置。"},{"en":"If an inventor creates many devices for one system, they may profit if that system spreads.","zh":"如果發明家為某一系統創造許多裝置，該系統普及時他可能獲利。"},{"en":"The phrase connects invention with a particular electrical system.","zh":"這個短語把發明與特定電力系統連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":21},{"front":"use movie cameras","meaning":"使用電影攝影機","examples":[{"en":"Edison used movie cameras to influence public opinion.","zh":"愛迪生使用電影攝影機來影響公眾輿論。"},{"en":"To use movie cameras means to record events on film.","zh":"use movie cameras 指用攝影機把事件拍攝成影片。"},{"en":"A school may use cameras to record a play for parents who cannot attend.","zh":"學校可能使用攝影機錄下話劇，給不能出席的家長觀看。"},{"en":"If a campaign uses movie cameras, it can spread images to a wider audience.","zh":"如果宣傳運動使用電影攝影機，它就能把影像傳給更廣泛觀眾。"},{"en":"The phrase shows how visual media can shape opinion.","zh":"這個短語顯示視覺媒體如何塑造意見。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":21},{"front":"scare people","meaning":"恐嚇人們","examples":[{"en":"Edison tried to scare people about AC.","zh":"愛迪生試圖令人民害怕交流電。"},{"en":"To scare people means to make them feel afraid.","zh":"scare people 指令人感到害怕。"},{"en":"False rumours can scare people into avoiding safe public transport.","zh":"虛假謠言可以嚇怕人們，使他們避開安全的公共交通。"},{"en":"If a campaign scares people rather than informs them, decisions may become emotional.","zh":"如果宣傳運動是恐嚇人們而不是告知他們，決定可能變得情緒化。"},{"en":"The phrase describes creating fear, often deliberately.","zh":"這個短語描述製造恐懼，通常是有意的。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":21},{"front":"invent the electric chair","meaning":"發明電椅","examples":[{"en":"The electric chair was invented to use electricity for execution.","zh":"電椅被發明來使用電力處決。"},{"en":"To invent the electric chair means to create a device for carrying out execution by electricity.","zh":"invent the electric chair 指創造用電執行處決的裝置。"},{"en":"An invention can be controversial if it is designed to harm rather than help people.","zh":"如果一項發明是為傷害而不是幫助人而設計，它可能很具爭議。"},{"en":"If electricity is linked to the electric chair, the public may associate it with death.","zh":"如果電力與電椅連繫起來，公眾可能把它與死亡聯想在一起。"},{"en":"The phrase refers to creating a specific execution device.","zh":"這個短語指創造特定處決裝置。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":21},{"front":"answer the questions","meaning":"回答問題","examples":[{"en":"Students answer the questions by choosing the correct letter.","zh":"學生透過選出正確字母回答問題。"},{"en":"To answer the questions means to provide responses to the tasks given.","zh":"answer the questions 指對給出的任務提供答案。"},{"en":"Students should read the passage carefully before they answer the questions.","zh":"學生回答問題前，應仔細閱讀文章。"},{"en":"If students answer the questions too quickly, they may miss key details.","zh":"如果學生太快回答問題，可能錯過關鍵細節。"},{"en":"The phrase is a general instruction in exercises and exams.","zh":"這個短語是練習和考試中的一般指示。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":21},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter for each question.","zh":"學生為每題選出正確字母。"},{"en":"To choose the correct letter means to select the lettered option that matches the right answer.","zh":"choose the correct letter 指選出與正確答案相配的字母選項。"},{"en":"In a multiple-choice task, students choose the correct letter after comparing all options.","zh":"在選擇題中，學生比較所有選項後選出正確字母。"},{"en":"If two options look similar, students should return to the passage before choosing the letter.","zh":"如果兩個選項看起來相似，學生在選字母前應回到文章。"},{"en":"The phrase tells students the required answer format.","zh":"這個短語告訴學生所需答案格式。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":21},{"front":"favour AC","meaning":"支持交流電","examples":[{"en":"Tesla and Westinghouse favoured AC.","zh":"特斯拉和 Westinghouse 支持交流電。"},{"en":"To favour AC means to prefer or support alternating current.","zh":"favour AC 指偏好或支持交流電。"},{"en":"A city may favour buses over cars if it wants to reduce traffic.","zh":"如果城市想減少交通擠塞，可能支持巴士而不是私家車。"},{"en":"If engineers favour AC, they may argue that it travels more efficiently over long distances.","zh":"如果工程師支持交流電，他們可能主張它能更高效地長距離傳輸。"},{"en":"The phrase shows preference for one system over another.","zh":"這個短語顯示對一個系統而非另一個系統的偏好。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":21},{"front":"start a company","meaning":"創辦公司","examples":[{"en":"Edison and Westinghouse both started companies.","zh":"愛迪生和 Westinghouse 都創辦了公司。"},{"en":"To start a company means to create a new business.","zh":"start a company 指建立一間新企業。"},{"en":"Two classmates may start a company after their app becomes popular.","zh":"兩位同學的應用程式變得流行後，可能創辦公司。"},{"en":"If inventors start a company, they can sell their ideas instead of only designing them.","zh":"如果發明家創辦公司，他們就能銷售自己的想法，而不只是設計它們。"},{"en":"The phrase focuses on beginning a business.","zh":"這個短語重點在開始一盤生意。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":21},{"front":"have a face-to-face fight","meaning":"面對面爭執","examples":[{"en":"Edison and Tesla had a face-to-face confrontation.","zh":"愛迪生和特斯拉曾有一次面對面衝突。"},{"en":"To have a face-to-face fight means to argue or clash directly in person.","zh":"have a face-to-face fight 指親身直接爭吵或衝突。"},{"en":"Two neighbours may have a face-to-face fight after months of noise complaints.","zh":"兩個鄰居在數月噪音投訴後，可能面對面爭執。"},{"en":"If people fight face to face, emotions can rise more quickly than in emails.","zh":"如果人們面對面爭執，情緒可能比電郵中升得更快。"},{"en":"The phrase stresses direct personal conflict.","zh":"這個短語強調直接的人際衝突。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":21},{"front":"invent many devices","meaning":"發明許多裝置","examples":[{"en":"Edison and Tesla invented many electrical devices.","zh":"愛迪生和特斯拉發明了許多電力裝置。"},{"en":"To invent many devices means to create many machines, tools or technical objects.","zh":"invent many devices 指創造許多機器、工具或技術物件。"},{"en":"A robotics team may invent many devices before choosing the best design.","zh":"機械人團隊在選出最佳設計前，可能發明許多裝置。"},{"en":"If inventors create many devices, some may become commercially valuable.","zh":"如果發明家創造許多裝置，其中一些可能具有商業價值。"},{"en":"The phrase stresses repeated creative output.","zh":"這個短語強調反覆的創造產出。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":21},{"front":"own many patents","meaning":"擁有許多專利","examples":[{"en":"Edison and Westinghouse owned many patents.","zh":"愛迪生和 Westinghouse 擁有許多專利。"},{"en":"To own many patents means to possess legal rights over many inventions.","zh":"own many patents 指擁有許多發明的法律權利。"},{"en":"A technology company may own many patents for phone screens, cameras and batteries.","zh":"科技公司可能擁有許多關於手機屏幕、相機和電池的專利。"},{"en":"If a company owns many patents, competitors may need permission to use similar ideas.","zh":"如果公司擁有許多專利，競爭者可能需要許可才能使用相似想法。"},{"en":"The phrase links legal ownership with technological power.","zh":"這個短語把法律擁有權與科技力量連繫起來。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":22},{"front":"be well educated","meaning":"受過良好教育","examples":[{"en":"Tesla and Westinghouse were well educated in technical fields.","zh":"特斯拉和 Westinghouse 在技術領域受過良好教育。"},{"en":"To be well educated means to have received strong and useful education.","zh":"be well educated 指接受過扎實而有用的教育。"},{"en":"A well-educated engineer can explain both the theory and the practical risks of a design.","zh":"受過良好教育的工程師可以解釋設計的理論和實際風險。"},{"en":"If workers are well educated in their field, they can solve problems more independently.","zh":"如果工人在自己的領域受過良好教育，他們就能更獨立地解決問題。"},{"en":"The phrase refers to depth of learning, not only having certificates.","zh":"這個短語指學習深度，而不只是擁有證書。"}],"source":"89 - AC or DC - The War of Currents.pdf","sourcePage":22}],"ielts/reading/passage-2/Practice 90":[{"front":"sampling bias","meaning":"抽樣偏差","examples":[{"en":"Sampling bias is one of the biggest problems in statistical data gathering.","zh":"抽樣偏差是統計數據收集中的最大問題之一。"},{"en":"Sampling bias happens when the people or items selected do not fairly represent the whole group.","zh":"抽樣偏差發生於被選中的人或物未能公平代表整個群體。"},{"en":"A school survey has sampling bias if it asks only top students about homework stress.","zh":"如果學校調查只問尖子學生功課壓力，就會有抽樣偏差。"},{"en":"Sampling bias can make results look precise while still leading to the wrong conclusion.","zh":"抽樣偏差可以令結果看似精確，但仍導致錯誤結論。"},{"en":"Even a large survey can suffer from sampling bias if important groups are left out.","zh":"即使調查規模很大，如果遺漏重要群體，也可能出現抽樣偏差。"}],"source":"90 - Sampling Bias.pdf","sourcePage":1},{"front":"primitive ancestors","meaning":"原始祖先","examples":[{"en":"Our primitive ancestors left many paintings on cave walls.","zh":"我們的原始祖先在洞穴牆壁上留下許多畫作。"},{"en":"Primitive ancestors are very early human relatives or early people from long before modern society.","zh":"primitive ancestors 指遠早於現代社會的早期人類親屬或早期人類。"},{"en":"Students learn about primitive ancestors by studying tools, bones, shelters and paintings.","zh":"學生透過研究工具、骨頭、住所和畫作來了解原始祖先。"},{"en":"Because primitive ancestors left few written records, physical evidence is very important.","zh":"因為原始祖先留下很少文字記錄，實物證據非常重要。"},{"en":"This phrase refers to early humans, not people who were simple-minded or inferior.","zh":"這個短語指早期人類，而不是指人思想簡單或低等。"}],"source":"90 - Sampling Bias.pdf","sourcePage":1},{"front":"leave paintings on","meaning":"在……留下畫作","examples":[{"en":"Prehistoric people left paintings on the walls inside caves.","zh":"史前人在洞穴內的牆壁上留下畫作。"},{"en":"To leave paintings on a surface means to create pictures there that remain after the artists are gone.","zh":"leave paintings on a surface 指在某表面創作圖畫，並在創作者離開後仍留下來。"},{"en":"Children may leave drawings on a classroom board before the teacher cleans it.","zh":"孩子可能在老師清理前，在課室白板上留下畫作。"},{"en":"Paintings left on stone can survive longer than paintings on paper or cloth.","zh":"留在石頭上的畫作可以比留在紙或布上的畫作保存更久。"},{"en":"This phrase focuses on traces that remain in a place.","zh":"這個短語著重留在某地的痕跡。"}],"source":"90 - Sampling Bias.pdf","sourcePage":1},{"front":"walls inside caves","meaning":"洞穴內的牆壁","examples":[{"en":"Many ancient paintings were found on walls inside caves.","zh":"許多古代畫作被發現在洞穴內的牆壁上。"},{"en":"Walls inside caves are the inner rock surfaces of caves.","zh":"walls inside caves 指洞穴內部的岩石表面。"},{"en":"Archaeologists may study walls inside caves because they can preserve old marks and drawings.","zh":"考古學家可能研究洞穴內的牆壁，因為它們能保存古老痕跡和圖畫。"},{"en":"Cave walls protect paintings from rain, wind and sunlight better than open rock surfaces.","zh":"洞穴牆壁比露天岩石表面更能保護畫作免受雨、風和陽光影響。"},{"en":"This phrase explains where the evidence was found.","zh":"這個短語說明證據被發現的位置。"}],"source":"90 - Sampling Bias.pdf","sourcePage":1},{"front":"evidence of","meaning":"……的證據","examples":[{"en":"There is evidence of fire pits, refuse sites and burial sites near the caves.","zh":"洞穴附近有火坑、廢物遺址和墓葬遺址的證據。"},{"en":"Evidence of something is information or material that shows it existed or happened.","zh":"evidence of something 指顯示某事存在或發生過的資訊或材料。"},{"en":"Muddy shoes are evidence of someone walking through wet ground.","zh":"沾滿泥的鞋是有人走過濕地的證據。"},{"en":"Strong evidence helps researchers avoid guessing about the past.","zh":"強證據幫助研究人員避免憑空猜測過去。"},{"en":"This phrase points to clues that support a conclusion.","zh":"這個短語指出支持結論的線索。"}],"source":"90 - Sampling Bias.pdf","sourcePage":1},{"front":"fire pits","meaning":"火坑","examples":[{"en":"Fire pits provide evidence of daily life near the caves.","zh":"火坑提供了洞穴附近日常生活的證據。"},{"en":"Fire pits are places where people made fires for warmth, cooking or protection.","zh":"fire pits 指人們用來生火取暖、煮食或防護的地方。"},{"en":"Campers may dig small fire pits to cook food safely outdoors.","zh":"露營者可能挖小火坑，在戶外安全煮食。"},{"en":"Ancient fire pits can contain ash, burnt bones and tools, giving clues about human habits.","zh":"古代火坑可能含有灰燼、燒焦骨頭和工具，提供人類習慣的線索。"},{"en":"This phrase refers to physical remains of controlled fire use.","zh":"這個短語指受控用火留下的實物遺跡。"}],"source":"90 - Sampling Bias.pdf","sourcePage":1},{"front":"refuse sites","meaning":"垃圾堆放處；廢物遺址","examples":[{"en":"Refuse sites suggest that people once lived near these places.","zh":"廢物遺址顯示人們曾經住在這些地方附近。"},{"en":"Refuse sites are places where waste or rubbish was thrown away.","zh":"refuse sites 指人們丟棄廢物或垃圾的地方。"},{"en":"A modern refuse site may contain food packaging, broken furniture and old appliances.","zh":"現代垃圾堆放處可能包含食物包裝、破家具和舊電器。"},{"en":"Ancient refuse sites can reveal what people ate, used and threw away.","zh":"古代廢物遺址可以揭示人們吃甚麼、用甚麼和丟棄甚麼。"},{"en":"This phrase refers to waste areas that become historical evidence.","zh":"這個短語指成為歷史證據的廢物區域。"}],"source":"90 - Sampling Bias.pdf","sourcePage":1},{"front":"burial sites","meaning":"埋葬地點；墓葬遺址","examples":[{"en":"Burial sites provide clues about prehistoric life.","zh":"墓葬遺址提供關於史前生活的線索。"},{"en":"Burial sites are places where dead people were placed or buried.","zh":"burial sites 指死者被安放或埋葬的地方。"},{"en":"Archaeologists study burial sites to learn about beliefs, tools, clothing and social status.","zh":"考古學家研究墓葬遺址，以了解信仰、工具、衣物和社會地位。"},{"en":"Objects found in burial sites can show what a community valued.","zh":"墓葬遺址中發現的物件可以顯示一個社群重視甚麼。"},{"en":"This phrase refers to graves or places connected with death rituals.","zh":"這個短語指墳墓或與死亡儀式相關的地方。"}],"source":"90 - Sampling Bias.pdf","sourcePage":1},{"front":"one could equally imagine","meaning":"同樣可以想像","examples":[{"en":"One could equally imagine evidence of daily life on exposed cliffs.","zh":"人們同樣可以想像日常生活的證據曾在暴露在外的懸崖上。"},{"en":"One could equally imagine means it is just as reasonable to think of another possibility.","zh":"one could equally imagine 指另一種可能性同樣合理、同樣可以被想到。"},{"en":"One could equally imagine students studying in cafés if the library is too crowded.","zh":"如果圖書館太擠，人們同樣可以想像學生在咖啡店溫習。"},{"en":"This phrase helps challenge a narrow explanation by offering another possible scenario.","zh":"這個短語透過提出另一種可能情境，挑戰狹窄解釋。"},{"en":"It is useful when the evidence allows more than one interpretation.","zh":"當證據容許多於一種詮釋時，這個短語很有用。"}],"source":"90 - Sampling Bias.pdf","sourcePage":1},{"front":"evidence of daily life","meaning":"日常生活的證據","examples":[{"en":"Evidence of daily life may once have existed outside caves.","zh":"日常生活的證據可能曾經存在於洞穴以外。"},{"en":"Evidence of daily life is material that shows how people ate, worked, slept or organised ordinary activities.","zh":"evidence of daily life 指顯示人們如何飲食、工作、睡覺或安排日常活動的材料。"},{"en":"Old cooking pots can be evidence of daily life in an ancient village.","zh":"舊煮食鍋可以是古村落日常生活的證據。"},{"en":"Such evidence helps researchers understand normal habits, not only dramatic events.","zh":"這類證據幫助研究人員理解普通習慣，而不只是重大事件。"},{"en":"This phrase refers to clues about everyday living.","zh":"這個短語指關於日常生活的線索。"}],"source":"90 - Sampling Bias.pdf","sourcePage":1},{"front":"exposed cliffs","meaning":"暴露在外的懸崖","examples":[{"en":"Evidence on exposed cliffs would probably have disappeared over time.","zh":"暴露在外的懸崖上的證據很可能已隨時間消失。"},{"en":"Exposed cliffs are open rock faces that are not protected from wind, rain or sunlight.","zh":"exposed cliffs 指沒有受到風、雨或陽光保護的露天岩壁。"},{"en":"Paint on exposed cliffs may fade quickly because weather hits it directly.","zh":"暴露在外的懸崖上的顏料可能很快褪色，因為天氣直接影響它。"},{"en":"Evidence on exposed cliffs is less likely to survive than evidence inside caves.","zh":"暴露懸崖上的證據比洞穴內的證據較不可能保存下來。"},{"en":"This phrase highlights a place that is open to natural damage.","zh":"這個短語突出一個暴露於自然破壞中的地方。"}],"source":"90 - Sampling Bias.pdf","sourcePage":2},{"front":"hillsides","meaning":"山坡","examples":[{"en":"Evidence on hillsides may have been eroded away.","zh":"山坡上的證據可能已被侵蝕掉。"},{"en":"Hillsides are sloping areas of land on the sides of hills.","zh":"hillsides 指山的側面斜坡地帶。"},{"en":"Farmers may plant trees on hillsides to reduce soil loss after heavy rain.","zh":"農民可能在山坡種樹，以減少大雨後泥土流失。"},{"en":"Objects left on hillsides can move, break or disappear because water runs downhill.","zh":"留在山坡上的物件可能因水向下流而移動、破碎或消失。"},{"en":"This phrase describes open sloping land, not a protected shelter.","zh":"這個短語描述露天斜坡地，而不是受保護的住所。"}],"source":"90 - Sampling Bias.pdf","sourcePage":2},{"front":"animal skins","meaning":"動物皮","examples":[{"en":"Paintings on animal skins would have rotted away long ago.","zh":"動物皮上的畫作早就會腐爛消失。"},{"en":"Animal skins are hides from animals that can be used for clothing, shelter or surfaces for drawing.","zh":"animal skins 指來自動物的皮，可用作衣物、遮蔽物或繪畫表面。"},{"en":"Early people may have used animal skins to keep warm in cold weather.","zh":"早期人類可能使用動物皮在寒冷天氣保暖。"},{"en":"Because animal skins are organic, they decay more easily than stone.","zh":"因為動物皮是有機材料，它比石頭更容易腐爛。"},{"en":"This phrase refers to natural material that usually does not survive for very long.","zh":"這個短語指通常不能長久保存的天然材料。"}],"source":"90 - Sampling Bias.pdf","sourcePage":2},{"front":"beside rivers and coastlines","meaning":"在河邊和海岸旁","examples":[{"en":"Evidence beside rivers and coastlines would have been washed away.","zh":"在河邊和海岸旁的證據本會被沖走。"},{"en":"Beside rivers and coastlines means next to rivers or the edges of seas and oceans.","zh":"beside rivers and coastlines 指在河流旁或海洋邊緣附近。"},{"en":"People often build homes beside rivers and coastlines because water and food are nearby.","zh":"人們常在河邊和海岸旁建屋，因為水和食物較近。"},{"en":"Floods, tides and storms can destroy evidence left beside rivers and coastlines.","zh":"洪水、潮汐和風暴可以破壞留在河邊和海岸旁的證據。"},{"en":"This phrase highlights places where water can remove traces of the past.","zh":"這個短語突出水能移走過去痕跡的地方。"}],"source":"90 - Sampling Bias.pdf","sourcePage":2},{"front":"would have long been","meaning":"早已經……","examples":[{"en":"Such evidence would have long been destroyed by natural processes.","zh":"這類證據早已經被自然過程破壞。"},{"en":"Would have long been means something probably happened far before now.","zh":"would have long been 指某事很可能在很久以前已經發生。"},{"en":"A paper notice left outside would have long been ruined by rain and sunlight.","zh":"留在戶外的紙張通告早已經被雨水和陽光破壞。"},{"en":"This structure is used to reason about what likely happened in the past.","zh":"這個結構用來推論過去很可能發生了甚麼。"},{"en":"It often explains why certain evidence is no longer available.","zh":"它常用來解釋為何某些證據已不再存在。"}],"source":"90 - Sampling Bias.pdf","sourcePage":2},{"front":"washed away","meaning":"被沖走","examples":[{"en":"Evidence beside rivers would have been washed away.","zh":"河邊的證據本會被沖走。"},{"en":"Washed away means removed by moving water.","zh":"washed away 指被流動的水移走。"},{"en":"Heavy rain washed away the chalk marks on the playground.","zh":"大雨把操場上的粉筆痕跡沖走了。"},{"en":"Floods can wash away small objects, soil and traces of old settlements.","zh":"洪水可以沖走小物件、泥土和舊聚落痕跡。"},{"en":"This phrase explains disappearance caused by water.","zh":"這個短語解釋由水造成的消失。"}],"source":"90 - Sampling Bias.pdf","sourcePage":2},{"front":"eroded away","meaning":"被侵蝕掉","examples":[{"en":"Evidence on exposed cliffs may have been eroded away.","zh":"暴露懸崖上的證據可能已被侵蝕掉。"},{"en":"Eroded away means gradually worn down or removed by wind, water or weather.","zh":"eroded away 指被風、水或天氣逐漸磨損或移除。"},{"en":"Waves can erode away the edge of a beach over many years.","zh":"海浪可以在多年之間侵蝕掉海灘邊緣。"},{"en":"Evidence on open rock can be eroded away before archaeologists ever find it.","zh":"露天岩石上的證據可能在考古學家發現前已被侵蝕掉。"},{"en":"This phrase suggests slow natural destruction.","zh":"這個短語表示緩慢的自然破壞。"}],"source":"90 - Sampling Bias.pdf","sourcePage":2},{"front":"rotted away","meaning":"腐爛消失","examples":[{"en":"Organic materials such as animal skins would have rotted away.","zh":"動物皮等有機材料本會腐爛消失。"},{"en":"Rotted away means decayed and disappeared because of natural breakdown.","zh":"rotted away 指因自然分解而腐爛並消失。"},{"en":"Fruit left in a warm room can rot away within days.","zh":"放在溫暖房間的水果可能在幾天內腐爛消失。"},{"en":"Wood, cloth and skin can rot away much faster than stone or metal.","zh":"木、布和皮比石頭或金屬更快腐爛消失。"},{"en":"This phrase explains why soft natural materials often leave little evidence.","zh":"這個短語解釋為何柔軟天然材料常留下很少證據。"}],"source":"90 - Sampling Bias.pdf","sourcePage":2},{"front":"prehistoric people","meaning":"史前人類","examples":[{"en":"Prehistoric people are often characterised as cavemen.","zh":"史前人類常被描述為穴居人。"},{"en":"Prehistoric people are humans who lived before written history.","zh":"prehistoric people 指生活在文字歷史以前的人類。"},{"en":"Students study prehistoric people through bones, tools, art and settlement remains.","zh":"學生透過骨頭、工具、藝術和聚落遺跡研究史前人類。"},{"en":"Because they left no written records, modern ideas about them depend heavily on surviving evidence.","zh":"因為他們沒有留下文字記錄，現代人對他們的看法高度依賴保存下來的證據。"},{"en":"This phrase refers to early humans from before recorded history.","zh":"這個短語指有文字記錄以前的早期人類。"}],"source":"90 - Sampling Bias.pdf","sourcePage":2},{"front":"be characterised as","meaning":"被描述為；被界定為","examples":[{"en":"Prehistoric people are characterised as cavemen because most evidence is found in caves.","zh":"史前人類被描述為穴居人，因為大部分證據在洞穴中被發現。"},{"en":"To be characterised as something means to be described or presented in that way.","zh":"be characterised as something 指被描述或呈現為某種樣子。"},{"en":"A quiet student may be characterised as shy, even if they are simply careful.","zh":"安靜學生可能被描述為害羞，即使他只是謹慎。"},{"en":"Characterising a group wrongly can create a misleading picture.","zh":"錯誤界定一個群體會造成誤導印象。"},{"en":"This phrase often shows how people are labelled or understood.","zh":"這個短語常顯示人們如何被貼標籤或被理解。"}],"source":"90 - Sampling Bias.pdf","sourcePage":2},{"front":"cavemen","meaning":"穴居人","examples":[{"en":"The word cavemen may reflect sampling bias rather than real living habits.","zh":"「穴居人」一詞可能反映抽樣偏差，而不是真實生活習慣。"},{"en":"Cavemen is a traditional term for prehistoric people imagined as living mainly in caves.","zh":"cavemen 是傳統上把史前人類想像為主要住在洞穴中的詞語。"},{"en":"Children may picture cavemen with stone tools and animal skins.","zh":"孩子可能把穴居人想像成拿着石器、穿着動物皮的人。"},{"en":"The term can be misleading if cave evidence survives simply because caves protect it better.","zh":"如果洞穴證據只是因為洞穴較能保護它而保存下來，這個詞可能具誤導性。"},{"en":"This word may describe the evidence we found more than where people actually lived.","zh":"這個詞描述的可能更多是我們找到的證據，而不是人們實際住在哪裡。"}],"source":"90 - Sampling Bias.pdf","sourcePage":3},{"front":"be presumed to","meaning":"被推定為","examples":[{"en":"Prehistoric people are presumed to have lived mainly in caves.","zh":"史前人類被推定為主要住在洞穴中。"},{"en":"To be presumed to do something means to be believed to do it without complete proof.","zh":"be presumed to do something 指在沒有完整證明下被相信會做某事。"},{"en":"A missing student may be presumed to be at home until the school calls the family.","zh":"在學校致電家庭前，失蹤學生可能被推定為在家。"},{"en":"Presumptions can be useful, but they may be wrong if the evidence is incomplete.","zh":"推定可能有用，但如果證據不完整，也可能錯誤。"},{"en":"This phrase shows an assumption rather than a proven fact.","zh":"這個短語表示假設，而不是已證明事實。"}],"source":"90 - Sampling Bias.pdf","sourcePage":3},{"front":"have a predilection for","meaning":"偏愛……","examples":[{"en":"They were presumed to have a predilection for dwelling in caves.","zh":"他們被推定為偏愛住在洞穴中。"},{"en":"To have a predilection for something means to have a strong preference for it.","zh":"have a predilection for something 指對某事有強烈偏好。"},{"en":"A student may have a predilection for visual notes rather than long paragraphs.","zh":"學生可能偏愛視覺筆記，而不是長段文字。"},{"en":"People may wrongly assume a preference when they see only limited evidence.","zh":"當人們只看到有限證據時，可能錯誤假設某種偏好。"},{"en":"This phrase is formal and means “tend to like”.","zh":"這個短語較正式，意思是「傾向喜歡」。"}],"source":"90 - Sampling Bias.pdf","sourcePage":3},{"front":"dwell in","meaning":"居住於","examples":[{"en":"Prehistoric people were thought to dwell in caves.","zh":"人們曾認為史前人類居住於洞穴。"},{"en":"To dwell in a place means to live there.","zh":"dwell in a place 指居住在某地方。"},{"en":"Some families dwell in remote villages far from hospitals and schools.","zh":"有些家庭居住於遠離醫院和學校的偏遠村莊。"},{"en":"Where people dwell affects their access to food, safety and community life.","zh":"人們居住在哪裡會影響他們獲得食物、安全和社區生活的方式。"},{"en":"This phrase is more formal or literary than “live in”.","zh":"這個短語比 live in 較正式或文學化。"}],"source":"90 - Sampling Bias.pdf","sourcePage":3},{"front":"only because","meaning":"只是因為","examples":[{"en":"They are called cavemen only because most evidence is found in caves.","zh":"他們被稱為穴居人，只是因為大部分證據在洞穴中被發現。"},{"en":"Only because means for just that reason and not for other reasons.","zh":"only because 指只是出於那個原因，而不是其他原因。"},{"en":"A student may seem quiet only because they are listening carefully.","zh":"學生看起來安靜，可能只是因為正在仔細聆聽。"},{"en":"This phrase helps correct a mistaken explanation by narrowing the real cause.","zh":"這個短語透過收窄真正原因來修正錯誤解釋。"},{"en":"It warns readers not to add extra meaning beyond the stated reason.","zh":"它提醒讀者不要在所述原因以外添加額外意思。"}],"source":"90 - Sampling Bias.pdf","sourcePage":3},{"front":"where most evidence is found","meaning":"大部分證據被發現的地方","examples":[{"en":"Caves are where most evidence is found.","zh":"洞穴是大部分證據被發現的地方。"},{"en":"Where most evidence is found means the place that gives researchers the largest amount of surviving proof.","zh":"where most evidence is found 指提供最多存留證據的地方。"},{"en":"If most school complaints are found in online forms, researchers may focus there first.","zh":"如果大部分學校投訴都在網上表格中被發現，研究人員可能先集中那裡。"},{"en":"The place where evidence is found may not be the same as the place where most activity happened.","zh":"證據被發現的地方，未必等於大部分活動發生的地方。"},{"en":"This phrase helps explain how surviving evidence can shape interpretation.","zh":"這個短語幫助解釋保存下來的證據如何塑造詮釋。"}],"source":"90 - Sampling Bias.pdf","sourcePage":3},{"front":"the caveman effect","meaning":"「穴居人效應」","examples":[{"en":"The caveman effect is an example of sampling bias.","zh":"「穴居人效應」是抽樣偏差的一個例子。"},{"en":"The caveman effect is the mistaken impression created when cave evidence survives better than evidence from other places.","zh":"caveman effect 指洞穴證據比其他地方證據更容易保存而造成的錯誤印象。"},{"en":"If only cave art survives, people may overestimate how much prehistoric people lived in caves.","zh":"如果只有洞穴藝術保存下來，人們可能高估史前人類住在洞穴中的程度。"},{"en":"This effect shows how available evidence can distort our picture of the past.","zh":"這種效應顯示可取得證據如何扭曲我們對過去的看法。"},{"en":"The term teaches that evidence survival is not the same as real-life frequency.","zh":"這個詞提醒我們，證據能保存下來不等於現實中最常發生。"}],"source":"90 - Sampling Bias.pdf","sourcePage":3},{"front":"an example of what is known as","meaning":"……的例子","examples":[{"en":"The caveman effect is an example of what is known as sampling bias.","zh":"穴居人效應是所謂抽樣偏差的一個例子。"},{"en":"An example of what is known as introduces a specific case of a named idea or problem.","zh":"an example of what is known as 用來引入某個有名稱概念或問題的具體例子。"},{"en":"A student copying a popular answer online is an example of what is known as groupthink.","zh":"學生抄襲網上熱門答案，是所謂群體思維的一個例子。"},{"en":"This phrase connects a concrete situation with a broader concept.","zh":"這個短語把具體情況與更廣泛概念連繫起來。"},{"en":"It is useful when teaching a technical term through a simple case.","zh":"當透過簡單個案教授技術詞時，這個短語很有用。"}],"source":"90 - Sampling Bias.pdf","sourcePage":3},{"front":"one of the biggest problems","meaning":"最大問題之一","examples":[{"en":"Sampling bias is one of the biggest problems in survey research.","zh":"抽樣偏差是調查研究中的最大問題之一。"},{"en":"One of the biggest problems means one of the most serious difficulties in a situation.","zh":"one of the biggest problems 指某情況中最嚴重的困難之一。"},{"en":"Lack of sleep is one of the biggest problems for students preparing for exams.","zh":"睡眠不足是準備考試學生的最大問題之一。"},{"en":"A big problem can affect many later decisions if it is not noticed early.","zh":"如果大問題沒有及早被注意，它可能影響許多之後的決定。"},{"en":"This phrase highlights importance without saying it is the only problem.","zh":"這個短語突出重要性，但不是說它是唯一問題。"}],"source":"90 - Sampling Bias.pdf","sourcePage":3},{"front":"conduct any form of","meaning":"進行任何形式的……","examples":[{"en":"Researchers may encounter bias when conducting any form of data gathering.","zh":"研究人員在進行任何形式的數據收集時，都可能遇到偏差。"},{"en":"To conduct any form of something means to carry out any type of that activity.","zh":"conduct any form of something 指執行任何類型的某活動。"},{"en":"A school should protect privacy when conducting any form of student survey.","zh":"學校在進行任何形式的學生調查時，都應保護私隱。"},{"en":"Different forms of research can create different kinds of errors.","zh":"不同形式的研究可以產生不同種類的錯誤。"},{"en":"This phrase emphasises that the issue applies widely, not only to one method.","zh":"這個短語強調問題廣泛適用，而不只限於一種方法。"}],"source":"90 - Sampling Bias.pdf","sourcePage":3},{"front":"statistical data gathering","meaning":"統計數據收集","examples":[{"en":"Sampling bias affects statistical data gathering.","zh":"抽樣偏差影響統計數據收集。"},{"en":"Statistical data gathering is the process of collecting numerical information for analysis.","zh":"statistical data gathering 指為分析而收集數字資料的過程。"},{"en":"A hospital uses statistical data gathering when it records waiting times for patients.","zh":"醫院記錄病人等候時間時，就是在進行統計數據收集。"},{"en":"If data are gathered unfairly, later statistics may mislead decision-makers.","zh":"如果數據收集不公平，之後的統計可能誤導決策者。"},{"en":"This phrase refers to collecting data before calculation and interpretation.","zh":"這個短語指計算和詮釋之前的數據收集。"}],"source":"90 - Sampling Bias.pdf","sourcePage":4},{"front":"surveys","meaning":"調查","examples":[{"en":"Surveys are popular because they are easy to administer.","zh":"調查很受歡迎，因為它們容易進行。"},{"en":"Surveys are sets of questions used to collect opinions, facts or experiences from people.","zh":"surveys 指用來收集人們意見、事實或經驗的一組問題。"},{"en":"A restaurant may use surveys to ask customers about food quality and service.","zh":"餐廳可能使用調查詢問顧客食物質素和服務。"},{"en":"Surveys can reveal broad patterns, but only if the sample is fair.","zh":"調查可以揭示廣泛模式，但前提是樣本公平。"},{"en":"This word refers to a research tool, not just casual questioning.","zh":"這個詞指研究工具，而不只是隨便提問。"}],"source":"90 - Sampling Bias.pdf","sourcePage":4},{"front":"easy to administer","meaning":"容易執行；容易進行","examples":[{"en":"Surveys are easy to administer and relatively cost-effective.","zh":"調查容易執行，而且相對具成本效益。"},{"en":"Easy to administer means simple to organise, give out and collect.","zh":"easy to administer 指容易組織、派發和收集。"},{"en":"An online quiz is easy to administer because students can complete it on their phones.","zh":"網上小測容易進行，因為學生可以用手機完成。"},{"en":"If a test is easy to administer, teachers can use it with many students quickly.","zh":"如果測驗容易執行，老師可以很快對許多學生使用它。"},{"en":"This phrase focuses on practical convenience.","zh":"這個短語著重實際便利性。"}],"source":"90 - Sampling Bias.pdf","sourcePage":4},{"front":"relatively cost-effective","meaning":"相對具成本效益","examples":[{"en":"Surveys can be relatively cost-effective.","zh":"調查可以相對具成本效益。"},{"en":"Relatively cost-effective means giving useful results for a fairly low cost compared with other methods.","zh":"relatively cost-effective 指與其他方法相比，以較低成本帶來有用結果。"},{"en":"Email surveys are relatively cost-effective because they do not require printed forms or travel.","zh":"電郵調查相對具成本效益，因為不需要印刷表格或出行。"},{"en":"A method may be cheap but still poor if it produces biased results.","zh":"一種方法可能便宜，但如果產生偏差結果，仍然很差。"},{"en":"This phrase compares value and cost rather than cost alone.","zh":"這個短語比較價值和成本，而不只是成本。"}],"source":"90 - Sampling Bias.pdf","sourcePage":4},{"front":"conducted remotely","meaning":"遙距進行","examples":[{"en":"Surveys are often conducted remotely through technical means.","zh":"調查常透過科技方式遙距進行。"},{"en":"Conducted remotely means carried out without meeting people face to face.","zh":"conducted remotely 指不用面對面見面而進行。"},{"en":"A doctor’s follow-up appointment may be conducted remotely by video call.","zh":"醫生的覆診可能透過視像通話遙距進行。"},{"en":"Remote surveys can reach many people, but they may miss people without internet or phones.","zh":"遙距調查可以接觸很多人，但也可能漏掉沒有網絡或電話的人。"},{"en":"This phrase focuses on distance between researcher and respondent.","zh":"這個短語著重研究者和受訪者之間的距離。"}],"source":"90 - Sampling Bias.pdf","sourcePage":4},{"front":"through technical means","meaning":"透過科技方式","examples":[{"en":"Surveys may be conducted through technical means such as telephone or email.","zh":"調查可以透過電話或電郵等科技方式進行。"},{"en":"Through technical means means using technology to carry out an action.","zh":"through technical means 指使用科技來完成某行動。"},{"en":"Schools can contact parents through technical means such as apps, emails and text messages.","zh":"學校可以透過應用程式、電郵和短訊等科技方式聯絡家長。"},{"en":"Technology can make communication faster, but it may exclude people who lack access.","zh":"科技可以令溝通更快，但也可能排除缺乏使用渠道的人。"},{"en":"This phrase highlights the tool used to reach people.","zh":"這個短語突出用來接觸人們的工具。"}],"source":"90 - Sampling Bias.pdf","sourcePage":4},{"front":"lend themselves to","meaning":"適合用來……","examples":[{"en":"Surveys lend themselves to obtaining large numbers of respondents.","zh":"調查適合用來取得大量受訪者。"},{"en":"To lend themselves to something means to be naturally suitable for that purpose.","zh":"lend themselves to something 指自然適合某用途。"},{"en":"Short online forms lend themselves to quick feedback after a lesson.","zh":"簡短網上表格適合用來在課後快速收集回饋。"},{"en":"A method that lends itself to large numbers can still fail if the sample is biased.","zh":"適合大量收集的方法，如果樣本有偏差，仍可能失敗。"},{"en":"This phrase describes suitability, not lending money or objects.","zh":"這個短語描述適合性，而不是借出金錢或物件。"}],"source":"90 - Sampling Bias.pdf","sourcePage":4},{"front":"large numbers of respondents","meaning":"大量受訪者","examples":[{"en":"Surveys can obtain large numbers of respondents.","zh":"調查可以取得大量受訪者。"},{"en":"Large numbers of respondents means many people who answer a survey or study questions.","zh":"large numbers of respondents 指很多回答調查或研究問題的人。"},{"en":"A popular online poll may collect large numbers of respondents within one day.","zh":"受歡迎的網上民意調查可能一天內收集到大量受訪者。"},{"en":"More respondents can help, but numbers alone do not guarantee fairness.","zh":"更多受訪者可能有幫助，但數量本身不保證公平。"},{"en":"This phrase focuses on quantity of participants.","zh":"這個短語著重參與者數量。"}],"source":"90 - Sampling Bias.pdf","sourcePage":4},{"front":"in theory","meaning":"理論上","examples":[{"en":"In theory, a larger survey gives a greater chance of sampling the target population.","zh":"理論上，較大型調查有更大機會抽樣到目標群體。"},{"en":"In theory means according to the idea or principle, though reality may be different.","zh":"in theory 指按想法或原則來說，雖然現實可能不同。"},{"en":"In theory, studying every day should improve English, but the method also matters.","zh":"理論上，每天學習應能改善英文，但方法也很重要。"},{"en":"This phrase often introduces an ideal expectation before practical problems appear.","zh":"這個短語常在實際問題出現前引入理想預期。"},{"en":"It warns readers that the real situation may be more complicated.","zh":"它提醒讀者真實情況可能更複雜。"}],"source":"90 - Sampling Bias.pdf","sourcePage":4},{"front":"a greater chance of","meaning":"更大機會","examples":[{"en":"A large survey allows a greater chance of sampling all variations.","zh":"大型調查有更大機會抽取所有差異。"},{"en":"A greater chance of something means a higher possibility that it will happen.","zh":"greater chance of something 指某事發生的可能性較高。"},{"en":"Practising speaking every week gives students a greater chance of becoming fluent.","zh":"每星期練習說話讓學生有更大機會變得流利。"},{"en":"A bigger sample can give a greater chance of including different groups.","zh":"較大樣本可以有更大機會包括不同群體。"},{"en":"This phrase expresses probability, not certainty.","zh":"這個短語表達可能性，而不是確定性。"}],"source":"90 - Sampling Bias.pdf","sourcePage":4},{"front":"sample all the variations of","meaning":"抽取……的所有差異","examples":[{"en":"Researchers hope to sample all the variations of the target population.","zh":"研究人員希望抽取目標群體的所有差異。"},{"en":"To sample all the variations of a group means to include its different types, views or backgrounds.","zh":"sample all the variations of a group 指包括該群體中不同類型、觀點或背景。"},{"en":"A school survey should sample all variations of students, not only those in top classes.","zh":"學校調查應抽取學生的所有差異，而不只是尖子班學生。"},{"en":"If important variations are missed, the final results may hide real differences.","zh":"如果遺漏重要差異，最終結果可能隱藏真實分別。"},{"en":"This phrase stresses diversity inside a sample.","zh":"這個短語強調樣本內部的多樣性。"}],"source":"90 - Sampling Bias.pdf","sourcePage":5},{"front":"target population","meaning":"目標群體","examples":[{"en":"A survey should represent the target population accurately.","zh":"調查應準確代表目標群體。"},{"en":"The target population is the whole group that a study wants to understand.","zh":"target population 指研究想了解的整個群體。"},{"en":"If a survey studies teenagers, adults are not part of the target population.","zh":"如果調查研究青少年，成年人就不是目標群體的一部分。"},{"en":"A sample is useful only if it reflects the target population fairly.","zh":"只有當樣本公平反映目標群體時，它才有用。"},{"en":"This phrase identifies who the research is really about.","zh":"這個短語指出研究真正關於誰。"}],"source":"90 - Sampling Bias.pdf","sourcePage":5},{"front":"be standardised with","meaning":"以……標準化","examples":[{"en":"Surveys can be standardised with fixed questions and responses.","zh":"調查可以以固定問題和答案標準化。"},{"en":"To be standardised with something means to be made consistent using the same format or rules.","zh":"be standardised with something 指用相同格式或規則令某事一致。"},{"en":"A school test can be standardised with the same questions for every class.","zh":"學校測驗可以用每班相同問題來標準化。"},{"en":"Standardisation makes results easier to compare, but it may limit detailed answers.","zh":"標準化令結果較易比較，但可能限制詳細答案。"},{"en":"This phrase focuses on consistency across participants.","zh":"這個短語著重不同參與者之間的一致性。"}],"source":"90 - Sampling Bias.pdf","sourcePage":5},{"front":"fixed questions and responses","meaning":"固定問題和答案","examples":[{"en":"Fixed questions and responses make survey results easier to analyse.","zh":"固定問題和答案令調查結果較容易分析。"},{"en":"Fixed questions and responses are set questions with set answer choices.","zh":"fixed questions and responses 指預設問題和預設答案選項。"},{"en":"A survey asking “yes”, “no” or “not sure” uses fixed responses.","zh":"問「是」、「否」或「不確定」的調查使用固定答案。"},{"en":"Fixed answers help researchers count results quickly, but they may miss unusual opinions.","zh":"固定答案幫助研究人員快速點算結果，但可能錯過不尋常意見。"},{"en":"This phrase describes a controlled survey format.","zh":"這個短語描述受控制的調查格式。"}],"source":"90 - Sampling Bias.pdf","sourcePage":5},{"front":"tick-the-box questions","meaning":"剔格題","examples":[{"en":"Tick-the-box questions are easy to collate and analyse.","zh":"剔格題容易整理和分析。"},{"en":"Tick-the-box questions are questions answered by selecting from given choices.","zh":"tick-the-box questions 指透過從已給選項中選擇來回答的問題。"},{"en":"A school form may use tick-the-box questions for lunch options.","zh":"學校表格可能用剔格題詢問午餐選項。"},{"en":"These questions save time because answers can be counted directly.","zh":"這些問題節省時間，因為答案可以直接點算。"},{"en":"This phrase refers to simple fixed-choice questions.","zh":"這個短語指簡單的固定選項問題。"}],"source":"90 - Sampling Bias.pdf","sourcePage":5},{"front":"closed-ended questions","meaning":"封閉式問題","examples":[{"en":"Closed-ended questions provide fixed answer choices.","zh":"封閉式問題提供固定答案選項。"},{"en":"Closed-ended questions are questions that limit respondents to a set of possible answers.","zh":"closed-ended questions 指把受訪者限制在一組可能答案中的問題。"},{"en":"“Do you own a car: yes or no?” is a closed-ended question.","zh":"「你有車嗎：是或否？」是一條封閉式問題。"},{"en":"Closed-ended questions are easy to compare, but they may not capture complex feelings.","zh":"封閉式問題容易比較，但未必能捕捉複雜感受。"},{"en":"This phrase contrasts fixed answers with open-ended explanations.","zh":"這個短語把固定答案與開放式解釋作對比。"}],"source":"90 - Sampling Bias.pdf","sourcePage":5},{"front":"easy collation","meaning":"容易整理","examples":[{"en":"Fixed responses allow easy collation of survey results.","zh":"固定答案讓調查結果容易整理。"},{"en":"Easy collation means results can be collected, grouped and counted without much difficulty.","zh":"easy collation 指結果可以不太困難地被收集、分組和點算。"},{"en":"Multiple-choice answers allow easy collation because each option can be counted.","zh":"多項選擇答案容易整理，因為每個選項都可以被點算。"},{"en":"Easy collation saves time, especially when many people respond.","zh":"容易整理可以節省時間，尤其當很多人回覆時。"},{"en":"This phrase focuses on organising data after collection.","zh":"這個短語著重收集後組織數據。"}],"source":"90 - Sampling Bias.pdf","sourcePage":5},{"front":"analysis and presentation of results","meaning":"結果分析和展示","examples":[{"en":"Standardised surveys allow easy analysis and presentation of results.","zh":"標準化調查讓結果分析和展示更容易。"},{"en":"Analysis and presentation of results means studying the data and showing the findings clearly.","zh":"analysis and presentation of results 指研究數據並清楚展示發現。"},{"en":"A teacher may use charts for the analysis and presentation of exam results.","zh":"老師可能用圖表進行考試結果分析和展示。"},{"en":"Good presentation helps people understand what the analysis has found.","zh":"良好展示幫助人們理解分析發現了甚麼。"},{"en":"This phrase covers both thinking about results and communicating them.","zh":"這個短語涵蓋思考結果和傳達結果兩部分。"}],"source":"90 - Sampling Bias.pdf","sourcePage":5},{"front":"the air of precision","meaning":"精確的感覺","examples":[{"en":"Mathematics gives survey results the air of precision.","zh":"數學賦予調查結果一種精確的感覺。"},{"en":"The air of precision means the appearance or feeling that something is exact.","zh":"air of precision 指某事看起來或感覺上很精確。"},{"en":"A chart with percentages may have the air of precision even if the sample is biased.","zh":"帶有百分比的圖表即使樣本有偏差，也可能有精確的感覺。"},{"en":"Numbers can make weak evidence look stronger than it really is.","zh":"數字可以令薄弱證據看起來比實際更強。"},{"en":"This phrase warns that something may seem exact without being reliable.","zh":"這個短語提醒我們，某事可能看似精確但並不可靠。"}],"source":"90 - Sampling Bias.pdf","sourcePage":5},{"front":"have proven notoriously unreliable","meaning":"已證明極不可靠","examples":[{"en":"Such surveys have proven notoriously unreliable.","zh":"這類調查已證明極不可靠。"},{"en":"To have proven notoriously unreliable means to have shown over time that they often cannot be trusted.","zh":"have proven notoriously unreliable 指隨時間顯示它們經常不可信。"},{"en":"Online reviews can prove unreliable if only angry customers choose to write them.","zh":"如果只有憤怒顧客選擇寫評論，網上評論可能證明不可靠。"},{"en":"A method becomes notoriously unreliable when many people know its results often fail.","zh":"當許多人都知道某方法結果經常失敗，它就變得出名地不可靠。"},{"en":"This phrase gives a strong warning about repeated weakness.","zh":"這個短語強烈警告某事反覆存在弱點。"}],"source":"90 - Sampling Bias.pdf","sourcePage":5},{"front":"difficulty in obtaining","meaning":"難以取得……","examples":[{"en":"The main problem is the difficulty in obtaining representative samples.","zh":"主要問題是難以取得具代表性的樣本。"},{"en":"Difficulty in obtaining something means trouble getting or securing it.","zh":"difficulty in obtaining something 指取得或獲得某事物時遇到困難。"},{"en":"A school may face difficulty in obtaining enough volunteers for a weekend event.","zh":"學校可能難以取得足夠義工參與週末活動。"},{"en":"If researchers cannot obtain fair samples, their conclusions may be weak.","zh":"如果研究人員不能取得公平樣本，結論可能薄弱。"},{"en":"This phrase focuses on a practical barrier to getting what is needed.","zh":"這個短語著重取得所需事物時的實際障礙。"}],"source":"90 - Sampling Bias.pdf","sourcePage":6},{"front":"representative samples","meaning":"具代表性的樣本","examples":[{"en":"Surveys are unreliable when they fail to obtain representative samples.","zh":"當調查未能取得具代表性的樣本時，就不可靠。"},{"en":"Representative samples are samples that fairly reflect the larger group being studied.","zh":"representative samples 指能公平反映被研究較大群體的樣本。"},{"en":"A student survey should include different years, classes and ability levels to be representative.","zh":"學生調查應包括不同年級、班別和能力水平，才具代表性。"},{"en":"Without representative samples, results may describe only one small subgroup.","zh":"沒有具代表性的樣本，結果可能只描述一個小群體。"},{"en":"This phrase is central to fair research.","zh":"這個短語是公平研究的核心。"}],"source":"90 - Sampling Bias.pdf","sourcePage":6},{"front":"in other words","meaning":"換言之","examples":[{"en":"In other words, the sampling is biased.","zh":"換言之，抽樣有偏差。"},{"en":"In other words introduces the same idea again in clearer or simpler language.","zh":"in other words 用更清楚或更簡單的語言重新表達同一想法。"},{"en":"The sample missed working adults; in other words, it did not represent everyone.","zh":"樣本漏掉在職成年人；換言之，它沒有代表所有人。"},{"en":"Writers use this phrase to help readers understand a difficult point.","zh":"作者使用這個短語幫助讀者理解困難重點。"},{"en":"It signals that the next phrase explains the previous idea.","zh":"它表示下一個短語會解釋前一個想法。"}],"source":"90 - Sampling Bias.pdf","sourcePage":6},{"front":"be biased","meaning":"有偏差","examples":[{"en":"The sampling may be biased in favour of certain outcomes.","zh":"抽樣可能偏向某些結果。"},{"en":"To be biased means to unfairly lean towards one group, idea or result.","zh":"be biased 指不公平地偏向某群體、想法或結果。"},{"en":"A class poll is biased if only students who like sports are asked about PE lessons.","zh":"如果班級投票只問喜歡運動的學生對體育課的意見，就是有偏差。"},{"en":"Biased data can lead to unfair decisions because some voices are missing.","zh":"有偏差的數據可能導致不公平決定，因為某些聲音被遺漏。"},{"en":"This phrase warns that something is not neutral or balanced.","zh":"這個短語提醒某事並不中立或平衡。"}],"source":"90 - Sampling Bias.pdf","sourcePage":6},{"front":"skewed in favour of","meaning":"偏向於……","examples":[{"en":"The data may be skewed in favour of certain outcomes.","zh":"數據可能偏向於某些結果。"},{"en":"Skewed in favour of something means distorted so that one result appears stronger than it should.","zh":"skewed in favour of something 指被扭曲到令某結果看起來比應有更強。"},{"en":"A restaurant review page may be skewed in favour of angry customers if happy customers rarely comment.","zh":"如果滿意顧客很少留言，餐廳評論頁可能偏向憤怒顧客。"},{"en":"Skewed data can make one option seem more popular than it really is.","zh":"偏斜數據可以令一個選項看起來比實際更受歡迎。"},{"en":"This phrase describes unfair leaning in the results.","zh":"這個短語描述結果中的不公平傾向。"}],"source":"90 - Sampling Bias.pdf","sourcePage":6},{"front":"certain outcomes","meaning":"某些結果","examples":[{"en":"Sampling bias can favour certain outcomes.","zh":"抽樣偏差可以偏向某些結果。"},{"en":"Certain outcomes are particular results that may appear more likely or stronger.","zh":"certain outcomes 指某些特定、可能顯得更可能或更強的結果。"},{"en":"A survey written in difficult English may favour certain outcomes by excluding weaker readers.","zh":"用艱深英文寫成的調查可能排除閱讀能力較弱者，從而偏向某些結果。"},{"en":"If certain outcomes are overrepresented, the final conclusion becomes misleading.","zh":"如果某些結果被過度代表，最終結論會具誤導性。"},{"en":"This phrase refers to specific results rather than all possible results.","zh":"這個短語指特定結果，而不是所有可能結果。"}],"source":"90 - Sampling Bias.pdf","sourcePage":6},{"front":"let us look at","meaning":"讓我們看看","examples":[{"en":"Let us look at some examples of sampling bias.","zh":"讓我們看看一些抽樣偏差的例子。"},{"en":"Let us look at means let us examine or consider something together.","zh":"let us look at 指讓我們一起檢視或考慮某事。"},{"en":"A teacher may say, “Let us look at this sentence,” before explaining a grammar mistake.","zh":"老師在解釋文法錯誤前，可能說：「讓我們看看這句子。」"},{"en":"This phrase guides readers from a general idea to examples.","zh":"這個短語引導讀者從一般概念走向例子。"},{"en":"It is often used in explanations and classroom-style writing.","zh":"它常用於解釋和課堂式寫作。"}],"source":"90 - Sampling Bias.pdf","sourcePage":6},{"front":"exclude those who","meaning":"排除那些……的人","examples":[{"en":"Calling mobile phones excludes those who favour landlines.","zh":"致電手機會排除那些偏好固網電話的人。"},{"en":"To exclude those who do something means to leave out people with that habit or preference.","zh":"exclude those who do something 指遺漏有某種習慣或偏好的人。"},{"en":"An online survey excludes those who do not use the internet.","zh":"網上調查會排除那些不使用互聯網的人。"},{"en":"Excluding certain people can make a sample less representative.","zh":"排除某些人會令樣本較不具代表性。"},{"en":"This phrase shows how a research method can miss part of the population.","zh":"這個短語顯示研究方法如何漏掉部分人口。"}],"source":"90 - Sampling Bias.pdf","sourcePage":6},{"front":"favour landlines","meaning":"偏好固網電話","examples":[{"en":"Some people still favour landlines over mobile phones.","zh":"有些人仍然比起手機更偏好固網電話。"},{"en":"To favour landlines means to prefer fixed home telephones to mobile phones.","zh":"favour landlines 指比起手機更喜歡固定家居電話。"},{"en":"Elderly people may favour landlines because they are familiar and easy to find at home.","zh":"長者可能偏好固網電話，因為它們熟悉，而且在家容易找到。"},{"en":"If a survey contacts only mobile phones, people who favour landlines may be missed.","zh":"如果調查只聯絡手機，偏好固網電話的人可能被遺漏。"},{"en":"This phrase describes a preference in communication method.","zh":"這個短語描述通訊方式上的偏好。"}],"source":"90 - Sampling Bias.pdf","sourcePage":6},{"front":"sample of respondents","meaning":"受訪者樣本","examples":[{"en":"The sample of respondents may be more technically conversant.","zh":"受訪者樣本可能更熟悉科技。"},{"en":"A sample of respondents is the group of people who answer a survey.","zh":"sample of respondents 指回答調查的一群人。"},{"en":"A student survey’s sample of respondents may include mostly those who like giving opinions.","zh":"學生調查的受訪者樣本可能主要包括喜歡發表意見的人。"},{"en":"If the sample of respondents is unusual, the results may not represent the whole population.","zh":"如果受訪者樣本不尋常，結果可能不能代表整體人口。"},{"en":"This phrase focuses on who actually answered.","zh":"這個短語著重實際回答的是誰。"}],"source":"90 - Sampling Bias.pdf","sourcePage":6},{"front":"technically conversant","meaning":"熟悉科技的","examples":[{"en":"Mobile-phone respondents may be more technically conversant.","zh":"手機受訪者可能更熟悉科技。"},{"en":"Technically conversant means familiar with technology and able to use it comfortably.","zh":"technically conversant 指熟悉科技並能自在使用它。"},{"en":"A person who can install apps, join video calls and fix simple settings is technically conversant.","zh":"能安裝應用程式、參與視像通話和修正常見設定的人，就是熟悉科技。"},{"en":"Surveys using digital tools may attract more technically conversant respondents.","zh":"使用數碼工具的調查可能吸引更多熟悉科技的受訪者。"},{"en":"This phrase describes comfort with technology, not general intelligence.","zh":"這個短語描述對科技的熟悉程度，而不是一般智力。"}],"source":"90 - Sampling Bias.pdf","sourcePage":7},{"front":"skew data based on","meaning":"令基於……的數據偏斜","examples":[{"en":"A biased sample can skew data based on technical issues.","zh":"有偏差的樣本可以令科技相關議題的數據偏斜。"},{"en":"To skew data based on something means to distort results because of that factor.","zh":"skew data based on something 指因某因素而扭曲結果。"},{"en":"A survey in English may skew data based on language ability.","zh":"英文調查可能令基於語言能力的數據偏斜。"},{"en":"If the method favours one group, the data can be skewed before analysis even begins.","zh":"如果方法偏向某群體，數據在分析開始前已可能偏斜。"},{"en":"This phrase connects a source of bias with distorted results.","zh":"這個短語把偏差來源與扭曲結果連繫起來。"}],"source":"90 - Sampling Bias.pdf","sourcePage":7},{"front":"technical issues","meaning":"科技相關議題","examples":[{"en":"A phone survey may distort results about technical issues.","zh":"電話調查可能扭曲關於科技相關議題的結果。"},{"en":"Technical issues are problems or topics connected with technology, machines or digital systems.","zh":"technical issues 指與科技、機器或數碼系統相關的問題或主題。"},{"en":"A school may ask students about technical issues such as slow Wi-Fi or broken tablets.","zh":"學校可能詢問學生 Wi-Fi 緩慢或平板電腦損壞等科技相關議題。"},{"en":"People who use technology more often may answer technical questions differently.","zh":"較常使用科技的人，可能以不同方式回答科技問題。"},{"en":"This phrase refers to technology-related matters.","zh":"這個短語指與科技有關的事項。"}],"source":"90 - Sampling Bias.pdf","sourcePage":7},{"front":"domestic homes","meaning":"住戶家庭","examples":[{"en":"Calling domestic homes during the daytime creates another bias.","zh":"在日間致電住戶家庭會造成另一種偏差。"},{"en":"Domestic homes are private homes where people live, not workplaces or public buildings.","zh":"domestic homes 指人們居住的私人住宅，而不是工作場所或公共建築。"},{"en":"A survey calling domestic homes may reach parents, retirees or people working from home.","zh":"致電住戶家庭的調查可能接觸到家長、退休人士或在家工作的人。"},{"en":"If calls are made only to homes, people without stable housing may be excluded.","zh":"如果只致電家庭，沒有穩定住所的人可能被排除。"},{"en":"This phrase focuses on household addresses or home phones.","zh":"這個短語著重家庭地址或家居電話。"}],"source":"90 - Sampling Bias.pdf","sourcePage":7},{"front":"during the daytime","meaning":"在日間","examples":[{"en":"People who work during the daytime may be excluded.","zh":"在日間工作的人可能被排除。"},{"en":"During the daytime means in the hours when it is light and most people are working or studying.","zh":"during the daytime 指天亮、而大多數人工作或上學的時段。"},{"en":"A delivery may fail during the daytime if no one is at home.","zh":"如果家中無人，日間送貨可能失敗。"},{"en":"Surveys done during the daytime may overrepresent people who stay at home.","zh":"在日間進行的調查可能過度代表留在家中的人。"},{"en":"This phrase identifies a time period that can affect who is reached.","zh":"這個短語指出一個會影響接觸對象的時間段。"}],"source":"90 - Sampling Bias.pdf","sourcePage":7},{"front":"be excluded","meaning":"被排除","examples":[{"en":"Workers may be excluded from a survey conducted during the day.","zh":"工人可能被日間進行的調查排除。"},{"en":"To be excluded means to be left out or not included.","zh":"be excluded 指被遺漏或不被包括在內。"},{"en":"Students without internet may be excluded from an online homework system.","zh":"沒有網絡的學生可能被網上功課系統排除。"},{"en":"When people are excluded from research, their views may disappear from the results.","zh":"當人們被研究排除，他們的觀點可能從結果中消失。"},{"en":"This phrase shows who is missing from a group or process.","zh":"這個短語顯示誰在群體或過程中缺失。"}],"source":"90 - Sampling Bias.pdf","sourcePage":7},{"front":"more likely to be","meaning":"更有可能是","examples":[{"en":"Those who answer daytime calls are more likely to be retired.","zh":"接聽日間電話的人更有可能是退休人士。"},{"en":"More likely to be means having a higher chance of belonging to a certain group or condition.","zh":"more likely to be 指屬於某群體或狀態的機會較高。"},{"en":"People at a library on a weekday morning are more likely to be students, retirees or remote workers.","zh":"平日上午在圖書館的人，更有可能是學生、退休人士或遙距工作者。"},{"en":"If one group is more likely to answer, the sample may become biased.","zh":"如果某群體更有可能回答，樣本可能變得有偏差。"},{"en":"This phrase expresses probability, not certainty.","zh":"這個短語表達可能性，而不是確定性。"}],"source":"90 - Sampling Bias.pdf","sourcePage":7},{"front":"the unemployed","meaning":"失業人士","examples":[{"en":"The unemployed may be overrepresented in daytime surveys.","zh":"失業人士在日間調查中可能被過度代表。"},{"en":"The unemployed are people who do not currently have paid work but may be able or willing to work.","zh":"the unemployed 指目前沒有受薪工作、但可能有能力或願意工作的人。"},{"en":"A job centre provides support for the unemployed through training and job matching.","zh":"就業中心透過培訓和職位配對支援失業人士。"},{"en":"If a survey reaches more unemployed people than their real share, results may be biased.","zh":"如果調查接觸到的失業人士多於其真實比例，結果可能有偏差。"},{"en":"This phrase refers to employment status, not personal worth.","zh":"這個短語指就業狀態，而不是個人價值。"}],"source":"90 - Sampling Bias.pdf","sourcePage":7},{"front":"the disabled","meaning":"殘疾人士","examples":[{"en":"The disabled may be more likely to be at home during the day.","zh":"殘疾人士可能較有機會在日間留在家中。"},{"en":"The disabled are people who have physical, mental or sensory conditions that may limit daily activities.","zh":"the disabled 指有身體、精神或感官狀況，可能限制日常活動的人。"},{"en":"Public buildings need lifts and ramps so disabled people can enter safely.","zh":"公共建築需要升降機和斜道，讓殘疾人士安全進入。"},{"en":"Surveys should avoid treating disabled people as one single identical group.","zh":"調查應避免把殘疾人士視為完全相同的一個群體。"},{"en":"This phrase refers to people with disabilities and should be used respectfully.","zh":"這個短語指有殘疾的人，應尊重地使用。"}],"source":"90 - Sampling Bias.pdf","sourcePage":7},{"front":"the elderly","meaning":"長者","examples":[{"en":"The elderly may be more likely to answer daytime calls.","zh":"長者可能較有機會接聽日間電話。"},{"en":"The elderly are older people, especially those in later life.","zh":"the elderly 指年紀較大的人，尤其是晚年人士。"},{"en":"Public transport should consider the elderly by providing seats, clear signs and lifts.","zh":"公共交通應透過提供座位、清楚標示和升降機來照顧長者。"},{"en":"If the elderly are overrepresented, results may not reflect younger working adults.","zh":"如果長者被過度代表，結果可能不能反映較年輕在職成年人。"},{"en":"This phrase is formal and should be used with care and respect.","zh":"這個短語較正式，應謹慎並尊重地使用。"}],"source":"90 - Sampling Bias.pdf","sourcePage":7},{"front":"the retired","meaning":"退休人士","examples":[{"en":"The retired may be overrepresented in a daytime home survey.","zh":"退休人士在日間家居調查中可能被過度代表。"},{"en":"The retired are people who have stopped working, usually because of age or long service.","zh":"the retired 指已停止工作的人，通常是因年齡或長期服務。"},{"en":"Retired people may have more time to answer surveys than full-time workers.","zh":"退休人士可能比全職工作者有更多時間回答調查。"},{"en":"If the retired answer more often, work-related opinions may be distorted.","zh":"如果退休人士較常回答，與工作有關的意見可能被扭曲。"},{"en":"This phrase refers to people no longer in regular paid employment.","zh":"這個短語指不再從事固定受薪工作的人。"}],"source":"90 - Sampling Bias.pdf","sourcePage":8},{"front":"work-related issues","meaning":"與工作有關的議題","examples":[{"en":"A daytime home survey may skew data about work-related issues.","zh":"日間家居調查可能令與工作有關的議題的數據偏斜。"},{"en":"Work-related issues are topics connected with jobs, workplaces, wages or working conditions.","zh":"work-related issues 指與職位、工作場所、工資或工作條件相關的議題。"},{"en":"A company survey may ask about work-related issues such as overtime and safety.","zh":"公司調查可能詢問加班和安全等與工作有關的議題。"},{"en":"If many workers are missed, opinions about work-related issues may be inaccurate.","zh":"如果很多工人被遺漏，關於工作議題的意見可能不準確。"},{"en":"This phrase focuses on matters connected with employment.","zh":"這個短語著重與就業相關的事項。"}],"source":"90 - Sampling Bias.pdf","sourcePage":8},{"front":"no matter how large","meaning":"無論……有多大","examples":[{"en":"No matter how large the sample size is, bias can invalidate the results.","zh":"無論樣本大小有多大，偏差都可以使結果無效。"},{"en":"No matter how large means regardless of how big something is.","zh":"no matter how large 指不管某物有多大。"},{"en":"No matter how large a class is, a teacher still needs to hear quiet students.","zh":"無論班級有多大，老師仍需要聽到安靜學生的聲音。"},{"en":"Size does not solve every problem if the method is unfair.","zh":"如果方法不公平，規模大小不能解決所有問題。"},{"en":"This phrase stresses that one condition remains true even at a large scale.","zh":"這個短語強調即使規模很大，某情況仍然成立。"}],"source":"90 - Sampling Bias.pdf","sourcePage":8},{"front":"sample size","meaning":"樣本大小","examples":[{"en":"A large sample size does not automatically remove sampling bias.","zh":"大樣本大小不會自動消除抽樣偏差。"},{"en":"Sample size is the number of people or items included in a study.","zh":"sample size 指研究中包含的人或物的數量。"},{"en":"A survey with 2,000 students has a larger sample size than one with 50 students.","zh":"有二千名學生的調查，比只有五十名學生的調查樣本大小更大。"},{"en":"A bigger sample size can improve accuracy only if the sample is fairly chosen.","zh":"較大樣本大小只有在樣本被公平選出時，才可以提高準確性。"},{"en":"This phrase measures quantity, not representativeness.","zh":"這個短語量度數量，而不是代表性。"}],"source":"90 - Sampling Bias.pdf","sourcePage":8},{"front":"invalidate the results","meaning":"使結果無效","examples":[{"en":"Sampling bias can invalidate the results of a survey.","zh":"抽樣偏差可以使調查結果無效。"},{"en":"To invalidate the results means to make them unreliable, unusable or no longer valid.","zh":"invalidate the results 指令結果不可靠、不能使用或不再有效。"},{"en":"If students copy answers in a test, cheating can invalidate the results.","zh":"如果學生在測驗中抄襲，作弊可以使結果無效。"},{"en":"A serious error in data collection can destroy the value of later analysis.","zh":"數據收集中的嚴重錯誤可以破壞之後分析的價值。"},{"en":"This phrase shows that a problem is serious enough to ruin the conclusion.","zh":"這個短語顯示問題嚴重到足以破壞結論。"}],"source":"90 - Sampling Bias.pdf","sourcePage":8},{"front":"subtler forms of","meaning":"較隱蔽的形式","examples":[{"en":"Self-selection is one of the subtler forms of sampling bias.","zh":"自我選擇是抽樣偏差較隱蔽的形式之一。"},{"en":"Subtler forms of something are less obvious versions of it.","zh":"subtler forms of something 指某事物較不明顯的版本。"},{"en":"A student may notice obvious bullying but miss subtler forms of exclusion.","zh":"學生可能注意到明顯欺凌，但錯過較隱蔽的排斥形式。"},{"en":"Subtle problems are harder to fix because people may not see them immediately.","zh":"隱蔽問題較難修正，因為人們未必立即看見。"},{"en":"This phrase points to hidden or less visible types of a problem.","zh":"這個短語指出問題中較隱藏或較不可見的類型。"}],"source":"90 - Sampling Bias.pdf","sourcePage":8},{"front":"be known as","meaning":"被稱為","examples":[{"en":"This form of bias is known as self-selection.","zh":"這種偏差形式被稱為自我選擇。"},{"en":"To be known as something means to be called by that name.","zh":"be known as something 指被稱作某個名稱。"},{"en":"The fear of missing out is often known as FOMO.","zh":"錯失恐懼常被稱為 FOMO。"},{"en":"Giving a problem a name makes it easier to discuss and recognise.","zh":"為問題命名令它更容易被討論和識別。"},{"en":"This phrase introduces a term or label.","zh":"這個短語用來引入術語或標籤。"}],"source":"90 - Sampling Bias.pdf","sourcePage":8},{"front":"self-selection","meaning":"自我選擇","examples":[{"en":"Self-selection occurs when only certain people choose to respond.","zh":"當只有某些人選擇作答時，就會出現自我選擇。"},{"en":"Self-selection is bias caused by people deciding for themselves whether to take part.","zh":"self-selection 指由人們自行決定是否參與而造成的偏差。"},{"en":"An online review page may suffer from self-selection because very happy or very angry customers respond.","zh":"網上評論頁可能有自我選擇問題，因為非常滿意或非常憤怒的顧客會回應。"},{"en":"Self-selection can overrepresent people with strong opinions.","zh":"自我選擇可能過度代表有強烈意見的人。"},{"en":"This phrase describes a bias created by voluntary participation.","zh":"這個短語描述由自願參與造成的偏差。"}],"source":"90 - Sampling Bias.pdf","sourcePage":8},{"front":"no matter how rigorously","meaning":"無論多麼嚴謹地","examples":[{"en":"No matter how rigorously respondents are chosen, self-selection can remain.","zh":"無論受訪者被多麼嚴謹地選出，自我選擇仍可能存在。"},{"en":"No matter how rigorously means even if the process is done very carefully and strictly.","zh":"no matter how rigorously 指即使過程非常仔細和嚴格地進行。"},{"en":"No matter how rigorously a teacher checks homework, some misunderstandings may remain.","zh":"無論老師多麼嚴謹地檢查功課，仍可能有一些誤解存在。"},{"en":"Careful selection cannot remove bias if selected people still choose not to answer.","zh":"如果被選中的人仍選擇不回答，仔細選樣也不能消除偏差。"},{"en":"This phrase shows that strict methods may still have limits.","zh":"這個短語顯示嚴格方法仍可能有限制。"}],"source":"90 - Sampling Bias.pdf","sourcePage":8},{"front":"be chosen to be random","meaning":"被選為隨機的","examples":[{"en":"Respondents may be chosen to be random and representative.","zh":"受訪者可能被選為隨機且具代表性的。"},{"en":"To be chosen to be random means to be selected by chance rather than by preference.","zh":"be chosen to be random 指透過機會而非偏好被選出。"},{"en":"A teacher may choose random student numbers to answer questions fairly.","zh":"老師可能隨機選學生號碼回答問題，以保持公平。"},{"en":"Random choice helps reduce human preference, but it does not guarantee everyone will respond.","zh":"隨機選擇幫助減少人為偏好，但不保證每個人都會回應。"},{"en":"This phrase describes a method meant to make selection fair.","zh":"這個短語描述旨在令選取公平的方法。"}],"source":"90 - Sampling Bias.pdf","sourcePage":8},{"front":"characteristic of","meaning":"具有……特徵","examples":[{"en":"The sample should be characteristic of the target population.","zh":"樣本應具有目標群體的特徵。"},{"en":"Characteristic of something means showing the usual features of that thing.","zh":"characteristic of something 指顯示某事物通常具有的特徵。"},{"en":"A class sample is characteristic of the school if it includes different years and abilities.","zh":"如果班級樣本包括不同年級和能力，就具有學校整體的特徵。"},{"en":"A sample that is not characteristic may produce misleading results.","zh":"不具代表特徵的樣本可能產生誤導結果。"},{"en":"This phrase focuses on typical features.","zh":"這個短語著重典型特徵。"}],"source":"90 - Sampling Bias.pdf","sourcePage":9},{"front":"choose to respond","meaning":"選擇作答","examples":[{"en":"People who choose to respond may differ from those who do not.","zh":"選擇作答的人可能與沒有作答的人不同。"},{"en":"To choose to respond means to decide voluntarily to answer.","zh":"choose to respond 指自願決定回答。"},{"en":"Students who choose to respond to a school survey may have stronger opinions than silent students.","zh":"選擇回答學校調查的學生，可能比沉默學生有更強意見。"},{"en":"Voluntary response can create bias because non-respondents may think differently.","zh":"自願回答可能造成偏差，因為不回答者可能想法不同。"},{"en":"This phrase focuses on the decision to answer.","zh":"這個短語著重回答這個決定。"}],"source":"90 - Sampling Bias.pdf","sourcePage":9},{"front":"be different from","meaning":"與……不同","examples":[{"en":"Respondents are often different from people who refuse to answer.","zh":"受訪者往往與拒絕回答的人不同。"},{"en":"To be different from someone or something means not to be the same as them.","zh":"be different from someone or something 指與某人或某物不相同。"},{"en":"Students who join a debate club may be different from students who avoid public speaking.","zh":"參加辯論學會的學生，可能與避免公開演說的學生不同。"},{"en":"If respondents are different from non-respondents, survey results may be biased.","zh":"如果受訪者與不回應者不同，調查結果可能有偏差。"},{"en":"This phrase signals a contrast between two groups.","zh":"這個短語表示兩組之間的對比。"}],"source":"90 - Sampling Bias.pdf","sourcePage":9},{"front":"be willing to","meaning":"願意","examples":[{"en":"Respondents are willing to invest time in giving answers.","zh":"受訪者願意投放時間作答。"},{"en":"To be willing to do something means to be ready or happy to do it.","zh":"be willing to do something 指準備好或樂意做某事。"},{"en":"A student may be willing to help a classmate if the task is clear and short.","zh":"如果任務清楚而簡短，學生可能願意幫助同學。"},{"en":"People who are willing to answer surveys may have more interest in the topic.","zh":"願意回答調查的人，可能對主題更有興趣。"},{"en":"This phrase shows readiness, not force.","zh":"這個短語表示自願，而不是被迫。"}],"source":"90 - Sampling Bias.pdf","sourcePage":9},{"front":"invest time in","meaning":"投放時間於……","examples":[{"en":"Some respondents invest time in giving survey answers.","zh":"有些受訪者投放時間於提供調查答案。"},{"en":"To invest time in something means to spend time on it because it seems worthwhile.","zh":"invest time in something 指因覺得某事值得而花時間在上面。"},{"en":"A student may invest time in vocabulary practice to improve reading speed.","zh":"學生可能投放時間於詞彙練習，以提高閱讀速度。"},{"en":"People invest time in surveys when they believe their views matter.","zh":"當人們相信自己的看法重要時，會投放時間於調查。"},{"en":"This phrase treats time as a valuable resource.","zh":"這個短語把時間視為寶貴資源。"}],"source":"90 - Sampling Bias.pdf","sourcePage":9},{"front":"give answers","meaning":"作答","examples":[{"en":"Respondents may give answers because they want to express an opinion.","zh":"受訪者可能因為想表達意見而作答。"},{"en":"To give answers means to provide responses to questions.","zh":"give answers 指對問題提供回應。"},{"en":"Students give answers in class when the teacher asks about a reading passage.","zh":"老師詢問閱讀文章時，學生會在課堂上作答。"},{"en":"The quality of a survey depends partly on whether people give thoughtful answers.","zh":"調查質素部分取決於人們是否給出經思考的答案。"},{"en":"This phrase focuses on the act of responding.","zh":"這個短語著重回應這個行動。"}],"source":"90 - Sampling Bias.pdf","sourcePage":9},{"front":"want to say something","meaning":"有話想說","examples":[{"en":"People who respond often want to say something.","zh":"回應的人往往有話想說。"},{"en":"Want to say something means have an opinion, complaint or message to express.","zh":"want to say something 指有意見、投訴或訊息想表達。"},{"en":"A student may raise a hand because they want to say something about the school rules.","zh":"學生可能舉手，因為他有話想說關於校規。"},{"en":"Surveys can overrepresent people who feel strongly and want to speak.","zh":"調查可能過度代表感受強烈、有話想說的人。"},{"en":"This phrase shows motivation behind responding.","zh":"這個短語顯示回答背後的動機。"}],"source":"90 - Sampling Bias.pdf","sourcePage":9},{"front":"choose not to answer","meaning":"選擇不回答","examples":[{"en":"Those who choose not to answer may have different views.","zh":"選擇不回答的人可能有不同看法。"},{"en":"To choose not to answer means to decide to remain silent or refuse a response.","zh":"choose not to answer 指決定保持沉默或拒絕回應。"},{"en":"Some parents may choose not to answer a school survey if they are too busy.","zh":"如果太忙，有些家長可能選擇不回答學校調查。"},{"en":"If many people choose not to answer, their opinions disappear from the data.","zh":"如果很多人選擇不回答，他們的意見就會從數據中消失。"},{"en":"This phrase explains a major source of missing information.","zh":"這個短語解釋缺失資訊的一個主要來源。"}],"source":"90 - Sampling Bias.pdf","sourcePage":9},{"front":"give clear answers","meaning":"給出清晰答案","examples":[{"en":"Some respondents do not give clear answers.","zh":"有些受訪者不會給出清晰答案。"},{"en":"To give clear answers means to respond in a way that is specific and easy to understand.","zh":"give clear answers 指以具體且易明的方式回應。"},{"en":"A student gives a clear answer when they explain both the choice and the reason.","zh":"學生解釋選擇和原因時，就是給出清晰答案。"},{"en":"Unclear answers are harder to count, compare and interpret.","zh":"不清晰答案較難點算、比較和詮釋。"},{"en":"This phrase focuses on answer quality.","zh":"這個短語著重答案質素。"}],"source":"90 - Sampling Bias.pdf","sourcePage":9},{"front":"cursory answers","meaning":"草率的答案","examples":[{"en":"Cursory answers can make a survey less reliable.","zh":"草率的答案可以令調查較不可靠。"},{"en":"Cursory answers are quick, careless responses given without enough attention.","zh":"cursory answers 指快速、粗心、沒有足夠注意的回應。"},{"en":"A student gives a cursory answer when they write one vague sentence without reading the question.","zh":"學生沒有看清題目，只寫一句含糊句子，就是給出草率答案。"},{"en":"Too many cursory answers can weaken the quality of the data.","zh":"太多草率答案會削弱數據質素。"},{"en":"This phrase suggests a shallow response.","zh":"這個短語表示膚淺回應。"}],"source":"90 - Sampling Bias.pdf","sourcePage":9},{"front":"unthinking answers","meaning":"未經思考的答案","examples":[{"en":"Unthinking answers can invalidate survey results.","zh":"未經思考的答案可以使調查結果無效。"},{"en":"Unthinking answers are responses given without careful thought.","zh":"unthinking answers 指沒有仔細思考就給出的回應。"},{"en":"A respondent may give unthinking answers by ticking the same option for every question.","zh":"受訪者每題都剔同一選項，可能就是給出未經思考的答案。"},{"en":"If many answers are unthinking, the results may not reflect real opinions.","zh":"如果很多答案未經思考，結果可能不能反映真實意見。"},{"en":"This phrase warns that participation alone is not enough.","zh":"這個短語提醒我們，單是有人參與並不足夠。"}],"source":"90 - Sampling Bias.pdf","sourcePage":10},{"front":"opinionated perspectives","meaning":"主觀強烈的觀點","examples":[{"en":"Opinionated perspectives may be disproportionately represented.","zh":"主觀強烈的觀點可能被不成比例地代表。"},{"en":"Opinionated perspectives are strong personal views held with confidence or stubbornness.","zh":"opinionated perspectives 指帶有自信或固執的強烈個人看法。"},{"en":"Online comment sections often contain opinionated perspectives because calm readers may not post.","zh":"網上留言區常有主觀強烈的觀點，因為冷靜讀者未必留言。"},{"en":"Strong views can dominate a survey if only highly motivated people respond.","zh":"如果只有高度有動機的人回應，強烈觀點可以主導調查。"},{"en":"This phrase describes views that are forceful rather than neutral.","zh":"這個短語描述有力而非中立的看法。"}],"source":"90 - Sampling Bias.pdf","sourcePage":10},{"front":"be disproportionately represented","meaning":"被不成比例地代表","examples":[{"en":"Strong opinions may be disproportionately represented in survey results.","zh":"強烈意見可能在調查結果中被不成比例地代表。"},{"en":"To be disproportionately represented means to appear more often than is fair or accurate.","zh":"be disproportionately represented 指出現比例高於公平或準確水平。"},{"en":"If only angry customers write reviews, complaints are disproportionately represented.","zh":"如果只有憤怒顧客寫評論，投訴就會被不成比例地代表。"},{"en":"Disproportionate representation can make a minority view look like the majority view.","zh":"不成比例的代表可以令少數意見看似多數意見。"},{"en":"This phrase shows imbalance in who or what appears in the data.","zh":"這個短語顯示數據中誰或甚麼出現得不平衡。"}],"source":"90 - Sampling Bias.pdf","sourcePage":10},{"front":"such an immediate and obvious problem","meaning":"如此即時而明顯的問題","examples":[{"en":"Self-selection is such an immediate and obvious problem that special techniques are needed.","zh":"自我選擇是如此即時而明顯的問題，以致需要特別技術。"},{"en":"Such an immediate and obvious problem means a problem that appears clearly and quickly.","zh":"such an immediate and obvious problem 指很快且清楚出現的問題。"},{"en":"If half the class cannot log in, it is such an immediate and obvious problem that the lesson must stop.","zh":"如果半班學生不能登入，這就是如此即時而明顯的問題，以致課堂必須暫停。"},{"en":"Obvious problems need action because ignoring them can damage the whole process.","zh":"明顯問題需要行動，因為忽視它可能破壞整個過程。"},{"en":"This phrase stresses urgency and visibility.","zh":"這個短語強調迫切性和可見性。"}],"source":"90 - Sampling Bias.pdf","sourcePage":10},{"front":"give rise to","meaning":"引起；促成","examples":[{"en":"This problem has given rise to techniques for increasing responses.","zh":"這個問題促成了增加回覆的技術。"},{"en":"To give rise to something means to cause it to appear or develop.","zh":"give rise to something 指導致某事出現或發展。"},{"en":"Heavy traffic can give rise to complaints from residents.","zh":"嚴重交通可以引起居民投訴。"},{"en":"A repeated problem often gives rise to new rules or methods.","zh":"反覆出現的問題常會促成新規則或新方法。"},{"en":"This phrase links a cause with a later result.","zh":"這個短語把原因與之後的結果連繫起來。"}],"source":"90 - Sampling Bias.pdf","sourcePage":10},{"front":"maximise the possibility of","meaning":"最大限度提高……的可能性","examples":[{"en":"Researchers try to maximise the possibility of receiving responses.","zh":"研究人員嘗試最大限度提高收到回覆的可能性。"},{"en":"To maximise the possibility of something means to make it as likely as possible.","zh":"maximise the possibility of something 指盡量令某事最有可能發生。"},{"en":"A student can maximise the possibility of passing by practising regularly and sleeping well.","zh":"學生可以透過定期練習和睡眠充足，最大限度提高合格可能性。"},{"en":"Clear instructions and polite contact can increase the chance that people reply.","zh":"清楚指示和禮貌聯絡可以提高人們回覆的機會。"},{"en":"This phrase focuses on improving probability.","zh":"這個短語著重提高可能性。"}],"source":"90 - Sampling Bias.pdf","sourcePage":10},{"front":"garner responses","meaning":"收集回覆","examples":[{"en":"Some techniques help researchers garner responses.","zh":"有些技術幫助研究人員收集回覆。"},{"en":"To garner responses means to collect or obtain replies from people.","zh":"garner responses 指從人們那裡收集或取得回覆。"},{"en":"A school may send reminders to garner responses from parents.","zh":"學校可能發送提醒，以收集家長回覆。"},{"en":"More responses can improve a survey only if different groups are still fairly represented.","zh":"更多回覆只有在不同群體仍被公平代表時，才能改善調查。"},{"en":"This phrase is more formal than “get replies”.","zh":"這個短語比 get replies 較正式。"}],"source":"90 - Sampling Bias.pdf","sourcePage":10},{"front":"one of the more effective techniques","meaning":"較有效的方法之一","examples":[{"en":"Advance notice is one of the more effective techniques.","zh":"預先通知是較有效的方法之一。"},{"en":"One of the more effective techniques means one method that works better than many others.","zh":"one of the more effective techniques 指比許多其他方法更有效的其中一種方法。"},{"en":"Giving students examples is one of the more effective techniques for teaching new vocabulary.","zh":"給學生例句是教授新詞彙較有效的方法之一。"},{"en":"Effective techniques help solve a problem with less wasted effort.","zh":"有效方法幫助以較少浪費力氣解決問題。"},{"en":"This phrase praises a method without saying it is the only good one.","zh":"這個短語讚揚某方法，但不是說它是唯一好方法。"}],"source":"90 - Sampling Bias.pdf","sourcePage":10},{"front":"advance notice","meaning":"預先通知","examples":[{"en":"Researchers may give respondents advance notice of a survey.","zh":"研究人員可能預先通知受訪者有一項調查。"},{"en":"Advance notice is information given before an event happens.","zh":"advance notice 指在事件發生前給出的資訊。"},{"en":"A school gives advance notice when it tells parents about a trip two weeks early.","zh":"學校提前兩星期告知家長旅行安排，就是給出預先通知。"},{"en":"Advance notice can increase responses because people know when and why they will be contacted.","zh":"預先通知可以增加回覆，因為人們知道何時以及為何會被聯絡。"},{"en":"This phrase focuses on preparation before the main action.","zh":"這個短語著重主要行動前的準備。"}],"source":"90 - Sampling Bias.pdf","sourcePage":10},{"front":"highlight the time, nature and mode of delivery","meaning":"突出調查的時間、性質和進行方式","examples":[{"en":"The notice highlights the time, nature and mode of delivery of the survey.","zh":"通知會突出調查的時間、性質和進行方式。"},{"en":"To highlight the time, nature and mode of delivery means to clearly state when it happens, what it is and how it will be carried out.","zh":"highlight the time, nature and mode of delivery 指清楚說明何時進行、是甚麼，以及如何進行。"},{"en":"A school notice may highlight the time, purpose and online platform of a parent meeting.","zh":"學校通告可能突出家長會的時間、目的和網上平台。"},{"en":"Clear details reduce confusion and make people more willing to participate.","zh":"清楚細節減少混亂，並令人更願意參與。"},{"en":"This phrase describes giving key practical information in advance.","zh":"這個短語描述預先提供關鍵實際資訊。"}],"source":"90 - Sampling Bias.pdf","sourcePage":10},{"front":"mode of delivery","meaning":"進行方式","examples":[{"en":"The mode of delivery may be telephone, mail or email.","zh":"進行方式可能是電話、郵寄或電郵。"},{"en":"Mode of delivery means the method used to send, provide or carry out something.","zh":"mode of delivery 指傳送、提供或進行某事的方法。"},{"en":"A lesson’s mode of delivery may be face-to-face, online or recorded video.","zh":"課堂的進行方式可能是面授、網上或錄影。"},{"en":"The mode of delivery can affect who can access the service.","zh":"進行方式可以影響誰能使用該服務。"},{"en":"This phrase focuses on how something reaches people.","zh":"這個短語著重某事如何接觸人們。"}],"source":"90 - Sampling Bias.pdf","sourcePage":11},{"front":"express appreciation for","meaning":"對……表示感謝","examples":[{"en":"The notice expresses appreciation for respondents’ assistance.","zh":"通知對受訪者的協助表示感謝。"},{"en":"To express appreciation for something means to show thanks for it.","zh":"express appreciation for something 指對某事表示謝意。"},{"en":"A teacher may express appreciation for students’ effort after a difficult project.","zh":"困難項目後，老師可能對學生的努力表示感謝。"},{"en":"Showing appreciation can make people feel respected and more willing to help.","zh":"表示感謝可以令人感到被尊重，並更願意幫忙。"},{"en":"This phrase is polite and often used in formal communication.","zh":"這個短語有禮貌，常用於正式溝通。"}],"source":"90 - Sampling Bias.pdf","sourcePage":11},{"front":"assistance","meaning":"協助","examples":[{"en":"Researchers thank respondents for their assistance.","zh":"研究人員感謝受訪者的協助。"},{"en":"Assistance means help or support given to someone.","zh":"assistance 指給予某人的幫助或支援。"},{"en":"A tourist may ask for assistance when they cannot find the correct train platform.","zh":"遊客找不到正確月台時，可能尋求協助。"},{"en":"Assistance from respondents helps researchers collect better data.","zh":"受訪者的協助幫助研究人員收集更好數據。"},{"en":"This word is more formal than “help”.","zh":"這個詞比 help 較正式。"}],"source":"90 - Sampling Bias.pdf","sourcePage":11},{"front":"interviewers themselves","meaning":"訪問員本身","examples":[{"en":"The interviewers themselves must be sufficiently trained.","zh":"訪問員本身必須受過足夠訓練。"},{"en":"Interviewers themselves means the people conducting the interviews, not just the survey system or questions.","zh":"interviewers themselves 指進行訪問的人，而不只是調查系統或問題。"},{"en":"A survey may fail if the interviewers themselves sound rude or unclear.","zh":"如果訪問員本身聽起來無禮或不清楚，調查可能失敗。"},{"en":"Good training matters because interviewers directly affect whether people trust the process.","zh":"良好訓練很重要，因為訪問員會直接影響人們是否信任過程。"},{"en":"This phrase shifts attention to the human workers doing the interviews.","zh":"這個短語把注意力轉向實際進行訪問的人員。"}],"source":"90 - Sampling Bias.pdf","sourcePage":11},{"front":"sufficiently trained in","meaning":"在……方面受過足夠訓練","examples":[{"en":"Interviewers must be sufficiently trained in question-asking techniques.","zh":"訪問員必須在提問技巧方面受過足夠訓練。"},{"en":"Sufficiently trained in something means having enough training to do it properly.","zh":"sufficiently trained in something 指在某方面有足夠訓練，能正確完成。"},{"en":"Nurses must be sufficiently trained in using new medical equipment.","zh":"護士必須在使用新醫療設備方面受過足夠訓練。"},{"en":"Without enough training, workers may make mistakes that affect the whole project.","zh":"沒有足夠訓練，工人可能犯錯，影響整個項目。"},{"en":"This phrase focuses on adequate preparation.","zh":"這個短語著重充分準備。"}],"source":"90 - Sampling Bias.pdf","sourcePage":11},{"front":"question-asking techniques","meaning":"提問技巧","examples":[{"en":"Interviewers need correct question-asking techniques.","zh":"訪問員需要正確提問技巧。"},{"en":"Question-asking techniques are methods for asking questions clearly, fairly and without leading people.","zh":"question-asking techniques 指清楚、公平且不引導他人地提問的方法。"},{"en":"A teacher uses good question-asking techniques when asking students to explain, not just guess.","zh":"老師要求學生解釋而不只是猜答案時，就是使用良好提問技巧。"},{"en":"Poor questioning can push respondents towards certain answers.","zh":"差劣提問可以把受訪者推向某些答案。"},{"en":"This phrase focuses on how questions are asked, not only what they ask.","zh":"這個短語著重問題如何被提出，而不只是問甚麼。"}],"source":"90 - Sampling Bias.pdf","sourcePage":11},{"front":"cranks, salespeople and scam artists","meaning":"古怪人士、銷售員和騙徒","examples":[{"en":"Cranks, salespeople and scam artists make people suspicious of callers.","zh":"古怪人士、銷售員和騙徒令人們對來電者起疑。"},{"en":"Cranks, salespeople and scam artists are strange callers, commercial callers and dishonest callers who may bother or deceive people.","zh":"cranks, salespeople and scam artists 指可能滋擾或欺騙人的古怪來電者、商業來電者和不誠實來電者。"},{"en":"Many people ignore unknown calls because they fear salespeople or scam artists.","zh":"許多人忽略陌生來電，因為害怕銷售員或騙徒。"},{"en":"Suspicion of callers can reduce survey response rates.","zh":"對來電者的懷疑可以降低調查回覆率。"},{"en":"This phrase explains why interviewers must build trust quickly.","zh":"這個短語解釋為何訪問員必須迅速建立信任。"}],"source":"90 - Sampling Bias.pdf","sourcePage":11},{"front":"be abounding","meaning":"大量存在","examples":[{"en":"Scam artists are abounding, so interviewers must gain trust.","zh":"騙徒大量存在，因此訪問員必須取得信任。"},{"en":"To be abounding means to exist in large numbers.","zh":"be abounding 指大量存在。"},{"en":"During exam season, advice videos are abounding online.","zh":"考試季節期間，網上有大量備試建議影片。"},{"en":"When scams are abounding, people become more careful about phone calls.","zh":"當詐騙大量存在，人們會對電話更謹慎。"},{"en":"This phrase is formal and means “there are many”.","zh":"這個短語較正式，意思是「有很多」。"}],"source":"90 - Sampling Bias.pdf","sourcePage":11},{"front":"introduce themselves","meaning":"介紹自己","examples":[{"en":"Interviewers must introduce themselves clearly.","zh":"訪問員必須清楚介紹自己。"},{"en":"To introduce themselves means to say who they are and why they are contacting someone.","zh":"introduce themselves 指說明自己是誰，以及為何聯絡對方。"},{"en":"A new teacher introduces herself before starting the first lesson.","zh":"新老師在第一堂課開始前會介紹自己。"},{"en":"Clear introductions reduce suspicion and help people feel safe.","zh":"清楚介紹可以減少懷疑，並令人感到安全。"},{"en":"This phrase focuses on the first step of respectful communication.","zh":"這個短語著重尊重溝通的第一步。"}],"source":"90 - Sampling Bias.pdf","sourcePage":11},{"front":"the nature of the interview","meaning":"訪問的性質","examples":[{"en":"Interviewers should explain the nature of the interview.","zh":"訪問員應解釋訪問的性質。"},{"en":"The nature of the interview means what the interview is about and what kind of process it will be.","zh":"nature of the interview 指訪問關於甚麼，以及它會是怎樣的過程。"},{"en":"Before a job interview, the company may explain whether it is formal, practical or conversational.","zh":"在求職面試前，公司可能解釋面試是正式、實務還是對話式。"},{"en":"Explaining the nature of an interview helps people know what to expect.","zh":"解釋訪問性質幫助人們知道會發生甚麼。"},{"en":"This phrase refers to the purpose and character of the interview.","zh":"這個短語指訪問的目的和性質。"}],"source":"90 - Sampling Bias.pdf","sourcePage":11},{"front":"with evident sincerity","meaning":"帶着明顯的誠意","examples":[{"en":"Interviewers should speak fully and with evident sincerity.","zh":"訪問員應完整並帶着明顯的誠意說話。"},{"en":"With evident sincerity means in a way that clearly sounds honest and genuine.","zh":"with evident sincerity 指以清楚聽得出真誠和可信的方式。"},{"en":"A doctor speaking with evident sincerity can help a worried patient feel calmer.","zh":"醫生帶着明顯的誠意說話，可以幫助焦慮病人較平靜。"},{"en":"People are more likely to trust a caller who explains the purpose honestly.","zh":"人們較可能信任誠實解釋目的的來電者。"},{"en":"This phrase focuses on visible or audible honesty.","zh":"這個短語著重可見或可聽出的真誠。"}],"source":"90 - Sampling Bias.pdf","sourcePage":12},{"front":"in order to","meaning":"為了","examples":[{"en":"Interviewers introduce themselves in order to gain trust.","zh":"訪問員介紹自己是為了取得信任。"},{"en":"In order to means for the purpose of doing something.","zh":"in order to 指為了做某事。"},{"en":"Students revise past papers in order to understand exam patterns.","zh":"學生操練歷屆試題是為了理解考試模式。"},{"en":"This phrase clearly links an action with its purpose.","zh":"這個短語清楚把行動與目的連繫起來。"},{"en":"It is more formal than simply saying “to”.","zh":"它比簡單說 to 較正式。"}],"source":"90 - Sampling Bias.pdf","sourcePage":12},{"front":"gain the trust of","meaning":"取得……的信任","examples":[{"en":"Interviewers must gain the trust of the people they contact.","zh":"訪問員必須取得他們聯絡的人的信任。"},{"en":"To gain the trust of someone means to make them believe you are honest and safe to deal with.","zh":"gain the trust of someone 指令人相信你誠實，並且可以安全互動。"},{"en":"A new teacher gains the trust of students by being fair and consistent.","zh":"新老師透過公平和一致來取得學生信任。"},{"en":"Without trust, people may refuse to answer even a useful survey.","zh":"沒有信任，人們即使面對有用調查也可能拒絕回答。"},{"en":"This phrase focuses on building confidence before cooperation.","zh":"這個短語著重在合作前建立信心。"}],"source":"90 - Sampling Bias.pdf","sourcePage":12},{"front":"those they are talking to","meaning":"他們正在交談的人","examples":[{"en":"Interviewers need to gain the trust of those they are talking to.","zh":"訪問員需要取得他們正在交談的人的信任。"},{"en":"Those they are talking to means the people currently being spoken to.","zh":"those they are talking to 指目前正在與他們交談的人。"},{"en":"A teacher should watch whether those they are talking to look confused or comfortable.","zh":"老師應觀察正在交談的人看起來困惑還是自在。"},{"en":"Communication improves when speakers consider the feelings of their listeners.","zh":"當說話者考慮聽者感受，溝通會改善。"},{"en":"This phrase identifies the people directly involved in the conversation.","zh":"這個短語指出直接參與對話的人。"}],"source":"90 - Sampling Bias.pdf","sourcePage":12},{"front":"even with this","meaning":"即使這樣","examples":[{"en":"Even with this, sampling bias can easily arise.","zh":"即使這樣，抽樣偏差仍很容易產生。"},{"en":"Even with this means despite this effort, condition or precaution.","zh":"even with this 指儘管有這種努力、條件或預防措施。"},{"en":"A student may revise hard; even with this, exam stress can still affect performance.","zh":"學生可能努力溫習；即使這樣，考試壓力仍可能影響表現。"},{"en":"This phrase shows that a problem may remain after a solution is attempted.","zh":"這個短語顯示在嘗試解決後，問題仍可能存在。"},{"en":"It prepares readers for a limitation.","zh":"它為讀者引出限制。"}],"source":"90 - Sampling Bias.pdf","sourcePage":12},{"front":"arise due to","meaning":"因……而產生","examples":[{"en":"Sampling bias can arise due to many variables.","zh":"抽樣偏差可以因許多變數而產生。"},{"en":"To arise due to something means to happen because of it.","zh":"arise due to something 指因某事而發生。"},{"en":"Delays may arise due to bad weather or staff illness.","zh":"延誤可能因惡劣天氣或員工生病而產生。"},{"en":"Bias can arise due to small choices in time, place or wording.","zh":"偏差可以因時間、地點或措辭上的小選擇而產生。"},{"en":"This phrase connects a problem with its cause.","zh":"這個短語把問題與原因連繫起來。"}],"source":"90 - Sampling Bias.pdf","sourcePage":12},{"front":"variables in place","meaning":"現有的變數","examples":[{"en":"Bias can arise because of the number of variables in place.","zh":"偏差可能因現有變數的數目而產生。"},{"en":"Variables in place are the different factors already affecting a situation.","zh":"variables in place 指已經影響某情況的不同因素。"},{"en":"In a classroom, variables in place may include noise, time of day and student mood.","zh":"在課室中，現有變數可能包括噪音、時間和學生情緒。"},{"en":"More variables make it harder to know what caused the result.","zh":"變數越多，就越難知道甚麼造成結果。"},{"en":"This phrase highlights existing factors that can influence outcomes.","zh":"這個短語突出會影響結果的既有因素。"}],"source":"90 - Sampling Bias.pdf","sourcePage":12},{"front":"it only takes one to","meaning":"只需要一個……就會","examples":[{"en":"It only takes one variable to skew the data.","zh":"只需要一個變數就會令數據偏斜。"},{"en":"It only takes one to do something means a single factor is enough to cause a result.","zh":"it only takes one to do something 指單一因素已足以造成結果。"},{"en":"It only takes one careless mistake to change the meaning of a sentence.","zh":"只需要一個粗心錯誤，就會改變句子的意思。"},{"en":"In research, one hidden bias can damage an otherwise careful study.","zh":"在研究中，一個隱藏偏差可以破壞原本仔細的研究。"},{"en":"This phrase stresses how little is needed to create a problem.","zh":"這個短語強調造成問題所需的因素很少。"}],"source":"90 - Sampling Bias.pdf","sourcePage":12},{"front":"skew the data","meaning":"扭曲數據；令數據偏斜","examples":[{"en":"A single variable can skew the data.","zh":"單一變數可以扭曲數據。"},{"en":"To skew the data means to distort the results so they no longer reflect reality fairly.","zh":"skew the data 指扭曲結果，使其不能公平反映現實。"},{"en":"Asking only gym members about exercise habits can skew the data.","zh":"只問健身會員運動習慣，可能令數據偏斜。"},{"en":"Skewed data may lead leaders to solve the wrong problem.","zh":"偏斜數據可能令領導者解決錯誤問題。"},{"en":"This phrase warns that numbers can be bent by hidden factors.","zh":"這個短語提醒我們，數字可以被隱藏因素扭曲。"}],"source":"90 - Sampling Bias.pdf","sourcePage":12},{"front":"take samples from","meaning":"從……抽取樣本","examples":[{"en":"Researchers may take samples from a specific location.","zh":"研究人員可能從特定地點抽取樣本。"},{"en":"To take samples from somewhere means to collect data, people or material from that place.","zh":"take samples from somewhere 指從某地方收集數據、人或材料。"},{"en":"A health team may take samples from several clinics to study patient waiting times.","zh":"醫療團隊可能從幾間診所抽取樣本，研究病人等候時間。"},{"en":"Sampling from only one place can miss people with different habits.","zh":"只從一個地方抽樣，可能漏掉有不同習慣的人。"},{"en":"This phrase focuses on where the sample is collected.","zh":"這個短語著重樣本從哪裡收集。"}],"source":"90 - Sampling Bias.pdf","sourcePage":12},{"front":"a specific location","meaning":"特定地點","examples":[{"en":"Taking samples from a specific location may create bias.","zh":"從特定地點抽取樣本可能造成偏差。"},{"en":"A specific location is one particular place, not a wide range of places.","zh":"specific location 指某一個特定地方，而不是廣泛地點。"},{"en":"A survey done outside one shopping mall uses a specific location.","zh":"在一個商場外進行的調查使用了特定地點。"},{"en":"One location may attract a special type of person, so results may not be general.","zh":"一個地點可能吸引特殊類型的人，所以結果未必能概括。"},{"en":"This phrase highlights a narrow sampling place.","zh":"這個短語突出狹窄的抽樣地點。"}],"source":"90 - Sampling Bias.pdf","sourcePage":13},{"front":"street corner","meaning":"街角","examples":[{"en":"A street corner may not provide a representative sample.","zh":"街角未必能提供具代表性的樣本。"},{"en":"A street corner is the place where two streets meet.","zh":"street corner 指兩條街道相交的地方。"},{"en":"A charity worker may stand on a street corner to ask people for donations.","zh":"慈善工作者可能站在街角向人募捐。"},{"en":"People passing one street corner may not represent the whole city.","zh":"經過某一個街角的人未必代表整個城市。"},{"en":"This phrase refers to a small public location often used for quick contact.","zh":"這個短語指常用於快速接觸人的小型公共地點。"}],"source":"90 - Sampling Bias.pdf","sourcePage":13},{"front":"business district","meaning":"商業區","examples":[{"en":"A street corner in the business district may exclude ordinary workers.","zh":"商業區的街角可能排除普通工人。"},{"en":"A business district is an area with many offices, banks and commercial buildings.","zh":"business district 指有很多辦公室、銀行和商業建築的地區。"},{"en":"People in a business district at lunchtime may mostly be office workers.","zh":"午餐時間在商業區的人可能主要是辦公室員工。"},{"en":"Sampling there may miss residents, students or workers in other industries.","zh":"在那裡抽樣可能漏掉居民、學生或其他行業工人。"},{"en":"This phrase describes an area shaped by business activity.","zh":"這個短語描述由商業活動塑造的地區。"}],"source":"90 - Sampling Bias.pdf","sourcePage":13},{"front":"ordinary workers","meaning":"普通工人","examples":[{"en":"Ordinary workers may be excluded from a business-district survey.","zh":"普通工人可能被商業區調查排除。"},{"en":"Ordinary workers are regular employees who are not managers, executives or specialists in the context being discussed.","zh":"ordinary workers 指在所討論語境中不是管理層、高層或專家的普通僱員。"},{"en":"Factory staff, cleaners and shop assistants may be ordinary workers in a labour survey.","zh":"在勞工調查中，工廠員工、清潔工和店員都可能是普通工人。"},{"en":"If ordinary workers are excluded, the survey may overrepresent office professionals.","zh":"如果普通工人被排除，調查可能過度代表辦公室專業人士。"},{"en":"This phrase focuses on everyday employees.","zh":"這個短語著重日常僱員。"}],"source":"90 - Sampling Bias.pdf","sourcePage":13},{"front":"restaurant district","meaning":"餐廳區","examples":[{"en":"A restaurant district may exclude people who usually cook for themselves.","zh":"餐廳區可能排除通常自己煮食的人。"},{"en":"A restaurant district is an area with many restaurants, cafés or food businesses.","zh":"restaurant district 指有很多餐廳、咖啡店或飲食業的地區。"},{"en":"A survey in a restaurant district may find many people who eat out often.","zh":"在餐廳區進行調查，可能找到很多經常外出用餐的人。"},{"en":"Such a location can bias food spending results because home cooks are less visible there.","zh":"這種地點可以令飲食開支結果有偏差，因為自己煮食的人在那裡較不常見。"},{"en":"This phrase describes a food-focused urban area.","zh":"這個短語描述以飲食為中心的市區。"}],"source":"90 - Sampling Bias.pdf","sourcePage":13},{"front":"cook for themselves","meaning":"自己煮食","examples":[{"en":"People who cook for themselves may not appear in a restaurant-district sample.","zh":"自己煮食的人可能不會出現在餐廳區樣本中。"},{"en":"To cook for themselves means to prepare their own meals instead of buying cooked food.","zh":"cook for themselves 指自己準備飯餐，而不是購買已煮好的食物。"},{"en":"Students may cook for themselves to save money.","zh":"學生可能自己煮食以節省金錢。"},{"en":"People who cook for themselves may have different food habits from people who eat out.","zh":"自己煮食的人可能與外出用餐的人有不同飲食習慣。"},{"en":"This phrase describes a home-based eating habit.","zh":"這個短語描述以家居為基礎的飲食習慣。"}],"source":"90 - Sampling Bias.pdf","sourcePage":13},{"front":"health club","meaning":"健身會","examples":[{"en":"A health club nearby may affect the type of respondents.","zh":"附近的健身會可能影響受訪者類型。"},{"en":"A health club is a place where people exercise, train or use fitness facilities.","zh":"health club 指人們運動、訓練或使用健身設施的地方。"},{"en":"People leaving a health club may be more interested in exercise than average residents.","zh":"離開健身會的人可能比一般居民更關心運動。"},{"en":"Sampling near a health club can bias results about health habits.","zh":"在健身會附近抽樣可能令健康習慣結果有偏差。"},{"en":"This phrase refers to a gym or fitness centre.","zh":"這個短語指健身室或健身中心。"}],"source":"90 - Sampling Bias.pdf","sourcePage":13},{"front":"the majority of respondents","meaning":"大多數受訪者","examples":[{"en":"The majority of respondents near a health club may be healthier than average.","zh":"健身會附近的大多數受訪者可能比平均水平更健康。"},{"en":"The majority of respondents means more than half of the people who answer.","zh":"majority of respondents 指超過一半的回答者。"},{"en":"If the majority of respondents are students, a school survey may not reflect parents’ views.","zh":"如果大多數受訪者是學生，學校調查可能不能反映家長看法。"},{"en":"Knowing who forms the majority helps researchers interpret results carefully.","zh":"知道誰構成大多數，有助研究人員謹慎詮釋結果。"},{"en":"This phrase identifies the main group among respondents.","zh":"這個短語指出受訪者中的主要群體。"}],"source":"90 - Sampling Bias.pdf","sourcePage":13},{"front":"healthier than the average","meaning":"比平均水平更健康","examples":[{"en":"Respondents near a health club may be healthier than the average of the population.","zh":"健身會附近的受訪者可能比人口平均水平更健康。"},{"en":"Healthier than the average means having better health than most people in the comparison group.","zh":"healthier than the average 指健康狀況比比較群體中大多數人更好。"},{"en":"Regular swimmers may be healthier than the average adult in their area.","zh":"經常游泳的人可能比其地區一般成年人更健康。"},{"en":"If healthier people are overrepresented, health survey results may look too positive.","zh":"如果較健康的人被過度代表，健康調查結果可能看起來過分正面。"},{"en":"This phrase compares one group with the general level.","zh":"這個短語把某群體與一般水平比較。"}],"source":"90 - Sampling Bias.pdf","sourcePage":13},{"front":"university campus","meaning":"大學校園","examples":[{"en":"A survey on a university campus may still suffer from bias.","zh":"在大學校園進行的調查仍可能有偏差。"},{"en":"A university campus is the area where a university’s buildings, classrooms and facilities are located.","zh":"university campus 指大學建築、課室和設施所在的區域。"},{"en":"A campus survey may reach many students but miss people who study online or part-time.","zh":"校園調查可能接觸到很多學生，但漏掉網上或兼讀學生。"},{"en":"Location within a campus can affect which students are contacted.","zh":"校園內的位置可以影響哪些學生被接觸。"},{"en":"This phrase refers to the physical setting of a university.","zh":"這個短語指大學的實體環境。"}],"source":"90 - Sampling Bias.pdf","sourcePage":13},{"front":"be designed to poll","meaning":"旨在調查","examples":[{"en":"The survey may be designed to poll university students.","zh":"該調查可能旨在調查大學生。"},{"en":"To be designed to poll a group means to be created to ask that group for opinions or information.","zh":"be designed to poll a group 指被設計來詢問某群體的意見或資料。"},{"en":"A school form may be designed to poll parents about lunch choices.","zh":"學校表格可能旨在調查家長對午餐選擇的意見。"},{"en":"A survey’s design should match the people it aims to reach.","zh":"調查設計應配合它想接觸的人。"},{"en":"This phrase focuses on the intended survey target.","zh":"這個短語著重調查的目標對象。"}],"source":"90 - Sampling Bias.pdf","sourcePage":14},{"front":"university students","meaning":"大學生","examples":[{"en":"A campus survey may aim to poll university students.","zh":"校園調查可能旨在調查大學生。"},{"en":"University students are people studying at a university for a degree or higher qualification.","zh":"university students 指在大學攻讀學位或高等資格的人。"},{"en":"University students may have different schedules depending on lectures, work and part-time study.","zh":"大學生的時間表可能因課堂、工作和兼讀而不同。"},{"en":"A survey of university students should include different faculties and study modes.","zh":"大學生調查應包括不同學院和學習模式。"},{"en":"This phrase identifies a specific education group.","zh":"這個短語指出一個特定教育群體。"}],"source":"90 - Sampling Bias.pdf","sourcePage":14},{"front":"engineering faculty","meaning":"工程學院","examples":[{"en":"A survey near the engineering faculty may miss arts students.","zh":"在工程學院附近進行調查可能漏掉文科學生。"},{"en":"The engineering faculty is the university department or area for engineering studies.","zh":"engineering faculty 指大學中負責工程學科的部門或區域。"},{"en":"Students near the engineering faculty may have different interests from students in humanities subjects.","zh":"工程學院附近的學生可能與人文科學生有不同興趣。"},{"en":"Sampling only near one faculty can bias results about the whole university.","zh":"只在一個學院附近抽樣，可能令整間大學的結果有偏差。"},{"en":"This phrase refers to one academic division.","zh":"這個短語指一個學術分部。"}],"source":"90 - Sampling Bias.pdf","sourcePage":14},{"front":"arts faculty","meaning":"文學院；藝術學院","examples":[{"en":"A survey near the arts faculty may miss engineering students.","zh":"在文學院附近進行調查可能漏掉工程學生。"},{"en":"The arts faculty is the university department or area for humanities, languages, arts or related subjects.","zh":"arts faculty 指大學中負責人文、語言、藝術或相關科目的部門或區域。"},{"en":"Students in an arts faculty may spend more time in libraries, studios or seminar rooms.","zh":"文學院學生可能花更多時間在圖書館、工作室或研討室。"},{"en":"Sampling only near the arts faculty may overrepresent certain academic backgrounds.","zh":"只在文學院附近抽樣，可能過度代表某些學術背景。"},{"en":"This phrase refers to one part of a university, not all students.","zh":"這個短語指大學的一部分，而不是所有學生。"}],"source":"90 - Sampling Bias.pdf","sourcePage":14},{"front":"part-time or full-time schools","meaning":"兼讀制或全日制學院","examples":[{"en":"Researchers should consider whether respondents are from part-time or full-time schools.","zh":"研究人員應考慮受訪者來自兼讀制還是全日制學院。"},{"en":"Part-time or full-time schools refer to study arrangements where students attend either limited hours or a full schedule.","zh":"part-time or full-time schools 指學生以有限時間或完整時間表上課的學習安排。"},{"en":"Part-time students may work during the day, while full-time students may spend more time on campus.","zh":"兼讀學生可能日間工作，而全日制學生可能花更多時間在校園。"},{"en":"Mixing these groups without care can hide important differences.","zh":"若不謹慎混合這些群體，可能隱藏重要差異。"},{"en":"This phrase highlights study mode as a sampling variable.","zh":"這個短語突出學習模式作為抽樣變數。"}],"source":"90 - Sampling Bias.pdf","sourcePage":14},{"front":"race, colour and gender","meaning":"種族、膚色和性別","examples":[{"en":"Race, colour and gender may all affect survey samples.","zh":"種族、膚色和性別都可能影響調查樣本。"},{"en":"Race, colour and gender are personal and social characteristics that may influence people’s experiences.","zh":"race, colour and gender 是可能影響人們經驗的個人和社會特徵。"},{"en":"A workplace survey should check whether race, colour and gender groups are fairly represented.","zh":"工作場所調查應檢查不同種族、膚色和性別群體是否被公平代表。"},{"en":"If these factors are ignored, important patterns of unfair treatment may be missed.","zh":"如果忽視這些因素，重要的不公平對待模式可能被錯過。"},{"en":"This phrase names identity variables that can affect sampling.","zh":"這個短語列出可能影響抽樣的身份變數。"}],"source":"90 - Sampling Bias.pdf","sourcePage":14},{"front":"socio-economic background","meaning":"社會經濟背景","examples":[{"en":"Socio-economic background may be another sampling variable.","zh":"社會經濟背景可能是另一個抽樣變數。"},{"en":"Socio-economic background means a person’s social and economic position, including income, education and occupation.","zh":"socio-economic background 指一個人的社會和經濟位置，包括收入、教育和職業。"},{"en":"Students from different socio-economic backgrounds may have different access to tutoring and technology.","zh":"來自不同社會經濟背景的學生，可能有不同補習和科技使用機會。"},{"en":"Ignoring socio-economic background can make inequality invisible in survey results.","zh":"忽視社會經濟背景可能令不平等在調查結果中變得不可見。"},{"en":"This phrase links social position with economic conditions.","zh":"這個短語把社會位置與經濟條件連繫起來。"}],"source":"90 - Sampling Bias.pdf","sourcePage":14},{"front":"first language","meaning":"第一語言","examples":[{"en":"First language can affect who is represented in a sample.","zh":"第一語言可以影響誰在樣本中得到代表。"},{"en":"A first language is the language a person first learned or uses most naturally from early life.","zh":"first language 指一個人最早學會或從小最自然使用的語言。"},{"en":"A survey written only in English may miss people whose first language is not English.","zh":"只用英文寫成的調查，可能漏掉第一語言不是英文的人。"},{"en":"Language barriers can influence who answers and how clearly they answer.","zh":"語言障礙可以影響誰回答，以及他們回答得多清楚。"},{"en":"This phrase is important when studying mixed-language populations.","zh":"研究多語言人口時，這個短語很重要。"}],"source":"90 - Sampling Bias.pdf","sourcePage":14},{"front":"the list goes on and on","meaning":"清單沒完沒了","examples":[{"en":"The list of possible sampling variables goes on and on.","zh":"可能的抽樣變數清單沒完沒了。"},{"en":"The list goes on and on means there are many more examples than can easily be named.","zh":"the list goes on and on 指例子多到難以全部列出。"},{"en":"Students face distractions from phones, noise, hunger, stress, and the list goes on and on.","zh":"學生面對手機、噪音、飢餓、壓力等干擾，清單沒完沒了。"},{"en":"This phrase shows that a problem has many possible parts.","zh":"這個短語顯示問題有很多可能部分。"},{"en":"It is often used when the speaker does not want to list every example.","zh":"當說話者不想列出每個例子時，常使用這個短語。"}],"source":"90 - Sampling Bias.pdf","sourcePage":14},{"front":"deal with this","meaning":"處理這個問題","examples":[{"en":"One method to deal with this is to represent all targeted groups.","zh":"處理這個問題的一種方法，是讓所有目標群組都得到代表。"},{"en":"To deal with this means to handle or try to solve the problem just mentioned.","zh":"deal with this 指處理或嘗試解決剛提到的問題。"},{"en":"If students keep arriving late, the school must deal with this by checking transport and routines.","zh":"如果學生持續遲到，學校必須透過檢查交通和日常安排來處理這個問題。"},{"en":"Dealing with a problem may reduce harm even if it cannot remove the problem completely.","zh":"處理問題可以減少傷害，即使不能完全消除問題。"},{"en":"This phrase refers back to an existing difficulty.","zh":"這個短語回指已有困難。"}],"source":"90 - Sampling Bias.pdf","sourcePage":14},{"front":"targeted groups","meaning":"目標群組","examples":[{"en":"All targeted groups should be represented in the sample.","zh":"所有目標群組都應在樣本中得到代表。"},{"en":"Targeted groups are the specific groups a study, policy or message aims to include or reach.","zh":"targeted groups 指研究、政策或訊息旨在包括或接觸的特定群體。"},{"en":"A youth survey may have targeted groups such as students, apprentices and unemployed young people.","zh":"青年調查的目標群組可能包括學生、學徒和失業青年。"},{"en":"If targeted groups are missed, the research cannot answer its own question fairly.","zh":"如果漏掉目標群組，研究就不能公平回答自己的問題。"},{"en":"This phrase focuses on the groups that matter for the study.","zh":"這個短語著重對研究重要的群體。"}],"source":"90 - Sampling Bias.pdf","sourcePage":15},{"front":"be represented","meaning":"得到代表","examples":[{"en":"All targeted groups should be represented, if only a little.","zh":"所有目標群組都應得到代表，即使只是少量。"},{"en":"To be represented means to be included in a way that shows a group’s presence or views.","zh":"be represented 指以能顯示某群體存在或觀點的方式被包括在內。"},{"en":"A school council is fairer when younger students are represented as well as older students.","zh":"當較年幼和較年長學生都得到代表時，學生會較公平。"},{"en":"If a group is not represented, its needs may be ignored.","zh":"如果一個群體沒有得到代表，其需要可能被忽視。"},{"en":"This phrase focuses on inclusion in data or decision-making.","zh":"這個短語著重在數據或決策中的納入。"}],"source":"90 - Sampling Bias.pdf","sourcePage":15},{"front":"if only a little","meaning":"即使只是少量","examples":[{"en":"Every group should be represented, if only a little.","zh":"每個群體都應得到代表，即使只是少量。"},{"en":"If only a little means even if the amount is small.","zh":"if only a little 指即使數量很少。"},{"en":"A busy parent may help with a school event, if only a little, by bringing supplies.","zh":"忙碌家長可以透過帶用品來協助學校活動，即使只是少量。"},{"en":"Small representation is better than complete absence, but it may still be limited.","zh":"少量代表比完全缺席好，但仍可能有限。"},{"en":"This phrase shows a minimum acceptable level.","zh":"這個短語表示最低限度。"}],"source":"90 - Sampling Bias.pdf","sourcePage":15},{"front":"mathematical extrapolations","meaning":"數學推算","examples":[{"en":"Researchers can make mathematical extrapolations to correct bias.","zh":"研究人員可以作出數學推算來修正偏差。"},{"en":"Mathematical extrapolations are calculations that estimate unknown values from known data.","zh":"mathematical extrapolations 指根據已知數據估計未知數值的計算。"},{"en":"A teacher may estimate a class’s final average from early test scores using a simple extrapolation.","zh":"老師可能用早期測驗分數，透過簡單推算估計班級最終平均分。"},{"en":"Extrapolations can help, but they depend on strong assumptions.","zh":"推算可以有幫助，但取決於強而有力的假設。"},{"en":"This phrase refers to extending numbers beyond what was directly measured.","zh":"這個短語指把數字延伸到直接量度以外。"}],"source":"90 - Sampling Bias.pdf","sourcePage":15},{"front":"correct the bias","meaning":"修正偏差","examples":[{"en":"Mathematical extrapolations may help correct the bias.","zh":"數學推算可能幫助修正偏差。"},{"en":"To correct the bias means to adjust data or methods so the result becomes fairer.","zh":"correct the bias 指調整數據或方法，使結果變得較公平。"},{"en":"A survey may correct bias by giving more weight to groups that were undercounted.","zh":"調查可以透過給被少算群體更高權重來修正偏差。"},{"en":"Correcting bias is difficult if researchers do not know exactly who was missed.","zh":"如果研究人員不知道究竟漏掉了誰，修正偏差會很困難。"},{"en":"This phrase focuses on reducing distortion.","zh":"這個短語著重減少扭曲。"}],"source":"90 - Sampling Bias.pdf","sourcePage":15},{"front":"for this to work","meaning":"要使這方法奏效","examples":[{"en":"For this to work, the degree of underrepresentation must be quantified.","zh":"要使這方法奏效，代表性不足的程度必須被量化。"},{"en":"For this to work means for this method or plan to succeed.","zh":"for this to work 指要讓這個方法或計劃成功。"},{"en":"For online lessons to work, students need stable internet and a quiet place.","zh":"要使網上課堂奏效，學生需要穩定網絡和安靜地方。"},{"en":"A method may sound good but fail if its necessary conditions are missing.","zh":"一種方法可能聽起來好，但如果缺少必要條件，就會失敗。"},{"en":"This phrase introduces a condition for success.","zh":"這個短語引入成功條件。"}],"source":"90 - Sampling Bias.pdf","sourcePage":15},{"front":"degree of underrepresentation","meaning":"代表性不足的程度","examples":[{"en":"The degree of underrepresentation needs to be quantified exactly.","zh":"代表性不足的程度需要被準確量化。"},{"en":"The degree of underrepresentation means how much a group is included less than it should be.","zh":"degree of underrepresentation 指某群體被納入的程度比應有水平低多少。"},{"en":"If women form half the population but only one fifth of a sample, their underrepresentation is large.","zh":"如果女性佔人口一半，但只佔樣本五分之一，她們代表性不足的程度很大。"},{"en":"Measuring this degree helps researchers decide how much adjustment is needed.","zh":"量度這個程度幫助研究人員決定需要多少調整。"},{"en":"This phrase focuses on the size of the missing representation.","zh":"這個短語著重缺失代表性的大小。"}],"source":"90 - Sampling Bias.pdf","sourcePage":15},{"front":"be quantified exactly","meaning":"被準確量化","examples":[{"en":"The bias needs to be quantified exactly.","zh":"偏差需要被準確量化。"},{"en":"To be quantified exactly means to be measured precisely in numbers.","zh":"be quantified exactly 指用數字精確量度。"},{"en":"A school cannot fix attendance problems well unless absence rates are quantified exactly.","zh":"除非缺席率被準確量化，學校難以妥善解決出席問題。"},{"en":"Exact measurement allows clearer comparison and correction.","zh":"準確量度能讓比較和修正更清楚。"},{"en":"This phrase focuses on turning a problem into precise numbers.","zh":"這個短語著重把問題轉化為精確數字。"}],"source":"90 - Sampling Bias.pdf","sourcePage":15},{"front":"one needs to assume","meaning":"人們需要假設","examples":[{"en":"One needs to assume that underrepresented respondents are typical.","zh":"人們需要假設代表性不足的受訪者是典型的。"},{"en":"One needs to assume means it is necessary to accept something as true for the argument or calculation.","zh":"one needs to assume 指為了論證或計算，必須接受某事為真。"},{"en":"To estimate travel time, one needs to assume the train is running normally.","zh":"要估計交通時間，人們需要假設火車正常運作。"},{"en":"If the assumption is wrong, the conclusion may also be wrong.","zh":"如果假設錯誤，結論也可能錯誤。"},{"en":"This phrase introduces a necessary but uncertain condition.","zh":"這個短語引入必要但不確定的條件。"}],"source":"90 - Sampling Bias.pdf","sourcePage":15},{"front":"underrepresented respondents","meaning":"代表性不足的受訪者","examples":[{"en":"Underrepresented respondents may not be typical of their group.","zh":"代表性不足的受訪者未必是其群體的典型代表。"},{"en":"Underrepresented respondents are people from a group that appears too rarely in the sample.","zh":"underrepresented respondents 指來自某個在樣本中出現太少的群體的受訪者。"},{"en":"If only a few part-time students answer a survey, they are underrepresented respondents.","zh":"如果只有少數兼讀學生回答調查，他們就是代表性不足的受訪者。"},{"en":"Their answers may not reflect all people in the same group.","zh":"他們的答案未必反映同一群體中的所有人。"},{"en":"This phrase warns against trusting a very small subgroup too much.","zh":"這個短語提醒不要過分相信非常小的子群體。"}],"source":"90 - Sampling Bias.pdf","sourcePage":15},{"front":"typical of their kind","meaning":"其類別中的典型代表","examples":[{"en":"Researchers assume the respondents are typical of their kind.","zh":"研究人員假設受訪者是其類別中的典型代表。"},{"en":"Typical of their kind means showing the usual features of the group they belong to.","zh":"typical of their kind 指顯示所屬群體通常特徵。"},{"en":"One quiet student is not always typical of all students in the class.","zh":"一名安靜學生不一定是全班學生的典型代表。"},{"en":"If a few respondents are not typical of their kind, extrapolation may mislead.","zh":"如果少數受訪者不是其類別中的典型代表，推算可能誤導。"},{"en":"This phrase focuses on whether examples fairly represent a group.","zh":"這個短語著重例子是否公平代表某群體。"}],"source":"90 - Sampling Bias.pdf","sourcePage":16},{"front":"aim to find","meaning":"旨在找出","examples":[{"en":"A survey may aim to find the population’s opinion.","zh":"調查可能旨在找出大眾意見。"},{"en":"To aim to find something means to have the goal of discovering it.","zh":"aim to find something 指以發現某事為目標。"},{"en":"A school survey may aim to find why students avoid the library.","zh":"學校調查可能旨在找出學生為何避開圖書館。"},{"en":"Clear aims help researchers choose the right questions and sample.","zh":"清楚目標幫助研究人員選擇正確問題和樣本。"},{"en":"This phrase states the purpose of an investigation.","zh":"這個短語說明調查目的。"}],"source":"90 - Sampling Bias.pdf","sourcePage":16},{"front":"the population’s opinion","meaning":"大眾意見","examples":[{"en":"Researchers may try to find the population’s opinion on an election.","zh":"研究人員可能嘗試找出大眾對選舉的意見。"},{"en":"The population’s opinion means the view held by the wider group of people being studied.","zh":"population’s opinion 指被研究較大群體所持的看法。"},{"en":"A city council may survey residents to learn the population’s opinion on bus services.","zh":"市議會可能調查居民，以了解大眾對巴士服務的意見。"},{"en":"A small biased sample cannot reliably show the population’s opinion.","zh":"有偏差的小樣本不能可靠顯示大眾意見。"},{"en":"This phrase refers to the general view of the whole target group.","zh":"這個短語指整個目標群體的一般看法。"}],"source":"90 - Sampling Bias.pdf","sourcePage":16},{"front":"outcome of an election","meaning":"選舉結果","examples":[{"en":"The survey may ask about the outcome of an election.","zh":"調查可能詢問選舉結果。"},{"en":"The outcome of an election is the final result, such as who wins or how many votes each side receives.","zh":"outcome of an election 指最終結果，例如誰勝出或每方獲得多少票。"},{"en":"Polls try to predict the outcome of an election before voting finishes.","zh":"民意調查嘗試在投票結束前預測選舉結果。"},{"en":"Biased samples can make an election prediction inaccurate.","zh":"有偏差樣本可以令選舉預測不準確。"},{"en":"This phrase focuses on the result, not the campaign process.","zh":"這個短語著重結果，而不是競選過程。"}],"source":"90 - Sampling Bias.pdf","sourcePage":16},{"front":"for whatever reason","meaning":"不論因為甚麼原因","examples":[{"en":"For whatever reason, the researchers may interview fewer women than men.","zh":"不論因為甚麼原因，研究人員訪問的女性可能少於男性。"},{"en":"For whatever reason means no matter what the cause is or even if the cause is unknown.","zh":"for whatever reason 指不管原因是甚麼，甚至原因未知。"},{"en":"For whatever reason, some students may avoid answering a survey about school rules.","zh":"不論因為甚麼原因，有些學生可能避免回答關於校規的調查。"},{"en":"The effect of missing responses matters even when the reason is unclear.","zh":"即使原因不清楚，缺失回覆的影響仍然重要。"},{"en":"This phrase moves attention from cause to consequence.","zh":"這個短語把注意力從原因轉向後果。"}],"source":"90 - Sampling Bias.pdf","sourcePage":16},{"front":"one woman for every four men","meaning":"每四名男性對一名女性","examples":[{"en":"The sample may include one woman for every four men.","zh":"樣本可能包括每四名男性對一名女性。"},{"en":"One woman for every four men means a ratio of 1 female respondent to 4 male respondents.","zh":"one woman for every four men 指女性受訪者與男性受訪者的比例為一比四。"},{"en":"If a club survey has one girl for every four boys, girls’ views may be underrepresented.","zh":"如果學會調查中每四名男生只有一名女生，女生意見可能代表不足。"},{"en":"Unequal ratios can create bias when groups have different opinions.","zh":"當不同群體有不同意見，不平等比例可能造成偏差。"},{"en":"This phrase expresses imbalance through a simple ratio.","zh":"這個短語用簡單比例表達不平衡。"}],"source":"90 - Sampling Bias.pdf","sourcePage":16},{"front":"be multiplied by","meaning":"乘以……","examples":[{"en":"The responses of the women could be multiplied by four.","zh":"女性的回覆可以乘以四。"},{"en":"To be multiplied by a number means to be increased according to that number in a calculation.","zh":"be multiplied by a number 指在計算中按該數字增加。"},{"en":"If one answer represents three missing people, it may be multiplied by three in weighting.","zh":"如果一個答案代表三個缺失的人，它在加權中可能乘以三。"},{"en":"Multiplying responses can adjust numbers, but it cannot guarantee true representativeness.","zh":"放大回覆可以調整數字，但不能保證真正具代表性。"},{"en":"This phrase describes a mathematical correction.","zh":"這個短語描述數學修正。"}],"source":"90 - Sampling Bias.pdf","sourcePage":16},{"front":"guardedly","meaning":"謹慎地","examples":[{"en":"Researchers can only assume the bias has been corrected guardedly.","zh":"研究人員只能謹慎地假設偏差已被修正。"},{"en":"Guardedly means carefully and with caution, because there is uncertainty.","zh":"guardedly 指因存在不確定而小心謹慎地。"},{"en":"A doctor may speak guardedly before test results are confirmed.","zh":"在檢測結果確認前，醫生可能謹慎地說話。"},{"en":"Researchers should state conclusions guardedly when assumptions are weak.","zh":"當假設薄弱時，研究人員應謹慎地陳述結論。"},{"en":"This word shows careful confidence, not full certainty.","zh":"這個詞表示小心的信心，而不是完全確定。"}],"source":"90 - Sampling Bias.pdf","sourcePage":16},{"front":"with many provisos","meaning":"帶有很多附帶條件","examples":[{"en":"The conclusion should be made with many provisos.","zh":"結論應帶有很多附帶條件地作出。"},{"en":"With many provisos means with many conditions, warnings or limitations attached.","zh":"with many provisos 指附帶許多條件、警告或限制。"},{"en":"A teacher may praise an essay with provisos if the ideas are good but grammar is weak.","zh":"如果文章想法好但文法弱，老師可能帶有附帶條件地稱讚它。"},{"en":"Conclusions based on adjusted data often need provisos because assumptions may be wrong.","zh":"基於調整數據的結論常需要附帶條件，因為假設可能錯誤。"},{"en":"This phrase warns readers not to accept a conclusion too simply.","zh":"這個短語提醒讀者不要過於簡單地接受結論。"}],"source":"90 - Sampling Bias.pdf","sourcePage":16},{"front":"bias from gender","meaning":"來自性別的偏差","examples":[{"en":"The sampling bias from gender may be corrected mathematically.","zh":"來自性別的抽樣偏差可能可透過數學方式修正。"},{"en":"Bias from gender is distortion caused by one gender being overrepresented or underrepresented.","zh":"bias from gender 指因某一性別被過度或不足代表而造成的扭曲。"},{"en":"A workplace survey may have bias from gender if mostly men answer questions about promotion.","zh":"如果職場晉升調查主要由男性回答，就可能有來自性別的偏差。"},{"en":"Gender bias can hide the experiences of groups that answer less often.","zh":"性別偏差可以隱藏較少回答群體的經驗。"},{"en":"This phrase names gender as the source of sampling distortion.","zh":"這個短語指出性別是抽樣扭曲的來源。"}],"source":"90 - Sampling Bias.pdf","sourcePage":16},{"front":"all the other variables","meaning":"所有其他變數","examples":[{"en":"All the other variables must also be excluded.","zh":"所有其他變數也必須被排除。"},{"en":"All the other variables means every other factor that could affect the result.","zh":"all the other variables 指所有其他可能影響結果的因素。"},{"en":"In a study about sleep, other variables may include stress, diet, exercise and screen time.","zh":"在睡眠研究中，其他變數可能包括壓力、飲食、運動和螢幕時間。"},{"en":"If other variables remain, researchers cannot be sure what caused the result.","zh":"如果其他變數仍存在，研究人員不能確定甚麼造成結果。"},{"en":"This phrase stresses the difficulty of isolating one factor.","zh":"這個短語強調隔離單一因素的困難。"}],"source":"90 - Sampling Bias.pdf","sourcePage":17},{"front":"introduce bias","meaning":"引入偏差","examples":[{"en":"Other variables may introduce bias.","zh":"其他變數可能引入偏差。"},{"en":"To introduce bias means to bring distortion or unfair influence into a result.","zh":"introduce bias 指把扭曲或不公平影響帶入結果。"},{"en":"Asking a question in a leading way can introduce bias into a survey.","zh":"以引導方式提問可以把偏差引入調查。"},{"en":"Bias may be introduced unintentionally through timing, location or wording.","zh":"偏差可能透過時間、地點或措辭無意中被引入。"},{"en":"This phrase shows how a problem enters the research process.","zh":"這個短語顯示問題如何進入研究過程。"}],"source":"90 - Sampling Bias.pdf","sourcePage":17},{"front":"problematic assumption","meaning":"有問題的假設","examples":[{"en":"This is often a very problematic assumption to make.","zh":"這往往是一個非常有問題的假設。"},{"en":"A problematic assumption is an uncertain or risky belief that may weaken an argument.","zh":"problematic assumption 指可能削弱論點的不確定或有風險信念。"},{"en":"Assuming every student has quiet study space at home is a problematic assumption.","zh":"假設每個學生家中都有安靜溫習空間，是一個有問題的假設。"},{"en":"If an assumption is problematic, the conclusion based on it may also be weak.","zh":"如果假設有問題，基於它的結論也可能薄弱。"},{"en":"This phrase warns that a key belief may not be safe.","zh":"這個短語提醒一個關鍵信念可能不可靠。"}],"source":"90 - Sampling Bias.pdf","sourcePage":17},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"Students decide whether the following statements agree with the passage.","zh":"學生判斷以下陳述是否與文章一致。"},{"en":"Do the following statements agree with asks whether each statement matches what the text says.","zh":"do the following statements agree with 是問每個陳述是否符合文本內容。"},{"en":"In reading tests, students should check exact wording before deciding whether statements agree.","zh":"在閱讀測驗中，學生應檢查準確措辭，再判斷陳述是否一致。"},{"en":"A statement may sound reasonable but still not agree with the passage.","zh":"陳述可能聽起來合理，但仍未必與文章一致。"},{"en":"This phrase introduces a TRUE, FALSE or NOT GIVEN style task.","zh":"這個短語引入 TRUE、FALSE 或 NOT GIVEN 類型題目。"}],"source":"90 - Sampling Bias.pdf","sourcePage":17},{"front":"information given in","meaning":"……中提供的資料","examples":[{"en":"The answer should be based on the information given in the passage.","zh":"答案應根據文章中提供的資料。"},{"en":"Information given in a passage means the details actually stated or clearly supported by the text.","zh":"information given in a passage 指文本實際說明或清楚支持的細節。"},{"en":"Students should use information given in the passage, not personal knowledge, in reading tests.","zh":"在閱讀測驗中，學生應使用文章中提供的資料，而不是個人知識。"},{"en":"If the passage does not support an answer, it should not be chosen.","zh":"如果文章不支持某答案，就不應選擇它。"},{"en":"This phrase reminds students to stay within the text.","zh":"這個短語提醒學生留在文本範圍內。"}],"source":"90 - Sampling Bias.pdf","sourcePage":17},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A FALSE answer means the statement contradicts the information.","zh":"FALSE 答案表示陳述與資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"contradict the information 指說法與文本所說相反。"},{"en":"If a passage says surveys are unreliable, a statement saying they are always reliable contradicts the information.","zh":"如果文章說調查不可靠，而陳述說它們永遠可靠，就是與資料相矛盾。"},{"en":"Students should choose FALSE only when there is clear conflict with the text.","zh":"只有當陳述與文本明顯衝突時，學生才應選 FALSE。"},{"en":"This phrase means the statement and the passage cannot both be true.","zh":"這個短語表示陳述與文章不能同時為真。"}],"source":"90 - Sampling Bias.pdf","sourcePage":17},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"NOT GIVEN means there is no information on this.","zh":"NOT GIVEN 表示沒有相關資料。"},{"en":"No information on this means the passage does not clearly state or support the point.","zh":"no information on this 指文章沒有清楚說明或支持該點。"},{"en":"If a text describes cave paintings but not the artists’ ages, there is no information on their ages.","zh":"如果文本描述洞穴畫作但沒有說畫家年齡，就沒有關於年齡的相關資料。"},{"en":"Students should not guess TRUE or FALSE when the text gives no evidence.","zh":"當文本沒有證據時，學生不應猜 TRUE 或 FALSE。"},{"en":"This phrase signals that the answer cannot be proved from the passage.","zh":"這個短語表示答案不能從文章中證明。"}],"source":"90 - Sampling Bias.pdf","sourcePage":17},{"front":"very good artists","meaning":"很出色的藝術家","examples":[{"en":"The statement asks whether cavemen were often very good artists.","zh":"該陳述問穴居人是否常常是很出色的藝術家。"},{"en":"Very good artists are people with strong skill in drawing, painting or visual creation.","zh":"very good artists 指在繪畫、畫作或視覺創作方面有強大技巧的人。"},{"en":"A child may become a very good artist after years of practice and feedback.","zh":"孩子經多年練習和回饋後，可能成為很出色的藝術家。"},{"en":"Skill in surviving cave paintings does not prove all prehistoric people were good artists.","zh":"保存下來的洞穴畫技巧，不足以證明所有史前人類都是出色藝術家。"},{"en":"This phrase describes artistic ability, not general intelligence.","zh":"這個短語描述藝術能力，而不是一般智力。"}],"source":"90 - Sampling Bias.pdf","sourcePage":17},{"front":"done cheaply by telephone","meaning":"透過電話低成本進行","examples":[{"en":"Surveys can sometimes be done cheaply by telephone.","zh":"調查有時可以透過電話低成本進行。"},{"en":"Done cheaply by telephone means carried out at low cost using phone calls.","zh":"done cheaply by telephone 指使用電話以低成本進行。"},{"en":"A small charity may collect feedback cheaply by telephone instead of visiting every home.","zh":"小型慈善機構可能透過電話低成本收集回饋，而不是探訪每個家庭。"},{"en":"Telephone surveys save travel costs but can miss people who do not answer calls.","zh":"電話調查節省交通成本，但可能漏掉不接電話的人。"},{"en":"This phrase connects low cost with a specific survey method.","zh":"這個短語把低成本與特定調查方法連繫起來。"}],"source":"90 - Sampling Bias.pdf","sourcePage":17},{"front":"give reliable information","meaning":"提供可靠資料","examples":[{"en":"Surveys do not always give reliable information.","zh":"調查不一定總是提供可靠資料。"},{"en":"To give reliable information means to provide data or facts that can be trusted.","zh":"give reliable information 指提供可信的數據或事實。"},{"en":"A well-designed school survey can give reliable information about lunch quality.","zh":"設計良好的學校調查可以提供關於午餐質素的可靠資料。"},{"en":"Poor sampling can prevent a survey from giving reliable information.","zh":"差劣抽樣可以令調查無法提供可靠資料。"},{"en":"This phrase focuses on trustworthiness of the data.","zh":"這個短語著重數據的可信程度。"}],"source":"90 - Sampling Bias.pdf","sourcePage":17},{"front":"at home during the day","meaning":"日間在家","examples":[{"en":"Elderly and disabled people may often be at home during the day.","zh":"長者和殘疾人士可能常在日間在家。"},{"en":"At home during the day means staying in one’s home in daytime hours.","zh":"at home during the day 指在日間時段留在家中。"},{"en":"People who work night shifts may be at home during the day and asleep when calls arrive.","zh":"夜班工作者可能日間在家，來電時正在睡覺。"},{"en":"Daytime home surveys may reach certain groups more often than others.","zh":"日間家居調查可能較常接觸某些群體。"},{"en":"This phrase connects time and location with sampling bias.","zh":"這個短語把時間和地點與抽樣偏差連繫起來。"}],"source":"90 - Sampling Bias.pdf","sourcePage":18},{"front":"reduce sampling bias","meaning":"減少抽樣偏差","examples":[{"en":"Larger samples do not necessarily reduce sampling bias.","zh":"較大樣本不一定能減少抽樣偏差。"},{"en":"To reduce sampling bias means to make a sample more fairly represent the target population.","zh":"reduce sampling bias 指令樣本更公平地代表目標群體。"},{"en":"A school can reduce sampling bias by asking students from every year group.","zh":"學校可以透過詢問每個年級的學生來減少抽樣偏差。"},{"en":"Reducing bias requires better selection, not just more people.","zh":"減少偏差需要更好選樣，而不只是更多人。"},{"en":"This phrase focuses on making research fairer.","zh":"這個短語著重令研究更公平。"}],"source":"90 - Sampling Bias.pdf","sourcePage":18},{"front":"complete the flowchart","meaning":"完成流程圖","examples":[{"en":"Students complete the flowchart using words from the passage.","zh":"學生使用文章中的字詞完成流程圖。"},{"en":"To complete the flowchart means to fill missing words in a diagram showing steps or stages.","zh":"complete the flowchart 指在顯示步驟或階段的圖表中填入缺失字詞。"},{"en":"In a science lesson, students may complete a flowchart about how water moves through a plant.","zh":"在科學課中，學生可能完成關於水如何通過植物的流程圖。"},{"en":"Flowcharts help learners see order, cause and process.","zh":"流程圖幫助學習者看見次序、原因和過程。"},{"en":"This phrase is a common reading-test instruction.","zh":"這個短語是常見閱讀測驗指示。"}],"source":"90 - Sampling Bias.pdf","sourcePage":18},{"front":"no more than two words","meaning":"不多於兩個詞","examples":[{"en":"Students should choose no more than two words from the passage.","zh":"學生應從文章中選擇不多於兩個詞。"},{"en":"No more than two words means one word or two words, but not three.","zh":"no more than two words 指一個詞或兩個詞，但不是三個。"},{"en":"If the answer limit is no more than two words, “sampling bias” is allowed.","zh":"如果答案限制是不多於兩個詞，“sampling bias” 是可以的。"},{"en":"Writing too many words can lose marks even if the meaning is correct.","zh":"即使意思正確，寫太多詞也可能失分。"},{"en":"This phrase gives a strict answer-length rule.","zh":"這個短語給出嚴格答案字數規則。"}],"source":"90 - Sampling Bias.pdf","sourcePage":18},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter from the options.","zh":"學生從選項中選出正確字母。"},{"en":"To choose the correct letter means to select the answer marked by the right letter.","zh":"choose the correct letter 指選出由正確字母標示的答案。"},{"en":"In multiple-choice questions, students should check whether the answer is A, B, C or D.","zh":"在多項選擇題中，學生應檢查答案是 A、B、C 還是 D。"},{"en":"Understanding the text is not enough if the wrong letter is copied.","zh":"如果抄錯字母，即使理解文本也不夠。"},{"en":"This phrase focuses on answer format.","zh":"這個短語著重答案格式。"}],"source":"90 - Sampling Bias.pdf","sourcePage":18},{"front":"the number of sampling variables","meaning":"抽樣變數的數目","examples":[{"en":"The number of sampling variables can make bias difficult to control.","zh":"抽樣變數的數目可以令偏差難以控制。"},{"en":"The number of sampling variables means how many factors may affect who is included in a sample.","zh":"number of sampling variables 指有多少因素可能影響誰被納入樣本。"},{"en":"A survey may have many variables, such as age, language, income and location.","zh":"調查可能有許多變數，例如年齡、語言、收入和地點。"},{"en":"The more variables there are, the harder it is to correct every imbalance.","zh":"變數越多，就越難修正每個不平衡。"},{"en":"This phrase focuses on the complexity of sampling.","zh":"這個短語著重抽樣的複雜性。"}],"source":"90 - Sampling Bias.pdf","sourcePage":18},{"front":"result in","meaning":"導致","examples":[{"en":"Too many variables can result in important input being lost.","zh":"太多變數可以導致重要意見流失。"},{"en":"To result in something means to cause it to happen.","zh":"result in something 指導致某事發生。"},{"en":"Poor sleep can result in weak concentration during lessons.","zh":"睡眠不足可以導致課堂專注力差。"},{"en":"A biased sample can result in a misleading decision.","zh":"有偏差的樣本可以導致誤導性決定。"},{"en":"This phrase clearly connects cause and effect.","zh":"這個短語清楚連接原因和結果。"}],"source":"90 - Sampling Bias.pdf","sourcePage":18},{"front":"important input","meaning":"重要意見；重要輸入","examples":[{"en":"Important input may be lost if the sample is biased.","zh":"如果樣本有偏差，重要意見可能會流失。"},{"en":"Important input is useful information, advice or opinion that helps a decision.","zh":"important input 指有助決策的有用資訊、建議或意見。"},{"en":"A school may lose important input if quiet students are never asked for feedback.","zh":"如果學校從不詢問安靜學生的回饋，可能失去重要意見。"},{"en":"Missing important input can make a plan less fair or less effective.","zh":"缺少重要意見會令計劃較不公平或較低效。"},{"en":"This phrase focuses on valuable contributions to a process.","zh":"這個短語著重對過程有價值的貢獻。"}],"source":"90 - Sampling Bias.pdf","sourcePage":18},{"front":"mathematical extrapolation","meaning":"數學推算","examples":[{"en":"Mathematical extrapolation requires exact ratios.","zh":"數學推算需要精確比例。"},{"en":"Mathematical extrapolation is a calculation that estimates missing or future values from known data.","zh":"mathematical extrapolation 指根據已知數據估計缺失或未來數值的計算。"},{"en":"A shop may use mathematical extrapolation to estimate monthly sales from one week’s figures.","zh":"商店可能用一星期數字進行數學推算，以估計每月銷售。"},{"en":"Extrapolation becomes risky when the known data are biased or incomplete.","zh":"當已知數據有偏差或不完整時，推算會變得有風險。"},{"en":"This phrase refers to extending a calculation beyond direct observation.","zh":"這個短語指把計算延伸到直接觀察以外。"}],"source":"90 - Sampling Bias.pdf","sourcePage":18},{"front":"yield confident results","meaning":"產生可信的結果","examples":[{"en":"Mathematical extrapolation does not always yield confident results.","zh":"數學推算不一定總能產生可信的結果。"},{"en":"To yield confident results means to produce findings that researchers can trust strongly.","zh":"yield confident results 指產生研究人員能高度信任的發現。"},{"en":"A small survey may not yield confident results if many groups are missing.","zh":"如果許多群體缺失，小型調查未必能產生可信結果。"},{"en":"Weak assumptions reduce confidence even when the calculation is neat.","zh":"即時計算整齊，薄弱假設也會降低信心。"},{"en":"This phrase links method quality with trust in the conclusion.","zh":"這個短語把方法質素與對結論的信任連繫起來。"}],"source":"90 - Sampling Bias.pdf","sourcePage":18},{"front":"require responses from","meaning":"需要來自……的回覆","examples":[{"en":"A fair survey may require responses from different groups.","zh":"公平調查可能需要來自不同群體的回覆。"},{"en":"Require responses from means need answers from particular people or groups.","zh":"require responses from 指需要特定人士或群體的答案。"},{"en":"A school policy survey may require responses from students, parents and teachers.","zh":"學校政策調查可能需要來自學生、家長和老師的回覆。"},{"en":"If responses come from only one group, the decision may ignore others.","zh":"如果回覆只來自一個群體，決定可能忽視其他人。"},{"en":"This phrase focuses on whose answers are needed.","zh":"這個短語著重需要誰的答案。"}],"source":"90 - Sampling Bias.pdf","sourcePage":19},{"front":"exact ratios","meaning":"精確比例","examples":[{"en":"Mathematical extrapolation needs exact ratios to correct bias.","zh":"數學推算需要精確比例來修正偏差。"},{"en":"Exact ratios are precise comparisons between amounts or groups.","zh":"exact ratios 指數量或群體之間的精確比較。"},{"en":"A recipe needs exact ratios of flour and water if the dough must have the right texture.","zh":"如果麵糰需要正確質感，食譜就需要麵粉和水的精確比例。"},{"en":"In survey correction, exact ratios help decide how much each group should count.","zh":"在調查修正中，精確比例幫助決定每個群體應佔多少權重。"},{"en":"This phrase focuses on precise numerical relationships.","zh":"這個短語著重精確數字關係。"}],"source":"90 - Sampling Bias.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 91":[{"front":"the authorship question","meaning":"作者身份問題","examples":[{"en":"The passage discusses the authorship question surrounding Shakespeare’s plays.","zh":"文章討論圍繞莎士比亞劇作的作者身份問題。"},{"en":"The authorship question is the debate about who really wrote a work.","zh":"authorship question 指關於某作品真正作者是誰的爭論。"},{"en":"A newly discovered poem may create an authorship question if no name appears on it.","zh":"如果新發現的詩沒有署名，它可能引起作者身份問題。"},{"en":"When documents are missing or unclear, an authorship question can attract researchers and readers.","zh":"當文件缺失或不清楚，作者身份問題可以吸引研究人員和讀者。"},{"en":"The phrase focuses on identity of the writer, not the quality of the writing.","zh":"這個短語重點是作者身份，而不是作品質素。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":1},{"front":"if one were asked to","meaning":"如果有人被問到","examples":[{"en":"If one were asked to name the greatest writer in English, many would choose Shakespeare.","zh":"如果有人被問到要說出英文中最偉大的作家，許多人會選擇莎士比亞。"},{"en":"If one were asked to means if someone were invited or required to answer a question.","zh":"if one were asked to 指如果有人被邀請或被要求回答某問題。"},{"en":"If one were asked to name a useful study habit, many teachers would choose regular revision.","zh":"如果有人被問到要說出一個有用學習習慣，許多老師會選擇定期溫習。"},{"en":"This structure is formal and often introduces a hypothetical question.","zh":"這個結構較正式，常用來引入假設性問題。"},{"en":"The phrase lets a writer discuss what people would probably say.","zh":"這個短語讓作者討論人們大概會怎樣回答。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":1},{"front":"the greatest writer in","meaning":"……中最偉大的作家","examples":[{"en":"Shakespeare is often described as the greatest writer in the English language.","zh":"莎士比亞常被形容為英語中最偉大的作家。"},{"en":"The greatest writer in a language or tradition means the writer many people consider the best or most important.","zh":"greatest writer in 某語言或傳統，指許多人認為最優秀或最重要的作家。"},{"en":"A country may debate who is the greatest writer in its national literature.","zh":"一個國家可能爭論誰是其民族文學中最偉大的作家。"},{"en":"Calling someone the greatest writer raises expectations about their skill, influence, and reputation.","zh":"稱某人為最偉大的作家，會令人對其技巧、影響和名聲有很高期望。"},{"en":"The phrase expresses high praise, not a neutral description.","zh":"這個短語表達高度讚賞，而不是中性描述。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":1},{"front":"few would hesitate in","meaning":"很少人會猶豫去","examples":[{"en":"Few would hesitate in naming Shakespeare as a great writer.","zh":"很少人會猶豫把莎士比亞稱為偉大作家。"},{"en":"Few would hesitate in doing something means most people would do it without uncertainty.","zh":"few would hesitate in doing something 指大多數人會毫不猶豫地做某事。"},{"en":"Few would hesitate in saying that clean water is essential for health.","zh":"很少人會猶豫說清潔食水對健康必不可少。"},{"en":"When evidence or opinion is very strong, few people hesitate before agreeing.","zh":"當證據或看法很強，人們通常不會猶豫就同意。"},{"en":"The phrase suggests broad confidence or agreement.","zh":"這個短語暗示廣泛信心或共識。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":1},{"front":"dabble in","meaning":"涉獵；略為從事","examples":[{"en":"Although Shakespeare dabbled in poetry, he is best known for his plays.","zh":"雖然莎士比亞也涉獵詩歌，但他最著名的是劇作。"},{"en":"To dabble in something means to try it lightly or occasionally, without making it one’s main activity.","zh":"dabble in something 指輕度或偶爾嘗試某事，而不是把它作為主要活動。"},{"en":"A student may dabble in photography by taking pictures on weekends.","zh":"學生可能週末拍照，略為涉獵攝影。"},{"en":"If someone only dabbles in a subject, they may know the basics but not become an expert.","zh":"如果某人只是涉獵某學科，他可能懂基本內容，但不會成為專家。"},{"en":"The phrase suggests limited involvement rather than deep commitment.","zh":"這個短語暗示有限參與，而不是深入投入。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":1},{"front":"central claim to fame","meaning":"最主要的成名原因","examples":[{"en":"Shakespeare’s central claim to fame is his plays.","zh":"莎士比亞最主要的成名原因是他的劇作。"},{"en":"A central claim to fame is the main reason someone or something is famous.","zh":"central claim to fame 指某人或某事最主要的成名原因。"},{"en":"A singer’s central claim to fame may be one song that everyone remembers.","zh":"歌手最主要的成名原因可能是一首人人記得的歌曲。"},{"en":"If a writer’s plays are studied and performed worldwide, they become the strongest reason for fame.","zh":"如果作家的劇作在全球被研究和演出，它們就成為最強的成名原因。"},{"en":"The phrase points to the core achievement behind reputation.","zh":"這個短語指出聲譽背後的核心成就。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":1},{"front":"extensively studied","meaning":"被廣泛研究","examples":[{"en":"Shakespeare’s plays are extensively studied around the world.","zh":"莎士比亞的劇作在世界各地被廣泛研究。"},{"en":"Extensively studied means examined carefully and widely by many people.","zh":"extensively studied 指被許多人仔細而廣泛地研究。"},{"en":"Climate change is extensively studied because it affects food, cities, and health.","zh":"氣候變化被廣泛研究，因為它影響食物、城市和健康。"},{"en":"When a work is extensively studied, scholars often produce many books and articles about it.","zh":"當作品被廣泛研究，學者通常會寫出許多書籍和文章。"},{"en":"The phrase suggests both depth and wide attention.","zh":"這個短語暗示研究深度和廣泛關注。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":1},{"front":"constantly performed","meaning":"經常被演出","examples":[{"en":"His plays are constantly performed in theatres.","zh":"他的劇作經常在劇院被演出。"},{"en":"Constantly performed means staged or presented again and again over time.","zh":"constantly performed 指隨時間一再被搬上舞台或呈現。"},{"en":"A popular school musical may be constantly performed because every new class enjoys it.","zh":"受歡迎的學校音樂劇可能經常被演出，因為每屆新學生都喜歡。"},{"en":"If a play is constantly performed, it remains alive for audiences rather than only existing in books.","zh":"如果劇作經常被演出，它就為觀眾保持鮮活，而不只是存在於書本中。"},{"en":"The phrase stresses repeated public performance.","zh":"這個短語強調重複的公開演出。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":1},{"front":"adapted and reinterpreted","meaning":"被改編和重新詮釋","examples":[{"en":"Shakespeare’s plays are often adapted and reinterpreted in new ways.","zh":"莎士比亞的劇作常以新方式被改編和重新詮釋。"},{"en":"Adapted and reinterpreted means changed and understood again for a new purpose, audience, or context.","zh":"adapted and reinterpreted 指為了新目的、觀眾或背景而被改動並重新理解。"},{"en":"A classic novel may be adapted and reinterpreted as a modern film set in a city.","zh":"經典小說可能被改編和重新詮釋成以現代城市為背景的電影。"},{"en":"When old stories are reinterpreted, new audiences can connect them with present-day problems.","zh":"當舊故事被重新詮釋，新觀眾可以把它們與現代問題連起來。"},{"en":"The phrase suggests creative change, not simple copying.","zh":"這個短語暗示創意改變，而不是單純複製。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":1},{"front":"in modern contexts","meaning":"在現代背景下","examples":[{"en":"His plays are reinterpreted in modern contexts.","zh":"他的劇作在現代背景下被重新詮釋。"},{"en":"In modern contexts means in present-day settings, situations, or social conditions.","zh":"in modern contexts 指在當代場景、情況或社會條件中。"},{"en":"A history lesson may explain old laws in modern contexts such as privacy and technology.","zh":"歷史課可能在私隱和科技等現代背景下解釋舊法律。"},{"en":"When a classic play is set in a modern office, its conflicts may feel more familiar.","zh":"當經典劇作以現代辦公室為背景，其衝突可能更令人熟悉。"},{"en":"The phrase connects older material with today’s world.","zh":"這個短語把舊材料與今日世界連起來。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":1},{"front":"remain as popular as ever","meaning":"仍然一如既往地受歡迎","examples":[{"en":"Shakespeare’s plays remain as popular as ever.","zh":"莎士比亞的劇作仍然一如既往地受歡迎。"},{"en":"To remain as popular as ever means to continue being just as well liked as before.","zh":"remain as popular as ever 指繼續像以前一樣受喜愛。"},{"en":"A local snack may remain as popular as ever even after many new restaurants open.","zh":"即使許多新餐廳開業，本地小食仍可能一如既往地受歡迎。"},{"en":"If a play remains popular for centuries, it speaks to feelings that many generations understand.","zh":"如果一齣劇數百年來仍受歡迎，它就觸及許多世代都理解的情感。"},{"en":"The phrase stresses lasting appeal.","zh":"這個短語強調持久吸引力。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":1},{"front":"the immediate reaction","meaning":"即時反應","examples":[{"en":"The immediate reaction is to wonder why anyone would question Shakespeare’s authorship.","zh":"即時反應是想知道為何有人會質疑莎士比亞的作者身份。"},{"en":"The immediate reaction is the first thought or feeling someone has after hearing something.","zh":"immediate reaction 指某人聽到某事後的第一個想法或感受。"},{"en":"When students hear that an exam is cancelled, their immediate reaction may be relief.","zh":"當學生聽到考試取消，他們的即時反應可能是鬆一口氣。"},{"en":"A surprising claim often creates an immediate reaction before people examine the evidence.","zh":"驚人的聲稱通常會先引起即時反應，然後人們才檢視證據。"},{"en":"The phrase focuses on the first response, not the final judgement.","zh":"這個短語重點是第一反應，而不是最終判斷。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":2},{"front":"wonder why","meaning":"想知道為何","examples":[{"en":"Many readers wonder why anyone would ask whether Shakespeare wrote the plays.","zh":"許多讀者想知道為何有人會問莎士比亞是否寫了這些劇作。"},{"en":"To wonder why means to feel curious or puzzled about the reason for something.","zh":"wonder why 指對某事原因感到好奇或困惑。"},{"en":"A student may wonder why a correct-looking answer was marked wrong.","zh":"學生可能想知道為何看似正確的答案被評為錯。"},{"en":"People wonder why a debate exists when the usual answer seems obvious.","zh":"當一般答案看起來明顯，人們會想知道為何仍有爭論存在。"},{"en":"The phrase introduces a question about reasons.","zh":"這個短語引入關於原因的問題。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":2},{"front":"documentary evidence","meaning":"文獻證據；文件證據","examples":[{"en":"There is little documentary evidence of Shakespeare’s life.","zh":"關於莎士比亞生平的文獻證據很少。"},{"en":"Documentary evidence means proof found in written records, official papers, or documents.","zh":"documentary evidence 指在書面紀錄、官方文件或文獻中找到的證據。"},{"en":"Birth records, contracts, letters, and court papers can be documentary evidence.","zh":"出生記錄、合約、信件和法庭文件都可以是文獻證據。"},{"en":"If documentary evidence is limited, historians must be careful about strong claims.","zh":"如果文獻證據有限，歷史學家就必須小心作出強烈聲稱。"},{"en":"The phrase refers to recorded proof, not personal guesses.","zh":"這個短語指有紀錄的證明，而不是個人猜測。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":2},{"front":"what does exist","meaning":"確實存在的資料","examples":[{"en":"What does exist identifies Shakespeare as the author.","zh":"確實存在的資料把莎士比亞確認為作者。"},{"en":"What does exist means the evidence or information that is actually available.","zh":"what does exist 指實際可取得的證據或資訊。"},{"en":"A teacher may say that many records are missing, but what does exist supports the student’s explanation.","zh":"老師可能說許多記錄遺失了，但確實存在的資料支持學生的解釋。"},{"en":"When evidence is limited, what does exist becomes especially important.","zh":"當證據有限，確實存在的資料就特別重要。"},{"en":"The phrase contrasts missing evidence with available evidence.","zh":"這個短語把缺失證據與現有證據作對比。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":2},{"front":"unequivocally identify someone as","meaning":"明確地確認某人為","examples":[{"en":"The existing evidence unequivocally identifies Shakespeare as the author.","zh":"現有證據明確地確認莎士比亞為作者。"},{"en":"To unequivocally identify someone as something means to name them clearly and without ambiguity.","zh":"unequivocally identify someone as something 指清楚而沒有歧義地指出某人是某身份。"},{"en":"A passport unequivocally identifies a traveller as the person named on the document.","zh":"護照明確地確認旅客為文件上所列的人。"},{"en":"If records unequivocally identify an author, alternative theories need very strong evidence.","zh":"如果記錄明確確認作者，其他理論就需要非常強的證據。"},{"en":"The phrase stresses clarity and certainty.","zh":"這個短語強調清晰和確定性。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":2},{"front":"the author of","meaning":"……的作者","examples":[{"en":"The documents identify Shakespeare as the author of the plays.","zh":"這些文件確認莎士比亞為這些劇作的作者。"},{"en":"The author of a work is the person who wrote it.","zh":"author of a work 指寫出某作品的人。"},{"en":"Students must name the author of a book when they write a proper reference.","zh":"學生寫正式引用時，必須寫出一本書的作者。"},{"en":"If a document names someone as the author, it becomes important evidence in an authorship debate.","zh":"如果文件把某人列為作者，它就成為作者身份爭論中的重要證據。"},{"en":"The phrase links a person with a written work.","zh":"這個短語把人物與書面作品連起來。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":2},{"front":"title pages","meaning":"書名頁","examples":[{"en":"Shakespeare’s name appears on the title pages of some publications.","zh":"莎士比亞的名字出現在一些出版物的書名頁上。"},{"en":"Title pages are the first pages of books or publications that show the title, author, and publication details.","zh":"title pages 指書本或出版物中顯示書名、作者和出版資料的開首頁面。"},{"en":"A student checks the title page to find the author and publisher of a book.","zh":"學生查看書名頁，以找出作者和出版社。"},{"en":"If a name appears on title pages, it gives visible evidence of authorship.","zh":"如果名字出現在書名頁上，它提供可見的作者身份證據。"},{"en":"The phrase refers to a specific part of printed works.","zh":"這個短語指印刷作品中的特定部分。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":2},{"front":"printing orders","meaning":"印刷訂單","examples":[{"en":"His name appears in printing orders and theatrical documents.","zh":"他的名字出現在印刷訂單和戲劇文件中。"},{"en":"Printing orders are official instructions or records related to producing printed books or texts.","zh":"printing orders 指與印刷書籍或文本相關的官方指示或紀錄。"},{"en":"A publisher may keep printing orders to show how many copies were requested.","zh":"出版社可能保存印刷訂單，以顯示要求印刷多少本。"},{"en":"If a writer’s name appears in printing orders, it can support the record of authorship.","zh":"如果作家名字出現在印刷訂單中，它可以支持作者身份記錄。"},{"en":"The phrase belongs to the world of publishing and document records.","zh":"這個短語屬於出版和文件紀錄領域。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":2},{"front":"theatrical documents","meaning":"戲劇文件","examples":[{"en":"Theatrical documents mention Shakespeare as the author.","zh":"戲劇文件提到莎士比亞為作者。"},{"en":"Theatrical documents are records connected with plays, theatres, actors, or performances.","zh":"theatrical documents 指與劇作、劇院、演員或演出相關的紀錄。"},{"en":"A theatre may keep documents about scripts, payments, casting, and performance dates.","zh":"劇院可能保存劇本、付款、選角和演出日期等文件。"},{"en":"If theatrical documents name an author, they become evidence about who wrote the play.","zh":"如果戲劇文件列出作者，它們就成為誰寫該劇的證據。"},{"en":"The phrase refers to records from the theatre world.","zh":"這個短語指來自戲劇界的紀錄。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":2},{"front":"contemporary commentators","meaning":"同時代評論者","examples":[{"en":"Contemporary commentators also mention Shakespeare.","zh":"同時代評論者也提到莎士比亞。"},{"en":"Contemporary commentators are people from the same period who wrote or spoke about events and people.","zh":"contemporary commentators 指來自同一時期、曾書寫或談論事件和人物的人。"},{"en":"Modern historians value contemporary commentators because they lived close to the events described.","zh":"現代歷史學家重視同時代評論者，因為他們生活在所描述事件附近。"},{"en":"If commentators from Shakespeare’s time mention him as a writer, their remarks support the historical record.","zh":"如果莎士比亞時代的評論者提到他是作家，他們的說法就支持歷史記錄。"},{"en":"The phrase means witnesses or observers from the period, not modern critics.","zh":"這個短語指該時期的見證者或觀察者，而不是現代評論家。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":2},{"front":"fellow playwright","meaning":"同行劇作家","examples":[{"en":"A fellow playwright referred to Shakespeare as a writer.","zh":"一位同行劇作家把莎士比亞稱為作家。"},{"en":"A fellow playwright is another person who writes plays and belongs to the same profession.","zh":"fellow playwright 指另一位同樣寫劇本、屬於同一專業的人。"},{"en":"A fellow teacher may understand classroom problems better than someone outside education.","zh":"同行教師可能比教育界外的人更理解課室問題。"},{"en":"If a fellow playwright recognises someone as a writer, that comment can carry professional weight.","zh":"如果同行劇作家承認某人是作家，該評論可以有專業分量。"},{"en":"The phrase stresses shared occupation.","zh":"這個短語強調共同職業。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":2},{"front":"publicly and in private memoirs","meaning":"在公開場合和私人回憶錄中","examples":[{"en":"Shakespeare was mentioned both publicly and in private memoirs.","zh":"莎士比亞在公開場合和私人回憶錄中都被提及。"},{"en":"Publicly and in private memoirs means in open records or statements and also in personal written memories.","zh":"publicly and in private memoirs 指在公開紀錄或言論中，以及私人書面回憶中。"},{"en":"A famous teacher may be praised publicly and in private memoirs by former students.","zh":"著名老師可能在公開場合和前學生私人回憶錄中都受到讚揚。"},{"en":"If a person appears in both public and private sources, the evidence becomes broader.","zh":"如果某人同時出現在公開和私人來源中，證據就更廣泛。"},{"en":"The phrase contrasts open recognition with personal recollection.","zh":"這個短語把公開認可與個人回憶作對比。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":3},{"front":"private memoirs","meaning":"私人回憶錄","examples":[{"en":"Some references to Shakespeare appear in private memoirs.","zh":"一些對莎士比亞的提及出現在私人回憶錄中。"},{"en":"Private memoirs are personal written accounts of memories and experiences.","zh":"private memoirs 指個人書寫的記憶和經歷記錄。"},{"en":"A retired doctor may write private memoirs about patients, hospitals, and public health changes.","zh":"退休醫生可能寫私人回憶錄，記錄病人、醫院和公共衛生變化。"},{"en":"Memoirs can preserve details that official documents do not record.","zh":"回憶錄可以保存官方文件沒有記錄的細節。"},{"en":"The phrase refers to personal life writing, not formal government records.","zh":"這個短語指個人生活書寫，而不是正式政府記錄。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":3},{"front":"in a way consistent with","meaning":"以與……一致的方式","examples":[{"en":"The references describe Shakespeare in a way consistent with his being the author.","zh":"這些提及以與莎士比亞是作者這一點一致的方式描述他。"},{"en":"In a way consistent with something means in a manner that fits or agrees with that idea.","zh":"in a way consistent with something 指以符合或配合某想法的方式。"},{"en":"A student’s careful notes are consistent with her being well prepared for the exam.","zh":"學生仔細的筆記與她為考試準備充分這一點一致。"},{"en":"If several records describe someone as a writer, that is consistent with the claim that he wrote the works.","zh":"如果多項紀錄把某人描述為作家，這與他寫了那些作品的聲稱一致。"},{"en":"The phrase suggests agreement, not necessarily absolute proof by itself.","zh":"這個短語暗示相符，但本身不一定是絕對證明。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":3},{"front":"consequently","meaning":"因此","examples":[{"en":"Consequently, no one doubted Shakespeare’s authorship for hundreds of years.","zh":"因此，數百年來沒有人懷疑莎士比亞的作者身份。"},{"en":"Consequently means as a result.","zh":"consequently 指因此或結果是。"},{"en":"The school failed to inform parents; consequently, many students arrived at the wrong time.","zh":"學校沒有通知家長；因此，許多學生在錯誤時間到達。"},{"en":"When evidence seems clear, people may consequently stop questioning the matter.","zh":"當證據看似清楚，人們因此可能停止質疑此事。"},{"en":"The word links a cause with its result.","zh":"這個詞把原因與結果連起來。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":3},{"front":"hold doubts on","meaning":"對……存疑","examples":[{"en":"For centuries, people held no serious doubts on the matter.","zh":"數百年來，人們對此事沒有嚴重疑問。"},{"en":"To hold doubts on something means to feel uncertain or suspicious about it.","zh":"hold doubts on something 指對某事感到不確定或懷疑。"},{"en":"Parents may hold doubts on a school policy if the reasons are not explained.","zh":"如果原因沒有被解釋，家長可能對學校政策存疑。"},{"en":"If documents are clear, fewer people hold doubts about the official account.","zh":"如果文件清楚，較少人會對官方說法存疑。"},{"en":"The phrase is formal and means having doubts about an issue.","zh":"這個短語較正式，意思是對某議題有疑問。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":3},{"front":"any doubts whatsoever","meaning":"任何疑問","examples":[{"en":"No one held any doubts whatsoever about Shakespeare’s authorship.","zh":"沒有人對莎士比亞的作者身份有任何疑問。"},{"en":"Any doubts whatsoever means even the smallest doubts at all.","zh":"any doubts whatsoever 指哪怕最小的疑問也沒有。"},{"en":"If a teacher gives clear instructions, students should not have any doubts whatsoever about the deadline.","zh":"如果老師給出清楚指示，學生對截止日期應不會有任何疑問。"},{"en":"The phrase strongly denies the existence of uncertainty.","zh":"這個短語強烈否定不確定性的存在。"},{"en":"It is more emphatic than simply saying no doubts.","zh":"它比單純說 no doubts 更強調。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":3},{"front":"on the matter","meaning":"關於此事","examples":[{"en":"For hundreds of years, no one doubted Shakespeare on the matter.","zh":"數百年來，沒有人在此事上懷疑莎士比亞。"},{"en":"On the matter means about that particular issue.","zh":"on the matter 指關於該特定議題。"},{"en":"The school will make a decision on the matter after meeting parents.","zh":"學校會在與家長會面後就此事作出決定。"},{"en":"If experts agree on the matter, the public may accept the conclusion more easily.","zh":"如果專家在此事上意見一致，公眾可能更容易接受結論。"},{"en":"The phrase points back to the issue being discussed.","zh":"這個短語指回正在討論的問題。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":3},{"front":"the matter would have rested there","meaning":"事情本會就此結束","examples":[{"en":"The matter would have rested there if Shakespeare’s reputation had not grown so greatly.","zh":"如果莎士比亞的名聲沒有大幅增長，事情本會就此結束。"},{"en":"The matter would have rested there means the issue would have ended without further debate.","zh":"matter would have rested there 指事情本來會停止，不再有進一步爭論。"},{"en":"A small complaint would have rested there if no new evidence had appeared.","zh":"如果沒有新證據出現，小投訴本會就此結束。"},{"en":"When later fame makes people rethink old records, a settled matter can become controversial again.","zh":"當後來名聲令人重新思考舊記錄，已定論的事情也可能再次變得具爭議。"},{"en":"The phrase describes a debate that could have stopped.","zh":"這個短語描述一場本可以停止的爭論。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":3},{"front":"posthumous reputation","meaning":"死後名聲","examples":[{"en":"Shakespeare’s posthumous reputation reached extraordinary heights.","zh":"莎士比亞的死後名聲達到非凡高度。"},{"en":"Posthumous reputation is the fame or respect someone receives after death.","zh":"posthumous reputation 指某人死後得到的名聲或尊重。"},{"en":"Some artists become more famous after death, so their posthumous reputation grows.","zh":"有些藝術家死後變得更有名，所以死後名聲增長。"},{"en":"A rising posthumous reputation can make later generations study a person more intensely.","zh":"不斷上升的死後名聲可以令後世更深入研究某人。"},{"en":"The phrase focuses on reputation after life, not during life.","zh":"這個短語重點是死後聲譽，而不是在世時聲譽。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":3},{"front":"reach lofty heights","meaning":"達到崇高地位","examples":[{"en":"His reputation reached such lofty heights that doubts began to appear.","zh":"他的聲譽達到如此崇高地位，以致疑問開始出現。"},{"en":"To reach lofty heights means to become extremely high in status, fame, or achievement.","zh":"reach lofty heights 指在地位、名聲或成就上達到極高水平。"},{"en":"A small company may reach lofty heights if its product becomes famous worldwide.","zh":"如果小公司產品全球聞名，它可能達到崇高地位。"},{"en":"When a reputation becomes extraordinary, people may question whether one person could deserve it all.","zh":"當名聲變得非凡，人們可能質疑一個人是否真的配得上所有成就。"},{"en":"The phrase suggests very elevated status.","zh":"這個短語暗示非常高的地位。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":3},{"front":"widespread acceptance of","meaning":"對……的廣泛接受","examples":[{"en":"The widespread acceptance of Shakespeare’s genius led to new questions.","zh":"對莎士比亞天才的廣泛接受引發了新問題。"},{"en":"Widespread acceptance of something means many people have come to believe or agree with it.","zh":"widespread acceptance of something 指許多人開始相信或同意某事。"},{"en":"Widespread acceptance of online learning grew after more schools used it successfully.","zh":"在更多學校成功使用網上學習後，人們對它的廣泛接受增加了。"},{"en":"When a belief becomes widely accepted, people may start examining its implications.","zh":"當某信念被廣泛接受，人們可能開始檢視其含義。"},{"en":"The phrase stresses broad agreement across many people.","zh":"這個短語強調許多人之間的廣泛同意。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":3},{"front":"dramatic genius","meaning":"戲劇天才","examples":[{"en":"Many people came to accept Shakespeare’s dramatic genius.","zh":"許多人開始接受莎士比亞的戲劇天才。"},{"en":"Dramatic genius is exceptional talent in writing or creating drama.","zh":"dramatic genius 指在寫作或創作戲劇方面的非凡才華。"},{"en":"A playwright shows dramatic genius when characters, conflict, and language remain powerful for centuries.","zh":"當劇作家的角色、衝突和語言數百年後仍具力量，他就展現戲劇天才。"},{"en":"Belief in Shakespeare’s dramatic genius made some critics wonder about his background and education.","zh":"對莎士比亞戲劇天才的相信，令一些評論者質疑他的背景和教育。"},{"en":"The phrase praises extraordinary ability in theatre.","zh":"這個短語讚揚戲劇方面的非凡能力。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":4},{"front":"apparent inconsistencies","meaning":"表面上的不一致之處","examples":[{"en":"Some readers perceived apparent inconsistencies in Shakespeare’s life story.","zh":"一些讀者在莎士比亞生平故事中察覺到表面上的不一致之處。"},{"en":"Apparent inconsistencies are details that seem not to fit together, even if they may later be explained.","zh":"apparent inconsistencies 指看起來不相符的細節，即使之後可能被解釋。"},{"en":"A student’s timetable may show apparent inconsistencies if two classes seem to happen at the same time.","zh":"如果兩堂課看似同時發生，學生時間表可能顯示表面上的不一致。"},{"en":"When records are incomplete, apparent inconsistencies can grow into larger doubts.","zh":"當記錄不完整，表面上的不一致可能發展成更大疑問。"},{"en":"The phrase means seeming contradictions, not necessarily real contradictions.","zh":"這個短語指看似矛盾，而不一定是真正矛盾。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":4},{"front":"be perceived","meaning":"被察覺","examples":[{"en":"Apparent inconsistencies were perceived by later critics.","zh":"表面上的不一致之處被後來評論者察覺。"},{"en":"To be perceived means to be noticed, understood, or interpreted in a certain way.","zh":"be perceived 指被注意、理解或以某種方式詮釋。"},{"en":"A quiet student may be perceived as unfriendly even if he is only shy.","zh":"安靜的學生可能被視為不友善，即使他只是害羞。"},{"en":"If a lack of documents is perceived as suspicious, people may begin forming theories.","zh":"如果缺乏文件被視為可疑，人們可能開始形成理論。"},{"en":"The phrase focuses on how something is seen or interpreted.","zh":"這個短語重點是某事如何被看見或理解。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":4},{"front":"chief among these","meaning":"其中最主要的是","examples":[{"en":"Chief among these doubts was the question of Shakespeare’s background.","zh":"這些疑問之中最主要的是莎士比亞背景的問題。"},{"en":"Chief among these means the most important among the things just mentioned.","zh":"chief among these 指剛提到的事物之中最重要的一個。"},{"en":"Many problems affected the project; chief among these was the lack of time.","zh":"許多問題影響了項目；其中最主要的是時間不足。"},{"en":"When several doubts exist, the writer can use this phrase to highlight the main one.","zh":"當存在多個疑問，作者可以用這個短語突出主要疑問。"},{"en":"The phrase signals priority or importance.","zh":"這個短語表示優先性或重要性。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":4},{"front":"originate from","meaning":"源自","examples":[{"en":"Some people wondered how such literature could originate from Shakespeare.","zh":"有些人想知道這樣的文學作品怎可能源自莎士比亞。"},{"en":"To originate from someone or somewhere means to come from that source.","zh":"originate from someone or somewhere 指來自某人或某處這個來源。"},{"en":"A family recipe may originate from a grandmother who cooked it for festivals.","zh":"家庭食譜可能源自一位在節日烹調它的祖母。"},{"en":"If a work seems highly educated, critics may ask whether it could originate from a less documented background.","zh":"如果作品看似極有學問，評論者可能問它是否能源自記錄較少的背景。"},{"en":"The phrase focuses on source or beginning.","zh":"這個短語重點是來源或起點。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":4},{"front":"be viewed as","meaning":"被視為","examples":[{"en":"Shakespeare was viewed by some as a humble country figure.","zh":"有些人把莎士比亞視為出身平凡的鄉間人物。"},{"en":"To be viewed as something means to be seen or regarded in that way.","zh":"be viewed as something 指被看作或被認為是某種身份或樣子。"},{"en":"A strict teacher may be viewed as unfair by students who do not understand the rules.","zh":"如果學生不理解規則，嚴格老師可能被視為不公平。"},{"en":"If someone is viewed as ordinary, people may underestimate what they can achieve.","zh":"如果某人被視為普通，人們可能低估他能取得的成就。"},{"en":"The phrase describes perception, not necessarily truth.","zh":"這個短語描述看法，而不一定是真相。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":4},{"front":"humble","meaning":"卑微的；出身平凡的","examples":[{"en":"Some critics described Shakespeare as a humble man from Stratford.","zh":"一些評論者把莎士比亞描述為來自斯特拉特福的出身平凡男子。"},{"en":"Humble can mean having a low social position or modest background.","zh":"humble 可以指社會地位較低或背景樸素。"},{"en":"A successful business owner may come from humble beginnings in a small village.","zh":"成功企業家可能出身平凡，來自小村莊。"},{"en":"If a writer has a humble background, some unfair critics may wrongly assume limited ability.","zh":"如果作家背景平凡，一些不公平評論者可能錯誤假設其能力有限。"},{"en":"The word can be neutral, positive, or dismissive depending on context.","zh":"這個詞可按語境帶中性、正面或貶低意味。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":4},{"front":"ill-educated","meaning":"教育程度低的","examples":[{"en":"Some anti-Stratfordians believed Shakespeare was ill-educated.","zh":"一些反斯特拉特福派相信莎士比亞教育程度低。"},{"en":"Ill-educated means having little formal education or poor educational training.","zh":"ill-educated 指接受很少正規教育或教育訓練不足。"},{"en":"A person can be ill-educated in school subjects but still be intelligent and observant.","zh":"一個人在學校科目上教育程度不高，但仍可以聰明和善於觀察。"},{"en":"Critics may use the label ill-educated to question whether someone could write complex works.","zh":"評論者可能使用教育程度低這個標籤，質疑某人是否能寫出複雜作品。"},{"en":"The word can sound dismissive, so it should be used carefully.","zh":"這個詞可能帶貶低意味，因此應小心使用。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":4},{"front":"country bumpkin","meaning":"鄉巴佬；土包子","examples":[{"en":"Critics unfairly dismissed Shakespeare as a country bumpkin.","zh":"評論者不公平地把莎士比亞貶低為鄉巴佬。"},{"en":"A country bumpkin is an insulting term for someone seen as simple, rural, and unsophisticated.","zh":"country bumpkin 是侮辱性用語，指被視為簡單、鄉下和不夠世故的人。"},{"en":"Calling a new student a country bumpkin because he comes from a village is rude and unfair.","zh":"因為新學生來自村莊就稱他為土包子，是粗魯而不公平的。"},{"en":"Such labels can make people underestimate someone’s intelligence or creativity.","zh":"這類標籤可以令人低估某人的智慧或創意。"},{"en":"The phrase is derogatory and should not be used politely.","zh":"這個短語帶貶義，不應在禮貌場合使用。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":4},{"front":"bawdy stage entrepreneur","meaning":"粗俗的劇場企業家","examples":[{"en":"Some critics saw Shakespeare as a bawdy stage entrepreneur rather than a great author.","zh":"一些評論者把莎士比亞看成粗俗的劇場企業家，而不是偉大作者。"},{"en":"A bawdy stage entrepreneur is a theatre businessperson associated with crude humour and commercial entertainment.","zh":"bawdy stage entrepreneur 指與粗俗幽默和商業娛樂相關的劇場商人。"},{"en":"A theatre owner who sells noisy comic shows may be described this way by snobbish critics.","zh":"出售吵鬧喜劇表演的劇院老闆，可能被勢利評論者這樣描述。"},{"en":"The phrase suggests critics viewed Shakespeare as practical and vulgar, not literary and refined.","zh":"這個短語暗示評論者把莎士比亞看成實際和粗俗，而非文學和精緻。"},{"en":"It is a loaded description, not a neutral job title.","zh":"這是帶有立場的描述，而不是中性職稱。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":4},{"front":"about whom so little was known","meaning":"關於其人所知甚少","examples":[{"en":"Some people questioned how a man about whom so little was known could write such plays.","zh":"有些人質疑一個關於其人所知甚少的人怎能寫出這些劇作。"},{"en":"About whom so little was known means people had very little information about that person.","zh":"about whom so little was known 指人們對該人掌握的資訊非常少。"},{"en":"A mysterious artist about whom so little is known may attract rumours and theories.","zh":"一位所知甚少的神秘藝術家可能吸引傳聞和理論。"},{"en":"When little is known about a writer’s education, critics may fill the gaps with speculation.","zh":"當人們對作家教育所知甚少，評論者可能用猜測填補空白。"},{"en":"The phrase highlights missing biographical information.","zh":"這個短語突出傳記資料缺失。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":4},{"front":"documentary details","meaning":"文獻中的細節","examples":[{"en":"Documentary details of Shakespeare’s schooling are almost nonexistent.","zh":"關於莎士比亞學校教育的文獻細節幾乎不存在。"},{"en":"Documentary details are specific facts found in written records or documents.","zh":"documentary details 指在書面記錄或文件中找到的具體事實。"},{"en":"A school archive may provide documentary details about old students’ exams and attendance.","zh":"學校檔案可能提供舊學生考試和出席紀錄的文獻細節。"},{"en":"If documentary details are missing, historians cannot confirm every part of a life story.","zh":"如果文獻細節缺失，歷史學家不能確認人生故事的每一部分。"},{"en":"The phrase focuses on specific recorded information.","zh":"這個短語重點是具體記錄資料。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":5},{"front":"schooling and upbringing","meaning":"學校教育和成長背景","examples":[{"en":"Critics focus on the lack of evidence about Shakespeare’s schooling and upbringing.","zh":"評論者集中於缺乏關於莎士比亞學校教育和成長背景的證據。"},{"en":"Schooling and upbringing mean a person’s formal education and the way they were raised.","zh":"schooling and upbringing 指一個人的正規教育和被養育方式。"},{"en":"A child’s schooling and upbringing can shape language, confidence, and social habits.","zh":"孩子的學校教育和成長背景可以塑造語言、信心和社交習慣。"},{"en":"If little is known about someone’s schooling and upbringing, people may debate how they developed their skills.","zh":"如果人們對某人的學校教育和成長背景所知甚少，他們可能爭論其技能如何形成。"},{"en":"The phrase covers both school experience and family background.","zh":"這個短語涵蓋學校經驗和家庭背景。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":5},{"front":"market town","meaning":"集鎮；市鎮","examples":[{"en":"Shakespeare grew up in the small market town of Stratford-upon-Avon.","zh":"莎士比亞在埃文河畔斯特拉特福這個小集鎮長大。"},{"en":"A market town is a town where people from surrounding areas traditionally came to buy and sell goods.","zh":"market town 指周邊地區的人傳統上會來買賣貨物的城鎮。"},{"en":"A market town may have shops, inns, traders, and weekly markets.","zh":"集鎮可能有商店、旅館、商人和每週市場。"},{"en":"Growing up in a market town could expose a child to many voices, stories, and social types.","zh":"在集鎮長大，可能讓孩子接觸許多聲音、故事和社會類型。"},{"en":"The phrase describes a local economic centre, not a large city.","zh":"這個短語描述地方經濟中心，而不是大城市。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":5},{"front":"Stratford-upon-Avon","meaning":"埃文河畔斯特拉特福","examples":[{"en":"Shakespeare’s upbringing took place in Stratford-upon-Avon.","zh":"莎士比亞的成長發生在埃文河畔斯特拉特福。"},{"en":"Stratford-upon-Avon is the English town traditionally associated with Shakespeare’s birth and early life.","zh":"Stratford-upon-Avon 是傳統上與莎士比亞出生和早年生活相關的英格蘭城鎮。"},{"en":"A biography may mention Stratford-upon-Avon to explain Shakespeare’s family background.","zh":"傳記可能提到埃文河畔斯特拉特福，以解釋莎士比亞的家庭背景。"},{"en":"Because it is linked to Shakespeare, the town became important in literary tourism.","zh":"因為它與莎士比亞有關，該鎮在文學旅遊中變得重要。"},{"en":"The phrase is a place name and should be treated as a proper noun.","zh":"這個短語是地名，應視為專有名詞。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":5},{"front":"virtually nonexistent","meaning":"幾乎不存在的","examples":[{"en":"Documents about Shakespeare’s early education are virtually nonexistent.","zh":"關於莎士比亞早期教育的文件幾乎不存在。"},{"en":"Virtually nonexistent means almost not existing at all.","zh":"virtually nonexistent 指幾乎完全不存在。"},{"en":"In a small village, public transport may be virtually nonexistent after midnight.","zh":"在小村莊，午夜後公共交通可能幾乎不存在。"},{"en":"If records are virtually nonexistent, researchers must avoid pretending to know too much.","zh":"如果記錄幾乎不存在，研究人員必須避免假裝知道太多。"},{"en":"The phrase is stronger than rare and means almost absent.","zh":"這個短語比 rare 更強，意思是幾乎沒有。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":5},{"front":"there is no evidence that","meaning":"沒有證據顯示","examples":[{"en":"There is no evidence that Shakespeare’s surviving children received a good education.","zh":"沒有證據顯示莎士比亞尚在人世的子女接受過良好教育。"},{"en":"There is no evidence that means no available proof shows the claim is true.","zh":"there is no evidence that 指沒有可用證據顯示某聲稱為真。"},{"en":"There is no evidence that a student cheated if cameras and papers show nothing suspicious.","zh":"如果攝錄和試卷都沒有可疑之處，就沒有證據顯示學生作弊。"},{"en":"Lack of evidence does not always prove the opposite, but it weakens a claim.","zh":"缺乏證據不一定證明相反，但會削弱某聲稱。"},{"en":"The phrase is useful when separating facts from assumptions.","zh":"這個短語適合用來區分事實與假設。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":5},{"front":"surviving children","meaning":"尚在人世的子女","examples":[{"en":"There is little evidence about the education of Shakespeare’s surviving children.","zh":"關於莎士比亞尚在人世子女的教育，證據很少。"},{"en":"Surviving children are children who were still alive after others may have died.","zh":"surviving children 指在其他子女可能已去世後仍然活着的子女。"},{"en":"A family history may record only the surviving children because earlier children died young.","zh":"家族史可能只記錄尚在人世的子女，因為早夭子女已去世。"},{"en":"Studying surviving children can give clues about a family’s values and resources.","zh":"研究尚在人世的子女可以提供家庭價值和資源的線索。"},{"en":"The phrase is historical or formal and refers to children who lived on.","zh":"這個短語較歷史或正式，指繼續存活的子女。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":5},{"front":"receive a good education","meaning":"接受良好教育","examples":[{"en":"Critics claim that his children did not receive a good education.","zh":"評論者聲稱他的子女沒有接受良好教育。"},{"en":"To receive a good education means to have useful, high-quality teaching and learning opportunities.","zh":"receive a good education 指得到有用而高質素的教學和學習機會。"},{"en":"A child may receive a good education through strong teachers, books, and family support.","zh":"孩子可以透過優秀老師、書本和家庭支援接受良好教育。"},{"en":"If children do not receive a good education, critics may question the family’s priorities or resources.","zh":"如果子女沒有接受良好教育，評論者可能質疑家庭的優先事項或資源。"},{"en":"The phrase focuses on quality of learning, not only school attendance.","zh":"這個短語重點是學習質素，而不只是上學。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":5},{"front":"acquire basic literacy skills","meaning":"掌握基本讀寫能力","examples":[{"en":"Some of Shakespeare’s children may not have acquired basic literacy skills.","zh":"莎士比亞的一些子女可能沒有掌握基本讀寫能力。"},{"en":"To acquire basic literacy skills means to learn simple reading and writing abilities.","zh":"acquire basic literacy skills 指學會簡單閱讀和寫作能力。"},{"en":"Children acquire basic literacy skills when they can read signs, write their names, and understand short texts.","zh":"當孩子能讀標誌、寫自己的名字和理解短文，他們就是掌握基本讀寫能力。"},{"en":"Without basic literacy skills, people may struggle with letters, contracts, and records.","zh":"沒有基本讀寫能力，人們可能難以處理信件、合約和紀錄。"},{"en":"The phrase refers to fundamental reading and writing competence.","zh":"這個短語指基本閱讀和寫作能力。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":5},{"front":"original written texts","meaning":"原始手稿文本","examples":[{"en":"No original written texts by Shakespeare have ever been found.","zh":"從未發現莎士比亞的原始手稿文本。"},{"en":"Original written texts are the first handwritten or author-produced versions of a work.","zh":"original written texts 指作品最初的手寫或作者製作版本。"},{"en":"A museum may value an original written text more than a later printed copy.","zh":"博物館可能比後來印刷本更重視原始手稿文本。"},{"en":"If no original texts survive, scholars must rely on printed editions and other records.","zh":"如果沒有原始文本存世，學者必須依靠印刷版本和其他記錄。"},{"en":"The phrase refers to primary written material, not later copies.","zh":"這個短語指一手書面材料，而不是後來副本。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":5},{"front":"surviving signatures","meaning":"保存下來的簽名","examples":[{"en":"Six surviving signatures are attributed to Shakespeare.","zh":"六個保存下來的簽名被歸於莎士比亞。"},{"en":"Surviving signatures are signatures that still exist today from the past.","zh":"surviving signatures 指從過去保存到今天仍存在的簽名。"},{"en":"A historian may compare surviving signatures to confirm whether documents were signed by the same person.","zh":"歷史學家可能比較保存下來的簽名，以確認文件是否由同一人簽署。"},{"en":"If only a few signatures survive, it is difficult to judge someone’s normal handwriting.","zh":"如果只有少數簽名存世，就很難判斷某人的正常筆跡。"},{"en":"The phrase focuses on preserved written marks of a name.","zh":"這個短語重點是被保存下來的姓名書寫痕跡。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":5},{"front":"unsteady","meaning":"不穩定的；不流暢的","examples":[{"en":"Shakespeare’s surviving signatures appear unsteady.","zh":"莎士比亞保存下來的簽名看起來不穩定。"},{"en":"Unsteady means not smooth, firm, or controlled.","zh":"unsteady 指不順暢、不穩固或不受控制。"},{"en":"A child’s handwriting may look unsteady when she first learns to write.","zh":"孩子初學寫字時，筆跡可能看起來不流暢。"},{"en":"An unsteady signature does not always prove poor literacy; age, illness, or writing tools may affect it.","zh":"不穩定的簽名不一定證明讀寫能力差；年齡、疾病或書寫工具都可能影響它。"},{"en":"The word describes shaky form or movement.","zh":"這個詞描述搖晃、不穩的形式或動作。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":6},{"front":"inconsistent style and spelling","meaning":"風格和串法不一致","examples":[{"en":"The signatures show inconsistent style and spelling.","zh":"這些簽名顯示風格和串法不一致。"},{"en":"Inconsistent style and spelling means the appearance and word forms vary instead of staying the same.","zh":"inconsistent style and spelling 指外觀和字詞形式有變化，而不是保持相同。"},{"en":"A student’s notes show inconsistent spelling if the same word is written three different ways.","zh":"如果同一個字被寫成三種不同形式，學生筆記就顯示串法不一致。"},{"en":"In old documents, inconsistent spelling may reflect the period’s loose spelling rules.","zh":"在舊文件中，串法不一致可能反映當時拼寫規則較鬆。"},{"en":"The phrase points to variation that seems irregular.","zh":"這個短語指出看似不規則的變化。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":6},{"front":"most tellingly","meaning":"對某些人而言最有說服力的是","examples":[{"en":"Most tellingly for some critics, Shakespeare’s death raised further questions.","zh":"對某些評論者而言最有說服力的是，莎士比亞的死亡引發了更多問題。"},{"en":"Most tellingly means most importantly or most revealingly as evidence.","zh":"most tellingly 指最重要地，或作為證據最能揭示問題地。"},{"en":"The student was absent all week, but most tellingly, he had not opened the online lessons either.","zh":"該學生整週缺席，但最有說服力的是，他也沒有打開網上課程。"},{"en":"Writers use this phrase before the detail they think is strongest.","zh":"作者會在他們認為最強的細節前使用這個短語。"},{"en":"The phrase signals that the next point is especially persuasive to some people.","zh":"這個短語表示下一點對某些人特別有說服力。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":6},{"front":"the circumstances of","meaning":"……的情況","examples":[{"en":"The circumstances of Shakespeare’s death puzzled later critics.","zh":"莎士比亞死亡的情況令後來評論者困惑。"},{"en":"The circumstances of an event are the conditions, details, and situation surrounding it.","zh":"circumstances of an event 指圍繞某事件的條件、細節和情況。"},{"en":"Police may investigate the circumstances of an accident before deciding what caused it.","zh":"警方可能先調查意外的情況，再決定原因。"},{"en":"When the circumstances of a death are unclear, later readers may form questions.","zh":"當死亡情況不清楚，後來讀者可能提出問題。"},{"en":"The phrase focuses on surrounding details, not just the event itself.","zh":"這個短語重點是周邊細節，而不只是事件本身。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":6},{"front":"firstly","meaning":"首先","examples":[{"en":"Firstly, critics point to Shakespeare’s will.","zh":"首先，評論者指出莎士比亞的遺囑。"},{"en":"Firstly means first in a list of points or reasons.","zh":"firstly 指在一系列要點或原因中的第一點。"},{"en":"Firstly, students should read the question carefully before writing an answer.","zh":"首先，學生應仔細閱讀題目，然後才寫答案。"},{"en":"Writers use firstly to organise an argument clearly.","zh":"作者使用 firstly 來清楚組織論點。"},{"en":"The word signals that more points may follow.","zh":"這個詞表示後面可能還有更多要點。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":6},{"front":"will","meaning":"遺囑","examples":[{"en":"Shakespeare’s will made no mention of his literary papers.","zh":"莎士比亞的遺囑沒有提及他的文學手稿。"},{"en":"A will is a legal document that states what should happen to a person’s property after death.","zh":"will 在這裡指法律文件，說明一個人死後財產應如何處理。"},{"en":"A parent may write a will to say who should receive the house, savings, and personal belongings.","zh":"父母可能寫遺囑，說明誰應得到房屋、儲蓄和個人財物。"},{"en":"If a writer’s will does not mention manuscripts, some critics may find that surprising.","zh":"如果作家的遺囑沒有提及手稿，一些評論者可能覺得奇怪。"},{"en":"The word here means 遺囑, not future intention.","zh":"這裡的 will 指遺囑，而不是未來意願。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":6},{"front":"commonplace and unpoetic","meaning":"平凡而沒有詩意的","examples":[{"en":"The will was a commonplace and unpoetic document.","zh":"這份遺囑是一份平凡而沒有詩意的文件。"},{"en":"Commonplace and unpoetic means ordinary, practical, and lacking literary beauty.","zh":"commonplace and unpoetic 指普通、實用並缺乏文學美感。"},{"en":"A shopping list is usually commonplace and unpoetic, even if written by a poet.","zh":"購物清單通常平凡而沒有詩意，即使由詩人寫成。"},{"en":"Critics may find an unpoetic will surprising when it belongs to a celebrated writer.","zh":"當一份沒有詩意的遺囑屬於著名作家，評論者可能覺得奇怪。"},{"en":"The phrase contrasts everyday legal language with imaginative writing.","zh":"這個短語把日常法律語言與想像性寫作作對比。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":6},{"front":"make no mention whatsoever of","meaning":"完全沒有提及","examples":[{"en":"His will made no mention whatsoever of his unpublished writings.","zh":"他的遺囑完全沒有提及未出版作品。"},{"en":"To make no mention whatsoever of something means to say absolutely nothing about it.","zh":"make no mention whatsoever of something 指完全沒有說到某事。"},{"en":"A school notice about a trip made no mention whatsoever of lunch, so parents were confused.","zh":"學校旅行告示完全沒有提及午餐，所以家長感到困惑。"},{"en":"If an important item is not mentioned at all, people may wonder whether it existed or mattered.","zh":"如果重要項目完全沒有被提及，人們可能想知道它是否存在或是否重要。"},{"en":"The phrase strongly emphasises total absence.","zh":"這個短語強烈強調完全缺席。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":6},{"front":"a considerable body of","meaning":"大量的……","examples":[{"en":"Critics expected a considerable body of papers to be mentioned.","zh":"評論者預期遺囑會提及大量文件。"},{"en":"A considerable body of something means a large or important amount of it.","zh":"considerable body of something 指大量或重要數量的某物。"},{"en":"A researcher may collect a considerable body of evidence before publishing a study.","zh":"研究人員可能在發表研究前收集大量證據。"},{"en":"If a playwright wrote many works, people might expect a considerable body of papers to survive.","zh":"如果劇作家寫了許多作品，人們可能預期會有大量手稿保存下來。"},{"en":"The phrase suggests more than a few scattered items.","zh":"這個短語暗示不只是幾件零散物品。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":6},{"front":"reference books","meaning":"參考書","examples":[{"en":"A playwright of Shakespeare’s stature might be expected to own reference books.","zh":"具有莎士比亞這種地位的劇作家可能被預期擁有參考書。"},{"en":"Reference books are books used for checking facts, meanings, background, or information.","zh":"reference books 指用來查核事實、意思、背景或資料的書。"},{"en":"Dictionaries, encyclopaedias, and legal handbooks can be reference books.","zh":"字典、百科全書和法律手冊都可以是參考書。"},{"en":"A writer may use reference books to check history, geography, and specialised vocabulary.","zh":"作家可能使用參考書查核歷史、地理和專門詞彙。"},{"en":"The phrase refers to books used for consultation, not casual reading only.","zh":"這個短語指用來查閱的書，而不只是休閒閱讀。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":6},{"front":"miscellaneous writings","meaning":"各式各樣的作品","examples":[{"en":"His will did not mention miscellaneous writings or plays.","zh":"他的遺囑沒有提及各式各樣的作品或劇作。"},{"en":"Miscellaneous writings are various pieces of writing that do not all belong to one neat category.","zh":"miscellaneous writings 指不全屬於同一清晰類別的各種文字作品。"},{"en":"A writer’s notebook may contain poems, letters, ideas, and miscellaneous writings.","zh":"作家的筆記本可能包含詩、信件、想法和各式各樣的作品。"},{"en":"If miscellaneous writings are missing from a will, critics may wonder what happened to them.","zh":"如果各式各樣的作品沒有出現在遺囑中，評論者可能想知道它們去了哪裡。"},{"en":"The phrase means assorted written materials.","zh":"這個短語指雜項書面材料。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":6},{"front":"one would expect","meaning":"人們會預期","examples":[{"en":"One would expect a playwright to possess many papers and books.","zh":"人們會預期一位劇作家擁有許多文件和書籍。"},{"en":"One would expect means people would reasonably think something should be true.","zh":"one would expect 指人們合理地認為某事應該是真的。"},{"en":"One would expect a school library to contain dictionaries and reference books.","zh":"人們會預期學校圖書館有字典和參考書。"},{"en":"If reality differs from what one would expect, questions may arise.","zh":"如果現實與人們預期不同，問題可能出現。"},{"en":"The phrase introduces a reasonable assumption.","zh":"這個短語引入合理假設。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":7},{"front":"of Shakespeare’s stature","meaning":"具有Shakespeare這種地位的","examples":[{"en":"A writer of Shakespeare’s stature would be expected to value his papers.","zh":"具有莎士比亞這種地位的作家會被預期重視自己的文件。"},{"en":"Of Shakespeare’s stature means having Shakespeare’s level of importance, reputation, or achievement.","zh":"of Shakespeare’s stature 指具有莎士比亞那種重要性、聲譽或成就水平。"},{"en":"A scientist of Einstein’s stature would be expected to leave important records.","zh":"具有愛因斯坦這種地位的科學家會被預期留下重要紀錄。"},{"en":"When someone has such stature, ordinary gaps in documents may seem more surprising.","zh":"當某人有如此高地位，普通文件缺口可能顯得更令人驚訝。"},{"en":"The phrase highlights very high status.","zh":"這個短語突出極高地位。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":7},{"front":"be unconcerned about","meaning":"對……不關心","examples":[{"en":"Shakespeare appeared to be unconcerned about the rights to his plays.","zh":"莎士比亞似乎對其劇作權利不關心。"},{"en":"To be unconcerned about something means to seem not worried or interested in it.","zh":"be unconcerned about something 指看似不擔心或不關心某事。"},{"en":"A student who never checks deadlines appears unconcerned about grades.","zh":"從不查看截止日期的學生看似對成績不關心。"},{"en":"If a writer is unconcerned about rights, later readers may question whether he valued the works.","zh":"如果作家不關心版權，後來讀者可能質疑他是否重視那些作品。"},{"en":"The phrase suggests lack of attention or worry.","zh":"這個短語暗示缺乏注意或憂慮。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":7},{"front":"the rights to","meaning":"……的版權；權利","examples":[{"en":"The will does not discuss the rights to Shakespeare’s plays.","zh":"遺囑沒有討論莎士比亞劇作的權利。"},{"en":"The rights to a work are the legal permissions to publish, perform, sell, or control it.","zh":"rights to a work 指出版、演出、銷售或控制某作品的法律權利。"},{"en":"A musician may sell the rights to a song to a record company.","zh":"音樂人可能把歌曲版權賣給唱片公司。"},{"en":"If the rights to plays are not mentioned, people may wonder who controlled them after death.","zh":"如果劇作權利沒有被提及，人們可能想知道死後由誰控制它們。"},{"en":"The phrase refers to legal ownership or control.","zh":"這個短語指法律擁有權或控制權。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":7},{"front":"remain unpublished","meaning":"仍未出版","examples":[{"en":"Many of Shakespeare’s plays remained unpublished at that time.","zh":"當時莎士比亞許多劇作仍未出版。"},{"en":"To remain unpublished means not yet to have been printed or made publicly available.","zh":"remain unpublished 指尚未印刷或公開發布。"},{"en":"A researcher’s report may remain unpublished until the data are checked.","zh":"研究人員的報告在數據查核前可能仍未出版。"},{"en":"If plays remain unpublished, manuscripts or rights may become especially important.","zh":"如果劇作仍未出版，手稿或權利就可能特別重要。"},{"en":"The phrase describes works that still have not reached publication.","zh":"這個短語描述仍未出版的作品。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":7},{"front":"literary heritage","meaning":"文學遺產","examples":[{"en":"Critics argue that Shakespeare seemed careless about his literary heritage.","zh":"評論者認為莎士比亞似乎不重視自己的文學遺產。"},{"en":"Literary heritage is the body of writing and influence a writer leaves for later generations.","zh":"literary heritage 指作家留給後世的作品和影響。"},{"en":"A poet’s notebooks, drafts, letters, and published poems can form part of literary heritage.","zh":"詩人的筆記、草稿、信件和已出版詩作都可以構成文學遺產的一部分。"},{"en":"If a writer does not protect manuscripts, critics may say the literary heritage was neglected.","zh":"如果作家不保護手稿，評論者可能說文學遺產被忽略。"},{"en":"The phrase connects literature with inheritance and cultural memory.","zh":"這個短語把文學與繼承和文化記憶連起來。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":7},{"front":"upon his death","meaning":"在他去世時","examples":[{"en":"Upon his death, there were no public tributes to Shakespeare.","zh":"在他去世時，沒有公開致敬莎士比亞的活動。"},{"en":"Upon his death means at the time when he died or immediately after.","zh":"upon his death 指在他死亡時或死亡後不久。"},{"en":"Upon her death, the teacher’s former students wrote letters to thank her family.","zh":"在老師去世時，她的舊學生寫信感謝她的家人。"},{"en":"If no public reaction appears upon a famous person’s death, later readers may find it surprising.","zh":"如果名人去世時沒有公開反應，後來讀者可能覺得奇怪。"},{"en":"The phrase is formal and means when death occurred.","zh":"這個短語較正式，意思是死亡發生時。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":7},{"front":"eulogies","meaning":"悼詞","examples":[{"en":"There were no eulogies after Shakespeare died.","zh":"莎士比亞死後沒有悼詞。"},{"en":"Eulogies are speeches or writings that praise someone after their death.","zh":"eulogies 指人在死後讚揚他的演說或文章。"},{"en":"At a funeral, a friend may give a eulogy about the person’s kindness and achievements.","zh":"在葬禮上，朋友可能發表悼詞，講述逝者的善良和成就。"},{"en":"If no eulogies appear for a respected writer, critics may wonder why there was public silence.","zh":"如果受尊重作家沒有悼詞出現，評論者可能想知道為何公開場合沉默。"},{"en":"The word is connected with memorial praise.","zh":"這個詞與紀念性讚頌有關。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":7},{"front":"mourning notices","meaning":"哀悼公告","examples":[{"en":"The passage says there were no mourning notices after his death.","zh":"文章說他死後沒有哀悼公告。"},{"en":"Mourning notices are public announcements expressing sadness after someone dies.","zh":"mourning notices 指某人去世後表達悲傷的公開公告。"},{"en":"A newspaper may publish mourning notices for a community leader.","zh":"報紙可能為社區領袖刊登哀悼公告。"},{"en":"Mourning notices show that a death was publicly recognised and felt.","zh":"哀悼公告顯示死亡被公眾認可和感受到。"},{"en":"The phrase refers to public expressions of grief.","zh":"這個短語指公開表達哀傷的公告。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":7},{"front":"testimonies from","meaning":"來自……的證言","examples":[{"en":"There were no testimonies from those who knew Shakespeare.","zh":"沒有來自認識莎士比亞的人的證言。"},{"en":"Testimonies from people are statements or accounts given by those people as evidence or memory.","zh":"testimonies from people 指由那些人提供、作為證據或記憶的陳述。"},{"en":"A school investigation may collect testimonies from students who saw an incident.","zh":"學校調查可能收集來自目擊事件學生的證言。"},{"en":"If no testimonies come from friends or colleagues, later historians lose personal evidence.","zh":"如果沒有來自朋友或同事的證言，後來歷史學家就失去個人證據。"},{"en":"The phrase refers to spoken or written witness accounts.","zh":"這個短語指口頭或書面見證記錄。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":7},{"front":"those who knew him","meaning":"認識他的人","examples":[{"en":"No testimonies appeared from those who knew him personally.","zh":"沒有來自親自認識他的人的證言出現。"},{"en":"Those who knew him means people who had personal contact with him.","zh":"those who knew him 指與他有個人接觸的人。"},{"en":"A biography becomes richer when it includes memories from those who knew the person well.","zh":"如果傳記包括熟悉某人的人的回憶，它會更豐富。"},{"en":"If those who knew someone remain silent, later readers may have fewer personal details.","zh":"如果認識某人的人保持沉默，後來讀者就可能得到較少個人細節。"},{"en":"The phrase focuses on direct acquaintances, not distant admirers.","zh":"這個短語重點是直接認識的人，而不是遙遠崇拜者。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":7},{"front":"seem very perplexing","meaning":"似乎非常令人費解","examples":[{"en":"This silence seemed very perplexing to some critics.","zh":"這種沉默對一些評論者而言似乎非常令人費解。"},{"en":"To seem very perplexing means to appear very puzzling or difficult to explain.","zh":"seem very perplexing 指看起來非常令人困惑或難以解釋。"},{"en":"A student’s sudden absence may seem perplexing if she had perfect attendance before.","zh":"如果學生以前從不缺席，她突然缺席可能令人費解。"},{"en":"Public silence after a famous person’s death can seem strange when respect was expected.","zh":"當人們預期會有尊重表達時，名人死後的公開沉默可能顯得奇怪。"},{"en":"The phrase describes strong confusion.","zh":"這個短語描述強烈困惑。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":8},{"front":"whilst not necessarily considered","meaning":"雖然不一定被認為","examples":[{"en":"Shakespeare was respected, whilst not necessarily considered the most learned writer.","zh":"莎士比亞受到尊重，雖然不一定被認為是最博學的作家。"},{"en":"Whilst not necessarily considered means although people did not always regard someone in that particular way.","zh":"whilst not necessarily considered 指雖然人們不一定以某特定方式看待某人。"},{"en":"A teacher may be popular, whilst not necessarily considered the strictest member of staff.","zh":"老師可能受歡迎，雖然不一定被認為是最嚴格的員工。"},{"en":"Someone can be respected even if they are not seen as the most polished or educated person.","zh":"一個人即使不被視為最圓熟或最有學問，仍可以受到尊重。"},{"en":"The phrase creates a careful contrast.","zh":"這個短語建立謹慎對比。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":8},{"front":"polished","meaning":"圓熟的；精緻的","examples":[{"en":"His peers may not have considered him the most polished playwright.","zh":"他的同輩可能沒有認為他是最圓熟的劇作家。"},{"en":"Polished means refined, elegant, skilled, and carefully finished.","zh":"polished 指精緻、優雅、熟練並經仔細打磨。"},{"en":"A polished speech sounds smooth because the speaker has practised and edited it.","zh":"圓熟的演講聽起來流暢，因為演講者已練習和修改。"},{"en":"A writer may be powerful without being the most polished in style.","zh":"作家可以很有力量，即使風格不是最精緻。"},{"en":"The word can describe language, performance, manners, or artistic skill.","zh":"這個詞可描述語言、表演、禮儀或藝術技巧。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":8},{"front":"learned","meaning":"博學的","examples":[{"en":"He was not necessarily considered the most learned writer by his peers.","zh":"他不一定被同輩認為是最博學的作家。"},{"en":"Learned means highly educated or having deep knowledge.","zh":"learned 指受過高深教育或有深厚知識。"},{"en":"A learned professor may know several languages and many historical sources.","zh":"博學的教授可能懂幾種語言和許多歷史資料。"},{"en":"A person can be creative even if others do not consider him the most learned.","zh":"即使別人不認為某人最博學，他仍可以富有創意。"},{"en":"The word is formal and connected with scholarship.","zh":"這個詞較正式，與學問有關。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":8},{"front":"by his peers","meaning":"由他的同輩","examples":[{"en":"Shakespeare achieved respect among his peers.","zh":"莎士比亞在同輩之中獲得尊重。"},{"en":"By his peers means by people of similar profession, age, or status.","zh":"by his peers 指由職業、年齡或地位相近的人作出判斷。"},{"en":"A doctor respected by her peers is trusted by other doctors.","zh":"受到同輩尊重的醫生會被其他醫生信任。"},{"en":"Recognition by peers can matter because they understand the difficulty of the work.","zh":"來自同輩的認可可以很重要，因為他們理解工作的難度。"},{"en":"The phrase focuses on judgement from equals or colleagues.","zh":"這個短語重點是來自同等身份者或同事的評價。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":8},{"front":"nevertheless","meaning":"然而；儘管如此","examples":[{"en":"He nevertheless achieved wealth, respect and fame.","zh":"然而，他仍獲得財富、尊重和名聲。"},{"en":"Nevertheless means however or despite that fact.","zh":"nevertheless 指然而或儘管如此。"},{"en":"The course was difficult; nevertheless, many students completed it successfully.","zh":"課程很困難；然而，許多學生成功完成。"},{"en":"A writer may lack certain advantages and nevertheless become respected.","zh":"作家可能缺乏某些優勢，儘管如此仍變得受尊重。"},{"en":"The word introduces a contrast with the previous idea.","zh":"這個詞引入與前一想法的對比。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":8},{"front":"achieve considerable wealth","meaning":"獲得可觀財富","examples":[{"en":"Shakespeare achieved considerable wealth during his lifetime.","zh":"莎士比亞在有生之年獲得可觀財富。"},{"en":"To achieve considerable wealth means to gain a large amount of money or property.","zh":"achieve considerable wealth 指取得大量金錢或財產。"},{"en":"A business owner may achieve considerable wealth after years of successful trading.","zh":"企業主可能經過多年成功貿易後獲得可觀財富。"},{"en":"Wealth can show commercial success, but it does not automatically prove literary genius.","zh":"財富可以顯示商業成功，但不會自動證明文學天才。"},{"en":"The phrase focuses on material success.","zh":"這個短語重點是物質成功。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":8},{"front":"respect and fame","meaning":"尊重和名聲","examples":[{"en":"He achieved respect and fame even in his own lifetime.","zh":"他甚至在有生之年已獲得尊重和名聲。"},{"en":"Respect and fame mean admiration from others and being widely known.","zh":"respect and fame 指他人的敬重以及廣為人知。"},{"en":"A scientist may gain respect and fame after making a discovery that helps many people.","zh":"科學家作出幫助許多人的發現後，可能獲得尊重和名聲。"},{"en":"If someone has respect and fame while alive, later silence after death may seem surprising.","zh":"如果某人在世時已有尊重和名聲，死後公開沉默可能顯得令人驚訝。"},{"en":"The phrase combines reputation for quality with public recognition.","zh":"這個短語結合質素聲譽和公眾認可。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":8},{"front":"in his own lifetime","meaning":"在他有生之年","examples":[{"en":"Shakespeare became famous in his own lifetime.","zh":"莎士比亞在他有生之年已成名。"},{"en":"In his own lifetime means while he was still alive.","zh":"in his own lifetime 指在他仍然在世時。"},{"en":"Some artists are ignored while alive, but others become successful in their own lifetime.","zh":"有些藝術家在世時被忽視，但另一些人在有生之年已成功。"},{"en":"Fame in one’s own lifetime means the person did not have to wait until after death for recognition.","zh":"在有生之年成名，表示該人不必等到死後才獲認可。"},{"en":"The phrase contrasts living reputation with posthumous reputation.","zh":"這個短語把在世名聲與死後名聲作對比。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":8},{"front":"become public","meaning":"變得公開","examples":[{"en":"Doubts about Shakespeare’s authorship first became public in the mid-19th century.","zh":"關於莎士比亞作者身份的疑問首次在19世紀中葉變得公開。"},{"en":"To become public means to become known or discussed openly by many people.","zh":"become public 指被許多人知道或公開討論。"},{"en":"A school problem may become public if parents discuss it in newspapers.","zh":"如果家長在報紙上討論，學校問題可能變得公開。"},{"en":"Once private doubts become public, a wider debate can begin.","zh":"一旦私人疑問變得公開，更廣泛爭論就可以開始。"},{"en":"The phrase focuses on moving from hidden or private to open awareness.","zh":"這個短語重點是由隱藏或私人轉為公開認知。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":8},{"front":"in the mid-19th century","meaning":"在19世紀中葉","examples":[{"en":"The authorship debate became public in the mid-19th century.","zh":"作者身份爭論在19世紀中葉變得公開。"},{"en":"In the mid-19th century means around the middle years of the 1800s.","zh":"in the mid-19th century 指1800年代中期左右。"},{"en":"Many social reforms were debated in the mid-19th century.","zh":"許多社會改革在19世紀中葉受到爭論。"},{"en":"If a debate began in the mid-19th century, it appeared long after Shakespeare’s death.","zh":"如果爭論在19世紀中葉開始，它就是在莎士比亞死後很久才出現。"},{"en":"The phrase gives a broad historical time period.","zh":"這個短語提供廣泛歷史時期。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":8},{"front":"the debate has never ceased","meaning":"爭論從未停止","examples":[{"en":"The debate over Shakespeare’s authorship has never ceased.","zh":"關於莎士比亞作者身份的爭論從未停止。"},{"en":"If a debate has never ceased, people have continued arguing about it without stopping completely.","zh":"如果 debate has never ceased，意思是人們一直爭論，沒有完全停止。"},{"en":"The debate over school uniforms has never ceased because parents and students value different things.","zh":"校服爭論從未停止，因為家長和學生重視不同事情。"},{"en":"A debate can continue for years when evidence is interpreted in different ways.","zh":"當證據被不同方式詮釋，爭論可以持續多年。"},{"en":"The phrase stresses long-lasting controversy.","zh":"這個短語強調長期持續的爭議。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":9},{"front":"develop into","meaning":"發展成為","examples":[{"en":"The doubts developed into the Shakespeare authorship question.","zh":"這些疑問發展成為莎士比亞作者身份問題。"},{"en":"To develop into something means to gradually become that thing.","zh":"develop into something 指逐漸變成某事物。"},{"en":"A small disagreement can develop into a serious argument if nobody listens.","zh":"如果沒有人聆聽，小分歧可以發展成嚴重爭吵。"},{"en":"When scattered doubts become organised, they can develop into a recognised debate.","zh":"當零散疑問變得有組織，它們可以發展成被承認的爭論。"},{"en":"The phrase shows gradual change from one state to another.","zh":"這個短語顯示由一種狀態逐漸變成另一種狀態。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":9},{"front":"be known by","meaning":"被稱為","examples":[{"en":"The debate became known by a grand title.","zh":"這場爭論被冠上一個宏大的稱號。"},{"en":"To be known by a name means to be called or recognised using that name.","zh":"be known by a name 指以某名稱被稱呼或認識。"},{"en":"A school event may be known by a short nickname among students.","zh":"學生活動可能在學生之間被稱為一個短暱稱。"},{"en":"When a debate is known by a formal title, it may sound more serious or established.","zh":"當爭論被正式標題稱呼，它可能聽起來更嚴肅或更確立。"},{"en":"The phrase focuses on naming and recognition.","zh":"這個短語重點是命名和認知。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":9},{"front":"the grand title","meaning":"冠冕堂皇的稱號","examples":[{"en":"The issue was given the grand title the Shakespeare authorship question.","zh":"這個問題被冠以「莎士比亞作者身份問題」這個冠冕堂皇的稱號。"},{"en":"A grand title is a formal, impressive, or important-sounding name.","zh":"grand title 指正式、令人印象深刻或聽起來重要的名稱。"},{"en":"A simple school project may be given a grand title to make it sound more official.","zh":"簡單學校項目可能被冠上宏大標題，使它聽起來更正式。"},{"en":"Giving an issue a grand title can make it appear larger than it really is.","zh":"給一個問題冠上宏大稱號，可以令它顯得比實際更大。"},{"en":"The phrase can carry mild irony.","zh":"這個短語可以帶輕微諷刺意味。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":9},{"front":"divide someone into","meaning":"把某人分成","examples":[{"en":"The question divided interested readers into two sides.","zh":"這個問題把感興趣的讀者分成兩派。"},{"en":"To divide people into groups means to separate them according to opinion, role, or category.","zh":"divide people into groups 指按意見、角色或類別把人分開。"},{"en":"A debate about phones in schools may divide parents into supporters and opponents.","zh":"關於學校手機的爭論可能把家長分成支持者和反對者。"},{"en":"When evidence is controversial, readers may divide into different camps.","zh":"當證據具爭議，讀者可能分成不同陣營。"},{"en":"The phrase shows separation by viewpoint.","zh":"這個短語顯示按觀點分隔。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":9},{"front":"the Stratfordians","meaning":"斯特拉特福派","examples":[{"en":"The Stratfordians support Shakespeare as the author.","zh":"斯特拉特福派支持莎士比亞為作者。"},{"en":"The Stratfordians are people who accept the traditional view that Shakespeare of Stratford wrote the plays.","zh":"Stratfordians 指接受傳統觀點，即斯特拉特福的莎士比亞寫了這些劇作的人。"},{"en":"In an authorship debate, Stratfordians rely heavily on documentary evidence.","zh":"在作者身份爭論中，斯特拉特福派非常依靠文獻證據。"},{"en":"Stratfordians oppose theories that assign the plays to aristocrats or other writers.","zh":"斯特拉特福派反對把劇作歸於貴族或其他作家的理論。"},{"en":"The phrase names one side of the debate.","zh":"這個短語命名爭論中的一方。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":9},{"front":"the anti-Stratfordians","meaning":"反斯特拉特福派","examples":[{"en":"The anti-Stratfordians reject Shakespeare as the author.","zh":"反斯特拉特福派否認莎士比亞是作者。"},{"en":"Anti-Stratfordians are people who deny that Shakespeare of Stratford wrote the plays attributed to him.","zh":"anti-Stratfordians 指否認斯特拉特福的莎士比亞寫了歸於他的劇作的人。"},{"en":"Anti-Stratfordians often search for alternative candidates with higher education or noble background.","zh":"反斯特拉特福派常尋找教育程度更高或有貴族背景的替代候選人。"},{"en":"Their position requires explaining why documents name Shakespeare as author.","zh":"他們的立場需要解釋為何文件把莎士比亞列為作者。"},{"en":"The phrase names the side opposing the traditional view.","zh":"這個短語命名反對傳統觀點的一方。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":9},{"front":"support someone as","meaning":"支持某人作為","examples":[{"en":"Stratfordians support Shakespeare as the author of the plays.","zh":"斯特拉特福派支持莎士比亞作為這些劇作的作者。"},{"en":"To support someone as something means to believe or argue that the person has that role or identity.","zh":"support someone as something 指相信或主張某人具有某角色或身份。"},{"en":"A committee may support a teacher as the best candidate for principal.","zh":"委員會可能支持一名老師作為校長的最佳候選人。"},{"en":"If evidence names a person repeatedly, supporters may use it to support him as the author.","zh":"如果證據反覆列出某人名字，支持者可能用它支持他作為作者。"},{"en":"The phrase connects belief with a person’s role.","zh":"這個短語把信念與某人的角色連起來。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":9},{"front":"the latter body","meaning":"後者群體","examples":[{"en":"For the latter body, a conspiracy must be assumed.","zh":"對後者群體而言，必須假設存在一場陰謀。"},{"en":"The latter body means the second group just mentioned.","zh":"latter body 指剛提到的第二個群體。"},{"en":"If a report mentions teachers and parents, the latter body refers to parents.","zh":"如果報告提到老師和家長，後者群體就是家長。"},{"en":"Writers use this phrase to avoid repeating the name of a group.","zh":"作者使用這個短語，以避免重複群體名稱。"},{"en":"The phrase requires readers to look back at the previous comparison.","zh":"這個短語要求讀者回看前面的比較。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":9},{"front":"overcome the documentary evidence","meaning":"克服文獻證據","examples":[{"en":"Anti-Stratfordians must overcome the documentary evidence supporting Shakespeare.","zh":"反斯特拉特福派必須克服支持莎士比亞的文獻證據。"},{"en":"To overcome documentary evidence means to explain or refute written records that support the opposite view.","zh":"overcome documentary evidence 指解釋或反駁支持相反觀點的書面紀錄。"},{"en":"A lawyer must overcome documentary evidence if signed papers contradict the client’s story.","zh":"如果簽署文件與客戶說法矛盾，律師就必須克服文獻證據。"},{"en":"If documents clearly support one claim, alternative theories need stronger proof to overcome them.","zh":"如果文件清楚支持某聲稱，替代理論需要更強證明才能克服它們。"},{"en":"The phrase describes the challenge of dealing with written evidence.","zh":"這個短語描述處理書面證據的挑戰。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":9},{"front":"in support of","meaning":"支持……","examples":[{"en":"There is documentary evidence in support of Shakespeare’s authorship.","zh":"有文獻證據支持莎士比亞的作者身份。"},{"en":"In support of something means helping to prove, defend, or strengthen it.","zh":"in support of something 指幫助證明、捍衛或加強某事。"},{"en":"A student may quote data in support of an argument about public transport.","zh":"學生可能引用數據支持關於公共交通的論點。"},{"en":"Evidence in support of one theory makes competing theories harder to accept.","zh":"支持某理論的證據會令競爭理論較難被接受。"},{"en":"The phrase links evidence with the claim it helps.","zh":"這個短語把證據與其支持的聲稱連起來。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":9},{"front":"assume a conspiracy existed","meaning":"假設存在陰謀","examples":[{"en":"Some anti-Stratfordians assume a conspiracy existed.","zh":"一些反斯特拉特福派假設存在陰謀。"},{"en":"To assume a conspiracy existed means to believe without direct proof that people secretly worked together to hide the truth.","zh":"assume a conspiracy existed 指在沒有直接證據下相信有人秘密合作隱瞞真相。"},{"en":"If exam results disappear, students should not assume a conspiracy existed without evidence.","zh":"如果考試結果消失，學生不應在沒有證據下假設存在陰謀。"},{"en":"Conspiracy assumptions can explain away documents, but they require strong proof.","zh":"陰謀假設可以把文件證據解釋掉，但需要強力證明。"},{"en":"The phrase suggests a hidden plan is being imagined.","zh":"這個短語暗示人們想像有隱藏計劃。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":10},{"front":"among a select group of","meaning":"在一小撮……之間","examples":[{"en":"The supposed conspiracy existed among a select group of people.","zh":"這場所謂陰謀存在於一小撮人之間。"},{"en":"Among a select group of people means within a small, specially chosen or limited group.","zh":"among a select group of people 指在一個小型、特別選定或有限的群體之內。"},{"en":"A confidential school decision may be discussed among a select group of senior staff.","zh":"機密學校決定可能只在一小撮高級職員之間討論。"},{"en":"If only a select group knew the truth, secrecy would be easier but still difficult to prove.","zh":"如果只有一小撮人知道真相，保密會較容易，但仍難以證明。"},{"en":"The phrase suggests exclusiveness and limited membership.","zh":"這個短語暗示排他性和成員有限。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":10},{"front":"protect the real author’s identity","meaning":"保護真正作者的身份","examples":[{"en":"The conspiracy was supposedly arranged to protect the real author’s identity.","zh":"這場陰謀據稱是為了保護真正作者的身份而安排的。"},{"en":"To protect the real author’s identity means to keep secret who actually wrote the work.","zh":"protect the real author’s identity 指保密真正寫作該作品的人是誰。"},{"en":"A whistle-blower may hide a writer’s identity to protect them from punishment.","zh":"告密者可能隱藏作者身份，以保護他免受懲罰。"},{"en":"If the real author’s identity is hidden, another name may appear on the publication.","zh":"如果真正作者身份被隱藏，出版物上可能出現另一個名字。"},{"en":"The phrase focuses on secrecy around authorship.","zh":"這個短語重點是圍繞作者身份的保密。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":10},{"front":"it goes without saying that","meaning":"不言而喻","examples":[{"en":"In those times, it goes without saying that the candidate was assumed to be male.","zh":"在那個時代，不言而喻，候選人被假定為男性。"},{"en":"It goes without saying that means something is considered so obvious that it does not need to be explained.","zh":"it goes without saying that 指某事被視為非常明顯，不需要解釋。"},{"en":"It goes without saying that students should not copy answers during an exam.","zh":"不言而喻，學生考試時不應抄答案。"},{"en":"The phrase can reveal assumptions that people in a period treated as normal.","zh":"這個短語可以揭示某時代的人視為正常的假設。"},{"en":"It often introduces a point the writer thinks is obvious.","zh":"它常引入作者認為明顯的點。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":10},{"front":"search for","meaning":"尋找","examples":[{"en":"Anti-Stratfordians search for an upper-class candidate.","zh":"反斯特拉特福派尋找一位上流社會候選人。"},{"en":"To search for something means to try to find it.","zh":"search for something 指嘗試找出某物。"},{"en":"A student may search for reliable sources before writing an essay.","zh":"學生可能在寫作文前尋找可靠資料來源。"},{"en":"When people reject the usual answer, they often search for an alternative explanation.","zh":"當人們拒絕一般答案，他們通常會尋找另一種解釋。"},{"en":"The phrase describes active looking.","zh":"這個短語描述主動搜尋。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":10},{"front":"university-educated","meaning":"受過大學教育的","examples":[{"en":"They search for a university-educated candidate.","zh":"他們尋找一位受過大學教育的候選人。"},{"en":"University-educated means having studied at a university.","zh":"university-educated 指曾在大學學習。"},{"en":"A university-educated lawyer has usually completed advanced legal training.","zh":"受過大學教育的律師通常完成了高等法律訓練。"},{"en":"Critics may prefer a university-educated author if they believe the plays show elite learning.","zh":"如果評論者相信劇作顯示精英學問，他們可能偏好受過大學教育的作者。"},{"en":"The phrase describes educational background.","zh":"這個短語描述教育背景。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":10},{"front":"upper-class candidate","meaning":"上流社會候選人","examples":[{"en":"Anti-Stratfordians prefer an upper-class candidate for authorship.","zh":"反斯特拉特福派偏好以上流社會候選人作為作者。"},{"en":"An upper-class candidate is a possible author from a high social rank or wealthy background.","zh":"upper-class candidate 指來自高社會階層或富裕背景的可能作者。"},{"en":"A theory may favour an upper-class candidate if the work describes royal courts in detail.","zh":"如果作品詳細描寫王室宮廷，某理論可能偏好上流社會候選人。"},{"en":"Choosing an upper-class candidate reflects assumptions about who could possess certain knowledge.","zh":"選擇上流社會候選人反映人們對誰能擁有某些知識的假設。"},{"en":"The phrase focuses on social status.","zh":"這個短語重點是社會地位。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":10},{"front":"inevitably have had knowledge of","meaning":"必然會對……有所了解","examples":[{"en":"Such a candidate would inevitably have had knowledge of courtly manners.","zh":"這樣的候選人必然會對宮廷禮儀有所了解。"},{"en":"Inevitably have had knowledge of something means must certainly have known about it because of background or experience.","zh":"inevitably have had knowledge of something 指由於背景或經驗，必定知道某事。"},{"en":"A nurse who worked in emergency care would inevitably have had knowledge of hospital routines.","zh":"曾在急症室工作的護士必然會了解醫院程序。"},{"en":"Critics assume an aristocrat would know court behaviour because he lived near that world.","zh":"評論者假設貴族會了解宮廷行為，因為他生活接近那個世界。"},{"en":"The phrase expresses strong certainty about past knowledge.","zh":"這個短語表達對過去知識的強烈確定。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":10},{"front":"aristocratic manners and mores","meaning":"貴族禮儀和習俗","examples":[{"en":"The plays show knowledge of aristocratic manners and mores.","zh":"這些劇作顯示對貴族禮儀和習俗的了解。"},{"en":"Aristocratic manners and mores are the behaviours, customs, and social rules of the upper class.","zh":"aristocratic manners and mores 指上流階層的行為、習俗和社會規則。"},{"en":"A novel about a royal court may describe aristocratic manners such as formal greetings and ranked seating.","zh":"關於王室宮廷的小說可能描述正式問候和按地位排座等貴族禮儀。"},{"en":"If a play uses these customs accurately, some readers may think the author knew elite society well.","zh":"如果劇作準確使用這些習俗，一些讀者可能認為作者很了解精英社會。"},{"en":"The phrase combines behaviour and social values.","zh":"這個短語結合行為和社會價值。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":10},{"front":"familiarity with","meaning":"對……熟悉","examples":[{"en":"The real author would need familiarity with royal court politics.","zh":"真正作者需要對王室宮廷政治熟悉。"},{"en":"Familiarity with something means knowledge of it gained through experience or study.","zh":"familiarity with something 指透過經驗或學習得到的相關知識。"},{"en":"A teacher needs familiarity with exam requirements before preparing students.","zh":"老師在準備學生前需要熟悉考試要求。"},{"en":"Familiarity with court life could help a writer describe ceremonies and power struggles convincingly.","zh":"熟悉宮廷生活可以幫助作家有說服力地描寫儀式和權力鬥爭。"},{"en":"The phrase suggests practical knowledge, not just hearing a word once.","zh":"這個短語暗示實際知識，而不是只聽過一次某詞。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":10},{"front":"proceedings and politics","meaning":"程序和政治運作","examples":[{"en":"The plays reveal familiarity with the proceedings and politics of court life.","zh":"這些劇作顯示作者熟悉宮廷生活的程序和政治運作。"},{"en":"Proceedings and politics mean formal processes and power relationships in an institution.","zh":"proceedings and politics 指機構中的正式流程和權力關係。"},{"en":"A student council has proceedings such as meetings and votes, and politics such as alliances and influence.","zh":"學生會有會議和投票等程序，也有聯盟和影響力等政治運作。"},{"en":"A writer who knows court proceedings and politics can show how decisions are made and power is used.","zh":"熟悉宮廷程序和政治運作的作家，可以展示決策如何形成和權力如何使用。"},{"en":"The phrase combines official procedure with hidden or open power struggles.","zh":"這個短語結合官方程序與隱性或公開權力鬥爭。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":10},{"front":"the royal court","meaning":"王室宮廷","examples":[{"en":"Many plays include details about the royal court.","zh":"許多劇作包括關於王室宮廷的細節。"},{"en":"The royal court is the household, officials, advisers, and social world surrounding a monarch.","zh":"royal court 指圍繞君主的家庭、官員、顧問和社交世界。"},{"en":"A royal court may include ceremonies, political discussions, servants, nobles, and visitors.","zh":"王室宮廷可能包括儀式、政治討論、僕人、貴族和訪客。"},{"en":"Writers use royal court settings to explore power, ambition, loyalty, and betrayal.","zh":"作家使用王室宮廷背景來探討權力、野心、忠誠和背叛。"},{"en":"The phrase refers to the ruler’s political and social centre.","zh":"這個短語指統治者的政治和社交中心。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":11},{"front":"appear in the plays","meaning":"出現在劇中","examples":[{"en":"Aristocratic settings often appear in the plays.","zh":"貴族背景常出現在劇中。"},{"en":"To appear in the plays means to be shown, mentioned, or included in the dramatic works.","zh":"appear in the plays 指在劇作中被展示、提及或包括。"},{"en":"Ghosts, kings, battles, and courts may appear in historical plays.","zh":"鬼魂、國王、戰爭和宮廷都可能出現在歷史劇中。"},{"en":"If certain settings appear repeatedly, critics may ask how the writer knew them.","zh":"如果某些背景反覆出現，評論者可能問作者如何知道它們。"},{"en":"The phrase focuses on content found inside the plays.","zh":"這個短語重點是劇作中的內容。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":11},{"front":"the reason for","meaning":"……的原因","examples":[{"en":"The reason for the conspiracy was supposedly the danger faced by the real author.","zh":"這場陰謀的原因據說是真正作者面對的危險。"},{"en":"The reason for something is the cause or explanation behind it.","zh":"reason for something 指某事背後的原因或解釋。"},{"en":"The reason for a school rule should be explained so students understand it.","zh":"學校規則的原因應被解釋，使學生理解。"},{"en":"If a theory includes a conspiracy, it must also explain the reason for hiding the truth.","zh":"如果理論包括陰謀，它也必須解釋隱藏真相的原因。"},{"en":"The phrase introduces cause or motive.","zh":"這個短語引入原因或動機。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":11},{"front":"produce such works","meaning":"創作這類作品","examples":[{"en":"Producing such works could have been dangerous for a nobleman.","zh":"對貴族男子而言，創作這類作品可能是危險的。"},{"en":"To produce such works means to create writings of that kind.","zh":"produce such works 指創作這種類型的作品。"},{"en":"A journalist producing critical articles may face pressure in an authoritarian society.","zh":"在威權社會中，創作批判文章的記者可能面對壓力。"},{"en":"If works discuss rebellion and murder, producing them could create political risk.","zh":"如果作品討論叛亂和謀殺，創作它們可能造成政治風險。"},{"en":"The phrase focuses on the act of creating the works.","zh":"這個短語重點是創作作品的行為。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":11},{"front":"full of themes of","meaning":"充滿……主題","examples":[{"en":"The plays are full of themes of revenge, murder and rebellion.","zh":"這些劇作充滿復仇、謀殺和叛亂主題。"},{"en":"Full of themes of something means containing many repeated ideas about that subject.","zh":"full of themes of something 指包含許多關於該主題的重複想法。"},{"en":"A film full of themes of family conflict may show arguments, silence, and reconciliation.","zh":"充滿家庭衝突主題的電影可能展示爭吵、沉默和和解。"},{"en":"If a play is full of political themes, authorities may read it as dangerous.","zh":"如果劇作充滿政治主題，當局可能把它解讀為危險。"},{"en":"The phrase points to repeated ideas, not one single scene.","zh":"這個短語指出重複思想，而不是單一場景。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":11},{"front":"royal revenge","meaning":"王室復仇","examples":[{"en":"Royal revenge is one of the themes found in the plays.","zh":"王室復仇是劇作中的主題之一。"},{"en":"Royal revenge means revenge involving kings, queens, princes, or royal families.","zh":"royal revenge 指涉及國王、女王、王子或王室家族的復仇。"},{"en":"A drama about a prince avenging his father’s murder contains royal revenge.","zh":"關於王子為父親被殺報仇的戲劇包含王室復仇。"},{"en":"Such themes can feel politically sensitive when they involve rulers and violence.","zh":"當這類主題涉及統治者和暴力，它們可能具有政治敏感性。"},{"en":"The phrase combines monarchy with retaliation.","zh":"這個短語結合君主制度與報復。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":11},{"front":"intrigue and assassination","meaning":"陰謀和暗殺","examples":[{"en":"The plays include themes of intrigue and assassination.","zh":"這些劇作包括陰謀和暗殺主題。"},{"en":"Intrigue and assassination mean secret plotting and the murder of an important person for political reasons.","zh":"intrigue and assassination 指秘密策劃以及因政治原因謀殺重要人物。"},{"en":"A court drama may involve intrigue and assassination when nobles secretly plan to kill a ruler.","zh":"當貴族秘密計劃殺死統治者，宮廷劇就涉及陰謀和暗殺。"},{"en":"These themes can make a story exciting but politically dangerous.","zh":"這些主題可以令故事刺激，但在政治上危險。"},{"en":"The phrase suggests hidden schemes and violent power struggles.","zh":"這個短語暗示隱藏計謀和暴力權力鬥爭。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":11},{"front":"mob rule and rebellion","meaning":"群眾暴政和叛亂","examples":[{"en":"The works include themes of mob rule and rebellion.","zh":"這些作品包括群眾暴政和叛亂主題。"},{"en":"Mob rule and rebellion mean violent crowd control and organised resistance against authority.","zh":"mob rule and rebellion 指暴力群眾控制局勢，以及有組織地反抗權威。"},{"en":"A city may fear mob rule when angry crowds attack officials and ignore the law.","zh":"當憤怒群眾攻擊官員並無視法律，城市可能害怕群眾暴政。"},{"en":"Plays about rebellion can be sensitive because they question political order.","zh":"關於叛亂的劇作可能敏感，因為它們質疑政治秩序。"},{"en":"The phrase combines disorder from crowds with open resistance.","zh":"這個短語結合群眾造成的混亂和公開反抗。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":11},{"front":"render someone liable to","meaning":"使某人有可能受到……","examples":[{"en":"Writing such plays could render a nobleman liable to political accusations.","zh":"寫這類劇作可能使貴族男子有可能受到政治指控。"},{"en":"To render someone liable to something means to make them likely or legally open to that risk.","zh":"render someone liable to something 指使某人很可能或在法律上可能面對某風險。"},{"en":"Careless driving can render a driver liable to prosecution.","zh":"粗心駕駛可能使司機面臨檢控。"},{"en":"Publishing dangerous political writing could make an aristocrat vulnerable to punishment.","zh":"出版危險政治作品可能令貴族容易受到懲罰。"},{"en":"The phrase is formal and often connected with law or risk.","zh":"這個短語較正式，常與法律或風險有關。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":11},{"front":"a nobleman","meaning":"貴族男子","examples":[{"en":"A nobleman might have feared being accused of subversion.","zh":"貴族男子可能害怕被指控顛覆。"},{"en":"A nobleman is a man from the aristocracy or upper social rank.","zh":"nobleman 指來自貴族或上流社會階層的男子。"},{"en":"A nobleman in a royal court may have land, titles, and political connections.","zh":"王室宮廷中的貴族男子可能擁有土地、頭銜和政治聯繫。"},{"en":"If a nobleman wrote controversial works, his social position could make the risk greater.","zh":"如果貴族男子寫具爭議作品，他的社會地位可能令風險更大。"},{"en":"The phrase refers to male aristocratic status.","zh":"這個短語指男性貴族身份。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":11},{"front":"the dangerous charge of","meaning":"……的危險指控","examples":[{"en":"A noble author could face the dangerous charge of subversion.","zh":"貴族作者可能面對顛覆活動的危險指控。"},{"en":"The dangerous charge of something means a serious accusation that could bring punishment or disgrace.","zh":"dangerous charge of something 指可能帶來懲罰或羞辱的嚴重指控。"},{"en":"In a strict school, the dangerous charge of cheating can damage a student’s record.","zh":"在嚴格學校中，作弊的嚴重指控可以損害學生紀錄。"},{"en":"Political accusations are dangerous when rulers see writing as a threat to authority.","zh":"當統治者把寫作視為權威威脅，政治指控就很危險。"},{"en":"The phrase stresses the seriousness of being accused.","zh":"這個短語強調被指控的嚴重性。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":11},{"front":"subversion","meaning":"顛覆活動；顛覆罪","examples":[{"en":"Themes of rebellion could lead to accusations of subversion.","zh":"叛亂主題可能導致顛覆活動的指控。"},{"en":"Subversion means attempts or ideas that undermine an established authority or political order.","zh":"subversion 指削弱既有權威或政治秩序的嘗試或思想。"},{"en":"A government may treat calls for rebellion as subversion.","zh":"政府可能把呼籲叛亂視為顛覆活動。"},{"en":"Writing about overthrowing rulers could be risky in a society afraid of political instability.","zh":"在害怕政治不穩的社會中，寫推翻統治者可能很危險。"},{"en":"The word is political and often connected with threats to authority.","zh":"這個詞具政治性，常與對權威的威脅有關。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":12},{"front":"socially unacceptable","meaning":"社會上不能接受的","examples":[{"en":"Publishing creative literature for money was considered socially unacceptable for the upper class.","zh":"對上流階層而言，為金錢出版創作文學被認為在社會上不能接受。"},{"en":"Socially unacceptable means disapproved of by society or by a particular social group.","zh":"socially unacceptable 指不被社會或某個社會群體認可。"},{"en":"In some workplaces, shouting at colleagues is socially unacceptable even if it is not illegal.","zh":"在一些工作場所，對同事大叫即使不違法，也是社會上不能接受的。"},{"en":"If aristocrats considered paid publishing shameful, they might avoid attaching their names to it.","zh":"如果貴族認為為錢出版很丟臉，他們可能避免署名。"},{"en":"The phrase describes social judgement, not necessarily law.","zh":"這個短語描述社會評價，而不一定是法律。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":12},{"front":"the upper class","meaning":"上流階層","examples":[{"en":"Some argued that the upper class avoided publishing for money.","zh":"有些人認為上流階層避免為金錢出版作品。"},{"en":"The upper class means the wealthiest or highest-status group in society.","zh":"upper class 指社會中最富裕或地位最高的群體。"},{"en":"In old societies, the upper class often had land, titles, education, and political access.","zh":"在舊社會中，上流階層通常擁有土地、頭銜、教育和政治渠道。"},{"en":"Expectations of upper-class behaviour could limit what noble people felt free to do.","zh":"對上流階層行為的期望，可能限制貴族覺得自己可以做甚麼。"},{"en":"The phrase refers to social rank.","zh":"這個短語指社會階級。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":12},{"front":"publish creative literature","meaning":"出版創作文學","examples":[{"en":"It was considered improper for aristocrats to publish creative literature for profit.","zh":"貴族為牟利而出版創作文學被認為不合適。"},{"en":"To publish creative literature means to make poems, plays, stories, or similar imaginative writing publicly available.","zh":"publish creative literature 指公開發表詩、劇作、故事或類似想像性作品。"},{"en":"A young writer may publish creative literature in a magazine before releasing a book.","zh":"年輕作家可能先在雜誌出版創作文學，之後才出書。"},{"en":"In some periods, publishing for money could damage an aristocrat’s social image.","zh":"在某些時期，為金錢出版可能損害貴族的社會形象。"},{"en":"The phrase focuses on public release of imaginative writing.","zh":"這個短語重點是公開發布想像性寫作。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":12},{"front":"monetary gain","meaning":"金錢收益","examples":[{"en":"Upper-class writers supposedly avoided publishing for monetary gain.","zh":"上流階層作家據稱避免為金錢收益而出版。"},{"en":"Monetary gain means financial profit or money earned from an activity.","zh":"monetary gain 指從某活動中獲得的財務利潤或金錢。"},{"en":"A teacher should not recommend books only for monetary gain.","zh":"老師不應只為金錢收益而推薦書本。"},{"en":"If a writer publishes for monetary gain, critics may judge the action differently in class-conscious societies.","zh":"如果作家為金錢收益出版，在階級意識強的社會中，評論者可能不同地評價此行為。"},{"en":"The phrase focuses on money as the benefit.","zh":"這個短語重點是金錢作為好處。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":12},{"front":"confine oneself to","meaning":"只限於；局限於","examples":[{"en":"Upper-class authors often confined themselves to private circulation.","zh":"上流階層作者通常只限於私人傳閱。"},{"en":"To confine oneself to something means to limit oneself to that activity or area.","zh":"confine oneself to something 指把自己限制於某活動或範圍。"},{"en":"A student may confine herself to simple sentences until she gains confidence.","zh":"學生可能在建立信心前只限於寫簡單句。"},{"en":"If writers confine themselves to private sharing, the public may never see their work.","zh":"如果作家只局限於私人分享，公眾可能永遠看不到他們的作品。"},{"en":"The phrase stresses self-limitation.","zh":"這個短語強調自我限制。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":12},{"front":"circulate writings among","meaning":"在……之間傳閱作品","examples":[{"en":"Some writers circulated their writings among their peers.","zh":"一些作家在同輩之間傳閱作品。"},{"en":"To circulate writings among people means to share written works within that group.","zh":"circulate writings among people 指在某群體內分享書面作品。"},{"en":"Students may circulate draft essays among classmates for comments.","zh":"學生可能在同學之間傳閱作文草稿以取得意見。"},{"en":"Private circulation lets writers receive feedback without publishing publicly.","zh":"私人傳閱讓作家不用公開出版也能得到回饋。"},{"en":"The phrase focuses on distribution within a limited circle.","zh":"這個短語重點是在有限圈子中分發。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":12},{"front":"their peers","meaning":"他們的同輩","examples":[{"en":"Upper-class authors shared writings among their peers.","zh":"上流階層作者在他們的同輩之間分享作品。"},{"en":"Their peers are people of similar rank, age, profession, or social group.","zh":"their peers 指地位、年齡、職業或社會群體相近的人。"},{"en":"Students often learn from their peers because classmates face similar problems.","zh":"學生常從同輩身上學習，因為同學面對相似問題。"},{"en":"If aristocrats circulated writing only among peers, ordinary readers would not see it.","zh":"如果貴族只在同輩之間傳閱作品，普通讀者就看不到它。"},{"en":"The phrase refers to people considered social or professional equals.","zh":"這個短語指被視為社會或專業上相等的人。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":12},{"front":"courtly audiences","meaning":"宮廷觀眾","examples":[{"en":"Their works might be performed for courtly audiences.","zh":"他們的作品可能為宮廷觀眾演出。"},{"en":"Courtly audiences are audiences connected with a royal court or aristocratic society.","zh":"courtly audiences 指與王室宮廷或貴族社會有關的觀眾。"},{"en":"A courtly audience might include nobles, advisers, courtiers, and royal guests.","zh":"宮廷觀眾可能包括貴族、顧問、朝臣和王室賓客。"},{"en":"A play for courtly audiences may use references and manners familiar to elite viewers.","zh":"面向宮廷觀眾的劇作可能使用精英觀眾熟悉的典故和禮儀。"},{"en":"The phrase contrasts elite audiences with the general public.","zh":"這個短語把精英觀眾與一般公眾作對比。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":12},{"front":"leading contenders","meaning":"主要競爭者","examples":[{"en":"The passage discusses four leading contenders for Shakespeare’s authorship.","zh":"文章討論四位莎士比亞作者身份的主要競爭者。"},{"en":"Leading contenders are the strongest or most prominent candidates in a debate or competition.","zh":"leading contenders 指爭論或競爭中最有力或最突出的候選人。"},{"en":"In a school election, the leading contenders are the candidates most likely to win.","zh":"在學校選舉中，主要競爭者是最有可能勝出的候選人。"},{"en":"If several names are proposed, leading contenders receive the most attention.","zh":"如果提出多個名字，主要競爭者會得到最多關注。"},{"en":"The phrase points to main rivals or candidates.","zh":"這個短語指出主要對手或候選人。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":12},{"front":"be first nominated","meaning":"首先被提名","examples":[{"en":"Sir Francis Bacon was the first candidate nominated.","zh":"Francis Bacon 爵士是首先被提名的候選人。"},{"en":"To be first nominated means to be the first person formally suggested for a role or position.","zh":"be first nominated 指成為第一個被正式提出擔任某角色或位置的人。"},{"en":"A student may be first nominated for class captain before other names are suggested.","zh":"學生可能首先被提名為班長，之後才有其他名字被提出。"},{"en":"Being nominated first can make a candidate historically important in a debate.","zh":"首先被提名可以令候選人在爭論史上重要。"},{"en":"The phrase focuses on the order of being proposed.","zh":"這個短語重點是被提出的次序。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":12},{"front":"intellectual credentials","meaning":"學術資歷；知識背景","examples":[{"en":"Bacon had impressive intellectual credentials.","zh":"Bacon 有令人印象深刻的學術資歷。"},{"en":"Intellectual credentials are qualifications, achievements, or reputation showing strong learning and intelligence.","zh":"intellectual credentials 指顯示高深學問和智慧的資格、成就或聲譽。"},{"en":"A professor’s books, degrees, and research prizes can be intellectual credentials.","zh":"教授的書籍、學位和研究獎項都可以是學術資歷。"},{"en":"Supporters may value Bacon’s credentials because they seem to fit the plays’ learning.","zh":"支持者可能重視 Bacon 的知識背景，因為它看似符合劇作中的學問。"},{"en":"The phrase refers to evidence of intellectual authority.","zh":"這個短語指智識權威的證據。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":13},{"front":"well-versed in","meaning":"精通","examples":[{"en":"Bacon was well-versed in law, philosophy and science.","zh":"Bacon 精通法律、哲學和科學。"},{"en":"To be well-versed in something means to know it very well.","zh":"well-versed in something 指非常熟悉或精通某事。"},{"en":"A good immigration lawyer is well-versed in visa rules and court procedures.","zh":"優秀移民律師精通簽證規則和法庭程序。"},{"en":"Someone well-versed in history may write more confidently about past events.","zh":"精通歷史的人寫過去事件時可能更有信心。"},{"en":"The phrase suggests deep knowledge, not casual familiarity.","zh":"這個短語暗示深厚知識，而不是隨便熟悉。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":13},{"front":"essay writing","meaning":"散文寫作","examples":[{"en":"Bacon was known for essay writing and philosophy.","zh":"Bacon 以散文寫作和哲學聞名。"},{"en":"Essay writing is the practice of composing organised arguments or reflections in prose.","zh":"essay writing 指用散文形式寫出有組織論點或思考的寫作活動。"},{"en":"Students improve essay writing by planning, giving examples, and linking paragraphs clearly.","zh":"學生透過規劃、舉例和清楚連接段落來改善散文寫作。"},{"en":"A person skilled in essay writing may express ideas logically and briefly.","zh":"擅長散文寫作的人可能能邏輯而簡潔地表達思想。"},{"en":"The phrase refers to prose composition, not drama or poetry specifically.","zh":"這個短語指散文創作，而不專指戲劇或詩歌。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":13},{"front":"since the 1920s","meaning":"自1920年代以來","examples":[{"en":"Since the 1920s, Edward de Vere has become a leading candidate.","zh":"自1920年代以來，Edward de Vere 已成為主要候選人。"},{"en":"Since the 1920s means from the decade of the 1920s until now or a later reference point.","zh":"since the 1920s 指從1920年代起直到現在或後來某參考點。"},{"en":"Since the 1990s, online communication has changed how students learn languages.","zh":"自1990年代以來，網上通訊改變了學生學語言的方式。"},{"en":"If a theory has grown since the 1920s, it has a modern history rather than an early one.","zh":"如果某理論自1920年代以來才增長，它就有現代歷史，而不是早期歷史。"},{"en":"The phrase marks the starting period of a continuing trend.","zh":"這個短語標示持續趨勢的開始時期。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":13},{"front":"aristocratic earl","meaning":"貴族伯爵","examples":[{"en":"Edward de Vere was an aristocratic earl.","zh":"Edward de Vere 是一位貴族伯爵。"},{"en":"An aristocratic earl is a nobleman with a high hereditary title.","zh":"aristocratic earl 指擁有高級世襲頭銜的貴族男子。"},{"en":"An aristocratic earl might have access to court life, private education, and elite circles.","zh":"貴族伯爵可能接觸宮廷生活、私人教育和精英圈子。"},{"en":"Such background can make a candidate attractive to those seeking an upper-class author.","zh":"這種背景可以令候選人對尋找上流作者的人有吸引力。"},{"en":"The phrase combines noble status with a specific title.","zh":"這個短語結合貴族地位和特定頭銜。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":13},{"front":"patronise and sponsor","meaning":"贊助和支持","examples":[{"en":"De Vere patronised and sponsored actors and the arts.","zh":"De Vere 贊助和支持演員及藝術。"},{"en":"To patronise and sponsor artists means to support them with money, protection, or opportunities.","zh":"patronise and sponsor artists 指以金錢、保護或機會支持藝術家。"},{"en":"A local business may sponsor a school play by paying for costumes.","zh":"本地企業可能透過支付服裝費來贊助學校劇作。"},{"en":"A nobleman who supports actors may become closely connected with theatre culture.","zh":"支持演員的貴族可能與戲劇文化建立緊密連繫。"},{"en":"The phrase focuses on financial or social support.","zh":"這個短語重點是財務或社會支持。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":13},{"front":"actors and the arts","meaning":"演員和藝術","examples":[{"en":"De Vere supported actors and the arts.","zh":"De Vere 支持演員和藝術。"},{"en":"Actors and the arts means performers and creative fields such as theatre, music, painting, and literature.","zh":"actors and the arts 指表演者，以及戲劇、音樂、繪畫和文學等創意領域。"},{"en":"A city supports actors and the arts when it funds theatres and public performances.","zh":"城市資助劇院和公共表演時，就是支持演員和藝術。"},{"en":"Support for the arts can help creative workers produce better work.","zh":"對藝術的支持可以幫助創作者創作更好作品。"},{"en":"The phrase connects people in performance with broader creative culture.","zh":"這個短語把表演者與更廣泛創意文化連起來。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":13},{"front":"become the leading contender","meaning":"成為主要競爭者","examples":[{"en":"Edward de Vere has become the leading contender among alternative candidates.","zh":"Edward de Vere 已成為替代候選人中的主要競爭者。"},{"en":"To become the leading contender means to become the strongest or most supported candidate.","zh":"become the leading contender 指成為最有力或最受支持的候選人。"},{"en":"A student may become the leading contender for a scholarship after excellent interview results.","zh":"學生在面試表現優秀後，可能成為獎學金的主要競爭者。"},{"en":"A candidate becomes leading when more arguments and supporters gather around him.","zh":"當更多論點和支持者集中於某候選人，他就成為主要競爭者。"},{"en":"The phrase describes rising to first place among rivals.","zh":"這個短語描述在對手之中升至首位。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":13},{"front":"only slightly less favoured","meaning":"受支持程度只稍低","examples":[{"en":"Marlowe is only slightly less favoured than Edward de Vere.","zh":"Marlowe 的受支持程度只比 Edward de Vere 稍低。"},{"en":"Only slightly less favoured means supported almost as much, but a little less.","zh":"only slightly less favoured 指受支持程度幾乎一樣，只是少一點。"},{"en":"In a class vote, one candidate may be only slightly less favoured than the winner.","zh":"在班級投票中，一名候選人的支持度可能只比勝出者稍低。"},{"en":"A theory can remain important even if it is slightly less popular than another.","zh":"即使某理論比另一理論稍為不受歡迎，它仍可以重要。"},{"en":"The phrase compares support with a small difference.","zh":"這個短語比較支持度上的小差異。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":13},{"front":"fellow playwright","meaning":"同行劇作家","examples":[{"en":"Christopher Marlowe was a fellow playwright.","zh":"Christopher Marlowe 是一位同行劇作家。"},{"en":"A fellow playwright is another writer of plays from the same profession or period.","zh":"fellow playwright 指同一職業或時期的另一位劇作家。"},{"en":"Fellow playwrights may know similar theatre companies, actors, and audiences.","zh":"同行劇作家可能認識相似的劇團、演員和觀眾。"},{"en":"Because Marlowe was a playwright, supporters can more easily imagine him writing dramatic works.","zh":"因為 Marlowe 是劇作家，支持者較容易想像他寫出戲劇作品。"},{"en":"The phrase stresses shared literary work.","zh":"這個短語強調共同的文學工作。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":13},{"front":"be born into","meaning":"出生於","examples":[{"en":"Marlowe was born into the same social class as Shakespeare.","zh":"Marlowe 出生於與莎士比亞相同的社會階層。"},{"en":"To be born into a class or family means to enter that social position at birth.","zh":"be born into a class or family 指出生時就進入某社會地位或家庭。"},{"en":"A child born into a farming family may learn about crops from an early age.","zh":"出生於農民家庭的孩子可能從小學到農作物知識。"},{"en":"Social background can affect education, contacts, and opportunities.","zh":"社會背景可以影響教育、人脈和機會。"},{"en":"The phrase describes inherited starting conditions.","zh":"這個短語描述出生時承繼的起點條件。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":13},{"front":"the same social class as","meaning":"與……相同的社會階層","examples":[{"en":"Marlowe came from the same social class as Shakespeare.","zh":"Marlowe 來自與莎士比亞相同的社會階層。"},{"en":"The same social class as someone means belonging to a similar social rank or economic background.","zh":"same social class as someone 指屬於相似社會地位或經濟背景。"},{"en":"Two students from the same social class may share similar access to schools and books.","zh":"來自相同社會階層的兩名學生，可能有相似的學校和書本資源。"},{"en":"If Marlowe came from the same class but went to university, supporters may compare him with Shakespeare.","zh":"如果 Marlowe 來自相同階層但上過大學，支持者可能把他與莎士比亞比較。"},{"en":"The phrase is used for social comparison.","zh":"這個短語用於社會比較。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":14},{"front":"go to university","meaning":"上大學","examples":[{"en":"Marlowe went to university, unlike Shakespeare as far as records show.","zh":"根據紀錄，Marlowe 上過大學，而莎士比亞沒有。"},{"en":"To go to university means to study at a university.","zh":"go to university 指在大學學習。"},{"en":"A student may go to university to study law, medicine, literature, or science.","zh":"學生可能上大學修讀法律、醫學、文學或科學。"},{"en":"University education can provide access to books, languages, and scholarly networks.","zh":"大學教育可以提供書本、語言和學術網絡的接觸機會。"},{"en":"The phrase describes formal higher education.","zh":"這個短語描述正式高等教育。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":14},{"front":"early death","meaning":"早逝","examples":[{"en":"Marlowe’s early death creates difficulties for the theory.","zh":"Marlowe 的早逝為該理論造成困難。"},{"en":"Early death means dying at a young age or before expected.","zh":"early death 指年輕時或早於預期死亡。"},{"en":"A musician’s early death may leave many unfinished songs.","zh":"音樂人的早逝可能留下許多未完成歌曲。"},{"en":"If a proposed author died before some works were written, supporters must explain the timeline.","zh":"如果被提出的作者在某些作品寫成前已死亡，支持者必須解釋時間線。"},{"en":"The phrase focuses on death happening too soon for later events.","zh":"這個短語重點是死亡發生得太早，無法配合後來事件。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":14},{"front":"tavern brawl","meaning":"酒館打鬥","examples":[{"en":"Marlowe died in a tavern brawl.","zh":"Marlowe 死於一場酒館打鬥。"},{"en":"A tavern brawl is a fight in an inn, pub, or drinking place.","zh":"tavern brawl 指在旅店、酒館或飲酒場所發生的打鬥。"},{"en":"Police may be called if a tavern brawl becomes violent.","zh":"如果酒館打鬥變得暴力，警方可能被召喚。"},{"en":"If a writer dies in a tavern brawl, the sudden death may become part of later mystery.","zh":"如果作家死於酒館打鬥，突然死亡可能成為後來謎團的一部分。"},{"en":"The phrase describes a rough public fight.","zh":"這個短語描述粗暴的公開打鬥。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":14},{"front":"present difficulties","meaning":"造成困難","examples":[{"en":"Marlowe’s death presents difficulties for his supporters.","zh":"Marlowe 的死亡為其支持者造成困難。"},{"en":"To present difficulties means to create problems or obstacles.","zh":"present difficulties 指造成問題或障礙。"},{"en":"A missing receipt presents difficulties when a customer wants a refund.","zh":"如果顧客想退款但缺少收據，就會造成困難。"},{"en":"A death date can present difficulties if a theory requires the person to write later works.","zh":"如果理論要求某人在死亡日期後仍寫作，死亡日期就會造成困難。"},{"en":"The phrase shows that something makes an argument harder to maintain.","zh":"這個短語顯示某事令論點更難維持。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":14},{"front":"unless one assumes","meaning":"除非有人假設","examples":[{"en":"The theory fails unless one assumes Marlowe’s death was faked.","zh":"除非有人假設 Marlowe 的死亡是偽造的，否則該理論不能成立。"},{"en":"Unless one assumes means except if someone accepts a particular unproven idea.","zh":"unless one assumes 指除非有人接受某個未證實的想法。"},{"en":"The timetable does not make sense unless one assumes the meeting was moved earlier.","zh":"除非有人假設會議提前了，否則時間表說不通。"},{"en":"A theory becomes weaker when it depends on extra assumptions without evidence.","zh":"當理論依賴沒有證據的額外假設，它會變弱。"},{"en":"The phrase introduces a condition needed to save an argument.","zh":"這個短語引入挽救論點所需的條件。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":14},{"front":"demise","meaning":"死亡","examples":[{"en":"Some supporters claim that Marlowe’s demise was fabricated.","zh":"一些支持者聲稱 Marlowe 的死亡被捏造。"},{"en":"Demise is a formal word for death or ending.","zh":"demise 是表示死亡或終結的正式詞語。"},{"en":"A newspaper may report the demise of a public figure in formal language.","zh":"報紙可能以正式語言報道公眾人物的死亡。"},{"en":"If someone claims a demise was faked, they are saying the death did not really happen.","zh":"如果有人聲稱死亡被偽造，他們就是說死亡並沒有真正發生。"},{"en":"The word is more formal than death.","zh":"這個詞比 death 更正式。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":14},{"front":"be fabricated","meaning":"被捏造","examples":[{"en":"Some theorists suggest that Marlowe’s death was fabricated.","zh":"一些理論家暗示 Marlowe 的死亡被捏造。"},{"en":"To be fabricated means to be invented or falsely created.","zh":"be fabricated 指被編造或虛假製造。"},{"en":"A student’s excuse may be fabricated if the story keeps changing.","zh":"如果學生的藉口不斷改變，故事可能是捏造的。"},{"en":"If a death record is fabricated, then the official story is false.","zh":"如果死亡記錄被捏造，官方故事就是假的。"},{"en":"The phrase suggests deliberate falsehood.","zh":"這個短語暗示故意造假。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":14},{"front":"allow someone to","meaning":"讓某人能夠","examples":[{"en":"The fake-death theory would allow Marlowe to continue writing.","zh":"假死理論會讓 Marlowe 能夠繼續寫作。"},{"en":"To allow someone to do something means to make it possible or permitted for them to do it.","zh":"allow someone to do something 指使某人可以或獲准做某事。"},{"en":"Online lessons allow students to study even when they cannot travel to school.","zh":"網上課程讓學生即使不能到校也能學習。"},{"en":"In this theory, a fake death would allow a writer to hide and keep producing work.","zh":"在這個理論中，假死會讓作家能夠隱藏並繼續創作。"},{"en":"The phrase can describe permission or practical possibility.","zh":"這個短語可以描述許可或實際可能性。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":14},{"front":"under Shakespeare’s name","meaning":"以Shakespeare的名義","examples":[{"en":"Marlowe supposedly continued writing under Shakespeare’s name.","zh":"Marlowe 據稱以莎士比亞的名義繼續寫作。"},{"en":"Under someone’s name means using that person’s name as the public author or identity.","zh":"under someone’s name 指使用某人的名字作為公開作者或身份。"},{"en":"A ghostwriter may publish a speech under a politician’s name.","zh":"代筆人可能以政治家的名義發表演講。"},{"en":"If works are written under another person’s name, true authorship becomes hidden.","zh":"如果作品以另一人的名義寫成，真正作者身份就被隱藏。"},{"en":"The phrase focuses on public attribution.","zh":"這個短語重點是公開署名。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":14},{"front":"contemporary accounts","meaning":"同時代記載","examples":[{"en":"Contemporary accounts say that William Stanley wrote plays.","zh":"同時代記載說 William Stanley 寫過劇作。"},{"en":"Contemporary accounts are reports or descriptions written by people living at the same time as the events.","zh":"contemporary accounts 指由與事件同時代的人寫下的報告或描述。"},{"en":"Contemporary accounts of a school’s founding may include letters, diaries, and local newspapers.","zh":"關於學校創立的同時代記載可能包括信件、日記和地方報紙。"},{"en":"Such accounts are valuable because they are close in time to the events described.","zh":"這些記載有價值，因為它們在時間上接近所描述事件。"},{"en":"The phrase refers to period evidence, not later imagination.","zh":"這個短語指時代證據，而不是後來想像。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":14},{"front":"attest to the fact that","meaning":"證明……這一事實","examples":[{"en":"Contemporary accounts attest to the fact that Stanley wrote plays.","zh":"同時代記載證明 Stanley 寫過劇作這一事實。"},{"en":"To attest to the fact that something happened means to give evidence or testimony that it happened.","zh":"attest to the fact that something happened 指提供證據或證言表明某事發生。"},{"en":"Hospital records can attest to the fact that a patient received treatment.","zh":"醫院記錄可以證明病人接受過治療這一事實。"},{"en":"If accounts attest that someone wrote plays, they support the claim with recorded testimony.","zh":"如果記載證明某人寫過劇作，它們就以紀錄證言支持該聲稱。"},{"en":"The phrase is formal and evidence-focused.","zh":"這個短語較正式，重點是證據。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":15},{"front":"for the common people","meaning":"為平民百姓","examples":[{"en":"Stanley was said to have written plays for the common people.","zh":"據說 Stanley 為平民百姓寫劇本。"},{"en":"For the common people means intended for ordinary people rather than elite audiences.","zh":"for the common people 指為普通人而設，而不是為精英觀眾而設。"},{"en":"A public library is built for the common people, not only scholars.","zh":"公共圖書館是為平民百姓而建，而不只是為學者而建。"},{"en":"Plays for common audiences may use accessible language, humour, and popular stories.","zh":"面向普通觀眾的劇作可能使用易懂語言、幽默和流行故事。"},{"en":"The phrase contrasts ordinary audiences with upper-class or courtly groups.","zh":"這個短語把普通觀眾與上流或宮廷群體作對比。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":15},{"front":"throughout his life","meaning":"在他一生中","examples":[{"en":"Throughout his life, Stanley supported the theatre.","zh":"Stanley 在他一生中支持戲劇界。"},{"en":"Throughout his life means during all or most of his lifetime.","zh":"throughout his life 指在他一生全部或大部分時間。"},{"en":"Throughout her life, a teacher may remain committed to helping poor students.","zh":"老師可能在一生中都致力幫助貧困學生。"},{"en":"If someone supports theatre throughout life, the interest is not just a short hobby.","zh":"如果某人一生支持戲劇，那興趣就不只是短暫嗜好。"},{"en":"The phrase stresses long-term continuity.","zh":"這個短語強調長期持續。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":15},{"front":"display interest in","meaning":"表現出對……的興趣","examples":[{"en":"Stanley displayed interest in the theatre.","zh":"Stanley 表現出對戲劇界的興趣。"},{"en":"To display interest in something means to show curiosity, involvement, or support for it.","zh":"display interest in something 指顯示對某事的好奇、參與或支持。"},{"en":"A student displays interest in science when she asks questions after class.","zh":"學生課後提問，就是表現出對科學的興趣。"},{"en":"Repeated support for theatre can display genuine interest in dramatic art.","zh":"反覆支持戲劇可以顯示對戲劇藝術的真正興趣。"},{"en":"The phrase focuses on visible signs of interest.","zh":"這個短語重點是可見的興趣跡象。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":15},{"front":"support for the theatre","meaning":"對戲劇界的支持","examples":[{"en":"Stanley displayed support for the theatre throughout his life.","zh":"Stanley 在一生中都表現出對戲劇界的支持。"},{"en":"Support for the theatre means help, money, attention, or encouragement given to theatrical activity.","zh":"support for the theatre 指給予戲劇活動的幫助、金錢、關注或鼓勵。"},{"en":"A city shows support for the theatre when it funds local performances.","zh":"城市資助本地演出時，就是顯示對戲劇界的支持。"},{"en":"Long-term support for theatre can make someone seem connected to playwriting and performance.","zh":"對戲劇的長期支持可以令某人看起來與劇本創作和演出有關。"},{"en":"The phrase refers to backing the theatre world.","zh":"這個短語指支持戲劇世界。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":15},{"front":"mere historical and literary conjecture","meaning":"純粹的歷史和文學猜測","examples":[{"en":"The evidence is described as mere historical and literary conjecture.","zh":"這些證據被描述為純粹的歷史和文學猜測。"},{"en":"Mere historical and literary conjecture means only guesses based on history and literature, not solid proof.","zh":"mere historical and literary conjecture 指只基於歷史和文學的猜想，而不是實質證明。"},{"en":"A theory about a lost poem may be conjecture if no manuscript or document supports it.","zh":"如果沒有手稿或文件支持，關於失傳詩作的理論可能只是猜測。"},{"en":"Conjecture can be interesting, but it should not be treated as established fact.","zh":"猜測可以有趣，但不應被視為既定事實。"},{"en":"The phrase is critical and suggests weak evidence.","zh":"這個短語帶批評意味，暗示證據薄弱。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":15},{"front":"vague similarities","meaning":"含糊的相似之處","examples":[{"en":"The case relies partly on vague similarities in writing styles.","zh":"這個論點部分依賴寫作風格上的含糊相似之處。"},{"en":"Vague similarities are unclear or weak likenesses that are not precise enough to prove much.","zh":"vague similarities 指不清楚或薄弱的相似，精確度不足以證明太多。"},{"en":"Two essays may have vague similarities because both use common phrases.","zh":"兩篇作文可能因為都使用常見短語而有含糊相似之處。"},{"en":"If a theory rests on vague similarities, stronger evidence is still needed.","zh":"如果理論依靠含糊相似之處，仍需要更強證據。"},{"en":"The phrase suggests resemblance without solid proof.","zh":"這個短語暗示有相似，但沒有實質證明。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":15},{"front":"writing styles","meaning":"寫作風格","examples":[{"en":"Supporters compare similarities in writing styles.","zh":"支持者比較寫作風格中的相似之處。"},{"en":"Writing styles are the typical ways writers use words, sentences, tone, structure, and imagery.","zh":"writing styles 指作家使用字詞、句子、語氣、結構和意象的典型方式。"},{"en":"A teacher can recognise a student’s writing style if the student always uses short direct sentences.","zh":"如果學生總是使用短而直接的句子，老師可能認出他的寫作風格。"},{"en":"Comparing writing styles may give clues, but it does not automatically prove authorship.","zh":"比較寫作風格可能提供線索，但不會自動證明作者身份。"},{"en":"The phrase refers to patterns in how someone writes.","zh":"這個短語指某人寫作方式中的模式。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":15},{"front":"loose coincidences","meaning":"牽強的巧合","examples":[{"en":"The arguments depend on loose coincidences rather than proof.","zh":"這些論點依靠牽強的巧合，而不是證據。"},{"en":"Loose coincidences are weak chance similarities that do not firmly show a real connection.","zh":"loose coincidences 指薄弱的偶然相似，不能有力顯示真正關連。"},{"en":"Two students may both mention rain in essays, but that may be a loose coincidence.","zh":"兩名學生作文中都提到雨，但那可能只是牽強巧合。"},{"en":"If arguments rely on loose coincidences, they can sound clever but remain unconvincing.","zh":"如果論點依賴牽強巧合，它們可能聽起來聰明，但仍不令人信服。"},{"en":"The phrase criticises connections that are too weak.","zh":"這個短語批評太薄弱的連結。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":15},{"front":"link A to B","meaning":"將A與B聯繫起來","examples":[{"en":"Some theories link the lives of candidates to scenes in the plays.","zh":"一些理論把候選人的生平與劇中場景聯繫起來。"},{"en":"To link A to B means to connect one thing with another.","zh":"link A to B 指把一件事與另一件事連起來。"},{"en":"A teacher may link a grammar mistake to lack of proofreading.","zh":"老師可能把文法錯誤與缺乏校對聯繫起來。"},{"en":"If a theory links a candidate’s travel to a play setting, it must show the connection is meaningful.","zh":"如果理論把候選人的遊歷與劇作背景聯繫起來，它必須顯示該連結有意義。"},{"en":"The phrase describes making a connection between two things.","zh":"這個短語描述在兩件事之間建立關連。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":15},{"front":"lives and travels","meaning":"生平和遊歷","examples":[{"en":"The contenders’ lives and travels are compared with play settings.","zh":"候選人的生平和遊歷被拿來與劇作背景比較。"},{"en":"Lives and travels mean people’s personal histories and the places they visited.","zh":"lives and travels 指人們的個人歷史以及他們到訪過的地方。"},{"en":"A biography may describe a writer’s life and travels to explain influences on his work.","zh":"傳記可能描述作家的生平和遊歷，以解釋其作品受到的影響。"},{"en":"If a candidate visited a place similar to a play setting, supporters may use it as a clue.","zh":"如果候選人到訪過與劇作背景相似的地方，支持者可能把它當作線索。"},{"en":"The phrase combines biography with movement between places.","zh":"這個短語結合傳記與地點移動。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":15},{"front":"contenders","meaning":"競爭者；候選人","examples":[{"en":"The passage discusses several contenders for the authorship of the plays.","zh":"文章討論幾位劇作作者身份的候選人。"},{"en":"Contenders are people or options competing for a position, title, or explanation.","zh":"contenders 指競爭某位置、稱號或解釋的人或選項。"},{"en":"In a school debate, several students may be contenders for best speaker.","zh":"在學校辯論中，幾名學生可能是最佳辯手的競爭者。"},{"en":"In an authorship dispute, each contender is proposed as the possible writer.","zh":"在作者身份爭論中，每位競爭者都被提出為可能作者。"},{"en":"The word means candidates with some level of support.","zh":"這個詞指有一定支持度的候選人。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":16},{"front":"scenes and settings","meaning":"場景和背景","examples":[{"en":"The plays contain scenes and settings linked loosely to the candidates.","zh":"劇作包含被牽強地與候選人聯繫起來的場景和背景。"},{"en":"Scenes and settings are the particular moments and places where a story happens.","zh":"scenes and settings 指故事發生的特定時刻和地點。"},{"en":"A film may have school scenes, home scenes, and settings in different cities.","zh":"電影可能有校園場景、家庭場景和不同城市背景。"},{"en":"If a candidate’s travels match a setting, supporters may claim a connection.","zh":"如果候選人的遊歷與某背景相符，支持者可能聲稱有關連。"},{"en":"The phrase covers both action moments and background locations.","zh":"這個短語涵蓋行動場面和背景地點。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":16},{"front":"in question","meaning":"正被討論的；有關的","examples":[{"en":"The plays in question are traditionally attributed to Shakespeare.","zh":"有關劇作傳統上被歸於莎士比亞。"},{"en":"In question means being discussed, examined, or referred to.","zh":"in question 指正在被討論、檢視或提及。"},{"en":"The rule in question applies only to final exams, not homework.","zh":"有關規則只適用於期末考試，而不是功課。"},{"en":"When writers say the documents in question, they mean the specific documents under discussion.","zh":"當作者說 documents in question，他們指正在討論的特定文件。"},{"en":"The phrase narrows attention to the relevant item.","zh":"這個短語把注意力收窄至相關項目。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":16},{"front":"nothing solid at all","meaning":"完全沒有實質證據","examples":[{"en":"The writer says there is nothing solid at all in the alternative theories.","zh":"作者說替代理論完全沒有實質證據。"},{"en":"Nothing solid at all means no reliable evidence or firm basis whatsoever.","zh":"nothing solid at all 指完全沒有可靠證據或堅實基礎。"},{"en":"A rumour about a school closure has nothing solid at all if no official notice exists.","zh":"如果沒有官方通知，關於學校停辦的傳聞就完全沒有實質證據。"},{"en":"Without solid evidence, a theory may remain interesting but unproven.","zh":"沒有實質證據，理論可能有趣但仍未被證明。"},{"en":"The phrase strongly rejects the strength of the evidence.","zh":"這個短語強烈否定證據力度。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":16},{"front":"so flimsy that","meaning":"如此薄弱以致","examples":[{"en":"The case is so flimsy that scholars barely discuss it.","zh":"這個論點如此薄弱，以致學者幾乎不討論它。"},{"en":"So flimsy that means so weak that a particular result follows.","zh":"so flimsy that 指如此薄弱，以致產生某結果。"},{"en":"His excuse was so flimsy that the teacher immediately asked for the truth.","zh":"他的藉口如此薄弱，以致老師立刻要求他說實話。"},{"en":"If evidence is so flimsy, serious researchers may not spend much time on it.","zh":"如果證據如此薄弱，嚴肅研究人員可能不會花太多時間在它上面。"},{"en":"The phrase links extreme weakness with consequence.","zh":"這個短語把極度薄弱與後果連起來。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":16},{"front":"reputable scholars","meaning":"有聲望的學者","examples":[{"en":"Reputable scholars rarely take the authorship theories seriously.","zh":"有聲望的學者很少認真看待作者身份理論。"},{"en":"Reputable scholars are respected researchers with strong academic standards.","zh":"reputable scholars 指有良好學術標準並受尊重的研究人員。"},{"en":"Reputable scholars check sources carefully before accepting a claim.","zh":"有聲望的學者在接受聲稱前會仔細查核來源。"},{"en":"If reputable scholars barely discuss a theory, they may find the evidence too weak.","zh":"如果有聲望的學者幾乎不討論某理論，他們可能認為證據太薄弱。"},{"en":"The phrase refers to credible academic experts.","zh":"這個短語指可信的學術專家。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":16},{"front":"barely discuss","meaning":"幾乎不討論","examples":[{"en":"Most reputable scholars barely discuss the authorship question.","zh":"大多數有聲望的學者幾乎不討論作者身份問題。"},{"en":"To barely discuss something means to mention it very little or almost not at all.","zh":"barely discuss something 指很少提及或幾乎完全不討論某事。"},{"en":"A teacher may barely discuss a rare grammar point if it is unlikely to appear in exams.","zh":"如果某文法點很少出現在考試中，老師可能幾乎不討論它。"},{"en":"Scholars may barely discuss a theory when they think it lacks serious evidence.","zh":"當學者認為某理論缺乏嚴肅證據，他們可能幾乎不討論它。"},{"en":"The phrase suggests very limited attention.","zh":"這個短語暗示非常有限的關注。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":16},{"front":"rightly so","meaning":"這樣做是對的","examples":[{"en":"The writer says that scholars ignore the case, and rightly so.","zh":"作者說學者忽視這個論點，而這樣做是對的。"},{"en":"Rightly so means this action or judgement is correct or justified.","zh":"rightly so 指這個行動或判斷是正確或合理的。"},{"en":"The school cancelled the outdoor trip during a storm, and rightly so.","zh":"學校在暴風期間取消戶外旅行，而這樣做是對的。"},{"en":"If evidence is weak, scholars may ignore the theory, and rightly so.","zh":"如果證據薄弱，學者可能忽視該理論，而這樣做是對的。"},{"en":"The phrase clearly supports the judgement just mentioned.","zh":"這個短語明確支持剛提到的判斷。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":16},{"front":"capable of attracting","meaning":"能夠吸引","examples":[{"en":"The debate is capable of attracting public interest.","zh":"這場爭論能夠吸引公眾興趣。"},{"en":"Capable of attracting something means able to draw or gain it.","zh":"capable of attracting something 指有能力吸引或獲得某物。"},{"en":"A well-designed poster is capable of attracting students to a school event.","zh":"設計良好的海報能夠吸引學生參加學校活動。"},{"en":"A mystery about a famous writer can attract readers even if experts reject it.","zh":"關於著名作家的謎團即使被專家否定，也可以吸引讀者。"},{"en":"The phrase focuses on ability to draw attention.","zh":"這個短語重點是吸引注意的能力。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":16},{"front":"public interest","meaning":"公眾興趣","examples":[{"en":"The authorship question attracts public interest.","zh":"作者身份問題吸引公眾興趣。"},{"en":"Public interest means attention, curiosity, or concern from ordinary people or society as a whole.","zh":"public interest 指普通人或整個社會的關注、好奇或重視。"},{"en":"A missing historical document can attract public interest if it concerns a famous person.","zh":"如果失蹤歷史文件涉及名人，它可以吸引公眾興趣。"},{"en":"Public interest does not always mean a theory is academically strong.","zh":"公眾興趣不一定表示某理論在學術上有力。"},{"en":"The phrase describes popular attention.","zh":"這個短語描述大眾關注。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":16},{"front":"selling books","meaning":"賣書；促進書籍銷售","examples":[{"en":"The controversy can help authors sell books.","zh":"這場爭議可以幫助作者賣書。"},{"en":"Selling books means earning money or gaining readers through book sales.","zh":"selling books 指透過書籍銷售賺錢或獲得讀者。"},{"en":"A dramatic title can help an author sell books even before readers check the evidence.","zh":"戲劇性的標題可以在讀者查核證據前就幫作者賣書。"},{"en":"Controversies often sell books because people enjoy mysteries and arguments.","zh":"爭議通常能促進書籍銷售，因為人們喜歡謎團和爭論。"},{"en":"The phrase focuses on commercial success.","zh":"這個短語重點是商業成功。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":16},{"front":"unless some real evidence emerges","meaning":"除非有真正證據出現","examples":[{"en":"Unless some real evidence emerges, the authorship question remains weak.","zh":"除非有真正證據出現，作者身份問題仍然薄弱。"},{"en":"Unless some real evidence emerges means except if solid proof appears later.","zh":"unless some real evidence emerges 指除非之後出現實質證明。"},{"en":"Unless real evidence emerges, the rumour about the school closing should not be believed.","zh":"除非有真正證據出現，關於學校停辦的傳聞不應被相信。"},{"en":"A theory can remain possible in imagination but weak without new evidence.","zh":"沒有新證據，理論可以在想像中仍可能，但依然薄弱。"},{"en":"The phrase sets the condition needed for serious reconsideration.","zh":"這個短語設定認真重新考慮所需的條件。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":17},{"front":"real evidence","meaning":"真正證據","examples":[{"en":"The writer demands real evidence before accepting the theory.","zh":"作者要求有真正證據，才接受該理論。"},{"en":"Real evidence means reliable proof, not guesses, rumours, or coincidences.","zh":"real evidence 指可靠證明，而不是猜測、傳聞或巧合。"},{"en":"A teacher needs real evidence before accusing a student of plagiarism.","zh":"老師在指控學生抄襲前需要真正證據。"},{"en":"Real evidence can include documents, records, verified testimony, or physical materials.","zh":"真正證據可以包括文件、記錄、已核實證言或實物材料。"},{"en":"The phrase stresses proof that can support a serious claim.","zh":"這個短語強調能支持嚴肅聲稱的證明。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":17},{"front":"not questionable at all","meaning":"根本不值得質疑","examples":[{"en":"The writer concludes that the authorship question is not questionable at all.","zh":"作者總結指作者身份問題根本不值得質疑。"},{"en":"Not questionable at all means not open to serious doubt or challenge.","zh":"not questionable at all 指不應受到嚴肅懷疑或挑戰。"},{"en":"If attendance records clearly show a student was present, that fact may be not questionable at all.","zh":"如果出席紀錄清楚顯示學生在場，該事實可能根本不值得質疑。"},{"en":"The phrase shows the writer thinks the debate lacks a real basis.","zh":"這個短語顯示作者認為該爭論缺乏真正基礎。"},{"en":"It is a strong way to reject doubt.","zh":"它是強烈否定疑問的說法。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":17},{"front":"write TRUE, FALSE, or NOT GIVEN","meaning":"寫上TRUE、FALSE或NOT GIVEN","examples":[{"en":"Candidates write TRUE, FALSE, or NOT GIVEN for each statement.","zh":"考生為每項陳述寫上 TRUE、FALSE 或 NOT GIVEN。"},{"en":"This instruction means students must decide whether each statement matches, contradicts, or is not covered by the passage.","zh":"這個指示表示學生必須判斷每項陳述是否與文章相符、相矛盾，或文中沒有提及。"},{"en":"If the passage clearly supports a statement, the answer is TRUE.","zh":"如果文章清楚支持某陳述，答案就是 TRUE。"},{"en":"If the passage gives the opposite information, the answer is FALSE.","zh":"如果文章提供相反資料，答案就是 FALSE。"},{"en":"If the passage does not say enough, the answer is NOT GIVEN.","zh":"如果文章沒有說明足夠資料，答案就是 NOT GIVEN。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":17},{"front":"agree with the information","meaning":"與資料一致","examples":[{"en":"A statement is TRUE if it agrees with the information in the passage.","zh":"如果陳述與文章中的資料一致，它就是 TRUE。"},{"en":"To agree with the information means to match what the text says.","zh":"agree with the information 指與文本所說內容相符。"},{"en":"If the passage says a theory appeared in the 19th century and the statement says the same, it agrees.","zh":"如果文章說某理論在19世紀出現，而陳述也這樣說，它就是一致。"},{"en":"Students should check wording carefully because a small change can alter meaning.","zh":"學生應仔細檢查措辭，因為小改動可以改變意思。"},{"en":"The phrase is common in TRUE, FALSE, NOT GIVEN tasks.","zh":"這個短語常見於 TRUE、FALSE、NOT GIVEN 題目。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":17},{"front":"contradict the information","meaning":"與資料矛盾","examples":[{"en":"A statement is FALSE if it contradicts the information in the passage.","zh":"如果陳述與文章資料矛盾，它就是 FALSE。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"contradict the information 指說出與文本相反的內容。"},{"en":"If the passage says evidence exists and the statement says no evidence exists, it contradicts the information.","zh":"如果文章說證據存在，而陳述說沒有證據存在，它就是與資料矛盾。"},{"en":"Students should choose FALSE only when there is a clear conflict.","zh":"學生只有在有清楚衝突時才應選 FALSE。"},{"en":"The phrase means disagreement with the text, not missing information.","zh":"這個短語表示與文本不同，而不是資料缺失。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":17},{"front":"there is no information on this","meaning":"文中沒有相關資料","examples":[{"en":"Candidates write NOT GIVEN if there is no information on this.","zh":"如果文中沒有相關資料，考生寫 NOT GIVEN。"},{"en":"There is no information on this means the passage does not state whether the idea is true or false.","zh":"there is no information on this 指文章沒有說明該想法是真是假。"},{"en":"If the passage describes Shakespeare’s will but not his favourite food, there is no information on the food.","zh":"如果文章描述莎士比亞的遺囑，但沒有提到他最愛的食物，就沒有相關資料。"},{"en":"Students should not use outside knowledge to fill missing information.","zh":"學生不應用外部知識填補缺失資料。"},{"en":"The phrase warns against guessing beyond the passage.","zh":"這個短語提醒不要超出文章猜測。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":17},{"front":"appear on many documents","meaning":"出現在許多文件上","examples":[{"en":"The statement asks whether Shakespeare’s name appears on many documents.","zh":"該陳述問莎士比亞的名字是否出現在許多文件上。"},{"en":"To appear on many documents means to be written or printed in several records.","zh":"appear on many documents 指被寫或印在多份記錄上。"},{"en":"A student’s name may appear on many school documents, such as reports, certificates, and attendance lists.","zh":"學生的名字可能出現在許多學校文件上，例如成績表、證書和出席名單。"},{"en":"If a name appears on many documents, it can support identification or authorship.","zh":"如果名字出現在許多文件上，它可以支持身份或作者身份判斷。"},{"en":"The phrase focuses on visible written evidence.","zh":"這個短語重點是可見書面證據。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":17},{"front":"be considered a genius","meaning":"被認為是天才","examples":[{"en":"The statement asks whether Shakespeare was considered a genius in his lifetime.","zh":"該陳述問莎士比亞在有生之年是否被認為是天才。"},{"en":"To be considered a genius means to be regarded as having extraordinary ability.","zh":"be considered a genius 指被視為具有非凡能力。"},{"en":"A young musician may be considered a genius if she composes complex music easily.","zh":"如果年輕音樂人能輕易創作複雜音樂，她可能被認為是天才。"},{"en":"Being famous is not always the same as being considered a genius.","zh":"出名不一定等於被認為是天才。"},{"en":"The phrase focuses on how others judge someone’s ability.","zh":"這個短語重點是他人如何判斷某人的能力。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":17},{"front":"in his lifetime","meaning":"在他有生之年","examples":[{"en":"The question asks about Shakespeare’s reputation in his lifetime.","zh":"題目問莎士比亞在他有生之年的聲譽。"},{"en":"In his lifetime means during the time when he was alive.","zh":"in his lifetime 指在他仍然在世的時期。"},{"en":"Some writers receive little attention in their lifetime but become famous later.","zh":"有些作家在有生之年很少受到關注，但後來成名。"},{"en":"Evidence about reputation in a person’s lifetime helps separate contemporary fame from later fame.","zh":"關於某人在世聲譽的證據，有助區分同時代名聲和後世名聲。"},{"en":"The phrase contrasts living recognition with posthumous reputation.","zh":"這個短語把在世認可與死後名聲作對比。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":17},{"front":"be well-educated","meaning":"受過良好教育","examples":[{"en":"The question asks whether Shakespeare was well-educated.","zh":"題目問莎士比亞是否受過良好教育。"},{"en":"To be well-educated means to have received strong formal or intellectual training.","zh":"be well-educated 指接受過良好正規或智識訓練。"},{"en":"A well-educated person may know languages, history, literature, and logic.","zh":"受過良好教育的人可能懂語言、歷史、文學和邏輯。"},{"en":"If records of schooling are missing, it may be hard to prove whether someone was well-educated.","zh":"如果學校教育記錄缺失，就可能難以證明某人是否受過良好教育。"},{"en":"The phrase focuses on quality and depth of education.","zh":"這個短語重點是教育質素和深度。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":17},{"front":"not all the plays had been published","meaning":"並非所有劇作都已出版","examples":[{"en":"The statement says that not all the plays had been published when he died.","zh":"該陳述說他死時並非所有劇作都已出版。"},{"en":"Not all the plays had been published means some plays were still unpublished at that time.","zh":"not all the plays had been published 指當時仍有部分劇作未出版。"},{"en":"Not all the class notes had been uploaded when students started revising.","zh":"當學生開始溫習時，並非所有課堂筆記都已上載。"},{"en":"If not all works were published before death, papers and rights might be expected in the will.","zh":"如果死前並非所有作品都已出版，人們可能預期遺囑中會提到文件和權利。"},{"en":"The phrase expresses partial publication, not total absence.","zh":"這個短語表達部分出版，而不是完全沒有出版。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":18},{"front":"complete the sentences","meaning":"完成句子","examples":[{"en":"Candidates complete the sentences using words from the passage.","zh":"考生使用文章中的字詞完成句子。"},{"en":"To complete the sentences means to fill in missing words so the sentences become whole and grammatical.","zh":"complete the sentences 指填上缺失字詞，使句子完整並符合文法。"},{"en":"Students should use the exact word form required by the sentence.","zh":"學生應使用句子所需的準確詞形。"},{"en":"Completion questions test meaning, grammar, and careful locating of information.","zh":"完成句子題測試意思、文法和仔細定位資料。"},{"en":"The phrase is an exam instruction.","zh":"這個短語是考試指示。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":18},{"front":"choose one word","meaning":"選擇一個字","examples":[{"en":"Candidates choose one word from the passage for each answer.","zh":"考生為每個答案從文章中選擇一個字。"},{"en":"Choose one word means select exactly a single word, not a phrase.","zh":"choose one word 指準確選擇一個詞，而不是短語。"},{"en":"If the answer space allows one word, writing two words can lose marks.","zh":"如果答案格只容許一個詞，寫兩個詞可能失分。"},{"en":"Students must check whether the word fits grammatically in the sentence.","zh":"學生必須檢查該詞在句子中是否符合文法。"},{"en":"The phrase sets a strict answer length.","zh":"這個短語設定嚴格答案長度。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":18},{"front":"examples of","meaning":"……的例子","examples":[{"en":"The question asks about six examples of Shakespeare’s signatures.","zh":"題目問莎士比亞簽名的六個例子。"},{"en":"Examples of something are particular cases that show or represent that thing.","zh":"examples of something 指顯示或代表某事的具體個案。"},{"en":"A teacher may give examples of strong introductions before students write essays.","zh":"老師可能在學生寫作文前提供優秀引言的例子。"},{"en":"Six examples of signatures can help people compare handwriting patterns.","zh":"六個簽名例子可以幫助人們比較筆跡模式。"},{"en":"The phrase introduces specific instances.","zh":"這個短語引入具體例子。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":18},{"front":"ordinary language","meaning":"普通語言","examples":[{"en":"The question refers to the ordinary language used in Shakespeare’s will.","zh":"題目提到莎士比亞遺囑中使用的普通語言。"},{"en":"Ordinary language is plain, everyday wording rather than poetic or specialised language.","zh":"ordinary language 指平實日常用語，而不是詩意或專門語言。"},{"en":"A school notice should use ordinary language so parents can understand it quickly.","zh":"學校告示應使用普通語言，讓家長快速理解。"},{"en":"Ordinary language in a writer’s will may surprise people who expect literary beauty.","zh":"作家遺囑中的普通語言可能令期待文學美感的人驚訝。"},{"en":"The phrase contrasts simple wording with artistic style.","zh":"這個短語把簡單用語與藝術風格作對比。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":18},{"front":"lack of public grieving","meaning":"缺乏公開哀悼","examples":[{"en":"The lack of public grieving after Shakespeare’s death puzzled some critics.","zh":"莎士比亞死後缺乏公開哀悼令一些評論者困惑。"},{"en":"Lack of public grieving means absence of visible public sadness after someone dies.","zh":"lack of public grieving 指某人死後缺少可見的公眾悲傷表達。"},{"en":"If a famous community leader dies and there are no notices or speeches, people may notice the lack of public grieving.","zh":"如果著名社區領袖去世卻沒有公告或演說，人們可能注意到缺乏公開哀悼。"},{"en":"Such absence can seem strange when the person was respected in life.","zh":"當該人在世時受尊重，這種缺席可能顯得奇怪。"},{"en":"The phrase focuses on missing public mourning.","zh":"這個短語重點是公開哀悼的缺失。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":18},{"front":"public grieving","meaning":"公開哀悼","examples":[{"en":"Public grieving was absent when Shakespeare died.","zh":"莎士比亞去世時沒有公開哀悼。"},{"en":"Public grieving is open expression of sadness by a community or society after a death.","zh":"public grieving 指某人死後社區或社會公開表達悲傷。"},{"en":"Public grieving may include memorial services, newspaper notices, speeches, or public ceremonies.","zh":"公開哀悼可能包括追悼會、報紙公告、演說或公共儀式。"},{"en":"When public grieving is absent, later observers may wonder whether the person was valued at the time.","zh":"當公開哀悼缺席，後來觀察者可能想知道該人在當時是否受重視。"},{"en":"The phrase describes communal mourning.","zh":"這個短語描述群體哀悼。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":18},{"front":"upon his death","meaning":"在他去世時","examples":[{"en":"The question focuses on what happened upon his death.","zh":"題目集中於他去世時發生了甚麼。"},{"en":"Upon his death means at the moment of his death or immediately after it.","zh":"upon his death 指在他死亡時或死後不久。"},{"en":"Upon his death, a writer’s papers may be passed to family members or libraries.","zh":"作家去世時，其文件可能交給家人或圖書館。"},{"en":"What happens upon someone’s death can reveal how others valued that person.","zh":"某人去世時發生的事，可以揭示他人如何重視此人。"},{"en":"The phrase is formal and time-focused.","zh":"這個短語較正式，重點是時間。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":18},{"front":"believe someone was not the author","meaning":"相信某人不是作者","examples":[{"en":"Some people believe Shakespeare was not the author of the plays.","zh":"有些人相信莎士比亞不是這些劇作的作者。"},{"en":"To believe someone was not the author means to think that person did not write the work.","zh":"believe someone was not the author 指認為某人沒有寫該作品。"},{"en":"If a student submits an essay in a very different style, a teacher may wonder whether he was not the author.","zh":"如果學生提交風格非常不同的作文，老師可能懷疑他不是作者。"},{"en":"Such a belief needs evidence that explains both the real writer and the misleading name.","zh":"這種信念需要證據，同時解釋真正作者和誤導性署名。"},{"en":"The phrase expresses doubt about authorship.","zh":"這個短語表達對作者身份的懷疑。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":18},{"front":"complete the flowchart","meaning":"完成流程圖","examples":[{"en":"Candidates complete the flowchart with words from the passage.","zh":"考生使用文章中的字詞完成流程圖。"},{"en":"To complete the flowchart means to fill missing words in a diagram showing steps or logic.","zh":"complete the flowchart 指在顯示步驟或邏輯的圖中填上缺失字詞。"},{"en":"Students complete a flowchart by following arrows and checking how ideas connect.","zh":"學生透過跟隨箭嘴並檢查想法如何連接來完成流程圖。"},{"en":"Flowcharts test whether readers understand sequence, cause, and result.","zh":"流程圖測試讀者是否理解次序、原因和結果。"},{"en":"The phrase is an exam instruction about diagram completion.","zh":"這個短語是關於圖表填充的考試指示。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":18},{"front":"no more than three words","meaning":"不多於三個字","examples":[{"en":"The instructions allow no more than three words from the passage.","zh":"指示允許使用文章中不多於三個字。"},{"en":"No more than three words means one, two, or three words only.","zh":"no more than three words 指只可一個、兩個或三個詞。"},{"en":"If the answer has four words, it breaks the rule even if the meaning is correct.","zh":"如果答案有四個詞，即使意思正確，也違反規則。"},{"en":"Students should copy carefully and count words before writing the final answer.","zh":"學生應仔細抄寫並在寫最終答案前數詞數。"},{"en":"The phrase gives a strict word limit.","zh":"這個短語提供嚴格字數限制。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":18},{"front":"the argument for","meaning":"支持……的論點","examples":[{"en":"The flowchart summarises the argument for an aristocratic author.","zh":"流程圖總結支持貴族作者的論點。"},{"en":"The argument for something is the reasoning used to support it.","zh":"argument for something 指用來支持某事的推理。"},{"en":"The argument for school uniforms may include equality, discipline, and safety.","zh":"支持校服的論點可能包括平等、紀律和安全。"},{"en":"In the passage, the argument for an aristocratic author depends on education, court knowledge, and social risk.","zh":"在文章中，支持貴族作者的論點依賴教育、宮廷知識和社會風險。"},{"en":"The phrase introduces supporting logic.","zh":"這個短語引入支持性邏輯。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":19},{"front":"aristocratic author","meaning":"貴族作者","examples":[{"en":"Some anti-Stratfordians argue for an aristocratic author.","zh":"一些反斯特拉特福派主張貴族作者。"},{"en":"An aristocratic author is a writer from the noble or upper class.","zh":"aristocratic author 指來自貴族或上流階層的作者。"},{"en":"A theory may prefer an aristocratic author if the works describe court life in detail.","zh":"如果作品詳細描述宮廷生活，某理論可能偏好貴族作者。"},{"en":"Supporters may believe aristocratic background explains knowledge of manners and politics.","zh":"支持者可能相信貴族背景解釋了對禮儀和政治的知識。"},{"en":"The phrase focuses on the author’s social rank.","zh":"這個短語重點是作者的社會地位。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":19},{"front":"commercial plays","meaning":"商業劇作","examples":[{"en":"The flowchart refers to the social risks of writing commercial plays.","zh":"流程圖提到寫商業劇作的社會風險。"},{"en":"Commercial plays are plays written or performed for paying audiences and profit.","zh":"commercial plays 指為付費觀眾和利潤而寫作或演出的劇作。"},{"en":"A popular comedy in a city theatre can be a commercial play.","zh":"城市劇院中的受歡迎喜劇可以是商業劇作。"},{"en":"If upper-class writers considered paid publication shameful, commercial plays could create social risk.","zh":"如果上流作家認為收費出版可恥，商業劇作可能造成社會風險。"},{"en":"The phrase contrasts profit-making theatre with private or courtly writing.","zh":"這個短語把牟利戲劇與私人或宮廷寫作作對比。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":19},{"front":"real author","meaning":"真正作者","examples":[{"en":"The theory claims that the real author needed to hide his identity.","zh":"該理論聲稱真正作者需要隱藏身份。"},{"en":"The real author is the person who actually wrote a work, regardless of the name shown publicly.","zh":"real author 指實際寫出作品的人，不論公開顯示的是甚麼名字。"},{"en":"If a celebrity memoir is ghostwritten, the real author may be someone else.","zh":"如果名人回憶錄由代筆人寫成，真正作者可能是另一人。"},{"en":"Authorship debates try to separate public attribution from the real writer.","zh":"作者身份爭論試圖區分公開署名和真正寫作者。"},{"en":"The phrase focuses on actual creation.","zh":"這個短語重點是實際創作。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":19},{"front":"a conspiracy was arranged","meaning":"一場陰謀被安排","examples":[{"en":"The theory assumes that a conspiracy was arranged.","zh":"該理論假設一場陰謀被安排。"},{"en":"A conspiracy was arranged means people secretly planned together to hide or control something.","zh":"conspiracy was arranged 指有人秘密一起策劃，以隱藏或控制某事。"},{"en":"If officials secretly change exam results, a conspiracy has been arranged.","zh":"如果官員秘密更改考試結果，就表示一場陰謀被安排。"},{"en":"Claiming a conspiracy was arranged requires evidence of secret cooperation.","zh":"聲稱一場陰謀被安排，需要有秘密合作的證據。"},{"en":"The phrase suggests deliberate hidden planning.","zh":"這個短語暗示故意的隱藏計劃。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":19},{"front":"counter the evidence","meaning":"反駁證據","examples":[{"en":"The conspiracy theory is used to counter the evidence supporting Shakespeare.","zh":"陰謀理論被用來反駁支持莎士比亞的證據。"},{"en":"To counter the evidence means to answer, challenge, or weaken evidence against your position.","zh":"counter the evidence 指回應、挑戰或削弱不利於自己立場的證據。"},{"en":"A student may counter evidence in an essay by explaining why a source is unreliable.","zh":"學生可能在作文中透過解釋資料來源不可靠來反駁證據。"},{"en":"If documents support Shakespeare, alternative theories must counter that evidence convincingly.","zh":"如果文件支持莎士比亞，替代理論必須有說服力地反駁該證據。"},{"en":"The phrase focuses on responding to opposing proof.","zh":"這個短語重點是回應相反證明。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":19},{"front":"supporting Shakespeare’s authorship","meaning":"支持Shakespeare作者身份的","examples":[{"en":"The documentary evidence supports Shakespeare’s authorship.","zh":"文獻證據支持莎士比亞的作者身份。"},{"en":"Supporting Shakespeare’s authorship means helping to prove that Shakespeare wrote the plays.","zh":"supporting Shakespeare’s authorship 指幫助證明莎士比亞寫了這些劇作。"},{"en":"A title page with his name can be evidence supporting his authorship.","zh":"有他名字的書名頁可以是支持其作者身份的證據。"},{"en":"If several independent records support the same claim, that claim becomes stronger.","zh":"如果幾項獨立紀錄支持同一聲稱，該聲稱就變得更強。"},{"en":"The phrase connects evidence with the traditional author claim.","zh":"這個短語把證據與傳統作者聲稱連起來。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":19},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Candidates choose the correct letter, A, B, C or D.","zh":"考生選出正確字母 A、B、C 或 D。"},{"en":"Choose the correct letter means select the option that matches the answer.","zh":"choose the correct letter 指選擇符合答案的選項字母。"},{"en":"If option C matches the passage, students should write C, not the full sentence.","zh":"如果選項 C 與文章相符，學生應寫 C，而不是完整句子。"},{"en":"Students should read all options before choosing the correct letter.","zh":"學生在選出正確字母前應閱讀所有選項。"},{"en":"The phrase is an exam instruction about multiple-choice answers.","zh":"這個短語是關於選擇題答案的考試指示。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":19},{"front":"be mentioned in","meaning":"在……中被提及","examples":[{"en":"The question asks which statement was mentioned in the reading passage.","zh":"題目問哪項陳述在閱讀文章中被提及。"},{"en":"To be mentioned in a text means to be stated or referred to there.","zh":"be mentioned in a text 指在文本中被說明或提到。"},{"en":"If a name is mentioned in a report, it appears somewhere in the document.","zh":"如果名字在報告中被提及，它就出現在文件某處。"},{"en":"Students should not choose an answer just because it sounds possible; it must be mentioned in the passage.","zh":"學生不應因答案聽起來可能就選它；它必須在文章中被提及。"},{"en":"The phrase focuses on textual evidence.","zh":"這個短語重點是文本證據。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":19},{"front":"the smartest of the candidates","meaning":"候選人中最聰明的","examples":[{"en":"The option describes Bacon as the smartest of the candidates.","zh":"選項把 Bacon 描述為候選人中最聰明的。"},{"en":"The smartest of the candidates means the most intelligent among the proposed people.","zh":"smartest of the candidates 指被提出的人之中最有智慧的一位。"},{"en":"In a scholarship interview, one student may seem the smartest of the candidates but not the most suitable.","zh":"在獎學金面試中，一名學生可能看似是候選人中最聰明的，但不是最適合的。"},{"en":"Being the smartest candidate does not automatically prove authorship.","zh":"成為最聰明候選人不會自動證明作者身份。"},{"en":"The phrase compares intelligence within a group.","zh":"這個短語比較群體內的智慧。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":19},{"front":"the prime candidate","meaning":"首要候選人","examples":[{"en":"The option asks whether Marlowe is the prime candidate.","zh":"選項問 Marlowe 是否首要候選人。"},{"en":"The prime candidate is the main or most likely candidate.","zh":"prime candidate 指主要或最有可能的候選人。"},{"en":"A student with excellent grades and leadership may be the prime candidate for head prefect.","zh":"成績優秀且有領導能力的學生可能是總領袖生的首要候選人。"},{"en":"If another contender has more support, Marlowe may not be the prime candidate.","zh":"如果另一位競爭者有更多支持，Marlowe 可能不是首要候選人。"},{"en":"The phrase indicates top status among options.","zh":"這個短語表示選項中的最高地位。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":19},{"front":"wrote plays for courtly audiences","meaning":"為宮廷觀眾寫劇本","examples":[{"en":"The option says that William Stanley wrote plays for courtly audiences.","zh":"選項說 William Stanley 為宮廷觀眾寫劇本。"},{"en":"To write plays for courtly audiences means to create drama intended for nobles or people around a royal court.","zh":"write plays for courtly audiences 指創作供貴族或王室宮廷周圍人士觀看的戲劇。"},{"en":"A play for courtly audiences may include formal manners, court politics, and elite references.","zh":"面向宮廷觀眾的劇作可能包括正式禮儀、宮廷政治和精英典故。"},{"en":"Writing for courtly audiences is different from writing for ordinary public theatres.","zh":"為宮廷觀眾寫作不同於為普通公共劇院寫作。"},{"en":"The phrase connects authorship with elite performance settings.","zh":"這個短語把作者身份與精英演出場合連起來。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":20},{"front":"the author believes that","meaning":"作者認為","examples":[{"en":"The question asks what the author believes about Shakespeare.","zh":"題目問作者對莎士比亞有何看法。"},{"en":"The author believes that means the writer’s opinion or conclusion is that something is true.","zh":"author believes that 指作者的意見或結論認為某事為真。"},{"en":"In an opinion article, students must separate what the author believes from what other people claim.","zh":"在評論文章中，學生必須區分作者認為的內容和其他人聲稱的內容。"},{"en":"If the author dismisses weak theories, his belief may favour the traditional view.","zh":"如果作者否定薄弱理論，他的看法可能支持傳統觀點。"},{"en":"The phrase focuses on the writer’s viewpoint.","zh":"這個短語重點是作者觀點。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":20},{"front":"probably wrote the plays","meaning":"很可能寫了這些劇作","examples":[{"en":"The option says that Shakespeare probably wrote the plays.","zh":"選項說莎士比亞很可能寫了這些劇作。"},{"en":"Probably wrote the plays means most likely wrote them, though the wording leaves some uncertainty.","zh":"probably wrote the plays 指最有可能寫了那些劇作，但措辭仍保留一些不確定性。"},{"en":"If records and title pages point to one person, he probably wrote the works unless stronger evidence appears.","zh":"如果記錄和書名頁都指向同一人，除非有更強證據，否則他很可能寫了作品。"},{"en":"Probably is weaker than certainly because it still allows some doubt.","zh":"probably 比 certainly 弱，因為它仍容許一些疑問。"},{"en":"The phrase expresses high likelihood, not absolute proof.","zh":"這個短語表達高度可能性，而不是絕對證明。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":20},{"front":"certainly wrote the plays","meaning":"肯定寫了這些劇作","examples":[{"en":"The option says that Shakespeare certainly wrote the plays.","zh":"選項說莎士比亞肯定寫了這些劇作。"},{"en":"Certainly wrote the plays means definitely wrote them, without serious doubt.","zh":"certainly wrote the plays 指確定寫了那些劇作，沒有嚴重疑問。"},{"en":"If many reliable records name the same author, some readers may say he certainly wrote the work.","zh":"如果許多可靠記錄都列出同一作者，有些讀者可能說他肯定寫了該作品。"},{"en":"Certainly is stronger than probably and leaves almost no room for doubt.","zh":"certainly 比 probably 更強，幾乎不留下懷疑空間。"},{"en":"The phrase expresses firm belief in authorship.","zh":"這個短語表達對作者身份的堅定相信。"}],"source":"91 - Shakespeare - The Authorship Question.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 92":[{"front":"overcrowded roads","meaning":"擠塞的道路","examples":[{"en":"The passage asks whether Britain’s canals could be a solution to overcrowded roads.","zh":"篇章詢問英國運河能否成為擠塞道路的解決方法。"},{"en":"Overcrowded roads are roads with too many vehicles, causing slow traffic and delays.","zh":"擠塞的道路是車輛太多、導致交通緩慢和延誤的道路。"},{"en":"During the morning rush hour, overcrowded roads can make a ten-minute journey take half an hour.","zh":"在早上繁忙時間，擠塞道路可以令十分鐘車程變成半小時。"},{"en":"Overcrowded roads can increase pollution, stress, fuel use and delivery costs.","zh":"擠塞道路會增加污染、壓力、燃油使用和送貨成本。"},{"en":"Cities may look for rail, bus or water transport when overcrowded roads become too difficult to manage.","zh":"當道路擠塞變得太難處理，城市可能尋找鐵路、巴士或水路運輸。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":1},{"front":"it’s hard to imagine that","meaning":"很難想像","examples":[{"en":"It’s hard to imagine that many canals were once neglected and full of rubbish.","zh":"很難想像許多運河曾經被忽視，而且滿是垃圾。"},{"en":"It’s hard to imagine that means something is surprising because the present situation looks very different.","zh":"很難想像，是指某事令人驚訝，因為現在情況看起來非常不同。"},{"en":"It’s hard to imagine that this clean park was once an abandoned car park.","zh":"很難想像這個乾淨公園曾經是一個廢棄停車場。"},{"en":"People use this phrase when change has been so great that the past seems unbelievable.","zh":"當改變巨大得令過去看似難以置信，人們會使用這個短語。"},{"en":"This phrase often introduces a contrast between past neglect and present improvement.","zh":"這個短語常引入過去荒廢與現在改善之間的對比。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":1},{"front":"a decade or so ago","meaning":"大約十年前","examples":[{"en":"A decade or so ago, many of the nation’s canals were badly neglected.","zh":"大約十年前，全國許多運河被嚴重忽視。"},{"en":"A decade or so ago means about ten years ago, not exactly ten years.","zh":"大約十年前，是指約十年前，不一定剛好十年。"},{"en":"A decade or so ago, few students carried tablets to school.","zh":"大約十年前，很少學生帶平板電腦上學。"},{"en":"This phrase is useful when the time is approximate rather than exact.","zh":"當時間是大概而非精確時，這個短語很有用。"},{"en":"It often introduces a change between the recent past and the present.","zh":"它常引入近年過去與現在之間的改變。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":1},{"front":"the nation’s canals","meaning":"全國的運河","examples":[{"en":"Many of the nation’s canals have changed dramatically in recent years.","zh":"全國許多運河近年已發生巨大改變。"},{"en":"The nation’s canals means the canal system belonging to or located across a country.","zh":"全國的運河，是指屬於或分布於一個國家的運河系統。"},{"en":"The nation’s canals may connect towns, factories, rivers and ports.","zh":"全國的運河可能連接城鎮、工廠、河流和港口。"},{"en":"If the nation’s canals are restored, they can support tourism, transport and urban renewal.","zh":"如果全國運河得到復修，它們可以支持旅遊、運輸和城市更新。"},{"en":"This phrase treats canals as part of a country’s infrastructure.","zh":"這個短語把運河視為國家基礎設施的一部分。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":1},{"front":"little more than","meaning":"只不過是","examples":[{"en":"Some canals were little more than dumping places for abandoned shopping trolleys.","zh":"有些運河只不過是棄置購物手推車的地方。"},{"en":"Little more than means almost only that thing, with very little extra value or function.","zh":"只不過是，是指幾乎只是那樣東西，沒有多少額外價值或功能。"},{"en":"Without teachers, a classroom is little more than a room full of desks.","zh":"沒有老師，課室只不過是一個擺滿桌子的房間。"},{"en":"When a park is badly maintained, it may become little more than an empty patch of grass.","zh":"當公園維修很差，它可能只不過是一片空草地。"},{"en":"This phrase often criticises something by saying it has lost its proper purpose.","zh":"這個短語常透過說某物失去原有用途來作批評。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":1},{"front":"the last resting place for","meaning":"……的最後棄置地","examples":[{"en":"Neglected canals became the last resting place for abandoned shopping trolleys.","zh":"被忽視的運河成為被棄置購物手推車的最後棄置地。"},{"en":"The last resting place for something means the place where unwanted objects finally end up.","zh":"某物的最後棄置地，是指不想要的物件最終停留的地方。"},{"en":"An old storeroom can become the last resting place for broken chairs and unused computers.","zh":"舊儲物室可以成為破椅子和不用電腦的最後棄置地。"},{"en":"When public spaces are ignored, they can become places where rubbish gathers.","zh":"當公共空間被忽視，它們會變成垃圾聚集的地方。"},{"en":"This phrase gives a slightly dramatic image of objects being dumped and forgotten.","zh":"這個短語用略帶戲劇性的畫面描述物件被丟棄和遺忘。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":1},{"front":"abandoned shopping trolleys","meaning":"被棄置的購物手推車","examples":[{"en":"Many canals used to contain abandoned shopping trolleys.","zh":"許多運河以前有被棄置的購物手推車。"},{"en":"Abandoned shopping trolleys are supermarket carts left somewhere instead of being returned.","zh":"被棄置的購物手推車，是指沒有歸還、被留在某處的超市手推車。"},{"en":"A car park may look messy if abandoned shopping trolleys are left near the entrance.","zh":"如果入口附近有被棄置的購物手推車，停車場會看起來混亂。"},{"en":"Abandoned trolleys in canals show that the waterways were treated like rubbish dumps.","zh":"運河中的棄置手推車顯示水道曾被當成垃圾場。"},{"en":"This phrase gives a concrete image of urban neglect.","zh":"這個短語提供城市荒廢的具體畫面。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":1},{"front":"there’s still work to be done","meaning":"仍有工作要做","examples":[{"en":"There’s still work to be done, but the transformation has been remarkable.","zh":"仍有工作要做，但轉變已非常顯著。"},{"en":"There’s still work to be done means improvement has happened, but the task is not finished.","zh":"仍有工作要做，是指已有改善，但任務尚未完成。"},{"en":"The school garden looks better now, but there is still work to be done before students can use it safely.","zh":"學校花園現在看起來更好，但學生安全使用前仍有工作要做。"},{"en":"This phrase balances praise with realism.","zh":"這個短語平衡讚賞與現實。"},{"en":"It is useful when progress is clear but further effort is still needed.","zh":"當進展清楚但仍需進一步努力時，它很有用。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":1},{"front":"transformation","meaning":"轉變；改造","examples":[{"en":"The transformation of Britain’s canals has been remarkable.","zh":"英國運河的轉變非常顯著。"},{"en":"Transformation means a major change in appearance, use or condition.","zh":"轉變是指外觀、用途或狀況上的重大改變。"},{"en":"A neglected library can undergo a transformation when it is renovated and filled with new books.","zh":"被忽視的圖書館經翻新並添置新書後，可以經歷改造。"},{"en":"Transformation often requires time, money, planning and public support.","zh":"轉變通常需要時間、金錢、規劃和公眾支持。"},{"en":"This word suggests change that is much stronger than a small improvement.","zh":"這個詞暗示比小改善強烈得多的變化。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":1},{"front":"remarkable","meaning":"顯著的；非凡的","examples":[{"en":"The change in Britain’s canals has been remarkable.","zh":"英國運河的改變非常顯著。"},{"en":"Remarkable means unusual, impressive and worth noticing.","zh":"顯著的，是指不尋常、令人印象深刻並值得注意。"},{"en":"A student’s progress is remarkable if they move from failing essays to writing clearly in three months.","zh":"如果學生在三個月內由作文不及格進步到寫得清楚，其進步就是非凡的。"},{"en":"A remarkable change often surprises people because it is larger than expected.","zh":"顯著改變常令人驚訝，因為它比預期更大。"},{"en":"This word is used for something that stands out strongly.","zh":"這個詞用於非常突出的事物。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":1},{"front":"city-centre canals","meaning":"市中心運河","examples":[{"en":"City-centre canals have become fashionable urban spaces.","zh":"市中心運河已成為時尚的城市空間。"},{"en":"City-centre canals are waterways located in the central areas of cities.","zh":"市中心運河是位於城市中心區域的水道。"},{"en":"City-centre canals may attract cafés, walkers, cyclists and new housing.","zh":"市中心運河可能吸引咖啡店、步行者、單車人士和新住宅。"},{"en":"When restored, city-centre canals can turn neglected areas into lively public spaces.","zh":"復修後，市中心運河可以把荒廢地區變成熱鬧公共空間。"},{"en":"This phrase links waterways with urban life, not only transport.","zh":"這個短語把水道與城市生活連接起來，而不只是運輸。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":1},{"front":"stagnant reminders of","meaning":"令人想起……的停滯象徵","examples":[{"en":"Some canals were once stagnant reminders of a fading industrial past.","zh":"有些運河曾是令人想起逐漸遠去工業時代的停滯象徵。"},{"en":"Stagnant reminders of something are still, neglected things that make people remember an old period.","zh":"令人想起某事的停滯象徵，是指靜止、被忽視並令人記起舊時期的事物。"},{"en":"Empty factory buildings can be stagnant reminders of a town’s lost manufacturing jobs.","zh":"空置工廠大樓可以是令人想起城鎮失去製造業工作的停滯象徵。"},{"en":"When places are not renewed, they can make decline feel visible and permanent.","zh":"當地方沒有更新，它們會令衰落顯得可見且永久。"},{"en":"This phrase combines physical stillness with historical memory.","zh":"這個短語結合身體上的停滯與歷史記憶。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":2},{"front":"a fading industrial past","meaning":"逐漸遠去的工業時代","examples":[{"en":"Old canals once reminded people of a fading industrial past.","zh":"舊運河曾令人想起逐漸遠去的工業時代。"},{"en":"A fading industrial past means an earlier age of factories, manufacturing and heavy transport that is gradually disappearing from memory.","zh":"逐漸遠去的工業時代，是指工廠、製造業和重型運輸的舊年代正逐步從記憶中消失。"},{"en":"Rusting warehouses can remind a city of its fading industrial past.","zh":"生鏽倉庫可以令城市想起其逐漸遠去的工業時代。"},{"en":"As economies change, old industrial sites may lose their original purpose.","zh":"隨着經濟改變，舊工業地點可能失去原有用途。"},{"en":"This phrase suggests both history and decline.","zh":"這個短語同時暗示歷史與衰落。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":2},{"front":"the epitome of","meaning":"……的典範","examples":[{"en":"Some restored canals have become the epitome of urban cool.","zh":"有些復修運河已成為都市型格的典範。"},{"en":"The epitome of something means the perfect example of that quality.","zh":"某特質的典範，是指該特質的完美例子。"},{"en":"A quiet café beside the water may be the epitome of relaxed city living.","zh":"水邊一間安靜咖啡店可能是悠閒城市生活的典範。"},{"en":"When a place becomes the epitome of style, people use it to represent the whole trend.","zh":"當一個地方成為時尚的典範，人們會用它代表整個趨勢。"},{"en":"This phrase strongly highlights one defining quality.","zh":"這個短語強烈突出一種定義性特質。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":2},{"front":"urban cool","meaning":"都市型格","examples":[{"en":"Restored canals are now seen as the epitome of urban cool.","zh":"復修運河現在被視為都市型格的典範。"},{"en":"Urban cool means a fashionable, stylish and modern city atmosphere.","zh":"都市型格是指時尚、有格調和現代的城市氣氛。"},{"en":"Street cafés, renovated warehouses and waterside flats can create urban cool.","zh":"街邊咖啡店、翻新倉庫和水邊單位可以營造都市型格。"},{"en":"A place gains urban cool when young people, businesses and visitors see it as attractive.","zh":"當年輕人、企業和遊客覺得某地吸引，它就會獲得都市型格。"},{"en":"This phrase describes image and lifestyle as much as physical design.","zh":"這個短語描述形象和生活方式，也描述實體設計。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":2},{"front":"21st-century priorities","meaning":"二十一世紀的優先事項","examples":[{"en":"Twenty-first-century priorities require canals to serve new transport needs.","zh":"二十一世紀的優先事項要求運河服務新的運輸需要。"},{"en":"Twenty-first-century priorities are the needs and goals that matter most in modern times.","zh":"二十一世紀的優先事項，是現代最重要的需要和目標。"},{"en":"Cleaner transport, lower emissions and efficient deliveries are twenty-first-century priorities for many cities.","zh":"更清潔交通、較低排放和高效送貨是許多城市的二十一世紀優先事項。"},{"en":"When priorities change, old infrastructure may be given new uses.","zh":"當優先事項改變，舊基礎設施可能被賦予新用途。"},{"en":"This phrase connects modern values with planning decisions.","zh":"這個短語把現代價值與規劃決策連接起來。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":2},{"front":"dictate that","meaning":"決定；規定","examples":[{"en":"Modern transport priorities dictate that canal rehabilitation cannot stop there.","zh":"現代運輸優先事項決定運河復修不能止步於此。"},{"en":"Dictate that means strongly require or determine that something must happen.","zh":"決定或規定某事，是指強烈要求或決定某事必須發生。"},{"en":"Safety rules dictate that students must wear goggles during the experiment.","zh":"安全規則規定學生做實驗時必須戴護目鏡。"},{"en":"When pollution becomes serious, public policy may dictate that cleaner transport be used.","zh":"當污染變得嚴重，公共政策可能規定使用更清潔交通。"},{"en":"This phrase sounds stronger than simply saying “suggest.”","zh":"這個短語比單純說 “suggest” 更強。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":2},{"front":"the rehabilitation of","meaning":"……的復修","examples":[{"en":"The rehabilitation of the old canal system cannot stop with leisure projects.","zh":"舊運河系統的復修不能只停留在休閒項目。"},{"en":"The rehabilitation of something means repairing it and making it useful again.","zh":"某物的復修，是指修復它並令它重新有用。"},{"en":"The rehabilitation of an old school building may include new classrooms, lifts and safety systems.","zh":"舊校舍的復修可能包括新課室、升降機和安全系統。"},{"en":"Rehabilitation can restore value to places that were once neglected.","zh":"復修可以讓曾被忽視的地方重新有價值。"},{"en":"This phrase is often used for bringing damaged systems back into good condition.","zh":"這個短語常用於把受損系統恢復到良好狀態。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":2},{"front":"motorway system","meaning":"高速交通系統","examples":[{"en":"The canal network was once an eighteenth-century motorway system.","zh":"運河網絡曾是十八世紀的高速交通系統。"},{"en":"A motorway system is a major network for moving people or goods quickly across long distances.","zh":"高速交通系統是用來把人或貨物快速長距離運送的主要網絡。"},{"en":"Before modern roads, canals functioned like a transport system for heavy goods.","zh":"在現代道路之前，運河像重型貨物的運輸系統一樣運作。"},{"en":"Calling canals a motorway system shows how important they once were to trade.","zh":"把運河稱為高速交通系統，顯示它們曾對貿易非常重要。"},{"en":"This phrase compares old water routes with modern road networks.","zh":"這個短語把舊水路與現代道路網絡比較。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":2},{"front":"cannot stop there","meaning":"不能止步於此","examples":[{"en":"The rehabilitation of canals cannot stop with urban renewal.","zh":"運河復修不能只止步於城市更新。"},{"en":"Cannot stop there means further action is needed after the first improvement.","zh":"不能止步於此，是指第一步改善之後仍需要進一步行動。"},{"en":"A school may renovate classrooms, but improvement cannot stop there if teaching quality is weak.","zh":"學校可以翻新課室，但如果教學質素薄弱，改善不能止步於此。"},{"en":"This phrase pushes the reader from one success toward the next necessary step.","zh":"這個短語把讀者從一項成功推向下一個必要步驟。"},{"en":"It is useful when progress is good but incomplete.","zh":"當進展良好但未完成時，它很有用。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":2},{"front":"navigable rivers","meaning":"可通航河流","examples":[{"en":"Canals and navigable rivers form a major transport network.","zh":"運河和可通航河流形成主要運輸網絡。"},{"en":"Navigable rivers are rivers deep and wide enough for boats or ships to travel on.","zh":"可通航河流是深度和寬度足以讓船隻航行的河流。"},{"en":"A city beside a navigable river can move goods by water instead of road.","zh":"位於可通航河流旁的城市可以用水路而非道路運送貨物。"},{"en":"Navigable rivers reduce pressure on roads when they are connected to ports and warehouses.","zh":"當可通航河流連接港口和倉庫，它們可以減輕道路壓力。"},{"en":"This phrase describes rivers that can be used for transport.","zh":"這個短語描述可用於運輸的河流。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":2},{"front":"form a major transport network","meaning":"形成主要運輸網絡","examples":[{"en":"Canals and navigable rivers form a major transport network.","zh":"運河和可通航河流形成主要運輸網絡。"},{"en":"To form a major transport network means to create an important connected system for moving goods or people.","zh":"形成主要運輸網絡，是指建立一個用來運送貨物或人員的重要連接系統。"},{"en":"Railways, bus routes and stations can form a major transport network in a city.","zh":"鐵路、巴士路線和車站可以在城市中形成主要運輸網絡。"},{"en":"A connected network is more useful than isolated routes because goods can travel farther.","zh":"連接起來的網絡比孤立路線有用，因為貨物可以走得更遠。"},{"en":"This phrase stresses connection, scale and practical use.","zh":"這個短語強調連接、規模和實際用途。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":2},{"front":"in need of","meaning":"需要","examples":[{"en":"The waterways are in need of only piecemeal investment.","zh":"這些水道只需要零星投資。"},{"en":"In need of means requiring something because it is missing or necessary.","zh":"需要某物，是指因缺少或必要而需要它。"},{"en":"A school playground may be in need of repair after years of heavy use.","zh":"學校操場經多年大量使用後可能需要維修。"},{"en":"If a system is in need of investment, money must be spent before it can work well.","zh":"如果一個系統需要投資，就必須花錢才能運作良好。"},{"en":"This phrase points to a requirement or weakness.","zh":"這個短語指出需求或弱點。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":3},{"front":"piecemeal investment","meaning":"零星投資；逐步投資","examples":[{"en":"The canal system needs only piecemeal investment to become more useful.","zh":"運河系統只需要零星投資就能變得更有用。"},{"en":"Piecemeal investment means small, gradual investments made step by step rather than all at once.","zh":"零星投資是一步一步作出的小型、漸進投資，而不是一次過投放大量資金。"},{"en":"A school may improve its library through piecemeal investment, buying new shelves one year and computers the next.","zh":"學校可以透過逐步投資改善圖書館，一年買新書架，下一年買電腦。"},{"en":"Piecemeal investment is useful when a system already exists but needs targeted upgrades.","zh":"當系統已經存在但需要針對性升級時，零星投資很有用。"},{"en":"This phrase contrasts with a huge single rebuilding project.","zh":"這個短語與一次大型重建項目形成對比。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":3},{"front":"spare capacity","meaning":"剩餘運力","examples":[{"en":"The waterways have spare capacity to carry more freight.","zh":"這些水道有剩餘運力，可以運載更多貨物。"},{"en":"Spare capacity means unused ability to do more work, carry more goods or serve more people.","zh":"剩餘運力是尚未使用的能力，可以做更多工作、運更多貨物或服務更多人。"},{"en":"A bus route has spare capacity if many seats are empty during the day.","zh":"如果巴士路線在日間有很多空座位，它就有剩餘運力。"},{"en":"Using spare capacity can reduce the need to build completely new systems.","zh":"使用剩餘運力可以減少建設全新系統的需要。"},{"en":"This phrase shows that an existing resource is not being fully used.","zh":"這個短語顯示現有資源未被充分使用。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":3},{"front":"eliminate the need for","meaning":"消除……的需要","examples":[{"en":"Canals could eliminate the need for many lorry journeys.","zh":"運河可以消除許多貨車運輸行程的需要。"},{"en":"To eliminate the need for something means to remove the reason for using or doing it.","zh":"消除某事的需要，是指移除使用或做該事的理由。"},{"en":"Online forms can eliminate the need for people to queue at an office.","zh":"網上表格可以消除人們到辦公室排隊的需要。"},{"en":"If goods move by water, some road journeys may no longer be necessary.","zh":"如果貨物以水路運送，一些道路行程可能不再必要。"},{"en":"This phrase describes removing a requirement, not just reducing it slightly.","zh":"這個短語描述移除需求，而不只是稍為減少。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":3},{"front":"hundreds of thousands of","meaning":"數十萬的……","examples":[{"en":"Canals could remove the need for hundreds of thousands of lorry journeys.","zh":"運河可以消除數十萬次貨車運輸行程的需要。"},{"en":"Hundreds of thousands of means a very large number, at least several hundred thousand.","zh":"數十萬的，是指非常大的數量，至少有幾十萬。"},{"en":"A popular app may be downloaded by hundreds of thousands of users in one week.","zh":"一個受歡迎應用程式可能一星期內被數十萬用戶下載。"},{"en":"When a change affects hundreds of thousands of journeys, its impact is large.","zh":"當一項改變影響數十萬次行程，其影響很大。"},{"en":"This phrase emphasises scale.","zh":"這個短語強調規模。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":3},{"front":"lorry journeys","meaning":"貨車運輸行程","examples":[{"en":"More canal freight could reduce the number of lorry journeys.","zh":"更多運河貨運可以減少貨車運輸行程的數目。"},{"en":"Lorry journeys are trips made by large trucks carrying goods.","zh":"貨車運輸行程是大型貨車運送貨物的旅程。"},{"en":"A supermarket delivery may require several lorry journeys from warehouse to store.","zh":"超市送貨可能需要幾次由倉庫到店舖的貨車運輸行程。"},{"en":"Fewer lorry journeys can mean less road congestion, pollution and noise.","zh":"較少貨車行程可以代表較少道路擠塞、污染和噪音。"},{"en":"This phrase is useful when discussing freight transport.","zh":"這個短語適合用於討論貨運交通。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":3},{"front":"drive the industrial revolution","meaning":"推動工業革命","examples":[{"en":"Canals helped drive the industrial revolution in Britain.","zh":"運河幫助推動英國工業革命。"},{"en":"To drive the industrial revolution means to help power, support or accelerate major industrial change.","zh":"推動工業革命，是指幫助推動、支持或加速重大工業變化。"},{"en":"Cheap energy helped drive factory growth in many industrial cities.","zh":"便宜能源幫助推動許多工業城市的工廠增長。"},{"en":"Canals drove industrial growth by moving heavy goods more cheaply than roads.","zh":"運河透過比道路更便宜地運送重貨，推動工業增長。"},{"en":"This phrase treats transport as a force behind economic change.","zh":"這個短語把運輸視為經濟變化背後的力量。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":3},{"front":"the industrial revolution","meaning":"工業革命","examples":[{"en":"Canals played an important role in the industrial revolution.","zh":"運河在工業革命中扮演重要角色。"},{"en":"The industrial revolution was a period when machine production, factories and transport systems expanded rapidly.","zh":"工業革命是一段機器生產、工廠和運輸系統快速擴張的時期。"},{"en":"During the industrial revolution, coal, iron and textiles became central to economic growth.","zh":"在工業革命期間，煤、鐵和紡織品成為經濟增長核心。"},{"en":"Better transport helped factories receive materials and send products to markets.","zh":"更好運輸幫助工廠接收材料並把產品送往市場。"},{"en":"This phrase refers to a major historical shift from hand production to industrial production.","zh":"這個短語指由手工生產轉向工業生產的重大歷史轉變。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":3},{"front":"authorities","meaning":"當局","examples":[{"en":"Authorities now want canals to reduce road congestion.","zh":"當局現在希望運河減少道路擠塞。"},{"en":"Authorities are official organisations or people with power to make decisions and rules.","zh":"當局是有權作決定和制定規則的官方組織或人員。"},{"en":"Transport authorities may change bus routes when roads become too crowded.","zh":"當道路變得太擠塞，交通當局可能更改巴士路線。"},{"en":"When authorities support canal freight, businesses may feel safer investing in it.","zh":"當當局支持運河貨運，企業投資時可能更安心。"},{"en":"This word refers to official decision-makers.","zh":"這個詞指官方決策者。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":3},{"front":"drive congestion off the roads","meaning":"把交通擠塞從道路上轉移走","examples":[{"en":"Authorities want canals to drive congestion off the roads.","zh":"當局希望運河把交通擠塞從道路上轉移走。"},{"en":"To drive congestion off the roads means to reduce road traffic by moving journeys or freight elsewhere.","zh":"把交通擠塞從道路上轉移走，是指透過把行程或貨運移到其他地方來減少道路交通。"},{"en":"Better trains can drive congestion off the roads if commuters leave their cars at home.","zh":"如果通勤者把車留在家中，更好的鐵路可以把交通擠塞從道路上轉移走。"},{"en":"Moving heavy goods to water transport can free road space for other traffic.","zh":"把重貨轉到水路運輸，可以為其他交通釋放道路空間。"},{"en":"This phrase describes shifting pressure away from roads.","zh":"這個短語描述把壓力從道路轉移走。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":3},{"front":"the European Commission","meaning":"歐洲委員會","examples":[{"en":"The European Commission proposed a plan to move freight onto inland waterways.","zh":"歐洲委員會提出一項計劃，把貨運轉移到內陸水道。"},{"en":"The European Commission is a major institution of the European Union that proposes policies and plans.","zh":"歐洲委員會是歐盟的重要機構，負責提出政策和計劃。"},{"en":"The European Commission may support transport projects that reduce pollution across member countries.","zh":"歐洲委員會可能支持能減少成員國污染的運輸項目。"},{"en":"When the Commission proposes a plan, it can influence national transport decisions.","zh":"當委員會提出計劃，它可以影響各國運輸決定。"},{"en":"This phrase identifies the official body behind the European freight proposal.","zh":"這個短語指出歐洲貨運方案背後的官方機構。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":3},{"front":"propose a seven-year plan","meaning":"提出七年計劃","examples":[{"en":"The European Commission proposed a seven-year plan for freight transport.","zh":"歐洲委員會提出一項貨運七年計劃。"},{"en":"To propose a seven-year plan means to suggest a programme intended to run for seven years.","zh":"提出七年計劃，是指建議一項預期持續七年的方案。"},{"en":"A school may propose a five-year plan to improve libraries, laboratories and sports facilities.","zh":"學校可能提出五年計劃，以改善圖書館、實驗室和運動設施。"},{"en":"Long-term plans help governments coordinate investment and policy changes.","zh":"長期計劃幫助政府協調投資和政策改變。"},{"en":"This phrase describes an official proposal with a fixed time frame.","zh":"這個短語描述有固定時間框架的官方建議。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":4},{"front":"shift large amounts of freight","meaning":"轉移大量貨運","examples":[{"en":"The plan aims to shift large amounts of freight from roads to waterways.","zh":"該計劃旨在把大量貨運從道路轉移到水道。"},{"en":"To shift large amounts of freight means to move many goods from one transport system to another.","zh":"轉移大量貨運，是指把許多貨物從一種運輸系統移到另一種。"},{"en":"A port may shift large amounts of freight from trucks to trains to reduce road traffic.","zh":"港口可能把大量貨運從貨車轉移到火車，以減少道路交通。"},{"en":"Shifting freight can lower congestion if the alternative route has spare capacity.","zh":"如果替代路線有剩餘運力，轉移貨運可以降低擠塞。"},{"en":"This phrase focuses on moving cargo flows, not passengers.","zh":"這個短語聚焦貨物流動，而不是乘客。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":4},{"front":"freight","meaning":"貨運；貨物","examples":[{"en":"Canals can be used to carry freight.","zh":"運河可用來運載貨物。"},{"en":"Freight means goods transported by lorry, train, ship, barge or aircraft.","zh":"貨物是由貨車、火車、船、駁船或飛機運送的商品。"},{"en":"A factory sends freight to shops when it delivers boxes of products.","zh":"工廠把一箱箱產品送到店舖時，就是發送貨物。"},{"en":"Heavy freight may be cheaper to move by water than by road.","zh":"重型貨物以水路運輸可能比道路更便宜。"},{"en":"This word refers to cargo, not passengers.","zh":"這個詞指貨物，而不是乘客。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":4},{"front":"inland waterways","meaning":"內陸水道","examples":[{"en":"Inland waterways can make transport more efficient and environmentally friendly.","zh":"內陸水道可以令運輸更有效率和更環保。"},{"en":"Inland waterways are canals, rivers and other water routes inside a country.","zh":"內陸水道是位於國家內部的運河、河流和其他水路。"},{"en":"A city can use inland waterways to carry waste, building materials or industrial goods.","zh":"城市可以使用內陸水道運送廢物、建築材料或工業貨物。"},{"en":"Inland waterways reduce road pressure when they connect useful places.","zh":"當內陸水道連接有用地點，它們能減輕道路壓力。"},{"en":"This phrase refers to water transport routes away from the open sea.","zh":"這個短語指遠離外海的水路運輸路線。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":4},{"front":"come as no surprise","meaning":"並不令人意外","examples":[{"en":"Europe’s enthusiasm for canal transport comes as no surprise.","zh":"歐洲對運河運輸的熱情並不令人意外。"},{"en":"To come as no surprise means to be expected or easy to understand.","zh":"並不令人意外，是指某事是預期之內或容易理解的。"},{"en":"It comes as no surprise that students prefer shorter journeys to school.","zh":"學生較喜歡較短上學路程，這並不令人意外。"},{"en":"If freight traffic is growing, interest in alternative transport should not surprise us.","zh":"如果貨運交通正在增長，對替代運輸的興趣就不應令人意外。"},{"en":"This phrase introduces a result that follows logically from the situation.","zh":"這個短語引入由情況自然推導出的結果。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":4},{"front":"freight traffic","meaning":"貨運交通量","examples":[{"en":"Freight traffic is expected to grow by a third in the next decade.","zh":"貨運交通量預計在未來十年增長三分之一。"},{"en":"Freight traffic means the movement of goods by road, rail, water or air.","zh":"貨運交通量是指貨物透過道路、鐵路、水路或空運移動。"},{"en":"Busy ports create heavy freight traffic as containers move to warehouses.","zh":"繁忙港口會因貨櫃運往倉庫而產生大量貨運交通。"},{"en":"Growing freight traffic can increase congestion if all goods travel by lorry.","zh":"如果所有貨物都由貨車運送，增長中的貨運交通會增加擠塞。"},{"en":"This phrase focuses on goods movement rather than personal travel.","zh":"這個短語聚焦貨物流動，而不是個人出行。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":4},{"front":"be expected to","meaning":"預計會","examples":[{"en":"Freight traffic is expected to grow rapidly.","zh":"貨運交通量預計會快速增長。"},{"en":"Be expected to means people think something is likely to happen.","zh":"預計會，是指人們認為某事很可能發生。"},{"en":"The new bus route is expected to reduce waiting times.","zh":"新巴士路線預計會減少等候時間。"},{"en":"Forecasts are useful for planning, but they may still be wrong.","zh":"預測對規劃有用，但仍可能出錯。"},{"en":"This phrase presents a likely future result.","zh":"這個短語呈現很可能出現的未來結果。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":4},{"front":"grow by a third","meaning":"增長三分之一","examples":[{"en":"Freight traffic is expected to grow by a third.","zh":"貨運交通量預計會增長三分之一。"},{"en":"To grow by a third means to increase by about 33%.","zh":"增長三分之一，是指增加約 33%。"},{"en":"If a class grows from 30 students to 40, it has grown by about a third.","zh":"如果一班由 30 人增至 40 人，就是約增長三分之一。"},{"en":"Growth of this size can create serious pressure on transport systems.","zh":"這種幅度的增長會對運輸系統造成重大壓力。"},{"en":"This phrase gives a specific proportional increase.","zh":"這個短語給出具體比例增幅。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":4},{"front":"in the next decade","meaning":"在未來十年","examples":[{"en":"Freight traffic is expected to grow in the next decade.","zh":"貨運交通量預計在未來十年增長。"},{"en":"In the next decade means during the next ten years.","zh":"在未來十年，是指接下來十年期間。"},{"en":"In the next decade, many schools may use more digital assessment tools.","zh":"在未來十年，許多學校可能使用更多數碼評估工具。"},{"en":"Long-term transport planning matters when demand will grow over ten years.","zh":"當需求會在十年內增長，長期運輸規劃很重要。"},{"en":"This phrase gives a future time frame.","zh":"這個短語給出未來時間範圍。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":4},{"front":"the cost of pollution and congestion","meaning":"污染及交通擠塞的成本","examples":[{"en":"The cost of pollution and congestion is extremely high.","zh":"污染及交通擠塞的成本極高。"},{"en":"The cost of pollution and congestion means the money, health damage and lost time caused by dirty air and traffic jams.","zh":"污染及交通擠塞的成本，是指污濁空氣和交通堵塞造成的金錢、健康損害和時間損失。"},{"en":"A city pays the cost of congestion when workers sit in traffic instead of doing useful work.","zh":"當工人困在交通中而不是做有用工作，城市就承擔擠塞成本。"},{"en":"Pollution and congestion can damage health, delay deliveries and reduce economic efficiency.","zh":"污染和擠塞會損害健康、延誤送貨並降低經濟效率。"},{"en":"This phrase shows that environmental and traffic problems also have economic effects.","zh":"這個短語顯示環境和交通問題也有經濟影響。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":4},{"front":"be set to","meaning":"預計會；勢將","examples":[{"en":"The cost of pollution and congestion is set to swallow part of Europe’s GDP.","zh":"污染和交通擠塞的成本勢將吞噬歐洲部分本地生產總值。"},{"en":"Be set to means be likely or scheduled to happen.","zh":"預計會，是指很可能或已安排會發生。"},{"en":"The new bridge is set to open next year if construction stays on schedule.","zh":"如果工程按時間表進行，新橋預計明年開通。"},{"en":"This phrase often introduces a predicted future development.","zh":"這個短語常引入預測中的未來發展。"},{"en":"It sounds stronger than “may” because the trend already points that way.","zh":"它比 “may” 更強，因為趨勢已指向那方向。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":4},{"front":"swallow one per cent of","meaning":"吞噬百分之一的……","examples":[{"en":"Pollution and congestion could swallow one per cent of Europe’s GDP.","zh":"污染和擠塞可能吞噬歐洲 GDP 的百分之一。"},{"en":"To swallow one per cent of something means to consume or use up that share, usually in a negative way.","zh":"吞噬某物百分之一，是指消耗或用去該比例，通常帶負面意思。"},{"en":"Rising rent can swallow half of a family’s monthly income.","zh":"租金上升可以吞噬家庭每月收入的一半。"},{"en":"If congestion swallows economic output, society loses money without gaining value.","zh":"如果擠塞吞噬經濟產出，社會就失去金錢而沒有獲得價值。"},{"en":"This phrase gives a vivid image of costs eating into resources.","zh":"這個短語用生動畫面描述成本侵蝕資源。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":5},{"front":"entire GDP","meaning":"整體本地生產總值","examples":[{"en":"The cost could reach one per cent of Europe’s entire GDP.","zh":"該成本可能達到歐洲整體本地生產總值的百分之一。"},{"en":"Entire GDP means the total value of goods and services produced by an economy.","zh":"整體本地生產總值，是指一個經濟體生產的所有商品和服務總值。"},{"en":"A small percentage of an entire GDP can still represent a huge amount of money.","zh":"整體 GDP 的小百分比仍可以代表巨大金額。"},{"en":"When transport problems affect GDP, they become national economic issues.","zh":"當運輸問題影響 GDP，它們就成為全國經濟議題。"},{"en":"This phrase refers to the whole economic output, not one industry only.","zh":"這個短語指整體經濟產出，而不只是一個行業。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":5},{"front":"a fleet of","meaning":"一隊；船隊","examples":[{"en":"Europe has a fleet of 11,000 vessels on its waterways.","zh":"歐洲在其水道上有一支 11,000 艘船的船隊。"},{"en":"A fleet of vehicles or vessels means a group of them operated or used together.","zh":"一隊車輛或船隊，是指一起運作或使用的一組車輛或船隻。"},{"en":"A delivery company may own a fleet of electric vans.","zh":"送貨公司可能擁有一隊電動貨車。"},{"en":"A large fleet can carry more goods and make a transport system more useful.","zh":"大型船隊可以運載更多貨物，令運輸系統更有用。"},{"en":"This phrase is often used for ships, buses, aircraft or lorries.","zh":"這個短語常用於船、巴士、飛機或貨車。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":5},{"front":"vessels","meaning":"船隻","examples":[{"en":"Inland waterways use vessels to carry freight.","zh":"內陸水道使用船隻運載貨物。"},{"en":"Vessels are boats or ships used for travel, transport or work on water.","zh":"船隻是在水上用於出行、運輸或工作的船或艦。"},{"en":"Fishing vessels leave the harbour early in the morning.","zh":"漁船清晨離開港口。"},{"en":"Freight vessels can move heavy goods with less road traffic.","zh":"貨運船隻可以以較少道路交通運送重貨。"},{"en":"This word is more formal than “boats.”","zh":"這個詞比 “boats” 更正式。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":5},{"front":"a capacity equalling","meaning":"相等於……的運載能力","examples":[{"en":"The waterways have a capacity equalling many trains and trucks.","zh":"這些水道有相等於許多火車和貨車的運載能力。"},{"en":"A capacity equalling something means an ability to carry or handle the same amount as that thing.","zh":"相等於某物的運載能力，是指能承載或處理與該物相同數量的能力。"},{"en":"A new hall may have a capacity equalling three old classrooms.","zh":"新禮堂的容量可能相等於三間舊課室。"},{"en":"If a barge has capacity equalling many lorries, one trip can replace several road journeys.","zh":"如果一艘駁船的運載能力相等於多輛貨車，一次航程就能取代幾次道路行程。"},{"en":"This phrase compares carrying power.","zh":"這個短語比較承載能力。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":5},{"front":"make transport more efficient","meaning":"令運輸更有效率","examples":[{"en":"Inland waterways can make transport more efficient.","zh":"內陸水道可以令運輸更有效率。"},{"en":"To make transport more efficient means to move goods or people using less time, energy, money or waste.","zh":"令運輸更有效率，是指用更少時間、能源、金錢或浪費來運送貨物或人。"},{"en":"A direct bus route can make transport more efficient for students travelling to school.","zh":"直接巴士路線可以令學生上學交通更有效率。"},{"en":"Water transport can be efficient for heavy goods because one vessel can carry a large load.","zh":"水路運輸對重貨可以有效率，因為一艘船能載大量貨物。"},{"en":"This phrase focuses on better use of resources.","zh":"這個短語聚焦更好地使用資源。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":5},{"front":"reliable","meaning":"可靠的","examples":[{"en":"Waterway transport can be efficient, reliable and environmentally friendly.","zh":"水路運輸可以有效率、可靠且環保。"},{"en":"Reliable means able to be trusted to work well and arrive as expected.","zh":"可靠的，是指可以信任其運作良好並按預期到達。"},{"en":"A reliable bus service comes on time and does not suddenly disappear.","zh":"可靠的巴士服務會準時到達，不會突然取消。"},{"en":"Reliable transport helps businesses plan deliveries and avoid costly delays.","zh":"可靠運輸幫助企業規劃送貨並避免昂貴延誤。"},{"en":"This word describes consistency and trustworthiness.","zh":"這個詞描述穩定性和可信程度。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":5},{"front":"environmentally friendly","meaning":"環保的","examples":[{"en":"Inland waterways can provide environmentally friendly transport.","zh":"內陸水道可以提供環保運輸。"},{"en":"Environmentally friendly means causing less harm to air, water, land or climate.","zh":"環保的，是指對空氣、水、土地或氣候造成較少傷害。"},{"en":"Cycling is environmentally friendly because it creates no exhaust fumes.","zh":"踩單車是環保的，因為它不產生廢氣。"},{"en":"Transport becomes more environmentally friendly when it uses less energy and produces fewer emissions.","zh":"當運輸使用較少能源並產生較少排放，它就更環保。"},{"en":"This phrase describes choices that reduce environmental damage.","zh":"這個短語描述減少環境破壞的選擇。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":5},{"front":"cannot afford to","meaning":"承受不起；不能不","examples":[{"en":"Europe cannot afford to leave the potential of waterways unused.","zh":"歐洲承受不起讓水道潛力閒置不用。"},{"en":"Cannot afford to means it would be too damaging or costly not to act.","zh":"承受不起做某事，是指不行動會造成太大損害或成本。"},{"en":"A hospital cannot afford to ignore a shortage of nurses.","zh":"醫院不能不理會護士短缺。"},{"en":"When pollution and congestion are expensive, governments cannot afford to waste transport capacity.","zh":"當污染和擠塞成本高昂，政府不能浪費運輸能力。"},{"en":"This phrase often expresses urgency rather than literal lack of money.","zh":"這個短語常表達迫切性，而不只是字面缺錢。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":5},{"front":"leave that potential untapped","meaning":"讓那種潛力未被開發","examples":[{"en":"Europe cannot afford to leave that potential untapped.","zh":"歐洲承受不起讓那種潛力未被開發。"},{"en":"To leave potential untapped means to fail to use a resource or ability that could be valuable.","zh":"讓潛力未被開發，是指沒有使用可能有價值的資源或能力。"},{"en":"A school leaves student talent untapped if it never offers music, sport or debate clubs.","zh":"如果學校從不提供音樂、運動或辯論學會，就會讓學生才能未被開發。"},{"en":"Untapped potential matters because useful capacity already exists but is not being used.","zh":"未被開發的潛力很重要，因為有用能力已存在卻未被使用。"},{"en":"This phrase suggests waste through inaction.","zh":"這個短語暗示因不行動而造成浪費。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":5},{"front":"mainland Europe","meaning":"歐洲大陸","examples":[{"en":"Mainland Europe continued to use waterways for freight.","zh":"歐洲大陸繼續使用水道作貨運。"},{"en":"Mainland Europe means the main continental part of Europe, excluding islands such as Britain.","zh":"歐洲大陸是指歐洲主要大陸部分，不包括英國等島嶼。"},{"en":"Goods can travel across mainland Europe by river, road and rail.","zh":"貨物可以在歐洲大陸透過河流、道路和鐵路運輸。"},{"en":"Comparing mainland Europe with Britain shows different transport choices over time.","zh":"比較歐洲大陸與英國，可以顯示不同時期的運輸選擇。"},{"en":"This phrase gives a geographical contrast.","zh":"這個短語提供地理對比。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":5},{"front":"in fairness","meaning":"公平來說","examples":[{"en":"In fairness, mainland Europe has never completely ignored its waterways.","zh":"公平來說，歐洲大陸從未完全忽視其水道。"},{"en":"In fairness means to be fair or to give a balanced view.","zh":"公平來說，是指為求公平或提供平衡看法。"},{"en":"In fairness, the student arrived late because the bus broke down.","zh":"公平來說，該學生遲到是因為巴士壞了。"},{"en":"This phrase is used before adding a point that corrects or softens criticism.","zh":"這個短語用於加入一點來修正或緩和批評。"},{"en":"It helps writers avoid sounding one-sided.","zh":"它幫助作者避免顯得片面。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":6},{"front":"completely untapped","meaning":"完全未被開發的","examples":[{"en":"Mainland Europe has never left canal transport completely untapped.","zh":"歐洲大陸從未讓運河運輸完全未被開發。"},{"en":"Completely untapped means not used at all, even though it could be useful.","zh":"完全未被開發，是指完全沒有被使用，即使它可能有用。"},{"en":"A school’s rooftop garden is completely untapped if no classes or clubs ever use it.","zh":"如果沒有課堂或學會使用學校天台花園，它就是完全未被開發的資源。"},{"en":"When a resource is not completely untapped, at least some people are already using it.","zh":"當資源並非完全未被開發，至少已有一些人在使用。"},{"en":"This phrase describes unused potential in a strong way.","zh":"這個短語強烈描述未被使用的潛力。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":6},{"front":"the Low Countries","meaning":"低地國家","examples":[{"en":"The canals of the Low Countries continued to carry freight.","zh":"低地國家的運河繼續運載貨物。"},{"en":"The Low Countries usually refers to Belgium, the Netherlands and Luxembourg.","zh":"低地國家通常指比利時、荷蘭和盧森堡。"},{"en":"The Low Countries have many canals and rivers that support trade and transport.","zh":"低地國家有許多運河和河流，支持貿易和運輸。"},{"en":"Because much of the area is flat and watery, waterways have long been important there.","zh":"因為該地區很多地方地勢平坦且水道眾多，水路一直很重要。"},{"en":"This phrase names a European region rather than one single country.","zh":"這個短語命名一個歐洲地區，而不是單一國家。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":6},{"front":"Central and Eastern Europe","meaning":"中歐及東歐","examples":[{"en":"Rivers in Central and Eastern Europe continued to carry freight barges.","zh":"中歐及東歐的河流繼續運載貨運駁船。"},{"en":"Central and Eastern Europe refers to countries in the middle and eastern parts of Europe.","zh":"中歐及東歐是指位於歐洲中部和東部的國家。"},{"en":"Rivers in Central and Eastern Europe can connect inland cities with larger trade routes.","zh":"中歐及東歐的河流可以把內陸城市連接到更大的貿易路線。"},{"en":"This region kept using waterways while Britain moved more toward roads and railways.","zh":"當英國更轉向道路和鐵路時，這個地區仍使用水道。"},{"en":"This phrase gives a broad geographical area.","zh":"這個短語提供廣泛地理區域。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":6},{"front":"buzz with","meaning":"充滿……的聲音；熱鬧運作","examples":[{"en":"Some European waterways buzzed with the sound of freight barges.","zh":"有些歐洲水道充滿貨運駁船的聲音，熱鬧運作。"},{"en":"To buzz with something means to be full of activity, sound or energy.","zh":"充滿某物的聲音或熱鬧運作，是指充滿活動、聲音或活力。"},{"en":"A school corridor may buzz with excited voices before a sports day.","zh":"運動日前，學校走廊可能充滿興奮的聲音。"},{"en":"When a waterway buzzes with barges, it is actively used rather than neglected.","zh":"當水道充滿駁船活動，它就是被積極使用，而不是被忽視。"},{"en":"This phrase gives a lively image of movement.","zh":"這個短語提供熱鬧移動的畫面。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":6},{"front":"freight barges","meaning":"貨運駁船","examples":[{"en":"Freight barges continued to operate in parts of Europe.","zh":"貨運駁船繼續在歐洲部分地區運作。"},{"en":"Freight barges are flat-bottomed boats used to carry goods on rivers and canals.","zh":"貨運駁船是在河流和運河上運載貨物的平底船。"},{"en":"A freight barge can carry building materials, waste, coal or containers.","zh":"貨運駁船可以運載建築材料、廢物、煤或貨櫃。"},{"en":"Barges can reduce road traffic because one vessel may replace many lorry trips.","zh":"駁船可以減少道路交通，因為一艘船可能取代多次貨車行程。"},{"en":"This phrase refers to cargo boats, not passenger boats.","zh":"這個短語指貨船，而不是客船。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":6},{"front":"long after","meaning":"在……之後很久","examples":[{"en":"European waterways carried freight long after British industry moved to roads and railways.","zh":"在英國工業轉向道路和鐵路之後很久，歐洲水道仍運載貨物。"},{"en":"Long after means much later than a particular event or period.","zh":"在……之後很久，是指比某事件或時期晚很多。"},{"en":"Some students remember a kind teacher long after leaving school.","zh":"有些學生離校很久後仍記得一位善良老師。"},{"en":"This phrase shows that one activity continued even after another major change happened.","zh":"這個短語顯示一項活動在另一重大改變後仍繼續。"},{"en":"It is useful for comparing different historical paths.","zh":"它適合用於比較不同歷史路徑。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":6},{"front":"throw in its lot with","meaning":"選擇與……站在一起；投向","examples":[{"en":"British industry threw in its lot with railways and roads.","zh":"英國工業選擇投向鐵路和道路。"},{"en":"To throw in one’s lot with something means to choose to support or depend on it.","zh":"選擇與某事站在一起，是指選擇支持或依賴它。"},{"en":"A small shop may throw in its lot with online delivery when foot traffic falls.","zh":"當人流下降，小店可能選擇投向網上送貨。"},{"en":"Once a business chooses one system, it may invest less in alternatives.","zh":"一旦企業選擇一個系統，它可能較少投資其他選項。"},{"en":"This phrase suggests making a strategic choice and accepting its consequences.","zh":"這個短語暗示作出策略選擇並承擔後果。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":6},{"front":"attempts to revive","meaning":"復興……的嘗試","examples":[{"en":"Attempts to revive freight on British canals have faced difficulties.","zh":"復興英國運河貨運的嘗試面對困難。"},{"en":"Attempts to revive something are efforts to bring it back after decline or disappearance.","zh":"復興某事的嘗試，是指在其衰落或消失後努力讓它回來。"},{"en":"A town may make attempts to revive a market that lost shoppers years ago.","zh":"城鎮可能嘗試復興多年前失去顧客的市場。"},{"en":"Revival attempts can fail if the old system has been neglected too long.","zh":"如果舊系統被忽視太久，復興嘗試可能失敗。"},{"en":"This phrase describes efforts to restore activity.","zh":"這個短語描述恢復活動的努力。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":6},{"front":"revive freight","meaning":"復興貨運","examples":[{"en":"Britain has tried to revive freight on its canals.","zh":"英國曾嘗試在其運河上復興貨運。"},{"en":"To revive freight means to bring goods transport back into use after it has declined.","zh":"復興貨運，是指在貨物運輸衰落後讓它重新使用。"},{"en":"A port may revive freight by reopening an old rail connection to warehouses.","zh":"港口可能透過重開通往倉庫的舊鐵路連線來復興貨運。"},{"en":"Reviving freight on canals requires suitable goods, reliable routes and business demand.","zh":"在運河上復興貨運需要合適貨物、可靠路線和商業需求。"},{"en":"This phrase focuses on restoring cargo transport.","zh":"這個短語聚焦恢復貨物運輸。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":6},{"front":"be hampered by","meaning":"受到……阻礙","examples":[{"en":"Attempts to revive canal freight have been hampered by historical decline.","zh":"復興運河貨運的嘗試受到歷史衰落阻礙。"},{"en":"To be hampered by something means to be slowed down or made more difficult by it.","zh":"受到某事阻礙，是指因它而變慢或變得更困難。"},{"en":"A school trip may be hampered by heavy rain and delayed buses.","zh":"學校旅行可能受到大雨和巴士延誤阻礙。"},{"en":"Old neglect can hamper revival because repairs become costly and complicated.","zh":"長期忽視會阻礙復興，因為維修變得昂貴又複雜。"},{"en":"This phrase describes an obstacle that limits progress.","zh":"這個短語描述限制進展的障礙。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":6},{"front":"their heyday","meaning":"全盛時期","examples":[{"en":"The heyday of British canals lasted barely 60 years.","zh":"英國運河的全盛時期僅維持約 60 年。"},{"en":"A heyday is the period when something is most successful, popular or powerful.","zh":"全盛時期是某事最成功、最受歡迎或最有力量的時期。"},{"en":"A shopping street’s heyday may be the years when every shop was busy.","zh":"購物街的全盛時期可能是每間店都繁忙的那些年。"},{"en":"After a short heyday, canals declined when railways became stronger.","zh":"短暫全盛後，當鐵路變強，運河便衰落。"},{"en":"This word compares a peak period with later decline.","zh":"這個詞把高峰時期與後來衰落作比較。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":7},{"front":"last barely","meaning":"僅維持","examples":[{"en":"The heyday of British canals lasted barely 60 years.","zh":"英國運河的全盛時期僅維持 60 年。"},{"en":"To last barely a period means to continue for only that short time, almost not more.","zh":"僅維持某段時間，是指只持續那麼短時間，幾乎不超過。"},{"en":"The phone battery lasted barely three hours during the school trip.","zh":"學校旅行期間，手機電池僅維持三小時。"},{"en":"If a system’s success lasts barely a few decades, later generations may remember mostly its decline.","zh":"如果一個系統的成功僅維持幾十年，後代可能主要記得它的衰落。"},{"en":"This phrase stresses short duration.","zh":"這個短語強調持續時間短。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":7},{"front":"be considered obsolete","meaning":"被視為過時","examples":[{"en":"British canals were first considered obsolete 150 years ago.","zh":"英國運河最早在 150 年前被視為過時。"},{"en":"To be considered obsolete means to be regarded as outdated and no longer useful.","zh":"被視為過時，是指被認為落後且不再有用。"},{"en":"Some people considered fax machines obsolete after email became common.","zh":"電郵普及後，有些人認為傳真機已經過時。"},{"en":"A technology may be considered obsolete when faster or cheaper alternatives appear.","zh":"當更快或更便宜的替代品出現，某科技可能被視為過時。"},{"en":"This phrase describes judgement about usefulness over time.","zh":"這個短語描述人們對用途隨時間的判斷。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":7},{"front":"obsolete","meaning":"過時的；被淘汰的","examples":[{"en":"Canals were once considered obsolete.","zh":"運河曾被視為過時。"},{"en":"Obsolete means no longer useful because something newer or better has replaced it.","zh":"過時的，是指因被更新或更好事物取代而不再有用。"},{"en":"Old computer disks became obsolete when modern storage devices became common.","zh":"當現代儲存裝置普及，舊電腦磁碟變得過時。"},{"en":"Obsolete systems may still have value if new problems make them useful again.","zh":"過時系統如果因新問題而再次有用，仍可能有價值。"},{"en":"This word describes something outdated, not simply old.","zh":"這個詞描述落後淘汰，而不只是舊。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":7},{"front":"the intervening period","meaning":"中間的一段時期","examples":[{"en":"Many canals were neglected for much of the intervening period.","zh":"許多運河在中間很長一段時期被忽視。"},{"en":"The intervening period is the time between two events.","zh":"中間的一段時期，是指兩個事件之間的時間。"},{"en":"Between primary school and university, the intervening period includes secondary education.","zh":"在小學和大學之間，中間時期包括中學教育。"},{"en":"If a place is neglected during the intervening period, restoration later becomes harder.","zh":"如果一個地方在中間時期被忽視，之後復修會更困難。"},{"en":"This phrase helps describe what happened between two historical points.","zh":"這個短語幫助描述兩個歷史時間點之間發生的事。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":7},{"front":"be left to rot","meaning":"被任由荒廢","examples":[{"en":"Many British canals were simply left to rot.","zh":"許多英國運河只是被任由荒廢。"},{"en":"To be left to rot means to be abandoned until it decays, breaks down or becomes useless.","zh":"被任由荒廢，是指被拋棄至腐壞、破損或失去用途。"},{"en":"An old school building may be left to rot if no one repairs the roof or windows.","zh":"如果沒有人修理屋頂或窗戶，舊校舍可能被任由荒廢。"},{"en":"When infrastructure is left to rot, later restoration costs much more.","zh":"當基礎設施被任由荒廢，之後復修成本會高很多。"},{"en":"This phrase strongly criticises neglect.","zh":"這個短語強烈批評忽視。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":7},{"front":"network in decline","meaning":"衰落中的網絡","examples":[{"en":"Britain’s canal network was in decline for a long time.","zh":"英國運河網絡長期處於衰落之中。"},{"en":"A network in decline is a connected system that is becoming weaker, less used or poorly maintained.","zh":"衰落中的網絡，是指一個連接系統變得更弱、較少使用或維修不善。"},{"en":"A bus network in decline may have fewer routes, older vehicles and fewer passengers.","zh":"衰落中的巴士網絡可能路線較少、車輛較舊、乘客較少。"},{"en":"Declining networks become less useful because connections disappear.","zh":"衰落中的網絡因連接消失而變得較不有用。"},{"en":"This phrase describes long-term weakening of infrastructure.","zh":"這個短語描述基礎設施長期變弱。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":7},{"front":"compared to","meaning":"與……相比","examples":[{"en":"Britain’s waterways declined compared to those in much of Europe.","zh":"與歐洲許多地方的水道相比，英國水道衰落了。"},{"en":"Compared to means judged beside another person, thing or situation.","zh":"與某物相比，是指把某人、某物或情況並列判斷。"},{"en":"Compared to driving, cycling is cheaper and cleaner for short journeys.","zh":"與駕車相比，短途踩單車更便宜、更清潔。"},{"en":"Comparisons help show whether one system performed better or worse than another.","zh":"比較幫助顯示一個系統比另一個表現更好還是更差。"},{"en":"This phrase clearly places two things side by side.","zh":"這個短語清楚把兩件事並列。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":7},{"front":"carry on using","meaning":"繼續使用","examples":[{"en":"Other countries carried on using their waterways.","zh":"其他國家繼續使用其水道。"},{"en":"To carry on using something means to continue using it.","zh":"繼續使用某物，是指持續使用它。"},{"en":"A school may carry on using printed books even after introducing tablets.","zh":"學校即使引入平板電腦，也可能繼續使用印刷書。"},{"en":"If people carry on using a system, it is less likely to fall into neglect.","zh":"如果人們繼續使用一個系統，它就較不容易被荒廢。"},{"en":"This phrase shows continuity rather than abandonment.","zh":"這個短語顯示延續，而不是放棄。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":7},{"front":"be neglected","meaning":"被忽視；被荒廢","examples":[{"en":"British canals were neglected for many years.","zh":"英國運河多年來被忽視。"},{"en":"To be neglected means to be ignored, poorly cared for or left without maintenance.","zh":"被忽視，是指被不理會、照顧不善或缺乏維修。"},{"en":"A garden becomes neglected if no one waters, cuts or cleans it.","zh":"如果沒有人澆水、修剪或清理，花園就會被荒廢。"},{"en":"Neglected canals fill with rubbish and lose their transport value.","zh":"被忽視的運河會充滿垃圾，失去運輸價值。"},{"en":"This phrase describes damage caused by lack of attention.","zh":"這個短語描述缺乏關注造成的損害。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":7},{"front":"enlarge canals","meaning":"擴建運河","examples":[{"en":"Many European countries enlarged their canals 100 years ago.","zh":"許多歐洲國家在一百年前擴建了運河。"},{"en":"To enlarge canals means to make them wider, deeper or more suitable for larger boats.","zh":"擴建運河，是指令運河更寬、更深或更適合大型船隻。"},{"en":"A town may enlarge a road when traffic grows too heavy.","zh":"當交通太繁忙，城鎮可能擴闊道路。"},{"en":"Enlarging canals can allow bigger freight barges to use them.","zh":"擴建運河可以讓更大型貨運駁船使用它們。"},{"en":"This phrase describes physical expansion for greater capacity.","zh":"這個短語描述為提高容量而作出的實體擴張。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":7},{"front":"reverse a decline","meaning":"扭轉衰落","examples":[{"en":"The decline in Britain’s canals has been reversed.","zh":"英國運河的衰落已被扭轉。"},{"en":"To reverse a decline means to stop a downward trend and make the situation improve.","zh":"扭轉衰落，是指停止下降趨勢並令情況改善。"},{"en":"A school can reverse a decline in reading by opening a better library and reading club.","zh":"學校可以透過開設更好圖書館和閱讀會來扭轉閱讀衰落。"},{"en":"Reversing decline often requires investment, public interest and practical use.","zh":"扭轉衰落通常需要投資、公眾興趣和實際用途。"},{"en":"This phrase describes moving from deterioration back toward recovery.","zh":"這個短語描述由惡化轉向恢復。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":8},{"front":"leisure seekers","meaning":"休閒活動人士","examples":[{"en":"Leisure seekers helped bring canals back into use.","zh":"休閒活動人士幫助運河重新投入使用。"},{"en":"Leisure seekers are people looking for recreation, relaxation or enjoyable activities.","zh":"休閒活動人士是尋找消閒、放鬆或愉快活動的人。"},{"en":"Walkers, cyclists, boaters and anglers can all be leisure seekers along a canal.","zh":"步行者、單車人士、船民和釣魚人士都可以是運河旁的休閒活動人士。"},{"en":"When leisure seekers return to a place, cafés and housing may also develop there.","zh":"當休閒人士重返某地，咖啡店和住宅也可能在那裡發展。"},{"en":"This phrase describes people using a space for enjoyment rather than work.","zh":"這個短語描述為享受而非工作使用空間的人。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":8},{"front":"more recently","meaning":"近年來","examples":[{"en":"More recently, industry has also returned to the waterways.","zh":"近年來，工業也回到水道上。"},{"en":"More recently means in a later and nearer period of time.","zh":"近年來，是指較後且較接近現在的一段時間。"},{"en":"Schools first used computers for typing; more recently, they have used them for online lessons.","zh":"學校起初用電腦打字；近年來，則用它們上網課。"},{"en":"This phrase helps describe a new stage after earlier developments.","zh":"這個短語幫助描述早前發展之後的新階段。"},{"en":"It often signals that the story has moved closer to the present.","zh":"它常表示故事已移近現在。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":8},{"front":"boaters","meaning":"船民；遊船人士","examples":[{"en":"Boaters now benefit from Britain’s navigable waterways.","zh":"船民現在受惠於英國可通航水道。"},{"en":"Boaters are people who travel, live or spend leisure time on boats.","zh":"船民或遊船人士，是在船上旅行、生活或消閒的人。"},{"en":"Boaters may use canals for holidays, weekend trips or waterside communities.","zh":"遊船人士可能用運河度假、週末出遊或建立水上社群。"},{"en":"Restored waterways attract boaters and bring activity back to canal areas.","zh":"復修水道吸引遊船人士，為運河地區帶回活動。"},{"en":"This word refers to recreational or regular boat users.","zh":"這個詞指休閒或經常使用船的人。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":8},{"front":"anglers","meaning":"釣魚人士","examples":[{"en":"Anglers use canals and rivers for recreation.","zh":"釣魚人士使用運河和河流作消閒。"},{"en":"Anglers are people who fish with a rod and line, usually as a hobby.","zh":"釣魚人士是使用魚竿和魚線釣魚的人，通常作為興趣。"},{"en":"An angler may spend Sunday morning fishing quietly beside a canal.","zh":"釣魚人士可能在星期日早上安靜地在運河旁釣魚。"},{"en":"Clean waterways attract anglers because fish and pleasant surroundings matter.","zh":"清潔水道吸引釣魚人士，因為魚和舒適環境都重要。"},{"en":"This word describes recreational fishing people, not commercial fishermen.","zh":"這個詞描述休閒釣魚人士，而不是商業漁民。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":8},{"front":"benefit from","meaning":"從……受益","examples":[{"en":"Walkers and cyclists benefit from paths along the waterways.","zh":"步行者和單車人士從水道沿線的小徑中受益。"},{"en":"To benefit from something means to gain help, advantage or enjoyment from it.","zh":"從某事受益，是指從它得到幫助、好處或享受。"},{"en":"Students benefit from clear notes because they know what to revise.","zh":"學生從清晰筆記中受益，因為他們知道要溫習甚麼。"},{"en":"Communities benefit from restored canals when public paths and businesses improve.","zh":"當公共小徑和商業改善，社區就從復修運河中受益。"},{"en":"This phrase focuses on the positive effect someone receives.","zh":"這個短語聚焦某人獲得的正面影響。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":8},{"front":"navigable waterways","meaning":"可通航水道","examples":[{"en":"Britain has thousands of miles of navigable waterways.","zh":"英國有數千英里的可通航水道。"},{"en":"Navigable waterways are canals or rivers that boats can travel along.","zh":"可通航水道是船隻能沿着航行的運河或河流。"},{"en":"A navigable waterway can support boating, freight, tourism and waterside paths.","zh":"可通航水道可以支持遊船、貨運、旅遊和水邊小徑。"},{"en":"If a waterway is blocked or too shallow, it is no longer fully navigable.","zh":"如果水道被阻塞或太淺，它就不再完全可通航。"},{"en":"This phrase describes water routes that can be used practically.","zh":"這個短語描述可實際使用的水路。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":8},{"front":"paths and trails","meaning":"小徑和步道","examples":[{"en":"Paths and trails run alongside many waterways.","zh":"小徑和步道沿着許多水道伸延。"},{"en":"Paths and trails are routes for walking, cycling or exploring outdoors.","zh":"小徑和步道是供步行、踩單車或戶外探索的路線。"},{"en":"A family may use paths and trails beside a canal for a weekend walk.","zh":"家庭可能在週末使用運河旁的小徑和步道散步。"},{"en":"Good paths and trails make waterways useful even for people who never use boats.","zh":"良好的小徑和步道讓水道對從不坐船的人也有用。"},{"en":"This phrase refers to land routes connected with outdoor recreation.","zh":"這個短語指與戶外消閒相關的陸上路線。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":8},{"front":"run alongside","meaning":"沿着……伸延","examples":[{"en":"Paths and trails run alongside the waterways.","zh":"小徑和步道沿着水道伸延。"},{"en":"To run alongside something means to extend next to it in the same direction.","zh":"沿着某物伸延，是指在其旁邊以相同方向延伸。"},{"en":"A cycle path may run alongside a railway line for several kilometres.","zh":"單車徑可能沿着鐵路線伸延數公里。"},{"en":"Paths that run alongside canals make them easier to enjoy and maintain.","zh":"沿着運河伸延的小徑讓人更容易享受和維護運河。"},{"en":"This phrase describes physical position and direction.","zh":"這個短語描述實體位置和方向。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":8},{"front":"waterside living","meaning":"水邊居住","examples":[{"en":"Waterside living has become fashionable.","zh":"水邊居住已變得時尚。"},{"en":"Waterside living means living near a river, canal, lake or harbour.","zh":"水邊居住是指住在河、運河、湖或港口附近。"},{"en":"New flats beside a canal may appeal to people who enjoy waterside living.","zh":"運河旁的新住宅可能吸引喜歡水邊居住的人。"},{"en":"Cleaned-up waterways can make nearby housing more attractive.","zh":"清理後的水道可以令附近住宅更吸引。"},{"en":"This phrase connects housing with the appeal of water views and leisure space.","zh":"這個短語把住屋與水景和休閒空間的吸引力連接起來。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":8},{"front":"fashionable","meaning":"時尚的；流行的","examples":[{"en":"Waterside living is now fashionable.","zh":"水邊居住現在很時尚。"},{"en":"Fashionable means popular, stylish and admired by many people at a particular time.","zh":"時尚的，是指在某時期受歡迎、有格調並被許多人欣賞。"},{"en":"Old warehouse flats became fashionable after artists and cafés moved into the area.","zh":"藝術家和咖啡店搬入後，舊倉庫單位變得時尚。"},{"en":"When a place becomes fashionable, property prices and visitor numbers may rise.","zh":"當一個地方變得流行，樓價和遊客數量可能上升。"},{"en":"This word describes social popularity, not only clothing style.","zh":"這個詞描述社會受歡迎程度，而不只是衣着風格。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":8},{"front":"a focus for urban renewal","meaning":"城市更新的焦點","examples":[{"en":"City-centre canals have been a focus for urban renewal.","zh":"市中心運河一直是城市更新的焦點。"},{"en":"A focus for urban renewal is an area or feature that becomes central to improving a city district.","zh":"城市更新的焦點，是指成為改善城市地區核心的區域或特色。"},{"en":"A disused railway station can become a focus for urban renewal if it is turned into shops and public space.","zh":"如果廢棄火車站被改造成商店和公共空間，它可以成為城市更新焦點。"},{"en":"When canals attract investment, they can help revive surrounding neighbourhoods.","zh":"當運河吸引投資，它們可以幫助周邊社區復興。"},{"en":"This phrase shows how one place can lead wider city improvement.","zh":"這個短語顯示一個地方如何帶動更廣泛的城市改善。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":9},{"front":"urban renewal","meaning":"城市更新","examples":[{"en":"Canal restoration can support urban renewal.","zh":"運河復修可以支持城市更新。"},{"en":"Urban renewal means improving old or neglected city areas through repair, new uses and investment.","zh":"城市更新是透過修復、新用途和投資改善舊有或被忽視的城市地區。"},{"en":"Urban renewal may turn empty factories into housing, parks and community centres.","zh":"城市更新可能把空置工廠改造成住宅、公園和社區中心。"},{"en":"Renewal can attract businesses and residents, but it must also serve existing communities.","zh":"更新可以吸引企業和居民，但也必須服務原有社區。"},{"en":"This phrase refers to city improvement and redevelopment.","zh":"這個短語指城市改善和再發展。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":9},{"front":"despite our obsession with","meaning":"儘管我們沉迷於……","examples":[{"en":"Despite Britain’s obsession with road transport, waterways are being reconsidered.","zh":"儘管英國沉迷於道路運輸，水道正在被重新考慮。"},{"en":"Despite our obsession with something means although we are strongly focused on it, another idea still matters.","zh":"儘管我們沉迷於某事，是指雖然我們非常集中於它，另一個想法仍然重要。"},{"en":"Despite our obsession with exam marks, students also need sleep, confidence and curiosity.","zh":"儘管我們沉迷於考試分數，學生也需要睡眠、信心和好奇心。"},{"en":"This phrase contrasts a dominant habit with an alternative approach.","zh":"這個短語把主導習慣與另一種方法作對比。"},{"en":"It often suggests that people have been too focused on one solution.","zh":"它常暗示人們過分集中於一種解決方法。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":9},{"front":"road transport","meaning":"道路運輸","examples":[{"en":"Britain has long depended heavily on road transport.","zh":"英國長期高度依賴道路運輸。"},{"en":"Road transport means moving people or goods by cars, buses, vans or lorries on roads.","zh":"道路運輸是指透過道路上的汽車、巴士、客貨車或貨車運送人或貨物。"},{"en":"A delivery company uses road transport when it sends parcels by van.","zh":"送貨公司用客貨車寄送包裹時，就是使用道路運輸。"},{"en":"Heavy dependence on road transport can create congestion and pollution.","zh":"高度依賴道路運輸會造成擠塞和污染。"},{"en":"This phrase contrasts with rail, air and water transport.","zh":"這個短語與鐵路、空運和水路運輸形成對比。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":9},{"front":"environmental considerations","meaning":"環境考慮因素","examples":[{"en":"Environmental considerations are forcing businesses to reconsider canal transport.","zh":"環境考慮因素正迫使企業重新考慮運河運輸。"},{"en":"Environmental considerations are concerns about pollution, emissions, energy use and damage to nature.","zh":"環境考慮因素，是關於污染、排放、能源使用和自然破壞的顧慮。"},{"en":"A school may choose reusable lunch boxes because of environmental considerations.","zh":"學校可能因環境考慮因素而選擇可重用飯盒。"},{"en":"When environmental considerations become important, companies may change how they deliver goods.","zh":"當環境考慮因素變得重要，公司可能改變送貨方式。"},{"en":"This phrase shows that decisions are influenced by ecological impact.","zh":"這個短語顯示決策受生態影響所左右。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":9},{"front":"force someone to","meaning":"迫使某人去","examples":[{"en":"Environmental concerns are forcing government and business to rethink transport.","zh":"環境顧慮正迫使政府和企業重新思考運輸。"},{"en":"To force someone to do something means to make them do it because pressure or circumstances leave little choice.","zh":"迫使某人做某事，是指壓力或情況使他們幾乎沒有選擇，只能去做。"},{"en":"A sudden rent rise may force a family to move to a smaller flat.","zh":"租金突然上升可能迫使家庭搬到較小單位。"},{"en":"Pollution can force authorities to look for cleaner transport systems.","zh":"污染可以迫使當局尋找更清潔的運輸系統。"},{"en":"This phrase shows strong pressure, not gentle encouragement.","zh":"這個短語顯示強大壓力，而不是溫和鼓勵。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":9},{"front":"turn the clock back","meaning":"讓時光倒流；回到過去做法","examples":[{"en":"Businesses may need to turn the clock back and use waterways again.","zh":"企業可能需要回到過去做法，再次使用水道。"},{"en":"To turn the clock back means to return to an older way of doing things.","zh":"讓時光倒流，是指回到較舊的做事方式。"},{"en":"A school may turn the clock back by using handwritten notes when tablets fail.","zh":"當平板電腦失靈，學校可能回到手寫筆記的做法。"},{"en":"Sometimes an old method becomes useful again because modern problems change.","zh":"有時舊方法因現代問題改變而再次變得有用。"},{"en":"This phrase does not always mean going backward badly; it can mean reviving a past solution.","zh":"這個短語不一定指壞的倒退；也可以指復興過去的解決方法。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":9},{"front":"in a minor way","meaning":"在較小程度上","examples":[{"en":"Waterways are working again, at least in a minor way.","zh":"水道再次運作，至少在較小程度上如此。"},{"en":"In a minor way means to a small or limited degree.","zh":"在較小程度上，是指以小規模或有限程度。"},{"en":"A student may improve in a minor way after one lesson, but real progress needs time.","zh":"學生一堂課後可能有小幅改善，但真正進步需要時間。"},{"en":"Small changes can still matter if they show a new direction.","zh":"小改變仍然重要，如果它顯示新方向。"},{"en":"This phrase limits a claim so it does not sound exaggerated.","zh":"這個短語限制主張，避免聽起來誇大。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":9},{"front":"get waterways working again","meaning":"令水道重新運作","examples":[{"en":"Government and business want to get waterways working again.","zh":"政府和企業希望令水道重新運作。"},{"en":"To get waterways working again means to make canals and rivers useful for transport or other activity after decline.","zh":"令水道重新運作，是指在衰落後使運河和河流重新用於運輸或其他活動。"},{"en":"A city may get an old tram line working again to reduce traffic.","zh":"城市可能令舊電車線重新運作，以減少交通。"},{"en":"Restoring locks, routes and loading points can get waterways working again.","zh":"復修船閘、路線和裝卸點可以令水道重新運作。"},{"en":"This phrase focuses on returning a system to practical use.","zh":"這個短語聚焦讓系統重新實際使用。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":9},{"front":"industrial goods","meaning":"工業貨物","examples":[{"en":"Industrial goods have never completely disappeared from large rivers.","zh":"工業貨物從未完全從大河上消失。"},{"en":"Industrial goods are materials or products used in industry, building or manufacturing.","zh":"工業貨物是用於工業、建築或製造的材料或產品。"},{"en":"Coal, steel and petroleum are examples of industrial goods.","zh":"煤、鋼材和石油都是工業貨物例子。"},{"en":"Heavy industrial goods often suit water transport because they do not need fast delivery.","zh":"重型工業貨物通常適合水路運輸，因為它們不需要快速送達。"},{"en":"This phrase refers to goods for production, not ordinary shopping items.","zh":"這個短語指生產用貨物，而不是普通購物商品。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":9},{"front":"coal","meaning":"煤","examples":[{"en":"Coal is one of the industrial goods still carried by water.","zh":"煤是仍由水路運載的工業貨物之一。"},{"en":"Coal is a black fuel dug from the ground and burned for heat or power.","zh":"煤是從地下挖出、燃燒以產生熱力或電力的黑色燃料。"},{"en":"A power station may receive coal by barge, train or lorry.","zh":"發電廠可能透過駁船、火車或貨車接收煤。"},{"en":"Coal is heavy, so water transport can be useful when routes are available.","zh":"煤很重，所以當路線可用時，水路運輸會有用。"},{"en":"This word names a traditional industrial fuel.","zh":"這個詞命名一種傳統工業燃料。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":9},{"front":"steel","meaning":"鋼材","examples":[{"en":"Steel can be transported by waterway.","zh":"鋼材可以由水道運輸。"},{"en":"Steel is a strong metal made mainly from iron and used in buildings, vehicles and machines.","zh":"鋼材是主要由鐵製成的堅固金屬，用於建築、車輛和機器。"},{"en":"Construction companies use steel for bridges, towers and railway lines.","zh":"建築公司使用鋼材建造橋樑、大樓和鐵路線。"},{"en":"Because steel is heavy, barges may carry it more efficiently than lorries over some routes.","zh":"因為鋼材很重，在某些路線上駁船可能比貨車更有效率地運載。"},{"en":"This word refers to an important industrial material.","zh":"這個詞指重要工業材料。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":10},{"front":"aggregates","meaning":"砂石骨料","examples":[{"en":"Aggregates are now carried by barge on the River Severn.","zh":"砂石骨料現在由駁船在塞文河上運載。"},{"en":"Aggregates are materials such as sand, gravel and crushed stone used in construction.","zh":"砂石骨料是建築中使用的沙、碎石和碎石料等材料。"},{"en":"Builders use aggregates to make concrete, roads and foundations.","zh":"建築工人使用砂石骨料製作混凝土、道路和地基。"},{"en":"Aggregates are heavy and bulky, so water transport can be suitable for them.","zh":"砂石骨料重且體積大，因此水路運輸可能適合。"},{"en":"This word refers to basic building materials rather than finished products.","zh":"這個詞指基本建築材料，而不是完成品。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":10},{"front":"petroleum","meaning":"石油","examples":[{"en":"Petroleum is among the industrial goods carried on waterways.","zh":"石油是水道上運載的工業貨物之一。"},{"en":"Petroleum is crude oil or oil-based fuel used for energy, transport and industry.","zh":"石油是用於能源、運輸和工業的原油或油基燃料。"},{"en":"Refineries process petroleum into petrol, diesel and other products.","zh":"煉油廠把石油加工成汽油、柴油和其他產品。"},{"en":"Because petroleum is valuable and heavy in large quantities, transport must be carefully managed.","zh":"因為石油有價值且大量時很重，運輸必須仔細管理。"},{"en":"This word names an important energy resource.","zh":"這個詞命名一種重要能源資源。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":10},{"front":"designated commercial waterways","meaning":"指定商業水道","examples":[{"en":"Some rivers are designated commercial waterways.","zh":"有些河流被指定為商業水道。"},{"en":"Designated commercial waterways are water routes officially identified for business or freight use.","zh":"指定商業水道，是官方確認用於商業或貨運的水路。"},{"en":"A river may be designated commercial if barges can safely carry goods along it.","zh":"如果駁船能安全沿河運送貨物，該河可能被指定為商業水道。"},{"en":"Official designation can attract investment in docks, loading points and maintenance.","zh":"官方指定可以吸引碼頭、裝卸點和維修方面的投資。"},{"en":"This phrase shows that some waterways have a recognised economic function.","zh":"這個短語顯示有些水道具有被承認的經濟功能。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":10},{"front":"the River Severn","meaning":"塞文河","examples":[{"en":"Barges on the River Severn have started carrying aggregates again.","zh":"塞文河上的駁船已重新開始運載砂石骨料。"},{"en":"The River Severn is named as a waterway used for carrying freight in Britain.","zh":"塞文河在文中被指為英國用作貨運的水道。"},{"en":"A river like the Severn can connect inland places with industrial and construction sites.","zh":"像塞文河這樣的河流可以連接內陸地方與工業和建築地點。"},{"en":"When freight returns to a river, it may reduce local lorry journeys.","zh":"當貨運回到河流上，它可能減少本地貨車行程。"},{"en":"This phrase gives a specific geographical example.","zh":"這個短語提供具體地理例子。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":10},{"front":"the equivalent of","meaning":"相等於……","examples":[{"en":"Barges carry the equivalent of 34,000 lorry loads each year.","zh":"駁船每年運載相等於 34,000 車貨車載貨量的貨物。"},{"en":"The equivalent of something means the same amount, value or effect as that thing.","zh":"相等於某物，是指與該物相同的數量、價值或效果。"},{"en":"One online lesson may save the equivalent of two hours of travel time.","zh":"一堂網課可能節省相等於兩小時的交通時間。"},{"en":"Comparing barges with lorry loads helps readers understand the scale of freight moved.","zh":"把駁船與貨車載貨量比較，幫助讀者理解運送貨量規模。"},{"en":"This phrase is useful when translating one measure into a more familiar one.","zh":"這個短語適合把一種量度轉換成更熟悉的量度。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":10},{"front":"lorry loads","meaning":"貨車載貨量","examples":[{"en":"Barges on the River Severn carry thousands of lorry loads of aggregates.","zh":"塞文河上的駁船運載數以千計貨車載貨量的砂石骨料。"},{"en":"Lorry loads are amounts of goods that would fill one or more lorries.","zh":"貨車載貨量是指足以裝滿一輛或多輛貨車的貨物數量。"},{"en":"A building project may need hundreds of lorry loads of sand and stone.","zh":"建築項目可能需要數百車貨車載貨量的沙和石。"},{"en":"If barges carry many lorry loads, fewer heavy trucks need to use local roads.","zh":"如果駁船運載許多貨車載貨量，較少重型貨車需要使用本地道路。"},{"en":"This phrase measures freight in terms of truck capacity.","zh":"這個短語以貨車容量來衡量貨運量。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":10},{"front":"freight traffic","meaning":"貨運交通","examples":[{"en":"The River Severn has seen its first freight traffic for a decade.","zh":"塞文河出現十年來首次貨運交通。"},{"en":"Freight traffic means the movement of goods along a transport route.","zh":"貨運交通是指貨物沿運輸路線移動。"},{"en":"A railway line has freight traffic when trains carry containers or raw materials.","zh":"當火車運載貨櫃或原材料時，鐵路線就有貨運交通。"},{"en":"Returning freight traffic can show that an old route is becoming useful again.","zh":"貨運交通回歸可以顯示舊路線正重新變得有用。"},{"en":"This phrase refers to goods transport, not ordinary passenger travel.","zh":"這個短語指貨物運輸，而不是普通乘客出行。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":10},{"front":"for a decade","meaning":"長達十年","examples":[{"en":"The River Severn had no freight traffic for a decade.","zh":"塞文河長達十年沒有貨運交通。"},{"en":"For a decade means for ten years.","zh":"長達十年，是指持續十年。"},{"en":"A shop may remain family-owned for a decade before being sold.","zh":"一間店可能長達十年由同一家族擁有，然後才出售。"},{"en":"If a transport route is unused for a decade, restarting it may require planning and repair.","zh":"如果運輸路線長達十年未被使用，重新啟用可能需要規劃和維修。"},{"en":"This phrase gives the length of time something continued.","zh":"這個短語給出某事持續的時間長度。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":10},{"front":"British Waterways","meaning":"英國水道局","examples":[{"en":"British Waterways owns about half of Britain’s navigable inland waterways.","zh":"英國水道局擁有英國約一半可通航內陸水道。"},{"en":"British Waterways is named as the organisation responsible for many British inland waterways.","zh":"英國水道局在文中被指為負責許多英國內陸水道的組織。"},{"en":"An organisation like British Waterways may manage canals, locks, paths and freight projects.","zh":"像英國水道局這樣的組織可能管理運河、船閘、小徑和貨運項目。"},{"en":"Ownership matters because maintenance and commercial planning need clear responsibility.","zh":"擁有權很重要，因為維修和商業規劃需要清晰責任。"},{"en":"This phrase identifies a key body in the canal system.","zh":"這個短語指出運河系統中的關鍵機構。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":10},{"front":"navigable inland waterways","meaning":"可通航內陸水道","examples":[{"en":"British Waterways owns many navigable inland waterways.","zh":"英國水道局擁有許多可通航內陸水道。"},{"en":"Navigable inland waterways are canals and rivers inside a country that boats can use.","zh":"可通航內陸水道是位於國家內部、船隻可以使用的運河和河流。"},{"en":"These waterways can carry barges, leisure boats or industrial goods.","zh":"這些水道可以運載駁船、遊船或工業貨物。"},{"en":"If inland waterways are navigable, they can reduce pressure on roads.","zh":"如果內陸水道可通航，它們可以減輕道路壓力。"},{"en":"This phrase combines location, usability and transport function.","zh":"這個短語結合位置、可用性和運輸功能。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":10},{"front":"25-ton lorry loads","meaning":"二十五噸貨車載貨量","examples":[{"en":"British Waterways carried the equivalent of 64,000 25-ton lorry loads of freight.","zh":"英國水道局運載了相等於 64,000 車二十五噸貨車載貨量的貨物。"},{"en":"25-ton lorry loads are amounts of freight equal to what 25-ton lorries would carry.","zh":"二十五噸貨車載貨量，是指相等於二十五噸貨車所能運載的貨量。"},{"en":"A construction project may compare barge loads with 25-ton lorry loads to estimate road savings.","zh":"建築項目可能把駁船載貨量與二十五噸貨車載貨量比較，以估計節省的道路行程。"},{"en":"Using this measure helps show how many heavy truck journeys water transport can replace.","zh":"使用這種量度有助顯示水路運輸可以取代多少重型貨車行程。"},{"en":"This phrase expresses freight volume through familiar road-transport units.","zh":"這個短語透過熟悉的道路運輸單位表達貨運量。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":11},{"front":"be certain to increase","meaning":"肯定會增加","examples":[{"en":"The organisation says the figures are certain to increase.","zh":"該組織表示數字肯定會增加。"},{"en":"Be certain to increase means will definitely or almost definitely rise.","zh":"肯定會增加，是指一定或幾乎一定會上升。"},{"en":"If a school opens a new campus, student numbers are certain to increase.","zh":"如果學校開設新校舍，學生人數肯定會增加。"},{"en":"Strong demand and new schemes can make future growth very likely.","zh":"強勁需求和新計劃可以令未來增長非常可能。"},{"en":"This phrase expresses strong confidence about an upward trend.","zh":"這個短語表達對上升趨勢的強烈信心。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":11},{"front":"new schemes","meaning":"新計劃","examples":[{"en":"New schemes are expected to increase freight on waterways.","zh":"新計劃預計會增加水道貨運。"},{"en":"New schemes are new organised plans or projects designed to achieve a goal.","zh":"新計劃是為達成目標而設計的新組織方案或項目。"},{"en":"A council may start new schemes to encourage cycling and reduce car use.","zh":"市議會可能推出新計劃，鼓勵踩單車並減少汽車使用。"},{"en":"New schemes can turn a good idea into practical action.","zh":"新計劃可以把好想法轉化為實際行動。"},{"en":"This phrase is often used for public or business projects.","zh":"這個短語常用於公共或商業項目。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":11},{"front":"carrying freight by water","meaning":"以水路運送貨物","examples":[{"en":"Carrying freight by water uses less energy than road transport.","zh":"以水路運送貨物比道路運輸使用較少能源。"},{"en":"Carrying freight by water means moving goods on rivers, canals or other waterways.","zh":"以水路運送貨物，是指在河流、運河或其他水道上運送貨品。"},{"en":"A company may carry freight by water when goods are heavy and delivery is not urgent.","zh":"當貨物沉重且送達不緊急，公司可能以水路運送貨物。"},{"en":"Water freight can reduce energy use because one barge can carry a large load.","zh":"水路貨運可以減少能源使用，因為一艘駁船能載大量貨物。"},{"en":"This phrase contrasts water-based cargo transport with road transport.","zh":"這個短語把水路貨物運輸與道路運輸作對比。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":11},{"front":"a quarter of the energy","meaning":"四分之一的能源","examples":[{"en":"Water transport uses about a quarter of the energy of an equivalent road journey.","zh":"水路運輸使用相等道路運輸行程約四分之一的能源。"},{"en":"A quarter of the energy means 25% of the energy used by another option.","zh":"四分之一的能源，是指使用另一選項能源的 25%。"},{"en":"If a machine uses a quarter of the energy, it is much more efficient than the old one.","zh":"如果一部機器使用四分之一能源，它就比舊機器有效率得多。"},{"en":"Lower energy use usually means lower emissions and lower operating costs.","zh":"較低能源使用通常代表較低排放和較低營運成本。"},{"en":"This phrase gives a clear comparison of efficiency.","zh":"這個短語清楚比較能源效益。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":11},{"front":"equivalent road journey","meaning":"相等的道路運輸行程","examples":[{"en":"A barge trip may use less energy than an equivalent road journey.","zh":"駁船行程使用的能源可能少於相等的道路運輸行程。"},{"en":"An equivalent road journey is a road trip carrying the same load over a similar route or distance.","zh":"相等的道路運輸行程，是指運載相同貨量、路線或距離相近的道路行程。"},{"en":"A train journey may be compared with an equivalent road journey to measure emissions.","zh":"火車行程可與相等道路行程比較，以量度排放。"},{"en":"Comparing equivalent journeys makes transport efficiency easier to judge fairly.","zh":"比較相等行程令運輸效益更容易公平判斷。"},{"en":"This phrase is used when two transport methods are being compared.","zh":"當比較兩種運輸方法時，會使用這個短語。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":11},{"front":"in comparison to","meaning":"與……相比","examples":[{"en":"In comparison to lorries, barges produce low emissions.","zh":"與貨車相比，駁船產生低排放。"},{"en":"In comparison to means when compared with another thing.","zh":"與某物相比，是指把某事與另一事對照。"},{"en":"In comparison to taxis, buses can carry more people using less road space.","zh":"與的士相比，巴士可以用較少道路空間載更多人。"},{"en":"This phrase helps show advantages or disadvantages by direct comparison.","zh":"這個短語透過直接比較顯示優點或缺點。"},{"en":"It is a formal way to introduce contrast.","zh":"它是引入對比的正式說法。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":11},{"front":"low emissions","meaning":"低排放","examples":[{"en":"Barges produce low emissions and little noise.","zh":"駁船產生低排放和少量噪音。"},{"en":"Low emissions means releasing only a small amount of pollution or greenhouse gases.","zh":"低排放是指只釋放少量污染物或溫室氣體。"},{"en":"Electric buses can offer low emissions compared with diesel buses.","zh":"與柴油巴士相比，電動巴士可以提供低排放。"},{"en":"Low emissions help reduce air pollution and climate impact.","zh":"低排放有助減少空氣污染和氣候影響。"},{"en":"This phrase is often used when comparing transport options.","zh":"這個短語常用於比較運輸選項。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":11},{"front":"little noise","meaning":"噪音少","examples":[{"en":"Barges create little noise compared with lorries.","zh":"與貨車相比，駁船產生的噪音少。"},{"en":"Little noise means only a small amount of sound or disturbance.","zh":"噪音少，是指只有少量聲音或干擾。"},{"en":"A quiet electric train may create little noise near homes.","zh":"安靜的電動列車在住宅附近可能噪音少。"},{"en":"Transport that creates little noise can improve quality of life for nearby residents.","zh":"噪音少的運輸可以改善附近居民的生活質素。"},{"en":"This phrase describes a practical environmental advantage.","zh":"這個短語描述實際環境優勢。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":11},{"front":"visually unobtrusive","meaning":"視覺上不礙眼的","examples":[{"en":"Barges are visually unobtrusive.","zh":"駁船在視覺上不礙眼。"},{"en":"Visually unobtrusive means not standing out in an ugly or disturbing way when people look at it.","zh":"視覺上不礙眼，是指看起來不會突兀、難看或造成干擾。"},{"en":"A small sign in a historic street can be visually unobtrusive if it matches the surroundings.","zh":"如果小標誌配合周圍環境，它在歷史街道中可以視覺上不礙眼。"},{"en":"Barges may be less visually intrusive than long lines of lorries on busy roads.","zh":"與繁忙道路上一長列貨車相比，駁船可能較不影響視覺。"},{"en":"This phrase describes something that does not spoil the view.","zh":"這個短語描述不會破壞景觀的事物。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":11},{"front":"transport campaigner","meaning":"交通議題倡議者","examples":[{"en":"Tony Bosworth is a transport campaigner for Friends of the Earth.","zh":"Tony Bosworth 是地球之友的交通議題倡議者。"},{"en":"A transport campaigner is a person who publicly argues for changes in transport policy.","zh":"交通議題倡議者是公開主張改變交通政策的人。"},{"en":"A transport campaigner may support safer cycle lanes or fewer polluting lorries.","zh":"交通倡議者可能支持更安全單車徑或減少污染貨車。"},{"en":"Campaigners can influence public debate by explaining problems and proposing solutions.","zh":"倡議者可以透過解釋問題和提出方案影響公共討論。"},{"en":"This phrase describes an advocate, not simply a transport worker.","zh":"這個短語描述倡議者，而不只是交通從業員。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":11},{"front":"Friends of the Earth","meaning":"地球之友","examples":[{"en":"Friends of the Earth supports efforts to reduce road freight.","zh":"地球之友支持減少道路貨運的努力。"},{"en":"Friends of the Earth is named as an environmental organisation in the passage.","zh":"地球之友在文中被指為一個環保組織。"},{"en":"An environmental group may support canal freight if it reduces emissions and road congestion.","zh":"如果運河貨運能減少排放和道路擠塞，環保組織可能支持它。"},{"en":"Such organisations often campaign for policies that protect climate and public health.","zh":"這類組織常倡議保護氣候和公共健康的政策。"},{"en":"This phrase identifies the campaign group quoted in the passage.","zh":"這個短語指出文中引用的倡議團體。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":12},{"front":"take freight off the roads","meaning":"把貨運從道路上轉移走","examples":[{"en":"Canals can help take freight off the roads.","zh":"運河可以幫助把貨運從道路上轉移走。"},{"en":"To take freight off the roads means to move goods by another method instead of lorries.","zh":"把貨運從道路上轉移走，是指用另一種方式而不是貨車運送貨物。"},{"en":"Rail freight can take heavy goods off the roads between cities.","zh":"鐵路貨運可以把城市之間的重貨從道路上轉移走。"},{"en":"Taking freight off roads can reduce traffic jams, emissions and road wear.","zh":"把貨運轉離道路可以減少交通堵塞、排放和道路磨損。"},{"en":"This phrase describes shifting cargo away from road transport.","zh":"這個短語描述把貨物運輸從道路轉移出去。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":12},{"front":"be fully explored","meaning":"得到充分探討","examples":[{"en":"Any method that reduces road freight needs to be fully explored.","zh":"任何能減少道路貨運的方法都需要得到充分探討。"},{"en":"To be fully explored means to be carefully examined before being accepted or rejected.","zh":"得到充分探討，是指在接受或否定之前被仔細研究。"},{"en":"A school should fully explore timetable changes before deciding they will not work.","zh":"學校在決定時間表改變不可行之前，應充分探討它。"},{"en":"If a solution may reduce pollution, planners should study its costs and benefits carefully.","zh":"如果一個方案可能減少污染，規劃者應仔細研究其成本和好處。"},{"en":"This phrase suggests serious investigation, not a quick opinion.","zh":"這個短語暗示認真調查，而不是快速意見。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":12},{"front":"cut the pollution","meaning":"減少污染","examples":[{"en":"Canals can help cut the pollution that causes climate change.","zh":"運河可以幫助減少導致氣候變化的污染。"},{"en":"To cut pollution means to reduce the amount of harmful substances released into the environment.","zh":"減少污染，是指降低排放到環境中的有害物質數量。"},{"en":"Using public transport can cut pollution if fewer people drive private cars.","zh":"如果較少人駕私家車，使用公共交通可以減少污染。"},{"en":"Moving freight from lorries to barges may cut pollution by using less fuel.","zh":"把貨運從貨車轉到駁船可能透過使用較少燃料來減少污染。"},{"en":"This phrase focuses on reducing environmental harm.","zh":"這個短語聚焦減少環境傷害。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":12},{"front":"climate change","meaning":"氣候變化","examples":[{"en":"Reducing road freight can help reduce pollution that causes climate change.","zh":"減少道路貨運可以幫助減少導致氣候變化的污染。"},{"en":"Climate change means long-term changes in Earth’s temperature, weather patterns and climate systems.","zh":"氣候變化是指地球溫度、天氣模式和氣候系統的長期改變。"},{"en":"Burning fossil fuels releases gases that contribute to climate change.","zh":"燃燒化石燃料會釋放導致氣候變化的氣體。"},{"en":"Cleaner transport can reduce emissions linked to climate change.","zh":"更清潔交通可以減少與氣候變化相關的排放。"},{"en":"This phrase refers to a global environmental problem.","zh":"這個短語指全球環境問題。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":12},{"front":"there is a limit to","meaning":"……是有限度的","examples":[{"en":"There is a limit to what canals can carry.","zh":"運河能運載甚麼是有限度的。"},{"en":"There is a limit to something means it cannot go beyond a certain point.","zh":"某事是有限度的，是指它不能超過某個範圍。"},{"en":"There is a limit to how much homework students can complete well in one evening.","zh":"學生一晚能做好多少功課是有限度的。"},{"en":"Canal transport is useful, but speed and cargo type create limits.","zh":"運河運輸有用，但速度和貨物種類造成限制。"},{"en":"This phrase prevents an argument from sounding too extreme.","zh":"這個短語防止論點聽起來太絕對。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":12},{"front":"the slow pace of","meaning":"……的緩慢速度","examples":[{"en":"The slow pace of water travel is unsuitable for some goods.","zh":"水路運輸的緩慢速度不適合某些貨物。"},{"en":"The slow pace of something means its low speed or gradual movement.","zh":"某事的緩慢速度，是指其低速度或漸進移動。"},{"en":"The slow pace of a queue can make customers impatient.","zh":"排隊速度緩慢會令顧客不耐煩。"},{"en":"Slow transport may be fine for heavy materials but bad for urgent deliveries.","zh":"緩慢運輸可能適合重型材料，但不適合緊急送貨。"},{"en":"This phrase explains why some methods do not fit some needs.","zh":"這個短語解釋為何某些方法不配合某些需要。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":12},{"front":"water travel","meaning":"水路運輸","examples":[{"en":"The slow pace of water travel does not suit fresh produce.","zh":"水路運輸的緩慢速度不適合新鮮農產品。"},{"en":"Water travel means movement by boat, barge or ship along rivers, canals or seas.","zh":"水路運輸是指乘船、駁船或船隻沿河流、運河或海洋移動。"},{"en":"Tourists may enjoy water travel because it is slow and scenic.","zh":"遊客可能喜歡水路旅行，因為它慢而風景優美。"},{"en":"For freight, water travel can save energy but may take longer than roads.","zh":"對貨運而言，水路運輸可以節省能源，但可能比道路更慢。"},{"en":"This phrase covers transport by water, not walking beside water.","zh":"這個短語涵蓋水上運輸，而不是在水邊步行。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":12},{"front":"fit well with","meaning":"與……配合得好","examples":[{"en":"Water transport does not fit well with fresh produce.","zh":"水路運輸與新鮮農產品配合得不好。"},{"en":"To fit well with something means to suit its needs or conditions.","zh":"與某事配合得好，是指適合其需要或條件。"},{"en":"Online lessons fit well with students who live far from school.","zh":"網課與住得離學校遠的學生配合得好。"},{"en":"Slow transport does not fit well with goods that must arrive fresh.","zh":"緩慢運輸與必須保持新鮮的貨物配合不好。"},{"en":"This phrase describes suitability between a method and a situation.","zh":"這個短語描述方法與情況之間的適合程度。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":12},{"front":"limited shelf-life","meaning":"有限保鮮期","examples":[{"en":"Fresh produce has a limited shelf-life.","zh":"新鮮農產品有有限保鮮期。"},{"en":"Limited shelf-life means a product stays usable or fresh for only a short time.","zh":"有限保鮮期，是指產品只能在短時間內保持可用或新鮮。"},{"en":"Milk has a limited shelf-life, so shops must sell it quickly.","zh":"牛奶有有限保鮮期，所以商店必須很快售出。"},{"en":"Goods with limited shelf-life need fast transport and careful storage.","zh":"有有限保鮮期的貨物需要快速運輸和小心儲存。"},{"en":"This phrase is common when discussing food and perishable products.","zh":"這個短語常用於討論食物和易腐產品。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":12},{"front":"fresh produce","meaning":"新鮮農產品","examples":[{"en":"Fresh produce is not ideal for slow water transport.","zh":"新鮮農產品並不適合緩慢的水路運輸。"},{"en":"Fresh produce means fresh fruit, vegetables and similar food products.","zh":"新鮮農產品是指新鮮水果、蔬菜和類似食物產品。"},{"en":"A supermarket receives fresh produce early in the morning before shoppers arrive.","zh":"超市在顧客到來前的清晨接收新鮮農產品。"},{"en":"Fresh produce can spoil if transport takes too long or storage is poor.","zh":"如果運輸太久或儲存不佳，新鮮農產品會變壞。"},{"en":"This phrase refers to perishable food, not packaged dry goods.","zh":"這個短語指易腐食物，而不是包裝乾貨。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":12},{"front":"trust something to","meaning":"把……交託給","examples":[{"en":"Supermarkets may not trust cherry tomatoes to water transport.","zh":"超市可能不會把車厘茄交託給水路運輸。"},{"en":"To trust something to a method means to rely on that method to handle it safely.","zh":"把某物交託給某方法，是指依靠該方法安全處理它。"},{"en":"Parents may not trust a fragile cake to a crowded bus journey.","zh":"父母可能不會把脆弱蛋糕交託給擁擠巴士旅程。"},{"en":"Businesses avoid transport methods they do not trust for delicate goods.","zh":"企業會避免把精細貨物交給它們不信任的運輸方法。"},{"en":"This phrase shows doubt about whether a method is suitable or safe.","zh":"這個短語顯示對某方法是否合適或安全的懷疑。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":13},{"front":"cherry tomatoes","meaning":"車厘茄","examples":[{"en":"Cherry tomatoes may not be suitable for slow canal transport.","zh":"車厘茄可能不適合緩慢的運河運輸。"},{"en":"Cherry tomatoes are small round tomatoes often used in salads and fresh dishes.","zh":"車厘茄是小而圓的番茄，常用於沙律和新鮮菜式。"},{"en":"A café may buy cherry tomatoes daily because customers expect them to be fresh.","zh":"咖啡店可能每天購買車厘茄，因為顧客期望它們新鮮。"},{"en":"Delicate fresh food can be damaged if transport is slow or rough.","zh":"精細新鮮食物如果運輸緩慢或顛簸，可能受損。"},{"en":"This phrase gives a clear example of perishable produce.","zh":"這個短語提供易腐農產品的清楚例子。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":13},{"front":"waste paper and plastic","meaning":"廢紙及塑膠","examples":[{"en":"Supermarkets might transport waste paper and plastic by canal.","zh":"超市可能用運河運送廢紙及塑膠。"},{"en":"Waste paper and plastic are used materials that can be collected, recycled or disposed of.","zh":"廢紙及塑膠是可以被收集、回收或棄置的已使用材料。"},{"en":"Shops often collect waste paper and plastic from packaging after deliveries.","zh":"店舖在送貨後常從包裝中收集廢紙和塑膠。"},{"en":"These materials are less urgent than fresh food, so slower canal transport may suit them.","zh":"這些材料不像新鮮食物那麼緊急，所以較慢的運河運輸可能適合。"},{"en":"This phrase names waste products that can be moved for recycling.","zh":"這個短語命名可被運去回收的廢物產品。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":13},{"front":"be used to protect","meaning":"被用來保護","examples":[{"en":"Waste paper and plastic are used to protect fresh produce.","zh":"廢紙和塑膠被用來保護新鮮農產品。"},{"en":"To be used to protect something means to serve the purpose of keeping it safe from damage.","zh":"被用來保護某物，是指用作防止其受損。"},{"en":"Bubble wrap is used to protect glasses during a house move.","zh":"氣泡紙在搬屋時被用來保護玻璃杯。"},{"en":"Protective packaging can reduce damage but also creates waste.","zh":"保護性包裝可以減少損壞，但也會產生廢物。"},{"en":"This phrase explains the function of an object or material.","zh":"這個短語解釋物件或材料的功能。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":13},{"front":"proposals to utilise","meaning":"利用……的建議","examples":[{"en":"Many proposals to utilise waterways are based on recycling schemes.","zh":"許多利用水道的建議都以回收計劃為基礎。"},{"en":"Proposals to utilise something are plans suggesting how to use it effectively.","zh":"利用某物的建議，是指提出如何有效使用它的計劃。"},{"en":"A council may discuss proposals to utilise empty school buildings for community classes.","zh":"市議會可能討論利用空置校舍開辦社區課程的建議。"},{"en":"Proposals become stronger when they match a real need and practical route.","zh":"當建議符合真實需要和可行路線，它就更有力。"},{"en":"This phrase introduces planned uses of an available resource.","zh":"這個短語引入對可用資源的計劃用途。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":13},{"front":"utilise Britain’s waterways","meaning":"利用英國水道","examples":[{"en":"Some schemes aim to utilise Britain’s waterways for waste transport.","zh":"有些計劃旨在利用英國水道運送廢物。"},{"en":"To utilise Britain’s waterways means to make practical use of the country’s canals and rivers.","zh":"利用英國水道，是指實際使用該國的運河和河流。"},{"en":"Businesses may utilise waterways to move heavy materials with less road traffic.","zh":"企業可能利用水道運送重型材料，以減少道路交通。"},{"en":"Using waterways can turn old infrastructure into a modern transport resource.","zh":"使用水道可以把舊基礎設施變成現代運輸資源。"},{"en":"This phrase is a formal way to say “use Britain’s waterways.”","zh":"這個短語是 “use Britain’s waterways” 的正式說法。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":13},{"front":"waste management","meaning":"廢物管理","examples":[{"en":"Many canal proposals focus on waste management.","zh":"許多運河建議集中於廢物管理。"},{"en":"Waste management means collecting, moving, treating, recycling or disposing of rubbish and unwanted materials.","zh":"廢物管理是收集、運送、處理、回收或棄置垃圾和不需要材料。"},{"en":"A city needs good waste management so streets stay clean and recycling works properly.","zh":"城市需要良好廢物管理，街道才會清潔，回收才會正常運作。"},{"en":"If waste management uses canals, fewer rubbish trucks may travel through local streets.","zh":"如果廢物管理使用運河，較少垃圾車可能駛經本地街道。"},{"en":"This phrase refers to the whole system for dealing with waste.","zh":"這個短語指處理廢物的整個系統。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":13},{"front":"recycling schemes","meaning":"回收計劃","examples":[{"en":"Recycling schemes may use canals to move waste.","zh":"回收計劃可能使用運河運送廢物。"},{"en":"Recycling schemes are organised plans for collecting and reusing materials instead of throwing them away.","zh":"回收計劃是收集和再用材料，而不是把它們丟棄的有組織方案。"},{"en":"A school recycling scheme may collect paper, bottles and batteries separately.","zh":"學校回收計劃可能分開收集紙張、瓶子和電池。"},{"en":"Recycling schemes need transport to move materials to processing plants.","zh":"回收計劃需要運輸，把材料送到處理廠。"},{"en":"This phrase describes organised recycling action, not one person’s habit only.","zh":"這個短語描述有組織的回收行動，而不只是個人習慣。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":13},{"front":"a pilot scheme","meaning":"試驗計劃","examples":[{"en":"A pilot scheme in Hackney has tested waste transport by barge.","zh":"哈克尼的一項試驗計劃測試了用駁船運送廢物。"},{"en":"A pilot scheme is a small trial project used to test whether an idea works.","zh":"試驗計劃是用來測試想法是否可行的小型試行項目。"},{"en":"A school may run a pilot scheme for later start times before changing the whole timetable.","zh":"學校可能先為較遲上課時間進行試驗計劃，再改變整個時間表。"},{"en":"Pilot schemes reduce risk because problems can be found before large-scale use.","zh":"試驗計劃能降低風險，因為大規模使用前可以發現問題。"},{"en":"This phrase describes testing a plan on a limited scale.","zh":"這個短語描述以有限規模測試計劃。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":13},{"front":"Hackney","meaning":"哈克尼","examples":[{"en":"A pilot scheme in Hackney uses barges to transport municipal waste.","zh":"哈克尼的一項試驗計劃使用駁船運送市政廢物。"},{"en":"Hackney is named as the area where a waste-transport trial took place.","zh":"哈克尼在文中被指為進行廢物運輸試驗的地區。"},{"en":"A local area like Hackney can test a transport idea before it spreads elsewhere.","zh":"像哈克尼這樣的地方可以先測試運輸想法，再推廣到其他地區。"},{"en":"Local pilot schemes help planners see how a proposal works on real streets and waterways.","zh":"本地試驗計劃幫助規劃者了解建議如何在真實街道和水道上運作。"},{"en":"This phrase gives the specific location of the trial.","zh":"這個短語給出試驗的具體地點。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":13},{"front":"municipal waste","meaning":"市政廢物","examples":[{"en":"Municipal waste is collected by truck and transferred to a barge.","zh":"市政廢物由貨車收集，然後轉移到駁船上。"},{"en":"Municipal waste means rubbish produced by homes, shops and local public services.","zh":"市政廢物是家庭、商店和本地公共服務產生的垃圾。"},{"en":"A city’s municipal waste may include food waste, packaging, paper and household rubbish.","zh":"城市的市政廢物可能包括廚餘、包裝、紙張和家居垃圾。"},{"en":"Moving municipal waste by barge can reduce rubbish-truck traffic on local roads.","zh":"用駁船運送市政廢物可以減少本地道路上的垃圾車交通。"},{"en":"This phrase refers to waste managed by local authorities.","zh":"這個短語指由地方當局管理的廢物。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":13},{"front":"be collected by truck","meaning":"由貨車收集","examples":[{"en":"Municipal waste is collected by truck before being moved by barge.","zh":"市政廢物在由駁船運送前，先由貨車收集。"},{"en":"To be collected by truck means to be picked up and carried first by a road vehicle.","zh":"由貨車收集，是指先由道路車輛取走和運載。"},{"en":"Recycling bags may be collected by truck every Friday morning.","zh":"回收袋可能每星期五早上由貨車收集。"},{"en":"Trucks can gather waste from many streets before it is transferred to another transport method.","zh":"貨車可以從許多街道收集廢物，再轉移到另一種運輸方法。"},{"en":"This phrase describes the first stage of a transport chain.","zh":"這個短語描述運輸鏈的第一階段。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":14},{"front":"be transferred to","meaning":"被轉移到","examples":[{"en":"The waste is transferred to a barge for transportation.","zh":"廢物被轉移到駁船上作運輸。"},{"en":"To be transferred to something means to be moved from one place, vehicle or system to another.","zh":"被轉移到某處，是指從一個地方、車輛或系統移到另一個。"},{"en":"A patient may be transferred to another hospital for specialist care.","zh":"病人可能被轉移到另一間醫院接受專科照顧。"},{"en":"Freight may be transferred from lorries to barges when water routes are available.","zh":"當水路可用，貨物可能從貨車轉移到駁船。"},{"en":"This phrase describes movement between stages.","zh":"這個短語描述階段之間的移動。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":14},{"front":"a barge","meaning":"駁船","examples":[{"en":"A barge can carry waste to a reprocessing plant.","zh":"駁船可以把廢物運送到再加工廠。"},{"en":"A barge is a long, flat-bottomed boat often used for carrying heavy goods on canals and rivers.","zh":"駁船是一種長而平底的船，常用於在運河和河流上運載重貨。"},{"en":"A construction company may use a barge to move sand or stone.","zh":"建築公司可能使用駁船運送沙或石。"},{"en":"Barges can reduce lorry traffic because they carry large loads at once.","zh":"駁船可以減少貨車交通，因為它們一次運載大量貨物。"},{"en":"This word refers to a practical freight boat.","zh":"這個詞指實用貨運船隻。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":14},{"front":"transportation to","meaning":"運送到……","examples":[{"en":"The waste is transferred to a barge for transportation to a reprocessing plant.","zh":"廢物被轉移到駁船上，以運送到再加工廠。"},{"en":"Transportation to a place means the movement of people or goods to that destination.","zh":"運送到某地，是指把人或貨物移動到該目的地。"},{"en":"A school arranges transportation to the museum for a class visit.","zh":"學校安排交通把學生運送到博物館參觀。"},{"en":"Choosing the right transportation to a site affects cost, timing and pollution.","zh":"選擇前往某地的合適運輸會影響成本、時間和污染。"},{"en":"This phrase focuses on the destination of movement.","zh":"這個短語聚焦移動的目的地。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":14},{"front":"a reprocessing plant","meaning":"再加工廠","examples":[{"en":"The barge transports waste to a reprocessing plant.","zh":"駁船把廢物運送到再加工廠。"},{"en":"A reprocessing plant is a facility where waste materials are treated so they can be reused or recycled.","zh":"再加工廠是處理廢料，使其可以再用或回收的設施。"},{"en":"Plastic bottles may be sent to a reprocessing plant and turned into new materials.","zh":"膠樽可能被送到再加工廠，變成新材料。"},{"en":"Reprocessing plants need steady waste supplies and reliable transport links.","zh":"再加工廠需要穩定廢物供應和可靠運輸連接。"},{"en":"This phrase refers to an industrial site for recycling or treatment.","zh":"這個短語指用於回收或處理的工業場地。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":14},{"front":"remove dustcart miles","meaning":"減少垃圾車行駛里數","examples":[{"en":"The scheme could remove 300,000 dustcart miles from local streets.","zh":"該計劃可以從本地街道減少 300,000 英里的垃圾車行駛里數。"},{"en":"To remove dustcart miles means to reduce the distance rubbish trucks travel on roads.","zh":"減少垃圾車行駛里數，是指降低垃圾車在道路上行駛的距離。"},{"en":"A recycling centre near a canal could remove many dustcart miles from a busy neighbourhood.","zh":"運河附近的回收中心可以從繁忙社區減少許多垃圾車行駛里數。"},{"en":"Fewer dustcart miles can mean less noise, pollution and congestion.","zh":"較少垃圾車行駛里數可以代表較少噪音、污染和擠塞。"},{"en":"This phrase measures the road traffic avoided by changing waste transport.","zh":"這個短語衡量改變廢物運輸所避免的道路交通。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":14},{"front":"dustcart","meaning":"垃圾車","examples":[{"en":"A dustcart is used to collect rubbish from streets.","zh":"垃圾車用來從街道收集垃圾。"},{"en":"A dustcart is a rubbish-collection truck used by local waste services.","zh":"垃圾車是本地廢物服務用來收集垃圾的貨車。"},{"en":"Residents may hear a dustcart early in the morning on collection day.","zh":"居民可能在收集日清晨聽到垃圾車聲。"},{"en":"Fewer dustcarts on local streets can reduce noise and congestion.","zh":"本地街道上較少垃圾車可以減少噪音和擠塞。"},{"en":"This word is British English for a garbage truck.","zh":"這個詞是英式英語中的 garbage truck。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":14},{"front":"the borough’s streets","meaning":"該行政區的街道","examples":[{"en":"The scheme could reduce traffic on the borough’s streets.","zh":"該計劃可以減少該行政區街道上的交通。"},{"en":"The borough’s streets are the roads within a local administrative district.","zh":"該行政區的街道，是指一個地方行政區內的道路。"},{"en":"A borough’s streets may become crowded when waste trucks and delivery vans use the same routes.","zh":"當垃圾車和送貨車使用同一路線，行政區街道可能變得擠塞。"},{"en":"Moving waste by barge can reduce pressure on local streets.","zh":"用駁船運送廢物可以減輕本地街道壓力。"},{"en":"This phrase focuses on traffic effects within one local area.","zh":"這個短語聚焦一個本地地區內的交通影響。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":14},{"front":"current arrangements","meaning":"現行安排","examples":[{"en":"Current arrangements could be just the tip of the iceberg.","zh":"現行安排可能只是冰山一角。"},{"en":"Current arrangements are the systems, plans or methods being used now.","zh":"現行安排是現在使用的系統、計劃或方法。"},{"en":"A school’s current arrangements for lunch may include staggered meal times and online ordering.","zh":"學校現行午膳安排可能包括錯峰用餐和網上訂餐。"},{"en":"If current arrangements are only a beginning, larger changes may follow later.","zh":"如果現行安排只是開始，之後可能有更大改變。"},{"en":"This phrase refers to the present setup.","zh":"這個短語指目前的設置。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":14},{"front":"the tip of the iceberg","meaning":"冰山一角","examples":[{"en":"The current scheme may be just the tip of the iceberg.","zh":"目前計劃可能只是冰山一角。"},{"en":"The tip of the iceberg means the small visible part of a much larger situation.","zh":"冰山一角，是指一個更大情況中可見的小部分。"},{"en":"One student complaint may be the tip of the iceberg if many others are afraid to speak.","zh":"如果許多其他學生不敢說，一宗學生投訴可能只是冰山一角。"},{"en":"This phrase warns that more problems or possibilities may exist below the surface.","zh":"這個短語提醒人，表面之下可能有更多問題或可能性。"},{"en":"It often suggests that what we see now is only the beginning.","zh":"它常暗示我們現在看到的只是開始。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":14},{"front":"planning permission","meaning":"規劃許可","examples":[{"en":"Planning permission has been given for a recycling plant.","zh":"一座回收廠已獲規劃許可。"},{"en":"Planning permission is official approval to build or change the use of land or buildings.","zh":"規劃許可是建造或改變土地、建築物用途的官方批准。"},{"en":"A family may need planning permission before adding another floor to a house.","zh":"家庭在為房屋加建一層前可能需要規劃許可。"},{"en":"Without planning permission, a project may be delayed or stopped.","zh":"沒有規劃許可，項目可能被延誤或叫停。"},{"en":"This phrase refers to legal approval for development.","zh":"這個短語指發展項目的法律批准。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":14},{"front":"Powerday recycling plant","meaning":"Powerday 回收廠","examples":[{"en":"The Powerday recycling plant will handle large amounts of waste.","zh":"Powerday 回收廠將處理大量廢物。"},{"en":"The Powerday recycling plant is the specific recycling facility named in the passage.","zh":"Powerday 回收廠是篇章中提到的具體回收設施。"},{"en":"A recycling plant like Powerday can receive waste, sort materials and prepare them for reuse.","zh":"像 Powerday 這樣的回收廠可以接收廢物、分類材料並準備再用。"},{"en":"Its location matters because it connects road, rail and canal networks.","zh":"其位置很重要，因為它連接公路、鐵路和運河網絡。"},{"en":"This phrase identifies a particular project used as evidence in the passage.","zh":"這個短語指出篇章中用作證據的特定項目。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":15},{"front":"Willesden Junction","meaning":"Willesden Junction","examples":[{"en":"The recycling plant will be built at Willesden Junction.","zh":"回收廠將建於 Willesden Junction。"},{"en":"Willesden Junction is named as the location of the recycling plant.","zh":"Willesden Junction 在文中被指為回收廠的位置。"},{"en":"A junction is useful for freight when several transport routes meet there.","zh":"當幾條運輸路線在交匯處相遇，該地點對貨運很有用。"},{"en":"Building a plant at Willesden Junction can support transfers between road, rail and canal.","zh":"在 Willesden Junction 建廠可以支持公路、鐵路和運河之間的轉運。"},{"en":"This phrase gives the specific site of the proposed facility.","zh":"這個短語給出擬建設施的具體地點。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":15},{"front":"at the intersection of","meaning":"在……的交匯處","examples":[{"en":"The site is at the intersection of road, rail and canal networks.","zh":"該地點位於公路、鐵路和運河網絡的交匯處。"},{"en":"At the intersection of means located where different routes, systems or ideas meet.","zh":"在某些事物的交匯處，是指位於不同路線、系統或想法相遇的地方。"},{"en":"A new station may be built at the intersection of two railway lines.","zh":"新車站可能建於兩條鐵路線的交匯處。"},{"en":"A site at a transport intersection can make transfers easier and cheaper.","zh":"位於交通交匯處的地點可以令轉運更容易、更便宜。"},{"en":"This phrase shows why a location is strategically useful.","zh":"這個短語顯示某地點為何具策略用途。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":15},{"front":"road, rail and canal networks","meaning":"公路、鐵路及運河網絡","examples":[{"en":"The site connects road, rail and canal networks.","zh":"該地點連接公路、鐵路及運河網絡。"},{"en":"Road, rail and canal networks are transport systems using roads, trains and waterways.","zh":"公路、鐵路及運河網絡，是使用道路、火車和水道的運輸系統。"},{"en":"A logistics centre works best when road, rail and canal networks meet nearby.","zh":"當公路、鐵路和運河網絡在附近交匯，物流中心最能發揮作用。"},{"en":"Connecting networks allows freight to move by the most suitable method for each stage.","zh":"連接不同網絡讓貨物在每個階段使用最合適方法移動。"},{"en":"This phrase highlights multimodal transport.","zh":"這個短語突出多式聯運。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":15},{"front":"have the capacity to","meaning":"有能力去","examples":[{"en":"The plant will have the capacity to handle large amounts of waste.","zh":"該工廠將有能力處理大量廢物。"},{"en":"To have the capacity to do something means to have enough ability, space or resources to do it.","zh":"有能力做某事，是指有足夠能力、空間或資源去做。"},{"en":"A school hall may have the capacity to hold 500 students.","zh":"學校禮堂可能有能力容納 500 名學生。"},{"en":"If a plant has enough capacity, it can process waste without creating delays.","zh":"如果工廠有足夠能力，它可以處理廢物而不造成延誤。"},{"en":"This phrase focuses on ability and scale.","zh":"這個短語聚焦能力和規模。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":15},{"front":"handle waste","meaning":"處理廢物","examples":[{"en":"The plant will handle a million and a half tons of waste each year.","zh":"該工廠每年將處理一百五十萬噸廢物。"},{"en":"To handle waste means to receive, process, recycle or dispose of rubbish and unwanted materials.","zh":"處理廢物，是指接收、加工、回收或棄置垃圾和不需要材料。"},{"en":"A city needs facilities that can handle waste safely and efficiently.","zh":"城市需要能安全有效處理廢物的設施。"},{"en":"Poor waste handling can create smell, pollution and public health risks.","zh":"廢物處理不善會造成臭味、污染和公共健康風險。"},{"en":"This phrase describes practical management of rubbish.","zh":"這個短語描述垃圾的實際管理。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":15},{"front":"a million and a half tons","meaning":"一百五十萬噸","examples":[{"en":"The plant can handle a million and a half tons of waste every year.","zh":"該工廠每年可以處理一百五十萬噸廢物。"},{"en":"A million and a half tons means 1.5 million tons.","zh":"一百五十萬噸是指 1.5 million tons。"},{"en":"A large recycling plant may process a million and a half tons if it serves a whole city.","zh":"如果大型回收廠服務整個城市，它可能處理一百五十萬噸。"},{"en":"Such a large amount requires strong transport links and careful management.","zh":"如此大量需要強大運輸連接和仔細管理。"},{"en":"This phrase gives a very large quantity.","zh":"這個短語給出非常大的數量。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":15},{"front":"be capped at","meaning":"上限為；被限制在","examples":[{"en":"The amount carried by road will be capped at 500,000 tons.","zh":"由道路運載的數量上限為 500,000 噸。"},{"en":"To be capped at an amount means to be limited to that maximum level.","zh":"被限制在某數量，是指被限定於該最高水平。"},{"en":"A class size may be capped at 30 students for safety and teaching quality.","zh":"班級人數可能上限為 30 人，以保障安全和教學質素。"},{"en":"Capping road transport can force companies to use rail or canals for extra freight.","zh":"限制道路運輸可以迫使公司用鐵路或運河運送額外貨物。"},{"en":"This phrase describes an official upper limit.","zh":"這個短語描述官方上限。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":15},{"front":"grow the business","meaning":"擴展業務","examples":[{"en":"If the company wants to grow the business, it will have to use the canals.","zh":"如果公司想擴展業務，就必須使用運河。"},{"en":"To grow the business means to expand its sales, capacity, customers or operations.","zh":"擴展業務，是指擴大銷售、產能、客戶或營運。"},{"en":"A bakery may grow the business by opening a second shop.","zh":"麵包店可能透過開第二間分店來擴展業務。"},{"en":"If road transport is capped, a company may need another transport route to expand.","zh":"如果道路運輸受限，公司可能需要另一條運輸路線來擴展。"},{"en":"This phrase describes business expansion.","zh":"這個短語描述業務擴張。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":15},{"front":"work with","meaning":"與……合作","examples":[{"en":"The company will have to work with British Waterways.","zh":"該公司將必須與英國水道局合作。"},{"en":"To work with someone means to cooperate with them to achieve a goal.","zh":"與某人合作，是指與他們協力達成目標。"},{"en":"A school may work with parents to improve students’ attendance.","zh":"學校可能與家長合作改善學生出席率。"},{"en":"Large transport projects often require companies to work with public bodies.","zh":"大型運輸項目通常需要公司與公共機構合作。"},{"en":"This phrase describes cooperation, not simply working near someone.","zh":"這個短語描述合作，而不只是與某人在附近工作。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":15},{"front":"get freight back on","meaning":"讓貨運重回……","examples":[{"en":"British Waterways wants to get freight back on the canals.","zh":"英國水道局希望讓貨運重回運河。"},{"en":"To get freight back on something means to make goods transport return to that route or system.","zh":"讓貨運重回某處，是指使貨物運輸回到該路線或系統。"},{"en":"A railway company may try to get freight back on an old line after repairing it.","zh":"鐵路公司修復舊線後，可能嘗試讓貨運重回該路線。"},{"en":"Getting freight back on canals requires customers, loading points and reliable routes.","zh":"讓貨運重回運河需要客戶、裝卸點和可靠路線。"},{"en":"This phrase describes restoring cargo use to an old transport system.","zh":"這個短語描述恢復舊運輸系統的貨運用途。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":15},{"front":"little more than an idea","meaning":"只不過是一個想法","examples":[{"en":"For many years, canal freight was little more than an idea.","zh":"多年來，運河貨運只不過是一個想法。"},{"en":"Little more than an idea means it existed mainly as a plan or hope, not as real action.","zh":"只不過是一個想法，是指它主要只是計劃或希望，而不是實際行動。"},{"en":"A school garden may be little more than an idea until someone finds land and funding.","zh":"學校花園在有人找到土地和資金前，可能只不過是一個想法。"},{"en":"Projects become real only when planning turns into practical work.","zh":"項目只有在規劃變成實際工作時才會成真。"},{"en":"This phrase contrasts imagination with actual implementation.","zh":"這個短語把想像與真正落實作對比。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":16},{"front":"proof of what really can be done","meaning":"證明真正可做到的事","examples":[{"en":"The Powerday project is proof of what really can be done.","zh":"Powerday 項目證明真正可做到的事。"},{"en":"Proof of what really can be done means clear evidence that an idea is practical, not just theoretical.","zh":"證明真正可做到的事，是指清楚證據顯示某想法實際可行，而不只是理論。"},{"en":"A successful trial class can be proof of what really can be done with a new teaching method.","zh":"成功的試驗課可以證明新教學方法真正可做到的事。"},{"en":"Practical proof encourages others to invest because the risk feels lower.","zh":"實際證明會鼓勵其他人投資，因為風險感較低。"},{"en":"This phrase shows that a project has moved from talk to reality.","zh":"這個短語顯示項目已由空談走向現實。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":16},{"front":"details have yet to be decided","meaning":"細節仍未決定","examples":[{"en":"The details of the Olympic transport plan have yet to be decided.","zh":"奧運運輸計劃的細節仍未決定。"},{"en":"Details have yet to be decided means the main idea exists but the specific arrangements are not final.","zh":"細節仍未決定，是指主要想法存在，但具體安排尚未最終確定。"},{"en":"A school trip may be approved, but the exact route and lunch time have yet to be decided.","zh":"學校旅行可能已獲批准，但確切路線和午餐時間仍未決定。"},{"en":"Unsettled details can delay planning because people need clear information before acting.","zh":"未確定細節會延誤規劃，因為人們行動前需要清楚資訊。"},{"en":"This phrase describes an unfinished planning stage.","zh":"這個短語描述未完成的規劃階段。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":16},{"front":"the most appropriate way to","meaning":"最合適的方法去","examples":[{"en":"British Waterways believes water transport is the most appropriate way to move some materials.","zh":"英國水道局相信水路運輸是運送某些材料的最合適方法。"},{"en":"The most appropriate way to do something is the method that best fits the purpose and conditions.","zh":"做某事的最合適方法，是最符合目的和條件的方法。"},{"en":"For a short school notice, email may be the most appropriate way to contact parents.","zh":"對簡短學校通知而言，電郵可能是聯絡家長的最合適方法。"},{"en":"Heavy non-urgent materials may be best moved by water because speed is less important.","zh":"不急需的重型材料可能最適合以水路運送，因為速度較不重要。"},{"en":"This phrase stresses suitability, not just possibility.","zh":"這個短語強調合適程度，而不只是可能性。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":16},{"front":"building materials","meaning":"建築材料","examples":[{"en":"Some building materials may be transported by water.","zh":"一些建築材料可以由水路運輸。"},{"en":"Building materials are substances used to construct buildings, roads and other structures.","zh":"建築材料是用來建造樓宇、道路和其他結構的物質。"},{"en":"Sand, bricks, cement, steel and timber are common building materials.","zh":"沙、磚、水泥、鋼材和木材都是常見建築材料。"},{"en":"Heavy building materials often suit canal transport because they are bulky but not always urgent.","zh":"重型建築材料通常適合運河運輸，因為它們體積大但不一定緊急。"},{"en":"This phrase refers to construction supplies.","zh":"這個短語指建築用品。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":16},{"front":"be destined for","meaning":"將運往；注定用於","examples":[{"en":"Some building materials are destined for London’s Olympic construction project.","zh":"一些建築材料將運往倫敦奧運建設工程。"},{"en":"To be destined for a place or project means to be intended or planned to go there.","zh":"將運往某地或用於某項目，是指被計劃或預定送到那裡。"},{"en":"The new desks are destined for classrooms opening next term.","zh":"新書桌將運往下學期開放的課室。"},{"en":"Freight routes are chosen based on where goods are destined for.","zh":"貨運路線會根據貨物目的地而選擇。"},{"en":"This phrase describes the planned destination or purpose of something.","zh":"這個短語描述某物的預定目的地或用途。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":16},{"front":"giant Olympic construction project","meaning":"大型奧運建設工程","examples":[{"en":"London’s giant Olympic construction project may use water transport.","zh":"倫敦大型奧運建設工程可能使用水路運輸。"},{"en":"A giant Olympic construction project is a very large building programme connected with the Olympic Games.","zh":"大型奧運建設工程，是與奧運會相關的非常大型建築計劃。"},{"en":"Such a project may require huge amounts of concrete, steel and other materials.","zh":"這類工程可能需要大量混凝土、鋼材和其他材料。"},{"en":"Large construction projects can create heavy freight traffic if materials arrive by road.","zh":"如果材料由道路運抵，大型建設工程會造成大量貨運交通。"},{"en":"This phrase stresses the scale of the building work.","zh":"這個短語強調建築工程規模。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":16},{"front":"network of waterways","meaning":"水道網絡","examples":[{"en":"A network of waterways links the Thames and east London.","zh":"一個水道網絡連接泰晤士河和倫敦東部。"},{"en":"A network of waterways is a connected system of canals, rivers and water routes.","zh":"水道網絡是由運河、河流和水路組成的連接系統。"},{"en":"A region with a network of waterways can move boats between several districts.","zh":"有水道網絡的地區可以讓船在幾個區域之間移動。"},{"en":"Connected waterways are more useful because goods can travel from one route to another.","zh":"連接水道更有用，因為貨物可以從一條路線轉到另一條。"},{"en":"This phrase emphasises connection between water routes.","zh":"這個短語強調水路之間的連接。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":16},{"front":"the Thames","meaning":"泰晤士河","examples":[{"en":"The Thames is linked to east London by a network of waterways.","zh":"泰晤士河透過水道網絡與倫敦東部相連。"},{"en":"The Thames is the major river running through London.","zh":"泰晤士河是流經倫敦的主要河流。"},{"en":"The Thames can connect central London with docks, canals and riverside districts.","zh":"泰晤士河可以連接倫敦市中心、碼頭、運河和河畔地區。"},{"en":"Using the Thames for freight can reduce pressure on some roads.","zh":"使用泰晤士河作貨運可以減輕某些道路壓力。"},{"en":"This phrase gives a specific London waterway.","zh":"這個短語提供具體倫敦水道。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":16},{"front":"east London","meaning":"倫敦東部","examples":[{"en":"The waterways link the Thames and east London.","zh":"這些水道連接泰晤士河和倫敦東部。"},{"en":"East London means the eastern part of London.","zh":"倫敦東部是指倫敦的東面部分。"},{"en":"Major construction projects in east London may need large deliveries of materials.","zh":"倫敦東部的大型建設項目可能需要大量材料運送。"},{"en":"If waterways reach east London, they can help move freight into development sites.","zh":"如果水道到達倫敦東部，它們可以幫助把貨物運入發展地點。"},{"en":"This phrase gives the geographical area connected by the canal network.","zh":"這個短語給出運河網絡連接的地理區域。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":16},{"front":"Olympic Delivery Authority","meaning":"奧運交付管理局","examples":[{"en":"The Olympic Delivery Authority is considering transport by water.","zh":"奧運交付管理局正在考慮水路運輸。"},{"en":"The Olympic Delivery Authority is named as the body responsible for planning delivery for the Olympic project.","zh":"奧運交付管理局在文中被指為負責規劃奧運項目交付工作的機構。"},{"en":"Such an authority must consider cost, timing, sustainability and logistics.","zh":"這類機構必須考慮成本、時間、可持續性和物流。"},{"en":"If the authority chooses water transport, building materials may travel by canal or river.","zh":"如果該機構選擇水路運輸，建築材料可能經運河或河流運送。"},{"en":"This phrase identifies the official organisation involved in the Olympic project.","zh":"這個短語指出參與奧運項目的官方組織。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":16},{"front":"be looked at","meaning":"正在被考慮","examples":[{"en":"Transport by water is being looked at for the Olympic project.","zh":"奧運項目正在考慮使用水路運輸。"},{"en":"To be looked at means to be considered, examined or studied as a possible option.","zh":"正在被考慮，是指被作為可能選項來研究或審視。"},{"en":"A school may look at later start times if many students arrive tired.","zh":"如果許多學生疲倦到校，學校可能考慮較遲上課時間。"},{"en":"When an option is being looked at, it has not necessarily been chosen yet.","zh":"當某選項正在被考慮，它不一定已被選定。"},{"en":"This phrase describes investigation before a final decision.","zh":"這個短語描述最終決定前的研究。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":17},{"front":"the final solution","meaning":"最終方案","examples":[{"en":"The final solution could involve some transportation by water.","zh":"最終方案可能涉及部分水路運輸。"},{"en":"The final solution means the plan or arrangement finally chosen after considering options.","zh":"最終方案，是指考慮選項後最後選定的計劃或安排。"},{"en":"A family may compare flats, schools and transport before deciding on the final solution.","zh":"家庭可能比較單位、學校和交通後才決定最終方案。"},{"en":"Final solutions often combine several methods instead of relying on only one.","zh":"最終方案通常結合幾種方法，而不是只依賴一種。"},{"en":"This phrase refers to the end result of planning.","zh":"這個短語指規劃的最後結果。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":17},{"front":"could well involve","meaning":"很可能涉及","examples":[{"en":"The final solution could well involve some transport by water.","zh":"最終方案很可能涉及一些水路運輸。"},{"en":"Could well involve means is quite likely to include something.","zh":"很可能涉及，是指相當可能包括某事。"},{"en":"The school’s new timetable could well involve shorter lunch breaks and more activity time.","zh":"學校新時間表很可能涉及較短午膳時間和更多活動時間。"},{"en":"This phrase expresses likelihood without making a definite promise.","zh":"這個短語表達可能性，但不作出確定承諾。"},{"en":"It is useful when a decision is not final but one option seems probable.","zh":"當決定未最終確定但某選項看似可能時，它很有用。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":17},{"front":"a range of factors","meaning":"一系列因素","examples":[{"en":"The decision will be based on a range of factors.","zh":"該決定將基於一系列因素。"},{"en":"A range of factors means several different issues or considerations.","zh":"一系列因素是指幾個不同議題或考慮因素。"},{"en":"Choosing a school may depend on a range of factors, including distance, fees and teaching quality.","zh":"選擇學校可能取決於一系列因素，包括距離、學費和教學質素。"},{"en":"Complex transport decisions need many factors because cost alone is not enough.","zh":"複雜運輸決定需要許多因素，因為單看成本不足夠。"},{"en":"This phrase shows that a decision is multi-sided.","zh":"這個短語顯示決定有多方面。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":17},{"front":"sustainability","meaning":"可持續性","examples":[{"en":"Sustainability will be one factor in the final transport decision.","zh":"可持續性將是最終運輸決定的其中一個因素。"},{"en":"Sustainability means the ability to meet present needs without damaging future people or the environment.","zh":"可持續性是指滿足當前需要而不損害未來人們或環境的能力。"},{"en":"A sustainable school policy saves energy and reduces waste over time.","zh":"可持續的學校政策會隨時間節省能源並減少廢物。"},{"en":"Transport choices are more sustainable when they use less fuel and create fewer emissions.","zh":"當運輸選擇使用較少燃料並造成較少排放，它們就更可持續。"},{"en":"This word connects current decisions with long-term effects.","zh":"這個詞把當前決定與長期影響連接起來。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":17},{"front":"gentle pace","meaning":"緩慢節奏","examples":[{"en":"The canals’ gentle pace makes them suitable only for certain transport uses.","zh":"運河的緩慢節奏令它們只適合某些運輸用途。"},{"en":"Gentle pace means a slow, calm speed rather than a fast or urgent one.","zh":"緩慢節奏是指慢而平靜的速度，而不是快速或緊急速度。"},{"en":"A gentle pace is pleasant for a weekend walk but unsuitable for an emergency delivery.","zh":"緩慢節奏適合週末散步，但不適合緊急送貨。"},{"en":"Canals move slowly, so they suit heavy goods better than urgent fresh food.","zh":"運河移動較慢，所以比起緊急新鮮食品，更適合重貨。"},{"en":"This phrase explains both the charm and limitation of canals.","zh":"這個短語同時解釋運河的魅力和限制。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":17},{"front":"niche player","meaning":"小眾角色；特定領域參與者","examples":[{"en":"Canals will remain a niche player in modern transport.","zh":"運河在現代運輸中仍會是小眾角色。"},{"en":"A niche player is something that serves a small, specific role rather than the whole market.","zh":"小眾角色是指服務小而特定功能，而不是整個市場的事物。"},{"en":"A small bookshop may be a niche player because it specialises in rare local history books.","zh":"小書店可能是小眾角色，因為它專門賣稀有本地歷史書。"},{"en":"Canals can be useful for certain goods, but they cannot replace all road transport.","zh":"運河對某些貨物有用，但不能取代所有道路運輸。"},{"en":"This phrase describes limited but specialised importance.","zh":"這個短語描述有限但專門的重要性。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":17},{"front":"a busy world","meaning":"繁忙的世界","examples":[{"en":"The canals’ slow speed limits their role in a busy world.","zh":"運河速度慢，限制了它們在繁忙世界中的角色。"},{"en":"A busy world means a society where people and businesses expect speed, efficiency and constant movement.","zh":"繁忙的世界，是指人和企業期望速度、效率和持續流動的社會。"},{"en":"In a busy world, customers often expect next-day delivery.","zh":"在繁忙世界中，顧客常期望翌日送貨。"},{"en":"Slow transport can struggle when schedules are tight and demand is urgent.","zh":"當時間表緊迫、需求急切時，緩慢運輸會吃力。"},{"en":"This phrase contrasts modern speed with slower older systems.","zh":"這個短語把現代速度與較慢舊系統作對比。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":17},{"front":"after 200 years of neglect","meaning":"在二百年的忽視之後","examples":[{"en":"After 200 years of neglect, canals are becoming useful again.","zh":"在二百年的忽視之後，運河正再次變得有用。"},{"en":"After 200 years of neglect means following two centuries of being ignored or poorly maintained.","zh":"在二百年的忽視之後，是指經歷兩個世紀被忽略或維修不善之後。"},{"en":"After years of neglect, an old theatre may reopen only after major repairs.","zh":"經多年忽視後，舊劇院可能只有在大修後才重新開放。"},{"en":"Long neglect makes recovery impressive because the system has survived serious decline.","zh":"長期忽視令恢復更令人印象深刻，因為系統經歷了嚴重衰落。"},{"en":"This phrase highlights the long period before renewal.","zh":"這個短語突出更新前的漫長時期。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":17},{"front":"the tide is starting to turn","meaning":"形勢開始逆轉","examples":[{"en":"The tide is starting to turn for Britain’s canals.","zh":"英國運河的形勢開始逆轉。"},{"en":"The tide is starting to turn means a bad or declining situation is beginning to improve.","zh":"形勢開始逆轉，是指不好或衰落的情況開始改善。"},{"en":"After months of falling sales, the tide started to turn when the shop launched online orders.","zh":"銷售下跌數月後，店舖推出網上訂單，形勢開始逆轉。"},{"en":"Small successful projects can show that public opinion and practical use are changing.","zh":"小型成功項目可以顯示公眾看法和實際用途正在改變。"},{"en":"This phrase gives a hopeful image of reversal.","zh":"這個短語給出充滿希望的逆轉畫面。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":17},{"front":"the text has eight paragraphs","meaning":"文章有八段","examples":[{"en":"The text has eight paragraphs about Britain’s canals.","zh":"這篇關於英國運河的文章有八段。"},{"en":"The text has eight paragraphs means the passage is divided into eight separate sections.","zh":"文章有八段，是指篇章被分成八個獨立部分。"},{"en":"In a reading test, knowing paragraph numbers helps students match headings accurately.","zh":"在閱讀測驗中，知道段落數目有助學生準確配對標題。"},{"en":"If a text has many paragraphs, students should identify the main idea of each one.","zh":"如果文章有多段，學生應找出每段主旨。"},{"en":"This phrase describes the structure of the passage.","zh":"這個短語描述篇章結構。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":17},{"front":"which paragraph does each heading best fit","meaning":"每個標題最適合哪一段","examples":[{"en":"The task asks which paragraph each heading best fits.","zh":"題目要求判斷每個標題最適合哪一段。"},{"en":"Which paragraph each heading best fits means students must match titles to the paragraphs they summarise best.","zh":"每個標題最適合哪一段，是指學生必須把標題配對到最能概括它的段落。"},{"en":"A heading about pollution should fit the paragraph mainly discussing emissions and congestion.","zh":"關於污染的標題應配對到主要討論排放和擠塞的段落。"},{"en":"This task tests understanding of main ideas rather than single words.","zh":"這項任務測試對主旨的理解，而不是單字。"},{"en":"This phrase describes a heading-matching reading question.","zh":"這個短語描述標題配對閱讀題。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":18},{"front":"Olympic transport","meaning":"奧運運輸","examples":[{"en":"One heading refers to Olympic transport.","zh":"其中一個標題提到奧運運輸。"},{"en":"Olympic transport means the movement of people, goods or materials connected with the Olympic Games.","zh":"奧運運輸是指與奧運會有關的人員、貨物或材料移動。"},{"en":"An Olympic construction site may need transport for steel, concrete and equipment.","zh":"奧運建築工地可能需要運送鋼材、混凝土和設備。"},{"en":"Good Olympic transport planning can reduce road congestion during major projects.","zh":"良好奧運運輸規劃可以在大型項目期間減少道路擠塞。"},{"en":"This phrase connects sports events with logistics and infrastructure.","zh":"這個短語把體育盛事與物流和基礎設施連接起來。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":18},{"front":"the decline of British canals","meaning":"英國運河的衰落","examples":[{"en":"One heading asks about the decline of British canals.","zh":"其中一個標題問及英國運河的衰落。"},{"en":"The decline of British canals means the period when canals became less used, less maintained and less important.","zh":"英國運河的衰落，是指運河變得較少使用、較少維修和較不重要的時期。"},{"en":"The decline of a town market may happen when shoppers move to online stores.","zh":"當顧客轉向網店，城鎮市場可能出現衰落。"},{"en":"British canals declined when industry shifted toward railways and roads.","zh":"當工業轉向鐵路和道路，英國運河便衰落。"},{"en":"This phrase focuses on historical weakening.","zh":"這個短語聚焦歷史上的變弱。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":18},{"front":"modern leisure uses","meaning":"現代休閒用途","examples":[{"en":"The passage describes modern leisure uses of canals.","zh":"篇章描述運河的現代休閒用途。"},{"en":"Modern leisure uses are present-day ways people enjoy a place for relaxation and recreation.","zh":"現代休閒用途，是指現今人們為放鬆和消閒而享用某地方的方式。"},{"en":"Canals may have modern leisure uses such as boating, cycling, walking and waterside cafés.","zh":"運河可能有現代休閒用途，例如遊船、踩單車、散步和水邊咖啡店。"},{"en":"Leisure uses can bring people back to neglected spaces and support local business.","zh":"休閒用途可以把人帶回被忽視的空間，並支持本地商業。"},{"en":"This phrase contrasts today’s recreation with older industrial transport use.","zh":"這個短語把今天的消閒與舊有工業運輸用途作對比。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":18},{"front":"energy efficiency","meaning":"能源效益","examples":[{"en":"Water transport can offer energy efficiency.","zh":"水路運輸可以提供能源效益。"},{"en":"Energy efficiency means using less energy to do the same task.","zh":"能源效益是指用較少能源完成同一任務。"},{"en":"An energy-efficient fridge keeps food cold while using less electricity.","zh":"節能雪櫃用較少電力保持食物冰冷。"},{"en":"Barges can offer energy efficiency because they carry heavy loads with less fuel than lorries.","zh":"駁船可以提供能源效益，因為它們用比貨車更少燃料運載重貨。"},{"en":"This phrase is important when comparing environmental and economic benefits.","zh":"這個短語在比較環境和經濟好處時很重要。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":18},{"front":"according to the text","meaning":"根據文章","examples":[{"en":"Students should choose statements according to the text.","zh":"學生應根據文章選擇陳述。"},{"en":"According to the text means based only on what the passage says.","zh":"根據文章，是指只基於篇章所說的內容。"},{"en":"In reading exams, students should answer according to the text rather than personal knowledge.","zh":"在閱讀考試中，學生應根據文章回答，而不是根據個人知識。"},{"en":"If an answer sounds true but is not supported by the passage, it should not be chosen.","zh":"如果答案聽起來正確但文章沒有支持，就不應選擇。"},{"en":"This phrase reminds students to rely on textual evidence.","zh":"這個短語提醒學生依靠文本證據。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":18},{"front":"five of the following statements","meaning":"以下陳述中的五項","examples":[{"en":"The task asks students to identify five true statements.","zh":"題目要求學生找出以下陳述中的五項真確陳述。"},{"en":"Five of the following statements means five items from the list that match the text.","zh":"以下陳述中的五項，是指列表中五個符合文本的項目。"},{"en":"In a reading task, students may need to choose five true statements from eight options.","zh":"在閱讀題中，學生可能需要從八個選項中選出五項正確陳述。"},{"en":"This instruction requires careful selection because not every statement is correct.","zh":"這項指示需要仔細選擇，因為不是每個陳述都正確。"},{"en":"The phrase tells students the exact number of answers needed.","zh":"這個短語告訴學生所需答案的確切數量。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":18},{"front":"corresponding letters","meaning":"相應字母","examples":[{"en":"Students write the corresponding letters in the answer boxes.","zh":"學生在答案格中寫上相應字母。"},{"en":"Corresponding letters are the letters that match the correct answer choices.","zh":"相應字母是與正確答案選項相配的字母。"},{"en":"If option C is correct, C is the corresponding letter students should write.","zh":"如果 C 選項正確，C 就是學生應寫的相應字母。"},{"en":"In multiple-answer tasks, missing one corresponding letter can lose a mark.","zh":"在多答案題中，漏寫一個相應字母可能失分。"},{"en":"This phrase describes how answers are recorded.","zh":"這個短語描述答案如何記錄。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":18},{"front":"answer boxes","meaning":"答案格","examples":[{"en":"The corresponding letters should be written in the answer boxes.","zh":"相應字母應寫在答案格中。"},{"en":"Answer boxes are spaces on a test paper where candidates write their answers.","zh":"答案格是試卷上供考生寫答案的空格。"},{"en":"Students should write clearly in answer boxes so markers can read their choices.","zh":"學生應在答案格中清楚書寫，使評卷員能讀出選擇。"},{"en":"Writing outside the answer boxes may cause confusion or lost marks.","zh":"寫在答案格以外可能造成混亂或失分。"},{"en":"This phrase refers to the official place for recording exam answers.","zh":"這個短語指記錄考試答案的正式位置。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":18},{"front":"be important in","meaning":"在……中很重要","examples":[{"en":"Canals were important in the industrial revolution.","zh":"運河在工業革命中很重要。"},{"en":"To be important in something means to play a significant role in it.","zh":"在某事中很重要，是指在其中發揮重要作用。"},{"en":"Sleep is important in memory because the brain organises information during rest.","zh":"睡眠在記憶中很重要，因為大腦在休息時整理資訊。"},{"en":"Canals were important in industry because they moved heavy goods cheaply.","zh":"運河在工業中很重要，因為它們便宜地運送重貨。"},{"en":"This phrase links a factor with a wider process or event.","zh":"這個短語把一個因素與更廣泛過程或事件連接起來。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":18},{"front":"be expected to grow","meaning":"預計會增長","examples":[{"en":"Freight traffic is expected to grow over the next ten years.","zh":"貨運交通量預計會在未來十年內增長。"},{"en":"Be expected to grow means people predict that something will increase.","zh":"預計會增長，是指人們預測某事會增加。"},{"en":"The number of online learners is expected to grow as courses become cheaper.","zh":"隨着課程變得更便宜，網上學習者人數預計會增長。"},{"en":"If demand is expected to grow, planners must prepare capacity in advance.","zh":"如果需求預計會增長，規劃者必須提前準備容量。"},{"en":"This phrase presents a predicted upward trend.","zh":"這個短語呈現預測中的上升趨勢。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":18},{"front":"over the next ten years","meaning":"在未來十年內","examples":[{"en":"Freight traffic may grow over the next ten years.","zh":"貨運交通量可能在未來十年內增長。"},{"en":"Over the next ten years means during the coming decade.","zh":"在未來十年內，是指在接下來十年期間。"},{"en":"Over the next ten years, a city may build new railway lines and cycle paths.","zh":"在未來十年內，城市可能建設新鐵路線和單車徑。"},{"en":"Ten-year forecasts help governments plan investment before demand becomes too high.","zh":"十年預測幫助政府在需求過高前規劃投資。"},{"en":"This phrase gives a future planning period.","zh":"這個短語給出未來規劃時段。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":19},{"front":"let something decline","meaning":"任由……衰落","examples":[{"en":"Britain allowed many of its canals to decline.","zh":"英國任由許多運河衰落。"},{"en":"To let something decline means to allow it to become weaker or worse through neglect or lack of action.","zh":"任由某事衰落，是指因忽視或不行動而讓它變弱或變差。"},{"en":"A school may let its library decline if it never buys new books or repairs shelves.","zh":"如果學校從不買新書或修理書架，就是任由圖書館衰落。"},{"en":"Letting infrastructure decline often makes later restoration more expensive.","zh":"任由基礎設施衰落，通常會令後來復修更昂貴。"},{"en":"This phrase suggests responsibility through inaction.","zh":"這個短語暗示因不行動而有責任。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":19},{"front":"become a focus for","meaning":"成為……的焦點","examples":[{"en":"Canals have become a focus for city-centre renewal.","zh":"運河已成為市中心更新的焦點。"},{"en":"To become a focus for something means to become a main point of attention or activity.","zh":"成為某事的焦點，是指成為主要關注點或活動中心。"},{"en":"A new library can become a focus for community learning.","zh":"新圖書館可以成為社區學習的焦點。"},{"en":"When canals become a focus for renewal, investment gathers around them.","zh":"當運河成為更新焦點，投資會圍繞它們聚集。"},{"en":"This phrase describes how one place becomes central to a wider effort.","zh":"這個短語描述一個地方如何成為更廣泛努力的中心。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":19},{"front":"city-centre renewal","meaning":"市中心更新","examples":[{"en":"Canals can support city-centre renewal.","zh":"運河可以支持市中心更新。"},{"en":"City-centre renewal means improving old or neglected areas in the middle of a city.","zh":"市中心更新是改善城市中心舊有或被忽視地區。"},{"en":"City-centre renewal may include new housing, public spaces, cafés and transport links.","zh":"市中心更新可能包括新住宅、公共空間、咖啡店和交通連接。"},{"en":"Restored canals can attract people back to central districts.","zh":"復修運河可以吸引人們回到中心地區。"},{"en":"This phrase refers to urban improvement in central areas.","zh":"這個短語指市中心地區的城市改善。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":19},{"front":"less polluting than","meaning":"比……污染較少","examples":[{"en":"Barges are less polluting than lorries.","zh":"駁船比貨車污染較少。"},{"en":"Less polluting than means causing less environmental harm or fewer emissions than another option.","zh":"比某物污染較少，是指比另一選項造成較少環境傷害或較少排放。"},{"en":"Trains are often less polluting than private cars when many passengers travel together.","zh":"當許多乘客一起出行，火車通常比私家車污染較少。"},{"en":"If barges use less fuel per load, they can be less polluting than road freight.","zh":"如果駁船每批貨使用較少燃料，它們可以比道路貨運污染較少。"},{"en":"This phrase is used to compare environmental impact.","zh":"這個短語用於比較環境影響。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":19},{"front":"be transported on canals","meaning":"在運河上運輸","examples":[{"en":"Some waste can be transported on canals.","zh":"有些廢物可以在運河上運輸。"},{"en":"To be transported on canals means to be carried by boat or barge along canal routes.","zh":"在運河上運輸，是指由船或駁船沿運河路線運載。"},{"en":"Building sand may be transported on canals if the construction site is near the water.","zh":"如果建築工地靠近水道，建築沙可能在運河上運輸。"},{"en":"Goods suited to slower delivery can use canals instead of crowded roads.","zh":"適合較慢送達的貨物可以使用運河，而不是擠塞道路。"},{"en":"This phrase describes waterway-based movement of goods.","zh":"這個短語描述以水道為基礎的貨物移動。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":19},{"front":"amount of waste","meaning":"廢物量","examples":[{"en":"The amount of waste carried by road will be limited.","zh":"由道路運送的廢物量將會被限制。"},{"en":"Amount of waste means the quantity of rubbish or unwanted material.","zh":"廢物量是指垃圾或不需要材料的數量。"},{"en":"A school can reduce the amount of waste by using reusable lunch containers.","zh":"學校可以透過使用可重用飯盒減少廢物量。"},{"en":"If the amount of waste moved by road is limited, other transport methods must be used.","zh":"如果道路運送的廢物量受限，就必須使用其他運輸方法。"},{"en":"This phrase focuses on quantity.","zh":"這個短語聚焦數量。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":19},{"front":"major form of transport","meaning":"主要運輸方式","examples":[{"en":"Canals are unlikely to become a major form of transport worldwide.","zh":"運河不太可能成為全球主要運輸方式。"},{"en":"A major form of transport is one of the main ways people or goods move.","zh":"主要運輸方式，是人或貨物流動的主要方法之一。"},{"en":"In many cities, buses and trains are major forms of transport.","zh":"在許多城市，巴士和火車是主要運輸方式。"},{"en":"Because canals are slow and limited by route, they may remain specialised rather than major.","zh":"因為運河速度慢且受路線限制，它們可能保持專門用途而非主要方式。"},{"en":"This phrase describes importance within a transport system.","zh":"這個短語描述在運輸系統中的重要性。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":19},{"front":"choose the correct answer","meaning":"選出正確答案","examples":[{"en":"Students must choose the correct answer from the options.","zh":"學生必須從選項中選出正確答案。"},{"en":"To choose the correct answer means to select the option that best matches the passage or question.","zh":"選出正確答案，是指選擇最符合篇章或題目的選項。"},{"en":"In a multiple-choice task, students should read all options before choosing the correct answer.","zh":"在選擇題中，學生應先閱讀所有選項，再選出正確答案。"},{"en":"The correct answer may use different words from the passage but keep the same meaning.","zh":"正確答案可能使用不同於篇章的字詞，但意思相同。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":19},{"front":"require relatively little investment","meaning":"需要相對少量投資","examples":[{"en":"Canals will require relatively little investment.","zh":"運河將需要相對少量投資。"},{"en":"To require relatively little investment means to need only a small amount of money compared with other options.","zh":"需要相對少量投資，是指與其他選項相比只需少量金錢。"},{"en":"Repairing an existing classroom may require relatively little investment compared with building a new school.","zh":"與建新學校相比，維修現有課室可能需要相對少量投資。"},{"en":"If infrastructure already exists, small upgrades may make it useful again.","zh":"如果基礎設施已存在，小型升級可能令它重新有用。"},{"en":"This phrase compares cost against larger alternatives.","zh":"這個短語把成本與更大型替代方案比較。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":19},{"front":"relatively little","meaning":"相對少量的","examples":[{"en":"The canal network needs relatively little investment.","zh":"運河網絡需要相對少量的投資。"},{"en":"Relatively little means a small amount compared with something else.","zh":"相對少量的，是指與其他事物相比數量較少。"},{"en":"A student may need relatively little time to revise a topic they already understand.","zh":"學生溫習已理解的課題可能需要相對少量時間。"},{"en":"Something can still require money, but relatively little when compared with a bigger project.","zh":"某事仍需要金錢，但與大型項目相比可能是相對少量。"},{"en":"This phrase always suggests comparison.","zh":"這個短語總是暗示比較。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":19},{"front":"considerable investment","meaning":"大量投資","examples":[{"en":"The option suggests canals may need considerable investment.","zh":"該選項暗示運河可能需要大量投資。"},{"en":"Considerable investment means a large amount of money, effort or resources.","zh":"大量投資是指很多金錢、努力或資源。"},{"en":"Building a new hospital requires considerable investment from the government.","zh":"建造新醫院需要政府大量投資。"},{"en":"If a canal is badly damaged, considerable investment may be needed before freight can return.","zh":"如果運河嚴重受損，貨運回歸前可能需要大量投資。"},{"en":"This phrase describes a serious financial commitment.","zh":"這個短語描述重大的財務承擔。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":20},{"front":"equal to","meaning":"相等於","examples":[{"en":"One option mentions investment equal to part of a transport budget.","zh":"一個選項提到相等於部分運輸預算的投資。"},{"en":"Equal to means the same in number, value, amount or level.","zh":"相等於，是指在數字、價值、數量或水平上相同。"},{"en":"Two half-hour lessons are equal to one full hour of study.","zh":"兩節半小時課相等於一小時學習。"},{"en":"Saying one cost is equal to part of a budget helps readers understand its size.","zh":"說一項成本相等於預算的一部分，幫助讀者理解其大小。"},{"en":"This phrase is used for exact or approximate equivalence.","zh":"這個短語用於精確或大約等同。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":20},{"front":"transport budget","meaning":"運輸預算","examples":[{"en":"The option refers to Europe’s transport budget.","zh":"該選項指歐洲的運輸預算。"},{"en":"A transport budget is money planned for roads, railways, buses, waterways and related systems.","zh":"運輸預算是計劃用於道路、鐵路、巴士、水道和相關系統的金錢。"},{"en":"A city may use its transport budget to repair bridges and buy electric buses.","zh":"城市可能使用運輸預算維修橋樑和購買電動巴士。"},{"en":"Large projects compete for transport-budget money, so priorities matter.","zh":"大型項目爭奪運輸預算資金，所以優先次序很重要。"},{"en":"This phrase refers to planned spending on transport.","zh":"這個短語指用於交通的計劃開支。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":20},{"front":"the European canal network","meaning":"歐洲運河網絡","examples":[{"en":"The question asks about the European canal network.","zh":"題目問及歐洲運河網絡。"},{"en":"The European canal network means the connected canals and waterways used across parts of Europe.","zh":"歐洲運河網絡是指歐洲部分地區使用的互相連接運河和水道。"},{"en":"A strong canal network can link factories, ports, cities and rivers.","zh":"強大的運河網絡可以連接工廠、港口、城市和河流。"},{"en":"A connected European network makes freight by water more practical than isolated canals.","zh":"連接起來的歐洲網絡令水路貨運比孤立運河更實際。"},{"en":"This phrase refers to a regional transport system.","zh":"這個短語指區域運輸系統。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":20},{"front":"transport most of","meaning":"運送大部分的……","examples":[{"en":"The option claims that canals transported most of Europe’s goods.","zh":"該選項聲稱運河運送了歐洲大部分貨物。"},{"en":"To transport most of something means to carry the majority of it from place to place.","zh":"運送大部分某物，是指把其中大多數從一地運到另一地。"},{"en":"A school bus system may transport most of the students if few families drive.","zh":"如果很少家庭駕車，校巴系統可能運送大部分學生。"},{"en":"Saying canals transported most goods would mean they dominated freight movement.","zh":"說運河運送大部分貨物，意思是它們主導貨物流動。"},{"en":"This phrase describes carrying the largest share.","zh":"這個短語描述運載最大比例。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":20},{"front":"be built mostly","meaning":"主要建於","examples":[{"en":"The option discusses when the network was built mostly.","zh":"該選項討論該網絡主要建於何時。"},{"en":"To be built mostly means to be constructed mainly during a particular period or in a particular way.","zh":"主要建於，是指主要在某個時期或以某種方式建造。"},{"en":"A housing estate may be built mostly in the 1970s.","zh":"一個屋苑可能主要建於 1970 年代。"},{"en":"Knowing when a network was mostly built helps explain its design and limitations.","zh":"知道一個網絡主要建於何時，有助解釋其設計和限制。"},{"en":"This phrase focuses on the main period or method of construction.","zh":"這個短語聚焦主要建造時期或方法。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":20},{"front":"be expanded in some countries","meaning":"在部分國家被擴建","examples":[{"en":"Canals have been expanded in some countries.","zh":"運河已在部分國家被擴建。"},{"en":"To be expanded in some countries means to be enlarged or developed in certain nations, but not everywhere.","zh":"在部分國家被擴建，是指在某些國家被擴大或發展，但不是所有地方。"},{"en":"High-speed rail has been expanded in some countries while others still rely on older trains.","zh":"高速鐵路已在部分國家擴建，而其他國家仍依靠較舊列車。"},{"en":"Different investment choices can make transport systems develop unevenly.","zh":"不同投資選擇可以令運輸系統發展不均。"},{"en":"This phrase shows variation between countries.","zh":"這個短語顯示國家之間的差異。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":20},{"front":"over the last hundred years","meaning":"在過去一百年","examples":[{"en":"Some European canals were enlarged over the last hundred years.","zh":"一些歐洲運河在過去一百年被擴建。"},{"en":"Over the last hundred years means during the past century.","zh":"在過去一百年，是指在最近一個世紀期間。"},{"en":"Over the last hundred years, cities have changed through cars, electricity and new housing.","zh":"在過去一百年，城市因汽車、電力和新住宅而改變。"},{"en":"A century-long period helps explain major infrastructure changes.","zh":"一個世紀長的時期有助解釋重大基礎設施變化。"},{"en":"This phrase gives a long historical time frame.","zh":"這個短語提供長期歷史時間範圍。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":20},{"front":"suitable products for transportation","meaning":"適合運輸的產品","examples":[{"en":"The question asks about suitable products for transportation by canal.","zh":"題目問哪些產品適合以運河運輸。"},{"en":"Suitable products for transportation are goods that fit a transport method’s speed, cost and handling conditions.","zh":"適合運輸的產品，是符合某運輸方法速度、成本和處理條件的貨物。"},{"en":"Heavy sand may be suitable for canal transport, while fresh strawberries may not be.","zh":"重型沙石可能適合運河運輸，但新鮮士多啤梨可能不適合。"},{"en":"Choosing suitable products prevents waste, delays and damage.","zh":"選擇合適產品可以防止浪費、延誤和損壞。"},{"en":"This phrase links product type with transport suitability.","zh":"這個短語把產品種類與運輸適合度連接起來。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":20},{"front":"transportation by canal","meaning":"以運河運輸","examples":[{"en":"Some products are suitable for transportation by canal.","zh":"有些產品適合以運河運輸。"},{"en":"Transportation by canal means moving goods or materials along canals by boat or barge.","zh":"以運河運輸，是指用船或駁船沿運河運送貨物或材料。"},{"en":"Waste paper may be suitable for transportation by canal because it is not highly time-sensitive.","zh":"廢紙可能適合以運河運輸，因為它不是高度受時間限制。"},{"en":"Canal transportation works best when the route connects collection points and processing sites.","zh":"當路線連接收集點和處理地點，運河運輸最有效。"},{"en":"This phrase describes a specific water-transport method.","zh":"這個短語描述一種特定水路運輸方法。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":20},{"front":"fresh fruit and vegetables","meaning":"新鮮水果和蔬菜","examples":[{"en":"Fresh fruit and vegetables may not suit slow canal transport.","zh":"新鮮水果和蔬菜可能不適合緩慢的運河運輸。"},{"en":"Fresh fruit and vegetables are perishable foods that can spoil if delivery takes too long.","zh":"新鮮水果和蔬菜是易腐食物，如果送貨太久可能變壞。"},{"en":"A supermarket needs fresh fruit and vegetables to arrive quickly and in good condition.","zh":"超市需要新鮮水果和蔬菜快速且狀況良好地到達。"},{"en":"Slow transport can damage freshness, so these goods usually need faster routes.","zh":"緩慢運輸會損害新鮮度，所以這些貨物通常需要更快路線。"},{"en":"This phrase gives examples of products with limited shelf-life.","zh":"這個短語提供有限保鮮期產品的例子。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":20},{"front":"how much waste","meaning":"多少廢物","examples":[{"en":"The question asks how much waste the plant can treat in one year.","zh":"題目問該工廠一年內能處理多少廢物。"},{"en":"How much waste means the quantity of rubbish or unwanted material.","zh":"多少廢物，是指垃圾或不需要材料的數量。"},{"en":"A recycling centre must know how much waste it can handle each day.","zh":"回收中心必須知道自己每天能處理多少廢物。"},{"en":"If the amount is too large, transport and processing systems may become overloaded.","zh":"如果數量太大，運輸和處理系統可能超負荷。"},{"en":"This phrase asks for a measurable amount.","zh":"這個短語詢問可量度的數量。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":21},{"front":"treat waste","meaning":"處理廢物","examples":[{"en":"The recycling plant can treat large amounts of waste.","zh":"回收廠可以處理大量廢物。"},{"en":"To treat waste means to process it so it can be recycled, reused, made safer or disposed of properly.","zh":"處理廢物，是指加工廢物，使其可以回收、再用、變得較安全或妥善棄置。"},{"en":"A wastewater plant treats dirty water before it returns to rivers.","zh":"污水處理廠在污水回到河流前處理污水。"},{"en":"Treating waste properly reduces pollution and protects public health.","zh":"妥善處理廢物能減少污染並保護公共健康。"},{"en":"This phrase refers to processing waste, not simply collecting it.","zh":"這個短語指加工處理廢物，而不只是收集。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":21},{"front":"in one year","meaning":"一年內","examples":[{"en":"The plant can handle a million and a half tons of waste in one year.","zh":"該工廠一年內可以處理一百五十萬噸廢物。"},{"en":"In one year means within a period of twelve months.","zh":"一年內，是指在十二個月的期間之內。"},{"en":"A student can learn many useful phrases in one year with regular practice.","zh":"學生透過定期練習，可以在一年內學會許多有用短語。"},{"en":"Annual figures help people compare capacity, cost or progress clearly.","zh":"年度數字幫助人們清楚比較容量、成本或進展。"},{"en":"This phrase gives a fixed time period for measuring quantity.","zh":"這個短語給出衡量數量的固定時間期間。"}],"source":"92 - Britain’s canals – the solution to overcrowded roads?.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 93":[{"front":"seek quantity and quality","meaning":"追求數量與質素","examples":[{"en":"British universities are seeking both quantity and quality in higher education.","zh":"英國大學正在高等教育中追求數量與質素。"},{"en":"To seek quantity and quality means to try to increase numbers while also keeping standards high.","zh":"seek quantity and quality 指嘗試增加數量，同時保持高標準。"},{"en":"A school may seek quantity and quality by admitting more students but still giving careful feedback.","zh":"學校可以透過取錄更多學生但仍提供仔細回饋，來追求數量與質素。"},{"en":"If an organisation seeks quantity without quality, its results may look impressive but become weaker.","zh":"如果機構只追求數量而沒有質素，成果可能看似壯觀但變得薄弱。"},{"en":"This phrase is useful when expansion and standards must be balanced.","zh":"當擴張和標準必須平衡時，這個短語很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":1},{"front":"pity someone","meaning":"同情某人；可憐某人","examples":[{"en":"The article asks readers to pity the poor British professor.","zh":"文章要求讀者同情可憐的英國教授。"},{"en":"To pity someone means to feel sorry for them because they are in a difficult or unfortunate situation.","zh":"pity someone 指因某人處於困難或不幸情況而感到同情。"},{"en":"A teacher may pity a student who worked hard but missed the exam because of illness.","zh":"老師可能同情一名努力溫習卻因病錯過考試的學生。"},{"en":"Pity can make people sympathetic, but it can also sound slightly patronising if used carelessly.","zh":"同情可以令人有憐憫心，但若使用不慎，也可能聽起來有點居高臨下。"},{"en":"This phrase focuses on feeling sorry for another person’s trouble.","zh":"這個短語聚焦對他人困境感到難過。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":1},{"front":"once upon a time","meaning":"從前","examples":[{"en":"Once upon a time, British university students were drawn from a small elite.","zh":"從前，英國大學生來自一小群精英。"},{"en":"Once upon a time means in the past, often with a slightly story-like or nostalgic tone.","zh":"once upon a time 指在過去，語氣常帶有故事感或懷舊意味。"},{"en":"Once upon a time, many children walked to school without carrying a mobile phone.","zh":"從前，許多孩子上學時不用帶手機。"},{"en":"Writers use this phrase when they want to contrast the past with the present.","zh":"作者想把過去與現在作對比時，會使用這個短語。"},{"en":"It can sound gentle, reflective, or ironic depending on the context.","zh":"視乎語境，它可以聽起來溫和、反思或帶有諷刺意味。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":1},{"front":"the halcyon 1960s","meaning":"昔日美好的1960年代","examples":[{"en":"Professors remember the halcyon 1960s as a very different period.","zh":"教授把昔日美好的1960年代記成一個非常不同的時期。"},{"en":"The halcyon 1960s means the 1960s remembered as a peaceful, successful, or idealised time.","zh":"the halcyon 1960s 指被回憶為平靜、成功或理想化的1960年代。"},{"en":"An older teacher may describe the halcyon days of small classes and quiet libraries.","zh":"年長老師可能描述小班教學和安靜圖書館的昔日美好時光。"},{"en":"People often use halcyon when they look back fondly, even if the past was not perfect.","zh":"人們深情回望過去時常用 halcyon，即使過去並非完美。"},{"en":"This phrase suggests nostalgia for a supposedly better earlier period.","zh":"這個短語暗示對一個被認為較好的早期時代的懷舊。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":1},{"front":"a privileged few","meaning":"少數享有特權的人","examples":[{"en":"University students were once a privileged few.","zh":"大學生曾經是少數享有特權的人。"},{"en":"A privileged few are a small number of people who enjoy special advantages not available to most others.","zh":"privileged few 指少數享有大多數人沒有的特殊優勢的人。"},{"en":"In the past, only a privileged few could afford private tutors or overseas study.","zh":"過去，只有少數享有特權的人能負擔私人補習或海外升學。"},{"en":"When opportunities belong to a privileged few, society may become less equal.","zh":"當機會只屬於少數享有特權的人，社會可能變得較不平等。"},{"en":"This phrase often criticises unfair access to education, wealth, or power.","zh":"這個短語常用來批評教育、財富或權力上的不公平取得。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":1},{"front":"an academic elite","meaning":"學術精英","examples":[{"en":"Students once formed an academic elite drawn from the top four per cent of the population.","zh":"學生曾經構成來自人口最頂尖百分之四的學術精英。"},{"en":"An academic elite is a small group of people considered highly successful or selective in education.","zh":"academic elite 指在教育上被視為高度成功或經嚴格篩選的一小群人。"},{"en":"A scholarship programme may select an academic elite from thousands of applicants.","zh":"獎學金計劃可能從數千名申請者中選出學術精英。"},{"en":"If universities serve only an academic elite, many capable students may be excluded.","zh":"如果大學只服務學術精英，許多有能力的學生可能被排除在外。"},{"en":"This phrase links education with selectiveness and high status.","zh":"這個短語把教育與篩選性和高地位連接起來。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":1},{"front":"drawn from","meaning":"來自；選自","examples":[{"en":"The students were drawn from the top four per cent of the population.","zh":"這些學生來自人口最頂尖的百分之四。"},{"en":"Drawn from means selected or taken from a particular group or source.","zh":"drawn from 指從某個群體或來源中選出或取得。"},{"en":"A school team may be drawn from the strongest players in several classes.","zh":"學校隊伍可能從幾個班中最強的球員選出。"},{"en":"If candidates are drawn from only wealthy families, the group may not represent society fairly.","zh":"如果候選人只來自富裕家庭，該群體可能不能公平代表社會。"},{"en":"This phrase is useful when explaining where people or examples come from.","zh":"解釋人物或例子來自哪裡時，這個短語很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":1},{"front":"the top four per cent","meaning":"最頂尖的百分之四","examples":[{"en":"University students were once drawn from the top four per cent of the population.","zh":"大學生曾經來自人口中最頂尖的百分之四。"},{"en":"The top four per cent means the highest-ranking four out of every hundred people in a group.","zh":"top four per cent 指一個群體中每一百人裏排名最高的四人。"},{"en":"A school may give prizes to students in the top four per cent of exam results.","zh":"學校可能向考試成績最頂尖百分之四的學生頒獎。"},{"en":"Selecting only the top four per cent creates a very narrow and competitive system.","zh":"只選最頂尖百分之四會形成非常狹窄而競爭激烈的制度。"},{"en":"This phrase is used to show extreme selectiveness.","zh":"這個短語用來顯示極高的篩選性。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":1},{"front":"literate and numerate","meaning":"具備讀寫和數學能力","examples":[{"en":"New university arrivals were expected to be literate and numerate.","zh":"新入學大學生被期望具備讀寫和數學能力。"},{"en":"Literate and numerate means able to read, write, and handle basic numbers properly.","zh":"literate and numerate 指能正確閱讀、書寫和處理基本數字。"},{"en":"A cashier needs to be literate and numerate to read labels and give correct change.","zh":"收銀員需要具備讀寫和數學能力，才能閱讀標籤並找對零錢。"},{"en":"If students are not literate and numerate, university assignments become much harder.","zh":"如果學生沒有讀寫和數學能力，大學功課會變得困難得多。"},{"en":"This phrase describes basic academic and practical skills.","zh":"這個短語描述基本學術和實用技能。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":1},{"front":"crimes against grammar","meaning":"嚴重語法錯誤","examples":[{"en":"Crimes against grammar were once the exception rather than the rule.","zh":"嚴重語法錯誤曾經是例外而非常態。"},{"en":"Crimes against grammar is a humorous phrase for serious or obvious grammar mistakes.","zh":"crimes against grammar 是幽默說法，指嚴重或明顯的文法錯誤。"},{"en":"A teacher may call repeated subject-verb errors crimes against grammar to make students notice them.","zh":"老師可能把反覆的主謂一致錯誤稱為嚴重語法錯誤，以令學生注意。"},{"en":"The phrase sounds dramatic because grammar mistakes are not real crimes.","zh":"這個短語聽起來戲劇化，因為文法錯誤不是真正罪行。"},{"en":"It is useful in informal criticism of very poor writing.","zh":"它適合用於非正式批評很差的寫作。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":1},{"front":"the exception rather than the rule","meaning":"例外而非常態","examples":[{"en":"Grammar mistakes were once the exception rather than the rule.","zh":"文法錯誤曾經是例外而非常態。"},{"en":"The exception rather than the rule means something happens rarely, not normally.","zh":"exception rather than the rule 指某事很少發生，而不是通常情況。"},{"en":"In a well-run class, late homework should be the exception rather than the rule.","zh":"在管理良好的班級，遲交功課應是例外而非常態。"},{"en":"If a problem becomes the rule, it is no longer a small occasional issue.","zh":"如果問題變成常態，它就不再是偶爾的小問題。"},{"en":"This phrase clearly contrasts rare cases with the usual pattern.","zh":"這個短語清楚對比罕見情況與通常模式。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":1},{"front":"according to","meaning":"根據","examples":[{"en":"According to a new survey, university staff are worried about student standards.","zh":"根據一項新調查，大學教職員擔心學生水平。"},{"en":"According to means based on what a source says or reports.","zh":"according to 指基於某來源所說或所報道。"},{"en":"According to the timetable, the last bus leaves at midnight.","zh":"根據時間表，最後一班巴士在午夜開出。"},{"en":"This phrase helps show where information comes from.","zh":"這個短語幫助顯示資訊來源。"},{"en":"In reading tasks, according to the text means the answer must be supported by the passage.","zh":"在閱讀題中，according to the text 表示答案必須由文章支持。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":2},{"front":"a comprehensive survey","meaning":"全面調查","examples":[{"en":"A comprehensive survey examined the views of British university faculty and staff.","zh":"一項全面調查研究了英國大學教職員的看法。"},{"en":"A comprehensive survey is a detailed study that covers many people, questions, or aspects of a topic.","zh":"comprehensive survey 指涵蓋許多人、問題或主題面向的詳細研究。"},{"en":"A school may conduct a comprehensive survey to understand students’ learning needs.","zh":"學校可能進行全面調查，以了解學生學習需要。"},{"en":"A broad survey can reveal patterns that a few interviews may miss.","zh":"廣泛調查可以揭示少數訪問可能看不到的模式。"},{"en":"This phrase suggests the research is wide-ranging and serious.","zh":"這個短語暗示研究範圍廣且認真。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":2},{"front":"faculty and staff","meaning":"教職員","examples":[{"en":"The survey collected opinions from university faculty and staff.","zh":"調查收集了大學教職員的意見。"},{"en":"Faculty and staff means academic teachers and other employees in an institution.","zh":"faculty and staff 指學術教師和機構內其他員工。"},{"en":"Faculty and staff may include professors, tutors, librarians, technicians, and administrators.","zh":"教職員可能包括教授、導師、圖書館員、技術員和行政人員。"},{"en":"When both groups are surveyed, the results reflect more than classroom teaching alone.","zh":"當兩類人都被調查，結果反映的不只是課堂教學。"},{"en":"This phrase is common in university and school contexts.","zh":"這個短語常見於大學和學校語境。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":2},{"front":"incoming students","meaning":"入學新生","examples":[{"en":"Some tutors complain that incoming students do not know how to write essays.","zh":"有些導師投訴入學新生不知道如何寫論文。"},{"en":"Incoming students are students who are just entering a school, college, or university.","zh":"incoming students 指剛進入學校、學院或大學的學生。"},{"en":"A university may run orientation sessions for incoming students before classes begin.","zh":"大學可能在開課前為入學新生舉辦迎新活動。"},{"en":"If incoming students lack key skills, teachers may need to spend time on remedial work.","zh":"如果入學新生缺乏關鍵技能，教師可能需要花時間補底。"},{"en":"This phrase focuses on students at the point of entry.","zh":"這個短語聚焦剛入學階段的學生。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":2},{"front":"know how to","meaning":"知道如何","examples":[{"en":"Some incoming students do not know how to write essays properly.","zh":"有些入學新生不知道如何正確寫論文。"},{"en":"Know how to do something means understand the method or skill needed to do it.","zh":"know how to do something 指理解做某事所需的方法或技能。"},{"en":"A child may know how to use a phone but not know how to organise homework.","zh":"孩子可能知道如何使用手機，但不知道如何整理功課。"},{"en":"If students do not know how to plan, they may write essays with weak structure.","zh":"如果學生不知道如何規劃，文章結構可能薄弱。"},{"en":"This phrase is useful when talking about practical ability.","zh":"談論實際能力時，這個短語很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":2},{"front":"write essays","meaning":"寫論文；寫文章","examples":[{"en":"Some students do not know how to write essays.","zh":"有些學生不知道如何寫論文。"},{"en":"To write essays means to produce organised pieces of academic writing with arguments, evidence, and structure.","zh":"write essays 指寫出有論點、證據和結構的學術文章。"},{"en":"Students learn to write essays by planning paragraphs and supporting ideas with examples.","zh":"學生透過規劃段落並用例子支持想法來學習寫文章。"},{"en":"Poor essay writing can make good ideas look unclear.","zh":"寫作能力差會令好想法看起來不清楚。"},{"en":"This phrase is central to school and university study.","zh":"這個短語是學校和大學學習的核心。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":2},{"front":"assemble bits from","meaning":"從……拼湊片段","examples":[{"en":"Some students simply assemble bits from the Internet.","zh":"有些學生只是從互聯網拼湊片段。"},{"en":"To assemble bits from something means to put together small pieces from a source without creating a strong original whole.","zh":"assemble bits from something 指從某來源把小片段拼在一起，而沒有形成強而原創的整體。"},{"en":"A weak report may assemble bits from websites instead of explaining the topic clearly.","zh":"薄弱報告可能從網站拼湊片段，而不是清楚解釋主題。"},{"en":"If students only assemble bits from the Internet, they may not understand what they submit.","zh":"如果學生只從互聯網拼湊片段，他們可能不理解自己提交的內容。"},{"en":"This phrase often criticises shallow copying or patchwork writing.","zh":"這個短語常批評膚淺抄襲或拼貼式寫作。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":2},{"front":"a disgruntled tutor","meaning":"不滿的導師","examples":[{"en":"A disgruntled Oxford tutor criticised students’ writing ability.","zh":"一名不滿的牛津導師批評學生的寫作能力。"},{"en":"A disgruntled tutor is a teacher who feels dissatisfied, annoyed, or disappointed.","zh":"disgruntled tutor 指感到不滿、惱怒或失望的教師。"},{"en":"A disgruntled tutor may complain when students repeatedly ignore feedback.","zh":"當學生反覆忽視回饋，不滿的導師可能會投訴。"},{"en":"Disgruntled teachers often speak out when they believe standards are falling.","zh":"當教師認為水平下降，他們常會不滿並公開發聲。"},{"en":"This phrase describes both the person and their unhappy attitude.","zh":"這個短語同時描述人物和其不滿態度。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":2},{"front":"the cream of candidates","meaning":"候選人中的精英","examples":[{"en":"Even the cream of candidates may have problems with punctuation.","zh":"即使候選人中的精英也可能有標點問題。"},{"en":"The cream of candidates means the very best applicants or people in a selection group.","zh":"cream of candidates 指申請者或候選群體中最優秀的人。"},{"en":"A scholarship interview may invite only the cream of candidates from hundreds of applicants.","zh":"獎學金面試可能只邀請數百名申請者中的精英。"},{"en":"If even the best candidates have weak writing, the problem may be widespread.","zh":"如果連最優秀候選人寫作都弱，問題可能很普遍。"},{"en":"This phrase is idiomatic and means the top group, not literal cream.","zh":"這個短語是習語，表示頂尖群體，不是字面上的忌廉。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":2},{"front":"not necessarily","meaning":"不一定","examples":[{"en":"The best candidates do not necessarily know how to use an apostrophe.","zh":"最好的候選人不一定知道如何正確使用撇號。"},{"en":"Not necessarily means not always or not automatically.","zh":"not necessarily 指不總是或不自動表示。"},{"en":"A high exam score does not necessarily mean a student can write clearly.","zh":"高考試分數不一定表示學生能清楚寫作。"},{"en":"This phrase helps avoid overgeneralising from one fact.","zh":"這個短語有助避免從一個事實作過度概括。"},{"en":"It is useful when something may be true in some cases but not all.","zh":"當某事在部分情況下可能成立，但不是全部成立時，它很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":2},{"front":"use an apostrophe","meaning":"使用撇號","examples":[{"en":"Some students do not know how to use an apostrophe correctly.","zh":"有些學生不知道如何正確使用撇號。"},{"en":"To use an apostrophe means to place the mark ’ correctly in contractions or possession.","zh":"use an apostrophe 指在縮寫或所有格中正確放置 ’ 這個符號。"},{"en":"A student uses an apostrophe in don’t because letters have been left out.","zh":"學生在 don’t 中使用撇號，因為有字母被省略。"},{"en":"Wrong apostrophes can make writing look careless even when the idea is good.","zh":"錯誤撇號會令文章看起來粗心，即使想法不錯。"},{"en":"This phrase belongs to punctuation and grammar.","zh":"這個短語屬於標點和文法。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":2},{"front":"decline in student competence","meaning":"學生能力下降","examples":[{"en":"The decline in student competence has worried professors and employers.","zh":"學生能力下降令教授和僱主擔憂。"},{"en":"A decline in student competence means a fall in students’ ability or preparedness.","zh":"decline in student competence 指學生能力或準備程度下降。"},{"en":"A school may notice a decline in competence if students cannot read exam questions accurately.","zh":"如果學生不能準確閱讀考題，學校可能注意到能力下降。"},{"en":"When competence declines, teachers may need to reteach basic skills.","zh":"當能力下降，教師可能需要重新教授基本技能。"},{"en":"This phrase is often used in debates about education standards.","zh":"這個短語常用於教育水平辯論。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":3},{"front":"parallel a dramatic increase in","meaning":"與……大幅增加同步出現","examples":[{"en":"The decline in student competence parallels a dramatic increase in enrolment.","zh":"學生能力下降與收生人數大幅增加同步出現。"},{"en":"To parallel a dramatic increase in something means to happen at the same time as a large rise in it.","zh":"parallel a dramatic increase in something 指與某事的大幅上升同時發生。"},{"en":"A rise in online shopping may parallel a dramatic increase in delivery jobs.","zh":"網購上升可能與外賣或送貨工作大幅增加同步出現。"},{"en":"When two trends move together, people may ask whether they are connected.","zh":"當兩個趨勢同時移動，人們可能問它們是否有關。"},{"en":"This phrase shows simultaneous change, not necessarily direct cause.","zh":"這個短語表示同步變化，不一定表示直接因果。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":3},{"front":"university and college enrolment","meaning":"大學及院校收生人數","examples":[{"en":"University and college enrolment has increased dramatically.","zh":"大學及院校收生人數大幅增加。"},{"en":"University and college enrolment means the number of students entering or studying in higher education institutions.","zh":"university and college enrolment 指進入或就讀高等教育機構的學生人數。"},{"en":"A country may expand enrolment by building new campuses and offering more places.","zh":"國家可以透過興建新校園和提供更多學額來擴大收生。"},{"en":"Higher enrolment can widen access but may put pressure on teaching resources.","zh":"更高收生人數可以擴大入學機會，但也可能令教學資源受壓。"},{"en":"This phrase is common in education policy.","zh":"這個短語常見於教育政策。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":3},{"front":"over the past decade","meaning":"在過去十年","examples":[{"en":"Enrolment has risen sharply over the past decade.","zh":"收生人數在過去十年大幅上升。"},{"en":"Over the past decade means during the last ten years.","zh":"over the past decade 指在過去十年期間。"},{"en":"Online learning has expanded over the past decade.","zh":"網上學習在過去十年擴展。"},{"en":"This phrase helps describe recent long-term change rather than a single event.","zh":"這個短語幫助描述近期長期變化，而不是單一事件。"},{"en":"It is often used with trends, increases, declines, and policy changes.","zh":"它常與趨勢、上升、下降和政策改變一起使用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":3},{"front":"be spurred by","meaning":"受到……推動","examples":[{"en":"The increase was spurred by Tony Blair’s education policy.","zh":"這次增加受到 Tony Blair 的教育政策推動。"},{"en":"To be spurred by something means to be encouraged or driven by it.","zh":"be spurred by something 指受到某事鼓勵或推動。"},{"en":"A student’s improvement may be spurred by praise from a teacher.","zh":"學生進步可能受到老師讚賞推動。"},{"en":"Policy changes can spur growth by creating targets and funding incentives.","zh":"政策改變可以透過制定目標和資金誘因推動增長。"},{"en":"This phrase shows what pushed a change forward.","zh":"這個短語顯示甚麼推動變化向前。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":3},{"front":"in recent years","meaning":"近年","examples":[{"en":"The policy has been promoted in recent years.","zh":"這項政策近年一直被推動。"},{"en":"In recent years means during the last few years before the time being discussed.","zh":"in recent years 指在所討論時間之前的最近幾年。"},{"en":"In recent years, more schools have used tablets in class.","zh":"近年，更多學校在課堂使用平板電腦。"},{"en":"This phrase helps writers point to a modern trend or recent change.","zh":"這個短語幫助作者指出現代趨勢或近期變化。"},{"en":"It is useful when contrasting newer developments with older patterns.","zh":"當比較較新的發展與較舊模式時，它很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":3},{"front":"Prime Minister Tony Blair’s push for","meaning":"首相 Tony Blair 對……的推動","examples":[{"en":"Prime Minister Tony Blair’s push for wider access changed higher education.","zh":"首相 Tony Blair 對擴大入學機會的推動改變了高等教育。"},{"en":"A push for something is a strong effort to promote or achieve it.","zh":"push for something 指強力推動或努力達成某事。"},{"en":"A principal’s push for smaller classes may lead to hiring more teachers.","zh":"校長對小班教學的推動可能導致聘請更多老師。"},{"en":"A political push can change institutions if it becomes policy.","zh":"如果政治推動變成政策，它可以改變制度。"},{"en":"This phrase links a leader’s effort with wider social change.","zh":"這個短語把領導人的努力與更廣泛社會變化連接起來。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":3},{"front":"half of all young Britons","meaning":"全英年輕人中的一半","examples":[{"en":"The government wants half of all young Britons to obtain a university degree.","zh":"政府希望全英年輕人中的一半取得大學學位。"},{"en":"Half of all young Britons means fifty per cent of young people in Britain.","zh":"half of all young Britons 指英國年輕人中的百分之五十。"},{"en":"A government target for half of all young adults to study further would greatly expand education.","zh":"政府若以一半年輕成年人繼續升學為目標，將大幅擴展教育。"},{"en":"Such a target can increase opportunity but may also raise questions about quality and funding.","zh":"這類目標可以增加機會，但也可能引起對質素和資金的疑問。"},{"en":"This phrase gives a large national proportion.","zh":"這個短語提供一個大型全國比例。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":3},{"front":"obtain a university degree","meaning":"取得大學學位","examples":[{"en":"More young people are expected to obtain a university degree.","zh":"更多年輕人被期望取得大學學位。"},{"en":"To obtain a university degree means to successfully complete university study and receive a formal qualification.","zh":"obtain a university degree 指成功完成大學學習並獲得正式資格。"},{"en":"A student may obtain a university degree after three or four years of study.","zh":"學生可能經過三至四年學習後取得大學學位。"},{"en":"Getting a degree can improve job options, but it usually requires time and money.","zh":"取得學位可以改善工作選擇，但通常需要時間和金錢。"},{"en":"This phrase is formal and common in education policy.","zh":"這個短語較正式，常見於教育政策。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":3},{"front":"professors and business owners alike","meaning":"教授和企業東主同樣","examples":[{"en":"Professors and business owners alike have criticised graduate quality.","zh":"教授和企業東主同樣批評畢業生質素。"},{"en":"Professors and business owners alike means both university teachers and company owners share the same view or reaction.","zh":"professors and business owners alike 指大學教師和企業東主都持相同看法或反應。"},{"en":"Parents and teachers alike may worry if students sleep too little.","zh":"如果學生睡眠太少，家長和老師同樣可能擔心。"},{"en":"When different groups complain alike, the issue may seem more serious.","zh":"當不同群體同樣投訴，問題可能顯得更嚴重。"},{"en":"This phrase stresses agreement across groups that are normally separate.","zh":"這個短語強調通常分開的群體之間有一致看法。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":3},{"front":"decry the quality of","meaning":"批評……的質素","examples":[{"en":"Some observers decry the quality of university students and graduates.","zh":"有些觀察者批評大學生及畢業生的質素。"},{"en":"To decry the quality of something means to publicly criticise it as poor or declining.","zh":"decry the quality of something 指公開批評某物質素差或正在下降。"},{"en":"Employers may decry the quality of applications if many candidates cannot write clearly.","zh":"如果許多候選人不能清楚寫作，僱主可能批評申請質素。"},{"en":"Public criticism can pressure institutions to improve standards.","zh":"公開批評可以向機構施壓，要求改善標準。"},{"en":"This phrase is formal and stronger than simply complain about.","zh":"這個短語較正式，比 simply complain about 更強。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":3},{"front":"university students and graduates","meaning":"大學生及畢業生","examples":[{"en":"Employers are concerned about the quality of university students and graduates.","zh":"僱主關注大學生及畢業生的質素。"},{"en":"University students and graduates means people currently studying at university and people who have completed university.","zh":"university students and graduates 指正在大學就讀的人，以及已完成大學的人。"},{"en":"Employers may assess university students and graduates through interviews, writing tasks, and internships.","zh":"僱主可能透過面試、寫作任務和實習評估大學生及畢業生。"},{"en":"If graduates lack skills, universities may face pressure to change teaching.","zh":"如果畢業生缺乏技能，大學可能面對改變教學的壓力。"},{"en":"This phrase covers both current learners and former students entering work.","zh":"這個短語涵蓋現時學習者和進入職場的前學生。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":4},{"front":"more than a few observers","meaning":"不少觀察者","examples":[{"en":"More than a few observers are questioning the policy.","zh":"不少觀察者正在質疑這項政策。"},{"en":"More than a few observers means quite a number of people who watch or analyse the issue.","zh":"more than a few observers 指相當多觀察或分析該議題的人。"},{"en":"More than a few teachers worry that students rely too heavily on copied notes.","zh":"不少老師擔心學生過度依賴抄來的筆記。"},{"en":"This phrase suggests the criticism is not isolated or rare.","zh":"這個短語暗示批評並非孤立或罕見。"},{"en":"It is a cautious way to say that many people are concerned.","zh":"它是表示許多人擔心的謹慎說法。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":4},{"front":"question the wisdom of","meaning":"質疑……是否明智","examples":[{"en":"Some observers question the wisdom of expanding university education so quickly.","zh":"有些觀察者質疑如此快速擴展大學教育是否明智。"},{"en":"To question the wisdom of something means to doubt whether it is sensible or wise.","zh":"question the wisdom of something 指懷疑某事是否合理或明智。"},{"en":"Parents may question the wisdom of giving children phones at a very young age.","zh":"家長可能質疑很小就給孩子手機是否明智。"},{"en":"If a policy creates costs and weak results, people may question its wisdom.","zh":"如果政策造成成本和薄弱成果，人們可能質疑其明智程度。"},{"en":"This phrase is formal and useful for criticising decisions politely.","zh":"這個短語較正式，適合禮貌批評決定。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":4},{"front":"ivory towers","meaning":"象牙塔；大學學術圈","examples":[{"en":"Some people question the wisdom of packing ivory towers with the masses.","zh":"有些人質疑把普羅大眾塞進象牙塔是否明智。"},{"en":"Ivory towers refers to universities or academic circles seen as separate from ordinary life.","zh":"ivory towers 指被視為與普通生活分離的大學或學術圈。"},{"en":"Critics may say professors live in ivory towers if their ideas ignore real workplace problems.","zh":"如果教授的想法忽視真實工作問題，批評者可能說他們住在象牙塔裏。"},{"en":"The phrase can be critical because it suggests distance from practical reality.","zh":"這個短語可以帶批評意味，因為它暗示遠離實際現實。"},{"en":"In this context, it refers to higher education becoming less exclusive.","zh":"在此語境中，它指高等教育變得較不精英化。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":4},{"front":"the masses","meaning":"普羅大眾","examples":[{"en":"Critics worry about packing ivory towers with the masses.","zh":"批評者擔心把普羅大眾塞進象牙塔。"},{"en":"The masses means ordinary people in large numbers, rather than a small elite.","zh":"the masses 指大量普通人，而不是一小群精英。"},{"en":"Public transport is designed for the masses, not only for wealthy travellers.","zh":"公共交通是為普羅大眾而設，不只是為富裕旅客而設。"},{"en":"When education opens to the masses, access becomes wider but resources may be stretched.","zh":"當教育向普羅大眾開放，入學機會會擴大，但資源可能被拉緊。"},{"en":"This phrase can sound neutral, democratic, or slightly dismissive depending on tone.","zh":"視乎語氣，這個短語可以中性、民主化，或略帶貶意。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":4},{"front":"higher education","meaning":"高等教育","examples":[{"en":"Students may question whether higher education is overvalued.","zh":"學生可能質疑高等教育是否被高估。"},{"en":"Higher education means education after secondary school, especially at universities and colleges.","zh":"higher education 指中學後的教育，尤其是大學和學院教育。"},{"en":"Higher education can include degrees, diplomas, research training, and professional courses.","zh":"高等教育可以包括學位、文憑、研究訓練和專業課程。"},{"en":"It can improve skills and job prospects, but it may also involve high costs.","zh":"它可以改善技能和就業前景，但也可能涉及高成本。"},{"en":"This phrase is central to discussions of universities and social mobility.","zh":"這個短語是討論大學和社會流動的核心。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":4},{"front":"be overvalued","meaning":"被高估","examples":[{"en":"Some students may begin to wonder whether higher education is overvalued.","zh":"有些學生可能開始懷疑高等教育是否被高估。"},{"en":"To be overvalued means to be considered more useful, important, or valuable than it really is.","zh":"be overvalued 指被認為比實際更有用、更重要或更有價值。"},{"en":"A brand-name product may be overvalued if a cheaper one works just as well.","zh":"如果便宜產品同樣好用，名牌產品可能被高估。"},{"en":"If university costs rise but benefits feel uncertain, people may think degrees are overvalued.","zh":"如果大學成本上升但好處不確定，人們可能認為學位被高估。"},{"en":"This phrase is useful when questioning reputation or price.","zh":"質疑名聲或價格時，這個短語很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":4},{"front":"tuition rates","meaning":"學費","examples":[{"en":"Tuition rates are set to rise steeply.","zh":"學費即將大幅上升。"},{"en":"Tuition rates are the amounts students must pay for education.","zh":"tuition rates 指學生必須支付的教育費用。"},{"en":"Parents may compare tuition rates before choosing a private course.","zh":"家長選擇私人課程前可能比較學費。"},{"en":"Higher tuition rates can make students worry about debt.","zh":"更高學費可以令學生擔心債務。"},{"en":"This phrase is common in education finance.","zh":"這個短語常見於教育財務。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":4},{"front":"be set to","meaning":"即將；預計會","examples":[{"en":"Tuition rates are set to rise steeply next autumn.","zh":"學費預計會在明年秋季大幅上升。"},{"en":"Be set to means expected or scheduled to happen soon.","zh":"be set to 指預計或安排即將發生。"},{"en":"The school is set to open a new library next term.","zh":"學校預計下學期開放新圖書館。"},{"en":"When something is set to happen, people should prepare for its effects.","zh":"當某事即將發生，人們應準備其影響。"},{"en":"This phrase is common in news and reports.","zh":"這個短語常見於新聞和報告。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":4},{"front":"rise steeply","meaning":"大幅上升","examples":[{"en":"Tuition rates are expected to rise steeply.","zh":"學費預計會大幅上升。"},{"en":"To rise steeply means to increase quickly and by a large amount.","zh":"rise steeply 指快速且大幅增加。"},{"en":"Rent may rise steeply when a new train station opens nearby.","zh":"當附近開通新火車站，租金可能大幅上升。"},{"en":"A steep rise in fees can force families to rethink their budgets.","zh":"學費大幅上升可能迫使家庭重新考慮預算。"},{"en":"This phrase is used for sharp increases in prices, numbers, or rates.","zh":"這個短語用於價格、數字或比率急升。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":4},{"front":"next autumn","meaning":"明年秋季","examples":[{"en":"Tuition rates are set to rise steeply next autumn.","zh":"學費將於明年秋季大幅上升。"},{"en":"Next autumn means the autumn after the present time or the time being discussed.","zh":"next autumn 指現在或所討論時間之後的下一個秋季。"},{"en":"The new course will begin next autumn after the summer break.","zh":"新課程將在暑假後的明年秋季開始。"},{"en":"Giving a season tells readers roughly when a change will happen.","zh":"說出季節可以讓讀者大概知道變化何時發生。"},{"en":"This phrase is useful for future plans and policy changes.","zh":"這個短語適用於未來計劃和政策改變。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":4},{"front":"be teeming with","meaning":"擠滿；充滿","examples":[{"en":"British universities and colleges are teeming with young adults.","zh":"英國大學和學院擠滿年輕成年人。"},{"en":"To be teeming with something means to be full of many people, animals, or things.","zh":"be teeming with something 指充滿大量人、動物或事物。"},{"en":"A school canteen may be teeming with students during lunch break.","zh":"午飯時間，學校飯堂可能擠滿學生。"},{"en":"When a place is teeming with people, space and services may become stretched.","zh":"當一個地方擠滿人，空間和服務可能變得緊張。"},{"en":"This phrase creates a strong image of crowded activity.","zh":"這個短語營造出擁擠活動的強烈畫面。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":5},{"front":"young adults","meaning":"年輕成年人","examples":[{"en":"Universities and colleges are full of young adults.","zh":"大學和學院充滿年輕成年人。"},{"en":"Young adults are people who are no longer children but are still in the early stage of adulthood.","zh":"young adults 指不再是兒童，但仍處於成年早期的人。"},{"en":"Many young adults leave home for university, work, or training.","zh":"許多年輕成年人離家上大學、工作或接受培訓。"},{"en":"Policies affecting young adults can shape careers, debt, and family decisions.","zh":"影響年輕成年人的政策可以塑造職業、債務和家庭決定。"},{"en":"This phrase usually refers to people around late teens to twenties.","zh":"這個短語通常指十多歲後期至二十多歲的人。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":5},{"front":"a 12-fold increase","meaning":"12倍增長","examples":[{"en":"The number of students represents a 12-fold increase over 1960s numbers.","zh":"學生人數相比1960年代代表12倍增長。"},{"en":"A 12-fold increase means the number has become twelve times as large.","zh":"12-fold increase 指數字變成原來的十二倍。"},{"en":"If a club grows from 10 members to 120, it has had a 12-fold increase.","zh":"如果學會由10人增至120人，就是12倍增長。"},{"en":"Such a large increase can transform an institution’s size, cost, and culture.","zh":"這種巨大增長可以改變機構的規模、成本和文化。"},{"en":"This phrase is useful for describing very large growth.","zh":"描述非常大幅增長時，這個短語很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":5},{"front":"over 1960s numbers","meaning":"相比1960年代的人數","examples":[{"en":"Student numbers have risen sharply over 1960s numbers.","zh":"學生人數相比1960年代的人數大幅上升。"},{"en":"Over 1960s numbers means compared with the number recorded in the 1960s.","zh":"over 1960s numbers 指與1960年代記錄的人數相比。"},{"en":"A school may say enrolment is far higher over 1990s numbers.","zh":"學校可能說收生人數相比1990年代的人數高得多。"},{"en":"Comparing with older numbers helps show long-term change.","zh":"與舊數字比較有助顯示長期變化。"},{"en":"This phrase uses a past period as the baseline.","zh":"這個短語以過去時期作為基準。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":5},{"front":"up almost fifty per cent","meaning":"上升接近百分之五十","examples":[{"en":"Student numbers are up almost fifty per cent over the past decade.","zh":"學生人數在過去十年上升接近百分之五十。"},{"en":"Up almost fifty per cent means increased by nearly half.","zh":"up almost fifty per cent 指增加接近一半。"},{"en":"If rent is up almost fifty per cent, many tenants may struggle to pay.","zh":"如果租金上升接近百分之五十，許多租客可能難以負擔。"},{"en":"A rise of this size can create pressure on space, staff, and funding.","zh":"這種幅度的上升可以對空間、人手和資金造成壓力。"},{"en":"This phrase describes a large numerical increase.","zh":"這個短語描述大幅數字增長。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":5},{"front":"the past decade alone","meaning":"單是過去十年","examples":[{"en":"Enrolment has risen sharply over the past decade alone.","zh":"單是過去十年，收生人數已大幅上升。"},{"en":"The past decade alone means only the last ten years, without counting earlier periods.","zh":"past decade alone 指只計過去十年，不包括更早時期。"},{"en":"A neighbourhood may change greatly over the past decade alone if many new buildings appear.","zh":"如果許多新建築出現，社區單是過去十年已可能大變。"},{"en":"This phrase emphasises that a large change happened in a relatively short recent period.","zh":"這個短語強調巨大變化發生在相對較短的近期。"},{"en":"It is useful when recent change is especially striking.","zh":"當近期變化特別明顯時，它很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":5},{"front":"a report published last month","meaning":"上月發表的報告","examples":[{"en":"A report published last month examined graduate recruitment.","zh":"上月發表的一份報告研究了畢業生招聘。"},{"en":"A report published last month is a document made public in the previous month.","zh":"report published last month 指在上一個月公開的文件。"},{"en":"A school may discuss a report published last month about student wellbeing.","zh":"學校可能討論上月發表的一份關於學生福祉的報告。"},{"en":"Recent reports can influence public debate because they contain fresh evidence.","zh":"近期報告可以影響公共討論，因為它們包含新證據。"},{"en":"This phrase gives timing and source type together.","zh":"這個短語同時提供時間和來源類型。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":5},{"front":"graduate recruiters","meaning":"畢業生招聘者","examples":[{"en":"The Association of Graduate Recruiters represents employers of university graduates.","zh":"畢業生招聘者協會代表聘請大學畢業生的僱主。"},{"en":"Graduate recruiters are employers or specialists who hire people leaving university.","zh":"graduate recruiters 指聘請大學畢業生的僱主或專門人員。"},{"en":"Large companies may send graduate recruiters to university career fairs.","zh":"大公司可能派畢業生招聘者到大學招聘展。"},{"en":"Recruiters judge whether graduates have the skills needed for professional jobs.","zh":"招聘者會判斷畢業生是否具備專業工作所需技能。"},{"en":"This phrase connects university education with the job market.","zh":"這個短語把大學教育與就業市場連接起來。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":5},{"front":"top employers","meaning":"主要僱主","examples":[{"en":"Almost half of the top employers were unhappy with graduate candidates.","zh":"幾乎一半主要僱主對畢業生候選人不滿。"},{"en":"Top employers are major or highly regarded organisations that hire many workers.","zh":"top employers 指主要或備受重視、聘請大量員工的機構。"},{"en":"Top employers may receive thousands of applications for graduate jobs.","zh":"主要僱主可能收到數千份畢業生職位申請。"},{"en":"If top employers complain about skills, universities may take the criticism seriously.","zh":"如果主要僱主投訴技能問題，大學可能認真看待批評。"},{"en":"This phrase often refers to leading companies in a job market.","zh":"這個短語常指就業市場中的領先公司。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":5},{"front":"university graduates","meaning":"大學畢業生","examples":[{"en":"Employers recruit university graduates for skilled jobs.","zh":"僱主招聘大學畢業生擔任技術性職位。"},{"en":"University graduates are people who have completed a degree at university.","zh":"university graduates 指已完成大學學位的人。"},{"en":"A hospital may recruit university graduates for nursing, administration, or laboratory roles.","zh":"醫院可能招聘大學畢業生擔任護理、行政或實驗室職位。"},{"en":"Graduates are often expected to have writing, reasoning, and communication skills.","zh":"畢業生通常被期望具備寫作、推理和溝通能力。"},{"en":"This phrase refers to people after they finish university study.","zh":"這個短語指完成大學學習後的人。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":5},{"front":"be unhappy with","meaning":"對……不滿","examples":[{"en":"Many employers were unhappy with the calibre of candidates.","zh":"許多僱主對候選人的質素不滿。"},{"en":"To be unhappy with something means to be dissatisfied with it.","zh":"be unhappy with something 指對某事不滿意。"},{"en":"A customer may be unhappy with a meal if it arrives cold.","zh":"如果餐點送到時已變冷，顧客可能對它不滿。"},{"en":"When employers are unhappy with candidates, they may change recruitment tests.","zh":"當僱主對候選人不滿，他們可能改變招聘測試。"},{"en":"This phrase is a common way to express dissatisfaction.","zh":"這個短語是表達不滿的常見方式。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":5},{"front":"the calibre of candidates","meaning":"候選人的質素","examples":[{"en":"Employers criticised the calibre of candidates.","zh":"僱主批評候選人的質素。"},{"en":"The calibre of candidates means the quality, ability, or standard of people applying for positions.","zh":"calibre of candidates 指申請職位者的質素、能力或水平。"},{"en":"A company may raise salaries to attract a higher calibre of candidates.","zh":"公司可能提高薪金，以吸引更高質素的候選人。"},{"en":"If the calibre of candidates falls, employers may struggle to fill skilled roles.","zh":"如果候選人質素下降，僱主可能難以填補技術性職位。"},{"en":"This phrase is formal and common in recruitment.","zh":"這個短語較正式，常見於招聘語境。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":6},{"front":"a recent survey","meaning":"最近一項調查","examples":[{"en":"A recent survey listed a catalogue of complaints about freshmen.","zh":"最近一項調查列出一連串對大學新生的投訴。"},{"en":"A recent survey is a study carried out not long before the time being discussed.","zh":"recent survey 指在所討論時間不久前進行的研究。"},{"en":"A recent survey may show that students are worried about tuition fees.","zh":"最近一項調查可能顯示學生擔心學費。"},{"en":"Recent surveys can make old concerns feel urgent again.","zh":"近期調查可以令舊有擔憂再次顯得迫切。"},{"en":"This phrase introduces evidence from current research.","zh":"這個短語引入來自當前研究的證據。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":6},{"front":"be conducted by","meaning":"由……進行","examples":[{"en":"The survey was conducted by Oxford University and UCAS.","zh":"這項調查由牛津大學和 UCAS 進行。"},{"en":"To be conducted by someone means to be carried out or organised by them.","zh":"be conducted by someone 指由某人或機構執行或組織。"},{"en":"A health survey may be conducted by a local hospital.","zh":"健康調查可能由本地醫院進行。"},{"en":"Knowing who conducted a study helps readers judge its reliability and purpose.","zh":"知道研究由誰進行，有助讀者判斷其可靠性和目的。"},{"en":"This phrase is formal and common in research writing.","zh":"這個短語較正式，常見於研究寫作。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":6},{"front":"admissions service","meaning":"招生服務機構","examples":[{"en":"UCAS is a universities and colleges admissions service.","zh":"UCAS 是一個大學及院校招生服務機構。"},{"en":"An admissions service is an organisation or system that manages applications to educational institutions.","zh":"admissions service 指管理教育機構申請的組織或系統。"},{"en":"Students may use an admissions service to apply to several universities at once.","zh":"學生可能透過招生服務機構一次過申請幾間大學。"},{"en":"A central service can make applications more organised but also more competitive.","zh":"中央服務可以令申請更有組織，但也可能更具競爭性。"},{"en":"This phrase belongs to education and application processes.","zh":"這個短語屬於教育和申請流程。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":6},{"front":"a catalogue of complaints","meaning":"一連串投訴","examples":[{"en":"The survey listed a catalogue of complaints about freshmen.","zh":"調查列出一連串對大學新生的投訴。"},{"en":"A catalogue of complaints means a long list of criticisms or problems.","zh":"catalogue of complaints 指一長串批評或問題。"},{"en":"A hotel may receive a catalogue of complaints if rooms are dirty, noisy, and poorly staffed.","zh":"如果酒店房間骯髒、嘈吵且人手不足，可能收到一連串投訴。"},{"en":"When complaints are numerous, leaders may need to investigate a system-wide problem.","zh":"當投訴很多，領導者可能需要調查整個系統的問題。"},{"en":"This phrase emphasises the number and variety of criticisms.","zh":"這個短語強調批評的數量和種類。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":6},{"front":"freshmen","meaning":"大學新生","examples":[{"en":"The survey collected complaints about freshmen.","zh":"調查收集了對大學新生的投訴。"},{"en":"Freshmen are students in their first year at university or college.","zh":"freshmen 指大學或學院一年級學生。"},{"en":"Freshmen often need guidance on essays, lectures, deadlines, and independent study.","zh":"大學新生常需要關於論文、講課、截止日期和自主學習的指導。"},{"en":"If freshmen arrive underprepared, tutors may need to adjust early courses.","zh":"如果新生準備不足，導師可能需要調整初期課程。"},{"en":"This word is common in American English but is understood in university contexts.","zh":"這個詞常見於美式英語，但在大學語境中一般能理解。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":6},{"front":"lead in some cases to","meaning":"在某些情況下導致","examples":[{"en":"Student weaknesses led in some cases to courses being delayed.","zh":"學生弱點在某些情況下導致課程被延遲。"},{"en":"Lead in some cases to means cause a result in certain situations, though not always.","zh":"lead in some cases to 指在某些情況下造成結果，但不是每次都如此。"},{"en":"Poor attendance can lead in some cases to students repeating a course.","zh":"出席率差在某些情況下可能導致學生重讀課程。"},{"en":"This phrase is careful because it does not claim the result happens every time.","zh":"這個短語很謹慎，因為它沒有聲稱結果每次都發生。"},{"en":"It is useful for discussing limited but serious consequences.","zh":"討論有限但嚴重的後果時，它很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":6},{"front":"year-long courses","meaning":"為期一年的課程","examples":[{"en":"Some year-long courses were deferred by a year.","zh":"有些為期一年的課程被延遲一年。"},{"en":"Year-long courses are courses that last for one full academic year or twelve months.","zh":"year-long courses 指持續一整個學年或十二個月的課程。"},{"en":"A year-long language course gives students time to practise reading, writing, listening, and speaking.","zh":"為期一年的語言課程讓學生有時間練習讀、寫、聽、說。"},{"en":"If a year-long course is delayed, students’ graduation plans may also be affected.","zh":"如果為期一年的課程被延遲，學生的畢業計劃也可能受影響。"},{"en":"This phrase describes course duration.","zh":"這個短語描述課程長度。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":6},{"front":"be deferred by a year","meaning":"被延遲一年","examples":[{"en":"Some courses had to be deferred by a year.","zh":"有些課程不得不被延遲一年。"},{"en":"To be deferred by a year means to be postponed for one year.","zh":"be deferred by a year 指被推遲一年。"},{"en":"A building project may be deferred by a year if funding is not ready.","zh":"如果資金未準備好，建築項目可能被延遲一年。"},{"en":"Deferring a course can affect students’ timetables, costs, and motivation.","zh":"延遲課程可以影響學生時間表、成本和動機。"},{"en":"This phrase is formal and often used in education or planning.","zh":"這個短語較正式，常用於教育或規劃。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":6},{"front":"go to higher education","meaning":"接受高等教育","examples":[{"en":"More students are going to higher education now.","zh":"現在更多學生接受高等教育。"},{"en":"To go to higher education means to enter university, college, or another post-secondary institution.","zh":"go to higher education 指進入大學、學院或其他中學後教育機構。"},{"en":"A student may go to higher education after finishing secondary school.","zh":"學生完成中學後可能接受高等教育。"},{"en":"Wider access allows more people to continue studying, but institutions need enough support.","zh":"擴大入學機會讓更多人繼續學習，但機構需要足夠支援。"},{"en":"This phrase describes moving into the next stage of education.","zh":"這個短語描述進入下一階段教育。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":6},{"front":"would not have done so","meaning":"以前不會這樣做","examples":[{"en":"Some students now enter higher education who would not have done so 20 years ago.","zh":"有些現在進入高等教育的學生，二十年前以前不會這樣做。"},{"en":"Would not have done so means would not have taken that action in an earlier or different situation.","zh":"would not have done so 指在較早或不同情況下不會採取該行動。"},{"en":"Many people now shop online who would not have done so before smartphones became common.","zh":"許多人現在網購，但在智能手機普及前以前不會這樣做。"},{"en":"This phrase helps compare present behaviour with a past possibility.","zh":"這個短語幫助比較現在行為與過去可能性。"},{"en":"It often shows how social conditions have changed.","zh":"它常顯示社會條件如何改變。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":6},{"front":"in some ways","meaning":"在某些方面","examples":[{"en":"In some ways, widening access to higher education is a good thing.","zh":"在某些方面，擴大高等教育入學機會是一件好事。"},{"en":"In some ways means from certain points of view, but not necessarily in every respect.","zh":"in some ways 指從某些角度看，但不一定在每方面都是。"},{"en":"In some ways, online classes are convenient because students can learn from home.","zh":"在某些方面，網上課堂很方便，因為學生可以在家學習。"},{"en":"This phrase lets writers make a balanced point before mentioning limitations.","zh":"這個短語讓作者先提出平衡觀點，再提限制。"},{"en":"It is useful when an issue has both benefits and problems.","zh":"當議題有好處也有問題時，它很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":7},{"front":"widen opportunity","meaning":"擴大機會","examples":[{"en":"Expanding higher education widens opportunity.","zh":"擴展高等教育會擴大機會。"},{"en":"To widen opportunity means to give more people access to chances they previously lacked.","zh":"widen opportunity 指讓更多人得到以前缺乏的機會。"},{"en":"Scholarships widen opportunity by helping poorer students study further.","zh":"獎學金透過幫助較貧窮學生繼續升學來擴大機會。"},{"en":"Wider opportunity can improve fairness, but it must be supported by good teaching.","zh":"擴大機會可以改善公平，但必須有良好教學支援。"},{"en":"This phrase is positive and often used in social policy.","zh":"這個短語帶正面意味，常用於社會政策。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":7},{"front":"genuine concerns about","meaning":"對……真正的擔憂","examples":[{"en":"There are genuine concerns about young people’s readiness for university.","zh":"人們對年輕人是否準備好入讀大學有真正的擔憂。"},{"en":"Genuine concerns about something are real worries based on evidence or experience.","zh":"genuine concerns about something 指基於證據或經驗的真實擔憂。"},{"en":"Parents may have genuine concerns about children walking home late at night.","zh":"家長可能對孩子深夜步行回家有真正的擔憂。"},{"en":"Genuine concerns should be discussed, not dismissed as simple negativity.","zh":"真正的擔憂應被討論，而不是被視為單純負面而忽略。"},{"en":"This phrase signals that the worry may be reasonable.","zh":"這個短語表示擔憂可能合理。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":7},{"front":"capacity to benefit from","meaning":"從……受益的能力","examples":[{"en":"Some people question students’ capacity to benefit from higher education.","zh":"有些人質疑學生從高等教育受益的能力。"},{"en":"Capacity to benefit from something means ability to gain useful results from it.","zh":"capacity to benefit from something 指從某事獲得有用成果的能力。"},{"en":"A student’s capacity to benefit from a fast course may depend on her reading level.","zh":"學生從高速課程受益的能力可能取決於她的閱讀水平。"},{"en":"If learners lack basic skills, they may not fully benefit from advanced teaching.","zh":"如果學習者缺乏基本技能，他們可能無法充分受益於進階教學。"},{"en":"This phrase is formal and focuses on readiness and ability.","zh":"這個短語較正式，聚焦準備程度和能力。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":7},{"front":"part of the problem","meaning":"部分問題","examples":[{"en":"Part of the problem lies in the way teenagers are taught in school.","zh":"部分問題在於青少年在學校受教的方式。"},{"en":"Part of the problem means one cause or element of a wider difficulty.","zh":"part of the problem 指較大困難中的一個原因或部分。"},{"en":"If students cannot write clearly, part of the problem may be lack of reading.","zh":"如果學生不能清楚寫作，部分問題可能是閱讀不足。"},{"en":"Saying part of the problem suggests there may be other causes too.","zh":"說 part of the problem 暗示可能還有其他原因。"},{"en":"This phrase is useful for balanced explanations.","zh":"這個短語適合用於平衡解釋。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":7},{"front":"lie in the way","meaning":"在於……的方式","examples":[{"en":"The problem lies in the way teenagers are taught.","zh":"問題在於青少年受教的方式。"},{"en":"Lie in the way means the cause is found in the method or manner of doing something.","zh":"lie in the way 指原因存在於做某事的方法或方式之中。"},{"en":"A child’s fear of maths may lie in the way the subject was first taught.","zh":"孩子害怕數學，可能在於最初教授該科的方式。"},{"en":"If a problem lies in teaching methods, changing exams alone may not solve it.","zh":"如果問題在於教學方法，只改考試未必能解決它。"},{"en":"This phrase points to the source of a problem.","zh":"這個短語指出問題來源。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":7},{"front":"be taught in school","meaning":"在學校受教","examples":[{"en":"Teenagers are taught in school to prepare closely for exams.","zh":"青少年在學校受教，要仔細準備考試。"},{"en":"To be taught in school means to receive instruction as part of formal education.","zh":"be taught in school 指作為正式教育的一部分接受教導。"},{"en":"Children are taught in school how to read, count, and work with others.","zh":"孩子在學校受教，學習如何閱讀、計算和與他人合作。"},{"en":"What students are taught in school shapes their habits and confidence later.","zh":"學生在學校受教的內容會塑造他們日後的習慣和信心。"},{"en":"This phrase focuses on formal classroom learning.","zh":"這個短語聚焦正式課堂學習。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":7},{"front":"be prepped assiduously for","meaning":"被悉心訓練應付……","examples":[{"en":"Students are prepped assiduously for exams.","zh":"學生被悉心訓練應付考試。"},{"en":"To be prepped assiduously for something means to be trained carefully and intensively for it.","zh":"be prepped assiduously for something 指被仔細而密集地訓練以應付某事。"},{"en":"A debating team may be prepped assiduously for a final competition.","zh":"辯論隊可能被悉心訓練應付決賽。"},{"en":"Intensive preparation can improve scores but may narrow learning if used too much.","zh":"密集準備可以提高分數，但若過度使用，可能令學習變窄。"},{"en":"This phrase suggests diligent but possibly over-focused training.","zh":"這個短語暗示勤奮但可能過分集中的訓練。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":7},{"front":"at the expense of","meaning":"以犧牲……為代價","examples":[{"en":"Exam preparation may come at the expense of broader understanding.","zh":"考試準備可能以犧牲更廣泛理解為代價。"},{"en":"At the expense of something means gaining one thing while sacrificing another.","zh":"at the expense of something 指得到一件事但犧牲另一件事。"},{"en":"A student may get high marks at the expense of sleep and health.","zh":"學生可能以犧牲睡眠和健康為代價取得高分。"},{"en":"If schools focus only on exam drills, deeper learning may suffer.","zh":"如果學校只集中考試操練，較深入學習可能受損。"},{"en":"This phrase clearly shows a trade-off.","zh":"這個短語清楚顯示取捨。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":7},{"front":"broader understanding","meaning":"更廣泛的理解","examples":[{"en":"Students may lack broader understanding because of exam-focused teaching.","zh":"由於教學過分集中考試，學生可能缺乏更廣泛的理解。"},{"en":"Broader understanding means deeper and wider knowledge beyond narrow facts or exam answers.","zh":"broader understanding 指超越狹窄事實或考試答案的更深入、更廣泛知識。"},{"en":"Reading novels can give students broader understanding of people’s emotions and choices.","zh":"閱讀小說可以讓學生更廣泛地理解人的情感和選擇。"},{"en":"Without broader understanding, students may pass tests but struggle with real problems.","zh":"沒有更廣泛的理解，學生可能通過測驗，卻難以處理真實問題。"},{"en":"This phrase values meaning, context, and connection.","zh":"這個短語重視意思、背景和連繫。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":7},{"front":"academic failings","meaning":"學業不足","examples":[{"en":"The survey noted students’ academic failings.","zh":"調查指出學生的學業不足。"},{"en":"Academic failings are weaknesses in study skills, knowledge, writing, reasoning, or preparation.","zh":"academic failings 指學習技能、知識、寫作、推理或準備方面的弱點。"},{"en":"Poor grammar and weak essay structure can be academic failings.","zh":"文法差和文章結構薄弱都可以是學業不足。"},{"en":"If academic failings are identified early, students can receive support before they fall behind.","zh":"如果學業不足及早被識別，學生可以在落後前得到支援。"},{"en":"This phrase is formal and often used in education reports.","zh":"這個短語較正式，常用於教育報告。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":7},{"front":"the survey did find","meaning":"調查確實發現","examples":[{"en":"The survey did find that students had some strengths.","zh":"調查確實發現學生有一些優點。"},{"en":"The survey did find means the survey genuinely discovered something, often despite earlier criticism.","zh":"survey did find 指調查確實發現某事，常用於與早前批評形成平衡。"},{"en":"The report criticised homework habits, but it did find that students were motivated.","zh":"報告批評功課習慣，但確實發現學生有動機。"},{"en":"This structure adds balance by emphasising a positive or contrasting finding.","zh":"這個結構透過強調正面或對比發現來增加平衡。"},{"en":"The word did gives extra emphasis to the result.","zh":"did 這個字對結果加強語氣。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":8},{"front":"tech-savvy","meaning":"熟悉科技的","examples":[{"en":"Modern students are more tech-savvy than their predecessors.","zh":"現代學生比上一代學生更熟悉科技。"},{"en":"Tech-savvy means comfortable and skilled in using technology.","zh":"tech-savvy 指使用科技時熟練且自在。"},{"en":"A tech-savvy student can create slides, search online, and fix simple computer problems.","zh":"熟悉科技的學生可以製作簡報、網上搜尋並處理簡單電腦問題。"},{"en":"Being tech-savvy can help with study and work, but it does not replace writing skill.","zh":"熟悉科技有助學習和工作，但不能取代寫作能力。"},{"en":"This phrase is informal and common in modern education and business.","zh":"這個短語較非正式，常見於現代教育和商業。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":8},{"front":"oral communication","meaning":"口語溝通","examples":[{"en":"Students are better at oral communication than earlier generations.","zh":"學生比早期世代更擅長口語溝通。"},{"en":"Oral communication means expressing ideas clearly by speaking.","zh":"oral communication 指透過說話清楚表達想法。"},{"en":"Group discussions, presentations, interviews, and phone calls all require oral communication.","zh":"小組討論、匯報、面試和電話都需要口語溝通。"},{"en":"Good speaking skills can help students explain ideas even if their writing is weaker.","zh":"良好說話能力可以幫助學生解釋想法，即使寫作較弱。"},{"en":"This phrase contrasts spoken communication with written communication.","zh":"這個短語把口頭溝通與書面溝通作對比。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":8},{"front":"predecessors","meaning":"前輩；上一代學生","examples":[{"en":"Students today may be more tech-savvy than their predecessors.","zh":"今天的學生可能比上一代學生更熟悉科技。"},{"en":"Predecessors are people who came before in the same role, position, or group.","zh":"predecessors 指在同一角色、位置或群體中較早出現的人。"},{"en":"A new principal may learn from the mistakes of her predecessors.","zh":"新校長可能從前任的錯誤中學習。"},{"en":"Comparing students with their predecessors shows how skills and habits change over time.","zh":"把學生與上一代比較，可以顯示技能和習慣如何隨時間改變。"},{"en":"This word is formal and useful for historical comparison.","zh":"這個詞較正式，適合歷史比較。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":8},{"front":"nevertheless","meaning":"然而","examples":[{"en":"Nevertheless, concerns about the university system are deepening.","zh":"然而，對大學制度的擔憂正在加深。"},{"en":"Nevertheless means despite what has just been said.","zh":"nevertheless 指儘管剛才所說如此。"},{"en":"The new library is popular; nevertheless, many students still need quiet study rooms.","zh":"新圖書館很受歡迎；然而，許多學生仍需要安靜自修室。"},{"en":"This word introduces a contrast that does not cancel the previous point.","zh":"這個詞引出對比，但不否定上一點。"},{"en":"It is more formal than but.","zh":"它比 but 更正式。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":8},{"front":"concerns about the state of","meaning":"對……狀況的擔憂","examples":[{"en":"Concerns about the state of Britain’s university system are deepening.","zh":"對英國大學制度狀況的擔憂正在加深。"},{"en":"Concerns about the state of something are worries about its current condition.","zh":"concerns about the state of something 指對某事目前情況的擔心。"},{"en":"Parents may have concerns about the state of school toilets if they are dirty and broken.","zh":"如果學校洗手間骯髒又破損，家長可能對其狀況感到擔憂。"},{"en":"Such concerns grow when problems appear repeatedly rather than once.","zh":"當問題反覆出現而不是只出現一次，這類擔憂會增加。"},{"en":"This phrase is useful for discussing public systems and institutions.","zh":"討論公共系統和機構時，這個短語很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":8},{"front":"the university system","meaning":"大學制度","examples":[{"en":"Britain’s university system faces major funding changes.","zh":"英國大學制度面臨重大資金變化。"},{"en":"The university system means the network of universities, rules, funding, admissions, teaching, and qualifications in a country.","zh":"university system 指一個國家的大學網絡、規則、資金、招生、教學和資格制度。"},{"en":"A university system can expand if more places and funding are provided.","zh":"如果提供更多學額和資金，大學制度可以擴展。"},{"en":"Problems in the system may affect students, staff, employers, and taxpayers.","zh":"制度中的問題可能影響學生、教職員、僱主和納稅人。"},{"en":"This phrase refers to higher education as a whole, not one university only.","zh":"這個短語指整個高等教育，而不只是一間大學。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":8},{"front":"deepen","meaning":"加深","examples":[{"en":"Concerns about the university system are deepening this year.","zh":"對大學制度的擔憂今年正在加深。"},{"en":"To deepen means to become stronger, more serious, or more intense.","zh":"deepen 指變得更強、更嚴重或更深。"},{"en":"A disagreement may deepen if both sides refuse to listen.","zh":"如果雙方拒絕聆聽，分歧可能加深。"},{"en":"When concerns deepen, people are more likely to demand action.","zh":"當擔憂加深，人們更可能要求行動。"},{"en":"This verb is often used for worries, crises, understanding, or relationships.","zh":"這個動詞常用於擔憂、危機、理解或關係。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":8},{"front":"funding","meaning":"資金；撥款","examples":[{"en":"University funding faces major changes.","zh":"大學資金面臨重大變化。"},{"en":"Funding means money provided for an organisation, project, or service.","zh":"funding 指提供給機構、項目或服務的金錢。"},{"en":"A school needs funding to hire teachers and buy books.","zh":"學校需要資金聘請老師和購買書本。"},{"en":"If funding falls, services may be cut or fees may rise.","zh":"如果資金下降，服務可能被削減或費用可能上升。"},{"en":"This word is central to education, healthcare, charities, and public services.","zh":"這個詞是教育、醫療、慈善和公共服務的核心。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":8},{"front":"face a shake-up","meaning":"面臨重大改革","examples":[{"en":"The university funding system faces a major shake-up.","zh":"大學資金制度面臨重大改革。"},{"en":"To face a shake-up means to be about to experience major change or reform.","zh":"face a shake-up 指即將經歷重大變化或改革。"},{"en":"A company may face a shake-up when a new manager closes weak departments.","zh":"當新經理關閉薄弱部門，公司可能面臨重大改革。"},{"en":"Shake-ups can solve old problems but also create uncertainty.","zh":"改革可以解決舊問題，但也會造成不確定性。"},{"en":"This phrase is common in news about institutions and policy.","zh":"這個短語常見於關於機構和政策的新聞。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":8},{"front":"one of the biggest shake-ups in decades","meaning":"數十年來最大的改革之一","examples":[{"en":"The funding change is one of the biggest shake-ups in decades.","zh":"這次資金變化是數十年來最大的改革之一。"},{"en":"One of the biggest shake-ups in decades means one of the most important reforms for many years.","zh":"one of the biggest shake-ups in decades 指多年來最重要的改革之一。"},{"en":"A new exam system could be one of the biggest shake-ups in decades for schools.","zh":"新考試制度可能是學校數十年來最大的改革之一。"},{"en":"Such a change may affect rules, costs, behaviour, and public expectations.","zh":"這種變化可能影響規則、成本、行為和公眾期望。"},{"en":"This phrase emphasises historical importance.","zh":"這個短語強調歷史重要性。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":8},{"front":"follow the lead of","meaning":"效法","examples":[{"en":"Britain is following the lead of countries such as America and Australia.","zh":"英國正在效法美國和澳洲等國家。"},{"en":"To follow the lead of someone means to copy or be guided by their example.","zh":"follow the lead of someone 指模仿或以某人的例子為指引。"},{"en":"A school may follow the lead of another school that has successfully reduced bullying.","zh":"學校可能效法另一間成功減少欺凌的學校。"},{"en":"Following another country’s lead can save time, but local conditions may differ.","zh":"效法另一個國家可以節省時間，但本地情況可能不同。"},{"en":"This phrase shows influence through example.","zh":"這個短語顯示透過榜樣產生影響。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":9},{"front":"among others","meaning":"除其他之外","examples":[{"en":"America, Australia and New Zealand, among others, have influenced the policy.","zh":"美國、澳洲和新西蘭等國，除其他之外，影響了這項政策。"},{"en":"Among others means including these examples, but not only these.","zh":"among others 指包括這些例子，但不只這些。"},{"en":"The school offers football, drama, debate, and music, among others.","zh":"學校提供足球、戲劇、辯論和音樂等活動。"},{"en":"This phrase avoids listing every example while showing the list is incomplete.","zh":"這個短語避免列出每個例子，同時顯示列表並不完整。"},{"en":"It is useful in formal writing when several examples are enough.","zh":"在正式寫作中，當幾個例子已足夠時，它很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":9},{"front":"introduce a tuition fee","meaning":"引入學費","examples":[{"en":"Universities will introduce a new annual tuition fee.","zh":"大學將引入新的每年學費。"},{"en":"To introduce a tuition fee means to start charging students money for study.","zh":"introduce a tuition fee 指開始向學生收取學習費用。"},{"en":"A training centre may introduce a tuition fee after free trial classes end.","zh":"培訓中心可能在免費試堂結束後引入學費。"},{"en":"Introducing fees can raise money but may discourage some learners.","zh":"引入學費可以籌集資金，但可能令一些學習者卻步。"},{"en":"This phrase is common in education finance and policy.","zh":"這個短語常見於教育財務和政策。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":9},{"front":"annual tuition fee","meaning":"每年學費","examples":[{"en":"Students will pay a new annual tuition fee.","zh":"學生將支付新的每年學費。"},{"en":"An annual tuition fee is the amount paid each year for study.","zh":"annual tuition fee 指每年為學習支付的金額。"},{"en":"A university may list its annual tuition fee on its admissions website.","zh":"大學可能在招生網站列出每年學費。"},{"en":"High annual fees can affect family budgets and student loan decisions.","zh":"高昂每年學費可以影響家庭預算和學生貸款決定。"},{"en":"This phrase focuses on yearly education cost.","zh":"這個短語聚焦年度教育成本。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":9},{"front":"nearly triple","meaning":"接近三倍","examples":[{"en":"The new fee is nearly triple the current fee.","zh":"新費用接近現時費用的三倍。"},{"en":"Nearly triple means almost three times as much or as many.","zh":"nearly triple 指幾乎是三倍。"},{"en":"If a bus fare goes from $5 to nearly $15, it has nearly tripled.","zh":"如果巴士票價由5元升至接近15元，就是接近三倍。"},{"en":"A near tripling of cost can make people rethink whether they can afford something.","zh":"成本接近三倍可以令人重新考慮是否負擔得起。"},{"en":"This phrase describes a very large increase.","zh":"這個短語描述非常大幅的增加。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":9},{"front":"the current fee","meaning":"現時的費用","examples":[{"en":"The new charge is almost three times the current fee.","zh":"新收費幾乎是現時費用的三倍。"},{"en":"The current fee is the amount charged now, before any change.","zh":"current fee 指改變前現在收取的金額。"},{"en":"A gym may compare its new monthly price with the current fee.","zh":"健身室可能把新的月費與現時費用比較。"},{"en":"Knowing the current fee helps people understand how big an increase is.","zh":"知道現時費用有助人們理解加幅有多大。"},{"en":"This phrase gives the baseline for comparison.","zh":"這個短語提供比較基準。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":9},{"front":"be brought in by","meaning":"由……引入","examples":[{"en":"The charge was brought in by the government.","zh":"這項收費由政府引入。"},{"en":"To be brought in by someone means to be introduced or put into effect by them.","zh":"be brought in by someone 指由某人或某機構引入或實施。"},{"en":"A new school rule may be brought in by the principal after safety concerns.","zh":"校長可能因安全擔憂而引入新校規。"},{"en":"When a policy is brought in, people must adjust to the new system.","zh":"當政策被引入，人們必須適應新制度。"},{"en":"This phrase is common in policy and law.","zh":"這個短語常見於政策和法律。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":9},{"front":"drum up cash for","meaning":"為……籌集資金","examples":[{"en":"The government wants to drum up cash for universities.","zh":"政府想為大學籌集資金。"},{"en":"To drum up cash for something means to raise or gather money for it, often with effort.","zh":"drum up cash for something 指努力為某事籌集或募集金錢。"},{"en":"A charity may drum up cash for a new community kitchen.","zh":"慈善機構可能為新的社區廚房籌集資金。"},{"en":"If public funding is short, institutions may look for ways to drum up cash.","zh":"如果公共資金不足，機構可能尋找籌集資金的方法。"},{"en":"This phrase is informal and suggests active fundraising.","zh":"這個短語較非正式，暗示積極籌款。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":9},{"front":"a perennially underfunded sector","meaning":"長期資金不足的界別","examples":[{"en":"Higher education is described as a perennially underfunded sector.","zh":"高等教育被描述為長期資金不足的界別。"},{"en":"A perennially underfunded sector is an area of work that has lacked enough money for many years.","zh":"perennially underfunded sector 指多年來一直缺乏足夠資金的工作領域。"},{"en":"Public libraries may become a perennially underfunded sector if budgets are cut every year.","zh":"如果每年削減預算，公共圖書館可能成為長期資金不足的界別。"},{"en":"Long-term underfunding can damage quality, staff morale, and services.","zh":"長期資金不足會損害質素、員工士氣和服務。"},{"en":"This phrase stresses that the funding problem is chronic, not temporary.","zh":"這個短語強調資金問題是長期性的，而不是暫時性的。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":9},{"front":"be expected to","meaning":"預計會","examples":[{"en":"The new fee is expected to increase graduate debt.","zh":"新學費預計會增加畢業生債務。"},{"en":"Be expected to means people think something will probably happen.","zh":"be expected to 指人們認為某事很可能發生。"},{"en":"The new bus route is expected to reduce traffic near the school.","zh":"新巴士路線預計會減少學校附近交通。"},{"en":"Expectations are predictions, so they may still need evidence later.","zh":"預期是預測，因此之後仍可能需要證據。"},{"en":"This phrase is common in reports and forecasts.","zh":"這個短語常見於報告和預測。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":9},{"front":"saddle graduates with debts","meaning":"令畢業生背負債務","examples":[{"en":"The policy may saddle graduates with large debts.","zh":"這項政策可能令畢業生背負大量債務。"},{"en":"To saddle someone with debts means to burden them with money they must repay.","zh":"saddle someone with debts 指令某人背負必須償還的金錢負擔。"},{"en":"A family can be saddled with debt after unexpected medical bills.","zh":"突如其來的醫療帳單可能令家庭背負債務。"},{"en":"Large debts can delay buying a home, starting a business, or saving money.","zh":"大額債務可以延遲買樓、創業或儲蓄。"},{"en":"This phrase is negative and stresses burden.","zh":"這個短語帶負面意思，強調負擔。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":9},{"front":"debts of at least","meaning":"至少……的債務","examples":[{"en":"Graduates may leave university with debts of at least £12,000.","zh":"畢業生離開大學時可能背負至少12,000英鎊的債務。"},{"en":"Debts of at least a certain amount means debts equal to or greater than that amount.","zh":"debts of at least a certain amount 指等於或高於某金額的債務。"},{"en":"A student with debts of at least $50,000 may need years to repay them.","zh":"背負至少50,000美元債務的學生可能需要多年償還。"},{"en":"The phrase gives a minimum figure, so the real amount may be higher.","zh":"這個短語提供最低數字，因此真實金額可能更高。"},{"en":"It is useful when discussing financial burden.","zh":"討論財務負擔時，它很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":10},{"front":"National Union of Students","meaning":"全國學生聯會","examples":[{"en":"The National Union of Students warned about the effect of debt.","zh":"全國學生聯會警告債務的影響。"},{"en":"The National Union of Students is an organisation representing student interests.","zh":"National Union of Students 指代表學生利益的組織。"},{"en":"A student union may speak publicly when fees or housing costs rise.","zh":"當學費或住宿成本上升，學生會可能公開發聲。"},{"en":"Student organisations can influence debate by showing how policies affect young people.","zh":"學生組織可以透過展示政策如何影響年輕人來影響討論。"},{"en":"This phrase names a specific representative body.","zh":"這個短語指一個特定代表機構。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":10},{"front":"make someone think twice about","meaning":"令某人重新考慮","examples":[{"en":"Debt may make students think twice about whether to study.","zh":"債務可能令學生重新考慮是否升學。"},{"en":"To make someone think twice about something means to make them reconsider it carefully.","zh":"make someone think twice about something 指令某人仔細重新考慮某事。"},{"en":"High travel costs may make a family think twice about taking a holiday.","zh":"高昂旅費可能令家庭重新考慮是否去旅行。"},{"en":"When risks or costs rise, people often think twice before making a decision.","zh":"當風險或成本上升，人們常在決定前再三考慮。"},{"en":"This phrase suggests hesitation after new concerns appear.","zh":"這個短語暗示新擔憂出現後的猶豫。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":10},{"front":"official figures","meaning":"官方數字","examples":[{"en":"Official figures show that university applications fell this year.","zh":"官方數字顯示今年大學申請下降。"},{"en":"Official figures are numbers released by a government or recognised organisation.","zh":"official figures 指由政府或受認可機構發布的數字。"},{"en":"Official figures on unemployment can influence economic policy.","zh":"關於失業的官方數字可以影響經濟政策。"},{"en":"Because they come from official sources, such figures are often used in public debate.","zh":"因為它們來自官方來源，這類數字常用於公共討論。"},{"en":"This phrase introduces numerical evidence.","zh":"這個短語引入數字證據。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":10},{"front":"university applicants","meaning":"大學申請人","examples":[{"en":"The number of university applicants fell this year.","zh":"大學申請人數今年下降。"},{"en":"University applicants are people who apply to enter university.","zh":"university applicants 指申請入讀大學的人。"},{"en":"Applicants may submit grades, personal statements, and references.","zh":"申請人可能提交成績、個人陳述和推薦信。"},{"en":"If applicant numbers fall, universities may worry about demand and income.","zh":"如果申請人數下降，大學可能擔心需求和收入。"},{"en":"This phrase focuses on people before admission.","zh":"這個短語聚焦入學前的人。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":10},{"front":"fall for the first time in six years","meaning":"六年來首次下降","examples":[{"en":"University applications fell for the first time in six years.","zh":"大學申請六年來首次下降。"},{"en":"To fall for the first time in six years means to decrease after six years without a decrease.","zh":"fall for the first time in six years 指經過六年沒有下降後首次減少。"},{"en":"A shop’s sales may fall for the first time in six years after a new competitor opens.","zh":"新競爭者開業後，商店銷售可能六年來首次下降。"},{"en":"Such a fall attracts attention because it breaks a long pattern.","zh":"這種下降會吸引注意，因為它打破長期模式。"},{"en":"This phrase is useful when a decline is historically unusual.","zh":"當下降在歷史上不尋常時，這個短語很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":10},{"front":"by 3.4 per cent","meaning":"下降百分之三點四","examples":[{"en":"Applications fell by 3.4 per cent.","zh":"申請數字下降百分之三點四。"},{"en":"By 3.4 per cent means the change was 3.4 per cent of the original amount.","zh":"by 3.4 per cent 指變化幅度為原本數量的百分之三點四。"},{"en":"If a class of 1,000 applicants falls by 3.4 per cent, there are 34 fewer applicants.","zh":"如果1,000名申請人下降百分之三點四，就少了34名申請人。"},{"en":"Percentages help compare changes across groups of different sizes.","zh":"百分比有助比較不同規模群體的變化。"},{"en":"This phrase gives the exact size of a change.","zh":"這個短語提供變化的確切幅度。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":10},{"front":"say all along that","meaning":"一直表示","examples":[{"en":"The student union has said all along that the policy will deter students.","zh":"學生聯會一直表示這項政策會阻嚇學生。"},{"en":"To say all along that something is true means to have said it consistently from the beginning.","zh":"say all along that something is true 指從一開始就持續這樣說。"},{"en":"A teacher may say all along that regular revision is better than last-minute study.","zh":"老師可能一直表示定期溫習比臨急抱佛腳好。"},{"en":"If later evidence supports the claim, the speaker may feel vindicated.","zh":"如果後來證據支持該說法，說話者可能覺得自己得到證明。"},{"en":"This phrase stresses long-standing consistency.","zh":"這個短語強調長期一致。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":10},{"front":"deter prospective students from","meaning":"阻嚇準學生去……","examples":[{"en":"Higher fees may deter prospective students from going to university.","zh":"更高學費可能阻嚇準學生入讀大學。"},{"en":"To deter prospective students from doing something means to discourage future applicants from taking that action.","zh":"deter prospective students from doing something 指阻止未來申請者採取某行動。"},{"en":"Expensive transport may deter students from joining an after-school course.","zh":"昂貴交通費可能阻嚇學生參加課後課程。"},{"en":"If young people fear debt, they may decide not to apply.","zh":"如果年輕人害怕債務，他們可能決定不申請。"},{"en":"This phrase focuses on preventing action through fear, cost, or difficulty.","zh":"這個短語聚焦透過恐懼、成本或困難阻止行動。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":10},{"front":"prospective students","meaning":"準學生","examples":[{"en":"Prospective students may worry about future debt.","zh":"準學生可能擔心未來債務。"},{"en":"Prospective students are people who may apply to or enter a school, college, or university in the future.","zh":"prospective students 指未來可能申請或入讀學校、學院或大學的人。"},{"en":"Universities hold open days for prospective students and their families.","zh":"大學為準學生及其家庭舉辦開放日。"},{"en":"If prospective students are worried about costs, application numbers may fall.","zh":"如果準學生擔心成本，申請人數可能下降。"},{"en":"This phrase refers to potential future students, not current students.","zh":"這個短語指潛在未來學生，而不是現時學生。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":10},{"front":"be attributable to","meaning":"可歸因於","examples":[{"en":"The fall in applications is attributed to the threat of debt.","zh":"申請下降被歸因於債務威脅。"},{"en":"To be attributable to something means to be caused by or explained by it.","zh":"be attributable to something 指由某事造成或可由某事解釋。"},{"en":"A drop in shop sales may be attributable to bad weather and road closures.","zh":"商店銷售下降可能可歸因於惡劣天氣和封路。"},{"en":"This phrase is formal and often used when explaining causes.","zh":"這個短語較正式，常用於解釋原因。"},{"en":"It suggests a likely cause, though evidence should still be examined.","zh":"它暗示一個可能原因，但仍應檢視證據。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":10},{"front":"the threat of debt","meaning":"債務威脅","examples":[{"en":"The threat of debt may discourage young people from applying.","zh":"債務威脅可能令年輕人不敢申請。"},{"en":"The threat of debt means the possibility of owing a large amount of money in the future.","zh":"threat of debt 指未來可能欠下大量金錢的可能性。"},{"en":"The threat of debt may make a student choose a cheaper college.","zh":"債務威脅可能令學生選擇較便宜的學院。"},{"en":"Fear of future repayment can affect decisions before the debt even exists.","zh":"對未來還款的恐懼可以在債務尚未出現前影響決定。"},{"en":"This phrase describes financial risk as a discouraging force.","zh":"這個短語把財務風險描述成阻嚇力量。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":11},{"front":"for the government","meaning":"對政府來說","examples":[{"en":"For the government, the fall in applicants is slightly awkward.","zh":"對政府來說，申請人數下降有點尷尬。"},{"en":"For the government means from the government’s point of view or in relation to its interests.","zh":"for the government 指從政府角度或就其利益而言。"},{"en":"For the school, falling attendance is a warning sign.","zh":"對學校來說，出席率下降是一個警號。"},{"en":"This phrase helps show how one situation affects a particular group.","zh":"這個短語幫助顯示某情況如何影響特定群體。"},{"en":"It is useful when different people may view the same event differently.","zh":"當不同人可能以不同方式看同一事件時，它很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":11},{"front":"a fall in applicants","meaning":"申請人數下降","examples":[{"en":"A fall in applicants creates a problem for the government.","zh":"申請人數下降為政府造成問題。"},{"en":"A fall in applicants means a decrease in the number of people applying.","zh":"fall in applicants 指申請人數減少。"},{"en":"A training course may close if there is a sharp fall in applicants.","zh":"如果申請人數大幅下降，培訓課程可能關閉。"},{"en":"Fewer applicants can reduce income and make targets harder to reach.","zh":"申請人較少可以減少收入，並令目標更難達成。"},{"en":"This phrase is common in education, recruitment, and admissions.","zh":"這個短語常見於教育、招聘和招生。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":11},{"front":"slightly awkward","meaning":"有點尷尬","examples":[{"en":"The decline in applications is slightly awkward for the government.","zh":"申請下降對政府來說有點尷尬。"},{"en":"Slightly awkward means somewhat embarrassing, inconvenient, or uncomfortable.","zh":"slightly awkward 指有點令人尷尬、不方便或不舒服。"},{"en":"It is slightly awkward when a teacher praises a project and then realises it was copied.","zh":"老師稱讚一個項目後才發現它是抄襲的，情況會有點尷尬。"},{"en":"A situation becomes awkward when it conflicts with what someone has publicly promised.","zh":"當情況與某人公開承諾相衝突，它就會變得尷尬。"},{"en":"This phrase softens criticism while still noting a problem.","zh":"這個短語在指出問題時語氣較溫和。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":11},{"front":"Labour administration","meaning":"工黨政府","examples":[{"en":"Tony Blair’s Labour administration set a target for higher education.","zh":"Tony Blair 的工黨政府為高等教育設定目標。"},{"en":"Labour administration refers to the government led by the Labour Party.","zh":"Labour administration 指由工黨領導的政府。"},{"en":"A new administration may change education, tax, or housing policy.","zh":"新政府可能改變教育、稅務或房屋政策。"},{"en":"When an administration sets a target, departments are expected to work toward it.","zh":"當政府設定目標，各部門被期望朝它努力。"},{"en":"This phrase is political and refers to a period of government.","zh":"這個短語屬政治用語，指一段執政時期。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":11},{"front":"commit itself to","meaning":"承諾去","examples":[{"en":"The government has committed itself to increasing university participation.","zh":"政府已承諾增加大學參與率。"},{"en":"To commit itself to something means to make a firm promise or obligation to do it.","zh":"commit itself to something 指作出堅定承諾或承擔去做某事。"},{"en":"A school may commit itself to reducing bullying within one year.","zh":"學校可能承諾在一年內減少欺凌。"},{"en":"Once an organisation commits itself publicly, failure becomes politically or socially costly.","zh":"一旦機構公開承諾，失敗就會帶來政治或社會成本。"},{"en":"This phrase is formal and often used for policy promises.","zh":"這個短語較正式，常用於政策承諾。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":11},{"front":"boost the number of","meaning":"增加……的數目","examples":[{"en":"The government wants to boost the number of young people in higher education.","zh":"政府想增加接受高等教育的年輕人數目。"},{"en":"To boost the number of something means to increase it.","zh":"boost the number of something 指增加某物數量。"},{"en":"A school may boost the number of library users by holding reading competitions.","zh":"學校可以透過閱讀比賽增加圖書館使用者數目。"},{"en":"Increasing numbers can help access, but quality must still be protected.","zh":"增加數量可以改善機會，但仍必須保護質素。"},{"en":"This phrase is common in policy, business, and education.","zh":"這個短語常見於政策、商業和教育。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":11},{"front":"by 2010","meaning":"到2010年","examples":[{"en":"The government wants to reach its target by 2010.","zh":"政府希望到2010年達成目標。"},{"en":"By 2010 means no later than the year 2010.","zh":"by 2010 指不遲於2010年。"},{"en":"A school may aim to renovate all classrooms by 2030.","zh":"學校可能目標到2030年翻新所有課室。"},{"en":"A deadline makes a target more concrete and easier to measure.","zh":"截止年份令目標更具體，也較容易衡量。"},{"en":"This phrase sets a time limit for achievement.","zh":"這個短語為達成目標設定時限。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":11},{"front":"prove tricky","meaning":"可能會變得棘手","examples":[{"en":"The target might prove tricky if students are deterred by debt.","zh":"如果學生被債務嚇退，該目標可能會變得棘手。"},{"en":"To prove tricky means to turn out to be difficult or complicated.","zh":"prove tricky 指結果變得困難或複雜。"},{"en":"Organising a school trip may prove tricky if transport and weather are uncertain.","zh":"如果交通和天氣不確定，籌辦學校旅行可能會變得棘手。"},{"en":"A target can prove tricky when several problems appear at once.","zh":"當幾個問題同時出現，目標可能變得棘手。"},{"en":"This phrase is slightly informal and suggests practical difficulty.","zh":"這個短語略帶非正式語氣，表示實際困難。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":11},{"front":"be deterred by","meaning":"被……嚇退","examples":[{"en":"Teenagers and parents may be deterred by the cost of study.","zh":"青少年和家長可能被就讀成本嚇退。"},{"en":"To be deterred by something means to be discouraged or stopped by it.","zh":"be deterred by something 指被某事阻嚇或阻止。"},{"en":"A student may be deterred by a long journey to school.","zh":"學生可能被漫長上學路程嚇退。"},{"en":"High costs can deter people even when they value the opportunity.","zh":"高成本可以阻嚇人們，即使他們重視該機會。"},{"en":"This phrase shows how obstacles reduce willingness to act.","zh":"這個短語顯示障礙如何降低行動意願。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":11},{"front":"burgeoning cost of study","meaning":"不斷上升的就讀成本","examples":[{"en":"The burgeoning cost of study may discourage university applicants.","zh":"不斷上升的就讀成本可能令大學申請人卻步。"},{"en":"Burgeoning cost of study means the rapidly growing expense of education.","zh":"burgeoning cost of study 指快速增長的教育開支。"},{"en":"A family may worry when the burgeoning cost of tutoring uses more of its monthly income.","zh":"當補習成本不斷上升並佔用更多家庭月收入，家庭可能擔心。"},{"en":"Rising costs can make students think carefully before applying.","zh":"成本上升可以令學生申請前仔細思考。"},{"en":"This phrase stresses that the cost is increasing quickly.","zh":"這個短語強調成本正在快速增加。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":11},{"front":"an expert at","meaning":"……的專家","examples":[{"en":"Alison Wolf is an expert at King’s College London.","zh":"Alison Wolf 是倫敦國王學院的專家。"},{"en":"An expert at an institution is a specialist who works or teaches there.","zh":"expert at an institution 指在某機構工作或任教的專家。"},{"en":"An expert at a hospital may explain a new treatment to the public.","zh":"醫院的專家可能向公眾解釋新療法。"},{"en":"Experts are often quoted because they have training and experience in the field.","zh":"專家常被引用，因為他們在該領域有訓練和經驗。"},{"en":"This phrase identifies both expertise and workplace.","zh":"這個短語同時指出專業知識和工作地點。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":12},{"front":"author of","meaning":"……的作者","examples":[{"en":"Alison Wolf is the author of a book called Does Education Matter?","zh":"Alison Wolf 是一本名為 Does Education Matter? 的書的作者。"},{"en":"Author of means the person who wrote a particular book, article, or work.","zh":"author of 指某本書、文章或作品的寫作者。"},{"en":"A teacher may introduce the author of a novel before students read it.","zh":"老師可能在學生閱讀小說前介紹其作者。"},{"en":"Knowing the author can help readers understand the perspective behind a text.","zh":"知道作者有助讀者理解文本背後的觀點。"},{"en":"This phrase identifies responsibility for a written work.","zh":"這個短語指出作品的創作責任。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":12},{"front":"concede that","meaning":"承認","examples":[{"en":"Alison Wolf concedes that the added fees might make students think twice.","zh":"Alison Wolf 承認額外學費可能令學生重新考慮。"},{"en":"To concede that something is true means to admit it, often despite disagreeing with a larger argument.","zh":"concede that something is true 指承認某事是真的，常是在不同意較大論點的情況下。"},{"en":"A manager may concede that the new system is confusing but still defend its benefits.","zh":"經理可能承認新系統令人困惑，但仍為其好處辯護。"},{"en":"Conceding one point can make an argument sound fairer.","zh":"承認一點可以令論點聽起來更公平。"},{"en":"This phrase is useful when acknowledging a weakness or opposing point.","zh":"當承認弱點或相反觀點時，這個短語很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":12},{"front":"added fees","meaning":"額外學費","examples":[{"en":"The added fees may make students think twice.","zh":"額外學費可能令學生重新考慮。"},{"en":"Added fees are extra charges placed on top of existing costs.","zh":"added fees 指在現有費用以外增加的額外收費。"},{"en":"A gym may lose members if added fees are charged for lockers and classes.","zh":"如果健身室對儲物櫃和課堂收取額外費用，可能流失會員。"},{"en":"Extra fees can change decisions because the total cost becomes less affordable.","zh":"額外費用會改變決定，因為總成本變得較難負擔。"},{"en":"This phrase focuses on new or additional financial burden.","zh":"這個短語聚焦新的或額外的財務負擔。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":12},{"front":"price increase","meaning":"加價；費用上升","examples":[{"en":"Wolf says the price increase will not turn students away.","zh":"Wolf 說費用上升不會令學生卻步。"},{"en":"A price increase is a rise in the amount people must pay.","zh":"price increase 指人們必須支付的金額上升。"},{"en":"A price increase in bus fares may affect students who travel daily.","zh":"巴士票價上升可能影響每天通勤的學生。"},{"en":"Price increases can reduce demand if people feel the product is no longer worth it.","zh":"如果人們覺得產品不再值得，價格上升可以降低需求。"},{"en":"This phrase is common in business, shopping, and public services.","zh":"這個短語常見於商業、購物和公共服務。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":12},{"front":"turn someone away","meaning":"使某人卻步","examples":[{"en":"The fees will not turn students away from university, according to Wolf.","zh":"根據 Wolf 的說法，這些學費不會使學生對大學卻步。"},{"en":"To turn someone away from something means to discourage them from choosing it.","zh":"turn someone away from something 指阻嚇某人選擇某事。"},{"en":"Long waiting times may turn patients away from a clinic.","zh":"漫長等候時間可能令病人對診所卻步。"},{"en":"If the expected benefit remains high, people may not be turned away by higher costs.","zh":"如果預期好處仍很高，人們未必會因成本較高而卻步。"},{"en":"This phrase focuses on discouragement or loss of interest.","zh":"這個短語聚焦阻嚇或失去興趣。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":12},{"front":"become as important as","meaning":"變得像……一樣重要","examples":[{"en":"A degree has become extremely important in society.","zh":"學位在社會中已變得極其重要。"},{"en":"To become as important as something means to gain similar importance or status.","zh":"become as important as something 指獲得相近的重要性或地位。"},{"en":"Digital skills have become as important as handwriting in many workplaces.","zh":"在許多工作場所，數碼技能已變得像手寫一樣重要。"},{"en":"When a qualification becomes important, people may pursue it even if it is costly.","zh":"當資格變得重要，人們即使成本高也可能追求它。"},{"en":"This phrase helps describe changing social value.","zh":"這個短語有助描述社會價值的變化。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":12},{"front":"all the evidence is that","meaning":"所有證據都顯示","examples":[{"en":"Wolf says all the evidence is that fees will not have a major impact.","zh":"Wolf 說所有證據都顯示學費不會有重大影響。"},{"en":"All the evidence is that means the available information strongly supports a particular conclusion.","zh":"all the evidence is that 指現有資料強烈支持某個結論。"},{"en":"All the evidence is that regular reading improves vocabulary over time.","zh":"所有證據都顯示定期閱讀會隨時間改善詞彙。"},{"en":"This phrase is strong because it claims the evidence points in one direction.","zh":"這個短語語氣強，因為它聲稱證據指向同一方向。"},{"en":"It is useful in argument, but the evidence should be trustworthy.","zh":"它適用於論證，但證據應可靠。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":12},{"front":"have an impact","meaning":"有影響","examples":[{"en":"Fees may not have a strong impact on demand for degrees.","zh":"學費可能不會對學位需求有強烈影響。"},{"en":"To have an impact means to affect something.","zh":"have an impact 指對某事產生影響。"},{"en":"A good teacher can have an impact on a student’s confidence.","zh":"好老師可以對學生信心有影響。"},{"en":"If a policy has little impact, it may not change behaviour much.","zh":"如果政策影響很小，它可能不會大幅改變行為。"},{"en":"This phrase is useful for discussing effects and consequences.","zh":"討論效果和後果時，這個短語很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":12},{"front":"economically worthwhile","meaning":"在經濟上值得","examples":[{"en":"It is still economically worthwhile to get a degree.","zh":"取得學位在經濟上仍然值得。"},{"en":"Economically worthwhile means financially worth doing because the benefits are greater than the costs.","zh":"economically worthwhile 指因好處大於成本而在財務上值得做。"},{"en":"A training course is economically worthwhile if it helps a worker earn more later.","zh":"如果培訓課程幫助工人日後賺更多，它就在經濟上值得。"},{"en":"Even if study is expensive, it may be worthwhile if lifetime earnings rise enough.","zh":"即使讀書昂貴，如果一生收入增加足夠多，它仍可能值得。"},{"en":"This phrase evaluates a decision through money and long-term return.","zh":"這個短語透過金錢和長遠回報評估決定。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":12},{"front":"get a degree","meaning":"取得學位","examples":[{"en":"Many students believe it is still worthwhile to get a degree.","zh":"許多學生相信取得學位仍然值得。"},{"en":"To get a degree means to complete university study and receive the qualification.","zh":"get a degree 指完成大學學習並取得資格。"},{"en":"A student may get a degree in engineering, education, business, or art.","zh":"學生可能取得工程、教育、商業或藝術學位。"},{"en":"Getting a degree can open doors, but it also requires effort and money.","zh":"取得學位可以打開機會，但也需要努力和金錢。"},{"en":"This phrase is common and less formal than obtain a university degree.","zh":"這個短語常用，沒有 obtain a university degree 那麼正式。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":12},{"front":"estimates suggest","meaning":"估計顯示","examples":[{"en":"Estimates suggest that graduates earn much more over a lifetime.","zh":"估計顯示畢業生一生中收入高得多。"},{"en":"Estimates suggest means approximate calculations indicate something is likely.","zh":"estimates suggest 指大約計算顯示某事可能成立。"},{"en":"Estimates suggest that a new bus route could serve thousands of passengers each week.","zh":"估計顯示新巴士路線每週可服務數千名乘客。"},{"en":"Estimates are useful when exact future numbers are not yet known.","zh":"當確切未來數字尚未知時，估計很有用。"},{"en":"This phrase is common in reports and forecasts.","zh":"這個短語常見於報告和預測。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":13},{"front":"over a lifetime","meaning":"一生中","examples":[{"en":"Graduates may earn much more over a lifetime than non-graduates.","zh":"大學畢業生一生中可能比非大學畢業生賺得多得多。"},{"en":"Over a lifetime means across a person’s whole life or working life.","zh":"over a lifetime 指在一個人的整個人生或工作人生中。"},{"en":"Small savings can become large over a lifetime if they are made regularly.","zh":"如果定期儲蓄，小額存款一生中可以變成大筆金錢。"},{"en":"Looking over a lifetime can make short-term costs seem smaller.","zh":"從一生中來看，短期成本可能顯得較小。"},{"en":"This phrase is useful for long-term comparison.","zh":"這個短語適合長遠比較。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":13},{"front":"non-graduates","meaning":"非大學畢業生","examples":[{"en":"Graduates may earn more than non-graduates.","zh":"大學畢業生可能比非大學畢業生賺得更多。"},{"en":"Non-graduates are people who have not completed a university degree.","zh":"non-graduates 指沒有完成大學學位的人。"},{"en":"Some non-graduates succeed through apprenticeships, business experience, or skilled trades.","zh":"有些非大學畢業生透過學徒訓練、商業經驗或技術行業取得成功。"},{"en":"Comparing graduates and non-graduates helps people discuss the value of a degree.","zh":"比較畢業生與非畢業生有助人們討論學位價值。"},{"en":"This word describes education status, not intelligence or worth.","zh":"這個詞描述教育狀況，而不是智力或價值。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":13},{"front":"be worth it","meaning":"是值得的","examples":[{"en":"A little debt may be worth it in the long run.","zh":"少量債務長遠而言可能是值得的。"},{"en":"To be worth it means the benefit is enough to justify the cost, effort, or risk.","zh":"be worth it 指好處足以合理化成本、努力或風險。"},{"en":"A difficult course may be worth it if it helps a student enter her chosen career.","zh":"如果困難課程幫助學生進入理想職業，它可能是值得的。"},{"en":"Something is not worth it if the cost is high and the benefit is small.","zh":"如果成本高而好處小，某事就不值得。"},{"en":"This phrase is common in everyday decision-making.","zh":"這個短語常見於日常決策。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":13},{"front":"in the long run","meaning":"長遠而言","examples":[{"en":"Wolf argues that a degree remains worthwhile in the long run.","zh":"Wolf 認為學位長遠而言仍然值得。"},{"en":"In the long run means over a long period, not immediately.","zh":"in the long run 指經過長時間後，而不是即時。"},{"en":"Regular exercise may be tiring now but helpful in the long run.","zh":"定期運動現在可能令人疲倦，但長遠而言有幫助。"},{"en":"Long-term benefits can make short-term costs easier to accept.","zh":"長遠好處可以令短期成本較容易接受。"},{"en":"This phrase is useful when comparing present sacrifice with future gain.","zh":"比較當前犧牲和未來收穫時，這個短語很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":13},{"front":"higher education minister","meaning":"高等教育部長","examples":[{"en":"Bill Rammell was the higher education minister.","zh":"Bill Rammell 是高等教育部長。"},{"en":"A higher education minister is a government official responsible for university and college policy.","zh":"higher education minister 指負責大學和學院政策的政府官員。"},{"en":"A higher education minister may speak about tuition fees, student loans, and university targets.","zh":"高等教育部長可能談論學費、學生貸款和大學目標。"},{"en":"The minister’s views matter because they can explain or defend government policy.","zh":"部長的看法重要，因為它們可以解釋或捍衛政府政策。"},{"en":"This phrase identifies a political role in education.","zh":"這個短語指出教育中的政治職位。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":13},{"front":"target of fifty per cent enrolment","meaning":"百分之五十入學率目標","examples":[{"en":"The target of fifty per cent enrolment is defended by the minister.","zh":"百分之五十入學率目標由該部長辯護。"},{"en":"A target of fifty per cent enrolment means a goal that half of the relevant group should enter higher education.","zh":"target of fifty per cent enrolment 指相關群體中一半人應進入高等教育的目標。"},{"en":"A school may set a target of ninety per cent attendance to improve learning.","zh":"學校可能設定百分之九十出席率目標，以改善學習。"},{"en":"A numerical target can guide policy but may also create pressure to focus on numbers.","zh":"數字目標可以引導政策，但也可能造成過分聚焦數量的壓力。"},{"en":"This phrase combines a percentage goal with education participation.","zh":"這個短語結合百分比目標和教育參與。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":13},{"front":"an economic and social necessity","meaning":"經濟及社會需要","examples":[{"en":"The minister calls the enrolment target an economic and social necessity.","zh":"部長稱該入學率目標是經濟及社會需要。"},{"en":"An economic and social necessity is something considered essential for both the economy and society.","zh":"economic and social necessity 指被認為對經濟和社會都必不可少的事物。"},{"en":"Affordable childcare can be an economic and social necessity because it helps parents work and children develop.","zh":"可負擔幼兒照顧可以是經濟及社會需要，因為它幫助父母工作和孩子發展。"},{"en":"Calling something a necessity makes the argument stronger than calling it a preference.","zh":"把某事稱為需要，比稱為偏好更能加強論點。"},{"en":"This phrase is used to justify major public policy.","zh":"這個短語用於支持重大公共政策。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":13},{"front":"point out that","meaning":"指出","examples":[{"en":"Bill Rammell points out that many graduate jobs will be created.","zh":"Bill Rammell 指出許多畢業生職位將被創造出來。"},{"en":"To point out that something is true means to mention it clearly as an important fact.","zh":"point out that something is true 指清楚提到某事是一項重要事實。"},{"en":"A teacher may point out that neat handwriting helps examiners read answers.","zh":"老師可能指出整潔字跡有助考官閱讀答案。"},{"en":"People point out facts to support an argument or correct misunderstanding.","zh":"人們指出事實以支持論點或糾正誤解。"},{"en":"This phrase is useful in explanations and debates.","zh":"這個短語適合用於解釋和辯論。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":13},{"front":"an estimated","meaning":"估計","examples":[{"en":"An estimated 6.8 million graduate jobs will have been created.","zh":"估計將會創造680萬個畢業生職位。"},{"en":"An estimated amount is an approximate number based on calculation or prediction.","zh":"estimated amount 指基於計算或預測的大約數字。"},{"en":"An estimated 500 students attended the school fair.","zh":"估計有500名學生參加學校嘉年華。"},{"en":"Estimated figures are useful when exact counts are unavailable.","zh":"當確切數字不可得時，估計數字很有用。"},{"en":"This phrase tells readers the number is approximate, not exact.","zh":"這個短語告訴讀者數字是大約，而不是精確。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":13},{"front":"graduate jobs","meaning":"要求大學學歷的職位","examples":[{"en":"Graduate jobs require workers with university education.","zh":"畢業生職位要求具大學教育的員工。"},{"en":"Graduate jobs are positions usually designed for people who have completed a degree.","zh":"graduate jobs 指通常為已完成學位的人而設的職位。"},{"en":"Banks, consultancies, schools, and technology firms may offer graduate jobs.","zh":"銀行、顧問公司、學校和科技公司可能提供畢業生職位。"},{"en":"If graduate jobs increase, demand for university-educated workers may also rise.","zh":"如果畢業生職位增加，對受過大學教育勞動人口的需求也可能上升。"},{"en":"This phrase connects degrees with employment opportunities.","zh":"這個短語把學位與就業機會連接起來。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":13},{"front":"be created","meaning":"被創造出來","examples":[{"en":"Millions of graduate jobs will be created by 2012.","zh":"到2012年，數百萬個畢業生職位將被創造出來。"},{"en":"To be created means to be made, produced, or brought into existence.","zh":"be created 指被製造、產生或使其存在。"},{"en":"New teaching posts may be created when a school opens more classes.","zh":"當學校開設更多班級，可能會創造新的教學職位。"},{"en":"Job creation can reduce unemployment if workers have the right skills.","zh":"如果工人具備合適技能，創造職位可以降低失業。"},{"en":"This phrase is common in economic and policy writing.","zh":"這個短語常見於經濟和政策寫作。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":14},{"front":"require increasing numbers of","meaning":"需要越來越多……","examples":[{"en":"New jobs will require increasing numbers of university-educated workers.","zh":"新職位將需要越來越多受過大學教育的勞動人口。"},{"en":"Require increasing numbers of means need more and more of something over time.","zh":"require increasing numbers of 指隨時間需要越來越多某事物。"},{"en":"Hospitals may require increasing numbers of nurses as the population ages.","zh":"隨着人口老化，醫院可能需要越來越多護士。"},{"en":"Rising demand can force schools and training centres to expand.","zh":"需求上升可以迫使學校和培訓中心擴展。"},{"en":"This phrase links growth in need with future planning.","zh":"這個短語把需求增長與未來規劃連接起來。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":14},{"front":"university-educated workers","meaning":"受過大學教育的勞動人口","examples":[{"en":"The economy needs more university-educated workers.","zh":"經濟需要更多受過大學教育的勞動人口。"},{"en":"University-educated workers are people who have received education at university level.","zh":"university-educated workers 指接受過大學程度教育的工作者。"},{"en":"Research labs and engineering firms often employ university-educated workers.","zh":"研究實驗室和工程公司常聘請受過大學教育的員工。"},{"en":"If the economy needs such workers, universities may be asked to produce more graduates.","zh":"如果經濟需要這類工人，大學可能被要求培養更多畢業生。"},{"en":"This phrase focuses on education level in the workforce.","zh":"這個短語聚焦勞動人口的教育程度。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":14},{"front":"it is therefore crucial that","meaning":"因此至關重要的是","examples":[{"en":"It is therefore crucial that Britain produces enough skilled graduates.","zh":"因此至關重要的是，英國要培養足夠的高技能畢業生。"},{"en":"It is therefore crucial that means because of the previous reason, it is extremely important that something happen.","zh":"it is therefore crucial that 指由於前述原因，某事發生極其重要。"},{"en":"The exam is next week; it is therefore crucial that students revise regularly now.","zh":"考試在下星期；因此至關重要的是學生現在定期溫習。"},{"en":"This phrase clearly links evidence to an urgent conclusion.","zh":"這個短語清楚把證據與迫切結論連接起來。"},{"en":"It is formal and common in policy argument.","zh":"它較正式，常見於政策論證。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":14},{"front":"produce sufficient numbers of","meaning":"培養足夠數量的……","examples":[{"en":"Universities must produce sufficient numbers of employable graduates.","zh":"大學必須培養足夠數量的具就業能力畢業生。"},{"en":"To produce sufficient numbers of something means to create enough of it to meet demand.","zh":"produce sufficient numbers of something 指創造或培養足夠數量以滿足需求。"},{"en":"A hospital must train sufficient numbers of nurses before opening a new ward.","zh":"醫院在開設新病房前必須培訓足夠數量的護士。"},{"en":"If supply is insufficient, important posts may remain empty.","zh":"如果供應不足，重要職位可能空缺。"},{"en":"This phrase is common in workforce and education planning.","zh":"這個短語常見於勞動力和教育規劃。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":14},{"front":"highly skilled","meaning":"高技能的","examples":[{"en":"The economy needs highly skilled graduates.","zh":"經濟需要高技能畢業生。"},{"en":"Highly skilled means having advanced ability, training, or expertise.","zh":"highly skilled 指具備進階能力、訓練或專業知識。"},{"en":"A highly skilled technician can repair complex medical equipment.","zh":"高技能技術員可以維修複雜醫療設備。"},{"en":"Skilled workers are important when jobs require judgement, accuracy, and specialised knowledge.","zh":"當工作需要判斷、準確性和專門知識，技術工人很重要。"},{"en":"This phrase describes a high level of practical or professional ability.","zh":"這個短語描述高水平的實用或專業能力。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":14},{"front":"employable graduates","meaning":"具就業能力的畢業生","examples":[{"en":"Universities need to produce employable graduates.","zh":"大學需要培養具就業能力的畢業生。"},{"en":"Employable graduates are graduates with skills, attitudes, and knowledge that employers value.","zh":"employable graduates 指具備僱主重視的技能、態度和知識的畢業生。"},{"en":"An employable graduate can communicate clearly, solve problems, and learn quickly at work.","zh":"具就業能力的畢業生能清楚溝通、解決問題並在工作中快速學習。"},{"en":"If graduates are not employable, employers may criticise university training.","zh":"如果畢業生不具就業能力，僱主可能批評大學訓練。"},{"en":"This phrase focuses on readiness for work.","zh":"這個短語聚焦工作準備度。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":14},{"front":"fill those posts","meaning":"填補那些職位","examples":[{"en":"Graduates are needed to fill those posts.","zh":"需要畢業生來填補那些職位。"},{"en":"To fill those posts means to take up or occupy the available jobs.","zh":"fill those posts 指擔任或佔用可用職位。"},{"en":"A hospital may need trained nurses to fill posts in a new department.","zh":"醫院可能需要受訓護士填補新部門的職位。"},{"en":"If there are not enough qualified people, posts may remain vacant.","zh":"如果合資格人員不足，職位可能保持空缺。"},{"en":"This phrase connects workers with job vacancies.","zh":"這個短語把工作者與職位空缺連接起來。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":14},{"front":"industrialised countries","meaning":"工業化國家","examples":[{"en":"Most industrialised countries have targets to expand university numbers.","zh":"大多數工業化國家都有擴大大學人數的目標。"},{"en":"Industrialised countries are countries with developed industries, advanced infrastructure, and modern economies.","zh":"industrialised countries 指具備發達工業、先進基建和現代經濟的國家。"},{"en":"Industrialised countries often need workers with technical, scientific, and professional skills.","zh":"工業化國家常需要具技術、科學和專業技能的工人。"},{"en":"Their education systems may expand to meet changing labour-market needs.","zh":"它們的教育制度可能擴展，以滿足變化中的勞動市場需要。"},{"en":"This phrase is common in economic and social comparison.","zh":"這個短語常見於經濟和社會比較。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":14},{"front":"expand university numbers","meaning":"擴大大學收生人數","examples":[{"en":"Many countries want to expand university numbers.","zh":"許多國家想擴大大學收生人數。"},{"en":"To expand university numbers means to increase the number of people entering or studying at university.","zh":"expand university numbers 指增加入讀或就讀大學的人數。"},{"en":"A government may expand university numbers by funding new places and campuses.","zh":"政府可以透過資助新學額和校園來擴大大學人數。"},{"en":"Expansion can widen access but may challenge teaching quality.","zh":"擴展可以擴大入學機會，但也可能挑戰教學質素。"},{"en":"This phrase is common in higher-education policy.","zh":"這個短語常見於高等教育政策。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":14},{"front":"the government’s target","meaning":"政府目標","examples":[{"en":"Wolf thinks the government’s target is unreasonable.","zh":"Wolf 認為政府目標不合理。"},{"en":"The government’s target is the goal officially set by the government.","zh":"government’s target 指政府正式設定的目標。"},{"en":"A government’s target for reducing pollution may guide factory rules and transport policy.","zh":"政府減少污染的目標可能引導工廠規則和交通政策。"},{"en":"Targets can motivate action, but unrealistic targets may create poor decisions.","zh":"目標可以推動行動，但不切實際的目標可能造成差劣決定。"},{"en":"This phrase refers to an official policy aim.","zh":"這個短語指官方政策目標。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":14},{"front":"be nuts","meaning":"荒謬；瘋狂","examples":[{"en":"Wolf says the fifty per cent target is nuts.","zh":"Wolf 說百分之五十目標是荒謬的。"},{"en":"Be nuts means be crazy, foolish, or unreasonable.","zh":"be nuts 指瘋狂、愚蠢或不合理。"},{"en":"It would be nuts to spend all your savings on a phone you do not need.","zh":"把所有積蓄花在一部不需要的手機上會很荒謬。"},{"en":"This phrase is informal and should be avoided in formal academic writing.","zh":"這個短語較非正式，正式學術寫作中應避免。"},{"en":"It expresses strong criticism in a blunt way.","zh":"它以直接方式表達強烈批評。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":15},{"front":"no evidence that","meaning":"沒有證據顯示","examples":[{"en":"Wolf argues that there is no evidence that the target supports growth.","zh":"Wolf 主張沒有證據顯示該目標支持增長。"},{"en":"No evidence that means there is no proof or reliable information showing something is true.","zh":"no evidence that 指沒有證明或可靠資料顯示某事是真的。"},{"en":"A teacher should not punish a student if there is no evidence that cheating occurred.","zh":"如果沒有證據顯示作弊發生，老師不應懲罰學生。"},{"en":"Without evidence, a claim remains only an assumption.","zh":"沒有證據，說法就仍然只是假設。"},{"en":"This phrase is important in argument and critical thinking.","zh":"這個短語在論證和批判思考中很重要。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":15},{"front":"economic growth","meaning":"經濟增長","examples":[{"en":"She argues that the target is not essential for economic growth.","zh":"她主張該目標對經濟增長並非必要。"},{"en":"Economic growth means an increase in a country’s production, income, or economic activity.","zh":"economic growth 指一個國家的生產、收入或經濟活動增加。"},{"en":"New industries can support economic growth by creating jobs and exports.","zh":"新產業可以透過創造工作和出口來支持經濟增長。"},{"en":"Growth may slow if workers lack the skills that employers need.","zh":"如果工人缺乏僱主需要的技能，增長可能放慢。"},{"en":"This phrase is central to discussions of national policy.","zh":"這個短語是國家政策討論的核心。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":15},{"front":"contend that","meaning":"主張；聲稱","examples":[{"en":"Wolf contends that the policy is not important for economic growth.","zh":"Wolf 主張這項政策對經濟增長並不重要。"},{"en":"To contend that means to argue or claim something, especially in a debate.","zh":"contend that 指主張或聲稱某事，尤其是在辯論中。"},{"en":"Some teachers contend that homework quality matters more than homework quantity.","zh":"有些老師主張功課質素比功課數量更重要。"},{"en":"This phrase signals a position that others may challenge.","zh":"這個短語表示一個可能被他人挑戰的立場。"},{"en":"It is formal and common in essays and articles.","zh":"它較正式，常見於文章和論文。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":15},{"front":"the richest country in Europe","meaning":"歐洲最富有的國家","examples":[{"en":"Switzerland is described as the richest country in Europe.","zh":"瑞士被描述為歐洲最富有的國家。"},{"en":"The richest country in Europe means the European country with the highest wealth by a given measure.","zh":"richest country in Europe 指按某種衡量方式計算，歐洲最富有的國家。"},{"en":"A country may be rich because of high wages, strong industries, and stable institutions.","zh":"一個國家可能因高工資、強大產業和穩定制度而富有。"},{"en":"The phrase is used to compare national wealth across countries.","zh":"這個短語用來比較不同國家的國家財富。"},{"en":"In arguments, such examples may challenge simple links between degrees and prosperity.","zh":"在論證中，這類例子可能挑戰學位與繁榮之間的簡單連繫。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":15},{"front":"one of the lowest numbers of","meaning":"……數目最低之一","examples":[{"en":"Switzerland has one of the lowest numbers of graduates.","zh":"瑞士的畢業生數目是最低之一。"},{"en":"One of the lowest numbers of something means among the smallest quantities in a group.","zh":"one of the lowest numbers of something 指在一個群體中數量屬於最少之一。"},{"en":"A village may have one of the lowest numbers of cars because most people walk.","zh":"村莊可能因多數人步行而汽車數目最低之一。"},{"en":"This phrase is used when comparing many places or groups.","zh":"比較許多地方或群體時，會使用這個短語。"},{"en":"It suggests a low ranking, but not necessarily the very lowest.","zh":"它表示排名很低，但不一定是最低。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":15},{"front":"a market-based society","meaning":"市場主導社會","examples":[{"en":"A market-based society can decide what kind of workers it needs.","zh":"市場主導社會可以決定需要甚麼類型的工人。"},{"en":"A market-based society is one where supply, demand, prices, and employers strongly shape decisions.","zh":"market-based society 指由供求、價格和僱主強烈塑造決定的社會。"},{"en":"In a market-based society, wages may rise when skilled workers are scarce.","zh":"在市場主導社會中，當技術工人短缺，工資可能上升。"},{"en":"Supporters say markets can signal what training people should choose.","zh":"支持者認為市場可以發出訊號，告訴人們應選擇甚麼訓練。"},{"en":"This phrase contrasts market decisions with government planning.","zh":"這個短語把市場決定與政府規劃作對比。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":15},{"front":"be capable of","meaning":"有能力","examples":[{"en":"A market-based society is capable of working out its labour needs.","zh":"市場主導社會有能力弄清楚自身勞動需求。"},{"en":"To be capable of doing something means to have the ability to do it.","zh":"be capable of doing something 指有能力做某事。"},{"en":"A strong student is capable of improving quickly with clear practice.","zh":"能力強的學生在清楚練習下有能力快速進步。"},{"en":"If a system is capable of solving a problem itself, government control may be less necessary.","zh":"如果系統有能力自行解決問題，政府控制可能較不必要。"},{"en":"This phrase describes ability or capacity.","zh":"這個短語描述能力或容量。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":15},{"front":"work out","meaning":"弄清楚；計算出","examples":[{"en":"The market can work out what kind of workers are needed.","zh":"市場可以弄清楚需要甚麼類型的工人。"},{"en":"To work out something means to calculate, understand, or figure it out.","zh":"work out something 指計算、理解或找出某事。"},{"en":"A student can work out the answer by checking the grammar and meaning.","zh":"學生可以透過檢查文法和意思計算出答案。"},{"en":"Markets may work out labour needs through wages, vacancies, and employer demand.","zh":"市場可能透過工資、職位空缺和僱主需求弄清勞動需要。"},{"en":"This phrase is common and practical.","zh":"這個短語常用且實用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":15},{"front":"government-mandated quotas","meaning":"政府規定的配額","examples":[{"en":"Wolf questions the value of government-mandated quotas.","zh":"Wolf 質疑政府規定配額的價值。"},{"en":"Government-mandated quotas are numerical targets required by the government.","zh":"government-mandated quotas 指由政府要求的數字目標或配額。"},{"en":"A government-mandated quota may require a certain number of training places.","zh":"政府規定的配額可能要求一定數量的培訓名額。"},{"en":"Quotas can expand access, but they may also encourage institutions to chase numbers.","zh":"配額可以擴大機會，但也可能鼓勵機構追逐數字。"},{"en":"This phrase is formal and often used critically.","zh":"這個短語較正式，常帶批評意味。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":15},{"front":"end up encouraging","meaning":"最終鼓勵","examples":[{"en":"Quotas may end up encouraging the wrong people to attend university.","zh":"配額可能最終鼓勵不合適的人入讀大學。"},{"en":"To end up encouraging something means to finally or unintentionally encourage it as a result.","zh":"end up encouraging something 指結果或無意中鼓勵某事。"},{"en":"Too many rewards may end up encouraging students to study only for prizes.","zh":"太多獎勵可能最終鼓勵學生只為獎品而學習。"},{"en":"Policies can have unexpected effects if incentives are poorly designed.","zh":"如果誘因設計不良，政策可能產生意外效果。"},{"en":"This phrase often points to unintended consequences.","zh":"這個短語常指出非預期後果。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":15},{"front":"might do better","meaning":"可能會有更好發展","examples":[{"en":"Some people might do better pursuing vocational routes.","zh":"有些人追求職業技能路向可能會有更好發展。"},{"en":"Might do better means may achieve a better result by choosing a different path.","zh":"might do better 指選擇不同道路可能取得更好結果。"},{"en":"A student who dislikes lectures might do better in hands-on training.","zh":"不喜歡講課的學生可能在實作訓練中有更好發展。"},{"en":"Choosing the right route can matter more than following the most prestigious route.","zh":"選擇合適道路可能比跟隨最有名望的道路更重要。"},{"en":"This phrase is careful because it suggests possibility, not certainty.","zh":"這個短語較謹慎，表示可能性而非確定性。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":16},{"front":"pursue vocational endeavours","meaning":"追求職業技能路向","examples":[{"en":"Some young people might do better pursuing vocational endeavours.","zh":"有些年輕人追求職業技能路向可能會有更好發展。"},{"en":"To pursue vocational endeavours means to follow training or work connected with practical job skills.","zh":"pursue vocational endeavours 指追求與實用工作技能有關的訓練或工作。"},{"en":"A teenager may pursue vocational training in plumbing, cooking, design, or childcare.","zh":"青少年可能追求水喉、烹飪、設計或幼兒照顧的職業訓練。"},{"en":"Vocational routes can lead to stable careers without a traditional university degree.","zh":"職業路向可以帶來穩定職業，而不需要傳統大學學位。"},{"en":"This phrase contrasts practical career training with academic study.","zh":"這個短語把實用職業訓練與學術學習作對比。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":16},{"front":"make more sense for society","meaning":"對社會更合理","examples":[{"en":"Wolf says it would make more sense for society if some people did not attend university.","zh":"Wolf 說如果有些人不入讀大學，對社會會更合理。"},{"en":"To make more sense for society means to be more reasonable or beneficial for society as a whole.","zh":"make more sense for society 指對整個社會而言更合理或更有益。"},{"en":"It may make more sense for society to train more nurses than to produce unused degrees.","zh":"對社會而言，培訓更多護士可能比產生用不上的學位更合理。"},{"en":"A choice that helps individuals may not always be the best choice for the whole community.","zh":"對個人有幫助的選擇未必總是對整個社區最佳。"},{"en":"This phrase evaluates policy from a social perspective.","zh":"這個短語從社會角度評估政策。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":16},{"front":"for the wrong reasons","meaning":"出於錯誤原因","examples":[{"en":"Some people may go to university for the wrong reasons.","zh":"有些人可能出於錯誤原因入讀大學。"},{"en":"For the wrong reasons means because of motives that are unsuitable, mistaken, or unhelpful.","zh":"for the wrong reasons 指因不合適、錯誤或無幫助的動機。"},{"en":"A student may choose medicine for the wrong reasons if she only wants family approval.","zh":"如果學生只為得到家人認可而選讀醫科，她可能是出於錯誤原因。"},{"en":"Choosing a path for the wrong reasons can lead to regret and poor performance.","zh":"出於錯誤原因選擇道路，可能導致後悔和表現差。"},{"en":"This phrase focuses on motivation behind a decision.","zh":"這個短語聚焦決定背後的動機。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":16},{"front":"as long as","meaning":"只要","examples":[{"en":"Demand for degrees will remain high as long as employers use them for screening.","zh":"只要僱主把學位用作篩選工具，對學位的需求就會維持高企。"},{"en":"As long as means provided that or while a condition continues.","zh":"as long as 指只要某條件持續。"},{"en":"Students can borrow books as long as they return them on time.","zh":"只要學生準時還書，就可以借書。"},{"en":"If the condition changes, the result may also change.","zh":"如果條件改變，結果也可能改變。"},{"en":"This phrase introduces a condition that keeps something true.","zh":"這個短語引出令某事保持成立的條件。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":16},{"front":"use degrees as a filter device","meaning":"把學位用作篩選工具","examples":[{"en":"Employers use degrees as a filter device for screening candidates.","zh":"僱主把學位用作篩選候選人的工具。"},{"en":"To use degrees as a filter device means to use university qualifications to reduce or sort applicants.","zh":"use degrees as a filter device 指用大學資格來減少或分類申請人。"},{"en":"A company may reject applicants without degrees before reading their full CVs.","zh":"公司可能在閱讀完整履歷前先拒絕沒有學位的申請人。"},{"en":"This practice saves time but may exclude skilled people without university education.","zh":"這種做法節省時間，但可能排除沒有大學教育的有技能人士。"},{"en":"This phrase criticises using degrees as a simple sorting tool.","zh":"這個短語批評把學位當作簡單分類工具。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":16},{"front":"screen candidates","meaning":"篩選候選人","examples":[{"en":"Employers use degrees to screen candidates.","zh":"僱主使用學位來篩選候選人。"},{"en":"To screen candidates means to examine applicants and remove those who do not meet requirements.","zh":"screen candidates 指審查申請人，並剔除不符合要求的人。"},{"en":"A school may screen candidates for a teaching job by checking qualifications and references.","zh":"學校可能透過檢查資格和推薦信來篩選教師職位候選人。"},{"en":"Screening helps manage large numbers of applications, but it can miss hidden talent.","zh":"篩選有助處理大量申請，但可能錯過隱藏人才。"},{"en":"This phrase is common in recruitment.","zh":"這個短語常見於招聘。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":16},{"front":"demand for degrees","meaning":"對學位的需求","examples":[{"en":"Demand for degrees will remain high.","zh":"對學位的需求將維持高企。"},{"en":"Demand for degrees means the desire or need for university qualifications.","zh":"demand for degrees 指對大學資格的渴望或需要。"},{"en":"Demand for degrees may rise if employers require them for most office jobs.","zh":"如果僱主要求大多數辦公室工作都要有學位，對學位的需求可能上升。"},{"en":"High demand can encourage more young people to apply to university.","zh":"高需求可以鼓勵更多年輕人申請大學。"},{"en":"This phrase links education choices with labour-market expectations.","zh":"這個短語把教育選擇與勞動市場期望連接起來。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":16},{"front":"remain high","meaning":"維持高企","examples":[{"en":"Demand for degrees will remain high.","zh":"對學位的需求將維持高企。"},{"en":"Remain high means continue to be at a high level.","zh":"remain high 指繼續處於高水平。"},{"en":"Housing costs may remain high if supply stays low.","zh":"如果供應持續偏低，住房成本可能維持高企。"},{"en":"When demand remains high, prices or competition may also stay high.","zh":"當需求維持高企，價格或競爭也可能保持高水平。"},{"en":"This phrase describes a continuing condition.","zh":"這個短語描述持續狀態。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":16},{"front":"which paragraph best fits","meaning":"哪一段最適合","examples":[{"en":"Students decide which paragraph best fits each heading.","zh":"學生判斷哪一段最適合每個標題。"},{"en":"Which paragraph best fits asks students to choose the paragraph whose main idea matches the heading.","zh":"which paragraph best fits 指要求學生選出主旨與標題相配的段落。"},{"en":"In a reading test, students should read the whole paragraph before deciding which heading fits best.","zh":"在閱讀測驗中，學生應先讀完整段，再判斷哪個標題最適合。"},{"en":"A paragraph may contain the same word as a heading but still not be the best match.","zh":"段落可能包含與標題相同的字眼，但仍未必是最佳配對。"},{"en":"This phrase is common in paragraph-heading tasks.","zh":"這個短語常見於段落標題配對題。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":16},{"front":"the following headings","meaning":"以下標題","examples":[{"en":"The following headings summarise parts of the text.","zh":"以下標題概括文章部分內容。"},{"en":"The following headings means the titles listed after the instruction.","zh":"following headings 指指示之後列出的標題。"},{"en":"Students should compare the following headings with each paragraph’s main idea.","zh":"學生應把以下標題與每段主旨比較。"},{"en":"Headings usually summarise broad meaning, not small details.","zh":"標題通常概括大意，而不是小細節。"},{"en":"This phrase is common in reading-test instructions.","zh":"這個短語常見於閱讀測驗指示。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":16},{"front":"higher fees","meaning":"更高學費","examples":[{"en":"Higher fees may affect students’ decisions about university.","zh":"更高學費可能影響學生對大學的決定。"},{"en":"Higher fees are increased charges that students or families must pay.","zh":"higher fees 指學生或家庭必須支付的費用上升。"},{"en":"Higher fees for a course may make some learners choose cheaper alternatives.","zh":"課程學費更高可能令一些學習者選擇較便宜替代方案。"},{"en":"When fees rise, students may worry more about loans and future debt.","zh":"當學費上升，學生可能更擔心貸款和未來債務。"},{"en":"This phrase is often linked to access and affordability.","zh":"這個短語常與入學機會和可負擔性有關。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":17},{"front":"many employers unhappy","meaning":"許多僱主不滿","examples":[{"en":"Many employers are unhappy with the quality of graduates.","zh":"許多僱主對畢業生質素不滿。"},{"en":"Many employers unhappy means a large number of employers feel dissatisfied.","zh":"many employers unhappy 指大量僱主感到不滿。"},{"en":"Many employers may be unhappy if applicants cannot write clear emails.","zh":"如果申請人不能寫清楚電郵，許多僱主可能不滿。"},{"en":"Employer dissatisfaction can pressure universities to improve practical skills.","zh":"僱主不滿可以向大學施壓，要求改善實用技能。"},{"en":"This phrase summarises a complaint from the job market.","zh":"這個短語概括就業市場的投訴。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":17},{"front":"government’s push for numbers","meaning":"政府推動增加人數","examples":[{"en":"The government’s push for numbers aims to expand higher education.","zh":"政府推動增加人數旨在擴展高等教育。"},{"en":"The government’s push for numbers means a strong official effort to increase participation or enrolment.","zh":"government’s push for numbers 指官方強力推動增加參與率或收生人數。"},{"en":"A government may push for numbers by setting targets and funding new places.","zh":"政府可能透過設定目標和資助新學額來推動人數增加。"},{"en":"Focusing on numbers can widen access but may raise concerns about quality.","zh":"聚焦數字可以擴大機會，但也可能引起質素憂慮。"},{"en":"This phrase is useful when policy emphasises quantity.","zh":"當政策強調數量時，這個短語很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":17},{"front":"paying is worth it","meaning":"付費是值得的","examples":[{"en":"Some experts argue that paying for a degree is worth it.","zh":"有些專家認為為學位付費是值得的。"},{"en":"Paying is worth it means the benefits justify the money spent.","zh":"paying is worth it 指所得好處足以合理化花費。"},{"en":"Paying for a good language course may be worth it if it helps someone get a better job.","zh":"如果優質語言課幫助某人得到更好工作，付費可能值得。"},{"en":"People accept cost more easily when they expect strong long-term returns.","zh":"當人們預期有強長遠回報，他們較容易接受成本。"},{"en":"This phrase evaluates whether an expense is sensible.","zh":"這個短語評估某項開支是否合理。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":17},{"front":"according to the text","meaning":"根據文章","examples":[{"en":"Students choose the true statements according to the text.","zh":"學生根據文章選出正確陳述。"},{"en":"According to the text means based only on what the passage says.","zh":"according to the text 指只根據文章所說。"},{"en":"In reading exams, students should answer according to the text, not personal belief.","zh":"在閱讀考試中，學生應根據文章作答，而不是個人信念。"},{"en":"This phrase reminds students to look for evidence before choosing.","zh":"這個短語提醒學生選答案前要尋找證據。"},{"en":"It is common in comprehension questions.","zh":"它常見於理解題。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":17},{"front":"the following statements","meaning":"以下陳述","examples":[{"en":"Five of the following statements are true.","zh":"以下陳述中有五項是正確的。"},{"en":"The following statements means the sentences listed after the instruction.","zh":"following statements 指指示之後列出的句子。"},{"en":"Students should read the following statements carefully before checking the passage.","zh":"學生應先仔細閱讀以下陳述，再查閱文章。"},{"en":"Some statements may be partly true but not fully supported.","zh":"有些陳述可能部分正確，但未被完全支持。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":17},{"front":"corresponding letters","meaning":"相應字母","examples":[{"en":"Students write the corresponding letters in the answer boxes.","zh":"學生在答案格中寫上相應字母。"},{"en":"Corresponding letters are the letters that match the correct options.","zh":"corresponding letters 指與正確選項相配的字母。"},{"en":"If the correct answers are A and D, students write the corresponding letters in the boxes.","zh":"如果正確答案是 A 和 D，學生就在格中寫上相應字母。"},{"en":"Writing the wrong letter can lose marks even if the student understands the idea.","zh":"即使學生理解意思，寫錯字母也可能失分。"},{"en":"This phrase focuses on matching answer format.","zh":"這個短語聚焦答案格式配對。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":17},{"front":"in any order","meaning":"以任何次序","examples":[{"en":"The answers may be written in any order.","zh":"答案可以以任何次序書寫。"},{"en":"In any order means the sequence does not matter.","zh":"in any order 指次序不重要。"},{"en":"Students may list the correct letters in any order if the instructions allow it.","zh":"如果指示容許，學生可以以任何次序列出正確字母。"},{"en":"This phrase reduces pressure because students do not need to rank answers.","zh":"這個短語減少壓力，因為學生不需要為答案排序。"},{"en":"It is common in exam instructions with multiple correct answers.","zh":"它常見於有多個正確答案的考試指示。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":17},{"front":"postpone taking courses","meaning":"延遲修讀課程","examples":[{"en":"Certain students have had to postpone taking courses.","zh":"某些學生不得不延遲修讀課程。"},{"en":"To postpone taking courses means to delay starting or continuing courses until later.","zh":"postpone taking courses 指把開始或繼續修讀課程推遲到之後。"},{"en":"A student may postpone taking a course because of illness or financial problems.","zh":"學生可能因疾病或財務問題延遲修讀課程。"},{"en":"Postponement can delay graduation and change study plans.","zh":"延遲可以推遲畢業並改變學習計劃。"},{"en":"This phrase is useful in education and scheduling.","zh":"這個短語適用於教育和時間安排。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":17},{"front":"be better at using technology","meaning":"較擅長使用科技","examples":[{"en":"Students nowadays are better at using technology.","zh":"現今學生較擅長使用科技。"},{"en":"To be better at using technology means to have stronger skills with digital tools and devices.","zh":"be better at using technology 指在數碼工具和裝置方面有較強技能。"},{"en":"A student who can edit videos and manage online files is better at using technology than before.","zh":"能剪片和管理網上檔案的學生，比以前更擅長使用科技。"},{"en":"Technology skills can help with research and presentations, but they do not guarantee deeper understanding.","zh":"科技技能有助研究和匯報，但不保證更深入理解。"},{"en":"This phrase compares digital ability across people or generations.","zh":"這個短語比較不同人或世代的數碼能力。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":17},{"front":"university applications","meaning":"大學申請","examples":[{"en":"The number of university applications has declined this year.","zh":"大學申請數目今年下降。"},{"en":"University applications are formal requests to enter university programmes.","zh":"university applications 指申請入讀大學課程的正式申請。"},{"en":"Students usually send university applications with grades, statements, and references.","zh":"學生通常連同成績、陳述和推薦信提交大學申請。"},{"en":"If applications decline, universities may worry about future enrolment.","zh":"如果申請下降，大學可能擔心未來收生。"},{"en":"This phrase refers to the application process or total number of applications.","zh":"這個短語可指申請流程或申請總數。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":17},{"front":"decline this year","meaning":"今年下降","examples":[{"en":"University applications have declined this year.","zh":"大學申請今年下降。"},{"en":"Decline this year means decrease during the current year being discussed.","zh":"decline this year 指在所討論的今年減少。"},{"en":"Sales may decline this year if prices rise and customers spend less.","zh":"如果價格上升而顧客花費減少，銷售今年可能下降。"},{"en":"A yearly decline can warn organisations to investigate causes quickly.","zh":"年度下降可以提醒機構迅速調查原因。"},{"en":"This phrase gives both direction and time.","zh":"這個短語同時提供方向和時間。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":18},{"front":"agree with","meaning":"同意","examples":[{"en":"One expert may or may not agree with another commentator.","zh":"一位專家可能同意或不同意另一位評論者。"},{"en":"To agree with someone means to share the same opinion or accept their point.","zh":"agree with someone 指持有相同意見或接受對方觀點。"},{"en":"A student may agree with a teacher’s advice after seeing her writing improve.","zh":"學生看到自己寫作進步後，可能同意老師的建議。"},{"en":"Experts may disagree when they value different evidence.","zh":"當專家重視不同證據，他們可能不同意。"},{"en":"This phrase is useful in debate and comparison.","zh":"這個短語適用於辯論和比較。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":18},{"front":"follow Britain’s example","meaning":"效法英國","examples":[{"en":"Another country may follow Britain’s example.","zh":"另一個國家可能效法英國。"},{"en":"To follow Britain’s example means to copy or be influenced by what Britain has done.","zh":"follow Britain’s example 指模仿或受英國做法影響。"},{"en":"A school may follow another school’s example if its reading programme succeeds.","zh":"如果另一間學校的閱讀計劃成功，學校可能效法它。"},{"en":"Following an example can spread a policy, but local needs should still be considered.","zh":"效法例子可以傳播政策，但仍應考慮本地需要。"},{"en":"This phrase shows imitation across countries or institutions.","zh":"這個短語顯示國家或機構之間的模仿。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":18},{"front":"choose the correct answer or answers","meaning":"選出正確答案","examples":[{"en":"Students choose the correct answer or answers from the choices given.","zh":"學生從所提供選項中選出正確答案。"},{"en":"Choose the correct answer or answers means select one or more options that are supported by the text.","zh":"choose the correct answer or answers 指選出一個或多個由文章支持的選項。"},{"en":"In a multiple-answer question, students must check whether more than one choice is right.","zh":"在多答案題中，學生必須檢查是否多於一個選項正確。"},{"en":"Careful reading prevents students from stopping after the first correct option.","zh":"仔細閱讀可以防止學生找到第一個正確選項後就停下。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":18},{"front":"from the choices given","meaning":"從所提供選項中","examples":[{"en":"The answers must come from the choices given.","zh":"答案必須從所提供選項中選出。"},{"en":"From the choices given means only the listed options may be used.","zh":"from the choices given 指只能使用列出的選項。"},{"en":"Students should not invent their own answer if the task says to choose from the choices given.","zh":"如果題目說要從所提供選項中選，學生不應自己創作答案。"},{"en":"This instruction limits possible answers and tests careful selection.","zh":"這個指示限制可能答案，並測試仔細選擇。"},{"en":"It is common in multiple-choice questions.","zh":"它常見於選擇題。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":18},{"front":"be criticised for","meaning":"因……受到批評","examples":[{"en":"University students nowadays are criticised for weak writing skills.","zh":"現今大學生因寫作能力弱而受到批評。"},{"en":"To be criticised for something means to be judged negatively because of it.","zh":"be criticised for something 指因某事而被負面評價。"},{"en":"A restaurant may be criticised for slow service and dirty tables.","zh":"餐廳可能因服務慢和桌子骯髒而受到批評。"},{"en":"Criticism can lead to improvement if the problem is clearly identified.","zh":"如果問題被清楚指出，批評可以帶來改善。"},{"en":"This phrase connects a person or group with the reason for disapproval.","zh":"這個短語把人物或群體與被不滿的原因連接起來。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":18},{"front":"lack of","meaning":"缺乏","examples":[{"en":"Students are criticised for their lack of essay writing ability.","zh":"學生因缺乏寫論文能力而受到批評。"},{"en":"Lack of something means not having enough of it.","zh":"lack of something 指某事物不足或沒有足夠。"},{"en":"A lack of sleep can make students careless in exams.","zh":"缺乏睡眠可以令學生在考試中粗心。"},{"en":"When there is a lack of practice, skills may remain weak.","zh":"當缺乏練習，技能可能仍然薄弱。"},{"en":"This phrase is useful for explaining shortages or weaknesses.","zh":"這個短語適合解釋短缺或弱點。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":18},{"front":"mathematical ability","meaning":"數學能力","examples":[{"en":"Some critics question students’ mathematical ability.","zh":"有些批評者質疑學生的數學能力。"},{"en":"Mathematical ability is the skill to understand and use numbers, calculations, and logical patterns.","zh":"mathematical ability 指理解和運用數字、計算和邏輯模式的能力。"},{"en":"A shop assistant needs mathematical ability to check prices and change.","zh":"店員需要數學能力來檢查價格和找續。"},{"en":"Weak mathematical ability can make finance, science, and data tasks harder.","zh":"數學能力弱會令財務、科學和數據任務更困難。"},{"en":"This phrase describes skill with numbers and reasoning.","zh":"這個短語描述數字和推理能力。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":18},{"front":"essay writing ability","meaning":"寫論文能力","examples":[{"en":"University students are criticised for their essay writing ability.","zh":"大學生因寫論文能力而受到批評。"},{"en":"Essay writing ability is the skill to organise ideas, develop arguments, and write clearly.","zh":"essay writing ability 指組織想法、發展論點和清楚寫作的能力。"},{"en":"A student improves essay writing ability by planning, reading model essays, and revising drafts.","zh":"學生透過規劃、閱讀範文和修改草稿來改善寫論文能力。"},{"en":"Weak essay writing can hide good thinking behind unclear structure.","zh":"寫作能力弱可能把好思考藏在不清楚結構後面。"},{"en":"This phrase is central to academic performance.","zh":"這個短語是學術表現的核心。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":18},{"front":"criminal behaviour","meaning":"犯罪行為","examples":[{"en":"The option refers to criminal behaviour, but the passage is about grammar mistakes.","zh":"這個選項提到犯罪行為，但文章講的是文法錯誤。"},{"en":"Criminal behaviour means actions that break the law.","zh":"criminal behaviour 指違反法律的行為。"},{"en":"Theft, fraud, and assault are examples of criminal behaviour.","zh":"偷竊、欺詐和襲擊都是犯罪行為例子。"},{"en":"In this context, “crimes against grammar” is humorous and does not mean real criminal behaviour.","zh":"在這個語境中，crimes against grammar 是幽默說法，不是真正犯罪行為。"},{"en":"This phrase helps students avoid taking figurative language too literally.","zh":"這個短語幫助學生避免把比喻語言理解得太字面。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":18},{"front":"be concerned about","meaning":"關注；擔心","examples":[{"en":"Geoff Hayward is concerned about the quality of students.","zh":"Geoff Hayward 關注學生的質素。"},{"en":"To be concerned about something means to feel worried about it.","zh":"be concerned about something 指對某事感到擔心。"},{"en":"Parents may be concerned about children spending too much time online.","zh":"家長可能擔心孩子花太多時間上網。"},{"en":"Concern can lead people to investigate a problem and suggest solutions.","zh":"擔憂可以促使人們調查問題並提出解決方法。"},{"en":"This phrase is common in formal and everyday English.","zh":"這個短語在正式和日常英語中都常見。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":18},{"front":"communicate properly","meaning":"適當地溝通","examples":[{"en":"Some people worry about whether students can communicate properly.","zh":"有些人擔心學生能否適當地溝通。"},{"en":"To communicate properly means to express ideas clearly and appropriately.","zh":"communicate properly 指清楚而恰當地表達想法。"},{"en":"A nurse must communicate properly when explaining medicine to a patient.","zh":"護士向病人解釋藥物時必須適當地溝通。"},{"en":"Poor communication can create mistakes, confusion, and frustration.","zh":"溝通不良會造成錯誤、混亂和挫折。"},{"en":"This phrase covers speaking, writing, listening, and tone.","zh":"這個短語涵蓋說話、寫作、聆聽和語氣。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":19},{"front":"focus too much on","meaning":"過分集中於","examples":[{"en":"Schools may focus too much on examinations.","zh":"學校可能過分集中於考試。"},{"en":"To focus too much on something means to give it excessive attention at the cost of other things.","zh":"focus too much on something 指給予某事過多注意，以致犧牲其他事情。"},{"en":"A student who focuses too much on vocabulary lists may forget to practise speaking.","zh":"過分集中於詞彙表的學生可能忘記練習說話。"},{"en":"Too much focus on exams can reduce curiosity and broader understanding.","zh":"過分集中於考試可以削弱好奇心和更廣泛理解。"},{"en":"This phrase is useful when criticising imbalance.","zh":"批評不平衡時，這個短語很有用。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":19},{"front":"examinations","meaning":"考試","examples":[{"en":"Exam-focused teaching may reduce broader understanding.","zh":"以考試為中心的教學可能削弱更廣泛理解。"},{"en":"Examinations are formal tests used to measure knowledge or skill.","zh":"examinations 指用來衡量知識或技能的正式測驗。"},{"en":"Students often revise grammar, vocabulary, and essay structure before examinations.","zh":"學生常在考試前溫習文法、詞彙和文章結構。"},{"en":"Exams can motivate study, but too many exams may narrow learning.","zh":"考試可以推動學習，但太多考試可能令學習變窄。"},{"en":"This word is common in education contexts.","zh":"這個詞常見於教育語境。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":19},{"front":"point out that","meaning":"指出","examples":[{"en":"Bill Rammell points out that other countries also want more graduates.","zh":"Bill Rammell 指出其他國家也想要更多畢業生。"},{"en":"To point out that something is true means to mention it clearly because it supports an argument.","zh":"point out that something is true 指清楚提到某事，因為它支持一個論點。"},{"en":"A teacher may point out that reading the question carefully prevents careless mistakes.","zh":"老師可能指出仔細讀題可以防止粗心錯誤。"},{"en":"People point out facts to add evidence or correct an incomplete view.","zh":"人們指出事實，以增加證據或修正不完整看法。"},{"en":"This phrase is useful in discussion and explanation.","zh":"這個短語適合用於討論和解釋。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":19},{"front":"increase the number of","meaning":"增加……的數目","examples":[{"en":"Other countries want to increase the number of graduates.","zh":"其他國家想增加畢業生數目。"},{"en":"To increase the number of something means to make there be more of it.","zh":"increase the number of something 指令某事物數量更多。"},{"en":"A school may increase the number of reading lessons to improve literacy.","zh":"學校可能增加閱讀課節數目，以改善讀寫能力。"},{"en":"Increasing numbers can solve shortages, but quality control is still needed.","zh":"增加數量可以解決短缺，但仍需要質素控制。"},{"en":"This phrase is common in policy and planning.","zh":"這個短語常見於政策和規劃。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":19},{"front":"market forces","meaning":"市場力量","examples":[{"en":"Wolf believes that market forces should influence university numbers.","zh":"Wolf 認為市場力量應影響大學人數。"},{"en":"Market forces are pressures created by supply, demand, prices, wages, and competition.","zh":"market forces 指由供應、需求、價格、工資和競爭造成的壓力。"},{"en":"Market forces may raise salaries when there are not enough skilled workers.","zh":"當技術工人不足，市場力量可能推高薪金。"},{"en":"Supporters say market forces show what people and employers really need.","zh":"支持者認為市場力量顯示人們和僱主真正需要甚麼。"},{"en":"This phrase contrasts economic signals with government targets.","zh":"這個短語把經濟訊號與政府目標作對比。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":19},{"front":"determine how many people","meaning":"決定有多少人","examples":[{"en":"Market forces may determine how many people go to university.","zh":"市場力量可能決定有多少人上大學。"},{"en":"To determine how many people means to decide or strongly influence the number of people involved.","zh":"determine how many people 指決定或強烈影響參與人數。"},{"en":"Ticket prices may determine how many people attend a concert.","zh":"票價可能決定有多少人參加演唱會。"},{"en":"If employers demand more graduates, market forces may increase university participation.","zh":"如果僱主需要更多畢業生，市場力量可能增加大學參與率。"},{"en":"This phrase connects causes with numbers.","zh":"這個短語把原因與數量連接起來。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":19},{"front":"shorten lists of applicants","meaning":"縮短申請人名單","examples":[{"en":"Employers use degrees to shorten lists of applicants.","zh":"僱主使用學位來縮短申請人名單。"},{"en":"To shorten lists of applicants means to reduce the number of people being considered for a job.","zh":"shorten lists of applicants 指減少被考慮聘用的人數。"},{"en":"A company may shorten a list of applicants by requiring experience or a qualification.","zh":"公司可能透過要求經驗或資格來縮短申請人名單。"},{"en":"Shortlisting saves time, but it may remove good candidates too early.","zh":"篩選名單節省時間，但也可能太早排除好候選人。"},{"en":"This phrase explains one practical reason employers value degrees.","zh":"這個短語解釋僱主重視學位的一個實際原因。"}],"source":"93 - British Universities Seek Quantity and Quality.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 94":[{"front":"Clicks, Bricks, and Bargains","meaning":"網上點擊、實體店與優惠","examples":[{"en":"The title “Clicks, Bricks, and Bargains” refers to online shopping, physical stores, and cheap deals.","zh":"標題「網上點擊、實體店與優惠」指網上購物、實體店和便宜交易。"},{"en":"Clicks, bricks, and bargains means the mix of internet shopping, real shops, and low prices.","zh":"Clicks, bricks, and bargains 是指互聯網購物、真實店舖和低價的混合。"},{"en":"A shopper may compare prices online, visit a store, and look for bargains before buying a phone.","zh":"顧客買手機前，可能先網上格價，再到店舖查看，並尋找優惠。"},{"en":"Retailers succeed when they connect clicks, bricks, and bargains into one smooth shopping experience.","zh":"當零售商把網上點擊、實體店和優惠連成順暢購物體驗時，就更容易成功。"},{"en":"This phrase shows that modern shopping is not only online or offline, but a mixture of both.","zh":"這個短語顯示現代購物不只是網上或線下，而是兩者的混合。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":1},{"front":"a new phenomenon","meaning":"新現象","examples":[{"en":"Cyber Monday is described as a new phenomenon.","zh":"網絡星期一被描述為一種新現象。"},{"en":"A new phenomenon is a recent event, trend, or behaviour that people have only recently started noticing.","zh":"新現象是人們最近才開始注意到的事件、趨勢或行為。"},{"en":"Online lessons became a new phenomenon for many families during school closures.","zh":"在停課期間，網上課堂對許多家庭而言成為新現象。"},{"en":"A new phenomenon can grow quickly when technology changes people’s habits.","zh":"當科技改變人們習慣時，新現象可以迅速增長。"},{"en":"This phrase suggests something is new, noticeable, and worth explaining.","zh":"這個短語暗示某事新近出現、明顯且值得解釋。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":1},{"front":"Cyber Monday","meaning":"網絡星期一","examples":[{"en":"Cyber Monday became an important day for online shopping.","zh":"網絡星期一成為網上購物的重要日子。"},{"en":"Cyber Monday is the Monday after Thanksgiving when many retailers offer online discounts.","zh":"網絡星期一是感恩節後的星期一，許多零售商會提供網上折扣。"},{"en":"A customer may wait until Cyber Monday to buy electronics at a lower price.","zh":"顧客可能等到網絡星期一才以較低價格購買電子產品。"},{"en":"Cyber Monday became important because shoppers could use fast internet to find deals quickly.","zh":"網絡星期一變得重要，因為購物者可以用高速網絡快速尋找優惠。"},{"en":"This phrase is linked to online sales rather than shopping in physical stores only.","zh":"這個短語與網上銷售有關，而不只是實體店購物。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":1},{"front":"return to work after","meaning":"在……之後返回工作崗位","examples":[{"en":"Millions of Americans returned to work after the Thanksgiving holiday.","zh":"數以百萬計美國人在感恩節假期後返回工作崗位。"},{"en":"To return to work after something means to go back to one’s job when a break or event has ended.","zh":"return to work after something 是指假期或事件結束後回到工作。"},{"en":"Employees return to work after a long weekend and often have many emails to answer.","zh":"員工在長週末後返回工作崗位，通常有很多電郵要回覆。"},{"en":"When people return to work after a holiday, office internet and computers become available again.","zh":"當人們假期後返回工作崗位，辦公室網絡和電腦又可使用。"},{"en":"This phrase links the end of a break with normal work routines.","zh":"這個短語把休息結束與正常工作日常連接起來。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":1},{"front":"Thanksgiving holiday","meaning":"感恩節假期","examples":[{"en":"Americans returned to work after the Thanksgiving holiday.","zh":"美國人在感恩節假期後返回工作崗位。"},{"en":"The Thanksgiving holiday is a major American holiday period centred on giving thanks and family meals.","zh":"感恩節假期是美國重要假期，主要圍繞感恩和家庭聚餐。"},{"en":"Many families travel during the Thanksgiving holiday to eat together and visit relatives.","zh":"許多家庭在感恩節假期期間旅行，一起吃飯和探親。"},{"en":"Shopping often increases after the Thanksgiving holiday because Christmas is approaching.","zh":"感恩節假期後購物通常增加，因為聖誕節臨近。"},{"en":"This phrase refers to the holiday period, not only the meal itself.","zh":"這個短語指整個假期時段，而不只是那頓飯。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":1},{"front":"fire up office computers","meaning":"啟動辦公室電腦","examples":[{"en":"Workers fired up their office computers to shop online.","zh":"員工啟動辦公室電腦來網上購物。"},{"en":"To fire up office computers means to turn them on and start using them.","zh":"fire up office computers 是指開啟辦公室電腦並開始使用。"},{"en":"Staff may fire up office computers early in the morning to check orders and emails.","zh":"員工可能早上先啟動辦公室電腦來檢查訂單和電郵。"},{"en":"When faster office computers became available, workers could shop online more easily.","zh":"當較快的辦公室電腦可用時，員工可以更容易網上購物。"},{"en":"This phrase is informal and suggests starting a machine for immediate use.","zh":"這個短語較口語，暗示啟動機器並立即使用。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":1},{"front":"take advantage of","meaning":"利用","examples":[{"en":"Shoppers took advantage of high-speed Internet links.","zh":"購物者利用高速互聯網連線。"},{"en":"To take advantage of something means to use an opportunity or resource for benefit.","zh":"take advantage of something 是指利用機會或資源來獲益。"},{"en":"Students can take advantage of free library Wi-Fi to finish online research.","zh":"學生可以利用圖書館免費 Wi-Fi 完成網上資料搜集。"},{"en":"Retailers take advantage of holiday demand by offering special discounts.","zh":"零售商利用假日需求推出特別折扣。"},{"en":"This phrase can be positive when it means making good use of something.","zh":"當意思是善用某物時，這個短語可以是正面的。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":1},{"front":"high-speed Internet links","meaning":"高速互聯網連線","examples":[{"en":"Office workers used high-speed Internet links to shop online.","zh":"辦公室員工使用高速互聯網連線網上購物。"},{"en":"High-speed Internet links are fast internet connections that allow pages and orders to load quickly.","zh":"高速互聯網連線是快速網絡連接，可讓網頁和訂單迅速載入。"},{"en":"A school needs high-speed Internet links if many students use online learning platforms at once.","zh":"如果許多學生同時使用網上學習平台，學校需要高速互聯網連線。"},{"en":"Faster links can make online shopping smoother and reduce waiting time.","zh":"更快的連線可以令網上購物更順暢，減少等待時間。"},{"en":"This phrase focuses on internet connection speed.","zh":"這個短語集中於互聯網連線速度。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":1},{"front":"continue the arduous task of","meaning":"繼續……這項艱巨任務","examples":[{"en":"They continued the arduous task of hunting for Christmas presents.","zh":"他們繼續尋找聖誕禮物這項艱巨任務。"},{"en":"To continue the arduous task of something means to keep doing a difficult and tiring job.","zh":"continue the arduous task of something 是指繼續做一項困難而累人的工作。"},{"en":"Parents may continue the arduous task of finding a suitable school for their child.","zh":"父母可能繼續為孩子尋找合適學校這項艱巨任務。"},{"en":"A task feels arduous when it takes time, effort, and repeated searching.","zh":"當任務需要時間、努力和反覆搜尋時，就會顯得艱巨。"},{"en":"This phrase suggests the work is necessary but not easy.","zh":"這個短語暗示工作必要但不容易。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":1},{"front":"hunting for Christmas presents","meaning":"尋找聖誕禮物","examples":[{"en":"Many people were hunting for Christmas presents online.","zh":"許多人在網上尋找聖誕禮物。"},{"en":"Hunting for Christmas presents means actively searching for gifts to buy before Christmas.","zh":"hunting for Christmas presents 是指在聖誕節前積極尋找要買的禮物。"},{"en":"A shopper may hunt for presents by comparing prices, reading reviews, and checking delivery dates.","zh":"購物者可能透過格價、閱讀評價和檢查送貨日期來尋找禮物。"},{"en":"Gift hunting can become stressful when popular items sell out quickly.","zh":"當熱門商品很快售罄時，尋找禮物會變得有壓力。"},{"en":"This phrase makes shopping sound like a focused search.","zh":"這個短語令購物聽起來像一次有目標的搜尋。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":1},{"front":"retail websites","meaning":"零售網站","examples":[{"en":"Visits to some retail websites more than doubled.","zh":"一些零售網站的到訪量增加超過一倍。"},{"en":"Retail websites are websites where shops or companies sell goods to customers.","zh":"retail websites 是商店或公司向顧客銷售商品的網站。"},{"en":"A customer may visit retail websites to compare shoes, phones, or household items.","zh":"顧客可能到訪零售網站比較鞋、手機或家居用品。"},{"en":"Retail websites become busier when discounts or holiday shopping periods begin.","zh":"當折扣或假日購物期開始時，零售網站會更繁忙。"},{"en":"This phrase refers to online stores rather than information-only pages.","zh":"這個短語指網上商店，而不是只提供資訊的網頁。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":1},{"front":"more than doubled","meaning":"增加超過一倍","examples":[{"en":"Visits to some retail websites more than doubled.","zh":"一些零售網站的到訪量增加超過一倍。"},{"en":"More than doubled means increased to more than twice the original amount.","zh":"more than doubled 是指增加到超過原本數量的兩倍。"},{"en":"If a shop had 100 visitors yesterday and 230 today, visits more than doubled.","zh":"如果店舖昨天有100名訪客，今天有230名，訪客量就是增加超過一倍。"},{"en":"Strong discounts can make website traffic more than double in one day.","zh":"強勁折扣可以令網站流量一天內增加超過一倍。"},{"en":"This phrase describes very large growth.","zh":"這個短語描述非常大的增長。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":2},{"front":"online spending","meaning":"網上消費","examples":[{"en":"Visa reported a sharp rise in online spending.","zh":"Visa 報告網上消費急升。"},{"en":"Online spending is the money people spend when buying goods or services on the internet.","zh":"online spending 是人們在互聯網購買商品或服務時花的錢。"},{"en":"A family’s online spending may rise before Christmas because they buy gifts and decorations.","zh":"家庭在聖誕節前網上消費可能上升，因為他們購買禮物和裝飾。"},{"en":"Online spending grows when people trust websites and find delivery convenient.","zh":"當人們信任網站並覺得送貨方便時，網上消費會增長。"},{"en":"This phrase measures purchases made through the internet.","zh":"這個短語量度透過互聯網進行的購買。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":2},{"front":"cardholders","meaning":"持卡人","examples":[{"en":"Online spending by Visa cardholders grew sharply.","zh":"Visa 持卡人的網上消費大幅增長。"},{"en":"Cardholders are people who own or use a payment card issued by a bank or company.","zh":"cardholders 是擁有或使用由銀行或公司發出的付款卡的人。"},{"en":"Credit-card companies may offer rewards to cardholders who shop online.","zh":"信用卡公司可能向網上購物的持卡人提供獎賞。"},{"en":"Spending data from cardholders helps companies understand shopping trends.","zh":"持卡人的消費數據幫助公司理解購物趨勢。"},{"en":"This word refers to customers with cards, not the physical card itself.","zh":"這個詞指有卡的顧客，而不是卡本身。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":2},{"front":"grow by 26 per cent","meaning":"增長百分之二十六","examples":[{"en":"Online spending by Visa cardholders grew by 26 per cent.","zh":"Visa 持卡人的網上消費增長百分之二十六。"},{"en":"To grow by 26 per cent means to increase by 26% compared with an earlier figure.","zh":"grow by 26 per cent 是指與早前數字相比增加26%。"},{"en":"If sales grow by 26 per cent, a shop earning $100,000 before would earn $126,000 now.","zh":"如果銷售增長百分之二十六，一間原本賺10萬元的店現在會賺12.6萬元。"},{"en":"A percentage increase helps readers compare growth even when original amounts differ.","zh":"百分比增幅即使原本金額不同，也幫助讀者比較增長。"},{"en":"This phrase gives a precise measure of growth.","zh":"這個短語給出精確的增長量度。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":2},{"front":"compared with","meaning":"與……相比","examples":[{"en":"Online spending rose compared with the same day a year ago.","zh":"與一年前同一天相比，網上消費上升。"},{"en":"Compared with means measured or judged against another thing or time.","zh":"compared with 是指與另一事物或時間相比來量度或判斷。"},{"en":"Compared with last month, this month’s rent is easier to pay because income rose.","zh":"與上個月相比，這個月租金較容易支付，因為收入上升了。"},{"en":"Businesses compare current sales with past sales to see whether they are improving.","zh":"企業把目前銷售與過去銷售比較，以了解是否改善。"},{"en":"This phrase introduces the reference point for comparison.","zh":"這個短語引入比較的參考點。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":2},{"front":"the same day a year ago","meaning":"一年前同一天","examples":[{"en":"The figure was compared with the same day a year ago.","zh":"該數字與一年前同一天比較。"},{"en":"The same day a year ago means the matching date or shopping day in the previous year.","zh":"the same day a year ago 是指上一年相同日期或相同購物日。"},{"en":"A retailer may compare this Monday’s sales with the same day a year ago to judge growth fairly.","zh":"零售商可能把本星期一銷售與一年前同一天比較，以公平判斷增長。"},{"en":"Comparing the same day avoids confusing holiday effects with real growth.","zh":"比較同一天可以避免把假日影響誤當成真正增長。"},{"en":"This phrase is used for year-on-year comparison.","zh":"這個短語用於按年比較。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":2},{"front":"concerns about","meaning":"對……的憂慮","examples":[{"en":"There were concerns about a fall in consumer confidence.","zh":"人們對消費者信心下降有所憂慮。"},{"en":"Concerns about something are worries or doubts about a possible problem.","zh":"concerns about something 是對潛在問題的擔心或疑慮。"},{"en":"Parents may have concerns about children spending too much time online.","zh":"家長可能對孩子花太多時間上網感到憂慮。"},{"en":"Concerns about falling sales can make businesses reduce hiring or advertising.","zh":"對銷售下降的憂慮會令企業減少招聘或廣告。"},{"en":"This phrase introduces what people are worried about.","zh":"這個短語引入人們擔心的事情。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":2},{"front":"a fall in consumer confidence","meaning":"消費者信心下降","examples":[{"en":"A fall in consumer confidence could affect store sales.","zh":"消費者信心下降可能影響店舖銷售。"},{"en":"A fall in consumer confidence means shoppers feel less willing to spend money because they are worried about the economy.","zh":"fall in consumer confidence 是指購物者因擔心經濟而較不願意花錢。"},{"en":"If people fear job losses, a fall in consumer confidence may follow.","zh":"如果人們害怕失業，可能出現消費者信心下降。"},{"en":"When confidence falls, families may delay buying expensive items.","zh":"當信心下降，家庭可能延遲購買昂貴物品。"},{"en":"This phrase links public mood with shopping behaviour.","zh":"這個短語把公眾情緒與購物行為連接起來。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":2},{"front":"put the brake on","meaning":"抑制；拖慢","examples":[{"en":"Lower consumer confidence could put the brake on store sales.","zh":"較低的消費者信心可能抑制店舖銷售。"},{"en":"To put the brake on something means to slow it down or stop it growing.","zh":"put the brake on something 是指拖慢或阻止某事增長。"},{"en":"Higher rent can put the brake on a small shop’s expansion plans.","zh":"較高租金可以拖慢小店的擴展計劃。"},{"en":"If customers feel uncertain, they may put the brake on spending.","zh":"如果顧客感到不確定，他們可能會抑制消費。"},{"en":"This phrase uses driving as a metaphor for slowing progress.","zh":"這個短語以駕駛作比喻，表示減慢進展。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":2},{"front":"store sales","meaning":"店舖銷售","examples":[{"en":"Concerns grew that weaker confidence might reduce store sales.","zh":"人們越來越擔心較弱信心可能減少店舖銷售。"},{"en":"Store sales are the goods or services sold through physical shops.","zh":"store sales 是透過實體店售出的商品或服務。"},{"en":"Store sales may rise during holidays when more people visit shopping centres.","zh":"假日期間更多人到訪商場，店舖銷售可能上升。"},{"en":"Bad weather can reduce store sales because fewer customers go outside.","zh":"惡劣天氣可以減少店舖銷售，因為較少顧客外出。"},{"en":"This phrase usually refers to sales in shops, not online orders.","zh":"這個短語通常指店內銷售，而不是網上訂單。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":2},{"front":"online purchases","meaning":"網上購物；網上購買","examples":[{"en":"Online purchases are soaring in most countries.","zh":"網上購物在大多數國家急升。"},{"en":"Online purchases are goods or services bought through websites or apps.","zh":"online purchases 是透過網站或應用程式購買的商品或服務。"},{"en":"A student may make online purchases for books, clothes, or exam materials.","zh":"學生可能網上購買書籍、衣服或考試材料。"},{"en":"Online purchases increase when delivery is cheap and payment feels safe.","zh":"當送貨便宜且付款感覺安全時，網上購物會增加。"},{"en":"This phrase refers to the act of buying online, not just browsing.","zh":"這個短語指網上購買行為，而不只是瀏覽。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":2},{"front":"be soaring","meaning":"急升；飆升","examples":[{"en":"Online purchases are soaring in many countries.","zh":"網上購物在許多國家急升。"},{"en":"To be soaring means to be rising very quickly and strongly.","zh":"be soaring 是指非常快速而強勁地上升。"},{"en":"Rent may be soaring if many people want homes in the same district.","zh":"如果很多人想住在同一區，租金可能飆升。"},{"en":"Sales can soar when a product becomes popular on social media.","zh":"當產品在社交媒體上流行，銷售可以急升。"},{"en":"This phrase suggests a sharp upward movement.","zh":"這個短語暗示急劇向上移動。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":3},{"front":"increasingly","meaning":"越來越多地","examples":[{"en":"Increasingly, conventional retailers are growing quickly online.","zh":"越來越多地，傳統零售商在網上快速增長。"},{"en":"Increasingly means more and more over time.","zh":"increasingly 是指隨時間越來越多或越來越強。"},{"en":"Students are increasingly using phones to check homework and messages.","zh":"學生越來越多地使用手機查看功課和訊息。"},{"en":"Retailers increasingly invest in websites because customers expect online options.","zh":"零售商越來越多地投資網站，因為顧客期望有網上選項。"},{"en":"This word shows that a trend is becoming stronger.","zh":"這個詞顯示趨勢正在加強。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":3},{"front":"websites run by","meaning":"由……營運的網站","examples":[{"en":"The websites run by conventional retailers are growing quickly.","zh":"由傳統零售商營運的網站正在快速增長。"},{"en":"Websites run by a company are websites operated, managed, or controlled by that company.","zh":"websites run by a company 是由該公司營運、管理或控制的網站。"},{"en":"A school website run by the office may publish notices and timetables.","zh":"由校務處營運的學校網站可能發布通知和時間表。"},{"en":"Websites run by trusted stores may attract customers who worry about online fraud.","zh":"由可信店舖營運的網站，可能吸引擔心網上詐騙的顧客。"},{"en":"This phrase identifies who operates the website.","zh":"這個短語指出誰營運該網站。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":3},{"front":"conventional retailers","meaning":"傳統零售商","examples":[{"en":"Conventional retailers are becoming important online sellers.","zh":"傳統零售商正在成為重要網上賣家。"},{"en":"Conventional retailers are traditional shops or chains that originally sold goods through physical stores.","zh":"conventional retailers 是最初透過實體店銷售商品的傳統商店或連鎖店。"},{"en":"A supermarket chain is a conventional retailer if customers usually visit its shops in person.","zh":"如果顧客通常親身到店購物，連鎖超市就是傳統零售商。"},{"en":"Conventional retailers can grow online because many customers already trust their brands.","zh":"傳統零售商可以在網上成長，因為許多顧客已經信任其品牌。"},{"en":"This phrase contrasts traditional shop-based sellers with internet-only businesses.","zh":"這個短語把傳統店舖賣家與純網上業務作對比。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":3},{"front":"once considered","meaning":"曾被視為","examples":[{"en":"These retailers were once considered dinosaurs of the bricks-and-mortar age.","zh":"這些零售商曾被視為實體店時代的恐龍。"},{"en":"Once considered means people used to think of someone or something in a particular way.","zh":"once considered 是指人們過去曾以某種方式看待某人或某事。"},{"en":"Online learning was once considered less serious than classroom learning by some parents.","zh":"有些家長曾認為網上學習不如課堂學習嚴肅。"},{"en":"A company once considered old-fashioned can become modern if it adapts quickly.","zh":"曾被視為老派的公司，如果快速適應，也可以變得現代。"},{"en":"This phrase contrasts past opinion with later change.","zh":"這個短語把過去看法與後來變化作對比。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":3},{"front":"dinosaurs of the bricks-and-mortar age","meaning":"實體店時代的恐龍；落伍者","examples":[{"en":"Some conventional retailers were once considered dinosaurs of the bricks-and-mortar age.","zh":"有些傳統零售商曾被視為實體店時代的恐龍。"},{"en":"Dinosaurs of the bricks-and-mortar age means old-fashioned store-based businesses seen as slow to adapt.","zh":"dinosaurs of the bricks-and-mortar age 是指被視為適應緩慢、以實體店為主的老派企業。"},{"en":"A bank with no app may be called a dinosaur if customers expect online service.","zh":"如果顧客期望網上服務，而銀行沒有應用程式，它可能被稱為恐龍。"},{"en":"Such retailers can prove critics wrong if they build strong websites.","zh":"如果這些零售商建立強大網站，就能證明批評者錯了。"},{"en":"This phrase is metaphorical and slightly critical.","zh":"這個短語是比喻，並帶少許批評意味。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":3},{"front":"bricks-and-mortar age","meaning":"實體店時代","examples":[{"en":"Traditional retailers belonged to the bricks-and-mortar age.","zh":"傳統零售商屬於實體店時代。"},{"en":"The bricks-and-mortar age refers to a period when shopping mainly happened in physical stores.","zh":"bricks-and-mortar age 是指購物主要在實體店發生的時期。"},{"en":"In the bricks-and-mortar age, customers usually travelled to shops to see products.","zh":"在實體店時代，顧客通常到店舖查看產品。"},{"en":"The internet changed retail by adding online choices to store-based shopping.","zh":"互聯網透過在實體店購物之外加入網上選擇，改變了零售。"},{"en":"This phrase contrasts physical retail with digital retail.","zh":"這個短語把實體零售與數碼零售作對比。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":3},{"front":"grow the fastest","meaning":"增長最快","examples":[{"en":"Websites run by conventional retailers are growing the fastest.","zh":"由傳統零售商營運的網站增長最快。"},{"en":"To grow the fastest means to increase more quickly than other comparable things.","zh":"grow the fastest 是指比其他可比較事物增長得更快。"},{"en":"In a class, the student who practises daily may improve the fastest.","zh":"在班上，每天練習的學生可能進步最快。"},{"en":"A website grows fastest when customers already know and trust the brand.","zh":"當顧客已經認識並信任品牌時，網站可能增長最快。"},{"en":"This phrase compares speed of growth.","zh":"這個短語比較增長速度。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":3},{"front":"Thanksgiving Day itself","meaning":"感恩節當日","examples":[{"en":"On Thanksgiving Day itself, Wal-Mart’s website attracted huge traffic.","zh":"在感恩節當日，沃爾瑪網站吸引大量流量。"},{"en":"Thanksgiving Day itself means the exact holiday day, not the days before or after it.","zh":"Thanksgiving Day itself 是指確切的感恩節當天，而不是前後日子。"},{"en":"On Christmas Day itself, many shops may close even if sales are high before it.","zh":"在聖誕節當日，即使節日前銷售很高，許多店舖也可能關門。"},{"en":"Mentioning the day itself makes the timing more precise.","zh":"提到當日令時間更精確。"},{"en":"This phrase stresses the specific day.","zh":"這個短語強調具體那一天。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":3},{"front":"the number of visitors to","meaning":"到訪……的人數","examples":[{"en":"The number of visitors to Wal-Mart’s website exceeded Amazon’s.","zh":"到訪沃爾瑪網站的人數超過亞馬遜。"},{"en":"The number of visitors to a website means how many people went to that site.","zh":"number of visitors to a website 是指到訪該網站的人數。"},{"en":"A school can track the number of visitors to its website after exam results are posted.","zh":"學校在公布考試結果後，可以追蹤到訪其網站的人數。"},{"en":"More visitors can mean more interest, but not always more sales.","zh":"更多訪客可以表示更多興趣，但不一定代表更多銷售。"},{"en":"This phrase measures website traffic.","zh":"這個短語量度網站流量。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":3},{"front":"exceed those visiting","meaning":"超過到訪……的人","examples":[{"en":"Visitors to Wal-Mart’s website exceeded those visiting Amazon.","zh":"到訪沃爾瑪網站的人超過到訪亞馬遜的人。"},{"en":"To exceed those visiting another site means to have more visitors than that site.","zh":"exceed those visiting another site 是指訪客人數比另一網站更多。"},{"en":"During a sale, visitors to a local retailer’s website may exceed those visiting a larger competitor.","zh":"促銷期間，本地零售商網站訪客可能超過大型競爭者。"},{"en":"If one site offers better deals, its visitor numbers may exceed others.","zh":"如果一個網站提供更好優惠，其訪客數可能超過其他網站。"},{"en":"This phrase compares the number of visitors.","zh":"這個短語比較訪客數量。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":3},{"front":"the first time that has ever happened","meaning":"這是首次發生","examples":[{"en":"This was the first time that had ever happened.","zh":"這是首次發生。"},{"en":"The first time that has ever happened means an event has never occurred before.","zh":"first time that has ever happened 是指某事件以前從未發生。"},{"en":"When a small team wins the championship, it may be the first time that has ever happened.","zh":"當小隊伍贏得冠軍時，這可能是首次發生。"},{"en":"Such a phrase highlights a surprising new record or milestone.","zh":"這個短語突顯令人驚訝的新紀錄或里程碑。"},{"en":"It shows that the event is historically unusual.","zh":"它顯示該事件在歷史上不同尋常。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":4},{"front":"monitor Internet usage","meaning":"監察互聯網使用情況","examples":[{"en":"Hitwise monitors Internet usage.","zh":"Hitwise 監察互聯網使用情況。"},{"en":"To monitor Internet usage means to track how people use websites and online services.","zh":"monitor Internet usage 是指追蹤人們如何使用網站和網上服務。"},{"en":"A company may monitor website usage to see which pages customers visit most.","zh":"公司可能監察網站使用情況，以了解顧客最多到訪哪些頁面。"},{"en":"Monitoring internet use can reveal shopping trends and popular brands.","zh":"監察互聯網使用情況可以揭示購物趨勢和熱門品牌。"},{"en":"This phrase focuses on observation and data collection.","zh":"這個短語集中於觀察和數據收集。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":4},{"front":"excluding travel","meaning":"不包括旅遊","examples":[{"en":"Online sales in America, excluding travel, were expected to grow.","zh":"美國網上銷售不包括旅遊在內，預計會增長。"},{"en":"Excluding travel means not counting spending on flights, hotels, holidays, or transport bookings.","zh":"excluding travel 是指不計算機票、酒店、假期或交通預訂的消費。"},{"en":"A report may say online spending rose, excluding travel, to focus only on retail goods.","zh":"報告可能說網上消費上升，不包括旅遊，以只集中於零售商品。"},{"en":"Excluding one category can make data easier to compare.","zh":"排除某一類別可以令數據更易比較。"},{"en":"This phrase tells readers what is left out of the calculation.","zh":"這個短語告訴讀者計算中排除了甚麼。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":4},{"front":"be expected to grow to","meaning":"預計增至","examples":[{"en":"Online sales were expected to grow to more than 19 billion dollars.","zh":"網上銷售預計增至超過190億美元。"},{"en":"To be expected to grow to an amount means experts predict it will increase until it reaches that amount.","zh":"be expected to grow to an amount 是指專家預測它會增加並達到該數量。"},{"en":"A school’s enrolment may be expected to grow to 1,000 students after a new campus opens.","zh":"新校園開放後，學校入學人數可能預計增至1000人。"},{"en":"Sales forecasts help businesses prepare staff, stock, and delivery systems.","zh":"銷售預測幫助企業準備人手、存貨和送貨系統。"},{"en":"This phrase expresses prediction, not a confirmed result.","zh":"這個短語表達預測，而不是已確認結果。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":4},{"front":"crucial two months","meaning":"關鍵的兩個月","examples":[{"en":"The two months before Christmas are crucial for retailers.","zh":"聖誕節前兩個月對零售商非常關鍵。"},{"en":"Crucial two months means a two-month period that is extremely important for success.","zh":"crucial two months 是指對成功極為重要的兩個月時期。"},{"en":"The two months before exams are crucial for students who need steady revision.","zh":"考試前兩個月對需要穩定溫習的學生很關鍵。"},{"en":"Retailers rely on the Christmas period because it can decide annual profits.","zh":"零售商依賴聖誕節時期，因為它可以決定全年利潤。"},{"en":"This phrase stresses importance within a limited time.","zh":"這個短語強調有限時間內的重要性。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":4},{"front":"running up to Christmas","meaning":"聖誕節前夕","examples":[{"en":"Sales rise during the months running up to Christmas.","zh":"銷售在聖誕節前夕的幾個月上升。"},{"en":"Running up to Christmas means in the period before Christmas arrives.","zh":"running up to Christmas 是指聖誕節到來前的一段時間。"},{"en":"Shops hire extra staff in the weeks running up to Christmas.","zh":"商店在聖誕節前幾星期聘請額外員工。"},{"en":"Demand rises before Christmas because people buy gifts, food, and decorations.","zh":"聖誕節前需求上升，因為人們購買禮物、食物和裝飾。"},{"en":"This phrase focuses on the lead-up period.","zh":"這個短語集中於節日前的準備時期。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":4},{"front":"the same period last year","meaning":"去年同期","examples":[{"en":"Sales were higher than during the same period last year.","zh":"銷售高於去年同期。"},{"en":"The same period last year means the matching weeks or months in the previous year.","zh":"the same period last year 是指上一年相同的幾星期或幾個月。"},{"en":"A shop compares December sales with the same period last year to judge real growth.","zh":"商店把12月銷售與去年同期比較，以判斷真正增長。"},{"en":"This comparison is fairer because shopping seasons affect sales strongly.","zh":"這種比較較公平，因為購物季節強烈影響銷售。"},{"en":"This phrase is common in business reports.","zh":"這個短語常見於商業報告。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":4},{"front":"according to","meaning":"根據","examples":[{"en":"According to comScore Networks, online sales were rising quickly.","zh":"根據 comScore Networks，網上銷售正在快速上升。"},{"en":"According to means based on what a person, report, or organisation says.","zh":"according to 是指根據某人、報告或機構所說。"},{"en":"According to the timetable, the store closes at nine.","zh":"根據時間表，店舖九點關門。"},{"en":"Writers use this phrase to show the source of information.","zh":"作者使用這個短語來顯示資訊來源。"},{"en":"This phrase reports a claim without necessarily proving it by itself.","zh":"這個短語報告一項說法，但本身不一定證明它。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":4},{"front":"research firm","meaning":"研究公司","examples":[{"en":"comScore Networks is a research firm.","zh":"comScore Networks 是一間研究公司。"},{"en":"A research firm is a company that collects and analyses information for clients or the public.","zh":"research firm 是為客戶或公眾收集和分析資訊的公司。"},{"en":"A research firm may study shopping habits, website traffic, or customer opinions.","zh":"研究公司可能研究購物習慣、網站流量或顧客意見。"},{"en":"Businesses use research firms to understand markets before making decisions.","zh":"企業在作決定前使用研究公司來理解市場。"},{"en":"This phrase refers to a company focused on data and analysis.","zh":"這個短語指專注於數據和分析的公司。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":4},{"front":"computer games","meaning":"電腦遊戲","examples":[{"en":"Online sales of computer games rose sharply.","zh":"電腦遊戲的網上銷售大幅上升。"},{"en":"Computer games are digital games played on computers or similar devices.","zh":"computer games 是在電腦或類似設備上玩的數碼遊戲。"},{"en":"Parents may buy computer games online as holiday gifts for children.","zh":"家長可能在網上購買電腦遊戲作為孩子的假日禮物。"},{"en":"Sales of games can rise quickly when new releases or discounts appear.","zh":"當新遊戲推出或有折扣時，遊戲銷售可以快速上升。"},{"en":"This phrase refers to game products rather than computer hardware.","zh":"這個短語指遊戲產品，而不是電腦硬件。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":4},{"front":"clothing and jewellery","meaning":"服裝和首飾","examples":[{"en":"Online sales of clothing and jewellery were more than 30 per cent higher.","zh":"服裝和首飾的網上銷售高出超過百分之三十。"},{"en":"Clothing and jewellery means clothes and decorative items such as rings, necklaces, or bracelets.","zh":"clothing and jewellery 是指衣服以及戒指、項鍊或手鏈等裝飾物品。"},{"en":"A shopper may buy clothing and jewellery online when size charts and photos are clear.","zh":"當尺寸表和照片清楚時，顧客可能在網上購買服裝和首飾。"},{"en":"Holiday demand can raise sales of clothing and jewellery because people buy gifts and party outfits.","zh":"假日需求可以提高服裝和首飾銷售，因為人們購買禮物和派對服裝。"},{"en":"This phrase groups fashion items together.","zh":"這個短語把時尚商品歸為一類。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":4},{"front":"more than 30 per cent higher","meaning":"高出超過百分之三十","examples":[{"en":"Online sales of several categories were more than 30 per cent higher.","zh":"幾個類別的網上銷售高出超過百分之三十。"},{"en":"More than 30 per cent higher means the figure increased by over 30% compared with another figure.","zh":"more than 30 per cent higher 是指數字比另一數字增加超過30%。"},{"en":"If this year’s sales are more than 30 per cent higher, a shop has grown strongly.","zh":"如果今年銷售高出超過百分之三十，店舖就有強勁增長。"},{"en":"Percentages help readers compare growth across different product categories.","zh":"百分比幫助讀者比較不同產品類別的增長。"},{"en":"This phrase signals a large measurable increase.","zh":"這個短語表示大型且可量度的增加。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":5},{"front":"get the most visitors","meaning":"獲最多訪客","examples":[{"en":"eBay and Amazon get the most visitors in many countries.","zh":"eBay 和 Amazon 在許多國家獲最多訪客。"},{"en":"To get the most visitors means to attract more website users than competitors.","zh":"get the most visitors 是指吸引比競爭者更多網站使用者。"},{"en":"A school notice page may get the most visitors when exam results are posted.","zh":"當考試結果公布時，學校通知頁可能獲最多訪客。"},{"en":"Websites get more visitors when they offer useful products, low prices, or trusted service.","zh":"當網站提供有用產品、低價或可信服務時，就會獲得更多訪客。"},{"en":"This phrase measures popularity by traffic.","zh":"這個短語以流量量度受歡迎程度。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":5},{"front":"pure Internet plays","meaning":"純互聯網業務","examples":[{"en":"eBay and Amazon are considered pure Internet plays.","zh":"eBay 和 Amazon 被視為純互聯網業務。"},{"en":"Pure Internet plays are businesses that operate mainly or entirely online rather than through physical shops.","zh":"pure Internet plays 是主要或完全在網上營運，而不是透過實體店營運的企業。"},{"en":"A food-delivery app with no restaurants of its own is a kind of internet-based business.","zh":"沒有自己餐廳的外賣應用程式，是一種互聯網業務。"},{"en":"Pure internet companies can grow quickly because they are not limited by store locations.","zh":"純互聯網公司可以快速成長，因為不受店舖位置限制。"},{"en":"This phrase contrasts online-only firms with traditional retailers.","zh":"這個短語把純網上公司與傳統零售商作對比。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":5},{"front":"physical shops","meaning":"實體店","examples":[{"en":"Pure Internet plays have no physical shops.","zh":"純互聯網業務沒有實體店。"},{"en":"Physical shops are real stores that customers can visit in person.","zh":"physical shops 是顧客可以親身到訪的真實店舖。"},{"en":"A customer may prefer physical shops when they want to try on clothes before buying.","zh":"當顧客想在購買前試穿衣服時，可能偏好實體店。"},{"en":"Physical shops build trust because customers can see staff, products, and return desks.","zh":"實體店建立信任，因為顧客可以看見員工、產品和退貨櫃位。"},{"en":"This phrase contrasts real-world stores with online websites.","zh":"這個短語把現實店舖與網上網站作對比。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":5},{"front":"business models","meaning":"商業模式","examples":[{"en":"Their business models have changed markedly.","zh":"它們的商業模式已明顯改變。"},{"en":"A business model is the way a company makes money and delivers value to customers.","zh":"business model 是公司賺錢並向顧客提供價值的方式。"},{"en":"A shop’s business model may rely on low prices, fast delivery, or personal service.","zh":"商店的商業模式可能依賴低價、快速送貨或個人化服務。"},{"en":"When technology changes, companies may need new business models to survive.","zh":"當科技改變，公司可能需要新商業模式才能生存。"},{"en":"This phrase explains how a business works, not just what it sells.","zh":"這個短語解釋企業如何運作，而不只是賣甚麼。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":5},{"front":"change markedly","meaning":"明顯改變","examples":[{"en":"Their business models have changed markedly.","zh":"它們的商業模式已明顯改變。"},{"en":"To change markedly means to change clearly and noticeably.","zh":"change markedly 是指清楚而明顯地改變。"},{"en":"A student’s writing can change markedly after regular feedback and practice.","zh":"學生在定期回饋和練習後，寫作可以明顯改變。"},{"en":"Retail changes markedly when customers move from stores to websites.","zh":"當顧客由店舖轉向網站，零售會明顯改變。"},{"en":"This phrase suggests a visible difference, not a small adjustment.","zh":"這個短語暗示可見差異，而不是小調整。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":5},{"front":"resemble online versions of","meaning":"像是……的網上版本","examples":[{"en":"They now resemble online versions of department stores.","zh":"它們現在像是百貨公司的網上版本。"},{"en":"To resemble online versions of something means to look or function like that thing on the internet.","zh":"resemble online versions of something 是指在網上看起來或運作起來像某事物。"},{"en":"A school portal may resemble an online version of the school office.","zh":"學校平台可能像是校務處的網上版本。"},{"en":"Amazon resembles a department store online because many sellers and product types are gathered together.","zh":"Amazon 像網上百貨公司，因為許多賣家和產品類型聚集在一起。"},{"en":"This phrase compares a digital service with a familiar physical model.","zh":"這個短語把數碼服務與熟悉的實體模式比較。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":5},{"front":"vast department stores","meaning":"大型百貨公司","examples":[{"en":"Amazon and eBay resemble vast department stores.","zh":"Amazon 和 eBay 像大型百貨公司。"},{"en":"Vast department stores are very large shops that sell many different types of goods.","zh":"vast department stores 是銷售許多不同商品的大型商店。"},{"en":"A vast department store may sell clothes, electronics, toys, furniture, and food in one place.","zh":"大型百貨公司可能在同一地方銷售衣服、電子產品、玩具、家具和食品。"},{"en":"Online platforms resemble department stores when customers can find almost everything there.","zh":"當顧客幾乎能在平台上找到所有東西，網上平台就像百貨公司。"},{"en":"This phrase suggests great size and wide product variety.","zh":"這個短語暗示規模很大和產品種類廣泛。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":5},{"front":"third-party merchants","meaning":"第三方商戶","examples":[{"en":"Thousands of third-party merchants sell goods on these platforms.","zh":"數以千計第三方商戶在這些平台上出售商品。"},{"en":"Third-party merchants are independent sellers who use another company’s platform to reach customers.","zh":"third-party merchants 是使用另一公司平台接觸顧客的獨立賣家。"},{"en":"A small shop may become a third-party merchant on Amazon to sell beyond its local area.","zh":"小店可能成為 Amazon 上的第三方商戶，把貨品賣到本地以外。"},{"en":"Platforms grow when many third-party merchants add more products and choices.","zh":"當許多第三方商戶加入更多產品和選擇，平台會成長。"},{"en":"This phrase separates outside sellers from the platform owner.","zh":"這個短語把外部賣家與平台擁有者分開。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":5},{"front":"offer their wares","meaning":"出售商品","examples":[{"en":"Third-party merchants offer their wares online.","zh":"第三方商戶在網上出售商品。"},{"en":"To offer their wares means to present their goods for sale.","zh":"offer their wares 是指展示商品以供出售。"},{"en":"At a market, small sellers offer their wares on tables and stalls.","zh":"在市集，小販在桌子和攤位上出售商品。"},{"en":"Online platforms let merchants offer their wares to customers far away.","zh":"網上平台讓商戶向遠方顧客出售商品。"},{"en":"This phrase is slightly old-fashioned and refers to selling goods.","zh":"這個短語稍帶舊式語感，指銷售貨品。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":5},{"front":"consumer electronics","meaning":"消費電子產品","examples":[{"en":"Amazon sold more consumer electronics than books during Thanksgiving in 2004.","zh":"2004年感恩節期間，Amazon 賣出的消費電子產品比書更多。"},{"en":"Consumer electronics are electronic products bought for personal use, such as phones, cameras, or speakers.","zh":"consumer electronics 是供個人使用的電子產品，例如手機、相機或喇叭。"},{"en":"A family may buy consumer electronics online because prices are easy to compare.","zh":"家庭可能在網上購買消費電子產品，因為價格容易比較。"},{"en":"Sales of electronics often rise during holidays because they are popular gifts.","zh":"電子產品銷售常在假期上升，因為它們是受歡迎禮物。"},{"en":"This phrase refers to everyday electronic goods for consumers.","zh":"這個短語指面向消費者的日常電子商品。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":5},{"front":"prove that","meaning":"證明","examples":[{"en":"Amazon proved that online retailing could be a huge business.","zh":"Amazon 證明網上零售可以成為龐大業務。"},{"en":"To prove that means to show something is true through evidence or results.","zh":"prove that 是指透過證據或結果顯示某事是真實的。"},{"en":"Good exam results can prove that steady revision works.","zh":"良好考試成績可以證明穩定溫習有效。"},{"en":"Strong sales proved that customers were willing to buy expensive items online.","zh":"強勁銷售證明顧客願意在網上購買昂貴商品。"},{"en":"This phrase links evidence with a conclusion.","zh":"這個短語把證據與結論連接起來。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":6},{"front":"online retailing","meaning":"網上零售","examples":[{"en":"Amazon helped prove that online retailing could be profitable.","zh":"Amazon 幫助證明網上零售可以有利可圖。"},{"en":"Online retailing is the business of selling goods to customers through the internet.","zh":"online retailing 是透過互聯網向顧客銷售商品的業務。"},{"en":"A supermarket does online retailing when customers order groceries through its website.","zh":"當超市讓顧客透過網站訂購食品雜貨，就是做網上零售。"},{"en":"Online retailing grows when payment, delivery, and customer service are reliable.","zh":"當付款、送貨和顧客服務可靠時，網上零售會增長。"},{"en":"This phrase describes retail business done online.","zh":"這個短語描述在網上進行的零售業務。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":6},{"front":"a huge business","meaning":"龐大業務","examples":[{"en":"Online retailing became a huge business.","zh":"網上零售成為龐大業務。"},{"en":"A huge business is an industry or activity that earns a lot of money and involves many customers.","zh":"huge business 是賺取大量金錢並涉及許多顧客的行業或活動。"},{"en":"Delivery apps became a huge business when many people began ordering meals from home.","zh":"當許多人開始在家叫餐，外賣應用程式成為龐大業務。"},{"en":"A business becomes huge when demand, technology, and trust grow together.","zh":"當需求、科技和信任一起增長，業務就會變得龐大。"},{"en":"This phrase stresses commercial size and importance.","zh":"這個短語強調商業規模和重要性。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":6},{"front":"lead the pack","meaning":"領先群雄","examples":[{"en":"Amazon still leads the pack in online retailing.","zh":"Amazon 在網上零售中仍然領先群雄。"},{"en":"To lead the pack means to be ahead of all competitors in a group.","zh":"lead the pack 是指在一群競爭者中處於最前。"},{"en":"A runner leads the pack when everyone else is behind her.","zh":"跑手若所有其他人都在她後面，就是領先群雄。"},{"en":"A company leads the pack when its sales, technology, or reputation are strongest.","zh":"當公司的銷售、科技或聲譽最強，它就領先群雄。"},{"en":"This phrase is informal and competitive.","zh":"這個短語較口語，帶競爭意味。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":6},{"front":"the online rise of","meaning":"……在網上的崛起","examples":[{"en":"The online rise of Wal-Mart is being closely watched.","zh":"沃爾瑪在網上的崛起正受到密切關注。"},{"en":"The online rise of a company means its growth and increasing importance on the internet.","zh":"online rise of a company 是指某公司在互聯網上的增長和重要性提升。"},{"en":"The online rise of a small brand can happen quickly if customers share its products on social media.","zh":"如果顧客在社交媒體分享產品，小品牌在網上的崛起可以很快發生。"},{"en":"Competitors watch a retailer’s online rise because it may change the market.","zh":"競爭者關注零售商在網上的崛起，因為它可能改變市場。"},{"en":"This phrase focuses on digital growth.","zh":"這個短語集中於數碼增長。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":6},{"front":"mighty Wal-Mart","meaning":"強大的沃爾瑪","examples":[{"en":"The passage describes Wal-Mart as a mighty retailer.","zh":"文章把沃爾瑪描述為強大的零售商。"},{"en":"Mighty Wal-Mart means Wal-Mart is powerful, large, and influential in retail.","zh":"mighty Wal-Mart 是指沃爾瑪在零售業中強大、龐大且有影響力。"},{"en":"A mighty company can negotiate lower prices because it buys goods in huge quantities.","zh":"強大的公司可以因大量採購而談判更低價格。"},{"en":"Wal-Mart’s size gives it advantages both in physical stores and online.","zh":"沃爾瑪的規模給它在線下店和網上都帶來優勢。"},{"en":"This phrase emphasises strength and scale.","zh":"這個短語強調力量和規模。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":6},{"front":"the world’s biggest retailer","meaning":"全球最大零售商","examples":[{"en":"Wal-Mart is described as the world’s biggest retailer.","zh":"沃爾瑪被描述為全球最大零售商。"},{"en":"The world’s biggest retailer means the largest retail company in the world by scale or sales.","zh":"world’s biggest retailer 是指按規模或銷售計算全球最大的零售公司。"},{"en":"A company with thousands of stores and huge sales may be called the world’s biggest retailer.","zh":"擁有數千間店和龐大銷售的公司，可能被稱為全球最大零售商。"},{"en":"Large scale can help a retailer offer low prices and broad product choice.","zh":"大規模可以幫助零售商提供低價和廣泛產品選擇。"},{"en":"This phrase highlights global size, not just local popularity.","zh":"這個短語強調全球規模，而不只是本地受歡迎程度。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":6},{"front":"be closely followed by","meaning":"被……緊隨其後","examples":[{"en":"Wal-Mart is being closely followed by Target.","zh":"沃爾瑪被 Target 緊隨其後。"},{"en":"To be closely followed by a competitor means another company is near behind in ranking or performance.","zh":"be closely followed by a competitor 是指另一家公司在排名或表現上緊接其後。"},{"en":"The top student was closely followed by two classmates with almost the same marks.","zh":"第一名學生被兩名分數幾乎相同的同學緊隨其後。"},{"en":"A close follower can become a serious threat if it grows quickly.","zh":"如果緊隨其後者快速增長，它可以成為嚴重威脅。"},{"en":"This phrase describes competition with a small gap.","zh":"這個短語描述差距很小的競爭。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":6},{"front":"chief supermarket rival","meaning":"主要超市競爭對手","examples":[{"en":"Target is described as Wal-Mart’s chief supermarket rival.","zh":"Target 被描述為沃爾瑪的主要超市競爭對手。"},{"en":"A chief rival is the main competitor in a market or activity.","zh":"chief rival 是市場或活動中的主要競爭者。"},{"en":"Two nearby supermarkets may be chief rivals if they fight for the same customers.","zh":"如果兩間附近超市爭取同一批顧客，它們可能是主要競爭對手。"},{"en":"A chief rival can force a company to improve prices, service, and product choice.","zh":"主要競爭對手可以迫使公司改善價格、服務和產品選擇。"},{"en":"This phrase identifies the most important competitor.","zh":"這個短語指出最重要的競爭者。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":6},{"front":"operate the fourth most popular","meaning":"經營第四受歡迎的……","examples":[{"en":"Target operates the fourth most popular retail website in America.","zh":"Target 經營美國第四受歡迎的零售網站。"},{"en":"To operate the fourth most popular website means to run a website ranked fourth by visitors or usage.","zh":"operate the fourth most popular website 是指營運一個按訪客或使用量排名第四的網站。"},{"en":"A school club may operate the second most popular student page on campus.","zh":"學生會可能經營校內第二受歡迎的學生網頁。"},{"en":"Ranking popularity helps compare online reach across organisations.","zh":"受歡迎程度排名幫助比較不同機構的網上覆蓋範圍。"},{"en":"This phrase combines management with ranking.","zh":"這個短語結合營運和排名。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":6},{"front":"retail site","meaning":"零售網站","examples":[{"en":"Argos is the third most popular retail site in Britain.","zh":"Argos 是英國第三受歡迎的零售網站。"},{"en":"A retail site is a website where customers can browse and buy products.","zh":"retail site 是顧客可以瀏覽和購買產品的網站。"},{"en":"A retail site may show product photos, prices, reviews, and delivery options.","zh":"零售網站可能展示產品照片、價格、評價和送貨選項。"},{"en":"A popular retail site can bring a company many customers without opening new shops.","zh":"受歡迎的零售網站可以不用開新店也為公司帶來許多顧客。"},{"en":"This phrase means an online retail website.","zh":"這個短語指網上零售網站。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":6},{"front":"catalogue merchant","meaning":"目錄零售商","examples":[{"en":"Argos is a catalogue merchant.","zh":"Argos 是一間目錄零售商。"},{"en":"A catalogue merchant is a retailer that sells goods through a catalogue of listed products.","zh":"catalogue merchant 是透過產品目錄銷售貨品的零售商。"},{"en":"Customers may choose items from a catalogue before ordering online or in a shop.","zh":"顧客可能先從目錄選擇商品，再網上下單或到店購買。"},{"en":"Catalogue merchants can move online easily because their business already depends on product listings.","zh":"目錄零售商較容易轉到網上，因為其業務本來已依賴產品列表。"},{"en":"This phrase refers to a seller built around catalogue-based shopping.","zh":"這個短語指以目錄購物為基礎的賣家。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":7},{"front":"supermarket chain","meaning":"連鎖超市","examples":[{"en":"Tesco is Britain’s biggest supermarket chain.","zh":"Tesco 是英國最大的連鎖超市。"},{"en":"A supermarket chain is a group of supermarkets owned or operated under the same brand.","zh":"supermarket chain 是由同一品牌擁有或營運的一組超市。"},{"en":"A supermarket chain can buy in bulk and sell food at lower prices.","zh":"連鎖超市可以大量採購並以較低價格出售食品。"},{"en":"Chain stores grow because customers recognise the brand in many locations.","zh":"連鎖店成長是因為顧客在許多地點都認得該品牌。"},{"en":"This phrase refers to a network of stores, not one single shop.","zh":"這個短語指店舖網絡，而不是單一店舖。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":7},{"front":"surf the web","meaning":"瀏覽互聯網","examples":[{"en":"Europeans are surfing the web in record numbers.","zh":"歐洲人正以創紀錄數量瀏覽互聯網。"},{"en":"To surf the web means to browse websites on the internet.","zh":"surf the web 是指在互聯網上瀏覽網站。"},{"en":"Students may surf the web to compare prices before buying textbooks.","zh":"學生可能在購買教科書前瀏覽互聯網來格價。"},{"en":"More people surf the web when internet access becomes cheaper and faster.","zh":"當網絡接入更便宜更快速，更多人會瀏覽互聯網。"},{"en":"This phrase is informal and means looking around online.","zh":"這個短語較口語，意思是在網上四處查看。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":7},{"front":"in record numbers","meaning":"數量創新高地","examples":[{"en":"Europeans are surfing the web in record numbers.","zh":"歐洲人正以創新高的數量瀏覽互聯網。"},{"en":"In record numbers means in greater numbers than ever before.","zh":"in record numbers 是指數量比以往任何時候都多。"},{"en":"Students joined the school fair in record numbers after it moved online.","zh":"校園嘉年華轉到網上後，學生參與人數創新高。"},{"en":"A website may receive visitors in record numbers during a major sale.","zh":"大型促銷期間，網站訪客數可能創新高。"},{"en":"This phrase highlights unusually high participation.","zh":"這個短語突顯異常高的參與度。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":7},{"front":"almost half","meaning":"接近一半","examples":[{"en":"Almost half of Europeans now visit retail websites.","zh":"現在接近一半歐洲人會到訪零售網站。"},{"en":"Almost half means nearly 50%, but not quite.","zh":"almost half 是指接近50%，但未完全達到。"},{"en":"Almost half the class chose online research instead of printed books.","zh":"接近一半學生選擇網上研究，而不是印刷書籍。"},{"en":"If almost half of customers use a service, it has become very common.","zh":"如果接近一半顧客使用某服務，它已變得很普遍。"},{"en":"This phrase gives an approximate large proportion.","zh":"這個短語給出一個大約的大比例。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":7},{"front":"traditional merchants","meaning":"傳統商戶","examples":[{"en":"Many Europeans visit the websites of traditional merchants.","zh":"許多歐洲人到訪傳統商戶的網站。"},{"en":"Traditional merchants are established sellers that usually have physical shops or older retail methods.","zh":"traditional merchants 是通常有實體店或舊式零售方法的既有賣家。"},{"en":"A family may trust traditional merchants because they have bought from them for years.","zh":"家庭可能信任傳統商戶，因為多年來一直向他們購物。"},{"en":"Traditional merchants can attract online customers by using their existing reputation.","zh":"傳統商戶可以利用已有聲譽吸引網上顧客。"},{"en":"This phrase contrasts older sellers with newer internet-only firms.","zh":"這個短語把較舊賣家與較新的純網上企業作對比。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":7},{"front":"leading retail websites","meaning":"主要零售網站","examples":[{"en":"The leading retail websites in Europe include Tchibo and OTTO.","zh":"歐洲主要零售網站包括 Tchibo 和 OTTO。"},{"en":"Leading retail websites are among the most popular or important online shopping sites.","zh":"leading retail websites 是最受歡迎或最重要的網上購物網站之一。"},{"en":"Leading websites often attract customers because they offer trust, range, and convenience.","zh":"主要網站常因提供信任、選擇和方便而吸引顧客。"},{"en":"A leading retail website can shape how other shops design their online services.","zh":"主要零售網站可以塑造其他店舖如何設計網上服務。"},{"en":"This phrase highlights market position.","zh":"這個短語突顯市場地位。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":7},{"front":"diversified chain","meaning":"多元化連鎖店","examples":[{"en":"Tchibo is a diversified chain.","zh":"Tchibo 是一間多元化連鎖店。"},{"en":"A diversified chain is a group of stores that sells or does several different kinds of business.","zh":"diversified chain 是銷售或經營多種不同業務的連鎖店。"},{"en":"A shop chain is diversified if it sells coffee, clothes, home goods, and services.","zh":"如果連鎖店售賣咖啡、服裝、家居用品和服務，它就是多元化的。"},{"en":"Diversification can reduce risk because the company does not depend on one product only.","zh":"多元化可以降低風險，因為公司不只依賴一種產品。"},{"en":"This phrase describes variety within a retail business.","zh":"這個短語描述零售業務內部的多樣性。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":7},{"front":"mail-order specialist","meaning":"郵購專門店","examples":[{"en":"OTTO is a German mail-order specialist.","zh":"OTTO 是德國郵購專門店。"},{"en":"A mail-order specialist is a retailer experienced in selling goods through catalogues and delivery orders.","zh":"mail-order specialist 是擅長透過目錄和送貨訂單銷售商品的零售商。"},{"en":"Before online shopping, customers ordered from mail-order specialists by phone or post.","zh":"在網上購物前，顧客透過電話或郵寄向郵購專門店訂貨。"},{"en":"Such companies could adapt online because they already understood remote selling and delivery.","zh":"這類公司能適應網上銷售，因為它們本已理解遠距離銷售和送貨。"},{"en":"This phrase refers to expertise in distance shopping.","zh":"這個短語指遠距離購物方面的專門能力。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":7},{"front":"high-street favourite","meaning":"商業街受歡迎品牌","examples":[{"en":"Fnac is a French high-street favourite.","zh":"Fnac 是法國商業街受歡迎品牌。"},{"en":"A high-street favourite is a well-liked shop commonly found or recognised in main shopping streets.","zh":"high-street favourite 是在主要購物街常見或受歡迎的店舖。"},{"en":"A bakery can become a high-street favourite if local families visit it every weekend.","zh":"如果本地家庭每週末都到訪，麵包店可以成為商業街受歡迎品牌。"},{"en":"High-street favourites can gain online customers because people already know the brand.","zh":"商業街受歡迎品牌可以獲得網上顧客，因為人們已認識該品牌。"},{"en":"This phrase suggests popularity in ordinary physical shopping areas.","zh":"這個短語暗示在普通實體購物區受歡迎。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":7},{"front":"far from","meaning":"不但沒有；遠非","examples":[{"en":"Far from wrecking retailers’ businesses, the web plays to their strengths.","zh":"網絡不但沒有摧毀零售商業務，反而發揮它們的優勢。"},{"en":"Far from means not at all; in fact, the opposite is true.","zh":"far from 是指完全不是；事實上，相反情況才是真的。"},{"en":"Far from wasting time, careful revision can make exam preparation more efficient.","zh":"仔細溫習不但沒有浪費時間，反而可以令備考更有效率。"},{"en":"Far from hurting stores, a good website may send more customers to them.","zh":"好網站不但沒有傷害店舖，反而可能帶更多顧客到店。"},{"en":"This phrase introduces a strong contrast with an expected idea.","zh":"這個短語引入與預期想法強烈相反的內容。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":7},{"front":"wreck retailers’ businesses","meaning":"摧毀零售商的業務","examples":[{"en":"The web has not wrecked retailers’ businesses.","zh":"網絡並沒有摧毀零售商的業務。"},{"en":"To wreck retailers’ businesses means to seriously damage or destroy shops’ ability to make money.","zh":"wreck retailers’ businesses 是指嚴重損害或摧毀商店賺錢的能力。"},{"en":"A sudden rent increase can wreck a small shop’s business if it cannot pay.","zh":"如果小店無法支付，突然加租可以摧毀其業務。"},{"en":"Online competition can hurt some retailers, but it can also create new sales channels.","zh":"網上競爭可以傷害某些零售商，但也可以創造新銷售渠道。"},{"en":"This phrase describes severe harm, not a small difficulty.","zh":"這個短語描述嚴重傷害，而不是小困難。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":8},{"front":"play to their strengths","meaning":"發揮……的優勢","examples":[{"en":"The web plays to the strengths of traditional retailers.","zh":"網絡發揮傳統零售商的優勢。"},{"en":"To play to someone’s strengths means to use what they are already good at.","zh":"play to someone’s strengths 是指運用某人或某組織本已擅長的地方。"},{"en":"A teacher plays to a student’s strengths by letting a good speaker lead discussions.","zh":"老師讓擅長說話的學生帶領討論，就是發揮其優勢。"},{"en":"Traditional retailers can use brand trust and store networks as online advantages.","zh":"傳統零售商可以把品牌信任和店舖網絡用作網上優勢。"},{"en":"This phrase suggests using existing advantages wisely.","zh":"這個短語暗示明智地運用既有優點。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":8},{"front":"shopping comparison sites","meaning":"購物比較網站","examples":[{"en":"Shopping comparison sites help users compare prices.","zh":"購物比較網站幫助使用者比較價格。"},{"en":"Shopping comparison sites are websites that show prices from different retailers for the same or similar products.","zh":"shopping comparison sites 是顯示不同零售商對相同或類似產品報價的網站。"},{"en":"A customer may use a comparison site before buying a laptop.","zh":"顧客買手提電腦前可能使用購物比較網站。"},{"en":"These sites save time because shoppers do not need to check every shop separately.","zh":"這些網站節省時間，因為購物者不需要逐間店檢查。"},{"en":"This phrase refers to websites built for price and product comparison.","zh":"這個短語指為價格和產品比較而設的網站。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":8},{"front":"fastest growing destinations","meaning":"增長最快的網站目的地","examples":[{"en":"Shopping comparison sites are among the fastest growing destinations on the web.","zh":"購物比較網站是網上增長最快的目的地之一。"},{"en":"Fastest growing destinations are websites or online places gaining visitors most quickly.","zh":"fastest growing destinations 是訪客增加最快的網站或網上地點。"},{"en":"A new homework platform may become one of the fastest growing destinations for students.","zh":"新功課平台可能成為學生中增長最快的網站之一。"},{"en":"Rapid growth usually means many users find the service useful or popular.","zh":"快速增長通常表示許多使用者覺得服務有用或受歡迎。"},{"en":"This phrase compares growth in online traffic.","zh":"這個短語比較網上流量的增長。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":8},{"front":"compare products","meaning":"比較產品","examples":[{"en":"These sites allow users to compare products.","zh":"這些網站讓使用者比較產品。"},{"en":"To compare products means to examine differences in price, quality, features, or reviews before buying.","zh":"compare products 是指購買前檢查價格、質素、功能或評價上的差異。"},{"en":"Shoppers compare products when choosing between two phones with different cameras.","zh":"購物者在兩部相機不同的手機之間選擇時，就是在比較產品。"},{"en":"Comparing products can prevent wasteful spending because customers understand their options.","zh":"比較產品可以防止浪費消費，因為顧客理解自己的選項。"},{"en":"This phrase focuses on careful choice before purchase.","zh":"這個短語集中於購買前的仔細選擇。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":8},{"front":"read reviews","meaning":"閱讀評價","examples":[{"en":"Users can read reviews before buying products.","zh":"使用者可以在購買產品前閱讀評價。"},{"en":"To read reviews means to look at other customers’ opinions or ratings before making a choice.","zh":"read reviews 是指在作選擇前查看其他顧客的意見或評分。"},{"en":"A student may read reviews before buying a printer for schoolwork.","zh":"學生可能在購買做功課用的打印機前閱讀評價。"},{"en":"Reviews can warn shoppers about poor quality, slow delivery, or good service.","zh":"評價可以提醒購物者注意低質素、送貨慢或良好服務。"},{"en":"This phrase shows how customers use other people’s experiences.","zh":"這個短語顯示顧客如何使用他人的經驗。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":8},{"front":"most important of all","meaning":"最重要的是","examples":[{"en":"Most important of all, users can see who offers the lowest prices.","zh":"最重要的是，使用者可以看見誰提供最低價格。"},{"en":"Most important of all means the next point is the most important among several points.","zh":"most important of all 是指接下來的一點是幾點之中最重要的。"},{"en":"A shop needs good products, friendly staff, and, most important of all, customer trust.","zh":"商店需要好產品、友善員工，最重要的是顧客信任。"},{"en":"This phrase helps writers highlight the strongest reason.","zh":"這個短語幫助作者突出最有力原因。"},{"en":"It signals that the following point deserves special attention.","zh":"它表示下一點值得特別注意。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":8},{"front":"offer the lowest prices","meaning":"提供最低價格","examples":[{"en":"Comparison sites show who is offering the lowest prices.","zh":"比較網站顯示誰正在提供最低價格。"},{"en":"To offer the lowest prices means to sell goods more cheaply than competitors.","zh":"offer the lowest prices 是指以比競爭者更便宜的價格出售商品。"},{"en":"A supermarket may offer the lowest prices by buying products in huge quantities.","zh":"超市可以透過大量採購來提供最低價格。"},{"en":"Low prices can attract shoppers, but service and trust also matter.","zh":"低價可以吸引購物者，但服務和信任也重要。"},{"en":"This phrase is about price competition.","zh":"這個短語關於價格競爭。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":8},{"front":"make money from","meaning":"從……賺錢","examples":[{"en":"Comparison sites make money from advertising.","zh":"比較網站從廣告賺錢。"},{"en":"To make money from something means to earn income through it.","zh":"make money from something 是指透過某事獲得收入。"},{"en":"A website may make money from ads, subscriptions, or commission fees.","zh":"網站可能從廣告、訂閱或佣金賺錢。"},{"en":"Companies choose business models based on where money can be made.","zh":"公司會根據哪裡可以賺錢來選擇商業模式。"},{"en":"This phrase explains the income source.","zh":"這個短語解釋收入來源。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":8},{"front":"charge retailers","meaning":"向零售商收費","examples":[{"en":"Some sites make money by charging retailers for clicks.","zh":"有些網站透過按點擊向零售商收費來賺錢。"},{"en":"To charge retailers means to ask shops or sellers to pay a fee.","zh":"charge retailers 是指要求商店或賣家支付費用。"},{"en":"A delivery platform may charge restaurants for each order it brings them.","zh":"外賣平台可能按每張訂單向餐廳收費。"},{"en":"Charging retailers for clicks means the comparison site earns money when users visit a seller.","zh":"按點擊向零售商收費，意思是當使用者到訪賣家網站時，比較網站就賺錢。"},{"en":"This phrase describes a payment system between businesses.","zh":"這個短語描述企業之間的付款制度。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":8},{"front":"click on a link","meaning":"點擊連結","examples":[{"en":"Users click on a link to the retailer’s website.","zh":"使用者點擊通往零售商網站的連結。"},{"en":"To click on a link means to press a web link so that a new page opens.","zh":"click on a link 是指按下網頁連結，使新頁面打開。"},{"en":"Students click on a link in an email to join an online lesson.","zh":"學生點擊電郵中的連結來加入網上課堂。"},{"en":"Each click can send a potential customer from a comparison site to a shop.","zh":"每次點擊都可以把潛在顧客從比較網站送到商店。"},{"en":"This phrase describes a basic online action.","zh":"這個短語描述基本網上動作。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":8},{"front":"huge economies of scale","meaning":"巨大的規模經濟","examples":[{"en":"Retail giants benefit from huge economies of scale.","zh":"零售巨頭受益於巨大的規模經濟。"},{"en":"Huge economies of scale are cost advantages that large companies get because they buy or produce in very large quantities.","zh":"huge economies of scale 是大公司因大量購買或生產而獲得的成本優勢。"},{"en":"A big supermarket can sell cheaper milk if it buys from suppliers in massive volumes.","zh":"大型超市如果向供應商大量採購，就可以出售較便宜牛奶。"},{"en":"Economies of scale can help large retailers offer lower prices than small shops.","zh":"規模經濟可以幫助大型零售商提供比小店更低的價格。"},{"en":"This phrase explains why size can reduce costs.","zh":"這個短語解釋為何規模可以降低成本。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":9},{"front":"it is hardly surprising that","meaning":"……並不令人意外","examples":[{"en":"It is hardly surprising that Wal-Mart often offers cheap prices.","zh":"沃爾瑪常提供便宜價格，這並不令人意外。"},{"en":"It is hardly surprising that means something is expected and not shocking.","zh":"it is hardly surprising that 是指某事是預期之內，並不令人震驚。"},{"en":"It is hardly surprising that students do better when they practise every day.","zh":"學生每天練習後表現更好，這並不令人意外。"},{"en":"Large retailers often offer low prices because their size gives them cost advantages.","zh":"大型零售商常提供低價，因為其規模給它們成本優勢。"},{"en":"This phrase introduces a result that makes sense.","zh":"這個短語引入合理的結果。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":9},{"front":"emerge as","meaning":"成為；顯現為","examples":[{"en":"Wal-Mart often emerges as the cheapest vendor.","zh":"沃爾瑪常顯現為最便宜的賣方。"},{"en":"To emerge as something means to become recognised as that thing after comparison or development.","zh":"emerge as something 是指經過比較或發展後被認定為某種身份。"},{"en":"A quiet student may emerge as the group leader during a difficult project.","zh":"安靜學生可能在困難項目中成為小組領袖。"},{"en":"A retailer emerges as cheapest when price comparisons show it offers the lowest price.","zh":"當價格比較顯示零售商提供最低價，它就成為最便宜者。"},{"en":"This phrase suggests a status becoming clear.","zh":"這個短語暗示某種地位變得清楚。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":9},{"front":"the vendor offering","meaning":"提供……的賣方","examples":[{"en":"Wal-Mart often emerges as the vendor offering the cheapest prices.","zh":"沃爾瑪常成為提供最低價格的賣方。"},{"en":"The vendor offering something means the seller providing that product, price, or service.","zh":"vendor offering something 是指提供某產品、價格或服務的賣方。"},{"en":"A school may choose the vendor offering the safest transport service.","zh":"學校可能選擇提供最安全交通服務的供應商。"},{"en":"Customers often choose the vendor offering the lowest price if quality seems similar.","zh":"如果質素看似相近，顧客常選擇提供最低價格的賣方。"},{"en":"This phrase identifies a seller by what it provides.","zh":"這個短語按賣方提供的東西來識別它。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":9},{"front":"cheapest prices","meaning":"最低價格","examples":[{"en":"Large retailers often offer the cheapest prices.","zh":"大型零售商常提供最低價格。"},{"en":"Cheapest prices are the lowest prices available among competing sellers.","zh":"cheapest prices 是競爭賣家之中可找到的最低價格。"},{"en":"A customer may use comparison sites to find the cheapest prices for a camera.","zh":"顧客可能使用比較網站尋找相機的最低價格。"},{"en":"Cheap prices attract shoppers, especially when money is tight.","zh":"低價吸引購物者，尤其在金錢緊張時。"},{"en":"This phrase focuses on cost, not necessarily quality.","zh":"這個短語集中於成本，而不一定是質素。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":9},{"front":"besides attracting","meaning":"除了吸引……之外","examples":[{"en":"Besides attracting online purchases, comparison searches can advertise stores.","zh":"除了吸引網上購買之外，比較搜尋也可以為店舖做宣傳。"},{"en":"Besides attracting means in addition to bringing in or drawing something.","zh":"besides attracting 是指除了帶來或吸引某事之外。"},{"en":"Besides attracting tourists, a museum can educate local students.","zh":"除了吸引遊客之外，博物館也可以教育本地學生。"},{"en":"Comparison sites do more than create online sales; they also guide shoppers to brands.","zh":"比較網站不只創造網上銷售，也引導購物者認識品牌。"},{"en":"This phrase adds another benefit or effect.","zh":"這個短語加入另一個好處或效果。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":9},{"front":"online purchase","meaning":"網上購買","examples":[{"en":"Comparison searches can attract an online purchase.","zh":"比較搜尋可以吸引一次網上購買。"},{"en":"An online purchase is a product or service bought through the internet.","zh":"online purchase 是透過互聯網購買的產品或服務。"},{"en":"A customer makes an online purchase when she orders shoes from a website.","zh":"顧客從網站訂購鞋子時，就是完成網上購買。"},{"en":"Clear prices and reviews can turn browsing into an online purchase.","zh":"清楚價格和評價可以把瀏覽轉化為網上購買。"},{"en":"This phrase refers to a completed act of buying online.","zh":"這個短語指已完成的網上購買行為。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":9},{"front":"ordinary retailers","meaning":"一般零售商","examples":[{"en":"Ordinary retailers can use comparison searches to attract customers.","zh":"一般零售商可以使用比較搜尋來吸引顧客。"},{"en":"Ordinary retailers are normal shops or sellers, not necessarily huge chains or internet giants.","zh":"ordinary retailers 是普通商店或賣家，不一定是大型連鎖或網絡巨頭。"},{"en":"A small electronics shop is an ordinary retailer if it sells directly to local customers.","zh":"小型電子產品店若直接賣給本地顧客，就是一般零售商。"},{"en":"Online tools can help ordinary retailers compete with larger companies.","zh":"網上工具可以幫助一般零售商與大型公司競爭。"},{"en":"This phrase refers to regular retail businesses.","zh":"這個短語指普通零售業務。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":9},{"front":"a relatively cheap way to","meaning":"相對便宜的方法去……","examples":[{"en":"Comparison sites are a relatively cheap way to advertise.","zh":"比較網站是一種相對便宜的宣傳方法。"},{"en":"A relatively cheap way to do something means a method that costs less than many alternatives.","zh":"relatively cheap way to do something 是指比許多其他選擇成本較低的方法。"},{"en":"Posting on social media is a relatively cheap way to promote a school event.","zh":"在社交媒體發帖是宣傳學校活動的相對便宜方法。"},{"en":"Small shops may choose cheap advertising because their budgets are limited.","zh":"小店可能選擇便宜廣告，因為預算有限。"},{"en":"This phrase compares cost with other possible methods.","zh":"這個短語把成本與其他可能方法比較。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":9},{"front":"attract consumers to","meaning":"吸引消費者到……","examples":[{"en":"Retailers can attract consumers to their physical stores.","zh":"零售商可以吸引消費者到實體店。"},{"en":"To attract consumers to a place means to make shoppers interested enough to go there.","zh":"attract consumers to a place 是指令購物者有足夠興趣前往某地。"},{"en":"A café may attract consumers with free Wi-Fi and comfortable seats.","zh":"咖啡店可以用免費 Wi-Fi 和舒適座位吸引消費者。"},{"en":"Online ads can attract consumers to stores by showing local stock and discounts.","zh":"網上廣告可以透過展示本地存貨和折扣，吸引消費者到店。"},{"en":"This phrase focuses on drawing customers in.","zh":"這個短語集中於吸引顧客進來。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":9},{"front":"physical stores","meaning":"實體店","examples":[{"en":"Online searches can also bring consumers to physical stores.","zh":"網上搜尋也可以把消費者帶到實體店。"},{"en":"Physical stores are real shops customers can enter, browse, and buy from in person.","zh":"physical stores 是顧客可以親身進入、瀏覽和購買的真實店舖。"},{"en":"A physical store lets customers touch products before deciding.","zh":"實體店讓顧客在決定前觸摸產品。"},{"en":"Online information can support physical stores by telling customers where items are available.","zh":"網上資訊可以告訴顧客哪些店有貨，從而支援實體店。"},{"en":"This phrase contrasts real shops with online shops.","zh":"這個短語把真實店舖與網上商店作對比。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":9},{"front":"expand stores online","meaning":"將店舖擴展至網上","examples":[{"en":"Traditional retailers are expanding their stores online.","zh":"傳統零售商正將店舖擴展至網上。"},{"en":"To expand stores online means to add internet sales or services to an existing shop business.","zh":"expand stores online 是指為現有店舖業務加入網上銷售或服務。"},{"en":"A bookstore expands online when customers can order books through its website.","zh":"當書店讓顧客透過網站訂書，就是把店舖擴展至網上。"},{"en":"Online expansion helps shops reach customers who cannot visit in person.","zh":"網上擴展幫助店舖接觸無法親身到訪的顧客。"},{"en":"This phrase describes moving retail activity into digital space.","zh":"這個短語描述把零售活動移到數碼空間。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":10},{"front":"in cyberspace","meaning":"在網絡空間","examples":[{"en":"In cyberspace, even the biggest store has fewer physical limits.","zh":"在網絡空間，即使最大的店也有較少實體限制。"},{"en":"In cyberspace means on the internet or in the online world.","zh":"in cyberspace 是指在互聯網或網上世界中。"},{"en":"A small business can look much larger in cyberspace if its website is well designed.","zh":"如果網站設計良好，小企業在網絡空間中可以看起來大得多。"},{"en":"Cyberspace removes some limits of shelves, buildings, and local geography.","zh":"網絡空間移除某些貨架、建築和本地地理限制。"},{"en":"This phrase contrasts online space with physical space.","zh":"這個短語把網上空間與實體空間作對比。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":10},{"front":"super-centre","meaning":"大型超級購物中心","examples":[{"en":"Even the biggest super-centre faces fewer limits online.","zh":"即使最大的超級購物中心在線上也面對較少限制。"},{"en":"A super-centre is a very large retail store that sells many types of goods, often including groceries.","zh":"super-centre 是售賣許多類型商品的大型零售店，通常包括食品雜貨。"},{"en":"A family may visit a super-centre to buy food, clothes, toys, and household items at once.","zh":"家庭可能到大型超級購物中心一次過買食物、衣服、玩具和家居用品。"},{"en":"Online stores can offer even more variety than a super-centre because they do not need shelf space.","zh":"網上商店可以比大型超級購物中心提供更多種類，因為不需要貨架空間。"},{"en":"This phrase suggests a very large physical store.","zh":"這個短語暗示非常大型的實體店。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":10},{"front":"be unconstrained by","meaning":"不受……限制","examples":[{"en":"Online stores are unconstrained by planning laws.","zh":"網上商店不受規劃法例限制。"},{"en":"To be unconstrained by something means not to be limited or restricted by it.","zh":"be unconstrained by something 是指不受某事限制或約束。"},{"en":"Online classes are unconstrained by classroom size if many students can join remotely.","zh":"如果許多學生可以遙距加入，網上課堂就不受課室大小限制。"},{"en":"Shops online are less constrained by building space than physical stores.","zh":"網上店舖比實體店較少受建築空間限制。"},{"en":"This phrase shows freedom from a specific limitation.","zh":"這個短語顯示不受某個特定限制約束。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":10},{"front":"planning laws","meaning":"規劃法例","examples":[{"en":"Physical store expansion may be limited by planning laws.","zh":"實體店擴展可能受規劃法例限制。"},{"en":"Planning laws are rules that control how land and buildings can be used or developed.","zh":"planning laws 是控制土地和建築如何使用或發展的規則。"},{"en":"A shop may need permission under planning laws before opening a large new store.","zh":"店舖開設大型新店前，可能需要根據規劃法例取得許可。"},{"en":"Planning laws can slow expansion if neighbours or councils object.","zh":"如果鄰居或地方政府反對，規劃法例可以拖慢擴展。"},{"en":"This phrase refers to legal rules about physical development.","zh":"這個短語指關於實體發展的法律規則。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":10},{"front":"be dogged by protests","meaning":"不斷受到抗議困擾","examples":[{"en":"Wal-Mart is often dogged by protests when it expands offline.","zh":"沃爾瑪擴展線下業務時常不斷受到抗議困擾。"},{"en":"To be dogged by protests means to be repeatedly troubled by public opposition.","zh":"be dogged by protests 是指反覆受到公眾反對困擾。"},{"en":"A new road project may be dogged by protests from residents worried about noise.","zh":"新道路項目可能因居民擔心噪音而不斷受到抗議困擾。"},{"en":"Protests can delay expansion and damage a company’s public image.","zh":"抗議可以延誤擴展並損害公司公眾形象。"},{"en":"This phrase suggests persistent problems that follow a project.","zh":"這個短語暗示項目被持續問題纏繞。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":10},{"front":"expand offline","meaning":"擴展線下業務","examples":[{"en":"Wal-Mart sometimes faces protests when it expands offline.","zh":"沃爾瑪擴展線下業務時有時面對抗議。"},{"en":"To expand offline means to grow physical stores or real-world operations, not just online services.","zh":"expand offline 是指擴展實體店或現實世界業務，而不只是網上服務。"},{"en":"An online brand expands offline when it opens its first shop in a mall.","zh":"當網上品牌在商場開設第一間店時，就是擴展線下業務。"},{"en":"Offline expansion can face rent, planning laws, and local opposition.","zh":"線下擴展可能面對租金、規劃法例和本地反對。"},{"en":"This phrase contrasts physical growth with online growth.","zh":"這個短語把實體增長與網上增長作對比。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":10},{"front":"test the market for","meaning":"測試……的市場反應","examples":[{"en":"Wal-Mart and Target use the web to test the market for certain products.","zh":"沃爾瑪和 Target 使用網絡測試某些產品的市場反應。"},{"en":"To test the market for a product means to see whether customers want it before selling it more widely.","zh":"test the market for a product 是指在更廣泛銷售前了解顧客是否想要它。"},{"en":"A bakery may test the market for a new cake by selling it for one weekend.","zh":"麵包店可能透過在一個週末出售新蛋糕來測試市場反應。"},{"en":"Testing the market reduces risk because retailers learn demand before stocking many stores.","zh":"測試市場可以降低風險，因為零售商在大量鋪貨前先了解需求。"},{"en":"This phrase describes trying a product with customers before full launch.","zh":"這個短語描述在全面推出前讓顧客試驗產品。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":10},{"front":"certain products","meaning":"某些產品","examples":[{"en":"Retailers test certain products online before sending them to stores.","zh":"零售商先在網上測試某些產品，再送到店舖。"},{"en":"Certain products means particular products, not all products.","zh":"certain products 是指特定產品，而不是所有產品。"},{"en":"A shop may test certain products, such as new toys, before ordering large quantities.","zh":"商店可能先測試某些產品，例如新玩具，再大量訂貨。"},{"en":"Online testing helps retailers decide which products deserve shelf space.","zh":"網上測試幫助零售商決定哪些產品值得佔用貨架空間。"},{"en":"This phrase narrows attention to selected items.","zh":"這個短語把注意力收窄到被選中的商品。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":10},{"front":"conventional shopkeepers","meaning":"傳統店主","examples":[{"en":"Conventional shopkeepers were late coming to the Internet.","zh":"傳統店主較遲進入互聯網。"},{"en":"Conventional shopkeepers are traditional store owners or retailers who sell through physical shops.","zh":"conventional shopkeepers 是透過實體店銷售的傳統店主或零售商。"},{"en":"A conventional shopkeeper may know local customers well but struggle with online tools.","zh":"傳統店主可能很熟悉本地顧客，但不擅長網上工具。"},{"en":"Traditional shopkeepers joined the internet late because their businesses were built around stores.","zh":"傳統店主較遲加入互聯網，因為其業務本來圍繞實體店建立。"},{"en":"This phrase contrasts old retail habits with digital retailing.","zh":"這個短語把舊零售習慣與數碼零售作對比。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":10},{"front":"be late coming to","meaning":"較遲進入……","examples":[{"en":"Conventional retailers were late coming to the Internet.","zh":"傳統零售商較遲進入互聯網。"},{"en":"To be late coming to something means to start using or joining it later than others.","zh":"be late coming to something 是指比其他人較遲開始使用或加入某事。"},{"en":"Some teachers were late coming to online platforms because they preferred paper materials.","zh":"有些老師較遲使用網上平台，因為他們偏好紙本材料。"},{"en":"A business that comes late to a market may have to catch up quickly.","zh":"較遲進入市場的企業可能必須快速追趕。"},{"en":"This phrase describes delayed adoption.","zh":"這個短語描述延遲採用。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":10},{"front":"realise that","meaning":"意識到","examples":[{"en":"Retailers realise that they can offer more to customers online.","zh":"零售商意識到他們可以在網上向顧客提供更多。"},{"en":"To realise that means to understand or become aware of a fact.","zh":"realise that 是指理解或意識到某個事實。"},{"en":"A student may realise that short daily revision works better than last-minute study.","zh":"學生可能意識到每日短時間溫習比臨急抱佛腳更有效。"},{"en":"Retailers realised online stores could show more products than physical shelves.","zh":"零售商意識到網上商店可以展示比實體貨架更多產品。"},{"en":"This phrase marks a new understanding.","zh":"這個短語標示新的理解。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":11},{"front":"offer more to","meaning":"向……提供更多","examples":[{"en":"Retailers can offer more to their customers online.","zh":"零售商可以在網上向顧客提供更多。"},{"en":"To offer more to customers means to provide extra choice, service, information, or convenience.","zh":"offer more to customers 是指提供更多選擇、服務、資訊或方便。"},{"en":"A library offers more to students when it adds e-books and online databases.","zh":"圖書館加入電子書和網上資料庫時，就是向學生提供更多。"},{"en":"Online stores can offer more because they are not limited by shelf space.","zh":"網上商店可以提供更多，因為不受貨架空間限制。"},{"en":"This phrase is about increasing customer value.","zh":"這個短語關於增加顧客價值。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":11},{"front":"the technology required to","meaning":"……所需的科技","examples":[{"en":"The technology required to sell online is relatively easy to use.","zh":"網上銷售所需的科技相對容易使用。"},{"en":"The technology required to do something means the tools or systems needed for that activity.","zh":"technology required to do something 是指做某活動所需的工具或系統。"},{"en":"The technology required to teach online may include a camera, microphone, and stable internet.","zh":"網上教學所需的科技可能包括攝影機、麥克風和穩定網絡。"},{"en":"If the required technology is simple, more businesses can adopt it.","zh":"如果所需科技簡單，更多企業可以採用。"},{"en":"This phrase identifies the technical tools needed for a task.","zh":"這個短語指出某任務所需的技術工具。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":11},{"front":"relatively easy to use","meaning":"相對容易使用","examples":[{"en":"The technology is relatively easy to use.","zh":"這項科技相對容易使用。"},{"en":"Relatively easy to use means not too difficult compared with other tools or systems.","zh":"relatively easy to use 是指與其他工具或系統相比不太困難。"},{"en":"A simple payment app is relatively easy to use if older customers can learn it quickly.","zh":"如果年長顧客能快速學會，簡單付款應用程式就是相對容易使用。"},{"en":"Easy technology helps small retailers start selling online without huge training costs.","zh":"容易使用的科技幫助小零售商不用高昂培訓成本也能開始網上銷售。"},{"en":"This phrase compares ease with expected difficulty.","zh":"這個短語把容易程度與預期困難作比較。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":11},{"front":"most profitable customers","meaning":"最有利可圖的顧客","examples":[{"en":"Retailers’ most profitable customers like online convenience.","zh":"零售商最有利可圖的顧客喜歡網上方便。"},{"en":"Most profitable customers are the customers who bring the highest profit to a business.","zh":"most profitable customers 是為企業帶來最高利潤的顧客。"},{"en":"A shop’s most profitable customers may buy regularly and choose higher-value items.","zh":"商店最有利可圖的顧客可能經常購買並選擇較高價商品。"},{"en":"Retailers pay attention to these customers because losing them can hurt profits strongly.","zh":"零售商重視這些顧客，因為失去他們會嚴重影響利潤。"},{"en":"This phrase focuses on customer value to the business.","zh":"這個短語集中於顧客對企業的價值。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":11},{"front":"the convenience of","meaning":"……的方便","examples":[{"en":"Customers appreciate the convenience of an online offering.","zh":"顧客欣賞網上服務的方便。"},{"en":"The convenience of something means the ease and time-saving benefit it provides.","zh":"convenience of something 是指某事提供的容易程度和節省時間的好處。"},{"en":"Parents like the convenience of ordering groceries from home after work.","zh":"父母喜歡下班後在家訂購食品雜貨的方便。"},{"en":"Convenience can make customers choose one service over another.","zh":"方便可以令顧客選擇一項服務而不是另一項。"},{"en":"This phrase explains why something is easy or useful in daily life.","zh":"這個短語解釋某事為何在日常生活中容易或有用。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":11},{"front":"online offering","meaning":"網上服務；網上產品","examples":[{"en":"A strong online offering can complement store shopping.","zh":"強大的網上服務可以補充店內購物。"},{"en":"An online offering is the products, services, or information a company provides through the internet.","zh":"online offering 是公司透過互聯網提供的產品、服務或資訊。"},{"en":"A bookstore’s online offering may include home delivery, stock checks, and e-books.","zh":"書店的網上服務可能包括送貨到家、查庫存和電子書。"},{"en":"A good online offering can support customers before and after they visit a store.","zh":"良好的網上服務可以在顧客到店前後提供支援。"},{"en":"This phrase refers to what a business provides online.","zh":"這個短語指企業在網上提供的東西。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":11},{"front":"complementary to","meaning":"與……相輔相成","examples":[{"en":"The online offering is complementary to the in-store experience.","zh":"網上服務與店內體驗相輔相成。"},{"en":"Complementary to something means working well with it and making it more complete.","zh":"complementary to something 是指與某事配合良好，並令它更完整。"},{"en":"Online notes are complementary to classroom teaching when they help students review at home.","zh":"當網上筆記幫助學生在家複習時，它與課堂教學相輔相成。"},{"en":"A website and a physical store can support each other instead of competing directly.","zh":"網站和實體店可以互相支援，而不是直接競爭。"},{"en":"This phrase shows two things helping each other.","zh":"這個短語顯示兩件事互相幫助。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":11},{"front":"in-store experience","meaning":"店內體驗","examples":[{"en":"Customers may enjoy both online convenience and the in-store experience.","zh":"顧客可能同時享受網上方便和店內體驗。"},{"en":"The in-store experience is what customers feel and do when they visit a physical shop.","zh":"in-store experience 是顧客到訪實體店時的感受和行為。"},{"en":"Good lighting, helpful staff, and clear displays improve the in-store experience.","zh":"良好燈光、 helpful staff 和清晰陳列可以改善店內體驗。"},{"en":"Some shoppers still visit stores because they enjoy seeing products in person.","zh":"有些購物者仍到店購物，因為他們喜歡親身看產品。"},{"en":"This phrase focuses on the customer’s real-world shopping experience.","zh":"這個短語集中於顧客的現實購物體驗。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":11},{"front":"successful examples of","meaning":"……的成功例子","examples":[{"en":"Mr Silverstein points to successful examples of this approach.","zh":"Silverstein 先生指出這種做法的成功例子。"},{"en":"Successful examples of something are cases that show a method has worked well.","zh":"successful examples of something 是顯示某方法運作良好的個案。"},{"en":"A teacher may show successful examples of essays before students write their own.","zh":"老師可能在學生寫作前展示成功文章例子。"},{"en":"Examples help people trust an approach because they can see real results.","zh":"例子幫助人信任某做法，因為他們能看見實際結果。"},{"en":"This phrase introduces proof through cases.","zh":"這個短語透過個案引入證據。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":11},{"front":"this approach","meaning":"這種做法","examples":[{"en":"Several retailers have succeeded with this approach.","zh":"幾間零售商透過這種做法取得成功。"},{"en":"This approach means the method or strategy just mentioned.","zh":"this approach 是指剛提到的方法或策略。"},{"en":"A school may use this approach if short daily practice helps students more than long weekly tests.","zh":"如果每日短練習比每週長測驗更能幫助學生，學校可能使用這種做法。"},{"en":"Retailers use this approach when they combine online services with store advantages.","zh":"零售商結合網上服務和店舖優勢時，就是使用這種做法。"},{"en":"This phrase refers back to a plan or method.","zh":"這個短語指回某個計劃或方法。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":11},{"front":"point to","meaning":"指出；舉出","examples":[{"en":"Mr Silverstein points to Neiman Marcus as an example.","zh":"Silverstein 先生舉出 Neiman Marcus 作為例子。"},{"en":"To point to something means to mention it as evidence or an example.","zh":"point to something 是指提及某事作為證據或例子。"},{"en":"A teacher may point to a student’s improved draft as proof that feedback worked.","zh":"老師可能指出學生改善了的草稿，以證明回饋有效。"},{"en":"Analysts point to strong online sales when arguing that retail habits are changing.","zh":"分析員指出強勁網上銷售，以主張零售習慣正在改變。"},{"en":"This phrase introduces supporting evidence.","zh":"這個短語引入支持證據。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":12},{"front":"take a lead in","meaning":"在……方面領先","examples":[{"en":"Neiman Marcus has taken a lead in online top-end fashion.","zh":"Neiman Marcus 在網上高端時裝方面領先。"},{"en":"To take a lead in something means to become one of the first or strongest performers in that area.","zh":"take a lead in something 是指在某領域成為最早或最強的參與者之一。"},{"en":"A school can take a lead in digital learning by training teachers early.","zh":"學校可以透過及早培訓老師，在數碼學習方面領先。"},{"en":"Companies that take a lead often shape what competitors do next.","zh":"領先的公司常塑造競爭者下一步如何做。"},{"en":"This phrase suggests early strength and influence.","zh":"這個短語暗示早期優勢和影響力。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":12},{"front":"online top-end fashion","meaning":"網上高端時裝","examples":[{"en":"Neiman Marcus has taken a lead in online top-end fashion.","zh":"Neiman Marcus 在網上高端時裝方面領先。"},{"en":"Online top-end fashion means expensive, high-quality fashion sold through the internet.","zh":"online top-end fashion 是透過互聯網銷售的昂貴高質時裝。"},{"en":"A luxury store sells online top-end fashion when customers buy designer clothes from its website.","zh":"當奢侈品店讓顧客從網站購買設計師服裝時，就是銷售網上高端時裝。"},{"en":"High-end fashion needs strong trust online because products are costly.","zh":"高端時裝在線上需要強大信任，因為產品價格高。"},{"en":"This phrase combines luxury retail with internet shopping.","zh":"這個短語結合奢華零售與網上購物。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":12},{"front":"lingerie","meaning":"女裝內衣","examples":[{"en":"Victoria’s Secret is a successful online retailer in lingerie.","zh":"Victoria’s Secret 是女裝內衣方面成功的網上零售商。"},{"en":"Lingerie means women’s underwear and related intimate clothing.","zh":"lingerie 是女裝內衣及相關貼身衣物。"},{"en":"Customers may buy lingerie online if size guides and return policies are clear.","zh":"如果尺寸指南和退貨政策清楚，顧客可能在網上購買女裝內衣。"},{"en":"Privacy can make online lingerie shopping attractive to some customers.","zh":"私隱可以令網上內衣購物對某些顧客更有吸引力。"},{"en":"This word refers to a specific clothing category.","zh":"這個詞指一個特定服裝類別。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":12},{"front":"a pioneer of","meaning":"……的先驅","examples":[{"en":"Circuit City was a pioneer of the pick-up in-store option.","zh":"Circuit City 是網上下單、店內取貨選項的先驅。"},{"en":"A pioneer of something is one of the first people or companies to develop or use it.","zh":"pioneer of something 是最早發展或使用某事的人或公司之一。"},{"en":"A teacher who used online videos early may be a pioneer of digital learning.","zh":"很早使用網上影片的老師可能是數碼學習的先驅。"},{"en":"Pioneers take risks because they try methods before others know they will work.","zh":"先驅會承擔風險，因為他們在其他人知道方法有效前先嘗試。"},{"en":"This phrase gives credit for early innovation.","zh":"這個短語肯定早期創新。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":12},{"front":"pick-up in-store option","meaning":"網上下單、店內取貨選項","examples":[{"en":"The pick-up in-store option is popular with Internet shoppers.","zh":"網上下單、店內取貨選項受網上購物者歡迎。"},{"en":"A pick-up in-store option lets customers order online and collect the goods from a physical shop.","zh":"pick-up in-store option 讓顧客網上下單，並到實體店領取貨品。"},{"en":"A customer may choose pick-up in-store to avoid delivery fees.","zh":"顧客可能選擇店內取貨，以避免送貨費。"},{"en":"This option combines online convenience with the reassurance of a local store.","zh":"這個選項結合網上方便和本地店舖的安心感。"},{"en":"This phrase describes a hybrid shopping service.","zh":"這個短語描述混合式購物服務。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":12},{"front":"prove increasingly popular with","meaning":"越來越受……歡迎","examples":[{"en":"The option is proving increasingly popular with Internet shoppers.","zh":"這個選項越來越受網上購物者歡迎。"},{"en":"To prove increasingly popular with a group means to become more and more liked by them.","zh":"prove increasingly popular with a group 是指越來越受某群體喜愛。"},{"en":"Mobile payment is proving increasingly popular with busy commuters.","zh":"流動支付越來越受忙碌通勤者歡迎。"},{"en":"A service becomes popular when it solves a real customer problem.","zh":"當服務解決真正顧客問題時，就會受歡迎。"},{"en":"This phrase shows rising approval over time.","zh":"這個短語顯示認可度隨時間上升。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":12},{"front":"Internet shoppers","meaning":"網上購物者","examples":[{"en":"Internet shoppers increasingly use pick-up in-store services.","zh":"網上購物者越來越多使用店內取貨服務。"},{"en":"Internet shoppers are people who buy products or services online.","zh":"Internet shoppers 是在網上購買產品或服務的人。"},{"en":"Internet shoppers often compare prices and read reviews before buying.","zh":"網上購物者購買前常比較價格並閱讀評價。"},{"en":"Retailers design websites carefully because internet shoppers can leave quickly if checkout is difficult.","zh":"零售商仔細設計網站，因為如果付款困難，網上購物者可以很快離開。"},{"en":"This phrase refers to customers shopping through the web.","zh":"這個短語指透過網絡購物的顧客。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":12},{"front":"around half","meaning":"大約一半","examples":[{"en":"Around half of Circuit City’s online customers collect purchases in-store.","zh":"Circuit City 大約一半網上顧客會到店領取所購貨品。"},{"en":"Around half means approximately 50%.","zh":"around half 是指大約50%。"},{"en":"Around half the students chose the online quiz instead of the paper version.","zh":"大約一半學生選擇網上小測，而不是紙本版本。"},{"en":"If around half of customers use a service, it is no longer a small trend.","zh":"如果大約一半顧客使用某服務，它就不再是小趨勢。"},{"en":"This phrase gives an approximate proportion.","zh":"這個短語給出大約比例。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":12},{"front":"buying goods online from","meaning":"從……網上購買貨品","examples":[{"en":"Customers buying goods online from Circuit City often collect them in-store.","zh":"從 Circuit City 網上購買貨品的顧客常到店取貨。"},{"en":"Buying goods online from a retailer means purchasing that retailer’s products through its website.","zh":"buying goods online from a retailer 是指透過該零售商網站購買其產品。"},{"en":"A parent buying school supplies online from a stationery shop may choose store collection.","zh":"家長從文具店網上購買學校用品時，可能選擇店內取貨。"},{"en":"Customers buy online when they want convenience, price comparison, or guaranteed stock.","zh":"顧客想要方便、格價或確保有貨時，會網上購買。"},{"en":"This phrase identifies both the buying method and the seller.","zh":"這個短語同時指出購買方法和賣方。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":12},{"front":"collect their purchases","meaning":"領取所購貨品","examples":[{"en":"Many customers collect their purchases at a shop.","zh":"許多顧客在店舖領取所購貨品。"},{"en":"To collect their purchases means to pick up items they have already bought or ordered.","zh":"collect their purchases 是指領取已購買或已訂購的商品。"},{"en":"A customer may collect online purchases from a local store after work.","zh":"顧客可能下班後到本地店舖領取網上購買的貨品。"},{"en":"Collecting purchases can save delivery fees and waiting time.","zh":"領取所購貨品可以節省送貨費和等待時間。"},{"en":"This phrase focuses on receiving goods, not choosing them.","zh":"這個短語集中於收取貨品，而不是選擇貨品。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":12},{"front":"holiday season","meaning":"假日購物季","examples":[{"en":"For this holiday season, Circuit City offered a pick-up guarantee.","zh":"在這個假日購物季，Circuit City 提供取貨保證。"},{"en":"The holiday season is the busy shopping period around major holidays, especially Christmas.","zh":"holiday season 是主要節日前後的繁忙購物期，尤其指聖誕節。"},{"en":"Shops hire extra workers during the holiday season because customer demand rises.","zh":"商店在假日購物季聘請額外員工，因為顧客需求上升。"},{"en":"Retailers offer guarantees and discounts during this period to attract shoppers.","zh":"零售商在這段時期提供保證和折扣來吸引購物者。"},{"en":"This phrase usually refers to a festive buying season.","zh":"這個短語通常指節日購買季節。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":13},{"front":"offer what it calls","meaning":"提供它所稱的……","examples":[{"en":"The company is offering what it calls a 24/24 Pick-up Guarantee.","zh":"該公司提供它所稱的 24/24 取貨保證。"},{"en":"To offer what it calls something means a company gives a service under its own chosen name.","zh":"offer what it calls something 是指公司以自己選定的名稱提供某服務。"},{"en":"A school may offer what it calls a “study rescue session” before exams.","zh":"學校可能在考試前提供它所稱的「學習急救課」。"},{"en":"Companies name services to make them sound clear, memorable, or attractive.","zh":"公司為服務命名，是為了令它聽起來清楚、易記或吸引。"},{"en":"This phrase signals that the label comes from the company itself.","zh":"這個短語表示該標籤來自公司本身。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":13},{"front":"ordered online","meaning":"在網上下單的","examples":[{"en":"Goods ordered online may be collected at a local store.","zh":"在網上下單的貨品可以在本地店舖領取。"},{"en":"Ordered online means bought or requested through a website or app.","zh":"ordered online 是指透過網站或應用程式購買或訂購。"},{"en":"Books ordered online can sometimes be collected from a bookstore the same day.","zh":"在網上下單的書有時可以同日在書店領取。"},{"en":"Online ordering saves time because customers can choose items before travelling.","zh":"網上下單節省時間，因為顧客可以先選好商品再出門。"},{"en":"This phrase describes how the purchase was made.","zh":"這個短語描述購買是如何完成的。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":13},{"front":"over the telephone","meaning":"透過電話","examples":[{"en":"Goods can be ordered online or over the telephone.","zh":"貨品可以在網上或透過電話訂購。"},{"en":"Over the telephone means by using a phone call.","zh":"over the telephone 是指透過電話通話。"},{"en":"Older customers may prefer ordering over the telephone if they are not comfortable online.","zh":"如果年長顧客不習慣網上操作，可能偏好透過電話訂購。"},{"en":"Phone ordering helps customers who need to ask questions before buying.","zh":"電話訂購幫助購買前需要提問的顧客。"},{"en":"This phrase describes a communication method.","zh":"這個短語描述一種溝通方法。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":13},{"front":"be available for collection","meaning":"可供領取","examples":[{"en":"The goods are available for collection at a local store.","zh":"貨品可在本地店舖領取。"},{"en":"To be available for collection means ready for the customer to pick up.","zh":"be available for collection 是指已準備好讓顧客領取。"},{"en":"A library book is available for collection when staff have placed it at the counter.","zh":"當圖書館職員把書放到櫃台，該書就可供領取。"},{"en":"Clear collection times help customers avoid wasted trips.","zh":"清楚取貨時間幫助顧客避免白行一趟。"},{"en":"This phrase tells customers when and where they can receive items.","zh":"這個短語告訴顧客何時何地可收取物品。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":13},{"front":"local store","meaning":"本地店舖","examples":[{"en":"Customers collect the goods at a local store.","zh":"顧客在本地店舖領取貨品。"},{"en":"A local store is a nearby physical shop in a customer’s area.","zh":"local store 是顧客所在地區附近的實體店。"},{"en":"A customer may choose a local store because it is close to home or work.","zh":"顧客可能選擇本地店舖，因為它靠近住所或工作地點。"},{"en":"Local stores build trust because customers know where to go if a problem appears.","zh":"本地店舖建立信任，因為顧客知道有問題時去哪裡。"},{"en":"This phrase focuses on nearby store access.","zh":"這個短語集中於附近店舖的可及性。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":13},{"front":"within 24 minutes of purchase","meaning":"購買後24分鐘內","examples":[{"en":"The goods should be available within 24 minutes of purchase.","zh":"貨品應在購買後24分鐘內可供領取。"},{"en":"Within 24 minutes of purchase means no later than 24 minutes after buying.","zh":"within 24 minutes of purchase 是指購買後不遲於24分鐘。"},{"en":"A café may promise that online orders are ready within ten minutes of purchase.","zh":"咖啡店可能承諾網上訂單在購買後10分鐘內準備好。"},{"en":"A short collection time gives customers quick satisfaction.","zh":"短取貨時間給顧客快速滿足感。"},{"en":"This phrase sets a precise time limit after buying.","zh":"這個短語設定購買後的精確時間限制。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":13},{"front":"claim a gift voucher","meaning":"申領禮券","examples":[{"en":"The customer can claim a gift voucher if the goods are not ready.","zh":"如果貨品未準備好，顧客可以申領禮券。"},{"en":"To claim a gift voucher means to ask for or receive a voucher one is entitled to.","zh":"claim a gift voucher 是指要求或取得自己有權獲得的禮券。"},{"en":"A shopper may claim a voucher if a store fails to meet its delivery promise.","zh":"如果店舖未能履行送貨承諾，購物者可能申領禮券。"},{"en":"Guarantees encourage customers because they offer compensation when service fails.","zh":"保證能鼓勵顧客，因為服務失敗時會提供補償。"},{"en":"This phrase describes receiving a promised benefit.","zh":"這個短語描述領取承諾了的利益。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":13},{"front":"apart from","meaning":"除了……之外","examples":[{"en":"Apart from instant gratification, there are many reasons to collect in-store.","zh":"除了即時滿足感之外，到店取貨還有許多原因。"},{"en":"Apart from means besides or in addition to something.","zh":"apart from 是指除了某事之外，另有其他東西。"},{"en":"Apart from lower prices, customers also want reliable delivery.","zh":"除了較低價格之外，顧客也想要可靠送貨。"},{"en":"This phrase introduces another point while keeping the first point in mind.","zh":"這個短語在保留第一點的同時，引入另一點。"},{"en":"It is useful when listing extra reasons.","zh":"列出額外原因時，這個短語很有用。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":13},{"front":"instant consumer gratification","meaning":"消費者即時滿足感","examples":[{"en":"In-store collection provides instant consumer gratification.","zh":"店內取貨提供消費者即時滿足感。"},{"en":"Instant consumer gratification is the immediate satisfaction customers feel when they get what they bought quickly.","zh":"instant consumer gratification 是顧客快速取得所購商品時感到的即時滿足。"},{"en":"A shopper gets instant gratification when she orders online and collects the item that afternoon.","zh":"顧客網上下單並當天下午取貨時，會得到即時滿足感。"},{"en":"Quick collection can make customers happier than waiting several days for delivery.","zh":"快速取貨可以比等候數天送貨令顧客更開心。"},{"en":"This phrase focuses on immediate pleasure after purchase.","zh":"這個短語集中於購買後的即時愉悅。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":13},{"front":"the convenience of buying online","meaning":"網上購物的方便","examples":[{"en":"Customers like the convenience of buying online.","zh":"顧客喜歡網上購物的方便。"},{"en":"The convenience of buying online means the ease of shopping without visiting a store.","zh":"convenience of buying online 是指不用到店也能購物的便利。"},{"en":"A busy parent likes buying online because it can be done after children sleep.","zh":"忙碌父母喜歡網上購物，因為可以在孩子睡後完成。"},{"en":"Online convenience saves travel time and allows quick price comparison.","zh":"網上方便節省交通時間，並可快速格價。"},{"en":"This phrase explains why many customers use websites.","zh":"這個短語解釋為何許多顧客使用網站。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":13},{"front":"trek to a store","meaning":"長途跋涉到店舖","examples":[{"en":"Some customers still trek to a store to collect goods.","zh":"有些顧客仍長途跋涉到店舖領取貨品。"},{"en":"To trek to a store means to make a trip there, often suggesting effort or inconvenience.","zh":"trek to a store 是指前往店舖，通常暗示需要努力或不太方便。"},{"en":"A customer may trek to a distant store if delivery is too expensive.","zh":"如果送貨太貴，顧客可能長途跋涉到遠方店舖。"},{"en":"People are willing to make the trip when they want the product immediately.","zh":"當人們想立即取得產品時，會願意走這一趟。"},{"en":"This phrase makes the journey sound somewhat tiring.","zh":"這個短語令旅程聽起來有點吃力。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":14},{"front":"take delivery","meaning":"收貨","examples":[{"en":"Some shoppers go to the store to take delivery.","zh":"有些購物者到店舖收貨。"},{"en":"To take delivery means to receive goods that have been ordered or purchased.","zh":"take delivery 是指接收已訂購或購買的貨品。"},{"en":"A customer may take delivery of a new laptop at the shop counter.","zh":"顧客可能在店舖櫃台收取新手提電腦。"},{"en":"Taking delivery in-store can avoid missed home deliveries.","zh":"店內收貨可以避免錯過上門送貨。"},{"en":"This phrase focuses on receiving goods.","zh":"這個短語集中於接收貨品。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":14},{"front":"it appears","meaning":"看來","examples":[{"en":"There are, it appears, many reasons for this behaviour.","zh":"看來，這種行為有許多原因。"},{"en":"It appears means it seems or looks likely based on the available information.","zh":"it appears 是指根據現有資訊看似如此。"},{"en":"It appears that customers prefer collection when delivery is slow.","zh":"看來，當送貨慢時，顧客更偏好取貨。"},{"en":"Writers use this phrase when they want to sound cautious rather than certain.","zh":"作者想語氣謹慎而非絕對時會使用這個短語。"},{"en":"This phrase introduces a careful judgement.","zh":"這個短語引入謹慎判斷。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":14},{"front":"examine items","meaning":"檢查貨品","examples":[{"en":"Some people want to examine items before accepting them.","zh":"有些人想在接受貨品前檢查貨品。"},{"en":"To examine items means to look at products carefully to check quality, size, or condition.","zh":"examine items 是指仔細查看產品的質素、尺寸或狀況。"},{"en":"A shopper may examine a coat in-store to see whether the fabric feels comfortable.","zh":"購物者可能在店內檢查外套，看看布料是否舒適。"},{"en":"Examining items before acceptance reduces the risk of keeping damaged goods.","zh":"接受前檢查貨品可降低保留損壞貨品的風險。"},{"en":"This phrase describes careful checking before final acceptance.","zh":"這個短語描述最終接受前的仔細檢查。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":14},{"front":"save on delivery costs","meaning":"節省送貨費","examples":[{"en":"Some shoppers collect goods to save on delivery costs.","zh":"有些購物者取貨是為了節省送貨費。"},{"en":"To save on delivery costs means to spend less money by avoiding or reducing delivery fees.","zh":"save on delivery costs 是指透過避免或減少送貨費來少花錢。"},{"en":"A student may collect textbooks from a shop to save on delivery costs.","zh":"學生可能從店舖領取教科書，以節省送貨費。"},{"en":"High delivery fees can make store collection more attractive.","zh":"高送貨費可以令店內取貨更有吸引力。"},{"en":"This phrase explains a money-saving reason for customer behaviour.","zh":"這個短語解釋顧客行為中的省錢原因。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":14},{"front":"avoid hanging around for","meaning":"避免一直等候……","examples":[{"en":"Others want to avoid hanging around for the delivery man.","zh":"其他人想避免一直等候送貨員。"},{"en":"To avoid hanging around for someone means to avoid waiting idly for them to arrive.","zh":"avoid hanging around for someone 是指避免無所事事地等某人到來。"},{"en":"A customer may collect a parcel in-store to avoid waiting at home all afternoon.","zh":"顧客可能到店領取包裹，以避免整個下午在家等候。"},{"en":"Waiting for delivery can waste time if the arrival window is unclear.","zh":"如果送貨時間範圍不清楚，等候送貨會浪費時間。"},{"en":"This phrase suggests inconvenient waiting.","zh":"這個短語暗示不方便的等待。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":14},{"front":"the delivery man to call","meaning":"送貨員上門","examples":[{"en":"Some people do not want to wait for the delivery man to call.","zh":"有些人不想等候送貨員上門。"},{"en":"The delivery man to call means the delivery worker arriving at the home or contacting the customer.","zh":"delivery man to call 是指送貨員到家或聯絡顧客。"},{"en":"A customer may miss the delivery man if she has to leave for work.","zh":"如果顧客要上班離開，她可能錯過送貨員。"},{"en":"Store collection avoids the problem of waiting for someone to deliver the goods.","zh":"店內取貨避免了等候送貨員送貨的問題。"},{"en":"This phrase describes the expected arrival or contact of a delivery person.","zh":"這個短語描述送貨人員預期到達或聯絡。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":14},{"front":"the chief reason","meaning":"主要原因","examples":[{"en":"The chief reason is trust in a big retailing brand.","zh":"主要原因是對大型零售品牌的信任。"},{"en":"The chief reason means the main or most important reason.","zh":"chief reason 是指主要或最重要原因。"},{"en":"The chief reason students choose online notes may be convenience.","zh":"學生選擇網上筆記的主要原因可能是方便。"},{"en":"Identifying the chief reason helps businesses focus on what matters most to customers.","zh":"識別主要原因幫助企業集中於顧客最重視的事。"},{"en":"This phrase separates the main cause from smaller ones.","zh":"這個短語把主因與較小原因分開。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":14},{"front":"trust a big retailing brand","meaning":"信任大型零售品牌","examples":[{"en":"Many shoppers trust a big retailing brand with a local store.","zh":"許多購物者信任有本地店舖的大型零售品牌。"},{"en":"To trust a big retailing brand means to believe a large retailer will deliver, refund, and solve problems fairly.","zh":"trust a big retailing brand 是指相信大型零售商會送貨、退款和公平解決問題。"},{"en":"A customer may buy an expensive TV online because she trusts the retailer’s name.","zh":"顧客可能因信任零售商名稱而在網上購買昂貴電視。"},{"en":"Brand trust reduces fear when shoppers cannot see the product before paying.","zh":"當購物者付款前看不到產品時，品牌信任可減少恐懼。"},{"en":"This phrase links customer confidence with a known retailer.","zh":"這個短語把顧客信心與知名零售商連接起來。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":14},{"front":"not least because","meaning":"尤其因為","examples":[{"en":"Customers trust local stores, not least because returns are easier.","zh":"顧客信任本地店舖，尤其因為退貨較容易。"},{"en":"Not least because means especially because, among other reasons.","zh":"not least because 是指在其他原因之中尤其因為某事。"},{"en":"Students like clear notes, not least because they save revision time.","zh":"學生喜歡清晰筆記，尤其因為它們節省溫習時間。"},{"en":"People trust local shops, not least because they know where to go if something breaks.","zh":"人們信任本地店舖，尤其因為東西壞了知道去哪裡。"},{"en":"This phrase highlights an important reason without saying it is the only reason.","zh":"這個短語突出重要原因，但不表示它是唯一原因。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":14},{"front":"goods can be returned","meaning":"貨品可被退回","examples":[{"en":"Customers know where goods can be returned.","zh":"顧客知道貨品可以退回到哪裡。"},{"en":"Goods can be returned means customers are allowed to take products back for refund, exchange, or repair.","zh":"goods can be returned 是指顧客可以把產品退回以退款、換貨或維修。"},{"en":"A shopper may buy online more confidently if unwanted goods can be returned nearby.","zh":"如果不想要的貨品可以在附近退回，購物者會更有信心網購。"},{"en":"Clear return policies reduce the risk of online shopping.","zh":"清楚退貨政策降低網上購物風險。"},{"en":"This phrase focuses on post-purchase protection.","zh":"這個短語集中於購買後保障。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":14},{"front":"if there is a problem","meaning":"如果出現問題","examples":[{"en":"Customers can return goods if there is a problem.","zh":"如果出現問題，顧客可以退回貨品。"},{"en":"If there is a problem means if something is wrong, damaged, unsuitable, or not as promised.","zh":"if there is a problem 是指如果某物有錯、損壞、不合適或與承諾不符。"},{"en":"A customer keeps the receipt in case there is a problem with the product.","zh":"顧客保留收據，以防產品出現問題。"},{"en":"Easy returns make shoppers less afraid of buying online.","zh":"容易退貨令購物者較不害怕網購。"},{"en":"This phrase introduces the condition for taking action.","zh":"這個短語引入採取行動的條件。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":15},{"front":"in America alone","meaning":"單是在美國","examples":[{"en":"Wal-Mart has more than 3,700 stores in America alone.","zh":"沃爾瑪單是在美國就有超過3700間店。"},{"en":"In America alone means counting only America, not other countries.","zh":"in America alone 是指只計算美國，不包括其他國家。"},{"en":"A company may have 500 staff in Hong Kong alone, before counting overseas offices.","zh":"公司可能單是在香港就有500名員工，尚未計算海外辦公室。"},{"en":"This phrase emphasises how large a number is within just one place.","zh":"這個短語強調數字在單一地方已經很大。"},{"en":"It often makes the scale sound more impressive.","zh":"它常令規模聽起來更驚人。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":15},{"front":"hand someone another big advantage","meaning":"給予某人另一大優勢","examples":[{"en":"This gives Wal-Mart another big advantage.","zh":"這給予沃爾瑪另一大優勢。"},{"en":"To hand someone another big advantage means to give them one more strong benefit over competitors.","zh":"hand someone another big advantage 是指給某人或公司多一項強大競爭優勢。"},{"en":"A school near a train station has another big advantage because students can travel easily.","zh":"靠近火車站的學校有另一大優勢，因為學生交通方便。"},{"en":"Thousands of stores give Wal-Mart an advantage because customers can return goods locally.","zh":"數千間店給沃爾瑪優勢，因為顧客可以在本地退貨。"},{"en":"This phrase explains why one competitor is stronger.","zh":"這個短語解釋為何某個競爭者更強。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":15},{"front":"develop services","meaning":"開發服務","examples":[{"en":"Wal-Mart is developing services that link the web with stores.","zh":"沃爾瑪正在開發把網絡與店舖連繫起來的服務。"},{"en":"To develop services means to create or improve useful activities offered to customers.","zh":"develop services 是指創造或改善向顧客提供的有用活動。"},{"en":"A library may develop services such as online booking and home delivery for elderly readers.","zh":"圖書館可能開發網上預約和長者送書到家等服務。"},{"en":"Retailers develop new services when customer habits change.","zh":"當顧客習慣改變，零售商會開發新服務。"},{"en":"This phrase focuses on building customer support, not only selling products.","zh":"這個短語集中於建立顧客服務，而不只是銷售產品。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":15},{"front":"link the web with its stores","meaning":"將網絡與實體店連繫起來","examples":[{"en":"Wal-Mart links the web with its stores.","zh":"沃爾瑪將網絡與實體店連繫起來。"},{"en":"To link the web with stores means to connect online services with physical shop locations.","zh":"link the web with stores 是指把網上服務與實體店地點連接。"},{"en":"A customer may order photos online and collect them in a nearby store.","zh":"顧客可以在網上訂相片，並在附近店舖領取。"},{"en":"Linking web and store services gives shoppers both convenience and local support.","zh":"將網絡與實體店服務連繫起來，給購物者方便和本地支援。"},{"en":"This phrase describes integration between online and offline retail.","zh":"這個短語描述網上和線下零售的整合。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":15},{"front":"digital pictures","meaning":"數碼相片","examples":[{"en":"Customers can e-mail digital pictures and pick up the prints.","zh":"顧客可以電郵數碼相片並領取沖印本。"},{"en":"Digital pictures are photographs stored as electronic files.","zh":"digital pictures 是以電子檔案儲存的照片。"},{"en":"A family may send digital pictures to a shop for printing before a birthday party.","zh":"家庭可能在生日派對前把數碼相片傳給店舖沖印。"},{"en":"Digital pictures are easy to share online but may still be printed for albums or gifts.","zh":"數碼相片容易在網上分享，但仍可能沖印成相簿或禮物。"},{"en":"This phrase refers to photo files, not paper photos.","zh":"這個短語指相片檔案，而不是紙本照片。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":15},{"front":"pick up the prints","meaning":"領取相片沖印本","examples":[{"en":"Customers can pick up the prints in a store.","zh":"顧客可以在店內領取相片沖印本。"},{"en":"To pick up the prints means to collect printed photographs after they are ready.","zh":"pick up the prints 是指在相片沖印完成後領取紙本照片。"},{"en":"A parent may upload school photos online and pick up the prints after work.","zh":"家長可能先網上上載學校相片，下班後領取沖印本。"},{"en":"Store pick-up helps customers receive photos quickly without waiting for delivery.","zh":"店內取貨幫助顧客快速收到照片，不用等候送貨。"},{"en":"This phrase refers to collecting printed copies.","zh":"這個短語指領取印刷副本。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":15},{"front":"retailing giants","meaning":"零售巨頭","examples":[{"en":"Retailing giants may come to dominate the web.","zh":"零售巨頭可能逐漸主導網絡。"},{"en":"Retailing giants are very large and powerful retail companies.","zh":"retailing giants 是非常大型且有力量的零售公司。"},{"en":"A retailing giant can influence prices because it buys and sells huge quantities.","zh":"零售巨頭因大量買賣而可以影響價格。"},{"en":"Giants may dominate online shopping if customers already trust their physical stores.","zh":"如果顧客已信任它們的實體店，巨頭可能主導網上購物。"},{"en":"This phrase emphasises size and market power.","zh":"這個短語強調規模和市場力量。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":15},{"front":"come to dominate","meaning":"逐漸主導","examples":[{"en":"Retailing giants may come to dominate cyberspace.","zh":"零售巨頭可能逐漸主導網絡空間。"},{"en":"To come to dominate means to gradually become the most powerful or important player.","zh":"come to dominate 是指逐漸成為最有力量或最重要的參與者。"},{"en":"A small app can come to dominate a market if users recommend it widely.","zh":"如果使用者廣泛推薦，小應用程式也可以逐漸主導市場。"},{"en":"Large retailers may dominate online because they already have scale, data, and trust.","zh":"大型零售商可能主導網上市場，因為它們已有規模、數據和信任。"},{"en":"This phrase suggests dominance developing over time.","zh":"這個短語暗示主導地位隨時間形成。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":15},{"front":"the high street","meaning":"商業街；實體零售市場","examples":[{"en":"Retailing giants already dominate the high street.","zh":"零售巨頭已經主導商業街。"},{"en":"The high street means the main shopping area with physical stores in a town or city.","zh":"high street 是城鎮或城市中有實體店的主要購物區。"},{"en":"A café on the high street gets many customers because people walk past every day.","zh":"商業街上的咖啡店每天有人經過，因此獲得許多顧客。"},{"en":"Companies strong on the high street may use their store network to support online sales.","zh":"在線下商業街強大的公司，可以利用店舖網絡支援網上銷售。"},{"en":"This phrase refers to physical retail areas.","zh":"這個短語指實體零售區域。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":15},{"front":"carve out large chunks of","meaning":"佔據大部分……","examples":[{"en":"Some retailers might carve out large chunks of cyberspace.","zh":"有些零售商可能佔據網絡空間的大部分。"},{"en":"To carve out large chunks of a market means to gain and control big parts of it.","zh":"carve out large chunks of a market 是指取得並控制市場的大部分。"},{"en":"A new delivery app may carve out a large share of lunch orders in a city.","zh":"新外賣應用程式可能佔據某城市午餐訂單的大份額。"},{"en":"Strong brands can take large online space because customers search for them first.","zh":"強大品牌可以佔據大量網上空間，因為顧客會先搜尋它們。"},{"en":"This phrase suggests claiming a significant portion.","zh":"這個短語暗示取得重要份額。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":15},{"front":"cyberspace","meaning":"網絡空間","examples":[{"en":"Large retailers may dominate parts of cyberspace.","zh":"大型零售商可能主導部分網絡空間。"},{"en":"Cyberspace means the online world of websites, apps, networks, and digital communication.","zh":"cyberspace 是由網站、應用程式、網絡和數碼通訊組成的網上世界。"},{"en":"Students spend time in cyberspace when they join online classes or forums.","zh":"學生參加網上課堂或論壇時，就是在網絡空間中活動。"},{"en":"Businesses compete in cyberspace by improving websites, search results, and customer service.","zh":"企業透過改善網站、搜尋結果和顧客服務在網絡空間競爭。"},{"en":"This phrase contrasts digital space with physical space.","zh":"這個短語把數碼空間與實體空間作對比。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":16},{"front":"for instance","meaning":"例如","examples":[{"en":"Tesco, for instance, has a large share of the grocery market.","zh":"例如，Tesco 在食品雜貨市場佔有很大份額。"},{"en":"For instance means for example.","zh":"for instance 是指例如。"},{"en":"Some shops use websites well; for instance, a bookstore can show live stock online.","zh":"有些店舖善用網站；例如，書店可以在網上顯示即時庫存。"},{"en":"Writers use this phrase to introduce a clear example of a general point.","zh":"作者使用這個短語引入一般論點的清楚例子。"},{"en":"This phrase helps make an argument more concrete.","zh":"這個短語幫助令論點更具體。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":16},{"front":"a huge 30 per cent share of","meaning":"佔有高達百分之三十的……份額","examples":[{"en":"Tesco has a huge 30 per cent share of the British grocery market.","zh":"Tesco 佔有英國食品雜貨市場高達百分之三十的份額。"},{"en":"A huge 30 per cent share means one company controls nearly one third of the market.","zh":"huge 30 per cent share 是指一間公司控制接近三分之一市場。"},{"en":"A school with a 30 per cent share of applications would be very popular in its district.","zh":"如果學校佔有區內申請的30%份額，它在該區會非常受歡迎。"},{"en":"A large market share gives a company strong bargaining power and brand visibility.","zh":"大市場份額給公司強大議價能力和品牌能見度。"},{"en":"This phrase highlights an unusually large percentage.","zh":"這個短語突顯異常大的百分比。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":16},{"front":"grocery market","meaning":"食品雜貨市場","examples":[{"en":"Tesco has a large share of the British grocery market.","zh":"Tesco 在英國食品雜貨市場佔有很大份額。"},{"en":"The grocery market is the business of selling food and everyday household goods.","zh":"grocery market 是銷售食物和日常家居用品的業務市場。"},{"en":"Supermarkets compete in the grocery market through price, freshness, and delivery service.","zh":"超市透過價格、新鮮度和送貨服務在食品雜貨市場競爭。"},{"en":"Online grocery shopping grows when customers trust stores to choose fresh products.","zh":"當顧客信任店舖代選新鮮產品時，網上食品雜貨購物會增長。"},{"en":"This phrase refers to food and daily essentials retail.","zh":"這個短語指食物和日常必需品零售。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":16},{"front":"even more popular","meaning":"更受歡迎","examples":[{"en":"Tesco is even more popular online.","zh":"Tesco 在網上更受歡迎。"},{"en":"Even more popular means liked or used to a greater degree than before or than in another context.","zh":"even more popular 是指比以前或比另一情境中更受喜愛或使用。"},{"en":"A café may be popular in the neighbourhood but even more popular on delivery apps.","zh":"咖啡店可能在社區受歡迎，但在外賣應用程式上更受歡迎。"},{"en":"Online convenience can make a strong physical brand even more popular.","zh":"網上方便可以令強大的實體品牌更受歡迎。"},{"en":"This phrase strengthens a comparison of popularity.","zh":"這個短語加強受歡迎程度的比較。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":16},{"front":"online shoppers","meaning":"網上購物者","examples":[{"en":"Many online shoppers plan to buy groceries from Tesco.","zh":"許多網上購物者計劃從 Tesco 購買食品雜貨。"},{"en":"Online shoppers are people who buy goods or services through the internet.","zh":"online shoppers 是透過互聯網購買商品或服務的人。"},{"en":"Online shoppers often care about delivery speed, price, and return policies.","zh":"網上購物者通常關心送貨速度、價格和退貨政策。"},{"en":"Retailers study online shoppers to improve websites and product recommendations.","zh":"零售商研究網上購物者，以改善網站和產品推薦。"},{"en":"This phrase identifies customers who shop digitally.","zh":"這個短語指出數碼購物顧客。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":16},{"front":"buy groceries","meaning":"購買食品雜貨","examples":[{"en":"Many online shoppers plan to buy groceries from tesco.com.","zh":"許多網上購物者計劃從 tesco.com 購買食品雜貨。"},{"en":"To buy groceries means to purchase food and everyday household items.","zh":"buy groceries 是指購買食物和日常家居用品。"},{"en":"A family may buy groceries online when they are too busy to visit a supermarket.","zh":"家庭太忙無法去超市時，可能在網上購買食品雜貨。"},{"en":"Grocery shopping online saves travel time but depends on reliable delivery.","zh":"網上購買食品雜貨節省交通時間，但依賴可靠送貨。"},{"en":"This phrase refers to buying daily food and essentials.","zh":"這個短語指購買日常食物和必需品。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":16},{"front":"still face competition","meaning":"仍然面對競爭","examples":[{"en":"Traditional retailers still face competition online.","zh":"傳統零售商在線上仍然面對競爭。"},{"en":"To still face competition means competitors remain a challenge despite existing advantages.","zh":"still face competition 是指即使有既有優勢，競爭者仍然是挑戰。"},{"en":"A famous school still faces competition from newer schools with strong programmes.","zh":"著名學校仍然面對來自新學校強大課程的競爭。"},{"en":"Even large retailers must improve because customers can compare alternatives easily online.","zh":"即使大型零售商也必須改善，因為顧客可以在網上輕易比較其他選擇。"},{"en":"This phrase shows that success does not remove pressure.","zh":"這個短語顯示成功不會消除壓力。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":16},{"front":"annual sales","meaning":"年銷售額","examples":[{"en":"Wal-Mart has more than five times the annual sales of Target.","zh":"沃爾瑪的年銷售額超過 Target 的五倍。"},{"en":"Annual sales are the total value of goods or services sold in one year.","zh":"annual sales 是一年內售出商品或服務的總價值。"},{"en":"A shop reviews annual sales to decide whether it can afford a new branch.","zh":"商店檢視年銷售額，以決定是否負擔得起新分店。"},{"en":"Higher annual sales often show greater scale, but not necessarily higher profit per order.","zh":"較高年銷售額通常顯示較大規模，但不一定代表每張訂單利潤較高。"},{"en":"This phrase measures business activity over a year.","zh":"這個短語量度一年內的商業活動。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":16},{"front":"according to some analysts","meaning":"據一些分析員所說","examples":[{"en":"According to some analysts, Target’s online sales are more valuable on average.","zh":"據一些分析員所說，Target 的網上銷售平均價值更高。"},{"en":"According to some analysts means based on the views or calculations of certain experts.","zh":"according to some analysts 是指根據某些專家的看法或計算。"},{"en":"According to some analysts, delivery speed matters more than price for busy customers.","zh":"據一些分析員所說，對忙碌顧客而言，送貨速度比價格更重要。"},{"en":"This phrase shows that the statement comes from expert opinion, not the writer alone.","zh":"這個短語顯示該說法來自專家意見，而不只是作者本人。"},{"en":"It also leaves room for other analysts to disagree.","zh":"它也為其他分析員可能不同意留下空間。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":16},{"front":"average value of","meaning":"……的平均價值","examples":[{"en":"The average value of an online sale at Target is higher.","zh":"Target 每宗網上銷售交易的平均價值較高。"},{"en":"The average value of something means the typical amount calculated by dividing the total by the number of cases.","zh":"average value of something 是指用總額除以個案數後計算出的典型金額。"},{"en":"A shop calculates the average value of each order to understand customer spending.","zh":"商店計算每張訂單的平均價值，以理解顧客消費。"},{"en":"Higher average order value can matter even if total visitor numbers are smaller.","zh":"即使總訪客數較少，較高平均訂單價值也可能重要。"},{"en":"This phrase focuses on typical monetary size.","zh":"這個短語集中於典型金額大小。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":16},{"front":"online sale","meaning":"網上銷售交易","examples":[{"en":"The average value of an online sale differs between retailers.","zh":"不同零售商的網上銷售交易平均價值不同。"},{"en":"An online sale is a completed purchase made through the internet.","zh":"online sale 是透過互聯網完成的購買交易。"},{"en":"A retailer records an online sale when a customer pays for a product on its website.","zh":"當顧客在零售商網站付款購買產品時，零售商就記錄一宗網上銷售交易。"},{"en":"Online sales can be measured by number of orders, total revenue, or average value.","zh":"網上銷售可以按訂單數、總收入或平均價值量度。"},{"en":"This phrase refers to actual buying, not just visiting a website.","zh":"這個短語指實際購買，而不只是到訪網站。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":17},{"front":"roughly three times","meaning":"大約三倍","examples":[{"en":"Target’s average online sale is roughly three times that of Wal-Mart.","zh":"Target 的平均網上銷售交易約為沃爾瑪的大約三倍。"},{"en":"Roughly three times means about three times as much, but not exactly.","zh":"roughly three times 是指大約為三倍，但不是完全精確。"},{"en":"If one meal costs roughly three times another, it is much more expensive.","zh":"如果一餐飯價格大約是另一餐的三倍，它就貴很多。"},{"en":"Approximate figures are useful when exact numbers are not needed.","zh":"當不需要精確數字時，近似數字很有用。"},{"en":"This phrase gives a close comparison without claiming precision.","zh":"這個短語給出接近比較，而不聲稱精確。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":17},{"front":"one reason why","meaning":"……的其中一個原因","examples":[{"en":"This is one reason why Wal-Mart is offering more upmarket goods online.","zh":"這是沃爾瑪在網上提供更多高檔商品的其中一個原因。"},{"en":"One reason why means one cause or explanation among several possible reasons.","zh":"one reason why 是指幾個可能原因中的其中一個原因或解釋。"},{"en":"A long commute is one reason why some workers prefer remote work.","zh":"長途通勤是有些員工偏好遙距工作的其中一個原因。"},{"en":"Businesses may change product range for many reasons, including higher-value customers.","zh":"企業改變產品範圍可能有許多原因，包括較高價值顧客。"},{"en":"This phrase gives a partial explanation, not the whole story.","zh":"這個短語提供部分解釋，而不是完整故事。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":17},{"front":"upmarket goods","meaning":"高檔商品","examples":[{"en":"Wal-Mart is offering more upmarket goods on its website.","zh":"沃爾瑪在其網站上提供更多高檔商品。"},{"en":"Upmarket goods are more expensive, higher-quality, or more stylish products aimed at wealthier customers.","zh":"upmarket goods 是面向較富裕顧客、較昂貴、較高質或較時尚的產品。"},{"en":"A shop sells upmarket goods when it offers designer bags and premium watches.","zh":"當商店出售設計師手袋和高級手錶時，就是銷售高檔商品。"},{"en":"Retailers add upmarket goods to raise the average value of each sale.","zh":"零售商加入高檔商品，以提高每宗銷售的平均價值。"},{"en":"This phrase contrasts higher-end products with basic low-cost items.","zh":"這個短語把高端產品與基本低價商品作對比。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":17},{"front":"diamond rings","meaning":"鑽石戒指","examples":[{"en":"Wal-Mart sells upmarket goods online, including diamond rings.","zh":"沃爾瑪在網上銷售高檔商品，包括鑽石戒指。"},{"en":"Diamond rings are rings decorated with diamonds, often sold as jewellery or engagement gifts.","zh":"diamond rings 是鑲有鑽石的戒指，常作首飾或訂婚禮物出售。"},{"en":"A customer buying a diamond ring online may need clear photos, certificates, and return policies.","zh":"顧客網上購買鑽石戒指時，可能需要清晰照片、證書和退貨政策。"},{"en":"Expensive jewellery requires trust because customers cannot easily judge quality from a screen.","zh":"昂貴首飾需要信任，因為顧客不易從螢幕判斷質素。"},{"en":"This phrase is an example of a high-value product.","zh":"這個短語是高價值產品的例子。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":17},{"front":"stick to books","meaning":"堅持只賣書","examples":[{"en":"Some people wonder whether Amazon should have stuck to books.","zh":"有些人想知道 Amazon 是否本應堅持只賣書。"},{"en":"To stick to books means to continue selling only books instead of expanding into other products.","zh":"stick to books 是指繼續只賣書，而不是擴展到其他產品。"},{"en":"A small restaurant may stick to noodles if that is what customers trust it for.","zh":"如果顧客信任小餐館的麵食，它可能堅持只賣麵。"},{"en":"Companies face risk when they expand beyond the product that made them famous.","zh":"公司擴展到令其成名的產品以外時會面對風險。"},{"en":"This phrase means staying with the original focus.","zh":"這個短語指保留原本焦點。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":17},{"front":"founder and chief executive","meaning":"創辦人兼行政總裁","examples":[{"en":"Jeff Bezos is Amazon’s founder and chief executive.","zh":"Jeff Bezos 是 Amazon 的創辦人兼行政總裁。"},{"en":"A founder and chief executive is the person who started a company and leads its management.","zh":"founder and chief executive 是創立公司並領導其管理的人。"},{"en":"A founder may set the company’s original vision, while a chief executive runs major decisions.","zh":"創辦人可能設定公司最初願景，而行政總裁作出重大管理決定。"},{"en":"When the same person holds both roles, they may strongly shape the company’s direction.","zh":"當同一人擁有兩個角色，他可能強烈塑造公司方向。"},{"en":"This phrase combines origin and leadership.","zh":"這個短語結合起源和領導。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":17},{"front":"plug his site","meaning":"宣傳他的網站","examples":[{"en":"Jeff Bezos likes to plug his site as offering a huge selection.","zh":"Jeff Bezos 喜歡宣傳他的網站提供巨大選擇。"},{"en":"To plug a site means to promote or advertise it strongly.","zh":"plug a site 是指大力推廣或宣傳某網站。"},{"en":"A teacher may plug a school reading platform during class so students remember to use it.","zh":"老師可能在課堂宣傳學校閱讀平台，讓學生記得使用。"},{"en":"Business leaders plug their services when they want customers and investors to notice them.","zh":"企業領袖想顧客和投資者注意服務時，會宣傳它們。"},{"en":"This phrase is informal and means actively promoting something.","zh":"這個短語較口語，意思是積極推廣某事。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":17},{"front":"a growing army of","meaning":"越來越龐大的……隊伍","examples":[{"en":"Amazon has a growing army of other traders.","zh":"Amazon 有越來越龐大的其他商戶隊伍。"},{"en":"A growing army of people means a large and increasing number of them.","zh":"growing army of people 是指數量龐大且不斷增加的一群人。"},{"en":"A school may have a growing army of volunteers before a major fair.","zh":"學校在大型嘉年華前可能有越來越龐大的義工隊伍。"},{"en":"More traders joining a platform can increase product choice and competition.","zh":"更多商戶加入平台可以增加產品選擇和競爭。"},{"en":"This phrase uses “army” metaphorically to stress size and growth.","zh":"這個短語以「軍隊」作比喻，強調規模和增長。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":17},{"front":"other traders","meaning":"其他商戶","examples":[{"en":"Amazon includes a growing army of other traders.","zh":"Amazon 包括越來越龐大的其他商戶。"},{"en":"Other traders are sellers outside the main company who use the platform to sell goods.","zh":"other traders 是主公司以外、使用平台銷售商品的賣家。"},{"en":"A marketplace website may host other traders selling second-hand books and electronics.","zh":"市集網站可能容納其他商戶出售二手書和電子產品。"},{"en":"Other traders expand choice because the platform no longer sells only its own stock.","zh":"其他商戶增加選擇，因為平台不再只賣自己的存貨。"},{"en":"This phrase refers to outside sellers.","zh":"這個短語指外部賣家。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":17},{"front":"earth’s biggest selection","meaning":"地球上最大的選擇","examples":[{"en":"Amazon presents itself as offering earth’s biggest selection.","zh":"Amazon 把自己說成提供地球上最大的選擇。"},{"en":"Earth’s biggest selection means the widest range of products available anywhere in the world.","zh":"earth’s biggest selection 是指世界任何地方可得的最廣泛產品選擇。"},{"en":"A shop claiming the biggest selection wants customers to believe they can find almost anything there.","zh":"聲稱有最大選擇的商店，是想令顧客相信幾乎甚麼都能找到。"},{"en":"Huge selection attracts shoppers because they can compare many options in one place.","zh":"巨大選擇吸引購物者，因為他們可以在一個地方比較許多選項。"},{"en":"This phrase is promotional and deliberately grand.","zh":"這個短語帶宣傳意味，故意說得宏大。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":17},{"front":"nevertheless","meaning":"然而","examples":[{"en":"Nevertheless, Jeff Bezos is spreading his bets.","zh":"然而，Jeff Bezos 正在分散風險。"},{"en":"Nevertheless means despite what has just been said, the following point is still true.","zh":"nevertheless 是指儘管剛才所說如此，接下來的重點仍然成立。"},{"en":"The exam was difficult; nevertheless, many students finished on time.","zh":"考試很難；然而，許多學生準時完成。"},{"en":"A company may be successful in one area; nevertheless, it may still diversify.","zh":"公司可能在某領域成功；然而，它仍可能多元化。"},{"en":"This word introduces contrast with the previous idea.","zh":"這個詞引入與前一想法的對比。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":18},{"front":"spread one’s bets","meaning":"分散風險；多方面下注","examples":[{"en":"Amazon is spreading its bets beyond direct retailing.","zh":"Amazon 正把風險分散到直接零售以外。"},{"en":"To spread one’s bets means to reduce risk by investing in several different options.","zh":"spread one’s bets 是指透過投放於幾個不同選項來降低風險。"},{"en":"A student applying to several universities is spreading her bets.","zh":"學生申請幾所大學，就是在分散風險。"},{"en":"A company spreads its bets when it sells products, services, and technology support instead of only one thing.","zh":"公司不只賣一樣東西，而是銷售產品、服務和科技支援，就是在分散風險。"},{"en":"This phrase comes from gambling but is often used in business.","zh":"這個短語來自賭博，但常用於商業。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":18},{"front":"e-commerce experience","meaning":"電子商貿經驗","examples":[{"en":"Amazon also sells its e-commerce experience.","zh":"Amazon 也出售其電子商貿經驗。"},{"en":"E-commerce experience means knowledge and skill in running online buying and selling systems.","zh":"e-commerce experience 是營運網上買賣系統的知識和技能。"},{"en":"A company with e-commerce experience knows how to handle checkout, payments, delivery, and customer data.","zh":"有電子商貿經驗的公司懂得處理付款、送貨和顧客數據。"},{"en":"Traditional retailers may buy such experience from firms that already know online retail well.","zh":"傳統零售商可能向已熟悉網上零售的公司購買這種經驗。"},{"en":"This phrase treats experience as a valuable business service.","zh":"這個短語把經驗視為有價值的商業服務。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":18},{"front":"help to run","meaning":"協助營運","examples":[{"en":"Amazon helps to run the websites of traditional retailers.","zh":"Amazon 協助營運傳統零售商的網站。"},{"en":"To help to run something means to assist in operating or managing it.","zh":"help to run something 是指協助操作或管理某事。"},{"en":"A senior student may help to run a school club by organising meetings.","zh":"高年級學生可能透過組織會議來協助營運學會。"},{"en":"Technology companies help retailers run websites when they provide systems and expertise.","zh":"科技公司提供系統和專門知識時，就是協助零售商營運網站。"},{"en":"This phrase suggests practical operational support.","zh":"這個短語暗示實際營運支援。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":18},{"front":"traditional retailers","meaning":"傳統零售商","examples":[{"en":"Amazon helps traditional retailers run their websites.","zh":"Amazon 幫助傳統零售商營運其網站。"},{"en":"Traditional retailers are established shop-based businesses that sell goods to consumers.","zh":"traditional retailers 是既有、以店舖為基礎、向消費者銷售商品的企業。"},{"en":"A department store or supermarket chain is a traditional retailer if it began with physical stores.","zh":"如果百貨公司或連鎖超市始於實體店，它就是傳統零售商。"},{"en":"Traditional retailers may need online partners when they lack digital experience.","zh":"當傳統零售商缺乏數碼經驗時，可能需要網上合作夥伴。"},{"en":"This phrase contrasts store-based sellers with internet-native companies.","zh":"這個短語把店舖型賣家與互聯網原生公司作對比。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":18},{"front":"following headings","meaning":"以下標題","examples":[{"en":"Students match the following headings with the paragraphs.","zh":"學生將以下標題與段落配對。"},{"en":"Following headings means the list of titles printed after the instruction.","zh":"following headings 是指指示後列出的標題列表。"},{"en":"In reading tasks, students should read the following headings before matching paragraphs.","zh":"在閱讀任務中，學生配對段落前應先閱讀以下標題。"},{"en":"Headings usually summarise main ideas, not tiny details.","zh":"標題通常概括主旨，而不是細小細節。"},{"en":"This phrase points to answer options that come next.","zh":"這個短語指接下來的答案選項。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":18},{"front":"best fit","meaning":"最適合","examples":[{"en":"Students decide which paragraph each heading best fits.","zh":"學生決定每個標題最適合哪一段。"},{"en":"Best fit means the option that matches most accurately or appropriately.","zh":"best fit 是指最準確或最適合的選項。"},{"en":"A teacher may ask which title is the best fit for an essay’s main idea.","zh":"老師可能問哪個標題最適合文章主旨。"},{"en":"In matching tasks, the best fit may not repeat exact words but matches overall meaning.","zh":"在配對題中，最適合的選項未必重複原字，但符合整體意思。"},{"en":"This phrase focuses on suitability.","zh":"這個短語集中於合適程度。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":18},{"front":"compare prices on the Net","meaning":"在網上比較價格","examples":[{"en":"Shopping comparison sites allow users to compare prices on the Net.","zh":"購物比較網站讓使用者在網上比較價格。"},{"en":"To compare prices on the Net means to check online how much different sellers charge.","zh":"compare prices on the Net 是指在網上查看不同賣家收費多少。"},{"en":"A customer may compare prices on the Net before buying a washing machine.","zh":"顧客買洗衣機前可能在網上比較價格。"},{"en":"Online comparison can save money by showing cheaper sellers quickly.","zh":"網上比較可以快速顯示較便宜賣家，從而省錢。"},{"en":"This phrase describes internet-based price checking.","zh":"這個短語描述以互聯網進行的價格檢查。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":18},{"front":"buy online, collect at the store","meaning":"網上購買，店內取貨","examples":[{"en":"Some shoppers buy online and collect at the store.","zh":"有些購物者網上購買，店內取貨。"},{"en":"Buy online, collect at the store means order through the internet and pick up the goods in a physical shop.","zh":"buy online, collect at the store 是指透過互聯網下單，並在實體店領取貨品。"},{"en":"A customer may buy a camera online and collect it at the store after work.","zh":"顧客可能在網上購買相機，下班後到店取貨。"},{"en":"This method saves delivery time and lets customers check the item in person.","zh":"這種方法節省送貨時間，並讓顧客親身檢查物品。"},{"en":"This phrase describes a mixed online-offline shopping method.","zh":"這個短語描述混合網上和線下的購物方法。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":18},{"front":"street and web domination","meaning":"實體店與網上主導地位","examples":[{"en":"The question refers to domination of both the high street and the web.","zh":"題目指實體店和網上的主導地位。"},{"en":"Street and web domination means strong control in both physical retail areas and online shopping spaces.","zh":"street and web domination 是指在實體零售區和網上購物空間都有強大控制力。"},{"en":"A retailer dominates the street if it has many popular stores and dominates the web if its site attracts many shoppers.","zh":"如果零售商有許多受歡迎店舖，就是主導實體市場；如果網站吸引大量顧客，就是主導網絡。"},{"en":"Companies with both advantages can reach customers wherever they shop.","zh":"同時擁有兩種優勢的公司可以在任何購物場景接觸顧客。"},{"en":"This phrase combines offline and online market power.","zh":"這個短語結合線下和網上市場力量。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":18},{"front":"in the footsteps of","meaning":"追隨……的步伐","examples":[{"en":"Some retailers are following in the footsteps of Amazon.","zh":"有些零售商正在追隨 Amazon 的步伐。"},{"en":"To follow in the footsteps of someone means to copy or follow a path they have already taken.","zh":"follow in the footsteps of someone 是指模仿或跟隨某人已走過的路。"},{"en":"A young teacher may follow in the footsteps of a mentor by using similar classroom methods.","zh":"年輕老師可能透過使用相似課堂方法，追隨導師的步伐。"},{"en":"Retailers follow Amazon’s footsteps when they build marketplaces and online services.","zh":"當零售商建立市集和網上服務時，就是追隨 Amazon 的步伐。"},{"en":"This phrase suggests learning from an earlier example.","zh":"這個短語暗示向早前例子學習。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":18},{"front":"according to the text","meaning":"根據文章","examples":[{"en":"Students choose true statements according to the text.","zh":"學生根據文章選擇正確陳述。"},{"en":"According to the text means based only on the information in the passage.","zh":"according to the text 是指只根據篇章中的資料。"},{"en":"In exams, students should answer according to the text, not personal opinion.","zh":"在考試中，學生應根據文章回答，而不是個人意見。"},{"en":"A statement is true according to the text only if the passage supports it.","zh":"只有在文章支持時，陳述才算根據文章屬實。"},{"en":"This phrase limits the evidence source.","zh":"這個短語限制證據來源。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":19},{"front":"the following statements are true","meaning":"以下陳述屬實","examples":[{"en":"Five of the following statements are true.","zh":"以下陳述中有五項屬實。"},{"en":"The following statements are true means the listed sentences match the information in the passage.","zh":"the following statements are true 是指列出的句子符合文章資料。"},{"en":"Students must check each statement carefully rather than choosing the ones that sound familiar.","zh":"學生必須仔細檢查每句陳述，而不是選聽起來熟悉的句子。"},{"en":"A true statement is supported by evidence, not by outside guessing.","zh":"屬實陳述由證據支持，而不是由外部猜測支持。"},{"en":"This phrase appears in reading-comprehension tasks.","zh":"這個短語出現在閱讀理解任務中。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":19},{"front":"corresponding letters","meaning":"對應字母","examples":[{"en":"Candidates write the corresponding letters in the answer boxes.","zh":"考生在答案格中寫下對應字母。"},{"en":"Corresponding letters are the option letters that match the correct answers.","zh":"corresponding letters 是與正確答案相配的選項字母。"},{"en":"If answer A matches the first statement, students write the corresponding letter A.","zh":"如果答案 A 與第一句陳述相符，學生就寫對應字母 A。"},{"en":"Writing the wrong letter can lose marks even if the student understands the idea.","zh":"即使學生理解意思，寫錯字母也可能失分。"},{"en":"This phrase focuses on matching answer labels.","zh":"這個短語集中於配對答案標籤。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":19},{"front":"in any order","meaning":"以任何次序","examples":[{"en":"The answers can be written in any order.","zh":"答案可以以任何次序書寫。"},{"en":"In any order means the sequence does not matter.","zh":"in any order 是指次序不重要。"},{"en":"Students may list the correct letters in any order if the instructions allow it.","zh":"如果指示容許，學生可以以任何次序列出正確字母。"},{"en":"This reduces pressure because candidates do not need to rank the answers.","zh":"這減少壓力，因為考生不需要排列答案高低。"},{"en":"This phrase tells students that arrangement is flexible.","zh":"這個短語告訴學生排列方式有彈性。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":19},{"front":"websites operated by","meaning":"由……營運的網站","examples":[{"en":"Websites operated by traditional retailers are growing quickly.","zh":"由傳統零售商營運的網站正在快速增長。"},{"en":"Websites operated by a company are websites managed and run by that company.","zh":"websites operated by a company 是由該公司管理和營運的網站。"},{"en":"A charity website operated by volunteers may share event details and donation links.","zh":"由義工營運的慈善網站可能分享活動資料和捐款連結。"},{"en":"Retail websites grow when the operator has a trusted brand and good delivery system.","zh":"當營運者有可信品牌和良好送貨系統時，零售網站會成長。"},{"en":"This phrase identifies who controls the website.","zh":"這個短語指出誰控制該網站。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":19},{"front":"the fastest growing ones","meaning":"增長最快的那些","examples":[{"en":"The question asks whether traditional retailers’ websites are the fastest growing ones.","zh":"題目問傳統零售商網站是否是增長最快的那些。"},{"en":"The fastest growing ones are the members of a group increasing most quickly.","zh":"fastest growing ones 是一組中增長最快的成員。"},{"en":"In a class, the fastest growing skills may be reading and speaking if students practise daily.","zh":"在班上，如果學生每天練習，閱讀和口語可能是增長最快的技能。"},{"en":"Identifying the fastest growing websites helps show where customer behaviour is moving.","zh":"識別增長最快的網站，有助顯示顧客行為正在往哪裡移動。"},{"en":"This phrase compares growth speed within a group.","zh":"這個短語比較群體內的增長速度。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":19},{"front":"over 19 billion dollars","meaning":"超過190億美元","examples":[{"en":"The question refers to online sales of over 19 billion dollars.","zh":"題目提到超過190億美元的網上銷售。"},{"en":"Over 19 billion dollars means more than $19 billion.","zh":"over 19 billion dollars 是指超過190億美元。"},{"en":"A market worth over 19 billion dollars is large enough to attract serious competition.","zh":"價值超過190億美元的市場足以吸引嚴肅競爭。"},{"en":"Large sales figures show that online shopping has become a major business.","zh":"龐大銷售數字顯示網上購物已成為主要業務。"},{"en":"This phrase gives a high monetary amount.","zh":"這個短語給出高額金額。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":19},{"front":"the biggest online retailer","meaning":"最大的網上零售商","examples":[{"en":"The question asks whether Amazon is the biggest online retailer.","zh":"題目問 Amazon 是否是最大的網上零售商。"},{"en":"The biggest online retailer means the largest company selling goods on the internet.","zh":"biggest online retailer 是在互聯網銷售商品的最大公司。"},{"en":"A retailer may be biggest by visitors, sales, product range, or market share.","zh":"零售商可以按訪客、銷售、產品範圍或市場份額成為最大。"},{"en":"The biggest online retailer can influence customer expectations for delivery and choice.","zh":"最大的網上零售商可以影響顧客對送貨和選擇的期望。"},{"en":"This phrase compares online retail scale.","zh":"這個短語比較網上零售規模。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":19},{"front":"compare prices in different stores","meaning":"比較不同店舖的價格","examples":[{"en":"Shopzilla allows people to compare prices in different stores.","zh":"Shopzilla 讓人們比較不同店舖的價格。"},{"en":"To compare prices in different stores means to check how much the same product costs at several sellers.","zh":"compare prices in different stores 是指檢查同一產品在幾個賣家的價格。"},{"en":"A shopper may compare prices in different stores before buying a television.","zh":"購物者買電視前可能比較不同店舖的價格。"},{"en":"Price comparison helps customers avoid paying more than necessary.","zh":"格價幫助顧客避免付出不必要的高價。"},{"en":"This phrase describes practical shopping research.","zh":"這個短語描述實用購物研究。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":19},{"front":"mix online and traditional shopping","meaning":"混合網上和傳統購物","examples":[{"en":"Some customers like to mix online and traditional shopping.","zh":"有些顧客喜歡混合網上和傳統購物。"},{"en":"To mix online and traditional shopping means to use both websites and physical stores when buying things.","zh":"mix online and traditional shopping 是指購買東西時同時使用網站和實體店。"},{"en":"A customer may choose a phone online but collect it from a shop.","zh":"顧客可能在網上選手機，但到店領取。"},{"en":"Mixing both methods gives shoppers convenience and the chance to see products in person.","zh":"混合兩種方法給購物者方便，也給他們親身看產品的機會。"},{"en":"This phrase describes hybrid shopping behaviour.","zh":"這個短語描述混合式購物行為。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":19},{"front":"one of the first businesses of its kind","meaning":"同類企業中的先驅之一","examples":[{"en":"Circuit City was one of the first businesses of its kind.","zh":"Circuit City 是同類企業中的先驅之一。"},{"en":"One of the first businesses of its kind means among the earliest companies to offer that type of service.","zh":"one of the first businesses of its kind 是指最早提供該類服務的公司之一。"},{"en":"A café that first allowed app ordering in its district was one of the first businesses of its kind locally.","zh":"如果咖啡店是區內最早容許應用程式點餐的店，它就是本地同類企業先驅之一。"},{"en":"Early businesses take risks but can shape customer habits before competitors arrive.","zh":"早期企業承擔風險，但可以在競爭者到來前塑造顧客習慣。"},{"en":"This phrase praises early adoption or innovation.","zh":"這個短語讚揚早期採用或創新。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":19},{"front":"biggest share of","meaning":"最大的……份額","examples":[{"en":"The question asks whether Tesco has the biggest share of Britain’s retail market.","zh":"題目問 Tesco 是否佔有英國零售市場最大份額。"},{"en":"The biggest share of a market means the largest portion controlled by one company.","zh":"biggest share of a market 是一間公司控制的最大市場部分。"},{"en":"A phone brand has the biggest share if more customers buy it than any rival brand.","zh":"如果購買某手機品牌的顧客比任何競爭品牌都多，它就有最大份額。"},{"en":"A bigger share gives a company stronger influence over suppliers and customers.","zh":"較大份額給公司對供應商和顧客更強影響力。"},{"en":"This phrase measures market position.","zh":"這個短語量度市場地位。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":20},{"front":"according to the information given","meaning":"根據所提供的資料","examples":[{"en":"Candidates choose answers according to the information given in the text.","zh":"考生根據文本所提供的資料選擇答案。"},{"en":"According to the information given means based only on the details provided.","zh":"according to the information given 是指只根據已提供的細節。"},{"en":"Students should not use outside facts if the question says to answer according to the text.","zh":"如果題目說根據文本作答，學生不應使用外部事實。"},{"en":"If the information is not given, the safest answer may be NOT GIVEN.","zh":"如果資料沒有提供，最安全的答案可能是 NOT GIVEN。"},{"en":"This phrase limits reasoning to the source.","zh":"這個短語把推理限制在來源中。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":20},{"front":"choose the correct answer","meaning":"選出正確答案","examples":[{"en":"Students choose the correct answer from the choices.","zh":"學生從選項中選出正確答案。"},{"en":"To choose the correct answer means to select the option that best matches the passage or question.","zh":"choose the correct answer 是指選擇最符合文章或題目的選項。"},{"en":"In reading exams, students should underline evidence before choosing an answer.","zh":"在閱讀考試中，學生選答案前應先畫出證據。"},{"en":"A correct answer must fit both meaning and wording of the question.","zh":"正確答案必須同時符合題目的意思和措辭。"},{"en":"This phrase describes a basic exam action.","zh":"這個短語描述基本考試動作。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":20},{"front":"from the choices given","meaning":"從所提供選項中","examples":[{"en":"Candidates choose from the choices given.","zh":"考生從所提供選項中選擇。"},{"en":"From the choices given means using only the options provided in the question.","zh":"from the choices given 是指只使用題目提供的選項。"},{"en":"Students should not invent a new answer when they must choose from the choices given.","zh":"當學生必須從所提供選項中選擇時，不應自創新答案。"},{"en":"Even if several options look possible, only one may best fit the passage.","zh":"即使幾個選項看似可能，可能只有一個最符合文章。"},{"en":"This phrase limits the answer set.","zh":"這個短語限制答案範圍。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":20},{"front":"the busiest day for","meaning":"……最繁忙的一天","examples":[{"en":"The option asks whether Cyber Monday is the busiest day for online shopping.","zh":"該選項問網絡星期一是否是網上購物最繁忙的一天。"},{"en":"The busiest day for something means the day with the highest activity or demand.","zh":"busiest day for something 是某活動或需求最高的一天。"},{"en":"A restaurant’s busiest day may be Sunday if many families eat out then.","zh":"如果許多家庭星期日外出用餐，餐廳最繁忙的一天可能是星期日。"},{"en":"The busiest shopping day can strain websites, delivery systems, and customer service.","zh":"最繁忙購物日會令網站、送貨系統和顧客服務承受壓力。"},{"en":"This phrase identifies peak activity.","zh":"這個短語指出活動高峰。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":20},{"front":"begin shopping for Christmas","meaning":"開始購買聖誕禮物","examples":[{"en":"The option says Americans begin shopping for Christmas on Cyber Monday.","zh":"該選項說美國人在網絡星期一開始購買聖誕禮物。"},{"en":"To begin shopping for Christmas means to start buying gifts, food, or decorations for Christmas.","zh":"begin shopping for Christmas 是指開始為聖誕節購買禮物、食物或裝飾。"},{"en":"Some families begin shopping for Christmas early to avoid crowds and high prices.","zh":"有些家庭提早開始聖誕購物，以避開人群和高價。"},{"en":"Early shopping can spread costs over several weeks.","zh":"提早購物可以把成本分散到幾個星期。"},{"en":"This phrase describes the start of seasonal buying.","zh":"這個短語描述季節性購物的開始。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":20},{"front":"be considered to be","meaning":"被認為是","examples":[{"en":"eBay and Amazon are considered to be pure Internet plays.","zh":"eBay 和 Amazon 被認為是純互聯網業務。"},{"en":"To be considered to be something means people regard or describe it in that way.","zh":"be considered to be something 是指人們以某種方式看待或描述某事。"},{"en":"A student may be considered to be hardworking if she submits every assignment on time.","zh":"如果學生每份功課都準時交，她可能被認為是勤奮。"},{"en":"Companies are considered online businesses when most activity happens on the internet.","zh":"當公司大部分活動在互聯網上發生，它就被認為是網上企業。"},{"en":"This phrase shows public or expert judgement.","zh":"這個短語顯示公眾或專家判斷。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":20},{"front":"third-party agents","meaning":"第三方代理","examples":[{"en":"The option mentions third-party agents selling goods online.","zh":"該選項提到第三方代理在網上出售商品。"},{"en":"Third-party agents are outside sellers or intermediaries that operate through another company’s platform.","zh":"third-party agents 是透過另一公司平台運作的外部賣家或中介。"},{"en":"A travel website may use third-party agents to sell hotel rooms.","zh":"旅遊網站可能使用第三方代理銷售酒店房間。"},{"en":"Third-party agents increase choice but may create questions about service responsibility.","zh":"第三方代理增加選擇，但可能帶來服務責任問題。"},{"en":"This phrase refers to outside participants, not the platform owner.","zh":"這個短語指外部參與者，而不是平台擁有者。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":20},{"front":"problems that retailers have","meaning":"零售商面對的問題","examples":[{"en":"The question asks about problems that retailers have when expanding.","zh":"題目問零售商擴展時面對的問題。"},{"en":"Problems that retailers have are difficulties shops face in running or growing their businesses.","zh":"problems that retailers have 是商店在營運或成長時面對的困難。"},{"en":"Retailers may have problems with rent, staffing, delivery, or competition.","zh":"零售商可能面對租金、人手、送貨或競爭問題。"},{"en":"Expansion creates problems because new stores need permission, money, and customer support.","zh":"擴展會產生問題，因為新店需要許可、資金和顧客支持。"},{"en":"This phrase introduces business challenges.","zh":"這個短語引入商業挑戰。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":20},{"front":"when expanding","meaning":"擴展時","examples":[{"en":"Traditional retailers may face problems when expanding.","zh":"傳統零售商擴展時可能面對問題。"},{"en":"When expanding means during the process of growing, opening new branches, or entering new markets.","zh":"when expanding 是指在成長、開新分店或進入新市場的過程中。"},{"en":"A business may face cash-flow problems when expanding too quickly.","zh":"如果企業擴展太快，可能在擴展時面對現金流問題。"},{"en":"Expansion can bring opportunity, but it also creates new costs and risks.","zh":"擴展可以帶來機會，但也帶來新成本和風險。"},{"en":"This phrase focuses on the growth stage of a business.","zh":"這個短語集中於企業成長階段。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":20},{"front":"getting planning permission","meaning":"取得規劃許可","examples":[{"en":"Retailers may have difficulty getting planning permission for new stores.","zh":"零售商可能難以為新店取得規劃許可。"},{"en":"Getting planning permission means obtaining official approval to build or use land in a particular way.","zh":"getting planning permission 是指取得官方批准，以特定方式建造或使用土地。"},{"en":"A shop may need planning permission before opening a large supermarket near homes.","zh":"商店在住宅附近開大型超市前，可能需要規劃許可。"},{"en":"Without permission, expansion can be delayed or stopped.","zh":"沒有許可，擴展可能被延誤或停止。"},{"en":"This phrase refers to legal approval for physical development.","zh":"這個短語指實體發展所需的法律批准。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":20},{"front":"protesting new stores","meaning":"抗議新店舖","examples":[{"en":"People may protest against new stores.","zh":"人們可能抗議新店舖。"},{"en":"Protesting new stores means publicly opposing the opening of new shops or branches.","zh":"protesting new stores 是指公開反對新店或分店開業。"},{"en":"Residents may protest against a new supermarket if they fear traffic and noise.","zh":"如果居民擔心交通和噪音，可能抗議新超市。"},{"en":"Protests can delay construction and make retailers change their plans.","zh":"抗議可以延誤建設，並令零售商改變計劃。"},{"en":"This phrase describes public resistance to expansion.","zh":"這個短語描述公眾對擴展的抗拒。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":21},{"front":"construct new stores","meaning":"興建新店舖","examples":[{"en":"The option mentions finding money to construct new stores.","zh":"該選項提到尋找資金興建新店舖。"},{"en":"To construct new stores means to build new physical shop buildings or branches.","zh":"construct new stores 是指建造新的實體店建築或分店。"},{"en":"A retailer may construct new stores in areas where many new families live.","zh":"零售商可能在人口增加的新家庭區興建新店舖。"},{"en":"Building stores requires money, land, permission, and local support.","zh":"建店需要資金、土地、許可和本地支持。"},{"en":"This phrase refers to physical expansion.","zh":"這個短語指實體擴展。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":21},{"front":"collect their purchases","meaning":"領取所購貨品","examples":[{"en":"Some people buy online and then collect their purchases in-store.","zh":"有些人網上購買，然後在店內領取所購貨品。"},{"en":"To collect their purchases means to pick up goods that have already been bought or ordered.","zh":"collect their purchases 是指領取已購買或訂購的貨品。"},{"en":"A customer may collect purchases from a store after receiving a text message.","zh":"顧客收到短訊後，可能到店舖領取所購貨品。"},{"en":"In-store collection can be faster than waiting at home for delivery.","zh":"店內取貨可能比在家等送貨更快。"},{"en":"This phrase focuses on receiving the bought items.","zh":"這個短語集中於收取已購買物品。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":21},{"front":"wait for delivery","meaning":"等候送貨","examples":[{"en":"Some people collect goods because they do not want to wait for delivery.","zh":"有些人取貨是因為不想等候送貨。"},{"en":"To wait for delivery means to stay available until ordered goods arrive.","zh":"wait for delivery 是指保持有空，直到訂購貨品送達。"},{"en":"A shopper may avoid home delivery if the delivery window is too long.","zh":"如果送貨時間範圍太長，購物者可能避免送貨到家。"},{"en":"Store collection saves customers from waiting at home all day.","zh":"店內取貨讓顧客不用整天在家等候。"},{"en":"This phrase describes the time cost of home delivery.","zh":"這個短語描述送貨到家的時間成本。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":21},{"front":"return the goods","meaning":"退回貨品","examples":[{"en":"Customers know they can return the goods if there is a problem.","zh":"顧客知道如果出現問題，他們可以退回貨品。"},{"en":"To return the goods means to take products back to the seller for refund, exchange, or repair.","zh":"return the goods 是指把產品帶回賣方以退款、換貨或維修。"},{"en":"A customer may return the goods if the size is wrong or the item is damaged.","zh":"如果尺寸不對或物品損壞，顧客可能退回貨品。"},{"en":"Easy returns increase customer confidence in online shopping.","zh":"容易退貨提升顧客對網上購物的信心。"},{"en":"This phrase is about post-purchase action.","zh":"這個短語關於購買後的行動。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":21},{"front":"faulty goods","meaning":"有問題的貨品","examples":[{"en":"Customers want to know they can return faulty goods.","zh":"顧客想知道他們可以退回有問題的貨品。"},{"en":"Faulty goods are products that are damaged, broken, or not working properly.","zh":"faulty goods 是損壞、破裂或不能正常運作的產品。"},{"en":"A customer may return faulty goods if a new kettle does not heat water.","zh":"如果新水壺不能加熱水，顧客可能退回有問題的貨品。"},{"en":"Clear return policies protect shoppers when faulty goods are delivered.","zh":"清楚退貨政策在有問題貨品送達時保護購物者。"},{"en":"This phrase describes goods with defects or problems.","zh":"這個短語描述有缺陷或問題的貨品。"}],"source":"94 - Clicks, Bricks, and Bargains.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 95":[{"front":"looking for life on the ocean wave","meaning":"在海浪上尋找生命","examples":[{"en":"Venter’s expedition was like looking for life on the ocean wave.","zh":"Venter 的考察就像在海浪上尋找生命。"},{"en":"Looking for life on the ocean wave means searching for living things in the sea.","zh":"looking for life on the ocean wave 指在海洋中尋找生物。"},{"en":"Marine scientists may spend weeks looking for life on the ocean wave by collecting water samples.","zh":"海洋科學家可能花數星期採集海水樣本，在海浪上尋找生命。"},{"en":"If researchers look for life on the ocean wave, they may discover organisms too small to see.","zh":"如果研究人員在海浪上尋找生命，他們可能發現肉眼看不見的生物。"},{"en":"The phrase gives a poetic image of scientific exploration at sea.","zh":"這個片語以詩意方式呈現海上科學探索。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":1},{"front":"buccaneering entrepreneur-cum-bioscientist","meaning":"富冒險精神的企業家兼生物科學家","examples":[{"en":"The passage presents Venter as a buccaneering entrepreneur-cum-bioscientist.","zh":"文章把 Venter 描述為富冒險精神的企業家兼生物科學家。"},{"en":"A buccaneering entrepreneur-cum-bioscientist is an adventurous businessperson who is also a biological scientist.","zh":"buccaneering entrepreneur-cum-bioscientist 指一位富冒險精神、同時也是生物科學家的企業家。"},{"en":"A researcher who starts companies and explores unknown ecosystems may seem like a buccaneering entrepreneur-cum-bioscientist.","zh":"一位創辦公司並探索未知生態系統的研究員，可能像富冒險精神的企業家兼生物科學家。"},{"en":"If someone mixes bold business risk with scientific ambition, this description may fit them.","zh":"如果某人把大膽商業風險與科學雄心結合，這個描述就可能適合他。"},{"en":"The phrase suggests daring, independence, science, and commerce together.","zh":"這個片語暗示冒險、獨立、科學和商業並存。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":1},{"front":"luxury yacht","meaning":"豪華遊艇","examples":[{"en":"The scientist collected samples from a luxury yacht.","zh":"這位科學家從豪華遊艇上採集樣本。"},{"en":"A luxury yacht is an expensive private boat designed for comfort and leisure.","zh":"luxury yacht 是為舒適和休閒而設計的昂貴私人船隻。"},{"en":"Wealthy travellers may use a luxury yacht for holidays along a coast.","zh":"富裕旅客可能使用豪華遊艇沿海度假。"},{"en":"If a yacht is also used for research, leisure space may become scientific workspace.","zh":"如果遊艇也用於研究，休閒空間就可能變成科學工作空間。"},{"en":"The phrase suggests comfort, money, and sea travel.","zh":"這個片語暗示舒適、金錢和海上旅行。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":1},{"front":"mighty fine nets","meaning":"非常細密的網","examples":[{"en":"He used mighty fine nets to trawl the world’s oceans.","zh":"他使用非常細密的網在全球海洋中拖網搜尋。"},{"en":"Mighty fine nets are extremely fine nets that can catch very small organisms.","zh":"mighty fine nets 指能捕捉非常微小生物的極細密網。"},{"en":"A scientist may use fine nets to collect tiny insects near a river.","zh":"科學家可能用細密的網在河邊收集微小昆蟲。"},{"en":"If the nets are fine enough, they can capture creatures that ordinary fishing nets miss.","zh":"如果網夠細密，就能捕捉普通漁網漏掉的生物。"},{"en":"The phrase stresses how small the target organisms are.","zh":"這個片語強調目標生物非常細小。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":1},{"front":"trawl the world’s oceans","meaning":"在全球海洋中拖網搜尋","examples":[{"en":"Venter used nets to trawl the world’s oceans for tiny creatures.","zh":"Venter 用網在全球海洋中拖網搜尋微小生物。"},{"en":"Trawl the world’s oceans means search widely through the seas, often by dragging nets or collecting samples.","zh":"trawl the world’s oceans 指在海洋中廣泛搜尋，通常透過拖網或採集樣本。"},{"en":"Researchers may trawl the world’s oceans to compare life in warm and cold waters.","zh":"研究人員可能在全球海洋中拖網搜尋，以比較暖水和冷水中的生命。"},{"en":"If scientists trawl many oceans, they can build a broader picture of marine life.","zh":"如果科學家搜索多個海洋，就能建立更廣闊的海洋生命圖像。"},{"en":"The phrase suggests a large-scale search across the sea.","zh":"這個片語暗示跨海洋的大規模搜尋。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":1},{"front":"the smallest creatures","meaning":"最微小的生物","examples":[{"en":"The expedition searched for the smallest creatures in the ocean.","zh":"這次考察搜尋海洋中最微小的生物。"},{"en":"The smallest creatures are living things so tiny that they may need microscopes to be seen.","zh":"the smallest creatures 是非常細小、可能需要顯微鏡才看得見的生物。"},{"en":"Pond water can contain some of the smallest creatures students study in biology class.","zh":"池塘水中可能含有生物課學生研究的最微小生物。"},{"en":"If scientists study the smallest creatures, they may discover major roles in ecosystems.","zh":"如果科學家研究最微小的生物，可能發現牠們在生態系統中的重大角色。"},{"en":"The phrase refers to tiny life forms, not large animals.","zh":"這個片語指細小生命形式，而不是大型動物。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":1},{"front":"catalogue genetic diversity","meaning":"為基因多樣性編目；記錄基因多樣性","examples":[{"en":"The team wanted to catalogue the genetic diversity of ocean microbes.","zh":"團隊希望記錄海洋微生物的基因多樣性。"},{"en":"Catalogue genetic diversity means record and organise information about different genes in a group of organisms.","zh":"catalogue genetic diversity 指記錄並整理某群生物中不同基因的資料。"},{"en":"Scientists may catalogue genetic diversity in crops to protect useful varieties.","zh":"科學家可能記錄農作物的基因多樣性，以保護有用物種。"},{"en":"If researchers catalogue genetic diversity well, they can find genes with medical or environmental value.","zh":"如果研究人員妥善記錄基因多樣性，就能找到有醫療或環境價值的基因。"},{"en":"The phrase combines careful recording with biological variety.","zh":"這個片語結合仔細記錄和生物多樣性。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":1},{"front":"genetic diversity","meaning":"基因多樣性","examples":[{"en":"Marine microbes contain enormous genetic diversity.","zh":"海洋微生物包含巨大的基因多樣性。"},{"en":"Genetic diversity means variety in genes within a species, group, or ecosystem.","zh":"genetic diversity 指一個物種、群體或生態系統中的基因差異。"},{"en":"A seed bank protects genetic diversity by storing different crop varieties.","zh":"種子庫透過保存不同作物品種來保護基因多樣性。"},{"en":"If genetic diversity is high, some organisms may survive disease or environmental change better.","zh":"如果基因多樣性高，一些生物可能更能抵抗疾病或環境變化。"},{"en":"The phrase refers to biological variety at the gene level.","zh":"這個片語指基因層面的生物多樣性。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":1},{"front":"the most abundant form of life","meaning":"數量最多的生命形式","examples":[{"en":"Microbes are the most abundant form of life in the ocean.","zh":"微生物是海洋中數量最多的生命形式。"},{"en":"The most abundant form of life means the type of living thing found in the greatest numbers.","zh":"the most abundant form of life 指數量最多的一類生物。"},{"en":"In soil, bacteria may be the most abundant form of life by number.","zh":"在泥土中，細菌可能是按數量計最多的生命形式。"},{"en":"If microbes are the most abundant form of life, their hidden effects can be enormous.","zh":"如果微生物是數量最多的生命形式，牠們隱藏的影響可以非常巨大。"},{"en":"The phrase focuses on quantity rather than size.","zh":"這個片語集中於數量，而不是大小。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":1},{"front":"the largest habitat on Earth","meaning":"地球上最大的棲息地","examples":[{"en":"The ocean is the largest habitat on Earth.","zh":"海洋是地球上最大的棲息地。"},{"en":"The largest habitat on Earth means the biggest natural living environment on the planet.","zh":"the largest habitat on Earth 指地球上最大的自然生存環境。"},{"en":"Forests are large habitats, but the ocean covers far more of Earth’s surface.","zh":"森林是大型棲息地，但海洋覆蓋地球表面更多地方。"},{"en":"If the ocean is the largest habitat on Earth, changes there affect global life systems.","zh":"如果海洋是地球上最大的棲息地，那裏的變化會影響全球生命系統。"},{"en":"The phrase stresses the ocean’s enormous ecological importance.","zh":"這個片語強調海洋巨大的生態重要性。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":1},{"front":"hijack the molecular machinery of","meaning":"利用……的分子機制","examples":[{"en":"Scientists hope to hijack the molecular machinery of microbes.","zh":"科學家希望利用微生物的分子機制。"},{"en":"Hijack the molecular machinery of means take control of tiny biological systems and use them for a purpose.","zh":"hijack the molecular machinery of 指控制細小生物系統，並把它們用於某目的。"},{"en":"Engineers may try to hijack the molecular machinery of cells to produce medicine.","zh":"工程師可能嘗試利用細胞的分子機制來生產藥物。"},{"en":"If scientists hijack microbial machinery safely, microbes could help make fuels or drugs.","zh":"如果科學家安全地利用微生物機制，微生物可幫助製造燃料或藥物。"},{"en":"The phrase is metaphorical and suggests using nature’s internal tools.","zh":"這個片語是比喻，暗示使用自然內部工具。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":2},{"front":"molecular machinery","meaning":"分子機制","examples":[{"en":"The molecular machinery of microbes may help produce clean energy.","zh":"微生物的分子機制可能有助生產清潔能源。"},{"en":"Molecular machinery means the tiny biological parts and processes inside cells that do work.","zh":"molecular machinery 指細胞內進行工作的微小生物部件和過程。"},{"en":"The molecular machinery of cells helps copy DNA and make proteins.","zh":"細胞的分子機制幫助複製 DNA 和製造蛋白質。"},{"en":"If molecular machinery is understood, scientists may redesign it for useful tasks.","zh":"如果分子機制被理解，科學家可能重新設計它來完成有用任務。"},{"en":"The phrase describes cell-level systems, not physical machines with gears.","zh":"這個片語描述細胞層面的系統，而不是有齒輪的實體機器。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":2},{"front":"microbes","meaning":"微生物","examples":[{"en":"Microbes make up much of the life in the sea.","zh":"微生物構成海洋中許多生命。"},{"en":"Microbes are extremely small living things such as bacteria, viruses, and some fungi or algae.","zh":"microbes 是非常微小的生物，例如細菌、病毒，以及一些真菌或藻類。"},{"en":"Yogurt contains useful microbes that help create its taste and texture.","zh":"乳酪含有有用微生物，幫助形成味道和質感。"},{"en":"If harmful microbes grow in food, people may become sick.","zh":"如果有害微生物在食物中生長，人們可能生病。"},{"en":"The word refers to tiny life forms, many of which cannot be seen without microscopes.","zh":"這個詞指微小生命形式，許多需要顯微鏡才看得見。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":2},{"front":"make clean energy","meaning":"製造清潔能源","examples":[{"en":"Microbes may one day help us make clean energy.","zh":"微生物有一天可能幫助我們製造清潔能源。"},{"en":"Make clean energy means produce energy with little pollution or carbon emission.","zh":"make clean energy 指生產污染或碳排放較少的能源。"},{"en":"Solar panels help households make clean energy from sunlight.","zh":"太陽能板幫助家庭從陽光製造清潔能源。"},{"en":"If microbes can make clean energy, fuel production may become less harmful to the climate.","zh":"如果微生物能製造清潔能源，燃料生產可能對氣候較少傷害。"},{"en":"The phrase links energy production with environmental benefit.","zh":"這個片語把能源生產與環境好處連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":2},{"front":"develop new drugs","meaning":"研發新藥","examples":[{"en":"Marine genes may help scientists develop new drugs.","zh":"海洋基因可能幫助科學家研發新藥。"},{"en":"Develop new drugs means create and test new medicines for treating disease.","zh":"develop new drugs 指創造並測試用於治療疾病的新藥物。"},{"en":"Pharmaceutical companies develop new drugs after years of laboratory research and clinical trials.","zh":"製藥公司經多年實驗室研究和臨床試驗後研發新藥。"},{"en":"If ocean genes contain useful chemical instructions, they may help develop new drugs.","zh":"如果海洋基因含有有用化學指令，它們可能幫助研發新藥。"},{"en":"The phrase focuses on medical invention.","zh":"這個片語集中於醫學發明。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":2},{"front":"boost the ability of","meaning":"提升……的能力","examples":[{"en":"Microbes may boost the ability of the oceans to absorb carbon dioxide.","zh":"微生物可能提升海洋吸收二氧化碳的能力。"},{"en":"Boost the ability of means increase how well someone or something can do a task.","zh":"boost the ability of 指提升某人或某物完成任務的能力。"},{"en":"Extra practice can boost the ability of students to answer speaking questions calmly.","zh":"額外練習可以提升學生冷靜回答口語問題的能力。"},{"en":"If microbes boost ocean carbon absorption, they may help reduce climate pressure.","zh":"如果微生物提升海洋吸碳能力，它們可能幫助減少氣候壓力。"},{"en":"The phrase describes strengthening a capacity.","zh":"這個片語描述強化能力。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":2},{"front":"the Earth’s lungs","meaning":"地球之肺","examples":[{"en":"The oceans can act like the Earth’s lungs.","zh":"海洋可以像地球之肺一樣運作。"},{"en":"The Earth’s lungs is a metaphor for natural systems that absorb gases and help regulate the atmosphere.","zh":"the Earth’s lungs 是比喻，指吸收氣體並幫助調節大氣的自然系統。"},{"en":"Forests are often called the Earth’s lungs because trees take in carbon dioxide.","zh":"森林常被稱為地球之肺，因為樹木吸收二氧化碳。"},{"en":"If oceans act as the Earth’s lungs, damage to marine life may affect the air and climate.","zh":"如果海洋像地球之肺，海洋生命受損可能影響空氣和氣候。"},{"en":"The phrase makes environmental functions easier to imagine.","zh":"這個片語令環境功能更容易想像。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":2},{"front":"breathe more carbon dioxide","meaning":"吸收更多二氧化碳","examples":[{"en":"Marine organisms may help the Earth’s lungs breathe more carbon dioxide.","zh":"海洋生物可能幫助地球之肺吸收更多二氧化碳。"},{"en":"Breathe more carbon dioxide here means absorb or take in more carbon dioxide from the atmosphere.","zh":"breathe more carbon dioxide 在此指從大氣中吸收更多二氧化碳。"},{"en":"A well-managed forest can, in a loose sense, breathe more carbon dioxide as it grows.","zh":"管理良好的森林在生長時，可寬泛地說吸收更多二氧化碳。"},{"en":"If marine organisms help oceans breathe more carbon dioxide, warming may slow slightly.","zh":"如果海洋生物幫助海洋吸收更多二氧化碳，暖化可能稍為減慢。"},{"en":"The phrase is metaphorical; oceans do not literally breathe like animals.","zh":"這個片語是比喻；海洋不是真的像動物一樣呼吸。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":2},{"front":"limit global warming","meaning":"限制全球暖化","examples":[{"en":"Capturing more carbon dioxide may help limit global warming.","zh":"捕捉更多二氧化碳可能有助限制全球暖化。"},{"en":"Limit global warming means reduce or slow the rise in Earth’s average temperature.","zh":"limit global warming 指減少或減慢地球平均溫度上升。"},{"en":"Using less coal and oil can help limit global warming.","zh":"減少使用煤和石油可以幫助限制全球暖化。"},{"en":"If oceans absorb more carbon, they may help limit global warming for a time.","zh":"如果海洋吸收更多碳，它們可能暫時幫助限制全球暖化。"},{"en":"The phrase describes reducing climate change, not stopping all warming instantly.","zh":"這個片語描述減少氣候變化，而不是立即停止所有暖化。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":2},{"front":"sound like the outline for","meaning":"聽起來像……的大綱","examples":[{"en":"The project may sound like the outline for a science-fiction story.","zh":"這個項目可能聽起來像科幻故事的大綱。"},{"en":"Sound like the outline for means seem similar to the basic plot or plan of something.","zh":"sound like the outline for 指聽起來像某事的基本情節或計劃。"},{"en":"A robot teacher in every classroom may sound like the outline for a future film.","zh":"每間課室都有機械人老師，可能聽起來像未來電影的大綱。"},{"en":"If a real project sounds like science fiction, people may doubt it before seeing evidence.","zh":"如果真實項目聽起來像科幻，人們在看到證據前可能懷疑它。"},{"en":"The phrase compares an idea with a story plan.","zh":"這個片語把一個想法與故事計劃作比較。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":2},{"front":"sci-fi potboiler","meaning":"科幻通俗小說","examples":[{"en":"The project sounds like a sci-fi potboiler.","zh":"這個項目聽起來像科幻通俗小說。"},{"en":"A sci-fi potboiler is an exciting but possibly sensational science-fiction story made for popular entertainment.","zh":"sci-fi potboiler 指令人興奮但可能煽情、為大眾娛樂而寫的科幻故事。"},{"en":"A novel about microbes saving Earth from climate disaster might sound like a sci-fi potboiler.","zh":"一本關於微生物拯救地球免於氣候災難的小說，可能聽起來像科幻通俗小說。"},{"en":"If a scientific idea sounds like a potboiler, writers may be stressing how dramatic it seems.","zh":"如果科學想法聽起來像通俗小說，作者可能在強調它看起來多麼戲劇化。"},{"en":"The phrase is slightly humorous and informal.","zh":"這個片語略帶幽默和口語感。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":3},{"front":"sum up","meaning":"概括","examples":[{"en":"The opening paragraph sums up Craig Venter’s remarkable efforts.","zh":"開首段概括 Craig Venter 的非凡努力。"},{"en":"Sum up means describe the main points briefly and clearly.","zh":"sum up 指簡短清楚地描述重點。"},{"en":"A teacher may sum up a long lesson in three key sentences.","zh":"老師可能用三個重點句概括一堂長課。"},{"en":"If a report sums up the evidence well, readers can understand the argument quickly.","zh":"如果報告能很好地概括證據，讀者可以快速理解論點。"},{"en":"The phrase focuses on giving a short overall account.","zh":"這個片語集中於給出簡短總述。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":3},{"front":"remarkable efforts","meaning":"非凡努力","examples":[{"en":"The passage describes the remarkable efforts of Craig Venter.","zh":"文章描述 Craig Venter 的非凡努力。"},{"en":"Remarkable efforts are actions that are unusually impressive because they require courage, skill, or hard work.","zh":"remarkable efforts 指因需要勇氣、技巧或辛勤工作而特別令人印象深刻的行動。"},{"en":"A nurse makes remarkable efforts when she cares for patients during a crisis.","zh":"護士在危機期間照顧病人，就是作出非凡努力。"},{"en":"If remarkable efforts succeed, they may change how people understand a field.","zh":"如果非凡努力成功，它們可能改變人們對某領域的理解。"},{"en":"The phrase praises work that goes beyond the ordinary.","zh":"這個片語讚揚超越平常的工作。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":3},{"front":"maverick American scientist","meaning":"特立獨行的美國科學家","examples":[{"en":"Craig Venter is described as a maverick American scientist.","zh":"Craig Venter 被描述為特立獨行的美國科學家。"},{"en":"A maverick American scientist is a US scientist who acts independently and challenges normal methods.","zh":"maverick American scientist 指一位行事獨立、挑戰常規方法的美國科學家。"},{"en":"A maverick scientist may ignore old procedures if they believe a faster method works.","zh":"如果特立獨行的科學家相信較快方法有效，可能會忽略舊程序。"},{"en":"If a maverick scientist succeeds, critics may later rethink their objections.","zh":"如果特立獨行的科學家成功，批評者日後可能重新思考反對意見。"},{"en":"The phrase suggests independence, risk, and controversy.","zh":"這個片語暗示獨立、冒險和爭議。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":3},{"front":"announce at the White House","meaning":"在白宮宣佈","examples":[{"en":"Venter announced his genome discovery at the White House.","zh":"Venter 在白宮宣佈他的基因組發現。"},{"en":"Announce at the White House means make a public statement at the official residence and workplace of the US president.","zh":"announce at the White House 指在美國總統官邸及辦公地點作公開宣佈。"},{"en":"A major health programme might be announced at the White House to attract national attention.","zh":"重大健康計劃可能在白宮宣佈，以吸引全國關注。"},{"en":"If a scientific discovery is announced there, it signals political and public importance.","zh":"如果科學發現在那裡宣佈，就表示它具有政治和公眾重要性。"},{"en":"The phrase connects an announcement with high-level visibility.","zh":"這個片語把宣佈與高層可見度連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":3},{"front":"identify all the genes","meaning":"識別出所有基因","examples":[{"en":"Venter identified all the genes in a human being’s DNA.","zh":"Venter 識別出一個人類 DNA 中所有基因。"},{"en":"Identify all the genes means find and name the full set of genetic instructions in an organism.","zh":"identify all the genes 指找出並命名一個生物體中的完整遺傳指令。"},{"en":"Scientists may identify all the genes in a plant to understand disease resistance.","zh":"科學家可能識別出植物中的所有基因，以了解抗病能力。"},{"en":"If researchers identify all the genes, they can study how those genes affect growth and health.","zh":"如果研究人員識別出所有基因，就能研究那些基因如何影響生長和健康。"},{"en":"The phrase describes a complete genetic mapping task.","zh":"這個片語描述完整基因圖譜工作。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":3},{"front":"the genome","meaning":"基因組","examples":[{"en":"The genome contains all the genes in an organism.","zh":"基因組包含一個生物體中的所有基因。"},{"en":"The genome is the complete set of genetic information in a living thing.","zh":"genome 是生物體中的完整遺傳資訊。"},{"en":"A doctor may study a patient’s genome to understand inherited disease risk.","zh":"醫生可能研究病人的基因組，以了解遺傳疾病風險。"},{"en":"If scientists read a genome, they can discover instructions that shape an organism.","zh":"如果科學家讀取基因組，就能發現塑造生物體的指令。"},{"en":"The word refers to the whole genetic blueprint.","zh":"這個詞指完整遺傳藍圖。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":3},{"front":"DNA","meaning":"脫氧核糖核酸；DNA","examples":[{"en":"Venter studied the genes in the DNA of a human being.","zh":"Venter 研究一個人類 DNA 中的基因。"},{"en":"DNA is the molecule that carries genetic instructions in living things.","zh":"DNA 是在生物體中攜帶遺傳指令的分子。"},{"en":"Biology students learn that DNA helps determine inherited traits.","zh":"生物學生會學到 DNA 幫助決定遺傳特徵。"},{"en":"If DNA is damaged, cells may not function properly.","zh":"如果 DNA 受損，細胞可能無法正常運作。"},{"en":"The term is short for deoxyribonucleic acid.","zh":"這個詞是 deoxyribonucleic acid 的縮寫。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":3},{"front":"a human being","meaning":"人類","examples":[{"en":"Venter identified the genome of a human being.","zh":"Venter 識別了一個人類的基因組。"},{"en":"A human being is an individual person.","zh":"a human being 指一個個別的人。"},{"en":"A hospital treats each patient as a human being, not just a medical case.","zh":"醫院把每位病人視為一個人，而不只是醫療個案。"},{"en":"If scientists read the genome of a human being, they examine one person’s genetic information.","zh":"如果科學家讀取一個人類的基因組，他們就是檢查一個人的遺傳資訊。"},{"en":"The phrase is slightly formal and stresses personhood.","zh":"這個片語略正式，強調人的身份。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":3},{"front":"the culmination of","meaning":"……的成果；頂點","examples":[{"en":"The discovery was the culmination of a bitter race.","zh":"這項發現是一場激烈競賽的成果。"},{"en":"The culmination of something is the final result or highest point of a long process.","zh":"the culmination of 指一個漫長過程的最終結果或最高點。"},{"en":"Graduation can be the culmination of years of study and family support.","zh":"畢業可以是多年學習和家庭支持的成果。"},{"en":"If a discovery is the culmination of a race, many earlier efforts led to it.","zh":"如果一項發現是一場競賽的成果，許多早前努力都通向它。"},{"en":"The phrase highlights the final achievement after a long build-up.","zh":"這個片語強調長期累積後的最終成就。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":3},{"front":"a bitter race with","meaning":"與……之間激烈競爭","examples":[{"en":"The genome project was the culmination of a bitter race with government labs.","zh":"基因組項目是與政府實驗室之間激烈競爭的成果。"},{"en":"A bitter race with means a fierce and unpleasant competition against someone.","zh":"a bitter race with 指與某人或某方進行激烈而不愉快的競爭。"},{"en":"Two companies may enter a bitter race to launch the first affordable electric taxi.","zh":"兩間公司可能展開激烈競爭，爭取推出首款可負擔電動的士。"},{"en":"If a scientific race becomes bitter, cooperation may turn into rivalry.","zh":"如果科學競賽變得激烈，合作可能轉為競爭。"},{"en":"The phrase suggests strong competition mixed with conflict.","zh":"這個片語暗示強烈競爭並帶有衝突。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":4},{"front":"international consortium","meaning":"國際聯盟","examples":[{"en":"Venter competed with an international consortium of government labs.","zh":"Venter 與政府實驗室組成的國際聯盟競爭。"},{"en":"An international consortium is a group of organisations from different countries working together.","zh":"international consortium 指來自不同國家的機構共同合作的組織。"},{"en":"Universities may form an international consortium to study climate change.","zh":"大學可能成立國際聯盟來研究氣候變化。"},{"en":"If an international consortium shares data, large research projects become easier.","zh":"如果國際聯盟分享數據，大型研究項目就變得更容易。"},{"en":"The phrase describes organised cooperation across countries.","zh":"這個片語描述跨國有組織合作。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":4},{"front":"government labs","meaning":"政府實驗室","examples":[{"en":"The race involved an international consortium of government labs.","zh":"這場競賽涉及政府實驗室組成的國際聯盟。"},{"en":"Government labs are research laboratories funded or run by public authorities.","zh":"government labs 是由公共當局資助或營運的研究實驗室。"},{"en":"Government labs may test food safety, medicines, climate data, or public health risks.","zh":"政府實驗室可能測試食物安全、藥物、氣候數據或公共健康風險。"},{"en":"If government labs join forces, they can support large scientific projects.","zh":"如果政府實驗室合作，就能支持大型科學項目。"},{"en":"The phrase refers to public research institutions.","zh":"這個片語指公共研究機構。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":4},{"front":"bull-in-a-china-shop approach","meaning":"橫衝直撞的做法","examples":[{"en":"Venter’s bull-in-a-china-shop approach made him controversial.","zh":"Venter 橫衝直撞的做法令他具爭議性。"},{"en":"A bull-in-a-china-shop approach is a forceful, careless, or disruptive way of doing things.","zh":"bull-in-a-china-shop approach 指強硬、粗心或具破壞性的做事方式。"},{"en":"A manager with a bull-in-a-china-shop approach may change every rule before listening to staff.","zh":"採取橫衝直撞做法的經理，可能未聽員工意見就改變所有規則。"},{"en":"If someone uses this approach, they may move fast but upset many people.","zh":"如果某人使用這種做法，可能進展很快，但會令很多人不滿。"},{"en":"The phrase suggests power without delicacy.","zh":"這個片語暗示有力量但缺乏細緻。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":4},{"front":"earn someone the epithet","meaning":"使某人獲得……稱號","examples":[{"en":"His approach earned him the epithet “the bad boy of science”.","zh":"他的做法使他獲得「科學界壞男孩」的稱號。"},{"en":"Earn someone the epithet means cause someone to receive a descriptive nickname or label.","zh":"earn someone the epithet 指使某人獲得一個描述性綽號或標籤。"},{"en":"A fearless journalist may earn the epithet “the watchdog of the city”.","zh":"無畏記者可能獲得「城市監察者」的稱號。"},{"en":"If a person behaves controversially, public reaction may earn them an unflattering epithet.","zh":"如果一個人行為具爭議性，公眾反應可能令他獲得不好聽的稱號。"},{"en":"The phrase focuses on how reputation creates a label.","zh":"這個片語集中於聲譽如何產生標籤。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":4},{"front":"the bad boy of science","meaning":"科學界壞男孩","examples":[{"en":"Venter was called the bad boy of science.","zh":"Venter 被稱為科學界壞男孩。"},{"en":"The bad boy of science means a scientist seen as rebellious, controversial, and unwilling to follow normal rules.","zh":"the bad boy of science 指被視為叛逆、具爭議、不願遵循常規的科學家。"},{"en":"A researcher who challenges respected institutions may be called the bad boy of a field.","zh":"挑戰受尊敬機構的研究員，可能被稱為某領域的壞男孩。"},{"en":"If a scientist’s methods upset the establishment, such a nickname may follow.","zh":"如果科學家的方法令建制派不滿，這類綽號可能隨之而來。"},{"en":"The phrase is informal and partly critical, partly admiring.","zh":"這個片語較口語，既帶批評，也帶欣賞。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":4},{"front":"deter someone","meaning":"阻止某人；使某人卻步","examples":[{"en":"Criticism did not deter Venter from continuing his work.","zh":"批評沒有阻止 Venter 繼續他的工作。"},{"en":"Deter someone means stop or discourage someone from doing something.","zh":"deter someone 指阻止或使某人打消做某事的念頭。"},{"en":"Heavy rain may deter shoppers from going to an outdoor market.","zh":"大雨可能使顧客不去戶外市場。"},{"en":"If criticism does not deter a scientist, they will continue despite opposition.","zh":"如果批評不能阻止科學家，他們會在反對聲中繼續。"},{"en":"The phrase shows that pressure fails or succeeds in stopping action.","zh":"這個片語顯示壓力是否能阻止行動。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":4},{"front":"scientific establishment","meaning":"科學界建制派","examples":[{"en":"Many critics in the scientific establishment opposed Venter.","zh":"科學界建制派中的許多批評者反對 Venter。"},{"en":"The scientific establishment means the accepted institutions, senior experts, and mainstream authorities in science.","zh":"scientific establishment 指科學中公認機構、資深專家和主流權威。"},{"en":"A new theory may face resistance from the scientific establishment at first.","zh":"新理論起初可能面對科學界建制派的阻力。"},{"en":"If the scientific establishment rejects an idea, researchers may need strong evidence to change minds.","zh":"如果科學界建制派拒絕某想法，研究人員可能需要強有力證據來改變看法。"},{"en":"The phrase refers to the powerful mainstream of science.","zh":"這個片語指科學中的強大主流。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":4},{"front":"vilify someone","meaning":"詆毀某人","examples":[{"en":"Some critics in the scientific establishment vilified Venter.","zh":"科學界建制派中的一些批評者詆毀 Venter。"},{"en":"Vilify someone means attack someone’s character harshly and publicly.","zh":"vilify someone 指嚴厲而公開地攻擊某人的人格。"},{"en":"Social media users may vilify a public figure before knowing all the facts.","zh":"社交媒體用戶可能在知道全部事實前詆毀公眾人物。"},{"en":"If critics vilify a scientist, debate can become personal rather than evidence-based.","zh":"如果批評者詆毀科學家，討論可能變成人身攻擊，而不是基於證據。"},{"en":"The phrase is stronger than simply criticise.","zh":"這個片語比單純批評更強烈。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":4},{"front":"disappear from view","meaning":"淡出公眾視野","examples":[{"en":"Many of Venter’s critics later disappeared from view.","zh":"Venter 的許多批評者後來淡出公眾視野。"},{"en":"Disappear from view means stop being noticed, discussed, or publicly visible.","zh":"disappear from view 指不再被注意、討論或公開看見。"},{"en":"A local issue may disappear from view once news cameras leave.","zh":"一旦新聞攝影機離開，本地議題可能淡出公眾視野。"},{"en":"If critics disappear from view after a discovery succeeds, public attention shifts to the result.","zh":"如果發現成功後批評者淡出公眾視野，公眾注意力便轉向結果。"},{"en":"The phrase can describe fading from public attention.","zh":"這個片語可描述從公眾關注中淡出。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":4},{"front":"go on to become","meaning":"後來成為","examples":[{"en":"Venter went on to become the first person to read his own genome.","zh":"Venter 後來成為第一個讀取自己基因組的人。"},{"en":"Go on to become means later develop into or achieve a new role or status.","zh":"go on to become 指後來發展成或取得新角色或身份。"},{"en":"A quiet student may go on to become a confident teacher.","zh":"一名安靜學生可能後來成為有信心的老師。"},{"en":"If a researcher goes on to become a leader, early criticism may seem less important.","zh":"如果研究員後來成為領袖，早期批評可能顯得較不重要。"},{"en":"The phrase links an earlier stage with a later achievement.","zh":"這個片語把早期階段與後來成就連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":5},{"front":"read his own genome","meaning":"讀取自己的基因組","examples":[{"en":"Venter became the first person to read his own genome.","zh":"Venter 成為第一個讀取自己基因組的人。"},{"en":"Read his own genome means decode and examine the complete genetic information in his own DNA.","zh":"read his own genome 指解碼並檢查自己 DNA 中的完整遺傳資訊。"},{"en":"A patient might read parts of their genome to learn about inherited health risks.","zh":"病人可能讀取自己基因組的一部分，以了解遺傳健康風險。"},{"en":"If someone reads their own genome, private genetic information becomes personally visible.","zh":"如果某人讀取自己的基因組，私人遺傳資訊就變得可被本人看見。"},{"en":"The phrase describes direct access to one’s own genetic blueprint.","zh":"這個片語描述直接接觸自己的遺傳藍圖。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":5},{"front":"undertake an extraordinary effort","meaning":"展開一項非凡工作","examples":[{"en":"Venter is undertaking an extraordinary effort to create a synthetic genome.","zh":"Venter 正在展開一項創造合成基因組的非凡工作。"},{"en":"Undertake an extraordinary effort means begin and carry out an unusually difficult or ambitious task.","zh":"undertake an extraordinary effort 指開始並進行一項異常困難或雄心勃勃的任務。"},{"en":"A school may undertake an extraordinary effort to rebuild after a flood.","zh":"學校可能在水災後展開重建的非凡工作。"},{"en":"If scientists undertake an extraordinary effort, they need money, skill, and long-term commitment.","zh":"如果科學家展開非凡工作，他們需要金錢、技巧和長期承諾。"},{"en":"The phrase stresses both action and difficulty.","zh":"這個片語強調行動和難度。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":5},{"front":"synthetic genome","meaning":"合成基因組","examples":[{"en":"Venter is trying to create a synthetic genome.","zh":"Venter 正在嘗試創造合成基因組。"},{"en":"A synthetic genome is a genome designed or built artificially rather than copied directly from nature.","zh":"synthetic genome 是人工設計或建造，而不是直接從自然複製的基因組。"},{"en":"Scientists may use a synthetic genome to study how simple cells work.","zh":"科學家可能使用合成基因組研究簡單細胞如何運作。"},{"en":"If a synthetic genome controls a cell, it could help create new biological tools.","zh":"如果合成基因組能控制細胞，它可能幫助創造新生物工具。"},{"en":"The phrase belongs to advanced genetic engineering.","zh":"這個片語屬於先進基因工程。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":5},{"front":"artificial organism","meaning":"人工生物","examples":[{"en":"A synthetic genome could be used to create an artificial organism.","zh":"合成基因組可用來創造人工生物。"},{"en":"An artificial organism is a living system designed or built by humans rather than naturally evolved.","zh":"artificial organism 是由人類設計或建造，而不是自然演化形成的生命系統。"},{"en":"Researchers may imagine an artificial organism that produces fuel or medicine.","zh":"研究人員可能想像一種能生產燃料或藥物的人工生物。"},{"en":"If artificial organisms escape control, safety rules become extremely important.","zh":"如果人工生物脫離控制，安全規則就變得極其重要。"},{"en":"The phrase refers to engineered life, not a robot.","zh":"這個片語指工程化生命，而不是機械人。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":5},{"front":"bobbing in the middle of","meaning":"在……中央隨波起伏","examples":[{"en":"Venter is bobbing in the middle of the Sea of Cortez.","zh":"Venter 正在科爾特斯海中央隨波起伏。"},{"en":"Bobbing in the middle of means floating up and down on water in the centre of an area.","zh":"bobbing in the middle of 指在某區域中央的水面上下浮動。"},{"en":"A small boat may be bobbing in the middle of a lake during windy weather.","zh":"大風天氣中，小船可能在湖中央隨波起伏。"},{"en":"If a research yacht is bobbing in the middle of the sea, scientists must work with waves and movement.","zh":"如果研究遊艇在海中央隨波起伏，科學家就必須在波浪和晃動中工作。"},{"en":"The phrase gives a physical image of floating at sea.","zh":"這個片語給出在海上漂浮的實體畫面。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":5},{"front":"the Sea of Cortez","meaning":"科爾特斯海","examples":[{"en":"Venter collected marine DNA in the Sea of Cortez.","zh":"Venter 在科爾特斯海採集海洋 DNA。"},{"en":"The Sea of Cortez is a body of water between Baja California and mainland Mexico.","zh":"Sea of Cortez 是位於下加利福尼亞半島和墨西哥大陸之間的海域。"},{"en":"Marine biologists may visit the Sea of Cortez because it contains rich sea life.","zh":"海洋生物學家可能到科爾特斯海，因為那裏有豐富海洋生命。"},{"en":"If samples come from the Sea of Cortez, they represent one important marine region.","zh":"如果樣本來自科爾特斯海，它們代表一個重要海洋區域。"},{"en":"The phrase names a specific sea used in the expedition.","zh":"這個片語指考察中使用的一個特定海域。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":5},{"front":"mix business with pleasure","meaning":"工作與享樂兼顧","examples":[{"en":"Venter mixed business with pleasure while sailing.","zh":"Venter 航行時把工作與享樂兼顧。"},{"en":"Mix business with pleasure means combine work with enjoyable leisure activities.","zh":"mix business with pleasure 指把工作與愉快的休閒活動結合。"},{"en":"A teacher may mix business with pleasure by attending a conference in a city she wants to visit.","zh":"老師到自己想去的城市參加會議，可能就是工作與享樂兼顧。"},{"en":"If a scientist collects samples while sailing for enjoyment, work and leisure overlap.","zh":"如果科學家一邊享受航行一邊採集樣本，工作和休閒就重疊。"},{"en":"The phrase can sound positive or slightly teasing.","zh":"這個片語可以帶正面或略帶調侃的語氣。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":5},{"front":"marine DNA codes","meaning":"海洋 DNA 編碼","examples":[{"en":"The project aimed to read marine DNA codes.","zh":"該項目旨在讀取海洋 DNA 編碼。"},{"en":"Marine DNA codes are genetic instructions found in ocean organisms.","zh":"marine DNA codes 是海洋生物中的遺傳指令。"},{"en":"Scientists may compare marine DNA codes from warm seas and cold seas.","zh":"科學家可能比較暖海和冷海中的海洋 DNA 編碼。"},{"en":"If marine DNA codes are decoded, researchers can identify organisms without seeing them directly.","zh":"如果海洋 DNA 編碼被解讀，研究人員就能在不直接看見生物下識別牠們。"},{"en":"The phrase connects ocean life with genetic information.","zh":"這個片語把海洋生命與遺傳資訊連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":5},{"front":"sail along","meaning":"沿着……航行","examples":[{"en":"Venter sailed along the west coast of the Americas.","zh":"Venter 沿着美洲西岸航行。"},{"en":"Sail along means travel by boat beside or following a coastline or route.","zh":"sail along 指乘船沿着海岸線或路線航行。"},{"en":"Tourists may sail along a coast to visit small fishing villages.","zh":"遊客可能沿着海岸航行，參觀小漁村。"},{"en":"If researchers sail along many regions, they can collect samples from different waters.","zh":"如果研究人員沿多個地區航行，就能從不同水域採集樣本。"},{"en":"The phrase describes movement by sea along a path.","zh":"這個片語描述沿路線在海上移動。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":5},{"front":"the west coast of the Americas","meaning":"美洲西岸","examples":[{"en":"The expedition followed the west coast of the Americas.","zh":"這次考察沿着美洲西岸進行。"},{"en":"The west coast of the Americas is the Pacific-facing coastline of North, Central, and South America.","zh":"the west coast of the Americas 指北美、中美和南美面向太平洋的海岸線。"},{"en":"Ships travelling along the west coast of the Americas pass many climates and ecosystems.","zh":"沿美洲西岸航行的船隻會經過許多氣候和生態系統。"},{"en":"If an expedition follows this coast, it can sample very different marine environments.","zh":"如果考察沿這條海岸進行，就能採集非常不同的海洋環境樣本。"},{"en":"The phrase identifies a long geographical route.","zh":"這個片語指出一條很長的地理路線。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":6},{"front":"sloop","meaning":"單桅帆船","examples":[{"en":"The Sorcerer II is a 29-metre sloop.","zh":"Sorcerer II 是一艘29米長的單桅帆船。"},{"en":"A sloop is a sailing boat with one mast and a simple sail arrangement.","zh":"sloop 是一種有一支桅杆和簡單帆具配置的帆船。"},{"en":"A sailing school may use a small sloop to teach basic sailing skills.","zh":"帆船學校可能使用小型單桅帆船教授基本航海技巧。"},{"en":"If a sloop is large enough, it can carry equipment for long sea journeys.","zh":"如果單桅帆船足夠大，就能攜帶長途海上旅程所需設備。"},{"en":"The word names a type of sailing vessel.","zh":"這個詞指一種帆船。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":6},{"front":"floating laboratory","meaning":"浮動實驗室","examples":[{"en":"Venter’s yacht is a floating laboratory.","zh":"Venter 的遊艇是一個浮動實驗室。"},{"en":"A floating laboratory is a boat or ship equipped for scientific research.","zh":"floating laboratory 是配備科學研究設備的船隻。"},{"en":"A university may use a floating laboratory to study water quality in a harbour.","zh":"大學可能使用浮動實驗室研究港口水質。"},{"en":"If a boat becomes a floating laboratory, scientists can collect and process samples at sea.","zh":"如果船隻成為浮動實驗室，科學家就能在海上收集和處理樣本。"},{"en":"The phrase combines travel, water, and research equipment.","zh":"這個片語結合旅行、水域和研究設備。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":6},{"front":"rather than","meaning":"而不是","examples":[{"en":"Rather than grow microorganisms in the lab, Venter sampled seawater directly.","zh":"Venter 直接採集海水樣本，而不是在實驗室培養微生物。"},{"en":"Rather than means instead of one thing, another thing is chosen.","zh":"rather than 指選擇一件事，而不是另一件事。"},{"en":"Rather than memorise every sentence, students should learn how the grammar works.","zh":"學生應學習文法如何運作，而不是背誦每一句。"},{"en":"If scientists sample seawater directly rather than grow microbes, they may find more hidden life.","zh":"如果科學家直接採集海水，而不是培養微生物，就可能發現更多隱藏生命。"},{"en":"The phrase creates a clear contrast between two methods.","zh":"這個片語在兩種方法之間形成清楚對比。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":6},{"front":"the traditional method of","meaning":"……的傳統方法","examples":[{"en":"The traditional method of studying microorganisms involves growing them in the lab.","zh":"研究微生物的傳統方法涉及在實驗室培養牠們。"},{"en":"The traditional method of something is the usual older way of doing it.","zh":"the traditional method of 指做某事的通常較舊方法。"},{"en":"The traditional method of language learning often involved memorising lists of words.","zh":"語言學習的傳統方法常涉及背誦詞表。"},{"en":"If a traditional method misses many organisms, scientists may need a new approach.","zh":"如果傳統方法漏掉許多生物，科學家可能需要新方法。"},{"en":"The phrase contrasts an established method with newer alternatives.","zh":"這個片語把既有方法與較新替代方案作對比。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":6},{"front":"microorganisms","meaning":"微生物","examples":[{"en":"Scientists often study microorganisms by growing them in a laboratory.","zh":"科學家常透過在實驗室培養微生物來研究牠們。"},{"en":"Microorganisms are living things too small to be seen clearly without a microscope.","zh":"microorganisms 是沒有顯微鏡便難以清楚看見的微小生物。"},{"en":"Microorganisms in soil help break down dead leaves and recycle nutrients.","zh":"土壤中的微生物幫助分解枯葉並循環營養。"},{"en":"If harmful microorganisms enter drinking water, public health can be at risk.","zh":"如果有害微生物進入食水，公共健康可能受威脅。"},{"en":"The word includes bacteria and many other tiny forms of life.","zh":"這個詞包括細菌和許多其他微小生命形式。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":6},{"front":"grow them in the lab","meaning":"在實驗室培養牠們","examples":[{"en":"The traditional method is to grow microorganisms in the lab.","zh":"傳統方法是在實驗室培養微生物。"},{"en":"Grow them in the lab means cultivate organisms under controlled laboratory conditions.","zh":"grow them in the lab 指在受控實驗室條件下培養生物。"},{"en":"Biology students may grow bacteria in the lab to see how colonies form.","zh":"生物學生可能在實驗室培養細菌，觀察菌落如何形成。"},{"en":"If microbes cannot grow in the lab, scientists may fail to study most of them by traditional methods.","zh":"如果微生物不能在實驗室培養，科學家可能無法用傳統方法研究大部分微生物。"},{"en":"The phrase describes controlled cultivation, not natural growth in the wild.","zh":"這個片語描述受控培養，而不是野外自然生長。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":6},{"front":"one species in every 100","meaning":"每100個物種中只有一個","examples":[{"en":"The laboratory method works with only one species in every 100.","zh":"實驗室方法每100個物種中只有一個適用。"},{"en":"One species in every 100 means only 1 percent of species.","zh":"one species in every 100 指只有百分之一的物種。"},{"en":"If a survey reaches one student in every 100, it may miss most opinions.","zh":"如果調查每100名學生中只接觸到一人，就可能漏掉大多數意見。"},{"en":"If a method studies only one species in every 100, its picture of life is incomplete.","zh":"如果一種方法每100個物種中只研究到一個，它對生命的圖像就不完整。"},{"en":"The phrase highlights a very small proportion.","zh":"這個片語強調非常小的比例。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":6},{"front":"obtain the genetic codes of","meaning":"取得……的基因編碼","examples":[{"en":"Venter obtained the genetic codes of organisms in seawater.","zh":"Venter 取得海水中生物的基因編碼。"},{"en":"Obtain the genetic codes of means get the DNA sequence information from organisms.","zh":"obtain the genetic codes of 指取得生物的 DNA 序列資料。"},{"en":"Scientists may obtain the genetic codes of bacteria to study antibiotic resistance.","zh":"科學家可能取得細菌的基因編碼，以研究抗生素抗藥性。"},{"en":"If researchers obtain genetic codes directly from seawater, they can identify life without growing it first.","zh":"如果研究人員直接從海水取得基因編碼，就能不先培養而識別生命。"},{"en":"The phrase describes collecting genetic information.","zh":"這個片語描述收集遺傳資訊。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":6},{"front":"anything and everything","meaning":"所有東西；一切","examples":[{"en":"Venter collected the genetic codes of anything and everything in seawater.","zh":"Venter 收集海水中所有東西的基因編碼。"},{"en":"Anything and everything means all possible things, without selecting only a few.","zh":"anything and everything 指所有可能的東西，而不是只選少數。"},{"en":"When cleaning a classroom, students may remove anything and everything left under the desks.","zh":"清潔課室時，學生可能清走書桌下留下的一切東西。"},{"en":"If scientists analyse anything and everything in a sample, they may discover unexpected organisms.","zh":"如果科學家分析樣本中的所有東西，就可能發現意想不到的生物。"},{"en":"The phrase stresses total coverage.","zh":"這個片語強調全面涵蓋。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":6},{"front":"present in seawater","meaning":"存在於海水中的","examples":[{"en":"The team analysed organisms present in seawater.","zh":"團隊分析存在於海水中的生物。"},{"en":"Present in seawater means existing or found within seawater.","zh":"present in seawater 指存在或被發現於海水之中。"},{"en":"Salt, minerals, tiny algae, and bacteria are present in seawater.","zh":"鹽分、礦物、微小藻類和細菌都存在於海水中。"},{"en":"If a harmful microbe is present in seawater near a beach, swimmers may be warned.","zh":"如果有害微生物存在於泳灘附近海水中，泳客可能收到警告。"},{"en":"The phrase identifies what exists inside seawater.","zh":"這個片語指出海水內存在甚麼。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":7},{"front":"a radical new view of","meaning":"對……的嶄新觀點","examples":[{"en":"The project created a radical new view of life in the oceans.","zh":"該項目創造了對海洋生命的嶄新觀點。"},{"en":"A radical new view of something is a very different way of understanding it.","zh":"a radical new view of 指非常不同的理解方式。"},{"en":"Online learning gave some teachers a radical new view of what classrooms could be.","zh":"網上學習令一些老師對課室可以是甚麼產生嶄新觀點。"},{"en":"If new evidence changes basic assumptions, it can create a radical new view of a field.","zh":"如果新證據改變基本假設，它可以創造對某領域的嶄新觀點。"},{"en":"The phrase suggests a deep change in understanding.","zh":"這個片語暗示理解上的深層改變。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":7},{"front":"life in the oceans","meaning":"海洋生命","examples":[{"en":"Venter’s work changed how scientists view life in the oceans.","zh":"Venter 的工作改變了科學家如何看待海洋生命。"},{"en":"Life in the oceans means all living organisms found in marine environments.","zh":"life in the oceans 指海洋環境中的所有生物。"},{"en":"Life in the oceans includes whales, fish, coral, plankton, bacteria, and viruses.","zh":"海洋生命包括鯨魚、魚、珊瑚、浮游生物、細菌和病毒。"},{"en":"If life in the oceans changes, food chains and climate systems may also change.","zh":"如果海洋生命改變，食物鏈和氣候系統也可能改變。"},{"en":"The phrase covers both visible animals and invisible microbes.","zh":"這個片語涵蓋可見動物和看不見的微生物。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":7},{"front":"the modern answer to","meaning":"現代版的……","examples":[{"en":"The voyage is described as the modern answer to Darwin’s journey.","zh":"這次航行被描述為達爾文旅程的現代版。"},{"en":"The modern answer to means a present-day version or counterpart of an earlier example.","zh":"the modern answer to 指某早期例子的現代版本或對應物。"},{"en":"Online libraries may be the modern answer to traditional public reading rooms.","zh":"網上圖書館可能是傳統公共閱覽室的現代版。"},{"en":"If Venter’s voyage is the modern answer to Darwin’s, genes replace visible animals as the focus.","zh":"如果 Venter 的航行是達爾文旅程的現代版，基因就取代可見動物成為焦點。"},{"en":"The phrase compares a new activity with a famous older one.","zh":"這個片語把新活動與著名舊例子作比較。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":7},{"front":"19th-century voyage","meaning":"十九世紀航行","examples":[{"en":"Darwin’s 19th-century voyage inspired later scientific exploration.","zh":"達爾文的十九世紀航行啟發後來的科學探索。"},{"en":"A 19th-century voyage is a sea journey that took place between 1801 and 1900.","zh":"19th-century voyage 是1801至1900年間進行的海上旅程。"},{"en":"A museum may display maps from a 19th-century voyage around the world.","zh":"博物館可能展示一次十九世紀環球航行的地圖。"},{"en":"If a voyage happened in the 19th century, its tools and scientific methods were very different from today’s.","zh":"如果航行發生在十九世紀，其工具和科學方法會與今日非常不同。"},{"en":"The phrase identifies both period and travel by sea.","zh":"這個片語同時指出時期和海上旅行。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":7},{"front":"HMS Beagle","meaning":"貝格爾號","examples":[{"en":"Darwin travelled on HMS Beagle.","zh":"達爾文乘坐貝格爾號航行。"},{"en":"HMS Beagle was the ship used in Charles Darwin’s famous scientific voyage.","zh":"HMS Beagle 是 Charles Darwin 著名科學航行所乘坐的船。"},{"en":"Students often learn about HMS Beagle when studying evolution.","zh":"學生研究演化時常會認識貝格爾號。"},{"en":"If a modern expedition is compared with HMS Beagle, the writer suggests historical importance.","zh":"如果現代考察被拿來與貝格爾號相比，作者暗示其歷史重要性。"},{"en":"The phrase names a specific ship in science history.","zh":"這個片語指科學史上的一艘特定船隻。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":7},{"front":"view the world in a gene-centred fashion","meaning":"以基因為中心看世界","examples":[{"en":"Venter wants to view the world in a gene-centred fashion.","zh":"Venter 想以基因為中心看世界。"},{"en":"View the world in a gene-centred fashion means understand life mainly through genes and genetic information.","zh":"view the world in a gene-centred fashion 指主要透過基因和遺傳資訊理解生命。"},{"en":"A doctor may view disease in a gene-centred fashion when studying inherited risk.","zh":"醫生研究遺傳風險時，可能以基因為中心看待疾病。"},{"en":"If scientists view ecosystems through genes, they may discover hidden organisms and relationships.","zh":"如果科學家透過基因看待生態系統，就可能發現隱藏生物和關係。"},{"en":"The phrase describes a genetic lens for understanding life.","zh":"這個片語描述以遺傳角度理解生命。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":7},{"front":"gene-centred","meaning":"以基因為中心的","examples":[{"en":"Venter’s approach is gene-centred.","zh":"Venter 的方法是以基因為中心的。"},{"en":"Gene-centred means focused mainly on genes rather than visible features or whole organisms.","zh":"gene-centred 指主要集中於基因，而不是可見特徵或整個生物體。"},{"en":"A gene-centred study of disease looks at DNA changes before symptoms appear.","zh":"以基因為中心的疾病研究會在症狀出現前檢視 DNA 變化。"},{"en":"If research is gene-centred, it may reveal organisms that cannot be grown in a lab.","zh":"如果研究以基因為中心，就可能揭示不能在實驗室培養的生物。"},{"en":"The phrase describes the main focus of a scientific method.","zh":"這個片語描述科學方法的主要焦點。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":7},{"front":"sort out evolution","meaning":"理清演化過程","examples":[{"en":"Venter hopes to sort out evolution by studying genes.","zh":"Venter 希望透過研究基因來理清演化過程。"},{"en":"Sort out evolution means clarify how living things are related and how they changed over time.","zh":"sort out evolution 指釐清生物如何相關以及如何隨時間改變。"},{"en":"Biology teachers use family trees to help students sort out evolution.","zh":"生物老師使用族譜圖幫助學生理清演化過程。"},{"en":"If genes are compared across organisms, scientists may sort out confusing evolutionary relationships.","zh":"如果比較不同生物的基因，科學家可能理清混亂的演化關係。"},{"en":"The phrase suggests organising a complex scientific picture.","zh":"這個片語暗示整理複雜科學圖像。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":7},{"front":"work back from","meaning":"從……反推","examples":[{"en":"The team works back from the genes to identify organisms.","zh":"團隊從基因反推，以識別生物。"},{"en":"Work back from means begin with later evidence and use it to infer the source or cause.","zh":"work back from 指從後來的證據開始，推斷來源或原因。"},{"en":"A detective may work back from footprints to identify who entered a room.","zh":"偵探可能從足印反推出誰進入房間。"},{"en":"If scientists work back from DNA, they can infer what organisms were present.","zh":"如果科學家從 DNA 反推，就能推斷有哪些生物存在。"},{"en":"The phrase describes reverse reasoning.","zh":"這個片語描述反向推理。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":7},{"front":"what organisms are there","meaning":"那裏有哪些生物","examples":[{"en":"Genes can help reveal what organisms are there.","zh":"基因可以幫助揭示那裏有哪些生物。"},{"en":"What organisms are there means which living things exist in a place or sample.","zh":"what organisms are there 指某地方或樣本中有哪些生物存在。"},{"en":"A pond-water test can show what organisms are there even if the water looks clear.","zh":"池塘水測試可以顯示那裏有哪些生物，即使水看起來清澈。"},{"en":"If researchers know what organisms are there, they can understand the ecosystem better.","zh":"如果研究人員知道那裏有哪些生物，就能更好理解生態系統。"},{"en":"The phrase asks about the living contents of an environment.","zh":"這個片語詢問某環境中的生命內容。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":8},{"front":"metagenomics","meaning":"宏基因組學","examples":[{"en":"Venter calls his approach metagenomics.","zh":"Venter 把他的方法稱為宏基因組學。"},{"en":"Metagenomics is the study of genetic material collected directly from environmental samples.","zh":"metagenomics 是直接從環境樣本收集遺傳材料並加以研究的方法。"},{"en":"Scientists may use metagenomics to study microbes in soil, seawater, or the human gut.","zh":"科學家可能使用宏基因組學研究泥土、海水或人體腸道中的微生物。"},{"en":"If microbes cannot be grown in the lab, metagenomics can still reveal their genes.","zh":"如果微生物不能在實驗室培養，宏基因組學仍可揭示其基因。"},{"en":"The word names a gene-based method for studying whole communities.","zh":"這個詞指用基因研究整個生物群落的方法。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":8},{"front":"make up the vast majority of","meaning":"佔……的絕大部分","examples":[{"en":"Microbes make up the vast majority of life on the planet.","zh":"微生物佔地球生命的絕大部分。"},{"en":"Make up the vast majority of means form most of something by number, amount, or importance.","zh":"make up the vast majority of 指按數量、份量或重要性構成某事物的大部分。"},{"en":"Small daily tasks make up the vast majority of a teacher’s workload.","zh":"日常小任務佔老師工作量的絕大部分。"},{"en":"If microbes make up most life, ignoring them gives a false picture of biology.","zh":"如果微生物佔大部分生命，忽視牠們就會得到錯誤生物圖像。"},{"en":"The phrase stresses that one group forms nearly all of a whole.","zh":"這個片語強調某群體構成整體的幾乎全部。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":8},{"front":"the vast majority of life","meaning":"生命的絕大部分","examples":[{"en":"Microbes represent the vast majority of life on Earth.","zh":"微生物代表地球生命的絕大部分。"},{"en":"The vast majority of life means most living things, especially by number or biological mass.","zh":"the vast majority of life 指大多數生物，尤其按數量或生物量計。"},{"en":"The vast majority of life in a spoonful of soil may be invisible to the eye.","zh":"一匙泥土中的生命絕大部分可能肉眼不可見。"},{"en":"If the vast majority of life is microbial, ecosystems depend heavily on tiny organisms.","zh":"如果生命的絕大部分是微生物，生態系統就高度依賴微小生物。"},{"en":"The phrase reminds us that visible animals are only part of life.","zh":"這個片語提醒我們，可見動物只是生命的一部分。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":8},{"front":"account for up to","meaning":"佔多達……","examples":[{"en":"Microbes account for up to 90 per cent of the biological mass in the sea.","zh":"微生物佔海洋生物量多達90%。"},{"en":"Account for up to means form as much as a stated maximum amount.","zh":"account for up to 指構成最高可達某個指定數量。"},{"en":"Rent can account for up to half of a student’s monthly budget in an expensive city.","zh":"在昂貴城市，租金可佔學生每月預算多達一半。"},{"en":"If microbes account for such a large share of sea life, their role must be important.","zh":"如果微生物佔海洋生命如此大比例，牠們的角色必定重要。"},{"en":"The phrase gives a maximum proportion.","zh":"這個片語給出最高比例。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":8},{"front":"biological mass","meaning":"生物量","examples":[{"en":"Microbes account for much of the biological mass in the sea.","zh":"微生物佔海洋生物量的很大部分。"},{"en":"Biological mass means the total amount of living material in an ecosystem or area.","zh":"biological mass 指某生態系統或地區中生命物質的總量。"},{"en":"A forest’s biological mass includes trees, insects, fungi, birds, and microbes.","zh":"森林的生物量包括樹木、昆蟲、真菌、鳥類和微生物。"},{"en":"If microbes form much of the biological mass, small organisms can still have huge ecological weight.","zh":"如果微生物構成大量生物量，細小生物仍可有巨大生態分量。"},{"en":"The phrase measures living matter, not physical space.","zh":"這個片語量度生命物質，而不是實體空間。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":8},{"front":"central processors of","meaning":"……的核心處理者","examples":[{"en":"Microbes are the central processors of matter and energy in ecosystems.","zh":"微生物是生態系統中物質和能量的核心處理者。"},{"en":"Central processors of means the main agents that transform, recycle, or manage something.","zh":"central processors of 指轉化、循環或管理某事物的主要執行者。"},{"en":"In a school office, administrators are central processors of forms, records, and schedules.","zh":"在校務處中，行政人員是表格、紀錄和時間表的核心處理者。"},{"en":"If microbes process matter and energy, ecosystems depend on their hidden work.","zh":"如果微生物處理物質和能量，生態系統就依賴牠們隱藏的工作。"},{"en":"The phrase compares biological roles to a core processing system.","zh":"這個片語把生物角色比作核心處理系統。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":8},{"front":"matter and energy","meaning":"物質和能量","examples":[{"en":"Microbes process matter and energy in ecosystems.","zh":"微生物在生態系統中處理物質和能量。"},{"en":"Matter and energy are the materials and power that move through living systems.","zh":"matter and energy 是在生命系統中流動的材料和力量。"},{"en":"Food provides both matter and energy for a growing child.","zh":"食物為成長中的孩子提供物質和能量。"},{"en":"If microbes recycle matter and energy, dead material can support new life.","zh":"如果微生物循環物質和能量，死亡物質就可以支持新生命。"},{"en":"The phrase describes two basic things ecosystems must move and transform.","zh":"這個片語描述生態系統必須移動和轉化的兩種基本東西。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":8},{"front":"ecosystems","meaning":"生態系統","examples":[{"en":"Microbes play a central role in marine ecosystems.","zh":"微生物在海洋生態系統中扮演核心角色。"},{"en":"Ecosystems are communities of living things interacting with each other and their environment.","zh":"ecosystems 是生物彼此互動並與環境互動的群落。"},{"en":"A pond ecosystem includes water plants, insects, fish, bacteria, sunlight, and nutrients.","zh":"池塘生態系統包括水生植物、昆蟲、魚、細菌、陽光和營養物。"},{"en":"If one part of an ecosystem changes, food chains and habitats may also change.","zh":"如果生態系統中的一部分改變，食物鏈和棲息地也可能改變。"},{"en":"The word refers to both organisms and their physical surroundings.","zh":"這個詞同時指生物和其物理環境。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":8},{"front":"be responsible for","meaning":"負責；是……的原因","examples":[{"en":"Microbes are responsible for the creation and maintenance of the air we breathe.","zh":"微生物負責創造和維持我們呼吸的空氣。"},{"en":"Be responsible for means be the cause of or have an important role in something.","zh":"be responsible for 指是某事的原因，或在某事中有重要作用。"},{"en":"Poor planning may be responsible for delays in a school event.","zh":"規劃不善可能是學校活動延誤的原因。"},{"en":"If microbes are responsible for air chemistry, tiny organisms support large-scale life.","zh":"如果微生物負責空氣化學，微小生物就支撐大規模生命。"},{"en":"The phrase identifies cause or duty.","zh":"這個片語指出原因或責任。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":8},{"front":"creation and maintenance","meaning":"創造和維持","examples":[{"en":"Microbes help with the creation and maintenance of the air we breathe.","zh":"微生物幫助創造和維持我們呼吸的空氣。"},{"en":"Creation and maintenance means making something and keeping it working or continuing.","zh":"creation and maintenance 指創造某物並保持其運作或延續。"},{"en":"A school website needs both creation and maintenance; it must be built and updated.","zh":"學校網站需要創造和維持；它必須被建立和更新。"},{"en":"If microbes help create and maintain air conditions, they affect life every day.","zh":"如果微生物幫助創造和維持空氣條件，牠們每天都影響生命。"},{"en":"The phrase joins beginning something with preserving it.","zh":"這個片語把開始某事與保存某事連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":9},{"front":"the air we breathe","meaning":"我們呼吸的空氣","examples":[{"en":"Microbes help maintain the air we breathe.","zh":"微生物幫助維持我們呼吸的空氣。"},{"en":"The air we breathe means the atmosphere humans and other animals depend on for life.","zh":"the air we breathe 指人類和其他動物賴以生存的大氣。"},{"en":"Factories and traffic can affect the quality of the air we breathe.","zh":"工廠和交通可以影響我們呼吸的空氣質素。"},{"en":"If marine microbes influence the air we breathe, ocean health matters to human health.","zh":"如果海洋微生物影響我們呼吸的空氣，海洋健康就與人類健康有關。"},{"en":"The phrase makes an environmental issue feel personal and immediate.","zh":"這個片語令環境議題感覺個人化而迫切。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":9},{"front":"our biggest hope of","meaning":"我們……的最大希望","examples":[{"en":"Microbes may be our biggest hope of slowing global warming.","zh":"微生物可能是我們減慢全球暖化的最大希望。"},{"en":"Our biggest hope of means the most promising chance for achieving something.","zh":"our biggest hope of 指達成某事最有希望的機會。"},{"en":"Early treatment may be a patient’s biggest hope of recovery.","zh":"早期治療可能是病人康復的最大希望。"},{"en":"If microbes absorb carbon effectively, they may be a major hope for climate protection.","zh":"如果微生物有效吸收碳，牠們可能是氣候保護的重要希望。"},{"en":"The phrase suggests strong but not guaranteed optimism.","zh":"這個片語暗示強烈但不保證的樂觀。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":9},{"front":"slowing global warming","meaning":"減慢全球暖化","examples":[{"en":"Microbes may help with slowing global warming.","zh":"微生物可能有助減慢全球暖化。"},{"en":"Slowing global warming means reducing the speed at which Earth’s temperature rises.","zh":"slowing global warming 指降低地球溫度上升的速度。"},{"en":"Saving energy and using renewable power can help with slowing global warming.","zh":"節省能源和使用可再生能源可以幫助減慢全球暖化。"},{"en":"If oceans absorb more carbon, they may contribute to slowing global warming.","zh":"如果海洋吸收更多碳，它們可能有助減慢全球暖化。"},{"en":"The phrase describes reducing the pace of climate change.","zh":"這個片語描述降低氣候變化速度。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":9},{"front":"sink of carbon","meaning":"碳匯","examples":[{"en":"The oceans are the biggest sink of carbon.","zh":"海洋是最大的碳匯。"},{"en":"A sink of carbon is a place or system that absorbs and stores carbon.","zh":"sink of carbon 是吸收並儲存碳的地方或系統。"},{"en":"Forests can act as a sink of carbon when trees grow and store carbon in wood.","zh":"當樹木生長並把碳儲存在木材中，森林可以作為碳匯。"},{"en":"If a carbon sink weakens, more carbon dioxide may remain in the atmosphere.","zh":"如果碳匯減弱，更多二氧化碳可能留在大氣中。"},{"en":"The phrase describes carbon storage in nature.","zh":"這個片語描述自然中的碳儲存。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":9},{"front":"thanks in part to","meaning":"部分歸功於","examples":[{"en":"Oceans absorb carbon thanks in part to marine organisms.","zh":"海洋吸收碳，部分歸功於海洋生物。"},{"en":"Thanks in part to means partly because of someone or something helpful.","zh":"thanks in part to 指部分由於某人或某物的幫助。"},{"en":"The school event succeeded thanks in part to parent volunteers.","zh":"學校活動成功，部分歸功於家長義工。"},{"en":"If oceans absorb carbon thanks in part to microbes, tiny life helps regulate climate.","zh":"如果海洋吸收碳部分歸功於微生物，微小生命就幫助調節氣候。"},{"en":"The phrase gives partial credit to one cause.","zh":"這個片語把部分功勞歸於某個原因。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":9},{"front":"absorb carbon from the atmosphere","meaning":"從大氣中吸收碳","examples":[{"en":"Some organisms absorb carbon from the atmosphere.","zh":"有些生物從大氣中吸收碳。"},{"en":"Absorb carbon from the atmosphere means take in carbon dioxide or carbon-containing material from the air.","zh":"absorb carbon from the atmosphere 指從空氣中吸收二氧化碳或含碳物質。"},{"en":"Trees absorb carbon from the atmosphere as they grow.","zh":"樹木生長時會從大氣中吸收碳。"},{"en":"If organisms absorb more carbon from the atmosphere, they may reduce greenhouse gas levels.","zh":"如果生物從大氣中吸收更多碳，就可能降低溫室氣體水平。"},{"en":"The phrase links living processes with climate regulation.","zh":"這個片語把生命過程與氣候調節連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":9},{"front":"build their skeletons and shells","meaning":"建造骨骼和外殼","examples":[{"en":"Organisms use carbon to build their skeletons and shells.","zh":"生物使用碳來建造骨骼和外殼。"},{"en":"Build their skeletons and shells means form hard body parts using materials such as carbon compounds.","zh":"build their skeletons and shells 指使用碳化合物等材料形成堅硬身體部分。"},{"en":"Corals and shellfish need minerals to build their skeletons and shells.","zh":"珊瑚和貝類需要礦物來建造骨骼和外殼。"},{"en":"If ocean chemistry changes, some organisms may struggle to build shells properly.","zh":"如果海洋化學改變，一些生物可能難以正常建造外殼。"},{"en":"The phrase describes biological construction of hard parts.","zh":"這個片語描述硬質身體部分的生物建造。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":9},{"front":"their role and function","meaning":"其角色和功能","examples":[{"en":"Scientists need to understand microbes’ role and function.","zh":"科學家需要理解微生物的角色和功能。"},{"en":"Their role and function means what they do and why they matter in a system.","zh":"their role and function 指它們在系統中做甚麼，以及為何重要。"},{"en":"A school needs to understand each staff member’s role and function during emergencies.","zh":"學校需要在緊急情況中理解每位員工的角色和功能。"},{"en":"If scientists know microbes’ role and function, they can predict ecosystem changes better.","zh":"如果科學家知道微生物的角色和功能，就能更好預測生態系統變化。"},{"en":"The phrase connects position with practical activity.","zh":"這個片語把位置與實際活動連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":9},{"front":"ensure the survival of","meaning":"確保……的存續","examples":[{"en":"Understanding microbes may help ensure the survival of the planet.","zh":"理解微生物可能有助確保地球的存續。"},{"en":"Ensure the survival of means make sure something continues to exist or stay alive.","zh":"ensure the survival of 指確保某物繼續存在或存活。"},{"en":"Vaccination can help ensure the survival of vulnerable patients during disease outbreaks.","zh":"疫苗接種可以在疾病爆發期間幫助確保弱勢病人的生存。"},{"en":"If ecosystems are protected, society can help ensure the survival of many species.","zh":"如果生態系統受保護，社會就能幫助確保許多物種的存續。"},{"en":"The phrase suggests active protection against serious risk.","zh":"這個片語暗示主動防範嚴重風險。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":9},{"front":"human life","meaning":"人類生命","examples":[{"en":"Microbes may be important for the survival of human life.","zh":"微生物可能對人類生命的存續很重要。"},{"en":"Human life means the existence, health, and continuation of people.","zh":"human life 指人的存在、健康和延續。"},{"en":"Clean water and food are basic requirements for human life.","zh":"清潔食水和食物是人類生命的基本需求。"},{"en":"If air, water, or climate systems fail, human life is placed at risk.","zh":"如果空氣、水或氣候系統失效，人類生命就會面臨風險。"},{"en":"The phrase refers to people’s survival and wellbeing.","zh":"這個片語指人類的生存和福祉。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":10},{"front":"founder and chairman of","meaning":"……的創辦人兼主席","examples":[{"en":"Venter is the founder and chairman of the J. Craig Venter Institute.","zh":"Venter 是 J. Craig Venter Institute 的創辦人兼主席。"},{"en":"Founder and chairman of means the person who created an organisation and holds a senior leadership role in it.","zh":"founder and chairman of 指創立一個機構並擔任高層領導職位的人。"},{"en":"The founder and chairman of a school charity may set its goals and lead major decisions.","zh":"學校慈善組織的創辦人兼主席可能設定目標並領導重大決策。"},{"en":"If someone is both founder and chairman, they may strongly shape the organisation’s direction.","zh":"如果某人既是創辦人又是主席，就可能強烈塑造機構方向。"},{"en":"The phrase combines origin with leadership.","zh":"這個片語結合起源和領導。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":10},{"front":"the Sorcerer II expedition","meaning":"Sorcerer II 號考察","examples":[{"en":"The Sorcerer II expedition began with a pilot project in 2003.","zh":"Sorcerer II 號考察於2003年以一個試驗性項目開始。"},{"en":"The Sorcerer II expedition was Venter’s research voyage using the yacht Sorcerer II to collect marine DNA.","zh":"Sorcerer II expedition 是 Venter 使用 Sorcerer II 遊艇採集海洋 DNA 的研究航行。"},{"en":"A science class may study the Sorcerer II expedition as an example of ocean genomics.","zh":"科學課可能把 Sorcerer II 號考察作為海洋基因組學例子來研究。"},{"en":"If an expedition collects samples across oceans, it can reveal patterns hidden in local studies.","zh":"如果考察在多個海洋採樣，就能揭示本地研究看不到的模式。"},{"en":"The phrase names a specific scientific voyage.","zh":"這個片語指一場特定科學航行。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":10},{"front":"pilot project","meaning":"試驗性項目","examples":[{"en":"The expedition began with a pilot project in the Sargasso Sea.","zh":"這次考察以馬尾藻海的一個試驗性項目開始。"},{"en":"A pilot project is a small trial used to test whether a larger plan will work.","zh":"pilot project 是用來測試大型計劃是否可行的小型試驗。"},{"en":"A school may run a pilot project before changing the timetable for all classes.","zh":"學校可能先進行試驗性項目，再為所有班級更改時間表。"},{"en":"If a pilot project succeeds, the team may expand it to more places.","zh":"如果試驗性項目成功，團隊可能把它擴展到更多地方。"},{"en":"The phrase describes a trial stage before full development.","zh":"這個片語描述全面發展前的試驗階段。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":10},{"front":"the Sargasso Sea","meaning":"馬尾藻海","examples":[{"en":"The pilot project took place in the Sargasso Sea near Bermuda.","zh":"試驗性項目在百慕達附近的馬尾藻海進行。"},{"en":"The Sargasso Sea is a region of the Atlantic Ocean known for floating seaweed and clear blue water.","zh":"Sargasso Sea 是大西洋中以漂浮海藻和清澈藍水聞名的區域。"},{"en":"Marine scientists may sample the Sargasso Sea to study open-ocean life.","zh":"海洋科學家可能在馬尾藻海採樣，以研究開放海域生命。"},{"en":"If an area once seen as poor in life contains many genes, assumptions must change.","zh":"如果曾被視為生命貧乏的區域含有許多基因，假設就必須改變。"},{"en":"The phrase names a specific ocean region.","zh":"這個片語指一個特定海洋區域。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":10},{"front":"near Bermuda","meaning":"在百慕達附近","examples":[{"en":"The Sargasso Sea is near Bermuda.","zh":"馬尾藻海在百慕達附近。"},{"en":"Near Bermuda means close to the island territory of Bermuda in the North Atlantic.","zh":"near Bermuda 指靠近北大西洋的百慕達島區。"},{"en":"A research ship near Bermuda may collect samples from warm Atlantic waters.","zh":"在百慕達附近的研究船可能從溫暖的大西洋水域採集樣本。"},{"en":"If a study begins near Bermuda, its results reflect one ocean region, not the whole sea.","zh":"如果研究在百慕達附近開始，其結果反映一個海洋區域，而不是整個海洋。"},{"en":"The phrase gives geographical location.","zh":"這個片語給出地理位置。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":10},{"front":"marine equivalent of a desert","meaning":"海洋中的沙漠等同物","examples":[{"en":"The Sargasso Sea was thought to be the marine equivalent of a desert.","zh":"馬尾藻海曾被認為是海洋中的沙漠等同物。"},{"en":"The marine equivalent of a desert means an ocean area believed to have little life or few nutrients.","zh":"marine equivalent of a desert 指被認為生命少或營養物少的海洋區域。"},{"en":"A clear blue sea may look beautiful but can seem like a marine desert if few organisms grow there.","zh":"清澈藍海可能很美，但如果很少生物生長，就可能像海洋沙漠。"},{"en":"If genetic studies find many microbes in such a place, the old comparison becomes misleading.","zh":"如果基因研究在這類地方發現許多微生物，舊比較就會令人誤解。"},{"en":"The phrase compares a low-productivity sea region with a land desert.","zh":"這個片語把低生產力海域與陸地沙漠相比。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":10},{"front":"fly back and forth","meaning":"來回飛行","examples":[{"en":"Venter flew back and forth to join the crew.","zh":"Venter 來回飛行以加入船員團隊。"},{"en":"Fly back and forth means travel repeatedly by plane between places.","zh":"fly back and forth 指在不同地方之間反覆乘飛機往返。"},{"en":"A business owner may fly back and forth between Hong Kong and Singapore for meetings.","zh":"企業主可能為會議在香港和新加坡之間來回飛行。"},{"en":"If a scientist flies back and forth during an expedition, they can join key stages without staying the whole time.","zh":"如果科學家在考察期間來回飛行，就能參與關鍵階段而不用全程留船。"},{"en":"The phrase suggests repeated travel in two directions.","zh":"這個片語暗示雙向反覆旅行。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":10},{"front":"join the crew","meaning":"加入船員團隊","examples":[{"en":"Venter flew back and forth to join the crew during the expedition.","zh":"Venter 在考察期間來回飛行以加入船員團隊。"},{"en":"Join the crew means become part of the group working on a ship, aircraft, or project.","zh":"join the crew 指加入在船隻、飛機或項目上工作的團隊。"},{"en":"A student may join the crew filming a school documentary.","zh":"學生可能加入拍攝學校紀錄片的團隊。"},{"en":"If a scientist joins the crew at sea, they can help collect samples directly.","zh":"如果科學家在海上加入船員團隊，就能直接協助採集樣本。"},{"en":"The phrase focuses on becoming part of a working team.","zh":"這個片語集中於成為工作團隊的一部分。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":10},{"front":"sample the waters","meaning":"採集海水樣本","examples":[{"en":"The crew sampled the waters from Halifax to the Eastern Tropical Pacific.","zh":"船員從哈利法克斯到東熱帶太平洋採集海水樣本。"},{"en":"Sample the waters means collect water samples for testing or study.","zh":"sample the waters 指採集水樣作測試或研究。"},{"en":"Environmental officers may sample the waters near a beach after heavy rain.","zh":"大雨後，環境人員可能在泳灘附近採集水樣。"},{"en":"If researchers sample waters from many locations, they can compare pollution or life forms.","zh":"如果研究人員從多個地點採集水樣，就能比較污染或生命形式。"},{"en":"The phrase describes scientific collection from water bodies.","zh":"這個片語描述從水體進行科學採集。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":10},{"front":"major ocean passages","meaning":"主要海上航程","examples":[{"en":"Venter took part in all the major ocean passages.","zh":"Venter 參與了所有主要海上航程。"},{"en":"Major ocean passages are important long sections of a sea voyage.","zh":"major ocean passages 是海上航行中重要而漫長的部分。"},{"en":"Sailors prepare carefully before major ocean passages because land may be far away.","zh":"水手在主要海上航程前會仔細準備，因為陸地可能很遠。"},{"en":"If a scientist joins major ocean passages, they experience the most important parts of the expedition.","zh":"如果科學家參與主要海上航程，就能經歷考察中最重要部分。"},{"en":"The phrase highlights significant stretches of ocean travel.","zh":"這個片語強調重要海上旅程段落。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":11},{"front":"in particular","meaning":"尤其；特別是","examples":[{"en":"One passage in particular was a transforming event.","zh":"尤其有一段航程是具有轉化意義的事件。"},{"en":"In particular means especially or more than the others.","zh":"in particular 指尤其或比其他更特別。"},{"en":"Many students improved, but one shy student in particular became much more confident.","zh":"許多學生都有進步，但尤其一名害羞學生變得更有信心。"},{"en":"If one part of a trip stands out in particular, it may have changed the person deeply.","zh":"如果旅程中的某一部分特別突出，它可能深刻改變了那個人。"},{"en":"The phrase singles out one item from a group.","zh":"這個片語從一組事物中突出一項。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":11},{"front":"the Panama Canal","meaning":"巴拿馬運河","examples":[{"en":"The expedition travelled through the Panama Canal.","zh":"這次考察穿過巴拿馬運河。"},{"en":"The Panama Canal is a man-made waterway connecting the Atlantic and Pacific Oceans through Panama.","zh":"Panama Canal 是穿過巴拿馬、連接大西洋和太平洋的人工水道。"},{"en":"Cargo ships use the Panama Canal to avoid sailing around South America.","zh":"貨船使用巴拿馬運河，以避免繞過南美洲航行。"},{"en":"If an expedition passes through the Panama Canal, it can move between oceans more directly.","zh":"如果考察穿過巴拿馬運河，就能更直接地在兩大洋之間移動。"},{"en":"The phrase names a major global shipping route.","zh":"這個片語指重要全球航運路線。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":11},{"front":"Cocos Island","meaning":"科科斯島","examples":[{"en":"The voyage went up to Cocos Island.","zh":"航程向上到達科科斯島。"},{"en":"Cocos Island is an island in the Pacific Ocean often associated with rich marine life.","zh":"Cocos Island 是太平洋中的一個島嶼，常與豐富海洋生命有關。"},{"en":"Divers may visit Cocos Island to see sharks and other ocean animals.","zh":"潛水員可能到訪科科斯島觀看鯊魚和其他海洋動物。"},{"en":"If a research route includes Cocos Island, scientists can sample a remote marine environment.","zh":"如果研究路線包括科科斯島，科學家就能採樣偏遠海洋環境。"},{"en":"The phrase names a specific island destination.","zh":"這個片語指特定島嶼目的地。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":11},{"front":"the Galapagos","meaning":"加拉帕戈斯群島","examples":[{"en":"The expedition continued down to the Galapagos.","zh":"考察繼續向下到達加拉帕戈斯群島。"},{"en":"The Galapagos are islands in the Pacific famous for unique wildlife and evolutionary history.","zh":"Galapagos 是太平洋中以獨特野生動物和演化史聞名的群島。"},{"en":"Biology students often learn about the Galapagos when studying Darwin and natural selection.","zh":"生物學生研究達爾文和自然選擇時，常會認識加拉帕戈斯群島。"},{"en":"If an expedition visits the Galapagos, its scientific symbolism becomes stronger.","zh":"如果考察到訪加拉帕戈斯群島，其科學象徵意義會更強。"},{"en":"The phrase names a famous island group in science.","zh":"這個片語指科學史上一個著名群島。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":11},{"front":"a transforming event","meaning":"具有轉化意義的事件","examples":[{"en":"Venter described one ocean passage as a transforming event.","zh":"Venter 把其中一段海上航程描述為具有轉化意義的事件。"},{"en":"A transforming event is an experience that changes how someone thinks, feels, or works.","zh":"transforming event 是改變某人思想、感受或工作方式的經歷。"},{"en":"A volunteer trip can be a transforming event if it changes a student’s career goals.","zh":"如果義工旅行改變學生的職業目標，它可以是具有轉化意義的事件。"},{"en":"If a voyage becomes a transforming event, the traveller may return with a new sense of purpose.","zh":"如果一次航行成為具有轉化意義的事件，旅者可能帶着新使命感回來。"},{"en":"The phrase suggests deep personal or professional change.","zh":"這個片語暗示深層個人或專業改變。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":11},{"front":"combine genomics with","meaning":"將基因組學與……結合","examples":[{"en":"Venter combined genomics with writing and diving.","zh":"Venter 將基因組學與寫作和潛水結合。"},{"en":"Combine genomics with means bring genetic science together with another activity or field.","zh":"combine genomics with 指把基因科學與另一活動或領域結合。"},{"en":"A university course may combine genomics with public health to study disease prevention.","zh":"大學課程可能將基因組學與公共健康結合，以研究疾病預防。"},{"en":"If scientists combine genomics with ocean travel, they can study life directly in the field.","zh":"如果科學家將基因組學與海洋旅行結合，就能在野外直接研究生命。"},{"en":"The phrase highlights mixing disciplines or activities.","zh":"這個片語強調混合不同學科或活動。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":11},{"front":"genomics","meaning":"基因組學","examples":[{"en":"Genomics is central to Venter’s ocean project.","zh":"基因組學是 Venter 海洋項目的核心。"},{"en":"Genomics is the study of genomes and the full set of genes in organisms.","zh":"genomics 是研究基因組和生物體完整基因組合的學科。"},{"en":"Doctors may use genomics to understand why some patients respond differently to medicine.","zh":"醫生可能使用基因組學理解為何某些病人對藥物反應不同。"},{"en":"If genomics is applied to seawater, hidden microbial communities can be studied.","zh":"如果基因組學應用於海水，就能研究隱藏的微生物群落。"},{"en":"The word refers to large-scale genetic study.","zh":"這個詞指大規模遺傳研究。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":11},{"front":"autobiography","meaning":"自傳","examples":[{"en":"Venter worked on an autobiography during the voyage.","zh":"Venter 在航程期間撰寫自傳。"},{"en":"An autobiography is a book or account someone writes about their own life.","zh":"autobiography 是某人寫關於自己人生的書或記述。"},{"en":"A retired teacher may write an autobiography about students, classrooms, and social change.","zh":"退休老師可能寫一本關於學生、課室和社會變化的自傳。"},{"en":"If a scientist writes an autobiography, readers may learn both personal history and research background.","zh":"如果科學家寫自傳，讀者可同時了解個人歷史和研究背景。"},{"en":"The word refers to self-written life story.","zh":"這個詞指自己撰寫的人生故事。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":11},{"front":"dive with sharks","meaning":"與鯊魚潛水","examples":[{"en":"Venter combined scientific work with diving with sharks.","zh":"Venter 將科學工作與鯊魚潛水結合。"},{"en":"Dive with sharks means swim underwater near sharks, usually with diving equipment.","zh":"dive with sharks 指通常使用潛水裝備，在鯊魚附近水下游動。"},{"en":"Tourists may dive with sharks only under strict safety rules.","zh":"遊客只能在嚴格安全規則下與鯊魚潛水。"},{"en":"If a scientist dives with sharks during a research trip, fieldwork and adventure overlap.","zh":"如果科學家在研究旅程中與鯊魚潛水，野外工作和冒險就重疊。"},{"en":"The phrase suggests risk, excitement, and direct contact with marine life.","zh":"這個片語暗示風險、刺激和直接接觸海洋生命。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":11},{"front":"under the gaze of","meaning":"在……注視下","examples":[{"en":"The voyage took place under the gaze of a TV crew.","zh":"這次航行在攝製隊注視下進行。"},{"en":"Under the gaze of means while being watched closely by someone.","zh":"under the gaze of 指在某人密切觀看之下。"},{"en":"A student giving a speech may feel nervous under the gaze of the whole class.","zh":"學生在全班注視下演講時可能感到緊張。"},{"en":"If research happens under the gaze of cameras, public attention may shape how it is presented.","zh":"如果研究在攝影機注視下進行，公眾關注可能影響呈現方式。"},{"en":"The phrase suggests observation and visibility.","zh":"這個片語暗示觀察和可見度。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":12},{"front":"Discovery Channel TV crew","meaning":"探索頻道攝製隊","examples":[{"en":"A Discovery Channel TV crew followed part of the expedition.","zh":"探索頻道攝製隊跟拍了部分考察。"},{"en":"A Discovery Channel TV crew is a filming team working for a documentary television channel.","zh":"Discovery Channel TV crew 是為紀錄片電視頻道工作的拍攝團隊。"},{"en":"A TV crew may record scientists at work so viewers can understand the research process.","zh":"攝製隊可能拍攝科學家工作，讓觀眾理解研究過程。"},{"en":"If a TV crew follows an expedition, the journey may reach a wider audience.","zh":"如果攝製隊跟隨考察，旅程可能接觸更廣泛觀眾。"},{"en":"The phrase identifies a media team connected with science programming.","zh":"這個片語指出與科學節目有關的媒體團隊。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":12},{"front":"a flood of discoveries","meaning":"大量發現","examples":[{"en":"A flood of discoveries emerged from the latest phase of the expedition.","zh":"大量發現從考察最新階段中出現。"},{"en":"A flood of discoveries means a very large number of new findings appearing quickly.","zh":"a flood of discoveries 指大量新發現迅速出現。"},{"en":"After old documents were opened, historians reported a flood of discoveries.","zh":"舊文件公開後，歷史學家報告了大量發現。"},{"en":"If a project produces a flood of discoveries, scientists need time to analyse them properly.","zh":"如果項目產生大量發現，科學家需要時間仔細分析。"},{"en":"The phrase suggests abundance and speed.","zh":"這個片語暗示數量多和速度快。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":12},{"front":"emerge from","meaning":"從……出現","examples":[{"en":"Many discoveries emerged from the latest phase of the expedition.","zh":"許多發現從考察最新階段中出現。"},{"en":"Emerge from means come out of or result from a process, place, or event.","zh":"emerge from 指從某過程、地方或事件中出現或產生。"},{"en":"New ideas may emerge from a classroom discussion when students ask honest questions.","zh":"當學生誠實發問，新想法可能從課堂討論中出現。"},{"en":"If discoveries emerge from an expedition, the journey has produced useful results.","zh":"如果發現從考察中出現，該旅程就產生有用結果。"},{"en":"The phrase links an outcome with its source.","zh":"這個片語把結果與來源連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":12},{"front":"the latest phase of","meaning":"……的最新階段","examples":[{"en":"The latest phase of the expedition produced many discoveries.","zh":"考察的最新階段產生了許多發現。"},{"en":"The latest phase of something is its most recent stage.","zh":"the latest phase of 指某事最近的階段。"},{"en":"The latest phase of a school renovation may include painting and furniture installation.","zh":"學校翻新的最新階段可能包括油漆和家具安裝。"},{"en":"If the latest phase produces strong results, earlier preparation may have paid off.","zh":"如果最新階段產生強勁結果，早期準備可能已見成效。"},{"en":"The phrase divides a long project into stages.","zh":"這個片語把長項目分成階段。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":12},{"front":"phenomenal computing power","meaning":"驚人的電腦運算能力","examples":[{"en":"The analysis required phenomenal computing power.","zh":"這項分析需要驚人的電腦運算能力。"},{"en":"Phenomenal computing power means an extremely large ability to process data with computers.","zh":"phenomenal computing power 指電腦處理數據的能力極大。"},{"en":"Weather forecasting needs phenomenal computing power to model storms and temperatures.","zh":"天氣預報需要驚人的電腦運算能力來模擬風暴和氣溫。"},{"en":"If DNA data are enormous, researchers need strong computers to analyse them.","zh":"如果 DNA 數據龐大，研究人員需要強大電腦分析它們。"},{"en":"The phrase stresses the scale of calculation.","zh":"這個片語強調計算規模。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":12},{"front":"reconstruct and analyse","meaning":"重組並分析","examples":[{"en":"The team used computers to reconstruct and analyse microbial DNA.","zh":"團隊使用電腦重組並分析微生物 DNA。"},{"en":"Reconstruct and analyse means rebuild information from pieces and study it carefully.","zh":"reconstruct and analyse 指從碎片重建資料並仔細研究。"},{"en":"Police may reconstruct and analyse a timeline after an accident.","zh":"警方可能在意外後重組並分析時間線。"},{"en":"If DNA fragments are reconstructed and analysed, scientists can identify genes and organisms.","zh":"如果 DNA 片段被重組並分析，科學家就能識別基因和生物。"},{"en":"The phrase combines rebuilding with detailed examination.","zh":"這個片語結合重建和詳細檢查。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":12},{"front":"microbial DNA","meaning":"微生物 DNA","examples":[{"en":"The expedition generated huge amounts of microbial DNA data.","zh":"這次考察產生了大量微生物 DNA 數據。"},{"en":"Microbial DNA is genetic material from microbes such as bacteria and other tiny organisms.","zh":"microbial DNA 是來自細菌和其他微小生物等微生物的遺傳材料。"},{"en":"A hospital may examine microbial DNA to identify an infection.","zh":"醫院可能檢查微生物 DNA 以識別感染。"},{"en":"If microbial DNA is found in seawater, it can reveal what tiny organisms live there.","zh":"如果海水中發現微生物 DNA，就能揭示那裏有哪些微小生物。"},{"en":"The phrase links microbes with genetic evidence.","zh":"這個片語把微生物與遺傳證據連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":12},{"front":"a single stage of","meaning":"……的單一階段","examples":[{"en":"A single stage of the calculations took more than a million hours.","zh":"這些計算的單一階段用了超過一百萬小時。"},{"en":"A single stage of something means one separate part of a longer process.","zh":"a single stage of 指較長過程中的一個獨立部分。"},{"en":"A single stage of a school project may involve collecting survey answers.","zh":"學校項目的單一階段可能涉及收集問卷答案。"},{"en":"If one stage takes a million computer hours, the whole analysis is extremely demanding.","zh":"如果一個階段需要一百萬電腦小時，整項分析就極其艱巨。"},{"en":"The phrase focuses on one step within a larger task.","zh":"這個片語集中於大型任務中的一個步驟。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":12},{"front":"calculations","meaning":"計算","examples":[{"en":"The calculations required supercomputer time.","zh":"這些計算需要超級電腦運算時間。"},{"en":"Calculations are mathematical or computer-based processes used to work out results.","zh":"calculations 是用來得出結果的數學或電腦處理過程。"},{"en":"Students make calculations when they compare prices and discounts in a shop.","zh":"學生在商店比較價格和折扣時會進行計算。"},{"en":"If scientific calculations involve huge DNA datasets, ordinary computers may be too slow.","zh":"如果科學計算涉及龐大 DNA 數據集，普通電腦可能太慢。"},{"en":"The word refers to working out numbers or data-based results.","zh":"這個詞指算出數字或基於數據的結果。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":12},{"front":"supercomputer time","meaning":"超級電腦運算時間","examples":[{"en":"The calculations used more than a million hours of supercomputer time.","zh":"這些計算使用了超過一百萬小時的超級電腦運算時間。"},{"en":"Supercomputer time means processing time on extremely powerful computers.","zh":"supercomputer time 指在極強大電腦上的處理時間。"},{"en":"Climate researchers may need supercomputer time to model future weather patterns.","zh":"氣候研究人員可能需要超級電腦運算時間來模擬未來天氣模式。"},{"en":"If a project uses huge amounts of supercomputer time, its data analysis is very complex.","zh":"如果項目使用大量超級電腦運算時間，其數據分析就非常複雜。"},{"en":"The phrase measures computing effort, not human working hours.","zh":"這個片語量度電腦運算工作，而不是人類工作時間。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":13},{"front":"a trio of papers","meaning":"三篇論文","examples":[{"en":"Venter announced his findings in a trio of papers.","zh":"Venter 在三篇論文中宣佈他的發現。"},{"en":"A trio of papers means three academic articles or research papers.","zh":"a trio of papers 指三篇學術文章或研究論文。"},{"en":"A research team may publish a trio of papers on climate, health, and economics.","zh":"研究團隊可能發表三篇關於氣候、健康和經濟的論文。"},{"en":"If findings require three papers, the results are probably broad and detailed.","zh":"如果發現需要三篇論文呈現，結果很可能廣泛而詳細。"},{"en":"The phrase is a slightly formal way to say three papers.","zh":"這個片語是 three papers 的稍正式說法。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":13},{"front":"return to port with","meaning":"帶着……返回港口","examples":[{"en":"His team returned to port with hundreds of newly discovered microbes.","zh":"他的團隊帶着數百種新發現微生物返回港口。"},{"en":"Return to port with means come back to harbour carrying or having obtained something.","zh":"return to port with 指帶着或取得某物後返回港口。"},{"en":"A fishing boat may return to port with a full catch after a successful night.","zh":"漁船在成功一夜後可能帶着滿滿漁獲返回港口。"},{"en":"If researchers return to port with new samples, laboratory analysis can begin.","zh":"如果研究人員帶着新樣本返回港口，實驗室分析就可以開始。"},{"en":"The phrase connects the end of a voyage with what was gained.","zh":"這個片語把航程結束與所得收穫連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":13},{"front":"newly discovered microbes","meaning":"新發現的微生物","examples":[{"en":"The team found 400 newly discovered microbes.","zh":"團隊發現了400種新發現的微生物。"},{"en":"Newly discovered microbes are tiny organisms that scientists have only recently identified.","zh":"newly discovered microbes 是科學家最近才識別出的微小生物。"},{"en":"A hospital lab may report newly discovered microbes if unusual bacteria appear in samples.","zh":"如果樣本中出現不尋常細菌，醫院實驗室可能報告新發現的微生物。"},{"en":"If many newly discovered microbes are found, previous knowledge of an ecosystem was incomplete.","zh":"如果發現許多新微生物，先前對生態系統的認識就不完整。"},{"en":"The phrase highlights recent scientific discovery.","zh":"這個片語強調近期科學發現。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":13},{"front":"contain the instructions used to","meaning":"包含用以……的指令","examples":[{"en":"Each gene contains the instructions used to make proteins.","zh":"每個基因包含用以製造蛋白質的指令。"},{"en":"Contain the instructions used to means hold the information needed for a process.","zh":"contain the instructions used to 指包含某過程所需的資料。"},{"en":"A recipe contains the instructions used to bake a cake.","zh":"食譜包含用以烘焗蛋糕的指令。"},{"en":"If genes contain instructions for proteins, changes in genes can affect how bodies work.","zh":"如果基因包含製造蛋白質的指令，基因變化就能影響身體如何運作。"},{"en":"The phrase explains how information guides production.","zh":"這個片語解釋資訊如何引導生產。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":13},{"front":"make the proteins","meaning":"製造蛋白質","examples":[{"en":"Genes contain the instructions used to make proteins.","zh":"基因包含用以製造蛋白質的指令。"},{"en":"Make the proteins means produce the molecules that cells use for structure and function.","zh":"make the proteins 指產生細胞用於結構和功能的分子。"},{"en":"Cells make proteins to build tissues, send signals, and control chemical reactions.","zh":"細胞製造蛋白質來建造組織、傳送訊號和控制化學反應。"},{"en":"If a gene’s instructions change, the cell may make a different protein.","zh":"如果基因指令改變，細胞可能製造不同蛋白質。"},{"en":"The phrase describes a basic biological process.","zh":"這個片語描述基本生物過程。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":13},{"front":"build and operate living things","meaning":"建構並運作生物體","examples":[{"en":"Proteins help build and operate living things.","zh":"蛋白質幫助建構並運作生物體。"},{"en":"Build and operate living things means create body structures and keep biological processes working.","zh":"build and operate living things 指建立身體結構並維持生物過程運作。"},{"en":"In a body, proteins help build muscles and operate chemical reactions.","zh":"在身體中，蛋白質幫助建構肌肉並運作化學反應。"},{"en":"If proteins do not work properly, living things may grow poorly or become ill.","zh":"如果蛋白質不能正常運作，生物體可能生長不良或生病。"},{"en":"The phrase shows that proteins support both structure and function.","zh":"這個片語顯示蛋白質支撐結構和功能。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":13},{"front":"Venter’s bounty","meaning":"Venter 的豐富收穫","examples":[{"en":"Venter’s bounty doubled the number of genes known to science.","zh":"Venter 的豐富收穫令科學界已知基因數量增加一倍。"},{"en":"Venter’s bounty means the rich collection of discoveries produced by Venter’s expedition.","zh":"Venter’s bounty 指 Venter 考察產生的豐富發現。"},{"en":"A teacher’s bounty of examples can help students understand difficult vocabulary.","zh":"老師的大量例子可以幫助學生理解困難詞彙。"},{"en":"If a research bounty doubles known genes, the project has produced an enormous scientific harvest.","zh":"如果研究收穫令已知基因數量增加一倍，該項目就產生了巨大的科學收成。"},{"en":"The phrase treats discoveries like valuable treasure.","zh":"這個片語把發現視為有價值的寶藏。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":13},{"front":"double the number known to science","meaning":"令科學界已知數量增加一倍","examples":[{"en":"The new genes doubled the number known to science.","zh":"這些新基因令科學界已知數量增加一倍。"},{"en":"Double the number known to science means increase the scientifically recorded total to twice its previous size.","zh":"double the number known to science 指把科學記錄中的總數增加至原來兩倍。"},{"en":"A new survey could double the number of bird species known in a small forest.","zh":"一項新調查可能令一片小森林中已知鳥類數量增加一倍。"},{"en":"If a discovery doubles a known number, it greatly expands a field’s knowledge.","zh":"如果一項發現令已知數量增加一倍，它就大大擴展某領域知識。"},{"en":"The phrase describes a dramatic increase in scientific records.","zh":"這個片語描述科學記錄中的劇烈增加。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":13},{"front":"harness genetic information","meaning":"利用基因資料","examples":[{"en":"Synthetic Genomics wants to harness genetic information.","zh":"Synthetic Genomics 希望利用基因資料。"},{"en":"Harness genetic information means use gene data in a practical and controlled way.","zh":"harness genetic information 指以實用且受控方式使用基因數據。"},{"en":"Doctors may harness genetic information to choose safer medicine for patients.","zh":"醫生可能利用基因資料為病人選擇較安全藥物。"},{"en":"If companies harness genetic information from microbes, they may create fuels or drugs.","zh":"如果公司利用微生物的基因資料，就可能創造燃料或藥物。"},{"en":"The phrase suggests turning knowledge into useful power.","zh":"這個片語暗示把知識轉化為有用力量。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":13},{"front":"turn carbon dioxide into","meaning":"將二氧化碳轉化為","examples":[{"en":"The company wants to turn carbon dioxide into fuels.","zh":"該公司希望將二氧化碳轉化為燃料。"},{"en":"Turn carbon dioxide into means convert carbon dioxide into another useful substance.","zh":"turn carbon dioxide into 指把二氧化碳轉化成另一種有用物質。"},{"en":"Scientists hope to turn waste gases into materials for industry.","zh":"科學家希望把廢氣轉化為工業材料。"},{"en":"If microbes can turn carbon dioxide into fuel, emissions may become a resource.","zh":"如果微生物能將二氧化碳轉化為燃料，排放物可能變成資源。"},{"en":"The phrase describes chemical or biological transformation.","zh":"這個片語描述化學或生物轉化。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":14},{"front":"propane","meaning":"丙烷","examples":[{"en":"Microbes may help turn carbon dioxide into propane.","zh":"微生物可能幫助把二氧化碳轉化為丙烷。"},{"en":"Propane is a fuel gas used for heating, cooking, and some vehicles.","zh":"propane 是一種用於供暖、煮食和某些車輛的燃氣。"},{"en":"A campsite may use propane for portable stoves.","zh":"露營地可能使用丙烷作便攜爐燃料。"},{"en":"If microbes produce propane from carbon dioxide, fuel production could change.","zh":"如果微生物從二氧化碳生產丙烷，燃料生產可能改變。"},{"en":"The word refers to a specific hydrocarbon fuel.","zh":"這個詞指一種特定碳氫燃料。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":14},{"front":"short-circuit the traditional process","meaning":"繞過傳統過程","examples":[{"en":"The company hopes to short-circuit the traditional geological process.","zh":"該公司希望繞過傳統地質過程。"},{"en":"Short-circuit the traditional process means bypass the usual long route and achieve the result more directly.","zh":"short-circuit the traditional process 指繞過通常漫長路線，更直接達成結果。"},{"en":"Online booking can short-circuit the traditional process of waiting in a long queue.","zh":"網上預約可以繞過傳統排長隊過程。"},{"en":"If microbes make fuel quickly, they may short-circuit the natural process that forms fossil fuels.","zh":"如果微生物快速製造燃料，它們可能繞過形成化石燃料的自然過程。"},{"en":"The phrase suggests speeding up or bypassing normal steps.","zh":"這個片語暗示加快或避開正常步驟。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":14},{"front":"geological process","meaning":"地質過程","examples":[{"en":"Coal and oil form through a long geological process.","zh":"煤和石油透過漫長地質過程形成。"},{"en":"A geological process is a natural Earth process involving rocks, pressure, heat, time, or movement.","zh":"geological process 是涉及岩石、壓力、熱力、時間或運動的自然地球過程。"},{"en":"Mountain formation is a geological process that can take millions of years.","zh":"造山是一種可能需要數百萬年的地質過程。"},{"en":"If fuel normally forms through geological processes, artificial production may save enormous time.","zh":"如果燃料通常透過地質過程形成，人工生產可能節省大量時間。"},{"en":"The phrase refers to slow natural change in Earth systems.","zh":"這個片語指地球系統中的緩慢自然變化。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":14},{"front":"ancient creatures","meaning":"古代生物","examples":[{"en":"Ancient creatures were compressed into coal and oil.","zh":"古代生物被壓縮成煤和石油。"},{"en":"Ancient creatures are organisms that lived in the distant past.","zh":"ancient creatures 是生活在遙遠過去的生物。"},{"en":"Fossils help students imagine ancient creatures that no longer exist.","zh":"化石幫助學生想像已不存在的古代生物。"},{"en":"If ancient creatures are buried under pressure for long periods, their remains may change chemically.","zh":"如果古代生物在壓力下長期被埋藏，其遺骸可能發生化學變化。"},{"en":"The phrase refers to long-dead life forms.","zh":"這個片語指早已死亡的生命形式。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":14},{"front":"be compressed into","meaning":"被壓縮成","examples":[{"en":"Ancient creatures are compressed into coal and oil over time.","zh":"古代生物隨時間被壓縮成煤和石油。"},{"en":"Be compressed into means be pressed and changed into a denser or different form.","zh":"be compressed into 指被壓迫並變成更密實或不同的形態。"},{"en":"Old paper can be compressed into tight blocks for recycling.","zh":"舊紙可以被壓縮成緊密紙塊作回收。"},{"en":"If organic remains are compressed under heat and pressure, they may become fossil fuels.","zh":"如果有機遺骸在熱力和壓力下被壓縮，可能變成化石燃料。"},{"en":"The phrase stresses pressure and transformation.","zh":"這個片語強調壓力和轉化。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":14},{"front":"coal and oil","meaning":"煤和石油","examples":[{"en":"Ancient organisms can become coal and oil.","zh":"古代生物可以變成煤和石油。"},{"en":"Coal and oil are fossil fuels formed from ancient organic material over long periods.","zh":"coal and oil 是由古代有機物質經長時間形成的化石燃料。"},{"en":"Many power stations and vehicles have depended on coal and oil for energy.","zh":"許多發電廠和車輛一直依賴煤和石油提供能源。"},{"en":"If societies burn coal and oil, carbon dioxide emissions usually increase.","zh":"如果社會燃燒煤和石油，二氧化碳排放通常會增加。"},{"en":"The phrase refers to major traditional energy sources.","zh":"這個片語指主要傳統能源。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":14},{"front":"over the aeons","meaning":"經過漫長年代","examples":[{"en":"Coal and oil form over the aeons.","zh":"煤和石油經過漫長年代形成。"},{"en":"Over the aeons means over extremely long periods of geological time.","zh":"over the aeons 指經過極其漫長的地質時間。"},{"en":"Rocks can change shape and position over the aeons.","zh":"岩石經過漫長年代可以改變形狀和位置。"},{"en":"If fossil fuels form over the aeons, they cannot be replaced quickly after use.","zh":"如果化石燃料經過漫長年代形成，使用後就不能快速補充。"},{"en":"The phrase emphasises immense time.","zh":"這個片語強調極長時間。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":14},{"front":"hydrogen production","meaning":"氫氣生產","examples":[{"en":"Hydrogen production is another target of Venter’s company.","zh":"氫氣生產是 Venter 公司另一個目標。"},{"en":"Hydrogen production means making hydrogen gas for use as fuel or industrial material.","zh":"hydrogen production 指製造氫氣，用作燃料或工業材料。"},{"en":"Engineers study hydrogen production to support cleaner transport.","zh":"工程師研究氫氣生產，以支持較清潔交通。"},{"en":"If hydrogen production becomes cheap and clean, buses and factories may reduce emissions.","zh":"如果氫氣生產變得便宜清潔，巴士和工廠可能減少排放。"},{"en":"The phrase describes making a fuel, not simply finding it.","zh":"這個片語描述製造燃料，而不只是發現燃料。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":14},{"front":"the ultimate clean fuel","meaning":"終極清潔燃料","examples":[{"en":"Hydrogen is described as the ultimate clean fuel.","zh":"氫氣被描述為終極清潔燃料。"},{"en":"The ultimate clean fuel means a fuel imagined as extremely clean and highly desirable.","zh":"the ultimate clean fuel 指被想像為極其清潔且非常理想的燃料。"},{"en":"Some people see green hydrogen as the ultimate clean fuel for heavy transport.","zh":"有些人把綠氫視為重型交通的終極清潔燃料。"},{"en":"If a fuel produces only water when used, it may seem like an ideal clean fuel.","zh":"如果燃料使用時只產生水，它可能看似理想清潔燃料。"},{"en":"The phrase expresses a very strong positive judgement.","zh":"這個片語表達非常強烈的正面判斷。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":14},{"front":"when it comes to","meaning":"說到……","examples":[{"en":"When it comes to climate change, the expedition produced another insight.","zh":"說到氣候變化，這次考察帶來另一項見解。"},{"en":"When it comes to means when discussing or considering a particular subject.","zh":"when it comes to 指在討論或考慮某個特定主題時。"},{"en":"When it comes to grammar, small mistakes can change meaning.","zh":"說到文法，小錯誤可以改變意思。"},{"en":"If a report says when it comes to energy, it is shifting focus to that topic.","zh":"如果報告說「說到能源」，它就是把焦點轉向該主題。"},{"en":"The phrase introduces a specific area of discussion.","zh":"這個片語引出特定討論範疇。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":15},{"front":"climate change","meaning":"氣候變化","examples":[{"en":"The expedition produced findings relevant to climate change.","zh":"這次考察產生了與氣候變化相關的發現。"},{"en":"Climate change means long-term changes in Earth’s temperature, weather patterns, and climate systems.","zh":"climate change 指地球溫度、天氣模式和氣候系統的長期變化。"},{"en":"Schools may teach climate change through lessons on storms, droughts, and sea-level rise.","zh":"學校可能透過風暴、乾旱和海平面上升的課題教授氣候變化。"},{"en":"If oceans absorb less carbon, climate change may become harder to limit.","zh":"如果海洋吸收較少碳，氣候變化可能更難限制。"},{"en":"The phrase refers to broad environmental change over time.","zh":"這個片語指長時間的廣泛環境變化。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":15},{"front":"throw up another key insight","meaning":"帶來另一項重要見解","examples":[{"en":"The expedition threw up another key insight about carbon capture.","zh":"這次考察帶來另一項關於碳捕捉的重要見解。"},{"en":"Throw up another key insight means unexpectedly produce another important understanding.","zh":"throw up another key insight 指意外產生另一項重要理解。"},{"en":"A classroom debate may throw up a key insight about why students avoid speaking English.","zh":"課堂辯論可能帶來一項關於學生為何避免說英語的重要見解。"},{"en":"If data throw up a new insight, researchers may change their explanation.","zh":"如果數據帶來新見解，研究人員可能改變解釋。"},{"en":"The phrase suggests discovery emerging from investigation.","zh":"這個片語暗示發現從調查中出現。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":15},{"front":"carbon-hungry organisms","meaning":"渴求碳的生物","examples":[{"en":"Some parts of the ocean contain more carbon-hungry organisms than others.","zh":"海洋某些部分含有比其他地方更多渴求碳的生物。"},{"en":"Carbon-hungry organisms are organisms that take in or use large amounts of carbon.","zh":"carbon-hungry organisms 指吸收或使用大量碳的生物。"},{"en":"Fast-growing plants can be carbon-hungry organisms when they absorb much carbon dioxide.","zh":"快速生長植物在吸收大量二氧化碳時，可被視為渴求碳的生物。"},{"en":"If seas contain many carbon-hungry organisms, they may absorb more atmospheric carbon.","zh":"如果海域含有許多渴求碳的生物，它們可能吸收更多大氣中的碳。"},{"en":"The phrase describes organisms by their appetite for carbon.","zh":"這個片語用對碳的需求來描述生物。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":15},{"front":"local nutrient levels","meaning":"本地營養物水平","examples":[{"en":"Scientists thought populations reflected local nutrient levels.","zh":"科學家認為種群反映本地營養物水平。"},{"en":"Local nutrient levels are the amounts of nutrients available in a particular place.","zh":"local nutrient levels 是某特定地方可用營養物的數量。"},{"en":"Farmers test local nutrient levels in soil before deciding what fertiliser to use.","zh":"農民在決定使用甚麼肥料前會測試土壤本地營養物水平。"},{"en":"If nutrient levels are low, some organisms may grow slowly or remain rare.","zh":"如果營養物水平低，一些生物可能生長緩慢或保持稀少。"},{"en":"The phrase connects biological growth with available food-like substances.","zh":"這個片語把生物生長與可用營養物連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":15},{"front":"this may not be the case","meaning":"情況未必如此","examples":[{"en":"Venter found that this may not be the case.","zh":"Venter 發現情況未必如此。"},{"en":"This may not be the case means the earlier assumption may not be true.","zh":"this may not be the case 指先前假設未必正確。"},{"en":"Many people think expensive lessons are always better, but this may not be the case.","zh":"許多人認為昂貴課堂一定較好，但情況未必如此。"},{"en":"If new evidence contradicts an old idea, researchers may say this is not the case.","zh":"如果新證據與舊想法相矛盾，研究人員可能說情況並非如此。"},{"en":"The phrase gently challenges a previous belief.","zh":"這個片語溫和地挑戰先前信念。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":15},{"front":"the culprit","meaning":"元兇","examples":[{"en":"The culprit could be bacterial viruses.","zh":"元兇可能是細菌病毒。"},{"en":"The culprit means the thing or person responsible for a problem.","zh":"the culprit 指造成問題的人或事物。"},{"en":"If the classroom smells bad, the culprit may be food left in a desk.","zh":"如果課室有臭味，元兇可能是留在書桌裏的食物。"},{"en":"If microbes are unexpectedly low, researchers look for the culprit behind the pattern.","zh":"如果微生物數量意外偏低，研究人員會尋找背後元兇。"},{"en":"The phrase points to the likely cause of trouble.","zh":"這個片語指出問題的可能原因。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":15},{"front":"bacterial viruses","meaning":"細菌病毒","examples":[{"en":"Bacterial viruses may keep microbe levels low.","zh":"細菌病毒可能令微生物水平維持偏低。"},{"en":"Bacterial viruses are viruses that infect bacteria.","zh":"bacterial viruses 是感染細菌的病毒。"},{"en":"Scientists study bacterial viruses to understand how bacterial populations are controlled.","zh":"科學家研究細菌病毒，以理解細菌族群如何被控制。"},{"en":"If bacterial viruses kill many bacteria, microbe levels in an area may fall.","zh":"如果細菌病毒殺死許多細菌，某地區微生物水平可能下降。"},{"en":"The phrase is another way to refer to phages.","zh":"這個片語是指噬菌體的另一種說法。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":15},{"front":"phages","meaning":"噬菌體","examples":[{"en":"Phages are bacterial viruses that may affect microbe populations.","zh":"噬菌體是可能影響微生物種群的細菌病毒。"},{"en":"Phages are viruses that infect and often destroy bacteria.","zh":"phages 是感染並常會破壞細菌的病毒。"},{"en":"Doctors and researchers study phages as possible tools against antibiotic-resistant infections.","zh":"醫生和研究人員研究噬菌體，作為對抗抗藥性感染的可能工具。"},{"en":"If phages attack ocean microbes, they may change carbon absorption in the sea.","zh":"如果噬菌體攻擊海洋微生物，它們可能改變海洋吸碳能力。"},{"en":"The word is short for bacteriophages.","zh":"這個詞是 bacteriophages 的簡稱。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":15},{"front":"keep microbe levels low","meaning":"令微生物水平維持偏低","examples":[{"en":"Phages may keep microbe levels low in some seas.","zh":"噬菌體可能在某些海域令微生物水平維持偏低。"},{"en":"Keep microbe levels low means prevent microbe populations from becoming large.","zh":"keep microbe levels low 指防止微生物族群變大。"},{"en":"Cleaning rules in hospitals help keep harmful microbe levels low.","zh":"醫院清潔規則幫助令有害微生物水平維持偏低。"},{"en":"If viruses keep microbe levels low, fewer carbon-absorbing organisms may be present.","zh":"如果病毒令微生物水平維持偏低，就可能有較少吸碳生物存在。"},{"en":"The phrase describes control of population size.","zh":"這個片語描述對族群大小的控制。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":15},{"front":"inhibit the viruses","meaning":"抑制病毒","examples":[{"en":"Scientists may try to inhibit the viruses that attack microbes.","zh":"科學家可能嘗試抑制攻擊微生物的病毒。"},{"en":"Inhibit the viruses means slow down, block, or reduce the activity of viruses.","zh":"inhibit the viruses 指減慢、阻擋或降低病毒活動。"},{"en":"Medicine can sometimes inhibit viruses by stopping them from multiplying.","zh":"藥物有時可以透過阻止病毒繁殖來抑制病毒。"},{"en":"If researchers inhibit viruses that kill useful bacteria, more bacteria may survive.","zh":"如果研究人員抑制殺死有用細菌的病毒，更多細菌可能存活。"},{"en":"The phrase describes limiting viral action.","zh":"這個片語描述限制病毒作用。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":16},{"front":"make the bacteria resistant","meaning":"令細菌具抵抗力","examples":[{"en":"Scientists may try to make the bacteria resistant to viruses.","zh":"科學家可能嘗試令細菌對病毒具抵抗力。"},{"en":"Make the bacteria resistant means change or select bacteria so they can survive an attack.","zh":"make the bacteria resistant 指改變或選擇細菌，使它們能在攻擊中存活。"},{"en":"Farmers may choose crops resistant to disease so fewer plants die.","zh":"農民可能選擇抗病作物，以減少植物死亡。"},{"en":"If bacteria become resistant to phages, their populations may increase.","zh":"如果細菌對噬菌體具抵抗力，其族群可能增加。"},{"en":"The phrase describes strengthening bacteria against a threat.","zh":"這個片語描述強化細菌以抵抗威脅。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":16},{"front":"capturing carbon dioxide","meaning":"捕捉二氧化碳","examples":[{"en":"More organisms could help with capturing carbon dioxide.","zh":"更多生物可以幫助捕捉二氧化碳。"},{"en":"Capturing carbon dioxide means taking in or trapping carbon dioxide so it does not remain in the air.","zh":"capturing carbon dioxide 指吸收或困住二氧化碳，使它不留在空氣中。"},{"en":"Trees help with capturing carbon dioxide as they grow.","zh":"樹木生長時幫助捕捉二氧化碳。"},{"en":"If microbes capture more carbon dioxide, they may reduce some climate pressure.","zh":"如果微生物捕捉更多二氧化碳，就可能減少部分氣候壓力。"},{"en":"The phrase focuses on removing carbon dioxide from the atmosphere or water.","zh":"這個片語集中於從大氣或水中移除二氧化碳。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":16},{"front":"the biggest impact of","meaning":"……的最大影響","examples":[{"en":"The biggest impact of Venter’s project has been on basic science.","zh":"Venter 項目的最大影響在於基礎科學。"},{"en":"The biggest impact of something is its most important effect.","zh":"the biggest impact of 指某事最重要的影響。"},{"en":"The biggest impact of online lessons may be wider access for students far from schools.","zh":"網上課堂的最大影響可能是讓遠離學校的學生更容易上課。"},{"en":"If a project’s biggest impact is on basic science, it changes knowledge before practical products.","zh":"如果項目最大影響在基礎科學，它是在實用產品出現前改變知識。"},{"en":"The phrase identifies the main consequence.","zh":"這個片語指出主要後果。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":16},{"front":"basic science","meaning":"基礎科學","examples":[{"en":"Venter’s project has had a major impact on basic science.","zh":"Venter 的項目對基礎科學有重大影響。"},{"en":"Basic science is research aimed at understanding how nature works, not immediately making products.","zh":"basic science 是旨在理解自然如何運作，而非立即製造產品的研究。"},{"en":"A biology lab studying cell division may be doing basic science.","zh":"研究細胞分裂的生物實驗室可能正在做基礎科學。"},{"en":"If basic science improves, future medicine and technology may later benefit.","zh":"如果基礎科學進步，未來醫學和科技日後可能受益。"},{"en":"The phrase focuses on fundamental knowledge.","zh":"這個片語集中於基本知識。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":16},{"front":"overturn established ideas","meaning":"推翻既有觀念","examples":[{"en":"The project overturned many established ideas about the tree of life.","zh":"該項目推翻了許多關於生命樹的既有觀念。"},{"en":"Overturn established ideas means prove that accepted beliefs may be wrong or incomplete.","zh":"overturn established ideas 指證明被接受的信念可能錯誤或不完整。"},{"en":"New medical evidence can overturn established ideas about treatment.","zh":"新醫學證據可以推翻關於治療的既有觀念。"},{"en":"If research overturns old ideas, textbooks may eventually change.","zh":"如果研究推翻舊想法，教科書最終可能改變。"},{"en":"The phrase describes a major challenge to accepted thinking.","zh":"這個片語描述對既有思維的重大挑戰。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":16},{"front":"the tree of life","meaning":"生命樹","examples":[{"en":"The discoveries changed ideas about the tree of life.","zh":"這些發現改變了關於生命樹的想法。"},{"en":"The tree of life is a model showing how living things are related through evolution.","zh":"the tree of life 是顯示生物如何透過演化互相關聯的模型。"},{"en":"Biology textbooks use the tree of life to connect animals, plants, fungi, and microbes.","zh":"生物教科書使用生命樹連接動物、植物、真菌和微生物。"},{"en":"If new genes change the tree of life, scientists must rethink evolutionary relationships.","zh":"如果新基因改變生命樹，科學家就必須重新思考演化關係。"},{"en":"The phrase is a visual metaphor for biological ancestry.","zh":"這個片語是生物祖源的視覺比喻。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":16},{"front":"protein pigment","meaning":"蛋白質色素","examples":[{"en":"A protein pigment in human eyes enables us to detect light.","zh":"人眼中的蛋白質色素使我們能感知光線。"},{"en":"A protein pigment is a coloured or light-sensitive protein involved in biological sensing or function.","zh":"protein pigment 是參與生物感知或功能的有色或感光蛋白質。"},{"en":"Students learn that pigments in the eye help turn light into signals.","zh":"學生會學到眼睛中的色素幫助把光轉化為訊號。"},{"en":"If a protein pigment reacts to light, it may help an organism sense its environment.","zh":"如果蛋白質色素對光作出反應，它可能幫助生物感知環境。"},{"en":"The phrase connects proteins with colour or light detection.","zh":"這個片語把蛋白質與顏色或光感知連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":16},{"front":"enable someone to detect light","meaning":"使某人能夠感知光線","examples":[{"en":"The pigment enables humans to detect light.","zh":"這種色素使人類能夠感知光線。"},{"en":"Enable someone to detect light means make it possible for someone to sense light.","zh":"enable someone to detect light 指使某人能夠感知光。"},{"en":"Healthy eyes enable a child to detect light, colour, and movement.","zh":"健康眼睛使孩子能夠感知光線、顏色和動作。"},{"en":"If a pigment enables light detection, damage to it may affect vision.","zh":"如果某種色素使人能感知光線，它受損可能影響視力。"},{"en":"The phrase explains what gives a person or organism a sensing ability.","zh":"這個片語解釋甚麼賦予人或生物感知能力。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":16},{"front":"be rare","meaning":"罕見","examples":[{"en":"The protein pigment was once thought to be rare.","zh":"這種蛋白質色素曾被認為很罕見。"},{"en":"Be rare means be uncommon or found only in small numbers.","zh":"be rare 指不常見或數量很少。"},{"en":"A quiet study room is rare in a crowded school.","zh":"在擠迫學校中，安靜自修室很罕見。"},{"en":"If a gene is not rare but widespread, scientists must revise their assumptions.","zh":"如果某基因並不罕見而是分布廣泛，科學家就必須修正假設。"},{"en":"The phrase describes low frequency or limited occurrence.","zh":"這個片語描述頻率低或出現有限。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":16},{"front":"gene trawl","meaning":"基因拖網搜尋","examples":[{"en":"Venter’s gene trawl revealed surprising information about marine organisms.","zh":"Venter 的基因拖網搜尋揭示了關於海洋生物的驚人資訊。"},{"en":"A gene trawl is a large-scale search through genetic material for useful or unknown genes.","zh":"gene trawl 是在遺傳材料中進行大規模搜尋，以尋找有用或未知基因。"},{"en":"Scientists may carry out a gene trawl in soil samples to find genes for antibiotic resistance.","zh":"科學家可能在土壤樣本中進行基因拖網搜尋，以尋找抗藥性基因。"},{"en":"If a gene trawl covers many environments, it may reveal hidden biological patterns.","zh":"如果基因拖網搜尋涵蓋多種環境，就可能揭示隱藏生物模式。"},{"en":"The phrase compares genetic searching with fishing.","zh":"這個片語把基因搜尋比作捕魚。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":17},{"front":"surface marine organisms","meaning":"海面生物","examples":[{"en":"All surface marine organisms appear to make proteorhodopsins.","zh":"所有海面生物似乎都會製造變形菌視紫紅質。"},{"en":"Surface marine organisms are living things found near the ocean surface.","zh":"surface marine organisms 是生活在海洋表面附近的生物。"},{"en":"Sunlight, temperature, and waves affect surface marine organisms every day.","zh":"陽光、溫度和海浪每天都影響海面生物。"},{"en":"If surface organisms use light-sensitive proteins, sunlight may shape their biology.","zh":"如果海面生物使用感光蛋白，陽光可能塑造牠們的生物特性。"},{"en":"The phrase identifies marine life by where it lives.","zh":"這個片語按棲息位置識別海洋生命。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":17},{"front":"proteorhodopsins","meaning":"變形菌視紫紅質","examples":[{"en":"Proteorhodopsins help marine organisms detect coloured light.","zh":"變形菌視紫紅質幫助海洋生物感知有色光。"},{"en":"Proteorhodopsins are light-sensitive proteins found in many marine microbes.","zh":"proteorhodopsins 是在許多海洋微生物中發現的感光蛋白。"},{"en":"Scientists study proteorhodopsins to understand how microbes use sunlight.","zh":"科學家研究變形菌視紫紅質，以理解微生物如何使用陽光。"},{"en":"If proteorhodopsins vary by environment, they may help organisms adapt to different light conditions.","zh":"如果變形菌視紫紅質因環境而異，它們可能幫助生物適應不同光照條件。"},{"en":"The term names a specific family of microbial proteins.","zh":"這個術語指一個特定微生物蛋白家族。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":17},{"front":"detect coloured light","meaning":"感知有色光","examples":[{"en":"Proteorhodopsins detect coloured light.","zh":"變形菌視紫紅質能感知有色光。"},{"en":"Detect coloured light means sense light of different wavelengths or colours.","zh":"detect coloured light 指感知不同波長或顏色的光。"},{"en":"Human eyes detect coloured light through light-sensitive cells in the retina.","zh":"人眼透過視網膜中的感光細胞感知有色光。"},{"en":"If microbes detect coloured light, they may respond differently in blue or green water.","zh":"如果微生物感知有色光，牠們在藍色或綠色水域中可能有不同反應。"},{"en":"The phrase describes light sensing, not conscious vision.","zh":"這個片語描述光感知，而不是有意識視覺。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":17},{"front":"turn out to be","meaning":"結果是；原來是","examples":[{"en":"Proteorhodopsins turn out to be an important gene family.","zh":"變形菌視紫紅質結果是一個重要基因家族。"},{"en":"Turn out to be means be discovered to be something after more information is known.","zh":"turn out to be 指在知道更多資料後發現原來是某事物。"},{"en":"A quiet student may turn out to be an excellent public speaker.","zh":"安靜學生可能原來是出色公開演講者。"},{"en":"If a gene turns out to be widespread, scientists may change their view of its importance.","zh":"如果某基因原來分布廣泛，科學家可能改變對其重要性的看法。"},{"en":"The phrase shows a result that becomes clear later.","zh":"這個片語顯示後來才變清楚的結果。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":17},{"front":"gene families","meaning":"基因家族","examples":[{"en":"Proteorhodopsins are one of the most abundant gene families on the planet.","zh":"變形菌視紫紅質是地球上數量最多的基因家族之一。"},{"en":"Gene families are groups of related genes with similar sequences or functions.","zh":"gene families 是序列或功能相似的相關基因群組。"},{"en":"Biology students may study gene families to understand how genes evolve.","zh":"生物學生可能研究基因家族，以理解基因如何演化。"},{"en":"If a gene family is abundant, it may perform an important role in many organisms.","zh":"如果一個基因家族數量豐富，它可能在許多生物中執行重要角色。"},{"en":"The phrase organises genes into related groups.","zh":"這個片語把基因組織成相關群組。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":17},{"front":"blue and green variants","meaning":"藍色和綠色變體","examples":[{"en":"Blue and green variants are found in different environments.","zh":"藍色和綠色變體存在於不同環境中。"},{"en":"Blue and green variants are forms of something adapted to blue or green light conditions.","zh":"blue and green variants 是適應藍光或綠光條件的不同形式。"},{"en":"A plant may have variants that grow better in shade or sunlight.","zh":"植物可能有較適合陰影或陽光的變體。"},{"en":"If microbes have blue and green variants, their proteins may match the light around them.","zh":"如果微生物有藍色和綠色變體，其蛋白質可能配合周圍光線。"},{"en":"The phrase describes different forms suited to different environments.","zh":"這個片語描述適合不同環境的不同形式。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":17},{"front":"different environments","meaning":"不同環境","examples":[{"en":"Different variants are found in different environments.","zh":"不同變體存在於不同環境中。"},{"en":"Different environments are places or conditions that vary in features such as light, temperature, water, or nutrients.","zh":"different environments 是在光線、溫度、水分或營養物等特徵上不同的地方或條件。"},{"en":"Students learn differently in noisy and quiet environments.","zh":"學生在嘈吵和安靜環境中學習方式不同。"},{"en":"If organisms live in different environments, they may develop different adaptations.","zh":"如果生物生活在不同環境中，就可能發展出不同適應。"},{"en":"The phrase stresses variation in surroundings.","zh":"這個片語強調周圍條件的差異。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":17},{"front":"the open ocean","meaning":"開放海域","examples":[{"en":"Blue light is preferred in the open ocean.","zh":"在開放海域中，藍光較受偏好。"},{"en":"The open ocean is the broad sea far from coasts and shallow waters.","zh":"the open ocean 是遠離海岸和淺水區的廣闊海洋。"},{"en":"Research ships in the open ocean may be far from ports for days or weeks.","zh":"在開放海域的研究船可能數天或數星期遠離港口。"},{"en":"If blue light travels deeper in open ocean water, organisms may adapt to it.","zh":"如果藍光在開放海域中傳得更深，生物可能適應它。"},{"en":"The phrase contrasts deep offshore waters with coastal areas.","zh":"這個片語把深遠近海水域與沿岸地區作對比。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":17},{"front":"the indigo Sargasso Sea","meaning":"靛藍色的馬尾藻海","examples":[{"en":"The indigo Sargasso Sea is an example of the open ocean.","zh":"靛藍色的馬尾藻海是開放海域的一個例子。"},{"en":"The indigo Sargasso Sea means the deep blue Sargasso Sea, described by its colour.","zh":"the indigo Sargasso Sea 指以深藍顏色描述的馬尾藻海。"},{"en":"A traveller may remember the indigo sea because its colour looks unusually rich.","zh":"旅客可能記得靛藍色海洋，因為其顏色異常濃郁。"},{"en":"If blue light dominates the indigo Sargasso Sea, microbes there may favour blue-light proteins.","zh":"如果藍光主導靛藍色的馬尾藻海，那裏的微生物可能偏好藍光蛋白。"},{"en":"The phrase combines place, colour, and ocean environment.","zh":"這個片語結合地方、顏色和海洋環境。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":17},{"front":"along coasts","meaning":"沿海岸","examples":[{"en":"Green light is preferred along coasts.","zh":"沿海岸地區較偏好綠光。"},{"en":"Along coasts means near or beside the edges of land where it meets the sea.","zh":"along coasts 指靠近或位於陸地與海洋交界邊緣。"},{"en":"Many fishing villages are built along coasts.","zh":"許多漁村建於沿海岸地區。"},{"en":"If water along coasts contains more particles, different colours of light may dominate.","zh":"如果沿海岸水域含有更多微粒，不同顏色的光可能佔主導。"},{"en":"The phrase describes a location near shorelines.","zh":"這個片語描述靠近海岸線的位置。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":18},{"front":"help microbes to use energy","meaning":"幫助微生物使用能量","examples":[{"en":"Venter believes the proteins help microbes to use energy from the sun.","zh":"Venter 相信這些蛋白質幫助微生物使用來自太陽的能量。"},{"en":"Help microbes to use energy means enable tiny organisms to capture or benefit from a power source.","zh":"help microbes to use energy 指使微小生物能捕捉或利用某種能量來源。"},{"en":"Certain proteins help cells use energy stored in food.","zh":"某些蛋白質幫助細胞使用食物中儲存的能量。"},{"en":"If proteins help microbes use sunlight, microbes may survive even with few nutrients.","zh":"如果蛋白質幫助微生物使用陽光，微生物即使營養物少也可能存活。"},{"en":"The phrase connects biological tools with energy use.","zh":"這個片語把生物工具與能量使用連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":18},{"front":"energy from the sun","meaning":"來自太陽的能量","examples":[{"en":"Microbes may use energy from the sun without photosynthesis.","zh":"微生物可能不經光合作用便使用來自太陽的能量。"},{"en":"Energy from the sun means sunlight that organisms or technology can use as power.","zh":"energy from the sun 指生物或科技可用作動力的陽光。"},{"en":"Solar panels turn energy from the sun into electricity for homes.","zh":"太陽能板把來自太陽的能量轉化為家庭用電。"},{"en":"If microbes use energy from the sun, light can support life even in nutrient-poor waters.","zh":"如果微生物使用來自太陽的能量，光線就能在營養物貧乏水域支持生命。"},{"en":"The phrase refers to solar energy in simple terms.","zh":"這個片語以簡單方式指太陽能。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":18},{"front":"without photosynthesis","meaning":"不經光合作用","examples":[{"en":"Some microbes may use sunlight without photosynthesis.","zh":"有些微生物可能不經光合作用便使用陽光。"},{"en":"Without photosynthesis means without using the plant-like process that turns light, carbon dioxide, and water into food.","zh":"without photosynthesis 指不使用植物般把光、二氧化碳和水轉化為食物的過程。"},{"en":"A device can use sunlight without photosynthesis if it is a solar panel, not a plant.","zh":"如果某裝置是太陽能板而不是植物，它可不經光合作用使用陽光。"},{"en":"If microbes use light without photosynthesis, they may have a different energy system.","zh":"如果微生物不經光合作用使用光線，牠們可能有不同能源系統。"},{"en":"The phrase contrasts one light-use method with another.","zh":"這個片語把一種用光方式與另一種作對比。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":18},{"front":"light-harvesting machinery","meaning":"採光機制","examples":[{"en":"Microbes may use light-harvesting machinery to capture solar energy.","zh":"微生物可能使用採光機制捕捉太陽能。"},{"en":"Light-harvesting machinery means biological parts that capture light and turn it into usable energy.","zh":"light-harvesting machinery 指捕捉光線並把它轉化為可用能量的生物部件。"},{"en":"Plants use light-harvesting systems in leaves to capture sunlight.","zh":"植物在葉中使用採光系統捕捉陽光。"},{"en":"If microbes have light-harvesting machinery, they can benefit from sunlight in the sea.","zh":"如果微生物有採光機制，就能在海中利用陽光。"},{"en":"The phrase describes cell-level tools for using light.","zh":"這個片語描述使用光線的細胞層面工具。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":18},{"front":"pump charged atoms","meaning":"推動帶電原子","examples":[{"en":"The machinery may pump charged atoms like a solar battery.","zh":"這套機制可能像太陽能電池一樣推動帶電原子。"},{"en":"Pump charged atoms means move electrically charged particles across a membrane or system.","zh":"pump charged atoms 指把帶電粒子移過膜或系統。"},{"en":"Cells can pump charged atoms to create energy differences.","zh":"細胞可以推動帶電原子，以產生能量差。"},{"en":"If proteins pump charged atoms using light, they can help store solar energy biologically.","zh":"如果蛋白質利用光推動帶電原子，就能幫助以生物方式儲存太陽能。"},{"en":"The phrase describes a microscopic energy process.","zh":"這個片語描述微觀能源過程。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":18},{"front":"the equivalent of","meaning":"相當於……的東西","examples":[{"en":"The system works in the equivalent of solar batteries.","zh":"這個系統運作起來相當於太陽能電池。"},{"en":"The equivalent of means something that has the same value, role, or function as another thing.","zh":"the equivalent of 指在價值、角色或功能上相同的東西。"},{"en":"A school ID card can act as the equivalent of a library card.","zh":"學生證可以相當於圖書證使用。"},{"en":"If a microbial system works like the equivalent of a battery, it stores or moves energy.","zh":"如果微生物系統像相當於電池的東西一樣運作，它就是儲存或轉移能量。"},{"en":"The phrase compares function rather than exact form.","zh":"這個片語比較功能，而不是完全相同形態。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":18},{"front":"solar batteries","meaning":"太陽能電池","examples":[{"en":"Microbes may use a mechanism similar to solar batteries.","zh":"微生物可能使用類似太陽能電池的機制。"},{"en":"Solar batteries are systems that store or use energy from sunlight.","zh":"solar batteries 是儲存或使用來自陽光能量的系統。"},{"en":"A house with solar batteries can use stored solar power at night.","zh":"有太陽能電池的房屋可在夜間使用儲存的太陽能。"},{"en":"If microbes act like tiny solar batteries, sunlight may power some of their activities.","zh":"如果微生物像微型太陽能電池，陽光可能為牠們一些活動供能。"},{"en":"The phrase links solar energy with energy storage or use.","zh":"這個片語把太陽能與能量儲存或使用連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":18},{"front":"protect microbes from","meaning":"保護微生物免受……","examples":[{"en":"The team found proteins that protect microbes from UV rays.","zh":"團隊發現保護微生物免受紫外線傷害的蛋白質。"},{"en":"Protect microbes from means shield tiny organisms against harm or damage.","zh":"protect microbes from 指保護微小生物免受傷害或損害。"},{"en":"Sunscreen protects skin from strong sunlight.","zh":"防曬霜保護皮膚免受強烈陽光傷害。"},{"en":"If proteins protect microbes from UV rays, microbes can survive nearer the ocean surface.","zh":"如果蛋白質保護微生物免受紫外線傷害，微生物就能在海洋表面附近存活。"},{"en":"The phrase shows defence against a specific danger.","zh":"這個片語顯示對特定危險的防禦。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":18},{"front":"UV rays","meaning":"紫外線","examples":[{"en":"Some proteins protect microbes from UV rays.","zh":"有些蛋白質保護微生物免受紫外線傷害。"},{"en":"UV rays are ultraviolet rays from sunlight that can damage cells and DNA.","zh":"UV rays 是來自陽光、可損害細胞和 DNA 的紫外線。"},{"en":"People wear sunglasses and sunscreen to reduce harm from UV rays.","zh":"人們戴太陽眼鏡和塗防曬霜，以減少紫外線傷害。"},{"en":"If microbes live near the surface, UV rays can be a serious threat.","zh":"如果微生物生活在表面附近，紫外線可能是嚴重威脅。"},{"en":"The phrase refers to invisible light with biological effects.","zh":"這個片語指具有生物影響的不可見光。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":18},{"front":"be involved in","meaning":"參與","examples":[{"en":"Some proteins are involved in repairing UV damage.","zh":"有些蛋白質參與修復紫外線損害。"},{"en":"Be involved in means take part in or have a role in a process.","zh":"be involved in 指參與某過程或在其中有角色。"},{"en":"A school counsellor is involved in helping students manage stress.","zh":"學校輔導員參與幫助學生管理壓力。"},{"en":"If a protein is involved in repair, damage may be fixed more efficiently.","zh":"如果蛋白質參與修復，損害可能更有效地被修復。"},{"en":"The phrase identifies participation or function.","zh":"這個片語指出參與或功能。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":19},{"front":"repair the damage caused by","meaning":"修復由……造成的損害","examples":[{"en":"Some proteins repair the damage caused by UV rays.","zh":"有些蛋白質修復由紫外線造成的損害。"},{"en":"Repair the damage caused by means fix harm resulting from a particular cause.","zh":"repair the damage caused by 指修復由某原因造成的傷害。"},{"en":"After a storm, workers repair the damage caused by fallen trees.","zh":"風暴後，工人修復由倒塌樹木造成的損害。"},{"en":"If cells repair UV damage quickly, organisms can survive stronger sunlight.","zh":"如果細胞迅速修復紫外線損害，生物就能在較強陽光下存活。"},{"en":"The phrase connects harm, cause, and recovery.","zh":"這個片語把傷害、原因和復原連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":19},{"front":"be specific to","meaning":"只屬於……","examples":[{"en":"Some proteins were thought to be specific to one kingdom of life.","zh":"有些蛋白質曾被認為只屬於一個生命界。"},{"en":"Be specific to means belong only to or be found only in a particular group, place, or situation.","zh":"be specific to 指只屬於或只存在於某特定群體、地方或情況。"},{"en":"A school rule may be specific to senior students, not the whole school.","zh":"某校規可能只屬於高年級學生，而不是全校。"},{"en":"If a protein is not specific to one group, it may be more widespread than scientists thought.","zh":"如果蛋白質並非只屬於某一群體，它可能比分科學家所想更廣泛。"},{"en":"The phrase describes limited association.","zh":"這個片語描述有限關聯。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":19},{"front":"one kingdom of life","meaning":"一個生命界","examples":[{"en":"Some proteins were thought to belong to one kingdom of life.","zh":"有些蛋白質曾被認為屬於一個生命界。"},{"en":"One kingdom of life means one major biological category, such as animals, plants, fungi, or bacteria.","zh":"one kingdom of life 指一個主要生物分類，例如動物、植物、真菌或細菌。"},{"en":"Biology students learn that living things can be grouped into different kingdoms of life.","zh":"生物學生會學到生物可被分成不同生命界。"},{"en":"If a protein appears in more than one kingdom, it may have an ancient or shared role.","zh":"如果蛋白質出現在不止一個生命界，它可能有古老或共同角色。"},{"en":"The phrase refers to broad biological classification.","zh":"這個片語指廣泛生物分類。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":19},{"front":"more widespread","meaning":"分布更廣泛","examples":[{"en":"Many proteins turned out to be more widespread than expected.","zh":"許多蛋白質結果比分預期分布更廣泛。"},{"en":"More widespread means found in more places or groups than people thought.","zh":"more widespread 指比人們以為的更常出現在更多地方或群體中。"},{"en":"Online payment has become more widespread in small shops than before.","zh":"網上付款在小店中已比以前分布更廣泛。"},{"en":"If a gene is more widespread, it may be more important than earlier research suggested.","zh":"如果某基因分布更廣泛，它可能比早期研究所指更重要。"},{"en":"The phrase describes broader distribution.","zh":"這個片語描述更廣的分布。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":19},{"front":"this is only the start","meaning":"這只是開始","examples":[{"en":"Venter says this is only the start of understanding microbes.","zh":"Venter 說這只是理解微生物的開始。"},{"en":"This is only the start means much more work, discovery, or development is still to come.","zh":"this is only the start 指仍有更多工作、發現或發展將會出現。"},{"en":"A first grammar lesson is only the start of learning a language.","zh":"第一堂文法課只是學習語言的開始。"},{"en":"If one expedition finds many genes, it may still be only the start of understanding ocean life.","zh":"如果一次考察發現許多基因，它仍可能只是理解海洋生命的開始。"},{"en":"The phrase suggests early progress, not completion.","zh":"這個片語暗示初步進展，而不是完成。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":19},{"front":"scratch the surface of","meaning":"只觸及……的表面","examples":[{"en":"Scientists have only begun to scratch the surface of the microbial world.","zh":"科學家才剛開始觸及微生物世界的表面。"},{"en":"Scratch the surface of means understand only a small part of a much larger subject.","zh":"scratch the surface of 指只理解一個更大主題中的小部分。"},{"en":"A one-day visit can only scratch the surface of a city’s history.","zh":"一日遊只能觸及一座城市歷史的表面。"},{"en":"If researchers only scratch the surface, many deeper questions remain unanswered.","zh":"如果研究人員只觸及表面，許多更深問題仍未回答。"},{"en":"The phrase suggests early and limited understanding.","zh":"這個片語暗示早期且有限的理解。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":19},{"front":"the microbial world","meaning":"微生物世界","examples":[{"en":"The microbial world remains only partly understood.","zh":"微生物世界仍然只被部分理解。"},{"en":"The microbial world means the vast world of microbes and their roles in nature.","zh":"the microbial world 指微生物及其在自然中角色所構成的廣闊世界。"},{"en":"The microbial world exists in oceans, soil, food, hospitals, and human bodies.","zh":"微生物世界存在於海洋、泥土、食物、醫院和人體中。"},{"en":"If we understand the microbial world better, we may improve medicine, farming, and climate science.","zh":"如果我們更好理解微生物世界，就可能改善醫學、農業和氣候科學。"},{"en":"The phrase refers to tiny life forms as a whole system.","zh":"這個片語把微小生命形式視為一整套系統。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":19},{"front":"which paragraph does each heading best fit","meaning":"每個標題最適合哪一段","examples":[{"en":"Students must decide which paragraph each heading best fits.","zh":"學生必須判斷每個標題最適合哪一段。"},{"en":"Which paragraph does each heading best fit asks students to match headings with the most suitable paragraph.","zh":"which paragraph does each heading best fit 要求學生把標題配對到最合適段落。"},{"en":"In a reading test, students skim each paragraph before choosing the best heading.","zh":"在閱讀測驗中，學生在選最佳標題前會略讀每段。"},{"en":"If two headings seem similar, students must identify the paragraph’s main idea carefully.","zh":"如果兩個標題看似相似，學生必須仔細識別段落主旨。"},{"en":"The phrase describes a common IELTS reading task.","zh":"這個片語描述常見 IELTS 閱讀題型。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":19},{"front":"how to save the world","meaning":"如何拯救世界","examples":[{"en":"The heading asks whether microbes could help save the world.","zh":"該標題問微生物是否可以幫助拯救世界。"},{"en":"How to save the world means how to protect humanity or the planet from serious danger.","zh":"how to save the world 指如何保護人類或地球免受嚴重危險。"},{"en":"A documentary about clean energy may ask how to save the world from climate change.","zh":"關於清潔能源的紀錄片可能詢問如何拯救世界免受氣候變化影響。"},{"en":"If microbes help absorb carbon, they may become part of a plan to protect the planet.","zh":"如果微生物幫助吸收碳，它們可能成為保護地球計劃的一部分。"},{"en":"The phrase is broad and dramatic, often used for major global problems.","zh":"這個片語範圍廣且戲劇化，常用於重大全球問題。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":19},{"front":"contradict conventional ideas","meaning":"與傳統觀念相矛盾","examples":[{"en":"Venter’s research contradicts conventional ideas about marine life.","zh":"Venter 的研究與關於海洋生命的傳統觀念相矛盾。"},{"en":"Contradict conventional ideas means show that common accepted beliefs may be wrong.","zh":"contradict conventional ideas 指顯示普遍接受的信念可能錯誤。"},{"en":"A new teaching method may contradict conventional ideas about how children learn grammar.","zh":"新教學方法可能與孩子如何學文法的傳統觀念相矛盾。"},{"en":"If evidence contradicts conventional ideas, experts may need to revise textbooks.","zh":"如果證據與傳統觀念相矛盾，專家可能需要修訂教科書。"},{"en":"The phrase describes a challenge to mainstream thinking.","zh":"這個片語描述對主流思維的挑戰。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":20},{"front":"conventional ideas","meaning":"傳統觀念","examples":[{"en":"The project challenged conventional ideas about the tree of life.","zh":"該項目挑戰了關於生命樹的傳統觀念。"},{"en":"Conventional ideas are widely accepted beliefs or ways of thinking.","zh":"conventional ideas 是被廣泛接受的信念或思考方式。"},{"en":"Conventional ideas about success often focus on money and status.","zh":"關於成功的傳統觀念常集中於金錢和地位。"},{"en":"If new evidence appears, conventional ideas may become outdated.","zh":"如果新證據出現，傳統觀念可能變得過時。"},{"en":"The phrase refers to normal mainstream assumptions.","zh":"這個片語指正常主流假設。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":20},{"front":"genome race winner","meaning":"基因組競賽勝出者","examples":[{"en":"Venter was involved in a race to identify the human genome.","zh":"Venter 參與了一場識別人類基因組的競賽。"},{"en":"A genome race winner is someone who succeeds in a competition to decode genetic information first.","zh":"genome race winner 指在率先解碼遺傳資訊的競賽中成功的人。"},{"en":"Newspapers may call a scientist a race winner if their team reaches a discovery before others.","zh":"如果科學家團隊比其他人更早達成發現，報紙可能稱他為競賽勝出者。"},{"en":"If a genome race has a winner, it means several groups were competing toward the same goal.","zh":"如果基因組競賽有勝出者，就表示幾個團隊競逐同一目標。"},{"en":"The phrase connects scientific discovery with competition.","zh":"這個片語把科學發現與競爭連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":20},{"front":"the importance of microbes","meaning":"微生物的重要性","examples":[{"en":"The passage explains the importance of microbes to ecosystems.","zh":"文章解釋微生物對生態系統的重要性。"},{"en":"The importance of microbes means why tiny organisms matter in life, health, climate, or ecosystems.","zh":"the importance of microbes 指微小生物在生命、健康、氣候或生態系統中為何重要。"},{"en":"Doctors teach the importance of microbes when explaining infections and digestion.","zh":"醫生解釋感染和消化時會教授微生物的重要性。"},{"en":"If microbes help recycle nutrients, their importance is much greater than their size suggests.","zh":"如果微生物幫助循環營養，牠們的重要性就遠大於體型所暗示。"},{"en":"The phrase focuses on the value and role of tiny life forms.","zh":"這個片語集中於微小生命形式的價值和角色。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":20},{"front":"according to the text","meaning":"根據文章","examples":[{"en":"According to the text, microbes may help slow global warming.","zh":"根據文章，微生物可能有助減慢全球暖化。"},{"en":"According to the text means based on what the passage says, not outside knowledge.","zh":"according to the text 指根據文章所說，而不是外部知識。"},{"en":"According to the text, students should choose answers supported by the passage.","zh":"根據文章，學生應選擇由文章支持的答案。"},{"en":"If an idea is not mentioned in the text, students should not treat it as stated.","zh":"如果某想法文章沒有提及，學生不應把它當成已陳述。"},{"en":"The phrase reminds learners to rely on the reading passage.","zh":"這個片語提醒學習者依賴閱讀文章。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":20},{"front":"the following statements are true","meaning":"以下陳述屬實","examples":[{"en":"Students must identify which of the following statements are true.","zh":"學生必須辨認以下哪些陳述屬實。"},{"en":"The following statements are true means the listed sentences are correct if supported by the text.","zh":"the following statements are true 指所列句子如獲文本支持，就是正確。"},{"en":"In a reading exercise, students check which following statements are true before writing letters.","zh":"在閱讀練習中，學生在寫字母前檢查以下哪些陳述屬實。"},{"en":"If a statement sounds logical but is not supported, it may not be true according to the passage.","zh":"如果陳述聽起來合理但沒有支持，根據文章它未必屬實。"},{"en":"The phrase introduces a selection task.","zh":"這個片語引出選擇任務。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":20},{"front":"corresponding letters","meaning":"相應字母","examples":[{"en":"Students write the corresponding letters in the answer boxes.","zh":"學生在答案框中寫上相應字母。"},{"en":"Corresponding letters are the option letters that match the chosen answers.","zh":"corresponding letters 是與所選答案相符的選項字母。"},{"en":"In a multiple-choice task, students may write corresponding letters such as A, C, and D.","zh":"在多項選擇題中，學生可能寫上 A、C 和 D 等相應字母。"},{"en":"If students understand the answer but write the wrong letter, they may lose the mark.","zh":"如果學生理解答案但寫錯字母，可能失分。"},{"en":"The phrase refers to answer format.","zh":"這個片語指答案格式。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":20},{"front":"in any order","meaning":"以任何次序","examples":[{"en":"The letters may be written in any order.","zh":"字母可以以任何次序書寫。"},{"en":"In any order means the sequence does not matter.","zh":"in any order 指次序不重要。"},{"en":"If three tasks must be finished in any order, students can start with the easiest one.","zh":"如果三項任務可以以任何次序完成，學生可以先做最容易的一項。"},{"en":"When answers are accepted in any order, the focus is on correctness, not sequence.","zh":"當答案可按任何次序接受時，重點是正確性，而不是排列。"},{"en":"The phrase removes the need to arrange items.","zh":"這個片語取消排列項目的需要。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":20},{"front":"unconventional scientist","meaning":"非傳統的科學家","examples":[{"en":"Craig Venter is an unconventional scientist.","zh":"Craig Venter 是一位非傳統的科學家。"},{"en":"An unconventional scientist is a scientist who uses unusual methods or challenges accepted practice.","zh":"unconventional scientist 指使用不尋常方法或挑戰既有做法的科學家。"},{"en":"An unconventional scientist may work outside universities and still make major discoveries.","zh":"非傳統的科學家可能在大學以外工作，仍作出重大發現。"},{"en":"If an unconventional scientist succeeds, others may reconsider old research habits.","zh":"如果非傳統科學家成功，其他人可能重新思考舊研究習慣。"},{"en":"The phrase suggests originality and possible controversy.","zh":"這個片語暗示原創性和可能的爭議。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":20},{"front":"scientific qualifications","meaning":"科學資歷","examples":[{"en":"The option refers to Venter’s scientific qualifications.","zh":"該選項提到 Venter 的科學資歷。"},{"en":"Scientific qualifications are formal training, degrees, or recognised expertise in science.","zh":"scientific qualifications 指科學方面的正式訓練、學位或公認專業知識。"},{"en":"A laboratory may require scientific qualifications before hiring a researcher.","zh":"實驗室可能在聘請研究員前要求科學資歷。"},{"en":"If someone lacks formal qualifications but has strong results, debate may arise.","zh":"如果某人缺乏正式資歷但成果強勁，就可能引起討論。"},{"en":"The phrase concerns credentials, not personality.","zh":"這個片語關乎資格，而不是性格。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":20},{"front":"sea creatures","meaning":"海洋生物","examples":[{"en":"Carbon is used to make shells for sea creatures.","zh":"碳被用來為海洋生物製造外殼。"},{"en":"Sea creatures are animals and other living things that live in the sea.","zh":"sea creatures 是生活在海中的動物和其他生物。"},{"en":"Children may see sea creatures such as crabs, fish, and starfish in a rock pool.","zh":"孩子可能在潮池中看到螃蟹、魚和海星等海洋生物。"},{"en":"If sea creatures cannot build shells, marine food chains may be affected.","zh":"如果海洋生物不能建造外殼，海洋食物鏈可能受影響。"},{"en":"The phrase is broad and easy for learners to use.","zh":"這個片語範圍廣，學習者容易使用。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":21},{"front":"not rich in life","meaning":"生命不豐富","examples":[{"en":"The Sargasso Sea was thought of as not rich in life.","zh":"馬尾藻海曾被認為生命不豐富。"},{"en":"Not rich in life means having few living organisms or low biological diversity.","zh":"not rich in life 指生物數量少或生物多樣性低。"},{"en":"A dry, polluted pond may be not rich in life compared with a healthy wetland.","zh":"與健康濕地相比，乾涸受污染池塘可能生命不豐富。"},{"en":"If a place thought not rich in life contains many microbes, the assumption is wrong.","zh":"如果被認為生命不豐富的地方含有許多微生物，該假設就是錯的。"},{"en":"The phrase describes apparent biological poverty.","zh":"這個片語描述表面上的生物貧乏。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":21},{"front":"scientifically useless","meaning":"在科學上無用","examples":[{"en":"The option says the genes are scientifically useless.","zh":"該選項說這些基因在科學上無用。"},{"en":"Scientifically useless means having no value for scientific knowledge or research.","zh":"scientifically useless 指對科學知識或研究沒有價值。"},{"en":"A badly labelled sample may become scientifically useless if no one knows where it came from.","zh":"如果沒有人知道樣本來自哪裡，標籤錯誤的樣本可能在科學上無用。"},{"en":"If genes reveal new functions, they are clearly not scientifically useless.","zh":"如果基因揭示新功能，它們顯然並非在科學上無用。"},{"en":"The phrase is a strong negative judgement about research value.","zh":"這個片語是對研究價值的強烈負面判斷。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":21},{"front":"resistant to viruses","meaning":"對病毒有抵抗力","examples":[{"en":"Venter wants to make bacteria resistant to viruses.","zh":"Venter 希望令細菌對病毒有抵抗力。"},{"en":"Resistant to viruses means able to survive or avoid infection by viruses.","zh":"resistant to viruses 指能抵抗病毒感染或在病毒攻擊中存活。"},{"en":"Some crop varieties are resistant to disease and need less chemical treatment.","zh":"有些作物品種對疾病有抵抗力，需要較少化學處理。"},{"en":"If bacteria become resistant to viruses, they may survive longer and grow in number.","zh":"如果細菌對病毒有抵抗力，就可能存活更久並增加數量。"},{"en":"The phrase describes protection against viral attack.","zh":"這個片語描述對病毒攻擊的保護。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":21},{"front":"use sunlight as energy","meaning":"利用陽光作為能量","examples":[{"en":"Microbes may use sunlight as energy.","zh":"微生物可能利用陽光作為能量。"},{"en":"Use sunlight as energy means capture light from the sun and use it to power biological activity.","zh":"use sunlight as energy 指捕捉太陽光並用它推動生物活動。"},{"en":"Plants use sunlight as energy when they grow leaves and roots.","zh":"植物長出葉和根時會利用陽光作為能量。"},{"en":"If microbes use sunlight as energy, they may survive in places with few nutrients.","zh":"如果微生物利用陽光作為能量，就可能在營養物少的地方存活。"},{"en":"The phrase links light with life processes.","zh":"這個片語把光線與生命過程連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":21},{"front":"protect microbes from too much sunlight","meaning":"保護微生物免受過量陽光傷害","examples":[{"en":"Some proteins protect microbes from too much sunlight.","zh":"有些蛋白質保護微生物免受過量陽光傷害。"},{"en":"Protect microbes from too much sunlight means shield tiny organisms from harmful excess light or UV radiation.","zh":"protect microbes from too much sunlight 指保護微小生物免受過強光線或紫外線傷害。"},{"en":"A hat protects a child from too much sunlight during outdoor sports.","zh":"帽子在戶外運動時保護孩子免受過量陽光傷害。"},{"en":"If proteins protect microbes from sunlight damage, surface microbes may survive better.","zh":"如果蛋白質保護微生物免受陽光損害，表層微生物可能更容易存活。"},{"en":"The phrase describes defence against excessive light exposure.","zh":"這個片語描述對過量光照的防禦。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":21},{"front":"according to the information given","meaning":"根據所提供的資料","examples":[{"en":"Students must answer according to the information given in the passage.","zh":"學生必須根據文章中所提供的資料作答。"},{"en":"According to the information given means based only on the details provided.","zh":"according to the information given 指只根據所提供的細節。"},{"en":"In an exam, students should answer according to the information given, not personal opinion.","zh":"在考試中，學生應根據所提供的資料作答，而不是個人意見。"},{"en":"If the text does not mention a fact, it cannot be assumed from outside knowledge.","zh":"如果文本沒有提及某事實，就不能從外部知識假設。"},{"en":"The phrase reminds students to stay within the source.","zh":"這個片語提醒學生留在來源範圍內。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":21},{"front":"choose the correct answer or answers","meaning":"選出正確答案","examples":[{"en":"The question asks students to choose the correct answer or answers.","zh":"題目要求學生選出正確答案。"},{"en":"Choose the correct answer or answers means select one or more options that match the passage.","zh":"choose the correct answer or answers 指選出一個或多個符合文章的選項。"},{"en":"In some reading tasks, students may need more than one correct letter.","zh":"在一些閱讀題中，學生可能需要多於一個正確字母。"},{"en":"If the instruction says answer or answers, students should check whether multiple choices are possible.","zh":"如果指示說 answer or answers，學生應檢查是否可能有多個選項。"},{"en":"The phrase gives exam format guidance.","zh":"這個片語提供考試格式指引。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":21},{"front":"genetic code","meaning":"基因密碼","examples":[{"en":"Venter became the first person to read his own genetic code.","zh":"Venter 成為第一個讀取自己基因密碼的人。"},{"en":"Genetic code means the DNA information that carries biological instructions.","zh":"genetic code 指攜帶生物指令的 DNA 資訊。"},{"en":"Doctors may study a person’s genetic code to understand inherited disease risk.","zh":"醫生可能研究一個人的基因密碼，以了解遺傳疾病風險。"},{"en":"If a genetic code contains a mutation, it may affect how a protein is made.","zh":"如果基因密碼包含突變，可能影響蛋白質如何製造。"},{"en":"The phrase is often used to describe an organism’s genetic information.","zh":"這個片語常用來描述生物體的遺傳資訊。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":21},{"front":"own a floating laboratory","meaning":"擁有一個浮動實驗室","examples":[{"en":"Craig Venter owns a floating laboratory.","zh":"Craig Venter 擁有一個浮動實驗室。"},{"en":"Own a floating laboratory means possess a boat or vessel equipped for scientific research.","zh":"own a floating laboratory 指擁有一艘配備科學研究設備的船隻。"},{"en":"A university may own a floating laboratory for studying lakes and coastal waters.","zh":"大學可能擁有一個浮動實驗室，用來研究湖泊和沿岸水域。"},{"en":"If a scientist owns a floating laboratory, they can collect samples directly from the sea.","zh":"如果科學家擁有浮動實驗室，就能直接從海上採集樣本。"},{"en":"The phrase combines ownership with mobile scientific work.","zh":"這個片語結合擁有權和流動科學工作。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":21},{"front":"disagree with Darwin’s theory of evolution","meaning":"不同意達爾文的演化論","examples":[{"en":"The option suggests that Venter disagrees with Darwin’s theory of evolution.","zh":"該選項暗示 Venter 不同意達爾文的演化論。"},{"en":"Disagree with Darwin’s theory of evolution means reject or oppose Darwin’s explanation of how species change over time.","zh":"disagree with Darwin’s theory of evolution 指拒絕或反對達爾文關於物種如何隨時間改變的解釋。"},{"en":"A student may misunderstand an article and think a scientist disagrees with evolution when they only use a new method.","zh":"學生可能誤解文章，以為科學家不同意演化論，其實只是使用新方法。"},{"en":"If a passage compares Venter with Darwin, it does not automatically mean disagreement.","zh":"如果文章把 Venter 與達爾文比較，並不自動表示不同意。"},{"en":"The phrase describes opposition to a major biological theory.","zh":"這個片語描述對重要生物理論的反對。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":22},{"front":"take place in","meaning":"在……進行","examples":[{"en":"The pilot project took place in the Sargasso Sea.","zh":"試驗性項目在馬尾藻海進行。"},{"en":"Take place in means happen or occur in a particular location or setting.","zh":"take place in 指在某特定地方或場景發生。"},{"en":"The school concert will take place in the main hall.","zh":"學校音樂會將在禮堂進行。"},{"en":"If a project takes place in one sea, its results may need testing elsewhere.","zh":"如果項目在某一海域進行，其結果可能需要在其他地方測試。"},{"en":"The phrase identifies where an event happens.","zh":"這個片語指出事件發生的地點。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":22},{"front":"end at","meaning":"在……結束","examples":[{"en":"The option says the pilot project ended at the Galapagos Islands.","zh":"該選項說試驗性項目在加拉帕戈斯群島結束。"},{"en":"End at means finish at a particular place, point, or time.","zh":"end at 指在某個地方、位置或時間結束。"},{"en":"The bus route ends at the railway station.","zh":"巴士路線在火車站結束。"},{"en":"If a voyage ends at an island, the final samples may come from that region.","zh":"如果航程在某島結束，最後樣本可能來自該區域。"},{"en":"The phrase marks the finishing point.","zh":"這個片語標記終點。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":22},{"front":"give someone the idea of","meaning":"使某人想到……","examples":[{"en":"The option suggests the project gave him the idea of writing an autobiography.","zh":"該選項暗示這個項目使他想到寫自傳。"},{"en":"Give someone the idea of means make someone think of doing something.","zh":"give someone the idea of 指令某人想到做某事。"},{"en":"A school trip may give a student the idea of studying history.","zh":"學校旅行可能使學生想到讀歷史。"},{"en":"If a voyage gives a scientist the idea of writing, personal experience becomes part of the project.","zh":"如果航行使科學家想到寫作，個人經歷就成為項目的一部分。"},{"en":"The phrase links an experience with a new thought or plan.","zh":"這個片語把經歷與新想法或計劃連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":22},{"front":"owned by Venter","meaning":"由 Venter 擁有","examples":[{"en":"Synthetic Genomics is a company owned by Venter.","zh":"Synthetic Genomics 是一間由 Venter 擁有的公司。"},{"en":"Owned by Venter means legally possessed or controlled by Venter.","zh":"owned by Venter 指在法律上由 Venter 擁有或控制。"},{"en":"A café owned by a teacher may also be used for small English workshops.","zh":"由老師擁有的咖啡店也可能用作小型英語工作坊。"},{"en":"If a company is owned by a scientist, research and business interests may overlap.","zh":"如果公司由科學家擁有，研究和商業利益可能重疊。"},{"en":"The phrase identifies ownership.","zh":"這個片語指出擁有權。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":22},{"front":"hope to","meaning":"希望","examples":[{"en":"Synthetic Genomics hopes to use microbes to make fuel.","zh":"Synthetic Genomics 希望使用微生物製造燃料。"},{"en":"Hope to means want and expect to do something in the future.","zh":"hope to 指想並期望未來做某事。"},{"en":"A student may hope to improve pronunciation before an interview.","zh":"學生可能希望在面試前改善發音。"},{"en":"If a company hopes to make fuel from microbes, it still needs proof and technology.","zh":"如果公司希望用微生物製造燃料，仍需要證據和科技。"},{"en":"The phrase expresses intention with uncertainty.","zh":"這個片語表達有不確定性的意圖。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":22},{"front":"make fuel from carbon dioxide","meaning":"由二氧化碳製造燃料","examples":[{"en":"The company hopes to make fuel from carbon dioxide.","zh":"該公司希望由二氧化碳製造燃料。"},{"en":"Make fuel from carbon dioxide means convert carbon dioxide into a usable energy source.","zh":"make fuel from carbon dioxide 指把二氧化碳轉化為可用能源來源。"},{"en":"Scientists may try to make fuel from waste gases instead of extracting more oil.","zh":"科學家可能嘗試由廢氣製造燃料，而不是開採更多石油。"},{"en":"If fuel can be made from carbon dioxide, pollution may become a useful input.","zh":"如果燃料可以由二氧化碳製造，污染物可能變成有用投入。"},{"en":"The phrase describes turning a greenhouse gas into energy material.","zh":"這個片語描述把溫室氣體變成能源材料。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":22},{"front":"produce hydrogen","meaning":"生產氫氣","examples":[{"en":"Hydrogen production is one target of the company.","zh":"氫氣生產是該公司的其中一個目標。"},{"en":"Produce hydrogen means make hydrogen gas for fuel, industry, or research.","zh":"produce hydrogen 指為燃料、工業或研究製造氫氣。"},{"en":"A laboratory may produce hydrogen during a chemistry experiment.","zh":"實驗室可能在化學實驗中生產氫氣。"},{"en":"If microbes can produce hydrogen cleanly, they may help create future fuels.","zh":"如果微生物能清潔地生產氫氣，就可能幫助創造未來燃料。"},{"en":"The phrase focuses on making a specific gas.","zh":"這個片語集中於製造一種特定氣體。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":22},{"front":"discover more species of microbe","meaning":"發現更多微生物物種","examples":[{"en":"The option suggests that the company hopes to discover more species of microbe.","zh":"該選項暗示該公司希望發現更多微生物物種。"},{"en":"Discover more species of microbe means find additional kinds of tiny organisms not previously known.","zh":"discover more species of microbe 指發現更多以前未知的微小生物種類。"},{"en":"Scientists may discover more species of microbe by studying soil from different forests.","zh":"科學家可能透過研究不同森林的泥土來發現更多微生物物種。"},{"en":"If researchers discover more microbes, they may also discover useful genes.","zh":"如果研究人員發現更多微生物，就可能也發現有用基因。"},{"en":"The phrase focuses on expanding known biological diversity.","zh":"這個片語集中於擴大已知生物多樣性。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":22},{"front":"before Venter’s study","meaning":"在 Venter 的研究之前","examples":[{"en":"Before Venter’s study, scientists had different ideas about microbes.","zh":"在 Venter 的研究之前，科學家對微生物有不同想法。"},{"en":"Before Venter’s study means during the period before his research changed the discussion.","zh":"before Venter’s study 指在他的研究改變討論之前的時期。"},{"en":"Before a new school policy, teachers may have different ways of marking homework.","zh":"在新校政之前，老師可能有不同批改功課方式。"},{"en":"If ideas were different before a study, the study may have shifted scientific understanding.","zh":"如果研究之前想法不同，該研究可能已改變科學理解。"},{"en":"The phrase marks a contrast between earlier and later knowledge.","zh":"這個片語標示早期和後來知識之間的對比。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":22},{"front":"nutrient levels depended on","meaning":"營養物水平取決於……","examples":[{"en":"The option suggests that nutrient levels depended on carbon-hungry organisms.","zh":"該選項暗示營養物水平取決於渴求碳的生物。"},{"en":"Nutrient levels depended on means the amount of nutrients was controlled or influenced by something.","zh":"nutrient levels depended on 指營養物數量由某事控制或影響。"},{"en":"In a garden, plant growth may depend on soil nutrient levels.","zh":"在花園中，植物生長可能取決於泥土營養物水平。"},{"en":"If microbe populations do not depend mainly on nutrients, another factor must explain them.","zh":"如果微生物種群並非主要取決於營養物，就必須有另一因素解釋。"},{"en":"The phrase links one variable with another.","zh":"這個片語把一個變項與另一個連接起來。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":23},{"front":"organisms that eat carbon","meaning":"吸收碳的生物","examples":[{"en":"Some organisms absorb carbon from the atmosphere.","zh":"有些生物從大氣中吸收碳。"},{"en":"Organisms that eat carbon are living things that take in carbon compounds or carbon dioxide for growth or energy.","zh":"organisms that eat carbon 指吸收碳化合物或二氧化碳以生長或獲取能量的生物。"},{"en":"Plants can be thought of as organisms that use carbon when they grow from carbon dioxide.","zh":"植物從二氧化碳中生長時，可被簡化理解為使用碳的生物。"},{"en":"If organisms that eat carbon increase, more carbon may be removed from air or water.","zh":"如果吸收碳的生物增加，更多碳可能從空氣或水中被移除。"},{"en":"The phrase is a simplified way to describe carbon-absorbing life.","zh":"這個片語是描述吸碳生命的簡化說法。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":23},{"front":"keep microbe levels under control","meaning":"控制微生物數量","examples":[{"en":"Viruses may keep microbe levels under control.","zh":"病毒可能控制微生物數量。"},{"en":"Keep microbe levels under control means prevent microbe populations from growing too large.","zh":"keep microbe levels under control 指防止微生物族群增長過多。"},{"en":"Cleaning kitchens properly helps keep harmful microbe levels under control.","zh":"妥善清潔廚房有助控制有害微生物數量。"},{"en":"If viruses keep microbes under control in the ocean, they affect the balance of marine ecosystems.","zh":"如果病毒在海洋中控制微生物數量，它們就影響海洋生態系統平衡。"},{"en":"The phrase describes regulation of population size.","zh":"這個片語描述對族群大小的調節。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":23},{"front":"be responsible for climate change","meaning":"對氣候變化負責","examples":[{"en":"The option suggests that bacteria might be responsible for climate change.","zh":"該選項暗示細菌可能對氣候變化負責。"},{"en":"Be responsible for climate change means be a cause of long-term changes in the climate system.","zh":"be responsible for climate change 指成為氣候系統長期變化的原因。"},{"en":"Burning fossil fuels is widely discussed as being responsible for much modern climate change.","zh":"燃燒化石燃料被廣泛討論為現代氣候變化的重要原因。"},{"en":"If bacteria affected carbon cycles strongly, scientists might ask whether they influence climate change.","zh":"如果細菌強烈影響碳循環，科學家可能會問牠們是否影響氣候變化。"},{"en":"The phrase identifies a possible cause of climate change.","zh":"這個片語指出氣候變化的可能原因。"}],"source":"95 - Looking for Life on the Ocean Wave.pdf","sourcePage":23}],"ielts/reading/passage-2/Practice 96":[{"front":"No Growing Pains","meaning":"沒有成長陣痛；成長順利","examples":[{"en":"The article suggests that Daniel Radcliffe has had no growing pains as a young star.","zh":"文章暗示 Daniel Radcliffe 作為年輕明星，成長過程沒有成長陣痛。"},{"en":"No growing pains means someone develops smoothly without serious trouble during a difficult stage.","zh":"「No growing pains」意思是某人在困難成長階段中發展順利，沒有嚴重麻煩。"},{"en":"A new student may have no growing pains if classmates welcome him and teachers support him early.","zh":"如果新學生一早受到同學歡迎和老師支援，他可能沒有適應上的成長陣痛。"},{"en":"If young stars avoid scandals and stay balanced, people may say they have had no growing pains.","zh":"如果年輕明星避開醜聞並保持平衡，人們可能說他們沒有成長陣痛。"},{"en":"The phrase contrasts smooth development with the problems people often expect during growing up.","zh":"這個短語把順利發展與人們常預期的成長問題作對比。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":1},{"front":"tales of lost youth","meaning":"失去童年的故事","examples":[{"en":"People often tell tales of lost youth about child actors.","zh":"人們常講述童星失去童年的故事。"},{"en":"Tales of lost youth are stories about young people losing a normal childhood because of fame, pressure or work.","zh":"「tales of lost youth」是關於年輕人因名氣、壓力或工作而失去正常童年的故事。"},{"en":"A child singer may become the subject of tales of lost youth if she spends all her time performing instead of playing.","zh":"如果童星歌手把全部時間花在表演而不是玩耍，她可能成為失去童年故事的主角。"},{"en":"If children grow up under public pressure, people may worry that their youth has been taken away.","zh":"如果孩子在公眾壓力下長大，人們可能擔心他們的童年被奪走。"},{"en":"The phrase carries sadness because childhood is shown as something lost too early.","zh":"這個短語帶有傷感，因為童年被呈現為太早失去的東西。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":1},{"front":"spring from","meaning":"源於；來自","examples":[{"en":"Such stories often spring from actors who become successful too soon.","zh":"這類故事常源於太早成功的演員。"},{"en":"To spring from something means to come from it or be caused by it.","zh":"「spring from」某事，意思是來自它或由它造成。"},{"en":"A class argument may spring from a small misunderstanding during group work.","zh":"課堂爭執可能源於小組活動中的小誤會。"},{"en":"If jealousy springs from unfair treatment, solving the unfairness may reduce the jealousy.","zh":"如果嫉妒源於不公平對待，解決不公平可能減少嫉妒。"},{"en":"The phrase explains the source or origin of an idea, feeling or problem.","zh":"這個短語解釋想法、感受或問題的來源。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":1},{"front":"too successful too soon","meaning":"太早成名","examples":[{"en":"Some young actors become too successful too soon.","zh":"有些年輕演員太早成名。"},{"en":"Too successful too soon means becoming famous or powerful before someone is mature enough to handle it.","zh":"「too successful too soon」意思是在未夠成熟處理成功前，就變得有名或有權勢。"},{"en":"A teenager who becomes rich overnight may struggle if success arrives too soon.","zh":"一名青少年一夜暴富，可能因成功來得太早而難以應付。"},{"en":"If success comes before good habits and support are built, it can create pressure and bad choices.","zh":"如果成功在良好習慣和支援建立前到來，它可能造成壓力和錯誤選擇。"},{"en":"The phrase warns that early success can be dangerous as well as exciting.","zh":"這個短語提醒人們，早期成功可以令人興奮，也可以有危險。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":1},{"front":"you will probably not hear any about","meaning":"你大概不會聽到任何關於……的","examples":[{"en":"You will probably not hear any tales of lost youth about Daniel Radcliffe.","zh":"你大概不會聽到任何關於 Daniel Radcliffe 失去童年的故事。"},{"en":"You will probably not hear any about something means people are unlikely to hear such stories or reports.","zh":"「you will probably not hear any about」某事，意思是人們大概不會聽到這類故事或報道。"},{"en":"You will probably not hear any complaints about the new library if students use it happily every day.","zh":"如果學生每天都開心使用新圖書館，你大概不會聽到任何關於它的投訴。"},{"en":"If a young actor behaves calmly and avoids scandals, people will probably not hear many negative stories about him.","zh":"如果年輕演員表現冷靜並避開醜聞，人們大概不會聽到很多關於他的負面故事。"},{"en":"The phrase suggests that an expected kind of story is missing.","zh":"這個短語暗示一種本來可能預期出現的故事沒有出現。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":1},{"front":"conjures up","meaning":"變出；塑造出","examples":[{"en":"Daniel Radcliffe conjures up his alter ego Harry Potter in the film.","zh":"Daniel Radcliffe 在電影中塑造出他的另一個自我 Harry Potter。"},{"en":"To conjure up something means to create, suggest or bring an image strongly into people’s minds.","zh":"「conjure up」某物，意思是創造、喚起或在別人腦海中強烈呈現某個形象。"},{"en":"The smell of old books can conjure up memories of a school library.","zh":"舊書的氣味可以喚起學校圖書館的回憶。"},{"en":"If an actor plays a role convincingly, he can conjure up a whole fictional world for viewers.","zh":"如果演員把角色演得可信，他可以為觀眾塑造出整個虛構世界。"},{"en":"The phrase often suggests imagination, magic or vivid mental pictures.","zh":"這個短語常暗示想像、魔法或鮮明的心理圖像。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":1},{"front":"alter ego","meaning":"另一個自我；銀幕化身","examples":[{"en":"Harry Potter became Daniel Radcliffe’s famous alter ego.","zh":"Harry Potter 成為 Daniel Radcliffe 著名的銀幕化身。"},{"en":"An alter ego is another identity or public self closely connected with a person.","zh":"「alter ego」是與某人密切相連的另一個身份或公開自我。"},{"en":"A shy student may have a confident alter ego when performing on stage.","zh":"害羞的學生在舞台表演時，可能有一個自信的另一個自我。"},{"en":"If an actor plays one role for many years, audiences may connect that alter ego with the actor himself.","zh":"如果演員多年飾演同一角色，觀眾可能把那個銀幕化身與演員本人連在一起。"},{"en":"The phrase suggests a second self, not just a temporary costume.","zh":"這個短語暗示第二個自我，而不只是臨時服裝。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":1},{"front":"boy-wizard saga","meaning":"男孩巫師傳奇故事","examples":[{"en":"Harry Potter and the Goblet of Fire is part of the boy-wizard saga.","zh":"《哈利波特：火盃的考驗》是男孩巫師傳奇故事的一部分。"},{"en":"A boy-wizard saga is a long adventure story about a young male wizard.","zh":"「boy-wizard saga」是關於年輕男巫的長篇冒險故事。"},{"en":"A fantasy series about a child learning magic at school could be called a boy-wizard saga.","zh":"一個關於孩子在學校學魔法的奇幻系列，可以被稱為男孩巫師傳奇故事。"},{"en":"If a story continues across many books and films, it becomes a saga rather than a single tale.","zh":"如果故事跨越多本書和多部電影延續，它就是 saga，而不是單一故事。"},{"en":"The phrase combines character type with a long-running story.","zh":"這個短語把角色類型與長篇連載故事結合起來。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":1},{"front":"opening Nov. 18","meaning":"於十一月十八日上映","examples":[{"en":"The film was opening Nov. 18 after its New York premiere.","zh":"該電影在紐約首映後，於十一月十八日上映。"},{"en":"Opening Nov. 18 means being released or shown to the public on November 18.","zh":"「opening Nov. 18」意思是於十一月十八日公開上映或展示。"},{"en":"A new school exhibition opening Friday will allow parents to see students’ artwork.","zh":"星期五開幕的新學校展覽將讓家長看到學生作品。"},{"en":"If a film opens after its premiere, the premiere happens first and public release follows.","zh":"如果電影在首映後上映，首映先發生，公開放映隨後開始。"},{"en":"The phrase gives the date when audiences can start watching it.","zh":"這個短語提供觀眾可以開始觀看的日期。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":1},{"front":"its premiere","meaning":"首映","examples":[{"en":"The film had its premiere in New York City.","zh":"該電影在紐約市舉行首映。"},{"en":"A premiere is the first public showing of a film, play or performance.","zh":"「premiere」是電影、戲劇或表演的首次公開放映或演出。"},{"en":"The school play had its premiere on Friday before parents and teachers.","zh":"學校話劇星期五在家長和老師面前首演。"},{"en":"If a movie has a glamorous premiere, reporters and actors may attend before the wider release.","zh":"如果電影有盛大首映，記者和演員可能在正式上映前出席。"},{"en":"The phrase refers to the first official showing, not every later screening.","zh":"這個短語指首次正式放映，而不是之後每次放映。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":1},{"front":"be surrounded by","meaning":"被……包圍","examples":[{"en":"Radcliffe describes childhood as being surrounded by people he loves.","zh":"Radcliffe 把童年描述為被他所愛的人包圍。"},{"en":"To be surrounded by people means to have them all around you physically or emotionally.","zh":"「be surrounded by」人，意思是身體上或情感上被他們圍繞。"},{"en":"A child feels safer when surrounded by family members who listen and care.","zh":"當孩子被願意聆聽和關心的家人包圍，他會感到更安全。"},{"en":"If someone is surrounded by supportive people, fame or pressure may be easier to handle.","zh":"如果某人被支持他的人包圍，名氣或壓力可能較容易應付。"},{"en":"The phrase can describe both a physical setting and a network of support.","zh":"這個短語可以描述實際環境，也可以描述支援網絡。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":1},{"front":"people who you love being around","meaning":"你喜歡相處的人","examples":[{"en":"Childhood can mean being with people who you love being around.","zh":"童年可以意味着與你喜歡相處的人在一起。"},{"en":"People who you love being around are people whose company makes you feel happy, safe or comfortable.","zh":"「people who you love being around」是令你感到快樂、安全或舒服的人。"},{"en":"A student may enjoy school more when classmates are people she loves being around.","zh":"當同學是她喜歡相處的人，學生可能更享受上學。"},{"en":"If a child grows up around kind people, childhood memories may feel warmer.","zh":"如果孩子在友善的人身邊長大，童年回憶可能更溫暖。"},{"en":"The phrase focuses on emotional comfort in relationships.","zh":"這個短語集中於人際關係中的情感舒適。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":2},{"front":"incredibly happy","meaning":"非常快樂","examples":[{"en":"Radcliffe says he has been incredibly happy.","zh":"Radcliffe 說他一直非常快樂。"},{"en":"Incredibly happy means extremely happy.","zh":"「incredibly happy」意思是極度快樂。"},{"en":"A student may feel incredibly happy after being accepted into her first-choice school.","zh":"學生被第一志願學校錄取後，可能感到非常快樂。"},{"en":"If someone feels supported at home and work, they may be incredibly happy despite pressure.","zh":"如果某人在家庭和工作中都得到支援，即使有壓力也可能非常快樂。"},{"en":"The phrase strongly emphasises happiness.","zh":"這個短語強烈強調快樂程度。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":2},{"front":"I absolutely have had that","meaning":"我絕對有過那樣的經歷","examples":[{"en":"Radcliffe says he absolutely has had a happy childhood.","zh":"Radcliffe 說他絕對有過快樂童年。"},{"en":"I absolutely have had that means the speaker strongly confirms that they have experienced it.","zh":"「I absolutely have had that」意思是說話者強烈確認自己有過那種經歷。"},{"en":"If someone asks whether you had support from teachers, you might say, “I absolutely have had that.”","zh":"如果有人問你是否得到老師支援，你可能說：「我絕對有過那樣的經歷。」"},{"en":"The phrase adds confidence when the speaker wants to reject doubt.","zh":"當說話者想消除懷疑時，這個短語加入肯定語氣。"},{"en":"It is more emphatic than simply saying “yes, I have.”","zh":"它比單純說 “yes, I have” 更強調。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":2},{"front":"a bizarre childhood","meaning":"奇異的童年","examples":[{"en":"Radcliffe describes his childhood as a bizarre childhood.","zh":"Radcliffe 把他的童年描述為奇異的童年。"},{"en":"A bizarre childhood is a childhood that is strange, unusual or very different from normal.","zh":"「a bizarre childhood」是奇怪、不尋常或與正常童年很不同的童年。"},{"en":"A child who travels with a circus every month may have a bizarre childhood compared with classmates.","zh":"每個月跟馬戲團旅行的孩子，與同學相比可能有奇異的童年。"},{"en":"If a child grows up on film sets instead of ordinary playgrounds, life may feel bizarre but exciting.","zh":"如果孩子在片場而不是普通遊樂場長大，生活可能奇異但令人興奮。"},{"en":"The phrase does not always mean bad; it means unusually strange.","zh":"這個短語不一定表示壞；它表示異常奇怪。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":2},{"front":"it’s been strange, but…","meaning":"雖然很奇怪，但……","examples":[{"en":"It’s been strange, but it’s been great.","zh":"雖然很奇怪，但這一直很棒。"},{"en":"It’s been strange, but… introduces a contrast between an unusual experience and a positive judgement.","zh":"「it’s been strange, but…」用來引出不尋常經歷與正面評價之間的對比。"},{"en":"Moving to a new country has been strange, but it has taught me a lot.","zh":"搬到新國家雖然很奇怪，但教會了我很多。"},{"en":"If a new school feels unfamiliar but supportive, a student may say it has been strange but good.","zh":"如果新學校感覺陌生但有支援，學生可能說雖然奇怪但很好。"},{"en":"The phrase balances honesty about difficulty with appreciation.","zh":"這個短語平衡對困難的誠實和感激。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":2},{"front":"an articulate 16-year-old","meaning":"表達清晰的十六歲少年","examples":[{"en":"Radcliffe is described as an articulate 16-year-old.","zh":"Radcliffe 被描述為一名表達清晰的十六歲少年。"},{"en":"An articulate 16-year-old is a sixteen-year-old who can express ideas clearly and confidently.","zh":"「an articulate 16-year-old」是能清楚而自信表達想法的十六歲少年。"},{"en":"An articulate student can explain her opinion without using complicated words.","zh":"表達清晰的學生可以不用複雜字詞也能解釋自己的意見。"},{"en":"If a young actor is articulate, interviews may feel easier and more natural.","zh":"如果年輕演員表達清晰，訪問可能更容易和自然。"},{"en":"The phrase praises communication ability, not age alone.","zh":"這個短語稱讚溝通能力，而不只是年齡。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":2},{"front":"has not been arrested","meaning":"沒有被捕","examples":[{"en":"Radcliffe has not been arrested or involved in public scandals.","zh":"Radcliffe 沒有被捕，也沒有牽涉公開醜聞。"},{"en":"Has not been arrested means the person has not been taken by police for suspected wrongdoing.","zh":"「has not been arrested」意思是此人沒有因涉嫌犯錯而被警方拘捕。"},{"en":"A celebrity who has not been arrested avoids one common source of damaging news.","zh":"沒有被捕的名人避開了一種常見的負面新聞來源。"},{"en":"If a young star stays out of legal trouble, the public may see him as responsible.","zh":"如果年輕明星遠離法律麻煩，公眾可能視他為負責任。"},{"en":"The phrase is used to contrast him with troubled celebrities.","zh":"這個短語用來把他與有問題的名人作對比。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":2},{"front":"warred with his parents over","meaning":"因……與父母爭執","examples":[{"en":"He has not warred with his parents over his money.","zh":"他沒有因金錢與父母爭執。"},{"en":"To war with someone over something means to fight or argue seriously about it.","zh":"「war with someone over」某事，意思是因某事與某人嚴重爭鬥或爭吵。"},{"en":"A teenager may war with parents over phone use if no clear rules are agreed.","zh":"如果沒有清楚規則，青少年可能因手機使用與父母爭執。"},{"en":"If a child star argues with parents over money, family trust can break down.","zh":"如果童星因金錢與父母爭執，家庭信任可能瓦解。"},{"en":"The phrase is stronger than “disagree”; it suggests serious conflict.","zh":"這個短語比 “disagree” 更強，暗示嚴重衝突。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":2},{"front":"his millions now tucked away","meaning":"他已妥善存放的數百萬財產","examples":[{"en":"His millions are now tucked away safely.","zh":"他的數百萬財產現在已妥善存放。"},{"en":"Money tucked away is money saved or stored safely rather than spent immediately.","zh":"「money tucked away」是被安全儲存而不是立即花掉的金錢。"},{"en":"A family may keep emergency savings tucked away for medical bills or repairs.","zh":"家庭可能妥善存放緊急儲蓄，以應付醫療費或維修。"},{"en":"If a child actor’s money is tucked away, it may be protected until he is older.","zh":"如果童星的金錢被妥善存放，它可能受到保護，直到他年紀更大。"},{"en":"The phrase suggests careful saving and protection.","zh":"這個短語暗示仔細儲蓄和保護。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":2},{"front":"thrown hissy fits","meaning":"發脾氣；鬧情緒","examples":[{"en":"Radcliffe has not thrown hissy fits on the set.","zh":"Radcliffe 沒有在片場發脾氣。"},{"en":"To throw a hissy fit means to have a childish angry outburst over something small.","zh":"「throw a hissy fit」意思是因小事爆發孩子氣的怒氣。"},{"en":"A child may throw a hissy fit if he is told he cannot buy another toy.","zh":"如果孩子被告知不能再買玩具，他可能鬧情緒。"},{"en":"If an actor throws hissy fits at work, colleagues may find him difficult to deal with.","zh":"如果演員在工作中發脾氣，同事可能覺得他難以相處。"},{"en":"The phrase is informal and often critical.","zh":"這個短語較口語，而且常帶批評意味。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":2},{"front":"on the set","meaning":"在片場","examples":[{"en":"He has behaved well on the set.","zh":"他在片場表現良好。"},{"en":"On the set means at the place where a film or television programme is being made.","zh":"「on the set」意思是在電影或電視節目拍攝的地方。"},{"en":"Actors must arrive on the set early so filming can begin on time.","zh":"演員必須早點到片場，拍攝才能準時開始。"},{"en":"If someone behaves badly on the set, the whole production may be delayed.","zh":"如果有人在片場表現差，整個製作可能延誤。"},{"en":"The phrase refers to the working location for filming.","zh":"這個短語指拍攝工作的地點。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":2},{"front":"in the name of","meaning":"到底；究竟","examples":[{"en":"The writer asks what in the name of Macaulay Culkin is going on.","zh":"作者問「到底以 Macaulay Culkin 之名，發生了甚麼事」。"},{"en":"In the name of is used for dramatic emphasis when someone is surprised, confused or annoyed.","zh":"「in the name of」用於某人驚訝、困惑或惱怒時，加強語氣。"},{"en":"A teacher might say, “What in the name of common sense happened to this classroom?”","zh":"老師可能說：「到底發生了甚麼事，令這間課室變成這樣？」"},{"en":"If a situation is very unexpected, this phrase adds humour or disbelief.","zh":"如果情況非常出乎意料，這個短語會加入幽默或難以置信的語氣。"},{"en":"The phrase is not literal; it is an emphatic expression.","zh":"這個短語不是字面意思，而是強調用語。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":3},{"front":"what is going on","meaning":"發生甚麼事","examples":[{"en":"The writer wonders what is going on with such a well-behaved child star.","zh":"作者想知道這樣一位表現良好的童星到底發生甚麼事。"},{"en":"What is going on means what is happening or why a situation is happening.","zh":"「what is going on」意思是發生甚麼事，或為甚麼情況會這樣。"},{"en":"A parent may ask what is going on if a normally cheerful child becomes quiet.","zh":"如果一個平常開朗的孩子突然變沉默，家長可能問發生甚麼事。"},{"en":"If expectations do not match reality, people ask what is going on.","zh":"如果預期與現實不符，人們會問到底發生甚麼事。"},{"en":"The phrase is used when someone wants an explanation.","zh":"這個短語用於某人想要解釋時。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":3},{"front":"know exactly what they’re worth","meaning":"清楚知道自己的身價","examples":[{"en":"The young actors know exactly what they are worth.","zh":"這些年輕演員清楚知道自己的身價。"},{"en":"To know exactly what one is worth means to understand one’s value, pay level or public importance.","zh":"「know exactly what one is worth」意思是明白自己的價值、薪酬水平或公眾重要性。"},{"en":"A skilled worker who knows exactly what she is worth may negotiate a fair salary.","zh":"清楚知道自己價值的熟練工人，可能會爭取公平薪金。"},{"en":"If young stars know their market value too early, they may become difficult or overconfident.","zh":"如果年輕明星太早知道自己的市場價值，他們可能變得難相處或過分自信。"},{"en":"The phrase can refer to money, status or personal value.","zh":"這個短語可以指金錢、地位或個人價值。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":3},{"front":"co-stars","meaning":"聯合主演；共同演出的演員","examples":[{"en":"Emma Watson and Rupert Grint are Radcliffe’s co-stars.","zh":"Emma Watson 和 Rupert Grint 是 Radcliffe 的聯合主演。"},{"en":"Co-stars are actors who share major roles in the same film, show or play.","zh":"「co-stars」是在同一部電影、節目或戲劇中共同擔任主要角色的演員。"},{"en":"Two students can be co-stars in a school musical if both play leading roles.","zh":"如果兩名學生都在學校音樂劇中擔任主角，他們可以是聯合主演。"},{"en":"If co-stars work well together, the story feels more natural on screen.","zh":"如果共同主演合作良好，故事在銀幕上會感覺更自然。"},{"en":"The phrase describes people acting alongside one another.","zh":"這個短語描述一起演出的演員。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":3},{"front":"become impossible","meaning":"變得難以相處","examples":[{"en":"The young actors have not become impossible.","zh":"這些年輕演員沒有變得難以相處。"},{"en":"To become impossible means to become extremely difficult to deal with.","zh":"「become impossible」意思是變得極難應付。"},{"en":"A student may become impossible in class if every rule is ignored and every request becomes an argument.","zh":"如果學生無視每條規則，並把每個要求都變成爭吵，他在課堂上可能變得難以應付。"},{"en":"If fame makes young actors demanding and rude, colleagues may say they have become impossible.","zh":"如果名氣令年輕演員要求多多又粗魯，同事可能說他們變得難以相處。"},{"en":"The phrase describes behaviour that is no longer manageable.","zh":"這個短語描述不再容易管理的行為。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":3},{"front":"became a global icon","meaning":"成為全球偶像","examples":[{"en":"Radcliffe became a global icon as a child actor.","zh":"Radcliffe 作為童星成為全球偶像。"},{"en":"To become a global icon means to become famous and recognised around the world.","zh":"「become a global icon」意思是變得在世界各地知名和被認出。"},{"en":"A singer may become a global icon if people in many countries know her songs and image.","zh":"如果許多國家的人都認識某歌手的歌曲和形象，她可能成為全球偶像。"},{"en":"If a child actor becomes a global icon, ordinary school life may become harder.","zh":"如果童星成為全球偶像，普通校園生活可能變得更困難。"},{"en":"The phrase suggests worldwide fame, not just local popularity.","zh":"這個短語暗示全球名氣，而不只是本地受歡迎。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":3},{"front":"as a 10-year-old","meaning":"十歲時","examples":[{"en":"Radcliffe became famous as a 10-year-old.","zh":"Radcliffe 十歲時成名。"},{"en":"As a 10-year-old means when he was ten years old.","zh":"「as a 10-year-old」意思是在他十歲時。"},{"en":"As a 10-year-old, a child may still need adults to help manage school, money and public attention.","zh":"十歲時，孩子通常仍需要成人幫助管理學校、金錢和公眾關注。"},{"en":"If someone becomes famous as a child, their development may be shaped by fame early.","zh":"如果某人在兒童時期成名，他的成長可能早早受到名氣影響。"},{"en":"The phrase fixes the age at which something happened.","zh":"這個短語確定某事發生時的年齡。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":3},{"front":"won a worldwide casting call","meaning":"在全球選角中勝出","examples":[{"en":"Radcliffe won a worldwide casting call to play Harry Potter.","zh":"Radcliffe 在全球選角中勝出，飾演 Harry Potter。"},{"en":"To win a worldwide casting call means to be chosen from actors searched for internationally.","zh":"「win a worldwide casting call」意思是在國際範圍尋找演員後被選中。"},{"en":"A child dancer might win a national audition if judges choose her from thousands of applicants.","zh":"如果評審從數千名申請者中選中一名兒童舞者，她可能在全國試鏡中勝出。"},{"en":"If a role is famous, winning the casting call can change an actor’s life.","zh":"如果角色很有名，贏得選角可以改變演員一生。"},{"en":"The phrase highlights strong competition and selection.","zh":"這個短語強調激烈競爭和選拔。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":3},{"front":"casting call","meaning":"選角招募","examples":[{"en":"The casting call searched for the right actor to play Harry Potter.","zh":"選角招募尋找適合飾演 Harry Potter 的演員。"},{"en":"A casting call is an announcement or process for finding actors for roles.","zh":"「casting call」是為角色尋找演員的公告或過程。"},{"en":"A school drama club may hold a casting call for students who want to act in a play.","zh":"學校戲劇社可能為想參演話劇的學生舉行選角招募。"},{"en":"If many people attend a casting call, directors can compare different talents.","zh":"如果許多人參加選角招募，導演可以比較不同才能。"},{"en":"The phrase belongs to film, television and theatre production.","zh":"這個短語屬於電影、電視和劇場製作語境。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":3},{"front":"breathe life into","meaning":"賦予……生命","examples":[{"en":"Radcliffe was chosen to breathe life into Harry Potter.","zh":"Radcliffe 被選中去賦予 Harry Potter 生命。"},{"en":"To breathe life into a character means to make the character feel real and alive.","zh":"「breathe life into」角色，意思是令角色感覺真實而有生命力。"},{"en":"A good storyteller can breathe life into old history by describing ordinary people’s choices.","zh":"好說書人可以透過描述普通人的選擇，為舊歷史賦予生命。"},{"en":"If an actor understands a role deeply, the performance can bring energy to the story.","zh":"如果演員深入理解角色，表演可以為故事注入活力。"},{"en":"The phrase means making something vivid, not literally giving it breath.","zh":"這個短語意思是令某物生動，而不是字面上給它呼吸。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":3},{"front":"best-selling fantasy books","meaning":"暢銷奇幻小說","examples":[{"en":"Harry Potter came from J. K. Rowling’s best-selling fantasy books.","zh":"Harry Potter 來自 J. K. Rowling 的暢銷奇幻小說。"},{"en":"Best-selling fantasy books are fantasy books that sell extremely well.","zh":"「best-selling fantasy books」是銷量非常好的奇幻小說。"},{"en":"A best-selling children’s book may become a film if many readers love the story.","zh":"如果一本暢銷兒童書受到許多讀者喜愛，它可能被改編成電影。"},{"en":"If fantasy books become best-sellers, publishers may create films, games and merchandise.","zh":"如果奇幻小說成為暢銷書，出版社可能推出電影、遊戲和商品。"},{"en":"The phrase combines genre with commercial success.","zh":"這個短語把文類和商業成功結合起來。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":3},{"front":"despite endless adoration","meaning":"儘管受到無盡崇拜","examples":[{"en":"Despite endless adoration, Radcliffe has remained grounded.","zh":"儘管受到無盡崇拜，Radcliffe 仍然保持腳踏實地。"},{"en":"Despite endless adoration means although many people admire him intensely and continuously.","zh":"「despite endless adoration」意思是雖然很多人持續而強烈地崇拜他。"},{"en":"Despite winning many awards, a student may remain humble if teachers and family guide him well.","zh":"儘管贏得很多獎項，如果有老師和家人良好引導，學生仍可能保持謙遜。"},{"en":"If someone stays normal despite fame, people may respect their character more.","zh":"如果某人即使成名仍保持正常，人們可能更尊重其品格。"},{"en":"The phrase highlights contrast between public worship and personal balance.","zh":"這個短語強調公眾崇拜與個人平衡之間的對比。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":4},{"front":"notorious fraternity of","meaning":"惡名昭彰的一群……","examples":[{"en":"He avoids the notorious fraternity of troubled young actors.","zh":"他避開了惡名昭彰的一群有問題年輕演員。"},{"en":"A notorious fraternity of people is a well-known group with a bad reputation.","zh":"「notorious fraternity of」某些人，是因壞名聲而廣為人知的一群人。"},{"en":"A school may have a notorious group of students who always disrupt lessons.","zh":"學校可能有一群惡名昭彰、總是打擾課堂的學生。"},{"en":"If young celebrities join a badly behaved crowd, their reputation may suffer.","zh":"如果年輕名人加入行為差劣的一群人，他們的名聲可能受損。"},{"en":"The phrase is negative and suggests belonging to a problematic group.","zh":"這個短語帶負面意思，暗示屬於有問題的群體。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":4},{"front":"thespian lads","meaning":"年輕男演員","examples":[{"en":"The writer refers to young male actors as thespian lads.","zh":"作者把年輕男演員稱為 thespian lads。"},{"en":"Thespian lads means young male actors, often said in a playful or literary way.","zh":"「thespian lads」指年輕男演員，常帶玩味或文學色彩。"},{"en":"A drama teacher may praise the thespian lads who helped prepare the school play.","zh":"戲劇老師可能稱讚幫忙準備學校話劇的年輕男演員。"},{"en":"If young actors become famous too early, writers may discuss how these thespian lads handle fame.","zh":"如果年輕演員太早成名，作者可能討論這些年輕男演員如何處理名氣。"},{"en":"The phrase is more colourful than simply saying “young actors”.","zh":"這個短語比單純說 “young actors” 更有色彩。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":4},{"front":"turn rotten","meaning":"變壞；走歪","examples":[{"en":"Some young actors turn rotten after early success.","zh":"有些年輕演員在早期成功後變壞。"},{"en":"To turn rotten means to become morally worse, badly behaved or spoiled.","zh":"「turn rotten」意思是變得道德上更差、行為惡劣或被寵壞。"},{"en":"A child may become spoiled if every demand is accepted and no one sets limits.","zh":"如果孩子每個要求都被接受而沒有人設限，他可能被寵壞。"},{"en":"If fame comes without guidance, a young person may turn arrogant or irresponsible.","zh":"如果名氣在沒有引導下到來，年輕人可能變得傲慢或不負責任。"},{"en":"The phrase is informal and strongly negative.","zh":"這個短語較口語，而且非常負面。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":4},{"front":"a one-to-one conversation","meaning":"一對一談話","examples":[{"en":"The interview took place in a one-to-one conversation at a London hotel.","zh":"訪問是在倫敦一間酒店的一對一談話中進行。"},{"en":"A one-to-one conversation is a private conversation between two people.","zh":"「a one-to-one conversation」是兩個人之間的私人談話。"},{"en":"A teacher may have a one-to-one conversation with a student who needs personal advice.","zh":"老師可能與需要個人建議的學生進行一對一談話。"},{"en":"If an interview is one-to-one, the speaker may answer more honestly than in a crowd.","zh":"如果訪問是一對一的，說話者可能比在群眾面前更誠實作答。"},{"en":"The phrase contrasts private dialogue with a group discussion.","zh":"這個短語把私人對話與小組討論作對比。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":4},{"front":"at a London hotel","meaning":"在倫敦一間酒店","examples":[{"en":"The conversation happened at a London hotel.","zh":"這次談話在倫敦一間酒店進行。"},{"en":"At a London hotel means the event took place in a hotel located in London.","zh":"「at a London hotel」意思是事件發生在位於倫敦的一間酒店。"},{"en":"A business meeting may be held at a London hotel when visitors arrive from abroad.","zh":"當訪客從海外抵達，商務會議可能在倫敦一間酒店舉行。"},{"en":"If an interview happens in a hotel, the setting may feel formal but temporary.","zh":"如果訪問在酒店進行，場景可能感覺正式但臨時。"},{"en":"The phrase gives the location of the conversation.","zh":"這個短語提供談話地點。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":4},{"front":"without those spectacles","meaning":"沒有那副眼鏡","examples":[{"en":"Without those Harry Potter spectacles, Radcliffe looks different.","zh":"沒有那副 Harry Potter 眼鏡，Radcliffe 看起來不同。"},{"en":"Without those spectacles means when he is not wearing those glasses.","zh":"「without those spectacles」意思是當他沒有戴那副眼鏡時。"},{"en":"A student may look very different without the round glasses everyone recognises.","zh":"如果學生沒有戴那副大家都認得的圓眼鏡，他可能看起來很不同。"},{"en":"If an actor removes a famous costume item, audiences may see the real person more clearly.","zh":"如果演員除下著名服裝配件，觀眾可能更清楚看到真人。"},{"en":"The phrase points to a visual difference caused by removing glasses.","zh":"這個短語指出因除下眼鏡造成的外觀差異。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":4},{"front":"emerges as","meaning":"顯得是；展現為","examples":[{"en":"Radcliffe emerges as very much a boy.","zh":"Radcliffe 顯得十足是一個男孩。"},{"en":"To emerge as something means to appear or be seen in that way after people look more closely.","zh":"「emerge as」某種人或事，意思是在仔細觀察後顯得或被看成那樣。"},{"en":"After the interview, the quiet student emerged as a thoughtful leader.","zh":"訪問後，那名安靜的學生展現為一位有思想的領袖。"},{"en":"If a star removes the costume, he may emerge as an ordinary teenager.","zh":"如果明星除下戲服，他可能顯得像普通青少年。"},{"en":"The phrase shows how someone’s true impression becomes clear.","zh":"這個短語顯示某人的真正印象變得清楚。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":4},{"front":"very much a boy","meaning":"十足一個男孩","examples":[{"en":"Without the costume, Radcliffe seems very much a boy.","zh":"沒有戲服時，Radcliffe 看起來十足一個男孩。"},{"en":"Very much a boy means clearly still boyish, young and not fully adult.","zh":"「very much a boy」意思是明顯仍然有男孩氣、年輕且未完全成人。"},{"en":"A young actor may sound confident on stage but still seem very much a boy in private.","zh":"年輕演員在台上可能聽起來自信，但私下仍像十足一個男孩。"},{"en":"If someone is famous but still childlike, people may notice the contrast more strongly.","zh":"如果某人有名但仍有孩子氣，人們可能更強烈注意到對比。"},{"en":"The phrase stresses ordinary youth behind public fame.","zh":"這個短語強調公眾名氣背後的普通年少感。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":4},{"front":"a showman’s polish","meaning":"表演者的老練風度","examples":[{"en":"Radcliffe has a showman’s polish when speaking in public.","zh":"Radcliffe 公開說話時有表演者的老練風度。"},{"en":"A showman’s polish means the smooth, confident manner of someone used to performing for an audience.","zh":"「a showman’s polish」指習慣面向觀眾表演的人所具有的流暢自信風度。"},{"en":"A student host may develop a showman’s polish after leading many school assemblies.","zh":"學生主持人在主持多次學校集會後，可能培養出表演者的老練風度。"},{"en":"If an actor answers questions smoothly, reporters may see professional polish beyond his age.","zh":"如果演員流暢回答問題，記者可能看到超越其年齡的專業老練。"},{"en":"The phrase praises public performance skill.","zh":"這個短語稱讚公開表現能力。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":4},{"front":"no abracadabra could evoke","meaning":"連咒語也無法喚出的","examples":[{"en":"No abracadabra could have evoked such polish when he first started.","zh":"他剛開始時，連咒語也無法喚出這種老練風度。"},{"en":"No abracadabra could evoke something means no magic words could suddenly create it.","zh":"「no abracadabra could evoke」某物，意思是沒有魔法字句能突然創造它。"},{"en":"No magic phrase could give a shy student confidence without practice.","zh":"沒有魔法句子能讓害羞學生不經練習就有信心。"},{"en":"If public confidence takes years to develop, it cannot be conjured up instantly.","zh":"如果公開自信需要多年培養，它就不能立即被變出來。"},{"en":"The phrase uses magic language humorously to say a skill was not automatic.","zh":"這個短語幽默地使用魔法語言，表示技能不是自動出現的。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":4},{"front":"wielded a magic wand","meaning":"揮動魔杖","examples":[{"en":"Radcliffe first wielded a magic wand as Harry Potter.","zh":"Radcliffe 首次以 Harry Potter 身份揮動魔杖。"},{"en":"To wield a magic wand means to hold and use a wand, usually in a magical story.","zh":"「wield a magic wand」意思是拿着並使用魔杖，通常出現在魔法故事中。"},{"en":"In a school play, a student playing a fairy may wield a magic wand on stage.","zh":"在學校話劇中，飾演仙女的學生可能在台上揮動魔杖。"},{"en":"If an actor is famous for wielding a wand, audiences may connect him strongly with a wizard role.","zh":"如果演員因揮動魔杖而出名，觀眾可能強烈把他與巫師角色連在一起。"},{"en":"The phrase belongs to fantasy and performance contexts.","zh":"這個短語屬於奇幻和表演語境。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":5},{"front":"make small talk","meaning":"閒談；寒暄","examples":[{"en":"Radcliffe makes small talk before the first question.","zh":"Radcliffe 在第一條問題前先寒暄。"},{"en":"To make small talk means to chat politely about light topics.","zh":"「make small talk」意思是禮貌地談論輕鬆話題。"},{"en":"People often make small talk about weather while waiting for a meeting to start.","zh":"人們在等待會議開始時，常閒談天氣。"},{"en":"If someone makes small talk easily, an interview may begin more comfortably.","zh":"如果某人能自然寒暄，訪問開始時可能更舒服。"},{"en":"The phrase describes casual conversation, not serious discussion.","zh":"這個短語描述輕鬆對話，而不是嚴肅討論。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":5},{"front":"before the first question is popped","meaning":"在第一條問題被提出之前","examples":[{"en":"He makes small talk before the first question is popped.","zh":"他在第一條問題被提出之前先閒談。"},{"en":"Before the first question is popped means before the interviewer asks the first question.","zh":"「before the first question is popped」意思是在訪問者提出第一條問題之前。"},{"en":"A teacher may smile and chat before the first question is asked in an oral exam.","zh":"老師可能在口試第一條問題被提出前微笑並聊天。"},{"en":"If someone relaxes the room before questions begin, the conversation may feel less tense.","zh":"如果有人在問題開始前放鬆氣氛，談話可能較不緊張。"},{"en":"The phrase uses “popped” informally to mean asked suddenly or casually.","zh":"這個短語中的 “popped” 較口語，意思是突然或輕鬆地提出。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":5},{"front":"in a press conference","meaning":"在記者會上","examples":[{"en":"Radcliffe later spoke in a press conference.","zh":"Radcliffe 之後在記者會上發言。"},{"en":"In a press conference means at a formal event where reporters ask questions.","zh":"「in a press conference」意思是在記者提問的正式活動中。"},{"en":"A school may hold a press conference after winning a major competition.","zh":"學校在贏得大型比賽後可能舉行記者會。"},{"en":"If an actor speaks well in a press conference, newspapers may describe him as confident.","zh":"如果演員在記者會上表現良好，報章可能形容他自信。"},{"en":"The phrase belongs to media and public communication.","zh":"這個短語屬於媒體和公共溝通語境。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":5},{"front":"works the room","meaning":"掌控全場氣氛","examples":[{"en":"He works the room like a professional comedian.","zh":"他像專業喜劇演員一樣掌控全場氣氛。"},{"en":"To work the room means to handle an audience skillfully and keep people engaged.","zh":"「work the room」意思是熟練地應付觀眾並保持大家投入。"},{"en":"A confident host works the room by greeting guests and making them laugh.","zh":"自信主持人透過問候嘉賓和逗大家笑來掌控全場氣氛。"},{"en":"If someone works the room well, the atmosphere becomes lively and relaxed.","zh":"如果某人善於掌控全場，氣氛會變得活躍而放鬆。"},{"en":"The phrase describes social performance, not physical labour.","zh":"這個短語描述社交表演能力，而不是體力勞動。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":5},{"front":"like a professional comedian","meaning":"像專業喜劇演員一樣","examples":[{"en":"He handles the room like a professional comedian.","zh":"他像專業喜劇演員一樣應付全場。"},{"en":"Like a professional comedian means with the timing, confidence and audience control of an experienced comic performer.","zh":"「like a professional comedian」意思是帶着有經驗喜劇表演者的時機掌握、自信和控場能力。"},{"en":"A teacher may explain a boring topic like a professional comedian if students keep laughing and listening.","zh":"如果學生一直笑着聽，老師可能像專業喜劇演員一樣解釋沉悶題目。"},{"en":"If an actor jokes naturally with reporters, he may seem unusually polished for his age.","zh":"如果演員自然地與記者開玩笑，他可能顯得比同齡人老練。"},{"en":"The phrase compares someone’s public skill to stage comedy.","zh":"這個短語把某人的公開表現能力比作舞台喜劇。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":5},{"front":"be stung by","meaning":"被……刺痛；因……受傷","examples":[{"en":"Radcliffe has never been stung by a bad review.","zh":"Radcliffe 從未因負面評論而受傷。"},{"en":"To be stung by criticism means to feel hurt or upset by it.","zh":"「be stung by」批評，意思是因它而感到受傷或不快。"},{"en":"A student may be stung by a teacher’s harsh comment even if the advice is useful.","zh":"即使建議有用，學生也可能因老師嚴厲評論而受傷。"},{"en":"If someone avoids reading reviews, they may avoid being hurt by negative opinions.","zh":"如果某人避免閱讀評論，他可能避免被負面意見傷害。"},{"en":"The phrase compares emotional pain to a sharp sting.","zh":"這個短語把情感痛楚比作尖銳刺痛。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":5},{"front":"a bad review","meaning":"負面評論","examples":[{"en":"He has never been stung by a bad review.","zh":"他從未因負面評論而受傷。"},{"en":"A bad review is a negative judgement of a film, book, performance or product.","zh":"「a bad review」是對電影、書籍、表演或產品的負面評價。"},{"en":"A restaurant may receive a bad review if service is slow and food is cold.","zh":"如果服務慢且食物冷，餐廳可能收到負面評論。"},{"en":"If actors read bad reviews too closely, their confidence may suffer.","zh":"如果演員太仔細閱讀負面評論，他們的信心可能受影響。"},{"en":"The phrase refers to criticism, not simply a low score.","zh":"這個短語指批評，而不只是低分。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":5},{"front":"an unflattering portrait","meaning":"不討好的描寫","examples":[{"en":"He has not been hurt by an unflattering portrait in the press.","zh":"他沒有被媒體中不討好的描寫傷害。"},{"en":"An unflattering portrait is a description that makes someone look bad or less attractive.","zh":"「an unflattering portrait」是令某人看起來不好或不吸引的描寫。"},{"en":"A newspaper profile can become unflattering if it focuses only on mistakes.","zh":"如果報章人物專訪只集中於錯誤，它可能變成不討好的描寫。"},{"en":"If a young star reads an unflattering portrait, it may damage their confidence.","zh":"如果年輕明星讀到不討好的描寫，它可能傷害其信心。"},{"en":"The phrase refers to a negative public depiction, not an actual painted picture only.","zh":"這個短語指負面的公開描繪，不只是實際畫像。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":5},{"front":"read any of his press","meaning":"閱讀關於自己的媒體報道","examples":[{"en":"Radcliffe has never read any of his press.","zh":"Radcliffe 從未閱讀任何關於自己的媒體報道。"},{"en":"To read any of his press means to read media reports, reviews or articles about himself.","zh":"「read any of his press」意思是閱讀關於自己的媒體報道、評論或文章。"},{"en":"Some singers avoid reading their press because praise and criticism can both affect mood.","zh":"有些歌手避免閱讀自己的媒體報道，因為讚賞和批評都可能影響心情。"},{"en":"If an actor never reads his press, he may stay less affected by public opinion.","zh":"如果演員從不閱讀自己的報道，他可能較少受公眾意見影響。"},{"en":"The phrase refers to media coverage about a person.","zh":"這個短語指關於某人的媒體覆蓋。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":5},{"front":"provide a magic carpet ride into","meaning":"為……提供順利而神奇的過渡","examples":[{"en":"His parents have provided a magic carpet ride into puberty.","zh":"他的父母為他進入青春期提供了順利而神奇的過渡。"},{"en":"To provide a magic carpet ride into something means to make a difficult transition feel smooth and protected.","zh":"「provide a magic carpet ride into」某階段，意思是令困難過渡變得順利而受保護。"},{"en":"A supportive school can provide a smooth ride into secondary education for nervous students.","zh":"有支援的學校可以為緊張學生進入中學提供順利過渡。"},{"en":"If parents protect a child from pressure during puberty, growing up may feel less frightening.","zh":"如果父母在青春期保護孩子免受壓力，成長可能較不令人害怕。"},{"en":"The phrase uses a magical image to describe an unusually easy transition.","zh":"這個短語用神奇意象描述異常順利的過渡。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":5},{"front":"puberty","meaning":"青春期","examples":[{"en":"Radcliffe’s parents protected him as he entered puberty.","zh":"Radcliffe 的父母在他進入青春期時保護他。"},{"en":"Puberty is the stage when a child’s body and emotions begin changing toward adulthood.","zh":"「puberty」是孩子身體和情緒開始向成人階段轉變的時期。"},{"en":"Many students feel awkward during puberty because their bodies and friendships change quickly.","zh":"許多學生在青春期感到尷尬，因為身體和友誼都快速改變。"},{"en":"If a young actor enters puberty in public, media attention can make the stage harder.","zh":"如果年輕演員在公眾視線中進入青春期，媒體關注可能令這階段更困難。"},{"en":"The word refers to a normal but sensitive stage of growing up.","zh":"這個詞指正常但敏感的成長階段。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":6},{"front":"protect someone from","meaning":"保護某人免受……影響","examples":[{"en":"His parents protected him from both praise and criticism.","zh":"他的父母保護他免受讚美和批評影響。"},{"en":"To protect someone from something means to keep them safe from its harm or influence.","zh":"「protect someone from」某事，意思是令某人免受其傷害或影響。"},{"en":"Parents may protect children from online bullying by setting clear internet rules.","zh":"家長可能透過設立清楚網絡規則，保護孩子免受網上欺凌。"},{"en":"If praise and criticism are both extreme, protecting a child from them may help him stay balanced.","zh":"如果讚美和批評都很極端，保護孩子免受它們影響可能幫助他保持平衡。"},{"en":"The phrase shows active care against danger or pressure.","zh":"這個短語顯示主動照顧，以抵抗危險或壓力。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":6},{"front":"the adulation and the evisceration","meaning":"狂熱崇拜和尖刻批評","examples":[{"en":"His parents protected him from the adulation and the evisceration.","zh":"他的父母保護他免受狂熱崇拜和尖刻批評影響。"},{"en":"The adulation and the evisceration means extreme praise and harsh criticism.","zh":"「the adulation and the evisceration」指極端讚美和嚴厲批評。"},{"en":"A famous singer may receive both adulation from fans and evisceration from reviewers.","zh":"著名歌手可能同時收到粉絲的狂熱崇拜和評論家的尖刻批評。"},{"en":"If a young person hears only extreme praise or brutal criticism, their self-image may become unstable.","zh":"如果年輕人只聽到極端讚美或殘酷批評，他的自我形象可能變得不穩。"},{"en":"The phrase contrasts two dangerous extremes of public attention.","zh":"這個短語對比公眾關注的兩個危險極端。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":6},{"front":"reportedly ranked in wealth","meaning":"據報在財富排名中位列","examples":[{"en":"Radcliffe is reportedly ranked in wealth just behind other young Britons.","zh":"Radcliffe 據報在年輕英國人財富排名中位列其他人之後。"},{"en":"Reportedly ranked in wealth means said by reports to have a certain position in a list of rich people.","zh":"「reportedly ranked in wealth」意思是據報在富人名單中有某個排名。"},{"en":"A young entrepreneur may be reportedly ranked among the richest people under thirty.","zh":"年輕創業者可能據報位列三十歲以下最富有人士之一。"},{"en":"If someone is reportedly wealthy, the claim comes from media reports rather than the person directly.","zh":"如果某人據報富有，這個說法來自媒體報道，而不是本人直接透露。"},{"en":"The phrase signals reported information, not confirmed personal disclosure.","zh":"這個短語表示報道所得資料，而不是已確認的個人披露。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":6},{"front":"fellow young Britons","meaning":"其他年輕英國人","examples":[{"en":"Charlotte Church and Prince Harry are fellow young Britons.","zh":"Charlotte Church 和 Prince Harry 是其他年輕英國人。"},{"en":"Fellow young Britons means other young people from Britain.","zh":"「fellow young Britons」意思是其他來自英國的年輕人。"},{"en":"A student studying abroad may meet fellow young Britons at a university event.","zh":"在海外讀書的學生可能在大學活動中遇到其他年輕英國人。"},{"en":"If a report compares one actor with fellow young Britons, it places him in the same national age group.","zh":"如果報道把一名演員與其他年輕英國人比較，它把他放在同一國籍和年齡群體中。"},{"en":"The phrase identifies shared nationality and youth.","zh":"這個短語指出共同國籍和年輕身份。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":6},{"front":"remains blissfully ignorant of","meaning":"對……毫不知情且不以為意","examples":[{"en":"Radcliffe remains blissfully ignorant of his riches.","zh":"Radcliffe 對自己的財富毫不知情且不以為意。"},{"en":"To remain blissfully ignorant of something means to not know about it and not be troubled by not knowing.","zh":"「remain blissfully ignorant of」某事，意思是不知道它，而且不因不知道而煩惱。"},{"en":"A child may remain blissfully ignorant of family bills because parents handle them quietly.","zh":"孩子可能對家庭帳單毫不知情且不以為意，因為父母悄悄處理。"},{"en":"If a young star does not know his exact fortune, money may affect him less.","zh":"如果年輕明星不知道自己的準確財富，金錢可能較少影響他。"},{"en":"The phrase suggests happy unawareness.","zh":"這個短語暗示快樂地不知情。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":6},{"front":"his riches","meaning":"他的財富","examples":[{"en":"Radcliffe says he does not know the exact amount of his riches.","zh":"Radcliffe 說他不知道自己財富的確切數量。"},{"en":"His riches means the large amount of money or wealth he has.","zh":"「his riches」意思是他擁有的大量金錢或財產。"},{"en":"A business owner may keep quiet about his riches to avoid unwanted attention.","zh":"企業主可能對自己的財富保持低調，以避免不必要關注。"},{"en":"If a teenager focuses too much on his riches, money may shape his choices too strongly.","zh":"如果青少年太專注於自己的財富，金錢可能過度塑造他的選擇。"},{"en":"The phrase is more dramatic than simply saying “his money”.","zh":"這個短語比單純說 “his money” 更戲劇化。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":6},{"front":"to be honest","meaning":"老實說","examples":[{"en":"To be honest, Radcliffe does not know how much money he has.","zh":"老實說，Radcliffe 不知道自己有多少錢。"},{"en":"To be honest introduces a sincere or direct statement.","zh":"「to be honest」用來引出真誠或直接的陳述。"},{"en":"To be honest, I did not understand the lesson until I saw a clear example.","zh":"老實說，直到看到清楚例子，我才明白那堂課。"},{"en":"If someone says “to be honest,” they may be preparing to say something plain or surprising.","zh":"如果某人說 “to be honest”，他可能準備說出直接或令人意外的話。"},{"en":"The phrase makes the speaker sound open and frank.","zh":"這個短語令說話者聽起來坦率。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":6},{"front":"at this point","meaning":"到目前這一刻","examples":[{"en":"He does not know how much money he has at this point.","zh":"到目前這一刻，他不知道自己有多少錢。"},{"en":"At this point means at the present moment or stage.","zh":"「at this point」意思是在目前這一刻或階段。"},{"en":"At this point, the project is not finished, but the main research is done.","zh":"到目前這一刻，項目尚未完成，但主要研究已做好。"},{"en":"If a student is still deciding, it is fair to say that no final choice has been made at this point.","zh":"如果學生仍在決定，可以說到目前仍未作出最終選擇。"},{"en":"The phrase marks the current stage, not the final result.","zh":"這個短語標示當前階段，而不是最終結果。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":6},{"front":"in a way","meaning":"某程度上","examples":[{"en":"In a way, Radcliffe thinks it is right not to focus on money.","zh":"某程度上，Radcliffe 認為不專注於金錢是對的。"},{"en":"In a way means partly or from one point of view.","zh":"「in a way」意思是部分而言，或從某個角度來看。"},{"en":"In a way, failing the test helped him because he finally changed his study habits.","zh":"某程度上，考試不及格幫了他，因為他終於改變學習習慣。"},{"en":"If a situation has both good and bad sides, “in a way” helps express a limited view.","zh":"如果情況有好有壞，in a way 可以幫助表達有限角度。"},{"en":"The phrase softens a statement by making it less absolute.","zh":"這個短語透過令說法較不絕對來軟化語氣。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":6},{"front":"affects the way I think about things","meaning":"影響我看待事情的方式","examples":[{"en":"Money does not affect the way Radcliffe thinks about things.","zh":"金錢不影響 Radcliffe 看待事情的方式。"},{"en":"To affect the way someone thinks about things means to change their attitudes, priorities or judgement.","zh":"「affect the way someone thinks about things」意思是改變某人的態度、優先次序或判斷。"},{"en":"Living abroad may affect the way a student thinks about family and independence.","zh":"海外生活可能影響學生看待家庭和獨立的方式。"},{"en":"If money does not affect someone’s thinking, they may stay humble despite wealth.","zh":"如果金錢不影響某人的想法，他即使富有也可能保持謙遜。"},{"en":"The phrase describes influence on mindset.","zh":"這個短語描述對心態的影響。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":6},{"front":"blue eyes lock in","meaning":"藍眼睛直視對方","examples":[{"en":"Radcliffe’s blue eyes lock in without fear.","zh":"Radcliffe 的藍眼睛毫不害怕地直視對方。"},{"en":"Eyes lock in means someone looks directly and steadily at another person.","zh":"「eyes lock in」意思是某人直接而穩定地看着另一人。"},{"en":"During an interview, a confident speaker’s eyes may lock in with the listener’s.","zh":"訪問期間，自信說話者的眼睛可能與聽者直接對視。"},{"en":"If someone maintains direct eye contact, they may seem calm and unafraid.","zh":"如果某人保持直接眼神接觸，他可能顯得冷靜而不害怕。"},{"en":"The phrase describes focused eye contact.","zh":"這個短語描述專注的眼神接觸。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":7},{"front":"without trepidation","meaning":"毫不害怕；毫不怯場","examples":[{"en":"Radcliffe answers questions without trepidation.","zh":"Radcliffe 毫不怯場地回答問題。"},{"en":"Without trepidation means without fear, nervousness or hesitation.","zh":"「without trepidation」意思是沒有恐懼、緊張或猶豫。"},{"en":"A prepared student can enter an oral exam without trepidation.","zh":"準備充分的學生可以毫不害怕地走入口試。"},{"en":"If someone answers awkward questions without trepidation, they seem confident and mature.","zh":"如果某人毫不怯場地回答尷尬問題，他會顯得自信而成熟。"},{"en":"The phrase is formal and highlights calm courage.","zh":"這個短語較正式，強調冷靜勇氣。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":7},{"front":"gives relatively few interviews","meaning":"接受訪問的次數相對較少","examples":[{"en":"Radcliffe gives relatively few interviews.","zh":"Radcliffe 接受訪問的次數相對較少。"},{"en":"To give relatively few interviews means to speak to the media less often than expected.","zh":"「give relatively few interviews」意思是比預期較少與媒體訪談。"},{"en":"A private singer may give relatively few interviews even after a popular album.","zh":"私生活低調的歌手即使推出受歡迎專輯，也可能接受相對較少訪問。"},{"en":"If a celebrity limits interviews, they can protect privacy and avoid overexposure.","zh":"如果名人限制訪問，他們可以保護私隱並避免過度曝光。"},{"en":"The phrase compares the number of interviews with what is normal for fame.","zh":"這個短語把訪問數量與名氣下的正常情況比較。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":7},{"front":"flinch at","meaning":"對……退縮","examples":[{"en":"He does not flinch at potentially awkward questions.","zh":"他不會對可能令人尷尬的問題退縮。"},{"en":"To flinch at something means to react with fear, discomfort or hesitation.","zh":"「flinch at」某事，意思是因恐懼、不舒服或猶豫而退縮。"},{"en":"A confident student does not flinch at difficult grammar questions during class.","zh":"自信學生在課堂上不會對困難文法問題退縮。"},{"en":"If a public figure does not flinch at criticism, people may see him as calm and prepared.","zh":"如果公眾人物面對批評不退縮，人們可能視他為冷靜且有準備。"},{"en":"The phrase describes emotional reaction, not only physical movement.","zh":"這個短語描述情緒反應，不只是身體動作。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":7},{"front":"potentially awkward questions","meaning":"可能令人尷尬的問題","examples":[{"en":"Radcliffe answers potentially awkward questions calmly.","zh":"Radcliffe 冷靜回答可能令人尷尬的問題。"},{"en":"Potentially awkward questions are questions that might make someone embarrassed or uncomfortable.","zh":"「potentially awkward questions」是可能令人尷尬或不舒服的問題。"},{"en":"Asking a job applicant about a gap in employment can be a potentially awkward question.","zh":"問求職者履歷中的空白期，可以是可能令人尷尬的問題。"},{"en":"If someone answers awkward questions calmly, the conversation can remain respectful.","zh":"如果某人冷靜回答尷尬問題，談話仍可以保持尊重。"},{"en":"The phrase shows that a topic may be sensitive even if it is not openly rude.","zh":"這個短語顯示某話題可能敏感，即使並非明顯無禮。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":7},{"front":"millionaire action-figure boy-next-door","meaning":"百萬富翁兼鄰家男孩式動作人偶","examples":[{"en":"The writer describes Radcliffe as a millionaire action-figure boy-next-door.","zh":"作者把 Radcliffe 描述為百萬富翁兼鄰家男孩式動作人偶。"},{"en":"A millionaire action-figure boy-next-door is someone rich and famous who still seems ordinary, friendly and youthful.","zh":"「millionaire action-figure boy-next-door」指富有又有名，但仍顯得普通、友善和年輕的人。"},{"en":"A celebrity may seem boy-next-door if he dresses simply and speaks politely despite wealth.","zh":"如果名人即使富有仍穿着簡單、說話有禮，他可能顯得像鄰家男孩。"},{"en":"If fame and money do not make a young star arrogant, this contrast becomes striking.","zh":"如果名氣和金錢沒有令年輕明星傲慢，這種對比就很突出。"},{"en":"The phrase combines wealth, celebrity image and ordinary charm.","zh":"這個短語結合財富、名人形象和普通親切感。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":7},{"front":"boy-next-door","meaning":"鄰家男孩","examples":[{"en":"Radcliffe gives the impression of a boy-next-door.","zh":"Radcliffe 給人鄰家男孩的印象。"},{"en":"A boy-next-door is a friendly, ordinary and trustworthy young man.","zh":"「boy-next-door」是友善、普通且值得信任的年輕男子。"},{"en":"A schoolmate who is polite, helpful and not showy may seem like a boy-next-door.","zh":"一位有禮、樂於助人又不炫耀的同學，可能像鄰家男孩。"},{"en":"If a celebrity feels like a boy-next-door, fans may see him as approachable.","zh":"如果名人感覺像鄰家男孩，粉絲可能覺得他容易接近。"},{"en":"The phrase suggests normality and warmth rather than glamour.","zh":"這個短語暗示平凡和親切，而不是華麗。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":7},{"front":"trust someone to","meaning":"信任某人去……","examples":[{"en":"You would trust Radcliffe to take your teenage daughter out.","zh":"你會信任 Radcliffe 帶你十多歲的女兒外出。"},{"en":"To trust someone to do something means to believe they will do it safely, responsibly or honestly.","zh":"「trust someone to」做某事，意思是相信他會安全、負責或誠實地完成。"},{"en":"Parents may trust an older sibling to walk a younger child home from school.","zh":"家長可能信任年長兄姐接年幼孩子放學回家。"},{"en":"If someone behaves maturely, people are more willing to trust him with responsibility.","zh":"如果某人表現成熟，人們會更願意信任他承擔責任。"},{"en":"The phrase expresses confidence in someone’s character.","zh":"這個短語表達對某人品格的信心。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":7},{"front":"take someone out for a soda","meaning":"帶某人出去喝汽水","examples":[{"en":"The writer jokes that you would trust him to take your daughter out for a soda.","zh":"作者開玩笑說你會信任他帶你女兒出去喝汽水。"},{"en":"To take someone out for a soda means to go out casually with someone for a simple drink.","zh":"「take someone out for a soda」意思是與某人輕鬆外出喝一杯簡單飲品。"},{"en":"A teenager may ask a classmate out for a soda after school as a harmless date.","zh":"青少年可能放學後約同學出去喝汽水，作為無害約會。"},{"en":"If parents trust a boy to take their daughter out, they see him as safe and polite.","zh":"如果父母信任男孩帶女兒出去，他們視他為安全和有禮。"},{"en":"The phrase sounds innocent and old-fashioned, which adds humour.","zh":"這個短語聽起來天真又有點老派，因此帶有幽默感。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":7},{"front":"striped dress shirt","meaning":"間條恤衫","examples":[{"en":"Radcliffe wears a green striped dress shirt.","zh":"Radcliffe 穿着一件綠色間條恤衫。"},{"en":"A striped dress shirt is a smart shirt with lines running across or down it.","zh":"「striped dress shirt」是有橫線或直線圖案的整齊恤衫。"},{"en":"A student may wear a striped dress shirt for a formal school presentation.","zh":"學生可能在正式學校匯報中穿間條恤衫。"},{"en":"Clothing details can help a writer make a public figure seem more real and ordinary.","zh":"衣着細節可以幫助作者令公眾人物顯得更真實普通。"},{"en":"The phrase describes a specific item of clothing.","zh":"這個短語描述一件特定衣物。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":7},{"front":"his only accessory","meaning":"他唯一的隨行配件","examples":[{"en":"His only accessory is his publicist and family friend.","zh":"他唯一的隨行配件是他的公關人員兼家庭朋友。"},{"en":"His only accessory means the only person or thing accompanying him in a noticeable way.","zh":"「his only accessory」意思是唯一明顯陪伴他的人或物。"},{"en":"A singer arriving without bodyguards but with one assistant might be described as having only one accessory.","zh":"如果歌手到場時沒有保鑣，只有一名助手，可以被形容為只有一件隨行配件。"},{"en":"If a celebrity has few assistants around him, he may seem less showy.","zh":"如果名人身邊助手很少，他可能顯得不浮誇。"},{"en":"The phrase is playful because a person is described like a fashion item.","zh":"這個短語帶玩味，因為它把人描述成時尚配件。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":7},{"front":"publicist","meaning":"公關人員","examples":[{"en":"His publicist attended the interview with him.","zh":"他的公關人員陪同他出席訪問。"},{"en":"A publicist is a person who manages publicity and media relations for a client.","zh":"「publicist」是為客戶管理宣傳和媒體關係的人。"},{"en":"A publicist may arrange interviews, prepare statements and protect a celebrity’s image.","zh":"公關人員可能安排訪問、準備聲明並保護名人形象。"},{"en":"If an actor is young, a publicist can help manage difficult questions from reporters.","zh":"如果演員年紀小，公關人員可以幫助處理記者的困難問題。"},{"en":"The word refers to a professional media helper.","zh":"這個詞指專業媒體協助者。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":8},{"front":"long-time family friend","meaning":"相識多年的家庭朋友","examples":[{"en":"Vanessa Davies is a long-time family friend.","zh":"Vanessa Davies 是相識多年的家庭朋友。"},{"en":"A long-time family friend is someone who has known and been close to a family for many years.","zh":"「long-time family friend」是認識並親近某家庭很多年的人。"},{"en":"A long-time family friend may attend birthdays, weddings and important family events.","zh":"相識多年的家庭朋友可能出席生日、婚禮和重要家庭活動。"},{"en":"If a publicist is also a family friend, the young actor may feel safer during interviews.","zh":"如果公關人員也是家庭朋友，年輕演員在訪問期間可能更安心。"},{"en":"The phrase suggests trust built over time.","zh":"這個短語暗示長時間建立的信任。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":8},{"front":"except for premieres","meaning":"除了首映禮之外","examples":[{"en":"Except for premieres, Radcliffe’s family employs no bodyguards.","zh":"除了首映禮之外，Radcliffe 的家人不聘用保鑣。"},{"en":"Except for premieres means not including special first-showing events.","zh":"「except for premieres」意思是不包括特別首映活動。"},{"en":"Except for exam days, students may wear casual clothes during the summer programme.","zh":"除了考試日之外，學生在暑期課程中可以穿便服。"},{"en":"If bodyguards are used only for premieres, daily life is less heavily protected.","zh":"如果保鑣只在首映禮使用，日常生活就沒有受到那麼嚴密保護。"},{"en":"The phrase introduces an exception to a general statement.","zh":"這個短語引出一般陳述中的例外。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":8},{"front":"employs no bodyguards","meaning":"不聘用保鑣","examples":[{"en":"Radcliffe’s family employs no bodyguards in daily life.","zh":"Radcliffe 的家人在日常生活中不聘用保鑣。"},{"en":"Employs no bodyguards means does not hire security staff for protection.","zh":"「employs no bodyguards」意思是不聘請保安人員作保護。"},{"en":"A local singer may employ no bodyguards because fans are respectful and calm.","zh":"如果粉絲尊重而冷靜，本地歌手可能不聘用保鑣。"},{"en":"If a celebrity’s family employs no bodyguards, they may be trying to keep life normal.","zh":"如果名人家庭不聘用保鑣，他們可能在努力保持生活正常。"},{"en":"The phrase suggests a low level of daily security.","zh":"這個短語暗示日常保安程度較低。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":8},{"front":"according to the actor","meaning":"據這位演員所說","examples":[{"en":"According to the actor, his family does not usually hire bodyguards.","zh":"據這位演員所說，他的家人通常不聘請保鑣。"},{"en":"According to the actor means the information comes from what the actor says.","zh":"「according to the actor」意思是資料來自該演員所說。"},{"en":"According to the teacher, the test will focus mainly on reading skills.","zh":"據老師所說，測驗將主要集中於閱讀技巧。"},{"en":"If a claim is introduced this way, readers know whose statement it is.","zh":"如果說法以這種方式引出，讀者就知道那是誰的陳述。"},{"en":"The phrase identifies the source of information.","zh":"這個短語指出資料來源。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":8},{"front":"at school","meaning":"在學校","examples":[{"en":"At school, the excitement over his presence dies down after a few weeks.","zh":"在學校，因他的出現而起的興奮幾星期後逐漸平息。"},{"en":"At school means in the school environment or during school life.","zh":"「at school」意思是在學校環境中或學校生活期間。"},{"en":"A famous student may attract attention at school for a short time.","zh":"有名的學生可能在學校短時間吸引注意。"},{"en":"If classmates get used to someone’s presence, daily school life becomes normal again.","zh":"如果同學習慣某人的出現，日常校園生活會再次變正常。"},{"en":"The phrase gives the setting of the situation.","zh":"這個短語提供情境場所。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":8},{"front":"the hubbub over","meaning":"關於……的喧鬧；騷動","examples":[{"en":"The hubbub over his presence dies down after a few weeks.","zh":"關於他出現的喧鬧幾星期後逐漸平息。"},{"en":"The hubbub over something means noisy excitement, attention or fuss about it.","zh":"「the hubbub over」某事，意思是圍繞它的吵鬧興奮、關注或騷動。"},{"en":"There was a hubbub over the new cafeteria when it first opened.","zh":"新飯堂剛開放時，引起了一陣喧鬧。"},{"en":"If people get used to a change, the hubbub usually becomes quieter.","zh":"如果人們習慣改變，騷動通常會變得較安靜。"},{"en":"The phrase describes public excitement that may not last.","zh":"這個短語描述可能不會持久的公眾興奮。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":8},{"front":"his presence","meaning":"他的出現；他在場","examples":[{"en":"Students eventually get used to Radcliffe’s presence at school.","zh":"學生最終習慣 Radcliffe 在學校出現。"},{"en":"His presence means the fact that he is there.","zh":"「his presence」意思是他在場這件事。"},{"en":"A new teacher’s presence can make a noisy class behave more carefully.","zh":"新老師在場可以令吵鬧班級行為更小心。"},{"en":"If students get used to a famous classmate’s presence, they may stop staring.","zh":"如果學生習慣有名同學的出現，他們可能停止盯着看。"},{"en":"The phrase focuses on someone being in a place.","zh":"這個短語集中於某人在某地出現。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":8},{"front":"dies down","meaning":"逐漸平息","examples":[{"en":"The hubbub at school dies down after a few weeks.","zh":"學校裡的騷動幾星期後逐漸平息。"},{"en":"Dies down means becomes quieter, weaker or less intense.","zh":"「dies down」意思是變得較安靜、較弱或較不強烈。"},{"en":"The noise in the playground dies down when the bell rings.","zh":"鐘聲響起時，操場上的噪音逐漸平息。"},{"en":"If excitement dies down, people return to normal behaviour.","zh":"如果興奮逐漸平息，人們會回到正常行為。"},{"en":"The phrase often describes noise, emotion or attention becoming calmer.","zh":"這個短語常描述噪音、情緒或關注變得平靜。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":8},{"front":"after a few weeks","meaning":"幾星期後","examples":[{"en":"The excitement usually dies down after a few weeks.","zh":"興奮通常在幾星期後逐漸平息。"},{"en":"After a few weeks means following a short period of several weeks.","zh":"「after a few weeks」意思是在幾個星期這段短時間之後。"},{"en":"A new school routine may feel normal after a few weeks.","zh":"新學校日程可能在幾星期後變得正常。"},{"en":"If attention fades after a few weeks, the situation was probably temporary.","zh":"如果關注在幾星期後淡去，情況可能只是暫時的。"},{"en":"The phrase gives a rough time frame, not an exact date.","zh":"這個短語提供大約時間框架，而不是準確日期。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":8},{"front":"fan interest","meaning":"粉絲關注","examples":[{"en":"Fan interest never became too aggressive.","zh":"粉絲關注從未變得太激烈。"},{"en":"Fan interest means the attention and curiosity fans show toward a celebrity.","zh":"「fan interest」指粉絲對名人的注意和好奇。"},{"en":"Fan interest may include asking for photos, following news or attending events.","zh":"粉絲關注可能包括要求拍照、追蹤新聞或出席活動。"},{"en":"If fan interest becomes too strong, a celebrity may need more security.","zh":"如果粉絲關注變得太強烈，名人可能需要更多保安。"},{"en":"The phrase can be positive or worrying depending on intensity.","zh":"這個短語可正面也可令人擔心，視乎強度。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":8},{"front":"never got too aggressive","meaning":"從未變得太激烈","examples":[{"en":"Fan interest never got too aggressive.","zh":"粉絲關注從未變得太激烈。"},{"en":"Never got too aggressive means never became too forceful, threatening or uncontrolled.","zh":"「never got too aggressive」意思是從未變得太強硬、具威脅或失控。"},{"en":"A classroom debate is healthy if it never gets too aggressive.","zh":"如果課堂辯論從未變得太激烈，它就是健康的。"},{"en":"If fans stay respectful, public attention does not become dangerous.","zh":"如果粉絲保持尊重，公眾關注就不會變得危險。"},{"en":"The phrase shows that a situation stayed within safe limits.","zh":"這個短語顯示情況保持在安全限度內。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":9},{"front":"slightly obsessed","meaning":"有點癡迷的","examples":[{"en":"Some people are slightly obsessed with Radcliffe.","zh":"有些人對 Radcliffe 有點癡迷。"},{"en":"Slightly obsessed means a little too interested in someone or something.","zh":"「slightly obsessed」意思是對某人或某事有點過分感興趣。"},{"en":"A student may be slightly obsessed with a game if he talks about it every lunch break.","zh":"如果學生每個午息都談論同一個遊戲，他可能有點癡迷。"},{"en":"If fan interest becomes obsessive, it may start to feel uncomfortable.","zh":"如果粉絲關注變得癡迷，它可能開始令人不舒服。"},{"en":"The phrase softens the idea of obsession but still suggests too much focus.","zh":"這個短語把 obsession 語氣放輕，但仍暗示過度專注。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":9},{"front":"doesn’t really worry me","meaning":"不太令我擔心","examples":[{"en":"Fan attention does not really worry Radcliffe too much.","zh":"粉絲關注不太令 Radcliffe 擔心。"},{"en":"Doesn’t really worry me means it does not make me feel very anxious or afraid.","zh":"「doesn’t really worry me」意思是它不會令我非常焦慮或害怕。"},{"en":"A small spelling mistake does not really worry a student if the essay is clear.","zh":"如果作文清楚，小拼寫錯誤不太令學生擔心。"},{"en":"If attention stays polite, a celebrity may not feel worried by it.","zh":"如果關注保持有禮，名人可能不會因此擔心。"},{"en":"The phrase sounds calm and mildly reassuring.","zh":"這個短語聽起來冷靜而略帶安撫。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":9},{"front":"as long as","meaning":"只要","examples":[{"en":"He is not worried as long as the attention stays at its current level.","zh":"只要關注保持在目前程度，他就不擔心。"},{"en":"As long as means provided that or only if a condition remains true.","zh":"「as long as」意思是只要某條件仍然成立。"},{"en":"Students may use laptops as long as they do not disturb others.","zh":"只要不打擾別人，學生可以使用手提電腦。"},{"en":"If fan attention stays respectful, it may not become a problem.","zh":"如果粉絲關注保持尊重，它可能不會成為問題。"},{"en":"The phrase introduces the condition that makes something acceptable.","zh":"這個短語引入使某事可接受的條件。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":9},{"front":"stays at the pitch it is now","meaning":"保持在現有程度","examples":[{"en":"Radcliffe is comfortable if fan interest stays at the pitch it is now.","zh":"如果粉絲關注保持在現有程度，Radcliffe 會感到舒服。"},{"en":"Stays at the pitch it is now means remains at the current level or intensity.","zh":"「stays at the pitch it is now」意思是保持在目前水平或強度。"},{"en":"A teacher may be happy if class noise stays at the level it is now.","zh":"如果課堂噪音保持在現有程度，老師可能感到滿意。"},{"en":"If attention becomes louder or more intense, comfort may turn into concern.","zh":"如果關注變得更大或更強烈，舒服可能變成擔心。"},{"en":"The phrase uses “pitch” to mean degree or level.","zh":"這個短語中的 “pitch” 指程度或水平。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":9},{"front":"slightly worrying","meaning":"有點令人擔心的","examples":[{"en":"Occasionally, he meets someone slightly worrying.","zh":"偶爾，他會遇到有點令人擔心的人。"},{"en":"Slightly worrying means causing a small amount of concern or unease.","zh":"「slightly worrying」意思是令人有少量擔心或不安。"},{"en":"A student’s sudden silence may be slightly worrying if he is usually talkative.","zh":"如果平常健談的學生突然沉默，可能有點令人擔心。"},{"en":"If a fan behaves strangely, the situation may become slightly worrying without being dangerous.","zh":"如果粉絲行為奇怪，情況可能有點令人擔心，但不一定危險。"},{"en":"The phrase suggests mild concern, not panic.","zh":"這個短語暗示輕微擔憂，而不是恐慌。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":9},{"front":"feel in danger","meaning":"感到有危險","examples":[{"en":"Radcliffe says he never really feels in danger.","zh":"Radcliffe 說他從未真正感到有危險。"},{"en":"To feel in danger means to feel unsafe or threatened.","zh":"「feel in danger」意思是感到不安全或受威脅。"},{"en":"A child may feel in danger if a stranger follows him on the way home.","zh":"如果陌生人在回家路上跟着孩子，孩子可能感到有危險。"},{"en":"If security is calm and fans are respectful, a celebrity may not feel in danger.","zh":"如果保安冷靜而粉絲有禮，名人可能不會感到有危險。"},{"en":"The phrase describes a personal feeling of risk.","zh":"這個短語描述個人對風險的感受。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":9},{"front":"the security issue","meaning":"安全問題；保障問題","examples":[{"en":"The security issue that absorbs him is his career longevity.","zh":"目前令他關注的保障問題是作為演員的長久發展。"},{"en":"The security issue means the matter connected with safety, protection or long-term stability.","zh":"「the security issue」指與安全、保護或長期穩定有關的問題。"},{"en":"For a school, the security issue may be how visitors enter the building.","zh":"對學校來說，安全問題可能是訪客如何進入校舍。"},{"en":"For an actor, security can also mean protecting a future career, not only physical safety.","zh":"對演員來說，保障也可以指保護未來事業，而不只是身體安全。"},{"en":"The phrase can refer to personal safety or broader protection.","zh":"這個短語可以指人身安全，也可以指更廣義的保護。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":9},{"front":"absorbs him at the moment","meaning":"目前令他關注","examples":[{"en":"Longevity as an actor absorbs him at the moment.","zh":"作為演員的長久發展目前令他關注。"},{"en":"If something absorbs someone, it takes up their attention and thinking.","zh":"如果某事 absorbs 某人，它佔據了他的注意力和思想。"},{"en":"A final exam may absorb a student for several weeks before the test.","zh":"期末考試可能在考前幾星期佔據學生心思。"},{"en":"If career survival absorbs an actor, he is thinking seriously about future roles.","zh":"如果事業長遠發展令演員關注，他就是在認真思考未來角色。"},{"en":"The phrase means the issue currently occupies his mind.","zh":"這個短語意思是該議題目前佔據他的心思。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":9},{"front":"longevity as an actor","meaning":"作為演員的長久發展","examples":[{"en":"Radcliffe is thinking about longevity as an actor.","zh":"Radcliffe 正在思考作為演員的長久發展。"},{"en":"Longevity as an actor means the ability to keep working successfully as an actor for many years.","zh":"「longevity as an actor」指多年持續成功從事演員工作的能力。"},{"en":"A singer may seek career longevity by changing style and protecting her voice.","zh":"歌手可能透過改變風格和保護聲線來追求事業長久發展。"},{"en":"If an actor is known for only one role, career longevity may be harder.","zh":"如果演員只因一個角色出名，事業長久發展可能更難。"},{"en":"The phrase focuses on long-term professional survival.","zh":"這個短語集中於長期職業生存。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":9},{"front":"for the first time since","meaning":"自……以來首次","examples":[{"en":"For the first time since Harry Potter began, he will work on another feature.","zh":"自 Harry Potter 開始以來，他將首次拍攝另一部電影長片。"},{"en":"For the first time since means something has not happened during the period after a previous event until now.","zh":"「for the first time since」意思是自某事件後直到現在，某事首次發生。"},{"en":"For the first time since starting school, a child may spend a whole day away from classmates.","zh":"自開始上學以來，孩子可能首次整天離開同學。"},{"en":"If an actor takes a new role for the first time since a famous series began, it signals a career shift.","zh":"如果演員自著名系列開始以來首次接新角色，這表示事業轉向。"},{"en":"The phrase highlights a break from a long pattern.","zh":"這個短語強調打破長期模式。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":9},{"front":"is set to","meaning":"準備；即將","examples":[{"en":"Radcliffe is set to work on another feature film.","zh":"Radcliffe 準備拍攝另一部電影長片。"},{"en":"Is set to means is scheduled, ready or expected to do something soon.","zh":"「is set to」意思是已安排、準備或預計很快做某事。"},{"en":"The school team is set to play in the final next week.","zh":"學校隊伍即將在下星期參加決賽。"},{"en":"If a film is set to begin shooting, planning has already reached an advanced stage.","zh":"如果電影準備開始拍攝，規劃通常已到較後階段。"},{"en":"The phrase points to an arranged future action.","zh":"這個短語指已安排的未來行動。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":10},{"front":"work on another feature","meaning":"拍攝另一部電影長片","examples":[{"en":"He is set to work on another feature called December Boys.","zh":"他即將拍攝另一部名為《December Boys》的電影長片。"},{"en":"To work on another feature means to take part in making another full-length film.","zh":"「work on another feature」意思是參與製作另一部長片。"},{"en":"An actor may work on another feature during a break between two major series films.","zh":"演員可能在兩部大型系列電影之間的空檔拍攝另一部長片。"},{"en":"If a young star works on another feature, audiences can see him beyond one famous role.","zh":"如果年輕明星拍攝另一部長片，觀眾可以在一個著名角色以外看見他。"},{"en":"The phrase refers to film work, not a short school video.","zh":"這個短語指電影工作，而不是學校短片。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":10},{"front":"a coming-of-age tale","meaning":"成長故事","examples":[{"en":"December Boys is a coming-of-age tale.","zh":"《December Boys》是一個成長故事。"},{"en":"A coming-of-age tale is a story about a young person growing emotionally and becoming more mature.","zh":"「a coming-of-age tale」是關於年輕人在情感上成長並變得更成熟的故事。"},{"en":"A novel about a teenager learning responsibility after leaving home can be a coming-of-age tale.","zh":"一本關於青少年離家後學習責任的小說，可以是成長故事。"},{"en":"If a story shows someone moving from innocence to experience, it often belongs to this type.","zh":"如果故事展示某人從天真走向經驗，它通常屬於這種類型。"},{"en":"The phrase focuses on emotional growth, not just getting older.","zh":"這個短語集中於情感成長，而不只是年紀增長。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":10},{"front":"plays an orphan","meaning":"飾演孤兒","examples":[{"en":"Radcliffe plays an orphan in December Boys.","zh":"Radcliffe 在《December Boys》中飾演孤兒。"},{"en":"To play an orphan means to act as a character whose parents are dead or absent.","zh":"「play an orphan」意思是飾演父母已去世或不在身邊的角色。"},{"en":"A student in a school play may play an orphan who is looking for a new family.","zh":"學生在學校話劇中可能飾演尋找新家庭的孤兒。"},{"en":"If an actor plays an orphan, the role may involve loneliness, independence or longing.","zh":"如果演員飾演孤兒，角色可能涉及孤獨、獨立或渴望。"},{"en":"The phrase describes the character role an actor performs.","zh":"這個短語描述演員表演的角色身份。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":10},{"front":"begins shooting","meaning":"開始拍攝","examples":[{"en":"The film begins shooting in Australia in December.","zh":"該電影十二月在澳洲開始拍攝。"},{"en":"Begins shooting means starts filming.","zh":"「begins shooting」意思是開始拍攝。"},{"en":"A school documentary begins shooting once students have written the plan and found locations.","zh":"學校紀錄片在學生寫好計劃並找到地點後開始拍攝。"},{"en":"If a film begins shooting, actors and crew move from preparation to actual filming.","zh":"如果電影開始拍攝，演員和工作人員就從準備進入實際拍攝。"},{"en":"The phrase belongs to film production schedules.","zh":"這個短語屬於電影製作時間表。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":10},{"front":"taking a cue from","meaning":"參照；仿效","examples":[{"en":"Radcliffe is taking a cue from one of his idols.","zh":"Radcliffe 正在參照他的其中一位偶像。"},{"en":"To take a cue from someone means to follow their example or learn from what they do.","zh":"「take a cue from」某人，意思是跟隨其榜樣或從其行為中學習。"},{"en":"A student may take a cue from a calm classmate and speak more slowly during a presentation.","zh":"學生可能參照冷靜同學的做法，在匯報時說得更慢。"},{"en":"If a young actor admires an older actor’s career, he may copy some career choices.","zh":"如果年輕演員欣賞年長演員的事業，他可能仿效一些事業選擇。"},{"en":"The phrase suggests guidance through example.","zh":"這個短語暗示透過榜樣獲得指引。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":10},{"front":"one of his idols","meaning":"他的其中一位偶像","examples":[{"en":"Gary Oldman is one of Radcliffe’s idols.","zh":"Gary Oldman 是 Radcliffe 的其中一位偶像。"},{"en":"One of his idols means one person he greatly admires and wants to learn from.","zh":"「one of his idols」意思是他非常仰慕並想學習的人之一。"},{"en":"A young footballer may call a famous striker one of his idols.","zh":"年輕足球員可能稱著名前鋒為他的其中一位偶像。"},{"en":"If someone follows an idol’s career path, admiration may shape future decisions.","zh":"如果某人跟隨偶像的事業路線，崇拜可能影響未來決定。"},{"en":"The phrase identifies a role model.","zh":"這個短語指出榜樣人物。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":10},{"front":"plays Harry’s godfather","meaning":"飾演哈利的教父","examples":[{"en":"Gary Oldman plays Harry’s godfather Sirius Black.","zh":"Gary Oldman 飾演哈利的教父 Sirius Black。"},{"en":"To play Harry’s godfather means to act as the character who is Harry’s godfather.","zh":"「plays Harry’s godfather」意思是飾演哈利教父這個角色。"},{"en":"In a school play, an older student may play the hero’s uncle or guardian.","zh":"在學校話劇中，較年長學生可能飾演主角的叔叔或監護人。"},{"en":"If an actor plays a mentor figure, the role may influence younger actors around him.","zh":"如果演員飾演導師型人物，該角色可能影響身邊年輕演員。"},{"en":"The phrase describes both the actor’s role and the character’s relationship.","zh":"這個短語同時描述演員角色和人物關係。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":10},{"front":"forge various on-screen personas","meaning":"塑造不同銀幕形象","examples":[{"en":"Radcliffe wants to forge various on-screen personas.","zh":"Radcliffe 想塑造不同銀幕形象。"},{"en":"To forge various on-screen personas means to build different acting identities in films.","zh":"「forge various on-screen personas」意思是在電影中建立不同演員身份或形象。"},{"en":"An actor may forge a comic persona in one film and a serious persona in another.","zh":"演員可能在一部電影中塑造喜劇形象，在另一部中塑造嚴肅形象。"},{"en":"If a young star creates different screen identities, audiences may stop seeing him as only one role.","zh":"如果年輕明星創造不同銀幕身份，觀眾可能不再只把他看成一個角色。"},{"en":"The phrase focuses on shaping a varied acting image.","zh":"這個短語集中於塑造多樣化演藝形象。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":10},{"front":"complete the series","meaning":"完成整個系列","examples":[{"en":"Radcliffe does not want to complete the series without doing other roles.","zh":"Radcliffe 不想在沒有做其他角色的情況下完成整個系列。"},{"en":"To complete the series means to finish all parts of a film, book or story sequence.","zh":"「complete the series」意思是完成電影、書籍或故事系列的所有部分。"},{"en":"A student may complete a book series after reading every volume.","zh":"學生讀完每一冊後，就完成整個書籍系列。"},{"en":"If an actor completes a famous series without other work, the public may connect him only with that character.","zh":"如果演員完成著名系列而沒有其他作品，公眾可能只把他與那個角色連在一起。"},{"en":"The phrase marks finishing the whole set.","zh":"這個短語標示完成整套作品。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":10},{"front":"without having done anything else","meaning":"沒有做過其他事情","examples":[{"en":"He worries about finishing Harry Potter without having done anything else.","zh":"他擔心在沒有做過其他事情的情況下完成 Harry Potter。"},{"en":"Without having done anything else means without gaining any other experience or achievement.","zh":"「without having done anything else」意思是沒有取得其他經驗或成就。"},{"en":"A student may worry about graduating without having tried any club or activity.","zh":"學生可能擔心畢業時沒有參加過任何社團或活動。"},{"en":"If an actor has done only one role, future casting may become more difficult.","zh":"如果演員只做過一個角色，未來選角可能更困難。"},{"en":"The phrase shows concern about being too narrowly defined.","zh":"這個短語顯示對被過分狹窄定義的擔心。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":10},{"front":"during that time","meaning":"在那段期間","examples":[{"en":"He wants to take other roles during that time.","zh":"他想在那段期間接其他角色。"},{"en":"During that time means within the period already being discussed.","zh":"「during that time」意思是在已討論的那段時間內。"},{"en":"A student may study for exams in May; during that time, she may stop using social media.","zh":"學生可能在五月準備考試；在那段期間，她可能停止使用社交媒體。"},{"en":"If an actor works on another film during a series, he can broaden his experience.","zh":"如果演員在系列期間拍另一部電影，他可以擴闊經驗。"},{"en":"The phrase links an action to a specific period.","zh":"這個短語把行動連到特定時期。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":11},{"front":"be seen as anything else","meaning":"被視為其他角色","examples":[{"en":"Radcliffe wants to be seen as something other than Harry Potter.","zh":"Radcliffe 想被視為 Harry Potter 以外的其他角色。"},{"en":"To be seen as anything else means to be recognised in a different way or role.","zh":"「be seen as anything else」意思是以不同方式或角色被認識。"},{"en":"A teacher who writes music may want to be seen as more than just a teacher.","zh":"會寫音樂的老師可能想被視為不只是老師。"},{"en":"If audiences see an actor only as one character, career growth may be limited.","zh":"如果觀眾只把演員看作一個角色，事業發展可能受限。"},{"en":"The phrase describes a desire for a broader identity.","zh":"這個短語描述對更廣闊身份的渴望。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":11},{"front":"showing people","meaning":"向人展示","examples":[{"en":"He wants to show people he can do other things.","zh":"他想向人展示自己能做其他事情。"},{"en":"Showing people something means proving or demonstrating it to others.","zh":"「showing people」某事，意思是向他人證明或展示它。"},{"en":"A student may show people she is serious by arriving early and finishing work on time.","zh":"學生可能透過早到和準時完成功課，向人展示自己是認真的。"},{"en":"If an actor chooses a different role, he can show people a wider range of skills.","zh":"如果演員選擇不同角色，他可以向人展示更廣泛技能。"},{"en":"The phrase focuses on changing others’ view through action.","zh":"這個短語集中於透過行動改變他人看法。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":11},{"front":"do other things","meaning":"做其他事情","examples":[{"en":"Radcliffe wants to prove that he can do other things.","zh":"Radcliffe 想證明自己能做其他事情。"},{"en":"To do other things means to take on different activities, roles or challenges.","zh":"「do other things」意思是承擔不同活動、角色或挑戰。"},{"en":"A student known only for sports may want to do other things, such as music or debating.","zh":"只因運動出名的學生可能想做其他事情，例如音樂或辯論。"},{"en":"If someone does other things successfully, people stop limiting them to one identity.","zh":"如果某人成功做其他事情，人們就不再把他限制在一種身份中。"},{"en":"The phrase suggests variety beyond the familiar role.","zh":"這個短語暗示超越熟悉角色的多樣性。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":11},{"front":"at the moment","meaning":"目前","examples":[{"en":"At the moment, Radcliffe is preparing for the fifth Potter film.","zh":"目前，Radcliffe 正在準備第五部 Harry Potter 電影。"},{"en":"At the moment means right now or at the present time.","zh":"「at the moment」意思是現在或目前。"},{"en":"At the moment, the library is closed for renovation.","zh":"目前，圖書館因翻新而關閉。"},{"en":"If someone is busy at the moment, their plans may change later.","zh":"如果某人目前很忙，他的計劃之後可能改變。"},{"en":"The phrase marks the current situation, not a permanent state.","zh":"這個短語標示當前情況，而不是永久狀態。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":11},{"front":"preparing for","meaning":"正在準備","examples":[{"en":"Radcliffe is preparing for the fifth Potter edition.","zh":"Radcliffe 正在準備第五部 Harry Potter 電影。"},{"en":"Preparing for something means getting ready for it.","zh":"「preparing for」某事，意思是為它作準備。"},{"en":"Students prepare for an oral exam by practising answers aloud.","zh":"學生透過大聲練習答案來準備口試。"},{"en":"If an actor is preparing for a film, he may study the script, rehearse and plan his schedule.","zh":"如果演員正在準備電影，他可能研究劇本、排練並安排時間表。"},{"en":"The phrase points to work done before the main event.","zh":"這個短語指出主要事件前所做的工作。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":11},{"front":"the fifth Potter edition","meaning":"第五部哈利波特電影","examples":[{"en":"He is preparing for the fifth Potter edition.","zh":"他正在準備第五部 Harry Potter 電影。"},{"en":"The fifth Potter edition means the fifth film or instalment in the Harry Potter series.","zh":"「the fifth Potter edition」意思是 Harry Potter 系列中的第五部電影或作品。"},{"en":"A reader may wait for the fifth edition of a favourite book series after finishing the fourth.","zh":"讀者讀完第四冊後，可能等待最愛書系的第五部。"},{"en":"If a film series reaches its fifth part, actors may already have spent years with the same characters.","zh":"如果電影系列來到第五部，演員可能已與同一角色相處多年。"},{"en":"The phrase identifies a numbered part of the series.","zh":"這個短語指出系列中的編號部分。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":11},{"front":"requires him to","meaning":"要求他","examples":[{"en":"The filming requires him to take tutoring at the studio.","zh":"拍攝要求他在片場接受私人補習。"},{"en":"Requires him to means makes it necessary for him to do something.","zh":"「requires him to」意思是使他有必要做某事。"},{"en":"A scholarship may require a student to keep good grades.","zh":"獎學金可能要求學生保持良好成績。"},{"en":"If filming requires tutoring, school lessons must fit around the work schedule.","zh":"如果拍攝要求補習，學校課業就必須配合工作時間表。"},{"en":"The phrase shows an obligation or necessary condition.","zh":"這個短語顯示義務或必要條件。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":11},{"front":"take tutoring","meaning":"接受私人補習","examples":[{"en":"Radcliffe takes tutoring at the Leavesden Studios.","zh":"Radcliffe 在 Leavesden Studios 接受私人補習。"},{"en":"To take tutoring means to receive private teaching or academic support.","zh":"「take tutoring」意思是接受私人教學或學業支援。"},{"en":"A student may take tutoring in maths before an important exam.","zh":"學生可能在重要考試前接受數學補習。"},{"en":"If a child actor misses normal school hours, tutoring can help maintain schoolwork.","zh":"如果童星錯過正常上課時間，私人補習可以幫助維持學業。"},{"en":"The phrase describes extra learning support.","zh":"這個短語描述額外學習支援。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":11},{"front":"aged out of","meaning":"因年齡增長而不再受……限制","examples":[{"en":"He has aged out of many child labour restrictions.","zh":"他因年齡增長而不再受許多童工限制約束。"},{"en":"To age out of rules means to become too old for those rules to apply.","zh":"「age out of」規則，意思是因年齡太大而不再適用那些規則。"},{"en":"A teenager may age out of a children’s sports league when he turns sixteen.","zh":"青少年滿十六歲時，可能因年齡增長而不能再參加兒童運動聯賽。"},{"en":"If a young actor ages out of child labour rules, filming hours may become longer.","zh":"如果年輕演員不再受童工規則限制，拍攝時間可能變長。"},{"en":"The phrase links age with losing or leaving a category.","zh":"這個短語把年齡與離開某類別連繫起來。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":11},{"front":"restrictions of child labour laws","meaning":"童工法限制","examples":[{"en":"He has aged out of many restrictions of child labour laws.","zh":"他已因年齡增長而不再受許多童工法限制。"},{"en":"Restrictions of child labour laws are legal limits that protect children from excessive work.","zh":"「restrictions of child labour laws」是保護兒童免受過度工作的法律限制。"},{"en":"Child labour laws may limit how many hours a young actor can work each day.","zh":"童工法可能限制年輕演員每天可以工作多少小時。"},{"en":"If those restrictions no longer apply, a production schedule may become more demanding.","zh":"如果那些限制不再適用，製作時間表可能變得更吃力。"},{"en":"The phrase refers to legal protection for working children.","zh":"這個短語指對工作兒童的法律保護。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":11},{"front":"determined to stick to","meaning":"決心堅持","examples":[{"en":"Radcliffe is determined to stick to his old schedule.","zh":"Radcliffe 決心堅持他原有的時間表。"},{"en":"To be determined to stick to something means to firmly decide to continue following it.","zh":"「determined to stick to」某事，意思是堅定決定繼續遵循它。"},{"en":"A student may be determined to stick to a revision timetable until exams finish.","zh":"學生可能決心堅持溫習時間表直到考試結束。"},{"en":"If someone sticks to a balanced schedule, work and study may suffer less.","zh":"如果某人堅持平衡時間表，工作和學業可能較少受影響。"},{"en":"The phrase shows strong commitment to a plan.","zh":"這個短語顯示對計劃的強烈承諾。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":12},{"front":"his old schedule","meaning":"他原有的時間表","examples":[{"en":"He wants to keep his old filming and study schedule.","zh":"他想保留原有的拍攝和學習時間表。"},{"en":"His old schedule means the routine or timetable he used before.","zh":"「his old schedule」指他以前使用的日程或時間表。"},{"en":"A student may return to his old schedule after a school holiday ends.","zh":"學生可能在假期結束後回到原有時間表。"},{"en":"If a schedule has worked well, keeping it can protect balance and discipline.","zh":"如果某時間表一直有效，保留它可以保護平衡和紀律。"},{"en":"The phrase refers to a familiar routine, not necessarily an outdated one.","zh":"這個短語指熟悉日程，不一定是過時安排。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":12},{"front":"typically takes","meaning":"通常需要","examples":[{"en":"Each film typically takes 11 months to finish.","zh":"每部電影通常需要11個月完成。"},{"en":"Typically takes means usually needs a certain amount of time.","zh":"「typically takes」意思是通常需要某段時間。"},{"en":"A school project typically takes two weeks if students collect data and write a report.","zh":"如果學生要收集數據並寫報告，學校項目通常需要兩星期。"},{"en":"If a film typically takes almost a year, actors must plan study and rest carefully.","zh":"如果電影通常需要接近一年，演員必須仔細安排學習和休息。"},{"en":"The phrase describes a normal time requirement.","zh":"這個短語描述正常時間需求。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":12},{"front":"too intense","meaning":"太緊湊；太吃力","examples":[{"en":"Radcliffe thinks the schedule would be too intense.","zh":"Radcliffe 認為時間表會太緊湊。"},{"en":"Too intense means too demanding, tiring or difficult to handle.","zh":"「too intense」意思是太高要求、太疲累或太難應付。"},{"en":"A student may find three exams in one day too intense.","zh":"學生可能覺得一天三個考試太吃力。"},{"en":"If filming and schoolwork happen at the same time, the pressure may become too intense.","zh":"如果拍攝和學業同時進行，壓力可能變得太大。"},{"en":"The phrase shows that the level of pressure is excessive.","zh":"這個短語顯示壓力程度過高。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":12},{"front":"at the same time","meaning":"同時","examples":[{"en":"He does not want too much school and filming at the same time.","zh":"他不想同時有太多學業和拍攝。"},{"en":"At the same time means during the same period or simultaneously.","zh":"「at the same time」意思是在同一段時間或同時進行。"},{"en":"A student may struggle if she works part-time and prepares for exams at the same time.","zh":"如果學生同時兼職和準備考試，她可能會吃力。"},{"en":"If two demanding responsibilities happen together, both may become harder.","zh":"如果兩項高要求責任同時發生，兩者都可能變得更難。"},{"en":"The phrase points to overlapping activities.","zh":"這個短語指活動時間重疊。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":12},{"front":"would suffer","meaning":"會受影響","examples":[{"en":"Both his performance and schoolwork would suffer.","zh":"他的表現和學業都會受影響。"},{"en":"Would suffer means would become worse or be harmed.","zh":"「would suffer」意思是會變差或受損。"},{"en":"A student’s sleep would suffer if he studied until 3 a.m. every night.","zh":"如果學生每晚讀到凌晨三點，他的睡眠會受影響。"},{"en":"If an actor takes on too much work, acting quality and health may suffer.","zh":"如果演員承擔太多工作，演技質素和健康都可能受影響。"},{"en":"The phrase shows a negative result of too much pressure.","zh":"這個短語顯示過大壓力的負面結果。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":12},{"front":"schoolwork","meaning":"學業；功課","examples":[{"en":"His schoolwork would suffer if the schedule became too intense.","zh":"如果時間表變得太緊湊，他的學業會受影響。"},{"en":"Schoolwork means the study tasks, homework and academic responsibilities students must complete.","zh":"「schoolwork」指學生必須完成的學習任務、功課和學業責任。"},{"en":"A student’s schoolwork may include reading, essays, projects and exam revision.","zh":"學生的學業可能包括閱讀、作文、專題研習和考試溫習。"},{"en":"If filming takes too much time, schoolwork may fall behind.","zh":"如果拍攝佔太多時間，學業可能落後。"},{"en":"The word focuses on learning duties, not school friendships.","zh":"這個詞集中於學習責任，而不是校園友誼。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":12},{"front":"prepared to follow","meaning":"準備遵循","examples":[{"en":"Radcliffe is prepared to follow the same routine for another film.","zh":"Radcliffe 準備為另一部電影遵循相同日程。"},{"en":"Prepared to follow means willing and ready to continue using a plan or routine.","zh":"「prepared to follow」意思是願意並準備繼續使用某計劃或流程。"},{"en":"A patient may be prepared to follow a strict diet if it improves health.","zh":"如果嚴格飲食能改善健康，病人可能準備遵循它。"},{"en":"If a routine protects balance, someone may be willing to repeat it.","zh":"如果某流程能保持平衡，人們可能願意重複使用。"},{"en":"The phrase shows readiness and acceptance.","zh":"這個短語顯示準備和接受。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":12},{"front":"the same routine","meaning":"相同日程；相同安排","examples":[{"en":"He may follow the same routine for the sixth film.","zh":"他可能為第六部電影遵循相同安排。"},{"en":"The same routine means the same regular pattern of activities.","zh":"「the same routine」意思是相同的定期活動模式。"},{"en":"A student may keep the same routine every morning: breakfast, bus, school and revision.","zh":"學生可能每天早上保持相同日程：早餐、乘巴士、上學和溫習。"},{"en":"If a routine works well, repeating it can reduce stress and confusion.","zh":"如果某日程有效，重複使用可以減少壓力和混亂。"},{"en":"The phrase refers to repeated organisation of time and actions.","zh":"這個短語指時間和行動上的重複安排。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":12},{"front":"if called upon to","meaning":"如果被邀請去","examples":[{"en":"Radcliffe may continue if called upon to do the sixth film.","zh":"如果被邀請拍第六部電影，Radcliffe 可能會繼續。"},{"en":"If called upon to do something means if asked or required to do it.","zh":"「if called upon to」做某事，意思是如果被要求或邀請去做。"},{"en":"A teacher may help at a school event if called upon to supervise students.","zh":"如果被要求監督學生，老師可能在學校活動中幫忙。"},{"en":"If an actor is called upon to return to a role, he must decide whether to accept.","zh":"如果演員被邀請回歸某角色，他必須決定是否接受。"},{"en":"The phrase sounds formal and suggests being invited or asked for service.","zh":"這個短語較正式，暗示被邀請或被要求提供服務。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":12},{"front":"ultimately","meaning":"最終","examples":[{"en":"Ultimately, the decision comes down to whether he wants to do it.","zh":"最終，決定歸結為他是否想做。"},{"en":"Ultimately means in the end or after considering everything.","zh":"「ultimately」意思是最後，或在考慮所有事情後。"},{"en":"Ultimately, a student must choose the subject that fits her goals best.","zh":"最終，學生必須選擇最符合自己目標的科目。"},{"en":"If many factors matter, the final decision may still depend on personal willingness.","zh":"即使許多因素重要，最後決定可能仍取決於個人意願。"},{"en":"The word signals the final and most important point.","zh":"這個詞表示最後和最重要的一點。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":12},{"front":"comes down to","meaning":"歸結為","examples":[{"en":"The choice comes down to whether he feels like doing it.","zh":"選擇歸結為他是否想做這件事。"},{"en":"Comes down to means is finally decided by one main factor.","zh":"「comes down to」意思是最終由一個主要因素決定。"},{"en":"Choosing a school may come down to distance if two schools are equally good.","zh":"如果兩所學校一樣好，選校可能歸結為距離。"},{"en":"If all practical problems are solved, a decision may come down to personal desire.","zh":"如果所有實際問題都解決，決定可能歸結為個人意願。"},{"en":"The phrase simplifies a complex choice to its key issue.","zh":"這個短語把複雜選擇簡化為關鍵問題。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":13},{"front":"feel like doing it","meaning":"想做這件事","examples":[{"en":"Radcliffe will decide whether he feels like doing it.","zh":"Radcliffe 會決定自己是否想做這件事。"},{"en":"To feel like doing something means to want to do it or feel willing to do it.","zh":"「feel like doing」某事，意思是想做或願意做它。"},{"en":"A student may not feel like studying after a long day, even if exams are near.","zh":"漫長一天後，即使考試快到，學生也可能不想溫習。"},{"en":"If an actor does not feel like taking a role, the performance may lack energy.","zh":"如果演員不想接某角色，表演可能缺乏能量。"},{"en":"The phrase is informal and focuses on personal desire.","zh":"這個短語較口語，集中於個人意願。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":13},{"front":"a great script","meaning":"出色劇本","examples":[{"en":"He may continue if the film has a great script.","zh":"如果電影有出色劇本，他可能會繼續。"},{"en":"A great script is a well-written plan for a film or play, including dialogue and scenes.","zh":"「a great script」是寫得很好的電影或戲劇文本，包括對白和場景。"},{"en":"A school play needs a clear script so actors know what to say and do.","zh":"學校話劇需要清楚劇本，演員才知道要說什麼和做什麼。"},{"en":"If a script is strong, an actor may feel challenged and excited by the role.","zh":"如果劇本強，演員可能覺得角色有挑戰性並感到興奮。"},{"en":"The phrase focuses on story and writing quality.","zh":"這個短語集中於故事和寫作質素。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":13},{"front":"will challenge me","meaning":"會挑戰我","examples":[{"en":"Radcliffe wants a role that will challenge him.","zh":"Radcliffe 想要一個會挑戰他的角色。"},{"en":"A role that will challenge someone will test their ability and push them to improve.","zh":"「will challenge me」的角色會考驗某人的能力並推動他進步。"},{"en":"A student may choose a difficult project because it will challenge her research skills.","zh":"學生可能選擇困難專題，因為它會挑戰她的研究能力。"},{"en":"If a role is too easy, an actor may not grow professionally.","zh":"如果角色太容易，演員可能無法在專業上成長。"},{"en":"The phrase suggests meaningful difficulty, not impossible pressure.","zh":"這個短語暗示有意義的困難，而不是不可能承受的壓力。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":13},{"front":"there’s no reason for me not to","meaning":"我沒有理由不……","examples":[{"en":"If the role is challenging, there is no reason for him not to do it.","zh":"如果角色有挑戰性，他沒有理由不做。"},{"en":"There’s no reason for me not to means I see no good reason to refuse.","zh":"「there’s no reason for me not to」意思是我看不到拒絕的好理由。"},{"en":"If the course is useful and affordable, there is no reason for a student not to join.","zh":"如果課程有用又負擔得起，學生沒有理由不參加。"},{"en":"If a role is well written and fits an actor’s goals, refusing may make little sense.","zh":"如果角色寫得好並符合演員目標，拒絕可能沒什麼道理。"},{"en":"The phrase expresses strong openness to an opportunity.","zh":"這個短語表達對機會的強烈開放態度。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":13},{"front":"an amazing part","meaning":"非常精彩的角色","examples":[{"en":"The sixth book would provide an amazing part for him.","zh":"第六本書會為他提供一個非常精彩的角色。"},{"en":"An amazing part is an exciting, impressive or rewarding acting role.","zh":"「an amazing part」是令人興奮、印象深刻或值得演出的角色。"},{"en":"A school play may give a quiet student an amazing part that lets her show confidence.","zh":"學校話劇可能給安靜學生一個精彩角色，讓她展示自信。"},{"en":"If a role has emotional depth and action, an actor may see it as an amazing part.","zh":"如果角色有情感深度和動作場面，演員可能把它視為精彩角色。"},{"en":"The phrase praises the quality of a role.","zh":"這個短語稱讚角色的質素。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":13},{"front":"a long way away","meaning":"還有很長時間","examples":[{"en":"The sixth film was still a long way away.","zh":"第六部電影仍然還有很長時間才到。"},{"en":"A long way away means far in the future or not happening soon.","zh":"「a long way away」意思是在很遠的未來，或不會很快發生。"},{"en":"Graduation may feel a long way away for a student in the first year.","zh":"對一年級學生來說，畢業可能感覺還有很長時間。"},{"en":"If a project is still a long way away, decisions do not need to be final yet.","zh":"如果項目仍然很久之後才發生，決定未必需要現在定案。"},{"en":"The phrase can refer to time, not only distance.","zh":"這個短語可以指時間，而不只是距離。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":13},{"front":"puts someone through his paces","meaning":"讓某人充分展示本領","examples":[{"en":"The fourth film puts Radcliffe through his paces.","zh":"第四部電影讓 Radcliffe 充分展示本領。"},{"en":"To put someone through his paces means to test someone’s ability thoroughly.","zh":"「put someone through his paces」意思是全面測試某人的能力。"},{"en":"A coach may put a new player through his paces during the first training session.","zh":"教練可能在第一次訓練中讓新球員充分展示本領。"},{"en":"If a film includes action, emotion and difficult scenes, it can fully test an actor.","zh":"如果電影包含動作、情感和困難場面，它可以全面考驗演員。"},{"en":"The phrase suggests a demanding test of skill.","zh":"這個短語暗示對技能的高要求測試。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":13},{"front":"hormonally charged setting","meaning":"充滿青春期情緒的環境","examples":[{"en":"The film places Radcliffe in a hormonally charged setting.","zh":"該電影把 Radcliffe 放在充滿青春期情緒的環境中。"},{"en":"A hormonally charged setting is a situation full of teenage emotions, attraction and tension.","zh":"「hormonally charged setting」是充滿青少年情緒、吸引和緊張的情境。"},{"en":"A school dance can become hormonally charged when students are nervous about romance and appearance.","zh":"當學生對戀愛和外表感到緊張，學校舞會可能變成充滿青春期情緒的場景。"},{"en":"If a film shows adolescence honestly, emotions may feel awkward and intense.","zh":"如果電影真實呈現青春期，情緒可能顯得尷尬而強烈。"},{"en":"The phrase points to puberty-related feelings in the story.","zh":"這個短語指故事中的青春期相關感受。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":13},{"front":"crafted it first as","meaning":"首先把它塑造成","examples":[{"en":"Newell crafted the film first as a thriller.","zh":"Newell 首先把該電影塑造成驚慄片。"},{"en":"Crafted it first as means shaped or designed it mainly as that type of work at the beginning.","zh":"「crafted it first as」意思是起初主要把它塑造或設計成某種類型。"},{"en":"A teacher may craft a lesson first as a game before adding formal grammar practice.","zh":"老師可能先把課堂設計成遊戲，再加入正式文法練習。"},{"en":"If a director crafts a fantasy film as a thriller, the story may feel darker and more tense.","zh":"如果導演把奇幻電影塑造成驚慄片，故事可能感覺更黑暗和緊張。"},{"en":"The phrase focuses on creative design and genre.","zh":"這個短語集中於創作設計和類型。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":13},{"front":"a thriller","meaning":"驚慄片","examples":[{"en":"The director treated the film partly as a thriller.","zh":"導演部分把該電影視為驚慄片。"},{"en":"A thriller is a story designed to create suspense, fear or excitement.","zh":"「a thriller」是旨在製造懸念、恐懼或刺激的故事。"},{"en":"A film about a missing student and a race against time could be a thriller.","zh":"關於失蹤學生和爭分奪秒尋人的電影可以是驚慄片。"},{"en":"If a fantasy film includes danger and suspense, it may also feel like a thriller.","zh":"如果奇幻電影包含危險和懸念，它也可能感覺像驚慄片。"},{"en":"The phrase names a genre built around tension.","zh":"這個短語指出以緊張感為核心的類型。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":13},{"front":"pitting someone against","meaning":"使某人與……對抗","examples":[{"en":"The film pits Harry against Lord Voldemort.","zh":"該電影使 Harry 與 Lord Voldemort 對抗。"},{"en":"To pit someone against someone else means to place them in direct conflict or competition.","zh":"「pit someone against」另一人，意思是把他們放入直接衝突或競爭中。"},{"en":"A debate competition may pit two strong students against each other.","zh":"辯論比賽可能讓兩名強學生互相對抗。"},{"en":"If a story pits the hero against a powerful enemy, tension increases.","zh":"如果故事讓英雄與強大敵人對抗，緊張感會增加。"},{"en":"The phrase shows opposition between two sides.","zh":"這個短語顯示兩方之間的對立。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":14},{"front":"budding sorcery prodigy","meaning":"初露頭角的魔法神童","examples":[{"en":"Harry is portrayed as a budding sorcery prodigy.","zh":"Harry 被描繪為初露頭角的魔法神童。"},{"en":"A budding sorcery prodigy is a young person beginning to show extraordinary magical talent.","zh":"「budding sorcery prodigy」是開始展現非凡魔法才能的年輕人。"},{"en":"A child pianist who plays advanced music early may be called a budding musical prodigy.","zh":"很小就能彈高難度音樂的兒童鋼琴家，可能被稱為初露頭角的音樂神童。"},{"en":"If a young character shows rare talent, readers expect that talent to grow.","zh":"如果年輕角色展現罕見才能，讀者會期待那種才能成長。"},{"en":"The phrase combines early development with exceptional ability.","zh":"這個短語結合早期發展和非凡能力。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":14},{"front":"has not appeared since","meaning":"自……以來沒有出現","examples":[{"en":"Lord Voldemort has not appeared since killing Harry’s parents.","zh":"Lord Voldemort 自殺死 Harry 父母以來沒有出現。"},{"en":"Has not appeared since means has not been seen or shown after a particular event.","zh":"「has not appeared since」意思是在某事件之後沒有被看見或出現。"},{"en":"A student who moved away has not appeared at school events since graduation.","zh":"搬走的學生自畢業以來沒有出現在學校活動中。"},{"en":"If a villain has not appeared for years, their return can create suspense.","zh":"如果反派多年沒有出現，他的回歸可以製造懸念。"},{"en":"The phrase connects absence with a starting point in the past.","zh":"這個短語把缺席與過去某起點連繫起來。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":14},{"front":"immersed himself in","meaning":"投入；置身於","examples":[{"en":"Radcliffe immersed himself in an extended underwater scene.","zh":"Radcliffe 投入一場長時間水底場面。"},{"en":"To immerse oneself in something means to become deeply involved in it or physically placed in it.","zh":"「immerse oneself in」某事，意思是深度投入其中，或身體上置身其中。"},{"en":"A student may immerse herself in English by reading, listening and speaking every day.","zh":"學生可以透過每天閱讀、聆聽和說話，讓自己沉浸於英語中。"},{"en":"If an actor immerses himself in a difficult scene, the performance may feel more real.","zh":"如果演員投入困難場面，表演可能感覺更真實。"},{"en":"The phrase can be literal, as in water, or figurative, as in study.","zh":"這個短語可以是字面意思，如在水中，也可以是比喻意思，如在學習中。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":14},{"front":"extended underwater scene","meaning":"長時間水底場面","examples":[{"en":"Radcliffe acted in an extended underwater scene.","zh":"Radcliffe 演出了一場長時間水底場面。"},{"en":"An extended underwater scene is a long part of a film shot or set below water.","zh":"「extended underwater scene」是電影中一段長時間在水下拍攝或設定的場面。"},{"en":"A swimming documentary may include an extended underwater scene showing how athletes move.","zh":"游泳紀錄片可能包含長時間水底場面，展示運動員如何移動。"},{"en":"If a scene is filmed underwater for a long time, actors need special training and safety support.","zh":"如果場面長時間在水下拍攝，演員需要特別訓練和安全支援。"},{"en":"The phrase describes both length and location of a film scene.","zh":"這個短語描述電影場面的長度和地點。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":14},{"front":"turn into","meaning":"變成","examples":[{"en":"The producer says Radcliffe will not turn into a stuntman.","zh":"監製說 Radcliffe 不會變成特技演員。"},{"en":"To turn into something means to become that thing.","zh":"「turn into」某物，意思是變成那樣東西。"},{"en":"A hobby can turn into a career if someone practises seriously for years.","zh":"如果某人多年認真練習，興趣可以變成事業。"},{"en":"If an actor does action scenes, that does not mean he will become a professional stuntman.","zh":"如果演員拍動作場面，這不代表他會變成專業特技演員。"},{"en":"The phrase describes change from one state or role to another.","zh":"這個短語描述從一種狀態或角色轉變成另一種。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":14},{"front":"a stuntman","meaning":"特技演員","examples":[{"en":"Radcliffe is not expected to become a stuntman.","zh":"Radcliffe 預計不會成為特技演員。"},{"en":"A stuntman is a trained performer who does dangerous actions in films or television.","zh":"「a stuntman」是在電影或電視中做危險動作的受訓表演者。"},{"en":"A stuntman may fall from a height, drive fast cars or perform fight scenes safely.","zh":"特技演員可能從高處跌下、駕駛高速汽車或安全完成打鬥場面。"},{"en":"If a stunt is risky, trained stunt performers protect actors from injury.","zh":"如果特技有風險，受訓特技演員可以保護演員免受傷害。"},{"en":"The word refers to a specialist in physical action scenes.","zh":"這個詞指身體動作場面的專家。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":14},{"front":"a responsible boy","meaning":"負責任的男孩","examples":[{"en":"The producer describes Radcliffe as a responsible boy.","zh":"監製形容 Radcliffe 是一個負責任的男孩。"},{"en":"A responsible boy is a young male who behaves sensibly and can be trusted.","zh":"「a responsible boy」是行為理智且值得信任的年輕男孩。"},{"en":"A responsible student finishes homework, arrives on time and respects others.","zh":"負責任的學生會完成功課、準時到達並尊重別人。"},{"en":"If a young actor is responsible, adults can trust him with difficult work.","zh":"如果年輕演員負責任，成人可以信任他處理困難工作。"},{"en":"The phrase praises maturity in a young person.","zh":"這個短語稱讚年輕人的成熟。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":14},{"front":"enjoy the spotlight","meaning":"享受鎂光燈焦點","examples":[{"en":"Radcliffe seems to enjoy the spotlight more than his co-stars.","zh":"Radcliffe 似乎比他的共同主演更享受鎂光燈焦點。"},{"en":"To enjoy the spotlight means to like public attention.","zh":"「enjoy the spotlight」意思是喜歡公眾關注。"},{"en":"A student who loves performing may enjoy the spotlight during a school concert.","zh":"喜愛表演的學生可能在學校音樂會中享受鎂光燈焦點。"},{"en":"If someone enjoys attention, interviews and public events may feel exciting rather than frightening.","zh":"如果某人享受關注，訪問和公開活動可能令人興奮而不是害怕。"},{"en":"The phrase can be positive or negative depending on how the person handles fame.","zh":"這個短語可正可負，視乎此人如何處理名氣。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":14},{"front":"piping in with","meaning":"插話說出","examples":[{"en":"Radcliffe kept piping in with glib comments.","zh":"Radcliffe 不斷插話說出流暢但略顯油滑的評論。"},{"en":"To pipe in with something means to interrupt or join a conversation by saying it suddenly.","zh":"「pipe in with」某話，意思是突然插入或加入談話說出它。"},{"en":"A child may pipe in with an answer before the teacher finishes the question.","zh":"孩子可能在老師問題還未問完前就插話回答。"},{"en":"If someone keeps piping in, they may seem lively, confident or slightly rude.","zh":"如果某人不斷插話，他可能顯得活潑、自信或有點無禮。"},{"en":"The phrase describes sudden spoken contributions.","zh":"這個短語描述突然的口頭加入。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":14},{"front":"glib comments","meaning":"流暢但略顯油滑的評論","examples":[{"en":"Radcliffe made glib comments during the press conference.","zh":"Radcliffe 在記者會上作出流暢但略顯油滑的評論。"},{"en":"Glib comments are smooth and quick remarks that may sound clever but not very deep or sincere.","zh":"「glib comments」是流暢快速、聽起來聰明但不太深入或真誠的評論。"},{"en":"A student may give glib answers if he wants to sound smart without thinking carefully.","zh":"如果學生想顯得聰明但沒有仔細思考，他可能給出油滑答案。"},{"en":"If comments are too glib, people may doubt whether the speaker is serious.","zh":"如果評論太油滑，人們可能懷疑說話者是否認真。"},{"en":"The phrase can be mildly critical.","zh":"這個短語可以帶輕微批評意味。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":14},{"front":"stumbled through","meaning":"結結巴巴地完成","examples":[{"en":"Rupert Grint stumbled through the afternoon news conference.","zh":"Rupert Grint 結結巴巴地完成下午的記者會。"},{"en":"To stumble through something means to get through it awkwardly, nervously or with difficulty.","zh":"「stumble through」某事，意思是尷尬、緊張或困難地完成它。"},{"en":"A nervous student may stumble through an oral presentation.","zh":"緊張的學生可能結結巴巴地完成口頭匯報。"},{"en":"If someone is uncomfortable with reporters, a news conference may feel hard to complete smoothly.","zh":"如果某人不習慣面對記者，記者會可能難以順利完成。"},{"en":"The phrase suggests effort despite awkwardness.","zh":"這個短語暗示雖然尷尬仍努力完成。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":15},{"front":"news conference","meaning":"記者會","examples":[{"en":"The young actors attended an afternoon news conference.","zh":"這些年輕演員出席了下午的記者會。"},{"en":"A news conference is a formal event where reporters ask questions and gather information.","zh":"「news conference」是記者提問並收集資料的正式活動。"},{"en":"A school may hold a news conference after a student wins an international prize.","zh":"學生贏得國際獎項後，學校可能舉行記者會。"},{"en":"If actors attend a news conference, they must answer questions in front of many journalists.","zh":"如果演員出席記者會，他們必須在許多記者面前回答問題。"},{"en":"The phrase is similar to press conference.","zh":"這個短語與 press conference 相近。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":15},{"front":"all the while","meaning":"一直；同時","examples":[{"en":"All the while, Radcliffe’s parents watched from the back row.","zh":"一直以來，Radcliffe 的父母在後排觀看。"},{"en":"All the while means during the whole time something else is happening.","zh":"「all the while」意思是在另一件事發生的整個期間。"},{"en":"The student gave her speech, and all the while her teacher smiled from the back of the room.","zh":"學生發表演說時，老師一直在課室後面微笑。"},{"en":"If parents watch quietly all the while, they may be supporting without interfering.","zh":"如果父母一直安靜觀看，他們可能是在支持而不干預。"},{"en":"The phrase shows a simultaneous background action.","zh":"這個短語顯示同時發生的背景行動。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":15},{"front":"in the back row","meaning":"在後排","examples":[{"en":"His parents sat in the back row.","zh":"他的父母坐在後排。"},{"en":"In the back row means in the row of seats farthest from the front.","zh":"「in the back row」意思是在離前方最遠的一排座位。"},{"en":"Shy students may choose seats in the back row during a large lecture.","zh":"害羞學生在大型講座中可能選擇坐在後排。"},{"en":"If parents sit in the back row, they can observe without drawing attention.","zh":"如果父母坐在後排，他們可以觀察而不吸引注意。"},{"en":"The phrase gives a specific seating location.","zh":"這個短語提供具體座位位置。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":15},{"front":"with thin smiles","meaning":"帶着淡淡的笑容","examples":[{"en":"His parents watched with thin smiles.","zh":"他的父母帶着淡淡的笑容觀看。"},{"en":"With thin smiles means with small, controlled smiles that may show quiet approval or restraint.","zh":"「with thin smiles」意思是帶着細小、克制的笑容，可能顯示安靜認可或克制。"},{"en":"A teacher may watch a nervous student with a thin smile to show support without interrupting.","zh":"老師可能帶着淡淡笑容觀看緊張學生，以示支持而不打斷。"},{"en":"If parents smile thinly during a public event, they may be proud but cautious.","zh":"如果父母在公開活動中淡淡微笑，他們可能既自豪又謹慎。"},{"en":"The phrase suggests subtle emotion, not broad excitement.","zh":"這個短語暗示細微情感，而不是熱烈興奮。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":15},{"front":"arms folded","meaning":"雙臂交叉","examples":[{"en":"His parents sat with their arms folded.","zh":"他的父母雙臂交叉坐着。"},{"en":"Arms folded means with both arms crossed in front of the body.","zh":"「arms folded」意思是雙臂在身體前交叉。"},{"en":"A teacher may stand with arms folded while waiting for a noisy class to settle.","zh":"老師可能雙臂交叉站着，等待吵鬧班級安靜。"},{"en":"Folded arms can suggest patience, control, caution or seriousness.","zh":"雙臂交叉可以暗示耐心、控制、謹慎或嚴肅。"},{"en":"The phrase describes body language.","zh":"這個短語描述身體語言。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":15},{"front":"arrogant and big-headed","meaning":"傲慢自大","examples":[{"en":"Radcliffe says he might be arrogant and big-headed without his parents.","zh":"Radcliffe 說沒有父母的話，他可能會傲慢自大。"},{"en":"Arrogant and big-headed means too proud and thinking too highly of oneself.","zh":"「arrogant and big-headed」意思是過分驕傲並把自己看得太高。"},{"en":"A student who wins one prize and then refuses advice may seem arrogant and big-headed.","zh":"贏了一個獎就拒絕意見的學生，可能顯得傲慢自大。"},{"en":"If fame is not balanced by honest guidance, a young person may become full of himself.","zh":"如果名氣沒有誠實引導來平衡，年輕人可能變得自滿。"},{"en":"The phrase is strongly negative and criticises attitude.","zh":"這個短語非常負面，用來批評態度。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":15},{"front":"kept me really grounded","meaning":"讓我保持腳踏實地","examples":[{"en":"Radcliffe says his parents kept him really grounded.","zh":"Radcliffe 說他的父母讓他保持腳踏實地。"},{"en":"To keep someone grounded means to help them stay humble, sensible and connected to normal life.","zh":"「keep someone grounded」意思是幫助某人保持謙遜、理智並與正常生活相連。"},{"en":"Honest friends can keep a successful student grounded by reminding her to keep working.","zh":"誠實朋友可以透過提醒成功學生繼續努力，讓她保持腳踏實地。"},{"en":"If a young celebrity stays grounded, fame is less likely to damage their character.","zh":"如果年輕名人保持腳踏實地，名氣較不容易損害其品格。"},{"en":"The phrase praises support that prevents arrogance.","zh":"這個短語稱讚防止傲慢的支援。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":15},{"front":"can’t thank them enough","meaning":"怎樣感謝也不夠","examples":[{"en":"He says he cannot thank his parents enough.","zh":"他說怎樣感謝父母也不夠。"},{"en":"Can’t thank them enough means feels extremely grateful and believes ordinary thanks are not sufficient.","zh":"「can’t thank them enough」意思是非常感激，覺得普通感謝不足夠。"},{"en":"A patient may say she cannot thank the nurses enough after a difficult recovery.","zh":"病人艱難康復後，可能說怎樣感謝護士也不夠。"},{"en":"If someone’s support changed your life, simple thanks may feel too small.","zh":"如果某人的支持改變了你的人生，簡單道謝可能顯得太少。"},{"en":"The phrase expresses deep gratitude.","zh":"這個短語表達深切感激。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":15},{"front":"on-screen dragon slayer","meaning":"銀幕上的屠龍者","examples":[{"en":"Radcliffe is more an on-screen dragon slayer than a ladykiller.","zh":"Radcliffe 更像銀幕上的屠龍者，而不是迷倒女士的男子。"},{"en":"An on-screen dragon slayer is someone who plays heroic fantasy roles in films.","zh":"「on-screen dragon slayer」是在電影中飾演英雄奇幻角色的人。"},{"en":"An actor may be famous as an on-screen hero but still shy in real life.","zh":"演員可能因銀幕英雄形象而出名，但現實中仍害羞。"},{"en":"If a star is known for magical battles, the public may see him as a fantasy hero rather than a romantic figure.","zh":"如果明星因魔法戰鬥而聞名，公眾可能視他為奇幻英雄，而不是浪漫人物。"},{"en":"The phrase separates screen image from real personality.","zh":"這個短語把銀幕形象與真實個性分開。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":15},{"front":"ladykiller","meaning":"迷倒女士的男子","examples":[{"en":"The writer says Radcliffe is not yet a ladykiller.","zh":"作者說 Radcliffe 尚未是迷倒女士的男子。"},{"en":"A ladykiller is a man who is very attractive to women.","zh":"「ladykiller」是對女性非常有吸引力的男子。"},{"en":"A confident singer may be called a ladykiller if many fans find him charming.","zh":"如果很多粉絲覺得自信歌手很有魅力，他可能被稱為 ladykiller。"},{"en":"If someone is awkward with girls, people would not describe him as a ladykiller.","zh":"如果某人與女生相處尷尬，人們不會形容他是 ladykiller。"},{"en":"The word is informal and slightly playful.","zh":"這個詞較口語，並帶一點玩味。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":15},{"front":"spoke frankly about","meaning":"坦率談及","examples":[{"en":"Radcliffe spoke frankly about his awkwardness with girls.","zh":"Radcliffe 坦率談及自己與女生相處時的尷尬。"},{"en":"To speak frankly about something means to discuss it honestly and directly.","zh":"「speak frankly about」某事，意思是誠實而直接地談論它。"},{"en":"A student may speak frankly about exam anxiety when talking to a trusted teacher.","zh":"學生可能在與信任老師談話時坦率談及考試焦慮。"},{"en":"If a celebrity speaks frankly, audiences may feel he is more genuine.","zh":"如果名人坦率說話，觀眾可能覺得他更真實。"},{"en":"The phrase suggests openness rather than polished public relations.","zh":"這個短語暗示開放，而不是經過包裝的公關說法。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":16},{"front":"less-than-magical ways with girls","meaning":"與女生相處時不太神奇的本領","examples":[{"en":"Radcliffe joked about his less-than-magical ways with girls.","zh":"Radcliffe 開玩笑談到自己與女生相處時不太神奇的本領。"},{"en":"Less-than-magical ways with girls means not being especially charming or successful in romance.","zh":"「less-than-magical ways with girls」意思是在戀愛或吸引女生方面並不特別迷人或成功。"},{"en":"A boy may be funny with friends but awkward when talking to someone he likes.","zh":"男孩可能和朋友相處很有趣，但與喜歡的人說話時很尷尬。"},{"en":"If people expect a star to be charming, ordinary awkwardness can seem surprising.","zh":"如果人們期望明星有魅力，普通尷尬可能顯得令人意外。"},{"en":"The phrase humorously contrasts a magical screen image with real teenage awkwardness.","zh":"這個短語幽默地把魔法銀幕形象與真實青春期尷尬作對比。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":16},{"front":"expectations of him as","meaning":"對他作為……的期望","examples":[{"en":"Girls may have expectations of him as Harry Potter.","zh":"女生可能對他作為 Harry Potter 有期望。"},{"en":"Expectations of someone as a role are ideas about how that person should behave because of that role.","zh":"「expectations of someone as」某角色，指因該角色而產生對此人應如何表現的想法。"},{"en":"Students may have expectations of a class monitor as someone responsible and fair.","zh":"學生可能對班長作為負責任且公平的人有期望。"},{"en":"If fans expect an actor to behave like his character, real life can disappoint them.","zh":"如果粉絲期望演員像其角色一樣行事，現實生活可能令他們失望。"},{"en":"The phrase connects public expectation with a specific identity.","zh":"這個短語把公眾期望與特定身份連繫起來。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":16},{"front":"dissolve into","meaning":"化為；消散成","examples":[{"en":"Their expectations dissolve into a grimmer reality.","zh":"她們的期望化為較灰暗的現實。"},{"en":"To dissolve into something means to disappear or change gradually into another state.","zh":"「dissolve into」某物，意思是逐漸消失或變成另一種狀態。"},{"en":"A student’s confidence may dissolve into panic if the exam paper looks unfamiliar.","zh":"如果試卷看起來陌生，學生的信心可能化為恐慌。"},{"en":"If romantic expectations meet awkward reality, the imagined image may fade.","zh":"如果浪漫期望遇上尷尬現實，想像中的形象可能消散。"},{"en":"The phrase suggests a gradual change from one feeling to another.","zh":"這個短語暗示從一種感受逐漸變成另一種感受。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":16},{"front":"a grimmer reality","meaning":"較灰暗的現實","examples":[{"en":"Girls’ expectations may dissolve into a grimmer reality.","zh":"女生的期望可能化為較灰暗的現實。"},{"en":"A grimmer reality is a less pleasant or more disappointing truth.","zh":"「a grimmer reality」是較不愉快或較令人失望的真相。"},{"en":"A student may dream of easy university life, but the grimmer reality includes deadlines and pressure.","zh":"學生可能幻想大學生活輕鬆，但較灰暗的現實包括截止日期和壓力。"},{"en":"If someone expects magic but meets ordinary awkwardness, reality may feel grimmer.","zh":"如果某人期待魔法，卻遇上普通尷尬，現實可能顯得較灰暗。"},{"en":"The phrase contrasts fantasy with a harsher truth.","zh":"這個短語把幻想與較嚴峻真相作對比。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":16},{"front":"long outlive","meaning":"比……持續得久得多","examples":[{"en":"The Potter experience will long outlive his awkwardness.","zh":"Harry Potter 的經歷會比他的尷尬持續得久得多。"},{"en":"To long outlive something means to continue for much longer than it.","zh":"「long outlive」某事，意思是比它持續長得多。"},{"en":"A good friendship can long outlive a small argument.","zh":"好友誼可以比一次小爭吵持續得久得多。"},{"en":"If a teenage embarrassment fades, a major career experience may remain important for years.","zh":"如果青春期尷尬淡去，重大事業經歷仍可能多年重要。"},{"en":"The phrase compares how long two things last.","zh":"這個短語比較兩件事持續多久。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":16},{"front":"awkwardness","meaning":"尷尬；笨拙","examples":[{"en":"Radcliffe knows his awkwardness will not last forever.","zh":"Radcliffe 知道他的尷尬不會永遠持續。"},{"en":"Awkwardness is the uncomfortable feeling of not knowing how to behave naturally.","zh":"「awkwardness」是不知道如何自然表現時的不舒服感覺。"},{"en":"A student may feel awkwardness when speaking to a new class for the first time.","zh":"學生第一次向新班級說話時，可能感到尷尬。"},{"en":"If awkwardness decreases with practice, social confidence can grow.","zh":"如果尷尬隨練習減少，社交信心可以增加。"},{"en":"The word often describes embarrassment in social situations.","zh":"這個詞常描述社交情境中的難堪。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":16},{"front":"after all","meaning":"畢竟","examples":[{"en":"After all, millions of moviegoers have fallen under his spell.","zh":"畢竟，數百萬電影觀眾已被他迷住。"},{"en":"After all introduces a reason that explains or supports what has just been said.","zh":"「after all」用來引出解釋或支持剛才說法的理由。"},{"en":"You should bring an umbrella; after all, the sky is already dark.","zh":"你應該帶傘；畢竟，天空已經很暗。"},{"en":"If millions of people admire an actor, it helps explain why he feels more confident.","zh":"如果數百萬人欣賞演員，這有助解釋他為何更有信心。"},{"en":"The phrase reminds readers of an important supporting fact.","zh":"這個短語提醒讀者一個重要支持事實。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":16},{"front":"moviegoers","meaning":"電影觀眾","examples":[{"en":"Millions of moviegoers have watched Radcliffe as Harry Potter.","zh":"數百萬電影觀眾看過 Radcliffe 飾演 Harry Potter。"},{"en":"Moviegoers are people who watch films, especially in cinemas.","zh":"「moviegoers」是觀看電影的人，尤其是在戲院看電影的人。"},{"en":"Moviegoers may choose a film because of actors, reviews or trailers.","zh":"電影觀眾可能因演員、評論或預告片選擇電影。"},{"en":"If millions of moviegoers love a character, the actor may become famous worldwide.","zh":"如果數百萬電影觀眾喜愛某角色，演員可能全球成名。"},{"en":"The word refers to film audiences.","zh":"這個詞指電影受眾。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":16},{"front":"fallen under his spell","meaning":"被他迷住","examples":[{"en":"Millions of moviegoers have fallen under his spell.","zh":"數百萬電影觀眾已被他迷住。"},{"en":"To fall under someone’s spell means to become strongly charmed or attracted by them.","zh":"「fall under someone’s spell」意思是被某人強烈吸引或迷住。"},{"en":"Audiences may fall under a singer’s spell when her voice feels warm and honest.","zh":"當歌手聲音溫暖真誠，觀眾可能被她迷住。"},{"en":"If viewers fall under an actor’s spell, they may remember the character for years.","zh":"如果觀眾被演員迷住，他們可能多年記得該角色。"},{"en":"The phrase uses magic imagery to describe strong admiration.","zh":"這個短語用魔法意象描述強烈欣賞。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":16},{"front":"a feeling of confidence","meaning":"自信感","examples":[{"en":"The Potter experience has given Radcliffe a feeling of confidence.","zh":"Harry Potter 的經歷給了 Radcliffe 一種自信感。"},{"en":"A feeling of confidence is a sense that one can handle a situation successfully.","zh":"「a feeling of confidence」是一種相信自己能成功應付情況的感覺。"},{"en":"A student may gain a feeling of confidence after answering several practice questions correctly.","zh":"學生正確回答幾條練習題後，可能獲得自信感。"},{"en":"If a young actor succeeds in a major role, that success can build confidence for future work.","zh":"如果年輕演員在重要角色中成功，那種成功可以為未來工作建立自信。"},{"en":"The phrase describes inner belief, not public praise alone.","zh":"這個短語描述內在信念，而不只是公眾讚美。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":16},{"front":"which I might not have had otherwise","meaning":"否則我可能不會有的","examples":[{"en":"The role gave him confidence which he might not have had otherwise.","zh":"這個角色給了他自信，否則他可能不會有。"},{"en":"Which I might not have had otherwise means which I probably would not have gained without that experience.","zh":"「which I might not have had otherwise」意思是如果沒有那次經歷，我可能不會獲得。"},{"en":"A shy student may gain confidence from drama club which she might not have had otherwise.","zh":"害羞學生可能從戲劇社得到自信，否則她可能不會有。"},{"en":"If an opportunity changes someone’s self-belief, life may be different without it.","zh":"如果一個機會改變某人的自我信念，沒有它人生可能不同。"},{"en":"The phrase shows that one experience created a benefit that may not have existed.","zh":"這個短語顯示某次經歷帶來了本來未必存在的好處。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":17},{"front":"the text has nine paragraphs","meaning":"文章有九段","examples":[{"en":"The text has nine paragraphs about Daniel Radcliffe.","zh":"這篇關於 Daniel Radcliffe 的文章有九段。"},{"en":"The text has nine paragraphs means the passage is divided into nine separate sections.","zh":"「the text has nine paragraphs」意思是文章分成九個獨立段落。"},{"en":"A reading test may ask students to match headings when a text has several paragraphs.","zh":"當文章有幾段時，閱讀測驗可能要求學生配對標題。"},{"en":"If students know the number of paragraphs, they can organise their search more carefully.","zh":"如果學生知道段落數量，他們可以更仔細組織搜尋。"},{"en":"The phrase describes the structure of a passage.","zh":"這個短語描述文章結構。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":17},{"front":"which paragraph does each heading best fit","meaning":"每個標題最適合哪一段","examples":[{"en":"Students decide which paragraph each heading best fits.","zh":"學生判斷每個標題最適合哪一段。"},{"en":"Which paragraph does each heading best fit means students choose the paragraph that matches each heading most closely.","zh":"「which paragraph does each heading best fit」意思是學生選出與每個標題最相符的段落。"},{"en":"In IELTS reading, students should read the main idea before matching headings to paragraphs.","zh":"在 IELTS 閱讀中，學生應先讀主旨，再把標題配對到段落。"},{"en":"If a heading matches only one detail but not the main idea, it may not be the best fit.","zh":"如果標題只符合一個細節而非主旨，它可能不是最佳配對。"},{"en":"The phrase gives an instruction for a heading-matching task.","zh":"這個短語是段落標題配對題的指示。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":17},{"front":"security","meaning":"保安；安全","examples":[{"en":"One heading focuses on security and personal safety.","zh":"其中一個標題集中於保安和人身安全。"},{"en":"Security means protection from danger, harm or unwanted intrusion.","zh":"「security」意思是免受危險、傷害或不必要侵擾的保護。"},{"en":"A school improves security by checking visitors at the entrance.","zh":"學校透過在入口檢查訪客來改善保安。"},{"en":"If fans become too aggressive, a celebrity may need more security.","zh":"如果粉絲變得太激烈，名人可能需要更多保安。"},{"en":"The word can refer to physical safety or broader protection.","zh":"這個詞可以指身體安全，也可以指更廣義的保障。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":17},{"front":"underwater scene","meaning":"水底場面","examples":[{"en":"The article describes an underwater scene in the film.","zh":"文章描述電影中的一個水底場面。"},{"en":"An underwater scene is a film scene that takes place or is filmed below water.","zh":"「underwater scene」是在水下發生或拍攝的電影場面。"},{"en":"A documentary about divers may include an underwater scene showing coral reefs.","zh":"關於潛水員的紀錄片可能包含展示珊瑚礁的水底場面。"},{"en":"If a scene is underwater, actors may need breathing support and safety planning.","zh":"如果場面在水底，演員可能需要呼吸支援和安全規劃。"},{"en":"The phrase gives the setting of a particular part of a film.","zh":"這個短語提供電影某部分的場景。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":17},{"front":"balancing filming and studies","meaning":"平衡拍攝和學業","examples":[{"en":"Radcliffe discusses balancing filming and studies.","zh":"Radcliffe 討論平衡拍攝和學業。"},{"en":"Balancing filming and studies means managing acting work and schoolwork at the same time.","zh":"「balancing filming and studies」意思是同時管理演藝工作和學業。"},{"en":"A student athlete must balance training and homework during competition season.","zh":"學生運動員在比賽季節必須平衡訓練和功課。"},{"en":"If filming takes too many hours, study time may suffer.","zh":"如果拍攝佔太多時間，學習時間可能受影響。"},{"en":"The phrase focuses on managing two demanding responsibilities.","zh":"這個短語集中於管理兩項高要求責任。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":17},{"front":"not a bad star","meaning":"不是壞明星；表現不差的明星","examples":[{"en":"The heading suggests that Radcliffe is not a badly behaved star.","zh":"這個標題暗示 Radcliffe 不是行為差劣的明星。"},{"en":"Not a bad star means a celebrity who behaves better than people might expect.","zh":"「not a bad star」意思是表現比人們預期更好的名人。"},{"en":"A singer who arrives on time and thanks staff may be described as not a bad star.","zh":"如果歌手準時到達並感謝工作人員，他可以被形容為不是壞明星。"},{"en":"If a young celebrity avoids scandals, people may contrast him with badly behaved stars.","zh":"如果年輕名人避開醜聞，人們可能把他與行為差的明星作對比。"},{"en":"The phrase is understated praise.","zh":"這個短語是低調稱讚。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":17},{"front":"according to the text","meaning":"根據文章","examples":[{"en":"Students choose statements that are true according to the text.","zh":"學生選出根據文章屬實的陳述。"},{"en":"According to the text means based only on what the passage says.","zh":"「according to the text」意思是只根據文章所說。"},{"en":"In reading tests, students should answer according to the text, not personal knowledge.","zh":"在閱讀測驗中，學生應根據文章作答，而不是個人知識。"},{"en":"If the text does not mention a point, students should not assume it is true.","zh":"如果文章沒有提到某點，學生不應假設它為真。"},{"en":"The phrase reminds learners to use evidence from the passage.","zh":"這個短語提醒學習者使用文章證據。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":17},{"front":"the following statements are true","meaning":"以下陳述屬實","examples":[{"en":"The task asks which following statements are true.","zh":"任務要求判斷以下哪些陳述屬實。"},{"en":"The following statements are true means the statements listed below match the information given.","zh":"「the following statements are true」意思是下方列出的陳述符合所提供資料。"},{"en":"A test may ask students to choose which statements are true after reading a passage.","zh":"測驗可能要求學生閱讀文章後選出哪些陳述屬實。"},{"en":"If a statement sounds likely but the text does not support it, it should not be chosen.","zh":"如果陳述聽起來合理但文本不支持，就不應選擇。"},{"en":"The phrase gives an instruction for evidence checking.","zh":"這個短語給出核對證據的指示。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":17},{"front":"corresponding letters","meaning":"相應字母","examples":[{"en":"Students write the corresponding letters in the answer boxes.","zh":"學生在答案框中寫下相應字母。"},{"en":"Corresponding letters are the option letters that match the chosen answers.","zh":"「corresponding letters」是與所選答案匹配的選項字母。"},{"en":"In a multiple-choice test, students may write A, B, C or D as corresponding letters.","zh":"在多項選擇題中，學生可能寫 A、B、C 或 D 作相應字母。"},{"en":"If students choose the right idea but write the wrong letter, the answer may be marked wrong.","zh":"如果學生選對意思但寫錯字母，答案可能被判錯。"},{"en":"The phrase refers to answer labels.","zh":"這個短語指答案標籤。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":17},{"front":"in any order","meaning":"以任何次序","examples":[{"en":"The answers may be written in any order.","zh":"答案可以以任何次序寫下。"},{"en":"In any order means the sequence does not matter.","zh":"「in any order」意思是次序不重要。"},{"en":"A teacher may say students can answer the short questions in any order.","zh":"老師可能說學生可以以任何次序回答短問題。"},{"en":"If answers are accepted in any order, students can write the ones they know first.","zh":"如果答案可以以任何次序接受，學生可以先寫自己知道的答案。"},{"en":"The phrase removes the need for a fixed sequence.","zh":"這個短語取消固定順序的需要。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":17},{"front":"the first showing of","meaning":"首次放映","examples":[{"en":"The statement refers to the first showing of the film.","zh":"該陳述指電影的首次放映。"},{"en":"The first showing of a film is its first screening or premiere.","zh":"「the first showing of」電影，意思是它的首次放映或首映。"},{"en":"A school documentary’s first showing may happen in front of parents and teachers.","zh":"學校紀錄片的首次放映可能在家長和老師面前進行。"},{"en":"If a film’s first showing happens in New York, that does not mean general release begins there.","zh":"如果電影首次放映在紐約，這不代表正式上映一定從那裡開始。"},{"en":"The phrase identifies the earliest public screening.","zh":"這個短語指出最早的公開放映。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":18},{"front":"started acting","meaning":"開始演戲","examples":[{"en":"The question asks when Daniel Radcliffe started acting.","zh":"問題問 Daniel Radcliffe 何時開始演戲。"},{"en":"Started acting means began performing in films, television or theatre.","zh":"「started acting」意思是開始在電影、電視或劇場中表演。"},{"en":"A child may start acting in school plays before joining professional auditions.","zh":"孩子可能先在學校話劇中開始演戲，再參加專業試鏡。"},{"en":"If someone starts acting young, their education and work must be carefully balanced.","zh":"如果某人年紀很小就開始演戲，教育和工作必須小心平衡。"},{"en":"The phrase marks the beginning of an acting career.","zh":"這個短語標示演藝生涯的開始。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":18},{"front":"talk to reporters often","meaning":"經常與記者交談","examples":[{"en":"The statement asks whether Daniel Radcliffe talks to reporters often.","zh":"該陳述問 Daniel Radcliffe 是否經常與記者交談。"},{"en":"To talk to reporters often means to give frequent interviews or media comments.","zh":"「talk to reporters often」意思是經常接受訪問或向媒體發言。"},{"en":"A school principal may talk to reporters often after a major public event.","zh":"大型公共事件後，校長可能經常與記者交談。"},{"en":"If a celebrity gives few interviews, it is not accurate to say he talks to reporters often.","zh":"如果名人很少接受訪問，說他經常與記者交談就不準確。"},{"en":"The phrase describes frequency of media contact.","zh":"這個短語描述媒體接觸的頻率。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":18},{"front":"treated specially at school","meaning":"在學校受到特別對待","examples":[{"en":"The question asks whether Daniel Radcliffe is treated specially at school.","zh":"問題問 Daniel Radcliffe 是否在學校受到特別對待。"},{"en":"Treated specially at school means given unusual attention or different treatment because of who he is.","zh":"「treated specially at school」意思是因身份而在學校得到不尋常關注或不同對待。"},{"en":"A famous student may be treated specially if classmates crowd around him every day.","zh":"如果同學每天圍着有名學生，他可能在學校受到特別對待。"},{"en":"If excitement dies down after a few weeks, school life may return to normal.","zh":"如果興奮幾星期後平息，學校生活可能回復正常。"},{"en":"The phrase focuses on whether fame changes daily treatment.","zh":"這個短語集中於名氣是否改變日常對待。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":18},{"front":"when filming","meaning":"拍攝期間","examples":[{"en":"When filming, Radcliffe studies with a tutor at the studio.","zh":"拍攝期間，Radcliffe 在片場跟導師學習。"},{"en":"When filming means during the period when a film is being made.","zh":"「when filming」意思是在電影製作期間。"},{"en":"When filming a school video, students may need to repeat scenes several times.","zh":"拍攝學校影片時，學生可能需要重拍場面幾次。"},{"en":"If an actor is still a student when filming, lessons may need to happen on set.","zh":"如果演員拍攝期間仍是學生，課堂可能需要在片場進行。"},{"en":"The phrase gives the time context for another action.","zh":"這個短語提供另一行動的時間背景。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":18},{"front":"tutored at the film studio","meaning":"在電影片場接受補習","examples":[{"en":"Radcliffe is tutored at the film studio during filming.","zh":"Radcliffe 拍攝期間在電影片場接受補習。"},{"en":"Tutored at the film studio means taught privately at the place where the film is made.","zh":"「tutored at the film studio」意思是在電影製作地點接受私人教學。"},{"en":"A child actor may be tutored between scenes so schoolwork continues.","zh":"童星可能在場景之間接受補習，使學業繼續。"},{"en":"If lessons happen at the studio, filming and education can fit into the same day.","zh":"如果課堂在片場進行，拍攝和教育可以安排在同一天。"},{"en":"The phrase describes education arranged around film production.","zh":"這個短語描述圍繞電影製作安排的教育。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":18},{"front":"gets on with","meaning":"與……相處融洽","examples":[{"en":"The statement asks whether Radcliffe gets on with the director.","zh":"該陳述問 Radcliffe 是否與導演相處融洽。"},{"en":"To get on with someone means to have a good relationship with them.","zh":"「get on with」某人，意思是與他有良好關係。"},{"en":"A student learns better when she gets on with her teacher.","zh":"如果學生與老師相處融洽，她會學得更好。"},{"en":"If an actor and director get on well, filming may be smoother.","zh":"如果演員和導演相處良好，拍攝可能更順利。"},{"en":"The phrase is common in British English for friendly relations.","zh":"這個短語在英式英語中常用來表示友好關係。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":18},{"front":"dealing with reporters","meaning":"應付記者","examples":[{"en":"Radcliffe seems good at dealing with reporters.","zh":"Radcliffe 似乎很擅長應付記者。"},{"en":"Dealing with reporters means handling journalists’ questions and media attention.","zh":"「dealing with reporters」意思是處理記者問題和媒體關注。"},{"en":"A school spokesperson must be careful when dealing with reporters after an incident.","zh":"事故後，學校發言人在應付記者時必須小心。"},{"en":"If someone answers clearly and calmly, they can manage media pressure better.","zh":"如果某人回答清楚而冷靜，他能更好處理媒體壓力。"},{"en":"The phrase focuses on communication under public attention.","zh":"這個短語集中於公眾關注下的溝通。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":18},{"front":"unhappy with","meaning":"對……不高興","examples":[{"en":"The statement asks whether Radcliffe’s parents were unhappy with the press conference.","zh":"該陳述問 Radcliffe 的父母是否對記者會不高興。"},{"en":"Unhappy with something means dissatisfied, worried or displeased about it.","zh":"「unhappy with」某事，意思是對它不滿、擔心或不高興。"},{"en":"Parents may be unhappy with a school policy if it creates too much homework.","zh":"如果學校政策造成太多功課，家長可能對它不高興。"},{"en":"If someone watches with a thin smile, it does not necessarily prove they are unhappy.","zh":"如果某人帶着淡淡笑容觀看，這不一定證明他不高興。"},{"en":"The phrase describes a negative feeling toward a situation.","zh":"這個短語描述對某情況的負面感受。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":18},{"front":"according to the information given","meaning":"根據所提供的資料","examples":[{"en":"Students answer according to the information given in the text.","zh":"學生根據文章所提供的資料作答。"},{"en":"According to the information given means based only on the details provided.","zh":"「according to the information given」意思是只根據已提供的細節。"},{"en":"In a reading exam, students should not use outside knowledge if the answer must come from the text.","zh":"在閱讀考試中，如果答案必須來自文章，學生不應使用外部知識。"},{"en":"If information is not given, students should avoid guessing.","zh":"如果資料沒有提供，學生應避免猜測。"},{"en":"The phrase reminds students to rely on evidence.","zh":"這個短語提醒學生依賴證據。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":18},{"front":"choose the correct answer","meaning":"選出正確答案","examples":[{"en":"Students choose the correct answer from the choices given.","zh":"學生從所給選項中選出正確答案。"},{"en":"To choose the correct answer means to select the option that best matches the text or question.","zh":"「choose the correct answer」意思是選擇最符合文本或問題的選項。"},{"en":"In multiple-choice questions, students should read all choices before choosing the correct answer.","zh":"在多項選擇題中，學生應先閱讀所有選項，再選出正確答案。"},{"en":"If two answers look similar, evidence from the text helps decide which is correct.","zh":"如果兩個答案看似相似，文章證據可以幫助判斷哪個正確。"},{"en":"The phrase is a standard exam instruction.","zh":"這個短語是標準考試指示。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":18},{"front":"from the choices given","meaning":"從所給選項中","examples":[{"en":"The answer must come from the choices given.","zh":"答案必須來自所給選項。"},{"en":"From the choices given means from the listed options, not from your own wording.","zh":"「from the choices given」意思是從列出的選項中，而不是用自己的字句。"},{"en":"A test may ask students to choose A, B, C or D from the choices given.","zh":"測驗可能要求學生從所給選項 A、B、C 或 D 中選擇。"},{"en":"If the correct idea is not written exactly, students still must choose the closest listed option.","zh":"如果正確意思沒有完全寫出，學生仍必須選最接近的列出選項。"},{"en":"The phrase limits answers to the options provided.","zh":"這個短語把答案限制在所提供選項中。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":19},{"front":"the writer says that","meaning":"作者說","examples":[{"en":"The question asks what the writer says about Daniel Radcliffe.","zh":"問題問作者對 Daniel Radcliffe 說了甚麼。"},{"en":"The writer says that means the answer should reflect the writer’s view or statement.","zh":"「the writer says that」意思是答案應反映作者的看法或說法。"},{"en":"In reading tests, students must separate what the writer says from what other people assume.","zh":"在閱讀測驗中，學生必須分清作者所說與其他人假設。"},{"en":"If the writer describes someone as professional, students should not choose an answer about height unless supported.","zh":"如果作者形容某人專業，除非有支持，學生不應選關於身高的答案。"},{"en":"The phrase points to the author’s own description.","zh":"這個短語指向作者自己的描述。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":19},{"front":"looks taller without","meaning":"沒有……時看起來較高","examples":[{"en":"The option asks whether he looks taller without his glasses.","zh":"該選項問他沒有眼鏡時是否看起來較高。"},{"en":"Looks taller without something means appears taller when that item is removed.","zh":"「looks taller without」某物，意思是移除該物時看起來較高。"},{"en":"A student may look taller without a large backpack because his posture is clearer.","zh":"學生沒有大型背包時，因姿勢更清楚，可能看起來較高。"},{"en":"If the text only says someone looks different, it may not prove he looks taller.","zh":"如果文本只說某人看起來不同，這未必證明他看起來較高。"},{"en":"The phrase describes a visual comparison caused by absence of an item.","zh":"這個短語描述因缺少某物造成的視覺比較。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":19},{"front":"behaves very professionally","meaning":"表現非常專業","examples":[{"en":"The writer suggests that Radcliffe behaves very professionally.","zh":"作者暗示 Radcliffe 表現非常專業。"},{"en":"Behaves very professionally means acts with confidence, control and responsibility in work situations.","zh":"「behaves very professionally」意思是在工作情境中表現自信、克制和負責任。"},{"en":"A student behaves professionally during a presentation if she is prepared, polite and clear.","zh":"如果學生在匯報中準備充足、有禮且清晰，她就表現得專業。"},{"en":"If an actor handles reporters smoothly, people may see him as professional beyond his age.","zh":"如果演員能流暢應付記者，人們可能覺得他比同齡人成熟專業。"},{"en":"The phrase praises mature behaviour at work.","zh":"這個短語稱讚工作中的成熟行為。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":19},{"front":"reviews of his acting","meaning":"對他演技的評論","examples":[{"en":"Radcliffe does not read reviews of his acting.","zh":"Radcliffe 不閱讀對他演技的評論。"},{"en":"Reviews of his acting are critics’ opinions about his performance as an actor.","zh":"「reviews of his acting」是評論者對他作為演員表現的意見。"},{"en":"A theatre student may read reviews of her acting to learn what audiences noticed.","zh":"戲劇學生可能閱讀對自己演技的評論，以了解觀眾注意到什麼。"},{"en":"If an actor avoids reviews, praise and criticism may affect him less.","zh":"如果演員避免看評論，讚美和批評可能較少影響他。"},{"en":"The phrase refers to evaluation of performance, not the film alone.","zh":"這個短語指對表演的評價，而不只是電影本身。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":19},{"front":"less money than","meaning":"比……少錢","examples":[{"en":"The option asks whether Radcliffe has less money than Prince Harry.","zh":"該選項問 Radcliffe 是否比 Prince Harry 少錢。"},{"en":"Less money than means a smaller amount of money compared with another person or group.","zh":"「less money than」意思是與另一人或群體相比有較少金錢。"},{"en":"A student may have less money than classmates but still manage spending carefully.","zh":"學生可能比同學少錢，但仍能仔細管理開支。"},{"en":"If a report ranks someone behind another person, it may suggest they have less wealth.","zh":"如果報道把某人排在另一人之後，可能暗示他的財富較少。"},{"en":"The phrase is used for direct financial comparison.","zh":"這個短語用於直接財務比較。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":19},{"front":"has made","meaning":"已賺得","examples":[{"en":"The question asks how much money Radcliffe has made.","zh":"問題問 Radcliffe 已賺得多少錢。"},{"en":"Has made means has earned or gained through work or activity.","zh":"「has made」意思是透過工作或活動已賺取或獲得。"},{"en":"A part-time worker may calculate how much money he has made during the summer.","zh":"兼職工人可能計算自己暑假期間已賺得多少錢。"},{"en":"If an actor has made a large amount of money, reporters may ask whether it affects him.","zh":"如果演員已賺得大量金錢，記者可能問這是否影響他。"},{"en":"The phrase focuses on income already earned.","zh":"這個短語集中於已賺取的收入。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":19},{"front":"doesn’t care how much","meaning":"不在乎有多少","examples":[{"en":"The option asks whether Radcliffe does not care how much money he has made.","zh":"該選項問 Radcliffe 是否不在乎自己已賺多少錢。"},{"en":"Doesn’t care how much means is not concerned about the exact amount.","zh":"「doesn’t care how much」意思是不關心確切數量。"},{"en":"A volunteer may not care how much time she spends if the work feels meaningful.","zh":"如果義工覺得工作有意義，她可能不在乎花了多少時間。"},{"en":"If someone does not focus on money, wealth may not shape their decisions strongly.","zh":"如果某人不專注於金錢，財富可能不會強烈塑造其決定。"},{"en":"The phrase can suggest indifference or healthy distance.","zh":"這個短語可以暗示漠不關心，也可以暗示健康距離。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":19},{"front":"play roles other than","meaning":"飾演……以外的角色","examples":[{"en":"Radcliffe wants to play roles other than Harry Potter.","zh":"Radcliffe 想飾演 Harry Potter 以外的角色。"},{"en":"To play roles other than something means to act as different characters beyond one familiar role.","zh":"「play roles other than」某角色，意思是飾演熟悉角色以外的不同人物。"},{"en":"A student known for comedy may want to play roles other than funny characters.","zh":"因喜劇出名的學生可能想飾演搞笑角色以外的角色。"},{"en":"If an actor plays different roles, audiences can see a wider range of talent.","zh":"如果演員飾演不同角色，觀眾可以看到更廣泛才能。"},{"en":"The phrase shows a desire to avoid being limited.","zh":"這個短語顯示不想被限制的願望。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":19},{"front":"suggested it","meaning":"建議這樣做","examples":[{"en":"The option asks whether Gary Oldman suggested it.","zh":"該選項問 Gary Oldman 是否建議這樣做。"},{"en":"Suggested it means proposed the idea or advised someone to do it.","zh":"「suggested it」意思是提出該想法或建議某人這樣做。"},{"en":"A teacher suggested it when a student was unsure whether to join the debate team.","zh":"當學生不確定是否加入辯論隊時，老師建議這樣做。"},{"en":"If a mentor suggests a career move, the young person may take it seriously.","zh":"如果導師建議某個事業決定，年輕人可能認真考慮。"},{"en":"The phrase points to where an idea came from.","zh":"這個短語指出想法來源。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":19},{"front":"can only play","meaning":"只會飾演","examples":[{"en":"Radcliffe does not want people to think he can only play Harry Potter.","zh":"Radcliffe 不想人們以為他只會飾演 Harry Potter。"},{"en":"Can only play means is limited to acting as one type of character or role.","zh":"「can only play」意思是只能飾演某一類人物或角色。"},{"en":"An actor known for villains may worry that directors think he can only play bad people.","zh":"因反派出名的演員可能擔心導演以為他只會飾演壞人。"},{"en":"If audiences believe an actor can only play one role, career options may shrink.","zh":"如果觀眾相信演員只會飾演一個角色，事業選項可能縮小。"},{"en":"The phrase expresses limitation in ability or public image.","zh":"這個短語表達能力或公眾形象上的限制。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":19},{"front":"successful with girls","meaning":"在女生方面成功","examples":[{"en":"The question asks why Radcliffe has not been successful with girls.","zh":"問題問為何 Radcliffe 在女生方面未算成功。"},{"en":"Successful with girls means able to attract or build romantic interest with girls.","zh":"「successful with girls」意思是能吸引女生或建立浪漫興趣。"},{"en":"A boy may be popular in class but not successful with girls if he becomes shy when talking to them.","zh":"男孩可能在班上受歡迎，但如果與女生說話時變得害羞，就未必在女生方面成功。"},{"en":"If girls expect a famous character instead of the real person, romance may become awkward.","zh":"如果女生期待的是著名角色而不是真人，戀愛可能變得尷尬。"},{"en":"The phrase is informal and refers to dating or attraction.","zh":"這個短語較口語，指約會或吸引力。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":20},{"front":"expect him to be like","meaning":"期望他像……","examples":[{"en":"Some girls expect Radcliffe to be like Harry Potter.","zh":"有些女生期望 Radcliffe 像 Harry Potter。"},{"en":"To expect someone to be like a character means to imagine they will behave like that role in real life.","zh":"「expect someone to be like」某角色，意思是想像他在現實生活中會像那角色一樣行事。"},{"en":"Fans may expect a comedian to be funny all the time, even off stage.","zh":"粉絲可能期望喜劇演員即使下台後也一直有趣。"},{"en":"If people expect an actor to match his character, the real person may disappoint them.","zh":"如果人們期望演員符合其角色，真人可能令他們失望。"},{"en":"The phrase shows confusion between public image and reality.","zh":"這個短語顯示公眾形象與現實之間的混淆。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":20},{"front":"go dating","meaning":"去約會","examples":[{"en":"The option asks whether his parents will let him go dating.","zh":"該選項問他的父母是否會讓他去約會。"},{"en":"To go dating means to go out romantically with someone.","zh":"「go dating」意思是與某人進行浪漫約會。"},{"en":"A teenager may ask parents for permission to go dating on the weekend.","zh":"青少年可能請求父母准許週末去約會。"},{"en":"If parents trust their child, they may allow dating with clear rules and safe plans.","zh":"如果父母信任孩子，他們可能在有清楚規則和安全安排下允許約會。"},{"en":"The phrase refers to romantic social activity, not simply meeting friends.","zh":"這個短語指浪漫社交活動，而不只是見朋友。"}],"source":"96 - No Growing Pains for Daniel Radcliffe.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 97":[{"front":"childhood obesity","meaning":"兒童肥胖","examples":[{"en":"The passage explains the causes, effects and treatment of childhood obesity.","zh":"文章解釋兒童肥胖的原因、影響和治療。"},{"en":"Childhood obesity is a health condition in which a child has too much body fat for healthy growth.","zh":"兒童肥胖是一種健康狀況，指兒童體脂過多，影響健康成長。"},{"en":"A school nurse may notice childhood obesity when several students struggle with exercise and tiredness.","zh":"當幾名學生在運動和疲倦方面有困難時，學校護士可能注意到兒童肥胖。"},{"en":"Childhood obesity can lead to physical, emotional and social problems if it is not managed early.","zh":"如果兒童肥胖沒有及早處理，可能導致身體、情緒和社交問題。"},{"en":"The phrase focuses on obesity during childhood, not weight gain in adults.","zh":"這個短語強調兒童期的肥胖，而不是成人增重。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":1},{"front":"become obese","meaning":"變得肥胖","examples":[{"en":"If a child becomes obese, their body processes can change.","zh":"如果兒童變得肥胖，他們的身體機能可能會改變。"},{"en":"To become obese means to gain enough excess body fat to create health concern.","zh":"“Become obese” 指增加過多體脂，以致造成健康憂慮。"},{"en":"A child may become obese if high-calorie food and little exercise become daily habits.","zh":"如果高卡路里食物和缺乏運動變成日常習慣，兒童可能變得肥胖。"},{"en":"If someone becomes obese early in life, weight control may become harder later.","zh":"如果人在生命早期變得肥胖，之後控制體重可能更困難。"},{"en":"The phrase describes a change into an unhealthy weight condition.","zh":"這個短語描述變成不健康體重狀態的改變。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":1},{"front":"body processes","meaning":"身體機能；身體運作過程","examples":[{"en":"If a child becomes obese, their body processes can change.","zh":"如果兒童變得肥胖，他們的身體機能可能會改變。"},{"en":"Body processes are the natural ways the body works, such as storing fat, using sugar and sending hunger signals.","zh":"身體機能是身體自然運作的方式，例如儲存脂肪、使用糖分和發出飢餓訊號。"},{"en":"Sleep, digestion and growth are body processes that affect a child’s health every day.","zh":"睡眠、消化和成長都是每天影響兒童健康的身體運作過程。"},{"en":"If body processes change early, the effects may continue into adulthood.","zh":"如果身體機能早期改變，其影響可能延續至成年期。"},{"en":"The phrase refers to how the body functions internally.","zh":"這個短語指身體內部如何運作。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":1},{"front":"be difficult to alter","meaning":"難以改變","examples":[{"en":"Some body processes may be difficult to alter in adulthood.","zh":"一些身體機能在成年期可能難以改變。"},{"en":"To be difficult to alter means to be hard to change once a pattern has been established.","zh":"“Be difficult to alter” 指某模式一旦形成後就難以改變。"},{"en":"A long-term habit of sleeping late can be difficult to alter after many years.","zh":"多年來晚睡的長期習慣可能難以改變。"},{"en":"If fat storage patterns are set early, they may be difficult to alter later.","zh":"如果脂肪儲存模式早期已形成，日後可能難以改變。"},{"en":"The phrase suggests that early prevention may be easier than later change.","zh":"這個短語暗示早期預防可能比日後改變更容易。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":1},{"front":"in adulthood","meaning":"在成年期","examples":[{"en":"Some effects of childhood obesity may continue in adulthood.","zh":"兒童肥胖的一些影響可能在成年期持續。"},{"en":"In adulthood means during the stage of life when someone is an adult.","zh":"“In adulthood” 指在人生成為成人的階段。"},{"en":"Childhood eating habits may affect health in adulthood.","zh":"童年的飲食習慣可能影響成年期健康。"},{"en":"If a problem continues in adulthood, it may influence work, family life and long-term health.","zh":"如果問題在成年期持續，可能影響工作、家庭生活和長期健康。"},{"en":"The phrase contrasts adult life with childhood or teenage years.","zh":"這個短語把成人生活與兒童期或青少年期作對比。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":1},{"front":"fat cells","meaning":"脂肪細胞","examples":[{"en":"Fat cells are created in the first few years of life.","zh":"脂肪細胞在出生後最初幾年形成。"},{"en":"Fat cells are body cells that store fat for energy and insulation.","zh":"脂肪細胞是儲存脂肪作能量和保溫用途的身體細胞。"},{"en":"Doctors may explain fat cells when teaching families why early weight control matters.","zh":"醫生向家庭解釋早期體重控制為何重要時，可能會講解脂肪細胞。"},{"en":"If a child develops many fat cells early, the body may store fat more easily later.","zh":"如果兒童早期形成大量脂肪細胞，身體日後可能更容易儲存脂肪。"},{"en":"The phrase refers to the cells involved in storing body fat.","zh":"這個短語指參與儲存體脂的細胞。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":1},{"front":"be created","meaning":"被產生；形成","examples":[{"en":"Fat cells are created in the first few years of life.","zh":"脂肪細胞在出生後最初幾年被產生。"},{"en":"To be created means to be formed, produced or brought into existence.","zh":"“Be created” 指被形成、產生或創造出來。"},{"en":"New routines are created when a family decides to eat dinner at the same time every night.","zh":"當家庭決定每晚同一時間吃飯，新的習慣就會形成。"},{"en":"If more fat cells are created early, later weight control may become more challenging.","zh":"如果更多脂肪細胞早期形成，日後控制體重可能更具挑戰。"},{"en":"The phrase describes something coming into being.","zh":"這個短語描述某事物出現。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":1},{"front":"in the first few years of life","meaning":"在出生後最初幾年","examples":[{"en":"Fat cells are created in the first few years of life.","zh":"脂肪細胞在出生後最初幾年形成。"},{"en":"In the first few years of life means during early childhood, shortly after birth.","zh":"“In the first few years of life” 指出生後不久的幼兒早期。"},{"en":"Children learn basic language skills in the first few years of life.","zh":"兒童在出生後最初幾年學習基本語言能力。"},{"en":"If health patterns develop in the first few years of life, parents need to pay attention early.","zh":"如果健康模式在出生後最初幾年形成，父母需要及早注意。"},{"en":"The phrase refers to a very early and important stage of development.","zh":"這個短語指非常早期且重要的發展階段。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":1},{"front":"be stored quickly","meaning":"被迅速儲存","examples":[{"en":"If fat is stored quickly, more fat cells are created.","zh":"如果脂肪被迅速儲存，就會形成更多脂肪細胞。"},{"en":"To be stored quickly means to be kept or accumulated in the body at a fast rate.","zh":"“Be stored quickly” 指以快速速度被身體保存或累積。"},{"en":"Extra energy from food can be stored quickly if a child eats much more than they use.","zh":"如果兒童攝取的食物能量遠多於消耗量，多餘能量可能被迅速儲存。"},{"en":"When fat is stored quickly during early childhood, the number of fat cells may increase.","zh":"當脂肪在幼兒期被迅速儲存，脂肪細胞數量可能增加。"},{"en":"The phrase explains rapid accumulation, not slow gradual change.","zh":"這個短語解釋快速累積，而不是緩慢漸變。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":1},{"front":"up to three times as many","meaning":"多達三倍","examples":[{"en":"An obese child can have up to three times as many fat cells as a child of normal weight.","zh":"肥胖兒童的脂肪細胞數量可多達體重正常兒童的三倍。"},{"en":"Up to three times as many means as many as three times the number, but not always that much.","zh":"“Up to three times as many” 指數量最多可達三倍，但不一定每次都達到。"},{"en":"One class may have up to three times as many students as another if one school is much larger.","zh":"如果一間學校大得多，一班學生數量可能多達另一班的三倍。"},{"en":"If a child has up to three times as many fat cells, the body may be more ready to store fat.","zh":"如果兒童脂肪細胞多達三倍，身體可能更容易準備儲存脂肪。"},{"en":"The phrase gives a maximum comparison.","zh":"這個短語給出最高比較數量。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":1},{"front":"a child of normal weight","meaning":"體重正常的兒童","examples":[{"en":"An obese child may have more fat cells than a child of normal weight.","zh":"肥胖兒童可能比體重正常的兒童有更多脂肪細胞。"},{"en":"A child of normal weight is a child whose weight is within a healthy range for their age and height.","zh":"體重正常的兒童，是體重處於其年齡和身高健康範圍內的兒童。"},{"en":"A doctor may compare an overweight child with a child of normal weight to explain health risks.","zh":"醫生可能把超重兒童與體重正常的兒童比較，以解釋健康風險。"},{"en":"If a child is of normal weight, they may still need balanced food and regular activity.","zh":"即使兒童體重正常，仍需要均衡飲食和定期活動。"},{"en":"The phrase describes a healthy weight category, not a perfect body shape.","zh":"這個短語描述健康體重類別，而不是完美身形。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":1},{"front":"normal weight","meaning":"正常體重","examples":[{"en":"A child of normal weight has fewer fat cells than an obese child.","zh":"體重正常的兒童比肥胖兒童有較少脂肪細胞。"},{"en":"Normal weight means a healthy weight range for a person’s age, height and body development.","zh":"正常體重指符合一個人年齡、身高和身體發展的健康體重範圍。"},{"en":"A school health check may identify whether a child is underweight, normal weight or overweight.","zh":"學校健康檢查可能識別兒童是體重過輕、正常體重還是超重。"},{"en":"If a child stays within a normal weight range, some obesity-related risks may be lower.","zh":"如果兒童保持在正常體重範圍內，一些與肥胖有關的風險可能較低。"},{"en":"The phrase is about health range, not appearance alone.","zh":"這個短語關乎健康範圍，而不只是外觀。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":2},{"front":"eventually","meaning":"最終","examples":[{"en":"Eventually, fat cells stop multiplying.","zh":"最終，脂肪細胞會停止增生。"},{"en":"Eventually means finally, after some time or after several stages.","zh":"“Eventually” 指經過一段時間或幾個階段後，最後發生。"},{"en":"If a student practises reading every day, difficult passages may eventually become easier.","zh":"如果學生每天練習閱讀，困難文章最終可能變得較容易。"},{"en":"When a process eventually stops, it does not continue forever.","zh":"當一個過程最終停止，它就不會永遠持續。"},{"en":"The word points to the final result after a period of change.","zh":"這個詞指一段變化後的最後結果。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":2},{"front":"stop multiplying","meaning":"停止增生","examples":[{"en":"Fat cells eventually stop multiplying.","zh":"脂肪細胞最終會停止增生。"},{"en":"To stop multiplying means to stop increasing in number.","zh":"“Stop multiplying” 指停止數量增加。"},{"en":"Bacteria may stop multiplying when medicine successfully controls an infection.","zh":"當藥物成功控制感染，細菌可能停止增生。"},{"en":"Once fat cells stop multiplying, existing cells mainly grow larger or smaller.","zh":"一旦脂肪細胞停止增生，現有細胞主要只是變大或變小。"},{"en":"The phrase describes the end of repeated increase.","zh":"這個短語描述重複增加的結束。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":2},{"front":"a fixed number","meaning":"固定數量","examples":[{"en":"An adult has a fixed number of fat cells for the rest of their life.","zh":"成人在餘生中擁有固定數量的脂肪細胞。"},{"en":"A fixed number is a number that stays the same and does not normally change.","zh":"固定數量是保持相同、通常不改變的數目。"},{"en":"A class may have a fixed number of seats, so late applicants cannot join easily.","zh":"一個班可能有固定數量的座位，所以遲申請者不容易加入。"},{"en":"If adults have a fixed number of fat cells, weight change mainly affects cell size.","zh":"如果成人有固定數量的脂肪細胞，體重變化主要影響細胞大小。"},{"en":"The phrase stresses stability rather than growth.","zh":"這個短語強調穩定，而不是增長。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":2},{"front":"for the rest of their life","meaning":"在餘生中","examples":[{"en":"An adult has a fixed number of fat cells for the rest of their life.","zh":"成人在餘生中擁有固定數量的脂肪細胞。"},{"en":"For the rest of their life means from that point until the person dies.","zh":"“For the rest of their life” 指從那一刻起直到該人去世。"},{"en":"A serious injury may affect someone’s movement for the rest of their life.","zh":"嚴重受傷可能在餘生中影響某人的活動能力。"},{"en":"If a health pattern lasts for the rest of a person’s life, early prevention becomes important.","zh":"如果健康模式在一個人的餘生中持續，早期預防便變得重要。"},{"en":"The phrase describes a lifelong effect.","zh":"這個短語描述終生影響。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":2},{"front":"existing cells","meaning":"現有細胞","examples":[{"en":"The existing cells simply swell or shrink to accommodate more fat.","zh":"現有細胞只是膨脹或縮小，以容納更多脂肪。"},{"en":"Existing cells are the cells already present in the body.","zh":"現有細胞是身體中已經存在的細胞。"},{"en":"In adults, existing fat cells may change size when body fat increases or decreases.","zh":"在成人身上，現有脂肪細胞可能在體脂增加或減少時改變大小。"},{"en":"If existing cells swell, weight can rise even without creating many new fat cells.","zh":"如果現有細胞膨脹，即使沒有形成許多新脂肪細胞，體重也可以上升。"},{"en":"The phrase refers to cells that are already there, not newly formed cells.","zh":"這個短語指已經存在的細胞，而不是新形成的細胞。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":2},{"front":"swell or shrink","meaning":"膨脹或縮小","examples":[{"en":"Fat cells swell or shrink to accommodate more fat.","zh":"脂肪細胞膨脹或縮小，以容納更多脂肪。"},{"en":"To swell or shrink means to become larger or smaller in size.","zh":"“Swell or shrink” 指體積變大或變小。"},{"en":"A sponge may swell when it absorbs water and shrink when it dries.","zh":"海綿吸水時可能膨脹，乾燥時縮小。"},{"en":"Fat cells swell when they store more fat and shrink when fat is used.","zh":"脂肪細胞儲存更多脂肪時會膨脹，脂肪被使用時會縮小。"},{"en":"The phrase describes change in size, not change in number.","zh":"這個短語描述大小改變，而不是數量改變。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":2},{"front":"accommodate more fat","meaning":"容納更多脂肪","examples":[{"en":"Existing fat cells swell to accommodate more fat.","zh":"現有脂肪細胞會膨脹，以容納更多脂肪。"},{"en":"To accommodate more fat means to make space for additional fat storage.","zh":"“Accommodate more fat” 指騰出空間儲存額外脂肪。"},{"en":"A suitcase expands to accommodate more clothes when the zip is opened wider.","zh":"當拉鏈拉得更開，行李箱會擴大以容納更多衣物。"},{"en":"When fat cells accommodate more fat, they become larger.","zh":"當脂肪細胞容納更多脂肪，它們會變得更大。"},{"en":"The phrase explains how the body stores extra energy.","zh":"這個短語解釋身體如何儲存額外能量。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":2},{"front":"be thought to be","meaning":"被認為是","examples":[{"en":"The amount of fat the body wants to store is thought to be proportional to the number of fat cells.","zh":"身體想儲存的脂肪量被認為與脂肪細胞數量成比例。"},{"en":"Be thought to be means people believe or consider something to be true.","zh":"“Be thought to be” 指人們相信或認為某事是真實的。"},{"en":"Regular exercise is thought to be helpful for both physical and mental health.","zh":"定期運動被認為對身心健康都有幫助。"},{"en":"If something is thought to be linked to early childhood, parents may pay attention sooner.","zh":"如果某事被認為與幼兒期有關，父母可能更早注意。"},{"en":"The phrase reports a belief or scientific view without stating it too absolutely.","zh":"這個短語報告一種信念或科學看法，而不把語氣說得太絕對。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":2},{"front":"be proportional to","meaning":"與……成比例","examples":[{"en":"The amount of fat stored is proportional to the total number of fat cells.","zh":"儲存的脂肪量與脂肪細胞總數成比例。"},{"en":"To be proportional to something means to increase or decrease in relation to it.","zh":"“Be proportional to” 某事指隨它相應增加或減少。"},{"en":"A taxi fare may be roughly proportional to the distance travelled.","zh":"的士車費可能大致與行駛距離成比例。"},{"en":"If fat storage is proportional to fat-cell number, more cells may mean a stronger tendency to store fat.","zh":"如果脂肪儲存與脂肪細胞數量成比例，更多細胞可能意味更強儲脂傾向。"},{"en":"The phrase explains a relationship between two quantities.","zh":"這個短語解釋兩個數量之間的關係。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":2},{"front":"the total number of","meaning":"……的總數","examples":[{"en":"Fat storage is related to the total number of fat cells.","zh":"脂肪儲存與脂肪細胞的總數有關。"},{"en":"The total number of something means the complete amount when all parts are counted together.","zh":"“The total number of” 某物指把所有部分加起來的完整數量。"},{"en":"A teacher checks the total number of students before booking a bus.","zh":"老師在預訂巴士前檢查學生總數。"},{"en":"If the total number of fat cells is high, the body may store fat more readily.","zh":"如果脂肪細胞總數高，身體可能更容易儲存脂肪。"},{"en":"The phrase focuses on the full count, not part of the count.","zh":"這個短語強調完整數量，而不是部分數量。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":2},{"front":"be programmed to","meaning":"被設定為；天生傾向於","examples":[{"en":"If you were overweight as a child, your body is programmed to carry more fat.","zh":"如果你小時候超重，你的身體就被設定為儲存更多脂肪。"},{"en":"To be programmed to do something means to be set up or strongly inclined to behave in that way.","zh":"“Be programmed to” 做某事指被設定或強烈傾向於以該方式運作。"},{"en":"A phone is programmed to lock itself after several minutes for security.","zh":"手機被設定為幾分鐘後自動鎖機，以保安全。"},{"en":"If the body is programmed to store more fat, losing weight may require more effort.","zh":"如果身體被設定為儲存更多脂肪，減重可能需要更多努力。"},{"en":"The phrase suggests a built-in tendency, not a conscious choice.","zh":"這個短語暗示內在傾向，而不是有意識選擇。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":3},{"front":"carry more fat","meaning":"儲存更多脂肪","examples":[{"en":"The body may be programmed to carry more fat.","zh":"身體可能天生傾向於儲存更多脂肪。"},{"en":"To carry more fat means to store a larger amount of body fat.","zh":"“Carry more fat” 指儲存較多體脂。"},{"en":"A person may carry more fat after months of eating more calories than they use.","zh":"如果一個人數月來攝取的卡路里多於消耗量，可能會儲存更多脂肪。"},{"en":"If the body tends to carry more fat, maintaining weight loss can be difficult.","zh":"如果身體傾向儲存更多脂肪，維持減重成果可能困難。"},{"en":"The phrase describes body fat storage, not carrying something by hand.","zh":"這個短語描述體脂儲存，而不是用手拿東西。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":3},{"front":"lose weight through diet and exercise","meaning":"透過飲食和運動減重","examples":[{"en":"You can lose weight through diet and exercise, but it may be harder.","zh":"你可以透過飲食和運動減重，但可能較困難。"},{"en":"To lose weight through diet and exercise means to reduce body weight by eating differently and being more active.","zh":"“Lose weight through diet and exercise” 指透過改變飲食和增加活動來減少體重。"},{"en":"A family may help a child lose weight through healthier meals and regular walks.","zh":"家庭可能透過較健康膳食和定期散步，幫助兒童減重。"},{"en":"If someone loses weight through diet and exercise, the change is usually safer than extreme methods.","zh":"如果某人透過飲食和運動減重，這種改變通常比極端方法更安全。"},{"en":"The phrase describes lifestyle-based weight loss.","zh":"這個短語描述以生活方式為本的減重。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":3},{"front":"diet and exercise","meaning":"飲食和運動","examples":[{"en":"Diet and exercise can help an overweight person lose weight.","zh":"飲食和運動可以幫助超重人士減重。"},{"en":"Diet and exercise mean what a person eats and how physically active they are.","zh":"飲食和運動指一個人吃甚麼，以及身體活動量如何。"},{"en":"A doctor may advise diet and exercise before discussing medicine or surgery.","zh":"醫生在討論藥物或手術前，可能先建議飲食和運動。"},{"en":"Good diet and exercise habits can improve energy, sleep and long-term health.","zh":"良好的飲食和運動習慣可以改善能量、睡眠和長期健康。"},{"en":"The phrase joins two key parts of weight management.","zh":"這個短語結合體重管理的兩個關鍵部分。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":3},{"front":"few health problems are observed","meaning":"觀察到的健康問題不多","examples":[{"en":"Few health problems are observed in obese children at first.","zh":"起初，肥胖兒童身上觀察到的健康問題不多。"},{"en":"Few health problems are observed means only a small number of problems can be seen or detected.","zh":"“Few health problems are observed” 指只看見或檢測到少量健康問題。"},{"en":"At the start of poor posture, few health problems may be observed, but pain can appear later.","zh":"坐姿差的初期，觀察到的健康問題可能不多，但疼痛可能之後出現。"},{"en":"If few health problems are observed early, families may wrongly think there is no risk.","zh":"如果早期觀察到的健康問題不多，家庭可能錯誤以為沒有風險。"},{"en":"The phrase warns that hidden problems may develop later.","zh":"這個短語提醒隱藏問題可能日後發展。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":3},{"front":"obese children","meaning":"肥胖兒童","examples":[{"en":"Obese children may develop health problems later in life.","zh":"肥胖兒童可能在日後人生中出現健康問題。"},{"en":"Obese children are children whose body fat is high enough to raise health concerns.","zh":"肥胖兒童是體脂高到引起健康憂慮的兒童。"},{"en":"Schools may support obese children by encouraging activity without teasing or shame.","zh":"學校可以透過鼓勵活動而不取笑或羞辱，來支援肥胖兒童。"},{"en":"If obese children receive help early, some later health risks may be reduced.","zh":"如果肥胖兒童及早得到幫助，一些日後健康風險可能減少。"},{"en":"The phrase should be used carefully and respectfully.","zh":"這個短語使用時應小心和尊重。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":3},{"front":"develop conditions","meaning":"患上疾病；出現健康狀況","examples":[{"en":"Obese children may develop conditions that cause problems later in life.","zh":"肥胖兒童可能出現會在日後人生造成問題的健康狀況。"},{"en":"To develop conditions means to begin to have illnesses or health problems.","zh":"“Develop conditions” 指開始患有疾病或健康問題。"},{"en":"People who sit all day may develop conditions such as back pain or poor circulation.","zh":"整天久坐的人可能出現背痛或血液循環差等健康狀況。"},{"en":"If children develop conditions early, they may need long-term monitoring.","zh":"如果兒童早期患上疾病，可能需要長期監察。"},{"en":"The phrase describes health problems appearing over time.","zh":"這個短語描述健康問題隨時間出現。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":3},{"front":"later in life","meaning":"在日後人生中","examples":[{"en":"Some childhood health conditions cause problems later in life.","zh":"一些兒童健康狀況會在日後人生中造成問題。"},{"en":"Later in life means at a future stage, often during adulthood or older age.","zh":"“Later in life” 指在人生較後階段，通常是成年期或年老時。"},{"en":"A child who learns good study habits may benefit later in life.","zh":"孩子學會良好學習習慣後，日後人生可能受益。"},{"en":"If obesity begins early, some health effects may appear later in life.","zh":"如果肥胖早期開始，一些健康影響可能在日後人生中出現。"},{"en":"The phrase connects early experiences with future consequences.","zh":"這個短語把早期經驗與未來後果連繫起來。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":3},{"front":"high blood pressure","meaning":"高血壓","examples":[{"en":"Obese children may develop high blood pressure.","zh":"肥胖兒童可能患上高血壓。"},{"en":"High blood pressure is a condition in which blood pushes too strongly against artery walls.","zh":"高血壓是一種血液對動脈壁壓力過高的情況。"},{"en":"A doctor may check high blood pressure during a routine health visit.","zh":"醫生可能在例行健康檢查中檢查高血壓。"},{"en":"If high blood pressure continues, it can increase the risk of heart disease later.","zh":"如果高血壓持續，日後可能增加患心臟病的風險。"},{"en":"The phrase refers to a measurable medical problem.","zh":"這個短語指可量度的醫學問題。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":3},{"front":"suffer from","meaning":"患有；受……之苦","examples":[{"en":"Some obese children may suffer from sleep apnoea.","zh":"一些肥胖兒童可能患有睡眠窒息症。"},{"en":"To suffer from a condition means to have it and experience its harmful effects.","zh":"“Suffer from” 某狀況指患有它並經歷其有害影響。"},{"en":"A student may suffer from headaches if they sleep too little.","zh":"如果學生睡得太少，可能受頭痛之苦。"},{"en":"If a child suffers from sleep apnoea, their rest and daytime energy may be affected.","zh":"如果兒童患有睡眠窒息症，他們的休息和日間精力可能受影響。"},{"en":"The phrase is used for illnesses, pain and serious difficulties.","zh":"這個短語用於疾病、疼痛和嚴重困難。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":3},{"front":"sleep apnoea","meaning":"睡眠窒息症","examples":[{"en":"Sleep apnoea can stop a child’s breathing during sleep.","zh":"睡眠窒息症可以令兒童在睡眠期間停止呼吸。"},{"en":"Sleep apnoea is a condition in which breathing repeatedly stops or becomes blocked during sleep.","zh":"睡眠窒息症是一種睡眠期間呼吸反覆停止或受阻的情況。"},{"en":"Parents may notice sleep apnoea if a child snores loudly and wakes up tired.","zh":"如果孩子大聲打鼻鼾並醒來疲倦，父母可能注意到睡眠窒息症。"},{"en":"If sleep apnoea is untreated, it can affect memory, energy and heart health.","zh":"如果睡眠窒息症未經治療，可能影響記憶、精力和心臟健康。"},{"en":"The phrase names a sleep-related breathing disorder.","zh":"這個短語指與睡眠有關的呼吸障礙。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":3},{"front":"soft tissue","meaning":"軟組織","examples":[{"en":"Soft tissue in the throat can block the airways during sleep.","zh":"喉嚨中的軟組織可以在睡眠期間阻塞氣道。"},{"en":"Soft tissue is body material such as muscle, fat or skin, not bone.","zh":"軟組織是肌肉、脂肪或皮膚等身體組織，不是骨骼。"},{"en":"A doctor may examine soft tissue around an injury to check for swelling.","zh":"醫生可能檢查傷處附近的軟組織，以查看是否腫脹。"},{"en":"If soft tissue blocks the throat during sleep, breathing may stop briefly.","zh":"如果軟組織在睡眠期間阻塞喉嚨，呼吸可能短暫停止。"},{"en":"The phrase describes flexible body tissue rather than hard bone.","zh":"這個短語描述柔軟身體組織，而不是堅硬骨骼。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":4},{"front":"block the airways","meaning":"阻塞氣道","examples":[{"en":"Soft tissue in the throat may block the airways.","zh":"喉嚨中的軟組織可能阻塞氣道。"},{"en":"To block the airways means to stop or reduce the flow of air through the breathing passages.","zh":"“Block the airways” 指停止或減少空氣通過呼吸通道。"},{"en":"Food stuck in the throat can block the airways and become an emergency.","zh":"卡在喉嚨的食物可以阻塞氣道，並成為緊急情況。"},{"en":"If airways are blocked during sleep, the person may wake repeatedly without knowing why.","zh":"如果氣道在睡眠期間被阻塞，該人可能反覆醒來而不知道原因。"},{"en":"The phrase describes a serious breathing problem.","zh":"這個短語描述嚴重呼吸問題。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":4},{"front":"during sleep","meaning":"在睡眠期間","examples":[{"en":"Sleep apnoea can block the airways during sleep.","zh":"睡眠窒息症可以在睡眠期間阻塞氣道。"},{"en":"During sleep means while a person is asleep.","zh":"“During sleep” 指在人睡着時。"},{"en":"Children grow and recover energy during sleep.","zh":"兒童在睡眠期間成長並恢復能量。"},{"en":"If breathing is interrupted during sleep, daytime tiredness may follow.","zh":"如果呼吸在睡眠期間被打斷，日間疲倦可能隨之出現。"},{"en":"The phrase identifies when the problem happens.","zh":"這個短語指出問題發生的時間。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":4},{"front":"stop someone’s breathing","meaning":"令某人停止呼吸","examples":[{"en":"Sleep apnoea can stop a child’s breathing for up to a minute.","zh":"睡眠窒息症可以令兒童停止呼吸長達一分鐘。"},{"en":"To stop someone’s breathing means to interrupt the process of breathing.","zh":"“Stop someone’s breathing” 指中斷某人的呼吸過程。"},{"en":"A severe allergic reaction can stop someone’s breathing and needs emergency help.","zh":"嚴重過敏反應可以令某人停止呼吸，並需要緊急協助。"},{"en":"If sleep apnoea stops breathing many times, the body may not get enough oxygen.","zh":"如果睡眠窒息症多次令呼吸停止，身體可能得不到足夠氧氣。"},{"en":"The phrase describes a dangerous interruption to breathing.","zh":"這個短語描述危險的呼吸中斷。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":4},{"front":"for up to a minute","meaning":"長達一分鐘","examples":[{"en":"Sleep apnoea can stop breathing for up to a minute.","zh":"睡眠窒息症可以令呼吸停止長達一分鐘。"},{"en":"For up to a minute means for as long as one minute, but possibly less.","zh":"“For up to a minute” 指最長可達一分鐘，但也可能較短。"},{"en":"A child may hold a yoga pose for up to a minute during class.","zh":"孩子在課堂中可能保持瑜伽姿勢長達一分鐘。"},{"en":"If breathing stops for up to a minute, the event can be frightening and medically serious.","zh":"如果呼吸停止長達一分鐘，情況可能令人害怕且具醫學嚴重性。"},{"en":"The phrase gives a maximum length of time.","zh":"這個短語給出最長時間。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":4},{"front":"hundreds of times a night","meaning":"每晚數百次","examples":[{"en":"This process can happen hundreds of times a night.","zh":"這個過程每晚可以發生數百次。"},{"en":"Hundreds of times a night means very many times during one night.","zh":"“Hundreds of times a night” 指在一晚之內發生非常多次。"},{"en":"A restless sleeper may wake briefly hundreds of times a night without remembering it.","zh":"睡眠不安的人可能每晚短暫醒來數百次，而自己不記得。"},{"en":"If breathing is interrupted hundreds of times a night, sleep quality becomes very poor.","zh":"如果呼吸每晚被中斷數百次，睡眠質素會變得很差。"},{"en":"The phrase stresses frequency and seriousness.","zh":"這個短語強調頻率和嚴重性。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":4},{"front":"lead to heart disease","meaning":"導致心臟病","examples":[{"en":"Repeated breathing problems may lead to heart disease.","zh":"反覆呼吸問題可能導致心臟病。"},{"en":"To lead to heart disease means to increase the risk of developing illness in the heart.","zh":"“Lead to heart disease” 指增加患上心臟疾病的風險。"},{"en":"Long-term high blood pressure can lead to heart disease if it is not controlled.","zh":"如果長期高血壓沒有受控，可能導致心臟病。"},{"en":"If sleep apnoea places stress on the body every night, it may lead to heart problems later.","zh":"如果睡眠窒息症每晚令身體受壓，日後可能導致心臟問題。"},{"en":"The phrase describes a serious possible health consequence.","zh":"這個短語描述嚴重的可能健康後果。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":4},{"front":"memory problems","meaning":"記憶問題","examples":[{"en":"Sleep apnoea may lead to memory problems.","zh":"睡眠窒息症可能導致記憶問題。"},{"en":"Memory problems are difficulties in remembering information, events or instructions.","zh":"記憶問題是記住資料、事件或指示方面的困難。"},{"en":"A student with memory problems may forget homework dates or classroom rules.","zh":"有記憶問題的學生可能忘記功課日期或課室規則。"},{"en":"If poor sleep affects the brain, memory problems may become worse.","zh":"如果睡眠差影響大腦，記憶問題可能變得更嚴重。"},{"en":"The phrase describes trouble with remembering.","zh":"這個短語描述記憶方面的困難。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":4},{"front":"headaches and tiredness","meaning":"頭痛和疲倦","examples":[{"en":"Sleep apnoea can cause headaches and tiredness.","zh":"睡眠窒息症可以造成頭痛和疲倦。"},{"en":"Headaches and tiredness are common symptoms involving head pain and low energy.","zh":"頭痛和疲倦是常見症狀，包括頭部疼痛和精力低下。"},{"en":"A child who sleeps badly may arrive at school with headaches and tiredness.","zh":"睡眠差的孩子可能帶着頭痛和疲倦到校。"},{"en":"If breathing is disturbed at night, headaches and tiredness may appear in the morning.","zh":"如果夜間呼吸受干擾，頭痛和疲倦可能在早上出現。"},{"en":"The phrase describes everyday symptoms that may signal a deeper problem.","zh":"這個短語描述可能顯示深層問題的日常症狀。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":4},{"front":"develop diabetes","meaning":"患上糖尿病","examples":[{"en":"Some obese children may develop diabetes.","zh":"一些肥胖兒童可能患上糖尿病。"},{"en":"To develop diabetes means to begin having a condition in which the body cannot control blood sugar properly.","zh":"“Develop diabetes” 指開始患有身體不能正常控制血糖的疾病。"},{"en":"A doctor may monitor an overweight child carefully in case they develop diabetes.","zh":"醫生可能仔細監察超重兒童，以防他們患上糖尿病。"},{"en":"If children develop diabetes early, they may need treatment for many years.","zh":"如果兒童早期患上糖尿病，可能需要多年治療。"},{"en":"The phrase describes the start of a serious long-term health condition.","zh":"這個短語描述嚴重長期健康狀況的開始。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":4},{"front":"diabetes","meaning":"糖尿病","examples":[{"en":"Diabetes can cause serious long-term health problems.","zh":"糖尿病可以造成嚴重長期健康問題。"},{"en":"Diabetes is a condition in which the body has difficulty controlling blood sugar.","zh":"糖尿病是一種身體難以控制血糖的疾病。"},{"en":"A person with diabetes may need to monitor food, medicine and blood sugar levels.","zh":"患有糖尿病的人可能需要監察食物、藥物和血糖水平。"},{"en":"If diabetes is not treated, it can damage nerves, kidneys and eyes.","zh":"如果糖尿病沒有治療，可能損害神經、腎臟和眼睛。"},{"en":"The word refers to a chronic medical condition, not a short illness.","zh":"這個詞指慢性醫學疾病，而不是短期病。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":4},{"front":"much later in life","meaning":"在人生較後期","examples":[{"en":"Diabetes normally starts much later in life.","zh":"糖尿病通常在人生較後期才開始。"},{"en":"Much later in life means at a far later age or stage than childhood.","zh":"“Much later in life” 指在人生遠較後的年齡或階段。"},{"en":"Some people only face joint pain much later in life after years of heavy work.","zh":"一些人在多年繁重工作後，才在人生較後期面對關節痛。"},{"en":"If a disease appears much earlier than usual, doctors may see it as especially worrying.","zh":"如果疾病比通常時間早得多出現，醫生可能視為尤其令人擔心。"},{"en":"The phrase contrasts early appearance with the usual later timing.","zh":"這個短語把早期出現與通常較後時間作對比。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":5},{"front":"when it strikes","meaning":"當它發病時","examples":[{"en":"When diabetes strikes, the body stops processing sugar properly.","zh":"當糖尿病發病時，身體會停止正常處理糖分。"},{"en":"When a disease strikes means when it begins to affect someone seriously.","zh":"“When a disease strikes” 指疾病開始嚴重影響某人時。"},{"en":"When flu strikes a classroom, many students may be absent at the same time.","zh":"當流感在班房爆發時，許多學生可能同時缺席。"},{"en":"When diabetes strikes, daily habits and medical treatment may need to change.","zh":"當糖尿病發病時，日常習慣和醫療治療可能需要改變。"},{"en":"The phrase makes illness sound sudden or serious.","zh":"這個短語令疾病聽起來突然或嚴重。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":5},{"front":"process sugar properly","meaning":"正常處理糖分","examples":[{"en":"The body stops being able to process sugar properly.","zh":"身體停止能夠正常處理糖分。"},{"en":"To process sugar properly means to use and control sugar in the blood in a healthy way.","zh":"“Process sugar properly” 指以健康方式使用和控制血液中的糖分。"},{"en":"After a meal, a healthy body processes sugar properly and gives cells energy.","zh":"飯後，健康身體會正常處理糖分，並為細胞提供能量。"},{"en":"If the body cannot process sugar properly, blood sugar may become too high.","zh":"如果身體不能正常處理糖分，血糖可能變得過高。"},{"en":"The phrase explains a key problem in diabetes.","zh":"這個短語解釋糖尿病中的關鍵問題。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":5},{"front":"be starved of energy","meaning":"缺乏能量","examples":[{"en":"The cells are starved of energy when sugar is not processed properly.","zh":"當糖分沒有被正常處理時，細胞會缺乏能量。"},{"en":"To be starved of energy means to lack the fuel needed to work properly.","zh":"“Be starved of energy” 指缺乏正常運作所需的燃料。"},{"en":"A tired student may feel starved of energy after skipping breakfast.","zh":"如果學生不吃早餐，可能在之後感到缺乏能量。"},{"en":"If cells cannot use sugar, they may be starved of energy even when food has been eaten.","zh":"如果細胞不能使用糖分，即使已進食，它們也可能缺乏能量。"},{"en":"The phrase describes a lack of usable energy, not simply hunger.","zh":"這個短語描述缺乏可用能量，而不只是飢餓。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":5},{"front":"cannot be cured","meaning":"無法根治","examples":[{"en":"Diabetes cannot be cured, but it can be treated.","zh":"糖尿病無法根治，但可以治療。"},{"en":"Cannot be cured means the disease cannot be completely removed or ended.","zh":"“Cannot be cured” 指疾病不能被完全消除或終止。"},{"en":"Some long-term conditions cannot be cured, so doctors focus on control and care.","zh":"一些長期疾病無法根治，所以醫生集中於控制和照顧。"},{"en":"If diabetes cannot be cured, early prevention becomes especially important.","zh":"如果糖尿病無法根治，早期預防就尤其重要。"},{"en":"The phrase contrasts permanent cure with ongoing treatment.","zh":"這個短語把永久根治與持續治療作對比。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":5},{"front":"can be treated","meaning":"可以治療","examples":[{"en":"Diabetes cannot be cured, but it can be treated.","zh":"糖尿病無法根治，但可以治療。"},{"en":"Can be treated means medical care or lifestyle changes can help manage the condition.","zh":"“Can be treated” 指醫療照顧或生活方式改變可以幫助管理該疾病。"},{"en":"High blood pressure can be treated with medicine, diet and exercise.","zh":"高血壓可以用藥物、飲食和運動治療。"},{"en":"If diabetes can be treated well, serious complications may be reduced.","zh":"如果糖尿病得到良好治療，嚴重併發症可能減少。"},{"en":"The phrase suggests control and management rather than complete cure.","zh":"這個短語暗示控制和管理，而不是完全根治。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":5},{"front":"nerve damage","meaning":"神經損傷","examples":[{"en":"Diabetes may lead to nerve damage.","zh":"糖尿病可能導致神經損傷。"},{"en":"Nerve damage is harm to the nerves that carry messages between the brain and body.","zh":"神經損傷是對負責在大腦和身體之間傳遞訊息的神經造成傷害。"},{"en":"A person with nerve damage may feel numbness, pain or weakness.","zh":"有神經損傷的人可能感到麻木、疼痛或無力。"},{"en":"If diabetes damages nerves, movement and sensation may be affected.","zh":"如果糖尿病損害神經，活動和感覺可能受影響。"},{"en":"The phrase describes a serious possible complication.","zh":"這個短語描述嚴重的可能併發症。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":5},{"front":"kidney disease","meaning":"腎病","examples":[{"en":"Diabetes may lead to kidney disease.","zh":"糖尿病可能導致腎病。"},{"en":"Kidney disease is a condition in which the kidneys do not filter waste from the blood properly.","zh":"腎病是腎臟不能正常從血液中過濾廢物的疾病。"},{"en":"Doctors may test urine and blood to check for kidney disease.","zh":"醫生可能檢查尿液和血液，以查看是否有腎病。"},{"en":"If diabetes damages the kidneys, waste may build up in the body.","zh":"如果糖尿病損害腎臟，廢物可能在身體中累積。"},{"en":"The phrase names a serious long-term health problem.","zh":"這個短語指嚴重長期健康問題。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":5},{"front":"blindness","meaning":"失明","examples":[{"en":"Diabetes may lead to blindness.","zh":"糖尿病可能導致失明。"},{"en":"Blindness is the loss of sight or the inability to see.","zh":"失明是視力喪失或無法看見。"},{"en":"An eye disease may cause blindness if it is not treated early.","zh":"如果眼疾沒有及早治療，可能造成失明。"},{"en":"If diabetes damages blood vessels in the eyes, blindness may become a risk.","zh":"如果糖尿病損害眼部血管，失明可能成為風險。"},{"en":"The word describes a severe loss of vision.","zh":"這個詞描述嚴重視力喪失。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":5},{"front":"live with it all their lives","meaning":"終生與之共存","examples":[{"en":"Children with diabetes may have to live with it all their lives.","zh":"患有糖尿病的兒童可能必須終生與之共存。"},{"en":"To live with it all their lives means to manage a condition for their whole lifetime.","zh":"“Live with it all their lives” 指一生都要管理某種疾病或狀況。"},{"en":"A child with asthma may learn to live with it by using medicine and avoiding triggers.","zh":"患有哮喘的孩子可能透過用藥和避免誘因，學會與之共存。"},{"en":"If diabetes begins early, the child may need long-term habits and medical care.","zh":"如果糖尿病早期開始，孩子可能需要長期習慣和醫療照顧。"},{"en":"The phrase stresses lifelong management.","zh":"這個短語強調終生管理。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":5},{"front":"increase the chance of","meaning":"增加……的機會","examples":[{"en":"Diabetes increases the chance of serious health problems.","zh":"糖尿病增加嚴重健康問題的機會。"},{"en":"To increase the chance of something means to make it more likely to happen.","zh":"“Increase the chance of” 某事指令它更可能發生。"},{"en":"Wearing no helmet can increase the chance of head injury during cycling.","zh":"騎單車不戴頭盔可以增加頭部受傷的機會。"},{"en":"If obesity increases the chance of disease, prevention becomes important.","zh":"如果肥胖增加疾病的機會，預防便變得重要。"},{"en":"The phrase explains higher risk.","zh":"這個短語解釋較高風險。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":5},{"front":"negative body image","meaning":"負面的身體形象","examples":[{"en":"Negative body image can cause depression and social problems.","zh":"負面的身體形象可以造成抑鬱和社交問題。"},{"en":"Negative body image means feeling unhappy, ashamed or critical about one’s own body.","zh":"負面的身體形象指對自己的身體感到不快、羞愧或批判。"},{"en":"A teenager may develop negative body image after being teased about weight or appearance.","zh":"青少年被取笑體重或外貌後，可能形成負面的身體形象。"},{"en":"If negative body image becomes strong, a child may avoid sports, friends or school events.","zh":"如果負面的身體形象變得強烈，孩子可能避開運動、朋友或學校活動。"},{"en":"The phrase connects appearance worries with mental health.","zh":"這個短語把外貌焦慮與心理健康連繫起來。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":6},{"front":"body image","meaning":"身體形象","examples":[{"en":"Body image can affect a child’s mental health.","zh":"身體形象可以影響兒童的心理健康。"},{"en":"Body image is the way a person sees, feels about and thinks about their own body.","zh":"身體形象是一個人如何看待、感受和思考自己的身體。"},{"en":"Social media can affect body image when children compare themselves with edited photos.","zh":"當兒童把自己與修圖照片比較時，社交媒體可以影響身體形象。"},{"en":"If a child has poor body image, confidence and friendships may suffer.","zh":"如果孩子身體形象差，自信和友誼可能受影響。"},{"en":"The phrase is about self-perception, not actual body size only.","zh":"這個短語關乎自我感知，而不只是實際身形。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":6},{"front":"depression","meaning":"抑鬱","examples":[{"en":"Negative body image can cause depression.","zh":"負面的身體形象可以造成抑鬱。"},{"en":"Depression is a mental health condition involving long-lasting sadness, low energy and loss of interest.","zh":"抑鬱是一種心理健康狀況，涉及長期悲傷、低能量和失去興趣。"},{"en":"A student with depression may stop enjoying hobbies and find school harder.","zh":"患有抑鬱的學生可能不再享受興趣，並覺得上學更困難。"},{"en":"If teasing leads to depression, emotional support becomes as important as physical treatment.","zh":"如果取笑導致抑鬱，情緒支援就與身體治療一樣重要。"},{"en":"The word refers to a serious condition, not ordinary short sadness.","zh":"這個詞指嚴重狀況，而不是普通短暫傷心。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":6},{"front":"social problems","meaning":"社交問題","examples":[{"en":"Overweight children may experience social problems.","zh":"超重兒童可能經歷社交問題。"},{"en":"Social problems are difficulties involving relationships, acceptance or participation in group life.","zh":"社交問題是涉及關係、接納或參與群體生活的困難。"},{"en":"A child who is teased at lunch may face social problems at school.","zh":"午膳時被取笑的孩子可能在學校面對社交問題。"},{"en":"If social problems continue, a child may become lonely or avoid classmates.","zh":"如果社交問題持續，孩子可能變得孤獨或避開同學。"},{"en":"The phrase focuses on how a condition affects life with other people.","zh":"這個短語強調某狀況如何影響與他人相處的生活。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":6},{"front":"be teased","meaning":"被取笑","examples":[{"en":"Overweight children are often teased.","zh":"超重兒童經常被取笑。"},{"en":"To be teased means to be laughed at, mocked or made fun of by others.","zh":"“Be teased” 指被別人嘲笑、戲弄或取笑。"},{"en":"A student may be teased for wearing old shoes or speaking with a different accent.","zh":"學生可能因穿舊鞋或帶不同口音而被取笑。"},{"en":"If a child is teased repeatedly, self-esteem and school confidence may fall.","zh":"如果孩子反覆被取笑，自尊和上學信心可能下降。"},{"en":"The phrase can sound light, but the effect can be harmful.","zh":"這個短語聽起來可能輕微，但影響可以很有害。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":6},{"front":"low self-esteem","meaning":"低自尊","examples":[{"en":"Low self-esteem is the biggest problem obese children face in everyday life.","zh":"低自尊是肥胖兒童在日常生活中面對的最大問題。"},{"en":"Low self-esteem means having a poor opinion of oneself and little confidence in one’s worth.","zh":"低自尊指對自己評價低，並對自身價值缺乏信心。"},{"en":"A student with low self-esteem may avoid answering questions even when they know the answer.","zh":"有低自尊的學生即使知道答案，也可能避免回答問題。"},{"en":"If low self-esteem leads to comfort eating, the original problem may become worse.","zh":"如果低自尊導致情緒性進食，原本問題可能變得更嚴重。"},{"en":"The phrase describes emotional harm, not just shyness.","zh":"這個短語描述情緒傷害，而不只是害羞。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":6},{"front":"directly affect","meaning":"直接影響","examples":[{"en":"Low self-esteem may not directly affect physical health.","zh":"低自尊未必直接影響身體健康。"},{"en":"To directly affect something means to influence it immediately or in a clear way.","zh":"“Directly affect” 某事指即時或清楚地影響它。"},{"en":"Poor sleep can directly affect concentration the next morning.","zh":"睡眠不足可以直接影響第二天早上的專注力。"},{"en":"Even if low self-esteem does not directly affect the body, it can influence eating habits.","zh":"即使低自尊不直接影響身體，它也可以影響飲食習慣。"},{"en":"The phrase separates immediate effects from indirect ones.","zh":"這個短語把直接影響與間接影響分開。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":6},{"front":"physical health","meaning":"身體健康","examples":[{"en":"Low self-esteem may not directly affect physical health.","zh":"低自尊未必直接影響身體健康。"},{"en":"Physical health is the condition of the body, including fitness, illness, sleep and energy.","zh":"身體健康是身體狀況，包括體能、疾病、睡眠和精力。"},{"en":"Regular exercise and enough sleep can improve physical health.","zh":"定期運動和足夠睡眠可以改善身體健康。"},{"en":"If childhood obesity affects physical health, doctors may check blood pressure and sugar levels.","zh":"如果兒童肥胖影響身體健康，醫生可能檢查血壓和血糖水平。"},{"en":"The phrase contrasts body health with mental or social health.","zh":"這個短語把身體健康與心理或社交健康作對比。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":6},{"front":"the biggest problem someone faces","meaning":"某人面對的最大問題","examples":[{"en":"Low self-esteem is the biggest problem obese children face.","zh":"低自尊是肥胖兒童面對的最大問題。"},{"en":"The biggest problem someone faces is the most serious difficulty in their situation.","zh":"某人面對的最大問題，是其處境中最嚴重的困難。"},{"en":"For a new immigrant student, the biggest problem they face may be language rather than homework.","zh":"對新移民學生來說，他們面對的最大問題可能是語言，而不是功課。"},{"en":"If low self-esteem is the biggest problem, treatment must include emotional support.","zh":"如果低自尊是最大問題，治療就必須包括情緒支援。"},{"en":"The phrase identifies the main difficulty among several problems.","zh":"這個短語在多個問題中指出主要困難。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":6},{"front":"in everyday life","meaning":"在日常生活中","examples":[{"en":"Low self-esteem affects obese children in everyday life.","zh":"低自尊在日常生活中影響肥胖兒童。"},{"en":"In everyday life means in ordinary daily situations, not only in special events.","zh":"“In everyday life” 指在普通日常情況中，而不只是特殊事件中。"},{"en":"A child’s confidence affects how they speak, play and ask for help in everyday life.","zh":"孩子的信心會影響他們在日常生活中如何說話、玩耍和求助。"},{"en":"If a problem appears in everyday life, it can affect school, home and friendships.","zh":"如果問題在日常生活中出現，就可能影響學校、家庭和友誼。"},{"en":"The phrase connects a problem with daily experience.","zh":"這個短語把問題與日常經驗連繫起來。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":6},{"front":"comfort eating","meaning":"情緒性進食","examples":[{"en":"Low self-esteem may lead to comfort eating.","zh":"低自尊可能導致情緒性進食。"},{"en":"Comfort eating means eating to feel better emotionally rather than because of hunger.","zh":"情緒性進食指為了情緒上好受而進食，而不是因為肚餓。"},{"en":"A stressed student may turn to comfort eating after a difficult school day.","zh":"壓力大的學生可能在艱難上學日後轉向情緒性進食。"},{"en":"If comfort eating becomes a habit, weight problems may become harder to manage.","zh":"如果情緒性進食成為習慣，體重問題可能更難管理。"},{"en":"The phrase links emotions with food choices.","zh":"這個短語把情緒與食物選擇連繫起來。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":6},{"front":"eat to feel good","meaning":"為了令自己好受而進食","examples":[{"en":"Comfort eating means eating to feel good.","zh":"情緒性進食指為了令自己好受而進食。"},{"en":"To eat to feel good means to use food for emotional comfort rather than hunger.","zh":"“Eat to feel good” 指用食物獲得情緒安慰，而不是因為肚餓。"},{"en":"A child may eat to feel good after being teased by classmates.","zh":"孩子被同學取笑後，可能為了令自己好受而進食。"},{"en":"If someone often eats to feel good, food may become a way to escape sadness or stress.","zh":"如果某人經常為了令自己好受而進食，食物可能成為逃避傷心或壓力的方法。"},{"en":"The phrase explains the emotional purpose of comfort eating.","zh":"這個短語解釋情緒性進食的情感目的。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":7},{"front":"make the situation worse","meaning":"令情況惡化","examples":[{"en":"Comfort eating can make the situation worse.","zh":"情緒性進食可以令情況惡化。"},{"en":"To make the situation worse means to increase the problem or create further difficulty.","zh":"“Make the situation worse” 指令問題加劇或造成更多困難。"},{"en":"Ignoring a leaking pipe can make the situation worse because water damage spreads.","zh":"忽視漏水水管可以令情況惡化，因為水浸損害會擴散。"},{"en":"If comfort eating leads to more weight gain, it can deepen shame and stress.","zh":"如果情緒性進食導致更多增重，它可以加深羞愧和壓力。"},{"en":"The phrase describes a negative result that adds to an existing problem.","zh":"這個短語描述為現有問題增添困難的負面結果。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":7},{"front":"modern-day culture","meaning":"現代文化","examples":[{"en":"Modern-day culture places emphasis on the perfect body.","zh":"現代文化強調完美身形。"},{"en":"Modern-day culture means the beliefs, habits and values common in today’s society.","zh":"現代文化指當今社會常見的信念、習慣和價值觀。"},{"en":"Modern-day culture often uses social media images to shape ideas about beauty.","zh":"現代文化常使用社交媒體影像來塑造對美的想法。"},{"en":"If modern-day culture praises only one body type, children may feel pressure.","zh":"如果現代文化只讚美一種身形，兒童可能感到壓力。"},{"en":"The phrase refers to present society, not ancient customs.","zh":"這個短語指現今社會，而不是古代習俗。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":7},{"front":"place less emphasis on","meaning":"較少強調","examples":[{"en":"Society could place less emphasis on the perfect body.","zh":"社會可以較少強調完美身形。"},{"en":"To place less emphasis on something means to treat it as less important.","zh":"“Place less emphasis on” 某事指把它看得較不重要。"},{"en":"Schools could place less emphasis on exam ranking and more on learning habits.","zh":"學校可以較少強調考試排名，而更多強調學習習慣。"},{"en":"If society places less emphasis on body shape, children may feel less shame about appearance.","zh":"如果社會較少強調身形，兒童可能對外貌感到較少羞恥。"},{"en":"The phrase shows a change in priorities.","zh":"這個短語顯示優先次序的改變。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":7},{"front":"the perfect body","meaning":"完美身形","examples":[{"en":"Modern culture often places emphasis on the perfect body.","zh":"現代文化常常強調完美身形。"},{"en":"The perfect body is an unrealistic ideal of how a body should look.","zh":"完美身形是一種不現實的理想，指身體應該如何看起來。"},{"en":"Magazines and social media may make young people chase the perfect body.","zh":"雜誌和社交媒體可能令年輕人追求完美身形。"},{"en":"If children believe they need the perfect body, self-esteem may fall.","zh":"如果兒童相信自己需要完美身形，自尊可能下降。"},{"en":"The phrase usually suggests social pressure rather than real health.","zh":"這個短語通常暗示社會壓力，而不是真正健康。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":7},{"front":"a set of problems","meaning":"一系列問題","examples":[{"en":"One set of problems associated with obesity would disappear.","zh":"與肥胖有關的一系列問題會消失。"},{"en":"A set of problems means a group of related difficulties.","zh":"“A set of problems” 指一組相關困難。"},{"en":"Poor time management can create a set of problems, including stress, late work and weak sleep.","zh":"時間管理差可以造成一系列問題，包括壓力、遲交功課和睡眠差。"},{"en":"If society reduces body-shaming, one set of social problems may become smaller.","zh":"如果社會減少身體羞辱，一系列社交問題可能變小。"},{"en":"The phrase groups several connected problems together.","zh":"這個短語把幾個相關問題歸在一起。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":7},{"front":"be associated with","meaning":"與……有關","examples":[{"en":"Some social problems are associated with obesity.","zh":"一些社交問題與肥胖有關。"},{"en":"To be associated with something means to be connected with it in some way.","zh":"“Be associated with” 某事指以某種方式與它有聯繫。"},{"en":"Long study hours may be associated with tiredness and eye strain.","zh":"長時間學習可能與疲倦和眼睛疲勞有關。"},{"en":"If teasing is associated with obesity, support should address both weight and social treatment.","zh":"如果取笑與肥胖有關，支援就應同時處理體重和社交對待。"},{"en":"The phrase shows connection, not always direct cause.","zh":"這個短語顯示關聯，不一定是直接原因。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":7},{"front":"completely understood","meaning":"被完全理解","examples":[{"en":"The causes of childhood obesity are not yet completely understood.","zh":"兒童肥胖的原因尚未被完全理解。"},{"en":"Completely understood means fully known and clearly explained.","zh":"“Completely understood” 指被完全知道並清楚解釋。"},{"en":"A disease may not be completely understood even after many studies.","zh":"即使經過許多研究，一種疾病可能仍未被完全理解。"},{"en":"If a problem is not completely understood, solutions should be cautious and flexible.","zh":"如果問題未被完全理解，解決方案應謹慎而具彈性。"},{"en":"The phrase shows that knowledge is still incomplete.","zh":"這個短語顯示知識仍不完整。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":7},{"front":"it is clear to scientists that","meaning":"科學家清楚知道","examples":[{"en":"It is clear to scientists that both genes and the environment play a role.","zh":"科學家清楚知道，基因和環境都發揮作用。"},{"en":"It is clear to scientists that means researchers are confident about this point.","zh":"“It is clear to scientists that” 指研究人員對這一點有信心。"},{"en":"It is clear to scientists that sleep affects learning and memory.","zh":"科學家清楚知道睡眠會影響學習和記憶。"},{"en":"If scientists are clear that two factors matter, solutions should consider both of them.","zh":"如果科學家清楚知道兩個因素都重要，解決方案就應考慮兩者。"},{"en":"The phrase introduces a well-supported scientific view.","zh":"這個短語引出有充分支持的科學看法。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":7},{"front":"genes and the environment","meaning":"基因和環境","examples":[{"en":"Genes and the environment both play a role in obesity.","zh":"基因和環境都在肥胖中發揮作用。"},{"en":"Genes and the environment mean inherited biological factors and outside life conditions.","zh":"基因和環境指遺傳生物因素和外在生活條件。"},{"en":"A child’s height is influenced by genes and the environment, including nutrition and health.","zh":"孩子的身高受基因和環境影響，包括營養和健康。"},{"en":"If genes and the environment both matter, blaming only personal choice is too simple.","zh":"如果基因和環境都重要，只責怪個人選擇就過於簡化。"},{"en":"The phrase combines biology with surroundings and lifestyle.","zh":"這個短語結合生物因素與周圍環境和生活方式。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":7},{"front":"play a role","meaning":"發揮作用","examples":[{"en":"Both genes and the environment play a role in obesity.","zh":"基因和環境都在肥胖中發揮作用。"},{"en":"To play a role means to contribute to a situation or result.","zh":"“Play a role” 指對某情況或結果有所貢獻。"},{"en":"Sleep, practice and confidence all play a role in exam performance.","zh":"睡眠、練習和信心都在考試表現中發揮作用。"},{"en":"If fast food and low activity play a role in obesity, prevention must address daily habits.","zh":"如果快餐和低活動量在肥胖中發揮作用，預防就必須處理日常習慣。"},{"en":"The phrase shows that something is one factor among others.","zh":"這個短語顯示某事是眾多因素之一。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":7},{"front":"recent increase in","meaning":"近期……的增加","examples":[{"en":"The recent increase in obesity is linked to environmental factors.","zh":"近期肥胖的增加與環境因素有關。"},{"en":"A recent increase in something is a rise that has happened not long ago.","zh":"“A recent increase in” 某事指不久前發生的上升。"},{"en":"A recent increase in homework complaints may show that students feel overloaded.","zh":"近期功課投訴的增加可能顯示學生感到負擔過重。"},{"en":"If there is a recent increase in childhood obesity, changes in modern lifestyle may be involved.","zh":"如果近期兒童肥胖增加，現代生活方式變化可能牽涉其中。"},{"en":"The phrase points to a new upward trend.","zh":"這個短語指新的上升趨勢。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":8},{"front":"around the world","meaning":"世界各地","examples":[{"en":"Obesity has increased in many countries around the world.","zh":"肥胖在世界各地許多國家增加。"},{"en":"Around the world means in many places globally.","zh":"“Around the world” 指在全球許多地方。"},{"en":"Children around the world now use screens for school, games and entertainment.","zh":"世界各地的兒童現在都使用螢幕上課、玩遊戲和娛樂。"},{"en":"If a health problem rises around the world, local causes may be linked to global changes.","zh":"如果健康問題在世界各地上升，本地原因可能與全球變化有關。"},{"en":"The phrase shows that something is not limited to one country.","zh":"這個短語顯示某事不限於一個國家。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":8},{"front":"be linked to","meaning":"與……有關","examples":[{"en":"The increase in obesity seems to be linked to environmental factors.","zh":"肥胖增加似乎與環境因素有關。"},{"en":"To be linked to something means to be connected with it.","zh":"“Be linked to” 某事指與它有聯繫。"},{"en":"Poor sleep is often linked to low concentration in class.","zh":"睡眠不足常與課堂專注力低有關。"},{"en":"If obesity is linked to environment, changes in food access and activity may matter.","zh":"如果肥胖與環境有關，食物取得和活動量的改變可能重要。"},{"en":"The phrase shows association, not always certain cause.","zh":"這個短語顯示關聯，不一定是確定原因。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":8},{"front":"environmental factors","meaning":"環境因素","examples":[{"en":"Environmental factors contribute to the rise in obesity.","zh":"環境因素促成肥胖上升。"},{"en":"Environmental factors are outside conditions that influence behaviour or health.","zh":"環境因素是影響行為或健康的外在條件。"},{"en":"Safe parks, food prices and school lunch options are environmental factors for children.","zh":"安全公園、食物價格和學校午餐選擇都是兒童的環境因素。"},{"en":"If unhealthy food is cheap and exercise spaces are limited, environmental factors may increase obesity risk.","zh":"如果不健康食物便宜而運動空間有限，環境因素可能增加肥胖風險。"},{"en":"The phrase shifts attention from the individual to surrounding conditions.","zh":"這個短語把注意力由個人轉向周圍條件。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":8},{"front":"physically active","meaning":"身體活動量大的","examples":[{"en":"Many people are much less physically active nowadays.","zh":"現今許多人的身體活動量大大減少。"},{"en":"Physically active means moving the body often through walking, sport, play or exercise.","zh":"“Physically active” 指經常透過步行、運動、玩耍或鍛煉來活動身體。"},{"en":"A child is physically active when they run, swim, cycle or play games outdoors.","zh":"孩子跑步、游泳、踩單車或在戶外玩遊戲時，就是身體活動量大。"},{"en":"If children become less physically active, they may use fewer calories each day.","zh":"如果兒童變得較少身體活動，每天消耗的卡路里可能較少。"},{"en":"The phrase describes movement-based activity, not mental activity.","zh":"這個短語描述身體活動，而不是心理活動。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":8},{"front":"fatty and sugary foods","meaning":"高脂高糖食物","examples":[{"en":"Fatty and sugary foods are more accessible to more people.","zh":"高脂高糖食物對更多人來說更容易取得。"},{"en":"Fatty and sugary foods are foods high in fat, sugar or both.","zh":"高脂高糖食物是脂肪、糖分或兩者含量高的食物。"},{"en":"Cakes, fried snacks and sweet drinks are common fatty and sugary foods.","zh":"蛋糕、炸小食和甜飲都是常見高脂高糖食物。"},{"en":"If fatty and sugary foods are cheap and easy to buy, children may eat them more often.","zh":"如果高脂高糖食物便宜且容易購買，兒童可能更常吃。"},{"en":"The phrase describes foods that can contribute to weight gain when eaten too much.","zh":"這個短語描述過量食用時可能導致增重的食物。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":8},{"front":"be accessible to","meaning":"對……來說容易取得","examples":[{"en":"Fatty and sugary foods are more accessible to people nowadays.","zh":"現今，高脂高糖食物對人們來說更容易取得。"},{"en":"To be accessible to someone means to be easy for them to get, use or reach.","zh":"“Be accessible to” 某人指對他們來說容易取得、使用或接觸。"},{"en":"Public libraries make books accessible to families who cannot buy many books.","zh":"公共圖書館令買不起許多書的家庭容易取得書籍。"},{"en":"If unhealthy snacks are accessible to children every day, they may become a normal choice.","zh":"如果不健康小食每天對兒童來說容易取得，它們可能成為正常選擇。"},{"en":"The phrase focuses on ease of access.","zh":"這個短語強調取得是否容易。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":8},{"front":"average portion sizes","meaning":"平均食物分量","examples":[{"en":"Average portion sizes have become larger.","zh":"平均食物分量變得更大。"},{"en":"Average portion sizes are the usual amounts of food served or eaten per meal.","zh":"平均食物分量是每餐通常供應或食用的食物量。"},{"en":"A restaurant may increase average portion sizes to attract customers who want value for money.","zh":"餐廳可能增加平均食物分量，以吸引想要物有所值的顧客。"},{"en":"If average portion sizes grow, people may eat more without noticing.","zh":"如果平均食物分量增加，人們可能不知不覺吃得更多。"},{"en":"The phrase connects serving size with eating habits.","zh":"這個短語把供應分量與飲食習慣連繫起來。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":8},{"front":"become larger","meaning":"變得更大","examples":[{"en":"Portion sizes have become larger in many restaurants.","zh":"許多餐廳的食物分量變得更大。"},{"en":"Become larger means increase in size, amount or scale.","zh":"“Become larger” 指大小、數量或規模增加。"},{"en":"A class may become larger if more students join after the first week.","zh":"如果更多學生在第一週後加入，班級可能變得更大。"},{"en":"If food portions become larger, calorie intake may rise even when people order the same meal.","zh":"如果食物分量變得更大，即使人們點同一餐，卡路里攝取也可能上升。"},{"en":"The phrase describes growth over time.","zh":"這個短語描述隨時間增長。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":8},{"front":"have more food to eat","meaning":"有更多食物可吃","examples":[{"en":"People have more food to eat than before.","zh":"人們比以前有更多食物可吃。"},{"en":"To have more food to eat means to have a greater amount of food available for meals or snacks.","zh":"“Have more food to eat” 指有更大量食物可供正餐或小食食用。"},{"en":"During a festival, families may have more food to eat than on normal days.","zh":"節日期間，家庭可能比平日有更多食物可吃。"},{"en":"If children have more food to eat and move less, weight gain becomes more likely.","zh":"如果兒童有更多食物可吃而活動較少，增重就更可能發生。"},{"en":"The phrase describes increased food availability.","zh":"這個短語描述食物供應增加。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":8},{"front":"fast-food restaurants","meaning":"快餐店","examples":[{"en":"Fast-food restaurants often serve larger portions.","zh":"快餐店通常提供較大分量。"},{"en":"Fast-food restaurants are places that sell quick meals such as burgers, fries and fried chicken.","zh":"快餐店是售賣漢堡、薯條和炸雞等快速餐點的地方。"},{"en":"Busy families may visit fast-food restaurants when there is little time to cook.","zh":"當沒有太多時間煮飯時，忙碌家庭可能到快餐店用餐。"},{"en":"If fast-food restaurants serve large cheap meals, children may consume more calories.","zh":"如果快餐店提供便宜大份量餐點，兒童可能攝取更多卡路里。"},{"en":"The phrase refers to quick-service food outlets.","zh":"這個短語指快速服務餐飲店。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":8},{"front":"serve larger portions","meaning":"提供更大分量","examples":[{"en":"Restaurants now serve larger portions for little extra money.","zh":"餐廳現在只需少量額外金錢便提供更大分量。"},{"en":"To serve larger portions means to give customers bigger amounts of food.","zh":"“Serve larger portions” 指向顧客提供更多食物。"},{"en":"A café may serve larger portions at lunchtime to attract office workers.","zh":"咖啡店可能在午餐時間提供更大分量，以吸引辦公室員工。"},{"en":"If restaurants serve larger portions, customers may eat more than their bodies need.","zh":"如果餐廳提供更大分量，顧客可能吃得超過身體所需。"},{"en":"The phrase describes how food size is increased by the seller.","zh":"這個短語描述賣方如何增加食物大小。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":9},{"front":"relatively little extra money","meaning":"相對少量的額外金錢","examples":[{"en":"Restaurants serve larger portions for relatively little extra money.","zh":"餐廳以相對少量的額外金錢提供更大分量。"},{"en":"Relatively little extra money means only a small additional cost compared with what is already paid.","zh":"“Relatively little extra money” 指與已支付金額相比，只需少量額外費用。"},{"en":"A cinema may offer a larger drink for relatively little extra money.","zh":"戲院可能以相對少量的額外金錢提供更大杯飲品。"},{"en":"If extra food costs very little, customers may buy more even when they are not very hungry.","zh":"如果額外食物成本很低，顧客即使不太餓也可能買更多。"},{"en":"The phrase explains why upsizing can be tempting.","zh":"這個短語解釋為何加大分量很誘人。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":9},{"front":"calories per mouthful","meaning":"每一口食物的卡路里","examples":[{"en":"Calories per mouthful of food have increased.","zh":"每一口食物的卡路里已經增加。"},{"en":"Calories per mouthful means the amount of energy contained in each bite of food.","zh":"“Calories per mouthful” 指每一口食物所含的能量。"},{"en":"A small bite of cake may contain more calories per mouthful than a large bite of salad.","zh":"一小口蛋糕每一口的卡路里可能比一大口沙律更高。"},{"en":"If calories per mouthful rise, people can gain energy quickly without feeling full.","zh":"如果每一口食物的卡路里上升，人們可以很快攝取能量而未必感到飽。"},{"en":"The phrase connects food density with calorie intake.","zh":"這個短語把食物能量密度與卡路里攝取連繫起來。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":9},{"front":"traditionally","meaning":"傳統上","examples":[{"en":"Traditionally, children have been forced to finish all the food on their plate.","zh":"傳統上，兒童一直被強迫吃完整碟食物。"},{"en":"Traditionally means according to long-established customs or common past practice.","zh":"“Traditionally” 指根據長久建立的習俗或過去常見做法。"},{"en":"Traditionally, many families eat together during important festivals.","zh":"傳統上，許多家庭會在重要節日一起吃飯。"},{"en":"If a habit has been done traditionally, people may continue it without questioning whether it is healthy.","zh":"如果某習慣一直傳統上被實行，人們可能不會質疑它是否健康便繼續做。"},{"en":"The word introduces a practice from the past.","zh":"這個詞引出過去的做法。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":9},{"front":"all over the world","meaning":"世界各地","examples":[{"en":"Children all over the world have been told to finish their food.","zh":"世界各地的兒童都被叫吃完自己的食物。"},{"en":"All over the world means in many countries and regions globally.","zh":"“All over the world” 指在全球許多國家和地區。"},{"en":"Children all over the world learn family rules about food, sleep and manners.","zh":"世界各地的兒童都會學習關於食物、睡眠和禮貌的家庭規則。"},{"en":"If a habit exists all over the world, it may feel normal even when it has problems.","zh":"如果一個習慣存在於世界各地，即使它有問題，也可能感覺正常。"},{"en":"The phrase stresses wide global spread.","zh":"這個短語強調廣泛全球分布。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":9},{"front":"be forced by","meaning":"被……強迫","examples":[{"en":"Children have often been forced by their parents to finish their meals.","zh":"兒童常被父母強迫吃完整餐。"},{"en":"To be forced by someone means to be made to do something because of pressure or authority.","zh":"“Be forced by” 某人指因壓力或權威而被要求做某事。"},{"en":"A student may feel forced by classmates to join an activity they dislike.","zh":"學生可能感到被同學強迫參加自己不喜歡的活動。"},{"en":"If children are forced by adults to eat more, they may stop listening to their own hunger signals.","zh":"如果兒童被成年人強迫吃更多，他們可能停止聆聽自己的飢餓訊號。"},{"en":"The phrase shows pressure, not free choice.","zh":"這個短語顯示壓力，而不是自由選擇。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":9},{"front":"finish all the food on their plate","meaning":"吃完整碟食物","examples":[{"en":"Parents often force children to finish all the food on their plate.","zh":"父母常強迫兒童吃完整碟食物。"},{"en":"To finish all the food on their plate means to eat everything served to them.","zh":"“Finish all the food on their plate” 指吃完所有盛給他們的食物。"},{"en":"A child may feel uncomfortable if they are told to finish all the food even when full.","zh":"如果孩子已經飽了仍被叫吃完整碟食物，可能感到不舒服。"},{"en":"If children must finish every plate, they may learn to ignore fullness signals.","zh":"如果兒童必須每次吃完整碟食物，可能學會忽略飽足訊號。"},{"en":"The phrase describes a common mealtime rule.","zh":"這個短語描述常見用膳規則。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":9},{"front":"force children to eat more","meaning":"強迫兒童吃更多","examples":[{"en":"Parents should not force children to eat more when they are full.","zh":"當兒童已經飽時，父母不應強迫他們吃更多。"},{"en":"To force children to eat more means to pressure them to continue eating after they do not want more food.","zh":"“Force children to eat more” 指在孩子不想再吃後仍施壓要他們繼續進食。"},{"en":"A parent may force a child to eat more because they worry food will be wasted.","zh":"父母可能因擔心浪費食物而強迫孩子吃更多。"},{"en":"If children are forced to eat more, they may lose their natural sense of fullness.","zh":"如果兒童被強迫吃更多，可能失去自然飽足感。"},{"en":"The phrase warns against pressure at mealtimes.","zh":"這個短語提醒不要在用膳時間施壓。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":9},{"front":"lose their ability to","meaning":"失去……的能力","examples":[{"en":"Children could lose their ability to regulate what they eat.","zh":"兒童可能失去調節自己所吃食物的能力。"},{"en":"To lose their ability to do something means to no longer be able to do it well.","zh":"“Lose their ability to” 做某事指不再能夠好好做到該事。"},{"en":"Students may lose their ability to concentrate if they use their phones constantly during study.","zh":"如果學生溫習時不斷使用手機，可能失去專注的能力。"},{"en":"If children are pressured to overeat, they may lose their ability to stop when full.","zh":"如果兒童被施壓過量進食，可能失去飽了便停止的能力。"},{"en":"The phrase describes the weakening or loss of a skill.","zh":"這個短語描述技能減弱或喪失。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":9},{"front":"naturally regulate","meaning":"自然調節","examples":[{"en":"Children need to naturally regulate what they eat.","zh":"兒童需要自然調節自己所吃的東西。"},{"en":"To naturally regulate something means to control it using the body’s own signals without strong outside pressure.","zh":"“Naturally regulate” 某事指不用強烈外在壓力，而是用身體自身訊號控制它。"},{"en":"A child may naturally regulate food intake by stopping when full.","zh":"孩子可能透過飽了便停止來自然調節食量。"},{"en":"If adults ignore a child’s natural regulation, overeating habits may develop.","zh":"如果成年人忽視孩子的自然調節，過量進食習慣可能形成。"},{"en":"The phrase stresses internal control rather than external forcing.","zh":"這個短語強調內在控制，而不是外在強迫。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":9},{"front":"what they eat","meaning":"他們所吃的東西","examples":[{"en":"Children should learn to regulate what they eat.","zh":"兒童應學會調節他們所吃的東西。"},{"en":"What they eat means the food and drink children choose or consume.","zh":"“What they eat” 指兒童選擇或攝取的食物和飲品。"},{"en":"Parents can help children think about what they eat by explaining food groups simply.","zh":"父母可以透過簡單解釋食物類別，幫助孩子思考他們所吃的東西。"},{"en":"If children understand what they eat, they may make healthier choices.","zh":"如果兒童了解自己所吃的東西，可能作出更健康選擇。"},{"en":"The phrase refers to diet content, not only amount.","zh":"這個短語指飲食內容，而不只是分量。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":9},{"front":"wait a few minutes before","meaning":"在……之前等幾分鐘","examples":[{"en":"Parents should wait a few minutes before serving a second portion.","zh":"父母應在提供第二份食物之前等幾分鐘。"},{"en":"To wait a few minutes before doing something means to pause briefly before taking the next action.","zh":"“Wait a few minutes before” 做某事指在採取下一步前短暫停頓。"},{"en":"A teacher may wait a few minutes before giving hints so students can think first.","zh":"老師可能在給提示前等幾分鐘，讓學生先思考。"},{"en":"If parents wait before giving more food, the child’s fullness signal may reach the brain.","zh":"如果父母在給更多食物前等一等，孩子的飽足訊號可能到達大腦。"},{"en":"The phrase suggests patience before acting.","zh":"這個短語暗示行動前要有耐性。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":10},{"front":"serve a second portion","meaning":"提供第二份食物","examples":[{"en":"Parents should wait before serving a second portion of food.","zh":"父母應在提供第二份食物之前等待。"},{"en":"To serve a second portion means to give another helping of food after the first one.","zh":"“Serve a second portion” 指在第一份後再給另一份食物。"},{"en":"A child may ask for a second portion of rice if they are still hungry.","zh":"如果孩子仍然肚餓，可能要求第二份飯。"},{"en":"If parents serve a second portion too quickly, the child may eat before feeling full.","zh":"如果父母太快提供第二份食物，孩子可能在感到飽之前已經吃下去。"},{"en":"The phrase refers to giving more food after the first serving.","zh":"這個短語指第一份之後再給更多食物。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":10},{"front":"at mealtimes","meaning":"在用膳時間","examples":[{"en":"Parents should avoid pressuring children at mealtimes.","zh":"父母應避免在用膳時間向兒童施壓。"},{"en":"At mealtimes means during breakfast, lunch, dinner or other eating periods.","zh":"“At mealtimes” 指在早餐、午餐、晚餐或其他進食時間。"},{"en":"Families can talk calmly at mealtimes so children do not feel stressed around food.","zh":"家庭可以在用膳時間平靜交談，讓兒童不會因食物感到壓力。"},{"en":"If children feel pressure at mealtimes, eating may become emotional rather than natural.","zh":"如果兒童在用膳時間感到壓力，進食可能變得情緒化而非自然。"},{"en":"The phrase identifies the time when food habits are formed.","zh":"這個短語指出飲食習慣形成的時間。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":10},{"front":"it takes some time for","meaning":"……需要一些時間","examples":[{"en":"It takes some time for fullness messages to reach the brain.","zh":"飽足訊息到達大腦需要一些時間。"},{"en":"It takes some time for something to happen means it does not happen immediately.","zh":"“It takes some time for” 某事發生指它不會即時發生。"},{"en":"It takes some time for a new student to feel comfortable in class.","zh":"新學生需要一些時間才在班上感到自在。"},{"en":"If fullness messages need time, eating slowly can help prevent overeating.","zh":"如果飽足訊息需要時間，慢慢吃可以幫助防止過量進食。"},{"en":"The phrase explains a delay between action and result.","zh":"這個短語解釋行動與結果之間的延遲。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":10},{"front":"have had enough to eat","meaning":"已經吃夠","examples":[{"en":"The body sends messages when we have had enough to eat.","zh":"當我們已經吃夠時，身體會發出訊息。"},{"en":"To have had enough to eat means to have eaten enough food and no longer need more.","zh":"“Have had enough to eat” 指已吃下足夠食物，不再需要更多。"},{"en":"A child may say they have had enough to eat even if food remains on the plate.","zh":"即使碟上仍有食物，孩子也可能說自己已經吃夠。"},{"en":"If adults ignore this signal, children may eat beyond fullness.","zh":"如果成年人忽視這個訊號，兒童可能吃到超過飽足。"},{"en":"The phrase describes physical fullness, not politeness.","zh":"這個短語描述身體飽足，而不是禮貌。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":10},{"front":"reach the brain","meaning":"到達大腦","examples":[{"en":"Fullness messages take time to reach the brain.","zh":"飽足訊息需要時間到達大腦。"},{"en":"To reach the brain means to arrive at the brain as a signal or message.","zh":"“Reach the brain” 指作為訊號或訊息到達大腦。"},{"en":"Pain signals reach the brain after a person touches something hot.","zh":"人碰到熱物後，痛楚訊號會到達大腦。"},{"en":"If fullness messages have not reached the brain yet, a child may keep eating.","zh":"如果飽足訊息尚未到達大腦，孩子可能繼續進食。"},{"en":"The phrase describes how body signals are communicated.","zh":"這個短語描述身體訊號如何傳達。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":10},{"front":"another global tradition","meaning":"另一個全球傳統","examples":[{"en":"Another global tradition is giving children food as a reward.","zh":"另一個全球傳統是把食物作為獎勵給孩子。"},{"en":"Another global tradition means one more common custom found in many parts of the world.","zh":"“Another global tradition” 指世界許多地方都能找到的另一種常見習俗。"},{"en":"Another global tradition is celebrating birthdays with sweet food or special meals.","zh":"另一個全球傳統是用甜食或特別餐點慶祝生日。"},{"en":"If a tradition is global, many families may follow it without questioning its effects.","zh":"如果一項傳統是全球性的，許多家庭可能不質疑其影響便跟從。"},{"en":"The phrase introduces an additional worldwide habit.","zh":"這個短語引入另一個全球習慣。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":10},{"front":"give someone something as a reward","meaning":"把……作為獎勵給某人","examples":[{"en":"Some parents give children their favourite food as a reward.","zh":"一些父母把孩子最喜歡的食物作為獎勵給他們。"},{"en":"To give someone something as a reward means to give it because they behaved well or achieved something.","zh":"“Give someone something as a reward” 指因某人表現好或取得成就而給他某物。"},{"en":"A teacher may give students stickers as a reward for careful work.","zh":"老師可能把貼紙作為獎勵給做事細心的學生。"},{"en":"If parents give sweets as rewards, children may learn to value sweets more highly.","zh":"如果父母把甜食作為獎勵給孩子，孩子可能學會更高度重視甜食。"},{"en":"The phrase describes reward-giving, not ordinary sharing.","zh":"這個短語描述給予獎勵，而不是普通分享。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":10},{"front":"favourite food","meaning":"最喜歡的食物","examples":[{"en":"Children may receive their favourite food as a reward.","zh":"兒童可能收到最喜歡的食物作為獎勵。"},{"en":"Favourite food is the food someone likes most.","zh":"最喜歡的食物是某人最喜愛的食物。"},{"en":"A child’s favourite food may be noodles, pizza, mangoes or ice cream.","zh":"孩子最喜歡的食物可能是麵、薄餅、芒果或雪糕。"},{"en":"If favourite food is always used as a reward, it may become emotionally powerful.","zh":"如果最喜歡的食物總被用作獎勵，它可能變得情緒上很有力量。"},{"en":"The phrase describes personal food preference.","zh":"這個短語描述個人食物偏好。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":10},{"front":"good behaviour","meaning":"良好行為","examples":[{"en":"Parents may reward children for good behaviour.","zh":"父母可能因兒童良好行為而獎勵他們。"},{"en":"Good behaviour means acting politely, safely or responsibly.","zh":"良好行為指有禮、安全或負責任地行動。"},{"en":"A teacher may praise good behaviour when students listen and help each other.","zh":"當學生聆聽並互相幫助時，老師可能讚賞良好行為。"},{"en":"If food is always given for good behaviour, children may connect snacks with approval.","zh":"如果食物總是因良好行為而給予，兒童可能把零食與認可連繫起來。"},{"en":"The phrase refers to actions adults consider positive.","zh":"這個短語指成年人認為正面的行動。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":10},{"front":"good grades at school","meaning":"在學校取得好成績","examples":[{"en":"Some children receive food rewards for good grades at school.","zh":"一些兒童因在學校取得好成績而得到食物獎勵。"},{"en":"Good grades at school are high marks or strong academic results.","zh":"在學校取得好成績指獲得高分或良好學業成果。"},{"en":"Parents may celebrate good grades at school with praise or a family activity.","zh":"父母可能用讚賞或家庭活動慶祝孩子在學校取得好成績。"},{"en":"If good grades are rewarded only with food, children may link achievement with eating treats.","zh":"如果好成績只用食物獎勵，兒童可能把成就與吃零食連繫起來。"},{"en":"The phrase refers to academic success.","zh":"這個短語指學業成功。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":10},{"front":"food as a reward","meaning":"以食物作為獎勵","examples":[{"en":"Using food as a reward is never a good idea.","zh":"以食物作為獎勵從來不是好主意。"},{"en":"Food as a reward means giving food to praise behaviour or achievement.","zh":"以食物作為獎勵指用食物來表揚行為或成就。"},{"en":"A parent may use chocolate as a reward after homework is finished.","zh":"父母可能在孩子完成功課後用朱古力作為獎勵。"},{"en":"If food as a reward becomes common, children may value treat foods too highly.","zh":"如果以食物作為獎勵變得常見，兒童可能過度重視獎勵性食物。"},{"en":"The phrase warns that food can become tied to emotions and approval.","zh":"這個短語提醒食物可能與情緒和認可綁在一起。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":11},{"front":"learn to value","meaning":"學會重視","examples":[{"en":"Children may learn to value particular treat foods.","zh":"兒童可能學會重視某些獎勵性食物。"},{"en":"To learn to value something means to begin seeing it as important, desirable or special.","zh":"“Learn to value” 某事指開始把它視為重要、想要或特別。"},{"en":"Students may learn to value reading when books are connected to their interests.","zh":"當書籍與學生興趣相連，他們可能學會重視閱讀。"},{"en":"If children receive sweets as prizes, they may learn to value sweets more than healthy food.","zh":"如果兒童收到甜食作為獎品，可能學會比健康食物更重視甜食。"},{"en":"The phrase describes how attitudes are formed over time.","zh":"這個短語描述態度如何隨時間形成。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":11},{"front":"treat foods","meaning":"獎勵性食物；零食","examples":[{"en":"Children may learn to value particular treat foods.","zh":"兒童可能學會重視某些獎勵性食物。"},{"en":"Treat foods are special foods, often sweet or rich, eaten for pleasure rather than daily nutrition.","zh":"獎勵性食物是特別食物，通常較甜或較濃味，為享受而吃，而不是為日常營養而吃。"},{"en":"Ice cream, sweets and crisps can be treat foods for many children.","zh":"雪糕、糖果和薯片都可以是許多兒童的獎勵性食物。"},{"en":"If treat foods are used too often as rewards, they may become too emotionally important.","zh":"如果獎勵性食物過度用作獎勵，它們可能在情緒上變得太重要。"},{"en":"The phrase describes occasional pleasure foods, not everyday balanced meals.","zh":"這個短語描述偶爾享受的食物，而不是日常均衡膳食。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":11},{"front":"turn to food for comfort","meaning":"以食物尋求安慰","examples":[{"en":"Children may turn to food for comfort.","zh":"兒童可能以食物尋求安慰。"},{"en":"To turn to food for comfort means to eat in order to feel calmer, safer or less upset.","zh":"“Turn to food for comfort” 指為了感到更平靜、安全或不那麼難過而進食。"},{"en":"A child may turn to food for comfort after an argument with friends.","zh":"孩子與朋友爭吵後，可能以食物尋求安慰。"},{"en":"If children often turn to food for comfort, they may not learn other ways to handle emotions.","zh":"如果兒童經常以食物尋求安慰，可能學不會其他處理情緒的方法。"},{"en":"The phrase describes emotional dependence on eating.","zh":"這個短語描述對進食的情緒依賴。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":11},{"front":"non-food rewards","meaning":"非食物獎勵","examples":[{"en":"Parents should use non-food rewards instead.","zh":"父母應改用非食物獎勵。"},{"en":"Non-food rewards are rewards that do not involve giving something to eat.","zh":"非食物獎勵是不涉及給食物的獎勵。"},{"en":"Praise, extra playtime and a family walk can be non-food rewards.","zh":"讚賞、額外玩耍時間和家庭散步都可以是非食物獎勵。"},{"en":"If parents use non-food rewards, children may not link success with sugary snacks.","zh":"如果父母使用非食物獎勵，兒童可能不會把成功與高糖小食連繫起來。"},{"en":"The phrase encourages healthier ways to motivate children.","zh":"這個短語鼓勵以較健康方式激勵兒童。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":11},{"front":"material rewards","meaning":"物質獎勵","examples":[{"en":"Rewards do not need to be large material rewards.","zh":"獎勵不需要是大型物質獎勵。"},{"en":"Material rewards are physical items given as prizes, such as toys, money or gifts.","zh":"物質獎勵是作為獎品給予的實體物件，例如玩具、金錢或禮物。"},{"en":"A small sticker can be a material reward, while praise is not.","zh":"小貼紙可以是物質獎勵，而讚賞則不是。"},{"en":"If parents depend only on material rewards, children may expect gifts for every good action.","zh":"如果父母只依賴物質獎勵，兒童可能期待每個良好行為都有禮物。"},{"en":"The phrase contrasts physical rewards with emotional rewards like praise.","zh":"這個短語把實體獎勵與讚賞等情感獎勵作對比。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":11},{"front":"one of the best motivators","meaning":"最好的激勵因素之一","examples":[{"en":"One of the best motivators is praise.","zh":"最好的激勵因素之一是讚賞。"},{"en":"One of the best motivators means one of the strongest things that encourages people to act.","zh":"“One of the best motivators” 指最能鼓勵人行動的因素之一。"},{"en":"For many students, clear praise is one of the best motivators to keep practising.","zh":"對許多學生來說，清晰讚賞是讓他們持續練習的最佳激勵因素之一。"},{"en":"If praise motivates children better than sweets, parents can reward effort without using food.","zh":"如果讚賞比甜食更能激勵兒童，父母就可以不用食物來獎勵努力。"},{"en":"The phrase identifies a powerful source of motivation.","zh":"這個短語指出強大的動力來源。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":11},{"front":"praise","meaning":"讚賞","examples":[{"en":"Praise can be an effective non-food reward.","zh":"讚賞可以是有效的非食物獎勵。"},{"en":"Praise is spoken or written approval that recognises someone’s effort or behaviour.","zh":"讚賞是用口頭或書面方式認可某人的努力或行為。"},{"en":"A teacher may give praise when a quiet student tries to answer a question.","zh":"當安靜學生嘗試回答問題時，老師可能給予讚賞。"},{"en":"If children receive honest praise, they may feel valued without needing food rewards.","zh":"如果兒童得到真誠讚賞，可能不需要食物獎勵也感到被重視。"},{"en":"The word describes encouragement through positive words.","zh":"這個詞描述透過正面說話作鼓勵。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":11},{"front":"tell someone off for","meaning":"因……責罵某人","examples":[{"en":"Parents should not tell their child off for being fat.","zh":"父母不應因孩子肥胖而責罵他們。"},{"en":"To tell someone off for something means to scold or criticise them because of it.","zh":"“Tell someone off for” 某事指因該事責罵或批評某人。"},{"en":"A teacher may tell a student off for shouting during class.","zh":"老師可能因學生上課大叫而責罵他。"},{"en":"If parents tell a child off for weight, the child may feel ashamed rather than supported.","zh":"如果父母因體重責罵孩子，孩子可能感到羞愧，而不是得到支持。"},{"en":"The phrase describes criticism, often from someone in authority.","zh":"這個短語描述批評，通常來自有權威的人。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":11},{"front":"feel upset about","meaning":"因……感到難過","examples":[{"en":"A child may already feel upset about their weight.","zh":"孩子可能已經因自己的體重感到難過。"},{"en":"To feel upset about something means to feel sad, worried or hurt because of it.","zh":"“Feel upset about” 某事指因它感到傷心、擔心或受傷。"},{"en":"A student may feel upset about a low test mark even before anyone mentions it.","zh":"學生可能在任何人提起前，已經因低分感到難過。"},{"en":"If a child already feels upset about weight, criticism can deepen the pain.","zh":"如果孩子已經因體重感到難過，批評可能加深痛苦。"},{"en":"The phrase describes an emotional reaction to a problem.","zh":"這個短語描述對問題的情緒反應。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":11},{"front":"add to the problem","meaning":"令問題加劇","examples":[{"en":"Telling a child off may add to the problem.","zh":"責罵孩子可能令問題加劇。"},{"en":"To add to the problem means to make the existing difficulty worse.","zh":"“Add to the problem” 指令現有困難變得更糟。"},{"en":"Shouting at a nervous speaker may add to the problem by increasing anxiety.","zh":"對緊張的演講者大叫，可能透過增加焦慮而令問題加劇。"},{"en":"If criticism increases shame, it adds to the problem instead of solving it.","zh":"如果批評增加羞恥感，它就是令問題加劇，而不是解決問題。"},{"en":"The phrase shows that a response can unintentionally worsen a situation.","zh":"這個短語顯示回應可能無意中令情況惡化。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":11},{"front":"single out","meaning":"單獨挑出","examples":[{"en":"Parents should not single out one child as the problem.","zh":"父母不應把一個孩子單獨挑出來視為問題。"},{"en":"To single out someone means to choose one person from a group for special attention, often negatively.","zh":"“Single out” 某人指從群體中挑出一人特別關注，常帶負面意思。"},{"en":"A teacher should not single out one student for every classroom mistake.","zh":"老師不應每次課室錯誤都單獨挑出一名學生。"},{"en":"If parents single out one child, that child may feel blamed and isolated.","zh":"如果父母單獨挑出一個孩子，該孩子可能感到被責怪和孤立。"},{"en":"The phrase warns against unfairly focusing on one person.","zh":"這個短語提醒不要不公平地集中於一個人。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":12},{"front":"the one with the problem","meaning":"有問題的那個人","examples":[{"en":"Parents should not treat one child as the one with the problem.","zh":"父母不應把一個孩子視為有問題的那個人。"},{"en":"The one with the problem means the person seen as responsible for or defined by the difficulty.","zh":"“The one with the problem” 指被視為對困難負責或被困難定義的人。"},{"en":"In a family argument, one child should not always be labelled as the one with the problem.","zh":"在家庭爭執中，不應總把一個孩子標籤為有問題的那個人。"},{"en":"If one child is treated as the problem, the whole family may ignore shared habits.","zh":"如果一個孩子被視為問題所在，全家可能忽視共同習慣。"},{"en":"The phrase warns against blame and labelling.","zh":"這個短語提醒不要責怪和貼標籤。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":12},{"front":"introduce healthier meals","meaning":"引入較健康的膳食","examples":[{"en":"Parents should introduce healthier meals to the whole family.","zh":"父母應向全家人引入較健康的膳食。"},{"en":"To introduce healthier meals means to begin serving meals with better nutrition and less unhealthy food.","zh":"“Introduce healthier meals” 指開始提供營養較好、較少不健康食物的膳食。"},{"en":"A family may introduce healthier meals by adding vegetables and reducing fried food.","zh":"家庭可能透過加入蔬菜和減少炸食來引入較健康的膳食。"},{"en":"If healthier meals are introduced for everyone, one child is less likely to feel blamed.","zh":"如果較健康的膳食是為所有人引入，一個孩子就較不可能感到被責怪。"},{"en":"The phrase describes a practical change in family eating.","zh":"這個短語描述家庭飲食中的實際改變。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":12},{"front":"the whole family","meaning":"全家人","examples":[{"en":"Healthier meals should be introduced to the whole family.","zh":"較健康的膳食應引入給全家人。"},{"en":"The whole family means every family member, not only one person.","zh":"全家人指每位家庭成員，而不只是其中一人。"},{"en":"The whole family may go for a walk after dinner to build healthier habits together.","zh":"全家人可能晚飯後一起散步，以共同建立較健康習慣。"},{"en":"If the whole family changes, the child receives support instead of blame.","zh":"如果全家人一起改變，孩子得到的是支持而不是責怪。"},{"en":"The phrase stresses shared responsibility.","zh":"這個短語強調共同責任。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":12},{"front":"make healthy changes to","meaning":"對……作出健康改變","examples":[{"en":"Everyone can make healthy changes to their lifestyle.","zh":"每個人都可以對自己的生活方式作出健康改變。"},{"en":"To make healthy changes to something means to adjust it in ways that improve health.","zh":"“Make healthy changes to” 某事指以改善健康的方式調整它。"},{"en":"A student can make healthy changes to their routine by sleeping earlier and eating breakfast.","zh":"學生可以透過早睡和吃早餐，對自己的日常習慣作出健康改變。"},{"en":"If a family makes healthy changes together, children may follow more easily.","zh":"如果家庭一起作出健康改變，兒童可能更容易跟隨。"},{"en":"The phrase describes positive, practical improvement.","zh":"這個短語描述正面而實際的改善。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":12},{"front":"lifestyle","meaning":"生活方式","examples":[{"en":"The whole family can make healthy changes to their lifestyle.","zh":"全家人可以對自己的生活方式作出健康改變。"},{"en":"Lifestyle is the way a person or family lives, including food, sleep, activity and daily habits.","zh":"生活方式是一個人或家庭生活的方式，包括食物、睡眠、活動和日常習慣。"},{"en":"A busy lifestyle may leave little time for cooking or exercise.","zh":"忙碌生活方式可能令煮飯或運動時間很少。"},{"en":"If lifestyle changes are small and realistic, they are easier to maintain.","zh":"如果生活方式改變細小而現實，就較容易維持。"},{"en":"The phrase describes everyday patterns, not one single choice.","zh":"這個短語描述日常模式，而不是單一選擇。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":12},{"front":"be worth doing","meaning":"值得做","examples":[{"en":"It is not worth forbidding fattening foods.","zh":"禁止致肥食物並不值得做。"},{"en":"Be worth doing means be useful or valuable enough to do.","zh":"“Be worth doing” 指某事有足夠用途或價值，值得去做。"},{"en":"It is worth checking homework before submitting it because small mistakes can be fixed.","zh":"交功課前檢查是值得做的，因為小錯誤可以被修正。"},{"en":"If banning a food makes children want it more, the ban may not be worth doing.","zh":"如果禁止某食物令兒童更想要它，該禁令可能不值得做。"},{"en":"The phrase judges whether an action gives enough benefit.","zh":"這個短語判斷行動是否有足夠好處。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":12},{"front":"forbid fattening foods","meaning":"禁止致肥食物","examples":[{"en":"Forbidding fattening foods can make them seem more attractive.","zh":"禁止致肥食物可以令它們看起來更吸引。"},{"en":"To forbid fattening foods means to ban foods that are likely to cause weight gain.","zh":"“Forbid fattening foods” 指禁止容易導致增重的食物。"},{"en":"Parents may forbid sweets at home, but children may then want them more at parties.","zh":"父母可能在家禁止甜食，但兒童之後在派對上可能更想要它們。"},{"en":"If forbidden foods become exciting, strict bans may backfire.","zh":"如果被禁止的食物變得令人興奮，嚴格禁令可能適得其反。"},{"en":"The phrase describes a restrictive approach to eating.","zh":"這個短語描述限制性的飲食方法。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":12},{"front":"fattening foods","meaning":"容易令人肥胖的食物","examples":[{"en":"Fattening foods may seem more attractive when they are forbidden.","zh":"容易令人肥胖的食物在被禁止時可能看起來更吸引。"},{"en":"Fattening foods are foods that can easily contribute to weight gain when eaten often or in large amounts.","zh":"容易令人肥胖的食物是經常或大量食用時容易導致增重的食物。"},{"en":"Fried snacks, sugary drinks and rich desserts can be fattening foods.","zh":"炸小食、含糖飲品和濃甜品都可以是容易令人肥胖的食物。"},{"en":"If children eat fattening foods every day, calorie intake may rise quickly.","zh":"如果兒童每天吃容易令人肥胖的食物，卡路里攝取可能迅速上升。"},{"en":"The phrase describes a risk when such foods are eaten too much.","zh":"這個短語描述過量食用這類食物時的風險。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":12},{"front":"make something seem more attractive","meaning":"令……看起來更吸引","examples":[{"en":"Forbidding certain foods can make them seem more attractive.","zh":"禁止某些食物可以令它們看起來更吸引。"},{"en":"To make something seem more attractive means to cause it to look more desirable or interesting.","zh":"“Make something seem more attractive” 指令某物看起來更令人想要或更有趣。"},{"en":"A limited-time offer can make a product seem more attractive to shoppers.","zh":"限時優惠可以令產品對購物者看起來更吸引。"},{"en":"If parents ban sweets completely, the ban may make sweets seem more attractive.","zh":"如果父母完全禁止甜食，禁令可能令甜食看起來更吸引。"},{"en":"The phrase explains how attention or desire can be increased.","zh":"這個短語解釋注意力或慾望如何增加。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":12},{"front":"teach someone about","meaning":"教導某人有關……","examples":[{"en":"Parents should teach their child about the health value of foods.","zh":"父母應教導孩子有關食物的健康價值。"},{"en":"To teach someone about something means to explain it so they understand it better.","zh":"“Teach someone about” 某事指解釋它，讓某人更好理解。"},{"en":"A nurse may teach children about washing hands before meals.","zh":"護士可能教導兒童有關飯前洗手。"},{"en":"If parents teach children about nutrition, children may make wiser choices later.","zh":"如果父母教導孩子有關營養，孩子日後可能作出更明智選擇。"},{"en":"The phrase focuses on education, not orders.","zh":"這個短語強調教育，而不是命令。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":12},{"front":"health value","meaning":"健康價值","examples":[{"en":"Children should learn about the health value of foods.","zh":"兒童應學習有關食物的健康價值。"},{"en":"Health value means the benefit a food or habit gives to the body.","zh":"健康價值指食物或習慣對身體帶來的益處。"},{"en":"Fruit has health value because it can provide vitamins, fibre and water.","zh":"水果有健康價值，因為它可以提供維他命、纖維和水分。"},{"en":"If children understand health value, they may see healthy food as useful rather than boring.","zh":"如果兒童理解健康價值，可能把健康食物視為有用，而不是沉悶。"},{"en":"The phrase focuses on nutrition and wellbeing.","zh":"這個短語強調營養和身心健康。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":13},{"front":"be rich in","meaning":"富含……","examples":[{"en":"Parents should teach children about foods that are rich in vitamins and nutrients.","zh":"父母應教導兒童有關富含維他命和營養素的食物。"},{"en":"To be rich in something means to contain a large amount of it.","zh":"“Be rich in” 某物指含有大量該物質。"},{"en":"Oranges are rich in vitamin C, and beans are rich in fibre.","zh":"橙富含維他命C，豆類富含纖維。"},{"en":"If meals are rich in nutrients, children may get energy and support for growth.","zh":"如果膳食富含營養素，兒童可能得到能量和成長支援。"},{"en":"The phrase is often used to describe healthy food content.","zh":"這個短語常用來描述健康食物成分。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":13},{"front":"vitamins and nutrients","meaning":"維他命和營養素","examples":[{"en":"Healthy foods are often rich in vitamins and nutrients.","zh":"健康食物通常富含維他命和營養素。"},{"en":"Vitamins and nutrients are substances in food that help the body grow, repair and stay healthy.","zh":"維他命和營養素是食物中幫助身體成長、修復和保持健康的物質。"},{"en":"Vegetables, fruit, beans and fish can provide vitamins and nutrients.","zh":"蔬菜、水果、豆類和魚可以提供維他命和營養素。"},{"en":"If children lack vitamins and nutrients, growth and energy may be affected.","zh":"如果兒童缺乏維他命和營養素，成長和精力可能受影響。"},{"en":"The phrase refers to useful food components, not just calories.","zh":"這個短語指有用的食物成分，而不只是卡路里。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":13},{"front":"healthy food zone","meaning":"健康食物區","examples":[{"en":"Parents can make their home a healthy food zone.","zh":"父母可以把家中變成健康食物區。"},{"en":"A healthy food zone is a place where healthy food is easy to find and unhealthy snacks are limited.","zh":"健康食物區是容易找到健康食物，而不健康小食受限制的地方。"},{"en":"A kitchen can become a healthy food zone if fruit, water and simple meals are available.","zh":"如果有水果、水和簡單膳食，廚房可以變成健康食物區。"},{"en":"If the home is a healthy food zone, children make better choices without constant arguments.","zh":"如果家中是健康食物區，兒童不用經常爭辯也能作出較好選擇。"},{"en":"The phrase describes an environment designed to support healthy eating.","zh":"這個短語描述旨在支援健康飲食的環境。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":13},{"front":"fill up","meaning":"裝滿","examples":[{"en":"Parents should fill up the fruit bowl instead of buying snacks.","zh":"父母應裝滿水果碗，而不是購買零食。"},{"en":"To fill up something means to put enough items into it until it is full or nearly full.","zh":"“Fill up” 某物指放入足夠物品，直到它滿或接近滿。"},{"en":"A student may fill up a water bottle before a long lesson.","zh":"學生可能在長課前裝滿水樽。"},{"en":"If parents fill up the fruit bowl, children are more likely to see fruit first.","zh":"如果父母裝滿水果碗，兒童更可能先看見水果。"},{"en":"The phrase describes making something full and ready to use.","zh":"這個短語描述令某物變滿並可供使用。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":13},{"front":"fruit bowl","meaning":"水果碗","examples":[{"en":"Parents can fill up the fruit bowl to encourage healthy eating.","zh":"父母可以裝滿水果碗，以鼓勵健康飲食。"},{"en":"A fruit bowl is a bowl used to hold fruit where people can easily see and take it.","zh":"水果碗是用來盛載水果、讓人容易看見和拿取的碗。"},{"en":"A fruit bowl on the table may remind children to choose an apple instead of biscuits.","zh":"桌上的水果碗可能提醒兒童選擇蘋果，而不是餅乾。"},{"en":"If the fruit bowl is empty, children may look for crisps or sweets instead.","zh":"如果水果碗是空的，兒童可能改為尋找薯片或糖果。"},{"en":"The phrase describes a simple home tool for healthy eating.","zh":"這個短語描述家中支援健康飲食的簡單工具。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":13},{"front":"instead of buying","meaning":"而不是購買","examples":[{"en":"Parents should buy fruit instead of buying biscuits and crisps.","zh":"父母應購買水果，而不是購買餅乾和薯片。"},{"en":"Instead of buying something means choosing another option and not buying that item.","zh":"“Instead of buying” 某物指選擇另一選項，而不購買該物。"},{"en":"A student may borrow a book instead of buying it to save money.","zh":"學生可能借書而不是購買，以節省金錢。"},{"en":"If parents buy fruit instead of snacks, healthier food becomes more available at home.","zh":"如果父母購買水果而不是零食，家中健康食物就更容易取得。"},{"en":"The phrase clearly shows replacement.","zh":"這個短語清楚顯示替代。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":13},{"front":"biscuits and crisps","meaning":"餅乾和薯片","examples":[{"en":"Parents should buy fruit instead of biscuits and crisps.","zh":"父母應購買水果，而不是餅乾和薯片。"},{"en":"Biscuits and crisps are common snack foods, often high in sugar, fat or salt.","zh":"餅乾和薯片是常見零食，通常糖、脂肪或鹽分較高。"},{"en":"Children may eat biscuits and crisps while watching television after school.","zh":"兒童放學後看電視時可能吃餅乾和薯片。"},{"en":"If biscuits and crisps are always available, children may choose them instead of healthier food.","zh":"如果餅乾和薯片總是容易取得，兒童可能選它們而不是健康食物。"},{"en":"The phrase refers to everyday snack foods.","zh":"這個短語指日常零食。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":13},{"front":"be likely to","meaning":"很可能會","examples":[{"en":"Your child is likely to model their behaviour on yours.","zh":"你的孩子很可能會模仿你的行為。"},{"en":"Be likely to do something means have a good chance of doing it.","zh":"“Be likely to” 做某事指有很大機會做該事。"},{"en":"A student is likely to improve if they practise speaking every day.","zh":"如果學生每天練習說話，很可能會進步。"},{"en":"If parents eat healthy food, children are likely to copy that habit.","zh":"如果父母吃健康食物，兒童很可能會模仿這個習慣。"},{"en":"The phrase describes probability, not certainty.","zh":"這個短語描述可能性，而不是確定性。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":13},{"front":"model one’s behaviour on","meaning":"模仿某人的行為","examples":[{"en":"Children often model their behaviour on their parents’ behaviour.","zh":"兒童常常模仿父母的行為。"},{"en":"To model one’s behaviour on someone means to copy or learn from that person’s actions.","zh":"“Model one’s behaviour on” 某人指模仿或學習該人的行動。"},{"en":"A younger student may model their study habits on an older sibling.","zh":"年幼學生可能模仿兄姊的學習習慣。"},{"en":"If parents choose healthy meals, children may model their behaviour on that example.","zh":"如果父母選擇健康膳食，兒童可能模仿這個榜樣。"},{"en":"The phrase explains learning by imitation.","zh":"這個短語解釋透過模仿學習。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":13},{"front":"healthy food options","meaning":"健康食物選擇","examples":[{"en":"Parents should choose healthy food options whenever possible.","zh":"父母應盡可能選擇健康食物選擇。"},{"en":"Healthy food options are food choices that support good nutrition and health.","zh":"健康食物選擇是支援良好營養和健康的食物選項。"},{"en":"In a café, soup, fruit and wholegrain bread may be healthy food options.","zh":"在咖啡店中，湯、水果和全麥麵包可能是健康食物選擇。"},{"en":"If healthy food options are easy to find, families may rely less on fried snacks.","zh":"如果健康食物選擇容易找到，家庭可能較少依賴炸小食。"},{"en":"The phrase focuses on available choices, not only personal willpower.","zh":"這個短語強調可用選項，而不只是個人意志力。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":13},{"front":"whenever possible","meaning":"盡可能","examples":[{"en":"Parents should choose healthy food options whenever possible.","zh":"父母應盡可能選擇健康食物。"},{"en":"Whenever possible means every time it can reasonably be done.","zh":"“Whenever possible” 指每當合理可行時都這樣做。"},{"en":"Students should ask questions whenever possible instead of staying confused.","zh":"學生應盡可能提問，而不是一直困惑。"},{"en":"If families choose healthier food whenever possible, small changes can build over time.","zh":"如果家庭盡可能選擇較健康食物，小改變可以隨時間累積。"},{"en":"The phrase allows flexibility while encouraging frequent action.","zh":"這個短語容許彈性，同時鼓勵經常行動。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":14},{"front":"offer someone a choice of","meaning":"給某人……的選擇","examples":[{"en":"Offering a child a choice of food is generally not a good idea.","zh":"給兒童食物選擇通常不是好主意。"},{"en":"To offer someone a choice of something means to give them several options to choose from.","zh":"“Offer someone a choice of” 某物指給某人幾個選項去選。"},{"en":"A teacher may offer students a choice of two essay topics.","zh":"老師可能給學生兩個作文題目的選擇。"},{"en":"If children are offered too many food choices, they may eat more than they need.","zh":"如果兒童獲提供太多食物選擇，可能吃得超過需要。"},{"en":"The phrase focuses on giving options.","zh":"這個短語強調提供選項。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":14},{"front":"generally not a good idea","meaning":"通常不是好主意","examples":[{"en":"Offering too much choice is generally not a good idea.","zh":"提供太多選擇通常不是好主意。"},{"en":"Generally not a good idea means usually unhelpful or likely to cause problems.","zh":"“Generally not a good idea” 指通常沒有幫助或可能造成問題。"},{"en":"Studying all night before an exam is generally not a good idea.","zh":"考試前通宵溫習通常不是好主意。"},{"en":"If too much food choice encourages overeating, it is generally not a good idea at home.","zh":"如果太多食物選擇鼓勵過量進食，在家中通常不是好主意。"},{"en":"The phrase gives a broad warning, not an absolute rule.","zh":"這個短語給出一般提醒，而不是絕對規則。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":14},{"front":"research has shown that","meaning":"研究顯示","examples":[{"en":"Research has shown that more choice can lead to overeating.","zh":"研究顯示，更多選擇可以導致過量進食。"},{"en":"Research has shown that means studies have provided evidence for a point.","zh":"“Research has shown that” 指研究已為某一點提供證據。"},{"en":"Research has shown that sleep helps students remember new information.","zh":"研究顯示睡眠幫助學生記住新資訊。"},{"en":"If research has shown a risk, parents may change habits with more confidence.","zh":"如果研究顯示某種風險，父母可能更有信心改變習慣。"},{"en":"The phrase introduces evidence rather than personal opinion.","zh":"這個短語引出證據，而不是個人意見。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":14},{"front":"more choice available","meaning":"有更多選擇","examples":[{"en":"When there is more choice available, we tend to eat more.","zh":"當有更多選擇時，我們往往吃得更多。"},{"en":"More choice available means more options are present and easy to choose from.","zh":"“More choice available” 指有更多選項存在並容易選擇。"},{"en":"At a buffet, more choice available can make people try extra dishes.","zh":"在自助餐中，有更多選擇可以令人嘗試額外菜式。"},{"en":"If children see many snacks at once, the extra choice may encourage more eating.","zh":"如果兒童一次看見許多零食，額外選擇可能鼓勵更多進食。"},{"en":"The phrase connects variety with behaviour.","zh":"這個短語把多樣性與行為連繫起來。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":14},{"front":"tend to eat more","meaning":"往往吃得更多","examples":[{"en":"People tend to eat more when more food choices are available.","zh":"當有更多食物選擇時，人們往往吃得更多。"},{"en":"Tend to eat more means usually eat a larger amount.","zh":"“Tend to eat more” 指通常吃更多分量。"},{"en":"At parties, guests tend to eat more because snacks are placed everywhere.","zh":"在派對上，客人往往吃得更多，因為小食到處都有。"},{"en":"If children tend to eat more when tempted, limiting choices can help.","zh":"如果兒童受誘惑時往往吃得更多，限制選擇可以有幫助。"},{"en":"The phrase describes a common pattern, not a certainty.","zh":"這個短語描述常見模式，而不是必然結果。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":14},{"front":"the sight or smell of","meaning":"……的外觀或氣味","examples":[{"en":"The sight or smell of tempting food can trigger eating.","zh":"誘人食物的外觀或氣味可以觸發進食。"},{"en":"The sight or smell of something means seeing it or smelling it.","zh":"“The sight or smell of” 某物指看見它或聞到它。"},{"en":"The sight or smell of fresh bread may make shoppers feel hungry.","zh":"新鮮麵包的外觀或氣味可能令購物者感到肚餓。"},{"en":"If the sight or smell of snacks triggers eating, children may eat even when they are not hungry.","zh":"如果小食的外觀或氣味觸發進食，兒童即使不餓也可能吃東西。"},{"en":"The phrase describes sensory cues.","zh":"這個短語描述感官線索。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":14},{"front":"tempting food","meaning":"誘人的食物","examples":[{"en":"Tempting food can override the body’s natural regulation mechanism.","zh":"誘人的食物可以凌駕身體的自然調節機制。"},{"en":"Tempting food is food that looks, smells or tastes so attractive that people want to eat it.","zh":"誘人的食物是外觀、氣味或味道非常吸引，令人想吃的食物。"},{"en":"Warm chips or chocolate cake can be tempting food for many children.","zh":"熱薯條或朱古力蛋糕對許多兒童來說可以是誘人的食物。"},{"en":"If tempting food is visible all day, children may eat when they are not hungry.","zh":"如果誘人的食物整天可見，兒童可能在不餓時進食。"},{"en":"The phrase describes food that strongly attracts desire.","zh":"這個短語描述強烈引發食慾的食物。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":14},{"front":"override","meaning":"凌駕；壓過","examples":[{"en":"Tempting food can override the body’s natural regulation mechanism.","zh":"誘人的食物可以凌駕身體的自然調節機制。"},{"en":"To override something means to become stronger than it and stop it from working normally.","zh":"“Override” 某事指變得比它更強，並阻止它正常運作。"},{"en":"Fear can override clear thinking during a difficult exam.","zh":"恐懼可以在困難考試中壓過清晰思考。"},{"en":"If the smell of food overrides fullness signals, a child may keep eating.","zh":"如果食物氣味凌駕飽足訊號，孩子可能繼續進食。"},{"en":"The word describes one force overpowering another.","zh":"這個詞描述一種力量壓過另一種力量。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":14},{"front":"natural mechanism of regulation","meaning":"自然調節機制","examples":[{"en":"The body has a natural mechanism of regulation for hunger.","zh":"身體有一套控制飢餓的自然調節機制。"},{"en":"A natural mechanism of regulation is the body’s built-in system for controlling something.","zh":"自然調節機制是身體用來控制某事的內建系統。"},{"en":"Sweating is a natural mechanism of regulation that helps cool the body.","zh":"出汗是一種幫助身體降溫的自然調節機制。"},{"en":"If tempting food overrides this mechanism, people may eat even after they are full.","zh":"如果誘人食物凌駕這套機制，人們即使飽了也可能進食。"},{"en":"The phrase describes automatic body control.","zh":"這個短語描述身體自動控制。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":14},{"front":"when we’re not hungry","meaning":"當我們不餓時","examples":[{"en":"Tempting food can make us eat when we’re not hungry.","zh":"誘人的食物可以令我們在不餓時進食。"},{"en":"When we’re not hungry means at a time when the body does not need food.","zh":"“When we’re not hungry” 指身體不需要食物的時候。"},{"en":"People may snack when they are not hungry simply because food is on the table.","zh":"人們可能只因食物在桌上，便在不餓時吃零食。"},{"en":"If children often eat when they are not hungry, natural appetite control may weaken.","zh":"如果兒童經常在不餓時進食，自然食慾控制可能變弱。"},{"en":"The phrase contrasts desire with physical need.","zh":"這個短語把慾望與身體需要作對比。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":14},{"front":"keep the options to","meaning":"把選擇限制在……","examples":[{"en":"Parents should keep the food options to an absolute minimum.","zh":"父母應把食物選擇限制在絕對最低限度。"},{"en":"To keep the options to a level means to limit the number of choices to that level.","zh":"“Keep the options to” 某水平指把選擇數量限制在該水平。"},{"en":"A teacher may keep homework options to two topics so students do not feel confused.","zh":"老師可能把功課選擇限制在兩個題目，以免學生感到混亂。"},{"en":"If parents keep snack options limited, children may be less tempted to overeat.","zh":"如果父母限制零食選項，兒童可能較少受誘惑而過量進食。"},{"en":"The phrase describes controlling choice by reducing variety.","zh":"這個短語描述透過減少多樣性來控制選擇。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":15},{"front":"an absolute minimum","meaning":"絕對最低限度","examples":[{"en":"Parents should keep food choices to an absolute minimum.","zh":"父母應把食物選擇維持在絕對最低限度。"},{"en":"An absolute minimum means the smallest possible amount or number.","zh":"“An absolute minimum” 指可能的最少數量或最低程度。"},{"en":"During an exam, talking should be kept to an absolute minimum.","zh":"考試期間，談話應維持在絕對最低限度。"},{"en":"If tempting food choices are kept to an absolute minimum, overeating may be easier to prevent.","zh":"如果誘人食物選擇被限制在絕對最低限度，過量進食可能較容易預防。"},{"en":"The phrase strongly emphasises reduction.","zh":"這個短語強烈強調減少。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":15},{"front":"weight management camps","meaning":"體重管理營","examples":[{"en":"Weight management camps can be a good way to treat obesity.","zh":"體重管理營可以是治療肥胖的好方法。"},{"en":"Weight management camps are programmes where children receive support with eating, activity and healthy habits.","zh":"體重管理營是兒童在飲食、活動和健康習慣方面得到支援的計劃。"},{"en":"A child may attend a weight management camp during school holidays.","zh":"兒童可能在學校假期參加體重管理營。"},{"en":"If the family does not change after the camp, lost weight may return.","zh":"如果家庭在營後沒有改變，減去的體重可能反彈。"},{"en":"The phrase refers to organised treatment, not ordinary holiday camps.","zh":"這個短語指有組織的治療，而不是普通假期營。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":15},{"front":"a good way to treat obesity","meaning":"治療肥胖的好方法","examples":[{"en":"Weight management camps can be a good way to treat obesity.","zh":"體重管理營可以是治療肥胖的好方法。"},{"en":"A good way to treat obesity is a method that helps reduce health risks and support lasting habits.","zh":"治療肥胖的好方法，是幫助減少健康風險並支援持久習慣的方法。"},{"en":"Family exercise and healthier meals may be a good way to treat mild obesity.","zh":"家庭運動和較健康膳食可能是治療輕度肥胖的好方法。"},{"en":"If a method teaches long-term habits, it is more useful than a short crash diet.","zh":"如果一種方法教授長期習慣，它就比短期極端節食更有用。"},{"en":"The phrase focuses on treatment that can actually help.","zh":"這個短語強調真正有幫助的治療。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":15},{"front":"treat obesity","meaning":"治療肥胖","examples":[{"en":"Special camps may help treat obesity.","zh":"特別營可能幫助治療肥胖。"},{"en":"To treat obesity means to manage and reduce obesity through lifestyle, medical or specialist support.","zh":"“Treat obesity” 指透過生活方式、醫療或專業支援來管理和減少肥胖。"},{"en":"Doctors may treat obesity by helping families improve food habits and activity levels.","zh":"醫生可能透過幫助家庭改善飲食習慣和活動量來治療肥胖。"},{"en":"If obesity is treated early, later health problems may be reduced.","zh":"如果肥胖及早治療，日後健康問題可能減少。"},{"en":"The phrase describes active management of a health condition.","zh":"這個短語描述對健康狀況的主動管理。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":15},{"front":"keeping off the weight","meaning":"保持減去的體重不反彈","examples":[{"en":"One problem is keeping off the weight that children lose.","zh":"其中一個問題是保持兒童減去的體重不反彈。"},{"en":"Keeping off the weight means maintaining weight loss and not gaining the lost weight back.","zh":"“Keeping off the weight” 指維持減重成果，不把已減去的體重重新增加。"},{"en":"A person may lose weight during a programme but find keeping it off harder at home.","zh":"一個人可能在計劃中減重，但回家後發現保持不反彈更困難。"},{"en":"If old eating habits return, keeping off the weight becomes difficult.","zh":"如果舊飲食習慣回來，保持減去的體重不反彈會變得困難。"},{"en":"The phrase focuses on long-term maintenance after weight loss.","zh":"這個短語強調減重後的長期維持。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":15},{"front":"lose weight at such camps","meaning":"在這類營中減重","examples":[{"en":"Children may lose weight at weight management camps.","zh":"兒童可能在體重管理營中減重。"},{"en":"To lose weight at such camps means to reduce body weight while attending these programmes.","zh":"“Lose weight at such camps” 指參加這些計劃期間減少體重。"},{"en":"A child may lose weight at a camp because meals and activities are carefully planned.","zh":"兒童可能因膳食和活動被仔細規劃，而在營中減重。"},{"en":"If children lose weight at camp but go home to old habits, the change may not last.","zh":"如果兒童在營中減重，但回家後恢復舊習慣，改變可能不能持久。"},{"en":"The phrase describes weight loss inside a structured programme.","zh":"這個短語描述在結構化計劃中的減重。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":15},{"front":"alter eating habits","meaning":"改變飲食習慣","examples":[{"en":"Family members may need to alter their eating habits.","zh":"家庭成員可能需要改變飲食習慣。"},{"en":"To alter eating habits means to change what, when or how much people eat.","zh":"“Alter eating habits” 指改變人們吃甚麼、何時吃或吃多少。"},{"en":"A family may alter eating habits by cooking more vegetables and buying fewer snacks.","zh":"家庭可能透過煮更多蔬菜和少買零食來改變飲食習慣。"},{"en":"If only the child changes but the family does not, new habits may be difficult to keep.","zh":"如果只有孩子改變而家庭沒有改變，新習慣可能難以維持。"},{"en":"The phrase describes practical change in daily food behaviour.","zh":"這個短語描述日常飲食行為的實際改變。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":15},{"front":"be difficult to sustain","meaning":"難以維持","examples":[{"en":"Improvements may be difficult to sustain without family support.","zh":"沒有家庭支援，改善可能難以維持。"},{"en":"To be difficult to sustain means to be hard to keep going over time.","zh":"“Be difficult to sustain” 指難以長時間保持。"},{"en":"A student’s revision plan may be difficult to sustain if it leaves no rest time.","zh":"如果溫習計劃沒有休息時間，學生可能難以維持。"},{"en":"If healthy eating is not supported at home, progress may be difficult to sustain.","zh":"如果健康飲食在家中沒有得到支援，進展可能難以維持。"},{"en":"The phrase stresses long-term maintenance.","zh":"這個短語強調長期維持。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":15},{"front":"lead by example","meaning":"以身作則","examples":[{"en":"Parents should lead by example when changing eating habits.","zh":"父母在改變飲食習慣時應以身作則。"},{"en":"To lead by example means to guide others by doing the desired behaviour yourself.","zh":"“Lead by example” 指透過自己做出期望行為來引導他人。"},{"en":"A teacher leads by example when she arrives prepared and listens respectfully.","zh":"老師準備充足並尊重地聆聽，就是以身作則。"},{"en":"If parents eat vegetables and exercise, children may copy those habits more easily.","zh":"如果父母吃蔬菜和運動，兒童可能更容易模仿這些習慣。"},{"en":"The phrase means actions teach more powerfully than instructions alone.","zh":"這個短語表示行動比單靠指示更有教學力量。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":15},{"front":"an increasing number of","meaning":"越來越多","examples":[{"en":"An increasing number of parents ask doctors about surgery.","zh":"越來越多父母向醫生詢問手術。"},{"en":"An increasing number of people means more and more people over time.","zh":"“An increasing number of” 人指隨時間越來越多人。"},{"en":"An increasing number of students are using online tools to practise English.","zh":"越來越多學生使用網上工具練習英語。"},{"en":"If an increasing number of parents ask about surgery, concern about severe obesity may be rising.","zh":"如果越來越多父母詢問手術，對嚴重肥胖的憂慮可能正在上升。"},{"en":"The phrase describes a growing trend.","zh":"這個短語描述增長趨勢。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":15},{"front":"surgery","meaning":"手術","examples":[{"en":"Some parents ask doctors about surgery to tackle obesity.","zh":"一些父母向醫生詢問用手術處理肥胖。"},{"en":"Surgery is medical treatment in which doctors operate on the body.","zh":"手術是醫生對身體進行操作的醫療治療。"},{"en":"Surgery may be needed when medicine and lifestyle changes cannot solve a serious problem.","zh":"當藥物和生活方式改變不能解決嚴重問題時，可能需要手術。"},{"en":"If surgery is considered for a child, doctors must weigh benefits against serious risks.","zh":"如果考慮為兒童進行手術，醫生必須權衡好處與嚴重風險。"},{"en":"The word refers to a major medical option, not a simple treatment.","zh":"這個詞指重大醫療選項，而不是簡單治療。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":16},{"front":"liposuction","meaning":"抽脂","examples":[{"en":"Liposuction is sometimes discussed as a treatment for severe obesity.","zh":"抽脂有時被討論為治療嚴重肥胖的方法。"},{"en":"Liposuction is a surgical procedure that removes fat from parts of the body.","zh":"抽脂是一種從身體部位移除脂肪的外科程序。"},{"en":"Adults may ask about liposuction for cosmetic reasons, but obesity treatment is more complex.","zh":"成人可能因美容原因詢問抽脂，但肥胖治療更複雜。"},{"en":"If liposuction is considered for children, ethical and medical concerns become serious.","zh":"如果考慮為兒童抽脂，倫理和醫療憂慮會變得嚴重。"},{"en":"The phrase names a specific type of fat-removal surgery.","zh":"這個短語指一種特定的去脂手術。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":16},{"front":"tackle obesity","meaning":"處理肥胖問題","examples":[{"en":"Some parents consider surgery to tackle obesity.","zh":"一些父母考慮用手術處理肥胖問題。"},{"en":"To tackle obesity means to deal with obesity actively and try to reduce its harm.","zh":"“Tackle obesity” 指積極處理肥胖並嘗試減少其傷害。"},{"en":"A school may tackle obesity by improving lunches and adding daily physical activity.","zh":"學校可能透過改善午餐和加入每日身體活動來處理肥胖問題。"},{"en":"If families tackle obesity together, children may feel supported rather than blamed.","zh":"如果家庭一起處理肥胖問題，兒童可能感到被支持而非被責怪。"},{"en":"The phrase suggests practical action against a problem.","zh":"這個短語暗示針對問題採取實際行動。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":16},{"front":"severe obesity","meaning":"嚴重肥胖","examples":[{"en":"Surgery may be considered only in cases of severe obesity.","zh":"手術可能只在嚴重肥胖個案中被考慮。"},{"en":"Severe obesity is obesity serious enough to create major health risks.","zh":"嚴重肥胖是嚴重到造成重大健康風險的肥胖。"},{"en":"A doctor may treat severe obesity with specialist medical support and careful monitoring.","zh":"醫生可能用專業醫療支援和仔細監察治療嚴重肥胖。"},{"en":"If severe obesity puts health at risk, more treatment options may need discussion.","zh":"如果嚴重肥胖令健康受威脅，可能需要討論更多治療選項。"},{"en":"The phrase describes a more serious level of obesity.","zh":"這個短語描述較嚴重程度的肥胖。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":16},{"front":"put someone at serious risk","meaning":"令某人面臨嚴重風險","examples":[{"en":"Severe obesity can put a child’s health at serious risk.","zh":"嚴重肥胖可以令兒童健康面臨嚴重風險。"},{"en":"To put someone at serious risk means to make them likely to face major harm or danger.","zh":"“Put someone at serious risk” 指令某人很可能面對重大傷害或危險。"},{"en":"Driving without a seat belt can put passengers at serious risk.","zh":"不扣安全帶駕駛可以令乘客面臨嚴重風險。"},{"en":"If a child’s weight affects breathing, heart health or diabetes risk, their health may be at serious risk.","zh":"如果孩子體重影響呼吸、心臟健康或糖尿病風險，其健康可能面臨嚴重風險。"},{"en":"The phrase signals danger that should not be ignored.","zh":"這個短語表示不應忽視的危險。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":16},{"front":"all options have to be considered","meaning":"必須考慮所有選項","examples":[{"en":"If a child’s health is at serious risk, all options have to be considered.","zh":"如果孩子健康面臨嚴重風險，必須考慮所有選項。"},{"en":"All options have to be considered means every possible solution should be examined.","zh":"“All options have to be considered” 指每個可能解決方案都應被檢視。"},{"en":"If a school is unsafe, all options have to be considered, including repairs, relocation or closure.","zh":"如果學校不安全，就必須考慮所有選項，包括維修、搬遷或關閉。"},{"en":"When health is in danger, doctors and parents may need to discuss even difficult treatments.","zh":"當健康處於危險中，醫生和父母可能需要討論甚至困難的治療。"},{"en":"The phrase shows that the situation is serious enough for broad consideration.","zh":"這個短語顯示情況嚴重到需要廣泛考慮。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":16},{"front":"surgical treatments","meaning":"外科治療","examples":[{"en":"Surgical treatments have shown good results in adults.","zh":"外科治療在成人身上顯示良好成效。"},{"en":"Surgical treatments are medical procedures involving operations on the body.","zh":"外科治療是涉及對身體進行手術的醫療程序。"},{"en":"A hospital may use surgical treatments when other treatments cannot solve the problem.","zh":"當其他治療不能解決問題時，醫院可能使用外科治療。"},{"en":"If surgical treatments work in adults, doctors still must ask whether they are safe for children.","zh":"如果外科治療在成人身上有效，醫生仍必須問它們對兒童是否安全。"},{"en":"The phrase refers to operation-based medical care.","zh":"這個短語指以手術為本的醫療照顧。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":16},{"front":"show good results","meaning":"顯示良好成效","examples":[{"en":"Surgical treatments have shown good results in adults.","zh":"外科治療在成人身上顯示良好成效。"},{"en":"To show good results means to produce successful or encouraging outcomes.","zh":"“Show good results” 指產生成功或令人鼓舞的結果。"},{"en":"A new reading programme shows good results if students understand texts better after joining.","zh":"如果學生參加後更理解文本，新閱讀計劃就顯示良好成效。"},{"en":"If a treatment shows good results in adults, researchers may study whether it works for younger patients.","zh":"如果治療在成人身上顯示良好成效，研究人員可能研究它是否適用於年輕病人。"},{"en":"The phrase describes evidence of success.","zh":"這個短語描述成功的證據。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":16},{"front":"serious risks","meaning":"嚴重風險","examples":[{"en":"Surgery can involve serious risks.","zh":"手術可以涉及嚴重風險。"},{"en":"Serious risks are dangers that could cause major harm, illness or complications.","zh":"嚴重風險是可能造成重大傷害、疾病或併發症的危險。"},{"en":"A mountain trip in bad weather can involve serious risks.","zh":"在惡劣天氣下登山可能涉及嚴重風險。"},{"en":"If treatment carries serious risks, doctors must discuss them clearly with families.","zh":"如果治療帶有嚴重風險，醫生必須與家庭清楚討論。"},{"en":"The phrase warns that benefits must be weighed against danger.","zh":"這個短語提醒好處必須與危險權衡。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":16},{"front":"perform surgery on children","meaning":"對兒童進行手術","examples":[{"en":"Performing surgery on children would raise difficult issues.","zh":"對兒童進行手術會引發棘手問題。"},{"en":"To perform surgery on children means to operate medically on young patients.","zh":"“Perform surgery on children” 指對年幼病人進行醫療手術。"},{"en":"Doctors must be especially careful when they perform surgery on children because children are still growing.","zh":"醫生對兒童進行手術時必須特別小心，因為兒童仍在成長。"},{"en":"If surgery is done too early or unnecessarily, it may create ethical and medical problems.","zh":"如果手術過早或不必要地進行，可能造成倫理和醫療問題。"},{"en":"The phrase describes a sensitive medical action.","zh":"這個短語描述敏感醫療行動。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":16},{"front":"raise difficult issues","meaning":"引發棘手問題","examples":[{"en":"Performing surgery on children would raise difficult issues.","zh":"對兒童進行手術會引發棘手問題。"},{"en":"To raise difficult issues means to create or bring up questions that are hard to solve.","zh":"“Raise difficult issues” 指造成或提出難以解決的問題。"},{"en":"Using cameras in classrooms may raise difficult issues about privacy and trust.","zh":"在課室使用攝影機可能引發關於私隱和信任的棘手問題。"},{"en":"If doctors consider surgery for children, they must face questions about risk, consent and long-term effects.","zh":"如果醫生考慮為兒童手術，就必須面對風險、同意和長期影響等問題。"},{"en":"The phrase introduces complex problems that need careful discussion.","zh":"這個短語引出需要謹慎討論的複雜問題。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":16},{"front":"only be considered when","meaning":"只應在……時才考慮","examples":[{"en":"Surgery should only be considered when all other options have been exhausted.","zh":"手術只應在所有其他方法都已用盡時才考慮。"},{"en":"Only be considered when means should be thought about only under a specific condition.","zh":"“Only be considered when” 指只應在特定條件下才被思考。"},{"en":"Moving school should only be considered when support at the current school has failed.","zh":"轉校只應在現有學校的支援失敗時才考慮。"},{"en":"If surgery is risky, it should only be considered after safer methods have been tried.","zh":"如果手術有風險，就只應在較安全方法已嘗試後才考慮。"},{"en":"The phrase sets a strict condition.","zh":"這個短語設定嚴格條件。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":17},{"front":"all others have been exhausted","meaning":"所有其他方法都已用盡","examples":[{"en":"Surgery should be considered only when all other options have been exhausted.","zh":"手術只應在所有其他方法都已用盡時才考慮。"},{"en":"All other options have been exhausted means every other possible method has been tried or ruled out.","zh":"“All other options have been exhausted” 指所有其他可能方法都已嘗試或排除。"},{"en":"A school may suspend a student only after all other support options have been exhausted.","zh":"學校可能只在所有其他支援方法都已用盡後，才停學處分學生。"},{"en":"If all other treatments have been exhausted, doctors may discuss more serious medical choices.","zh":"如果所有其他治療方法都已用盡，醫生可能討論更嚴重的醫療選擇。"},{"en":"The phrase shows that something is a last resort.","zh":"這個短語顯示某事是最後手段。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":17},{"front":"young children","meaning":"年幼兒童","examples":[{"en":"Parents of young children can help the family change its lifestyle.","zh":"年幼兒童的父母可以幫助家庭改變生活方式。"},{"en":"Young children are children in the early years of childhood.","zh":"年幼兒童是處於兒童早期的孩子。"},{"en":"Young children often learn habits by watching adults rather than listening to advice.","zh":"年幼兒童通常透過觀察成年人學習習慣，而不是聽建議。"},{"en":"If young children grow up with healthy meals, those habits may feel normal later.","zh":"如果年幼兒童在健康膳食中長大，這些習慣日後可能感覺自然。"},{"en":"The phrase refers to children who are still very early in development.","zh":"這個短語指仍處於非常早期發展階段的兒童。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":17},{"front":"make sure","meaning":"確保","examples":[{"en":"Parents can make sure the family changes to a healthy lifestyle.","zh":"父母可以確保家庭改為健康生活方式。"},{"en":"To make sure means to check or take action so something definitely happens.","zh":"“Make sure” 指檢查或採取行動，使某事確實發生。"},{"en":"A teacher may make sure every student understands the homework before class ends.","zh":"老師可能在下課前確保每名學生明白功課。"},{"en":"If parents make sure healthy food is at home, children have better daily choices.","zh":"如果父母確保家中有健康食物，兒童每天就有較好選擇。"},{"en":"The phrase shows responsibility and careful attention.","zh":"這個短語顯示責任和細心注意。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":17},{"front":"change to a healthy lifestyle","meaning":"改為健康生活方式","examples":[{"en":"The family can change to a healthy lifestyle.","zh":"家庭可以改為健康生活方式。"},{"en":"To change to a healthy lifestyle means to adopt habits that support health, such as better eating, sleep and activity.","zh":"“Change to a healthy lifestyle” 指採納支援健康的習慣，例如更好飲食、睡眠和活動。"},{"en":"A family may change to a healthy lifestyle by cooking more often and walking after dinner.","zh":"家庭可能透過更常煮飯和晚飯後散步，改為健康生活方式。"},{"en":"If everyone changes together, the child may feel supported rather than singled out.","zh":"如果每個人一起改變，孩子可能感到被支持，而不是被單獨挑出。"},{"en":"The phrase describes broad habit change, not one diet rule.","zh":"這個短語描述廣泛習慣改變，而不是一條飲食規則。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":17},{"front":"rather than","meaning":"而不是","examples":[{"en":"Parents should focus on a healthy lifestyle rather than weight loss alone.","zh":"父母應集中於健康生活方式，而不是只集中於減重。"},{"en":"Rather than means instead of, or in preference to another option.","zh":"“Rather than” 指而不是，或相對另一選項更偏向某選項。"},{"en":"A student should build daily study habits rather than panic before every test.","zh":"學生應建立每日學習習慣，而不是每次測驗前才驚慌。"},{"en":"If families focus on health rather than numbers only, children may feel less pressure.","zh":"如果家庭集中於健康而不是只看數字，兒童可能感到較少壓力。"},{"en":"The phrase clearly shows contrast between two choices.","zh":"這個短語清楚顯示兩個選擇之間的對比。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":17},{"front":"target weight loss specifically","meaning":"專門以減重為目標","examples":[{"en":"Parents should not always target weight loss specifically.","zh":"父母不應總是專門以減重為目標。"},{"en":"To target weight loss specifically means to make losing weight the direct and main goal.","zh":"“Target weight loss specifically” 指把減重作為直接和主要目標。"},{"en":"A doctor may focus on better sleep and activity rather than target weight loss specifically at first.","zh":"醫生起初可能集中於改善睡眠和活動，而不是專門以減重為目標。"},{"en":"If parents target weight loss too strongly, children may feel judged by their body size.","zh":"如果父母過度專門以減重為目標，兒童可能覺得自己被身形評判。"},{"en":"The phrase contrasts weight-focused goals with broader health goals.","zh":"這個短語把體重導向目標與更廣泛健康目標作對比。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":17},{"front":"grow at different rates","meaning":"以不同速度成長","examples":[{"en":"Children grow at different rates.","zh":"兒童以不同速度成長。"},{"en":"To grow at different rates means to develop faster or slower than others.","zh":"“Grow at different rates” 指比其他人發展得更快或更慢。"},{"en":"Two classmates of the same age may grow at different rates during puberty.","zh":"兩名同齡同學在青春期可能以不同速度成長。"},{"en":"If children grow at different rates, weight should be judged with age and height in mind.","zh":"如果兒童以不同速度成長，判斷體重時應考慮年齡和身高。"},{"en":"The phrase reminds us not to compare children too simply.","zh":"這個短語提醒我們不要過於簡單地比較兒童。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":17},{"front":"grow out of it","meaning":"長大後自然改善","examples":[{"en":"Many overweight children will grow out of it as they grow taller.","zh":"許多超重兒童會隨着長高而長大後自然改善。"},{"en":"To grow out of it means to stop having a problem naturally as one grows older or develops.","zh":"“Grow out of it” 指隨着年齡增長或發展而自然不再有某問題。"},{"en":"Some children grow out of a fear of the dark as they become more confident.","zh":"一些兒童變得更有信心後，會自然克服怕黑。"},{"en":"If a young child grows taller quickly, mild overweight may improve without strict dieting.","zh":"如果年幼兒童迅速長高，輕微超重可能不用嚴格節食也改善。"},{"en":"The phrase suggests natural improvement over time.","zh":"這個短語暗示隨時間自然改善。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":17},{"front":"as they grow taller","meaning":"隨着他們長高","examples":[{"en":"Some overweight children slim down as they grow taller.","zh":"一些超重兒童會隨着他們長高而變瘦。"},{"en":"As they grow taller means while their height increases during growth.","zh":"“As they grow taller” 指在成長期間身高增加時。"},{"en":"A child’s clothes may become too short as they grow taller.","zh":"隨着孩子長高，衣服可能變得太短。"},{"en":"If children gain height faster than weight, they may look slimmer as they grow taller.","zh":"如果兒童身高增加快於體重增加，他們可能隨着長高而看起來較瘦。"},{"en":"The phrase connects physical growth with a visible change.","zh":"這個短語把身體成長與可見變化連繫起來。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":17},{"front":"be targeted at","meaning":"針對……","examples":[{"en":"Few treatments are targeted at children under the age of seven.","zh":"很少治療針對七歲以下兒童。"},{"en":"To be targeted at a group means to be designed especially for that group.","zh":"“Be targeted at” 某群體指專門為該群體設計。"},{"en":"A reading app targeted at young children uses simple words and pictures.","zh":"針對年幼兒童的閱讀應用程式會使用簡單詞語和圖片。"},{"en":"If obesity treatments are not targeted at very young children, families may focus on lifestyle instead.","zh":"如果肥胖治療不針對非常年幼的兒童，家庭可能改為集中生活方式。"},{"en":"The phrase describes intended users or audience.","zh":"這個短語描述目標使用者或受眾。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":17},{"front":"under the age of seven","meaning":"七歲以下","examples":[{"en":"Few treatments are targeted at children under the age of seven.","zh":"很少治療針對七歲以下兒童。"},{"en":"Under the age of seven means younger than seven years old.","zh":"“Under the age of seven” 指少於七歲。"},{"en":"Children under the age of seven may need simpler explanations and more family support.","zh":"七歲以下兒童可能需要較簡單解釋和更多家庭支援。"},{"en":"If treatments are not designed for children under seven, parents should ask doctors for age-appropriate advice.","zh":"如果治療不是為七歲以下兒童設計，父母應向醫生尋求合適年齡的建議。"},{"en":"The phrase sets an age limit.","zh":"這個短語設定年齡界限。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":18},{"front":"from age eight to ten","meaning":"從八至十歲起","examples":[{"en":"From age eight to ten, an obese child should have a medical evaluation.","zh":"從八至十歲起，肥胖兒童應接受醫學評估。"},{"en":"From age eight to ten means during the period when a child is eight, nine or ten years old.","zh":"“From age eight to ten” 指兒童八歲、九歲或十歲的時期。"},{"en":"From age eight to ten, many children become more aware of classmates’ opinions.","zh":"從八至十歲起，許多兒童變得更意識到同學的看法。"},{"en":"If obesity continues from age eight to ten, doctors may begin more careful assessment.","zh":"如果肥胖從八至十歲仍然持續，醫生可能開始更仔細評估。"},{"en":"The phrase identifies a specific childhood age range.","zh":"這個短語指出特定兒童年齡範圍。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":18},{"front":"medical evaluation","meaning":"醫學評估","examples":[{"en":"An obese child should have a medical evaluation.","zh":"肥胖兒童應接受醫學評估。"},{"en":"A medical evaluation is a professional health assessment by a doctor or medical team.","zh":"醫學評估是由醫生或醫療團隊進行的專業健康評估。"},{"en":"A medical evaluation may include checking height, weight, blood pressure and family history.","zh":"醫學評估可能包括檢查身高、體重、血壓和家族病史。"},{"en":"If a medical evaluation finds serious risk, treatment can be planned more safely.","zh":"如果醫學評估發現嚴重風險，治療就能更安全地規劃。"},{"en":"The phrase refers to health assessment, not casual opinion.","zh":"這個短語指健康評估，而不是隨意意見。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":18},{"front":"assess the severity of","meaning":"評估……的嚴重程度","examples":[{"en":"A medical evaluation can assess the severity of the problem.","zh":"醫學評估可以評估問題的嚴重程度。"},{"en":"To assess the severity of something means to judge how serious it is.","zh":"“Assess the severity of” 某事指判斷它有多嚴重。"},{"en":"A doctor may assess the severity of an injury before choosing treatment.","zh":"醫生可能先評估受傷的嚴重程度，再選擇治療。"},{"en":"If doctors assess the severity of obesity, they can decide whether lifestyle support is enough.","zh":"如果醫生評估肥胖的嚴重程度，就能決定生活方式支援是否足夠。"},{"en":"The phrase focuses on measuring seriousness.","zh":"這個短語強調量度嚴重性。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":18},{"front":"the severity of the problem","meaning":"問題的嚴重程度","examples":[{"en":"Doctors can assess the severity of the problem.","zh":"醫生可以評估問題的嚴重程度。"},{"en":"The severity of the problem means how serious, dangerous or difficult the problem is.","zh":"問題的嚴重程度指問題有多嚴重、危險或困難。"},{"en":"A school may judge the severity of a bullying case before deciding what action to take.","zh":"學校可能先判斷欺凌個案的嚴重程度，再決定採取甚麼行動。"},{"en":"If the severity of the problem is high, stronger support may be needed.","zh":"如果問題的嚴重程度很高，可能需要更強支援。"},{"en":"The phrase helps match the solution to the seriousness of the issue.","zh":"這個短語幫助把解決方案配對問題嚴重性。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":18},{"front":"the older your child is","meaning":"你的孩子年紀越大","examples":[{"en":"The older your child is, the less likely they are to grow out of it.","zh":"你的孩子年紀越大，他們就越不可能自然改善。"},{"en":"The older your child is means as your child increases in age.","zh":"“The older your child is” 指隨着你的孩子年齡增加。"},{"en":"The older your child is, the more they may understand explanations about health.","zh":"你的孩子年紀越大，可能越能理解關於健康的解釋。"},{"en":"If a child remains overweight as they get older, natural improvement may become less likely.","zh":"如果孩子隨着年齡增長仍然超重，自然改善可能變得較不可能。"},{"en":"The phrase begins a comparison based on age.","zh":"這個短語開始一個基於年齡的比較。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":18},{"front":"the less likely they are to","meaning":"他們就越不可能","examples":[{"en":"The older the child is, the less likely they are to grow out of obesity.","zh":"孩子年紀越大，就越不可能自然擺脫肥胖。"},{"en":"The less likely they are to do something means the chance of that thing happening becomes lower.","zh":"“The less likely they are to” 做某事指該事發生的機會變低。"},{"en":"The longer students avoid revision, the less likely they are to feel ready for the exam.","zh":"學生越長時間逃避溫習，就越不可能覺得已準備好考試。"},{"en":"If obesity continues into later childhood, the child is less likely to grow out of it naturally.","zh":"如果肥胖持續至較後兒童期，孩子就較不可能自然改善。"},{"en":"The phrase completes a “the more…, the less…” comparison.","zh":"這個短語完成 “the more…, the less…” 比較句式。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":18},{"front":"remain so in adulthood","meaning":"到成年期仍然如此","examples":[{"en":"A 15-year-old who is overweight is likely to remain so in adulthood.","zh":"一名15歲超重青少年很可能到成年期仍然如此。"},{"en":"To remain so in adulthood means to continue being in the same condition as an adult.","zh":"“Remain so in adulthood” 指成年後仍然處於同一狀態。"},{"en":"A teenager with poor sleep habits may remain so in adulthood if routines never change.","zh":"如果作息從未改變，有睡眠習慣差的青少年可能到成年期仍然如此。"},{"en":"If an overweight teenager remains so in adulthood, long-term health risks may rise.","zh":"如果超重青少年到成年期仍然如此，長期健康風險可能上升。"},{"en":"The phrase connects teenage condition with adult outcome.","zh":"這個短語把青少年狀況與成人結果連繫起來。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":18},{"front":"which paragraph does each heading best fit?","meaning":"每個標題最適合哪一段？","examples":[{"en":"Students decide which paragraph each heading best fits.","zh":"學生判斷每個標題最適合哪一段。"},{"en":"Which paragraph does each heading best fit asks students to match headings with the most suitable paragraphs.","zh":"“Which paragraph does each heading best fit?” 要求學生把標題與最合適段落配對。"},{"en":"In a reading test, students should find the main idea before choosing which heading fits.","zh":"在閱讀測驗中，學生應先找出主旨，再選擇哪個標題適合。"},{"en":"If a heading matches only one small detail, it may not best fit the paragraph.","zh":"如果標題只符合一個小細節，它未必最適合該段。"},{"en":"The phrase is a common matching-heading instruction.","zh":"這個短語是常見標題配對指示。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":18},{"front":"the following headings","meaning":"以下標題","examples":[{"en":"The task asks students to match the following headings with paragraphs.","zh":"任務要求學生把以下標題與段落配對。"},{"en":"The following headings are the list of titles given after the instruction.","zh":"以下標題是指示後給出的標題列表。"},{"en":"Students should read the following headings before scanning the passage.","zh":"學生應先閱讀以下標題，再掃讀文章。"},{"en":"If the following headings are similar, students need to compare main ideas carefully.","zh":"如果以下標題相似，學生需要仔細比較主旨。"},{"en":"The phrase refers to answer choices that come next.","zh":"這個短語指接下來出現的答案選項。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":18},{"front":"best fit","meaning":"最適合","examples":[{"en":"Students choose the heading that best fits each paragraph.","zh":"學生選擇最適合每段的標題。"},{"en":"Best fit means the option that matches most accurately or suitably.","zh":"“Best fit” 指最準確或最合適地配對的選項。"},{"en":"A teacher may ask which title best fits a student’s essay.","zh":"老師可能問哪個標題最適合學生的作文。"},{"en":"If two headings seem possible, the best fit should match the whole paragraph, not one sentence.","zh":"如果兩個標題看似可行，最適合的應符合整段，而不是一句。"},{"en":"The phrase is useful for choosing the most suitable answer.","zh":"這個短語適合用於選擇最合適答案。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":18},{"front":"feeling bad about yourself","meaning":"對自己感覺不好","examples":[{"en":"The heading “Feeling bad about yourself” refers to low self-esteem and body image.","zh":"標題 “Feeling bad about yourself” 指低自尊和身體形象。"},{"en":"Feeling bad about yourself means having negative feelings about who you are or how you look.","zh":"“Feeling bad about yourself” 指對自己是誰或自己的外貌有負面感受。"},{"en":"A child may feel bad about themselves after being teased at school.","zh":"孩子在學校被取笑後，可能對自己感覺不好。"},{"en":"If children feel bad about themselves, they may avoid friends or use food for comfort.","zh":"如果兒童對自己感覺不好，可能避開朋友或以食物尋求安慰。"},{"en":"The phrase describes emotional self-criticism.","zh":"這個短語描述情緒上的自我批評。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":19},{"front":"reducing weight","meaning":"減重","examples":[{"en":"The heading “Reducing weight” refers to ways of treating obesity.","zh":"標題 “Reducing weight” 指治療肥胖的方法。"},{"en":"Reducing weight means lowering body weight through healthy changes or treatment.","zh":"“Reducing weight” 指透過健康改變或治療降低體重。"},{"en":"A doctor may discuss reducing weight through meals, activity and family support.","zh":"醫生可能討論透過膳食、活動和家庭支援來減重。"},{"en":"If weight is reduced too quickly by extreme dieting, health may be harmed.","zh":"如果透過極端節食太快減重，健康可能受損。"},{"en":"The phrase focuses on weight loss as a treatment goal.","zh":"這個短語強調減重作為治療目標。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":19},{"front":"age is a factor","meaning":"年齡是一個因素","examples":[{"en":"The heading “Age is a factor” refers to how age affects obesity treatment.","zh":"標題 “Age is a factor” 指年齡如何影響肥胖治療。"},{"en":"Age is a factor means age influences the situation or decision.","zh":"“Age is a factor” 指年齡會影響情況或決定。"},{"en":"Age is a factor when doctors choose medicine because children and adults may need different doses.","zh":"醫生選擇藥物時，年齡是一個因素，因為兒童和成人可能需要不同劑量。"},{"en":"If a child is older, the chance of naturally growing out of obesity may be lower.","zh":"如果孩子年紀較大，自然擺脫肥胖的機會可能較低。"},{"en":"The phrase means age must be considered.","zh":"這個短語表示必須考慮年齡。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":19},{"front":"according to the text","meaning":"根據文章","examples":[{"en":"According to the text, several statements about childhood obesity are true.","zh":"根據文章，關於兒童肥胖的幾項陳述是真確的。"},{"en":"According to the text means based on what the passage says.","zh":"“According to the text” 指根據文章所說。"},{"en":"In reading exams, answers should be chosen according to the text, not outside knowledge.","zh":"在閱讀考試中，答案應根據文章選出，而不是根據外部知識。"},{"en":"If the text does not mention a point, students should not assume it is true.","zh":"如果文章沒有提到某一點，學生不應假設它為真。"},{"en":"The phrase identifies the source of the answer.","zh":"這個短語指出答案來源。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":19},{"front":"corresponding letters","meaning":"相應字母","examples":[{"en":"Students write the corresponding letters in the answer boxes.","zh":"學生在答案框中寫上相應字母。"},{"en":"Corresponding letters are the letters that match the correct answers or options.","zh":"相應字母是與正確答案或選項配對的字母。"},{"en":"In a matching task, the corresponding letter may be A, B, C or D.","zh":"在配對題中，相應字母可能是 A、B、C 或 D。"},{"en":"If students choose the right idea but write the wrong corresponding letter, they may lose marks.","zh":"如果學生選對意思但寫錯相應字母，可能會失分。"},{"en":"The phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":19},{"front":"in any order","meaning":"以任何次序","examples":[{"en":"The answers may be written in any order.","zh":"答案可以以任何次序寫出。"},{"en":"In any order means the sequence does not matter.","zh":"“In any order” 指順序並不重要。"},{"en":"If a question asks for two reasons in any order, students can write either reason first.","zh":"如果題目要求以任何次序寫兩個原因，學生可以先寫任何一個。"},{"en":"When answers are allowed in any order, accuracy matters more than arrangement.","zh":"當答案可用任何次序寫出，準確度比排列更重要。"},{"en":"The phrase tells students they do not need to follow a fixed sequence.","zh":"這個短語告訴學生不需要跟固定次序。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":19},{"front":"gain fat cells","meaning":"增加脂肪細胞","examples":[{"en":"Adults do not usually gain fat cells after childhood.","zh":"成人通常不會在兒童期後增加脂肪細胞。"},{"en":"To gain fat cells means to increase the number of fat cells in the body.","zh":"“Gain fat cells” 指增加身體中的脂肪細胞數量。"},{"en":"A child may gain fat cells if excess fat is stored quickly in early life.","zh":"如果兒童早期迅速儲存過多脂肪，可能增加脂肪細胞。"},{"en":"If adults do not usually gain fat cells, adult weight gain mainly changes cell size.","zh":"如果成人通常不會增加脂肪細胞，成人增重主要改變細胞大小。"},{"en":"The phrase describes an increase in cell number.","zh":"這個短語描述細胞數量增加。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":19},{"front":"a permanent problem","meaning":"永久性的問題","examples":[{"en":"The statement asks whether diabetes is a permanent problem.","zh":"該陳述問糖尿病是否是永久性的問題。"},{"en":"A permanent problem is a problem that lasts for a very long time or cannot be completely removed.","zh":"永久性的問題是持續很長時間或不能完全消除的問題。"},{"en":"A damaged tooth may become a permanent problem if it is ignored for too long.","zh":"如果受損牙齒被忽視太久，可能變成永久性的問題。"},{"en":"If diabetes cannot be cured, it may become a permanent problem that needs lifelong management.","zh":"如果糖尿病無法根治，它可能成為需要終生管理的永久性問題。"},{"en":"The phrase contrasts long-lasting problems with temporary ones.","zh":"這個短語把長期問題與暫時問題作對比。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":19},{"front":"generally considered to be","meaning":"一般被認為是","examples":[{"en":"Obesity is generally considered to be partly genetic.","zh":"肥胖一般被認為部分由基因造成。"},{"en":"Generally considered to be means widely believed or accepted as being something.","zh":"“Generally considered to be” 指被廣泛相信或接受為某事。"},{"en":"Regular reading is generally considered to be helpful for language learning.","zh":"定期閱讀一般被認為有助語言學習。"},{"en":"If obesity is generally considered partly genetic, blaming children alone is unfair.","zh":"如果肥胖一般被認為部分由基因造成，只責怪兒童是不公平的。"},{"en":"The phrase reports a common view.","zh":"這個短語報告常見看法。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":19},{"front":"partly genetic","meaning":"部分由基因造成","examples":[{"en":"Obesity is generally considered to be partly genetic.","zh":"肥胖一般被認為部分由基因造成。"},{"en":"Partly genetic means influenced in part by inherited genes.","zh":"“Partly genetic” 指部分受遺傳基因影響。"},{"en":"Height is partly genetic, though food and health also matter.","zh":"身高部分由基因造成，雖然食物和健康也重要。"},{"en":"If obesity is partly genetic, environment and family habits still play important roles.","zh":"如果肥胖部分由基因造成，環境和家庭習慣仍發揮重要作用。"},{"en":"The phrase means genes are one factor, not the only cause.","zh":"這個短語表示基因是一個因素，而不是唯一原因。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":19},{"front":"messages about how much food is required","meaning":"關於需要多少食物的訊息","examples":[{"en":"Messages about how much food is required take time to reach the brain.","zh":"關於需要多少食物的訊息需要時間到達大腦。"},{"en":"Messages about how much food is required are body signals that tell us whether we are still hungry or full.","zh":"關於需要多少食物的訊息，是告訴我們仍然肚餓還是已經飽的身體訊號。"},{"en":"After eating quickly, these messages may arrive too late to prevent overeating.","zh":"進食太快後，這些訊息可能太遲到達，無法防止過量進食。"},{"en":"If children eat slowly, the brain has more time to receive fullness messages.","zh":"如果兒童慢慢吃，大腦就有更多時間接收飽足訊息。"},{"en":"The phrase refers to internal hunger and fullness signals.","zh":"這個短語指內在飢餓和飽足訊號。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":19},{"front":"go from the stomach to the brain","meaning":"從胃部傳到大腦","examples":[{"en":"Fullness messages go from the stomach to the brain.","zh":"飽足訊息從胃部傳到大腦。"},{"en":"To go from the stomach to the brain means to travel as body signals from digestion to the nervous system.","zh":"“Go from the stomach to the brain” 指作為身體訊號由消化系統傳到神經系統。"},{"en":"After a meal, signals go from the stomach to the brain to show fullness.","zh":"飯後，訊號從胃部傳到大腦，以顯示飽足。"},{"en":"If these signals take time, eating too quickly may lead to overeating.","zh":"如果這些訊號需要時間，吃得太快可能導致過量進食。"},{"en":"The phrase explains the path of fullness communication.","zh":"這個短語解釋飽足溝通的路徑。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":20},{"front":"take the lead by","meaning":"帶頭做……","examples":[{"en":"Parents should take the lead by buying healthy foods.","zh":"父母應透過購買健康食物帶頭做。"},{"en":"To take the lead by doing something means to guide others through one’s own action.","zh":"“Take the lead by” 做某事指透過自己的行動引導他人。"},{"en":"A teacher can take the lead by reading quietly with students every morning.","zh":"老師可以透過每天早上與學生安靜閱讀來帶頭做。"},{"en":"If parents take the lead by choosing healthy food, children have a model to follow.","zh":"如果父母透過選擇健康食物帶頭做，兒童就有榜樣可跟。"},{"en":"The phrase means setting an example first.","zh":"這個短語表示先以身作則。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":20},{"front":"buy healthy foods","meaning":"購買健康食物","examples":[{"en":"Parents should buy healthy foods for the home.","zh":"父母應為家中購買健康食物。"},{"en":"To buy healthy foods means to choose and purchase foods that support good nutrition.","zh":"“Buy healthy foods” 指選擇並購買支援良好營養的食物。"},{"en":"A family may buy healthy foods such as fruit, vegetables, fish and wholegrain bread.","zh":"家庭可能購買水果、蔬菜、魚和全麥麵包等健康食物。"},{"en":"If parents buy healthy foods regularly, children are more likely to eat them.","zh":"如果父母定期購買健康食物，兒童更可能吃它們。"},{"en":"The phrase describes a practical shopping decision.","zh":"這個短語描述實際購物決定。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":20},{"front":"appear overweight","meaning":"看起來超重","examples":[{"en":"Some young children may appear overweight when they are short.","zh":"一些年幼兒童在矮小時可能看起來超重。"},{"en":"To appear overweight means to look heavier than expected, even if growth may later change the picture.","zh":"“Appear overweight” 指看起來比預期重，即使成長日後可能改變情況。"},{"en":"A child may appear overweight before a growth spurt makes them taller.","zh":"孩子在快速長高前可能看起來超重。"},{"en":"If children appear overweight when young, doctors may consider height, age and development before judging.","zh":"如果兒童年幼時看起來超重，醫生可能先考慮身高、年齡和發展再判斷。"},{"en":"The phrase describes appearance, not always a final medical conclusion.","zh":"這個短語描述外觀，不一定是最終醫學結論。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":20},{"front":"choose the correct answer","meaning":"選出正確答案","examples":[{"en":"Students choose the correct answer from the choices given.","zh":"學生從給出的選項中選出正確答案。"},{"en":"To choose the correct answer means to select the option that best matches the text or question.","zh":"“Choose the correct answer” 指選出最符合文本或題目的選項。"},{"en":"In a multiple-choice question, students should read all options before choosing the correct answer.","zh":"在選擇題中，學生應先閱讀所有選項，再選出正確答案。"},{"en":"If two answers look similar, exact evidence from the passage helps decide.","zh":"如果兩個答案看起來相似，文章中的準確證據有助決定。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":20},{"front":"suffer from sleep apnoea","meaning":"患有睡眠窒息症","examples":[{"en":"People with obesity may suffer from sleep apnoea.","zh":"肥胖人士可能患有睡眠窒息症。"},{"en":"To suffer from sleep apnoea means to have repeated breathing problems during sleep.","zh":"“Suffer from sleep apnoea” 指在睡眠期間反覆出現呼吸問題。"},{"en":"A child who suffers from sleep apnoea may snore loudly and feel tired in the morning.","zh":"患有睡眠窒息症的孩子可能大聲打鼻鼾，並在早上感到疲倦。"},{"en":"If someone suffers from sleep apnoea, poor sleep may affect memory and mood.","zh":"如果某人患有睡眠窒息症，睡眠質素差可能影響記憶和心情。"},{"en":"The phrase describes a health problem linked to breathing during sleep.","zh":"這個短語描述與睡眠呼吸有關的健康問題。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":20},{"front":"low blood pressure","meaning":"低血壓","examples":[{"en":"The question option mentions low blood pressure.","zh":"該題目選項提到低血壓。"},{"en":"Low blood pressure is a condition in which blood pressure is lower than normal.","zh":"低血壓是血壓低於正常水平的情況。"},{"en":"A person with low blood pressure may feel dizzy when standing up quickly.","zh":"有低血壓的人快速站起時可能感到頭暈。"},{"en":"If a reading passage mentions high blood pressure, students should not choose low blood pressure by mistake.","zh":"如果閱讀文章提到高血壓，學生不應錯選低血壓。"},{"en":"The phrase contrasts with high blood pressure.","zh":"這個短語與高血壓形成對比。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":20},{"front":"contributing to obesity","meaning":"促成肥胖","examples":[{"en":"Environmental factors contributing to obesity include lack of exercise.","zh":"促成肥胖的環境因素包括缺乏運動。"},{"en":"Contributing to obesity means helping to cause or increase obesity.","zh":"“Contributing to obesity” 指幫助造成或增加肥胖。"},{"en":"Large portions and sugary drinks may be factors contributing to obesity.","zh":"大分量食物和含糖飲品可能是促成肥胖的因素。"},{"en":"If a neighbourhood has no safe parks, low activity may contribute to obesity.","zh":"如果社區沒有安全公園，低活動量可能促成肥胖。"},{"en":"The phrase identifies causes or supporting factors.","zh":"這個短語指出原因或支持因素。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":20},{"front":"lack of exercise","meaning":"缺乏運動","examples":[{"en":"Lack of exercise is an environmental factor contributing to obesity.","zh":"缺乏運動是促成肥胖的環境因素。"},{"en":"Lack of exercise means not getting enough physical activity.","zh":"缺乏運動指沒有足夠身體活動。"},{"en":"A child may have a lack of exercise if they spend most free time sitting with a screen.","zh":"如果孩子大部分空閒時間都坐着看螢幕，就可能缺乏運動。"},{"en":"If lack of exercise continues, the body may use fewer calories each day.","zh":"如果缺乏運動持續，身體每天消耗的卡路里可能較少。"},{"en":"The phrase describes insufficient movement.","zh":"這個短語描述活動量不足。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":20},{"front":"larger portions of food","meaning":"較大的食物分量","examples":[{"en":"Larger portions of food at restaurants can contribute to obesity.","zh":"餐廳中較大的食物分量可以促成肥胖。"},{"en":"Larger portions of food are bigger servings than people used to receive or need.","zh":"較大的食物分量是比人們以往收到或實際需要更多的食物份量。"},{"en":"A child may eat larger portions of food if the plate is filled too heavily.","zh":"如果碟子裝得太滿，孩子可能吃下較大的食物分量。"},{"en":"If restaurants serve larger portions, customers may consume extra calories without planning to.","zh":"如果餐廳提供較大食物分量，顧客可能在沒有計劃下攝取額外卡路里。"},{"en":"The phrase connects serving size with overeating risk.","zh":"這個短語把供應分量與過量進食風險連繫起來。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":20},{"front":"bad things that parents do","meaning":"父母做的不良做法","examples":[{"en":"The question asks about bad things that parents do.","zh":"題目問父母做的不良做法。"},{"en":"Bad things that parents do are harmful habits or actions that may create problems for children.","zh":"父母做的不良做法，是可能為兒童造成問題的有害習慣或行動。"},{"en":"Forcing children to finish food can be one of the bad things that parents do at meals.","zh":"強迫兒童吃完食物可以是父母在用膳時做的不良做法之一。"},{"en":"If parents use food as a reward, they may unintentionally teach unhealthy attitudes to food.","zh":"如果父母以食物作為獎勵，可能無意中教導不健康的食物態度。"},{"en":"The phrase refers to actions needing correction, not blaming parents as people.","zh":"這個短語指需要糾正的行動，而不是責怪父母本人。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":20},{"front":"finish their dinners","meaning":"吃完整頓晚餐","examples":[{"en":"Parents should not force children to finish their dinners.","zh":"父母不應強迫兒童吃完整頓晚餐。"},{"en":"To finish their dinners means to eat all the food served at dinner.","zh":"“Finish their dinners” 指吃完晚餐時盛給他們的所有食物。"},{"en":"A child may be full before they finish their dinner.","zh":"孩子可能在吃完整頓晚餐前已經飽了。"},{"en":"If children are forced to finish their dinners, they may ignore natural fullness signals.","zh":"如果兒童被強迫吃完整頓晚餐，可能會忽略自然飽足訊號。"},{"en":"The phrase describes a common family mealtime expectation.","zh":"這個短語描述常見家庭用膳期望。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":21},{"front":"second portions of food","meaning":"第二份食物","examples":[{"en":"Parents should wait before serving second portions of food.","zh":"父母應在提供第二份食物前等待。"},{"en":"Second portions of food are extra servings given after the first serving has been eaten.","zh":"第二份食物是在第一份食物吃完後再給的額外分量。"},{"en":"At dinner, a child may ask for second portions of food if still hungry.","zh":"晚飯時，如果孩子仍然肚餓，可能要求第二份食物。"},{"en":"If second portions are served too quickly, the child may eat before fullness messages arrive.","zh":"如果第二份食物太快被提供，孩子可能在飽足訊息到達前進食。"},{"en":"The phrase refers to additional food after the first portion.","zh":"這個短語指第一份後的額外食物。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":21},{"front":"want them even more","meaning":"更加想要它們","examples":[{"en":"Forbidding foods may make children want them even more.","zh":"禁止食物可能令兒童更加想要它們。"},{"en":"To want them even more means to desire those things more strongly than before.","zh":"“Want them even more” 指比以前更強烈地想要那些東西。"},{"en":"If a toy is completely banned, a child may want it even more.","zh":"如果玩具被完全禁止，孩子可能更加想要它。"},{"en":"When snacks become forbidden, children may see them as exciting and special.","zh":"當零食變成被禁止之物，兒童可能把它們視為刺激和特別。"},{"en":"The phrase describes desire increasing because of restriction.","zh":"這個短語描述慾望因限制而增加。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":21},{"front":"be offered a choice of food","meaning":"獲提供食物選擇","examples":[{"en":"Children should not always be offered a wide choice of food.","zh":"兒童不應總是獲提供廣泛食物選擇。"},{"en":"To be offered a choice of food means to be given several food options to choose from.","zh":"“Be offered a choice of food” 指獲給予幾種食物選項去選擇。"},{"en":"At a buffet, children are offered a wide choice of food.","zh":"在自助餐中，兒童獲提供廣泛食物選擇。"},{"en":"If children are offered too much choice, they may eat more because many foods look tempting.","zh":"如果兒童獲提供太多選擇，可能因許多食物看起來誘人而吃得更多。"},{"en":"The phrase describes receiving food options.","zh":"這個短語描述獲得食物選項。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":21},{"front":"be treated equally","meaning":"被平等對待","examples":[{"en":"The option says children should be treated equally.","zh":"該選項說兒童應被平等對待。"},{"en":"To be treated equally means to be treated in the same fair way as others.","zh":"“Be treated equally” 指以與他人相同且公平的方式被對待。"},{"en":"In a classroom, students should be treated equally when rules are applied.","zh":"在課室中，執行規則時學生應被平等對待。"},{"en":"If the whole family changes meals together, the overweight child may feel treated equally rather than singled out.","zh":"如果全家一起改變膳食，超重兒童可能感到被平等對待，而不是被單獨挑出。"},{"en":"The phrase focuses on fairness and avoiding blame.","zh":"這個短語強調公平和避免責怪。"}],"source":"97 - Childhood Obesity.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 98":[{"front":"Fruit That Falls Far from the Tree","meaning":"離樹很遠的果實；遠離本源的人","examples":[{"en":"The title Fruit That Falls Far from the Tree suggests people moving far from their origins.","zh":"標題 Fruit That Falls Far from the Tree 暗示人們遠離自己的本源。"},{"en":"Fruit that falls far from the tree refers to people who move far away from where they began.","zh":"fruit that falls far from the tree 指遠離自己起點或出身地的人。"},{"en":"A student from a small village who studies abroad may feel like fruit that falls far from the tree.","zh":"一個來自小村莊、後來到海外讀書的學生，可能像離樹很遠的果實。"},{"en":"When talented people leave home for better chances, their success may also create distance from their roots.","zh":"當有才能的人為了更好機會離鄉，他們的成功也可能使他們與根源產生距離。"},{"en":"This phrase plays on the idea that children or talents do not always stay close to their source.","zh":"這個片語借用果實與樹的意象，表示孩子或人才不一定留在源頭附近。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":1},{"front":"reigning world champions","meaning":"衛冕世界冠軍","examples":[{"en":"France were the reigning world champions before their defeat by Senegal.","zh":"法國在敗給塞內加爾前是衛冕世界冠軍。"},{"en":"Reigning world champions are the team or person currently holding the world championship title.","zh":"reigning world champions 是目前持有世界冠軍頭銜的隊伍或人物。"},{"en":"A boxer is the reigning world champion until another boxer defeats him for the title.","zh":"拳擊手在另一名拳手擊敗他奪冠前，就是衛冕世界冠軍。"},{"en":"If reigning world champions lose to a weaker team, the result can shock fans.","zh":"如果衛冕世界冠軍輸給較弱隊伍，結果可能震驚球迷。"},{"en":"This phrase describes current title holders, not former champions from long ago.","zh":"這個片語描述目前持有冠軍頭銜者，而不是很久以前的前冠軍。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":1},{"front":"suffer a humiliating defeat","meaning":"遭受恥辱性失敗","examples":[{"en":"France suffered a humiliating defeat to Senegal in the 2002 World Cup.","zh":"法國在2002年世界盃遭塞內加爾擊敗，遭受恥辱性失敗。"},{"en":"To suffer a humiliating defeat means to lose in a way that causes shame or embarrassment.","zh":"suffer a humiliating defeat 指以令人羞愧或尷尬的方式落敗。"},{"en":"A school team may suffer a humiliating defeat if it loses heavily after expecting an easy win.","zh":"如果校隊原本預期輕鬆勝出，卻大敗而回，便可能遭受恥辱性失敗。"},{"en":"Such a defeat can damage confidence and force a team to rethink its preparation.","zh":"這樣的失敗可以打擊信心，迫使隊伍重新思考準備工作。"},{"en":"This phrase is stronger than simply lose because it includes public embarrassment.","zh":"這個片語比 simply lose 更強，因為它包含公開尷尬。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":1},{"front":"unfancied Senegal","meaning":"不被看好的塞內加爾","examples":[{"en":"France lost to unfancied Senegal in the 2002 World Cup.","zh":"法國在2002年世界盃敗給不被看好的塞內加爾。"},{"en":"Unfancied Senegal means Senegal was not expected by most people to win.","zh":"unfancied Senegal 指大多數人原本不預期塞內加爾會勝出。"},{"en":"An unfancied school team may surprise everyone by beating the strongest team in the tournament.","zh":"一支不被看好的校隊可能擊敗錦標賽中最強的隊伍，令所有人意外。"},{"en":"When an unfancied side wins, people often question their assumptions about ability and reputation.","zh":"當不被看好的一方勝出，人們常會質疑自己對能力和名氣的假設。"},{"en":"This phrase describes low expectations before the event.","zh":"這個片語描述賽前期望很低。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":1},{"front":"victorious team","meaning":"獲勝隊伍","examples":[{"en":"All 11 members of the victorious Senegalese team had played for European clubs.","zh":"獲勝的塞內加爾隊11名成員都曾效力歐洲球會。"},{"en":"A victorious team is the team that wins a match, competition, or battle.","zh":"victorious team 是在比賽、競賽或戰鬥中勝出的一方。"},{"en":"The victorious debate team celebrated after winning the inter-school final.","zh":"獲勝的辯論隊在贏得校際決賽後慶祝。"},{"en":"A victorious team may gain confidence, publicity, and new opportunities after a major win.","zh":"獲勝隊伍在重大勝利後可能獲得信心、曝光和新機會。"},{"en":"This phrase focuses on the winning side.","zh":"這個片語聚焦於勝出的一方。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":1},{"front":"play for European clubs","meaning":"效力歐洲球會","examples":[{"en":"Many Senegalese footballers had played for European clubs.","zh":"許多塞內加爾足球員曾效力歐洲球會。"},{"en":"To play for European clubs means to be employed as a footballer by teams based in Europe.","zh":"play for European clubs 指受僱於歐洲球隊作為足球員。"},{"en":"A young player may dream of playing for European clubs because the leagues are famous and well paid.","zh":"年輕球員可能夢想效力歐洲球會，因為那些聯賽有名且薪酬高。"},{"en":"If many players leave to play abroad, local leagues may lose talent but gain role models.","zh":"如果許多球員離鄉效力海外球會，本地聯賽可能失去人才，但也得到榜樣。"},{"en":"This phrase describes professional football migration.","zh":"這個片語描述職業足球移民。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":1},{"front":"they were not alone","meaning":"他們並非個別例子","examples":[{"en":"The Senegalese players were not alone in moving to European clubs.","zh":"塞內加爾球員轉到歐洲球會，他們並非個別例子。"},{"en":"They were not alone means other people were in the same situation too.","zh":"they were not alone 指其他人也處於同樣情況。"},{"en":"A student who feels nervous before an exam is not alone because many classmates feel the same.","zh":"考試前感到緊張的學生並不孤單，因為很多同學也有同感。"},{"en":"If one country loses players to richer leagues, it may not be alone; many others may face similar migration.","zh":"如果一個國家流失球員到較富裕聯賽，它可能不是唯一例子；很多國家也有類似移民。"},{"en":"This phrase shows that a case is part of a wider pattern.","zh":"這個片語顯示某個個案屬於更廣泛模式。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":1},{"front":"first and second divisions","meaning":"甲組和乙組聯賽","examples":[{"en":"African players appeared in the first and second divisions of Europe’s leagues.","zh":"非洲球員出現在歐洲聯賽的甲組和乙組。"},{"en":"First and second divisions are the top two levels of a sports league system.","zh":"first and second divisions 是體育聯賽制度中的最高兩個級別。"},{"en":"A footballer in the second division may still play professionally and earn a strong salary.","zh":"乙組球員仍可能是職業球員，並賺取可觀薪酬。"},{"en":"If many foreign players enter first and second divisions, the leagues become more international.","zh":"如果許多外國球員進入甲組和乙組聯賽，聯賽會變得更國際化。"},{"en":"This phrase refers to ranking levels within organised sport.","zh":"這個片語指有組織體育中的排名級別。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":1},{"front":"poach African players","meaning":"挖走非洲球員","examples":[{"en":"European leagues had poached many African players.","zh":"歐洲聯賽已挖走許多非洲球員。"},{"en":"To poach African players means to attract or take African players away from their original clubs or countries.","zh":"poach African players 指吸引或帶走非洲球員，使他們離開原本球會或國家。"},{"en":"A rich school may be accused of poaching athletes if it offers scholarships to rival teams’ best players.","zh":"如果富裕學校向對手球隊最強球員提供獎學金，可能被指挖走運動員。"},{"en":"If wealthy clubs poach players, poorer leagues may lose talent and spectators.","zh":"如果富裕球會挖走球員，較貧窮聯賽可能失去人才和觀眾。"},{"en":"This phrase often suggests unfair or aggressive recruitment.","zh":"這個片語常暗示不公平或進取的招攬。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":1},{"front":"field 70 teams","meaning":"派出70支球隊","examples":[{"en":"Europe’s leagues had enough African players to field 70 teams.","zh":"歐洲聯賽擁有足夠非洲球員，可以派出70支球隊。"},{"en":"To field 70 teams means to have enough players to send out or form seventy teams.","zh":"field 70 teams 指有足夠球員派出或組成70支隊伍。"},{"en":"A school with many students could field several debate teams for a competition.","zh":"一間有很多學生的學校可以派出幾支辯論隊參加比賽。"},{"en":"If a league can field many teams from foreign players alone, migration has reached a large scale.","zh":"如果單靠外國球員已能組成許多球隊，移民規模已經很大。"},{"en":"This phrase is about having enough people to form teams.","zh":"這個片語關於有足夠人手組成隊伍。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":1},{"front":"greedy European clubs","meaning":"貪婪的歐洲球會","examples":[{"en":"The passage asks whether greedy European clubs deprived Senegal of its best footballers.","zh":"文章問貪婪的歐洲球會是否剝奪了塞內加爾最好的足球員。"},{"en":"Greedy European clubs are clubs described as wanting too much talent, money, or success for themselves.","zh":"greedy European clubs 是被描述為過度追求人才、金錢或成功的歐洲球會。"},{"en":"A company may be called greedy if it takes all the best workers from smaller firms.","zh":"如果公司從較小企業挖走所有最好員工，可能被稱為貪婪。"},{"en":"If clubs recruit aggressively, critics may say they damage poorer football systems.","zh":"如果球會積極招攬球員，批評者可能說它們傷害較貧窮足球體系。"},{"en":"This phrase is critical and suggests selfish behaviour.","zh":"這個片語帶批評意味，暗示自私行為。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":1},{"front":"deprive someone of","meaning":"剝奪某人……","examples":[{"en":"European clubs may have deprived Senegal of its best footballers.","zh":"歐洲球會可能剝奪了塞內加爾最好的足球員。"},{"en":"To deprive someone of something means to take it away or prevent them from having it.","zh":"deprive someone of something 指拿走某物或阻止某人擁有它。"},{"en":"Lack of sleep can deprive students of the concentration they need in class.","zh":"睡眠不足可以剝奪學生上課所需的專注力。"},{"en":"If skilled workers leave, a country may be deprived of services it badly needs.","zh":"如果技術工人離開，一個國家可能被剝奪急需的服務。"},{"en":"This phrase usually describes a serious loss.","zh":"這個片語通常描述嚴重損失。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":2},{"front":"the prospect of","meaning":"……的前景","examples":[{"en":"The prospect of a lucrative career in Europe encouraged more Senegalese to play football.","zh":"在歐洲發展賺錢豐厚事業的前景鼓勵更多塞內加爾人踢足球。"},{"en":"The prospect of something means the possibility that it may happen in the future.","zh":"the prospect of something 指某事將來可能發生的可能性。"},{"en":"The prospect of a scholarship may motivate a student to study harder.","zh":"獎學金的前景可能激勵學生更努力學習。"},{"en":"If the prospect of migration is attractive, more people may invest in training.","zh":"如果移民前景吸引，更多人可能投資於培訓。"},{"en":"This phrase focuses on a future possibility that influences present choices.","zh":"這個片語聚焦於影響當前選擇的未來可能性。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":2},{"front":"a lucrative career","meaning":"賺錢豐厚的事業","examples":[{"en":"A lucrative career in Europe attracted many Senegalese footballers.","zh":"在歐洲賺錢豐厚的事業吸引了許多塞內加爾足球員。"},{"en":"A lucrative career is a job path that can bring a lot of money.","zh":"lucrative career 是可以帶來很多收入的職業道路。"},{"en":"A doctor may leave a small town for a lucrative career in a major hospital.","zh":"醫生可能離開小鎮，到大型醫院追求賺錢豐厚的事業。"},{"en":"If young people see a lucrative career abroad, they may study or train harder.","zh":"如果年輕人看見海外有賺錢豐厚的事業，可能更努力學習或訓練。"},{"en":"This phrase stresses financial reward.","zh":"這個片語強調金錢回報。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":2},{"front":"encourage someone to","meaning":"鼓勵某人去……","examples":[{"en":"The chance of success encouraged more Senegalese to take up football.","zh":"成功機會鼓勵更多塞內加爾人開始踢足球。"},{"en":"To encourage someone to do something means to make them feel motivated or willing to do it.","zh":"encourage someone to do something 指令某人有動機或願意做某事。"},{"en":"A teacher may encourage students to read by choosing books about their interests.","zh":"老師可能透過選擇關於學生興趣的書，鼓勵學生閱讀。"},{"en":"If successful migrants return with stories of opportunity, they may encourage others to study.","zh":"如果成功移民帶着機會故事回來，可能鼓勵其他人讀書。"},{"en":"This phrase describes positive pressure or motivation.","zh":"這個片語描述正面推動或動機。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":2},{"front":"take up the beautiful game","meaning":"開始踢足球","examples":[{"en":"More Senegalese were encouraged to take up the beautiful game.","zh":"更多塞內加爾人受到鼓勵開始踢足球。"},{"en":"To take up the beautiful game means to start playing football.","zh":"take up the beautiful game 指開始踢足球。"},{"en":"A child may take up football after watching a local player succeed overseas.","zh":"孩子看到本地球員在海外成功後，可能開始踢足球。"},{"en":"If football offers a path to a better career, more young people may begin training seriously.","zh":"如果足球提供更好事業道路，更多年輕人可能開始認真訓練。"},{"en":"This phrase uses the beautiful game as a common nickname for football.","zh":"這個片語使用 the beautiful game 作為足球的常見別稱。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":2},{"front":"pose a question","meaning":"提出問題","examples":[{"en":"The book poses a question about football migration and the brain drain.","zh":"這本書提出一個關於足球移民和人才外流的問題。"},{"en":"To pose a question means to raise or present a question for people to consider.","zh":"pose a question 指提出一個問題供人思考。"},{"en":"A teacher may pose a question at the start of class to make students think.","zh":"老師可能在課堂開始時提出問題，讓學生思考。"},{"en":"If a problem has both benefits and harms, posing a question can open discussion.","zh":"如果一個問題同時有利有弊，提出問題可以開啟討論。"},{"en":"This phrase is more formal than simply ask.","zh":"這個片語比 simply ask 更正式。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":2},{"front":"development economists","meaning":"發展經濟學家","examples":[{"en":"The authors are development economists first and football fans second.","zh":"作者首先是發展經濟學家，其次才是足球迷。"},{"en":"Development economists study how poor countries grow, reduce poverty, and improve living standards.","zh":"development economists 研究貧窮國家如何增長、減少貧窮和改善生活水平。"},{"en":"A development economist may study whether migration helps or harms a country’s schools and hospitals.","zh":"發展經濟學家可能研究移民是幫助還是傷害一個國家的學校和醫院。"},{"en":"If skilled workers leave poor countries, development economists ask about the long-term effects.","zh":"如果技術工人離開貧窮國家，發展經濟學家會問長期影響是甚麼。"},{"en":"This phrase names specialists in economic development.","zh":"這個片語指經濟發展方面的專家。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":2},{"front":"if at all","meaning":"如果算是的話","examples":[{"en":"The authors are football fans second, if at all.","zh":"作者其次才是足球迷，如果算是的話。"},{"en":"If at all means if something is true, it is true only slightly or uncertainly.","zh":"if at all 指如果某事成立，也只是很輕微或不確定地成立。"},{"en":"He speaks French rarely, if at all, because he has almost forgotten it.","zh":"他很少說法語，如果有說的話，因為他幾乎忘記了。"},{"en":"If a researcher is a sports fan only if at all, their main interest is probably economic evidence.","zh":"如果研究者只是勉強算是體育迷，他的主要興趣很可能是經濟證據。"},{"en":"This phrase weakens or questions the statement before it.","zh":"這個片語削弱或質疑前面的說法。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":2},{"front":"the emigration of","meaning":"……的移民外流","examples":[{"en":"The emigration of African players is an example of the brain drain.","zh":"非洲球員的移民外流是人才外流的一個例子。"},{"en":"The emigration of a group means people from that group leave their country to live or work elsewhere.","zh":"the emigration of a group 指該群體的人離開本國到別處生活或工作。"},{"en":"The emigration of young nurses may leave local hospitals short of staff.","zh":"年輕護士的移民外流可能令本地醫院人手不足。"},{"en":"If emigration is large, the home country may lose skills but also gain remittances and connections.","zh":"如果移民外流規模大，原居國可能失去技能，但也可能得到匯款和人脈。"},{"en":"This phrase focuses on movement out of a country.","zh":"這個片語聚焦於人口向外流出。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":2},{"front":"a highly visible example of","meaning":"……的高度可見例子","examples":[{"en":"Football migration is a highly visible example of the brain drain.","zh":"足球移民是人才外流的一個高度可見例子。"},{"en":"A highly visible example of something is an example that many people can easily see or notice.","zh":"a highly visible example of something 是許多人容易看見或注意到的例子。"},{"en":"Long queues outside a clinic are a highly visible example of staff shortages.","zh":"診所外的長隊是人手短缺的高度可見例子。"},{"en":"Footballers are famous, so their migration is easier to notice than that of nurses or teachers.","zh":"足球員有名，所以他們的移民比護士或教師的移民更容易被注意。"},{"en":"This phrase stresses that an example is obvious to the public.","zh":"這個片語強調例子對公眾來說很明顯。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":2},{"front":"brain drain","meaning":"人才外流","examples":[{"en":"The departure of skilled workers from poor countries is often called brain drain.","zh":"技術工人離開貧窮國家常被稱為人才外流。"},{"en":"Brain drain means the loss of educated or skilled people from one country or place to another.","zh":"brain drain 指受教育或有技能的人從一個國家或地方流失到另一地。"},{"en":"A small town may suffer brain drain if its best graduates all move to the capital.","zh":"如果小鎮最優秀畢業生都搬到首都，它可能遭受人才外流。"},{"en":"Brain drain can weaken hospitals, schools, and businesses in the places people leave.","zh":"人才外流可以削弱人們離開地區的醫院、學校和企業。"},{"en":"This phrase usually carries concern about losing human talent.","zh":"這個片語通常帶有對人才流失的憂慮。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":2},{"front":"less visible, but more worrying","meaning":"較不明顯但更令人擔憂","examples":[{"en":"The departure of doctors and nurses is less visible, but more worrying.","zh":"醫生和護士的離開較不明顯，但更令人擔憂。"},{"en":"Less visible, but more worrying means harder to notice but more serious in effect.","zh":"less visible, but more worrying 指較難被看見，但影響更嚴重。"},{"en":"A cracked pipe under a school floor may be less visible but more worrying than peeling paint.","zh":"學校地板下破裂的水管可能比剝落油漆較不明顯，但更令人擔憂。"},{"en":"When doctors leave, the damage may not appear on television, but patients feel it deeply.","zh":"當醫生離開，傷害未必出現在電視上，但病人會深切感受到。"},{"en":"This phrase contrasts public attention with real seriousness.","zh":"這個片語對比公眾注意與真正嚴重性。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":3},{"front":"the departure of","meaning":"……的離開","examples":[{"en":"The departure of doctors, nurses and teachers worries development economists.","zh":"醫生、護士和教師的離開令發展經濟學家擔憂。"},{"en":"The departure of a group means those people leave a place, job, or country.","zh":"the departure of a group 指該群人離開某地方、工作或國家。"},{"en":"The departure of experienced teachers can make a school less stable.","zh":"有經驗教師的離開可以令學校較不穩定。"},{"en":"If trained workers depart, the community may lose services and knowledge.","zh":"如果受訓工人離開，社區可能失去服務和知識。"},{"en":"This phrase is often used when people leaving creates consequences.","zh":"當人們離開造成後果時，常使用這個片語。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":3},{"front":"the poor world","meaning":"貧窮國家；貧窮世界","examples":[{"en":"The poor world loses many skilled workers to richer countries.","zh":"貧窮世界失去許多技術工人到較富裕國家。"},{"en":"The poor world means poorer countries or regions with fewer economic resources.","zh":"the poor world 指經濟資源較少的貧窮國家或地區。"},{"en":"Hospitals in the poor world may struggle when doctors move abroad.","zh":"當醫生移居海外，貧窮國家的醫院可能難以運作。"},{"en":"If rich countries attract too many skilled workers, the poor world may face deeper shortages.","zh":"如果富國吸引太多技術工人，貧窮世界可能面對更深層短缺。"},{"en":"This phrase is broad and contrasts with the rich world.","zh":"這個片語較廣泛，與富裕世界相對。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":3},{"front":"lucrative job markets","meaning":"收入較高的就業市場","examples":[{"en":"Doctors may leave poor countries for more lucrative job markets.","zh":"醫生可能離開貧窮國家，前往收入較高的就業市場。"},{"en":"Lucrative job markets are places where workers can earn much higher pay.","zh":"lucrative job markets 是工人可以賺取高得多薪酬的地方。"},{"en":"A programmer may move to a lucrative job market if local salaries are very low.","zh":"如果本地薪酬很低，程式員可能搬到收入較高的就業市場。"},{"en":"If overseas job markets pay much more, skilled workers may be tempted to leave.","zh":"如果海外就業市場薪酬高很多，技術工人可能被吸引離開。"},{"en":"This phrase focuses on financial attraction in employment.","zh":"這個片語聚焦於就業中的金錢吸引力。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":3},{"front":"the rich world","meaning":"富裕國家；富裕世界","examples":[{"en":"Many skilled workers move to job markets in the rich world.","zh":"許多技術工人前往富裕世界的就業市場。"},{"en":"The rich world means wealthier countries with stronger economies and higher wages.","zh":"the rich world 指經濟較強、工資較高的富裕國家。"},{"en":"Universities in the rich world may attract students from poorer countries.","zh":"富裕國家的大學可能吸引來自貧窮國家的學生。"},{"en":"If the rich world recruits heavily, poorer countries may lose trained workers.","zh":"如果富裕世界大量招聘，較貧窮國家可能失去受訓工人。"},{"en":"This phrase contrasts economically powerful countries with poorer ones.","zh":"這個片語把經濟強國與較貧窮國家作對比。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":3},{"front":"per 100,000 people","meaning":"每10萬人","examples":[{"en":"Ghana has only 6.2 doctors per 100,000 people.","zh":"加納每10萬人只有6.2名醫生。"},{"en":"Per 100,000 people means for every group of one hundred thousand people in a population.","zh":"per 100,000 people 指人口中每一組十萬人。"},{"en":"A city may report hospital beds per 100,000 people to compare healthcare access.","zh":"城市可能報告每10萬人的醫院床位數，以比較醫療可及性。"},{"en":"If a country has few doctors per 100,000 people, patients may wait longer for care.","zh":"如果一個國家每10萬人的醫生很少，病人可能要等待更久。"},{"en":"This phrase helps compare countries of different population sizes.","zh":"這個片語幫助比較人口規模不同的國家。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":3},{"front":"three-quarters of","meaning":"四分之三的……","examples":[{"en":"Perhaps three-quarters of Ghana’s doctors leave within ten years of qualifying.","zh":"加納可能有四分之三的醫生在取得資格後十年內離開。"},{"en":"Three-quarters of something means 75 percent of it.","zh":"three-quarters of something 指某物的75%。"},{"en":"Three-quarters of the class passed the exam, so most students succeeded.","zh":"班上四分之三的學生通過考試，所以大多數學生成功。"},{"en":"If three-quarters of trained doctors leave, the remaining health system faces heavy pressure.","zh":"如果四分之三受訓醫生離開，剩下的醫療系統會面對巨大壓力。"},{"en":"This phrase describes a large majority.","zh":"這個片語描述很大多數。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":3},{"front":"within ten years of qualifying","meaning":"取得資格後十年內","examples":[{"en":"Many doctors leave Ghana within ten years of qualifying.","zh":"許多醫生在取得資格後十年內離開加納。"},{"en":"Within ten years of qualifying means before ten years have passed after becoming officially trained or certified.","zh":"within ten years of qualifying 指正式受訓或取得資格後十年過去之前。"},{"en":"A teacher may change schools within ten years of qualifying if better opportunities appear.","zh":"如果更好機會出現，教師可能在取得資格後十年內轉校。"},{"en":"If doctors leave soon after qualifying, the country loses the benefit of its training investment.","zh":"如果醫生取得資格後不久離開，國家便失去培訓投資的好處。"},{"en":"This phrase gives a time limit after professional qualification.","zh":"這個片語給出取得專業資格後的時間限制。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":3},{"front":"the Senegal conundrum","meaning":"塞內加爾難題","examples":[{"en":"The Senegal conundrum concerns whether football migration helps or harms Senegal.","zh":"塞內加爾難題關於足球移民究竟幫助還是傷害塞內加爾。"},{"en":"The Senegal conundrum is the puzzle of whether losing players abroad is good or bad overall.","zh":"the Senegal conundrum 是失去球員到海外整體上是好是壞的難題。"},{"en":"A school may face a similar conundrum if its best students leave but inspire others to study harder.","zh":"如果一間學校最優秀學生離開，但激勵其他人更努力讀書，它可能面對類似難題。"},{"en":"If migrants both remove talent and encourage training, the final effect becomes hard to judge.","zh":"如果移民同時帶走人才並鼓勵培訓，最終影響便難以判斷。"},{"en":"This phrase names a difficult question with mixed effects.","zh":"這個片語指出一個有混合效果的困難問題。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":3},{"front":"of course","meaning":"當然","examples":[{"en":"The answer to the Senegal conundrum is of course both.","zh":"塞內加爾難題的答案當然是兩者皆是。"},{"en":"Of course means naturally, obviously, or as expected.","zh":"of course 指自然地、明顯地或如預期地。"},{"en":"Of course, students need practice if they want to speak more fluently.","zh":"當然，如果學生想說得更流利，就需要練習。"},{"en":"If a policy has both benefits and costs, the answer may of course be complicated.","zh":"如果政策有利也有弊，答案當然可能很複雜。"},{"en":"This phrase can introduce something the writer thinks should be clear.","zh":"這個片語可以引入作者認為應該清楚的事情。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":3},{"front":"the dream of emulating someone","meaning":"效法某人的夢想","examples":[{"en":"The dream of emulating successful players motivates many young people.","zh":"效法成功球員的夢想激勵許多年輕人。"},{"en":"The dream of emulating someone means wanting to copy or equal another person’s success.","zh":"the dream of emulating someone 指想模仿或達到另一個人的成功。"},{"en":"A young musician may practise daily because of the dream of emulating a famous singer.","zh":"年輕音樂人可能因效法著名歌手的夢想而每天練習。"},{"en":"If role models succeed abroad, others may train harder to follow their path.","zh":"如果榜樣在海外成功，其他人可能更努力訓練以追隨他們的道路。"},{"en":"This phrase links admiration with ambition.","zh":"這個片語把崇拜與抱負連接起來。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":3},{"front":"motivate someone to","meaning":"激勵某人去……","examples":[{"en":"The success of emigrant players motivates others to take their place.","zh":"移民球員的成功激勵其他人取代他們的位置。"},{"en":"To motivate someone to do something means to give them a reason or desire to do it.","zh":"motivate someone to do something 指給某人理由或意欲去做某事。"},{"en":"A scholarship can motivate a student to stay in school longer.","zh":"獎學金可以激勵學生繼續留校讀書更久。"},{"en":"If migration success is visible, it may motivate young people to invest in education.","zh":"如果移民成功很顯眼，它可能激勵年輕人投資於教育。"},{"en":"This phrase describes the force that encourages action.","zh":"這個片語描述鼓勵行動的力量。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":4},{"front":"take someone’s place","meaning":"取代某人的位置","examples":[{"en":"Young players are motivated to take the place of those who leave.","zh":"年輕球員受到激勵去取代離開者的位置。"},{"en":"To take someone’s place means to replace that person in a role, job, or position.","zh":"take someone’s place 指在角色、工作或位置上取代某人。"},{"en":"When a team captain graduates, another student may take her place.","zh":"當隊長畢業，另一名學生可能取代她的位置。"},{"en":"If skilled workers leave, new trainees may try to take their place.","zh":"如果技術工人離開，新受訓者可能嘗試取代他們的位置。"},{"en":"This phrase shows replacement after someone is absent or has moved on.","zh":"這個片語顯示某人離開後的替代。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":4},{"front":"outweigh the first","meaning":"超過前者；比前者重要","examples":[{"en":"The real question is whether the second effect outweighs the first.","zh":"真正問題是第二種效果是否超過前者。"},{"en":"To outweigh the first means to be more important or stronger than the first effect.","zh":"outweigh the first 指比第一種效果更重要或更強。"},{"en":"A higher salary may outweigh the longer journey if the job also offers training.","zh":"如果工作也提供培訓，較高薪金可能超過較長通勤的缺點。"},{"en":"If inspiration from emigrants creates many new skilled workers, it may outweigh the loss of those who left.","zh":"如果移民帶來的激勵創造許多新技術工人，它可能超過離開者造成的損失。"},{"en":"This phrase compares two effects and asks which is larger.","zh":"這個片語比較兩種效果，並問哪一個較大。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":4},{"front":"stronger or weaker than","meaning":"比……更強或更弱","examples":[{"en":"The brain drain may leave a country stronger or weaker than it otherwise would be.","zh":"人才外流可能令一個國家比在其他情況下更強或更弱。"},{"en":"Stronger or weaker than means better or worse compared with another possible situation.","zh":"stronger or weaker than 指相比另一種可能情況更好或更差。"},{"en":"A school may become stronger or weaker than before depending on whether good teachers stay.","zh":"學校可能比以前更強或更弱，視乎好老師是否留下。"},{"en":"If migration raises education but removes doctors, the country’s final position is hard to judge.","zh":"如果移民提高教育但帶走醫生，國家的最終處境便難以判斷。"},{"en":"This phrase compares real outcomes with an alternative possibility.","zh":"這個片語把真實結果與另一可能性作比較。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":4},{"front":"otherwise would be","meaning":"在其他情況下會是","examples":[{"en":"Senegal may be stronger or weaker than it otherwise would be.","zh":"塞內加爾可能比在其他情況下會更強或更弱。"},{"en":"Otherwise would be means would be in a different situation if the event had not happened.","zh":"otherwise would be 指如果某事件沒有發生，情況本來會是另一樣子。"},{"en":"Without extra tutoring, a student might be weaker than she otherwise would be.","zh":"如果沒有額外補習，學生可能比原本可以達到的水平更弱。"},{"en":"If migration encourages more training, a country may end up more educated than it otherwise would be.","zh":"如果移民鼓勵更多培訓，一個國家最終可能比其他情況下更有教育水平。"},{"en":"This phrase asks us to compare reality with a possible alternative world.","zh":"這個片語要求我們把現實與另一個可能世界作比較。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":4},{"front":"net effect","meaning":"淨效果","examples":[{"en":"The net effect of the brain drain is ambiguous.","zh":"人才外流的淨效果含糊不清。"},{"en":"The net effect is the overall result after both positive and negative effects are considered.","zh":"net effect 是同時考慮正面和負面影響後的整體結果。"},{"en":"A new bus route may have a positive net effect if it reduces travel time more than it increases noise.","zh":"如果新巴士路線減少通勤時間的好處大於增加噪音的壞處，它可能有正面淨效果。"},{"en":"If emigration causes both loss and learning, its net effect is hard to calculate.","zh":"如果移民同時造成損失和學習，其淨效果便難以計算。"},{"en":"This phrase focuses on the final balance.","zh":"這個片語聚焦於最終平衡。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":4},{"front":"similarly ambiguous","meaning":"同樣含糊不清","examples":[{"en":"The net effect of the brain drain is similarly ambiguous.","zh":"人才外流的淨效果同樣含糊不清。"},{"en":"Similarly ambiguous means unclear in the same kind of way.","zh":"similarly ambiguous 指以相似方式不清楚。"},{"en":"The effect of online learning is similarly ambiguous because it helps some students but hurts others.","zh":"網上學習的效果同樣含糊不清，因為它幫助一些學生，但傷害另一些學生。"},{"en":"If both football migration and doctor migration have mixed outcomes, both are similarly hard to judge.","zh":"如果足球移民和醫生移民都有混合結果，兩者便同樣難以判斷。"},{"en":"This phrase links two unclear situations.","zh":"這個片語把兩個不清楚的情況連接起來。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":4},{"front":"secure a visa","meaning":"取得簽證","examples":[{"en":"The prospect of securing a visa may encourage people to study.","zh":"取得簽證的前景可能鼓勵人們讀書。"},{"en":"To secure a visa means to successfully obtain official permission to enter or live in another country.","zh":"secure a visa 指成功取得進入或居住另一國家的官方許可。"},{"en":"A student may study English harder because she hopes to secure a visa for university abroad.","zh":"學生可能更努力學英文，因為她希望取得海外大學簽證。"},{"en":"If visas are possible but difficult, people may invest in qualifications to improve their chances.","zh":"如果簽證有可能但困難，人們可能投資於學歷以提高機會。"},{"en":"This phrase describes getting legal permission to migrate or travel.","zh":"這個片語描述取得合法移民或旅行許可。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":4},{"front":"tempt someone to","meaning":"吸引某人去……","examples":[{"en":"The chance of migration may tempt people to invest in education.","zh":"移民機會可能吸引人們投資於教育。"},{"en":"To tempt someone to do something means to attract them toward doing it.","zh":"tempt someone to do something 指吸引某人去做某事。"},{"en":"A discount may tempt customers to buy a product earlier than planned.","zh":"折扣可能吸引顧客比原計劃更早購買產品。"},{"en":"If overseas jobs pay more, they may tempt young people to study longer.","zh":"如果海外工作薪酬更高，它們可能吸引年輕人讀書更久。"},{"en":"This phrase can be positive or negative depending on context.","zh":"這個片語可正可負，視乎語境。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":4},{"front":"invest in education","meaning":"投資於教育","examples":[{"en":"People in poor countries may invest in education to improve their chances abroad.","zh":"貧窮國家的人可能投資於教育，以改善自己在海外的機會。"},{"en":"To invest in education means to spend time, money, or effort on learning and qualifications.","zh":"invest in education 指把時間、金錢或努力投入學習和學歷。"},{"en":"A family may invest in education by paying for books, courses, and exam fees.","zh":"家庭可能透過支付書本、課程和考試費來投資於教育。"},{"en":"If education raises the chance of migration, more young people may stay in school.","zh":"如果教育提高移民機會，更多年輕人可能繼續留校讀書。"},{"en":"This phrase treats learning as something that can bring future returns.","zh":"這個片語把學習視為能帶來未來回報的投資。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":4},{"front":"brain gain","meaning":"人才增益","examples":[{"en":"Mr Stark calls this possible positive effect a brain gain.","zh":"Stark 先生把這種可能的正面效果稱為人才增益。"},{"en":"Brain gain means a country gains more educated or skilled people, even when some people leave.","zh":"brain gain 指即使有人離開，一個國家仍得到更多受教育或有技能的人。"},{"en":"A town may experience brain gain if students leave for university but later inspire others to study.","zh":"如果學生離鄉上大學，但之後激勵其他人讀書，小鎮可能出現人才增益。"},{"en":"If migration encourages more education than it removes talent, the home country may benefit.","zh":"如果移民鼓勵的教育多於它帶走的人才，原居國可能受益。"},{"en":"This phrase contrasts with brain drain.","zh":"這個片語與 brain drain 形成對比。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":4},{"front":"strong enough","meaning":"足夠強烈","examples":[{"en":"If the temptation is strong enough, more people may study.","zh":"如果誘惑足夠強烈，更多人可能會讀書。"},{"en":"Strong enough means powerful or attractive enough to produce a result.","zh":"strong enough 指力量或吸引力足以產生某結果。"},{"en":"A prize may be strong enough to make students join a reading challenge.","zh":"獎品可能足夠強烈地吸引學生參加閱讀挑戰。"},{"en":"If the hope of a better job is strong enough, people may accept years of training.","zh":"如果更好工作的希望足夠強烈，人們可能接受多年培訓。"},{"en":"This phrase links the strength of a cause with its effect.","zh":"這個片語把原因的強度與效果連接起來。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":5},{"front":"land a visa","meaning":"取得簽證","examples":[{"en":"If the chances of landing a visa are low, many educated people may stay.","zh":"如果取得簽證的機會低，許多受教育人士可能會留下。"},{"en":"To land a visa means to succeed in getting a visa.","zh":"land a visa 指成功取得簽證。"},{"en":"A graduate may learn a foreign language to improve his chance of landing a work visa.","zh":"畢業生可能學外語，以提高取得工作簽證的機會。"},{"en":"If few people land visas, many newly educated workers remain in their home country.","zh":"如果很少人取得簽證，許多新受教育工人便留在本國。"},{"en":"This phrase is informal and means successfully obtain.","zh":"這個片語較口語，意思是成功取得。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":5},{"front":"come out ahead","meaning":"最終得益","examples":[{"en":"A poor country could come out ahead if more people become educated than leave.","zh":"如果受教育的人比離開的人更多，貧窮國家可能最終得益。"},{"en":"To come out ahead means to end with a gain after costs and losses are considered.","zh":"come out ahead 指在考慮成本和損失後最終仍有收益。"},{"en":"A shop may come out ahead after a sale if higher customer numbers cover the discount.","zh":"如果更多顧客帶來的收入抵消折扣，小店在促銷後可能最終得益。"},{"en":"If migration encourages many people to study but only a few leave, the country may benefit overall.","zh":"如果移民鼓勵很多人讀書，但只有少數人離開，國家整體可能得益。"},{"en":"This phrase describes a positive final balance.","zh":"這個片語描述正面的最終平衡。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":5},{"front":"qualified doctors and engineers","meaning":"合資格的醫生和工程師","examples":[{"en":"A country might gain more qualified doctors and engineers than it loses.","zh":"一個國家得到的合資格醫生和工程師可能多於它失去的。"},{"en":"Qualified doctors and engineers are people officially trained and certified in medicine or engineering.","zh":"qualified doctors and engineers 是在醫學或工程方面正式受訓並取得資格的人。"},{"en":"A hospital needs qualified doctors, while a bridge project needs qualified engineers.","zh":"醫院需要合資格醫生，而橋樑工程需要合資格工程師。"},{"en":"If education expands, a country may produce more skilled professionals even after some emigrate.","zh":"如果教育擴大，一個國家即使有人移民，仍可能培養更多專業人才。"},{"en":"This phrase refers to trained experts, not ordinary workers.","zh":"這個片語指受訓專家，而不是普通工人。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":5},{"front":"theory has run ahead of evidence","meaning":"理論走在證據之前","examples":[{"en":"In debates about the brain drain, theory has run ahead of evidence.","zh":"在人才外流辯論中，理論走在證據之前。"},{"en":"Theory has run ahead of evidence means ideas and arguments have developed faster than reliable proof.","zh":"theory has run ahead of evidence 指想法和論點發展得比可靠證據更快。"},{"en":"A health trend may spread online before evidence catches up.","zh":"健康潮流可能在證據跟上之前已在網上流傳。"},{"en":"If migration data are weak, economists may have theories that are not yet fully tested.","zh":"如果移民數據薄弱，經濟學家可能有尚未完全驗證的理論。"},{"en":"This phrase warns that explanation may be stronger than evidence.","zh":"這個片語警告解釋可能比證據更強。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":5},{"front":"international flows of people","meaning":"國際人口流動","examples":[{"en":"The numbers on international flows of people are patchy.","zh":"關於國際人口流動的數字很零散。"},{"en":"International flows of people are movements of people across national borders.","zh":"international flows of people 是人口跨越國界的移動。"},{"en":"Students, workers, refugees, and families can all be part of international flows of people.","zh":"學生、工人、難民和家庭都可以屬於國際人口流動的一部分。"},{"en":"If these flows are not measured well, migration policy becomes harder to judge.","zh":"如果這些流動沒有被好好量度，移民政策便更難評估。"},{"en":"This phrase focuses on people moving between countries.","zh":"這個片語聚焦於人們在國家之間移動。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":5},{"front":"much patchier than","meaning":"比……零散得多","examples":[{"en":"Migration data are much patchier than data on trade or capital.","zh":"移民數據比貿易或資本數據零散得多。"},{"en":"Much patchier than means far less complete, regular, or reliable than something else.","zh":"much patchier than 指比另一事物遠遠更不完整、不規律或不可靠。"},{"en":"A student’s notes may be much patchier than the teacher’s slides if many lessons were missed.","zh":"如果學生缺席許多課，他的筆記可能比老師簡報零散得多。"},{"en":"If migration records are patchy, researchers cannot measure effects as clearly as trade flows.","zh":"如果移民記錄零散，研究人員便不能像量度貿易流動那樣清楚量度影響。"},{"en":"This phrase compares the quality of information.","zh":"這個片語比較資訊質素。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":5},{"front":"cross-border flows","meaning":"跨境流動","examples":[{"en":"Data on cross-border flows of goods are easier to measure.","zh":"貨物跨境流動的數據較容易量度。"},{"en":"Cross-border flows are movements across national borders.","zh":"cross-border flows 是跨越國界的流動。"},{"en":"Trucks carrying food from one country to another are part of cross-border flows.","zh":"從一個國家運送食物到另一國的貨車屬於跨境流動。"},{"en":"Goods crossing borders are often recorded at customs, so the data may be clearer than migration data.","zh":"貨物過境常在海關被記錄，所以數據可能比移民數據更清楚。"},{"en":"This phrase can refer to people, goods, money, or services moving internationally.","zh":"這個片語可以指人、貨物、金錢或服務的國際流動。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":5},{"front":"goods or capital","meaning":"貨物或資本","examples":[{"en":"Data on goods or capital are more complete than migration data.","zh":"貨物或資本的數據比移民數據更完整。"},{"en":"Goods or capital means physical products or financial money and assets.","zh":"goods or capital 指實體產品或金融資金和資產。"},{"en":"A company may move goods or capital across borders when it exports products or invests abroad.","zh":"公司出口產品或海外投資時，可能把貨物或資本跨境轉移。"},{"en":"Because goods and capital are often taxed or recorded, their flows can be easier to track.","zh":"因為貨物和資本常被徵稅或記錄，其流動較容易追蹤。"},{"en":"This phrase contrasts trade and finance with human migration.","zh":"這個片語把貿易和金融與人口移民作對比。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":5},{"front":"in a recent paper","meaning":"在最近一篇論文中","examples":[{"en":"In a recent paper, Stark and his co-authors investigated internal migration.","zh":"在最近一篇論文中，Stark 和他的合著者研究了國內遷移。"},{"en":"In a recent paper means in an academic article published not long ago.","zh":"in a recent paper 指在不久前發表的學術文章中。"},{"en":"In a recent paper, researchers may report new evidence about student learning.","zh":"在最近一篇論文中，研究人員可能報告關於學生學習的新證據。"},{"en":"If a recent paper studies migration, it may update older theories with newer data.","zh":"如果最近一篇論文研究移民，它可能用較新數據更新舊理論。"},{"en":"This phrase introduces research evidence from a scholarly source.","zh":"這個片語引入來自學術來源的研究證據。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":5},{"front":"co-authors","meaning":"合著者","examples":[{"en":"Mr Stark and his co-authors investigated internal migration.","zh":"Stark 先生和他的合著者研究了國內遷移。"},{"en":"Co-authors are people who write a paper, book, or report together.","zh":"co-authors 是共同撰寫論文、書籍或報告的人。"},{"en":"A student may have two co-authors for a group research project.","zh":"學生在小組研究項目中可能有兩位合著者。"},{"en":"If several co-authors work together, they can combine data, methods, and ideas.","zh":"如果幾位合著者合作，他們可以結合數據、方法和想法。"},{"en":"This word refers to shared authorship.","zh":"這個詞指共同作者身份。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":5},{"front":"internal migration","meaning":"國內遷移","examples":[{"en":"The researchers investigated internal migration in Mexico.","zh":"研究人員調查墨西哥的國內遷移。"},{"en":"Internal migration is movement from one place to another within the same country.","zh":"internal migration 是在同一國家內從一地移動到另一地。"},{"en":"A worker moving from a village to the capital city is an example of internal migration.","zh":"工人從村莊搬到首都城市，是國內遷移的例子。"},{"en":"If internal migration pulls young people to cities, villages may lose talent but gain connections.","zh":"如果國內遷移把年輕人吸引到城市，村莊可能失去人才，但得到人脈。"},{"en":"This phrase differs from international migration because no national border is crossed.","zh":"這個片語不同於國際移民，因為沒有跨越國界。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":6},{"front":"rural villages","meaning":"鄉村村落","examples":[{"en":"Rural villages in Mexico lose many of their brightest young people.","zh":"墨西哥鄉村村落失去許多最優秀的年輕人。"},{"en":"Rural villages are small countryside communities away from major cities.","zh":"rural villages 是遠離主要城市的小型鄉郊社區。"},{"en":"A rural village may have farms, small schools, and close family networks.","zh":"鄉村村落可能有農場、小學校和緊密家庭網絡。"},{"en":"If young people leave rural villages, local schools and businesses may shrink.","zh":"如果年輕人離開鄉村村落，本地學校和企業可能萎縮。"},{"en":"This phrase describes small non-urban communities.","zh":"這個片語描述小型非城市社區。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":6},{"front":"the brightest sons and daughters","meaning":"最優秀的年輕人","examples":[{"en":"The villages lose many of their brightest sons and daughters to cities.","zh":"村莊失去許多最優秀的年輕人到城市。"},{"en":"The brightest sons and daughters means the most talented or able young people from a community.","zh":"the brightest sons and daughters 指一個社區中最有才能或能力的年輕人。"},{"en":"A town may lose its brightest sons and daughters when top students all leave for university abroad.","zh":"如果頂尖學生都到海外讀大學，小鎮可能失去最優秀的年輕人。"},{"en":"If the most able young people leave, the home community may worry about its future leadership.","zh":"如果最有能力的年輕人離開，原社區可能擔心未來領導力。"},{"en":"This phrase is emotional and treats young talent as belonging to a place.","zh":"這個片語帶情感色彩，把年輕人才視為屬於某地方。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":6},{"front":"border towns","meaning":"邊境城鎮","examples":[{"en":"Some young Mexicans leave their villages for jobs in border towns.","zh":"一些年輕墨西哥人離開村莊，到邊境城鎮工作。"},{"en":"Border towns are towns located near the boundary between two countries.","zh":"border towns 是位於兩國邊界附近的城鎮。"},{"en":"A border town may have factories, trade routes, and many migrant workers.","zh":"邊境城鎮可能有工廠、貿易路線和許多移民工人。"},{"en":"If jobs are available in border towns, young people from villages may move there.","zh":"如果邊境城鎮有工作，村莊年輕人可能搬到那裡。"},{"en":"This phrase connects geography with work opportunities.","zh":"這個片語把地理位置與工作機會連接起來。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":6},{"front":"tend to be","meaning":"往往是","examples":[{"en":"Those who leave their home villages tend to be better educated.","zh":"離開家鄉村莊的人往往受教育程度較高。"},{"en":"Tend to be means are usually or often.","zh":"tend to be 指通常是或往往是。"},{"en":"Students who read every day tend to be more confident writers.","zh":"每天閱讀的學生往往是較有信心的寫作者。"},{"en":"If migrants tend to be better educated, the places they leave may lose skilled people.","zh":"如果移民往往受教育程度較高，他們離開的地方可能失去有技能的人。"},{"en":"This phrase describes a general pattern, not an absolute rule.","zh":"這個片語描述一般模式，而不是絕對規則。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":6},{"front":"those who stay","meaning":"留下來的人","examples":[{"en":"Those who leave are often better educated than those who stay.","zh":"離開的人通常比留下來的人受教育程度更高。"},{"en":"Those who stay are the people who remain in their original place.","zh":"those who stay 指留在原本地方的人。"},{"en":"In a small town, those who stay may care for family farms or local shops.","zh":"在小鎮中，留下來的人可能照顧家庭農場或本地商店。"},{"en":"If those who leave are highly educated, those who stay may still benefit from their example.","zh":"如果離開者受教育程度高，留下來的人仍可能從他們的榜樣中受益。"},{"en":"This phrase contrasts stayers with leavers.","zh":"這個片語把留下者與離開者作對比。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":6},{"front":"despite this","meaning":"儘管如此","examples":[{"en":"Despite this, the leavers may still improve education in the village.","zh":"儘管如此，離開者仍可能改善村莊教育。"},{"en":"Despite this means although the previous point is true.","zh":"despite this 指雖然前一點是真的。"},{"en":"The exam was difficult; despite this, many students passed.","zh":"考試很難；儘管如此，許多學生合格了。"},{"en":"Even if educated people leave, they may still inspire others at home.","zh":"即使受教育人士離開，他們仍可能激勵家鄉其他人。"},{"en":"This phrase introduces a contrast with what we might expect.","zh":"這個片語引入與預期不同的對比。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":6},{"front":"the example someone sets","meaning":"某人樹立的榜樣","examples":[{"en":"The example the leavers set raises the average level of schooling.","zh":"離開者樹立的榜樣提高了平均受教育程度。"},{"en":"The example someone sets is the behaviour that others may copy or learn from.","zh":"the example someone sets 指某人的行為可供他人模仿或學習。"},{"en":"A hardworking older student can set an example for younger classmates.","zh":"勤奮的高年級學生可以為低年級同學樹立榜樣。"},{"en":"If migrants show that education opens doors, others may stay in school longer.","zh":"如果移民顯示教育能打開機會之門，其他人可能留校讀書更久。"},{"en":"This phrase shows influence through visible behaviour.","zh":"這個片語顯示透過可見行為產生影響。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":6},{"front":"job leads","meaning":"就業線索；工作機會資訊","examples":[{"en":"The leavers provide job leads for those left behind.","zh":"離開者為留下來的人提供就業線索。"},{"en":"Job leads are information or contacts that may help someone find work.","zh":"job leads 是可能幫助某人找工作的資訊或人脈。"},{"en":"A former classmate may send job leads when she hears a company is hiring.","zh":"當舊同學聽到公司招聘時，可能傳來工作機會資訊。"},{"en":"If migrants share job leads, people at home may access opportunities they would not know about.","zh":"如果移民分享就業線索，家鄉的人可能接觸到本來不知道的機會。"},{"en":"This phrase refers to useful employment information, not guaranteed jobs.","zh":"這個片語指有用的就業資訊，而不是保證有工作。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":6},{"front":"raise the average level of schooling","meaning":"提高平均受教育程度","examples":[{"en":"The leavers raise the average level of schooling of those left behind.","zh":"離開者提高了留下來的人平均受教育程度。"},{"en":"To raise the average level of schooling means to increase how many years people stay in education on average.","zh":"raise the average level of schooling 指提高人們平均接受教育的年數。"},{"en":"A scholarship programme can raise the average level of schooling in a poor district.","zh":"獎學金計劃可以提高貧困地區的平均受教育程度。"},{"en":"If children see education leading to jobs, they may stay in school longer.","zh":"如果孩子看到教育帶來工作，他們可能留校更久。"},{"en":"This phrase describes improvement in a community’s education level.","zh":"這個片語描述社區教育水平的提升。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":6},{"front":"those left behind","meaning":"留下來的人","examples":[{"en":"Those left behind may stay in school for longer.","zh":"留下來的人可能留校讀書更久。"},{"en":"Those left behind are people who remain after others have moved away.","zh":"those left behind 指其他人離開後仍留下的人。"},{"en":"When older siblings migrate, those left behind may receive advice and money from them.","zh":"當兄姊移民，留下來的人可能收到他們的建議和金錢。"},{"en":"If leavers succeed, those left behind may gain motivation rather than only suffer loss.","zh":"如果離開者成功，留下來的人可能得到動力，而不只是承受損失。"},{"en":"This phrase focuses on the people who stay in the original community.","zh":"這個片語聚焦於留在原社區的人。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":6},{"front":"aspire to","meaning":"渴望達到；嚮往","examples":[{"en":"Young Mexicans can aspire to a world beyond the village.","zh":"年輕墨西哥人可以嚮往村莊以外的世界。"},{"en":"To aspire to something means to strongly hope to achieve or reach it.","zh":"aspire to something 指強烈希望達到或獲得某事。"},{"en":"A student may aspire to become a doctor after meeting a kind surgeon.","zh":"學生見到仁慈的外科醫生後，可能渴望成為醫生。"},{"en":"If young people see migrants succeed, they may aspire to education and wider opportunities.","zh":"如果年輕人看見移民成功，可能嚮往教育和更廣闊機會。"},{"en":"This phrase describes ambition toward a higher or broader goal.","zh":"這個片語描述朝向更高或更廣目標的抱負。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":7},{"front":"a world beyond the village","meaning":"村莊以外的世界","examples":[{"en":"Education helps young people imagine a world beyond the village.","zh":"教育幫助年輕人想像村莊以外的世界。"},{"en":"A world beyond the village means opportunities, places, and ways of life outside the local community.","zh":"a world beyond the village 指本地社區以外的機會、地方和生活方式。"},{"en":"Internet access can show rural students a world beyond the village.","zh":"互聯網可以向鄉村學生展示村莊以外的世界。"},{"en":"If young people imagine wider possibilities, they may work harder at school.","zh":"如果年輕人想像到更廣闊可能，他們可能在學校更努力。"},{"en":"This phrase contrasts a local life with broader horizons.","zh":"這個片語把本地生活與更廣闊視野作對比。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":7},{"front":"an added reason to","meaning":"額外理由去……","examples":[{"en":"Migration gives young people an added reason to stay in school.","zh":"移民給年輕人一個額外理由繼續留校讀書。"},{"en":"An added reason to do something is an extra motivation for doing it.","zh":"an added reason to do something 是做某事的額外動機。"},{"en":"A school prize can give students an added reason to read more books.","zh":"學校獎品可以給學生一個額外理由多讀書。"},{"en":"If education may lead to migration, students have another reason to continue studying.","zh":"如果教育可能帶來移民機會，學生便有另一個理由繼續讀書。"},{"en":"This phrase suggests one more reason in addition to existing reasons.","zh":"這個片語暗示在已有理由之外再多一個理由。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":7},{"front":"stay in school","meaning":"繼續留校讀書","examples":[{"en":"Young Mexicans have an added reason to stay in school beyond a ninth year.","zh":"年輕墨西哥人有額外理由在第九年級後繼續留校讀書。"},{"en":"To stay in school means to continue formal education instead of leaving early.","zh":"stay in school 指繼續接受正規教育，而不是提早離校。"},{"en":"A teenager may stay in school because a diploma improves job choices.","zh":"青少年可能因文憑改善工作選擇而繼續留校讀書。"},{"en":"If young people stay in school longer, the community may become better educated.","zh":"如果年輕人留校讀書更久，社區可能變得受教育程度更高。"},{"en":"This phrase focuses on remaining in education.","zh":"這個片語聚焦於繼續接受教育。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":7},{"front":"beyond a ninth year","meaning":"超過第九年級","examples":[{"en":"Some students stay in school beyond a ninth year.","zh":"一些學生留校讀書超過第九年級。"},{"en":"Beyond a ninth year means after completing nine years of schooling.","zh":"beyond a ninth year 指完成九年教育之後。"},{"en":"A student who studies beyond a ninth year may gain more skills and qualifications.","zh":"超過第九年級繼續讀書的學生可能獲得更多技能和資格。"},{"en":"If migration opportunities require education, more students may continue beyond basic schooling.","zh":"如果移民機會需要教育，更多學生可能超過基礎教育後繼續學習。"},{"en":"This phrase marks education past a specific school year.","zh":"這個片語標示超過某一特定學年。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":7},{"front":"a better-educated populace","meaning":"受教育程度較高的民眾","examples":[{"en":"The brain drain may leave a country with a better-educated populace.","zh":"人才外流可能令一個國家留下受教育程度較高的民眾。"},{"en":"A better-educated populace is a population with higher levels of schooling or training.","zh":"better-educated populace 是教育或培訓水平較高的人口。"},{"en":"A town with more graduates has a better-educated populace than before.","zh":"擁有更多畢業生的小鎮，民眾受教育程度比以前更高。"},{"en":"If migration encourages many people to study, the remaining population may become more educated.","zh":"如果移民鼓勵許多人讀書，留下的人口可能變得更有教育水平。"},{"en":"This phrase describes the education level of a whole community.","zh":"這個片語描述整個社區的教育水平。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":7},{"front":"necessarily a good thing","meaning":"必然是好事","examples":[{"en":"A better-educated population is not necessarily a good thing in every case.","zh":"受教育程度較高的人口不一定在每種情況下都是好事。"},{"en":"Not necessarily a good thing means it may be good in some ways but not always or not completely.","zh":"not necessarily a good thing 指某事可能在某些方面好，但不一定總是或完全是好事。"},{"en":"A high salary is not necessarily a good thing if the job destroys someone’s health.","zh":"如果工作摧毀健康，高薪不一定是好事。"},{"en":"If people study only to leave and later regret it, more education may have mixed results.","zh":"如果人們只為離鄉而讀書，之後又後悔，更多教育可能有混合結果。"},{"en":"This phrase warns against assuming a result is always positive.","zh":"這個片語提醒我們不要假設某結果必然正面。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":7},{"front":"gamble on a diploma","meaning":"把文憑當作賭注","examples":[{"en":"Some people gamble on a diploma as a ticket overseas.","zh":"有些人把文憑當作出國門票的賭注。"},{"en":"To gamble on a diploma means to take the risk of investing in education in the hope it will bring a reward.","zh":"gamble on a diploma 指冒險投資教育，希望它帶來回報。"},{"en":"A student may gamble on an expensive course if she believes it will lead to a better job.","zh":"如果學生相信昂貴課程會帶來更好工作，她可能把該課程當作賭注。"},{"en":"If the hoped-for visa never comes, the person may feel the educational gamble failed.","zh":"如果期望中的簽證從未到來，那人可能覺得教育賭注失敗。"},{"en":"This phrase treats education as a risky bet.","zh":"這個片語把教育視為有風險的賭注。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":7},{"front":"a ticket overseas","meaning":"出國的門票","examples":[{"en":"Some students see a diploma as a ticket overseas.","zh":"一些學生把文憑視為出國的門票。"},{"en":"A ticket overseas means something that gives a person a chance to move or work abroad.","zh":"a ticket overseas 指給人機會到海外生活或工作的東西。"},{"en":"A nursing qualification may feel like a ticket overseas if foreign hospitals are hiring.","zh":"如果外國醫院招聘，護理資格可能感覺像出國的門票。"},{"en":"If young people see education as a route abroad, they may study for migration as much as for learning.","zh":"如果年輕人把教育視為出國途徑，他們讀書可能既為移民，也為學習。"},{"en":"This phrase is metaphorical; it does not mean a real travel ticket.","zh":"這個片語是比喻，不是真的旅行票。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":7},{"front":"regret their decision","meaning":"後悔自己的決定","examples":[{"en":"Some people who study in order to emigrate may regret their decision.","zh":"一些為了移民而讀書的人可能後悔自己的決定。"},{"en":"To regret their decision means to feel sorry later about the choice they made.","zh":"regret their decision 指日後對自己作出的選擇感到後悔。"},{"en":"A student may regret choosing a course only because friends chose it.","zh":"學生可能後悔只因朋友選某課程而跟着選。"},{"en":"If education does not lead to migration or a good job, some people may feel disappointed.","zh":"如果教育沒有帶來移民或好工作，一些人可能感到失望。"},{"en":"This phrase describes later dissatisfaction with a past choice.","zh":"這個片語描述對過去選擇的日後不滿。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":7},{"front":"tend to demand too little education","meaning":"往往對教育需求過低","examples":[{"en":"Mr Stark assumes that people in poor countries tend to demand too little education.","zh":"Stark 先生假設貧窮國家的人往往對教育需求過低。"},{"en":"To tend to demand too little education means usually to choose less schooling than is socially useful.","zh":"tend to demand too little education 指通常選擇少於對社會有益的教育年數。"},{"en":"A family may demand too little education if school fees seem costly and future benefits feel uncertain.","zh":"如果學費看似昂貴，而未來好處不確定，家庭可能對教育需求過低。"},{"en":"If people do not receive all the benefits of education themselves, they may underinvest in it.","zh":"如果人們不能自己得到教育的全部好處，便可能對教育投資不足。"},{"en":"This phrase describes a market failure in education decisions.","zh":"這個片語描述教育決策中的市場失靈。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":7},{"front":"productivity depends on","meaning":"生產力取決於……","examples":[{"en":"A person’s productivity depends on the skills of those around him.","zh":"一個人的生產力取決於身邊人的技能。"},{"en":"Productivity depends on something means the amount or quality of work produced is affected by that factor.","zh":"productivity depends on something 指工作產出數量或質素受該因素影響。"},{"en":"A student’s productivity may depend on sleep, quiet space, and clear goals.","zh":"學生的生產力可能取決於睡眠、安靜空間和清晰目標。"},{"en":"If colleagues are skilled, one worker may solve problems faster and produce more.","zh":"如果同事有技能，一名工人可能更快解決問題並產出更多。"},{"en":"This phrase explains what influences output.","zh":"這個片語解釋甚麼影響產出。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":8},{"front":"the skills of those around him","meaning":"身邊人的技能","examples":[{"en":"A person benefits from the skills of those around him.","zh":"一個人會受益於身邊人的技能。"},{"en":"The skills of those around him means the abilities and knowledge of nearby colleagues or community members.","zh":"the skills of those around him 指附近同事或社群成員的能力和知識。"},{"en":"A new nurse learns faster when the skills of those around her are strong.","zh":"當身邊人的技能很強，新護士會學得更快。"},{"en":"If a workplace loses skilled people, everyone’s productivity may fall.","zh":"如果工作場所失去有技能的人，所有人的生產力可能下降。"},{"en":"This phrase shows that individual success can depend on other people’s abilities.","zh":"這個片語顯示個人成功可以取決於其他人的能力。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":8},{"front":"as well as","meaning":"以及；也","examples":[{"en":"A person’s productivity depends on others’ skills as well as his own.","zh":"一個人的生產力取決於他人的技能以及自己的技能。"},{"en":"As well as means in addition to.","zh":"as well as 指除了……之外，也包括……。"},{"en":"A good essay needs clear examples as well as correct grammar.","zh":"好文章需要清晰例子，也需要正確文法。"},{"en":"If productivity depends on teamwork as well as individual ability, education benefits more than one person.","zh":"如果生產力取決於團隊合作以及個人能力，教育便惠及不只一個人。"},{"en":"This phrase adds another important factor.","zh":"這個片語加入另一個重要因素。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":8},{"front":"spillovers","meaning":"外溢效應","examples":[{"en":"Education creates spillovers that benefit the wider economy.","zh":"教育創造惠及更廣泛經濟的外溢效應。"},{"en":"Spillovers are effects that spread beyond the person or place where they begin.","zh":"spillovers 是從原本人或地方擴散出去的影響。"},{"en":"A clean park creates spillovers because nearby shops may get more customers.","zh":"乾淨公園會產生外溢效應，因為附近商店可能有更多顧客。"},{"en":"If one worker becomes more skilled, colleagues may also learn from him.","zh":"如果一名工人技能提高，同事也可能向他學習。"},{"en":"This word describes indirect benefits or costs reaching others.","zh":"這個詞描述間接好處或成本傳到他人身上。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":8},{"front":"the economy as a whole","meaning":"整體經濟","examples":[{"en":"An individual’s education may be worth more to the economy as a whole.","zh":"個人的教育對整體經濟可能比對個人本身更有價值。"},{"en":"The economy as a whole means the entire economic system, not just one person or company.","zh":"the economy as a whole 指整個經濟系統，而不是單一個人或公司。"},{"en":"Good public transport helps the economy as a whole by making work and shopping easier.","zh":"良好公共交通透過令工作和購物更方便來幫助整體經濟。"},{"en":"If education improves many workers’ productivity, the whole economy gains.","zh":"如果教育提高許多工人的生產力，整體經濟便受益。"},{"en":"This phrase looks at broad social value rather than private benefit only.","zh":"這個片語着眼於廣泛社會價值，而不只是私人好處。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":8},{"front":"underinvest in","meaning":"對……投資不足","examples":[{"en":"People may underinvest in education because they do not receive all its benefits.","zh":"人們可能對教育投資不足，因為他們不能得到其全部好處。"},{"en":"To underinvest in something means to spend too little money, time, or effort on it.","zh":"underinvest in something 指在某事上投入太少金錢、時間或努力。"},{"en":"A school may underinvest in libraries if it focuses only on exam drills.","zh":"如果學校只重視考試操練，可能對圖書館投資不足。"},{"en":"If families cannot see long-term benefits, they may spend too little on education.","zh":"如果家庭看不到長期好處，可能在教育上花得太少。"},{"en":"This phrase suggests investment is below the useful level.","zh":"這個片語暗示投資低於有用水平。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":8},{"front":"as a result","meaning":"因此；結果","examples":[{"en":"He may underinvest in education as a result.","zh":"因此，他可能對教育投資不足。"},{"en":"As a result means because of what happened before.","zh":"as a result 指因為之前發生的事。"},{"en":"The bus broke down; as a result, many students arrived late.","zh":"巴士壞了；結果，許多學生遲到。"},{"en":"If people cannot capture all the benefits of education, they may invest too little as a result.","zh":"如果人們不能取得教育的全部好處，結果可能投資太少。"},{"en":"This phrase connects cause and effect.","zh":"這個片語連接原因和結果。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":8},{"front":"limited emigration","meaning":"有限度移民","examples":[{"en":"Limited emigration may help fix this market failure.","zh":"有限度移民可能幫助糾正這種市場失靈。"},{"en":"Limited emigration means some people leave the country, but not so many that the loss becomes overwhelming.","zh":"limited emigration 指有些人離開國家，但數量不至於造成壓倒性損失。"},{"en":"A small number of graduates working abroad may send skills, money, and contacts home.","zh":"少量畢業生到海外工作，可能把技能、金錢和人脈帶回家鄉。"},{"en":"If emigration is limited, it may encourage education without draining too many professionals.","zh":"如果移民有限，它可能鼓勵教育，同時不流失太多專業人士。"},{"en":"This phrase suggests controlled or moderate outward migration.","zh":"這個片語暗示受控制或適度的向外移民。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":8},{"front":"fix this market failure","meaning":"糾正這種市場失靈","examples":[{"en":"Mr Stark sees limited emigration as one way to fix this market failure.","zh":"Stark 先生把有限度移民視為糾正這種市場失靈的一種方法。"},{"en":"To fix this market failure means to correct a situation where private choices produce a bad social result.","zh":"fix this market failure 指糾正私人選擇造成不良社會結果的情況。"},{"en":"A government may fix a market failure by subsidising vaccines that protect the whole community.","zh":"政府可能透過補貼保護整個社區的疫苗來糾正市場失靈。"},{"en":"If people underinvest in education, migration incentives might make more people study.","zh":"如果人們對教育投資不足，移民誘因可能令更多人讀書。"},{"en":"This phrase describes solving an economic problem caused by misaligned incentives.","zh":"這個片語描述解決由誘因錯配造成的經濟問題。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":8},{"front":"software engineers","meaning":"軟件工程師","examples":[{"en":"India’s software engineers may illustrate this principle.","zh":"印度的軟件工程師可能說明這個原則。"},{"en":"Software engineers are professionals who design, build, test, and maintain computer software.","zh":"software engineers 是設計、建立、測試和維護電腦軟件的專業人士。"},{"en":"A software engineer may create an app that helps students organise homework.","zh":"軟件工程師可能創建幫助學生整理功課的應用程式。"},{"en":"If many students learn coding, a country may develop a stronger technology industry.","zh":"如果許多學生學習編程，一個國家可能發展出更強的科技產業。"},{"en":"This phrase refers to skilled workers in the software field.","zh":"這個片語指軟件領域的技術工人。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":8},{"front":"an example of this principle at work","meaning":"這個原則發揮作用的例子","examples":[{"en":"India’s software engineers are an example of this principle at work.","zh":"印度的軟件工程師是這個原則發揮作用的例子。"},{"en":"An example of this principle at work is a real case showing that an idea operates in practice.","zh":"an example of this principle at work 是顯示某想法在現實中運作的真實個案。"},{"en":"A student improving through daily reading is an example of practice paying off at work.","zh":"學生透過每日閱讀而進步，就是練習帶來成效的例子。"},{"en":"If migration dreams lead students to learn coding, the education incentive principle is visible.","zh":"如果移民夢想令學生學習編程，教育誘因原則便清楚可見。"},{"en":"This phrase connects theory with real-life evidence.","zh":"這個片語把理論與現實證據連接起來。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":8},{"front":"computer coding","meaning":"電腦編程","examples":[{"en":"Indian students had little reason to learn computer coding before the software industry grew.","zh":"在軟件產業成長前，印度學生幾乎沒有理由學習電腦編程。"},{"en":"Computer coding means writing instructions that computers can follow.","zh":"computer coding 指寫出電腦能遵循的指令。"},{"en":"A teenager may learn computer coding to build a simple game or website.","zh":"青少年可能學習電腦編程，以製作簡單遊戲或網站。"},{"en":"If coding skills become valuable in the job market, more students may choose to learn them.","zh":"如果編程技能在就業市場變得有價值，更多學生可能選擇學習它。"},{"en":"This phrase refers to practical programming skills.","zh":"這個片語指實用程式編寫技能。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":9},{"front":"take root","meaning":"扎根；穩固發展","examples":[{"en":"A software industry could not take root without computer engineers.","zh":"沒有電腦工程師，軟件產業不可能扎根。"},{"en":"To take root means to become established and start growing steadily.","zh":"take root 指變得穩定並開始持續發展。"},{"en":"A reading habit may take root if a child finds books that feel exciting.","zh":"如果孩子找到令人興奮的書，閱讀習慣可能扎根。"},{"en":"If an industry lacks skilled workers, it may fail to take root.","zh":"如果一個產業缺乏技術工人，它可能無法穩固發展。"},{"en":"This phrase compares an idea or industry to a plant beginning to grow.","zh":"這個片語把想法或產業比作開始生長的植物。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":9},{"front":"man an industry","meaning":"為某行業配備人手","examples":[{"en":"The industry needed computer engineers to man it.","zh":"該產業需要電腦工程師為其配備人手。"},{"en":"To man an industry means to provide the workers needed to operate it.","zh":"man an industry 指提供運作該行業所需的人手。"},{"en":"A hospital needs enough nurses to man its emergency department.","zh":"醫院需要足夠護士為急症室配備人手。"},{"en":"If trained engineers are unavailable, a new industry cannot function properly.","zh":"如果缺乏受訓工程師，新產業便不能正常運作。"},{"en":"This phrase focuses on staffing an activity or organisation.","zh":"這個片語聚焦於為活動或組織提供人員。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":9},{"front":"Silicon Valley","meaning":"矽谷","examples":[{"en":"The dream of a job in Silicon Valley attracted Indian students to coding.","zh":"在矽谷工作的夢想吸引印度學生學習編程。"},{"en":"Silicon Valley is a famous technology region in California associated with software and start-ups.","zh":"Silicon Valley 是加州著名科技區，與軟件和初創公司相關。"},{"en":"A young programmer may dream of working in Silicon Valley because major tech companies are based there.","zh":"年輕程式員可能夢想在矽谷工作，因為大型科技公司設於那裡。"},{"en":"If Silicon Valley jobs seem possible, students may invest more in computer skills.","zh":"如果矽谷工作看似可能，學生可能更投資於電腦技能。"},{"en":"This phrase often symbolises global technology opportunity.","zh":"這個片語常象徵全球科技機會。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":9},{"front":"lure someone into","meaning":"吸引某人進入……","examples":[{"en":"The possibility of overseas work lured many students into coding.","zh":"海外工作的可能性吸引許多學生進入編程領域。"},{"en":"To lure someone into something means to attract them into doing or joining it.","zh":"lure someone into something 指吸引某人去做某事或加入某領域。"},{"en":"A high salary may lure graduates into finance even if they first studied science.","zh":"高薪可能吸引畢業生進入金融業，即使他們原本讀科學。"},{"en":"If global jobs look attractive, they can lure young people into technical training.","zh":"如果全球工作看起來吸引，它們可以吸引年輕人進入技術培訓。"},{"en":"This phrase suggests a strong attraction, sometimes with risk or temptation.","zh":"這個片語暗示強烈吸引，有時帶風險或誘惑。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":9},{"front":"bright young things","meaning":"聰明有為的年輕人","examples":[{"en":"The dream of Silicon Valley lured many of India’s bright young things into coding.","zh":"矽谷夢想吸引許多印度聰明有為的年輕人進入編程。"},{"en":"Bright young things are clever, talented, and promising young people.","zh":"bright young things 指聰明、有才華、有前途的年輕人。"},{"en":"A city may create scholarships to keep its bright young things from leaving.","zh":"城市可能設立獎學金，以留住聰明有為的年輕人。"},{"en":"If bright young people see opportunity in technology, they may train for that industry.","zh":"如果聰明年輕人看到科技機會，他們可能為該行業接受培訓。"},{"en":"This phrase is informal and slightly playful.","zh":"這個片語較口語，也略帶俏皮意味。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":9},{"front":"hatch an indigenous software industry","meaning":"孵化出本土軟件產業","examples":[{"en":"Coding skills helped hatch an indigenous software industry in India.","zh":"編程技能幫助印度孵化出本土軟件產業。"},{"en":"To hatch an indigenous software industry means to help create a local software industry from the beginning.","zh":"hatch an indigenous software industry 指幫助從零創造本地軟件產業。"},{"en":"A town may hatch a local design industry if many young people learn digital tools.","zh":"如果許多年輕人學習數碼工具，小鎮可能孵化出本地設計產業。"},{"en":"If enough skilled coders remain, overseas dreams can indirectly create a home-grown industry.","zh":"如果足夠技術程式員留下，海外夢想可以間接創造本土產業。"},{"en":"This phrase compares an industry’s birth to an egg hatching.","zh":"這個片語把產業誕生比作蛋孵化。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":9},{"front":"where none existed before","meaning":"在原本不存在的地方","examples":[{"en":"India developed a software industry where none existed before.","zh":"印度在原本不存在軟件產業的地方發展出軟件產業。"},{"en":"Where none existed before means in a place or situation where that thing had not previously existed.","zh":"where none existed before 指在某物以前不存在的地方或情況中。"},{"en":"A school garden can create a quiet study area where none existed before.","zh":"學校花園可以在原本沒有安靜學習區的地方創造一個。"},{"en":"If training creates an industry where none existed before, education has transformed the local economy.","zh":"如果培訓在原本不存在的地方創造產業，教育便改變了本地經濟。"},{"en":"This phrase stresses creation from absence.","zh":"這個片語強調從無到有的創造。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":9},{"front":"valley dwellers","meaning":"矽谷工作者","examples":[{"en":"India’s valley dwellers represent one part of a larger diaspora.","zh":"印度的矽谷工作者代表更大海外僑民群體中的一部分。"},{"en":"Valley dwellers here refers to Indians working in Silicon Valley.","zh":"valley dwellers 在此指在矽谷工作的印度人。"},{"en":"A graduate who moves to Silicon Valley for a technology job becomes part of that overseas professional community.","zh":"搬到矽谷從事科技工作的畢業生成為該海外專業社群的一部分。"},{"en":"If valley dwellers send knowledge and contacts home, they may help their country’s technology sector.","zh":"如果矽谷工作者把知識和人脈帶回家鄉，他們可能幫助本國科技業。"},{"en":"This phrase is a shorthand for skilled migrants in Silicon Valley.","zh":"這個片語是指矽谷技術移民的簡略說法。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":9},{"front":"represent one contingent in","meaning":"代表……中的一個群體","examples":[{"en":"India’s valley dwellers represent one contingent in a larger diaspora.","zh":"印度的矽谷工作者代表更大海外僑民群體中的一個群體。"},{"en":"To represent one contingent in a group means to be one subgroup within a bigger community.","zh":"represent one contingent in a group 指成為較大社群中的一個小群體。"},{"en":"Nurses may represent one contingent in a country’s overseas workforce.","zh":"護士可能代表一個國家海外勞動力中的一個群體。"},{"en":"If software workers are only one contingent, the diaspora also includes doctors, teachers, and businesspeople.","zh":"如果軟件工人只是其中一個群體，海外僑民還包括醫生、教師和商人。"},{"en":"This phrase helps describe parts within a larger whole.","zh":"這個片語幫助描述較大整體中的部分。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":9},{"front":"diaspora","meaning":"diaspora；海外僑民群體","examples":[{"en":"The Indian diaspora includes many highly educated emigrants.","zh":"印度海外僑民群體包括許多受過高等教育的移民。"},{"en":"A diaspora is a group of people from one country or culture living in many other places.","zh":"diaspora 指來自同一國家或文化、分散居住在許多其他地方的人群。"},{"en":"A city may have a large Filipino diaspora with churches, shops, and community groups.","zh":"城市可能有大型菲律賓海外僑民群體，並有教會、商店和社區組織。"},{"en":"Diaspora members can send money, knowledge, and business contacts back home.","zh":"海外僑民成員可以把金錢、知識和商業人脈帶回家鄉。"},{"en":"This word focuses on overseas communities linked to a homeland.","zh":"這個詞聚焦於與故鄉相連的海外社群。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":9},{"front":"according to","meaning":"根據……","examples":[{"en":"According to the World Bank, many educated Indians lived in OECD countries.","zh":"根據世界銀行，許多受教育的印度人居住在經合組織國家。"},{"en":"According to means based on what a person, report, or organisation says.","zh":"according to 指根據某人、報告或組織所說。"},{"en":"According to the school notice, the exam will start at nine o’clock.","zh":"根據學校通告，考試將於九時開始。"},{"en":"If a claim is according to a report, readers should know which source supports it.","zh":"如果某主張根據一份報告，讀者應知道是哪個來源支持它。"},{"en":"This phrase introduces evidence or authority.","zh":"這個片語引入證據或權威來源。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":10},{"front":"the most exhaustive study of","meaning":"對……最詳盡的研究","examples":[{"en":"The most exhaustive study of the brain drain was released by the World Bank.","zh":"對人才外流最詳盡的研究由世界銀行發布。"},{"en":"The most exhaustive study of something is the most complete and detailed research on it.","zh":"the most exhaustive study of something 是關於某事最完整、最詳細的研究。"},{"en":"A hospital may use the most exhaustive study of a disease to update treatment rules.","zh":"醫院可能使用對某疾病最詳盡的研究來更新治療規則。"},{"en":"If a study is exhaustive, it covers many countries, cases, or data sources.","zh":"如果研究詳盡，它會涵蓋許多國家、個案或數據來源。"},{"en":"This phrase emphasises depth and completeness.","zh":"這個片語強調深度和完整性。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":10},{"front":"released by","meaning":"由……發布","examples":[{"en":"The study was released by the World Bank.","zh":"該研究由世界銀行發布。"},{"en":"Released by means officially published or made available by an organisation or person.","zh":"released by 指由某組織或個人正式發布或公開。"},{"en":"The exam timetable was released by the school office on Monday.","zh":"考試時間表於星期一由校務處發布。"},{"en":"If a report is released by a major institution, it may influence policy debates.","zh":"如果報告由大型機構發布，它可能影響政策辯論。"},{"en":"This phrase identifies who made information public.","zh":"這個片語指出誰把資訊公開。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":10},{"front":"Indian-born people","meaning":"印度出生的人","examples":[{"en":"Many Indian-born people educated past secondary school lived abroad.","zh":"許多受過中學以上教育的印度出生人士居住海外。"},{"en":"Indian-born people are people who were born in India, regardless of where they live now.","zh":"Indian-born people 是在印度出生的人，不論他們現在住在哪裡。"},{"en":"An Indian-born engineer may work in Canada while still keeping family ties to India.","zh":"印度出生的工程師可能在加拿大工作，同時仍與印度家庭保持聯繫。"},{"en":"If many Indian-born graduates live abroad, the diaspora becomes an important economic link.","zh":"如果許多印度出生的畢業生居住海外，海外僑民群體便成為重要經濟連繫。"},{"en":"This phrase focuses on place of birth, not current nationality alone.","zh":"這個片語聚焦於出生地，而不只是目前國籍。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":10},{"front":"educated past secondary school","meaning":"受過中學以上教育","examples":[{"en":"The study counted Indian-born people educated past secondary school.","zh":"該研究統計受過中學以上教育的印度出生人士。"},{"en":"Educated past secondary school means having education beyond high school level.","zh":"educated past secondary school 指接受過高中以上程度的教育。"},{"en":"A student educated past secondary school may have a diploma, college degree, or professional training.","zh":"受過中學以上教育的學生可能有文憑、大學學位或專業培訓。"},{"en":"If migrants are educated past secondary school, they may qualify for skilled jobs abroad.","zh":"如果移民受過中學以上教育，他們可能符合海外技術工作的資格。"},{"en":"This phrase describes higher-than-basic education.","zh":"這個片語描述高於基本水平的教育。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":10},{"front":"relatively rich countries","meaning":"相對富裕的國家","examples":[{"en":"Many educated Indians lived in relatively rich countries of the OECD.","zh":"許多受教育印度人居住在經合組織相對富裕的國家。"},{"en":"Relatively rich countries are countries that are wealthy compared with many others.","zh":"relatively rich countries 是相比許多其他國家較富裕的國家。"},{"en":"Workers may move to relatively rich countries because wages and services are better.","zh":"工人可能因工資和服務較好而移居相對富裕的國家。"},{"en":"If educated migrants concentrate in rich countries, poorer countries may lose skilled labour.","zh":"如果受教育移民集中在富國，較貧窮國家可能失去技術勞動力。"},{"en":"This phrase compares wealth levels rather than saying countries are equally rich.","zh":"這個片語比較財富水平，而不是說所有國家同樣富裕。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":10},{"front":"the OECD","meaning":"經合組織","examples":[{"en":"The OECD includes 30 relatively rich countries in the passage.","zh":"在文章中，經合組織包括30個相對富裕的國家。"},{"en":"The OECD is an organisation of mostly wealthy countries that cooperate on economic and social policy.","zh":"OECD 是主要由富裕國家組成、在經濟和社會政策上合作的組織。"},{"en":"Researchers may use OECD countries as a group when comparing migration patterns.","zh":"研究人員比較移民模式時，可能把經合組織國家作為一組。"},{"en":"If many skilled migrants live in OECD countries, richer economies gain human capital.","zh":"如果許多技術移民居住在經合組織國家，較富裕經濟體會得到人力資本。"},{"en":"This phrase names a group of developed economies in the passage.","zh":"這個片語指出文章中的一組發達經濟體。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":10},{"front":"acquire one’s education","meaning":"接受教育；取得學歷","examples":[{"en":"Some emigrants acquired their education outside their country of birth.","zh":"一些移民在出生國家以外接受教育。"},{"en":"To acquire one’s education means to receive or obtain schooling, training, or qualifications.","zh":"acquire one’s education 指接受或取得學校教育、培訓或學歷。"},{"en":"A student may acquire her education in a city far from her hometown.","zh":"學生可能在遠離家鄉的城市接受教育。"},{"en":"If migrants study abroad, the home country may not have paid for their training.","zh":"如果移民在海外讀書，原居國可能沒有支付他們的培訓成本。"},{"en":"This phrase focuses on where and how education is obtained.","zh":"這個片語聚焦於教育在哪裡和如何取得。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":10},{"front":"country of birth","meaning":"出生國家","examples":[{"en":"The report notes that some people studied outside their country of birth.","zh":"報告指出，一些人在出生國家以外讀書。"},{"en":"Country of birth means the country where a person was born.","zh":"country of birth 指一個人出生的國家。"},{"en":"A person’s country of birth may be different from the country where they now live.","zh":"一個人的出生國家可能不同於他現在居住的國家。"},{"en":"If someone studies outside their country of birth, migration statistics can be harder to interpret.","zh":"如果有人在出生國家以外讀書，移民統計可能更難解讀。"},{"en":"This phrase is about birthplace, not necessarily citizenship.","zh":"這個片語關於出生地，而不一定是公民身份。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":10},{"front":"the report notes","meaning":"報告指出","examples":[{"en":"The report notes that an unknown number studied abroad.","zh":"報告指出，有數目不明的人曾在海外讀書。"},{"en":"The report notes means the report mentions or points out a fact.","zh":"the report notes 指報告提及或指出某事實。"},{"en":"The school report notes that attendance improved after breakfast was provided.","zh":"學校報告指出，提供早餐後出席率改善。"},{"en":"If a report notes missing data, readers should be careful about strong conclusions.","zh":"如果報告指出數據缺失，讀者應小心作出強烈結論。"},{"en":"This phrase introduces an observation from a written source.","zh":"這個片語引入書面來源中的觀察。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":10},{"front":"more than just","meaning":"不只是……","examples":[{"en":"The diaspora is more than just something to envy and emulate.","zh":"海外僑民群體不只是值得羨慕和效法的東西。"},{"en":"More than just means not only that thing, but also something more important or useful.","zh":"more than just 指不只是某物，還有更重要或有用的作用。"},{"en":"A library is more than just a place for books; it can be a community centre.","zh":"圖書館不只是放書的地方；它也可以是社區中心。"},{"en":"If emigrants send knowledge and contacts home, they are more than symbols of success.","zh":"如果移民把知識和人脈帶回家鄉，他們就不只是成功象徵。"},{"en":"This phrase expands the meaning beyond a simple label.","zh":"這個片語把意思擴展到簡單標籤以外。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":10},{"front":"envy and emulate","meaning":"羨慕和效法","examples":[{"en":"A successful diaspora can be something to envy and emulate.","zh":"成功的海外僑民群體可以是令人羨慕和效法的對象。"},{"en":"To envy and emulate someone means to admire their success and try to copy it.","zh":"envy and emulate someone 指羨慕某人的成功並嘗試模仿。"},{"en":"Younger students may envy and emulate a senior who wins a scholarship.","zh":"低年級學生可能羨慕並效法獲得獎學金的高年級學生。"},{"en":"If emigrants become rich abroad, people at home may want to follow their path.","zh":"如果移民在海外致富，家鄉的人可能想追隨他們的道路。"},{"en":"This phrase combines admiration with imitation.","zh":"這個片語結合羨慕與模仿。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":11},{"front":"a source of know-how and money","meaning":"技術知識和資金來源","examples":[{"en":"Diaspora members can be a source of know-how and money.","zh":"海外僑民成員可以成為技術知識和資金來源。"},{"en":"A source of know-how and money means a provider of practical knowledge and financial support.","zh":"a source of know-how and money 指提供實用知識和財務支持的人或群體。"},{"en":"Former students working abroad may become a source of advice and donations for their old school.","zh":"在海外工作的舊生可能成為母校的建議和捐款來源。"},{"en":"If emigrants send expertise and investment home, they can help local industries grow.","zh":"如果移民把專業知識和投資帶回家鄉，他們可以幫助本地產業成長。"},{"en":"This phrase describes practical value from overseas communities.","zh":"這個片語描述海外社群的實際價值。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":11},{"front":"valuable entrées into","meaning":"進入……的寶貴門路","examples":[{"en":"Diaspora members can provide valuable entrées into foreign markets.","zh":"海外僑民成員可以提供進入外國市場的寶貴門路。"},{"en":"Valuable entrées into something are useful openings or ways of gaining access to it.","zh":"valuable entrées into something 是進入某領域的有用機會或門路。"},{"en":"A former classmate working in a company may provide a valuable entrée into that industry.","zh":"在公司工作的舊同學可能提供進入該行業的寶貴門路。"},{"en":"If emigrants understand foreign business culture, they can help home firms enter new markets.","zh":"如果移民了解外國商業文化，他們可以幫助家鄉企業進入新市場。"},{"en":"This phrase suggests access through contacts and knowledge.","zh":"這個片語暗示透過人脈和知識取得進入機會。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":11},{"front":"foreign markets","meaning":"外國市場","examples":[{"en":"Educated emigrants can help companies enter foreign markets.","zh":"受教育移民可以幫助公司進入外國市場。"},{"en":"Foreign markets are markets in countries outside a company’s home country.","zh":"foreign markets 是公司本國以外國家的市場。"},{"en":"A small tea brand may enter foreign markets by working with overseas distributors.","zh":"小型茶葉品牌可能透過與海外分銷商合作進入外國市場。"},{"en":"If a diaspora knows local tastes abroad, it can guide firms entering those markets.","zh":"如果海外僑民了解海外本地口味，就能指導企業進入那些市場。"},{"en":"This phrase refers to selling or operating internationally.","zh":"這個片語指國際銷售或經營。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":11},{"front":"supply chains","meaning":"供應鏈","examples":[{"en":"Diaspora members can help create links with supply chains.","zh":"海外僑民成員可以幫助建立與供應鏈的連繫。"},{"en":"Supply chains are networks that move materials, products, and services from producers to customers.","zh":"supply chains 是把材料、產品和服務從生產者送到顧客手中的網絡。"},{"en":"A bakery’s supply chain includes flour suppliers, delivery drivers, and shops.","zh":"麵包店的供應鏈包括麵粉供應商、送貨司機和店舖。"},{"en":"If emigrants know reliable suppliers abroad, they can help home businesses connect to them.","zh":"如果移民認識海外可靠供應商，就可以幫助家鄉企業連接他們。"},{"en":"This phrase describes the practical network behind production and trade.","zh":"這個片語描述生產和貿易背後的實際網絡。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":11},{"front":"relatively happy experience with","meaning":"與……有相對正面的經驗","examples":[{"en":"India has had a relatively happy experience with its educated emigrants.","zh":"印度與其受教育移民有相對正面的經驗。"},{"en":"A relatively happy experience with something means an experience that has been mostly positive compared with others.","zh":"relatively happy experience with something 指相比其他情況，大致較正面的經驗。"},{"en":"A school may have a relatively happy experience with online learning if most students adapt well.","zh":"如果大多數學生適應良好，學校可能對網上學習有相對正面的經驗。"},{"en":"If emigrants send money, knowledge, and contacts back, the home country may benefit.","zh":"如果移民把金錢、知識和人脈帶回家鄉，原居國可能受益。"},{"en":"This phrase suggests positive results, but not perfect success.","zh":"這個片語暗示正面結果，但不是完美成功。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":11},{"front":"educated émigrés","meaning":"受過教育的移民","examples":[{"en":"India’s educated émigrés have helped its economy in some ways.","zh":"印度受過教育的移民在某些方面幫助了其經濟。"},{"en":"Educated émigrés are people with education or qualifications who have left their country to live abroad.","zh":"educated émigrés 是有教育或資格、已離開本國到海外生活的人。"},{"en":"An educated émigré may work overseas but advise start-ups in their home country.","zh":"受過教育的移民可能在海外工作，但向家鄉初創企業提供建議。"},{"en":"If educated émigrés remain connected, they can transfer skills and business opportunities home.","zh":"如果受教育移民保持聯繫，他們可以把技能和商業機會帶回家鄉。"},{"en":"This phrase focuses on skilled emigrants.","zh":"這個片語聚焦於有技能的移民。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":11},{"front":"the exception rather than the rule","meaning":"例外而非常規","examples":[{"en":"India’s experience may be the exception rather than the rule.","zh":"印度的經驗可能是例外而非常規。"},{"en":"The exception rather than the rule means an unusual case, not the normal pattern.","zh":"the exception rather than the rule 指不尋常個案，而不是一般模式。"},{"en":"A student who improves without practice is the exception rather than the rule.","zh":"不練習也進步的學生是例外而非常規。"},{"en":"If India benefits from emigrants while many countries lose talent, India may be unusual.","zh":"如果印度從移民中受益，而許多國家流失人才，印度可能是不尋常個案。"},{"en":"This phrase warns us not to generalise from one case.","zh":"這個片語提醒我們不要從單一個案作廣泛推論。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":11},{"front":"million-strong brain drain","meaning":"百萬規模的人才外流","examples":[{"en":"India’s million-strong brain drain represents a small share of its graduates.","zh":"印度百萬規模的人才外流只佔其畢業生人口的一小部分。"},{"en":"A million-strong brain drain means a loss of educated people numbering around a million.","zh":"million-strong brain drain 指受教育人士流失人數約達百萬。"},{"en":"A city may have a large outward flow of graduates, but the effect depends on its total graduate population.","zh":"一個城市可能有大量畢業生外流，但影響取決於其畢業生總人口。"},{"en":"If a million emigrants are only a small share, the home country may still have many skilled workers.","zh":"如果百萬移民只是一小部分，原居國可能仍有許多技術工人。"},{"en":"This phrase combines large absolute numbers with the idea of talent loss.","zh":"這個片語結合龐大絕對數字與人才流失概念。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":11},{"front":"vast graduate population","meaning":"龐大的大學畢業生人口","examples":[{"en":"India has a vast graduate population.","zh":"印度有龐大的大學畢業生人口。"},{"en":"A vast graduate population is a very large number of people with university-level education.","zh":"vast graduate population 是擁有大學程度教育的人數非常龐大。"},{"en":"A country with many universities may produce a vast graduate population over time.","zh":"擁有許多大學的國家可能隨時間培養龐大的大學畢業生人口。"},{"en":"If the graduate population is huge, even a large number of emigrants may represent a small percentage.","zh":"如果畢業生人口巨大，即使移民人數龐大，也可能只佔小百分比。"},{"en":"This phrase stresses the size of the educated population.","zh":"這個片語強調受教育人口的規模。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":11},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, Ghana loses a much higher share of its educated people.","zh":"相比之下，加納流失其受教育人口的比例高得多。"},{"en":"By contrast means compared with the previous point, the next point is different.","zh":"by contrast 指與前一點相比，下一點有所不同。"},{"en":"One school has many teachers; by contrast, another struggles to fill posts.","zh":"一間學校有很多老師；相比之下，另一間難以填補職位。"},{"en":"If India loses a small share but Ghana loses a large share, the impact differs greatly.","zh":"如果印度流失小比例，而加納流失大比例，影響便大不相同。"},{"en":"This phrase highlights a clear comparison.","zh":"這個片語突出清楚比較。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":11},{"front":"highly educated native sons","meaning":"受過高等教育的本國人才","examples":[{"en":"Many of Ghana’s highly educated native sons live in OECD countries.","zh":"加納許多受過高等教育的本國人才居住在經合組織國家。"},{"en":"Highly educated native sons means men from a country who have received a high level of education.","zh":"highly educated native sons 指來自某國並受過高等教育的男性人才。"},{"en":"A town may be proud of its highly educated native sons and daughters who become doctors or engineers.","zh":"小鎮可能為成為醫生或工程師的受過高等教育本地子弟感到自豪。"},{"en":"If many highly educated people live abroad, the home country may lose important expertise.","zh":"如果許多高學歷人士居住海外，原居國可能失去重要專業知識。"},{"en":"This phrase is emotional and focuses on talented people originally from a place.","zh":"這個片語帶情感色彩，聚焦於原本來自某地的人才。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":12},{"front":"stimulative leeching of talent","meaning":"具刺激作用的人才流失","examples":[{"en":"This is not a stimulative leeching of talent.","zh":"這不是具刺激作用的人才流失。"},{"en":"Stimulative leeching of talent would mean talent loss that somehow encourages more education or achievement.","zh":"stimulative leeching of talent 指雖然人才流失，卻某程度上刺激更多教育或成就。"},{"en":"A school losing top students might still be stimulated if younger students work harder to follow them.","zh":"學校失去頂尖學生後，如果低年級學生更努力追隨他們，仍可能受到刺激。"},{"en":"If too many doctors leave, however, the loss may harm the country more than it motivates anyone.","zh":"然而，如果太多醫生離開，這種流失對國家的傷害可能大於激勵作用。"},{"en":"This phrase contrasts helpful talent loss with damaging talent loss.","zh":"這個片語對比有幫助的人才流失與有害的人才流失。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":12},{"front":"haemorrhage","meaning":"大出血；嚴重流失","examples":[{"en":"The loss of talent in some countries is described as a haemorrhage.","zh":"一些國家的人才流失被描述為大出血。"},{"en":"A haemorrhage is a severe and uncontrolled loss, originally a heavy loss of blood.","zh":"haemorrhage 是嚴重而失控的流失，原意是大量失血。"},{"en":"A company may suffer a haemorrhage of staff if many workers resign at once.","zh":"如果許多員工同時辭職，公司可能遭受人手大出血。"},{"en":"If a country loses a very high share of its doctors, the damage can feel like bleeding talent.","zh":"如果一個國家流失極高比例醫生，傷害就像人才失血。"},{"en":"This word is dramatic and stresses serious loss.","zh":"這個詞語氣強烈，強調嚴重流失。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":12},{"front":"a spur to greater accomplishment","meaning":"促使取得更大成就的動力","examples":[{"en":"Emigration might be a spur to greater accomplishment.","zh":"移民可能是促使取得更大成就的動力。"},{"en":"A spur to greater accomplishment is something that pushes people to achieve more.","zh":"a spur to greater accomplishment 是推動人們取得更多成就的事物。"},{"en":"A competition can be a spur to greater accomplishment if it makes students practise harder.","zh":"如果比賽令學生更努力練習，它可以成為促使更大成就的動力。"},{"en":"If the chance to work abroad inspires education, migration can motivate higher achievement.","zh":"如果海外工作機會激發教育，移民可以推動更高成就。"},{"en":"This phrase describes a force that stimulates progress.","zh":"這個片語描述刺激進步的力量。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":12},{"front":"deserve a chance to","meaning":"值得有機會去……","examples":[{"en":"The poor world’s talent deserves a chance to compete globally.","zh":"貧窮世界的人才值得有機會在全球競爭。"},{"en":"To deserve a chance to do something means to have a fair right or opportunity to try it.","zh":"deserve a chance to do something 指應有公平權利或機會去嘗試某事。"},{"en":"A hardworking student deserves a chance to apply for a scholarship.","zh":"勤奮學生值得有機會申請獎學金。"},{"en":"If talented people are trapped by borders or poverty, their abilities may be wasted.","zh":"如果有才能的人被國界或貧窮困住，他們的能力可能被浪費。"},{"en":"This phrase appeals to fairness and opportunity.","zh":"這個片語訴諸公平與機會。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":12},{"front":"compete on a global stage","meaning":"在全球舞台上競爭","examples":[{"en":"Talented people from poor countries deserve to compete on a global stage.","zh":"來自貧窮國家的有才能人士值得在全球舞台上競爭。"},{"en":"To compete on a global stage means to take part in worldwide competition or opportunity.","zh":"compete on a global stage 指參與世界範圍的競爭或機會。"},{"en":"A young scientist may compete on a global stage by joining an international research team.","zh":"年輕科學家可能透過加入國際研究團隊在全球舞台上競爭。"},{"en":"If skilled workers compete globally, they may earn more and build wider networks.","zh":"如果技術工人在全球競爭，他們可能賺得更多並建立更廣人脈。"},{"en":"This phrase suggests international visibility and competition.","zh":"這個片語暗示國際曝光和競爭。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":12},{"front":"run a managed emigration policy","meaning":"推行受管理的移民政策","examples":[{"en":"It is not easy to run a managed emigration policy.","zh":"推行受管理的移民政策並不容易。"},{"en":"To run a managed emigration policy means to organise and control how many people leave and under what conditions.","zh":"run a managed emigration policy 指組織和控制多少人離開，以及在甚麼條件下離開。"},{"en":"A government may try to manage emigration by offering return programmes for graduates.","zh":"政府可能透過為畢業生提供回流計劃來管理移民外流。"},{"en":"If other countries control visas, the home country cannot fully manage who leaves.","zh":"如果其他國家控制簽證，原居國不能完全管理誰離開。"},{"en":"This phrase describes policy control over outward migration.","zh":"這個片語描述對向外移民的政策控制。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":12},{"front":"the drain of educated minds","meaning":"受教育人才的流失","examples":[{"en":"The drain of educated minds from poor countries is hard to control.","zh":"貧窮國家受教育人才的流失很難控制。"},{"en":"The drain of educated minds means the loss of educated people to other places.","zh":"the drain of educated minds 指受教育人士流失到其他地方。"},{"en":"A hospital system may suffer when trained doctors leave faster than new doctors qualify.","zh":"當受訓醫生離開速度快於新醫生取得資格，醫療系統可能受損。"},{"en":"If educated minds leave permanently, schools, clinics, and firms may lose leadership.","zh":"如果受教育人才永久離開，學校、診所和企業可能失去領導力。"},{"en":"This phrase is another way to describe skilled brain drain.","zh":"這個片語是描述技術人才外流的另一種說法。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":12},{"front":"be determined by","meaning":"由……決定","examples":[{"en":"The drain of skilled workers is mostly determined by host countries’ rules.","zh":"技術工人的流失主要由接收國的規則決定。"},{"en":"To be determined by something means to be decided or strongly shaped by it.","zh":"be determined by something 指由某事決定或強烈塑造。"},{"en":"A student’s final grade may be determined by exams, coursework, and attendance.","zh":"學生的最終成績可能由考試、課業和出席率決定。"},{"en":"If migration depends on host-country visas, home countries have limited control.","zh":"如果移民取決於接收國簽證，原居國控制力便有限。"},{"en":"This phrase identifies the main deciding factor.","zh":"這個片語指出主要決定因素。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":12},{"front":"host countries’ rules","meaning":"接收國的規則","examples":[{"en":"Migration is often controlled by host countries’ rules.","zh":"移民常由接收國的規則控制。"},{"en":"Host countries’ rules are the immigration laws and policies of the countries receiving migrants.","zh":"host countries’ rules 是接收移民國家的移民法律和政策。"},{"en":"A host country may require language tests before allowing skilled workers to enter.","zh":"接收國可能要求語言測試，才允許技術工人入境。"},{"en":"If host countries loosen their rules, more skilled workers may leave poorer countries.","zh":"如果接收國放寬規則，更多技術工人可能離開較貧窮國家。"},{"en":"This phrase focuses on the receiving country’s control.","zh":"這個片語聚焦於接收國的控制權。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":12},{"front":"home countries’ interests","meaning":"原居國的利益","examples":[{"en":"The rules often reflect host countries’ needs rather than home countries’ interests.","zh":"這些規則常反映接收國需要，而不是原居國利益。"},{"en":"Home countries’ interests are the needs and benefits of the countries migrants come from.","zh":"home countries’ interests 是移民來源國的需要和利益。"},{"en":"A home country may want its doctors to stay, while a host country wants to recruit them.","zh":"原居國可能希望醫生留下，而接收國想招聘他們。"},{"en":"If migration policy ignores home countries’ interests, poorer health systems may suffer.","zh":"如果移民政策忽視原居國利益，較貧窮醫療系統可能受損。"},{"en":"This phrase highlights a conflict between sending and receiving countries.","zh":"這個片語突出輸出國與接收國之間的衝突。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":12},{"front":"tremendous pressure","meaning":"巨大壓力","examples":[{"en":"There will be tremendous pressure to loosen immigration rules.","zh":"將會有巨大壓力去放寬移民規則。"},{"en":"Tremendous pressure means very strong force, demand, or urgency.","zh":"tremendous pressure 指非常強的力量、需求或迫切性。"},{"en":"A hospital faces tremendous pressure when many patients arrive and staff are short.","zh":"當大量病人到來而人手不足，醫院會面對巨大壓力。"},{"en":"If rich countries need workers, political pressure to accept migrants may grow.","zh":"如果富國需要工人，接納移民的政治壓力可能增加。"},{"en":"This phrase describes a strong push toward action.","zh":"這個片語描述推動行動的強大壓力。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":13},{"front":"loosen those rules","meaning":"放寬那些規則","examples":[{"en":"Rich countries may loosen those rules in the future.","zh":"富裕國家未來可能放寬那些規則。"},{"en":"To loosen those rules means to make rules less strict.","zh":"loosen those rules 指令規則不那麼嚴格。"},{"en":"A school may loosen uniform rules during very hot weather.","zh":"學校可能在非常炎熱天氣放寬校服規則。"},{"en":"If immigration rules are loosened, more workers may qualify to enter.","zh":"如果移民規則被放寬，更多工人可能符合入境資格。"},{"en":"This phrase describes reducing restrictions.","zh":"這個片語描述減少限制。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":13},{"front":"not least because","meaning":"尤其是因為","examples":[{"en":"Pressure will grow, not least because the baby-boom generation is retiring.","zh":"壓力會增加，尤其是因為嬰兒潮一代正在退休。"},{"en":"Not least because means especially because, among other reasons.","zh":"not least because 指在多個原因中特別因為某個原因。"},{"en":"Students need sleep, not least because tiredness damages concentration.","zh":"學生需要睡眠，尤其是因為疲倦會損害專注力。"},{"en":"Rich countries may need migrants, especially because many older workers are retiring.","zh":"富國可能需要移民，尤其是因為許多年長工人正在退休。"},{"en":"This phrase highlights an important reason without saying it is the only one.","zh":"這個片語突出一個重要原因，但不表示它是唯一原因。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":13},{"front":"baby-boom generation","meaning":"嬰兒潮一代","examples":[{"en":"The baby-boom generation will create pressure on the workforce as it retires.","zh":"嬰兒潮一代退休時會對勞動人口造成壓力。"},{"en":"The baby-boom generation is the large group of people born during a period of high birth rates after World War II.","zh":"baby-boom generation 是二戰後出生率高企時期出生的大量人口。"},{"en":"As the baby-boom generation retires, fewer younger workers may support more older people.","zh":"隨着嬰兒潮一代退休，較少年輕工人可能要支持更多老人。"},{"en":"If many retirees leave the labour force at once, governments may need more taxpaying workers.","zh":"如果許多退休人士同時離開勞動市場，政府可能需要更多納稅工人。"},{"en":"This phrase refers to an age group with major economic effects.","zh":"這個片語指具有重大經濟影響的年齡群體。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":13},{"front":"backfill the taxpaying workforce","meaning":"補充納稅勞動人口","examples":[{"en":"Rich countries will need migrants to backfill the taxpaying workforce.","zh":"富裕國家將需要移民來補充納稅勞動人口。"},{"en":"To backfill the taxpaying workforce means to replace workers who leave or retire so enough people still pay taxes.","zh":"backfill the taxpaying workforce 指補充離職或退休工人，使仍有足夠人納稅。"},{"en":"A hospital may backfill nursing posts when older nurses retire.","zh":"當年長護士退休，醫院可能補充護理職位。"},{"en":"If many workers retire, migrants may help keep public services funded through taxes.","zh":"如果許多工人退休，移民可能透過納稅幫助維持公共服務資金。"},{"en":"This phrase describes filling gaps in the labour force.","zh":"這個片語描述填補勞動力缺口。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":13},{"front":"taxpaying workforce","meaning":"納稅勞動人口","examples":[{"en":"The retiring generation needs a taxpaying workforce behind it.","zh":"退休一代背後需要納稅勞動人口。"},{"en":"The taxpaying workforce is the group of working people who earn income and pay taxes.","zh":"taxpaying workforce 是有工作收入並繳稅的勞動人口。"},{"en":"A country needs a strong taxpaying workforce to fund hospitals, pensions, and schools.","zh":"一個國家需要強大的納稅勞動人口來資助醫院、退休金和學校。"},{"en":"If the workforce shrinks, public finances may come under pressure.","zh":"如果勞動人口縮小，公共財政可能承受壓力。"},{"en":"This phrase links employment with government revenue.","zh":"這個片語把就業與政府收入連接起來。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":13},{"front":"as someone puts it","meaning":"正如某人所說","examples":[{"en":"The authors describe this need as backfilling the taxpaying workforce.","zh":"正如作者所說，這種需要是補充納稅勞動人口。"},{"en":"As someone puts it means in the words used by that person.","zh":"as someone puts it 指用某人所用的說法來表達。"},{"en":"As the teacher puts it, practice is the bridge between knowing and using.","zh":"正如老師所說，練習是知道與使用之間的橋樑。"},{"en":"If an author’s wording is memorable, quoting how they put it can make the point clearer.","zh":"如果作者措辭令人印象深刻，引用他的說法可以令重點更清楚。"},{"en":"This phrase introduces another person’s expression.","zh":"這個片語引入另一人的表達方式。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":13},{"front":"no longer welcomes","meaning":"不再歡迎……","examples":[{"en":"The rich world no longer welcomes the tired and the huddled.","zh":"富裕世界不再歡迎疲憊而擁擠的人群。"},{"en":"No longer welcomes means used to accept or invite, but does not do so now.","zh":"no longer welcomes 指以前接受或邀請，但現在不再如此。"},{"en":"A club may no longer welcome new members if the room is already full.","zh":"如果房間已滿，社團可能不再歡迎新會員。"},{"en":"If rich countries prefer skilled migrants, they may become less open to poorer migrants.","zh":"如果富國較偏好技術移民，它們可能對較貧窮移民較不開放。"},{"en":"This phrase shows a change from past openness to present restriction.","zh":"這個片語顯示由過去開放轉向現在限制。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":13},{"front":"the tired and the huddled","meaning":"疲憊而擁擠的人群","examples":[{"en":"The phrase the tired and the huddled refers to poor and desperate migrants.","zh":"the tired and the huddled 這個片語指貧窮而絕望的移民。"},{"en":"The tired and the huddled describes exhausted, crowded, vulnerable people seeking refuge or opportunity.","zh":"the tired and the huddled 描述疲憊、擠在一起、脆弱並尋求庇護或機會的人。"},{"en":"A refugee family arriving after a long journey may look tired and huddled together.","zh":"經過長途旅程抵達的難民家庭可能看起來疲憊並聚在一起。"},{"en":"If rich countries stop welcoming such migrants, immigration policy becomes more selective.","zh":"如果富國停止歡迎這類移民，移民政策便變得更具選擇性。"},{"en":"This phrase is emotional and evokes hardship.","zh":"這個片語帶情感色彩，喚起艱難處境。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":13},{"front":"looks set to","meaning":"看來將會","examples":[{"en":"The rich world looks set to compete for skilled workers.","zh":"富裕世界看來將會爭奪技術工人。"},{"en":"Looks set to means seems likely to do something soon or in the future.","zh":"looks set to 指看似很可能很快或將來做某事。"},{"en":"The school looks set to open a new library after receiving funding.","zh":"學校獲得資金後，看來將會開設新圖書館。"},{"en":"If ageing countries need workers, they look likely to recruit more skilled migrants.","zh":"如果老齡化國家需要工人，它們看來很可能招聘更多技術移民。"},{"en":"This phrase describes a likely future development.","zh":"這個片語描述很可能出現的未來發展。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":13},{"front":"compete ever more fiercely for","meaning":"為爭奪……而競爭越來越激烈","examples":[{"en":"Rich countries will compete ever more fiercely for educated migrants.","zh":"富裕國家將為爭奪受教育移民而競爭越來越激烈。"},{"en":"To compete ever more fiercely for something means to fight increasingly hard to obtain it.","zh":"compete ever more fiercely for something 指越來越激烈地爭取某物。"},{"en":"Universities may compete ever more fiercely for top students when student numbers fall.","zh":"當學生人數下降，大學可能為爭奪頂尖學生而競爭越來越激烈。"},{"en":"If skilled workers become scarce, rich countries may offer better visas and salaries.","zh":"如果技術工人變得稀缺，富國可能提供更好簽證和薪酬。"},{"en":"This phrase stresses growing intensity in competition.","zh":"這個片語強調競爭強度不斷增加。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":13},{"front":"the bright and the qualified","meaning":"聰明而具資格的人才","examples":[{"en":"The rich world increasingly seeks the bright and the qualified.","zh":"富裕世界越來越尋求聰明而具資格的人才。"},{"en":"The bright and the qualified means intelligent people with recognised skills or credentials.","zh":"the bright and the qualified 指聰明並擁有認可技能或資格的人。"},{"en":"A technology company may recruit the bright and the qualified from universities around the world.","zh":"科技公司可能從世界各地大學招聘聰明而具資格的人才。"},{"en":"If rich countries prefer such migrants, poorer countries may lose some of their best-trained people.","zh":"如果富國偏好這類移民，較貧窮國家可能失去部分最受訓的人才。"},{"en":"This phrase contrasts skilled migrants with poorer and less qualified migrants.","zh":"這個片語把技術移民與較貧窮和資格較低移民作對比。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":14},{"front":"which paragraph does each heading best fit","meaning":"每個標題最適合哪一段","examples":[{"en":"Students decide which paragraph each heading best fits.","zh":"學生判斷每個標題最適合哪一段。"},{"en":"Which paragraph does each heading best fit asks students to match headings with the most suitable paragraph.","zh":"which paragraph does each heading best fit 要求學生把標題與最合適段落配對。"},{"en":"In a reading test, a heading about “brain gain” should match the paragraph discussing positive effects.","zh":"在閱讀測驗中，關於「人才增益」的標題應配對討論正面效果的段落。"},{"en":"If students match only keywords, they may choose the wrong paragraph.","zh":"如果學生只配對關鍵字，可能選錯段落。"},{"en":"This phrase is a common heading-matching instruction.","zh":"這個片語是常見標題配對指示。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":14},{"front":"brain gain or brain drain","meaning":"人才增益還是人才外流","examples":[{"en":"The heading brain gain or brain drain contrasts the benefits and losses of migration.","zh":"標題 brain gain or brain drain 對比移民的好處和損失。"},{"en":"Brain gain or brain drain asks whether migration increases or reduces a country’s skilled people overall.","zh":"brain gain or brain drain 問移民整體上是增加還是減少一國技術人才。"},{"en":"A village may face brain drain when graduates leave, but brain gain if their example keeps others in school.","zh":"當畢業生離開，村莊可能面對人才外流；但如果他們的榜樣令其他人留校，則可能有人才增益。"},{"en":"If education rises more than emigration, migration may help rather than harm.","zh":"如果教育增長多於移民外流，移民可能是幫助而非傷害。"},{"en":"This phrase frames migration as a balanced question, not a simple judgement.","zh":"這個片語把移民視為平衡問題，而不是簡單判斷。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":14},{"front":"brain haemorrhage","meaning":"人才大出血","examples":[{"en":"Brain haemorrhage describes a severe loss of educated people.","zh":"brain haemorrhage 描述受教育人士的嚴重流失。"},{"en":"Brain haemorrhage is a dramatic phrase for extreme brain drain.","zh":"brain haemorrhage 是形容極端人才外流的強烈說法。"},{"en":"A country losing most of its doctors may be described as suffering a brain haemorrhage.","zh":"流失大部分醫生的國家可能被描述為遭受人才大出血。"},{"en":"If talent loss is this severe, ordinary “brain drain” may sound too mild.","zh":"如果人才流失如此嚴重，普通的「人才外流」可能聽起來太溫和。"},{"en":"This phrase stresses emergency-level loss of skilled people.","zh":"這個片語強調技術人才的危急級別流失。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":14},{"front":"migrants can be connectors","meaning":"移民可成為連繫者","examples":[{"en":"Migrants can be connectors between their home countries and foreign markets.","zh":"移民可以成為原居國與外國市場之間的連繫者。"},{"en":"Migrants can be connectors means migrants can link people, businesses, and ideas across countries.","zh":"migrants can be connectors 指移民可以連接不同國家的人、企業和想法。"},{"en":"An emigrant working abroad may introduce a local company to overseas buyers.","zh":"在海外工作的移民可能把本地公司介紹給海外買家。"},{"en":"If migrants keep contacts in both places, they can help trade, investment, and knowledge flow.","zh":"如果移民在兩地都保持人脈，他們可以幫助貿易、投資和知識流動。"},{"en":"This phrase presents migration as connection, not only loss.","zh":"這個片語把移民呈現為連接，而不只是損失。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":14},{"front":"opportunities lead to longer education","meaning":"機會帶來更長時間的教育","examples":[{"en":"Opportunities abroad can lead to longer education at home.","zh":"海外機會可以在本國帶來更長時間的教育。"},{"en":"Opportunities lead to longer education means people study for more years because they see future rewards.","zh":"opportunities lead to longer education 指人們因看見未來回報而讀書更多年。"},{"en":"A scholarship opportunity may lead a student to stay in school instead of leaving for work.","zh":"獎學金機會可能令學生留校讀書，而不是離校工作。"},{"en":"If migration requires qualifications, young people may invest more time in education.","zh":"如果移民需要資格，年輕人可能把更多時間投資於教育。"},{"en":"This phrase links future chances with present schooling decisions.","zh":"這個片語把未來機會與當前教育決策連接起來。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":14},{"front":"according to the text","meaning":"根據文章","examples":[{"en":"Students should choose statements according to the text.","zh":"學生應根據文章選擇陳述。"},{"en":"According to the text means based only on what the passage says.","zh":"according to the text 指只根據文章所說。"},{"en":"In reading exams, students should answer according to the text, not personal opinion.","zh":"在閱讀考試中，學生應根據文章作答，而不是個人意見。"},{"en":"If the text gives no evidence, students should not invent an answer.","zh":"如果文本沒有證據，學生不應自行創作答案。"},{"en":"This phrase reminds candidates to stay close to the source.","zh":"這個片語提醒考生緊貼來源。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":14},{"front":"corresponding letters","meaning":"相應字母","examples":[{"en":"Students write the corresponding letters in the answer boxes.","zh":"學生在答案框中寫下相應字母。"},{"en":"Corresponding letters are the letters that match the correct options or statements.","zh":"corresponding letters 是與正確選項或陳述相配的字母。"},{"en":"If option C matches paragraph 4, C is the corresponding letter.","zh":"如果選項 C 配對第4段，C 就是相應字母。"},{"en":"Students lose marks if they understand the answer but write the wrong corresponding letter.","zh":"如果學生理解答案但寫錯相應字母，仍會失分。"},{"en":"This phrase is common in matching tasks.","zh":"這個片語常見於配對題。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":14},{"front":"in any order","meaning":"以任何次序","examples":[{"en":"The five answers can be written in any order.","zh":"五個答案可以以任何次序書寫。"},{"en":"In any order means the sequence does not matter.","zh":"in any order 指排列次序不重要。"},{"en":"Students may list three correct letters in any order if the instruction allows it.","zh":"如果指示容許，學生可以以任何次序列出三個正確字母。"},{"en":"If answers are accepted in any order, candidates should focus on accuracy rather than sequence.","zh":"如果答案可以以任何次序接受，考生應專注準確性而不是順序。"},{"en":"This phrase removes the need to arrange answers.","zh":"這個片語表示不需要排列答案。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":14},{"front":"health care workers","meaning":"醫護人員","examples":[{"en":"The emigration of health care workers can seriously affect poor countries.","zh":"醫護人員移民外流可以嚴重影響貧窮國家。"},{"en":"Health care workers are people who provide medical care, such as doctors, nurses, and carers.","zh":"health care workers 是提供醫療護理的人，例如醫生、護士和護理員。"},{"en":"A clinic cannot serve patients well if too many health care workers leave.","zh":"如果太多醫護人員離開，診所便不能好好服務病人。"},{"en":"If rich countries recruit health workers from poor countries, local hospitals may suffer shortages.","zh":"如果富國從貧窮國家招聘醫護人員，本地醫院可能人手短缺。"},{"en":"This phrase refers to people working in medical and care services.","zh":"這個片語指醫療和護理服務中的工作者。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":14},{"front":"more important than","meaning":"比……更重要","examples":[{"en":"The departure of doctors may be more important than that of footballers.","zh":"醫生的離開可能比足球員的離開更重要。"},{"en":"More important than means having greater seriousness, value, or effect compared with something else.","zh":"more important than 指相比另一事物有更大嚴重性、價值或影響。"},{"en":"Clean water may be more important than a new shopping centre for a poor community.","zh":"對貧困社區而言，清潔食水可能比新商場更重要。"},{"en":"If doctors leave, the effect on health may be more serious than the loss of sports talent.","zh":"如果醫生離開，對健康的影響可能比體育人才流失更嚴重。"},{"en":"This phrase compares priority or significance.","zh":"這個片語比較優先次序或重要性。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":14},{"front":"chances of getting a visa","meaning":"取得簽證的機會","examples":[{"en":"The chances of getting a visa may affect people’s education decisions.","zh":"取得簽證的機會可能影響人們的教育決定。"},{"en":"Chances of getting a visa means the probability of receiving legal permission to enter or stay in another country.","zh":"chances of getting a visa 指獲得進入或逗留另一國合法許可的概率。"},{"en":"A student may choose a course partly because it improves her chances of getting a visa.","zh":"學生可能部分因某課程提高取得簽證機會而選擇它。"},{"en":"If visa chances are low, many educated people may remain in their home country.","zh":"如果簽證機會低，許多受教育人士可能留在本國。"},{"en":"This phrase connects migration rules with personal planning.","zh":"這個片語把移民規則與個人規劃連接起來。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":15},{"front":"benefit poor countries","meaning":"令貧窮國家受惠","examples":[{"en":"Low visa chances could benefit poor countries by increasing education.","zh":"低簽證機會可以透過增加教育令貧窮國家受惠。"},{"en":"To benefit poor countries means to help poorer nations improve or avoid losses.","zh":"benefit poor countries 指幫助較貧窮國家改善或避免損失。"},{"en":"Training programmes can benefit poor countries if graduates stay and work locally.","zh":"如果畢業生留下並在本地工作，培訓計劃可以令貧窮國家受惠。"},{"en":"If migration hopes make more people study but few actually leave, the home country may gain skills.","zh":"如果移民希望令更多人讀書，但實際離開的人少，原居國可能獲得技能。"},{"en":"This phrase focuses on advantages for less wealthy nations.","zh":"這個片語聚焦於對較不富裕國家的好處。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":15},{"front":"difficult to measure","meaning":"難以量度","examples":[{"en":"International migration can be difficult to measure accurately.","zh":"國際移民可能難以準確量度。"},{"en":"Difficult to measure means hard to count, estimate, or record reliably.","zh":"difficult to measure 指難以可靠地點算、估算或記錄。"},{"en":"Student stress is difficult to measure because people show it in different ways.","zh":"學生壓力難以量度，因為人們以不同方式表現壓力。"},{"en":"If migration data are incomplete, researchers may disagree about its effects.","zh":"如果移民數據不完整，研究人員可能對其影響有分歧。"},{"en":"This phrase describes a problem with evidence and numbers.","zh":"這個片語描述證據和數字方面的問題。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":15},{"front":"flow of money","meaning":"資金流動","examples":[{"en":"The flow of money across borders is easier to measure than migration.","zh":"跨境資金流動比移民更容易量度。"},{"en":"Flow of money means the movement of funds from one place to another.","zh":"flow of money 指資金從一地移動到另一地。"},{"en":"Banks record the flow of money when customers send remittances abroad.","zh":"當客戶向海外匯款，銀行會記錄資金流動。"},{"en":"Because money transfers leave records, they may be easier to track than people’s movements.","zh":"因為轉帳留下紀錄，資金流動可能比人口移動更容易追蹤。"},{"en":"This phrase is common in economics and finance.","zh":"這個片語常見於經濟和金融。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":15},{"front":"across national borders","meaning":"跨越國界","examples":[{"en":"Capital often moves across national borders.","zh":"資本常跨越國界流動。"},{"en":"Across national borders means from one country into another.","zh":"across national borders 指從一個國家進入另一個國家。"},{"en":"Goods move across national borders when companies export them.","zh":"公司出口貨物時，貨物會跨越國界。"},{"en":"If workers move across national borders, they become international migrants.","zh":"如果工人跨越國界移動，他們便成為國際移民。"},{"en":"This phrase describes movement between countries.","zh":"這個片語描述國家之間的移動。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":15},{"front":"to a certain extent","meaning":"在某程度上","examples":[{"en":"A person’s productivity depends, to a certain extent, on others.","zh":"一個人的生產力在某程度上取決於他人。"},{"en":"To a certain extent means partly, but not completely.","zh":"to a certain extent 指部分地，但不是完全地。"},{"en":"Exam success depends to a certain extent on natural ability, but practice matters too.","zh":"考試成功在某程度上取決於天分，但練習也重要。"},{"en":"If productivity depends partly on colleagues, one person’s education can benefit others.","zh":"如果生產力部分取決於同事，一個人的教育也可以惠及他人。"},{"en":"This phrase limits a statement so it is not too absolute.","zh":"這個片語限制說法，使它不太絕對。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":15},{"front":"set up coding industries","meaning":"建立編程產業","examples":[{"en":"Skilled workers can help set up coding industries.","zh":"技術工人可以幫助建立編程產業。"},{"en":"To set up coding industries means to create businesses or sectors based on computer programming.","zh":"set up coding industries 指建立以電腦編程為基礎的企業或行業。"},{"en":"A city may set up a coding industry by training programmers and supporting start-ups.","zh":"城市可以透過培訓程式員和支持初創公司來建立編程產業。"},{"en":"If enough skilled coders remain, local companies can begin producing software.","zh":"如果足夠技術程式員留下，本地公司便能開始生產軟件。"},{"en":"This phrase describes building a technology sector from the ground up.","zh":"這個片語描述從零建立科技產業。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":15},{"front":"Indian-born people with degrees","meaning":"擁有學位的印度出生人士","examples":[{"en":"The question refers to Indian-born people with degrees.","zh":"題目指擁有學位的印度出生人士。"},{"en":"Indian-born people with degrees are people born in India who have university qualifications.","zh":"Indian-born people with degrees 是在印度出生並擁有大學學歷的人。"},{"en":"An Indian-born person with a degree may work in the United States or return to India later.","zh":"擁有學位的印度出生人士可能在美國工作，或之後返回印度。"},{"en":"If many degree holders live abroad, the effect depends on how many graduates remain at home.","zh":"如果許多學位持有人居住海外，影響取決於國內仍有多少畢業生。"},{"en":"This phrase identifies migrants by birthplace and education level.","zh":"這個片語按出生地和教育水平識別移民。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":15},{"front":"return to India","meaning":"返回印度","examples":[{"en":"The option asks whether most Indian emigrants return to India.","zh":"這個選項問大多數印度移民是否返回印度。"},{"en":"To return to India means to go back to India after living or working elsewhere.","zh":"return to India 指在其他地方生活或工作後回到印度。"},{"en":"An engineer may return to India after gaining experience in Silicon Valley.","zh":"工程師可能在矽谷取得經驗後返回印度。"},{"en":"If emigrants return with skills and contacts, they may help local industries.","zh":"如果移民帶着技能和人脈回流，他們可能幫助本地產業。"},{"en":"This phrase describes movement back to the country of origin.","zh":"這個片語描述回到原居國的移動。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":15},{"front":"international migration policy","meaning":"國際移民政策","examples":[{"en":"International migration policy is often shaped by rich countries.","zh":"國際移民政策常由富裕國家塑造。"},{"en":"International migration policy means rules about who can move between countries and under what conditions.","zh":"international migration policy 指關於誰可以在國家之間移動及在甚麼條件下移動的規則。"},{"en":"Visa quotas and work permits are part of international migration policy.","zh":"簽證配額和工作許可都是國際移民政策的一部分。"},{"en":"If rich countries change immigration rules, workers in poor countries may respond.","zh":"如果富國改變移民規則，貧窮國家的工人可能作出反應。"},{"en":"This phrase links government rules with cross-border movement.","zh":"這個片語把政府規則與跨境移動連接起來。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":15},{"front":"largely decided by","meaning":"主要由……決定","examples":[{"en":"Migration policy is largely decided by host countries.","zh":"移民政策主要由接收國決定。"},{"en":"Largely decided by means mainly determined by something or someone.","zh":"largely decided by 指主要由某事或某人決定。"},{"en":"A student’s timetable is largely decided by the school, not by the student.","zh":"學生時間表主要由學校決定，而不是學生自己決定。"},{"en":"If host countries control visas, poor countries cannot easily manage emigration.","zh":"如果接收國控制簽證，貧窮國家便難以管理移民外流。"},{"en":"This phrase identifies the main source of decision-making power.","zh":"這個片語指出決策權的主要來源。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":15},{"front":"rich countries rather than poor ones","meaning":"富國而非窮國","examples":[{"en":"Migration rules are often set by rich countries rather than poor ones.","zh":"移民規則常由富國而非窮國制定。"},{"en":"Rich countries rather than poor ones means wealthy countries, not poorer countries, are the main actors.","zh":"rich countries rather than poor ones 指主要行動者是富裕國家，而不是貧窮國家。"},{"en":"International exam standards may be influenced by elite universities rather than small schools.","zh":"國際考試標準可能受精英大學而非小學校影響。"},{"en":"If rich countries set the rules, poor countries’ interests may be overlooked.","zh":"如果富國制定規則，窮國利益可能被忽視。"},{"en":"This phrase shows contrast between who has power and who is affected.","zh":"這個片語對比誰有權力與誰受影響。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":16},{"front":"according to the information given","meaning":"根據文中提供的資料","examples":[{"en":"Students choose answers according to the information given in the text.","zh":"學生根據文中提供的資料選擇答案。"},{"en":"According to the information given means based only on the details provided in the passage.","zh":"according to the information given 指只根據文章提供的細節。"},{"en":"In reading tests, students should not use outside knowledge if the information given is enough.","zh":"在閱讀測驗中，如果文中資料足夠，學生不應使用外部知識。"},{"en":"If the text says nothing about a claim, the answer may be NOT GIVEN.","zh":"如果文本沒有提及某主張，答案可能是 NOT GIVEN。"},{"en":"This phrase keeps answers grounded in the source.","zh":"這個片語令答案緊扣來源。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":16},{"front":"choose the correct answer","meaning":"選出正確答案","examples":[{"en":"Students choose the correct answer from the choices given.","zh":"學生從所給選項中選出正確答案。"},{"en":"To choose the correct answer means to select the option that best matches the question and passage.","zh":"choose the correct answer 指選擇最符合題目和文章的選項。"},{"en":"A student should read all options before choosing the correct answer.","zh":"學生應閱讀所有選項後才選出正確答案。"},{"en":"If two answers look similar, the correct one must match the exact meaning of the text.","zh":"如果兩個答案看似相似，正確答案必須符合文本的確切意思。"},{"en":"This phrase is a standard exam instruction.","zh":"這個片語是標準考試指示。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":16},{"front":"was not expected to","meaning":"不被預期會……","examples":[{"en":"Senegal was not expected to beat France in the 2002 World Cup.","zh":"塞內加爾不被預期會在2002年世界盃擊敗法國。"},{"en":"Was not expected to means people did not think something would happen.","zh":"was not expected to 指人們不認為某事會發生。"},{"en":"A small school team was not expected to win against the champion school.","zh":"小型校隊不被預期會擊敗冠軍學校。"},{"en":"When an unlikely team wins, the result feels surprising because expectations were low.","zh":"當不被看好的隊伍勝出，結果會令人驚訝，因為期望很低。"},{"en":"This phrase describes prediction before an event.","zh":"這個片語描述事件前的預測。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":16},{"front":"provide most of","meaning":"提供大部分……","examples":[{"en":"The option asks whether Senegal provides most of the African footballers in Europe.","zh":"這個選項問塞內加爾是否提供歐洲大部分非洲足球員。"},{"en":"To provide most of something means to supply the largest part or majority of it.","zh":"provide most of something 指供應某物最大部分或多數。"},{"en":"One bakery may provide most of the bread for a small school canteen.","zh":"一間麵包店可能為小學飯堂提供大部分麵包。"},{"en":"If one country provides most players, its role in the league is unusually large.","zh":"如果一個國家提供大部分球員，它在聯賽中的角色便異常大。"},{"en":"This phrase focuses on supplying the majority.","zh":"這個片語聚焦於供應多數。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":16},{"front":"be beneficial because","meaning":"有益，因為……","examples":[{"en":"The departure of players may be beneficial because it encourages others.","zh":"球員離開可能有益，因為它鼓勵其他人。"},{"en":"Be beneficial because means be helpful for a particular reason.","zh":"be beneficial because 指因某個特定原因而有幫助。"},{"en":"Reading aloud is beneficial because it improves pronunciation and confidence.","zh":"朗讀有益，因為它改善發音和信心。"},{"en":"If footballers leave but inspire more young people to train, their departure may have a positive effect.","zh":"如果足球員離開但激勵更多年輕人訓練，他們的離開可能有正面作用。"},{"en":"This phrase explains the reason something helps.","zh":"這個片語解釋某事為何有幫助。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":16},{"front":"tend to migrate","meaning":"往往會遷移","examples":[{"en":"Some Mexicans tend to migrate within their own country.","zh":"一些墨西哥人往往會在本國內遷移。"},{"en":"Tend to migrate means usually or often move from one place to another.","zh":"tend to migrate 指通常或經常從一地遷往另一地。"},{"en":"Young graduates may tend to migrate to cities where jobs are easier to find.","zh":"年輕畢業生往往會遷移到較易找到工作的城市。"},{"en":"If rural wages are low, workers may migrate to towns or border areas.","zh":"如果鄉郊工資低，工人可能遷往城鎮或邊境地區。"},{"en":"This phrase describes a common movement pattern.","zh":"這個片語描述常見移動模式。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":16},{"front":"not a big problem because","meaning":"不是大問題，因為……","examples":[{"en":"India’s brain drain may not be a big problem because it is a small percentage of its graduates.","zh":"印度的人才外流可能不是大問題，因為它只佔畢業生的一小部分。"},{"en":"Not a big problem because means something may be less serious for the reason given.","zh":"not a big problem because 指某事因所給原因而可能沒那麼嚴重。"},{"en":"A student’s one spelling mistake is not a big problem because the main argument is clear.","zh":"學生一個拼寫錯誤不是大問題，因為主要論點很清楚。"},{"en":"If emigrants are a small share of all graduates, the country may still have enough skilled people.","zh":"如果移民只佔所有畢業生的一小部分，國家可能仍有足夠技術人才。"},{"en":"This phrase explains why a situation may be less worrying than it seems.","zh":"這個片語解釋為何某情況可能沒有看起來那麼令人擔心。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":16},{"front":"a small percentage of","meaning":"一小部分","examples":[{"en":"India’s brain drain represents a small percentage of its graduate population.","zh":"印度的人才外流只佔其畢業生人口的一小部分。"},{"en":"A small percentage of something means a low proportion of the total.","zh":"a small percentage of something 指總數中的低比例。"},{"en":"A small percentage of students may need extra support after the first test.","zh":"第一次測驗後，只有一小部分學生可能需要額外支援。"},{"en":"If only a small percentage of graduates leave, the country keeps most of its educated people.","zh":"如果只有一小部分畢業生離開，國家便保留大多數受教育人士。"},{"en":"This phrase compares a part with the whole.","zh":"這個片語把部分與整體作比較。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":16},{"front":"spread all over the world","meaning":"分布於世界各地","examples":[{"en":"Indian emigrants are spread all over the world.","zh":"印度移民分布於世界各地。"},{"en":"Spread all over the world means located in many countries and regions globally.","zh":"spread all over the world 指分布在全球許多國家和地區。"},{"en":"A famous singer’s fans may be spread all over the world.","zh":"著名歌手的粉絲可能分布於世界各地。"},{"en":"If emigrants are spread widely, they can connect the home country with many markets.","zh":"如果移民分布廣泛，他們可以把原居國與許多市場連接起來。"},{"en":"This phrase emphasises wide international distribution.","zh":"這個片語強調廣泛的國際分布。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":16},{"front":"government restricts emigration carefully","meaning":"政府謹慎限制移民外流","examples":[{"en":"A government may restrict emigration carefully, although this is difficult to manage.","zh":"政府可能謹慎限制移民外流，雖然這很難管理。"},{"en":"If a government restricts emigration carefully, it tries to control people leaving without causing unfair harm.","zh":"government restricts emigration carefully 指政府嘗試控制人口外流，同時避免造成不公平傷害。"},{"en":"A country may ask publicly trained doctors to serve locally for several years before working abroad.","zh":"國家可能要求公費培訓的醫生先在本地服務數年，才到海外工作。"},{"en":"If restrictions are too harsh, talented people may feel trapped or treated unfairly.","zh":"如果限制太嚴厲，有才能的人可能感到被困住或被不公平對待。"},{"en":"This phrase describes a difficult balance between national needs and individual freedom.","zh":"這個片語描述國家需要與個人自由之間的困難平衡。"}],"source":"98 - Fruit that Falls Far from the Tree.pdf","sourcePage":16}],"ielts/reading/passage-2/Practice 99":[{"front":"reading the screen","meaning":"閱讀屏幕","examples":[{"en":"The article discusses whether reading the screen can support modern literacy.","zh":"文章討論閱讀屏幕是否能支持現代讀寫能力。"},{"en":"Reading the screen means reading words, images, and information on digital devices.","zh":"閱讀屏幕是指在數碼裝置上閱讀文字、影像和資訊。"},{"en":"A student is reading the screen when they study an online article on a tablet.","zh":"學生在平板電腦上閱讀網上文章時，就是在閱讀屏幕。"},{"en":"If children spend more time online, reading the screen may become part of their daily literacy.","zh":"如果兒童花更多時間上網，閱讀屏幕可能成為日常讀寫能力的一部分。"},{"en":"This phrase contrasts digital reading with reading printed books or papers.","zh":"這個片語把數碼閱讀與閱讀印刷書籍或紙張作對比。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":1},{"front":"electronic media","meaning":"電子媒體","examples":[{"en":"The writer asks whether electronic media are making children less literate.","zh":"作者問電子媒體是否令兒童讀寫能力下降。"},{"en":"Electronic media are forms of communication that use electronic technology, such as television, computers, and the Internet.","zh":"電子媒體是使用電子科技的傳播形式，例如電視、電腦和互聯網。"},{"en":"Students use electronic media when they watch educational videos or read online articles.","zh":"學生觀看教育影片或閱讀網上文章時，就是使用電子媒體。"},{"en":"Electronic media can reduce some old habits, but they can also create new forms of reading and writing.","zh":"電子媒體可以減少一些舊習慣，但也可以創造新的閱讀和寫作形式。"},{"en":"This phrase refers to digital and broadcast media rather than printed books alone.","zh":"這個片語指數碼和廣播媒體，而不只是印刷書籍。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":1},{"front":"exacerbate illiteracy","meaning":"加劇文盲問題；令讀寫能力問題惡化","examples":[{"en":"Some people fear that electronic media may exacerbate illiteracy.","zh":"有些人擔心電子媒體可能加劇文盲問題。"},{"en":"To exacerbate illiteracy means to make problems with reading and writing worse.","zh":"To exacerbate illiteracy 指令閱讀和寫作問題惡化。"},{"en":"A school may exacerbate illiteracy if it gives students screens but no guidance on reading carefully.","zh":"如果學校只給學生屏幕，卻沒有指導他們仔細閱讀，可能會令讀寫能力問題惡化。"},{"en":"If children only watch short videos and rarely read, their reading problems may become worse.","zh":"如果兒童只看短片而很少閱讀，他們的閱讀問題可能變得更嚴重。"},{"en":"This phrase describes a negative effect that deepens an existing literacy problem.","zh":"這個片語描述令現有讀寫問題加深的負面影響。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":1},{"front":"illiteracy","meaning":"文盲；缺乏讀寫能力","examples":[{"en":"The article challenges the claim that new media increase illiteracy.","zh":"文章質疑新媒體增加文盲問題這一說法。"},{"en":"Illiteracy means the inability or serious difficulty to read and write.","zh":"Illiteracy 指不能閱讀和寫作，或在讀寫方面有嚴重困難。"},{"en":"Adults with illiteracy may struggle to read medicine labels, forms, or bus notices.","zh":"缺乏讀寫能力的成年人可能難以閱讀藥物標籤、表格或巴士告示。"},{"en":"Poor education, poverty, and lack of reading practice can contribute to illiteracy.","zh":"教育不足、貧窮和缺乏閱讀練習都可能造成文盲問題。"},{"en":"This word describes a serious lack of literacy, not just weak spelling.","zh":"這個詞描述嚴重缺乏讀寫能力，而不只是串字差。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":1},{"front":"make someone stupid","meaning":"令某人變笨","examples":[{"en":"The opening question asks whether electronic media are making children stupid.","zh":"開首問題問電子媒體是否正在令兒童變笨。"},{"en":"To make someone stupid means to reduce their ability to think, learn, or judge clearly.","zh":"To make someone stupid 指降低某人清楚思考、學習或判斷的能力。"},{"en":"Some parents worry that too much passive screen time may make children less curious.","zh":"有些家長擔心過多被動屏幕時間可能令孩子變得較少好奇心。"},{"en":"If technology is used without thinking, it may weaken attention rather than build knowledge.","zh":"如果科技被不加思考地使用，它可能削弱注意力，而不是建立知識。"},{"en":"This phrase is informal and strong, so it is often used in arguments or criticism.","zh":"這個片語較口語且語氣強烈，常用於爭論或批評中。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":1},{"front":"on the contrary","meaning":"相反","examples":[{"en":"On the contrary, Colin McCabe argues that electronic media may improve literacy.","zh":"相反，Colin McCabe認為電子媒體可能改善讀寫能力。"},{"en":"On the contrary is used to introduce the opposite of what has just been suggested.","zh":"On the contrary 用來引出與剛才所說相反的意思。"},{"en":"Some people think online learning is useless; on the contrary, it can help students in remote areas.","zh":"有些人認為網上學習沒有用；相反，它可以幫助偏遠地區的學生。"},{"en":"If evidence shows the opposite result, a writer may use “on the contrary” to correct a false idea.","zh":"如果證據顯示相反結果，作者可能用 “on the contrary” 修正錯誤想法。"},{"en":"This phrase clearly signals contrast and disagreement.","zh":"這個片語清楚標示對比和不同意。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":1},{"front":"have the potential to","meaning":"有潛力去","examples":[{"en":"New media have the potential to make people truly literate.","zh":"新媒體有潛力令人真正具備讀寫能力。"},{"en":"To have the potential to do something means to be able to develop into that result.","zh":"To have the potential to do something 指有能力發展成某種結果。"},{"en":"A quiet student may have the potential to become a strong speaker with enough practice.","zh":"安靜的學生如果有足夠練習，可能有潛力成為強大的演講者。"},{"en":"Technology has the potential to support learning if teachers use it carefully.","zh":"如果老師謹慎使用科技，它有潛力支持學習。"},{"en":"This phrase suggests possibility, not guaranteed success.","zh":"這個片語暗示可能性，而不是保證成功。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":1},{"front":"truly literate","meaning":"真正具備讀寫能力的","examples":[{"en":"The writer believes that electronic media can make us truly literate.","zh":"作者相信電子媒體可以令我們真正具備讀寫能力。"},{"en":"Truly literate means able to understand, use, judge, and create meaning through different forms of language and media.","zh":"Truly literate 指能透過不同語言和媒體形式理解、使用、判斷和創造意義。"},{"en":"A truly literate student can read a news article and question its evidence.","zh":"真正具備讀寫能力的學生能閱讀新聞文章，並質疑其證據。"},{"en":"In modern life, true literacy may include print, screens, images, and sound.","zh":"在現代生活中，真正的讀寫能力可能包括印刷文字、屏幕、影像和聲音。"},{"en":"This phrase suggests deep literacy, not just basic reading and writing.","zh":"這個片語暗示深層讀寫能力，而不只是基本閱讀和寫作。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":1},{"front":"the debate surrounding","meaning":"圍繞……的辯論","examples":[{"en":"The debate surrounding literacy is highly charged.","zh":"圍繞讀寫能力的辯論非常激烈。"},{"en":"The debate surrounding something is the discussion, disagreement, or controversy around it.","zh":"The debate surrounding something 指圍繞某事的討論、分歧或爭議。"},{"en":"The debate surrounding homework often includes parents, teachers, and students.","zh":"圍繞功課的辯論常包括家長、老師和學生。"},{"en":"When an issue affects children’s future, the debate surrounding it may become emotional.","zh":"當議題影響兒童未來，圍繞它的辯論可能變得情緒化。"},{"en":"This phrase describes the arguments around a topic.","zh":"這個片語描述圍繞某主題的爭論。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":1},{"front":"literacy","meaning":"讀寫能力","examples":[{"en":"The passage explores changing ideas about literacy.","zh":"文章探討關於讀寫能力的不斷變化的想法。"},{"en":"Literacy is the ability to read, write, understand, and use language effectively.","zh":"Literacy 是有效閱讀、寫作、理解和使用語言的能力。"},{"en":"A person needs literacy to read forms, messages, websites, and instructions.","zh":"人需要讀寫能力來閱讀表格、訊息、網站和指示。"},{"en":"As media change, literacy may also include understanding images, screens, and digital information.","zh":"隨着媒體改變，讀寫能力也可能包括理解影像、屏幕和數碼資訊。"},{"en":"This word can mean more than simply knowing letters and words.","zh":"這個詞可以不只是認識字母和詞語。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":1},{"front":"one of the most charged","meaning":"最具爭議性之一","examples":[{"en":"The debate surrounding literacy is one of the most charged in education.","zh":"圍繞讀寫能力的辯論是教育界最具爭議性的辯論之一。"},{"en":"One of the most charged means one of the most emotional, controversial, or intense.","zh":"One of the most charged 指最情緒化、最具爭議或最激烈之一。"},{"en":"School admissions can be one of the most charged issues for parents.","zh":"學校收生可以是家長最激烈討論的議題之一。"},{"en":"A topic becomes charged when people connect it with fairness, identity, or children’s future.","zh":"當人們把某主題與公平、身份或兒童未來連在一起，它便會變得具爭議。"},{"en":"This phrase shows that a debate is not calm or neutral.","zh":"這個片語顯示辯論並不平靜或中立。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":2},{"front":"in education","meaning":"在教育界","examples":[{"en":"Literacy remains a major issue in education.","zh":"讀寫能力在教育界仍是重大議題。"},{"en":"In education means in the field of teaching, learning, schools, and training.","zh":"In education 指在教學、學習、學校和培訓領域中。"},{"en":"Technology use in education can help students if teachers give clear guidance.","zh":"如果老師提供清晰指導，教育界中的科技使用可以幫助學生。"},{"en":"Problems in education often affect later work, income, and social participation.","zh":"教育界中的問題常影響日後工作、收入和社會參與。"},{"en":"This phrase locates an issue within the world of learning and schooling.","zh":"這個片語把某議題放在學習和學校世界中。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":2},{"front":"on the one hand","meaning":"一方面","examples":[{"en":"On the one hand, some people believe traditional literacy skills are declining.","zh":"一方面，有些人認為傳統讀寫技能正在下降。"},{"en":"On the one hand introduces one side of a comparison or argument.","zh":"On the one hand 用來引出比較或論證的一方。"},{"en":"On the one hand, online classes are convenient; on the other hand, students may feel isolated.","zh":"一方面，網上課堂很方便；另一方面，學生可能感到孤立。"},{"en":"Writers use this phrase when they want to present more than one viewpoint.","zh":"作者想呈現多於一個觀點時，會使用這個片語。"},{"en":"This phrase prepares the reader for a contrasting point later.","zh":"這個片語讓讀者準備接收之後的對比觀點。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":2},{"front":"an army of people","meaning":"一大批人","examples":[{"en":"There is an army of people convinced that reading and writing are declining.","zh":"有一大批人堅信閱讀和寫作正在衰退。"},{"en":"An army of people means a very large number of people.","zh":"An army of people 指非常大量的人。"},{"en":"An army of parents may complain if a school suddenly changes its timetable.","zh":"如果學校突然更改時間表，可能有一大批家長投訴。"},{"en":"When an army of people shares the same worry, the debate becomes harder to ignore.","zh":"當一大批人有同樣憂慮，這場辯論便更難被忽視。"},{"en":"This phrase is figurative and emphasises a large group, not real soldiers.","zh":"這個片語是比喻，強調一大群人，而不是真正士兵。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":2},{"front":"be convinced that","meaning":"堅信","examples":[{"en":"Many people are convinced that traditional literacy skills are declining.","zh":"許多人堅信傳統讀寫技能正在下降。"},{"en":"To be convinced that something is true means to strongly believe it.","zh":"To be convinced that something is true 指強烈相信某事是真的。"},{"en":"A parent may be convinced that screen time hurts learning after seeing poor exam results.","zh":"家長看見成績差後，可能堅信屏幕時間損害學習。"},{"en":"People may become convinced by personal experience even before full evidence appears.","zh":"即使完整證據尚未出現，人們也可能被個人經驗說服。"},{"en":"This phrase describes strong belief, not necessarily proven fact.","zh":"這個片語描述強烈信念，而不一定是已證明事實。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":2},{"front":"traditional skills","meaning":"傳統技能","examples":[{"en":"Traditional skills of reading and writing are still valued in schools.","zh":"閱讀和寫作的傳統技能在學校中仍被重視。"},{"en":"Traditional skills are older, established abilities that people have long considered important.","zh":"Traditional skills 是長久以來被人認為重要的既有能力。"},{"en":"Handwriting, spelling, and reading printed texts are traditional skills in education.","zh":"書寫、串字和閱讀印刷文本是教育中的傳統技能。"},{"en":"New technology may change how traditional skills are taught, but it does not always replace them.","zh":"新科技可能改變傳統技能如何被教授，但不一定取代它們。"},{"en":"This phrase often contrasts older abilities with newer digital skills.","zh":"這個片語常把舊能力與新的數碼技能作對比。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":2},{"front":"reading and writing","meaning":"讀寫","examples":[{"en":"The debate focuses on the changing importance of reading and writing.","zh":"這場辯論集中於讀寫重要性的改變。"},{"en":"Reading and writing are the basic skills of understanding written language and producing written language.","zh":"Reading and writing 是理解書面語和產生書面語的基本技能。"},{"en":"Students practise reading and writing when they study articles and write essays.","zh":"學生研讀文章和寫作文時，就是練習讀寫。"},{"en":"If reading and writing weaken, people may struggle with school, work, and public information.","zh":"如果讀寫能力變弱，人們可能在學校、工作和公共資訊方面遇到困難。"},{"en":"This phrase names the core skills traditionally linked with literacy.","zh":"這個片語命名傳統上與讀寫能力相關的核心技能。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":2},{"front":"be declining","meaning":"正在下降；日漸衰退","examples":[{"en":"Some people believe that reading and writing skills are declining.","zh":"有些人認為閱讀和寫作技能正在下降。"},{"en":"To be declining means to be becoming weaker, lower, or less common.","zh":"To be declining 指正在變弱、降低或變得較少見。"},{"en":"A student’s concentration may be declining if they sleep badly for many weeks.","zh":"如果學生連續多星期睡得差，專注力可能正在下降。"},{"en":"If vocabulary is declining in newspapers, texts may become simpler over time.","zh":"如果報章詞彙正在下降，文本可能隨時間變得較簡單。"},{"en":"This phrase describes a downward trend.","zh":"這個片語描述下降趨勢。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":2},{"front":"on the other","meaning":"另一方面","examples":[{"en":"On the other, progressives argue that literacy is more complicated.","zh":"另一方面，進步派人士認為讀寫能力更複雜。"},{"en":"On the other is a shortened form of “on the other hand”, introducing the contrasting side.","zh":"On the other 是 “on the other hand” 的縮略形式，用來引出相反一方。"},{"en":"Some parents want stricter tests; on the other, teachers may want broader assessment.","zh":"有些家長想要更嚴格測驗；另一方面，老師可能想要更廣泛評估。"},{"en":"This phrase helps present two opposing viewpoints in a balanced discussion.","zh":"這個片語有助在平衡討論中呈現兩個相反觀點。"},{"en":"It is usually paired with “on the one hand” earlier.","zh":"它通常與前面的 “on the one hand” 配合使用。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":2},{"front":"a host of","meaning":"大量；許多","examples":[{"en":"A host of progressives reject a narrow view of literacy.","zh":"大量進步派人士拒絕對讀寫能力的狹窄看法。"},{"en":"A host of means a large number of people or things.","zh":"A host of 指大量的人或事物。"},{"en":"A host of parents may support later school start times if students are tired.","zh":"如果學生疲倦，許多家長可能支持延遲上學時間。"},{"en":"When a host of experts agree, an idea gains more influence.","zh":"當大量專家同意，一個想法便更具影響力。"},{"en":"This phrase is similar to “many”, but slightly more formal.","zh":"這個片語類似 “many”，但稍為正式。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":2},{"front":"progressives","meaning":"進步派人士","examples":[{"en":"Progressives argue that literacy involves more than basic technical skills.","zh":"進步派人士認為讀寫能力不只是基本技術技能。"},{"en":"Progressives are people who support new ideas, reform, and broader social change.","zh":"Progressives 是支持新想法、改革和更廣泛社會改變的人。"},{"en":"In education, progressives may support creative learning instead of only exams.","zh":"在教育界，進步派人士可能支持創意學習，而不只是考試。"},{"en":"Progressives may challenge old definitions when society and technology change.","zh":"當社會和科技改變，進步派人士可能挑戰舊定義。"},{"en":"This word describes people who favour reform rather than tradition alone.","zh":"這個詞描述傾向改革，而不只是傳統的人。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":3},{"front":"protest that","meaning":"反駁說；抗議說","examples":[{"en":"Progressives protest that literacy is more complicated than simple reading and writing.","zh":"進步派人士反駁說，讀寫能力比簡單閱讀和寫作更複雜。"},{"en":"To protest that something is true means to argue strongly against another view.","zh":"To protest that something is true 指強烈反駁另一個觀點。"},{"en":"Teachers may protest that exam scores do not show the whole ability of a student.","zh":"老師可能反駁說考試分數不能展示學生的全部能力。"},{"en":"People protest when they believe a simple claim is unfair or inaccurate.","zh":"當人們認為簡單說法不公平或不準確時，便會反駁。"},{"en":"This phrase introduces strong disagreement.","zh":"這個片語引出強烈不同意。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":3},{"front":"much more complicated than","meaning":"比……複雜得多","examples":[{"en":"Literacy is much more complicated than a simple technical skill.","zh":"讀寫能力比一項簡單技術技能複雜得多。"},{"en":"Much more complicated than means far less simple than something else.","zh":"Much more complicated than 指遠比另一事物不簡單。"},{"en":"Learning a language is much more complicated than memorising a word list.","zh":"學習語言比背單詞表複雜得多。"},{"en":"If a problem is much more complicated than it seems, simple solutions may fail.","zh":"如果問題比表面看來複雜得多，簡單方案可能失敗。"},{"en":"This phrase stresses a large difference in complexity.","zh":"這個片語強調複雜程度上的巨大差異。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":3},{"front":"technical mastery of","meaning":"對……的技術性掌握","examples":[{"en":"Literacy is not just the technical mastery of reading and writing.","zh":"讀寫能力不只是對閱讀和寫作的技術性掌握。"},{"en":"Technical mastery of something means having the practical skills to do it correctly.","zh":"Technical mastery of something 指具備正確完成某事的實用技能。"},{"en":"A pianist needs technical mastery of scales before playing difficult music.","zh":"鋼琴家在演奏困難音樂前，需要對音階有技術性掌握。"},{"en":"Reading words correctly is useful, but literacy also requires judgement and context.","zh":"正確讀出文字有用，但讀寫能力也需要判斷和背景理解。"},{"en":"This phrase focuses on skill and technique, not deeper understanding alone.","zh":"這個片語著重技能和技術，而不只是深層理解。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":3},{"front":"be supported by","meaning":"得到……支持","examples":[{"en":"This second position is supported by most relevant academic work.","zh":"第二種立場得到大多數相關學術研究支持。"},{"en":"To be supported by something means to have evidence, reasons, or backing from it.","zh":"To be supported by something 指有來自某事的證據、理由或支持。"},{"en":"A school policy is stronger when it is supported by research and classroom experience.","zh":"如果學校政策得到研究和課堂經驗支持，它會更有力。"},{"en":"If a claim is supported by many studies, it becomes more convincing.","zh":"如果一項主張得到許多研究支持，它會更有說服力。"},{"en":"This phrase links an idea with evidence behind it.","zh":"這個片語把想法與背後證據連接起來。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":3},{"front":"relevant academic work","meaning":"相關學術研究","examples":[{"en":"Relevant academic work supports a broader view of literacy.","zh":"相關學術研究支持對讀寫能力更廣闊的看法。"},{"en":"Relevant academic work means scholarly research that directly relates to the topic.","zh":"Relevant academic work 指與該主題直接相關的學術研究。"},{"en":"A teacher writing about homework should look at relevant academic work on learning and stress.","zh":"老師寫關於功課的文章時，應查看關於學習和壓力的相關學術研究。"},{"en":"Academic work can challenge popular opinions by providing evidence and analysis.","zh":"學術研究可以透過提供證據和分析，挑戰流行觀點。"},{"en":"This phrase refers to research, not casual opinions.","zh":"這個片語指研究，而不是隨便意見。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":3},{"front":"over the past 20 years","meaning":"在過去20年裏","examples":[{"en":"Academic work over the past 20 years supports this view.","zh":"在過去20年裏，學術研究支持這個看法。"},{"en":"Over the past 20 years means during the last twenty years.","zh":"Over the past 20 years 指在過去二十年間。"},{"en":"Over the past 20 years, phones have changed how people read, write, and communicate.","zh":"在過去20年裏，手機改變了人們閱讀、寫作和溝通的方式。"},{"en":"Research collected over many years can reveal long-term patterns.","zh":"多年累積的研究可以揭示長期模式。"},{"en":"This phrase places evidence within a recent historical period.","zh":"這個片語把證據放在近期歷史時期中。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":3},{"front":"argue that","meaning":"主張；認為","examples":[{"en":"These studies argue that literacy must be understood in context.","zh":"這些研究主張讀寫能力必須在背景下理解。"},{"en":"To argue that something is true means to give reasons for that view.","zh":"To argue that something is true 指提出理由支持某看法。"},{"en":"Some teachers argue that students learn grammar better through real examples.","zh":"有些老師認為學生透過真實例子能更好學文法。"},{"en":"Researchers argue a point when they believe evidence supports it.","zh":"當研究人員相信證據支持某觀點，他們便會提出該主張。"},{"en":"This phrase introduces a reasoned claim, not just a personal feeling.","zh":"這個片語引出有理由支持的主張，而不只是個人感受。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":3},{"front":"be understood in context","meaning":"在背景下理解","examples":[{"en":"Literacy can only be understood in its social and technical context.","zh":"讀寫能力只能在其社會及技術背景下理解。"},{"en":"To be understood in context means to be interpreted with its background, situation, and surroundings.","zh":"To be understood in context 指連同其背景、情況和周圍環境來理解。"},{"en":"A student’s weak writing should be understood in context, such as language background and reading habits.","zh":"學生寫作薄弱應在背景下理解，例如語言背景和閱讀習慣。"},{"en":"If we ignore context, we may judge skills too simply or unfairly.","zh":"如果忽視背景，我們可能過度簡化或不公平地評價技能。"},{"en":"This phrase shows that meaning depends on the situation around it.","zh":"這個片語顯示意思取決於周圍情況。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":3},{"front":"social and technical context","meaning":"社會及技術背景","examples":[{"en":"Literacy should be understood in its social and technical context.","zh":"讀寫能力應在其社會及技術背景下理解。"},{"en":"Social and technical context means the society, tools, media, and technologies surrounding an activity.","zh":"Social and technical context 指圍繞某活動的社會、工具、媒體和科技。"},{"en":"Writing a letter in the past and sending a text today happen in different social and technical contexts.","zh":"過去寫信和今天發短訊發生在不同社會及技術背景中。"},{"en":"When technology changes, the context of reading and writing also changes.","zh":"當科技改變，閱讀和寫作的背景也會改變。"},{"en":"This phrase explains why literacy is not the same in every period.","zh":"這個片語解釋為何讀寫能力在每個時期並不相同。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":3},{"front":"Renaissance England","meaning":"文藝復興時期的英格蘭","examples":[{"en":"Renaissance England had different levels of reading and writing ability.","zh":"文藝復興時期的英格蘭有不同程度的閱讀和寫作能力。"},{"en":"Renaissance England refers to England during the Renaissance period, when culture, learning, and print developed.","zh":"Renaissance England 指文藝復興時期的英格蘭，當時文化、學問和印刷有所發展。"},{"en":"In Renaissance England, some people could read printed texts but not handwritten documents.","zh":"在文藝復興時期的英格蘭，有些人能閱讀印刷文字，但不能閱讀手寫文件。"},{"en":"Historical examples from Renaissance England show that literacy has never been simple.","zh":"文藝復興時期英格蘭的歷史例子顯示，讀寫能力從來不簡單。"},{"en":"This phrase places the discussion in an earlier historical society.","zh":"這個片語把討論放在較早的歷史社會中。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":4},{"front":"for example","meaning":"例如","examples":[{"en":"For example, many more people could read than could write.","zh":"例如，會閱讀的人比會寫作的人多很多。"},{"en":"For example introduces a specific case that explains or supports a general point.","zh":"For example 用來引出解釋或支持一般重點的具體例子。"},{"en":"Some students learn better through sound; for example, they may remember words after hearing them.","zh":"有些學生透過聲音學得更好；例如，他們聽到詞語後可能記得它們。"},{"en":"Examples help readers understand abstract ideas more clearly.","zh":"例子幫助讀者更清楚理解抽象想法。"},{"en":"This phrase signals that a concrete illustration is coming.","zh":"這個片語標示接下來會有具體說明。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":4},{"front":"many more people could read than could write","meaning":"會閱讀的人比會寫作的人多很多","examples":[{"en":"In Renaissance England, many more people could read than could write.","zh":"在文藝復興時期的英格蘭，會閱讀的人比會寫作的人多很多。"},{"en":"This means reading ability was more common than writing ability.","zh":"這意思是閱讀能力比寫作能力更普遍。"},{"en":"A child may learn to read signs before they can write full sentences.","zh":"孩子可能先學會閱讀標誌，然後才會寫完整句子。"},{"en":"If reading and writing develop separately, literacy cannot be judged as one simple skill.","zh":"如果閱讀和寫作分開發展，讀寫能力就不能被視為單一簡單技能。"},{"en":"This phrase shows that different literacy skills may not appear together.","zh":"這個片語顯示不同讀寫技能未必同時出現。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":4},{"front":"there was a distinction between","meaning":"……之間有區別","examples":[{"en":"There was a distinction between reading print and reading manuscript.","zh":"閱讀印刷文字和閱讀手稿之間有區別。"},{"en":"There was a distinction between two things means they were treated as different.","zh":"There was a distinction between two things 指兩者被視為不同。"},{"en":"There is a distinction between understanding a word and being able to use it naturally.","zh":"理解一個詞和能自然使用它之間有區別。"},{"en":"If two skills are different, students may be strong in one but weak in the other.","zh":"如果兩項技能不同，學生可能一項強、一項弱。"},{"en":"This phrase helps separate similar but not identical ideas.","zh":"這個片語幫助區分相似但不相同的想法。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":4},{"front":"read print","meaning":"閱讀印刷文字","examples":[{"en":"Some people in Renaissance England could read print.","zh":"文藝復興時期英格蘭有些人能閱讀印刷文字。"},{"en":"To read print means to read printed words in books, newspapers, notices, or other printed materials.","zh":"To read print 指閱讀書籍、報紙、告示或其他印刷材料中的印刷文字。"},{"en":"A child who can read print may understand a simple storybook.","zh":"能閱讀印刷文字的孩子可能理解簡單故事書。"},{"en":"Reading print can be easier than reading messy handwriting because the letters are standardised.","zh":"閱讀印刷文字可能比閱讀凌亂手寫字容易，因為字母較標準化。"},{"en":"This phrase refers to reading printed text rather than handwriting or screens.","zh":"這個片語指閱讀印刷文本，而不是手寫字或屏幕。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":4},{"front":"manage the more difficult task of","meaning":"應付較困難的任務","examples":[{"en":"Some readers could manage the more difficult task of reading manuscript.","zh":"有些讀者能應付閱讀手稿這項較困難的任務。"},{"en":"To manage the more difficult task of something means to succeed in doing a harder activity.","zh":"To manage the more difficult task of something 指成功完成較困難的活動。"},{"en":"A strong student may manage the more difficult task of explaining an answer to classmates.","zh":"能力強的學生可能能應付向同學解釋答案這項較困難的任務。"},{"en":"If learners can manage harder tasks, they show deeper skill and confidence.","zh":"如果學習者能應付較難任務，便顯示更深技能和信心。"},{"en":"This phrase highlights ability under greater difficulty.","zh":"這個片語突顯在更大困難下的能力。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":4},{"front":"reading manuscript","meaning":"閱讀手稿","examples":[{"en":"Reading manuscript was more difficult than reading print.","zh":"閱讀手稿比閱讀印刷文字更困難。"},{"en":"Reading manuscript means reading handwritten text rather than printed text.","zh":"Reading manuscript 指閱讀手寫文本，而不是印刷文本。"},{"en":"Students may find reading manuscript difficult if the handwriting is old, unclear, or irregular.","zh":"如果字跡古老、不清楚或不規則，學生可能覺得閱讀手稿困難。"},{"en":"Before standard printing was common, reading manuscript required more practice and familiarity.","zh":"在標準印刷普及之前，閱讀手稿需要更多練習和熟悉度。"},{"en":"This phrase shows that not all reading tasks are equally easy.","zh":"這個片語顯示並非所有閱讀任務都同樣容易。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":4},{"front":"an understanding of","meaning":"對……的理解","examples":[{"en":"An understanding of earlier periods helps us understand today’s debate.","zh":"對較早時期的理解有助我們理解今天的辯論。"},{"en":"An understanding of something means knowledge of how it works, why it matters, and what it involves.","zh":"An understanding of something 指知道某事如何運作、為何重要和涉及甚麼。"},{"en":"An understanding of grammar helps students write clearer sentences.","zh":"對文法的理解幫助學生寫出更清晰句子。"},{"en":"If people understand history, they may avoid judging today’s problems too simply.","zh":"如果人們理解歷史，可能避免過度簡化地判斷今天問題。"},{"en":"This phrase describes more than knowing facts; it means seeing meaning and connections.","zh":"這個片語不只是知道事實，而是看見意義和關聯。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":4},{"front":"earlier periods","meaning":"較早時期","examples":[{"en":"Earlier periods show that literacy has always been complex.","zh":"較早時期顯示讀寫能力一直很複雜。"},{"en":"Earlier periods are times in history before the present or before the period being discussed.","zh":"Earlier periods 是現在之前或所討論時期之前的歷史時段。"},{"en":"Earlier periods of education often used fewer digital tools than schools use today.","zh":"較早時期的教育通常比今天學校使用較少數碼工具。"},{"en":"Looking at earlier periods helps us see that modern problems may have older roots.","zh":"觀察較早時期有助我們看見現代問題可能有更早根源。"},{"en":"This phrase places evidence in the past.","zh":"這個片語把證據放在過去。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":4},{"front":"crisis in literacy","meaning":"讀寫能力危機","examples":[{"en":"The passage questions today’s crisis in literacy debate.","zh":"文章質疑今天關於讀寫能力危機的辯論。"},{"en":"A crisis in literacy is a serious concern that people’s reading and writing abilities are too weak.","zh":"Crisis in literacy 是指人們閱讀和寫作能力太弱的嚴重憂慮。"},{"en":"A country may speak of a crisis in literacy if many students cannot understand basic texts.","zh":"如果許多學生不能理解基本文本，一個國家可能談論讀寫能力危機。"},{"en":"If the crisis is exaggerated, schools may choose the wrong solutions.","zh":"如果危機被誇大，學校可能選擇錯誤方案。"},{"en":"This phrase describes a public worry about reading and writing standards.","zh":"這個片語描述關於閱讀和寫作標準的公共憂慮。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":4},{"front":"literacy debate","meaning":"讀寫能力辯論","examples":[{"en":"The literacy debate is shaped by historical examples.","zh":"讀寫能力辯論受到歷史例子塑造。"},{"en":"The literacy debate is the public discussion about what literacy means and whether it is improving or declining.","zh":"Literacy debate 是關於讀寫能力是甚麼，以及它是改善還是下降的公共討論。"},{"en":"Teachers, parents, researchers, and media workers may all join the literacy debate.","zh":"老師、家長、研究人員和媒體工作者都可能參與讀寫能力辯論。"},{"en":"Historical examples can make the literacy debate less simplistic.","zh":"歷史例子可以令讀寫能力辯論不那麼簡化。"},{"en":"This phrase refers to arguments about reading, writing, media, and education.","zh":"這個片語指關於閱讀、寫作、媒體和教育的爭論。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":5},{"front":"there does seem to be evidence that","meaning":"似乎確有證據顯示","examples":[{"en":"There does seem to be evidence that some reading and writing skills have declined.","zh":"似乎確有證據顯示某些閱讀和寫作技能有所下降。"},{"en":"This phrase means the writer cautiously accepts that some evidence supports the claim.","zh":"這個片語意思是作者謹慎承認有些證據支持該主張。"},{"en":"There does seem to be evidence that students sleep less when exams are near.","zh":"似乎確有證據顯示學生在考試臨近時睡得較少。"},{"en":"The word “seem” makes the claim careful rather than absolute.","zh":"“Seem” 令主張較謹慎，而不是絕對。"},{"en":"This phrase is useful when evidence exists but the conclusion is still limited.","zh":"當證據存在但結論仍有限時，這個片語很有用。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":5},{"front":"overall decline in","meaning":"……的整體下降","examples":[{"en":"There has been an overall decline in some aspects of literacy.","zh":"讀寫能力某些方面出現了整體下降。"},{"en":"An overall decline in something is a general decrease across a broad area.","zh":"Overall decline in something 指某範圍整體上下降。"},{"en":"A school may see an overall decline in attendance during flu season.","zh":"流感季期間，學校可能出現出席率整體下降。"},{"en":"An overall decline does not mean every single person or skill has worsened.","zh":"整體下降不代表每個人或每項技能都變差。"},{"en":"This phrase describes a broad downward trend.","zh":"這個片語描述廣泛下降趨勢。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":5},{"front":"some aspects of","meaning":"……的某些方面","examples":[{"en":"The decline affects some aspects of reading and writing.","zh":"下降影響閱讀和寫作的某些方面。"},{"en":"Some aspects of something are certain parts or features of it, not the whole thing.","zh":"Some aspects of something 指某事的某些部分或特徵，而不是整體。"},{"en":"A student may be strong in grammar but weak in some aspects of speaking.","zh":"學生可能文法強，但口語某些方面較弱。"},{"en":"If only some aspects decline, the full picture is more complex.","zh":"如果只有某些方面下降，整體情況便更複雜。"},{"en":"This phrase helps avoid overgeneralising.","zh":"這個片語有助避免過度概括。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":5},{"front":"tabloid newspapers","meaning":"小報；通俗報章","examples":[{"en":"The writer compares today’s tabloid newspapers with those of 50 years ago.","zh":"作者把今天的小報與50年前的小報作比較。"},{"en":"Tabloid newspapers are popular newspapers that often use short articles, large headlines, and simple language.","zh":"Tabloid newspapers 是常使用短文章、大標題和簡單語言的通俗報章。"},{"en":"A tabloid newspaper may focus on celebrities, crime, sport, and dramatic stories.","zh":"小報可能集中於名人、罪案、體育和戲劇化故事。"},{"en":"If tabloids use fewer words than before, they may show changes in public reading habits.","zh":"如果小報使用的詞比以前少，可能顯示公眾閱讀習慣的變化。"},{"en":"This phrase refers to a type of newspaper, not all newspapers.","zh":"這個片語指一種報章，而不是所有報章。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":5},{"front":"a clear decrease in","meaning":"……明顯減少","examples":[{"en":"The comparison shows a clear decrease in vocabulary.","zh":"這種比較顯示詞彙明顯減少。"},{"en":"A clear decrease in something means an obvious reduction in amount, level, or variety.","zh":"Clear decrease in something 指數量、水平或種類有明顯下降。"},{"en":"A teacher may notice a clear decrease in homework quality when students are tired.","zh":"當學生疲倦，老師可能注意到功課質素明顯下降。"},{"en":"If newspapers show a clear decrease in vocabulary, their language has become simpler.","zh":"如果報章顯示詞彙明顯減少，它們的語言便變得較簡單。"},{"en":"This phrase describes a reduction that is easy to see.","zh":"這個片語描述容易看見的減少。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":5},{"front":"vocabulary","meaning":"詞彙","examples":[{"en":"Modern tabloids show a decrease in vocabulary.","zh":"現代小報顯示詞彙減少。"},{"en":"Vocabulary is the set of words a person, text, or language uses.","zh":"Vocabulary 是一個人、一篇文本或一種語言所使用的一組詞語。"},{"en":"Reading widely can help students build richer vocabulary.","zh":"廣泛閱讀可以幫助學生建立更豐富的詞彙。"},{"en":"If a newspaper uses limited vocabulary, readers meet fewer new words.","zh":"如果報章使用有限詞彙，讀者接觸到的新詞會較少。"},{"en":"This word is central to reading, writing, and language learning.","zh":"這個詞是閱讀、寫作和語言學習的核心。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":5},{"front":"simplification of syntax","meaning":"句法簡化","examples":[{"en":"The writer notes a simplification of syntax in modern newspapers.","zh":"作者指出現代報章出現句法簡化。"},{"en":"Simplification of syntax means sentence structure becomes simpler and less complex.","zh":"Simplification of syntax 指句子結構變得較簡單、不那麼複雜。"},{"en":"Children’s books often use simplification of syntax so young readers can follow the story.","zh":"兒童書常使用句法簡化，讓年幼讀者能跟上故事。"},{"en":"If newspapers simplify syntax too much, readers may see fewer complex sentence patterns.","zh":"如果報章過度簡化句法，讀者可能接觸到較少複雜句式。"},{"en":"This phrase describes a change in how sentences are built.","zh":"這個片語描述句子如何構成的改變。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":5},{"front":"syntax","meaning":"句法","examples":[{"en":"Newspapers today may use simpler syntax than before.","zh":"今天的報章可能比以前使用較簡單句法。"},{"en":"Syntax is the way words are arranged to form phrases and sentences.","zh":"Syntax 是詞語如何排列成片語和句子的方式。"},{"en":"In English, syntax helps decide whether we say “the big house” or “house big”.","zh":"在英文中，句法幫助決定我們說 “the big house” 而不是 “house big”。"},{"en":"Complex syntax can make writing richer but also harder to read.","zh":"複雜句法可以令寫作更豐富，但也更難閱讀。"},{"en":"This word refers to sentence structure, not vocabulary meaning.","zh":"這個詞指句子結構，而不是詞彙意思。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":5},{"front":"the picture is not uniform","meaning":"情況並不一致","examples":[{"en":"The picture is not uniform, so the situation is complex.","zh":"情況並不一致，所以局面很複雜。"},{"en":"The picture is not uniform means the evidence does not show the same pattern everywhere.","zh":"The picture is not uniform 指證據並非到處顯示同一模式。"},{"en":"In one class, reading may improve, while in another it may fall; the picture is not uniform.","zh":"一個班的閱讀可能進步，另一個班可能下降；情況並不一致。"},{"en":"If the picture is not uniform, simple claims like “literacy is collapsing” may be misleading.","zh":"如果情況並不一致，「讀寫能力正在崩潰」這類簡單說法可能具誤導性。"},{"en":"This phrase warns that the situation has mixed results.","zh":"這個片語提醒人，情況有混合結果。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":5},{"front":"readily demonstrate","meaning":"容易顯示","examples":[{"en":"The evidence does not readily demonstrate a simple division.","zh":"證據並不容易顯示一種簡單區分。"},{"en":"To readily demonstrate something means to show it easily and clearly.","zh":"To readily demonstrate something 指容易而清楚地顯示某事。"},{"en":"Test scores do not readily demonstrate a student’s creativity.","zh":"測驗分數不容易顯示學生的創意。"},{"en":"If evidence does not readily demonstrate a claim, more careful analysis is needed.","zh":"如果證據不容易顯示某主張，便需要更仔細分析。"},{"en":"This phrase is often used to say that a conclusion is not easy to prove.","zh":"這個片語常用來表示某結論不容易證明。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":6},{"front":"simple distinction between","meaning":"……之間的簡單區分","examples":[{"en":"The old simple distinction between literate and illiterate is inadequate.","zh":"有讀寫能力與文盲之間的舊式簡單區分並不足夠。"},{"en":"A simple distinction between two things is a basic division that treats them as separate categories.","zh":"Simple distinction between two things 是把兩者視為分開類別的基本區分。"},{"en":"The simple distinction between good students and bad students ignores effort, confidence, and support.","zh":"好學生和差學生之間的簡單區分忽視努力、信心和支援。"},{"en":"If real life is complex, a simple distinction may hide important differences.","zh":"如果現實生活複雜，簡單區分可能隱藏重要差異。"},{"en":"This phrase describes a basic contrast that may be too crude.","zh":"這個片語描述可能過於粗略的基本對比。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":6},{"front":"literate and illiterate","meaning":"有讀寫能力與文盲的","examples":[{"en":"The distinction between literate and illiterate is no longer simple.","zh":"有讀寫能力與文盲之間的區分已不再簡單。"},{"en":"Literate and illiterate describe people with and without reading and writing ability.","zh":"Literate and illiterate 描述有讀寫能力和沒有讀寫能力的人。"},{"en":"A person may be literate in everyday messages but struggle with legal documents.","zh":"一個人可能能閱讀日常訊息，但難以理解法律文件。"},{"en":"Modern media make the line between literate and illiterate harder to draw.","zh":"現代媒體令有讀寫能力與文盲之間的界線更難劃定。"},{"en":"This phrase contrasts two literacy categories, though real skills may lie between them.","zh":"這個片語對比兩種讀寫能力類別，但真實技能可能介乎兩者之間。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":6},{"front":"be considered adequate","meaning":"被認為足夠","examples":[{"en":"The old distinction had been considered adequate since the 19th century.","zh":"這種舊區分自19世紀以來一直被認為足夠。"},{"en":"To be considered adequate means to be judged good enough for a purpose.","zh":"To be considered adequate 指被判斷為足以達到某目的。"},{"en":"A short answer may be considered adequate if it directly answers the question.","zh":"如果短答案直接回答問題，可能被認為足夠。"},{"en":"A definition that once seemed adequate may become weak when society changes.","zh":"當社會改變，曾經看似足夠的定義可能變得薄弱。"},{"en":"This phrase means “accepted as sufficient”, not “excellent”.","zh":"這個片語意思是「被接受為足夠」，而不是「優秀」。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":6},{"front":"since the middle of","meaning":"自……中期以來","examples":[{"en":"The distinction had been accepted since the middle of the 19th century.","zh":"這種區分自19世紀中期以來一直被接受。"},{"en":"Since the middle of a period means from the midpoint of that period until later.","zh":"Since the middle of a period 指從某時期中間開始直到之後。"},{"en":"The school has used the same uniform since the middle of the last decade.","zh":"學校自上個十年中期以來一直使用同一校服。"},{"en":"If an idea has been accepted since the middle of the 19th century, it has lasted a long time.","zh":"如果一個想法自19世紀中期以來一直被接受，它已持續很久。"},{"en":"This phrase marks when a long-lasting situation began.","zh":"這個片語標示長期情況從何時開始。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":6},{"front":"a certain amount of","meaning":"一定程度的……","examples":[{"en":"A certain amount of writing remains necessary in industrial societies.","zh":"在工業社會中，一定程度的寫作仍然必要。"},{"en":"A certain amount of something means some quantity, though not an exact number.","zh":"A certain amount of something 指某種數量，但不是精確數字。"},{"en":"A student needs a certain amount of quiet time to revise well.","zh":"學生需要一定程度的安靜時間才能好好溫習。"},{"en":"Even if people write less, a certain amount of writing is still needed for work and daily life.","zh":"即使人們寫得較少，工作和日常生活仍需要一定程度的寫作。"},{"en":"This phrase gives a limited but real quantity.","zh":"這個片語表示有限但真實存在的數量。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":6},{"front":"as crucial as they have ever been","meaning":"一如既往地重要","examples":[{"en":"Reading and writing are as crucial as they have ever been in some societies.","zh":"在一些社會中，閱讀和寫作一如既往地重要。"},{"en":"As crucial as they have ever been means just as important as at any earlier time.","zh":"As crucial as they have ever been 指與以往任何時候一樣重要。"},{"en":"Clear communication is as crucial as it has ever been in hospitals.","zh":"在醫院中，清晰溝通一如既往地重要。"},{"en":"Even with technology, reading instructions remains extremely important in many jobs.","zh":"即使有科技，在許多工作中閱讀指示仍然極其重要。"},{"en":"This phrase stresses that importance has not disappeared.","zh":"這個片語強調重要性並未消失。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":6},{"front":"industrial societies","meaning":"工業社會","examples":[{"en":"Reading and writing remain important in industrial societies.","zh":"閱讀和寫作在工業社會中仍然重要。"},{"en":"Industrial societies are societies where industry, factories, machines, and organised production play a major role.","zh":"Industrial societies 是工業、工廠、機器和有組織生產扮演重要角色的社會。"},{"en":"In industrial societies, workers often need to read manuals, safety rules, and forms.","zh":"在工業社會中，工人常需要閱讀手冊、安全規則和表格。"},{"en":"Reading and writing support complex work systems in industrial economies.","zh":"閱讀和寫作支援工業經濟中的複雜工作制度。"},{"en":"This phrase contrasts with farming-based societies.","zh":"這個片語與以農業為本的社會形成對比。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":6},{"front":"it is doubtful whether","meaning":"是否……令人懷疑","examples":[{"en":"It is doubtful whether fully developed reading and writing skills are as necessary as before.","zh":"充分發展的閱讀和寫作技能是否像以前一樣必要，令人懷疑。"},{"en":"It is doubtful whether means it is uncertain or open to question.","zh":"It is doubtful whether 指某事不確定或值得質疑。"},{"en":"It is doubtful whether extra homework alone can improve weak writing.","zh":"單靠額外功課是否能改善薄弱寫作，令人懷疑。"},{"en":"When society changes, old assumptions may become doubtful.","zh":"當社會改變，舊假設可能變得令人懷疑。"},{"en":"This phrase introduces uncertainty about a claim.","zh":"這個片語引出對某主張的不確定。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":6},{"front":"a fully developed grasp of","meaning":"對……的充分掌握","examples":[{"en":"A fully developed grasp of writing may be less necessary than it once was.","zh":"對寫作的充分掌握可能不如以往必要。"},{"en":"A fully developed grasp of something means a deep and complete understanding or ability.","zh":"A fully developed grasp of something 指對某事有深刻而完整的理解或能力。"},{"en":"A student with a fully developed grasp of grammar can use complex sentences accurately.","zh":"對文法有充分掌握的學生能準確使用複雜句子。"},{"en":"If a skill is less used in daily life, fewer people may develop a full grasp of it.","zh":"如果一項技能在日常生活中較少使用，較少人可能充分掌握它。"},{"en":"This phrase describes advanced ability, not basic knowledge.","zh":"這個片語描述高階能力，而不是基本知識。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":6},{"front":"as necessary as it was","meaning":"像以往一樣必要","examples":[{"en":"Writing fluent letters may not be as necessary as it was decades ago.","zh":"寫流暢書信可能不如數十年前那樣必要。"},{"en":"As necessary as it was means as needed or important as it used to be.","zh":"As necessary as it was 指像以前一樣需要或重要。"},{"en":"Memorising phone numbers is not as necessary as it was before smartphones.","zh":"背電話號碼不如智能手機出現前那樣必要。"},{"en":"If technology replaces a task, that task may become less necessary than before.","zh":"如果科技取代某任務，該任務可能不如以前必要。"},{"en":"This phrase compares present need with past need.","zh":"這個片語比較現在需要與過去需要。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":7},{"front":"print retains much of its authority","meaning":"印刷文字仍保有不少權威","examples":[{"en":"Print retains much of its authority as a source of information.","zh":"印刷文字作為資訊來源仍保有不少權威。"},{"en":"This means printed texts still keep a strong sense of trust and importance.","zh":"這意思是印刷文本仍保留強烈可信度和重要性。"},{"en":"Many people still trust printed textbooks more than random online posts.","zh":"許多人仍然比起隨機網上帖文更信任印刷教科書。"},{"en":"Even when screens are common, print may still feel official and reliable.","zh":"即使屏幕很普遍，印刷文字仍可能感覺正式而可靠。"},{"en":"This phrase shows that print has lost some power but not all of it.","zh":"這個片語顯示印刷文字失去了一些力量，但不是全部。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":7},{"front":"authority as a source of","meaning":"作為……來源的權威","examples":[{"en":"Print still has authority as a source of topical information.","zh":"印刷文字作為時事資料來源仍有權威。"},{"en":"Authority as a source of something means being trusted as a reliable provider of that information.","zh":"Authority as a source of something 指作為該資訊可靠提供者而受到信任。"},{"en":"A medical journal has authority as a source of health research.","zh":"醫學期刊作為健康研究來源具有權威。"},{"en":"If a source loses authority, readers may turn to television or online media instead.","zh":"如果某來源失去權威，讀者可能改看電視或網上媒體。"},{"en":"This phrase links trust with information.","zh":"這個片語把信任與資訊連接起來。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":7},{"front":"topical information","meaning":"時事資料","examples":[{"en":"Television has become an important source of topical information.","zh":"電視已成為時事資料的重要來源。"},{"en":"Topical information is current information about recent events or issues.","zh":"Topical information 是關於近期事件或議題的當前資訊。"},{"en":"News websites provide topical information about elections, weather, and public health.","zh":"新聞網站提供關於選舉、天氣和公共衛生的時事資料。"},{"en":"People often choose fast media when they want topical information immediately.","zh":"當人們想立即取得時事資料，常會選擇快速媒體。"},{"en":"This phrase refers to current affairs, not timeless knowledge.","zh":"這個片語指時事資訊，而不是永恆知識。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":7},{"front":"increasingly usurped this role","meaning":"日益取代這個角色","examples":[{"en":"Television has increasingly usurped the role once held by print.","zh":"電視日益取代曾由印刷文字擔當的角色。"},{"en":"To increasingly usurp a role means to gradually take over a position or function from something else.","zh":"To increasingly usurp a role 指逐漸從另一事物手中接管某位置或功能。"},{"en":"Messaging apps have increasingly usurped the role of handwritten notes among friends.","zh":"即時通訊應用程式在朋友之間日益取代手寫便條的角色。"},{"en":"If one medium becomes faster and more attractive, it may take over another medium’s role.","zh":"如果一種媒體變得更快、更吸引，它可能取代另一種媒體的角色。"},{"en":"This phrase suggests replacement, often with a sense of power being taken away.","zh":"這個片語暗示替代，而且常帶有權力被奪走的意味。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":7},{"front":"the ability to write fluent letters","meaning":"寫流暢書信的能力","examples":[{"en":"The ability to write fluent letters has been undermined by the telephone.","zh":"寫流暢書信的能力已被電話削弱。"},{"en":"The ability to write fluent letters means being able to write clear, smooth, and connected letters.","zh":"The ability to write fluent letters 指能寫出清晰、順暢而連貫書信的能力。"},{"en":"Before messaging apps, many people practised fluent letter-writing with relatives and friends.","zh":"在通訊應用程式出現前，許多人透過寫信給親友練習流暢書信寫作。"},{"en":"If people rarely write letters, this skill may weaken over time.","zh":"如果人們很少寫信，這項技能可能隨時間變弱。"},{"en":"This phrase refers to a specific traditional writing skill.","zh":"這個片語指一項特定傳統寫作技能。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":7},{"front":"be undermined by","meaning":"被……削弱","examples":[{"en":"Letter-writing has been undermined by the telephone.","zh":"書信寫作已被電話削弱。"},{"en":"To be undermined by something means to be weakened or made less important by it.","zh":"To be undermined by something 指被某事削弱或變得較不重要。"},{"en":"Students’ sleep can be undermined by late-night phone use.","zh":"學生睡眠可能被深夜使用手機削弱。"},{"en":"If a new tool replaces an old habit, the old skill may be undermined.","zh":"如果新工具取代舊習慣，舊技能可能被削弱。"},{"en":"This phrase describes gradual weakening rather than sudden destruction.","zh":"這個片語描述逐漸削弱，而不是突然摧毀。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":7},{"front":"research suggests that","meaning":"研究顯示","examples":[{"en":"Research suggests that many people write very little after school.","zh":"研究顯示，許多人離開學校後寫作很少。"},{"en":"Research suggests that means studies indicate something is probably true.","zh":"Research suggests that 指研究顯示某事很可能是真的。"},{"en":"Research suggests that children learn vocabulary better through repeated reading.","zh":"研究顯示，兒童透過反覆閱讀能更好學習詞彙。"},{"en":"This phrase is careful because it points to evidence without claiming absolute proof.","zh":"這個片語較謹慎，因為它指向證據而不聲稱絕對證明。"},{"en":"Writers use it when presenting findings in a cautious way.","zh":"作者在謹慎呈現研究結果時會使用它。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":7},{"front":"outside formal education","meaning":"在正規教育以外","examples":[{"en":"Outside formal education, many people write only shopping lists.","zh":"在正規教育以外，許多人只寫購物清單。"},{"en":"Outside formal education means outside schools, colleges, exams, and organised courses.","zh":"Outside formal education 指在學校、大學、考試和有組織課程以外。"},{"en":"After leaving school, some adults rarely write except for work forms or messages.","zh":"離開學校後，有些成年人除了工作表格或訊息外很少寫作。"},{"en":"If writing happens mostly inside formal education, people may write less in everyday life.","zh":"如果寫作主要發生在正規教育內，人們在日常生活中可能寫得較少。"},{"en":"This phrase contrasts school-based learning with daily life.","zh":"這個片語把學校學習與日常生活作對比。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":7},{"front":"the compilation of","meaning":"編寫；彙編","examples":[{"en":"Writing is often limited to the compilation of shopping lists.","zh":"寫作常限於編寫購物清單。"},{"en":"The compilation of something means putting items or information together into a list or collection.","zh":"The compilation of something 指把項目或資訊整理成清單或集合。"},{"en":"A teacher may ask for the compilation of useful vocabulary from a reading passage.","zh":"老師可能要求學生從閱讀文章中彙編有用詞彙。"},{"en":"If writing is reduced to compiling lists, people practise fewer complex sentences.","zh":"如果寫作縮減為編寫清單，人們練習複雜句子的機會會較少。"},{"en":"This phrase is formal and often refers to gathering information.","zh":"這個片語較正式，常指收集和整理資訊。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":7},{"front":"shopping lists","meaning":"購物清單","examples":[{"en":"For many people, writing outside school means making shopping lists.","zh":"對許多人來說，離開學校後寫作就是寫購物清單。"},{"en":"Shopping lists are lists of things people plan to buy.","zh":"Shopping lists 是人們打算購買物品的清單。"},{"en":"A family may write shopping lists before going to the supermarket.","zh":"家庭去超市前可能寫購物清單。"},{"en":"If someone writes only shopping lists, they may not practise longer forms of writing.","zh":"如果某人只寫購物清單，他們可能不會練習較長形式的寫作。"},{"en":"This phrase gives a simple example of everyday practical writing.","zh":"這個片語提供日常實用寫作的簡單例子。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":8},{"front":"car manufacturers","meaning":"汽車製造商","examples":[{"en":"Some car manufacturers issue instructions as video packs.","zh":"一些汽車製造商以影片套裝形式發出指示。"},{"en":"Car manufacturers are companies that design and produce cars.","zh":"Car manufacturers 是設計和生產汽車的公司。"},{"en":"Car manufacturers may give mechanics repair information in manuals or videos.","zh":"汽車製造商可能以手冊或影片向技工提供維修資訊。"},{"en":"If car manufacturers use videos instead of handbooks, reading may become less central to some tasks.","zh":"如果汽車製造商使用影片而不是手冊，閱讀在某些任務中可能變得較不核心。"},{"en":"This phrase names businesses involved in making vehicles.","zh":"這個片語命名製造車輛的企業。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":8},{"front":"issue instructions to","meaning":"向……發出指示","examples":[{"en":"Car manufacturers may issue instructions to mechanics in video form.","zh":"汽車製造商可能以影片形式向技工發出指示。"},{"en":"To issue instructions to someone means to officially give them directions about what to do.","zh":"To issue instructions to someone 指正式向某人提供該做甚麼的指示。"},{"en":"A school may issue instructions to students before a fire drill.","zh":"學校可能在消防演習前向學生發出指示。"},{"en":"If instructions are issued clearly, workers are less likely to make mistakes.","zh":"如果指示發出得清楚，工人較少可能犯錯。"},{"en":"This phrase is often used in formal or workplace situations.","zh":"這個片語常用於正式或工作場合。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":8},{"front":"mechanics","meaning":"機械維修員；技工","examples":[{"en":"Some instructions for mechanics are now provided as videos.","zh":"一些給技工的指示現在以影片形式提供。"},{"en":"Mechanics are workers who repair and maintain machines, especially vehicles.","zh":"Mechanics 是維修和保養機器，尤其是車輛的工人。"},{"en":"A mechanic may use a video guide to learn how to replace a car part.","zh":"技工可能使用影片指南學習如何更換汽車零件。"},{"en":"If instructions are visual, mechanics may need less written explanation for some tasks.","zh":"如果指示是視覺化的，技工在某些任務中可能需要較少書面解釋。"},{"en":"This word refers to technical repair workers.","zh":"這個詞指技術維修工人。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":8},{"front":"video pack","meaning":"影片套裝","examples":[{"en":"A video pack may replace a written handbook.","zh":"影片套裝可能取代書面手冊。"},{"en":"A video pack is a set of videos that explains information or instructions.","zh":"Video pack 是一組用來解釋資訊或指示的影片。"},{"en":"A company may give new staff a video pack showing safety rules.","zh":"公司可能給新員工一套展示安全規則的影片套裝。"},{"en":"Video packs can make practical steps easier to see than printed descriptions.","zh":"影片套裝可以令實際步驟比印刷描述更容易看見。"},{"en":"This phrase describes instruction through video rather than text alone.","zh":"這個片語描述透過影片而不只是文字進行指導。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":8},{"front":"rather than as","meaning":"而不是作為","examples":[{"en":"Some instructions are issued as a video pack rather than as a handbook.","zh":"一些指示以影片套裝形式發出，而不是作為手冊。"},{"en":"Rather than as means in one form instead of another form.","zh":"Rather than as 指以某種形式而不是另一種形式。"},{"en":"A teacher may give feedback as an audio recording rather than as written comments.","zh":"老師可能以錄音形式給回饋，而不是作為書面評語。"},{"en":"Choosing video rather than print can change what skills users need.","zh":"選擇影片而不是印刷文字，可以改變使用者所需技能。"},{"en":"This phrase clearly contrasts two formats.","zh":"這個片語清楚對比兩種形式。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":8},{"front":"handbook","meaning":"手冊","examples":[{"en":"A handbook may no longer be the main form of instruction.","zh":"手冊可能不再是主要指示形式。"},{"en":"A handbook is a small book or guide that gives information, rules, or instructions.","zh":"Handbook 是提供資訊、規則或指示的小書或指南。"},{"en":"New employees often receive a handbook explaining workplace policies.","zh":"新員工常收到一本解釋工作場所政策的手冊。"},{"en":"If videos replace handbooks, people may read fewer long instructions.","zh":"如果影片取代手冊，人們可能較少閱讀長篇指示。"},{"en":"This word refers to a written guide, usually for practical use.","zh":"這個詞指書面指南，通常用於實際用途。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":8},{"front":"be taken to","meaning":"被理解為","examples":[{"en":"This decision might be taken to signal a major change in literacy.","zh":"這個決定可能被理解為標誌讀寫能力的重大改變。"},{"en":"To be taken to mean something means to be understood or interpreted in that way.","zh":"To be taken to mean something 指被理解或詮釋為某意思。"},{"en":"A sudden resignation may be taken to show that a company has serious problems.","zh":"突然辭職可能被理解為公司有嚴重問題。"},{"en":"If a school removes textbooks, some may take it to mean print is losing power.","zh":"如果學校移除教科書，有些人可能把它理解為印刷文字正在失去力量。"},{"en":"This phrase describes interpretation, not necessarily the true intention.","zh":"這個片語描述詮釋，而不一定是真正意圖。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":8},{"front":"spell the end of","meaning":"預示……的終結","examples":[{"en":"Video instructions might spell the end of a link between industry and literacy.","zh":"影片指示可能預示工業與讀寫能力之間聯繫的終結。"},{"en":"To spell the end of something means to signal that it is likely to finish or disappear.","zh":"To spell the end of something 指預示某事很可能結束或消失。"},{"en":"Online banking may spell the end of some paper bank statements.","zh":"網上銀行可能預示某些紙本銀行結單的終結。"},{"en":"If videos replace written manuals, some traditional reading tasks may disappear.","zh":"如果影片取代書面手冊，一些傳統閱讀任務可能消失。"},{"en":"This phrase suggests a major ending caused by change.","zh":"這個片語暗示由變化造成的重大終結。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":8},{"front":"automatic link between","meaning":"……之間的必然聯繫","examples":[{"en":"The example challenges the automatic link between industrialisation and literacy.","zh":"這個例子挑戰工業化與讀寫能力之間的必然聯繫。"},{"en":"An automatic link between two things is an assumed connection that people do not question.","zh":"Automatic link between two things 是人們不加質疑地假設存在的聯繫。"},{"en":"Some people assume an automatic link between high grades and real understanding.","zh":"有些人假設高分與真正理解之間有必然聯繫。"},{"en":"If evidence challenges an automatic link, we need to examine the relationship more carefully.","zh":"如果證據挑戰必然聯繫，我們需要更仔細檢視兩者關係。"},{"en":"This phrase describes a connection treated as obvious, even if it may not be true.","zh":"這個片語描述被視為顯而易見，但未必真實的聯繫。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":8},{"front":"industrialisation","meaning":"工業化","examples":[{"en":"The passage questions the link between industrialisation and literacy.","zh":"文章質疑工業化與讀寫能力之間的聯繫。"},{"en":"Industrialisation is the process by which a society develops factories, machines, and large-scale production.","zh":"Industrialisation 是社會發展工廠、機器和大規模生產的過程。"},{"en":"Industrialisation changed where people worked and what skills they needed.","zh":"工業化改變了人們工作地點和所需技能。"},{"en":"It often increased the need for instructions, records, and organised communication.","zh":"它常增加對指示、紀錄和有組織溝通的需要。"},{"en":"This word describes a major economic and social transformation.","zh":"這個詞描述重大經濟和社會轉型。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":9},{"front":"on the other hand","meaning":"另一方面","examples":[{"en":"On the other hand, more people now earn money from writing.","zh":"另一方面，現在更多人靠寫作賺錢。"},{"en":"On the other hand introduces a contrasting point or different side of an argument.","zh":"On the other hand 用來引出相反重點或論證的另一面。"},{"en":"Online media can reduce letter-writing; on the other hand, they create new writing jobs.","zh":"網上媒體可以減少書信寫作；另一方面，它們創造新的寫作工作。"},{"en":"Writers use this phrase to show that a situation is balanced or complex.","zh":"作者使用這個片語來顯示情況是平衡或複雜的。"},{"en":"This phrase helps avoid presenting only one side of an issue.","zh":"這個片語有助避免只呈現議題一面。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":9},{"front":"ever-increasing numbers of","meaning":"越來越多的……","examples":[{"en":"Ever-increasing numbers of people make their living from writing.","zh":"越來越多人以寫作謀生。"},{"en":"Ever-increasing numbers of means more and more people or things over time.","zh":"Ever-increasing numbers of 指人或事物數量隨時間越來越多。"},{"en":"Ever-increasing numbers of students use online dictionaries for homework.","zh":"越來越多學生使用網上字典做功課。"},{"en":"If ever-increasing numbers of people write for work, writing has not simply disappeared.","zh":"如果越來越多人靠寫作工作，寫作就不只是消失了。"},{"en":"This phrase emphasises continuous growth.","zh":"這個片語強調持續增長。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":9},{"front":"make one’s living from","meaning":"以……謀生","examples":[{"en":"Many people now make their living from writing.","zh":"許多人現在以寫作謀生。"},{"en":"To make one’s living from something means to earn money through that activity.","zh":"To make one’s living from something 指透過某活動賺錢維生。"},{"en":"A musician may make her living from teaching, performing, and recording songs.","zh":"音樂人可能透過教學、表演和錄音來謀生。"},{"en":"If more people make their living from writing, writing may become more economically valuable.","zh":"如果更多人以寫作謀生，寫作可能變得更具經濟價值。"},{"en":"This phrase describes how someone supports themselves financially.","zh":"這個片語描述某人如何在財政上養活自己。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":9},{"front":"be better rewarded than ever before","meaning":"比以往任何時候都更有回報","examples":[{"en":"Writing is better rewarded than ever before.","zh":"寫作比以往任何時候都更有回報。"},{"en":"To be better rewarded than ever before means to receive more money, status, or recognition than in the past.","zh":"To be better rewarded than ever before 指比過去得到更多金錢、地位或認可。"},{"en":"Skilled software work is better rewarded than ever before in many industries.","zh":"在許多行業中，熟練軟件工作比以往任何時候都更有回報。"},{"en":"If writing is better rewarded, more people may choose writing-related careers.","zh":"如果寫作更有回報，更多人可能選擇與寫作相關的職業。"},{"en":"This phrase compares present rewards with all earlier periods.","zh":"這個片語把現在的回報與所有較早時期作比較。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":9},{"front":"be generally seen as","meaning":"通常被視為","examples":[{"en":"Schools are generally seen as institutions where books dominate.","zh":"學校通常被視為書本主導的機構。"},{"en":"To be generally seen as something means most people view it in that way.","zh":"To be generally seen as something 指大多數人把它看成某樣東西。"},{"en":"Libraries are generally seen as quiet places for reading and study.","zh":"圖書館通常被視為安靜閱讀和學習的地方。"},{"en":"If schools are seen as book-centred, screen-based learning may seem out of place.","zh":"如果學校被視為以書本為中心，屏幕學習可能顯得格格不入。"},{"en":"This phrase describes a common public perception.","zh":"這個片語描述常見公眾看法。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":9},{"front":"institutions where the book rules","meaning":"以書本為主導的機構","examples":[{"en":"Schools are often treated as institutions where the book rules.","zh":"學校常被視為以書本為主導的機構。"},{"en":"Institutions where the book rules are places where printed books dominate learning and authority.","zh":"Institutions where the book rules 是印刷書籍主導學習和權威的地方。"},{"en":"A traditional classroom may feel like a place where the book rules if lessons rely only on textbooks.","zh":"如果課堂只依賴教科書，傳統課室可能像以書本為主導的地方。"},{"en":"When the book rules completely, film, sound, and digital media may be undervalued.","zh":"當書本完全主導，電影、聲音和數碼媒體可能被低估。"},{"en":"This phrase uses “rules” to mean “dominates”.","zh":"這個片語用 “rules” 表示「主導」。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":9},{"front":"recorded sound","meaning":"錄音","examples":[{"en":"Film, television and recorded sound have little place in many schools.","zh":"電影、電視和錄音在許多學校中位置很少。"},{"en":"Recorded sound is sound that has been captured and can be played back later.","zh":"Recorded sound 是被錄下並可之後播放的聲音。"},{"en":"Students use recorded sound when they listen to a language-learning audio file.","zh":"學生聆聽語言學習音訊檔時，就是使用錄音。"},{"en":"Recorded sound can support literacy by helping students hear rhythm, pronunciation, and tone.","zh":"錄音可以透過幫助學生聽到節奏、發音和語氣來支持讀寫能力。"},{"en":"This phrase refers to audio media, not live speech only.","zh":"這個片語指音訊媒體，而不只是現場說話。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":9},{"front":"have almost no place","meaning":"幾乎沒有位置","examples":[{"en":"Film and television have almost no place in traditional classrooms.","zh":"電影和電視在傳統課室中幾乎沒有位置。"},{"en":"To have almost no place means to be given very little role, space, or importance.","zh":"To have almost no place 指幾乎沒有角色、空間或重要性。"},{"en":"Art may have almost no place in a school that focuses only on exam drilling.","zh":"如果學校只集中於考試操練，藝術可能幾乎沒有位置。"},{"en":"If new media have almost no place in classrooms, students may not learn how to use them critically.","zh":"如果新媒體在課室中幾乎沒有位置，學生可能學不到如何批判地使用它們。"},{"en":"This phrase describes near exclusion.","zh":"這個片語描述幾乎被排除。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":9},{"front":"it is not clear that","meaning":"並不清楚……是否","examples":[{"en":"It is not clear that the opposition between books and screens is appropriate.","zh":"書本與屏幕之間的對立是否恰當，並不清楚。"},{"en":"It is not clear that means there is not enough certainty to accept the claim.","zh":"It is not clear that 指沒有足夠確定性接受某主張。"},{"en":"It is not clear that more homework always improves learning.","zh":"更多功課是否總能改善學習，並不清楚。"},{"en":"When evidence is mixed, a writer may say it is not clear that one view is correct.","zh":"當證據不一致，作者可能說並不清楚某一觀點是否正確。"},{"en":"This phrase introduces doubt in a careful way.","zh":"這個片語以謹慎方式引出疑問。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":9},{"front":"this opposition is appropriate","meaning":"這種對立是恰當的","examples":[{"en":"The writer doubts whether this opposition is appropriate.","zh":"作者懷疑這種對立是否恰當。"},{"en":"This opposition is appropriate means this contrast or division is suitable and useful.","zh":"This opposition is appropriate 指這種對比或區分是合適而有用的。"},{"en":"The opposition between online and offline learning may not be appropriate if students use both together.","zh":"如果學生同時使用網上和線下學習，兩者之間的對立可能不恰當。"},{"en":"If two things can support each other, treating them as opposites may be misleading.","zh":"如果兩件事可以互相支持，把它們視為對立可能具誤導性。"},{"en":"This phrase questions whether a contrast is fair.","zh":"這個片語質疑某種對比是否公平。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":10},{"front":"in order to","meaning":"為了","examples":[{"en":"You need to read and write in order to make television programmes.","zh":"為了製作電視節目，你需要閱讀和寫作。"},{"en":"In order to means for the purpose of doing something.","zh":"In order to 指為了做某事。"},{"en":"Students practise speaking in order to become more confident in interviews.","zh":"學生練習口語，是為了在面試中更有信心。"},{"en":"Media workers need literacy skills in order to plan scripts, emails, and production notes.","zh":"媒體工作者需要讀寫技能，是為了規劃劇本、電郵和製作筆記。"},{"en":"This phrase connects an action with its purpose.","zh":"這個片語把行動與目的連接起來。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":10},{"front":"make programmes","meaning":"製作節目","examples":[{"en":"People need literacy skills to make programmes.","zh":"人們需要讀寫技能來製作節目。"},{"en":"To make programmes means to create television, radio, video, or media productions.","zh":"To make programmes 指創作電視、電台、影片或媒體製作。"},{"en":"A media team makes programmes by planning topics, writing scripts, filming, and editing.","zh":"媒體團隊透過規劃主題、寫劇本、拍攝和剪接來製作節目。"},{"en":"If people make programmes, they often need to read research and write clear instructions.","zh":"如果人們製作節目，他們常需要閱讀資料並寫清楚指示。"},{"en":"This phrase describes producing media content, not merely watching it.","zh":"這個片語描述製作媒體內容，而不只是觀看。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":10},{"front":"new media","meaning":"新媒體","examples":[{"en":"Those who work in the new media are not illiterate.","zh":"從事新媒體的人並非文盲。"},{"en":"New media are modern digital forms of communication, such as websites, social media, video platforms, and interactive tools.","zh":"New media 是現代數碼傳播形式，例如網站、社交媒體、影片平台和互動工具。"},{"en":"A student uses new media when they create a podcast or design a webpage.","zh":"學生製作播客或設計網頁時，就是使用新媒體。"},{"en":"New media often require reading, writing, editing, and critical judgement.","zh":"新媒體常需要閱讀、寫作、剪接和批判判斷力。"},{"en":"This phrase contrasts newer digital media with older print or broadcast forms.","zh":"這個片語把較新的數碼媒體與較舊印刷或廣播形式作對比。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":10},{"front":"anything but illiterate","meaning":"絕非文盲","examples":[{"en":"People working in new media are anything but illiterate.","zh":"從事新媒體工作的人絕非文盲。"},{"en":"Anything but illiterate means definitely not illiterate.","zh":"Anything but illiterate 指絕對不是缺乏讀寫能力。"},{"en":"A journalist who writes scripts, captions, and articles all day is anything but illiterate.","zh":"整天寫劇本、字幕和文章的記者絕非文盲。"},{"en":"New media workers often need strong language skills to plan and communicate clearly.","zh":"新媒體工作者常需要強大語言能力來清楚規劃和溝通。"},{"en":"This phrase strongly rejects the idea that someone lacks literacy.","zh":"這個片語強烈否定某人缺乏讀寫能力的想法。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":10},{"front":"traditional oppositions between","meaning":"……之間的傳統對立","examples":[{"en":"Traditional oppositions between old and new media are inadequate.","zh":"舊媒體與新媒體之間的傳統對立並不足夠。"},{"en":"Traditional oppositions between two things are old ways of treating them as opposite sides.","zh":"Traditional oppositions between two things 是把兩者視為相反兩方的舊方式。"},{"en":"The traditional opposition between study and play may be too simple if games can teach skills.","zh":"如果遊戲可以教技能，學習和玩樂之間的傳統對立可能過於簡單。"},{"en":"If old and new media work together, the opposition between them becomes weak.","zh":"如果舊媒體和新媒體可以合作，它們之間的對立便變弱。"},{"en":"This phrase questions a long-established contrast.","zh":"這個片語質疑長久以來的對比。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":10},{"front":"old and new media","meaning":"舊媒體與新媒體","examples":[{"en":"The passage challenges the divide between old and new media.","zh":"文章挑戰舊媒體與新媒體之間的分界。"},{"en":"Old and new media mean older forms such as books and newspapers, and newer forms such as websites and digital video.","zh":"Old and new media 指書本和報紙等較舊形式，以及網站和數碼影片等較新形式。"},{"en":"A lesson may combine old and new media by using a printed poem and an online performance.","zh":"一堂課可以透過使用印刷詩歌和網上表演來結合舊媒體與新媒體。"},{"en":"If both forms support learning, dividing them too sharply may be unhelpful.","zh":"如果兩種形式都支持學習，把它們過分分開可能沒有幫助。"},{"en":"This phrase contrasts media by historical period and technology.","zh":"這個片語按歷史時期和科技對比媒體。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":10},{"front":"be inadequate for","meaning":"不足以用於","examples":[{"en":"The old media categories are inadequate for understanding children’s world.","zh":"舊媒體分類不足以用於理解兒童的世界。"},{"en":"To be inadequate for something means not good enough or not complete enough for that purpose.","zh":"To be inadequate for something 指對某目的而言不夠好或不夠完整。"},{"en":"Exam scores alone are inadequate for understanding a student’s creativity.","zh":"單靠考試分數不足以理解學生創意。"},{"en":"If old categories cannot explain modern life, they become inadequate.","zh":"如果舊分類不能解釋現代生活，它們便變得不足。"},{"en":"This phrase describes a tool or idea that is too limited.","zh":"這個片語描述工具或想法太有限。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":10},{"front":"encounter","meaning":"遇到；接觸到","examples":[{"en":"A young child now encounters a world shaped by many media forms.","zh":"年幼兒童現在接觸到一個由多種媒體形式塑造的世界。"},{"en":"To encounter something means to meet, experience, or come across it.","zh":"To encounter something 指遇見、經歷或接觸到某事。"},{"en":"Students encounter new words when they read stories above their usual level.","zh":"學生閱讀高於平常水平的故事時，會遇到新詞。"},{"en":"Children encounter media at home, in school, on phones, and in public spaces.","zh":"兒童在家中、學校、手機和公共空間接觸到媒體。"},{"en":"This word describes contact with something in real life.","zh":"這個詞描述在現實生活中與某物接觸。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":10},{"front":"re-establish a central place for","meaning":"重新確立……的核心地位","examples":[{"en":"The computer has re-established a central place for the written word.","zh":"電腦重新確立了書面文字的核心地位。"},{"en":"To re-establish a central place for something means to make it important again.","zh":"To re-establish a central place for something 指令某事重新變得重要。"},{"en":"Online learning has re-established a central place for written instructions in many courses.","zh":"網上學習在許多課程中重新確立了書面指示的核心地位。"},{"en":"If computers require typing and reading, they can bring written language back into daily life.","zh":"如果電腦需要打字和閱讀，它們可以把書面語帶回日常生活。"},{"en":"This phrase describes restoring importance after it seemed reduced.","zh":"這個片語描述在重要性似乎下降後重新恢復其重要性。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":10},{"front":"the written word","meaning":"書面文字","examples":[{"en":"The computer has brought the written word back to the screen.","zh":"電腦把書面文字帶回屏幕上。"},{"en":"The written word means language in written form, whether printed or digital.","zh":"Written word 指書面形式的語言，不論是印刷還是數碼。"},{"en":"Emails, subtitles, articles, and search results all use the written word.","zh":"電郵、字幕、文章和搜尋結果都使用書面文字。"},{"en":"If screens display more text, the written word remains important in digital life.","zh":"如果屏幕顯示更多文字，書面文字在數碼生活中仍然重要。"},{"en":"This phrase contrasts writing with images, speech, or sound.","zh":"這個片語把文字與影像、說話或聲音作對比。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":11},{"front":"on the screen","meaning":"在屏幕上","examples":[{"en":"The written word now appears constantly on the screen.","zh":"書面文字現在不斷出現在屏幕上。"},{"en":"On the screen means displayed on a computer, phone, television, or other digital display.","zh":"On the screen 指顯示在電腦、手機、電視或其他數碼顯示器上。"},{"en":"Students read instructions on the screen when they complete an online test.","zh":"學生完成網上測驗時，在屏幕上閱讀指示。"},{"en":"If more words appear on the screen, screen reading becomes part of literacy.","zh":"如果更多文字出現在屏幕上，屏幕閱讀便成為讀寫能力的一部分。"},{"en":"This phrase locates information in digital visual form.","zh":"這個片語把資訊定位於數碼視覺形式中。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":11},{"front":"be devoted to","meaning":"專用於","examples":[{"en":"The screen used to be devoted mainly to the image.","zh":"屏幕過去主要專用於影像。"},{"en":"To be devoted to something means to be used mainly for that purpose.","zh":"To be devoted to something 指主要被用於該目的。"},{"en":"A classroom notice board may be devoted to exam reminders during revision week.","zh":"在溫習週，課室告示板可能專用於考試提醒。"},{"en":"If screens are devoted only to images, written text has less space there.","zh":"如果屏幕只專用於影像，書面文字在那裡的空間便較少。"},{"en":"This phrase describes main use or focus.","zh":"這個片語描述主要用途或焦點。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":11},{"front":"entirely devoted to","meaning":"完全用於","examples":[{"en":"The screen used to be entirely devoted to the image.","zh":"屏幕過去完全用於影像。"},{"en":"Entirely devoted to means completely used for one purpose.","zh":"Entirely devoted to 指完全被用於一個目的。"},{"en":"A quiet room may be entirely devoted to study during exam season.","zh":"在考試季節，安靜房間可能完全用於學習。"},{"en":"If a screen is entirely devoted to images, reading plays almost no role.","zh":"如果屏幕完全用於影像，閱讀幾乎沒有角色。"},{"en":"This phrase emphasises complete focus on one thing.","zh":"這個片語強調完全集中於一件事。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":11},{"front":"the image","meaning":"影像","examples":[{"en":"The screen was once mainly associated with the image.","zh":"屏幕曾經主要與影像相關。"},{"en":"The image means visual material such as pictures, photographs, drawings, or moving visuals.","zh":"The image 指圖片、照片、圖畫或動態視覺等視覺材料。"},{"en":"A film often uses the image to tell emotion without words.","zh":"電影常使用影像不用文字地表達情感。"},{"en":"If education focuses only on the image, students may miss the role of written language.","zh":"如果教育只集中於影像，學生可能忽略書面語的角色。"},{"en":"This phrase contrasts visual communication with written text.","zh":"這個片語把視覺傳播與書面文字作對比。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":11},{"front":"anecdotal evidence","meaning":"軼事證據；非正式證據","examples":[{"en":"There is anecdotal evidence that children learn to read for the Internet.","zh":"有非正式證據顯示兒童為了使用互聯網而學習閱讀。"},{"en":"Anecdotal evidence is informal evidence based on personal stories or individual cases.","zh":"Anecdotal evidence 是基於個人故事或個別案例的非正式證據。"},{"en":"A teacher may hear anecdotal evidence that students read more when stories are online.","zh":"老師可能聽到軼事證據，說學生在故事放到網上時閱讀更多。"},{"en":"Anecdotal evidence can suggest a pattern, but research is needed to test it.","zh":"軼事證據可以提示某種模式，但需要研究來測試。"},{"en":"This phrase refers to experience-based evidence, not systematic proof.","zh":"這個片語指基於經驗的證據，而不是系統證明。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":11},{"front":"master reading and writing","meaning":"掌握讀寫","examples":[{"en":"Some children master reading and writing in order to use the Internet.","zh":"一些兒童為了使用互聯網而掌握讀寫。"},{"en":"To master reading and writing means to become skilled at understanding and producing written language.","zh":"To master reading and writing 指熟練理解和產生書面語。"},{"en":"A child may master reading and writing faster when they want to send messages to friends.","zh":"當孩子想給朋友發訊息時，可能更快掌握讀寫。"},{"en":"Strong motivation can help students practise difficult literacy skills more often.","zh":"強烈動機可以幫助學生更頻繁練習困難讀寫技能。"},{"en":"This phrase describes achieving a solid level of literacy.","zh":"這個片語描述達到穩固的讀寫能力水平。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":11},{"front":"get on to the Internet","meaning":"上網","examples":[{"en":"Children may learn reading and writing to get on to the Internet.","zh":"兒童可能為了上網而學習閱讀和寫作。"},{"en":"To get on to the Internet means to access or use the Internet.","zh":"To get on to the Internet 指接入或使用互聯網。"},{"en":"A student needs basic reading skills to get on to the Internet and search for homework help.","zh":"學生需要基本閱讀能力才能上網搜尋功課幫助。"},{"en":"If children want to join online games or websites, they may become motivated to read.","zh":"如果兒童想加入網上遊戲或網站，他們可能更有動機閱讀。"},{"en":"This phrase describes entering or using the online world.","zh":"這個片語描述進入或使用網上世界。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":11},{"front":"there is no reason why","meaning":"沒有理由……不可以","examples":[{"en":"There is no reason why new and old media cannot be integrated.","zh":"沒有理由新媒體和舊媒體不可以被整合。"},{"en":"There is no reason why means there is no clear obstacle or good argument against it.","zh":"There is no reason why 指沒有清楚障礙或有力理由反對某事。"},{"en":"There is no reason why students cannot use both notebooks and tablets.","zh":"沒有理由學生不可以同時使用筆記簿和平板電腦。"},{"en":"If two tools help learning, they do not need to be treated as enemies.","zh":"如果兩種工具都幫助學習，它們不需要被視為敵人。"},{"en":"This phrase rejects an unnecessary limitation.","zh":"這個片語否定不必要的限制。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":11},{"front":"be integrated in schools","meaning":"融入學校","examples":[{"en":"New and old media can be integrated in schools.","zh":"新媒體和舊媒體可以融入學校。"},{"en":"To be integrated in schools means to be combined into teaching, learning, and school culture.","zh":"To be integrated in schools 指被結合進教學、學習和學校文化中。"},{"en":"A teacher can integrate books, videos, and online discussion in one lesson.","zh":"老師可以在一堂課中結合書本、影片和網上討論。"},{"en":"If media are integrated well, students learn how to use each form critically.","zh":"如果媒體被良好融入，學生會學懂如何批判地使用每種形式。"},{"en":"This phrase describes meaningful inclusion, not just placing equipment in classrooms.","zh":"這個片語描述有意義的加入，而不只是把設備放進課室。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":11},{"front":"provide the skills needed to","meaning":"提供所需技能去","examples":[{"en":"Schools can provide the skills needed to succeed in modern society.","zh":"學校可以提供在現代社會成功所需的技能。"},{"en":"To provide the skills needed to do something means to teach or give the abilities required for it.","zh":"To provide the skills needed to do something 指教授或提供完成某事所需的能力。"},{"en":"A language course can provide the skills needed to write job applications.","zh":"語言課可以提供寫求職申請所需技能。"},{"en":"If schools teach digital and print literacy together, students may be better prepared.","zh":"如果學校同時教授數碼和印刷讀寫能力，學生可能準備得更好。"},{"en":"This phrase connects education with practical ability.","zh":"這個片語把教育與實用能力連接起來。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":12},{"front":"economically productive","meaning":"具經濟生產力的","examples":[{"en":"Education should help students become economically productive.","zh":"教育應幫助學生成為具經濟生產力的人。"},{"en":"Economically productive means able to contribute to work, income, production, or economic activity.","zh":"Economically productive 指能對工作、收入、生產或經濟活動作出貢獻。"},{"en":"A person with useful skills can become economically productive by finding stable work.","zh":"擁有有用技能的人可以透過找到穩定工作而具經濟生產力。"},{"en":"Literacy can help people understand instructions, communicate, and earn money.","zh":"讀寫能力可以幫助人理解指示、溝通和賺錢。"},{"en":"This phrase connects education with employment and economic contribution.","zh":"這個片語把教育與就業及經濟貢獻連接起來。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":12},{"front":"politically enfranchised","meaning":"享有政治權利的","examples":[{"en":"Literacy can help people become politically enfranchised.","zh":"讀寫能力可以幫助人們享有政治權利。"},{"en":"Politically enfranchised means having the rights, knowledge, and ability to participate in political life.","zh":"Politically enfranchised 指擁有參與政治生活的權利、知識和能力。"},{"en":"A citizen who can read election information is better able to vote responsibly.","zh":"能閱讀選舉資訊的公民更能負責任地投票。"},{"en":"If people cannot understand public notices, they may be excluded from political participation.","zh":"如果人們不能理解公共告示，他們可能被排除於政治參與之外。"},{"en":"This phrase connects literacy with democratic rights and involvement.","zh":"這個片語把讀寫能力與民主權利和參與連接起來。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":12},{"front":"nevertheless","meaning":"然而；儘管如此","examples":[{"en":"Nevertheless, the writer accepts that there is a crisis in literacy.","zh":"然而，作者承認存在讀寫能力危機。"},{"en":"Nevertheless means however or despite what has just been said.","zh":"Nevertheless 指然而或儘管剛才所說如此。"},{"en":"Technology can support learning; nevertheless, students still need guidance.","zh":"科技可以支持學習；然而，學生仍需要指導。"},{"en":"A writer uses “nevertheless” to add a contrasting point without rejecting the previous one completely.","zh":"作者使用 “nevertheless” 來加入對比重點，而不是完全否定前一點。"},{"en":"This phrase helps show a balanced argument.","zh":"這個片語有助呈現平衡論證。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":12},{"front":"it would be foolish to","meaning":"……是愚蠢的","examples":[{"en":"It would be foolish to ignore the crisis in literacy.","zh":"忽視讀寫能力危機是愚蠢的。"},{"en":"It would be foolish to do something means doing it would be unwise or careless.","zh":"It would be foolish to do something 指做某事是不明智或粗心的。"},{"en":"It would be foolish to buy an expensive phone without checking the price elsewhere.","zh":"不先比較其他地方價錢就買昂貴手機是愚蠢的。"},{"en":"If evidence suggests a real problem, ignoring it would be irresponsible.","zh":"如果證據顯示真有問題，忽視它是不負責任的。"},{"en":"This phrase gives a strong warning against a bad choice.","zh":"這個片語強烈警告不要作出差劣選擇。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":12},{"front":"ignore it","meaning":"忽視它","examples":[{"en":"The writer says that the crisis should not be ignored.","zh":"作者說不應忽視這場危機。"},{"en":"To ignore it means to pay no attention to the problem or issue.","zh":"To ignore it 指不理會該問題或議題。"},{"en":"A school should not ignore weak reading results if many students are struggling.","zh":"如果許多學生有困難，學校不應忽視薄弱閱讀成績。"},{"en":"Ignoring a problem can allow it to become larger and harder to solve.","zh":"忽視問題可以令它變得更大、更難解決。"},{"en":"This phrase warns against pretending that something does not matter.","zh":"這個片語提醒人不要假裝某事不重要。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":12},{"front":"less central to","meaning":"對……較不核心","examples":[{"en":"Literacy may be less central to some aspects of everyday life.","zh":"讀寫能力對日常生活某些方面可能較不核心。"},{"en":"Less central to something means less important or less necessary within it.","zh":"Less central to something 指在某事中較不重要或較不必要。"},{"en":"Handwriting is less central to office work now than it was before computers.","zh":"與電腦出現前相比，手寫現在對辦公工作較不核心。"},{"en":"If a skill becomes less central, people may practise it less often.","zh":"如果一項技能變得較不核心，人們可能較少練習它。"},{"en":"This phrase describes reduced importance, not total disappearance.","zh":"這個片語描述重要性下降，而不是完全消失。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":12},{"front":"everyday life","meaning":"日常生活","examples":[{"en":"Some forms of literacy are less central to everyday life.","zh":"某些形式的讀寫能力對日常生活較不核心。"},{"en":"Everyday life means ordinary daily activities at home, work, school, and in the community.","zh":"Everyday life 指家中、工作、學校和社區中的普通日常活動。"},{"en":"Reading messages, paying bills, shopping, and travelling are parts of everyday life.","zh":"閱讀訊息、繳費、購物和出行都是日常生活的一部分。"},{"en":"If writing letters disappears from everyday life, people may write them less fluently.","zh":"如果寫信從日常生活中消失，人們可能寫得不那麼流暢。"},{"en":"This phrase refers to normal daily experience, not special occasions.","zh":"這個片語指正常每日經驗，而不是特別場合。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":12},{"front":"not the same as","meaning":"並不等同於","examples":[{"en":"Understanding a problem is not the same as accepting it.","zh":"理解一個問題並不等同於接受它。"},{"en":"Not the same as means two things are different and should not be confused.","zh":"Not the same as 指兩件事不同，不應混淆。"},{"en":"Understanding why a student cheated is not the same as saying cheating is acceptable.","zh":"理解學生為何作弊，並不等同於說作弊可以接受。"},{"en":"A writer can explain a decline without agreeing that it should continue.","zh":"作者可以解釋下降現象，而不等於同意它應繼續。"},{"en":"This phrase separates explanation from approval.","zh":"這個片語把解釋與認可分開。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":12},{"front":"acquiesce in","meaning":"默許；順從接受","examples":[{"en":"The writer does not support acquiescing in declining literacy.","zh":"作者不支持默許讀寫能力下降。"},{"en":"To acquiesce in something means to accept it without protest, even if it is undesirable.","zh":"To acquiesce in something 指即使某事不理想，也不反對地接受它。"},{"en":"Parents should not acquiesce in unsafe school transport simply because change is difficult.","zh":"家長不應只因改變困難，就默許不安全的校車安排。"},{"en":"If society acquiesces in poor literacy, the problem may continue.","zh":"如果社會默許讀寫能力差，問題可能繼續。"},{"en":"This phrase is formal and suggests passive acceptance.","zh":"這個片語較正式，暗示被動接受。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":12},{"front":"this state of affairs","meaning":"這種情況","examples":[{"en":"The writer refuses to acquiesce in this state of affairs.","zh":"作者拒絕默許這種情況。"},{"en":"This state of affairs means the present situation or condition.","zh":"This state of affairs 指目前的情況或狀況。"},{"en":"If students are reading less every year, this state of affairs should concern teachers.","zh":"如果學生每年閱讀更少，這種情況應令老師擔心。"},{"en":"A bad state of affairs may require action, not just explanation.","zh":"差劣情況可能需要行動，而不只是解釋。"},{"en":"This phrase refers to the situation already described.","zh":"這個片語指前文已描述的情況。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":13},{"front":"production of schoolwork","meaning":"製作學校作業","examples":[{"en":"The production of schoolwork with new technologies could support literacy.","zh":"使用新科技製作學校作業可以支持讀寫能力。"},{"en":"The production of schoolwork means creating assignments, projects, essays, videos, or presentations for school.","zh":"Production of schoolwork 指為學校創作功課、項目、文章、影片或簡報。"},{"en":"Students produce schoolwork when they write reports, edit videos, or design slides.","zh":"學生寫報告、剪接影片或設計簡報時，就是在製作學校作業。"},{"en":"If technology helps students create meaningful schoolwork, it can strengthen literacy.","zh":"如果科技幫助學生創作有意義的學校作業，它可以強化讀寫能力。"},{"en":"This phrase focuses on students making work, not just consuming media.","zh":"這個片語著重學生製作作品，而不只是消費媒體。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":13},{"front":"a significant stimulus to","meaning":"對……的重要刺激","examples":[{"en":"New technologies could be a significant stimulus to literacy.","zh":"新科技可以成為對讀寫能力的重要刺激。"},{"en":"A significant stimulus to something is an important factor that encourages or strengthens it.","zh":"Significant stimulus to something 是鼓勵或強化某事的重要因素。"},{"en":"A reading competition can be a significant stimulus to children’s interest in books.","zh":"閱讀比賽可以成為刺激兒童讀書興趣的重要因素。"},{"en":"If students use technology to write, edit, and publish, it may stimulate literacy.","zh":"如果學生使用科技寫作、剪接和發布，它可能刺激讀寫能力。"},{"en":"This phrase describes something that gives strong encouragement or energy.","zh":"這個片語描述給予強烈鼓勵或動力的事物。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":13},{"front":"be introduced into","meaning":"被引入","examples":[{"en":"The article asks how new technologies should be introduced into schools.","zh":"文章問新科技應如何被引入學校。"},{"en":"To be introduced into a place means to be brought into use there.","zh":"To be introduced into a place 指被帶入該處使用。"},{"en":"Tablets were introduced into some classrooms to support interactive learning.","zh":"平板電腦被引入一些課室，以支持互動學習。"},{"en":"If technology is introduced without training, it may not improve learning.","zh":"如果科技在沒有培訓下被引入，它可能不會改善學習。"},{"en":"This phrase describes bringing something new into a system.","zh":"這個片語描述把新事物帶入一個系統。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":13},{"front":"it isn’t enough to","meaning":"……是不足夠的","examples":[{"en":"It isn’t enough to put equipment into every classroom.","zh":"把設備放進每間課室是不足夠的。"},{"en":"It isn’t enough to do something means that action alone will not solve the problem.","zh":"It isn’t enough to do something 指單靠該行動不能解決問題。"},{"en":"It isn’t enough to buy books if students are never taught how to read them well.","zh":"如果從不教學生如何好好閱讀，單是買書是不足夠的。"},{"en":"Schools need training, planning, and clear aims, not just equipment.","zh":"學校需要培訓、規劃和清晰目標，而不只是設備。"},{"en":"This phrase warns that a solution is incomplete.","zh":"這個片語提醒人某方案並不完整。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":13},{"front":"call for","meaning":"呼籲；要求","examples":[{"en":"Some people call for computers in every classroom.","zh":"有些人呼籲每間課室都應有電腦。"},{"en":"To call for something means to publicly ask or demand that it should happen.","zh":"To call for something 指公開要求或呼籲某事應發生。"},{"en":"Parents may call for more reading support if many children fall behind.","zh":"如果許多孩子落後，家長可能呼籲提供更多閱讀支援。"},{"en":"Calling for equipment is easier than planning how to use it well.","zh":"呼籲添置設備比規劃如何善用它更容易。"},{"en":"This phrase is common in public debate and policy discussion.","zh":"這個片語常見於公共辯論和政策討論。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":13},{"front":"camcorders","meaning":"攝錄機","examples":[{"en":"Camcorders alone will not improve literacy unless they are properly used.","zh":"除非妥善使用，單靠攝錄機不會改善讀寫能力。"},{"en":"Camcorders are portable video cameras used to record moving images and sound.","zh":"Camcorders 是用來錄製動態影像和聲音的便攜式攝影機。"},{"en":"Students may use camcorders to film interviews for a media project.","zh":"學生可能使用攝錄機為媒體項目拍攝訪問。"},{"en":"A camcorder can support literacy if students plan scripts, questions, and captions.","zh":"如果學生規劃劇本、問題和字幕，攝錄機可以支持讀寫能力。"},{"en":"This word refers to equipment, not the teaching method itself.","zh":"這個詞指設備，而不是教學方法本身。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":13},{"front":"edit suites","meaning":"剪接室","examples":[{"en":"Edit suites need to be integrated into the educational culture.","zh":"剪接室需要融入教育文化。"},{"en":"Edit suites are rooms or systems with equipment for editing video, audio, or media projects.","zh":"Edit suites 是配有剪接影片、音訊或媒體項目設備的房間或系統。"},{"en":"Students may use edit suites to cut interviews and add subtitles to a documentary.","zh":"學生可能使用剪接室剪輯訪問並為紀錄片加入字幕。"},{"en":"If edit suites are available but not used in lessons, they do little for learning.","zh":"如果剪接室可用但沒有在課堂中使用，它們對學習幫助不大。"},{"en":"This phrase refers to media-production facilities.","zh":"這個片語指媒體製作設施。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":13},{"front":"properly integrated into","meaning":"妥善融入","examples":[{"en":"Technology must be properly integrated into classroom teaching.","zh":"科技必須妥善融入課堂教學。"},{"en":"Properly integrated into something means included in a careful, useful, and meaningful way.","zh":"Properly integrated into something 指以謹慎、有用和有意義的方式加入某事。"},{"en":"A tablet is properly integrated into a lesson when students use it to research, write, and discuss.","zh":"當學生使用平板電腦研究、寫作和討論，它才算妥善融入課堂。"},{"en":"If technology is not properly integrated, it may distract students instead of helping them.","zh":"如果科技沒有妥善融入，它可能分散學生注意力而不是幫助他們。"},{"en":"This phrase stresses thoughtful use, not simple addition.","zh":"這個片語強調有思考的使用，而不是單純加入。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":13},{"front":"educational culture","meaning":"教育文化","examples":[{"en":"New technologies must become part of the educational culture.","zh":"新科技必須成為教育文化的一部分。"},{"en":"Educational culture means the habits, values, expectations, and practices of teaching and learning.","zh":"Educational culture 指教與學中的習慣、價值觀、期望和做法。"},{"en":"A school’s educational culture may value discussion, exams, creativity, or discipline.","zh":"學校的教育文化可能重視討論、考試、創意或紀律。"},{"en":"Technology works better when it fits the educational culture rather than sitting outside it.","zh":"當科技配合教育文化，而不是置身其外，它會更有效。"},{"en":"This phrase describes the deeper environment of learning.","zh":"這個片語描述較深層的學習環境。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":13},{"front":"stand unused","meaning":"閒置不用","examples":[{"en":"Without proper integration, technology will stand unused.","zh":"如果沒有妥善融入，科技會閒置不用。"},{"en":"To stand unused means to remain available but not actually be used.","zh":"To stand unused 指某物存在或可用，但實際上沒有被使用。"},{"en":"A computer room may stand unused if teachers are not trained to use it.","zh":"如果老師未受訓使用，電腦室可能閒置不用。"},{"en":"Equipment standing unused wastes money and does not improve learning.","zh":"設備閒置不用會浪費金錢，並不能改善學習。"},{"en":"This phrase describes neglect after something has been bought or installed.","zh":"這個片語描述某物被購買或安裝後遭忽視。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":14},{"front":"evidence suggests that","meaning":"證據顯示","examples":[{"en":"Evidence suggests that much classroom technology is unused.","zh":"證據顯示許多課室科技都未被使用。"},{"en":"Evidence suggests that means available facts point toward a likely conclusion.","zh":"Evidence suggests that 指現有事實指向一個可能結論。"},{"en":"Attendance records may suggest that students arrive late on rainy days.","zh":"出席紀錄可能顯示學生在下雨天較常遲到。"},{"en":"If evidence suggests a problem, schools should investigate instead of guessing.","zh":"如果證據顯示有問題，學校應調查，而不是猜測。"},{"en":"This phrase is cautious and evidence-based.","zh":"這個片語謹慎且以證據為本。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":14},{"front":"the fate of","meaning":"……的命運","examples":[{"en":"Standing unused is the fate of much information technology in classrooms.","zh":"閒置不用是許多課室資訊科技的命運。"},{"en":"The fate of something is what finally happens to it.","zh":"The fate of something 指某事物最終發生甚麼。"},{"en":"The fate of old textbooks may be storage if no one updates the curriculum.","zh":"如果沒有人更新課程，舊教科書的命運可能是被放入儲物室。"},{"en":"If technology is poorly planned, its fate may be to gather dust in a corner.","zh":"如果科技規劃差，它的命運可能是在角落積塵。"},{"en":"This phrase often suggests an outcome, sometimes a negative one.","zh":"這個片語常暗示結果，有時是負面的結果。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":14},{"front":"information technology","meaning":"資訊科技","examples":[{"en":"Information technology is often underused in classrooms.","zh":"資訊科技在課室中常被低度使用。"},{"en":"Information technology means computer systems, software, networks, and digital tools used to store, process, or share information.","zh":"Information technology 指用來儲存、處理或分享資訊的電腦系統、軟件、網絡和數碼工具。"},{"en":"Schools use information technology when students write online documents or use learning platforms.","zh":"學生寫網上文件或使用學習平台時，學校就是在使用資訊科技。"},{"en":"If information technology is not linked to learning goals, it may not improve lessons.","zh":"如果資訊科技沒有連接學習目標，它可能不會改善課堂。"},{"en":"This phrase refers to digital tools for handling information.","zh":"這個片語指處理資訊的數碼工具。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":14},{"front":"used in the classroom","meaning":"在課堂上使用","examples":[{"en":"Technology used in the classroom must support learning.","zh":"在課堂上使用的科技必須支持學習。"},{"en":"Used in the classroom means applied during lessons or school learning activities.","zh":"Used in the classroom 指在課堂或學校學習活動中應用。"},{"en":"Videos used in the classroom should help students understand the topic, not just entertain them.","zh":"在課堂上使用的影片應幫助學生理解主題，而不只是娛樂他們。"},{"en":"If a tool is used in the classroom without purpose, it may waste time.","zh":"如果工具在課堂上沒有目的地使用，可能浪費時間。"},{"en":"This phrase focuses on practical teaching use.","zh":"這個片語著重實際教學用途。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":14},{"front":"similarly","meaning":"同樣地","examples":[{"en":"Similarly, media studies have entered the curriculum without clear aims.","zh":"同樣地，媒體研究已進入課程，但缺乏清晰目標。"},{"en":"Similarly means in a similar way or for a similar reason.","zh":"Similarly 指以相似方式或基於相似原因。"},{"en":"Some students dislike long essays; similarly, others dislike long reading passages.","zh":"有些學生不喜歡長作文；同樣地，另一些不喜歡長閱讀文章。"},{"en":"Writers use “similarly” to connect two examples with the same pattern.","zh":"作者使用 “similarly” 來連接兩個具有相同模式的例子。"},{"en":"This phrase shows that the next point is related to the previous one.","zh":"這個片語顯示下一點與前一點相關。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":14},{"front":"media studies","meaning":"媒體研究","examples":[{"en":"Media studies are now part of the national curriculum.","zh":"媒體研究現在是國家課程的一部分。"},{"en":"Media studies is the study of film, television, advertising, news, digital media, and how they create meaning.","zh":"Media studies 是研究電影、電視、廣告、新聞、數碼媒體，以及它們如何創造意義的科目。"},{"en":"Students in media studies may analyse a news report or create a short video.","zh":"媒體研究學生可能分析新聞報道或製作短片。"},{"en":"Media studies can support literacy if students learn to read images and write scripts critically.","zh":"如果學生學會批判地閱讀影像和寫劇本，媒體研究可以支持讀寫能力。"},{"en":"This phrase refers to an academic subject about media.","zh":"這個片語指關於媒體的學科。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":14},{"front":"national curriculum","meaning":"國家課程","examples":[{"en":"Media studies are now part of the national curriculum.","zh":"媒體研究現在是國家課程的一部分。"},{"en":"A national curriculum is the official set of subjects and learning goals used in schools across a country.","zh":"National curriculum 是全國學校使用的官方科目和學習目標。"},{"en":"If media studies enters the national curriculum, more students may study it.","zh":"如果媒體研究進入國家課程，更多學生可能學習它。"},{"en":"A national curriculum can shape what teachers teach and what students are tested on.","zh":"國家課程可以塑造老師教甚麼和學生考甚麼。"},{"en":"This phrase refers to official education planning at country level.","zh":"這個片語指國家層面的官方教育規劃。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":14},{"front":"more and more students","meaning":"越來越多學生","examples":[{"en":"More and more students are clamouring to take media studies courses.","zh":"越來越多學生強烈要求修讀媒體研究課程。"},{"en":"More and more students means an increasing number of students.","zh":"More and more students 指學生數量不斷增加。"},{"en":"More and more students use online videos to revise difficult topics.","zh":"越來越多學生使用網上影片溫習困難主題。"},{"en":"If more and more students choose a subject, schools may need more teachers for it.","zh":"如果越來越多學生選修某科，學校可能需要更多該科老師。"},{"en":"This phrase describes a rising trend.","zh":"這個片語描述上升趨勢。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":14},{"front":"clamour to","meaning":"強烈要求","examples":[{"en":"Students are clamouring to take media studies courses.","zh":"學生強烈要求修讀媒體研究課程。"},{"en":"To clamour to do something means to demand or ask for it loudly and strongly.","zh":"To clamour to do something 指大聲而強烈地要求做某事。"},{"en":"Students may clamour to join a popular drama club if places are limited.","zh":"如果名額有限，學生可能強烈要求加入受歡迎的戲劇社。"},{"en":"When many people clamour for a course, schools may feel pressure to offer it.","zh":"當許多人強烈要求某課程，學校可能感到壓力去提供它。"},{"en":"This phrase suggests strong public demand.","zh":"這個片語暗示強烈公眾需求。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":14},{"front":"take these courses","meaning":"修讀這些課程","examples":[{"en":"Many students want to take these courses.","zh":"許多學生想修讀這些課程。"},{"en":"To take these courses means to enrol in and study these classes.","zh":"To take these courses 指報讀並學習這些課程。"},{"en":"Students may take media courses because they enjoy film, advertising, and digital culture.","zh":"學生可能因喜歡電影、廣告和數碼文化而修讀媒體課程。"},{"en":"If many students take these courses, teachers need clear methods and aims.","zh":"如果許多學生修讀這些課程，老師需要清晰方法和目標。"},{"en":"This phrase refers to studying a subject formally.","zh":"這個片語指正式學習某科目。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":15},{"front":"remain uncertain about","meaning":"仍然不確定","examples":[{"en":"Teachers remain uncertain about methods and aims in media studies.","zh":"老師對媒體研究的方法和目標仍然不確定。"},{"en":"To remain uncertain about something means to continue not being sure about it.","zh":"To remain uncertain about something 指繼續對某事不肯定。"},{"en":"A teacher may remain uncertain about using AI tools if school rules are unclear.","zh":"如果校規不清楚，老師可能仍然不確定如何使用AI工具。"},{"en":"If teachers are uncertain about aims, lessons may lack direction.","zh":"如果老師對目標不確定，課堂可能缺乏方向。"},{"en":"This phrase describes continuing doubt.","zh":"這個片語描述持續疑惑。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":15},{"front":"methods and aims","meaning":"方法和目標","examples":[{"en":"Teachers are unsure about both methods and aims in this area.","zh":"老師對這個範疇的方法和目標都不確定。"},{"en":"Methods and aims are the ways of teaching and the goals the teaching is meant to achieve.","zh":"Methods and aims 是教學方式，以及教學打算達到的目標。"},{"en":"A reading lesson needs clear methods and aims, such as close reading and vocabulary growth.","zh":"閱讀課需要清晰方法和目標，例如細讀和詞彙增長。"},{"en":"If methods and aims are unclear, students may do activities without knowing why.","zh":"如果方法和目標不清楚，學生可能做活動卻不知道原因。"},{"en":"This phrase connects classroom practice with educational purpose.","zh":"這個片語把課堂做法與教育目的連接起來。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":15},{"front":"in this area","meaning":"在這個範疇","examples":[{"en":"Teachers remain uncertain about teaching methods in this area.","zh":"老師對這個範疇的教學方法仍然不確定。"},{"en":"In this area means in this subject, field, or part of work.","zh":"In this area 指在這個科目、領域或工作部分中。"},{"en":"A new teacher may need support in this area if they have never taught media studies before.","zh":"如果新老師從未教過媒體研究，可能在這個範疇需要支援。"},{"en":"If experts disagree in this area, schools may find it hard to design lessons.","zh":"如果專家在這個範疇有分歧，學校可能難以設計課堂。"},{"en":"This phrase points back to the topic already being discussed.","zh":"這個片語指回正在討論的主題。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":15},{"front":"this is not the fault of","meaning":"這不是……的錯","examples":[{"en":"The writer says this is not the fault of the teachers.","zh":"作者說這不是老師的錯。"},{"en":"This is not the fault of someone means that person should not be blamed for the problem.","zh":"This is not the fault of someone 指不應把問題歸咎於該人。"},{"en":"If a school buys equipment without training, poor use is not the fault of the students.","zh":"如果學校購買設備卻沒有培訓，使用差並不是學生的錯。"},{"en":"Problems caused by unclear policy should not be blamed on teachers alone.","zh":"由政策不清楚造成的問題，不應只怪老師。"},{"en":"This phrase separates responsibility from blame.","zh":"這個片語把責任與責怪分開。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":15},{"front":"entertainment and information industries","meaning":"娛樂及資訊產業","examples":[{"en":"The entertainment and information industries should join the educational debate.","zh":"娛樂及資訊產業應加入教育辯論。"},{"en":"Entertainment and information industries are businesses that create media, news, films, music, games, and digital content.","zh":"Entertainment and information industries 是創作媒體、新聞、電影、音樂、遊戲和數碼內容的行業。"},{"en":"Television companies and online platforms are part of these industries.","zh":"電視公司和網上平台都是這些產業的一部分。"},{"en":"If these industries shape children’s media world, they should help discuss media education.","zh":"如果這些產業塑造兒童的媒體世界，它們應幫助討論媒體教育。"},{"en":"This phrase refers to powerful media-related sectors.","zh":"這個片語指強大的媒體相關行業。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":15},{"front":"be drawn into a debate with","meaning":"被拉進與……的討論","examples":[{"en":"Media industries must be drawn into a debate with educational institutions.","zh":"媒體產業必須被拉進與教育機構的討論。"},{"en":"To be drawn into a debate with someone means to be brought into discussion or argument with them.","zh":"To be drawn into a debate with someone 指被帶入與某人的討論或爭論中。"},{"en":"Parents may be drawn into a debate with schools about phone use.","zh":"家長可能被拉進與學校關於手機使用的討論。"},{"en":"If media companies affect children’s learning, educators may want them involved in the discussion.","zh":"如果媒體公司影響兒童學習，教育工作者可能希望它們參與討論。"},{"en":"This phrase describes being included in an important debate.","zh":"這個片語描述被納入重要辯論。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":15},{"front":"educational institutions","meaning":"教育機構","examples":[{"en":"Educational institutions need to work with media industries.","zh":"教育機構需要與媒體產業合作。"},{"en":"Educational institutions are schools, colleges, universities, and other organisations that provide education.","zh":"Educational institutions 是學校、學院、大學和其他提供教育的組織。"},{"en":"A university is an educational institution because it teaches students and conducts research.","zh":"大學是教育機構，因為它教學生並進行研究。"},{"en":"If educational institutions work with media industries, students may learn modern communication skills better.","zh":"如果教育機構與媒體產業合作，學生可能更好學習現代溝通技能。"},{"en":"This phrase refers to organised places of learning.","zh":"這個片語指有組織的學習場所。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":15},{"front":"determine how best to","meaning":"決定如何最好地","examples":[{"en":"The groups should determine how best to use new technologies.","zh":"這些團體應決定如何最好地使用新科技。"},{"en":"To determine how best to do something means to decide the most effective way to do it.","zh":"To determine how best to do something 指決定做某事最有效的方法。"},{"en":"A school must determine how best to support students who read slowly.","zh":"學校必須決定如何最好地支援閱讀較慢的學生。"},{"en":"If technology is expensive, leaders should decide carefully how it will improve learning.","zh":"如果科技昂貴，領導者應仔細決定它如何改善學習。"},{"en":"This phrase focuses on choosing the best method.","zh":"這個片語著重選擇最佳方法。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":15},{"front":"blend into","meaning":"融入","examples":[{"en":"New technologies should be blended into the classroom.","zh":"新科技應融入課室。"},{"en":"To blend into something means to become part of it smoothly.","zh":"To blend into something 指順利成為其中一部分。"},{"en":"Online quizzes can blend into a lesson when they check understanding at the right moment.","zh":"如果網上小測在合適時候檢查理解，它就能融入課堂。"},{"en":"If technology blends into classroom work, it supports learning instead of interrupting it.","zh":"如果科技融入課堂工作，它會支持學習，而不是打斷學習。"},{"en":"This phrase suggests smooth integration rather than awkward addition.","zh":"這個片語暗示順暢整合，而不是生硬加入。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":15},{"front":"in our era","meaning":"在我們這個時代","examples":[{"en":"Many people in our era are pessimistic about new media.","zh":"在我們這個時代，許多人對新媒體持悲觀態度。"},{"en":"In our era means in the present age or period in which we live.","zh":"In our era 指在我們現在生活的時代或時期。"},{"en":"In our era, students often learn through both books and screens.","zh":"在我們這個時代，學生常透過書本和屏幕學習。"},{"en":"Because technology changes quickly in our era, people may feel worried about old skills.","zh":"因為在我們這個時代科技變化很快，人們可能擔心舊技能。"},{"en":"This phrase places an idea in the current historical moment.","zh":"這個片語把想法放在當前歷史時刻。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":16},{"front":"be drawn to","meaning":"被……吸引","examples":[{"en":"Many people are drawn to a pessimistic view of new media.","zh":"許多人被對新媒體的悲觀觀點吸引。"},{"en":"To be drawn to something means to feel attracted to it or inclined to accept it.","zh":"To be drawn to something 指感到被某事吸引，或傾向接受它。"},{"en":"Students may be drawn to short videos because they are quick and entertaining.","zh":"學生可能被短片吸引，因為它們快速而有趣。"},{"en":"People may be drawn to pessimistic views when change feels threatening.","zh":"當變化令人感到威脅，人們可能被悲觀觀點吸引。"},{"en":"This phrase describes attraction to an idea, person, or activity.","zh":"這個片語描述被想法、人或活動吸引。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":16},{"front":"the pessimistic view","meaning":"悲觀觀點","examples":[{"en":"The pessimistic view is that new media destroy old skills.","zh":"悲觀觀點是新媒體摧毀舊技能。"},{"en":"The pessimistic view is the negative interpretation of a situation, focusing on danger or decline.","zh":"Pessimistic view 是對情況的負面解讀，集中於危險或衰退。"},{"en":"A pessimistic view of online learning says students will become lazy and isolated.","zh":"對網上學習的悲觀觀點認為學生會變懶和孤立。"},{"en":"If people hold only a pessimistic view, they may miss possible benefits.","zh":"如果人們只有悲觀觀點，可能會錯過可能好處。"},{"en":"This phrase contrasts with a more hopeful or balanced view.","zh":"這個片語與較有希望或較平衡的看法形成對比。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":16},{"front":"destroy old skills","meaning":"摧毀舊技能","examples":[{"en":"Some people believe new media are destroying old skills.","zh":"有些人相信新媒體正在摧毀舊技能。"},{"en":"To destroy old skills means to make traditional abilities disappear or become useless.","zh":"To destroy old skills 指令傳統能力消失或變得無用。"},{"en":"Some worry that calculators destroy old mental arithmetic skills.","zh":"有些人擔心計數機摧毀舊式心算技能。"},{"en":"New tools may reduce practice in old skills, but they can also create new skills.","zh":"新工具可能減少舊技能練習，但也可以創造新技能。"},{"en":"This phrase presents change as harmful and destructive.","zh":"這個片語把變化呈現為有害和破壞性的。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":16},{"front":"erode critical judgement","meaning":"削弱批判判斷力","examples":[{"en":"Critics fear that new media erode critical judgement.","zh":"批評者擔心新媒體削弱批判判斷力。"},{"en":"To erode critical judgement means to gradually weaken people’s ability to think carefully and evaluate information.","zh":"To erode critical judgement 指逐漸削弱人們仔細思考和評估資訊的能力。"},{"en":"Constant clickbait may erode critical judgement if readers stop checking evidence.","zh":"如果讀者停止查證證據，持續的標題黨內容可能削弱批判判斷力。"},{"en":"If students only consume fast media, they may judge information too quickly.","zh":"如果學生只消費快速媒體，他們可能太快判斷資訊。"},{"en":"This phrase describes slow weakening of careful thinking.","zh":"這個片語描述謹慎思考能力的逐步削弱。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":16},{"front":"critical judgement","meaning":"批判判斷力","examples":[{"en":"Education should protect students’ critical judgement.","zh":"教育應保護學生的批判判斷力。"},{"en":"Critical judgement is the ability to evaluate information, arguments, and evidence carefully.","zh":"Critical judgement 是仔細評估資訊、論點和證據的能力。"},{"en":"A student uses critical judgement when they ask who wrote an article and why.","zh":"當學生問一篇文章由誰撰寫以及為何撰寫時，就是在使用批判判斷力。"},{"en":"Strong critical judgement helps people avoid fake news and weak arguments.","zh":"強大的批判判斷力幫助人避開假新聞和薄弱論點。"},{"en":"This phrase describes careful, independent thinking.","zh":"這個片語描述謹慎而獨立的思考。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":16},{"front":"past generations","meaning":"過去幾代人","examples":[{"en":"Past generations may have been more literate in one sense.","zh":"從某種意義上說，過去幾代人可能更具讀寫能力。"},{"en":"Past generations are people who lived before the present generation.","zh":"Past generations 是生活在當代之前的人們。"},{"en":"Past generations often wrote letters more frequently than many people do today.","zh":"過去幾代人通常比今天許多人更常寫信。"},{"en":"Comparing past generations with today’s children can reveal both losses and gains.","zh":"比較過去幾代人與今天兒童，可以揭示失去和獲得。"},{"en":"This phrase refers to earlier groups of people in history.","zh":"這個片語指歷史中較早的人群。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":16},{"front":"taking the pre-19th century meaning","meaning":"按19世紀前的意思來理解","examples":[{"en":"Taking the pre-19th century meaning of literacy, only a few people were literate.","zh":"按19世紀前對讀寫能力的意思來理解，只有少數人具備讀寫能力。"},{"en":"Taking a meaning means using that definition to understand the word.","zh":"Taking a meaning 指使用某個定義來理解該詞。"},{"en":"Taking the older meaning of “literacy” changes how we judge who was literate.","zh":"按 “literacy” 的舊意思理解，會改變我們判斷誰有讀寫能力的方式。"},{"en":"If a word’s meaning changes, arguments about it may also change.","zh":"如果一個詞的意思改變，關於它的爭論也可能改變。"},{"en":"This phrase asks readers to use an older definition.","zh":"這個片語要求讀者使用較舊定義。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":16},{"front":"a small section of","meaning":"一小部分","examples":[{"en":"Only a small section of the population was once fully literate.","zh":"曾經只有一小部分人口完全具備讀寫能力。"},{"en":"A small section of something means a small part of a larger group.","zh":"A small section of something 指較大群體中的一小部分。"},{"en":"A small section of a class may need extra help with pronunciation.","zh":"班上一小部分學生可能需要額外發音支援。"},{"en":"If only a small section of society has a skill, that skill is not widely shared.","zh":"如果只有一小部分社會成員擁有某技能，該技能就不普及。"},{"en":"This phrase describes a limited part of a whole.","zh":"這個片語描述整體中的有限部分。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":16},{"front":"the population","meaning":"人口","examples":[{"en":"Only a small section of the population had full literary knowledge.","zh":"只有一小部分人口擁有完整文學知識。"},{"en":"The population means all the people living in a country, area, or group.","zh":"The population 指居住在某國家、地區或群體中的所有人。"},{"en":"The population of a city may include children, workers, elderly people, and migrants.","zh":"城市人口可能包括兒童、工人、長者和移民。"},{"en":"If literacy reaches the whole population, more people can participate in public life.","zh":"如果讀寫能力普及到整個人口，更多人能參與公共生活。"},{"en":"This phrase refers to people as a collective group.","zh":"這個片語把人視為集體群體。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":16},{"front":"a 19th-century coinage","meaning":"19世紀創造的詞","examples":[{"en":"The word literacy is a 19th-century coinage.","zh":"“Literacy” 這個詞是19世紀創造的詞。"},{"en":"A 19th-century coinage is a word or expression created in the nineteenth century.","zh":"A 19th-century coinage 是在19世紀創造的詞語或表達。"},{"en":"Some modern education terms are recent coinages created to name new ideas.","zh":"一些現代教育術語是為命名新想法而創造的新詞。"},{"en":"If a word is a coinage, its history can affect how people understand it.","zh":"如果某詞是被創造出來的，其歷史可以影響人們如何理解它。"},{"en":"This phrase describes the historical creation of a term.","zh":"這個片語描述術語的歷史創造。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":17},{"front":"describe the divorce of A from B","meaning":"描述A與B的分離","examples":[{"en":"The term describes the divorce of reading and writing from literary knowledge.","zh":"這個詞描述閱讀和寫作與文學知識的分離。"},{"en":"To describe the divorce of A from B means to show that two things once connected have become separated.","zh":"To describe the divorce of A from B 指顯示兩個曾經相關的事物已經分開。"},{"en":"Some people describe the divorce of exams from real learning when tests measure memory only.","zh":"當測驗只量度記憶，有些人會描述考試與真正學習的分離。"},{"en":"If reading and writing are separated from literature, literacy becomes a technical skill.","zh":"如果閱讀和寫作與文學分離，讀寫能力便成為技術技能。"},{"en":"This phrase describes separation between ideas or practices.","zh":"這個片語描述想法或做法之間的分離。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":17},{"front":"a full knowledge of","meaning":"對……的全面認識","examples":[{"en":"Literacy became separated from a full knowledge of literature.","zh":"讀寫能力開始與對文學的全面認識分離。"},{"en":"A full knowledge of something means deep, broad, and complete understanding of it.","zh":"A full knowledge of something 指對某事有深刻、廣泛而完整的理解。"},{"en":"A historian needs a full knowledge of sources before making strong claims.","zh":"歷史學家在提出強烈主張前，需要對資料來源有全面認識。"},{"en":"A person can read basic texts without having a full knowledge of literature.","zh":"一個人可以閱讀基本文本，而不一定對文學有全面認識。"},{"en":"This phrase describes complete understanding, not basic familiarity.","zh":"這個片語描述完整理解，而不是基本熟悉。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":17},{"front":"education reforms","meaning":"教育改革","examples":[{"en":"Education reforms changed the meaning of literacy.","zh":"教育改革改變了讀寫能力的意思。"},{"en":"Education reforms are changes made to improve or reorganise schools, teaching, exams, or learning goals.","zh":"Education reforms 是為改善或重組學校、教學、考試或學習目標而作出的改變。"},{"en":"Education reforms may introduce new subjects, new tests, or new teaching methods.","zh":"教育改革可能引入新科目、新考試或新教學方法。"},{"en":"When education reforms separate skills from culture, the meaning of literacy may change.","zh":"當教育改革把技能與文化分開，讀寫能力的意思可能改變。"},{"en":"This phrase describes planned changes in education systems.","zh":"這個片語描述教育制度中的有計劃改變。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":17},{"front":"produce something as","meaning":"把……塑造成","examples":[{"en":"The education reforms produced reading and writing as separate skills.","zh":"教育改革把閱讀和寫作塑造成分開的技能。"},{"en":"To produce something as something else means to create or define it in that form.","zh":"To produce something as something else 指把某事創造或界定成某種形式。"},{"en":"A school policy may produce speaking as a separate exam skill.","zh":"學校政策可能把口語塑造成獨立考試技能。"},{"en":"If reforms produce literacy as technical skills, cultural knowledge may seem less central.","zh":"如果改革把讀寫能力塑造成技術技能，文化知識可能顯得較不核心。"},{"en":"This phrase describes how a system shapes the meaning of an activity.","zh":"這個片語描述制度如何塑造活動的意思。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":17},{"front":"separable from","meaning":"可與……分開的","examples":[{"en":"Reading and writing became skills separable from cultural participation.","zh":"閱讀和寫作變成可與文化參與分開的技能。"},{"en":"Separable from means able to be treated as independent from something else.","zh":"Separable from 指可以被視為獨立於另一事物。"},{"en":"Grammar is not always separable from meaning because sentence choices affect interpretation.","zh":"文法不一定可與意思分開，因為句子選擇會影響解讀。"},{"en":"If reading is separable from literature, people may learn the skill without joining literary culture.","zh":"如果閱讀可與文學分開，人們可能學會技能而不參與文學文化。"},{"en":"This phrase describes the possibility of separating two connected things.","zh":"這個片語描述把兩件相關事物分開的可能性。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":17},{"front":"full participation in","meaning":"全面參與","examples":[{"en":"Literacy no longer meant full participation in the cultural heritage.","zh":"讀寫能力不再意味全面參與文化遺產。"},{"en":"Full participation in something means complete involvement in it, not just limited access.","zh":"Full participation in something 指完整參與其中，而不只是有限接觸。"},{"en":"A student has full participation in class when they can listen, speak, read, and contribute.","zh":"當學生能聆聽、發言、閱讀和貢獻，就是全面參與課堂。"},{"en":"If people lack access to literature, they may not have full participation in cultural life.","zh":"如果人們缺乏接觸文學的機會，可能無法全面參與文化生活。"},{"en":"This phrase describes deep involvement rather than surface contact.","zh":"這個片語描述深入參與，而不是表面接觸。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":17},{"front":"cultural heritage","meaning":"文化遺產","examples":[{"en":"Education once connected literacy with the cultural heritage.","zh":"教育曾經把讀寫能力與文化遺產連接起來。"},{"en":"Cultural heritage is the literature, art, music, stories, traditions, and knowledge passed down from the past.","zh":"Cultural heritage 是從過去傳承下來的文學、藝術、音樂、故事、傳統和知識。"},{"en":"A museum protects cultural heritage by preserving objects and explaining their meaning.","zh":"博物館透過保存物件並解釋其意義來保護文化遺產。"},{"en":"If children cannot access cultural heritage, they may feel disconnected from history.","zh":"如果兒童不能接觸文化遺產，他們可能感到與歷史脫節。"},{"en":"This phrase refers to culture inherited from earlier generations.","zh":"這個片語指從前幾代繼承而來的文化。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":17},{"front":"point not only to","meaning":"不但指向","examples":[{"en":"The new media point not only to a cyber-economy but also to the past.","zh":"新媒體不但指向網絡經濟，也指向過去。"},{"en":"To point not only to A but also to B means to suggest or lead toward both things.","zh":"To point not only to A but also to B 指不但暗示或引向A，也引向B。"},{"en":"A school library points not only to study but also to community life.","zh":"學校圖書館不但指向學習，也指向社區生活。"},{"en":"New media may look futuristic, but they can also reconnect people with old culture.","zh":"新媒體可能看起來很未來化，但也可以把人重新連接到舊文化。"},{"en":"This phrase widens the meaning beyond one obvious direction.","zh":"這個片語把意思擴展到一個明顯方向之外。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":17},{"front":"futuristic cyber-economy","meaning":"未來派網絡經濟","examples":[{"en":"New media point to a futuristic cyber-economy.","zh":"新媒體指向未來派網絡經濟。"},{"en":"A futuristic cyber-economy is a future-looking economy based on digital networks, online work, and electronic communication.","zh":"Futuristic cyber-economy 是基於數碼網絡、網上工作和電子溝通的未來式經濟。"},{"en":"Online shops, digital payments, and remote work are parts of a cyber-economy.","zh":"網店、數碼付款和遙距工作都是網絡經濟的一部分。"},{"en":"If literacy is needed online, digital economies may still depend on reading and writing.","zh":"如果網上仍需要讀寫能力，數碼經濟仍可能依賴閱讀和寫作。"},{"en":"This phrase connects new media with future economic life.","zh":"這個片語把新媒體與未來經濟生活連接起來。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":17},{"front":"make something available to","meaning":"使……可供……接觸","examples":[{"en":"New media make the cultural past available to the whole nation.","zh":"新媒體使文化過去可供整個國家接觸。"},{"en":"To make something available to people means to let them access or use it.","zh":"To make something available to people 指讓人們可以接觸或使用某物。"},{"en":"Online libraries make old books available to students far from major cities.","zh":"網上圖書館使舊書可供遠離大城市的學生接觸。"},{"en":"If culture becomes available to more people, education can become more equal.","zh":"如果文化可供更多人接觸，教育可以變得更平等。"},{"en":"This phrase describes opening access.","zh":"這個片語描述開放接觸機會。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":18},{"front":"cultural past","meaning":"文化過去；文化傳統","examples":[{"en":"New media can make our cultural past widely accessible.","zh":"新媒體可以令我們的文化過去被廣泛接觸。"},{"en":"Cultural past means the literature, art, history, stories, and traditions inherited from earlier times.","zh":"Cultural past 指從較早時期繼承下來的文學、藝術、歷史、故事和傳統。"},{"en":"Old films, poems, songs, and historical records are part of a society’s cultural past.","zh":"舊電影、詩歌、歌曲和歷史紀錄都是社會文化過去的一部分。"},{"en":"Digital media can help young people encounter cultural materials they might never seek out alone.","zh":"數碼媒體可以幫助年輕人接觸他們可能不會主動尋找的文化材料。"},{"en":"This phrase points to culture from earlier generations.","zh":"這個片語指來自前幾代的文化。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":18},{"front":"the whole nation","meaning":"整個國家","examples":[{"en":"The writer believes cultural heritage can now reach the whole nation.","zh":"作者相信文化遺產現在可以接觸到整個國家。"},{"en":"The whole nation means all people in a country, not just a small elite group.","zh":"The whole nation 指一個國家的所有人，而不只是小部分精英。"},{"en":"Public broadcasting can bring theatre, history, and literature to the whole nation.","zh":"公共廣播可以把戲劇、歷史和文學帶給整個國家。"},{"en":"If cultural resources reach the whole nation, access becomes more democratic.","zh":"如果文化資源接觸到整個國家，接觸機會便變得更民主。"},{"en":"This phrase emphasises broad national access.","zh":"這個片語強調廣泛的全國接觸。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":18},{"front":"access to","meaning":"接觸……的機會","examples":[{"en":"Children’s access to cultural treasures often begins with television.","zh":"兒童接觸文化珍寶的機會常由電視開始。"},{"en":"Access to something means the chance or ability to use, see, or experience it.","zh":"Access to something 指使用、觀看或體驗某事的機會或能力。"},{"en":"Students with access to libraries can read more widely.","zh":"有機會使用圖書館的學生可以更廣泛閱讀。"},{"en":"If children lack access to books, television or the Internet may become their first cultural doorway.","zh":"如果兒童缺乏接觸書籍的機會，電視或互聯網可能成為他們第一道文化門口。"},{"en":"This phrase focuses on opportunity to reach something.","zh":"這個片語著重接觸某事物的機會。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":18},{"front":"these treasures","meaning":"這些珍貴資源","examples":[{"en":"Television gives children access to cultural treasures.","zh":"電視讓兒童接觸文化珍貴資源。"},{"en":"These treasures means valuable cultural works, knowledge, or traditions mentioned earlier.","zh":"These treasures 指前文提到的有價值文化作品、知識或傳統。"},{"en":"Shakespeare plays, classic novels, and historical documentaries may be cultural treasures.","zh":"莎士比亞戲劇、經典小說和歷史紀錄片都可以是文化珍貴資源。"},{"en":"If children meet these treasures through television, they may later read the original works.","zh":"如果兒童透過電視接觸這些珍貴資源，他們之後可能閱讀原作。"},{"en":"This phrase refers to precious cultural materials.","zh":"這個片語指珍貴文化材料。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":18},{"front":"initially through","meaning":"最初透過","examples":[{"en":"Most children first encounter these treasures initially through television.","zh":"大多數兒童最初透過電視接觸這些珍貴資源。"},{"en":"Initially through means at first by means of a particular route or medium.","zh":"Initially through 指最初經由某個特定途徑或媒介。"},{"en":"Many students initially learn about history through films before reading textbooks.","zh":"許多學生最初透過電影認識歷史，然後才閱讀教科書。"},{"en":"If children initially meet literature through television, screens can lead them toward books.","zh":"如果兒童最初透過電視接觸文學，屏幕可以把他們帶向書本。"},{"en":"This phrase describes the first path of contact.","zh":"這個片語描述最初接觸途徑。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":18},{"front":"literary heritage","meaning":"文學遺產","examples":[{"en":"The writer discusses access to Britain’s literary heritage.","zh":"作者討論接觸英國文學遺產的機會。"},{"en":"Literary heritage means important writing, stories, poems, plays, and authors inherited from the past.","zh":"Literary heritage 指從過去繼承下來的重要寫作、故事、詩歌、戲劇和作家。"},{"en":"Shakespeare and Dickens are often treated as part of Britain’s literary heritage.","zh":"莎士比亞和狄更斯常被視為英國文學遺產的一部分。"},{"en":"If media make literary heritage easier to access, more people may engage with it.","zh":"如果媒體令文學遺產更容易接觸，更多人可能參與其中。"},{"en":"This phrase refers to a society’s inherited literature.","zh":"這個片語指一個社會繼承的文學。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":18},{"front":"be sought out by","meaning":"被……主動尋求","examples":[{"en":"The literary heritage has rarely been sought out by most people.","zh":"文學遺產很少被大多數人主動尋求。"},{"en":"To be sought out by people means to be actively looked for by them.","zh":"To be sought out by people 指被人們主動尋找。"},{"en":"Specialist books may be sought out by researchers but ignored by general readers.","zh":"專門書籍可能被研究人員主動尋求，但被一般讀者忽視。"},{"en":"If cultural works are not sought out, broadcasting may bring them to people indirectly.","zh":"如果文化作品不被主動尋求，廣播可能間接把它們帶給人們。"},{"en":"This phrase describes active searching.","zh":"這個片語描述主動尋找。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":18},{"front":"joined to","meaning":"與……結合","examples":[{"en":"New media can be joined to old media through broadcasting.","zh":"新媒體可以透過廣播與舊媒體結合。"},{"en":"To be joined to something means to be connected or combined with it.","zh":"To be joined to something 指與某事連接或結合。"},{"en":"A printed poem can be joined to a video performance in a lesson.","zh":"印刷詩歌可以在課堂中與影片表演結合。"},{"en":"If new and old media are joined, students may understand both more deeply.","zh":"如果新媒體和舊媒體結合，學生可能更深入理解兩者。"},{"en":"This phrase describes connection rather than opposition.","zh":"這個片語描述連接，而不是對立。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":18},{"front":"public-service tradition","meaning":"公共服務傳統","examples":[{"en":"British broadcasting has a public-service tradition.","zh":"英國廣播有公共服務傳統。"},{"en":"A public-service tradition is a belief that media should educate, inform, and serve the public, not only make profit.","zh":"Public-service tradition 是相信媒體應教育、告知和服務公眾，而不只是賺錢的理念。"},{"en":"A public broadcaster may show documentaries, arts programmes, and educational content.","zh":"公共廣播機構可能播放紀錄片、藝術節目和教育內容。"},{"en":"If broadcasting follows a public-service tradition, it can widen access to culture.","zh":"如果廣播遵循公共服務傳統，它可以擴大文化接觸機會。"},{"en":"This phrase connects media with social responsibility.","zh":"這個片語把媒體與社會責任連接起來。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":18},{"front":"British broadcasting","meaning":"英國廣播","examples":[{"en":"British broadcasting helps make literary tradition available to all.","zh":"英國廣播幫助令文學傳統人人可接觸。"},{"en":"British broadcasting refers to radio and television broadcasting in Britain.","zh":"British broadcasting 指英國的電台和電視廣播。"},{"en":"British broadcasting has often included news, education, drama, documentaries, and cultural programmes.","zh":"英國廣播常包括新聞、教育、戲劇、紀錄片和文化節目。"},{"en":"If broadcasting presents classic literature, people may access culture without first buying books.","zh":"如果廣播呈現經典文學，人們可以不先買書也接觸文化。"},{"en":"This phrase names a media system connected with public culture.","zh":"這個片語命名與公共文化相關的媒體系統。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":19},{"front":"literary tradition","meaning":"文學傳統","examples":[{"en":"New media can make the literary tradition available to everyone.","zh":"新媒體可以令文學傳統人人可接觸。"},{"en":"Literary tradition is the body of important writing, storytelling, and interpretation passed down over time.","zh":"Literary tradition 是隨時間傳承的重要寫作、敘事和詮釋總體。"},{"en":"A country’s literary tradition may include poems, plays, novels, myths, and essays.","zh":"一個國家的文學傳統可能包括詩歌、戲劇、小說、神話和散文。"},{"en":"When media present classic works, they can help more people join the literary tradition.","zh":"當媒體呈現經典作品，它們可以幫助更多人加入文學傳統。"},{"en":"This phrase refers to inherited writing and its cultural meaning.","zh":"這個片語指繼承下來的寫作及其文化意義。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":19},{"front":"available to all","meaning":"人人可接觸的","examples":[{"en":"The writer argues that literature can now be available to all.","zh":"作者認為文學現在可以人人可接觸。"},{"en":"Available to all means accessible to everyone, not only a small group.","zh":"Available to all 指所有人都可接觸，而不只是小部分人。"},{"en":"Online courses can make high-quality lessons available to all students with Internet access.","zh":"網上課程可以令有互聯網的學生都接觸到高質素課堂。"},{"en":"If cultural materials are available to all, education becomes less exclusive.","zh":"如果文化材料人人可接觸，教育便較不排外。"},{"en":"This phrase emphasises open and broad access.","zh":"這個片語強調開放而廣泛的接觸。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":19},{"front":"choose the appropriate letters","meaning":"選出合適字母","examples":[{"en":"Candidates must choose the appropriate letters for the questions.","zh":"考生必須為題目選出合適字母。"},{"en":"Choose the appropriate letters means select the answer letters that best match the questions.","zh":"Choose the appropriate letters 指選出最符合題目的答案字母。"},{"en":"In a reading test, students may choose A, B, C, or D from the options.","zh":"在閱讀測驗中，學生可能從選項中選A、B、C或D。"},{"en":"Choosing the right letter requires understanding meaning, not just matching words.","zh":"選出正確字母需要理解意思，而不只是配對字詞。"},{"en":"This phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":19},{"front":"write them in boxes","meaning":"在方格內填寫答案","examples":[{"en":"Students write their answers in boxes on the answer sheet.","zh":"學生在答題紙方格內填寫答案。"},{"en":"Write them in boxes means put the chosen answers inside the spaces provided.","zh":"Write them in boxes 指把所選答案寫在提供的空格中。"},{"en":"If the answer is B, students should write B clearly in the answer box.","zh":"如果答案是B，學生應在答案方格中清楚寫B。"},{"en":"Writing answers in the wrong place may cause lost marks even if the idea is correct.","zh":"即使想法正確，把答案寫錯位置也可能失分。"},{"en":"This phrase gives practical exam instructions.","zh":"這個片語提供實用考試指示。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":19},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"Candidates write their responses on the answer sheet.","zh":"考生在答題紙上寫下回應。"},{"en":"An answer sheet is the paper or form where students write their final answers.","zh":"Answer sheet 是學生寫最終答案的紙張或表格。"},{"en":"In public exams, the answer sheet may be checked by a computer or examiner.","zh":"在公開考試中，答題紙可能由電腦或考官批改。"},{"en":"Students should transfer answers carefully so they do not lose marks through careless mistakes.","zh":"學生應仔細轉抄答案，以免因粗心錯誤失分。"},{"en":"This phrase refers to the official place for answers.","zh":"這個片語指正式作答位置。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":19},{"front":"when discussing","meaning":"在討論……時","examples":[{"en":"When discussing literacy, the writer notes that the issue is complex.","zh":"在討論讀寫能力時，作者指出這個議題很複雜。"},{"en":"When discussing something means while talking or writing about that topic.","zh":"When discussing something 指在談論或寫作某主題時。"},{"en":"When discussing homework, teachers should consider time, stress, and learning value.","zh":"在討論功課時，老師應考慮時間、壓力和學習價值。"},{"en":"A careful writer considers different evidence when discussing a controversial issue.","zh":"謹慎的作者在討論具爭議議題時會考慮不同證據。"},{"en":"This phrase introduces the topic being examined.","zh":"這個片語引出正在被檢視的主題。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":19},{"front":"the writer notes that","meaning":"作者指出","examples":[{"en":"The writer notes that literacy is related to social and technical contexts.","zh":"作者指出讀寫能力與社會及技術背景有關。"},{"en":"The writer notes that means the writer points out or observes something.","zh":"The writer notes that 指作者指出或觀察到某事。"},{"en":"The writer notes that children often learn differently outside school.","zh":"作者指出兒童在校外常以不同方式學習。"},{"en":"When a writer notes something, they are drawing the reader’s attention to it.","zh":"當作者指出某事，就是把讀者注意力帶到它上面。"},{"en":"This phrase introduces an observation from the text.","zh":"這個片語引出文本中的觀察。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":19},{"front":"be related to","meaning":"與……有關","examples":[{"en":"Literacy is related to external social and technical factors.","zh":"讀寫能力與外在社會及技術因素有關。"},{"en":"To be related to something means to be connected with it.","zh":"To be related to something 指與某事有連繫。"},{"en":"A student’s reading progress may be related to sleep, vocabulary, and home support.","zh":"學生閱讀進步可能與睡眠、詞彙和家庭支援有關。"},{"en":"If literacy is related to technology, new media may change how literacy works.","zh":"如果讀寫能力與科技有關，新媒體可能改變讀寫能力如何運作。"},{"en":"This phrase shows connection or influence.","zh":"這個片語顯示關聯或影響。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":19},{"front":"external factors","meaning":"外在因素","examples":[{"en":"The question asks whether literacy is related to external factors.","zh":"問題問讀寫能力是否與外在因素有關。"},{"en":"External factors are influences outside the person, organisation, or skill itself.","zh":"External factors 是人、組織或技能本身以外的影響。"},{"en":"A student’s performance may be affected by external factors such as noise, family stress, or lack of books.","zh":"學生表現可能受噪音、家庭壓力或缺乏書籍等外在因素影響。"},{"en":"If external factors shape literacy, we cannot judge ability by tests alone.","zh":"如果外在因素塑造讀寫能力，我們不能只靠測驗判斷能力。"},{"en":"This phrase focuses on outside influences.","zh":"這個片語著重外部影響。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":19},{"front":"opposing arguments","meaning":"相反論點","examples":[{"en":"The debate includes opposing arguments about literacy.","zh":"這場辯論包括關於讀寫能力的相反論點。"},{"en":"Opposing arguments are arguments that take different or opposite positions.","zh":"Opposing arguments 是採取不同或相反立場的論點。"},{"en":"In a school debate, one side may support uniforms while the other gives opposing arguments.","zh":"在學校辯論中，一方可能支持校服，另一方提出相反論點。"},{"en":"Opposing arguments help readers see that an issue is not simple.","zh":"相反論點幫助讀者看見議題並不簡單。"},{"en":"This phrase describes disagreement within a discussion.","zh":"這個片語描述討論中的分歧。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":20},{"front":"equally convincing","meaning":"同樣有說服力","examples":[{"en":"The option asks whether the arguments are equally convincing.","zh":"選項問這些論點是否同樣有說服力。"},{"en":"Equally convincing means both arguments seem similarly persuasive or believable.","zh":"Equally convincing 指兩個論點看起來同樣令人信服或可信。"},{"en":"Two essays may be equally convincing if both use clear evidence and strong reasoning.","zh":"如果兩篇文章都使用清楚證據和有力推理，它們可能同樣有說服力。"},{"en":"If one argument has stronger research support, the two sides are not equally convincing.","zh":"如果一方論點有更強研究支持，兩方就不是同樣有說服力。"},{"en":"This phrase compares persuasive strength.","zh":"這個片語比較說服力強弱。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":20},{"front":"main point","meaning":"主要觀點","examples":[{"en":"The question asks for the writer’s main point in the paragraph.","zh":"問題要求找出作者在該段的主要觀點。"},{"en":"The main point is the most important idea the writer wants to communicate.","zh":"Main point 是作者最想傳達的重要想法。"},{"en":"In a reading passage, details support the main point but do not replace it.","zh":"在閱讀文章中，細節支持主要觀點，但不能取代它。"},{"en":"If students focus only on examples, they may miss the main point.","zh":"如果學生只集中例子，可能錯過主要觀點。"},{"en":"This phrase is central to summary and comprehension questions.","zh":"這個片語是摘要和理解題的核心。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":20},{"front":"the printed word","meaning":"印刷文字","examples":[{"en":"The printed word is both gaining and losing power.","zh":"印刷文字既獲得又失去力量。"},{"en":"The printed word means written language in printed form, such as books, newspapers, and magazines.","zh":"Printed word 指以印刷形式出現的書面語，例如書籍、報紙和雜誌。"},{"en":"A textbook is an example of the printed word used in education.","zh":"教科書是在教育中使用印刷文字的例子。"},{"en":"Digital media may reduce some uses of print while also making written language more visible on screens.","zh":"數碼媒體可能減少某些印刷用途，同時又令書面語在屏幕上更可見。"},{"en":"This phrase contrasts print with speech, images, and digital media.","zh":"這個片語把印刷文字與說話、影像和數碼媒體作對比。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":20},{"front":"gaining and losing power","meaning":"既獲得又失去力量","examples":[{"en":"The printed word may be gaining and losing power at the same time.","zh":"印刷文字可能同時既獲得又失去力量。"},{"en":"Gaining and losing power means becoming stronger in some ways but weaker in others.","zh":"Gaining and losing power 指在某些方面變強，但在另一些方面變弱。"},{"en":"A school subject may gain power in exams but lose power in students’ daily interests.","zh":"某科目可能在考試中獲得力量，但在學生日常興趣中失去力量。"},{"en":"Print may lose authority to television for news while gaining importance on computer screens.","zh":"印刷文字可能在新聞方面被電視削弱權威，但在電腦屏幕上變得更重要。"},{"en":"This phrase captures a mixed and complex change.","zh":"這個片語概括混合而複雜的變化。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":20},{"front":"bring disadvantages as well as benefits","meaning":"既帶來壞處也帶來好處","examples":[{"en":"The option suggests that inventions bring disadvantages as well as benefits.","zh":"選項指出發明既帶來壞處也帶來好處。"},{"en":"To bring disadvantages as well as benefits means to create both negative and positive effects.","zh":"To bring disadvantages as well as benefits 指同時造成負面和正面影響。"},{"en":"Smartphones bring convenience as well as distraction.","zh":"智能手機既帶來便利，也帶來分心。"},{"en":"If a new tool saves time but weakens old skills, it has both benefits and drawbacks.","zh":"如果新工具節省時間但削弱舊技能，它便同時有好處和壞處。"},{"en":"This phrase supports a balanced view of change.","zh":"這個片語支持對變化的平衡看法。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":20},{"front":"manual jobs","meaning":"體力勞動工作","examples":[{"en":"The option refers to people who work in manual jobs.","zh":"選項提到從事體力勞動工作的人。"},{"en":"Manual jobs are jobs that mainly involve physical work with the hands or body.","zh":"Manual jobs 是主要涉及用手或身體進行體力工作的職位。"},{"en":"Mechanics, cleaners, builders, and farm workers often do manual jobs.","zh":"技工、清潔工、建築工人和農場工人常從事體力勞動工作。"},{"en":"If instructions become video-based, some workers in manual jobs may rely less on written handbooks.","zh":"如果指示變成影片形式，一些體力勞動工人可能較少依賴書面手冊。"},{"en":"This phrase contrasts physical work with office or knowledge work.","zh":"這個片語把體力工作與辦公室或知識工作作對比。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":20},{"front":"offer the best careers for","meaning":"為……提供最佳事業","examples":[{"en":"The option claims that the media offer the best careers for writers.","zh":"選項聲稱媒體為作家提供最佳事業。"},{"en":"To offer the best careers for someone means to provide the strongest job opportunities for that group.","zh":"To offer the best careers for someone 指為某群體提供最強的工作機會。"},{"en":"The technology industry may offer good careers for people who enjoy problem-solving.","zh":"科技行業可能為喜歡解難的人提供良好事業。"},{"en":"If writing is well rewarded in media, some writers may find strong career paths there.","zh":"如果寫作在媒體中有良好回報，一些作家可能在那裡找到強大職業道路。"},{"en":"This phrase compares job opportunities across fields.","zh":"這個片語比較不同領域的工作機會。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":20},{"front":"face today","meaning":"今天面對","examples":[{"en":"The question asks what problem schools face today.","zh":"問題問學校今天面對甚麼問題。"},{"en":"To face today means to deal with something in the present time.","zh":"To face today 指在當前處理某事。"},{"en":"Schools face today the challenge of teaching both traditional literacy and digital literacy.","zh":"學校今天面對教授傳統讀寫能力和數碼讀寫能力的挑戰。"},{"en":"If teachers face new technology without clear guidance, classroom practice may become confused.","zh":"如果老師在沒有清晰指導下面對新科技，課堂實踐可能變得混亂。"},{"en":"This phrase highlights a current challenge.","zh":"這個片語突顯當前挑戰。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":20},{"front":"incorporate technology into","meaning":"把科技融入……","examples":[{"en":"Schools must decide how to incorporate technology into teaching.","zh":"學校必須決定如何把科技融入教學。"},{"en":"To incorporate technology into something means to include digital tools in a useful and planned way.","zh":"To incorporate technology into something 指以有用和有計劃的方式加入數碼工具。"},{"en":"A teacher can incorporate technology into writing lessons by asking students to edit shared documents.","zh":"老師可以透過要求學生編輯共享文件，把科技融入寫作課。"},{"en":"If technology is incorporated poorly, it may distract rather than support learning.","zh":"如果科技融入得差，它可能分散注意力而不是支持學習。"},{"en":"This phrase describes purposeful integration of digital tools.","zh":"這個片語描述有目的地整合數碼工具。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":20},{"front":"classroom teaching","meaning":"課堂教學","examples":[{"en":"Technology should be incorporated into classroom teaching.","zh":"科技應融入課堂教學。"},{"en":"Classroom teaching means the teaching that happens during lessons with students and teachers.","zh":"Classroom teaching 指老師和學生在課堂中進行的教學。"},{"en":"Classroom teaching may include explanation, discussion, reading, writing, and group work.","zh":"課堂教學可能包括解釋、討論、閱讀、寫作和小組活動。"},{"en":"Technology improves classroom teaching only when it supports clear learning goals.","zh":"科技只有在支持清晰學習目標時，才會改善課堂教學。"},{"en":"This phrase focuses on actual lesson practice.","zh":"這個片語著重實際課堂做法。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":21},{"front":"find the means to","meaning":"找到方法去","examples":[{"en":"The option discusses finding the means to purchase equipment.","zh":"選項討論找到方法去購買設備。"},{"en":"To find the means to do something means to find the money, tools, or method needed to do it.","zh":"To find the means to do something 指找到做某事所需的金錢、工具或方法。"},{"en":"A school may need to find the means to hire more reading teachers.","zh":"學校可能需要找到方法去聘請更多閱讀老師。"},{"en":"Even if a school finds the means to buy computers, it still needs training and planning.","zh":"即使學校找到方法購買電腦，仍需要培訓和規劃。"},{"en":"This phrase focuses on the resources needed for action.","zh":"這個片語著重行動所需資源。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":21},{"front":"purchase technological equipment","meaning":"購買科技設備","examples":[{"en":"Schools may need funds to purchase technological equipment.","zh":"學校可能需要資金購買科技設備。"},{"en":"To purchase technological equipment means to buy digital or electronic tools.","zh":"To purchase technological equipment 指購買數碼或電子工具。"},{"en":"A school may purchase technological equipment such as tablets, cameras, and editing software.","zh":"學校可能購買平板電腦、攝錄機和剪接軟件等科技設備。"},{"en":"Buying equipment without a teaching plan may waste money.","zh":"在沒有教學計劃下購買設備可能浪費金錢。"},{"en":"This phrase refers to acquiring tools, not using them effectively.","zh":"這個片語指取得工具，而不是有效使用工具。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":21},{"front":"widely differing levels of","meaning":"差異很大的……水平","examples":[{"en":"The option refers to widely differing levels of literacy among pupils.","zh":"選項提到學生之間差異很大的讀寫能力水平。"},{"en":"Widely differing levels of something means very large differences in ability or amount.","zh":"Widely differing levels of something 指能力或數量上有很大差異。"},{"en":"A class may have widely differing levels of English if students come from different schools.","zh":"如果學生來自不同學校，一個班可能有差異很大的英語水平。"},{"en":"When levels differ widely, teachers need flexible materials and support.","zh":"當水平差異很大，老師需要彈性教材和支援。"},{"en":"This phrase describes large variation within a group.","zh":"這個片語描述群體內部的大差異。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":21},{"front":"amongst pupils","meaning":"在學生之間","examples":[{"en":"The option discusses literacy levels amongst pupils.","zh":"選項討論學生之間的讀寫能力水平。"},{"en":"Amongst pupils means among students or schoolchildren.","zh":"Amongst pupils 指在學生或學童之間。"},{"en":"Reading habits amongst pupils may differ because some families have more books at home.","zh":"學生之間的閱讀習慣可能不同，因為有些家庭家中有更多書。"},{"en":"If literacy levels vary amongst pupils, one teaching method may not help everyone.","zh":"如果學生之間讀寫能力水平不同，一種教學方法未必幫到所有人。"},{"en":"This phrase locates an issue within a student group.","zh":"這個片語把議題定位於學生群體內。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":21},{"front":"at the end of the article","meaning":"在文章結尾","examples":[{"en":"At the end of the article, the writer discusses access to culture.","zh":"在文章結尾，作者討論接觸文化的機會。"},{"en":"At the end of the article means in the final part of the text.","zh":"At the end of the article 指在文本最後部分。"},{"en":"At the end of an article, writers often return to the main argument.","zh":"在文章結尾，作者常回到主要論點。"},{"en":"If a conclusion appears at the end, students should read it carefully for the writer’s final view.","zh":"如果結論出現在結尾，學生應仔細閱讀，以了解作者最終看法。"},{"en":"This phrase gives the location of information in a text.","zh":"這個片語指出資訊在文本中的位置。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":21},{"front":"be suggesting that","meaning":"正在暗示","examples":[{"en":"The writer is suggesting that cultural information may become more accessible.","zh":"作者正在暗示文化資料可能變得更容易接觸。"},{"en":"To be suggesting that means to imply or gently argue an idea without stating it too directly.","zh":"To be suggesting that 指暗示或較溫和地提出某想法，而不是太直接說出。"},{"en":"A teacher may be suggesting that students need more practice when she gives extra exercises.","zh":"老師給額外練習時，可能正在暗示學生需要更多練習。"},{"en":"Writers often suggest ideas through examples and contrasts.","zh":"作者常透過例子和對比暗示想法。"},{"en":"This phrase describes an implied meaning or cautious claim.","zh":"這個片語描述隱含意思或謹慎主張。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":21},{"front":"literature and culture","meaning":"文學與文化","examples":[{"en":"The option connects literature and culture.","zh":"選項把文學與文化連接起來。"},{"en":"Literature and culture refer to written artistic works and the wider values, traditions, and knowledge of a society.","zh":"Literature and culture 指書面藝術作品，以及社會更廣泛的價值、傳統和知識。"},{"en":"A novel can show literature and culture through language, characters, and social customs.","zh":"小說可以透過語言、人物和社會習俗呈現文學與文化。"},{"en":"If students study literature without culture, they may miss historical and social meaning.","zh":"如果學生學文學時沒有文化背景，可能錯過歷史和社會意義。"},{"en":"This phrase links written works with the society that produced them.","zh":"這個片語把書面作品與創造它們的社會連接起來。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":21},{"front":"be divorced","meaning":"被分離","examples":[{"en":"The option asks whether literature and culture can be divorced.","zh":"選項問文學和文化是否可以被分離。"},{"en":"To be divorced from something means to be separated from it, even though they were once connected.","zh":"To be divorced from something 指與某事分離，即使兩者曾經相連。"},{"en":"Grammar should not be divorced from meaning because sentence form affects communication.","zh":"文法不應與意思分離，因為句子形式影響溝通。"},{"en":"If literature is divorced from culture, students may treat texts as empty language exercises.","zh":"如果文學與文化分離，學生可能把文本視為空洞語言練習。"},{"en":"This phrase describes separation between connected things.","zh":"這個片語描述相關事物之間的分離。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":21},{"front":"not very useful","meaning":"不太有用","examples":[{"en":"The option suggests that the term literacy has not been very useful.","zh":"選項指出 “literacy” 這個術語不太有用。"},{"en":"Not very useful means not especially helpful or effective.","zh":"Not very useful 指不特別有幫助或不太有效。"},{"en":"A dictionary is not very useful if it gives definitions that students cannot understand.","zh":"如果字典給出的定義學生看不懂，它就不太有用。"},{"en":"If a term causes confusion, it may not be very useful in debate.","zh":"如果某術語造成混亂，它在辯論中可能不太有用。"},{"en":"This phrase expresses mild criticism.","zh":"這個片語表達溫和批評。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":21},{"front":"exposure to","meaning":"接觸……","examples":[{"en":"New media may increase our exposure to cultural information.","zh":"新媒體可能增加我們接觸文化資料的機會。"},{"en":"Exposure to something means contact with it or experience of it.","zh":"Exposure to something 指接觸或經歷某事。"},{"en":"Exposure to different books can make students more curious about language.","zh":"接觸不同書籍可以令學生對語言更好奇。"},{"en":"If children gain more exposure to culture, they may later seek deeper knowledge.","zh":"如果兒童更多接觸文化，他們之後可能尋求更深入知識。"},{"en":"This phrase describes access and contact, not full mastery.","zh":"這個片語描述接觸機會，而不是完全掌握。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":22},{"front":"cultural information","meaning":"文化資料","examples":[{"en":"Television and new media can increase access to cultural information.","zh":"電視和新媒體可以增加接觸文化資料的機會。"},{"en":"Cultural information is knowledge about literature, history, art, customs, and shared traditions.","zh":"Cultural information 是關於文學、歷史、藝術、習俗和共同傳統的知識。"},{"en":"A documentary about old poems gives viewers cultural information.","zh":"關於古詩的紀錄片給觀眾文化資料。"},{"en":"If cultural information is presented clearly, more people can understand their heritage.","zh":"如果文化資料被清楚呈現，更多人可以理解自己的遺產。"},{"en":"This phrase refers to knowledge about culture, not just entertainment.","zh":"這個片語指關於文化的知識，而不只是娛樂。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":22},{"front":"be likely to increase","meaning":"很可能增加","examples":[{"en":"Our exposure to cultural information is likely to increase.","zh":"我們接觸文化資料的機會很可能增加。"},{"en":"To be likely to increase means probably to become greater.","zh":"To be likely to increase 指很可能變得更多。"},{"en":"Students’ screen reading is likely to increase as more homework moves online.","zh":"隨着更多功課轉到網上，學生的屏幕閱讀很可能增加。"},{"en":"If more archives go digital, access to cultural information will probably grow.","zh":"如果更多檔案數碼化，接觸文化資料的機會很可能增加。"},{"en":"This phrase predicts a probable upward trend.","zh":"這個片語預測可能的上升趨勢。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":22},{"front":"agree with the views of","meaning":"與……的觀點一致","examples":[{"en":"Candidates decide whether the statements agree with the views of the writer.","zh":"考生判斷陳述是否與作者觀點一致。"},{"en":"To agree with the views of the writer means to match the writer’s opinion or argument.","zh":"To agree with the views of the writer 指與作者的意見或論點相符。"},{"en":"A statement agrees with the writer only if the text clearly supports it.","zh":"只有文本清楚支持某陳述，它才與作者觀點一致。"},{"en":"Students must separate the writer’s view from other people’s views in the passage.","zh":"學生必須把作者觀點與文章中其他人的觀點分開。"},{"en":"This phrase is common in YES/NO/NOT GIVEN questions.","zh":"這個片語常見於YES/NO/NOT GIVEN題型。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":22},{"front":"contradict the views of","meaning":"與……的觀點矛盾","examples":[{"en":"A statement contradicts the writer’s views if it says the opposite.","zh":"如果陳述說出相反意思，它就與作者觀點矛盾。"},{"en":"To contradict the views of someone means to disagree directly with what they think.","zh":"To contradict the views of someone 指直接不同意某人的看法。"},{"en":"If the writer says screens can support literacy, a statement saying screens only harm literacy may contradict the writer.","zh":"如果作者說屏幕可以支持讀寫能力，而陳述說屏幕只會傷害讀寫能力，便可能與作者觀點矛盾。"},{"en":"Students choose NO only when the statement clearly opposes the writer’s view.","zh":"只有當陳述清楚反對作者觀點時，學生才選NO。"},{"en":"This phrase is important for distinguishing NO from NOT GIVEN.","zh":"這個片語對區分NO和NOT GIVEN很重要。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":22},{"front":"it is impossible to say","meaning":"無法判斷","examples":[{"en":"Students choose NOT GIVEN if it is impossible to say what the writer thinks.","zh":"如果無法判斷作者怎樣想，學生選NOT GIVEN。"},{"en":"It is impossible to say means the text does not give enough information to decide.","zh":"It is impossible to say 指文本沒有提供足夠資料讓人判斷。"},{"en":"If a passage never mentions a writer’s opinion on exams, it is impossible to say what they think.","zh":"如果文章從未提及作者對考試的看法，就無法判斷他們怎樣想。"},{"en":"Students should not use outside knowledge when the passage gives no evidence.","zh":"當文章沒有證據時，學生不應使用外部知識。"},{"en":"This phrase signals missing information, not disagreement.","zh":"這個片語標示資料缺失，而不是不同意。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":22},{"front":"analyse literacy levels","meaning":"分析讀寫能力水平","examples":[{"en":"It is not easy to analyse literacy levels in a simple way.","zh":"要以簡單方式分析讀寫能力水平並不容易。"},{"en":"To analyse literacy levels means to examine how strong people’s reading and writing abilities are.","zh":"To analyse literacy levels 指檢視人們閱讀和寫作能力有多強。"},{"en":"A school may analyse literacy levels by looking at reading tests, writing samples, and classroom work.","zh":"學校可能透過閱讀測驗、寫作樣本和課堂作品來分析讀寫能力水平。"},{"en":"If literacy includes digital skills, analysis becomes more complex.","zh":"如果讀寫能力包括數碼技能，分析會變得更複雜。"},{"en":"This phrase describes careful examination of reading and writing ability.","zh":"這個片語描述對閱讀和寫作能力的仔細檢視。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":22},{"front":"as it used to be","meaning":"像以往那樣","examples":[{"en":"Literacy is not as easy to analyse as it used to be.","zh":"讀寫能力不像以往那樣容易分析。"},{"en":"As it used to be means as it was in the past.","zh":"As it used to be 指像過去那樣。"},{"en":"Writing letters is not as common as it used to be before mobile phones.","zh":"在手機出現前，寫信曾像以往那樣常見；現在則少見得多。"},{"en":"If social and technical contexts change, old ways of judging literacy may no longer work.","zh":"如果社會和技術背景改變，舊有判斷讀寫能力的方法可能不再有效。"},{"en":"This phrase compares the present with the past.","zh":"這個片語把現在與過去作比較。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":22},{"front":"highly developed","meaning":"高度發展的","examples":[{"en":"The question asks whether literacy skills need to be highly developed.","zh":"問題問讀寫技能是否需要高度發展。"},{"en":"Highly developed means advanced, strong, and well practised.","zh":"Highly developed 指高階、強大並經充分練習。"},{"en":"A highly developed vocabulary helps students understand difficult articles.","zh":"高度發展的詞彙量幫助學生理解困難文章。"},{"en":"Some jobs require highly developed writing skills, while others need only basic writing.","zh":"有些工作需要高度發展的寫作技能，另一些只需要基本寫作。"},{"en":"This phrase describes a high level of ability.","zh":"這個片語描述高水平能力。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":22},{"front":"in the past","meaning":"在過去","examples":[{"en":"The statement compares today’s literacy needs with those in the past.","zh":"這項陳述把今天的讀寫需要與過去的需要作比較。"},{"en":"In the past means in earlier times.","zh":"In the past 指在較早時期。"},{"en":"In the past, people often wrote letters more frequently than they do today.","zh":"在過去，人們通常比今天更常寫信。"},{"en":"Comparing today with the past helps show how technology changes daily literacy.","zh":"把今天與過去比較，有助顯示科技如何改變日常讀寫。"},{"en":"This phrase places the discussion before the present.","zh":"這個片語把討論放在現在之前。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":22},{"front":"on the increase","meaning":"正在上升","examples":[{"en":"The statement asks whether illiteracy is on the increase.","zh":"這項陳述問文盲問題是否正在上升。"},{"en":"On the increase means becoming more common or greater in number.","zh":"On the increase 指變得更常見或數量更多。"},{"en":"Screen reading is on the increase as more schoolwork moves online.","zh":"隨着更多學校作業轉到網上，屏幕閱讀正在上升。"},{"en":"If illiteracy is on the increase, schools may need urgent support programmes.","zh":"如果文盲問題正在上升，學校可能需要緊急支援計劃。"},{"en":"This phrase describes an upward trend.","zh":"這個片語描述上升趨勢。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":23},{"front":"professional writers","meaning":"專業作家","examples":[{"en":"Professional writers may earn more than they used to.","zh":"專業作家可能比以往賺得更多。"},{"en":"Professional writers are people who earn money by writing as their job.","zh":"Professional writers 是以寫作作為工作賺錢的人。"},{"en":"Journalists, novelists, scriptwriters, and advertising copywriters can be professional writers.","zh":"記者、小說家、編劇和廣告文案都可以是專業作家。"},{"en":"If media industries grow, professional writers may find more paid opportunities.","zh":"如果媒體產業成長，專業作家可能找到更多有薪機會。"},{"en":"This phrase describes writing as paid work, not just a hobby.","zh":"這個片語描述寫作作為有薪工作，而不只是興趣。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":23},{"front":"earn relatively more than","meaning":"相對以往賺得更多","examples":[{"en":"Professional writers earn relatively more than they used to.","zh":"專業作家相對以往賺得更多。"},{"en":"To earn relatively more than before means to receive more money compared with earlier times or other groups.","zh":"To earn relatively more than before 指與早前或其他群體相比收入更多。"},{"en":"Skilled designers may earn relatively more than before as online businesses grow.","zh":"隨着網上業務增長，熟練設計師可能相對以往賺得更多。"},{"en":"If writing becomes valuable in media work, writers’ pay may rise.","zh":"如果寫作在媒體工作中變得有價值，作家的收入可能上升。"},{"en":"This phrase compares income across time or context.","zh":"這個片語比較不同時間或語境中的收入。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":23},{"front":"good literacy level","meaning":"良好的讀寫能力水平","examples":[{"en":"A good literacy level is important for people who work in television.","zh":"良好的讀寫能力水平對從事電視行業的人很重要。"},{"en":"A good literacy level means a strong enough ability to read, write, understand, and communicate effectively.","zh":"Good literacy level 指具備足夠強的閱讀、寫作、理解和有效溝通能力。"},{"en":"A producer needs a good literacy level to read scripts, emails, schedules, and research notes.","zh":"製作人需要良好讀寫能力水平來閱讀劇本、電郵、時間表和研究筆記。"},{"en":"If media workers lack literacy, production planning and communication may suffer.","zh":"如果媒體工作者缺乏讀寫能力，製作規劃和溝通可能受損。"},{"en":"This phrase describes practical reading and writing ability.","zh":"這個片語描述實用閱讀和寫作能力。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":23},{"front":"work in television","meaning":"從事電視行業","examples":[{"en":"People who work in television still need to read and write.","zh":"從事電視行業的人仍需要閱讀和寫作。"},{"en":"To work in television means to be employed in making, planning, producing, or broadcasting TV programmes.","zh":"To work in television 指受僱於製作、規劃、生產或播放電視節目。"},{"en":"A person who works in television may write scripts, read schedules, or edit captions.","zh":"從事電視行業的人可能寫劇本、讀時間表或編輯字幕。"},{"en":"Television work involves images and sound, but it also depends on written planning.","zh":"電視工作涉及影像和聲音，但也依賴書面規劃。"},{"en":"This phrase refers to employment in the TV industry.","zh":"這個片語指在電視行業工作。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":23},{"front":"have a negative impact on","meaning":"對……有負面影響","examples":[{"en":"The statement asks whether computers have a negative impact on literacy.","zh":"這項陳述問電腦是否對讀寫能力有負面影響。"},{"en":"To have a negative impact on something means to harm or weaken it.","zh":"To have a negative impact on something 指傷害或削弱某事。"},{"en":"Poor sleep can have a negative impact on memory and mood.","zh":"睡眠不足可以對記憶和心情有負面影響。"},{"en":"Computers may have a negative impact if they distract students from careful reading.","zh":"如果電腦令學生分心，不能仔細閱讀，它們可能有負面影響。"},{"en":"This phrase describes harmful effect, not neutral change.","zh":"這個片語描述有害影響，而不是中性改變。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":23},{"front":"literacy in schools","meaning":"學校裏的讀寫能力","examples":[{"en":"The role of computers in literacy in schools is debated.","zh":"電腦在學校讀寫能力中的角色受到辯論。"},{"en":"Literacy in schools means how reading, writing, and related communication skills are taught and practised in education.","zh":"Literacy in schools 指閱讀、寫作和相關溝通技能如何在教育中被教授和練習。"},{"en":"Literacy in schools may include books, essays, online research, and digital projects.","zh":"學校裏的讀寫能力可能包括書本、作文、網上研究和數碼項目。"},{"en":"If computers are used well, they can support literacy in schools rather than harm it.","zh":"如果電腦被善用，它們可以支持而不是傷害學校裏的讀寫能力。"},{"en":"This phrase focuses on literacy within formal education.","zh":"這個片語著重正規教育中的讀寫能力。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":23},{"front":"complete the sentences below","meaning":"完成以下句子","examples":[{"en":"Candidates complete the sentences below with words from the passage.","zh":"考生用文章中的字詞完成以下句子。"},{"en":"Complete the sentences below means fill in missing words in the following sentences.","zh":"Complete the sentences below 指填寫下面句子中的缺失字詞。"},{"en":"Students should read the whole sentence before choosing an answer.","zh":"學生應先閱讀整個句子，再選擇答案。"},{"en":"The answer must fit both the grammar of the sentence and the meaning in the passage.","zh":"答案必須同時符合句子文法和文章意思。"},{"en":"This phrase is a common reading-test instruction.","zh":"這個片語是常見閱讀測驗指示。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":23},{"front":"words taken from","meaning":"取自……的字詞","examples":[{"en":"Answers must use words taken from the reading passage.","zh":"答案必須使用取自閱讀文章的字詞。"},{"en":"Words taken from means exact words copied or selected from a source text.","zh":"Words taken from 指從來源文本中抄取或選出的原字詞。"},{"en":"In IELTS reading, answers often require words taken from the passage, not invented synonyms.","zh":"在IELTS閱讀中，答案常要求使用取自文章的字詞，而不是自創同義詞。"},{"en":"If students change the wording, the answer may become incorrect.","zh":"如果學生改變用字，答案可能變錯。"},{"en":"This phrase tells students to stay close to the original text.","zh":"這個片語提醒學生緊扣原文。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":23},{"front":"no more than three words","meaning":"不多於三個字","examples":[{"en":"Students must use no more than three words for each answer.","zh":"學生每個答案必須使用不多於三個字。"},{"en":"No more than three words means the answer may contain one, two, or three words only.","zh":"No more than three words 指答案只能包含一、二或三個字。"},{"en":"If the answer has four words, it breaks the instruction even if the idea is correct.","zh":"如果答案有四個字，即使意思正確也違反指示。"},{"en":"Students should copy only the necessary words from the passage.","zh":"學生應只從文章中抄寫必要字詞。"},{"en":"This phrase controls the maximum answer length.","zh":"這個片語控制答案的最長長度。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":23},{"front":"the best readers","meaning":"最好的讀者","examples":[{"en":"In Renaissance England, the best readers could read manuscript.","zh":"在文藝復興時期的英格蘭，最好的讀者能閱讀手稿。"},{"en":"The best readers are people with the strongest reading ability in a group.","zh":"The best readers 是一個群體中閱讀能力最強的人。"},{"en":"The best readers in a class may understand difficult texts without much help.","zh":"班中最好的讀者可能不太需要幫助也能理解困難文本。"},{"en":"If only the best readers can read manuscript, the task must be difficult.","zh":"如果只有最好的讀者能閱讀手稿，這項任務一定很困難。"},{"en":"This phrase identifies the most skilled readers.","zh":"這個片語指出最熟練的讀者。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":24},{"front":"able to read","meaning":"能夠閱讀","examples":[{"en":"The best readers were able to read difficult manuscript.","zh":"最好的讀者能夠閱讀困難手稿。"},{"en":"Able to read means having the skill to understand written words or texts.","zh":"Able to read 指有能力理解書面文字或文本。"},{"en":"A child is able to read simple signs before they can read long stories.","zh":"孩子可能在能讀長故事前，已能閱讀簡單標誌。"},{"en":"Being able to read opens access to books, instructions, forms, and online information.","zh":"能夠閱讀讓人接觸書籍、指示、表格和網上資訊。"},{"en":"This phrase describes reading ability, not necessarily writing ability.","zh":"這個片語描述閱讀能力，而不一定是寫作能力。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":24},{"front":"illustrate the general fall in","meaning":"說明……的普遍下降","examples":[{"en":"The writer uses tabloids to illustrate the general fall in certain literacy skills.","zh":"作者使用小報來說明某些讀寫技能的普遍下降。"},{"en":"To illustrate the general fall in something means to use an example to show a broad decline.","zh":"To illustrate the general fall in something 指用例子顯示某事廣泛下降。"},{"en":"A teacher may use spelling tests to illustrate the general fall in students’ accuracy.","zh":"老師可能使用串字測驗來說明學生準確度的普遍下降。"},{"en":"If one example clearly shows a trend, it can help readers understand the wider problem.","zh":"如果一個例子清楚顯示趨勢，它可以幫助讀者理解更廣泛問題。"},{"en":"This phrase connects a specific example with a wider decline.","zh":"這個片語把具體例子與較廣泛下降連接起來。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":24},{"front":"general fall","meaning":"普遍下降","examples":[{"en":"The passage points to a general fall in vocabulary and syntax.","zh":"文章指出詞彙和句法普遍下降。"},{"en":"A general fall is a broad decline across a whole area or group.","zh":"General fall 是整個範圍或群體中的廣泛下降。"},{"en":"A school may notice a general fall in reading scores after long online disruption.","zh":"長期網上干擾後，學校可能注意到閱讀分數普遍下降。"},{"en":"A general fall does not mean every individual has declined equally.","zh":"普遍下降不代表每個個體都同樣下降。"},{"en":"This phrase describes an overall downward trend.","zh":"這個片語描述整體下降趨勢。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":24},{"front":"certain areas of literacy","meaning":"讀寫能力的某些範疇","examples":[{"en":"The article discusses a decline in certain areas of literacy.","zh":"文章討論讀寫能力某些範疇的下降。"},{"en":"Certain areas of literacy are particular parts of reading, writing, or language ability.","zh":"Certain areas of literacy 是閱讀、寫作或語言能力中的特定部分。"},{"en":"Vocabulary, syntax, spelling, and argument writing are certain areas of literacy.","zh":"詞彙、句法、串字和論證寫作都是讀寫能力的某些範疇。"},{"en":"A student may improve in reading speed while still struggling in certain areas of writing.","zh":"學生可能閱讀速度進步，但仍在寫作某些範疇吃力。"},{"en":"This phrase avoids saying all literacy has declined.","zh":"這個片語避免說所有讀寫能力都下降。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":24},{"front":"it has been shown that","meaning":"已顯示","examples":[{"en":"It has been shown that many people write very little after leaving school.","zh":"已顯示許多人離校後寫作很少。"},{"en":"It has been shown that means evidence has demonstrated or indicated something.","zh":"It has been shown that 指證據已證明或顯示某事。"},{"en":"It has been shown that regular reading helps students build vocabulary.","zh":"已顯示定期閱讀幫助學生建立詞彙。"},{"en":"This phrase gives a claim more authority because it refers to evidence.","zh":"這個片語因提到證據而令主張更具權威。"},{"en":"It is often used in academic or formal writing.","zh":"它常用於學術或正式寫作。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":24},{"front":"after leaving school","meaning":"離校後","examples":[{"en":"After leaving school, many people write only shopping lists.","zh":"離校後，許多人只寫購物清單。"},{"en":"After leaving school means after finishing formal education at school.","zh":"After leaving school 指完成學校正規教育之後。"},{"en":"After leaving school, some adults rarely write long essays again.","zh":"離校後，一些成年人很少再寫長文章。"},{"en":"If people write less after leaving school, their writing fluency may weaken.","zh":"如果人們離校後寫得較少，寫作流暢度可能變弱。"},{"en":"This phrase marks the period after school education ends.","zh":"這個片語標示學校教育結束後的時期。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":24},{"front":"a lot of people write","meaning":"很多人寫","examples":[{"en":"The passage says that a lot of people write little outside education.","zh":"文章說很多人在教育以外寫得很少。"},{"en":"A lot of people write means many people use writing in some situation.","zh":"A lot of people write 指很多人在某種情況下使用寫作。"},{"en":"A lot of people write messages every day, but fewer write formal letters.","zh":"很多人每天寫訊息，但較少人寫正式書信。"},{"en":"If many people write only short notes, longer writing skills may receive less practice.","zh":"如果很多人只寫短便條，較長寫作技能可能得到較少練習。"},{"en":"This phrase describes a common behaviour among many people.","zh":"這個片語描述許多人共有的行為。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":24},{"front":"the only things that","meaning":"唯一……的東西","examples":[{"en":"For many people, the only things they write are shopping lists.","zh":"對許多人來說，他們唯一寫的東西是購物清單。"},{"en":"The only things that means the sole items or activities in a group.","zh":"The only things that 指某群體中唯一的項目或活動。"},{"en":"The only things a tired student reads may be short messages and exam notes.","zh":"疲倦學生唯一閱讀的東西可能是短訊和考試筆記。"},{"en":"If the only things people write are lists, their writing practice is very limited.","zh":"如果人們唯一寫的東西是清單，他們的寫作練習便非常有限。"},{"en":"This phrase emphasises restriction to one small category.","zh":"這個片語強調只限於一個小類別。"}],"source":"99 - READING THE SCREEN.pdf","sourcePage":24}],"ielts/reading/passage-2/Practice 100":[{"front":"Wheel of Fortune","meaning":"命運之輪；際遇轉變","examples":[{"en":"The title “Wheel of Fortune” suggests that technological change can alter companies’ fortunes.","zh":"標題 “Wheel of Fortune” 暗示科技轉變可以改變公司的命運。"},{"en":"Wheel of Fortune refers to sudden changes in success, failure, luck, or business position.","zh":"Wheel of Fortune 指成功、失敗、運氣或商業位置的突然轉變。"},{"en":"A small shop may experience its own wheel of fortune when a new train station brings many customers.","zh":"當新火車站帶來大量顧客，小店可能經歷自己的命運之輪。"},{"en":"If a company fails to adapt to change, the wheel of fortune can turn against it quickly.","zh":"如果公司未能適應轉變，命運之輪可以很快轉向不利。"},{"en":"The phrase suggests that success is not fixed; luck and circumstances can change.","zh":"這個短語暗示成功並非固定；運氣和環境可以改變。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":1},{"front":"potential effects of","meaning":"……的潛在影響","examples":[{"en":"Emma Duncan discusses the potential effects of the digital revolution.","zh":"Emma Duncan 討論數碼革命的潛在影響。"},{"en":"Potential effects of something are the possible results it may produce in the future.","zh":"potential effects of 某事，是它將來可能造成的結果。"},{"en":"Teachers may discuss the potential effects of phones on students’ attention.","zh":"老師可能討論手機對學生專注力的潛在影響。"},{"en":"If a new road is built, the potential effects include less traffic but more noise.","zh":"如果興建新道路，潛在影響包括交通減少但噪音增加。"},{"en":"The phrase is useful when results are possible but not yet certain.","zh":"這個短語適用於結果可能出現但尚未確定時。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":1},{"front":"the digital revolution","meaning":"數碼革命","examples":[{"en":"The digital revolution may transform the entertainment industry.","zh":"數碼革命可能改變娛樂產業。"},{"en":"The digital revolution is the major change caused by computers, the Internet, and digital information.","zh":"the digital revolution 是由電腦、互聯網和數碼資訊造成的重大轉變。"},{"en":"Online banking is part of the digital revolution because people no longer need to visit banks for every service.","zh":"網上銀行是數碼革命的一部分，因為人們不再需要每項服務都親身到銀行辦理。"},{"en":"The digital revolution can make services faster, but it can also disrupt old jobs.","zh":"數碼革命可以令服務更快，但也可以衝擊舊工作。"},{"en":"The phrase describes a deep technological shift, not just one new device.","zh":"這個短語描述深層科技轉變，而不只是單一新裝置。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":1},{"front":"the entertainment industry","meaning":"娛樂產業；娛樂業","examples":[{"en":"The entertainment industry has been changed by many new technologies.","zh":"娛樂產業已被許多新科技改變。"},{"en":"The entertainment industry includes businesses that produce music, films, television, games, shows, and other leisure content.","zh":"the entertainment industry 包括製作音樂、電影、電視、遊戲、表演和其他休閒內容的企業。"},{"en":"Streaming platforms have become an important part of the entertainment industry.","zh":"串流平台已成為娛樂產業的重要部分。"},{"en":"If audiences change how they watch films, the entertainment industry must change its business model.","zh":"如果觀眾改變觀看電影的方式，娛樂產業就必須改變其商業模式。"},{"en":"The phrase refers to a whole business sector, not just performers.","zh":"這個短語指整個商業界別，而不只是表演者。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":1},{"front":"moving pictures","meaning":"電影；活動影像","examples":[{"en":"Moving pictures were invented about a century ago.","zh":"電影大約在一個世紀前被發明。"},{"en":"Moving pictures are films or images that appear to move on a screen.","zh":"moving pictures 是在螢幕上看似會移動的電影或影像。"},{"en":"Children may first understand moving pictures by watching cartoons on television.","zh":"孩子可能透過在電視上看卡通，最初理解活動影像。"},{"en":"When moving pictures became popular, stories could be shown visually to large audiences.","zh":"當電影變得流行，故事就可以用視覺方式展示給大量觀眾。"},{"en":"The phrase is an older way to refer to cinema or film.","zh":"這個短語是指電影或影片的較舊說法。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":1},{"front":"a century ago","meaning":"一個世紀前","examples":[{"en":"Moving pictures were invented a century ago.","zh":"電影在一個世紀前被發明。"},{"en":"A century ago means one hundred years before the time being discussed.","zh":"a century ago 指所討論時間的一百年前。"},{"en":"A century ago, most students wrote letters instead of sending instant messages.","zh":"一個世紀前，大多數學生寫信，而不是發即時訊息。"},{"en":"If a technology began a century ago, it has had time to change many parts of society.","zh":"如果一項科技在一個世紀前開始，它已有時間改變社會許多部分。"},{"en":"The phrase gives a broad historical time reference.","zh":"這個短語提供概括的歷史時間參照。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":1},{"front":"a new way of","meaning":"……的新方式","examples":[{"en":"A new way of distributing entertainment emerges about once every generation.","zh":"大約每一代都會出現一種發放娛樂內容的新方式。"},{"en":"A new way of doing something means a different method for doing it.","zh":"a new way of doing something 指做某事的不同方法。"},{"en":"Online classes became a new way of learning when schools could not open.","zh":"當學校不能開放時，網課成為學習的新方式。"},{"en":"A new way of shopping can change how shops, workers, and customers behave.","zh":"購物的新方式可以改變商店、員工和顧客的行為。"},{"en":"The phrase introduces a changed method or approach.","zh":"這個短語引出改變了的方法或做法。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":1},{"front":"distributing entertainment to consumers","meaning":"向消費者發放娛樂內容","examples":[{"en":"New technologies change the way companies distribute entertainment to consumers.","zh":"新科技改變公司向消費者發放娛樂內容的方式。"},{"en":"Distributing entertainment to consumers means delivering films, music, games, or shows to the people who use them.","zh":"distributing entertainment to consumers 指把電影、音樂、遊戲或節目送到使用者手中。"},{"en":"A streaming app distributes entertainment to consumers through phones, TVs, and computers.","zh":"串流應用程式透過手機、電視和電腦向消費者發放娛樂內容。"},{"en":"If distribution becomes cheaper, companies can reach more consumers in more places.","zh":"如果發放成本降低，公司就能接觸更多地方的更多消費者。"},{"en":"The phrase focuses on how entertainment travels from producer to audience.","zh":"這個短語重點在娛樂內容如何由製作方到達觀眾。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":1},{"front":"emerge","meaning":"出現；冒起","examples":[{"en":"A new form of entertainment distribution emerges about once every generation.","zh":"大約每一代都會出現一種新的娛樂發放形式。"},{"en":"To emerge means to appear, develop, or become noticeable.","zh":"emerge 指出現、發展或變得明顯。"},{"en":"A new problem may emerge when too many students use the same online platform at once.","zh":"當太多學生同時使用同一個網上平台，新問題可能出現。"},{"en":"When cheaper competitors emerge, older companies may need to improve quickly.","zh":"當較便宜的競爭者冒起，老牌公司可能需要迅速改善。"},{"en":"The word suggests something becoming visible or important over time.","zh":"這個字暗示某事隨時間變得可見或重要。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":1},{"front":"about once every generation","meaning":"大約每一代一次","examples":[{"en":"A major innovation in entertainment appears about once every generation.","zh":"娛樂方面的重大創新大約每一代出現一次。"},{"en":"About once every generation means roughly one time during the lifetime of each new group of people.","zh":"about once every generation 指大約在每一代人的生命時期中出現一次。"},{"en":"A school may change its whole teaching system about once every generation.","zh":"學校可能大約每一代全面改變一次教學制度。"},{"en":"If major changes happen about once every generation, each age group faces a different world.","zh":"如果重大轉變大約每一代發生一次，每個年齡群體都會面對不同世界。"},{"en":"The phrase gives an approximate frequency, not an exact schedule.","zh":"這個短語提供大概頻率，而不是精確時間表。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":1},{"front":"each such innovation","meaning":"每一項這類創新","examples":[{"en":"Each such innovation has changed the entertainment industry irreversibly.","zh":"每一項這類創新都不可逆轉地改變了娛樂產業。"},{"en":"Each such innovation means every new invention or method of the kind just mentioned.","zh":"each such innovation 指剛提及那類每一項新發明或新方法。"},{"en":"Each such innovation in transport, from buses to apps, changes how people plan journeys.","zh":"從巴士到應用程式，交通上的每一項這類創新都改變人們如何規劃旅程。"},{"en":"If each such innovation affects customers, companies must decide whether to resist or adapt.","zh":"如果每一項這類創新都影響顧客，公司就必須決定抗拒還是適應。"},{"en":"The phrase refers back to a series of similar changes.","zh":"這個短語指回一連串相似的轉變。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":2},{"front":"change the industry irreversibly","meaning":"不可逆轉地改變行業","examples":[{"en":"Digital technology may change the industry irreversibly.","zh":"數碼科技可能不可逆轉地改變行業。"},{"en":"To change the industry irreversibly means to alter a business sector so deeply that it cannot return to its old form.","zh":"change the industry irreversibly 指深層改變一個商業界別，使它不能回到舊形式。"},{"en":"Online booking changed the travel industry irreversibly because customers could compare prices instantly.","zh":"網上預訂不可逆轉地改變旅遊業，因為顧客可以即時比較價格。"},{"en":"If streaming replaces physical sales, it may change the music industry irreversibly.","zh":"如果串流取代實體銷售，它可能不可逆轉地改變音樂產業。"},{"en":"The phrase suggests permanent structural change.","zh":"這個短語暗示永久性的結構轉變。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":2},{"front":"be accompanied by","meaning":"伴隨着","examples":[{"en":"Each innovation has been accompanied by fear and excitement.","zh":"每項創新都伴隨着恐懼和興奮。"},{"en":"To be accompanied by something means to happen together with it.","zh":"be accompanied by 某事，意思是與它同時出現。"},{"en":"A new school rule may be accompanied by confusion during the first week.","zh":"新校規在第一星期可能伴隨混亂。"},{"en":"If rapid change is accompanied by fear, people may need clear explanations and support.","zh":"如果快速轉變伴隨恐懼，人們可能需要清楚解釋和支援。"},{"en":"The phrase shows that two things occur side by side.","zh":"這個短語顯示兩件事並行發生。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":2},{"front":"a period of fear","meaning":"一段恐懼時期","examples":[{"en":"New technology can bring a period of fear to existing companies.","zh":"新科技可以為現有公司帶來一段恐懼時期。"},{"en":"A period of fear is a time when people feel worried about what may happen next.","zh":"a period of fear 是人們擔心接下來會發生甚麼的一段時間。"},{"en":"A company may enter a period of fear when a strong new competitor opens nearby.","zh":"當強大的新競爭者在附近開業，公司可能進入一段恐懼時期。"},{"en":"If workers do not understand a new system, a period of fear may slow down adoption.","zh":"如果員工不理解新系統，一段恐懼時期可能減慢採用速度。"},{"en":"The phrase describes temporary anxiety during change.","zh":"這個短語描述轉變期間的暫時焦慮。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":2},{"front":"fear mixed with exhilaration","meaning":"既恐懼又興奮","examples":[{"en":"Technological innovation is often met with fear mixed with exhilaration.","zh":"科技創新常令人既恐懼又興奮。"},{"en":"Fear mixed with exhilaration means people feel both anxious and excited at the same time.","zh":"fear mixed with exhilaration 指人同時感到焦慮和興奮。"},{"en":"A student may feel fear mixed with exhilaration before giving a first public speech.","zh":"學生第一次公開演講前，可能既恐懼又興奮。"},{"en":"If a new job offers opportunity but uncertainty, it can create fear mixed with exhilaration.","zh":"如果新工作帶來機會但也有不確定性，它可以令人既恐懼又興奮。"},{"en":"The phrase describes mixed emotions, not simple happiness or simple worry.","zh":"這個短語描述混合情緒，而不是單純快樂或單純擔心。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":2},{"front":"exhilaration","meaning":"興奮；雀躍","examples":[{"en":"The arrival of a new technology can create exhilaration as well as fear.","zh":"新科技的出現可以帶來恐懼，也可以帶來興奮。"},{"en":"Exhilaration is a strong feeling of excitement, energy, and joy.","zh":"exhilaration 是強烈的興奮、活力和喜悅感。"},{"en":"A runner may feel exhilaration after finishing a difficult race.","zh":"跑手完成艱難比賽後，可能感到雀躍。"},{"en":"If students finally solve a hard problem, exhilaration may replace frustration.","zh":"如果學生終於解決一道難題，興奮可能取代挫敗感。"},{"en":"The word describes intense excitement, not calm satisfaction.","zh":"這個字描述強烈興奮，而不是平靜滿足。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":2},{"front":"the arrival of","meaning":"……的出現","examples":[{"en":"The arrival of digital technology marks a major period of change.","zh":"數碼科技的出現標誌着一個重大轉變時期。"},{"en":"The arrival of something means the time when it appears or begins to be used.","zh":"the arrival of 某物，指它出現或開始被使用的時候。"},{"en":"The arrival of online lessons changed how many students studied at home.","zh":"網課的出現改變了許多學生在家學習的方式。"},{"en":"If the arrival of a new product excites customers, competitors may react quickly.","zh":"如果新產品的出現令顧客興奮，競爭者可能迅速反應。"},{"en":"The phrase focuses on the beginning of a new presence or influence.","zh":"這個短語重點在新的存在或影響開始出現。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":2},{"front":"digital technology","meaning":"數碼科技","examples":[{"en":"Digital technology translates music, pictures and text into computer language.","zh":"數碼科技把音樂、圖片和文字轉換成電腦語言。"},{"en":"Digital technology uses computer-based systems to store, process, and share information.","zh":"digital technology 使用電腦系統來儲存、處理和分享資訊。"},{"en":"A school uses digital technology when students submit homework through an online platform.","zh":"當學生透過網上平台提交功課，學校就是使用數碼科技。"},{"en":"If digital technology spreads, businesses can reach customers faster and more cheaply.","zh":"如果數碼科技普及，企業就能更快和更低成本地接觸顧客。"},{"en":"The phrase includes computers, smartphones, the Internet, and digital media systems.","zh":"這個短語包括電腦、智能手機、互聯網和數碼媒體系統。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":2},{"front":"translate something into","meaning":"把……轉換成","examples":[{"en":"Digital technology translates music and pictures into computer language.","zh":"數碼科技把音樂和圖片轉換成電腦語言。"},{"en":"To translate something into another form means to change it so it can be understood or used in that form.","zh":"translate something into 另一形式，指把某物改變成可在該形式中被理解或使用。"},{"en":"A teacher may translate a difficult rule into simple examples for beginners.","zh":"老師可能把困難規則轉換成簡單例子給初學者。"},{"en":"If a camera translates light into digital data, the picture can be stored on a phone.","zh":"如果相機把光線轉換成數碼數據，圖片就可以儲存在手機中。"},{"en":"The phrase can describe language translation or conversion into another system.","zh":"這個短語可以描述語言翻譯，也可以描述轉換成另一系統。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":2},{"front":"zeros and ones","meaning":"0 和 1","examples":[{"en":"Digital technology converts information into zeros and ones.","zh":"數碼科技把資訊轉換成 0 和 1。"},{"en":"Zeros and ones are the basic binary digits used by computers to represent information.","zh":"zeros and ones 是電腦用來表示資訊的基本二進制數字。"},{"en":"A photo on a phone is stored as zeros and ones, even though users see colours and shapes.","zh":"手機上的照片雖然用戶看到顏色和形狀，但其實以 0 和 1 儲存。"},{"en":"If music becomes zeros and ones, it can be copied, streamed, and edited by computers.","zh":"如果音樂變成 0 和 1，它就可以被電腦複製、串流和編輯。"},{"en":"The phrase explains the basic language of digital information.","zh":"這個短語解釋數碼資訊的基本語言。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":2},{"front":"computer language","meaning":"電腦語言","examples":[{"en":"Music, pictures and text can be translated into computer language.","zh":"音樂、圖片和文字可以被轉換成電腦語言。"},{"en":"Computer language is a system of digital instructions or code that computers can process.","zh":"computer language 是電腦可以處理的數碼指令或代碼系統。"},{"en":"Programmers use computer language to tell apps what to do.","zh":"程式員使用電腦語言告訴應用程式做甚麼。"},{"en":"If a song is changed into computer language, it can be stored and played by digital devices.","zh":"如果歌曲被轉換成電腦語言，它就可以被數碼裝置儲存和播放。"},{"en":"The phrase refers to how computers represent and handle information.","zh":"這個短語指電腦表示和處理資訊的方式。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":3},{"front":"mark one of those periods","meaning":"標誌着其中一個時期","examples":[{"en":"The arrival of digital technology marks one of those periods of change.","zh":"數碼科技的出現標誌着其中一個轉變時期。"},{"en":"To mark one of those periods means to signal or identify one important stage in a repeating pattern.","zh":"mark one of those periods 指標示或指出一個重複模式中的重要階段。"},{"en":"The start of exams marks one of those periods when students must manage time carefully.","zh":"考試開始標誌着學生必須小心管理時間的其中一個時期。"},{"en":"If a new technology marks one of those periods, companies should expect both risk and opportunity.","zh":"如果新科技標誌着其中一個時期，公司就應預期風險和機遇並存。"},{"en":"The phrase points to a recognisable phase in history or experience.","zh":"這個短語指出歷史或經驗中可辨認的一個階段。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":3},{"front":"sound familiar","meaning":"聽起來熟悉","examples":[{"en":"This may sound familiar because the digital revolution has been discussed for years.","zh":"這可能聽起來熟悉，因為數碼革命已被討論多年。"},{"en":"To sound familiar means to seem known because you have heard or experienced something similar before.","zh":"sound familiar 指因曾聽過或經歷過相似事物而感到熟悉。"},{"en":"A student may say a grammar rule sounds familiar after hearing it in an earlier lesson.","zh":"學生在早前課堂聽過文法規則後，可能說它聽起來熟悉。"},{"en":"If a warning sounds familiar, it may be because the same problem has happened before.","zh":"如果一個警告聽起來熟悉，可能是因為同一問題曾經發生。"},{"en":"The phrase describes recognition, even when the details are not fully remembered.","zh":"這個短語描述認得某事，即使細節未必完全記得。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":3},{"front":"the explosion of choice","meaning":"選擇急增","examples":[{"en":"The digital revolution was expected to bring an explosion of choice.","zh":"人們預期數碼革命會帶來選擇急增。"},{"en":"The explosion of choice means a sudden and very large increase in available options.","zh":"the explosion of choice 指可用選項突然大幅增加。"},{"en":"Streaming services created an explosion of choice for people who watch films at home.","zh":"串流服務為在家看電影的人帶來選擇急增。"},{"en":"If consumers face an explosion of choice, they may enjoy freedom but feel overwhelmed.","zh":"如果消費者面對選擇急增，他們可能享有自由，但也感到不知所措。"},{"en":"The phrase suggests rapid growth in options, not a physical explosion.","zh":"這個短語暗示選項快速增長，而不是實際爆炸。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":3},{"front":"go with","meaning":"與……一起出現","examples":[{"en":"An explosion of choice would go with the digital revolution.","zh":"選擇急增會與數碼革命一起出現。"},{"en":"To go with something means to happen together with it or naturally belong with it.","zh":"go with 某事，意思是與它同時發生或自然相配。"},{"en":"Extra homework often goes with exam preparation.","zh":"額外功課常與考試準備一起出現。"},{"en":"If convenience goes with higher cost, customers must decide whether it is worth paying for.","zh":"如果便利與更高成本一起出現，顧客就必須決定是否值得付錢。"},{"en":"The phrase links two things that appear together.","zh":"這個短語把兩件同時出現的事連繫起來。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":3},{"front":"be heralded","meaning":"被預告；被宣揚即將來臨","examples":[{"en":"The digital revolution has been heralded for some time.","zh":"數碼革命一段時間以來一直被預告即將來臨。"},{"en":"To be heralded means to be announced, predicted, or presented as coming soon.","zh":"be heralded 指被宣布、預測或宣揚為即將出現。"},{"en":"A new railway line may be heralded as the solution to traffic problems before it opens.","zh":"新鐵路線在開通前可能被宣揚為交通問題的解決方案。"},{"en":"If a product is heralded too early, people may lose interest before it arrives.","zh":"如果產品太早被預告，人們可能在它到來前已失去興趣。"},{"en":"The phrase often suggests public expectation before an event.","zh":"這個短語常暗示事件發生前的公眾期待。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":3},{"front":"for some time","meaning":"一段時間以來","examples":[{"en":"The digital revolution had been predicted for some time.","zh":"數碼革命一段時間以來已被預測。"},{"en":"For some time means for a fairly long period, though the exact length is not stated.","zh":"for some time 指持續了相當一段時間，但沒有說明確實長度。"},{"en":"The school has been planning the new library for some time.","zh":"學校一段時間以來一直在籌劃新圖書館。"},{"en":"If a problem has existed for some time, people may wonder why it was not solved earlier.","zh":"如果問題已存在一段時間，人們可能會問為何不早點解決。"},{"en":"The phrase gives an imprecise but noticeable duration.","zh":"這個短語提供不精確但明顯的持續時間。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":3},{"front":"chief executive of","meaning":"……的行政總裁","examples":[{"en":"John Malone was the chief executive of TCI.","zh":"John Malone 是 TCI 的行政總裁。"},{"en":"The chief executive of a company is the senior leader responsible for major decisions.","zh":"chief executive of 一間公司，是負責重大決策的最高層領導。"},{"en":"The chief executive of a hospital group may decide where new clinics should open.","zh":"醫院集團的行政總裁可能決定新診所應在哪裏開設。"},{"en":"If the chief executive makes a poor strategy, the whole company may suffer.","zh":"如果行政總裁制定差劣策略，整間公司都可能受害。"},{"en":"The phrase identifies a person’s top management role.","zh":"這個短語指出某人的最高管理職位。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":3},{"front":"a cable giant","meaning":"有線電視巨企","examples":[{"en":"TCI was an American cable giant.","zh":"TCI 是一間美國有線電視巨企。"},{"en":"A cable giant is a very large and powerful cable television company.","zh":"a cable giant 是非常大型且有影響力的有線電視公司。"},{"en":"A cable giant can control many channels and reach millions of homes.","zh":"有線電視巨企可以控制許多頻道並接觸數百萬家庭。"},{"en":"If a cable giant invests in new technology, smaller competitors may feel pressure.","zh":"如果有線電視巨企投資新科技，較小競爭者可能感到壓力。"},{"en":"The phrase describes size and influence in the cable business.","zh":"這個短語描述有線電視業中的規模和影響力。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":3},{"front":"welcome something","meaning":"迎接；歡迎","examples":[{"en":"John Malone welcomed the idea of a 500-channel universe.","zh":"John Malone 歡迎五百頻道世界這個想法。"},{"en":"To welcome something means to accept it positively or show support for it.","zh":"welcome something 指正面接受某事或表示支持它。"},{"en":"Parents may welcome a new school bus service because it saves travel time.","zh":"家長可能歡迎新的校巴服務，因為它節省交通時間。"},{"en":"If customers welcome a new app, the company may invest more in it.","zh":"如果顧客歡迎新應用程式，公司可能投放更多資源。"},{"en":"The phrase shows approval, not just greeting a person.","zh":"這個短語表示認可，而不只是迎接某人。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":3},{"front":"the 500-channel universe","meaning":"五百頻道的世界","examples":[{"en":"The 500-channel universe was expected to give viewers far more choice.","zh":"五百頻道的世界預期會給觀眾多很多選擇。"},{"en":"The 500-channel universe means a television world with hundreds of available channels.","zh":"the 500-channel universe 指有數百個可用頻道的電視世界。"},{"en":"For a family, a 500-channel universe sounds attractive because everyone can find something to watch.","zh":"對家庭而言，五百頻道的世界聽起來吸引，因為每個人都能找到想看的內容。"},{"en":"If viewers enter a 500-channel universe, traditional broadcasters may lose control over attention.","zh":"如果觀眾進入五百頻道的世界，傳統廣播公司可能失去對注意力的控制。"},{"en":"The phrase represents massive media choice.","zh":"這個短語代表大量媒體選擇。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":4},{"front":"be about to","meaning":"即將","examples":[{"en":"Digital television was about to deliver many services to people’s homes.","zh":"數碼電視即將把許多服務送到人們家中。"},{"en":"Be about to means be going to happen very soon.","zh":"be about to 指某事很快就會發生。"},{"en":"The train is about to leave, so passengers should board immediately.","zh":"火車即將開出，所以乘客應立即上車。"},{"en":"If a company is about to launch a product, staff prepare advertising and customer support.","zh":"如果公司即將推出產品，員工會準備廣告和客戶支援。"},{"en":"The phrase shows that something is near in time.","zh":"這個短語顯示某事在時間上很接近。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":4},{"front":"deliver something to","meaning":"把……送到","examples":[{"en":"Digital television was expected to deliver entertainment to people’s living rooms.","zh":"人們預期數碼電視會把娛樂內容送到人們的客廳。"},{"en":"To deliver something to someone means to bring or send it to them.","zh":"deliver something to 某人，指把某物帶給或發送給他們。"},{"en":"A supermarket can deliver groceries to a family’s home after an online order.","zh":"超級市場可以在網上訂單後把雜貨送到家庭家中。"},{"en":"If a platform delivers lessons to students’ phones, learning becomes more flexible.","zh":"如果平台把課堂送到學生手機上，學習就變得更靈活。"},{"en":"The phrase shows movement from provider to user.","zh":"這個短語顯示由提供者到使用者的移動。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":4},{"front":"everything except pizzas","meaning":"幾乎一切；除了薄餅之外的一切","examples":[{"en":"Digital television seemed ready to deliver everything except pizzas.","zh":"數碼電視似乎準備好送來除了薄餅之外的一切。"},{"en":"Everything except pizzas is a humorous way to say almost every service or product imaginable.","zh":"everything except pizzas 是幽默說法，指幾乎所有可想像的服務或產品。"},{"en":"A shopping app may seem to offer everything except pizzas if it has clothes, books, tools, and medicine.","zh":"如果購物應用程式有衣服、書本、工具和藥物，它可能看似提供除了薄餅之外的一切。"},{"en":"If a technology promises everything except pizzas, people may expect too much from it.","zh":"如果一項科技承諾幾乎一切，人們可能對它期望過高。"},{"en":"The phrase exaggerates to show a very wide range of services.","zh":"這個短語用誇張方式顯示服務範圍非常廣。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":4},{"front":"living rooms","meaning":"客廳","examples":[{"en":"Digital television promised to bring new services into people’s living rooms.","zh":"數碼電視承諾把新服務帶入人們的客廳。"},{"en":"Living rooms are the main rooms in homes where families relax, talk, and watch television.","zh":"living rooms 是家中主要房間，家人在那裏放鬆、聊天和看電視。"},{"en":"Many families watch films together in their living rooms on weekends.","zh":"許多家庭週末在客廳一起看電影。"},{"en":"If entertainment reaches living rooms directly, people may go out to cinemas less often.","zh":"如果娛樂內容直接到達客廳，人們可能較少去戲院。"},{"en":"The phrase represents ordinary home life and home-based viewing.","zh":"這個短語代表普通家庭生活和家中觀看。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":4},{"front":"try out the technology","meaning":"試用該科技","examples":[{"en":"Entertainment companies tried out the technology.","zh":"娛樂公司試用了該科技。"},{"en":"To try out the technology means to test it to see whether it works well.","zh":"try out the technology 指測試科技是否運作良好。"},{"en":"A school may try out the technology in one class before using it everywhere.","zh":"學校可能先在一班試用該科技，才全面使用。"},{"en":"If a company tries out new technology and customers dislike it, the launch may be delayed.","zh":"如果公司試用新科技而顧客不喜歡，推出時間可能延遲。"},{"en":"The phrase describes practical testing before wider use.","zh":"這個短語描述廣泛使用前的實際測試。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":4},{"front":"work fine","meaning":"運作良好","examples":[{"en":"The technology worked fine, but it was too expensive for consumers.","zh":"該科技運作良好，但對消費者來說太昂貴。"},{"en":"Work fine means function properly without major technical problems.","zh":"work fine 指正常運作，沒有重大技術問題。"},{"en":"The printer works fine now that the paper jam has been removed.","zh":"紙張卡住的問題解決後，打印機現在運作良好。"},{"en":"If a product works fine but costs too much, customers may still refuse to buy it.","zh":"如果產品運作良好但成本太高，顧客仍可能拒絕購買。"},{"en":"The phrase separates technical success from practical success.","zh":"這個短語把技術成功與實際成功分開。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":4},{"front":"at a price that","meaning":"以……的價格","examples":[{"en":"The technology did not work at a price that people were prepared to pay.","zh":"該科技未能以人們願意支付的價格運作。"},{"en":"At a price that means at a cost level which produces a particular reaction or result.","zh":"at a price that 指以某個會產生特定反應或結果的成本水平。"},{"en":"A café must sell lunch at a price that students can afford.","zh":"咖啡店必須以學生負擔得起的價格售賣午餐。"},{"en":"If a service is offered at a price that feels unfair, customers may leave.","zh":"如果服務以令人覺得不公平的價格提供，顧客可能離開。"},{"en":"The phrase links cost with willingness or possibility.","zh":"這個短語把成本與意願或可能性連繫起來。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":4},{"front":"be prepared to pay","meaning":"願意支付","examples":[{"en":"Consumers were not prepared to pay the high price.","zh":"消費者不願意支付高昂價格。"},{"en":"To be prepared to pay means to be willing to spend a certain amount of money.","zh":"be prepared to pay 指願意花費某個金額。"},{"en":"Parents may be prepared to pay more for a safe school bus service.","zh":"家長可能願意為安全校巴服務支付更多。"},{"en":"If customers are not prepared to pay, even good technology may fail commercially.","zh":"如果顧客不願意支付，即使好科技也可能商業失敗。"},{"en":"The phrase focuses on willingness, not ability only.","zh":"這個短語重點在意願，而不只是能力。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":4},{"front":"eventually arrive","meaning":"最終出現","examples":[{"en":"The 500 channels eventually arrived through the Internet and the PC.","zh":"五百個頻道最終透過互聯網和個人電腦出現。"},{"en":"To eventually arrive means to appear or happen after a delay or long process.","zh":"eventually arrive 指在延遲或漫長過程後出現或發生。"},{"en":"The new textbooks eventually arrived two weeks after school started.","zh":"新課本在開學兩星期後終於到達。"},{"en":"If a promised service eventually arrives through a different route, the original plan has changed.","zh":"如果承諾的服務最終透過不同途徑出現，原本計劃就已改變。"},{"en":"The phrase suggests that something comes later than expected.","zh":"這個短語暗示某事比預期更遲到來。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":4},{"front":"via the Internet","meaning":"透過互聯網","examples":[{"en":"The channels arrived via the Internet rather than through television.","zh":"這些頻道透過互聯網而不是透過電視出現。"},{"en":"Via the Internet means through online networks or web-based systems.","zh":"via the Internet 指透過網上網絡或網頁系統。"},{"en":"Students can submit homework via the Internet instead of handing in paper copies.","zh":"學生可以透過互聯網提交功課，而不是交紙本。"},{"en":"If entertainment is delivered via the Internet, users can access it from many devices.","zh":"如果娛樂內容透過互聯網發放，用戶就可以從多種裝置存取。"},{"en":"The phrase describes the route or channel of delivery.","zh":"這個短語描述發放的途徑或渠道。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":5},{"front":"the PC","meaning":"個人電腦","examples":[{"en":"The digital revolution reached consumers through the PC.","zh":"數碼革命透過個人電腦到達消費者。"},{"en":"The PC means the personal computer used by individuals at home, school, or work.","zh":"the PC 指個人在家、學校或工作中使用的個人電腦。"},{"en":"Before smartphones became common, many people used the PC to check email and watch videos.","zh":"在智能手機普及前，許多人用個人電腦查電郵和看影片。"},{"en":"If services reach users through the PC, computer ownership becomes important.","zh":"如果服務透過個人電腦到達用戶，電腦擁有率就變得重要。"},{"en":"The phrase refers to a personal computer, not a television set.","zh":"這個短語指個人電腦，而不是電視機。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":5},{"front":"rather than through","meaning":"而不是透過","examples":[{"en":"The change came via the Internet rather than through television.","zh":"這種轉變透過互聯網出現，而不是透過電視。"},{"en":"Rather than through means by one route or method instead of another.","zh":"rather than through 指透過一種途徑或方法，而不是另一種。"},{"en":"Many students now ask questions through messaging apps rather than through formal emails.","zh":"許多學生現在透過訊息應用程式提問，而不是透過正式電郵。"},{"en":"If customers buy tickets through an app rather than through a counter, staffing needs may change.","zh":"如果顧客透過應用程式而不是櫃位買票，人手需求可能改變。"},{"en":"The phrase clearly contrasts two possible channels.","zh":"這個短語清楚對比兩種可能渠道。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":5},{"front":"start to affect","meaning":"開始影響","examples":[{"en":"The digital revolution started to affect the entertainment business.","zh":"數碼革命開始影響娛樂業。"},{"en":"To start to affect something means to begin changing or influencing it.","zh":"start to affect 某事，意思是開始改變或影響它。"},{"en":"A lack of sleep can start to affect a student’s memory after several nights.","zh":"連續幾晚睡眠不足後，可能開始影響學生記憶。"},{"en":"If higher rent starts to affect small shops, some may close or raise prices.","zh":"如果租金上升開始影響小店，一些可能結業或加價。"},{"en":"The phrase marks the beginning of an influence.","zh":"這個短語標示影響的開始。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":5},{"front":"in unexpected ways","meaning":"以意想不到的方式","examples":[{"en":"Digital technology affected entertainment in unexpected ways.","zh":"數碼科技以意想不到的方式影響娛樂業。"},{"en":"In unexpected ways means in ways that people did not predict or plan for.","zh":"in unexpected ways 指以人們沒有預測或計劃到的方式。"},{"en":"A new bus route may help small shops in unexpected ways by bringing more foot traffic.","zh":"新巴士路線可能以意想不到的方式幫助小店，因為它帶來更多人流。"},{"en":"If a policy changes behaviour in unexpected ways, leaders may need to adjust it.","zh":"如果政策以意想不到的方式改變行為，領導者可能需要調整它。"},{"en":"The phrase highlights surprising results.","zh":"這個短語突出令人意外的結果。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":5},{"front":"every aspect of","meaning":"……的每一方面","examples":[{"en":"The digital revolution will change every aspect of the entertainment business.","zh":"數碼革命將改變娛樂業的每一方面。"},{"en":"Every aspect of something means all parts of it, from small details to major systems.","zh":"every aspect of 某事，指它的所有部分，從細節到主要系統。"},{"en":"Moving house affects every aspect of family life, from transport to school routines.","zh":"搬屋會影響家庭生活的每一方面，從交通到上學日程。"},{"en":"If technology changes every aspect of a business, workers need new skills at many levels.","zh":"如果科技改變一個企業的每一方面，員工在多個層面都需要新技能。"},{"en":"The phrase stresses complete and wide-ranging influence.","zh":"這個短語強調全面而廣泛的影響。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":5},{"front":"from the way…to the way…","meaning":"從……的方式到……的方式","examples":[{"en":"The revolution will change everything from the way cartoons are made to the way people buy music.","zh":"這場革命將改變一切，從卡通製作方式到人們購買音樂的方式。"},{"en":"From the way…to the way… means across a whole range of methods or activities.","zh":"from the way…to the way… 指橫跨一整個方法或活動範圍。"},{"en":"A new school policy can affect everything from the way teachers mark homework to the way students revise.","zh":"新校政可以影響一切，從老師批改功課的方式到學生溫習的方式。"},{"en":"If a platform changes everything from production to sales, the whole industry must respond.","zh":"如果平台從製作到銷售都改變，整個行業就必須回應。"},{"en":"The phrase shows a wide span between two examples.","zh":"這個短語透過兩個例子顯示廣闊範圍。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":5},{"front":"cartoons are made","meaning":"卡通製作方式","examples":[{"en":"Digital technology may change the way cartoons are made.","zh":"數碼科技可能改變卡通製作方式。"},{"en":"Cartoons are made through drawing, animation, voice recording, editing, and visual design.","zh":"cartoons are made 涉及繪畫、動畫、配音、剪接和視覺設計。"},{"en":"A small studio can now make cartoons with computer software instead of hand-drawing every frame.","zh":"小型工作室現在可以用電腦軟件製作卡通，而不是手繪每一格。"},{"en":"If cartoons are made digitally, production may become faster and easier to revise.","zh":"如果卡通以數碼方式製作，製作可能更快，也更容易修改。"},{"en":"The phrase refers to the production process behind animated films or shows.","zh":"這個短語指動畫電影或節目背後的製作過程。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":5},{"front":"films are screened","meaning":"電影放映方式","examples":[{"en":"Digital technology may change the way films are screened.","zh":"數碼科技可能改變電影放映方式。"},{"en":"Films are screened when they are shown to an audience in a cinema, hall, or other viewing place.","zh":"films are screened 指電影在戲院、禮堂或其他觀看地點向觀眾播放。"},{"en":"Schools sometimes screen films in the hall for history or language lessons.","zh":"學校有時在禮堂放映電影，用於歷史或語言課。"},{"en":"If films are screened digitally, cinemas may no longer need heavy physical film reels.","zh":"如果電影以數碼方式放映，戲院可能不再需要沉重實體菲林卷。"},{"en":"The phrase focuses on showing films, not making them.","zh":"這個短語重點在播放電影，而不是製作電影。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":5},{"front":"buy music","meaning":"購買音樂","examples":[{"en":"The Internet has changed the way people buy music.","zh":"互聯網改變了人們購買音樂的方式。"},{"en":"To buy music means to pay for songs, albums, downloads, or access to music services.","zh":"buy music 指為歌曲、專輯、下載或音樂服務付費。"},{"en":"Many people now buy music through apps instead of visiting record shops.","zh":"許多人現在透過應用程式購買音樂，而不是到唱片店。"},{"en":"If people stop buying music physically, record stores may lose income.","zh":"如果人們停止購買實體音樂，唱片店可能失去收入。"},{"en":"The phrase describes consumer behaviour in the music market.","zh":"這個短語描述音樂市場中的消費者行為。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":5},{"front":"that much is clear","meaning":"這一點很清楚","examples":[{"en":"That much is clear, but the financial effects remain uncertain.","zh":"這一點很清楚，但財務影響仍不確定。"},{"en":"That much is clear means that one point is obvious, even if other details are not.","zh":"that much is clear 指某一點很明顯，即使其他細節仍未知。"},{"en":"The exam will be difficult; that much is clear, although the exact questions are unknown.","zh":"考試會很難；這一點很清楚，雖然確實題目仍未知。"},{"en":"If sales are falling, that much is clear, but the reason may still need investigation.","zh":"如果銷售正在下降，這一點很清楚，但原因仍可能需要調查。"},{"en":"The phrase separates a known fact from uncertain issues.","zh":"這個短語把已知事實與不確定問題分開。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":6},{"front":"what nobody is sure of is","meaning":"沒有人確定的是","examples":[{"en":"What nobody is sure of is how the change will affect business economics.","zh":"沒有人確定的是，這種轉變將如何影響商業經濟運作。"},{"en":"What nobody is sure of is introduces the main point that remains uncertain.","zh":"what nobody is sure of is 用來引出仍然不確定的重點。"},{"en":"What nobody is sure of is whether the new timetable will reduce student stress.","zh":"沒有人確定的是，新時間表是否會減少學生壓力。"},{"en":"If a plan is new, what nobody is sure of is how people will actually use it.","zh":"如果計劃是新的，沒有人確定的是人們實際會如何使用它。"},{"en":"The phrase highlights a major unanswered question.","zh":"這個短語突出一個重大未解問題。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":6},{"front":"the economics of the business","meaning":"該行業的經濟運作","examples":[{"en":"Digital technology may change the economics of the business.","zh":"數碼科技可能改變該行業的經濟運作。"},{"en":"The economics of the business means how money is made, spent, saved, and distributed in that industry.","zh":"the economics of the business 指該行業如何賺錢、花錢、節省成本和分配收入。"},{"en":"Free delivery changed the economics of the restaurant business by increasing packaging and courier costs.","zh":"免費送餐改變餐飲業的經濟運作，因為包裝和外賣員成本增加。"},{"en":"If production costs fall, the economics of the business may become more favourable.","zh":"如果製作成本下降，該行業的經濟運作可能變得更有利。"},{"en":"The phrase focuses on financial structure, not general economic theory only.","zh":"這個短語重點在財務結構，而不只是一般經濟理論。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":6},{"front":"contain within them","meaning":"內含；本身包含","examples":[{"en":"New technologies contain within them both threats and opportunities.","zh":"新科技本身同時包含威脅與機遇。"},{"en":"To contain within them means to have something inside as part of their nature or possible effect.","zh":"contain within them 指本身內含某些特質或可能影響。"},{"en":"A new exam system may contain within it both fairer assessment and extra pressure.","zh":"新考試制度本身可能同時包含更公平評核和額外壓力。"},{"en":"If a change contains within it risk and benefit, leaders must manage both carefully.","zh":"如果一項轉變本身包含風險和好處，領導者就必須小心管理兩者。"},{"en":"The phrase suggests hidden possibilities inside something.","zh":"這個短語暗示某物內部有隱藏可能性。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":6},{"front":"threats and opportunities","meaning":"威脅與機遇","examples":[{"en":"New technologies bring both threats and opportunities.","zh":"新科技帶來威脅與機遇。"},{"en":"Threats and opportunities are possible dangers and possible advantages in a situation.","zh":"threats and opportunities 是一個情況中的可能危險和可能好處。"},{"en":"A new shopping mall brings threats and opportunities for small shops nearby.","zh":"新商場為附近小店帶來威脅與機遇。"},{"en":"If a school introduces AI tools, the threats and opportunities must both be discussed.","zh":"如果學校引入 AI 工具，就必須同時討論威脅與機遇。"},{"en":"The phrase reminds people to consider both negative and positive outcomes.","zh":"這個短語提醒人們同時考慮負面和正面結果。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":6},{"front":"have the potential to","meaning":"有潛力去","examples":[{"en":"New technologies have the potential to make companies richer or destroy them.","zh":"新科技有潛力令公司更富有，也有潛力摧毀它們。"},{"en":"To have the potential to do something means to be capable of doing it in the future.","zh":"have the potential to do something 指將來有能力做到某事。"},{"en":"A quiet student may have the potential to become a strong speaker with practice.","zh":"安靜的學生經過練習，可能有潛力成為出色演講者。"},{"en":"If a new app has the potential to save time, companies may test it quickly.","zh":"如果新應用程式有潛力節省時間，公司可能很快測試它。"},{"en":"The phrase describes possibility, not certainty.","zh":"這個短語描述可能性，而不是確定性。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":6},{"front":"a great deal richer","meaning":"富裕得多","examples":[{"en":"Technology could make entertainment companies a great deal richer.","zh":"科技可能令娛樂公司富裕得多。"},{"en":"A great deal richer means much richer, not just slightly better off.","zh":"a great deal richer 指富有很多，而不只是稍微好一點。"},{"en":"A successful online shop can make a small business a great deal richer within a few years.","zh":"成功的網店可以在幾年內令小企業富裕得多。"},{"en":"If a company owns both content and distribution, it may become a great deal richer.","zh":"如果公司同時擁有內容和發放渠道，它可能變得富裕得多。"},{"en":"The phrase emphasises a large increase in wealth.","zh":"這個短語強調財富大幅增加。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":6},{"front":"sweep them away","meaning":"把它們淘汰；把它們一掃而空","examples":[{"en":"New technology can sweep old companies away.","zh":"新科技可以把舊公司淘汰。"},{"en":"To sweep them away means to remove or destroy them quickly and powerfully.","zh":"sweep them away 指快速而有力地移除或摧毀它們。"},{"en":"Online news swept away many small print newspapers that could not adapt.","zh":"網上新聞淘汰了許多無法適應的小型紙本報章。"},{"en":"If cheaper services appear suddenly, they may sweep weaker businesses away.","zh":"如果較便宜服務突然出現，它們可能把較弱企業淘汰。"},{"en":"The phrase suggests being pushed out by a strong force of change.","zh":"這個短語暗示被強大的轉變力量推出市場。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":6},{"front":"be hostile to","meaning":"對……抱敵意","examples":[{"en":"Hollywood was hostile to television at first.","zh":"荷里活最初對電視抱敵意。"},{"en":"To be hostile to something means to strongly oppose it or feel unfriendly toward it.","zh":"be hostile to 某事，指強烈反對它或對它不友善。"},{"en":"Some teachers were hostile to online learning before they saw its benefits.","zh":"一些老師在看見網上學習的好處前，曾對它抱敵意。"},{"en":"If workers are hostile to a new system, training may be needed before it can succeed.","zh":"如果員工對新系統抱敵意，在它成功前可能需要培訓。"},{"en":"The phrase describes active dislike or resistance.","zh":"這個短語描述主動厭惡或抗拒。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":6},{"front":"be terrified by","meaning":"對……感到恐懼","examples":[{"en":"Television companies were terrified by the VCR.","zh":"電視公司曾對錄影機感到恐懼。"},{"en":"To be terrified by something means to be extremely frightened of it.","zh":"be terrified by 某事，指對它極度害怕。"},{"en":"A small shop may be terrified by a huge chain opening next door.","zh":"小店可能對隔壁開大型連鎖店感到恐懼。"},{"en":"If companies are terrified by new technology, they may try to block it instead of learning from it.","zh":"如果公司對新科技感到恐懼，它們可能嘗試阻止它，而不是向它學習。"},{"en":"The phrase describes intense fear, not mild concern.","zh":"這個短語描述強烈恐懼，而不是輕微擔心。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":6},{"front":"the VCR","meaning":"錄影機","examples":[{"en":"Television companies once feared the VCR.","zh":"電視公司曾經害怕錄影機。"},{"en":"The VCR was a machine that recorded and played video tapes.","zh":"the VCR 是用來錄製和播放錄影帶的機器。"},{"en":"Families used the VCR to record television programmes before digital recorders became common.","zh":"在數碼錄影機普及前，家庭用錄影機錄下電視節目。"},{"en":"If viewers used the VCR to watch shows later, broadcasters lost some control over schedules.","zh":"如果觀眾用錄影機稍後觀看節目，廣播公司就失去部分時間表控制。"},{"en":"The phrase refers to an older home video technology.","zh":"這個短語指一種較舊的家庭錄影科技。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":7},{"front":"go back far enough","meaning":"追溯得夠遠的話","examples":[{"en":"If we go back far enough, similar fears can be found in publishing.","zh":"如果我們追溯得夠遠，在出版業也可找到相似恐懼。"},{"en":"To go back far enough means to look far enough into the past.","zh":"go back far enough 指回看過去到足夠久遠的時期。"},{"en":"If we go back far enough, we can find old debates about almost every new invention.","zh":"如果我們追溯得夠遠，幾乎每項新發明都有舊爭論。"},{"en":"Going back far enough helps people see that today’s fears may not be completely new.","zh":"追溯得夠遠有助人們看見今天的恐懼未必完全新鮮。"},{"en":"The phrase invites a historical comparison.","zh":"這個短語邀請作歷史比較。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":7},{"front":"point out","meaning":"指出","examples":[{"en":"Hal Varian points out that publishers once feared circulating libraries.","zh":"Hal Varian 指出出版商曾害怕租借圖書館。"},{"en":"To point out means to mention or explain something important.","zh":"point out 指提及或解釋重要事情。"},{"en":"A teacher may point out that a wrong answer fails because of grammar, not vocabulary.","zh":"老師可能指出錯誤答案失分是因為文法，而不是詞彙。"},{"en":"If someone points out a hidden risk, the team can prepare earlier.","zh":"如果有人指出隱藏風險，團隊就能更早準備。"},{"en":"The phrase often introduces an observation or correction.","zh":"這個短語常引出觀察或糾正。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":7},{"front":"circulating libraries","meaning":"流動圖書館；租借圖書館","examples":[{"en":"Publishers once worried that circulating libraries would reduce book sales.","zh":"出版商曾擔心租借圖書館會減少書本銷售。"},{"en":"Circulating libraries were libraries that lent books to readers, often for a fee or membership.","zh":"circulating libraries 是把書借給讀者的圖書館，通常收費或採用會員制度。"},{"en":"A circulating library allowed one book to be read by many people.","zh":"租借圖書館讓一本書可被許多人閱讀。"},{"en":"If readers borrowed books instead of buying them, publishers feared lower sales.","zh":"如果讀者借書而不是買書，出版商就擔心銷售下降。"},{"en":"The phrase describes an older book-lending system.","zh":"這個短語描述一種較舊的借書系統。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":7},{"front":"cannibalise sales","meaning":"蠶食銷售額","examples":[{"en":"Publishers feared that circulating libraries would cannibalise their sales.","zh":"出版商擔心租借圖書館會蠶食他們的銷售額。"},{"en":"To cannibalise sales means to reduce sales of one product by offering another similar option.","zh":"cannibalise sales 指透過提供另一個相似選項而減少某產品銷售。"},{"en":"A cheap online course may cannibalise sales of a school’s more expensive classroom course.","zh":"便宜網上課程可能蠶食學校較昂貴面授課程的銷售額。"},{"en":"If a company launches a low-price product, it may cannibalise sales of its premium product.","zh":"如果公司推出低價產品，它可能蠶食高級產品的銷售額。"},{"en":"The phrase describes one offer eating into another offer’s revenue.","zh":"這個短語描述一項產品或服務侵蝕另一項的收入。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":7},{"front":"new technology has come in","meaning":"新科技出現","examples":[{"en":"Whenever new technology has come in, existing companies have often made more money.","zh":"每當新科技出現，現有公司往往賺到更多錢。"},{"en":"New technology has come in means a new tool or system has entered use.","zh":"new technology has come in 指新工具或系統已投入使用。"},{"en":"When mobile payment came in, small shops had to learn a new way to collect money.","zh":"當流動支付出現，小店必須學習新的收款方式。"},{"en":"If new technology comes in smoothly, it can create new customers rather than only destroy old business.","zh":"如果新科技順利出現，它可以創造新顧客，而不只是摧毀舊生意。"},{"en":"The phrase describes the arrival of technology into everyday or business life.","zh":"這個短語描述科技進入日常或商業生活。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":7},{"front":"existing entertainment companies","meaning":"現有娛樂公司","examples":[{"en":"New technology has often benefited existing entertainment companies.","zh":"新科技往往令現有娛樂公司受益。"},{"en":"Existing entertainment companies are entertainment businesses already operating before a new change arrives.","zh":"existing entertainment companies 是新轉變出現前已在營運的娛樂企業。"},{"en":"A long-established studio is one of the existing entertainment companies in the market.","zh":"老牌片廠是市場中的現有娛樂公司之一。"},{"en":"If existing entertainment companies adapt quickly, new technology may increase their profits.","zh":"如果現有娛樂公司迅速適應，新科技可能增加它們的利潤。"},{"en":"The phrase contrasts old players with new entrants.","zh":"這個短語把舊有參與者與新進入者作對比。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":7},{"front":"the proliferation of","meaning":"……的激增","examples":[{"en":"The proliferation of distribution methods can increase profits.","zh":"發放方式的激增可以增加利潤。"},{"en":"The proliferation of something means a rapid increase in the number or variety of it.","zh":"the proliferation of 某物，指其數量或種類快速增加。"},{"en":"The proliferation of delivery apps has changed how families order dinner.","zh":"外賣應用程式的激增改變了家庭訂晚餐的方式。"},{"en":"If there is a proliferation of channels, audiences can be reached in more ways.","zh":"如果渠道激增，觀眾就可以透過更多方式被接觸到。"},{"en":"The phrase suggests fast growth, often with many new options.","zh":"這個短語暗示快速增長，通常帶來許多新選項。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":7},{"front":"means of distribution","meaning":"發放渠道；分銷方式","examples":[{"en":"The means of distribution have multiplied over time.","zh":"發放渠道隨時間增加。"},{"en":"Means of distribution are the methods or channels used to deliver products or content to users.","zh":"means of distribution 是把產品或內容送到使用者手中的方法或渠道。"},{"en":"Shops, websites, apps, and home delivery are all means of distribution for retailers.","zh":"店舖、網站、應用程式和送貨上門都是零售商的分銷方式。"},{"en":"If means of distribution increase, a company can reach customers who prefer different channels.","zh":"如果發放渠道增加，公司就能接觸偏好不同渠道的顧客。"},{"en":"The phrase focuses on delivery routes, not the product itself.","zh":"這個短語重點在發送路線，而不是產品本身。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":7},{"front":"result in","meaning":"導致","examples":[{"en":"The proliferation of distribution channels results in more revenue.","zh":"發放渠道的激增導致更多收入。"},{"en":"To result in something means to cause it to happen.","zh":"result in 某事，意思是造成某事發生。"},{"en":"Poor sleep can result in weak concentration during lessons.","zh":"睡眠不足可以導致上課時專注力弱。"},{"en":"If better advertising results in more customers, the business may expand.","zh":"如果更好廣告導致更多顧客，企業可能擴張。"},{"en":"The phrase introduces an outcome or consequence.","zh":"這個短語引出結果或後果。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":7},{"front":"gratifyingly","meaning":"令人欣慰的是","examples":[{"en":"Gratifyingly, more distribution channels have often meant more money.","zh":"令人欣慰的是，更多發放渠道往往意味着更多金錢。"},{"en":"Gratifyingly means in a way that is pleasing or satisfying.","zh":"gratifyingly 指以令人高興或滿意的方式。"},{"en":"Gratifyingly, the shy student spoke clearly during the final presentation.","zh":"令人欣慰的是，害羞的學生在最後匯報中說得很清楚。"},{"en":"If a difficult change leads to better results, people may say gratifyingly that the effort was worthwhile.","zh":"如果困難轉變帶來更好結果，人們可能欣慰地說努力是值得的。"},{"en":"The word signals a pleasing outcome.","zh":"這個字表示令人滿意的結果。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":8},{"front":"and the rest","meaning":"等等；其餘同類事物","examples":[{"en":"Dollars, pounds, pesetas and the rest represent the money generated by entertainment.","zh":"美元、英鎊、比塞塔等等代表娛樂業產生的金錢。"},{"en":"And the rest means and other similar things not listed individually.","zh":"and the rest 指其他未逐一列出的相似事物。"},{"en":"The shop sells notebooks, pens, folders and the rest for students.","zh":"這間店售賣筆記本、筆、文件夾等等學生用品。"},{"en":"If a list is long, “and the rest” helps avoid naming every example.","zh":"如果清單很長，and the rest 可以避免列出每個例子。"},{"en":"The phrase is informal and groups together similar items.","zh":"這個短語較口語，把相似項目歸在一起。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":8},{"front":"pay for it","meaning":"為此付費","examples":[{"en":"Consumers eventually pay for the expanded entertainment system.","zh":"消費者最終為擴大的娛樂系統付費。"},{"en":"To pay for it means to provide the money needed for something.","zh":"pay for it 指提供某事所需金錢。"},{"en":"A family may enjoy a new streaming service, but they must pay for it each month.","zh":"家庭可能享受新的串流服務，但他們每月都必須為此付費。"},{"en":"If a service becomes more expensive, customers may question whether they should pay for it.","zh":"如果服務變得更昂貴，顧客可能質疑是否應為此付費。"},{"en":"The phrase can refer to financial cost or, in other contexts, consequences.","zh":"這個短語可以指金錢成本；在其他語境中也可指後果。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":8},{"front":"all the same","meaning":"儘管如此","examples":[{"en":"All the same, there is some truth in the old companies’ fears.","zh":"儘管如此，老牌公司的憂慮也有一定道理。"},{"en":"All the same means despite what has just been said.","zh":"all the same 指儘管剛才所說是那樣。"},{"en":"The new timetable is helpful; all the same, some students still feel tired.","zh":"新時間表有幫助；儘管如此，一些學生仍感到疲倦。"},{"en":"If profits rise, all the same, workers may worry about job security.","zh":"如果利潤上升，儘管如此，員工仍可能擔心工作保障。"},{"en":"The phrase introduces a contrasting point.","zh":"這個短語引出對比觀點。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":8},{"front":"there is something in","meaning":"……是有道理的","examples":[{"en":"There is something in the old companies’ fears.","zh":"老牌公司的憂慮是有一定道理的。"},{"en":"There is something in an idea means it has some truth or value.","zh":"there is something in 某想法，意思是它有一些真實性或價值。"},{"en":"There is something in the student’s complaint if many classmates feel confused too.","zh":"如果許多同學也感到困惑，這名學生的投訴可能有道理。"},{"en":"If customers keep repeating the same criticism, there may be something in it.","zh":"如果顧客不斷重複同一批評，其中可能有些道理。"},{"en":"The phrase gives partial agreement without accepting everything.","zh":"這個短語表示部分同意，而不是完全接受。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":8},{"front":"old companies’ fears","meaning":"老牌公司的憂慮","examples":[{"en":"Old companies’ fears are not completely irrational.","zh":"老牌公司的憂慮並非完全不理性。"},{"en":"Old companies’ fears are worries held by established businesses facing change.","zh":"old companies’ fears 是既有企業面對轉變時持有的憂慮。"},{"en":"A family shop may have old companies’ fears when a large online retailer enters the market.","zh":"當大型網上零售商進入市場，家庭小店可能有老牌公司的憂慮。"},{"en":"If new technology changes customer habits, old companies’ fears may become realistic.","zh":"如果新科技改變顧客習慣，老牌公司的憂慮可能變得現實。"},{"en":"The phrase describes anxiety among established firms.","zh":"這個短語描述既有公司之間的焦慮。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":8},{"front":"threaten their lives","meaning":"威脅其生存","examples":[{"en":"New technologies may not threaten companies’ lives, but they change their roles.","zh":"新科技未必威脅公司的生存，但會改變它們的角色。"},{"en":"To threaten their lives means to put their survival or continued existence at risk.","zh":"threaten their lives 指使其生存或繼續存在面臨風險。"},{"en":"A small business may feel that rising rent threatens its life.","zh":"小企業可能覺得租金上升威脅其生存。"},{"en":"If a company loses all customers, the change may threaten its life.","zh":"如果公司失去所有顧客，這種轉變可能威脅其生存。"},{"en":"The phrase is metaphorical when used for companies.","zh":"這個短語用於公司時是比喻說法。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":8},{"front":"change their role","meaning":"改變其角色","examples":[{"en":"New technology often changes the role of old companies.","zh":"新科技常改變舊公司的角色。"},{"en":"To change their role means to alter what they do or how they fit into an industry.","zh":"change their role 指改變它們做甚麼或如何在行業中定位。"},{"en":"Online booking changed the role of travel agents from ticket sellers to advisers.","zh":"網上預訂把旅行社角色由賣票者改變成顧問。"},{"en":"If schools use more digital tools, teachers’ roles may change from lecturers to guides.","zh":"如果學校使用更多數碼工具，老師角色可能由講授者改變成引導者。"},{"en":"The phrase focuses on function, not existence alone.","zh":"這個短語重點在功能，而不只是存在與否。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":8},{"front":"become widespread","meaning":"變得普及","examples":[{"en":"Once television became widespread, other media lost their central role.","zh":"一旦電視變得普及，其他媒體就失去中心角色。"},{"en":"To become widespread means to be used or found by many people in many places.","zh":"become widespread 指被許多人在許多地方使用或發現。"},{"en":"Mobile payment became widespread when small shops began accepting it.","zh":"當小店開始接受流動支付，它就變得普及。"},{"en":"If a disease becomes widespread, public health measures may be needed.","zh":"如果疾病變得普及，可能需要公共衞生措施。"},{"en":"The phrase describes broad spread or common use.","zh":"這個短語描述廣泛傳播或普遍使用。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":8},{"front":"staple form of entertainment","meaning":"主要娛樂形式","examples":[{"en":"Film and radio stopped being the staple form of entertainment.","zh":"電影和收音機不再是主要娛樂形式。"},{"en":"A staple form of entertainment is the main or regular kind of entertainment people use.","zh":"staple form of entertainment 是人們主要或經常使用的娛樂類型。"},{"en":"Television was once the staple form of entertainment for many families after dinner.","zh":"電視曾經是許多家庭晚飯後的主要娛樂形式。"},{"en":"If streaming becomes the staple form of entertainment, cinemas may face fewer casual visitors.","zh":"如果串流成為主要娛樂形式，戲院可能面對較少隨意入場的觀眾。"},{"en":"The phrase describes the standard everyday choice.","zh":"這個短語描述標準日常選擇。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":8},{"front":"undermine the power of","meaning":"削弱……的權力","examples":[{"en":"Cable television has undermined the power of broadcasters.","zh":"有線電視削弱了廣播機構的權力。"},{"en":"To undermine the power of someone means to weaken their control or influence.","zh":"undermine the power of 某人，指削弱其控制力或影響力。"},{"en":"Online reviews can undermine the power of advertisers by letting customers share honest opinions.","zh":"網上評論讓顧客分享真實意見，可以削弱廣告商的權力。"},{"en":"If workers organise together, they may undermine the power of unfair managers.","zh":"如果工人組織起來，他們可能削弱不公平管理者的權力。"},{"en":"The phrase describes gradual weakening, not always immediate defeat.","zh":"這個短語描述逐漸削弱，不一定是即時擊敗。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":9},{"front":"broadcasters","meaning":"廣播機構；電視廣播公司","examples":[{"en":"Cable television reduced the power of traditional broadcasters.","zh":"有線電視削弱了傳統廣播機構的權力。"},{"en":"Broadcasters are companies or organisations that send television or radio programmes to audiences.","zh":"broadcasters 是向觀眾傳送電視或電台節目的公司或機構。"},{"en":"Public broadcasters may provide news, education, drama, and cultural programmes.","zh":"公共廣播機構可能提供新聞、教育、劇集和文化節目。"},{"en":"If viewers move to online platforms, broadcasters may lose advertising income.","zh":"如果觀眾轉向網上平台，廣播機構可能失去廣告收入。"},{"en":"The word refers to media organisations that transmit content.","zh":"這個字指傳送內容的媒體機構。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":9},{"front":"as power has shifted","meaning":"隨着權力轉移","examples":[{"en":"As power has shifted, many old entertainment companies have been absorbed.","zh":"隨着權力轉移，許多老牌娛樂公司被吸收。"},{"en":"As power has shifted means while control or influence has moved from one group to another.","zh":"as power has shifted 指隨着控制力或影響力從一個群體轉到另一個群體。"},{"en":"As power has shifted to online platforms, small shops have had to learn digital marketing.","zh":"隨着權力轉移到網上平台，小店必須學習數碼營銷。"},{"en":"If power shifts from teachers to students in class discussions, lessons may become more interactive.","zh":"如果課堂討論中的權力從老師轉向學生，課堂可能變得更互動。"},{"en":"The phrase links changing authority with changing outcomes.","zh":"這個短語把權威變化與結果變化連繫起來。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":9},{"front":"movie studios","meaning":"電影製片廠","examples":[{"en":"Movie studios became part of larger entertainment businesses.","zh":"電影製片廠成為較大娛樂企業的一部分。"},{"en":"Movie studios are companies or facilities that produce films.","zh":"movie studios 是製作電影的公司或設施。"},{"en":"A movie studio may employ directors, actors, editors, designers, and technicians.","zh":"電影製片廠可能聘用導演、演員、剪接師、設計師和技術員。"},{"en":"If movie studios join larger groups, they may gain money but lose independence.","zh":"如果電影製片廠加入大型集團，它們可能得到資金但失去獨立性。"},{"en":"The phrase refers to film-production organisations.","zh":"這個短語指電影製作機構。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":9},{"front":"be swallowed up","meaning":"被吞併","examples":[{"en":"Many old entertainment companies have been swallowed up by larger groups.","zh":"許多老牌娛樂公司已被大型集團吞併。"},{"en":"To be swallowed up means to be absorbed, taken over, or made part of something larger.","zh":"be swallowed up 指被吸收、收購或成為更大事物的一部分。"},{"en":"A small local shop may be swallowed up by a national chain.","zh":"本地小店可能被全國連鎖店吞併。"},{"en":"If a company is swallowed up, its old name may remain but its control changes.","zh":"如果公司被吞併，其舊名稱可能保留，但控制權會改變。"},{"en":"The phrase suggests losing independence inside a bigger organisation.","zh":"這個短語暗示在大型組織內失去獨立性。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":9},{"front":"grand old names","meaning":"老牌著名名稱","examples":[{"en":"The grand old names of entertainment now have more fame than power.","zh":"娛樂業的老牌著名名稱現在名氣大於權力。"},{"en":"Grand old names are famous traditional names with long histories and public recognition.","zh":"grand old names 是有悠久歷史和公眾認知的著名傳統名稱。"},{"en":"A grand old name in education may still attract parents because of its reputation.","zh":"教育界的老牌名校可能仍因名聲而吸引家長。"},{"en":"If a grand old name loses control, it may survive as a brand rather than a powerful company.","zh":"如果老牌著名名稱失去控制權，它可能作為品牌而非強大公司存在。"},{"en":"The phrase suggests prestige from the past.","zh":"這個短語暗示來自過去的聲望。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":9},{"front":"have more resonance than power","meaning":"名氣大於實權","examples":[{"en":"Some old entertainment names have more resonance than power.","zh":"一些老牌娛樂名稱名氣大於實權。"},{"en":"To have more resonance than power means to be better known or emotionally meaningful than actually influential.","zh":"have more resonance than power 指知名度或情感意義高於實際影響力。"},{"en":"An old school name may have more resonance than power if few students study there now.","zh":"如果一間老學校現在學生很少，它的名字可能名氣大於實權。"},{"en":"If a brand has more resonance than power, people remember it but it does not control the market.","zh":"如果品牌名氣大於實權，人們記得它，但它不控制市場。"},{"en":"The phrase contrasts reputation with real authority.","zh":"這個短語把名聲與實際權力作對比。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":9},{"front":"resonance","meaning":"影響力；共鳴；知名度","examples":[{"en":"Old company names still have resonance with the public.","zh":"老公司名稱仍然對公眾有共鳴。"},{"en":"Resonance is emotional meaning, recognition, or lasting influence that a name or idea carries.","zh":"resonance 是一個名稱或想法帶有的情感意義、認知度或持久影響。"},{"en":"A song from childhood may have strong resonance for adults who remember it.","zh":"童年歌曲可能對記得它的成年人有強烈共鳴。"},{"en":"If a brand has resonance, customers may trust it even after ownership changes.","zh":"如果品牌有共鳴，即使擁有權改變，顧客仍可能信任它。"},{"en":"The word describes meaning that continues to echo in people’s minds.","zh":"這個字描述仍在人們心中迴響的意義。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":9},{"front":"be part of","meaning":"是……的一部分","examples":[{"en":"Paramount is part of Viacom.","zh":"Paramount 是 Viacom 的一部分。"},{"en":"To be part of something means to belong to a larger group, system, or organisation.","zh":"be part of 某物，意思是屬於較大的群體、系統或組織。"},{"en":"A small clinic may be part of a larger hospital network.","zh":"小診所可能是大型醫院網絡的一部分。"},{"en":"If a studio is part of a large company, decisions may be made above it.","zh":"如果片廠是大公司的一部分，決策可能由上層作出。"},{"en":"The phrase shows membership or ownership within a bigger whole.","zh":"這個短語顯示在較大整體中的成員身份或擁有關係。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":9},{"front":"a drinks-and-entertainment company","meaning":"飲品及娛樂公司","examples":[{"en":"Universal became part of a drinks-and-entertainment company.","zh":"Universal 成為一間飲品及娛樂公司的一部分。"},{"en":"A drinks-and-entertainment company is a business group involved in both beverages and entertainment.","zh":"a drinks-and-entertainment company 是同時涉足飲品和娛樂的商業集團。"},{"en":"A company that sells soft drinks and owns music labels could be a drinks-and-entertainment company.","zh":"出售汽水並擁有唱片品牌的公司可以是飲品及娛樂公司。"},{"en":"If a film studio joins a drinks-and-entertainment company, its owner may have interests beyond films.","zh":"如果電影製片廠加入飲品及娛樂公司，其擁有者可能有電影以外的利益。"},{"en":"The phrase shows a mixed business structure.","zh":"這個短語顯示混合式商業結構。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":9},{"front":"the roaring lion of Hollywood","meaning":"荷里活昔日雄獅","examples":[{"en":"MGM was once the roaring lion of Hollywood.","zh":"MGM 曾經是荷里活昔日雄獅。"},{"en":"The roaring lion of Hollywood means a powerful, famous film studio strongly associated with Hollywood glory.","zh":"the roaring lion of Hollywood 指一間強大、著名並與荷里活輝煌密切相關的片廠。"},{"en":"A company may be called a roaring lion if it once dominated its market loudly and confidently.","zh":"如果一間公司曾自信而強勢地支配市場，它可能被稱為雄獅。"},{"en":"If the roaring lion loses money and influence, its famous image may hide weakness.","zh":"如果雄獅失去金錢和影響力，其著名形象可能掩蓋弱點。"},{"en":"The phrase uses a vivid image to describe past strength.","zh":"這個短語用鮮明形象描述過去的力量。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":10},{"front":"be reduced to a whisper","meaning":"被削弱至幾乎無聲無息","examples":[{"en":"MGM has been reduced to a whisper because it is not part of a giant group.","zh":"MGM 因不是大型集團的一部分而被削弱至幾乎無聲無息。"},{"en":"To be reduced to a whisper means to become very weak, quiet, or almost unnoticed.","zh":"be reduced to a whisper 指變得非常弱、安靜或幾乎不被注意。"},{"en":"A once-busy market may be reduced to a whisper after shoppers move online.","zh":"當購物者轉到網上，一個曾經繁忙的市場可能被削弱至幾乎無聲無息。"},{"en":"If a famous brand loses money and audience attention, it may be reduced to a whisper.","zh":"如果著名品牌失去金錢和觀眾注意，它可能變得幾乎無聲無息。"},{"en":"The phrase strongly contrasts past power with present weakness.","zh":"這個短語強烈對比過去的權力與現在的弱勢。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":10},{"front":"the giants","meaning":"巨企；大型集團","examples":[{"en":"Companies outside the giants may lose influence.","zh":"巨企以外的公司可能失去影響力。"},{"en":"The giants are the largest and most powerful companies in an industry.","zh":"the giants 是某行業中最大和最有權力的公司。"},{"en":"Small shops often struggle to compete with the giants of online retail.","zh":"小店常難以與網上零售巨企競爭。"},{"en":"If the giants control both content and distribution, smaller firms may find it hard to survive.","zh":"如果巨企同時控制內容和發放渠道，較小公司可能難以生存。"},{"en":"The phrase emphasises size, power, and market dominance.","zh":"這個短語強調規模、權力和市場支配力。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":10},{"front":"a recording label","meaning":"唱片品牌","examples":[{"en":"RCA is now a recording label belonging to Bertelsmann.","zh":"RCA 現在是屬於 Bertelsmann 的唱片品牌。"},{"en":"A recording label is a music company or brand that produces, markets, and distributes recorded music.","zh":"a recording label 是製作、推廣和發行錄製音樂的音樂公司或品牌。"},{"en":"A singer may sign with a recording label to release an album.","zh":"歌手可能與唱片品牌簽約推出專輯。"},{"en":"If a recording label belongs to a larger group, business decisions may depend on that parent company.","zh":"如果唱片品牌屬於大型集團，商業決定可能取決於母公司。"},{"en":"The phrase refers to the business side of music production.","zh":"這個短語指音樂製作的商業層面。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":10},{"front":"belonging to","meaning":"屬於","examples":[{"en":"RCA is a recording label belonging to a German entertainment company.","zh":"RCA 是屬於一間德國娛樂公司的唱片品牌。"},{"en":"Belonging to means owned by, connected with, or part of someone or something.","zh":"belonging to 指由某人或某物擁有、與其相關或是其一部分。"},{"en":"A library card belonging to a student should not be used by another person.","zh":"屬於某學生的圖書證不應由另一人使用。"},{"en":"If a studio belongs to a larger company, it may have less freedom to choose projects.","zh":"如果片廠屬於大型公司，它選擇項目的自由可能較少。"},{"en":"The phrase shows ownership or close connection.","zh":"這個短語顯示擁有關係或密切連繫。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":10},{"front":"incumbents","meaning":"在位者；既有公司","examples":[{"en":"Incumbents were pushed aside when they failed to adapt.","zh":"在位者未能適應時被擠到一旁。"},{"en":"Incumbents are existing holders of power, positions, or market advantages.","zh":"incumbents 是已擁有權力、職位或市場優勢的人或公司。"},{"en":"In business, incumbents may include old companies that already have loyal customers.","zh":"在商業中，既有公司可能包括已擁有忠實顧客的老牌公司。"},{"en":"If incumbents ignore new habits, younger competitors may take their place.","zh":"如果既有公司忽視新習慣，年輕競爭者可能取代它們。"},{"en":"The word contrasts established players with newcomers.","zh":"這個字把既有參與者與新來者作對比。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":10},{"front":"get pushed aside","meaning":"被擠到一旁；被邊緣化","examples":[{"en":"Some established companies got pushed aside by new business models.","zh":"一些老牌公司被新商業模式擠到一旁。"},{"en":"To get pushed aside means to lose importance, attention, or position because others move ahead.","zh":"get pushed aside 指因其他人或事物走在前面而失去重要性、注意或位置。"},{"en":"A quiet student may get pushed aside in a group project if louder classmates dominate.","zh":"在小組項目中，如果較大聲的同學主導，安靜學生可能被邊緣化。"},{"en":"If a company does not adapt, it may get pushed aside by faster competitors.","zh":"如果公司不適應，它可能被較快競爭者擠到一旁。"},{"en":"The phrase describes being marginalised or displaced.","zh":"這個短語描述被邊緣化或被取代。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":10},{"front":"see what was coming","meaning":"預見即將發生的事","examples":[{"en":"Some companies failed because they did not see what was coming.","zh":"一些公司失敗，因為它們沒有預見即將發生的事。"},{"en":"To see what was coming means to recognise or predict a future change or problem.","zh":"see what was coming 指認出或預測未來的轉變或問題。"},{"en":"A shop that saw online shopping coming started selling through a website early.","zh":"預見網上購物即將到來的商店，很早就開始透過網站銷售。"},{"en":"If managers do not see what is coming, they may prepare too late.","zh":"如果管理層看不到即將發生的事，他們可能準備得太遲。"},{"en":"The phrase is about foresight and preparation.","zh":"這個短語關於遠見和準備。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":10},{"front":"face a tighter regulatory environment","meaning":"面對更嚴格的監管環境","examples":[{"en":"Old companies faced a tighter regulatory environment than companies today.","zh":"舊公司比今天的公司面對更嚴格的監管環境。"},{"en":"To face a tighter regulatory environment means to operate under stricter laws and rules.","zh":"face a tighter regulatory environment 指在更嚴格法律和規則下運作。"},{"en":"Banks face a tighter regulatory environment after financial scandals.","zh":"金融醜聞後，銀行面對更嚴格的監管環境。"},{"en":"If companies face tighter rules, they may find it harder to merge or expand.","zh":"如果公司面對更嚴格規則，它們可能更難合併或擴張。"},{"en":"The phrase links business freedom with government control.","zh":"這個短語把商業自由與政府控制連繫起來。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":10},{"front":"regulatory environment","meaning":"監管環境","examples":[{"en":"The regulatory environment affected how entertainment companies could grow.","zh":"監管環境影響娛樂公司如何成長。"},{"en":"The regulatory environment is the system of laws, rules, and official controls around an industry.","zh":"regulatory environment 是圍繞某行業的法律、規則和官方控制系統。"},{"en":"The regulatory environment for schools includes safety rules, exams, and teacher requirements.","zh":"學校的監管環境包括安全規則、考試和教師要求。"},{"en":"If the regulatory environment becomes stricter, companies may need lawyers and compliance teams.","zh":"如果監管環境變得更嚴格，公司可能需要律師和合規團隊。"},{"en":"The phrase describes the rule-setting context in which organisations operate.","zh":"這個短語描述組織運作所處的規則背景。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":10},{"front":"the present one","meaning":"現在的那個","examples":[{"en":"The old regulatory environment was stricter than the present one.","zh":"舊監管環境比現在的那個更嚴格。"},{"en":"The present one means the current example or situation being compared with an earlier one.","zh":"the present one 指當前被拿來與較早情況比較的例子或情況。"},{"en":"The old timetable was harder than the present one because lessons ended later.","zh":"舊時間表比現在的那個更辛苦，因為課堂更晚結束。"},{"en":"If the present one is more flexible, companies can make decisions faster than before.","zh":"如果現在的那個較靈活，公司就能比以前更快作決策。"},{"en":"The phrase avoids repeating the noun already mentioned.","zh":"這個短語避免重複已提及的名詞。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":11},{"front":"laws preventing someone from doing something","meaning":"阻止某人做某事的法律","examples":[{"en":"Some laws prevented broadcasters from owning programme companies.","zh":"一些法律阻止廣播公司擁有節目製作公司。"},{"en":"Laws preventing someone from doing something are rules that legally stop that action.","zh":"laws preventing someone from doing something 是在法律上阻止該行動的規則。"},{"en":"Laws preventing shops from selling alcohol to children protect young people.","zh":"阻止商店向兒童售酒的法律保護年輕人。"},{"en":"If laws prevent companies from merging, they may remain smaller and less powerful.","zh":"如果法律阻止公司合併，它們可能保持較小和較弱。"},{"en":"The phrase explains legal restriction.","zh":"這個短語解釋法律限制。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":11},{"front":"television broadcasters","meaning":"電視廣播公司","examples":[{"en":"Television broadcasters were once restricted by ownership laws.","zh":"電視廣播公司曾受擁有權法律限制。"},{"en":"Television broadcasters are organisations that transmit television programmes to viewers.","zh":"television broadcasters 是向觀眾傳送電視節目的機構。"},{"en":"Television broadcasters may produce news, dramas, sports coverage, and children’s shows.","zh":"電視廣播公司可能製作新聞、劇集、體育報道和兒童節目。"},{"en":"If television broadcasters cannot own production companies, they depend on outside suppliers.","zh":"如果電視廣播公司不能擁有製作公司，它們就依賴外部供應商。"},{"en":"The phrase refers to companies that send TV content to the public.","zh":"這個短語指向公眾傳送電視內容的公司。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":11},{"front":"programme companies","meaning":"節目製作公司","examples":[{"en":"Broadcasters were once prevented from owning programme companies.","zh":"廣播公司曾被阻止擁有節目製作公司。"},{"en":"Programme companies are businesses that make television or radio programmes.","zh":"programme companies 是製作電視或電台節目的企業。"},{"en":"A programme company may produce documentaries, dramas, or quiz shows for broadcasters.","zh":"節目製作公司可能為廣播公司製作紀錄片、劇集或問答節目。"},{"en":"If broadcasters own programme companies, they can control both production and distribution.","zh":"如果廣播公司擁有節目製作公司，它們就能同時控制製作和發放。"},{"en":"The phrase refers to content producers, not the channels themselves.","zh":"這個短語指內容製作者，而不是頻道本身。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":11},{"front":"be repealed","meaning":"被廢除","examples":[{"en":"The laws were repealed earlier in the decade.","zh":"這些法律在本十年較早時候被廢除。"},{"en":"To be repealed means to be officially cancelled or removed as a law.","zh":"be repealed 指法律被正式取消或移除。"},{"en":"An outdated school rule may be repealed if it no longer helps students.","zh":"如果過時校規不再幫助學生，它可能被廢除。"},{"en":"If ownership laws are repealed, companies may gain freedom to merge or expand.","zh":"如果擁有權法律被廢除，公司可能獲得合併或擴張的自由。"},{"en":"The phrase is mainly used for laws and official rules.","zh":"這個短語主要用於法律和官方規則。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":11},{"front":"earlier this decade","meaning":"本十年較早時候","examples":[{"en":"These laws were repealed earlier this decade.","zh":"這些法律在本十年較早時候被廢除。"},{"en":"Earlier this decade means during the earlier years of the current ten-year period being discussed.","zh":"earlier this decade 指在所討論這個十年期的較早年份中。"},{"en":"The school introduced tablets earlier this decade before most classes moved online.","zh":"學校在本十年較早時候引入平板電腦，之後大多數課堂才轉到網上。"},{"en":"If a rule changed earlier this decade, its effects may already be visible now.","zh":"如果規則在本十年較早時候改變，其影響現在可能已經可見。"},{"en":"The phrase gives a recent but not exact time reference.","zh":"這個短語提供近期但不精確的時間參照。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":11},{"front":"allow the creation of","meaning":"允許……的建立","examples":[{"en":"The repeal allowed the creation of vertically integrated businesses.","zh":"法律廢除允許垂直整合企業的建立。"},{"en":"To allow the creation of something means to make it legally or practically possible to form it.","zh":"allow the creation of 某物，指在法律上或實際上使其形成成為可能。"},{"en":"New zoning rules may allow the creation of more homes near train stations.","zh":"新分區規則可能允許火車站附近建立更多住宅。"},{"en":"If a law allows the creation of larger companies, competition may change.","zh":"如果法律允許更大型公司的建立，競爭可能改變。"},{"en":"The phrase links permission with the formation of something new.","zh":"這個短語把許可與新事物形成連繫起來。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":11},{"front":"vertically integrated businesses","meaning":"垂直整合企業","examples":[{"en":"Vertically integrated businesses can both create and distribute content.","zh":"垂直整合企業可以同時創作和發放內容。"},{"en":"Vertically integrated businesses control several stages of production and delivery in the same industry.","zh":"vertically integrated businesses 控制同一行業中生產和交付的多個階段。"},{"en":"A bakery that grows wheat, bakes bread, and sells it in its own shops is vertically integrated.","zh":"如果麵包店種小麥、烘焙麵包並在自家店舖出售，就是垂直整合。"},{"en":"If an entertainment company creates films and owns distribution channels, it becomes more vertically integrated.","zh":"如果娛樂公司製作電影並擁有發放渠道，它就變得更加垂直整合。"},{"en":"The phrase describes control from production to delivery.","zh":"這個短語描述由生產到交付的控制。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":11},{"front":"greater freedom","meaning":"更大自由","examples":[{"en":"Greater freedom allowed smarter companies to reinvent themselves.","zh":"更大自由讓較精明的公司重塑自身。"},{"en":"Greater freedom means having more ability to choose actions without restrictions.","zh":"greater freedom 指有更多不受限制地選擇行動的能力。"},{"en":"Students have greater freedom when they can choose topics for their projects.","zh":"當學生可以選擇專題題目，他們就有更大自由。"},{"en":"If companies gain greater freedom, they may enter new markets or combine services.","zh":"如果公司獲得更大自由，它們可能進入新市場或結合服務。"},{"en":"The phrase often follows the removal of rules or limits.","zh":"這個短語常跟隨規則或限制被移除而出現。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":11},{"front":"combined with","meaning":"加上；結合","examples":[{"en":"Greater freedom, combined with a sense of history, changed company strategy.","zh":"更大自由加上歷史意識，改變了公司策略。"},{"en":"Combined with means joined together with another factor to produce an effect.","zh":"combined with 指與另一因素結合並產生影響。"},{"en":"Good teaching, combined with regular practice, can improve exam results.","zh":"良好教學加上定期練習，可以改善考試成績。"},{"en":"If low prices are combined with good service, customers are more likely to return.","zh":"如果低價格結合良好服務，顧客更可能回來。"},{"en":"The phrase shows two factors working together.","zh":"這個短語顯示兩個因素共同作用。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":11},{"front":"a sense of history","meaning":"歷史感；歷史意識","examples":[{"en":"A sense of history helped companies learn from past mistakes.","zh":"歷史意識幫助公司從過去錯誤中學習。"},{"en":"A sense of history means awareness of what happened before and why it matters now.","zh":"a sense of history 指意識到以前發生過甚麼，以及它為何對現在重要。"},{"en":"A teacher with a sense of history can explain how old conflicts shape today’s society.","zh":"有歷史感的老師可以解釋舊衝突如何塑造今天社會。"},{"en":"If managers have a sense of history, they may avoid repeating earlier business failures.","zh":"如果管理層有歷史意識，他們可能避免重複早前商業失敗。"},{"en":"The phrase links memory of the past with wiser decisions.","zh":"這個短語把對過去的記憶與更明智決策連繫起來。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":12},{"front":"prompt someone to","meaning":"促使某人去","examples":[{"en":"New freedom prompted companies to reinvent themselves.","zh":"新自由促使公司重塑自身。"},{"en":"To prompt someone to do something means to cause or encourage them to do it.","zh":"prompt someone to do something 指造成或鼓勵某人做某事。"},{"en":"A teacher’s advice may prompt a student to revise earlier for exams.","zh":"老師的建議可能促使學生更早為考試溫習。"},{"en":"If falling sales prompt a shop to improve service, a problem can lead to useful change.","zh":"如果銷售下降促使商店改善服務，問題就可以帶來有用轉變。"},{"en":"The phrase introduces a trigger for action.","zh":"這個短語引出行動的觸發因素。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":12},{"front":"reinvent themselves","meaning":"重塑自身","examples":[{"en":"Smarter entertainment companies reinvented themselves.","zh":"較精明的娛樂公司重塑自身。"},{"en":"To reinvent themselves means to change their identity, strategy, or way of working in a major way.","zh":"reinvent themselves 指大幅改變自己的身份、策略或工作方式。"},{"en":"A teacher may reinvent herself by moving from textbook teaching to online course design.","zh":"老師可能從課本教學轉向網上課程設計，從而重塑自身。"},{"en":"If a company reinvents itself successfully, it can survive after old markets decline.","zh":"如果公司成功重塑自身，它可以在舊市場衰退後生存。"},{"en":"The phrase suggests deep self-transformation, not a small update.","zh":"這個短語暗示深層自我轉型，而不是小更新。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":12},{"front":"the smarter companies","meaning":"較精明的公司","examples":[{"en":"The smarter companies learned from the mistakes of their predecessors.","zh":"較精明的公司從前輩公司的錯誤中學習。"},{"en":"The smarter companies are the firms that make wiser decisions than others in the same situation.","zh":"the smarter companies 是在同一情況中作出較明智決定的企業。"},{"en":"The smarter companies train staff before new technology causes confusion.","zh":"較精明的公司會在新科技造成混亂前培訓員工。"},{"en":"If the smarter companies study past failures, they can avoid repeating them.","zh":"如果較精明的公司研究過去失敗，它們就能避免重複。"},{"en":"The phrase contrasts adaptable firms with slower or less thoughtful ones.","zh":"這個短語把能適應的企業與較慢或較欠思考的企業作對比。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":12},{"front":"predecessors","meaning":"前身；前輩公司","examples":[{"en":"Some predecessors were stuck with one form of distribution.","zh":"一些前輩公司被困於單一發放渠道。"},{"en":"Predecessors are people, companies, or things that came before the present ones.","zh":"predecessors 是在現有的人、公司或事物之前出現的前任或前身。"},{"en":"A new principal may learn from the successes and mistakes of her predecessors.","zh":"新校長可能從前任的成功和錯誤中學習。"},{"en":"If companies study their predecessors, they can understand why older strategies failed.","zh":"如果公司研究前輩公司，它們就能理解舊策略為何失敗。"},{"en":"The word links the present with earlier examples.","zh":"這個字把現在與較早例子連繫起來。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":12},{"front":"be stuck with","meaning":"被困於；只能依賴","examples":[{"en":"Old companies were stuck with one form of distribution.","zh":"舊公司被困於單一發放渠道。"},{"en":"To be stuck with something means to be unable to escape from or change it easily.","zh":"be stuck with 某物，指難以擺脫或改變它。"},{"en":"A student may be stuck with a slow laptop until they can afford a new one.","zh":"學生可能在買得起新電腦前，只能繼續用一部很慢的手提電腦。"},{"en":"If a company is stuck with one sales channel, a market shift can hurt it badly.","zh":"如果公司被困於單一銷售渠道，市場轉變可以嚴重傷害它。"},{"en":"The phrase suggests limitation and lack of flexibility.","zh":"這個短語暗示限制和缺乏彈性。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":12},{"front":"one form of distribution","meaning":"單一發放渠道","examples":[{"en":"Companies that depended on one form of distribution became vulnerable.","zh":"依賴單一發放渠道的公司變得脆弱。"},{"en":"One form of distribution means a single method of delivering products or content to users.","zh":"one form of distribution 指把產品或內容送到使用者手中的單一方法。"},{"en":"A restaurant relying only on dine-in service depends on one form of distribution.","zh":"只依賴堂食服務的餐廳，就是依賴單一發放渠道。"},{"en":"If one form of distribution fails, a company without alternatives may lose customers quickly.","zh":"如果單一發放渠道失效，而公司沒有替代方案，就可能迅速失去顧客。"},{"en":"The phrase highlights risk from depending on one channel.","zh":"這個短語突出依賴單一渠道的風險。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":12},{"front":"the powers in the entertainment business","meaning":"娛樂業的權力核心","examples":[{"en":"The powers in the entertainment business are now large integrated companies.","zh":"娛樂業的權力核心現在是大型整合公司。"},{"en":"The powers in the entertainment business are the organisations that hold the greatest control and influence in entertainment.","zh":"the powers in the entertainment business 是娛樂業中擁有最大控制力和影響力的組織。"},{"en":"Streaming platforms have become powers in the entertainment business by controlling access to audiences.","zh":"串流平台透過控制觀眾接觸渠道，成為娛樂業的權力核心。"},{"en":"If the powers in the industry change, smaller creators must adapt their strategies.","zh":"如果行業權力核心改變，較小創作者就必須調整策略。"},{"en":"The phrase refers to centres of influence, not physical strength.","zh":"這個短語指影響力中心，而不是身體力量。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":12},{"front":"no longer","meaning":"不再","examples":[{"en":"The powers are no longer just movie studios or broadcasters.","zh":"權力核心不再只是電影製片廠或廣播公司。"},{"en":"No longer means not now, although it was true before.","zh":"no longer 指現在不再如此，雖然以前是。"},{"en":"The library is no longer quiet only; it is also a place for group learning.","zh":"圖書館不再只是安靜地方；它也是小組學習場所。"},{"en":"If customers no longer visit physical shops, retailers must sell online.","zh":"如果顧客不再到實體店，零售商就必須網上銷售。"},{"en":"The phrase marks a change from past to present.","zh":"這個短語標示從過去到現在的轉變。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":12},{"front":"become part of bigger businesses","meaning":"成為更大企業的一部分","examples":[{"en":"Movie studios and publishers have become part of bigger businesses.","zh":"電影製片廠和出版商已成為更大企業的一部分。"},{"en":"To become part of bigger businesses means to be absorbed into larger companies or corporate groups.","zh":"become part of bigger businesses 指被吸收進更大型公司或企業集團。"},{"en":"A family pharmacy may become part of a bigger business after a chain buys it.","zh":"家庭藥房被連鎖店收購後，可能成為更大企業的一部分。"},{"en":"If a small studio becomes part of a bigger business, it may gain resources but lose independence.","zh":"如果小片廠成為更大企業的一部分，它可能獲得資源但失去獨立性。"},{"en":"The phrase describes corporate absorption or integration.","zh":"這個短語描述企業吸收或整合。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":12},{"front":"create content","meaning":"創作內容","examples":[{"en":"Modern entertainment companies can create content.","zh":"現代娛樂公司可以創作內容。"},{"en":"To create content means to produce material such as videos, music, articles, games, or shows.","zh":"create content 指製作影片、音樂、文章、遊戲或節目等材料。"},{"en":"A teacher creates content when she records grammar videos for students.","zh":"老師錄製文法影片給學生，就是在創作內容。"},{"en":"If a company can create content itself, it does not depend fully on outside producers.","zh":"如果公司能自行創作內容，它就不完全依賴外部製作者。"},{"en":"The phrase focuses on making media material.","zh":"這個短語重點在製作媒體材料。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":13},{"front":"distribute content","meaning":"發放內容","examples":[{"en":"Modern entertainment companies can also distribute content.","zh":"現代娛樂公司也可以發放內容。"},{"en":"To distribute content means to deliver media material to viewers, listeners, readers, or users.","zh":"distribute content 指把媒體材料送到觀眾、聽眾、讀者或用戶手中。"},{"en":"A school distributes content through an online learning platform.","zh":"學校透過網上學習平台發放內容。"},{"en":"If a company distributes content through its own app, it controls the relationship with users.","zh":"如果公司透過自家應用程式發放內容，它就控制與用戶的關係。"},{"en":"The phrase focuses on delivery and access.","zh":"這個短語重點在傳送和存取。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":13},{"front":"in a range of different ways","meaning":"以多種不同方式","examples":[{"en":"Content can now be distributed in a range of different ways.","zh":"內容現在可以以多種不同方式發放。"},{"en":"In a range of different ways means through several different methods or forms.","zh":"in a range of different ways 指透過幾種不同方法或形式。"},{"en":"A teacher can explain vocabulary in a range of different ways, including stories, pictures, and examples.","zh":"老師可以以多種不同方式解釋詞彙，包括故事、圖片和例句。"},{"en":"If customers can pay in a range of different ways, shopping becomes more convenient.","zh":"如果顧客可以以多種不同方式付款，購物就更方便。"},{"en":"The phrase stresses variety of methods.","zh":"這個短語強調方法多樣。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":13},{"front":"out of all this","meaning":"從這一切之中","examples":[{"en":"Out of all this, seven huge entertainment companies have emerged.","zh":"從這一切之中，七間大型娛樂公司冒起。"},{"en":"Out of all this means as a result of all these events, changes, or conditions.","zh":"out of all this 指作為所有這些事件、轉變或條件的結果。"},{"en":"Out of all this confusion, the team finally created a clearer plan.","zh":"從這一切混亂之中，團隊終於制定出更清晰計劃。"},{"en":"If many small changes happen together, something new may emerge out of all this.","zh":"如果許多小轉變一同發生，可能從這一切之中出現新事物。"},{"en":"The phrase introduces an outcome from a complex situation.","zh":"這個短語從複雜情況中引出結果。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":13},{"front":"huge entertainment companies","meaning":"大型娛樂公司","examples":[{"en":"Seven huge entertainment companies dominate much of the industry.","zh":"七間大型娛樂公司主導該行業大部分。"},{"en":"Huge entertainment companies are very large businesses that control major parts of media and entertainment.","zh":"huge entertainment companies 是控制媒體和娛樂重要部分的非常大型企業。"},{"en":"A huge entertainment company may own film studios, TV channels, music labels, and streaming platforms.","zh":"大型娛樂公司可能擁有電影製片廠、電視頻道、唱片品牌和串流平台。"},{"en":"If huge entertainment companies control distribution, smaller creators may struggle to reach audiences.","zh":"如果大型娛樂公司控制發放渠道，較小創作者可能難以接觸觀眾。"},{"en":"The phrase stresses size, reach, and market power.","zh":"這個短語強調規模、覆蓋範圍和市場權力。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":13},{"front":"emerge","meaning":"形成；冒起","examples":[{"en":"Seven huge companies have emerged from changes in the entertainment business.","zh":"七間大型公司從娛樂業轉變中形成。"},{"en":"To emerge means to appear, form, or become important after a process of change.","zh":"emerge 指在轉變過程後出現、形成或變得重要。"},{"en":"New leaders may emerge during a school project when problems need solving.","zh":"當專題研習需要解決問題時，新領袖可能冒起。"},{"en":"If larger companies emerge after mergers, the market becomes more concentrated.","zh":"如果合併後形成更大型公司，市場就變得更集中。"},{"en":"The word often describes something becoming visible or powerful over time.","zh":"這個字常描述某物隨時間變得可見或有力量。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":13},{"front":"cover pretty well every bit of","meaning":"幾乎涵蓋……的每一部分","examples":[{"en":"These companies cover pretty well every bit of the entertainment business.","zh":"這些公司幾乎涵蓋娛樂業的每一部分。"},{"en":"To cover pretty well every bit of something means to include almost all parts of it.","zh":"cover pretty well every bit of 某事，指幾乎包括它的所有部分。"},{"en":"A large supermarket may cover pretty well every bit of daily household shopping.","zh":"大型超級市場可能幾乎涵蓋日常家庭購物的每一部分。"},{"en":"If a company covers every part of an industry, it can influence both production and sales.","zh":"如果公司涵蓋一個行業的每一部分，它就能影響製作和銷售。"},{"en":"The phrase is informal and emphasises near-complete coverage.","zh":"這個短語較口語，強調接近全面覆蓋。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":13},{"front":"except pornography","meaning":"除了色情內容之外","examples":[{"en":"The companies cover nearly every part of entertainment except pornography.","zh":"這些公司幾乎涵蓋娛樂的每一部分，除了色情內容之外。"},{"en":"Except pornography means excluding adult sexual material from the category being discussed.","zh":"except pornography 指在所討論類別中排除成人色情材料。"},{"en":"A media company may cover films, music, games, and books, except pornography.","zh":"媒體公司可能涵蓋電影、音樂、遊戲和書籍，除了色情內容之外。"},{"en":"If a business excludes one category, its coverage may still be very broad except for that area.","zh":"如果企業排除一個類別，除了該範圍之外，其覆蓋仍可能很廣。"},{"en":"The phrase marks a specific exception to a general claim.","zh":"這個短語標示一般說法中的特定例外。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":13},{"front":"managing director of","meaning":"……的董事總經理","examples":[{"en":"Christopher Dixon is the managing director of media research at PaineWebber.","zh":"Christopher Dixon 是 PaineWebber 媒體研究的董事總經理。"},{"en":"The managing director of a department is a senior manager responsible for leading that area.","zh":"managing director of 某部門，是負責領導該範疇的高級管理人員。"},{"en":"The managing director of a school group may oversee budgets, staff, and strategy.","zh":"學校集團的董事總經理可能監督預算、人員和策略。"},{"en":"If the managing director makes a forecast, investors may take it seriously.","zh":"如果董事總經理作出預測，投資者可能認真看待。"},{"en":"The phrase identifies a senior leadership position.","zh":"這個短語指出高級領導職位。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":13},{"front":"media research","meaning":"媒體研究","examples":[{"en":"Christopher Dixon works in media research.","zh":"Christopher Dixon 從事媒體研究。"},{"en":"Media research is the study of audiences, media companies, content, advertising, and communication trends.","zh":"media research 是研究觀眾、媒體公司、內容、廣告和傳播趨勢。"},{"en":"A student doing media research may compare how teenagers use television and social media.","zh":"做媒體研究的學生可能比較青少年如何使用電視和社交媒體。"},{"en":"If media research shows viewers prefer streaming, companies may shift investment online.","zh":"如果媒體研究顯示觀眾偏好串流，公司可能把投資轉向網上。"},{"en":"The phrase describes research into how media works and changes.","zh":"這個短語描述對媒體如何運作和轉變的研究。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":13},{"front":"a stockbroker","meaning":"股票經紀公司","examples":[{"en":"PaineWebber is described as a stockbroker.","zh":"PaineWebber 被描述為股票經紀公司。"},{"en":"A stockbroker is a company or person who helps clients buy and sell shares.","zh":"a stockbroker 是幫助客戶買賣股票的公司或人士。"},{"en":"An investor may ask a stockbroker for help before buying shares in a media company.","zh":"投資者購買媒體公司股票前，可能向股票經紀公司尋求協助。"},{"en":"If a stockbroker studies an industry, its advice may influence investment decisions.","zh":"如果股票經紀公司研究一個行業，其建議可能影響投資決定。"},{"en":"The word belongs to finance and investing.","zh":"這個字屬於金融和投資範疇。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":14},{"front":"the creation of","meaning":"……的形成","examples":[{"en":"The entertainment industry is seeing the creation of a global oligopoly.","zh":"娛樂業正在見證全球寡頭壟斷的形成。"},{"en":"The creation of something means the process of making or forming it.","zh":"the creation of 某物，指製造或形成它的過程。"},{"en":"The creation of a new school club may begin with a few interested students.","zh":"新學會的形成可能由幾名有興趣的學生開始。"},{"en":"If mergers lead to the creation of a few powerful companies, competition may decrease.","zh":"如果合併導致少數強大公司的形成，競爭可能減少。"},{"en":"The phrase focuses on how something comes into existence.","zh":"這個短語重點在某物如何出現。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":14},{"front":"a global oligopoly","meaning":"全球寡頭壟斷","examples":[{"en":"Christopher Dixon describes the situation as a global oligopoly.","zh":"Christopher Dixon 把這種情況描述為全球寡頭壟斷。"},{"en":"A global oligopoly is a worldwide market controlled by a small number of very large companies.","zh":"a global oligopoly 是由少數大型公司控制的全球市場。"},{"en":"If only a few firms control most streaming platforms, the market may look like a global oligopoly.","zh":"如果只有少數公司控制大多數串流平台，市場可能像全球寡頭壟斷。"},{"en":"A global oligopoly can reduce competition and give major companies more bargaining power.","zh":"全球寡頭壟斷可以減少競爭，並給大型公司更多議價能力。"},{"en":"The phrase describes concentrated control across countries.","zh":"這個短語描述跨國集中控制。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":14},{"front":"the oil and automotive businesses","meaning":"石油及汽車行業","examples":[{"en":"Similar concentration happened earlier in the oil and automotive businesses.","zh":"類似集中化較早在石油及汽車行業發生。"},{"en":"The oil and automotive businesses are the industries dealing with oil production and motor vehicles.","zh":"the oil and automotive businesses 是處理石油生產和汽車的行業。"},{"en":"Large mergers in the oil and automotive businesses can create very powerful corporations.","zh":"石油及汽車行業的大型合併可以創造非常強大的企業。"},{"en":"If entertainment follows the oil and automotive businesses, a few giants may dominate the market.","zh":"如果娛樂業跟隨石油及汽車行業的模式，少數巨企可能主導市場。"},{"en":"The phrase names two industries used for comparison.","zh":"這個短語指出用作比較的兩個行業。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":14},{"front":"earlier this century","meaning":"本世紀較早時候","examples":[{"en":"A similar pattern happened earlier this century.","zh":"類似模式在本世紀較早時候發生。"},{"en":"Earlier this century means during the earlier part of the century being discussed.","zh":"earlier this century 指在所討論世紀的較早部分。"},{"en":"Earlier this century, many people still bought music on CDs.","zh":"本世紀較早時候，許多人仍購買 CD 音樂。"},{"en":"If a trend began earlier this century, its effects may shape today’s businesses.","zh":"如果趨勢在本世紀較早時候開始，其影響可能塑造今天的企業。"},{"en":"The phrase gives a broad historical time reference.","zh":"這個短語提供概括歷史時間參照。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":14},{"front":"it remains to be seen whether","meaning":"尚待觀察是否","examples":[{"en":"It remains to be seen whether digital technology will weaken the giants.","zh":"數碼科技是否會削弱那些巨企仍有待觀察。"},{"en":"It remains to be seen whether means the answer is still unknown and will become clear later.","zh":"it remains to be seen whether 指答案仍未知，之後才會變清楚。"},{"en":"It remains to be seen whether the new timetable will improve students’ results.","zh":"新時間表是否會改善學生成績仍有待觀察。"},{"en":"If a policy is new, it remains to be seen whether people will accept it.","zh":"如果政策是新的，人們是否會接受仍有待觀察。"},{"en":"The phrase expresses uncertainty about a future result.","zh":"這個短語表達對未來結果的不確定。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":14},{"front":"the latest technology","meaning":"最新科技","examples":[{"en":"The latest technology may weaken or strengthen major companies.","zh":"最新科技可能削弱或加強主要公司。"},{"en":"The latest technology means the newest tools, systems, or technical developments available.","zh":"the latest technology 指目前可用的最新工具、系統或技術發展。"},{"en":"A hospital may use the latest technology to scan patients more accurately.","zh":"醫院可能使用最新科技更準確地掃描病人。"},{"en":"If a school buys the latest technology without training teachers, it may waste money.","zh":"如果學校購買最新科技卻不培訓老師，可能浪費金錢。"},{"en":"The phrase stresses newness, not automatically usefulness.","zh":"這個短語強調新，但不代表一定有用。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":14},{"front":"weaken those great companies","meaning":"削弱那些大公司","examples":[{"en":"The digital revolution could weaken those great companies.","zh":"數碼革命可能削弱那些大公司。"},{"en":"To weaken those great companies means to reduce the power, profits, or influence of major firms.","zh":"weaken those great companies 指減少主要公司的權力、利潤或影響力。"},{"en":"Small online sellers can weaken large shops if customers prefer lower prices and convenience.","zh":"如果顧客偏好低價和便利，小型網店可以削弱大型商店。"},{"en":"If technology gives creators direct access to audiences, it may weaken those great companies.","zh":"如果科技讓創作者直接接觸觀眾，它可能削弱那些大公司。"},{"en":"The phrase describes a possible loss of strength among dominant firms.","zh":"這個短語描述主導企業可能失去力量。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":14},{"front":"stronger than ever","meaning":"比以往更強大","examples":[{"en":"The latest technology may make the giants stronger than ever.","zh":"最新科技可能令巨企比以往更強大。"},{"en":"Stronger than ever means more powerful, successful, or secure than at any previous time.","zh":"stronger than ever 指比過去任何時候都更有力量、更成功或更穩固。"},{"en":"After improving its online service, a small school’s reputation became stronger than ever.","zh":"改善網上服務後，一間小學校的聲譽比以往更強。"},{"en":"If a company uses new technology well, it may become stronger than ever while rivals fall behind.","zh":"如果公司善用新科技，它可能在競爭者落後時比以往更強大。"},{"en":"The phrase describes a new peak of strength.","zh":"這個短語描述力量的新高峰。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":14},{"front":"reading passage","meaning":"閱讀篇章","examples":[{"en":"Reading Passage 2 has seven paragraphs.","zh":"閱讀篇章二有七段。"},{"en":"A reading passage is a text used for reading practice or examination questions.","zh":"reading passage 是用於閱讀練習或考試題目的文本。"},{"en":"Students should skim the reading passage before answering detailed questions.","zh":"學生回答細節題前，應先略讀閱讀篇章。"},{"en":"If a reading passage has many names and dates, careful note-taking may help.","zh":"如果閱讀篇章有許多人名和日期，仔細記筆記可能有幫助。"},{"en":"The phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":14},{"front":"mention the following","meaning":"提及以下內容","examples":[{"en":"The question asks which paragraph mentions the following information.","zh":"題目問哪一段提及以下資料。"},{"en":"Mention the following means refer to the details listed after the instruction.","zh":"mention the following 指提到指示後列出的細節。"},{"en":"A worksheet may ask students to find which paragraph mentions the following causes of pollution.","zh":"工作紙可能要求學生找出哪段提及以下污染原因。"},{"en":"If a paragraph mentions the following information, students should match it carefully.","zh":"如果某段提及以下資料，學生應仔細配對。"},{"en":"The phrase introduces a matching task based on specific details.","zh":"這個短語引出基於具體細節的配對題。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":15},{"front":"appropriate letters","meaning":"適當字母","examples":[{"en":"Students write the appropriate letters in the answer boxes.","zh":"學生在答案框中寫上適當字母。"},{"en":"Appropriate letters are the correct letter choices that match the questions.","zh":"appropriate letters 是與題目相配的正確字母選項。"},{"en":"In a matching exercise, students may write appropriate letters such as A, C, or F.","zh":"在配對練習中，學生可能寫上 A、C 或 F 等適當字母。"},{"en":"If students write inappropriate letters, the answer will not match the passage.","zh":"如果學生寫上不適當字母，答案就不會與文章相符。"},{"en":"The phrase refers to answer format, not handwriting style.","zh":"這個短語指答案格式，而不是字體。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":15},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"Answers should be written on the answer sheet.","zh":"答案應寫在答題紙上。"},{"en":"An answer sheet is the paper or digital form where candidates record their final answers.","zh":"answer sheet 是考生記錄最終答案的紙張或電子表格。"},{"en":"During exams, students should copy answers carefully onto the answer sheet before time ends.","zh":"考試期間，學生應在時間完結前小心把答案抄到答題紙上。"},{"en":"If an answer is correct but not on the answer sheet, it may not be marked.","zh":"如果答案正確但沒有寫在答題紙上，可能不會被評分。"},{"en":"The phrase refers to the official place for answers.","zh":"這個短語指官方填寫答案的地方。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":15},{"front":"be used more than once","meaning":"被使用多於一次","examples":[{"en":"Some paragraphs will be used more than once.","zh":"有些段落會被使用多於一次。"},{"en":"To be used more than once means to be selected or applied multiple times.","zh":"be used more than once 指被選擇或應用多次。"},{"en":"In a grammar exercise, the same word may be used more than once if it fits several blanks.","zh":"在文法練習中，如果同一字適合幾個空格，它可以被使用多於一次。"},{"en":"If a paragraph contains several answers, it may be used more than once in matching questions.","zh":"如果一段包含幾個答案，它在配對題中可能被使用多於一次。"},{"en":"The phrase warns students not to assume each option is used only one time.","zh":"這個短語提醒學生不要假設每個選項只用一次。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":15},{"front":"contrasting effects","meaning":"相反的影響","examples":[{"en":"The question refers to the contrasting effects of new technology.","zh":"題目指新科技的相反影響。"},{"en":"Contrasting effects are different or opposite results produced by the same thing.","zh":"contrasting effects 是同一事物造成的不同或相反結果。"},{"en":"Homework can have contrasting effects: it helps practice but may also increase stress.","zh":"功課可以有相反影響：它有助練習，但也可能增加壓力。"},{"en":"If new technology brings profit to one company but loss to another, it has contrasting effects.","zh":"如果新科技為一間公司帶來利潤，卻令另一間公司虧損，它就有相反影響。"},{"en":"The phrase highlights both sides of an influence.","zh":"這個短語突出一種影響的兩面。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":15},{"front":"new technology can have on","meaning":"新科技可以對……產生的影響","examples":[{"en":"New technology can have contrasting effects on existing businesses.","zh":"新科技可以對現有企業產生相反影響。"},{"en":"New technology can have on something means new tools or systems can produce an effect on it.","zh":"new technology can have on 某物，指新工具或系統可以對它產生影響。"},{"en":"Online learning can have a strong effect on students who live far from school.","zh":"網上學習可以對住得離學校很遠的學生產生強烈影響。"},{"en":"If technology has an effect on work habits, staff may need new training.","zh":"如果科技對工作習慣產生影響，員工可能需要新培訓。"},{"en":"The phrase links a cause with the thing being affected.","zh":"這個短語把原因與受影響對象連繫起來。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":15},{"front":"existing business","meaning":"現有企業","examples":[{"en":"The question asks about effects on existing business.","zh":"題目問對現有企業的影響。"},{"en":"Existing business means companies or commercial activities already operating before a change occurs.","zh":"existing business 指轉變發生前已經營運的公司或商業活動。"},{"en":"A new shopping centre can affect existing business in nearby streets.","zh":"新商場可以影響附近街道的現有企業。"},{"en":"If existing business fails to adapt, new competitors may take customers away.","zh":"如果現有企業未能適應，新競爭者可能搶走顧客。"},{"en":"The phrase contrasts current firms with new entrants or future plans.","zh":"這個短語把現有公司與新加入者或未來計劃作對比。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":15},{"front":"total transformation","meaning":"全面轉變","examples":[{"en":"A total transformation may take place in entertainment delivery.","zh":"娛樂內容發放可能出現全面轉變。"},{"en":"Total transformation means a complete and major change in form, structure, or operation.","zh":"total transformation 指形式、結構或運作上的完整重大改變。"},{"en":"A school may undergo total transformation if it becomes fully digital and changes all lessons.","zh":"如果學校完全數碼化並改變所有課堂，它可能經歷全面轉變。"},{"en":"If entertainment delivery experiences total transformation, old business models may disappear.","zh":"如果娛樂內容發放經歷全面轉變，舊商業模式可能消失。"},{"en":"The phrase describes deep change, not small improvement.","zh":"這個短語描述深層改變，而不是小改善。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":15},{"front":"take place in the future","meaning":"在未來發生","examples":[{"en":"The passage predicts changes that will take place in the future.","zh":"文章預測將在未來發生的轉變。"},{"en":"To take place in the future means to happen at a later time.","zh":"take place in the future 指在較後時間發生。"},{"en":"The school announced changes that will take place in the future, not this term.","zh":"學校宣布的改變會在未來發生，而不是本學期。"},{"en":"If a plan will take place in the future, people still have time to prepare.","zh":"如果計劃會在未來發生，人們仍有時間準備。"},{"en":"The phrase separates future events from present reality.","zh":"這個短語把未來事件與當前現實分開。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":15},{"front":"delivery of all forms of entertainment","meaning":"各種娛樂內容的發放","examples":[{"en":"Digital technology may change the delivery of all forms of entertainment.","zh":"數碼科技可能改變各種娛樂內容的發放。"},{"en":"Delivery of all forms of entertainment means how every type of entertainment reaches audiences.","zh":"delivery of all forms of entertainment 指每種娛樂內容如何到達觀眾。"},{"en":"Apps have changed the delivery of films, games, music, and live shows.","zh":"應用程式已改變電影、遊戲、音樂和現場表演的發放。"},{"en":"If delivery becomes digital, audiences can access entertainment without visiting shops or cinemas.","zh":"如果發放變成數碼化，觀眾不用到商店或戲院也能接觸娛樂。"},{"en":"The phrase focuses on distribution across many media types.","zh":"這個短語重點在多種媒體類型的分發。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":15},{"front":"confused feelings","meaning":"複雜而矛盾的感受","examples":[{"en":"People may have confused feelings in response to innovation.","zh":"人們可能因應創新而有複雜而矛盾的感受。"},{"en":"Confused feelings are mixed emotions that are hard to separate or understand clearly.","zh":"confused feelings 是難以清楚分開或理解的混合情緒。"},{"en":"A student may have confused feelings after receiving both praise and criticism for the same essay.","zh":"學生同一篇文章同時得到讚賞和批評後，可能有複雜感受。"},{"en":"If a change brings both opportunity and risk, confused feelings are natural.","zh":"如果轉變同時帶來機會和風險，複雜而矛盾的感受是自然的。"},{"en":"The phrase describes emotional uncertainty.","zh":"這個短語描述情緒上的不確定。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":16},{"front":"be known to have experienced","meaning":"已知曾經歷過","examples":[{"en":"People are known to have experienced mixed emotions during technological change.","zh":"人們已知曾在科技轉變期間經歷混合情緒。"},{"en":"To be known to have experienced something means evidence shows that people did experience it.","zh":"be known to have experienced 某事，指證據顯示人們確實經歷過它。"},{"en":"Patients are known to have experienced anxiety before major surgery.","zh":"病人已知曾在大型手術前經歷焦慮。"},{"en":"If workers are known to have experienced stress during restructuring, managers should offer support.","zh":"如果員工已知曾在重組期間經歷壓力，管理層應提供支援。"},{"en":"The phrase presents something as recognised or documented.","zh":"這個短語把某事呈現為被認知或有紀錄。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":16},{"front":"in response to","meaning":"回應；因應","examples":[{"en":"Companies reacted with fear in response to technological innovation.","zh":"公司因應科技創新而以恐懼反應。"},{"en":"In response to means because of something or as a reaction to it.","zh":"in response to 指因為某事或作為對它的反應。"},{"en":"A school may add counselling services in response to student stress.","zh":"學校可能因應學生壓力而增加輔導服務。"},{"en":"If prices rise in response to higher costs, customers may buy less.","zh":"如果價格因成本上升而上調，顧客可能買少了。"},{"en":"The phrase links an action with the event that caused it.","zh":"這個短語把行動與造成它的事件連繫起來。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":16},{"front":"technological innovation","meaning":"科技創新","examples":[{"en":"Technological innovation often changes entire industries.","zh":"科技創新常改變整個行業。"},{"en":"Technological innovation is the creation or use of new technology to solve problems or improve work.","zh":"technological innovation 是創造或使用新科技來解決問題或改善工作。"},{"en":"Contactless payment is a technological innovation that makes shopping faster.","zh":"感應式付款是一項令購物更快的科技創新。"},{"en":"If technological innovation lowers costs, companies may change how they serve customers.","zh":"如果科技創新降低成本，公司可能改變服務顧客的方式。"},{"en":"The phrase refers to new technology that affects real practice.","zh":"這個短語指影響實際做法的新科技。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":16},{"front":"learn from the mistakes of others","meaning":"從別人的錯誤中學習","examples":[{"en":"Some companies have learnt from the mistakes of others.","zh":"一些公司已從別人的錯誤中學習。"},{"en":"To learn from the mistakes of others means to avoid repeating problems that other people or companies already experienced.","zh":"learn from the mistakes of others 指避免重複其他人或公司已經經歷過的問題。"},{"en":"A student can learn from the mistakes of classmates by checking common grammar errors.","zh":"學生可以透過檢查同學常犯文法錯誤，從別人的錯誤中學習。"},{"en":"If a company studies failed competitors, it can learn from the mistakes of others before launching a product.","zh":"如果公司研究失敗競爭者，它可以在推出產品前從別人的錯誤中學習。"},{"en":"The phrase stresses indirect learning through observation.","zh":"這個短語強調透過觀察作間接學習。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":16},{"front":"high cost to the consumer","meaning":"消費者需承擔的高昂成本","examples":[{"en":"The high cost to the consumer limited early digital television.","zh":"消費者需承擔的高昂成本限制了早期數碼電視。"},{"en":"High cost to the consumer means the buyer has to pay too much to use or buy something.","zh":"high cost to the consumer 指買家要支付太多金錢才能使用或購買某物。"},{"en":"High cost to the consumer can stop families from using private healthcare.","zh":"消費者需承擔的高昂成本可以阻止家庭使用私營醫療。"},{"en":"If a useful technology has a high cost to the consumer, many people will wait for cheaper versions.","zh":"如果有用科技對消費者而言成本高昂，許多人會等待較便宜版本。"},{"en":"The phrase focuses on price from the customer’s side.","zh":"這個短語從顧客角度看價格。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":16},{"front":"uncertainty regarding","meaning":"關於……的不確定性","examples":[{"en":"There is uncertainty regarding the financial impact of wider media access.","zh":"關於更廣泛媒體接觸途徑的財務影響，仍存在不確定性。"},{"en":"Uncertainty regarding something means lack of clear knowledge about it.","zh":"uncertainty regarding 某事，指對它缺乏清楚了解。"},{"en":"There is uncertainty regarding tomorrow’s outdoor event because heavy rain is possible.","zh":"由於可能有大雨，關於明天戶外活動仍有不確定性。"},{"en":"If there is uncertainty regarding costs, a business may delay investment.","zh":"如果關於成本存在不確定性，企業可能延遲投資。"},{"en":"The phrase introduces an area where people are not yet sure.","zh":"這個短語引出人們尚未確定的範疇。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":16},{"front":"financial impact","meaning":"財務影響","examples":[{"en":"The financial impact of the digital revolution is still uncertain.","zh":"數碼革命的財務影響仍不確定。"},{"en":"Financial impact means the effect something has on income, costs, profit, or money management.","zh":"financial impact 指某事對收入、成本、利潤或金錢管理的影響。"},{"en":"A rent increase has a financial impact on families and small shops.","zh":"加租會對家庭和小店造成財務影響。"},{"en":"If a new machine cuts labour costs, its financial impact may be positive.","zh":"如果新機器降低人工成本，其財務影響可能是正面的。"},{"en":"The phrase focuses on money-related consequences.","zh":"這個短語重點在與金錢相關的後果。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":16},{"front":"wider media access","meaning":"更廣泛的媒體接觸途徑","examples":[{"en":"Wider media access may change the economics of entertainment.","zh":"更廣泛的媒體接觸途徑可能改變娛樂業的經濟運作。"},{"en":"Wider media access means more people can reach more kinds of media through more channels.","zh":"wider media access 指更多人可透過更多渠道接觸更多種類的媒體。"},{"en":"Cheap smartphones created wider media access for students in rural areas.","zh":"便宜智能手機為鄉村學生創造更廣泛的媒體接觸途徑。"},{"en":"If wider media access increases audience numbers, companies may gain new revenue.","zh":"如果更廣泛媒體接觸途徑增加觀眾數量，公司可能得到新收入。"},{"en":"The phrase describes broader availability of media content.","zh":"這個短語描述媒體內容更廣泛可得。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":16},{"front":"victims of","meaning":"……的受害者","examples":[{"en":"Some companies were victims of strict government policy.","zh":"一些公司是嚴格政府政策的受害者。"},{"en":"Victims of something are people or organisations harmed by it.","zh":"victims of 某事，是受到它傷害的人或組織。"},{"en":"Small shops can become victims of rising rent if they cannot afford new leases.","zh":"如果小店負擔不起新租約，它們可能成為租金上升的受害者。"},{"en":"If companies are victims of regulation, they may lose opportunities that newer firms later enjoy.","zh":"如果公司是監管的受害者，它們可能失去後來新公司享有的機會。"},{"en":"The phrase identifies who suffers from a cause.","zh":"這個短語指出誰因某原因受害。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":16},{"front":"strict government policy","meaning":"嚴格的政府政策","examples":[{"en":"Strict government policy limited some older companies.","zh":"嚴格的政府政策限制了一些較舊公司。"},{"en":"Strict government policy means firm official rules made by the government.","zh":"strict government policy 指政府制定的嚴格官方規則。"},{"en":"Strict government policy on food safety can require restaurants to pass regular inspections.","zh":"嚴格的食品安全政府政策可以要求餐廳定期通過檢查。"},{"en":"If strict government policy limits ownership, companies may be unable to expand freely.","zh":"如果嚴格政府政策限制擁有權，公司可能無法自由擴張。"},{"en":"The phrase describes strong state control through rules.","zh":"這個短語描述透過規則進行的強力政府控制。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":17},{"front":"undermine giant entertainment companies","meaning":"削弱大型娛樂公司","examples":[{"en":"The digital revolution could undermine giant entertainment companies.","zh":"數碼革命可能削弱大型娛樂公司。"},{"en":"To undermine giant entertainment companies means to weaken the power of very large entertainment firms.","zh":"undermine giant entertainment companies 指削弱非常大型娛樂公司的權力。"},{"en":"Independent creators may undermine giant entertainment companies if they reach audiences directly online.","zh":"如果獨立創作者能直接在網上接觸觀眾，他們可能削弱大型娛樂公司。"},{"en":"If customers stop using traditional channels, giant companies may lose control over distribution.","zh":"如果顧客停止使用傳統渠道，巨企可能失去對發放的控制。"},{"en":"The phrase describes a possible challenge to dominant firms.","zh":"這個短語描述對主導企業的可能挑戰。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":17},{"front":"refer to","meaning":"提到；指稱","examples":[{"en":"The writer refers to various individuals and companies.","zh":"作者提到不同人物及公司。"},{"en":"To refer to someone or something means to mention or talk about them.","zh":"refer to 某人或某物，指提及或談及他們。"},{"en":"A teacher may refer to yesterday’s lesson when explaining a new grammar point.","zh":"老師解釋新文法點時，可能提到昨天的課。"},{"en":"If an article refers to many companies, readers should track who does what.","zh":"如果文章提到許多公司，讀者應追蹤誰做了甚麼。"},{"en":"The phrase means mention, not necessarily recommend.","zh":"這個短語意思是提及，不一定是推薦。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":17},{"front":"various individuals and companies","meaning":"不同人物及公司","examples":[{"en":"The passage refers to various individuals and companies.","zh":"文章提到不同人物及公司。"},{"en":"Various individuals and companies means several different people and business organisations.","zh":"various individuals and companies 指幾個不同人物和商業組織。"},{"en":"A news report about an industry may mention various individuals and companies involved in the issue.","zh":"關於某行業的新聞報道可能提到涉及該議題的不同人物及公司。"},{"en":"If a text includes various individuals and companies, matching questions may test who said what.","zh":"如果文本包括不同人物及公司，配對題可能測試誰說了甚麼。"},{"en":"The phrase highlights a mixture of named people and firms.","zh":"這個短語突出有名字的人和公司的混合。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":17},{"front":"points made about","meaning":"關於……所提出的觀點","examples":[{"en":"Students match people with points made about new technology.","zh":"學生把人物與關於新科技所提出的觀點配對。"},{"en":"Points made about something are ideas, claims, or arguments stated about it.","zh":"points made about 某事，是關於它所陳述的想法、主張或論點。"},{"en":"In a debate, students list points made about homework before deciding their opinion.","zh":"在辯論中，學生先列出關於功課所提出的觀點，再決定意見。"},{"en":"If several experts make different points about technology, readers must compare them carefully.","zh":"如果幾位專家對科技提出不同觀點，讀者必須仔細比較。"},{"en":"The phrase refers to stated ideas, not physical points.","zh":"這個短語指被陳述的想法，而不是實體點。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":17},{"front":"introduction of new technology","meaning":"新科技的引入","examples":[{"en":"The introduction of new technology has often alarmed established businesses.","zh":"新科技的引入常令老牌企業感到憂慮。"},{"en":"The introduction of new technology means the start of using a new tool, system, or method.","zh":"introduction of new technology 指開始使用新工具、系統或方法。"},{"en":"The introduction of tablets in class changed how students took notes.","zh":"平板電腦在課堂中的引入改變了學生記筆記的方式。"},{"en":"If the introduction of new technology is rushed, workers may feel confused.","zh":"如果新科技的引入太急，員工可能感到混亂。"},{"en":"The phrase focuses on the moment a new technology enters use.","zh":"這個短語重點在新科技開始投入使用的一刻。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":17},{"front":"historically","meaning":"從歷史上看","examples":[{"en":"Historically, new forms of distribution have worried established companies.","zh":"從歷史上看，新的發放形式令老牌公司憂慮。"},{"en":"Historically means according to what happened in the past.","zh":"historically 指根據過去發生的事來看。"},{"en":"Historically, many students learned mainly through books before online videos became common.","zh":"從歷史上看，在網上影片普及前，許多學生主要透過書本學習。"},{"en":"If a pattern has appeared historically, it may help explain present behaviour.","zh":"如果一種模式從歷史上看曾出現，它可能幫助解釋現在行為。"},{"en":"The word introduces evidence from earlier periods.","zh":"這個字引出早期時期的證據。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":17},{"front":"new forms of distributing entertainment","meaning":"發放娛樂內容的新形式","examples":[{"en":"New forms of distributing entertainment have repeatedly changed the industry.","zh":"發放娛樂內容的新形式反覆改變該行業。"},{"en":"New forms of distributing entertainment are new ways to send films, music, shows, or games to audiences.","zh":"new forms of distributing entertainment 是把電影、音樂、節目或遊戲送給觀眾的新方式。"},{"en":"Streaming is one of the new forms of distributing entertainment to homes and phones.","zh":"串流是向家庭和手機發放娛樂內容的新形式之一。"},{"en":"If new forms of distribution grow quickly, older channels may lose influence.","zh":"如果新發放形式快速增長，舊渠道可能失去影響力。"},{"en":"The phrase focuses on delivery methods rather than content itself.","zh":"這個短語重點在發放方法，而不是內容本身。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":17},{"front":"alarm those well-established in","meaning":"令在……中根基穩固的人感到憂慮","examples":[{"en":"New distribution methods can alarm those well-established in the business.","zh":"新發放方式可以令在行業中根基穩固的人感到憂慮。"},{"en":"To alarm those well-established in a business means to make existing powerful players worried.","zh":"alarm those well-established in 某行業，指令現有強大參與者擔心。"},{"en":"A new online tutor platform may alarm schools well-established in exam preparation.","zh":"新網上補習平台可能令在考試補習中根基穩固的學校感到憂慮。"},{"en":"If newcomers offer cheaper services, they can alarm those already strong in the market.","zh":"如果新加入者提供較便宜服務，就可以令市場中已有實力的人憂慮。"},{"en":"The phrase shows how change frightens established groups.","zh":"這個短語顯示轉變如何使既有群體害怕。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":17},{"front":"well-established in the business","meaning":"在行業中根基穩固的","examples":[{"en":"Companies well-established in the business often fear new technology.","zh":"在行業中根基穩固的公司常害怕新科技。"},{"en":"Well-established in the business means long present, recognised, and powerful in an industry.","zh":"well-established in the business 指在行業中存在已久、受認可並有實力。"},{"en":"A language school well-established in the business may already have loyal students and a strong reputation.","zh":"在行業中根基穩固的語言學校可能已擁有忠實學生和強大聲譽。"},{"en":"If a company is well-established, it may resist changes that threaten its old advantages.","zh":"如果公司根基穩固，它可能抗拒威脅舊有優勢的轉變。"},{"en":"The phrase describes a strong existing position.","zh":"這個短語描述強大的既有位置。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":17},{"front":"merger of entertainment companies","meaning":"娛樂公司的合併","examples":[{"en":"The merger of entertainment companies follows a wider industrial pattern.","zh":"娛樂公司的合併遵循更廣泛的工業模式。"},{"en":"Merger of entertainment companies means two or more entertainment businesses joining into one larger organisation.","zh":"merger of entertainment companies 指兩間或以上娛樂企業合成一個更大組織。"},{"en":"A merger of film and music companies can create a group that controls many kinds of content.","zh":"電影和音樂公司的合併可以創造控制多種內容的集團。"},{"en":"If mergers reduce the number of competitors, the market becomes more concentrated.","zh":"如果合併減少競爭者數量，市場就會更集中。"},{"en":"The phrase describes corporate combination in entertainment.","zh":"這個短語描述娛樂業中的企業結合。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":18},{"front":"follow a pattern","meaning":"遵循一種模式","examples":[{"en":"The consolidation of entertainment companies follows a pattern seen elsewhere.","zh":"娛樂公司的整合遵循其他地方可見的模式。"},{"en":"To follow a pattern means to develop in a way similar to previous examples.","zh":"follow a pattern 指以類似早前例子的方式發展。"},{"en":"A student’s mistakes may follow a pattern if they always involve verb tense.","zh":"如果學生的錯誤總涉及動詞時態，就可能遵循一種模式。"},{"en":"If mergers follow a pattern seen in other industries, analysts may predict the next stage.","zh":"如果合併遵循其他行業可見的模式，分析師可能預測下一階段。"},{"en":"The phrase suggests repeated structure, not random events.","zh":"這個短語暗示重複的結構，而不是隨機事件。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":18},{"front":"evident in","meaning":"在……中明顯可見","examples":[{"en":"The same pattern is evident in other industries.","zh":"同一模式在其他行業中明顯可見。"},{"en":"Evident in means clearly seen or shown in something.","zh":"evident in 指在某事中清楚可見或顯示出來。"},{"en":"The student’s progress is evident in her clearer essays and stronger speaking.","zh":"學生的進步在她更清晰的文章和更強的口語中明顯可見。"},{"en":"If rising prices are evident in supermarkets, families may reduce spending.","zh":"如果價格上升在超級市場中明顯可見，家庭可能減少開支。"},{"en":"The phrase points to visible evidence.","zh":"這個短語指出可見證據。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":18},{"front":"other industries","meaning":"其他行業","examples":[{"en":"Similar mergers have happened in other industries.","zh":"類似合併曾在其他行業發生。"},{"en":"Other industries are business sectors outside the one currently being discussed.","zh":"other industries 是目前討論行業以外的商業界別。"},{"en":"A trend in education may also appear in other industries such as healthcare or retail.","zh":"教育中的趨勢也可能出現在醫療或零售等其他行業。"},{"en":"If media consolidation resembles other industries, the change may be part of a wider economic pattern.","zh":"如果媒體整合類似其他行業，這種轉變可能是一個更廣泛經濟模式的一部分。"},{"en":"The phrase helps compare one sector with others.","zh":"這個短語幫助把一個界別與其他界別比較。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":18},{"front":"major entertainment bodies","meaning":"主要娛樂機構","examples":[{"en":"Major entertainment bodies may lose influence if they remain independent.","zh":"主要娛樂機構如果保持獨立，可能失去影響力。"},{"en":"Major entertainment bodies are important organisations or companies in the entertainment industry.","zh":"major entertainment bodies 是娛樂業中的重要組織或公司。"},{"en":"A major entertainment body may own famous films, music catalogues, or television channels.","zh":"主要娛樂機構可能擁有著名電影、音樂目錄或電視頻道。"},{"en":"If major entertainment bodies do not join larger groups, they may lack money or distribution power.","zh":"如果主要娛樂機構不加入大型集團，它們可能缺乏資金或發放權力。"},{"en":"The phrase refers to big institutional players in entertainment.","zh":"這個短語指娛樂業中的大型制度性參與者。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":18},{"front":"remain independent","meaning":"保持獨立","examples":[{"en":"Some entertainment companies lost influence when they remained independent.","zh":"一些娛樂公司保持獨立時失去影響力。"},{"en":"To remain independent means to continue operating without being owned or controlled by a larger group.","zh":"remain independent 指繼續在沒有被大型集團擁有或控制下運作。"},{"en":"A small school may remain independent instead of joining a large education chain.","zh":"小型學校可能保持獨立，而不是加入大型教育連鎖。"},{"en":"If a company remains independent, it keeps freedom but may have fewer resources.","zh":"如果公司保持獨立，它保留自由，但可能資源較少。"},{"en":"The phrase highlights both autonomy and possible vulnerability.","zh":"這個短語同時突出自主和可能的脆弱性。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":18},{"front":"lose their influence","meaning":"失去影響力","examples":[{"en":"Independent entertainment companies may lose their influence.","zh":"獨立娛樂公司可能失去影響力。"},{"en":"To lose their influence means to have less power to affect decisions, markets, or audiences.","zh":"lose their influence 指在影響決策、市場或觀眾方面變得較弱。"},{"en":"A teacher may lose influence if students stop trusting her advice.","zh":"如果學生不再信任老師的建議，她可能失去影響力。"},{"en":"If small studios cannot reach audiences, they may lose their influence in the industry.","zh":"如果小片廠不能接觸觀眾，它們可能在行業中失去影響力。"},{"en":"The phrase describes declining power rather than complete disappearance.","zh":"這個短語描述權力下降，而不是完全消失。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":18},{"front":"the most recent technological development","meaning":"最新科技發展","examples":[{"en":"The most recent technological development had been discussed years earlier.","zh":"最新科技發展在數年前已被討論。"},{"en":"The most recent technological development means the newest major change in technology at the time.","zh":"the most recent technological development 指當時最新的重大科技轉變。"},{"en":"A school may study the most recent technological development in online assessment.","zh":"學校可能研究網上評核中的最新科技發展。"},{"en":"If the most recent technological development was predicted earlier, people had warning before it arrived.","zh":"如果最新科技發展較早已被預測，人們在它到來前已有警告。"},{"en":"The phrase identifies the latest important innovation.","zh":"這個短語指出最新的重要創新。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":18},{"front":"be published some years ago","meaning":"數年前已被刊登","examples":[{"en":"News of the development was published some years ago.","zh":"有關該發展的消息數年前已被刊登。"},{"en":"To be published some years ago means to have been printed or released publicly several years earlier.","zh":"be published some years ago 指在幾年前已被印刷或公開發布。"},{"en":"A research report may have been published some years ago but still be useful today.","zh":"研究報告可能數年前已被刊登，但今天仍有用。"},{"en":"If an idea was published years ago, it may not be as new as people think.","zh":"如果某想法數年前已被刊登，它可能不像人們想像般新。"},{"en":"The phrase gives a past publication time without an exact date.","zh":"這個短語提供沒有精確日期的過去出版時間。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":18},{"front":"choose the appropriate letters","meaning":"選出適當字母","examples":[{"en":"Students choose the appropriate letters from the options.","zh":"學生從選項中選出適當字母。"},{"en":"Choose the appropriate letters means select the correct lettered answers.","zh":"choose the appropriate letters 指選出以字母標示的正確答案。"},{"en":"In a matching question, students should choose the appropriate letters after checking each paragraph.","zh":"在配對題中，學生應檢查每段後選出適當字母。"},{"en":"If students choose letters too quickly, they may miss a better match later.","zh":"如果學生太快選字母，可能之後錯過更合適配對。"},{"en":"The phrase gives an exam instruction about answer format.","zh":"這個短語給出關於答案格式的考試指示。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":18},{"front":"put across her views","meaning":"表達她的看法","examples":[{"en":"The question asks how the writer puts across her views.","zh":"題目問作者如何表達她的看法。"},{"en":"To put across her views means to express or communicate her opinions clearly.","zh":"put across her views 指清楚表達或傳達她的意見。"},{"en":"A student can put across her views better by using examples and clear reasons.","zh":"學生可以透過例子和清楚理由，更好地表達她的看法。"},{"en":"If a writer uses comparisons, she may put across her views more persuasively.","zh":"如果作者使用比較，她可能更有說服力地表達看法。"},{"en":"The phrase focuses on how opinions are presented.","zh":"這個短語重點在意見如何被呈現。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":19},{"front":"examine the forms of media","meaning":"審視媒體形式","examples":[{"en":"One option says the writer examines the forms of media affected by technology.","zh":"一個選項說作者審視受科技影響的媒體形式。"},{"en":"To examine the forms of media means to study different kinds of media carefully.","zh":"examine the forms of media 指仔細研究不同種類的媒體。"},{"en":"Students may examine the forms of media young people use, such as videos, podcasts, and social platforms.","zh":"學生可能審視年輕人使用的媒體形式，例如影片、播客和社交平台。"},{"en":"If researchers examine media forms, they can see which ones are most affected by digital change.","zh":"如果研究者審視媒體形式，他們就能看出哪些最受數碼轉變影響。"},{"en":"The phrase suggests careful study of media types.","zh":"這個短語暗示仔細研究媒體種類。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":19},{"front":"be affected by","meaning":"受到……影響","examples":[{"en":"Many forms of media will be affected by the digital revolution.","zh":"許多媒體形式將受到數碼革命影響。"},{"en":"To be affected by something means to be changed or influenced by it.","zh":"be affected by 某事，指被它改變或影響。"},{"en":"Students’ sleep can be affected by late-night phone use.","zh":"學生睡眠可能受到深夜使用手機影響。"},{"en":"If transport is affected by heavy rain, workers may arrive late.","zh":"如果交通受到大雨影響，員工可能遲到。"},{"en":"The phrase describes influence, not always damage.","zh":"這個短語描述影響，不一定是傷害。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":19},{"front":"analyse the way","meaning":"分析……的方式","examples":[{"en":"The option mentions analysing the way companies have reacted.","zh":"選項提到分析公司反應的方式。"},{"en":"To analyse the way something happens means to study the method, pattern, or reasons behind it.","zh":"analyse the way 某事發生，指研究其方法、模式或背後原因。"},{"en":"A teacher may analyse the way students answer questions to find common mistakes.","zh":"老師可能分析學生答題方式，以找出常見錯誤。"},{"en":"If a manager analyses the way customers complain, she can improve service.","zh":"如果經理分析顧客投訴的方式，她就可以改善服務。"},{"en":"The phrase suggests careful explanation, not simple description only.","zh":"這個短語暗示仔細解釋，而不只是簡單描述。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":19},{"front":"react to","meaning":"對……作出反應","examples":[{"en":"Entertainment companies have reacted differently to new technology.","zh":"娛樂公司對新科技作出不同反應。"},{"en":"To react to something means to respond to it in thought, feeling, or action.","zh":"react to 某事，指在想法、感受或行動上回應它。"},{"en":"Students may react to a surprise test with panic, calmness, or determination.","zh":"學生可能對突擊測驗作出恐慌、冷靜或下定決心的反應。"},{"en":"If customers react badly to a price increase, sales may fall.","zh":"如果顧客對加價反應差，銷售可能下跌。"},{"en":"The phrase focuses on response.","zh":"這個短語重點在回應。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":19},{"front":"a personal definition of","meaning":"……的個人定義","examples":[{"en":"The option refers to a personal definition of technological innovation.","zh":"選項指科技創新的個人定義。"},{"en":"A personal definition of something is one person’s own explanation of what it means.","zh":"a personal definition of 某事，是某個人自己對其意思的解釋。"},{"en":"A student may give a personal definition of success based on happiness rather than money.","zh":"學生可能基於快樂而不是金錢，給出成功的個人定義。"},{"en":"If a writer gives a personal definition, readers must decide whether it fits the evidence.","zh":"如果作者給出個人定義，讀者必須判斷它是否符合證據。"},{"en":"The phrase highlights an individual explanation, not a dictionary meaning only.","zh":"這個短語突出個人解釋，而不只是字典意思。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":19},{"front":"draw comparisons with","meaning":"與……作比較","examples":[{"en":"The writer draws comparisons with earlier periods of technological innovation.","zh":"作者與較早科技創新時期作比較。"},{"en":"To draw comparisons with something means to compare it with another example to show similarities or differences.","zh":"draw comparisons with 某事，指把它與另一例子比較，以顯示相似或不同。"},{"en":"A teacher may draw comparisons with past exams to explain a new question type.","zh":"老師可能與過去考試作比較，解釋新題型。"},{"en":"If a writer draws comparisons with history, readers can see patterns more clearly.","zh":"如果作者與歷史作比較，讀者就能更清楚看見模式。"},{"en":"The phrase describes using comparison as an explanation method.","zh":"這個短語描述以比較作為解釋方法。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":19},{"front":"other periods of","meaning":"其他……時期","examples":[{"en":"The passage compares digital change with other periods of innovation.","zh":"文章把數碼轉變與其他創新時期比較。"},{"en":"Other periods of something are different times when similar events or conditions occurred.","zh":"other periods of 某事，是發生過相似事件或情況的不同時期。"},{"en":"Students may compare this recession with other periods of economic difficulty.","zh":"學生可能把這次衰退與其他經濟困難時期比較。"},{"en":"If today’s technology resembles other periods of change, old lessons may still help.","zh":"如果今天的科技類似其他轉變時期，舊經驗仍可能有幫助。"},{"en":"The phrase creates a historical comparison across time.","zh":"這個短語建立跨時間的歷史比較。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":19},{"front":"best summarise","meaning":"最能概括","examples":[{"en":"Students choose the option that best summarises the writer’s views.","zh":"學生選擇最能概括作者看法的選項。"},{"en":"To best summarise something means to express its main idea most accurately and briefly.","zh":"best summarise 某事，指最準確而簡潔地表達其主要意思。"},{"en":"A good title should best summarise the main message of an article.","zh":"好標題應最能概括文章主要訊息。"},{"en":"If an answer includes details but misses the main view, it does not best summarise the text.","zh":"如果答案包含細節但錯過主要看法，它就不能最能概括文本。"},{"en":"The phrase asks for the most accurate overall summary.","zh":"這個短語要求最準確的整體摘要。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":19},{"front":"cease resisting","meaning":"停止抗拒","examples":[{"en":"The option says the public should cease resisting new technology.","zh":"選項說公眾應停止抗拒新科技。"},{"en":"To cease resisting means to stop opposing or fighting against something.","zh":"cease resisting 指停止反對或抵抗某事。"},{"en":"A student may cease resisting feedback after seeing that it improves writing.","zh":"學生看見回饋能改善寫作後，可能停止抗拒意見。"},{"en":"If workers cease resisting a useful system, training can become smoother.","zh":"如果員工停止抗拒有用系統，培訓可以更順利。"},{"en":"The phrase suggests ending opposition.","zh":"這個短語暗示結束反對。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":19},{"front":"the introduction of new technology","meaning":"新科技的引入","examples":[{"en":"The introduction of new technology often causes anxiety.","zh":"新科技的引入常造成焦慮。"},{"en":"The introduction of new technology means the beginning of using a new tool or system.","zh":"the introduction of new technology 指開始使用新工具或系統。"},{"en":"The introduction of online payment changed how small shops handled money.","zh":"網上付款的引入改變了小店處理金錢的方式。"},{"en":"If the introduction of new technology is not explained well, people may fear it.","zh":"如果新科技的引入沒有被清楚解釋，人們可能害怕它。"},{"en":"The phrase focuses on the arrival and early use of technology.","zh":"這個短語重點在科技的到來和早期使用。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":20},{"front":"increase profits","meaning":"增加利潤","examples":[{"en":"Digital technology may increase profits in the entertainment business.","zh":"數碼科技可能增加娛樂業利潤。"},{"en":"To increase profits means to raise the amount of money left after costs are paid.","zh":"increase profits 指提高扣除成本後剩下的金錢。"},{"en":"A restaurant can increase profits by reducing food waste and attracting more customers.","zh":"餐廳可以透過減少食物浪費和吸引更多顧客來增加利潤。"},{"en":"If digital delivery lowers costs, it may increase profits for media companies.","zh":"如果數碼發放降低成本，它可能為媒體公司增加利潤。"},{"en":"The phrase describes a positive financial result.","zh":"這個短語描述正面的財務結果。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":20},{"front":"adapt to technological innovation","meaning":"適應科技創新","examples":[{"en":"Entertainment companies should adapt to technological innovation.","zh":"娛樂公司應適應科技創新。"},{"en":"To adapt to technological innovation means to change methods, skills, or strategy because of new technology.","zh":"adapt to technological innovation 指因新科技而改變方法、技能或策略。"},{"en":"Teachers adapt to technological innovation when they learn to use online classrooms effectively.","zh":"老師學會有效使用網上課室時，就是在適應科技創新。"},{"en":"If companies adapt to technological innovation early, they may avoid being pushed aside.","zh":"如果公司早日適應科技創新，它們可能避免被邊緣化。"},{"en":"The phrase stresses flexible response to new tools and systems.","zh":"這個短語強調對新工具和系統作出靈活回應。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":20},{"front":"only benefits","meaning":"只令……受益","examples":[{"en":"The option claims that technological change only benefits large companies.","zh":"選項聲稱科技轉變只令大型公司受益。"},{"en":"Only benefits means helps only one group or side, without helping others.","zh":"only benefits 指只幫助某一群體或一方，而不幫助其他人。"},{"en":"A school policy should not only benefit top students; weaker students need support too.","zh":"校政不應只令尖子受益；較弱學生也需要支援。"},{"en":"If a new law only benefits big firms, small businesses may complain.","zh":"如果新法律只令大企業受益，小企業可能投訴。"},{"en":"The phrase signals a limited and possibly unfair advantage.","zh":"這個短語表示有限且可能不公平的好處。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":20},{"front":"big entertainment companies","meaning":"大型娛樂公司","examples":[{"en":"Big entertainment companies may become stronger through digital technology.","zh":"大型娛樂公司可能透過數碼科技變得更強。"},{"en":"Big entertainment companies are large firms that produce or distribute major forms of entertainment.","zh":"big entertainment companies 是製作或發放主要娛樂形式的大型企業。"},{"en":"A big entertainment company may own streaming services, music labels, and film studios.","zh":"大型娛樂公司可能擁有串流服務、唱片品牌和電影製片廠。"},{"en":"If big entertainment companies control several channels, independent creators may have fewer choices.","zh":"如果大型娛樂公司控制多個渠道，獨立創作者可能有較少選擇。"},{"en":"The phrase points to powerful firms with broad reach.","zh":"這個短語指覆蓋廣泛的強大企業。"}],"source":"100 - Wheel of Fortune.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 101":[{"front":"robots","meaning":"機械人","examples":[{"en":"Robots can carry out tasks that are dangerous, boring or difficult for humans.","zh":"機械人可以執行對人類來說危險、沉悶或困難的任務。"},{"en":"Robots are machines that can do tasks automatically or with limited human control.","zh":"機械人是能自動或在有限人類控制下完成任務的機器。"},{"en":"Factories use robots to lift heavy parts that would tire human workers quickly.","zh":"工廠使用機械人搬運會很快令工人疲倦的重型零件。"},{"en":"Robots can reduce risk when they work in places with fire, chemicals or radiation.","zh":"當機械人在有火、化學品或輻射的地方工作時，可以降低風險。"},{"en":"A robot does not have to look human; it simply needs to perform useful actions.","zh":"機械人不一定要像人類；它只需要能執行有用動作。"}],"source":"101 - ROBOTS.pdf","sourcePage":1},{"front":"since the dawn of","meaning":"自……開始以來","examples":[{"en":"Since the dawn of human ingenuity, people have devised tools to make work easier.","zh":"自人類巧思開始以來，人們已設計工具使工作更容易。"},{"en":"Since the dawn of something means from the very beginning of that thing.","zh":"since the dawn of something 指從某事物最早開始的時候起。"},{"en":"Since the dawn of farming, people have searched for better ways to grow food.","zh":"自農業開始以來，人們一直尋找更好的種植食物方法。"},{"en":"A phrase like this gives a long historical perspective on a development.","zh":"這類短語為某項發展提供很長的歷史角度。"},{"en":"It is often used when discussing ideas that have existed for a very long time.","zh":"它常用於討論已存在很久的想法。"}],"source":"101 - ROBOTS.pdf","sourcePage":1},{"front":"human ingenuity","meaning":"人類創意；人類巧思","examples":[{"en":"Human ingenuity has led to the invention of increasingly sophisticated tools.","zh":"人類創意促成了越來越精密工具的發明。"},{"en":"Human ingenuity is the ability of people to think creatively and solve practical problems.","zh":"human ingenuity 指人類創意思考和解決實際問題的能力。"},{"en":"A simple umbrella shows human ingenuity because it solves the problem of rain with a light tool.","zh":"簡單雨傘展現人類巧思，因為它用輕便工具解決下雨問題。"},{"en":"Human ingenuity can turn difficult work into safer and faster work.","zh":"人類創意可以把困難工作變得更安全和更快速。"},{"en":"This phrase praises human creativity, especially when people invent useful solutions.","zh":"這個短語讚揚人類創造力，尤其是人們發明有用解決方法時。"}],"source":"101 - ROBOTS.pdf","sourcePage":1},{"front":"devise tools","meaning":"設計工具；發明工具","examples":[{"en":"People have devised tools to cope with unpleasant work.","zh":"人們設計工具來應付令人不快的工作。"},{"en":"To devise tools means to design or invent tools for a particular purpose.","zh":"devise tools 指為特定目的設計或發明工具。"},{"en":"Students may devise tools, such as checklists, to remember homework deadlines.","zh":"學生可能設計工具，例如清單，來記住功課限期。"},{"en":"When a job is slow or risky, people often devise tools to make it easier.","zh":"當工作緩慢或有風險時，人們常會發明工具使它更容易。"},{"en":"This phrase focuses on creating a practical solution, not just using an existing one.","zh":"這個短語著重創造實際解決方法，而不只是使用現有工具。"}],"source":"101 - ROBOTS.pdf","sourcePage":1},{"front":"ever more cunning tools","meaning":"越來越精巧的工具","examples":[{"en":"Humans have devised ever more cunning tools to solve practical problems.","zh":"人類設計了越來越精巧的工具來解決實際問題。"},{"en":"Ever more cunning tools are increasingly clever tools designed to deal with difficult tasks.","zh":"ever more cunning tools 指越來越聰明、用來處理困難任務的工具。"},{"en":"A phone app that reminds patients to take medicine is an ever more cunning tool for healthcare.","zh":"提醒病人服藥的手機應用程式，是醫療上的一種越來越精巧的工具。"},{"en":"As problems become more complex, people create more clever tools to handle them.","zh":"隨着問題變得更複雜，人們會創造更精巧的工具來處理它們。"},{"en":"This phrase suggests tools that are not only useful but intelligently designed.","zh":"這個短語表示工具不只是有用，而且設計得聰明。"}],"source":"101 - ROBOTS.pdf","sourcePage":1},{"front":"cope with","meaning":"應付；處理","examples":[{"en":"People use tools to cope with work that is dangerous or onerous.","zh":"人們使用工具來應付危險或繁重的工作。"},{"en":"To cope with something means to manage or deal with a difficult situation.","zh":"cope with something 指管理或處理困難情況。"},{"en":"A student may use a timetable to cope with heavy homework.","zh":"學生可能使用時間表來應付大量功課。"},{"en":"Good tools help workers cope with tasks that would otherwise be too tiring.","zh":"好工具幫助工人處理原本太令人疲倦的任務。"},{"en":"This phrase suggests effort under pressure, not an easy situation.","zh":"這個短語表示在壓力下努力應對，而不是輕鬆情況。"}],"source":"101 - ROBOTS.pdf","sourcePage":1},{"front":"onerous work","meaning":"繁重的工作","examples":[{"en":"Robots can help people avoid onerous work.","zh":"機械人可以幫助人們避免繁重的工作。"},{"en":"Onerous work is work that feels heavy, difficult, tiring or burdensome.","zh":"onerous work 指沉重、困難、令人疲倦或負擔很大的工作。"},{"en":"Carrying boxes up five floors all day would be onerous work for most people.","zh":"整天把箱子搬上五層樓，對大多數人而言都是繁重的工作。"},{"en":"If machines take over onerous work, workers may have more energy for skilled tasks.","zh":"如果機器接手繁重工作，工人可能有更多精力處理技術性任務。"},{"en":"This phrase is more formal than “hard work” and often suggests a heavy burden.","zh":"這個短語比 hard work 較正式，常表示沉重負擔。"}],"source":"101 - ROBOTS.pdf","sourcePage":1},{"front":"just plain nasty","meaning":"實在令人厭惡","examples":[{"en":"Some jobs are dangerous, boring, onerous or just plain nasty.","zh":"有些工作危險、沉悶、繁重，或者實在令人厭惡。"},{"en":"Just plain nasty means simply very unpleasant, without needing a more polite explanation.","zh":"just plain nasty 指某事就是非常令人不快，不需要更客氣的解釋。"},{"en":"Cleaning a blocked drain in hot weather can be just plain nasty.","zh":"在炎熱天氣清理堵塞渠管可以實在令人厭惡。"},{"en":"People create tools because some jobs are not only hard but also just plain nasty.","zh":"人們創造工具，因為有些工作不只困難，還實在令人厭惡。"},{"en":"This phrase is informal and strongly expresses dislike.","zh":"這個短語較口語，強烈表達厭惡。"}],"source":"101 - ROBOTS.pdf","sourcePage":1},{"front":"culminate in","meaning":"最終發展成","examples":[{"en":"That human compulsion has culminated in robotics.","zh":"那種人類衝動最終發展成機械人學。"},{"en":"To culminate in something means to develop over time and finally reach that result.","zh":"culminate in something 指隨時間發展，最後達到某結果。"},{"en":"Years of practice may culminate in a student’s first public performance.","zh":"多年練習可能最終發展成學生第一次公開表演。"},{"en":"Small inventions can accumulate and culminate in a major technological field.","zh":"小發明可以累積，最終發展成一個重要科技領域。"},{"en":"This phrase shows the final stage of a long process.","zh":"這個短語顯示漫長過程的最後階段。"}],"source":"101 - ROBOTS.pdf","sourcePage":1},{"front":"robotics","meaning":"機械人學","examples":[{"en":"Robotics is the science of giving machines human-like capabilities.","zh":"機械人學是賦予機器類似人類能力的科學。"},{"en":"Robotics is the field that designs, builds and studies robots.","zh":"robotics 指設計、建造和研究機械人的領域。"},{"en":"A university robotics club may build a small robot that follows a line on the floor.","zh":"大學機械人學會可能製作一部沿地上線條行走的小型機械人。"},{"en":"Robotics can make dangerous work safer by sending machines instead of people.","zh":"機械人學可以派機器代替人進入危險工作，使工作更安全。"},{"en":"This word refers to the study and creation of robots, not just the robots themselves.","zh":"這個詞指研究和創造機械人的學科，而不只是機械人本身。"}],"source":"101 - ROBOTS.pdf","sourcePage":1},{"front":"the science of","meaning":"……的科學","examples":[{"en":"Robotics is the science of conferring human capabilities on machines.","zh":"機械人學是把人類能力賦予機器的科學。"},{"en":"The science of something is the organised study of how it works.","zh":"the science of something 指有系統地研究某事如何運作的學科。"},{"en":"Nutrition is the science of how food affects the body.","zh":"營養學是研究食物如何影響身體的科學。"},{"en":"A field becomes a science when people test ideas carefully and build evidence.","zh":"當人們仔細測試想法並建立證據，一個領域就成為科學。"},{"en":"This phrase introduces a subject by explaining what it studies.","zh":"這個短語透過解釋研究內容來介紹一門學科。"}],"source":"101 - ROBOTS.pdf","sourcePage":2},{"front":"confer capabilities on","meaning":"賦予……能力","examples":[{"en":"Robotics confers various human capabilities on machines.","zh":"機械人學把各種人類能力賦予機器。"},{"en":"To confer capabilities on something means to give it abilities it did not naturally have.","zh":"confer capabilities on something 指給予某物本來沒有的能力。"},{"en":"A screen reader can confer reading support on a phone for people with poor eyesight.","zh":"螢幕閱讀器可以為視力較弱的人，把閱讀支援能力賦予手機。"},{"en":"Engineers confer new capabilities on machines by adding sensors, software and motors.","zh":"工程師透過加入感應器、軟件和摩打，把新能力賦予機器。"},{"en":"This phrase is formal and means “give abilities to”.","zh":"這個短語較正式，意思是「給予能力」。"}],"source":"101 - ROBOTS.pdf","sourcePage":2},{"front":"human capabilities","meaning":"人類能力","examples":[{"en":"Robotics aims to confer human capabilities on machines.","zh":"機械人學旨在把人類能力賦予機器。"},{"en":"Human capabilities are abilities that people have, such as seeing, moving, learning or making decisions.","zh":"human capabilities 指人類擁有的能力，例如看見、移動、學習或作決定。"},{"en":"Speech recognition gives computers one small part of human communication capability.","zh":"語音識別給予電腦一小部分人類溝通能力。"},{"en":"Machines need many different capabilities before they can work safely in messy real-life situations.","zh":"機器需要許多不同能力，才能在混亂的現實情況中安全工作。"},{"en":"This phrase refers to what humans can do, not simply what humans know.","zh":"這個短語指人類能做甚麼，而不只是人類知道甚麼。"}],"source":"101 - ROBOTS.pdf","sourcePage":2},{"front":"increasingly populated by","meaning":"越來越充滿……","examples":[{"en":"The modern world is increasingly populated by quasi-intelligent machines.","zh":"現代世界越來越充滿半智能機器。"},{"en":"Increasingly populated by something means becoming more and more filled with it.","zh":"increasingly populated by something 指越來越被某物充滿。"},{"en":"Modern homes are increasingly populated by smart speakers, sensors and connected appliances.","zh":"現代家庭越來越充滿智能喇叭、感應器和聯網電器。"},{"en":"As technology becomes cheaper, public spaces become increasingly populated by automated machines.","zh":"隨着科技變得更便宜，公共空間越來越充滿自動化機器。"},{"en":"This phrase shows a gradual rise in the number or presence of something.","zh":"這個短語顯示某物的數量或存在感逐漸增加。"}],"source":"101 - ROBOTS.pdf","sourcePage":2},{"front":"quasi-intelligent gizmos","meaning":"半智能小裝置","examples":[{"en":"The modern world is full of quasi-intelligent gizmos.","zh":"現代世界充滿半智能小裝置。"},{"en":"Quasi-intelligent gizmos are small devices that seem partly smart because they can respond or act automatically.","zh":"quasi-intelligent gizmos 指看似有部分智能、能自動回應或行動的小裝置。"},{"en":"A smart thermostat is a quasi-intelligent gizmo because it adjusts temperature by itself.","zh":"智能恆溫器是一種半智能小裝置，因為它會自行調節溫度。"},{"en":"These devices can make daily life easier, but they are not truly intelligent like humans.","zh":"這些裝置可以令日常生活更方便，但它們不像人類那樣真正智能。"},{"en":"This phrase is informal and slightly playful.","zh":"這個短語較口語，帶有一點玩味。"}],"source":"101 - ROBOTS.pdf","sourcePage":2},{"front":"whose presence we barely notice","meaning":"我們幾乎察覺不到其存在","examples":[{"en":"Many robotic devices have a presence we barely notice.","zh":"許多機械裝置的存在，我們幾乎察覺不到。"},{"en":"Whose presence we barely notice means that something exists around us but we almost do not pay attention to it.","zh":"whose presence we barely notice 指某物存在於我們身邊，但我們幾乎不留意。"},{"en":"Automatic doors are so common that their presence is barely noticed by shoppers.","zh":"自動門太常見，以致購物者幾乎察覺不到其存在。"},{"en":"When technology becomes normal, people may stop noticing how often they use it.","zh":"當科技變得日常，人們可能不再注意自己多常使用它。"},{"en":"This phrase shows quiet familiarity rather than dramatic visibility.","zh":"這個短語顯示安靜的熟悉感，而不是戲劇化的可見性。"}],"source":"101 - ROBOTS.pdf","sourcePage":2},{"front":"creeping ubiquity","meaning":"逐漸無處不在","examples":[{"en":"The creeping ubiquity of robots has changed daily life.","zh":"機械人逐漸無處不在，改變了日常生活。"},{"en":"Creeping ubiquity means something gradually becomes present almost everywhere.","zh":"creeping ubiquity 指某物逐漸變得到處都有。"},{"en":"The creeping ubiquity of smartphones changed how people read maps, pay and communicate.","zh":"智能手機逐漸無處不在，改變了人們看地圖、付款和溝通的方式。"},{"en":"Because the change is slow, people may not notice it until it is everywhere.","zh":"因為改變緩慢，人們可能到它到處都有時才注意到。"},{"en":"This phrase suggests a quiet but powerful spread.","zh":"這個短語表示安靜但強大的擴散。"}],"source":"101 - ROBOTS.pdf","sourcePage":2},{"front":"remove much human drudgery","meaning":"減少大量人類苦差","examples":[{"en":"Robots have removed much human drudgery.","zh":"機械人已減少大量人類苦差。"},{"en":"To remove much human drudgery means to take away many dull, tiring or repetitive jobs from people.","zh":"remove much human drudgery 指為人類消除許多沉悶、疲累或重複工作。"},{"en":"Washing machines removed much human drudgery from household laundry.","zh":"洗衣機從家庭洗衣中減少了大量人類苦差。"},{"en":"When machines handle repetitive tasks, people can spend more time on skilled or creative work.","zh":"當機器處理重複任務，人們就能把更多時間花在技術或創意工作上。"},{"en":"This phrase presents technology as reducing unpleasant labour.","zh":"這個短語把科技呈現為減少令人不快的勞動。"}],"source":"101 - ROBOTS.pdf","sourcePage":2},{"front":"human drudgery","meaning":"人類苦差；沉悶辛勞的工作","examples":[{"en":"Automated machines can reduce human drudgery.","zh":"自動化機器可以減少人類苦差。"},{"en":"Human drudgery is boring, repetitive and tiring work done by people.","zh":"human drudgery 指人類所做的沉悶、重複和疲累工作。"},{"en":"Copying hundreds of numbers by hand is human drudgery that software can reduce.","zh":"手抄數百個數字是軟件可以減少的人類苦差。"},{"en":"Reducing human drudgery can improve morale because workers feel less trapped in dull tasks.","zh":"減少人類苦差可以改善士氣，因為工人較少被困在沉悶任務中。"},{"en":"This phrase is often used when technology takes over unpleasant routine work.","zh":"這個短語常用於科技接手令人不快的例行工作時。"}],"source":"101 - ROBOTS.pdf","sourcePage":2},{"front":"hum to the rhythm of","meaning":"隨着……的節奏運作","examples":[{"en":"Factories hum to the rhythm of robot assembly arms.","zh":"工廠隨着機械人裝配臂的節奏運作。"},{"en":"To hum to the rhythm of something means to operate steadily around its repeated movement or sound.","zh":"hum to the rhythm of something 指圍繞某物重複的動作或聲音穩定運作。"},{"en":"A busy kitchen may hum to the rhythm of timers, orders and chopping knives.","zh":"繁忙廚房可能隨着計時器、訂單和切菜刀的節奏運作。"},{"en":"When machines control the pace, the whole workplace can follow their rhythm.","zh":"當機器控制速度，整個工作場所都可能跟隨它們的節奏。"},{"en":"This phrase gives a place the feeling of smooth repeated activity.","zh":"這個短語令一個地方帶有順暢重複活動的感覺。"}],"source":"101 - ROBOTS.pdf","sourcePage":2},{"front":"robot assembly arms","meaning":"機械人裝配臂","examples":[{"en":"Robot assembly arms are common in modern factories.","zh":"機械人裝配臂在現代工廠很常見。"},{"en":"Robot assembly arms are mechanical arms used to build, move or fit parts together.","zh":"robot assembly arms 指用來建造、移動或組合零件的機械手臂。"},{"en":"A car factory may use robot assembly arms to weld doors onto car bodies.","zh":"汽車工廠可能使用機械人裝配臂把車門焊接到車身上。"},{"en":"These arms can improve speed and consistency when the same action must be repeated thousands of times.","zh":"當同一動作必須重複數千次時，這些手臂可以提升速度和一致性。"},{"en":"This phrase refers to industrial robots shaped like arms.","zh":"這個短語指形狀像手臂的工業機械人。"}],"source":"101 - ROBOTS.pdf","sourcePage":3},{"front":"automated teller terminals","meaning":"自動櫃員機終端機","examples":[{"en":"Banking is often done at automated teller terminals.","zh":"銀行服務常在自動櫃員機終端機完成。"},{"en":"Automated teller terminals are machines that allow people to withdraw money or use basic banking services.","zh":"automated teller terminals 指讓人提款或使用基本銀行服務的機器。"},{"en":"A customer may use an automated teller terminal after the bank branch has closed.","zh":"銀行分行關門後，顧客可能使用自動櫃員機終端機。"},{"en":"These machines reduce waiting time because simple transactions do not need a human cashier.","zh":"這些機器減少等候時間，因為簡單交易不需要真人櫃員。"},{"en":"This phrase is a formal name for ATM machines.","zh":"這個短語是 ATM 機的正式名稱。"}],"source":"101 - ROBOTS.pdf","sourcePage":3},{"front":"rote politeness","meaning":"機械式禮貌","examples":[{"en":"Automated teller terminals thank customers with rote politeness.","zh":"自動櫃員機終端機以機械式禮貌感謝顧客。"},{"en":"Rote politeness is polite language repeated automatically without real feeling.","zh":"rote politeness 指自動重複、沒有真實情感的禮貌語言。"},{"en":"A recorded phone message may say “thank you” with rote politeness after every option.","zh":"錄音電話訊息可能在每個選項後以機械式禮貌說「謝謝」。"},{"en":"Machines can sound polite, but their politeness is programmed rather than sincere.","zh":"機器可以聽起來有禮貌，但其禮貌是被編程的，而不是真誠的。"},{"en":"This phrase gently criticises automatic politeness that feels mechanical.","zh":"這個短語溫和批評感覺機械化的自動禮貌。"}],"source":"101 - ROBOTS.pdf","sourcePage":3},{"front":"for the transaction","meaning":"就該交易","examples":[{"en":"The machine thanks the customer for the transaction.","zh":"機器就該交易感謝顧客。"},{"en":"For the transaction means because of the banking action, purchase or exchange just completed.","zh":"for the transaction 指因剛完成的銀行操作、購買或交換而感謝。"},{"en":"A shop receipt may thank a customer for the transaction after payment is made.","zh":"顧客付款後，商店收據可能就該交易向顧客致謝。"},{"en":"The phrase links thanks to a specific completed business action.","zh":"這個短語把感謝與特定已完成商業行動連繫起來。"},{"en":"It is more formal than simply saying “thanks for buying”.","zh":"它比簡單說 thanks for buying 更正式。"}],"source":"101 - ROBOTS.pdf","sourcePage":3},{"front":"subway trains","meaning":"地鐵列車","examples":[{"en":"Some subway trains are controlled by automated systems.","zh":"有些地鐵列車由自動系統控制。"},{"en":"Subway trains are trains that usually run underground in a city transport system.","zh":"subway trains 指通常在城市交通系統地下行駛的列車。"},{"en":"Many commuters take subway trains because they avoid road traffic.","zh":"許多通勤者乘搭地鐵列車，因為它們避開路面交通。"},{"en":"Automated subway trains can run regularly when the system controls speed and stopping.","zh":"當系統控制速度和停站，自動化地鐵列車可以定時行駛。"},{"en":"This phrase refers to urban rail transport, not long-distance trains.","zh":"這個短語指城市鐵路交通，而不是長途火車。"}],"source":"101 - ROBOTS.pdf","sourcePage":3},{"front":"be controlled by","meaning":"由……控制","examples":[{"en":"Subway trains may be controlled by tireless robo-drivers.","zh":"地鐵列車可能由不知疲倦的機械駕駛員控制。"},{"en":"To be controlled by something means to be directed or operated by it.","zh":"be controlled by something 指由某物指揮或操作。"},{"en":"A lift is controlled by buttons and a computer system.","zh":"升降機由按鈕和電腦系統控制。"},{"en":"When transport is controlled by software, human drivers may not need to make every decision.","zh":"當交通工具由軟件控制，真人司機未必需要作出每個決定。"},{"en":"This phrase identifies who or what has power over the action.","zh":"這個短語指出誰或甚麼掌握行動控制權。"}],"source":"101 - ROBOTS.pdf","sourcePage":3},{"front":"tireless robo-drivers","meaning":"不知疲倦的機械駕駛員","examples":[{"en":"Subway trains can be controlled by tireless robo-drivers.","zh":"地鐵列車可以由不知疲倦的機械駕駛員控制。"},{"en":"Tireless robo-drivers are automated driving systems that do not get tired like humans.","zh":"tireless robo-drivers 指不會像人類般疲倦的自動駕駛系統。"},{"en":"An airport train may use tireless robo-drivers to run all day with regular timing.","zh":"機場列車可能使用不知疲倦的機械駕駛員，全天定時行駛。"},{"en":"Removing fatigue from driving can reduce some human-error risks.","zh":"從駕駛中消除疲勞，可以減少某些人為錯誤風險。"},{"en":"This phrase presents automated drivers as constant and hardworking.","zh":"這個短語把自動駕駛員呈現為持續而勤勞。"}],"source":"101 - ROBOTS.pdf","sourcePage":3},{"front":"mine shafts","meaning":"礦井；礦道","examples":[{"en":"Mine shafts may be dug by automated machines.","zh":"礦井可能由自動化機器挖掘。"},{"en":"Mine shafts are deep passages or tunnels made to reach minerals underground.","zh":"mine shafts 指為到達地下礦物而開挖的深通道或隧道。"},{"en":"Miners use mine shafts to move people, tools and materials below the surface.","zh":"礦工使用礦井把人員、工具和材料運到地面以下。"},{"en":"Digging mine shafts can be dangerous because of collapse, gas and dust.","zh":"挖掘礦井可能很危險，因為有倒塌、氣體和粉塵風險。"},{"en":"This phrase refers to underground mining passages.","zh":"這個短語指地下採礦通道。"}],"source":"101 - ROBOTS.pdf","sourcePage":3},{"front":"automated moles","meaning":"自動化鑽挖機器","examples":[{"en":"Mine shafts can be dug by automated moles.","zh":"礦井可以由自動化鑽挖機器挖掘。"},{"en":"Automated moles are machines that dig underground like moles, usually without direct human digging.","zh":"automated moles 指像鼴鼠般在地下挖掘、通常不需人類直接挖土的機器。"},{"en":"A city may use automated moles to dig tunnels for cables or trains.","zh":"城市可能使用自動化鑽挖機器為電纜或列車挖隧道。"},{"en":"These machines keep workers farther from unstable soil and dangerous dust.","zh":"這些機器使工人遠離不穩定泥土和危險粉塵。"},{"en":"This phrase compares digging machines with animals that burrow underground.","zh":"這個短語把挖掘機器比作在地下打洞的動物。"}],"source":"101 - ROBOTS.pdf","sourcePage":3},{"front":"nuclear accidents","meaning":"核事故","examples":[{"en":"Robots can help clean up nuclear accidents.","zh":"機械人可以幫助清理核事故。"},{"en":"Nuclear accidents are dangerous events involving nuclear power, radioactive material or radiation leakage.","zh":"nuclear accidents 指涉及核能、放射性物質或輻射洩漏的危險事件。"},{"en":"After a nuclear accident, humans may not be able to enter some areas safely.","zh":"核事故後，人類可能無法安全進入某些地區。"},{"en":"Robots are useful because radiation can harm people but machines can be built to resist it.","zh":"機械人有用，因為輻射會傷害人，但機器可被設計成能抵抗輻射。"},{"en":"This phrase describes a serious emergency involving nuclear danger.","zh":"這個短語描述涉及核危險的嚴重緊急事件。"}],"source":"101 - ROBOTS.pdf","sourcePage":3},{"front":"clean up","meaning":"清理","examples":[{"en":"Robots can clean up dangerous accident sites.","zh":"機械人可以清理危險事故現場。"},{"en":"To clean up means to remove dirt, waste, danger or damage from a place.","zh":"clean up 指移除地方上的污垢、廢物、危險或損壞。"},{"en":"Students clean up the classroom after an art lesson by collecting paper and washing brushes.","zh":"美術課後，學生透過收集紙張和清洗畫筆來清理課室。"},{"en":"After a chemical spill, trained workers may clean up the area to make it safe again.","zh":"化學品洩漏後，受訓工人可能清理該區，使其重新安全。"},{"en":"This phrase often means restoring order or safety after a mess or accident.","zh":"這個短語常指在混亂或事故後恢復秩序或安全。"}],"source":"101 - ROBOTS.pdf","sourcePage":4},{"front":"robotic muckers","meaning":"機械清理工","examples":[{"en":"Robotic muckers can work in dangerous environments.","zh":"機械清理工可以在危險環境中工作。"},{"en":"Robotic muckers are machines used to clear dirt, waste or dangerous material.","zh":"robotic muckers 指用來清除污垢、廢物或危險物質的機器。"},{"en":"A robotic mucker could remove rubble where the air is unsafe for human workers.","zh":"機械清理工可以在人類工人不能安全呼吸的地方移除瓦礫。"},{"en":"Using robotic muckers reduces the need for people to enter polluted or unstable sites.","zh":"使用機械清理工可減少人們進入污染或不穩定現場的需要。"},{"en":"This phrase presents robots as mechanical cleaners for heavy or dirty work.","zh":"這個短語把機械人呈現為處理重型或骯髒工作的機械清潔者。"}],"source":"101 - ROBOTS.pdf","sourcePage":4},{"front":"fit to withstand","meaning":"適合承受……","examples":[{"en":"Some robots are fit to withstand radiation.","zh":"有些機械人適合承受輻射。"},{"en":"Fit to withstand something means strong or suitable enough to survive it.","zh":"fit to withstand something 指足夠強或足夠合適，能承受某事。"},{"en":"A waterproof watch is fit to withstand rain and shallow swimming.","zh":"防水手錶適合承受雨水和淺水游泳。"},{"en":"Robots used in disasters must be fit to withstand heat, dust and unstable ground.","zh":"用於災難中的機械人必須適合承受高溫、粉塵和不穩地面。"},{"en":"This phrase focuses on suitability under difficult conditions.","zh":"這個短語著重在困難條件下的適合程度。"}],"source":"101 - ROBOTS.pdf","sourcePage":4},{"front":"withstand radiation","meaning":"承受輻射","examples":[{"en":"Robots can withstand radiation in nuclear accidents.","zh":"機械人可以在核事故中承受輻射。"},{"en":"To withstand radiation means to survive or keep working despite exposure to harmful radioactive energy.","zh":"withstand radiation 指即使暴露於有害放射性能量下仍能存活或運作。"},{"en":"Special cameras in nuclear plants must withstand radiation to send images safely.","zh":"核電廠中的特殊攝影機必須承受輻射，才能安全傳送影像。"},{"en":"If a machine can withstand radiation, it can work where humans cannot safely stay.","zh":"如果機器能承受輻射，它就能在人類不能安全停留的地方工作。"},{"en":"This phrase is used for equipment built for extreme environments.","zh":"這個短語用於為極端環境而設的設備。"}],"source":"101 - ROBOTS.pdf","sourcePage":4},{"front":"the scope of uses","meaning":"用途範圍","examples":[{"en":"Karel Capek envisioned a wide scope of uses for robots.","zh":"Karel Capek 設想了機械人的廣泛用途範圍。"},{"en":"The scope of uses means the range of different purposes something can serve.","zh":"scope of uses 指某事物可以服務的不同目的範圍。"},{"en":"A smartphone has a wide scope of uses, including calls, maps, photos and payments.","zh":"智能手機有廣泛用途範圍，包括通話、地圖、拍照和付款。"},{"en":"When a technology has a wide scope of uses, it can affect many parts of life.","zh":"當一項科技有廣泛用途範圍，它可以影響生活許多部分。"},{"en":"This phrase focuses on range, not just one example.","zh":"這個短語著重範圍，而不只是單一例子。"}],"source":"101 - ROBOTS.pdf","sourcePage":4},{"front":"envision","meaning":"設想；想像","examples":[{"en":"Karel Capek envisioned many possible uses for robots.","zh":"Karel Capek 設想了機械人的許多可能用途。"},{"en":"To envision something means to imagine it clearly as a future possibility.","zh":"envision something 指清楚想像某事成為未來可能性。"},{"en":"A school principal may envision a library where students can read, meet and learn online.","zh":"校長可能設想一個讓學生閱讀、見面和網上學習的圖書館。"},{"en":"Inventors often envision uses for technology before the technology becomes common.","zh":"發明者常在科技普及前設想其用途。"},{"en":"This verb suggests imaginative planning, not just casual guessing.","zh":"這個動詞表示有想像力的規劃，而不只是隨便猜測。"}],"source":"101 - ROBOTS.pdf","sourcePage":4},{"front":"coin the term","meaning":"創造某個詞語","examples":[{"en":"Karel Capek coined the term “robot” in 1920.","zh":"Karel Capek 在 1920 年創造了 “robot” 這個詞語。"},{"en":"To coin the term means to create a new word or phrase.","zh":"coin the term 指創造一個新詞或新短語。"},{"en":"A journalist may coin a term to describe a new social habit.","zh":"記者可能創造某個詞語來描述新的社會習慣。"},{"en":"Once a useful term is coined, other people may begin to use it widely.","zh":"一旦有用詞語被創造，其他人可能開始廣泛使用它。"},{"en":"This phrase is often used when explaining the origin of a word.","zh":"這個短語常用於解釋詞語來源。"}],"source":"101 - ROBOTS.pdf","sourcePage":4},{"front":"forced labour","meaning":"強迫勞動","examples":[{"en":"The Czech word “robota” means forced labour.","zh":"捷克語 “robota” 的意思是強迫勞動。"},{"en":"Forced labour is work that people are made to do against their will.","zh":"forced labour 指人們被迫違背意願去做的工作。"},{"en":"A worker trapped by threats and unpaid wages may be experiencing forced labour.","zh":"被威脅和欠薪困住的工人可能正在經歷強迫勞動。"},{"en":"Laws against forced labour protect people from being treated like tools.","zh":"反對強迫勞動的法律保護人們免被當作工具對待。"},{"en":"This phrase is serious and refers to exploitation, not ordinary hard work.","zh":"這個短語嚴肅地指剝削，而不是普通辛苦工作。"}],"source":"101 - ROBOTS.pdf","sourcePage":4},{"front":"as progress accelerates","meaning":"隨着進步加快","examples":[{"en":"As progress accelerates, experimental technology becomes practical more quickly.","zh":"隨着進步加快，實驗性技術更快變得實用。"},{"en":"As progress accelerates means as development becomes faster.","zh":"as progress accelerates 指隨着發展變得更快。"},{"en":"As medical progress accelerates, treatments that once seemed impossible may become normal.","zh":"隨着醫學進步加快，曾經看似不可能的治療可能變得正常。"},{"en":"Faster progress can shorten the time between invention and real-world use.","zh":"更快進步可以縮短發明與現實應用之間的時間。"},{"en":"This phrase introduces what happens when improvement speeds up.","zh":"這個短語引入改善加速時會發生的事。"}],"source":"101 - ROBOTS.pdf","sourcePage":4},{"front":"the experimental becomes the exploitable","meaning":"實驗性的東西變成可應用的東西","examples":[{"en":"In robotics, the experimental becomes the exploitable at a rapid pace.","zh":"在機械人學中，實驗性的東西正以快速步伐變成可應用的東西。"},{"en":"The experimental becomes the exploitable means ideas tested in labs become useful for real work.","zh":"the experimental becomes the exploitable 指在實驗室測試的想法變成可用於現實工作的東西。"},{"en":"A school experiment with online lessons became exploitable when it turned into a regular course system.","zh":"學校網上課堂實驗在變成常規課程系統時，就由實驗性變成可應用。"},{"en":"When technology matures, companies can turn risky trials into practical products.","zh":"當科技成熟，公司可以把有風險試驗轉化為實用產品。"},{"en":"This phrase contrasts early testing with later practical use.","zh":"這個短語把早期測試與後來實際使用作對比。"}],"source":"101 - ROBOTS.pdf","sourcePage":4},{"front":"at a record pace","meaning":"以創紀錄的速度","examples":[{"en":"Robotic progress is advancing at a record pace.","zh":"機械人進步正以創紀錄的速度推進。"},{"en":"At a record pace means faster than ever before or faster than previously recorded.","zh":"at a record pace 指比以往任何時候都快，或比之前記錄更快。"},{"en":"The school finished its renovation at a record pace after extra workers were hired.","zh":"學校聘請額外工人後，以創紀錄的速度完成翻新。"},{"en":"Rapid progress can create excitement, but it can also make rules and training struggle to catch up.","zh":"快速進步可以令人興奮，但也可能令規則和培訓追不上。"},{"en":"This phrase emphasises unusual speed.","zh":"這個短語強調不尋常的速度。"}],"source":"101 - ROBOTS.pdf","sourcePage":5},{"front":"other innovations","meaning":"其他創新","examples":[{"en":"Other innovations promise to extend human abilities.","zh":"其他創新有望擴展人類能力。"},{"en":"Other innovations are additional new ideas, tools or methods that improve how things work.","zh":"other innovations 指其他改善事物運作的新想法、工具或方法。"},{"en":"In a school, other innovations may include online homework systems and digital libraries.","zh":"在學校中，其他創新可能包括網上功課系統和數碼圖書館。"},{"en":"Innovations can solve old problems by giving people new ways to act.","zh":"創新可以透過給人新行動方式來解決舊問題。"},{"en":"This phrase adds more examples beyond the main technology being discussed.","zh":"這個短語加入正在討論的主要科技以外的更多例子。"}],"source":"101 - ROBOTS.pdf","sourcePage":5},{"front":"extend the abilities of","meaning":"擴展……的能力","examples":[{"en":"Robotic systems can extend the abilities of human operators.","zh":"機械人系統可以擴展人類操作員的能力。"},{"en":"To extend the abilities of someone means to help them do more than they could do alone.","zh":"extend the abilities of someone 指幫助某人做到單靠自己做不到的事。"},{"en":"Glasses extend the abilities of people who cannot see distant signs clearly.","zh":"眼鏡擴展看不清遠處標誌的人的能力。"},{"en":"Tools extend human abilities when they add strength, accuracy, speed or safety.","zh":"工具透過增加力量、準確度、速度或安全性來擴展人類能力。"},{"en":"This phrase shows technology as support rather than replacement.","zh":"這個短語把科技呈現為支援，而不是取代。"}],"source":"101 - ROBOTS.pdf","sourcePage":5},{"front":"human operators","meaning":"人類操作員","examples":[{"en":"Robots can assist human operators in dangerous or precise tasks.","zh":"機械人可以協助人類操作員完成危險或精準任務。"},{"en":"Human operators are people who control, guide or monitor machines.","zh":"human operators 指控制、引導或監察機器的人。"},{"en":"A crane needs a human operator to move heavy materials safely.","zh":"起重機需要人類操作員安全移動重物。"},{"en":"When machines are powerful, human operators must understand both the controls and the risks.","zh":"當機器力量強大，人類操作員必須理解控制方式和風險。"},{"en":"This phrase contrasts people controlling systems with the machines themselves.","zh":"這個短語把控制系統的人與機器本身作對比。"}],"source":"101 - ROBOTS.pdf","sourcePage":5},{"front":"thanks to","meaning":"由於；多虧","examples":[{"en":"Thanks to miniaturisation, robot systems can perform delicate surgery.","zh":"由於微型化，機械人系統可以進行精細手術。"},{"en":"Thanks to something means because of it, usually with a positive result.","zh":"thanks to something 指因為某事，通常帶有正面結果。"},{"en":"Thanks to online maps, visitors can find a clinic more easily.","zh":"多虧網上地圖，訪客可以更容易找到診所。"},{"en":"New tools become possible thanks to earlier scientific and engineering progress.","zh":"新工具之所以成為可能，是由於較早的科學和工程進步。"},{"en":"This phrase gives credit to the cause of a good outcome.","zh":"這個短語把好結果歸功於其原因。"}],"source":"101 - ROBOTS.pdf","sourcePage":5},{"front":"incessant miniaturisation","meaning":"持續微型化","examples":[{"en":"Incessant miniaturisation has made smaller robotic systems possible.","zh":"持續微型化使更小型機械人系統成為可能。"},{"en":"Incessant miniaturisation means the continuous process of making devices smaller and smaller.","zh":"incessant miniaturisation 指把裝置不斷做得越來越小的持續過程。"},{"en":"Phones became powerful partly because of incessant miniaturisation in electronics.","zh":"手機變得強大，部分原因是電子學中的持續微型化。"},{"en":"Smaller components allow tools to enter tighter spaces and perform finer tasks.","zh":"較小零件讓工具進入更狹窄空間並執行更精細任務。"},{"en":"This phrase suggests ongoing reduction in size, not a one-time change.","zh":"這個短語表示持續縮小，而不是一次性改變。"}],"source":"101 - ROBOTS.pdf","sourcePage":5},{"front":"electronics and micromechanics","meaning":"電子學和微機械學","examples":[{"en":"Electronics and micromechanics have advanced rapidly.","zh":"電子學和微機械學已迅速進步。"},{"en":"Electronics and micromechanics are fields involving electronic circuits and very small mechanical parts.","zh":"electronics and micromechanics 指涉及電子電路和極小機械部件的領域。"},{"en":"A modern hearing aid depends on electronics and micromechanics to process sound in a tiny device.","zh":"現代助聽器依靠電子學和微機械學，在細小裝置中處理聲音。"},{"en":"Progress in these fields can make medical tools smaller and more accurate.","zh":"這些領域的進步可以令醫療工具更小和更準確。"},{"en":"This phrase links tiny machines with electronic control.","zh":"這個短語把微小機器與電子控制連繫起來。"}],"source":"101 - ROBOTS.pdf","sourcePage":5},{"front":"robot systems","meaning":"機械人系統","examples":[{"en":"Robot systems can perform some kinds of surgery.","zh":"機械人系統可以進行某些種類的手術。"},{"en":"Robot systems are groups of robotic parts, sensors, software and controls working together.","zh":"robot systems 指由機械部件、感應器、軟件和控制裝置共同運作的系統。"},{"en":"A hospital robot system may include a surgical arm, cameras and a doctor’s control console.","zh":"醫院機械人系統可能包括手術臂、攝影機和醫生控制台。"},{"en":"A robot system can be more useful than one machine part because the parts cooperate.","zh":"機械人系統可以比單一機件更有用，因為各部分會合作。"},{"en":"This phrase refers to the whole working setup, not one robot piece only.","zh":"這個短語指整個運作配置，而不只是某個機械人部件。"}],"source":"101 - ROBOTS.pdf","sourcePage":5},{"front":"brain and bone surgery","meaning":"腦部及骨科手術","examples":[{"en":"Some robot systems can perform brain and bone surgery.","zh":"有些機械人系統可以進行腦部及骨科手術。"},{"en":"Brain and bone surgery means operations on the brain or the bones, where accuracy is extremely important.","zh":"brain and bone surgery 指在大腦或骨骼上進行的手術，準確度極為重要。"},{"en":"A surgeon may use a robotic system when a cut must be made in a very exact place.","zh":"當切口必須在非常精確的位置時，外科醫生可能使用機械人系統。"},{"en":"Mistakes in brain and bone surgery can be serious, so precision matters greatly.","zh":"腦部及骨科手術中的錯誤可能很嚴重，所以精準度非常重要。"},{"en":"This phrase refers to delicate medical procedures, not ordinary treatment.","zh":"這個短語指精細醫療程序，而不是普通治療。"}],"source":"101 - ROBOTS.pdf","sourcePage":5},{"front":"submillimetre accuracy","meaning":"亞毫米級精準度","examples":[{"en":"Robots can perform surgery with submillimetre accuracy.","zh":"機械人可以以亞毫米級精準度進行手術。"},{"en":"Submillimetre accuracy means accuracy smaller than one millimetre.","zh":"submillimetre accuracy 指小於一毫米的精準程度。"},{"en":"A machine cutting a tiny medical implant may need submillimetre accuracy.","zh":"切割微型醫療植入物的機器可能需要亞毫米級精準度。"},{"en":"Such accuracy is important when a tiny mistake could damage tissue or bone.","zh":"當細微錯誤可能損傷組織或骨骼時，這種精準度很重要。"},{"en":"This phrase shows an extremely high level of precision.","zh":"這個短語顯示極高精準水平。"}],"source":"101 - ROBOTS.pdf","sourcePage":5},{"front":"far greater precision than","meaning":"遠高於……的精準度","examples":[{"en":"Robots may achieve far greater precision than human hands alone.","zh":"機械人可能達到遠高於單靠人手的精準度。"},{"en":"Far greater precision than means much more exact than the comparison point.","zh":"far greater precision than 指比比較對象精確得多。"},{"en":"A laser cutter can achieve far greater precision than scissors in making tiny shapes.","zh":"雷射切割機在製作細小形狀時，精準度可遠高於剪刀。"},{"en":"Greater precision reduces mistakes when small movements matter.","zh":"當細小動作很重要時，更高精準度可減少錯誤。"},{"en":"This phrase clearly compares two levels of accuracy.","zh":"這個短語清楚比較兩種準確程度。"}],"source":"101 - ROBOTS.pdf","sourcePage":6},{"front":"highly skilled physicians","meaning":"技術高超的醫生","examples":[{"en":"Even highly skilled physicians may benefit from robotic assistance.","zh":"即使技術高超的醫生，也可能從機械人協助中受益。"},{"en":"Highly skilled physicians are doctors with advanced training and strong medical ability.","zh":"highly skilled physicians 指受過高階訓練、醫療能力強的醫生。"},{"en":"A highly skilled physician may still use technology to check details before surgery.","zh":"技術高超的醫生在手術前仍可能使用科技檢查細節。"},{"en":"Expert doctors can perform better when tools support their judgement and hand movements.","zh":"當工具支援醫生的判斷和手部動作時，專家醫生可以表現更好。"},{"en":"This phrase praises human expertise while allowing for machine assistance.","zh":"這個短語讚揚人類專業，同時容許機器協助。"}],"source":"101 - ROBOTS.pdf","sourcePage":6},{"front":"with their hands alone","meaning":"單靠雙手","examples":[{"en":"Doctors may not achieve such precision with their hands alone.","zh":"醫生單靠雙手未必能達到這種精準度。"},{"en":"With their hands alone means using only their hands, without tools or machines helping.","zh":"with their hands alone 指只使用雙手，而沒有工具或機器協助。"},{"en":"A jeweller may not shape a tiny part perfectly with hands alone, so tools are needed.","zh":"珠寶匠單靠雙手未必能完美塑造細小零件，所以需要工具。"},{"en":"When work needs extreme accuracy, human hands may need technological support.","zh":"當工作需要極高準確度時，人手可能需要科技支援。"},{"en":"This phrase contrasts unaided human action with assisted action.","zh":"這個短語把無輔助的人類行動與有輔助行動作對比。"}],"source":"101 - ROBOTS.pdf","sourcePage":6},{"front":"at the same time","meaning":"同時","examples":[{"en":"At the same time, long-distance control can keep people away from danger.","zh":"同時，遙距控制可以使人遠離危險。"},{"en":"At the same time means simultaneously or used to introduce another related point.","zh":"at the same time 指同時發生，或用來引入另一個相關重點。"},{"en":"A teacher can correct grammar and, at the same time, encourage confidence.","zh":"老師可以改正文法，同時鼓勵信心。"},{"en":"This phrase often adds a second benefit or contrast to the discussion.","zh":"這個短語常為討論加入第二個好處或對比。"},{"en":"It helps show that two things can be true together.","zh":"它幫助顯示兩件事可以同時成立。"}],"source":"101 - ROBOTS.pdf","sourcePage":6},{"front":"techniques of long-distance control","meaning":"遙距控制技術","examples":[{"en":"Techniques of long-distance control allow robots to work in hazardous places.","zh":"遙距控制技術讓機械人在危險地方工作。"},{"en":"Techniques of long-distance control are methods for operating machines from far away.","zh":"techniques of long-distance control 指從遠處操作機器的方法。"},{"en":"A drone pilot uses long-distance control to inspect a roof without climbing up.","zh":"無人機操作員使用遙距控制技術檢查屋頂，而不需要爬上去。"},{"en":"These techniques keep people safer when the work site is dangerous or hard to reach.","zh":"當工作地點危險或難以到達時，這些技術使人更安全。"},{"en":"This phrase focuses on remote operation.","zh":"這個短語著重遠距離操作。"}],"source":"101 - ROBOTS.pdf","sourcePage":6},{"front":"keep people from hazard","meaning":"使人遠離危險","examples":[{"en":"Robots can keep people farther from hazard.","zh":"機械人可以使人更遠離危險。"},{"en":"To keep people from hazard means to prevent people from getting close to danger.","zh":"keep people from hazard 指防止人們接近危險。"},{"en":"Firefighters may use robots to keep people from hazard in a burning building.","zh":"消防員可能使用機械人，使人遠離燃燒建築中的危險。"},{"en":"If dangerous work can be done remotely, fewer workers need to enter risky areas.","zh":"如果危險工作可以遙距完成，就較少工人需要進入高風險區域。"},{"en":"This phrase shows protection through distance.","zh":"這個短語顯示透過距離來保護。"}],"source":"101 - ROBOTS.pdf","sourcePage":6},{"front":"a robotic explorer","meaning":"機械人探測器","examples":[{"en":"NASA used a robotic explorer called Dante.","zh":"NASA 使用了一個名為 Dante 的機械人探測器。"},{"en":"A robotic explorer is a robot designed to investigate places that may be dangerous or difficult for humans.","zh":"robotic explorer 指設計用來調查對人類可能危險或困難地方的機械人。"},{"en":"A robotic explorer could enter a collapsed tunnel before rescue workers go inside.","zh":"機械人探測器可以在救援人員進入前，先進入倒塌隧道。"},{"en":"Such robots collect information while keeping people out of immediate danger.","zh":"這些機械人收集資訊，同時讓人遠離即時危險。"},{"en":"This phrase presents the robot as a machine built for exploration.","zh":"這個短語把機械人呈現為為探索而建的機器。"}],"source":"101 - ROBOTS.pdf","sourcePage":6},{"front":"video-camera eyes","meaning":"攝錄機眼睛","examples":[{"en":"Dante had video-camera eyes and spiderlike legs.","zh":"Dante 有攝錄機眼睛和蜘蛛般的腿。"},{"en":"Video-camera eyes are cameras used by a robot to send visual information like eyes do for humans.","zh":"video-camera eyes 指機械人用來傳送視覺資訊的攝錄機，就像人類眼睛一樣。"},{"en":"A security robot may use video-camera eyes to see corridors at night.","zh":"保安機械人可能使用攝錄機眼睛在夜間查看走廊。"},{"en":"Cameras allow human operators to guide robots through places they cannot enter safely.","zh":"攝錄機讓人類操作員引導機械人穿過人類不能安全進入的地方。"},{"en":"This phrase describes robot vision in a vivid, human-like way.","zh":"這個短語以生動、類似人類的方式描述機械人視覺。"}],"source":"101 - ROBOTS.pdf","sourcePage":6},{"front":"spiderlike legs","meaning":"蜘蛛般的腿","examples":[{"en":"The robot moved on spiderlike legs.","zh":"這部機械人用蜘蛛般的腿移動。"},{"en":"Spiderlike legs are legs shaped or arranged like those of a spider.","zh":"spiderlike legs 指形狀或排列像蜘蛛腳的腿。"},{"en":"A robot with spiderlike legs can step over rocks better than a robot with wheels.","zh":"有蜘蛛般的腿的機械人，比有輪子的機械人更能跨過石塊。"},{"en":"Multiple legs can help a machine keep balance on uneven ground.","zh":"多條腿可以幫助機器在不平地面保持平衡。"},{"en":"This phrase helps readers imagine the robot’s unusual movement.","zh":"這個短語幫助讀者想像機械人的不尋常移動方式。"}],"source":"101 - ROBOTS.pdf","sourcePage":6},{"front":"scramble over","meaning":"爬過；攀越","examples":[{"en":"The robotic explorer scrambled over the rim of a volcano.","zh":"機械人探測器爬過火山邊緣。"},{"en":"To scramble over something means to climb or move over it awkwardly but actively.","zh":"scramble over something 指笨拙但積極地爬過或越過某物。"},{"en":"Children may scramble over rocks at the beach when the path is uneven.","zh":"當路面不平，孩子可能在海灘上爬過石頭。"},{"en":"Robots need strong movement systems to scramble over rough ground safely.","zh":"機械人需要強大移動系統，才能安全攀越崎嶇地面。"},{"en":"This phrase suggests difficult climbing rather than smooth walking.","zh":"這個短語表示困難攀爬，而不是順暢行走。"}],"source":"101 - ROBOTS.pdf","sourcePage":6},{"front":"the menacing rim of","meaning":"……險惡的邊緣","examples":[{"en":"Dante scrambled over the menacing rim of an Alaskan volcano.","zh":"Dante 爬過一座阿拉斯加火山險惡的邊緣。"},{"en":"The menacing rim of something is the dangerous-looking edge around it.","zh":"menacing rim of something 指某物周圍看起來危險的邊緣。"},{"en":"Hikers may avoid the menacing rim of a cliff when strong winds blow.","zh":"強風吹起時，遠足者可能避開懸崖險惡的邊緣。"},{"en":"A place can look menacing because a small mistake there could cause serious harm.","zh":"一個地方可能顯得險惡，因為在那裡小錯誤也可能造成嚴重傷害。"},{"en":"This phrase creates a strong sense of danger at the edge of a place.","zh":"這個短語在某地邊緣營造強烈危險感。"}],"source":"101 - ROBOTS.pdf","sourcePage":7},{"front":"an Alaskan volcano","meaning":"阿拉斯加火山","examples":[{"en":"The robot explored the rim of an Alaskan volcano.","zh":"這部機械人探索了一座阿拉斯加火山的邊緣。"},{"en":"An Alaskan volcano is a volcano located in Alaska.","zh":"Alaskan volcano 指位於阿拉斯加的火山。"},{"en":"Scientists may study an Alaskan volcano to understand eruptions, gases and heat.","zh":"科學家可能研究阿拉斯加火山，以了解噴發、氣體和熱力。"},{"en":"Volcanic areas can be dangerous, so robots can help collect information safely.","zh":"火山地區可能危險，所以機械人可以幫助安全收集資訊。"},{"en":"This phrase gives a specific geographical setting for the exploration.","zh":"這個短語為探測提供具體地理背景。"}],"source":"101 - ROBOTS.pdf","sourcePage":7},{"front":"watch the scene by satellite","meaning":"透過衛星觀看現場","examples":[{"en":"Technicians watched the scene by satellite.","zh":"技術員透過衛星觀看現場。"},{"en":"To watch the scene by satellite means to observe a distant place using signals sent through satellites.","zh":"watch the scene by satellite 指使用經衛星傳送的信號觀察遠方地方。"},{"en":"Rescue teams may watch a flooded area by satellite before sending people in.","zh":"救援隊可能在派人進入前，透過衛星觀看水浸地區。"},{"en":"Satellite viewing helps people monitor remote or dangerous places from a safe distance.","zh":"衛星觀察幫助人們從安全距離監察偏遠或危險地方。"},{"en":"This phrase links observation with long-distance technology.","zh":"這個短語把觀察與遙距科技連繫起來。"}],"source":"101 - ROBOTS.pdf","sourcePage":7},{"front":"control someone’s descent","meaning":"控制……的下降","examples":[{"en":"Technicians controlled Dante’s descent from far away.","zh":"技術員從遠處控制 Dante 的下降。"},{"en":"To control someone’s descent means to guide how they move downward.","zh":"control someone’s descent 指引導某人或某物如何向下移動。"},{"en":"A climbing instructor may control a student’s descent on a rope.","zh":"攀石教練可能用繩索控制學生下降。"},{"en":"Controlling descent is important when the surface is steep, unstable or dangerous.","zh":"當表面陡斜、不穩或危險時，控制下降很重要。"},{"en":"This phrase focuses on safe downward movement.","zh":"這個短語著重安全向下移動。"}],"source":"101 - ROBOTS.pdf","sourcePage":7},{"front":"reach the next stage of","meaning":"達到……的下一階段","examples":[{"en":"Robots must improve to reach the next stage of labour-saving utility.","zh":"機械人必須改進，才能達到節省勞力實用性的下一階段。"},{"en":"To reach the next stage of something means to develop enough to move to a more advanced level.","zh":"reach the next stage of something 指發展到足以進入更高階段。"},{"en":"A student may reach the next stage of writing when they can organise paragraphs clearly.","zh":"當學生能清楚組織段落時，可能達到寫作的下一階段。"},{"en":"Technologies reach the next stage when they become more useful and less dependent on human help.","zh":"當科技變得更有用、更少依賴人類協助時，就達到下一階段。"},{"en":"This phrase shows progress from one level to another.","zh":"這個短語顯示由一個層次進步到另一個層次。"}],"source":"101 - ROBOTS.pdf","sourcePage":7},{"front":"labour-saving utility","meaning":"節省勞力的實用性","examples":[{"en":"Robots need greater labour-saving utility.","zh":"機械人需要更大的節省勞力實用性。"},{"en":"Labour-saving utility is the practical usefulness of reducing the amount of human work needed.","zh":"labour-saving utility 指減少所需人力工作的實際用途。"},{"en":"A dishwasher has labour-saving utility because it reduces time spent washing plates by hand.","zh":"洗碗機有節省勞力的實用性，因為它減少手洗碗碟的時間。"},{"en":"A robot has higher labour-saving utility if it can work safely without constant supervision.","zh":"如果機械人能在沒有持續監督下安全工作，它就有更高節省勞力實用性。"},{"en":"This phrase focuses on usefulness in saving effort.","zh":"這個短語著重節省力氣方面的用途。"}],"source":"101 - ROBOTS.pdf","sourcePage":7},{"front":"operate with less human supervision","meaning":"在較少人類監督下運作","examples":[{"en":"Future robots will need to operate with less human supervision.","zh":"未來機械人需要在較少人類監督下運作。"},{"en":"To operate with less human supervision means to work with fewer people watching or guiding each step.","zh":"operate with less human supervision 指工作時較少需要人觀看或引導每一步。"},{"en":"A cleaning robot operates with less supervision when it can avoid furniture by itself.","zh":"清潔機械人如果能自行避開家具，就是在較少監督下運作。"},{"en":"Less supervision saves time, but it also requires the robot to make safer decisions.","zh":"較少監督可節省時間，但也要求機械人作出更安全決定。"},{"en":"This phrase shows a move towards greater independence.","zh":"這個短語顯示走向更大自主性。"}],"source":"101 - ROBOTS.pdf","sourcePage":7},{"front":"human supervision","meaning":"人類監督","examples":[{"en":"Some robots still require close human supervision.","zh":"有些機械人仍需要密切人類監督。"},{"en":"Human supervision is the watching, checking or guiding done by people.","zh":"human supervision 指由人進行的觀看、檢查或引導。"},{"en":"Young children need human supervision when they use sharp tools in a classroom.","zh":"年幼孩子在課室使用鋒利工具時需要人類監督。"},{"en":"If a machine makes serious mistakes, human supervision becomes essential.","zh":"如果機器會犯嚴重錯誤，人類監督就變得必要。"},{"en":"This phrase contrasts independent operation with people monitoring the process.","zh":"這個短語把自主運作與由人監察過程作對比。"}],"source":"101 - ROBOTS.pdf","sourcePage":7},{"front":"make decisions for themselves","meaning":"自行作決定","examples":[{"en":"Advanced robots may need to make decisions for themselves.","zh":"先進機械人可能需要自行作決定。"},{"en":"To make decisions for themselves means to choose actions without direct human instruction each time.","zh":"make decisions for themselves 指不需每次由人直接指示而選擇行動。"},{"en":"A delivery robot must make decisions for itself when a path is blocked.","zh":"當路徑被阻塞，送貨機械人必須自行作決定。"},{"en":"Independent decisions can make robots more useful, but wrong decisions can create risk.","zh":"自主決定可以令機械人更有用，但錯誤決定可能造成風險。"},{"en":"This phrase focuses on autonomy.","zh":"這個短語著重自主性。"}],"source":"101 - ROBOTS.pdf","sourcePage":7},{"front":"pose a formidable challenge","meaning":"構成艱巨挑戰","examples":[{"en":"Giving robots common sense poses a formidable challenge.","zh":"賦予機械人常識構成艱巨挑戰。"},{"en":"To pose a formidable challenge means to create a very difficult problem.","zh":"pose a formidable challenge 指造成非常困難的問題。"},{"en":"Teaching a computer to understand jokes poses a formidable challenge because meaning depends on context.","zh":"教電腦理解笑話構成艱巨挑戰，因為意思取決於語境。"},{"en":"A formidable challenge may require years of research and many failed attempts.","zh":"艱巨挑戰可能需要多年研究和許多失敗嘗試。"},{"en":"This phrase signals that the task is seriously difficult.","zh":"這個短語表示任務非常困難。"}],"source":"101 - ROBOTS.pdf","sourcePage":7},{"front":"a formidable challenge","meaning":"艱巨挑戰","examples":[{"en":"Artificial intelligence remains a formidable challenge.","zh":"人工智能仍然是一項艱巨挑戰。"},{"en":"A formidable challenge is a problem that is large, difficult and intimidating.","zh":"formidable challenge 指巨大、困難而令人望而生畏的問題。"},{"en":"Learning a new language as an adult can be a formidable challenge without regular practice.","zh":"成年後學新語言，如果沒有定期練習，可能是一項艱巨挑戰。"},{"en":"Formidable challenges require patience, planning and support.","zh":"艱巨挑戰需要耐性、計劃和支援。"},{"en":"This phrase is stronger than “a difficult task”.","zh":"這個短語比 a difficult task 語氣更強。"}],"source":"101 - ROBOTS.pdf","sourcePage":8},{"front":"handle a specific error","meaning":"處理特定錯誤","examples":[{"en":"Engineers can tell a robot how to handle a specific error.","zh":"工程師可以告訴機械人如何處理特定錯誤。"},{"en":"To handle a specific error means to deal with one clearly identified mistake or problem.","zh":"handle a specific error 指處理一個明確識別出的錯誤或問題。"},{"en":"A printer can handle a specific error by showing a message when paper is stuck.","zh":"當紙張卡住時，打印機可以透過顯示訊息處理特定錯誤。"},{"en":"Robots are easier to program for known errors than for unexpected situations.","zh":"為已知錯誤編程機械人，比處理意外情況容易。"},{"en":"This phrase focuses on one defined problem, not general understanding.","zh":"這個短語著重一個已定義問題，而不是一般理解能力。"}],"source":"101 - ROBOTS.pdf","sourcePage":8},{"front":"common sense","meaning":"常識","examples":[{"en":"Robots do not yet have enough common sense.","zh":"機械人尚未有足夠常識。"},{"en":"Common sense is practical judgement about ordinary situations.","zh":"common sense 指對普通情況的實際判斷力。"},{"en":"A person uses common sense when they avoid touching a hot pan without being told.","zh":"一個人不用別人提醒也不碰熱鍋，就是在使用常識。"},{"en":"Common sense helps people handle new situations that do not follow exact rules.","zh":"常識幫助人處理不完全跟隨明確規則的新情況。"},{"en":"This phrase refers to everyday judgement, not academic knowledge.","zh":"這個短語指日常判斷，而不是學術知識。"}],"source":"101 - ROBOTS.pdf","sourcePage":8},{"front":"reliably interact with","meaning":"可靠地與……互動","examples":[{"en":"Robots cannot yet reliably interact with a dynamic world.","zh":"機械人尚未能可靠地與不斷變化的世界互動。"},{"en":"To reliably interact with something means to work with it successfully and consistently.","zh":"reliably interact with something 指能持續成功地與某物互動。"},{"en":"A customer-service chatbot must reliably interact with users who ask questions in different ways.","zh":"客戶服務聊天機械人必須可靠地與用不同方式提問的使用者互動。"},{"en":"Reliable interaction is hard when the environment keeps changing.","zh":"當環境不斷改變時，可靠互動很困難。"},{"en":"This phrase focuses on consistent performance in real situations.","zh":"這個短語著重在真實情況中的穩定表現。"}],"source":"101 - ROBOTS.pdf","sourcePage":8},{"front":"a dynamic world","meaning":"不斷變化的世界","examples":[{"en":"Robots struggle to interact with a dynamic world.","zh":"機械人難以與不斷變化的世界互動。"},{"en":"A dynamic world is a world that keeps changing and contains many unpredictable events.","zh":"dynamic world 指不斷改變並包含許多難以預測事件的世界。"},{"en":"A busy school corridor is dynamic because students, bags and doors keep moving.","zh":"繁忙學校走廊是不斷變化的，因為學生、書包和門都在移動。"},{"en":"Machines find dynamic environments harder than fixed factory settings.","zh":"機器覺得動態環境比固定工廠環境更困難。"},{"en":"This phrase highlights change and unpredictability.","zh":"這個短語突出變化和不可預測性。"}],"source":"101 - ROBOTS.pdf","sourcePage":8},{"front":"the quest for","meaning":"對……的追求","examples":[{"en":"The quest for true artificial intelligence has produced mixed results.","zh":"對真正人工智能的追求產生了好壞參半的結果。"},{"en":"The quest for something is a long search or effort to achieve it.","zh":"quest for something 指為達成某事而進行的長期尋找或努力。"},{"en":"A scientist’s quest for a safer medicine may take many years.","zh":"科學家對更安全藥物的追求可能需要多年。"},{"en":"Quests often involve setbacks because the goal is difficult.","zh":"追求常包含挫折，因為目標很困難。"},{"en":"This phrase gives a serious, long-term feeling to the effort.","zh":"這個短語令努力帶有嚴肅而長期的感覺。"}],"source":"101 - ROBOTS.pdf","sourcePage":8},{"front":"true artificial intelligence","meaning":"真正的人工智能","examples":[{"en":"The quest for true artificial intelligence has been difficult.","zh":"對真正人工智能的追求一直很困難。"},{"en":"True artificial intelligence means machine intelligence that can understand, learn and adapt broadly like a human mind.","zh":"true artificial intelligence 指能像人類思維般廣泛理解、學習和適應的機器智能。"},{"en":"A calculator is useful, but it is not true artificial intelligence because it cannot understand situations.","zh":"計算機很有用，但它不是真正的人工智能，因為它不能理解情況。"},{"en":"Creating true artificial intelligence is hard because everyday judgement is complex.","zh":"創造真正人工智能很難，因為日常判斷很複雜。"},{"en":"This phrase refers to deep intelligence, not simple automation.","zh":"這個短語指深層智能，而不是簡單自動化。"}],"source":"101 - ROBOTS.pdf","sourcePage":8},{"front":"mixed results","meaning":"好壞參半的結果","examples":[{"en":"Research into artificial intelligence has produced mixed results.","zh":"人工智能研究產生了好壞參半的結果。"},{"en":"Mixed results are results that include both successes and failures.","zh":"mixed results 指同時包含成功和失敗的結果。"},{"en":"A new study method may give mixed results if some students improve but others do not.","zh":"如果有些學生進步而另一些沒有，新學習方法可能產生好壞參半的結果。"},{"en":"Mixed results make it hard to claim that a project is clearly successful.","zh":"好壞參半的結果令人難以聲稱項目明顯成功。"},{"en":"This phrase suggests a balanced or uncertain outcome.","zh":"這個短語表示平衡或不確定的結果。"}],"source":"101 - ROBOTS.pdf","sourcePage":8},{"front":"a spasm of initial optimism","meaning":"一陣最初的樂觀情緒","examples":[{"en":"There was a spasm of initial optimism about artificial intelligence.","zh":"人工智能曾引發一陣最初的樂觀情緒。"},{"en":"A spasm of initial optimism is a short, sudden period of strong early hope.","zh":"spasm of initial optimism 指一段短暫而突然的強烈早期希望。"},{"en":"A new school policy may produce a spasm of initial optimism before practical problems appear.","zh":"新學校政策可能在實際問題出現前帶來一陣最初的樂觀情緒。"},{"en":"Early excitement can fade when the task proves harder than expected.","zh":"當任務比預期更困難，早期興奮可能消退。"},{"en":"This phrase suggests optimism that is intense but may not last.","zh":"這個短語表示樂觀強烈但未必持久。"}],"source":"101 - ROBOTS.pdf","sourcePage":8},{"front":"transistor circuits","meaning":"晶體管電路","examples":[{"en":"Researchers once thought transistor circuits could imitate the brain.","zh":"研究人員曾認為晶體管電路可以模仿大腦。"},{"en":"Transistor circuits are electronic circuits built from small components that control electrical signals.","zh":"transistor circuits 指由控制電信號的小型元件構成的電子電路。"},{"en":"Computers use transistor circuits to process information quickly.","zh":"電腦使用晶體管電路快速處理資訊。"},{"en":"Early researchers hoped these circuits could model human thinking, but the brain proved far more complex.","zh":"早期研究人員希望這些電路可以模擬人類思考，但大腦證明複雜得多。"},{"en":"This phrase refers to the hardware inside electronic devices.","zh":"這個短語指電子裝置內部的硬件。"}],"source":"101 - ROBOTS.pdf","sourcePage":8},{"front":"microprocessors","meaning":"微處理器","examples":[{"en":"Microprocessors were once expected to perform like the human brain.","zh":"微處理器曾被期待像人類大腦一樣運作。"},{"en":"Microprocessors are small computer chips that carry out instructions and calculations.","zh":"microprocessors 指執行指令和計算的小型電腦晶片。"},{"en":"A phone, washing machine or car may contain microprocessors to control its functions.","zh":"手機、洗衣機或汽車可能含有微處理器來控制其功能。"},{"en":"More powerful microprocessors allow machines to process more information faster.","zh":"更強大的微處理器讓機器更快處理更多資訊。"},{"en":"This phrase refers to the “thinking” chips inside many electronic devices.","zh":"這個短語指許多電子裝置內部的「思考」晶片。"}],"source":"101 - ROBOTS.pdf","sourcePage":9},{"front":"perform in the same way as","meaning":"以與……相同的方式運作","examples":[{"en":"Computers were expected to perform in the same way as the human brain.","zh":"電腦曾被期待以與人類大腦相同的方式運作。"},{"en":"To perform in the same way as something means to work or behave like it.","zh":"perform in the same way as something 指像某物那樣運作或表現。"},{"en":"A translation app does not perform in the same way as a human interpreter because it may miss tone.","zh":"翻譯應用程式不像真人傳譯員那樣運作，因為它可能錯過語氣。"},{"en":"Machines can imitate some human actions but still fail to perform like people in complex situations.","zh":"機器可以模仿某些人類行動，但在複雜情況中仍未必能像人一樣表現。"},{"en":"This phrase compares how two things operate.","zh":"這個短語比較兩件事如何運作。"}],"source":"101 - ROBOTS.pdf","sourcePage":9},{"front":"by the 21st century","meaning":"到21世紀時","examples":[{"en":"Some researchers expected machines to imitate the brain by the 21st century.","zh":"有些研究人員預期機器到21世紀時會模仿大腦。"},{"en":"By the 21st century means no later than the time when the 21st century arrived.","zh":"by the 21st century 指不遲於21世紀到來時。"},{"en":"Some people expected paper books to disappear by the 21st century, but they did not.","zh":"有些人曾預期紙本書到21世紀時會消失，但它們沒有。"},{"en":"Predictions with “by” set a deadline for when something is expected to happen.","zh":"使用 by 的預測會為某事預期發生時間設定期限。"},{"en":"This phrase connects a forecast with a time limit.","zh":"這個短語把預測與時間限制連繫起來。"}],"source":"101 - ROBOTS.pdf","sourcePage":9},{"front":"extend forecasts by","meaning":"將預測延後……","examples":[{"en":"Researchers have extended their forecasts by decades.","zh":"研究人員已將預測延後數十年。"},{"en":"To extend forecasts by a period means to move expected dates further into the future.","zh":"extend forecasts by a period 指把預期日期推遲到更遠的未來。"},{"en":"A builder may extend a completion forecast by two months after heavy rain delays work.","zh":"大雨延誤工程後，建築商可能把完工預測延後兩個月。"},{"en":"Forecasts are extended when progress is slower than originally expected.","zh":"當進展比原先預期慢，預測就會被延後。"},{"en":"This phrase shows a delayed expectation.","zh":"這個短語顯示期望被推遲。"}],"source":"101 - ROBOTS.pdf","sourcePage":9},{"front":"by decades if not centuries","meaning":"即使不是數百年，也至少是數十年","examples":[{"en":"Researchers have extended their forecasts by decades if not centuries.","zh":"研究人員已將預測延後即使不是數百年，也至少是數十年。"},{"en":"By decades if not centuries means by many decades, and possibly by hundreds of years.","zh":"by decades if not centuries 指延後許多個十年，甚至可能數百年。"},{"en":"A difficult medical cure may be delayed by decades if not centuries if the science is not ready.","zh":"如果科學尚未成熟，困難醫療療法可能延後即使不是數百年，也至少是數十年。"},{"en":"This phrase emphasises that the delay may be extremely long.","zh":"這個短語強調延誤可能極長。"},{"en":"It is used when the speaker thinks earlier expectations were far too optimistic.","zh":"當說話者認為早期期望過分樂觀時，會使用這個短語。"}],"source":"101 - ROBOTS.pdf","sourcePage":9},{"front":"attempt to model thought","meaning":"嘗試模擬思維","examples":[{"en":"Scientists are attempting to model thought in machines.","zh":"科學家正嘗試在機器中模擬思維。"},{"en":"To attempt to model thought means to try to represent thinking through a machine or system.","zh":"attempt to model thought 指嘗試透過機器或系統呈現思考。"},{"en":"A simple chatbot models part of conversation but not full human thought.","zh":"簡單聊天機械人模擬部分對話，但不是完整人類思維。"},{"en":"Modelling thought is difficult because thinking includes memory, emotion, context and judgement.","zh":"模擬思維很困難，因為思考包括記憶、情感、語境和判斷。"},{"en":"This phrase describes an effort to turn mental processes into a technical model.","zh":"這個短語描述把心理過程轉化為技術模型的努力。"}],"source":"101 - ROBOTS.pdf","sourcePage":9},{"front":"roughly one hundred billion neurons","meaning":"約一千億個神經元","examples":[{"en":"The human brain contains roughly one hundred billion neurons.","zh":"人類大腦包含約一千億個神經元。"},{"en":"Roughly one hundred billion neurons means about 100,000,000,000 nerve cells.","zh":"roughly one hundred billion neurons 指大約 100,000,000,000 個神經細胞。"},{"en":"A teacher might use this number to show why the brain is hard to copy.","zh":"老師可能用這個數字說明為何大腦難以複製。"},{"en":"The huge number of neurons helps explain why human perception is so complex.","zh":"神經元數量龐大，有助解釋人類感知為何如此複雜。"},{"en":"This phrase gives an approximate scale, not an exact count.","zh":"這個短語給出近似規模，而不是精確數量。"}],"source":"101 - ROBOTS.pdf","sourcePage":9},{"front":"human perception","meaning":"人類感知","examples":[{"en":"Human perception is far more complicated than expected.","zh":"人類感知比預期複雜得多。"},{"en":"Human perception is the way people see, hear, notice and understand the world around them.","zh":"human perception 指人類觀看、聆聽、注意和理解周圍世界的方式。"},{"en":"A driver uses human perception to notice a child near the road while ignoring background signs.","zh":"司機使用人類感知注意路邊的小孩，同時忽略背景標誌。"},{"en":"Perception is complex because the brain must select important information quickly.","zh":"感知很複雜，因為大腦必須快速選擇重要資訊。"},{"en":"This phrase refers to how humans make sense of sensory information.","zh":"這個短語指人類如何理解感官資訊。"}],"source":"101 - ROBOTS.pdf","sourcePage":9},{"front":"previously imagined","meaning":"以往所想像的","examples":[{"en":"The brain is more complex than previously imagined.","zh":"大腦比以往所想像的更複雜。"},{"en":"Previously imagined means thought or believed earlier.","zh":"previously imagined 指早前所想或所相信的。"},{"en":"Online teaching proved harder than previously imagined when teachers had to keep students engaged.","zh":"當老師需要保持學生投入時，網上教學證明比以往所想像的更困難。"},{"en":"New evidence can show that a problem is deeper than people first believed.","zh":"新證據可以顯示問題比人們最初所相信的更深。"},{"en":"This phrase compares current understanding with earlier assumptions.","zh":"這個短語比較目前理解與早前假設。"}],"source":"101 - ROBOTS.pdf","sourcePage":9},{"front":"recognise the misalignment of","meaning":"識別……的錯位","examples":[{"en":"Some robots can recognise the misalignment of a machine panel.","zh":"有些機械人可以識別機器面板的錯位。"},{"en":"To recognise the misalignment of something means to notice that it is not correctly lined up.","zh":"recognise the misalignment of something 指注意到某物沒有正確對齊。"},{"en":"A mechanic can recognise the misalignment of a car door when it does not close smoothly.","zh":"當車門不能順暢關上，機械師可以識別車門錯位。"},{"en":"Detecting misalignment early can prevent larger mechanical problems later.","zh":"及早偵測錯位可以防止日後更大的機械問題。"},{"en":"This phrase focuses on noticing small positional errors.","zh":"這個短語著重注意細小位置錯誤。"}],"source":"101 - ROBOTS.pdf","sourcePage":9},{"front":"a machine panel","meaning":"機器面板","examples":[{"en":"A robot can detect a tiny misalignment in a machine panel.","zh":"機械人可以偵測機器面板中的微小錯位。"},{"en":"A machine panel is a flat part or cover on a machine, often holding controls or protecting inner parts.","zh":"machine panel 指機器上的平面部分或外蓋，常用來放置控制裝置或保護內部零件。"},{"en":"A factory worker may open a machine panel to check wires or buttons inside.","zh":"工廠工人可能打開機器面板，檢查裡面的電線或按鈕。"},{"en":"If a machine panel is not aligned, the machine may not close or operate safely.","zh":"如果機器面板沒有對齊，機器可能無法安全關閉或運作。"},{"en":"This phrase refers to a physical part of a machine.","zh":"這個短語指機器的實體部分。"}],"source":"101 - ROBOTS.pdf","sourcePage":10},{"front":"a fraction of a millimetre","meaning":"一毫米的一小部分","examples":[{"en":"The robot can detect an error by a fraction of a millimetre.","zh":"機械人可以偵測到一毫米一小部分的錯誤。"},{"en":"A fraction of a millimetre is a very tiny distance smaller than one millimetre.","zh":"fraction of a millimetre 指小於一毫米的極小距離。"},{"en":"A watchmaker may work with parts that differ by only a fraction of a millimetre.","zh":"鐘錶匠可能處理只相差一毫米一小部分的零件。"},{"en":"Tiny differences can matter when machines must fit together exactly.","zh":"當機器必須精確組合時，細小差異也可能重要。"},{"en":"This phrase emphasises extremely small measurement.","zh":"這個短語強調極細微量度。"}],"source":"101 - ROBOTS.pdf","sourcePage":10},{"front":"a controlled factory environment","meaning":"受控的工廠環境","examples":[{"en":"Robots perform well in a controlled factory environment.","zh":"機械人在受控的工廠環境中表現良好。"},{"en":"A controlled factory environment is a workplace where conditions, movements and tasks are carefully arranged.","zh":"controlled factory environment 指條件、動作和任務都被仔細安排的工作場所。"},{"en":"Assembly lines are controlled environments because parts arrive in a fixed order.","zh":"裝配線是受控環境，因為零件以固定次序到達。"},{"en":"Robots perform better when surprises are reduced and each action is predictable.","zh":"當意外情況減少，每個動作可預測時，機械人表現更好。"},{"en":"This phrase contrasts factories with messy real-world settings.","zh":"這個短語把工廠與混亂現實環境作對比。"}],"source":"101 - ROBOTS.pdf","sourcePage":10},{"front":"the human mind","meaning":"人類思維","examples":[{"en":"The human mind can process complex scenes very quickly.","zh":"人類思維可以非常快速地處理複雜場景。"},{"en":"The human mind is the part of a person that thinks, perceives, remembers and judges.","zh":"human mind 指人用來思考、感知、記憶和判斷的部分。"},{"en":"A driver’s mind can notice a moving bicycle while also reading traffic lights.","zh":"司機的人類思維可以注意移動中的單車，同時看交通燈。"},{"en":"The human mind filters information so people can focus on what matters.","zh":"人類思維會過濾資訊，使人能集中於重要事物。"},{"en":"This phrase refers to mental ability, not the physical brain alone.","zh":"這個短語指心理能力，而不只是實體大腦。"}],"source":"101 - ROBOTS.pdf","sourcePage":10},{"front":"glimpse a rapidly changing scene","meaning":"瞥見快速變化的場景","examples":[{"en":"The human mind can glimpse a rapidly changing scene.","zh":"人類思維可以瞥見快速變化的場景。"},{"en":"To glimpse a rapidly changing scene means to see it briefly while many things are moving or changing.","zh":"glimpse a rapidly changing scene 指在許多事物移動或變化時短暫看見該場景。"},{"en":"A passenger may glimpse a rapidly changing street scene from a moving bus.","zh":"乘客可能從行駛中的巴士瞥見快速變化的街景。"},{"en":"The brain can still pick out important details from a brief view.","zh":"大腦仍能從短暫一瞥中挑出重要細節。"},{"en":"This phrase shows quick visual understanding.","zh":"這個短語顯示快速視覺理解。"}],"source":"101 - ROBOTS.pdf","sourcePage":10},{"front":"immediately disregard","meaning":"立即忽略","examples":[{"en":"The brain can immediately disregard irrelevant information.","zh":"大腦可以立即忽略不相關資訊。"},{"en":"To immediately disregard something means to ignore it at once because it is not useful.","zh":"immediately disregard something 指因某事無用而立刻忽略它。"},{"en":"A student reading a timetable may immediately disregard routes that do not stop near school.","zh":"學生閱讀時間表時，可能立即忽略不到學校附近停站的路線。"},{"en":"Ignoring useless information quickly helps people make faster decisions.","zh":"快速忽略無用資訊幫助人更快作決定。"},{"en":"This phrase shows rapid filtering.","zh":"這個短語顯示快速過濾。"}],"source":"101 - ROBOTS.pdf","sourcePage":10},{"front":"irrelevant","meaning":"不相關的","examples":[{"en":"The brain filters out information that is irrelevant.","zh":"大腦會過濾不相關的資訊。"},{"en":"Irrelevant means not connected to what matters in the situation.","zh":"irrelevant 指與當前情況中重要事情無關。"},{"en":"In an exam, a story about your weekend is irrelevant if the question asks for data analysis.","zh":"在考試中，如果題目要求數據分析，關於週末的故事就是不相關的。"},{"en":"Removing irrelevant details can make an answer clearer.","zh":"刪除不相關細節可以令答案更清晰。"},{"en":"This word helps separate useful information from distracting information.","zh":"這個詞幫助把有用資訊與令人分心的資訊分開。"}],"source":"101 - ROBOTS.pdf","sourcePage":10},{"front":"instantaneously focusing on","meaning":"即時集中於","examples":[{"en":"The mind can instantaneously focus on a key detail.","zh":"人類思維可以即時集中於關鍵細節。"},{"en":"Instantaneously focusing on something means paying attention to it immediately.","zh":"instantaneously focusing on something 指立即把注意力放在某事上。"},{"en":"A nurse may instantaneously focus on a patient’s breathing if it suddenly changes.","zh":"如果病人呼吸突然改變，護士可能即時集中於該變化。"},{"en":"Quick focus helps people respond to danger before they fully analyse the whole scene.","zh":"快速集中注意力幫助人在完全分析整個場景前回應危險。"},{"en":"This phrase describes very fast attention.","zh":"這個短語描述非常快速的注意力。"}],"source":"101 - ROBOTS.pdf","sourcePage":10},{"front":"a winding forest road","meaning":"彎曲的森林道路","examples":[{"en":"A driver may notice an animal beside a winding forest road.","zh":"司機可能注意到彎曲的森林道路旁有一隻動物。"},{"en":"A winding forest road is a road through a forest that bends many times.","zh":"winding forest road 指穿過森林、轉彎很多的道路。"},{"en":"Drivers must slow down on a winding forest road because they cannot see far ahead.","zh":"司機在彎曲的森林道路上必須減速，因為看不到很遠前方。"},{"en":"Curves, trees and shadows make such roads visually complex.","zh":"彎道、樹木和陰影令這種道路在視覺上很複雜。"},{"en":"This phrase creates a scene where quick perception is important.","zh":"這個短語營造一個需要快速感知的場景。"}],"source":"101 - ROBOTS.pdf","sourcePage":10},{"front":"a suspicious face","meaning":"可疑的面孔","examples":[{"en":"The mind may notice a single suspicious face in a crowd.","zh":"人類思維可能在人群中注意到一張可疑的面孔。"},{"en":"A suspicious face is a face that looks unusual, threatening or worth attention.","zh":"suspicious face 指看起來不尋常、有威脅或值得注意的面孔。"},{"en":"A security guard may notice a suspicious face near a locked door.","zh":"保安員可能在上鎖門附近注意到一張可疑的面孔。"},{"en":"People focus on suspicious signs because they may indicate danger or wrongdoing.","zh":"人們集中於可疑跡象，因為它們可能表示危險或不當行為。"},{"en":"This phrase shows how one detail can stand out from many others.","zh":"這個短語顯示一個細節如何從許多事物中突出。"}],"source":"101 - ROBOTS.pdf","sourcePage":10},{"front":"a tumultuous crowd","meaning":"混亂的人群","examples":[{"en":"A human can notice one face in a tumultuous crowd.","zh":"人類可以在混亂的人群中注意到一張面孔。"},{"en":"A tumultuous crowd is a noisy, confused or disorderly group of many people.","zh":"tumultuous crowd 指嘈雜、混亂或失序的大群人。"},{"en":"After a concert, a station entrance may become a tumultuous crowd.","zh":"音樂會後，車站入口可能變成混亂的人群。"},{"en":"In a tumultuous crowd, it is hard for cameras or people to follow every movement.","zh":"在混亂的人群中，攝影機或人都難以跟蹤每個動作。"},{"en":"This phrase suggests movement, noise and confusion.","zh":"這個短語表示移動、噪音和混亂。"}],"source":"101 - ROBOTS.pdf","sourcePage":11},{"front":"the most advanced computer systems","meaning":"最先進的電腦系統","examples":[{"en":"The most advanced computer systems cannot match the human brain.","zh":"最先進的電腦系統也無法匹敵人類大腦。"},{"en":"The most advanced computer systems are the most powerful and modern computing machines available.","zh":"most advanced computer systems 指現有最強大、最現代化的電腦機器。"},{"en":"A hospital may use advanced computer systems to scan images and store records.","zh":"醫院可能使用先進電腦系統掃描影像和儲存紀錄。"},{"en":"Even very advanced systems can fail at tasks humans handle naturally.","zh":"即使非常先進的系統，也可能在一些人類自然處理的任務上失敗。"},{"en":"This phrase sets up a comparison between top technology and human ability.","zh":"這個短語建立頂尖科技與人類能力之間的比較。"}],"source":"101 - ROBOTS.pdf","sourcePage":11},{"front":"approach that kind of ability","meaning":"接近那種能力","examples":[{"en":"Computer systems cannot approach that kind of ability.","zh":"電腦系統無法接近那種能力。"},{"en":"To approach that kind of ability means to come close to matching that level of skill.","zh":"approach that kind of ability 指接近匹配那種技能水平。"},{"en":"A beginner swimmer cannot yet approach the ability of a trained lifeguard.","zh":"初學游泳者尚不能接近受訓救生員的能力。"},{"en":"A system may be impressive but still not close to human perception.","zh":"一個系統可能令人印象深刻，但仍未接近人類感知。"},{"en":"This phrase shows that the gap remains large.","zh":"這個短語顯示差距仍然很大。"}],"source":"101 - ROBOTS.pdf","sourcePage":11},{"front":"neuroscientists","meaning":"神經科學家","examples":[{"en":"Neuroscientists still do not fully understand human perception.","zh":"神經科學家仍未完全理解人類感知。"},{"en":"Neuroscientists are scientists who study the brain, nerves and nervous system.","zh":"neuroscientists 指研究大腦、神經和神經系統的科學家。"},{"en":"Neuroscientists may study how children learn language or how patients recover after brain injury.","zh":"神經科學家可能研究孩子如何學語言，或病人腦傷後如何康復。"},{"en":"Their research helps explain memory, movement, emotion and perception.","zh":"他們的研究幫助解釋記憶、動作、情緒和感知。"},{"en":"This word refers to experts in the science of the nervous system.","zh":"這個詞指神經系統科學方面的專家。"}],"source":"101 - ROBOTS.pdf","sourcePage":11},{"front":"know quite how","meaning":"確切知道如何","examples":[{"en":"Neuroscientists still do not know quite how the brain does this.","zh":"神經科學家仍未確切知道大腦如何做到這一點。"},{"en":"To know quite how something happens means to understand the exact method or process.","zh":"know quite how something happens 指理解某事發生的準確方法或過程。"},{"en":"Teachers may know that students improve with practice but not know quite how each student learns best.","zh":"老師可能知道學生會透過練習進步，但未必確切知道每個學生如何學得最好。"},{"en":"Not knowing quite how something works can limit the ability to copy or improve it.","zh":"如果未確切知道某事如何運作，就可能限制複製或改善它的能力。"},{"en":"This phrase expresses incomplete understanding of a process.","zh":"這個短語表達對過程的不完整理解。"}],"source":"101 - ROBOTS.pdf","sourcePage":11},{"front":"nonetheless","meaning":"儘管如此","examples":[{"en":"Nonetheless, researchers are finding ways to make robots more lifelike.","zh":"儘管如此，研究人員正尋找方法令機械人更像生命。"},{"en":"Nonetheless means despite what has just been said.","zh":"nonetheless 指儘管剛才所說如此。"},{"en":"The exam is difficult; nonetheless, steady practice can improve your score.","zh":"考試很難；儘管如此，穩定練習可以提升分數。"},{"en":"Writers use nonetheless to continue with a positive point after a difficulty.","zh":"作者使用 nonetheless，在困難之後繼續提出正面重點。"},{"en":"This word signals contrast without cancelling the previous idea.","zh":"這個詞表示對比，但不取消前一個想法。"}],"source":"101 - ROBOTS.pdf","sourcePage":11},{"front":"information theorists","meaning":"資訊理論學家","examples":[{"en":"Information theorists work with neuroscientists and computer experts.","zh":"資訊理論學家與神經科學家和電腦專家合作。"},{"en":"Information theorists study how information is measured, transmitted and processed.","zh":"information theorists 研究資訊如何被量度、傳送和處理。"},{"en":"An information theorist may help design a system that sends messages with fewer errors.","zh":"資訊理論學家可能幫助設計能以較少錯誤傳送訊息的系統。"},{"en":"Their ideas can help robots handle signals, patterns and uncertainty.","zh":"他們的想法可以幫助機械人處理信號、模式和不確定性。"},{"en":"This phrase refers to specialists in the mathematics of information.","zh":"這個短語指資訊數學方面的專家。"}],"source":"101 - ROBOTS.pdf","sourcePage":11},{"front":"pool their talents","meaning":"集合各自才能","examples":[{"en":"Scientists pool their talents to develop lifelike intelligence.","zh":"科學家集合各自才能，以發展類似生命的智能。"},{"en":"To pool their talents means to combine different people’s skills for a shared goal.","zh":"pool their talents 指把不同人的技能結合起來，為共同目標努力。"},{"en":"Teachers may pool their talents to create better lesson materials.","zh":"老師可能集合各自才能，創造更好的教材。"},{"en":"Complex problems improve when experts from different fields work together.","zh":"當不同領域專家合作時，複雜問題會得到改善。"},{"en":"This phrase emphasises cooperation and shared ability.","zh":"這個短語強調合作和共享能力。"}],"source":"101 - ROBOTS.pdf","sourcePage":11},{"front":"lifelike intelligence","meaning":"類似生命的智能","examples":[{"en":"Researchers are trying to get lifelike intelligence from robots.","zh":"研究人員正嘗試從機械人中獲得類似生命的智能。"},{"en":"Lifelike intelligence is machine behaviour that seems similar to real living intelligence.","zh":"lifelike intelligence 指看似接近真正生命智能的機器行為。"},{"en":"A robot that recognises emotion and responds gently may seem to have lifelike intelligence.","zh":"能識別情緒並溫和回應的機械人，可能看似具有類似生命的智能。"},{"en":"Lifelike intelligence is difficult because life involves context, feeling and flexible judgement.","zh":"類似生命的智能很難，因為生命涉及語境、感受和靈活判斷。"},{"en":"This phrase describes intelligence that appears natural rather than mechanical.","zh":"這個短語描述看起來自然而非機械的智能。"}],"source":"101 - ROBOTS.pdf","sourcePage":11},{"front":"renounce","meaning":"放棄","examples":[{"en":"One method renounces the usual structure of electronic circuits.","zh":"一種方法放棄了電子電路的通常結構。"},{"en":"To renounce something means to give it up or reject it deliberately.","zh":"renounce something 指有意放棄或拒絕某事。"},{"en":"A company may renounce plastic packaging and use paper instead.","zh":"公司可能放棄塑膠包裝，改用紙張。"},{"en":"Researchers renounce old methods when they believe a new approach can work better.","zh":"當研究人員相信新方法更有效時，會放棄舊方法。"},{"en":"This word is formal and stronger than “stop using”.","zh":"這個詞較正式，比 stop using 語氣更強。"}],"source":"101 - ROBOTS.pdf","sourcePage":11},{"front":"linear, logical structure","meaning":"線性、邏輯式結構","examples":[{"en":"Traditional electronic circuits have a linear, logical structure.","zh":"傳統電子電路具有線性、邏輯式結構。"},{"en":"A linear, logical structure follows an orderly step-by-step pattern.","zh":"linear, logical structure 指按有秩序步驟一步一步進行的結構。"},{"en":"A recipe has a linear structure when each step follows the previous one clearly.","zh":"如果食譜每一步清楚接續前一步，它就有線性結構。"},{"en":"Such structure is easy to control but may not imitate the messy brain well.","zh":"這種結構容易控制，但未必能很好模仿雜亂大腦。"},{"en":"This phrase contrasts neat sequence with complex natural networks.","zh":"這個短語把整齊順序與複雜自然網絡作對比。"}],"source":"101 - ROBOTS.pdf","sourcePage":12},{"front":"conventional electronic circuits","meaning":"傳統電子電路","examples":[{"en":"Neural networks differ from conventional electronic circuits.","zh":"神經網絡不同於傳統電子電路。"},{"en":"Conventional electronic circuits are standard circuits that follow planned electronic paths and logic.","zh":"conventional electronic circuits 指按照預定電子路徑和邏輯運作的標準電路。"},{"en":"A radio, calculator or simple alarm may use conventional electronic circuits.","zh":"收音機、計算機或簡單警報器可能使用傳統電子電路。"},{"en":"These circuits are reliable for fixed tasks but may be less flexible than learning systems.","zh":"這些電路對固定任務可靠，但可能不如學習系統靈活。"},{"en":"This phrase refers to traditional electronic design.","zh":"這個短語指傳統電子設計。"}],"source":"101 - ROBOTS.pdf","sourcePage":12},{"front":"in favour of","meaning":"轉而採用；支持","examples":[{"en":"Some researchers reject conventional circuits in favour of neural networks.","zh":"有些研究人員拒絕傳統電路，轉而採用神經網絡。"},{"en":"In favour of something means choosing or supporting it instead of another option.","zh":"in favour of something 指選擇或支持某事，而不是另一個選項。"},{"en":"A school may stop printed notices in favour of email messages.","zh":"學校可能停止印刷通告，轉而採用電郵訊息。"},{"en":"This phrase clearly shows preference between two choices.","zh":"這個短語清楚顯示兩個選擇之間的偏好。"},{"en":"It often appears when one old method is replaced by a newer one.","zh":"它常出現在舊方法被新方法取代時。"}],"source":"101 - ROBOTS.pdf","sourcePage":12},{"front":"messy, ad hoc arrangement","meaning":"雜亂、臨時組合式的安排","examples":[{"en":"The brain has a messy, ad hoc arrangement of neurons.","zh":"大腦有一種雜亂、臨時組合式的神經元安排。"},{"en":"A messy, ad hoc arrangement is an irregular setup formed in a practical but not perfectly planned way.","zh":"messy, ad hoc arrangement 指不規則、實用但不是完美規劃出來的配置。"},{"en":"A teacher’s desk before an exam may have a messy, ad hoc arrangement of notes, papers and pens.","zh":"考試前老師桌上可能有一種筆記、試卷和筆的雜亂臨時安排。"},{"en":"Such an arrangement can still work, even if it does not look neat or logical.","zh":"這種安排即使看起來不整齊或不合邏輯，仍可能有效。"},{"en":"This phrase contrasts natural complexity with tidy design.","zh":"這個短語把自然複雜性與整齊設計作對比。"}],"source":"101 - ROBOTS.pdf","sourcePage":12},{"front":"a real brain’s neurons","meaning":"真實大腦的神經元","examples":[{"en":"Neural networks imitate the arrangement of a real brain’s neurons.","zh":"神經網絡模仿真實大腦神經元的安排。"},{"en":"A real brain’s neurons are the nerve cells inside an actual living brain.","zh":"real brain’s neurons 指真實生命大腦中的神經細胞。"},{"en":"Scientists study a real brain’s neurons to understand learning and memory.","zh":"科學家研究真實大腦的神經元，以理解學習和記憶。"},{"en":"Artificial systems copy only some features of real neurons, not the full biological system.","zh":"人工系統只複製真實神經元的某些特徵，而不是完整生物系統。"},{"en":"This phrase distinguishes biological neurons from computer models.","zh":"這個短語把生物神經元與電腦模型分開。"}],"source":"101 - ROBOTS.pdf","sourcePage":12},{"front":"neural networks","meaning":"神經網絡","examples":[{"en":"Neural networks can teach themselves through feedback.","zh":"神經網絡可以透過反饋自行學習。"},{"en":"Neural networks are computer systems inspired by the connected structure of brain cells.","zh":"neural networks 指受腦細胞連接結構啟發的電腦系統。"},{"en":"A neural network may learn to recognise handwritten numbers after seeing many examples.","zh":"神經網絡看過許多例子後，可能學會識別手寫數字。"},{"en":"Feedback helps neural networks improve by strengthening useful connections.","zh":"反饋透過強化有用連接，幫助神經網絡改善。"},{"en":"This phrase refers to learning systems, not ordinary wiring alone.","zh":"這個短語指學習系統，而不只是普通電線。"}],"source":"101 - ROBOTS.pdf","sourcePage":12},{"front":"do not have to be programmed","meaning":"不必被編程","examples":[{"en":"Neural networks do not have to be programmed in the usual way.","zh":"神經網絡不必以通常方式被編程。"},{"en":"Do not have to be programmed means do not need every rule to be written directly by humans.","zh":"do not have to be programmed 指不需要由人直接寫入每一條規則。"},{"en":"A spelling app may learn from mistakes rather than being programmed with every possible error.","zh":"拼字應用程式可能從錯誤中學習，而不是被編程記住每個可能錯誤。"},{"en":"Learning systems can improve from examples instead of relying only on fixed instructions.","zh":"學習系統可以從例子中改善，而不只依賴固定指令。"},{"en":"This phrase shows a difference between learning and traditional programming.","zh":"這個短語顯示學習與傳統編程之間的差異。"}],"source":"101 - ROBOTS.pdf","sourcePage":12},{"front":"teach themselves","meaning":"自行學習","examples":[{"en":"Neural networks can teach themselves by using feedback signals.","zh":"神經網絡可以透過反饋訊號自行學習。"},{"en":"To teach themselves means to improve through experience without being directly taught every step.","zh":"teach themselves 指透過經驗改善，而不需每一步都被直接教導。"},{"en":"A child may teach themselves a song by listening to it many times.","zh":"孩子可能透過聽很多次自行學會一首歌。"},{"en":"A system that teaches itself can adapt when new examples appear.","zh":"能自行學習的系統可以在新例子出現時適應。"},{"en":"This phrase suggests learning through repeated feedback.","zh":"這個短語表示透過反覆反饋學習。"}],"source":"101 - ROBOTS.pdf","sourcePage":12},{"front":"a system of feedback signals","meaning":"反饋訊號系統","examples":[{"en":"Neural networks learn through a system of feedback signals.","zh":"神經網絡透過反饋訊號系統學習。"},{"en":"A system of feedback signals is a set of messages that tells a system whether its responses are useful or wrong.","zh":"system of feedback signals 指一組訊息，用來告訴系統其反應是否有用或錯誤。"},{"en":"A teacher’s comments are a feedback system that helps students improve essays.","zh":"老師評語是一種反饋系統，幫助學生改善文章。"},{"en":"Feedback signals guide learning by rewarding correct responses and weakening errors.","zh":"反饋訊號透過獎勵正確反應和削弱錯誤來引導學習。"},{"en":"This phrase explains how learning can happen without direct step-by-step rules.","zh":"這個短語解釋學習如何在沒有直接逐步規則下發生。"}],"source":"101 - ROBOTS.pdf","sourcePage":12},{"front":"reinforce electrical pathways","meaning":"強化電路通路","examples":[{"en":"Feedback signals reinforce electrical pathways that produce correct responses.","zh":"反饋訊號會強化產生正確反應的電路通路。"},{"en":"To reinforce electrical pathways means to strengthen connections that lead to successful results.","zh":"reinforce electrical pathways 指強化導致成功結果的連接。"},{"en":"A student reinforces a memory pathway by practising the same pronunciation correctly many times.","zh":"學生透過多次正確練習同一發音來強化記憶通路。"},{"en":"Connections that produce good results become stronger through repeated feedback.","zh":"產生好結果的連接會透過反覆反饋變得更強。"},{"en":"This phrase explains how a network learns from success.","zh":"這個短語解釋網絡如何從成功中學習。"}],"source":"101 - ROBOTS.pdf","sourcePage":12},{"front":"produce correct responses","meaning":"產生正確反應","examples":[{"en":"Some pathways produce correct responses.","zh":"有些通路會產生正確反應。"},{"en":"To produce correct responses means to give answers or actions that match the target.","zh":"produce correct responses 指給出符合目標的答案或行動。"},{"en":"A calculator produces correct responses when it gives the right answer to a maths problem.","zh":"計算機在數學題中給出正確答案時，就是產生正確反應。"},{"en":"Correct responses are strengthened in learning systems because they help the task succeed.","zh":"在學習系統中，正確反應會被強化，因為它們有助任務成功。"},{"en":"This phrase focuses on successful output.","zh":"這個短語著重成功輸出。"}],"source":"101 - ROBOTS.pdf","sourcePage":13},{"front":"conversely","meaning":"相反地","examples":[{"en":"Conversely, connections that produce errors are removed.","zh":"相反地，產生錯誤的連接會被移除。"},{"en":"Conversely means in the opposite way or on the other hand.","zh":"conversely 指相反地或另一方面。"},{"en":"Good sleep improves memory; conversely, poor sleep can make learning harder.","zh":"良好睡眠改善記憶；相反地，睡眠不足會令學習更困難。"},{"en":"Writers use conversely to show contrast between two related points.","zh":"作者使用 conversely 來顯示兩個相關觀點之間的對比。"},{"en":"This word helps compare opposite effects.","zh":"這個詞幫助比較相反效果。"}],"source":"101 - ROBOTS.pdf","sourcePage":13},{"front":"wipe out connections","meaning":"清除連接","examples":[{"en":"The system can wipe out connections that produce errors.","zh":"系統可以清除產生錯誤的連接。"},{"en":"To wipe out connections means to remove or eliminate links completely.","zh":"wipe out connections 指完全移除或消除連結。"},{"en":"A teacher may ask students to wipe out wrong links in a matching exercise and try again.","zh":"老師可能要求學生清除配對練習中的錯誤連線，然後再試。"},{"en":"Removing bad connections helps a learning system avoid repeating mistakes.","zh":"移除不良連接幫助學習系統避免重複錯誤。"},{"en":"This phrase suggests strong removal, not a small adjustment.","zh":"這個短語表示強力移除，而不是小調整。"}],"source":"101 - ROBOTS.pdf","sourcePage":13},{"front":"eventually","meaning":"最終","examples":[{"en":"Eventually, the network wires itself into a useful system.","zh":"最終，網絡自行連接成一個有用系統。"},{"en":"Eventually means after some time or after a process has developed.","zh":"eventually 指經過一段時間或過程發展之後。"},{"en":"A student may struggle at first, but eventually the grammar rule becomes natural.","zh":"學生一開始可能吃力，但最終文法規則會變得自然。"},{"en":"This word shows that the result does not happen immediately.","zh":"這個詞顯示結果不是立即發生。"},{"en":"It often follows a period of practice, change or waiting.","zh":"它常跟在練習、改變或等待一段時間之後。"}],"source":"101 - ROBOTS.pdf","sourcePage":13},{"front":"the net wires itself","meaning":"網絡自行連接成","examples":[{"en":"The net wires itself into a system that can recognise patterns.","zh":"網絡自行連接成一個能識別模式的系統。"},{"en":"The net wires itself means the neural network forms its own useful connections through learning.","zh":"net wires itself 指神經網絡透過學習形成自己的有用連接。"},{"en":"A learning app improves when its internal system adjusts itself after many student answers.","zh":"學習應用程式在許多學生答案後調整內部系統時，就會改善。"},{"en":"Self-wiring allows a network to become organised without every connection being planned by a human.","zh":"自行連接讓網絡變得有組織，而不用每個連接都由人規劃。"},{"en":"This phrase describes automatic organisation inside a learning system.","zh":"這個短語描述學習系統內部的自動組織。"}],"source":"101 - ROBOTS.pdf","sourcePage":13},{"front":"pronounce certain words","meaning":"讀出某些字詞","examples":[{"en":"A neural network may learn to pronounce certain words.","zh":"神經網絡可能學會讀出某些字詞。"},{"en":"To pronounce certain words means to say particular words with the correct sounds.","zh":"pronounce certain words 指用正確聲音說出特定字詞。"},{"en":"Language learners often practise to pronounce certain words that are difficult in English.","zh":"語言學習者常練習讀出某些英文中困難的字詞。"},{"en":"Feedback helps learners correct sounds that are unclear or wrong.","zh":"反饋幫助學習者改正不清楚或錯誤的聲音。"},{"en":"This phrase focuses on spoken form, not written meaning.","zh":"這個短語著重口語形式，而不是書面意思。"}],"source":"101 - ROBOTS.pdf","sourcePage":13},{"front":"distinguish certain shapes","meaning":"分辨某些形狀","examples":[{"en":"A neural network may learn to distinguish certain shapes.","zh":"神經網絡可能學會分辨某些形狀。"},{"en":"To distinguish certain shapes means to tell particular shapes apart from others.","zh":"distinguish certain shapes 指把特定形狀與其他形狀區分開。"},{"en":"Young children learn to distinguish circles, squares and triangles in class.","zh":"年幼孩子在課堂上學習分辨圓形、正方形和三角形。"},{"en":"A robot must distinguish shapes if it needs to pick the right object from a box.","zh":"如果機械人需要從箱中拿起正確物件，就必須分辨形狀。"},{"en":"This phrase focuses on recognising differences.","zh":"這個短語著重識別差異。"}],"source":"101 - ROBOTS.pdf","sourcePage":13},{"front":"in other areas","meaning":"在其他範疇","examples":[{"en":"In other areas, researchers are studying the relationship between people and robots.","zh":"在其他範疇，研究人員正在研究人與機械人的關係。"},{"en":"In other areas means in different fields, topics or parts of the research.","zh":"in other areas 指在不同領域、主題或研究部分中。"},{"en":"A school may be strong in science, while in other areas it still needs improvement.","zh":"一所學校在科學方面可能很強，而在其他範疇仍需改善。"},{"en":"This phrase moves the discussion to another part of a wider subject.","zh":"這個短語把討論轉向較大主題中的另一部分。"},{"en":"It helps organise writing by changing focus.","zh":"它透過改變焦點來幫助組織文章。"}],"source":"101 - ROBOTS.pdf","sourcePage":13},{"front":"struggle to fashion","meaning":"努力塑造","examples":[{"en":"Researchers are struggling to fashion a more natural relationship with robots.","zh":"研究人員正努力塑造與機械人更自然的關係。"},{"en":"To struggle to fashion something means to find it difficult to create or shape it.","zh":"struggle to fashion something 指難以創造或塑造某事物。"},{"en":"A teacher may struggle to fashion a lesson that works for both beginners and advanced students.","zh":"老師可能努力設計一堂同時適合初學者和高階學生的課。"},{"en":"Creating natural human-robot interaction is hard because people expect social signals.","zh":"創造自然的人機互動很難，因為人們期待社交訊號。"},{"en":"This phrase shows effort and difficulty in building something new.","zh":"這個短語顯示建立新事物時的努力和困難。"}],"source":"101 - ROBOTS.pdf","sourcePage":13},{"front":"a more natural relationship","meaning":"更自然的關係","examples":[{"en":"Researchers want a more natural relationship between people and robots.","zh":"研究人員希望人與機械人之間有更自然的關係。"},{"en":"A more natural relationship is an interaction that feels comfortable, normal and easy.","zh":"more natural relationship 指令人感到舒服、正常和容易的互動。"},{"en":"A helpful robot in a hospital needs a natural relationship with patients so they do not feel afraid.","zh":"醫院中的輔助機械人需要與病人有自然關係，讓他們不會害怕。"},{"en":"Better communication, facial expression and timing can make interaction feel more natural.","zh":"更好的溝通、面部表情和時機可以令互動感覺更自然。"},{"en":"This phrase focuses on human comfort.","zh":"這個短語著重人類的舒適感。"}],"source":"101 - ROBOTS.pdf","sourcePage":13},{"front":"in the expectation that","meaning":"預期","examples":[{"en":"Researchers are preparing robots in the expectation that they will perform human tasks.","zh":"研究人員正在準備機械人，預期它們會執行人類任務。"},{"en":"In the expectation that means because people believe or hope something will happen.","zh":"in the expectation that 指因為人們相信或希望某事會發生。"},{"en":"A school may train teachers in new software in the expectation that online lessons will continue.","zh":"學校可能培訓老師使用新軟件，預期網上課堂會繼續。"},{"en":"Planning based on expectation can be useful, but the future may still change.","zh":"根據預期規劃可以有用，但未來仍可能改變。"},{"en":"This phrase links preparation with a predicted future.","zh":"這個短語把準備與預測中的未來連繫起來。"}],"source":"101 - ROBOTS.pdf","sourcePage":14},{"front":"take on tasks","meaning":"承擔任務","examples":[{"en":"Machines may someday take on tasks now done by humans.","zh":"機器有一天可能承擔現在由人類完成的任務。"},{"en":"To take on tasks means to accept or begin doing work or responsibilities.","zh":"take on tasks 指接受或開始做某些工作或責任。"},{"en":"A new assistant may take on tasks such as answering emails and arranging meetings.","zh":"新助理可能承擔回覆電郵和安排會議等任務。"},{"en":"When machines take on routine tasks, people may focus on care, judgement or creativity.","zh":"當機器承擔例行任務，人們可能集中於照顧、判斷或創意。"},{"en":"This phrase suggests assuming responsibility for work.","zh":"這個短語表示承擔工作的責任。"}],"source":"101 - ROBOTS.pdf","sourcePage":14},{"front":"nursing homes","meaning":"安老院","examples":[{"en":"Robots may eventually perform tasks in nursing homes.","zh":"機械人最終可能在安老院執行任務。"},{"en":"Nursing homes are places where elderly or vulnerable people live and receive care.","zh":"nursing homes 指長者或弱勢人士居住並接受照顧的地方。"},{"en":"Staff in nursing homes help residents eat, wash, move and take medicine.","zh":"安老院職員幫助住客進食、洗澡、移動和服藥。"},{"en":"Robots may support nursing homes by carrying supplies or reminding residents about routines.","zh":"機械人可能透過運送用品或提醒住客日常事項來支援安老院。"},{"en":"This phrase refers to care facilities, not hospitals for short-term treatment.","zh":"這個短語指照護設施，而不是短期治療醫院。"}],"source":"101 - ROBOTS.pdf","sourcePage":14},{"front":"particularly important","meaning":"尤其重要","examples":[{"en":"This research is particularly important in Japan.","zh":"這項研究在日本尤其重要。"},{"en":"Particularly important means especially important compared with other cases.","zh":"particularly important 指與其他情況相比尤其重要。"},{"en":"Clear signs are particularly important in hospitals because visitors may be worried or lost.","zh":"清楚標示在醫院尤其重要，因為訪客可能擔心或迷路。"},{"en":"A topic becomes particularly important when it affects many people or urgent needs.","zh":"當一個議題影響很多人或迫切需要時，就變得尤其重要。"},{"en":"This phrase highlights special significance.","zh":"這個短語突出特殊重要性。"}],"source":"101 - ROBOTS.pdf","sourcePage":14},{"front":"elderly citizens","meaning":"長者市民","examples":[{"en":"The percentage of elderly citizens is increasing in Japan.","zh":"日本長者市民的比例正在增加。"},{"en":"Elderly citizens are older members of a country or community.","zh":"elderly citizens 指一個國家或社區中的年長成員。"},{"en":"Public transport should consider elderly citizens who may need seats, lifts and clear signs.","zh":"公共交通應考慮可能需要座位、升降機和清楚標示的長者市民。"},{"en":"More elderly citizens can increase demand for healthcare and care workers.","zh":"更多長者市民會增加醫療和照護人員需求。"},{"en":"This phrase is more formal than “old people”.","zh":"這個短語比 old people 較正式。"}],"source":"101 - ROBOTS.pdf","sourcePage":14},{"front":"rapidly increasing","meaning":"迅速增加","examples":[{"en":"The percentage of elderly citizens is rapidly increasing.","zh":"長者市民的比例正在迅速增加。"},{"en":"Rapidly increasing means growing quickly over a short period of time.","zh":"rapidly increasing 指在短時間內快速增長。"},{"en":"A school may need more classrooms if student numbers are rapidly increasing.","zh":"如果學生人數迅速增加，學校可能需要更多課室。"},{"en":"Rapid growth can create pressure on services and planning.","zh":"快速增長可以對服務和規劃造成壓力。"},{"en":"This phrase emphasises speed of change.","zh":"這個短語強調變化速度。"}],"source":"101 - ROBOTS.pdf","sourcePage":14},{"front":"a face robot","meaning":"臉部機械人","examples":[{"en":"Researchers in Tokyo have created a face robot.","zh":"東京的研究人員創造了一個臉部機械人。"},{"en":"A face robot is a robot designed to show or read facial expressions.","zh":"face robot 指設計用來展示或讀取面部表情的機械人。"},{"en":"A laboratory may build a face robot to study how people react to machine emotions.","zh":"實驗室可能製造臉部機械人，以研究人們如何回應機器情緒。"},{"en":"Face robots can help researchers test whether machines can communicate socially.","zh":"臉部機械人可以幫助研究人員測試機器能否進行社交溝通。"},{"en":"This phrase refers to a robot focused on facial interaction.","zh":"這個短語指專注於面部互動的機械人。"}],"source":"101 - ROBOTS.pdf","sourcePage":14},{"front":"life-size","meaning":"真人大小的","examples":[{"en":"The prototype is a life-size model of a female head.","zh":"該原型是一個真人大小的女性頭部模型。"},{"en":"Life-size means the same size as the real person, animal or object.","zh":"life-size 指與真實人、動物或物件相同大小。"},{"en":"A museum may display a life-size model of a dinosaur to help visitors imagine its scale.","zh":"博物館可能展出真人大小的恐龍模型，幫助訪客想像其規模。"},{"en":"Life-size models feel more realistic because people can compare them with their own bodies.","zh":"真人大小的模型較真實，因為人們可以用自己身體比較。"},{"en":"This phrase describes size, not whether something is alive.","zh":"這個短語描述尺寸，而不是某物是否有生命。"}],"source":"101 - ROBOTS.pdf","sourcePage":14},{"front":"a soft plastic model","meaning":"柔軟塑膠模型","examples":[{"en":"The robot is a soft plastic model of a female head.","zh":"這個機械人是一個女性頭部的柔軟塑膠模型。"},{"en":"A soft plastic model is a shaped copy made from flexible plastic material.","zh":"soft plastic model 指用有彈性的塑膠材料製成的造型複製品。"},{"en":"Medical students may practise on a soft plastic model before treating real patients.","zh":"醫科學生可能先在柔軟塑膠模型上練習，再治療真實病人。"},{"en":"Soft materials can make a robot face less frightening and more human-like.","zh":"柔軟材料可以令機械人臉部較不嚇人、更像人類。"},{"en":"This phrase describes both material and form.","zh":"這個短語同時描述材料和形態。"}],"source":"101 - ROBOTS.pdf","sourcePage":14},{"front":"embedded in","meaning":"嵌入","examples":[{"en":"A video camera is embedded in the robot’s left eye.","zh":"一部攝錄機嵌入機械人的左眼。"},{"en":"Embedded in something means fixed inside it as part of its structure.","zh":"embedded in something 指固定在某物內部，成為其結構一部分。"},{"en":"A sensor may be embedded in a smartwatch to measure heart rate.","zh":"感應器可能嵌入智能手錶，用來量度心率。"},{"en":"Embedded devices are often hidden but still perform important functions.","zh":"嵌入式裝置常被隱藏，但仍執行重要功能。"},{"en":"This phrase means placed inside, not just attached on the surface.","zh":"這個短語指放在內部，而不只是貼在表面。"}],"source":"101 - ROBOTS.pdf","sourcePage":14},{"front":"as a prototype","meaning":"作為原型","examples":[{"en":"The face robot was created as a prototype.","zh":"這個臉部機械人是作為原型被創造出來。"},{"en":"As a prototype means as an early test version of a product or idea.","zh":"as a prototype 指作為產品或想法的早期測試版本。"},{"en":"A company may build a prototype of a new bicycle before selling it.","zh":"公司可能在出售前先製作新單車原型。"},{"en":"Prototypes help designers discover problems before full production.","zh":"原型幫助設計師在全面生產前發現問題。"},{"en":"This phrase shows that something is experimental, not the final version.","zh":"這個短語顯示某物仍屬實驗性，不是最終版本。"}],"source":"101 - ROBOTS.pdf","sourcePage":15},{"front":"feel comfortable around","meaning":"在……身邊感到自在","examples":[{"en":"The researchers want robots that people feel comfortable around.","zh":"研究人員希望製造令人們在其身邊感到自在的機械人。"},{"en":"To feel comfortable around someone or something means to feel relaxed and not afraid near it.","zh":"feel comfortable around someone or something 指在某人或某物身邊感到放鬆而不害怕。"},{"en":"Patients feel more comfortable around nurses who speak gently and explain procedures.","zh":"病人在語氣溫和並解釋程序的護士身邊會感到較自在。"},{"en":"If people feel comfortable around robots, they may accept help from them more easily.","zh":"如果人們在機械人身邊感到自在，就可能更容易接受其幫助。"},{"en":"This phrase focuses on emotional ease.","zh":"這個短語著重情感上的舒適。"}],"source":"101 - ROBOTS.pdf","sourcePage":15},{"front":"concentrate on","meaning":"集中研究","examples":[{"en":"The researchers are concentrating on the face.","zh":"研究人員正集中研究臉部。"},{"en":"To concentrate on something means to give most attention to it.","zh":"concentrate on something 指把大部分注意力放在某事上。"},{"en":"A student may concentrate on pronunciation before preparing a full speech.","zh":"學生可能先集中練習發音，再準備完整演講。"},{"en":"Focusing on one area helps researchers solve a complex problem step by step.","zh":"集中於一個範疇有助研究人員逐步解決複雜問題。"},{"en":"This phrase shows deliberate focus.","zh":"這個短語顯示有意識的專注。"}],"source":"101 - ROBOTS.pdf","sourcePage":15},{"front":"facial expressions","meaning":"面部表情","examples":[{"en":"Facial expressions transfer emotional messages.","zh":"面部表情傳遞情感訊息。"},{"en":"Facial expressions are movements or positions of the face that show feelings.","zh":"facial expressions 指顯示感受的臉部動作或狀態。"},{"en":"A smile, frown or raised eyebrow can be a facial expression.","zh":"微笑、皺眉或揚眉都可以是面部表情。"},{"en":"People use facial expressions to understand whether someone is happy, worried or angry.","zh":"人們使用面部表情理解某人是開心、擔心還是生氣。"},{"en":"This phrase connects the face with emotional communication.","zh":"這個短語把臉部與情感溝通連繫起來。"}],"source":"101 - ROBOTS.pdf","sourcePage":15},{"front":"transfer emotional messages","meaning":"傳遞情感訊息","examples":[{"en":"Facial expressions can transfer emotional messages.","zh":"面部表情可以傳遞情感訊息。"},{"en":"To transfer emotional messages means to communicate feelings from one person to another.","zh":"transfer emotional messages 指把感受從一個人傳達給另一個人。"},{"en":"A worried look can transfer an emotional message before anyone speaks.","zh":"擔心的表情可以在人開口前傳遞情感訊息。"},{"en":"If a robot can transfer emotional messages, people may find it easier to interact with.","zh":"如果機械人能傳遞情感訊息，人們可能更容易與它互動。"},{"en":"This phrase shows communication without words.","zh":"這個短語顯示非語言溝通。"}],"source":"101 - ROBOTS.pdf","sourcePage":15},{"front":"read those messages","meaning":"讀懂那些訊息","examples":[{"en":"People read emotional messages by interpreting expressions.","zh":"人們透過解讀表情來讀懂情感訊息。"},{"en":"To read those messages means to understand the meaning behind signs, expressions or signals.","zh":"read those messages 指理解跡象、表情或訊號背後的意思。"},{"en":"A teacher may read a student’s tired face and know the class needs a short break.","zh":"老師可能讀懂學生疲倦的表情，知道班上需要短暫休息。"},{"en":"Reading emotional messages helps people respond kindly and appropriately.","zh":"讀懂情感訊息幫助人們友善並適當地回應。"},{"en":"This phrase means understand, not literally read words.","zh":"這個短語指理解，而不是字面上閱讀文字。"}],"source":"101 - ROBOTS.pdf","sourcePage":15},{"front":"interpret expressions","meaning":"解讀表情","examples":[{"en":"People interpret expressions to understand emotions.","zh":"人們解讀表情來理解情緒。"},{"en":"To interpret expressions means to decide what feelings a face is showing.","zh":"interpret expressions 指判斷臉部正在顯示甚麼感受。"},{"en":"A nurse may interpret a patient’s expression to see whether they are in pain.","zh":"護士可能解讀病人的表情，以了解他是否疼痛。"},{"en":"Misinterpreting expressions can lead to misunderstanding in communication.","zh":"錯誤解讀表情可能導致溝通誤會。"},{"en":"This phrase focuses on reading meaning from facial signals.","zh":"這個短語著重從面部訊號讀出意思。"}],"source":"101 - ROBOTS.pdf","sourcePage":15},{"front":"detect emotions","meaning":"偵測情緒","examples":[{"en":"The robot is designed to detect emotions.","zh":"這部機械人設計用來偵測情緒。"},{"en":"To detect emotions means to notice or identify feelings such as happiness, anger or sadness.","zh":"detect emotions 指注意或識別快樂、憤怒或悲傷等感受。"},{"en":"A teacher may detect emotions in students by watching their faces and body language.","zh":"老師可能透過觀察學生表情和身體語言偵測情緒。"},{"en":"Robots need sensors and software to detect emotions from facial cues.","zh":"機械人需要感應器和軟件，才能從面部線索偵測情緒。"},{"en":"This phrase focuses on recognising feelings, not feeling them personally.","zh":"這個短語著重識別感受，而不是親自感受。"}],"source":"101 - ROBOTS.pdf","sourcePage":15},{"front":"the person it is looking at","meaning":"它正在觀看的人","examples":[{"en":"The robot detects emotions in the person it is looking at.","zh":"機械人偵測它正在觀看的人身上的情緒。"},{"en":"The person it is looking at means the person currently facing the robot’s camera or sensors.","zh":"person it is looking at 指目前面向機械人攝影機或感應器的人。"},{"en":"A security camera records the person it is looking at when someone stands in front of it.","zh":"當有人站在保安攝影機前，它會記錄正在觀看的人。"},{"en":"A robot must first identify the person it is observing before responding to their expression.","zh":"機械人在回應表情前，必須先識別它正在觀察的人。"},{"en":"This phrase specifies the target of the robot’s attention.","zh":"這個短語指出機械人注意的對象。"}],"source":"101 - ROBOTS.pdf","sourcePage":15},{"front":"sense changes in","meaning":"感應……的變化","examples":[{"en":"The robot senses changes in the arrangement of facial features.","zh":"機械人感應面部特徵排列的變化。"},{"en":"To sense changes in something means to detect that it has become different.","zh":"sense changes in something 指偵測到某物變得不同。"},{"en":"A thermostat senses changes in room temperature and turns heating on or off.","zh":"恆溫器感應室溫變化，然後開關暖氣。"},{"en":"Sensing changes allows machines to respond to new conditions.","zh":"感應變化讓機器能回應新條件。"},{"en":"This phrase links detection with reaction.","zh":"這個短語把偵測與反應連繫起來。"}],"source":"101 - ROBOTS.pdf","sourcePage":15},{"front":"spatial arrangement","meaning":"空間排列","examples":[{"en":"The robot analyses the spatial arrangement of facial features.","zh":"機械人分析面部特徵的空間排列。"},{"en":"Spatial arrangement means how things are positioned in relation to one another in space.","zh":"spatial arrangement 指事物在空間中彼此如何放置。"},{"en":"A classroom’s spatial arrangement affects whether students can see the board clearly.","zh":"課室的空間排列會影響學生是否能清楚看見黑板。"},{"en":"Small changes in facial arrangement can signal different emotions.","zh":"臉部排列的小變化可以表示不同情緒。"},{"en":"This phrase focuses on position and distance.","zh":"這個短語著重位置和距離。"}],"source":"101 - ROBOTS.pdf","sourcePage":16},{"front":"eyebrows","meaning":"眉毛","examples":[{"en":"Eyebrows are part of the facial arrangement the robot analyses.","zh":"眉毛是機械人分析的面部排列一部分。"},{"en":"Eyebrows are the lines of hair above the eyes that help show expression.","zh":"eyebrows 指眼睛上方的毛髮線條，有助顯示表情。"},{"en":"Raised eyebrows may show surprise, while lowered eyebrows may show anger or concentration.","zh":"揚起眉毛可能表示驚訝，而壓低眉毛可能表示憤怒或專注。"},{"en":"Robots read eyebrows because their position can change the meaning of a face.","zh":"機械人讀取眉毛，因為其位置可以改變臉部意思。"},{"en":"This word refers to a small but important facial feature.","zh":"這個詞指細小但重要的面部特徵。"}],"source":"101 - ROBOTS.pdf","sourcePage":16},{"front":"compare configurations with","meaning":"將構型與……比較","examples":[{"en":"The robot compares configurations with a database.","zh":"機械人將構型與資料庫比較。"},{"en":"To compare configurations with something means to check one arrangement against stored examples.","zh":"compare configurations with something 指把一種排列與已儲存例子作比較。"},{"en":"A phone may compare a fingerprint pattern with saved fingerprints before unlocking.","zh":"手機解鎖前可能把指紋模式與已儲存指紋比較。"},{"en":"Comparison helps a system decide which known example is most similar.","zh":"比較幫助系統判斷哪個已知例子最相似。"},{"en":"This phrase describes matching current data with reference data.","zh":"這個短語描述把目前數據與參考數據配對。"}],"source":"101 - ROBOTS.pdf","sourcePage":16},{"front":"configurations","meaning":"構型；配置","examples":[{"en":"The robot studies facial configurations to guess emotions.","zh":"機械人研究面部構型來猜測情緒。"},{"en":"Configurations are particular arrangements of parts in a system or object.","zh":"configurations 指系統或物件中各部分的特定排列方式。"},{"en":"A classroom can have different configurations, such as rows, groups or a circle.","zh":"課室可以有不同配置，例如排成列、小組或圓圈。"},{"en":"Changing a configuration can change how the whole system works or appears.","zh":"改變配置可以改變整個系統如何運作或呈現。"},{"en":"This word focuses on how parts are arranged.","zh":"這個詞著重各部分如何排列。"}],"source":"101 - ROBOTS.pdf","sourcePage":16},{"front":"a database of","meaning":"……的資料庫","examples":[{"en":"The robot uses a database of standard facial expressions.","zh":"機械人使用標準面部表情的資料庫。"},{"en":"A database of something is an organised collection of information about that thing.","zh":"database of something 指有系統地收集關於某事物的資訊。"},{"en":"A library uses a database of books to help readers find titles quickly.","zh":"圖書館使用書籍資料庫，幫助讀者快速找書。"},{"en":"Databases help machines compare new information with stored examples.","zh":"資料庫幫助機器把新資訊與已儲存例子比較。"},{"en":"This phrase refers to structured stored information.","zh":"這個短語指有結構地儲存的資訊。"}],"source":"101 - ROBOTS.pdf","sourcePage":16},{"front":"standard facial expressions","meaning":"標準面部表情","examples":[{"en":"The database contains standard facial expressions.","zh":"資料庫包含標準面部表情。"},{"en":"Standard facial expressions are commonly recognised face patterns linked with emotions.","zh":"standard facial expressions 指常被辨認、與情緒有關的面部模式。"},{"en":"A smile is a standard facial expression often connected with happiness.","zh":"微笑是一種常與快樂相關的標準面部表情。"},{"en":"Robots compare new faces with standard expressions to guess emotional meaning.","zh":"機械人把新臉孔與標準表情比較，以猜測情緒意思。"},{"en":"This phrase refers to typical expression patterns, not every possible face.","zh":"這個短語指典型表情模式，而不是每一種可能臉孔。"}],"source":"101 - ROBOTS.pdf","sourcePage":16},{"front":"guess the emotion","meaning":"猜測情緒","examples":[{"en":"The robot guesses the emotion from the person’s face.","zh":"機械人從那人的臉上猜測情緒。"},{"en":"To guess the emotion means to estimate what someone is feeling from available clues.","zh":"guess the emotion 指根據可用線索估計某人正在感受甚麼。"},{"en":"A teacher may guess a student’s emotion from their silence and facial expression.","zh":"老師可能根據學生的沉默和面部表情猜測情緒。"},{"en":"Emotion guessing can be wrong because people may hide or mix feelings.","zh":"猜測情緒可能錯誤，因為人們可能隱藏或混合感受。"},{"en":"This phrase suggests uncertain interpretation, not perfect knowledge.","zh":"這個短語表示不確定的解讀，而不是完美知識。"}],"source":"101 - ROBOTS.pdf","sourcePage":16},{"front":"an ensemble of","meaning":"一組","examples":[{"en":"The robot uses an ensemble of tiny pressure pads.","zh":"機械人使用一組微型壓力墊。"},{"en":"An ensemble of things is a group of parts working together.","zh":"ensemble of things 指一起運作的一組部件。"},{"en":"A music ensemble works because different instruments combine their sounds.","zh":"音樂合奏能成功，是因為不同樂器結合聲音。"},{"en":"A group of small parts can create a complex movement when they act together.","zh":"一組小部件一起行動時，可以創造複雜動作。"},{"en":"This phrase presents many parts as a coordinated set.","zh":"這個短語把多個部分呈現為協調組合。"}],"source":"101 - ROBOTS.pdf","sourcePage":16},{"front":"tiny pressure pads","meaning":"微型壓力墊","examples":[{"en":"Tiny pressure pads adjust the robot’s plastic face.","zh":"微型壓力墊調整機械人的塑膠臉部。"},{"en":"Tiny pressure pads are small devices that respond to pressure or create controlled movement.","zh":"tiny pressure pads 指會對壓力作出反應或產生受控動作的小型裝置。"},{"en":"A medical training model may use tiny pressure pads to simulate touch or movement.","zh":"醫療訓練模型可能使用微型壓力墊來模擬觸感或動作。"},{"en":"Small pads can make slight changes in a robot face, creating different expressions.","zh":"小墊可以令機械人臉部產生細微變化，創造不同表情。"},{"en":"This phrase refers to small mechanical parts used for fine control.","zh":"這個短語指用於精細控制的小型機械部件。"}],"source":"101 - ROBOTS.pdf","sourcePage":16},{"front":"adjust its plastic face","meaning":"調整它的塑膠臉部","examples":[{"en":"The robot adjusts its plastic face into an emotional expression.","zh":"機械人把它的塑膠臉部調整成情感表情。"},{"en":"To adjust its plastic face means to move or change the artificial face slightly.","zh":"adjust its plastic face 指稍微移動或改變人工臉部。"},{"en":"A toy robot may adjust its face by moving its eyebrows and mouth.","zh":"玩具機械人可能透過移動眉毛和嘴巴來調整臉部。"},{"en":"Adjusting the face helps a robot respond in a way humans can recognise.","zh":"調整臉部幫助機械人以人類能識別的方式回應。"},{"en":"This phrase shows physical change used for communication.","zh":"這個短語顯示用於溝通的身體變化。"}],"source":"101 - ROBOTS.pdf","sourcePage":16},{"front":"an appropriate emotional response","meaning":"適當的情感反應","examples":[{"en":"The robot produces an appropriate emotional response.","zh":"機械人產生適當的情感反應。"},{"en":"An appropriate emotional response is a reaction that matches the feeling or situation.","zh":"appropriate emotional response 指與感受或情況相配的反應。"},{"en":"A friend gives an appropriate emotional response by speaking gently when someone is sad.","zh":"當某人悲傷時，朋友溫柔說話就是適當的情感反應。"},{"en":"If a robot responds happily to a person’s fear, the response is not appropriate.","zh":"如果機械人對人的恐懼作出快樂回應，該反應就不適當。"},{"en":"This phrase focuses on matching emotion to context.","zh":"這個短語著重情緒與語境相配。"}],"source":"101 - ROBOTS.pdf","sourcePage":17},{"front":"take a different approach","meaning":"採取不同方法","examples":[{"en":"Other labs are taking a different approach to robot intelligence.","zh":"其他實驗室正對機械人智能採取不同方法。"},{"en":"To take a different approach means to use another method or way of thinking.","zh":"take a different approach 指使用另一種方法或思考方式。"},{"en":"A teacher may take a different approach if students do not understand the first explanation.","zh":"如果學生不理解第一個解釋，老師可能採取不同方法。"},{"en":"Different approaches can solve problems that one method cannot solve.","zh":"不同方法可以解決單一方法無法解決的問題。"},{"en":"This phrase introduces a contrast in method.","zh":"這個短語引入方法上的對比。"}],"source":"101 - ROBOTS.pdf","sourcePage":17},{"front":"mimic human intelligence","meaning":"模仿人類智能","examples":[{"en":"Some researchers do not try to mimic human intelligence.","zh":"有些研究人員不嘗試模仿人類智能。"},{"en":"To mimic human intelligence means to imitate the way people think, learn or solve problems.","zh":"mimic human intelligence 指模仿人類思考、學習或解決問題的方式。"},{"en":"A chess program may mimic one part of human intelligence by choosing strategic moves.","zh":"棋類程式可能透過選擇策略性走法來模仿部分人類智能。"},{"en":"Some systems solve tasks well without copying the human brain directly.","zh":"有些系統不用直接複製人腦，也能很好地完成任務。"},{"en":"This phrase focuses on imitation of human thinking.","zh":"這個短語著重模仿人類思維。"}],"source":"101 - ROBOTS.pdf","sourcePage":17},{"front":"mimic human emotions","meaning":"模仿人類情感","examples":[{"en":"Some robots do not try to mimic human emotions.","zh":"有些機械人不嘗試模仿人類情感。"},{"en":"To mimic human emotions means to copy the outward signs of feelings such as joy or sadness.","zh":"mimic human emotions 指模仿快樂或悲傷等感受的外在表現。"},{"en":"A robot may mimic human emotions by smiling when it gives good news.","zh":"機械人可能在報告好消息時微笑，來模仿人類情感。"},{"en":"Mimicking emotion can make interaction easier, but it does not prove the machine feels anything.","zh":"模仿情感可以令互動更容易，但不證明機器真的有感受。"},{"en":"This phrase focuses on imitation, not real emotion.","zh":"這個短語著重模仿，而不是真實情感。"}],"source":"101 - ROBOTS.pdf","sourcePage":17},{"front":"move away from","meaning":"遠離；不再採用","examples":[{"en":"Computer design has moved away from one central mainframe.","zh":"電腦設計已遠離單一中央大型電腦。"},{"en":"To move away from something means to stop relying on it and choose another direction.","zh":"move away from something 指停止依賴某事物並選擇另一方向。"},{"en":"Schools may move away from paper notices and use online messages instead.","zh":"學校可能不再採用紙本通告，改用網上訊息。"},{"en":"Moving away from one system often happens when newer options are more flexible.","zh":"當新選項更靈活時，人們常會遠離舊系統。"},{"en":"This phrase shows a shift in method or preference.","zh":"這個短語顯示方法或偏好的轉變。"}],"source":"101 - ROBOTS.pdf","sourcePage":17},{"front":"a central mainframe","meaning":"中央大型電腦","examples":[{"en":"Older computer design often relied on one central mainframe.","zh":"較舊的電腦設計常依賴一部中央大型電腦。"},{"en":"A central mainframe is a large main computer that handles processing for many users or terminals.","zh":"central mainframe 指為許多使用者或終端機處理工作的主要大型電腦。"},{"en":"A university once might have used a central mainframe for all student records.","zh":"大學過去可能使用中央大型電腦處理所有學生紀錄。"},{"en":"If everything depends on one mainframe, failure in that system can affect everyone.","zh":"如果所有東西都依賴一部大型電腦，該系統故障會影響所有人。"},{"en":"This phrase refers to a centralised computing model.","zh":"這個短語指集中式電腦模式。"}],"source":"101 - ROBOTS.pdf","sourcePage":17},{"front":"in favour of myriad individual workstations","meaning":"轉而採用無數獨立工作站","examples":[{"en":"Computer design moved away from mainframes in favour of myriad individual workstations.","zh":"電腦設計遠離大型主機，轉而採用無數獨立工作站。"},{"en":"In favour of myriad individual workstations means choosing many separate computers instead of one central machine.","zh":"in favour of myriad individual workstations 指選擇許多獨立電腦，而不是一部中央機器。"},{"en":"Offices moved in this direction when each worker began using a personal computer.","zh":"當每名員工開始使用個人電腦時，辦公室就朝這方向轉變。"},{"en":"Many workstations allow tasks to be shared and handled more flexibly.","zh":"許多工作站讓任務更靈活地被分擔和處理。"},{"en":"This phrase contrasts central control with distributed computing.","zh":"這個短語把中央控制與分散式運算作對比。"}],"source":"101 - ROBOTS.pdf","sourcePage":17},{"front":"myriad individual workstations","meaning":"無數獨立工作站","examples":[{"en":"Modern computing uses myriad individual workstations.","zh":"現代運算使用無數獨立工作站。"},{"en":"Myriad individual workstations means a very large number of separate computers or terminals.","zh":"myriad individual workstations 指數量非常多的獨立電腦或終端機。"},{"en":"A university computer room may contain many individual workstations for students.","zh":"大學電腦室可能有許多供學生使用的獨立工作站。"},{"en":"Distributed workstations can solve parts of a problem at the same time.","zh":"分散式工作站可以同時解決問題的不同部分。"},{"en":"This phrase emphasises many separate working units.","zh":"這個短語強調許多分開運作的單位。"}],"source":"101 - ROBOTS.pdf","sourcePage":17},{"front":"single processors","meaning":"單一處理器","examples":[{"en":"Single processors have been replaced by arrays of smaller units.","zh":"單一處理器已被一系列較小單位取代。"},{"en":"Single processors are individual computer chips or units that handle processing tasks alone.","zh":"single processors 指單獨處理運算任務的個別電腦晶片或單位。"},{"en":"An old computer may depend heavily on one single processor to do most calculations.","zh":"舊電腦可能高度依賴一個單一處理器完成大部分計算。"},{"en":"Using many smaller units can make a system faster or more flexible than one processor alone.","zh":"使用多個較小單位可以令系統比單一處理器更快或更靈活。"},{"en":"This phrase contrasts one central unit with multiple smaller units.","zh":"這個短語把一個中央單位與多個小單位作對比。"}],"source":"101 - ROBOTS.pdf","sourcePage":17},{"front":"be replaced by arrays of","meaning":"被一系列……取代","examples":[{"en":"Single processors have been replaced by arrays of smaller units.","zh":"單一處理器已被一系列較小單位取代。"},{"en":"To be replaced by arrays of something means to be substituted with organised groups of many parts.","zh":"be replaced by arrays of something 指被許多有組織部件組成的群組取代。"},{"en":"One large classroom screen may be replaced by arrays of tablets for group learning.","zh":"一個大型課室螢幕可能被一系列平板電腦取代，用於小組學習。"},{"en":"Arrays of smaller parts can divide work and reduce dependence on one unit.","zh":"一系列較小部件可以分擔工作，減少對單一單位的依賴。"},{"en":"This phrase shows replacement by many coordinated components.","zh":"這個短語顯示由多個協調部件取代。"}],"source":"101 - ROBOTS.pdf","sourcePage":17},{"front":"break a big problem into parts","meaning":"將大問題拆成部分","examples":[{"en":"Arrays of smaller units can break a big problem into parts.","zh":"一系列較小單位可以將大問題拆成部分。"},{"en":"To break a big problem into parts means to divide it into smaller tasks that are easier to solve.","zh":"break a big problem into parts 指把大問題分成較小、較容易解決的任務。"},{"en":"A student can break a long essay into planning, writing, editing and proofreading.","zh":"學生可以把長文章拆成計劃、寫作、修改和校對。"},{"en":"Dividing a problem makes it less overwhelming and easier to manage.","zh":"把問題分開會令它較不令人望而生畏，也較易管理。"},{"en":"This phrase describes a practical problem-solving strategy.","zh":"這個短語描述實際解難策略。"}],"source":"101 - ROBOTS.pdf","sourcePage":18},{"front":"solved simultaneously","meaning":"同時被解決","examples":[{"en":"Different parts of a problem can be solved simultaneously.","zh":"問題的不同部分可以同時被解決。"},{"en":"Solved simultaneously means solved at the same time.","zh":"solved simultaneously 指在同一時間被解決。"},{"en":"In a group project, one student can research while another designs slides, so tasks are solved simultaneously.","zh":"在小組項目中，一名學生做研究，另一名設計投影片，任務就能同時被處理。"},{"en":"Doing parts at the same time can save time when coordination is clear.","zh":"當協調清楚時，同時處理各部分可以節省時間。"},{"en":"This phrase focuses on parallel work.","zh":"這個短語著重平行工作。"}],"source":"101 - ROBOTS.pdf","sourcePage":18},{"front":"investigate whether","meaning":"研究是否","examples":[{"en":"Researchers are investigating whether robot swarms can create collective intelligence.","zh":"研究人員正在研究機械人群是否能創造集體智能。"},{"en":"To investigate whether something is true means to study it carefully to find out.","zh":"investigate whether something is true 指仔細研究某事是否真實。"},{"en":"A school may investigate whether later start times improve student attention.","zh":"學校可能研究較遲上課是否改善學生注意力。"},{"en":"Research begins with a question and collects evidence before reaching a conclusion.","zh":"研究從問題開始，並在得出結論前收集證據。"},{"en":"This phrase introduces a scientific or careful inquiry.","zh":"這個短語引入科學或仔細調查。"}],"source":"101 - ROBOTS.pdf","sourcePage":18},{"front":"swarms of semi-smart robots","meaning":"成群半智能機械人","examples":[{"en":"Swarms of semi-smart robots may work together effectively.","zh":"成群半智能機械人可能有效合作。"},{"en":"Swarms of semi-smart robots are large groups of partly intelligent robots acting together.","zh":"swarms of semi-smart robots 指大量部分智能的機械人一起行動。"},{"en":"A swarm of small cleaning robots could divide a large hall into sections.","zh":"一群小型清潔機械人可以把大型禮堂分成不同區域清理。"},{"en":"Even simple robots can produce useful results when many of them cooperate.","zh":"即使簡單機械人，當大量合作時也可以產生有用結果。"},{"en":"This phrase compares robot groups with insect swarms.","zh":"這個短語把機械人群比作昆蟲群。"}],"source":"101 - ROBOTS.pdf","sourcePage":18},{"front":"collective intelligence","meaning":"集體智能","examples":[{"en":"A swarm may generate collective intelligence.","zh":"群體可能產生集體智能。"},{"en":"Collective intelligence is the ability of a group to solve problems together better than individuals alone.","zh":"collective intelligence 指群體一起解決問題、表現優於單個成員的能力。"},{"en":"A class can show collective intelligence when students share different ideas to solve a project problem.","zh":"當學生分享不同想法來解決項目問題時，班級可以展現集體智能。"},{"en":"Groups can become smarter when each member contributes information or action.","zh":"當每個成員貢獻資訊或行動，群體可以變得更聰明。"},{"en":"This phrase focuses on intelligence emerging from cooperation.","zh":"這個短語著重由合作產生的智能。"}],"source":"101 - ROBOTS.pdf","sourcePage":18},{"front":"greater than the sum of its parts","meaning":"大於各部分之和","examples":[{"en":"The group may become greater than the sum of its parts.","zh":"該群體可能變得大於各部分之和。"},{"en":"Greater than the sum of its parts means a group produces more value than its individual members could alone.","zh":"greater than the sum of its parts 指群體產生的價值超過單個成員獨自能做到的總和。"},{"en":"A good team can be greater than the sum of its parts when members support each other’s weaknesses.","zh":"當成員互相補足弱點時，好團隊可以大於各部分之和。"},{"en":"Cooperation can create results that no single part could produce by itself.","zh":"合作可以創造任何單一部分都不能獨自產生的結果。"},{"en":"This phrase explains why group systems can be powerful.","zh":"這個短語解釋為何群體系統可以很有力量。"}],"source":"101 - ROBOTS.pdf","sourcePage":18},{"front":"beehives and ant colonies","meaning":"蜂巢和蟻群","examples":[{"en":"Beehives and ant colonies show collective intelligence.","zh":"蜂巢和蟻群展現集體智能。"},{"en":"Beehives and ant colonies are insect communities where many individuals work together.","zh":"beehives and ant colonies 指許多個體一起工作的昆蟲社群。"},{"en":"Ant colonies can find food, build nests and protect the group without one ant controlling everything.","zh":"蟻群可以尋找食物、築巢和保護群體，而不需要一隻螞蟻控制一切。"},{"en":"These natural systems inspire robot researchers to design cooperating machines.","zh":"這些自然系統啟發機械人研究人員設計合作機器。"},{"en":"This phrase gives biological examples of group organisation.","zh":"這個短語提供群體組織的生物例子。"}],"source":"101 - ROBOTS.pdf","sourcePage":18},{"front":"be betting that","meaning":"押注於；相信","examples":[{"en":"Several teams are betting that small robots can work together.","zh":"幾個團隊押注於小型機械人能夠合作。"},{"en":"To be betting that something will happen means to strongly believe or invest hope in that possibility.","zh":"be betting that something will happen 指強烈相信或把希望投放在某可能性上。"},{"en":"A company may be betting that customers will prefer online ordering in the future.","zh":"公司可能押注於顧客未來會偏好網上訂購。"},{"en":"Researchers bet on an idea when they spend time and money testing it.","zh":"當研究人員花時間和金錢測試一個想法，就是押注於它。"},{"en":"This phrase suggests confidence, but not certainty.","zh":"這個短語表示信心，但不是確定。"}],"source":"101 - ROBOTS.pdf","sourcePage":18},{"front":"legions of mini-critters","meaning":"大批微型機械小生物","examples":[{"en":"Legions of mini-critters could be sent to explore dangerous places.","zh":"大批微型機械小生物可以被派去探索危險地方。"},{"en":"Legions of mini-critters means very large numbers of tiny robot-like creatures or machines.","zh":"legions of mini-critters 指大量微型、像小生物的機械或機械人。"},{"en":"A swarm of mini-critters could search a collapsed building through small gaps.","zh":"一群微型機械小生物可以穿過小縫搜尋倒塌建築物。"},{"en":"Many tiny robots can cover more ground than one large robot.","zh":"許多微型機械人可以比一部大型機械人覆蓋更多地方。"},{"en":"This phrase is playful and makes small robots sound like little creatures.","zh":"這個短語帶玩味，令小型機械人聽起來像小生物。"}],"source":"101 - ROBOTS.pdf","sourcePage":18},{"front":"working together like an ant colony","meaning":"像蟻群一樣合作","examples":[{"en":"Mini-robots may work together like an ant colony.","zh":"微型機械人可能像蟻群一樣合作。"},{"en":"Working together like an ant colony means many small units cooperate without needing one central leader for every action.","zh":"working together like an ant colony 指許多小單位合作，而不需要每個行動都有中央領袖控制。"},{"en":"Students cleaning a classroom can work like an ant colony if each person handles a small task.","zh":"如果每個學生負責一項小任務，清潔課室時就可以像蟻群一樣合作。"},{"en":"This kind of cooperation can make simple individuals produce a strong group result.","zh":"這種合作可以令簡單個體產生強大的群體結果。"},{"en":"This phrase uses ants as a model of organised teamwork.","zh":"這個短語使用螞蟻作為有組織團隊合作的模型。"}],"source":"101 - ROBOTS.pdf","sourcePage":18},{"front":"be sent to explore","meaning":"被派去探索","examples":[{"en":"Mini-robots could be sent to explore the climate of planets.","zh":"微型機械人可以被派去探索行星氣候。"},{"en":"To be sent to explore means to be dispatched to investigate an unknown or difficult place.","zh":"be sent to explore 指被派遣去調查未知或困難地方。"},{"en":"Scientists may send drones to explore a forest after a storm.","zh":"暴風雨後，科學家可能派無人機去探索森林。"},{"en":"Machines are sent to explore when places are too dangerous, distant or expensive for people.","zh":"當地方對人類太危險、太遙遠或成本太高，機器會被派去探索。"},{"en":"This phrase focuses on purposeful investigation.","zh":"這個短語著重有目的的調查。"}],"source":"101 - ROBOTS.pdf","sourcePage":19},{"front":"the climate of planets","meaning":"行星氣候","examples":[{"en":"Robots may explore the climate of planets.","zh":"機械人可能探索行星氣候。"},{"en":"The climate of planets means the long-term weather conditions on planets.","zh":"climate of planets 指行星上的長期天氣條件。"},{"en":"Scientists study the climate of planets to learn about temperature, storms and atmosphere.","zh":"科學家研究行星氣候，以了解溫度、風暴和大氣。"},{"en":"Understanding another planet’s climate can help judge whether machines or humans could survive there.","zh":"理解另一個行星的氣候，可以幫助判斷機器或人類能否在那裡生存。"},{"en":"This phrase refers to planetary conditions, not daily weather only.","zh":"這個短語指行星條件，而不只是每日天氣。"}],"source":"101 - ROBOTS.pdf","sourcePage":19},{"front":"inspect pipes","meaning":"檢查管道","examples":[{"en":"Mini-robots could inspect pipes in dangerous industrial situations.","zh":"微型機械人可以在危險工業環境中檢查管道。"},{"en":"To inspect pipes means to examine pipes carefully for damage, leaks or blockages.","zh":"inspect pipes 指仔細檢查管道是否有損壞、洩漏或堵塞。"},{"en":"A plumber may inspect pipes under a sink when water drains slowly.","zh":"當去水很慢時，水喉匠可能檢查水槽下的管道。"},{"en":"Robots can inspect pipes that are too narrow or dangerous for humans to enter.","zh":"機械人可以檢查人類無法進入、太狹窄或危險的管道。"},{"en":"This phrase focuses on careful checking of infrastructure.","zh":"這個短語著重仔細檢查基礎設施。"}],"source":"101 - ROBOTS.pdf","sourcePage":19},{"front":"dangerous industrial situations","meaning":"危險的工業環境","examples":[{"en":"Robots can be used in dangerous industrial situations.","zh":"機械人可以用於危險的工業環境。"},{"en":"Dangerous industrial situations are workplace conditions in factories, mines or plants that can harm people.","zh":"dangerous industrial situations 指工廠、礦場或廠房中可能傷害人的工作條件。"},{"en":"A chemical leak creates a dangerous industrial situation that workers should not enter without protection.","zh":"化學品洩漏會造成危險的工業環境，工人不應在沒有保護下進入。"},{"en":"Robots reduce risk by entering these places before human workers do.","zh":"機械人在人類工人進入前先進入這些地方，可以減少風險。"},{"en":"This phrase refers to hazards in industrial work.","zh":"這個短語指工業工作中的危害。"}],"source":"101 - ROBOTS.pdf","sourcePage":19},{"front":"reading passage","meaning":"閱讀文章","examples":[{"en":"Students answer questions based on the reading passage.","zh":"學生根據閱讀文章回答問題。"},{"en":"A reading passage is a text that students read before answering questions.","zh":"reading passage 指學生在回答問題前閱讀的文本。"},{"en":"In an exam, students should use evidence from the reading passage rather than outside knowledge.","zh":"在考試中，學生應使用閱讀文章中的證據，而不是外部知識。"},{"en":"Misreading the passage can lead to wrong answers even if the student knows the topic.","zh":"即使學生熟悉主題，讀錯文章也可能導致答案錯誤。"},{"en":"This phrase is common in reading tests.","zh":"這個短語常見於閱讀測驗。"}],"source":"101 - ROBOTS.pdf","sourcePage":19},{"front":"the most suitable heading","meaning":"最合適的標題","examples":[{"en":"Students choose the most suitable heading for each paragraph.","zh":"學生為每一段選出最合適的標題。"},{"en":"The most suitable heading is the title that best matches the main idea of a paragraph.","zh":"most suitable heading 指最符合段落主旨的標題。"},{"en":"A heading about “robot surgery” would not fit a paragraph mainly about robot swarms.","zh":"如果一段主要談機械人群，關於「機械人手術」的標題就不合適。"},{"en":"Students should focus on the whole paragraph, not one attractive word.","zh":"學生應集中於整段，而不是某個吸引字眼。"},{"en":"This phrase tests main-idea understanding.","zh":"這個短語測試主旨理解。"}],"source":"101 - ROBOTS.pdf","sourcePage":19},{"front":"from the list of headings below","meaning":"從以下標題列表中","examples":[{"en":"The headings are chosen from the list of headings below.","zh":"標題從以下標題列表中選出。"},{"en":"From the list of headings below means from the title options printed under the instruction.","zh":"from the list of headings below 指從指示下方列出的標題選項中。"},{"en":"Students should not invent their own headings if the list is provided.","zh":"如果題目提供列表，學生不應自己創作標題。"},{"en":"Reading all headings first helps prevent quick but careless choices.","zh":"先閱讀所有標題有助避免快速但粗心的選擇。"},{"en":"This phrase tells students where the answer options are.","zh":"這個短語告訴學生答案選項在哪裡。"}],"source":"101 - ROBOTS.pdf","sourcePage":19},{"front":"appropriate numbers","meaning":"適當號碼","examples":[{"en":"Students write the appropriate numbers on the answer sheet.","zh":"學生在答題紙上寫下適當號碼。"},{"en":"Appropriate numbers are the correct numbered choices for the answers.","zh":"appropriate numbers 指答案所對應的正確編號選項。"},{"en":"In a matching task, students must copy the appropriate numbers carefully.","zh":"在配對題中，學生必須仔細抄寫適當號碼。"},{"en":"A correct idea can still lose marks if the wrong number is written.","zh":"即使想法正確，如果寫錯號碼仍可能失分。"},{"en":"This phrase focuses on answer format and accuracy.","zh":"這個短語著重答案格式和準確性。"}],"source":"101 - ROBOTS.pdf","sourcePage":19},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生在答題紙上寫下答案。"},{"en":"On your answer sheet means in the official place where exam answers are recorded.","zh":"on your answer sheet 指在考試記錄答案的正式位置上。"},{"en":"A student should check that each answer is written in the correct box on the answer sheet.","zh":"學生應檢查每個答案是否寫在答題紙正確方格中。"},{"en":"Answers written only on the question paper may not be marked in some tests.","zh":"在某些測驗中，只寫在題目紙上的答案可能不會被評分。"},{"en":"This phrase tells students exactly where to put answers.","zh":"這個短語準確告訴學生答案要寫在哪裡。"}],"source":"101 - ROBOTS.pdf","sourcePage":19},{"front":"result from","meaning":"由……產生","examples":[{"en":"Some success has resulted from observing how the brain functions.","zh":"一些成功由觀察大腦如何運作而產生。"},{"en":"To result from something means to be caused by it.","zh":"result from something 指由某事造成。"},{"en":"Better exam scores may result from regular practice and clear feedback.","zh":"更好考試成績可能由定期練習和清楚回饋產生。"},{"en":"If a result comes from a cause, changing the cause may change the result.","zh":"如果結果來自某原因，改變原因可能改變結果。"},{"en":"This phrase links an outcome with its source.","zh":"這個短語把結果與來源連繫起來。"}],"source":"101 - ROBOTS.pdf","sourcePage":19},{"front":"observe how the brain functions","meaning":"觀察大腦如何運作","examples":[{"en":"Scientists observe how the brain functions to improve robot design.","zh":"科學家觀察大腦如何運作，以改善機械人設計。"},{"en":"To observe how the brain functions means to study how the brain works in real situations.","zh":"observe how the brain functions 指研究大腦在真實情況中如何工作。"},{"en":"Doctors may observe how the brain functions after an injury by using scans and tests.","zh":"醫生可能透過掃描和測試觀察受傷後大腦如何運作。"},{"en":"Brain observation can inspire new ways to design learning machines.","zh":"觀察大腦可以啟發設計學習機器的新方式。"},{"en":"This phrase focuses on studying brain activity, not guessing about it.","zh":"這個短語著重研究大腦活動，而不是猜測。"}],"source":"101 - ROBOTS.pdf","sourcePage":20},{"front":"expect too much from","meaning":"對……期望過高","examples":[{"en":"Some researchers ask whether we expect too much from one robot.","zh":"有些研究人員問我們是否對一部機械人期望過高。"},{"en":"To expect too much from someone or something means to demand more than it can reasonably do.","zh":"expect too much from someone or something 指要求超過其合理能力。"},{"en":"Parents may expect too much from a child if they want perfect grades in every subject.","zh":"如果父母要求孩子每科滿分，就可能對孩子期望過高。"},{"en":"Expecting too much from one machine can lead to disappointment and poor design choices.","zh":"對單一機器期望過高，可能導致失望和差劣設計選擇。"},{"en":"This phrase warns against unrealistic expectations.","zh":"這個短語提醒人們不要有不切實際的期望。"}],"source":"101 - ROBOTS.pdf","sourcePage":20},{"front":"humanistic possibilities","meaning":"人性化可能性","examples":[{"en":"Scientists are examining the humanistic possibilities of robotics.","zh":"科學家正在研究機械人學的人性化可能性。"},{"en":"Humanistic possibilities are ways technology might support human feelings, care, dignity or relationships.","zh":"humanistic possibilities 指科技可能支援人類感受、照顧、尊嚴或關係的方式。"},{"en":"A robot in a nursing home raises humanistic possibilities if it helps lonely residents feel noticed.","zh":"如果安老院機械人幫助孤獨住客感到被注意，它就帶來人性化可能性。"},{"en":"Technology has humanistic value when it improves people’s lives, not only efficiency.","zh":"當科技改善人的生活，而不只是效率時，就有人性化價值。"},{"en":"This phrase looks at the human side of machines.","zh":"這個短語關注機器的人性面。"}],"source":"101 - ROBOTS.pdf","sourcePage":20},{"front":"make judgements","meaning":"作出判斷","examples":[{"en":"There are judgements that robots cannot make.","zh":"有些判斷是機械人無法作出的。"},{"en":"To make judgements means to decide what is right, important or appropriate in a situation.","zh":"make judgements 指在某情況中決定甚麼正確、重要或合適。"},{"en":"A teacher must make judgements about when to help a student and when to let them try alone.","zh":"老師必須判斷何時幫助學生，何時讓他自己嘗試。"},{"en":"Judgements are hard for robots because they often require context and values.","zh":"判斷對機械人來說很難，因為它們常需要語境和價值觀。"},{"en":"This phrase refers to thoughtful decision-making, not simple calculation.","zh":"這個短語指深思熟慮的決策，而不是簡單計算。"}],"source":"101 - ROBOTS.pdf","sourcePage":20},{"front":"the power of robots","meaning":"機械人的力量","examples":[{"en":"Some people wonder whether the power of robots has become too great.","zh":"有些人懷疑機械人的力量是否已變得太大。"},{"en":"The power of robots means the ability robots have to affect work, safety and human life.","zh":"power of robots 指機械人影響工作、安全和人類生活的能力。"},{"en":"Factory robots have power because they can change how many workers a company needs.","zh":"工廠機械人有力量，因為它們可以改變公司需要多少工人。"},{"en":"If robot power grows without careful rules, people may worry about control and responsibility.","zh":"如果機械人的力量在沒有仔細規則下增長，人們可能擔心控制和責任。"},{"en":"This phrase refers to influence and capability, not only physical strength.","zh":"這個短語指影響力和能力，而不只是體力。"}],"source":"101 - ROBOTS.pdf","sourcePage":20},{"front":"heighten human skills","meaning":"提升人類技能","examples":[{"en":"Human skills have been heightened with the help of robotics.","zh":"人類技能已在機械人學幫助下得到提升。"},{"en":"To heighten human skills means to improve or strengthen what people can do.","zh":"heighten human skills 指改善或加強人類能做的事。"},{"en":"A spell-check tool can heighten writing skills by helping students notice repeated mistakes.","zh":"拼字檢查工具可以幫助學生注意反覆錯誤，從而提升寫作技能。"},{"en":"Robotics can heighten surgical skills by adding precision to a doctor’s movements.","zh":"機械人學可以透過增加醫生動作精準度來提升手術技能。"},{"en":"This phrase shows technology enhancing people rather than replacing them.","zh":"這個短語顯示科技增強人類，而不是取代人類。"}],"source":"101 - ROBOTS.pdf","sourcePage":20},{"front":"with the help of","meaning":"在……幫助下","examples":[{"en":"Surgery can be improved with the help of robotics.","zh":"手術可以在機械人學幫助下得到改善。"},{"en":"With the help of something means using support from it.","zh":"with the help of something 指使用某物提供的支援。"},{"en":"A student can improve pronunciation with the help of recorded model answers.","zh":"學生可以在錄音示範答案幫助下改善發音。"},{"en":"Help from tools can make difficult tasks safer, faster or more accurate.","zh":"工具的幫助可以令困難任務更安全、更快速或更準確。"},{"en":"This phrase shows assistance rather than independent action.","zh":"這個短語顯示協助，而不是獨立行動。"}],"source":"101 - ROBOTS.pdf","sourcePage":20},{"front":"prefer the brain to control","meaning":"較希望由大腦控制","examples":[{"en":"There are some things we prefer the brain to control.","zh":"有些事情我們較希望由大腦控制。"},{"en":"To prefer the brain to control something means to want human judgement rather than automatic control.","zh":"prefer the brain to control something 指希望由人類判斷控制，而不是自動控制。"},{"en":"In a medical emergency, people may prefer a doctor’s brain to control the final decision.","zh":"在醫療緊急情況中，人們可能較希望由醫生的大腦控制最終決定。"},{"en":"Some tasks require moral judgement, so people may not want machines to decide alone.","zh":"有些任務需要道德判斷，所以人們可能不希望機器獨自決定。"},{"en":"This phrase contrasts human control with machine control.","zh":"這個短語把人類控制與機器控制作對比。"}],"source":"101 - ROBOTS.pdf","sourcePage":20},{"front":"quietly infiltrate our lives","meaning":"悄悄滲入我們的生活","examples":[{"en":"Robots have quietly infiltrated our lives.","zh":"機械人已悄悄滲入我們的生活。"},{"en":"To quietly infiltrate our lives means to enter everyday life gradually without attracting much attention.","zh":"quietly infiltrate our lives 指逐漸進入日常生活，而沒有引起太多注意。"},{"en":"Automatic doors and self-checkout machines quietly infiltrated shopping without feeling dramatic.","zh":"自動門和自助付款機悄悄滲入購物場景，並不顯得戲劇化。"},{"en":"Slow technological spread can change habits before people fully notice it.","zh":"緩慢的科技擴散可以在人們完全察覺前改變習慣。"},{"en":"This phrase suggests subtle and gradual presence.","zh":"這個短語表示細微而漸進的存在。"}],"source":"101 - ROBOTS.pdf","sourcePage":20},{"front":"original predictions","meaning":"最初預測","examples":[{"en":"Original predictions about artificial intelligence have been revised.","zh":"關於人工智能的最初預測已被修訂。"},{"en":"Original predictions are the first forecasts made before later evidence appears.","zh":"original predictions 指在後來證據出現前最早作出的預測。"},{"en":"A school’s original prediction about enrolment may change after more families apply.","zh":"學校對收生人數的最初預測，可能在更多家庭申請後改變。"},{"en":"Predictions often need revision when progress is slower or faster than expected.","zh":"當進展比預期更慢或更快，預測常需要修訂。"},{"en":"This phrase compares early expectations with later understanding.","zh":"這個短語比較早期期望與後來理解。"}],"source":"101 - ROBOTS.pdf","sourcePage":20},{"front":"be revised","meaning":"被修訂","examples":[{"en":"Predictions about artificial intelligence have been revised.","zh":"關於人工智能的預測已被修訂。"},{"en":"To be revised means to be changed or corrected after review.","zh":"be revised 指經檢視後被改變或修正。"},{"en":"A student’s essay may be revised after the teacher gives feedback.","zh":"學生文章可能在老師給回饋後被修訂。"},{"en":"Plans are revised when new evidence shows the first version was unrealistic.","zh":"當新證據顯示第一版本不現實，計劃就會被修訂。"},{"en":"This phrase shows improvement or correction after reconsideration.","zh":"這個短語顯示重新考慮後的改善或修正。"}],"source":"101 - ROBOTS.pdf","sourcePage":21},{"front":"another approach","meaning":"另一種方法","examples":[{"en":"Researchers are trying another approach to robotic intelligence.","zh":"研究人員正在嘗試另一種機械人智能方法。"},{"en":"Another approach is a different method for dealing with the same problem.","zh":"another approach 指處理同一問題的不同方法。"},{"en":"If grammar drills do not help, a teacher may try another approach using stories.","zh":"如果文法操練無效，老師可能嘗試用故事的另一種方法。"},{"en":"Different approaches are useful when a problem is too complex for one method.","zh":"當問題太複雜，不能靠單一方法解決，不同方法就很有用。"},{"en":"This phrase introduces an alternative method.","zh":"這個短語引入替代方法。"}],"source":"101 - ROBOTS.pdf","sourcePage":21},{"front":"agree with the information given","meaning":"與所給資料一致","examples":[{"en":"Students decide whether each statement agrees with the information given.","zh":"學生判斷每個陳述是否與所給資料一致。"},{"en":"To agree with the information given means to match what the passage says.","zh":"agree with the information given 指與文章所說內容相符。"},{"en":"In a reading test, a true answer must agree with the information given, not outside knowledge.","zh":"在閱讀測驗中，正確答案必須與所給資料一致，而不是外部知識。"},{"en":"If one detail is changed, a statement may no longer agree with the text.","zh":"如果一個細節被改變，陳述可能不再與文本一致。"},{"en":"This phrase is common in TRUE, FALSE and NOT GIVEN questions.","zh":"這個短語常見於 TRUE、FALSE 和 NOT GIVEN 題型。"}],"source":"101 - ROBOTS.pdf","sourcePage":21},{"front":"contradict the information","meaning":"與資料矛盾","examples":[{"en":"A statement is false if it contradicts the information.","zh":"如果陳述與資料矛盾，它就是 false。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"contradict the information 指說法與文本所說相反。"},{"en":"If a passage says a robot was used in Alaska, a statement saying Japan contradicts the information.","zh":"如果文章說機械人在阿拉斯加使用，而陳述說日本，就是與資料矛盾。"},{"en":"Students should choose FALSE only when there is a clear conflict.","zh":"只有在明顯衝突時，學生才應選 FALSE。"},{"en":"This phrase means the text and statement cannot both be true.","zh":"這個短語表示文本和陳述不能同時為真。"}],"source":"101 - ROBOTS.pdf","sourcePage":21},{"front":"no information on this","meaning":"沒有這方面資料","examples":[{"en":"Students write “NOT GIVEN” when there is no information on this.","zh":"當沒有這方面資料時，學生寫 “NOT GIVEN”。"},{"en":"No information on this means the passage does not clearly discuss the point.","zh":"no information on this 指文章沒有清楚討論該點。"},{"en":"If a passage describes a robot’s shape but not its cost, there is no information on the cost.","zh":"如果文章描述機械人形狀但沒有說成本，就是沒有成本方面資料。"},{"en":"Students should not guess when the text gives no evidence.","zh":"當文本沒有證據時，學生不應猜測。"},{"en":"This phrase is used when an answer cannot be proved from the passage.","zh":"這個短語用於答案不能從文章證明的情況。"}],"source":"101 - ROBOTS.pdf","sourcePage":21},{"front":"successfully predict","meaning":"成功預測","examples":[{"en":"The question asks whether Karel Capek successfully predicted modern robot uses.","zh":"題目問 Karel Capek 是否成功預測現代機械人的用途。"},{"en":"To successfully predict something means to say what will happen and later be proved right.","zh":"successfully predict something 指說出將會發生的事，並在後來被證明正確。"},{"en":"A weather app successfully predicts rain if it forecasts rain and rain really falls.","zh":"如果天氣應用程式預測下雨，而真的下雨，它就是成功預測。"},{"en":"Successful prediction requires both a clear forecast and later evidence.","zh":"成功預測需要清楚預測和後來證據。"},{"en":"This phrase focuses on accuracy about the future.","zh":"這個短語著重對未來的準確性。"}],"source":"101 - ROBOTS.pdf","sourcePage":21},{"front":"current uses","meaning":"目前用途","examples":[{"en":"Robots now have many current uses.","zh":"機械人現在有許多目前用途。"},{"en":"Current uses are the ways something is used at the present time.","zh":"current uses 指某物在現在被使用的方式。"},{"en":"Current uses of smartphones include payment, maps, photos and communication.","zh":"智能手機的目前用途包括付款、地圖、拍照和溝通。"},{"en":"A technology’s current uses may be very different from what inventors first imagined.","zh":"一項科技的目前用途可能與發明者最初想像很不同。"},{"en":"This phrase focuses on present-day applications.","zh":"這個短語著重當代應用。"}],"source":"101 - ROBOTS.pdf","sourcePage":21},{"front":"lives were saved by","meaning":"生命被……拯救","examples":[{"en":"The statement asks whether lives were saved by the NASA robot Dante.","zh":"該陳述問生命是否被 NASA 機械人 Dante 拯救。"},{"en":"Lives were saved by something means people avoided death because of it.","zh":"lives were saved by something 指人們因某事而避免死亡。"},{"en":"Lives were saved by a fire alarm when residents left the building before the flames spread.","zh":"當住客在火勢蔓延前離開建築物，生命就被火警鐘拯救。"},{"en":"To prove that lives were saved, the passage must show people were in real danger and survived because of the action.","zh":"要證明生命被拯救，文章必須顯示人們處於真正危險並因該行動而存活。"},{"en":"This phrase refers to a serious protective result.","zh":"這個短語指嚴重的保護性結果。"}],"source":"101 - ROBOTS.pdf","sourcePage":21},{"front":"make fine visual judgements","meaning":"作出精細視覺判斷","examples":[{"en":"Some robots are able to make fine visual judgements.","zh":"有些機械人能作出精細視覺判斷。"},{"en":"To make fine visual judgements means to notice and decide based on very small visual differences.","zh":"make fine visual judgements 指根據非常細小的視覺差異作出判斷。"},{"en":"A quality-control robot may make fine visual judgements about scratches on a phone screen.","zh":"品質控制機械人可能對手機螢幕上的刮痕作出精細視覺判斷。"},{"en":"Fine visual judgement is useful in factories where parts must fit exactly.","zh":"在零件必須精確吻合的工廠中，精細視覺判斷很有用。"},{"en":"This phrase focuses on precise seeing and deciding.","zh":"這個短語著重精準觀看和判斷。"}],"source":"101 - ROBOTS.pdf","sourcePage":21},{"front":"internal workings of","meaning":"……的內部運作","examples":[{"en":"The internal workings of the brain remain difficult to replicate.","zh":"大腦的內部運作仍難以複製。"},{"en":"The internal workings of something are the hidden processes inside it that make it function.","zh":"internal workings of something 指使某物運作的內部隱藏過程。"},{"en":"A mechanic understands the internal workings of an engine, not just its outside shape.","zh":"機械師理解引擎的內部運作，而不只是外形。"},{"en":"If people do not understand internal workings, they cannot easily copy or repair a system.","zh":"如果人們不了解內部運作，就難以複製或修理系統。"},{"en":"This phrase points to what happens inside.","zh":"這個短語指內部發生的事情。"}],"source":"101 - ROBOTS.pdf","sourcePage":21},{"front":"be replicated by","meaning":"被……複製","examples":[{"en":"The brain’s internal workings cannot easily be replicated by robots.","zh":"大腦的內部運作不能輕易被機械人複製。"},{"en":"To be replicated by something means to be copied or reproduced by it.","zh":"be replicated by something 指被某物複製或重現。"},{"en":"A chef’s exact cooking style may not be replicated by a recipe alone.","zh":"廚師的精確烹調風格未必能單靠食譜複製。"},{"en":"Complex natural systems are hard to replicate because many hidden details matter.","zh":"複雜自然系統很難複製，因為許多隱藏細節都很重要。"},{"en":"This phrase focuses on copying a process or result.","zh":"這個短語著重複製過程或結果。"}],"source":"101 - ROBOTS.pdf","sourcePage":22},{"front":"advanced robot systems","meaning":"先進機械人系統","examples":[{"en":"The question refers to advanced robot systems.","zh":"題目指的是先進機械人系統。"},{"en":"Advanced robot systems are highly developed robotic setups with sensors, software and mechanical parts working together.","zh":"advanced robot systems 指由感應器、軟件和機械部件共同運作的高度發展機械人配置。"},{"en":"A hospital may use advanced robot systems for delicate surgery.","zh":"醫院可能使用先進機械人系統進行精細手術。"},{"en":"Advanced systems can do more complex work but may still need human oversight.","zh":"先進系統可以做更複雜工作，但仍可能需要人類監督。"},{"en":"This phrase refers to sophisticated robotics, not simple machines.","zh":"這個短語指精密機械人技術，而不是簡單機器。"}],"source":"101 - ROBOTS.pdf","sourcePage":22},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below with words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"To complete the summary below means to fill in missing words in the summary under the instruction.","zh":"complete the summary below 指填寫指示下方摘要中的空缺字詞。"},{"en":"Students should read the relevant paragraph before completing the summary below.","zh":"學生完成以下摘要前應閱讀相關段落。"},{"en":"A correct answer must fit both the meaning and the grammar of the sentence.","zh":"正確答案必須同時符合句子的意思和文法。"},{"en":"This phrase is common in reading tests with gaps.","zh":"這個短語常見於有空格的閱讀測驗。"}],"source":"101 - ROBOTS.pdf","sourcePage":22},{"front":"words taken from","meaning":"取自……的字詞","examples":[{"en":"The answers should be words taken from paragraph F.","zh":"答案應是取自 F 段的字詞。"},{"en":"Words taken from a passage are exact words copied from that part of the text.","zh":"words taken from a passage 指從該部分文本準確抄出的字詞。"},{"en":"If the instruction says words taken from the passage, students should not use their own synonyms.","zh":"如果指示說答案取自文章，學生不應使用自己的同義詞。"},{"en":"Copying exact words helps keep the answer within the test rules.","zh":"抄寫準確字詞有助答案符合測驗規則。"},{"en":"This phrase identifies the source of the answer.","zh":"這個短語指出答案來源。"}],"source":"101 - ROBOTS.pdf","sourcePage":22},{"front":"no more than three words","meaning":"不超過三個字","examples":[{"en":"Students should use no more than three words for each answer.","zh":"學生每個答案應使用不超過三個字。"},{"en":"No more than three words means one, two or three words, but not four.","zh":"no more than three words 指一個、兩個或三個字，但不是四個。"},{"en":"If the answer limit is no more than three words, “a video camera” is allowed.","zh":"如果答案限制是不超過三個字，“a video camera” 是可以的。"},{"en":"Writing too many words can lose marks even when the idea is correct.","zh":"即使意思正確，寫太多字也可能失分。"},{"en":"This phrase is a strict answer-length instruction.","zh":"這個短語是嚴格的答案字數指示。"}],"source":"101 - ROBOTS.pdf","sourcePage":22},{"front":"prototype of","meaning":"……的原型","examples":[{"en":"The prototype of the Japanese face robot observes humans.","zh":"日本臉部機械人的原型會觀察人類。"},{"en":"A prototype of something is an early test version of it.","zh":"prototype of something 指某事物的早期測試版本。"},{"en":"Engineers may build a prototype of a new wheelchair before making many copies.","zh":"工程師可能先製作新輪椅的原型，再大量生產。"},{"en":"A prototype helps researchers test ideas and find weaknesses.","zh":"原型幫助研究人員測試想法並找出弱點。"},{"en":"This phrase refers to a first model, not the finished product.","zh":"這個短語指第一版模型，而不是完成品。"}],"source":"101 - ROBOTS.pdf","sourcePage":22},{"front":"observe humans through","meaning":"透過……觀察人類","examples":[{"en":"The robot observes humans through a camera.","zh":"機械人透過攝影機觀察人類。"},{"en":"To observe humans through something means to watch or study people using that tool.","zh":"observe humans through something 指使用某工具觀看或研究人。"},{"en":"A security system observes visitors through cameras at the entrance.","zh":"保安系統透過入口的攝影機觀察訪客。"},{"en":"Robots use cameras to gather visual information before responding.","zh":"機械人使用攝影機收集視覺資訊，然後作出回應。"},{"en":"This phrase connects observation with the instrument used.","zh":"這個短語把觀察與所用工具連繫起來。"}],"source":"101 - ROBOTS.pdf","sourcePage":22},{"front":"embedded in its head","meaning":"嵌入其頭部","examples":[{"en":"The camera is embedded in the robot’s head.","zh":"攝影機嵌入機械人的頭部。"},{"en":"Embedded in its head means fixed inside the head as part of the robot’s structure.","zh":"embedded in its head 指固定在頭部內部，成為機械人結構的一部分。"},{"en":"A microphone may be embedded in a headset so the user can speak hands-free.","zh":"咪高峰可能嵌入耳機，讓使用者免提說話。"},{"en":"Embedding the camera makes the robot’s observation system less obvious and more face-like.","zh":"把攝影機嵌入頭部，令機械人的觀察系統較不明顯，也更像臉部。"},{"en":"This phrase describes an internal placement.","zh":"這個短語描述內部放置。"}],"source":"101 - ROBOTS.pdf","sourcePage":22},{"front":"refer to","meaning":"參考","examples":[{"en":"The robot refers to a database of facial expressions.","zh":"機械人參考面部表情資料庫。"},{"en":"To refer to something means to consult or use it for information.","zh":"refer to something 指查閱或使用某物作為資料來源。"},{"en":"A student may refer to a dictionary when unsure of a word’s meaning.","zh":"學生不確定詞義時，可能參考字典。"},{"en":"Referring to stored examples helps a system make a better judgement.","zh":"參考已儲存例子幫助系統作出更好判斷。"},{"en":"In this context, refer to means use as a source, not mention in speech.","zh":"在這個語境中，refer to 指用作來源，而不是在說話中提及。"}],"source":"101 - ROBOTS.pdf","sourcePage":22},{"front":"typical looks","meaning":"典型面貌；典型表情","examples":[{"en":"The database contains typical looks that the human face can have.","zh":"資料庫包含人臉可能有的典型面貌。"},{"en":"Typical looks are common facial appearances or expressions linked to certain feelings.","zh":"typical looks 指與某些感受相關的常見面部樣貌或表情。"},{"en":"A worried look and a happy smile are typical looks people may recognise quickly.","zh":"擔心的神情和開心的笑容都是人們可能快速識別的典型表情。"},{"en":"A robot compares a face with typical looks to guess emotion.","zh":"機械人把臉與典型表情比較來猜測情緒。"},{"en":"This phrase means common patterns, not unusual individual faces.","zh":"這個短語指常見模式，而不是不尋常的個人臉孔。"}],"source":"101 - ROBOTS.pdf","sourcePage":22},{"front":"decide what emotion","meaning":"判斷甚麼情緒","examples":[{"en":"The robot tries to decide what emotion the person is feeling.","zh":"機械人嘗試判斷那人正在感受甚麼情緒。"},{"en":"To decide what emotion someone is feeling means to judge whether they are happy, sad, angry or another feeling.","zh":"decide what emotion someone is feeling 指判斷某人是開心、悲傷、憤怒還是其他感受。"},{"en":"A parent may decide what emotion a child is feeling by listening to tone and looking at the face.","zh":"家長可能透過聆聽語氣和觀察臉部，判斷孩子正在感受甚麼情緒。"},{"en":"This decision is difficult because people can hide or mix emotions.","zh":"這種判斷很困難，因為人們可以隱藏或混合情緒。"},{"en":"This phrase focuses on emotional interpretation.","zh":"這個短語著重情感解讀。"}],"source":"101 - ROBOTS.pdf","sourcePage":23},{"front":"respond to this expression","meaning":"回應這個表情","examples":[{"en":"The robot changes its own face to respond to this expression.","zh":"機械人改變自己的臉來回應這個表情。"},{"en":"To respond to this expression means to react to the facial signal that has been shown.","zh":"respond to this expression 指對所顯示的面部訊號作出反應。"},{"en":"A teacher may respond to a confused expression by explaining the point again.","zh":"老師可能透過再次解釋重點來回應困惑表情。"},{"en":"A good response should match what the expression suggests.","zh":"好回應應該配合該表情所表示的意思。"},{"en":"This phrase connects reading emotion with taking action.","zh":"這個短語把讀取情緒與採取行動連繫起來。"}],"source":"101 - ROBOTS.pdf","sourcePage":23},{"front":"alter its own expression","meaning":"改變自己的表情","examples":[{"en":"The robot alters its own expression using pressure pads.","zh":"機械人使用壓力墊改變自己的表情。"},{"en":"To alter its own expression means to change the look of its face.","zh":"alter its own expression 指改變自己臉部的樣子。"},{"en":"A cartoon character may alter its expression from a smile to a frown to show sadness.","zh":"卡通角色可能把表情由微笑變成皺眉，以顯示悲傷。"},{"en":"Changing expression helps a robot communicate a response that people can recognise.","zh":"改變表情幫助機械人傳達人類能識別的回應。"},{"en":"This phrase focuses on visible facial change.","zh":"這個短語著重可見的面部變化。"}],"source":"101 - ROBOTS.pdf","sourcePage":23},{"front":"using a number of","meaning":"使用若干……","examples":[{"en":"The robot changes its face using a number of tiny pressure pads.","zh":"機械人使用若干微型壓力墊改變臉部。"},{"en":"Using a number of something means using several of them.","zh":"using a number of something 指使用幾個或若干個某物。"},{"en":"A teacher may explain a difficult word using a number of simple examples.","zh":"老師可能使用若干簡單例子來解釋困難詞語。"},{"en":"Several small parts can work together to create a more complex action.","zh":"幾個小部件可以一起運作，創造更複雜的動作。"},{"en":"This phrase introduces multiple tools or items used for one purpose.","zh":"這個短語引入為同一目的使用的多個工具或項目。"}],"source":"101 - ROBOTS.pdf","sourcePage":23}],"ielts/reading/passage-2/Practice 102":[{"front":"It’s Eco-logical","meaning":"「環保又合乎邏輯」的雙關語","examples":[{"en":"The title “It’s Eco-logical” plays on the words “ecological” and “logical.”","zh":"標題 “It’s Eco-logical” 是對 ecological 和 logical 兩個詞的雙關。"},{"en":"“It’s Eco-logical” suggests that environmentally friendly choices can also make practical sense.","zh":"“It’s Eco-logical” 暗示環保選擇也可以合乎實際道理。"},{"en":"A hotel using solar power and less water may call its policy eco-logical because it saves money and protects nature.","zh":"一間酒店使用太陽能和減少用水，可能稱其政策為 eco-logical，因為它既省錢又保護自然。"},{"en":"The title works because readers hear both ecology and logic in the same word.","zh":"這個標題有效，因為讀者同時聽到 ecology 和 logic 兩層意思。"},{"en":"The phrase is a pun, so its meaning depends on both sound and idea.","zh":"這個短語是雙關語，因此意思取決於聲音和概念兩方面。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":1},{"front":"eco-friendly holiday","meaning":"環保假期","examples":[{"en":"Planning an eco-friendly holiday can be difficult for travellers.","zh":"對旅客來說，規劃環保假期可能很困難。"},{"en":"An eco-friendly holiday is a trip designed to reduce harm to the environment.","zh":"eco-friendly holiday 指旨在減少對環境傷害的旅程。"},{"en":"A family may choose an eco-friendly holiday by taking trains, staying in a green hotel, and avoiding waste.","zh":"一個家庭可以透過乘坐火車、入住環保酒店和避免浪費來選擇環保假期。"},{"en":"If a holiday saves water, supports local people, and protects wildlife, it is more likely to be eco-friendly.","zh":"如果一個假期節約用水、支持本地人並保護野生動物，它就更可能是環保的。"},{"en":"The phrase means more than visiting nature; the whole trip should be responsible.","zh":"這個短語不只是指到訪自然景點；整個旅程都應負責任。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":1},{"front":"a minefield for","meaning":"對……來說是容易出錯的複雜局面","examples":[{"en":"Planning an eco-friendly holiday can be a minefield for travellers.","zh":"對旅客來說，規劃環保假期可能是一個容易出錯的複雜局面。"},{"en":"A minefield for someone is a situation full of hidden difficulties and possible mistakes.","zh":"a minefield for someone 指對某人來說充滿隱藏困難和可能錯誤的情況。"},{"en":"Choosing a school can be a minefield for parents if every website makes different claims.","zh":"如果每個網站都作出不同聲稱，選學校對家長來說可能是一個複雜局面。"},{"en":"Eco-tourism becomes a minefield when labels sound green but standards are unclear.","zh":"當旅遊標籤聽起來環保但標準不清，生態旅遊就會變成容易出錯的局面。"},{"en":"The phrase suggests people must move carefully to avoid problems.","zh":"這個短語暗示人們必須小心行動，以避免問題。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":1},{"front":"well-meaning traveller","meaning":"出於好意的旅客","examples":[{"en":"A well-meaning traveller may find eco-friendly holidays confusing.","zh":"出於好意的旅客可能覺得環保假期令人困惑。"},{"en":"A well-meaning traveller is a tourist who wants to do the right thing but may not know how.","zh":"well-meaning traveller 指想做正確事情但未必知道怎樣做的旅客。"},{"en":"A well-meaning traveller may avoid plastic bottles but still accidentally book a harmful tour.","zh":"出於好意的旅客可能避免使用膠樽，卻仍意外預訂有害的旅行團。"},{"en":"Without clear information, well-meaning travellers can support bad operators by mistake.","zh":"如果缺乏清晰資訊，出於好意的旅客可能錯誤支持不良營辦商。"},{"en":"The phrase is sympathetic; it describes good intentions, not foolishness.","zh":"這個短語帶同情意味；它描述好意，而不是愚蠢。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":1},{"front":"help is at hand","meaning":"幫助近在眼前","examples":[{"en":"Help is now at hand for travellers who want greener holidays.","zh":"對想要更綠色假期的旅客來說，幫助現在近在眼前。"},{"en":"Help is at hand means support or a solution is now available nearby or soon.","zh":"help is at hand 指支援或解決方法現在可取得、就在附近或即將出現。"},{"en":"If a student is confused by an application form, help is at hand when the school opens a support desk.","zh":"如果學生對申請表感到困惑，學校開設支援櫃位時，幫助就近在眼前。"},{"en":"For eco-tourists, guidebooks and accreditation lists mean help is at hand.","zh":"對生態旅客而言，指南和認證名冊表示幫助近在眼前。"},{"en":"The phrase gives reassurance that the problem can be solved.","zh":"這個短語令人安心，表示問題可以解決。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":1},{"front":"awards for","meaning":"……的獎項","examples":[{"en":"If there were awards for misused tourism phrases, ecotourism would win.","zh":"如果有「被濫用旅遊用語」的獎項，生態旅遊會勝出。"},{"en":"Awards for something are prizes or recognition given because of that quality or achievement.","zh":"awards for something 指因某種特質或成就而給予的獎項或認可。"},{"en":"A school may give awards for kindness, improvement, and teamwork.","zh":"學校可能頒發善良、進步和團隊合作的獎項。"},{"en":"Saying there should be awards for misused phrases is humorous because misuse is not normally rewarded.","zh":"說應該有濫用短語的獎項帶幽默意味，因為濫用通常不會獲獎。"},{"en":"The phrase can be used seriously or ironically, depending on context.","zh":"這個短語可按語境作認真或諷刺用法。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":1},{"front":"tourism phrases","meaning":"旅遊用語","examples":[{"en":"Some tourism phrases have been misused by advertisers.","zh":"一些旅遊用語被廣告商濫用。"},{"en":"Tourism phrases are words or expressions used to describe travel, holidays, and tourist experiences.","zh":"tourism phrases 指用來描述旅遊、假期和遊客體驗的詞語或表達。"},{"en":"Phrases like “authentic experience” and “hidden paradise” are common tourism phrases.","zh":"“authentic experience” 和 “hidden paradise” 這類短語都是常見旅遊用語。"},{"en":"When tourism phrases are used too loosely, travellers may misunderstand what they are buying.","zh":"當旅遊用語使用得太寬鬆，旅客可能誤解自己購買的是甚麼。"},{"en":"The phrase refers to language used in the travel industry.","zh":"這個短語指旅遊業使用的語言。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":1},{"front":"be hijacked","meaning":"被挪用；被騎劫","examples":[{"en":"The term ecotourism has been hijacked by marketers.","zh":"ecotourism 這個詞已被市場推廣人員挪用。"},{"en":"To be hijacked means to be taken over and used for someone else’s purpose.","zh":"be hijacked 指被奪取並用於別人的目的。"},{"en":"A serious discussion can be hijacked when people turn it into advertising.","zh":"當人們把嚴肅討論變成廣告，它就可能被騎劫。"},{"en":"If a green label is hijacked by companies, its original meaning becomes weaker.","zh":"如果綠色標籤被公司挪用，其原本意思就會變弱。"},{"en":"The phrase suggests unfair or inappropriate control.","zh":"這個短語暗示不公平或不恰當的控制。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":1},{"front":"be diluted","meaning":"被淡化","examples":[{"en":"The meaning of ecotourism has been diluted.","zh":"生態旅遊的意思已被淡化。"},{"en":"To be diluted means to become weaker, less clear, or less powerful.","zh":"be diluted 指變得較弱、較不清楚或較沒有力量。"},{"en":"A school rule is diluted if teachers apply it only sometimes.","zh":"如果老師只是有時執行某校規，該規則就被淡化。"},{"en":"When every nature trip is called ecotourism, the term is diluted.","zh":"當每個自然旅行都被稱為生態旅遊，這個詞就被淡化。"},{"en":"The phrase suggests the original strength or meaning has been reduced.","zh":"這個短語暗示原本力量或意思被削弱。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":1},{"front":"be misused","meaning":"被濫用","examples":[{"en":"The term ecotourism has been misused.","zh":"ecotourism 這個詞已被濫用。"},{"en":"To be misused means to be used incorrectly or in a way that distorts the original meaning.","zh":"be misused 指被錯誤使用，或以扭曲原意的方式使用。"},{"en":"The word “organic” can be misused if a product is not truly grown without certain chemicals.","zh":"如果產品並非真正不使用某些化學品種植，organic 一詞就可能被濫用。"},{"en":"When a label is misused, consumers may believe claims that are not accurate.","zh":"當標籤被濫用，消費者可能相信不準確的聲稱。"},{"en":"The phrase points to wrong or misleading use.","zh":"這個短語指錯誤或誤導性的使用。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":1},{"front":"earn top prize","meaning":"贏得最高獎項","examples":[{"en":"Ecotourism would earn top prize for being misused.","zh":"生態旅遊會因被濫用而贏得最高獎項。"},{"en":"To earn top prize means to be judged the best or most extreme example in a competition.","zh":"earn top prize 指在比賽中被評為最好或最極端的例子。"},{"en":"A student may earn top prize for a science project that solves a real problem.","zh":"如果學生的科學項目解決真實問題，他可能贏得最高獎項。"},{"en":"Here, the phrase is ironic because being misused is not a good achievement.","zh":"在這裡，這個短語帶諷刺意味，因為被濫用不是好成就。"},{"en":"The expression highlights how serious or obvious the misuse is.","zh":"這個表達突出濫用有多嚴重或明顯。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":1},{"front":"the term first surfaced","meaning":"這個詞首次出現","examples":[{"en":"The term ecotourism first surfaced in the early 1980s.","zh":"ecotourism 這個詞首次出現在1980年代初。"},{"en":"If a term first surfaced at a time, it first appeared or became noticeable then.","zh":"如果一個詞 first surfaced 於某時，意思是它在那時首次出現或變得受注意。"},{"en":"The phrase “digital detox” first surfaced when people began worrying about too much screen time.","zh":"當人們開始擔心螢幕時間過多，“digital detox” 這個短語首次出現。"},{"en":"When a term first surfaces, its meaning may still be new and unsettled.","zh":"當一個詞首次出現時，它的意思可能仍然新且未穩定。"},{"en":"The phrase is useful for explaining the origin of a word.","zh":"這個短語適合解釋詞語起源。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":2},{"front":"the early 1980s","meaning":"1980年代初","examples":[{"en":"The term first surfaced in the early 1980s.","zh":"這個詞首次出現在1980年代初。"},{"en":"The early 1980s means the first few years of the 1980s decade.","zh":"the early 1980s 指1980年代的最初幾年。"},{"en":"Many environmental ideas became more visible in public discussion in the early 1980s.","zh":"許多環保概念在1980年代初的公共討論中變得更顯眼。"},{"en":"If a word appeared in the early 1980s, it became known around that historical period.","zh":"如果一個詞出現在1980年代初，它就是在那段歷史時期左右開始被認識。"},{"en":"The phrase gives a general time, not one exact year.","zh":"這個短語提供大約時間，而不是確切年份。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":2},{"front":"reflect a surge in","meaning":"反映……急升","examples":[{"en":"The term reflected a surge in environmental awareness.","zh":"這個詞反映環保意識急升。"},{"en":"To reflect a surge in something means to show that it has risen quickly or become much stronger.","zh":"reflect a surge in something 指顯示某事迅速上升或變得強烈得多。"},{"en":"More bicycle lanes may reflect a surge in public interest in clean transport.","zh":"更多單車徑可能反映公眾對潔淨交通的興趣急升。"},{"en":"If eco-tourism grew quickly, it reflected a surge in concern about nature.","zh":"如果生態旅遊迅速增長，它反映人們對自然的關注急升。"},{"en":"The phrase links a visible change with a deeper social trend.","zh":"這個短語把可見變化與較深層社會趨勢連起來。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":2},{"front":"environmental awareness","meaning":"環保意識","examples":[{"en":"Ecotourism grew with environmental awareness.","zh":"生態旅遊隨着環保意識而增長。"},{"en":"Environmental awareness is understanding that human actions can harm or protect nature.","zh":"environmental awareness 指理解人類行為可以傷害或保護自然。"},{"en":"Schools build environmental awareness when students learn about waste, energy, and wildlife.","zh":"學校讓學生學習廢物、能源和野生動物時，就是建立環保意識。"},{"en":"Greater environmental awareness can make travellers choose hotels and tours more carefully.","zh":"更高的環保意識可以令旅客更小心選擇酒店和旅行團。"},{"en":"The phrase refers to concern and knowledge about the environment.","zh":"這個短語指對環境的關心和知識。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":2},{"front":"a realisation by","meaning":"……意識到","examples":[{"en":"The term reflected a realisation by tour operators.","zh":"這個詞反映旅遊營辦商意識到某事。"},{"en":"A realisation by someone is the moment when that person or group understands something important.","zh":"realisation by someone 指某人或某群體明白重要事情的時刻。"},{"en":"A realisation by teachers that students are tired may lead to shorter homework.","zh":"老師意識到學生疲倦，可能導致功課縮短。"},{"en":"A realisation by tour operators that tourists care about nature changed how holidays were marketed.","zh":"旅遊營辦商意識到遊客關心自然，改變了假期的推廣方式。"},{"en":"The phrase points to a new understanding that affects later action.","zh":"這個短語指出影響後續行動的新理解。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":2},{"front":"tour operators","meaning":"旅行社；旅遊營辦商","examples":[{"en":"Tour operators realised that travellers cared about their impact abroad.","zh":"旅遊營辦商意識到旅客關心自己在外地造成的影響。"},{"en":"Tour operators are companies or people who organise and sell travel experiences.","zh":"tour operators 指組織並銷售旅遊體驗的公司或人士。"},{"en":"Tour operators may arrange transport, hotels, guides, and activities for visitors.","zh":"旅遊營辦商可能為遊客安排交通、酒店、導遊和活動。"},{"en":"If tour operators make false green claims, travellers may support harmful trips by mistake.","zh":"如果旅遊營辦商作出虛假環保聲稱，旅客可能錯誤支持有害旅程。"},{"en":"The phrase refers to businesses that run tours, not the tourists themselves.","zh":"這個短語指營辦旅遊的企業，而不是旅客本身。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":2},{"front":"presence abroad","meaning":"在外地的存在","examples":[{"en":"Travellers wanted to believe their presence abroad would not cause harm.","zh":"旅客希望相信自己在外地的存在不會造成傷害。"},{"en":"Presence abroad means being physically in another country as a visitor, worker, or resident.","zh":"presence abroad 指作為訪客、工人或居民身處另一個國家。"},{"en":"A volunteer should think about how their presence abroad affects local people.","zh":"義工應思考自己在外地的存在如何影響本地人。"},{"en":"If many tourists arrive in a small village, their presence abroad can change prices and daily life.","zh":"如果許多遊客到達小村莊，他們在外地的存在可以改變價格和日常生活。"},{"en":"The phrase focuses on the effects of being in a foreign place.","zh":"這個短語重點是在外國地方存在所造成的影響。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":2},{"front":"have a negative impact","meaning":"造成負面影響","examples":[{"en":"Many travellers wanted holidays that would not have a negative impact.","zh":"許多旅客想要不會造成負面影響的假期。"},{"en":"To have a negative impact means to cause harm or an unwanted effect.","zh":"have a negative impact 指造成傷害或不想要的影響。"},{"en":"Too much noise can have a negative impact on students’ concentration.","zh":"太多噪音可以對學生專注力造成負面影響。"},{"en":"Tourism can have a negative impact if it damages habitats or pushes up local prices.","zh":"如果旅遊破壞棲息地或推高本地價格，它可以造成負面影響。"},{"en":"The phrase is useful for discussing harmful consequences.","zh":"這個短語適合討論有害後果。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":2},{"front":"rapidly became","meaning":"迅速變成","examples":[{"en":"Ecotourism rapidly became a powerful marketing label.","zh":"生態旅遊迅速變成強大的市場推廣標籤。"},{"en":"Rapidly became means changed into something quickly.","zh":"rapidly became 指快速變成某事物。"},{"en":"A small online trend can rapidly become a major business opportunity.","zh":"一個小型網上潮流可以迅速變成重大商機。"},{"en":"When travellers began caring about the environment, ecotourism rapidly became attractive to advertisers.","zh":"當旅客開始關心環境，生態旅遊迅速變得吸引廣告商。"},{"en":"The phrase highlights speed of change.","zh":"這個短語突出變化速度。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":2},{"front":"hottest marketing tag","meaning":"最熱門的市場推廣標籤","examples":[{"en":"Ecotourism became the hottest marketing tag a holiday could carry.","zh":"生態旅遊成為一個假期可以帶有的最熱門市場推廣標籤。"},{"en":"The hottest marketing tag is the most attractive label used to sell something.","zh":"hottest marketing tag 指用來銷售某物的最吸引標籤。"},{"en":"“Smart” became a hot marketing tag for phones, watches, and homes.","zh":"“Smart” 曾成為電話、手錶和家居產品的熱門市場推廣標籤。"},{"en":"When a tag becomes popular, companies may use it even when their product barely fits.","zh":"當一個標籤變得流行，公司可能即使產品不太符合也使用它。"},{"en":"The phrase suggests strong commercial appeal.","zh":"這個短語暗示強烈商業吸引力。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":2},{"front":"these days","meaning":"現今","examples":[{"en":"These days, the ecotourism label is used very broadly.","zh":"現今，生態旅遊標籤被非常廣泛地使用。"},{"en":"These days means nowadays or in the present period.","zh":"these days 指現今或現在這段時期。"},{"en":"These days, many students use online dictionaries more than paper ones.","zh":"現今，許多學生使用網上字典多於紙本字典。"},{"en":"If a term is used broadly these days, its meaning may be less precise than before.","zh":"如果一個詞現今被廣泛使用，它的意思可能比以前較不精確。"},{"en":"The phrase contrasts the present with the past.","zh":"這個短語把現在與過去作對比。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":2},{"front":"ecotourism label","meaning":"生態旅遊標籤","examples":[{"en":"The ecotourism label is used to cover many types of tour.","zh":"生態旅遊標籤被用來涵蓋許多類型的旅行團。"},{"en":"An ecotourism label is a name or description suggesting that a tour is environmentally responsible.","zh":"ecotourism label 指暗示某旅行團對環境負責的名稱或描述。"},{"en":"A rainforest walk may carry an ecotourism label if it claims to protect nature.","zh":"如果雨林徒步旅行聲稱保護自然，它可能帶有生態旅遊標籤。"},{"en":"If the label is not checked, travellers may not know whether the tour is truly responsible.","zh":"如果標籤沒有被查核，旅客可能不知道旅行團是否真正負責任。"},{"en":"The phrase refers to branding, not proof by itself.","zh":"這個短語指品牌標籤，本身不是證明。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":3},{"front":"be used to cover","meaning":"被用來涵蓋","examples":[{"en":"The label is used to cover many different holiday experiences.","zh":"這個標籤被用來涵蓋許多不同假期體驗。"},{"en":"To be used to cover something means to be applied broadly to include many things.","zh":"be used to cover something 指被廣泛套用以包括許多事物。"},{"en":"The word “wellness” is used to cover gyms, food plans, retreats, and apps.","zh":"“wellness” 一詞被用來涵蓋健身室、飲食計劃、靜修和應用程式。"},{"en":"When one label covers too many products, consumers may become confused.","zh":"當一個標籤涵蓋太多產品，消費者可能感到困惑。"},{"en":"The phrase can suggest that a term has become too wide.","zh":"這個短語可以暗示某詞變得過於寬泛。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":3},{"front":"anything from…to…","meaning":"從……到……任何東西","examples":[{"en":"Ecotourism can mean anything from tribal visits to motorboat trips.","zh":"生態旅遊可以指從部落探訪到機動船旅程的任何東西。"},{"en":"Anything from A to B means a very wide range of examples between two extremes.","zh":"anything from A to B 指從兩個極端之間的非常廣泛例子。"},{"en":"A school fair may sell anything from handmade cards to hot meals.","zh":"學校市集可能售賣從手製卡片到熱食的任何東西。"},{"en":"If one label covers anything from quiet village stays to fast boat rides, its meaning becomes unclear.","zh":"如果一個標籤涵蓋從安靜村莊住宿到高速船程的任何東西，它的意思就變得不清楚。"},{"en":"The phrase stresses variety and breadth.","zh":"這個短語強調種類多和範圍廣。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":3},{"front":"remote Indonesian tribes","meaning":"偏遠印尼部落","examples":[{"en":"Some ecotours involve living with remote Indonesian tribes.","zh":"一些生態旅遊涉及與偏遠印尼部落共同生活。"},{"en":"Remote Indonesian tribes are indigenous or traditional groups living far from major cities in Indonesia.","zh":"remote Indonesian tribes 指生活在印尼遠離主要城市的原住民或傳統群體。"},{"en":"A tour to remote tribes must respect local customs, privacy, and community decisions.","zh":"到訪偏遠部落的旅行必須尊重本地習俗、私隱和社區決定。"},{"en":"If tourism is careless, visits to remote communities can disturb daily life and culture.","zh":"如果旅遊處理不慎，到訪偏遠社區可能干擾日常生活和文化。"},{"en":"The phrase describes distance and cultural setting, not a tourist attraction by itself.","zh":"這個短語描述距離和文化背景，而不是本身就是旅遊景點。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":3},{"front":"motorboat trip","meaning":"機動船旅程","examples":[{"en":"A short motorboat trip may also be labelled ecotourism.","zh":"短程機動船旅程也可能被標籤為生態旅遊。"},{"en":"A motorboat trip is a journey taken in a boat powered by an engine.","zh":"motorboat trip 指乘坐由引擎推動的船隻進行的旅程。"},{"en":"A family may take a motorboat trip across a lake during a holiday.","zh":"一個家庭可能在假期乘機動船橫渡湖泊。"},{"en":"If a motorboat trip creates noise, fuel pollution, or wildlife disturbance, calling it eco-friendly may be questionable.","zh":"如果機動船旅程造成噪音、燃油污染或干擾野生動物，把它稱為環保可能有問題。"},{"en":"The phrase describes transport activity, not necessarily environmental responsibility.","zh":"這個短語描述交通活動，不一定表示對環境負責。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":3},{"front":"Australian gorge","meaning":"澳洲峽谷","examples":[{"en":"A motorboat trip through an Australian gorge may be called ecotourism.","zh":"穿越澳洲峽谷的機動船旅程可能被稱為生態旅遊。"},{"en":"An Australian gorge is a deep narrow valley in Australia, often with cliffs and a river.","zh":"Australian gorge 指澳洲的深而狹窄山谷，通常有峭壁和河流。"},{"en":"Tourists may visit an Australian gorge to see rock formations, wildlife, and scenery.","zh":"遊客可能到訪澳洲峽谷觀賞岩石地貌、野生動物和景色。"},{"en":"If too many boats enter a gorge, the natural environment may be disturbed.","zh":"如果太多船隻進入峽谷，自然環境可能受到干擾。"},{"en":"The phrase gives a natural location used in tourism marketing.","zh":"這個短語提供旅遊推廣中使用的自然地點。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":3},{"front":"in fact","meaning":"事實上","examples":[{"en":"In fact, many different tours are now called ecotourism.","zh":"事實上，許多不同旅行團現在都被稱為生態旅遊。"},{"en":"In fact introduces a true detail that explains, corrects, or strengthens the previous point.","zh":"in fact 引入一個真實細節，用來解釋、修正或加強前一點。"},{"en":"The hotel looks expensive; in fact, it is cheaper than the hostel nearby.","zh":"這間酒店看起來昂貴；事實上，它比附近青年旅舍更便宜。"},{"en":"Writers use in fact when the next sentence gives clearer evidence.","zh":"寫作者在下一句提供更清楚證據時會使用 in fact。"},{"en":"The phrase often signals that the real situation may be broader than expected.","zh":"這個短語通常表示真實情況可能比預期更廣。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":3},{"front":"involve cultural interaction","meaning":"涉及文化交流","examples":[{"en":"Some tours involve cultural interaction with local people.","zh":"一些旅行團涉及與本地人的文化交流。"},{"en":"To involve cultural interaction means to include contact and exchange between people from different cultures.","zh":"involve cultural interaction 指包括不同文化的人之間的接觸和交流。"},{"en":"A cooking class with local families can involve cultural interaction.","zh":"與本地家庭一起上的烹飪課可以涉及文化交流。"},{"en":"Cultural interaction can be valuable, but it should respect local people rather than turn them into entertainment.","zh":"文化交流可以有價值，但應尊重本地人，而不是把他們變成娛樂。"},{"en":"The phrase focuses on meaningful contact, not simply looking at a place.","zh":"這個短語重點是有意義的接觸，而不是單純觀看一個地方。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":3},{"front":"natural beauty spots","meaning":"自然景點","examples":[{"en":"Many ecotours include natural beauty spots.","zh":"許多生態旅遊包括自然景點。"},{"en":"Natural beauty spots are places valued for scenery, wildlife, landscapes, or unspoilt nature.","zh":"natural beauty spots 指因景色、野生動物、地貌或未受破壞自然環境而受重視的地方。"},{"en":"Lakes, forests, cliffs, and waterfalls can be natural beauty spots.","zh":"湖泊、森林、峭壁和瀑布都可以是自然景點。"},{"en":"Popular beauty spots may suffer if too many tourists visit without controls.","zh":"如果太多遊客在沒有管制下到訪，受歡迎自然景點可能受損。"},{"en":"The phrase refers to attractive natural places, not man-made attractions.","zh":"這個短語指吸引人的自然地方，而不是人造景點。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":3},{"front":"a dash of","meaning":"少量；一點","examples":[{"en":"A dash of soft adventure may help a holiday be called ecotourism.","zh":"一點輕度探險活動可能幫助一個假期被稱為生態旅遊。"},{"en":"A dash of something means a small amount of it added to something else.","zh":"a dash of something 指在某物中加入少量某元素。"},{"en":"A soup may need a dash of salt to improve its taste.","zh":"一碗湯可能需要一點鹽來改善味道。"},{"en":"A tour may add a dash of adventure to make it sound more exciting.","zh":"旅行團可能加入一點探險元素，使它聽起來更刺激。"},{"en":"The phrase suggests a small addition, not the main feature.","zh":"這個短語暗示小量加入，而不是主要特徵。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":3},{"front":"soft adventure","meaning":"輕度探險活動","examples":[{"en":"Soft adventure is often included under the ecotourism label.","zh":"輕度探險活動常被納入生態旅遊標籤之下。"},{"en":"Soft adventure means light outdoor activity that feels exciting but is not extremely risky.","zh":"soft adventure 指感覺刺激但風險不極高的輕量戶外活動。"},{"en":"Easy kayaking, short hikes, and guided cycling can be soft adventure.","zh":"簡單划艇、短途行山和導賞單車都可以是輕度探險活動。"},{"en":"Soft adventure attracts travellers who want activity without serious danger or specialist training.","zh":"輕度探險活動吸引想活動但不想承受嚴重危險或接受專門訓練的旅客。"},{"en":"The phrase contrasts with extreme adventure such as mountaineering or deep-sea diving.","zh":"這個短語與登山或深海潛水等極限探險形成對比。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":3},{"front":"be likely to be included in","meaning":"很可能被納入……","examples":[{"en":"Many nature-based tours are likely to be included in ecotourism.","zh":"許多以自然為基礎的旅行團很可能被納入生態旅遊。"},{"en":"To be likely to be included in something means to probably be counted as part of it.","zh":"be likely to be included in something 指很可能被視為某事的一部分。"},{"en":"A short writing task is likely to be included in an English exam.","zh":"短寫作任務很可能被納入英文考試。"},{"en":"If a trip includes forests, wildlife, and local culture, marketers may include it under ecotourism.","zh":"如果一個旅程包括森林、野生動物和本地文化，市場推廣人員可能把它納入生態旅遊。"},{"en":"The phrase shows probability, not certainty.","zh":"這個短語表示可能性，而不是確定性。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":4},{"front":"overflowing ecotourism folder","meaning":"過度膨脹的生態旅遊類別","examples":[{"en":"The ecotourism category has become an overflowing folder.","zh":"生態旅遊這個類別已變成一個過度膨脹的資料夾。"},{"en":"An overflowing folder is a metaphor for a category that contains too many mixed items.","zh":"overflowing folder 是比喻，指一個類別包含太多混雜項目。"},{"en":"A teacher’s folder overflows when every unrelated worksheet is put into it.","zh":"如果每張無關工作紙都放進老師的資料夾，資料夾就會爆滿。"},{"en":"When ecotourism includes too many different trips, the label becomes an overflowing folder.","zh":"當生態旅遊包括太多不同旅程，這個標籤就變成過度膨脹的類別。"},{"en":"The phrase suggests the category is overloaded and badly organised.","zh":"這個短語暗示類別負荷過重且組織混亂。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":4},{"front":"there is no doubt that","meaning":"毫無疑問","examples":[{"en":"There is no doubt that the original motives were honourable.","zh":"毫無疑問，最初動機是高尚的。"},{"en":"There is no doubt that means the writer is very sure about the statement.","zh":"there is no doubt that 指作者對該陳述非常肯定。"},{"en":"There is no doubt that clear examples help students learn vocabulary faster.","zh":"毫無疑問，清晰例子幫助學生更快學習詞彙。"},{"en":"When evidence is strong, writers use this phrase to show confidence.","zh":"當證據強，寫作者會使用這個短語表示信心。"},{"en":"The phrase expresses certainty, not hesitation.","zh":"這個短語表達肯定，而不是猶豫。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":4},{"front":"original motives","meaning":"最初動機","examples":[{"en":"The original motives behind ecotourism were honourable.","zh":"生態旅遊背後的最初動機是高尚的。"},{"en":"Original motives are the first reasons or intentions behind an action or movement.","zh":"original motives 指行動或運動背後最初的原因或意圖。"},{"en":"A charity’s original motives may be to help poor families, even if it later becomes commercial.","zh":"慈善機構的最初動機可能是幫助貧困家庭，即使後來變得商業化。"},{"en":"If original motives are forgotten, a movement can drift away from its purpose.","zh":"如果最初動機被忘記，運動可能偏離其目的。"},{"en":"The phrase looks back to why something began.","zh":"這個短語回顧某事為何開始。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":4},{"front":"honourable attempts","meaning":"高尚的嘗試","examples":[{"en":"Ecotourism began with honourable attempts to help travellers choose responsibly.","zh":"生態旅遊始於幫助旅客負責任選擇的高尚嘗試。"},{"en":"Honourable attempts are sincere efforts made for a good or morally respectable purpose.","zh":"honourable attempts 指出於良好或道德上值得尊重目的的真誠努力。"},{"en":"A school may make honourable attempts to reduce waste by teaching recycling.","zh":"學校透過教授回收來減少浪費，可能是一種高尚嘗試。"},{"en":"Even if an attempt fails, it can still be honourable if the intention is honest and responsible.","zh":"即使嘗試失敗，只要意圖誠實和負責任，仍可以是高尚的。"},{"en":"The phrase praises the purpose behind an action.","zh":"這個短語讚揚行動背後的目的。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":4},{"front":"provide a way for","meaning":"為……提供方法","examples":[{"en":"The movement provided a way for travellers to make informed choices.","zh":"這場運動為旅客提供方法去作出知情選擇。"},{"en":"To provide a way for someone means to give them a method or opportunity to do something.","zh":"provide a way for someone 指給某人做某事的方法或機會。"},{"en":"Clear labels provide a way for shoppers to compare products fairly.","zh":"清晰標籤為購物者提供方法公平比較產品。"},{"en":"Good travel information provides a way for tourists to support responsible operators.","zh":"良好旅遊資訊為遊客提供方法支持負責任營辦商。"},{"en":"The phrase focuses on enabling action.","zh":"這個短語重點是使行動成為可能。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":4},{"front":"those who cared","meaning":"關心的人","examples":[{"en":"Ecotourism was meant for those who cared about the environment.","zh":"生態旅遊原本是為關心環境的人而設。"},{"en":"Those who cared means the people who felt concern and wanted to act responsibly.","zh":"those who cared 指感到關注並想負責任行動的人。"},{"en":"A recycling campaign may attract those who cared about waste in their community.","zh":"回收活動可能吸引關心社區廢物問題的人。"},{"en":"If information is unclear, even those who care may make poor choices.","zh":"如果資訊不清，即使關心的人也可能作出差劣選擇。"},{"en":"The phrase points to people with concern, not casual consumers.","zh":"這個短語指有關心的人，而不是隨意消費者。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":4},{"front":"make informed choices","meaning":"作出知情選擇","examples":[{"en":"Responsible travellers wanted to make informed choices.","zh":"負責任的旅客想作出知情選擇。"},{"en":"To make informed choices means to decide after understanding the facts, risks, and options.","zh":"make informed choices 指在了解事實、風險和選項後作出決定。"},{"en":"Patients make informed choices when doctors explain benefits and side effects clearly.","zh":"當醫生清楚解釋好處和副作用，病人就能作出知情選擇。"},{"en":"Travellers can make informed choices by checking who owns a tour and how money is used.","zh":"旅客可以透過查核旅行團由誰擁有和金錢如何使用來作出知情選擇。"},{"en":"The phrase contrasts careful decision-making with blind trust.","zh":"這個短語把謹慎決策與盲目信任作對比。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":4},{"front":"lack of regulations","meaning":"缺乏規管","examples":[{"en":"The lack of regulations made ecotourism confusing.","zh":"缺乏規管令生態旅遊令人困惑。"},{"en":"A lack of regulations means there are not enough clear rules controlling an activity.","zh":"lack of regulations 指沒有足夠清晰規則控制某活動。"},{"en":"A market with a lack of regulations may allow unsafe products to be sold.","zh":"缺乏規管的市場可能容許不安全產品出售。"},{"en":"Without regulations, companies can make green claims that nobody checks.","zh":"如果沒有規管，公司可以作出無人查核的環保聲稱。"},{"en":"The phrase explains why consumers may feel uncertain.","zh":"這個短語解釋為何消費者可能感到不確定。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":4},{"front":"standard industry definition","meaning":"業界標準定義","examples":[{"en":"Ecotourism lacks a standard industry definition.","zh":"生態旅遊缺乏業界標準定義。"},{"en":"A standard industry definition is an agreed meaning used across a whole business sector.","zh":"standard industry definition 指整個行業共同使用的公認意思。"},{"en":"A standard definition helps hotels, travellers, and regulators understand the same term in the same way.","zh":"標準定義幫助酒店、旅客和監管者以相同方式理解同一詞語。"},{"en":"Without one, companies may call very different products by the same name.","zh":"如果沒有標準定義，公司可能用同一名稱稱呼非常不同的產品。"},{"en":"The phrase stresses shared meaning and consistency.","zh":"這個短語強調共同意思和一致性。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":4},{"front":"leave travellers lost","meaning":"令旅客不知所措","examples":[{"en":"The lack of standards left many travellers lost.","zh":"缺乏標準令許多旅客不知所措。"},{"en":"To leave travellers lost means to make tourists confused and unsure what to choose.","zh":"leave travellers lost 指令遊客困惑，不知道該選甚麼。"},{"en":"Too many similar hotel labels can leave travellers lost when they try to book responsibly.","zh":"太多相似酒店標籤可以令旅客在負責任預訂時不知所措。"},{"en":"If travellers are lost, they may simply choose the cheapest or most attractive advertisement.","zh":"如果旅客不知所措，他們可能只選最便宜或廣告最吸引的選項。"},{"en":"The phrase describes confusion, not physical getting lost.","zh":"這個短語描述困惑，而不是實際迷路。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":4},{"front":"ecotourism jungle","meaning":"生態旅遊的混亂局面","examples":[{"en":"Many travellers were lost in an ecotourism jungle.","zh":"許多旅客迷失在生態旅遊的混亂局面中。"},{"en":"An ecotourism jungle is a metaphor for a confusing market full of unclear green claims.","zh":"ecotourism jungle 是比喻，指充滿不清楚環保聲稱的混亂市場。"},{"en":"A consumer may feel trapped in a jungle of labels when every tour says it is responsible.","zh":"當每個旅行團都說自己負責任，消費者可能覺得被困在標籤叢林中。"},{"en":"The jungle exists because standards are weak and marketing is strong.","zh":"這個混亂局面之所以存在，是因為標準薄弱而市場推廣強大。"},{"en":"The phrase suggests travellers need guidance to find a trustworthy path.","zh":"這個短語暗示旅客需要指引，才能找到可信路線。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":5},{"front":"it is easier to understand why","meaning":"較容易明白為何……","examples":[{"en":"It is easier to understand why the market is overcrowded when we look at its value.","zh":"當我們看其價值時，較容易明白為何市場變得擁擠。"},{"en":"It is easier to understand why means the reason becomes clearer after considering certain information.","zh":"it is easier to understand why 指在考慮某些資訊後，原因變得更清楚。"},{"en":"It is easier to understand why students are tired when we see their homework load.","zh":"當我們看到學生的功課量，就較容易明白為何他們疲倦。"},{"en":"When a market is worth billions, it is easier to understand why many companies enter it.","zh":"當一個市場價值達數十億，就較容易明白為何許多公司進入。"},{"en":"The phrase prepares readers for an explanation.","zh":"這個短語為讀者準備解釋。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":5},{"front":"ecotourism market","meaning":"生態旅遊市場","examples":[{"en":"The ecotourism market has become overcrowded.","zh":"生態旅遊市場已變得擁擠。"},{"en":"The ecotourism market is the business area where eco-labelled trips are sold and bought.","zh":"ecotourism market 指銷售和購買帶環保標籤旅程的商業領域。"},{"en":"Hotels, guides, tour companies, and travellers all belong to the ecotourism market.","zh":"酒店、導遊、旅遊公司和旅客都屬於生態旅遊市場。"},{"en":"A profitable market attracts more operators, which can make quality harder to judge.","zh":"有利可圖的市場會吸引更多營辦商，使質素更難判斷。"},{"en":"The phrase refers to the commercial side of eco-travel.","zh":"這個短語指環保旅遊的商業一面。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":5},{"front":"become so overcrowded","meaning":"變得如此擠擁","examples":[{"en":"The market has become so overcrowded because it is profitable.","zh":"這個市場因為有利可圖而變得如此擠擁。"},{"en":"To become so overcrowded means to become filled with too many people, businesses, or options.","zh":"become so overcrowded 指變得充滿太多人、企業或選項。"},{"en":"A popular night market can become overcrowded when tourists and locals arrive at the same time.","zh":"當遊客和本地人同時到達，受歡迎夜市可以變得非常擠迫。"},{"en":"If a travel trend is profitable, too many companies may enter and crowd the market.","zh":"如果一種旅遊潮流有利可圖，太多公司可能加入並擠滿市場。"},{"en":"The phrase suggests excessive competition and confusion.","zh":"這個短語暗示競爭和混亂過多。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":5},{"front":"wider role in","meaning":"在……中的更廣泛角色","examples":[{"en":"The passage examines ecotourism’s wider role in the world economy.","zh":"文章檢視生態旅遊在世界經濟中的更廣泛角色。"},{"en":"A wider role in something means a broader importance or function beyond one small area.","zh":"wider role in something 指超越某個小範圍的更廣泛重要性或功能。"},{"en":"Public transport has a wider role in city life because it affects work, air quality, and equality.","zh":"公共交通在城市生活中有更廣泛角色，因為它影響工作、空氣質素和平等。"},{"en":"Ecotourism has a wider role when it influences jobs, conservation, and international tourism.","zh":"當生態旅遊影響就業、保育和國際旅遊時，它就有更廣泛角色。"},{"en":"The phrase asks readers to see the bigger picture.","zh":"這個短語要求讀者看見更大的圖景。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":5},{"front":"world economy","meaning":"世界經濟","examples":[{"en":"Ecotourism has a significant role in the world economy.","zh":"生態旅遊在世界經濟中有重要角色。"},{"en":"The world economy is the system of trade, money, production, and services across countries.","zh":"world economy 指跨國的貿易、金錢、生產和服務系統。"},{"en":"Tourism, technology, farming, and energy are all parts of the world economy.","zh":"旅遊、科技、農業和能源都是世界經濟的一部分。"},{"en":"When international travel grows, it can affect jobs and income in many countries.","zh":"當國際旅遊增長，它可以影響許多國家的工作和收入。"},{"en":"The phrase refers to economic connections beyond one nation.","zh":"這個短語指超越單一國家的經濟連繫。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":5},{"front":"according to","meaning":"根據","examples":[{"en":"According to World Tourism Organisation figures, ecotourism is worth billions.","zh":"根據世界旅遊組織數字，生態旅遊價值達數十億。"},{"en":"According to means based on information from a named source.","zh":"according to 指根據某個具名來源的資訊。"},{"en":"According to the timetable, the train leaves at nine.","zh":"根據時間表，火車九點開出。"},{"en":"Writers use according to when they want to show where information comes from.","zh":"寫作者想顯示資訊來源時會使用 according to。"},{"en":"The phrase introduces evidence or reported information.","zh":"這個短語引入證據或被報告的資訊。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":5},{"front":"World Tourism Organisation figures","meaning":"世界旅遊組織數字","examples":[{"en":"World Tourism Organisation figures show the value of ecotourism.","zh":"世界旅遊組織數字顯示生態旅遊的價值。"},{"en":"World Tourism Organisation figures are statistics reported by an international tourism body.","zh":"World Tourism Organisation figures 指由國際旅遊機構報告的統計數字。"},{"en":"Such figures can show tourist numbers, spending, growth rates, and market size.","zh":"這些數字可以顯示旅客人數、消費、增長率和市場規模。"},{"en":"When official figures show high value, more operators may enter the market.","zh":"當官方數字顯示高價值，更多營辦商可能進入市場。"},{"en":"The phrase refers to data, not personal opinion.","zh":"這個短語指數據，而不是個人意見。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":5},{"front":"be worth","meaning":"價值達","examples":[{"en":"Ecotourism is worth US$20 billion a year.","zh":"生態旅遊每年價值達200億美元。"},{"en":"To be worth an amount means to have that financial value.","zh":"be worth an amount 指具有某個金錢價值。"},{"en":"A company may be worth millions if its products sell well.","zh":"如果產品銷售良好，一間公司可能價值達數百萬。"},{"en":"If a market is worth billions, businesses have strong reasons to enter it.","zh":"如果一個市場價值達數十億，企業就有強大理由進入。"},{"en":"The phrase is often used to describe economic value.","zh":"這個短語常用來描述經濟價值。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":5},{"front":"make up","meaning":"佔","examples":[{"en":"Ecotourism makes up one-fifth of all international tourism.","zh":"生態旅遊佔所有國際旅遊的五分之一。"},{"en":"To make up a share means to form that part of a total.","zh":"make up a share 指構成總數中的某部分。"},{"en":"Rent may make up half of a student’s monthly spending.","zh":"租金可能佔學生每月開支的一半。"},{"en":"If eco-tourism makes up a large share of tourism, its standards affect many travellers.","zh":"如果生態旅遊佔旅遊業很大比例，其標準會影響許多旅客。"},{"en":"The phrase is useful for describing proportions.","zh":"這個短語適合描述比例。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":5},{"front":"one-fifth of","meaning":"五分之一的……","examples":[{"en":"Ecotourism makes up one-fifth of international tourism.","zh":"生態旅遊佔國際旅遊的五分之一。"},{"en":"One-fifth of something means one part out of five equal parts, or 20 percent.","zh":"one-fifth of something 指五等份中的一份，即百分之二十。"},{"en":"If one-fifth of a class is absent, six students are missing in a class of thirty.","zh":"如果一班三十人的五分之一缺席，就是六名學生缺席。"},{"en":"A sector that makes up one-fifth of a market is already very important.","zh":"佔市場五分之一的行業已經非常重要。"},{"en":"The phrase expresses a clear proportion.","zh":"這個短語表達清楚比例。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":5},{"front":"international tourism","meaning":"國際旅遊","examples":[{"en":"Ecotourism is a large part of international tourism.","zh":"生態旅遊是國際旅遊的重要部分。"},{"en":"International tourism is travel by people from one country to another for leisure, business, or other purposes.","zh":"international tourism 指人們從一個國家到另一個國家作休閒、商務或其他目的的旅行。"},{"en":"Airports, hotels, guides, and restaurants all depend partly on international tourism.","zh":"機場、酒店、導遊和餐廳都部分依靠國際旅遊。"},{"en":"When international tourism grows quickly, local communities may face both income and pressure.","zh":"當國際旅遊迅速增長，本地社區可能同時面對收入和壓力。"},{"en":"The phrase refers to cross-border travel.","zh":"這個短語指跨國旅行。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":6},{"front":"annual growth rate","meaning":"年增長率","examples":[{"en":"Ecotourism has an annual growth rate of around five per cent.","zh":"生態旅遊的年增長率約為百分之五。"},{"en":"Annual growth rate is the percentage by which something increases each year.","zh":"annual growth rate 指某事物每年增加的百分比。"},{"en":"A shop with an annual growth rate of ten percent is selling more each year.","zh":"年增長率為百分之十的商店每年銷售都在增加。"},{"en":"A steady growth rate attracts investors and new competitors.","zh":"穩定增長率會吸引投資者和新競爭者。"},{"en":"The phrase is common in business and economic reports.","zh":"這個短語常見於商業和經濟報告。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":6},{"front":"around five per cent","meaning":"約百分之五","examples":[{"en":"The annual growth rate is around five per cent.","zh":"年增長率約為百分之五。"},{"en":"Around five per cent means approximately five percent, not exactly five percent.","zh":"around five per cent 指大約百分之五，不是精確百分之五。"},{"en":"Around five per cent of a hundred students is about five students.","zh":"一百名學生的約百分之五就是大約五名學生。"},{"en":"Writers use around when the number is rounded or approximate.","zh":"當數字經四捨五入或只是估算，寫作者會使用 around。"},{"en":"The phrase gives a useful estimate without claiming precision.","zh":"這個短語提供有用估算，而不聲稱精確。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":6},{"front":"pressure for operators to","meaning":"營辦商去……的壓力","examples":[{"en":"There is pressure for operators to enter the ecotourism market.","zh":"營辦商有進入生態旅遊市場的壓力。"},{"en":"Pressure for someone to do something means strong influence pushing them toward that action.","zh":"pressure for someone to do something 指推動某人採取某行動的強大影響力。"},{"en":"There may be pressure for schools to use more technology if parents expect online learning.","zh":"如果家長期望網上學習，學校可能有更多使用科技的壓力。"},{"en":"When a market grows, companies feel pressure to join before competitors take customers.","zh":"當市場增長，公司會感到壓力，要在競爭者搶走顧客前加入。"},{"en":"The phrase describes business or social force.","zh":"這個短語描述商業或社會力量。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":6},{"front":"developed and developing countries","meaning":"已發展及發展中國家","examples":[{"en":"Operators in developed and developing countries joined the ecotourism trend.","zh":"已發展及發展中國家的營辦商都加入生態旅遊潮流。"},{"en":"Developed and developing countries means richer industrialised countries and countries still growing economically.","zh":"developed and developing countries 指較富裕工業化國家和經濟仍在發展的國家。"},{"en":"Climate policy affects both developed and developing countries, though their resources may differ.","zh":"氣候政策影響已發展及發展中國家，雖然它們資源可能不同。"},{"en":"If operators from both groups join a trend, the market becomes global.","zh":"如果兩類國家的營辦商都加入一股潮流，市場就變得全球化。"},{"en":"The phrase compares countries at different economic stages.","zh":"這個短語比較處於不同經濟階段的國家。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":6},{"front":"jump on the bandwagon","meaning":"趕潮流；跟風","examples":[{"en":"Many operators wanted to jump on the ecotourism bandwagon.","zh":"許多營辦商想趕上生態旅遊潮流。"},{"en":"To jump on the bandwagon means to join a trend because it is popular or profitable.","zh":"jump on the bandwagon 指因某事流行或有利可圖而加入潮流。"},{"en":"Shops may jump on the bandwagon when bubble tea suddenly becomes popular.","zh":"當珍珠奶茶突然流行，商店可能跟風推出。"},{"en":"If companies join a green trend without real commitment, they are just jumping on the bandwagon.","zh":"如果公司沒有真正承諾卻加入綠色潮流，它們只是跟風。"},{"en":"The phrase can sound critical because it suggests following fashion rather than principle.","zh":"這個短語可帶批評意味，因為它暗示追隨潮流而非原則。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":6},{"front":"accelerating bandwagon","meaning":"加速發展的潮流","examples":[{"en":"Ecotourism became an accelerating bandwagon.","zh":"生態旅遊變成加速發展的潮流。"},{"en":"An accelerating bandwagon is a trend that more and more people join at increasing speed.","zh":"accelerating bandwagon 指越來越多人以越來越快速度加入的潮流。"},{"en":"Online learning became an accelerating bandwagon when schools and businesses rushed to offer courses.","zh":"當學校和企業爭相提供課程，網上學習變成加速發展的潮流。"},{"en":"A fast-growing trend can attract weak operators as well as serious ones.","zh":"快速增長的潮流可以吸引薄弱營辦商，也可以吸引認真的營辦商。"},{"en":"The phrase suggests popularity is increasing quickly.","zh":"這個短語暗示流行程度正在迅速增加。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":6},{"front":"compelling","meaning":"令人難以抗拒的","examples":[{"en":"The pressure to join the market is compelling.","zh":"加入市場的壓力令人難以抗拒。"},{"en":"Compelling means powerful, convincing, or difficult to resist.","zh":"compelling 指有力量、令人信服或難以抗拒。"},{"en":"A compelling reason to sleep early is that it improves attention the next day.","zh":"早睡的一個有力理由是它改善翌日專注力。"},{"en":"High profits can make a business opportunity compelling to new companies.","zh":"高利潤可以令商機對新公司而言難以抗拒。"},{"en":"The word suggests strong attraction or strong argument.","zh":"這個詞暗示強烈吸引力或有力論點。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":6},{"front":"widely recognised accreditation system","meaning":"廣受承認的認證制度","examples":[{"en":"Ecotourism lacks a widely recognised accreditation system.","zh":"生態旅遊缺乏廣受承認的認證制度。"},{"en":"A widely recognised accreditation system is a trusted approval process accepted by many people or organisations.","zh":"widely recognised accreditation system 指被許多人或機構接受的可信認可程序。"},{"en":"A school qualification is more useful when it belongs to a widely recognised system.","zh":"學校資格如果屬於廣受承認的制度，就更有用。"},{"en":"Without recognised accreditation, travellers must judge tour claims by themselves.","zh":"如果沒有受承認的認證，旅客必須自行判斷旅行團聲稱。"},{"en":"The phrase stresses official approval and broad trust.","zh":"這個短語強調官方認可和廣泛信任。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":6},{"front":"consumers","meaning":"消費者","examples":[{"en":"Consumers often have to judge operators themselves.","zh":"消費者通常必須自行判斷營辦商。"},{"en":"Consumers are people who buy goods or services.","zh":"consumers 指購買貨品或服務的人。"},{"en":"Travellers become consumers when they pay for hotels, flights, and tours.","zh":"旅客支付酒店、機票和旅行團費用時，就是消費者。"},{"en":"If consumers lack reliable information, they may choose products based only on advertising.","zh":"如果消費者缺乏可靠資訊，他們可能只根據廣告選擇產品。"},{"en":"The word focuses on people as buyers.","zh":"這個詞重點是人作為買家。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":6},{"front":"investigate the credentials of","meaning":"查核……的資歷","examples":[{"en":"Consumers have had to investigate the credentials of operators themselves.","zh":"消費者一直要自行查核營辦商的資歷。"},{"en":"To investigate the credentials of someone means to check their qualifications, record, or trustworthiness.","zh":"investigate the credentials of someone 指查核某人的資格、紀錄或可信度。"},{"en":"Parents may investigate the credentials of a tutor before booking lessons.","zh":"家長可能在預訂課程前查核導師的資歷。"},{"en":"Checking credentials can prevent people from trusting companies with weak standards.","zh":"查核資歷可以防止人們信任標準薄弱的公司。"},{"en":"The phrase suggests careful checking before making a decision.","zh":"這個短語暗示決定前要仔細查證。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":6},{"front":"take claims at face value","meaning":"照單全收；信以為真","examples":[{"en":"Many travellers take an operator’s claims at face value.","zh":"許多旅客照單全收營辦商的聲稱。"},{"en":"To take claims at face value means to accept them as true without checking.","zh":"take claims at face value 指不查核就把聲稱當作真。"},{"en":"A shopper takes a label at face value if she believes “natural” without reading the ingredients.","zh":"如果購物者不看成分就相信 “natural” 標籤，她就是照單全收。"},{"en":"If travellers take green claims at face value, fake operators can profit.","zh":"如果旅客把環保聲稱信以為真，虛假營辦商就可以獲利。"},{"en":"The phrase warns against trusting words too quickly.","zh":"這個短語提醒人們不要太快相信文字。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":7},{"front":"add to","meaning":"加劇；增加","examples":[{"en":"Uncritical travellers add to the spread of fake ecotours.","zh":"不加批判的旅客加劇虛假生態旅遊的蔓延。"},{"en":"To add to something means to increase it or make it stronger.","zh":"add to something 指增加某事或令它更強。"},{"en":"Poor sleep can add to stress before an exam.","zh":"睡眠不足可以加劇考試前壓力。"},{"en":"When travellers support fake tours, they add to the problem of dishonest marketing.","zh":"當旅客支持虛假旅行團，他們就加劇不誠實市場推廣的問題。"},{"en":"The phrase shows something makes a situation bigger or worse.","zh":"這個短語顯示某事令情況變大或變差。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":7},{"front":"proliferation of","meaning":"……的激增","examples":[{"en":"Weak regulation adds to the proliferation of fake ecotours.","zh":"規管薄弱加劇虛假生態旅遊的激增。"},{"en":"Proliferation of something means rapid increase or spread in number.","zh":"proliferation of something 指數量快速增加或擴散。"},{"en":"The proliferation of cheap online courses can make quality difficult to judge.","zh":"便宜網上課程激增，可以令質素難以判斷。"},{"en":"When false labels spread, consumers face more confusion and risk.","zh":"當虛假標籤蔓延，消費者面對更多困惑和風險。"},{"en":"The phrase often suggests growth that is hard to control.","zh":"這個短語通常暗示難以控制的增長。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":7},{"front":"fake ecotours","meaning":"虛假的生態旅遊","examples":[{"en":"Some tours are fake ecotours rather than genuine responsible travel.","zh":"一些旅行團是虛假的生態旅遊，而不是真正負責任的旅遊。"},{"en":"Fake ecotours are trips marketed as environmentally responsible but not truly following those principles.","zh":"fake ecotours 指被包裝成對環境負責但並未真正遵守原則的旅程。"},{"en":"A boat trip that disturbs wildlife but calls itself green may be a fake ecotour.","zh":"干擾野生動物卻自稱綠色的船程，可能是虛假生態旅遊。"},{"en":"Fake ecotours can harm nature and mislead travellers who want to help.","zh":"虛假生態旅遊可以傷害自然，並誤導想幫助環境的旅客。"},{"en":"The phrase contrasts dishonest branding with genuine responsibility.","zh":"這個短語把不誠實品牌包裝與真正責任作對比。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":7},{"front":"simple questions","meaning":"簡單問題","examples":[{"en":"Several simple questions can help assess an operator’s commitment.","zh":"幾個簡單問題可以幫助評估營辦商的承諾。"},{"en":"Simple questions are clear, basic questions that reveal useful information.","zh":"simple questions 指清楚、基本、能揭示有用資訊的問題。"},{"en":"A traveller can ask who owns the hotel, where staff come from, and how waste is managed.","zh":"旅客可以問酒店由誰擁有、員工來自哪裡，以及廢物如何處理。"},{"en":"Simple questions can expose weak claims when operators cannot answer clearly.","zh":"當營辦商不能清楚回答，簡單問題可以揭露薄弱聲稱。"},{"en":"The phrase shows that useful checking does not always require expert knowledge.","zh":"這個短語顯示有用查核不一定需要專家知識。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":7},{"front":"assess a company’s commitment to","meaning":"評估公司對……的承諾","examples":[{"en":"Travellers can assess a company’s commitment to responsible tourism.","zh":"旅客可以評估公司對負責任旅遊的承諾。"},{"en":"To assess a company’s commitment to something means to judge how seriously it supports that goal.","zh":"assess a company’s commitment to something 指判斷公司有多認真支持某目標。"},{"en":"Customers can assess a company’s commitment to fairness by checking wages and worker treatment.","zh":"顧客可以透過查核工資和員工待遇，評估公司對公平的承諾。"},{"en":"If a company refuses to share details, its commitment may be weak.","zh":"如果公司拒絕分享細節，它的承諾可能薄弱。"},{"en":"The phrase focuses on judging real action, not just promises.","zh":"這個短語重點是判斷真實行動，而不只是承諾。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":7},{"front":"minimise environmental impact","meaning":"盡量減低環境影響","examples":[{"en":"Good operators try to minimise environmental impact.","zh":"良好營辦商會嘗試盡量減低環境影響。"},{"en":"To minimise environmental impact means to reduce harm to nature as much as possible.","zh":"minimise environmental impact 指盡可能減少對自然的傷害。"},{"en":"A hotel can minimise environmental impact by saving water and reducing plastic waste.","zh":"酒店可以透過節約用水和減少塑膠廢物來減低環境影響。"},{"en":"If tours limit visitor numbers, they may reduce pressure on wildlife and paths.","zh":"如果旅行團限制遊客人數，就可能減少對野生動物和步道的壓力。"},{"en":"The phrase focuses on making unavoidable effects as small as possible.","zh":"這個短語重點是把不可避免的影響盡量縮小。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":7},{"front":"maximise the benefits to","meaning":"盡量增加對……的好處","examples":[{"en":"Responsible tourism should maximise the benefits to the local community.","zh":"負責任旅遊應盡量增加對本地社區的好處。"},{"en":"To maximise the benefits to someone means to make the positive results for them as large as possible.","zh":"maximise the benefits to someone 指令某人得到的正面結果盡可能大。"},{"en":"A school programme should maximise the benefits to students by giving support where it is most needed.","zh":"學校計劃應把支援放在最需要的地方，以盡量增加對學生的好處。"},{"en":"Tourism can maximise local benefits by hiring local staff and buying local food.","zh":"旅遊可以透過聘用本地員工和購買本地食物來增加本地好處。"},{"en":"The phrase stresses increasing good effects, not just reducing harm.","zh":"這個短語強調增加好影響，而不只是減少傷害。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":7},{"front":"local community","meaning":"本地社區","examples":[{"en":"Ecotourism should benefit the local community.","zh":"生態旅遊應令本地社區受益。"},{"en":"The local community is the group of people who live in the area being visited.","zh":"local community 指居住在被到訪地區的人群。"},{"en":"A village, town, or neighbourhood can be a local community.","zh":"村莊、城鎮或社區都可以是本地社區。"},{"en":"If tourism money leaves the area, the local community may see little benefit.","zh":"如果旅遊收入流出該地，本地社區可能得不到多少好處。"},{"en":"The phrase focuses on residents, not only visitors or companies.","zh":"這個短語重點是居民，而不只是遊客或公司。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":7},{"front":"tourism area","meaning":"旅遊地區","examples":[{"en":"The local community in the tourism area should benefit.","zh":"旅遊地區中的本地社區應該受益。"},{"en":"A tourism area is a place visited by tourists for attractions, culture, scenery, or activities.","zh":"tourism area 指因景點、文化、景色或活動而被遊客到訪的地方。"},{"en":"A beach town, mountain village, or historic district can be a tourism area.","zh":"海灘小鎮、山村或歷史街區都可以是旅遊地區。"},{"en":"If a tourism area receives many visitors, it needs careful planning to protect residents and nature.","zh":"如果旅遊地區接待許多遊客，它需要仔細規劃以保護居民和自然。"},{"en":"The phrase describes the destination where tourism happens.","zh":"這個短語描述旅遊發生的目的地。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":7},{"front":"recycled materials","meaning":"回收物料","examples":[{"en":"Responsible companies may use recycled materials.","zh":"負責任公司可能使用回收物料。"},{"en":"Recycled materials are materials made from waste that has been processed for reuse.","zh":"recycled materials 指由經處理再用的廢物製成的物料。"},{"en":"A hotel may use recycled paper, glass, or plastic in its rooms.","zh":"酒店可能在房間中使用回收紙張、玻璃或塑膠。"},{"en":"Using recycled materials can reduce waste and demand for new resources.","zh":"使用回收物料可以減少廢物和對新資源的需求。"},{"en":"The phrase refers to reused material, not simply old-looking design.","zh":"這個短語指再用物料，而不是單純看起來舊的設計。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":7},{"front":"sustainable materials","meaning":"可持續物料","examples":[{"en":"Ecotourism properties should use sustainable materials where possible.","zh":"生態旅遊住宿物業應盡可能使用可持續物料。"},{"en":"Sustainable materials are materials that can be used without seriously damaging future resources or ecosystems.","zh":"sustainable materials 指使用時不會嚴重損害未來資源或生態系統的物料。"},{"en":"Bamboo, certified wood, and recycled metal can be sustainable materials in some projects.","zh":"竹、認證木材和回收金屬在某些項目中可以是可持續物料。"},{"en":"Choosing sustainable materials can reduce pollution and protect forests.","zh":"選擇可持續物料可以減少污染並保護森林。"},{"en":"The phrase focuses on long-term environmental responsibility.","zh":"這個短語重點是長期環境責任。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":8},{"front":"locally harvested materials","meaning":"本地採集的物料","examples":[{"en":"The company may use locally harvested materials to build tourist properties.","zh":"公司可能使用本地採集的物料建造旅遊住宿物業。"},{"en":"Locally harvested materials are materials collected from the nearby area in a responsible way.","zh":"locally harvested materials 指以負責任方式從附近地區採集的物料。"},{"en":"A lodge may use locally harvested wood or stone instead of importing heavy materials.","zh":"旅館可能使用本地採集的木材或石材，而不是進口沉重物料。"},{"en":"Local materials can reduce transport emissions and support nearby workers.","zh":"本地物料可以減少運輸排放並支持附近工人。"},{"en":"The phrase should imply careful use, not careless extraction from nature.","zh":"這個短語應暗示謹慎使用，而不是任意開採自然。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":8},{"front":"tourist properties","meaning":"旅遊住宿物業；旅遊設施","examples":[{"en":"Tourist properties can be built with sustainable materials.","zh":"旅遊住宿物業可以用可持續物料建造。"},{"en":"Tourist properties are buildings or facilities used by visitors, such as lodges, hotels, or camps.","zh":"tourist properties 指遊客使用的建築或設施，例如旅館、酒店或營地。"},{"en":"A small eco-lodge by a forest is a tourist property.","zh":"森林旁的小型生態旅館就是一種旅遊住宿物業。"},{"en":"Poorly built tourist properties can damage landscapes and use too much water.","zh":"建造不良的旅遊設施可以破壞景觀並使用太多水。"},{"en":"The phrase refers to tourism facilities, not land ownership only.","zh":"這個短語指旅遊設施，而不只是土地擁有權。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":8},{"front":"pay fair wages","meaning":"支付公平工資","examples":[{"en":"A responsible company pays fair wages to employees.","zh":"負責任公司向員工支付公平工資。"},{"en":"To pay fair wages means to give workers reasonable pay for their work.","zh":"pay fair wages 指為員工工作支付合理薪酬。"},{"en":"A restaurant pays fair wages when staff can cover basic living costs from their salary.","zh":"如果餐廳員工能用薪金支付基本生活費，餐廳就是支付公平工資。"},{"en":"If tour companies pay fair wages, local people benefit more from tourism.","zh":"如果旅遊公司支付公平工資，本地人會從旅遊中得到更多好處。"},{"en":"The phrase connects business ethics with worker treatment.","zh":"這個短語把商業倫理與員工待遇連起來。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":8},{"front":"offer training to","meaning":"向……提供培訓","examples":[{"en":"Good operators offer training to employees.","zh":"良好營辦商向員工提供培訓。"},{"en":"To offer training to someone means to provide lessons or practice so they can do a job better.","zh":"offer training to someone 指提供課程或練習，使某人能更好地工作。"},{"en":"A shop may offer training to new staff before they serve customers.","zh":"商店可能在新員工服務顧客前向他們提供培訓。"},{"en":"Training local guides can improve service quality and create better jobs.","zh":"培訓本地導遊可以改善服務質素並創造更好工作。"},{"en":"The phrase shows investment in people, not only profit.","zh":"這個短語顯示對人的投資，而不只是利潤。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":8},{"front":"city entrepreneurs","meaning":"城市企業家","examples":[{"en":"City entrepreneurs often own tour companies in rural areas.","zh":"城市企業家經常擁有鄉郊地區的旅遊公司。"},{"en":"City entrepreneurs are businesspeople based in cities who start or run companies.","zh":"city entrepreneurs 指以城市為基地、創立或經營公司的商人。"},{"en":"A city entrepreneur may open a guesthouse in a village without living there.","zh":"城市企業家可能在村莊開旅館，但自己並不住在那裡。"},{"en":"If city entrepreneurs take most profits away, rural communities may benefit less.","zh":"如果城市企業家把大部分利潤帶走，鄉郊社區可能受益較少。"},{"en":"The phrase contrasts outside business owners with local residents.","zh":"這個短語把外來企業主與本地居民作對比。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":8},{"front":"country areas","meaning":"鄉郊地區","examples":[{"en":"Tour companies in country areas may be owned by city entrepreneurs.","zh":"鄉郊地區的旅遊公司可能由城市企業家擁有。"},{"en":"Country areas are rural places outside large towns and cities.","zh":"country areas 指大城市和城鎮以外的鄉村地方。"},{"en":"Farms, villages, forests, and small communities can be found in country areas.","zh":"農場、村莊、森林和小型社區都可在鄉郊地區找到。"},{"en":"Tourism in country areas can bring income, but ownership matters for who benefits.","zh":"鄉郊地區的旅遊可以帶來收入，但擁有權會影響誰得益。"},{"en":"The phrase contrasts rural places with urban centres.","zh":"這個短語把鄉村地方與城市中心作對比。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":8},{"front":"end up in","meaning":"最終流入","examples":[{"en":"Money from tourism may end up in the city.","zh":"旅遊收入可能最終流入城市。"},{"en":"To end up in a place means to finally arrive there, often after a process.","zh":"end up in a place 指經過一個過程後最終到達某地。"},{"en":"A lost wallet may end up in the school office if someone hands it in.","zh":"如果有人拾到失物交回，遺失的錢包可能最後到達學校辦公室。"},{"en":"Tourism money may end up outside the village if companies are owned elsewhere.","zh":"如果公司由外地人擁有，旅遊收入可能最終流出村莊。"},{"en":"The phrase focuses on the final destination or result.","zh":"這個短語重點是最終目的地或結果。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":8},{"front":"the community being visited","meaning":"被到訪的社區","examples":[{"en":"Tourism money should benefit the community being visited.","zh":"旅遊收入應令被到訪的社區受益。"},{"en":"The community being visited is the local group of people living where tourists go.","zh":"community being visited 指遊客前往地點中居住的本地人群。"},{"en":"A village hosting visitors is the community being visited.","zh":"接待遊客的村莊就是被到訪的社區。"},{"en":"If money does not stay there, the visited community bears pressure without gaining much.","zh":"如果金錢沒有留在當地，被到訪的社區承受壓力卻得益不多。"},{"en":"The phrase reminds readers that destinations are people’s homes.","zh":"這個短語提醒讀者，旅遊目的地也是人們的家。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":8},{"front":"take a little extra time to","meaning":"多花一點時間去……","examples":[{"en":"Travellers should take a little extra time to investigate operators.","zh":"旅客應多花一點時間去查核營辦商。"},{"en":"To take a little extra time to do something means to spend a small additional amount of time on it.","zh":"take a little extra time to do something 指為某事多花少量額外時間。"},{"en":"Students should take a little extra time to check spelling before submitting essays.","zh":"學生提交作文前應多花一點時間檢查串字。"},{"en":"A few extra minutes of checking can prevent a poor travel choice.","zh":"多花幾分鐘查核可以避免差劣旅遊選擇。"},{"en":"The phrase suggests a small effort with useful results.","zh":"這個短語暗示小努力能帶來有用結果。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":8},{"front":"investigate the options","meaning":"查核各種選擇","examples":[{"en":"Travellers can investigate the ecotourism options before booking.","zh":"旅客可以在預訂前查核各種生態旅遊選擇。"},{"en":"To investigate the options means to check and compare available choices carefully.","zh":"investigate the options 指仔細查核和比較可用選擇。"},{"en":"A family may investigate school options before moving house.","zh":"家庭可能在搬屋前查核各種學校選擇。"},{"en":"Investigating options can reveal which tour really supports local people.","zh":"查核各種選擇可以揭示哪個旅行團真正支持本地人。"},{"en":"The phrase contrasts careful research with quick booking.","zh":"這個短語把仔細研究與快速預訂作對比。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":8},{"front":"direct your custom to","meaning":"將生意光顧給……","examples":[{"en":"Travellers can direct their custom to worthy operators.","zh":"旅客可以將生意光顧給值得支持的營辦商。"},{"en":"To direct your custom to a business means to choose to spend your money there.","zh":"direct your custom to a business 指選擇在某商戶花錢。"},{"en":"Shoppers can direct their custom to local stores instead of large chains.","zh":"購物者可以把生意光顧給本地小店，而不是大型連鎖店。"},{"en":"If travellers direct their custom to responsible companies, better operators are rewarded.","zh":"如果旅客把生意光顧給負責任公司，較好的營辦商就會得到回報。"},{"en":"The phrase treats consumer spending as a deliberate choice.","zh":"這個短語把消費視為有意識的選擇。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":9},{"front":"worthy operators","meaning":"值得支持的營辦商","examples":[{"en":"Worthy operators deserve support from responsible travellers.","zh":"值得支持的營辦商值得負責任旅客支持。"},{"en":"Worthy operators are tour companies that genuinely deserve trust and business.","zh":"worthy operators 指真正值得信任和光顧的旅遊公司。"},{"en":"A worthy operator pays local guides fairly and protects natural sites.","zh":"值得支持的營辦商會公平支付本地導遊，並保護自然景點。"},{"en":"Supporting worthy operators encourages better standards in the industry.","zh":"支持值得支持的營辦商能鼓勵業界提高標準。"},{"en":"The phrase praises companies that act responsibly, not just advertise well.","zh":"這個短語讚揚負責任行事的公司，而不只是廣告做得好。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":9},{"front":"far more rewarding","meaning":"有意義得多；更有收穫得多","examples":[{"en":"Responsible ecotours often offer far more rewarding experiences.","zh":"負責任的生態旅遊通常提供有意義得多的體驗。"},{"en":"Far more rewarding means much more satisfying, meaningful, or worthwhile.","zh":"far more rewarding 指令人滿足、有意義或值得得多。"},{"en":"Helping a local project can be far more rewarding than buying a souvenir quickly.","zh":"幫助本地項目可能比快速買紀念品更有收穫得多。"},{"en":"A responsible tour feels more rewarding when travellers know their money supports the community.","zh":"當旅客知道金錢支持社區，負責任旅行會感覺更有意義。"},{"en":"The phrase compares deeper value with ordinary enjoyment.","zh":"這個短語把較深層價值與普通享受作比較。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":9},{"front":"very much in need of","meaning":"非常需要","examples":[{"en":"The ecotourism business is very much in need of reform.","zh":"生態旅遊業非常需要改革。"},{"en":"Very much in need of something means needing it strongly or urgently.","zh":"very much in need of something 指強烈或迫切需要某物。"},{"en":"A school with old buildings may be very much in need of repair.","zh":"建築老舊的學校可能非常需要維修。"},{"en":"If an industry has weak standards, it may be very much in need of reform.","zh":"如果一個行業標準薄弱，它可能非常需要改革。"},{"en":"The phrase stresses strong necessity.","zh":"這個短語強調強烈需要。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":9},{"front":"a shake-up","meaning":"大改革；整頓","examples":[{"en":"The ecotourism business needs a shake-up.","zh":"生態旅遊業需要一次大改革。"},{"en":"A shake-up is a major change intended to improve a system or organisation.","zh":"shake-up 指旨在改善系統或組織的重大改變。"},{"en":"A company may need a shake-up if departments work badly together.","zh":"如果公司各部門合作很差，它可能需要整頓。"},{"en":"A shake-up in ecotourism could include stricter checks and clearer labels.","zh":"生態旅遊的大改革可以包括更嚴格查核和更清晰標籤。"},{"en":"The phrase suggests reform, not small surface changes.","zh":"這個短語暗示改革，而不是表面小改動。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":9},{"front":"standardised approach","meaning":"標準化做法","examples":[{"en":"Ecotourism needs a standardised approach.","zh":"生態旅遊需要標準化做法。"},{"en":"A standardised approach is a consistent method used in the same way across different cases.","zh":"standardised approach 指在不同個案中以相同方式使用的一致方法。"},{"en":"Schools use a standardised approach to marking so students are treated fairly.","zh":"學校使用標準化評分方法，使學生受到公平對待。"},{"en":"A standardised approach to ecotourism would make labels easier to trust.","zh":"生態旅遊的標準化做法會令標籤更容易信任。"},{"en":"The phrase stresses common rules and consistency.","zh":"這個短語強調共同規則和一致性。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":9},{"front":"spring up","meaning":"湧現；冒起","examples":[{"en":"A few organisations have sprung up in the last ten years.","zh":"過去十年已有幾個組織湧現。"},{"en":"To spring up means to appear or develop quickly.","zh":"spring up 指迅速出現或發展。"},{"en":"New cafés may spring up near a university when student numbers grow.","zh":"當學生人數增加，新咖啡店可能在大學附近冒起。"},{"en":"Organisations spring up when people see an urgent problem that needs action.","zh":"當人們看見急需處理的問題，組織就會湧現。"},{"en":"The phrase suggests relatively sudden emergence.","zh":"這個短語暗示相對突然出現。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":9},{"front":"in the last ten years or so","meaning":"過去十年左右","examples":[{"en":"Several organisations have appeared in the last ten years or so.","zh":"過去十年左右已有幾個組織出現。"},{"en":"In the last ten years or so means during roughly the past decade.","zh":"in the last ten years or so 指大約過去十年間。"},{"en":"In the last ten years or so, many people have begun using smartphones for payment.","zh":"過去十年左右，許多人開始使用智能手機付款。"},{"en":"The phrase gives an approximate recent time period, not an exact date.","zh":"這個短語提供近期的大約時段，而不是確切日期。"},{"en":"Writers use or so when the number is not meant to be precise.","zh":"當數字不需精確時，寫作者會使用 or so。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":9},{"front":"endeavour to","meaning":"努力去","examples":[{"en":"These organisations endeavour to educate travellers and operators.","zh":"這些組織努力教育旅客和營辦商。"},{"en":"To endeavour to do something means to try hard to do it.","zh":"endeavour to do something 指努力做某事。"},{"en":"A teacher may endeavour to make grammar clear for weaker students.","zh":"老師可能努力為能力較弱的學生講清文法。"},{"en":"Organisations endeavour to change behaviour by publishing guidance and training operators.","zh":"組織透過發布指引和培訓營辦商，努力改變行為。"},{"en":"The phrase is formal and stronger than simply try.","zh":"這個短語較正式，比 simply try 更強。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":9},{"front":"educate travellers and operators about","meaning":"教育旅客和營辦商有關……","examples":[{"en":"Organisations educate travellers and operators about responsible ecotourism.","zh":"組織教育旅客和營辦商有關負責任生態旅遊。"},{"en":"To educate people about something means to teach them useful knowledge and behaviour related to it.","zh":"educate people about something 指教導人們與某事相關的有用知識和行為。"},{"en":"Schools educate students about recycling by showing what goes into each bin.","zh":"學校透過展示每個回收箱應放甚麼，教育學生有關回收。"},{"en":"Educating both tourists and companies can reduce dishonest marketing and harmful travel choices.","zh":"同時教育遊客和公司可以減少不誠實市場推廣和有害旅遊選擇。"},{"en":"The phrase focuses on improving understanding and action.","zh":"這個短語重點是改善理解和行動。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":9},{"front":"responsible ecotourism","meaning":"負責任的生態旅遊","examples":[{"en":"The passage supports responsible ecotourism.","zh":"文章支持負責任的生態旅遊。"},{"en":"Responsible ecotourism is travel that protects nature and benefits local communities.","zh":"responsible ecotourism 指保護自然並令本地社區受益的旅遊。"},{"en":"A responsible ecotour hires local guides, limits waste, and respects wildlife.","zh":"負責任的生態旅遊會聘用本地導遊、限制廢物並尊重野生動物。"},{"en":"If ecotourism is not responsible, it may become ordinary tourism with a green label.","zh":"如果生態旅遊不負責任，它可能變成貼着綠色標籤的普通旅遊。"},{"en":"The phrase stresses genuine ethical practice.","zh":"這個短語強調真正的道德實踐。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":9},{"front":"founded in","meaning":"成立於","examples":[{"en":"The Ecotourism Society was founded in 1990.","zh":"生態旅遊協會成立於1990年。"},{"en":"Founded in a year means officially established or created in that year.","zh":"founded in a year 指在某一年正式成立或創立。"},{"en":"A school founded in 1950 has served students for many decades.","zh":"一所成立於1950年的學校已服務學生數十年。"},{"en":"Knowing when an organisation was founded helps readers understand its history.","zh":"知道一個組織何時成立，有助讀者理解其歷史。"},{"en":"The phrase gives the starting date of an institution.","zh":"這個短語提供機構的開始日期。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":10},{"front":"non-profit organisation","meaning":"非牟利組織","examples":[{"en":"The Ecotourism Society is a non-profit organisation.","zh":"生態旅遊協會是一個非牟利組織。"},{"en":"A non-profit organisation uses its money to support its mission rather than to pay profits to owners.","zh":"non-profit organisation 指把資金用於支持使命，而不是向擁有人分配利潤的組織。"},{"en":"A charity that provides free meals may be a non-profit organisation.","zh":"提供免費膳食的慈善機構可能是非牟利組織。"},{"en":"Non-profit organisations can educate the public because they are not mainly selling products.","zh":"非牟利組織可以教育公眾，因為它們主要不是銷售產品。"},{"en":"The phrase describes organisational purpose, not whether staff are paid.","zh":"這個短語描述組織目的，而不是員工是否有薪酬。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":10},{"front":"travel industry professionals","meaning":"旅遊業專業人士","examples":[{"en":"The society includes travel industry professionals.","zh":"該協會包括旅遊業專業人士。"},{"en":"Travel industry professionals are people who work in tourism, transport, hotels, or travel services.","zh":"travel industry professionals 指在旅遊、交通、酒店或旅行服務中工作的人。"},{"en":"Travel agents, hotel managers, guides, and airline staff can be travel industry professionals.","zh":"旅行社職員、酒店經理、導遊和航空公司員工都可以是旅遊業專業人士。"},{"en":"Their experience helps organisations understand how tourism works in practice.","zh":"他們的經驗幫助組織理解旅遊在實際上如何運作。"},{"en":"The phrase refers to people with professional knowledge of travel.","zh":"這個短語指具旅遊專業知識的人。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":10},{"front":"conservation professionals","meaning":"保育專業人士","examples":[{"en":"The society includes conservation professionals.","zh":"該協會包括保育專業人士。"},{"en":"Conservation professionals are experts who work to protect wildlife, habitats, and natural resources.","zh":"conservation professionals 指致力保護野生動物、棲息地和自然資源的專家。"},{"en":"A conservation professional may study how tourism affects sea turtles or forests.","zh":"保育專業人士可能研究旅遊如何影響海龜或森林。"},{"en":"Their knowledge helps tour operators avoid damaging sensitive environments.","zh":"他們的知識幫助旅遊營辦商避免破壞敏感環境。"},{"en":"The phrase refers to specialists in protecting nature.","zh":"這個短語指保護自然方面的專家。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":10},{"front":"ecological professionals","meaning":"生態專業人士","examples":[{"en":"The society includes ecological professionals.","zh":"該協會包括生態專業人士。"},{"en":"Ecological professionals are specialists who study ecosystems and relationships between living things and their environments.","zh":"ecological professionals 指研究生態系統，以及生物與環境關係的專家。"},{"en":"An ecological professional may advise where tourists can walk without harming plants.","zh":"生態專業人士可能建議遊客在哪裡行走才不傷害植物。"},{"en":"Ecological advice helps tourism protect habitats rather than damage them.","zh":"生態建議幫助旅遊保護棲息地，而不是破壞它們。"},{"en":"The phrase refers to experts in ecology and environmental systems.","zh":"這個短語指生態學和環境系統專家。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":10},{"front":"aim to make","meaning":"旨在使……成為","examples":[{"en":"The society aims to make ecotourism a genuine conservation tool.","zh":"該協會旨在使生態旅遊成為真正的保育工具。"},{"en":"To aim to make something a certain thing means to try to turn it into that thing.","zh":"aim to make something a certain thing 指嘗試把某事變成某種東西。"},{"en":"A school may aim to make reading a daily habit for all students.","zh":"學校可能旨在使閱讀成為所有學生的日常習慣。"},{"en":"If ecotourism becomes a conservation tool, travel money can help protect nature.","zh":"如果生態旅遊成為保育工具，旅遊收入就可以幫助保護自然。"},{"en":"The phrase explains a goal and intended change.","zh":"這個短語解釋目標和預期改變。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":10},{"front":"a genuine tool for","meaning":"……的真正工具","examples":[{"en":"Ecotourism can become a genuine tool for conservation.","zh":"生態旅遊可以成為保育的真正工具。"},{"en":"A genuine tool for something is a real and effective way to achieve that purpose.","zh":"genuine tool for something 指達成某目的的真實有效方法。"},{"en":"Feedback can be a genuine tool for learning if students use it to improve.","zh":"如果學生用回饋來改進，回饋可以成為學習的真正工具。"},{"en":"Tourism becomes a genuine tool for conservation only when money and rules protect nature.","zh":"只有當金錢和規則保護自然，旅遊才成為保育的真正工具。"},{"en":"The phrase contrasts real usefulness with empty claims.","zh":"這個短語把真正有用與空洞聲稱作對比。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":10},{"front":"conservation","meaning":"保育","examples":[{"en":"Ecotourism can support conservation.","zh":"生態旅遊可以支持保育。"},{"en":"Conservation is the protection of nature, wildlife, habitats, or cultural heritage.","zh":"conservation 指保護自然、野生動物、棲息地或文化遺產。"},{"en":"A park uses conservation measures when it limits visitors to protect rare birds.","zh":"公園限制遊客數量以保護稀有雀鳥時，就是使用保育措施。"},{"en":"Conservation can succeed when local people benefit from protecting the environment.","zh":"當本地人從保護環境中受益，保育就更可能成功。"},{"en":"The word focuses on preserving valuable things for the future.","zh":"這個詞重點是為未來保存有價值事物。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":10},{"front":"sustainable development","meaning":"可持續發展","examples":[{"en":"Ecotourism can support sustainable development.","zh":"生態旅遊可以支持可持續發展。"},{"en":"Sustainable development is growth that meets present needs without destroying future resources.","zh":"sustainable development 指滿足當前需要而不破壞未來資源的發展。"},{"en":"A town supports sustainable development when it creates jobs while protecting water and forests.","zh":"城鎮在創造就業同時保護食水和森林，就是支持可持續發展。"},{"en":"Tourism can support sustainable development if income helps communities and nature is protected.","zh":"如果旅遊收入幫助社區且自然受保護，旅遊可以支持可持續發展。"},{"en":"The phrase balances economy, society, and environment.","zh":"這個短語平衡經濟、社會和環境。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":10},{"front":"inherent economic value","meaning":"內在經濟價值","examples":[{"en":"Ecotourism can create inherent economic value in wilderness environments.","zh":"生態旅遊可以在荒野環境中創造內在經濟價值。"},{"en":"Inherent economic value means financial importance that belongs naturally to something when people recognise its worth.","zh":"inherent economic value 指當人們認識到某物價值時，它本身具有的經濟重要性。"},{"en":"A forest has economic value if protecting it brings tourism income and jobs.","zh":"如果保護森林能帶來旅遊收入和工作，森林就有經濟價值。"},{"en":"When wild places generate income without being destroyed, conservation becomes easier to justify.","zh":"當荒野地方不被破壞也能產生收入，保育就更容易被合理化。"},{"en":"The phrase connects natural existence with economic benefit.","zh":"這個短語把自然存在與經濟好處連起來。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":10},{"front":"wilderness environments","meaning":"荒野環境","examples":[{"en":"Ecotourism can give economic value to wilderness environments.","zh":"生態旅遊可以賦予荒野環境經濟價值。"},{"en":"Wilderness environments are natural areas with little human development.","zh":"wilderness environments 指人類開發很少的自然地區。"},{"en":"Remote forests, deserts, mountains, and wetlands can be wilderness environments.","zh":"偏遠森林、沙漠、山區和濕地都可以是荒野環境。"},{"en":"If tourism is carefully controlled, wilderness environments can be protected while supporting local income.","zh":"如果旅遊受到仔細管制，荒野環境可以在支持本地收入的同時受到保護。"},{"en":"The phrase refers to wild natural places, not city parks.","zh":"這個短語指野外自然地方，而不是城市公園。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":10},{"front":"threatened cultures","meaning":"受威脅的文化","examples":[{"en":"Ecotourism may help protect threatened cultures.","zh":"生態旅遊可能幫助保護受威脅的文化。"},{"en":"Threatened cultures are ways of life, languages, customs, or traditions at risk of disappearing.","zh":"threatened cultures 指面臨消失風險的生活方式、語言、習俗或傳統。"},{"en":"A small community’s language may be part of a threatened culture if few young people use it.","zh":"如果很少年輕人使用某小社區的語言，它可能屬於受威脅文化的一部分。"},{"en":"Tourism can help threatened cultures only if local people control how their culture is presented.","zh":"只有當本地人掌控文化如何被呈現，旅遊才可以幫助受威脅文化。"},{"en":"The phrase focuses on cultural survival, not entertainment for visitors.","zh":"這個短語重點是文化延續，而不是遊客娛樂。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":11},{"front":"undoubtedly","meaning":"毫無疑問地","examples":[{"en":"This achievement has undoubtedly been important.","zh":"這項成就毫無疑問地非常重要。"},{"en":"Undoubtedly means certainly or without serious doubt.","zh":"undoubtedly 指肯定地或沒有嚴重疑問地。"},{"en":"Clean water has undoubtedly improved public health in many cities.","zh":"清潔食水毫無疑問地改善了許多城市的公共健康。"},{"en":"Writers use undoubtedly when they want to show strong confidence in a point.","zh":"寫作者想對某點表示強烈信心時會使用 undoubtedly。"},{"en":"The word makes a statement sound firm and clear.","zh":"這個詞令陳述聽起來堅定而清楚。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":11},{"front":"notable achievements","meaning":"顯著成就","examples":[{"en":"Creating value in wild places is one of ecotourism’s notable achievements.","zh":"在荒野地方創造價值是生態旅遊的顯著成就之一。"},{"en":"Notable achievements are important successes that deserve attention.","zh":"notable achievements 指值得注意的重要成功。"},{"en":"A student’s notable achievements may include improving from failure to top grades.","zh":"學生的顯著成就可能包括由不及格進步到高分。"},{"en":"Ecotourism’s achievements are notable when they protect nature and help communities.","zh":"當生態旅遊保護自然並幫助社區，其成就就是顯著的。"},{"en":"The phrase highlights positive results worth remembering.","zh":"這個短語突出值得記住的正面成果。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":11},{"front":"annual initiative","meaning":"年度倡議","examples":[{"en":"The Ecotourism Society organises an annual initiative.","zh":"生態旅遊協會組織一項年度倡議。"},{"en":"An annual initiative is a planned project or campaign that happens once every year.","zh":"annual initiative 指每年進行一次的有計劃項目或活動。"},{"en":"A school may run an annual initiative to reduce plastic waste.","zh":"學校可能推行年度倡議以減少塑膠廢物。"},{"en":"Repeating an initiative every year helps build awareness and habits over time.","zh":"每年重複倡議有助隨時間建立意識和習慣。"},{"en":"The phrase combines regular timing with purposeful action.","zh":"這個短語結合固定時間和有目的行動。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":11},{"front":"further aid the development of","meaning":"進一步協助……的發展","examples":[{"en":"The initiative aims to further aid the development of ecotourism.","zh":"該倡議旨在進一步協助生態旅遊的發展。"},{"en":"To further aid the development of something means to give additional help so it can grow or improve.","zh":"further aid the development of something 指提供額外幫助，使某事成長或改善。"},{"en":"Mentoring can further aid the development of young teachers.","zh":"導師指導可以進一步協助年輕教師的發展。"},{"en":"Education campaigns can further aid ecotourism by improving traveller choices.","zh":"教育宣傳活動可以透過改善旅客選擇，進一步協助生態旅遊。"},{"en":"The phrase suggests extra support beyond what already exists.","zh":"這個短語暗示在已有基礎上提供額外支援。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":11},{"front":"launch a campaign","meaning":"展開宣傳活動","examples":[{"en":"The society is launching an educational campaign.","zh":"該協會正展開一項教育宣傳活動。"},{"en":"To launch a campaign means to start an organised effort to achieve a goal.","zh":"launch a campaign 指開始一項有組織、旨在達成目標的活動。"},{"en":"A school may launch a campaign to encourage students to read every day.","zh":"學校可能展開宣傳活動，鼓勵學生每天閱讀。"},{"en":"Organisations launch campaigns when they want to change public behaviour or awareness.","zh":"組織想改變公眾行為或意識時會展開宣傳活動。"},{"en":"The phrase suggests a public and planned start.","zh":"這個短語暗示公開而有計劃的開始。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":11},{"front":"educational campaign","meaning":"教育宣傳活動","examples":[{"en":"The campaign helps consumers understand travel impacts.","zh":"該宣傳活動幫助消費者理解旅遊影響。"},{"en":"An educational campaign is an organised effort to teach people about an issue.","zh":"educational campaign 指有組織地教導人們某議題的活動。"},{"en":"A health department may run an educational campaign about hand washing.","zh":"衞生部門可能推行關於洗手的教育宣傳活動。"},{"en":"An educational campaign can help travellers ask better questions before booking.","zh":"教育宣傳活動可以幫助旅客在預訂前提出更好的問題。"},{"en":"The phrase focuses on learning and awareness, not selling alone.","zh":"這個短語重點是學習和意識，而不只是銷售。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":11},{"front":"be aimed at","meaning":"旨在","examples":[{"en":"The campaign is aimed at helping consumers make better choices.","zh":"該宣傳活動旨在幫助消費者作出更好選擇。"},{"en":"To be aimed at something means to be designed for that purpose or audience.","zh":"be aimed at something 指被設計用於某目的或對象。"},{"en":"A grammar lesson aimed at beginners should use simple examples.","zh":"旨在初學者的文法課應使用簡單例子。"},{"en":"A campaign aimed at travellers may explain how to check tour operators.","zh":"旨在旅客的宣傳活動可能解釋如何查核旅遊營辦商。"},{"en":"The phrase identifies the target or purpose.","zh":"這個短語指出目標或目的。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":11},{"front":"potential positive and negative impacts","meaning":"潛在正面和負面影響","examples":[{"en":"Travel decisions may have potential positive and negative impacts.","zh":"旅遊決定可能有潛在正面和負面影響。"},{"en":"Potential positive and negative impacts are possible good and bad effects that may result from an action.","zh":"potential positive and negative impacts 指某行動可能帶來的好和壞效果。"},{"en":"Opening a new road can have positive impacts on transport but negative impacts on forests.","zh":"開通新道路可以對交通有正面影響，但對森林有負面影響。"},{"en":"Travellers should consider both benefits to communities and harm to nature.","zh":"旅客應同時考慮對社區的好處和對自然的傷害。"},{"en":"The phrase encourages balanced thinking before making choices.","zh":"這個短語鼓勵人在作選擇前平衡思考。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":11},{"front":"travel decisions","meaning":"旅遊決定","examples":[{"en":"Consumers should understand the impact of their travel decisions.","zh":"消費者應理解其旅遊決定的影響。"},{"en":"Travel decisions are choices people make about where, how, and with whom they travel.","zh":"travel decisions 指人們關於去哪裡、如何去和跟誰去的選擇。"},{"en":"Choosing a train instead of a flight is a travel decision.","zh":"選擇坐火車而不是坐飛機就是一個旅遊決定。"},{"en":"Travel decisions affect carbon emissions, local income, and pressure on destinations.","zh":"旅遊決定影響碳排放、本地收入和目的地壓力。"},{"en":"The phrase focuses on choices made before and during a trip.","zh":"這個短語重點是旅程前和旅程中的選擇。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":11},{"front":"offer guidance on","meaning":"就……提供指引","examples":[{"en":"The society offers guidance on the choice of ecotour.","zh":"該協會就生態旅遊選擇提供指引。"},{"en":"To offer guidance on something means to give advice or direction about it.","zh":"offer guidance on something 指就某事給予建議或方向。"},{"en":"A teacher may offer guidance on how to plan an essay.","zh":"老師可能就如何規劃作文提供指引。"},{"en":"Guidance helps travellers avoid misleading claims and choose better operators.","zh":"指引幫助旅客避開誤導聲稱，並選擇更好營辦商。"},{"en":"The phrase suggests helpful advice, not a command.","zh":"這個短語暗示有用建議，而不是命令。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":11},{"front":"choice of ecotour","meaning":"生態旅遊選擇","examples":[{"en":"Travellers may need guidance on the choice of ecotour.","zh":"旅客可能需要關於生態旅遊選擇的指引。"},{"en":"Choice of ecotour means the decision about which eco-labelled tour to take.","zh":"choice of ecotour 指決定參加哪一個帶環保標籤的旅行團。"},{"en":"A traveller may compare guides, transport, community benefits, and conservation work before choosing.","zh":"旅客在選擇前可能比較導遊、交通、社區好處和保育工作。"},{"en":"A poor choice of ecotour can support harmful businesses despite good intentions.","zh":"差劣的生態旅遊選擇可能即使出於好意，也支持有害企業。"},{"en":"The phrase focuses on selecting one tour from several options.","zh":"這個短語重點是從幾個選項中選一個旅行團。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":12},{"front":"establish a register of","meaning":"建立……名冊","examples":[{"en":"The society has established a register of approved operators.","zh":"該協會已建立認可營辦商名冊。"},{"en":"To establish a register of something means to create an official list of it.","zh":"establish a register of something 指建立某事物的官方名單。"},{"en":"A school may establish a register of approved tutors for parents.","zh":"學校可能為家長建立認可導師名冊。"},{"en":"A register helps travellers find operators that have passed certain checks.","zh":"名冊幫助旅客找到已通過某些查核的營辦商。"},{"en":"The phrase focuses on creating a trusted list.","zh":"這個短語重點是建立可信清單。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":12},{"front":"approved ecotourism operators","meaning":"認可生態旅遊營辦商","examples":[{"en":"The register lists approved ecotourism operators.","zh":"該名冊列出認可生態旅遊營辦商。"},{"en":"Approved ecotourism operators are tour companies that have met certain accepted standards.","zh":"approved ecotourism operators 指已符合某些公認標準的旅遊公司。"},{"en":"Travellers may prefer approved operators because their claims have been checked.","zh":"旅客可能偏好認可營辦商，因為其聲稱已被查核。"},{"en":"Approval can encourage companies to follow better environmental and community practices.","zh":"認可可以鼓勵公司遵循更好的環境和社區做法。"},{"en":"The phrase refers to recognised operators, not every company using the eco label.","zh":"這個短語指獲承認的營辦商，而不是每間使用環保標籤的公司。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":12},{"front":"around the world","meaning":"世界各地","examples":[{"en":"The society lists approved operators around the world.","zh":"該協會列出世界各地的認可營辦商。"},{"en":"Around the world means in many different countries or regions globally.","zh":"around the world 指在全球許多不同國家或地區。"},{"en":"Students around the world use online videos to learn languages.","zh":"世界各地的學生使用網上影片學習語言。"},{"en":"If approved operators are listed around the world, travellers can compare choices internationally.","zh":"如果世界各地的認可營辦商被列出，旅客可以在國際層面比較選擇。"},{"en":"The phrase emphasises global reach.","zh":"這個短語強調全球範圍。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":12},{"front":"leading ecotourism operator","meaning":"主要生態旅遊營辦商","examples":[{"en":"Tribes is a leading ecotourism operator in the United Kingdom.","zh":"Tribes 是英國主要生態旅遊營辦商。"},{"en":"A leading ecotourism operator is one of the main or most respected companies in the field.","zh":"leading ecotourism operator 指該領域中主要或最受尊重的公司之一。"},{"en":"A leading operator may influence standards because smaller companies copy its practices.","zh":"主要營辦商可能影響標準，因為較小公司會模仿其做法。"},{"en":"If a leading operator wins awards, it can shape public ideas about responsible tourism.","zh":"如果主要營辦商獲獎，它可以塑造公眾對負責任旅遊的看法。"},{"en":"The phrase suggests importance within the industry.","zh":"這個短語暗示在業界的重要性。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":12},{"front":"win an award for","meaning":"因……獲獎","examples":[{"en":"Tribes won an award for responsible tourism.","zh":"Tribes 因負責任旅遊而獲獎。"},{"en":"To win an award for something means to receive a prize because of that achievement or quality.","zh":"win an award for something 指因某成就或特質獲得獎項。"},{"en":"A student may win an award for excellent improvement in English.","zh":"學生可能因英文大幅進步而獲獎。"},{"en":"Winning an award can increase trust if the award is based on real standards.","zh":"如果獎項基於真實標準，獲獎可以增加信任。"},{"en":"The phrase links recognition with a specific reason.","zh":"這個短語把認可與具體原因連起來。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":12},{"front":"responsible tour operator","meaning":"負責任旅遊營辦商","examples":[{"en":"Tribes won an award for most responsible tour operator.","zh":"Tribes 獲得最負責任旅遊營辦商獎。"},{"en":"A responsible tour operator runs trips in a way that protects nature and treats local people fairly.","zh":"responsible tour operator 指以保護自然並公平對待本地人的方式營辦旅程的公司。"},{"en":"A responsible operator hires local guides and limits damage to wildlife areas.","zh":"負責任營辦商會聘用本地導遊，並限制對野生地區的破壞。"},{"en":"If a tour operator is responsible, travellers can enjoy the trip without supporting harmful practices.","zh":"如果旅遊營辦商負責任，旅客可以享受旅程而不支持有害做法。"},{"en":"The phrase describes behaviour, not only marketing language.","zh":"這個短語描述行為，而不只是市場推廣語言。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":12},{"front":"owner and director","meaning":"擁有人兼總監","examples":[{"en":"Amanda Marks is the owner and director of Tribes.","zh":"Amanda Marks 是 Tribes 的擁有人兼總監。"},{"en":"Owner and director means the person who owns the business and helps lead or manage it.","zh":"owner and director 指擁有該生意並協助領導或管理的人。"},{"en":"The owner and director of a small school may decide prices, staff, and teaching style.","zh":"小型學校的擁有人兼總監可能決定價格、員工和教學風格。"},{"en":"When the owner and director speaks, the view may represent both personal experience and company leadership.","zh":"當擁有人兼總監發言，其看法可能同時代表個人經驗和公司領導層。"},{"en":"The phrase identifies a senior role with control and responsibility.","zh":"這個短語指出具控制權和責任的高級角色。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":12},{"front":"have some way to go","meaning":"還有一段路要走","examples":[{"en":"The ecotourism industry still has some way to go.","zh":"生態旅遊業仍然還有一段路要走。"},{"en":"To have some way to go means to still need more progress before reaching a goal.","zh":"have some way to go 指距離達成目標仍需要更多進步。"},{"en":"A student who writes clearly but makes grammar mistakes still has some way to go.","zh":"一名寫作清楚但文法常錯的學生仍然還有一段路要走。"},{"en":"If an industry lacks reliable checks, it has some way to go before consumers fully trust it.","zh":"如果行業缺乏可靠查核，它在消費者完全信任前仍有一段路要走。"},{"en":"The phrase is a gentle way to say improvement is still needed.","zh":"這個短語是溫和地表示仍需要改善。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":12},{"front":"get its house in order","meaning":"整頓好內部問題","examples":[{"en":"The ecotourism industry needs to get its house in order.","zh":"生態旅遊業需要整頓好內部問題。"},{"en":"To get its house in order means to fix internal problems and become properly organised.","zh":"get its house in order 指修正內部問題並變得有組織。"},{"en":"A school must get its house in order if timetables, homework, and communication are chaotic.","zh":"如果時間表、功課和溝通混亂，學校必須整頓好內部問題。"},{"en":"Ecotourism needs clearer standards before it can ask travellers for full trust.","zh":"生態旅遊需要更清晰標準，才可要求旅客完全信任。"},{"en":"The phrase suggests internal reform before public confidence is possible.","zh":"這個短語暗示需要先內部改革，然後才可能建立公眾信心。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":12},{"front":"accreditation scheme","meaning":"認證計劃","examples":[{"en":"No ecotourism accreditation scheme had really worked.","zh":"沒有生態旅遊認證計劃真正奏效。"},{"en":"An accreditation scheme is a system for checking and approving organisations that meet standards.","zh":"accreditation scheme 指查核並認可符合標準組織的制度。"},{"en":"A language school may join an accreditation scheme to show teaching quality.","zh":"語言學校可能加入認證計劃，以顯示教學質素。"},{"en":"If a scheme has no real checking, companies may use the label without changing behaviour.","zh":"如果計劃沒有真正查核，公司可能不改變行為也使用標籤。"},{"en":"The phrase focuses on formal approval and standards.","zh":"這個短語重點是正式認可和標準。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":12},{"front":"principally because","meaning":"主要因為","examples":[{"en":"The schemes failed principally because checking was weak.","zh":"這些計劃失敗主要因為查核薄弱。"},{"en":"Principally because means mainly because or for the most important reason that follows.","zh":"principally because 指主要因為，或因為接下來最重要的原因。"},{"en":"The event failed principally because too few people knew about it.","zh":"活動失敗主要因為太少人知道它。"},{"en":"An accreditation scheme fails if companies are approved but not checked properly.","zh":"如果公司獲認可但沒有被妥善查核，認證計劃就會失敗。"},{"en":"The phrase identifies the main cause, not every cause.","zh":"這個短語指出主要原因，而不是所有原因。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":13},{"front":"systematic way of checking","meaning":"系統化查核方法","examples":[{"en":"There was no systematic way of checking accredited companies.","zh":"當時沒有系統化方法查核獲認證公司。"},{"en":"A systematic way of checking is an organised and regular method for inspection or review.","zh":"systematic way of checking 指有組織且定期的檢查或審核方法。"},{"en":"A school needs a systematic way of checking homework if many students forget it.","zh":"如果許多學生忘記功課，學校需要系統化查核功課的方法。"},{"en":"Without systematic checks, poor companies may keep using a trusted logo.","zh":"如果沒有系統化查核，差劣公司可能繼續使用可信標誌。"},{"en":"The phrase stresses method, order, and consistency.","zh":"這個短語強調方法、秩序和一致性。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":13},{"front":"accredited companies","meaning":"獲認證公司","examples":[{"en":"Accredited companies should comply with the code of practice.","zh":"獲認證公司應遵守行業守則。"},{"en":"Accredited companies are businesses officially recognised as meeting certain standards.","zh":"accredited companies 指被正式認可符合某些標準的企業。"},{"en":"An accredited school has passed checks by an approved organisation.","zh":"獲認證學校已通過認可機構的查核。"},{"en":"If accredited companies break the rules, the accreditation system loses trust.","zh":"如果獲認證公司違反規則，認證制度會失去信任。"},{"en":"The phrase refers to companies with formal approval.","zh":"這個短語指獲正式認可的公司。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":13},{"front":"comply with","meaning":"遵守","examples":[{"en":"Accredited companies must comply with the code of practice.","zh":"獲認證公司必須遵守行業守則。"},{"en":"To comply with rules means to follow them properly.","zh":"comply with rules 指正確遵循規則。"},{"en":"Students must comply with exam rules by writing only when allowed.","zh":"學生必須遵守考試規則，只在准許時書寫。"},{"en":"Companies that comply with environmental standards may reduce waste and pollution.","zh":"遵守環境標準的公司可能減少廢物和污染。"},{"en":"The phrase is formal and often used with laws, rules, and standards.","zh":"這個短語較正式，常與法律、規則和標準連用。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":13},{"front":"code of practice","meaning":"行業守則","examples":[{"en":"Operators should comply with a code of practice.","zh":"營辦商應遵守行業守則。"},{"en":"A code of practice is a set of rules or guidelines for proper professional behaviour.","zh":"code of practice 指關於正確專業行為的一套規則或指引。"},{"en":"Teachers may follow a code of practice for marking and student privacy.","zh":"老師可能遵守有關評分和學生私隱的行業守則。"},{"en":"A tourism code of practice can set standards for wages, waste, wildlife, and local culture.","zh":"旅遊行業守則可以為工資、廢物、野生動物和本地文化設定標準。"},{"en":"The phrase refers to agreed behaviour in an industry.","zh":"這個短語指行業中公認的行為規範。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":13},{"front":"the most promising system","meaning":"最有前景的制度","examples":[{"en":"Amanda Marks believes Green Globe 21 is the most promising system.","zh":"Amanda Marks 認為 Green Globe 21 是最有前景的制度。"},{"en":"The most promising system is the system that seems most likely to succeed.","zh":"most promising system 指看起來最有可能成功的制度。"},{"en":"A school may choose the most promising system for tracking student progress.","zh":"學校可能選擇最有前景的系統來追蹤學生進步。"},{"en":"A system becomes promising when it has clear standards and real checks.","zh":"當制度有清晰標準和真正查核，它就變得有前景。"},{"en":"The phrase expresses hope based on evidence, not guaranteed success.","zh":"這個短語表達基於證據的希望，而不是保證成功。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":13},{"front":"recently relaunched","meaning":"最近重新推出","examples":[{"en":"Green Globe 21 was recently relaunched.","zh":"Green Globe 21 最近重新推出。"},{"en":"Recently relaunched means started again in a new or improved form not long ago.","zh":"recently relaunched 指不久前以新的或改善形式重新開始。"},{"en":"A restaurant may be recently relaunched with a new menu and clearer brand.","zh":"餐廳可能以新餐牌和更清晰品牌最近重新推出。"},{"en":"Relaunching a scheme can fix earlier weaknesses and rebuild public trust.","zh":"重新推出計劃可以修正早期弱點並重建公眾信任。"},{"en":"The phrase suggests a fresh start after change.","zh":"這個短語暗示改變後的新開始。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":13},{"front":"be based on","meaning":"以……為基礎","examples":[{"en":"The Green Globe 21 award is based on sustainable development standards.","zh":"Green Globe 21 獎項以可持續發展標準為基礎。"},{"en":"To be based on something means to use it as the foundation or main support.","zh":"be based on something 指以某事作為基礎或主要支撐。"},{"en":"A lesson plan may be based on students’ common grammar mistakes.","zh":"教案可能以學生常見文法錯誤為基礎。"},{"en":"If an award is based on clear standards, it is more credible.","zh":"如果獎項以清晰標準為基礎，它就更可信。"},{"en":"The phrase shows the source or foundation of a decision.","zh":"這個短語顯示決定的來源或基礎。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":13},{"front":"sustainable development standards","meaning":"可持續發展標準","examples":[{"en":"The award is based on sustainable development standards.","zh":"該獎項以可持續發展標準為基礎。"},{"en":"Sustainable development standards are rules or criteria for balancing growth with environmental and social responsibility.","zh":"sustainable development standards 指平衡發展、環境責任和社會責任的規則或準則。"},{"en":"A hotel may meet sustainable standards by reducing waste and hiring local workers fairly.","zh":"酒店可以透過減少廢物和公平聘用本地工人來符合可持續標準。"},{"en":"Standards help turn broad ideals into measurable actions.","zh":"標準幫助把廣泛理想變成可量度行動。"},{"en":"The phrase connects sustainability with practical evaluation.","zh":"這個短語把可持續性與實際評估連起來。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":13},{"front":"be contained in","meaning":"載於","examples":[{"en":"The standards are contained in Agenda 21.","zh":"這些標準載於《21世紀議程》。"},{"en":"To be contained in a document means to be included or written inside it.","zh":"be contained in a document 指被包括或寫在某文件之內。"},{"en":"School rules are contained in the student handbook.","zh":"校規載於學生手冊。"},{"en":"If standards are contained in an official document, organisations can refer to the same source.","zh":"如果標準載於官方文件，組織可以參考同一來源。"},{"en":"The phrase points to where information is found.","zh":"這個短語指出資訊在哪裡找到。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":13},{"front":"Agenda 21","meaning":"《21世紀議程》","examples":[{"en":"The standards came from Agenda 21.","zh":"這些標準來自《21世紀議程》。"},{"en":"Agenda 21 is a named international action plan linked to sustainable development.","zh":"Agenda 21 是一項與可持續發展相關的國際行動計劃名稱。"},{"en":"A tourism scheme may use Agenda 21 to support environmental and social standards.","zh":"旅遊計劃可能使用《21世紀議程》來支持環境和社會標準。"},{"en":"Referring to Agenda 21 gives a programme a recognised policy foundation.","zh":"參考《21世紀議程》能為項目提供受承認的政策基礎。"},{"en":"The phrase is a proper noun, so it should be kept accurate.","zh":"這個短語是專有名詞，因此應保持準確。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":13},{"front":"Earth Summit","meaning":"地球高峰會","examples":[{"en":"Agenda 21 came from the 1992 Earth Summit.","zh":"《21世紀議程》來自1992年地球高峰會。"},{"en":"The Earth Summit was an international meeting focused on environment and development issues.","zh":"Earth Summit 指集中於環境和發展議題的國際會議。"},{"en":"Global meetings like the Earth Summit can produce principles for later policies.","zh":"像地球高峰會這樣的全球會議可以制定後來政策的原則。"},{"en":"If an award uses standards from the Earth Summit, it connects tourism with global sustainability goals.","zh":"如果獎項使用來自地球高峰會的標準，它就把旅遊與全球可持續目標連起來。"},{"en":"The phrase names a major environmental conference.","zh":"這個短語是一個重大環境會議名稱。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":14},{"front":"originally coordinated by","meaning":"最初由……協調","examples":[{"en":"The award was originally coordinated by the World Travel & Tourism Council.","zh":"該獎項最初由世界旅遊及旅行理事會協調。"},{"en":"Originally coordinated by someone means that person or organisation first managed or organised it.","zh":"originally coordinated by someone 指最初由某人或機構管理或組織。"},{"en":"A school exchange programme may be originally coordinated by one teacher before a department takes over.","zh":"學校交流計劃可能最初由一名老師協調，後來由學系接手。"},{"en":"Knowing who originally coordinated a scheme helps explain its history and early direction.","zh":"知道計劃最初由誰協調，有助解釋其歷史和早期方向。"},{"en":"The phrase focuses on the first organiser.","zh":"這個短語重點是最初組織者。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":14},{"front":"World Travel & Tourism Council","meaning":"世界旅遊及旅行理事會","examples":[{"en":"The World Travel & Tourism Council originally coordinated the scheme.","zh":"世界旅遊及旅行理事會最初協調該計劃。"},{"en":"The World Travel & Tourism Council is an organisation connected with the global travel and tourism industry.","zh":"World Travel & Tourism Council 指與全球旅遊及旅行業相關的組織。"},{"en":"Such a council may represent industry interests and support tourism standards.","zh":"這類理事會可能代表業界利益並支持旅遊標準。"},{"en":"If a major tourism council supports a scheme, operators may take it more seriously.","zh":"如果主要旅遊理事會支持某計劃，營辦商可能更認真看待它。"},{"en":"The phrase is a formal organisation name.","zh":"這個短語是正式組織名稱。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":14},{"front":"independent concern","meaning":"獨立機構","examples":[{"en":"The scheme is now an independent concern.","zh":"該計劃現在是一個獨立機構。"},{"en":"An independent concern is an organisation or business operating separately from another body.","zh":"independent concern 指獨立於另一機構運作的組織或企業。"},{"en":"A school magazine may become an independent concern after leaving the student union.","zh":"學校雜誌離開學生會後可能成為獨立機構。"},{"en":"Independence can make a certification scheme appear less controlled by industry interests.","zh":"獨立性可以令認證計劃看起來較不受業界利益控制。"},{"en":"The phrase stresses separate operation.","zh":"這個短語強調獨立運作。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":14},{"front":"still supports it","meaning":"仍然支持它","examples":[{"en":"The World Travel & Tourism Council still supports the scheme.","zh":"世界旅遊及旅行理事會仍然支持該計劃。"},{"en":"Still supports it means continues to approve, help, or back it.","zh":"still supports it 指繼續認可、幫助或支持它。"},{"en":"A former founder may still support a charity even after leaving daily management.","zh":"前創辦人即使離開日常管理，仍可能支持慈善機構。"},{"en":"Continued support from a respected body can give a scheme more credibility.","zh":"受尊重機構的持續支持可以令計劃更可信。"},{"en":"The phrase shows that support has not ended.","zh":"這個短語顯示支持尚未結束。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":14},{"front":"become affiliates","meaning":"成為附屬成員","examples":[{"en":"Tour companies used to become affiliates by paying a fee.","zh":"旅遊公司過去只需支付費用便可成為附屬成員。"},{"en":"To become affiliates means to join a scheme or organisation as connected members.","zh":"become affiliates 指作為相關成員加入某計劃或組織。"},{"en":"A small school may become an affiliate of a larger education network.","zh":"小型學校可能成為大型教育網絡的附屬成員。"},{"en":"If companies can become affiliates only by paying, membership may not prove quality.","zh":"如果公司只需付款就能成為附屬成員，會員身份未必證明質素。"},{"en":"The phrase describes formal connection, not necessarily high standards.","zh":"這個短語描述正式連繫，而不一定代表高標準。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":14},{"front":"use the logo","meaning":"使用標誌","examples":[{"en":"Affiliates could use the Green Globe logo.","zh":"附屬成員可以使用 Green Globe 標誌。"},{"en":"To use the logo means to display an organisation’s official symbol on materials or products.","zh":"use the logo 指在材料或產品上展示某組織的官方符號。"},{"en":"A certified shop may use the logo on its website and receipts.","zh":"獲認證商店可能在網站和收據上使用標誌。"},{"en":"If companies use a trusted logo without real checks, consumers may be misled.","zh":"如果公司未經真正查核也使用可信標誌，消費者可能被誤導。"},{"en":"The phrase focuses on visible branding.","zh":"這個短語重點是可見品牌標識。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":14},{"front":"merely on payment of","meaning":"僅憑支付……","examples":[{"en":"Companies could use the logo merely on payment of an annual fee.","zh":"公司僅憑支付年費便可使用標誌。"},{"en":"Merely on payment of something means only by paying, without further requirements.","zh":"merely on payment of something 指只要付款，而沒有其他要求。"},{"en":"A club that admits members merely on payment of a fee may not check their skills.","zh":"如果社團僅憑支付費用就收會員，它可能不查核會員技能。"},{"en":"If a green logo is available merely on payment, it is a weak quality standard.","zh":"如果綠色標誌僅憑付款就可取得，它就是薄弱的質素標準。"},{"en":"The phrase suggests payment alone is not enough.","zh":"這個短語暗示單靠付款不足夠。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":14},{"front":"annual fee","meaning":"年費","examples":[{"en":"Companies paid an annual fee to use the logo.","zh":"公司支付年費以使用標誌。"},{"en":"An annual fee is money paid once every year for membership, access, or use of a service.","zh":"annual fee 指每年支付一次的會費、使用費或服務費。"},{"en":"A gym may charge an annual fee for membership.","zh":"健身室可能收取會員年費。"},{"en":"If certification requires only an annual fee, consumers may doubt its seriousness.","zh":"如果認證只需要年費，消費者可能懷疑其嚴肅性。"},{"en":"The phrase describes regular yearly payment.","zh":"這個短語描述定期每年付款。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":14},{"front":"suitable qualifying standard","meaning":"合適的資格標準","examples":[{"en":"Payment alone was hardly a suitable qualifying standard.","zh":"單靠付款幾乎不是合適的資格標準。"},{"en":"A suitable qualifying standard is a fair requirement that proves someone deserves approval.","zh":"suitable qualifying standard 指能證明某人值得認可的公平要求。"},{"en":"A driving test is a suitable qualifying standard for a driving licence.","zh":"駕駛考試是獲得駕照的合適資格標準。"},{"en":"Payment is not suitable if the goal is to prove environmental responsibility.","zh":"如果目標是證明環境責任，付款就不合適。"},{"en":"The phrase asks whether the requirement truly measures quality.","zh":"這個短語詢問該要求是否真正衡量質素。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":14},{"front":"introduce an annual check","meaning":"引入年度檢查","examples":[{"en":"Green Globe 21 introduced an annual check on operators.","zh":"Green Globe 21 引入對營辦商的年度檢查。"},{"en":"To introduce an annual check means to start a yearly inspection or review.","zh":"introduce an annual check 指開始每年進行檢查或審核。"},{"en":"A school may introduce an annual check of classroom safety.","zh":"學校可能引入課室安全年度檢查。"},{"en":"Annual checks help prevent companies from meeting standards once and then slipping later.","zh":"年度檢查有助防止公司只一次符合標準，之後又退步。"},{"en":"The phrase suggests regular accountability.","zh":"這個短語暗示定期問責。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":14},{"front":"independent check","meaning":"獨立檢查","examples":[{"en":"The scheme introduced an independent check on operators.","zh":"該計劃引入對營辦商的獨立檢查。"},{"en":"An independent check is an inspection done by someone not controlled by the company being checked.","zh":"independent check 指由不受被查公司控制的人進行檢查。"},{"en":"An independent check of exam results can make grading fairer.","zh":"對考試成績作獨立檢查可以令評分更公平。"},{"en":"Independent checks increase trust because companies cannot simply approve themselves.","zh":"獨立檢查增加信任，因為公司不能自行批准自己。"},{"en":"The phrase stresses outside review.","zh":"這個短語強調外部審核。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":15},{"front":"operators wishing to","meaning":"希望……的營辦商","examples":[{"en":"Operators wishing to use the logo must now be checked.","zh":"希望使用標誌的營辦商現在必須接受查核。"},{"en":"Operators wishing to do something are companies that want or intend to do it.","zh":"operators wishing to do something 指想要或打算做某事的公司。"},{"en":"Students wishing to join the trip must submit forms before Friday.","zh":"希望參加旅行的學生必須在星期五前提交表格。"},{"en":"Operators wishing to use a trusted logo should prove they meet the standards.","zh":"希望使用可信標誌的營辦商應證明自己符合標準。"},{"en":"The phrase is formal and often used in rules or instructions.","zh":"這個短語較正式，常用於規則或指示。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":15},{"front":"marketing department","meaning":"市場推廣部","examples":[{"en":"Miriam Cain works in the Green Globe 21 marketing department.","zh":"Miriam Cain 在 Green Globe 21 市場推廣部工作。"},{"en":"A marketing department is the part of an organisation that promotes products, services, or messages.","zh":"marketing department 指組織中負責推廣產品、服務或訊息的部門。"},{"en":"A school’s marketing department may write course descriptions and manage social media.","zh":"學校的市場推廣部可能撰寫課程介紹並管理社交媒體。"},{"en":"Marketing departments shape how consumers understand a brand or scheme.","zh":"市場推廣部塑造消費者如何理解品牌或計劃。"},{"en":"The phrase refers to promotional work inside an organisation.","zh":"這個短語指組織內部的推廣工作。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":15},{"front":"current and new affiliates","meaning":"現有及新附屬成員","examples":[{"en":"Current and new affiliates have one year to meet the standards.","zh":"現有及新附屬成員有一年時間符合標準。"},{"en":"Current and new affiliates are existing members and organisations joining the scheme now.","zh":"current and new affiliates 指現有成員和現在加入計劃的組織。"},{"en":"A club may give current and new members the same deadline for updated rules.","zh":"社團可能給現有及新會員相同期限去遵守更新規則。"},{"en":"Giving all affiliates one year allows them time to improve operations.","zh":"給所有附屬成員一年時間，讓它們有時間改善營運。"},{"en":"The phrase includes both old and incoming members.","zh":"這個短語同時包括舊成員和新加入成員。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":15},{"front":"ensure that","meaning":"確保","examples":[{"en":"Affiliates must ensure that their operations meet the standards.","zh":"附屬成員必須確保其營運符合標準。"},{"en":"To ensure that something happens means to make sure it happens.","zh":"ensure that something happens 指確保某事發生。"},{"en":"Teachers ensure that students understand instructions before starting an exam.","zh":"老師在考試開始前確保學生明白指示。"},{"en":"Operators must check their daily practices if they want to ensure that standards are met.","zh":"如果營辦商想確保符合標準，就必須檢查日常做法。"},{"en":"The phrase expresses responsibility for a result.","zh":"這個短語表達對結果的責任。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":15},{"front":"operations comply with","meaning":"業務運作符合……","examples":[{"en":"Operators must ensure that their operations comply with Agenda 21 standards.","zh":"營辦商必須確保其業務運作符合《21世紀議程》標準。"},{"en":"Operations comply with standards when daily activities follow the required rules.","zh":"operations comply with standards 指日常活動遵循所要求規則。"},{"en":"A restaurant’s operations comply with hygiene rules when food storage and cleaning are checked.","zh":"當食物儲存和清潔受到檢查，餐廳業務運作就符合衛生規則。"},{"en":"If tour operations comply with sustainability standards, waste, wages, and community impact are managed.","zh":"如果旅遊業務運作符合可持續標準，廢物、工資和社區影響都會被管理。"},{"en":"The phrase connects everyday practice with formal requirements.","zh":"這個短語把日常實踐與正式要求連起來。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":15},{"front":"fail the first inspection","meaning":"首次檢查不合格","examples":[{"en":"If companies fail the first inspection, they can reapply once.","zh":"如果公司首次檢查不合格，它們可以重新申請一次。"},{"en":"To fail the first inspection means not to meet the required standard during the initial check.","zh":"fail the first inspection 指在最初檢查中未能符合所需標準。"},{"en":"A restaurant may fail the first inspection if its kitchen is not clean enough.","zh":"如果廚房不夠乾淨，餐廳可能首次檢查不合格。"},{"en":"Failing the first inspection gives companies a chance to fix problems before trying again.","zh":"首次檢查不合格給公司機會修正問題再嘗試。"},{"en":"The phrase refers to the first formal test or review.","zh":"這個短語指第一次正式測試或審核。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":15},{"front":"reapply once","meaning":"只可重新申請一次","examples":[{"en":"Companies that fail can only reapply once.","zh":"不合格公司只可重新申請一次。"},{"en":"To reapply once means to submit an application one more time and no more.","zh":"reapply once 指再提交一次申請，不能更多。"},{"en":"A student who misses a scholarship deadline may be allowed to reapply once next year.","zh":"錯過獎學金期限的學生可能獲准明年重新申請一次。"},{"en":"Limiting reapplication prevents companies from repeatedly failing without real change.","zh":"限制重新申請可防止公司反覆不合格卻沒有真正改變。"},{"en":"The phrase sets a strict second-chance rule.","zh":"這個短語設定嚴格的第二次機會規則。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":15},{"front":"inspection process","meaning":"檢查程序","examples":[{"en":"The inspection process is not a cheap option.","zh":"檢查程序並不是便宜的選擇。"},{"en":"An inspection process is the set of steps used to check whether standards are met.","zh":"inspection process 指用來檢查是否符合標準的一套步驟。"},{"en":"A building inspection process may include checking fire exits, wiring, and safety signs.","zh":"建築物檢查程序可能包括檢查消防出口、電線和安全標誌。"},{"en":"A detailed inspection process costs money because trained people must review real practices.","zh":"詳細檢查程序需要成本，因為受訓人員必須審核真實做法。"},{"en":"The phrase refers to organised checking, not a quick look.","zh":"這個短語指有組織查核，而不是快速看一眼。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":15},{"front":"not a cheap option","meaning":"並不便宜的選擇","examples":[{"en":"The inspection process is not a cheap option for large companies.","zh":"對大公司而言，檢查程序並不便宜。"},{"en":"Not a cheap option means it costs a lot or requires significant resources.","zh":"not a cheap option 指成本高或需要大量資源。"},{"en":"Hiring a private tutor every day is not a cheap option for many families.","zh":"每天聘請私人導師對許多家庭而言並不便宜。"},{"en":"Independent inspections are not cheap because they require trained assessors and travel.","zh":"獨立檢查並不便宜，因為它需要受訓評審員和交通。"},{"en":"The phrase warns that the choice may be financially demanding.","zh":"這個短語提醒該選擇可能在財務上要求很高。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":15},{"front":"large companies","meaning":"大公司","examples":[{"en":"The inspection process can be expensive for large companies.","zh":"檢查程序對大公司而言可能昂貴。"},{"en":"Large companies are businesses with many staff, operations, customers, or locations.","zh":"large companies 指有許多員工、營運、顧客或地點的企業。"},{"en":"A large company may need several departments to manage travel, finance, and customer service.","zh":"大公司可能需要多個部門管理旅遊、財務和客戶服務。"},{"en":"Checking a large company can be costly because many branches and practices must be reviewed.","zh":"查核大公司可能成本高，因為必須審核許多分店和做法。"},{"en":"The phrase contrasts big organisations with small businesses.","zh":"這個短語把大型組織與小企業作對比。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":15},{"front":"benefits of having Green Globe status","meaning":"擁有 Green Globe 資格的好處","examples":[{"en":"Companies may benefit from having Green Globe status.","zh":"公司可能從擁有 Green Globe 資格中受益。"},{"en":"Benefits of having Green Globe status are advantages that come from being officially recognised by the scheme.","zh":"benefits of having Green Globe status 指獲該計劃正式認可帶來的好處。"},{"en":"A company with recognised status may attract travellers who care about sustainability.","zh":"擁有認可資格的公司可能吸引關心可持續性的旅客。"},{"en":"Certification can also push companies to reduce waste and save operating costs.","zh":"認證也可以推動公司減少廢物並節省營運成本。"},{"en":"The phrase refers to practical gains from approval.","zh":"這個短語指由認可帶來的實際好處。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":16},{"front":"potential operational cost savings","meaning":"潛在營運成本節省","examples":[{"en":"Compliance may bring potential operational cost savings.","zh":"合規可能帶來潛在營運成本節省。"},{"en":"Potential operational cost savings are possible reductions in the cost of running a business.","zh":"potential operational cost savings 指營運企業成本可能降低。"},{"en":"A hotel may save money by using less electricity and water.","zh":"酒店可以透過使用較少電力和食水來省錢。"},{"en":"If sustainability standards reduce waste, they can also reduce operating costs.","zh":"如果可持續標準減少浪費，它們也可以降低營運成本。"},{"en":"The phrase links environmental practice with financial benefit.","zh":"這個短語把環保做法與財務好處連起來。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":16},{"front":"complying with the standards","meaning":"遵守標準","examples":[{"en":"Complying with the standards can bring cost savings.","zh":"遵守標準可以帶來成本節省。"},{"en":"Complying with the standards means following the required rules or criteria.","zh":"complying with the standards 指遵循所要求的規則或準則。"},{"en":"A restaurant complying with hygiene standards keeps food safely stored and kitchens clean.","zh":"遵守衛生標準的餐廳會安全儲存食物並保持廚房清潔。"},{"en":"Companies that comply with sustainability standards may use fewer resources over time.","zh":"遵守可持續標準的公司隨時間可能使用較少資源。"},{"en":"The phrase focuses on actual behaviour, not simply signing a document.","zh":"這個短語重點是實際行為，而不是單純簽署文件。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":16},{"front":"be significant","meaning":"顯著","examples":[{"en":"The benefits should be significant.","zh":"這些好處應該是顯著的。"},{"en":"To be significant means to be large enough or important enough to matter.","zh":"be significant 指大到或重要到值得關注。"},{"en":"A significant improvement in grades can show that a study plan is working.","zh":"成績顯著改善可以顯示學習計劃有效。"},{"en":"If cost savings are significant, companies have a stronger reason to follow standards.","zh":"如果成本節省顯著，公司就有更強理由遵守標準。"},{"en":"The word suggests importance, not a tiny effect.","zh":"這個詞暗示重要性，而不是微小效果。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":16},{"front":"joint ventures with","meaning":"與……合資合作","examples":[{"en":"Green Globe 21 has joint ventures with organisations around the world.","zh":"Green Globe 21 與世界各地組織有合資合作。"},{"en":"Joint ventures with others are business or project partnerships shared between two or more organisations.","zh":"joint ventures with others 指兩個或更多組織共同參與的商業或項目合作。"},{"en":"A school may form a joint venture with a technology company to build an online platform.","zh":"學校可能與科技公司合資合作建立網上平台。"},{"en":"Joint ventures allow organisations to share expertise, staff, and local knowledge.","zh":"合資合作使組織能分享專業知識、人手和本地知識。"},{"en":"The phrase describes cooperative work, not simple sponsorship.","zh":"這個短語描述合作工作，而不是單純贊助。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":16},{"front":"organisations around the world","meaning":"世界各地的組織","examples":[{"en":"The scheme works with organisations around the world.","zh":"該計劃與世界各地的組織合作。"},{"en":"Organisations around the world are groups or institutions located in many countries.","zh":"organisations around the world 指位於許多國家的團體或機構。"},{"en":"Environmental organisations around the world may share data on wildlife and climate.","zh":"世界各地的環保組織可能分享野生動物和氣候數據。"},{"en":"Working with global organisations helps a scheme check operators in different regions.","zh":"與全球組織合作幫助計劃查核不同地區的營辦商。"},{"en":"The phrase emphasises international cooperation.","zh":"這個短語強調國際合作。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":16},{"front":"allow someone to","meaning":"使某人能夠","examples":[{"en":"These partnerships allow Green Globe 21 to check operators effectively.","zh":"這些合作使 Green Globe 21 能夠有效查核營辦商。"},{"en":"To allow someone to do something means to make it possible or permitted for them to do it.","zh":"allow someone to do something 指使某人可以或獲准做某事。"},{"en":"A library card allows students to borrow books and use study rooms.","zh":"圖書證使學生能夠借書和使用自修室。"},{"en":"Local partnerships allow inspectors to check companies in places they cannot visit alone.","zh":"本地合作使檢查員能夠查核他們無法獨自到訪地方的公司。"},{"en":"The phrase can mean giving permission or creating ability.","zh":"這個短語可以指給予許可或創造能力。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":16},{"front":"effectively check","meaning":"有效查核","examples":[{"en":"The scheme can effectively check all affiliate operators.","zh":"該計劃可以有效查核所有附屬營辦商。"},{"en":"To effectively check something means to inspect it in a way that truly works.","zh":"effectively check something 指以真正有效的方式檢查某事。"},{"en":"Teachers effectively check understanding when they ask students to explain answers in their own words.","zh":"老師要求學生用自己的話解釋答案時，就能有效查核理解。"},{"en":"A certification scheme can effectively check operators only if inspections are independent and regular.","zh":"認證計劃只有在檢查獨立且定期時，才能有效查核營辦商。"},{"en":"The phrase stresses real effectiveness, not surface review.","zh":"這個短語強調真正有效，而不是表面審核。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":16},{"front":"affiliate operators","meaning":"附屬營辦商","examples":[{"en":"Affiliate operators must be checked under the scheme.","zh":"附屬營辦商必須在計劃下接受查核。"},{"en":"Affiliate operators are tour companies connected to a scheme or organisation as members.","zh":"affiliate operators 指作為成員與某計劃或組織連繫的旅遊公司。"},{"en":"An affiliate operator may use a logo after meeting required standards.","zh":"附屬營辦商在符合所需標準後可能使用標誌。"},{"en":"If affiliate operators are not checked, membership loses meaning.","zh":"如果附屬營辦商沒有被查核，會員身份就失去意義。"},{"en":"The phrase refers to operators formally linked to a programme.","zh":"這個短語指與項目正式連繫的營辦商。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":16},{"front":"destination communities","meaning":"旅遊目的地社區","examples":[{"en":"Destination communities can also become approved.","zh":"旅遊目的地社區也可以成為認可。"},{"en":"Destination communities are local communities in places where tourists travel.","zh":"destination communities 指遊客前往地點中的本地社區。"},{"en":"A mountain village that receives hikers is a destination community.","zh":"接待行山客的山村就是旅遊目的地社區。"},{"en":"If destination communities are included in approval systems, residents can help shape tourism standards.","zh":"如果旅遊目的地社區被納入認可制度，居民可以幫助塑造旅遊標準。"},{"en":"The phrase focuses on people living at the travel destination.","zh":"這個短語重點是居住在旅遊目的地的人。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":16},{"front":"become approved","meaning":"成為認可","examples":[{"en":"Communities can become Green Globe 21 approved.","zh":"社區可以成為 Green Globe 21 認可。"},{"en":"To become approved means to receive formal acceptance after meeting standards.","zh":"become approved 指在符合標準後獲得正式接受。"},{"en":"A restaurant can become approved by a health authority after passing inspection.","zh":"餐廳通過檢查後可以獲衛生部門認可。"},{"en":"Communities become approved when they show that tourism is managed responsibly.","zh":"當社區顯示旅遊得到負責任管理，它們就可以成為認可。"},{"en":"The phrase suggests official recognition.","zh":"這個短語暗示官方承認。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":16},{"front":"relatively new industry","meaning":"相對新興的行業","examples":[{"en":"Ecotourism is a relatively new industry.","zh":"生態旅遊是一個相對新興的行業。"},{"en":"A relatively new industry is a business field that has not existed or developed for very long.","zh":"relatively new industry 指存在或發展時間不算長的商業領域。"},{"en":"Online tutoring was a relatively new industry before many families became used to it.","zh":"在許多家庭習慣網上補習之前，網上補習曾是相對新興的行業。"},{"en":"New industries often have unclear standards because rules have not caught up.","zh":"新興行業常有不清晰標準，因為規則尚未跟上。"},{"en":"The phrase explains why early problems may occur.","zh":"這個短語解釋為何早期問題可能出現。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":17},{"front":"it is not surprising that","meaning":"……並不令人驚訝","examples":[{"en":"It is not surprising that ecotourism has had problems.","zh":"生態旅遊出現過問題並不令人驚訝。"},{"en":"It is not surprising that means the result is understandable or expected.","zh":"it is not surprising that 指某結果可以理解或可以預期。"},{"en":"It is not surprising that students are tired after three exams in one week.","zh":"一週內考三次試後學生疲倦並不令人驚訝。"},{"en":"If an industry grows quickly without clear rules, it is not surprising that confusion follows.","zh":"如果一個行業在沒有清晰規則下快速增長，隨之出現混亂並不令人驚訝。"},{"en":"The phrase shows that the writer sees a logical reason behind the situation.","zh":"這個短語顯示作者看見情況背後有合理原因。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":17},{"front":"undergo teething pains","meaning":"經歷初期問題","examples":[{"en":"Ecotourism has undergone teething pains.","zh":"生態旅遊已經歷初期問題。"},{"en":"To undergo teething pains means to experience early problems while something is still developing.","zh":"undergo teething pains 指在某事仍在發展時經歷早期問題。"},{"en":"A new school app may undergo teething pains when students first start using it.","zh":"學生剛開始使用新學校應用程式時，它可能經歷初期問題。"},{"en":"Early problems do not always mean failure; they may show a system still needs adjustment.","zh":"早期問題不一定代表失敗；它們可能顯示系統仍需調整。"},{"en":"The phrase compares a new industry to a growing child.","zh":"這個短語把新行業比作正在成長的孩子。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":17},{"front":"signs that","meaning":"……的跡象","examples":[{"en":"There are signs that things are changing for the better.","zh":"有跡象顯示事情正向好的方向改變。"},{"en":"Signs that something is happening are clues or evidence suggesting it may be true.","zh":"signs that something is happening 指暗示某事可能屬實的線索或證據。"},{"en":"Better attendance and stronger homework are signs that students are improving.","zh":"更好出席率和更強功課表現是學生正在進步的跡象。"},{"en":"New standards and checks may be signs that an industry is becoming more responsible.","zh":"新標準和檢查可能是行業變得更負責任的跡象。"},{"en":"The phrase introduces evidence of a trend.","zh":"這個短語引入趨勢的證據。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":17},{"front":"change for the better","meaning":"向好的方向改變","examples":[{"en":"There are signs that ecotourism is changing for the better.","zh":"有跡象顯示生態旅遊正向好的方向改變。"},{"en":"To change for the better means to improve.","zh":"change for the better 指改善。"},{"en":"A class can change for the better when students begin helping one another.","zh":"當學生開始互相幫助，一班可以向好的方向改變。"},{"en":"Ecotourism changes for the better when labels become clearer and communities benefit more.","zh":"當標籤變得更清楚而社區受益更多，生態旅遊就向好的方向改變。"},{"en":"The phrase describes positive development.","zh":"這個短語描述正面發展。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":17},{"front":"committed and unified approach","meaning":"堅定而一致的做法","examples":[{"en":"Ecotourism needs a committed and unified approach.","zh":"生態旅遊需要堅定而一致的做法。"},{"en":"A committed and unified approach is a serious, shared method followed by all key groups.","zh":"committed and unified approach 指所有關鍵群體共同遵循的認真一致方法。"},{"en":"A school improves faster when teachers use a committed and unified approach to discipline.","zh":"當老師對紀律使用堅定而一致的做法，學校會更快改善。"},{"en":"Ecotourism needs shared effort from companies, communities, and experts to build trust.","zh":"生態旅遊需要公司、社區和專家的共同努力來建立信任。"},{"en":"The phrase stresses dedication and cooperation.","zh":"這個短語強調投入和合作。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":17},{"front":"travel industry","meaning":"旅遊業","examples":[{"en":"The travel industry must work with local communities and experts.","zh":"旅遊業必須與本地社區和專家合作。"},{"en":"The travel industry includes businesses and workers involved in transport, holidays, hotels, tours, and tourism services.","zh":"travel industry 指涉及交通、假期、酒店、旅行團和旅遊服務的企業和工作者。"},{"en":"Airlines, hotels, guides, and booking websites are part of the travel industry.","zh":"航空公司、酒店、導遊和預訂網站都是旅遊業的一部分。"},{"en":"If the travel industry ignores local communities, tourism may become harmful.","zh":"如果旅遊業忽視本地社區，旅遊可能變得有害。"},{"en":"The phrase refers to the whole business field of travel.","zh":"這個短語指整個旅遊商業領域。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":17},{"front":"environmental experts","meaning":"環保專家","examples":[{"en":"Environmental experts can help improve ecotourism.","zh":"環保專家可以幫助改善生態旅遊。"},{"en":"Environmental experts are people with specialist knowledge of nature, pollution, conservation, or ecosystems.","zh":"environmental experts 指對自然、污染、保育或生態系統有專門知識的人。"},{"en":"An environmental expert may advise a hotel on water use and waste reduction.","zh":"環保專家可能就用水和減少廢物向酒店提供建議。"},{"en":"Expert advice helps operators avoid damaging habitats they do not fully understand.","zh":"專家建議幫助營辦商避免破壞他們未完全理解的棲息地。"},{"en":"The phrase refers to people with technical environmental knowledge.","zh":"這個短語指具有環境技術知識的人。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":17},{"front":"a tag to be proud of","meaning":"值得自豪的標籤","examples":[{"en":"Ecotourism could become a tag to be proud of.","zh":"生態旅遊可以成為值得自豪的標籤。"},{"en":"A tag to be proud of is a label that genuinely represents good standards or values.","zh":"tag to be proud of 指真正代表良好標準或價值的標籤。"},{"en":"A school badge becomes a tag to be proud of when students associate it with fairness and care.","zh":"當學生把校徽與公平和關懷連繫起來，它就成為值得自豪的標籤。"},{"en":"If ecotourism becomes honest and well regulated, companies can use the label proudly.","zh":"如果生態旅遊變得誠實且規管良好，公司就可以自豪地使用該標籤。"},{"en":"The phrase suggests reputation has been restored.","zh":"這個短語暗示聲譽已被恢復。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":17},{"front":"a tag to trust","meaning":"值得信任的標籤","examples":[{"en":"Ecotourism could become a tag that travellers can trust.","zh":"生態旅遊可以成為旅客能信任的標籤。"},{"en":"A tag to trust is a label consumers can believe because it is checked and meaningful.","zh":"tag to trust 指因經查核且有意義而讓消費者相信的標籤。"},{"en":"A food safety label becomes a tag to trust when inspections are strict.","zh":"當檢查嚴格，食物安全標籤就成為值得信任的標籤。"},{"en":"Travellers can trust a tag only if it is backed by real standards and independent checks.","zh":"只有當標籤有真實標準和獨立檢查支持，旅客才能信任它。"},{"en":"The phrase focuses on confidence in a label.","zh":"這個短語重點是對標籤的信心。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":17},{"front":"agree with the views of","meaning":"與……的觀點一致","examples":[{"en":"Students decide whether the statements agree with the views of the writer.","zh":"學生判斷陳述是否與作者觀點一致。"},{"en":"To agree with the views of someone means to match that person’s opinions or claims.","zh":"agree with the views of someone 指與某人的意見或主張相符。"},{"en":"In reading tests, students must check the writer’s wording instead of using personal opinion.","zh":"在閱讀測驗中，學生必須檢查作者用字，而不是使用個人意見。"},{"en":"A statement agrees with the writer only when the passage clearly supports it.","zh":"只有當篇章清楚支持某陳述，它才與作者觀點一致。"},{"en":"The phrase is common in Yes, No, Not Given questions.","zh":"這個短語常見於 Yes, No, Not Given 題目。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":17},{"front":"contradict the views of","meaning":"與……的觀點相矛盾","examples":[{"en":"Students write NO if the statement contradicts the views of the writer.","zh":"如果陳述與作者觀點相矛盾，學生寫 NO。"},{"en":"To contradict the views of someone means to say the opposite of that person’s opinion.","zh":"contradict the views of someone 指說出與某人意見相反的內容。"},{"en":"If the writer says regulation is needed, a statement saying regulation is unnecessary contradicts the view.","zh":"如果作者說需要規管，而陳述說規管不必要，就是與其觀點相矛盾。"},{"en":"Students should choose NO only when there is a direct conflict.","zh":"學生只有在有直接衝突時才應選 NO。"},{"en":"The phrase means disagreement with the writer, not missing information.","zh":"這個短語表示與作者不同意，而不是資料缺失。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":18},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"Students write NOT GIVEN if it is impossible to say what the writer thinks.","zh":"如果無法判斷作者怎樣想，學生寫 NOT GIVEN。"},{"en":"Impossible to say means there is not enough information to decide.","zh":"impossible to say 指資料不足，無法決定。"},{"en":"If a passage mentions tour labels but not hotel prices, it is impossible to say what the writer thinks about prices.","zh":"如果篇章提到旅行標籤但沒有提到酒店價格，就無法判斷作者對價格的看法。"},{"en":"In reading tests, impossible to say usually leads to NOT GIVEN.","zh":"在閱讀測驗中，無法判斷通常導向 NOT GIVEN。"},{"en":"The phrase warns students not to guess beyond the text.","zh":"這個短語提醒學生不要超出文本猜測。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":18},{"front":"advertising gimmick","meaning":"廣告噱頭","examples":[{"en":"The question asks whether ecotourism has become an advertising gimmick.","zh":"題目問生態旅遊是否已變成廣告噱頭。"},{"en":"An advertising gimmick is a trick or catchy idea used mainly to attract customers.","zh":"advertising gimmick 指主要用來吸引顧客的技巧或吸睛想法。"},{"en":"A product may use a green leaf picture as an advertising gimmick without being environmentally friendly.","zh":"產品可能使用綠葉圖片作為廣告噱頭，但本身並不環保。"},{"en":"If ecotourism is only a gimmick, the label sells holidays but does not protect nature.","zh":"如果生態旅遊只是噱頭，標籤就只是在銷售假期，而沒有保護自然。"},{"en":"The phrase is critical and suggests shallow marketing.","zh":"這個短語帶批評意味，暗示膚淺市場推廣。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":18},{"front":"coin the term","meaning":"創造這個詞","examples":[{"en":"The question refers to those who coined the term ecotourism.","zh":"題目提到創造 ecotourism 這個詞的人。"},{"en":"To coin a term means to create a new word or expression.","zh":"coin a term 指創造一個新詞或新表達。"},{"en":"A journalist may coin a term for a new social trend.","zh":"記者可能為一種新社會潮流創造新詞。"},{"en":"When a term is coined, it may later change meaning as more people use it.","zh":"當一個詞被創造，隨着更多人使用，它的意思可能後來改變。"},{"en":"The phrase focuses on the origin of language.","zh":"這個短語重點是語言來源。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":18},{"front":"sincere intentions","meaning":"真誠的意圖","examples":[{"en":"The question asks whether the original intentions were sincere.","zh":"題目問最初意圖是否真誠。"},{"en":"Sincere intentions are honest aims that are genuinely meant, not fake or manipulative.","zh":"sincere intentions 指真心而誠實的目標，不是假裝或操控。"},{"en":"A charity has sincere intentions if it truly wants to help people rather than only improve its image.","zh":"如果慈善機構真正想幫人，而不只是改善形象，它就有真誠意圖。"},{"en":"Sincere intentions can still lead to poor results if planning is weak.","zh":"真誠意圖如果缺乏良好規劃，仍可能導致差劣結果。"},{"en":"The phrase judges honesty of purpose.","zh":"這個短語判斷目的是否誠實。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":18},{"front":"faster rate than","meaning":"比……更快的速度","examples":[{"en":"The option asks whether ecotourism is growing at a faster rate than any other travel type.","zh":"選項問生態旅遊是否以比任何其他旅遊類型更快的速度增長。"},{"en":"Faster rate than means increasing more quickly than something else.","zh":"faster rate than 指比另一事物增長更快。"},{"en":"Online shopping grew at a faster rate than traditional shopping in many places.","zh":"在許多地方，網上購物以比傳統購物更快的速度增長。"},{"en":"If one travel type grows faster than others, more companies may enter that market.","zh":"如果一種旅遊類型比其他類型增長更快，更多公司可能進入該市場。"},{"en":"The phrase compares speed of growth.","zh":"這個短語比較增長速度。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":18},{"front":"type of travel","meaning":"旅遊類型","examples":[{"en":"Ecotourism is one type of travel.","zh":"生態旅遊是一種旅遊類型。"},{"en":"A type of travel is a category of journey based on purpose, style, or destination.","zh":"type of travel 指根據目的、風格或目的地劃分的旅程類別。"},{"en":"Business travel, family travel, adventure travel, and eco-travel are different types of travel.","zh":"商務旅遊、家庭旅遊、探險旅遊和生態旅遊都是不同旅遊類型。"},{"en":"Different travel types create different impacts on places and people.","zh":"不同旅遊類型對地方和人造成不同影響。"},{"en":"The phrase helps classify travel experiences.","zh":"這個短語幫助分類旅遊體驗。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":18},{"front":"be involved in","meaning":"參與","examples":[{"en":"Many tour organisations decided to become involved in ecotourism.","zh":"許多旅遊組織決定參與生態旅遊。"},{"en":"To be involved in something means to take part in it or have a role in it.","zh":"be involved in something 指參與某事或在其中有角色。"},{"en":"Students involved in a charity project may help plan events and collect donations.","zh":"參與慈善項目的學生可能幫忙策劃活動和籌款。"},{"en":"Companies become involved in growing markets when they see customer demand.","zh":"當公司看見顧客需求，它們會參與增長中的市場。"},{"en":"The phrase describes participation or connection.","zh":"這個短語描述參與或關連。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":18},{"front":"make investigations about","meaning":"調查關於……","examples":[{"en":"Tourists may need to make investigations about tour operators.","zh":"遊客可能需要調查旅遊營辦商。"},{"en":"To make investigations about something means to check information carefully before deciding.","zh":"make investigations about something 指在決定前仔細查核資訊。"},{"en":"Parents may make investigations about a summer camp before sending children there.","zh":"家長可能在送孩子去夏令營前調查該營地。"},{"en":"Investigating operators helps tourists avoid false claims and unsafe practices.","zh":"調查營辦商幫助遊客避開虛假聲稱和不安全做法。"},{"en":"The phrase suggests active checking rather than passive trust.","zh":"這個短語暗示主動查核，而不是被動相信。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":18},{"front":"before using them","meaning":"在使用它們之前","examples":[{"en":"Tourists should check operators before using them.","zh":"遊客應在使用營辦商服務之前查核它們。"},{"en":"Before using them means before buying their services or relying on them.","zh":"before using them 指在購買其服務或依靠它們之前。"},{"en":"Students should check sources before using them in an essay.","zh":"學生應在作文中使用資料來源之前先查核它們。"},{"en":"Checking operators before using them can prevent disappointment and support better businesses.","zh":"在使用營辦商之前查核，可以避免失望並支持更好的企業。"},{"en":"The phrase stresses action before commitment.","zh":"這個短語強調承諾前先行動。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":18},{"front":"have bad experiences","meaning":"有不愉快經歷","examples":[{"en":"The question asks whether tourists have had bad experiences on ecotour holidays.","zh":"題目問遊客是否曾在生態旅遊假期中有不愉快經歷。"},{"en":"To have bad experiences means to go through unpleasant, disappointing, or harmful events.","zh":"have bad experiences 指經歷不愉快、令人失望或有害的事件。"},{"en":"Travellers may have bad experiences if a tour is unsafe or dishonest.","zh":"如果旅行團不安全或不誠實，旅客可能有不愉快經歷。"},{"en":"Bad experiences can make people lose trust in an entire travel label.","zh":"不愉快經歷可以令人失去對整個旅遊標籤的信任。"},{"en":"The phrase focuses on what tourists actually go through.","zh":"這個短語重點是遊客實際經歷了甚麼。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":18},{"front":"according to the information given","meaning":"根據所提供資料","examples":[{"en":"Students choose answers according to the information given in the passage.","zh":"學生根據篇章所提供資料選擇答案。"},{"en":"According to the information given means based only on what the text provides.","zh":"according to the information given 指只根據文本提供的內容。"},{"en":"In reading tests, students should answer according to the passage, not their outside knowledge.","zh":"在閱讀測驗中，學生應根據篇章作答，而不是根據外部知識。"},{"en":"If information is not given, students should not invent an answer.","zh":"如果沒有提供資料，學生不應自創答案。"},{"en":"The phrase sets the evidence source for answering.","zh":"這個短語設定作答的證據來源。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":19},{"front":"which three of the following","meaning":"以下哪三項","examples":[{"en":"The question asks which three of the following statements are true.","zh":"題目問以下哪三項陳述屬實。"},{"en":"Which three of the following means students must choose three options from the list.","zh":"which three of the following 指學生必須從列表中選出三個選項。"},{"en":"If the question asks for three answers, choosing only two is incomplete.","zh":"如果題目要求三個答案，只選兩個就是不完整。"},{"en":"Students should check each option against the passage before selecting three.","zh":"學生在選三個答案前應把每個選項與篇章核對。"},{"en":"The phrase is an exam instruction about number of answers.","zh":"這個短語是關於答案數量的考試指示。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":19},{"front":"be true of","meaning":"對……而言屬實","examples":[{"en":"Students decide which statements are true of the Ecotourism Society.","zh":"學生判斷哪些陳述對生態旅遊協會而言屬實。"},{"en":"To be true of something means to correctly describe it.","zh":"be true of something 指正確描述某事。"},{"en":"It is true of many schools that exam periods are stressful.","zh":"對許多學校而言，考試期充滿壓力是屬實的。"},{"en":"A statement is true of an organisation only if the passage supports it clearly.","zh":"只有當篇章清楚支持某陳述，它才對某組織而言屬實。"},{"en":"The phrase links a description with the subject it describes.","zh":"這個短語把描述與其描述對象連起來。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":19},{"front":"monitor the growth in","meaning":"監察……的增長","examples":[{"en":"The option asks whether the society has monitored the growth in ecotourism.","zh":"選項問該協會是否監察生態旅遊的增長。"},{"en":"To monitor the growth in something means to watch and measure how it increases over time.","zh":"monitor the growth in something 指觀察並量度某事如何隨時間增加。"},{"en":"A school may monitor the growth in student numbers before hiring more teachers.","zh":"學校可能在聘請更多老師前監察學生人數增長。"},{"en":"Monitoring market growth helps organisations plan campaigns and standards.","zh":"監察市場增長幫助組織規劃宣傳活動和標準。"},{"en":"The phrase focuses on tracking change.","zh":"這個短語重點是追蹤變化。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":19},{"front":"involve a range of specialists","meaning":"涉及一系列專家","examples":[{"en":"The society involves a range of specialists in the field.","zh":"該協會涉及該領域的一系列專家。"},{"en":"To involve a range of specialists means to include different experts with relevant knowledge.","zh":"involve a range of specialists 指包括具有相關知識的不同專家。"},{"en":"A hospital project may involve specialists in medicine, design, and technology.","zh":"醫院項目可能涉及醫學、設計和科技方面的專家。"},{"en":"Ecotourism needs different specialists because it affects business, nature, and communities.","zh":"生態旅遊需要不同專家，因為它影響商業、自然和社區。"},{"en":"The phrase stresses diverse expertise.","zh":"這個短語強調多元專業知識。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":19},{"front":"in the field","meaning":"在該領域","examples":[{"en":"The society includes specialists in the field of ecotourism.","zh":"該協會包括生態旅遊領域的專家。"},{"en":"In the field means in a particular area of work, study, or professional practice.","zh":"in the field 指在某個工作、研究或專業實踐範疇中。"},{"en":"A doctor in the field of public health studies disease prevention.","zh":"公共衛生領域的醫生研究疾病預防。"},{"en":"Specialists in the field can judge problems more accurately than casual observers.","zh":"該領域的專家比普通觀察者更能準確判斷問題。"},{"en":"The phrase identifies the area of expertise.","zh":"這個短語指出專業範疇。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":19},{"front":"receive public recognition","meaning":"獲得公眾認可","examples":[{"en":"The option asks whether the society has received public recognition.","zh":"選項問該協會是否獲得公眾認可。"},{"en":"To receive public recognition means to be noticed, respected, or acknowledged by the public.","zh":"receive public recognition 指被公眾注意、尊重或承認。"},{"en":"A charity receives public recognition when people know and trust its work.","zh":"當人們知道並信任慈善機構的工作，它就獲得公眾認可。"},{"en":"Public recognition can help an organisation attract support and influence behaviour.","zh":"公眾認可可以幫助組織吸引支持並影響行為。"},{"en":"The phrase focuses on visible approval from society.","zh":"這個短語重點是來自社會的可見認同。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":19},{"front":"role it performs","meaning":"它所發揮的作用","examples":[{"en":"The option refers to the role the society performs.","zh":"選項提到該協會所發揮的作用。"},{"en":"The role it performs means the function or job it carries out.","zh":"role it performs 指它執行的功能或工作。"},{"en":"A library’s role is not only lending books but also supporting learning.","zh":"圖書館的作用不只是借書，也包括支持學習。"},{"en":"The Ecotourism Society performs a role when it educates travellers and lists approved operators.","zh":"生態旅遊協會教育旅客並列出認可營辦商時，就是發揮作用。"},{"en":"The phrase asks what an organisation actually does.","zh":"這個短語詢問組織實際做甚麼。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":19},{"front":"set up regular promotions","meaning":"設立定期推廣活動","examples":[{"en":"The option asks whether the society sets up regular promotions.","zh":"選項問該協會是否設立定期推廣活動。"},{"en":"To set up regular promotions means to organise repeated marketing or publicity activities.","zh":"set up regular promotions 指組織重複進行的市場推廣或宣傳活動。"},{"en":"A shop may set up regular promotions every weekend to attract customers.","zh":"商店可能每個週末設立定期推廣活動來吸引顧客。"},{"en":"Promotions can raise awareness, but they are different from inspections or standards.","zh":"推廣活動可以提高意識，但它們不同於檢查或標準。"},{"en":"The phrase focuses on repeated publicity efforts.","zh":"這個短語重點是重複宣傳工作。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":19},{"front":"offer information on","meaning":"提供關於……的資料","examples":[{"en":"The society offers information on ecotours internationally.","zh":"該協會提供關於國際生態旅遊的資料。"},{"en":"To offer information on something means to provide facts, advice, or explanations about it.","zh":"offer information on something 指提供關於某事的事實、建議或解釋。"},{"en":"A school website may offer information on courses, fees, and schedules.","zh":"學校網站可能提供關於課程、費用和時間表的資料。"},{"en":"Information on ecotours helps travellers compare choices before booking.","zh":"關於生態旅遊的資料幫助旅客在預訂前比較選擇。"},{"en":"The phrase focuses on giving useful knowledge.","zh":"這個短語重點是提供有用知識。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":19},{"front":"at an international level","meaning":"在國際層面","examples":[{"en":"The society offers guidance at an international level.","zh":"該協會在國際層面提供指引。"},{"en":"At an international level means across countries or involving more than one nation.","zh":"at an international level 指跨國或涉及多於一個國家。"},{"en":"Climate agreements must work at an international level because pollution crosses borders.","zh":"氣候協議必須在國際層面運作，因為污染會跨越邊界。"},{"en":"Guidance at an international level helps travellers compare operators in different countries.","zh":"國際層面的指引幫助旅客比較不同國家的營辦商。"},{"en":"The phrase contrasts global action with local action only.","zh":"這個短語把全球行動與單純本地行動作對比。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":19},{"front":"consult with","meaning":"諮詢；與……商議","examples":[{"en":"The option asks whether the society consults with people in tourist destinations.","zh":"選項問該協會是否與旅遊目的地的人商議。"},{"en":"To consult with someone means to discuss with them and ask for their views before deciding.","zh":"consult with someone 指在決定前與某人討論並詢問其看法。"},{"en":"A school should consult with parents before making major timetable changes.","zh":"學校在作出重大時間表改動前應諮詢家長。"},{"en":"Ecotourism groups should consult with local residents because they live with tourism’s effects.","zh":"生態旅遊團體應諮詢本地居民，因為他們承受旅遊影響。"},{"en":"The phrase suggests respectful discussion, not simply informing people afterward.","zh":"這個短語暗示尊重地討論，而不是事後單純通知。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":20},{"front":"tourist destinations","meaning":"旅遊目的地","examples":[{"en":"People working in tourist destinations may affect ecotourism.","zh":"在旅遊目的地工作的人可能影響生態旅遊。"},{"en":"Tourist destinations are places that visitors travel to for holidays, culture, nature, or activities.","zh":"tourist destinations 指遊客為假期、文化、自然或活動而前往的地方。"},{"en":"Beaches, historic cities, national parks, and villages can be tourist destinations.","zh":"海灘、歷史城市、國家公園和村莊都可以是旅遊目的地。"},{"en":"If destinations are poorly managed, tourism can damage local life and environments.","zh":"如果目的地管理不善，旅遊可以破壞本地生活和環境。"},{"en":"The phrase refers to places tourists go, not the tourists themselves.","zh":"這個短語指遊客前往的地方，而不是遊客本身。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":20},{"front":"which two of the following","meaning":"以下哪兩項","examples":[{"en":"The question asks which two of the following statements are true.","zh":"題目問以下哪兩項陳述屬實。"},{"en":"Which two of the following means students must choose exactly two options from a list.","zh":"which two of the following 指學生必須從列表中準確選出兩個選項。"},{"en":"If a reading question asks for two letters, writing three can lose marks.","zh":"如果閱讀題要求兩個字母，寫三個可能失分。"},{"en":"Students should eliminate unsupported options before choosing the two true ones.","zh":"學生應先排除沒有支持的選項，再選出兩項正確答案。"},{"en":"The phrase is an exam instruction about answer number.","zh":"這個短語是關於答案數量的考試指示。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":20},{"front":"self-regulating","meaning":"自我規管的","examples":[{"en":"The option asks whether the scheme is self-regulating.","zh":"選項問該計劃是否自我規管。"},{"en":"Self-regulating means controlled by its own members rather than by an outside authority.","zh":"self-regulating 指由自身成員控制，而不是由外部權威控制。"},{"en":"A professional association may be self-regulating if it writes and enforces its own rules.","zh":"如果專業協會自行制定並執行規則，它可能是自我規管的。"},{"en":"Self-regulation can work only if members are checked honestly.","zh":"自我規管只有在成員受到誠實查核時才有效。"},{"en":"The phrase raises the question of who monitors the system.","zh":"這個短語提出誰監察制度的問題。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":20},{"front":"be recruited to","meaning":"被招聘去……","examples":[{"en":"The option asks whether Amanda Marks was recruited to develop the award.","zh":"選項問 Amanda Marks 是否被招聘去發展該獎項。"},{"en":"To be recruited to do something means to be hired or invited to take on that task.","zh":"be recruited to do something 指被聘請或邀請承擔某任務。"},{"en":"A teacher may be recruited to design a new speaking course.","zh":"老師可能被招聘去設計新口語課程。"},{"en":"If an expert is recruited to develop an award, the organisers want specialist knowledge.","zh":"如果專家被招聘去發展獎項，主辦者就是想要專門知識。"},{"en":"The phrase focuses on being brought in for a role.","zh":"這個短語重點是被引入擔任某角色。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":20},{"front":"develop the award","meaning":"發展該獎項","examples":[{"en":"The option discusses developing the Green Globe 21 award.","zh":"選項討論發展 Green Globe 21 獎項。"},{"en":"To develop the award means to design, improve, or organise how the award works.","zh":"develop the award 指設計、改善或組織該獎項如何運作。"},{"en":"A committee may develop an award by setting criteria and judging methods.","zh":"委員會可以透過設定準則和評審方法來發展獎項。"},{"en":"Developing an award well requires clear standards and fair checks.","zh":"良好發展獎項需要清晰標準和公平查核。"},{"en":"The phrase focuses on building the system behind recognition.","zh":"這個短語重點是建立認可背後的制度。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":20},{"front":"prior to","meaning":"在……之前","examples":[{"en":"Prior to 1999, companies could use the logo after paying a fee.","zh":"在1999年之前，公司支付費用後便可使用標誌。"},{"en":"Prior to means before a particular time or event.","zh":"prior to 指在某特定時間或事件之前。"},{"en":"Students should revise key vocabulary prior to the exam.","zh":"學生應在考試之前溫習重點詞彙。"},{"en":"Prior to stricter checks, companies might use a logo without proving strong standards.","zh":"在更嚴格查核之前，公司可能不用證明高標準也能使用標誌。"},{"en":"The phrase is more formal than before.","zh":"這個短語比 before 更正式。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":20},{"front":"be required to pay for","meaning":"被要求支付……","examples":[{"en":"The option asks whether companies were required to pay for membership.","zh":"選項問公司是否被要求支付會員費。"},{"en":"To be required to pay for something means to be officially expected or forced to pay for it.","zh":"be required to pay for something 指被正式要求或必須為某事付款。"},{"en":"Students may be required to pay for replacement library books if they lose them.","zh":"如果學生遺失圖書館書籍，可能被要求支付補領費。"},{"en":"If companies are required to pay for membership, payment is part of joining the scheme.","zh":"如果公司被要求支付會員費，付款就是加入計劃的一部分。"},{"en":"The phrase focuses on an obligation to pay.","zh":"這個短語重點是付款義務。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":20},{"front":"tour sites","meaning":"旅遊地點","examples":[{"en":"Tour sites can apply for Green Globe 21 approval.","zh":"旅遊地點可以申請 Green Globe 21 認可。"},{"en":"Tour sites are places where tourists visit, stay, or take part in activities.","zh":"tour sites 指遊客到訪、停留或參與活動的地方。"},{"en":"A rainforest lodge, village trail, or cultural centre can be a tour site.","zh":"雨林旅館、村莊步道或文化中心都可以是旅遊地點。"},{"en":"If tour sites meet sustainability standards, they may receive approval.","zh":"如果旅遊地點符合可持續標準，它們可能獲得認可。"},{"en":"The phrase refers to physical destinations or facilities.","zh":"這個短語指實體目的地或設施。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":20},{"front":"apply for affiliation","meaning":"申請附屬資格","examples":[{"en":"Tour operators and communities can apply for affiliation.","zh":"旅遊營辦商和社區可以申請附屬資格。"},{"en":"To apply for affiliation means to request formal membership or connection with a scheme.","zh":"apply for affiliation 指申請與某計劃建立正式會員或連繫關係。"},{"en":"A small school may apply for affiliation with an examination board.","zh":"小型學校可能申請成為考試機構的附屬成員。"},{"en":"Applicants may need to prove they meet standards before affiliation is granted.","zh":"申請者在獲得附屬資格前可能需要證明符合標準。"},{"en":"The phrase describes applying to join an official network.","zh":"這個短語描述申請加入正式網絡。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":20},{"front":"intend to reduce","meaning":"打算減少","examples":[{"en":"The option asks whether the award intends to reduce the number of operators.","zh":"選項問該獎項是否打算減少營辦商數量。"},{"en":"To intend to reduce something means to plan or aim to make it smaller.","zh":"intend to reduce something 指計劃或旨在令某事減少。"},{"en":"A school may intend to reduce homework if students are too stressed.","zh":"如果學生壓力太大，學校可能打算減少功課。"},{"en":"An accreditation scheme may aim to improve standards rather than reduce the number of companies.","zh":"認證計劃可能旨在提升標準，而不是減少公司數量。"},{"en":"The phrase focuses on planned purpose.","zh":"這個短語重點是計劃目的。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":20},{"front":"number of ecotour operators","meaning":"生態旅遊營辦商數量","examples":[{"en":"The option concerns the number of ecotour operators.","zh":"選項關於生態旅遊營辦商數量。"},{"en":"Number of ecotour operators means how many companies or groups provide ecotourism trips.","zh":"number of ecotour operators 指提供生態旅遊旅程的公司或團體有多少。"},{"en":"If the number of operators increases quickly, travellers may find it harder to judge quality.","zh":"如果營辦商數量迅速增加，旅客可能更難判斷質素。"},{"en":"A large number of operators can create competition but also confusion.","zh":"大量營辦商可以創造競爭，但也可能造成混亂。"},{"en":"The phrase focuses on quantity in the industry.","zh":"這個短語重點是業界數量。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":21},{"front":"using no more than three words","meaning":"使用不超過三個詞","examples":[{"en":"Candidates answer using no more than three words.","zh":"考生使用不超過三個詞作答。"},{"en":"Using no more than three words means writing one, two, or three words only.","zh":"using no more than three words 指只寫一個、兩個或三個詞。"},{"en":"If the answer is four words long, it breaks the instruction even if the meaning is right.","zh":"如果答案有四個詞，即使意思正確，也違反指示。"},{"en":"Students should count words carefully in completion questions.","zh":"學生在填充題中應仔細數詞數。"},{"en":"The phrase gives a strict word-limit rule.","zh":"這個短語提供嚴格字數限制規則。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":21},{"front":"answer the following questions","meaning":"回答以下問題","examples":[{"en":"Students answer the following questions using words from the passage.","zh":"學生使用文章中的字詞回答以下問題。"},{"en":"To answer the following questions means to respond to the questions that come next.","zh":"answer the following questions 指回答接下來的問題。"},{"en":"In a reading test, students should answer the following questions by locating evidence in the text.","zh":"在閱讀測驗中，學生應透過在文本中定位證據來回答以下問題。"},{"en":"If the instruction says to use words from the passage, students should not paraphrase freely.","zh":"如果指示說使用文章中的字詞，學生不應隨意改寫。"},{"en":"The phrase is an exam instruction.","zh":"這個短語是考試指示。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":21},{"front":"global tourist numbers","meaning":"全球旅客人數","examples":[{"en":"The question asks which body provides information on global tourist numbers.","zh":"題目問哪個機構提供全球旅客人數資料。"},{"en":"Global tourist numbers are statistics showing how many people travel internationally or worldwide.","zh":"global tourist numbers 指顯示有多少人作國際或全球旅遊的統計數字。"},{"en":"Tourism organisations use global tourist numbers to understand market size and growth.","zh":"旅遊組織使用全球旅客人數來理解市場規模和增長。"},{"en":"If global tourist numbers rise, destinations may need better planning and environmental controls.","zh":"如果全球旅客人數上升，目的地可能需要更好規劃和環境管制。"},{"en":"The phrase refers to worldwide travel statistics.","zh":"這個短語指全球旅遊統計。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":21},{"front":"gain financially from","meaning":"從……中獲得經濟利益","examples":[{"en":"The question asks who often gains financially from tourism.","zh":"題目問誰經常從旅遊中獲得經濟利益。"},{"en":"To gain financially from something means to receive money or economic benefit from it.","zh":"gain financially from something 指從某事得到金錢或經濟好處。"},{"en":"Local shops gain financially from a festival when visitors buy food and gifts.","zh":"當遊客購買食物和禮物，本地商店就從節日中獲得經濟利益。"},{"en":"If city entrepreneurs gain financially while rural communities do not, tourism benefits are uneven.","zh":"如果城市企業家獲利而鄉郊社區沒有，旅遊好處就不平均。"},{"en":"The phrase focuses on money gained from an activity.","zh":"這個短語重點是從某活動中得到金錢。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":21},{"front":"rural environments","meaning":"鄉郊環境","examples":[{"en":"Tourism in rural environments may benefit city entrepreneurs.","zh":"鄉郊環境中的旅遊可能令城市企業家受益。"},{"en":"Rural environments are countryside areas with villages, farms, forests, or small settlements.","zh":"rural environments 指包含村莊、農場、森林或小型聚落的鄉郊地區。"},{"en":"A mountain village and farming valley are rural environments.","zh":"山村和農業山谷都是鄉郊環境。"},{"en":"Tourism in rural environments can create income, but it can also put pressure on water and land.","zh":"鄉郊環境中的旅遊可以創造收入，但也可能對水和土地造成壓力。"},{"en":"The phrase contrasts countryside settings with urban environments.","zh":"這個短語把鄉村環境與城市環境作對比。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":21},{"front":"provide the principles behind","meaning":"提供……背後的原則","examples":[{"en":"The question asks which meeting provided the principles behind the regulations.","zh":"題目問哪場會議提供規例背後的原則。"},{"en":"To provide the principles behind something means to supply the basic ideas that support it.","zh":"provide the principles behind something 指提供支撐某事的基本理念。"},{"en":"A school mission statement may provide the principles behind its discipline policy.","zh":"學校使命宣言可能提供紀律政策背後的原則。"},{"en":"If a summit provides principles for a scheme, the scheme is built on those ideas.","zh":"如果高峰會為某計劃提供原則，該計劃就是建立在那些理念之上。"},{"en":"The phrase connects rules with their guiding foundation.","zh":"這個短語把規則與其指導基礎連起來。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":21},{"front":"regulations","meaning":"規例","examples":[{"en":"Green Globe 21 regulations are linked to Agenda 21 standards.","zh":"Green Globe 21 規例與《21世紀議程》標準有關。"},{"en":"Regulations are official rules that control how people or organisations should act.","zh":"regulations 指控制人或組織應如何行事的官方規則。"},{"en":"Food safety regulations tell restaurants how to store and prepare food safely.","zh":"食物安全規例告訴餐廳如何安全儲存和準備食物。"},{"en":"Clear regulations can stop weak companies from making false environmental claims.","zh":"清晰規例可以阻止薄弱公司作出虛假環保聲稱。"},{"en":"The word is formal and often connected with law or standards.","zh":"這個詞較正式，常與法律或標準有關。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":21},{"front":"principles behind the regulations","meaning":"規例背後的原則","examples":[{"en":"The Earth Summit provided the principles behind the regulations.","zh":"地球高峰會提供了規例背後的原則。"},{"en":"Principles behind the regulations are the basic ideas or values that explain why the rules exist.","zh":"principles behind the regulations 指解釋規則為何存在的基本理念或價值。"},{"en":"Fairness and safety may be the principles behind school exam rules.","zh":"公平和安全可能是學校考試規則背後的原則。"},{"en":"If sustainability is the principle behind tourism regulations, operators must consider environment and communities.","zh":"如果可持續性是旅遊規例背後的原則，營辦商就必須考慮環境和社區。"},{"en":"The phrase looks beyond the rule itself to its reason.","zh":"這個短語不只看規則本身，也看其原因。"}],"source":"102 - IT’S ECO-LOGICAL.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 103":[{"front":"fun for the masses","meaning":"大眾娛樂","examples":[{"en":"The passage examines whether leisure has become fun for the masses.","zh":"篇章探討休閒是否已成為大眾娛樂。"},{"en":"Fun for the masses means entertainment that ordinary people, not only the rich, can enjoy.","zh":"大眾娛樂是指普通人也能享受的娛樂，而不只是富人的享受。"},{"en":"Cheap cinema tickets can turn films into fun for the masses.","zh":"便宜戲票可以令電影成為大眾娛樂。"},{"en":"When technology lowers prices, music and games become fun for the masses.","zh":"當科技降低價格，音樂和遊戲就會成為大眾娛樂。"},{"en":"This phrase contrasts public enjoyment with luxuries reserved for a small elite.","zh":"這個短語把大眾享樂與少數精英專享的奢侈品作對比。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":1},{"front":"the distribution of income","meaning":"收入分布","examples":[{"en":"Americans worry that the distribution of income is increasingly unequal.","zh":"美國人擔心收入分布越來越不平等。"},{"en":"The distribution of income means how money earned in a society is spread among people.","zh":"收入分布是指一個社會中賺得的金錢如何在不同人之間分配。"},{"en":"A country may have high income overall but an unfair distribution of income.","zh":"一個國家整體收入可能很高，但收入分布不公平。"},{"en":"If most gains go to the richest families, the distribution of income becomes unequal.","zh":"如果大部分收益流向最富有家庭，收入分布就會變得不平等。"},{"en":"This phrase focuses on who receives money, not just how much a country earns.","zh":"這個短語聚焦誰得到金錢，而不只是國家賺了多少。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":1},{"front":"increasingly unequal","meaning":"越來越不平等","examples":[{"en":"The distribution of income is increasingly unequal.","zh":"收入分布越來越不平等。"},{"en":"Increasingly unequal means becoming less fair or less evenly shared over time.","zh":"越來越不平等，是指隨時間變得較不公平或較不平均。"},{"en":"Housing opportunities may become increasingly unequal if only rich families can buy homes.","zh":"如果只有富裕家庭能買樓，住屋機會可能變得越來越不平等。"},{"en":"When wages rise mainly for top earners, society becomes increasingly unequal.","zh":"當工資主要為高收入者上升，社會就會越來越不平等。"},{"en":"This phrase shows a worsening pattern, not just one unfair moment.","zh":"這個短語顯示惡化中的模式，而不只是一次不公平情況。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":1},{"front":"leisure spending","meaning":"休閒開支","examples":[{"en":"Examining leisure spending changes the picture of inequality.","zh":"考察休閒開支會改變不平等的圖像。"},{"en":"Leisure spending means money spent on entertainment, recreation, hobbies, and free-time activities.","zh":"休閒開支是花在娛樂、消閒、興趣和空閒活動上的金錢。"},{"en":"A family’s leisure spending may include cinema tickets, sports fees, books, or music.","zh":"家庭休閒開支可能包括戲票、運動費、書籍或音樂。"},{"en":"If poorer families can afford more leisure, measured living standards may look less unequal.","zh":"如果較貧窮家庭能負擔更多休閒，所量度的生活水平不平等可能看起來較小。"},{"en":"This phrase looks beyond income to how people actually enjoy life.","zh":"這個短語超越收入，關注人們實際如何享受生活。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":1},{"front":"change that picture","meaning":"改變那種看法","examples":[{"en":"Leisure spending changes that picture of American inequality.","zh":"休閒開支改變了對美國不平等的那種看法。"},{"en":"To change that picture means to alter how a situation appears or is understood.","zh":"改變那種看法，是指改變某情況看起來或被理解的方式。"},{"en":"A school’s exam results may look weak, but student progress can change that picture.","zh":"學校考試成績可能看似薄弱，但學生進步可以改變那種看法。"},{"en":"When new evidence is considered, it can change the picture of a social problem.","zh":"當新證據被考慮在內，它可以改變人們對社會問題的看法。"},{"en":"This phrase shows that one extra factor can revise the overall interpretation.","zh":"這個短語顯示一個額外因素可以修正整體理解。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":1},{"front":"be better off than","meaning":"比……生活得更好","examples":[{"en":"Americans wonder whether they are better off than they used to be.","zh":"美國人想知道自己是否比以前生活得更好。"},{"en":"To be better off than before means to have a better life, usually with more money, comfort, or opportunity.","zh":"比以前生活得更好，是指生活更好，通常有更多金錢、舒適或機會。"},{"en":"A worker is better off than last year if wages rise and rent stays stable.","zh":"如果工人工資上升而租金穩定，他就比去年生活得更好。"},{"en":"People may earn more but not feel better off if costs rise even faster.","zh":"如果成本升得更快，人們即使賺更多也未必覺得生活更好。"},{"en":"This phrase compares present well-being with an earlier situation.","zh":"這個短語把現在的福祉與早前情況比較。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":1},{"front":"used to be","meaning":"以往；從前","examples":[{"en":"Some people ask whether Americans are better off than they used to be.","zh":"有些人問美國人是否比以往生活得更好。"},{"en":"Used to be means the way something was in the past but may not be now.","zh":"以往是指某事過去的狀態，但現在可能不同。"},{"en":"This street used to be quiet, but now it is full of cafés and traffic.","zh":"這條街從前很安靜，但現在滿是咖啡店和交通。"},{"en":"Comparisons with what life used to be help people judge change over time.","zh":"與以往生活比較，有助人們判斷隨時間出現的改變。"},{"en":"This phrase points to a past condition.","zh":"這個短語指向過去的狀態。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":1},{"front":"sustained economic growth","meaning":"持續經濟增長","examples":[{"en":"Americans still worry after six years of sustained economic growth.","zh":"在六年持續經濟增長後，美國人仍然擔心。"},{"en":"Sustained economic growth means the economy keeps expanding over a period of time.","zh":"持續經濟增長是指經濟在一段時間內持續擴張。"},{"en":"A city may enjoy sustained economic growth if jobs, trade, and investment keep rising.","zh":"如果就業、貿易和投資持續上升，城市可能享有持續經濟增長。"},{"en":"Even with sustained growth, some families may not feel richer if benefits are uneven.","zh":"即使有持續增長，如果好處分配不均，有些家庭仍未必覺得更富裕。"},{"en":"This phrase describes continued growth, not a short boom.","zh":"這個短語描述持續增長，而不是短暫繁榮。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":1},{"front":"plumb government income statistics","meaning":"深入研究政府收入統計數據","examples":[{"en":"Economists plumb government income statistics to study living standards.","zh":"經濟學家深入研究政府收入統計數據，以研究生活水平。"},{"en":"To plumb statistics means to examine them deeply and carefully for meaning.","zh":"深入研究統計數據，是指仔細而深入檢查數據以找出意義。"},{"en":"A researcher may plumb school attendance data to understand why students miss lessons.","zh":"研究人員可能深入研究學校出席數據，以了解學生缺課原因。"},{"en":"Economists plumb income figures because surface averages may hide important differences.","zh":"經濟學家深入研究收入數字，因為表面平均值可能隱藏重要差異。"},{"en":"This phrase suggests detailed investigation, not a quick glance.","zh":"這個短語暗示詳細調查，而不是快速瀏覽。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":1},{"front":"income statistics","meaning":"收入統計數據","examples":[{"en":"Economists use income statistics to measure changes in earnings.","zh":"經濟學家使用收入統計數據來衡量收入變化。"},{"en":"Income statistics are numerical data about how much people or households earn.","zh":"收入統計數據是關於個人或家庭賺多少錢的數字資料。"},{"en":"Governments collect income statistics to study wages, poverty, and inequality.","zh":"政府收集收入統計數據，以研究工資、貧窮和不平等。"},{"en":"Income statistics can show trends, but they may not show how enjoyable life is.","zh":"收入統計可以顯示趨勢，但未必顯示生活有多愉快。"},{"en":"This phrase refers to measured income data.","zh":"這個短語指被量度的收入資料。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":1},{"front":"as measured in","meaning":"以……衡量","examples":[{"en":"Americans’ incomes, as measured in inflation-adjusted dollars, have risen slowly.","zh":"美國人的收入，以經通脹調整後的美元衡量，增長緩慢。"},{"en":"As measured in means using a particular unit or method of measurement.","zh":"以某物衡量，是指使用某個單位或測量方法。"},{"en":"A child’s growth, as measured in height, may slow during some years.","zh":"孩子的成長如果以身高衡量，在某些年份可能放慢。"},{"en":"The result can look different depending on how it is measured.","zh":"結果會因衡量方法不同而看起來不同。"},{"en":"This phrase tells readers what standard is being used.","zh":"這個短語告訴讀者正在使用甚麼標準。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":1},{"front":"inflation-adjusted dollars","meaning":"經通脹調整後的美元","examples":[{"en":"Inflation-adjusted dollars show whether incomes have really risen.","zh":"經通脹調整後的美元顯示收入是否真正上升。"},{"en":"Inflation-adjusted dollars are money amounts corrected for changes in prices over time.","zh":"經通脹調整後的美元，是已因物價隨時間變化而修正的金額。"},{"en":"A salary may look higher today, but inflation-adjusted dollars show whether buying power improved.","zh":"今天薪金可能看起來較高，但經通脹調整後的美元能顯示購買力是否改善。"},{"en":"Without inflation adjustment, people may mistake price rises for real income growth.","zh":"沒有通脹調整，人們可能把物價上升誤以為實質收入增長。"},{"en":"This phrase helps compare money across different years fairly.","zh":"這個短語幫助公平比較不同年份的金錢。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":2},{"front":"in the past two decades","meaning":"在過去二十年間","examples":[{"en":"Incomes have risen more slowly in the past two decades.","zh":"在過去二十年間，收入增長較慢。"},{"en":"In the past two decades means during the last twenty years.","zh":"在過去二十年間，是指在最近二十年期間。"},{"en":"In the past two decades, many schools have added online learning tools.","zh":"在過去二十年間，許多學校加入了網上學習工具。"},{"en":"A two-decade view helps show long-term change rather than one-year variation.","zh":"二十年視角有助顯示長期改變，而不是一年變動。"},{"en":"This phrase gives a twenty-year time frame.","zh":"這個短語給出二十年的時間範圍。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":2},{"front":"in earlier times","meaning":"在較早時期","examples":[{"en":"Income growth was faster in earlier times.","zh":"在較早時期，收入增長較快。"},{"en":"In earlier times means during a previous period in the past.","zh":"在較早時期，是指過去某個較早的時段。"},{"en":"In earlier times, families often repaired clothes instead of replacing them.","zh":"在較早時期，家庭常修補衣服，而不是更換。"},{"en":"This phrase compares the present with a less recent past.","zh":"這個短語把現在與較久以前作比較。"},{"en":"It is useful when describing historical change.","zh":"它適合用來描述歷史變化。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":2},{"front":"real incomes","meaning":"實質收入","examples":[{"en":"Some workers’ real incomes have actually fallen.","zh":"有些工人的實質收入其實已經下降。"},{"en":"Real incomes are earnings measured after considering inflation and buying power.","zh":"實質收入是考慮通脹和購買力後衡量的收入。"},{"en":"If prices rise faster than wages, real incomes fall.","zh":"如果物價升得比工資快，實質收入就會下降。"},{"en":"Workers may earn more dollars but have lower real incomes if rent and food become expensive.","zh":"如果租金和食物變貴，工人可能賺更多美元但實質收入較低。"},{"en":"This phrase shows what money can actually buy.","zh":"這個短語顯示金錢實際能買到甚麼。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":2},{"front":"by almost any measure","meaning":"幾乎以任何標準衡量","examples":[{"en":"By almost any measure, income is less equally distributed than before.","zh":"幾乎以任何標準衡量，收入分布都比以前更不平均。"},{"en":"By almost any measure means according to nearly every reasonable way of judging something.","zh":"幾乎以任何標準衡量，是指根據幾乎所有合理判斷方法。"},{"en":"By almost any measure, the new library is busier than the old one.","zh":"幾乎以任何標準衡量，新圖書館都比舊圖書館更繁忙。"},{"en":"This phrase strengthens a claim by saying many indicators point the same way.","zh":"這個短語透過說明許多指標方向一致來加強主張。"},{"en":"It does not mean literally every possible measure, but nearly all important ones.","zh":"它不是指字面上每一個可能標準，而是幾乎所有重要標準。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":2},{"front":"be distributed less equally","meaning":"分布得較不平均","examples":[{"en":"Income is distributed less equally than it used to be.","zh":"收入比以往分布得較不平均。"},{"en":"To be distributed less equally means to be shared in a more uneven way.","zh":"分布得較不平均，是指以更不均勻的方式分配。"},{"en":"If one group receives most school funding, resources are distributed less equally.","zh":"如果一個群體得到大部分學校資源，資源就分布得較不平均。"},{"en":"Unequal distribution can increase social tension because people feel excluded.","zh":"不平均分布會增加社會緊張，因為人們感到被排除。"},{"en":"This phrase describes unfair or uneven spread.","zh":"這個短語描述不公平或不均勻的分布。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":2},{"front":"neither of those claims","meaning":"兩種說法都不","examples":[{"en":"Neither of those claims fully explains changes in living standards.","zh":"兩種說法都不能完全解釋生活水平的變化。"},{"en":"Neither of those claims means both of the two statements are not accepted or not sufficient.","zh":"兩種說法都不，是指兩個陳述都不被接受或都不足夠。"},{"en":"If one person blames price and another blames quality, neither claim may explain why sales fell.","zh":"如果一人怪價格，另一人怪質素，兩種說法都未必能解釋銷售下降。"},{"en":"This phrase rejects two explanations together.","zh":"這個短語同時否定兩個解釋。"},{"en":"It helps writers move toward a third or more complete explanation.","zh":"它幫助作者轉向第三個或更完整的解釋。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":2},{"front":"shed much light on","meaning":"有助說明；闡明","examples":[{"en":"Income figures do not shed much light on whether living standards are rising.","zh":"收入數字對生活水平是否上升並沒有太大說明作用。"},{"en":"To shed light on something means to help explain or clarify it.","zh":"闡明某事，是指幫助解釋或釐清它。"},{"en":"Student interviews can shed light on why exam anxiety affects performance.","zh":"學生訪問可以說明考試焦慮為何影響表現。"},{"en":"If data does not shed much light, it gives only limited understanding.","zh":"如果數據沒有太大說明作用，它只能提供有限理解。"},{"en":"This phrase is used when evidence helps, or fails to help, explanation.","zh":"這個短語用於證據能否幫助解釋時。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":2},{"front":"living standards","meaning":"生活水平","examples":[{"en":"It is difficult to measure whether living standards are rising or falling.","zh":"衡量生活水平是上升還是下降並不容易。"},{"en":"Living standards refer to how comfortable, healthy, secure, and well supplied people’s lives are.","zh":"生活水平指人們生活有多舒適、健康、安全和資源充足。"},{"en":"Living standards improve when families have safe housing, enough food, healthcare, and leisure.","zh":"當家庭有安全住所、足夠食物、醫療和休閒時，生活水平會改善。"},{"en":"Income matters, but living standards also depend on time, prices, and public services.","zh":"收入重要，但生活水平也取決於時間、物價和公共服務。"},{"en":"This phrase measures quality of life, not only money.","zh":"這個短語衡量生活質素，而不只是金錢。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":2},{"front":"a highly amorphous concept","meaning":"非常難以界定的概念","examples":[{"en":"Living standard is a highly amorphous concept.","zh":"生活水平是一個非常難以界定的概念。"},{"en":"A highly amorphous concept is an idea that is hard to define clearly because it has many parts.","zh":"非常難以界定的概念，是指因包含很多部分而難以清楚定義的想法。"},{"en":"“Happiness” is amorphous because it includes health, relationships, money, and meaning.","zh":"「快樂」很難界定，因為它包括健康、人際關係、金錢和意義。"},{"en":"When a concept is amorphous, researchers must choose careful measures.","zh":"當概念難以界定，研究人員必須選擇仔細的量度方法。"},{"en":"This phrase describes an idea with unclear boundaries.","zh":"這個短語描述界線不清的概念。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":2},{"front":"relatively easy","meaning":"相對容易","examples":[{"en":"Measuring how much people earn is relatively easy.","zh":"衡量人們賺多少錢相對容易。"},{"en":"Relatively easy means easier compared with something else, not necessarily simple.","zh":"相對容易，是指與另一件事相比較容易，不一定完全簡單。"},{"en":"Counting class attendance is relatively easy compared with measuring motivation.","zh":"與衡量動機相比，計算班級出席率相對容易。"},{"en":"A task may be relatively easy because the data is clear and numerical.","zh":"一項任務可能因數據清楚且可量化而相對容易。"},{"en":"This phrase makes a comparison, even if the other task is only implied.","zh":"這個短語作出比較，即使另一項任務只是隱含。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":2},{"front":"compared with","meaning":"與……相比","examples":[{"en":"Measuring income is easier compared with measuring quality of life.","zh":"與衡量生活質素相比，衡量收入較容易。"},{"en":"Compared with means when judged against another thing.","zh":"與某事相比，是指把某事與另一事對照判斷。"},{"en":"Compared with driving, taking the bus may be cheaper but slower.","zh":"與駕車相比，乘巴士可能較便宜但較慢。"},{"en":"Comparisons help readers understand degree, advantage, or difficulty.","zh":"比較幫助讀者理解程度、優勢或困難。"},{"en":"This phrase clearly sets two things side by side.","zh":"這個短語清楚把兩件事並列比較。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":3},{"front":"how well people live","meaning":"人們生活得有多好","examples":[{"en":"It is difficult to measure how well people live.","zh":"衡量人們生活得有多好並不容易。"},{"en":"How well people live means the quality, comfort, and security of their daily lives.","zh":"人們生活得有多好，是指日常生活的質素、舒適和安全程度。"},{"en":"A family may live well if it has time to rest, healthy food, and safe housing.","zh":"如果家庭有休息時間、健康食物和安全住所，就可能生活得好。"},{"en":"Money helps, but it does not fully show how well people live.","zh":"金錢有幫助，但不能完全顯示人們生活得有多好。"},{"en":"This phrase asks about real life, not only income.","zh":"這個短語問的是真實生活，而不只是收入。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":3},{"front":"a recent paper","meaning":"一篇近期論文","examples":[{"en":"A recent paper by Dora Costa looks at the living-standards debate.","zh":"Dora Costa 的一篇近期論文探討生活水平爭議。"},{"en":"A recent paper is a newly published academic article or study.","zh":"一篇近期論文是最近發表的學術文章或研究。"},{"en":"A recent paper on sleep may change how schools think about early start times.","zh":"關於睡眠的一篇近期論文可能改變學校對早上上課時間的看法。"},{"en":"Recent papers can introduce new evidence into an old debate.","zh":"近期論文可以把新證據帶入舊爭議。"},{"en":"This phrase refers to research writing, not an ordinary newspaper page.","zh":"這個短語指研究文章，而不是普通報紙頁面。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":3},{"front":"living-standards debate","meaning":"生活水平爭議","examples":[{"en":"Dora Costa studies the living-standards debate from a new angle.","zh":"Dora Costa 從新角度研究生活水平爭議。"},{"en":"The living-standards debate is disagreement about whether people’s quality of life is improving or worsening.","zh":"生活水平爭議，是關於人們生活質素是在改善還是惡化的分歧。"},{"en":"One side may focus on income, while another side focuses on housing, health, or leisure.","zh":"一方可能聚焦收入，另一方聚焦住屋、健康或休閒。"},{"en":"A debate continues when different measures tell different stories.","zh":"當不同量度方法講出不同故事，爭議就會持續。"},{"en":"This phrase refers to a discussion about quality of life over time.","zh":"這個短語指關於生活質素隨時間變化的討論。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":3},{"front":"from an unusual direction","meaning":"從不尋常的角度","examples":[{"en":"Ms Costa examines the debate from an unusual direction.","zh":"Costa 女士從不尋常的角度考察這場爭議。"},{"en":"From an unusual direction means using a less common approach or viewpoint.","zh":"從不尋常的角度，是指使用較少見的方法或觀點。"},{"en":"A teacher may study exam stress from an unusual direction by looking at sleep habits.","zh":"老師可能透過研究睡眠習慣，從不尋常角度研究考試壓力。"},{"en":"A new angle can reveal details that traditional measures miss.","zh":"新角度可以揭示傳統量度遺漏的細節。"},{"en":"This phrase highlights originality in method or perspective.","zh":"這個短語突出方法或視角的原創性。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":3},{"front":"rather than","meaning":"而不是","examples":[{"en":"Rather than focusing on cash incomes, she studies leisure habits.","zh":"她研究休閒習慣，而不是集中於現金收入。"},{"en":"Rather than means instead of; it clearly contrasts one choice with another.","zh":"而不是是指 instead of，清楚對比兩個選擇。"},{"en":"A student may revise by practising essays rather than only rereading notes.","zh":"學生可以透過練習作文溫習，而不是只重讀筆記。"},{"en":"Choosing one focus rather than another can change the conclusion of a study.","zh":"選擇一個焦點而不是另一個焦點，會改變研究結論。"},{"en":"This phrase helps separate what is not done from what is done.","zh":"這個短語幫助分清沒有做甚麼和做了甚麼。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":3},{"front":"cash incomes","meaning":"現金收入","examples":[{"en":"Ms Costa looks beyond cash incomes to study recreational habits.","zh":"Costa 女士超越現金收入，研究消閒習慣。"},{"en":"Cash incomes are the money people receive as wages, salaries, or other direct payments.","zh":"現金收入是人們以工資、薪金或其他直接付款形式得到的金錢。"},{"en":"A family’s cash income may rise, but living costs may rise too.","zh":"家庭現金收入可能上升，但生活成本也可能上升。"},{"en":"Cash income alone cannot show whether people have more free time or better leisure.","zh":"單看現金收入不能顯示人們是否有更多空閒時間或更好休閒。"},{"en":"This phrase refers to money received, not goods or services enjoyed.","zh":"這個短語指收到的金錢，而不是享用的商品或服務。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":3},{"front":"investigate recreational habits","meaning":"研究消閒習慣","examples":[{"en":"Ms Costa investigates Americans’ recreational habits over the past century.","zh":"Costa 女士研究美國人在過去一個世紀的消閒習慣。"},{"en":"To investigate recreational habits means to study how people spend free time and leisure money.","zh":"研究消閒習慣，是指研究人們如何花空閒時間和休閒金錢。"},{"en":"A city may investigate recreational habits before building new parks.","zh":"城市在建新公園前，可能研究居民消閒習慣。"},{"en":"Studying leisure habits can reveal changes in income, time, and technology.","zh":"研究休閒習慣可以揭示收入、時間和科技的變化。"},{"en":"This phrase describes research into what people do for enjoyment.","zh":"這個短語描述對人們娛樂方式的研究。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":3},{"front":"recreational habits","meaning":"消閒習慣","examples":[{"en":"Americans’ recreational habits have changed over the past century.","zh":"美國人的消閒習慣在過去一個世紀有所改變。"},{"en":"Recreational habits are regular ways people relax, play, travel, read, watch, or socialise.","zh":"消閒習慣是人們放鬆、玩樂、旅行、閱讀、觀看或社交的慣常方式。"},{"en":"A teenager’s recreational habits may include gaming, sport, music, and online videos.","zh":"青少年的消閒習慣可能包括打機、運動、音樂和網上影片。"},{"en":"Recreational habits change when prices, technology, and free time change.","zh":"當價格、科技和空閒時間改變，消閒習慣也會改變。"},{"en":"This phrase focuses on repeated leisure behaviour.","zh":"這個短語聚焦重複出現的休閒行為。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":3},{"front":"over the past century","meaning":"在過去一個世紀","examples":[{"en":"Ms Costa studies recreational habits over the past century.","zh":"Costa 女士研究過去一個世紀的消閒習慣。"},{"en":"Over the past century means during the last one hundred years.","zh":"在過去一個世紀，是指在最近一百年間。"},{"en":"Over the past century, travel has become faster and more affordable.","zh":"在過去一個世紀，旅行變得更快也更可負擔。"},{"en":"A century-long view helps researchers see deep social change.","zh":"一個世紀的視角幫助研究人員看見深層社會變化。"},{"en":"This phrase gives a long historical time frame.","zh":"這個短語提供長期歷史時間範圍。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":3},{"front":"income levels","meaning":"收入階層","examples":[{"en":"People of all income levels have spent more on having fun.","zh":"各收入階層的人都花更多錢在消遣娛樂上。"},{"en":"Income levels are different amounts or ranges of earnings among people or households.","zh":"收入階層是人們或家庭不同收入金額或範圍。"},{"en":"A survey may compare families from low, middle, and high income levels.","zh":"調查可能比較低、中、高收入階層家庭。"},{"en":"If leisure grows across income levels, it is not limited to the rich.","zh":"如果休閒在各收入階層都增長，就不只限於富人。"},{"en":"This phrase helps group people by earnings.","zh":"這個短語幫助按收入把人分類。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":3},{"front":"steadily increased","meaning":"穩步增加","examples":[{"en":"Americans have steadily increased the amount of time and money spent on leisure.","zh":"美國人花在休閒上的時間和金錢已穩步增加。"},{"en":"Steadily increased means grown gradually and continuously over time.","zh":"穩步增加，是指隨時間逐漸而持續增長。"},{"en":"A student’s vocabulary may steadily increase through daily reading.","zh":"學生透過每日閱讀，詞彙量可能穩步增加。"},{"en":"Steady growth suggests a long-term trend rather than a sudden jump.","zh":"穩定增長暗示長期趨勢，而不是突然跳升。"},{"en":"This phrase describes consistent upward movement.","zh":"這個短語描述持續向上的變化。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":4},{"front":"devote time and money to","meaning":"將時間和金錢投放於……","examples":[{"en":"People devote more time and money to having fun.","zh":"人們將更多時間和金錢投放於消遣娛樂。"},{"en":"To devote time and money to something means to spend them deliberately on that activity.","zh":"將時間和金錢投放於某事，是指有意把它們花在該活動上。"},{"en":"Parents may devote time and money to their children’s music lessons.","zh":"父母可能把時間和金錢投放於孩子的音樂課。"},{"en":"People devote more resources to leisure when necessities take a smaller share of income.","zh":"當必需品佔收入比例較小，人們會把更多資源投放於休閒。"},{"en":"This phrase shows purposeful allocation of limited resources.","zh":"這個短語顯示對有限資源的有意分配。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":4},{"front":"having fun","meaning":"消遣娛樂","examples":[{"en":"Americans of all incomes now spend more on having fun.","zh":"現在各收入階層的美國人都花更多錢在消遣娛樂上。"},{"en":"Having fun means enjoying leisure, entertainment, play, or social activities.","zh":"消遣娛樂是指享受休閒、娛樂、玩樂或社交活動。"},{"en":"A family may spend Saturday having fun at a public park.","zh":"一個家庭可能星期六在公園消遣娛樂。"},{"en":"When leisure becomes cheaper, more people can spend money on having fun.","zh":"當休閒變得更便宜，更多人可以花錢消遣娛樂。"},{"en":"This phrase is informal and focuses on enjoyment.","zh":"這個短語較口語，聚焦享受。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":4},{"front":"become more skewed","meaning":"變得更偏斜；更不平均","examples":[{"en":"The distribution of dollar incomes may have become more skewed.","zh":"美元收入分布可能變得更偏斜。"},{"en":"To become more skewed means to become more uneven or tilted toward one side.","zh":"變得更偏斜，是指變得更不平均或偏向一方。"},{"en":"A class’s results become skewed if a few students score extremely high and many score low.","zh":"如果少數學生得分極高而許多人低分，班級成績分布就會偏斜。"},{"en":"Income becomes more skewed when gains concentrate among richer groups.","zh":"當收益集中於較富裕群體，收入就變得更偏斜。"},{"en":"This phrase describes imbalance in a distribution.","zh":"這個短語描述分布中的失衡。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":4},{"front":"more evenly spread than ever","meaning":"比以往任何時候都分布得更平均","examples":[{"en":"Leisure is more evenly spread than ever.","zh":"休閒比以往任何時候都分布得更平均。"},{"en":"More evenly spread than ever means shared more equally now than at any earlier time.","zh":"比以往任何時候都分布得更平均，是指現在比過去任何時候都更平等共享。"},{"en":"Internet access to music has made entertainment more evenly spread than before.","zh":"網上音樂令娛樂比以前分布得更平均。"},{"en":"If leisure is evenly spread, poor and rich people enjoy more similar opportunities.","zh":"如果休閒分布平均，貧富人士享有的機會會更相似。"},{"en":"This phrase contrasts equality in leisure with inequality in income.","zh":"這個短語把休閒平等與收入不平等作對比。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":4},{"front":"base research on","meaning":"以……作為研究基礎","examples":[{"en":"Ms Costa bases her research on consumption surveys.","zh":"Costa 女士以消費調查作為研究基礎。"},{"en":"To base research on something means to use it as the main evidence or foundation.","zh":"以某物作為研究基礎，是指把它用作主要證據或根基。"},{"en":"A teacher may base a report on student interviews and test results.","zh":"老師可能以學生訪問和測驗結果作為報告基礎。"},{"en":"Research findings depend on the quality of the data they are based on.","zh":"研究結果取決於其所基於數據的質素。"},{"en":"This phrase shows where a study gets its support.","zh":"這個短語顯示研究從哪裡得到支持。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":4},{"front":"consumption surveys","meaning":"消費調查","examples":[{"en":"Consumption surveys show how households spend their money.","zh":"消費調查顯示家庭如何花錢。"},{"en":"Consumption surveys are studies that record what people or families buy and use.","zh":"消費調查是記錄個人或家庭購買和使用甚麼的研究。"},{"en":"A consumption survey may ask how much a family spends on food, rent, transport, and leisure.","zh":"消費調查可能詢問家庭在食物、租金、交通和休閒上花多少。"},{"en":"Such surveys help researchers compare living patterns across income groups.","zh":"這類調查幫助研究人員比較不同收入階層的生活模式。"},{"en":"This phrase refers to spending data, not income alone.","zh":"這個短語指開支數據，而不只是收入。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":4},{"front":"date back as far as","meaning":"追溯至早於……","examples":[{"en":"The surveys date back as far as 1888.","zh":"這些調查可追溯至早於 1888 年。"},{"en":"To date back as far as a year means to have records or origins from that early time.","zh":"追溯至某年份，是指記錄或起源來自那麼早的時間。"},{"en":"A school archive may date back as far as the 1920s.","zh":"學校檔案可能追溯至早於 1920 年代。"},{"en":"Old records allow researchers to compare today with a much earlier period.","zh":"舊記錄讓研究人員把今天與更早時期比較。"},{"en":"This phrase emphasises how far into the past the evidence reaches.","zh":"這個短語強調證據延伸到多遠的過去。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":4},{"front":"industrial workers","meaning":"產業工人","examples":[{"en":"Industrial workers in 1888 spent most of their incomes on necessities.","zh":"1888 年的產業工人大部分收入花在必需品上。"},{"en":"Industrial workers are people employed in factories, manufacturing, mining, or similar production work.","zh":"產業工人是在工廠、製造業、採礦或類似生產工作中受僱的人。"},{"en":"Industrial workers may spend long hours making goods or operating machines.","zh":"產業工人可能長時間製造貨品或操作機器。"},{"en":"In earlier times, many industrial workers had little money left after basic needs.","zh":"在較早時期，許多產業工人在基本需要後剩下很少錢。"},{"en":"This phrase identifies a working-class group in economic history.","zh":"這個短語指出經濟史中的工人階級群體。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":4},{"front":"on average","meaning":"平均而言","examples":[{"en":"On average, workers spent three-quarters of their incomes on basic needs.","zh":"平均而言，工人把四分之三收入花在基本需要上。"},{"en":"On average means when the total is divided across all people or cases.","zh":"平均而言，是指把總數分配到所有人或個案後所得的情況。"},{"en":"On average, students in the class read for twenty minutes each day.","zh":"平均而言，班上學生每天閱讀二十分鐘。"},{"en":"Averages can be useful, but they may hide differences between rich and poor families.","zh":"平均數有用，但可能隱藏貧富家庭之間的差異。"},{"en":"This phrase gives a general figure, not every individual case.","zh":"這個短語給出一般數字，而不是每個個體情況。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":4},{"front":"three-quarters of","meaning":"四分之三的……","examples":[{"en":"The workers spent three-quarters of their incomes on food, shelter and clothing.","zh":"工人把四分之三收入花在食物、住所和衣物上。"},{"en":"Three-quarters of something means seventy-five percent of it.","zh":"四分之三的某物，是指它的百分之七十五。"},{"en":"Three-quarters of the class joined the school picnic.","zh":"班上四分之三學生參加學校旅行。"},{"en":"If three-quarters of income goes to necessities, little money remains for leisure.","zh":"如果四分之三收入用於必需品，剩下給休閒的錢就很少。"},{"en":"This phrase expresses a large proportion.","zh":"這個短語表達很大比例。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":4},{"front":"food, shelter and clothing","meaning":"食物、住所和衣物","examples":[{"en":"Food, shelter and clothing took up most of workers’ incomes.","zh":"食物、住所和衣物佔去工人大部分收入。"},{"en":"Food, shelter and clothing are basic necessities people need to survive and live decently.","zh":"食物、住所和衣物是人們生存和體面生活所需的基本必需品。"},{"en":"A family first pays for food, shelter and clothing before spending on entertainment.","zh":"家庭會先支付食物、住所和衣物，再花錢娛樂。"},{"en":"When these basics are expensive, leisure spending becomes difficult.","zh":"當這些基本需要昂貴，休閒開支就變得困難。"},{"en":"This phrase refers to essential living needs.","zh":"這個短語指基本生活需要。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":5},{"front":"be spent on leisure","meaning":"花在休閒上","examples":[{"en":"Less than 2% of the average family’s income was spent on leisure.","zh":"一般家庭收入少於 2% 花在休閒上。"},{"en":"To be spent on leisure means money is used for entertainment or free-time activities.","zh":"花在休閒上，是指金錢用於娛樂或空閒活動。"},{"en":"A household budget may show how much is spent on leisure each month.","zh":"家庭預算可能顯示每月有多少花在休閒上。"},{"en":"When little income is spent on leisure, life may be mostly about survival.","zh":"當很少收入花在休閒上，生活可能主要圍繞生存。"},{"en":"This phrase describes where part of a budget goes.","zh":"這個短語描述預算的一部分流向哪裡。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":5},{"front":"hide large disparities","meaning":"掩蓋巨大差異","examples":[{"en":"The average hid large disparities between income groups.","zh":"平均數掩蓋了收入階層之間的巨大差異。"},{"en":"To hide large disparities means to make big differences less visible.","zh":"掩蓋巨大差異，是指令重大差別較不明顯。"},{"en":"A class average can hide large disparities if some students score very high and others fail.","zh":"如果有些學生高分而有些不及格，班級平均分會掩蓋巨大差異。"},{"en":"Averages may look simple, but they can conceal inequality.","zh":"平均數可能看似簡單，但它們可以掩蓋不平等。"},{"en":"This phrase warns that one number may not show the full picture.","zh":"這個短語提醒人，一個數字未必顯示完整圖像。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":5},{"front":"large disparities","meaning":"巨大差異","examples":[{"en":"There were large disparities in leisure spending between rich and poor families.","zh":"富裕家庭和貧窮家庭之間的休閒開支有巨大差異。"},{"en":"Large disparities are big differences between groups.","zh":"巨大差異是不同群體之間很大的差別。"},{"en":"There may be large disparities in internet access between city and rural students.","zh":"城市和鄉村學生之間的互聯網接觸可能有巨大差異。"},{"en":"Large disparities matter because they can lead to unequal opportunities.","zh":"巨大差異很重要，因為它們會導致機會不平等。"},{"en":"This phrase is often used in social and economic comparisons.","zh":"這個短語常用於社會和經濟比較。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":5},{"front":"the share of a family’s budget","meaning":"家庭預算中的比例","examples":[{"en":"The share of a family’s budget spent on fun rose with income.","zh":"家庭預算中花在娛樂上的比例隨收入上升。"},{"en":"The share of a family’s budget means the portion of total spending used for one purpose.","zh":"家庭預算中的比例，是指總開支中用於某目的的部分。"},{"en":"Rent may take a large share of a family’s budget in an expensive city.","zh":"在昂貴城市，租金可能佔家庭預算很大比例。"},{"en":"If leisure takes a bigger share, the family has more room beyond necessities.","zh":"如果休閒佔更大比例，家庭在必需品以外就有更多空間。"},{"en":"This phrase describes a percentage of household spending.","zh":"這個短語描述家庭開支中的百分比。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":5},{"front":"rise sharply with","meaning":"隨……急升","examples":[{"en":"Recreational spending rose sharply with income.","zh":"消閒開支隨收入急升。"},{"en":"To rise sharply with something means to increase quickly as that factor increases.","zh":"隨某事急升，是指當該因素增加時迅速上升。"},{"en":"Restaurant spending may rise sharply with income because richer families eat out more.","zh":"餐廳開支可能隨收入急升，因為較富裕家庭較常外出用餐。"},{"en":"If leisure spending rises sharply with income, richer people enjoy far more recreation.","zh":"如果休閒開支隨收入急升，富人就享有多得多的消閒。"},{"en":"This phrase shows a strong upward relationship.","zh":"這個短語顯示強烈上升關係。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":5},{"front":"working-class sample","meaning":"工人階級樣本","examples":[{"en":"The working-class sample showed clear differences in leisure spending.","zh":"工人階級樣本顯示休閒開支有清楚差異。"},{"en":"A working-class sample is a group of working-class people selected for study.","zh":"工人階級樣本是被選作研究的一組工人階級人士。"},{"en":"Researchers may use a working-class sample to understand factory workers’ budgets.","zh":"研究人員可能使用工人階級樣本來了解工廠工人的預算。"},{"en":"A sample helps researchers study a larger group without surveying everyone.","zh":"樣本幫助研究人員研究較大群體，而不必調查每個人。"},{"en":"This phrase combines social class with research method.","zh":"這個短語結合社會階級和研究方法。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":5},{"front":"lowest-income families","meaning":"收入最低的家庭","examples":[{"en":"The lowest-income families spent very little on recreation.","zh":"收入最低的家庭在消閒上花很少。"},{"en":"Lowest-income families are households earning the least money in a group or society.","zh":"收入最低的家庭是某群體或社會中賺錢最少的家庭。"},{"en":"Lowest-income families may have to spend nearly everything on rent, food, and transport.","zh":"收入最低的家庭可能幾乎把所有錢花在租金、食物和交通上。"},{"en":"When income is very low, leisure becomes harder to afford.","zh":"當收入很低，休閒就更難負擔。"},{"en":"This phrase identifies the poorest households in a comparison.","zh":"這個短語指出比較中的最貧困家庭。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":5},{"front":"barely 1%","meaning":"只有約百分之一；幾乎不足百分之一","examples":[{"en":"The poorest families spent barely 1% of their budgets on recreation.","zh":"最貧窮家庭只有約 1% 的預算花在消閒上。"},{"en":"Barely 1% means only about one percent, or almost not more than one percent.","zh":"只有約百分之一，是指大約只有百分之一，幾乎沒有超過。"},{"en":"If a student spends barely 1% of study time on speaking, progress will be slow.","zh":"如果學生只有約 1% 溫習時間用於口語，進步會很慢。"},{"en":"A very small percentage shows how limited the spending was.","zh":"很小的百分比顯示開支非常有限。"},{"en":"This phrase emphasises that the amount is extremely low.","zh":"這個短語強調數量極低。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":5},{"front":"higher earners","meaning":"較高收入者","examples":[{"en":"Higher earners spent more than 3% of their budgets on recreation.","zh":"較高收入者把超過 3% 的預算花在消閒上。"},{"en":"Higher earners are people who make more money than others in the comparison.","zh":"較高收入者是在比較中賺錢較多的人。"},{"en":"Higher earners may spend more on travel, concerts, and restaurant meals.","zh":"較高收入者可能花更多錢在旅行、音樂會和餐廳用餐上。"},{"en":"When entertainment is costly, higher earners can access it more easily.","zh":"當娛樂昂貴時，較高收入者較容易接觸到。"},{"en":"This phrase identifies people with relatively higher incomes.","zh":"這個短語指出收入相對較高的人。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":5},{"front":"afford such extravagances as","meaning":"負擔得起……這類奢侈享受","examples":[{"en":"Only higher earners could afford such extravagances as theatre performances.","zh":"只有較高收入者才負擔得起戲劇演出這類奢侈享受。"},{"en":"To afford such extravagances as something means to have enough money for costly luxuries like that.","zh":"負擔得起某類奢侈享受，是指有足夠金錢支付那類昂貴享受。"},{"en":"In the past, only rich families could afford such extravagances as private tutors abroad.","zh":"在過去，只有富裕家庭負擔得起海外私人補習這類奢侈享受。"},{"en":"When entertainment is expensive, it becomes an extravagance for ordinary workers.","zh":"當娛樂昂貴，它對普通工人而言就成為奢侈享受。"},{"en":"This phrase highlights luxury spending that not everyone can pay for.","zh":"這個短語突出不是人人都能支付的奢侈開支。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":5},{"front":"extravagances","meaning":"奢侈享受","examples":[{"en":"Theatre and concert performances were once expensive extravagances.","zh":"戲劇和音樂會演出曾是昂貴的奢侈享受。"},{"en":"Extravagances are costly things people enjoy but do not strictly need.","zh":"奢侈享受是昂貴、令人享受但並非嚴格必需的東西。"},{"en":"A luxury handbag may be an extravagance for a student on a small budget.","zh":"對預算很少的學生來說，名牌手袋可能是奢侈享受。"},{"en":"When incomes rise, former extravagances may become ordinary pleasures.","zh":"當收入上升，昔日奢侈享受可能變成普通樂趣。"},{"en":"This word contrasts luxuries with necessities.","zh":"這個詞把奢侈品與必需品作對比。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":6},{"front":"theatre and concert performances","meaning":"戲劇和音樂會演出","examples":[{"en":"Theatre and concert performances were once available mainly to higher earners.","zh":"戲劇和音樂會演出曾主要供較高收入者享受。"},{"en":"Theatre and concert performances are live shows such as plays, musicals, orchestras, or singers.","zh":"戲劇和音樂會演出是現場表演，例如舞台劇、音樂劇、管弦樂或歌手演出。"},{"en":"A family may attend theatre and concert performances during holidays.","zh":"家庭可能在假期觀看戲劇和音樂會演出。"},{"en":"High ticket prices can limit these performances to people with more money.","zh":"高票價會限制這些演出只供較有錢的人享受。"},{"en":"This phrase refers to live cultural entertainment.","zh":"這個短語指現場文化娛樂。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":6},{"front":"relatively much more expensive than","meaning":"相對上比……昂貴得多","examples":[{"en":"Concert performances were relatively much more expensive than they are today.","zh":"音樂會演出相對上比今天昂貴得多。"},{"en":"Relatively much more expensive than means far costlier when compared with income or alternatives.","zh":"相對上比某物昂貴得多，是指與收入或替代選項比較時成本高很多。"},{"en":"Air travel was relatively much more expensive than it is now.","zh":"航空旅行以往相對上比現在昂貴得多。"},{"en":"A service can feel cheaper today because incomes rose and technology reduced costs.","zh":"一項服務今天可能感覺較便宜，因為收入上升而科技降低成本。"},{"en":"This phrase compares affordability across time.","zh":"這個短語比較不同時期的可負擔程度。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":6},{"front":"since those days","meaning":"自那些日子以來","examples":[{"en":"Since those days, leisure has become less of a luxury.","zh":"自那些日子以來，休閒變得不那麼奢侈。"},{"en":"Since those days means from that earlier period until now.","zh":"自那些日子以來，是指從較早時期直到現在。"},{"en":"Since those days, mobile phones have changed how students communicate.","zh":"自那些日子以來，手機改變了學生溝通方式。"},{"en":"This phrase marks a change from the past to the present.","zh":"這個短語標示從過去到現在的改變。"},{"en":"It often introduces long-term development.","zh":"它常引入長期發展。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":6},{"front":"become less of a luxury","meaning":"變得不那麼奢侈","examples":[{"en":"Leisure has steadily become less of a luxury.","zh":"休閒已穩步變得不那麼奢侈。"},{"en":"To become less of a luxury means to become more affordable and ordinary.","zh":"變得不那麼奢侈，是指變得更可負擔和更普通。"},{"en":"Internet music has made listening to songs less of a luxury.","zh":"網上音樂令聽歌變得不那麼奢侈。"},{"en":"When prices fall, activities once reserved for the rich become more common.","zh":"當價格下降，曾經只屬富人的活動會變得更常見。"},{"en":"This phrase shows that access has widened.","zh":"這個短語顯示接觸機會擴大。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":6},{"front":"average household","meaning":"一般家庭","examples":[{"en":"The average household spent less of its income on necessities by 1991.","zh":"到 1991 年，一般家庭把較少收入花在必需品上。"},{"en":"The average household means a typical family or home in the data.","zh":"一般家庭是指數據中的典型家庭或住戶。"},{"en":"The average household may spend a large share of income on rent in a city.","zh":"在城市中，一般家庭可能把很大比例收入花在租金上。"},{"en":"Averages describe the typical case, but some families may be very different.","zh":"平均數描述典型情況，但有些家庭可能非常不同。"},{"en":"This phrase is often used in economic surveys.","zh":"這個短語常用於經濟調查。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":6},{"front":"devote income to","meaning":"將收入投放於……","examples":[{"en":"The average household needed to devote only 38% of its income to necessities.","zh":"一般家庭只需要將 38% 收入投放於必需品。"},{"en":"To devote income to something means to use part of earnings for that purpose.","zh":"將收入投放於某事，是指把部分收入用於該目的。"},{"en":"A family may devote income to rent, food, education, and savings.","zh":"家庭可能將收入投放於租金、食物、教育和儲蓄。"},{"en":"If less income is devoted to necessities, more remains for leisure or investment.","zh":"如果較少收入用於必需品，就有更多剩餘給休閒或投資。"},{"en":"This phrase describes how earnings are allocated.","zh":"這個短語描述收入如何分配。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":6},{"front":"basic necessities","meaning":"基本生活必需品","examples":[{"en":"Households spent a smaller share of income on basic necessities.","zh":"家庭把較小比例收入花在基本生活必需品上。"},{"en":"Basic necessities are essential things such as food, housing, clothing, and heating.","zh":"基本生活必需品是食物、住屋、衣物和暖氣等必需東西。"},{"en":"Families must pay for basic necessities before choosing entertainment.","zh":"家庭必須先支付基本生活必需品，再選擇娛樂。"},{"en":"When necessities become cheaper relative to income, living standards may improve.","zh":"當必需品相對收入變便宜，生活水平可能改善。"},{"en":"This phrase refers to needs, not luxuries.","zh":"這個短語指需要，而不是奢侈品。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":6},{"front":"moreover","meaning":"此外","examples":[{"en":"Moreover, leisure spending now rises less sharply with income.","zh":"此外，休閒開支現在隨收入上升的幅度較小。"},{"en":"Moreover means furthermore or in addition to what has just been said.","zh":"此外是指進一步或在剛才所說之外。"},{"en":"The library is open longer; moreover, it now offers free online books.","zh":"圖書館開放時間更長；此外，它現在提供免費電子書。"},{"en":"This word adds another supporting point to an argument.","zh":"這個詞為論點加入另一個支持點。"},{"en":"It is more formal than “also.”","zh":"它比 “also” 更正式。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":6},{"front":"much less sharply","meaning":"沒有以往那麼急劇","examples":[{"en":"Recreational spending rises much less sharply with income than before.","zh":"消閒開支隨收入上升的幅度沒有以往那麼急劇。"},{"en":"Much less sharply means the increase is far less steep or dramatic.","zh":"沒有那麼急劇，是指增幅遠沒有那麼陡或戲劇性。"},{"en":"Rent may rise much less sharply after the government adds housing supply.","zh":"政府增加房屋供應後，租金可能沒有以往那麼急劇上升。"},{"en":"If leisure spending rises less sharply with income, poorer people may be catching up.","zh":"如果休閒開支隨收入上升不那麼急劇，較貧窮人士可能正在追上。"},{"en":"This phrase describes a weaker relationship than before.","zh":"這個短語描述比以前較弱的關係。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":6},{"front":"at the beginning of this century","meaning":"在本世紀初","examples":[{"en":"At the beginning of this century, recreational spending rose quickly with income.","zh":"在本世紀初，消閒開支隨收入迅速上升。"},{"en":"At the beginning of this century means in the early years of the century being discussed.","zh":"在本世紀初，是指正在討論的世紀早期年份。"},{"en":"At the beginning of this century, many homes still had slower internet connections.","zh":"在本世紀初，許多家庭仍使用較慢的互聯網連線。"},{"en":"This phrase gives historical timing for a comparison.","zh":"這個短語為比較提供歷史時間點。"},{"en":"It helps show how patterns have changed since then.","zh":"它幫助顯示自那時以來模式如何改變。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":6},{"front":"tend to rise by","meaning":"往往上升……","examples":[{"en":"Recreational spending tended to rise by 20% for every 10% rise in income.","zh":"每當收入上升 10%，消閒開支往往上升 20%。"},{"en":"Tend to rise by means usually increase by a certain amount.","zh":"往往上升某數量，是指通常增加某個幅度。"},{"en":"Food costs may tend to rise by a few percent each year.","zh":"食物成本可能每年往往上升幾個百分點。"},{"en":"This phrase describes a general pattern, not every single case.","zh":"這個短語描述一般模式，而不是每個個案。"},{"en":"It is common in statistical explanation.","zh":"它常見於統計解釋。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":7},{"front":"income gain","meaning":"收入增長","examples":[{"en":"A 10% income gain led to a smaller rise in recreational spending.","zh":"10% 的收入增長導致消閒開支較小幅度上升。"},{"en":"An income gain is an increase in the money a person or household earns.","zh":"收入增長是個人或家庭所賺金錢增加。"},{"en":"A worker may use an income gain to save more or pay debts.","zh":"工人可能用收入增長來增加儲蓄或還債。"},{"en":"If income gains no longer strongly raise leisure spending, leisure may already be widely accessible.","zh":"如果收入增長不再強烈推高休閒開支，休閒可能已相當普及。"},{"en":"This phrase refers to extra earnings.","zh":"這個短語指額外收入。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":7},{"front":"lead to roughly","meaning":"導致大約……","examples":[{"en":"A 10% income gain led to roughly a 15% rise in recreational spending.","zh":"10% 的收入增長導致消閒開支大約上升 15%。"},{"en":"Lead to roughly means cause approximately a certain result.","zh":"導致大約某結果，是指造成近似某幅度的結果。"},{"en":"A short delay may lead to roughly ten minutes of extra waiting.","zh":"短暫延誤可能導致大約十分鐘額外等待。"},{"en":"Rough figures are useful when exact numbers are not necessary.","zh":"當不需要精確數字時，概約數字很有用。"},{"en":"This phrase connects a cause with an approximate effect.","zh":"這個短語把原因與大約結果連接起來。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":7},{"front":"what this implies is that","meaning":"這意味着","examples":[{"en":"What this implies is that leisure has become more available to everyone.","zh":"這意味着休閒變得更人人可及。"},{"en":"What this implies is that means the evidence suggests this conclusion.","zh":"這意味着，是指證據暗示這個結論。"},{"en":"If fewer students fail after extra support, what this implies is that support matters.","zh":"如果額外支援後較少學生不及格，這意味着支援很重要。"},{"en":"This phrase helps explain the meaning behind data.","zh":"這個短語幫助解釋數據背後的意思。"},{"en":"It introduces an interpretation, not just a number.","zh":"它引入解讀，而不只是數字。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":7},{"front":"one obvious cause","meaning":"一個明顯原因","examples":[{"en":"One obvious cause is that real income overall has risen.","zh":"一個明顯原因是整體實質收入上升。"},{"en":"One obvious cause means one reason that is easy to see or understand.","zh":"一個明顯原因，是指容易看見或理解的一個原因。"},{"en":"One obvious cause of late arrivals is heavy traffic near the school gate.","zh":"遲到的一個明顯原因是校門附近交通繁忙。"},{"en":"Obvious causes may explain part of a problem, but not necessarily all of it.","zh":"明顯原因可能解釋問題的一部分，但未必解釋全部。"},{"en":"This phrase introduces a clear explanation.","zh":"這個短語引入清楚解釋。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":7},{"front":"real income overall","meaning":"整體實質收入","examples":[{"en":"Real income overall has risen in the United States.","zh":"美國整體實質收入已經上升。"},{"en":"Real income overall means total buying power has increased after inflation is considered.","zh":"整體實質收入，是指考慮通脹後總體購買力增加。"},{"en":"Real income overall can rise even if some groups do not benefit equally.","zh":"即使有些群體未能平等受惠，整體實質收入仍可以上升。"},{"en":"When real income rises, families may have more money left after necessities.","zh":"當實質收入上升，家庭支付必需品後可能有更多餘錢。"},{"en":"This phrase describes broad purchasing power, not just cash amounts.","zh":"這個短語描述廣泛購買力，而不只是現金金額。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":7},{"front":"in general","meaning":"一般而言","examples":[{"en":"If Americans in general are richer, their entertainment spending changes.","zh":"如果美國人一般而言更富裕，他們的娛樂開支就會改變。"},{"en":"In general means overall or in most cases.","zh":"一般而言，是指整體上或在大多數情況下。"},{"en":"In general, students learn better when examples are concrete.","zh":"一般而言，例子具體時學生學得更好。"},{"en":"This phrase allows for exceptions while describing a broad pattern.","zh":"這個短語描述大致模式時容許例外。"},{"en":"It is useful when discussing large groups.","zh":"它適合用於討論大型群體。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":7},{"front":"consumption of entertainment goods","meaning":"娛樂商品消費","examples":[{"en":"The consumption of entertainment goods is less tied to income than before.","zh":"娛樂商品消費比以前較少與收入掛鉤。"},{"en":"Consumption of entertainment goods means buying or using products for enjoyment, such as music, films, or games.","zh":"娛樂商品消費是購買或使用音樂、電影、遊戲等享樂產品。"},{"en":"Streaming services have changed the consumption of entertainment goods at home.","zh":"串流服務改變了家庭中的娛樂商品消費。"},{"en":"When entertainment becomes cheap, consumption spreads beyond high-income groups.","zh":"當娛樂變便宜，消費就會擴散到高收入群體以外。"},{"en":"This phrase describes how people use leisure products.","zh":"這個短語描述人們如何使用休閒產品。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":7},{"front":"be less likely to be affected by","meaning":"較不容易受……影響","examples":[{"en":"Entertainment spending is less likely to be affected by income changes.","zh":"娛樂開支較不容易受收入變化影響。"},{"en":"To be less likely to be affected by something means to be less dependent on it or less changed by it.","zh":"較不容易受某事影響，是指較不依賴它或較少因它改變。"},{"en":"Public libraries make reading less likely to be affected by family income.","zh":"公共圖書館令閱讀較不容易受家庭收入影響。"},{"en":"If leisure is cheap, small income differences affect access less.","zh":"如果休閒便宜，小收入差異對接觸機會的影響較小。"},{"en":"This phrase describes weaker influence from a factor.","zh":"這個短語描述某因素的影響較弱。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":7},{"front":"reckon that","meaning":"估計；認為","examples":[{"en":"Ms Costa reckons that rising incomes explain only part of the change.","zh":"Costa 女士估計，收入上升只解釋了部分變化。"},{"en":"To reckon that means to think, estimate, or judge that something is true.","zh":"估計或認為某事，是指思考、估算或判斷某事為真。"},{"en":"A teacher may reckon that students need more practice before the exam.","zh":"老師可能認為學生考試前需要更多練習。"},{"en":"This phrase can sound slightly informal but is common in argument and analysis.","zh":"這個短語可帶少許口語感，但常見於論證和分析。"},{"en":"It introduces a reasoned opinion or estimate.","zh":"它引入有理由的看法或估計。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":7},{"front":"be responsible for","meaning":"是……的原因","examples":[{"en":"Rising incomes are responsible for at most half of the changing pattern.","zh":"收入上升最多只是這種變化模式一半的原因。"},{"en":"To be responsible for something means to be the cause of it.","zh":"是某事的原因，是指造成該事。"},{"en":"Poor planning may be responsible for delays in a school trip.","zh":"規劃不善可能是學校旅行延誤的原因。"},{"en":"A cause can be responsible for part of a change without explaining all of it.","zh":"一個原因可以解釋部分變化，而不解釋全部。"},{"en":"This phrase connects cause and effect.","zh":"這個短語連接原因和結果。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":7},{"front":"at most","meaning":"最多","examples":[{"en":"Rising incomes explain, at most, half of the change.","zh":"收入上升最多解釋一半變化。"},{"en":"At most means no more than a stated amount.","zh":"最多是指不超過所說的數量。"},{"en":"The walk to school takes ten minutes at most.","zh":"走路上學最多需要十分鐘。"},{"en":"If a factor explains at most half the change, other causes must also matter.","zh":"如果某因素最多解釋一半變化，其他原因也一定重要。"},{"en":"This phrase sets an upper limit.","zh":"這個短語設定上限。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":8},{"front":"the changing structure of","meaning":"……不斷變化的結構","examples":[{"en":"Ms Costa studies the changing structure of leisure spending.","zh":"Costa 女士研究休閒開支不斷變化的結構。"},{"en":"The changing structure of something means the way its parts or pattern are shifting over time.","zh":"某事不斷變化的結構，是指其組成部分或模式隨時間轉變。"},{"en":"A school may study the changing structure of student activities after online learning grows.","zh":"網上學習增長後，學校可能研究學生活動不斷變化的結構。"},{"en":"Looking at structure shows not only how much is spent, but what it is spent on.","zh":"查看結構不只顯示花了多少，也顯示花在哪裡。"},{"en":"This phrase focuses on patterns inside a larger total.","zh":"這個短語聚焦總體內部的模式。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":8},{"front":"be due to","meaning":"由於","examples":[{"en":"Much of the change may be due to poorer Americans having more time off.","zh":"很多變化可能由於較貧窮美國人有更多休息時間。"},{"en":"To be due to something means to be caused by it.","zh":"由於某事，是指由它造成。"},{"en":"The delay was due to a power failure at the station.","zh":"延誤是由於車站停電。"},{"en":"If leisure spending changes due to more free time, income is not the only cause.","zh":"如果休閒開支由於更多空閒時間而改變，收入就不是唯一原因。"},{"en":"This phrase gives a reason for a result.","zh":"這個短語給出結果的原因。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":8},{"front":"time off","meaning":"休息時間；假期","examples":[{"en":"Poorer Americans have more time off than they used to.","zh":"較貧窮美國人比以往有更多休息時間。"},{"en":"Time off means time away from work or duties for rest, holidays, or personal life.","zh":"休息時間是離開工作或職責，用於休息、假期或個人生活的時間。"},{"en":"A nurse may use time off to sleep, see family, or exercise.","zh":"護士可能用休息時間睡覺、見家人或運動。"},{"en":"More time off gives people more opportunity to enjoy leisure activities.","zh":"更多休息時間給人更多機會享受休閒活動。"},{"en":"This phrase refers to free time from work.","zh":"這個短語指離開工作的自由時間。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":8},{"front":"in earlier years","meaning":"在較早年代","examples":[{"en":"In earlier years, low-wage workers faced very long hours.","zh":"在較早年代，低薪工人面對極長工時。"},{"en":"In earlier years means during a previous period in the past.","zh":"在較早年代，是指過去某個較早時期。"},{"en":"In earlier years, many students wrote essays by hand rather than on computers.","zh":"在較早年代，許多學生用手寫作文，而不是用電腦。"},{"en":"This phrase helps compare past conditions with present ones.","zh":"這個短語幫助把過去條件與現在作比較。"},{"en":"It often introduces historical contrast.","zh":"它常引入歷史對比。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":8},{"front":"low-wage workers","meaning":"低薪工人","examples":[{"en":"Low-wage workers once worked extremely long hours.","zh":"低薪工人曾經工作極長時間。"},{"en":"Low-wage workers are people who earn relatively little money for their labour.","zh":"低薪工人是勞動所得相對較少的人。"},{"en":"Low-wage workers may include cleaners, kitchen staff, or delivery workers.","zh":"低薪工人可能包括清潔工、廚房員工或送貨員。"},{"en":"If low-wage workers have little time off, their leisure opportunities are limited.","zh":"如果低薪工人休息時間很少，休閒機會就有限。"},{"en":"This phrase identifies workers at the lower end of the pay scale.","zh":"這個短語指出薪酬階梯較低端的工人。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":8},{"front":"face extremely long hours","meaning":"面對極長工時","examples":[{"en":"Low-wage workers faced extremely long hours and few days off.","zh":"低薪工人面對極長工時和很少休假日。"},{"en":"To face extremely long hours means to have to work for very long periods.","zh":"面對極長工時，是指必須工作非常長時間。"},{"en":"A junior doctor may face extremely long hours during a busy hospital rotation.","zh":"初級醫生在繁忙醫院輪值期間可能面對極長工時。"},{"en":"Long hours reduce leisure because workers have little time or energy left.","zh":"長工時會減少休閒，因為工人剩下很少時間或精力。"},{"en":"This phrase describes demanding work conditions.","zh":"這個短語描述艱難工作條件。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":8},{"front":"few days off","meaning":"很少休假日","examples":[{"en":"Workers once enjoyed few days off.","zh":"工人曾經很少享有休假日。"},{"en":"Few days off means very few days away from work for rest.","zh":"很少休假日，是指離開工作休息的日子非常少。"},{"en":"A restaurant worker may have few days off during a holiday season.","zh":"餐廳員工在假期旺季可能很少休假日。"},{"en":"With few days off, people may have money but little time to enjoy leisure.","zh":"休假日很少時，人們可能有錢但沒有時間享受休閒。"},{"en":"This phrase points to lack of free time.","zh":"這個短語指出缺乏自由時間。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":8},{"front":"since the 1940s","meaning":"自二十世紀四十年代以來","examples":[{"en":"Since the 1940s, lower-paid workers have worked fewer hours.","zh":"自二十世紀四十年代以來，較低薪工人的工時減少。"},{"en":"Since the 1940s means from the decade of the 1940s until now or the later time discussed.","zh":"自二十世紀四十年代以來，是指從 1940 年代直到現在或所討論的後來時間。"},{"en":"Since the 1940s, many household technologies have changed daily life.","zh":"自二十世紀四十年代以來，許多家用科技改變了日常生活。"},{"en":"This phrase gives a historical starting point for a long trend.","zh":"這個短語為長期趨勢給出歷史起點。"},{"en":"It helps show that change happened over many decades.","zh":"它幫助顯示改變經歷了許多十年。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":8},{"front":"the less skilled","meaning":"技能較低的人","examples":[{"en":"The less skilled have worked ever-fewer hours since the 1940s.","zh":"技能較低的人自二十世紀四十年代以來工作時數越來越少。"},{"en":"The less skilled are workers with fewer specialised skills or qualifications.","zh":"技能較低的人是擁有較少專門技能或資格的工人。"},{"en":"The less skilled may have fewer job choices if industries demand advanced training.","zh":"如果行業要求高階訓練，技能較低的人可能工作選擇較少。"},{"en":"In this passage, the less skilled gained more leisure time as working hours fell.","zh":"在這篇文章中，技能較低的人因工時下降而獲得更多休閒時間。"},{"en":"This phrase refers to skill level, not personal worth.","zh":"這個短語指技能水平，而不是個人價值。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":8},{"front":"lower paid","meaning":"薪酬較低的","examples":[{"en":"Lower-paid workers have gained more time for leisure.","zh":"薪酬較低的工人獲得更多休閒時間。"},{"en":"Lower paid means receiving less money for work than other workers.","zh":"薪酬較低的，是指工作所得金錢比其他工人少。"},{"en":"Lower-paid staff may struggle more when rent and food prices rise.","zh":"當租金和食物價格上升，薪酬較低的員工可能更吃力。"},{"en":"If lower-paid workers gain time off, their leisure opportunities can improve.","zh":"如果薪酬較低的工人獲得休息時間，休閒機會可以改善。"},{"en":"This phrase compares pay levels within a workforce.","zh":"這個短語比較勞動人口中的薪酬水平。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":8},{"front":"ever-fewer hours","meaning":"越來越少的工時","examples":[{"en":"Lower-paid workers have worked ever-fewer hours.","zh":"薪酬較低的工人工作越來越少的工時。"},{"en":"Ever-fewer hours means fewer and fewer hours over time.","zh":"越來越少的工時，是指隨時間工時不斷減少。"},{"en":"A shop may open ever-fewer hours if customer numbers keep falling.","zh":"如果顧客數量持續下降，商店可能開放越來越少的時間。"},{"en":"Working ever-fewer hours can increase free time but may also reduce income.","zh":"工作越來越少的工時可以增加空閒時間，但也可能減少收入。"},{"en":"This phrase describes a continuing downward trend in time.","zh":"這個短語描述時間上的持續下降趨勢。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":9},{"front":"leisure pursuits","meaning":"消閒活動","examples":[{"en":"Shorter working hours give people more time to enjoy leisure pursuits.","zh":"較短工時給人更多時間享受消閒活動。"},{"en":"Leisure pursuits are activities people do for enjoyment in their free time.","zh":"消閒活動是人們在空閒時間為享受而做的活動。"},{"en":"Reading, sport, gardening, gaming, and music can all be leisure pursuits.","zh":"閱讀、運動、園藝、打機和音樂都可以是消閒活動。"},{"en":"More free time allows people to choose leisure pursuits beyond basic rest.","zh":"更多自由時間讓人選擇基本休息以外的消閒活動。"},{"en":"This phrase is slightly formal and means hobbies or recreation.","zh":"這個短語稍為正式，意思是興趣或休閒活動。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":9},{"front":"conveniently","meaning":"便利的是；剛好","examples":[{"en":"Conveniently, Americans now have more recreational possibilities.","zh":"便利的是，美國人現在有更多消閒選擇。"},{"en":"Conveniently means in a useful or helpful way that fits the situation well.","zh":"便利的是，是指以有用或有幫助、剛好配合情況的方式。"},{"en":"Conveniently, the bus stop is next to the library.","zh":"便利的是，巴士站就在圖書館旁邊。"},{"en":"If more free time appears at the same time as more leisure options, the two changes fit well.","zh":"如果更多自由時間與更多休閒選項同時出現，兩種變化就剛好配合。"},{"en":"This word can show that timing or circumstances are helpful.","zh":"這個詞可以表示時間或情況有利。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":9},{"front":"an increasing number of","meaning":"越來越多的……","examples":[{"en":"Americans have an increasing number of leisure options.","zh":"美國人有越來越多的休閒選項。"},{"en":"An increasing number of something means more and more of it over time.","zh":"越來越多的某物，是指其數量隨時間增加。"},{"en":"An increasing number of students use online dictionaries when writing essays.","zh":"越來越多學生寫作文時使用網上字典。"},{"en":"More options can make leisure more accessible but also more varied.","zh":"更多選項可以令休閒更易接觸，也更有變化。"},{"en":"This phrase describes growth in count or availability.","zh":"這個短語描述數量或可得性的增長。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":9},{"front":"recreational possibilities","meaning":"消閒選擇","examples":[{"en":"Americans have more recreational possibilities to choose from.","zh":"美國人有更多消閒選擇可供挑選。"},{"en":"Recreational possibilities are available ways to relax, play, travel, watch, listen, or socialise.","zh":"消閒選擇是可用的放鬆、玩樂、旅行、觀看、聆聽或社交方式。"},{"en":"A community centre creates recreational possibilities by offering sports and music classes.","zh":"社區中心透過提供運動和音樂課創造消閒選擇。"},{"en":"More possibilities can improve life when people have time and access.","zh":"當人們有時間和途徑，更多選擇可以改善生活。"},{"en":"This phrase means leisure options.","zh":"這個短語意思是休閒選項。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":9},{"front":"choose from","meaning":"從中選擇","examples":[{"en":"People now have many recreational possibilities to choose from.","zh":"人們現在有許多消閒選擇可從中選擇。"},{"en":"To choose from means to select among available options.","zh":"從中選擇，是指在可用選項之中挑選。"},{"en":"Students may choose from several clubs after school.","zh":"學生放學後可以從幾個學會中選擇。"},{"en":"Having more options to choose from can increase freedom and variety.","zh":"有更多選項可選可以增加自由和多樣性。"},{"en":"This phrase focuses on the set of available choices.","zh":"這個短語聚焦可用選擇的集合。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":9},{"front":"public investment in","meaning":"對……的公共投資","examples":[{"en":"Public investment in parks has made leisure more accessible.","zh":"對公園的公共投資令休閒更易接觸。"},{"en":"Public investment in something means government or public money spent to build or improve it.","zh":"對某事的公共投資，是指政府或公共資金用來建設或改善它。"},{"en":"Public investment in libraries gives more families free access to books.","zh":"對圖書館的公共投資讓更多家庭免費接觸書籍。"},{"en":"When public investment creates facilities, leisure no longer depends only on private wealth.","zh":"當公共投資創造設施，休閒就不再只取決於私人財富。"},{"en":"This phrase connects government spending with public benefit.","zh":"這個短語把政府開支與公共利益連接起來。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":9},{"front":"sports complexes","meaning":"綜合運動場館","examples":[{"en":"Sports complexes have made leisure cheaper and more accessible.","zh":"綜合運動場館令休閒更便宜、更易接觸。"},{"en":"Sports complexes are large facilities with several areas for exercise and sport.","zh":"綜合運動場館是有多個運動和健身區域的大型設施。"},{"en":"A sports complex may include swimming pools, courts, gyms, and running tracks.","zh":"綜合運動場館可能包括泳池、球場、健身室和跑道。"},{"en":"Public sports complexes can help low-income families enjoy exercise affordably.","zh":"公共綜合運動場館可以幫助低收入家庭以可負擔方式運動。"},{"en":"This phrase refers to organised places for physical recreation.","zh":"這個短語指有組織的體育消閒場所。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":9},{"front":"golf courses","meaning":"高爾夫球場","examples":[{"en":"Public investment in golf courses has expanded leisure options.","zh":"對高爾夫球場的公共投資擴大了休閒選擇。"},{"en":"Golf courses are large outdoor areas designed for playing golf.","zh":"高爾夫球場是為打高爾夫而設的大型戶外場地。"},{"en":"A public golf course can allow more people to try a sport once linked to wealth.","zh":"公共高爾夫球場可以讓更多人嘗試一項曾與財富相連的運動。"},{"en":"Building such facilities can widen access if prices are kept low.","zh":"如果價格保持低廉，建設這類設施可以擴大接觸機會。"},{"en":"This phrase names one type of recreational facility.","zh":"這個短語命名一種消閒設施。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":9},{"front":"make leisure cheaper and more accessible","meaning":"令休閒活動更便宜、更易接觸","examples":[{"en":"Public facilities have made leisure cheaper and more accessible.","zh":"公共設施令休閒活動更便宜、更易接觸。"},{"en":"To make leisure cheaper and more accessible means to reduce cost and make recreation easier to use.","zh":"令休閒活動更便宜、更易接觸，是指降低成本並令消閒更容易使用。"},{"en":"Free parks make leisure cheaper and more accessible for families without large budgets.","zh":"免費公園令預算不多的家庭也能更便宜、更容易接觸休閒。"},{"en":"When leisure becomes affordable, more people can enjoy rest and entertainment.","zh":"當休閒變得可負擔，更多人可以享受休息和娛樂。"},{"en":"This phrase describes widening access to recreation.","zh":"這個短語描述擴大消閒接觸機會。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":9},{"front":"so too has","meaning":"……亦同樣如此","examples":[{"en":"Public investment has made leisure cheaper, and so too has technological innovation.","zh":"公共投資令休閒更便宜，科技創新亦同樣如此。"},{"en":"So too has means another factor has done the same thing.","zh":"……亦同樣如此，是指另一個因素也做了同樣的事。"},{"en":"Better teaching has improved exam results, and so too has extra practice at home.","zh":"更好教學改善了考試成績，家中額外練習亦同樣如此。"},{"en":"This phrase adds a second cause with the same effect.","zh":"這個短語加入第二個具有相同效果的原因。"},{"en":"It is a formal way to say “has also.”","zh":"它是 “has also” 的正式說法。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":9},{"front":"technological innovation","meaning":"科技創新","examples":[{"en":"Technological innovation has made entertainment more widely available.","zh":"科技創新令娛樂更廣泛可得。"},{"en":"Technological innovation means new or improved technology that changes how people live or work.","zh":"科技創新是改變人們生活或工作的新的或改良的科技。"},{"en":"Streaming platforms are a technological innovation that changed how people watch films.","zh":"串流平台是一項改變人們觀看電影方式的科技創新。"},{"en":"Innovation can lower costs and let more people enjoy products at home.","zh":"創新可以降低成本，讓更多人在家享受產品。"},{"en":"This phrase refers to practical new technology, not just scientific ideas.","zh":"這個短語指實用新科技，而不只是科學想法。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":10},{"front":"listening to music used to imply","meaning":"聽音樂以往意味着……","examples":[{"en":"Listening to music used to imply paying for concerts or owning a piano.","zh":"聽音樂以往意味着要付費看音樂會或擁有鋼琴。"},{"en":"Used to imply means once usually meant or required something.","zh":"以往意味着，是指過去通常代表或需要某事。"},{"en":"Calling a friend used to imply finding a telephone, not tapping a screen.","zh":"打電話給朋友以往意味着要找電話，而不是點一下螢幕。"},{"en":"When technology changes, an activity may no longer imply the same cost or effort.","zh":"當科技改變，一項活動未必再意味相同成本或努力。"},{"en":"This phrase explains what an activity formerly involved.","zh":"這個短語解釋某活動以往涉及甚麼。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":10},{"front":"concert tickets","meaning":"音樂會門票","examples":[{"en":"People once had to pay for concert tickets to hear music.","zh":"人們曾經必須購買音樂會門票才能聽音樂。"},{"en":"Concert tickets are passes people buy to attend live music performances.","zh":"音樂會門票是人們購買用來入場觀看現場音樂表演的票。"},{"en":"A family may save money for concert tickets to see a favourite singer.","zh":"家庭可能儲錢買音樂會門票去看喜歡的歌手。"},{"en":"If music requires concert tickets, poorer people may hear less live music.","zh":"如果聽音樂需要音樂會門票，較貧窮人士可能較少接觸現場音樂。"},{"en":"This phrase refers to paid access to music events.","zh":"這個短語指音樂活動的付費入場權。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":10},{"front":"the invention of the radio","meaning":"收音機的發明","examples":[{"en":"The invention of the radio made music accessible to everyone.","zh":"收音機的發明令人人都能接觸音樂。"},{"en":"The invention of the radio refers to the creation of technology that could broadcast sound widely.","zh":"收音機的發明指能廣泛廣播聲音的科技被創造出來。"},{"en":"Radio allowed people to hear news and music without attending live events.","zh":"收音機讓人們不必出席現場活動也能聽新聞和音樂。"},{"en":"This invention reduced the cost of entertainment for ordinary households.","zh":"這項發明降低了普通家庭的娛樂成本。"},{"en":"This phrase names a technological change with social effects.","zh":"這個短語命名一項具有社會影響的科技變化。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":10},{"front":"accessible to everyone","meaning":"人人都能接觸到","examples":[{"en":"Radio made music accessible to everyone.","zh":"收音機令人人都能接觸到音樂。"},{"en":"Accessible to everyone means available and usable by all kinds of people.","zh":"人人都能接觸到，是指各類人都可以取得和使用。"},{"en":"Public parks make outdoor exercise accessible to everyone, not only gym members.","zh":"公園令戶外運動人人都能接觸到，而不只是健身室會員。"},{"en":"When prices fall, cultural goods can become accessible to lower-income families.","zh":"當價格下降，文化商品可以變得讓低收入家庭也能接觸。"},{"en":"This phrase stresses broad access.","zh":"這個短語強調廣泛可及。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":10},{"front":"virtually free","meaning":"幾乎免費","examples":[{"en":"Radio made music virtually free.","zh":"收音機令音樂幾乎免費。"},{"en":"Virtually free means almost free, with little or no extra cost.","zh":"幾乎免費，是指幾乎不用額外成本。"},{"en":"Public Wi-Fi can make online learning virtually free for students with devices.","zh":"公共 Wi-Fi 可以令有設備的學生幾乎免費進行網上學習。"},{"en":"When entertainment becomes virtually free, income matters less for access.","zh":"當娛樂變得幾乎免費，收入對接觸機會的影響較小。"},{"en":"This phrase means not completely free in every sense, but very close.","zh":"這個短語不是指在所有意義上完全免費，而是非常接近免費。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":10},{"front":"compact discs","meaning":"鐳射唱片","examples":[{"en":"Compact discs widened the choice of home entertainment.","zh":"鐳射唱片擴闊了家庭娛樂選擇。"},{"en":"Compact discs are discs used to store and play music or data digitally.","zh":"鐳射唱片是用來數碼儲存和播放音樂或資料的光碟。"},{"en":"Before streaming, many families bought compact discs to listen to music at home.","zh":"在串流之前，許多家庭購買鐳射唱片在家聽音樂。"},{"en":"CDs let listeners replay music without attending expensive live performances.","zh":"CD 讓聽眾不必出席昂貴現場演出也能重播音樂。"},{"en":"This phrase refers to one technology that expanded entertainment choice.","zh":"這個短語指擴大娛樂選擇的一種科技。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":10},{"front":"paraphernalia","meaning":"相關設備；用品","examples":[{"en":"Videos and other paraphernalia widened the choice even further.","zh":"影片和其他相關設備進一步擴闊了選擇。"},{"en":"Paraphernalia means related equipment, objects, or accessories used for an activity.","zh":"相關設備或用品，是指某活動所用的相關器材、物件或配件。"},{"en":"A photographer’s paraphernalia may include lenses, lights, memory cards, and tripods.","zh":"攝影師的相關設備可能包括鏡頭、燈、記憶卡和三腳架。"},{"en":"Entertainment paraphernalia can create more ways to enjoy music or films at home.","zh":"娛樂相關設備可以創造更多在家享受音樂或電影的方式。"},{"en":"This word often refers to extra items surrounding a main activity.","zh":"這個詞常指圍繞主要活動的額外物品。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":10},{"front":"widen the choice","meaning":"擴闊選擇","examples":[{"en":"Technology has widened the choice of leisure activities.","zh":"科技擴闊了休閒活動的選擇。"},{"en":"To widen the choice means to increase the number or range of options.","zh":"擴闊選擇，是指增加選項的數量或範圍。"},{"en":"Online courses widen the choice of subjects for students in small towns.","zh":"網上課程擴闊了小鎮學生的科目選擇。"},{"en":"Wider choice can make leisure more personal and more accessible.","zh":"更廣泛選擇可以令休閒更個人化、更易接觸。"},{"en":"This phrase describes expanding available options.","zh":"這個短語描述擴大可用選項。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":10},{"front":"even further","meaning":"更進一步","examples":[{"en":"New technology widened the choice even further.","zh":"新科技更進一步擴闊了選擇。"},{"en":"Even further means to an even greater degree than before.","zh":"更進一步，是指程度比之前更大。"},{"en":"Extra practice can improve writing, and feedback can improve it even further.","zh":"額外練習可以改善寫作，而回饋可以更進一步改善它。"},{"en":"This phrase adds another step beyond an existing increase.","zh":"這個短語在已有增加之外再加入一步。"},{"en":"It emphasises that change did not stop at the first improvement.","zh":"它強調改變沒有停在第一次改善。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":10},{"front":"at a time when","meaning":"在……的時候","examples":[{"en":"At a time when economists blame technology, Ms Costa gives another view.","zh":"在經濟學家指責科技的時候，Costa 女士提出另一種看法。"},{"en":"At a time when means during a period in which something is happening.","zh":"在……的時候，是指在某事正在發生的時期。"},{"en":"At a time when students feel stressed, clear guidance becomes especially important.","zh":"在學生感到壓力的時候，清晰指引變得尤其重要。"},{"en":"This phrase connects an argument with its wider historical or social context.","zh":"這個短語把論點與更廣泛的歷史或社會背景連接起來。"},{"en":"It helps show why a point is timely or surprising.","zh":"它幫助顯示某觀點為何及時或令人意外。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":10},{"front":"point accusing fingers at","meaning":"指責","examples":[{"en":"Many economists point accusing fingers at technology.","zh":"許多經濟學家指責科技。"},{"en":"To point accusing fingers at someone or something means to blame them.","zh":"指責某人或某事，是指把責任歸咎於他們。"},{"en":"After a project fails, team members may point accusing fingers at poor leadership.","zh":"項目失敗後，團隊成員可能指責領導不善。"},{"en":"Blame can be too simple if one factor is blamed for a complex problem.","zh":"如果把複雜問題只歸咎於一個因素，責怪可能過於簡單。"},{"en":"This phrase has a strong critical tone.","zh":"這個短語語氣帶強烈批評。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":11},{"front":"widening inequality","meaning":"不斷擴大的不平等","examples":[{"en":"Technology is often blamed for widening inequality in wages.","zh":"科技常被指造成工資上不斷擴大的不平等。"},{"en":"Widening inequality means the gap between groups is becoming larger.","zh":"不斷擴大的不平等，是指群體之間的差距變得更大。"},{"en":"If rich schools gain more resources while poor schools lose them, inequality widens.","zh":"如果富裕學校獲得更多資源，而貧困學校失去資源，不平等就會擴大。"},{"en":"Technology may widen wage inequality if skilled workers benefit more than others.","zh":"如果技術工人受惠更多，科技可能擴大工資不平等。"},{"en":"This phrase describes a growing gap, not a fixed difference.","zh":"這個短語描述正在增長的差距，而不是固定差異。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":11},{"front":"skilled and unskilled workers","meaning":"技術工人與非技術工人","examples":[{"en":"Technology may widen the wage gap between skilled and unskilled workers.","zh":"科技可能擴大技術工人與非技術工人之間的工資差距。"},{"en":"Skilled and unskilled workers are workers with different levels of training or specialised ability.","zh":"技術工人與非技術工人，是指訓練或專門能力水平不同的工人。"},{"en":"A skilled worker may repair machines, while an unskilled worker may do simpler manual tasks.","zh":"技術工人可能維修機器，而非技術工人可能做較簡單體力工作。"},{"en":"If technology rewards advanced skills, unskilled workers may fall behind in wages.","zh":"如果科技獎勵高階技能，非技術工人工資可能落後。"},{"en":"This phrase compares workers by skill level, not human value.","zh":"這個短語按技能水平比較工人，而不是人的價值。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":11},{"front":"give something an egalitarian face","meaning":"令……呈現較平等的一面","examples":[{"en":"Ms Costa’s research gives technology a more egalitarian face.","zh":"Costa 女士的研究令科技呈現較平等的一面。"},{"en":"To give something an egalitarian face means to show its more equalising or fairness-promoting side.","zh":"令某物呈現較平等的一面，是指顯示它促進平等或公平的一面。"},{"en":"Online classes can give technology an egalitarian face if rural students gain access to good teachers.","zh":"如果鄉村學生能接觸好老師，網課可以令科技呈現較平等的一面。"},{"en":"A tool blamed for inequality may also reduce inequality in another area.","zh":"一種被指造成不平等的工具，也可能在另一範疇減少不平等。"},{"en":"This phrase presents a more positive and equalising image.","zh":"這個短語呈現較正面和促進平等的形象。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":11},{"front":"egalitarian","meaning":"平等主義的；促進平等的","examples":[{"en":"Technology can have an egalitarian effect on leisure.","zh":"科技可以對休閒產生促進平等的影響。"},{"en":"Egalitarian means supporting greater equality between people.","zh":"平等主義的，是指支持人與人之間更大平等。"},{"en":"Free public education is an egalitarian idea because it gives all children a chance to learn.","zh":"免費公共教育是一個平等主義想法，因為它給所有孩子學習機會。"},{"en":"Cheap entertainment can be egalitarian when it lets poorer families enjoy culture too.","zh":"當便宜娛樂讓較貧窮家庭也享受文化時，它就有促進平等的作用。"},{"en":"This word describes something that reduces privilege or widens access.","zh":"這個詞描述減少特權或擴大接觸機會的事物。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":11},{"front":"afford amusement","meaning":"負擔得起娛樂","examples":[{"en":"High earners have always been able to afford amusement.","zh":"高收入者一直都能負擔得起娛樂。"},{"en":"To afford amusement means to have enough money to pay for entertainment.","zh":"負擔得起娛樂，是指有足夠金錢支付娛樂。"},{"en":"A family may not afford amusement if rent and food use nearly all income.","zh":"如果租金和食物幾乎用盡收入，家庭可能負擔不起娛樂。"},{"en":"When prices fall, more people can afford amusement without becoming rich.","zh":"當價格下降，更多人不必變富也能負擔娛樂。"},{"en":"This phrase links entertainment with ability to pay.","zh":"這個短語把娛樂與支付能力連接起來。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":11},{"front":"lower the price of entertainment","meaning":"降低娛樂價格","examples":[{"en":"Technology has lowered the price of entertainment.","zh":"科技降低了娛樂價格。"},{"en":"To lower the price of entertainment means to make films, music, games, or shows cheaper.","zh":"降低娛樂價格，是指令電影、音樂、遊戲或表演更便宜。"},{"en":"Streaming lowered the price of watching many films at home.","zh":"串流降低了在家觀看許多電影的價格。"},{"en":"Lower prices allow entertainment to reach people beyond high-income groups.","zh":"較低價格讓娛樂接觸到高收入群體以外的人。"},{"en":"This phrase describes cost reduction in leisure.","zh":"這個短語描述休閒方面的成本下降。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":11},{"front":"improve the standard of living","meaning":"提高生活水平","examples":[{"en":"Cheap entertainment has improved the standard of living of poorer people.","zh":"便宜娛樂提高了較貧窮人士的生活水平。"},{"en":"To improve the standard of living means to make daily life more comfortable or satisfying.","zh":"提高生活水平，是指令日常生活更舒適或更令人滿意。"},{"en":"Clean water, safe housing, and affordable transport improve living standards.","zh":"清潔食水、安全住所和可負擔交通能提高生活水平。"},{"en":"Entertainment can improve life because people need rest and pleasure, not only food.","zh":"娛樂可以改善生活，因為人們需要休息和樂趣，而不只是食物。"},{"en":"This phrase refers to better quality of life.","zh":"這個短語指生活質素改善。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":11},{"front":"at the lower end of","meaning":"在……的較低端","examples":[{"en":"Technology benefits those at the lower end of the income distribution.","zh":"科技令收入分布較低端的人受益。"},{"en":"At the lower end of something means among the lowest levels in a range.","zh":"在某範圍的較低端，是指處於該範圍中最低水平附近。"},{"en":"Students at the lower end of the score range may need extra support.","zh":"分數較低端的學生可能需要額外支援。"},{"en":"If benefits reach people at the lower end, inequality may become less severe.","zh":"如果好處到達較低端人士，不平等可能變得較不嚴重。"},{"en":"This phrase identifies the less advantaged part of a scale.","zh":"這個短語指出尺度中較弱勢的一端。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":11},{"front":"income distribution","meaning":"收入分布","examples":[{"en":"The lower end of the income distribution has gained from cheaper leisure.","zh":"收入分布較低端的人從較便宜休閒中得益。"},{"en":"Income distribution means how income is spread across people from low to high earners.","zh":"收入分布是指收入如何在低收入者至高收入者之間分布。"},{"en":"Economists study income distribution to see whether growth benefits everyone.","zh":"經濟學家研究收入分布，以了解增長是否惠及所有人。"},{"en":"Cheaper leisure can help people at the lower end of the distribution enjoy more.","zh":"較便宜休閒可以幫助收入分布較低端的人享受更多。"},{"en":"This phrase describes the pattern of earnings across society.","zh":"這個短語描述社會中的收入模式。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":11},{"front":"the implication of her results","meaning":"她的研究結果所暗示的意思","examples":[{"en":"The implication of her results is that leisure reduces measured inequality.","zh":"她的研究結果所暗示的意思是休閒減少了被量度的不平等。"},{"en":"The implication of results means the conclusion or meaning suggested by the findings.","zh":"研究結果的啟示，是指發現所暗示的結論或意義。"},{"en":"If students improve after group work, the implication is that discussion may help learning.","zh":"如果學生在小組活動後進步，啟示就是討論可能有助學習。"},{"en":"Implications are not always stated directly; readers must interpret them carefully.","zh":"啟示不一定直接說出；讀者必須小心解讀。"},{"en":"This phrase connects research findings with their broader meaning.","zh":"這個短語把研究發現與更廣泛意義連接起來。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":11},{"front":"take something into account","meaning":"將……考慮在內","examples":[{"en":"Once recreation is taken into account, living-standard gaps may look smaller.","zh":"一旦將消閒考慮在內，生活水平差距可能看起來較小。"},{"en":"To take something into account means to include it when judging or calculating something.","zh":"將某事考慮在內，是指在判斷或計算時包括它。"},{"en":"A teacher should take effort into account, not only test scores.","zh":"老師應將努力考慮在內，而不只是看測驗分數。"},{"en":"Including an extra factor can change the conclusion.","zh":"包括額外因素可以改變結論。"},{"en":"This phrase means not ignoring relevant information.","zh":"這個短語意思是不忽略相關資料。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":12},{"front":"after all","meaning":"畢竟；終究","examples":[{"en":"The differences may not have widened so much after all.","zh":"差距畢竟可能沒有擴大那麼多。"},{"en":"After all means despite what was first thought, the final judgement may be different.","zh":"畢竟是指儘管起初以為如此，最終判斷可能不同。"},{"en":"The trip looked too expensive, but after all the discounts, it was affordable after all.","zh":"旅行起初看似太貴，但折扣後畢竟可以負擔。"},{"en":"This phrase often revises an earlier assumption.","zh":"這個短語常修正早前假設。"},{"en":"It can express surprise or reconsideration.","zh":"它可以表達驚訝或重新考慮。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":12},{"front":"findings are not watertight","meaning":"研究結果並非無懈可擊","examples":[{"en":"These findings are not watertight.","zh":"這些研究結果並非無懈可擊。"},{"en":"Findings are not watertight means the evidence is useful but not completely free from weakness.","zh":"研究結果並非無懈可擊，是指證據有用，但並非完全沒有弱點。"},{"en":"A survey with too few students may suggest a pattern, but the findings are not watertight.","zh":"樣本太少的學生調查可能顯示某模式，但結果並非無懈可擊。"},{"en":"Weaknesses in data classification can make conclusions less certain.","zh":"數據分類的弱點會令結論較不確定。"},{"en":"This phrase gives cautious criticism of research evidence.","zh":"這個短語對研究證據作出謹慎批評。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":12},{"front":"depend heavily upon","meaning":"很大程度上取決於","examples":[{"en":"Ms Costa’s results depend heavily upon how spending is classified.","zh":"Costa 女士的結果很大程度上取決於開支如何分類。"},{"en":"To depend heavily upon something means to be strongly affected or determined by it.","zh":"很大程度上取決於某事，是指強烈受它影響或由它決定。"},{"en":"A school’s ranking may depend heavily upon exam scores.","zh":"學校排名可能很大程度上取決於考試成績。"},{"en":"If results depend heavily on classification, small category changes can affect conclusions.","zh":"如果結果很大程度上取決於分類，細小類別改變也會影響結論。"},{"en":"This phrase shows strong reliance on one factor.","zh":"這個短語顯示對某因素的強烈依賴。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":12},{"front":"be classed as","meaning":"被歸類為","examples":[{"en":"The results depend on what is classed as recreational expenditure.","zh":"結果取決於甚麼被歸類為消閒開支。"},{"en":"To be classed as something means to be placed into that category.","zh":"被歸類為某物，是指被放入該類別。"},{"en":"A library book may be classed as education rather than entertainment.","zh":"圖書館書籍可能被歸類為教育，而不是娛樂。"},{"en":"Classification matters because it changes how spending is counted.","zh":"分類很重要，因為它會改變開支如何計算。"},{"en":"This phrase describes categorising data.","zh":"這個短語描述數據分類。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":12},{"front":"recreational expenditure","meaning":"消閒開支","examples":[{"en":"Books may be counted as recreational expenditure.","zh":"書籍可能被計算為消閒開支。"},{"en":"Recreational expenditure means money spent on leisure or enjoyment.","zh":"消閒開支是花在休閒或享樂上的金錢。"},{"en":"A family’s recreational expenditure may include sports, streaming, books, and holidays.","zh":"家庭消閒開支可能包括運動、串流、書籍和假期。"},{"en":"If textbooks are counted as recreation, leisure spending may appear too high.","zh":"如果教科書被算作消閒，休閒開支可能看起來過高。"},{"en":"This phrase is a formal version of leisure spending.","zh":"這個短語是 leisure spending 的正式說法。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":12},{"front":"accounting for one-quarter of","meaning":"佔……四分之一","examples":[{"en":"Reading accounted for one-quarter of all recreational spending in 1888.","zh":"閱讀在 1888 年佔所有消閒開支的四分之一。"},{"en":"Accounting for one-quarter of something means making up 25% of the total.","zh":"佔某物四分之一，是指構成總數的 25%。"},{"en":"Rent may account for one-quarter of a family’s monthly budget.","zh":"租金可能佔家庭每月預算的四分之一。"},{"en":"A large share shows that the category is important in the total.","zh":"很大比例顯示該類別在總數中重要。"},{"en":"This phrase describes proportion within a whole.","zh":"這個短語描述整體中的比例。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":12},{"front":"recreational spending","meaning":"消閒開支","examples":[{"en":"Reading once made up a large share of recreational spending.","zh":"閱讀曾佔消閒開支很大比例。"},{"en":"Recreational spending is money used for leisure activities and entertainment.","zh":"消閒開支是用於休閒活動和娛樂的金錢。"},{"en":"A student’s recreational spending may include games, films, snacks, and books.","zh":"學生的消閒開支可能包括遊戲、電影、小食和書籍。"},{"en":"Changes in recreational spending can show how lifestyles change over time.","zh":"消閒開支變化可以顯示生活方式如何隨時間改變。"},{"en":"This phrase is useful in household-budget analysis.","zh":"這個短語適合用於家庭預算分析。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":12},{"front":"the entertainment dollar","meaning":"娛樂開支","examples":[{"en":"Reading took only 16% of the entertainment dollar in 1991.","zh":"閱讀在 1991 年只佔娛樂開支的 16%。"},{"en":"The entertainment dollar means the total money spent on entertainment, imagined as one whole dollar.","zh":"娛樂開支是指花在娛樂上的總金額，可想像成一整美元來看比例。"},{"en":"If streaming takes 40 cents of the entertainment dollar, it takes a large share of leisure spending.","zh":"如果串流佔娛樂開支中的 40 美分，它就佔休閒開支很大比例。"},{"en":"This phrase helps show how entertainment spending is divided among categories.","zh":"這個短語幫助顯示娛樂開支如何在不同類別中分配。"},{"en":"It is a simple way to discuss percentages of leisure money.","zh":"它是討論休閒金錢百分比的簡單方式。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":12},{"front":"expenditure surveys","meaning":"開支調查","examples":[{"en":"The Department of Labour’s expenditure surveys classify books as recreational expenses.","zh":"勞工部的開支調查把書籍歸類為消閒開支。"},{"en":"Expenditure surveys are studies that record how people spend money.","zh":"開支調查是記錄人們如何花錢的研究。"},{"en":"An expenditure survey may ask households about food, rent, education, and leisure costs.","zh":"開支調查可能詢問家庭食物、租金、教育和休閒成本。"},{"en":"These surveys depend on categories, so classification choices affect results.","zh":"這些調查依靠分類，因此分類選擇會影響結果。"},{"en":"This phrase refers to data collection about spending.","zh":"這個短語指關於開支的數據收集。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":12},{"front":"distinguish between","meaning":"區分","examples":[{"en":"The surveys do not distinguish between textbooks and novels.","zh":"這些調查沒有區分教科書和小說。"},{"en":"To distinguish between two things means to recognise and separate their differences.","zh":"區分兩件事，是指認出並分開它們的差異。"},{"en":"Students must distinguish between fact and opinion in reading tests.","zh":"學生在閱讀測驗中必須區分事實和意見。"},{"en":"If surveys fail to distinguish between categories, results may be misleading.","zh":"如果調查未能區分類別，結果可能具誤導性。"},{"en":"This phrase is used when two similar items must be separated clearly.","zh":"當兩個相似項目需要清楚分開時，可以使用這個短語。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":12},{"front":"mathematics tome","meaning":"數學巨著；厚重數學書","examples":[{"en":"A mathematics tome may be classified in the same way as a novel.","zh":"一本數學巨著可能與小說以同樣方式被分類。"},{"en":"A mathematics tome is a very large, serious, or difficult mathematics book.","zh":"數學巨著是一本非常厚重、嚴肅或困難的數學書。"},{"en":"A university student may buy a mathematics tome for an advanced course.","zh":"大學生可能為高階課程購買一本數學巨著。"},{"en":"Counting such a book as leisure may overstate recreational reading.","zh":"把這類書算作休閒，可能高估消閒閱讀。"},{"en":"This phrase contrasts academic books with light entertainment.","zh":"這個短語把學術書籍與輕鬆娛樂作對比。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":13},{"front":"best-selling novel","meaning":"暢銷小說","examples":[{"en":"A best-selling novel is classified as recreational expenditure.","zh":"暢銷小說被歸類為消閒開支。"},{"en":"A best-selling novel is a fiction book that sells very many copies.","zh":"暢銷小說是銷量很高的小說書籍。"},{"en":"A commuter may read a best-selling novel on the train for relaxation.","zh":"通勤者可能在火車上閱讀暢銷小說來放鬆。"},{"en":"Unlike a textbook, a novel clearly fits ordinary leisure reading.","zh":"與教科書不同，小說明顯屬於普通休閒閱讀。"},{"en":"This phrase refers to popular fiction.","zh":"這個短語指受歡迎的小說作品。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":13},{"front":"be classified as","meaning":"被歸類為","examples":[{"en":"Both textbooks and novels are classified as recreational expenses.","zh":"教科書和小說都被歸類為消閒開支。"},{"en":"To be classified as something means to be officially put into that category.","zh":"被歸類為某物，是指被正式放入該類別。"},{"en":"A school trip may be classified as education rather than leisure.","zh":"學校旅行可能被歸類為教育，而不是休閒。"},{"en":"Classification affects statistics because it changes what each category includes.","zh":"分類會影響統計，因為它改變每個類別包含甚麼。"},{"en":"This phrase describes how data or items are labelled.","zh":"這個短語描述數據或物品如何被標籤。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":13},{"front":"professional books","meaning":"專業書籍","examples":[{"en":"Professional books may make recreational spending appear higher.","zh":"專業書籍可能令消閒開支看起來較高。"},{"en":"Professional books are books used for work, training, or specialist knowledge.","zh":"專業書籍是用於工作、培訓或專門知識的書。"},{"en":"A nurse may buy professional books about patient care and medication.","zh":"護士可能購買關於病人照顧和藥物的專業書籍。"},{"en":"If professional books are counted as leisure, the data may exaggerate recreation.","zh":"如果專業書籍被算作休閒，數據可能誇大消閒。"},{"en":"This phrase contrasts work-related reading with entertainment reading.","zh":"這個短語把工作相關閱讀與娛樂閱讀作對比。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":13},{"front":"make something appear stronger than it really is","meaning":"令……看起來比實際更強","examples":[{"en":"Textbook spending could make recreational spending appear stronger than it really is.","zh":"教科書開支可能令消閒開支看起來比實際更強。"},{"en":"To make something appear stronger than it really is means to exaggerate its size, effect, or importance.","zh":"令某事看起來比實際更強，是指誇大其大小、影響或重要性。"},{"en":"A few very high scores can make a class average appear stronger than it really is.","zh":"少數很高分可以令班級平均分看起來比實際更強。"},{"en":"Misclassification can make a trend look bigger than the true leisure pattern.","zh":"錯誤分類可以令趨勢看起來比真實休閒模式更大。"},{"en":"This phrase warns that data can create a misleading impression.","zh":"這個短語提醒人，數據可能造成誤導印象。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":13},{"front":"address this problem","meaning":"處理這個問題","examples":[{"en":"Ms Costa tries to address this problem in her analysis.","zh":"Costa 女士嘗試在分析中處理這個問題。"},{"en":"To address this problem means to deal with it directly and try to reduce its effect.","zh":"處理這個問題，是指直接面對並嘗試減少其影響。"},{"en":"A school may address bullying by setting clear rules and support channels.","zh":"學校可能透過制定清晰規則和支援渠道來處理欺凌問題。"},{"en":"Researchers address data problems by testing whether results change under different assumptions.","zh":"研究人員透過測試不同假設下結果是否改變來處理數據問題。"},{"en":"This phrase means more than mentioning a problem; it means trying to handle it.","zh":"這個短語不只是提及問題，而是嘗試應對它。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":13},{"front":"results still hold","meaning":"結果仍然成立","examples":[{"en":"Her results still hold when some categories are removed.","zh":"當某些類別被剔除時，她的結果仍然成立。"},{"en":"Results still hold means the findings remain true or convincing after a change or test.","zh":"結果仍然成立，是指在改變或檢查後，發現仍然真確或有說服力。"},{"en":"A grammar rule still holds even when a few unusual examples are removed.","zh":"即使剔除少數不尋常例子，文法規則仍然成立。"},{"en":"If results hold under different checks, the conclusion becomes more reliable.","zh":"如果結果在不同檢查下仍成立，結論就更可靠。"},{"en":"This phrase shows robustness in research.","zh":"這個短語顯示研究的穩健性。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":13},{"front":"tricky categories","meaning":"棘手類別","examples":[{"en":"Books are tricky categories in leisure-spending research.","zh":"書籍在休閒開支研究中是棘手類別。"},{"en":"Tricky categories are groups that are difficult to classify clearly.","zh":"棘手類別是難以清楚分類的組別。"},{"en":"A computer bought for both school and games can be a tricky category in spending data.","zh":"一部既用於學校又用於遊戲的電腦，在開支數據中可以是棘手類別。"},{"en":"Tricky categories can make survey results harder to interpret.","zh":"棘手類別會令調查結果較難解讀。"},{"en":"This phrase describes classification problems.","zh":"這個短語描述分類問題。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":13},{"front":"be removed from the sample","meaning":"從樣本中剔除","examples":[{"en":"Tricky categories can be removed from the sample.","zh":"棘手類別可以從樣本中剔除。"},{"en":"To be removed from the sample means to be taken out of the data being analysed.","zh":"從樣本中剔除，是指從正在分析的數據中移除。"},{"en":"A researcher may remove incomplete surveys from the sample before calculating results.","zh":"研究人員可能在計算結果前，把不完整問卷從樣本中剔除。"},{"en":"Removing doubtful cases can test whether the conclusion depends on them.","zh":"剔除可疑個案可以測試結論是否依賴它們。"},{"en":"This phrase describes a research-cleaning step.","zh":"這個短語描述研究中的數據清理步驟。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":13},{"front":"not entirely eliminated","meaning":"未被完全消除","examples":[{"en":"The difficulty is not entirely eliminated.","zh":"這個困難未被完全消除。"},{"en":"Not entirely eliminated means not completely removed or solved.","zh":"未被完全消除，是指沒有完全移除或解決。"},{"en":"Online lessons reduce travel time, but technical problems are not entirely eliminated.","zh":"網課減少交通時間，但技術問題未被完全消除。"},{"en":"A correction may improve data without removing every weakness.","zh":"修正可以改善數據，但未必移除所有弱點。"},{"en":"This phrase gives cautious limitation.","zh":"這個短語提出謹慎限制。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":13},{"front":"nonetheless","meaning":"儘管如此","examples":[{"en":"Nonetheless, her broad conclusion seems fair.","zh":"儘管如此，她的整體結論看來合理。"},{"en":"Nonetheless means despite what has just been said.","zh":"儘管如此，是指雖然剛才有那個情況。"},{"en":"The study has some weaknesses; nonetheless, its main idea is useful.","zh":"研究有一些弱點；儘管如此，其主要想法仍有用。"},{"en":"This word helps a writer admit a problem while keeping a conclusion.","zh":"這個詞幫助作者承認問題，同時保留結論。"},{"en":"It is a formal way to say “even so.”","zh":"它是 “even so” 的正式說法。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":13},{"front":"broad conclusion","meaning":"整體結論","examples":[{"en":"Ms Costa’s broad conclusion is that leisure is more widely available.","zh":"Costa 女士的整體結論是休閒更廣泛可得。"},{"en":"A broad conclusion is the main general judgement drawn from evidence.","zh":"整體結論是從證據得出的主要一般判斷。"},{"en":"After many interviews, a teacher’s broad conclusion may be that students need clearer feedback.","zh":"多次訪問後，老師的整體結論可能是學生需要更清晰回饋。"},{"en":"Broad conclusions summarise the overall pattern rather than every detail.","zh":"整體結論概括總體模式，而不是每個細節。"},{"en":"This phrase refers to the big takeaway from research.","zh":"這個短語指研究中的大重點。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":14},{"front":"seem fair","meaning":"看來合理","examples":[{"en":"Her broad conclusion seems fair.","zh":"她的整體結論看來合理。"},{"en":"Seem fair means appear reasonable, balanced, or acceptable based on the evidence.","zh":"看來合理，是指根據證據顯得合理、平衡或可接受。"},{"en":"A teacher’s decision seems fair if all students follow the same rules.","zh":"如果所有學生遵守同樣規則，老師的決定就看來合理。"},{"en":"A conclusion can seem fair even when the data is not perfect.","zh":"即使數據不完美，結論仍可以看來合理。"},{"en":"This phrase gives cautious approval.","zh":"這個短語給出謹慎認同。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":14},{"front":"available to all","meaning":"人人都更容易獲得","examples":[{"en":"Recreation is more available to all than before.","zh":"消閒比以前更人人都容易獲得。"},{"en":"Available to all means accessible to everyone, not only a privileged group.","zh":"人人都能獲得，是指所有人都能接觸，而不只是特權群體。"},{"en":"Free public libraries make reading available to all.","zh":"免費公共圖書館令閱讀人人都能接觸。"},{"en":"When recreation is available to all, income matters less for enjoyment.","zh":"當消閒人人可得，收入對享受的影響較小。"},{"en":"This phrase stresses equal access.","zh":"這個短語強調平等接觸。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":14},{"front":"less dependent on income","meaning":"較少依賴收入","examples":[{"en":"Recreation is less dependent on income than it used to be.","zh":"消閒比以往較少依賴收入。"},{"en":"Less dependent on income means money matters less than before for access or enjoyment.","zh":"較少依賴收入，是指接觸或享受某事比以前較少取決於金錢。"},{"en":"Online videos make some entertainment less dependent on family income.","zh":"網上影片令某些娛樂較少依賴家庭收入。"},{"en":"If leisure is less income-dependent, poorer people can enjoy more similar options.","zh":"如果休閒較少依賴收入，較貧窮人士可以享受更相似選項。"},{"en":"This phrase describes reduced reliance on earnings.","zh":"這個短語描述對收入依賴減少。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":14},{"front":"on this measure","meaning":"以這個標準衡量","examples":[{"en":"On this measure, inequality of living standards has fallen.","zh":"以這個標準衡量，生活水平不平等已下降。"},{"en":"On this measure means judged according to this particular standard or method.","zh":"以這個標準衡量，是指根據這個特定標準或方法判斷。"},{"en":"On test scores, the class improved; on confidence, progress was slower.","zh":"以測驗分數衡量，班級有進步；以信心衡量，進步較慢。"},{"en":"A conclusion may change when a different measure is used.","zh":"使用不同量度方法時，結論可能改變。"},{"en":"This phrase reminds readers that the result depends on the chosen measure.","zh":"這個短語提醒讀者，結果取決於所選標準。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":14},{"front":"inequality of living standards","meaning":"生活水平不平等","examples":[{"en":"Inequality of living standards has fallen when leisure is considered.","zh":"當休閒被考慮在內，生活水平不平等已下降。"},{"en":"Inequality of living standards means differences in people’s quality of life.","zh":"生活水平不平等是指人們生活質素上的差異。"},{"en":"Two families may have unequal living standards if one has safe housing and free time while the other does not.","zh":"如果一個家庭有安全住所和自由時間，另一個沒有，兩者生活水平可能不平等。"},{"en":"Leisure can reduce measured inequality if more people can enjoy similar activities.","zh":"如果更多人能享受相似活動，休閒可以降低被量度的不平等。"},{"en":"This phrase looks beyond income to actual life conditions.","zh":"這個短語超越收入，關注實際生活條件。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":14},{"front":"choose the most suitable heading","meaning":"選出最合適的標題","examples":[{"en":"Students must choose the most suitable heading for each paragraph.","zh":"學生必須為每段選出最合適的標題。"},{"en":"To choose the most suitable heading means to select the title that best matches the paragraph’s main idea.","zh":"選出最合適的標題，是指選擇最符合段落主旨的標題。"},{"en":"In reading tests, students should ignore small details when choosing headings.","zh":"在閱讀測驗中，學生選標題時應忽略小細節。"},{"en":"A suitable heading covers the whole paragraph, not only one example.","zh":"合適標題涵蓋整段，而不只是其中一個例子。"},{"en":"This phrase is common in IELTS reading tasks.","zh":"這個短語常見於 IELTS 閱讀題。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":14},{"front":"write the appropriate numbers","meaning":"寫上適當的編號","examples":[{"en":"Students write the appropriate numbers in the answer boxes.","zh":"學生在答案框中寫上適當的編號。"},{"en":"To write the appropriate numbers means to record the correct option numbers as answers.","zh":"寫上適當的編號，是指把正確選項編號記作答案。"},{"en":"A student may write iii beside a paragraph if heading iii fits best.","zh":"如果標題 iii 最合適，學生可能在某段旁寫 iii。"},{"en":"Even if the idea is understood, writing the wrong number can lose marks.","zh":"即使理解意思，寫錯編號也可能失分。"},{"en":"This phrase describes the required exam-answer format.","zh":"這個短語描述考試所需答案格式。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":14},{"front":"wide differences in","meaning":"……方面的巨大差異","examples":[{"en":"The heading refers to wide differences in leisure activities.","zh":"該標題指消閒活動方面的巨大差異。"},{"en":"Wide differences in something are large variations between people, groups, or places.","zh":"某方面的巨大差異，是指人、群體或地方之間的大變化。"},{"en":"There may be wide differences in homework time between primary and secondary students.","zh":"小學生和中學生之間在功課時間方面可能有巨大差異。"},{"en":"Wide differences can reveal inequality or different access to resources.","zh":"巨大差異可以揭示不平等或資源接觸不同。"},{"en":"This phrase highlights large variation.","zh":"這個短語突出巨大變化。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":14},{"front":"according to income","meaning":"按收入而定","examples":[{"en":"Leisure activities once differed widely according to income.","zh":"消閒活動曾經按收入而有巨大差異。"},{"en":"According to income means depending on how much money people earn.","zh":"按收入而定，是指取決於人們賺多少錢。"},{"en":"Access to private tutoring may differ according to family income.","zh":"私人補習接觸機會可能按家庭收入而不同。"},{"en":"If leisure differs according to income, richer people can enjoy more options.","zh":"如果休閒按收入而不同，較富裕人士可以享受更多選項。"},{"en":"This phrase connects differences to earnings.","zh":"這個短語把差異與收入連接起來。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":14},{"front":"possible inconsistencies","meaning":"可能不一致之處","examples":[{"en":"The data may contain possible inconsistencies.","zh":"數據可能包含可能不一致之處。"},{"en":"Possible inconsistencies are details that may not match or may create doubt.","zh":"可能不一致之處，是指可能不相符或令人懷疑的細節。"},{"en":"A survey has possible inconsistencies if one table counts books as education and another as leisure.","zh":"如果一張表把書算作教育，另一張算作休閒，調查就有可能不一致之處。"},{"en":"Inconsistencies can weaken confidence in the results.","zh":"不一致會削弱對結果的信心。"},{"en":"This phrase introduces a careful criticism of data.","zh":"這個短語引入對數據的謹慎批評。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":14},{"front":"Ms Costa’s data","meaning":"Costa 女士的數據","examples":[{"en":"The heading questions possible inconsistencies in Ms Costa’s data.","zh":"該標題質疑 Costa 女士的數據中可能不一致之處。"},{"en":"Ms Costa’s data means the information and figures used in her research.","zh":"Costa 女士的數據，是指她研究中使用的資料和數字。"},{"en":"Researchers may question data if categories are unclear or samples are limited.","zh":"如果類別不清或樣本有限，研究人員可能質疑數據。"},{"en":"Data quality matters because weak data can lead to weak conclusions.","zh":"數據質素很重要，因為薄弱數據會導致薄弱結論。"},{"en":"This phrase refers to the evidence behind her argument.","zh":"這個短語指她論點背後的證據。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":15},{"front":"personal income and time","meaning":"個人收入和時間","examples":[{"en":"Personal income and time both influence leisure activities.","zh":"個人收入和時間都影響消閒活動。"},{"en":"Personal income and time are two resources that affect what people can do for leisure.","zh":"個人收入和時間是影響人們能做甚麼休閒活動的兩種資源。"},{"en":"A worker with money but no free evenings may still enjoy little recreation.","zh":"有錢但晚上沒有空的工人，仍可能享受很少消閒。"},{"en":"Leisure depends on both ability to pay and time available.","zh":"休閒取決於支付能力和可用時間。"},{"en":"This phrase shows that money alone does not explain leisure.","zh":"這個短語顯示金錢本身不能解釋休閒。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":15},{"front":"influence leisure activities","meaning":"影響消閒活動","examples":[{"en":"Income and time influence leisure activities.","zh":"收入和時間影響消閒活動。"},{"en":"To influence leisure activities means to affect what people do for enjoyment.","zh":"影響消閒活動，是指影響人們為享樂而做甚麼。"},{"en":"A student’s homework load can influence leisure activities after school.","zh":"學生的功課量會影響放學後的消閒活動。"},{"en":"If public facilities are cheap, they can influence people’s choice of recreation.","zh":"如果公共設施便宜，它們會影響人們的消閒選擇。"},{"en":"This phrase connects causes with leisure behaviour.","zh":"這個短語把原因與休閒行為連接起來。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":15},{"front":"investigate the problem from a new angle","meaning":"從新角度研究問題","examples":[{"en":"Ms Costa investigates the lifestyle problem from a new angle.","zh":"Costa 女士從新角度研究生活方式問題。"},{"en":"To investigate a problem from a new angle means to study it using a fresh perspective.","zh":"從新角度研究問題，是指用新視角研究它。"},{"en":"A school may investigate lateness from a new angle by looking at bus schedules.","zh":"學校可能透過查看巴士時間表，從新角度研究遲到問題。"},{"en":"New angles can reveal causes that traditional approaches miss.","zh":"新角度可以揭示傳統方法遺漏的原因。"},{"en":"This phrase describes original analysis.","zh":"這個短語描述原創分析。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":15},{"front":"fail to benefit everyone","meaning":"未能令所有人受惠","examples":[{"en":"The option suggests that increased incomes fail to benefit everyone.","zh":"該選項暗示收入增加未能令所有人受惠。"},{"en":"To fail to benefit everyone means not all people gain from a change.","zh":"未能令所有人受惠，是指不是所有人都從改變中得益。"},{"en":"A new shopping mall may fail to benefit everyone if small shops lose customers.","zh":"如果小店失去顧客，新商場可能未能令所有人受惠。"},{"en":"Economic growth can fail to benefit everyone when gains go mainly to the wealthy.","zh":"當收益主要流向富人，經濟增長可能未能令所有人受惠。"},{"en":"This phrase highlights uneven effects.","zh":"這個短語突出效果不均。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":15},{"front":"controversial development","meaning":"具爭議的發展","examples":[{"en":"Technology is presented as a controversial development.","zh":"科技被呈現為具爭議的發展。"},{"en":"A controversial development is a change that people disagree about strongly.","zh":"具爭議的發展，是指人們強烈意見不一的改變。"},{"en":"Facial-recognition cameras are a controversial development because they may improve safety but reduce privacy.","zh":"人臉識別鏡頭是具爭議的發展，因為它可能改善安全但減少私隱。"},{"en":"A development can have both benefits and harms, making debate likely.","zh":"一項發展可以同時有好處和壞處，因此容易引起爭論。"},{"en":"This phrase describes change that causes disagreement.","zh":"這個短語描述引起分歧的改變。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":15},{"front":"offer cheaper leisure activities","meaning":"提供更便宜的消閒活動","examples":[{"en":"Technology offers cheaper leisure activities to many people.","zh":"科技為許多人提供更便宜的消閒活動。"},{"en":"To offer cheaper leisure activities means to provide lower-cost ways to relax or be entertained.","zh":"提供更便宜的消閒活動，是指提供較低成本的放鬆或娛樂方式。"},{"en":"Free video platforms offer cheaper leisure activities than live shows.","zh":"免費影片平台比現場表演提供更便宜的消閒活動。"},{"en":"Cheaper leisure can reduce the gap between rich and poor households.","zh":"較便宜休閒可以縮小貧富家庭之間的差距。"},{"en":"This phrase connects technology with affordability.","zh":"這個短語把科技與可負擔性連接起來。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":15},{"front":"heighten differences","meaning":"加劇差異","examples":[{"en":"Some economists argue that technology heightens differences in living standards.","zh":"有些經濟學家認為科技加劇生活水平差異。"},{"en":"To heighten differences means to make differences larger or more noticeable.","zh":"加劇差異，是指令差異變得更大或更明顯。"},{"en":"Private tutoring can heighten differences if only wealthy students can afford it.","zh":"如果只有富裕學生能負擔私人補習，它可能加劇差異。"},{"en":"Technology may heighten wage gaps while reducing entertainment gaps.","zh":"科技可能加劇工資差距，同時減少娛樂差距。"},{"en":"This phrase means increasing inequality or contrast.","zh":"這個短語意思是增加不平等或對比。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":15},{"front":"the gap between…and…","meaning":"……與……之間的差距","examples":[{"en":"The heading discusses how the gap between income and leisure spending closes.","zh":"該標題討論收入與休閒開支之間的差距如何收窄。"},{"en":"The gap between two things is the difference or distance between them.","zh":"兩者之間的差距，是指它們之間的差別或距離。"},{"en":"The gap between strong and weak students can shrink after targeted support.","zh":"針對性支援後，強弱學生之間的差距可以縮小。"},{"en":"When the gap closes, two groups or figures become more similar.","zh":"當差距收窄，兩個群體或數字變得更相似。"},{"en":"This phrase is useful for discussing inequality.","zh":"這個短語適合用於討論不平等。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":15},{"front":"leisure spending closes","meaning":"休閒開支差距收窄","examples":[{"en":"The gap between income and leisure spending closes over time.","zh":"收入與休閒開支之間的差距隨時間收窄。"},{"en":"When a spending gap closes, differences between groups become smaller.","zh":"當開支差距收窄，群體之間的差異變小。"},{"en":"The gap in internet access may close when public libraries provide free computers.","zh":"當公共圖書館提供免費電腦，互聯網接觸差距可能收窄。"},{"en":"Leisure-spending gaps close when poorer families gain more time and cheaper options.","zh":"當較貧窮家庭得到更多時間和便宜選項，休閒開支差距會收窄。"},{"en":"This phrase describes narrowing inequality in spending.","zh":"這個短語描述開支不平等收窄。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":15},{"front":"a broader range of options","meaning":"更廣泛的選擇","examples":[{"en":"Public investment and technology have led to a broader range of options.","zh":"公共投資和科技帶來了更廣泛的選擇。"},{"en":"A broader range of options means more varied choices are available.","zh":"更廣泛的選擇，是指有更多不同種類的選項可用。"},{"en":"Online learning gives students a broader range of subjects than one small school can offer.","zh":"網上學習給學生比一間小學校能提供的更廣泛科目選擇。"},{"en":"More options can make leisure fit different incomes, tastes, and schedules.","zh":"更多選項可以令休閒配合不同收入、品味和時間表。"},{"en":"This phrase stresses variety and wider choice.","zh":"這個短語強調多樣性和更大選擇範圍。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":15},{"front":"complete each of the following statements","meaning":"完成以下每句陳述","examples":[{"en":"Students complete each of the following statements using words from the box.","zh":"學生使用方框中的詞語完成以下每句陳述。"},{"en":"To complete each statement means to fill in the missing part of every sentence.","zh":"完成每句陳述，是指填上每個句子缺失的部分。"},{"en":"In a reading test, students complete statements by matching meaning with passage information.","zh":"在閱讀測驗中，學生透過把意思與篇章資料配對來完成陳述。"},{"en":"This task checks grammar, vocabulary, and understanding together.","zh":"這項任務同時檢查文法、詞彙和理解。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":16},{"front":"words from the box","meaning":"方框中的詞語","examples":[{"en":"The answers must use words from the box.","zh":"答案必須使用方框中的詞語。"},{"en":"Words from the box are the given answer choices printed in a separate list.","zh":"方框中的詞語，是印在另一個列表中的指定答案選項。"},{"en":"Students should not invent new words if the instruction says to use words from the box.","zh":"如果指示說使用方框中的詞語，學生不應自創新詞。"},{"en":"The box limits possible answers and helps control the task.","zh":"方框限制可能答案，並幫助控制題目。"},{"en":"This phrase tells candidates where to choose answers.","zh":"這個短語告訴考生從哪裡選答案。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":16},{"front":"determine living standards","meaning":"判斷生活水平","examples":[{"en":"It is harder to determine living standards than cash incomes.","zh":"判斷生活水平比判斷現金收入更困難。"},{"en":"To determine living standards means to judge or measure people’s quality of life.","zh":"判斷生活水平，是指評估或衡量人們的生活質素。"},{"en":"A government may use housing, health, income, and leisure data to determine living standards.","zh":"政府可能使用住屋、健康、收入和休閒數據來判斷生活水平。"},{"en":"Living standards are hard to determine because they include many different factors.","zh":"生活水平難以判斷，因為它包括許多不同因素。"},{"en":"This phrase refers to assessing quality of life.","zh":"這個短語指評估生活質素。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":16},{"front":"non-luxury spending","meaning":"非奢侈品開支","examples":[{"en":"A decrease in non-luxury spending can leave more money for leisure.","zh":"非奢侈品開支減少可以留下更多錢給休閒。"},{"en":"Non-luxury spending means money spent on necessary or ordinary items rather than luxuries.","zh":"非奢侈品開支，是指花在必需或普通物品上，而非奢侈品上的金錢。"},{"en":"Rent, food, transport, and basic clothing are usually non-luxury spending.","zh":"租金、食物、交通和基本衣物通常是非奢侈品開支。"},{"en":"If non-luxury spending falls as a share of income, families can spend more on recreation.","zh":"如果非奢侈品開支佔收入比例下降，家庭就能花更多在消閒上。"},{"en":"This phrase contrasts essentials with discretionary pleasures.","zh":"這個短語把必需品與可自由選擇的享樂作對比。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":16},{"front":"a bigger investment in leisure","meaning":"對休閒作出更大投資","examples":[{"en":"Lower spending on necessities can lead to a bigger investment in leisure.","zh":"必需品開支下降可以導致對休閒作出更大投資。"},{"en":"A bigger investment in leisure means spending more time or money on recreation.","zh":"對休閒作出更大投資，是指花更多時間或金錢在消閒上。"},{"en":"A family may make a bigger investment in leisure after paying off debts.","zh":"家庭還清債務後，可能對休閒作出更大投資。"},{"en":"More leisure investment can improve life by adding rest, culture, and enjoyment.","zh":"更多休閒投資可以透過增加休息、文化和享受來改善生活。"},{"en":"This phrase treats leisure as something people put resources into.","zh":"這個短語把休閒視為人們投入資源的事物。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":16},{"front":"be directly affected by","meaning":"直接受……影響","examples":[{"en":"Leisure spending is directly affected by salaries and available time.","zh":"休閒開支直接受薪金和可用時間影響。"},{"en":"To be directly affected by something means to be changed by it in a clear way.","zh":"直接受某事影響，是指被它清楚改變。"},{"en":"A student’s sleep is directly affected by late-night homework.","zh":"學生睡眠直接受深夜功課影響。"},{"en":"If salaries rise or working hours fall, leisure behaviour may change directly.","zh":"如果薪金上升或工時下降，休閒行為可能直接改變。"},{"en":"This phrase shows a clear influence.","zh":"這個短語顯示清楚影響。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":16},{"front":"positive and negative influences","meaning":"正面和負面影響","examples":[{"en":"The writer notes both positive and negative influences of technology.","zh":"作者指出科技的正面和負面影響。"},{"en":"Positive and negative influences are helpful and harmful effects.","zh":"正面和負面影響是有幫助和有害的效果。"},{"en":"Social media has positive and negative influences on students’ friendships and study habits.","zh":"社交媒體對學生友誼和學習習慣有正面和負面影響。"},{"en":"Technology can widen wage gaps but also make entertainment cheaper.","zh":"科技可以擴大工資差距，但也令娛樂更便宜。"},{"en":"This phrase shows a balanced view.","zh":"這個短語顯示平衡看法。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":16},{"front":"define recreational activities","meaning":"界定消閒活動","examples":[{"en":"The way researchers define recreational activities can affect the results.","zh":"研究人員界定消閒活動的方式會影響結果。"},{"en":"To define recreational activities means to decide which activities count as leisure.","zh":"界定消閒活動，是指決定哪些活動算作休閒。"},{"en":"Researchers must decide whether reading textbooks counts as recreation or education.","zh":"研究人員必須決定閱讀教科書算作消閒還是教育。"},{"en":"Different definitions can change the size of measured leisure spending.","zh":"不同定義可以改變被量度休閒開支的大小。"},{"en":"This phrase shows that classification affects conclusions.","zh":"這個短語顯示分類會影響結論。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":16},{"front":"may have been misleading","meaning":"可能具誤導性","examples":[{"en":"Ms Costa’s definition of recreational spending may have been misleading.","zh":"Costa 女士對消閒開支的定義可能具誤導性。"},{"en":"May have been misleading means may have given a wrong or unclear impression.","zh":"可能具誤導性，是指可能給出錯誤或不清楚的印象。"},{"en":"A graph without a clear scale may have been misleading to readers.","zh":"沒有清楚刻度的圖表可能對讀者具誤導性。"},{"en":"If textbooks are counted as leisure, the spending figures may look larger than they should.","zh":"如果教科書被算作休閒，開支數字可能看起來比應有更大。"},{"en":"This phrase gives cautious criticism of past interpretation.","zh":"這個短語對過去解讀作出謹慎批評。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":16},{"front":"choose the appropriate letter","meaning":"選出適當字母","examples":[{"en":"Students must choose the appropriate letter from the options.","zh":"學生必須從選項中選出適當字母。"},{"en":"To choose the appropriate letter means to select the option letter that best answers the question.","zh":"選出適當字母，是指選擇最能回答問題的選項字母。"},{"en":"In a multiple-choice question, students may choose A, B, C, or D.","zh":"在選擇題中，學生可能選 A、B、C 或 D。"},{"en":"The appropriate letter depends on meaning, not just repeated words.","zh":"適當字母取決於意思，而不只是重複字。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":16},{"front":"provide strong evidence","meaning":"提供有力證據","examples":[{"en":"The option says Ms Costa provides strong evidence to support her theory.","zh":"該選項說 Costa 女士提供有力證據支持她的理論。"},{"en":"To provide strong evidence means to give clear and convincing support for a claim.","zh":"提供有力證據，是指為某主張給出清楚而有說服力的支持。"},{"en":"A school can provide strong evidence of improvement through repeated test results and student work.","zh":"學校可以透過反覆測驗結果和學生作品提供進步的有力證據。"},{"en":"Strong evidence makes an argument more believable.","zh":"有力證據令論點更可信。"},{"en":"This phrase refers to solid support, not weak examples.","zh":"這個短語指扎實支持，而不是薄弱例子。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":16},{"front":"support her theory","meaning":"支持她的理論","examples":[{"en":"Evidence may support her theory about leisure and inequality.","zh":"證據可能支持她關於休閒和不平等的理論。"},{"en":"To support her theory means to make her explanation seem more likely to be correct.","zh":"支持她的理論，是指令她的解釋看起來更可能正確。"},{"en":"Survey results may support a teacher’s theory that practice improves writing fluency.","zh":"調查結果可能支持老師「練習改善寫作流暢度」的理論。"},{"en":"Evidence can support a theory without proving it perfectly.","zh":"證據可以支持理論，但未必完美證明它。"},{"en":"This phrase connects data with an argument.","zh":"這個短語把數據與論點連接起來。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":17},{"front":"display serious flaws","meaning":"顯示嚴重缺陷","examples":[{"en":"The option claims that her research displays serious flaws.","zh":"該選項聲稱她的研究顯示嚴重缺陷。"},{"en":"To display serious flaws means to show major weaknesses or problems.","zh":"顯示嚴重缺陷，是指呈現重大弱點或問題。"},{"en":"A study displays serious flaws if the sample is too small and the questions are unclear.","zh":"如果樣本太小且問題不清楚，研究就顯示嚴重缺陷。"},{"en":"Serious flaws can make a conclusion unreliable.","zh":"嚴重缺陷會令結論不可靠。"},{"en":"This phrase is a strong criticism of research quality.","zh":"這個短語是對研究質素的強烈批評。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":17},{"front":"research methods","meaning":"研究方法","examples":[{"en":"The option criticises Ms Costa’s research methods.","zh":"該選項批評 Costa 女士的研究方法。"},{"en":"Research methods are the ways researchers collect, classify, and analyse evidence.","zh":"研究方法是研究人員收集、分類和分析證據的方式。"},{"en":"Interviews, surveys, experiments, and data analysis are research methods.","zh":"訪問、調查、實驗和數據分析都是研究方法。"},{"en":"Weak methods can lead to weak conclusions even when the topic is important.","zh":"即使主題重要，薄弱方法也會導致薄弱結論。"},{"en":"This phrase refers to how a study is carried out.","zh":"這個短語指研究如何進行。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":17},{"front":"attempt to answer too many questions","meaning":"嘗試回答太多問題","examples":[{"en":"The option suggests that she attempts to answer too many questions.","zh":"該選項暗示她嘗試回答太多問題。"},{"en":"To attempt to answer too many questions means to try to cover more issues than the evidence can support.","zh":"嘗試回答太多問題，是指試圖涵蓋超出證據能支持的議題。"},{"en":"A student essay may become weak if it attempts to answer too many questions at once.","zh":"如果學生作文同時嘗試回答太多問題，就可能變弱。"},{"en":"Research becomes clearer when its focus is limited and specific.","zh":"當研究焦點有限而具體時，會更清楚。"},{"en":"This phrase criticises an argument for being too broad.","zh":"這個短語批評論點過於廣泛。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":17},{"front":"a useful overall point","meaning":"有用的整體觀點","examples":[{"en":"The writer thinks Ms Costa has a useful overall point to make.","zh":"作者認為 Costa 女士有一個有用的整體觀點。"},{"en":"A useful overall point is a broad idea that helps readers understand the issue better.","zh":"有用的整體觀點，是幫助讀者更好理解議題的廣泛想法。"},{"en":"A report may have a useful overall point even if some details are imperfect.","zh":"即使有些細節不完美，報告仍可能有有用的整體觀點。"},{"en":"The main point can still be valuable when it changes how people view a problem.","zh":"當主要觀點改變人們看問題的方式，它仍然有價值。"},{"en":"This phrase gives balanced approval of an argument.","zh":"這個短語對論點給出平衡認同。"}],"source":"103 - Fun for the Masses.pdf","sourcePage":17}],"ielts/reading/passage-2/Practice 104":[{"front":"man-eaters","meaning":"食人猛獸；食人虎","examples":[{"en":"The article asks why so few tigers become man-eaters.","zh":"這篇文章問為何如此少老虎會成為食人猛獸。"},{"en":"Man-eaters are animals, especially large predators, that attack and eat humans.","zh":"man-eaters 指會襲擊並吃人的動物，尤其是大型掠食者。"},{"en":"A tiger may become a man-eater if injury or age makes normal hunting difficult.","zh":"如果受傷或年老令正常捕獵變得困難，老虎可能變成食人虎。"},{"en":"When an animal becomes a man-eater, nearby villagers may avoid fields and forests.","zh":"當動物成為食人猛獸，附近村民可能避開田地和森林。"},{"en":"This word is dramatic and is usually used for dangerous wild animals, not ordinary pets.","zh":"這個詞語帶有戲劇性，通常用於危險野生動物，而不是普通寵物。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":1},{"front":"as you leave","meaning":"當你離開……時","examples":[{"en":"As you leave the national park, you can see a warning notice.","zh":"當你離開國家公園時，你可以看到一個警告告示。"},{"en":"As you leave means at the time when you are leaving a place.","zh":"as you leave 指在你離開某地的時候。"},{"en":"As you leave the classroom, please return the worksheet to the teacher.","zh":"當你離開課室時，請把工作紙交回老師。"},{"en":"A sign placed at the exit can remind visitors of something as they leave.","zh":"放在出口的告示可以在訪客離開時提醒他們某事。"},{"en":"This phrase connects an action with the moment of departure.","zh":"這個短語把一個行動與離開的時刻連接起來。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":1},{"front":"Bandhavgarh National Park","meaning":"班達夫加爾國家公園","examples":[{"en":"Bandhavgarh National Park is located in central India.","zh":"班達夫加爾國家公園位於印度中部。"},{"en":"Bandhavgarh National Park is a protected natural area known in the passage as a place where tigers live.","zh":"Bandhavgarh National Park 是受保護的自然區域，文章中指它是老虎棲息之地。"},{"en":"Visitors to Bandhavgarh National Park may hope to see wildlife from a safe distance.","zh":"到班達夫加爾國家公園的遊客可能希望在安全距離外觀察野生動物。"},{"en":"A national park needs rules because people and wild animals may come close to each other.","zh":"國家公園需要規則，因為人和野生動物可能彼此接近。"},{"en":"In this passage, the park provides the setting for thinking about tiger behaviour.","zh":"在這篇文章中，該公園提供了思考老虎行為的背景。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":1},{"front":"central India","meaning":"印度中部","examples":[{"en":"Bandhavgarh National Park is in central India.","zh":"班達夫加爾國家公園位於印度中部。"},{"en":"Central India means the middle part of India.","zh":"central India 指印度的中部地區。"},{"en":"A traveller going to central India may need different plans from someone visiting the coast.","zh":"前往印度中部的旅客，可能需要與到海岸地區不同的計劃。"},{"en":"Location matters because climate, wildlife and transport can vary across a large country.","zh":"位置很重要，因為大國內不同地區的氣候、野生動物和交通都可能不同。"},{"en":"This phrase gives geographical position rather than detailed political information.","zh":"這個短語提供地理位置，而不是詳細政治資料。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":1},{"front":"a huge, placid tiger","meaning":"一隻巨大而溫順的老虎","examples":[{"en":"The notice shows a huge, placid tiger.","zh":"告示上展示一隻巨大而溫順的老虎。"},{"en":"A huge, placid tiger is a very large tiger that appears calm and gentle.","zh":"huge, placid tiger 指一隻非常大型、看起來平靜溫和的老虎。"},{"en":"A zoo poster may show a huge, placid tiger lying quietly in the shade.","zh":"動物園海報可能展示一隻巨大而溫順的老虎安靜躺在陰影中。"},{"en":"A calm-looking tiger can still be dangerous because appearance does not remove natural power.","zh":"看似平靜的老虎仍可能危險，因為外表不會消除牠的天然力量。"},{"en":"This phrase contrasts great size with a peaceful mood.","zh":"這個短語把巨大體型與平和狀態作對比。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":1},{"front":"You may not have seen me, but…","meaning":"你可能沒有……，但……","examples":[{"en":"You may not have seen the tiger, but the tiger has seen you.","zh":"你可能沒有看到老虎，但老虎已經看到你。"},{"en":"You may not have seen me, but… means the speaker suggests that although you did not notice them, they noticed you.","zh":"You may not have seen me, but… 指說話者表示雖然你沒有注意到他，他卻注意到你。"},{"en":"A teacher might say, “You may not have seen me, but I saw you helping your classmate.”","zh":"老師可能說：「你可能沒有看到我，但我看見你幫助同學。」"},{"en":"The phrase creates surprise because one side was aware while the other was not.","zh":"這個句式製造驚訝，因為一方察覺到，另一方卻沒有。"},{"en":"In the tiger notice, it reminds visitors that wild animals may observe humans silently.","zh":"在老虎告示中，它提醒遊客野生動物可能正靜靜觀察人類。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":1},{"front":"more than a billion","meaning":"超過十億","examples":[{"en":"There are more than a billion people in India.","zh":"印度有超過十億人口。"},{"en":"More than a billion means over one thousand million.","zh":"more than a billion 指超過十億。"},{"en":"A website with more than a billion users can influence how people communicate.","zh":"擁有超過十億用戶的網站可以影響人們溝通方式。"},{"en":"Very large numbers make even rare events happen many times in total.","zh":"數量非常龐大時，即使罕見事件總數也可能很多。"},{"en":"This phrase is used when a quantity is extremely large.","zh":"當數量極大時，會使用這個短語。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":1},{"front":"every single day of their lives","meaning":"牠們一生中的每一天","examples":[{"en":"Indian tigers probably see humans every single day of their lives.","zh":"印度老虎可能一生中的每一天都看見人類。"},{"en":"Every single day of their lives means each day without exception throughout their lives.","zh":"every single day of their lives 指在整個生命中每天都如此，沒有例外。"},{"en":"A shopkeeper may speak to customers every single day of his working life.","zh":"店主可能在整個工作人生中每天都與顧客說話。"},{"en":"Repeated daily exposure can make something familiar rather than unusual.","zh":"每天反覆接觸會令某事變得熟悉，而不是不尋常。"},{"en":"This phrase strongly emphasises frequency and regularity.","zh":"這個短語強烈強調頻率和規律性。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":1},{"front":"can and do kill","meaning":"確實能夠並會殺死","examples":[{"en":"Tigers can and do kill many animals in the jungle.","zh":"老虎確實能夠並會在叢林中殺死許多動物。"},{"en":"Can and do kill means they are able to kill and actually kill in real situations.","zh":"can and do kill 指牠們有能力殺死，而且在真實情況中確實會殺死。"},{"en":"Large waves can and do damage boats during strong storms.","zh":"巨浪在強烈風暴中確實能夠並會破壞船隻。"},{"en":"This structure stresses that something is not only possible but also real.","zh":"這個結構強調某事不只是可能，而是真實會發生。"},{"en":"It is stronger than simply saying can kill.","zh":"它比 simply saying can kill 更強。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":1},{"front":"almost everything they meet","meaning":"牠們遇到的幾乎所有東西","examples":[{"en":"Tigers can kill almost everything they meet in the jungle.","zh":"老虎可以殺死牠們在叢林中遇到的幾乎所有東西。"},{"en":"Almost everything they meet means nearly all animals or creatures they encounter.","zh":"almost everything they meet 指牠們遇到的幾乎所有動物或生物。"},{"en":"A powerful machine can damage almost everything it meets if it is out of control.","zh":"如果失控，強力機器可以破壞它遇到的幾乎所有東西。"},{"en":"The phrase suggests great power but still leaves room for exceptions.","zh":"這個短語表示力量很大，但仍保留例外空間。"},{"en":"In the passage, it helps explain why the rarity of human attacks seems surprising.","zh":"在文章中，它幫助解釋為何人類襲擊事件罕見顯得令人驚訝。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":1},{"front":"in the jungle","meaning":"在叢林中","examples":[{"en":"Tigers hunt many kinds of animals in the jungle.","zh":"老虎在叢林中捕獵多種動物。"},{"en":"In the jungle means in a dense tropical forest where many plants and animals live.","zh":"in the jungle 指在有許多植物和動物生活的茂密熱帶森林中。"},{"en":"A guide may warn visitors not to walk alone in the jungle.","zh":"導遊可能提醒遊客不要獨自在叢林中行走。"},{"en":"Dense vegetation can make movement and visibility difficult in the jungle.","zh":"茂密植被會令叢林中的移動和視野變得困難。"},{"en":"This phrase gives a wild natural setting.","zh":"這個短語提供野外自然背景。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":1},{"front":"attack elephants and rhinos","meaning":"攻擊大象和犀牛","examples":[{"en":"Tigers will even attack elephants and rhinos.","zh":"老虎甚至會攻擊大象和犀牛。"},{"en":"To attack elephants and rhinos means to go after very large and powerful animals.","zh":"attack elephants and rhinos 指攻擊非常大型而有力的動物。"},{"en":"A predator that attacks such animals must be strong, bold or desperate.","zh":"會攻擊這類動物的掠食者，必定強壯、大膽或走投無路。"},{"en":"This example shows that tigers are not easily frightened by size alone.","zh":"這個例子顯示老虎不會單因體型而輕易害怕。"},{"en":"The phrase helps emphasise how powerful tigers can be.","zh":"這個短語幫助強調老虎可以有多強大。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":2},{"front":"surely","meaning":"想必；無疑","examples":[{"en":"Surely, it is strange that tiger attacks on humans are not more frequent.","zh":"想必，老虎襲擊人類並不更頻繁是奇怪的。"},{"en":"Surely is used when the speaker thinks something is very likely or hard to deny.","zh":"surely 用於說話者認為某事很可能或難以否認時。"},{"en":"Surely a school should repair a broken staircase before someone gets hurt.","zh":"學校想必應在有人受傷前修理破損樓梯。"},{"en":"This word often introduces surprise, expectation or strong belief.","zh":"這個詞常引出驚訝、期望或強烈信念。"},{"en":"It can sound persuasive because the speaker expects agreement.","zh":"它可以帶有說服力，因為說話者期待別人同意。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":2},{"front":"a little strange that","meaning":"……有點奇怪","examples":[{"en":"It is a little strange that attacks on humans are not more frequent.","zh":"老虎襲擊人類並不更頻繁，這有點奇怪。"},{"en":"A little strange that means slightly surprising or difficult to explain that something is true.","zh":"a little strange that 指某事是真的，令人稍微驚訝或難以解釋。"},{"en":"It is a little strange that the classroom is empty when the lesson starts in five minutes.","zh":"還有五分鐘就上課，課室卻空無一人，這有點奇怪。"},{"en":"This phrase softens the judgement so it sounds curious rather than extreme.","zh":"這個短語把判斷說得較溫和，聽起來像好奇而不是極端。"},{"en":"It is useful when something does not match expectations.","zh":"當某事不符合預期時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":2},{"front":"attacks on humans","meaning":"對人類的襲擊","examples":[{"en":"Attacks on humans are rarer than we might expect.","zh":"對人類的襲擊比我們可能預期的更罕見。"},{"en":"Attacks on humans are incidents in which animals or people physically harm human beings.","zh":"attacks on humans 指動物或人身體傷害人類的事件。"},{"en":"Shark attacks on humans attract news attention because they sound frightening.","zh":"鯊魚對人類的襲擊會吸引新聞注意，因為聽起來可怕。"},{"en":"Even rare attacks can create fear if they are dramatic or widely reported.","zh":"即使襲擊罕見，如果事件戲劇化或被廣泛報道，也會造成恐懼。"},{"en":"This phrase focuses on the target of the attack.","zh":"這個短語聚焦襲擊的目標。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":2},{"front":"more frequent","meaning":"更頻繁的","examples":[{"en":"It is surprising that tiger attacks are not more frequent.","zh":"令人驚訝的是，老虎襲擊並不更頻繁。"},{"en":"More frequent means happening more often.","zh":"more frequent 指發生得更經常。"},{"en":"A bus service becomes more frequent when buses arrive every ten minutes instead of every thirty.","zh":"如果巴士由每三十分鐘一班變成每十分鐘一班，服務就更頻繁。"},{"en":"If attacks became more frequent, people living near forests would change their behaviour.","zh":"如果襲擊變得更頻繁，住在森林附近的人會改變行為。"},{"en":"This phrase is used when comparing how often events happen.","zh":"比較事件發生頻率時，會使用這個短語。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":2},{"front":"might argue that","meaning":"可能會主張","examples":[{"en":"Some people might argue that tiger attacks were common in the past.","zh":"有些人可能會主張老虎襲擊在過去很常見。"},{"en":"Might argue that means may claim or suggest a possible opinion.","zh":"might argue that 指可能聲稱或提出某種看法。"},{"en":"Some parents might argue that homework teaches discipline.","zh":"有些家長可能會主張功課教導紀律。"},{"en":"This phrase presents a view without saying the writer fully agrees with it.","zh":"這個短語提出一種觀點，但不表示作者完全同意。"},{"en":"It is useful when introducing an argument that may later be questioned.","zh":"當引入之後可能被質疑的論點時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":2},{"front":"in fact","meaning":"事實上","examples":[{"en":"Some people believe that these attacks were in fact common in the past.","zh":"有些人相信這些襲擊事實上在過去很常見。"},{"en":"In fact is used to emphasise what is true or to correct a mistaken impression.","zh":"in fact 用來強調真實情況，或修正錯誤印象。"},{"en":"The shop looks small; in fact, it has three floors inside.","zh":"這間店看起來很小；事實上，裏面有三層。"},{"en":"This phrase often introduces stronger or more exact information.","zh":"這個短語常引出更強或更準確的資訊。"},{"en":"It helps contrast appearance, belief or rumour with reality.","zh":"它幫助把外觀、信念或傳聞與現實作對比。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":2},{"front":"common in the past","meaning":"在過去很常見","examples":[{"en":"Tiger attacks may have seemed common in the past.","zh":"老虎襲擊在過去可能看似很常見。"},{"en":"Common in the past means happening often in earlier times.","zh":"common in the past 指在早期時代經常發生。"},{"en":"Handwritten letters were common in the past before email became normal.","zh":"在電郵普及前，手寫信在過去很常見。"},{"en":"Something may seem common in the past because old stories repeat the most dramatic cases.","zh":"某事可能看似在過去很常見，是因為舊故事反覆講述最戲劇化的案例。"},{"en":"This phrase compares earlier patterns with present ones.","zh":"這個短語比較早期與現在的模式。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":2},{"front":"British writers of adventure stories","meaning":"英國冒險故事作家","examples":[{"en":"British writers of adventure stories helped shape the image of man-eating tigers.","zh":"英國冒險故事作家幫助塑造食人虎的形象。"},{"en":"British writers of adventure stories were authors who wrote exciting stories about danger, travel and exploration.","zh":"British writers of adventure stories 指寫關於危險、旅行和探索的刺激故事的英國作者。"},{"en":"Such writers often made faraway places seem mysterious or threatening to readers at home.","zh":"這類作家常令遙遠地方在本國讀者眼中顯得神秘或危險。"},{"en":"Their stories could influence public imagination even when they exaggerated reality.","zh":"即使故事誇大現實，也可以影響公眾想像。"},{"en":"This phrase identifies a group whose writing shaped attitudes.","zh":"這個短語指出一群透過寫作塑造態度的人。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":2},{"front":"gave the impression that","meaning":"給人……的印象","examples":[{"en":"Some writers gave the impression that village life was under constant threat.","zh":"有些作家給人一種印象，覺得鄉村生活一直受威脅。"},{"en":"To give the impression that something is true means to make people think it is true.","zh":"give the impression that something is true 指令人覺得某事是真的。"},{"en":"A messy office may give the impression that the company is disorganised.","zh":"凌亂辦公室可能給人公司缺乏組織的印象。"},{"en":"Impressions can be misleading if they are based on only a few dramatic details.","zh":"如果印象只基於少數戲劇化細節，它可能會誤導人。"},{"en":"This phrase focuses on how something appears to others.","zh":"這個短語聚焦某事在他人眼中如何呈現。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":2},{"front":"village life","meaning":"鄉村生活","examples":[{"en":"Village life in India was often described as dangerous in adventure stories.","zh":"印度鄉村生活在冒險故事中常被描述為危險。"},{"en":"Village life means daily life in a small rural community.","zh":"village life 指小型鄉村社區中的日常生活。"},{"en":"Village life may include farming, local markets, family networks and close neighbour relationships.","zh":"鄉村生活可能包括耕作、本地市場、家庭網絡和緊密鄰里關係。"},{"en":"Stories can romanticise or exaggerate village life depending on the writer’s purpose.","zh":"故事可以根據作者目的浪漫化或誇大鄉村生活。"},{"en":"This phrase refers to a way of living, not just a place.","zh":"這個短語指一種生活方式，而不只是地方。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":2},{"front":"in the early years of","meaning":"在……初期","examples":[{"en":"The stories described India in the early years of the twentieth century.","zh":"這些故事描述二十世紀初期的印度。"},{"en":"In the early years of a period means near the beginning of that period.","zh":"in the early years of a period 指在某段時期接近開始的年份。"},{"en":"In the early years of secondary school, students often learn how to organise notes.","zh":"在中學初期，學生常學習如何整理筆記。"},{"en":"This phrase helps place an event near the start of a longer time span.","zh":"這個短語幫助把事件放在一段較長時期的初段。"},{"en":"It is useful in historical description.","zh":"它適用於歷史描述。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":3},{"front":"the twentieth century","meaning":"二十世紀","examples":[{"en":"The passage refers to village life in the early years of the twentieth century.","zh":"文章提到二十世紀初期的鄉村生活。"},{"en":"The twentieth century means the years from 1901 to 2000.","zh":"the twentieth century 指 1901 年至 2000 年。"},{"en":"Many technologies changed daily life during the twentieth century.","zh":"許多科技在二十世紀改變了日常生活。"},{"en":"Referring to a century helps writers place events in a broad historical frame.","zh":"提到世紀有助作者把事件放在廣闊歷史框架中。"},{"en":"This phrase is often used in history, literature and social studies.","zh":"這個短語常用於歷史、文學和社會研究。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":3},{"front":"involved a state of","meaning":"涉及一種……狀態","examples":[{"en":"The stories suggested that village life involved a state of constant siege.","zh":"這些故事暗示鄉村生活涉及一種長期被圍困的狀態。"},{"en":"Involved a state of means included or was characterised by a particular condition.","zh":"involved a state of 指包含某種情況或以某種狀態為特徵。"},{"en":"Life during exam week may involve a state of stress and careful time management.","zh":"考試週生活可能涉及一種壓力和仔細時間管理的狀態。"},{"en":"If a situation involves a state of fear, people may change their normal routines.","zh":"如果情況涉及恐懼狀態，人們可能改變正常日常。"},{"en":"This phrase is formal and describes an ongoing condition.","zh":"這個短語較正式，描述持續狀態。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":3},{"front":"a state of constant siege","meaning":"長期被圍困的狀態","examples":[{"en":"Some stories presented villages as being in a state of constant siege.","zh":"有些故事把村莊呈現為長期被圍困的狀態。"},{"en":"A state of constant siege means a situation where people feel continuously surrounded or threatened.","zh":"state of constant siege 指人們感到持續被包圍或威脅的情況。"},{"en":"A family living beside repeated violence may feel as if they are in a state of constant siege.","zh":"住在反覆暴力附近的家庭，可能感覺像處於長期被圍困的狀態。"},{"en":"Such a feeling can make ordinary life seem unsafe and tense.","zh":"這種感覺可以令普通生活變得不安全和緊張。"},{"en":"This phrase is dramatic and suggests continuous pressure.","zh":"這個短語帶有戲劇性，暗示持續壓力。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":3},{"front":"man-eating tigers","meaning":"食人虎","examples":[{"en":"Adventure stories often described man-eating tigers.","zh":"冒險故事常描述食人虎。"},{"en":"Man-eating tigers are tigers that attack and eat humans.","zh":"man-eating tigers 指會襲擊並吃人的老虎。"},{"en":"A story about man-eating tigers can make a forest seem terrifying to readers.","zh":"關於食人虎的故事可以令森林在讀者眼中顯得可怕。"},{"en":"If the number of such tigers is exaggerated, people may misunderstand real tiger behaviour.","zh":"如果這類老虎的數量被誇大，人們可能誤解真實老虎行為。"},{"en":"This phrase is more specific than man-eaters because it names the animal.","zh":"這個短語比 man-eaters 更具體，因為它指出動物種類。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":3},{"front":"overstated the terror","meaning":"誇大恐懼","examples":[{"en":"The writers may have overstated the terror spread by tigers.","zh":"這些作家可能誇大了老虎造成的恐懼。"},{"en":"To overstate the terror means to describe the fear as greater than it really was.","zh":"overstate the terror 指把恐懼描述得比真實情況更嚴重。"},{"en":"News reports can overstate the danger of a rare disease if they focus only on the worst cases.","zh":"如果新聞報道只聚焦最壞案例，可能誇大罕見疾病的危險。"},{"en":"Overstatement can make people afraid even when the actual risk is low.","zh":"誇大會令人害怕，即使實際風險很低。"},{"en":"This phrase is useful when fear is exaggerated.","zh":"當恐懼被誇大時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":3},{"front":"spread by tigers","meaning":"由老虎造成的恐懼","examples":[{"en":"The terror spread by tigers may have been exaggerated.","zh":"由老虎造成的恐懼可能被誇大。"},{"en":"Spread by tigers means caused or extended by the presence or actions of tigers.","zh":"spread by tigers 指由老虎的存在或行動造成或擴散。"},{"en":"Fear spread by rumours can become stronger than the real danger.","zh":"由謠言散播的恐懼可能比真實危險更強。"},{"en":"If stories repeat tiger attacks, the fear spread by tigers may seem larger than the facts support.","zh":"如果故事反覆講述老虎襲擊，由老虎造成的恐懼可能顯得比事實支持的更大。"},{"en":"This phrase shows the source of fear or influence.","zh":"這個短語顯示恐懼或影響的來源。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":3},{"front":"far more tigers around","meaning":"當時有多得多的老虎","examples":[{"en":"There were far more tigers around in those days.","zh":"當時有多得多的老虎。"},{"en":"Far more tigers around means many more tigers existed in the area or period being discussed.","zh":"far more tigers around 指在所討論的地區或時期有多得多老虎存在。"},{"en":"A forest with far more deer around may attract more predators.","zh":"如果森林中有多得多鹿，可能吸引更多掠食者。"},{"en":"If there were more tigers but attacks stayed rare, the argument about frequency becomes stronger.","zh":"如果老虎更多但襲擊仍罕見，關於頻率的論點就更有力。"},{"en":"This phrase stresses a large difference in numbers.","zh":"這個短語強調數量上的巨大差異。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":3},{"front":"in those days","meaning":"在那些年代","examples":[{"en":"There were probably 60,000 tigers in the subcontinent in those days.","zh":"在那些年代，次大陸可能有 60,000 隻老虎。"},{"en":"In those days means during that earlier period of time.","zh":"in those days 指在那個較早時期。"},{"en":"In those days, children often walked to school without smartphones.","zh":"在那些年代，孩子常沒有智能手機也步行上學。"},{"en":"This phrase creates a contrast between past and present.","zh":"這個短語創造過去與現在的對比。"},{"en":"It is often used when recalling older conditions or habits.","zh":"回憶舊時情況或習慣時，常用這個短語。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":3},{"front":"the subcontinent","meaning":"次大陸","examples":[{"en":"There were many more tigers in the subcontinent in the past.","zh":"過去次大陸有多得多老虎。"},{"en":"The subcontinent refers here to the Indian subcontinent, a large region including India and nearby areas.","zh":"the subcontinent 在此指印度次大陸，包括印度及附近地區的大型區域。"},{"en":"Historical reports about wildlife in the subcontinent often cover large and varied landscapes.","zh":"關於次大陸野生動物的歷史報告，常涵蓋廣闊而多樣的景觀。"},{"en":"A broad region can contain forests, villages, farms and cities, so animal encounters vary widely.","zh":"大區域可以包含森林、村莊、農田和城市，因此動物接觸情況差異很大。"},{"en":"This phrase gives a regional rather than local scale.","zh":"這個短語提供區域尺度，而不是本地尺度。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":3},{"front":"compared to","meaning":"與……相比","examples":[{"en":"There were about 60,000 tigers then, compared to about 3,000 today.","zh":"當時約有 60,000 隻老虎，與今天約 3,000 隻相比。"},{"en":"Compared to means set beside another figure or situation to show difference.","zh":"compared to 指把某數字或情況與另一個放在一起，以顯示差異。"},{"en":"The class is small this year, compared to last year’s group of forty students.","zh":"與去年四十人的班級相比，今年這班人數較少。"},{"en":"Comparisons help readers understand whether a number is large or small.","zh":"比較幫助讀者理解數字是大還是小。"},{"en":"This phrase is useful when showing change over time.","zh":"顯示隨時間變化時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":3},{"front":"in proportion","meaning":"按比例來看","examples":[{"en":"In proportion, tiger attacks seem to have been rare even in the past.","zh":"按比例來看，即使在過去，老虎襲擊似乎也很罕見。"},{"en":"In proportion means when considered in relation to the total number or size.","zh":"in proportion 指相對於總數或規模來考慮。"},{"en":"A school with ten accidents among two thousand students may have fewer accidents in proportion than a smaller school with five.","zh":"一間有兩千名學生且發生十宗意外的學校，按比例可能比一間只有五宗意外的小學校更少。"},{"en":"Looking at proportion prevents large raw numbers from misleading us.","zh":"看比例可以防止龐大原始數字誤導我們。"},{"en":"This phrase is useful when comparing rates, not just totals.","zh":"比較比率而不只是總數時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":4},{"front":"appear to have been","meaning":"看來曾經是","examples":[{"en":"Attacks appear to have been as rare then as they are today.","zh":"襲擊看來曾經和今天一樣罕見。"},{"en":"Appear to have been means seem, based on evidence, to have been true in the past.","zh":"appear to have been 指根據證據看來過去曾經如此。"},{"en":"The shop appears to have been busy yesterday because many items are sold out.","zh":"由於許多貨品售罄，這間店昨天看來曾經很忙。"},{"en":"This phrase is cautious because the writer is not claiming complete certainty.","zh":"這個短語較謹慎，因為作者沒有聲稱完全確定。"},{"en":"It is useful when interpreting past evidence.","zh":"解讀過去證據時，它很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":4},{"front":"as rare then as they are today","meaning":"當時和今天一樣罕見","examples":[{"en":"Tiger attacks were probably as rare then as they are today.","zh":"老虎襲擊當時可能和今天一樣罕見。"},{"en":"As rare then as they are today means equally uncommon in the past and present.","zh":"as rare then as they are today 指在過去和現在同樣不常見。"},{"en":"Serious library fires may be as rare now as they were decades ago.","zh":"嚴重圖書館火災現在可能和數十年前一樣罕見。"},{"en":"If something is equally rare across time, dramatic stories may exaggerate its importance.","zh":"如果某事跨時期同樣罕見，戲劇化故事可能誇大其重要性。"},{"en":"This phrase compares frequency across two periods.","zh":"這個短語比較兩個時期的頻率。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":4},{"front":"it is widely assumed that","meaning":"人們普遍認為","examples":[{"en":"It is widely assumed that tigers avoid humans because of fear.","zh":"人們普遍認為老虎因恐懼而避開人類。"},{"en":"It is widely assumed that means many people believe something, even if it may not be proven.","zh":"it is widely assumed that 指許多人相信某事，即使未必已被證明。"},{"en":"It is widely assumed that students prefer online notes, but some still learn better on paper.","zh":"人們普遍認為學生較喜歡網上筆記，但有些學生仍用紙本學得更好。"},{"en":"Common assumptions can be wrong if they are not tested against evidence.","zh":"如果沒有用證據檢驗，常見假設可能是錯的。"},{"en":"This phrase introduces a popular belief that may be questioned.","zh":"這個短語引入一個可能被質疑的普遍信念。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":4},{"front":"the constraint is fear","meaning":"限制因素是恐懼","examples":[{"en":"Some people think the constraint is fear.","zh":"有些人認為限制因素是恐懼。"},{"en":"The constraint is fear means fear is the factor that limits behaviour or action.","zh":"the constraint is fear 指恐懼是限制行為或行動的因素。"},{"en":"If a child avoids speaking in class, the constraint may be fear rather than lack of ideas.","zh":"如果孩子避免在課堂發言，限制因素可能是恐懼，而不是沒有想法。"},{"en":"When fear is the constraint, removing danger or building confidence may change behaviour.","zh":"當恐懼是限制因素，消除危險或建立信心可能改變行為。"},{"en":"This phrase identifies fear as the limiting cause.","zh":"這個短語把恐懼識別為限制原因。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":4},{"front":"afraid of","meaning":"害怕……","examples":[{"en":"The writer asks what tigers are afraid of.","zh":"作者問老虎害怕甚麼。"},{"en":"Afraid of something means feeling fear toward it.","zh":"afraid of something 指對某事感到恐懼。"},{"en":"A young child may be afraid of loud thunder during a storm.","zh":"幼童在暴風雨中可能害怕大雷聲。"},{"en":"Fear can make animals or people avoid something, even if they could physically face it.","zh":"恐懼可以令人或動物避開某事，即使身體上能面對它。"},{"en":"This phrase is common for describing emotional reaction to danger or uncertainty.","zh":"這個短語常用於描述對危險或不確定性的情緒反應。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":4},{"front":"better armed than","meaning":"比……配備更好的武器","examples":[{"en":"Humans may be better armed than tigers are.","zh":"人類可能比老虎配備更好的武器。"},{"en":"Better armed than means having stronger or more effective weapons or protection than another side.","zh":"better armed than 指比另一方擁有更強或更有效的武器或保護。"},{"en":"Police are usually better armed than ordinary citizens during a dangerous emergency.","zh":"在危險緊急情況中，警方通常比普通市民配備更好的武器。"},{"en":"If one group is better armed, opponents may avoid direct conflict.","zh":"如果一方武裝較好，對手可能避免直接衝突。"},{"en":"This phrase compares the ability to fight or defend.","zh":"這個短語比較戰鬥或防衛能力。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":4},{"front":"the species","meaning":"這個物種","examples":[{"en":"The writer questions whether the species has inherited a fear of humans.","zh":"作者質疑這個物種是否遺傳了對人類的恐懼。"},{"en":"The species means a group of living organisms that share basic biological features and can reproduce among themselves.","zh":"the species 指共享基本生物特徵並能互相繁殖的一類生物。"},{"en":"Tigers are a species with particular hunting habits and body structure.","zh":"老虎是一個具有特定捕獵習性和身體結構的物種。"},{"en":"When discussing a species, scientists look beyond one individual animal.","zh":"討論一個物種時，科學家看的不只是單一動物。"},{"en":"This phrase is useful in biology and animal behaviour.","zh":"這個短語適用於生物學和動物行為。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":4},{"front":"programmed into its genes","meaning":"被編入其基因中","examples":[{"en":"The fear may have been programmed into the tiger’s genes.","zh":"這種恐懼可能已被編入老虎的基因中。"},{"en":"Programmed into its genes means built into an animal’s inherited biology.","zh":"programmed into its genes 指某事被寫入動物遺傳生物特性中。"},{"en":"Some birds have migration patterns that seem programmed into their genes.","zh":"有些鳥類的遷徙模式似乎被編入基因中。"},{"en":"If behaviour is genetically programmed, it may appear without being taught.","zh":"如果行為由基因編程，它可能不需教導就出現。"},{"en":"This phrase is often used when discussing instinct.","zh":"這個短語常用於討論本能。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":4},{"front":"inherited as instinct","meaning":"作為本能遺傳下來","examples":[{"en":"Some fear may be inherited as instinct.","zh":"有些恐懼可能作為本能遺傳下來。"},{"en":"Inherited as instinct means passed down biologically as an automatic behaviour or reaction.","zh":"inherited as instinct 指作為自動行為或反應，透過生物方式傳下來。"},{"en":"A baby animal may avoid a predator because the fear is inherited as instinct.","zh":"幼小動物可能避開掠食者，因為恐懼作為本能遺傳下來。"},{"en":"Instinctive behaviour does not require careful reasoning or teaching.","zh":"本能行為不需要仔細推理或教導。"},{"en":"This phrase contrasts inherited reaction with learned experience.","zh":"這個短語把遺傳反應與後天學習經驗作對比。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":4},{"front":"the explanation may be simpler","meaning":"解釋可能更簡單","examples":[{"en":"The writer thinks the explanation may be simpler.","zh":"作者認為解釋可能更簡單。"},{"en":"The explanation may be simpler means the true reason may not require a complicated theory.","zh":"the explanation may be simpler 指真正原因可能不需要複雜理論。"},{"en":"If a student is late, the explanation may be simpler: the bus broke down.","zh":"如果學生遲到，解釋可能更簡單：巴士壞了。"},{"en":"Simple explanations can be powerful when they fit the evidence better.","zh":"當簡單解釋更符合證據，它也可以很有力。"},{"en":"This phrase prepares readers for an alternative idea.","zh":"這個短語讓讀者準備接受另一種想法。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":4},{"front":"in a way","meaning":"某程度上","examples":[{"en":"In a way, the explanation may be more intriguing.","zh":"某程度上，這個解釋可能更耐人尋味。"},{"en":"In a way means from one point of view or in one sense.","zh":"in a way 指從某個角度或某種意義上。"},{"en":"In a way, mistakes are useful because they show what needs practice.","zh":"某程度上，錯誤是有用的，因為它們顯示需要練習甚麼。"},{"en":"This phrase softens a claim and makes it less absolute.","zh":"這個短語使說法較溫和、不那麼絕對。"},{"en":"It is useful when the writer wants to qualify an opinion.","zh":"當作者想限制某個觀點時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":5},{"front":"more intriguing","meaning":"更耐人尋味的","examples":[{"en":"The writer offers a simpler and more intriguing explanation.","zh":"作者提出一個更簡單而更耐人尋味的解釋。"},{"en":"More intriguing means more interesting because it makes people curious or thoughtful.","zh":"more intriguing 指更有趣，因為它令人好奇或思考。"},{"en":"A mystery story becomes more intriguing when a small clue changes the whole case.","zh":"當一個小線索改變整個案件，懸疑故事就變得更耐人尋味。"},{"en":"An intriguing explanation can make readers rethink what they assumed.","zh":"耐人尋味的解釋可以令讀者重新思考原本假設。"},{"en":"This phrase is useful when an idea is not just true but mentally engaging.","zh":"當一個想法不只正確，還令人投入思考時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":5},{"front":"the growth of ethology","meaning":"動物行為學的發展","examples":[{"en":"The growth of ethology changed how scientists studied animals.","zh":"動物行為學的發展改變了科學家研究動物的方式。"},{"en":"The growth of ethology means the development and increasing importance of the scientific study of animal behaviour.","zh":"the growth of ethology 指動物行為科學研究的發展和重要性增加。"},{"en":"As ethology grew, researchers paid more attention to animals in natural settings.","zh":"隨着動物行為學發展，研究人員更重視動物在自然環境中的行為。"},{"en":"This development changed science by discouraging purely human-centred explanations.","zh":"這項發展改變了科學，因為它不鼓勵純粹以人類為中心的解釋。"},{"en":"This phrase refers to the rise of a field of study.","zh":"這個短語指一個研究領域的興起。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":5},{"front":"ethology","meaning":"動物行為學","examples":[{"en":"Ethology studies animal behaviour in natural habitats.","zh":"動物行為學研究自然棲息地中的動物行為。"},{"en":"Ethology is the scientific study of how animals behave, especially in their natural environments.","zh":"ethology 指科學研究動物如何行為，尤其是在自然環境中。"},{"en":"An ethologist may watch birds build nests instead of only testing them in cages.","zh":"動物行為學家可能觀察鳥築巢，而不是只在籠中測試牠們。"},{"en":"Ethology helps explain behaviour from the animal’s own situation.","zh":"動物行為學有助從動物自身情境解釋行為。"},{"en":"This word belongs to zoology and behavioural science.","zh":"這個詞屬於動物學和行為科學。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":5},{"front":"animal behaviour","meaning":"動物行為","examples":[{"en":"Ethology helps us understand animal behaviour.","zh":"動物行為學幫助我們理解動物行為。"},{"en":"Animal behaviour means the ways animals move, feed, communicate, hunt, mate or respond to danger.","zh":"animal behaviour 指動物移動、進食、溝通、捕獵、交配或應對危險的方式。"},{"en":"A dog hiding under a table during thunder is showing animal behaviour linked to fear.","zh":"狗在雷聲中躲到桌下，是表現出與恐懼有關的動物行為。"},{"en":"Studying behaviour can reveal what animals notice and need.","zh":"研究行為可以揭示動物注意到甚麼和需要甚麼。"},{"en":"This phrase is broad and can include both instinctive and learned actions.","zh":"這個短語很廣，可以包括本能和後天學習行為。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":5},{"front":"from the animal’s point of view","meaning":"從動物的角度","examples":[{"en":"Ethology tries to understand behaviour from the animal’s point of view.","zh":"動物行為學嘗試從動物的角度理解行為。"},{"en":"From the animal’s point of view means considering how the animal perceives and responds to the world.","zh":"from the animal’s point of view 指考慮動物如何感知並回應世界。"},{"en":"From a dog’s point of view, a vacuum cleaner may seem like a loud threat.","zh":"從狗的角度看，吸塵機可能像一個大聲的威脅。"},{"en":"This approach prevents people from assuming animals think exactly like humans.","zh":"這種方法防止人們假設動物和人類思考完全相同。"},{"en":"This phrase is central to careful animal-behaviour analysis.","zh":"這個短語是仔細分析動物行為的核心。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":5},{"front":"elegant experiments","meaning":"精巧的實驗","examples":[{"en":"Early ethologists carried out elegant experiments.","zh":"早期動物行為學家進行精巧的實驗。"},{"en":"Elegant experiments are simple, clever experiments that reveal an idea clearly.","zh":"elegant experiments 指簡潔、聰明且能清楚揭示想法的實驗。"},{"en":"A science teacher may design an elegant experiment using only water, paper and light.","zh":"科學老師可能只用水、紙和光設計精巧的實驗。"},{"en":"Good experiments do not need to be complicated if they answer the question well.","zh":"如果實驗能很好回答問題，就不需要複雜。"},{"en":"This phrase praises both clarity and intelligence in research design.","zh":"這個短語讚揚研究設計的清晰和智慧。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":5},{"front":"pioneers in the field","meaning":"該領域的先驅","examples":[{"en":"Konrad Lorenz was one of the pioneers in the field.","zh":"Konrad Lorenz 是該領域的先驅之一。"},{"en":"Pioneers in the field are people who help start or develop an area of study or work.","zh":"pioneers in the field 指幫助開創或發展某研究或工作領域的人。"},{"en":"Early computer scientists were pioneers in the field of digital technology.","zh":"早期電腦科學家是數碼科技領域的先驅。"},{"en":"Pioneers often create methods that later researchers improve.","zh":"先驅常創造方法，供後來研究者改進。"},{"en":"This phrase gives respect to people who opened a new path.","zh":"這個短語向開拓新道路的人表示尊重。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":5},{"front":"naturalists","meaning":"自然學家","examples":[{"en":"Naturalists once wrote about animals as if they were less intelligent humans.","zh":"自然學家曾經描寫動物，好像牠們是智力稍遜的人類。"},{"en":"Naturalists are people who observe and study plants, animals and the natural world.","zh":"naturalists 指觀察和研究植物、動物及自然世界的人。"},{"en":"A naturalist may keep notes on birds, insects and trees during long walks.","zh":"自然學家可能在長途步行中記錄鳥類、昆蟲和樹木。"},{"en":"Earlier naturalists sometimes mixed careful observation with human-like interpretations.","zh":"早期自然學家有時把仔細觀察與擬人化解釋混在一起。"},{"en":"This word is often used for observers of nature, especially before modern specialised science.","zh":"這個詞常用於自然觀察者，尤其是現代專門科學之前。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":5},{"front":"as if","meaning":"好像；彷彿","examples":[{"en":"Some writers described animals as if they were less intelligent humans.","zh":"有些作家描述動物，好像牠們是智力稍遜的人類。"},{"en":"As if means in a way that suggests something is true, even if it may not be true.","zh":"as if 指以一種暗示某事為真的方式，即使它未必是真的。"},{"en":"He looked at the broken phone as if it were a serious mystery.","zh":"他看着壞掉的電話，彷彿那是一宗嚴重謎案。"},{"en":"This phrase often introduces comparison, appearance or imagination.","zh":"這個短語常引出比較、外觀或想像。"},{"en":"It helps describe how something seems, not necessarily what it really is.","zh":"它幫助描述某事看起來如何，而不一定是現實如何。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":5},{"front":"slightly less intelligent humans","meaning":"智力稍遜的人類","examples":[{"en":"Early writers sometimes treated animals as slightly less intelligent humans.","zh":"早期作家有時把動物視為智力稍遜的人類。"},{"en":"Slightly less intelligent humans means people with a little less intelligence, but the phrase is used here to criticise a human-centred view of animals.","zh":"slightly less intelligent humans 指智力稍低的人，但在此用來批評以人類為中心看待動物的觀點。"},{"en":"If we treat dogs as slightly less intelligent humans, we may misunderstand why they bark or hide.","zh":"如果我們把狗看作智力稍遜的人類，就可能誤解牠們為何吠叫或躲藏。"},{"en":"Animals may solve problems differently because they perceive the world differently.","zh":"動物可能以不同方式解決問題，因為牠們以不同方式感知世界。"},{"en":"This phrase warns against explaining animal behaviour only through human thinking.","zh":"這個短語提醒我們不要只用人類思維解釋動物行為。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":5},{"front":"breathless accounts","meaning":"緊張刺激的敘述","examples":[{"en":"Jim Corbett wrote breathless accounts of his encounters with man-eaters.","zh":"Jim Corbett 寫下他與食人猛獸相遇的緊張刺激敘述。"},{"en":"Breathless accounts are exciting, dramatic descriptions that make events feel urgent.","zh":"breathless accounts 指令人覺得事件急迫、刺激而戲劇化的描述。"},{"en":"A journalist may write a breathless account of a last-minute rescue.","zh":"記者可能寫一篇關於最後一刻救援的緊張刺激敘述。"},{"en":"Such writing can attract readers but may also exaggerate danger.","zh":"這種寫法可以吸引讀者，但也可能誇大危險。"},{"en":"This phrase describes style and tone, not literal breathing.","zh":"這個短語描述風格和語氣，不是字面上的呼吸。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":6},{"front":"duels with man-eaters","meaning":"與食人猛獸的對決","examples":[{"en":"Corbett’s accounts described his duels with man-eaters.","zh":"Corbett 的敘述描寫他與食人猛獸的對決。"},{"en":"Duels with man-eaters are dramatic confrontations between a hunter and dangerous animals that attack humans.","zh":"duels with man-eaters 指獵人與會襲擊人的危險動物之間戲劇化的對抗。"},{"en":"Adventure stories often turn difficult hunts into duels between hero and beast.","zh":"冒險故事常把艱難獵捕寫成英雄與野獸的對決。"},{"en":"Calling a hunt a duel makes it feel personal, tense and heroic.","zh":"把狩獵稱為對決，會令它感覺個人化、緊張和英勇。"},{"en":"This phrase is literary and dramatic rather than neutral scientific language.","zh":"這個短語較文學化和戲劇化，而不是中性科學語言。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":6},{"front":"in truth","meaning":"其實；說實話","examples":[{"en":"In truth, those accounts reveal more about the writer than the animals.","zh":"其實，那些敘述透露更多關於作者，而不是動物。"},{"en":"In truth means actually or when the situation is understood honestly.","zh":"in truth 指實際上，或誠實理解情況時。"},{"en":"The plan looked simple; in truth, it required months of hidden work.","zh":"這個計劃看似簡單；其實，它需要數月隱藏工作。"},{"en":"This phrase often corrects a surface impression.","zh":"這個短語常用來修正表面印象。"},{"en":"It sounds reflective and slightly formal.","zh":"它聽起來帶有反思性，稍微正式。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":6},{"front":"tell us more about…than…","meaning":"告訴我們更多關於……而不是……","examples":[{"en":"His stories tell us more about Corbett than about the tigers.","zh":"他的故事告訴我們更多關於 Corbett，而不是關於老虎。"},{"en":"Tell us more about A than B means reveal more information about A than about B.","zh":"tell us more about A than B 指透露更多關於 A 而不是 B 的資料。"},{"en":"A student’s messy notes may tell us more about her thinking process than about her final answer.","zh":"學生凌亂的筆記可能告訴我們更多關於她的思考過程，而不是最終答案。"},{"en":"A dramatic story may reveal the writer’s fears more than the real danger.","zh":"戲劇化故事可能更多揭示作者的恐懼，而不是真實危險。"},{"en":"This phrase helps compare what a source truly shows.","zh":"這個短語幫助比較資料來源真正顯示甚麼。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":6},{"front":"the principle of ethology","meaning":"動物行為學的原則","examples":[{"en":"The principle of ethology requires careful observation.","zh":"動物行為學的原則要求仔細觀察。"},{"en":"The principle of ethology is the basic idea that animal behaviour should be studied from the animal’s own context.","zh":"principle of ethology 指應從動物自身情境研究動物行為的基本理念。"},{"en":"A researcher following this principle observes what the animal actually does before explaining it.","zh":"遵循這原則的研究者會先觀察動物實際做甚麼，再作解釋。"},{"en":"This approach reduces the mistake of treating animals like small humans.","zh":"這種方法減少把動物當成小型人類的錯誤。"},{"en":"This phrase refers to the guiding logic of animal-behaviour study.","zh":"這個短語指動物行為研究的指導邏輯。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":6},{"front":"on the other hand","meaning":"另一方面","examples":[{"en":"Ethology, on the other hand, asks us to think like the animal.","zh":"另一方面，動物行為學要求我們像動物那樣思考。"},{"en":"On the other hand introduces a contrasting idea or different side of the argument.","zh":"on the other hand 用來引出對比想法或論點的另一面。"},{"en":"Printed books are heavy; on the other hand, they are easy to mark and lend.","zh":"印刷書很重；另一方面，它們容易標記和借出。"},{"en":"This phrase helps writers compare two views fairly.","zh":"這個短語幫助作者公平比較兩種看法。"},{"en":"It is useful when one point balances or challenges another.","zh":"當一點平衡或挑戰另一點時，它很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":6},{"front":"requires us to","meaning":"要求我們","examples":[{"en":"Ethology requires us to observe animal behaviour carefully.","zh":"動物行為學要求我們仔細觀察動物行為。"},{"en":"Requires us to means makes it necessary for us to do something.","zh":"requires us to 指使我們有必要做某事。"},{"en":"Good writing requires us to revise, not just finish a first draft.","zh":"好寫作要求我們修訂，而不是只完成初稿。"},{"en":"When a task requires careful observation, quick guessing can lead to mistakes.","zh":"當任務要求仔細觀察，快速猜測可能導致錯誤。"},{"en":"This phrase shows obligation or necessity.","zh":"這個短語顯示義務或必要性。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":6},{"front":"think as the animal does","meaning":"像該動物那樣思考","examples":[{"en":"Researchers should try to think as the animal does.","zh":"研究人員應嘗試像該動物那樣思考。"},{"en":"To think as the animal does means to consider how the animal perceives, reacts and solves problems.","zh":"think as the animal does 指考慮動物如何感知、反應和解決問題。"},{"en":"A dog trainer thinks as the dog does when she asks what the dog hears and fears.","zh":"訓犬師問狗聽到甚麼、害怕甚麼時，就是像狗那樣思考。"},{"en":"This approach can reveal why an animal avoids, attacks or ignores something.","zh":"這種方法可以揭示動物為何避開、攻擊或忽視某物。"},{"en":"The phrase warns against assuming animal minds work like human minds.","zh":"這個短語提醒我們不要假設動物心智像人類心智一樣運作。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":6},{"front":"observe every tiny detail","meaning":"觀察每一個細微細節","examples":[{"en":"Ethologists observe every tiny detail of an animal’s behaviour.","zh":"動物行為學家觀察動物行為的每一個細微細節。"},{"en":"To observe every tiny detail means to watch even very small actions carefully.","zh":"observe every tiny detail 指仔細觀看即使非常小的動作。"},{"en":"A doctor may observe every tiny detail of a patient’s breathing before deciding what is wrong.","zh":"醫生可能在判斷問題前，觀察病人呼吸的每一個細微細節。"},{"en":"Small details can reveal causes that broad impressions miss.","zh":"細小細節可以揭示宏觀印象忽略的原因。"},{"en":"This phrase stresses careful, patient attention.","zh":"這個短語強調仔細而耐心的注意。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":6},{"front":"without imposing","meaning":"不把……強加於","examples":[{"en":"Researchers should observe animals without imposing human meanings on their actions.","zh":"研究人員應觀察動物，而不把人類意義強加於其行為上。"},{"en":"Without imposing something means without forcing an outside idea or interpretation onto it.","zh":"without imposing something 指不把外來想法或解釋強行套上去。"},{"en":"A teacher should listen to a student’s answer without imposing her own wording too quickly.","zh":"老師應先聆聽學生答案，而不要太快把自己的措辭強加上去。"},{"en":"Imposing human meanings on animals may hide what the animal is actually doing.","zh":"把人類意義強加於動物，可能掩蓋動物實際在做甚麼。"},{"en":"This phrase is useful when careful interpretation matters.","zh":"當仔細解釋很重要時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":6},{"front":"human significance","meaning":"人類賦予的意義","examples":[{"en":"We should not impose our own human significance on animal behaviour.","zh":"我們不應把自己的人類意義強加於動物行為上。"},{"en":"Human significance means meaning or importance understood from a human perspective.","zh":"human significance 指從人類角度理解的意義或重要性。"},{"en":"A cat knocking over a cup may not carry the human significance of deliberate rudeness.","zh":"貓打翻杯子未必具有人類所理解的故意無禮意義。"},{"en":"Giving human meaning too quickly can lead to misunderstanding animal behaviour.","zh":"太快賦予人類意義可能導致誤解動物行為。"},{"en":"This phrase contrasts human interpretation with animal reality.","zh":"這個短語把人類解釋與動物現實作對比。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":6},{"front":"on its actions","meaning":"在其行為上","examples":[{"en":"Researchers should avoid imposing human significance on an animal’s actions.","zh":"研究人員應避免把人類意義強加在動物的行為上。"},{"en":"On its actions means onto what the animal does.","zh":"on its actions 指在該動物所做的行為上。"},{"en":"If a dog turns away, we should not immediately put human guilt on its actions.","zh":"如果狗轉身離開，我們不應立即把人類的內疚感加在牠的行為上。"},{"en":"Careful observation separates the action itself from our interpretation of it.","zh":"仔細觀察會把行為本身與我們對行為的解釋分開。"},{"en":"This phrase is useful when discussing behaviour and meaning.","zh":"討論行為和意義時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":7},{"front":"I suspect that","meaning":"我懷疑","examples":[{"en":"I suspect that a tiger’s fear of humans is related to visual perception.","zh":"我懷疑老虎對人類的恐懼與視覺感知有關。"},{"en":"I suspect that means I think something may be true, though I am not completely certain.","zh":"I suspect that 指我認為某事可能是真的，但並非完全確定。"},{"en":"I suspect that the student is tired because she has made unusual mistakes today.","zh":"我懷疑這名學生很疲倦，因為她今天犯了不尋常錯誤。"},{"en":"This phrase presents a careful guess based on clues.","zh":"這個短語提出基於線索的謹慎猜想。"},{"en":"It is softer than I know that.","zh":"它比 I know that 更溫和。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":7},{"front":"fear of humans","meaning":"對人類的恐懼","examples":[{"en":"The writer offers a theory about a tiger’s fear of humans.","zh":"作者提出一個關於老虎對人類恐懼的理論。"},{"en":"Fear of humans means fear directed toward people.","zh":"fear of humans 指針對人的恐懼。"},{"en":"Wild animals may develop fear of humans if people often chase or harm them.","zh":"如果人類經常追趕或傷害野生動物，牠們可能發展出對人類的恐懼。"},{"en":"Fear can make animals avoid humans even when humans are nearby every day.","zh":"恐懼可以令動物避開人類，即使人類每天都在附近。"},{"en":"This phrase describes an animal’s reaction to people.","zh":"這個短語描述動物對人的反應。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":7},{"front":"lies not in…but in…","meaning":"不在於……而在於……","examples":[{"en":"The explanation lies not in instinct but in visual perception.","zh":"解釋不在於本能，而在於視覺感知。"},{"en":"Lies not in A but in B means the true explanation is not A; it is B.","zh":"lies not in A but in B 指真正解釋不是 A，而是 B。"},{"en":"A student’s poor score may lie not in laziness but in weak reading skills.","zh":"學生成績差可能不在於懶惰，而在於閱讀能力弱。"},{"en":"This structure is useful for correcting a wrong assumption and offering a better cause.","zh":"這個結構適合修正錯誤假設並提出更好原因。"},{"en":"It creates a clear contrast between two possible explanations.","zh":"它在兩種可能解釋之間創造清楚對比。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":7},{"front":"preprogrammed ancestral logic","meaning":"預設的祖傳邏輯","examples":[{"en":"The writer doubts that fear comes from preprogrammed ancestral logic.","zh":"作者懷疑恐懼來自預設的祖傳邏輯。"},{"en":"Preprogrammed ancestral logic means inherited behaviour shaped by ancestors and built into instinct.","zh":"preprogrammed ancestral logic 指由祖先塑造並寫入本能的遺傳行為邏輯。"},{"en":"Some people might explain a bird’s migration through preprogrammed ancestral logic.","zh":"有些人可能用預設的祖傳邏輯解釋鳥類遷徙。"},{"en":"The writer questions this kind of inherited explanation for tigers’ fear of humans.","zh":"作者質疑這種遺傳解釋能否說明老虎對人類的恐懼。"},{"en":"This phrase is technical and refers to instinctive evolutionary reasoning.","zh":"這個短語較技術性，指本能的演化邏輯。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":7},{"front":"perceives us visually","meaning":"以視覺方式感知我們","examples":[{"en":"The tiger may fear humans because of the way it perceives us visually.","zh":"老虎可能因其以視覺方式感知我們的方式而害怕人類。"},{"en":"Perceives us visually means sees and interprets our shape through sight.","zh":"perceives us visually 指透過視覺看見並理解我們的形狀。"},{"en":"A baby perceives adults visually before understanding their words.","zh":"嬰兒在理解成人語言前，會先以視覺方式感知成人。"},{"en":"If an animal perceives a shape wrongly, it may misjudge danger or prey.","zh":"如果動物錯誤感知形狀，牠可能誤判危險或獵物。"},{"en":"This phrase connects seeing with interpretation, not sight alone.","zh":"這個短語把看見與解讀連接起來，而不只是視力。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":7},{"front":"think like a tiger","meaning":"像老虎那樣思考","examples":[{"en":"If you think like a tiger, a human in a car may look different.","zh":"如果你像老虎那樣思考，車裏的人可能看起來不同。"},{"en":"To think like a tiger means to imagine how a tiger sees and interprets the world.","zh":"think like a tiger 指想像老虎如何看見和解讀世界。"},{"en":"A wildlife researcher tries to think like a tiger when asking why it avoids certain paths.","zh":"野生動物研究者問老虎為何避開某些路徑時，就是嘗試像老虎那樣思考。"},{"en":"Thinking like the animal can reveal explanations humans might otherwise miss.","zh":"像動物那樣思考，可以揭示人類原本可能忽略的解釋。"},{"en":"This phrase asks readers to shift perspective.","zh":"這個短語要求讀者轉換角度。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":7},{"front":"a human in a car","meaning":"車裏的人","examples":[{"en":"A human in a car may appear to be part of the car.","zh":"車裏的人可能看起來像車的一部分。"},{"en":"A human in a car means a person sitting inside a vehicle.","zh":"human in a car 指坐在車內的人。"},{"en":"From outside, a child in a car may be hard to see clearly behind glass.","zh":"從外面看，坐在車裏的孩子可能隔着玻璃難以看清。"},{"en":"To a tiger, the person may not look separate from the large moving object.","zh":"對老虎來說，那個人可能不像是與大型移動物件分開的個體。"},{"en":"This phrase is important because the car changes how the human is perceived.","zh":"這個短語很重要，因為車改變了人類被感知的方式。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":7},{"front":"appear just to be","meaning":"看起來只是","examples":[{"en":"The human may appear just to be part of the car.","zh":"那個人可能看起來只是車的一部分。"},{"en":"Appear just to be means seem to be only that thing and nothing separate.","zh":"appear just to be 指看起來只是某物，沒有獨立出來。"},{"en":"From a distance, a small shop may appear just to be part of a larger building.","zh":"從遠處看，小店可能看起來只是大型建築的一部分。"},{"en":"If a person appears to be part of a car, a tiger may not identify them as prey.","zh":"如果人看起來像車的一部分，老虎可能不會把他識別為獵物。"},{"en":"This phrase focuses on visual appearance, not actual reality.","zh":"這個短語聚焦視覺外觀，而不是實際現實。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":7},{"front":"part of the car","meaning":"車的一部分","examples":[{"en":"A tiger may see the person as part of the car.","zh":"老虎可能把那個人看成車的一部分。"},{"en":"Part of the car means one element of the whole vehicle rather than a separate object.","zh":"part of the car 指整輛車中的一部分，而不是分開的物件。"},{"en":"A child’s reflection in a window may seem like part of the car from outside.","zh":"從外面看，孩子在車窗中的倒影可能像車的一部分。"},{"en":"If the person is seen as part of the car, the tiger may ignore the human shape.","zh":"如果人被看作車的一部分，老虎可能忽略人形。"},{"en":"This phrase explains why being inside a car may change risk.","zh":"這個短語解釋為何在車內可能改變風險。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":7},{"front":"the human is safe","meaning":"人類是安全的","examples":[{"en":"The human is safe because tigers do not eat cars.","zh":"人類是安全的，因為老虎不吃車。"},{"en":"The human is safe means the person is not likely to be harmed in that situation.","zh":"the human is safe 指人在該情況下不大可能受傷。"},{"en":"A cyclist is safer when separated from traffic by a strong barrier.","zh":"當有堅固屏障把單車和車流分開，騎單車者會較安全。"},{"en":"In the passage, safety comes from how the tiger perceives the person inside the car.","zh":"在文章中，安全來自老虎如何感知車內的人。"},{"en":"This phrase describes a condition of low danger.","zh":"這個短語描述低危險狀態。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":7},{"front":"unless","meaning":"除非","examples":[{"en":"A person in a car is safe unless the car threatens the tiger.","zh":"車裏的人是安全的，除非車威脅到老虎。"},{"en":"Unless means except if.","zh":"unless 指除非；如果不是某情況就不會改變。"},{"en":"Students may use the library unless it is closed for cleaning.","zh":"學生可以使用圖書館，除非它因清潔而關閉。"},{"en":"This word introduces the condition that changes the situation.","zh":"這個詞引出會改變情況的條件。"},{"en":"It is useful for explaining exceptions.","zh":"它適合用來解釋例外情況。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":8},{"front":"menacing the tiger","meaning":"威脅老虎","examples":[{"en":"A car may be dangerous if it is menacing the tiger or its cubs.","zh":"如果汽車威脅老虎或其幼崽，它可能變得危險。"},{"en":"Menacing the tiger means threatening or frightening the tiger.","zh":"menacing the tiger 指威脅或嚇到老虎。"},{"en":"A person walking too close to an animal’s young may appear to be menacing the animal.","zh":"走得太接近動物幼崽的人，可能看起來像在威脅該動物。"},{"en":"If a tiger feels menaced, it may defend itself instead of retreating.","zh":"如果老虎感到被威脅，牠可能自衛而不是退走。"},{"en":"This phrase describes behaviour that the tiger may read as a threat.","zh":"這個短語描述老虎可能理解為威脅的行為。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":8},{"front":"cubs","meaning":"幼崽","examples":[{"en":"A tiger may attack if its cubs are threatened.","zh":"如果幼崽受到威脅，老虎可能攻擊。"},{"en":"Cubs are the young babies of animals such as tigers, lions or bears.","zh":"cubs 指老虎、獅子或熊等動物的幼小寶寶。"},{"en":"A mother animal may hide her cubs in thick grass or a den.","zh":"母獸可能把幼崽藏在長草或洞穴中。"},{"en":"Animals often become more defensive when their cubs are nearby.","zh":"當幼崽在附近，動物往往更有防衛性。"},{"en":"This word is common in wildlife writing.","zh":"這個詞常見於野生動物寫作。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":8},{"front":"in which case","meaning":"在這種情況下","examples":[{"en":"The car may threaten the tiger, in which case the tiger may charge.","zh":"汽車可能威脅老虎，在這種情況下老虎可能衝前攻擊。"},{"en":"In which case means if that situation happens, then the following result may happen.","zh":"in which case 指如果該情況發生，接下來的結果可能發生。"},{"en":"The train may be cancelled, in which case students should take the bus.","zh":"火車可能取消，在這種情況下學生應乘巴士。"},{"en":"This phrase links a possible condition with its consequence.","zh":"這個短語把可能條件與後果連接起來。"},{"en":"It is useful for explaining what happens under a specific scenario.","zh":"解釋特定情境下會發生甚麼時，它很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":8},{"front":"enraged tiger","meaning":"被激怒的老虎","examples":[{"en":"An enraged tiger may charge at a threatening car.","zh":"被激怒的老虎可能衝向有威脅性的汽車。"},{"en":"An enraged tiger is a tiger that is extremely angry.","zh":"enraged tiger 指極度憤怒的老虎。"},{"en":"An animal may become enraged if its young are threatened or it is trapped.","zh":"如果幼崽受到威脅或動物被困住，牠可能被激怒。"},{"en":"When a tiger is enraged, it may act more aggressively than usual.","zh":"當老虎被激怒，牠可能比平時更具攻擊性。"},{"en":"This phrase describes emotional intensity and danger.","zh":"這個短語描述情緒強度和危險。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":8},{"front":"may charge","meaning":"可能衝前攻擊","examples":[{"en":"A brave or enraged tiger may charge.","zh":"勇敢或被激怒的老虎可能衝前攻擊。"},{"en":"May charge means may rush forward aggressively to attack or threaten.","zh":"may charge 指可能突然向前衝，以攻擊或威嚇。"},{"en":"A bull may charge if it feels trapped or provoked.","zh":"如果公牛感到被困或被挑釁，可能衝前攻擊。"},{"en":"Charging is dangerous because the animal moves suddenly and powerfully.","zh":"衝前攻擊很危險，因為動物突然且有力地移動。"},{"en":"This phrase is often used for large animals attacking forward.","zh":"這個短語常用於大型動物向前攻擊。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":8},{"front":"on foot","meaning":"徒步；步行","examples":[{"en":"A human on foot is a different sort of puzzle.","zh":"徒步的人對老虎來說是另一種謎題。"},{"en":"On foot means walking rather than travelling by vehicle.","zh":"on foot 指步行，而不是乘車。"},{"en":"Visitors on foot may be more exposed to wildlife than visitors inside a car.","zh":"徒步遊客可能比車內遊客更容易接觸野生動物。"},{"en":"Being on foot changes how large, small or vulnerable a person appears.","zh":"徒步會改變一個人看起來的大小或脆弱程度。"},{"en":"This phrase describes the mode of movement.","zh":"這個短語描述移動方式。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":8},{"front":"a different sort of puzzle","meaning":"另一種謎題","examples":[{"en":"A standing human presents a different sort of puzzle to a tiger.","zh":"站立的人對老虎來說呈現另一種謎題。"},{"en":"A different sort of puzzle means a new kind of confusing situation that is hard to interpret.","zh":"different sort of puzzle 指一種新的、難以理解的困惑情況。"},{"en":"A silent student can be a different sort of puzzle for a teacher who expects questions.","zh":"對期待學生提問的老師來說，沉默學生可能是另一種謎題。"},{"en":"If an animal cannot interpret a shape, it may hesitate before acting.","zh":"如果動物不能理解某個形狀，牠可能在行動前猶豫。"},{"en":"This phrase frames the human body as something the tiger must make sense of.","zh":"這個短語把人體呈現為老虎必須理解的東西。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":8},{"front":"1.8 m tall","meaning":"一點八米高","examples":[{"en":"The writer asks us to imagine a man who is 1.8 m tall.","zh":"作者要求我們想像一名一點八米高的男子。"},{"en":"1.8 m tall means one point eight metres in height.","zh":"1.8 m tall 指高度為一點八米。"},{"en":"A door may be about two metres high, so a 1.8 m tall person can walk through easily.","zh":"門可能約兩米高，所以一點八米高的人可以輕易走過。"},{"en":"Height matters in the passage because the tiger sees the standing human from the front.","zh":"高度在文章中很重要，因為老虎從正面看站立的人。"},{"en":"This phrase gives a precise physical measurement.","zh":"這個短語提供精確身體尺寸。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":8},{"front":"less than 1 m tall","meaning":"不足一米高","examples":[{"en":"A tiger is less than 1 m tall.","zh":"老虎不足一米高。"},{"en":"Less than 1 m tall means shorter than one metre in height.","zh":"less than 1 m tall 指高度少於一米。"},{"en":"A desk may be less than 1 m tall but still long and wide.","zh":"書桌可能不足一米高，但仍然又長又闊。"},{"en":"The phrase helps compare a tiger’s height with a standing person’s height.","zh":"這個短語幫助比較老虎高度與站立者高度。"},{"en":"It reminds readers that height and length are different dimensions.","zh":"它提醒讀者高度和長度是不同尺寸。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":8},{"front":"up to 3 m long","meaning":"長達三米","examples":[{"en":"A tiger may be up to 3 m long from head to tail.","zh":"老虎由頭到尾可能長達三米。"},{"en":"Up to 3 m long means as long as three metres, but not necessarily always that long.","zh":"up to 3 m long 指最長可達三米，但不一定總是那麼長。"},{"en":"A small car may be up to several metres long even if it is not very tall.","zh":"小型汽車可能長達數米，即使它不太高。"},{"en":"This measurement helps explain why a tiger may judge prey by length and body shape.","zh":"這個尺寸幫助解釋為何老虎可能按長度和身形判斷獵物。"},{"en":"The phrase gives a maximum possible length.","zh":"這個短語提供最大可能長度。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":8},{"front":"from head to tail","meaning":"由頭到尾","examples":[{"en":"A tiger may measure up to 3 m from head to tail.","zh":"老虎由頭到尾可能長達三米。"},{"en":"From head to tail means measured from the front of the head to the end of the tail.","zh":"from head to tail 指從頭部前端量到尾巴末端。"},{"en":"A child drawing an animal may measure it from head to tail to compare its length.","zh":"孩子畫動物時，可能由頭到尾量度，以比較長度。"},{"en":"This measurement is useful for long-bodied animals.","zh":"這種量度對身體很長的動物很有用。"},{"en":"It differs from height, which measures from bottom to top.","zh":"它不同於高度，高度是從底部量到頂部。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":9},{"front":"face on","meaning":"從正面看","examples":[{"en":"A tiger sees a standing man face on.","zh":"老虎從正面看見一名站立男子。"},{"en":"Face on means from the front, directly facing the object or person.","zh":"face on 指從正前方、直接面向某物或某人觀看。"},{"en":"A person seen face on may look wider and clearer than from the side.","zh":"從正面看一個人，可能比從側面看更闊、更清楚。"},{"en":"In the passage, seeing a human face on may make the tiger misjudge the body’s size.","zh":"在文章中，從正面看人類可能令老虎誤判身體大小。"},{"en":"This phrase describes viewing angle.","zh":"這個短語描述觀看角度。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":9},{"front":"it might not be unreasonable for","meaning":"……可能不是不合理","examples":[{"en":"It might not be unreasonable for the tiger to misjudge the man’s size.","zh":"老虎誤判那男子的大小可能不是不合理。"},{"en":"It might not be unreasonable for someone to do something means the action or judgement could be understandable.","zh":"it might not be unreasonable for someone to do something 指某行動或判斷可能可以理解。"},{"en":"It might not be unreasonable for a teacher to worry if half the class is absent.","zh":"如果半班缺席，老師感到擔心可能不是不合理。"},{"en":"This phrase softens a claim and makes it sound fair rather than certain.","zh":"這個短語使說法較溫和，聽起來公平而非絕對。"},{"en":"It is useful when explaining why a mistake could happen.","zh":"解釋為何錯誤可能發生時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":9},{"front":"assume that","meaning":"假設；認為","examples":[{"en":"The tiger may assume that the man is much longer than he is.","zh":"老虎可能假設那男子比實際長得多。"},{"en":"To assume that something is true means to believe it without complete proof.","zh":"assume that something is true 指在沒有完整證據下相信某事是真的。"},{"en":"A student may assume that a word is familiar because it looks like another word.","zh":"學生可能因一個詞看起來像另一個詞，而假設它很熟悉。"},{"en":"Wrong assumptions can lead to wrong decisions.","zh":"錯誤假設可以導致錯誤決定。"},{"en":"This phrase is useful when perception or incomplete information shapes judgement.","zh":"當感知或不完整資訊塑造判斷時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":9},{"front":"a deer of this size","meaning":"這種大小的鹿","examples":[{"en":"A tiger might attack a deer of this size.","zh":"老虎可能會攻擊這種大小的鹿。"},{"en":"A deer of this size means a deer with similar body dimensions to the object being considered.","zh":"deer of this size 指身體尺寸與正在考慮的物體相近的鹿。"},{"en":"A hunter may judge whether an animal is prey by comparing it to a deer of this size.","zh":"獵手可能透過把某動物與這種大小的鹿比較，判斷它是否獵物。"},{"en":"If a human shape resembles a prey animal’s size, the tiger may become interested.","zh":"如果人形像獵物動物的大小，老虎可能產生興趣。"},{"en":"This phrase links visual size with hunting decision.","zh":"這個短語把視覺大小與捕獵決定連接起來。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":9},{"front":"by leaping on its back","meaning":"透過跳到其背上","examples":[{"en":"A tiger might attack the animal by leaping on its back.","zh":"老虎可能透過跳到該動物背上來攻擊牠。"},{"en":"By leaping on its back means by jumping onto the animal’s back as a method of attack.","zh":"by leaping on its back 指以跳到動物背上作為攻擊方法。"},{"en":"A cat may catch a toy mouse by leaping on it from behind.","zh":"貓可能從後方跳到玩具老鼠身上來捕捉它。"},{"en":"This method works only if the predator can identify where the prey’s back is.","zh":"這種方法只有在掠食者能辨認獵物背部位置時才有效。"},{"en":"The phrase describes the action used to attack.","zh":"這個短語描述用來攻擊的動作。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":9},{"front":"looks behind","meaning":"看向……後面","examples":[{"en":"When the tiger looks behind the man, it cannot see a back.","zh":"當老虎看向男子後面時，牠看不到背部。"},{"en":"Looks behind means directs its sight to the area at the back of someone or something.","zh":"looks behind 指把視線轉向某人或某物後方。"},{"en":"A driver looks behind before reversing the car.","zh":"司機倒車前會看向後方。"},{"en":"Looking behind a standing human may confuse the tiger if it expects to see a long back.","zh":"如果老虎預期看到長背部，看向站立人後面可能令牠困惑。"},{"en":"This phrase describes a checking action with the eyes.","zh":"這個短語描述用眼睛檢查的動作。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":9},{"front":"from the front","meaning":"從正面看","examples":[{"en":"From the front, the man may look huge to the tiger.","zh":"從正面看，這名男子對老虎來說可能顯得巨大。"},{"en":"From the front means viewed from the side facing the person or object directly.","zh":"from the front 指從直接面向人或物的一邊觀看。"},{"en":"A building may look narrow from the front but very deep from the side.","zh":"建築物從正面看可能很窄，但從側面看很深。"},{"en":"Viewing angle can change how size and shape are judged.","zh":"觀看角度可以改變人如何判斷大小和形狀。"},{"en":"This phrase helps explain visual perception.","zh":"這個短語幫助解釋視覺感知。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":9},{"front":"looked at from the side","meaning":"從側面看","examples":[{"en":"Looked at from the side, the man almost disappears.","zh":"從側面看，這名男子幾乎消失。"},{"en":"Looked at from the side means when viewed from the left or right rather than the front.","zh":"looked at from the side 指從左邊或右邊，而不是正面觀看。"},{"en":"A thin book may look large from the front but narrow when looked at from the side.","zh":"薄書從正面看可能很大，但從側面看很窄。"},{"en":"The side view can make a standing human seem much thinner.","zh":"側面視角可以令站立的人看起來瘦得多。"},{"en":"This phrase describes how perspective changes appearance.","zh":"這個短語描述角度如何改變外觀。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":9},{"front":"all but disappears","meaning":"幾乎消失","examples":[{"en":"From the side, the man all but disappears.","zh":"從側面看，這名男子幾乎消失。"},{"en":"All but disappears means almost completely disappears or becomes very hard to see.","zh":"all but disappears 指幾乎完全消失或變得很難看見。"},{"en":"A thin wire all but disappears against a dark background.","zh":"細電線在深色背景前幾乎消失。"},{"en":"If a shape almost disappears from one angle, an animal may find it confusing.","zh":"如果一個形狀從某角度幾乎消失，動物可能覺得困惑。"},{"en":"This phrase means nearly, but not absolutely, gone.","zh":"這個短語表示幾乎消失，但不是絕對消失。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":9},{"front":"very disconcerting","meaning":"非常令人困惑不安的","examples":[{"en":"This must be very disconcerting for a tiger.","zh":"這對老虎來說一定非常令人困惑不安。"},{"en":"Very disconcerting means very confusing, disturbing or unsettling.","zh":"very disconcerting 指非常令人困惑、煩亂或不安。"},{"en":"It can be very disconcerting when a familiar classroom is suddenly arranged differently.","zh":"當熟悉課室突然被重新排列，可能非常令人困惑不安。"},{"en":"If a hunter is disconcerted, it may hesitate before attacking.","zh":"如果獵手感到困惑不安，牠可能在攻擊前猶豫。"},{"en":"This phrase describes mental discomfort caused by confusion.","zh":"這個短語描述由困惑造成的心理不適。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":9},{"front":"a hunter has to be confident that","meaning":"獵手必須有信心……","examples":[{"en":"A hunter has to be confident that it can tackle its prey.","zh":"獵手必須有信心能對付獵物。"},{"en":"A hunter has to be confident that means a predator must feel sure before acting.","zh":"hunter has to be confident that 指掠食者在行動前必須感到有把握。"},{"en":"A student has to be confident that she understands the question before answering quickly.","zh":"學生在快速回答前，必須有信心自己理解題目。"},{"en":"If a hunter lacks confidence, it may avoid a risky attack.","zh":"如果獵手缺乏信心，牠可能避開高風險攻擊。"},{"en":"This phrase links confidence with successful action.","zh":"這個短語把信心與成功行動連接起來。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":10},{"front":"tackle its prey","meaning":"對付獵物","examples":[{"en":"A tiger needs confidence before it tackles its prey.","zh":"老虎在對付獵物前需要信心。"},{"en":"To tackle its prey means to attack, catch or deal with the animal it wants to hunt.","zh":"tackle its prey 指攻擊、捕捉或處理牠想獵捕的動物。"},{"en":"A cat may wait quietly before tackling a mouse.","zh":"貓可能在對付老鼠前安靜等待。"},{"en":"Predators choose the right moment because tackling prey can be dangerous.","zh":"掠食者會選擇合適時機，因為對付獵物也可能危險。"},{"en":"This phrase describes the active stage of hunting.","zh":"這個短語描述捕獵的主動階段。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":10},{"front":"when disconcerted","meaning":"在感到困惑不安時","examples":[{"en":"No hunter feels confident when disconcerted.","zh":"沒有獵手在感到困惑不安時仍會有信心。"},{"en":"When disconcerted means when confused, unsettled or disturbed.","zh":"when disconcerted 指在感到困惑、不安或被干擾時。"},{"en":"A speaker may lose confidence when disconcerted by unexpected laughter.","zh":"演講者可能因意外笑聲而感到困惑不安，從而失去信心。"},{"en":"Confusion can weaken action because the person or animal hesitates.","zh":"困惑會削弱行動，因為人或動物會猶豫。"},{"en":"This phrase links emotional disturbance with reduced confidence.","zh":"這個短語把情緒干擾與信心下降連接起來。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":10},{"front":"especially true of","meaning":"對……尤其如此","examples":[{"en":"This is especially true of a solitary hunter such as the tiger.","zh":"這對像老虎這樣的獨行獵手尤其如此。"},{"en":"Especially true of means particularly accurate when applied to a certain person, group or thing.","zh":"especially true of 指套用於某人、群體或事物時特別準確。"},{"en":"Clear instructions are useful for all students, but especially true of beginners.","zh":"清楚指示對所有學生都有用，但對初學者尤其如此。"},{"en":"When a point is especially true of one group, that group shows the idea most clearly.","zh":"當某點對一個群體尤其如此，該群體最清楚顯示這個想法。"},{"en":"This phrase narrows a general statement to a key example.","zh":"這個短語把一般說法收窄到關鍵例子。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":10},{"front":"a solitary hunter","meaning":"獨行獵手","examples":[{"en":"A tiger is a solitary hunter.","zh":"老虎是獨行獵手。"},{"en":"A solitary hunter is an animal that usually hunts alone rather than in a group.","zh":"solitary hunter 指通常獨自而不是成群捕獵的動物。"},{"en":"A cat is often a solitary hunter when it stalks a bird by itself.","zh":"貓獨自潛近鳥時，常像一個獨行獵手。"},{"en":"Solitary hunters cannot rely on companions to share risk or encourage action.","zh":"獨行獵手不能依賴同伴分擔風險或鼓勵行動。"},{"en":"This phrase contrasts tigers with group hunters such as lions.","zh":"這個短語把老虎與獅子等群體獵手作對比。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":10},{"front":"young lionesses","meaning":"年輕雌獅","examples":[{"en":"Young lionesses may encourage one another to take risks.","zh":"年輕雌獅可能鼓勵彼此冒險。"},{"en":"Young lionesses are young female lions.","zh":"young lionesses 指年輕的雌性獅子。"},{"en":"Young lionesses often learn hunting behaviour through group experience.","zh":"年輕雌獅常透過群體經驗學習捕獵行為。"},{"en":"When animals hunt together, they may attempt risks that a solitary hunter avoids.","zh":"當動物一起捕獵，牠們可能嘗試獨行獵手會避開的風險。"},{"en":"This phrase gives a contrast to the tiger’s solitary hunting style.","zh":"這個短語與老虎獨自捕獵風格形成對比。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":10},{"front":"tend to","meaning":"往往會","examples":[{"en":"Young lionesses tend to encourage one another.","zh":"年輕雌獅往往會鼓勵彼此。"},{"en":"Tend to means usually or often do something.","zh":"tend to 指通常或經常做某事。"},{"en":"Students tend to remember examples better when they are connected to daily life.","zh":"當例子與日常生活相連，學生往往會記得更好。"},{"en":"This phrase describes a general pattern, not an absolute rule.","zh":"這個短語描述一般模式，而不是絕對規則。"},{"en":"It is useful when behaviour happens often but not always.","zh":"當行為經常但不總是發生時，它很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":10},{"front":"encourage one another to","meaning":"鼓勵彼此去……","examples":[{"en":"Young lionesses encourage one another to take risks.","zh":"年輕雌獅鼓勵彼此去冒險。"},{"en":"To encourage one another to do something means to give each other confidence or support to do it.","zh":"encourage one another to do something 指彼此給予信心或支持去做某事。"},{"en":"Classmates may encourage one another to speak English during group work.","zh":"同學在小組活動中可能鼓勵彼此說英文。"},{"en":"Mutual encouragement can make difficult actions feel less frightening.","zh":"互相鼓勵可以令困難行動感覺不那麼可怕。"},{"en":"This phrase shows social support between members of a group.","zh":"這個短語顯示群體成員之間的社會支持。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":10},{"front":"take risks","meaning":"冒險","examples":[{"en":"Young lionesses may be more willing to take risks.","zh":"年輕雌獅可能更願意冒險。"},{"en":"To take risks means to do something that may lead to danger, loss or failure.","zh":"take risks 指做可能帶來危險、損失或失敗的事情。"},{"en":"A student takes a risk when she answers a difficult question in front of the class.","zh":"學生在全班面前回答困難問題時，就是在冒險。"},{"en":"Risk-taking can bring success, but it can also bring harm.","zh":"冒險可以帶來成功，但也可能帶來傷害。"},{"en":"This phrase is useful when outcomes are uncertain.","zh":"當結果不確定時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":10},{"front":"more dangerous than","meaning":"比……更危險","examples":[{"en":"The writer suggests that lions may be more dangerous than tigers.","zh":"作者暗示獅子可能比老虎更危險。"},{"en":"More dangerous than means having a higher risk of causing harm compared with something else.","zh":"more dangerous than 指與另一事物相比，造成傷害的風險更高。"},{"en":"Driving too fast in heavy rain is more dangerous than driving slowly on a dry road.","zh":"在大雨中高速駕駛比在乾路慢速駕駛更危險。"},{"en":"Something may be more dangerous because it is bolder, less predictable or more common.","zh":"某事可能因更大膽、更難預測或更常見而更危險。"},{"en":"This phrase is used for comparison of risk.","zh":"比較風險時會使用這個短語。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":10},{"front":"the theory that","meaning":"……這個理論","examples":[{"en":"The theory that tigers are confused by humans may explain rare attacks.","zh":"老虎被人類弄糊塗這個理論可能解釋襲擊罕見。"},{"en":"The theory that introduces an explanation or idea about why something happens.","zh":"the theory that 用來引出解釋某事為何發生的想法。"},{"en":"The theory that sleep improves memory is tested in many learning studies.","zh":"睡眠改善記憶這個理論在許多學習研究中被測試。"},{"en":"A theory becomes stronger when it explains evidence better than other ideas.","zh":"當一個理論比其他想法更好地解釋證據，它就更有力。"},{"en":"This phrase is useful in academic and scientific discussion.","zh":"這個短語適用於學術和科學討論。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":10},{"front":"a standing human","meaning":"站立的人","examples":[{"en":"A standing human may look confusing to a tiger.","zh":"站立的人對老虎來說可能看起來令人困惑。"},{"en":"A standing human is a person who is upright on two feet.","zh":"standing human 指用雙腳直立的人。"},{"en":"A standing human looks tall from the front but narrow from the side.","zh":"站立的人從正面看很高，但從側面看很窄。"},{"en":"This unusual shape may make a tiger unsure whether the person is prey.","zh":"這種不尋常形狀可能令老虎不確定此人是否獵物。"},{"en":"This phrase is important because posture changes visual appearance.","zh":"這個短語很重要，因為姿勢會改變視覺外觀。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":11},{"front":"both…and yet…","meaning":"既……但又……","examples":[{"en":"A standing human is both very big and yet somehow invisible.","zh":"站立的人既非常巨大，但又不知怎的看不見。"},{"en":"Both…and yet… shows that two surprising or opposite qualities are true at the same time.","zh":"both…and yet… 表示兩種令人驚訝或相反的特質同時成立。"},{"en":"A city can be both crowded and yet lonely for someone without friends.","zh":"對沒有朋友的人來說，城市可以既擁擠但又孤獨。"},{"en":"This structure helps express a paradox.","zh":"這個結構有助表達矛盾情況。"},{"en":"It is useful when something has two qualities that seem hard to combine.","zh":"當某物具有兩種看似難以並存的特質時，它很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":11},{"front":"somehow invisible","meaning":"不知怎的看不見","examples":[{"en":"From the side, a standing human may seem somehow invisible.","zh":"從側面看，站立的人可能不知怎的看不見。"},{"en":"Somehow invisible means strangely or unexpectedly hard to see.","zh":"somehow invisible 指奇怪地或出乎意料地難以看見。"},{"en":"A glass door can seem somehow invisible if it is very clean and unmarked.","zh":"如果玻璃門非常乾淨且沒有標記，它可能不知怎的看不見。"},{"en":"If a human nearly disappears from the side view, the tiger may become confused.","zh":"如果人類從側面幾乎消失，老虎可能變得困惑。"},{"en":"This phrase expresses puzzling invisibility, not literal disappearance.","zh":"這個短語表達令人費解的不可見，而不是字面消失。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":11},{"front":"the opposite should be true of","meaning":"相反情況應適用於……","examples":[{"en":"The opposite should be true of a squatting human.","zh":"相反情況應適用於蹲着的人。"},{"en":"The opposite should be true of something means the reverse situation should apply to it.","zh":"the opposite should be true of something 指相反情況應套用於某事物。"},{"en":"If bright colours attract attention, the opposite should be true of dull grey clothes.","zh":"如果鮮艷顏色吸引注意，相反情況應適用於暗灰色衣服。"},{"en":"This phrase helps compare two contrasting cases.","zh":"這個短語幫助比較兩個對立案例。"},{"en":"It is useful when reasoning from one situation to another.","zh":"從一個情況推理到另一個情況時，它很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":11},{"front":"a squatting human","meaning":"蹲着的人","examples":[{"en":"A squatting human may look more like prey to a tiger.","zh":"蹲着的人對老虎來說可能更像獵物。"},{"en":"A squatting human is a person bending low with knees bent, close to the ground.","zh":"squatting human 指屈膝低身、接近地面的人。"},{"en":"A villager squatting to cut grass may look shorter and wider than a standing person.","zh":"蹲着割草的村民可能比站立的人看起來更矮、更寬。"},{"en":"This posture can change the body shape a tiger sees.","zh":"這種姿勢可以改變老虎看到的身體形狀。"},{"en":"In the passage, squatting may make a human more vulnerable.","zh":"在文章中，蹲着可能令人體更容易受到攻擊。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":11},{"front":"half the size","meaning":"一半大小","examples":[{"en":"A squatting human is half the size of a standing one.","zh":"蹲着的人是站立者的一半大小。"},{"en":"Half the size means about fifty percent as large, tall or big as something else.","zh":"half the size 指大約是另一物的一半大、一半高或一半尺寸。"},{"en":"A folded table may be half the size it is when fully opened.","zh":"摺起的桌子可能是完全打開時的一半大小。"},{"en":"Size change can affect how an object is perceived by people or animals.","zh":"尺寸變化會影響人或動物如何感知物件。"},{"en":"This phrase expresses a clear comparison of size.","zh":"這個短語表達清楚的大小比較。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":11},{"front":"presents twice the spread of back","meaning":"呈現出兩倍的背部寬度","examples":[{"en":"A squatting human presents twice the spread of back.","zh":"蹲着的人呈現出兩倍的背部寬度。"},{"en":"Presents twice the spread of back means shows a back area that appears twice as broad or extended.","zh":"presents twice the spread of back 指顯示出看起來兩倍寬或更展開的背部區域。"},{"en":"When someone bends over, their back may look wider to an animal behind them.","zh":"當人彎腰時，對其後方的動物來說背部可能顯得更寬。"},{"en":"A wider back shape may make the person resemble a prey animal more closely.","zh":"較寬的背部形狀可能令這個人更像獵物動物。"},{"en":"This phrase explains how posture changes the visible target.","zh":"這個短語解釋姿勢如何改變可見目標。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":11},{"front":"more closely resembles","meaning":"更接近於","examples":[{"en":"A squatting human more closely resembles a medium-sized deer.","zh":"蹲着的人更接近於一隻中等大小的鹿。"},{"en":"More closely resembles means looks more similar to something else.","zh":"more closely resembles 指看起來與另一物更相似。"},{"en":"A child’s drawing may more closely resemble a cat after ears and whiskers are added.","zh":"孩子的畫加上耳朵和鬍鬚後，可能更接近於貓。"},{"en":"If a human shape resembles prey more closely, a predator may be more likely to attack.","zh":"如果人形更接近獵物，掠食者可能更有可能攻擊。"},{"en":"This phrase is used for visual or functional similarity.","zh":"這個短語用於視覺或功能上的相似。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":11},{"front":"a medium-sized deer","meaning":"中等大小的鹿","examples":[{"en":"A squatting human may resemble a medium-sized deer.","zh":"蹲着的人可能像一隻中等大小的鹿。"},{"en":"A medium-sized deer is a deer that is neither very small nor very large.","zh":"medium-sized deer 指既不很小也不很大的鹿。"},{"en":"A predator may judge a medium-sized deer as manageable prey.","zh":"掠食者可能把中等大小的鹿判斷為可處理的獵物。"},{"en":"The comparison helps explain why a crouched human shape could look attackable.","zh":"這個比較幫助解釋為何蹲下的人形可能看起來可被攻擊。"},{"en":"This phrase gives a familiar animal size reference.","zh":"這個短語提供熟悉的動物大小參照。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":11},{"front":"simply frightened of","meaning":"只是害怕……","examples":[{"en":"If tigers were simply frightened of humans, posture would not matter.","zh":"如果老虎只是害怕人類，姿勢就不會重要。"},{"en":"Simply frightened of means only afraid of something, without any more complex reason.","zh":"simply frightened of 指只是害怕某物，沒有更複雜原因。"},{"en":"If a child is simply frightened of dogs, the dog’s colour should not matter much.","zh":"如果孩子只是害怕狗，狗的顏色應該不太重要。"},{"en":"The phrase helps reject an explanation that is too simple.","zh":"這個短語幫助否定過於簡單的解釋。"},{"en":"It shows that fear alone cannot explain all the evidence.","zh":"它顯示單靠恐懼不能解釋所有證據。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":11},{"front":"no more attractive as a target than","meaning":"作為目標並不比……更吸引","examples":[{"en":"A squatting person would be no more attractive as a target than a standing one.","zh":"蹲着的人作為目標並不比站立的人更吸引。"},{"en":"No more attractive as a target than means not more likely to be chosen for attack than another option.","zh":"no more attractive as a target than 指不比另一選項更可能被選作攻擊目標。"},{"en":"If two bags look equally empty, one is no more attractive as a target for thieves than the other.","zh":"如果兩個袋子看起來同樣空，其中一個作為小偷目標並不比另一個更吸引。"},{"en":"This phrase is used to compare risk or appeal as a target.","zh":"這個短語用來比較作為目標的風險或吸引力。"},{"en":"In the passage, it helps test whether simple fear explains tiger behaviour.","zh":"在文章中，它幫助測試單純恐懼是否能解釋老虎行為。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":11},{"front":"appears not to be the case","meaning":"情況似乎並非如此","examples":[{"en":"This, however, appears not to be the case.","zh":"然而，情況似乎並非如此。"},{"en":"Appears not to be the case means seems not to be true.","zh":"appears not to be the case 指看來並非真實情況。"},{"en":"People thought the meeting would be short; this appears not to be the case.","zh":"人們以為會議會很短；情況似乎並非如此。"},{"en":"This phrase is cautious because it is based on evidence rather than absolute certainty.","zh":"這個短語較謹慎，因為它基於證據，而不是絕對肯定。"},{"en":"It is useful when rejecting an earlier assumption.","zh":"否定早前假設時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":12},{"front":"incidents of attacks on people","meaning":"襲擊人的事件","examples":[{"en":"Many incidents of attacks on people involve villagers squatting.","zh":"許多襲擊人的事件涉及村民蹲下。"},{"en":"Incidents of attacks on people are particular cases in which people are attacked.","zh":"incidents of attacks on people 指人遭受攻擊的具體案例。"},{"en":"Police reports may list incidents of attacks on people in a public park.","zh":"警方報告可能列出公園中襲擊人的事件。"},{"en":"Studying individual incidents helps researchers find patterns.","zh":"研究個別事件有助研究人員找出模式。"},{"en":"This phrase refers to concrete events, not general fear.","zh":"這個短語指具體事件，而不是一般恐懼。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":12},{"front":"involve villagers squatting","meaning":"涉及村民蹲下","examples":[{"en":"Many attacks involve villagers squatting or bending over.","zh":"許多襲擊涉及村民蹲下或彎腰。"},{"en":"Involve villagers squatting means include situations where villagers are low to the ground in a squatting posture.","zh":"involve villagers squatting 指包含村民以蹲姿接近地面的情況。"},{"en":"Field accidents may involve workers bending over and not seeing danger behind them.","zh":"田野意外可能涉及工人彎腰而沒有看到身後危險。"},{"en":"If many attacks involve the same posture, that posture may be part of the explanation.","zh":"如果許多襲擊涉及同一姿勢，該姿勢可能是解釋的一部分。"},{"en":"This phrase links body position with attack risk.","zh":"這個短語把身體姿勢與襲擊風險連接起來。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":12},{"front":"bending over","meaning":"彎腰","examples":[{"en":"Villagers may be attacked while bending over to cut grass.","zh":"村民可能在彎腰割草時被襲擊。"},{"en":"Bending over means leaning the upper body forward and downward.","zh":"bending over 指上半身向前向下傾。"},{"en":"A gardener bends over to pull weeds from the soil.","zh":"園丁彎腰從泥土中拔雜草。"},{"en":"Bending over can reduce awareness of what is happening behind or around the body.","zh":"彎腰會降低對身後或周圍情況的察覺。"},{"en":"In the passage, this posture may make a person look more like prey.","zh":"在文章中，這種姿勢可能令一個人看起來更像獵物。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":12},{"front":"cut grass for fodder","meaning":"割草作飼料","examples":[{"en":"Some villagers bend over to cut grass for fodder.","zh":"有些村民彎腰割草作飼料。"},{"en":"To cut grass for fodder means to cut grass that will be used as animal feed.","zh":"cut grass for fodder 指割取用作動物飼料的草。"},{"en":"Farmers may cut grass for fodder before the dry season.","zh":"農民可能在旱季前割草作飼料。"},{"en":"This work often requires bending low, which may change how the body appears.","zh":"這項工作常需要低身彎腰，可能改變身體外觀。"},{"en":"The phrase explains why villagers might be in a risky posture.","zh":"這個短語解釋村民為何可能處於有風險姿勢。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":12},{"front":"building material","meaning":"建築材料","examples":[{"en":"Villagers may cut grass for fodder or building material.","zh":"村民可能割草作飼料或建築材料。"},{"en":"Building material is material used to construct houses, shelters or other structures.","zh":"building material 指用來建造房屋、棚屋或其他結構的材料。"},{"en":"Wood, bricks, bamboo and grass can be building material in different communities.","zh":"木材、磚、竹和草在不同社區都可以是建築材料。"},{"en":"Collecting building material may require people to work outdoors in exposed areas.","zh":"收集建築材料可能需要人在戶外暴露地區工作。"},{"en":"This phrase explains one practical reason villagers gather grass.","zh":"這個短語解釋村民收集草的一個實際原因。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":12},{"front":"stand upright","meaning":"直立站立","examples":[{"en":"Humans stand upright, which may help them survive tiger attacks.","zh":"人類直立站立，這可能幫助他們避過老虎襲擊。"},{"en":"To stand upright means to stand straight on two feet.","zh":"stand upright 指用雙腳站直。"},{"en":"A teacher may ask students to stand upright during a presentation to look confident.","zh":"老師可能要求學生匯報時直立站立，以顯得有信心。"},{"en":"In the passage, standing upright changes the human shape seen by a tiger.","zh":"在文章中，直立站立改變了老虎看到的人類形狀。"},{"en":"This phrase describes posture and its possible protective effect.","zh":"這個短語描述姿勢及其可能的保護作用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":12},{"front":"not just…but also…","meaning":"不只是……也是……","examples":[{"en":"Standing upright is not just distinctive but also protective.","zh":"直立站立不只是獨特，也是有保護作用的。"},{"en":"Not just…but also… means one thing has both the first quality and the second quality.","zh":"not just…but also… 指某事同時具有第一個特質和第二個特質。"},{"en":"Reading is not just useful for exams but also helpful for understanding people.","zh":"閱讀不只是對考試有用，也有助理解人。"},{"en":"This structure adds a second, often more important, point.","zh":"這個結構加入第二點，而且常是更重要的一點。"},{"en":"It is useful when you want to show two connected benefits.","zh":"當你想顯示兩個相關好處時，它很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":12},{"front":"distinguishes them from","meaning":"使……有別於","examples":[{"en":"Standing upright distinguishes humans from most other species.","zh":"直立站立使人類有別於大多數其他物種。"},{"en":"To distinguish them from something means to make them different or recognisable compared with others.","zh":"distinguish them from something 指令他們與其他事物不同或容易被認出。"},{"en":"A school uniform distinguishes students from visitors on campus.","zh":"校服使學生有別於校園訪客。"},{"en":"A distinctive feature helps observers identify a group quickly.","zh":"獨特特徵幫助觀察者快速識別一個群體。"},{"en":"This phrase is useful when describing difference.","zh":"描述差異時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":12},{"front":"nearly all other species","meaning":"幾乎所有其他物種","examples":[{"en":"Humans stand upright, unlike nearly all other species.","zh":"人類直立站立，不同於幾乎所有其他物種。"},{"en":"Nearly all other species means almost every other kind of living organism.","zh":"nearly all other species 指幾乎每一種其他生物。"},{"en":"Nearly all other species in a forest move differently from humans.","zh":"森林中幾乎所有其他物種的移動方式都與人類不同。"},{"en":"The phrase emphasises that human posture is unusual in the animal world.","zh":"這個短語強調人類姿勢在動物世界中很不尋常。"},{"en":"It allows for a few exceptions without changing the general point.","zh":"它容許少數例外，但不改變整體觀點。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":12},{"front":"a factor that helped","meaning":"有助……的因素","examples":[{"en":"Standing upright may be a factor that helped humans survive.","zh":"直立站立可能是有助人類生存的因素。"},{"en":"A factor that helped means one cause or condition that contributed to a positive result.","zh":"factor that helped 指促成正面結果的一個原因或條件。"},{"en":"Good feedback may be a factor that helped a student improve quickly.","zh":"良好回饋可能是有助學生快速進步的因素。"},{"en":"A factor may help without being the only cause.","zh":"一個因素可以有幫助，但不一定是唯一原因。"},{"en":"This phrase is useful for cautious explanations.","zh":"這個短語適合謹慎解釋。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":12},{"front":"survive in","meaning":"在……中生存","examples":[{"en":"Standing upright helped humans survive in dangerous environments.","zh":"直立站立幫助人類在危險環境中生存。"},{"en":"To survive in a place or situation means to continue living despite danger or difficulty.","zh":"survive in a place or situation 指在危險或困難中繼續生活。"},{"en":"Small businesses survive in expensive cities by controlling costs carefully.","zh":"小企業透過仔細控制成本在昂貴城市中生存。"},{"en":"Survival often depends on adapting to local risks.","zh":"生存常取決於適應本地風險。"},{"en":"This phrase connects life or success with a challenging environment.","zh":"這個短語把生命或成功與具挑戰環境連接起來。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":13},{"front":"a dangerous and unpredictable environment","meaning":"危險而難以預測的環境","examples":[{"en":"Early humans lived in a dangerous and unpredictable environment.","zh":"早期人類生活在危險而難以預測的環境中。"},{"en":"A dangerous and unpredictable environment is a place where threats are serious and hard to foresee.","zh":"dangerous and unpredictable environment 指威脅嚴重且難以預見的地方。"},{"en":"A mountain rescue team works in a dangerous and unpredictable environment during storms.","zh":"山區救援隊在暴風雨中於危險而難以預測的環境工作。"},{"en":"In such conditions, posture, awareness and group behaviour may affect survival.","zh":"在這種條件下，姿勢、警覺性和群體行為都可能影響生存。"},{"en":"This phrase describes both risk and uncertainty.","zh":"這個短語同時描述風險和不確定性。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":13},{"front":"the branch of zoology","meaning":"動物學的分支","examples":[{"en":"Ethology is the branch of zoology that studies animal behaviour.","zh":"動物行為學是研究動物行為的動物學分支。"},{"en":"The branch of zoology means a specialised area within the scientific study of animals.","zh":"branch of zoology 指動物科學研究中的一個專門領域。"},{"en":"Marine biology is another branch of zoology focused on sea animals.","zh":"海洋生物學是另一個聚焦海洋動物的動物學分支。"},{"en":"A branch of a subject helps organise knowledge into more specific fields.","zh":"學科分支有助把知識組織成更具體領域。"},{"en":"This phrase is useful for defining academic disciplines.","zh":"定義學術學科時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":13},{"front":"studies the behaviour of animals","meaning":"研究動物行為","examples":[{"en":"Ethology studies the behaviour of animals in natural habitats.","zh":"動物行為學研究自然棲息地中的動物行為。"},{"en":"Studies the behaviour of animals means scientifically observes and explains what animals do.","zh":"studies the behaviour of animals 指科學地觀察並解釋動物做甚麼。"},{"en":"A researcher studies animal behaviour by watching feeding, movement and communication.","zh":"研究人員透過觀察進食、移動和溝通來研究動物行為。"},{"en":"Studying behaviour helps explain why animals attack, hide, migrate or cooperate.","zh":"研究行為有助解釋動物為何攻擊、躲藏、遷徙或合作。"},{"en":"This phrase describes the main work of ethology.","zh":"這個短語描述動物行為學的主要工作。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":13},{"front":"natural habitats","meaning":"自然棲息地","examples":[{"en":"Ethology studies animals in their natural habitats.","zh":"動物行為學在動物的自然棲息地研究牠們。"},{"en":"Natural habitats are the places where animals or plants normally live in nature.","zh":"natural habitats 指動植物在自然界中通常生活的地方。"},{"en":"A wetland is a natural habitat for many birds and insects.","zh":"濕地是許多鳥類和昆蟲的自然棲息地。"},{"en":"Studying animals in natural habitats can reveal behaviour that may not appear in cages.","zh":"在自然棲息地研究動物，可以揭示籠中未必出現的行為。"},{"en":"This phrase is important in ecology and animal behaviour.","zh":"這個短語在生態學和動物行為中很重要。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":13},{"front":"paragraph contains","meaning":"段落包含","examples":[{"en":"Students decide which paragraph contains the information.","zh":"學生判斷哪一段包含該資料。"},{"en":"Paragraph contains means a paragraph includes a particular detail, idea or example.","zh":"paragraph contains 指某段包括特定細節、想法或例子。"},{"en":"In a reading test, students scan to find which paragraph contains a reference to a theory.","zh":"在閱讀測驗中，學生掃讀以找出哪段包含對理論的提及。"},{"en":"The right paragraph may use different words from the question.","zh":"正確段落可能使用與題目不同的字眼。"},{"en":"This phrase is common in locating-information tasks.","zh":"這個短語常見於定位資訊題。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":13},{"front":"the following information","meaning":"以下資料","examples":[{"en":"The task asks students to locate the following information.","zh":"這項任務要求學生定位以下資料。"},{"en":"The following information means the details listed after the instruction.","zh":"following information 指指示之後列出的資料。"},{"en":"Students should read the following information carefully before searching the text.","zh":"學生在搜尋文本前應仔細閱讀以下資料。"},{"en":"Knowing exactly what information is needed prevents careless matching.","zh":"清楚知道需要甚麼資料，可以避免粗心配對。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":13},{"front":"write the correct letter","meaning":"寫下正確字母","examples":[{"en":"Students write the correct letter in the answer boxes.","zh":"學生在答案格中寫下正確字母。"},{"en":"To write the correct letter means to record the option letter that matches the answer.","zh":"write the correct letter 指記下與答案相配的選項字母。"},{"en":"In a matching task, students may write B instead of copying the whole paragraph name.","zh":"在配對題中，學生可能寫 B，而不是抄整個段落名稱。"},{"en":"A correct idea can lose marks if the wrong letter is written.","zh":"即使想法正確，寫錯字母也可能失分。"},{"en":"This phrase reminds students to follow the answer format exactly.","zh":"這個短語提醒學生嚴格按照答案格式作答。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":13},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生在答題紙上寫下答案。"},{"en":"An answer sheet is the official paper or form where exam answers are recorded.","zh":"answer sheet 指考試中記錄答案的正式紙張或表格。"},{"en":"A student may lose marks if answers stay in the question booklet but not on the answer sheet.","zh":"如果答案只留在題目冊而沒有寫在答題紙上，學生可能失分。"},{"en":"Checking the answer sheet helps prevent wrong numbering.","zh":"檢查答題紙有助避免題號錯配。"},{"en":"This phrase is common in exam contexts.","zh":"這個短語常見於考試語境。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":13},{"front":"a rejected explanation","meaning":"被否定的解釋","examples":[{"en":"The question asks for a rejected explanation of rare tiger attacks.","zh":"題目要求找出一個關於老虎襲擊罕見的被否定解釋。"},{"en":"A rejected explanation is an idea that the writer considers and then does not accept.","zh":"rejected explanation 指作者考慮過但不接受的想法。"},{"en":"In science, a rejected explanation may be replaced by one that fits the evidence better.","zh":"在科學中，被否定的解釋可能被更符合證據的解釋取代。"},{"en":"Identifying a rejected explanation helps students understand the writer’s argument.","zh":"識別被否定的解釋有助學生理解作者論點。"},{"en":"This phrase is useful in reading questions about reasoning.","zh":"這個短語適用於關於推理的閱讀題。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":13},{"front":"tiger attacks on humans","meaning":"老虎襲擊人類","examples":[{"en":"The passage discusses why tiger attacks on humans are rare.","zh":"文章討論為何老虎襲擊人類很罕見。"},{"en":"Tiger attacks on humans are cases where tigers physically attack people.","zh":"tiger attacks on humans 指老虎身體攻擊人的事件。"},{"en":"Reports of tiger attacks on humans can create strong fear in nearby villages.","zh":"老虎襲擊人類的報道可以在附近村莊造成強烈恐懼。"},{"en":"Studying when attacks happen helps researchers understand risk factors.","zh":"研究襲擊何時發生，有助研究人員理解風險因素。"},{"en":"This phrase focuses on the specific relationship between tigers and people.","zh":"這個短語聚焦老虎與人之間的特定關係。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":13},{"front":"might be expected to","meaning":"可能被預期會","examples":[{"en":"Tiger attacks might be expected to happen more often.","zh":"老虎襲擊可能被預期會更常發生。"},{"en":"Might be expected to means people may reasonably think something should happen.","zh":"might be expected to 指人們可能合理地認為某事應該會發生。"},{"en":"A popular café might be expected to be crowded at lunchtime.","zh":"受歡迎的咖啡店可能被預期在午餐時間很擠迫。"},{"en":"If reality differs from expectation, the writer may look for an explanation.","zh":"如果現實與預期不同，作者可能尋找解釋。"},{"en":"This phrase introduces a likely assumption.","zh":"這個短語引入一個可能的假設。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":14},{"front":"more often than they do","meaning":"比實際情況更頻繁","examples":[{"en":"Tiger attacks might be expected to happen more often than they do.","zh":"老虎襲擊可能被預期發生得比實際情況更頻繁。"},{"en":"More often than they do means more frequently than actually happens.","zh":"more often than they do 指比實際發生得更頻繁。"},{"en":"People might expect students to use the library more often than they do.","zh":"人們可能預期學生使用圖書館比實際情況更頻繁。"},{"en":"This phrase highlights a gap between expectation and reality.","zh":"這個短語突出預期與現實之間的差距。"},{"en":"It is useful when an event happens less frequently than predicted.","zh":"當事件發生頻率低於預測時，它很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":14},{"front":"examples of situations","meaning":"情況的例子","examples":[{"en":"The passage gives examples of situations in which humans are attacked.","zh":"文章給出人類被襲擊的情況例子。"},{"en":"Examples of situations are specific cases or circumstances that show when something happens.","zh":"examples of situations 指顯示某事何時發生的具體案例或情境。"},{"en":"A safety lesson may give examples of situations in which accidents occur.","zh":"安全課可能給出意外發生情況的例子。"},{"en":"Examples help readers understand a general idea through concrete cases.","zh":"例子幫助讀者透過具體案例理解一般想法。"},{"en":"This phrase is useful in explanation and exam questions.","zh":"這個短語適用於解釋和考試題。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":14},{"front":"more likely to be attacked","meaning":"較有可能被襲擊","examples":[{"en":"A squatting person may be more likely to be attacked.","zh":"蹲着的人可能較有可能被襲擊。"},{"en":"More likely to be attacked means having a higher chance of being attacked.","zh":"more likely to be attacked 指被攻擊的機會較高。"},{"en":"A pedestrian crossing a dark road without looking may be more likely to be hit.","zh":"行人若在黑暗道路上不看路橫過，可能較容易被撞。"},{"en":"In the passage, posture may increase risk by changing how the person looks to a tiger.","zh":"在文章中，姿勢可能透過改變人對老虎的外觀而增加風險。"},{"en":"This phrase describes probability, not certainty.","zh":"這個短語描述可能性，而不是確定性。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":14},{"front":"a claim about","meaning":"關於……的說法","examples":[{"en":"The question asks for a claim about the frequency of attacks.","zh":"題目要求找出關於襲擊頻率的說法。"},{"en":"A claim about something is a statement or argument concerning that topic.","zh":"claim about something 指關於某主題的陳述或論點。"},{"en":"A report may make a claim about why students are absent more often in winter.","zh":"報告可能提出關於學生冬天更常缺席原因的說法。"},{"en":"Claims should be checked against evidence before being accepted.","zh":"接受說法前，應把它與證據核對。"},{"en":"This phrase is common in reading and critical thinking tasks.","zh":"這個短語常見於閱讀和批判思考任務。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":14},{"front":"relative frequency","meaning":"相對頻率","examples":[{"en":"The passage discusses the relative frequency of tiger attacks.","zh":"文章討論老虎襲擊的相對頻率。"},{"en":"Relative frequency means how often something happens compared with another number or situation.","zh":"relative frequency 指某事相對於另一數字或情況發生的頻密程度。"},{"en":"The relative frequency of accidents may be lower in a large school than in a small one when student numbers are considered.","zh":"若考慮學生人數，大型學校的意外相對頻率可能比小學校低。"},{"en":"Looking at relative frequency helps avoid being misled by total numbers.","zh":"查看相對頻率有助避免被總數誤導。"},{"en":"This phrase is useful for comparing rates.","zh":"比較比率時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":14},{"front":"based on the principles of","meaning":"基於……的原則","examples":[{"en":"The writer gives an explanation based on the principles of ethology.","zh":"作者給出一個基於動物行為學原則的解釋。"},{"en":"Based on the principles of something means using its basic ideas as the foundation.","zh":"based on the principles of something 指以某事的基本理念作基礎。"},{"en":"A diet plan based on the principles of balanced nutrition includes different food groups.","zh":"基於均衡營養原則的飲食計劃包括不同食物類別。"},{"en":"When an explanation is based on clear principles, it is easier to follow and test.","zh":"當解釋基於清楚原則，它會更容易理解和測試。"},{"en":"This phrase links an argument to a theory or field.","zh":"這個短語把論點與理論或領域連接起來。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":14},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"Students decide whether the statements agree with the passage.","zh":"學生判斷以下陳述是否與文章一致。"},{"en":"Do the following statements agree with asks whether each statement matches the text.","zh":"do the following statements agree with 指詢問每個陳述是否與文本相符。"},{"en":"In reading tests, students should check evidence before deciding whether a statement agrees with the passage.","zh":"在閱讀測驗中，學生應先檢查證據，再判斷陳述是否與文章一致。"},{"en":"A statement may sound true but still not agree with the information given.","zh":"陳述可能聽起來正確，但仍未必與所給資料一致。"},{"en":"This phrase is common in True, False, Not Given tasks.","zh":"這個短語常見於 True, False, Not Given 題。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":14},{"front":"information given in","meaning":"……中提供的資料","examples":[{"en":"The answers must match the information given in the passage.","zh":"答案必須符合文章中提供的資料。"},{"en":"Information given in a text means facts or ideas stated or supported by that text.","zh":"information given in a text 指文本中陳述或支持的事實或想法。"},{"en":"Students should answer according to the information given in the article, not personal opinion.","zh":"學生應根據文章中提供的資料作答，而不是個人意見。"},{"en":"If information is not given in the passage, the answer may be Not Given.","zh":"如果文章中沒有提供相關資料，答案可能是 Not Given。"},{"en":"This phrase focuses on textual evidence.","zh":"這個短語聚焦文本證據。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":14},{"front":"if the statement agrees with","meaning":"如果陳述與……一致","examples":[{"en":"Students write TRUE if the statement agrees with the information.","zh":"如果陳述與資料一致，學生寫 TRUE。"},{"en":"If the statement agrees with means if the sentence matches what the source says.","zh":"if the statement agrees with 指如果句子與來源所說相符。"},{"en":"If the statement agrees with the timetable, the train time should be exactly supported.","zh":"如果陳述與時間表一致，火車時間應有確切支持。"},{"en":"Students should compare meaning carefully because wording may change the answer.","zh":"學生應仔細比較意思，因為措辭可能改變答案。"},{"en":"This phrase is part of exam-answer instructions.","zh":"這個短語是考試作答指示的一部分。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":14},{"front":"if the statement contradicts","meaning":"如果陳述與……矛盾","examples":[{"en":"Students write FALSE if the statement contradicts the information.","zh":"如果陳述與資料矛盾，學生寫 FALSE。"},{"en":"If the statement contradicts means if it says the opposite of what the source says.","zh":"if the statement contradicts 指如果陳述說出與來源相反的意思。"},{"en":"If a passage says attacks are rare, a statement saying they are common contradicts it.","zh":"如果文章說襲擊罕見，而陳述說襲擊常見，就與文章矛盾。"},{"en":"Contradiction is not the same as missing information; it directly conflicts with the text.","zh":"矛盾不同於缺少資料；它是直接與文本衝突。"},{"en":"This phrase helps students identify false answers.","zh":"這個短語幫助學生辨認錯誤答案。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":14},{"front":"no information on this","meaning":"沒有這方面的資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有這方面的資料，學生寫 NOT GIVEN。"},{"en":"No information on this means the passage does not say whether the statement is true or false.","zh":"no information on this 指文章沒有說明該陳述是真還是假。"},{"en":"If an article discusses tiger attacks but not tiger sleeping hours, there is no information on this sleeping claim.","zh":"如果文章討論老虎襲擊，但沒有討論老虎睡眠時間，就沒有這方面的睡眠資料。"},{"en":"Students should not guess when the text gives no evidence.","zh":"當文本沒有證據時，學生不應猜測。"},{"en":"This phrase is essential for Not Given answers.","zh":"這個短語對 Not Given 答案很重要。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":15},{"front":"protected species","meaning":"受保護物種","examples":[{"en":"The statement asks whether tigers in the park are a protected species.","zh":"這個陳述問公園中的老虎是否為受保護物種。"},{"en":"A protected species is an animal or plant protected by law from hunting, harm or trade.","zh":"protected species 指受法律保護、不可被獵殺、傷害或交易的動植物。"},{"en":"A government may protect a species if its population becomes dangerously small.","zh":"如果某物種數量變得危險地少，政府可能保護它。"},{"en":"Protected status can limit what people may do in a national park.","zh":"受保護地位可以限制人們在國家公園中能做甚麼。"},{"en":"This phrase belongs to conservation and wildlife law.","zh":"這個短語屬於保育和野生動物法律語境。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":15},{"front":"writers of fiction","meaning":"小說作家","examples":[{"en":"Some writers of fiction exaggerated the danger of tigers.","zh":"有些小說作家誇大了老虎的危險。"},{"en":"Writers of fiction are authors who create imagined stories rather than factual reports.","zh":"writers of fiction 指創作想像故事，而不是事實報告的作者。"},{"en":"Writers of fiction may use danger to make a story more exciting.","zh":"小說作家可能利用危險令故事更刺激。"},{"en":"Fiction can shape public beliefs even when it is not fully accurate.","zh":"即使小說並不完全準確，也可以塑造公眾信念。"},{"en":"This phrase contrasts story writers with scientists or historians.","zh":"這個短語把故事作者與科學家或歷史學家作對比。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":15},{"front":"exaggerated the danger","meaning":"誇大危險","examples":[{"en":"Some writers exaggerated the danger of tigers to humans.","zh":"有些作家誇大了老虎對人類的危險。"},{"en":"To exaggerate the danger means to make the risk sound greater than it really is.","zh":"exaggerate the danger 指把風險說得比真實情況更大。"},{"en":"A child may exaggerate the danger of a small spider because it looks frightening.","zh":"孩子可能因小蜘蛛看起來可怕而誇大其危險。"},{"en":"Exaggerated danger can lead people to fear something more than the evidence supports.","zh":"被誇大的危險可以令人比證據支持的程度更害怕某事。"},{"en":"This phrase is useful when stories or reports overstate risk.","zh":"當故事或報道誇大風險時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":15},{"front":"passed down in genes","meaning":"透過基因遺傳","examples":[{"en":"The fear of humans may be passed down in a tiger’s genes.","zh":"對人類的恐懼可能透過老虎基因遺傳下來。"},{"en":"Passed down in genes means inherited biologically from earlier generations.","zh":"passed down in genes 指透過生物方式由早前世代遺傳下來。"},{"en":"Some physical traits, such as eye colour, are passed down in genes.","zh":"一些身體特徵，例如眼睛顏色，是透過基因遺傳的。"},{"en":"If a behaviour is passed down genetically, it may appear without direct teaching.","zh":"如果行為透過基因遺傳，它可能不需直接教導就出現。"},{"en":"This phrase is used when discussing inherited features or instincts.","zh":"討論遺傳特徵或本能時，會使用這個短語。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":15},{"front":"claimed that","meaning":"聲稱","examples":[{"en":"The question asks whether Konrad Lorenz claimed that animals were more intelligent.","zh":"題目問 Konrad Lorenz 是否聲稱動物更聰明。"},{"en":"Claimed that means stated something as true, especially when others may question it.","zh":"claimed that 指把某事陳述為真，尤其是當他人可能質疑時。"},{"en":"A company claimed that its product worked faster than all competitors.","zh":"公司聲稱其產品比所有競爭對手更快有效。"},{"en":"Claims should be checked because saying something does not prove it.","zh":"聲稱需要被檢查，因為說出某事並不等於證明它。"},{"en":"This phrase is common in exam questions and argument analysis.","zh":"這個短語常見於考試題和論點分析。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":15},{"front":"more intelligent than","meaning":"比……更聰明","examples":[{"en":"The statement asks whether some animals are more intelligent than humans.","zh":"這個陳述問某些動物是否比人類更聰明。"},{"en":"More intelligent than means having greater ability to think, learn or solve problems compared with someone else.","zh":"more intelligent than 指與他人相比，思考、學習或解難能力更強。"},{"en":"A computer may be faster at calculation than humans, but that does not mean it is more intelligent in every way.","zh":"電腦計算可能比人類快，但不代表它在每方面都更聰明。"},{"en":"Comparing intelligence can be difficult because different species solve different problems.","zh":"比較智力可能很困難，因為不同物種解決不同問題。"},{"en":"This phrase is used for comparison of mental ability.","zh":"這個短語用於比較心智能力。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":15},{"front":"applying principles of","meaning":"應用……原則","examples":[{"en":"The question asks whether ethology involves applying principles of human behaviour.","zh":"題目問動物行為學是否涉及應用人類行為原則。"},{"en":"Applying principles of something means using its basic ideas to explain or handle another situation.","zh":"applying principles of something 指使用某事的基本理念來解釋或處理另一情況。"},{"en":"A teacher may apply principles of memory research when planning revision lessons.","zh":"老師規劃溫習課時，可能應用記憶研究原則。"},{"en":"Applying the wrong principles can lead to false explanations.","zh":"應用錯誤原則可以導致錯誤解釋。"},{"en":"This phrase is useful when ideas from one field are used in another.","zh":"當一個領域的想法被用於另一領域時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":15},{"front":"human behaviour","meaning":"人類行為","examples":[{"en":"Ethology does not simply apply human behaviour to animals.","zh":"動物行為學不只是把人類行為套用到動物身上。"},{"en":"Human behaviour means the ways people act, think, respond and interact.","zh":"human behaviour 指人們行動、思考、回應和互動的方式。"},{"en":"Waiting in line, apologising and helping others are examples of human behaviour in public life.","zh":"排隊、道歉和幫助他人都是公共生活中的人類行為例子。"},{"en":"Human behaviour may not explain animal behaviour because animals perceive the world differently.","zh":"人類行為未必能解釋動物行為，因為動物以不同方式感知世界。"},{"en":"This phrase is broad and appears in psychology, sociology and biology.","zh":"這個短語很廣，出現在心理學、社會學和生物學中。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":15},{"front":"choose the correct answer","meaning":"選出正確答案","examples":[{"en":"Students choose the correct answer from the options.","zh":"學生從選項中選出正確答案。"},{"en":"To choose the correct answer means to select the option that is supported by the question or passage.","zh":"choose the correct answer 指選出由題目或文章支持的選項。"},{"en":"In a reading test, students should choose the correct answer only after checking the relevant lines.","zh":"在閱讀測驗中，學生應查看相關句子後才選出正確答案。"},{"en":"A tempting answer may be wrong if it adds information not found in the passage.","zh":"誘人的答案若加入文章沒有的資料，仍可能是錯的。"},{"en":"This phrase is common in multiple-choice tasks.","zh":"這個短語常見於選擇題。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":15},{"front":"rarely attack people in cars","meaning":"很少襲擊車裏的人","examples":[{"en":"Tigers rarely attack people in cars.","zh":"老虎很少襲擊車裏的人。"},{"en":"Rarely attack people in cars means do not often attack humans who are inside vehicles.","zh":"rarely attack people in cars 指不常攻擊在車內的人類。"},{"en":"Safari visitors usually stay in vehicles because many animals ignore people in cars.","zh":"野生動物園遊客通常留在車內，因為許多動物會忽略車裏的人。"},{"en":"If the car threatens cubs, the risk may change despite the usual pattern.","zh":"如果汽車威脅幼崽，即使通常如此，風險也可能改變。"},{"en":"This phrase describes a low-frequency behaviour.","zh":"這個短語描述低頻率行為。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":15},{"front":"have learned that","meaning":"已經學會","examples":[{"en":"The option suggests that tigers have learned that cars are not dangerous.","zh":"這個選項暗示老虎已經學會汽車並不危險。"},{"en":"Have learned that means have come to understand something through experience or information.","zh":"have learned that 指透過經驗或資料理解某事。"},{"en":"A student may have learned that planning before writing saves time.","zh":"學生可能已經學會寫作前規劃可以節省時間。"},{"en":"Learned behaviour comes from experience rather than being present from birth.","zh":"學得的行為來自經驗，而不是出生時已有。"},{"en":"This phrase is useful when explaining acquired knowledge.","zh":"解釋後天獲得的知識時，這個短語很有用。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":16},{"front":"cannot be harmed","meaning":"不會受到傷害","examples":[{"en":"The option asks whether people in cars cannot be harmed.","zh":"這個選項問車裏的人是否不會受到傷害。"},{"en":"Cannot be harmed means cannot be injured or damaged.","zh":"cannot be harmed 指不能被傷害或損壞。"},{"en":"A phone in a strong case is less likely to be harmed if dropped.","zh":"手機放在堅固保護殼中，跌落時較不易受損。"},{"en":"Saying someone cannot be harmed is very strong and may ignore exceptions.","zh":"說某人不會受到傷害是很強的說法，可能忽略例外。"},{"en":"This phrase describes complete protection, not just lower risk.","zh":"這個短語描述完全保護，而不只是較低風險。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":16},{"front":"living creatures","meaning":"生物","examples":[{"en":"The option asks whether tigers see people in cars as living creatures.","zh":"這個選項問老虎是否把車裏的人看作生物。"},{"en":"Living creatures are living beings, such as animals, plants or humans.","zh":"living creatures 指有生命的存在，例如動物、植物或人類。"},{"en":"A child learns that insects are living creatures because they move, feed and grow.","zh":"孩子知道昆蟲是生物，因為牠們會移動、進食和生長。"},{"en":"If a tiger does not see a person as a separate living creature, it may not treat that person as prey.","zh":"如果老虎沒有把人看作分開的生物，牠可能不會把那人視為獵物。"},{"en":"This phrase contrasts living beings with objects.","zh":"這個短語把生物與物件作對比。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":16},{"front":"put their cubs at risk","meaning":"令幼崽陷入危險","examples":[{"en":"Tigers may attack if they think their cubs are at risk.","zh":"如果老虎認為幼崽陷入危險，牠們可能攻擊。"},{"en":"To put their cubs at risk means to place their young in possible danger.","zh":"put their cubs at risk 指令幼崽處於可能危險之中。"},{"en":"A careless visitor can put animal young at risk by walking too close to them.","zh":"粗心遊客走得太接近動物幼崽，可能令牠們陷入危險。"},{"en":"Parent animals may become aggressive when they think their young are threatened.","zh":"當親代動物認為幼崽受威脅，牠們可能變得具攻擊性。"},{"en":"This phrase explains defensive behaviour.","zh":"這個短語解釋防衛行為。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":16},{"front":"standing up","meaning":"站立","examples":[{"en":"The writer explains why tigers rarely attack a man who is standing up.","zh":"作者解釋為何老虎很少襲擊站立的人。"},{"en":"Standing up means being upright on one’s feet.","zh":"standing up 指用雙腳直立。"},{"en":"A student standing up in class looks taller and more visible than when sitting.","zh":"在課堂上站立的學生，比坐着時看起來更高、更明顯。"},{"en":"In the passage, standing up may make a human look confusing rather than like prey.","zh":"在文章中，站立可能令人體看起來令人困惑，而不是像獵物。"},{"en":"This phrase describes posture.","zh":"這個短語描述姿勢。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":16},{"front":"confused by","meaning":"被……弄糊塗","examples":[{"en":"Tigers may be confused by the shape of a standing human.","zh":"老虎可能被站立人類的形狀弄糊塗。"},{"en":"Confused by something means unable to understand or interpret it clearly.","zh":"confused by something 指不能清楚理解或解讀某事。"},{"en":"A student may be confused by a question if two options look very similar.","zh":"如果兩個選項看起來很相似，學生可能被題目弄糊塗。"},{"en":"Confusion can lead to hesitation or wrong judgement.","zh":"困惑可以導致猶豫或錯誤判斷。"},{"en":"This phrase explains why the tiger may avoid attacking.","zh":"這個短語解釋為何老虎可能避免攻擊。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":16},{"front":"the man’s shape","meaning":"那個人的形狀","examples":[{"en":"The tiger may be puzzled by the man’s shape.","zh":"老虎可能被那個人的形狀弄得困惑。"},{"en":"The man’s shape means the outline or form of the man’s body as seen from a particular angle.","zh":"the man’s shape 指從某角度看到的男子身體輪廓或形態。"},{"en":"A shadow can change a person’s shape on a wall.","zh":"影子可以改變人在牆上的形狀。"},{"en":"If the shape does not match known prey, a predator may hesitate.","zh":"如果形狀不符合已知獵物，掠食者可能猶豫。"},{"en":"This phrase focuses on visual form, not personality or identity.","zh":"這個短語聚焦視覺形態，而不是性格或身份。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":16},{"front":"lack of movement","meaning":"缺乏動作","examples":[{"en":"The option mentions the man’s lack of movement.","zh":"這個選項提到那個人缺乏動作。"},{"en":"Lack of movement means little or no physical motion.","zh":"lack of movement 指很少或沒有身體移動。"},{"en":"A teacher may notice a student’s lack of movement during sports and ask if he is injured.","zh":"老師在運動時注意到學生缺乏動作，可能會問他是否受傷。"},{"en":"Lack of movement can make an object seem less alive or less threatening.","zh":"缺乏動作可以令物件看起來較不像活物或較不具威脅。"},{"en":"This phrase describes absence of action.","zh":"這個短語描述行動的缺失。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":16},{"front":"unable to look directly at","meaning":"無法直視","examples":[{"en":"The option asks whether tigers are unable to look directly at a man.","zh":"這個選項問老虎是否無法直視一個人。"},{"en":"Unable to look directly at means not able to face or see something straight on.","zh":"unable to look directly at 指不能正面面對或觀看某物。"},{"en":"A child may be unable to look directly at the sun because it is too bright.","zh":"孩子可能因陽光太刺眼而無法直視太陽。"},{"en":"If an animal cannot look directly at something, its judgement may be affected.","zh":"如果動物不能直視某物，其判斷可能受影響。"},{"en":"This phrase describes a limitation in direct sight or attention.","zh":"這個短語描述直接視線或注意力上的限制。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":16},{"front":"more vulnerable to","meaning":"較容易受到……傷害","examples":[{"en":"A human is more vulnerable to tiger attack when squatting.","zh":"人類蹲着時較容易受到老虎襲擊傷害。"},{"en":"More vulnerable to something means more likely to be harmed by it.","zh":"more vulnerable to something 指更有可能被某事傷害。"},{"en":"Elderly people may be more vulnerable to heat during very hot weather.","zh":"在非常炎熱的天氣中，長者可能較容易受高溫傷害。"},{"en":"A person becomes more vulnerable when protection, awareness or strength is reduced.","zh":"當保護、警覺或力量減少，人就會更脆弱。"},{"en":"This phrase describes increased risk.","zh":"這個短語描述風險增加。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":16},{"front":"tiger attack","meaning":"老虎襲擊","examples":[{"en":"A squatting person may be more vulnerable to tiger attack.","zh":"蹲着的人可能較容易受到老虎襲擊。"},{"en":"A tiger attack is an incident in which a tiger attacks a person or animal.","zh":"tiger attack 指老虎攻擊人或動物的事件。"},{"en":"A village near a forest may prepare safety rules to reduce the risk of tiger attack.","zh":"靠近森林的村莊可能制定安全規則，以降低老虎襲擊風險。"},{"en":"Understanding when attacks happen can help people avoid dangerous situations.","zh":"理解襲擊何時發生，可以幫助人們避開危險情況。"},{"en":"This phrase names the danger directly.","zh":"這個短語直接指出危險。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":16},{"front":"unaware of","meaning":"沒有察覺","examples":[{"en":"The option asks whether the man is unaware of the tiger’s approach.","zh":"這個選項問那個人是否沒有察覺老虎接近。"},{"en":"Unaware of something means not knowing or noticing it.","zh":"unaware of something 指不知道或沒有注意到某事。"},{"en":"A cyclist wearing loud headphones may be unaware of a car behind him.","zh":"戴着大聲耳機的騎單車者可能沒有察覺身後汽車。"},{"en":"Being unaware of danger can increase risk because there is no time to react.","zh":"沒有察覺危險會增加風險，因為沒有時間反應。"},{"en":"This phrase describes lack of awareness.","zh":"這個短語描述缺乏警覺。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":17},{"front":"the tiger’s approach","meaning":"老虎接近","examples":[{"en":"A villager may not notice the tiger’s approach.","zh":"村民可能沒有注意到老虎接近。"},{"en":"The tiger’s approach means the tiger coming nearer.","zh":"tiger’s approach 指老虎逐漸靠近。"},{"en":"A quiet predator’s approach may be difficult to hear in long grass.","zh":"安靜掠食者在長草中的接近可能難以聽見。"},{"en":"If someone is bending over, they may not see the animal approaching from behind.","zh":"如果有人彎腰，可能看不到動物從後方接近。"},{"en":"This phrase focuses on the movement of danger toward someone.","zh":"這個短語聚焦危險向某人移動。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":17},{"front":"move his head","meaning":"移動頭部","examples":[{"en":"The option asks whether a squatting person cannot easily move his head.","zh":"這個選項問蹲着的人是否不能輕易移動頭部。"},{"en":"To move his head means to turn or lift the head to look around.","zh":"move his head 指轉動或抬起頭部四處看。"},{"en":"A person carrying a heavy box may not easily move his head to check traffic.","zh":"搬着重箱的人可能不容易移動頭部查看交通。"},{"en":"Limited head movement can reduce awareness of nearby danger.","zh":"頭部活動受限會降低對附近危險的察覺。"},{"en":"This phrase describes a physical ability to look around.","zh":"這個短語描述四處觀察的身體能力。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":17},{"front":"a better target","meaning":"更好的目標","examples":[{"en":"A squatting person may appear to be a better target.","zh":"蹲着的人可能看起來是更好的目標。"},{"en":"A better target means something that looks easier or more suitable to attack.","zh":"better target 指看起來更容易或更適合攻擊的對象。"},{"en":"A thief may see an unattended bag as a better target than one held tightly.","zh":"小偷可能把無人看管的袋子視為比被緊握的袋子更好的目標。"},{"en":"For a predator, shape, size and posture can affect whether something looks like a target.","zh":"對掠食者而言，形狀、大小和姿勢都會影響某物是否像目標。"},{"en":"This phrase describes attractiveness from the attacker’s point of view.","zh":"這個短語從攻擊者角度描述吸引力。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":17},{"front":"appears longer in relation to","meaning":"相對於……顯得較長","examples":[{"en":"The back appears longer in relation to the person’s height.","zh":"背部相對於人的高度顯得較長。"},{"en":"Appears longer in relation to means looks longer when compared with another measurement.","zh":"appears longer in relation to 指與另一尺寸比較時，看起來較長。"},{"en":"A narrow room may appear longer in relation to its width.","zh":"狹窄房間相對於其闊度可能顯得較長。"},{"en":"When someone squats, the back may look more extended compared with overall height.","zh":"當人蹲下時，背部相對於整體高度可能看起來更展開。"},{"en":"This phrase explains visual proportion.","zh":"這個短語解釋視覺比例。"}],"source":"104 - Why are so few tigers man-eaters?.pdf","sourcePage":17}],"ielts/reading/passage-2/Practice 105":[{"front":"a sense in which","meaning":"在某種意義上","examples":[{"en":"There has always been a sense in which America and Europe owned film.","zh":"在某種意義上，美國和歐洲一直主導著電影。"},{"en":"A sense in which means one particular way of looking at or understanding something.","zh":"a sense in which 是指理解某事的一種特定角度。"},{"en":"There is a sense in which homework is also training in discipline, not just revision.","zh":"在某種意義上，功課也是紀律訓練，而不只是溫習。"},{"en":"A city can belong to its residents in a sense, even if the government owns the land.","zh":"在某種意義上，即使土地由政府擁有，城市也屬於其居民。"},{"en":"This phrase is useful when a statement is partly true, but only from one angle.","zh":"當一句話部分正確，但只限於某個角度時，這個短語很有用。"}],"source":"105 - film.pdf","sourcePage":1},{"front":"own film","meaning":"主導電影；擁有電影的主導權","examples":[{"en":"America and Europe once seemed to own film as an art form.","zh":"美國和歐洲曾似乎主導電影這種藝術形式。"},{"en":"To own film here means to dominate cinema culturally, artistically, or commercially.","zh":"這裡的 own film 是指在文化、藝術或商業上主導電影。"},{"en":"A country may seem to own a sport if most champions and major events come from there.","zh":"如果多數冠軍和大型賽事都來自某國，該國可能似乎主導某項運動。"},{"en":"Hollywood seemed to own film because its studios, stars, and money shaped global cinema.","zh":"荷里活似乎主導電影，因為其片廠、明星和資金塑造全球電影。"},{"en":"This phrase does not mean legal ownership; it means having strong control or influence.","zh":"這個短語不是指法律上的擁有，而是指有強大控制力或影響力。"}],"source":"105 - film.pdf","sourcePage":1},{"front":"at the end of the nineteenth century","meaning":"在十九世紀末","examples":[{"en":"Cinema was invented at the end of the nineteenth century.","zh":"電影在十九世紀末被發明。"},{"en":"At the end of the nineteenth century means during the late 1800s.","zh":"at the end of the nineteenth century 是指在1800年代後期。"},{"en":"Many modern cities began to use electric lighting at the end of the nineteenth century.","zh":"許多現代城市在十九世紀末開始使用電燈。"},{"en":"Inventions from this period changed transport, entertainment, and communication.","zh":"這一時期的發明改變了交通、娛樂和通訊。"},{"en":"This phrase places an event near the close of the 1800s, not the beginning.","zh":"這個短語把事件放在1800年代接近結束時，而不是開初。"}],"source":"105 - film.pdf","sourcePage":1},{"front":"unfashionable places","meaning":"不時髦的地方；不起眼的地方","examples":[{"en":"Film was invented in unfashionable places such as New Jersey and Leeds.","zh":"電影在新澤西和利茲等不起眼的地方被發明。"},{"en":"Unfashionable places are locations that are not seen as stylish, famous, or culturally glamorous.","zh":"unfashionable places 是不被視為時髦、著名或有文化光環的地方。"},{"en":"A great business idea can begin in an unfashionable place, such as a small garage.","zh":"一個偉大商業想法可以始於不起眼的地方，例如小車房。"},{"en":"Unfashionable places may be ignored until something important happens there.","zh":"不起眼的地方可能一直被忽視，直到有重要事情在那裡發生。"},{"en":"This phrase contrasts ordinary locations with famous cultural centres.","zh":"這個短語把普通地方與著名文化中心作對比。"}],"source":"105 - film.pdf","sourcePage":1},{"front":"the suburbs of","meaning":"……的市郊","examples":[{"en":"Early film technology developed in the suburbs of Lyons.","zh":"早期電影科技在里昂市郊發展。"},{"en":"The suburbs of a city are the outer areas around it, often more residential than central.","zh":"the suburbs of a city 是城市周邊地區，通常比市中心更偏住宅性。"},{"en":"Many families live in the suburbs of a city because housing is quieter and cheaper.","zh":"許多家庭住在城市市郊，因為住房較安靜且較便宜。"},{"en":"New industries may begin in suburbs when central land is too expensive.","zh":"當市中心土地太昂貴，新行業可能在市郊開始。"},{"en":"This phrase locates something near a city but not in its centre.","zh":"這個短語把某事定位在城市附近，但不是市中心。"}],"source":"105 - film.pdf","sourcePage":1},{"front":"at first","meaning":"起初","examples":[{"en":"At first, people saw cinema as a mechanical curiosity.","zh":"起初，人們把電影視為一種機械奇觀。"},{"en":"At first means in the beginning, before later changes happened.","zh":"at first 是指一開始，在後來變化發生之前。"},{"en":"At first, the new student was quiet, but she became confident after a few weeks.","zh":"起初，新學生很安靜，但幾星期後變得有信心。"},{"en":"People may misunderstand an invention at first because they do not yet see its full use.","zh":"人們起初可能誤解一項發明，因為尚未看見其完整用途。"},{"en":"This phrase often prepares readers for a later contrast.","zh":"這個短語常為後面的對比作準備。"}],"source":"105 - film.pdf","sourcePage":1},{"front":"clumsy new camera-projectors","meaning":"笨重的新式攝影放映機","examples":[{"en":"The inventors saw their clumsy new camera-projectors as commercial devices.","zh":"發明者把他們笨重的新式攝影放映機視為商業設備。"},{"en":"Clumsy new camera-projectors were awkward early machines that both filmed and showed moving images.","zh":"clumsy new camera-projectors 是笨拙的早期機器，既能拍攝又能放映活動影像。"},{"en":"Early computers looked clumsy compared with today’s thin laptops and phones.","zh":"與今天輕薄的手提電腦和手機相比，早期電腦顯得笨重。"},{"en":"A clumsy machine can still be important if it opens a new field of invention.","zh":"如果笨重機器開啟新發明領域，它仍然可以很重要。"},{"en":"This phrase suggests early technology that was useful but not yet elegant.","zh":"這個短語暗示早期科技有用，但尚未精巧。"}],"source":"105 - film.pdf","sourcePage":1},{"front":"merely as","meaning":"只是作為","examples":[{"en":"They saw cinema merely as a more profitable version of lantern shows.","zh":"他們把電影只是看作幻燈片表演更賺錢的版本。"},{"en":"Merely as means only as, and not as anything more important.","zh":"merely as 是指只是作為某事，而不是更重要的東西。"},{"en":"Some people see art merely as decoration, not as a way to express ideas.","zh":"有些人把藝術只是看作裝飾，而不是表達思想的方式。"},{"en":"If teachers use videos merely as entertainment, students may not learn deeply.","zh":"如果老師把影片只是當作娛樂，學生可能學得不深。"},{"en":"This phrase often shows that someone is underestimating something.","zh":"這個短語常顯示某人低估了某事。"}],"source":"105 - film.pdf","sourcePage":1},{"front":"profitable versions of","meaning":"……的賺錢版本","examples":[{"en":"Early camera-projectors were seen as profitable versions of Victorian lantern shows.","zh":"早期攝影放映機被視為維多利亞時代幻燈片表演的賺錢版本。"},{"en":"Profitable versions of something are forms that can earn more money than the earlier model.","zh":"profitable versions of something 是比早期模式更能賺錢的形式。"},{"en":"A company may create a profitable version of a free app by adding paid features.","zh":"公司可能透過加入付費功能，創造免費應用程式的賺錢版本。"},{"en":"When entertainment becomes profitable, investors may support it more seriously.","zh":"當娛樂變得有利可圖，投資者可能更認真支持它。"},{"en":"This phrase focuses on money-making potential, not artistic value.","zh":"這個短語集中於賺錢潛力，而不是藝術價值。"}],"source":"105 - film.pdf","sourcePage":1},{"front":"Victorian lantern shows","meaning":"維多利亞時代的幻燈片表演","examples":[{"en":"Early cinema was compared with Victorian lantern shows.","zh":"早期電影被拿來與維多利亞時代的幻燈片表演比較。"},{"en":"Victorian lantern shows were older visual entertainments using projected images before cinema became popular.","zh":"Victorian lantern shows 是電影流行前使用投影影像的舊式視覺娛樂。"},{"en":"A museum may show lantern slides to explain how people enjoyed images before film.","zh":"博物館可能展示幻燈片，以解釋電影出現前人們如何欣賞影像。"},{"en":"Cinema seemed less radical at first because it resembled earlier lantern shows.","zh":"電影起初看似沒有那麼革命性，因為它類似較早的幻燈片表演。"},{"en":"This phrase places early film in an older entertainment tradition.","zh":"這個短語把早期電影放在更舊的娛樂傳統中。"}],"source":"105 - film.pdf","sourcePage":1},{"front":"mechanical curiosities","meaning":"機械奇觀；新奇機械玩意","examples":[{"en":"Early camera-projectors were treated as mechanical curiosities.","zh":"早期攝影放映機被視為機械奇觀。"},{"en":"Mechanical curiosities are interesting machines admired mainly because they are new or unusual.","zh":"mechanical curiosities 是主要因新奇或不尋常而令人感興趣的機器。"},{"en":"A robot waiter may seem like a mechanical curiosity before people see its practical value.","zh":"機械人侍應在別人看見其實用價值前，可能像一種新奇機械玩意。"},{"en":"Many inventions begin as curiosities before becoming serious tools.","zh":"許多發明一開始是新奇玩意，後來才成為嚴肅工具。"},{"en":"This phrase suggests fascination without full understanding of future importance.","zh":"這個短語暗示人們感到著迷，但尚未完全理解其未來重要性。"}],"source":"105 - film.pdf","sourcePage":1},{"front":"might have a use as","meaning":"可能可用作","examples":[{"en":"People thought cinema might have a use as a sideshow at a funfair.","zh":"人們認為電影可能可用作遊樂場的附帶表演。"},{"en":"Might have a use as means could possibly serve a particular purpose.","zh":"might have a use as 是指可能能作為某特定用途。"},{"en":"A spare classroom might have a use as a quiet study room after school.","zh":"空置課室可能可用作放學後的安靜自修室。"},{"en":"People may first see a new tool as having only a small use before discovering more possibilities.","zh":"人們起初可能只看見新工具的小用途，後來才發現更多可能性。"},{"en":"This phrase sounds uncertain and practical.","zh":"這個短語語氣不確定且偏實用。"}],"source":"105 - film.pdf","sourcePage":2},{"front":"a sideshow at a funfair","meaning":"遊樂場的附帶表演","examples":[{"en":"Early cinema was seen as a sideshow at a funfair.","zh":"早期電影被視為遊樂場的附帶表演。"},{"en":"A sideshow at a funfair is a small extra entertainment beside the main attractions.","zh":"a sideshow at a funfair 是遊樂場主要娛樂項目旁的小型附加表演。"},{"en":"A magic booth can be a sideshow at a funfair, attracting people for a few minutes.","zh":"魔術攤位可以是遊樂場的附帶表演，吸引人停留幾分鐘。"},{"en":"Seeing cinema as a sideshow meant people did not yet treat it as serious art.","zh":"把電影視為附帶表演，意味著人們尚未把它當作嚴肅藝術。"},{"en":"This phrase suggests something minor, temporary, and entertaining.","zh":"這個短語暗示某事較次要、短暫且具娛樂性。"}],"source":"105 - film.pdf","sourcePage":2},{"front":"the best of the pioneers","meaning":"最出色的先驅者","examples":[{"en":"The best of the pioneers looked beyond cinema’s fairground appeal.","zh":"最出色的先驅者看得比電影的遊樂場吸引力更遠。"},{"en":"The best of the pioneers means the most talented or visionary early innovators.","zh":"the best of the pioneers 是指最有才華或最有遠見的早期創新者。"},{"en":"The best of the pioneers in medicine saw possibilities that others missed.","zh":"醫學中最出色的先驅者看見了其他人錯過的可能性。"},{"en":"Such pioneers can turn a simple invention into a major cultural force.","zh":"這些先驅者可以把簡單發明變成重要文化力量。"},{"en":"This phrase praises the early people who saw further than most.","zh":"這個短語讚揚比大多數人看得更遠的早期人物。"}],"source":"105 - film.pdf","sourcePage":2},{"front":"look beyond","meaning":"看得比……更遠","examples":[{"en":"Some directors looked beyond the commercial uses of cinema.","zh":"有些導演看得比電影的商業用途更遠。"},{"en":"To look beyond something means to see possibilities greater than the obvious or immediate use.","zh":"look beyond something 是指看見比明顯或即時用途更大的可能性。"},{"en":"Good teachers look beyond exam scores and ask how students actually think.","zh":"好老師看得比考試分數更遠，會問學生實際如何思考。"},{"en":"Inventors succeed when they look beyond the first simple use of a tool.","zh":"發明者若看得比工具最初的簡單用途更遠，便可能成功。"},{"en":"This phrase suggests imagination and deeper vision.","zh":"這個短語暗示想像力和更深遠的眼光。"}],"source":"105 - film.pdf","sourcePage":2},{"front":"fairground properties","meaning":"遊樂場式的特質","examples":[{"en":"The pioneers looked beyond the fairground properties of their invention.","zh":"先驅者看得比其發明的遊樂場式特質更遠。"},{"en":"Fairground properties are features that make something feel like simple public entertainment.","zh":"fairground properties 是令某事感覺像簡單大眾娛樂的特徵。"},{"en":"Bright lights and surprise effects can give a performance fairground properties.","zh":"閃亮燈光和驚喜效果可以令表演帶有遊樂場式特質。"},{"en":"Cinema had fairground properties at first, but later became an artistic medium.","zh":"電影起初有遊樂場式特質，但後來成為藝術媒介。"},{"en":"This phrase refers to showy entertainment qualities rather than deep artistic value.","zh":"這個短語指炫目的娛樂特質，而不是深層藝術價值。"}],"source":"105 - film.pdf","sourcePage":2},{"front":"mostly forgotten","meaning":"大多已被遺忘","examples":[{"en":"A few directors, now mostly forgotten, saw cinema’s artistic potential.","zh":"幾位如今大多已被遺忘的導演看見了電影的藝術潛力。"},{"en":"Mostly forgotten means remembered by very few people today.","zh":"mostly forgotten 是指今天只有很少人記得。"},{"en":"Some inventors are mostly forgotten even though their work changed daily life.","zh":"有些發明者即使作品改變了日常生活，仍大多已被遺忘。"},{"en":"Artists can be mostly forgotten if later generations focus only on famous names.","zh":"如果後代只集中於名人，某些藝術家可能大多被遺忘。"},{"en":"This phrase suggests that historical importance and public memory are not the same.","zh":"這個短語暗示歷史重要性和公眾記憶並不相同。"}],"source":"105 - film.pdf","sourcePage":2},{"front":"flickering new medium","meaning":"閃爍的新媒介","examples":[{"en":"The flickering new medium was more than just entertainment.","zh":"這種閃爍的新媒介不只是娛樂。"},{"en":"A flickering new medium is a new form of communication or art that shows moving, shifting images.","zh":"flickering new medium 是一種呈現移動、變化影像的新溝通或藝術形式。"},{"en":"Early television was also a flickering new medium that changed home life.","zh":"早期電視也是一種閃爍的新媒介，改變了家庭生活。"},{"en":"A new medium may look rough at first but later become culturally powerful.","zh":"新媒介一開始可能看起來粗糙，但後來可變成文化力量。"},{"en":"This phrase captures both the technical look and novelty of early cinema.","zh":"這個短語同時捕捉早期電影的技術外觀和新奇感。"}],"source":"105 - film.pdf","sourcePage":2},{"front":"more than just","meaning":"不只是","examples":[{"en":"Cinema was more than just a diversion.","zh":"電影不只是消遣。"},{"en":"More than just means not only one simple thing, but something deeper or more important.","zh":"more than just 是指不只是某件簡單事，而是有更深或更重要的意思。"},{"en":"School is more than just exams; it also teaches habits and relationships.","zh":"學校不只是考試；它也教習慣和人際關係。"},{"en":"A film is more than just entertainment when it changes how viewers see society.","zh":"當電影改變觀眾看社會的方式時，它就不只是娛樂。"},{"en":"This phrase adds importance beyond the obvious function.","zh":"這個短語在明顯功能以外加入重要性。"}],"source":"105 - film.pdf","sourcePage":2},{"front":"a diversion","meaning":"消遣；娛樂","examples":[{"en":"Early film was first regarded as a diversion.","zh":"早期電影最初被視為一種消遣。"},{"en":"A diversion is an activity that entertains people or takes their attention away from serious matters.","zh":"diversion 是娛樂人們或把注意力從嚴肅事情轉移開的活動。"},{"en":"A short game can be a pleasant diversion during a long journey.","zh":"在漫長旅程中，小遊戲可以是令人愉快的消遣。"},{"en":"If students treat reading only as a diversion, they may not think deeply about the text.","zh":"如果學生只把閱讀視為消遣，他們可能不會深入思考文本。"},{"en":"This word often means light entertainment rather than serious work.","zh":"這個詞常指輕鬆娛樂，而不是嚴肅工作。"}],"source":"105 - film.pdf","sourcePage":2},{"front":"crass commercial invention","meaning":"粗俗的商業發明","examples":[{"en":"This crass commercial invention gradually evolved into an art.","zh":"這項粗俗的商業發明逐漸發展成一門藝術。"},{"en":"A crass commercial invention is a money-focused invention that seems crude or lacking artistic depth.","zh":"crass commercial invention 是以賺錢為中心、看似粗糙或缺乏藝術深度的發明。"},{"en":"Some people first saw television as a crass commercial invention for selling products.","zh":"有些人起初把電視視為用來賣產品的粗俗商業發明。"},{"en":"A commercial tool can later become artistic if creators discover deeper possibilities.","zh":"如果創作者發現更深可能性，商業工具後來也可以變成藝術。"},{"en":"This phrase is critical and contrasts business motives with art.","zh":"這個短語帶批評意味，並對比商業動機與藝術。"}],"source":"105 - film.pdf","sourcePage":2},{"front":"evolve as an art","meaning":"發展成一門藝術","examples":[{"en":"Cinema gradually began to evolve as an art.","zh":"電影逐漸開始發展成一門藝術。"},{"en":"To evolve as an art means to develop into a form used for beauty, expression, and meaning.","zh":"evolve as an art 是指發展成用於美感、表達和意義的形式。"},{"en":"Photography evolved as an art when people used it to express emotion, not only record faces.","zh":"當人們用攝影表達情感，而不只是記錄面孔時，攝影就發展成一門藝術。"},{"en":"A medium evolves artistically when creators test new styles and ideas.","zh":"當創作者測試新風格和想法時，媒介便在藝術上演化。"},{"en":"This phrase shows movement from simple technique to creative expression.","zh":"這個短語顯示由簡單技術走向創意表達。"}],"source":"105 - film.pdf","sourcePage":2},{"front":"glimpse its grace","meaning":"看出它的優雅之處","examples":[{"en":"D. W. Griffith glimpsed cinema’s grace in California.","zh":"D. W. Griffith 在加州看出電影的優雅之處。"},{"en":"To glimpse its grace means to briefly recognise its beauty, elegance, or artistic power.","zh":"glimpse its grace 是指短暫看見其美感、優雅或藝術力量。"},{"en":"A teacher may glimpse a shy student’s talent when reading one thoughtful sentence.","zh":"老師讀到一句有思想的句子時，可能看出害羞學生的才華。"},{"en":"Early directors glimpsed cinema’s grace before most people took film seriously.","zh":"早期導演在大多數人認真看待電影前，已看出其優雅之處。"},{"en":"This phrase suggests seeing potential that others may miss.","zh":"這個短語暗示看見別人可能錯過的潛力。"}],"source":"105 - film.pdf","sourcePage":3},{"front":"an analogue to","meaning":"……的類比；對應物","examples":[{"en":"German directors used film as an analogue to the human mind.","zh":"德國導演把電影用作人類心靈的類比。"},{"en":"An analogue to something is something that represents, parallels, or works like it in some way.","zh":"an analogue to something 是在某方面代表、平行或類似運作於某事的東西。"},{"en":"A classroom map can be an analogue to the real city when students learn directions.","zh":"學生學方向時，課室地圖可以是真實城市的對應物。"},{"en":"Film can act as an analogue to memory by jumping between images and times.","zh":"電影可以透過在影像和時間之間跳躍，成為記憶的類比。"},{"en":"This phrase means a comparison based on similar structure or function.","zh":"這個短語指基於相似結構或功能的比較。"}],"source":"105 - film.pdf","sourcePage":3},{"front":"the human mind","meaning":"人類心靈","examples":[{"en":"German directors used cinema to represent the human mind.","zh":"德國導演使用電影來呈現人類心靈。"},{"en":"The human mind means people’s thoughts, feelings, memories, imagination, and consciousness.","zh":"the human mind 是指人的思想、感受、記憶、想像和意識。"},{"en":"Dreams can show how strange and active the human mind can be.","zh":"夢境可以顯示人類心靈有多奇特和活躍。"},{"en":"Artists often try to represent the human mind through images, music, or stories.","zh":"藝術家常嘗試透過影像、音樂或故事呈現人類心靈。"},{"en":"This phrase refers to inner mental life, not the physical brain alone.","zh":"這個短語指內在精神生活，而不只是實體大腦。"}],"source":"105 - film.pdf","sourcePage":3},{"front":"the modernising city","meaning":"正在現代化的城市","examples":[{"en":"Film was used as an analogue to the modernising city.","zh":"電影被用作正在現代化的城市的類比。"},{"en":"The modernising city is a city changing through industry, transport, technology, and new social life.","zh":"modernising city 是透過工業、交通、科技和新社會生活而改變的城市。"},{"en":"Crowded streets and electric lights can show a modernising city in film.","zh":"擁擠街道和電燈可以在電影中展示正在現代化的城市。"},{"en":"A modernising city may feel exciting but also confusing and unstable.","zh":"正在現代化的城市可能令人興奮，也可能令人困惑和不穩。"},{"en":"This phrase captures urban change, not simply a modern-looking place.","zh":"這個短語捕捉城市變化，而不只是外觀現代的地方。"}],"source":"105 - film.pdf","sourcePage":3},{"front":"emphasise its properties","meaning":"強調其特質","examples":[{"en":"Soviet directors emphasised cinema’s intellectual properties.","zh":"蘇聯導演強調電影的知性特質。"},{"en":"To emphasise its properties means to focus on and highlight its particular qualities.","zh":"emphasise its properties 是指集中並突出某事的特定品質。"},{"en":"A teacher may emphasise a poem’s sound patterns before discussing its meaning.","zh":"老師可能先強調詩的聲音模式，再討論其意思。"},{"en":"Directors emphasise film’s visual properties when they use strong images and editing.","zh":"導演使用強烈影像和剪接時，就是強調電影的視覺特質。"},{"en":"This phrase means drawing attention to what makes something distinctive.","zh":"這個短語指把注意力引向某事的獨特之處。"}],"source":"105 - film.pdf","sourcePage":3},{"front":"agitational and intellectual properties","meaning":"鼓動性和知性的特質","examples":[{"en":"Soviets emphasised film’s agitational and intellectual properties.","zh":"蘇聯人強調電影的鼓動性和知性特質。"},{"en":"Agitational and intellectual properties are qualities that stir political feeling and provoke thought.","zh":"agitational and intellectual properties 是激發政治情感並引發思考的特質。"},{"en":"A documentary has agitational power if it pushes viewers to demand change.","zh":"如果紀錄片推動觀眾要求改變，它就有鼓動力量。"},{"en":"A film has intellectual value when it makes viewers question ideas, systems, or history.","zh":"當電影令觀眾質疑思想、制度或歷史時，它就有知性價值。"},{"en":"This phrase links cinema with both emotion and thinking.","zh":"這個短語把電影與情感和思考同時連接起來。"}],"source":"105 - film.pdf","sourcePage":3},{"front":"reconfigure something on a scale","meaning":"以……規模重新塑造……","examples":[{"en":"The Italians reconfigured cinema on an operatic scale.","zh":"意大利人以歌劇般的宏大規模重新塑造電影。"},{"en":"To reconfigure something on a scale means to reshape it with a particular size, style, or level of ambition.","zh":"reconfigure something on a scale 是指以某種大小、風格或抱負水平重新塑造某事。"},{"en":"A school may reconfigure its library on a community scale by turning it into a public learning space.","zh":"學校可以以社區規模重新塑造圖書館，把它變成公共學習空間。"},{"en":"Reconfiguring a project on a larger scale can make it more expensive and more impressive.","zh":"以更大規模重新塑造項目，可能令它更昂貴也更令人印象深刻。"},{"en":"This phrase suggests redesigning something with a clear level of grandeur or scope.","zh":"這個短語暗示以清晰的宏大程度或範圍重新設計某事。"}],"source":"105 - film.pdf","sourcePage":3},{"front":"on an operatic scale","meaning":"以歌劇般的宏大規模","examples":[{"en":"Italian directors reconfigured cinema on an operatic scale.","zh":"意大利導演以歌劇般的宏大規模重新塑造電影。"},{"en":"On an operatic scale means in a grand, dramatic, emotional, and large-scale way.","zh":"on an operatic scale 是指以宏大、戲劇化、情感強烈且大型的方式。"},{"en":"The wedding was planned on an operatic scale, with music, lights, and hundreds of guests.","zh":"那場婚禮以歌劇般的宏大規模策劃，有音樂、燈光和數百名賓客。"},{"en":"A film made on an operatic scale may use huge sets and powerful emotions.","zh":"以歌劇般規模製作的電影可能使用巨型佈景和強烈情感。"},{"en":"This phrase suggests grandeur and drama rather than small realism.","zh":"這個短語暗示宏大和戲劇性，而不是小型寫實。"}],"source":"105 - film.pdf","sourcePage":3},{"front":"heady decades","meaning":"令人興奮的年代","examples":[{"en":"The first decades of cinema were heady and exciting.","zh":"電影最初幾十年是令人興奮的年代。"},{"en":"Heady decades are years full of excitement, rapid change, and strong possibility.","zh":"heady decades 是充滿興奮、快速變化和強烈可能性的年代。"},{"en":"The early years of the internet were heady decades for young technology companies.","zh":"互聯網早期是年輕科技公司的令人興奮年代。"},{"en":"A heady period can inspire creativity because people feel old limits are disappearing.","zh":"令人興奮的時期可以激發創意，因為人們覺得舊限制正在消失。"},{"en":"This phrase suggests energy, ambition, and sometimes overconfidence.","zh":"這個短語暗示能量、抱負，有時也帶有過度自信。"}],"source":"105 - film.pdf","sourcePage":3},{"front":"first decades of cinema","meaning":"電影最初幾十年","examples":[{"en":"The first decades of cinema changed the art form rapidly.","zh":"電影最初幾十年快速改變了這種藝術形式。"},{"en":"The first decades of cinema means the early years after film was invented.","zh":"first decades of cinema 是指電影被發明後的早期年代。"},{"en":"During cinema’s first decades, filmmakers were still discovering what the medium could do.","zh":"在電影最初幾十年，電影製作人仍在發現這種媒介能做甚麼。"},{"en":"Early experiments in these decades shaped later editing, acting, and storytelling.","zh":"這幾十年的早期實驗塑造了後來的剪接、演技和敘事。"},{"en":"This phrase refers to cinema’s formative period.","zh":"這個短語指電影的形成期。"}],"source":"105 - film.pdf","sourcePage":3},{"front":"can be forgiven for assuming that","meaning":"以為……也情有可原","examples":[{"en":"America and Europe can be forgiven for assuming that they dominated cinema.","zh":"美國和歐洲以為自己主導電影，也情有可原。"},{"en":"Can be forgiven for assuming that means it is understandable that someone believed something.","zh":"can be forgiven for assuming that 是指某人相信某事是可以理解的。"},{"en":"A teacher can be forgiven for assuming students were tired after a week of exams.","zh":"老師以為學生在一星期考試後很累，也是情有可原的。"},{"en":"People may assume wrongly when early evidence seems to support their view.","zh":"當早期證據似乎支持某看法時，人們可能作出錯誤假設。"},{"en":"This phrase softens criticism by showing why the mistake was understandable.","zh":"這個短語透過顯示錯誤可以理解，來緩和批評。"}],"source":"105 - film.pdf","sourcePage":3},{"front":"the only game in town","meaning":"唯一重要的參與者；唯一主角","examples":[{"en":"America and Europe assumed that they were the only game in town.","zh":"美國和歐洲以為自己是唯一重要的電影主角。"},{"en":"The only game in town means the only important option, player, or source of influence.","zh":"the only game in town 是指唯一重要選項、參與者或影響來源。"},{"en":"Before online shopping, the village store was the only game in town for many families.","zh":"網上購物出現前，村中小店對許多家庭而言是唯一重要選擇。"},{"en":"A company may become careless if it thinks it is the only game in town.","zh":"如果公司以為自己是唯一重要參與者，它可能變得自滿。"},{"en":"This phrase is informal and often suggests overconfidence.","zh":"這個短語較口語，常暗示過度自信。"}],"source":"105 - film.pdf","sourcePage":4},{"front":"in less than twenty years","meaning":"在不到二十年內","examples":[{"en":"Western cinema changed dramatically in less than twenty years.","zh":"西方電影在不到二十年內發生巨大變化。"},{"en":"In less than twenty years means before a full period of twenty years had passed.","zh":"in less than twenty years 是指在完整二十年過去之前。"},{"en":"In less than twenty years, smartphones changed how people work, shop, and communicate.","zh":"在不到二十年內，智能手機改變了人們工作、購物和溝通的方式。"},{"en":"Rapid change can surprise people when it happens in less than one generation.","zh":"當變化在不到一代人的時間內發生，人們可能會感到驚訝。"},{"en":"This phrase stresses speed over a relatively short historical period.","zh":"這個短語強調在相對短的歷史時期中速度很快。"}],"source":"105 - film.pdf","sourcePage":4},{"front":"grow out of all recognition","meaning":"變得面目全非；發展得難以辨認","examples":[{"en":"Western cinema had grown out of all recognition.","zh":"西方電影已發展得面目全非。"},{"en":"To grow out of all recognition means to change so much that the original form is hard to recognise.","zh":"grow out of all recognition 是指改變得太多，以致原來形式難以辨認。"},{"en":"The small fishing village grew out of all recognition after hotels and highways were built.","zh":"酒店和公路建成後，小漁村變得面目全非。"},{"en":"A simple app can grow out of all recognition when millions of users shape its development.","zh":"當數百萬用戶塑造其發展，簡單應用程式可以變得難以辨認。"},{"en":"This phrase suggests dramatic transformation.","zh":"這個短語暗示劇烈轉變。"}],"source":"105 - film.pdf","sourcePage":4},{"front":"its unknowns","meaning":"原本默默無聞的人","examples":[{"en":"Cinema’s unknowns became the most famous people in the world.","zh":"電影中原本默默無聞的人變成世界上最有名的人。"},{"en":"Its unknowns means the people connected with it who were once not famous.","zh":"its unknowns 是指與某事相關、曾經不出名的人。"},{"en":"A new sport may turn its unknowns into national heroes after one major tournament.","zh":"一項新運動可能在一場大型比賽後，把原本默默無聞的人變成國民英雄。"},{"en":"Film transformed ordinary performers into stars because audiences saw their faces everywhere.","zh":"電影把普通表演者變成明星，因為觀眾到處看見他們的臉。"},{"en":"This phrase contrasts earlier obscurity with later fame.","zh":"這個短語對比早期默默無聞與後來成名。"}],"source":"105 - film.pdf","sourcePage":4},{"front":"financial backers","meaning":"出資者；財務支持者","examples":[{"en":"Financial backers did not expect Asian cinema to grow so quickly.","zh":"出資者沒有預期亞洲電影會發展得如此迅速。"},{"en":"Financial backers are people or organisations that provide money for a project.","zh":"financial backers 是為項目提供資金的人或機構。"},{"en":"A small theatre may need financial backers before it can stage a new play.","zh":"小劇場可能需要財務支持者，才能上演新劇。"},{"en":"Backers often influence creative work because their money makes production possible.","zh":"出資者常影響創作，因為其資金令製作成為可能。"},{"en":"This phrase focuses on funding support, not artistic creation itself.","zh":"這個短語集中於資金支持，而不是藝術創作本身。"}],"source":"105 - film.pdf","sourcePage":4},{"front":"it never occurred to someone that","meaning":"某人從未想到","examples":[{"en":"It never occurred to Western backers that Asia might develop film industries.","zh":"西方出資者從未想到亞洲可能發展出電影工業。"},{"en":"It never occurred to someone that means someone never thought of that possibility.","zh":"it never occurred to someone that 是指某人從未想到某種可能性。"},{"en":"It never occurred to me that the quiet student might be afraid to ask questions.","zh":"我從未想到那名安靜學生可能害怕提問。"},{"en":"People miss opportunities when it never occurs to them that others can innovate too.","zh":"當人們從未想到別人也能創新時，就會錯過機會。"},{"en":"This phrase often shows surprise about an overlooked idea.","zh":"這個短語常顯示對被忽略想法的驚訝。"}],"source":"105 - film.pdf","sourcePage":4},{"front":"another continent","meaning":"另一個大洲","examples":[{"en":"Another continent borrowed cinema and made it its own.","zh":"另一個大洲借用了電影，並把它變成自己的東西。"},{"en":"Another continent means a different large landmass or world region from the one first discussed.","zh":"another continent 是指與最初討論地區不同的另一大片陸地或世界區域。"},{"en":"A fashion trend can begin in Europe and later be reshaped on another continent.","zh":"時裝潮流可以始於歐洲，後來在另一個大洲被重新塑造。"},{"en":"When an invention moves to another continent, local cultures may change its use.","zh":"當發明傳到另一個大洲，本地文化可能改變其用途。"},{"en":"This phrase widens the discussion geographically.","zh":"這個短語在地理上擴闊討論。"}],"source":"105 - film.pdf","sourcePage":4},{"front":"borrow their magic box","meaning":"借用他們的神奇盒子","examples":[{"en":"Other countries borrowed the magic box of cinema.","zh":"其他國家借用了電影這個神奇盒子。"},{"en":"To borrow their magic box means to take up a powerful new tool first created elsewhere.","zh":"borrow their magic box 是指採用最初由別處創造的強大新工具。"},{"en":"A school may borrow another country’s teaching model but adapt it to local needs.","zh":"學校可能借用另一國家的教學模式，但按本地需要調整。"},{"en":"Borrowing a technology does not mean copying its original culture exactly.","zh":"借用一項科技不代表完全複製其原本文化。"},{"en":"This phrase is metaphorical and presents cinema as a wondrous invention.","zh":"這個短語是比喻，把電影呈現為神奇發明。"}],"source":"105 - film.pdf","sourcePage":4},{"front":"make something its own","meaning":"把……變成自己的東西","examples":[{"en":"Asian countries borrowed cinema and made it their own.","zh":"亞洲國家借用電影，並把它變成自己的東西。"},{"en":"To make something one’s own means to adapt it until it reflects one’s identity, needs, or style.","zh":"make something one’s own 是指調整某事，使它反映自己的身份、需要或風格。"},{"en":"A student can make a study method her own by changing it to fit her routine.","zh":"學生可以透過按自己作息修改學習方法，把它變成自己的方法。"},{"en":"Cultures make imported ideas their own when they add local language, humour, and values.","zh":"當文化加入本地語言、幽默和價值時，就把外來思想變成自己的東西。"},{"en":"This phrase suggests creative adaptation, not simple copying.","zh":"這個短語暗示創造性改造，而不是簡單複製。"}],"source":"105 - film.pdf","sourcePage":4},{"front":"film industries","meaning":"電影工業","examples":[{"en":"Film industries were emerging in Shanghai, Bombay and Tokyo.","zh":"電影工業正在上海、孟買和東京興起。"},{"en":"Film industries are the businesses, studios, workers, and systems that produce and distribute films.","zh":"film industries 是製作和發行電影的企業、片廠、工作者和系統。"},{"en":"Local film industries need directors, actors, writers, cinemas, investors, and audiences.","zh":"本地電影工業需要導演、演員、編劇、戲院、投資者和觀眾。"},{"en":"Film industries grow when technology, money, talent, and markets come together.","zh":"當科技、資金、人才和市場結合，電影工業就會成長。"},{"en":"This phrase refers to organised production, not just individual films.","zh":"這個短語指有組織的製作，而不只是個別電影。"}],"source":"105 - film.pdf","sourcePage":4},{"front":"emerge","meaning":"出現；興起","examples":[{"en":"Film industries began to emerge in several Asian cities.","zh":"電影工業開始在幾個亞洲城市興起。"},{"en":"To emerge means to appear, develop, or become noticeable.","zh":"emerge 是指出現、發展或變得明顯。"},{"en":"A new student leader may emerge when the class faces a difficult project.","zh":"當班級面對困難項目時，新的學生領袖可能出現。"},{"en":"New industries emerge when demand, technology, and investment support them.","zh":"當需求、科技和投資支持時，新行業會興起。"},{"en":"This word suggests a gradual appearance rather than a sudden arrival.","zh":"這個詞暗示逐漸出現，而不是突然到來。"}],"source":"105 - film.pdf","sourcePage":4},{"front":"outgrow those in the West","meaning":"發展得比西方更大","examples":[{"en":"Some Asian film industries would outgrow those in the West.","zh":"有些亞洲電影工業後來會發展得比西方更大。"},{"en":"To outgrow those in the West means to become larger or more productive than Western equivalents.","zh":"outgrow those in the West 是指變得比西方同類更大或更高產。"},{"en":"A small online shop may outgrow older local stores if demand rises quickly.","zh":"如果需求快速上升，小型網店可能發展得比舊本地商店更大。"},{"en":"Industries can outgrow rivals when they reach bigger audiences or produce more goods.","zh":"當行業接觸更大觀眾或生產更多產品時，就可能發展得比對手更大。"},{"en":"This phrase compares growth across regions.","zh":"這個短語比較不同地區的成長。"}],"source":"105 - film.pdf","sourcePage":5},{"front":"between 1930 and 1935","meaning":"在1930年至1935年間","examples":[{"en":"Between 1930 and 1935, China produced more than 500 films.","zh":"在1930年至1935年間，中國製作了超過500部電影。"},{"en":"Between 1930 and 1935 means during the years from 1930 to 1935.","zh":"between 1930 and 1935 是指1930年至1935年的期間。"},{"en":"Between 2010 and 2015, many schools began using tablets in class.","zh":"在2010年至2015年間，許多學校開始在課堂使用平板電腦。"},{"en":"Giving a date range helps readers understand when a trend happened.","zh":"給出日期範圍有助讀者理解趨勢何時發生。"},{"en":"This phrase marks a specific historical period.","zh":"這個短語標記一段特定歷史時期。"}],"source":"105 - film.pdf","sourcePage":5},{"front":"conventionally made","meaning":"以傳統方式製作","examples":[{"en":"Most Chinese films were conventionally made in studios.","zh":"大多數中國電影在片廠中以傳統方式製作。"},{"en":"Conventionally made means produced in the normal or traditional way for that time.","zh":"conventionally made 是指按當時正常或傳統方式製作。"},{"en":"A conventionally made cake follows a familiar recipe rather than experimental methods.","zh":"以傳統方式製作的蛋糕會跟隨熟悉食譜，而不是實驗方法。"},{"en":"Films can be conventionally made but still include fresh themes or realistic details.","zh":"電影可以以傳統方式製作，但仍加入新鮮主題或寫實細節。"},{"en":"This phrase contrasts standard production with unusual or experimental production.","zh":"這個短語對比標準製作與不尋常或實驗式製作。"}],"source":"105 - film.pdf","sourcePage":5},{"front":"studios in Shanghai","meaning":"上海的電影製片廠","examples":[{"en":"Many Chinese films were made in studios in Shanghai.","zh":"許多中國電影在上海的電影製片廠製作。"},{"en":"Studios in Shanghai were film-production spaces located in Shanghai.","zh":"studios in Shanghai 是位於上海的電影製作空間。"},{"en":"A city with many studios can become a centre for actors, directors, and investors.","zh":"有許多製片廠的城市可以成為演員、導演和投資者的中心。"},{"en":"Studios support film production by providing sets, equipment, staff, and controlled space.","zh":"製片廠透過提供佈景、設備、人手和受控空間來支援電影製作。"},{"en":"This phrase identifies Shanghai as an important production location.","zh":"這個短語指出上海是一個重要製作地點。"}],"source":"105 - film.pdf","sourcePage":5},{"front":"without soundtracks","meaning":"沒有聲軌","examples":[{"en":"Many Chinese films of the period were made without soundtracks.","zh":"該時期許多中國電影沒有聲軌。"},{"en":"Without soundtracks means with no recorded sound, music, or spoken dialogue attached to the film.","zh":"without soundtracks 是指電影沒有附上錄製聲音、音樂或對白。"},{"en":"Early silent films were shown without soundtracks, so musicians often played live music.","zh":"早期無聲電影沒有聲軌，因此音樂人常現場演奏。"},{"en":"A video without a soundtrack may rely more on images and subtitles.","zh":"沒有聲軌的影片可能更依賴影像和字幕。"},{"en":"This phrase explains why such films are described as silent.","zh":"這個短語解釋為何這類電影被稱為無聲電影。"}],"source":"105 - film.pdf","sourcePage":5},{"front":"introduce elements of realism","meaning":"引入寫實元素","examples":[{"en":"Chinese directors introduced elements of realism to their stories.","zh":"中國導演在故事中引入寫實元素。"},{"en":"To introduce elements of realism means to add details that make a story feel closer to real life.","zh":"introduce elements of realism 是指加入令故事更貼近現實生活的細節。"},{"en":"A school drama can introduce realism by showing ordinary classrooms and family problems.","zh":"校園劇可以透過展示普通課室和家庭問題來引入寫實。"},{"en":"Realistic elements can make viewers feel that a story reflects their own world.","zh":"寫實元素可以令觀眾覺得故事反映自己的世界。"},{"en":"This phrase means adding realism, not making the whole work documentary-like.","zh":"這個短語指加入寫實，而不是把整部作品變成紀錄片。"}],"source":"105 - film.pdf","sourcePage":5},{"front":"elements of realism","meaning":"寫實元素","examples":[{"en":"The best Chinese directors added elements of realism to their films.","zh":"最好的中國導演在電影中加入寫實元素。"},{"en":"Elements of realism are details that make art feel believable, everyday, or socially true.","zh":"elements of realism 是令藝術作品感覺可信、日常或符合社會真實的細節。"},{"en":"A film about workers may use real streets and simple dialogue as elements of realism.","zh":"關於工人的電影可能使用真實街道和簡單對白作為寫實元素。"},{"en":"Realistic details can make emotional scenes more convincing.","zh":"寫實細節可以令情感場面更有說服力。"},{"en":"This phrase points to parts of realism inside a larger artistic work.","zh":"這個短語指較大藝術作品中的寫實部分。"}],"source":"105 - film.pdf","sourcePage":5},{"front":"be regularly voted among","meaning":"經常被選為……之一","examples":[{"en":"Some early Chinese films are regularly voted among the country’s best films.","zh":"有些早期中國電影經常被選為該國最佳電影之一。"},{"en":"To be regularly voted among something means often chosen by critics or audiences as part of a top group.","zh":"be regularly voted among something 是指經常被評論者或觀眾選入頂尖群組。"},{"en":"A novel may be regularly voted among the best books for teenagers.","zh":"一本小說可能經常被選為最適合青少年的書之一。"},{"en":"Repeated voting suggests long-lasting respect rather than temporary popularity.","zh":"反覆被選中暗示長久尊重，而不只是短暫流行。"},{"en":"This phrase usually appears in rankings or polls.","zh":"這個短語通常出現在排名或投票中。"}],"source":"105 - film.pdf","sourcePage":5},{"front":"among the best ever made","meaning":"有史以來最佳之一","examples":[{"en":"The Peach Girl is regarded as among the best films ever made in China.","zh":"《桃花泣血記》被視為中國有史以來最佳電影之一。"},{"en":"Among the best ever made means considered one of the finest examples in history.","zh":"among the best ever made 是指被認為是歷史上最出色例子之一。"},{"en":"Some teachers regard that documentary as among the best ever made for history classes.","zh":"有些老師把那部紀錄片視為歷史課有史以來最佳教材之一。"},{"en":"A work reaches this status when later generations still admire it.","zh":"當後代仍然欣賞某作品，它就達到這種地位。"},{"en":"This phrase gives very high praise.","zh":"這個短語給予非常高的讚譽。"}],"source":"105 - film.pdf","sourcePage":5},{"front":"follow a different course","meaning":"走上不同道路","examples":[{"en":"India followed a different course in the development of cinema.","zh":"印度在電影發展上走上不同道路。"},{"en":"To follow a different course means to develop in another direction or pattern.","zh":"follow a different course 是指朝另一方向或模式發展。"},{"en":"Two students may follow different courses after graduation because their goals differ.","zh":"兩名學生畢業後可能因目標不同而走上不同道路。"},{"en":"A country’s film industry follows a different course when language, music, and markets shape it differently.","zh":"當語言、音樂和市場以不同方式塑造電影業時，它就走上不同道路。"},{"en":"This phrase compares separate paths of development.","zh":"這個短語比較不同發展路徑。"}],"source":"105 - film.pdf","sourcePage":5},{"front":"the arrival of talkies","meaning":"有聲電影的出現","examples":[{"en":"The arrival of talkies changed film in the West and India.","zh":"有聲電影的出現改變了西方和印度電影。"},{"en":"The arrival of talkies means the time when films with recorded sound became available.","zh":"the arrival of talkies 是指有錄製聲音的電影出現之時。"},{"en":"The arrival of smartphones changed how students communicate and search for information.","zh":"智能手機的出現改變了學生溝通和搜尋資訊的方式。"},{"en":"When talkies arrived, filmmakers had new possibilities for music, speech, and song.","zh":"有聲電影出現後，電影製作人有了音樂、說話和歌曲的新可能性。"},{"en":"This phrase marks a technological turning point in cinema.","zh":"這個短語標誌電影科技的一個轉折點。"}],"source":"105 - film.pdf","sourcePage":5},{"front":"talkies","meaning":"有聲電影","examples":[{"en":"Talkies gave birth to the musical in the West.","zh":"有聲電影在西方催生了音樂劇電影。"},{"en":"Talkies are films with recorded speech and sound, unlike silent films.","zh":"talkies 是有錄製說話和聲音的電影，不同於無聲電影。"},{"en":"Early audiences were excited by talkies because actors’ voices could finally be heard.","zh":"早期觀眾對有聲電影感到興奮，因為終於能聽到演員聲音。"},{"en":"Talkies changed acting because performers had to speak clearly as well as move expressively.","zh":"有聲電影改變了演技，因為表演者既要清楚說話，也要有表情地動作。"},{"en":"This word is historical and mainly refers to early sound films.","zh":"這個詞帶歷史意味，主要指早期有聲電影。"}],"source":"105 - film.pdf","sourcePage":6},{"front":"give birth to","meaning":"催生","examples":[{"en":"The arrival of talkies gave birth to a new genre.","zh":"有聲電影的出現催生了一種新類型。"},{"en":"To give birth to something means to create or lead to the beginning of it.","zh":"give birth to something 是指創造某事或導致其開始。"},{"en":"Online shopping gave birth to new delivery businesses.","zh":"網上購物催生了新的送貨業務。"},{"en":"A new technology can give birth to new habits, jobs, and art forms.","zh":"新科技可以催生新習慣、新工作和新藝術形式。"},{"en":"This phrase is metaphorical when used outside childbirth.","zh":"這個短語用於分娩以外時是比喻。"}],"source":"105 - film.pdf","sourcePage":6},{"front":"a new genre","meaning":"新類型","examples":[{"en":"The musical became a new genre after sound arrived.","zh":"聲音出現後，音樂劇電影成為一種新類型。"},{"en":"A new genre is a new category or style of art, film, music, or writing.","zh":"new genre 是藝術、電影、音樂或寫作中的新類別或風格。"},{"en":"Superhero films became a major genre when audiences repeatedly supported them.","zh":"當觀眾反覆支持，超級英雄電影成為主要類型。"},{"en":"A new genre appears when creators combine techniques in a recognisable way.","zh":"當創作者以可辨認方式結合技巧，新類型就會出現。"},{"en":"This phrase focuses on a new type of creative work.","zh":"這個短語集中於新的創作類別。"}],"source":"105 - film.pdf","sourcePage":6},{"front":"the musical","meaning":"音樂劇電影","examples":[{"en":"The musical became an important genre in Western cinema.","zh":"音樂劇電影成為西方電影中的重要類型。"},{"en":"The musical is a film or stage genre in which songs and music are central to the story.","zh":"musical 是歌曲和音樂對故事非常核心的電影或舞台類型。"},{"en":"A musical may use songs to express feelings that ordinary dialogue cannot fully show.","zh":"音樂劇電影可能用歌曲表達普通對白無法完全顯示的情感。"},{"en":"Musicals became easier to make after film sound technology improved.","zh":"電影聲音技術改善後，音樂劇電影變得更容易製作。"},{"en":"This genre depends on performance, rhythm, and emotional expression.","zh":"這種類型依賴表演、節奏和情感表達。"}],"source":"105 - film.pdf","sourcePage":6},{"front":"musical interludes","meaning":"音樂插曲","examples":[{"en":"Indian films often included musical interludes.","zh":"印度電影常包含音樂插曲。"},{"en":"Musical interludes are sections of music or song inserted between parts of a film or performance.","zh":"musical interludes 是插入電影或表演不同部分之間的音樂或歌曲段落。"},{"en":"A school play may include musical interludes while the stage scenery changes.","zh":"校園劇可能在舞台佈景轉換時加入音樂插曲。"},{"en":"Musical interludes can pause the plot and give viewers emotion, spectacle, or entertainment.","zh":"音樂插曲可以暫停情節，並給觀眾情感、場面或娛樂。"},{"en":"This phrase suggests music as a built-in part of the structure.","zh":"這個短語暗示音樂是結構中的內建部分。"}],"source":"105 - film.pdf","sourcePage":6},{"front":"stylistically wide-ranging","meaning":"風格上更廣泛多樣","examples":[{"en":"Indian films were stylistically more wide-ranging than Western musicals.","zh":"印度電影在風格上比西方音樂劇電影更廣泛多樣。"},{"en":"Stylistically wide-ranging means using many different artistic styles or tones.","zh":"stylistically wide-ranging 是指使用許多不同藝術風格或語調。"},{"en":"A lesson can be stylistically wide-ranging if it includes storytelling, debate, images, and music.","zh":"如果課堂包括故事、辯論、圖片和音樂，它可以在風格上很廣泛多樣。"},{"en":"A wide-ranging style can attract different audiences because it offers variety.","zh":"多樣風格可以吸引不同觀眾，因為它提供變化。"},{"en":"This phrase describes variety in form, not just subject matter.","zh":"這個短語描述形式上的多樣性，而不只是題材。"}],"source":"105 - film.pdf","sourcePage":6},{"front":"encompass","meaning":"包含；涵蓋","examples":[{"en":"Indian films encompassed realism and escapist dance.","zh":"印度電影包含寫實和逃避現實式舞蹈。"},{"en":"To encompass means to include or cover a wide range of things.","zh":"encompass 是指包括或涵蓋廣泛事物。"},{"en":"A good history course should encompass politics, culture, daily life, and ordinary people.","zh":"好的歷史課程應涵蓋政治、文化、日常生活和普通人。"},{"en":"A film that encompasses comedy and tragedy can feel emotionally rich.","zh":"同時包含喜劇和悲劇的電影，可以在情感上很豐富。"},{"en":"This word suggests broad inclusion.","zh":"這個詞暗示廣泛包含。"}],"source":"105 - film.pdf","sourcePage":6},{"front":"escapist dance","meaning":"逃避現實式舞蹈","examples":[{"en":"Indian films often included escapist dance sequences.","zh":"印度電影常包含逃避現實式舞蹈片段。"},{"en":"Escapist dance is dance that offers fantasy, pleasure, or temporary escape from real problems.","zh":"escapist dance 是提供幻想、愉悅或暫時逃離現實問題的舞蹈。"},{"en":"A bright musical scene can provide escapist pleasure after a serious plot moment.","zh":"在嚴肅情節之後，明亮的音樂場面可以提供逃避現實式愉悅。"},{"en":"Escapist dance may attract viewers who want beauty and joy, not only realism.","zh":"逃避現實式舞蹈可能吸引想要美感和快樂，而不只是寫實的觀眾。"},{"en":"This phrase connects dance with fantasy and emotional release.","zh":"這個短語把舞蹈與幻想和情感釋放連接起來。"}],"source":"105 - film.pdf","sourcePage":6},{"front":"individual sequences","meaning":"個別片段","examples":[{"en":"Different styles could appear within individual sequences.","zh":"不同風格可以出現在個別片段之中。"},{"en":"Individual sequences are separate scenes or sections within a film.","zh":"individual sequences 是電影中的獨立場面或段落。"},{"en":"A director may make one sequence funny and another quiet and tragic.","zh":"導演可能把一個片段拍得搞笑，另一個拍得安靜而悲傷。"},{"en":"Variation between sequences can make a long film feel lively.","zh":"片段之間的變化可以令長片感覺更有活力。"},{"en":"This phrase refers to parts of a film, not the whole film.","zh":"這個短語指電影部分，而不是整部電影。"}],"source":"105 - film.pdf","sourcePage":6},{"front":"rather than","meaning":"而不是","examples":[{"en":"Indian films were often three hours long rather than ninety minutes.","zh":"印度電影通常長達三小時，而不是九十分鐘。"},{"en":"Rather than means instead of one thing, another thing is true or chosen.","zh":"rather than 是指真正情況或選擇是某事，而不是另一事。"},{"en":"A teacher may use discussion rather than a long lecture to keep students active.","zh":"老師可能用討論而不是長講課來令學生保持主動。"},{"en":"Choosing depth rather than speed can help students understand difficult topics.","zh":"選擇深度而不是速度，可以幫助學生理解困難題目。"},{"en":"This phrase shows a clear contrast between two alternatives.","zh":"這個短語清楚顯示兩個選項之間的對比。"}],"source":"105 - film.pdf","sourcePage":6},{"front":"the cost of such productions","meaning":"這類製作的成本","examples":[{"en":"The cost of such productions shaped Indian cinema.","zh":"這類製作的成本塑造了印度電影。"},{"en":"The cost of such productions means the money needed to make films or performances of that kind.","zh":"cost of such productions 是指製作這類電影或表演所需的金錢。"},{"en":"The cost of a school concert may include costumes, lighting, music, and staff time.","zh":"學校音樂會的成本可能包括服裝、燈光、音樂和員工時間。"},{"en":"High production costs can force filmmakers to reach larger audiences to recover money.","zh":"高製作成本可以迫使電影製作人接觸更大觀眾，以收回資金。"},{"en":"This phrase links creative style with economic pressure.","zh":"這個短語把創作風格與經濟壓力連接起來。"}],"source":"105 - film.pdf","sourcePage":6},{"front":"result in","meaning":"導致","examples":[{"en":"The high cost of productions resulted in a distinctive national style.","zh":"高製作成本導致一種獨特的民族電影風格。"},{"en":"To result in something means to cause it to happen.","zh":"result in 是指導致某事發生。"},{"en":"Poor sleep can result in weak concentration the next day.","zh":"睡眠不足可能導致第二天專注力差。"},{"en":"High costs can result in films designed for wider audiences.","zh":"高成本可能導致電影被設計成面向更廣泛觀眾。"},{"en":"This phrase connects a cause with its outcome.","zh":"這個短語把原因與結果連接起來。"}],"source":"105 - film.pdf","sourcePage":7},{"front":"a distinctive national style","meaning":"獨特的民族電影風格","examples":[{"en":"Indian cinema developed a distinctive national style.","zh":"印度電影發展出一種獨特的民族電影風格。"},{"en":"A distinctive national style is a recognisable style linked to one country’s culture and industry.","zh":"distinctive national style 是與一國文化和產業相關、可辨認的風格。"},{"en":"Japanese design has a distinctive national style when simplicity and balance are emphasised.","zh":"當日本設計強調簡潔和平衡時，就有獨特民族風格。"},{"en":"A national style becomes distinctive when audiences can recognise its themes, rhythm, and images.","zh":"當觀眾能辨認其主題、節奏和影像時，民族風格就變得獨特。"},{"en":"This phrase suggests uniqueness at the level of a whole country’s art.","zh":"這個短語暗示整個國家藝術層面的獨特性。"}],"source":"105 - film.pdf","sourcePage":7},{"front":"the centre of what is now known as","meaning":"現稱為……的中心","examples":[{"en":"Bombay became the centre of what is now known as Bollywood.","zh":"孟買成為現稱為寶萊塢的中心。"},{"en":"The centre of what is now known as means the main location of something that later received its current name.","zh":"the centre of what is now known as 是指某事物的主要地點，而該事物後來有了現在的名稱。"},{"en":"A small workshop may become the centre of what is now known as a global brand.","zh":"一間小工作室可能成為現稱為全球品牌的中心。"},{"en":"This phrase links a historical place with a later familiar term.","zh":"這個短語把歷史地點與後來熟悉名稱連接起來。"},{"en":"It helps readers understand that the name may not have been used at the time.","zh":"它幫助讀者明白當時未必已使用這個名稱。"}],"source":"105 - film.pdf","sourcePage":7},{"front":"Bollywood","meaning":"寶萊塢","examples":[{"en":"Bombay became the centre of the film industry now known as Bollywood.","zh":"孟買成為現稱為寶萊塢的電影工業中心。"},{"en":"Bollywood is the Hindi-language commercial film industry centred historically in Bombay, now Mumbai.","zh":"Bollywood 是歷史上以孟買，即今日孟買為中心的印地語商業電影工業。"},{"en":"Many Bollywood films include songs, dance, romance, family conflict, and social themes.","zh":"許多寶萊塢電影包含歌曲、舞蹈、愛情、家庭衝突和社會主題。"},{"en":"Bollywood became influential because its films reached large audiences in India and abroad.","zh":"寶萊塢影響力大，因為其電影接觸印度和海外大量觀眾。"},{"en":"This word refers to an industry, not just one film style.","zh":"這個詞指一個產業，而不只是一種電影風格。"}],"source":"105 - film.pdf","sourcePage":7},{"front":"performed in Hindi","meaning":"以印地語演出","examples":[{"en":"Many Indian films were performed in Hindi.","zh":"許多印度電影以印地語演出。"},{"en":"Performed in Hindi means acted, sung, or spoken using the Hindi language.","zh":"performed in Hindi 是指使用印地語演戲、唱歌或說話。"},{"en":"A school play performed in English may help students practise pronunciation.","zh":"以英語演出的校園劇可以幫助學生練習發音。"},{"en":"Films performed in one widely understood language can reach a larger national audience.","zh":"以一種廣泛被理解的語言演出的電影，可以接觸更大全國觀眾。"},{"en":"This phrase focuses on the language of performance.","zh":"這個短語集中於演出的語言。"}],"source":"105 - film.pdf","sourcePage":7},{"front":"numerous regional languages","meaning":"眾多地區語言","examples":[{"en":"The films used Hindi rather than numerous regional languages.","zh":"這些電影使用印地語，而不是眾多地區語言。"},{"en":"Numerous regional languages are many languages used in different local areas of a country.","zh":"numerous regional languages 是一個國家不同地方使用的許多語言。"},{"en":"India has numerous regional languages, so language choice can affect a film’s audience.","zh":"印度有眾多地區語言，因此語言選擇會影響電影觀眾。"},{"en":"Using one common language may help distribution but may also reduce local variety.","zh":"使用一種共同語言可能有助發行，但也可能減少本地多樣性。"},{"en":"This phrase highlights linguistic diversity within one country.","zh":"這個短語突顯一國內部的語言多樣性。"}],"source":"105 - film.pdf","sourcePage":7},{"front":"address themes","meaning":"探討主題","examples":[{"en":"Indian films addressed social and peasant themes.","zh":"印度電影探討社會和農民主題。"},{"en":"To address themes means to deal with or explore important subjects in a work.","zh":"address themes 是指在作品中處理或探討重要題材。"},{"en":"A novel may address themes of friendship, poverty, and justice.","zh":"小說可能探討友誼、貧窮和正義等主題。"},{"en":"Films address social themes when they show how ordinary people are affected by society.","zh":"當電影展示普通人如何受社會影響時，就是在探討社會主題。"},{"en":"This phrase is about subject matter and meaning.","zh":"這個短語關於題材和意義。"}],"source":"105 - film.pdf","sourcePage":7},{"front":"social and peasant themes","meaning":"社會和農民主題","examples":[{"en":"Indian films often addressed social and peasant themes.","zh":"印度電影常探討社會和農民主題。"},{"en":"Social and peasant themes are subjects about society, village life, farming, class, and ordinary people.","zh":"social and peasant themes 是關於社會、鄉村生活、農業、階級和普通人的題材。"},{"en":"A film about debt in rural villages deals with social and peasant themes.","zh":"關於農村債務的電影就是處理社會和農民主題。"},{"en":"Such themes can make cinema feel connected to real community problems.","zh":"這類主題可以令電影感覺與真實社區問題相連。"},{"en":"This phrase contrasts ordinary lives with elite or purely glamorous stories.","zh":"這個短語把普通人生活與精英或純粹華麗故事作對比。"}],"source":"105 - film.pdf","sourcePage":7},{"front":"in an optimistic and romantic way","meaning":"以樂觀而浪漫的方式","examples":[{"en":"Indian films addressed social themes in an optimistic and romantic way.","zh":"印度電影以樂觀而浪漫的方式探討社會主題。"},{"en":"In an optimistic and romantic way means with hope, emotion, beauty, and belief in positive outcomes.","zh":"in an optimistic and romantic way 是指帶著希望、情感、美感和對正面結果的相信。"},{"en":"A film can show poverty in an optimistic way if it focuses on courage and community.","zh":"如果電影集中於勇氣和社區，它可以用樂觀方式呈現貧窮。"},{"en":"Romantic treatment can make difficult problems feel emotionally uplifting.","zh":"浪漫化處理可以令困難問題在情感上更振奮。"},{"en":"This phrase suggests a hopeful style rather than a dark or cynical one.","zh":"這個短語暗示希望式風格，而不是陰暗或犬儒式風格。"}],"source":"105 - film.pdf","sourcePage":7},{"front":"find markets in","meaning":"在……找到市場","examples":[{"en":"Indian films found markets in the Middle East, Africa and the Soviet Union.","zh":"印度電影在中東、非洲和蘇聯找到市場。"},{"en":"To find markets in places means to gain audiences or buyers there.","zh":"find markets in places 是指在那些地方獲得觀眾或買家。"},{"en":"A small food brand may find markets in nearby cities before going overseas.","zh":"小型食品品牌可能先在附近城市找到市場，再走向海外。"},{"en":"Films find new markets when language, music, and emotion appeal across borders.","zh":"當語言、音樂和情感跨越國界吸引人時，電影就能找到新市場。"},{"en":"This phrase focuses on commercial reach.","zh":"這個短語集中於商業覆蓋範圍。"}],"source":"105 - film.pdf","sourcePage":7},{"front":"the Middle East","meaning":"中東","examples":[{"en":"Indian films found audiences in the Middle East.","zh":"印度電影在中東找到觀眾。"},{"en":"The Middle East is a region including countries in western Asia and nearby areas.","zh":"the Middle East 是包括西亞及附近地區國家的區域。"},{"en":"Businesses entering the Middle East may need to understand local languages and customs.","zh":"進入中東市場的企業可能需要理解本地語言和習俗。"},{"en":"Film markets in the Middle East can be shaped by language, religion, and family viewing habits.","zh":"中東電影市場可能受語言、宗教和家庭觀影習慣塑造。"},{"en":"This phrase names a broad geographical region.","zh":"這個短語命名一個廣闊地理區域。"}],"source":"105 - film.pdf","sourcePage":7},{"front":"rival something in size","meaning":"在規模上與……匹敵","examples":[{"en":"Japan’s film industry did not rival India’s in size.","zh":"日本電影工業在規模上沒有與印度匹敵。"},{"en":"To rival something in size means to be as large as it or able to compete with it in scale.","zh":"rival something in size 是指在大小或規模上與某事相當或能競爭。"},{"en":"A new shopping mall may rival the old city centre in size.","zh":"新購物中心在規模上可能與舊市中心匹敵。"},{"en":"An industry can be artistically important even if it does not rival another in size.","zh":"一個行業即使規模上不與另一個匹敵，也可以在藝術上重要。"},{"en":"This phrase compares scale, not quality.","zh":"這個短語比較規模，而不是品質。"}],"source":"105 - film.pdf","sourcePage":8},{"front":"be unusual in other ways","meaning":"在其他方面不同尋常","examples":[{"en":"Japan’s film industry was unusual in other ways.","zh":"日本電影工業在其他方面不同尋常。"},{"en":"To be unusual in other ways means to be different for reasons other than the one just mentioned.","zh":"be unusual in other ways 是指因剛才提到以外的原因而不同。"},{"en":"A school may be small, but it may be unusual in other ways, such as its teaching freedom.","zh":"一間學校可能很小，但在其他方面不同尋常，例如有教學自由。"},{"en":"Japan’s industry was not the largest, but its studio system gave directors special power.","zh":"日本電影業不是最大，但其片廠制度給導演特殊權力。"},{"en":"This phrase shifts attention to a different kind of distinctiveness.","zh":"這個短語把注意力轉向另一種獨特性。"}],"source":"105 - film.pdf","sourcePage":8},{"front":"whereas","meaning":"然而；相比之下","examples":[{"en":"Whereas Hollywood centred on producers, Tokyo gave directors more power.","zh":"荷里活以監製為中心，然而東京給予導演更多權力。"},{"en":"Whereas is used to contrast two different facts or systems.","zh":"whereas 用來對比兩個不同事實或制度。"},{"en":"Some schools focus on exams, whereas others focus on projects and discussion.","zh":"有些學校集中於考試，相比之下，另一些集中於項目和討論。"},{"en":"Hollywood and Tokyo developed differently because authority was placed in different hands.","zh":"荷里活和東京發展不同，因為權威被放在不同人手中。"},{"en":"This word makes comparison clear and direct.","zh":"這個詞令比較清楚直接。"}],"source":"105 - film.pdf","sourcePage":8},{"front":"the central figure","meaning":"核心人物","examples":[{"en":"In Hollywood, the producer was the central figure.","zh":"在荷里活，監製是核心人物。"},{"en":"The central figure is the most important person in a system, event, or story.","zh":"central figure 是制度、事件或故事中最重要的人。"},{"en":"In a school play, the director may be the central figure during rehearsals.","zh":"在校園劇排練中，導演可能是核心人物。"},{"en":"A central figure has influence because others depend on their decisions.","zh":"核心人物有影響力，因為其他人依賴其決定。"},{"en":"This phrase identifies who holds main power or importance.","zh":"這個短語指出誰擁有主要權力或重要性。"}],"source":"105 - film.pdf","sourcePage":8},{"front":"choose the stories","meaning":"選擇故事","examples":[{"en":"In Tokyo, the director chose the stories.","zh":"在東京，導演選擇故事。"},{"en":"To choose the stories means to decide which narratives or scripts will be filmed or told.","zh":"choose the stories 是指決定哪些敘事或劇本會被拍攝或講述。"},{"en":"A teacher chooses stories that help students understand courage, conflict, and culture.","zh":"老師選擇幫助學生理解勇氣、衝突和文化的故事。"},{"en":"Whoever chooses the stories can shape what audiences see and remember.","zh":"誰選擇故事，誰就能塑造觀眾看見和記住的東西。"},{"en":"This phrase links creative power with selection.","zh":"這個短語把創作權力與選擇連接起來。"}],"source":"105 - film.pdf","sourcePage":8},{"front":"hire the producer and actors","meaning":"聘請監製和演員","examples":[{"en":"The director hired the producer and actors in Tokyo.","zh":"在東京，導演聘請監製和演員。"},{"en":"To hire the producer and actors means to choose and employ the people who organise and perform the film.","zh":"hire the producer and actors 是指選擇並聘用組織和演出電影的人。"},{"en":"A theatre director may hire actors after auditions.","zh":"劇場導演可能在試鏡後聘請演員。"},{"en":"The power to hire staff gives a director strong control over a production.","zh":"聘請人員的權力使導演對製作有強大控制。"},{"en":"This phrase shows authority inside the film-making system.","zh":"這個短語顯示電影製作制度中的權威。"}],"source":"105 - film.pdf","sourcePage":8},{"front":"the model was that of","meaning":"其模式是……","examples":[{"en":"The model was that of an artist and his studio of apprentices.","zh":"其模式是藝術家與其學徒工作室。"},{"en":"The model was that of means the system resembled a particular arrangement or example.","zh":"the model was that of 是指該制度類似某種安排或例子。"},{"en":"The school’s model was that of a workshop, where students learned by doing.","zh":"那所學校的模式是工作坊，學生透過實作學習。"},{"en":"A business model can shape who has authority and how people learn.","zh":"商業模式可以塑造誰有權威，以及人們如何學習。"},{"en":"This phrase explains a system by comparing it with a familiar pattern.","zh":"這個短語透過熟悉模式來解釋一個制度。"}],"source":"105 - film.pdf","sourcePage":8},{"front":"studio of apprentices","meaning":"學徒工作室","examples":[{"en":"The Japanese model resembled an artist and his studio of apprentices.","zh":"日本模式類似藝術家和其學徒工作室。"},{"en":"A studio of apprentices is a workplace where learners train under an experienced master.","zh":"studio of apprentices 是學習者在有經驗師傅指導下受訓的工作場所。"},{"en":"A chef may teach young cooks in a kitchen that works like a studio of apprentices.","zh":"廚師可能在像學徒工作室的廚房中教年輕廚師。"},{"en":"Apprentices learn through repeated practice, observation, and gradual responsibility.","zh":"學徒透過反覆練習、觀察和逐步承擔責任來學習。"},{"en":"This phrase suggests training through close work with a senior figure.","zh":"這個短語暗示透過與資深人物近距離工作來受訓。"}],"source":"105 - film.pdf","sourcePage":8},{"front":"be employed by","meaning":"受僱於","examples":[{"en":"A future director was employed by a studio as an assistant.","zh":"未來導演受僱於片廠，擔任助理。"},{"en":"To be employed by an organisation means to work for it in exchange for pay.","zh":"be employed by an organisation 是指為某機構工作並獲得薪酬。"},{"en":"A nurse may be employed by a public hospital.","zh":"護士可能受僱於公立醫院。"},{"en":"Being employed by a studio gave young filmmakers access to training and contacts.","zh":"受僱於片廠讓年輕電影人接觸培訓和人脈。"},{"en":"This phrase identifies the organisation someone works for.","zh":"這個短語指出某人為哪個機構工作。"}],"source":"105 - film.pdf","sourcePage":8},{"front":"assistant","meaning":"助理","examples":[{"en":"A future director often began as an assistant.","zh":"未來導演常先由助理做起。"},{"en":"An assistant is a person who helps someone more senior with work or organisation.","zh":"assistant 是幫助較資深人士處理工作或組織事務的人。"},{"en":"A classroom assistant may help prepare materials and support students.","zh":"課堂助理可能幫忙準備材料和支援學生。"},{"en":"Working as an assistant can teach a beginner practical skills through observation.","zh":"擔任助理可以讓初學者透過觀察學習實用技能。"},{"en":"This role is often a starting point before greater responsibility.","zh":"這個角色通常是承擔更大責任前的起點。"}],"source":"105 - film.pdf","sourcePage":8},{"front":"future director","meaning":"未來導演","examples":[{"en":"A future director learned his craft by working with senior figures.","zh":"未來導演透過與資深人物共事學習自己的技藝。"},{"en":"A future director is someone who will later become a director but is still training or gaining experience.","zh":"future director 是後來會成為導演，但仍在受訓或累積經驗的人。"},{"en":"A young assistant may be a future manager if she learns quickly and takes responsibility.","zh":"如果年輕助理學得快並願意負責，她可能是未來經理。"},{"en":"Future directors often learn by watching how experienced filmmakers solve problems.","zh":"未來導演常透過觀察有經驗電影人如何解決問題來學習。"},{"en":"This phrase looks at someone’s later role from an earlier stage.","zh":"這個短語從早期階段看某人後來的角色。"}],"source":"105 - film.pdf","sourcePage":8},{"front":"senior figures","meaning":"資深人物","examples":[{"en":"Young assistants worked with senior figures in the studio.","zh":"年輕助理在片廠中與資深人物共事。"},{"en":"Senior figures are experienced and important people in an organisation or field.","zh":"senior figures 是組織或領域中有經驗且重要的人。"},{"en":"New teachers often learn from senior figures in their department.","zh":"新老師常向部門中的資深人物學習。"},{"en":"Senior figures can shape a workplace because younger staff follow their example.","zh":"資深人物可以塑造工作場所，因為年輕員工會跟隨其榜樣。"},{"en":"This phrase suggests both experience and authority.","zh":"這個短語同時暗示經驗和權威。"}],"source":"105 - film.pdf","sourcePage":9},{"front":"learn one’s craft","meaning":"學習自己的技藝","examples":[{"en":"A future director learned his craft from senior filmmakers.","zh":"未來導演從資深電影人那裡學習自己的技藝。"},{"en":"To learn one’s craft means to develop the practical skills of a profession or art.","zh":"learn one’s craft 是指培養某專業或藝術的實用技能。"},{"en":"A young baker learns her craft by making bread every morning with an experienced chef.","zh":"年輕麵包師每天早上與有經驗廚師做麵包，學習自己的技藝。"},{"en":"Craft is learned through practice, correction, and watching skilled people work.","zh":"技藝透過練習、修正和觀察熟練人士工作而學成。"},{"en":"This phrase suggests deep hands-on training, not just theory.","zh":"這個短語暗示深入實作訓練，而不只是理論。"}],"source":"105 - film.pdf","sourcePage":9},{"front":"gain authority","meaning":"取得權威","examples":[{"en":"A future director gradually gained authority in the studio.","zh":"未來導演逐漸在片廠中取得權威。"},{"en":"To gain authority means to earn power, respect, or the right to make decisions.","zh":"gain authority 是指獲得權力、尊重或作決定的權利。"},{"en":"A team leader gains authority when colleagues trust her judgement.","zh":"當同事信任團隊領袖的判斷時，她就取得權威。"},{"en":"Experience can help someone gain authority because others see their skill.","zh":"經驗可以幫助某人取得權威，因為別人看見其能力。"},{"en":"This phrase shows authority as something built over time.","zh":"這個短語顯示權威是隨時間建立的。"}],"source":"105 - film.pdf","sourcePage":9},{"front":"be promoted to director","meaning":"晉升為導演","examples":[{"en":"An assistant could be promoted to director after gaining experience.","zh":"助理累積經驗後可以晉升為導演。"},{"en":"To be promoted to director means to move up to the role of director.","zh":"be promoted to director 是指升到導演職位。"},{"en":"An employee may be promoted to manager after showing strong leadership.","zh":"員工展現強大領導力後，可能晉升為經理。"},{"en":"Promotion often happens when a person has proved skill and reliability.","zh":"晉升通常在人證明自己有能力和可靠後發生。"},{"en":"This phrase describes career advancement.","zh":"這個短語描述事業晉升。"}],"source":"105 - film.pdf","sourcePage":9},{"front":"select screenplays and performers","meaning":"選擇劇本和演員","examples":[{"en":"The director had the power to select screenplays and performers.","zh":"導演有權選擇劇本和演員。"},{"en":"To select screenplays and performers means to choose scripts and the actors or artists who will appear.","zh":"select screenplays and performers 是指選擇劇本以及出演的演員或表演者。"},{"en":"A theatre director selects performers who fit the characters and tone of the play.","zh":"劇場導演會選擇適合角色和劇作語調的表演者。"},{"en":"Choosing the screenplay shapes the story, while choosing performers shapes how it feels.","zh":"選擇劇本塑造故事，而選擇演員塑造其感覺。"},{"en":"This phrase shows creative control over both text and performance.","zh":"這個短語顯示對文本和表演的創作控制。"}],"source":"105 - film.pdf","sourcePage":9},{"front":"freedom of the director","meaning":"導演的自由","examples":[{"en":"The freedom of the director led to some of Asia’s finest films.","zh":"導演的自由促成了一些亞洲最出色的電影。"},{"en":"The freedom of the director means the director’s ability to make creative decisions.","zh":"freedom of the director 是指导演作出創作決定的能力。"},{"en":"A director with freedom can choose story style, actors, camera movement, and editing rhythm.","zh":"有自由的導演可以選擇故事風格、演員、攝影機移動和剪接節奏。"},{"en":"Creative freedom can lead to original work when the artist has skill and responsibility.","zh":"當藝術家有技巧和責任感時，創作自由可以帶來原創作品。"},{"en":"This phrase links artistic power with artistic results.","zh":"這個短語把藝術權力與藝術成果連接起來。"}],"source":"105 - film.pdf","sourcePage":9},{"front":"lead to the production of","meaning":"促成……的製作","examples":[{"en":"This creative freedom led to the production of great films.","zh":"這種創作自由促成了偉大電影的製作。"},{"en":"To lead to the production of something means to cause or enable it to be made.","zh":"lead to the production of something 是指導致或使某物被製作出來。"},{"en":"Better funding can lead to the production of safer school facilities.","zh":"更好資金可以促成更安全校園設施的建造。"},{"en":"Training and freedom can lead to the production of more original films.","zh":"培訓和自由可以促成更多原創電影的製作。"},{"en":"This phrase connects conditions with the creation of a result.","zh":"這個短語把條件與成果創造連接起來。"}],"source":"105 - film.pdf","sourcePage":9},{"front":"Asia’s finest films","meaning":"亞洲最出色的電影","examples":[{"en":"Japanese directors produced some of Asia’s finest films.","zh":"日本導演製作了一些亞洲最出色的電影。"},{"en":"Asia’s finest films are films considered among the best made in Asia.","zh":"Asia’s finest films 是被認為屬於亞洲最佳之列的電影。"},{"en":"Film students study Asia’s finest films to learn about style, rhythm, and cultural meaning.","zh":"電影學生研究亞洲最出色的電影，以學習風格、節奏和文化意義。"},{"en":"Great films can shape international understanding of a region’s art.","zh":"偉大電影可以塑造國際對某地區藝術的理解。"},{"en":"This phrase gives strong praise to artistic quality.","zh":"這個短語對藝術質素給予高度讚揚。"}],"source":"105 - film.pdf","sourcePage":9},{"front":"among the greatest of these","meaning":"其中最偉大的之一","examples":[{"en":"The films of Kenji Mizoguchi were among the greatest of these.","zh":"溝口健二的電影是其中最偉大的之一。"},{"en":"Among the greatest of these means one of the best within the group just mentioned.","zh":"among the greatest of these 是指在剛提到的群組中屬於最佳之一。"},{"en":"Of all the school projects, her history documentary was among the greatest of these.","zh":"在所有學校項目中，她的歷史紀錄片是其中最出色之一。"},{"en":"This phrase ranks something highly while keeping it inside a larger category.","zh":"這個短語把某事放在較大類別中並給予高排名。"},{"en":"It gives praise without saying it is the single best.","zh":"它給予讚譽，但不說它是唯一最佳。"}],"source":"105 - film.pdf","sourcePage":9},{"front":"be set in","meaning":"以……為背景","examples":[{"en":"Mizoguchi’s films were usually set in the nineteenth century.","zh":"溝口健二的電影通常以十九世紀為背景。"},{"en":"To be set in a time or place means the story happens there.","zh":"be set in a time or place 是指故事發生在該時間或地方。"},{"en":"A novel set in a small village may show rural traditions and family life.","zh":"以小村莊為背景的小說可能展示鄉村傳統和家庭生活。"},{"en":"Setting a film in the past can help explore old social rules.","zh":"把電影設定在過去，可以幫助探討舊社會規則。"},{"en":"This phrase describes the background of a story.","zh":"這個短語描述故事背景。"}],"source":"105 - film.pdf","sourcePage":9},{"front":"analyse the way in which","meaning":"分析……的方式","examples":[{"en":"His films analysed the way in which women’s lives were constrained.","zh":"他的電影分析女性生活受限制的方式。"},{"en":"To analyse the way in which something happens means to examine how it happens and why.","zh":"analyse the way in which something happens 是指檢查某事如何發生及為何發生。"},{"en":"A teacher may analyse the way in which students misunderstand a grammar rule.","zh":"老師可能分析學生誤解文法規則的方式。"},{"en":"Films can analyse social pressure by showing repeated limits on characters’ choices.","zh":"電影可以透過展示角色選擇反覆受限來分析社會壓力。"},{"en":"This phrase focuses on method, process, and cause.","zh":"這個短語集中於方法、過程和原因。"}],"source":"105 - film.pdf","sourcePage":9},{"front":"female characters","meaning":"女性角色","examples":[{"en":"Mizoguchi focused on female characters in his films.","zh":"溝口健二在其電影中集中於女性角色。"},{"en":"Female characters are women or girls who appear in a story, film, or play.","zh":"female characters 是故事、電影或戲劇中出現的女性或女孩。"},{"en":"A novel with strong female characters may explore work, family, and freedom from women’s viewpoints.","zh":"有強大女性角色的小說可能從女性角度探討工作、家庭和自由。"},{"en":"Focusing on female characters can reveal social rules that male-centred stories may ignore.","zh":"集中於女性角色可以揭示以男性為中心的故事可能忽略的社會規則。"},{"en":"This phrase refers to story figures, not real actresses only.","zh":"這個短語指故事人物，而不只是現實女演員。"}],"source":"105 - film.pdf","sourcePage":10},{"front":"choose as his focus","meaning":"選作焦點","examples":[{"en":"Mizoguchi chose female characters as his focus.","zh":"溝口健二把女性角色選作焦點。"},{"en":"To choose something as one’s focus means to make it the main subject of attention.","zh":"choose something as one’s focus 是指把某事定為主要注意對象。"},{"en":"A student may choose climate change as her focus for a research project.","zh":"學生可能把氣候變化選作研究項目的焦點。"},{"en":"Choosing one focus helps a film or essay become clearer and more powerful.","zh":"選擇一個焦點有助電影或文章變得更清晰有力。"},{"en":"This phrase shows deliberate selection of a central topic.","zh":"這個短語顯示刻意選擇中心題目。"}],"source":"105 - film.pdf","sourcePage":10},{"front":"be constrained by","meaning":"受……限制","examples":[{"en":"The female characters were constrained by society.","zh":"女性角色受社會限制。"},{"en":"To be constrained by something means to be limited or restricted by it.","zh":"be constrained by something 是指受到某事限制或約束。"},{"en":"A family may be constrained by a small budget when choosing a flat.","zh":"家庭選擇單位時，可能受小預算限制。"},{"en":"Social rules can constrain people by limiting what choices seem acceptable.","zh":"社會規則可以透過限制哪些選擇看似可接受來約束人。"},{"en":"This phrase shows that freedom is reduced by an outside force.","zh":"這個短語顯示自由被外在力量減少。"}],"source":"105 - film.pdf","sourcePage":10},{"front":"the society of the time","meaning":"當時的社會","examples":[{"en":"His films showed the restrictions imposed by the society of the time.","zh":"他的電影展示當時社會所施加的限制。"},{"en":"The society of the time means the social world, values, and rules of a particular historical period.","zh":"the society of the time 是指某個歷史時期的社會世界、價值和規則。"},{"en":"A novel set in the 1800s should reflect the society of the time.","zh":"以十九世紀為背景的小說應反映當時的社會。"},{"en":"Understanding the society of the time helps viewers judge characters more fairly.","zh":"理解當時社會有助觀眾更公平地判斷角色。"},{"en":"This phrase reminds us that people’s choices are shaped by their era.","zh":"這個短語提醒我們，人的選擇受其時代塑造。"}],"source":"105 - film.pdf","sourcePage":10},{"front":"evolve a way of","meaning":"發展出一種……方式","examples":[{"en":"Mizoguchi evolved a sinuous way of moving his camera.","zh":"溝口健二發展出一種蜿蜒流動的攝影機移動方式。"},{"en":"To evolve a way of doing something means to gradually develop a distinctive method.","zh":"evolve a way of doing something 是指逐漸發展出獨特方法。"},{"en":"A teacher may evolve a way of explaining grammar through simple stories.","zh":"老師可能發展出一種透過簡單故事解釋文法的方法。"},{"en":"Artists evolve techniques through repeated practice and careful adjustment.","zh":"藝術家透過反覆練習和仔細調整來發展技巧。"},{"en":"This phrase suggests gradual creative development.","zh":"這個短語暗示逐步的創作發展。"}],"source":"105 - film.pdf","sourcePage":10},{"front":"sinuous","meaning":"蜿蜒流動的；流暢曲折的","examples":[{"en":"Mizoguchi developed a sinuous style of camera movement.","zh":"溝口健二發展出一種蜿蜒流動的攝影機移動風格。"},{"en":"Sinuous means smoothly curving, winding, or flowing rather than moving in straight lines.","zh":"sinuous 是指平滑彎曲、蜿蜒或流動，而不是直線移動。"},{"en":"A river can look sinuous as it bends through a valley.","zh":"河流彎過山谷時，看起來可以很蜿蜒。"},{"en":"Sinuous camera movement can make a scene feel graceful and continuous.","zh":"流暢曲折的攝影機移動可以令場面感覺優雅而連續。"},{"en":"This word often suggests elegant curves or flowing motion.","zh":"這個詞常暗示優雅曲線或流動動作。"}],"source":"105 - film.pdf","sourcePage":10},{"front":"in and around a scene","meaning":"在場景內外移動","examples":[{"en":"His camera moved in and around a scene.","zh":"他的攝影機在場景內外移動。"},{"en":"In and around a scene means through the space of a scene and around its people or objects.","zh":"in and around a scene 是指穿過場景空間，並圍繞其中人物或物件移動。"},{"en":"A tour guide may move in and around a group to show everyone the exhibit.","zh":"導賞員可能在一群人之間和周圍移動，讓每個人看到展品。"},{"en":"Camera movement in and around a scene can reveal relationships and hidden details.","zh":"攝影機在場景內外移動，可以揭示關係和隱藏細節。"},{"en":"This phrase suggests movement within a space, not just viewing from one fixed point.","zh":"這個短語暗示在空間內移動，而不只是從固定點觀看。"}],"source":"105 - film.pdf","sourcePage":10},{"front":"advance towards","meaning":"向……推進","examples":[{"en":"The camera advanced towards significant details.","zh":"攝影機向重要細節推進。"},{"en":"To advance towards something means to move forward in its direction.","zh":"advance towards something 是指朝某物方向向前移動。"},{"en":"A teacher may walk towards a student’s desk to look more closely at the work.","zh":"老師可能走向學生桌子，更仔細查看作品。"},{"en":"When a camera advances towards an object, viewers may feel that it matters.","zh":"當攝影機向某物推進，觀眾可能感到它很重要。"},{"en":"This phrase shows purposeful movement toward a target.","zh":"這個短語顯示朝目標的有目的移動。"}],"source":"105 - film.pdf","sourcePage":10},{"front":"significant details","meaning":"重要細節","examples":[{"en":"Mizoguchi’s camera moved towards significant details.","zh":"溝口健二的攝影機移向重要細節。"},{"en":"Significant details are small but important features that help explain meaning or emotion.","zh":"significant details 是細小但重要、能幫助解釋意思或情感的特徵。"},{"en":"In a history source, a date or signature can be a significant detail.","zh":"在歷史資料中，日期或簽名可以是重要細節。"},{"en":"Directors highlight significant details to guide viewers’ attention.","zh":"導演突出重要細節，以引導觀眾注意力。"},{"en":"This phrase reminds learners that small things can carry large meaning.","zh":"這個短語提醒學習者，小事可以承載重大意義。"}],"source":"105 - film.pdf","sourcePage":10},{"front":"retreat at moments of","meaning":"在……時後退","examples":[{"en":"The camera often retreated at moments of confrontation.","zh":"攝影機常在對峙時後退。"},{"en":"To retreat at moments of something means to move back during those particular moments.","zh":"retreat at moments of something 是指在那些特定時刻向後移動。"},{"en":"A speaker may retreat at moments of strong criticism to calm the audience.","zh":"演講者可能在受到強烈批評時退一步，以平息聽眾情緒。"},{"en":"A camera that retreats during conflict can make the scene feel controlled or distant.","zh":"在衝突中後退的攝影機，可以令場面感覺受控制或有距離。"},{"en":"This phrase connects movement with emotional timing.","zh":"這個短語把動作與情感時機連接起來。"}],"source":"105 - film.pdf","sourcePage":10},{"front":"confrontation","meaning":"對峙；衝突","examples":[{"en":"The camera retreated at moments of confrontation.","zh":"攝影機在對峙時後退。"},{"en":"A confrontation is a direct conflict, argument, or tense meeting between people.","zh":"confrontation 是人與人之間直接的衝突、爭論或緊張相遇。"},{"en":"A confrontation may happen when a student refuses to follow a classroom rule.","zh":"當學生拒絕遵守課堂規則時，可能發生對峙。"},{"en":"Films can show confrontation through silence, distance, or intense dialogue.","zh":"電影可以透過沉默、距離或激烈對白展示衝突。"},{"en":"This word suggests tension rather than ordinary disagreement.","zh":"這個詞暗示緊張，而不是普通分歧。"}],"source":"105 - film.pdf","sourcePage":10},{"front":"strong feeling","meaning":"強烈情感","examples":[{"en":"The camera often retreated during moments of strong feeling.","zh":"攝影機常在強烈情感時刻後退。"},{"en":"Strong feeling means intense emotion, such as grief, anger, love, or fear.","zh":"strong feeling 是指強烈情緒，例如悲傷、憤怒、愛或恐懼。"},{"en":"A person may speak more slowly during moments of strong feeling.","zh":"人在強烈情感時刻可能說話更慢。"},{"en":"Directors can show strong feeling without close-ups by using distance and silence.","zh":"導演可以不用特寫，而透過距離和沉默展示強烈情感。"},{"en":"This phrase focuses on emotional intensity.","zh":"這個短語集中於情感強度。"}],"source":"105 - film.pdf","sourcePage":11},{"front":"with such finesse","meaning":"以如此精妙的技巧","examples":[{"en":"No one had used the camera with such finesse before.","zh":"以前沒有人以如此精妙的技巧使用攝影機。"},{"en":"With such finesse means with great skill, delicacy, and subtle control.","zh":"with such finesse 是指以高超技巧、細膩和微妙控制去做某事。"},{"en":"A teacher handles a sensitive question with finesse when everyone feels respected.","zh":"老師若令每個人都感到被尊重，就是以精妙技巧處理敏感問題。"},{"en":"Using a tool with finesse can make difficult work look effortless.","zh":"以精妙技巧使用工具，可以令困難工作看起來毫不費力。"},{"en":"This phrase praises elegant skill rather than force.","zh":"這個短語讚揚優雅技巧，而不是力量。"}],"source":"105 - film.pdf","sourcePage":11},{"front":"finesse","meaning":"精妙技巧","examples":[{"en":"Mizoguchi used the camera with great finesse.","zh":"溝口健二以高超精妙技巧使用攝影機。"},{"en":"Finesse is skillful, subtle, and graceful handling of something difficult.","zh":"finesse 是以熟練、細膩和優雅方式處理困難事情。"},{"en":"A manager needs finesse when giving criticism to a hardworking employee.","zh":"經理批評勤奮員工時需要精妙技巧。"},{"en":"In art, finesse can turn a simple movement into something memorable.","zh":"在藝術中，精妙技巧可以把簡單動作變成令人難忘的東西。"},{"en":"This word suggests delicate skill and good judgement.","zh":"這個詞暗示細膩技巧和良好判斷。"}],"source":"105 - film.pdf","sourcePage":11},{"front":"even more important for","meaning":"對……甚至更重要","examples":[{"en":"Ozu’s work was even more important for film history.","zh":"小津安二郎的作品對電影史甚至更重要。"},{"en":"Even more important for means having greater significance for a particular field or purpose.","zh":"even more important for 是指對某領域或目的具有更大重要性。"},{"en":"Clear feedback is even more important for beginners than for advanced learners.","zh":"清晰回饋對初學者甚至比對高階學習者更重要。"},{"en":"A discovery becomes more important for science when it changes later research.","zh":"當發現改變後來研究時，它對科學就更重要。"},{"en":"This phrase strengthens a comparison of importance.","zh":"這個短語加強重要性的比較。"}],"source":"105 - film.pdf","sourcePage":11},{"front":"film history","meaning":"電影史","examples":[{"en":"Ozu’s work is very important for film history.","zh":"小津安二郎的作品對電影史非常重要。"},{"en":"Film history is the study of how cinema developed over time.","zh":"film history 是研究電影如何隨時間發展的學科。"},{"en":"Film history includes technology, directors, styles, industries, and audiences.","zh":"電影史包括科技、導演、風格、工業和觀眾。"},{"en":"Studying film history helps viewers understand why certain techniques became influential.","zh":"研究電影史幫助觀眾理解某些技巧為何變得有影響力。"},{"en":"This phrase treats cinema as a historical art form.","zh":"這個短語把電影視為一種歷史藝術形式。"}],"source":"105 - film.pdf","sourcePage":11},{"front":"crank up drama","meaning":"加強戲劇性","examples":[{"en":"Hollywood cranked up drama, but Ozu avoided it.","zh":"荷里活加強戲劇性，但小津避免這樣做。"},{"en":"To crank up drama means to increase emotional intensity, conflict, or excitement strongly.","zh":"crank up drama 是指強烈增加情感強度、衝突或刺激感。"},{"en":"A TV show may crank up drama by adding arguments and shocking music.","zh":"電視劇可能透過加入爭吵和震撼音樂來加強戲劇性。"},{"en":"Too much drama can make a story feel exaggerated rather than truthful.","zh":"太多戲劇性可以令故事感覺誇張，而不是真實。"},{"en":"This phrase is informal and suggests deliberate intensification.","zh":"這個短語較口語，暗示刻意加強。"}],"source":"105 - film.pdf","sourcePage":11},{"front":"avoid drama","meaning":"避免戲劇化","examples":[{"en":"Ozu avoided drama in his films.","zh":"小津在其電影中避免戲劇化。"},{"en":"To avoid drama means to avoid exaggerated conflict, strong emotional display, or sensational events.","zh":"avoid drama 是指避免誇張衝突、強烈情感展示或轟動事件。"},{"en":"A teacher may avoid drama by calmly solving a classroom disagreement.","zh":"老師可以透過冷靜解決課堂分歧來避免戲劇化。"},{"en":"A quiet film can avoid drama but still feel emotionally powerful.","zh":"安靜的電影可以避免戲劇化，但仍有情感力量。"},{"en":"This phrase suggests restraint rather than lack of feeling.","zh":"這個短語暗示克制，而不是缺乏情感。"}],"source":"105 - film.pdf","sourcePage":11},{"front":"seldom move","meaning":"很少移動","examples":[{"en":"Ozu’s camera seldom moved.","zh":"小津的攝影機很少移動。"},{"en":"Seldom move means rarely change position or move around.","zh":"seldom move 是指很少改變位置或移動。"},{"en":"During a formal interview, the camera may seldom move to keep attention on the speaker.","zh":"在正式訪問中，攝影機可能很少移動，以保持注意力在講者身上。"},{"en":"A still camera can make viewers notice small gestures and pauses.","zh":"靜止攝影機可以令觀眾注意細小動作和停頓。"},{"en":"This phrase suggests deliberate calmness or restraint.","zh":"這個短語暗示刻意的平靜或克制。"}],"source":"105 - film.pdf","sourcePage":11},{"front":"nestle at seated height","meaning":"安置在坐姿高度","examples":[{"en":"Ozu’s camera nestled at seated height.","zh":"小津的攝影機安置在坐姿高度。"},{"en":"To nestle at seated height means to be placed low and comfortably around the height of a seated person.","zh":"nestle at seated height 是指攝影機低低地、安穩地放在接近坐著的人高度。"},{"en":"A camera at seated height can make viewers feel as if they are sitting in the room.","zh":"坐姿高度的攝影機可以令觀眾感覺自己坐在房間裡。"},{"en":"Low camera placement creates intimacy because it matches everyday human posture.","zh":"低角度攝影機位置因符合日常人體姿勢而營造親密感。"},{"en":"This phrase suggests a quiet, settled camera position.","zh":"這個短語暗示安靜、穩定的攝影機位置。"}],"source":"105 - film.pdf","sourcePage":11},{"front":"seated height","meaning":"坐姿高度","examples":[{"en":"Ozu often placed the camera at seated height.","zh":"小津常把攝影機放在坐姿高度。"},{"en":"Seated height means the height of a person who is sitting down.","zh":"seated height 是一個人坐下時的高度。"},{"en":"A child’s eye level may be close to seated height for an adult.","zh":"兒童的眼睛高度可能接近成年人的坐姿高度。"},{"en":"Filming at seated height can make a conversation feel calm and domestic.","zh":"以坐姿高度拍攝可以令對話感覺平靜而居家。"},{"en":"This phrase is about camera level and viewing perspective.","zh":"這個短語關於攝影機高度和觀看角度。"}],"source":"105 - film.pdf","sourcePage":11},{"front":"frame people square on","meaning":"正面構圖拍攝人物","examples":[{"en":"Ozu framed people square on.","zh":"小津正面構圖拍攝人物。"},{"en":"To frame people square on means to film them directly from the front in a balanced composition.","zh":"frame people square on 是指從正面以平衡構圖拍攝人物。"},{"en":"A passport photo frames a person square on so the face is clear.","zh":"護照相正面拍攝人物，使面孔清楚。"},{"en":"Frontal framing can make viewers feel they are listening directly to a person.","zh":"正面構圖可以令觀眾感到自己正在直接聆聽某人。"},{"en":"This phrase describes both camera angle and composition.","zh":"這個短語同時描述攝影機角度和構圖。"}],"source":"105 - film.pdf","sourcePage":11},{"front":"listen quietly to","meaning":"靜靜聆聽","examples":[{"en":"Ozu’s camera seemed to listen quietly to people’s words.","zh":"小津的攝影機似乎靜靜聆聽人們的說話。"},{"en":"To listen quietly to someone means to give calm, respectful attention without interruption.","zh":"listen quietly to someone 是指平靜、尊重地專注聆聽，不打斷。"},{"en":"A good counsellor listens quietly to a patient before giving advice.","zh":"好輔導員在給建議前會靜靜聆聽病人。"},{"en":"A still camera can feel as if it listens quietly because it does not distract from speech.","zh":"靜止攝影機可能感覺像在靜靜聆聽，因為它不分散對說話的注意。"},{"en":"This phrase suggests patience and attention.","zh":"這個短語暗示耐性和專注。"}],"source":"105 - film.pdf","sourcePage":12},{"front":"reject the conventions of","meaning":"拒絕……的慣例","examples":[{"en":"Ozu rejected the conventions of editing.","zh":"小津拒絕剪接慣例。"},{"en":"To reject the conventions of something means to refuse to follow its normal rules or habits.","zh":"reject the conventions of something 是指拒絕跟隨某事的正常規則或習慣。"},{"en":"A young designer may reject the conventions of formal office clothing.","zh":"年輕設計師可能拒絕正式辦公服裝的慣例。"},{"en":"Artists reject conventions when they believe old rules limit expression.","zh":"當藝術家相信舊規則限制表達時，就會拒絕慣例。"},{"en":"This phrase suggests deliberate artistic independence.","zh":"這個短語暗示刻意的藝術獨立。"}],"source":"105 - film.pdf","sourcePage":12},{"front":"conventions of editing","meaning":"剪接慣例","examples":[{"en":"Ozu rejected normal conventions of editing.","zh":"小津拒絕正常剪接慣例。"},{"en":"Conventions of editing are the usual rules for cutting and joining film shots.","zh":"conventions of editing 是剪接和連接電影鏡頭的通常規則。"},{"en":"One convention of editing is to cut smoothly so viewers follow the action easily.","zh":"一種剪接慣例是流暢剪接，讓觀眾容易跟上動作。"},{"en":"Breaking editing conventions can make a film feel strange, calm, or original.","zh":"打破剪接慣例可以令電影感覺奇特、平靜或原創。"},{"en":"This phrase refers to accepted film-making practices.","zh":"這個短語指被接受的電影製作做法。"}],"source":"105 - film.pdf","sourcePage":12},{"front":"cut on action","meaning":"按動作剪接","examples":[{"en":"Western films usually cut on action.","zh":"西方電影通常按動作剪接。"},{"en":"To cut on action means to make an edit during a movement so the action appears continuous.","zh":"cut on action 是指在動作進行中剪接，使動作看起來連續。"},{"en":"A film may cut on action when a person opens a door and the next shot shows them entering.","zh":"電影可能在某人開門時按動作剪接，下一個鏡頭顯示他進入房間。"},{"en":"Cutting on action helps viewers feel that movement flows smoothly between shots.","zh":"按動作剪接幫助觀眾感覺動作在鏡頭之間流暢延續。"},{"en":"This phrase describes a common editing technique.","zh":"這個短語描述常見剪接技巧。"}],"source":"105 - film.pdf","sourcePage":12},{"front":"visual balance","meaning":"視覺平衡","examples":[{"en":"Ozu cut for visual balance rather than action.","zh":"小津按視覺平衡而不是動作剪接。"},{"en":"Visual balance is the pleasing arrangement of shapes, people, and space in an image.","zh":"visual balance 是影像中形狀、人物和空間令人舒服的安排。"},{"en":"A photograph has visual balance when objects on both sides feel carefully arranged.","zh":"當照片兩邊物件感覺安排得很仔細時，就有視覺平衡。"},{"en":"Editing for visual balance may create calmness rather than speed.","zh":"按視覺平衡剪接可能營造平靜，而不是速度感。"},{"en":"This phrase focuses on composition, not plot movement.","zh":"這個短語集中於構圖，而不是情節動作。"}],"source":"105 - film.pdf","sourcePage":12},{"front":"even more strikingly","meaning":"更令人注目的是","examples":[{"en":"Even more strikingly, Ozu cut away from the action.","zh":"更令人注目的是，小津從動作切走。"},{"en":"Even more strikingly means in an even more noticeable or surprising way.","zh":"even more strikingly 是指以更明顯或更令人驚訝的方式。"},{"en":"The student improved her grammar; even more strikingly, her confidence also grew.","zh":"那名學生改善了文法；更令人注目的是，她的信心也增加了。"},{"en":"A film style becomes striking when it breaks what viewers normally expect.","zh":"當電影風格打破觀眾通常預期時，就會令人注目。"},{"en":"This phrase introduces a point that is more remarkable than the previous one.","zh":"這個短語引入比前一點更值得注意的內容。"}],"source":"105 - film.pdf","sourcePage":12},{"front":"cut away from","meaning":"從……切走","examples":[{"en":"Ozu regularly cut away from his action to objects or landscapes.","zh":"小津經常從動作切走，轉到物件或風景。"},{"en":"To cut away from something means to edit away from the main action to another image.","zh":"cut away from something 是指從主要動作剪接到另一影像。"},{"en":"A documentary may cut away from an interview to old photographs.","zh":"紀錄片可能從訪問切走，轉到舊照片。"},{"en":"Cutting away can give viewers time to think or notice atmosphere.","zh":"切走可以給觀眾時間思考或注意氣氛。"},{"en":"This phrase describes a shift in visual attention.","zh":"這個短語描述視覺注意力的轉移。"}],"source":"105 - film.pdf","sourcePage":12},{"front":"a shot of","meaning":"……的鏡頭","examples":[{"en":"Ozu cut away to a shot of a tree or a kettle.","zh":"小津切到一個樹或水壺的鏡頭。"},{"en":"A shot of something is one filmed image or camera view of that thing.","zh":"a shot of something 是拍攝某物的一個影像或攝影機視角。"},{"en":"A film may begin with a shot of a quiet street before showing the main character.","zh":"電影可能先以一個安靜街道的鏡頭開始，再展示主角。"},{"en":"A shot of an object can suggest mood, place, or meaning.","zh":"物件的鏡頭可以暗示氣氛、地點或意義。"},{"en":"This phrase refers to one unit of film image.","zh":"這個短語指電影影像的一個單位。"}],"source":"105 - film.pdf","sourcePage":12},{"front":"establish a new location","meaning":"交代新地點","examples":[{"en":"These shots did not establish a new location.","zh":"這些鏡頭並沒有交代新地點。"},{"en":"To establish a new location means to show viewers where the next part of the story happens.","zh":"establish a new location 是指向觀眾顯示故事下一部分發生在哪裡。"},{"en":"A film may use a shot of a school gate to establish the new location.","zh":"電影可能用學校大門的鏡頭來交代新地點。"},{"en":"Establishing location helps viewers follow the story without confusion.","zh":"交代地點有助觀眾不混亂地跟上故事。"},{"en":"This phrase is about spatial information in film.","zh":"這個短語關於電影中的空間資訊。"}],"source":"105 - film.pdf","sourcePage":12},{"front":"a moment of repose","meaning":"片刻靜止；休息的時刻","examples":[{"en":"Ozu used such shots as moments of repose.","zh":"小津把這類鏡頭用作片刻靜止。"},{"en":"A moment of repose is a short period of calm, rest, or stillness.","zh":"moment of repose 是短暫的平靜、休息或靜止時刻。"},{"en":"A quiet pause after a difficult lesson can be a moment of repose for students.","zh":"困難課堂後的安靜停頓，可以是學生的休息時刻。"},{"en":"In film, a moment of repose can let emotion settle before the next scene.","zh":"在電影中，片刻靜止可以讓情感在下一場前沉澱。"},{"en":"This phrase suggests calm reflection rather than action.","zh":"這個短語暗示平靜反思，而不是動作。"}],"source":"105 - film.pdf","sourcePage":12},{"front":"pillow shots","meaning":"枕頭鏡頭","examples":[{"en":"Many historians compare Ozu’s pillow shots to a Buddhist idea.","zh":"許多歷史學家把小津的枕頭鏡頭與佛教理念比較。"},{"en":"Pillow shots are brief shots of objects, rooms, or landscapes that pause the main action.","zh":"pillow shots 是短暫拍攝物件、房間或風景，暫停主要動作的鏡頭。"},{"en":"A film may use a pillow shot of an empty hallway after an emotional conversation.","zh":"電影可能在情感對話後使用一個空走廊的枕頭鏡頭。"},{"en":"Pillow shots give viewers space to breathe and reflect.","zh":"枕頭鏡頭給觀眾呼吸和反思的空間。"},{"en":"This phrase is strongly associated with Ozu’s quiet film style.","zh":"這個短語與小津安靜的電影風格密切相關。"}],"source":"105 - film.pdf","sourcePage":12},{"front":"the Buddhist idea that","meaning":"佛教中……的理念","examples":[{"en":"Historians compare pillow shots to the Buddhist idea that emptiness matters.","zh":"歷史學家把枕頭鏡頭與佛教中空無也重要的理念相比。"},{"en":"The Buddhist idea that introduces a belief or concept connected with Buddhist thought.","zh":"the Buddhist idea that 用來引入與佛教思想相關的信念或概念。"},{"en":"A teacher may explain the Buddhist idea that desire can lead to suffering.","zh":"老師可能解釋佛教中慾望會導致痛苦的理念。"},{"en":"In art, a religious idea can shape how space, silence, and action are used.","zh":"在藝術中，宗教理念可以塑造空間、沉默和動作的使用方式。"},{"en":"This phrase introduces a philosophical explanation.","zh":"這個短語引入哲學解釋。"}],"source":"105 - film.pdf","sourcePage":13},{"front":"empty space","meaning":"空白空間","examples":[{"en":"Empty space can be an element of composition.","zh":"空白空間可以是構圖元素。"},{"en":"Empty space is an area in an image or design without objects, figures, or action.","zh":"empty space 是影像或設計中沒有物件、人物或動作的區域。"},{"en":"A poster with empty space can look calm and clear.","zh":"有空白空間的海報可以看起來平靜清晰。"},{"en":"Empty space can guide attention because it makes important objects stand out.","zh":"空白空間可以引導注意力，因為它令重要物件突出。"},{"en":"This phrase shows that absence can have visual meaning.","zh":"這個短語顯示「沒有」也可以有視覺意義。"}],"source":"105 - film.pdf","sourcePage":13},{"front":"an element of composition","meaning":"構圖元素","examples":[{"en":"Empty space is itself an element of composition.","zh":"空白空間本身就是一種構圖元素。"},{"en":"An element of composition is one part of how an image, scene, or design is arranged.","zh":"element of composition 是影像、場面或設計安排中的一部分。"},{"en":"Colour, shape, line, and empty space can all be elements of composition.","zh":"色彩、形狀、線條和空白空間都可以是構圖元素。"},{"en":"Good composition helps viewers know where to look first.","zh":"良好構圖幫助觀眾知道先看哪裡。"},{"en":"This phrase treats visual arrangement as a set of meaningful parts.","zh":"這個短語把視覺安排視為一組有意義的部分。"}],"source":"105 - film.pdf","sourcePage":13},{"front":"art form","meaning":"藝術形式","examples":[{"en":"Cinema is an art form strongly influenced by money and markets.","zh":"電影是一種深受金錢和市場影響的藝術形式。"},{"en":"An art form is a creative medium, such as film, painting, music, dance, or poetry.","zh":"art form 是創意媒介，例如電影、繪畫、音樂、舞蹈或詩歌。"},{"en":"Photography became an art form when artists used it to express ideas and emotions.","zh":"當藝術家用攝影表達思想和情感時，攝影就成為藝術形式。"},{"en":"An art form can still depend on business systems to reach audiences.","zh":"藝術形式仍可能依賴商業系統來接觸觀眾。"},{"en":"This phrase treats cinema as creative expression, not only entertainment.","zh":"這個短語把電影視為創意表達，而不只是娛樂。"}],"source":"105 - film.pdf","sourcePage":13},{"front":"be swayed by","meaning":"受……左右","examples":[{"en":"Cinema is an art form swayed by money and market forces.","zh":"電影是一種受金錢和市場力量左右的藝術形式。"},{"en":"To be swayed by something means to be influenced or pushed by it.","zh":"be swayed by something 是指受某事影響或推動。"},{"en":"A student may be swayed by friends when choosing subjects.","zh":"學生選科時可能受朋友左右。"},{"en":"Film studios can be swayed by profit when deciding which stories to produce.","zh":"片廠決定製作哪些故事時，可能受利潤左右。"},{"en":"This phrase suggests influence that may change decisions.","zh":"這個短語暗示可能改變決定的影響。"}],"source":"105 - film.pdf","sourcePage":13},{"front":"money and market","meaning":"金錢和市場","examples":[{"en":"Cinema is strongly affected by money and market pressures.","zh":"電影深受金錢和市場壓力影響。"},{"en":"Money and market refers to funding, profit, audience demand, and commercial competition.","zh":"money and market 指資金、利潤、觀眾需求和商業競爭。"},{"en":"A restaurant’s menu may be shaped by money and market conditions.","zh":"餐廳餐牌可能受金錢和市場條件塑造。"},{"en":"Film-makers may change stories if market pressure demands broader appeal.","zh":"如果市場壓力要求更廣泛吸引力，電影製作人可能改變故事。"},{"en":"This phrase links art with economic forces.","zh":"這個短語把藝術與經濟力量連接起來。"}],"source":"105 - film.pdf","sourcePage":13},{"front":"would appear to be","meaning":"看似是","examples":[{"en":"Cinema would appear to be too busy for philosophy.","zh":"電影看似太忙於其他事情而無暇顧及哲學。"},{"en":"Would appear to be means seems to be, though the judgement may not be final.","zh":"would appear to be 是指看似如此，但判斷未必最終確定。"},{"en":"The new timetable would appear to be simpler, but students still find it confusing.","zh":"新時間表看似更簡單，但學生仍覺得混亂。"},{"en":"A situation may appear one way at first and prove different after closer study.","zh":"情況起初可能看似某樣，仔細研究後卻證明不同。"},{"en":"This phrase expresses cautious appearance, not certainty.","zh":"這個短語表達謹慎的表面判斷，而非確定。"}],"source":"105 - film.pdf","sourcePage":13},{"front":"too busy to bother with","meaning":"太忙於……而無暇顧及","examples":[{"en":"Cinema may seem too busy to bother with philosophy.","zh":"電影可能看似太忙於其他事情而無暇顧及哲學。"},{"en":"Too busy to bother with something means too occupied to give attention to it.","zh":"too busy to bother with something 是指太忙而無法注意某事。"},{"en":"A student may feel too busy to bother with exercise during exam week.","zh":"學生在考試週可能覺得太忙而無暇顧及運動。"},{"en":"If people chase profit too hard, they may become too busy to think about values.","zh":"如果人們過分追逐利潤，可能變得太忙而無暇思考價值。"},{"en":"This phrase often criticises neglect of something important.","zh":"這個短語常批評對重要事情的忽視。"}],"source":"105 - film.pdf","sourcePage":13},{"front":"questions of philosophy","meaning":"哲學問題","examples":[{"en":"Asian cinema shows that film can deal with questions of philosophy.","zh":"亞洲電影顯示電影可以處理哲學問題。"},{"en":"Questions of philosophy are deep questions about life, meaning, reality, freedom, or identity.","zh":"questions of philosophy 是關於生命、意義、現實、自由或身份的深層問題。"},{"en":"A simple family film can raise philosophical questions about duty and personal choice.","zh":"一部簡單家庭電影可以提出關於責任和個人選擇的哲學問題。"},{"en":"Art deals with philosophy when it asks viewers how humans should live.","zh":"當藝術問觀眾人應如何生活時，它就在處理哲學。"},{"en":"This phrase points to serious ideas beneath a story.","zh":"這個短語指故事底下的嚴肅思想。"}],"source":"105 - film.pdf","sourcePage":13},{"front":"this is not the case","meaning":"情況並非如此","examples":[{"en":"Asian nations proved that this is not the case.","zh":"亞洲國家證明情況並非如此。"},{"en":"This is not the case means the previous idea is not true.","zh":"this is not the case 是指前面想法並不正確。"},{"en":"Some people think online lessons are always easier, but this is not the case.","zh":"有些人以為網上課堂總是較容易，但情況並非如此。"},{"en":"Evidence can show that a popular assumption is not correct.","zh":"證據可以顯示流行假設並不正確。"},{"en":"This phrase is used to reject or correct an earlier statement.","zh":"這個短語用來否定或修正前一說法。"}],"source":"105 - film.pdf","sourcePage":13},{"front":"deep ideas about","meaning":"關於……的深層思想","examples":[{"en":"Deep ideas about individual freedom shaped Hollywood cinema.","zh":"關於個人自由的深層思想塑造了荷里活電影。"},{"en":"Deep ideas about something are serious underlying beliefs or thoughts about it.","zh":"deep ideas about something 是關於某事的嚴肅基礎信念或思想。"},{"en":"A novel may contain deep ideas about family duty and personal happiness.","zh":"小說可能包含關於家庭責任和個人幸福的深層思想。"},{"en":"Films become richer when entertainment is supported by deep ideas.","zh":"當娛樂由深層思想支撐，電影會變得更豐富。"},{"en":"This phrase refers to meaning beneath the surface story.","zh":"這個短語指表面故事之下的意義。"}],"source":"105 - film.pdf","sourcePage":13},{"front":"individual freedom","meaning":"個人自由","examples":[{"en":"Hollywood cinema has been shaped by ideas about individual freedom.","zh":"荷里活電影受到關於個人自由的思想塑造。"},{"en":"Individual freedom is the ability of a person to make choices and live independently.","zh":"individual freedom 是個人作出選擇和獨立生活的能力。"},{"en":"A story about leaving home may explore individual freedom and family expectations.","zh":"關於離家的故事可能探討個人自由和家庭期望。"},{"en":"Societies value individual freedom differently, so films from different cultures feel different.","zh":"不同社會對個人自由的重視不同，所以不同文化的電影感覺不同。"},{"en":"This phrase is often linked to choice, self-expression, and independence.","zh":"這個短語常與選擇、自我表達和獨立有關。"}],"source":"105 - film.pdf","sourcePage":14},{"front":"aspirational cinema","meaning":"充滿抱負和理想的電影","examples":[{"en":"Hollywood developed an aspirational cinema based on individual freedom.","zh":"荷里活發展出一種以個人自由為基礎、充滿抱負和理想的電影。"},{"en":"Aspirational cinema presents hopes, dreams, success, and the belief that life can improve.","zh":"aspirational cinema 呈現希望、夢想、成功和生活可以改善的信念。"},{"en":"A film about a poor student becoming a doctor can be aspirational.","zh":"關於貧窮學生成為醫生的電影可以是充滿理想的電影。"},{"en":"Aspirational stories appeal to viewers because they offer possibility and motivation.","zh":"充滿抱負的故事吸引觀眾，因為它們提供可能性和動力。"},{"en":"This phrase suggests cinema built around ideals and ambition.","zh":"這個短語暗示圍繞理想和抱負建立的電影。"}],"source":"105 - film.pdf","sourcePage":14},{"front":"beliefs which underlie","meaning":"構成……基礎的信念","examples":[{"en":"The beliefs which underlie cultures help explain Asian cinema.","zh":"構成文化基礎的信念有助解釋亞洲電影。"},{"en":"Beliefs which underlie something are the deeper values that support or shape it.","zh":"beliefs which underlie something 是支持或塑造某事的深層價值。"},{"en":"The beliefs underlying a school system may include discipline, equality, or competition.","zh":"構成學校制度基礎的信念可能包括紀律、平等或競爭。"},{"en":"Hidden beliefs can shape art even when they are not stated directly.","zh":"隱藏信念即使沒有直接說出，也可以塑造藝術。"},{"en":"This phrase asks what deeper ideas sit beneath visible behaviour.","zh":"這個短語詢問可見行為之下有甚麼更深思想。"}],"source":"105 - film.pdf","sourcePage":14},{"front":"underlie cultures","meaning":"構成文化的基礎","examples":[{"en":"Different beliefs underlie different cultures.","zh":"不同信念構成不同文化的基礎。"},{"en":"To underlie cultures means to form the deep basis of how societies think and behave.","zh":"underlie cultures 是指成為社會思考和行為方式的深層基礎。"},{"en":"Ideas about family duty may underlie some cultural customs.","zh":"關於家庭責任的思想可能構成某些文化習俗的基礎。"},{"en":"Beliefs that underlie a culture can shape its stories, festivals, and films.","zh":"構成文化基礎的信念可以塑造故事、節日和電影。"},{"en":"This phrase describes hidden foundations, not surface details.","zh":"這個短語描述隱藏基礎，而不是表面細節。"}],"source":"105 - film.pdf","sourcePage":14},{"front":"explain the distinctiveness of","meaning":"解釋……的獨特性","examples":[{"en":"Cultural beliefs explain the distinctiveness of Asian cinema.","zh":"文化信念解釋亞洲電影的獨特性。"},{"en":"To explain the distinctiveness of something means to show why it is special or different.","zh":"explain the distinctiveness of something 是指顯示某事為何特別或不同。"},{"en":"Local food traditions can explain the distinctiveness of a city’s restaurants.","zh":"本地飲食傳統可以解釋一個城市餐廳的獨特性。"},{"en":"Understanding culture helps explain why films from different regions feel unlike each other.","zh":"理解文化有助解釋為何不同地區電影感覺不一樣。"},{"en":"This phrase links causes with uniqueness.","zh":"這個短語把原因與獨特性連接起來。"}],"source":"105 - film.pdf","sourcePage":14},{"front":"Asian cinema at its best","meaning":"最出色的亞洲電影","examples":[{"en":"Asian cinema at its best is shaped by culture and philosophy.","zh":"最出色的亞洲電影受到文化和哲學塑造。"},{"en":"Asian cinema at its best means the finest examples of Asian film-making.","zh":"Asian cinema at its best 是指亞洲電影製作中最優秀的例子。"},{"en":"At its best, a school project shows both careful research and personal creativity.","zh":"一個學校項目在最佳狀態下，會同時展現仔細研究和個人創意。"},{"en":"A film tradition at its best reveals values that ordinary entertainment may hide.","zh":"電影傳統在最佳狀態下，能揭示普通娛樂可能隱藏的價值。"},{"en":"This phrase praises the highest quality of a tradition.","zh":"這個短語讚揚某傳統的最高質素。"}],"source":"105 - film.pdf","sourcePage":14},{"front":"visually striking","meaning":"視覺上引人注目","examples":[{"en":"Many Asian films are visually striking.","zh":"許多亞洲電影在視覺上引人注目。"},{"en":"Visually striking means impressive or memorable because of how something looks.","zh":"visually striking 是指因外觀而令人印象深刻或難忘。"},{"en":"A poster with strong colours and simple shapes can be visually striking.","zh":"色彩強烈、形狀簡潔的海報可以在視覺上引人注目。"},{"en":"A visually striking film can hold attention even before viewers understand the story fully.","zh":"視覺上引人注目的電影，即使觀眾尚未完全理解故事，也能吸引注意。"},{"en":"This phrase focuses on visual impact.","zh":"這個短語集中於視覺衝擊力。"}],"source":"105 - film.pdf","sourcePage":14},{"front":"a different sense of","meaning":"對……的不同理解","examples":[{"en":"Asian films offer a different sense of what a person is.","zh":"亞洲電影提供對人是甚麼的不同理解。"},{"en":"A different sense of something means a different understanding or feeling about it.","zh":"a different sense of something 是指對某事有不同理解或感覺。"},{"en":"Travelling can give students a different sense of what home means.","zh":"旅遊可以給學生對家是甚麼的不同理解。"},{"en":"Films from another culture may give viewers a different sense of family, duty, or freedom.","zh":"另一文化的電影可能給觀眾對家庭、責任或自由的不同理解。"},{"en":"This phrase is about changed perception, not just new information.","zh":"這個短語關於改變感知，而不只是新資訊。"}],"source":"105 - film.pdf","sourcePage":14},{"front":"what space and action are","meaning":"空間和行動是甚麼","examples":[{"en":"Asian cinema presents a different sense of what space and action are.","zh":"亞洲電影呈現對空間和行動是甚麼的不同理解。"},{"en":"What space and action are means how a film understands location, movement, stillness, and events.","zh":"what space and action are 是指電影如何理解地點、動作、靜止和事件。"},{"en":"In some films, space is not just background; it shapes the emotion of the scene.","zh":"在有些電影中，空間不只是背景；它塑造場面的情感。"},{"en":"Different editing styles can change what viewers think action means.","zh":"不同剪接風格可以改變觀眾對行動意義的理解。"},{"en":"This phrase points to basic ideas about film form.","zh":"這個短語指向關於電影形式的基本思想。"}],"source":"105 - film.pdf","sourcePage":14},{"front":"new to Western eyes","meaning":"對西方人來說新鮮","examples":[{"en":"Asian cinema can feel new to Western eyes.","zh":"亞洲電影對西方人來說可能感覺新鮮。"},{"en":"New to Western eyes means unfamiliar or surprising to viewers from Western cultures.","zh":"new to Western eyes 是指對來自西方文化的觀眾而言陌生或令人驚訝。"},{"en":"A quiet film style may feel new to Western eyes if viewers expect fast editing.","zh":"如果觀眾期待快速剪接，安靜電影風格對西方人來說可能很新鮮。"},{"en":"Cultural habits can seem strange when people first see them through another society’s art.","zh":"當人們首次透過另一社會的藝術看見文化習慣，它們可能顯得奇特。"},{"en":"This phrase describes perception from a Western viewpoint.","zh":"這個短語描述西方視角下的感知。"}],"source":"105 - film.pdf","sourcePage":14},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"Students decide whether the following statements agree with the passage.","zh":"學生判斷以下陳述是否與文章一致。"},{"en":"Do the following statements agree with asks whether each statement matches the information or view in the text.","zh":"do the following statements agree with 是在問每句陳述是否符合文本中的資料或觀點。"},{"en":"In reading exams, students must check evidence before choosing TRUE or FALSE.","zh":"在閱讀考試中，學生選 TRUE 或 FALSE 前必須檢查證據。"},{"en":"A statement may sound reasonable but still not agree with the passage.","zh":"一句陳述可能聽起來合理，但仍未必與文章一致。"},{"en":"This instruction tests careful comparison between statement and text.","zh":"這個指示測試學生能否仔細比較陳述與文本。"}],"source":"105 - film.pdf","sourcePage":14},{"front":"information given in","meaning":"在……中提供的資料","examples":[{"en":"The answers depend on the information given in the passage.","zh":"答案取決於文章中提供的資料。"},{"en":"Information given in a text means details, facts, or views actually stated or shown there.","zh":"information given in a text 是指文本中實際陳述或展示的細節、事實或觀點。"},{"en":"Students should answer using information given in the article, not outside knowledge.","zh":"學生應使用文章中提供的資料回答，而不是外部知識。"},{"en":"If the information is not given in the text, students should not guess.","zh":"如果資料沒有在文本中提供，學生不應猜測。"},{"en":"This phrase limits the evidence source.","zh":"這個短語限制證據來源。"}],"source":"105 - film.pdf","sourcePage":15},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生把答案寫在答題紙上。"},{"en":"An answer sheet is the paper or digital form where test-takers record answers.","zh":"answer sheet 是考生記錄答案的紙張或電子表格。"},{"en":"Students should check the answer sheet before time ends.","zh":"學生應在時間結束前檢查答題紙。"},{"en":"A correct answer may be lost if it is written in the wrong box.","zh":"如果正確答案寫在錯誤格子中，可能會失分。"},{"en":"This phrase refers to where answers must be recorded.","zh":"這個短語指答案必須記錄的位置。"}],"source":"105 - film.pdf","sourcePage":15},{"front":"if the statement agrees with","meaning":"如果陳述與……一致","examples":[{"en":"Students write TRUE if the statement agrees with the information.","zh":"如果陳述與資料一致，學生寫 TRUE。"},{"en":"If the statement agrees with means if it matches what the passage says.","zh":"if the statement agrees with 是指如果陳述符合文章所說。"},{"en":"A statement agrees with a text only when clear evidence supports it.","zh":"只有在清晰證據支持時，陳述才與文本一致。"},{"en":"Students should not choose TRUE just because the statement sounds likely.","zh":"學生不應只因陳述聽起來可能正確就選 TRUE。"},{"en":"This phrase reminds learners to check the passage carefully.","zh":"這個短語提醒學習者仔細檢查文章。"}],"source":"105 - film.pdf","sourcePage":15},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"Students write FALSE if the statement contradicts the information.","zh":"如果陳述與資料相矛盾，學生寫 FALSE。"},{"en":"To contradict the information means to say the opposite of what the passage states.","zh":"contradict the information 是指說出與文章陳述相反的內容。"},{"en":"If the text says a film was silent, a statement saying it had songs contradicts the information.","zh":"如果文本說電影是無聲的，而陳述說它有歌曲，就是與資料相矛盾。"},{"en":"Contradiction requires clear opposite evidence, not just missing information.","zh":"矛盾需要清楚的相反證據，而不只是資料缺失。"},{"en":"This phrase is central to TRUE/FALSE/NOT GIVEN questions.","zh":"這個短語是 TRUE/FALSE/NOT GIVEN 題的核心。"}],"source":"105 - film.pdf","sourcePage":15},{"front":"there is no information on this","meaning":"沒有關於這方面的資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有關於這方面的資料，學生寫 NOT GIVEN。"},{"en":"There is no information on this means the passage does not say enough to decide.","zh":"there is no information on this 是指文章沒有提供足夠資料作出判斷。"},{"en":"If a text never mentions a director’s age, there is no information on this.","zh":"如果文本從未提及導演年齡，就是沒有關於這方面的資料。"},{"en":"Students should choose NOT GIVEN when the passage is silent about the statement.","zh":"當文章沒有提到某陳述時，學生應選 NOT GIVEN。"},{"en":"This phrase warns against guessing from general knowledge.","zh":"這個短語提醒不要根據常識猜測。"}],"source":"105 - film.pdf","sourcePage":15},{"front":"inventors of cinema","meaning":"電影的發明者","examples":[{"en":"The inventors of cinema first saw it as a minor attraction.","zh":"電影的發明者最初把它視為小型娛樂項目。"},{"en":"The inventors of cinema were the people who created early film technology and projection systems.","zh":"inventors of cinema 是創造早期電影科技和放映系統的人。"},{"en":"Inventors may not always understand how important their inventions will become.","zh":"發明者未必總是明白自己的發明後來會有多重要。"},{"en":"The inventors saw a business tool before later artists saw an art form.","zh":"發明者先看見商業工具，後來藝術家才看見藝術形式。"},{"en":"This phrase refers to early creators of the technology, not later directors.","zh":"這個短語指早期技術創造者，而不是後來導演。"}],"source":"105 - film.pdf","sourcePage":15},{"front":"regard something as","meaning":"把……視為","examples":[{"en":"The inventors regarded cinema as a minor attraction.","zh":"發明者把電影視為小型娛樂項目。"},{"en":"To regard something as something means to consider or see it in that way.","zh":"regard something as something 是指把某事看作某種東西。"},{"en":"Some students regard grammar as boring until they see how it improves writing.","zh":"有些學生把文法視為沉悶，直到看見它如何改善寫作。"},{"en":"If people regard a tool as only entertainment, they may miss its educational value.","zh":"如果人們把工具只視為娛樂，可能錯過其教育價值。"},{"en":"This phrase shows judgement or perception.","zh":"這個短語顯示判斷或看法。"}],"source":"105 - film.pdf","sourcePage":15},{"front":"a minor attraction","meaning":"小型娛樂項目；次要吸引物","examples":[{"en":"Early cinema was regarded as a minor attraction.","zh":"早期電影被視為小型娛樂項目。"},{"en":"A minor attraction is a small entertainment or feature that is not the main event.","zh":"minor attraction 是不是主要活動的小型娛樂或特色。"},{"en":"At a fair, a photo booth may be a minor attraction beside the big rides.","zh":"在嘉年華中，照相亭可能是大型機動遊戲旁的次要吸引物。"},{"en":"Something can begin as a minor attraction and later become culturally important.","zh":"某事可以一開始是小型娛樂項目，後來變得有文化重要性。"},{"en":"This phrase suggests low status at first.","zh":"這個短語暗示起初地位較低。"}],"source":"105 - film.pdf","sourcePage":15},{"front":"be aware of","meaning":"意識到","examples":[{"en":"Some directors were aware of cinema’s artistic possibilities.","zh":"有些導演意識到電影的藝術可能性。"},{"en":"To be aware of something means to know or notice that it exists.","zh":"be aware of 是指知道或注意到某事存在。"},{"en":"Students should be aware of the word limit before writing answers.","zh":"學生寫答案前應意識到字數限制。"},{"en":"Artists who are aware of a medium’s potential can use it more creatively.","zh":"意識到媒介潛力的藝術家可以更具創意地使用它。"},{"en":"This phrase shows recognition, not necessarily full understanding.","zh":"這個短語顯示認知，但不一定是完全理解。"}],"source":"105 - film.pdf","sourcePage":15},{"front":"artistic possibilities","meaning":"藝術可能性","examples":[{"en":"Some pioneers recognised cinema’s artistic possibilities.","zh":"有些先驅者認識到電影的藝術可能性。"},{"en":"Artistic possibilities are the creative things a medium could be used to express or achieve.","zh":"artistic possibilities 是一種媒介可以用來表達或達成的創意事情。"},{"en":"A phone camera has artistic possibilities when people use light, framing, and timing well.","zh":"當人們善用光線、構圖和時機，手機相機也有藝術可能性。"},{"en":"Recognising artistic possibilities can turn a simple technology into a serious art form.","zh":"認識藝術可能性可以把簡單科技變成嚴肅藝術形式。"},{"en":"This phrase focuses on creative potential.","zh":"這個短語集中於創作潛力。"}],"source":"105 - film.pdf","sourcePage":15},{"front":"from the very beginning","meaning":"從一開始","examples":[{"en":"The statement asks whether directors saw cinema’s potential from the very beginning.","zh":"該陳述問導演是否從一開始就看見電影的潛力。"},{"en":"From the very beginning means from the first moment or earliest stage.","zh":"from the very beginning 是指從最初一刻或最早階段。"},{"en":"From the very beginning, the teacher told students to use evidence in every answer.","zh":"從一開始，老師就告訴學生每個答案都要用證據。"},{"en":"Some ideas are not understood from the beginning; their value appears later.","zh":"有些想法不是從一開始就被理解；其價值後來才出現。"},{"en":"This phrase stresses the earliest point in a process.","zh":"這個短語強調過程中最早的一點。"}],"source":"105 - film.pdf","sourcePage":15},{"front":"artistic potential","meaning":"藝術潛力","examples":[{"en":"The passage discusses the development of cinema’s artistic potential.","zh":"文章討論電影藝術潛力的發展。"},{"en":"Artistic potential is the possibility that something can become expressive, beautiful, or meaningful art.","zh":"artistic potential 是某物可以成為有表達力、美感或意義的藝術的可能性。"},{"en":"A simple photograph has artistic potential if it captures emotion or a strong composition.","zh":"如果簡單照片捕捉到情感或強烈構圖，它就有藝術潛力。"},{"en":"Artistic potential grows when creators experiment with form, sound, and viewpoint.","zh":"當創作者實驗形式、聲音和視角時，藝術潛力會增長。"},{"en":"This phrase refers to what art might become, not only what it already is.","zh":"這個短語指藝術可能成為甚麼，而不只是已經是甚麼。"}],"source":"105 - film.pdf","sourcePage":16},{"front":"depend on technology","meaning":"取決於科技","examples":[{"en":"The question asks whether cinema’s artistic potential depended on technology.","zh":"題目問電影的藝術潛力是否取決於科技。"},{"en":"To depend on technology means to require tools, machines, or technical systems in order to work or develop.","zh":"depend on technology 是指需要工具、機器或技術系統才能運作或發展。"},{"en":"Online classes depend on technology such as cameras, microphones, and stable internet.","zh":"網上課堂取決於攝影機、麥克風和穩定網絡等科技。"},{"en":"Cinema depends on technology, but artistic value also depends on imagination and skill.","zh":"電影取決於科技，但藝術價值也取決於想像力和技巧。"},{"en":"This phrase links development with technical conditions.","zh":"這個短語把發展與技術條件連接起來。"}],"source":"105 - film.pdf","sourcePage":16},{"front":"in varied ways","meaning":"以不同方式","examples":[{"en":"Cinema’s possibilities were developed in varied ways in different countries.","zh":"電影的可能性在不同國家以不同方式發展。"},{"en":"In varied ways means in several different methods, styles, or forms.","zh":"in varied ways 是指以幾種不同方法、風格或形式。"},{"en":"Teachers can explain vocabulary in varied ways, such as stories, pictures, and role-play.","zh":"老師可以以故事、圖片和角色扮演等不同方式解釋詞彙。"},{"en":"A medium grows richer when different cultures use it in varied ways.","zh":"當不同文化以不同方式使用媒介時，它會變得更豐富。"},{"en":"This phrase stresses diversity of method.","zh":"這個短語強調方法多樣性。"}],"source":"105 - film.pdf","sourcePage":16},{"front":"Western countries","meaning":"西方國家","examples":[{"en":"Different Western countries developed cinema in different ways.","zh":"不同西方國家以不同方式發展電影。"},{"en":"Western countries generally refers to countries in Europe and North America, especially in cultural comparisons.","zh":"Western countries 一般指歐洲和北美國家，尤其用於文化比較。"},{"en":"Western countries may share some film traditions but still have different styles.","zh":"西方國家可能分享某些電影傳統，但仍有不同風格。"},{"en":"Comparing Western countries with Asian countries can reveal different cultural assumptions.","zh":"比較西方國家與亞洲國家，可以揭示不同文化假設。"},{"en":"This phrase is broad and depends on context.","zh":"這個短語很廣泛，取決於語境。"}],"source":"105 - film.pdf","sourcePage":16},{"front":"be concerned about","meaning":"擔心；關注","examples":[{"en":"Western businessmen were not concerned about Asian film industries at first.","zh":"西方商人起初並不擔心亞洲電影工業。"},{"en":"To be concerned about something means to be worried about it or pay serious attention to it.","zh":"be concerned about 是指擔心某事或認真關注某事。"},{"en":"Parents may be concerned about children’s screen time.","zh":"家長可能擔心孩子的螢幕時間。"},{"en":"Investors may ignore a new competitor until it grows large enough to concern them.","zh":"投資者可能忽視新競爭者，直到它成長到足以令他們關注。"},{"en":"This phrase can mean worry, interest, or both.","zh":"這個短語可以表示擔心，也可以表示關注，或兩者兼有。"}],"source":"105 - film.pdf","sourcePage":16},{"front":"the emergence of","meaning":"……的出現；興起","examples":[{"en":"The question mentions the emergence of film industries outside the West.","zh":"題目提到西方以外電影工業的興起。"},{"en":"The emergence of something means its appearance and early development.","zh":"emergence of something 是指某事的出現和早期發展。"},{"en":"The emergence of online learning changed how schools deliver lessons.","zh":"網上學習的興起改變了學校授課方式。"},{"en":"A new industry’s emergence can surprise people who focused only on old centres.","zh":"新行業的興起可能令只集中於舊中心的人感到驚訝。"},{"en":"This phrase describes something becoming visible and important.","zh":"這個短語描述某事變得可見和重要。"}],"source":"105 - film.pdf","sourcePage":16},{"front":"other parts of the world","meaning":"世界其他地區","examples":[{"en":"Film industries emerged in other parts of the world.","zh":"電影工業在世界其他地區興起。"},{"en":"Other parts of the world means regions outside the place already being discussed.","zh":"other parts of the world 是指已討論地方以外的地區。"},{"en":"A product may become popular in other parts of the world after success at home.","zh":"產品在本地成功後，可能在世界其他地區流行。"},{"en":"Ideas change when they travel to other parts of the world and meet local cultures.","zh":"思想傳到世界其他地區並遇上本地文化時，會發生改變。"},{"en":"This phrase expands the geographical scope.","zh":"這個短語擴大地理範圍。"}],"source":"105 - film.pdf","sourcePage":16},{"front":"complete the notes below","meaning":"完成以下筆記","examples":[{"en":"Students complete the notes below using words from the box.","zh":"學生使用方格中的詞語完成以下筆記。"},{"en":"Complete the notes below means fill in missing information in the notes that follow.","zh":"complete the notes below 是指填補下面筆記中的缺漏資料。"},{"en":"In reading exams, students complete notes by finding words that match meaning and grammar.","zh":"在閱讀考試中，學生透過找出符合意思和文法的字詞完成筆記。"},{"en":"Students should read the headings in the notes before searching the passage.","zh":"學生搜尋文章前應先閱讀筆記標題。"},{"en":"This phrase describes a common completion task.","zh":"這個短語描述常見填空任務。"}],"source":"105 - film.pdf","sourcePage":16},{"front":"using the list of words","meaning":"使用詞語列表","examples":[{"en":"The notes must be completed using the list of words.","zh":"筆記必須使用詞語列表完成。"},{"en":"Using the list of words means choosing answers only from the words provided.","zh":"using the list of words 是指只從提供的詞語中選擇答案。"},{"en":"Students should not invent new words if the task requires using the list.","zh":"如果任務要求使用詞語列表，學生不應自創新詞。"},{"en":"A word list reduces choices but still requires careful matching.","zh":"詞語列表減少選項，但仍需要仔細配對。"},{"en":"This phrase limits the answer source.","zh":"這個短語限制答案來源。"}],"source":"105 - film.pdf","sourcePage":16},{"front":"large number of","meaning":"大量的","examples":[{"en":"China produced a large number of films in the 1930s.","zh":"中國在1930年代製作了大量電影。"},{"en":"A large number of something means many of them.","zh":"large number of something 是指很多某物。"},{"en":"A school may receive a large number of applications after good exam results.","zh":"學校取得良好考試成績後，可能收到大量申請。"},{"en":"Producing a large number of films suggests an active and growing industry.","zh":"製作大量電影暗示電影工業活躍並正在成長。"},{"en":"This phrase describes quantity, not quality.","zh":"這個短語描述數量，而不是品質。"}],"source":"105 - film.pdf","sourcePage":16},{"front":"silent films","meaning":"無聲電影","examples":[{"en":"Many Chinese films in the early 1930s were silent films.","zh":"1930年代初期許多中國電影是無聲電影。"},{"en":"Silent films are films without recorded dialogue or synchronised sound.","zh":"silent films 是沒有錄製對白或同步聲音的電影。"},{"en":"Early silent films often used title cards and live music to help tell the story.","zh":"早期無聲電影常使用字幕卡和現場音樂來幫助講故事。"},{"en":"Without spoken dialogue, silent films depended heavily on gesture, expression, and visual rhythm.","zh":"沒有口頭對白，無聲電影高度依賴手勢、表情和視覺節奏。"},{"en":"This phrase refers to a major stage before sound cinema became common.","zh":"這個短語指有聲電影普及前的一個重要階段。"}],"source":"105 - film.pdf","sourcePage":16},{"front":"still generally regarded as","meaning":"仍普遍被視為","examples":[{"en":"Some early Chinese films are still generally regarded as outstanding.","zh":"有些早期中國電影仍普遍被視為傑出作品。"},{"en":"Still generally regarded as means still widely considered to be something.","zh":"still generally regarded as 是指至今仍被廣泛認為是某種東西。"},{"en":"This old textbook is still generally regarded as useful for beginners.","zh":"這本舊教科書仍普遍被視為適合初學者。"},{"en":"If a film is still regarded as great, later viewers continue to value it.","zh":"如果一部電影仍被視為偉大，表示後來觀眾繼續重視它。"},{"en":"This phrase shows lasting reputation.","zh":"這個短語顯示持久聲譽。"}],"source":"105 - film.pdf","sourcePage":17},{"front":"avoid negative topics","meaning":"避開負面題材","examples":[{"en":"The notes suggest that Indian films avoided negative topics.","zh":"筆記暗示印度電影避開負面題材。"},{"en":"To avoid negative topics means to stay away from sad, dark, critical, or unpleasant subjects.","zh":"avoid negative topics 是指避開悲傷、陰暗、批判性或令人不快的題材。"},{"en":"A family dinner may avoid negative topics to keep the atmosphere calm.","zh":"家庭晚餐可能避開負面題材，以保持氣氛平靜。"},{"en":"Films may avoid negative topics if they want to offer hope and entertainment.","zh":"如果電影想提供希望和娛樂，可能會避開負面題材。"},{"en":"This phrase describes topic choice, not whether problems truly exist.","zh":"這個短語描述題材選擇，而不是問題是否真正存在。"}],"source":"105 - film.pdf","sourcePage":17},{"front":"very powerful","meaning":"很有權力","examples":[{"en":"The Japanese film director was very powerful within the studio system.","zh":"日本電影導演在片廠制度中很有權力。"},{"en":"Very powerful means having strong authority, influence, or control.","zh":"very powerful 是指擁有強大權威、影響力或控制力。"},{"en":"A principal is very powerful if she controls budget, hiring, and school rules.","zh":"如果校長控制預算、聘任和校規，她就很有權力。"},{"en":"Powerful directors can shape stories, casting, and production style.","zh":"有權力的導演可以塑造故事、選角和製作風格。"},{"en":"This phrase refers to influence, not physical strength here.","zh":"這裡的短語指影響力，而不是體力。"}],"source":"105 - film.pdf","sourcePage":17},{"front":"restrictions faced by women","meaning":"女性面對的限制","examples":[{"en":"Mizoguchi focused on the restrictions faced by women.","zh":"溝口健二集中於女性面對的限制。"},{"en":"Restrictions faced by women are limits placed on women’s choices, work, movement, or rights.","zh":"restrictions faced by women 是女性在選擇、工作、行動或權利上受到的限制。"},{"en":"A film may show restrictions faced by women through marriage rules or job barriers.","zh":"電影可能透過婚姻規則或工作障礙展示女性面對的限制。"},{"en":"Studying these restrictions helps viewers understand social inequality.","zh":"研究這些限制幫助觀眾理解社會不平等。"},{"en":"This phrase highlights limits created by society, not personal weakness.","zh":"這個短語強調由社會造成的限制，而不是個人弱點。"}],"source":"105 - film.pdf","sourcePage":17},{"front":"camera movement","meaning":"攝影機移動","examples":[{"en":"Mizoguchi’s camera movement was central to his film style.","zh":"溝口健二的攝影機移動是其電影風格的核心。"},{"en":"Camera movement means the way a camera moves during filming.","zh":"camera movement 是拍攝期間攝影機移動的方式。"},{"en":"A camera may move slowly forward to make viewers notice a detail.","zh":"攝影機可能慢慢向前移動，令觀眾注意某個細節。"},{"en":"Camera movement can shape emotion, attention, and the rhythm of a scene.","zh":"攝影機移動可以塑造場面的情感、注意力和節奏。"},{"en":"This phrase refers to a film technique, not the movement of actors.","zh":"這個短語指電影技巧，而不是演員動作。"}],"source":"105 - film.pdf","sourcePage":17},{"front":"be related to","meaning":"與……有關","examples":[{"en":"Camera movement was related to the emotional content of the film.","zh":"攝影機移動與電影的情感內容有關。"},{"en":"To be related to something means to be connected with it.","zh":"be related to something 是指與某事有連繫。"},{"en":"Poor sleep is related to weaker memory and concentration.","zh":"睡眠不足與記憶和專注力較弱有關。"},{"en":"A film technique may be related to emotion when it changes how viewers feel.","zh":"當電影技巧改變觀眾感受時，它可能與情感有關。"},{"en":"This phrase shows connection, not always direct cause.","zh":"這個短語顯示關聯，不一定是直接因果。"}],"source":"105 - film.pdf","sourcePage":17},{"front":"emotional content","meaning":"情感內容","examples":[{"en":"Mizoguchi’s camera movement was related to emotional content.","zh":"溝口健二的攝影機移動與情感內容有關。"},{"en":"Emotional content is the feeling or emotional meaning inside a scene, story, or artwork.","zh":"emotional content 是場面、故事或藝術作品中的感受或情感意義。"},{"en":"A film’s emotional content may come from silence, music, acting, or camera distance.","zh":"電影的情感內容可能來自沉默、音樂、演技或攝影機距離。"},{"en":"Strong emotional content can make viewers remember a scene long after watching it.","zh":"強烈情感內容可以令觀眾看完很久仍記得某場面。"},{"en":"This phrase focuses on feeling rather than plot facts alone.","zh":"這個短語集中於感受，而不只是情節事實。"}],"source":"105 - film.pdf","sourcePage":17},{"front":"little camera movement","meaning":"很少攝影機移動","examples":[{"en":"Ozu’s films are known for little camera movement.","zh":"小津的電影以很少攝影機移動聞名。"},{"en":"Little camera movement means the camera rarely moves during scenes.","zh":"little camera movement 是指攝影機在場面中很少移動。"},{"en":"A film with little camera movement can feel calm, still, and observant.","zh":"很少攝影機移動的電影可以感覺平靜、靜止和觀察性強。"},{"en":"Less movement can make viewers focus on dialogue, faces, and empty space.","zh":"較少移動可以令觀眾集中於對白、面孔和空白空間。"},{"en":"This phrase describes a restrained visual style.","zh":"這個短語描述克制的視覺風格。"}],"source":"105 - film.pdf","sourcePage":17},{"front":"the most suitable title","meaning":"最合適的標題","examples":[{"en":"Students choose the most suitable title for the passage.","zh":"學生為文章選擇最合適的標題。"},{"en":"The most suitable title is the title that best matches the whole passage’s main idea.","zh":"most suitable title 是最符合整篇文章主旨的標題。"},{"en":"Students should choose a title that covers the whole text, not just one paragraph.","zh":"學生應選擇涵蓋整篇文本的標題，而不只是某一段。"},{"en":"A title is unsuitable if it focuses on a small detail and ignores the main argument.","zh":"如果標題集中於小細節而忽略主要論點，就不合適。"},{"en":"This phrase tests overall understanding.","zh":"這個短語測試整體理解。"}],"source":"105 - film.pdf","sourcePage":17},{"front":"blind to change","meaning":"對變化視而不見","examples":[{"en":"The title asks whether the West was blind to change.","zh":"標題問西方是否對變化視而不見。"},{"en":"Blind to change means unable or unwilling to notice that important changes are happening.","zh":"blind to change 是指不能或不願注意重要變化正在發生。"},{"en":"A business may be blind to change if it ignores customers moving online.","zh":"如果企業忽視顧客轉到網上，它可能對變化視而不見。"},{"en":"Being blind to change can make people underestimate new competitors.","zh":"對變化視而不見會令人低估新競爭者。"},{"en":"This phrase criticises lack of awareness.","zh":"這個短語批評缺乏覺察。"}],"source":"105 - film.pdf","sourcePage":17},{"front":"ignore Asian cinema","meaning":"忽視亞洲電影","examples":[{"en":"The question asks whether the West ignored Asian cinema for a long time.","zh":"題目問西方是否長期忽視亞洲電影。"},{"en":"To ignore Asian cinema means to pay little attention to films and film industries from Asia.","zh":"ignore Asian cinema 是指很少注意亞洲的電影和電影工業。"},{"en":"Critics ignore a film tradition when they discuss only Western examples.","zh":"當評論者只討論西方案例時，就是忽視某電影傳統。"},{"en":"Ignoring Asian cinema can make film history seem narrower than it really is.","zh":"忽視亞洲電影會令電影史看起來比實際更狹窄。"},{"en":"This phrase describes neglect of an important cultural field.","zh":"這個短語描述對重要文化領域的忽略。"}],"source":"105 - film.pdf","sourcePage":17},{"front":"for so long","meaning":"這麼久","examples":[{"en":"The title asks why Asian cinema was ignored for so long.","zh":"標題問亞洲電影為何被忽視這麼久。"},{"en":"For so long means for such a long time.","zh":"for so long 是指長達這樣久的時間。"},{"en":"Students may wonder why a simple problem was left unsolved for so long.","zh":"學生可能好奇為何一個簡單問題被擱置這麼久。"},{"en":"If an idea is ignored for so long, people may later ask what caused the neglect.","zh":"如果一個想法被忽視這麼久，人們後來可能問忽略的原因是甚麼。"},{"en":"This phrase emphasises duration and sometimes surprise.","zh":"這個短語強調持續時間，有時帶有驚訝。"}],"source":"105 - film.pdf","sourcePage":18},{"front":"a different basis","meaning":"不同基礎","examples":[{"en":"The title suggests that Asian cinema developed on a different basis.","zh":"標題暗示亞洲電影在不同基礎上發展。"},{"en":"A different basis means a different foundation, principle, or starting point.","zh":"different basis 是指不同的基礎、原則或出發點。"},{"en":"A school can build discipline on trust rather than fear, using a different basis.","zh":"學校可以把紀律建立在信任而不是恐懼上，使用不同基礎。"},{"en":"Asian cinema may feel different because it grew from different cultural beliefs.","zh":"亞洲電影可能感覺不同，因為它源自不同文化信念。"},{"en":"This phrase points to deeper foundations, not surface style alone.","zh":"這個短語指更深層基礎，而不只是表面風格。"}],"source":"105 - film.pdf","sourcePage":18},{"front":"be shaped by","meaning":"受……塑造","examples":[{"en":"The cinema of Asian countries was shaped by their cultures and beliefs.","zh":"亞洲國家的電影受其文化和信念塑造。"},{"en":"To be shaped by something means to be influenced or formed by it.","zh":"be shaped by something 是指受某事影響或形成。"},{"en":"A child’s habits can be shaped by family routines and school expectations.","zh":"孩子的習慣可以受家庭作息和學校期望塑造。"},{"en":"Film style is shaped by money, technology, culture, and audience taste.","zh":"電影風格受金錢、科技、文化和觀眾品味塑造。"},{"en":"This phrase explains the forces behind development.","zh":"這個短語解釋發展背後的力量。"}],"source":"105 - film.pdf","sourcePage":18},{"front":"cultures and beliefs","meaning":"文化和信念","examples":[{"en":"Asian cinema was shaped by local cultures and beliefs.","zh":"亞洲電影受到本地文化和信念塑造。"},{"en":"Cultures and beliefs are shared customs, values, ideas, and ways of understanding life.","zh":"cultures and beliefs 是共同習俗、價值、思想和理解生命的方式。"},{"en":"Family meals, festivals, religion, and social rules can all reflect cultures and beliefs.","zh":"家庭飯局、節日、宗教和社會規則都可以反映文化和信念。"},{"en":"Films shaped by culture often show what a society values or fears.","zh":"受文化塑造的電影常顯示一個社會重視或害怕甚麼。"},{"en":"This phrase connects art with deeper social foundations.","zh":"這個短語把藝術與更深層社會基礎連接起來。"}],"source":"105 - film.pdf","sourcePage":18},{"front":"origins of cinema","meaning":"電影的起源","examples":[{"en":"The option refers to the origins of cinema and its worldwide development.","zh":"該選項提到電影的起源及其全球發展。"},{"en":"Origins of cinema means the beginnings of film technology, exhibition, and artistic use.","zh":"origins of cinema 是電影科技、放映和藝術用途的開端。"},{"en":"Students study the origins of cinema to learn how a machine became an art form.","zh":"學生研究電影起源，以了解機器如何變成藝術形式。"},{"en":"Understanding origins helps explain later developments in different countries.","zh":"理解起源有助解釋後來在不同國家的發展。"},{"en":"This phrase focuses on where and how cinema began.","zh":"這個短語集中於電影在哪裡和如何開始。"}],"source":"105 - film.pdf","sourcePage":18},{"front":"affect its development worldwide","meaning":"影響其全球發展","examples":[{"en":"The question asks how cinema’s origins affected its development worldwide.","zh":"題目問電影的起源如何影響其全球發展。"},{"en":"To affect its development worldwide means to influence how it grew in many countries.","zh":"affect its development worldwide 是指影響它在許多國家如何成長。"},{"en":"The internet’s early design affected its development worldwide by making sharing easier.","zh":"互聯網的早期設計透過令分享更容易而影響其全球發展。"},{"en":"An invention’s origin can shape how later cultures adopt and change it.","zh":"發明的起源可以塑造後來文化如何採用和改變它。"},{"en":"This phrase links beginning conditions with global growth.","zh":"這個短語把開始條件與全球成長連接起來。"}],"source":"105 - film.pdf","sourcePage":18},{"front":"come to terms with","meaning":"接受並處理","examples":[{"en":"The option asks how Western cinema came to terms with Asian cinema.","zh":"該選項問西方電影如何接受並處理亞洲電影。"},{"en":"To come to terms with something means to accept, understand, and deal with it.","zh":"come to terms with something 是指接受、理解並處理某事。"},{"en":"A student may need time to come to terms with a disappointing exam result.","zh":"學生可能需要時間接受並處理令人失望的考試結果。"},{"en":"An industry comes to terms with change when it stops denying it and begins to adapt.","zh":"當行業停止否認並開始適應變化時，就是接受並處理變化。"},{"en":"This phrase suggests adjustment after difficulty or surprise.","zh":"這個短語暗示在困難或驚訝之後作出調整。"}],"source":"105 - film.pdf","sourcePage":18},{"front":"the challenge of the Asian market","meaning":"亞洲市場的挑戰","examples":[{"en":"The option refers to the challenge of the Asian market.","zh":"該選項提到亞洲市場的挑戰。"},{"en":"The challenge of the Asian market means the difficulty or pressure created by Asian audiences, industries, or competitors.","zh":"challenge of the Asian market 是由亞洲觀眾、產業或競爭者造成的困難或壓力。"},{"en":"A Western company may face the challenge of the Asian market if local brands understand consumers better.","zh":"如果本地品牌更了解消費者，西方公司可能面對亞洲市場的挑戰。"},{"en":"Film industries face market challenges when another region grows quickly and attracts audiences.","zh":"當另一地區迅速成長並吸引觀眾時，電影工業就面對市場挑戰。"},{"en":"This phrase frames Asia as an important commercial force.","zh":"這個短語把亞洲呈現為重要商業力量。"}],"source":"105 - film.pdf","sourcePage":18}],"ielts/reading/passage-2/Practice 106":[{"front":"Worldly Wealth","meaning":"世俗財富；物質財富","examples":[{"en":"The passage Worldly Wealth considers whether everyone can enjoy a rich lifestyle without damaging the planet.","zh":"文章《Worldly Wealth》思考是否每個人都能享有富裕生活而不破壞地球。"},{"en":"Worldly wealth means material comfort, possessions, money, and the physical benefits of a prosperous life.","zh":"Worldly wealth 指物質舒適、財產、金錢和富裕生活帶來的實體好處。"},{"en":"A family may measure worldly wealth by its home, savings, car, and ability to travel.","zh":"一個家庭可能以住房、儲蓄、汽車和旅行能力來衡量物質財富。"},{"en":"If people pursue worldly wealth without limits, natural resources may come under pressure.","zh":"如果人們無限制地追求物質財富，自然資源可能承受壓力。"},{"en":"The phrase focuses on material prosperity, not spiritual or emotional richness.","zh":"這個片語集中於物質繁榮，而不是精神或情感富足。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":1},{"front":"future population","meaning":"未來人口","examples":[{"en":"The future population of the world may reach around nine billion.","zh":"世界未來人口可能達到約九十億。"},{"en":"Future population means the number of people expected to live in a place later.","zh":"future population 指某地方日後預計會有的人口數量。"},{"en":"City planners study future population before deciding how many schools to build.","zh":"城市規劃者在決定建多少學校前會研究未來人口。"},{"en":"If future population grows quickly, housing, food, and transport demand will rise.","zh":"如果未來人口迅速增長，住房、食物和交通需求都會上升。"},{"en":"The phrase is often used when discussing long-term planning.","zh":"這個片語常用於討論長遠規劃。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":1},{"front":"enjoy a comfortable lifestyle","meaning":"享有舒適的生活方式","examples":[{"en":"The writer asks whether the future population can enjoy a comfortable lifestyle.","zh":"作者問未來人口能否享有舒適的生活方式。"},{"en":"Enjoy a comfortable lifestyle means live with enough space, goods, services, and security.","zh":"enjoy a comfortable lifestyle 指生活中有足夠空間、物品、服務和安全感。"},{"en":"A family may enjoy a comfortable lifestyle if they can afford rent, food, transport, and rest.","zh":"如果家庭負擔得起租金、食物、交通和休息，就可能享有舒適生活方式。"},{"en":"If incomes rise and prices fall, more people may enjoy a comfortable lifestyle.","zh":"如果收入上升而價格下降，更多人可能享有舒適生活方式。"},{"en":"The phrase suggests more than survival, but not necessarily extreme luxury.","zh":"這個片語暗示不只是生存，但不一定是極端奢華。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":1},{"front":"possessions, space and mobility","meaning":"財物、空間和流動能力","examples":[{"en":"Many people want possessions, space and mobility.","zh":"許多人想要財物、空間和流動能力。"},{"en":"Possessions, space and mobility mean material goods, enough room, and freedom to travel or move.","zh":"possessions, space and mobility 指物質財產、足夠空間，以及旅行或移動的自由。"},{"en":"A person may want possessions, space and mobility in the form of a phone, a larger flat, and a car.","zh":"一個人可能想要手機、較大單位和汽車，作為財物、空間和流動能力。"},{"en":"As incomes rise, demand for possessions, space and mobility often increases.","zh":"隨着收入上升，對財物、空間和流動能力的需求通常增加。"},{"en":"The phrase summarises common material goals in modern life.","zh":"這個片語概括現代生活中常見的物質目標。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":1},{"front":"without crippling the environment","meaning":"在不嚴重破壞環境的情況下","examples":[{"en":"The question is whether people can live comfortably without crippling the environment.","zh":"問題是人們能否在不嚴重破壞環境的情況下舒適生活。"},{"en":"Without crippling the environment means without severely damaging nature’s ability to function.","zh":"without crippling the environment 指不嚴重破壞自然正常運作的能力。"},{"en":"A city can expand without crippling the environment if it protects rivers, trees, and clean air.","zh":"如果城市保護河流、樹木和清潔空氣，就可以在不嚴重破壞環境下擴張。"},{"en":"If factories waste energy and pollute water, they may cripple the environment.","zh":"如果工廠浪費能源並污染食水，就可能嚴重破壞環境。"},{"en":"The phrase suggests avoiding serious long-term ecological harm.","zh":"這個片語暗示避免嚴重長期生態傷害。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":1},{"front":"be expected to stabilise at","meaning":"預計會穩定在……","examples":[{"en":"The world’s population is expected to stabilise at around nine billion.","zh":"世界人口預計會穩定在約九十億。"},{"en":"Be expected to stabilise at means be predicted to stop rising or falling and remain near a level.","zh":"be expected to stabilise at 指被預測會停止上升或下降，並維持在某水平附近。"},{"en":"A school’s enrolment may be expected to stabilise at 800 students after several years of growth.","zh":"學校收生人數在多年增長後，可能預計會穩定在800人。"},{"en":"If population stabilises at a high level, planners still need enough food and housing.","zh":"如果人口穩定在高水平，規劃者仍需要足夠食物和住房。"},{"en":"The phrase combines prediction with a future steady point.","zh":"這個片語結合預測和未來穩定點。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":1},{"front":"around nine billion","meaning":"約九十億","examples":[{"en":"The world’s population may stabilise at around nine billion.","zh":"世界人口可能穩定在約九十億。"},{"en":"Around nine billion means approximately 9,000,000,000.","zh":"around nine billion 指大約9,000,000,000。"},{"en":"A global population of around nine billion would require enormous food and energy systems.","zh":"約九十億的全球人口會需要龐大的食物和能源系統。"},{"en":"If around nine billion people seek comfort, resource efficiency becomes very important.","zh":"如果約九十億人追求舒適生活，資源效率就變得非常重要。"},{"en":"The phrase gives an approximate number, not an exact count.","zh":"這個片語給出大約數字，而不是精確數目。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":1},{"front":"the lifestyle enjoyed by","meaning":"……所享有的生活方式","examples":[{"en":"The writer discusses the lifestyle enjoyed today only by the wealthy.","zh":"作者討論今日只有富裕人士所享有的生活方式。"},{"en":"The lifestyle enjoyed by a group means the way of living that group currently has.","zh":"the lifestyle enjoyed by 某群體指該群體目前擁有的生活方式。"},{"en":"The lifestyle enjoyed by many office workers includes online shopping, commuting, and eating out.","zh":"許多辦公室員工所享有的生活方式包括網購、通勤和外出用餐。"},{"en":"If the lifestyle enjoyed by the wealthy spreads globally, energy demand may increase.","zh":"如果富裕人士所享有的生活方式擴展至全球，能源需求可能增加。"},{"en":"The phrase identifies whose standard of living is being described.","zh":"這個片語指出正在描述誰的生活水平。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":1},{"front":"the wealthy","meaning":"富裕人士","examples":[{"en":"The lifestyle of the wealthy may one day become more widely available.","zh":"富裕人士的生活方式有一天可能變得更廣泛可得。"},{"en":"The wealthy are people who have a lot of money, property, or financial security.","zh":"the wealthy 指擁有大量金錢、財產或財務保障的人。"},{"en":"The wealthy can often afford private healthcare, large homes, and frequent travel.","zh":"富裕人士通常負擔得起私人醫療、大型住房和頻繁旅行。"},{"en":"If technology becomes cheaper, goods once limited to the wealthy may reach ordinary families.","zh":"如果科技變得更便宜，曾只限於富裕人士的物品可能進入普通家庭。"},{"en":"The phrase refers to rich people as a social group.","zh":"這個片語把有錢人視為一個社會群體。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":1},{"front":"one school of thought","meaning":"一種思想流派；一種觀點","examples":[{"en":"One school of thought says that a rich global lifestyle is impossible.","zh":"一種觀點認為全球富裕生活方式是不可能的。"},{"en":"One school of thought means one particular way of thinking about an issue.","zh":"one school of thought 指看待某議題的一種特定思路。"},{"en":"One school of thought says homework builds discipline, while another says it increases stress.","zh":"一種觀點認為功課建立紀律，另一種則認為功課增加壓力。"},{"en":"If one school of thought dominates public debate, other possibilities may be ignored.","zh":"如果一種觀點主導公共討論，其他可能性可能被忽視。"},{"en":"The phrase is useful when introducing competing opinions.","zh":"這個片語在引入互相競爭的觀點時很有用。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":1},{"front":"the majority of","meaning":"大多數……","examples":[{"en":"Some argue that the majority of the world’s people must remain poor.","zh":"有些人認為世界大多數人必須保持貧窮。"},{"en":"The majority of means more than half of a group.","zh":"the majority of 指一個群體中超過一半。"},{"en":"The majority of students in a class may prefer online revision before exams.","zh":"班中大多數學生可能較喜歡考試前網上溫習。"},{"en":"If the majority of people cannot afford basic goods, inequality becomes severe.","zh":"如果大多數人負擔不起基本物品，不平等就變得嚴重。"},{"en":"The phrase describes the larger part of a group.","zh":"這個片語描述群體中較大部分。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":2},{"front":"resign themselves to","meaning":"使自己接受；無奈接受","examples":[{"en":"Some people believe the poor must resign themselves to poverty forever.","zh":"有些人認為窮人必須無奈接受永久貧窮。"},{"en":"Resign themselves to means accept an unpleasant situation because they think it cannot be changed.","zh":"resign themselves to 指因認為無法改變而接受不愉快情況。"},{"en":"A student should not resign themselves to poor grammar if regular practice can help.","zh":"如果定期練習有幫助，學生不應無奈接受文法差。"},{"en":"If people resign themselves to poverty, they may stop demanding better opportunities.","zh":"如果人們無奈接受貧窮，可能停止要求更好機會。"},{"en":"The phrase suggests reluctant acceptance, not happiness.","zh":"這個片語暗示勉強接受，而不是快樂接受。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":2},{"front":"poverty forever","meaning":"永久貧窮","examples":[{"en":"One school of thought says many people must accept poverty forever.","zh":"一種觀點認為許多人必須接受永久貧窮。"},{"en":"Poverty forever means a permanent state of being poor without realistic escape.","zh":"poverty forever 指永久處於貧窮狀態，沒有實際脫離機會。"},{"en":"No child should be told that poverty forever is their only future.","zh":"沒有孩子應被告知永久貧窮是他們唯一未來。"},{"en":"If education and jobs improve, poverty forever becomes less likely.","zh":"如果教育和工作改善，永久貧窮就較不可能。"},{"en":"The phrase expresses a bleak and fixed view of inequality.","zh":"這個片語表達對不平等的悲觀固定看法。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":2},{"front":"rich nations","meaning":"富裕國家","examples":[{"en":"Some argue that rich nations must adopt simpler lifestyles.","zh":"有些人認為富裕國家必須採取較簡樸的生活方式。"},{"en":"Rich nations are countries with high income, strong industries, and advanced services.","zh":"rich nations 指收入高、工業強、服務先進的國家。"},{"en":"Rich nations often consume more energy and manufactured goods than poorer nations.","zh":"富裕國家通常比貧窮國家消耗更多能源和製成品。"},{"en":"If rich nations reduce waste, global environmental pressure may fall.","zh":"如果富裕國家減少浪費，全球環境壓力可能下降。"},{"en":"The phrase refers to wealthy countries, not only wealthy individuals.","zh":"這個片語指富裕國家，而不只是富裕個人。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":2},{"front":"revert to","meaning":"回復到……","examples":[{"en":"Some people think rich nations must revert to simpler lifestyles.","zh":"有些人認為富裕國家必須回復到較簡樸的生活方式。"},{"en":"Revert to means return to an earlier condition, habit, or system.","zh":"revert to 指回到較早的狀態、習慣或制度。"},{"en":"A school may revert to paper notices if the online system fails.","zh":"如果網上系統失效，學校可能回復到紙本通知。"},{"en":"If society reverts to simpler lifestyles, people may use fewer machines and consume less energy.","zh":"如果社會回復到較簡樸生活方式，人們可能使用較少機器和能源。"},{"en":"The phrase suggests going back, not moving forward.","zh":"這個片語暗示回到過去，而不是向前。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":2},{"front":"simpler lifestyles","meaning":"較簡樸的生活方式","examples":[{"en":"Some believe simpler lifestyles are necessary to save the planet.","zh":"有些人認為較簡樸的生活方式是拯救地球所必需的。"},{"en":"Simpler lifestyles are ways of living with fewer possessions, less consumption, and lower energy use.","zh":"simpler lifestyles 指擁有較少物品、較少消費和較低能源使用的生活方式。"},{"en":"A family may choose a simpler lifestyle by cooking at home and buying fewer things.","zh":"一個家庭可能透過在家煮食和少買東西選擇較簡樸生活方式。"},{"en":"If many people adopt simpler lifestyles, waste and emissions may decrease.","zh":"如果很多人採取較簡樸生活方式，浪費和排放可能減少。"},{"en":"The phrase suggests reduced material consumption.","zh":"這個片語暗示降低物質消耗。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":2},{"front":"in order to","meaning":"為了","examples":[{"en":"Rich nations may need to change in order to save the planet.","zh":"富裕國家可能需要改變，為了拯救地球。"},{"en":"In order to means for the purpose of doing something.","zh":"in order to 指為了做某事。"},{"en":"Students revise past papers in order to understand exam patterns.","zh":"學生做歷屆試題，為了理解考試模式。"},{"en":"If a city wants cleaner air, it may limit traffic in order to reduce pollution.","zh":"如果城市想空氣更清潔，可能限制交通以減少污染。"},{"en":"The phrase clearly links an action with its purpose.","zh":"這個片語清楚把行動與目的連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":2},{"front":"save the planet","meaning":"拯救地球","examples":[{"en":"Some argue that simpler lifestyles are needed to save the planet.","zh":"有些人認為需要較簡樸生活方式來拯救地球。"},{"en":"Save the planet means protect Earth’s environment from serious damage.","zh":"save the planet 指保護地球環境免受嚴重破壞。"},{"en":"Recycling alone cannot save the planet if energy use and pollution keep rising.","zh":"如果能源使用和污染持續上升，單靠回收不能拯救地球。"},{"en":"If people want to save the planet, they must reduce harm to climate, forests, and oceans.","zh":"如果人們想拯救地球，就必須減少對氣候、森林和海洋的傷害。"},{"en":"The phrase is broad and often used in environmental arguments.","zh":"這個片語範圍很廣，常用於環保論述。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":2},{"front":"admittedly","meaning":"誠然","examples":[{"en":"Admittedly, there may be political or social barriers to achieving a rich world.","zh":"誠然，實現富裕世界可能有政治或社會障礙。"},{"en":"Admittedly means the writer accepts a point before continuing the argument.","zh":"admittedly 指作者先承認某一點，然後繼續論證。"},{"en":"Admittedly, online learning is convenient, but not every student has a quiet place to study.","zh":"誠然，網上學習很方便，但不是每個學生都有安靜地方溫習。"},{"en":"If a writer says admittedly, they are showing fairness toward an opposing point.","zh":"如果作者使用 admittedly，就是對相反觀點表示公平。"},{"en":"The word softens an argument by recognising a limitation.","zh":"這個詞透過承認限制來緩和論點。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":2},{"front":"political or social barriers","meaning":"政治或社會障礙","examples":[{"en":"Political or social barriers may prevent a rich world from being achieved.","zh":"政治或社會障礙可能阻止富裕世界實現。"},{"en":"Political or social barriers are obstacles caused by governments, laws, power, inequality, or public attitudes.","zh":"political or social barriers 是由政府、法律、權力、不平等或公眾態度造成的障礙。"},{"en":"A good housing plan may fail because of political or social barriers.","zh":"良好住房計劃可能因政治或社會障礙而失敗。"},{"en":"If political or social barriers remain strong, technology alone may not solve poverty.","zh":"如果政治或社會障礙仍然強大，單靠科技未必能解決貧窮。"},{"en":"The phrase points to human systems rather than physical limits.","zh":"這個片語指人類制度，而不是物理限制。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":2},{"front":"achieve a rich world","meaning":"實現富裕世界","examples":[{"en":"The writer considers whether humanity can achieve a rich world.","zh":"作者思考人類能否實現富裕世界。"},{"en":"Achieve a rich world means create a world where most or all people live prosperously.","zh":"achieve a rich world 指創造一個大多數或所有人都富足生活的世界。"},{"en":"Education, health care, and cheap clean energy could help society achieve a rich world.","zh":"教育、醫療和廉價清潔能源可幫助社會實現富裕世界。"},{"en":"If wealth is distributed unfairly, humanity may fail to achieve a rich world.","zh":"如果財富分配不公，人類可能無法實現富裕世界。"},{"en":"The phrase describes a global goal of widespread prosperity.","zh":"這個片語描述廣泛繁榮的全球目標。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":3},{"front":"in fact","meaning":"事實上","examples":[{"en":"In fact, the writer sees no insuperable ecological reason against prosperity.","zh":"事實上，作者看不到任何無法克服的生態原因反對繁榮。"},{"en":"In fact introduces a statement that strengthens, corrects, or clarifies what came before.","zh":"in fact 引出一個加強、修正或澄清前文的陳述。"},{"en":"Many people think the shop is expensive; in fact, its lunch sets are quite cheap.","zh":"許多人以為那間店很貴；事實上，它的午餐套餐相當便宜。"},{"en":"If a writer says in fact, they may be challenging a common assumption.","zh":"如果作者說 in fact，可能是在挑戰常見假設。"},{"en":"The phrase often signals a clearer or stronger point.","zh":"這個片語常標示更清楚或更有力的觀點。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":3},{"front":"insuperable reason","meaning":"無法克服的原因","examples":[{"en":"There seems to be no insuperable reason why nine billion people cannot live comfortably.","zh":"似乎沒有無法克服的原因，使九十億人不能舒適生活。"},{"en":"An insuperable reason is a reason so strong that it cannot be overcome.","zh":"insuperable reason 指強大到不能克服的原因。"},{"en":"Lack of money is difficult, but it is not always an insuperable reason to stop studying.","zh":"缺錢很困難，但不一定是停止學習的無法克服原因。"},{"en":"If no insuperable reason exists, a difficult goal may still be possible.","zh":"如果沒有無法克服的原因，困難目標仍可能達成。"},{"en":"The phrase describes an obstacle that would completely block success.","zh":"這個片語描述會完全阻止成功的障礙。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":3},{"front":"physical or ecological reason","meaning":"物理或生態方面的原因","examples":[{"en":"The writer sees no insuperable physical or ecological reason against a comfortable global lifestyle.","zh":"作者看不到任何無法克服的物理或生態原因，反對全球舒適生活方式。"},{"en":"A physical or ecological reason is a limit caused by nature, materials, energy, land, or ecosystems.","zh":"physical or ecological reason 是由自然、材料、能源、土地或生態系統造成的限制。"},{"en":"Lack of clean water can be a physical or ecological reason why a town cannot expand safely.","zh":"缺乏清潔食水可以是一個城鎮不能安全擴張的物理或生態原因。"},{"en":"If no physical or ecological reason blocks prosperity, social organisation becomes the main issue.","zh":"如果沒有物理或生態原因阻礙繁榮，社會組織就成為主要問題。"},{"en":"The phrase contrasts natural limits with political or social problems.","zh":"這個片語把自然限制與政治或社會問題作對比。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":3},{"front":"slightly more advanced than","meaning":"比……稍為先進","examples":[{"en":"The lifestyle may be possible with technology only slightly more advanced than today’s.","zh":"這種生活方式可能只需比今日科技稍為先進的技術便可實現。"},{"en":"Slightly more advanced than means a little more developed or improved than something now.","zh":"slightly more advanced than 指比目前某物稍為更發展或更改良。"},{"en":"A phone slightly more advanced than today’s models may have a longer battery and better camera.","zh":"比今日型號稍為先進的手機可能有更長電池和更好相機。"},{"en":"If only slightly more advanced technology is needed, the goal may be nearer than expected.","zh":"如果只需要稍為更先進的科技，目標可能比預期更接近。"},{"en":"The phrase suggests small progress, not science fiction.","zh":"這個片語暗示小幅進步，而不是科幻幻想。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":3},{"front":"technology we now possess","meaning":"我們現時擁有的科技","examples":[{"en":"The writer believes current technology is close to what is needed.","zh":"作者相信目前科技已接近所需水平。"},{"en":"Technology we now possess means the tools and scientific knowledge already available today.","zh":"technology we now possess 指今日已經可用的工具和科學知識。"},{"en":"The technology we now possess can already help people work, learn, and communicate remotely.","zh":"我們現時擁有的科技已能幫助人們遠程工作、學習和溝通。"},{"en":"If technology we now possess is used wisely, some future problems may be reduced.","zh":"如果我們現時擁有的科技被明智使用，一些未來問題可能減少。"},{"en":"The phrase stresses present ability, not distant invention.","zh":"這個片語強調目前能力，而不是遙遠發明。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":3},{"front":"future of civilisation","meaning":"文明的未來","examples":[{"en":"The writer discusses the future of civilisation.","zh":"作者討論文明的未來。"},{"en":"Future of civilisation means the long-term direction of human society, culture, technology, and survival.","zh":"future of civilisation 指人類社會、文化、科技和生存的長遠方向。"},{"en":"Climate change makes many students think seriously about the future of civilisation.","zh":"氣候變化令許多學生認真思考文明的未來。"},{"en":"If energy, food, and housing systems improve, the future of civilisation may look more hopeful.","zh":"如果能源、食物和住房系統改善，文明的未來可能更有希望。"},{"en":"The phrase is broad and concerns humanity as a whole.","zh":"這個片語範圍很廣，關乎整體人類。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":3},{"front":"ought to start by","meaning":"應該由……開始","examples":[{"en":"We ought to start by asking what people want.","zh":"我們應該由詢問人們想要甚麼開始。"},{"en":"Ought to start by means should begin with a particular first step.","zh":"ought to start by 指應以某個特定第一步開始。"},{"en":"A teacher ought to start by checking what students already understand.","zh":"老師應該由檢查學生已經明白甚麼開始。"},{"en":"If planners want better cities, they ought to start by asking how people actually live.","zh":"如果規劃者想要更好的城市，就應該由詢問人們實際如何生活開始。"},{"en":"The phrase gives advice about the correct beginning.","zh":"這個片語提供關於正確開端的建議。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":3},{"front":"evidence demonstrates that","meaning":"證據顯示","examples":[{"en":"The evidence demonstrates that richer people want more technology and mobility.","zh":"證據顯示，較富裕的人想要更多科技和流動能力。"},{"en":"Evidence demonstrates that means proof or data clearly shows something.","zh":"evidence demonstrates that 指證據或數據清楚顯示某事。"},{"en":"Attendance records demonstrate that students arrive earlier when buses are reliable.","zh":"出席紀錄顯示，當巴士可靠時，學生會較早到達。"},{"en":"If evidence demonstrates that people want more space, housing policy should respond.","zh":"如果證據顯示人們想要更多空間，住房政策就應回應。"},{"en":"The phrase introduces a claim supported by proof.","zh":"這個片語引出有證據支持的主張。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":3},{"front":"as people get richer","meaning":"隨着人們變得更富裕","examples":[{"en":"As people get richer, they tend to want more personal technology.","zh":"隨着人們變得更富裕，他們往往想要更多個人科技。"},{"en":"As people get richer means when people’s income or wealth increases.","zh":"as people get richer 指當人們收入或財富增加時。"},{"en":"As people get richer, they may spend more on travel, better housing, and education.","zh":"隨着人們變得更富裕，他們可能在旅遊、更好住房和教育上花更多錢。"},{"en":"If people get richer, demand for energy and consumer goods often rises.","zh":"如果人們變得更富裕，對能源和消費品的需求通常上升。"},{"en":"The phrase links economic growth with changing expectations.","zh":"這個片語把經濟增長與期望改變連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":3},{"front":"a greater range of","meaning":"更廣泛種類的……","examples":[{"en":"Richer people want a greater range of personal technology.","zh":"較富裕的人想要更廣泛種類的個人科技。"},{"en":"A greater range of means more different types or choices of something.","zh":"a greater range of 指更多不同種類或選擇的某事物。"},{"en":"A library with a greater range of books can serve children, adults, and researchers.","zh":"擁有更廣泛種類書籍的圖書館，可以服務兒童、成人和研究人員。"},{"en":"If people can afford a greater range of goods, consumption may become more diverse.","zh":"如果人們負擔得起更廣泛種類的貨品，消費可能變得更多元。"},{"en":"The phrase emphasises variety, not just quantity.","zh":"這個片語強調種類，而不只是數量。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":4},{"front":"personal technology","meaning":"個人科技","examples":[{"en":"Telephones, washing machines and cars are examples of personal technology.","zh":"電話、洗衣機和汽車都是個人科技的例子。"},{"en":"Personal technology means machines or devices used by individuals or households in daily life.","zh":"personal technology 指個人或家庭在日常生活中使用的機器或裝置。"},{"en":"A laptop, phone, smartwatch, or washing machine can be personal technology.","zh":"手提電腦、手機、智能手錶或洗衣機都可以是個人科技。"},{"en":"If personal technology becomes cheaper, more families can save time and effort.","zh":"如果個人科技變得更便宜，更多家庭可以節省時間和力氣。"},{"en":"The phrase refers to technology used personally, not only in factories.","zh":"這個片語指個人使用的科技，而不只是工廠科技。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":4},{"front":"lots of room","meaning":"大量空間","examples":[{"en":"People often want lots of room near natural surroundings.","zh":"人們通常想要靠近自然環境的大量空間。"},{"en":"Lots of room means plenty of physical space for living, working, or moving freely.","zh":"lots of room 指有充足實體空間居住、工作或自由活動。"},{"en":"Children need lots of room to run and play safely.","zh":"孩子需要大量空間安全奔跑和玩耍。"},{"en":"If people want lots of room, cities may spread outward unless housing is planned well.","zh":"如果人們想要大量空間，城市可能向外擴張，除非住房規劃得好。"},{"en":"The phrase suggests spaciousness and comfort.","zh":"這個片語暗示寬敞和舒適。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":4},{"front":"natural surroundings","meaning":"自然環境","examples":[{"en":"Many people prefer to live near or in natural surroundings.","zh":"許多人較喜歡住在自然環境附近或其中。"},{"en":"Natural surroundings are environments with trees, water, open land, wildlife, or other natural features.","zh":"natural surroundings 是有樹木、水域、開闊土地、野生動物或其他自然特色的環境。"},{"en":"A flat near a park gives residents easier access to natural surroundings.","zh":"靠近公園的單位讓居民更容易接觸自然環境。"},{"en":"If people live near natural surroundings, they may feel calmer and healthier.","zh":"如果人們住近自然環境，可能感覺更平靜和健康。"},{"en":"The phrase contrasts nature with dense built-up areas.","zh":"這個片語把自然與密集建成區作對比。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":4},{"front":"greater speed in travel","meaning":"更快的出行速度","examples":[{"en":"People want greater speed in travel as they become richer.","zh":"隨着人們變得更富裕，他們想要更快的出行速度。"},{"en":"Greater speed in travel means being able to move from place to place more quickly.","zh":"greater speed in travel 指能更快從一地移動到另一地。"},{"en":"High-speed trains provide greater speed in travel between cities.","zh":"高速鐵路提供城市之間更快的出行速度。"},{"en":"If people expect greater speed in travel, demand for better transport technology may rise.","zh":"如果人們期待更快出行速度，對更好交通科技的需求可能上升。"},{"en":"The phrase connects mobility with time-saving.","zh":"這個片語把流動能力與節省時間連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":4},{"front":"the developed world","meaning":"發達世界；發達國家","examples":[{"en":"In the developed world, many technologies have become necessities.","zh":"在發達世界，許多科技已成為必需品。"},{"en":"The developed world means wealthy industrialised countries with advanced infrastructure and services.","zh":"the developed world 指擁有先進基建和服務的富裕工業化國家。"},{"en":"In the developed world, internet access is often treated as part of normal daily life.","zh":"在發達世界，互聯網接入常被視為正常日常生活的一部分。"},{"en":"If a product becomes common in the developed world, people elsewhere may later expect it too.","zh":"如果產品在發達世界變得普遍，其他地方的人日後也可能期待擁有。"},{"en":"The phrase is used for broad economic comparison.","zh":"這個片語用於廣泛經濟比較。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":4},{"front":"become necessities","meaning":"成為必需品","examples":[{"en":"Cars and washing machines have become necessities within a generation or two.","zh":"汽車和洗衣機在一兩代人之內已成為必需品。"},{"en":"Become necessities means change from optional luxuries into things people feel they need.","zh":"become necessities 指由可有可無的奢侈品變成人們覺得需要的東西。"},{"en":"Smartphones have become necessities for many workers who need messages and maps.","zh":"對需要訊息和地圖的許多工人而言，智能手機已成為必需品。"},{"en":"If goods become necessities, households may feel unable to live normally without them.","zh":"如果貨品成為必需品，家庭可能覺得沒有它們就不能正常生活。"},{"en":"The phrase shows how expectations change over time.","zh":"這個片語顯示期望如何隨時間改變。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":4},{"front":"within a generation or two","meaning":"在一兩代人之內","examples":[{"en":"Many luxuries become necessities within a generation or two.","zh":"許多奢侈品在一兩代人之內成為必需品。"},{"en":"Within a generation or two means over the time of one or two age groups, roughly several decades.","zh":"within a generation or two 指在一兩代人的時間內，大約數十年間。"},{"en":"Within a generation or two, online banking became normal for many families.","zh":"在一兩代人之內，網上銀行對許多家庭而言變得正常。"},{"en":"If technology spreads within a generation or two, social expectations can change quickly.","zh":"如果科技在一兩代人之內普及，社會期望可以迅速改變。"},{"en":"The phrase gives a medium-term historical timescale.","zh":"這個片語給出中期歷史時間尺度。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":4},{"front":"increasing productivity","meaning":"生產力提高","examples":[{"en":"Increasing productivity can reduce the cost of manufactured goods.","zh":"生產力提高可以降低製成品成本。"},{"en":"Increasing productivity means producing more goods or services with the same or fewer resources.","zh":"increasing productivity 指用相同或較少資源生產更多貨品或服務。"},{"en":"A restaurant increases productivity when better kitchen planning lets staff serve more customers.","zh":"當更好廚房規劃讓員工服務更多客人，餐廳的生產力就提高。"},{"en":"If productivity increases, prices may fall and living standards may rise.","zh":"如果生產力提高，價格可能下降，生活水平可能上升。"},{"en":"The phrase focuses on efficiency in production.","zh":"這個片語集中於生產效率。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":4},{"front":"result in decreasing costs","meaning":"導致成本下降","examples":[{"en":"Increasing productivity results in decreasing costs for many goods.","zh":"生產力提高導致許多貨品成本下降。"},{"en":"Result in decreasing costs means cause the price or expense of producing something to fall.","zh":"result in decreasing costs 指導致某物價格或生產開支下降。"},{"en":"Better delivery software can result in decreasing costs for a small shop.","zh":"更好的送貨軟件可以導致小店成本下降。"},{"en":"If machines make goods faster, this may result in decreasing costs for consumers.","zh":"如果機器更快製造貨品，這可能導致消費者成本下降。"},{"en":"The phrase links improvement with lower expense.","zh":"這個片語把改善與較低開支連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":4},{"front":"be responsible for","meaning":"是……的原因","examples":[{"en":"Lower costs have been responsible for gains in living standards.","zh":"較低成本是生活水平提高的原因。"},{"en":"Be responsible for means be the cause of something.","zh":"be responsible for 指是某事的原因。"},{"en":"Good public transport can be responsible for shorter commuting times.","zh":"良好公共交通可以是通勤時間縮短的原因。"},{"en":"If cheaper goods are responsible for higher living standards, productivity matters greatly.","zh":"如果較便宜貨品是生活水平提高的原因，生產力就非常重要。"},{"en":"The phrase identifies what produces a result.","zh":"這個片語指出產生結果的因素。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":5},{"front":"the greatest gains in","meaning":"……方面最大的提升","examples":[{"en":"Productivity has produced the greatest gains in the standard of living.","zh":"生產力在生活水平方面帶來最大的提升。"},{"en":"The greatest gains in something are the biggest improvements in that area.","zh":"the greatest gains in 指某方面最大的改善。"},{"en":"A school may see the greatest gains in reading after adding daily practice.","zh":"學校加入每日練習後，閱讀方面可能有最大的提升。"},{"en":"If technology brings the greatest gains in living standards, access to it becomes important.","zh":"如果科技帶來生活水平方面最大的提升，獲得科技就變得重要。"},{"en":"The phrase compares improvements and highlights the largest one.","zh":"這個片語比較改善幅度並突出最大者。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":5},{"front":"standard of living","meaning":"生活水平","examples":[{"en":"Lower prices can improve the standard of living.","zh":"較低價格可以改善生活水平。"},{"en":"Standard of living means the level of comfort, goods, health, and services people can enjoy.","zh":"standard of living 指人們能享有的舒適、貨品、健康和服務水平。"},{"en":"A family’s standard of living may rise when rent becomes cheaper and wages increase.","zh":"當租金下降而工資上升，家庭生活水平可能提高。"},{"en":"If food, transport, and appliances become affordable, the standard of living improves.","zh":"如果食物、交通和電器變得可負擔，生活水平就改善。"},{"en":"The phrase measures material wellbeing in daily life.","zh":"這個片語衡量日常生活中的物質福祉。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":5},{"front":"there is every reason to believe that","meaning":"完全有理由相信","examples":[{"en":"There is every reason to believe that productivity gains will continue.","zh":"完全有理由相信生產力提升會持續。"},{"en":"There is every reason to believe that means there are strong grounds for thinking something is true.","zh":"there is every reason to believe that 指有充分理由認為某事為真。"},{"en":"There is every reason to believe that students will improve if they practise daily.","zh":"完全有理由相信，如果學生每天練習，他們會進步。"},{"en":"If past evidence is strong, there is every reason to believe the trend may continue.","zh":"如果過往證據強，就完全有理由相信趨勢可能持續。"},{"en":"The phrase expresses confidence based on evidence.","zh":"這個片語表達基於證據的信心。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":5},{"front":"as affluence grows","meaning":"隨着富裕程度提高","examples":[{"en":"As affluence grows, energy and raw-material use may increase.","zh":"隨着富裕程度提高，能源和原材料使用可能增加。"},{"en":"As affluence grows means as people or societies become wealthier.","zh":"as affluence grows 指隨着人們或社會變得更富裕。"},{"en":"As affluence grows, families may buy more appliances and travel more often.","zh":"隨着富裕程度提高，家庭可能購買更多電器並更常旅行。"},{"en":"If affluence grows without efficiency, environmental pressure can rise.","zh":"如果富裕程度提高但效率沒有提高，環境壓力可能上升。"},{"en":"The phrase links rising wealth with changing consumption.","zh":"這個片語把財富上升與消費變化連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":5},{"front":"amounts of energy","meaning":"能源用量","examples":[{"en":"The amounts of energy used to produce machinery will escalate.","zh":"生產機械所使用的能源用量將會急升。"},{"en":"Amounts of energy means quantities of power or fuel used for work, machines, or production.","zh":"amounts of energy 指用於工作、機器或生產的電力或燃料數量。"},{"en":"A factory records the amounts of energy used each month to control costs.","zh":"工廠每月記錄能源用量以控制成本。"},{"en":"If amounts of energy rise sharply, companies may search for more efficient systems.","zh":"如果能源用量急升，公司可能尋找更高效系統。"},{"en":"The phrase focuses on measurable energy use.","zh":"這個片語集中於可量度的能源使用。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":5},{"front":"raw materials","meaning":"原材料","examples":[{"en":"More raw materials may be needed to produce machinery.","zh":"生產機械可能需要更多原材料。"},{"en":"Raw materials are basic natural or processed substances used to make products.","zh":"raw materials 是用來製造產品的基本天然或加工物質。"},{"en":"Wood, metal, cotton, and oil can be raw materials for different industries.","zh":"木材、金屬、棉花和石油可成為不同行業的原材料。"},{"en":"If demand for machines grows, demand for raw materials may also grow.","zh":"如果對機器的需求增長，對原材料的需求也可能增長。"},{"en":"The phrase refers to inputs before manufacturing.","zh":"這個片語指製造前的投入材料。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":5},{"front":"produce machinery","meaning":"生產機械","examples":[{"en":"Energy and raw materials are used to produce machinery.","zh":"能源和原材料被用來生產機械。"},{"en":"Produce machinery means manufacture machines or mechanical equipment.","zh":"produce machinery 指製造機器或機械設備。"},{"en":"A factory may produce machinery for farms, hospitals, or construction sites.","zh":"工廠可能為農場、醫院或建築工地生產機械。"},{"en":"If more societies buy machines, industries must produce machinery in larger quantities.","zh":"如果更多社會購買機器，工業就必須大量生產機械。"},{"en":"The phrase describes industrial manufacturing.","zh":"這個片語描述工業製造。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":5},{"front":"therefore escalate","meaning":"因而急升","examples":[{"en":"The use of energy and raw materials will therefore escalate.","zh":"能源和原材料使用因而會急升。"},{"en":"Therefore escalate means increase sharply as a result of what has just been explained.","zh":"therefore escalate 指由於剛解釋的原因而迅速增加。"},{"en":"If rent and wages both rise, restaurant prices may therefore escalate.","zh":"如果租金和工資都上升，餐廳價格可能因而急升。"},{"en":"If more machines are produced, demand for metals and fuel may therefore escalate.","zh":"如果生產更多機器，對金屬和燃料的需求可能因而急升。"},{"en":"The phrase links a cause to a rapid increase.","zh":"這個片語把原因與快速增加連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":5},{"front":"need not mean","meaning":"不一定意味","examples":[{"en":"Greater use of materials need not mean an end to the machine age.","zh":"更多使用材料不一定意味機器時代的終結。"},{"en":"Need not mean means does not necessarily lead to or imply something.","zh":"need not mean 指不一定導致或意味某事。"},{"en":"A low test score need not mean a student cannot improve.","zh":"低測驗分數不一定意味學生不能進步。"},{"en":"If resource use rises, it need not mean disaster if recycling and efficiency improve.","zh":"如果資源使用上升，只要回收和效率改善，就不一定意味災難。"},{"en":"The phrase rejects an automatic conclusion.","zh":"這個片語否定自動得出的結論。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":5},{"front":"an end to","meaning":"……的終結","examples":[{"en":"Rising material use need not mean an end to modern machinery.","zh":"材料使用上升不一定意味現代機械的終結。"},{"en":"An end to something means that it stops or no longer continues.","zh":"an end to 指某事停止或不再持續。"},{"en":"Better planning can bring an end to long queues at the clinic.","zh":"更好規劃可以結束診所長隊。"},{"en":"If fuel becomes expensive, it does not necessarily mean an end to transport.","zh":"如果燃料變貴，不一定意味交通的終結。"},{"en":"The phrase describes stopping or disappearance.","zh":"這個片語描述停止或消失。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":6},{"front":"the machine age","meaning":"機器時代","examples":[{"en":"The writer argues that the machine age does not have to end.","zh":"作者認為機器時代不必終結。"},{"en":"The machine age means a period of society strongly shaped by machines and technology.","zh":"the machine age 指社會深受機器和科技塑造的時代。"},{"en":"Washing machines, cars, lifts, and computers are everyday signs of the machine age.","zh":"洗衣機、汽車、升降機和電腦都是機器時代的日常標誌。"},{"en":"If energy systems improve, the machine age may continue with less environmental harm.","zh":"如果能源系統改善，機器時代可以在較少環境傷害下繼續。"},{"en":"The phrase refers to modern technological civilisation.","zh":"這個片語指現代科技文明。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":6},{"front":"rather than being thrown away","meaning":"而不是被丟棄","examples":[{"en":"Rather than being thrown away, materials from old machinery can be recycled.","zh":"舊機械中的材料可以被回收再用，而不是被丟棄。"},{"en":"Rather than being thrown away means instead of being discarded as rubbish.","zh":"rather than being thrown away 指不是作為垃圾丟棄。"},{"en":"Rather than being thrown away, old school desks can be repaired and reused.","zh":"舊課桌可以被維修和重用，而不是被丟棄。"},{"en":"If materials are recycled rather than thrown away, fewer new raw materials are needed.","zh":"如果材料被回收而不是被丟棄，就需要較少新原材料。"},{"en":"The phrase creates a contrast between waste and reuse.","zh":"這個片語在浪費和重用之間形成對比。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":6},{"front":"old machinery","meaning":"舊機械","examples":[{"en":"Materials from old machinery can be recycled by manufacturers.","zh":"舊機械中的材料可由製造商回收再用。"},{"en":"Old machinery means machines that are no longer new, efficient, or in regular use.","zh":"old machinery 指不再新、不再高效或不再經常使用的機器。"},{"en":"A factory may sell old machinery when it buys newer equipment.","zh":"工廠購買新設備時可能出售舊機械。"},{"en":"If old machinery is dismantled carefully, useful metal and parts can be recovered.","zh":"如果舊機械被仔細拆解，有用金屬和零件可以被回收。"},{"en":"The phrase refers to machines near the end of their working life.","zh":"這個片語指接近使用壽命末段的機器。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":6},{"front":"be recycled by","meaning":"被……回收再用","examples":[{"en":"Materials from old machinery can be recycled by manufacturers.","zh":"舊機械中的材料可被製造商回收再用。"},{"en":"Be recycled by means be processed and reused by a particular person or organisation.","zh":"be recycled by 指由某人或機構處理並重新使用。"},{"en":"Plastic bottles can be recycled by local waste centres.","zh":"膠樽可被本地廢物處理中心回收再用。"},{"en":"If metals are recycled by manufacturers, production may need less mining.","zh":"如果金屬被製造商回收再用，生產可能需要較少採礦。"},{"en":"The phrase identifies who performs the recycling.","zh":"這個片語指出由誰進行回收。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":6},{"front":"manufacturers","meaning":"製造商","examples":[{"en":"Manufacturers can recycle materials from old machinery.","zh":"製造商可以回收舊機械中的材料。"},{"en":"Manufacturers are companies or people that make goods in factories or workshops.","zh":"manufacturers 是在工廠或工場製造貨品的公司或人。"},{"en":"Manufacturers of phones need metals, glass, plastic, and skilled workers.","zh":"手機製造商需要金屬、玻璃、塑膠和熟練工人。"},{"en":"If manufacturers design products for recycling, waste can be reduced.","zh":"如果製造商設計產品時方便回收，浪費可以減少。"},{"en":"The word refers to producers, not ordinary shoppers.","zh":"這個詞指生產者，而不是普通購物者。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":6},{"front":"long before","meaning":"早在……之前","examples":[{"en":"Long before fossil fuels are exhausted, rising prices may change industrial behaviour.","zh":"早在化石燃料被耗盡之前，價格上升可能改變工業行為。"},{"en":"Long before means much earlier than a later event.","zh":"long before 指遠早於某個後來事件。"},{"en":"Long before exams begin, good students start reviewing their notes.","zh":"早在考試開始之前，好學生已開始溫習筆記。"},{"en":"If fuel prices rise long before supplies end, society may change behaviour early.","zh":"如果燃料價格早在供應耗盡之前上升，社會可能早早改變行為。"},{"en":"The phrase emphasises that something happens well in advance.","zh":"這個片語強調某事很早發生。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":6},{"front":"fossil fuels","meaning":"化石燃料","examples":[{"en":"Fossil fuels may become more expensive before they are exhausted.","zh":"化石燃料可能在被耗盡之前變得更昂貴。"},{"en":"Fossil fuels are fuels such as coal, oil, and natural gas formed from ancient organic matter.","zh":"fossil fuels 是煤、石油和天然氣等由古代有機物形成的燃料。"},{"en":"Cars, power stations, and factories often depend on fossil fuels.","zh":"汽車、發電廠和工廠常依賴化石燃料。"},{"en":"If fossil fuels become scarce or costly, societies may shift to alternative energy.","zh":"如果化石燃料變得稀少或昂貴，社會可能轉向替代能源。"},{"en":"The phrase refers to non-renewable energy sources.","zh":"這個片語指不可再生能源。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":6},{"front":"be exhausted","meaning":"被耗盡","examples":[{"en":"Fossil fuels may eventually be exhausted.","zh":"化石燃料最終可能被耗盡。"},{"en":"Be exhausted means be completely used up.","zh":"be exhausted 指被完全用完。"},{"en":"The printer paper was exhausted before the final exam worksheets were copied.","zh":"在最後考試工作紙影印前，打印紙已被耗盡。"},{"en":"If fuel reserves are exhausted, society must rely on other energy sources.","zh":"如果燃料儲備被耗盡，社會就必須依賴其他能源。"},{"en":"The phrase suggests no usable supply remains.","zh":"這個片語暗示沒有可用供應剩下。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":6},{"front":"rising prices","meaning":"價格上升","examples":[{"en":"Rising prices may push society to use energy more efficiently.","zh":"價格上升可能推動社會更有效使用能源。"},{"en":"Rising prices are prices that are increasing over time.","zh":"rising prices 是隨時間增加的價格。"},{"en":"Rising prices in supermarkets can make families plan meals more carefully.","zh":"超市價格上升可以令家庭更仔細計劃膳食。"},{"en":"If fuel prices rise, businesses may invest in energy-saving machines.","zh":"如果燃料價格上升，企業可能投資節能機器。"},{"en":"The phrase often signals economic pressure.","zh":"這個片語常標示經濟壓力。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":6},{"front":"compel someone to","meaning":"迫使某人去……","examples":[{"en":"Rising fuel prices may compel industrial society to find alternatives.","zh":"燃料價格上升可能迫使工業社會尋找替代方案。"},{"en":"Compel someone to means force or strongly pressure someone to do something.","zh":"compel someone to 指迫使或強烈推動某人做某事。"},{"en":"A serious illness may compel a person to change their diet.","zh":"嚴重疾病可能迫使一個人改變飲食。"},{"en":"If costs rise sharply, they can compel companies to redesign products.","zh":"如果成本急升，它們可以迫使公司重新設計產品。"},{"en":"The phrase suggests strong pressure, not a gentle suggestion.","zh":"這個片語暗示強烈壓力，而不是溫和建議。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":7},{"front":"industrial society","meaning":"工業社會","examples":[{"en":"Industrial society may become more energy efficient.","zh":"工業社會可能變得更能源效益高。"},{"en":"Industrial society is a society whose economy depends heavily on factories, machines, and large-scale production.","zh":"industrial society 是經濟高度依賴工廠、機器和大規模生產的社會。"},{"en":"Industrial society needs transport, energy, skilled workers, and raw materials.","zh":"工業社會需要交通、能源、熟練工人和原材料。"},{"en":"If industrial society becomes energy efficient, it may reduce waste while keeping production high.","zh":"如果工業社會變得能源效益高，就可能在保持高產量下減少浪費。"},{"en":"The phrase describes a machine-based modern economy.","zh":"這個片語描述以機器為基礎的現代經濟。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":7},{"front":"energy efficient","meaning":"能源效益高的","examples":[{"en":"Rising prices may make industrial society more energy efficient.","zh":"價格上升可能使工業社會更能源效益高。"},{"en":"Energy efficient means using less energy to do the same job.","zh":"energy efficient 指用較少能源完成相同工作。"},{"en":"An energy-efficient fridge keeps food cold while using less electricity.","zh":"能源效益高的雪櫃能保持食物冷凍，同時用較少電。"},{"en":"If homes become energy efficient, families can lower bills and reduce emissions.","zh":"如果住房變得能源效益高，家庭可以減少帳單和排放。"},{"en":"The phrase describes reduced energy waste.","zh":"這個片語描述減少能源浪費。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":7},{"front":"alternative energy sources","meaning":"替代能源","examples":[{"en":"Industrial society may find alternative energy sources.","zh":"工業社會可能找到替代能源。"},{"en":"Alternative energy sources are energy supplies used instead of traditional fossil fuels.","zh":"alternative energy sources 是用來取代傳統化石燃料的能源供應。"},{"en":"Solar panels, wind turbines, and geothermal systems are alternative energy sources.","zh":"太陽能板、風力渦輪和地熱系統都是替代能源。"},{"en":"If fossil fuel prices rise, alternative energy sources become more attractive.","zh":"如果化石燃料價格上升，替代能源就變得更有吸引力。"},{"en":"The phrase points to replacement energy options.","zh":"這個片語指替代性能源選項。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":7},{"front":"sufficient for","meaning":"足以應付……","examples":[{"en":"Alternative energy sources may be sufficient for an advanced civilisation.","zh":"替代能源可能足以應付先進文明。"},{"en":"Sufficient for means enough to meet a need or purpose.","zh":"sufficient for 指足夠滿足某需要或目的。"},{"en":"One hour may be sufficient for a short grammar lesson.","zh":"一小時可能足以應付一堂短文法課。"},{"en":"If solar energy becomes cheap and reliable, it may be sufficient for many homes.","zh":"如果太陽能變得便宜可靠，它可能足以應付許多家庭需要。"},{"en":"The phrase focuses on adequacy, not excess.","zh":"這個片語集中於足夠，而不是過剩。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":7},{"front":"the demands of","meaning":"……的需求","examples":[{"en":"Future energy sources must meet the demands of technological civilisation.","zh":"未來能源必須滿足科技文明的需求。"},{"en":"The demands of something are the needs, pressures, or requirements it creates.","zh":"the demands of 指某事造成的需要、壓力或要求。"},{"en":"Parents often struggle with the demands of work and childcare.","zh":"父母常在工作和育兒的需求之間感到吃力。"},{"en":"If energy sources cannot meet the demands of industry, production may slow down.","zh":"如果能源不能滿足工業需求，生產可能放慢。"},{"en":"The phrase identifies what must be satisfied.","zh":"這個片語指出必須被滿足的內容。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":7},{"front":"advanced technological civilisation","meaning":"先進科技文明","examples":[{"en":"The writer imagines an advanced technological civilisation with alternative energy.","zh":"作者想像一個有替代能源的先進科技文明。"},{"en":"An advanced technological civilisation is a society with highly developed science, machines, transport, and energy systems.","zh":"advanced technological civilisation 是科學、機器、交通和能源系統高度發展的社會。"},{"en":"A city with automatic transport and clean power may seem part of an advanced technological civilisation.","zh":"有自動交通和清潔能源的城市，可能看似屬於先進科技文明。"},{"en":"If advanced technological civilisation uses dirty energy, environmental damage may still grow.","zh":"如果先進科技文明使用骯髒能源，環境破壞仍可能增加。"},{"en":"The phrase describes a highly developed future society.","zh":"這個片語描述高度發展的未來社會。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":7},{"front":"nuclear fission","meaning":"核裂變","examples":[{"en":"Nuclear fission is listed as a possible alternative energy source.","zh":"核裂變被列為可能的替代能源。"},{"en":"Nuclear fission is the process of splitting atomic nuclei to release energy.","zh":"nuclear fission 是分裂原子核以釋放能量的過程。"},{"en":"A nuclear power station may use nuclear fission to produce electricity.","zh":"核電站可能使用核裂變來發電。"},{"en":"If nuclear fission is used safely, it can generate large amounts of power.","zh":"如果核裂變被安全使用，它可以產生大量電力。"},{"en":"The phrase refers to one form of nuclear energy production.","zh":"這個片語指一種核能生產方式。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":7},{"front":"nuclear fusion","meaning":"核聚變","examples":[{"en":"Nuclear fusion may become a future energy source.","zh":"核聚變可能成為未來能源。"},{"en":"Nuclear fusion is the process of joining atomic nuclei to release energy.","zh":"nuclear fusion 是結合原子核以釋放能量的過程。"},{"en":"The sun produces energy through nuclear fusion.","zh":"太陽透過核聚變產生能量。"},{"en":"If nuclear fusion becomes practical, it could provide a powerful low-carbon energy source.","zh":"如果核聚變變得實用，它可以提供強大的低碳能源。"},{"en":"The phrase refers to a difficult but promising energy technology.","zh":"這個片語指一種困難但有前景的能源技術。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":7},{"front":"solar energy","meaning":"太陽能","examples":[{"en":"Solar energy is one possible alternative to fossil fuels.","zh":"太陽能是化石燃料的一種可能替代品。"},{"en":"Solar energy is energy from sunlight that can be used for heat or electricity.","zh":"solar energy 是來自陽光、可用於供熱或發電的能源。"},{"en":"A school may install solar panels to use solar energy during the day.","zh":"學校可能安裝太陽能板，在日間使用太陽能。"},{"en":"If solar energy becomes cheaper, households may rely less on fossil fuels.","zh":"如果太陽能變得更便宜，家庭可能較少依賴化石燃料。"},{"en":"The phrase refers to renewable energy from the sun.","zh":"這個片語指來自太陽的可再生能源。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":7},{"front":"chemical photosynthesis","meaning":"化學光合作用","examples":[{"en":"Chemical photosynthesis is mentioned as a possible energy source.","zh":"化學光合作用被提及為可能的能源。"},{"en":"Chemical photosynthesis refers to using chemical processes inspired by plants to capture and store energy.","zh":"chemical photosynthesis 指使用受植物啟發的化學過程來捕捉和儲存能源。"},{"en":"Scientists may study chemical photosynthesis to turn sunlight into useful fuels.","zh":"科學家可能研究化學光合作用，把陽光轉化為有用燃料。"},{"en":"If chemical photosynthesis becomes efficient, it could help replace some fossil fuels.","zh":"如果化學光合作用變得高效，它可能幫助取代部分化石燃料。"},{"en":"The phrase describes a scientific approach to artificial energy production.","zh":"這個片語描述人工能源生產的科學方法。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":8},{"front":"geothermal energy","meaning":"地熱能","examples":[{"en":"Geothermal energy may help meet future energy needs.","zh":"地熱能可能幫助滿足未來能源需求。"},{"en":"Geothermal energy is heat energy from inside the Earth.","zh":"geothermal energy 是來自地球內部的熱能。"},{"en":"Some buildings use geothermal energy for heating and cooling.","zh":"有些建築使用地熱能供暖和製冷。"},{"en":"If geothermal systems are available locally, they can provide steady energy day and night.","zh":"如果本地可使用地熱系統，它們可以日夜提供穩定能源。"},{"en":"The phrase refers to renewable energy from Earth’s internal heat.","zh":"這個片語指來自地球內部熱力的可再生能源。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":8},{"front":"biomass","meaning":"生物質能","examples":[{"en":"Biomass is listed among possible alternative energy sources.","zh":"生物質能被列入可能的替代能源之中。"},{"en":"Biomass is organic material from plants or animals that can be used for energy.","zh":"biomass 是可用於能源的植物或動物有機物質。"},{"en":"Wood waste, crop remains, and food scraps can be forms of biomass.","zh":"木材廢料、作物殘留物和食物廚餘都可以是生物質。"},{"en":"If biomass is managed badly, it may still cause pollution or land pressure.","zh":"如果生物質管理不善，它仍可能造成污染或土地壓力。"},{"en":"The phrase refers to energy material from living or once-living sources.","zh":"這個片語指來自生物或曾經有生命來源的能源材料。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":8},{"front":"yet unknown source of energy","meaning":"尚未知曉的能源","examples":[{"en":"Future society may rely on some yet unknown source of energy.","zh":"未來社會可能依賴某種尚未知曉的能源。"},{"en":"A yet unknown source of energy is an energy supply that has not been discovered or developed yet.","zh":"yet unknown source of energy 指尚未被發現或發展出來的能源供應。"},{"en":"Past generations could not imagine many energy technologies that schools now teach.","zh":"過去世代無法想像許多今日學校教授的能源科技。"},{"en":"If a yet unknown source of energy appears, it may change future civilisation dramatically.","zh":"如果一種尚未知曉的能源出現，它可能大幅改變未來文明。"},{"en":"The phrase leaves room for future scientific discovery.","zh":"這個片語為未來科學發現留下空間。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":8},{"front":"growth of cities and suburbs","meaning":"城市和郊區的擴張","examples":[{"en":"The growth of cities and suburbs is often seen as an environmental threat.","zh":"城市和郊區的擴張常被視為環境威脅。"},{"en":"Growth of cities and suburbs means expansion of urban areas and nearby residential districts.","zh":"growth of cities and suburbs 指城市地區和附近住宅區的擴展。"},{"en":"The growth of cities and suburbs can be seen when farms become housing estates.","zh":"當農田變成屋苑時，就可看見城市和郊區的擴張。"},{"en":"If cities and suburbs grow without planning, traffic and land use may increase.","zh":"如果城市和郊區在缺乏規劃下擴張，交通和土地使用可能增加。"},{"en":"The phrase describes urban expansion.","zh":"這個片語描述城市擴展。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":8},{"front":"be seen as","meaning":"被視為","examples":[{"en":"Urban growth is often seen as a threat to the environment.","zh":"城市增長常被視為對環境的威脅。"},{"en":"Be seen as means be regarded or understood in a particular way.","zh":"be seen as 指被認為或被理解為某種情況。"},{"en":"Extra homework may be seen as helpful by teachers but stressful by students.","zh":"額外功課可能被老師視為有幫助，但被學生視為有壓力。"},{"en":"If farmland expansion is seen as dangerous, policy may focus on food productivity.","zh":"如果農田擴張被視為危險，政策可能集中於糧食生產力。"},{"en":"The phrase shows perception or judgement.","zh":"這個片語顯示看法或判斷。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":8},{"front":"a threat to","meaning":"對……的威脅","examples":[{"en":"City growth is often seen as a threat to the environment.","zh":"城市增長常被視為對環境的威脅。"},{"en":"A threat to something is a danger that may harm it.","zh":"a threat to 指可能傷害某事物的危險。"},{"en":"Air pollution is a threat to children’s health.","zh":"空氣污染是對兒童健康的威脅。"},{"en":"If agriculture destroys forests, it becomes a threat to wildlife.","zh":"如果農業摧毀森林，它就成為對野生動物的威脅。"},{"en":"The phrase identifies what may be damaged.","zh":"這個片語指出可能受損的對象。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":8},{"front":"increasing amount of land","meaning":"不斷增加的土地面積","examples":[{"en":"Agriculture consumes an increasing amount of land.","zh":"農業佔用不斷增加的土地面積。"},{"en":"Increasing amount of land means more and more land over time.","zh":"increasing amount of land 指隨時間越來越多的土地。"},{"en":"A growing school may need an increasing amount of land for classrooms and sports areas.","zh":"成長中的學校可能需要不斷增加的土地面積作課室和運動場。"},{"en":"If farming uses an increasing amount of land, wild habitats may shrink.","zh":"如果農業使用不斷增加的土地面積，野生棲息地可能縮小。"},{"en":"The phrase highlights land use that keeps rising.","zh":"這個片語強調持續上升的土地使用。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":8},{"front":"consumed by agriculture","meaning":"被農業佔用","examples":[{"en":"The land consumed by agriculture is a serious environmental problem.","zh":"被農業佔用的土地是一個嚴重環境問題。"},{"en":"Consumed by agriculture means taken up or used for farming.","zh":"consumed by agriculture 指被農業佔據或使用。"},{"en":"Land consumed by housing cannot also be used as public parkland.","zh":"被住房佔用的土地不能同時用作公共公園。"},{"en":"If too much land is consumed by agriculture, forests and wild areas may disappear.","zh":"如果太多土地被農業佔用，森林和野生地區可能消失。"},{"en":"The phrase presents farming as a major user of land.","zh":"這個片語把農業呈現為主要土地使用者。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":8},{"front":"far greater danger than","meaning":"比……大得多的危險","examples":[{"en":"Agricultural land use is a far greater danger than urban sprawl.","zh":"農業土地使用是比城市蔓延大得多的危險。"},{"en":"Far greater danger than means much more harmful or risky than something else.","zh":"far greater danger than 指比另一事物有害或危險得多。"},{"en":"For a tired driver, sleepiness may be a far greater danger than a short delay.","zh":"對疲倦司機而言，睡意可能是比短暫延誤大得多的危險。"},{"en":"If farmland expansion destroys more habitat than suburbs, it is a far greater danger.","zh":"如果農地擴張比郊區發展摧毀更多棲息地，它就是大得多的危險。"},{"en":"The phrase makes a strong comparison of risk.","zh":"這個片語作出強烈風險比較。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":8},{"front":"urban sprawl","meaning":"城市蔓延","examples":[{"en":"Urban sprawl is less dangerous than the spread of farmland, according to the writer.","zh":"根據作者，城市蔓延比農田擴張較不危險。"},{"en":"Urban sprawl is the spread of low-density urban development into surrounding land.","zh":"urban sprawl 是低密度城市發展向周邊土地擴散。"},{"en":"Urban sprawl can create long commutes and dependence on cars.","zh":"城市蔓延可以造成長途通勤和依賴私家車。"},{"en":"If urban sprawl is uncontrolled, public transport becomes harder to provide.","zh":"如果城市蔓延不受控制，公共交通就更難提供。"},{"en":"The phrase describes outward city growth.","zh":"這個片語描述城市向外增長。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":9},{"front":"stop the growth of farms","meaning":"阻止農田擴張","examples":[{"en":"Stopping the growth of farms may help preserve wild areas.","zh":"阻止農田擴張可能有助保護野生地區。"},{"en":"Stop the growth of farms means prevent farmland from expanding into more land.","zh":"stop the growth of farms 指防止農地擴展到更多土地。"},{"en":"A government may stop the growth of farms near a wetland to protect birds.","zh":"政府可能阻止濕地附近農田擴張，以保護鳥類。"},{"en":"If farm growth stops and productivity improves, more land can remain wild.","zh":"如果農田擴張停止而生產力改善，更多土地可以保持野生。"},{"en":"The phrase focuses on limiting agricultural expansion.","zh":"這個片語集中於限制農業擴張。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":9},{"front":"preserve wild areas","meaning":"保護野生地區","examples":[{"en":"Reducing farmland could help preserve many wild areas.","zh":"減少農地可以幫助保護許多野生地區。"},{"en":"Preserve wild areas means protect natural land from being developed or damaged.","zh":"preserve wild areas 指保護自然土地免受發展或破壞。"},{"en":"Communities can preserve wild areas by limiting construction near forests.","zh":"社區可以透過限制森林附近建設來保護野生地區。"},{"en":"If farming needs less land, society may preserve more wild areas for animals and plants.","zh":"如果農業需要較少土地，社會可保護更多野生地區給動植物。"},{"en":"The phrase connects land protection with biodiversity.","zh":"這個片語把土地保護與生物多樣性連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":9},{"front":"remaining wild areas","meaning":"剩餘的野生地區","examples":[{"en":"The world still has remaining wild areas that need protection.","zh":"世界仍有需要保護的剩餘野生地區。"},{"en":"Remaining wild areas are natural places that have not yet been converted into farms, roads, or cities.","zh":"remaining wild areas 是尚未變成農場、道路或城市的自然地方。"},{"en":"A country may map remaining wild areas before deciding where development is allowed.","zh":"一個國家可能先繪製剩餘野生地區地圖，再決定哪裡可發展。"},{"en":"If remaining wild areas disappear, many species may lose their last habitats.","zh":"如果剩餘野生地區消失，許多物種可能失去最後棲息地。"},{"en":"The phrase emphasises what is left and still worth protecting.","zh":"這個片語強調仍然剩下且值得保護的東西。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":9},{"front":"dramatic downsizing of farmland","meaning":"大幅縮減農地","examples":[{"en":"The writer asks whether a dramatic downsizing of farmland is possible.","zh":"作者問是否可能大幅縮減農地。"},{"en":"Dramatic downsizing of farmland means a large reduction in the amount of land used for farming.","zh":"dramatic downsizing of farmland 指大幅減少用於農業的土地面積。"},{"en":"A dramatic downsizing of office space may happen if many workers stay remote.","zh":"如果很多員工維持遙距工作，辦公空間可能大幅縮減。"},{"en":"If food productivity rises sharply, dramatic downsizing of farmland may become possible.","zh":"如果糧食生產力急升，大幅縮減農地可能變得可行。"},{"en":"The phrase suggests a major and noticeable reduction.","zh":"這個片語暗示重大而明顯的縮減。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":9},{"front":"thanks to","meaning":"多虧；由於","examples":[{"en":"Thanks to agricultural productivity, reforestation has been under way.","zh":"多虧農業生產力，重新造林正在進行。"},{"en":"Thanks to means because of something positive or helpful.","zh":"thanks to 指由於某件正面或有幫助的事情。"},{"en":"Thanks to better buses, students arrive at school more easily.","zh":"多虧更好的巴士，學生更容易到校。"},{"en":"If crop yields improve thanks to new methods, less land may be needed.","zh":"如果作物產量由於新方法而提高，所需土地可能減少。"},{"en":"The phrase gives credit to a helpful cause.","zh":"這個片語把功勞歸於有幫助的原因。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":9},{"front":"agricultural productivity","meaning":"農業生產力","examples":[{"en":"Agricultural productivity can reduce the amount of land needed for food.","zh":"農業生產力可以減少生產食物所需土地面積。"},{"en":"Agricultural productivity means how much food or crop output is produced from farming resources.","zh":"agricultural productivity 指農業資源能產出多少食物或作物。"},{"en":"Better seeds and irrigation can increase agricultural productivity on a farm.","zh":"更好的種子和灌溉可以提高農場農業生產力。"},{"en":"If agricultural productivity rises, farmers can produce more food on less land.","zh":"如果農業生產力上升，農民可在較少土地上生產更多食物。"},{"en":"The phrase measures farming efficiency.","zh":"這個片語衡量農業效率。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":9},{"front":"reforestation","meaning":"重新造林","examples":[{"en":"Reforestation has been taking place in industrial countries.","zh":"重新造林一直在工業化國家發生。"},{"en":"Reforestation is the process of planting trees or allowing forests to return.","zh":"reforestation 是種樹或讓森林恢復的過程。"},{"en":"A school may join a reforestation project by planting trees on a hillside.","zh":"學校可能透過在山坡種樹參與重新造林項目。"},{"en":"If farmland is no longer needed, reforestation can restore habitats and store carbon.","zh":"如果農地不再需要，重新造林可以恢復棲息地並儲存碳。"},{"en":"The phrase describes the return of forest cover.","zh":"這個片語描述森林覆蓋的回復。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":9},{"front":"rewilding","meaning":"重新野化","examples":[{"en":"Rewilding has been under way in industrial countries for generations.","zh":"重新野化在工業化國家已進行了數代。"},{"en":"Rewilding means allowing land to return to a more natural state with wildlife and native plants.","zh":"rewilding 指讓土地回復較自然狀態，重新有野生動物和本地植物。"},{"en":"A community may practise rewilding by turning an unused field into meadow and woodland.","zh":"社區可能把閒置田地變成草地和林地來實行重新野化。"},{"en":"If rewilding succeeds, animals and plants may return without heavy human control.","zh":"如果重新野化成功，動植物可能在較少人為控制下回歸。"},{"en":"The phrase focuses on restoring natural processes.","zh":"這個片語集中於恢復自然過程。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":9},{"front":"be under way","meaning":"正在進行","examples":[{"en":"Reforestation and rewilding have been under way for generations.","zh":"重新造林和重新野化已進行了數代。"},{"en":"Be under way means be already happening or in progress.","zh":"be under way 指已經發生或正在進行。"},{"en":"Repairs are under way, so the school hall is temporarily closed.","zh":"維修正在進行，所以學校禮堂暫時關閉。"},{"en":"If rewilding is under way, the land is already beginning to change.","zh":"如果重新野化正在進行，土地已開始改變。"},{"en":"The phrase describes an ongoing process.","zh":"這個片語描述持續中的過程。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":9},{"front":"industrial countries","meaning":"工業化國家","examples":[{"en":"Rewilding has been under way in industrial countries.","zh":"重新野化一直在工業化國家進行。"},{"en":"Industrial countries are countries with developed industries, infrastructure, and high levels of production.","zh":"industrial countries 指工業、基建和生產水平發達的國家。"},{"en":"Industrial countries often have advanced transport systems and large manufacturing sectors.","zh":"工業化國家通常有先進交通系統和大型製造業。"},{"en":"If industrial countries reduce farmland, they may create space for forests and parks.","zh":"如果工業化國家減少農地，它們可能創造森林和公園空間。"},{"en":"The phrase is close to developed countries, but emphasises industry.","zh":"這個片語接近發達國家，但強調工業。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":10},{"front":"for generations","meaning":"持續了數代","examples":[{"en":"Reforestation has continued for generations.","zh":"重新造林已持續了數代。"},{"en":"For generations means over many family age groups or long periods of time.","zh":"for generations 指跨越多個家庭世代或很長時間。"},{"en":"A small bakery may be run by the same family for generations.","zh":"一間小麵包店可能由同一家族經營數代。"},{"en":"If reforestation continues for generations, landscapes can change greatly.","zh":"如果重新造林持續數代，景觀可以大幅改變。"},{"en":"The phrase shows long-term continuity.","zh":"這個片語顯示長期延續。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":10},{"front":"set aside in parks","meaning":"撥作公園用地","examples":[{"en":"More land in the US has been set aside in parks since 1950.","zh":"自1950年以來，美國有更多土地被撥作公園用地。"},{"en":"Set aside in parks means reserved or protected as parkland rather than used for other development.","zh":"set aside in parks 指保留或保護為公園用地，而不是用於其他發展。"},{"en":"A city may set aside land in parks so children have safe outdoor space.","zh":"城市可能撥出土地作公園，讓孩子有安全戶外空間。"},{"en":"If land is set aside in parks, it can protect nature and provide recreation.","zh":"如果土地被撥作公園用地，它可以保護自然並提供休憩。"},{"en":"The phrase describes official reservation of land.","zh":"這個片語描述官方保留土地。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":10},{"front":"be occupied by","meaning":"被……佔用","examples":[{"en":"Less land has been occupied by urban and suburban growth.","zh":"較少土地被城市和郊區增長佔用。"},{"en":"Be occupied by means be taken up or used by something.","zh":"be occupied by 指被某事物佔據或使用。"},{"en":"The classroom was occupied by another group, so we studied in the library.","zh":"課室被另一組人佔用，所以我們在圖書館溫習。"},{"en":"If land is occupied by housing, it cannot easily return to forest.","zh":"如果土地被住房佔用，就不容易回復為森林。"},{"en":"The phrase identifies what is using a space.","zh":"這個片語指出甚麼正在使用空間。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":10},{"front":"urban and suburban growth","meaning":"城市和郊區增長","examples":[{"en":"Urban and suburban growth has occupied less land than new parks.","zh":"城市和郊區增長佔用的土地少於新公園。"},{"en":"Urban and suburban growth means expansion of cities and their surrounding residential areas.","zh":"urban and suburban growth 指城市及其周邊住宅區擴張。"},{"en":"Urban and suburban growth can increase demand for roads, schools, and shops.","zh":"城市和郊區增長可以增加對道路、學校和商店的需求。"},{"en":"If urban and suburban growth is compact, it may use less land than scattered housing.","zh":"如果城市和郊區增長較緊湊，它可能比分散住房使用較少土地。"},{"en":"The phrase describes expansion of built environments.","zh":"這個片語描述建成環境的擴張。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":10},{"front":"nineteenth century","meaning":"十九世紀","examples":[{"en":"Much nineteenth-century farmland is now forest again.","zh":"許多十九世紀的農地現在再次成為森林。"},{"en":"Nineteenth century means the years from 1801 to 1900.","zh":"nineteenth century 指1801年至1900年。"},{"en":"A nineteenth-century building may have high ceilings and old stone walls.","zh":"十九世紀建築可能有高天花和舊石牆。"},{"en":"If nineteenth-century farmland returns to forest, land use has changed over time.","zh":"如果十九世紀農地回復為森林，土地使用已隨時間改變。"},{"en":"The phrase identifies a historical period.","zh":"這個片語指出一個歷史時期。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":10},{"front":"taking something as the norm","meaning":"以……作為標準","examples":[{"en":"Taking the best Iowa maize growers as the norm gives an optimistic estimate.","zh":"以愛荷華州最好的粟米種植者作為標準，會得出樂觀估計。"},{"en":"Taking something as the norm means treating it as the standard for comparison.","zh":"taking something as the norm 指把某事物視為比較標準。"},{"en":"Taking top students as the norm may make average learners feel they are failing.","zh":"以尖子學生作為標準，可能令普通學習者覺得自己失敗。"},{"en":"If planners take the best farms as the norm, they may overestimate global productivity.","zh":"如果規劃者以最佳農場作為標準，可能高估全球生產力。"},{"en":"The phrase warns that the chosen standard affects the conclusion.","zh":"這個片語提醒所選標準會影響結論。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":10},{"front":"maize growers","meaning":"粟米種植者","examples":[{"en":"The best Iowa maize growers are used as a productivity benchmark.","zh":"愛荷華州最好的粟米種植者被用作生產力基準。"},{"en":"Maize growers are farmers who grow maize, also called corn.","zh":"maize growers 是種植粟米的農民。"},{"en":"Maize growers need good soil, water, seeds, machines, and market access.","zh":"粟米種植者需要良好土壤、水源、種子、機器和市場渠道。"},{"en":"If maize growers improve yields, less land may be needed for the same amount of food.","zh":"如果粟米種植者提高產量，同樣食物可能需要較少土地。"},{"en":"The phrase refers to crop farmers.","zh":"這個片語指作物農民。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":10},{"front":"world food productivity","meaning":"世界糧食生產力","examples":[{"en":"The calculation concerns world food productivity.","zh":"這項計算涉及世界糧食生產力。"},{"en":"World food productivity means how efficiently the world produces food from land, labour, and technology.","zh":"world food productivity 指世界利用土地、勞動和科技生產食物的效率。"},{"en":"Better farming methods can raise world food productivity without clearing more forests.","zh":"更好的農業方法可以在不開墾更多森林下提高世界糧食生產力。"},{"en":"If world food productivity improves, fewer people may face hunger.","zh":"如果世界糧食生產力改善，面對飢餓的人可能減少。"},{"en":"The phrase looks at food production on a global scale.","zh":"這個片語從全球尺度看食物生產。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":10},{"front":"it has been calculated that","meaning":"據計算","examples":[{"en":"It has been calculated that less than a tenth of present cropland could feed 10 billion people.","zh":"據計算，少於現有耕地十分之一便可養活100億人。"},{"en":"It has been calculated that means someone has worked out a figure using data or assumptions.","zh":"it has been calculated that 指有人根據數據或假設計算出某數字。"},{"en":"It has been calculated that a new bus route could save students twenty minutes each day.","zh":"據計算，新巴士路線每天可為學生節省二十分鐘。"},{"en":"If it has been calculated that less land is needed, the assumptions behind the calculation matter.","zh":"如果據計算需要較少土地，計算背後的假設很重要。"},{"en":"The phrase introduces a numerical estimate.","zh":"這個片語引出數字估計。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":10},{"front":"less than a tenth of","meaning":"少於十分之一的……","examples":[{"en":"Less than a tenth of present cropland could support 10 billion people.","zh":"少於現有耕地十分之一便可支持100億人口。"},{"en":"Less than a tenth of means under 10 percent of something.","zh":"less than a tenth of 指少於某物的10%。"},{"en":"Less than a tenth of the class arrived late after the timetable changed.","zh":"時間表改變後，少於全班十分之一學生遲到。"},{"en":"If less than a tenth of land could feed everyone, agricultural efficiency would be extremely high.","zh":"如果少於十分之一土地便能養活所有人，農業效率會極高。"},{"en":"The phrase describes a very small fraction.","zh":"這個片語描述很小的比例。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":11},{"front":"present cropland","meaning":"現有耕地","examples":[{"en":"Present cropland could be used much more productively.","zh":"現有耕地可以被更高效地使用。"},{"en":"Present cropland means land currently used for growing crops.","zh":"present cropland 指目前用於種植作物的土地。"},{"en":"Farmers may improve present cropland by using better irrigation and soil care.","zh":"農民可以透過更好灌溉和土壤護理改善現有耕地。"},{"en":"If present cropland becomes more productive, less new land needs to be cleared.","zh":"如果現有耕地變得更高產，就較少需要開墾新土地。"},{"en":"The phrase refers to existing farmland, not future farmland.","zh":"這個片語指現有農地，而不是未來農地。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":11},{"front":"support a population of","meaning":"支持……人口","examples":[{"en":"Less than a tenth of present cropland could support a population of 10 billion.","zh":"少於現有耕地十分之一便可支持100億人口。"},{"en":"Support a population of means provide enough food, resources, or services for a number of people.","zh":"support a population of 指為某數量人口提供足夠食物、資源或服務。"},{"en":"A town must have enough water to support a population of 50,000.","zh":"一個城鎮必須有足夠食水，才能支持五萬人口。"},{"en":"If farmland can support a larger population, less natural land may be converted to agriculture.","zh":"如果農地能支持更大人口，較少自然土地需要轉為農業用地。"},{"en":"The phrase connects resources with the number of people they can sustain.","zh":"這個片語把資源與其可維持的人口數量連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":11},{"front":"a vision of a utopia","meaning":"一種烏托邦願景","examples":[{"en":"Nigel Calder described a vision of a utopia that was both technological and environmentalist.","zh":"Nigel Calder 描述了一種既科技化又環保主義的烏托邦願景。"},{"en":"A vision of a utopia is an imagined ideal society where problems have been solved.","zh":"a vision of a utopia 指想像中的理想社會，其中問題已被解決。"},{"en":"A student may write a vision of a utopia with clean transport, fair schools, and safe housing.","zh":"學生可能寫一種烏托邦願景，包括清潔交通、公平學校和安全住房。"},{"en":"If a vision of a utopia ignores real problems, it may sound attractive but unrealistic.","zh":"如果烏托邦願景忽視現實問題，它可能吸引但不切實際。"},{"en":"The phrase describes an ideal future picture.","zh":"這個片語描述理想未來圖像。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":11},{"front":"at once high-tech and environmentalist","meaning":"既高科技又環保主義的","examples":[{"en":"The vision was at once high-tech and environmentalist.","zh":"這個願景既高科技又環保主義。"},{"en":"At once high-tech and environmentalist means both technologically advanced and protective of the environment.","zh":"at once high-tech and environmentalist 指同時科技先進並保護環境。"},{"en":"A city with solar buildings and electric buses can be at once high-tech and environmentalist.","zh":"擁有太陽能建築和電動巴士的城市可以既高科技又環保。"},{"en":"If a food system uses laboratories to reduce farmland, it may be both high-tech and environmentalist.","zh":"如果食物系統利用實驗室減少農地，它可能既高科技又環保。"},{"en":"The phrase combines two qualities that some people assume are opposites.","zh":"這個片語結合兩種有些人以為相反的特質。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":11},{"front":"nourishing but unpalatable","meaning":"有營養但不可口的","examples":[{"en":"The proposed primary food would be nourishing but unpalatable.","zh":"提議中的基本食物會有營養但不可口。"},{"en":"Nourishing but unpalatable means healthy or nutritious but unpleasant to eat.","zh":"nourishing but unpalatable 指健康或有營養，但吃起來不愉快。"},{"en":"A bitter medicine-like drink may be nourishing but unpalatable.","zh":"像苦藥一樣的飲品可能有營養但不可口。"},{"en":"If food is nourishing but unpalatable, people may give it to animals rather than eat it directly.","zh":"如果食物有營養但不可口，人們可能把它餵給動物而不是直接食用。"},{"en":"The phrase contrasts nutritional value with taste.","zh":"這個片語把營養價值與味道作對比。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":11},{"front":"primary food","meaning":"基本食物","examples":[{"en":"Industrial techniques could produce primary food for animals.","zh":"工業技術可以為動物生產基本食物。"},{"en":"Primary food means basic food used as the main source of nutrition in a system.","zh":"primary food 指一個系統中作為主要營養來源的基本食物。"},{"en":"Rice is a primary food for many families in Asia.","zh":"米飯是亞洲許多家庭的基本食物。"},{"en":"If primary food can be produced efficiently, pressure on farmland may fall.","zh":"如果基本食物能高效生產，農地壓力可能下降。"},{"en":"The phrase refers to basic nourishment, not luxury food.","zh":"這個片語指基本營養，而不是奢侈食物。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":11},{"front":"produced by industrial techniques","meaning":"由工業技術生產","examples":[{"en":"Primary food could be produced by industrial techniques.","zh":"基本食物可以由工業技術生產。"},{"en":"Produced by industrial techniques means made using factory methods, machines, or controlled processes.","zh":"produced by industrial techniques 指使用工廠方法、機器或受控過程製造。"},{"en":"Bread can be produced by industrial techniques in large bakeries.","zh":"麵包可以在大型麵包廠由工業技術生產。"},{"en":"If food is produced by industrial techniques, it may require less farmland but more technology.","zh":"如果食物由工業技術生產，它可能需要較少農地但更多科技。"},{"en":"The phrase highlights method of production.","zh":"這個片語強調生產方法。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":11},{"front":"yeast from petroleum","meaning":"由石油製成的酵母","examples":[{"en":"Yeast from petroleum could be fed to animals.","zh":"由石油製成的酵母可以被餵給動物。"},{"en":"Yeast from petroleum means yeast produced using substances derived from oil.","zh":"yeast from petroleum 指使用來自石油的物質生產的酵母。"},{"en":"Scientists may study yeast from non-food sources to create protein more efficiently.","zh":"科學家可能研究來自非食物來源的酵母，以更有效製造蛋白質。"},{"en":"If yeast from petroleum feeds animals, people may still eat meat without growing as much feed crop.","zh":"如果由石油製成的酵母餵給動物，人們仍可吃肉而不需種植那麼多飼料作物。"},{"en":"The phrase describes an unusual industrial food source.","zh":"這個片語描述不尋常的工業食物來源。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":11},{"front":"be fed to animals","meaning":"被餵給動物","examples":[{"en":"Industrially produced food may be fed to animals.","zh":"工業生產的食物可能被餵給動物。"},{"en":"Be fed to animals means be given to animals as food.","zh":"be fed to animals 指被作為食物給動物食用。"},{"en":"Grain and vegetable scraps can be fed to animals on some farms.","zh":"在一些農場，穀物和蔬菜殘渣可以被餵給動物。"},{"en":"If industrial food is fed to animals, farmland used for feed crops may decrease.","zh":"如果工業食物被餵給動物，用於飼料作物的農地可能減少。"},{"en":"The phrase identifies the consumer of the food.","zh":"這個片語指出食物的食用者。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":11},{"front":"customary meat","meaning":"慣常食用的肉類","examples":[{"en":"People could continue to eat their customary meat.","zh":"人們可以繼續吃他們慣常食用的肉類。"},{"en":"Customary meat means the kinds of meat people are used to eating in their culture or daily life.","zh":"customary meat 指人們在文化或日常生活中習慣吃的肉類。"},{"en":"A family’s customary meat may be chicken, pork, beef, or fish.","zh":"一個家庭慣常食用的肉類可能是雞肉、豬肉、牛肉或魚。"},{"en":"If animal feed changes but the meat stays familiar, people may keep eating their customary meat.","zh":"如果動物飼料改變但肉類仍熟悉，人們可能繼續吃慣常肉類。"},{"en":"The phrase focuses on familiar dietary habits.","zh":"這個片語集中於熟悉的飲食習慣。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":12},{"front":"underdeveloped countries","meaning":"欠發達國家","examples":[{"en":"People in underdeveloped countries may gain better access to animal protein.","zh":"欠發達國家的人可能更容易獲得動物蛋白。"},{"en":"Underdeveloped countries are countries with lower income, weaker infrastructure, and fewer economic resources.","zh":"underdeveloped countries 指收入較低、基建較弱、經濟資源較少的國家。"},{"en":"Underdeveloped countries may struggle to provide clean water, schools, and healthcare for everyone.","zh":"欠發達國家可能難以為所有人提供清潔食水、學校和醫療。"},{"en":"If food technology becomes cheaper, underdeveloped countries may improve nutrition more quickly.","zh":"如果食物科技變得更便宜，欠發達國家可能更快改善營養。"},{"en":"The phrase is often used in economic development discussions.","zh":"這個片語常用於經濟發展討論。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":12},{"front":"adequate supplies of","meaning":"足夠供應","examples":[{"en":"Underdeveloped countries could have adequate supplies of animal protein.","zh":"欠發達國家可以有足夠的動物蛋白供應。"},{"en":"Adequate supplies of means enough amounts of something to meet people’s needs.","zh":"adequate supplies of 指有足夠數量的某物來滿足人們需要。"},{"en":"A hospital needs adequate supplies of masks, medicine, and clean water.","zh":"醫院需要足夠供應口罩、藥物和清潔食水。"},{"en":"If communities have adequate supplies of protein, children may grow more healthily.","zh":"如果社區有足夠蛋白質供應，孩子可能更健康成長。"},{"en":"The phrase means sufficient, not unlimited.","zh":"這個片語指足夠，而不是無限。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":12},{"front":"animal protein","meaning":"動物蛋白","examples":[{"en":"Industrial food production could increase access to animal protein.","zh":"工業食物生產可以增加獲得動物蛋白的機會。"},{"en":"Animal protein is protein that comes from animal sources such as meat, eggs, milk, or fish.","zh":"animal protein 是來自肉、蛋、奶或魚等動物來源的蛋白質。"},{"en":"A balanced diet may include animal protein or plant-based alternatives.","zh":"均衡飲食可包括動物蛋白或植物性替代品。"},{"en":"If animal protein becomes more available, nutrition may improve in some poor communities.","zh":"如果動物蛋白變得更容易獲得，一些貧困社區的營養可能改善。"},{"en":"The phrase focuses on nutritional content from animals.","zh":"這個片語集中於來自動物的營養成分。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":12},{"front":"for the first time","meaning":"首次","examples":[{"en":"Some people could receive adequate animal protein for the first time.","zh":"有些人可以首次獲得足夠動物蛋白。"},{"en":"For the first time means something happens that has never happened before.","zh":"for the first time 指某事以前從未發生，現在第一次發生。"},{"en":"A child may ride a bicycle alone for the first time after weeks of practice.","zh":"經過數星期練習後，孩子可能首次獨自踏單車。"},{"en":"If families get enough protein for the first time, health outcomes may improve.","zh":"如果家庭首次獲得足夠蛋白質，健康結果可能改善。"},{"en":"The phrase marks a new experience or milestone.","zh":"這個片語標示新經驗或里程碑。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":12},{"front":"in the long run","meaning":"長遠來說","examples":[{"en":"In the long run, tissue-cloning techniques could produce meat.","zh":"長遠來說，組織克隆技術可以生產肉類。"},{"en":"In the long run means over a long period, not immediately.","zh":"in the long run 指在長時間後，而不是立即。"},{"en":"Saving a little money every month can help in the long run.","zh":"每月儲一點錢長遠來說會有幫助。"},{"en":"If a technology is expensive now, it may become useful in the long run.","zh":"如果一項科技現在很昂貴，長遠來說可能變得有用。"},{"en":"The phrase shifts attention from short-term problems to future results.","zh":"這個片語把注意力由短期問題轉向未來結果。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":12},{"front":"tissue-cloning techniques","meaning":"組織克隆技術","examples":[{"en":"Tissue-cloning techniques could be used to grow meat.","zh":"組織克隆技術可用來培植肉類。"},{"en":"Tissue-cloning techniques are methods for growing cells or tissues from biological material.","zh":"tissue-cloning techniques 是從生物材料培養細胞或組織的方法。"},{"en":"Scientists may use tissue-cloning techniques to study disease or repair damaged tissue.","zh":"科學家可能使用組織克隆技術研究疾病或修復受損組織。"},{"en":"If tissue-cloning techniques produce meat, fewer animals may need to be raised for food.","zh":"如果組織克隆技術生產肉類，可能需要飼養較少食用動物。"},{"en":"The phrase refers to advanced biological production methods.","zh":"這個片語指先進生物生產方法。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":12},{"front":"desired portions of meat","meaning":"所需部位的肉","examples":[{"en":"Scientists could grow desired portions of meat by themselves.","zh":"科學家可以單獨培植所需部位的肉。"},{"en":"Desired portions of meat are the specific cuts or pieces of meat people want to eat.","zh":"desired portions of meat 是人們想食用的特定肉類切塊或部位。"},{"en":"A restaurant may order desired portions of meat such as steaks, ribs, or drumsticks.","zh":"餐廳可能訂購牛扒、肋骨或雞槌等所需部位的肉。"},{"en":"If laboratories grow only desired portions of meat, less unwanted animal material may be produced.","zh":"如果實驗室只培植所需部位的肉，可能產生較少不需要的動物材料。"},{"en":"The phrase focuses on selected meat parts.","zh":"這個片語集中於被選定的肉類部位。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":12},{"front":"by themselves","meaning":"單獨地；自行","examples":[{"en":"Desired portions of meat could be grown by themselves.","zh":"所需部位的肉可以單獨培植。"},{"en":"By themselves means separately, independently, or without the whole animal or system.","zh":"by themselves 指分開、獨立或不用整個動物或系統。"},{"en":"Students should try the questions by themselves before checking the answers.","zh":"學生應先自行嘗試題目，再檢查答案。"},{"en":"If meat portions are grown by themselves, the whole animal may not be needed.","zh":"如果肉類部位可以單獨培植，就可能不需要整隻動物。"},{"en":"The phrase emphasises separation or independence.","zh":"這個片語強調分離或獨立。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":12},{"front":"DNA has been extracted","meaning":"DNA 已被提取","examples":[{"en":"Meat could be produced once DNA has been extracted.","zh":"一旦 DNA 已被提取，肉類便可以被生產。"},{"en":"DNA has been extracted means genetic material has been removed from cells for use or study.","zh":"DNA has been extracted 指遺傳物質已從細胞中取出，用於使用或研究。"},{"en":"Scientists may test a sample after DNA has been extracted in a laboratory.","zh":"科學家可能在實驗室提取 DNA 後測試樣本。"},{"en":"If DNA has been extracted from livestock, cloning or tissue growth may become possible.","zh":"如果家畜 DNA 已被提取，克隆或組織生長可能變得可行。"},{"en":"The phrase describes an early step in biological technology.","zh":"這個片語描述生物科技中的早期步驟。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":12},{"front":"cow-less steaks","meaning":"無牛扒；不用牛隻生產的牛扒","examples":[{"en":"Tissue cloning could create cow-less steaks.","zh":"組織克隆可以創造不用牛隻生產的牛扒。"},{"en":"Cow-less steaks are steaks produced without raising or slaughtering a whole cow.","zh":"cow-less steaks 是不用飼養或屠宰整隻牛而生產的牛扒。"},{"en":"A restaurant of the future might serve cow-less steaks grown in a laboratory.","zh":"未來餐廳可能供應實驗室培植的無牛扒。"},{"en":"If cow-less steaks become cheap, cattle farming may shrink.","zh":"如果無牛扒變得便宜，養牛業可能縮小。"},{"en":"The phrase sounds unusual because it separates meat from the animal.","zh":"這個片語聽起來不尋常，因為它把肉和動物分開。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":13},{"front":"chicken-less drumsticks","meaning":"無雞槌；不用雞隻生產的雞槌","examples":[{"en":"Tissue cloning could create chicken-less drumsticks.","zh":"組織克隆可以創造不用雞隻生產的雞槌。"},{"en":"Chicken-less drumsticks are drumstick-shaped meat portions produced without raising a whole chicken.","zh":"chicken-less drumsticks 是不用飼養整隻雞而生產的雞槌形肉類。"},{"en":"A future takeaway shop might sell chicken-less drumsticks grown from cells.","zh":"未來外賣店可能出售由細胞培植的無雞槌。"},{"en":"If chicken-less drumsticks become common, poultry farming may change greatly.","zh":"如果無雞槌變得普遍，家禽養殖可能大幅改變。"},{"en":"The phrase describes laboratory-grown meat shaped like a familiar food.","zh":"這個片語描述形狀像熟悉食物的實驗室培植肉。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":13},{"front":"domesticated species of livestock","meaning":"馴養家畜物種","examples":[{"en":"Domesticated species of livestock could eventually become extinct.","zh":"馴養家畜物種最終可能滅絕。"},{"en":"Domesticated species of livestock are farm animals bred and kept by humans, such as cattle, sheep, pigs, or chickens.","zh":"domesticated species of livestock 是由人類培育和飼養的農場動物，例如牛、羊、豬或雞。"},{"en":"Farmers depend on domesticated species of livestock for meat, milk, eggs, and labour.","zh":"農民依賴馴養家畜物種提供肉、奶、蛋和勞力。"},{"en":"If laboratory meat replaces farming, some domesticated livestock species may no longer be needed.","zh":"如果實驗室肉取代畜牧業，一些馴養家畜物種可能不再需要。"},{"en":"The phrase refers to human-bred farm animal groups.","zh":"這個片語指由人類培育的農場動物群體。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":13},{"front":"bred for millennia","meaning":"經過數千年培育","examples":[{"en":"Livestock species have been bred for millennia.","zh":"家畜物種經過數千年培育。"},{"en":"Bred for millennia means selectively reproduced by humans for thousands of years.","zh":"bred for millennia 指被人類選擇性繁殖了數千年。"},{"en":"Dogs have been bred for millennia for hunting, guarding, and companionship.","zh":"狗經過數千年培育，用於狩獵、守衛和陪伴。"},{"en":"If animals have been bred for millennia, they may have traits very different from wild relatives.","zh":"如果動物經過數千年培育，牠們可能有與野生親屬很不同的特徵。"},{"en":"The phrase highlights long-term human selection.","zh":"這個片語強調長期人為選擇。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":13},{"front":"grotesquely enhanced traits","meaning":"被怪異地強化的特徵","examples":[{"en":"Some livestock have grotesquely enhanced traits.","zh":"有些家畜具有被怪異地強化的特徵。"},{"en":"Grotesquely enhanced traits are features exaggerated by breeding in an unnatural or disturbing way.","zh":"grotesquely enhanced traits 是透過培育被誇大到不自然或令人不安的特徵。"},{"en":"A plant bred only for giant fruit may develop grotesquely enhanced traits.","zh":"只為巨大果實而培育的植物，可能發展出被怪異地強化的特徵。"},{"en":"If animals are bred for extreme size or productivity, health problems may result.","zh":"如果動物為極端體型或生產力而被培育，健康問題可能出現。"},{"en":"The phrase suggests that human breeding has pushed traits too far.","zh":"這個片語暗示人類培育把特徵推得太遠。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":13},{"front":"be allowed to become extinct","meaning":"被允許滅絕","examples":[{"en":"Some domesticated species could be allowed to become extinct.","zh":"一些馴養物種可能被允許滅絕。"},{"en":"Be allowed to become extinct means humans would not prevent a species from disappearing.","zh":"be allowed to become extinct 指人類不阻止某物種消失。"},{"en":"A rare crop variety may become extinct if no farmers keep growing it.","zh":"如果沒有農民繼續種植，罕見作物品種可能滅絕。"},{"en":"If livestock are no longer needed, society might allow some breeds to disappear.","zh":"如果家畜不再被需要，社會可能容許某些品種消失。"},{"en":"The phrase suggests deliberate non-intervention.","zh":"這個片語暗示有意識地不介入。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":13},{"front":"except for","meaning":"除了……之外","examples":[{"en":"These species might disappear except for a few specimens in zoos.","zh":"這些物種可能消失，除了動物園中的少數個體之外。"},{"en":"Except for means not including or apart from something.","zh":"except for 指不包括某事物，或除某事物以外。"},{"en":"Everyone arrived on time except for one student whose bus broke down.","zh":"除了一名巴士壞了的學生之外，所有人都準時到達。"},{"en":"If a species disappears except for zoo specimens, it no longer lives normally in farms or wild areas.","zh":"如果某物種除了動物園個體之外都消失，它就不再正常生活於農場或野外。"},{"en":"The phrase introduces the only remaining exception.","zh":"這個片語引出唯一剩下的例外。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":13},{"front":"specimens in zoos","meaning":"動物園中的標本；個體","examples":[{"en":"A few specimens could be kept in zoos.","zh":"少數個體可以被保留在動物園中。"},{"en":"Specimens in zoos are individual animals kept as examples of a species.","zh":"specimens in zoos 是被保存在動物園中作為物種例子的個別動物。"},{"en":"A zoo may keep specimens of rare animals for education and conservation.","zh":"動物園可能保留罕見動物個體，用於教育和保育。"},{"en":"If only specimens in zoos remain, a species has lost its normal working or wild population.","zh":"如果只剩動物園中的個體，該物種已失去正常工作或野外族群。"},{"en":"The phrase refers to individual animals, not whole ecosystems.","zh":"這個片語指個別動物，而不是整個生態系統。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":13},{"front":"game such as","meaning":"……等野味","examples":[{"en":"Game such as wild deer and rabbits may become more abundant.","zh":"野鹿和兔子等野味可能變得更豐富。"},{"en":"Game such as means wild animals hunted or eaten as food, including the examples named.","zh":"game such as 指被狩獵或食用的野生動物，包括所列例子。"},{"en":"Restaurants may serve game such as venison during hunting season.","zh":"餐廳可能在狩獵季節供應鹿肉等野味。"},{"en":"If farms return to wilderness, game such as deer and rabbits may increase.","zh":"如果農場回復荒野，鹿和兔子等野味可能增加。"},{"en":"The phrase introduces examples of wild meat animals.","zh":"這個片語引出野生肉類動物例子。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":13},{"front":"wild deer","meaning":"野鹿","examples":[{"en":"Wild deer may become more abundant as farmland returns to wilderness.","zh":"隨着農地回復為荒野，野鹿可能變得更豐富。"},{"en":"Wild deer are deer that live freely in natural habitats rather than on farms.","zh":"wild deer 是自由生活在自然棲息地，而不是農場中的鹿。"},{"en":"Drivers in rural areas must watch for wild deer crossing roads at night.","zh":"鄉郊地區司機夜間必須留意野鹿橫過馬路。"},{"en":"If forests expand, wild deer may find more food and shelter.","zh":"如果森林擴大，野鹿可能找到更多食物和庇護。"},{"en":"The phrase refers to deer living outside human farming systems.","zh":"這個片語指生活在人類農業系統以外的鹿。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":13},{"front":"wild ducks","meaning":"野鴨","examples":[{"en":"Wild ducks may supplement laboratory-grown meat.","zh":"野鴨可能補充實驗室培植肉。"},{"en":"Wild ducks are ducks that live freely in wetlands, lakes, or rivers.","zh":"wild ducks 是自由生活在濕地、湖泊或河流中的鴨。"},{"en":"Birdwatchers may see wild ducks resting near a city park pond.","zh":"觀鳥者可能在城市公園池塘附近看到野鴨休息。"},{"en":"If wild habitats recover, wild ducks may become more common.","zh":"如果野生棲息地恢復，野鴨可能變得更常見。"},{"en":"The phrase refers to naturally living ducks, not farmed ducks.","zh":"這個片語指自然生活的鴨，而不是農場鴨。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":14},{"front":"ever more abundant","meaning":"越來越豐富","examples":[{"en":"Wild game may become ever more abundant.","zh":"野味可能變得越來越豐富。"},{"en":"Ever more abundant means increasingly plentiful over time.","zh":"ever more abundant 指隨時間越來越多。"},{"en":"Online learning materials have become ever more abundant for language students.","zh":"對語言學生而言，網上學習材料已變得越來越豐富。"},{"en":"If farmland reverts to wilderness, wild animals may become ever more abundant.","zh":"如果農地回復為荒野，野生動物可能變得越來越豐富。"},{"en":"The phrase emphasises continuing increase.","zh":"這個片語強調持續增加。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":14},{"front":"revert to wilderness","meaning":"回復為荒野","examples":[{"en":"Farms may revert to wilderness in the future.","zh":"農場未來可能回復為荒野。"},{"en":"Revert to wilderness means return to a wild natural state after human use ends.","zh":"revert to wilderness 指在人類使用停止後回到野生自然狀態。"},{"en":"An abandoned field may revert to wilderness as trees and animals return.","zh":"被棄置的田地可能隨着樹木和動物回歸而回復為荒野。"},{"en":"If food needs less farmland, some farms could revert to wilderness.","zh":"如果食物需要較少農地，一些農場可以回復為荒野。"},{"en":"The phrase describes land moving back toward nature.","zh":"這個片語描述土地回到自然狀態。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":14},{"front":"supplement laboratory-grown meat","meaning":"補充實驗室培植肉","examples":[{"en":"Wild game could supplement laboratory-grown meat.","zh":"野味可以補充實驗室培植肉。"},{"en":"Supplement laboratory-grown meat means add to or provide extra food alongside meat grown in labs.","zh":"supplement laboratory-grown meat 指在實驗室培植肉之外增加或提供額外食物。"},{"en":"A family may supplement rice with vegetables and fish for a more balanced meal.","zh":"家庭可以用蔬菜和魚補充米飯，令膳食更均衡。"},{"en":"If wild game supplements laboratory-grown meat, future diets may include both natural and artificial sources.","zh":"如果野味補充實驗室培植肉，未來飲食可同時包括自然和人工來源。"},{"en":"The phrase means adding to, not completely replacing.","zh":"這個片語指補充，而不是完全取代。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":14},{"front":"laboratory-grown meat","meaning":"實驗室培植肉","examples":[{"en":"Laboratory-grown meat may become part of future diets.","zh":"實驗室培植肉可能成為未來飲食的一部分。"},{"en":"Laboratory-grown meat is meat produced from cells in controlled conditions rather than from slaughtered animals.","zh":"laboratory-grown meat 是在受控條件下由細胞生產，而不是由屠宰動物取得的肉。"},{"en":"A future supermarket may sell laboratory-grown meat beside traditional meat.","zh":"未來超市可能把實驗室培植肉放在傳統肉類旁出售。"},{"en":"If laboratory-grown meat becomes cheap, farming and land use may change.","zh":"如果實驗室培植肉變得便宜，農業和土地使用可能改變。"},{"en":"The phrase refers to cultured or cell-based meat.","zh":"這個片語指培養肉或細胞肉。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":14},{"front":"diets of tomorrow’s affluent","meaning":"未來富裕人士的飲食","examples":[{"en":"Wild game may appear in the diets of tomorrow’s affluent.","zh":"野味可能出現在未來富裕人士的飲食中。"},{"en":"Diets of tomorrow’s affluent means the foods likely to be eaten by wealthy people in the future.","zh":"diets of tomorrow’s affluent 指未來富裕人士可能食用的食物。"},{"en":"The diets of tomorrow’s affluent may include lab-grown meat, wild game, and high-tech plant foods.","zh":"未來富裕人士的飲食可能包括實驗室肉、野味和高科技植物食品。"},{"en":"If affluent consumers demand ethical food, future diets may change quickly.","zh":"如果富裕消費者要求道德食物，未來飲食可能迅速改變。"},{"en":"The phrase links future wealth with eating habits.","zh":"這個片語把未來財富與飲食習慣連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":14},{"front":"rising personal incomes","meaning":"個人收入上升","examples":[{"en":"Rising personal incomes bring rising expectations of mobility.","zh":"個人收入上升帶來對流動能力日益提高的期望。"},{"en":"Rising personal incomes mean people individually earn more money over time.","zh":"rising personal incomes 指個人隨時間賺取更多金錢。"},{"en":"Rising personal incomes may allow families to buy cars, phones, or better housing.","zh":"個人收入上升可能讓家庭購買汽車、手機或更好住房。"},{"en":"If personal incomes rise, people often expect more freedom to travel.","zh":"如果個人收入上升，人們通常期待更多旅行自由。"},{"en":"The phrase connects individual wealth with lifestyle changes.","zh":"這個片語把個人財富與生活方式改變連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":14},{"front":"rising expectations of mobility","meaning":"對流動能力日益提高的期望","examples":[{"en":"Rising incomes create rising expectations of mobility.","zh":"收入上升創造對流動能力日益提高的期望。"},{"en":"Rising expectations of mobility mean growing demands for easier, faster, or more flexible travel.","zh":"rising expectations of mobility 指對更容易、更快速或更靈活出行的需求日益增加。"},{"en":"Young workers may have rising expectations of mobility if better transport lets them live farther from work.","zh":"如果更好交通讓年輕員工住得離工作更遠，他們可能有更高流動能力期望。"},{"en":"If people expect more mobility, governments may need better roads, trains, or air transport.","zh":"如果人們期待更多流動能力，政府可能需要更好道路、鐵路或航空交通。"},{"en":"The phrase links social expectations with movement.","zh":"這個片語把社會期望與移動連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":14},{"front":"another luxury of today’s rich","meaning":"當今富人的另一項奢侈享受","examples":[{"en":"Greater mobility is another luxury of today’s rich.","zh":"更大的流動能力是當今富人的另一項奢侈享受。"},{"en":"Another luxury of today’s rich means one more benefit currently enjoyed mainly by wealthy people.","zh":"another luxury of today’s rich 指目前主要由富裕人士享有的又一項好處。"},{"en":"Private tutoring can be another luxury of today’s rich in places where public education is weak.","zh":"在公共教育薄弱的地方，私人補習可以是當今富人的另一項奢侈享受。"},{"en":"If air taxis become cheaper, a luxury of today’s rich may become ordinary tomorrow.","zh":"如果空中的士變得更便宜，今日富人的奢侈享受明日可能變得普通。"},{"en":"The phrase compares present privilege with possible future access.","zh":"這個片語比較現在的特權與未來可能的可得性。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":14},{"front":"a necessity of tomorrow’s global population","meaning":"未來全球人口的必需品","examples":[{"en":"Mobility could become a necessity of tomorrow’s global population.","zh":"流動能力可能成為未來全球人口的必需品。"},{"en":"A necessity of tomorrow’s global population means something future people worldwide may feel they need.","zh":"a necessity of tomorrow’s global population 指未來世界各地的人可能覺得需要的東西。"},{"en":"Reliable internet may become a necessity of tomorrow’s global population.","zh":"可靠互聯網可能成為未來全球人口的必需品。"},{"en":"If people live far apart, mobility may become a necessity rather than a luxury.","zh":"如果人們分散居住，流動能力可能成為必需品，而不是奢侈品。"},{"en":"The phrase describes a future basic need.","zh":"這個片語描述未來基本需要。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":14},{"front":"choose to live","meaning":"選擇居住","examples":[{"en":"People may choose to live widely dispersed in the future.","zh":"人們未來可能選擇廣泛分散地居住。"},{"en":"Choose to live means decide where or how to make one’s home.","zh":"choose to live 指決定在哪裡或以甚麼方式安家。"},{"en":"Some families choose to live near schools, while others choose quiet countryside.","zh":"有些家庭選擇住近學校，另一些則選擇安靜鄉郊。"},{"en":"If transport becomes faster, people may choose to live farther from city centres.","zh":"如果交通變得更快，人們可能選擇住得離市中心更遠。"},{"en":"The phrase highlights personal decision about residence.","zh":"這個片語強調關於居住的個人決定。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":15},{"front":"widely dispersed","meaning":"廣泛分散的","examples":[{"en":"Future populations may live widely dispersed in a post-agrarian wilderness.","zh":"未來人口可能廣泛分散地生活在後農業荒野中。"},{"en":"Widely dispersed means spread out over a large area rather than gathered closely together.","zh":"widely dispersed 指分布在大範圍內，而不是緊密聚集。"},{"en":"Students in rural districts may be widely dispersed, so school buses travel long distances.","zh":"鄉郊地區學生可能廣泛分散，所以校巴要行駛很遠。"},{"en":"If homes are widely dispersed, transport and communication systems become important.","zh":"如果住宅廣泛分散，交通和通訊系統就變得重要。"},{"en":"The phrase describes a scattered pattern.","zh":"這個片語描述分散模式。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":15},{"front":"post-agrarian wilderness","meaning":"後農業荒野","examples":[{"en":"People may live in a post-agrarian wilderness after farmland declines.","zh":"農地減少後，人們可能生活在後農業荒野中。"},{"en":"A post-agrarian wilderness is land that has returned to wild nature after agriculture has reduced or ended.","zh":"post-agrarian wilderness 是農業減少或結束後回復野生自然的土地。"},{"en":"An abandoned farming valley may become a post-agrarian wilderness if forests and animals return.","zh":"如果森林和動物回歸，被棄置農谷可能變成後農業荒野。"},{"en":"If food production needs little farmland, more regions could become post-agrarian wilderness.","zh":"如果食物生產只需要少量農地，更多地區可能變成後農業荒野。"},{"en":"The phrase imagines nature returning after the age of farming.","zh":"這個片語想像農業時代後自然回歸。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":15},{"front":"a pilot as well as a writer","meaning":"既是飛機師也是作家","examples":[{"en":"James Fallows is a pilot as well as a writer.","zh":"James Fallows 既是飛機師也是作家。"},{"en":"A pilot as well as a writer means someone has both the skill of flying aircraft and the profession of writing.","zh":"a pilot as well as a writer 指某人既有駕駛飛機能力，也從事寫作。"},{"en":"A doctor as well as a teacher can explain medical topics clearly to students.","zh":"既是醫生也是老師的人，可以清楚向學生解釋醫學主題。"},{"en":"If a writer is also a pilot, their comments on aircraft may feel more informed.","zh":"如果作家同時是飛機師，他對飛機的評論可能更有根據。"},{"en":"The phrase highlights two roles in one person.","zh":"這個片語強調同一人有兩種角色。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":15},{"front":"serious attempts by","meaning":"由……作出的認真嘗試","examples":[{"en":"The book describes serious attempts by entrepreneurs to promote air taxis.","zh":"這本書描述企業家推廣空中的士的認真嘗試。"},{"en":"Serious attempts by means real and determined efforts made by a person or group.","zh":"serious attempts by 指由某人或群體作出的真實而堅定努力。"},{"en":"Serious attempts by teachers to improve speaking lessons may include new activities and feedback.","zh":"老師為改善口語課作出的認真嘗試，可能包括新活動和回饋。"},{"en":"If entrepreneurs make serious attempts to develop air taxis, the idea is not only fantasy.","zh":"如果企業家認真嘗試發展空中的士，這個想法就不只是幻想。"},{"en":"The phrase suggests effort with planning and commitment.","zh":"這個片語暗示有計劃和承諾的努力。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":15},{"front":"state and private entrepreneurs","meaning":"政府及私人企業家","examples":[{"en":"State and private entrepreneurs have tried to promote an air taxi system.","zh":"政府及私人企業家都曾嘗試推廣空中的士系統。"},{"en":"State and private entrepreneurs are innovators or business organisers from government and private sectors.","zh":"state and private entrepreneurs 指來自政府和私人界別的創新者或商業組織者。"},{"en":"State and private entrepreneurs may work together on transport, energy, or housing projects.","zh":"政府及私人企業家可能在交通、能源或住房項目上合作。"},{"en":"If both public and private entrepreneurs support a technology, development may speed up.","zh":"如果公共和私人企業家都支持一項科技，發展可能加快。"},{"en":"The phrase combines government-led and business-led initiative.","zh":"這個片語結合政府主導和商業主導的倡議。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":15},{"front":"promote an air taxi system","meaning":"推廣空中的士系統","examples":[{"en":"Entrepreneurs want to promote an air taxi system.","zh":"企業家希望推廣空中的士系統。"},{"en":"Promote an air taxi system means encourage people, investors, or governments to support small aircraft used like taxis.","zh":"promote an air taxi system 指鼓勵人們、投資者或政府支持像的士一樣使用的小型飛機。"},{"en":"A company may promote an air taxi system by showing how it saves travel time.","zh":"公司可能透過展示它如何節省交通時間來推廣空中的士系統。"},{"en":"If air taxis become safe and affordable, more cities may support the system.","zh":"如果空中的士變得安全且可負擔，更多城市可能支持該系統。"},{"en":"The phrase describes public and commercial support for a new transport idea.","zh":"這個片語描述對新交通概念的公眾和商業支持。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":15},{"front":"within the price range of","meaning":"在……可負擔的價格範圍內","examples":[{"en":"Air taxis may fall within the price range of today’s middle class.","zh":"空中的士可能落在今日中產階級可負擔的價格範圍內。"},{"en":"Within the price range of means affordable for a particular group.","zh":"within the price range of 指某群體負擔得起。"},{"en":"A laptop within the price range of students must be useful but not too expensive.","zh":"在學生可負擔價格範圍內的手提電腦必須有用但不太貴。"},{"en":"If air taxis fall within the price range of middle-class families, demand may grow.","zh":"如果空中的士落在中產家庭可負擔價格範圍內，需求可能增長。"},{"en":"The phrase connects cost with who can pay.","zh":"這個片語把成本與誰能付款連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":15},{"front":"today’s middle class","meaning":"今日的中產階級","examples":[{"en":"Air taxis may become affordable for today’s middle class.","zh":"空中的士可能變得讓今日的中產階級負擔得起。"},{"en":"Today’s middle class means people currently between the very rich and the poor in income and lifestyle.","zh":"today’s middle class 指目前在收入和生活方式上介乎非常富有與貧窮之間的人。"},{"en":"Today’s middle class may expect good schools, reliable transport, and modern technology.","zh":"今日的中產階級可能期待良好學校、可靠交通和現代科技。"},{"en":"If a product reaches today’s middle class, it can become a mass market item.","zh":"如果產品進入今日中產階級，它可能成為大眾市場商品。"},{"en":"The phrase refers to a present-day social and economic group.","zh":"這個片語指現今的社會和經濟群體。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":15},{"front":"chief obstacles to","meaning":"……的主要障礙","examples":[{"en":"Price and danger are two chief obstacles to personal aircraft.","zh":"價格和危險是個人飛機的兩個主要障礙。"},{"en":"Chief obstacles to something are the main problems preventing it from happening.","zh":"chief obstacles to 指阻止某事發生的主要問題。"},{"en":"High rent and low foot traffic are chief obstacles to opening a small shop.","zh":"高租金和低人流是開小店的主要障礙。"},{"en":"If price and danger are reduced, personal aircraft may become more realistic.","zh":"如果價格和危險降低，個人飛機可能變得更現實。"},{"en":"The phrase identifies the biggest barriers.","zh":"這個片語指出最大阻礙。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":15},{"front":"science fiction fantasy","meaning":"科幻幻想","examples":[{"en":"The personal plane remains a science fiction fantasy for many people.","zh":"對許多人而言，個人飛機仍然是科幻幻想。"},{"en":"A science fiction fantasy is an idea that sounds exciting but belongs more to imagined futures than present reality.","zh":"science fiction fantasy 是聽起來令人興奮，但更屬想像未來而非當前現實的想法。"},{"en":"Flying cars still feel like a science fiction fantasy to many commuters.","zh":"對許多通勤者而言，飛行汽車仍感覺像科幻幻想。"},{"en":"If technology lowers cost and danger, a science fiction fantasy may become practical.","zh":"如果科技降低成本和危險，科幻幻想可能變得實用。"},{"en":"The phrase contrasts imagination with current reality.","zh":"這個片語把想像與當前現實作對比。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":16},{"front":"personal plane","meaning":"個人飛機","examples":[{"en":"A personal plane could offer great mobility in the future.","zh":"個人飛機未來可以提供很高流動能力。"},{"en":"A personal plane is a small aircraft used by an individual or family for private travel.","zh":"personal plane 是個人或家庭用於私人旅行的小型飛機。"},{"en":"A business owner with a personal plane could visit distant clients more quickly.","zh":"擁有個人飛機的企業主可以更快拜訪遠方客戶。"},{"en":"If personal planes become cheaper and safer, travel patterns may change greatly.","zh":"如果個人飛機變得更便宜和安全，出行模式可能大幅改變。"},{"en":"The phrase describes private air transport.","zh":"這個片語描述私人航空交通。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":16},{"front":"hover car","meaning":"懸浮汽車","examples":[{"en":"A hover car is another fantasy of future mobility.","zh":"懸浮汽車是另一種未來流動能力幻想。"},{"en":"A hover car is an imagined vehicle that moves above the ground without normal wheels.","zh":"hover car 是想像中不靠普通輪子、在地面上方移動的車輛。"},{"en":"Children may draw a hover car when imagining a city of the future.","zh":"孩子想像未來城市時可能畫懸浮汽車。"},{"en":"If hover cars ever become real, road design and traffic rules would need to change.","zh":"如果懸浮汽車真的出現，道路設計和交通規則都需要改變。"},{"en":"The phrase belongs more to futuristic transport imagination than normal daily life.","zh":"這個片語較屬未來交通想像，而不是普通日常生活。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":16},{"front":"technological improvements","meaning":"技術改進","examples":[{"en":"Technological improvements are driving prices down.","zh":"技術改進正在使價格下降。"},{"en":"Technological improvements are advances that make machines, systems, or methods better.","zh":"technological improvements 是令機器、系統或方法變得更好的進步。"},{"en":"Technological improvements in batteries can make electric buses travel farther.","zh":"電池技術改進可以令電動巴士行駛更遠。"},{"en":"If technological improvements reduce costs, more people can buy advanced products.","zh":"如果技術改進降低成本，更多人可以購買先進產品。"},{"en":"The phrase describes progress in technology.","zh":"這個片語描述科技進步。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":16},{"front":"drive prices down","meaning":"使價格下降","examples":[{"en":"Technological improvements can drive prices down.","zh":"技術改進可以使價格下降。"},{"en":"Drive prices down means cause prices to fall.","zh":"drive prices down 指導致價格下降。"},{"en":"Competition between supermarkets can drive prices down for shoppers.","zh":"超市之間競爭可以為購物者使價格下降。"},{"en":"If machines become easier to build, production costs may drive prices down.","zh":"如果機器變得更容易製造，生產成本下降可能使價格下降。"},{"en":"The phrase links a cause with lower prices.","zh":"這個片語把原因與較低價格連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":16},{"front":"pilot an aircraft","meaning":"駕駛飛機","examples":[{"en":"Piloting an aircraft is harder than driving a car.","zh":"駕駛飛機比駕駛汽車更困難。"},{"en":"Pilot an aircraft means control and fly a plane or other flying machine.","zh":"pilot an aircraft 指控制並駕駛飛機或其他飛行器。"},{"en":"A trained pilot must learn weather, instruments, and safety rules before piloting an aircraft.","zh":"受訓飛機師在駕駛飛機前必須學習天氣、儀器和安全規則。"},{"en":"If more people pilot aircraft, training and computer support become important.","zh":"如果更多人駕駛飛機，訓練和電腦支援就變得重要。"},{"en":"The phrase refers to flying control, not being a passenger.","zh":"這個片語指飛行控制，而不是乘客身份。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":16},{"front":"in three dimensions","meaning":"在三維空間中","examples":[{"en":"Piloting an aircraft in three dimensions is difficult.","zh":"在三維空間中駕駛飛機很困難。"},{"en":"In three dimensions means with movement up and down as well as forward, backward, and sideways.","zh":"in three dimensions 指除了前後左右，也有上下移動。"},{"en":"Flying a drone in three dimensions requires more awareness than pushing a toy car on a table.","zh":"在三維空間中操控無人機，比在桌上推玩具車需要更多意識。"},{"en":"If a vehicle moves in three dimensions, there are more directions to control safely.","zh":"如果交通工具在三維空間中移動，就有更多方向需要安全控制。"},{"en":"The phrase describes movement through 3D space.","zh":"這個片語描述三維空間中的移動。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":16},{"front":"in two dimensions","meaning":"在二維平面中","examples":[{"en":"Driving a car in two dimensions is easier than flying.","zh":"在二維平面中駕駛汽車比飛行容易。"},{"en":"In two dimensions means moving mainly on a flat surface, forward, backward, left, or right.","zh":"in two dimensions 指主要在平面上前後左右移動。"},{"en":"A board game piece moves in two dimensions across the table.","zh":"棋子在桌面上以二維方式移動。"},{"en":"If driving happens mostly in two dimensions, it involves fewer movement directions than flying.","zh":"如果駕駛主要在二維平面中發生，它涉及的移動方向比飛行少。"},{"en":"The phrase contrasts flat movement with flight.","zh":"這個片語把平面移動與飛行作對比。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":16},{"front":"pilot error","meaning":"飛機師失誤","examples":[{"en":"Pilot error causes more fatalities than driver error.","zh":"飛機師失誤造成的死亡事故比司機失誤更多。"},{"en":"Pilot error means a mistake made by the person flying an aircraft.","zh":"pilot error 指駕駛飛機的人所犯的錯誤。"},{"en":"A pilot error may happen if someone misreads an instrument during bad weather.","zh":"如果有人在惡劣天氣中誤讀儀器，就可能發生飛機師失誤。"},{"en":"If pilot error is common, computer-controlled aircraft may improve safety.","zh":"如果飛機師失誤常見，電腦控制飛機可能改善安全。"},{"en":"The phrase identifies human mistakes in flying.","zh":"這個片語指出飛行中的人為錯誤。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":16},{"front":"fatalities","meaning":"死亡事故；死亡人數","examples":[{"en":"Pilot error causes many fatalities.","zh":"飛機師失誤造成許多死亡事故。"},{"en":"Fatalities are deaths caused by an accident, disaster, or violent event.","zh":"fatalities 是由意外、災難或暴力事件造成的死亡人數。"},{"en":"Road safety campaigns aim to reduce fatalities among drivers and pedestrians.","zh":"道路安全宣傳旨在減少司機和行人的死亡人數。"},{"en":"If aircraft accidents involve many fatalities, safety systems must be improved.","zh":"如果飛機事故涉及大量死亡，安全系統必須改善。"},{"en":"The word is formal and usually used in reports.","zh":"這個詞較正式，通常用於報告。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":16},{"front":"driver error","meaning":"司機失誤","examples":[{"en":"Driver error is compared with pilot error.","zh":"司機失誤被拿來與飛機師失誤比較。"},{"en":"Driver error means a mistake made by someone driving a vehicle.","zh":"driver error 指駕駛車輛的人所犯的錯誤。"},{"en":"Driver error may include speeding, distraction, or failing to check mirrors.","zh":"司機失誤可能包括超速、分心或沒有檢查倒後鏡。"},{"en":"If driver error causes crashes, training and road design may need improvement.","zh":"如果司機失誤導致撞車，訓練和道路設計可能需要改善。"},{"en":"The phrase identifies human mistakes in road transport.","zh":"這個片語指出道路交通中的人為錯誤。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":17},{"front":"before long","meaning":"不久之後","examples":[{"en":"Before long, aircraft and cars may be piloted by computers.","zh":"不久之後，飛機和汽車可能由電腦駕駛。"},{"en":"Before long means soon or after a short time.","zh":"before long 指很快或短時間之後。"},{"en":"If students practise daily, before long they may speak more confidently.","zh":"如果學生每天練習，不久之後可能說得更有信心。"},{"en":"If technology improves quickly, before long some vehicles may drive themselves.","zh":"如果科技迅速改善，不久之後一些交通工具可能自動駕駛。"},{"en":"The phrase suggests something is likely to happen fairly soon.","zh":"這個片語暗示某事可能較快發生。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":17},{"front":"be piloted by computers","meaning":"由電腦駕駛","examples":[{"en":"Future aircraft and cars may be piloted by computers.","zh":"未來飛機和汽車可能由電腦駕駛。"},{"en":"Be piloted by computers means be controlled or driven automatically by computer systems.","zh":"be piloted by computers 指由電腦系統自動控制或駕駛。"},{"en":"A delivery vehicle piloted by computers could follow routes without a human driver.","zh":"由電腦駕駛的送貨車可以在沒有人類司機下跟隨路線。"},{"en":"If aircraft are piloted by computers, human error may decrease.","zh":"如果飛機由電腦駕駛，人為錯誤可能減少。"},{"en":"The phrase describes automated control.","zh":"這個片語描述自動控制。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":17},{"front":"tired or stressed","meaning":"疲倦或受壓","examples":[{"en":"Computers are never tired or stressed.","zh":"電腦永遠不會疲倦或受壓。"},{"en":"Tired or stressed means physically exhausted or mentally under pressure.","zh":"tired or stressed 指身體疲勞或心理承受壓力。"},{"en":"A driver who is tired or stressed may react too slowly to danger.","zh":"疲倦或受壓的司機可能對危險反應太慢。"},{"en":"If machines do not become tired or stressed, they may avoid some human mistakes.","zh":"如果機器不會疲倦或受壓，它們可能避免一些人為錯誤。"},{"en":"The phrase describes conditions that can weaken human performance.","zh":"這個片語描述會削弱人類表現的狀態。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":17},{"front":"grounds for optimism","meaning":"樂觀的理由","examples":[{"en":"There may be grounds for optimism about the future of civilisation.","zh":"關於文明的未來，可能有樂觀的理由。"},{"en":"Grounds for optimism are reasons to feel hopeful.","zh":"grounds for optimism 是令人感到有希望的原因。"},{"en":"Falling pollution levels can be grounds for optimism in a city.","zh":"污染水平下降可以是城市樂觀的理由。"},{"en":"If technology reduces environmental pressure, there are grounds for optimism about prosperity.","zh":"如果科技減少環境壓力，就有理由對繁榮感到樂觀。"},{"en":"The phrase suggests hope based on evidence, not wishful thinking alone.","zh":"這個片語暗示基於證據的希望，而不只是空想。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":17},{"front":"when viewing","meaning":"在看待……時","examples":[{"en":"There are grounds for optimism when viewing the future of civilisation.","zh":"在看待文明未來時，有樂觀的理由。"},{"en":"When viewing means when considering, looking at, or judging something.","zh":"when viewing 指在考慮、觀察或判斷某事時。"},{"en":"When viewing exam results, teachers should also consider student effort.","zh":"在看待考試成績時，老師也應考慮學生努力。"},{"en":"If we focus only on problems when viewing the future, we may miss possible solutions.","zh":"如果我們在看待未來時只集中於問題，就可能錯過可能解決方案。"},{"en":"The phrase introduces the perspective being used.","zh":"這個片語引出所採用的角度。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":17},{"front":"with the help of","meaning":"在……的幫助下","examples":[{"en":"With the help of technology, people may enjoy possessions, space and mobility.","zh":"在科技的幫助下，人們可能享有財物、空間和流動能力。"},{"en":"With the help of means by using support from someone or something.","zh":"with the help of 指在某人或某物支持下。"},{"en":"With the help of a dictionary, students can understand difficult reading passages.","zh":"在字典的幫助下，學生可以理解困難閱讀文章。"},{"en":"If society uses technology well, it may become richer with less environmental damage.","zh":"如果社會善用科技，就可能在較少環境破壞下變得更富裕。"},{"en":"The phrase identifies the support that makes something easier.","zh":"這個片語指出令某事更容易的支持。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":17},{"front":"without putting serious strains on","meaning":"在不對……造成嚴重壓力的情況下","examples":[{"en":"The world may prosper without putting serious strains on the environment.","zh":"世界可能在不對環境造成嚴重壓力的情況下繁榮。"},{"en":"Without putting serious strains on means without placing heavy pressure or damage on something.","zh":"without putting serious strains on 指不對某事物施加沉重壓力或傷害。"},{"en":"A school can add activities without putting serious strains on teachers if schedules are planned well.","zh":"如果時間表規劃得好，學校可以增加活動而不對老師造成嚴重壓力。"},{"en":"If growth happens efficiently, it may avoid putting serious strains on energy and land.","zh":"如果增長高效發生，就可能避免對能源和土地造成嚴重壓力。"},{"en":"The phrase emphasises avoiding excessive pressure.","zh":"這個片語強調避免過度壓力。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":17},{"front":"global environment","meaning":"全球環境","examples":[{"en":"Technology may help reduce strains on the global environment.","zh":"科技可能幫助減少對全球環境的壓力。"},{"en":"The global environment means Earth’s natural systems as a whole, including air, water, land, climate, and ecosystems.","zh":"global environment 指地球整體自然系統，包括空氣、水、土地、氣候和生態系統。"},{"en":"Plastic pollution and carbon emissions affect the global environment beyond national borders.","zh":"塑膠污染和碳排放影響跨越國界的全球環境。"},{"en":"If the global environment is damaged, people everywhere may face consequences.","zh":"如果全球環境受損，各地人們都可能面對後果。"},{"en":"The phrase looks at nature on a worldwide scale.","zh":"這個片語從全球尺度看自然。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":17},{"front":"entire projected population","meaning":"預計中的全體人口","examples":[{"en":"The world’s entire projected population may enjoy a comfortable lifestyle.","zh":"世界預計中的全體人口可能享有舒適生活方式。"},{"en":"Entire projected population means all the people expected to exist in the future estimate.","zh":"entire projected population 指未來估計中預期存在的所有人。"},{"en":"A city must plan water supply for its entire projected population, not only current residents.","zh":"城市必須為預計中的全體人口規劃供水，而不只是現有居民。"},{"en":"If resources can support the entire projected population, global comfort may be possible.","zh":"如果資源能支持預計中的全體人口，全球舒適生活可能可行。"},{"en":"The phrase combines total coverage with future prediction.","zh":"這個片語結合全面覆蓋和未來預測。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":17},{"front":"reflect the claims of the writer","meaning":"反映作者的主張","examples":[{"en":"Students decide whether the statements reflect the claims of the writer.","zh":"學生判斷陳述是否反映作者的主張。"},{"en":"Reflect the claims of the writer means match what the writer argues or believes.","zh":"reflect the claims of the writer 指與作者的論點或信念相符。"},{"en":"In reading tests, students should check whether an answer reflects the writer’s claim, not their own opinion.","zh":"在閱讀測驗中，學生應檢查答案是否反映作者主張，而不是自己的意見。"},{"en":"If a statement changes the writer’s meaning, it does not reflect the writer’s claims.","zh":"如果陳述改變作者意思，它就不反映作者主張。"},{"en":"The phrase is common in YES, NO, NOT GIVEN tasks.","zh":"這個片語常見於 YES、NO、NOT GIVEN 題。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":18},{"front":"agree with the views of the writer","meaning":"與作者觀點一致","examples":[{"en":"YES means the statement agrees with the views of the writer.","zh":"YES 表示陳述與作者觀點一致。"},{"en":"Agree with the views of the writer means match the opinion or argument expressed by the writer.","zh":"agree with the views of the writer 指與作者表達的意見或論點相符。"},{"en":"A statement agrees with the writer if it says the same thing in different words.","zh":"如果陳述用不同字眼表達相同意思，就與作者觀點一致。"},{"en":"If the writer says technology can help, a statement saying technology may offer solutions may agree.","zh":"如果作者說科技可以幫忙，陳述說科技可能提供解決方案就可能一致。"},{"en":"The phrase focuses on matching the writer’s opinion.","zh":"這個片語集中於配對作者觀點。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":18},{"front":"contradict the views of the writer","meaning":"與作者觀點相矛盾","examples":[{"en":"NO means the statement contradicts the views of the writer.","zh":"NO 表示陳述與作者觀點相矛盾。"},{"en":"Contradict the views of the writer means say the opposite of what the writer believes.","zh":"contradict the views of the writer 指說出與作者信念相反的內容。"},{"en":"If the writer supports technology, a statement saying technology is useless may contradict their views.","zh":"如果作者支持科技，陳述說科技無用可能與其觀點相矛盾。"},{"en":"Students should choose NO only when the passage clearly gives the opposite meaning.","zh":"只有當文章清楚給出相反意思時，學生才應選 NO。"},{"en":"The phrase signals direct disagreement with the writer’s position.","zh":"這個片語表示與作者立場直接不一致。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":18},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"NOT GIVEN means it is impossible to say what the writer thinks.","zh":"NOT GIVEN 表示無法判斷作者想法。"},{"en":"Impossible to say means there is not enough information to decide.","zh":"impossible to say 指沒有足夠資料作判斷。"},{"en":"If a passage mentions buses but not ticket prices, it is impossible to say whether tickets are cheap.","zh":"如果文章提到巴士但沒有提到票價，就無法判斷車票是否便宜。"},{"en":"Students should not guess when it is impossible to say from the text.","zh":"當從文本無法判斷時，學生不應猜測。"},{"en":"The phrase signals missing evidence.","zh":"這個片語表示缺乏證據。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":18},{"front":"ignore the fact that","meaning":"忽視……這一事實","examples":[{"en":"The statement asks whether wealthy people ignore the fact that millions live in poverty.","zh":"該陳述問富裕人士是否忽視數百萬人生活在貧窮中這一事實。"},{"en":"Ignore the fact that means fail or refuse to recognise something true and important.","zh":"ignore the fact that 指沒有或拒絕承認某個真實而重要的事實。"},{"en":"A manager should not ignore the fact that staff are exhausted.","zh":"經理不應忽視員工已筋疲力竭這一事實。"},{"en":"If policy ignores the fact that people are poor, it may fail to solve real problems.","zh":"如果政策忽視人們貧窮這一事實，就可能無法解決真正問題。"},{"en":"The phrase criticises overlooking an important reality.","zh":"這個片語批評忽略重要現實。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":18},{"front":"millions are living in poverty","meaning":"數百萬人生活在貧窮中","examples":[{"en":"Millions of people are living in poverty.","zh":"數百萬人生活在貧窮中。"},{"en":"Millions are living in poverty means very large numbers of people lack enough income or resources for a decent life.","zh":"millions are living in poverty 指非常多人缺乏足夠收入或資源過上體面生活。"},{"en":"A charity report may show that millions are living in poverty despite economic growth.","zh":"慈善報告可能顯示，儘管經濟增長，仍有數百萬人生活在貧窮中。"},{"en":"If millions are living in poverty, global prosperity is not shared equally.","zh":"如果數百萬人生活在貧窮中，全球繁榮就沒有被公平分享。"},{"en":"The phrase highlights large-scale deprivation.","zh":"這個片語強調大規模匱乏。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":18},{"front":"there are reasons why","meaning":"有理由解釋為何……","examples":[{"en":"There are reasons why the future population may not enjoy a comfortable lifestyle.","zh":"有理由解釋為何未來人口可能不能享有舒適生活方式。"},{"en":"There are reasons why means explanations or causes exist for a situation.","zh":"there are reasons why 指某情況存在解釋或原因。"},{"en":"There are reasons why some students learn faster, including sleep, practice, and support.","zh":"有理由解釋為何有些學生學得更快，包括睡眠、練習和支援。"},{"en":"If there are reasons why a plan may fail, planners should address them early.","zh":"如果有理由解釋為何計劃可能失敗，規劃者應及早處理。"},{"en":"The phrase introduces possible causes or explanations.","zh":"這個片語引出可能原因或解釋。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":18},{"front":"first thing to consider","meaning":"首先要考慮的事情","examples":[{"en":"The question asks whether the first thing to consider is environmental protection.","zh":"題目問首先要考慮的事情是否是環境保護。"},{"en":"First thing to consider means the most important starting point in thinking about an issue.","zh":"first thing to consider 指思考議題時最重要的起點。"},{"en":"When choosing a school, the first thing to consider may be whether the child feels safe.","zh":"選擇學校時，首先要考慮的事情可能是孩子是否感到安全。"},{"en":"If environmental protection is the first thing to consider, economic plans must start from ecological limits.","zh":"如果環境保護是首先要考慮的事情，經濟計劃就必須從生態限制開始。"},{"en":"The phrase identifies the priority at the beginning.","zh":"這個片語指出一開始的優先事項。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":18},{"front":"environmental protection","meaning":"環境保護","examples":[{"en":"Environmental protection is one possible concern for the future.","zh":"環境保護是未來的一個可能關注點。"},{"en":"Environmental protection means actions taken to protect air, water, land, climate, and ecosystems.","zh":"environmental protection 指保護空氣、水、土地、氣候和生態系統的行動。"},{"en":"Recycling, tree planting, and pollution control are forms of environmental protection.","zh":"回收、種樹和污染控制都是環境保護形式。"},{"en":"If environmental protection is ignored, economic growth may damage health and nature.","zh":"如果環境保護被忽視，經濟增長可能損害健康和自然。"},{"en":"The phrase refers to caring for natural systems.","zh":"這個片語指照顧自然系統。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":18},{"front":"manufactured goods","meaning":"製成品","examples":[{"en":"As manufactured goods get cheaper, more people can benefit from them.","zh":"隨着製成品變得更便宜，更多人可以從中受益。"},{"en":"Manufactured goods are products made in factories or workshops.","zh":"manufactured goods 是在工廠或工場製造的產品。"},{"en":"Clothes, phones, washing machines, and furniture are manufactured goods.","zh":"衣服、手機、洗衣機和家具都是製成品。"},{"en":"If manufactured goods become cheaper, living standards may improve.","zh":"如果製成品變得更便宜，生活水平可能改善。"},{"en":"The phrase contrasts factory-made products with raw materials or services.","zh":"這個片語把工廠製品與原材料或服務作對比。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":18},{"front":"benefit more from","meaning":"從……中獲得更多好處","examples":[{"en":"People may benefit more from cheaper manufactured goods.","zh":"人們可能從較便宜製成品中獲得更多好處。"},{"en":"Benefit more from means gain greater advantage from something.","zh":"benefit more from 指從某事中得到更大好處。"},{"en":"Students may benefit more from clear examples than from long abstract explanations.","zh":"與冗長抽象解釋相比，學生可能從清晰例子中獲得更多好處。"},{"en":"If prices fall, poor families may benefit more because essentials become affordable.","zh":"如果價格下降，貧困家庭可能獲益更多，因為必需品變得可負擔。"},{"en":"The phrase compares the amount of advantage received.","zh":"這個片語比較所得好處的多少。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":19},{"front":"new types of raw materials","meaning":"新種類的原材料","examples":[{"en":"The statement mentions new types of raw materials for machinery.","zh":"該陳述提到機械的新種類原材料。"},{"en":"New types of raw materials are different basic substances that can be used to make products.","zh":"new types of raw materials 是可用來製造產品的不同基本物質。"},{"en":"A factory may test new types of raw materials to make lighter bicycles.","zh":"工廠可能測試新種類原材料，以製造較輕單車。"},{"en":"If new raw materials replace scarce metals, machinery production may become easier.","zh":"如果新原材料取代稀缺金屬，機械生產可能變得更容易。"},{"en":"The phrase focuses on new production inputs.","zh":"這個片語集中於新的生產投入。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":19},{"front":"production of machinery","meaning":"機械生產","examples":[{"en":"Raw materials are used in the production of machinery.","zh":"原材料用於機械生產。"},{"en":"Production of machinery means the process of making machines.","zh":"production of machinery 指製造機器的過程。"},{"en":"The production of machinery requires design, parts, skilled workers, and energy.","zh":"機械生產需要設計、零件、熟練工人和能源。"},{"en":"If production of machinery grows, demand for metals and power may rise.","zh":"如果機械生產增長，對金屬和電力的需求可能上升。"},{"en":"The phrase refers to manufacturing machines.","zh":"這個片語指製造機器。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":19},{"front":"bring some benefits","meaning":"帶來一些好處","examples":[{"en":"Rising fossil-fuel prices may bring some benefits.","zh":"化石燃料價格上升可能帶來一些好處。"},{"en":"Bring some benefits means produce certain useful or positive effects.","zh":"bring some benefits 指產生某些有用或正面效果。"},{"en":"A shorter school week may bring some benefits, such as more rest, but also create problems.","zh":"較短上課週可能帶來一些好處，例如更多休息，但也造成問題。"},{"en":"If fuel prices rise, they may bring benefits by encouraging efficiency and alternatives.","zh":"如果燃料價格上升，可能透過鼓勵效率和替代方案而帶來好處。"},{"en":"The phrase recognises positive effects without saying everything is good.","zh":"這個片語承認正面效果，但不表示所有事情都好。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":19},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill missing words in the short text that follows.","zh":"complete the summary below 指在下方短文中填上缺失字詞。"},{"en":"In reading tests, students complete the summary below by finding exact words in the passage.","zh":"在閱讀測驗中，學生透過在文章中尋找原字完成以下摘要。"},{"en":"If students ignore grammar, the summary may not fit even with the right idea.","zh":"如果學生忽視文法，即使意思對，摘要也可能不合適。"},{"en":"The phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":19},{"front":"one word only","meaning":"只限一個詞","examples":[{"en":"The instructions say to choose one word only from the passage.","zh":"指示說只限從文章中選擇一個詞。"},{"en":"One word only means the answer must contain exactly one word, not two or more.","zh":"one word only 指答案必須只包含一個詞，不能兩個或以上。"},{"en":"If the answer is “parks”, it follows the one word only rule.","zh":"如果答案是 parks，就符合只限一個詞的規則。"},{"en":"If students write two words, the answer may be marked wrong even if the idea is correct.","zh":"如果學生寫兩個詞，即使意思正確，也可能被判錯。"},{"en":"The phrase gives a strict exam word limit.","zh":"這個片語給出嚴格考試字數限制。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":19},{"front":"space for an increased population","meaning":"增加人口所需的空間","examples":[{"en":"The summary concerns space for an increased population.","zh":"摘要涉及增加人口所需的空間。"},{"en":"Space for an increased population means enough land or living area for more people.","zh":"space for an increased population 指供更多人使用的足夠土地或居住空間。"},{"en":"A city needs space for an increased population when many families move in.","zh":"當許多家庭搬入時，城市需要增加人口所需的空間。"},{"en":"If farmland shrinks and housing spreads wisely, there may be space for more people and nature.","zh":"如果農地縮小而住房明智擴展，就可能有人口和自然所需的空間。"},{"en":"The phrase links population growth with land use.","zh":"這個片語把人口增長與土地使用連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":19},{"front":"use of land for","meaning":"土地用於……","examples":[{"en":"The use of land for agriculture is a serious environmental threat.","zh":"土地用於農業是一項嚴重環境威脅。"},{"en":"Use of land for means using land for a particular purpose.","zh":"use of land for 指把土地用於某個特定目的。"},{"en":"The use of land for parking can reduce space for trees and playgrounds.","zh":"土地用於停車可以減少樹木和遊樂場空間。"},{"en":"If the use of land for agriculture expands, wild areas may shrink.","zh":"如果土地用於農業的面積擴大，野生地區可能縮小。"},{"en":"The phrase identifies the purpose land serves.","zh":"這個片語指出土地的用途。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":19},{"front":"the most serious threat to","meaning":"對……最嚴重的威脅","examples":[{"en":"Agricultural land use is described as the most serious threat to the environment.","zh":"農業土地使用被描述為對環境最嚴重的威脅。"},{"en":"The most serious threat to something is the greatest danger it faces.","zh":"the most serious threat to 指某事物面對的最大危險。"},{"en":"For some small shops, rising rent is the most serious threat to survival.","zh":"對一些小店而言，租金上升是對生存最嚴重的威脅。"},{"en":"If farming takes more land than cities, it may be the most serious threat to wild habitats.","zh":"如果農業佔用比城市更多土地，它可能是對野生棲息地最嚴重的威脅。"},{"en":"The phrase ranks one danger above others.","zh":"這個片語把某一危險排在其他危險之上。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":19},{"front":"an increase in the amount of land","meaning":"土地面積增加","examples":[{"en":"There has been an increase in the amount of land used for parks and forests.","zh":"用作公園和森林的土地面積已有增加。"},{"en":"An increase in the amount of land means more land is being used or reserved for a purpose.","zh":"an increase in the amount of land 指用於或保留作某目的的土地更多。"},{"en":"A school may need an increase in the amount of land for sports facilities.","zh":"學校可能需要增加土地面積作運動設施。"},{"en":"If there is an increase in land for parks, residents gain more green space.","zh":"如果公園土地面積增加，居民就得到更多綠色空間。"},{"en":"The phrase describes growth in land area.","zh":"這個片語描述土地面積增長。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":19},{"front":"land used for parks","meaning":"用作公園的土地","examples":[{"en":"More land has been used for parks in the United States.","zh":"美國有更多土地用作公園。"},{"en":"Land used for parks means land reserved for public green space, recreation, or nature protection.","zh":"land used for parks 指保留作公共綠地、休憩或自然保護的土地。"},{"en":"Land used for parks gives families places to walk, play, and rest.","zh":"用作公園的土地為家庭提供散步、玩耍和休息的地方。"},{"en":"If more land is used for parks, cities may become healthier and more attractive.","zh":"如果更多土地用作公園，城市可能變得更健康和有吸引力。"},{"en":"The phrase identifies a public and environmental land use.","zh":"這個片語指出公共和環境用途的土地。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":20},{"front":"far less land","meaning":"少得多的土地","examples":[{"en":"Far less land would be required if productivity improved.","zh":"如果生產力改善，就會需要少得多的土地。"},{"en":"Far less land means a much smaller area of land.","zh":"far less land 指面積小得多的土地。"},{"en":"Online files require far less office space than paper archives.","zh":"網上文件比紙本檔案需要少得多的辦公空間。"},{"en":"If farms produce more food per hectare, far less land may be needed.","zh":"如果農場每公頃生產更多食物，可能需要少得多的土地。"},{"en":"The phrase makes a strong reduction in land use clear.","zh":"這個片語清楚表達土地使用大幅減少。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":20},{"front":"be required to feed","meaning":"被需要用來養活","examples":[{"en":"Less land may be required to feed the world’s population.","zh":"可能需要較少土地來養活世界人口。"},{"en":"Be required to feed means be needed to produce enough food for people or animals.","zh":"be required to feed 指被需要用來為人或動物生產足夠食物。"},{"en":"A school kitchen needs enough rice and vegetables to feed hundreds of students.","zh":"學校廚房需要足夠米和蔬菜來養活數百名學生。"},{"en":"If crop yields improve, less land may be required to feed the same number of people.","zh":"如果作物產量改善，養活相同人數可能需要較少土地。"},{"en":"The phrase links resources with food supply.","zh":"這個片語把資源與食物供應連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":20},{"front":"improve worldwide","meaning":"在全球改善","examples":[{"en":"Food productivity could be improved worldwide.","zh":"糧食生產力可以在全球改善。"},{"en":"Improve worldwide means become better across the whole world, not only in one country.","zh":"improve worldwide 指在全世界變得更好，而不只是一個國家。"},{"en":"Internet access has improved worldwide, though some regions still lack service.","zh":"互聯網接入已在全球改善，雖然有些地區仍缺乏服務。"},{"en":"If farming techniques improve worldwide, hunger and land pressure may decrease.","zh":"如果農業技術在全球改善，飢餓和土地壓力可能下降。"},{"en":"The phrase describes global improvement.","zh":"這個片語描述全球性改善。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":20},{"front":"industrial production of","meaning":"……的工業生產","examples":[{"en":"Industrial production of animal foods could increase protein supplies.","zh":"動物食品的工業生產可以增加蛋白質供應。"},{"en":"Industrial production of something means making it through factory-based or technological processes.","zh":"industrial production of 指透過工廠或科技過程製造某物。"},{"en":"Industrial production of bread allows supermarkets to sell large quantities each morning.","zh":"麵包的工業生產讓超市每天早上出售大量麵包。"},{"en":"If industrial production of food expands, prices may fall but quality rules become important.","zh":"如果食物的工業生產擴大，價格可能下降，但品質規則變得重要。"},{"en":"The phrase focuses on large-scale manufactured production.","zh":"這個片語集中於大規模製造生產。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":20},{"front":"greater access to","meaning":"更容易獲得……","examples":[{"en":"Industrial techniques could allow greater access to animal protein.","zh":"工業技術可以讓人們更容易獲得動物蛋白。"},{"en":"Greater access to means more people can obtain or use something more easily.","zh":"greater access to 指更多人能更容易取得或使用某物。"},{"en":"Online lessons give rural students greater access to experienced teachers.","zh":"網上課堂讓鄉郊學生更容易接觸有經驗老師。"},{"en":"If protein production becomes cheaper, poor communities may gain greater access to nutritious food.","zh":"如果蛋白質生產變得更便宜，貧困社區可能更容易獲得營養食物。"},{"en":"The phrase focuses on availability and opportunity.","zh":"這個片語集中於可得性和機會。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":20},{"front":"entire world’s population","meaning":"全世界人口","examples":[{"en":"Animal protein could become available to the entire world’s population.","zh":"動物蛋白可以變得供全世界人口取得。"},{"en":"Entire world’s population means all people living on Earth.","zh":"entire world’s population 指生活在地球上的所有人。"},{"en":"A vaccine available to the entire world’s population would require massive production and fair distribution.","zh":"可供全世界人口使用的疫苗需要大規模生產和公平分配。"},{"en":"If nutritious food reaches the entire world’s population, global health may improve.","zh":"如果營養食物到達全世界人口，全球健康可能改善。"},{"en":"The phrase emphasises everyone, not only rich countries.","zh":"這個片語強調所有人，而不只是富裕國家。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":20},{"front":"help produce meat","meaning":"幫助生產肉類","examples":[{"en":"DNA could help scientists produce meat by tissue cloning.","zh":"DNA 可以幫助科學家透過組織克隆生產肉類。"},{"en":"Help produce meat means assist in creating meat, especially through scientific or industrial methods.","zh":"help produce meat 指幫助創造肉類，尤其是透過科學或工業方法。"},{"en":"Better animal feed can help produce meat more efficiently on farms.","zh":"更好的動物飼料可以幫助農場更有效生產肉類。"},{"en":"If DNA technology helps produce meat, fewer whole animals may be needed.","zh":"如果 DNA 科技幫助生產肉類，可能需要較少完整動物。"},{"en":"The phrase connects a tool or method with food production.","zh":"這個片語把工具或方法與食物生產連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":20},{"front":"allowed to die out","meaning":"被允許滅絕","examples":[{"en":"Some domesticated species could be allowed to die out.","zh":"一些馴養物種可能被允許滅絕。"},{"en":"Allowed to die out means permitted to disappear because people do not actively preserve them.","zh":"allowed to die out 指因人們不主動保育而被容許消失。"},{"en":"A local craft may be allowed to die out if no one teaches it to young people.","zh":"如果沒有人教年輕人，本地手藝可能被允許消失。"},{"en":"If livestock are no longer useful, some breeds might be allowed to die out.","zh":"如果家畜不再有用，某些品種可能被允許滅絕。"},{"en":"The phrase suggests passive or deliberate non-protection.","zh":"這個片語暗示被動或有意不保護。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":20},{"front":"in addition to","meaning":"除了……之外","examples":[{"en":"In addition to laboratory-grown meat, wild game may be available.","zh":"除了實驗室培植肉之外，野味也可能可得。"},{"en":"In addition to means as well as or besides something already mentioned.","zh":"in addition to 指除了已提及的事物之外。"},{"en":"In addition to homework, students should read books for pleasure.","zh":"除了功課之外，學生也應為興趣閱讀書籍。"},{"en":"If wild food is available in addition to lab meat, diets may become more varied.","zh":"如果除了實驗室肉之外還有野生食物，飲食可能變得更多樣。"},{"en":"The phrase adds another item to a list or idea.","zh":"這個片語為列表或想法加入另一項。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":20},{"front":"widely available","meaning":"廣泛可得","examples":[{"en":"Wild game may become widely available.","zh":"野味可能變得廣泛可得。"},{"en":"Widely available means easy for many people to obtain in many places.","zh":"widely available 指很多人在很多地方都容易取得。"},{"en":"Free Wi-Fi is widely available in many public libraries.","zh":"免費 Wi-Fi 在許多公共圖書館廣泛可得。"},{"en":"If laboratory meat becomes widely available, it may change everyday shopping habits.","zh":"如果實驗室肉廣泛可得，它可能改變日常購物習慣。"},{"en":"The phrase focuses on broad access.","zh":"這個片語集中於廣泛取得。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":21},{"front":"choose the correct answer","meaning":"選出正確答案","examples":[{"en":"Students choose the correct answer from the choices given.","zh":"學生從所給選項中選出正確答案。"},{"en":"Choose the correct answer means select the option that best matches the information.","zh":"choose the correct answer 指選出最符合資料的選項。"},{"en":"In a multiple-choice question, students must choose the correct answer, not the answer that only sounds familiar.","zh":"在多項選擇題中，學生必須選出正確答案，而不是只選聽起來熟悉的答案。"},{"en":"If students read too quickly, they may choose the wrong answer despite knowing the topic.","zh":"如果學生讀得太快，即使知道主題，也可能選錯答案。"},{"en":"The phrase is a standard exam instruction.","zh":"這個片語是標準考試指示。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":21},{"front":"a feature of the future","meaning":"未來的一個特徵","examples":[{"en":"Greater mobility may be a feature of the future.","zh":"更大流動能力可能是未來的一個特徵。"},{"en":"A feature of the future is something likely to characterise life in coming years.","zh":"a feature of the future 指未來歲月中可能成為生活特點的事物。"},{"en":"Remote work may be a feature of the future for many office jobs.","zh":"對許多辦公室工作而言，遙距工作可能是未來的一個特徵。"},{"en":"If air taxis become affordable, personal air travel may be a future feature.","zh":"如果空中的士變得可負擔，個人航空旅行可能成為未來特徵。"},{"en":"The phrase identifies a likely future characteristic.","zh":"這個片語指出可能的未來特點。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":21},{"front":"changes in","meaning":"……方面的改變","examples":[{"en":"The question asks about changes in the location of housing.","zh":"題目問住宅位置方面的改變。"},{"en":"Changes in means differences that happen over time in a particular area or situation.","zh":"changes in 指某方面或情況隨時間出現的差異。"},{"en":"Teachers notice changes in student confidence after weeks of speaking practice.","zh":"老師在數星期口語練習後注意到學生信心方面的改變。"},{"en":"If there are changes in housing location, transport needs may change too.","zh":"如果住宅位置方面有改變，交通需求也可能改變。"},{"en":"The phrase introduces the area where change occurs.","zh":"這個片語引出變化發生的範疇。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":21},{"front":"location of housing","meaning":"住宅位置","examples":[{"en":"Greater mobility may be connected with the location of housing.","zh":"更大流動能力可能與住宅位置有關。"},{"en":"Location of housing means where homes are built or where people choose to live.","zh":"location of housing 指住宅建於何處或人們選擇住在哪裡。"},{"en":"The location of housing affects school journeys, shopping habits, and transport needs.","zh":"住宅位置影響上學路程、購物習慣和交通需求。"},{"en":"If fast transport improves, the location of housing may spread farther from cities.","zh":"如果快速交通改善，住宅位置可能擴展到離城市更遠的地方。"},{"en":"The phrase links homes with geography and planning.","zh":"這個片語把住房與地理和規劃連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":21},{"front":"patterns of employment","meaning":"就業模式","examples":[{"en":"The option mentions changes in patterns of employment.","zh":"該選項提到就業模式的改變。"},{"en":"Patterns of employment are the ways people work, including job types, hours, places, and contracts.","zh":"patterns of employment 指人們工作的方式，包括工作類型、工時、地點和合約。"},{"en":"Remote work has changed patterns of employment for many office workers.","zh":"遙距工作改變了許多辦公室員工的就業模式。"},{"en":"If patterns of employment change, housing and transport demand may also change.","zh":"如果就業模式改變，住房和交通需求也可能改變。"},{"en":"The phrase describes broad work arrangements.","zh":"這個片語描述廣泛工作安排。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":21},{"front":"centres of transport","meaning":"交通中心","examples":[{"en":"The option mentions changes in centres of transport.","zh":"該選項提到交通中心的改變。"},{"en":"Centres of transport are important places where travel routes and services meet.","zh":"centres of transport 是交通路線和服務交匯的重要地方。"},{"en":"A railway station, airport, or bus terminal can be a centre of transport.","zh":"火車站、機場或巴士總站都可以是交通中心。"},{"en":"If air taxis become common, centres of transport may include small local airfields.","zh":"如果空中的士變得普遍，交通中心可能包括小型本地機場。"},{"en":"The phrase refers to transport hubs.","zh":"這個片語指交通樞紐。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":21},{"front":"distribution of wealth","meaning":"財富分配","examples":[{"en":"The option mentions changes in the distribution of wealth.","zh":"該選項提到財富分配的改變。"},{"en":"Distribution of wealth means how money, property, and resources are shared across society.","zh":"distribution of wealth 指金錢、財產和資源在社會中如何分配。"},{"en":"A country with unequal distribution of wealth may have luxury homes beside poor housing.","zh":"財富分配不平等的國家，可能有豪宅與貧困住房並列。"},{"en":"If the distribution of wealth improves, more people can afford comfort and mobility.","zh":"如果財富分配改善，更多人可以負擔舒適和流動能力。"},{"en":"The phrase focuses on who has economic resources.","zh":"這個片語集中於誰擁有經濟資源。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":21},{"front":"air transport","meaning":"航空交通","examples":[{"en":"Air transport may become safer through improved technology.","zh":"航空交通可能透過改良科技變得更安全。"},{"en":"Air transport means travel or movement of goods by aircraft.","zh":"air transport 指透過飛機運送人或貨物。"},{"en":"Air transport helps people cross long distances faster than road or sea travel.","zh":"航空交通幫助人們比道路或海上旅行更快跨越長距離。"},{"en":"If air transport becomes cheaper and safer, more people may use it regularly.","zh":"如果航空交通變得更便宜和安全，更多人可能定期使用。"},{"en":"The phrase covers planes, air taxis, cargo flights, and related systems.","zh":"這個片語涵蓋飛機、空中的士、貨運航班和相關系統。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":21},{"front":"new types of aircraft","meaning":"新型飛機","examples":[{"en":"The option mentions new types of aircraft.","zh":"該選項提到新型飛機。"},{"en":"New types of aircraft are newly designed flying vehicles with different technology, size, or purpose.","zh":"new types of aircraft 是具有不同科技、大小或用途的新設計飛行器。"},{"en":"Electric air taxis could be new types of aircraft for short city journeys.","zh":"電動空中的士可以是用於城市短途旅程的新型飛機。"},{"en":"If new types of aircraft are safer and cheaper, personal air travel may expand.","zh":"如果新型飛機更安全和便宜，個人航空旅行可能擴大。"},{"en":"The phrase focuses on aircraft innovation.","zh":"這個片語集中於飛機創新。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":21},{"front":"better training methods","meaning":"更好的訓練方法","examples":[{"en":"The option mentions better training methods for pilots.","zh":"該選項提到飛機師更好的訓練方法。"},{"en":"Better training methods are improved ways of teaching people skills and safe behaviour.","zh":"better training methods 是教授技能和安全行為的改良方式。"},{"en":"Driving schools use better training methods when they add simulation and feedback.","zh":"駕駛學校加入模擬和回饋時，就是使用更好的訓練方法。"},{"en":"If pilots receive better training methods, some human errors may decrease.","zh":"如果飛機師接受更好的訓練方法，一些人為錯誤可能減少。"},{"en":"The phrase focuses on improving how people learn to perform a task.","zh":"這個片語集中於改善人們學習執行任務的方式。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":22},{"front":"three-dimensional models","meaning":"三維模型","examples":[{"en":"The option mentions three-dimensional models.","zh":"該選項提到三維模型。"},{"en":"Three-dimensional models are representations with height, width, and depth.","zh":"three-dimensional models 是具有高度、寬度和深度的模型。"},{"en":"Architecture students use three-dimensional models to understand buildings before construction.","zh":"建築學生在施工前使用三維模型理解建築物。"},{"en":"If pilots train with three-dimensional models, they may understand space and movement better.","zh":"如果飛機師用三維模型訓練，可能更理解空間和移動。"},{"en":"The phrase refers to models that show objects in 3D form.","zh":"這個片語指以3D形式呈現物件的模型。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":22},{"front":"improved technology","meaning":"改良科技","examples":[{"en":"Improved technology may make air transport safer.","zh":"改良科技可能令航空交通更安全。"},{"en":"Improved technology means tools, machines, or systems that have become better than before.","zh":"improved technology 指比以前更好的工具、機器或系統。"},{"en":"Improved technology in cars can warn drivers before a collision.","zh":"汽車中的改良科技可以在碰撞前提醒司機。"},{"en":"If improved technology controls aircraft more accurately, accidents may decrease.","zh":"如果改良科技能更準確控制飛機，意外可能減少。"},{"en":"The phrase links technical progress with better performance.","zh":"這個片語把技術進步與更好表現連接起來。"}],"source":"106 - Worldly Wealth.pdf","sourcePage":22}],"ielts/reading/passage-2/Practice 107":[{"front":"natural choice","meaning":"自然之選","examples":[{"en":"The article presents shade-grown coffee as a natural choice for conservation-minded consumers.","zh":"文章把蔭下種植咖啡呈現為有保育意識消費者的自然之選。"},{"en":"A natural choice is an option that seems sensible or suitable because it fits the person’s values or needs.","zh":"「natural choice」是因符合某人的價值觀或需要而顯得合理或合適的選擇。"},{"en":"For a student who loves children, teaching may feel like a natural choice.","zh":"對喜歡孩子的學生來說，教學可能感覺是自然之選。"},{"en":"If a product protects wildlife, it becomes a natural choice for people who care about conservation.","zh":"如果一種產品保護野生動物，它就成為關心保育人士的自然之選。"},{"en":"The phrase suggests that the choice feels obvious, not forced.","zh":"這個短語暗示選擇感覺明顯合理，而不是被迫作出。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":1},{"front":"the connection between","meaning":"……之間的關係","examples":[{"en":"The article asks about the connection between coffee, birds and tree shade.","zh":"文章探問咖啡、鳥類和樹蔭之間的關係。"},{"en":"The connection between things is the way they are related or affect one another.","zh":"「the connection between」幾件事，指它們如何相關或互相影響。"},{"en":"A teacher may explain the connection between sleep and exam performance.","zh":"老師可能解釋睡眠與考試表現之間的關係。"},{"en":"If coffee farms provide tree shade, there may be a connection between farming and bird survival.","zh":"如果咖啡農場提供樹蔭，耕作與鳥類生存之間可能有關係。"},{"en":"This phrase helps readers link ideas that may seem separate at first.","zh":"這個短語幫助讀者把起初看似分開的概念連繫起來。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":1},{"front":"morning coffee","meaning":"早晨咖啡","examples":[{"en":"Your morning coffee may be connected to the survival of migratory birds.","zh":"你的早晨咖啡可能與候鳥的生存有關。"},{"en":"Morning coffee means the coffee someone drinks in the morning, often as part of a daily routine.","zh":"「morning coffee」指某人在早上喝的咖啡，通常是日常習慣的一部分。"},{"en":"Many office workers start the day with morning coffee before checking emails.","zh":"許多辦公室員工在查看電郵前，以早晨咖啡開始一天。"},{"en":"If morning coffee comes from wildlife-friendly farms, a daily habit may support conservation.","zh":"如果早晨咖啡來自野生動物友善農場，一個日常習慣也可能支持保育。"},{"en":"The phrase turns an ordinary drink into something with wider environmental meaning.","zh":"這個短語把普通飲品轉化為具有更大環境意義的事物。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":1},{"front":"wintering North American birds","meaning":"越冬的北美鳥類","examples":[{"en":"Shade-coffee forests provide refuge for wintering North American birds.","zh":"蔭下咖啡森林為越冬的北美鳥類提供庇護。"},{"en":"Wintering North American birds are birds from North America that spend the winter in another region.","zh":"「wintering North American birds」是來自北美、在另一地區過冬的鳥類。"},{"en":"Some birds fly south each year because food is easier to find during winter.","zh":"有些鳥每年南飛，因為冬季在那裡較容易找到食物。"},{"en":"If wintering birds lose safe habitats, their survival during migration may be threatened.","zh":"如果越冬鳥類失去安全棲息地，它們在遷徙期間的生存可能受威脅。"},{"en":"The phrase focuses on where birds stay during the colder months.","zh":"這個短語集中於鳥類在較寒冷月份停留的地方。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":1},{"front":"the cool shade of a tree","meaning":"樹下涼蔭","examples":[{"en":"Coffee plants can grow under the cool shade of a tree.","zh":"咖啡樹可以在樹下涼蔭中生長。"},{"en":"The cool shade of a tree is the cooler area protected from direct sunlight by its leaves and branches.","zh":"「the cool shade of a tree」是被樹葉和樹枝遮擋直射陽光而較涼爽的地方。"},{"en":"Children may rest under the cool shade of a tree on a hot school day.","zh":"在炎熱上課日，孩子可能在樹下涼蔭中休息。"},{"en":"If coffee plants grow under shade, the farm can also provide habitat for insects and birds.","zh":"如果咖啡樹在蔭下生長，農場也可以為昆蟲和鳥類提供棲息地。"},{"en":"The phrase suggests protection from heat and strong sunlight.","zh":"這個短語暗示免受高溫和強烈陽光直接照射的保護。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":1},{"front":"quite a lot","meaning":"相當多；很有關係","examples":[{"en":"There is quite a lot of connection between coffee farming and wildlife.","zh":"咖啡耕作與野生動物之間有相當多關係。"},{"en":"Quite a lot means a fairly large amount or degree.","zh":"「quite a lot」意思是數量或程度相當大。"},{"en":"There is quite a lot of traffic near the school at 8 a.m.","zh":"早上八時學校附近有相當多車流。"},{"en":"If a farm supports many birds and insects, it has quite a lot of ecological value.","zh":"如果農場支持許多鳥類和昆蟲，它就有相當多生態價值。"},{"en":"The phrase is stronger than “a little” but less exact than a number.","zh":"這個短語比「少量」更強，但不像數字那樣精確。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":1},{"front":"scientists from","meaning":"來自……的科學家","examples":[{"en":"Scientists from London’s Natural History Museum studied coffee farms in El Salvador.","zh":"來自倫敦自然歷史博物館的科學家研究了薩爾瓦多的咖啡農場。"},{"en":"Scientists from a place are researchers connected with that institution or location.","zh":"「scientists from」某地，是與該機構或地點有關的研究人員。"},{"en":"Scientists from a university may visit farms to collect soil samples.","zh":"來自大學的科學家可能到農場收集泥土樣本。"},{"en":"If scientists from a museum study biodiversity, their findings can support conservation work.","zh":"如果來自博物館的科學家研究生物多樣性，他們的發現可以支持保育工作。"},{"en":"The phrase identifies where the researchers come from or work.","zh":"這個短語指出研究人員來自哪裡或在哪裡工作。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":1},{"front":"Natural History Museum","meaning":"自然歷史博物館","examples":[{"en":"Researchers from the Natural History Museum visited coffee farms in Central America.","zh":"來自自然歷史博物館的研究人員到訪中美洲的咖啡農場。"},{"en":"A Natural History Museum studies and displays plants, animals, fossils and the natural world.","zh":"「Natural History Museum」研究並展示植物、動物、化石和自然世界。"},{"en":"Students may visit a natural history museum to learn about insects, birds and forests.","zh":"學生可能參觀自然歷史博物館，以學習昆蟲、鳥類和森林。"},{"en":"If museum researchers study farms, they may discover how agriculture affects wildlife.","zh":"如果博物館研究人員研究農場，他們可能發現農業如何影響野生動物。"},{"en":"The phrase names an institution linked to scientific collections and biodiversity research.","zh":"這個短語指出與科學收藏和生物多樣性研究相關的機構。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":1},{"front":"descend on","meaning":"突然到訪；大批來到","examples":[{"en":"Scientists descended on the coffee farms of El Salvador.","zh":"科學家突然大批來到薩爾瓦多的咖啡農場。"},{"en":"To descend on a place means to arrive there suddenly or in large numbers.","zh":"「descend on」某地，意思是突然或大批到達那裡。"},{"en":"Reporters descended on the school after the student won a national prize.","zh":"那名學生贏得全國獎項後，記者大批來到學校。"},{"en":"When researchers descend on a farm, they may collect data intensively over a short period.","zh":"當研究人員大批到訪農場，他們可能在短時間內密集收集數據。"},{"en":"The phrase often suggests a noticeable arrival of many people.","zh":"這個短語常暗示許多人明顯地到達。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":1},{"front":"coffee farms","meaning":"咖啡農場","examples":[{"en":"The researchers studied coffee farms in El Salvador.","zh":"研究人員研究了薩爾瓦多的咖啡農場。"},{"en":"Coffee farms are farms where coffee plants are grown and harvested.","zh":"「coffee farms」是種植和收成咖啡樹的農場。"},{"en":"Workers on coffee farms may pick coffee cherries by hand during harvest season.","zh":"咖啡農場的工人可能在收成季節用手採摘咖啡果。"},{"en":"If coffee farms keep shade trees, they can support more wildlife than bare fields.","zh":"如果咖啡農場保留遮蔭樹，它們可以比裸露田地支持更多野生動物。"},{"en":"The phrase refers to places that produce coffee, not cafés.","zh":"這個短語指生產咖啡的地方，而不是咖啡店。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":1},{"front":"tiny Central American republic","meaning":"中美洲小共和國","examples":[{"en":"El Salvador is described as a tiny Central American republic.","zh":"薩爾瓦多被描述為一個中美洲小共和國。"},{"en":"A tiny Central American republic is a small independent country in Central America.","zh":"「tiny Central American republic」是位於中美洲的小型獨立國家。"},{"en":"A geography lesson may compare a tiny republic with much larger neighbouring countries.","zh":"地理課可能把一個小共和國與大得多的鄰國比較。"},{"en":"If a small country loses natural forest, each remaining habitat may become especially important.","zh":"如果小國失去天然森林，每個剩餘棲息地都可能變得特別重要。"},{"en":"The phrase gives both size and political location.","zh":"這個短語同時提供大小和政治地理位置。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":1},{"front":"El Salvador","meaning":"薩爾瓦多","examples":[{"en":"El Salvador has lost much of its natural forest.","zh":"薩爾瓦多已失去大部分天然森林。"},{"en":"El Salvador is a country in Central America.","zh":"「El Salvador」是中美洲的一個國家。"},{"en":"A report about El Salvador may discuss coffee farming, forests and biodiversity.","zh":"關於薩爾瓦多的報告可能討論咖啡耕作、森林和生物多樣性。"},{"en":"If El Salvador loses forest, shade-grown farms may become more important for wildlife.","zh":"如果薩爾瓦多失去森林，蔭下種植農場對野生動物可能變得更重要。"},{"en":"The name gives the national setting of the research.","zh":"這個名稱提供研究的國家背景。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":2},{"front":"be astonished to find","meaning":"驚訝地發現","examples":[{"en":"The scientists were astonished to find great species diversity.","zh":"科學家驚訝地發現高度物種多樣性。"},{"en":"To be astonished to find something means to be very surprised when discovering it.","zh":"「be astonished to find」某事，意思是在發現它時非常驚訝。"},{"en":"A teacher was astonished to find that every student had finished the difficult homework.","zh":"老師驚訝地發現每位學生都完成了困難功課。"},{"en":"If researchers expect few species but find many, they may be astonished by the result.","zh":"如果研究人員預期物種很少，卻找到很多，他們可能對結果感到驚訝。"},{"en":"The phrase expresses strong surprise caused by new evidence.","zh":"這個短語表達由新證據引起的強烈驚訝。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":2},{"front":"diversity of insect and plant species","meaning":"昆蟲及植物物種多樣性","examples":[{"en":"The farms contained remarkable diversity of insect and plant species.","zh":"這些農場包含顯著的昆蟲及植物物種多樣性。"},{"en":"Diversity of insect and plant species means many different kinds of insects and plants living in one place.","zh":"「diversity of insect and plant species」指一個地方生活着許多不同種類的昆蟲和植物。"},{"en":"A school garden with flowers, trees and vegetables may support insect and plant diversity.","zh":"種有花、樹和蔬菜的學校花園，可能支持昆蟲和植物多樣性。"},{"en":"When farms contain many species, they may become healthier habitats for birds and other animals.","zh":"當農場包含許多物種，它們可能成為鳥類和其他動物更健康的棲息地。"},{"en":"The phrase describes biological variety.","zh":"這個短語描述生物種類的豐富程度。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":2},{"front":"during 18 months’ work","meaning":"在18個月的工作期間","examples":[{"en":"During 18 months’ work, the scientists studied 12 farms.","zh":"在18個月的工作期間，科學家研究了12個農場。"},{"en":"During 18 months’ work means over a period of one and a half years of research or activity.","zh":"「during 18 months’ work」意思是在一年半的研究或活動期間。"},{"en":"During six months’ work, a student may collect enough data for a project.","zh":"在六個月的工作期間，學生可能收集到足夠數據完成項目。"},{"en":"If scientists study farms for 18 months, their findings may include seasonal changes.","zh":"如果科學家研究農場18個月，他們的發現可能包括季節變化。"},{"en":"The phrase gives the length of the research period.","zh":"這個短語說明研究期長度。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":2},{"front":"a third more","meaning":"多三分之一","examples":[{"en":"They found a third more species of parasitic wasp than expected.","zh":"他們找到的寄生蜂物種比預期多三分之一。"},{"en":"A third more means about 33 percent more than the original amount or expectation.","zh":"「a third more」意思是比原本數量或預期多約百分之三十三。"},{"en":"If a class expected 30 students but got a third more, about 40 students arrived.","zh":"如果班級預期有30名學生，但多三分之一，大約有40名學生到達。"},{"en":"Finding a third more species than expected suggests the habitat is richer than researchers thought.","zh":"找到比預期多三分之一的物種，顯示棲息地比研究人員想像中更豐富。"},{"en":"The phrase gives a proportional increase.","zh":"這個短語提供比例上的增加。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":2},{"front":"species of","meaning":"……的物種","examples":[{"en":"The researchers found many species of tree on the farms.","zh":"研究人員在農場上找到許多樹木物種。"},{"en":"Species of something means different biological kinds within a larger group.","zh":"「species of」某類生物，意思是在較大群體中的不同生物種類。"},{"en":"A park may contain several species of bird, such as sparrows, pigeons and egrets.","zh":"公園可能有幾種鳥類，例如麻雀、鴿子和白鷺。"},{"en":"If a farm has many species of tree, it can provide different food and shelter for wildlife.","zh":"如果農場有許多樹木物種，它可以為野生動物提供不同食物和庇護。"},{"en":"The phrase is used to classify living things.","zh":"這個短語用於分類生物。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":2},{"front":"parasitic wasp","meaning":"寄生蜂","examples":[{"en":"The team found many species of parasitic wasp.","zh":"團隊找到許多寄生蜂物種。"},{"en":"A parasitic wasp is a small wasp whose young develop by living on or inside another insect.","zh":"「parasitic wasp」是一種小蜂，其幼蟲靠生活在另一昆蟲身上或體內發育。"},{"en":"Farmers may value parasitic wasps because they can help control crop pests naturally.","zh":"農民可能重視寄生蜂，因為牠們可以自然控制作物害蟲。"},{"en":"If parasitic wasps depend on specific trees, losing trees may reduce their numbers.","zh":"如果寄生蜂依賴特定樹木，失去樹木可能減少牠們的數量。"},{"en":"The phrase names an insect with an important ecological role.","zh":"這個短語指出具有重要生態作用的昆蟲。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":2},{"front":"be known to exist","meaning":"已知存在","examples":[{"en":"More species were found than were known to exist in Costa Rica.","zh":"發現的物種比哥斯達黎加已知存在的還要多。"},{"en":"To be known to exist means to have been officially recorded or recognised as existing.","zh":"「be known to exist」意思是已被正式記錄或確認存在。"},{"en":"A bird may be known to exist in one valley but not yet recorded in another.","zh":"一種鳥可能已知存在於某山谷，但尚未在另一山谷有記錄。"},{"en":"If researchers find more species than were known to exist before, scientific records may need updating.","zh":"如果研究人員發現比以往已知存在更多的物種，科學記錄可能需要更新。"},{"en":"The phrase focuses on documented knowledge, not total reality.","zh":"這個短語集中於已記錄知識，而不是全部現實。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":2},{"front":"in the whole country of","meaning":"在整個……國家","examples":[{"en":"The number exceeded those known in the whole country of Costa Rica.","zh":"該數量超過整個哥斯達黎加已知的數量。"},{"en":"In the whole country of a place means across the entire nation.","zh":"「in the whole country of」某地，意思是在整個國家範圍內。"},{"en":"A small town may have more libraries than some people expect in the whole country of a smaller nation.","zh":"一個小鎮擁有的圖書館數量，可能比一些人預期某個小國全國的還多。"},{"en":"If one set of farms has more species than a whole country’s known records, the discovery is striking.","zh":"如果一組農場的物種數量超過一個國家的已知記錄，這項發現就很驚人。"},{"en":"The phrase emphasises national scale.","zh":"這個短語強調國家規模。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":2},{"front":"describe new species","meaning":"描述新物種","examples":[{"en":"The scientists described four new species.","zh":"科學家描述了四個新物種。"},{"en":"To describe new species means to formally identify and record species not previously recognised by science.","zh":"「describe new species」意思是正式識別並記錄科學界之前未確認的物種。"},{"en":"Museum researchers may describe new species after comparing body features and DNA.","zh":"博物館研究人員可能在比較身體特徵和 DNA 後描述新物種。"},{"en":"If scientists describe a new species, it can be added to scientific records.","zh":"如果科學家描述一個新物種，它可以被加入科學記錄。"},{"en":"The phrase is a technical use of “describe”, not just casual explanation.","zh":"這裡的 describe 是技術用法，不只是普通解釋。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":2},{"front":"be aware of","meaning":"知道；察覺到","examples":[{"en":"The researchers were aware of a fifth new species.","zh":"研究人員知道還有第五個新物種。"},{"en":"To be aware of something means to know that it exists or is happening.","zh":"「be aware of」某事，意思是知道它存在或正在發生。"},{"en":"A teacher should be aware of students who are quietly struggling.","zh":"老師應察覺到正在默默吃力的學生。"},{"en":"If researchers are aware of a new species but lack full evidence, they may need more study.","zh":"如果研究人員知道有新物種但缺乏完整證據，他們可能需要更多研究。"},{"en":"The phrase means knowing or noticing, not necessarily proving completely.","zh":"這個短語表示知道或察覺，不一定是完全證明。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":2},{"front":"nearly 300 species of tree","meaning":"近300種樹木","examples":[{"en":"The scientists found nearly 300 species of tree on 24 farms.","zh":"科學家在24個農場上找到近300種樹木。"},{"en":"Nearly 300 species of tree means almost 300 different kinds of trees.","zh":"「nearly 300 species of tree」意思是接近300種不同樹木。"},{"en":"A large botanical garden may contain nearly 300 species of tree for study and display.","zh":"大型植物園可能收藏近300種樹木作研究和展示。"},{"en":"If farms contain nearly 300 tree species, they may function partly like forest habitats.","zh":"如果農場包含近300種樹木，它們可能部分像森林棲息地一樣運作。"},{"en":"The phrase shows unexpectedly high plant diversity.","zh":"這個短語顯示出乎意料地高的植物多樣性。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":3},{"front":"be expected to find","meaning":"預期會找到","examples":[{"en":"They had expected to find about 100 species of tree.","zh":"他們原本預期會找到約100種樹木。"},{"en":"To be expected to find something means to think it will probably be discovered.","zh":"「be expected to find」某物，意思是認為很可能會發現它。"},{"en":"A student may expect to find simple answers in a short article.","zh":"學生可能預期會在短文章中找到簡單答案。"},{"en":"If scientists find far more than expected, their assumptions may change.","zh":"如果科學家找到遠多於預期的東西，他們的假設可能改變。"},{"en":"The phrase describes prediction before discovery.","zh":"這個短語描述發現之前的預測。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":3},{"front":"natural forest","meaning":"天然森林","examples":[{"en":"El Salvador has lost much of its natural forest.","zh":"薩爾瓦多已失去大部分天然森林。"},{"en":"Natural forest is forest that develops largely through natural processes rather than being planted as a crop.","zh":"「natural forest」是主要透過自然過程形成，而不是作為作物種植的森林。"},{"en":"Natural forest can contain many layers of trees, plants, insects and animals.","zh":"天然森林可以包含多層樹木、植物、昆蟲和動物。"},{"en":"When natural forest is cleared, wildlife may lose food, shelter and breeding sites.","zh":"當天然森林被清除，野生動物可能失去食物、庇護和繁殖地。"},{"en":"The phrase contrasts wild forest with managed plantations.","zh":"這個短語把野生森林與人工管理種植園作對比。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":3},{"front":"cover nearly 10% of","meaning":"覆蓋接近百分之十","examples":[{"en":"Coffee farms cover nearly 10% of El Salvador.","zh":"咖啡農場覆蓋薩爾瓦多接近百分之十。"},{"en":"Cover nearly 10% of a place means occupy almost one tenth of its area.","zh":"「cover nearly 10% of」某地，意思是佔據其面積接近十分之一。"},{"en":"Parks may cover nearly 10% of a city if green spaces are well protected.","zh":"如果綠地受到良好保護，公園可能覆蓋城市接近百分之十。"},{"en":"If coffee farms cover a large area, their farming method can strongly affect biodiversity.","zh":"如果咖啡農場覆蓋大片地區，其耕作方法可以強烈影響生物多樣性。"},{"en":"The phrase describes land area and proportion.","zh":"這個短語描述土地面積和比例。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":3},{"front":"shade-grown method","meaning":"蔭下種植方法","examples":[{"en":"Most coffee farms in El Salvador use the shade-grown method.","zh":"薩爾瓦多大多數咖啡農場使用蔭下種植方法。"},{"en":"The shade-grown method grows crops under trees rather than in open full sunlight.","zh":"「shade-grown method」是在樹下種植作物，而不是在完全開闊的陽光下種植。"},{"en":"A farmer using the shade-grown method may keep tall trees above coffee plants.","zh":"使用蔭下種植方法的農民可能在咖啡樹上方保留高大樹木。"},{"en":"If shade trees remain, farms can support birds, insects and soil health.","zh":"如果遮蔭樹保留下來，農場可以支持鳥類、昆蟲和土壤健康。"},{"en":"The phrase describes a traditional and more habitat-friendly way of farming.","zh":"這個短語描述一種傳統且較有利棲息地的耕作方式。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":3},{"front":"method of production","meaning":"生產方法","examples":[{"en":"Shade-grown farming is a traditional method of production.","zh":"蔭下種植是一種傳統生產方法。"},{"en":"A method of production is the way goods or crops are made or grown.","zh":"「method of production」是製造貨品或種植作物的方式。"},{"en":"Factories may change their method of production to reduce waste.","zh":"工廠可能改變生產方法以減少浪費。"},{"en":"If the method of production changes, the product’s environmental impact may also change.","zh":"如果生產方法改變，產品的環境影響也可能改變。"},{"en":"The phrase focuses on how something is produced.","zh":"這個短語集中於某物如何被生產。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":3},{"front":"utilise","meaning":"利用","examples":[{"en":"The shade-grown method utilises a semi-natural forest ecosystem.","zh":"蔭下種植方法利用半天然森林生態系統。"},{"en":"To utilise something means to use it effectively for a purpose.","zh":"「utilise」某物，意思是有效地把它用於某目的。"},{"en":"A school may utilise empty classrooms for after-school tutoring.","zh":"學校可能利用空課室進行課後補習。"},{"en":"If farmers utilise tree shade, they can grow coffee while preserving habitat.","zh":"如果農民利用樹蔭，他們可以種植咖啡同時保留棲息地。"},{"en":"The word is more formal than “use”.","zh":"這個詞比 use 更正式。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":3},{"front":"semi-natural forest ecosystem","meaning":"半天然森林生態系統","examples":[{"en":"Shade-grown coffee farms utilise a semi-natural forest ecosystem.","zh":"蔭下咖啡農場利用半天然森林生態系統。"},{"en":"A semi-natural forest ecosystem is a forest-like system partly shaped by people but still rich in natural life.","zh":"「semi-natural forest ecosystem」是部分由人類塑造、但仍富含自然生命的類森林系統。"},{"en":"A park with planted trees and wild insects may become a semi-natural habitat.","zh":"一個有種植樹木和野生昆蟲的公園，可能成為半天然棲息地。"},{"en":"If a coffee farm keeps many tree layers, it may work like a semi-natural forest ecosystem.","zh":"如果咖啡農場保留多層樹木，它可能像半天然森林生態系統一樣運作。"},{"en":"The phrase shows that the farm is not completely wild, but not simply bare farmland either.","zh":"這個短語顯示農場不是完全野生，但也不只是裸露農地。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":3},{"front":"botanist on the expedition","meaning":"考察隊中的植物學家","examples":[{"en":"Alex Munro was the museum’s botanist on the expedition.","zh":"Alex Munro 是博物館考察隊中的植物學家。"},{"en":"A botanist on an expedition is a plant scientist who joins a research journey.","zh":"「botanist on the expedition」是參與研究旅程的植物科學家。"},{"en":"A botanist on a field trip may identify trees, flowers and forest layers.","zh":"田野考察中的植物學家可能識別樹木、花朵和森林層次。"},{"en":"If an expedition studies coffee farms, the botanist can explain plant diversity.","zh":"如果考察研究咖啡農場，植物學家可以解釋植物多樣性。"},{"en":"The phrase identifies the plant expert in the research team.","zh":"這個短語指出研究團隊中的植物專家。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":3},{"front":"findings","meaning":"研究發現","examples":[{"en":"The findings amazed the museum’s insect specialist.","zh":"這些研究發現令博物館的昆蟲專家驚訝。"},{"en":"Findings are results or discoveries from research.","zh":"「findings」是研究中的結果或發現。"},{"en":"A doctor may explain the findings of a blood test to a patient.","zh":"醫生可能向病人解釋血液測試的發現。"},{"en":"If research findings are surprising, they may change how people understand a problem.","zh":"如果研究發現令人驚訝，它們可能改變人們對問題的理解。"},{"en":"The word refers to evidence-based results, not guesses.","zh":"這個詞指基於證據的結果，而不是猜測。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":3},{"front":"insect specialist","meaning":"昆蟲專家","examples":[{"en":"The insect specialist was amazed by the biodiversity on the farms.","zh":"昆蟲專家對農場上的生物多樣性感到驚訝。"},{"en":"An insect specialist is an expert who studies insects.","zh":"「insect specialist」是研究昆蟲的專家。"},{"en":"A farmer may ask an insect specialist to identify a pest damaging crops.","zh":"農民可能請昆蟲專家識別破壞作物的害蟲。"},{"en":"If insect specialists find many species, they can explain how healthy a habitat is.","zh":"如果昆蟲專家發現許多物種，他們可以解釋棲息地有多健康。"},{"en":"The phrase refers to a trained expert, not someone who simply likes insects.","zh":"這個短語指受訓專家，而不只是喜歡昆蟲的人。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":3},{"front":"sophisticated food web","meaning":"複雜的食物網","examples":[{"en":"The farms contained a very sophisticated food web.","zh":"這些農場包含非常複雜的食物網。"},{"en":"A sophisticated food web is a complex network of organisms feeding on and depending on one another.","zh":"「sophisticated food web」是生物互相取食和依賴的複雜網絡。"},{"en":"A pond has a food web when algae, insects, fish and birds all affect one another.","zh":"當藻類、昆蟲、魚類和鳥類互相影響時，池塘就有食物網。"},{"en":"If one species disappears from a food web, other species may also be affected.","zh":"如果食物網中一個物種消失，其他物種也可能受影響。"},{"en":"The phrase shows ecological complexity, not just a simple food chain.","zh":"這個短語顯示生態複雜性，而不只是簡單食物鏈。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":4},{"front":"for instance","meaning":"例如","examples":[{"en":"The wasps, for instance, may depend on specific trees.","zh":"例如，這些蜂可能依賴特定樹木。"},{"en":"For instance introduces an example.","zh":"「for instance」用來引入例子。"},{"en":"Some school rules are useful; for instance, quiet reading time helps students concentrate.","zh":"有些校規很有用；例如，安靜閱讀時間幫助學生專注。"},{"en":"If a writer gives an example, readers can understand the general point more easily.","zh":"如果作者提供例子，讀者可以更容易理解一般觀點。"},{"en":"The phrase has a similar meaning to “for example”.","zh":"這個短語與 “for example” 意思相近。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":4},{"front":"depend on","meaning":"依賴","examples":[{"en":"Some wasps may depend on specific species of tree.","zh":"有些蜂可能依賴特定種類的樹木。"},{"en":"To depend on something means to need it in order to survive, work or succeed.","zh":"「depend on」某物，意思是需要它才能生存、運作或成功。"},{"en":"Students depend on clear instructions when preparing for an exam.","zh":"學生準備考試時依賴清楚指示。"},{"en":"If insects depend on certain trees, cutting those trees may harm the insects.","zh":"如果昆蟲依賴某些樹木，砍伐那些樹可能傷害昆蟲。"},{"en":"The phrase shows reliance.","zh":"這個短語顯示依靠關係。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":4},{"front":"specific species of","meaning":"特定種類的……","examples":[{"en":"The wasps may depend on specific species of tree.","zh":"這些蜂可能依賴特定種類的樹木。"},{"en":"Specific species of something means particular biological kinds, not just any kind.","zh":"「specific species of」某物，意思是特定生物種類，而不是任何種類都可以。"},{"en":"Some butterflies lay eggs only on specific species of plant.","zh":"有些蝴蝶只在特定種類的植物上產卵。"},{"en":"If wildlife needs specific tree species, general greenery may not be enough.","zh":"如果野生動物需要特定樹種，一般綠化可能不足夠。"},{"en":"The phrase emphasises exact ecological needs.","zh":"這個短語強調精確的生態需要。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":4},{"front":"the world over","meaning":"世界各地皆然","examples":[{"en":"It is the same the world over for shade-grown coffee.","zh":"對蔭下種植咖啡來說，世界各地皆然。"},{"en":"The world over means everywhere in the world.","zh":"「the world over」意思是在世界各地。"},{"en":"People the world over use phones to communicate with family and work.","zh":"世界各地的人都用電話與家人和工作聯繫。"},{"en":"If shade-grown farms support biodiversity the world over, the pattern is not limited to one country.","zh":"如果蔭下種植農場在世界各地都支持生物多樣性，這個模式就不限於一個國家。"},{"en":"The phrase gives a global scope.","zh":"這個短語提供全球範圍。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":4},{"front":"species diversity","meaning":"物種多樣性","examples":[{"en":"Species diversity is higher where coffee is grown in shade.","zh":"在蔭下種植咖啡的地方，物種多樣性較高。"},{"en":"Species diversity means the variety of different species in a place.","zh":"「species diversity」指一個地方不同物種的多樣程度。"},{"en":"A healthy wetland may have high species diversity, with birds, insects, fish and plants.","zh":"健康濕地可能有高物種多樣性，包括鳥類、昆蟲、魚類和植物。"},{"en":"If farming removes trees, species diversity may fall because fewer habitats remain.","zh":"如果農業移除樹木，因剩下棲息地較少，物種多樣性可能下降。"},{"en":"The phrase measures ecological richness.","zh":"這個短語量度生態豐富程度。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":4},{"front":"shade conditions","meaning":"蔭下環境","examples":[{"en":"Species diversity is higher in shade conditions.","zh":"在蔭下環境中，物種多樣性較高。"},{"en":"Shade conditions are environments where plants receive filtered or reduced sunlight.","zh":"「shade conditions」是植物接受被過濾或較少陽光的環境。"},{"en":"Some garden plants grow better in shade conditions than in direct midday sun.","zh":"有些園藝植物在蔭下環境比在正午直射陽光下長得更好。"},{"en":"If shade conditions remain on farms, insects and birds may find cooler habitat.","zh":"如果農場保留蔭下環境，昆蟲和鳥類可能找到較涼爽棲息地。"},{"en":"The phrase describes the light environment, not complete darkness.","zh":"這個短語描述光照環境，而不是完全黑暗。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":4},{"front":"in addition","meaning":"此外","examples":[{"en":"In addition, coffee and chocolate are often grown in rainforest regions.","zh":"此外，咖啡和朱古力常在雨林地區種植。"},{"en":"In addition means also or as another point.","zh":"「in addition」意思是此外、另外或作為另一點。"},{"en":"The school built a new library; in addition, it hired more reading teachers.","zh":"學校建了新圖書館；此外，它聘請了更多閱讀老師。"},{"en":"If an argument adds another reason, “in addition” helps connect the ideas smoothly.","zh":"如果論點加入另一個理由，in addition 能幫助順暢連接想法。"},{"en":"The phrase signals extra information.","zh":"這個短語表示額外資料。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":4},{"front":"tropical rainforest","meaning":"熱帶雨林","examples":[{"en":"Coffee and cocoa are often grown in tropical rainforest regions.","zh":"咖啡和可可常在熱帶雨林地區種植。"},{"en":"A tropical rainforest is a hot, wet forest near the equator with very high biodiversity.","zh":"「tropical rainforest」是赤道附近炎熱潮濕、擁有很高生物多樣性的森林。"},{"en":"Tropical rainforests often contain many trees, insects, birds and mammals.","zh":"熱帶雨林常包含許多樹木、昆蟲、鳥類和哺乳動物。"},{"en":"If farming expands into tropical rainforest, many species may lose habitat.","zh":"如果農業擴展到熱帶雨林，許多物種可能失去棲息地。"},{"en":"The phrase describes one of the richest ecosystems on Earth.","zh":"這個短語描述地球上最豐富的生態系統之一。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":4},{"front":"biodiversity hotspots","meaning":"生物多樣性熱點","examples":[{"en":"Tropical rainforest regions are biodiversity hotspots.","zh":"熱帶雨林地區是生物多樣性熱點。"},{"en":"Biodiversity hotspots are areas with many species, often including species found nowhere else.","zh":"「biodiversity hotspots」是擁有許多物種的地區，常包括其他地方沒有的物種。"},{"en":"Coral reefs and rainforests can be biodiversity hotspots because they support many life forms.","zh":"珊瑚礁和雨林可以是生物多樣性熱點，因為它們支持許多生命形式。"},{"en":"If a biodiversity hotspot is damaged, global species loss can increase.","zh":"如果生物多樣性熱點受損，全球物種流失可能增加。"},{"en":"The phrase marks places that are especially important for conservation.","zh":"這個短語標示對保育特別重要的地方。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":4},{"front":"support up to","meaning":"支持高達……","examples":[{"en":"These habitats support up to 70% of the planet’s species.","zh":"這些棲息地支持地球物種高達70%。"},{"en":"Support up to means provide conditions for as much as a certain maximum amount.","zh":"「support up to」意思是提供條件，使最高可達某個數量。"},{"en":"A classroom can support up to 30 students if there are enough seats.","zh":"如果有足夠座位，一間課室可以容納高達30名學生。"},{"en":"If a habitat supports up to 70% of species, losing it would have huge consequences.","zh":"如果棲息地支持高達70%的物種，失去它會帶來巨大後果。"},{"en":"The phrase gives a maximum possible level.","zh":"這個短語提供最高可能水平。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":4},{"front":"plant and animal species","meaning":"動植物物種","examples":[{"en":"Rainforest habitats support many plant and animal species.","zh":"雨林棲息地支持許多動植物物種。"},{"en":"Plant and animal species means different kinds of plants and animals.","zh":"「plant and animal species」指不同種類的植物和動物。"},{"en":"A nature reserve may protect plant and animal species such as trees, birds and insects.","zh":"自然保護區可能保護樹木、鳥類和昆蟲等動植物物種。"},{"en":"If farming removes forest layers, both plant and animal species may decline.","zh":"如果農業移除森林層次，動植物物種都可能下降。"},{"en":"The phrase includes living things from both major groups.","zh":"這個短語包括兩大類生物。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":5},{"front":"production methods","meaning":"生產方法","examples":[{"en":"The production methods of coffee and cocoa affect biodiversity.","zh":"咖啡和可可的生產方法影響生物多樣性。"},{"en":"Production methods are the ways products are grown, made or processed.","zh":"「production methods」是產品被種植、製造或加工的方式。"},{"en":"A factory may change production methods to reduce pollution and save energy.","zh":"工廠可能改變生產方法以減少污染和節省能源。"},{"en":"If coffee production methods remove shade trees, bird diversity may fall.","zh":"如果咖啡生產方法移除遮蔭樹，鳥類多樣性可能下降。"},{"en":"The phrase focuses on how production happens.","zh":"這個短語集中於生產如何發生。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":5},{"front":"cocoa and coffee","meaning":"可可和咖啡","examples":[{"en":"The production methods of cocoa and coffee can affect wildlife.","zh":"可可和咖啡的生產方法可以影響野生動物。"},{"en":"Cocoa and coffee are tropical crops used to make chocolate and coffee drinks.","zh":"「cocoa and coffee」是用來製作朱古力和咖啡飲品的熱帶作物。"},{"en":"Shops sell cocoa and coffee products that may come from farms with very different environmental effects.","zh":"商店售賣的可可和咖啡產品，可能來自環境影響很不同的農場。"},{"en":"If cocoa and coffee are grown under shade, their farms may support more wildlife.","zh":"如果可可和咖啡在蔭下種植，其農場可能支持更多野生動物。"},{"en":"The phrase connects two everyday products with farming and conservation.","zh":"這個短語把兩種日常產品與農業和保育連繫起來。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":5},{"front":"have a significant impact","meaning":"有重大影響","examples":[{"en":"Coffee production can have a significant impact on wildlife.","zh":"咖啡生產可以對野生動物有重大影響。"},{"en":"To have a significant impact means to affect something in an important or noticeable way.","zh":"「have a significant impact」意思是以重要或明顯的方式影響某事。"},{"en":"A new bus route can have a significant impact on students who live far from school.","zh":"新巴士路線可以對住得離學校很遠的學生有重大影響。"},{"en":"If farming methods change habitats, they can have a significant impact on birds and insects.","zh":"如果耕作方法改變棲息地，它們可以對鳥類和昆蟲有重大影響。"},{"en":"The phrase describes an effect that is not small or trivial.","zh":"這個短語描述不小或不瑣碎的影響。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":5},{"front":"hugely significant","meaning":"極其重大的","examples":[{"en":"The impact of coffee and cocoa farming can be hugely significant.","zh":"咖啡和可可耕作的影響可以極其重大。"},{"en":"Hugely significant means extremely important or very large in effect.","zh":"「hugely significant」意思是極其重要或影響非常大。"},{"en":"A small change in exam policy can be hugely significant for students applying to university.","zh":"考試政策的小改變，對申請大學的學生來說可以極其重大。"},{"en":"If a crop covers large areas of rainforest, its farming method can be hugely significant for wildlife.","zh":"如果一種作物覆蓋大片雨林，其耕作方法對野生動物可以極其重大。"},{"en":"The phrase strongly emphasises importance.","zh":"這個短語強烈強調重要性。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":5},{"front":"what does something mean","meaning":"……是甚麼意思","examples":[{"en":"The article asks what shade-grown means.","zh":"文章問蔭下種植是甚麼意思。"},{"en":"What does something mean asks for the definition or explanation of a word, phrase or idea.","zh":"「what does something mean」是詢問某個字、短語或概念的定義或解釋。"},{"en":"A student may ask what “biodiversity” means before reading a science passage.","zh":"學生在閱讀科學文章前，可能問 “biodiversity” 是甚麼意思。"},{"en":"If readers do not know what shade-grown means, they may not understand the environmental argument.","zh":"如果讀者不知道蔭下種植是甚麼意思，他們可能不理解環境論點。"},{"en":"The phrase introduces a request for meaning.","zh":"這個短語引出對意思的提問。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":5},{"front":"be good for wildlife","meaning":"對野生動物有益","examples":[{"en":"Shade-grown coffee can be good for wildlife.","zh":"蔭下種植咖啡可以對野生動物有益。"},{"en":"To be good for wildlife means to help wild animals survive, feed, breed or find shelter.","zh":"「be good for wildlife」意思是幫助野生動物生存、覓食、繁殖或找到庇護。"},{"en":"A park with native trees can be good for wildlife because birds and insects can live there.","zh":"有本地樹木的公園可以對野生動物有益，因為鳥類和昆蟲可以在那裡生活。"},{"en":"If farms keep tree cover, they may be good for wildlife as well as food production.","zh":"如果農場保留樹冠覆蓋，它們可能既生產食物，又對野生動物有益。"},{"en":"The phrase describes a positive effect on wild living things.","zh":"這個短語描述對野生生物的正面影響。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":5},{"front":"poor farmers","meaning":"貧困農民","examples":[{"en":"Most of the world’s coffee is produced by poor farmers.","zh":"世界上大部分咖啡由貧困農民生產。"},{"en":"Poor farmers are farmers with limited money, land, equipment or market power.","zh":"「poor farmers」是金錢、土地、設備或市場力量有限的農民。"},{"en":"Poor farmers may struggle to pay workers or invest in better farming methods.","zh":"貧困農民可能難以支付工人工資或投資更好耕作方法。"},{"en":"If prices collapse, poor farmers are often hit hardest because they have little financial protection.","zh":"如果價格崩潰，貧困農民通常受打擊最大，因為他們幾乎沒有財務保障。"},{"en":"The phrase describes economic vulnerability, not lack of effort.","zh":"這個短語描述經濟脆弱，而不是缺乏努力。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":5},{"front":"the developing world","meaning":"發展中國家","examples":[{"en":"Many coffee farmers live in the developing world.","zh":"許多咖啡農民生活在發展中國家。"},{"en":"The developing world refers to countries or regions with lower average income and less industrial development.","zh":"「the developing world」指平均收入較低、工業發展較少的國家或地區。"},{"en":"Farmers in the developing world may face weaker roads, lower prices and fewer financial services.","zh":"發展中國家的農民可能面對道路較差、價格較低和金融服務較少。"},{"en":"If global crop prices fall, communities in the developing world may suffer quickly.","zh":"如果全球作物價格下跌，發展中國家的社區可能很快受苦。"},{"en":"The phrase is broad and should be used carefully because countries differ greatly.","zh":"這個短語範圍很廣，應小心使用，因為各國差異很大。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":5},{"front":"traditionally","meaning":"傳統上","examples":[{"en":"Farmers have traditionally grown coffee under forest shade.","zh":"農民傳統上在森林蔭下種植咖啡。"},{"en":"Traditionally means according to long-established custom or past practice.","zh":"「traditionally」意思是按照長久建立的習俗或過去做法。"},{"en":"Families traditionally gather for dinner during important festivals.","zh":"家庭傳統上在重要節日時一起吃晚飯。"},{"en":"If coffee was traditionally grown under trees, full-sun farming represents a major change.","zh":"如果咖啡傳統上在樹下種植，全日照耕作就代表重大改變。"},{"en":"The word connects present discussion with older ways of doing things.","zh":"這個詞把當前討論與舊有做法連繫起來。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":5},{"front":"grow something under the shade of","meaning":"在……蔭下種植","examples":[{"en":"Farmers grow coffee under the shade of rainforest trees.","zh":"農民在雨林樹木蔭下種植咖啡。"},{"en":"To grow something under the shade of trees means to cultivate it below tree cover.","zh":"「grow something under the shade of」樹木，意思是在樹冠覆蓋下栽培某物。"},{"en":"Gardeners may grow herbs under the shade of taller plants during hot weather.","zh":"園丁可能在炎熱天氣中，在較高植物蔭下種植香草。"},{"en":"If crops grow under shade, the soil may stay cooler and wetter.","zh":"如果作物在蔭下生長，泥土可能保持較涼和較濕。"},{"en":"The phrase describes both farming position and light conditions.","zh":"這個短語同時描述耕作位置和光照環境。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":5},{"front":"selectively thinned tracts of rainforest","meaning":"經選擇性疏伐的雨林地帶","examples":[{"en":"Coffee is grown under selectively thinned tracts of rainforest.","zh":"咖啡種植在經選擇性疏伐的雨林地帶下。"},{"en":"Selectively thinned tracts of rainforest are areas where some trees are removed while others are kept.","zh":"「selectively thinned tracts of rainforest」是移除部分樹木而保留其他樹木的雨林區域。"},{"en":"A forest path may be selectively thinned so people can walk through without clearing everything.","zh":"森林步道可能被選擇性疏伐，使人可以通過而不清除全部樹木。"},{"en":"If rainforest is selectively thinned, shade can remain while space is made for crops.","zh":"如果雨林被選擇性疏伐，遮蔭可以保留，同時為作物騰出空間。"},{"en":"The phrase describes partial clearing, not total deforestation.","zh":"這個短語描述部分清理，而不是全面砍伐森林。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":6},{"front":"tract of rainforest","meaning":"一片雨林地帶","examples":[{"en":"A tract of rainforest may be thinned for shade-grown farming.","zh":"一片雨林地帶可能被疏伐以進行蔭下種植。"},{"en":"A tract of rainforest is a large area or stretch of rainforest land.","zh":"「tract of rainforest」是一大片或一段雨林土地。"},{"en":"A conservation group may protect a tract of rainforest near a river.","zh":"保育團體可能保護河流附近的一片雨林地帶。"},{"en":"If a tract of rainforest is converted to farming, many species may lose habitat.","zh":"如果一片雨林地帶被改作農業用途，許多物種可能失去棲息地。"},{"en":"The phrase describes an area of land, not a single tree.","zh":"這個短語描述一片土地，而不是單棵樹。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":6},{"front":"genuinely sustainable","meaning":"真正可持續的","examples":[{"en":"Shade-grown farming can be a genuinely sustainable form of farming.","zh":"蔭下種植可以是一種真正可持續的耕作方式。"},{"en":"Genuinely sustainable means truly able to continue without destroying the resources it depends on.","zh":"「genuinely sustainable」意思是真正能持續，而不破壞其依賴的資源。"},{"en":"A school recycling programme is genuinely sustainable only if students use it every day.","zh":"學校回收計劃只有在學生每天使用時，才真正可持續。"},{"en":"If farming protects soil, water and wildlife while supporting farmers, it may be genuinely sustainable.","zh":"如果耕作保護土壤、水和野生動物，同時支持農民，它可能真正可持續。"},{"en":"The phrase suggests real sustainability, not just a green label.","zh":"這個短語暗示真正的可持續性，而不只是環保標籤。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":6},{"front":"form of farming","meaning":"耕作方式","examples":[{"en":"The traditional method is a sustainable form of farming.","zh":"這種傳統方法是一種可持續耕作方式。"},{"en":"A form of farming is a particular way of growing crops or raising animals.","zh":"「form of farming」是一種種植作物或飼養動物的特定方式。"},{"en":"Organic vegetable growing is one form of farming that avoids many synthetic chemicals.","zh":"有機蔬菜種植是一種避免許多合成化學品的耕作方式。"},{"en":"If a form of farming keeps trees and soil healthy, it may protect wildlife too.","zh":"如果一種耕作方式保持樹木和土壤健康，它也可能保護野生動物。"},{"en":"The phrase describes a farming method or system.","zh":"這個短語描述農業方法或系統。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":6},{"front":"leaf fall","meaning":"落葉","examples":[{"en":"Leaf fall from the canopy provides nutrients for the soil.","zh":"樹冠層落葉為土壤提供養分。"},{"en":"Leaf fall is the leaves that drop from trees onto the ground.","zh":"「leaf fall」是從樹上落到地面的葉子。"},{"en":"In a garden, leaf fall can slowly become natural compost.","zh":"在花園中，落葉可以慢慢變成天然堆肥。"},{"en":"If leaf fall stays on the soil, it can return nutrients and protect moisture.","zh":"如果落葉留在泥土上，它可以歸還養分並保持水分。"},{"en":"The phrase describes a natural process that supports soil health.","zh":"這個短語描述支持土壤健康的自然過程。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":6},{"front":"canopy","meaning":"樹冠層","examples":[{"en":"The canopy provides shade, nutrients and habitat.","zh":"樹冠層提供遮蔭、養分和棲息地。"},{"en":"The canopy is the upper layer of branches and leaves formed by trees.","zh":"「canopy」是由樹木枝葉形成的上層。"},{"en":"Birds often nest in the canopy because it gives shelter and food.","zh":"鳥類常在樹冠層築巢，因為那裡提供庇護和食物。"},{"en":"If a farm keeps its canopy, the ground below may stay cooler and richer in life.","zh":"如果農場保留樹冠層，下方地面可能保持較涼且生命更豐富。"},{"en":"The phrase refers to a forest layer above the lower plants.","zh":"這個短語指位於低層植物上方的森林層次。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":6},{"front":"provide a supply of nutrients","meaning":"提供養分","examples":[{"en":"Leaf fall provides a supply of nutrients.","zh":"落葉提供養分。"},{"en":"To provide a supply of nutrients means to give substances that help plants grow.","zh":"「provide a supply of nutrients」意思是提供幫助植物生長的物質。"},{"en":"Compost provides a supply of nutrients for vegetables in a garden.","zh":"堆肥為花園中的蔬菜提供養分。"},{"en":"If fallen leaves break down, they can provide nutrients without chemical fertiliser.","zh":"如果落葉分解，它們可以在不用化學肥料的情況下提供養分。"},{"en":"The phrase connects natural materials with plant growth.","zh":"這個短語把天然材料與植物生長連繫起來。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":6},{"front":"act as a mulch","meaning":"充當覆蓋物","examples":[{"en":"Leaf fall acts as a mulch that suppresses weeds.","zh":"落葉充當抑制雜草的覆蓋物。"},{"en":"To act as a mulch means to cover soil like a protective layer.","zh":"「act as a mulch」意思是像保護層一樣覆蓋泥土。"},{"en":"Gardeners use straw to act as a mulch around young plants.","zh":"園丁使用稻草在幼苗周圍充當覆蓋物。"},{"en":"If leaves act as mulch, they can keep soil moist and reduce weed growth.","zh":"如果樹葉充當覆蓋物，它們可以保持泥土濕潤並減少雜草生長。"},{"en":"The phrase describes one thing functioning like a soil covering.","zh":"這個短語描述某物發揮泥土覆蓋層的作用。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":6},{"front":"suppress weeds","meaning":"抑制雜草","examples":[{"en":"The mulch helps suppress weeds.","zh":"覆蓋物有助抑制雜草。"},{"en":"To suppress weeds means to stop or reduce the growth of unwanted plants.","zh":"「suppress weeds」意思是阻止或減少不需要的植物生長。"},{"en":"Covering soil with cardboard can suppress weeds in a garden bed.","zh":"用紙板覆蓋泥土可以抑制花圃中的雜草。"},{"en":"If weeds are suppressed, crops can get more light, water and nutrients.","zh":"如果雜草被抑制，作物可以得到更多光、水和養分。"},{"en":"The phrase means controlling weeds, not necessarily removing every one by hand.","zh":"這個短語指控制雜草，不一定是用手清除每一棵。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":6},{"front":"live in the canopy","meaning":"生活在樹冠層","examples":[{"en":"Many useful insects live in the canopy.","zh":"許多有用昆蟲生活在樹冠層。"},{"en":"To live in the canopy means to make a home in the upper branches and leaves of trees.","zh":"「live in the canopy」意思是在樹木上層枝葉中生活。"},{"en":"Some birds and insects live in the canopy because food and shelter are found there.","zh":"有些鳥類和昆蟲生活在樹冠層，因為那裡有食物和庇護。"},{"en":"If trees are removed, animals that live in the canopy may lose habitat.","zh":"如果樹木被移除，生活在樹冠層的動物可能失去棲息地。"},{"en":"The phrase describes where organisms live inside a forest structure.","zh":"這個短語描述生物在森林結構中的生活位置。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":6},{"front":"pollinate","meaning":"授粉","examples":[{"en":"Insects in the canopy pollinate cocoa and coffee plants.","zh":"樹冠層中的昆蟲為可可和咖啡植物授粉。"},{"en":"To pollinate means to move pollen so plants can produce fruit or seeds.","zh":"「pollinate」意思是傳送花粉，使植物能產生果實或種子。"},{"en":"Bees pollinate many garden flowers and fruit trees.","zh":"蜜蜂為許多花園花卉和果樹授粉。"},{"en":"If pollinating insects disappear, some crops may produce less fruit.","zh":"如果授粉昆蟲消失，有些作物可能產生較少果實。"},{"en":"The word describes an essential plant reproduction process.","zh":"這個詞描述重要的植物繁殖過程。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":6},{"front":"prey on pests","meaning":"捕食害蟲","examples":[{"en":"Some insects prey on pests that damage crops.","zh":"有些昆蟲捕食破壞作物的害蟲。"},{"en":"To prey on pests means to hunt and eat organisms that harm crops.","zh":"「prey on pests」意思是獵捕並吃掉傷害作物的生物。"},{"en":"Ladybirds prey on aphids in many gardens.","zh":"瓢蟲在許多花園中捕食蚜蟲。"},{"en":"If helpful insects prey on pests, farmers may need fewer chemical sprays.","zh":"如果有益昆蟲捕食害蟲，農民可能需要較少化學噴劑。"},{"en":"The phrase describes natural pest control.","zh":"這個短語描述自然害蟲控制。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":7},{"front":"provide farmers with","meaning":"為農民提供","examples":[{"en":"The trees provide farmers with fruit and wood.","zh":"樹木為農民提供水果和木材。"},{"en":"To provide farmers with something means to give farmers a useful resource or benefit.","zh":"「provide farmers with」某物，意思是給農民有用資源或好處。"},{"en":"A training course can provide farmers with knowledge about soil care.","zh":"培訓課程可以為農民提供土壤護理知識。"},{"en":"If shade trees provide fruit and wood, farmers gain more than coffee from the land.","zh":"如果遮蔭樹提供水果和木材，農民從土地獲得的不只是咖啡。"},{"en":"The phrase shows what farmers receive.","zh":"這個短語顯示農民得到什麼。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":7},{"front":"wood for fuel","meaning":"作燃料的木材","examples":[{"en":"The trees provide wood for fuel.","zh":"樹木提供作燃料的木材。"},{"en":"Wood for fuel is wood used for cooking, heating or producing energy.","zh":"「wood for fuel」是用於煮食、取暖或產生能源的木材。"},{"en":"Rural families may collect wood for fuel when gas or electricity is expensive.","zh":"當煤氣或電力昂貴時，鄉村家庭可能收集作燃料的木材。"},{"en":"If farms provide wood for fuel, trees can have direct household value.","zh":"如果農場提供作燃料的木材，樹木就有直接家庭價值。"},{"en":"The phrase explains one practical use of trees.","zh":"這個短語解釋樹木的一種實際用途。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":7},{"front":"bird diversity","meaning":"鳥類多樣性","examples":[{"en":"Bird diversity is high in shade-grown coffee plantations.","zh":"蔭下咖啡種植園的鳥類多樣性很高。"},{"en":"Bird diversity means the variety of bird species in a place.","zh":"「bird diversity」指一個地方鳥類物種的多樣程度。"},{"en":"A city park with ponds, trees and flowers may have higher bird diversity than a concrete square.","zh":"有池塘、樹木和花朵的城市公園，鳥類多樣性可能高於混凝土廣場。"},{"en":"If farms keep shade trees, bird diversity may increase because there are more nesting and feeding sites.","zh":"如果農場保留遮蔭樹，因為有更多築巢和覓食地點，鳥類多樣性可能增加。"},{"en":"The phrase measures how many different kinds of birds a habitat supports.","zh":"這個短語量度棲息地支持多少不同鳥類。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":7},{"front":"shade-grown coffee plantations","meaning":"蔭下咖啡種植園","examples":[{"en":"Shade-grown coffee plantations can support many bird species.","zh":"蔭下咖啡種植園可以支持許多鳥類物種。"},{"en":"Shade-grown coffee plantations are coffee farms where coffee plants grow under tree cover.","zh":"「shade-grown coffee plantations」是咖啡樹在樹冠覆蓋下生長的咖啡農場。"},{"en":"Visitors to shade-grown plantations may see birds, insects and many tree species.","zh":"到訪蔭下種植園的人可能看到鳥類、昆蟲和許多樹種。"},{"en":"If plantations keep shade trees, they can act partly like forest habitat.","zh":"如果種植園保留遮蔭樹，它們可以部分像森林棲息地一樣運作。"},{"en":"The phrase describes coffee production that maintains overhead vegetation.","zh":"這個短語描述保留上層植被的咖啡生產方式。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":7},{"front":"rival that found in","meaning":"可媲美……中的","examples":[{"en":"Bird diversity in shade-grown plantations rivals that found in natural forests.","zh":"蔭下種植園中的鳥類多樣性可媲美天然森林中的鳥類多樣性。"},{"en":"To rival that found in something means to be almost as good, rich or impressive as it.","zh":"「rival that found in」某地，意思是幾乎與那裡的質素、豐富程度或令人印象深刻程度相當。"},{"en":"A small school’s library may rival that found in a larger private school.","zh":"一所小學校的圖書館可能可媲美較大型私校中的圖書館。"},{"en":"If bird diversity on farms rivals natural forests, the farms have strong conservation value.","zh":"如果農場上的鳥類多樣性可媲美天然森林，這些農場就有強大保育價值。"},{"en":"The phrase makes a comparison showing surprising similarity in quality.","zh":"這個短語透過比較顯示出乎意料的相似質素。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":7},{"front":"natural forests","meaning":"天然森林","examples":[{"en":"Bird diversity on some shade farms rivals that in natural forests.","zh":"一些蔭下農場的鳥類多樣性可媲美天然森林。"},{"en":"Natural forests are forests that grow mainly through natural processes rather than plantation design.","zh":"「natural forests」是主要透過自然過程生長，而不是按種植園設計形成的森林。"},{"en":"Natural forests often contain many tree ages, layers and wildlife habitats.","zh":"天然森林常包含多種樹齡、層次和野生動物棲息地。"},{"en":"If natural forests are replaced by simple plantations, biodiversity may fall sharply.","zh":"如果天然森林被簡單種植園取代，生物多樣性可能急劇下降。"},{"en":"The phrase contrasts original forest ecosystems with managed farmland.","zh":"這個短語把原生森林生態系統與管理農地作對比。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":7},{"front":"in the same region","meaning":"在同一地區","examples":[{"en":"Shade farms may support as many bird species as forests in the same region.","zh":"蔭下農場可能支持與同一地區森林一樣多的鳥類物種。"},{"en":"In the same region means in the same geographical area.","zh":"「in the same region」意思是在同一地理區域。"},{"en":"Schools in the same region may follow similar weather and transport arrangements.","zh":"同一地區的學校可能遵循相似的天氣和交通安排。"},{"en":"If farms and forests in the same region have similar bird diversity, the farming system is important locally.","zh":"如果同一地區的農場和森林有相似鳥類多樣性，該耕作系統在本地就很重要。"},{"en":"The phrase keeps a comparison geographically fair.","zh":"這個短語令比較在地理上更公平。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":7},{"front":"one of the world’s biggest producers of","meaning":"世界最大的……生產國之一","examples":[{"en":"Ghana is one of the world’s biggest producers of cocoa.","zh":"加納是世界最大的可可生產國之一。"},{"en":"One of the world’s biggest producers of something means one of the countries or companies that produces the largest amounts of it.","zh":"「one of the world’s biggest producers of」某物，意思是生產該物最多的國家或公司之一。"},{"en":"China is one of the world’s biggest producers of many manufactured goods.","zh":"中國是世界許多製成品的最大生產國之一。"},{"en":"If a country is a major producer, its farming methods can affect global markets and ecosystems.","zh":"如果一個國家是主要生產國，其耕作方法可以影響全球市場和生態系統。"},{"en":"The phrase describes a leading role in production.","zh":"這個短語描述在生產方面的領先角色。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":7},{"front":"grown under shade","meaning":"在蔭下種植","examples":[{"en":"Much of Ghana’s cocoa is grown under shade.","zh":"加納許多可可是在蔭下種植的。"},{"en":"Grown under shade means cultivated beneath trees or other cover that blocks some sunlight.","zh":"「grown under shade」意思是在樹木或其他遮擋部分陽光的覆蓋下栽培。"},{"en":"Some vegetables are grown under shade cloth during very hot weather.","zh":"在非常炎熱的天氣中，有些蔬菜在遮蔭網下種植。"},{"en":"If cocoa is grown under shade, the farm may keep more trees and wildlife habitat.","zh":"如果可可在蔭下種植，農場可能保留更多樹木和野生動物棲息地。"},{"en":"The phrase describes how the crop receives filtered light.","zh":"這個短語描述作物如何接受被過濾的光線。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":7},{"front":"forest plantations","meaning":"森林種植園","examples":[{"en":"Forest plantations are important habitats for migrant birds.","zh":"森林種植園是候鳥的重要棲息地。"},{"en":"Forest plantations are planted areas with trees, often managed for crops or products.","zh":"「forest plantations」是種植樹木的地區，通常為作物或產品而管理。"},{"en":"A forest plantation may contain coffee, cocoa or timber trees.","zh":"森林種植園可能包含咖啡、可可或木材樹。"},{"en":"If a plantation has varied tree cover, it can provide food and shelter for birds.","zh":"如果種植園有多樣樹冠覆蓋，它可以為鳥類提供食物和庇護。"},{"en":"The phrase describes managed tree-covered land, not necessarily wild forest.","zh":"這個短語描述受管理的樹木覆蓋土地，不一定是野生森林。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":7},{"front":"vital habitat","meaning":"重要棲息地","examples":[{"en":"Shade plantations provide vital habitat for migrant birds.","zh":"蔭下種植園為候鳥提供重要棲息地。"},{"en":"Vital habitat is habitat that is essential for the survival of a species or group.","zh":"「vital habitat」是對某物種或群體生存必不可少的棲息地。"},{"en":"Wetlands are vital habitat for many water birds.","zh":"濕地是許多水鳥的重要棲息地。"},{"en":"If vital habitat is destroyed, animals may not find enough food or safe places to rest.","zh":"如果重要棲息地被破壞，動物可能找不到足夠食物或安全休息地。"},{"en":"The phrase stresses that the habitat is necessary, not just useful.","zh":"這個短語強調該棲息地是必要的，而不只是有用。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":8},{"front":"wintering European migrant birds","meaning":"越冬的歐洲候鳥","examples":[{"en":"Ghana’s cocoa plantations are a vital habitat for wintering European migrant birds.","zh":"加納的可可種植園是越冬的歐洲候鳥的重要棲息地。"},{"en":"Wintering European migrant birds are birds from Europe that spend winter in another region.","zh":"「wintering European migrant birds」是來自歐洲並在另一地區過冬的鳥類。"},{"en":"Some European birds travel to warmer places when food becomes scarce at home.","zh":"當原居地食物變少，有些歐洲鳥類會飛往較溫暖地方。"},{"en":"If wintering habitats disappear, birds may struggle to survive the non-breeding season.","zh":"如果越冬棲息地消失，鳥類可能難以度過非繁殖季節。"},{"en":"The phrase describes birds by origin, movement and seasonal location.","zh":"這個短語透過來源、遷徙和季節位置描述鳥類。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":8},{"front":"in the same way","meaning":"同樣地","examples":[{"en":"In the same way, coffee forests support North American migrants.","zh":"同樣地，咖啡森林支持北美候鳥。"},{"en":"In the same way means similarly or by a similar process.","zh":"「in the same way」意思是相似地或透過相似過程。"},{"en":"Trees cool a playground; in the same way, shade trees cool a coffee farm.","zh":"樹木令遊樂場降溫；同樣地，遮蔭樹令咖啡農場降溫。"},{"en":"If cocoa plantations help European birds, coffee forests may support North American birds in the same way.","zh":"如果可可種植園幫助歐洲鳥類，咖啡森林也可能同樣支持北美鳥類。"},{"en":"The phrase connects two parallel examples.","zh":"這個短語連接兩個平行例子。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":8},{"front":"coffee forests","meaning":"咖啡森林","examples":[{"en":"Coffee forests in the Americas are refuges for migrant birds.","zh":"美洲的咖啡森林是候鳥的庇護所。"},{"en":"Coffee forests are shade-grown coffee areas that include many trees and forest-like cover.","zh":"「coffee forests」是包含許多樹木和類森林覆蓋的蔭下咖啡區域。"},{"en":"A coffee forest may look more like woodland than a bare crop field.","zh":"咖啡森林看起來可能更像樹林，而不是裸露農田。"},{"en":"If coffee forests are cleared, birds may lose places to feed and rest.","zh":"如果咖啡森林被清除，鳥類可能失去覓食和休息地。"},{"en":"The phrase shows that some coffee farms also function as habitat.","zh":"這個短語顯示有些咖啡農場也發揮棲息地功能。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":8},{"front":"a refuge for","meaning":"……的庇護所","examples":[{"en":"Coffee forests provide a refuge for wintering birds.","zh":"咖啡森林為越冬鳥類提供庇護所。"},{"en":"A refuge for something is a safe place where it can live, rest or escape danger.","zh":"「a refuge for」某物，是讓它生活、休息或避開危險的安全地方。"},{"en":"A library can be a refuge for students who need a quiet place to study.","zh":"圖書館可以是需要安靜地方溫習的學生的庇護所。"},{"en":"If birds find refuge in shade farms, those farms become important during migration.","zh":"如果鳥類在蔭下農場找到庇護，這些農場在遷徙期間就很重要。"},{"en":"The phrase emphasises safety and protection.","zh":"這個短語強調安全和保護。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":8},{"front":"North American migrants","meaning":"北美候鳥","examples":[{"en":"Central American coffee forests protect North American migrants.","zh":"中美洲咖啡森林保護北美候鳥。"},{"en":"North American migrants are migratory birds from North America that travel to other regions seasonally.","zh":"「North American migrants」是來自北美、按季節遷徙到其他地區的候鳥。"},{"en":"Birdwatchers may track North American migrants as they move south for winter.","zh":"觀鳥者可能追蹤北美候鳥南飛過冬的路線。"},{"en":"If their winter habitats shrink, North American migrants may return north in weaker condition.","zh":"如果牠們的越冬棲息地縮小，北美候鳥可能以較差狀態返回北方。"},{"en":"The phrase refers to migrating birds, not human migrants in this context.","zh":"在這個語境中，這個短語指候鳥，而不是人類移民。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":8},{"front":"more recently","meaning":"近年來","examples":[{"en":"More recently, many shade-grown plantations have been cleared.","zh":"近年來，許多蔭下種植園已被清除。"},{"en":"More recently means in a later or nearer period of time.","zh":"「more recently」意思是在較後或較接近現在的時期。"},{"en":"The town first relied on buses; more recently, it has built a metro line.","zh":"該城鎮最初依賴巴士；近年來，它建成了地鐵線。"},{"en":"If farming changed more recently, older traditions may have been replaced by new pressures.","zh":"如果耕作近年來改變，舊傳統可能被新壓力取代。"},{"en":"The phrase moves the discussion closer to the present.","zh":"這個短語把討論推近現在。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":8},{"front":"a combination of","meaning":"……的結合","examples":[{"en":"A combination of market collapse and production pressure damaged shade farming.","zh":"世界市場崩潰和生產壓力的結合損害了蔭下耕作。"},{"en":"A combination of things means several factors working together.","zh":"「a combination of」幾件事，意思是多個因素一起作用。"},{"en":"A combination of poor sleep and stress can make students perform badly.","zh":"睡眠不足和壓力的結合可以令學生表現差。"},{"en":"If market pressure and yield targets combine, farmers may change production methods.","zh":"如果市場壓力和產量目標結合，農民可能改變生產方法。"},{"en":"The phrase shows that more than one cause is involved.","zh":"這個短語顯示涉及不止一個原因。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":8},{"front":"collapse in the world market","meaning":"世界市場崩潰","examples":[{"en":"The collapse in the world market for coffee and cocoa affected farmers.","zh":"咖啡和可可世界市場崩潰影響了農民。"},{"en":"A collapse in the world market means a sharp fall in global prices, demand or trade.","zh":"「collapse in the world market」指全球價格、需求或貿易急劇下跌。"},{"en":"A collapse in the housing market can make homeowners and builders lose money.","zh":"房屋市場崩潰可以令業主和建築商損失金錢。"},{"en":"If coffee prices collapse globally, poor farmers may clear more land to increase production.","zh":"如果咖啡價格在全球崩潰，貧困農民可能清除更多土地以增加產量。"},{"en":"The phrase describes a major economic downturn.","zh":"這個短語描述重大的經濟下行。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":8},{"front":"a drive to increase yields","meaning":"提高產量的推動力","examples":[{"en":"A drive to increase yields led to full-sun production.","zh":"提高產量的推動力導致全日照生產。"},{"en":"A drive to increase yields is a strong push to produce more crops from the same or larger area.","zh":"「a drive to increase yields」是強烈推動從相同或更大面積中生產更多作物。"},{"en":"A school may have a drive to improve exam results before public tests.","zh":"學校可能在公開考試前有提升考試成績的推動力。"},{"en":"If farmers are pushed to increase yields, they may choose intensive methods.","zh":"如果農民被推動提高產量，他們可能選擇集約化方法。"},{"en":"The phrase suggests pressure toward higher output.","zh":"這個短語暗示朝更高產出方向的壓力。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":8},{"front":"producer countries","meaning":"生產國","examples":[{"en":"Producer countries wanted to increase crop yields.","zh":"生產國希望提高作物產量。"},{"en":"Producer countries are countries that grow or make a product for sale.","zh":"「producer countries」是種植或製造某產品以出售的國家。"},{"en":"Oil producer countries may be affected when global energy prices fall.","zh":"當全球能源價格下跌，石油生產國可能受影響。"},{"en":"If cocoa producer countries compete strongly, they may try to increase yields.","zh":"如果可可生產國競爭激烈，它們可能試圖提高產量。"},{"en":"The phrase identifies countries by what they produce.","zh":"這個短語透過國家生產的產品來識別它們。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":8},{"front":"lead to","meaning":"導致","examples":[{"en":"Market pressure led to the clearing of shade-grown farms.","zh":"市場壓力導致蔭下種植農場被清除。"},{"en":"To lead to something means to cause it or result in it.","zh":"「lead to」某事，意思是造成它或引起它。"},{"en":"Poor time management can lead to missed deadlines.","zh":"差劣時間管理可以導致錯過截止日期。"},{"en":"If low prices lead to more intensive farming, the environment may suffer.","zh":"如果低價格導致更集約化耕作，環境可能受損。"},{"en":"The phrase clearly shows cause and effect.","zh":"這個短語清楚顯示因果關係。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":9},{"front":"huge swathes of","meaning":"大片……","examples":[{"en":"Huge swathes of shade-grown coffee and cocoa were cleared.","zh":"大片蔭下咖啡和可可種植地被清除。"},{"en":"Huge swathes of land means very large areas of land.","zh":"「huge swathes of」土地，意思是非常大片土地。"},{"en":"A storm may flood huge swathes of farmland after days of heavy rain.","zh":"連日大雨後，風暴可能淹沒大片農田。"},{"en":"If huge swathes of shade farms are cleared, many habitats disappear at once.","zh":"如果大片蔭下農場被清除，許多棲息地會同時消失。"},{"en":"The phrase emphasises large scale.","zh":"這個短語強調規模很大。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":9},{"front":"be cleared to make way for","meaning":"被清除以讓路給","examples":[{"en":"Shade-grown farms were cleared to make way for full-sun production.","zh":"蔭下農場被清除，以讓路給全日照生產。"},{"en":"To be cleared to make way for something means to be removed so something else can be built or used there.","zh":"「be cleared to make way for」某物，意思是被移除，使另一東西可以在那裡建造或使用。"},{"en":"Old houses may be cleared to make way for a new railway station.","zh":"舊房屋可能被清拆，以讓路給新火車站。"},{"en":"If trees are cleared to make way for farming, wildlife loses shelter.","zh":"如果樹木被清除以讓路給耕作，野生動物就失去庇護。"},{"en":"The phrase shows replacement of one land use by another.","zh":"這個短語顯示一種土地用途被另一種取代。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":9},{"front":"highly intensive","meaning":"高度集約化的","examples":[{"en":"Full-sun farming is a highly intensive production system.","zh":"全日照耕作是一種高度集約化的生產系統。"},{"en":"Highly intensive means using a lot of input, labour, chemicals or effort to produce high output.","zh":"「highly intensive」意思是使用大量投入、勞力、化學品或努力來產生高產出。"},{"en":"A highly intensive revision schedule may include several practice papers every day.","zh":"高度密集的溫習時間表可能每天包括幾份練習卷。"},{"en":"If farming becomes highly intensive, yields may rise but environmental pressure may also increase.","zh":"如果耕作變得高度集約化，產量可能上升，但環境壓力也可能增加。"},{"en":"The phrase suggests heavy use of resources.","zh":"這個短語暗示大量使用資源。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":9},{"front":"monoculture pattern of production","meaning":"單一作物生產模式","examples":[{"en":"Full-sun farming is a monoculture pattern of production.","zh":"全日照耕作是一種單一作物生產模式。"},{"en":"A monoculture pattern of production grows mainly one crop over an area.","zh":"「monoculture pattern of production」是在一片地區主要種植一種作物。"},{"en":"A farm planting only corn year after year is using monoculture.","zh":"一個年復一年只種玉米的農場，就是使用單一作物耕作。"},{"en":"If production becomes monoculture, biodiversity may fall because fewer habitats and food sources remain.","zh":"如果生產變成單一作物模式，因棲息地和食物來源較少，生物多樣性可能下降。"},{"en":"The phrase contrasts single-crop farming with diverse farming systems.","zh":"這個短語把單一作物耕作與多樣化農業系統作對比。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":9},{"front":"full sun","meaning":"全日照種植","examples":[{"en":"Full sun is a production method that removes shade trees.","zh":"全日照種植是一種移除遮蔭樹的生產方法。"},{"en":"Full sun means crops are grown in direct sunlight without overhead tree shade.","zh":"「full sun」意思是作物在沒有上方樹蔭的直射陽光下生長。"},{"en":"Some garden plants need full sun, while others grow better in partial shade.","zh":"有些花園植物需要全日照，而另一些在半陰處長得更好。"},{"en":"If coffee is grown in full sun, more land may become exposed and less forest-like.","zh":"如果咖啡在全日照下種植，更多土地可能變得裸露且不像森林。"},{"en":"The phrase describes the light condition used in farming.","zh":"這個短語描述耕作中的光照條件。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":9},{"front":"not only…but also…","meaning":"不但……而且……","examples":[{"en":"Full-sun farming not only reduces biodiversity but also requires chemicals.","zh":"全日照耕作不但減少生物多樣性，而且需要化學品。"},{"en":"Not only…but also… links two related points and emphasises that both are true.","zh":"「not only…but also…」連接兩個相關重點，並強調兩者都是真的。"},{"en":"Good sleep not only improves memory but also helps mood.","zh":"良好睡眠不但改善記憶，而且有助心情。"},{"en":"If full-sun farming not only reduces wildlife but also increases chemical use, its impact is double.","zh":"如果全日照耕作不但減少野生動物，而且增加化學品使用，其影響就是雙重的。"},{"en":"The structure adds a second important consequence.","zh":"這個結構加入第二個重要後果。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":9},{"front":"reduce the diversity of flora and fauna","meaning":"減少動植物多樣性","examples":[{"en":"Full-sun cultivation reduces the diversity of flora and fauna.","zh":"全日照耕作減少動植物多樣性。"},{"en":"To reduce the diversity of flora and fauna means to lower the variety of plants and animals.","zh":"「reduce the diversity of flora and fauna」意思是降低植物和動物的種類多樣性。"},{"en":"Replacing a park with concrete can reduce the diversity of local plants and birds.","zh":"用混凝土取代公園可以減少本地植物和鳥類的多樣性。"},{"en":"If shade trees are removed, both insects and birds may decline.","zh":"如果遮蔭樹被移除，昆蟲和鳥類都可能減少。"},{"en":"The phrase describes damage to overall biodiversity.","zh":"這個短語描述對整體生物多樣性的損害。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":9},{"front":"flora and fauna","meaning":"動植物","examples":[{"en":"The method harms local flora and fauna.","zh":"這種方法傷害本地動植物。"},{"en":"Flora and fauna means the plants and animals of a place.","zh":"「flora and fauna」指某地的植物和動物。"},{"en":"A nature reserve protects local flora and fauna from development.","zh":"自然保護區保護本地動植物免受發展破壞。"},{"en":"If chemicals enter streams, nearby flora and fauna may be harmed.","zh":"如果化學品進入溪流，附近動植物可能受害。"},{"en":"The phrase is a formal way to say plant and animal life.","zh":"這個短語是表示植物和動物生命的正式說法。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":9},{"front":"require huge amounts of","meaning":"需要大量……","examples":[{"en":"Full-sun farming requires huge amounts of pesticides and fertilisers.","zh":"全日照耕作需要大量殺蟲劑和肥料。"},{"en":"Require huge amounts of something means need very large quantities of it.","zh":"「require huge amounts of」某物，意思是需要非常大量的它。"},{"en":"A large hospital requires huge amounts of electricity to run equipment day and night.","zh":"大型醫院需要大量電力日夜運作設備。"},{"en":"If farming requires huge amounts of chemicals, costs and pollution risks may rise.","zh":"如果耕作需要大量化學品，成本和污染風險可能上升。"},{"en":"The phrase stresses heavy dependence on a resource.","zh":"這個短語強調對某資源的高度依賴。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":9},{"front":"pesticides and fertilisers","meaning":"殺蟲劑和肥料","examples":[{"en":"Full-sun plantations often require pesticides and fertilisers.","zh":"全日照種植園常需要殺蟲劑和肥料。"},{"en":"Pesticides and fertilisers are chemicals used to control pests and help crops grow.","zh":"「pesticides and fertilisers」是用來控制害蟲和幫助作物生長的化學品。"},{"en":"Farmers may use pesticides for insects and fertilisers for soil nutrients.","zh":"農民可能使用殺蟲劑對付昆蟲，使用肥料補充土壤養分。"},{"en":"If too many pesticides and fertilisers wash into rivers, water quality may suffer.","zh":"如果太多殺蟲劑和肥料被沖入河流，水質可能受損。"},{"en":"The phrase covers two common agricultural inputs.","zh":"這個短語涵蓋兩種常見農業投入。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":9},{"front":"Côte d’Ivoire","meaning":"科特迪瓦","examples":[{"en":"Côte d’Ivoire produces more than half the world’s cocoa.","zh":"科特迪瓦生產全球超過一半可可。"},{"en":"Côte d’Ivoire is a West African country strongly associated with cocoa production.","zh":"「Côte d’Ivoire」是西非國家，與可可生產關係密切。"},{"en":"A geography class may discuss Côte d’Ivoire when learning about global chocolate supply.","zh":"地理課學習全球朱古力供應時，可能討論科特迪瓦。"},{"en":"If a major cocoa producer changes farming methods, the global cocoa industry may be affected.","zh":"如果主要可可生產國改變耕作方法，全球可可產業可能受影響。"},{"en":"The name gives an important country example in the article.","zh":"這個名稱提供文章中的重要國家例子。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":10},{"front":"produce more than half","meaning":"生產超過一半","examples":[{"en":"Côte d’Ivoire produces more than half the world’s cocoa.","zh":"科特迪瓦生產全球超過一半可可。"},{"en":"To produce more than half means to make over 50 percent of the total amount.","zh":"「produce more than half」意思是生產總量超過百分之五十。"},{"en":"One factory may produce more than half of a company’s shoes.","zh":"一間工廠可能生產公司超過一半鞋履。"},{"en":"If one country produces more than half of a crop, its farming choices matter globally.","zh":"如果一個國家生產某作物超過一半，其耕作選擇對全球都重要。"},{"en":"The phrase describes majority production.","zh":"這個短語描述佔多數的生產量。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":10},{"front":"the world’s cocoa","meaning":"全球可可","examples":[{"en":"More than half the world’s cocoa comes from Côte d’Ivoire.","zh":"全球超過一半可可來自科特迪瓦。"},{"en":"The world’s cocoa means the total cocoa produced globally.","zh":"「the world’s cocoa」指全球生產的可可總量。"},{"en":"Chocolate companies depend on the world’s cocoa supply for their products.","zh":"朱古力公司依賴全球可可供應來製造產品。"},{"en":"If climate change affects the world’s cocoa, chocolate prices may rise.","zh":"如果氣候變化影響全球可可，朱古力價格可能上升。"},{"en":"The phrase gives a global scale for one crop.","zh":"這個短語為一種作物提供全球尺度。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":10},{"front":"more than a third of","meaning":"超過三分之一","examples":[{"en":"More than a third of the crop is grown in full-sun conditions.","zh":"超過三分之一的作物在全日照環境中種植。"},{"en":"More than a third of something means more than one part out of three.","zh":"「more than a third of」某物，意思是超過三份之一。"},{"en":"More than a third of the class may take the bus to school.","zh":"班上超過三分之一學生可能乘巴士上學。"},{"en":"If more than a third of a crop uses one method, that method is common enough to matter.","zh":"如果超過三分之一作物使用某方法，該方法已常見到值得關注。"},{"en":"The phrase gives a large proportion but not a majority.","zh":"這個短語表示很大比例，但不是多數。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":10},{"front":"the crop","meaning":"農作物；收成","examples":[{"en":"A large part of the crop is now grown in full sun.","zh":"很大部分農作物現在在全日照下種植。"},{"en":"The crop means the plants grown and harvested for food or sale.","zh":"「the crop」指為食物或銷售而種植和收成的植物。"},{"en":"A farmer checks the crop after heavy rain to see whether it was damaged.","zh":"大雨後，農民檢查作物是否受損。"},{"en":"If the crop is grown without shade, it may need more chemicals and water.","zh":"如果作物在沒有遮蔭下種植，它可能需要更多化學品和水。"},{"en":"The phrase can mean one type of plant or the harvest from a field.","zh":"這個短語可以指一種植物，也可以指田地收成。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":10},{"front":"full-sun conditions","meaning":"全日照環境","examples":[{"en":"Many cocoa plants are now grown in full-sun conditions.","zh":"許多可可植物現在在全日照環境中種植。"},{"en":"Full-sun conditions are growing conditions with direct sunlight and little or no shade.","zh":"「full-sun conditions」是有直射陽光且幾乎沒有遮蔭的生長環境。"},{"en":"Tomatoes often grow well in full-sun conditions in a garden.","zh":"番茄在花園的全日照環境中通常長得好。"},{"en":"If forest crops are moved into full-sun conditions, biodiversity may decline.","zh":"如果森林作物被移到全日照環境，生物多樣性可能下降。"},{"en":"The phrase describes the light environment around plants.","zh":"這個短語描述植物周圍的光照環境。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":10},{"front":"loggers","meaning":"伐木工人","examples":[{"en":"The loggers have been busy in the Americas too.","zh":"伐木工人在美洲也一直很忙。"},{"en":"Loggers are workers who cut down trees for timber or land clearing.","zh":"「loggers」是為木材或清理土地而砍伐樹木的工人。"},{"en":"Loggers may work in forests using saws, trucks and heavy machines.","zh":"伐木工人可能在森林中使用鋸、貨車和重型機器工作。"},{"en":"If loggers clear shade trees, coffee farms may lose their forest-like structure.","zh":"如果伐木工人清除遮蔭樹，咖啡農場可能失去類森林結構。"},{"en":"The word identifies people involved in tree removal.","zh":"這個詞指出參與移除樹木的人。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":10},{"front":"be busy","meaning":"忙於","examples":[{"en":"Loggers have been busy clearing shade forests.","zh":"伐木工人忙於清除蔭下森林。"},{"en":"To be busy doing something means to spend a lot of time actively doing it.","zh":"「be busy」做某事，意思是花很多時間積極做它。"},{"en":"Teachers are busy marking essays before the end of term.","zh":"老師在學期末前忙於批改作文。"},{"en":"If loggers are busy clearing forests, land use may be changing quickly.","zh":"如果伐木工人忙於清除森林，土地用途可能正在快速改變。"},{"en":"The phrase shows active and repeated work.","zh":"這個短語顯示積極且重複的工作。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":10},{"front":"in the Americas","meaning":"在美洲","examples":[{"en":"Full-sun coffee production has expanded in the Americas.","zh":"全日照咖啡生產已在美洲擴展。"},{"en":"In the Americas means in North, Central or South America.","zh":"「in the Americas」意思是在北美、中美或南美。"},{"en":"Many migratory birds travel across different regions in the Americas.","zh":"許多候鳥穿越美洲不同地區。"},{"en":"If farming methods change in the Americas, bird migration routes may be affected.","zh":"如果美洲的耕作方法改變，鳥類遷徙路線可能受影響。"},{"en":"The phrase gives a broad geographical area.","zh":"這個短語提供廣泛地理範圍。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":10},{"front":"Colombian coffee","meaning":"哥倫比亞咖啡","examples":[{"en":"Nearly 70% of Colombian coffee is produced using full-sun methods.","zh":"接近70%的哥倫比亞咖啡使用全日照方法生產。"},{"en":"Colombian coffee is coffee grown or produced in Colombia.","zh":"「Colombian coffee」是在哥倫比亞種植或生產的咖啡。"},{"en":"Shops may advertise Colombian coffee because customers associate it with flavour and origin.","zh":"商店可能宣傳哥倫比亞咖啡，因為顧客把它與風味和來源聯想起來。"},{"en":"If Colombian coffee is increasingly full-sun, bird habitat in coffee regions may decline.","zh":"如果哥倫比亞咖啡越來越多使用全日照，咖啡地區的鳥類棲息地可能下降。"},{"en":"The phrase identifies coffee by national origin.","zh":"這個短語以國家來源識別咖啡。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":10},{"front":"be produced using","meaning":"使用……生產","examples":[{"en":"Colombian coffee is often produced using full-sun methods.","zh":"哥倫比亞咖啡常使用全日照方法生產。"},{"en":"To be produced using something means to be made or grown with that method or tool.","zh":"「be produced using」某物，意思是用該方法或工具製造或種植。"},{"en":"Bread may be produced using traditional ovens or modern machines.","zh":"麵包可以使用傳統焗爐或現代機器生產。"},{"en":"If coffee is produced using full-sun methods, its environmental impact may differ from shade coffee.","zh":"如果咖啡使用全日照方法生產，其環境影響可能不同於蔭下咖啡。"},{"en":"The phrase connects a product with its production method.","zh":"這個短語把產品與生產方法連繫起來。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":10},{"front":"full-sun methods","meaning":"全日照方法","examples":[{"en":"Full-sun methods have reduced bird diversity in some regions.","zh":"全日照方法已在一些地區減少鳥類多樣性。"},{"en":"Full-sun methods are farming methods that grow crops without shade trees.","zh":"「full-sun methods」是在沒有遮蔭樹下種植作物的耕作方法。"},{"en":"A farmer using full-sun methods may remove trees so crops receive direct sunlight.","zh":"使用全日照方法的農民可能移除樹木，讓作物接受直射陽光。"},{"en":"If full-sun methods reduce habitat complexity, fewer bird species may survive there.","zh":"如果全日照方法降低棲息地複雜性，能在那裡生存的鳥類物種可能更少。"},{"en":"The phrase contrasts with shade-grown methods.","zh":"這個短語與蔭下種植方法形成對比。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":11},{"front":"one study carried out in","meaning":"在……進行的一項研究","examples":[{"en":"One study carried out in Colombia and Mexico found major biodiversity loss.","zh":"在哥倫比亞和墨西哥進行的一項研究發現重大生物多樣性流失。"},{"en":"One study carried out in a place means a piece of research done there.","zh":"「one study carried out in」某地，意思是在那裡完成的一項研究。"},{"en":"One study carried out in schools compared reading habits before and after a new library opened.","zh":"在學校進行的一項研究比較了新圖書館開放前後的閱讀習慣。"},{"en":"If a study carried out in two countries finds the same pattern, the evidence becomes stronger.","zh":"如果在兩個國家進行的研究發現相同模式，證據就變得更強。"},{"en":"The phrase identifies where research was conducted.","zh":"這個短語指出研究在哪裡進行。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":11},{"front":"compared with","meaning":"與……相比","examples":[{"en":"Compared with shade coffee, full-sun plantations support fewer bird species.","zh":"與蔭下咖啡相比，全日照種植園支持較少鳥類物種。"},{"en":"Compared with means when considered against another thing.","zh":"「compared with」意思是與另一事物放在一起考慮。"},{"en":"Compared with driving, taking the train may produce less pollution.","zh":"與駕車相比，乘火車可能產生較少污染。"},{"en":"If full-sun farms support fewer birds compared with shade farms, farming method matters.","zh":"如果全日照農場與蔭下農場相比支持較少鳥類，耕作方法就很重要。"},{"en":"The phrase introduces a comparison.","zh":"這個短語引入比較。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":11},{"front":"shade coffee","meaning":"蔭下咖啡","examples":[{"en":"Shade coffee supports more bird species than full-sun coffee.","zh":"蔭下咖啡比全日照咖啡支持更多鳥類物種。"},{"en":"Shade coffee is coffee grown under trees instead of in open sunlight.","zh":"「shade coffee」是在樹下而不是開闊陽光下種植的咖啡。"},{"en":"A shopper may choose shade coffee if they want to support bird-friendly farming.","zh":"如果購物者想支持鳥類友善耕作，他們可能選擇蔭下咖啡。"},{"en":"If shade coffee keeps forest structure, it may protect biodiversity better.","zh":"如果蔭下咖啡保留森林結構，它可能更好保護生物多樣性。"},{"en":"The phrase describes coffee by how it is grown.","zh":"這個短語根據咖啡的種植方式描述它。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":11},{"front":"95% fewer species of birds","meaning":"鳥類物種少95%","examples":[{"en":"Full-sun plantations have 95% fewer species of birds.","zh":"全日照種植園的鳥類物種少95%。"},{"en":"95% fewer species of birds means the number of bird species is reduced by almost all of them.","zh":"「95% fewer species of birds」意思是鳥類物種數量幾乎全部減少。"},{"en":"If a park has 20 bird species and loses 95%, only about one species remains.","zh":"如果公園有20種鳥類並失去95%，大約只剩一種。"},{"en":"Such a large decline shows that habitat change can be severe.","zh":"這樣大的下降顯示棲息地改變可以很嚴重。"},{"en":"The phrase expresses a dramatic loss in bird diversity.","zh":"這個短語表達鳥類多樣性的劇烈流失。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":11},{"front":"cultural as well as ecological significance","meaning":"文化及生態意義","examples":[{"en":"Shade-coffee farms have cultural as well as ecological significance.","zh":"蔭下咖啡農場具有文化及生態意義。"},{"en":"Cultural as well as ecological significance means importance for human traditions as well as nature.","zh":"「cultural as well as ecological significance」意思是對人類傳統和自然環境都有重要性。"},{"en":"An old village pond may have cultural as well as ecological significance because people hold festivals there and animals live there.","zh":"舊村池塘可能有文化及生態意義，因為人們在那裡舉行節慶，而動物也在那裡生活。"},{"en":"If shade coffee preserves farming traditions and bird habitats, it has both kinds of value.","zh":"如果蔭下咖啡保存耕作傳統和鳥類棲息地，它就有兩種價值。"},{"en":"The phrase joins human meaning with environmental meaning.","zh":"這個短語把人文意義與環境意義結合起來。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":11},{"front":"ecological significance","meaning":"生態意義","examples":[{"en":"The farms have ecological significance for birds and other wildlife.","zh":"這些農場對鳥類和其他野生動物有生態意義。"},{"en":"Ecological significance means importance for ecosystems and living organisms.","zh":"「ecological significance」意思是對生態系統和生物的重要性。"},{"en":"A small wetland may have ecological significance if rare frogs breed there.","zh":"如果稀有青蛙在小濕地繁殖，該濕地可能有生態意義。"},{"en":"If farms provide habitat, they can have ecological significance beyond food production.","zh":"如果農場提供棲息地，它們就有超越糧食生產的生態意義。"},{"en":"The phrase focuses on value to nature.","zh":"這個短語集中於對自然的價值。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":11},{"front":"see them go","meaning":"看着它們消失","examples":[{"en":"People are not happy to see shade-coffee farms go.","zh":"人們不願看着蔭下咖啡農場消失。"},{"en":"To see them go means to watch them disappear, close or be lost.","zh":"「see them go」意思是看着它們消失、關閉或失去。"},{"en":"Residents were sad to see the old library go after many years of service.","zh":"居民對多年服務的舊圖書館消失感到難過。"},{"en":"If shade farms go, communities may lose both income and cultural landscapes.","zh":"如果蔭下農場消失，社區可能失去收入和文化景觀。"},{"en":"The phrase carries a feeling of loss.","zh":"這個短語帶有失落感。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":11},{"front":"financial pressures","meaning":"財政壓力","examples":[{"en":"The financial pressures on shade-coffee farmers are great.","zh":"蔭下咖啡農民承受很大財政壓力。"},{"en":"Financial pressures are money-related difficulties that force people to make hard choices.","zh":"「financial pressures」是與金錢有關、迫使人作艱難選擇的困難。"},{"en":"A family may face financial pressures when rent and food prices rise together.","zh":"當租金和食物價格同時上升，家庭可能面對財政壓力。"},{"en":"If farmers face strong financial pressure, they may change to higher-yield methods.","zh":"如果農民面對強大財政壓力，他們可能轉用產量更高的方法。"},{"en":"The phrase explains why environmentally valuable practices may be hard to maintain.","zh":"這個短語解釋為何有環境價值的做法可能難以維持。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":11},{"front":"make much money","meaning":"賺很多錢","examples":[{"en":"Few shade-coffee farms make much money.","zh":"很少蔭下咖啡農場能賺很多錢。"},{"en":"To make much money means to earn a large profit or income.","zh":"「make much money」意思是賺取大量利潤或收入。"},{"en":"A small family shop may work hard but not make much money after rent is paid.","zh":"小型家庭店可能很努力，但付租金後賺不了很多錢。"},{"en":"If shade-coffee farmers do not make much money, they may struggle to keep traditional systems.","zh":"如果蔭下咖啡農民賺不了很多錢，他們可能難以維持傳統系統。"},{"en":"The phrase focuses on profit, not effort.","zh":"這個短語集中於利潤，而不是努力。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":11},{"front":"a cooperative of","meaning":"由……組成的合作社","examples":[{"en":"The farm was a cooperative of 100 families.","zh":"該農場是一個由100個家庭組成的合作社。"},{"en":"A cooperative of people is a group owned or run jointly by its members.","zh":"「a cooperative of」某些人，是由成員共同擁有或管理的團體。"},{"en":"A cooperative of farmers may share equipment, storage and sales arrangements.","zh":"農民合作社可能共享設備、儲存和銷售安排。"},{"en":"If 100 families form a cooperative, profits and responsibilities may be shared.","zh":"如果100個家庭組成合作社，利潤和責任可能被共同分擔。"},{"en":"The phrase describes collective organisation.","zh":"這個短語描述集體組織形式。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":11},{"front":"per family","meaning":"每個家庭","examples":[{"en":"The cooperative made only about $100 per family.","zh":"該合作社每個家庭只賺約100美元。"},{"en":"Per family means for each family.","zh":"「per family」意思是每一個家庭。"},{"en":"A school trip may cost $50 per family if siblings share transport.","zh":"如果兄弟姊妹共用交通，學校旅行可能每個家庭花費50美元。"},{"en":"If profit is only $100 per family, the income is very small once labour is considered.","zh":"如果每個家庭利潤只有100美元，一旦考慮勞工，收入就非常少。"},{"en":"The phrase divides a total amount among families.","zh":"這個短語把總數分配到每個家庭。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":12},{"front":"take labour costs into account","meaning":"將勞工成本計算在內","examples":[{"en":"The figure did not take labour costs into account.","zh":"該數字沒有將勞工成本計算在內。"},{"en":"To take labour costs into account means to include the cost of workers’ time and effort in a calculation.","zh":"「take labour costs into account」意思是在計算中包括工人的時間和努力成本。"},{"en":"A restaurant must take labour costs into account before deciding menu prices.","zh":"餐廳在決定餐牌價格前，必須將勞工成本計算在內。"},{"en":"If a farm ignores labour costs, its profit may look higher than it really is.","zh":"如果農場忽略勞工成本，其利潤可能看起來比實際更高。"},{"en":"The phrase warns that a calculation may be incomplete.","zh":"這個短語提醒計算可能並不完整。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":12},{"front":"loss of shade-coffee forests","meaning":"蔭下咖啡森林的消失","examples":[{"en":"The loss of shade-coffee forests has alarmed wildlife organisations.","zh":"蔭下咖啡森林的消失令野生動物組織感到憂慮。"},{"en":"Loss of shade-coffee forests means these tree-covered coffee habitats are disappearing.","zh":"「loss of shade-coffee forests」意思是這些有樹木覆蓋的咖啡棲息地正在消失。"},{"en":"A town may worry about the loss of old trees because birds and people both depend on them.","zh":"城鎮可能擔心老樹消失，因為鳥類和人都依賴它們。"},{"en":"If shade-coffee forests are lost, migratory birds may lose winter refuges.","zh":"如果蔭下咖啡森林消失，候鳥可能失去越冬庇護所。"},{"en":"The phrase describes environmental disappearance and its concern.","zh":"這個短語描述環境消失及其引起的關注。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":12},{"front":"alarm a number of","meaning":"令多個……感到憂慮","examples":[{"en":"The loss of forests has alarmed a number of conservation groups.","zh":"森林消失令多個保育團體感到憂慮。"},{"en":"To alarm a number of people or groups means to make several of them worried or frightened.","zh":"「alarm a number of」人或團體，意思是令其中多個感到擔心或害怕。"},{"en":"Rising rents have alarmed a number of local families.","zh":"租金上升令多個本地家庭感到憂慮。"},{"en":"If many habitats disappear quickly, conservation groups may be alarmed and take action.","zh":"如果許多棲息地迅速消失，保育團體可能感到憂慮並採取行動。"},{"en":"The phrase signals serious concern among more than one group.","zh":"這個短語表示多於一個群體出現嚴重關注。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":12},{"front":"wildlife organisations","meaning":"野生動物組織","examples":[{"en":"Wildlife organisations are trying to save shade-coffee habitats.","zh":"野生動物組織正試圖拯救蔭下咖啡棲息地。"},{"en":"Wildlife organisations are groups that work to protect wild animals and their habitats.","zh":"「wildlife organisations」是致力保護野生動物及其棲息地的團體。"},{"en":"Wildlife organisations may run surveys, campaigns and education programmes.","zh":"野生動物組織可能進行調查、宣傳活動和教育計劃。"},{"en":"If wildlife organisations promote bird-friendly coffee, consumers can help support habitats.","zh":"如果野生動物組織推廣鳥類友善咖啡，消費者就可以幫助支持棲息地。"},{"en":"The phrase refers to conservation-focused groups.","zh":"這個短語指以保育為重點的團體。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":12},{"front":"harness consumer power","meaning":"利用消費者力量","examples":[{"en":"Wildlife organisations are harnessing consumer power to protect habitats.","zh":"野生動物組織正在利用消費者力量保護棲息地。"},{"en":"To harness consumer power means to use shoppers’ choices to create change.","zh":"「harness consumer power」意思是利用購物者的選擇來造成改變。"},{"en":"A campaign may harness consumer power by asking people to buy products with less plastic.","zh":"宣傳活動可能透過呼籲人們購買較少塑膠包裝的產品來利用消費者力量。"},{"en":"If many consumers choose shade-grown coffee, farmers may have a reason to keep shade trees.","zh":"如果許多消費者選擇蔭下咖啡，農民就可能有理由保留遮蔭樹。"},{"en":"The phrase shows how buying decisions can influence producers.","zh":"這個短語顯示購買決定如何影響生產者。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":12},{"front":"threatened habitats","meaning":"受威脅的棲息地","examples":[{"en":"Shade-coffee forests are threatened habitats for wildlife.","zh":"蔭下咖啡森林是野生動物受威脅的棲息地。"},{"en":"Threatened habitats are places where animals or plants live but that are at risk of damage or loss.","zh":"「threatened habitats」是動植物生活但面臨損害或消失風險的地方。"},{"en":"Wetlands near cities can become threatened habitats when buildings expand.","zh":"城市附近濕地在建築擴張時可能成為受威脅的棲息地。"},{"en":"If threatened habitats are protected, endangered species may have a better chance of survival.","zh":"如果受威脅的棲息地受到保護，瀕危物種可能有更大生存機會。"},{"en":"The phrase focuses on places in danger.","zh":"這個短語集中於處於危險中的地方。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":12},{"front":"promote a certification system","meaning":"推廣認證制度","examples":[{"en":"Organisations promote a certification system for shade-grown beans.","zh":"組織推廣蔭下種植咖啡豆的認證制度。"},{"en":"To promote a certification system means to encourage the use of official labels or standards.","zh":"「promote a certification system」意思是鼓勵使用官方標籤或標準。"},{"en":"A school may promote a certification system for safe lunch suppliers.","zh":"學校可能推廣安全午餐供應商的認證制度。"},{"en":"If coffee certification is promoted, consumers can identify how beans were grown.","zh":"如果咖啡認證被推廣，消費者可以識別咖啡豆如何種植。"},{"en":"The phrase links standards with public trust.","zh":"這個短語把標準與公眾信任連繫起來。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":12},{"front":"certification system","meaning":"認證制度","examples":[{"en":"A certification system can tell consumers how coffee was grown.","zh":"認證制度可以告訴消費者咖啡如何種植。"},{"en":"A certification system is a set of rules and labels showing that a product meets certain standards.","zh":"「certification system」是一套規則和標籤，顯示產品符合某些標準。"},{"en":"Organic food often uses a certification system to show how it was produced.","zh":"有機食品常使用認證制度來顯示其生產方式。"},{"en":"If a certification system is strict, buyers can trust the label more.","zh":"如果認證制度嚴格，買家可以更信任標籤。"},{"en":"The phrase describes organised proof of quality or method.","zh":"這個短語描述有組織的質素或方法證明。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":12},{"front":"indicate to consumers that","meaning":"向消費者顯示","examples":[{"en":"The label indicates to consumers that the beans were shade-grown.","zh":"標籤向消費者顯示這些咖啡豆是在蔭下種植的。"},{"en":"To indicate to consumers that something is true means to show buyers that information clearly.","zh":"「indicate to consumers that」某事為真，意思是向買家清楚顯示該資料。"},{"en":"A label may indicate to consumers that a product contains nuts.","zh":"標籤可能向消費者顯示產品含有果仁。"},{"en":"If certification indicates that coffee is shade-grown, buyers can choose more consciously.","zh":"如果認證顯示咖啡是蔭下種植，買家就可以更有意識地選擇。"},{"en":"The phrase connects product information with consumer decisions.","zh":"這個短語把產品資料與消費者決定連繫起來。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":12},{"front":"beans","meaning":"咖啡豆","examples":[{"en":"The beans may be certified as shade-grown.","zh":"這些咖啡豆可能被認證為蔭下種植。"},{"en":"Beans here means coffee beans, the seeds used to make coffee.","zh":"這裡的 「beans」指咖啡豆，即用來製作咖啡的種子。"},{"en":"A café may buy beans from farms that follow environmental standards.","zh":"咖啡店可能從遵守環境標準的農場購買咖啡豆。"},{"en":"If beans are certified, consumers may trust that they were grown in a particular way.","zh":"如果咖啡豆獲得認證，消費者可能相信它們是以特定方式種植的。"},{"en":"The word depends on context; here it does not mean ordinary food beans.","zh":"這個詞取決於語境；在這裡不是指普通豆類食品。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":12},{"front":"grown on shade plantations","meaning":"在蔭下種植園種植","examples":[{"en":"The beans were grown on shade plantations.","zh":"這些咖啡豆在蔭下種植園種植。"},{"en":"Grown on shade plantations means produced on farms where crops grow under tree cover.","zh":"「grown on shade plantations」意思是在作物於樹冠覆蓋下生長的農場中生產。"},{"en":"Cocoa grown on shade plantations may support birds and insects.","zh":"在蔭下種植園種植的可可可能支持鳥類和昆蟲。"},{"en":"If coffee beans are grown on shade plantations, trees remain part of the farming system.","zh":"如果咖啡豆在蔭下種植園種植，樹木仍是農業系統的一部分。"},{"en":"The phrase identifies the farming environment of the crop.","zh":"這個短語指出作物的耕作環境。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":13},{"front":"bird-friendly coffee","meaning":"鳥類友善咖啡","examples":[{"en":"Bird-friendly coffee is marketed by the Smithsonian Migratory Bird Center.","zh":"鳥類友善咖啡由 Smithsonian Migratory Bird Center 推廣銷售。"},{"en":"Bird-friendly coffee is coffee grown in ways that help protect bird habitats.","zh":"「bird-friendly coffee」是以有助保護鳥類棲息地的方式種植的咖啡。"},{"en":"A shopper may choose bird-friendly coffee to support farms with shade trees.","zh":"購物者可能選擇鳥類友善咖啡，以支持有遮蔭樹的農場。"},{"en":"If coffee is truly bird-friendly, it should provide food, shelter and resting places for birds.","zh":"如果咖啡真正對鳥類友善，它應為鳥類提供食物、庇護和休息地。"},{"en":"The phrase turns an environmental feature into a product label.","zh":"這個短語把環境特徵轉化為產品標籤。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":13},{"front":"be marketed by","meaning":"由……銷售；推廣","examples":[{"en":"Bird-friendly coffee is marketed by a conservation organisation.","zh":"鳥類友善咖啡由保育組織銷售或推廣。"},{"en":"To be marketed by a group means to be promoted or sold by that group.","zh":"「be marketed by」某團體，意思是由該團體推廣或銷售。"},{"en":"A local honey brand may be marketed by a farmers’ cooperative.","zh":"本地蜂蜜品牌可能由農民合作社推廣。"},{"en":"If a product is marketed by a conservation organisation, its environmental claim may attract buyers.","zh":"如果產品由保育組織推廣，其環境主張可能吸引買家。"},{"en":"The phrase identifies who promotes the product.","zh":"這個短語指出誰在推廣產品。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":13},{"front":"small extra cost","meaning":"少量額外成本","examples":[{"en":"The small extra cost is passed on to coffee farmers.","zh":"少量額外成本會轉交給咖啡農民。"},{"en":"A small extra cost is a little additional amount of money paid beyond the normal price.","zh":"「small extra cost」是在正常價格以外支付的一小筆額外金額。"},{"en":"A customer may pay a small extra cost for recyclable packaging.","zh":"顧客可能為可回收包裝支付少量額外成本。"},{"en":"If the extra cost reaches farmers, it can help them maintain shade trees.","zh":"如果額外成本到達農民手中，它可以幫助他們維持遮蔭樹。"},{"en":"The phrase suggests the added price is minor but useful.","zh":"這個短語暗示增加的價格不大但有用。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":13},{"front":"be passed directly on to","meaning":"直接轉交給","examples":[{"en":"The extra cost is passed directly on to the farmers.","zh":"額外成本會直接轉交給農民。"},{"en":"To be passed directly on to someone means to be given to them without being kept by others first.","zh":"「be passed directly on to」某人，意思是在不先被他人扣留的情況下交給他們。"},{"en":"Donations should be passed directly on to families who need help.","zh":"捐款應直接轉交給需要幫助的家庭。"},{"en":"If the premium is passed directly on to farmers, certification may improve their income.","zh":"如果溢價直接轉交給農民，認證可能改善他們的收入。"},{"en":"The phrase stresses that the benefit reaches the intended people.","zh":"這個短語強調好處到達目標人士手中。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":13},{"front":"financial incentive","meaning":"經濟誘因","examples":[{"en":"The certification system provides a financial incentive to farmers.","zh":"認證制度為農民提供經濟誘因。"},{"en":"A financial incentive is money or economic benefit that encourages people to do something.","zh":"「financial incentive」是鼓勵人們做某事的金錢或經濟利益。"},{"en":"A company may offer a financial incentive to employees who use public transport.","zh":"公司可能向使用公共交通的員工提供經濟誘因。"},{"en":"If farmers receive extra income for shade coffee, they have an incentive to protect trees.","zh":"如果農民因蔭下咖啡獲得額外收入，他們就有保護樹木的誘因。"},{"en":"The phrase explains how money can influence behaviour.","zh":"這個短語解釋金錢如何影響行為。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":13},{"front":"maintain shade-coffee farms","meaning":"維持蔭下咖啡農場","examples":[{"en":"The incentive helps farmers maintain shade-coffee farms.","zh":"這項誘因幫助農民維持蔭下咖啡農場。"},{"en":"To maintain shade-coffee farms means to keep these farms operating with tree shade intact.","zh":"「maintain shade-coffee farms」意思是保持這些農場運作，並保留樹蔭。"},{"en":"Farmers may maintain shade farms by planting new trees and avoiding full clearing.","zh":"農民可能透過種植新樹和避免全面清除來維持蔭下農場。"},{"en":"If farmers cannot earn enough, they may struggle to maintain shade systems.","zh":"如果農民賺不夠錢，他們可能難以維持蔭下系統。"},{"en":"The phrase focuses on keeping an existing farming practice alive.","zh":"這個短語集中於讓現有耕作做法持續存在。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":13},{"front":"not all conservationists agree","meaning":"並非所有保育人士都同意","examples":[{"en":"Not all conservationists agree with certification schemes.","zh":"並非所有保育人士都同意認證計劃。"},{"en":"Not all conservationists agree means some conservationists support the idea but others do not.","zh":"「not all conservationists agree」意思是有些保育人士支持該想法，但另一些不同意。"},{"en":"Not all teachers agree on whether homework should be given every day.","zh":"並非所有老師都同意是否應每天給功課。"},{"en":"If experts disagree, a policy may need stricter evidence and clearer safeguards.","zh":"如果專家不同意，一項政策可能需要更嚴格證據和更清楚保障。"},{"en":"The phrase shows partial disagreement within a group.","zh":"這個短語顯示一個群體內部有部分分歧。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":13},{"front":"conservationists","meaning":"保育人士","examples":[{"en":"Conservationists disagree about the value of shade-grown certification.","zh":"保育人士對蔭下種植認證的價值有不同意見。"},{"en":"Conservationists are people who work to protect nature, wildlife or cultural heritage.","zh":"「conservationists」是致力保護自然、野生動物或文化遺產的人。"},{"en":"Conservationists may study habitats, campaign for laws or advise farmers.","zh":"保育人士可能研究棲息地、推動法律或向農民提供建議。"},{"en":"If conservationists disagree, it may be because they worry about unintended consequences.","zh":"如果保育人士意見不同，可能是因為他們擔心意想不到的後果。"},{"en":"The word refers to people focused on protection and preservation.","zh":"這個詞指專注於保護和保存的人。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":13},{"front":"such measures","meaning":"這類措施","examples":[{"en":"Some conservationists criticise such measures.","zh":"有些保育人士批評這類措施。"},{"en":"Such measures means actions or policies of the kind just mentioned.","zh":"「such measures」意思是剛才提到的那類行動或政策。"},{"en":"A school may introduce phone bans and stricter rules; some parents may criticise such measures.","zh":"學校可能引入手機禁令和更嚴格規則；有些家長可能批評這類措施。"},{"en":"If certification schemes create risks, critics may question such measures.","zh":"如果認證計劃帶來風險，批評者可能質疑這類措施。"},{"en":"The phrase points back to actions already discussed.","zh":"這個短語指回前面已討論的行動。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":13},{"front":"lead to the loss of","meaning":"導致……失去","examples":[{"en":"Certification could lead to the loss of natural forests.","zh":"認證可能導致天然森林失去。"},{"en":"To lead to the loss of something means to cause it to disappear or be reduced.","zh":"「lead to the loss of」某物，意思是導致它消失或減少。"},{"en":"Poor planning can lead to the loss of public green space.","zh":"規劃不善可以導致公共綠地失去。"},{"en":"If shade-coffee marketing encourages forest conversion, it may lead to habitat loss.","zh":"如果蔭下咖啡市場推廣鼓勵森林改作種植園，它可能導致棲息地流失。"},{"en":"The phrase shows a harmful consequence.","zh":"這個短語顯示有害後果。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":13},{"front":"preservation of","meaning":"保育；保存","examples":[{"en":"Some critics say certification may not lead to the preservation of forests.","zh":"有些批評者說認證未必會帶來森林保育。"},{"en":"Preservation of something means protecting it so it continues to exist.","zh":"「preservation of」某物，意思是保護它，使它繼續存在。"},{"en":"The preservation of old buildings can help a city remember its history.","zh":"保存舊建築可以幫助城市記住自己的歷史。"},{"en":"If certification is weak, it may fail to ensure the preservation of real forests.","zh":"如果認證薄弱，它可能無法確保真正森林得到保育。"},{"en":"The phrase focuses on keeping something from being damaged or lost.","zh":"這個短語集中於防止某物受損或消失。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":14},{"front":"natural forests","meaning":"天然森林","examples":[{"en":"Some fear that natural forests may be converted into plantations.","zh":"有些人擔心天然森林可能被改造成種植園。"},{"en":"Natural forests are forests that developed mainly through natural processes.","zh":"「natural forests」是主要透過自然過程形成的森林。"},{"en":"Natural forests often contain richer structure than simple crop plantations.","zh":"天然森林通常比簡單作物種植園有更豐富結構。"},{"en":"If natural forests become plantations, some species may lose their original habitat.","zh":"如果天然森林變成種植園，有些物種可能失去原本棲息地。"},{"en":"The phrase is important because not all tree-covered land has the same ecological value.","zh":"這個短語很重要，因為並非所有有樹覆蓋的土地都有相同生態價值。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":14},{"front":"argue that","meaning":"認為；主張","examples":[{"en":"John Rappole argues that shade-grown marketing can create risks.","zh":"John Rappole 認為蔭下種植市場推廣可能造成風險。"},{"en":"To argue that means to state a view and give reasons for it.","zh":"「argue that」意思是提出一個看法並提供理由。"},{"en":"A student may argue that homework should be shorter but more meaningful.","zh":"學生可能主張功課應較短但更有意義。"},{"en":"If a scientist argues that a policy has risks, readers should look for the evidence.","zh":"如果科學家認為某政策有風險，讀者應尋找證據。"},{"en":"The phrase introduces a claim or opinion.","zh":"這個短語引出主張或意見。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":14},{"front":"shade-grown marketing","meaning":"蔭下種植市場推廣","examples":[{"en":"Shade-grown marketing may encourage conversion of primary forests.","zh":"蔭下種植市場推廣可能鼓勵原始森林轉換用途。"},{"en":"Shade-grown marketing is promotion that sells products by emphasising shade-grown farming.","zh":"「shade-grown marketing」是透過強調蔭下種植來銷售產品的推廣。"},{"en":"A coffee company may use shade-grown marketing on labels and advertisements.","zh":"咖啡公司可能在標籤和廣告上使用蔭下種植市場推廣。"},{"en":"If marketing rewards shade farms without strict rules, farmers may convert forests to gain premiums.","zh":"如果市場推廣在沒有嚴格規則下獎勵蔭下農場，農民可能為獲取溢價而改造森林。"},{"en":"The phrase describes the commercial promotion of an environmental idea.","zh":"這個短語描述環境概念的商業推廣。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":14},{"front":"provide an incentive to","meaning":"提供誘因去","examples":[{"en":"The marketing may provide an incentive to convert forest.","zh":"市場推廣可能提供誘因去轉換森林用途。"},{"en":"To provide an incentive to do something means to give a reason or reward that encourages it.","zh":"「provide an incentive to」做某事，意思是給予鼓勵該行為的理由或獎勵。"},{"en":"A discount can provide an incentive to buy a yearly membership.","zh":"折扣可以提供誘因去購買全年會籍。"},{"en":"If certification gives higher prices, it may provide an incentive to plant more shade coffee.","zh":"如果認證帶來更高價格，它可能提供誘因去種植更多蔭下咖啡。"},{"en":"The phrase shows how rewards can shape behaviour.","zh":"這個短語顯示獎勵如何塑造行為。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":14},{"front":"convert existing areas of","meaning":"改變現有……地區的用途","examples":[{"en":"Farmers may convert existing areas of primary forest into plantations.","zh":"農民可能把現有原始森林地區改造成種植園。"},{"en":"To convert existing areas of land means to change land already there into a different use.","zh":"「convert existing areas of」土地，意思是把原本存在的土地改作另一用途。"},{"en":"A city may convert existing areas of old factories into housing.","zh":"城市可能把現有舊工廠區改造成住宅。"},{"en":"If farmers convert primary forest into plantations, natural habitat may be lost.","zh":"如果農民把原始森林改造成種植園，天然棲息地可能流失。"},{"en":"The phrase focuses on changing land use.","zh":"這個短語集中於改變土地用途。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":14},{"front":"primary forest","meaning":"原始森林","examples":[{"en":"Primary forest may be converted into shade-coffee plantations.","zh":"原始森林可能被改造成蔭下咖啡種植園。"},{"en":"Primary forest is original forest that has not been heavily disturbed by human activity.","zh":"「primary forest」是未受人類活動嚴重干擾的原生森林。"},{"en":"Primary forest often contains old trees, complex layers and many specialised species.","zh":"原始森林常包含老樹、複雜層次和許多專門化物種。"},{"en":"If primary forest is converted, its ecological value may not be replaced by plantations.","zh":"如果原始森林被改造，其生態價值未必能由種植園取代。"},{"en":"The phrase describes especially valuable natural forest.","zh":"這個短語描述特別有價值的天然森林。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":14},{"front":"too remote or steep","meaning":"過於偏遠或陡峭","examples":[{"en":"Some forests are too remote or steep for other forms of cultivation.","zh":"有些森林過於偏遠或陡峭，不適合其他耕作形式。"},{"en":"Too remote or steep means too far away or too sharply sloped to be used easily.","zh":"「too remote or steep」意思是太遠或坡度太大，難以容易使用。"},{"en":"A village may be too remote for daily bus service.","zh":"一條村可能過於偏遠，無法提供每日巴士服務。"},{"en":"If land is too steep, ordinary farming may be difficult and expensive.","zh":"如果土地過於陡峭，普通耕作可能困難且昂貴。"},{"en":"The phrase explains why some land has not been converted before.","zh":"這個短語解釋為何有些土地之前沒有被改造。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":14},{"front":"profitably","meaning":"有利可圖地","examples":[{"en":"Some areas cannot be profitably converted to ordinary cultivation.","zh":"有些地區不能有利可圖地轉為普通耕作。"},{"en":"Profitably means in a way that earns more money than it costs.","zh":"「profitably」意思是以收入高於成本的方式。"},{"en":"A small shop cannot operate profitably if rent is higher than sales.","zh":"如果租金高於銷售額，小店就不能有利可圖地經營。"},{"en":"If land cannot be profitably farmed, people may leave it as forest unless a new market appears.","zh":"如果土地不能有利可圖地耕作，除非出現新市場，否則人們可能保留其森林狀態。"},{"en":"The word focuses on financial gain.","zh":"這個詞集中於經濟收益。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":14},{"front":"other forms of cultivation","meaning":"其他耕作形式","examples":[{"en":"Remote forests may be unsuitable for other forms of cultivation.","zh":"偏遠森林可能不適合其他耕作形式。"},{"en":"Other forms of cultivation are different ways of growing crops or using land for farming.","zh":"「other forms of cultivation」是種植作物或把土地用於農業的其他方式。"},{"en":"Rice farming and vegetable farming are different forms of cultivation.","zh":"種稻和種菜是不同耕作形式。"},{"en":"If land is too steep for ordinary crops, farmers may look for other forms of cultivation.","zh":"如果土地對普通作物來說太陡峭，農民可能尋找其他耕作形式。"},{"en":"The phrase compares one farming method with alternatives.","zh":"這個短語把一種耕作方法與替代方式比較。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":14},{"front":"shade-coffee plantations","meaning":"蔭下咖啡種植園","examples":[{"en":"Primary forest could be converted into shade-coffee plantations.","zh":"原始森林可能被改造成蔭下咖啡種植園。"},{"en":"Shade-coffee plantations are farms where coffee is grown under tree shade.","zh":"「shade-coffee plantations」是在樹蔭下種植咖啡的農場。"},{"en":"Some shade-coffee plantations can support birds, but they are not always equal to natural forests.","zh":"有些蔭下咖啡種植園可以支持鳥類，但它們不一定等同天然森林。"},{"en":"If primary forest is converted into plantations, biodiversity may still decline.","zh":"如果原始森林被改造成種植園，生物多樣性仍可能下降。"},{"en":"The phrase describes a farm type, not untouched forest.","zh":"這個短語描述一種農場類型，而不是未受干擾的森林。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":14},{"front":"argue the case for","meaning":"為……提出理據","examples":[{"en":"Some conservationists argue the case for shade coffee.","zh":"有些保育人士為蔭下咖啡提出理據。"},{"en":"To argue the case for something means to give reasons supporting it.","zh":"「argue the case for」某事，意思是提出支持它的理由。"},{"en":"A student may argue the case for later school start times by citing sleep research.","zh":"學生可能引用睡眠研究，為較遲上課時間提出理據。"},{"en":"If conservationists argue for shade coffee, they may point to bird habitat and farmer income.","zh":"如果保育人士為蔭下咖啡提出理據，他們可能指出鳥類棲息地和農民收入。"},{"en":"The phrase means presenting a defence or support.","zh":"這個短語意思是提出辯護或支持。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":15},{"front":"different types of","meaning":"不同種類的……","examples":[{"en":"There are different types of shade growing.","zh":"蔭下種植有不同種類。"},{"en":"Different types of something means several forms or categories of it.","zh":"「different types of」某物，意思是它有幾種形式或類別。"},{"en":"There are different types of public transport, such as buses, trains and ferries.","zh":"公共交通有不同種類，例如巴士、火車和渡輪。"},{"en":"If there are different types of shade farming, certification must judge them separately.","zh":"如果蔭下耕作有不同種類，認證就必須分開判斷它們。"},{"en":"The phrase warns readers not to treat one category as all the same.","zh":"這個短語提醒讀者不要把一個類別視為全都一樣。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":15},{"front":"shade growing","meaning":"蔭下種植","examples":[{"en":"Shade growing can benefit wildlife when it meets strict criteria.","zh":"當蔭下種植符合嚴格標準，它可以有益於野生動物。"},{"en":"Shade growing is the practice of growing crops under tree cover.","zh":"「shade growing」是在樹冠覆蓋下種植作物的做法。"},{"en":"Farmers may use shade growing for coffee or cocoa in tropical regions.","zh":"農民可能在熱帶地區對咖啡或可可使用蔭下種植。"},{"en":"If shade growing keeps diverse trees, it can provide habitat for birds and insects.","zh":"如果蔭下種植保留多樣樹木，它可以為鳥類和昆蟲提供棲息地。"},{"en":"The phrase describes a farming method that depends on shade.","zh":"這個短語描述依賴遮蔭的耕作方法。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":15},{"front":"subsistence farmers","meaning":"自給農民","examples":[{"en":"Subsistence farmers often use systems similar to natural forests.","zh":"自給農民常使用類似天然森林的系統。"},{"en":"Subsistence farmers grow mainly enough food or crops to support themselves and their families.","zh":"「subsistence farmers」主要種植足夠支持自己和家人的食物或作物。"},{"en":"A subsistence farmer may sell a little surplus but does not run a large commercial farm.","zh":"自給農民可能出售少量剩餘作物，但不經營大型商業農場。"},{"en":"If subsistence farmers use mixed crops and trees, their land may remain biodiverse.","zh":"如果自給農民使用混合作物和樹木，其土地可能保持生物多樣性。"},{"en":"The phrase focuses on survival farming rather than large-scale profit.","zh":"這個短語集中於維生農業，而不是大規模利潤。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":15},{"front":"virtually identical to","meaning":"幾乎完全相同於","examples":[{"en":"Some shade plantations are virtually identical to natural forests.","zh":"有些蔭下種植園幾乎完全相同於天然森林。"},{"en":"Virtually identical to means almost exactly the same as something else.","zh":"「virtually identical to」意思是幾乎與另一事物完全一樣。"},{"en":"The two exam papers were virtually identical except for the order of questions.","zh":"兩份試卷除了題目順序外幾乎完全相同。"},{"en":"If a plantation is virtually identical to forest, wildlife may use it in similar ways.","zh":"如果種植園幾乎與森林相同，野生動物可能以相似方式使用它。"},{"en":"The phrase means the difference is very small.","zh":"這個短語表示差異非常小。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":15},{"front":"comparable diversity","meaning":"可比的多樣性","examples":[{"en":"These plantations have comparable diversity to natural forests.","zh":"這些種植園具有可與天然森林相比的多樣性。"},{"en":"Comparable diversity means a similar level of variety in species or life forms.","zh":"「comparable diversity」指物種或生命形式的多樣程度相似。"},{"en":"Two school gardens may have comparable diversity if both contain many plants and insects.","zh":"如果兩個學校花園都包含許多植物和昆蟲，它們可能有可比的多樣性。"},{"en":"If a farm has comparable diversity to forest, it may have high conservation value.","zh":"如果農場具有可與森林相比的多樣性，它可能有高保育價值。"},{"en":"The phrase makes a careful similarity comparison.","zh":"這個短語作出謹慎的相似比較。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":15},{"front":"coffee plants as the understorey","meaning":"以咖啡樹作下層植被","examples":[{"en":"Some plantations use coffee plants as the understorey.","zh":"有些種植園以咖啡樹作下層植被。"},{"en":"Coffee plants as the understorey means coffee grows in the lower plant layer beneath taller trees.","zh":"「coffee plants as the understorey」意思是咖啡在較高樹木下方的低層植物層生長。"},{"en":"In a forest garden, herbs can form the understorey below fruit trees.","zh":"在森林花園中，香草可以在果樹下方形成下層植被。"},{"en":"If coffee grows as the understorey, the farm keeps an upper tree layer.","zh":"如果咖啡作為下層植被生長，農場就保留上層樹木。"},{"en":"The phrase describes the vertical structure of a shade plantation.","zh":"這個短語描述蔭下種植園的垂直結構。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":15},{"front":"cacao or citrus trees","meaning":"可可樹或柑橘樹","examples":[{"en":"Some plantations use cacao or citrus trees as the overstorey.","zh":"有些種植園以可可樹或柑橘樹作上層植被。"},{"en":"Cacao or citrus trees are trees that produce cocoa beans or citrus fruits such as oranges and lemons.","zh":"「cacao or citrus trees」是生產可可豆或橙、檸檬等柑橘水果的樹。"},{"en":"A farm may grow citrus trees above smaller crops to provide partial shade.","zh":"農場可能在較小作物上方種植柑橘樹，以提供部分遮蔭。"},{"en":"If cacao or citrus trees form the upper layer, they can provide both crops and habitat structure.","zh":"如果可可樹或柑橘樹形成上層，它們可以同時提供作物和棲息地結構。"},{"en":"The phrase names possible shade-tree crops.","zh":"這個短語指出可能用作遮蔭樹的作物。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":15},{"front":"overstorey","meaning":"上層植被","examples":[{"en":"Cacao or citrus trees may form the overstorey.","zh":"可可樹或柑橘樹可能形成上層植被。"},{"en":"The overstorey is the upper layer of taller plants or trees above lower vegetation.","zh":"「overstorey」是位於較低植被上方的高大植物或樹木上層。"},{"en":"In a forest, tall trees form the overstorey while shrubs grow below.","zh":"在森林中，高大樹木形成上層植被，而灌木在下方生長。"},{"en":"If a plantation has an overstorey, crops underneath receive shade and shelter.","zh":"如果種植園有上層植被，下方作物會得到遮蔭和庇護。"},{"en":"The phrase describes vertical layers in vegetation.","zh":"這個短語描述植被的垂直層次。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":15},{"front":"no more diverse than","meaning":"不比……更多樣化","examples":[{"en":"Some shade plantations are no more diverse than full-sun farms.","zh":"有些蔭下種植園不比全日照農場更多樣化。"},{"en":"No more diverse than means not having greater variety than another thing.","zh":"「no more diverse than」意思是多樣性不高於另一事物。"},{"en":"A garden with only one plant type is no more diverse than a plain lawn.","zh":"只種一種植物的花園，不比普通草坪更多樣化。"},{"en":"If a shade plantation has only a few tree species, it may be no more diverse than full-sun farming.","zh":"如果蔭下種植園只有少數樹種，它可能不比全日照耕作更多樣化。"},{"en":"The phrase warns that shade alone does not guarantee biodiversity.","zh":"這個短語提醒人們，單有遮蔭不保證生物多樣性。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":15},{"front":"certification procedures","meaning":"認證程序","examples":[{"en":"Certification procedures need to distinguish between different systems.","zh":"認證程序需要區分不同系統。"},{"en":"Certification procedures are the steps used to check whether a product meets official standards.","zh":"「certification procedures」是檢查產品是否符合官方標準的步驟。"},{"en":"A food label may require certification procedures before it can claim to be organic.","zh":"食品標籤在聲稱有機前，可能需要認證程序。"},{"en":"If procedures are weak, products may receive labels without truly protecting wildlife.","zh":"如果程序薄弱，產品可能獲得標籤卻沒有真正保護野生動物。"},{"en":"The phrase focuses on how certification is checked and approved.","zh":"這個短語集中於認證如何被檢查和批准。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":15},{"front":"distinguish between","meaning":"區分","examples":[{"en":"Certification must distinguish between high-value and low-value shade systems.","zh":"認證必須區分高價值和低價值的蔭下系統。"},{"en":"To distinguish between things means to recognise the difference between them.","zh":"「distinguish between」幾件事，意思是辨認它們之間的差異。"},{"en":"Students must distinguish between fact and opinion in reading tests.","zh":"學生在閱讀測驗中必須區分事實和意見。"},{"en":"If labels cannot distinguish between good and poor shade systems, consumers may be misled.","zh":"如果標籤不能區分良好和差劣蔭下系統，消費者可能被誤導。"},{"en":"The phrase is about accurate separation or comparison.","zh":"這個短語關於準確分辨或比較。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":16},{"front":"as long as","meaning":"只要","examples":[{"en":"Shade growing benefits the environment as long as the process is rigorous.","zh":"只要程序嚴謹，蔭下種植就對環境有益。"},{"en":"As long as means only if a condition is met.","zh":"「as long as」意思是只有在某條件符合時。"},{"en":"Students can use a dictionary as long as the teacher allows it.","zh":"只要老師允許，學生可以使用字典。"},{"en":"Shade certification can help wildlife as long as farms meet strict standards.","zh":"只要農場符合嚴格標準，蔭下認證就可以幫助野生動物。"},{"en":"The phrase introduces a condition that must be true.","zh":"這個短語引入必須成立的條件。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":16},{"front":"the process is rigorous","meaning":"程序嚴謹","examples":[{"en":"The certification process must be rigorous.","zh":"認證程序必須嚴謹。"},{"en":"If a process is rigorous, it is strict, careful and thorough.","zh":"如果程序嚴謹，它就是嚴格、仔細且全面的。"},{"en":"A rigorous exam checks understanding rather than simple memorisation.","zh":"嚴謹的考試檢查理解，而不只是簡單記憶。"},{"en":"If certification is rigorous, weak farms cannot easily receive the label.","zh":"如果認證嚴謹，差劣農場就不能輕易獲得標籤。"},{"en":"The phrase emphasises high standards and careful checking.","zh":"這個短語強調高標準和仔細檢查。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":16},{"front":"offer financial gains to","meaning":"為……提供經濟收益","examples":[{"en":"Certification should offer financial gains to producers.","zh":"認證應為生產者提供經濟收益。"},{"en":"To offer financial gains to someone means to give them a chance to earn more money.","zh":"「offer financial gains to」某人，意思是給他們賺取更多金錢的機會。"},{"en":"A bonus scheme can offer financial gains to workers who meet safety targets.","zh":"獎金制度可以為達到安全目標的工人提供經濟收益。"},{"en":"If shade certification offers financial gains to farmers, they may keep wildlife-friendly systems.","zh":"如果蔭下認證為農民提供經濟收益，他們可能保留野生動物友善系統。"},{"en":"The phrase shows the economic benefit of a policy or scheme.","zh":"這個短語顯示政策或計劃的經濟好處。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":16},{"front":"producers","meaning":"生產者","examples":[{"en":"The process should benefit producers as well as wildlife.","zh":"該程序應有利於生產者，也有利於野生動物。"},{"en":"Producers are people, farms or companies that make or grow goods.","zh":"「producers」是製造或種植貨品的人、農場或公司。"},{"en":"Coffee producers may include small farmers, cooperatives and larger farms.","zh":"咖啡生產者可能包括小農、合作社和較大型農場。"},{"en":"If producers earn too little, conservation-friendly production may not continue.","zh":"如果生產者收入太少，保育友善的生產可能無法持續。"},{"en":"The word focuses on those who create the product before it reaches consumers.","zh":"這個詞集中於產品到達消費者前創造產品的人。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":16},{"front":"benefit the environment","meaning":"對環境有益","examples":[{"en":"Rigorous shade-growing certification can benefit the environment.","zh":"嚴謹的蔭下種植認證可以對環境有益。"},{"en":"To benefit the environment means to help nature or reduce harm to ecosystems.","zh":"「benefit the environment」意思是幫助自然或減少對生態系統的傷害。"},{"en":"Planting native trees can benefit the environment by supporting birds and insects.","zh":"種植本地樹木可以透過支持鳥類和昆蟲而對環境有益。"},{"en":"If certification protects real shade farms, it can benefit the environment and farmers together.","zh":"如果認證保護真正的蔭下農場，它可以同時對環境和農民有益。"},{"en":"The phrase describes a positive environmental effect.","zh":"這個短語描述正面的環境影響。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":16},{"front":"agree with the information given in","meaning":"與文中資料一致","examples":[{"en":"Candidates decide whether the statements agree with the information given in the passage.","zh":"考生判斷陳述是否與文章中提供的資料一致。"},{"en":"To agree with the information given in a passage means to match what the text says.","zh":"「agree with the information given in」文章，意思是符合文本所說。"},{"en":"In a reading test, students should choose TRUE only when the statement is clearly supported.","zh":"在閱讀測驗中，只有陳述被清楚支持時，學生才應選 TRUE。"},{"en":"If a statement adds information not in the passage, it may not agree with the information given.","zh":"如果陳述加入文章沒有的資料，它可能不與所給資料一致。"},{"en":"The phrase reminds students to answer from evidence, not background knowledge.","zh":"這個短語提醒學生根據證據作答，而不是背景知識。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":16},{"front":"write TRUE if","meaning":"如果……則寫TRUE","examples":[{"en":"Students write TRUE if the statement agrees with the information.","zh":"如果陳述與資料一致，學生寫 TRUE。"},{"en":"Write TRUE if means choose TRUE only when a condition is satisfied.","zh":"「write TRUE if」意思是只有在條件符合時才選 TRUE。"},{"en":"Students write TRUE if the passage clearly says the same idea.","zh":"如果文章清楚說出同一意思，學生寫 TRUE。"},{"en":"If the statement is only partly supported, students should check carefully before writing TRUE.","zh":"如果陳述只得到部分支持，學生在寫 TRUE 前應仔細核對。"},{"en":"The phrase gives a precise test instruction.","zh":"這個短語給出精確考試指示。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":16},{"front":"contradict the information","meaning":"與資料矛盾","examples":[{"en":"A statement is false if it contradicts the information.","zh":"如果陳述與資料矛盾，它就是錯的。"},{"en":"To contradict the information means to say the opposite of what the passage says.","zh":"「contradict the information」意思是說出與文章所說相反的內容。"},{"en":"If the text says coffee is shade-grown but the statement says it is grown in full sun, it contradicts the information.","zh":"如果文本說咖啡是蔭下種植，但陳述說它在全日照下種植，該陳述就與資料矛盾。"},{"en":"Students should choose FALSE only when the conflict is clear.","zh":"學生只應在衝突清楚時選 FALSE。"},{"en":"The phrase is used for checking accuracy against a source.","zh":"這個短語用於根據來源檢查準確性。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":16},{"front":"there is no information on this","meaning":"文中沒有相關資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果文中沒有相關資料，學生寫 NOT GIVEN。"},{"en":"There is no information on this means the passage does not clearly mention the point.","zh":"「there is no information on this」意思是文章沒有清楚提及該點。"},{"en":"If a text never says whether farmers prefer one method, there is no information on this.","zh":"如果文本從未說農民是否較喜歡某方法，文中就沒有相關資料。"},{"en":"A statement may sound possible, but without evidence it should not be treated as true.","zh":"某陳述可能聽起來合理，但沒有證據時不應被視為真。"},{"en":"The phrase helps students avoid guessing.","zh":"這個短語幫助學生避免猜測。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":16},{"front":"survive on","meaning":"在……中生存","examples":[{"en":"The question asks whether more species survive on the studied farms.","zh":"問題問是否有更多物種在研究人員研究的農場中生存。"},{"en":"To survive on a place or resource means to continue living there or because of it.","zh":"「survive on」某地或資源，意思是在那裡或依靠它繼續生存。"},{"en":"Some insects survive on dead leaves and fallen fruit.","zh":"有些昆蟲靠枯葉和落果生存。"},{"en":"If many species survive on shade farms, those farms have ecological value.","zh":"如果許多物種在蔭下農場生存，這些農場就有生態價值。"},{"en":"The phrase connects survival with habitat or food supply.","zh":"這個短語把生存與棲息地或食物供應連繫起來。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":16},{"front":"farms studied by the researchers","meaning":"研究人員研究的農場","examples":[{"en":"The farms studied by the researchers contained many species.","zh":"研究人員研究的農場包含許多物種。"},{"en":"Farms studied by the researchers are the particular farms included in the research.","zh":"「farms studied by the researchers」是被納入研究的特定農場。"},{"en":"In a report, the schools studied by researchers may not represent every school in the country.","zh":"在報告中，研究人員研究的學校未必代表全國每一所學校。"},{"en":"If the studied farms contain many species, the findings apply first to those farms.","zh":"如果被研究的農場包含許多物種，研究發現首先適用於那些農場。"},{"en":"The phrase limits the claim to the research sample.","zh":"這個短語把說法限制在研究樣本之內。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":17},{"front":"natural El Salvador forests","meaning":"薩爾瓦多天然森林","examples":[{"en":"The statement compares farms with natural El Salvador forests.","zh":"該陳述把農場與薩爾瓦多天然森林作比較。"},{"en":"Natural El Salvador forests are naturally developed forests in El Salvador.","zh":"「natural El Salvador forests」是薩爾瓦多境內自然形成的森林。"},{"en":"A researcher may compare farms with natural forests to judge habitat value.","zh":"研究人員可能把農場與天然森林比較，以判斷棲息地價值。"},{"en":"If farms support more species than nearby forests, the result would be surprising and important.","zh":"如果農場支持比附近森林更多物種，結果就會令人驚訝且重要。"},{"en":"The phrase sets up a comparison between farmland and native forest.","zh":"這個短語建立農地與本地森林之間的比較。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":17},{"front":"nearly three-quarters of","meaning":"接近四分之三的……","examples":[{"en":"The statement refers to nearly three-quarters of Earth’s wildlife species.","zh":"該陳述提到接近四分之三的地球野生動物物種。"},{"en":"Nearly three-quarters of something means almost 75 percent of it.","zh":"「nearly three-quarters of」某物，意思是接近百分之七十五。"},{"en":"Nearly three-quarters of the class joined the school trip.","zh":"班上接近四分之三學生參加了學校旅行。"},{"en":"If a habitat supports nearly three-quarters of species, it is extremely important.","zh":"如果棲息地支持接近四分之三物種，它就極其重要。"},{"en":"The phrase gives a large but approximate proportion.","zh":"這個短語提供一個很大但大約的比例。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":17},{"front":"Earth’s wildlife species","meaning":"地球上的野生動物物種","examples":[{"en":"The question discusses Earth’s wildlife species.","zh":"問題討論地球上的野生動物物種。"},{"en":"Earth’s wildlife species are the different kinds of wild animals living on the planet.","zh":"「Earth’s wildlife species」是生活在地球上的不同種類野生動物。"},{"en":"Forests, wetlands and oceans all support Earth’s wildlife species.","zh":"森林、濕地和海洋都支持地球上的野生動物物種。"},{"en":"If major habitats disappear, many of Earth’s wildlife species may decline.","zh":"如果主要棲息地消失，地球上許多野生動物物種可能下降。"},{"en":"The phrase gives a global wildlife perspective.","zh":"這個短語提供全球野生動物視角。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":17},{"front":"shade-coffee plantations","meaning":"蔭下咖啡種植園","examples":[{"en":"The question asks about species in shade-coffee plantations.","zh":"問題問及蔭下咖啡種植園中的物種。"},{"en":"Shade-coffee plantations are coffee-growing areas where trees provide shade above the crop.","zh":"「shade-coffee plantations」是有樹木在作物上方提供遮蔭的咖啡種植區。"},{"en":"A shade-coffee plantation may contain coffee plants, tall trees, insects and birds.","zh":"蔭下咖啡種植園可能包含咖啡樹、高大樹木、昆蟲和鳥類。"},{"en":"If a plantation is diverse, it may support wildlife better than full-sun farming.","zh":"如果種植園多樣化，它可能比全日照耕作更好支持野生動物。"},{"en":"The phrase describes a managed farm with tree cover.","zh":"這個短語描述有樹冠覆蓋的受管理農場。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":17},{"front":"try both methods","meaning":"嘗試過兩種方法","examples":[{"en":"The statement refers to farmers who have tried both methods.","zh":"該陳述指嘗試過兩種方法的農民。"},{"en":"To try both methods means to test two different ways of doing something.","zh":"「try both methods」意思是測試兩種不同做事方式。"},{"en":"A student may try both methods of revision before choosing the one that works best.","zh":"學生可能嘗試過兩種溫習方法，再選擇最有效的一種。"},{"en":"If farmers try both shade and full-sun systems, they can compare cost, yield and wildlife effects.","zh":"如果農民嘗試蔭下和全日照兩種系統，他們可以比較成本、產量和野生動物影響。"},{"en":"The phrase describes practical comparison through experience.","zh":"這個短語描述透過經驗進行實際比較。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":17},{"front":"prefer shade-grown plantations","meaning":"較喜歡蔭下種植園","examples":[{"en":"The statement asks whether farmers prefer shade-grown plantations.","zh":"該陳述問農民是否較喜歡蔭下種植園。"},{"en":"To prefer shade-grown plantations means to choose or like tree-shaded farms more than other systems.","zh":"「prefer shade-grown plantations」意思是比其他系統更選擇或喜歡有樹蔭的農場。"},{"en":"A farmer may prefer shade-grown plantations if they provide extra fruit, wood and habitat benefits.","zh":"如果蔭下種植園提供額外水果、木材和棲息地好處，農民可能較喜歡它們。"},{"en":"If full-sun farms earn more money, some farmers may not prefer shade systems despite ecological benefits.","zh":"如果全日照農場賺更多錢，即使蔭下系統有生態好處，有些農民也未必較喜歡它。"},{"en":"The phrase asks about preference, not only environmental value.","zh":"這個短語問的是偏好，而不只是環境價值。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":17},{"front":"important for migrating birds","meaning":"對候鳥重要","examples":[{"en":"Shade plantations are important for migrating birds.","zh":"蔭下種植園對候鳥重要。"},{"en":"Important for migrating birds means useful or necessary for birds that travel seasonally.","zh":"「important for migrating birds」意思是對按季節遷徙的鳥類有用或必要。"},{"en":"Wetlands are important for migrating birds because they offer food and rest during long journeys.","zh":"濕地對候鳥重要，因為它們在長途旅程中提供食物和休息地。"},{"en":"If shade plantations disappear, migrating birds may lose safe stopping or wintering places.","zh":"如果蔭下種植園消失，候鳥可能失去安全停留或越冬地。"},{"en":"The phrase links habitat value with bird movement.","zh":"這個短語把棲息地價值與鳥類遷徙連繫起來。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":17},{"front":"both Africa and the Americas","meaning":"非洲和美洲兩地","examples":[{"en":"The passage discusses shade plantations in both Africa and the Americas.","zh":"文章討論非洲和美洲兩地的蔭下種植園。"},{"en":"Both Africa and the Americas means the discussion includes these two large regions.","zh":"「both Africa and the Americas」意思是討論包括這兩個大型地區。"},{"en":"Migratory birds can connect both Europe and Africa through seasonal movement.","zh":"候鳥可以透過季節遷徙連接歐洲和非洲。"},{"en":"If the same farming issue appears in both Africa and the Americas, it has international importance.","zh":"如果同一耕作問題出現在非洲和美洲兩地，它就具有國際重要性。"},{"en":"The phrase emphasises two-region coverage.","zh":"這個短語強調涵蓋兩個地區。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":17},{"front":"full-sun cultivation","meaning":"全日照耕作","examples":[{"en":"Full-sun cultivation can reduce wildlife diversity.","zh":"全日照耕作可以減少野生動物多樣性。"},{"en":"Full-sun cultivation is growing crops in direct sunlight without shade trees.","zh":"「full-sun cultivation」是在沒有遮蔭樹下以直射陽光種植作物。"},{"en":"Some crops grow well in full sun, but coffee and cocoa may lose habitat value when shade is removed.","zh":"有些作物在全日照下長得好，但咖啡和可可在遮蔭被移除時可能失去棲息地價值。"},{"en":"If full-sun cultivation replaces shade farming, birds and insects may decline.","zh":"如果全日照耕作取代蔭下耕作，鳥類和昆蟲可能減少。"},{"en":"The phrase describes a farming method with little tree cover.","zh":"這個短語描述樹冠覆蓋很少的耕作方法。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":17},{"front":"increase the costs of farming","meaning":"增加耕作成本","examples":[{"en":"Full-sun cultivation may increase the costs of farming.","zh":"全日照耕作可能增加耕作成本。"},{"en":"To increase the costs of farming means to make farming more expensive.","zh":"「increase the costs of farming」意思是令農業變得更昂貴。"},{"en":"Higher fuel prices can increase the costs of farming by raising transport and machinery expenses.","zh":"燃油價格上升可以透過提高運輸和機械開支來增加耕作成本。"},{"en":"If full-sun farms need more chemicals, their farming costs may rise.","zh":"如果全日照農場需要更多化學品，其耕作成本可能上升。"},{"en":"The phrase describes an economic consequence for farmers.","zh":"這個短語描述對農民的經濟後果。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":17},{"front":"look at the following opinions","meaning":"查看以下意見","examples":[{"en":"Candidates look at the following opinions and match them to people.","zh":"考生查看以下意見，並把它們配對至人物。"},{"en":"Look at the following opinions means read the opinions listed below carefully.","zh":"「look at the following opinions」意思是仔細閱讀下方列出的意見。"},{"en":"In a reading test, students look at the following opinions before scanning for names.","zh":"在閱讀測驗中，學生先查看以下意見，再掃讀尋找人名。"},{"en":"If students misunderstand an opinion, they may match it to the wrong person.","zh":"如果學生誤解某個意見，他們可能把它配對到錯誤人物。"},{"en":"The phrase gives an exam instruction.","zh":"這個短語給出考試指示。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":18},{"front":"list of people below","meaning":"下方的人名列表","examples":[{"en":"The task gives a list of people below the opinions.","zh":"該任務在意見下方提供人名列表。"},{"en":"A list of people below means the names are written underneath the question or statements.","zh":"「list of people below」意思是人名寫在問題或陳述下方。"},{"en":"In a matching task, students use the list of people below to choose answers.","zh":"在配對題中，學生使用下方的人名列表選答案。"},{"en":"If one person appears in the list, they may be used once or more depending on instructions.","zh":"如果某人出現在列表中，他們可按指示被使用一次或多次。"},{"en":"The phrase tells students where to find the answer options.","zh":"這個短語告訴學生在哪裡找到答案選項。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":18},{"front":"match each opinion to","meaning":"將每個意見配對至","examples":[{"en":"Candidates match each opinion to the person credited with it.","zh":"考生將每個意見配對至被歸屬於該意見的人。"},{"en":"To match each opinion to someone means to connect each view with the person who expressed it.","zh":"「match each opinion to」某人，意思是把每個看法連到表達它的人。"},{"en":"Students may match each opinion to a speaker in a listening test.","zh":"學生可能在聆聽測驗中將每個意見配對至說話者。"},{"en":"If two experts discuss similar ideas, matching opinions can become difficult.","zh":"如果兩位專家討論相似想法，配對意見可能變得困難。"},{"en":"The phrase tests accurate attribution.","zh":"這個短語測試準確歸屬。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":18},{"front":"be credited with","meaning":"歸功於；歸於","examples":[{"en":"The opinion is credited with a named person.","zh":"該意見被歸於一位具名人士。"},{"en":"To be credited with something means to be recognised as the person responsible for it.","zh":"「be credited with」某事，意思是被認為是對它負責或作出貢獻的人。"},{"en":"A scientist may be credited with discovering a new species.","zh":"科學家可能被認為發現了一個新物種。"},{"en":"If an opinion is credited to one researcher, students should match it with that name.","zh":"如果某意見被歸於一位研究人員，學生應把它與該名字配對。"},{"en":"The phrase is about giving recognition or attribution.","zh":"這個短語關於給予認可或歸屬。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":18},{"front":"encouraging shade growing","meaning":"鼓勵蔭下種植","examples":[{"en":"The question discusses the effects of encouraging shade growing.","zh":"問題討論鼓勵蔭下種植的影響。"},{"en":"Encouraging shade growing means promoting or supporting the practice of growing crops under trees.","zh":"「encouraging shade growing」意思是推廣或支持在樹下種植作物的做法。"},{"en":"A charity may encourage shade growing by helping farmers sell certified coffee.","zh":"慈善機構可能透過幫助農民出售認證咖啡來鼓勵蔭下種植。"},{"en":"If shade growing is encouraged without strict rules, some forests might be converted into plantations.","zh":"如果在沒有嚴格規則下鼓勵蔭下種植，有些森林可能被改造成種植園。"},{"en":"The phrase focuses on influencing farmers’ choices.","zh":"這個短語集中於影響農民選擇。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":18},{"front":"lead to farmers using","meaning":"導致農民使用","examples":[{"en":"Encouraging shade growing may lead to farmers using natural forest.","zh":"鼓勵蔭下種植可能導致農民使用天然森林。"},{"en":"Lead to farmers using something means cause farmers to start using it.","zh":"「lead to farmers using」某物，意思是造成農民開始使用它。"},{"en":"Higher vegetable prices may lead to farmers using more land for vegetable crops.","zh":"蔬菜價格上升可能導致農民使用更多土地種植蔬菜。"},{"en":"If shade certification pays more, it may lead to farmers using forest areas for coffee.","zh":"如果蔭下認證帶來更高價格，它可能導致農民使用森林地區種咖啡。"},{"en":"The phrase shows a possible consequence of an incentive.","zh":"這個短語顯示誘因可能帶來的後果。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":18},{"front":"match the right criteria","meaning":"符合正確標準","examples":[{"en":"Shade-coffee farms can help wildlife if they match the right criteria.","zh":"如果蔭下咖啡農場符合正確標準，它們可以幫助野生動物。"},{"en":"To match the right criteria means to meet the correct standards or conditions.","zh":"「match the right criteria」意思是符合正確標準或條件。"},{"en":"A student scholarship may require applicants to match the right criteria, such as grades and income level.","zh":"學生獎學金可能要求申請人符合正確標準，例如成績和收入水平。"},{"en":"If a farm does not match biodiversity criteria, it should not receive a wildlife-friendly label.","zh":"如果農場不符合生物多樣性標準，它不應獲得野生動物友善標籤。"},{"en":"The phrase is about meeting standards, not simply making a claim.","zh":"這個短語關於符合標準，而不只是作出聲稱。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":18},{"front":"good for wildlife","meaning":"對野生動物有益","examples":[{"en":"Shade farms can be good for wildlife under certain conditions.","zh":"在某些條件下，蔭下農場可以對野生動物有益。"},{"en":"Good for wildlife means helpful to wild animals, plants and their habitats.","zh":"「good for wildlife」意思是有助野生動物、植物及其棲息地。"},{"en":"Leaving dead wood in a park can be good for wildlife because insects and birds use it.","zh":"在公園保留枯木可以對野生動物有益，因為昆蟲和鳥類會利用它。"},{"en":"If shade farms keep diverse trees, they can be good for wildlife.","zh":"如果蔭下農場保留多樣樹木，它們可以對野生動物有益。"},{"en":"The phrase requires context because not every shaded farm is equally valuable.","zh":"這個短語需要語境，因為不是每個有遮蔭農場都有同等價值。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":18},{"front":"in a particular area","meaning":"在某一特定地區","examples":[{"en":"The question refers to bird species in a particular area.","zh":"問題提到某一特定地區的鳥類物種。"},{"en":"In a particular area means in one specific place or region.","zh":"「in a particular area」意思是在某一具體地方或地區。"},{"en":"A teacher may ask students to study traffic problems in a particular area near school.","zh":"老師可能要求學生研究學校附近某一特定地區的交通問題。"},{"en":"If bird species are counted in a particular area, the result may not apply everywhere.","zh":"如果鳥類物種只在某一特定地區點算，結果未必適用於所有地方。"},{"en":"The phrase narrows the location being discussed.","zh":"這個短語收窄正在討論的位置。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":18},{"front":"natural habitats","meaning":"天然棲息地","examples":[{"en":"Shade farms may rival natural habitats in bird diversity.","zh":"蔭下農場在鳥類多樣性上可能可媲美天然棲息地。"},{"en":"Natural habitats are places where species live without being created mainly by humans.","zh":"「natural habitats」是物種生活、且不是主要由人類創造的地方。"},{"en":"Rivers, forests and wetlands can be natural habitats for many animals.","zh":"河流、森林和濕地可以是許多動物的天然棲息地。"},{"en":"If farming replaces natural habitats, species may struggle unless the farms keep similar features.","zh":"如果農業取代天然棲息地，除非農場保留相似特徵，物種可能難以生存。"},{"en":"The phrase describes real living environments for wildlife.","zh":"這個短語描述野生動物真正的生活環境。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":18},{"front":"earn very little","meaning":"收入很少","examples":[{"en":"Many shade-coffee farmers currently earn very little.","zh":"許多蔭下咖啡農民目前收入很少。"},{"en":"To earn very little means to receive only a small amount of income.","zh":"「earn very little」意思是只獲得很少收入。"},{"en":"A part-time worker may earn very little if they get only a few hours each week.","zh":"如果兼職工每星期只有很少工作時數，他可能收入很少。"},{"en":"If farmers earn very little, they may be unable to invest in sustainable methods.","zh":"如果農民收入很少，他們可能無法投資可持續方法。"},{"en":"The phrase highlights economic hardship.","zh":"這個短語強調經濟困難。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":18},{"front":"classify the features","meaning":"將特徵分類","examples":[{"en":"Candidates classify the features according to farming method.","zh":"考生根據耕作方法將特徵分類。"},{"en":"To classify the features means to sort characteristics into groups.","zh":"「classify the features」意思是把特徵分成不同組別。"},{"en":"Students may classify animals by habitat, diet or body structure.","zh":"學生可能按棲息地、飲食或身體結構將動物分類。"},{"en":"If features apply to different farming methods, classification helps organise the information.","zh":"如果特徵適用於不同耕作方法，分類有助整理資料。"},{"en":"The phrase is common in matching or table-completion tasks.","zh":"這個短語常見於配對或表格填充題。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":19},{"front":"features described below","meaning":"以下描述的特徵","examples":[{"en":"The task asks about the features described below.","zh":"該任務問及以下描述的特徵。"},{"en":"Features described below are the characteristics listed underneath the instruction.","zh":"「features described below」是指示下方列出的特徵。"},{"en":"In a test, students should read the features described below before choosing categories.","zh":"在測驗中，學生應先閱讀以下描述的特徵，再選擇分類。"},{"en":"If a feature is not in the passage, students should not classify it from outside knowledge.","zh":"如果某特徵不在文章中，學生不應根據外部知識分類。"},{"en":"The phrase points students to the items they must analyse.","zh":"這個短語指向學生必須分析的項目。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":19},{"front":"apply to","meaning":"適用於","examples":[{"en":"The feature may apply to shade-grown or full-sun methods.","zh":"該特徵可能適用於蔭下種植或全日照方法。"},{"en":"To apply to something means to be relevant or true for it.","zh":"「apply to」某物，意思是與它相關或對它為真。"},{"en":"A discount may apply to students but not to adults.","zh":"折扣可能適用於學生，但不適用於成人。"},{"en":"If a feature applies to full-sun farming, it should be matched with that method.","zh":"如果某特徵適用於全日照耕作，它就應與該方法配對。"},{"en":"The phrase helps decide which category something belongs to.","zh":"這個短語幫助決定某事屬於哪個類別。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":19},{"front":"either coffee or cocoa plantations","meaning":"咖啡或可可種植園其中之一","examples":[{"en":"The method can be used on either coffee or cocoa plantations.","zh":"該方法可以用於咖啡或可可種植園其中之一。"},{"en":"Either coffee or cocoa plantations means one of the two types of plantations, or possibly both depending on context.","zh":"「either coffee or cocoa plantations」意思是兩類種植園其中之一，或按語境可能兩者都包括。"},{"en":"A farming rule may apply to either apple or pear orchards if both face the same pest.","zh":"如果蘋果園和梨園面對同一害蟲，農業規則可能適用於其中之一或兩者。"},{"en":"If shade growing works for either crop, conservation labels may cover more than coffee.","zh":"如果蔭下種植適用於其中一種作物，保育標籤可能涵蓋的不只是咖啡。"},{"en":"The phrase compares two possible crop settings.","zh":"這個短語比較兩種可能作物環境。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":19},{"front":"be expected to produce","meaning":"預期會生產","examples":[{"en":"Full-sun methods are expected to produce bigger crops.","zh":"全日照方法預期會生產更大的收成。"},{"en":"To be expected to produce something means people think a method will create that result.","zh":"「be expected to produce」某物，意思是人們認為某方法會產生該結果。"},{"en":"A new study plan is expected to produce better exam performance.","zh":"新學習計劃預期會帶來更好考試表現。"},{"en":"If full-sun farming is expected to produce bigger crops, farmers may choose it for income reasons.","zh":"如果全日照耕作預期會生產更大收成，農民可能因收入原因選擇它。"},{"en":"The phrase describes an anticipated outcome.","zh":"這個短語描述預期結果。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":19},{"front":"bigger crops","meaning":"更大的收成","examples":[{"en":"Full-sun farming is intended to produce bigger crops.","zh":"全日照耕作旨在生產更大的收成。"},{"en":"Bigger crops means larger harvests or greater crop yields.","zh":"「bigger crops」意思是更大的收成或更高作物產量。"},{"en":"Farmers may hope for bigger crops after using better seeds and irrigation.","zh":"使用更好種子和灌溉後，農民可能希望有更大的收成。"},{"en":"If bigger crops require more chemicals, the environmental cost may rise.","zh":"如果更大的收成需要更多化學品，環境成本可能上升。"},{"en":"The phrase focuses on quantity of harvest.","zh":"這個短語集中於收成數量。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":19},{"front":"documentation","meaning":"文件；證明文件","examples":[{"en":"Certification documentation may encourage sales.","zh":"認證文件可能促進銷售。"},{"en":"Documentation means written records, forms or proof that support a claim.","zh":"「documentation」指支持某項聲稱的書面記錄、表格或證明。"},{"en":"A traveller needs documentation such as a passport and visa before entering some countries.","zh":"旅客進入一些國家前需要護照和簽證等文件。"},{"en":"If coffee has certification documentation, shops can show customers how it was grown.","zh":"如果咖啡有認證文件，商店可以向顧客顯示它如何種植。"},{"en":"The word refers to evidence in written or official form.","zh":"這個詞指書面或官方形式的證據。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":19},{"front":"encourage sales","meaning":"促進銷售","examples":[{"en":"Certification may be used to encourage sales.","zh":"認證可能被用來促進銷售。"},{"en":"To encourage sales means to help persuade customers to buy more of a product.","zh":"「encourage sales」意思是幫助說服顧客購買更多產品。"},{"en":"A clear label can encourage sales by making a product easier to understand.","zh":"清晰標籤可以透過令產品更容易理解來促進銷售。"},{"en":"If consumers trust bird-friendly certification, the label may encourage sales of shade coffee.","zh":"如果消費者信任鳥類友善認證，該標籤可能促進蔭下咖啡銷售。"},{"en":"The phrase describes a marketing effect.","zh":"這個短語描述市場推廣效果。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":19},{"front":"reduce wildlife diversity","meaning":"降低野生動物多樣性","examples":[{"en":"Full-sun methods can reduce wildlife diversity.","zh":"全日照方法可以降低野生動物多樣性。"},{"en":"To reduce wildlife diversity means to lower the number or variety of wild species in a place.","zh":"「reduce wildlife diversity」意思是降低某地野生物種的數量或種類。"},{"en":"Replacing a mixed garden with concrete can reduce wildlife diversity.","zh":"用混凝土取代混合花園可以降低野生動物多樣性。"},{"en":"If farms remove shade trees, fewer birds and insects may survive there.","zh":"如果農場移除遮蔭樹，能在那裡生存的鳥類和昆蟲可能較少。"},{"en":"The phrase describes a negative ecological effect.","zh":"這個短語描述負面生態影響。"}],"source":"107 - NATURAL CHOICE Coffee and chocolate.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 108":[{"front":"inside the mind of","meaning":"在……的腦海裏；了解……的心理","examples":[{"en":"The passage explores what happens inside the mind of the consumer.","zh":"文章探討消費者腦海裏發生的事情。"},{"en":"Inside the mind of someone means understanding their thoughts, feelings, motives, or decisions.","zh":"“Inside the mind of” 某人指了解他的想法、感受、動機或決定。"},{"en":"A teacher tries to get inside the mind of a nervous student before giving advice.","zh":"老師在給建議前，會嘗試了解緊張學生的心理。"},{"en":"If marketers understand what happens inside the mind of buyers, they may predict purchases more accurately.","zh":"如果市場推廣人員了解買家腦海裏發生的事，他們可能更準確預測購買行為。"},{"en":"The phrase is useful when discussing hidden mental processes.","zh":"這個短語適合討論隱藏的心理過程。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":1},{"front":"brain-scanning technology","meaning":"腦部掃描科技","examples":[{"en":"Brain-scanning technology may help researchers assess consumer reactions.","zh":"腦部掃描科技可能幫助研究人員評估消費者反應。"},{"en":"Brain-scanning technology uses machines to observe activity inside the brain.","zh":"腦部掃描科技使用機器觀察大腦內的活動。"},{"en":"Doctors may use brain-scanning technology to study injury, memory, or disease.","zh":"醫生可能使用腦部掃描科技研究受傷、記憶或疾病。"},{"en":"If marketers use brain-scanning technology, they hope to see reactions people may not explain clearly.","zh":"如果市場推廣人員使用腦部掃描科技，他們希望看見人們未必能清楚解釋的反應。"},{"en":"The phrase refers to scientific tools used to examine brain activity.","zh":"這個短語指用來檢查腦部活動的科學工具。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":1},{"front":"provide an accurate way to","meaning":"提供準確方法去","examples":[{"en":"Brain-scanning technology may provide an accurate way to assess new products.","zh":"腦部掃描科技可能提供準確方法去評估新產品。"},{"en":"To provide an accurate way to do something means to offer a reliable method for doing it.","zh":"“Provide an accurate way to” 做某事指提供可靠的方法去完成它。"},{"en":"A thermometer provides an accurate way to check body temperature.","zh":"體溫計提供準確方法去檢查體溫。"},{"en":"If surveys are unreliable, researchers may look for a more accurate way to measure preferences.","zh":"如果問卷不可靠，研究人員可能尋找更準確方法去量度偏好。"},{"en":"The phrase connects a tool with a dependable method.","zh":"這個短語把工具與可靠方法連繫起來。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":1},{"front":"assess the appeal of","meaning":"評估……的吸引力","examples":[{"en":"Researchers want to assess the appeal of new products.","zh":"研究人員想評估新產品的吸引力。"},{"en":"To assess the appeal of something means to judge how attractive or interesting it is to people.","zh":"“Assess the appeal of” 某物指判斷它對人有多吸引或有趣。"},{"en":"A school may assess the appeal of a new course by asking students whether they would join it.","zh":"學校可能透過詢問學生會否報讀，來評估新課程的吸引力。"},{"en":"If a product has little appeal, customers may notice it but not buy it.","zh":"如果產品吸引力低，顧客可能注意到它但不購買。"},{"en":"The phrase is common in marketing, design, and product testing.","zh":"這個短語常見於市場推廣、設計和產品測試。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":1},{"front":"the appeal of new products","meaning":"新產品的吸引力","examples":[{"en":"Marketing researchers want to measure the appeal of new products.","zh":"市場研究人員想量度新產品的吸引力。"},{"en":"The appeal of new products means how attractive new goods or services are to potential buyers.","zh":"新產品的吸引力指新商品或服務對潛在買家有多吸引。"},{"en":"Shops test the appeal of new products by placing them near the entrance.","zh":"商店可能把新產品放近入口，以測試其吸引力。"},{"en":"If the appeal of new products is weak, companies may change the design, price, or advertising.","zh":"如果新產品的吸引力薄弱，公司可能改變設計、價格或廣告。"},{"en":"The phrase focuses on whether people feel interested enough to buy.","zh":"這個短語強調人們是否有足夠興趣購買。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":1},{"front":"the effectiveness of advertising","meaning":"廣告的成效","examples":[{"en":"Neuromarketing may help measure the effectiveness of advertising.","zh":"神經市場學可能幫助量度廣告的成效。"},{"en":"The effectiveness of advertising means how well advertisements influence attention, memory, or buying behaviour.","zh":"廣告的成效指廣告在影響注意力、記憶或購買行為方面有多有效。"},{"en":"A company may test the effectiveness of advertising by comparing sales before and after a campaign.","zh":"公司可能透過比較宣傳活動前後的銷售，測試廣告的成效。"},{"en":"If advertising is effective, more people may remember the brand or choose the product.","zh":"如果廣告有效，更多人可能記得品牌或選擇產品。"},{"en":"The phrase measures results, not just whether an advert looks attractive.","zh":"這個短語量度結果，而不只是廣告是否好看。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":1},{"front":"marketing people","meaning":"市場推廣人員","examples":[{"en":"Marketing people want to know what consumers really prefer.","zh":"市場推廣人員想知道消費者真正偏好甚麼。"},{"en":"Marketing people are workers who study customers and promote products or services.","zh":"市場推廣人員是研究顧客並推廣產品或服務的工作者。"},{"en":"Marketing people may design adverts, study sales data, or plan social media campaigns.","zh":"市場推廣人員可能設計廣告、研究銷售數據或規劃社交媒體宣傳。"},{"en":"If marketing people misunderstand customers, a product launch may fail.","zh":"如果市場推廣人員誤解顧客，產品推出可能失敗。"},{"en":"The phrase is informal and refers to people working in marketing.","zh":"這個短語較口語，指從事市場推廣的人。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":1},{"front":"no longer prepared to","meaning":"不再願意","examples":[{"en":"Marketing people are no longer prepared to take your word for it.","zh":"市場推廣人員不再願意相信你的一面之詞。"},{"en":"No longer prepared to do something means not willing to do it anymore.","zh":"“No longer prepared to” 做某事指不再願意做該事。"},{"en":"A teacher may be no longer prepared to accept late homework without a reason.","zh":"老師可能不再願意接受沒有理由的遲交功課。"},{"en":"If companies are no longer prepared to trust surveys alone, they may seek new research methods.","zh":"如果公司不再願意只相信問卷，它們可能尋找新的研究方法。"},{"en":"The phrase shows a change from past willingness to present refusal.","zh":"這個短語顯示由過去願意變成現在拒絕。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":1},{"front":"take your word for it","meaning":"相信你的一面之詞","examples":[{"en":"Companies are not willing to take your word for it when you say you prefer a product.","zh":"當你說自己較喜歡某產品，公司不願意相信你的一面之詞。"},{"en":"To take your word for it means to believe what you say without further proof.","zh":"“Take your word for it” 指在沒有進一步證據下相信你所說的話。"},{"en":"A parent may not take a child’s word for it if homework is always “already finished”.","zh":"如果孩子總說功課「已經完成」，父母可能不會相信他的一面之詞。"},{"en":"If customers say they like a product but never buy it, companies may stop taking their word for it.","zh":"如果顧客說喜歡產品卻從不購買，公司可能不再相信他們的一面之詞。"},{"en":"The phrase often appears when someone wants evidence instead of a claim.","zh":"當某人想要證據而不是主張時，常使用這個短語。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":1},{"front":"favour one product over another","meaning":"較喜歡某產品而非另一產品","examples":[{"en":"Consumers may say they favour one product over another.","zh":"消費者可能說他們較喜歡某產品而非另一產品。"},{"en":"To favour one product over another means to prefer one product instead of a different one.","zh":"“Favour one product over another” 指偏好某一產品，而不是另一產品。"},{"en":"A shopper may favour one phone over another because the camera is better.","zh":"購物者可能因相機較好而較喜歡一部手機而非另一部。"},{"en":"If many customers favour one brand over another, the weaker brand may lose market share.","zh":"如果許多顧客較喜歡一個品牌而非另一個，較弱品牌可能失去市場份額。"},{"en":"The phrase is useful when comparing choices.","zh":"這個短語適合比較選擇時使用。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":1},{"front":"scan your brain","meaning":"掃描你的腦部","examples":[{"en":"Researchers want to scan your brain to see what you really prefer.","zh":"研究人員想掃描你的腦部，看看你真正偏好甚麼。"},{"en":"To scan your brain means to use a machine to record or image brain activity.","zh":"“Scan your brain” 指使用機器記錄或成像腦部活動。"},{"en":"Doctors may scan your brain after a serious head injury.","zh":"嚴重頭部受傷後，醫生可能會掃描你的腦部。"},{"en":"If researchers scan your brain while you watch adverts, they may study attention and emotion.","zh":"如果研究人員在你觀看廣告時掃描你的腦部，他們可能研究注意力和情緒。"},{"en":"The phrase describes a scientific examination of brain responses.","zh":"這個短語描述對腦部反應的科學檢查。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":1},{"front":"the tools of neuroscientists","meaning":"神經科學家的工具","examples":[{"en":"Marketers are using the tools of neuroscientists to study consumer choices.","zh":"市場推廣人員正在使用神經科學家的工具來研究消費者選擇。"},{"en":"The tools of neuroscientists are scientific methods and machines used to study the brain and nervous system.","zh":"神經科學家的工具是用來研究大腦和神經系統的科學方法和機器。"},{"en":"Brain scanners and EEG machines are examples of the tools of neuroscientists.","zh":"腦掃描儀和腦電圖機器都是神經科學家的工具例子。"},{"en":"If marketers use these tools, marketing research becomes closer to brain science.","zh":"如果市場推廣人員使用這些工具，市場研究就變得更接近腦科學。"},{"en":"The phrase shows that one field is borrowing methods from another.","zh":"這個短語顯示一個領域正在借用另一領域的方法。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":2},{"front":"electroencephalogram mapping","meaning":"腦電圖映射","examples":[{"en":"Electroencephalogram mapping can be used to study brain activity.","zh":"腦電圖映射可以用來研究腦部活動。"},{"en":"Electroencephalogram mapping, or EEG mapping, records electrical activity in the brain.","zh":"腦電圖映射，即 EEG 映射，記錄大腦中的電活動。"},{"en":"Doctors may use EEG mapping to study sleep problems or seizures.","zh":"醫生可能使用腦電圖映射研究睡眠問題或癲癇發作。"},{"en":"In marketing, EEG mapping may show when an advert catches attention.","zh":"在市場推廣中，腦電圖映射可能顯示廣告何時吸引注意。"},{"en":"The phrase refers to measuring brain signals through electrical patterns.","zh":"這個短語指透過電訊號模式量度腦部訊號。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":2},{"front":"functional magnetic resonance imaging","meaning":"功能性磁力共振成像","examples":[{"en":"Functional magnetic resonance imaging can show real-time brain activity.","zh":"功能性磁力共振成像可以顯示實時腦部活動。"},{"en":"Functional magnetic resonance imaging, or fMRI, measures changes in blood flow linked to brain activity.","zh":"功能性磁力共振成像，即 fMRI，量度與腦部活動有關的血流變化。"},{"en":"Researchers may use fMRI to see which brain areas become active during a task.","zh":"研究人員可能使用 fMRI 觀察人在做任務時哪些腦區變得活躍。"},{"en":"If fMRI shows strong activity while someone sees a brand, researchers may infer emotional involvement.","zh":"如果 fMRI 顯示某人看到品牌時有強烈活動，研究人員可能推斷其情感投入。"},{"en":"The phrase refers to a brain-imaging method, not ordinary photography.","zh":"這個短語指腦成像方法，而不是普通攝影。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":2},{"front":"learn more about","meaning":"更深入了解","examples":[{"en":"Researchers are trying to learn more about purchasing decisions.","zh":"研究人員正嘗試更深入了解購買決定。"},{"en":"To learn more about something means to gain deeper knowledge of it.","zh":"“Learn more about” 某事指對它獲得更深入知識。"},{"en":"A doctor may learn more about a patient’s symptoms by asking detailed questions.","zh":"醫生可能透過詢問詳細問題，更深入了解病人的症狀。"},{"en":"If companies learn more about customers, they can design products that better match real needs.","zh":"如果公司更深入了解顧客，就能設計更符合真實需要的產品。"},{"en":"The phrase shows an attempt to understand something more fully.","zh":"這個短語顯示嘗試更完整理解某事。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":2},{"front":"mental processes behind","meaning":"……背後的心理過程","examples":[{"en":"Neuromarketing studies the mental processes behind purchasing decisions.","zh":"神經市場學研究購買決定背後的心理過程。"},{"en":"Mental processes behind something are the thoughts, emotions, memories, or calculations that cause it.","zh":"某事背後的心理過程，是造成它的想法、情緒、記憶或計算。"},{"en":"Teachers try to understand the mental processes behind a student’s wrong answer.","zh":"老師嘗試理解學生錯誤答案背後的心理過程。"},{"en":"If marketers know the mental processes behind a purchase, they may influence the decision more effectively.","zh":"如果市場推廣人員知道購買背後的心理過程，他們可能更有效影響決定。"},{"en":"The phrase points to hidden thinking beneath visible behaviour.","zh":"這個短語指可見行為之下隱藏的思考。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":2},{"front":"purchasing decisions","meaning":"購買決定","examples":[{"en":"Marketing researchers want to understand consumers’ purchasing decisions.","zh":"市場研究人員想了解消費者的購買決定。"},{"en":"Purchasing decisions are choices about whether, when, and what to buy.","zh":"購買決定是關於是否購買、何時購買和購買甚麼的選擇。"},{"en":"A family’s purchasing decisions may depend on price, quality, and monthly budget.","zh":"家庭的購買決定可能取決於價格、品質和每月預算。"},{"en":"If advertising changes purchasing decisions, companies may spend more on campaigns.","zh":"如果廣告改變購買決定，公司可能在宣傳活動上花更多錢。"},{"en":"The phrase is common in marketing and consumer behaviour.","zh":"這個短語常見於市場推廣和消費者行為。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":2},{"front":"the resulting fusion of","meaning":"由此產生的融合","examples":[{"en":"The resulting fusion of neuroscience and marketing is called neuromarketing.","zh":"神經科學與市場推廣由此產生的融合稱為神經市場學。"},{"en":"The resulting fusion of two fields means the new combination created when they are joined.","zh":"兩個領域由此產生的融合，指它們結合後形成的新組合。"},{"en":"The fusion of education and technology has created many online learning platforms.","zh":"教育與科技的融合創造了許多網上學習平台。"},{"en":"If brain science and marketing are combined, the resulting fusion creates a new research field.","zh":"如果腦科學與市場推廣結合，由此產生的融合就創造新研究領域。"},{"en":"The phrase highlights the product of combining two areas.","zh":"這個短語強調兩個範疇結合後的產物。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":2},{"front":"neuroscience and marketing","meaning":"神經科學與市場推廣","examples":[{"en":"Neuromarketing combines neuroscience and marketing.","zh":"神經市場學結合神經科學與市場推廣。"},{"en":"Neuroscience and marketing are two fields: one studies the brain, and the other studies customers and promotion.","zh":"神經科學與市場推廣是兩個領域：一個研究大腦，另一個研究顧客和推廣。"},{"en":"A university project may combine neuroscience and marketing to study why people remember adverts.","zh":"大學項目可能結合神經科學與市場推廣，研究人們為何記得廣告。"},{"en":"If neuroscience explains attention, marketing can use that knowledge to design stronger messages.","zh":"如果神經科學解釋注意力，市場推廣便可以使用該知識設計更強信息。"},{"en":"The phrase shows an interdisciplinary connection.","zh":"這個短語顯示跨學科連繫。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":2},{"front":"inevitably being called","meaning":"不可避免地被稱為","examples":[{"en":"The new field is inevitably being called neuromarketing.","zh":"這個新領域不可避免地被稱為神經市場學。"},{"en":"Inevitably being called something means it is naturally or predictably given that name.","zh":"“Inevitably being called” 某名稱指自然或可預料地被賦予該名稱。"},{"en":"A phone with a folding screen was inevitably called a foldable phone by customers.","zh":"有摺疊螢幕的手機不可避免地被顧客稱為摺疊手機。"},{"en":"When neuroscience and marketing combine, the field is inevitably given a blended name.","zh":"當神經科學與市場推廣結合，該領域自然會被賦予一個混合名稱。"},{"en":"The phrase suggests the name is unsurprising.","zh":"這個短語暗示名稱並不令人意外。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":2},{"front":"neuromarketing","meaning":"神經市場學","examples":[{"en":"Neuromarketing uses brain science to study consumer behaviour.","zh":"神經市場學使用腦科學研究消費者行為。"},{"en":"Neuromarketing is the use of neuroscience tools to understand marketing, advertising, and buying decisions.","zh":"神經市場學是使用神經科學工具理解市場推廣、廣告和購買決定。"},{"en":"A company may use neuromarketing to test whether people respond emotionally to a brand logo.","zh":"公司可能使用神經市場學測試人們是否對品牌標誌有情緒反應。"},{"en":"If neuromarketing reveals hidden reactions, firms may adjust adverts or products.","zh":"如果神經市場學揭示隱藏反應，企業可能調整廣告或產品。"},{"en":"The term combines “neuro” from brain science and “marketing” from business.","zh":"這個詞結合來自腦科學的 “neuro” 和來自商業的 “marketing”。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":2},{"front":"apply brain-imaging technology","meaning":"應用腦成像科技","examples":[{"en":"Gerry Zaltman was the first person to apply brain-imaging technology to marketing.","zh":"Gerry Zaltman 是第一個把腦成像科技應用於市場推廣的人。"},{"en":"To apply brain-imaging technology means to use brain-scanning methods for a particular purpose.","zh":"“Apply brain-imaging technology” 指為特定目的使用腦掃描方法。"},{"en":"Researchers may apply brain-imaging technology to study memory during language learning.","zh":"研究人員可能應用腦成像科技來研究語言學習中的記憶。"},{"en":"If marketers apply brain imaging to adverts, they can observe brain responses rather than only ask questions.","zh":"如果市場推廣人員把腦成像應用於廣告，就能觀察腦部反應，而不只是提問。"},{"en":"The phrase shows a scientific tool being used in a new field.","zh":"這個短語顯示科學工具被用於新領域。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":2},{"front":"in this way","meaning":"以這種方式","examples":[{"en":"Brain-imaging technology had not been used in this way before.","zh":"腦成像科技以前未曾以這種方式使用。"},{"en":"In this way means by this method, approach, or manner.","zh":"“In this way” 指用這種方法、做法或方式。"},{"en":"A teacher may use videos in this way to explain grammar through real conversations.","zh":"老師可能以這種方式使用影片，透過真實對話解釋文法。"},{"en":"If a medical tool is used in this way for marketing, it changes the purpose of the technology.","zh":"如果醫療工具以這種方式用於市場推廣，科技的用途就改變了。"},{"en":"The phrase refers back to the method just described.","zh":"這個短語回指剛才描述的方法。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":3},{"front":"the late 1990s","meaning":"1990年代末","examples":[{"en":"Gerry Zaltman began applying the technology in the late 1990s.","zh":"Gerry Zaltman 在1990年代末開始應用這項科技。"},{"en":"The late 1990s means the years near the end of the 1990s, such as 1997 to 1999.","zh":"“The late 1990s” 指1990年代接近尾聲的年份，例如1997年至1999年。"},{"en":"Many people first used the Internet at home in the late 1990s.","zh":"許多人在1990年代末首次在家中使用互聯網。"},{"en":"If a technique began in the late 1990s, it is relatively recent in historical terms.","zh":"如果一項技術始於1990年代末，以歷史角度來說相對近期。"},{"en":"The phrase gives an approximate time period.","zh":"這個短語給出大約時期。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":3},{"front":"remain in obscurity","meaning":"一直默默無聞","examples":[{"en":"The idea remained in obscurity until 2001.","zh":"這個想法一直默默無聞，直到2001年。"},{"en":"To remain in obscurity means to stay little known or unnoticed.","zh":"“Remain in obscurity” 指一直不為人知或不受注意。"},{"en":"A talented writer may remain in obscurity if no publisher promotes her work.","zh":"如果沒有出版社推廣，有才華作家可能一直默默無聞。"},{"en":"If an idea remains in obscurity, few people discuss or develop it.","zh":"如果想法一直默默無聞，很少人會討論或發展它。"},{"en":"The phrase suggests being hidden from public attention.","zh":"這個短語暗示遠離公眾注意。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":3},{"front":"marketing consultancy","meaning":"市場推廣顧問公司","examples":[{"en":"BrightHouse is a marketing consultancy based in Atlanta.","zh":"BrightHouse 是一家總部設於亞特蘭大的市場推廣顧問公司。"},{"en":"A marketing consultancy is a company that gives expert advice on branding, advertising, and customers.","zh":"市場推廣顧問公司是就品牌、廣告和顧客提供專業建議的公司。"},{"en":"A small business may hire a marketing consultancy before launching a new product.","zh":"小企業推出新產品前，可能聘請市場推廣顧問公司。"},{"en":"If a marketing consultancy understands consumer behaviour, its advice may improve sales.","zh":"如果市場推廣顧問公司理解消費者行為，其建議可能改善銷售。"},{"en":"The phrase refers to a professional advisory firm in marketing.","zh":"這個短語指市場推廣方面的專業顧問公司。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":3},{"front":"be based in","meaning":"總部設於","examples":[{"en":"The company is based in Atlanta, Georgia.","zh":"該公司總部設於喬治亞州亞特蘭大。"},{"en":"To be based in a place means to have one’s main office or centre of operations there.","zh":"“Be based in” 某地指主要辦公室或營運中心設在該地。"},{"en":"A charity based in Hong Kong may still work with schools overseas.","zh":"總部設於香港的慈善機構仍可能與海外學校合作。"},{"en":"If a company is based in one city, that city is usually its administrative home.","zh":"如果公司總部設於某城市，該城市通常是其行政中心。"},{"en":"The phrase identifies location, not necessarily all places where the company works.","zh":"這個短語指出地點，但不一定代表公司只在該地工作。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":3},{"front":"set up","meaning":"成立；設立","examples":[{"en":"BrightHouse set up a dedicated neuromarketing arm.","zh":"BrightHouse 成立了一個專門的神經市場學部門。"},{"en":"To set up something means to create, establish, or organise it.","zh":"“Set up” 某事指創立、建立或組織它。"},{"en":"A school may set up a reading club for weak readers.","zh":"學校可能為閱讀能力較弱的學生設立閱讀會。"},{"en":"If a company sets up a new department, it usually provides staff, budget, and goals.","zh":"如果公司成立新部門，通常會提供人手、預算和目標。"},{"en":"The phrase is common when describing the start of an organisation or system.","zh":"這個短語常用於描述機構或制度的開始。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":3},{"front":"dedicated neuromarketing arm","meaning":"專門的神經市場學部門","examples":[{"en":"The company set up a dedicated neuromarketing arm.","zh":"該公司成立了一個專門的神經市場學部門。"},{"en":"A dedicated neuromarketing arm is a specialised branch of a company focused only on neuromarketing work.","zh":"專門的神經市場學部門，是公司中只集中處理神經市場學工作的專門分支。"},{"en":"A hospital may have a dedicated cancer unit for patients needing specialist care.","zh":"醫院可能設有專門癌症部門，照顧需要專科護理的病人。"},{"en":"If a firm creates a dedicated arm, it shows serious interest in that area.","zh":"如果公司成立專門部門，顯示它對該範疇有認真興趣。"},{"en":"The phrase combines specialisation with organisational structure.","zh":"這個短語結合專門化與組織結構。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":3},{"front":"list someone among its clients","meaning":"把某人列為客戶之一","examples":[{"en":"BrightHouse lists Coca-Cola among its clients.","zh":"BrightHouse 把可口可樂列為其客戶之一。"},{"en":"To list someone among its clients means to name that person or company as one of its customers.","zh":"“List someone among its clients” 指把某人或某公司列名為其客戶之一。"},{"en":"A design agency may list a famous hotel among its clients to build trust.","zh":"設計公司可能把知名酒店列為客戶之一，以建立信任。"},{"en":"If a firm lists major brands among its clients, it may look more credible.","zh":"如果公司把大型品牌列為客戶之一，它可能顯得更可信。"},{"en":"The phrase is often used in company profiles and marketing materials.","zh":"這個短語常用於公司簡介和市場推廣材料。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":3},{"front":"among its clients","meaning":"在其客戶之中","examples":[{"en":"BrightHouse includes major companies among its clients.","zh":"BrightHouse 的客戶之中包括大型公司。"},{"en":"Among its clients means included in the group of people or companies that buy its services.","zh":"“Among its clients” 指包括在購買其服務的人或公司群體之中。"},{"en":"A law firm may have banks and technology firms among its clients.","zh":"律師行的客戶之中可能有銀行和科技公司。"},{"en":"If a company has respected brands among its clients, new customers may feel more confident.","zh":"如果公司的客戶之中有受尊重品牌，新客戶可能更有信心。"},{"en":"The phrase identifies part of a customer group.","zh":"這個短語指出客戶群體的一部分。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":3},{"front":"an example of clever marketing","meaning":"聰明市場推廣的例子","examples":[{"en":"The company’s name may itself be an example of clever marketing.","zh":"該公司的名稱本身可能就是聰明市場推廣的例子。"},{"en":"An example of clever marketing is a case where a brand uses language, design, or strategy in a smart way.","zh":"聰明市場推廣的例子，是品牌以精明方式使用語言、設計或策略的案例。"},{"en":"A café with a memorable name and clear story can be an example of clever marketing.","zh":"有易記名稱和清晰故事的咖啡店，可以是聰明市場推廣的例子。"},{"en":"If a company name suggests intelligence or insight, it may make clients trust the service more.","zh":"如果公司名稱暗示智慧或洞察力，可能令客戶更信任服務。"},{"en":"The phrase praises a marketing choice that works well.","zh":"這個短語稱讚有效的市場推廣選擇。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":3},{"front":"show someone specific products","meaning":"向某人展示特定產品","examples":[{"en":"BrightHouse does not scan people while showing them specific products.","zh":"BrightHouse 並不是在向人展示特定產品時掃描他們。"},{"en":"To show someone specific products means to present particular items for that person to view or judge.","zh":"“Show someone specific products” 指向某人展示特定物品，讓他觀看或判斷。"},{"en":"A shop assistant may show a customer specific products that fit her budget.","zh":"店員可能向顧客展示符合其預算的特定產品。"},{"en":"If researchers show people specific products during a scan, they can observe direct reactions to those items.","zh":"如果研究人員在掃描期間向人展示特定產品，就可以觀察他們對那些物品的直接反應。"},{"en":"The phrase focuses on concrete product testing.","zh":"這個短語強調具體產品測試。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":3},{"front":"campaign ideas","meaning":"宣傳活動構思","examples":[{"en":"The company does not test specific products or campaign ideas directly.","zh":"該公司並不直接測試特定產品或宣傳活動構思。"},{"en":"Campaign ideas are plans or concepts for advertising or public promotion.","zh":"宣傳活動構思是廣告或公共推廣的計劃或概念。"},{"en":"A team may discuss campaign ideas before choosing a slogan and poster design.","zh":"團隊可能先討論宣傳活動構思，再選擇口號和海報設計。"},{"en":"If campaign ideas are weak, even a good product may receive little attention.","zh":"如果宣傳活動構思薄弱，即使產品好也可能很少受到注意。"},{"en":"The phrase refers to early creative plans, not finished advertisements only.","zh":"這個短語指早期創意計劃，而不只是完成的廣告。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":4},{"front":"base its work on","meaning":"把工作建基於","examples":[{"en":"BrightHouse bases its work on general fMRI-based research.","zh":"BrightHouse 把工作建基於一般基於 fMRI 的研究。"},{"en":"To base its work on something means to use it as the foundation for decisions or services.","zh":"“Base its work on” 某事指以它作為決策或服務的基礎。"},{"en":"A teacher may base her lesson on students’ common grammar mistakes.","zh":"老師可能把課堂建基於學生常見文法錯誤。"},{"en":"If a company bases its work on research, its advice may be more evidence-led.","zh":"如果公司把工作建基於研究，其建議可能更以證據為本。"},{"en":"The phrase shows what supports the work.","zh":"這個短語顯示工作由甚麼支撐。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":4},{"front":"fMRI-based research","meaning":"基於功能性磁力共振成像的研究","examples":[{"en":"The company uses fMRI-based research into consumer preferences.","zh":"該公司使用關於消費者偏好的基於功能性磁力共振成像的研究。"},{"en":"fMRI-based research is research that uses functional magnetic resonance imaging as a main method.","zh":"基於功能性磁力共振成像的研究，是以 fMRI 作為主要方法的研究。"},{"en":"A university may use fMRI-based research to study how people react to fear or reward.","zh":"大學可能使用基於 fMRI 的研究，研究人們如何對恐懼或獎賞作出反應。"},{"en":"If marketing relies on fMRI-based research, brain activity becomes part of consumer analysis.","zh":"如果市場推廣依賴基於 fMRI 的研究，腦部活動就成為消費者分析的一部分。"},{"en":"The phrase identifies the scientific method behind the study.","zh":"這個短語指出研究背後的科學方法。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":4},{"front":"consumer preferences","meaning":"消費者偏好","examples":[{"en":"Neuromarketing aims to understand consumer preferences.","zh":"神經市場學旨在了解消費者偏好。"},{"en":"Consumer preferences are the products, brands, styles, or features that buyers like more than others.","zh":"消費者偏好是買家較喜歡的產品、品牌、風格或特色。"},{"en":"A supermarket studies consumer preferences before deciding which snacks to sell.","zh":"超市在決定售賣哪些小食前，會研究消費者偏好。"},{"en":"If consumer preferences change, companies may need to change packaging or flavours.","zh":"如果消費者偏好改變，公司可能需要改變包裝或味道。"},{"en":"The phrase focuses on what customers tend to choose.","zh":"這個短語強調顧客傾向選擇甚麼。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":4},{"front":"decision-making","meaning":"決策過程","examples":[{"en":"Researchers study consumer preferences and decision-making.","zh":"研究人員研究消費者偏好和決策過程。"},{"en":"Decision-making is the process of choosing between possible actions or options.","zh":"決策過程是在可能行動或選項之間作出選擇的過程。"},{"en":"A student’s decision-making may involve comparing cost, interest, and future goals before choosing a course.","zh":"學生選課前的決策過程可能涉及比較成本、興趣和未來目標。"},{"en":"If emotions influence decision-making, people may buy things they did not plan to buy.","zh":"如果情緒影響決策過程，人們可能購買原本沒有計劃購買的東西。"},{"en":"The phrase refers to the mental process behind choices.","zh":"這個短語指選擇背後的心理過程。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":4},{"front":"be carried out at","meaning":"在……進行","examples":[{"en":"The research was carried out at Emory University.","zh":"該研究在埃默里大學進行。"},{"en":"To be carried out at a place means to be conducted or performed there.","zh":"“Be carried out at” 某地指在該地進行或執行。"},{"en":"The language test was carried out at the school library.","zh":"語言測驗在學校圖書館進行。"},{"en":"If research is carried out at a university, it may involve academic staff and specialist equipment.","zh":"如果研究在大學進行，可能涉及學術人員和專門設備。"},{"en":"The phrase identifies where an activity happens.","zh":"這個短語指出活動發生的地點。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":4},{"front":"brain scanning","meaning":"腦部掃描","examples":[{"en":"Brain scanning may be applied to marketing research.","zh":"腦部掃描可能被應用於市場研究。"},{"en":"Brain scanning is the use of machines to observe the structure or activity of the brain.","zh":"腦部掃描是使用機器觀察大腦結構或活動。"},{"en":"Hospitals use brain scanning to investigate strokes, injuries, or unusual symptoms.","zh":"醫院使用腦部掃描調查中風、受傷或異常症狀。"},{"en":"If brain scanning is used in marketing, researchers can study reactions that people may not report honestly.","zh":"如果腦部掃描用於市場推廣，研究人員可以研究人們未必誠實報告的反應。"},{"en":"The phrase refers to a method of examining the brain.","zh":"這個短語指檢查大腦的方法。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":4},{"front":"be applied to","meaning":"被應用於","examples":[{"en":"Brain scanning can be applied to the study of consumer behaviour.","zh":"腦部掃描可以被應用於消費者行為研究。"},{"en":"To be applied to something means to be used for that purpose or situation.","zh":"“Be applied to” 某事指被用於該目的或情況。"},{"en":"A grammar rule can be applied to many different sentence patterns.","zh":"文法規則可以被應用於許多不同句式。"},{"en":"If a medical tool is applied to marketing, people may question whether the use is appropriate.","zh":"如果醫療工具被應用於市場推廣，人們可能質疑該用途是否合適。"},{"en":"The phrase shows practical use in a specific area.","zh":"這個短語顯示在特定範疇中的實際使用。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":4},{"front":"the basic principle","meaning":"基本原理","examples":[{"en":"The basic principle is similar to traditional market research.","zh":"基本原理與傳統市場研究相似。"},{"en":"The basic principle is the main idea or rule behind a method.","zh":"基本原理是某種方法背後的主要想法或規則。"},{"en":"The basic principle of saving money is spending less than you earn.","zh":"儲蓄的基本原理是花費少於收入。"},{"en":"If two methods share the same basic principle, they may differ mainly in tools rather than goals.","zh":"如果兩種方法有相同基本原理，它們可能主要在工具而不是目標上不同。"},{"en":"The phrase helps explain the foundation of a system.","zh":"這個短語幫助解釋制度的基礎。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":4},{"front":"not that different from","meaning":"與……沒有太大分別","examples":[{"en":"The method is not that different from focus groups.","zh":"這種方法與焦點小組沒有太大分別。"},{"en":"Not that different from means fairly similar to something, despite appearing new or unusual.","zh":"“Not that different from” 指與某事相當相似，即使看起來新或不尋常。"},{"en":"Online tutoring is not that different from face-to-face tutoring when the teacher still gives feedback.","zh":"當老師仍然給予回饋，網上補習與面授補習沒有太大分別。"},{"en":"If neuromarketing asks the same basic question as surveys, it may not be that different from older research.","zh":"如果神經市場學問的是與問卷相同的基本問題，它可能與舊研究沒有太大分別。"},{"en":"The phrase softens a comparison by saying the difference is not large.","zh":"這個短語用較溫和方式表示差異不大。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":4},{"front":"focus groups","meaning":"焦點小組","examples":[{"en":"Focus groups are a traditional form of market research.","zh":"焦點小組是一種傳統市場研究形式。"},{"en":"Focus groups are small groups of people asked to discuss products, adverts, or opinions.","zh":"焦點小組是被邀請討論產品、廣告或意見的小組人士。"},{"en":"A company may invite a focus group to taste a new drink before launching it.","zh":"公司可能邀請焦點小組在推出新飲品前試飲。"},{"en":"If one person dominates a focus group, the results may become biased.","zh":"如果一個人主導焦點小組，結果可能變得有偏差。"},{"en":"The phrase refers to discussion-based research with selected participants.","zh":"這個短語指以討論為本、由選定參與者組成的研究。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":4},{"front":"traditional forms of market research","meaning":"傳統市場研究形式","examples":[{"en":"Neuromarketing is compared with traditional forms of market research.","zh":"神經市場學被拿來與傳統市場研究形式作比較。"},{"en":"Traditional forms of market research include surveys, interviews, focus groups, and product tests.","zh":"傳統市場研究形式包括問卷、訪問、焦點小組和產品測試。"},{"en":"A shop may use traditional forms of market research by asking customers what they liked.","zh":"商店可能透過詢問顧客喜歡甚麼來使用傳統市場研究形式。"},{"en":"If traditional forms of research are flawed, companies may try newer methods.","zh":"如果傳統研究形式有缺陷，公司可能嘗試較新的方法。"},{"en":"The phrase refers to older, established ways of studying consumers.","zh":"這個短語指研究消費者的較舊、成熟方法。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":5},{"front":"a volunteer","meaning":"志願者","examples":[{"en":"A volunteer lies in an fMRI machine during the experiment.","zh":"志願者在實驗期間躺在 fMRI 儀器內。"},{"en":"A volunteer is someone who chooses to take part or help without being forced.","zh":"志願者是自願參與或幫助、而不是被迫的人。"},{"en":"A school event may need volunteers to guide visitors and give out leaflets.","zh":"學校活動可能需要志願者引導訪客和派發傳單。"},{"en":"If a study uses volunteers, participants have agreed to be involved.","zh":"如果研究使用志願者，參與者已同意加入。"},{"en":"The phrase is common in experiments, charities, and community activities.","zh":"這個短語常見於實驗、慈善和社區活動。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":5},{"front":"lie in an fMRI machine","meaning":"躺在功能性磁力共振成像儀內","examples":[{"en":"A volunteer lies in an fMRI machine and watches images.","zh":"志願者躺在功能性磁力共振成像儀內並觀看影像。"},{"en":"To lie in an fMRI machine means to rest inside the scanner while it records brain activity.","zh":"“Lie in an fMRI machine” 指躺在掃描儀內，讓它記錄腦部活動。"},{"en":"A patient may lie in an fMRI machine while doctors check which brain areas respond to movement.","zh":"醫生檢查哪些腦區對動作有反應時，病人可能躺在 fMRI 儀器內。"},{"en":"If a subject lies in the machine during an advert, researchers can monitor immediate brain responses.","zh":"如果受試者在觀看廣告時躺在儀器內，研究人員可以監察即時腦部反應。"},{"en":"The phrase describes the physical setup of the experiment.","zh":"這個短語描述實驗的身體安排。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":5},{"front":"video clips","meaning":"短片片段","examples":[{"en":"The subject may be shown images or video clips.","zh":"受試者可能被展示影像或短片片段。"},{"en":"Video clips are short pieces of video, often used for testing, teaching, or advertising.","zh":"短片片段是短小影片，常用於測試、教學或廣告。"},{"en":"A teacher may show video clips to explain a historical event more clearly.","zh":"老師可能播放短片片段，更清楚解釋歷史事件。"},{"en":"If viewers react strongly to video clips, marketers may use similar scenes in adverts.","zh":"如果觀眾對短片片段反應強烈，市場推廣人員可能在廣告中使用相似場景。"},{"en":"The phrase refers to short visual material rather than a full film.","zh":"這個短語指短視覺材料，而不是完整電影。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":5},{"front":"in place of","meaning":"代替","examples":[{"en":"In place of a questionnaire, researchers monitor brain activity.","zh":"研究人員監察腦部活動，代替使用問卷。"},{"en":"In place of means instead of or as a replacement for something.","zh":"“In place of” 指代替某事或作為其替代品。"},{"en":"A teacher may use a short discussion in place of a written quiz.","zh":"老師可能用簡短討論代替書面小測。"},{"en":"If brain scanning is used in place of interviews, researchers rely less on spoken answers.","zh":"如果腦部掃描用來代替訪問，研究人員就較少依賴口頭答案。"},{"en":"The phrase clearly shows substitution.","zh":"這個短語清楚顯示替代關係。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":5},{"front":"an interview or questionnaire","meaning":"訪問或問卷","examples":[{"en":"Neuromarketing uses brain scanning instead of an interview or questionnaire.","zh":"神經市場學使用腦部掃描，而不是訪問或問卷。"},{"en":"An interview or questionnaire is a method of asking people questions to collect information.","zh":"訪問或問卷是透過向人提問來收集資料的方法。"},{"en":"A school may use an interview or questionnaire to understand why students dislike a course.","zh":"學校可能使用訪問或問卷了解學生為何不喜歡某課程。"},{"en":"If people cannot explain their feelings, an interview or questionnaire may miss important information.","zh":"如果人們不能解釋自己的感受，訪問或問卷可能錯過重要資料。"},{"en":"The phrase refers to traditional ways of collecting opinions.","zh":"這個短語指收集意見的傳統方法。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":5},{"front":"the subject’s response","meaning":"受試者的反應","examples":[{"en":"The subject’s response is evaluated by monitoring brain activity.","zh":"受試者的反應透過監察腦部活動來評估。"},{"en":"The subject’s response is how the person in an experiment reacts to a stimulus or task.","zh":"受試者的反應是實驗中的人對刺激或任務作出的反應。"},{"en":"In a taste test, the subject’s response may include liking, dislike, or surprise.","zh":"在味覺測試中，受試者的反應可能包括喜歡、不喜歡或驚訝。"},{"en":"If the subject’s response is measured through the brain, researchers may see hidden reactions.","zh":"如果受試者的反應透過大腦量度，研究人員可能看見隱藏反應。"},{"en":"The phrase focuses on the participant’s reaction.","zh":"這個短語強調參與者的反應。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":5},{"front":"be evaluated by","meaning":"透過……評估","examples":[{"en":"The response is evaluated by observing the brain.","zh":"反應透過觀察大腦來評估。"},{"en":"To be evaluated by something means to be judged or assessed using that method.","zh":"“Be evaluated by” 某方法指使用該方法來判斷或評估。"},{"en":"A student’s speaking skill may be evaluated by a short oral exam.","zh":"學生的口語能力可能透過簡短口試來評估。"},{"en":"If reactions are evaluated by brain activity, researchers do not depend only on what people say.","zh":"如果反應透過腦部活動評估，研究人員就不只依賴人們所說的話。"},{"en":"The phrase links assessment with the method used.","zh":"這個短語把評估與所用方法連繫起來。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":5},{"front":"monitor brain activity","meaning":"監察腦部活動","examples":[{"en":"Researchers monitor brain activity while the subject views images.","zh":"研究人員在受試者觀看影像時監察腦部活動。"},{"en":"To monitor brain activity means to observe and record changes in how the brain works.","zh":"“Monitor brain activity” 指觀察並記錄大腦運作的變化。"},{"en":"Doctors may monitor brain activity during sleep studies.","zh":"醫生可能在睡眠研究中監察腦部活動。"},{"en":"If researchers monitor brain activity during adverts, they can see which moments attract attention.","zh":"如果研究人員在廣告播放時監察腦部活動，就可以看出哪些時刻吸引注意。"},{"en":"The phrase describes continuous observation of brain responses.","zh":"這個短語描述對腦部反應的持續觀察。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":5},{"front":"real-time images","meaning":"實時影像","examples":[{"en":"fMRI provides real-time images of brain activity.","zh":"fMRI 提供腦部活動的實時影像。"},{"en":"Real-time images show what is happening almost immediately as it happens.","zh":"實時影像顯示事情發生時幾乎即時的情況。"},{"en":"Traffic apps use real-time images or data to show current road conditions.","zh":"交通應用程式使用實時影像或數據顯示目前路況。"},{"en":"If brain scans provide real-time images, researchers can connect a stimulus with an immediate reaction.","zh":"如果腦掃描提供實時影像，研究人員可以把刺激與即時反應連繫起來。"},{"en":"The phrase stresses timing, not just picture quality.","zh":"這個短語強調時間性，而不只是圖像質素。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":5},{"front":"brain activity","meaning":"腦部活動","examples":[{"en":"Brain activity can reveal clues about consumer preferences.","zh":"腦部活動可以揭示關於消費者偏好的線索。"},{"en":"Brain activity is the electrical or blood-flow change that shows parts of the brain are working.","zh":"腦部活動是顯示腦部某些部分正在運作的電活動或血流變化。"},{"en":"Reading, listening, remembering, and choosing all involve brain activity.","zh":"閱讀、聆聽、記憶和選擇都涉及腦部活動。"},{"en":"If brain activity increases in a reward area, researchers may infer interest or pleasure.","zh":"如果獎賞區域的腦部活動增加，研究人員可能推斷有興趣或愉悅感。"},{"en":"The phrase refers to what the brain is doing internally.","zh":"這個短語指大腦內部正在做的事情。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":5},{"front":"areas light up","meaning":"區域亮起","examples":[{"en":"Different areas of the brain light up during the scan.","zh":"掃描期間，大腦不同區域會亮起。"},{"en":"Areas light up means brain regions appear active on a scan image.","zh":"“Areas light up” 指腦區在掃描影像上顯示為活躍。"},{"en":"When a person hears music, certain brain areas may light up.","zh":"當人聽音樂時，某些腦區可能亮起。"},{"en":"If an advert makes reward areas light up, researchers may think the advert is emotionally powerful.","zh":"如果廣告令獎賞區域亮起，研究人員可能認為廣告有情感力量。"},{"en":"The phrase is a visual way to describe measured brain activity.","zh":"這個短語以視覺方式描述量度到的腦部活動。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":6},{"front":"depending on","meaning":"取決於","examples":[{"en":"The areas light up depending on the level of blood flow.","zh":"這些區域亮起取決於血流量水平。"},{"en":"Depending on means controlled or affected by a particular factor.","zh":"“Depending on” 指受某特定因素控制或影響。"},{"en":"A student may choose a course depending on price, interest, and timetable.","zh":"學生可能根據價格、興趣和時間表選擇課程。"},{"en":"In a brain scan, images change depending on which areas need more blood.","zh":"在腦掃描中，影像會根據哪些區域需要更多血液而改變。"},{"en":"The phrase shows that one thing varies with another.","zh":"這個短語顯示一件事隨另一件事而變。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":6},{"front":"the level of blood flow","meaning":"血流量水平","examples":[{"en":"The scan shows changes in the level of blood flow.","zh":"掃描顯示血流量水平的變化。"},{"en":"The level of blood flow is the amount of blood moving to or through a body area.","zh":"血流量水平是流向或流經身體某區域的血液多少。"},{"en":"Doctors may check the level of blood flow after an injury.","zh":"醫生可能在受傷後檢查血流量水平。"},{"en":"If the level of blood flow rises in a brain area, that area may be more active.","zh":"如果某腦區血流量水平上升，該區域可能更活躍。"},{"en":"The phrase is important in explaining how fMRI works.","zh":"這個短語對解釋 fMRI 如何運作很重要。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":6},{"front":"provide clues to","meaning":"提供關於……的線索","examples":[{"en":"Brain activity may provide clues to subconscious thought patterns.","zh":"腦部活動可能提供關於潛意識思維模式的線索。"},{"en":"To provide clues to something means to give signs that help people understand it.","zh":"“Provide clues to” 某事指給出幫助人理解它的跡象。"},{"en":"A student’s repeated mistakes may provide clues to what grammar point they do not understand.","zh":"學生反覆犯錯可能提供關於他不明白哪個文法點的線索。"},{"en":"If brain scans provide clues to hidden preferences, marketers may use them to improve adverts.","zh":"如果腦掃描提供關於隱藏偏好的線索，市場推廣人員可能用它改善廣告。"},{"en":"The phrase suggests partial evidence, not complete proof.","zh":"這個短語暗示部分證據，而不是完整證明。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":6},{"front":"subconscious thought patterns","meaning":"潛意識思維模式","examples":[{"en":"fMRI may reveal subconscious thought patterns.","zh":"fMRI 可能揭示潛意識思維模式。"},{"en":"Subconscious thought patterns are habits of thinking or feeling that people are not fully aware of.","zh":"潛意識思維模式是人們未完全意識到的思考或感受習慣。"},{"en":"A person may have subconscious thought patterns that make one brand feel safer than another.","zh":"一個人可能有潛意識思維模式，令某品牌感覺比另一品牌更安全。"},{"en":"If subconscious thought patterns influence buying, customers may not explain their choices accurately.","zh":"如果潛意識思維模式影響購買，顧客可能無法準確解釋自己的選擇。"},{"en":"The phrase refers to hidden mental patterns beneath conscious reasoning.","zh":"這個短語指有意識推理之下隱藏的心理模式。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":6},{"front":"be associated with","meaning":"與……有關","examples":[{"en":"The sense of self is associated with the medial prefrontal cortex.","zh":"自我意識與內側前額葉皮層有關。"},{"en":"To be associated with something means to be connected or linked with it.","zh":"“Be associated with” 某事指與它有關或有聯繫。"},{"en":"Strong coffee is often associated with energy and early mornings.","zh":"濃咖啡常與精神和清晨有關。"},{"en":"If a brain area is associated with identity, activity there may suggest personal relevance.","zh":"如果某腦區與身份有關，該處活動可能暗示個人相關性。"},{"en":"The phrase shows connection, not always direct cause.","zh":"這個短語顯示關聯，不一定是直接原因。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":6},{"front":"the sense of self","meaning":"自我意識","examples":[{"en":"The sense of self is linked to a particular area of the brain.","zh":"自我意識與大腦某個特定區域有關。"},{"en":"The sense of self is a person’s feeling of who they are and how they relate to the world.","zh":"自我意識是一個人對自己是誰以及如何與世界相連的感覺。"},{"en":"A teenager’s sense of self may change as they make friends and choose interests.","zh":"青少年交朋友和選擇興趣時，自我意識可能改變。"},{"en":"If a brand connects with someone’s sense of self, it may feel personally meaningful.","zh":"如果品牌與某人的自我意識連接，它可能感覺具有個人意義。"},{"en":"The phrase is useful when discussing identity.","zh":"這個短語適合討論身份。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":6},{"front":"an area of the brain","meaning":"腦部區域","examples":[{"en":"The medial prefrontal cortex is an area of the brain.","zh":"內側前額葉皮層是一個腦部區域。"},{"en":"An area of the brain is a specific region that may have particular functions.","zh":"腦部區域是大腦中可能具有特定功能的某個區域。"},{"en":"Doctors may study an area of the brain involved in speech after a patient has language problems.","zh":"病人有語言問題後，醫生可能研究涉及說話的腦部區域。"},{"en":"If an area of the brain becomes active, it may be helping with a task.","zh":"如果一個腦部區域變得活躍，它可能正在幫助完成任務。"},{"en":"The phrase refers to a part of the brain, not the whole brain.","zh":"這個短語指大腦的一部分，而不是整個大腦。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":6},{"front":"medial prefrontal cortex","meaning":"內側前額葉皮層","examples":[{"en":"The medial prefrontal cortex is associated with the sense of self.","zh":"內側前額葉皮層與自我意識有關。"},{"en":"The medial prefrontal cortex is a brain region linked to self-related thinking and social judgement.","zh":"內側前額葉皮層是與自我相關思考和社會判斷有關的腦區。"},{"en":"Researchers may study the medial prefrontal cortex when people think about themselves.","zh":"當人們思考自己時，研究人員可能研究內側前額葉皮層。"},{"en":"If a logo activates this area, researchers may suspect a connection with personal identity.","zh":"如果標誌激活這個區域，研究人員可能懷疑它與個人身份有關。"},{"en":"The phrase names a specific part of the brain.","zh":"這個短語指大腦中的特定部分。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":6},{"front":"a flow of blood to","meaning":"流向……的血液","examples":[{"en":"A flow of blood to that area may suggest brand identification.","zh":"流向該區域的血液可能暗示品牌認同。"},{"en":"A flow of blood to an area means blood is moving toward that body or brain region.","zh":"“A flow of blood to” 某區域指血液正流向該身體或腦部區域。"},{"en":"Exercise increases the flow of blood to working muscles.","zh":"運動會增加流向工作肌肉的血液。"},{"en":"If blood flow to a brain area rises, the area may be more active during the task.","zh":"如果流向某腦區的血流上升，該區域在任務期間可能更活躍。"},{"en":"The phrase helps explain how brain scans detect activity.","zh":"這個短語幫助解釋腦掃描如何偵測活動。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":6},{"front":"a particular logo","meaning":"特定標誌","examples":[{"en":"A subject may identify with a brand while looking at a particular logo.","zh":"受試者在觀看特定標誌時可能認同某品牌。"},{"en":"A particular logo is one specific visual symbol used by a company or organisation.","zh":"特定標誌是公司或組織使用的某一個具體視覺符號。"},{"en":"A child may recognise a particular logo before they can read the brand name.","zh":"孩子可能在會讀品牌名稱前，已認出某個特定標誌。"},{"en":"If a particular logo triggers emotion, the brand may have strong personal meaning for the viewer.","zh":"如果特定標誌引發情緒，該品牌對觀看者可能有強烈個人意義。"},{"en":"The phrase narrows attention to one exact brand symbol.","zh":"這個短語把注意力收窄到一個確切品牌符號。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":6},{"front":"identify with","meaning":"認同；產生身份連繫","examples":[{"en":"If someone identifies with a brand, that brand feels personally relevant.","zh":"如果某人認同一個品牌，該品牌會感覺與個人有關。"},{"en":"To identify with something means to feel connected to it as part of one’s identity or values.","zh":"“Identify with” 某事指感到它與自己的身份或價值觀相連。"},{"en":"A student may identify with a character who also struggles with confidence.","zh":"學生可能認同一個同樣缺乏自信的角色。"},{"en":"If customers identify with a brand, they may choose it even when another product tastes better.","zh":"如果顧客認同某品牌，即使另一產品味道更好，他們也可能選擇它。"},{"en":"The phrase is stronger than simply recognising or liking something.","zh":"這個短語比單純認出或喜歡某物更強。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":7},{"front":"that brand","meaning":"該品牌","examples":[{"en":"The subject may identify with that brand during the scan.","zh":"受試者在掃描期間可能認同該品牌。"},{"en":"That brand means the particular company name, product identity, or logo just mentioned.","zh":"“That brand” 指剛才提到的特定公司名稱、產品身份或標誌。"},{"en":"A customer may buy that brand again because the previous product lasted for years.","zh":"顧客可能再次購買該品牌，因為之前的產品用了多年。"},{"en":"If someone feels loyal to that brand, they may ignore cheaper alternatives.","zh":"如果某人對該品牌有忠誠感，他們可能忽略較便宜替代品。"},{"en":"The phrase refers back to a specific brand already discussed.","zh":"這個短語回指已討論的特定品牌。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":7},{"front":"at first","meaning":"起初","examples":[{"en":"At first, only European companies admitted using neuromarketing.","zh":"起初，只有歐洲公司承認使用神經市場學。"},{"en":"At first means in the beginning or during the early stage.","zh":"“At first” 指在開始時或早期階段。"},{"en":"At first, a new student may feel shy before making friends.","zh":"起初，新學生在交朋友前可能感到害羞。"},{"en":"If only a few companies admit using a method at first, others may join later when it becomes accepted.","zh":"如果起初只有少數公司承認使用某方法，當它變得被接受時，其他公司可能之後加入。"},{"en":"The phrase contrasts an early situation with later change.","zh":"這個短語把早期情況與後來變化作對比。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":7},{"front":"be prepared to admit that","meaning":"願意承認","examples":[{"en":"Only some companies were prepared to admit that they used neuromarketing.","zh":"只有一些公司願意承認它們使用神經市場學。"},{"en":"To be prepared to admit that something is true means to be willing to acknowledge it openly.","zh":"“Be prepared to admit that” 某事為真指願意公開承認它。"},{"en":"A student may not be prepared to admit that they did not revise enough.","zh":"學生可能不願意承認自己溫習不足。"},{"en":"If companies fear criticism, they may not be prepared to admit using controversial methods.","zh":"如果公司害怕批評，它們可能不願意承認使用具爭議的方法。"},{"en":"The phrase suggests openness despite possible embarrassment or risk.","zh":"這個短語暗示即使可能尷尬或有風險，仍願意公開。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":7},{"front":"carmakers","meaning":"汽車製造商","examples":[{"en":"Two carmakers ran pilot studies in 2003.","zh":"兩家汽車製造商在2003年進行試驗研究。"},{"en":"Carmakers are companies that design, manufacture, or sell cars.","zh":"汽車製造商是設計、製造或銷售汽車的公司。"},{"en":"Carmakers may test new models before putting them on the market.","zh":"汽車製造商可能在推出市場前測試新車型。"},{"en":"If carmakers use neuromarketing, they may study reactions to design, comfort, or brand image.","zh":"如果汽車製造商使用神經市場學，它們可能研究人們對設計、舒適度或品牌形象的反應。"},{"en":"The word is a simple term for automobile manufacturers.","zh":"這個詞是 automobile manufacturers 的簡單說法。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":7},{"front":"European arm","meaning":"歐洲分部","examples":[{"en":"Ford’s European arm ran a pilot study.","zh":"福特的歐洲分部進行了一項試驗研究。"},{"en":"A European arm is the European branch or division of a larger organisation.","zh":"歐洲分部是大型機構在歐洲的分支或部門。"},{"en":"A technology company’s European arm may manage sales in France, Germany, and Spain.","zh":"科技公司的歐洲分部可能管理法國、德國和西班牙的銷售。"},{"en":"If the European arm tests a new method, the whole company may later adopt it.","zh":"如果歐洲分部測試新方法，整間公司之後可能採用它。"},{"en":"The phrase describes a regional part of a company.","zh":"這個短語描述公司中的地區部分。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":7},{"front":"run pilot studies","meaning":"進行試驗研究","examples":[{"en":"DaimlerChrysler and Ford’s European arm ran pilot studies.","zh":"DaimlerChrysler 和福特歐洲分部進行了試驗研究。"},{"en":"To run pilot studies means to carry out small early tests before a larger project.","zh":"“Run pilot studies” 指在大型項目前進行小型早期測試。"},{"en":"A school may run a pilot study before changing the timetable for all students.","zh":"學校可能在為所有學生改時間表前進行試驗研究。"},{"en":"If a pilot study works well, the method may be tested on a larger scale.","zh":"如果試驗研究效果好，該方法可能在更大規模測試。"},{"en":"The phrase suggests careful trial before full adoption.","zh":"這個短語暗示在全面採用前謹慎試行。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":7},{"front":"more recently","meaning":"近年來","examples":[{"en":"More recently, American companies have become more open about neuromarketing.","zh":"近年來，美國公司對神經市場學變得更公開。"},{"en":"More recently means at a later time, closer to the present.","zh":"“More recently” 指在較後時間、較接近現在。"},{"en":"More recently, many schools have begun using online homework platforms.","zh":"近年來，許多學校開始使用網上功課平台。"},{"en":"If companies were secretive before but more open recently, public attitudes may have changed.","zh":"如果公司以前保密但近年較公開，公眾態度可能已改變。"},{"en":"The phrase introduces a newer development.","zh":"這個短語引出較新的發展。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":7},{"front":"become more open about","meaning":"對……變得更公開","examples":[{"en":"American companies have become more open about their use of neuromarketing.","zh":"美國公司對使用神經市場學變得更公開。"},{"en":"To become more open about something means to speak about it more honestly or publicly.","zh":"“Become more open about” 某事指更誠實或公開地談論它。"},{"en":"Schools have become more open about mental health support for students.","zh":"學校對學生心理健康支援變得更公開。"},{"en":"If companies become more open about research methods, customers may trust them more.","zh":"如果公司對研究方法變得更公開，顧客可能更信任它們。"},{"en":"The phrase shows a shift from secrecy to transparency.","zh":"這個短語顯示由保密轉向透明。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":7},{"front":"marketing firm","meaning":"市場推廣公司","examples":[{"en":"Lieberman Research Worldwide is a marketing firm based in Los Angeles.","zh":"Lieberman Research Worldwide 是一家總部設於洛杉磯的市場推廣公司。"},{"en":"A marketing firm is a company that helps other businesses study customers and promote products.","zh":"市場推廣公司是幫助其他企業研究顧客和推廣產品的公司。"},{"en":"A marketing firm may design surveys, test adverts, or plan brand strategy.","zh":"市場推廣公司可能設計問卷、測試廣告或規劃品牌策略。"},{"en":"If a marketing firm gives poor advice, a company may waste money on ineffective campaigns.","zh":"如果市場推廣公司給出差劣建議，企業可能把錢浪費在無效宣傳上。"},{"en":"The phrase is a general term for a business in the marketing industry.","zh":"這個短語是市場推廣行業中企業的一般說法。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":7},{"front":"collaborate with","meaning":"與……合作","examples":[{"en":"The company is collaborating with Caltech.","zh":"該公司正在與加州理工學院合作。"},{"en":"To collaborate with someone means to work together on a shared project or goal.","zh":"“Collaborate with” 某人指為共同項目或目標一起工作。"},{"en":"A teacher may collaborate with parents to support a child’s learning.","zh":"老師可能與家長合作支援孩子學習。"},{"en":"If a marketing firm collaborates with scientists, it can combine business questions with research methods.","zh":"如果市場推廣公司與科學家合作，就能把商業問題與研究方法結合。"},{"en":"The phrase stresses cooperation, not working alone.","zh":"這個短語強調合作，而不是獨自工作。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":7},{"front":"enable someone to","meaning":"使某人能夠","examples":[{"en":"The collaboration enables movie studios to test film trailers.","zh":"這項合作使電影製片公司能夠測試電影預告片。"},{"en":"To enable someone to do something means to make it possible for them to do it.","zh":"“Enable someone to” 做某事指使某人能夠做到它。"},{"en":"Online lessons enable busy adults to study after work.","zh":"網上課堂使忙碌成年人能夠在下班後學習。"},{"en":"If new technology enables researchers to measure hidden reactions, market testing may change.","zh":"如果新科技使研究人員能夠量度隱藏反應，市場測試可能改變。"},{"en":"The phrase connects a tool or condition with a new ability.","zh":"這個短語把工具或條件與新能力連繫起來。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":8},{"front":"movie studios","meaning":"電影製片公司","examples":[{"en":"Movie studios can use neuromarketing to test film trailers.","zh":"電影製片公司可以使用神經市場學測試電影預告片。"},{"en":"Movie studios are companies that produce, finance, or distribute films.","zh":"電影製片公司是製作、投資或發行電影的公司。"},{"en":"Movie studios may test posters and trailers before releasing a film.","zh":"電影製片公司可能在上映前測試海報和預告片。"},{"en":"If movie studios know which scenes excite viewers, they may edit trailers differently.","zh":"如果電影製片公司知道哪些場景令觀眾興奮，可能會用不同方式剪接預告片。"},{"en":"The phrase refers to businesses in the film industry.","zh":"這個短語指電影行業中的企業。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":8},{"front":"market-test film trailers","meaning":"對電影預告片進行市場測試","examples":[{"en":"Researchers use neuromarketing to market-test film trailers.","zh":"研究人員使用神經市場學對電影預告片進行市場測試。"},{"en":"To market-test film trailers means to test audience reactions before using trailers publicly.","zh":"“Market-test film trailers” 指在公開使用預告片前測試觀眾反應。"},{"en":"A studio may market-test film trailers to choose the most exciting version.","zh":"製片公司可能對電影預告片進行市場測試，以選擇最令人興奮的版本。"},{"en":"If a trailer fails a market test, editors may cut it again before release.","zh":"如果預告片市場測試失敗，剪接師可能在上映前重新剪接。"},{"en":"The phrase combines marketing research with film promotion.","zh":"這個短語結合市場研究與電影宣傳。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":8},{"front":"more controversially","meaning":"更具爭議的是","examples":[{"en":"More controversially, a political consultancy has used neuromarketing techniques.","zh":"更具爭議的是，一家政治顧問公司使用了神經市場學技術。"},{"en":"More controversially means in a way that is more likely to cause disagreement or criticism.","zh":"“More controversially” 指更可能引起分歧或批評。"},{"en":"More controversially, a school may use cameras to monitor students’ attention in class.","zh":"更具爭議的是，學校可能使用攝影機監察學生上課注意力。"},{"en":"If a tool moves from advertising into politics, people may see it as more controversial.","zh":"如果工具從廣告進入政治，人們可能覺得它更具爭議。"},{"en":"The phrase introduces a point that may trouble readers more than previous examples.","zh":"這個短語引出比前面例子更可能令讀者不安的一點。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":8},{"front":"political consultancy","meaning":"政治顧問公司","examples":[{"en":"A political consultancy studied campaign commercials with neuromarketing.","zh":"一家政治顧問公司用神經市場學研究競選廣告。"},{"en":"A political consultancy is a firm that advises politicians, parties, or campaigns.","zh":"政治顧問公司是向政治人物、政黨或競選活動提供建議的公司。"},{"en":"A political consultancy may design slogans, study voters, and plan media strategy.","zh":"政治顧問公司可能設計口號、研究選民和規劃媒體策略。"},{"en":"If a political consultancy uses brain research, critics may worry about voter manipulation.","zh":"如果政治顧問公司使用腦研究，批評者可能擔心選民操控。"},{"en":"The phrase refers to professional advisers in politics.","zh":"這個短語指政治中的專業顧問。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":8},{"front":"study the effectiveness of","meaning":"研究……的成效","examples":[{"en":"Researchers studied the effectiveness of campaign commercials.","zh":"研究人員研究競選廣告的成效。"},{"en":"To study the effectiveness of something means to examine how well it achieves its purpose.","zh":"“Study the effectiveness of” 某事指研究它達成目的的程度。"},{"en":"A hospital may study the effectiveness of reminder messages for appointments.","zh":"醫院可能研究預約提醒訊息的成效。"},{"en":"If a campaign commercial is effective, viewers may remember the candidate or message better.","zh":"如果競選廣告有效，觀眾可能更記得候選人或信息。"},{"en":"The phrase focuses on measured results.","zh":"這個短語強調可量度結果。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":8},{"front":"campaign commercials","meaning":"競選廣告","examples":[{"en":"Campaign commercials can be tested using neuromarketing techniques.","zh":"競選廣告可以用神經市場學技術測試。"},{"en":"Campaign commercials are advertisements used to promote a political candidate, party, or cause.","zh":"競選廣告是用來宣傳政治候選人、政黨或議題的廣告。"},{"en":"Campaign commercials often use images, music, and slogans to influence voters.","zh":"競選廣告常使用影像、音樂和口號影響選民。"},{"en":"If campaign commercials create fear or trust, they may affect political choices.","zh":"如果競選廣告產生恐懼或信任，它們可能影響政治選擇。"},{"en":"The phrase belongs to election advertising and political communication.","zh":"這個短語屬於選舉廣告和政治傳播。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":8},{"front":"neuromarketing techniques","meaning":"神經市場學技術","examples":[{"en":"Neuromarketing techniques are being used in advertising and politics.","zh":"神經市場學技術正被用於廣告和政治。"},{"en":"Neuromarketing techniques are methods that use brain science to study reactions to products, brands, or messages.","zh":"神經市場學技術是使用腦科學研究人們對產品、品牌或信息反應的方法。"},{"en":"A firm may use neuromarketing techniques to compare two versions of an advert.","zh":"公司可能使用神經市場學技術比較兩個版本的廣告。"},{"en":"If these techniques reveal unconscious responses, marketers may change a campaign’s images or timing.","zh":"如果這些技術揭示無意識反應，市場推廣人員可能改變宣傳活動的影像或時機。"},{"en":"The phrase refers to practical methods within neuromarketing.","zh":"這個短語指神經市場學中的實際方法。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":8},{"front":"whether all this is any more than","meaning":"這一切是否不過是……","examples":[{"en":"It is unclear whether all this is any more than modern phrenology.","zh":"這一切是否不過是現代顱相學，仍不清楚。"},{"en":"Whether all this is any more than something asks if it is really better or more serious than that thing.","zh":"“Whether all this is any more than” 某事，是在問它是否真的比該事更好或更重要。"},{"en":"A critic may ask whether a new study app is any more than an expensive flashcard system.","zh":"批評者可能問一個新學習應用程式是否不過是昂貴的詞卡系統。"},{"en":"If neuromarketing lacks strong evidence, people may question whether it is more than a fashionable idea.","zh":"如果神經市場學缺乏有力證據，人們可能質疑它是否只是時髦想法。"},{"en":"The phrase expresses scepticism.","zh":"這個短語表達懷疑態度。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":8},{"front":"a modern-day version of","meaning":"……的現代版本","examples":[{"en":"Some critics wonder whether neuromarketing is a modern-day version of phrenology.","zh":"一些批評者懷疑神經市場學是否是顱相學的現代版本。"},{"en":"A modern-day version of something is a present form that resembles an older idea or practice.","zh":"某事的現代版本，是與較舊想法或做法相似的當代表現形式。"},{"en":"Some people see influencer advertising as a modern-day version of celebrity endorsement.","zh":"有些人把網紅廣告視為名人代言的現代版本。"},{"en":"If a new method repeats old mistakes, critics may call it a modern-day version of the old method.","zh":"如果新方法重複舊錯誤，批評者可能稱它為舊方法的現代版本。"},{"en":"The phrase compares present and past.","zh":"這個短語比較現在與過去。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":8},{"front":"phrenology","meaning":"顱相學","examples":[{"en":"Phrenology linked skull shapes to personality traits.","zh":"顱相學把頭骨形狀與性格特質聯繫起來。"},{"en":"Phrenology was a discredited belief that skull shape could reveal character or mental ability.","zh":"顱相學是一種已被否定的信念，認為頭骨形狀可以揭示性格或心智能力。"},{"en":"A history teacher may mention phrenology as an example of bad science.","zh":"歷史老師可能把顱相學作為壞科學的例子。"},{"en":"If neuromarketing is compared to phrenology, critics are questioning its scientific reliability.","zh":"如果神經市場學被拿來與顱相學比較，批評者是在質疑其科學可靠性。"},{"en":"The word carries a negative meaning in modern scientific discussion.","zh":"這個詞在現代科學討論中帶有負面意思。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":8},{"front":"Victorian obsession with","meaning":"維多利亞時代對……的迷戀","examples":[{"en":"Phrenology was a Victorian obsession with skull shapes and personality.","zh":"顱相學是維多利亞時代對頭骨形狀和性格的迷戀。"},{"en":"A Victorian obsession with something means a strong interest common in the Victorian period.","zh":"“Victorian obsession with” 某事指維多利亞時期常見的強烈興趣。"},{"en":"A museum exhibit may discuss Victorian obsession with collecting unusual natural objects.","zh":"博物館展覽可能討論維多利亞時代對收藏奇特自然物件的迷戀。"},{"en":"If people were obsessed with skull shapes, they may have overtrusted physical appearance.","zh":"如果人們迷戀頭骨形狀，他們可能過度相信外貌。"},{"en":"The phrase connects a historical period with an intense interest.","zh":"這個短語把歷史時期與強烈興趣連繫起來。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":9},{"front":"link something to","meaning":"把……與……聯繫起來","examples":[{"en":"Phrenology linked lumps in the skull to personality traits.","zh":"顱相學把頭骨凹凸處與性格特質聯繫起來。"},{"en":"To link something to something else means to connect the two ideas, causes, or facts.","zh":"“Link something to” 另一事物指把兩個想法、原因或事實連接起來。"},{"en":"Doctors may link poor sleep to low concentration.","zh":"醫生可能把睡眠不足與專注力低聯繫起來。"},{"en":"If researchers link a brain area to brand identity, they suggest a connection between them.","zh":"如果研究人員把某腦區與品牌身份聯繫起來，他們暗示兩者有關。"},{"en":"The phrase shows association, not always proven cause.","zh":"這個短語顯示關聯，不一定是已證明原因。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":9},{"front":"lumps and bumps","meaning":"凹凸處","examples":[{"en":"Phrenology focused on lumps and bumps in the skull.","zh":"顱相學集中研究頭骨上的凹凸處。"},{"en":"Lumps and bumps are raised or uneven parts on a surface.","zh":"“Lumps and bumps” 指表面上凸起或不平的位置。"},{"en":"A helmet can protect the head from painful lumps and bumps after a fall.","zh":"頭盔可以保護頭部，避免跌倒後出現疼痛凹凸處。"},{"en":"If someone studies skull lumps and bumps to judge personality, the method is not scientifically reliable.","zh":"如果有人研究頭骨凹凸處來判斷性格，這方法並不科學可靠。"},{"en":"The phrase is informal and refers to uneven shapes.","zh":"這個短語較口語，指不平整形狀。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":9},{"front":"the skull","meaning":"頭骨","examples":[{"en":"Phrenology studied the shape of the skull.","zh":"顱相學研究頭骨的形狀。"},{"en":"The skull is the bone structure of the head that protects the brain.","zh":"頭骨是保護大腦的頭部骨骼結構。"},{"en":"Doctors may examine the skull after a serious accident.","zh":"嚴重意外後，醫生可能檢查頭骨。"},{"en":"If a theory claims the skull reveals personality, modern science treats it with scepticism.","zh":"如果一種理論聲稱頭骨揭示性格，現代科學會懷疑地看待它。"},{"en":"The phrase refers to a physical part of the body.","zh":"這個短語指身體的一個實體部分。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":9},{"front":"personality traits","meaning":"性格特質","examples":[{"en":"Phrenology tried to link skull shape to personality traits.","zh":"顱相學試圖把頭骨形狀與性格特質聯繫起來。"},{"en":"Personality traits are stable qualities in how a person thinks, feels, or behaves.","zh":"性格特質是一個人在思考、感受或行為上的穩定特點。"},{"en":"Patience, confidence, and curiosity can be personality traits.","zh":"耐性、自信和好奇心都可以是性格特質。"},{"en":"If marketers understand personality traits, they may design messages for different customer types.","zh":"如果市場推廣人員了解性格特質，可能為不同顧客類型設計信息。"},{"en":"The phrase describes personal characteristics rather than temporary moods.","zh":"這個短語描述個人特徵，而不是短暫心情。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":9},{"front":"large-scale studies","meaning":"大型研究","examples":[{"en":"There have been no large-scale studies of neuromarketing.","zh":"目前沒有關於神經市場學的大型研究。"},{"en":"Large-scale studies are research projects involving many participants, places, or data points.","zh":"大型研究是涉及許多參與者、地點或數據點的研究項目。"},{"en":"A health policy should be tested in large-scale studies before being used widely.","zh":"健康政策在廣泛使用前，應在大型研究中測試。"},{"en":"If there are no large-scale studies, conclusions may remain uncertain.","zh":"如果沒有大型研究，結論可能仍不確定。"},{"en":"The phrase contrasts broad evidence with small experiments.","zh":"這個短語把廣泛證據與小型實驗作對比。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":9},{"front":"a handful of subjects","meaning":"少數受試者","examples":[{"en":"Scans of a handful of subjects may not be reliable.","zh":"少數受試者的掃描可能不可靠。"},{"en":"A handful of subjects means a very small number of people in a study.","zh":"“A handful of subjects” 指研究中非常少量的人。"},{"en":"A teacher cannot judge a whole school from a handful of students.","zh":"老師不能只憑少數學生判斷整間學校。"},{"en":"If only a handful of subjects are tested, the results may not represent most consumers.","zh":"如果只測試少數受試者，結果可能不能代表大多數消費者。"},{"en":"The phrase warns about limited evidence.","zh":"這個短語提醒證據有限。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":9},{"front":"a reliable guide to","meaning":"……的可靠指引","examples":[{"en":"A small study may not be a reliable guide to consumer behaviour.","zh":"小型研究未必是了解消費者行為的可靠指引。"},{"en":"A reliable guide to something is information that can be trusted to help understand it.","zh":"某事的可靠指引，是可以被信任並幫助理解它的資料。"},{"en":"One online review is not always a reliable guide to a restaurant’s quality.","zh":"一則網上評論不一定是餐廳質素的可靠指引。"},{"en":"If research is based on too few people, it may not guide business decisions safely.","zh":"如果研究基於太少人，它可能不能安全地指導商業決策。"},{"en":"The phrase stresses dependability.","zh":"這個短語強調可靠性。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":9},{"front":"consumer behaviour in general","meaning":"整體消費者行為","examples":[{"en":"A few brain scans may not explain consumer behaviour in general.","zh":"少數腦部掃描未必能解釋整體消費者行為。"},{"en":"Consumer behaviour in general means the usual patterns of how consumers think, choose, and buy overall.","zh":"整體消費者行為指消費者整體上如何思考、選擇和購買的通常模式。"},{"en":"One customer’s complaint cannot explain consumer behaviour in general.","zh":"一名顧客的投訴不能解釋整體消費者行為。"},{"en":"If researchers want to understand consumers broadly, they need evidence beyond a few cases.","zh":"如果研究人員想廣泛理解消費者，就需要超越少數個案的證據。"},{"en":"The phrase contrasts broad patterns with individual examples.","zh":"這個短語把廣泛模式與個別例子作對比。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":9},{"front":"be flawed","meaning":"有缺陷","examples":[{"en":"Focus groups and surveys are flawed too.","zh":"焦點小組和問卷也有缺陷。"},{"en":"To be flawed means to have weaknesses, mistakes, or limitations.","zh":"“Be flawed” 指有弱點、錯誤或限制。"},{"en":"A timetable is flawed if it gives students no time to move between classrooms.","zh":"如果時間表沒有給學生轉課室時間，它就是有缺陷的。"},{"en":"If research methods are flawed, their results may mislead decision-makers.","zh":"如果研究方法有缺陷，其結果可能誤導決策者。"},{"en":"The phrase does not mean useless, but it means imperfect.","zh":"這個短語不是指完全無用，而是指不完美。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":9},{"front":"strong personalities","meaning":"強勢性格的人","examples":[{"en":"Strong personalities can influence focus-group results.","zh":"強勢性格的人可以影響焦點小組結果。"},{"en":"Strong personalities are people with forceful, confident, or dominant ways of speaking and acting.","zh":"強勢性格的人是說話和行動有力、自信或具支配性的人。"},{"en":"In a group project, strong personalities may take control of the discussion.","zh":"在小組項目中，強勢性格的人可能控制討論。"},{"en":"If strong personalities dominate a focus group, quieter people may stop sharing honest views.","zh":"如果強勢性格的人主導焦點小組，較安靜的人可能停止分享真實看法。"},{"en":"The phrase can be neutral, but here it warns about influence.","zh":"這個短語可以是中性，但在此提醒影響力。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":9},{"front":"steer the outcomes of","meaning":"引導……的結果","examples":[{"en":"Strong personalities can steer the outcomes of focus groups.","zh":"強勢性格的人可以引導焦點小組的結果。"},{"en":"To steer the outcomes of something means to influence the final results or direction.","zh":"“Steer the outcomes of” 某事指影響最終結果或方向。"},{"en":"A loud student may steer the outcome of a group decision by speaking first and longest.","zh":"愛大聲說話的學生可能透過最先和最久發言來引導小組決定的結果。"},{"en":"If one participant steers the discussion, the research may reflect that person more than the group.","zh":"如果一名參與者引導討論，研究可能更多反映該人而不是整個小組。"},{"en":"The phrase suggests guiding or controlling results.","zh":"這個短語暗示引導或控制結果。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":10},{"front":"outcomes of focus groups","meaning":"焦點小組的結果","examples":[{"en":"The outcomes of focus groups may be affected by dominant participants.","zh":"焦點小組的結果可能受主導性參與者影響。"},{"en":"Outcomes of focus groups are the findings, opinions, or conclusions produced from group discussions.","zh":"焦點小組的結果，是小組討論產生的發現、意見或結論。"},{"en":"A company may use the outcomes of focus groups to adjust packaging.","zh":"公司可能使用焦點小組的結果來調整包裝。"},{"en":"If the outcomes are shaped by one loud person, they may not represent ordinary customers.","zh":"如果結果由一名愛大聲說話的人塑造，就可能不能代表普通顧客。"},{"en":"The phrase refers to research results from focus-group work.","zh":"這個短語指焦點小組工作的研究結果。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":10},{"front":"opinion pollsters","meaning":"民意調查員","examples":[{"en":"People do not always tell opinion pollsters the truth.","zh":"人們不一定會對民意調查員說真話。"},{"en":"Opinion pollsters are people or organisations that collect public views through surveys.","zh":"民意調查員是透過調查收集公眾意見的人或機構。"},{"en":"Opinion pollsters may ask voters which issue matters most to them.","zh":"民意調查員可能詢問選民哪個議題最重要。"},{"en":"If respondents hide their real views, opinion pollsters may predict results incorrectly.","zh":"如果受訪者隱藏真實看法，民意調查員可能錯誤預測結果。"},{"en":"The phrase is common in politics, media, and social research.","zh":"這個短語常見於政治、媒體和社會研究。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":10},{"front":"tell the truth","meaning":"說真話","examples":[{"en":"People do not always tell the truth in surveys.","zh":"人們在調查中不一定說真話。"},{"en":"To tell the truth means to say what is real or honest.","zh":"“Tell the truth” 指說出真實或誠實的內容。"},{"en":"A child may find it hard to tell the truth if they fear punishment.","zh":"如果孩子害怕懲罰，可能很難說真話。"},{"en":"If survey respondents do not tell the truth, researchers may misunderstand public opinion.","zh":"如果調查受訪者不說真話，研究人員可能誤解公眾意見。"},{"en":"The phrase contrasts honesty with hiding or changing facts.","zh":"這個短語把誠實與隱瞞或改變事實作對比。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":10},{"front":"explain their preferences","meaning":"解釋自己的偏好","examples":[{"en":"Even honest people cannot always explain their preferences.","zh":"即使誠實的人也不一定能解釋自己的偏好。"},{"en":"To explain their preferences means to give reasons for why they like one thing more than another.","zh":"“Explain their preferences” 指說明為何較喜歡某事物而非另一事物。"},{"en":"A student may prefer one teacher but struggle to explain the preference clearly.","zh":"學生可能較喜歡某位老師，但難以清楚解釋自己的偏好。"},{"en":"If people cannot explain their preferences, surveys may miss the real cause of their choices.","zh":"如果人們不能解釋自己的偏好，問卷可能錯過選擇背後的真正原因。"},{"en":"The phrase focuses on giving reasons for likes and dislikes.","zh":"這個短語強調為喜好和厭惡給出理由。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":10},{"front":"have the most potential","meaning":"最有潛力","examples":[{"en":"Neuromarketing may have the most potential where people cannot explain preferences.","zh":"在人們不能解釋偏好的情況下，神經市場學可能最有潛力。"},{"en":"To have the most potential means to have the greatest possible usefulness or future success.","zh":"“Have the most potential” 指具有最大的可能用途或未來成功機會。"},{"en":"A quiet student may have the most potential when given patient support and time.","zh":"如果得到耐心支援和時間，安靜學生可能最有潛力。"},{"en":"If ordinary surveys fail, brain scanning may have the most potential as an alternative tool.","zh":"如果普通問卷失效，腦部掃描作為替代工具可能最有潛力。"},{"en":"The phrase points to where something could be most valuable.","zh":"這個短語指出某事在哪裡最有價值。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":10},{"front":"cola drinks","meaning":"可樂飲品","examples":[{"en":"The study examined people’s attitudes towards two cola drinks.","zh":"該研究考察人們對兩款可樂飲品的態度。"},{"en":"Cola drinks are sweet fizzy drinks usually flavoured with cola.","zh":"可樂飲品是通常帶有可樂味的甜味有汽飲品。"},{"en":"A shop may place cola drinks near snacks because people often buy them together.","zh":"商店可能把可樂飲品放近小食，因為人們常一起購買。"},{"en":"If two cola drinks taste similar, brand image may strongly affect customer choice.","zh":"如果兩款可樂飲品味道相似，品牌形象可能強烈影響顧客選擇。"},{"en":"The phrase refers to a common type of soft drink.","zh":"這個短語指一種常見汽水。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":10},{"front":"claim to have","meaning":"聲稱有","examples":[{"en":"Most people claim to have a favourite brand.","zh":"大多數人聲稱有喜愛的品牌。"},{"en":"To claim to have something means to say that one has it, whether or not it is fully true.","zh":"“Claim to have” 某物指說自己擁有它，不論是否完全真實。"},{"en":"A student may claim to have finished homework before the teacher checks it.","zh":"學生可能在老師檢查前聲稱已完成功課。"},{"en":"If consumers claim to have a favourite brand, researchers may test whether behaviour matches the claim.","zh":"如果消費者聲稱有喜愛的品牌，研究人員可能測試行為是否符合該說法。"},{"en":"The phrase leaves room for doubt or verification.","zh":"這個短語留下懷疑或驗證空間。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":10},{"front":"a favourite brand","meaning":"喜愛的品牌","examples":[{"en":"Many consumers say they have a favourite brand.","zh":"許多消費者說他們有喜愛的品牌。"},{"en":"A favourite brand is the brand a person likes or chooses most often.","zh":"喜愛的品牌是一個人最喜歡或最常選擇的品牌。"},{"en":"A runner may have a favourite brand of shoes because they fit comfortably.","zh":"跑步者可能有喜愛的鞋履品牌，因為它穿起來舒服。"},{"en":"If people have a favourite brand, they may buy it even when competitors are cheaper.","zh":"如果人們有喜愛的品牌，即使競爭對手較便宜，他們也可能購買它。"},{"en":"The phrase connects personal preference with repeated choice.","zh":"這個短語把個人偏好與重複選擇連繫起來。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":10},{"front":"well-known cola drinks","meaning":"知名可樂飲品","examples":[{"en":"The study compared two well-known cola drinks.","zh":"該研究比較兩款知名可樂飲品。"},{"en":"Well-known cola drinks are cola brands that many people recognise.","zh":"知名可樂飲品是許多人認得的可樂品牌。"},{"en":"Supermarkets often place well-known cola drinks at eye level because customers recognise them quickly.","zh":"超市常把知名可樂飲品放在視線高度，因為顧客很快認出它們。"},{"en":"If a drink is well known, its brand image may affect taste judgement.","zh":"如果飲品很知名，其品牌形象可能影響味道判斷。"},{"en":"The phrase combines product type with brand familiarity.","zh":"這個短語結合產品類型與品牌熟悉度。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":10},{"front":"attitudes towards","meaning":"對……的態度","examples":[{"en":"The study examined attitudes towards two cola drinks.","zh":"該研究考察人們對兩款可樂飲品的態度。"},{"en":"Attitudes towards something are people’s feelings, opinions, or beliefs about it.","zh":"對某事的態度是人們對它的感受、意見或信念。"},{"en":"A school may survey students’ attitudes towards homework.","zh":"學校可能調查學生對功課的態度。"},{"en":"If customers have positive attitudes towards a brand, they may be more willing to buy it.","zh":"如果顧客對品牌有正面態度，他們可能更願意購買。"},{"en":"The phrase focuses on how people think and feel about an object or issue.","zh":"這個短語強調人們如何思考和感受某物或議題。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":10},{"front":"be carried out","meaning":"被進行","examples":[{"en":"The cola-drink study was carried out at a college of medicine.","zh":"可樂飲品研究在一所醫學院進行。"},{"en":"To be carried out means to be done, performed, or conducted.","zh":"“Be carried out” 指被完成、執行或進行。"},{"en":"A fire drill is carried out to test whether students know how to leave safely.","zh":"消防演習被進行，是為了測試學生是否知道如何安全離開。"},{"en":"If research is carried out carefully, its findings are more trustworthy.","zh":"如果研究被謹慎進行，其發現會更可信。"},{"en":"The phrase is formal and common in research writing.","zh":"這個短語較正式，常見於研究寫作。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":11},{"front":"blind tasting","meaning":"盲品測試","examples":[{"en":"Most subjects preferred one drink in a blind tasting.","zh":"大多數受試者在盲品測試中較喜歡其中一款飲品。"},{"en":"Blind tasting is a test where people taste products without knowing their names or brands.","zh":"盲品測試是人們在不知道名稱或品牌下品嚐產品的測試。"},{"en":"A café may use blind tasting to compare two coffee beans fairly.","zh":"咖啡店可能使用盲品測試公平比較兩種咖啡豆。"},{"en":"If brand labels are hidden, blind tasting can reveal taste preference without brand influence.","zh":"如果品牌標籤被隱藏，盲品測試可以揭示沒有品牌影響下的味道偏好。"},{"en":"The phrase is common in food and drink testing.","zh":"這個短語常見於食物和飲品測試。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":11},{"front":"light up a region","meaning":"令某區域亮起","examples":[{"en":"Drinking one brand lit up a region of the brain.","zh":"飲用其中一個品牌令大腦某區域亮起。"},{"en":"To light up a region means to make an area appear active on a brain scan.","zh":"“Light up a region” 指令某區域在腦掃描中顯示為活躍。"},{"en":"A happy memory may light up a brain region linked to emotion.","zh":"快樂記憶可能令與情緒有關的腦區亮起。"},{"en":"If a drink lights up a reward region more strongly, researchers may infer greater pleasure.","zh":"如果一款飲品令獎賞區域更強烈亮起，研究人員可能推斷有更大愉悅感。"},{"en":"The phrase describes visible activity in a scan image.","zh":"這個短語描述掃描影像中可見的活動。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":11},{"front":"the ventral putamen","meaning":"腹側殼核","examples":[{"en":"The ventral putamen is one of the brain’s reward centres.","zh":"腹側殼核是大腦獎賞中心之一。"},{"en":"The ventral putamen is a brain region involved in reward and pleasure responses.","zh":"腹側殼核是參與獎賞和愉悅反應的腦區。"},{"en":"Researchers may study the ventral putamen when people taste food or receive praise.","zh":"研究人員可能在人們品嚐食物或受到稱讚時研究腹側殼核。"},{"en":"If the ventral putamen becomes more active, the person may be experiencing reward.","zh":"如果腹側殼核變得更活躍，該人可能正在經歷獎賞感。"},{"en":"The phrase names a specific brain area.","zh":"這個短語指特定腦部區域。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":11},{"front":"reward centres","meaning":"獎賞中心","examples":[{"en":"The ventral putamen is one of the brain’s reward centres.","zh":"腹側殼核是大腦獎賞中心之一。"},{"en":"Reward centres are brain areas involved in pleasure, motivation, and positive reinforcement.","zh":"獎賞中心是參與愉悅、動機和正向強化的腦區。"},{"en":"Eating a favourite dessert may activate reward centres in the brain.","zh":"吃喜愛的甜品可能激活大腦中的獎賞中心。"},{"en":"If advertising activates reward centres, it may make a product feel more desirable.","zh":"如果廣告激活獎賞中心，它可能令產品感覺更吸引。"},{"en":"The phrase connects brain activity with pleasure and motivation.","zh":"這個短語把腦部活動與愉悅和動機連繫起來。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":11},{"front":"far more brightly than","meaning":"比……明亮得多","examples":[{"en":"One drink lit up the reward centre far more brightly than the other.","zh":"其中一款飲品令獎賞中心比另一款明亮得多。"},{"en":"Far more brightly than means much more strongly or clearly than another thing in a visual comparison.","zh":"“Far more brightly than” 指在視覺比較中比另一事物強烈或清楚得多。"},{"en":"In a scan, one area may appear far more brightly than another if it is more active.","zh":"在掃描中，如果某區域更活躍，它可能比另一區域明亮得多。"},{"en":"If one product produces a much brighter response, researchers may see it as more rewarding.","zh":"如果一款產品產生明亮得多的反應，研究人員可能視它為更有獎賞感。"},{"en":"The phrase shows a strong difference between two compared things.","zh":"這個短語顯示兩個比較事物之間有強烈差異。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":11},{"front":"be told which drink was which","meaning":"被告知哪種飲品是哪一種","examples":[{"en":"Subjects changed their preferences when told which drink was which.","zh":"受試者在被告知哪種飲品是哪一種後改變了偏好。"},{"en":"To be told which drink was which means to be informed of the brand or identity of each drink.","zh":"“Be told which drink was which” 指被告知每款飲品的品牌或身份。"},{"en":"In a taste test, people may choose differently after being told which cake came from which bakery.","zh":"在味覺測試中，人們在被告知哪件蛋糕來自哪間麵包店後，可能改變選擇。"},{"en":"If brand names are revealed, people may change their judgement because image influences taste.","zh":"如果品牌名稱被揭示，人們可能因形象影響味道而改變判斷。"},{"en":"The phrase shows how information can affect preference.","zh":"這個短語顯示資訊如何影響偏好。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":11},{"front":"brand image","meaning":"品牌形象","examples":[{"en":"A strong brand image can affect consumer choice.","zh":"強大的品牌形象可以影響消費者選擇。"},{"en":"Brand image is the set of feelings, ideas, and associations people connect with a brand.","zh":"品牌形象是人們與品牌連接的一組感受、想法和聯想。"},{"en":"A sports brand may build an image of energy, confidence, and youth.","zh":"運動品牌可能建立活力、自信和年輕的形象。"},{"en":"If brand image is powerful, customers may choose a product before comparing its real quality.","zh":"如果品牌形象強大，顧客可能在比較真實品質前已選擇產品。"},{"en":"The phrase refers to reputation and emotional meaning, not just a logo.","zh":"這個短語指聲譽和情感意義，而不只是標誌。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":11},{"front":"outweigh","meaning":"比……更重要；勝過","examples":[{"en":"A strong brand image can outweigh a more pleasant taste.","zh":"強大的品牌形象可以比更令人愉快的味道更重要。"},{"en":"To outweigh something means to be more important or influential than it.","zh":"“Outweigh” 某事指比它更重要或更有影響力。"},{"en":"A shorter commute may outweigh a slightly higher rent for a tired worker.","zh":"對疲憊上班族來說，較短通勤時間可能勝過略高租金。"},{"en":"If brand image outweighs taste, people may choose the famous drink even when another tastes better.","zh":"如果品牌形象勝過味道，人們可能選擇知名飲品，即使另一款味道更好。"},{"en":"The phrase is useful when comparing competing factors.","zh":"這個短語適合比較互相競爭的因素。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":11},{"front":"more pleasant taste","meaning":"較令人愉快的味道","examples":[{"en":"Brand image may outweigh the more pleasant taste of another drink.","zh":"品牌形象可能勝過另一款飲品較令人愉快的味道。"},{"en":"A more pleasant taste is a flavour that people find nicer or more enjoyable.","zh":"較令人愉快的味道是人們覺得更好或更享受的味道。"},{"en":"A child may choose the yoghurt with a more pleasant taste even if it costs more.","zh":"孩子可能選擇味道較令人愉快的乳酪，即使它較貴。"},{"en":"If branding is powerful, a more pleasant taste may not be enough to win customers.","zh":"如果品牌力量強大，較令人愉快的味道未必足以贏得顧客。"},{"en":"The phrase compares sensory enjoyment between products.","zh":"這個短語比較產品之間的感官享受。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":11},{"front":"form unconscious attitudes","meaning":"形成無意識態度","examples":[{"en":"People form unconscious attitudes towards products and brands.","zh":"人們會對產品和品牌形成無意識態度。"},{"en":"To form unconscious attitudes means to develop feelings or opinions without being fully aware of them.","zh":"“Form unconscious attitudes” 指在未完全意識到的情況下形成感受或意見。"},{"en":"A child may form unconscious attitudes about food from family habits and adverts.","zh":"孩子可能從家庭習慣和廣告中對食物形成無意識態度。"},{"en":"If people form unconscious attitudes towards brands, they may choose them without knowing why.","zh":"如果人們對品牌形成無意識態度，他們可能不知道原因也會選擇它。"},{"en":"The phrase describes hidden preference formation.","zh":"這個短語描述隱藏偏好的形成。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":11},{"front":"beyond traditional methods","meaning":"超出傳統方法所能處理","examples":[{"en":"Some attitudes are beyond traditional methods of market research.","zh":"一些態度超出傳統市場研究方法所能處理。"},{"en":"Beyond traditional methods means too difficult for older usual methods to measure or discover.","zh":"“Beyond traditional methods” 指太難以由較舊常規方法量度或發現。"},{"en":"A student’s hidden fear may be beyond traditional classroom tests.","zh":"學生隱藏的恐懼可能超出傳統課堂測驗所能處理。"},{"en":"If unconscious attitudes are beyond surveys, researchers may need different tools.","zh":"如果無意識態度超出問卷所能處理，研究人員可能需要不同工具。"},{"en":"The phrase shows the limits of established methods.","zh":"這個短語顯示既有方法的限制。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":12},{"front":"utilise introspection","meaning":"利用內省","examples":[{"en":"Traditional research methods often utilise introspection.","zh":"傳統研究方法常利用內省。"},{"en":"To utilise introspection means to use people’s own reflection on their thoughts and feelings.","zh":"“Utilise introspection” 指使用人們對自己思想和感受的反思。"},{"en":"A counsellor may ask a client to utilise introspection to understand why they feel anxious.","zh":"輔導員可能要求來訪者利用內省了解自己為何焦慮。"},{"en":"If consumers cannot access unconscious motives, introspection may give incomplete answers.","zh":"如果消費者不能接觸無意識動機，內省可能給出不完整答案。"},{"en":"The phrase is formal and means using self-examination as evidence.","zh":"這個短語較正式，意思是使用自我檢視作為證據。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":12},{"front":"introspection","meaning":"內省；自我反思","examples":[{"en":"Introspection cannot always reveal unconscious consumer attitudes.","zh":"內省不一定能揭示無意識消費者態度。"},{"en":"Introspection is the process of looking inward and thinking about one’s own thoughts and feelings.","zh":"內省是向內觀察並思考自己想法和感受的過程。"},{"en":"A student may use introspection to understand why they avoid speaking in class.","zh":"學生可能使用內省來了解自己為何避免在課堂說話。"},{"en":"If a choice is driven by habit, introspection may not fully explain it.","zh":"如果選擇由習慣驅動，內省未必能完全解釋它。"},{"en":"The word is useful in psychology and self-reflection.","zh":"這個詞適用於心理學和自我反思。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":12},{"front":"with over $100 billion spent each year","meaning":"每年花費超過一千億美元","examples":[{"en":"With over $100 billion spent each year on marketing, better research could be valuable.","zh":"由於市場推廣每年花費超過一千億美元，更好的研究可能很有價值。"},{"en":"With over $100 billion spent each year means because more than that amount is used annually.","zh":"“With over $100 billion spent each year” 指因每年使用超過該金額。"},{"en":"With so much money spent each year on transport, cities need careful planning.","zh":"由於交通每年花費大量金錢，城市需要謹慎規劃。"},{"en":"If marketing costs over $100 billion yearly, even small improvements in research may be valuable.","zh":"如果市場推廣每年成本超過一千億美元，即使研究有小改善也可能有價值。"},{"en":"The phrase introduces a large financial reason for interest.","zh":"這個短語引出人們感興趣的巨大財務原因。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":12},{"front":"in America alone","meaning":"單是在美國","examples":[{"en":"Over $100 billion is spent on marketing in America alone.","zh":"單是在美國，市場推廣開支就超過一千億美元。"},{"en":"In America alone means only in America, not counting other countries.","zh":"“In America alone” 指只計美國，不包括其他國家。"},{"en":"A company may sell millions of products in China alone before expanding elsewhere.","zh":"公司可能單是在中國就售出數百萬件產品，然後才擴展到其他地方。"},{"en":"If spending is huge in America alone, global spending is likely even larger.","zh":"如果單是在美國開支已很大，全球開支很可能更大。"},{"en":"The phrase emphasises the size of one location’s figure.","zh":"這個短語強調某一地點數字之大。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":12},{"front":"more accurately analyse","meaning":"更準確地分析","examples":[{"en":"Neuromarketing may help firms more accurately analyse customer responses.","zh":"神經市場學可能幫助公司更準確地分析顧客反應。"},{"en":"To more accurately analyse something means to study it with greater precision and fewer errors.","zh":"“More accurately analyse” 某事指以更高精準度和較少錯誤研究它。"},{"en":"A teacher can more accurately analyse writing mistakes by keeping records over several essays.","zh":"老師可以透過記錄幾篇作文中的錯誤，更準確地分析寫作問題。"},{"en":"If firms analyse responses more accurately, they may avoid wasting money on weak adverts.","zh":"如果公司更準確地分析反應，可能避免把錢浪費在薄弱廣告上。"},{"en":"The phrase highlights improvement in measurement and understanding.","zh":"這個短語強調量度和理解上的改善。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":12},{"front":"respond to products, brands and advertising","meaning":"對產品、品牌及廣告作出反應","examples":[{"en":"Companies want to know how customers respond to products, brands and advertising.","zh":"公司想知道顧客如何對產品、品牌及廣告作出反應。"},{"en":"To respond to products, brands and advertising means to react emotionally, mentally, or behaviourally to them.","zh":"“Respond to products, brands and advertising” 指在情感、心理或行為上對它們作出反應。"},{"en":"A customer may respond to a product by buying it, ignoring it, or recommending it.","zh":"顧客可能透過購買、忽略或推薦來對產品作出反應。"},{"en":"If customers respond badly to advertising, the company may change the message.","zh":"如果顧客對廣告反應差，公司可能改變信息。"},{"en":"The phrase covers reactions to both the item and its promotion.","zh":"這個短語涵蓋對物品及其推廣的反應。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":12},{"front":"make a fortune","meaning":"賺大錢","examples":[{"en":"A firm with better marketing tools could make a fortune.","zh":"擁有更好市場推廣工具的公司可能賺大錢。"},{"en":"To make a fortune means to earn a very large amount of money.","zh":"“Make a fortune” 指賺取非常大量金錢。"},{"en":"A small company can make a fortune if its app becomes popular worldwide.","zh":"如果小公司的應用程式在全球受歡迎，它可能賺大錢。"},{"en":"If neuromarketing helps companies sell more effectively, some firms may make a fortune from it.","zh":"如果神經市場學幫助公司更有效銷售，一些企業可能從中賺大錢。"},{"en":"The phrase is informal and strongly suggests major profit.","zh":"這個短語較口語，強烈暗示巨大利潤。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":12},{"front":"consumer advocates","meaning":"消費者權益倡議者","examples":[{"en":"Consumer advocates are wary of neuromarketing.","zh":"消費者權益倡議者對神經市場學保持警惕。"},{"en":"Consumer advocates are people or groups who protect buyers’ rights and interests.","zh":"消費者權益倡議者是保護買家權利和利益的人或團體。"},{"en":"Consumer advocates may warn the public about unsafe products or unfair pricing.","zh":"消費者權益倡議者可能提醒公眾注意不安全產品或不公平定價。"},{"en":"If consumer advocates worry about brain scanning, they may call for stronger rules.","zh":"如果消費者權益倡議者擔心腦部掃描，他們可能要求更嚴格規則。"},{"en":"The phrase refers to people speaking on behalf of consumers.","zh":"這個短語指代表消費者發聲的人。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":12},{"front":"be wary","meaning":"保持警惕；有所戒心","examples":[{"en":"Consumer advocates are wary of brain-scanning techniques in marketing.","zh":"消費者權益倡議者對市場推廣中的腦部掃描技術保持警惕。"},{"en":"To be wary means to be careful because something may be risky or harmful.","zh":"“Be wary” 指因某事可能有風險或有害而小心。"},{"en":"Parents may be wary of apps that collect children’s personal data.","zh":"家長可能對收集兒童個人資料的應用程式有所戒心。"},{"en":"If a method can influence hidden preferences, people may be wary of its use in advertising.","zh":"如果某方法能影響隱藏偏好，人們可能對其在廣告中的使用保持警惕。"},{"en":"The phrase suggests caution rather than complete rejection.","zh":"這個短語暗示謹慎，而不是完全拒絕。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":12},{"front":"lobby group","meaning":"游說團體","examples":[{"en":"Commercial Alert is described as a lobby group.","zh":"Commercial Alert 被描述為一個游說團體。"},{"en":"A lobby group is an organisation that tries to influence public policy or official decisions.","zh":"游說團體是嘗試影響公共政策或官方決定的組織。"},{"en":"A health lobby group may ask the government to limit junk-food advertising to children.","zh":"健康游說團體可能要求政府限制針對兒童的垃圾食物廣告。"},{"en":"If a lobby group opposes neuromarketing, it may pressure lawmakers to regulate it.","zh":"如果游說團體反對神經市場學，它可能向立法者施壓要求規管。"},{"en":"The phrase is common in politics and public-interest campaigns.","zh":"這個短語常見於政治和公共利益活動。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":12},{"front":"existing marketing techniques","meaning":"現有市場推廣技術","examples":[{"en":"Some critics think existing marketing techniques are already powerful enough.","zh":"一些批評者認為現有市場推廣技術已經夠強大。"},{"en":"Existing marketing techniques are the advertising and sales methods already being used.","zh":"現有市場推廣技術是已經正在使用的廣告和銷售方法。"},{"en":"Discounts, celebrity endorsements, and targeted adverts are existing marketing techniques.","zh":"折扣、名人代言和定向廣告都是現有市場推廣技術。"},{"en":"If existing marketing techniques already influence children strongly, new brain-based tools may worry critics more.","zh":"如果現有市場推廣技術已強烈影響兒童，新的腦科學工具可能令批評者更擔心。"},{"en":"The phrase contrasts current methods with newer ones.","zh":"這個短語把現行方法與較新方法作對比。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":13},{"front":"powerful enough","meaning":"已經夠強大","examples":[{"en":"Critics argue that marketing is already powerful enough.","zh":"批評者認為市場推廣已經夠強大。"},{"en":"Powerful enough means strong or effective enough for a purpose, sometimes too strong.","zh":"“Powerful enough” 指對某目的來說已足夠強或有效，有時甚至太強。"},{"en":"A small fan may be powerful enough to cool one desk but not a whole room.","zh":"小風扇可能已經夠強大，可以為一張桌降溫，但不足以冷卻整個房間。"},{"en":"If advertising is already powerful enough to shape habits, stronger tools may raise ethical concerns.","zh":"如果廣告已經夠強大，可以塑造習慣，更強工具可能引起倫理擔憂。"},{"en":"The phrase judges whether more power is needed.","zh":"這個短語判斷是否需要更多力量。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":13},{"front":"be deeply implicated in","meaning":"與……有深切關連","examples":[{"en":"Marketing is said to be deeply implicated in serious health problems.","zh":"據說市場推廣與嚴重健康問題有深切關連。"},{"en":"To be deeply implicated in something means to be strongly connected with or partly responsible for it.","zh":"“Be deeply implicated in” 某事指與它有強烈關聯或對其負有部分責任。"},{"en":"Poor housing may be deeply implicated in community health problems.","zh":"糟糕住房可能與社區健康問題有深切關連。"},{"en":"If advertising encourages unhealthy eating, it may be implicated in obesity trends.","zh":"如果廣告鼓勵不健康飲食，它可能與肥胖趨勢有關。"},{"en":"The phrase suggests serious involvement, not a small connection.","zh":"這個短語暗示嚴重牽涉，而不是小關聯。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":13},{"front":"serious pathologies","meaning":"嚴重病症","examples":[{"en":"Critics link marketing to serious pathologies.","zh":"批評者把市場推廣與嚴重病症聯繫起來。"},{"en":"Serious pathologies are severe diseases, disorders, or unhealthy conditions.","zh":"嚴重病症是嚴重疾病、障礙或不健康狀況。"},{"en":"Doctors study serious pathologies such as diabetes, heart disease, and addiction.","zh":"醫生研究糖尿病、心臟病和成癮等嚴重病症。"},{"en":"If marketing encourages harmful habits, critics may connect it with serious pathologies.","zh":"如果市場推廣鼓勵有害習慣，批評者可能把它與嚴重病症連繫起來。"},{"en":"The phrase is formal and medical in tone.","zh":"這個短語語氣正式且帶醫學色彩。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":13},{"front":"especially true of","meaning":"對……尤其如此","examples":[{"en":"The concern is especially true of children.","zh":"這種擔憂對兒童尤其如此。"},{"en":"Especially true of a group means particularly applicable to that group.","zh":"“Especially true of” 某群體指特別適用於該群體。"},{"en":"Screen-time worries are especially true of young children who cannot manage time alone.","zh":"螢幕時間的擔憂對未能自行管理時間的幼童尤其如此。"},{"en":"If children are easily influenced, concerns about advertising are especially true of them.","zh":"如果兒童容易受影響，對廣告的擔憂就對他們尤其如此。"},{"en":"The phrase highlights the group most affected.","zh":"這個短語突出最受影響的群體。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":13},{"front":"suffer from","meaning":"患有；受……之苦","examples":[{"en":"Children may suffer from marketing-related diseases.","zh":"兒童可能患有與市場推廣有關的疾病。"},{"en":"To suffer from a problem means to experience pain, illness, difficulty, or harm because of it.","zh":"“Suffer from” 某問題指因它而經歷痛苦、疾病、困難或傷害。"},{"en":"A student may suffer from stress when exams and homework pile up.","zh":"當考試和功課堆積，學生可能受壓力之苦。"},{"en":"If children suffer from obesity or diabetes, their daily life and long-term health may be affected.","zh":"如果兒童患有肥胖症或糖尿病，其日常生活和長期健康可能受影響。"},{"en":"The phrase is used for illnesses and serious difficulties.","zh":"這個短語用於疾病和嚴重困難。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":13},{"front":"an epidemic of","meaning":"……的流行；大量出現","examples":[{"en":"Critics warn of an epidemic of marketing-related diseases.","zh":"批評者警告與市場推廣有關的疾病大量出現。"},{"en":"An epidemic of something means a large and rapid spread of a disease or problem.","zh":"“An epidemic of” 某事指疾病或問題大規模而快速擴散。"},{"en":"A school may face an epidemic of flu if many students become sick in one week.","zh":"如果一星期內很多學生生病，學校可能面對流感大流行。"},{"en":"If unhealthy habits spread widely, critics may describe the problem as an epidemic.","zh":"如果不健康習慣廣泛擴散，批評者可能把問題描述為流行病。"},{"en":"The phrase can be literal for disease or figurative for social problems.","zh":"這個短語可以字面指疾病，也可以比喻指社會問題。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":13},{"front":"marketing-related diseases","meaning":"與市場推廣有關的疾病","examples":[{"en":"Some critics blame marketing-related diseases on powerful advertising.","zh":"一些批評者把與市場推廣有關的疾病歸咎於強大廣告。"},{"en":"Marketing-related diseases are health problems critics believe are encouraged by advertising or consumer culture.","zh":"與市場推廣有關的疾病，是批評者認為受廣告或消費文化鼓勵的健康問題。"},{"en":"Junk-food advertising may be linked to marketing-related diseases among children.","zh":"垃圾食物廣告可能與兒童中與市場推廣有關的疾病有關。"},{"en":"If marketing pushes unhealthy products, it may contribute to obesity or type-2 diabetes.","zh":"如果市場推廣推動不健康產品，它可能促成肥胖症或二型糖尿病。"},{"en":"The phrase reflects a critical view of marketing’s health impact.","zh":"這個短語反映對市場推廣健康影響的批判觀點。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":13},{"front":"obesity","meaning":"肥胖症","examples":[{"en":"Obesity is mentioned as a marketing-related disease.","zh":"肥胖症被提及為與市場推廣有關的疾病。"},{"en":"Obesity is a medical condition involving excessive body fat that can harm health.","zh":"肥胖症是一種涉及過多體脂並可能傷害健康的醫學狀況。"},{"en":"Doctors may discuss diet, activity, sleep, and stress when treating obesity.","zh":"醫生治療肥胖症時，可能討論飲食、活動、睡眠和壓力。"},{"en":"If advertising encourages frequent junk-food consumption, critics may link it to obesity.","zh":"如果廣告鼓勵頻繁食用垃圾食物，批評者可能把它與肥胖症連繫起來。"},{"en":"The word should be used as a health term, not as an insult.","zh":"這個詞應作健康用語使用，而不是侮辱。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":13},{"front":"type-2 diabetes","meaning":"二型糖尿病","examples":[{"en":"Type-2 diabetes is mentioned as a disease linked to marketing trends.","zh":"二型糖尿病被提及為與市場推廣趨勢有關的疾病。"},{"en":"Type-2 diabetes is a long-term condition in which the body has difficulty controlling blood sugar.","zh":"二型糖尿病是一種長期疾病，身體難以控制血糖。"},{"en":"A doctor may advise diet change and exercise to help manage type-2 diabetes.","zh":"醫生可能建議改變飲食和運動來幫助管理二型糖尿病。"},{"en":"If unhealthy eating becomes common, rates of type-2 diabetes may rise.","zh":"如果不健康飲食變得普遍，二型糖尿病比率可能上升。"},{"en":"The phrase names a specific medical condition.","zh":"這個短語指特定醫學疾病。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":13},{"front":"amplify these trends","meaning":"加劇這些趨勢","examples":[{"en":"Neuromarketing may amplify these trends.","zh":"神經市場學可能加劇這些趨勢。"},{"en":"To amplify these trends means to make these developments stronger, larger, or more serious.","zh":"“Amplify these trends” 指令這些發展變得更強、更大或更嚴重。"},{"en":"Social media can amplify fashion trends by spreading images quickly.","zh":"社交媒體可以透過快速傳播影像來放大時尚趨勢。"},{"en":"If neuromarketing makes advertising more powerful, it may amplify unhealthy consumption trends.","zh":"如果神經市場學令廣告更強大，它可能加劇不健康消費趨勢。"},{"en":"The phrase warns that an existing movement may become stronger.","zh":"這個短語提醒現有趨勢可能變得更強。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":13},{"front":"counter that","meaning":"反駁說","examples":[{"en":"Dr Quartz counters that neuromarketing could have positive uses.","zh":"Quartz 博士反駁說神經市場學可以有正面用途。"},{"en":"To counter that means to reply with an opposing argument or different view.","zh":"“Counter that” 指以相反論點或不同觀點回應。"},{"en":"A teacher may counter that exams are useful if they are designed fairly.","zh":"老師可能反駁說，如果考試設計公平，它們是有用的。"},{"en":"If critics say a tool is dangerous, supporters may counter that it can also be used responsibly.","zh":"如果批評者說工具危險，支持者可能反駁說它也可以負責任地使用。"},{"en":"The phrase introduces a rebuttal.","zh":"這個短語引出反駁。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":14},{"front":"could equally be used for","meaning":"同樣可以用於","examples":[{"en":"Neuromarketing could equally be used for benign purposes.","zh":"神經市場學同樣可以用於良性目的。"},{"en":"Could equally be used for means could also be used for another purpose just as reasonably.","zh":"“Could equally be used for” 指同樣合理地也可以用於另一目的。"},{"en":"A classroom camera could equally be used for teacher training, not only discipline.","zh":"課室攝影機同樣可以用於教師培訓，而不只是紀律管理。"},{"en":"If brain-scanning tools can sell products, they could equally be used to improve public health messages.","zh":"如果腦部掃描工具可以銷售產品，它們同樣可以用於改善公共健康信息。"},{"en":"The phrase introduces a balanced alternative use.","zh":"這個短語引出平衡的替代用途。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":14},{"front":"benign purposes","meaning":"良性目的","examples":[{"en":"Brain-scanning techniques could be used for benign purposes.","zh":"腦部掃描技術可以用於良性目的。"},{"en":"Benign purposes are harmless or positive aims that do not intend to exploit or damage people.","zh":"良性目的是無害或正面的目的，不意圖剝削或傷害人。"},{"en":"A school survey has a benign purpose if it helps improve student support.","zh":"如果學校問卷幫助改善學生支援，它就有良性目的。"},{"en":"If neuromarketing is used to make adverts less manipulative, that may be a benign purpose.","zh":"如果神經市場學用來令廣告較少操控性，那可能是良性目的。"},{"en":"The phrase contrasts helpful aims with harmful ones.","zh":"這個短語把有幫助的目的與有害目的作對比。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":14},{"front":"create more responsible advertising","meaning":"創造更負責任的廣告","examples":[{"en":"Neuromarketing could help create more responsible advertising.","zh":"神經市場學可以幫助創造更負責任的廣告。"},{"en":"To create more responsible advertising means to design adverts that respect consumers and avoid harmful manipulation.","zh":"“Create more responsible advertising” 指設計尊重消費者並避免有害操控的廣告。"},{"en":"Public health campaigns can create responsible advertising by giving clear information instead of fear.","zh":"公共健康宣傳可以透過提供清晰資訊而不是製造恐懼，創造負責任的廣告。"},{"en":"If research shows children are too easily influenced, companies may create more responsible advertising for them.","zh":"如果研究顯示兒童太容易受影響，公司可能為他們創造更負責任的廣告。"},{"en":"The phrase links advertising with ethics.","zh":"這個短語把廣告與倫理連繫起來。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":14},{"front":"determine when","meaning":"確定何時","examples":[{"en":"Brain scanning could determine when people are capable of free choice.","zh":"腦部掃描可以確定人們何時有能力作出自由選擇。"},{"en":"To determine when something happens means to find out the time or condition in which it happens.","zh":"“Determine when” 某事發生指找出它發生的時間或條件。"},{"en":"A doctor may determine when a patient is ready to return to work.","zh":"醫生可能確定病人何時可以重返工作。"},{"en":"If researchers can determine when advertising becomes manipulative, rules may become clearer.","zh":"如果研究人員能確定廣告何時變成操控，規則可能變得更清晰。"},{"en":"The phrase focuses on identifying timing or conditions.","zh":"這個短語強調識別時間或條件。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":14},{"front":"be capable of","meaning":"有能力","examples":[{"en":"Researchers could test when people are capable of making free choices.","zh":"研究人員可以測試人們何時有能力作出自由選擇。"},{"en":"To be capable of doing something means to have the ability or condition needed to do it.","zh":"“Be capable of” 做某事指具備做該事所需的能力或條件。"},{"en":"A tired driver may not be capable of reacting quickly enough.","zh":"疲倦司機可能沒有能力足夠快速反應。"},{"en":"If consumers are not capable of free choice under certain adverts, ethical limits may be needed.","zh":"如果消費者在某些廣告下沒有能力自由選擇，可能需要倫理界限。"},{"en":"The phrase focuses on ability, not permission.","zh":"這個短語強調能力，而不是許可。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":14},{"front":"making free choices","meaning":"作出自由選擇","examples":[{"en":"Responsible advertising should allow consumers to make free choices.","zh":"負責任廣告應讓消費者作出自由選擇。"},{"en":"Making free choices means choosing without unfair pressure, hidden manipulation, or force.","zh":"作出自由選擇指在沒有不公平壓力、隱藏操控或強迫下選擇。"},{"en":"Students make free choices when they understand all course options and are not pushed by others.","zh":"當學生理解所有課程選項且沒有被他人推迫時，他們就在作出自由選擇。"},{"en":"If adverts exploit fear or weakness, consumers may not be making free choices.","zh":"如果廣告利用恐懼或弱點，消費者可能不是在作出自由選擇。"},{"en":"The phrase connects decision-making with freedom and fairness.","zh":"這個短語把決策與自由和公平連繫起來。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":14},{"front":"ensure that","meaning":"確保","examples":[{"en":"Researchers may use the technology to ensure that advertising stays within ethical limits.","zh":"研究人員可能使用這項科技，確保廣告留在倫理界限之內。"},{"en":"To ensure that something happens means to make certain it happens or remains true.","zh":"“Ensure that” 某事發生指確保它發生或保持真實。"},{"en":"A school checks attendance to ensure that students are safe.","zh":"學校檢查出席率，以確保學生安全。"},{"en":"If companies ensure that adverts are not manipulative, public trust may improve.","zh":"如果公司確保廣告不具操控性，公眾信任可能改善。"},{"en":"The phrase shows responsibility and careful control.","zh":"這個短語顯示責任和謹慎控制。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":14},{"front":"fall within those bounds","meaning":"落在那些界限之內","examples":[{"en":"Advertising should fall within acceptable bounds.","zh":"廣告應落在可接受界限之內。"},{"en":"To fall within those bounds means to stay inside limits or rules that are considered acceptable.","zh":"“Fall within those bounds” 指留在被視為可接受的限制或規則之內。"},{"en":"A school punishment should fall within fair and legal bounds.","zh":"學校懲罰應落在公平和合法界限之內。"},{"en":"If an advert falls within ethical bounds, it informs consumers without exploiting them.","zh":"如果廣告落在倫理界限之內，它會告知消費者而不剝削他們。"},{"en":"The phrase is useful when discussing limits and standards.","zh":"這個短語適合討論限制和標準。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":14},{"front":"invasion of privacy","meaning":"侵犯私隱","examples":[{"en":"Some people worry that brain scanning is an invasion of privacy.","zh":"一些人擔心腦部掃描是侵犯私隱。"},{"en":"An invasion of privacy is an unfair or unwanted intrusion into someone’s personal life or information.","zh":"侵犯私隱是對某人的私人生活或資料作出不公平或不受歡迎的侵入。"},{"en":"Reading another person’s private messages can be an invasion of privacy.","zh":"閱讀他人的私人訊息可以是侵犯私隱。"},{"en":"If brain scans reveal personal preferences, critics may see the research as an invasion of privacy.","zh":"如果腦掃描揭示個人偏好，批評者可能把該研究視為侵犯私隱。"},{"en":"The phrase is common in debates about data, surveillance, and consent.","zh":"這個短語常見於關於數據、監控和同意的辯論。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":14},{"front":"information on the preferences of","meaning":"關於……偏好的資料","examples":[{"en":"Critics worry that information on the preferences of individuals could be misused.","zh":"批評者擔心關於個人偏好的資料可能被濫用。"},{"en":"Information on the preferences of someone means data about what that person likes, chooses, or avoids.","zh":"關於某人偏好的資料，是關於該人喜歡、選擇或避免甚麼的數據。"},{"en":"A shopping app may collect information on the preferences of its users.","zh":"購物應用程式可能收集關於用戶偏好的資料。"},{"en":"If preference information is stored carelessly, companies may target people too aggressively.","zh":"如果偏好資料被草率儲存，公司可能過度進取地針對人們。"},{"en":"The phrase connects personal taste with data.","zh":"這個短語把個人口味與數據連繫起來。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":14},{"front":"specific individuals","meaning":"特定個人","examples":[{"en":"People worry about information on the preferences of specific individuals.","zh":"人們擔心關於特定個人偏好的資料。"},{"en":"Specific individuals are particular named or identifiable people, not a general group.","zh":"特定個人是特別的、有姓名或可識別的人，而不是一般群體。"},{"en":"A school should protect data about specific individuals in student records.","zh":"學校應保護學生紀錄中特定個人的資料。"},{"en":"If research reveals the preferences of specific individuals, privacy concerns become stronger.","zh":"如果研究揭示特定個人的偏好，私隱擔憂會更強。"},{"en":"The phrase narrows attention to identifiable persons.","zh":"這個短語把注意力收窄到可識別人士。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":15},{"front":"be misused","meaning":"被濫用","examples":[{"en":"Personal preference data could be misused.","zh":"個人偏好數據可能被濫用。"},{"en":"To be misused means to be used in a wrong, harmful, or unfair way.","zh":"“Be misused” 指被以錯誤、有害或不公平方式使用。"},{"en":"A student’s personal information can be misused if it is shared without permission.","zh":"如果學生個人資料未經許可被分享，就可能被濫用。"},{"en":"If brain data is misused, companies might target vulnerable consumers unfairly.","zh":"如果腦部數據被濫用，公司可能不公平地針對弱勢消費者。"},{"en":"The phrase warns about improper use of something valuable or sensitive.","zh":"這個短語提醒有價值或敏感事物可能被不當使用。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":15},{"front":"rely on","meaning":"依賴","examples":[{"en":"Neuromarketing studies rely on small numbers of volunteer subjects.","zh":"神經市場學研究依賴少量志願受試者。"},{"en":"To rely on something means to depend on it for support, evidence, or success.","zh":"“Rely on” 某事指依靠它作為支援、證據或成功條件。"},{"en":"A student should not rely on memory alone when preparing for a speaking test.","zh":"學生準備口語考試時不應只依賴記憶。"},{"en":"If research relies on too few volunteers, its conclusions may be weak.","zh":"如果研究依賴太少志願者，其結論可能薄弱。"},{"en":"The phrase often warns about dependence.","zh":"這個短語常提醒依賴問題。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":15},{"front":"small numbers of","meaning":"少量的……","examples":[{"en":"Most neuromarketing studies use small numbers of volunteers.","zh":"大多數神經市場學研究使用少量志願者。"},{"en":"Small numbers of people or things means only a few of them.","zh":"“Small numbers of” 人或物指只有少數。"},{"en":"A school club may begin with small numbers of students before becoming popular.","zh":"學校社團起初可能只有少量學生，之後才變得受歡迎。"},{"en":"If studies use small numbers of participants, results may not apply to everyone.","zh":"如果研究使用少量參與者，結果可能不適用於所有人。"},{"en":"The phrase stresses limited quantity.","zh":"這個短語強調數量有限。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":15},{"front":"volunteer subjects","meaning":"志願受試者","examples":[{"en":"Neuromarketing studies usually involve volunteer subjects.","zh":"神經市場學研究通常涉及志願受試者。"},{"en":"Volunteer subjects are people who agree to take part in a study or experiment.","zh":"志願受試者是同意參與研究或實驗的人。"},{"en":"A psychology experiment may recruit volunteer subjects from a university.","zh":"心理學實驗可能從大學招募志願受試者。"},{"en":"If volunteer subjects know they are being studied, their behaviour may differ from ordinary shoppers.","zh":"如果志願受試者知道自己正在被研究，其行為可能不同於普通購物者。"},{"en":"The phrase refers to participants who join by choice.","zh":"這個短語指自願參與的參與者。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":15},{"front":"seem implausible","meaning":"看似不大可能","examples":[{"en":"The misuse of individual data seems implausible in small volunteer studies.","zh":"在小型志願者研究中，濫用個人數據看似不大可能。"},{"en":"To seem implausible means to appear unlikely or hard to believe.","zh":"“Seem implausible” 指看起來不太可能或難以相信。"},{"en":"It seems implausible that a small shop could serve ten thousand customers in one morning.","zh":"小店一個早上服務一萬名顧客看似不大可能。"},{"en":"If studies use anonymous volunteers, misuse of specific personal data may seem implausible.","zh":"如果研究使用匿名志願者，濫用特定個人資料可能看似不大可能。"},{"en":"The phrase expresses doubt about whether something is likely.","zh":"這個短語表達對某事是否可能的懷疑。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":15},{"front":"object to","meaning":"反對","examples":[{"en":"Critics object to the use of medical equipment for marketing.","zh":"批評者反對把醫療設備用於市場推廣。"},{"en":"To object to something means to disagree with it or oppose it.","zh":"“Object to” 某事指不同意或反對它。"},{"en":"Parents may object to a school rule if they think it is unfair.","zh":"如果家長認為校規不公平，可能反對該規則。"},{"en":"If people object to using hospitals’ machines for adverts, they may argue resources should serve patients first.","zh":"如果人們反對把醫院機器用於廣告，他們可能認為資源應先服務病人。"},{"en":"The phrase shows active disagreement.","zh":"這個短語顯示積極不同意。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":15},{"front":"medical equipment","meaning":"醫療設備","examples":[{"en":"Critics question the use of medical equipment for non-medical purposes.","zh":"批評者質疑把醫療設備用於非醫療目的。"},{"en":"Medical equipment is machinery or tools used to diagnose, monitor, or treat health conditions.","zh":"醫療設備是用來診斷、監察或治療健康狀況的機器或工具。"},{"en":"Hospitals need medical equipment such as scanners, monitors, and ventilators.","zh":"醫院需要掃描儀、監察器和呼吸機等醫療設備。"},{"en":"If medical equipment is used for marketing, some people may worry that health resources are being misused.","zh":"如果醫療設備用於市場推廣，一些人可能擔心健康資源被濫用。"},{"en":"The phrase refers to tools primarily designed for healthcare.","zh":"這個短語指主要為醫療保健設計的工具。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":15},{"front":"frivolous rather than medical purposes","meaning":"輕率用途而非醫療用途","examples":[{"en":"Some critics object to using medical equipment for frivolous rather than medical purposes.","zh":"一些批評者反對把醫療設備用於輕率用途而非醫療用途。"},{"en":"Frivolous rather than medical purposes means unimportant or commercial uses instead of serious health-related uses.","zh":"“Frivolous rather than medical purposes” 指不重要或商業用途，而不是嚴肅健康相關用途。"},{"en":"Using hospital scanners to test snack adverts may seem frivolous rather than medical to critics.","zh":"使用醫院掃描儀測試零食廣告，在批評者看來可能是輕率用途而非醫療用途。"},{"en":"If medical machines are scarce, using them for entertainment research may appear irresponsible.","zh":"如果醫療機器不足，把它們用於娛樂研究可能顯得不負責任。"},{"en":"The phrase creates a sharp contrast between trivial and serious uses.","zh":"這個短語在瑣碎用途與嚴肅用途之間形成鮮明對比。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":15},{"front":"a neuromarketing researcher","meaning":"神經市場學研究員","examples":[{"en":"Tim Ambler is a neuromarketing researcher at the London Business School.","zh":"Tim Ambler 是倫敦商學院的神經市場學研究員。"},{"en":"A neuromarketing researcher studies how brain science can explain consumer choices and marketing effects.","zh":"神經市場學研究員研究腦科學如何解釋消費者選擇和市場推廣效果。"},{"en":"A neuromarketing researcher may compare brain responses to two adverts.","zh":"神經市場學研究員可能比較人們對兩個廣告的腦部反應。"},{"en":"If a researcher works in business school, they may focus on commercial applications of brain data.","zh":"如果研究員在商學院工作，他們可能集中於腦部數據的商業應用。"},{"en":"The phrase describes a specialist in this new research field.","zh":"這個短語描述此新研究領域的專家。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":15},{"front":"a tool is a tool","meaning":"工具就是工具","examples":[{"en":"Tim Ambler argues that a tool is a tool.","zh":"Tim Ambler 認為工具就是工具。"},{"en":"A tool is a tool means an instrument is not wrong by itself; its value depends on how it is used.","zh":"“A tool is a tool” 指工具本身並非錯，其價值取決於如何使用。"},{"en":"A knife can prepare food or cause harm, so a tool is a tool.","zh":"刀可以準備食物，也可以造成傷害，所以工具就是工具。"},{"en":"If brain scanners are used responsibly, supporters may argue that the tool itself is not the problem.","zh":"如果腦掃描儀被負責任地使用，支持者可能認為工具本身不是問題。"},{"en":"The phrase defends practical use while shifting attention to purpose.","zh":"這個短語為實際使用辯護，同時把注意力轉向目的。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":15},{"front":"get a decent rent for","meaning":"獲得不錯的租金","examples":[{"en":"The owner of the tool can get a decent rent for hiring it out.","zh":"工具擁有人可以透過出租它獲得不錯的租金。"},{"en":"To get a decent rent for something means to earn a reasonable payment by renting it to others.","zh":"“Get a decent rent for” 某物指透過把它租給他人而賺取合理款項。"},{"en":"A family may get a decent rent for an unused parking space.","zh":"家庭可能因出租不用的停車位而獲得不錯的租金。"},{"en":"If hospitals rent out expensive equipment when it is free, they may recover some costs.","zh":"如果醫院在設備空閒時出租昂貴設備，可能收回部分成本。"},{"en":"The phrase focuses on earning income from an asset.","zh":"這個短語強調從資產賺取收入。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":16},{"front":"hire it out","meaning":"把它出租","examples":[{"en":"The owner of the equipment can hire it out to researchers.","zh":"設備擁有人可以把它出租給研究人員。"},{"en":"To hire it out means to rent it to someone else for payment.","zh":"“Hire it out” 指把它租給他人並收取費用。"},{"en":"A school may hire out its hall to community groups at weekends.","zh":"學校可能在週末把禮堂出租給社區團體。"},{"en":"If a hospital hires out a scanner during unused hours, the income may support maintenance.","zh":"如果醫院在不用時段出租掃描儀，收入可能支援維修保養。"},{"en":"The phrase refers to lending something commercially.","zh":"這個短語指以商業方式出租某物。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":16},{"front":"subsidise the cost of","meaning":"補貼……的成本","examples":[{"en":"Hiring out the equipment can subsidise the cost of the equipment.","zh":"出租設備可以補貼該設備的成本。"},{"en":"To subsidise the cost of something means to help pay for it and reduce the financial burden.","zh":"“Subsidise the cost of” 某事指幫助支付其費用並減輕財政負擔。"},{"en":"Government funding can subsidise the cost of public transport for students.","zh":"政府資助可以補貼學生公共交通成本。"},{"en":"If scanner rental income subsidises equipment costs, medical institutions may benefit financially.","zh":"如果掃描儀租金收入補貼設備成本，醫療機構可能在財務上受惠。"},{"en":"The phrase connects extra income or support with lower cost.","zh":"這個短語把額外收入或支援與較低成本連繫起來。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":16},{"front":"everybody wins","meaning":"人人受惠","examples":[{"en":"If the equipment earns money, everybody wins.","zh":"如果設備賺到錢，人人受惠。"},{"en":"Everybody wins means all parties benefit from the arrangement.","zh":"“Everybody wins” 指所有相關方都從安排中受益。"},{"en":"If a school opens its sports hall to the community and earns maintenance money, everybody wins.","zh":"如果學校開放體育館給社區並賺取維修費，人人受惠。"},{"en":"If researchers access equipment and hospitals receive income, supporters may say everybody wins.","zh":"如果研究人員使用到設備，而醫院獲得收入，支持者可能說人人受惠。"},{"en":"The phrase presents a situation as mutually beneficial.","zh":"這個短語把情況呈現為互利。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":16},{"front":"someday explain why","meaning":"有一天解釋為何","examples":[{"en":"More brain scanning may someday explain why people react differently to neuromarketing.","zh":"更多腦部掃描有一天可能解釋為何人們對神經市場學有不同反應。"},{"en":"Someday explain why means perhaps provide a reason in the future.","zh":"“Someday explain why” 指將來也許能提供原因。"},{"en":"More sleep research may someday explain why some students learn better at night.","zh":"更多睡眠研究有一天可能解釋為何一些學生在晚上學得更好。"},{"en":"If present evidence is incomplete, future studies may someday explain the missing cause.","zh":"如果目前證據不完整，未來研究有一天可能解釋缺失的原因。"},{"en":"The phrase points to a possible future explanation.","zh":"這個短語指向可能的未來解釋。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":16},{"front":"like the idea of","meaning":"喜歡……的想法","examples":[{"en":"Some people like the idea of neuromarketing, while others dislike it.","zh":"有些人喜歡神經市場學的想法，而另一些人不喜歡。"},{"en":"To like the idea of something means to find the concept attractive or acceptable.","zh":"“Like the idea of” 某事指覺得該概念吸引或可接受。"},{"en":"A student may like the idea of online lessons because they save travel time.","zh":"學生可能喜歡網上課堂的想法，因為它節省交通時間。"},{"en":"If people like the idea of responsible advertising, they may support careful use of neuromarketing.","zh":"如果人們喜歡負責任廣告的想法，可能支持謹慎使用神經市場學。"},{"en":"The phrase focuses on reaction to a concept before full experience.","zh":"這個短語強調在完整經驗前對概念的反應。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":16},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Students must choose the correct heading for each paragraph.","zh":"學生必須為每段選出正確標題。"},{"en":"To choose the correct heading means to select the title that best matches a paragraph’s main idea.","zh":"“Choose the correct heading” 指選出最符合段落主旨的標題。"},{"en":"In reading exams, students should understand the whole paragraph before choosing the heading.","zh":"在閱讀考試中，學生應先理解整段，再選標題。"},{"en":"If a heading matches only one detail, it may not be the correct answer.","zh":"如果標題只符合一個細節，它未必是正確答案。"},{"en":"The phrase is common in IELTS-style reading tasks.","zh":"這個短語常見於 IELTS 類閱讀題。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":16},{"front":"list of headings","meaning":"標題列表","examples":[{"en":"The question provides a list of headings below.","zh":"題目在下方提供標題列表。"},{"en":"A list of headings is a set of possible paragraph titles for students to choose from.","zh":"標題列表是一組可供學生選擇的段落標題。"},{"en":"Students should read the list of headings before scanning the passage structure.","zh":"學生應先閱讀標題列表，再掃讀文章結構。"},{"en":"If two headings look similar, the paragraph’s main idea helps separate them.","zh":"如果兩個標題看起來相似，段落主旨可幫助分辨它們。"},{"en":"The phrase refers to answer options in a matching-heading task.","zh":"這個短語指標題配對題中的答案選項。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":16},{"front":"write the correct number","meaning":"寫上正確編號","examples":[{"en":"Students write the correct number in the answer box.","zh":"學生在答案框中寫上正確編號。"},{"en":"To write the correct number means to record the number of the chosen answer option.","zh":"“Write the correct number” 指記錄所選答案選項的編號。"},{"en":"In matching tasks, students may write roman numerals or numbers instead of full words.","zh":"在配對題中，學生可能寫羅馬數字或數字，而不是完整文字。"},{"en":"If students choose the right heading but write the wrong number, they may lose marks.","zh":"如果學生選了正確標題但寫錯編號，可能會失分。"},{"en":"The phrase is a practical exam instruction.","zh":"這個短語是實用考試指示。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":16},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Answers should be written on the answer sheet.","zh":"答案應寫在答題紙上。"},{"en":"On your answer sheet means in the official place where exam answers are recorded.","zh":"“On your answer sheet” 指在記錄考試答案的正式位置上。"},{"en":"Students should transfer answers onto the answer sheet before time ends.","zh":"學生應在時間結束前把答案轉寫到答題紙上。"},{"en":"If an answer is only written on rough paper, it may not be marked.","zh":"如果答案只寫在草稿紙上，可能不會被評分。"},{"en":"The phrase reminds candidates where to put final answers.","zh":"這個短語提醒考生把最終答案放在哪裡。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":16},{"front":"a description of the procedure","meaning":"對程序的描述","examples":[{"en":"One heading refers to a description of the procedure.","zh":"其中一個標題指對程序的描述。"},{"en":"A description of the procedure explains the steps in a method or process.","zh":"對程序的描述解釋某方法或過程中的步驟。"},{"en":"A science worksheet may include a description of the procedure before an experiment.","zh":"科學工作紙可能在實驗前包含對程序的描述。"},{"en":"If a paragraph explains how volunteers are scanned, it may match this heading.","zh":"如果段落解釋志願者如何被掃描，它可能配對這個標題。"},{"en":"The phrase focuses on how something is done.","zh":"這個短語強調某事如何完成。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":16},{"front":"an international research project","meaning":"國際研究項目","examples":[{"en":"The option mentions an international research project.","zh":"該選項提到一個國際研究項目。"},{"en":"An international research project is a study involving researchers, data, or participants from more than one country.","zh":"國際研究項目是涉及多於一個國家的研究人員、數據或參與者的研究。"},{"en":"A university may run an international research project on student sleep habits.","zh":"大學可能進行關於學生睡眠習慣的國際研究項目。"},{"en":"If a project is international, its results may compare different cultures or markets.","zh":"如果項目是國際性的，其結果可能比較不同文化或市場。"},{"en":"The phrase suggests research beyond one nation.","zh":"這個短語暗示研究超越一個國家。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":17},{"front":"an experiment to investigate","meaning":"用來調查……的實驗","examples":[{"en":"The passage includes an experiment to investigate consumer responses.","zh":"文章包括一項用來調查消費者反應的實驗。"},{"en":"An experiment to investigate something is a controlled test designed to study it.","zh":"用來調查某事的實驗，是為研究它而設計的受控測試。"},{"en":"A teacher may run an experiment to investigate which revision method helps students remember more.","zh":"老師可能進行實驗，調查哪種溫習方法幫助學生記得更多。"},{"en":"If researchers run an experiment to investigate taste preference, they may control brand information.","zh":"如果研究人員進行實驗調查味道偏好，可能控制品牌資訊。"},{"en":"The phrase connects scientific testing with a research question.","zh":"這個短語把科學測試與研究問題連繫起來。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":17},{"front":"consumer responses","meaning":"消費者反應","examples":[{"en":"Neuromarketing investigates consumer responses to products and brands.","zh":"神經市場學調查消費者對產品和品牌的反應。"},{"en":"Consumer responses are the reactions customers have when they see, use, or think about a product.","zh":"消費者反應是顧客看見、使用或想到產品時產生的反應。"},{"en":"A company may measure consumer responses by studying sales, comments, or brain activity.","zh":"公司可能透過研究銷售、評論或腦部活動來量度消費者反應。"},{"en":"If consumer responses are negative, the company may change the advert or product design.","zh":"如果消費者反應負面，公司可能改變廣告或產品設計。"},{"en":"The phrase includes emotional, mental, and behavioural reactions.","zh":"這個短語包括情感、心理和行為反應。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":17},{"front":"an alternative name","meaning":"另一個名稱","examples":[{"en":"The heading refers to marketing an alternative name.","zh":"該標題提到推廣另一個名稱。"},{"en":"An alternative name is another name used instead of the original or expected one.","zh":"另一個名稱是用來代替原本或預期名稱的名稱。"},{"en":"A restaurant may use an alternative name for a dish to make it sound more attractive.","zh":"餐廳可能為菜式使用另一個名稱，使它聽起來更吸引。"},{"en":"If a field is given an alternative name, the new label may change how people see it.","zh":"如果某領域被賦予另一個名稱，新標籤可能改變人們看待它的方式。"},{"en":"The phrase focuses on naming choices.","zh":"這個短語強調命名選擇。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":17},{"front":"a misleading name","meaning":"具誤導性的名稱","examples":[{"en":"The heading suggests that a name may be misleading.","zh":"該標題暗示名稱可能具誤導性。"},{"en":"A misleading name gives people a wrong or incomplete impression.","zh":"具誤導性的名稱會給人錯誤或不完整印象。"},{"en":"A snack called “healthy bites” may have a misleading name if it contains too much sugar.","zh":"如果名為「健康小食」的零食含糖太多，它可能有具誤導性的名稱。"},{"en":"If a company name sounds scientific but the work is mostly marketing, critics may call it misleading.","zh":"如果公司名稱聽起來科學，但工作主要是市場推廣，批評者可能稱它具誤導性。"},{"en":"The phrase warns that a label can shape false expectations.","zh":"這個短語提醒標籤可以塑造錯誤期待。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":17},{"front":"a potentially profitable line of research","meaning":"一項可能有利可圖的研究方向","examples":[{"en":"Neuromarketing may become a potentially profitable line of research.","zh":"神經市場學可能成為一項可能有利可圖的研究方向。"},{"en":"A potentially profitable line of research is an area of study that could earn money in the future.","zh":"可能有利可圖的研究方向，是將來可能賺錢的研究範疇。"},{"en":"Research into better batteries is a potentially profitable line of research for electric-car companies.","zh":"對電動車公司來說，研究更好電池是一項可能有利可圖的研究方向。"},{"en":"If companies spend huge sums on marketing, tools that improve advertising may become profitable.","zh":"如果公司在市場推廣上花費巨額金錢，改善廣告的工具可能變得有利可圖。"},{"en":"The phrase connects academic study with commercial opportunity.","zh":"這個短語把學術研究與商業機會連繫起來。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":17},{"front":"medical dangers of the technique","meaning":"該技術的醫療風險","examples":[{"en":"The option refers to possible medical dangers of the technique.","zh":"該選項提到該技術可能的醫療風險。"},{"en":"Medical dangers of the technique are health risks that may come from using a method or device.","zh":"該技術的醫療風險，是使用某方法或設備可能帶來的健康風險。"},{"en":"A new treatment must be checked for medical dangers before doctors use it widely.","zh":"新治療在醫生廣泛使用前，必須檢查其醫療風險。"},{"en":"If a technique uses medical equipment, readers may ask whether it creates any health danger.","zh":"如果技術使用醫療設備，讀者可能會問它是否造成任何健康風險。"},{"en":"The phrase focuses on safety risks, not marketing ethics alone.","zh":"這個短語強調安全風險，而不只是市場推廣倫理。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":17},{"front":"drawbacks to marketing tools","meaning":"市場研究工具的缺點","examples":[{"en":"The paragraph discusses drawbacks to traditional marketing tools.","zh":"該段討論傳統市場研究工具的缺點。"},{"en":"Drawbacks to marketing tools are weaknesses or disadvantages in methods used to study or influence customers.","zh":"市場研究工具的缺點，是用來研究或影響顧客的方法中的弱點或不利之處。"},{"en":"A survey has drawbacks if people answer quickly without thinking.","zh":"如果人們沒有思考便快速回答，問卷就有缺點。"},{"en":"If focus groups are dominated by loud participants, that is a drawback to the tool.","zh":"如果焦點小組被愛大聲發言的參與者主導，那就是該工具的缺點。"},{"en":"The phrase helps evaluate methods critically.","zh":"這個短語幫助批判性評估方法。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":17},{"front":"broadening applications","meaning":"擴大的應用範圍","examples":[{"en":"The heading refers to the broadening applications of neuromarketing.","zh":"該標題指神經市場學擴大的應用範圍。"},{"en":"Broadening applications means an increasing range of uses in different fields or situations.","zh":"擴大的應用範圍指在不同領域或情況中的用途越來越多。"},{"en":"Smartphones show broadening applications when they are used for banking, learning, and healthcare.","zh":"當智能電話用於銀行、學習和醫療時，就顯示其應用範圍擴大。"},{"en":"If neuromarketing moves from products to films and politics, its applications are broadening.","zh":"如果神經市場學從產品走向電影和政治，其應用範圍正在擴大。"},{"en":"The phrase describes expansion of use.","zh":"這個短語描述用途擴展。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":17},{"front":"look at the following people","meaning":"查看以下人物","examples":[{"en":"Students look at the following people and match them with opinions.","zh":"學生查看以下人物，並把他們與意見配對。"},{"en":"Look at the following people means read the list of named people given in the question.","zh":"“Look at the following people” 指閱讀題目提供的人名列表。"},{"en":"In a matching task, students should look at the following people before scanning for their views.","zh":"在配對題中，學生應先查看以下人物，再掃讀他們的觀點。"},{"en":"If students confuse two speakers, they may match the wrong opinion.","zh":"如果學生混淆兩位發言者，可能配對錯誤意見。"},{"en":"The phrase is a practical exam instruction.","zh":"這個短語是實用考試指示。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":17},{"front":"list of opinions","meaning":"意見列表","examples":[{"en":"The question provides a list of opinions.","zh":"題目提供意見列表。"},{"en":"A list of opinions is a set of viewpoints that students must match with people or paragraphs.","zh":"意見列表是一組觀點，學生必須把它們與人物或段落配對。"},{"en":"Students should underline keywords in a list of opinions before searching the passage.","zh":"學生在搜尋文章前，應在意見列表中劃出關鍵詞。"},{"en":"If two opinions look similar, exact wording in the text becomes important.","zh":"如果兩個意見看起來相似，文本中的準確措辭就變得重要。"},{"en":"The phrase refers to answer choices based on views, not facts only.","zh":"這個短語指基於觀點而不只是事實的答案選項。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":17},{"front":"match each person with","meaning":"把每個人與……配對","examples":[{"en":"Students match each person with the opinion credited to him.","zh":"學生把每個人與歸於他的意見配對。"},{"en":"To match each person with something means to connect every person to the correct item.","zh":"“Match each person with” 某事指把每個人連接到正確項目。"},{"en":"A teacher may ask students to match each scientist with their discovery.","zh":"老師可能要求學生把每位科學家與其發現配對。"},{"en":"If a student matches a person with the wrong view, the answer will be incorrect.","zh":"如果學生把人物與錯誤觀點配對，答案就會錯。"},{"en":"The phrase is common in reading and listening exams.","zh":"這個短語常見於閱讀和聆聽考試。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":18},{"front":"be credited to","meaning":"歸於；被認為是……所說","examples":[{"en":"The opinion is credited to a particular person.","zh":"該意見被歸於某個特定人物。"},{"en":"To be credited to someone means to be attributed to that person as the source.","zh":"“Be credited to” 某人指被歸因於該人作為來源。"},{"en":"A famous quote may be credited to a writer even if people later check whether it is accurate.","zh":"名言可能被歸於某位作家，即使人們之後會查證是否準確。"},{"en":"If an opinion is credited to Dr Quartz, students should find where he expresses it.","zh":"如果意見被歸於 Quartz 博士，學生應找出他在哪裡表達它。"},{"en":"The phrase identifies who is believed to have said or held an idea.","zh":"這個短語指出某想法被認為由誰說出或持有。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":18},{"front":"contribute towards","meaning":"為……作出資助；幫補","examples":[{"en":"Neuromarketing could contribute towards the cost of medical technology.","zh":"神經市場學可以幫補醫療科技的成本。"},{"en":"To contribute towards something means to help pay for it or support it.","zh":"“Contribute towards” 某事指幫助支付或支援它。"},{"en":"Parents may contribute towards the cost of a school trip.","zh":"家長可能為學校旅行費用作出資助。"},{"en":"If companies rent brain scanners, the money may contribute towards equipment maintenance.","zh":"如果公司租用腦掃描儀，款項可能幫補設備維修。"},{"en":"The phrase suggests partial support, not paying everything.","zh":"這個短語暗示部分支援，而不是支付全部。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":18},{"front":"the cost of medical technology","meaning":"醫療科技的成本","examples":[{"en":"Renting out equipment may help cover the cost of medical technology.","zh":"出租設備可能有助支付醫療科技的成本。"},{"en":"The cost of medical technology is the money needed to buy, run, and maintain medical tools.","zh":"醫療科技的成本是購買、運作和維護醫療工具所需的金錢。"},{"en":"Hospitals must budget for the cost of medical technology such as scanners and monitors.","zh":"醫院必須為掃描儀和監察器等醫療科技的成本作預算。"},{"en":"If equipment is expensive, extra income may reduce the cost burden.","zh":"如果設備昂貴，額外收入可能減輕成本負擔。"},{"en":"The phrase focuses on the financial side of healthcare tools.","zh":"這個短語強調醫療工具的財務面。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":18},{"front":"a means of treating","meaning":"治療……的方法","examples":[{"en":"The option describes neuromarketing as a possible means of treating medical problems.","zh":"該選項把神經市場學描述為治療醫療問題的可能方法。"},{"en":"A means of treating something is a method used to cure, manage, or reduce a health problem.","zh":"治療某事的方法是用來治癒、管理或減少健康問題的方法。"},{"en":"Exercise can be a means of treating mild back pain for some patients.","zh":"對一些病人來說，運動可以是治療輕微背痛的方法。"},{"en":"If a technique is only used for market research, calling it a means of treating illness may be inaccurate.","zh":"如果一項技術只用於市場研究，把它稱為治療疾病的方法可能不準確。"},{"en":"The phrase focuses on medical use.","zh":"這個短語強調醫療用途。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":18},{"front":"existing problem","meaning":"現有問題","examples":[{"en":"Some critics believe neuromarketing could make an existing problem worse.","zh":"一些批評者認為神經市場學可能令現有問題惡化。"},{"en":"An existing problem is a difficulty that already exists before a new action or event happens.","zh":"現有問題是在新行動或事件發生前已經存在的困難。"},{"en":"A new timetable may make an existing transport problem worse if buses are already full.","zh":"如果巴士已經滿座，新時間表可能令現有交通問題惡化。"},{"en":"If advertising already contributes to unhealthy habits, neuromarketing may worsen that existing problem.","zh":"如果廣告已經促成不健康習慣，神經市場學可能加劇該現有問題。"},{"en":"The phrase contrasts old problems with new effects.","zh":"這個短語把舊問題與新影響作對比。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":18},{"front":"make something worse","meaning":"令……惡化","examples":[{"en":"Neuromarketing could make marketing-related problems worse.","zh":"神經市場學可能令與市場推廣有關的問題惡化。"},{"en":"To make something worse means to increase its seriousness, harm, or difficulty.","zh":"“Make something worse” 指增加其嚴重性、傷害或困難。"},{"en":"Ignoring a small leak can make the repair problem worse.","zh":"忽視小漏水可以令維修問題惡化。"},{"en":"If new advertising tools make unhealthy eating more attractive, they may make health problems worse.","zh":"如果新廣告工具令不健康飲食更吸引，它們可能令健康問題惡化。"},{"en":"The phrase shows negative cause and effect.","zh":"這個短語顯示負面因果關係。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":18},{"front":"lead to the misuse of","meaning":"導致……被濫用","examples":[{"en":"Some people worry that neuromarketing could lead to the misuse of medical equipment.","zh":"一些人擔心神經市場學可能導致醫療設備被濫用。"},{"en":"To lead to the misuse of something means to cause it to be used wrongly or irresponsibly.","zh":"“Lead to the misuse of” 某物指導致它被錯誤或不負責任地使用。"},{"en":"Poor data rules can lead to the misuse of personal information.","zh":"糟糕數據規則可能導致個人資料被濫用。"},{"en":"If hospitals rent scanners without limits, critics may fear misuse of medical equipment.","zh":"如果醫院無限制出租掃描儀，批評者可能擔心醫療設備被濫用。"},{"en":"The phrase connects a practice with a harmful consequence.","zh":"這個短語把做法與有害後果連繫起來。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":18},{"front":"prevent the exploitation of","meaning":"防止……被剝削","examples":[{"en":"Responsible advertising could help prevent the exploitation of consumers.","zh":"負責任廣告可以幫助防止消費者被剝削。"},{"en":"To prevent the exploitation of someone means to stop people from using them unfairly for profit or advantage.","zh":"“Prevent the exploitation of” 某人指阻止別人為了利潤或利益而不公平地利用他們。"},{"en":"Clear contracts can prevent the exploitation of workers by showing pay and duties.","zh":"清晰合約可以透過顯示薪酬和職責，防止工人被剝削。"},{"en":"If adverts are designed ethically, they may prevent the exploitation of vulnerable buyers.","zh":"如果廣告以倫理方式設計，可能防止弱勢買家被剝削。"},{"en":"The phrase focuses on protecting people from unfair use.","zh":"這個短語強調保護人們免受不公平利用。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":18},{"front":"exploitation of consumers","meaning":"剝削消費者","examples":[{"en":"Some critics worry about the exploitation of consumers.","zh":"一些批評者擔心剝削消費者。"},{"en":"Exploitation of consumers means using customers unfairly, often by manipulating weakness or lack of information.","zh":"剝削消費者指不公平地利用顧客，通常透過操控弱點或資訊不足。"},{"en":"Hidden fees can be a form of exploitation of consumers.","zh":"隱藏收費可以是一種剝削消費者的形式。"},{"en":"If brain data helps firms pressure people into buying, critics may call it exploitation.","zh":"如果腦部數據幫助企業迫使人購買，批評者可能稱之為剝削。"},{"en":"The phrase is used in debates about business ethics.","zh":"這個短語用於商業倫理辯論。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":18},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的詞語完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the short text under the question.","zh":"“Complete the summary below” 指填寫題目下方短文摘要中的缺漏詞語。"},{"en":"Students should read the whole sentence before completing the summary below.","zh":"學生應先閱讀整句，再完成以下摘要。"},{"en":"If the chosen word does not fit the grammar, the answer may be wrong.","zh":"如果所選詞語不符合文法，答案可能錯。"},{"en":"The phrase is a common reading-test instruction.","zh":"這個短語是常見閱讀測驗指示。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":18},{"front":"using words from the passage","meaning":"使用篇章中的字詞","examples":[{"en":"The answers must be written using words from the passage.","zh":"答案必須使用篇章中的字詞寫成。"},{"en":"Using words from the passage means copying or choosing exact words that appear in the text.","zh":"“Using words from the passage” 指抄寫或選擇文本中出現的準確字詞。"},{"en":"In completion tasks, students should use words from the passage rather than their own synonyms.","zh":"在填充題中，學生應使用篇章中的字詞，而不是自己的同義詞。"},{"en":"If the question requires passage words, paraphrasing may lose marks.","zh":"如果題目要求使用文章字詞，改寫可能會失分。"},{"en":"The phrase reminds students to base answers on the text.","zh":"這個短語提醒學生以文本為答題基礎。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":19},{"front":"choose one word only","meaning":"只選一個字","examples":[{"en":"Students should choose one word only from the passage.","zh":"學生應只從文章中選一個字。"},{"en":"Choose one word only means the answer must be exactly one word, not two or more.","zh":"“Choose one word only” 指答案必須正正是一個字，不能是兩個或以上。"},{"en":"If the answer is “surveys”, writing “market surveys” would break the one-word rule.","zh":"如果答案是 “surveys”，寫 “market surveys” 就違反一字規則。"},{"en":"Students should check spelling carefully when only one word is allowed.","zh":"當只允許一個字時，學生應仔細檢查拼字。"},{"en":"The phrase gives a strict exam limit.","zh":"這個短語給出嚴格考試限制。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":19},{"front":"provide valuable information on","meaning":"提供關於……的寶貴資料","examples":[{"en":"Neuromarketing can provide valuable information on consumer attitudes.","zh":"神經市場學可以提供關於消費者態度的寶貴資料。"},{"en":"To provide valuable information on something means to give useful knowledge about it.","zh":"“Provide valuable information on” 某事指提供關於它的有用知識。"},{"en":"A school survey can provide valuable information on students’ sleep habits.","zh":"學校調查可以提供關於學生睡眠習慣的寶貴資料。"},{"en":"If brain scans provide valuable information on hidden attitudes, companies may use them for planning.","zh":"如果腦掃描提供關於隱藏態度的寶貴資料，公司可能用它作規劃。"},{"en":"The phrase highlights information that helps decision-making.","zh":"這個短語強調有助決策的資料。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":19},{"front":"attitudes to particular brands","meaning":"對特定品牌的態度","examples":[{"en":"Neuromarketing can reveal attitudes to particular brands.","zh":"神經市場學可以揭示對特定品牌的態度。"},{"en":"Attitudes to particular brands are feelings or opinions about specific brand names or identities.","zh":"對特定品牌的態度，是對具體品牌名稱或身份的感受或意見。"},{"en":"A shopper may have positive attitudes to a brand because it reminds them of childhood.","zh":"購物者可能因某品牌令他想起童年，而對該品牌有正面態度。"},{"en":"If attitudes to particular brands are unconscious, people may not explain them in surveys.","zh":"如果對特定品牌的態度是無意識的，人們可能無法在問卷中解釋。"},{"en":"The phrase connects brand perception with personal response.","zh":"這個短語把品牌感知與個人反應連繫起來。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":19},{"front":"more reliable than surveys","meaning":"比問卷調查更可靠","examples":[{"en":"Neuromarketing may be more reliable than surveys in some situations.","zh":"在某些情況下，神經市場學可能比問卷調查更可靠。"},{"en":"More reliable than surveys means more trustworthy or accurate than asking people questions.","zh":"“More reliable than surveys” 指比向人提問更可信或準確。"},{"en":"Sales records may be more reliable than surveys when customers say one thing but buy another.","zh":"當顧客說一套買一套時，銷售紀錄可能比問卷調查更可靠。"},{"en":"If people cannot explain preferences honestly, brain responses may seem more reliable than survey answers.","zh":"如果人們不能誠實解釋偏好，腦部反應可能看似比問卷答案更可靠。"},{"en":"The phrase compares two research methods.","zh":"這個短語比較兩種研究方法。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":19},{"front":"be influenced by others","meaning":"受他人影響","examples":[{"en":"People in focus groups may be influenced by others.","zh":"焦點小組中的人可能受他人影響。"},{"en":"To be influenced by others means to have one’s thoughts or actions changed by other people.","zh":"“Be influenced by others” 指自己的想法或行動被他人改變。"},{"en":"A student may choose a course because they are influenced by friends.","zh":"學生可能因受朋友影響而選擇某課程。"},{"en":"If focus-group members are influenced by a dominant speaker, their answers may become less honest.","zh":"如果焦點小組成員受強勢發言者影響，其答案可能變得較不真誠。"},{"en":"The phrase explains why group research can be unreliable.","zh":"這個短語解釋為何小組研究可能不可靠。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":19},{"front":"identify thought patterns","meaning":"識別思維模式","examples":[{"en":"Brain scanning allows researchers to identify thought patterns.","zh":"腦部掃描讓研究人員能夠識別思維模式。"},{"en":"To identify thought patterns means to recognise repeated ways of thinking, reacting, or deciding.","zh":"“Identify thought patterns” 指辨認重複的思考、反應或決策方式。"},{"en":"A teacher may identify thought patterns by noticing the same mistake across many essays.","zh":"老師可能透過注意多篇作文中的同一錯誤來識別思維模式。"},{"en":"If scans identify thought patterns linked to reward, researchers may understand hidden preferences better.","zh":"如果掃描識別出與獎賞有關的思維模式，研究人員可能更好理解隱藏偏好。"},{"en":"The phrase focuses on recognising mental habits.","zh":"這個短語強調辨認心理習慣。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":19},{"front":"lead to problems such as","meaning":"導致例如……的問題","examples":[{"en":"Critics worry that neuromarketing could lead to problems such as disease.","zh":"批評者擔心神經市場學可能導致例如疾病的問題。"},{"en":"To lead to problems such as something means to cause or contribute to difficulties of that kind.","zh":"“Lead to problems such as” 某事指造成或促成那類困難。"},{"en":"Poor diet can lead to problems such as tiredness, weight gain, and illness.","zh":"糟糕飲食可以導致例如疲倦、體重增加和疾病的問題。"},{"en":"If advertising becomes too powerful, critics fear it may lead to health and social problems.","zh":"如果廣告變得太強大，批評者擔心它可能導致健康和社會問題。"},{"en":"The phrase introduces examples of possible negative results.","zh":"這個短語引出可能負面結果的例子。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":19},{"front":"an increase in disease","meaning":"疾病增加","examples":[{"en":"Some critics fear an increase in disease among children.","zh":"一些批評者擔心兒童中疾病增加。"},{"en":"An increase in disease means more cases of illness in a group or population.","zh":"疾病增加指某群體或人口中的患病個案增多。"},{"en":"A lack of clean water can cause an increase in disease in a community.","zh":"缺乏潔淨食水可以導致社區疾病增加。"},{"en":"If adverts encourage unhealthy habits, critics may fear an increase in obesity or diabetes.","zh":"如果廣告鼓勵不健康習慣，批評者可能擔心肥胖或糖尿病增加。"},{"en":"The phrase describes a rise in health problems.","zh":"這個短語描述健康問題上升。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":19},{"front":"among children","meaning":"在兒童之中","examples":[{"en":"Marketing-related diseases may increase among children.","zh":"與市場推廣有關的疾病可能在兒童之中增加。"},{"en":"Among children means within the group of children or affecting children as a group.","zh":"“Among children” 指在兒童群體內或影響兒童這一群體。"},{"en":"Short-sightedness has become more common among children in some cities.","zh":"在一些城市，近視在兒童之中變得更常見。"},{"en":"If junk-food advertising is strong among children, health risks may rise early in life.","zh":"如果垃圾食物廣告在兒童之中影響很強，健康風險可能在人生早期上升。"},{"en":"The phrase identifies the group affected.","zh":"這個短語指出受影響的群體。"}],"source":"108 - Inside the mind of the consumer.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 109":[{"front":"the wild side of town","meaning":"城市野性的一面","examples":[{"en":"The title “The Wild Side of Town” suggests that towns can contain rich wildlife.","zh":"標題「城市野性的一面」暗示城鎮可以包含豐富野生動植物。"},{"en":"The wild side of town means the natural, animal-filled part of urban life that people may not expect.","zh":"the wild side of town 指城市生活中自然、充滿動植物而人們未必預期的一面。"},{"en":"A child may discover the wild side of town by watching birds, insects, and frogs near a small park pond.","zh":"孩子可能透過在小公園池塘旁觀察鳥類、昆蟲和青蛙，發現城市野性的一面。"},{"en":"When cities create green spaces, the wild side of town becomes easier for residents to notice.","zh":"當城市創造綠色空間，居民便更容易注意到城市野性的一面。"},{"en":"This phrase reminds us that nature can exist inside cities, not only in remote countryside.","zh":"這個片語提醒我們，自然可以存在於城市之中，而不只在偏遠鄉郊。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":1},{"front":"the countryside","meaning":"鄉郊","examples":[{"en":"The countryside is no longer the only place to see wildlife.","zh":"鄉郊不再是唯一能看見野生動植物的地方。"},{"en":"The countryside means rural land outside towns and cities, often with fields, farms, and villages.","zh":"the countryside 指城鎮和城市以外的鄉村土地，通常有田野、農場和村莊。"},{"en":"Families may visit the countryside to walk, cycle, or enjoy open views.","zh":"家庭可能到鄉郊散步、踩單車或欣賞開闊景色。"},{"en":"If wildlife habitats decline in the countryside, some animals may survive better in towns.","zh":"如果鄉郊棲息地衰退，一些動物可能在城鎮中生存得更好。"},{"en":"This phrase contrasts rural areas with urban areas.","zh":"這個片語把鄉郊地區與城市地區作對比。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":1},{"front":"no longer the place to","meaning":"不再是……的地方","examples":[{"en":"The countryside is no longer the place to see wildlife.","zh":"鄉郊不再是看野生動植物的地方。"},{"en":"No longer the place to do something means it used to be the main place for that activity, but not now.","zh":"no longer the place to do something 指某地以前是做某事的主要地方，但現在不是。"},{"en":"The library is no longer the only place to find information because students also use online databases.","zh":"圖書館不再是尋找資料的唯一地方，因為學生也使用網上資料庫。"},{"en":"If towns now support many species, the countryside is no longer the only place to study nature.","zh":"如果城鎮現在支持許多物種，鄉郊就不再是研究自然的唯一地方。"},{"en":"This phrase shows that an old assumption has changed.","zh":"這個片語顯示舊有假設已經改變。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":1},{"front":"according to","meaning":"根據……","examples":[{"en":"According to Chris Barnes, towns now contain impressive wildlife.","zh":"根據 Chris Barnes 的說法，城鎮現在包含令人印象深刻的野生動植物。"},{"en":"According to someone means based on what that person says or reports.","zh":"according to someone 指根據某人所說或所報告的內容。"},{"en":"According to the teacher, students should read the question before looking at the options.","zh":"根據老師的說法，學生應先閱讀題目，再看選項。"},{"en":"According to the council’s report, the park is now home to more bird species.","zh":"根據議會報告，該公園現在是更多鳥類品種的棲息地。"},{"en":"This phrase introduces the source of an idea or piece of information.","zh":"這個片語引入想法或資料的來源。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":1},{"front":"these days","meaning":"現今","examples":[{"en":"These days, people may find wildlife in their own gardens.","zh":"現今，人們可能在自己的花園中找到野生動植物。"},{"en":"These days means nowadays or in the present period.","zh":"these days 指現今或目前這段時期。"},{"en":"These days, many students use phones to check bus times and homework messages.","zh":"現今，許多學生用電話查看巴士時間和功課訊息。"},{"en":"Because cities have more green spaces these days, some wildlife has become easier to see.","zh":"因為現今城市有更多綠色空間，一些野生動植物變得更容易看見。"},{"en":"This phrase compares the present with the past.","zh":"這個片語把現在與過去作比較。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":1},{"front":"be more likely to","meaning":"較有可能……","examples":[{"en":"You are more likely to find some wildlife in your own back garden.","zh":"你較有可能在自己的後花園找到一些野生動植物。"},{"en":"Be more likely to means have a greater chance of doing or experiencing something.","zh":"be more likely to 指做某事或經歷某事的機會較大。"},{"en":"A student who practises every day is more likely to improve in speaking.","zh":"每天練習的學生較有可能在口語方面進步。"},{"en":"If gardens provide food and shelter, birds are more likely to visit them.","zh":"如果花園提供食物和棲身處，鳥類較有可能到訪。"},{"en":"This phrase compares probabilities, not certainties.","zh":"這個片語比較可能性，而不是確定性。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":1},{"front":"impressive numbers of","meaning":"數量驚人的……","examples":[{"en":"People may find impressive numbers of skylarks and dragonflies in gardens.","zh":"人們可能在花園中找到數量驚人的雲雀和蜻蜓。"},{"en":"Impressive numbers of something means a surprisingly large or notable amount of it.","zh":"impressive numbers of something 指某物數量大得令人驚訝或值得注意。"},{"en":"A school open day may attract impressive numbers of parents if the programme is useful.","zh":"如果活動安排有用，學校開放日可能吸引數量驚人的家長。"},{"en":"When ponds are protected, impressive numbers of insects and frogs may appear.","zh":"當池塘受到保護，數量驚人的昆蟲和青蛙可能出現。"},{"en":"This phrase stresses that the amount is larger than expected.","zh":"這個片語強調數量比預期更大。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":1},{"front":"skylarks","meaning":"雲雀","examples":[{"en":"Skylarks may now be found in impressive numbers in some urban areas.","zh":"雲雀現在可能在一些城市地區以驚人數量出現。"},{"en":"Skylarks are small birds known for singing while flying high above open land.","zh":"skylarks 是小型鳥類，以在開闊土地上空高飛時鳴唱聞名。"},{"en":"A birdwatcher may hear skylarks before seeing them because their song carries through the air.","zh":"觀鳥者可能先聽到雲雀，才看見牠們，因為牠們的歌聲會在空中傳開。"},{"en":"If open grassy areas disappear, skylarks may lose places to feed and nest.","zh":"如果開闊草地消失，雲雀可能失去覓食和築巢地方。"},{"en":"This word refers to a particular kind of bird, not birds in general.","zh":"這個詞指一種特定鳥類，而不是泛指鳥。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":1},{"front":"dragonflies","meaning":"蜻蜓","examples":[{"en":"Dragonflies can benefit from urban ponds and wetlands.","zh":"蜻蜓可以受益於城市池塘和濕地。"},{"en":"Dragonflies are flying insects with long bodies and wide wings, often seen near water.","zh":"dragonflies 是有長身體和寬翅膀的飛行昆蟲，常在水邊出現。"},{"en":"Children may see dragonflies flying over a pond in a public park.","zh":"孩子可能在公園池塘上方看見蜻蜓飛行。"},{"en":"If ponds are cleaned and protected, dragonflies have better places to breed.","zh":"如果池塘被清潔和保護，蜻蜓會有更好的繁殖地方。"},{"en":"This word often appears in discussions of freshwater habitats and garden wildlife.","zh":"這個詞常出現在淡水棲息地和花園野生動植物的討論中。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":1},{"front":"toads","meaning":"蟾蜍","examples":[{"en":"Toads may be found in people’s back gardens.","zh":"蟾蜍可能在人的後花園中被發現。"},{"en":"Toads are small amphibians similar to frogs, often with drier, bumpier skin.","zh":"toads 是類似青蛙的小型兩棲動物，皮膚通常較乾且較粗糙。"},{"en":"A toad may hide under a flowerpot during the day and come out at night.","zh":"蟾蜍白天可能躲在花盆下，晚上才出來。"},{"en":"If gardens contain damp corners and insects, toads may survive there.","zh":"如果花園有潮濕角落和昆蟲，蟾蜍可能在那裡生存。"},{"en":"This word refers to an animal that needs both land and moist conditions.","zh":"這個詞指一種需要陸地和潮濕條件的動物。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":1},{"front":"in your own back garden","meaning":"在自己的後花園","examples":[{"en":"You may find impressive wildlife in your own back garden.","zh":"你可能在自己的後花園找到令人印象深刻的野生動植物。"},{"en":"In your own back garden means very close to home, in the private outdoor space behind your house.","zh":"in your own back garden 指就在家附近，在房子後面的私人戶外空間。"},{"en":"A family may grow herbs, flowers, and vegetables in their own back garden.","zh":"家庭可能在自己的後花園種香草、花卉和蔬菜。"},{"en":"If wildlife appears in your own back garden, nature feels less distant and more personal.","zh":"如果野生動植物出現在自己的後花園，自然便感覺不再遙遠，而更貼近個人。"},{"en":"This phrase suggests that discovery can happen nearby, not only on special trips.","zh":"這個片語暗示發現可以在附近發生，而不只在特別旅行中發生。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":1},{"front":"the past half century","meaning":"過去半個世紀","examples":[{"en":"The past half century has seen a reversal in Britain’s wildlife fortunes.","zh":"過去半個世紀見證了英國野生動植物命運的逆轉。"},{"en":"The past half century means the last fifty years.","zh":"the past half century 指過去五十年。"},{"en":"The past half century has changed how people work, travel, and communicate.","zh":"過去半個世紀改變了人們工作、旅行和溝通的方式。"},{"en":"If wildlife patterns change over the past half century, scientists can compare old and new records.","zh":"如果野生動植物模式在過去半個世紀改變，科學家可以比較舊紀錄和新紀錄。"},{"en":"This phrase gives a broad historical time frame.","zh":"這個片語給出廣闊的歷史時間範圍。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":2},{"front":"see a reversal in","meaning":"見證……的逆轉","examples":[{"en":"The past half century has seen a reversal in the fortunes of British wildlife.","zh":"過去半個世紀見證了英國野生動植物命運的逆轉。"},{"en":"To see a reversal in something means to experience or show a major change in the opposite direction.","zh":"see a reversal in something 指經歷或顯示某事朝相反方向出現重大轉變。"},{"en":"A school may see a reversal in exam results after improving teaching support.","zh":"學校改善教學支援後，可能見證考試成績的逆轉。"},{"en":"If rural wildlife declines while urban wildlife grows, we see a reversal in where nature thrives.","zh":"如果鄉郊野生動植物下降而城市野生動植物增加，我們就看見自然繁盛地點的逆轉。"},{"en":"This phrase shows a clear turn from one situation to another.","zh":"這個片語顯示由一種情況清楚轉向另一種情況。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":2},{"front":"a reversal in the fortunes of","meaning":"……命運的逆轉","examples":[{"en":"There has been a reversal in the fortunes of much of Britain’s wildlife.","zh":"英國大部分野生動植物的命運出現了逆轉。"},{"en":"A reversal in the fortunes of something means its situation has changed strongly, often from bad to good or good to bad.","zh":"a reversal in the fortunes of something 指某事物的處境出現強烈轉變，常由壞變好或由好變壞。"},{"en":"A small shop may experience a reversal in its fortunes after a new train station opens nearby.","zh":"新火車站在附近開通後，小店可能經歷命運逆轉。"},{"en":"If urban habitats improve, some animals may experience a reversal in their fortunes.","zh":"如果城市棲息地改善，一些動物可能經歷命運逆轉。"},{"en":"This phrase is used when success, survival, or condition changes sharply.","zh":"當成功、生存或狀況急劇改變時，會使用這個片語。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":2},{"front":"much of Britain’s wildlife","meaning":"英國大部分野生動植物","examples":[{"en":"Much of Britain’s wildlife has changed its distribution.","zh":"英國大部分野生動植物已改變其分布。"},{"en":"Much of Britain’s wildlife means a large proportion of wild plants and animals in Britain.","zh":"much of Britain’s wildlife 指英國野生植物和動物中的很大一部分。"},{"en":"Much of Britain’s wildlife depends on gardens, ponds, parks, and old industrial land.","zh":"英國大部分野生動植物依賴花園、池塘、公園和舊工業土地。"},{"en":"If habitats change, much of Britain’s wildlife may move, decline, or recover in different places.","zh":"如果棲息地改變，英國大部分野生動植物可能在不同地方遷移、衰退或恢復。"},{"en":"This phrase refers to many species, not just one animal.","zh":"這個片語指許多物種，而不是一種動物。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":2},{"front":"whilst","meaning":"然而；雖然","examples":[{"en":"Whilst rural habitats have declined, urban habitats have grown.","zh":"雖然鄉郊棲息地已經衰退，城市棲息地卻增長了。"},{"en":"Whilst means while or although, and it often introduces a contrast.","zh":"whilst 意思是 while 或 although，常用來引入對比。"},{"en":"Whilst some students prefer quiet study, others learn better through discussion.","zh":"雖然有些學生較喜歡安靜溫習，另一些則透過討論學得更好。"},{"en":"Whilst farmland has lost hedges, towns may have gained connected green corridors.","zh":"雖然農田失去了樹籬，城鎮可能增加了互相連接的綠色走廊。"},{"en":"This word is more formal and more British than while.","zh":"這個詞比 while 更正式，也更具英式用法。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":2},{"front":"rural countryside","meaning":"鄉郊地區","examples":[{"en":"The rural countryside has become poorer in wildlife.","zh":"鄉郊地區的野生動植物變得較貧乏。"},{"en":"Rural countryside means land outside towns and cities, especially farmland, villages, and open fields.","zh":"rural countryside 指城鎮和城市以外的土地，尤其是農田、村莊和開闊田野。"},{"en":"People may visit the rural countryside for walking routes and quiet views.","zh":"人們可能到鄉郊地區行山和欣賞寧靜景色。"},{"en":"If farms use heavy chemicals, the rural countryside may support fewer insects and birds.","zh":"如果農場大量使用化學品，鄉郊地區可能支持較少昆蟲和鳥類。"},{"en":"This phrase contrasts strongly with urban neighbourhoods.","zh":"這個片語與城市社區形成強烈對比。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":2},{"front":"become poorer and poorer","meaning":"變得越來越貧乏","examples":[{"en":"The rural countryside has become poorer and poorer in wildlife.","zh":"鄉郊地區的野生動植物變得越來越貧乏。"},{"en":"Become poorer and poorer means gradually lose richness, variety, or quality.","zh":"become poorer and poorer 指逐漸失去豐富度、多樣性或質素。"},{"en":"A library becomes poorer and poorer if old books are removed and no new ones are added.","zh":"如果舊書被移走而沒有新書加入，圖書館會變得越來越貧乏。"},{"en":"If hedges and ponds disappear, farmland becomes poorer and poorer as a wildlife habitat.","zh":"如果樹籬和池塘消失，農田作為野生動植物棲息地會變得越來越貧乏。"},{"en":"This phrase describes a continuing decline.","zh":"這個片語描述持續衰退。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":2},{"front":"wildlife habitat","meaning":"野生動植物棲息地","examples":[{"en":"Wildlife habitat in towns has burgeoned.","zh":"城鎮中的野生動植物棲息地已迅速增長。"},{"en":"Wildlife habitat is a place where wild plants and animals can live, feed, breed, and shelter.","zh":"wildlife habitat 是野生植物和動物可以生活、覓食、繁殖和棲身的地方。"},{"en":"A small pond can become wildlife habitat for frogs, insects, and birds.","zh":"小池塘可以成為青蛙、昆蟲和鳥類的野生動植物棲息地。"},{"en":"If a city protects parks and gardens, wildlife habitat can increase even in busy areas.","zh":"如果城市保護公園和花園，即使在繁忙地區，野生動植物棲息地也可以增加。"},{"en":"This phrase refers to living space for nature.","zh":"這個片語指自然的生活空間。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":2},{"front":"has burgeoned","meaning":"迅速增長；蓬勃發展","examples":[{"en":"Wildlife habitat in towns has burgeoned.","zh":"城鎮中的野生動植物棲息地已迅速增長。"},{"en":"Has burgeoned means has grown or increased quickly and strongly.","zh":"has burgeoned 指快速而強勁地增長或增加。"},{"en":"Online learning has burgeoned since schools began using more digital tools.","zh":"自從學校使用更多數碼工具，網上學習已蓬勃發展。"},{"en":"If abandoned land becomes woodland and wetland, urban wildlife habitat has burgeoned.","zh":"如果廢棄土地變成林地和濕地，城市野生動植物棲息地便已迅速增長。"},{"en":"This phrase suggests rapid growth, not slow minor change.","zh":"這個片語暗示快速增長，而不是緩慢小變化。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":2},{"front":"deafening dawn chorus","meaning":"震耳欲聾的黎明鳥鳴大合唱","examples":[{"en":"People can hear a deafening dawn chorus of birds in towns.","zh":"人們可以在城鎮中聽到震耳欲聾的黎明鳥鳴大合唱。"},{"en":"A deafening dawn chorus is very loud birdsong heard early in the morning.","zh":"deafening dawn chorus 指清晨聽到非常響亮的鳥鳴聲。"},{"en":"A person may wake at sunrise because the dawn chorus outside the window is so loud.","zh":"一個人可能在日出時被窗外響亮的黎明鳥鳴大合唱叫醒。"},{"en":"If many birds live in an area, the dawn chorus can become a sign of rich wildlife.","zh":"如果某區有許多鳥類，黎明鳥鳴大合唱可以成為野生動植物豐富的標誌。"},{"en":"This phrase describes both sound and abundance.","zh":"這個片語同時描述聲音和數量。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":2},{"front":"familiarise yourself with","meaning":"使自己熟悉……","examples":[{"en":"You can familiarise yourself with foxes in the urban forest.","zh":"你可以在城市森林中使自己熟悉狐狸。"},{"en":"To familiarise yourself with something means to learn about it until it feels less strange.","zh":"familiarise yourself with something 指學習某事，直到它感覺不再陌生。"},{"en":"Students should familiarise themselves with exam instructions before test day.","zh":"學生應在考試前熟悉考試指示。"},{"en":"If residents familiarise themselves with local wildlife, they may become less afraid of it.","zh":"如果居民熟悉本地野生動植物，可能會較少害怕它們。"},{"en":"This phrase suggests learning through attention and repeated contact.","zh":"這個片語暗示透過留意和反覆接觸來學習。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":2},{"front":"head for","meaning":"前往","examples":[{"en":"People can head for the urban forest to see wildlife.","zh":"人們可以前往城市森林觀察野生動植物。"},{"en":"To head for a place means to go towards it.","zh":"head for a place 指朝某地前往。"},{"en":"After school, students may head for the library to finish homework.","zh":"放學後，學生可能前往圖書館完成功課。"},{"en":"If you want to hear birdsong, you can head for a park early in the morning.","zh":"如果你想聽鳥鳴，可以清晨前往公園。"},{"en":"This phrase is common in everyday speech about direction and destination.","zh":"這個片語常用於日常英語中談方向和目的地。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":3},{"front":"urban forest","meaning":"城市森林","examples":[{"en":"The urban forest can provide a home for many species.","zh":"城市森林可以為許多物種提供家園。"},{"en":"An urban forest is the trees and wooded green areas found within a town or city.","zh":"urban forest 指城鎮或城市中的樹木和林地綠化區域。"},{"en":"Street trees, parks, and garden trees all form part of the urban forest.","zh":"街樹、公園和花園樹木都構成城市森林的一部分。"},{"en":"If an urban forest grows, it can cool streets, shelter birds, and improve air quality.","zh":"如果城市森林增長，它可以為街道降溫、庇護鳥類並改善空氣質素。"},{"en":"This phrase treats city trees as a connected natural system.","zh":"這個片語把城市樹木視為互相連接的自然系統。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":3},{"front":"species that depend on","meaning":"依賴……的物種","examples":[{"en":"Some species depend on wide open spaces.","zh":"一些物種依賴廣闊空地。"},{"en":"Species that depend on something need it in order to survive, feed, or reproduce.","zh":"species that depend on something 指需要某物才能生存、覓食或繁殖的物種。"},{"en":"Bees are species that depend on flowers for nectar and pollen.","zh":"蜜蜂是依賴花朵取得花蜜和花粉的物種。"},{"en":"If a species depends on open land, building over that land may threaten it.","zh":"如果某物種依賴開闊土地，在該土地上建樓可能威脅它。"},{"en":"This phrase explains a close link between an organism and its habitat.","zh":"這個片語解釋生物與其棲息地之間的密切連繫。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":3},{"front":"wide open spaces","meaning":"廣闊空地","examples":[{"en":"Hares and eagles depend on wide open spaces.","zh":"野兔和鷹依賴廣闊空地。"},{"en":"Wide open spaces are large areas of land without many buildings, trees, or barriers.","zh":"wide open spaces 是沒有很多建築物、樹木或障礙物的大面積土地。"},{"en":"Children may enjoy running in wide open spaces at a country park.","zh":"孩子可能喜歡在郊野公園的廣闊空地奔跑。"},{"en":"Animals that hunt or run across long distances often need wide open spaces.","zh":"需要長距離奔跑或狩獵的動物通常需要廣闊空地。"},{"en":"This phrase contrasts with crowded streets or enclosed gardens.","zh":"這個片語與擁擠街道或封閉花園形成對比。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":3},{"front":"the hare","meaning":"野兔","examples":[{"en":"The hare may still be restricted to remote rural landscapes.","zh":"野兔可能仍然只限於偏遠鄉郊景觀。"},{"en":"A hare is a fast-running wild animal similar to a rabbit but usually larger and with longer legs.","zh":"hare 是一種奔跑很快的野生動物，類似兔子，但通常較大、腿較長。"},{"en":"A farmer may see a hare crossing an open field at dawn.","zh":"農夫可能在黎明看見野兔穿過開闊田野。"},{"en":"If open farmland disappears, the hare may lose the space it needs to run and hide.","zh":"如果開闊農地消失，野兔可能失去奔跑和躲藏所需的空間。"},{"en":"This word refers to a wild animal, not a domestic pet rabbit.","zh":"這個詞指野生動物，而不是家養寵物兔。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":3},{"front":"the eagle","meaning":"鷹","examples":[{"en":"The eagle may still depend on remote rural landscapes.","zh":"鷹可能仍然依賴偏遠鄉郊景觀。"},{"en":"An eagle is a large bird of prey with strong eyesight, powerful wings, and sharp claws.","zh":"eagle 是大型猛禽，有強大視力、有力翅膀和尖銳爪。"},{"en":"Hikers may see an eagle circling above a mountain valley.","zh":"行山人士可能看見鷹在山谷上空盤旋。"},{"en":"If wide hunting areas disappear, eagles may struggle to find enough food.","zh":"如果廣闊狩獵區消失，鷹可能難以找到足夠食物。"},{"en":"This word usually suggests a powerful wild bird that needs large territories.","zh":"這個詞通常暗示需要大領地的強大野鳥。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":3},{"front":"red deer","meaning":"赤鹿","examples":[{"en":"Red deer may still be restricted to remote rural landscapes.","zh":"赤鹿可能仍然只限於偏遠鄉郊景觀。"},{"en":"Red deer are large wild deer found in open moorland, woodland, and rural areas.","zh":"red deer 是大型野生鹿，見於開闊荒原、林地和鄉郊地區。"},{"en":"Visitors may see red deer in a national park during autumn.","zh":"遊客可能在秋天於國家公園看見赤鹿。"},{"en":"If towns are too crowded and noisy, red deer are unlikely to live there permanently.","zh":"如果城鎮太擠迫和嘈雜，赤鹿不太可能長期生活在那裡。"},{"en":"This phrase names a particular large mammal, not deer in general.","zh":"這個片語指一種特定大型哺乳動物，而不是泛指鹿。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":3},{"front":"be restricted to","meaning":"只限於……","examples":[{"en":"Some species are still restricted to remote rural landscapes.","zh":"一些物種仍然只限於偏遠鄉郊景觀。"},{"en":"To be restricted to a place means to be limited to that place.","zh":"be restricted to a place 指被限制在某地方。"},{"en":"A school library may be restricted to students and teachers only.","zh":"學校圖書館可能只限學生和老師使用。"},{"en":"If an animal is restricted to one habitat, damage to that habitat can be serious.","zh":"如果動物只限於一種棲息地，該棲息地受損就可能很嚴重。"},{"en":"This phrase shows limitation in location, use, or access.","zh":"這個片語顯示地點、用途或進入權的限制。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":3},{"front":"remote rural landscapes","meaning":"偏遠鄉郊景觀","examples":[{"en":"Some animals still live mainly in remote rural landscapes.","zh":"一些動物仍主要生活在偏遠鄉郊景觀中。"},{"en":"Remote rural landscapes are countryside areas far from towns, cities, and busy human activity.","zh":"remote rural landscapes 是遠離城鎮、城市和繁忙人類活動的鄉郊地區。"},{"en":"A remote rural landscape may include mountains, open moors, farms, and forests.","zh":"偏遠鄉郊景觀可能包括山地、開闊荒原、農場和森林。"},{"en":"Species that need quiet and space may survive better in remote rural landscapes.","zh":"需要安靜和空間的物種可能在偏遠鄉郊景觀中生存得更好。"},{"en":"This phrase suggests distance, low population, and natural space.","zh":"這個片語暗示距離遠、人口少和自然空間。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":3},{"front":"wild plants and animals","meaning":"野生植物和動物","examples":[{"en":"Many wild plants and animals find the urban ecosystem ideal.","zh":"許多野生植物和動物覺得城市生態系統很理想。"},{"en":"Wild plants and animals are species that live naturally without being farmed or kept as pets.","zh":"wild plants and animals 是自然生活、不是被種植或作寵物飼養的物種。"},{"en":"Grass, insects, birds, and frogs in a park are examples of wild plants and animals.","zh":"公園中的草、昆蟲、鳥和青蛙都是野生植物和動物的例子。"},{"en":"If gardens provide food and shelter, wild plants and animals may settle there.","zh":"如果花園提供食物和棲身處，野生植物和動物可能在那裡定居。"},{"en":"This phrase includes both plant life and animal life.","zh":"這個片語包括植物生命和動物生命。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":3},{"front":"urban ecosystem","meaning":"城市生態系統","examples":[{"en":"Many species find the urban ecosystem ideal.","zh":"許多物種覺得城市生態系統很理想。"},{"en":"An urban ecosystem is the network of living things, buildings, parks, water, soil, and people within a city.","zh":"urban ecosystem 是城市中生物、建築、公園、水、土壤和人的網絡。"},{"en":"A city pond, street trees, insects, birds, and residents all belong to the urban ecosystem.","zh":"城市池塘、街樹、昆蟲、鳥類和居民都屬於城市生態系統。"},{"en":"If an urban ecosystem has connected habitats, wildlife can move and survive more easily.","zh":"如果城市生態系統有連接的棲息地，野生動植物可以更容易移動和生存。"},{"en":"This phrase treats the city as a living environmental system.","zh":"這個片語把城市視為一個有生命的環境系統。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":3},{"front":"this really should be no surprise","meaning":"這實在不應令人驚訝","examples":[{"en":"This really should be no surprise because farmland habitats have declined.","zh":"這實在不應令人驚訝，因為農田棲息地已經衰退。"},{"en":"This really should be no surprise means the result is understandable when we consider the reasons.","zh":"this really should be no surprise 指當我們考慮原因時，結果是可以理解的。"},{"en":"If a student never revises, a low mark really should be no surprise.","zh":"如果學生從不溫習，低分實在不應令人驚訝。"},{"en":"If rural habitats are damaged, urban wildlife growth should be less surprising.","zh":"如果鄉郊棲息地受損，城市野生動植物增長就不應那麼令人驚訝。"},{"en":"This phrase prepares the reader for an explanation.","zh":"這個片語讓讀者準備理解後面的解釋。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":4},{"front":"fragmentation","meaning":"碎片化","examples":[{"en":"Habitat fragmentation has contributed to the decline of many species.","zh":"棲息地碎片化導致了許多物種衰退。"},{"en":"Fragmentation means something is broken into smaller, separated pieces.","zh":"fragmentation 指某物被分裂成較小、互相分離的部分。"},{"en":"A community can suffer fragmentation if busy roads divide neighbourhoods.","zh":"如果繁忙道路把社區分隔開，社區可能出現碎片化。"},{"en":"When habitats are fragmented, animals may struggle to move, feed, or find mates.","zh":"當棲息地碎片化，動物可能難以移動、覓食或尋找伴侶。"},{"en":"This word often describes damage caused by breaking connected areas apart.","zh":"這個詞常描述連接地區被打散造成的破壞。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":4},{"front":"agrochemical pollution","meaning":"農用化學品污染","examples":[{"en":"Agrochemical pollution has harmed wildlife in farming lowlands.","zh":"農用化學品污染傷害了低地農田中的野生動植物。"},{"en":"Agrochemical pollution is pollution caused by farm chemicals such as pesticides and fertilisers.","zh":"agrochemical pollution 是由殺蟲劑和肥料等農場化學品造成的污染。"},{"en":"A stream near farms may suffer agrochemical pollution after heavy rain washes chemicals into it.","zh":"大雨把化學品沖入溪流後，農場附近的小溪可能受到農用化學品污染。"},{"en":"If insects die because of agrochemical pollution, birds may also lose food.","zh":"如果昆蟲因農用化學品污染死亡，鳥類也可能失去食物。"},{"en":"This phrase links farming chemicals with environmental damage.","zh":"這個片語把農業化學品與環境破壞連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":4},{"front":"farming lowlands","meaning":"低地農田","examples":[{"en":"Agrochemical pollution in the farming lowlands has damaged wildlife.","zh":"低地農田中的農用化學品污染傷害了野生動植物。"},{"en":"Farming lowlands are low, flat agricultural areas used for crops or livestock.","zh":"farming lowlands 是用於種植或畜牧的低平農業地區。"},{"en":"Farming lowlands may contain fields, drainage ditches, hedges, and farm tracks.","zh":"低地農田可能包含田野、排水溝、樹籬和農道。"},{"en":"If farming lowlands are managed intensively, wildlife may have fewer safe places to live.","zh":"如果低地農田被密集管理，野生動植物可能有較少安全居住地。"},{"en":"This phrase describes a type of rural farmland landscape.","zh":"這個片語描述一種鄉郊農田景觀。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":4},{"front":"lead to","meaning":"導致","examples":[{"en":"Fragmentation and pollution have led to species decline.","zh":"碎片化和污染導致物種衰退。"},{"en":"To lead to something means to cause it or make it happen.","zh":"lead to something 指造成某事或令某事發生。"},{"en":"Poor sleep can lead to weak concentration in class.","zh":"睡眠不足可以導致課堂專注力弱。"},{"en":"If ponds are filled in, the loss of water habitat can lead to fewer frogs.","zh":"如果池塘被填平，水域棲息地流失可以導致青蛙減少。"},{"en":"This phrase connects a cause with its result.","zh":"這個片語把原因與結果連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":4},{"front":"catastrophic decline","meaning":"災難性下降","examples":[{"en":"Many species have suffered a catastrophic decline.","zh":"許多物種遭受災難性下降。"},{"en":"A catastrophic decline is an extremely serious and damaging fall in number or quality.","zh":"catastrophic decline 是數量或質素極其嚴重而具破壞性的下降。"},{"en":"A school club may suffer a catastrophic decline if almost all members leave at once.","zh":"如果幾乎所有會員同時離開，學校社團可能遭受災難性下降。"},{"en":"If insects suffer a catastrophic decline, birds and other animals may lose food.","zh":"如果昆蟲遭受災難性下降，鳥類和其他動物可能失去食物。"},{"en":"This phrase is much stronger than a small decrease.","zh":"這個片語比小幅下降強烈得多。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":4},{"front":"so many species","meaning":"如此多物種","examples":[{"en":"Pollution has led to the decline of so many species.","zh":"污染導致如此多物種衰退。"},{"en":"So many species means a very large number of different kinds of living things.","zh":"so many species 指非常多不同種類的生物。"},{"en":"A healthy pond can support so many species, from insects to birds.","zh":"健康池塘可以支持如此多物種，從昆蟲到鳥類都有。"},{"en":"If so many species decline together, the whole ecosystem may be under pressure.","zh":"如果如此多物種一起衰退，整個生態系統可能承受壓力。"},{"en":"This phrase stresses both number and variety.","zh":"這個片語同時強調數量和多樣性。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":4},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, many urban open spaces have avoided heavy pesticide use.","zh":"相比之下，許多城市開放空間避過了大量殺蟲劑使用。"},{"en":"By contrast means compared with the previous point, the next point is different.","zh":"by contrast 指與前一點相比，下一點有所不同。"},{"en":"The old classroom is noisy; by contrast, the library is quiet.","zh":"舊課室很嘈吵；相比之下，圖書館很安靜。"},{"en":"Rural fields may be heavily sprayed; by contrast, city parks may use fewer chemicals.","zh":"鄉郊田野可能大量噴灑化學品；相比之下，城市公園可能使用較少化學品。"},{"en":"This phrase makes a clear comparison between two situations.","zh":"這個片語清楚比較兩種情況。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":4},{"front":"urban open spaces","meaning":"城市開放空間","examples":[{"en":"Urban open spaces can provide important habitats for wildlife.","zh":"城市開放空間可以為野生動植物提供重要棲息地。"},{"en":"Urban open spaces are parks, playing fields, gardens, wastelands, and other open areas in towns or cities.","zh":"urban open spaces 是城鎮或城市中的公園、球場、花園、荒地和其他開闊地區。"},{"en":"Residents may use urban open spaces for walking, exercise, and meeting neighbours.","zh":"居民可能使用城市開放空間散步、運動和與鄰居見面。"},{"en":"If urban open spaces include trees and ponds, they can support birds and insects.","zh":"如果城市開放空間包含樹木和池塘，它們可以支持鳥類和昆蟲。"},{"en":"This phrase refers to open land within built-up areas.","zh":"這個片語指建成區內的開闊土地。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":4},{"front":"escape the worst of","meaning":"避過……最壞的影響","examples":[{"en":"Urban open spaces have escaped the worst of the pesticide revolution.","zh":"城市開放空間避過了殺蟲劑革命最壞的影響。"},{"en":"To escape the worst of something means to avoid its most harmful effects.","zh":"escape the worst of something 指避開某事最有害的影響。"},{"en":"A village may escape the worst of a storm if the strongest winds pass north of it.","zh":"如果最強風向北掠過，村莊可能避過風暴最壞的影響。"},{"en":"If city parks use fewer chemicals, they may escape the worst of pesticide damage.","zh":"如果城市公園使用較少化學品，它們可能避過殺蟲劑傷害最壞的影響。"},{"en":"This phrase suggests harm still exists, but the most severe part is avoided.","zh":"這個片語暗示傷害仍可能存在，但最嚴重部分被避開。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":4},{"front":"pesticide revolution","meaning":"殺蟲劑革命；殺蟲劑大量使用","examples":[{"en":"The pesticide revolution affected many rural habitats.","zh":"殺蟲劑革命影響了許多鄉郊棲息地。"},{"en":"The pesticide revolution refers to the widespread modern use of chemical pesticides in farming.","zh":"pesticide revolution 指農業中現代化學殺蟲劑的大規模使用。"},{"en":"Farmers used pesticides to protect crops, but insects and birds could also be harmed.","zh":"農民使用殺蟲劑保護農作物，但昆蟲和鳥類也可能受害。"},{"en":"If pesticide use becomes intense, wildlife habitats may lose food sources.","zh":"如果殺蟲劑使用變得密集，野生動植物棲息地可能失去食物來源。"},{"en":"This phrase describes a major change in agricultural practice.","zh":"這個片語描述農業做法中的重大變化。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":4},{"front":"an intimate mosaic of","meaning":"緊密交織的……拼圖","examples":[{"en":"Urban areas form an intimate mosaic of interconnected habitats.","zh":"城市地區形成一幅緊密交織的互連棲息地拼圖。"},{"en":"An intimate mosaic of something means many small parts closely fitted together.","zh":"an intimate mosaic of something 指許多小部分緊密拼合在一起。"},{"en":"A neighbourhood can be an intimate mosaic of homes, shops, gardens, and small parks.","zh":"社區可以是一幅由住宅、商店、花園和小公園組成的緊密拼圖。"},{"en":"If habitats form a mosaic, animals can move from one small place to another.","zh":"如果棲息地形成拼圖，動物可以從一個小地方移到另一個小地方。"},{"en":"This phrase suggests close connection and variety.","zh":"這個片語暗示緊密連接和多樣性。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":5},{"front":"interconnected habitats","meaning":"互相連接的棲息地","examples":[{"en":"Towns contain many interconnected habitats.","zh":"城鎮包含許多互相連接的棲息地。"},{"en":"Interconnected habitats are habitats linked together so wildlife can move between them.","zh":"interconnected habitats 是彼此相連、讓野生動植物能在其間移動的棲息地。"},{"en":"A pond, hedge, park, and railway bank can become interconnected habitats in a city.","zh":"池塘、樹籬、公園和鐵路堤岸可以在城市中成為互相連接的棲息地。"},{"en":"If habitats are interconnected, animals are less trapped in isolated spaces.","zh":"如果棲息地互相連接，動物就較少被困在孤立空間。"},{"en":"This phrase is important for understanding urban ecological corridors.","zh":"這個片語對理解城市生態走廊很重要。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":5},{"front":"over the years","meaning":"多年來","examples":[{"en":"Over the years, hedgerow loss has damaged farmland habitats.","zh":"多年來，樹籬流失破壞了農田棲息地。"},{"en":"Over the years means gradually during a long period of time.","zh":"over the years 指在很長時間中逐漸地。"},{"en":"Over the years, a quiet student may become more confident through practice.","zh":"多年來，安靜的學生可能透過練習變得更有信心。"},{"en":"If hedges are removed over the years, wildlife routes across farmland may disappear.","zh":"如果多年來樹籬被移除，穿過農田的野生動植物路線可能消失。"},{"en":"This phrase suggests slow change rather than a sudden event.","zh":"這個片語暗示緩慢變化，而不是突然事件。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":5},{"front":"cutting down of hedgerows","meaning":"砍伐樹籬","examples":[{"en":"The cutting down of hedgerows has contributed to habitat isolation.","zh":"砍伐樹籬導致了棲息地孤立。"},{"en":"The cutting down of hedgerows means removing lines of shrubs or small trees from fields or boundaries.","zh":"cutting down of hedgerows 指從田地或邊界移除一排排灌木或小樹。"},{"en":"Farmers may cut down hedgerows to create larger fields for machinery.","zh":"農民可能砍伐樹籬，以創造更大的田地供機械使用。"},{"en":"If hedgerows are cut down, birds and small mammals may lose shelter and routes.","zh":"如果樹籬被砍伐，鳥類和小型哺乳動物可能失去庇護和路線。"},{"en":"This phrase describes a human action that can fragment habitats.","zh":"這個片語描述可能令棲息地碎片化的人類行為。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":5},{"front":"hedgerows","meaning":"樹籬","examples":[{"en":"Hedgerows once helped link habitats on farmland.","zh":"樹籬曾幫助連接農田上的棲息地。"},{"en":"Hedgerows are lines of bushes or small trees planted along field edges or boundaries.","zh":"hedgerows 是沿田邊或邊界種植的一排灌木或小樹。"},{"en":"Birds may nest in hedgerows because they provide cover and food.","zh":"鳥類可能在樹籬中築巢，因為它們提供遮蔽和食物。"},{"en":"If hedgerows are removed, wildlife may lose safe corridors between fields.","zh":"如果樹籬被移除，野生動植物可能失去田地之間的安全走廊。"},{"en":"This word is common in discussions of farmland ecology.","zh":"這個詞常見於農田生態討論。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":5},{"front":"farmland","meaning":"農田","examples":[{"en":"The cutting down of hedgerows on farmland has harmed wildlife.","zh":"農田上的樹籬砍伐傷害了野生動植物。"},{"en":"Farmland is land used for growing crops or keeping animals.","zh":"farmland 是用來種植農作物或飼養動物的土地。"},{"en":"Farmland may include fields, hedges, ponds, barns, and farm tracks.","zh":"農田可能包括田地、樹籬、池塘、穀倉和農道。"},{"en":"If farmland is managed only for high production, wildlife may lose food and shelter.","zh":"如果農田只為高產量而管理，野生動植物可能失去食物和庇護。"},{"en":"This phrase refers to agricultural land, not wild countryside in general.","zh":"這個片語指農業土地，而不是泛指野外鄉郊。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":5},{"front":"contribute to","meaning":"導致；促成","examples":[{"en":"Hedgerow loss has contributed to habitat isolation.","zh":"樹籬流失促成了棲息地孤立。"},{"en":"To contribute to something means to help cause it or add to it.","zh":"contribute to something 指幫助造成某事或增加某事。"},{"en":"Poor sleep can contribute to mistakes in an exam.","zh":"睡眠不足可以導致考試錯誤。"},{"en":"Removing trees can contribute to flooding because less rainwater is absorbed.","zh":"移除樹木可以促成水浸，因為較少雨水被吸收。"},{"en":"This phrase often describes one cause among several.","zh":"這個片語常描述多個原因中的其中一個。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":5},{"front":"habitat isolation","meaning":"棲息地孤立","examples":[{"en":"Habitat isolation can lead to species loss.","zh":"棲息地孤立可以導致物種流失。"},{"en":"Habitat isolation happens when living spaces are separated so animals and plants cannot move easily between them.","zh":"habitat isolation 指生活空間被分隔，使動植物難以在其間移動。"},{"en":"A road through a forest can create habitat isolation for small mammals.","zh":"穿過森林的道路可以為小型哺乳動物造成棲息地孤立。"},{"en":"If habitats become isolated, small populations may become weaker over time.","zh":"如果棲息地變得孤立，小型種群可能隨時間變弱。"},{"en":"This phrase explains why connection between habitats matters.","zh":"這個片語解釋為何棲息地之間的連接很重要。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":5},{"front":"species loss","meaning":"物種流失","examples":[{"en":"The loss of hedgerows has contributed to species loss.","zh":"樹籬流失導致了物種流失。"},{"en":"Species loss means the disappearance or decline of different kinds of living things in an area.","zh":"species loss 指某地區中不同種類生物的消失或衰退。"},{"en":"A pond filled with rubbish may suffer species loss as insects and frogs leave.","zh":"充滿垃圾的池塘可能因昆蟲和青蛙離開而出現物種流失。"},{"en":"If species loss continues, an ecosystem may become less stable.","zh":"如果物種流失持續，生態系統可能變得較不穩定。"},{"en":"This phrase focuses on biodiversity declining.","zh":"這個片語聚焦於生物多樣性下降。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":5},{"front":"the tangle of","meaning":"錯綜複雜的……","examples":[{"en":"The tangle of canals and railway embankments connects urban habitats.","zh":"錯綜複雜的運河和鐵路堤岸連接了城市棲息地。"},{"en":"The tangle of something means a complicated network of many crossing or connected parts.","zh":"the tangle of something 指許多交錯或連接部分形成的複雜網絡。"},{"en":"A city may have a tangle of small streets, footpaths, and alleyways.","zh":"城市可能有錯綜複雜的小街、行人路和小巷。"},{"en":"If a tangle of green routes crosses a town, wildlife can move through it more easily.","zh":"如果錯綜複雜的綠色路線穿過城鎮，野生動植物便更容易在其中移動。"},{"en":"This phrase suggests complexity and close connection.","zh":"這個片語暗示複雜性和緊密連接。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":5},{"front":"canals","meaning":"運河","examples":[{"en":"Canals can act as ecological corridors in towns.","zh":"運河可以在城鎮中作為生態走廊。"},{"en":"Canals are artificial waterways built for transport, drainage, or water management.","zh":"canals 是為運輸、排水或水管理而建造的人工水道。"},{"en":"People may walk beside canals to see ducks, plants, and insects.","zh":"人們可能在運河旁散步，看鴨子、植物和昆蟲。"},{"en":"If canals have green banks, they can help wildlife move through built-up areas.","zh":"如果運河有綠色岸邊，它們可以幫助野生動植物穿過建成區。"},{"en":"This word refers to man-made water routes, not natural rivers.","zh":"這個詞指人工水道，而不是天然河流。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":5},{"front":"railway embankments","meaning":"鐵路堤岸","examples":[{"en":"Railway embankments can provide routes for wildlife.","zh":"鐵路堤岸可以為野生動植物提供路線。"},{"en":"Railway embankments are raised banks of earth that support railway tracks.","zh":"railway embankments 是支撐鐵路軌道的高起土堤。"},{"en":"Grass and shrubs on railway embankments can shelter insects, birds, and small mammals.","zh":"鐵路堤岸上的草和灌木可以庇護昆蟲、鳥類和小型哺乳動物。"},{"en":"If embankments are left partly wild, they can connect habitats across a city.","zh":"如果堤岸部分保持野生狀態，它們可以連接城市中的棲息地。"},{"en":"This phrase shows how transport structures can also become wildlife corridors.","zh":"這個片語顯示交通結構也可以成為野生動植物走廊。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":6},{"front":"road verges","meaning":"路邊草帶","examples":[{"en":"Road verges can form part of an urban wildlife network.","zh":"路邊草帶可以構成城市野生動植物網絡的一部分。"},{"en":"Road verges are strips of grass or plants beside roads.","zh":"road verges 是道路旁的草地或植物帶。"},{"en":"Wildflowers on road verges can feed bees and butterflies.","zh":"路邊草帶上的野花可以為蜜蜂和蝴蝶提供食物。"},{"en":"If road verges are cut too often, insects may lose flowers and shelter.","zh":"如果路邊草帶被過於頻繁地修剪，昆蟲可能失去花朵和庇護。"},{"en":"This phrase refers to small roadside habitats that many people overlook.","zh":"這個片語指許多人忽略的路邊小棲息地。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":6},{"front":"boundary hedges","meaning":"邊界樹籬","examples":[{"en":"Boundary hedges help connect habitats in towns.","zh":"邊界樹籬幫助連接城鎮中的棲息地。"},{"en":"Boundary hedges are rows of shrubs or small trees marking the edge of gardens, fields, or properties.","zh":"boundary hedges 是標示花園、田地或物業邊緣的一排灌木或小樹。"},{"en":"A garden boundary hedge can give birds a safe place to hide.","zh":"花園邊界樹籬可以給鳥類安全藏身處。"},{"en":"If boundary hedges link gardens together, small animals can move between them.","zh":"如果邊界樹籬把花園連接起來，小動物便能在其間移動。"},{"en":"This phrase combines the idea of property boundary and wildlife shelter.","zh":"這個片語結合物業邊界和野生動植物庇護的概念。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":6},{"front":"lace the landscape together","meaning":"將景觀連繫起來","examples":[{"en":"Canals and hedges lace the urban landscape together.","zh":"運河和樹籬將城市景觀連繫起來。"},{"en":"To lace the landscape together means to connect different parts of an area like threads in fabric.","zh":"lace the landscape together 指像布料中的線一樣，把一個地區的不同部分連接起來。"},{"en":"Footpaths can lace a school campus together by linking classrooms, gardens, and sports areas.","zh":"行人路可以把課室、花園和運動區連接起來，將校園景觀連繫起來。"},{"en":"When green routes lace a city together, wildlife can travel safely between habitats.","zh":"當綠色路線把城市連繫起來，野生動植物便能在棲息地之間安全移動。"},{"en":"This phrase gives a visual image of connection.","zh":"這個片語給出連接的視覺畫面。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":6},{"front":"first-class ecological corridors","meaning":"一流的生態走廊","examples":[{"en":"Urban features can provide first-class ecological corridors.","zh":"城市特徵可以提供一流的生態走廊。"},{"en":"First-class ecological corridors are excellent natural routes that allow wildlife to move between habitats.","zh":"first-class ecological corridors 是讓野生動植物在棲息地之間移動的優秀自然路線。"},{"en":"A riverbank with trees and flowers can be a first-class ecological corridor through a town.","zh":"有樹木和花朵的河岸可以成為穿過城鎮的一流生態走廊。"},{"en":"If corridors are high quality, animals can feed, shelter, and travel more safely.","zh":"如果走廊質素高，動物可以更安全地覓食、棲身和移動。"},{"en":"This phrase suggests that urban routes can be highly valuable for nature.","zh":"這個片語暗示城市路線對自然可以極具價值。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":6},{"front":"hedgehogs","meaning":"刺蝟","examples":[{"en":"Hedgehogs can use urban ecological corridors.","zh":"刺蝟可以使用城市生態走廊。"},{"en":"Hedgehogs are small mammals with spines on their backs.","zh":"hedgehogs 是背上有刺的小型哺乳動物。"},{"en":"A hedgehog may visit a garden at night to search for insects.","zh":"刺蝟可能在夜晚到花園尋找昆蟲。"},{"en":"If fences have small gaps, hedgehogs can move between gardens more easily.","zh":"如果圍欄有小縫隙，刺蝟便更容易在花園之間移動。"},{"en":"This word refers to a garden mammal that benefits from connected green spaces.","zh":"這個詞指一種受益於連接綠地的花園哺乳動物。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":6},{"front":"kingfishers","meaning":"翠鳥","examples":[{"en":"Kingfishers may benefit from connected urban waterways.","zh":"翠鳥可能受益於互相連接的城市水道。"},{"en":"Kingfishers are brightly coloured birds that often hunt fish near rivers, canals, and ponds.","zh":"kingfishers 是色彩鮮明的鳥類，常在河流、運河和池塘附近捕魚。"},{"en":"A walker may see a kingfisher flash blue over a quiet stream.","zh":"散步者可能看見翠鳥在安靜小溪上方閃過藍色身影。"},{"en":"If urban waterways are clean and connected, kingfishers have better hunting routes.","zh":"如果城市水道潔淨並互相連接，翠鳥會有更好的捕食路線。"},{"en":"This word is often linked with healthy water habitats.","zh":"這個詞常與健康水域棲息地相關。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":6},{"front":"urban parks","meaning":"城市公園","examples":[{"en":"Urban parks are valuable for some species.","zh":"城市公園對某些物種有價值。"},{"en":"Urban parks are public green spaces inside towns or cities.","zh":"urban parks 是城鎮或城市中的公共綠色空間。"},{"en":"Families use urban parks for exercise, rest, picnics, and play.","zh":"家庭使用城市公園運動、休息、野餐和遊玩。"},{"en":"If urban parks contain trees, ponds, and unmown grass, they can support wildlife.","zh":"如果城市公園有樹木、池塘和未修剪草地，它們可以支持野生動植物。"},{"en":"This phrase refers to nature spaces within the city.","zh":"這個片語指城市中的自然空間。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":6},{"front":"formal recreation grounds","meaning":"正式康樂場地","examples":[{"en":"Formal recreation grounds can support certain species.","zh":"正式康樂場地可以支持某些物種。"},{"en":"Formal recreation grounds are organised public spaces used for sport, play, and leisure.","zh":"formal recreation grounds 是用於運動、遊玩和休閒的有規劃公共空間。"},{"en":"A football field and playground can be part of a formal recreation ground.","zh":"足球場和遊樂場可以是正式康樂場地的一部分。"},{"en":"If grass edges are left wild, formal recreation grounds can also help insects and birds.","zh":"如果草地邊緣保留野生狀態，正式康樂場地也可以幫助昆蟲和鳥類。"},{"en":"This phrase refers to planned leisure spaces, not wild countryside.","zh":"這個片語指有規劃的休閒空間，而不是野外鄉郊。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":6},{"front":"be valuable for","meaning":"對……有價值","examples":[{"en":"Urban parks are valuable for some species.","zh":"城市公園對某些物種有價值。"},{"en":"To be valuable for something means to be useful or important for it.","zh":"be valuable for something 指對某事有用或重要。"},{"en":"Quiet reading time is valuable for students who need to build vocabulary.","zh":"安靜閱讀時間對需要建立詞彙量的學生有價值。"},{"en":"A pond is valuable for frogs because it gives them a place to breed.","zh":"池塘對青蛙有價值，因為它給牠們繁殖的地方。"},{"en":"This phrase explains why something matters to a person, animal, or process.","zh":"這個片語解釋某物為何對人、動物或過程重要。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":6},{"front":"increasingly managed with wildlife in mind","meaning":"越來越以野生動植物為考慮來管理","examples":[{"en":"Many urban parks are increasingly managed with wildlife in mind.","zh":"許多城市公園越來越以野生動植物為考慮來管理。"},{"en":"Increasingly managed with wildlife in mind means more and more managed in ways that consider wild plants and animals.","zh":"increasingly managed with wildlife in mind 指越來越以考慮野生植物和動物的方式管理。"},{"en":"A school garden may be managed with wildlife in mind by leaving flowers for bees.","zh":"學校花園可以透過留下花給蜜蜂而以野生動植物為考慮來管理。"},{"en":"If parks are managed with wildlife in mind, mowing, planting, and pond care may change.","zh":"如果公園以野生動植物為考慮來管理，割草、種植和池塘護理方式可能改變。"},{"en":"This phrase shows a shift from human-only use to shared urban nature.","zh":"這個片語顯示由只為人類使用轉向共享城市自然。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":6},{"front":"with wildlife in mind","meaning":"考慮到野生動植物","examples":[{"en":"Some parks are managed with wildlife in mind.","zh":"一些公園在管理時考慮到野生動植物。"},{"en":"With wildlife in mind means while considering the needs of wild plants and animals.","zh":"with wildlife in mind 指同時考慮野生植物和動物的需要。"},{"en":"A gardener may plant native flowers with wildlife in mind.","zh":"園丁可能考慮到野生動植物而種植本地花卉。"},{"en":"If a council designs a park with wildlife in mind, it may include ponds, hedges, and long grass.","zh":"如果議會設計公園時考慮到野生動植物，可能會包括池塘、樹籬和長草。"},{"en":"This phrase shows that nature is part of the planning.","zh":"這個片語顯示自然是規劃的一部分。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":7},{"front":"significance is eclipsed by","meaning":"重要性被……蓋過","examples":[{"en":"Their significance is eclipsed by the huge legacy of post-industrial land.","zh":"它們的重要性被後工業土地的大量遺產蓋過。"},{"en":"If one thing’s significance is eclipsed by another, it becomes less noticeable because the other is more important.","zh":"如果某事的 significance is eclipsed by 另一事物，意思是它因另一事物更重要而變得較不顯眼。"},{"en":"A student’s small spelling mistakes may be eclipsed by the strength of a powerful argument.","zh":"學生的小拼寫錯誤可能被有力論點的強度蓋過。"},{"en":"Urban parks matter, but their role may be eclipsed by the wildlife value of brownfield land.","zh":"城市公園重要，但其作用可能被棕地的野生動植物價值蓋過。"},{"en":"This phrase compares importance and shows one thing overshadowing another.","zh":"這個片語比較重要性，並顯示一事物遮蓋另一事物。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":7},{"front":"huge legacy of","meaning":"……的大量遺產","examples":[{"en":"Cities contain a huge legacy of post-industrial land.","zh":"城市包含後工業土地的大量遺產。"},{"en":"A huge legacy of something means a large amount left behind from the past.","zh":"huge legacy of something 指從過去留下來的大量某物。"},{"en":"A city may have a huge legacy of old factories, canals, and railway lines.","zh":"城市可能有大量舊工廠、運河和鐵路線的遺產。"},{"en":"If old industrial land is left unused, it can become a legacy that wildlife later colonises.","zh":"如果舊工業土地被閒置，它可以成為之後被野生動植物佔據的遺產。"},{"en":"This phrase links the present with material remains from earlier history.","zh":"這個片語把現在與早期歷史留下的實體遺跡連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":7},{"front":"post-industrial land","meaning":"後工業土地","examples":[{"en":"Post-industrial land can become valuable wildlife habitat.","zh":"後工業土地可以變成有價值的野生動植物棲息地。"},{"en":"Post-industrial land is land left behind after factories, railways, mines, or other industries close.","zh":"post-industrial land 是工廠、鐵路、礦場或其他工業關閉後留下的土地。"},{"en":"An old factory site with weeds, ponds, and rubble can be post-industrial land.","zh":"有雜草、池塘和碎石的舊工廠地可以是後工業土地。"},{"en":"If post-industrial land is not immediately redeveloped, plants and animals may colonise it.","zh":"如果後工業土地沒有立即重新發展，植物和動物可能佔據它。"},{"en":"This phrase shows that abandoned industrial spaces can have ecological value.","zh":"這個片語顯示廢棄工業空間可以有生態價值。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":7},{"front":"demolished factories","meaning":"已拆卸的工廠","examples":[{"en":"Demolished factories can become brownfield wildlife sites.","zh":"已拆卸的工廠可以變成棕地野生動植物地點。"},{"en":"Demolished factories are factory buildings that have been knocked down or removed.","zh":"demolished factories 是已被拆除或移走的工廠建築。"},{"en":"A demolished factory may leave behind flat land, rubble, and open space.","zh":"已拆卸的工廠可能留下平地、碎石和開放空間。"},{"en":"If nature is allowed to return, demolished factories can become habitats for insects and birds.","zh":"如果容許自然回來，已拆卸的工廠可以成為昆蟲和鳥類的棲息地。"},{"en":"This phrase connects industrial decline with new ecological opportunity.","zh":"這個片語把工業衰退與新的生態機會連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":7},{"front":"waste tips","meaning":"垃圾堆填場；廢物堆","examples":[{"en":"Waste tips are part of the legacy of post-industrial land.","zh":"廢物堆是後工業土地遺產的一部分。"},{"en":"Waste tips are places where rubbish, spoil, or unwanted industrial material has been dumped.","zh":"waste tips 是垃圾、廢土或不需要的工業材料被傾倒的地方。"},{"en":"An old waste tip may look unattractive but later grow grasses and wildflowers.","zh":"舊廢物堆可能外觀不吸引，但之後會長出草和野花。"},{"en":"If waste tips are safely restored, they can sometimes support wildlife.","zh":"如果廢物堆被安全修復，有時可以支持野生動植物。"},{"en":"This phrase refers to dumped waste areas, not ordinary rubbish bins.","zh":"這個片語指傾倒廢物的地方，而不是普通垃圾桶。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":7},{"front":"quarries","meaning":"採石場","examples":[{"en":"Old quarries can become habitats for wildlife.","zh":"舊採石場可以成為野生動植物棲息地。"},{"en":"Quarries are places where stone, sand, or minerals have been dug out of the ground.","zh":"quarries 是從地面挖出石材、沙或礦物的地方。"},{"en":"A disused quarry may fill with water and become a pond or lake.","zh":"廢棄採石場可能積水，變成池塘或湖泊。"},{"en":"If cliffs and pools remain in old quarries, birds and insects may use them.","zh":"如果舊採石場保留峭壁和水池，鳥類和昆蟲可能使用它們。"},{"en":"This word refers to extraction sites that can later become nature sites.","zh":"這個詞指採掘地點，而它們之後可以變成自然地點。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":7},{"front":"redundant railway yards","meaning":"廢棄鐵路貨場","examples":[{"en":"Redundant railway yards can be colonised by plants and animals.","zh":"廢棄鐵路貨場可以被植物和動物佔據。"},{"en":"Redundant railway yards are old railway working areas that are no longer needed.","zh":"redundant railway yards 是不再需要的舊鐵路工作區。"},{"en":"A redundant railway yard may contain tracks, gravel, weeds, and unused buildings.","zh":"廢棄鐵路貨場可能包含軌道、碎石、雜草和閒置建築。"},{"en":"If railway yards are abandoned, hardy plants may grow first and attract insects.","zh":"如果鐵路貨場被棄置，耐生植物可能先長出，並吸引昆蟲。"},{"en":"This phrase describes transport land that has lost its original function.","zh":"這個片語描述失去原本功能的交通用地。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":7},{"front":"so-called brownfield sites","meaning":"所謂棕地","examples":[{"en":"So-called brownfield sites can support rich wildlife.","zh":"所謂棕地可以支持豐富野生動植物。"},{"en":"So-called brownfield sites are previously developed or industrial lands that are now unused or underused.","zh":"so-called brownfield sites 是以前已開發或工業使用、現在閒置或未充分使用的土地。"},{"en":"An old factory plot with weeds and rubble may be a brownfield site.","zh":"有雜草和碎石的舊工廠地皮可能是棕地。"},{"en":"If brownfield sites are left undisturbed, wildlife may colonise them quickly.","zh":"如果棕地不受打擾，野生動植物可能很快佔據它們。"},{"en":"This phrase suggests land that looks neglected but may have ecological value.","zh":"這個片語暗示土地看似荒廢，但可能有生態價值。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":7},{"front":"spectacularly colonised with","meaning":"被……大量而壯觀地佔據","examples":[{"en":"Some brownfield land has been spectacularly colonised with birch and willow woodland.","zh":"一些棕地被樺樹和柳樹林地大量而壯觀地佔據。"},{"en":"Spectacularly colonised with something means covered or occupied by it in a striking and impressive way.","zh":"spectacularly colonised with something 指以引人注目而令人印象深刻的方式被某物覆蓋或佔據。"},{"en":"An empty lot may be colonised with wildflowers after several wet seasons.","zh":"經過幾個潮濕季節，空地可能被野花佔據。"},{"en":"If old industrial land is colonised with trees, it can change from wasteland into habitat.","zh":"如果舊工業土地被樹木佔據，它可以由荒地變成棲息地。"},{"en":"This phrase suggests natural growth that is dramatic and noticeable.","zh":"這個片語暗示自然生長既劇烈又明顯。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":7},{"front":"birch and willow woodland","meaning":"樺樹和柳樹林地","examples":[{"en":"Birch and willow woodland has grown on old industrial land.","zh":"樺樹和柳樹林地已在舊工業土地上生長。"},{"en":"Birch and willow woodland is an area of trees mainly made up of birch and willow.","zh":"birch and willow woodland 是主要由樺樹和柳樹組成的林地。"},{"en":"A damp abandoned site may develop birch and willow woodland over time.","zh":"潮濕的廢棄地點可能隨時間發展出樺樹和柳樹林地。"},{"en":"If birch and willow woodland grows, birds and insects may gain shelter and food.","zh":"如果樺樹和柳樹林地生長，鳥類和昆蟲可能獲得庇護和食物。"},{"en":"This phrase describes a young woodland type often found on disturbed land.","zh":"這個片語描述常見於受擾土地上的年輕林地類型。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":7},{"front":"herb-rich grassland","meaning":"草本植物豐富的草地","examples":[{"en":"Herb-rich grassland can develop on brownfield sites.","zh":"草本植物豐富的草地可以在棕地上發展。"},{"en":"Herb-rich grassland is grassland containing many flowering herbs and small plants.","zh":"herb-rich grassland 是包含許多開花草本植物和小植物的草地。"},{"en":"Bees and butterflies may visit herb-rich grassland because it provides nectar.","zh":"蜜蜂和蝴蝶可能到訪草本植物豐富的草地，因為它提供花蜜。"},{"en":"If grassland is not cut too often, more herbs and flowers can grow.","zh":"如果草地不是過於頻繁地修剪，更多草本植物和花朵可以生長。"},{"en":"This phrase describes grassland with plant diversity, not plain lawn.","zh":"這個片語描述植物多樣的草地，而不是普通草坪。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":8},{"front":"shallow wetlands","meaning":"淺水濕地","examples":[{"en":"Shallow wetlands have developed on some post-industrial land.","zh":"淺水濕地已在一些後工業土地上發展。"},{"en":"Shallow wetlands are wet areas with low water levels, such as marshy pools and reed-filled edges.","zh":"shallow wetlands 是水位較低的濕地，例如沼澤水池和長滿蘆葦的邊緣。"},{"en":"Frogs, insects, and birds may use shallow wetlands for feeding or breeding.","zh":"青蛙、昆蟲和鳥類可能使用淺水濕地覓食或繁殖。"},{"en":"If rain collects on uneven ground, shallow wetlands can form naturally.","zh":"如果雨水聚集在不平地面，淺水濕地可以自然形成。"},{"en":"This phrase describes water habitat that is not deep.","zh":"這個片語描述不深的水域棲息地。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":8},{"front":"as a consequence","meaning":"因此","examples":[{"en":"As a consequence, there are many songbirds and predators in old industrial areas.","zh":"因此，舊工業區有許多鳴禽和掠食動物。"},{"en":"As a consequence means as a result of what happened before.","zh":"as a consequence 指作為之前事情的結果。"},{"en":"The bus was cancelled; as a consequence, many students arrived late.","zh":"巴士取消了；因此，許多學生遲到。"},{"en":"If trees and wetlands grow on brownfield land, more birds may appear as a consequence.","zh":"如果樹木和濕地在棕地上生長，更多鳥類可能因此出現。"},{"en":"This phrase connects a cause with its result.","zh":"這個片語把原因與結果連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":8},{"front":"songbirds","meaning":"鳴禽","examples":[{"en":"Songbirds are found in abundance over once-industrial landscapes.","zh":"鳴禽在曾經是工業區的景觀中大量出現。"},{"en":"Songbirds are birds known for producing musical calls or songs.","zh":"songbirds 是以發出悅耳叫聲或歌聲聞名的鳥類。"},{"en":"People may hear songbirds in gardens early in the morning.","zh":"人們可能在清晨於花園中聽到鳴禽。"},{"en":"If shrubs and trees grow, songbirds may find nesting places and food.","zh":"如果灌木和樹木生長，鳴禽可能找到築巢地方和食物。"},{"en":"This word highlights birds valued for their singing.","zh":"這個詞突出因歌聲而受重視的鳥類。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":8},{"front":"predators","meaning":"掠食動物","examples":[{"en":"Predators are also found in post-industrial landscapes.","zh":"掠食動物也出現在後工業景觀中。"},{"en":"Predators are animals that hunt and eat other animals.","zh":"predators 是捕獵並吃其他動物的動物。"},{"en":"A fox is a predator that may hunt small mammals or birds.","zh":"狐狸是可能捕獵小型哺乳動物或鳥類的掠食動物。"},{"en":"If prey animals increase, predators may also become more common.","zh":"如果獵物動物增加，掠食動物也可能變得更常見。"},{"en":"This word describes an animal’s role in the food chain.","zh":"這個詞描述動物在食物鏈中的角色。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":8},{"front":"in abundance","meaning":"大量地","examples":[{"en":"Songbirds and predators occur in abundance in these landscapes.","zh":"鳴禽和掠食動物在這些景觀中大量出現。"},{"en":"In abundance means in large numbers or plentiful amounts.","zh":"in abundance 指以大量或充足數量出現。"},{"en":"Wildflowers may grow in abundance after spring rain.","zh":"春雨過後，野花可能大量生長。"},{"en":"If insects occur in abundance, birds may have more food.","zh":"如果昆蟲大量出現，鳥類可能有更多食物。"},{"en":"This phrase suggests that something is common and plentiful.","zh":"這個片語暗示某物常見而充足。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":8},{"front":"once-industrial landscapes","meaning":"曾經是工業區的景觀","examples":[{"en":"Once-industrial landscapes can now support wildlife.","zh":"曾經是工業區的景觀現在可以支持野生動植物。"},{"en":"Once-industrial landscapes are areas that used to be industrial but are no longer mainly used for industry.","zh":"once-industrial landscapes 是以前用作工業、現在不再主要用於工業的地區。"},{"en":"An old railway yard with trees and ponds is a once-industrial landscape.","zh":"有樹木和池塘的舊鐵路貨場是一個曾經是工業區的景觀。"},{"en":"If industry leaves and nature returns, once-industrial landscapes can become rich habitats.","zh":"如果工業離開而自然回歸，曾經是工業區的景觀可以變成豐富棲息地。"},{"en":"This phrase contrasts past industrial use with present ecological value.","zh":"這個片語對比過去工業用途與現在生態價值。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":8},{"front":"domestic gardens","meaning":"家庭花園","examples":[{"en":"There are fifteen million domestic gardens in the UK.","zh":"英國有一千五百萬個家庭花園。"},{"en":"Domestic gardens are private gardens belonging to homes.","zh":"domestic gardens 是屬於住宅的私人花園。"},{"en":"A domestic garden may include a lawn, flower beds, shrubs, and a small pond.","zh":"家庭花園可能包括草坪、花圃、灌木和小池塘。"},{"en":"If many domestic gardens are wildlife-friendly, they can form a large habitat network.","zh":"如果許多家庭花園對野生動植物友善，它們可以形成大型棲息地網絡。"},{"en":"This phrase refers to home gardens, not public parks.","zh":"這個片語指家居花園，而不是公共公園。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":8},{"front":"managed as","meaning":"被管理成","examples":[{"en":"Some gardens are still managed as lifeless chemical war zones.","zh":"一些花園仍被管理成毫無生氣的化學戰場。"},{"en":"Managed as something means treated or organised in that particular way.","zh":"managed as something 指被以某種特定方式處理或組織。"},{"en":"A school garden can be managed as an outdoor classroom for science lessons.","zh":"學校花園可以被管理成科學課的戶外課室。"},{"en":"If a garden is managed as a tidy display only, it may offer little shelter for wildlife.","zh":"如果花園只被管理成整齊展示，它可能為野生動植物提供很少庇護。"},{"en":"This phrase describes the purpose or style of management.","zh":"這個片語描述管理目的或方式。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":8},{"front":"lifeless chemical war zones","meaning":"毫無生氣的化學戰場","examples":[{"en":"Some gardens are described as lifeless chemical war zones.","zh":"一些花園被描述為毫無生氣的化學戰場。"},{"en":"Lifeless chemical war zones are areas made poor for wildlife by heavy use of chemicals.","zh":"lifeless chemical war zones 是因大量使用化學品而不利於野生動植物的地區。"},{"en":"A garden sprayed too often may become a lifeless chemical war zone with few insects or birds.","zh":"過於頻繁噴藥的花園可能變成幾乎沒有昆蟲或鳥類的化學戰場。"},{"en":"If chemicals remove insects and weeds, the food chain in a garden may collapse.","zh":"如果化學品清除昆蟲和雜草，花園中的食物鏈可能崩潰。"},{"en":"This phrase is deliberately strong and critical.","zh":"這個片語語氣刻意強烈並帶批評意味。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":8},{"front":"benefit the local wildlife","meaning":"令本地野生動植物受益","examples":[{"en":"Most gardens benefit the local wildlife.","zh":"大多數花園令本地野生動植物受益。"},{"en":"To benefit the local wildlife means to help wild plants and animals living nearby.","zh":"benefit the local wildlife 指幫助附近生活的野生植物和動物。"},{"en":"A garden pond can benefit local wildlife by giving frogs and insects water.","zh":"花園池塘可以透過給青蛙和昆蟲水源而令本地野生動植物受益。"},{"en":"If gardeners avoid chemicals, birds and bees may benefit from safer food sources.","zh":"如果園丁避免使用化學品，鳥類和蜜蜂可能因更安全食物來源而受益。"},{"en":"This phrase focuses on positive effects for nearby nature.","zh":"這個片語聚焦於對附近自然的正面影響。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":8},{"front":"benign neglect","meaning":"善意的疏於打理","examples":[{"en":"Some gardens help wildlife through benign neglect.","zh":"一些花園透過善意的疏於打理幫助野生動植物。"},{"en":"Benign neglect means leaving something slightly untidy in a harmless or helpful way.","zh":"benign neglect 指以無害甚至有益的方式讓某物稍微不那麼整齊。"},{"en":"A gardener may practise benign neglect by leaving leaves under shrubs for insects.","zh":"園丁可能透過把落葉留在灌木下給昆蟲而實踐善意的疏於打理。"},{"en":"If every corner is cleaned too perfectly, wildlife may lose hiding places.","zh":"如果每個角落都清理得太完美，野生動植物可能失去藏身處。"},{"en":"This phrase suggests that doing less can sometimes help nature.","zh":"這個片語暗示有時少做一點反而能幫助自然。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":9},{"front":"positive encouragement","meaning":"積極鼓勵","examples":[{"en":"Some gardeners help wildlife through positive encouragement.","zh":"一些園丁透過積極鼓勵幫助野生動植物。"},{"en":"Positive encouragement means active support that helps something grow or succeed.","zh":"positive encouragement 指幫助某事成長或成功的主動支持。"},{"en":"A teacher gives positive encouragement when she praises effort and suggests the next step.","zh":"當老師讚賞努力並建議下一步時，她就在給予積極鼓勵。"},{"en":"Gardeners provide positive encouragement by planting flowers, adding ponds, and putting up nest boxes.","zh":"園丁透過種花、加池塘和設鳥巢箱提供積極鼓勵。"},{"en":"This phrase contrasts active help with simply leaving things alone.","zh":"這個片語把主動幫助與單純放任作對比。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":9},{"front":"do best","meaning":"表現最好；最受益","examples":[{"en":"Woodland species tend to do best in gardens.","zh":"林地物種往往在花園中表現最好。"},{"en":"To do best means to perform, grow, or survive most successfully.","zh":"do best 指表現、生長或生存得最成功。"},{"en":"Some students do best when they revise in short regular sessions.","zh":"有些學生在短而定期的溫習中表現最好。"},{"en":"If a garden resembles woodland edges, woodland species may do best there.","zh":"如果花園像林地邊緣，林地物種可能在那裡最受益。"},{"en":"This phrase compares which group benefits most.","zh":"這個片語比較哪一組受益最多。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":9},{"front":"tend to be","meaning":"往往是","examples":[{"en":"The species that do best tend to be woodland species.","zh":"表現最好的物種往往是林地物種。"},{"en":"Tend to be means are usually or often.","zh":"tend to be 指通常是或往往是。"},{"en":"Students who read often tend to be more comfortable with long passages.","zh":"經常閱讀的學生往往較能應付長文章。"},{"en":"Gardens with shrubs and trees tend to be useful for woodland species.","zh":"有灌木和樹木的花園往往對林地物種有用。"},{"en":"This phrase describes a general pattern, not an absolute rule.","zh":"這個片語描述一般模式，而不是絕對規則。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":9},{"front":"woodland species","meaning":"林地物種","examples":[{"en":"Woodland species often thrive in gardens.","zh":"林地物種常在花園中繁盛。"},{"en":"Woodland species are plants or animals normally associated with woods or forests.","zh":"woodland species 是通常與樹林或森林相關的植物或動物。"},{"en":"Robins, blue tits, and some insects can behave like woodland species in leafy gardens.","zh":"知更鳥、藍山雀和一些昆蟲可以在多葉花園中像林地物種一樣生活。"},{"en":"If gardens have trees, shrubs, and shaded edges, woodland species may find them suitable.","zh":"如果花園有樹木、灌木和陰影邊緣，林地物種可能覺得合適。"},{"en":"This phrase links species to a wooded habitat type.","zh":"這個片語把物種與林地棲息地類型連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":9},{"front":"garden lawns","meaning":"花園草坪","examples":[{"en":"Garden lawns can provide habitat for some wildlife.","zh":"花園草坪可以為一些野生動植物提供棲息地。"},{"en":"Garden lawns are areas of short grass in private gardens.","zh":"garden lawns 是私人花園中的短草區。"},{"en":"Children may play on garden lawns while birds search the grass for worms.","zh":"孩子可能在花園草坪上玩耍，而鳥類在草中尋找蚯蚓。"},{"en":"If a lawn is left partly unmown, flowers and insects may increase.","zh":"如果草坪部分不修剪，花朵和昆蟲可能增加。"},{"en":"This phrase refers to managed grass areas around homes.","zh":"這個片語指住宅周圍經管理的草地。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":9},{"front":"flower borders","meaning":"花圃邊界","examples":[{"en":"Flower borders can provide food and shelter for wildlife.","zh":"花圃邊界可以為野生動植物提供食物和庇護。"},{"en":"Flower borders are planted strips along the edges of gardens or paths.","zh":"flower borders 是沿花園或小徑邊緣種植的植物帶。"},{"en":"Bees may visit flower borders for nectar during spring and summer.","zh":"蜜蜂可能在春夏到訪花圃邊界採集花蜜。"},{"en":"If flower borders contain many plant types, they can support more insects.","zh":"如果花圃邊界包含多種植物，它們可以支持更多昆蟲。"},{"en":"This phrase refers to decorative planting that can also help wildlife.","zh":"這個片語指裝飾性種植，同時也可幫助野生動植物。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":9},{"front":"climber-covered fences","meaning":"被攀緣植物覆蓋的圍欄","examples":[{"en":"Climber-covered fences can resemble woodland edges.","zh":"被攀緣植物覆蓋的圍欄可以像林地邊緣。"},{"en":"Climber-covered fences are fences covered by climbing plants such as ivy or honeysuckle.","zh":"climber-covered fences 是被常春藤或忍冬等攀緣植物覆蓋的圍欄。"},{"en":"A climber-covered fence can give birds shelter and insects flowers.","zh":"被攀緣植物覆蓋的圍欄可以為鳥類提供庇護，並為昆蟲提供花朵。"},{"en":"If fences are bare, they offer little habitat, but climbers can change that.","zh":"如果圍欄光禿禿，棲息地價值很低，但攀緣植物可以改變這點。"},{"en":"This phrase shows how a garden structure can become more natural.","zh":"這個片語顯示花園結構如何變得更自然。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":9},{"front":"shrubberies","meaning":"灌木叢","examples":[{"en":"Shrubberies can provide shelter for garden wildlife.","zh":"灌木叢可以為花園野生動植物提供庇護。"},{"en":"Shrubberies are areas planted with shrubs or bushes.","zh":"shrubberies 是種有灌木或矮樹叢的區域。"},{"en":"Small birds may hide in shrubberies when cats or people come too close.","zh":"當貓或人太靠近時，小鳥可能躲進灌木叢。"},{"en":"If a garden has dense shrubberies, wildlife may find nesting and resting places.","zh":"如果花園有茂密灌木叢，野生動植物可能找到築巢和休息地。"},{"en":"This word refers to planted bushy areas, not large forests.","zh":"這個詞指種植的灌木區，而不是大型森林。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":9},{"front":"fruit trees","meaning":"果樹","examples":[{"en":"Fruit trees can benefit birds and insects.","zh":"果樹可以令鳥類和昆蟲受益。"},{"en":"Fruit trees are trees that produce fruit, such as apples, pears, or plums.","zh":"fruit trees 是結出水果的樹木，例如蘋果樹、梨樹或李子樹。"},{"en":"Bees may visit fruit trees when they blossom in spring.","zh":"果樹在春天開花時，蜜蜂可能到訪。"},{"en":"If fruit is left on a tree, birds and insects may feed on it.","zh":"如果水果留在樹上，鳥類和昆蟲可能以它為食。"},{"en":"This phrase connects garden planting with food for wildlife.","zh":"這個片語把花園種植與野生動植物食物連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":9},{"front":"a plausible alternative","meaning":"合理的替代選擇","examples":[{"en":"Gardens can be a plausible alternative to woodland.","zh":"花園可以成為林地的合理替代選擇。"},{"en":"A plausible alternative is a reasonable substitute that could work.","zh":"a plausible alternative 是合理並可能可行的替代方案。"},{"en":"Online lessons can be a plausible alternative when bad weather closes schools.","zh":"當惡劣天氣令學校停課，網上課堂可以是合理替代選擇。"},{"en":"If gardens contain trees and shrubs, they may be a plausible alternative for woodland species.","zh":"如果花園包含樹木和灌木，它們可能成為林地物種的合理替代選擇。"},{"en":"This phrase suggests something is believable and practical, not perfect.","zh":"這個片語暗示某物可信且實際，但不一定完美。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":9},{"front":"in some respects","meaning":"在某些方面","examples":[{"en":"In some respects, gardens are better than real woodland.","zh":"在某些方面，花園比真正林地更好。"},{"en":"In some respects means in certain ways, but not in every way.","zh":"in some respects 指在某些方面，但不是所有方面。"},{"en":"Online dictionaries are better than paper dictionaries in some respects, such as speed.","zh":"網上字典在某些方面比紙本字典更好，例如速度。"},{"en":"Gardens may be better for some insects in some respects because flowers are planted for longer seasons.","zh":"在某些方面，花園可能對一些昆蟲更好，因為花卉種植可延長季節。"},{"en":"This phrase limits a comparison carefully.","zh":"這個片語謹慎限制比較範圍。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":10},{"front":"rather better than the real thing","meaning":"比真正的東西更好","examples":[{"en":"Gardens may be rather better than the real thing for some wildlife.","zh":"對一些野生動植物來說，花園可能比真正林地更好。"},{"en":"Rather better than the real thing means somewhat better than the original or natural version.","zh":"rather better than the real thing 指在某程度上比原本或自然版本更好。"},{"en":"A practice exam with answers may be rather better than the real thing for learning from mistakes.","zh":"附答案的模擬試卷在從錯誤中學習方面可能比真正考試更好。"},{"en":"If gardens offer food for longer than woodland, they may be better than the real thing for certain insects.","zh":"如果花園提供食物的時間比林地更長，對某些昆蟲來說可能比真正林地更好。"},{"en":"This phrase is surprising because the copy or alternative may work better.","zh":"這個片語帶有驚訝感，因為替代品可能效果更好。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":10},{"front":"exotic flowers","meaning":"外來花卉","examples":[{"en":"Exotic flowers can extend the nectar season.","zh":"外來花卉可以延長花蜜季節。"},{"en":"Exotic flowers are flowers from other countries or unfamiliar climates.","zh":"exotic flowers 是來自其他國家或陌生氣候的花卉。"},{"en":"A gardener may plant exotic flowers because they look colourful and unusual.","zh":"園丁可能因外來花卉色彩鮮明且不尋常而種植它們。"},{"en":"If exotic flowers bloom when native flowers do not, insects may get extra food.","zh":"如果外來花卉在本地花不開花時開花，昆蟲可能得到額外食物。"},{"en":"This phrase refers to non-native or unusual flowering plants.","zh":"這個片語指非本地或不常見的開花植物。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":10},{"front":"extend the nectar season","meaning":"延長花蜜季節","examples":[{"en":"Exotic flowers can extend the nectar season for insects.","zh":"外來花卉可以為昆蟲延長花蜜季節。"},{"en":"To extend the nectar season means to make nectar available for a longer part of the year.","zh":"extend the nectar season 指讓花蜜在一年中更長時間可供取得。"},{"en":"A garden with early and late flowers can extend the nectar season for bees.","zh":"有早開和晚開花卉的花園可以為蜜蜂延長花蜜季節。"},{"en":"If insects find nectar for longer, they may survive better through difficult months.","zh":"如果昆蟲更長時間找到花蜜，牠們可能更好地度過困難月份。"},{"en":"This phrase connects flower timing with food supply.","zh":"這個片語把開花時間與食物供應連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":10},{"front":"birdfeeders","meaning":"餵鳥器","examples":[{"en":"Birdfeeders can supplement the natural seed supply.","zh":"餵鳥器可以補充天然種子供應。"},{"en":"Birdfeeders are containers or devices that provide food for birds.","zh":"birdfeeders 是為鳥類提供食物的容器或裝置。"},{"en":"A family may hang birdfeeders near a window to watch birds safely.","zh":"家庭可能把餵鳥器掛在窗邊，以安全觀察鳥類。"},{"en":"If winter food is scarce, birdfeeders can help birds survive.","zh":"如果冬季食物稀少，餵鳥器可以幫助鳥類生存。"},{"en":"This word refers to artificial feeding stations for birds.","zh":"這個詞指鳥類的人工餵食裝置。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":10},{"front":"supplement the natural seed supply","meaning":"補充天然種子供應","examples":[{"en":"Birdfeeders supplement the natural seed supply for birds.","zh":"餵鳥器為鳥類補充天然種子供應。"},{"en":"To supplement the natural seed supply means to add extra food when natural seeds are not enough.","zh":"supplement the natural seed supply 指在天然種子不足時加入額外食物。"},{"en":"In winter, gardeners may supplement the natural seed supply with sunflower seeds.","zh":"冬季時，園丁可能用葵花籽補充天然種子供應。"},{"en":"If natural food is limited, extra feeding can support garden birds.","zh":"如果天然食物有限，額外餵飼可以支持花園鳥類。"},{"en":"This phrase means adding to nature, not replacing it completely.","zh":"這個片語指補充自然供應，而不是完全取代它。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":10},{"front":"spoil the scene","meaning":"破壞美好局面","examples":[{"en":"Domestic cats may spoil the scene for garden wildlife.","zh":"家貓可能為花園野生動植物破壞美好局面。"},{"en":"To spoil the scene means to damage an otherwise positive situation.","zh":"spoil the scene 指破壞原本正面的情況。"},{"en":"A loud phone call can spoil the scene in a quiet library.","zh":"大聲講電話可以破壞安靜圖書館的氣氛。"},{"en":"If cats hunt birds, they may spoil an otherwise wildlife-friendly garden.","zh":"如果貓捕獵鳥類，牠們可能破壞原本對野生動植物友善的花園。"},{"en":"This phrase suggests one problem interrupts a good picture.","zh":"這個片語暗示一個問題打斷美好的畫面。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":10},{"front":"embrace the idea of","meaning":"接納……的理念","examples":[{"en":"Britain’s gardeners have embraced the idea of gardening with nature.","zh":"英國園丁已接納與自然共融的園藝理念。"},{"en":"To embrace the idea of something means to accept it warmly and willingly.","zh":"embrace the idea of something 指熱情而願意地接受某想法。"},{"en":"A school may embrace the idea of outdoor learning after seeing students become more engaged.","zh":"學校看見學生更投入後，可能接納戶外學習的理念。"},{"en":"If gardeners embrace wildlife-friendly methods, gardens can become richer habitats.","zh":"如果園丁接納有利野生動植物的方法，花園可以變成更豐富棲息地。"},{"en":"This phrase suggests active acceptance, not reluctant agreement.","zh":"這個片語暗示主動接受，而不是勉強同意。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":10},{"front":"gardening with nature","meaning":"與自然共融的園藝","examples":[{"en":"Many gardeners now practise gardening with nature.","zh":"許多園丁現在實踐與自然共融的園藝。"},{"en":"Gardening with nature means managing a garden in ways that support natural processes and wildlife.","zh":"gardening with nature 指以支持自然過程和野生動植物的方式管理花園。"},{"en":"A gardener practises gardening with nature by using compost, planting flowers, and avoiding pesticides.","zh":"園丁透過使用堆肥、種花和避免殺蟲劑來實踐與自然共融的園藝。"},{"en":"If people garden with nature, insects, birds, and soil life can benefit.","zh":"如果人們與自然共融地打理花園，昆蟲、鳥類和土壤生命都可以受益。"},{"en":"This phrase contrasts cooperation with nature against controlling everything too tightly.","zh":"這個片語對比與自然合作和過度控制一切。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":10},{"front":"wildlife’s response","meaning":"野生動植物的反應","examples":[{"en":"Wildlife’s response to natural gardening has been spectacular.","zh":"野生動植物對自然園藝的反應十分驚人。"},{"en":"Wildlife’s response means how wild plants and animals react to a change.","zh":"wildlife’s response 指野生植物和動物對某種改變的反應。"},{"en":"If a school plants flowers, wildlife’s response may include more bees and butterflies.","zh":"如果學校種花，野生動植物的反應可能包括更多蜜蜂和蝴蝶。"},{"en":"When people stop using chemicals, wildlife’s response can be quick and visible.","zh":"當人們停止使用化學品，野生動植物的反應可以快速而明顯。"},{"en":"This phrase treats animals and plants as reacting to human choices.","zh":"這個片語把動植物視為會對人類選擇作出反應。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":10},{"front":"spectacular","meaning":"驚人的；壯觀的","examples":[{"en":"The increase in garden bird species has been spectacular.","zh":"花園鳥類品種的增加十分驚人。"},{"en":"Spectacular means very impressive, striking, or dramatic.","zh":"spectacular 指非常令人印象深刻、引人注目或戲劇性。"},{"en":"A spectacular improvement in grades may happen when a student finally studies regularly.","zh":"當學生終於定期溫習，成績可能出現驚人進步。"},{"en":"If wildlife numbers rise sharply, the recovery can look spectacular.","zh":"如果野生動植物數量急升，恢復情況可以顯得很壯觀。"},{"en":"This word describes something that strongly catches attention.","zh":"這個詞描述強烈吸引注意的事物。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":10},{"front":"artificial feeders","meaning":"人工餵飼器","examples":[{"en":"More bird species have been seen at artificial feeders.","zh":"更多鳥類品種在人工餵飼器旁被看見。"},{"en":"Artificial feeders are human-made devices that provide food for animals, especially birds.","zh":"artificial feeders 是人造的餵食裝置，尤其用來餵鳥。"},{"en":"Gardeners may place artificial feeders near trees so birds can feed safely.","zh":"園丁可能把人工餵飼器放在樹附近，讓鳥類安全進食。"},{"en":"If artificial feeders are kept clean, they can help birds without spreading disease.","zh":"如果人工餵飼器保持清潔，它們可以幫助鳥類而不傳播疾病。"},{"en":"This phrase contrasts human-provided food with natural food sources.","zh":"這個片語把人類提供的食物與天然食物來源作對比。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":11},{"front":"increase from…to…","meaning":"從……增加至……","examples":[{"en":"The number of bird species increased from 17 to 81.","zh":"鳥類品種數目從17種增加至81種。"},{"en":"Increase from A to B means rise from a lower number or level to a higher one.","zh":"increase from A to B 指由較低數字或水平上升到較高數字或水平。"},{"en":"A class’s pass rate may increase from 60 percent to 85 percent after extra practice.","zh":"額外練習後，班級合格率可能從60%增加至85%。"},{"en":"If garden bird species increase from 17 to 81, biodiversity has grown greatly.","zh":"如果花園鳥類品種從17種增加至81種，生物多樣性便大幅增長。"},{"en":"This structure is useful for describing numerical change clearly.","zh":"這個結構適合清楚描述數字變化。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":11},{"front":"Biodiversity in Urban Gardens","meaning":"城市花園生物多樣性","examples":[{"en":"The BUGS project studies biodiversity in urban gardens.","zh":"BUGS 計劃研究城市花園生物多樣性。"},{"en":"Biodiversity in Urban Gardens refers to the variety of living things found in city gardens.","zh":"Biodiversity in Urban Gardens 指城市花園中各種生物的多樣性。"},{"en":"A project on biodiversity in urban gardens may count birds, insects, plants, ponds, and nest boxes.","zh":"城市花園生物多樣性研究計劃可能統計鳥類、昆蟲、植物、池塘和鳥巢箱。"},{"en":"If urban gardens contain many different habitats, their biodiversity can be high.","zh":"如果城市花園包含許多不同棲息地，其生物多樣性可以很高。"},{"en":"This phrase connects private gardens with scientific study of nature.","zh":"這個片語把私人花園與自然科學研究連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":11},{"front":"calculate that","meaning":"計算出","examples":[{"en":"The BUGS project calculates that Sheffield has many garden ponds and nest boxes.","zh":"BUGS 計劃計算出 Sheffield 有許多花園池塘和鳥巢箱。"},{"en":"To calculate that something is true means to work it out using numbers or evidence.","zh":"calculate that something is true 指用數字或證據計算出某事。"},{"en":"A teacher may calculate that each student needs ten minutes to present.","zh":"老師可能計算出每位學生需要十分鐘報告。"},{"en":"If researchers calculate that a city has many ponds, they can estimate its wildlife potential.","zh":"如果研究人員計算出城市有許多池塘，他們可以估算其野生動植物潛力。"},{"en":"This phrase introduces a result based on counting or measurement.","zh":"這個片語引入基於點算或量度的結果。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":11},{"front":"garden ponds","meaning":"花園池塘","examples":[{"en":"Garden ponds provide habitats for urban wildlife.","zh":"花園池塘為城市野生動植物提供棲息地。"},{"en":"Garden ponds are small bodies of water in private gardens.","zh":"garden ponds 是私人花園中的小型水體。"},{"en":"Frogs, dragonflies, and birds may use garden ponds for water, breeding, or feeding.","zh":"青蛙、蜻蜓和鳥類可能使用花園池塘飲水、繁殖或覓食。"},{"en":"If garden ponds are removed, some urban wildlife may lose important habitat.","zh":"如果花園池塘被移除，一些城市野生動植物可能失去重要棲息地。"},{"en":"This phrase refers to small water features that can have large ecological value.","zh":"這個片語指具有大型生態價值的小水景。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":11},{"front":"nest boxes","meaning":"鳥巢箱","examples":[{"en":"Nest boxes can support birds in urban gardens.","zh":"鳥巢箱可以支持城市花園中的鳥類。"},{"en":"Nest boxes are small human-made boxes where birds can nest.","zh":"nest boxes 是讓鳥類築巢的人造小盒子。"},{"en":"A family may put nest boxes on trees or walls before the breeding season.","zh":"家庭可能在繁殖季節前把鳥巢箱放在樹上或牆上。"},{"en":"If natural holes are rare, nest boxes can give birds a safe place to raise young.","zh":"如果天然樹洞稀少，鳥巢箱可以給鳥類安全育雛的地方。"},{"en":"This phrase refers to artificial nesting places for wildlife.","zh":"這個片語指野生動物的人工築巢地點。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":11},{"front":"in that one city alone","meaning":"單是在那一個城市","examples":[{"en":"There are 100,000 nest boxes in that one city alone.","zh":"單是在那一個城市，就有100,000個鳥巢箱。"},{"en":"In that one city alone means only in that single city, not counting other places.","zh":"in that one city alone 指只在那一個城市中，不包括其他地方。"},{"en":"In that one school alone, over 500 students joined the reading scheme.","zh":"單是在那一間學校，就有超過500名學生參加閱讀計劃。"},{"en":"If one city alone has many nest boxes, the national total may be much larger.","zh":"如果單是一個城市已有許多鳥巢箱，全國總數可能大得多。"},{"en":"This phrase emphasises how large a number is within a limited area.","zh":"這個片語強調在有限範圍內數字已經很大。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":11},{"front":"at last","meaning":"終於","examples":[{"en":"We are at last acknowledging the importance of urban wildlife habitat.","zh":"我們終於承認城市野生動植物棲息地的重要性。"},{"en":"At last means finally, after a long wait or delay.","zh":"at last 指在長時間等待或延誤後終於發生。"},{"en":"After weeks of repair, the lift is at last working again.","zh":"經過數星期維修，升降機終於再次運作。"},{"en":"If people at last recognise urban nature, conservation policy may change.","zh":"如果人們終於認識城市自然，保育政策可能改變。"},{"en":"This phrase often carries a feeling of relief.","zh":"這個片語常帶有鬆一口氣的感覺。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":11},{"front":"acknowledge that","meaning":"承認","examples":[{"en":"We are acknowledging that urban wildlife habitat provides benefits.","zh":"我們正承認城市野生動植物棲息地提供好處。"},{"en":"To acknowledge that something is true means to accept or recognise it openly.","zh":"acknowledge that something is true 指公開接受或承認某事為真。"},{"en":"A student may acknowledge that they need more practice after seeing test results.","zh":"學生看到測驗結果後可能承認自己需要更多練習。"},{"en":"If city planners acknowledge that wildlife helps people, they may protect more green space.","zh":"如果城市規劃者承認野生動植物幫助人類，可能會保護更多綠地。"},{"en":"This phrase is stronger than merely noticing something.","zh":"這個片語比單純注意到某事更強。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":11},{"front":"life support system","meaning":"生命支援系統","examples":[{"en":"Wildlife habitat in towns provides a valuable life support system.","zh":"城鎮中的野生動植物棲息地提供有價值的生命支援系統。"},{"en":"A life support system is something that helps living things survive by providing necessary support.","zh":"life support system 是透過提供必要支援幫助生物生存的東西。"},{"en":"Trees can act as a life support system by cooling streets and cleaning air.","zh":"樹木可以透過為街道降溫和清潔空氣而作為生命支援系統。"},{"en":"If wetlands absorb storm water, they support both wildlife and people.","zh":"如果濕地吸收暴雨水，它們便同時支持野生動植物和人類。"},{"en":"This phrase shows that nature provides practical services, not only beauty.","zh":"這個片語顯示自然提供實際服務，而不只是美觀。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":11},{"front":"canopy of the urban forest","meaning":"城市森林樹冠","examples":[{"en":"The canopy of the urban forest helps filter air pollution.","zh":"城市森林樹冠幫助過濾空氣污染。"},{"en":"The canopy of the urban forest is the layer of branches and leaves formed by city trees.","zh":"canopy of the urban forest 是城市樹木由樹枝和葉子形成的覆蓋層。"},{"en":"People walking under a tree canopy may feel cooler on a hot day.","zh":"在炎熱日子，人在樹冠下行走可能感覺較涼。"},{"en":"If the urban forest canopy is dense, it can catch dust and slow rainfall.","zh":"如果城市森林樹冠茂密，它可以捕捉灰塵並減慢降雨。"},{"en":"This phrase refers to the upper leafy cover of city trees.","zh":"這個片語指城市樹木上方的葉冠覆蓋。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":11},{"front":"filter air pollution","meaning":"過濾空氣污染","examples":[{"en":"The urban forest helps filter air pollution.","zh":"城市森林幫助過濾空氣污染。"},{"en":"To filter air pollution means to remove or reduce harmful particles and gases from the air.","zh":"filter air pollution 指從空氣中移除或減少有害粒子和氣體。"},{"en":"Trees near busy roads can help filter air pollution from traffic.","zh":"繁忙道路旁的樹木可以幫助過濾交通造成的空氣污染。"},{"en":"If more trees are planted, residents may breathe cleaner air.","zh":"如果種植更多樹木，居民可能呼吸較清潔空氣。"},{"en":"This phrase describes one practical environmental benefit of urban greenery.","zh":"這個片語描述城市綠化的一項實際環境好處。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":12},{"front":"intercept rainstorms","meaning":"截留暴雨","examples":[{"en":"The urban forest can intercept rainstorms.","zh":"城市森林可以截留暴雨。"},{"en":"To intercept rainstorms means to catch or slow rain before it reaches the ground directly.","zh":"intercept rainstorms 指在雨水直接到達地面前截住或減慢它。"},{"en":"A tree canopy can intercept rainstorms by holding water on leaves and branches.","zh":"樹冠可以透過把水留在葉子和樹枝上來截留暴雨。"},{"en":"If rain is intercepted, less water may rush into drains at once.","zh":"如果雨水被截留，較少水會同時湧入排水渠。"},{"en":"This phrase explains how trees can reduce flood pressure.","zh":"這個片語解釋樹木如何減低水浸壓力。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":12},{"front":"allow the water to drip","meaning":"讓水滴下","examples":[{"en":"The canopy allows the water to drip more gradually to the ground.","zh":"樹冠讓水更逐漸地滴到地面。"},{"en":"To allow the water to drip means to let water fall slowly in drops.","zh":"allow the water to drip 指讓水以水滴形式慢慢落下。"},{"en":"Leaves allow rainwater to drip from branch to branch after a shower.","zh":"陣雨後，葉子讓雨水從樹枝一層一層滴下。"},{"en":"If water drips slowly, drains have more time to handle it.","zh":"如果水慢慢滴下，排水渠有更多時間處理它。"},{"en":"This phrase describes a gentle movement of water.","zh":"這個片語描述水的溫和移動。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":12},{"front":"more gradually","meaning":"更逐漸地","examples":[{"en":"Rainwater drips more gradually to the ground.","zh":"雨水更逐漸地滴到地面。"},{"en":"More gradually means more slowly and in smaller stages.","zh":"more gradually 指更慢地、以較小階段進行。"},{"en":"A teacher may introduce difficult grammar more gradually so students do not feel lost.","zh":"老師可能更逐漸地引入困難文法，讓學生不會迷失。"},{"en":"If rain reaches the ground more gradually, flooding risk may be reduced.","zh":"如果雨水更逐漸地到達地面，水浸風險可能降低。"},{"en":"This phrase contrasts slow controlled change with sudden movement.","zh":"這個片語對比緩慢受控變化與突然移動。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":12},{"front":"sustainable urban drainage","meaning":"可持續城市排水","examples":[{"en":"Sustainable urban drainage relies on ponds and wetlands.","zh":"可持續城市排水依靠池塘和濕地。"},{"en":"Sustainable urban drainage is a way of managing rainwater in cities using natural or low-impact systems.","zh":"sustainable urban drainage 是在城市中用自然或低影響系統管理雨水的方法。"},{"en":"A housing estate may use ponds and planted channels as sustainable urban drainage.","zh":"屋苑可能使用池塘和種植水道作可持續城市排水。"},{"en":"If drainage is sustainable, it can reduce floods while supporting wildlife.","zh":"如果排水是可持續的，它可以減少水浸，同時支持野生動植物。"},{"en":"This phrase links water management with environmental design.","zh":"這個片語把水管理與環境設計連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":12},{"front":"rely on","meaning":"依靠","examples":[{"en":"Sustainable urban drainage relies on ponds and wetlands.","zh":"可持續城市排水依靠池塘和濕地。"},{"en":"To rely on something means to depend on it for support or success.","zh":"rely on something 指依賴某物取得支持或成功。"},{"en":"Students rely on clear examples when learning difficult vocabulary.","zh":"學生學習困難詞彙時依靠清楚例子。"},{"en":"If a city relies on wetlands for drainage, it must protect them.","zh":"如果城市依靠濕地排水，就必須保護它們。"},{"en":"This phrase shows dependence on a person, tool, or system.","zh":"這個片語顯示對人、工具或系統的依賴。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":12},{"front":"contain storm water runoff","meaning":"容納暴雨徑流","examples":[{"en":"Ponds and wetlands contain storm water runoff.","zh":"池塘和濕地容納暴雨徑流。"},{"en":"To contain storm water runoff means to hold rainwater that flows across surfaces after heavy rain.","zh":"contain storm water runoff 指容納大雨後流過表面的雨水。"},{"en":"A park pond can contain storm water runoff during a sudden downpour.","zh":"公園池塘可以在突然暴雨時容納暴雨徑流。"},{"en":"If runoff is contained, streets and homes are less likely to flood.","zh":"如果徑流被容納，街道和房屋較不容易水浸。"},{"en":"This phrase describes storing excess rainwater safely.","zh":"這個片語描述安全儲存多餘雨水。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":12},{"front":"reduce the risk of flooding","meaning":"減低水浸風險","examples":[{"en":"Wetlands can reduce the risk of flooding.","zh":"濕地可以減低水浸風險。"},{"en":"To reduce the risk of flooding means to make flooding less likely or less severe.","zh":"reduce the risk of flooding 指令水浸較不可能發生或較不嚴重。"},{"en":"Clearing drains before heavy rain can reduce the risk of flooding in streets.","zh":"大雨前清理排水渠可以減低街道水浸風險。"},{"en":"If wetlands store extra water, nearby homes may be safer during storms.","zh":"如果濕地儲存多餘水分，附近住宅在暴風雨中可能較安全。"},{"en":"This phrase explains a practical benefit of natural water systems.","zh":"這個片語解釋天然水系統的實際好處。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":12},{"front":"reed beds","meaning":"蘆葦床","examples":[{"en":"Reed beds help to clean up water.","zh":"蘆葦床幫助淨化水質。"},{"en":"Reed beds are areas of tall water plants growing in wet ground or shallow water.","zh":"reed beds 是在濕地或淺水中生長的高大水生植物區。"},{"en":"Birds may nest in reed beds because the tall stems provide cover.","zh":"鳥類可能在蘆葦床築巢，因為高莖提供遮蔽。"},{"en":"If dirty water passes through reed beds, plants and microbes can help remove pollutants.","zh":"如果污水流經蘆葦床，植物和微生物可以幫助移除污染物。"},{"en":"This phrase refers to wetland vegetation that can support wildlife and water cleaning.","zh":"這個片語指能支持野生動植物和淨化水質的濕地植被。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":12},{"front":"wetland wildlife communities","meaning":"濕地野生生物群落","examples":[{"en":"Wetland wildlife communities help clean up the water.","zh":"濕地野生生物群落幫助淨化水質。"},{"en":"Wetland wildlife communities are groups of plants, animals, and microbes living together in wetlands.","zh":"wetland wildlife communities 是一起生活在濕地中的植物、動物和微生物群體。"},{"en":"Frogs, insects, reeds, and bacteria can all be part of wetland wildlife communities.","zh":"青蛙、昆蟲、蘆葦和細菌都可以是濕地野生生物群落的一部分。"},{"en":"If these communities are healthy, they can filter water and support food chains.","zh":"如果這些群落健康，它們可以過濾水質並支持食物鏈。"},{"en":"This phrase describes living networks in wet habitats.","zh":"這個片語描述濕地棲息地中的生命網絡。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":12},{"front":"clean up the water","meaning":"淨化水質","examples":[{"en":"Reed beds and wetlands help clean up the water.","zh":"蘆葦床和濕地幫助淨化水質。"},{"en":"To clean up the water means to remove pollution or make water healthier.","zh":"clean up the water 指移除污染或令水更健康。"},{"en":"A community may plant reeds to clean up the water in a polluted pond.","zh":"社區可能種植蘆葦來淨化受污染池塘的水質。"},{"en":"If water is cleaned up, fish, insects, and birds can return more easily.","zh":"如果水質被淨化，魚類、昆蟲和鳥類更容易回來。"},{"en":"This phrase describes improving water quality.","zh":"這個片語描述改善水質。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":12},{"front":"scientific proof","meaning":"科學證據","examples":[{"en":"There is scientific proof that contact with wildlife can reduce stress.","zh":"有科學證據顯示接觸野生動植物可以減少壓力。"},{"en":"Scientific proof means evidence collected through careful research or testing.","zh":"scientific proof 指透過仔細研究或測試收集的證據。"},{"en":"Doctors need scientific proof before recommending a new treatment widely.","zh":"醫生在廣泛推薦新治療前需要科學證據。"},{"en":"If scientific proof supports nature contact, city planning should take green space seriously.","zh":"如果科學證據支持接觸自然，城市規劃就應認真看待綠地。"},{"en":"This phrase is stronger than personal opinion or belief.","zh":"這個片語比個人意見或信念更強。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":13},{"front":"contact with wildlife","meaning":"接觸野生動植物","examples":[{"en":"Contact with wildlife close to home can reduce stress and anger.","zh":"在家附近接觸野生動植物可以減少壓力和憤怒。"},{"en":"Contact with wildlife means seeing, hearing, or spending time near wild plants and animals.","zh":"contact with wildlife 指看見、聽見或花時間靠近野生植物和動物。"},{"en":"Watching birds from a window is a simple form of contact with wildlife.","zh":"從窗邊觀鳥是一種簡單的接觸野生動植物方式。"},{"en":"If people have regular contact with wildlife, they may feel calmer and more connected to nature.","zh":"如果人們定期接觸野生動植物，可能感到更平靜並與自然更有連繫。"},{"en":"This phrase does not always mean touching animals physically.","zh":"這個片語不一定表示實際觸摸動物。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":13},{"front":"close to home","meaning":"在家附近","examples":[{"en":"Wildlife close to home can benefit people’s health.","zh":"在家附近的野生動植物可以有益於人的健康。"},{"en":"Close to home means near where someone lives.","zh":"close to home 指靠近某人居住的地方。"},{"en":"A park close to home makes it easier for children to play outside after school.","zh":"在家附近有公園，孩子放學後更容易到戶外玩耍。"},{"en":"If nature is close to home, people can enjoy it without long travel.","zh":"如果自然在家附近，人們不用長途旅行也能享受它。"},{"en":"This phrase suggests convenience and personal relevance.","zh":"這個片語暗示方便和與個人相關。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":13},{"front":"reduce stress and anger","meaning":"減少壓力和憤怒","examples":[{"en":"Contact with wildlife can help reduce stress and anger.","zh":"接觸野生動植物可以幫助減少壓力和憤怒。"},{"en":"To reduce stress and anger means to make people feel calmer and less upset.","zh":"reduce stress and anger 指令人感到更平靜和較少不快。"},{"en":"A short walk in a quiet park can reduce stress and anger after work.","zh":"下班後在安靜公園短暫散步可以減少壓力和憤怒。"},{"en":"If hospital gardens help patients relax, they may support recovery.","zh":"如果醫院花園幫助病人放鬆，它們可能支持康復。"},{"en":"This phrase describes a mental health benefit.","zh":"這個片語描述心理健康好處。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":13},{"front":"hospital patients","meaning":"住院病人","examples":[{"en":"Hospital patients recover faster when they can see green space.","zh":"住院病人能看見綠地時康復得更快。"},{"en":"Hospital patients are people receiving medical care in a hospital.","zh":"hospital patients 是在醫院接受醫療護理的人。"},{"en":"Hospital patients may feel less lonely when visitors and nurses support them.","zh":"當訪客和護士支持他們，住院病人可能感到較少孤獨。"},{"en":"If hospital patients can see trees from a window, their mood may improve.","zh":"如果住院病人能從窗邊看見樹木，他們的心情可能改善。"},{"en":"This phrase refers to people under medical treatment, not hospital staff.","zh":"這個片語指接受醫療治療的人，而不是醫院職員。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":13},{"front":"a view of","meaning":"……的景觀","examples":[{"en":"Hospital patients with a view of natural green space recover faster.","zh":"擁有自然綠地景觀的住院病人康復得更快。"},{"en":"A view of something means the ability to see it from a particular place.","zh":"a view of something 指從某個地方能看見某物。"},{"en":"A classroom with a view of trees may feel calmer than one facing a wall.","zh":"有樹木景觀的課室可能比面向牆壁的課室感覺更平靜。"},{"en":"If patients have a view of nature, they may feel less stressed during recovery.","zh":"如果病人有自然景觀，他們康復期間可能壓力較少。"},{"en":"This phrase connects what people can see with how they feel.","zh":"這個片語把人們能看見的東西與感受連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":13},{"front":"natural green space","meaning":"自然綠地","examples":[{"en":"Natural green space can help patients recover.","zh":"自然綠地可以幫助病人康復。"},{"en":"Natural green space is land with plants, trees, grass, or water that feels close to nature.","zh":"natural green space 是有植物、樹木、草地或水並感覺接近自然的土地。"},{"en":"A hospital garden can provide natural green space for patients and visitors.","zh":"醫院花園可以為病人和訪客提供自然綠地。"},{"en":"If a neighbourhood lacks natural green space, residents may have fewer chances to relax outdoors.","zh":"如果社區缺乏自然綠地，居民可能較少有機會在戶外放鬆。"},{"en":"This phrase refers to living greenery, not painted green surfaces.","zh":"這個片語指有生命的綠化，而不是塗成綠色的表面。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":13},{"front":"make a more rapid recovery","meaning":"康復得更快","examples":[{"en":"Patients with a view of green space make a more rapid recovery.","zh":"有綠地景觀的病人康復得更快。"},{"en":"To make a more rapid recovery means to get better faster after illness or injury.","zh":"make a more rapid recovery 指在生病或受傷後更快好轉。"},{"en":"A patient may make a more rapid recovery if they rest well and follow medical advice.","zh":"如果病人休息充足並遵從醫囑，可能康復得更快。"},{"en":"If nature reduces stress, it may help patients recover more quickly.","zh":"如果自然減少壓力，它可能幫助病人更快康復。"},{"en":"This phrase focuses on faster healing.","zh":"這個片語聚焦於更快痊癒。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":13},{"front":"suffer less pain","meaning":"承受較少痛楚","examples":[{"en":"Patients with green views may suffer less pain.","zh":"有綠色景觀的病人可能承受較少痛楚。"},{"en":"To suffer less pain means to feel a lower level of physical discomfort.","zh":"suffer less pain 指感受到較低程度的身體不適。"},{"en":"A patient may suffer less pain after taking the correct medicine.","zh":"病人服用正確藥物後可能承受較少痛楚。"},{"en":"If a calm environment reduces tension, patients may experience less pain.","zh":"如果平靜環境減少緊張，病人可能感到較少痛楚。"},{"en":"This phrase describes a reduction in suffering, not complete absence of pain.","zh":"這個片語描述痛苦減少，而不是完全沒有痛楚。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":13},{"front":"traditionally","meaning":"傳統上","examples":[{"en":"Traditionally, nature conservation in the UK was seen as rural.","zh":"傳統上，英國的自然保育被視為鄉郊事務。"},{"en":"Traditionally means according to older customs, beliefs, or usual ways of thinking.","zh":"traditionally 指根據較舊的習俗、信念或慣常想法。"},{"en":"Traditionally, students learned vocabulary by copying lists, but many now use examples.","zh":"傳統上，學生透過抄詞表學詞彙，但現在許多人使用例句。"},{"en":"If conservation was traditionally seen as rural, urban wildlife may have been overlooked.","zh":"如果保育傳統上被視為鄉郊事務，城市野生動植物可能曾被忽視。"},{"en":"This word often introduces an older view that may now be changing.","zh":"這個詞常引入正在改變的舊觀點。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":13},{"front":"nature conservation","meaning":"自然保育","examples":[{"en":"Nature conservation is now part of urban policy.","zh":"自然保育現在是城市政策的一部分。"},{"en":"Nature conservation means protecting wild plants, animals, habitats, and natural processes.","zh":"nature conservation 指保護野生植物、動物、棲息地和自然過程。"},{"en":"Schools can teach nature conservation by helping students care for a pond or garden.","zh":"學校可以透過幫助學生照顧池塘或花園來教授自然保育。"},{"en":"If nature conservation is included in city planning, more habitats may be created.","zh":"如果自然保育被納入城市規劃，更多棲息地可能被創造。"},{"en":"This phrase refers to active protection of the natural world.","zh":"這個片語指對自然世界的主動保護。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":13},{"front":"be seen as marginal","meaning":"被視為邊緣","examples":[{"en":"Nature conservation has traditionally been seen as marginal.","zh":"自然保育傳統上被視為邊緣。"},{"en":"To be seen as marginal means to be considered unimportant or not central.","zh":"be seen as marginal 指被認為不重要或不是核心。"},{"en":"Art lessons may be seen as marginal if a school focuses only on exam subjects.","zh":"如果學校只重視考試科目，藝術課可能被視為邊緣。"},{"en":"If urban wildlife is seen as marginal, it may receive little funding or policy attention.","zh":"如果城市野生動植物被視為邊緣，它可能得到很少資金或政策關注。"},{"en":"This phrase describes low status in decision-making.","zh":"這個片語描述在決策中的低地位。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":14},{"front":"largely rural","meaning":"主要屬於鄉郊","examples":[{"en":"Nature conservation was traditionally seen as largely rural.","zh":"自然保育傳統上被視為主要屬於鄉郊。"},{"en":"Largely rural means mainly connected with the countryside.","zh":"largely rural 指主要與鄉郊有關。"},{"en":"A largely rural district may have many farms, villages, and open fields.","zh":"主要屬於鄉郊的地區可能有許多農場、村莊和開闊田野。"},{"en":"If conservation is seen as largely rural, city habitats may be undervalued.","zh":"如果保育被視為主要屬於鄉郊，城市棲息地可能被低估。"},{"en":"This phrase means mostly rural, not completely rural.","zh":"這個片語指大多是鄉郊，而不是完全是鄉郊。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":14},{"front":"place something at the heart of","meaning":"將……置於……的核心","examples":[{"en":"We are beginning to place nature conservation at the heart of policy.","zh":"我們開始將自然保育置於政策核心。"},{"en":"To place something at the heart of something means to make it central and important.","zh":"place something at the heart of something 指把某事放在中心和重要位置。"},{"en":"A school may place student well-being at the heart of its timetable design.","zh":"學校可能將學生身心健康置於時間表設計的核心。"},{"en":"If cities place wildlife at the heart of planning, green spaces become a priority.","zh":"如果城市將野生動植物置於規劃核心，綠色空間便會成為優先事項。"},{"en":"This phrase shows a shift from side issue to core concern.","zh":"這個片語顯示由邊緣議題轉為核心關注。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":14},{"front":"urban environmental and economic policy","meaning":"城市環境及經濟政策","examples":[{"en":"Nature conservation is becoming part of urban environmental and economic policy.","zh":"自然保育正成為城市環境及經濟政策的一部分。"},{"en":"Urban environmental and economic policy means city policy about the environment, jobs, money, land, and development.","zh":"urban environmental and economic policy 指關於城市環境、工作、金錢、土地和發展的政策。"},{"en":"A city may include tree planting in urban environmental and economic policy because green areas attract residents and visitors.","zh":"城市可能把植樹納入城市環境及經濟政策，因為綠地吸引居民和訪客。"},{"en":"If wildlife habitat reduces flooding and improves health, it belongs in urban policy.","zh":"如果野生動植物棲息地減少水浸並改善健康，它就應屬於城市政策。"},{"en":"This phrase connects nature with city management and economic planning.","zh":"這個片語把自然與城市管理和經濟規劃連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":14},{"front":"dozens of schemes","meaning":"數十個計劃","examples":[{"en":"There are now dozens of schemes to create and restore habitats.","zh":"現在有數十個計劃創造和修復棲息地。"},{"en":"Dozens of schemes means many plans or projects, usually at least twenty-four or more.","zh":"dozens of schemes 指許多計劃或項目，通常至少二十多個。"},{"en":"A city may run dozens of schemes to improve parks, transport, and housing.","zh":"城市可能推行數十個計劃改善公園、交通和房屋。"},{"en":"If dozens of schemes create habitats, urban wildlife can recover in many places at once.","zh":"如果數十個計劃創造棲息地，城市野生動植物可以在許多地方同時恢復。"},{"en":"This phrase stresses a large number of organised efforts.","zh":"這個片語強調大量有組織的努力。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":14},{"front":"create new habitats","meaning":"創造新棲息地","examples":[{"en":"Cities are creating new habitats for wildlife.","zh":"城市正在為野生動植物創造新棲息地。"},{"en":"To create new habitats means to make new places where plants and animals can live.","zh":"create new habitats 指建立植物和動物可以生活的新地方。"},{"en":"A school can create new habitats by adding a pond and planting native flowers.","zh":"學校可以透過增加池塘和種植本地花卉來創造新棲息地。"},{"en":"If new habitats are created in cities, wildlife may return to areas where it had disappeared.","zh":"如果城市創造新棲息地，野生動植物可能回到曾經消失的地區。"},{"en":"This phrase describes active environmental improvement.","zh":"這個片語描述主動的環境改善。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":14},{"front":"restore old ones","meaning":"修復舊有棲息地","examples":[{"en":"Some schemes restore old habitats in and around cities.","zh":"一些計劃修復城市及其周邊的舊有棲息地。"},{"en":"To restore old ones means to repair or bring back old habitats that have been damaged or lost.","zh":"restore old ones 指修復或恢復已受損或失去的舊棲息地。"},{"en":"A community may restore an old pond by removing rubbish and planting reeds.","zh":"社區可能透過清除垃圾和種植蘆葦來修復舊池塘。"},{"en":"If old habitats are restored, wildlife may return without needing completely new land.","zh":"如果舊棲息地被修復，野生動植物可能不需要全新土地也能回來。"},{"en":"This phrase contrasts repair with creating something from nothing.","zh":"這個片語對比修復與從零創造。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":14},{"front":"in and around","meaning":"在……及其周邊","examples":[{"en":"There are schemes in and around big cities.","zh":"大城市及其周邊有相關計劃。"},{"en":"In and around a place means both inside it and in the nearby surrounding areas.","zh":"in and around a place 指在某地方內部以及附近周邊地區。"},{"en":"Students may find part-time jobs in and around their neighbourhood.","zh":"學生可能在自己社區及其周邊找到兼職工作。"},{"en":"If habitat projects happen in and around cities, wildlife corridors can extend beyond city centres.","zh":"如果棲息地計劃在城市及其周邊進行，野生動植物走廊可以延伸到市中心以外。"},{"en":"This phrase expands the location beyond one exact boundary.","zh":"這個片語把地點擴展到精確邊界之外。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":14},{"front":"big cities","meaning":"大城市","examples":[{"en":"Wildlife schemes are being developed around big cities.","zh":"野生動植物計劃正在大城市周邊發展。"},{"en":"Big cities are large urban areas with many people, buildings, roads, and services.","zh":"big cities 是人口、建築、道路和服務很多的大型城市地區。"},{"en":"Big cities need parks and trees because many residents live in dense neighbourhoods.","zh":"大城市需要公園和樹木，因為許多居民住在人口稠密社區。"},{"en":"If big cities create habitats, many people can benefit from nearby nature.","zh":"如果大城市創造棲息地，許多人可以從附近自然中受益。"},{"en":"This phrase refers to major urban centres, not small towns.","zh":"這個片語指主要城市中心，而不是小城鎮。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":14},{"front":"biodiversity","meaning":"生物多樣性","examples":[{"en":"Biodiversity is important in parts of London.","zh":"生物多樣性在倫敦部分地區很重要。"},{"en":"Biodiversity means the variety of plants, animals, fungi, and other living things in an area.","zh":"biodiversity 指某地區中植物、動物、真菌和其他生物的多樣性。"},{"en":"A garden with flowers, trees, insects, birds, and frogs has higher biodiversity than a plain lawn.","zh":"有花、樹、昆蟲、鳥類和青蛙的花園，比普通草坪有更高生物多樣性。"},{"en":"If biodiversity increases, an ecosystem may become healthier and more resilient.","zh":"如果生物多樣性增加，生態系統可能變得更健康和更有韌性。"},{"en":"This word is central to conservation and habitat planning.","zh":"這個詞是保育和棲息地規劃中的核心概念。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":14},{"front":"thanks to","meaning":"多虧","examples":[{"en":"Biodiversity is increasing thanks to schemes like the London Wetland Centre.","zh":"多虧像倫敦濕地中心這樣的計劃，生物多樣性正在增加。"},{"en":"Thanks to means because of someone or something helpful.","zh":"thanks to 指因為某人或某事有幫助。"},{"en":"Thanks to extra practice, the student finally felt confident in speaking.","zh":"多虧額外練習，學生終於對說話有信心。"},{"en":"Thanks to new ponds and wetlands, more birds may return to a city.","zh":"多虧新的池塘和濕地，更多鳥類可能回到城市。"},{"en":"This phrase usually introduces a positive cause.","zh":"這個片語通常引入正面原因。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":14},{"front":"London Wetland Centre","meaning":"倫敦濕地中心","examples":[{"en":"The London Wetland Centre is a major urban nature site.","zh":"倫敦濕地中心是一個重要的城市自然地點。"},{"en":"The London Wetland Centre is a wetland reserve in London created from a former reservoir site.","zh":"London Wetland Centre 是倫敦一個由前水塘地點改造而成的濕地保護區。"},{"en":"Visitors may go to the London Wetland Centre to watch birds and learn about wetlands.","zh":"訪客可能到倫敦濕地中心觀鳥並學習濕地知識。"},{"en":"If a former reservoir becomes a wetland centre, it can support wildlife and education.","zh":"如果前水塘變成濕地中心，它可以支持野生動植物和教育。"},{"en":"This phrase names a specific example of urban habitat restoration.","zh":"這個片語指出城市棲息地修復的一個具體例子。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":15},{"front":"in the south west of","meaning":"在……西南部","examples":[{"en":"The London Wetland Centre is in the south west of the city.","zh":"倫敦濕地中心位於該城市的西南部。"},{"en":"In the south west of a place means in its lower-left or south-western area on a map.","zh":"in the south west of a place 指在地圖上某地的西南部或左下方區域。"},{"en":"A school may be located in the south west of a town near a park.","zh":"學校可能位於城鎮西南部、公園附近。"},{"en":"If a nature reserve is in the south west of a city, nearby residents can visit it easily.","zh":"如果自然保護區位於城市西南部，附近居民可以較容易到訪。"},{"en":"This phrase gives a location within a larger area.","zh":"這個片語給出較大地區中的位置。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":15},{"front":"unique scheme","meaning":"獨特計劃","examples":[{"en":"The London Wetland Centre is a unique scheme.","zh":"倫敦濕地中心是一個獨特計劃。"},{"en":"A unique scheme is a special plan or project that is unlike others.","zh":"unique scheme 是不同於其他項目的特殊計劃。"},{"en":"A city may create a unique scheme by turning an old car park into a community garden.","zh":"城市可能透過把舊停車場變成社區花園來創造獨特計劃。"},{"en":"If a scheme is unique, it may attract attention and become a model for other cities.","zh":"如果計劃獨特，它可能吸引關注並成為其他城市的模式。"},{"en":"This phrase stresses originality and special design.","zh":"這個片語強調原創性和特別設計。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":15},{"front":"masterminded by","meaning":"由……策劃","examples":[{"en":"The scheme was masterminded by the Wildfowl and Wetlands Trust.","zh":"這個計劃由野禽及濕地信託策劃。"},{"en":"Masterminded by someone means planned and directed by that person or organisation.","zh":"masterminded by someone 指由某人或某組織策劃並主導。"},{"en":"The school charity fair was masterminded by a group of older students.","zh":"學校慈善市集由一群高年級學生策劃。"},{"en":"If a project is masterminded by experts, it may be carefully designed from the start.","zh":"如果項目由專家策劃，它可能從一開始就設計得很仔細。"},{"en":"This phrase gives credit to the main planner behind a project.","zh":"這個片語把功勞歸於項目背後的主要策劃者。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":15},{"front":"Wildfowl and Wetlands Trust","meaning":"野禽及濕地信託","examples":[{"en":"The Wildfowl and Wetlands Trust created the London Wetland Centre.","zh":"野禽及濕地信託創建了倫敦濕地中心。"},{"en":"The Wildfowl and Wetlands Trust is an organisation concerned with wetland birds and wetland habitats.","zh":"Wildfowl and Wetlands Trust 是關注濕地鳥類和濕地棲息地的組織。"},{"en":"A conservation trust may protect birds by restoring ponds, marshes, and reed beds.","zh":"保育信託可以透過修復池塘、沼澤和蘆葦床來保護鳥類。"},{"en":"If such a trust creates a wetland reserve, both wildlife and visitors can benefit.","zh":"如果這類信託創建濕地保護區，野生動植物和訪客都可以受益。"},{"en":"This phrase names the organisation behind the scheme.","zh":"這個片語指出計劃背後的組織。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":15},{"front":"wildlife reserve","meaning":"野生動植物保護區","examples":[{"en":"The scheme created a wildlife reserve from an old reservoir.","zh":"這個計劃由舊水塘創造出野生動植物保護區。"},{"en":"A wildlife reserve is an area protected so wild plants and animals can live safely.","zh":"wildlife reserve 是受保護的地區，讓野生植物和動物安全生活。"},{"en":"Families may visit a wildlife reserve to learn about birds, insects, and wetlands.","zh":"家庭可能到野生動植物保護區學習鳥類、昆蟲和濕地。"},{"en":"If a site becomes a wildlife reserve, building and disturbance may be limited.","zh":"如果一個地點成為野生動植物保護區，建築和干擾可能受限制。"},{"en":"This phrase refers to land managed mainly for nature protection.","zh":"這個片語指主要為自然保護而管理的土地。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":15},{"front":"out of","meaning":"由……改造成","examples":[{"en":"The trust created a wildlife reserve out of a redundant reservoir.","zh":"該信託由一個廢棄水塘改造成野生動植物保護區。"},{"en":"Out of can mean using something as the material or starting point for making something new.","zh":"out of 可以指使用某物作材料或起點來製造新事物。"},{"en":"A teacher made a reading game out of old vocabulary cards.","zh":"老師用舊詞彙卡改造成閱讀遊戲。"},{"en":"If a city creates a wetland out of an old reservoir, unused land gains a new purpose.","zh":"如果城市由舊水塘改造成濕地，閒置土地便得到新用途。"},{"en":"This phrase shows transformation from one thing into another.","zh":"這個片語顯示由一物轉變成另一物。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":15},{"front":"redundant Victorian reservoir","meaning":"廢棄的維多利亞時代水塘","examples":[{"en":"The site was once a redundant Victorian reservoir.","zh":"該地點曾是一個廢棄的維多利亞時代水塘。"},{"en":"A redundant Victorian reservoir is an old water-storage structure from the Victorian period that is no longer needed.","zh":"redundant Victorian reservoir 是維多利亞時代建造、現在不再需要的舊儲水結構。"},{"en":"A redundant reservoir may become empty land if the city no longer uses it for water supply.","zh":"如果城市不再用水塘供水，廢棄水塘可能變成空置土地。"},{"en":"If such a reservoir is restored, it can become wetland habitat.","zh":"如果這類水塘被修復，它可以成為濕地棲息地。"},{"en":"This phrase combines age, original function, and disuse.","zh":"這個片語結合年代、原本功能和廢棄狀態。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":15},{"front":"within five years of","meaning":"在……之後五年內","examples":[{"en":"Within five years of its creation, the centre was recognised nationally.","zh":"在創立後五年內，該中心獲全國認可。"},{"en":"Within five years of something means before five years had passed after that event.","zh":"within five years of something 指在某事件之後五年過去之前。"},{"en":"Within five years of opening, a small school may become popular in the community.","zh":"小學校開辦後五年內可能在社區變得受歡迎。"},{"en":"If a wetland becomes nationally recognised within five years, its success is rapid.","zh":"如果濕地在五年內獲全國認可，其成功速度很快。"},{"en":"This phrase gives a time limit after a starting point.","zh":"這個片語給出起點之後的時間限制。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":15},{"front":"be hailed as","meaning":"被譽為","examples":[{"en":"The centre was hailed as one of England’s leading nature sites.","zh":"該中心被譽為英格蘭主要自然景點之一。"},{"en":"To be hailed as something means to be publicly praised or recognised as that thing.","zh":"be hailed as something 指被公開讚揚或認可為某事物。"},{"en":"A new hospital may be hailed as a major improvement for local healthcare.","zh":"新醫院可能被譽為本地醫療的一項重大改善。"},{"en":"If a restored wetland is hailed as a success, other cities may copy the idea.","zh":"如果修復濕地被譽為成功，其他城市可能仿效該想法。"},{"en":"This phrase suggests strong public approval.","zh":"這個片語暗示強烈公眾認可。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":15},{"front":"leading nature sites","meaning":"主要自然景點","examples":[{"en":"The centre became one of England’s leading nature sites.","zh":"該中心成為英格蘭主要自然景點之一。"},{"en":"Leading nature sites are important places known for wildlife, habitats, or conservation value.","zh":"leading nature sites 是以野生動植物、棲息地或保育價值聞名的重要地方。"},{"en":"A wetland with rare birds can become a leading nature site in a city.","zh":"有珍稀鳥類的濕地可以成為城市中的主要自然景點。"},{"en":"If a site attracts scientists and visitors, its conservation importance may grow.","zh":"如果一個地點吸引科學家和訪客，其保育重要性可能上升。"},{"en":"This phrase describes high status among nature locations.","zh":"這個片語描述自然地點中的高地位。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":15},{"front":"be designated","meaning":"被指定為","examples":[{"en":"The centre was designated a Site of Special Scientific Interest.","zh":"該中心被指定為具特殊科學價值地點。"},{"en":"To be designated means to be officially named or given a particular status.","zh":"be designated 指被正式命名或給予特定地位。"},{"en":"A building may be designated a heritage site because of its history.","zh":"建築物可能因其歷史而被指定為文物地點。"},{"en":"If a wetland is designated for protection, development may be limited.","zh":"如果濕地被指定為受保護地點，發展可能受限制。"},{"en":"This phrase is often used in official or legal contexts.","zh":"這個片語常用於官方或法律語境。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":16},{"front":"Site of Special Scientific Interest","meaning":"具特殊科學價值地點","examples":[{"en":"The London Wetland Centre was designated a Site of Special Scientific Interest.","zh":"倫敦濕地中心被指定為具特殊科學價值地點。"},{"en":"A Site of Special Scientific Interest is an officially recognised place with important wildlife, geology, or scientific value.","zh":"Site of Special Scientific Interest 是因重要野生動植物、地質或科學價值而獲官方認可的地方。"},{"en":"A rare wetland may be protected as a Site of Special Scientific Interest.","zh":"珍稀濕地可能被保護為具特殊科學價值地點。"},{"en":"If a site receives this status, it may gain stronger conservation protection.","zh":"如果地點獲得這種地位，它可能得到更強保育保護。"},{"en":"This phrase refers to a formal conservation designation.","zh":"這個片語指正式的保育指定。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":16},{"front":"consist of","meaning":"由……組成","examples":[{"en":"The centre consists of a 105-acre wetland site.","zh":"該中心由一個105英畝濕地組成。"},{"en":"To consist of something means to be made up of it.","zh":"consist of something 指由某物組成。"},{"en":"A school lunch may consist of rice, vegetables, soup, and fruit.","zh":"學校午餐可能由米飯、蔬菜、湯和水果組成。"},{"en":"If a reserve consists of wetlands, its wildlife will depend heavily on water habitats.","zh":"如果保護區由濕地組成，其野生動植物會高度依賴水域棲息地。"},{"en":"This phrase describes what something contains or is composed of.","zh":"這個片語描述某物包含甚麼或由甚麼構成。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":16},{"front":"105-acre wetland site","meaning":"105英畝濕地","examples":[{"en":"The centre consists of a 105-acre wetland site.","zh":"該中心由一個105英畝濕地組成。"},{"en":"A 105-acre wetland site is a large wetland area covering 105 acres.","zh":"105-acre wetland site 是面積達105英畝的大型濕地。"},{"en":"A site of this size can contain ponds, marshes, paths, and birdwatching areas.","zh":"這種大小的地點可以包含池塘、沼澤、小徑和觀鳥區。"},{"en":"If a wetland site is large enough, it can support many different species.","zh":"如果濕地面積足夠大，它可以支持許多不同物種。"},{"en":"This phrase combines land size with habitat type.","zh":"這個片語結合土地面積與棲息地類型。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":16},{"front":"be made up of","meaning":"由……組成","examples":[{"en":"The site is made up of different wetland habitats.","zh":"該地點由不同濕地棲息地組成。"},{"en":"To be made up of something means to consist of several parts or materials.","zh":"be made up of something 指由幾個部分或材料組成。"},{"en":"A good lesson is made up of explanation, examples, practice, and feedback.","zh":"好課堂由解釋、例子、練習和回饋組成。"},{"en":"If a reserve is made up of different habitats, it can support more species.","zh":"如果保護區由不同棲息地組成，它可以支持更多物種。"},{"en":"This phrase explains the parts inside a whole.","zh":"這個片語解釋整體中的部分。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":16},{"front":"wetland habitats","meaning":"濕地棲息地","examples":[{"en":"The site contains different wetland habitats.","zh":"該地點包含不同濕地棲息地。"},{"en":"Wetland habitats are wet places where water shapes the plants, animals, and soil.","zh":"wetland habitats 是受水影響植物、動物和土壤的濕潤地方。"},{"en":"Marshes, ponds, reed beds, and shallow pools are wetland habitats.","zh":"沼澤、池塘、蘆葦床和淺水池都是濕地棲息地。"},{"en":"If wetland habitats are healthy, frogs, insects, birds, and plants can thrive.","zh":"如果濕地棲息地健康，青蛙、昆蟲、鳥類和植物可以繁盛。"},{"en":"This phrase refers to water-based living environments.","zh":"這個片語指以水為基礎的生活環境。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":16},{"front":"shallow, open water","meaning":"淺而開闊的水域","examples":[{"en":"The site includes shallow, open water.","zh":"該地點包括淺而開闊的水域。"},{"en":"Shallow, open water means water that is not deep and is not covered by dense plants.","zh":"shallow, open water 指不深且沒有被茂密植物覆蓋的水域。"},{"en":"Ducks may feed in shallow, open water where they can reach plants and insects.","zh":"鴨子可能在淺而開闊的水域覓食，因為牠們可以接觸植物和昆蟲。"},{"en":"If a wetland has shallow open water, birds can land, feed, and rest there.","zh":"如果濕地有淺而開闊的水域，鳥類可以在那裡降落、覓食和休息。"},{"en":"This phrase describes a specific wetland feature.","zh":"這個片語描述特定濕地特徵。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":16},{"front":"grazing marsh","meaning":"放牧沼澤","examples":[{"en":"The wetland site includes grazing marsh.","zh":"該濕地包括放牧沼澤。"},{"en":"Grazing marsh is wet grassland where animals may graze and wetland wildlife can live.","zh":"grazing marsh 是可讓動物放牧並支持濕地野生動植物的潮濕草地。"},{"en":"Cattle may feed on grazing marsh while birds use the wet ground nearby.","zh":"牛可能在放牧沼澤進食，而鳥類使用附近濕地。"},{"en":"If grazing marsh is managed gently, it can support plants, insects, and birds.","zh":"如果放牧沼澤被溫和管理，它可以支持植物、昆蟲和鳥類。"},{"en":"This phrase combines farming use with wetland habitat.","zh":"這個片語結合農業用途與濕地棲息地。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":16},{"front":"attract more than","meaning":"吸引超過……","examples":[{"en":"The site attracts more than 104 species of bird.","zh":"該地點吸引超過104種鳥類。"},{"en":"To attract more than a number means to bring in a quantity greater than that number.","zh":"attract more than a number 指吸引多於某個數字的數量。"},{"en":"A school fair may attract more than 500 visitors if many families join.","zh":"如果許多家庭參與，學校市集可能吸引超過500名訪客。"},{"en":"If a wetland attracts more than 100 bird species, it is likely to be ecologically rich.","zh":"如果濕地吸引超過100種鳥類，它很可能生態豐富。"},{"en":"This phrase is used to show a minimum number exceeded.","zh":"這個片語用來顯示超過某個最低數字。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":16},{"front":"nationally important rarities","meaning":"具全國重要性的珍稀物種","examples":[{"en":"The site attracts nationally important rarities such as the bittern.","zh":"該地點吸引麻鳽等具全國重要性的珍稀物種。"},{"en":"Nationally important rarities are rare species considered important at the national level.","zh":"nationally important rarities 是在全國層面被視為重要的珍稀物種。"},{"en":"A reserve may become famous if it protects nationally important rarities.","zh":"如果保護區保護具全國重要性的珍稀物種，它可能變得有名。"},{"en":"If a rare bird breeds at a site, conservationists may give that site special attention.","zh":"如果珍稀鳥類在某地繁殖，保育人士可能特別重視該地點。"},{"en":"This phrase combines rarity with national conservation value.","zh":"這個片語結合珍稀性與全國保育價值。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":16},{"front":"bittern","meaning":"麻鳽；鳽鳥","examples":[{"en":"The bittern is one of the rare birds found at the site.","zh":"麻鳽是該地點發現的珍稀鳥類之一。"},{"en":"A bittern is a secretive wetland bird often associated with reeds and marshes.","zh":"bittern 是一種隱蔽的濕地鳥類，常與蘆葦和沼澤相關。"},{"en":"Birdwatchers may hear a bittern’s deep call before seeing the bird.","zh":"觀鳥者可能先聽到麻鳽低沉叫聲，才看見牠。"},{"en":"If reed beds are restored, bitterns may have better places to hide and breed.","zh":"如果蘆葦床被修復，麻鳽可能有更好的藏身和繁殖地方。"},{"en":"This word refers to a rare marshland bird.","zh":"這個詞指一種珍稀沼澤鳥類。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":16},{"front":"we need to remember that","meaning":"我們需要記住","examples":[{"en":"We need to remember that wildlife can work for us.","zh":"我們需要記住，野生動植物可以為我們發揮作用。"},{"en":"We need to remember that means we should not forget an important point.","zh":"we need to remember that 指我們不應忘記某個重要重點。"},{"en":"We need to remember that students learn better when they feel safe.","zh":"我們需要記住，學生在感到安全時學得更好。"},{"en":"If cities depend on nature for clean air and drainage, we need to remember its practical value.","zh":"如果城市依靠自然獲得清潔空氣和排水，我們就需要記住它的實際價值。"},{"en":"This phrase introduces a key reminder.","zh":"這個片語引入關鍵提醒。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":17},{"front":"work with wildlife","meaning":"與野生動植物合作","examples":[{"en":"If we work with wildlife, wildlife will work for us.","zh":"如果我們與野生動植物合作，野生動植物也會為我們發揮作用。"},{"en":"To work with wildlife means to design human spaces and actions in ways that support wild plants and animals.","zh":"work with wildlife 指以支持野生植物和動物的方式設計人類空間和行動。"},{"en":"A gardener works with wildlife by planting flowers and avoiding harmful chemicals.","zh":"園丁透過種花和避免有害化學品來與野生動植物合作。"},{"en":"If cities work with wildlife, habitats can also help people by reducing floods and stress.","zh":"如果城市與野生動植物合作，棲息地也可以透過減少水浸和壓力來幫助人類。"},{"en":"This phrase suggests cooperation with nature, not domination over it.","zh":"這個片語暗示與自然合作，而不是支配自然。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":17},{"front":"work for us","meaning":"為我們發揮作用","examples":[{"en":"Wildlife can work for us if we protect it.","zh":"如果我們保護野生動植物，它們可以為我們發揮作用。"},{"en":"To work for us means to provide useful benefits or services to people.","zh":"work for us 指為人類提供有用好處或服務。"},{"en":"Trees work for us by shading streets and cleaning air.","zh":"樹木透過為街道遮蔭和清潔空氣而為我們發揮作用。"},{"en":"If wetlands reduce flooding, they are working for nearby communities.","zh":"如果濕地減少水浸，它們就是在為附近社區發揮作用。"},{"en":"This phrase shows that nature can be practically useful.","zh":"這個片語顯示自然可以有實際用途。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":17},{"front":"the very essence of","meaning":"……的真正核心","examples":[{"en":"Working with wildlife is the very essence of sustainable development.","zh":"與野生動植物合作是可持續發展的真正核心。"},{"en":"The very essence of something means its most important and central quality.","zh":"the very essence of something 指某事最重要和最核心的特質。"},{"en":"Honest feedback is the very essence of good teaching because it helps students improve.","zh":"誠實回饋是良好教學的真正核心，因為它幫助學生進步。"},{"en":"If sustainable development means meeting human needs without destroying nature, wildlife cooperation is central to it.","zh":"如果可持續發展指在不破壞自然下滿足人類需要，與野生動植物合作就是其核心。"},{"en":"This phrase strongly identifies the core meaning of an idea.","zh":"這個片語強烈指出一個概念的核心意思。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":17},{"front":"sustainable development","meaning":"可持續發展","examples":[{"en":"The writer links wildlife conservation with sustainable development.","zh":"作者把野生動植物保育與可持續發展連繫起來。"},{"en":"Sustainable development means development that meets people’s needs while protecting resources and nature for the future.","zh":"sustainable development 指滿足人們需要，同時為未來保護資源和自然的發展。"},{"en":"A city practises sustainable development when it builds housing while keeping parks, trees, and drainage wetlands.","zh":"城市在興建房屋的同時保留公園、樹木和排水濕地，就是實踐可持續發展。"},{"en":"If development destroys all habitats, it is not truly sustainable.","zh":"如果發展摧毀所有棲息地，它就不是真正可持續。"},{"en":"This phrase connects economic progress with environmental responsibility.","zh":"這個片語把經濟進步與環境責任連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":17},{"front":"agree with the information","meaning":"與資料一致","examples":[{"en":"Students decide whether the statements agree with the information in the passage.","zh":"學生判斷陳述是否與文章中的資料一致。"},{"en":"To agree with the information means to match what the passage says.","zh":"agree with the information 指與文章所說內容相符。"},{"en":"If a passage says gardens help woodland species, a matching statement agrees with the information.","zh":"如果文章說花園幫助林地物種，意思相符的陳述便與資料一致。"},{"en":"Students should compare meaning carefully, not only look for the same words.","zh":"學生應仔細比較意思，而不只是尋找相同字眼。"},{"en":"This phrase is common in TRUE, FALSE, NOT GIVEN questions.","zh":"這個片語常見於 TRUE、FALSE、NOT GIVEN 題。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":17},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A statement is false if it contradicts the information.","zh":"如果陳述與資料相矛盾，它就是錯誤的。"},{"en":"To contradict the information means to say the opposite of what the passage says.","zh":"contradict the information 指說出與文章內容相反的意思。"},{"en":"If the text says wetlands reduce flooding, saying they increase flooding contradicts the information.","zh":"如果文本說濕地減少水浸，說濕地增加水浸便與資料相矛盾。"},{"en":"Students should choose FALSE when the text clearly gives the opposite meaning.","zh":"當文本清楚給出相反意思時，學生應選 FALSE。"},{"en":"This phrase is different from not given because the passage does provide opposing evidence.","zh":"這個片語不同於沒有相關資料，因為文章確實提供了相反證據。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":17},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有相關資料，學生則寫 NOT GIVEN。"},{"en":"No information on this means the passage does not mention that point.","zh":"no information on this 指文章沒有提及該點。"},{"en":"If the passage discusses gardens but not gardeners’ ages, there is no information on this age issue.","zh":"如果文章討論花園但沒有討論園丁年齡，便沒有關於年齡問題的相關資料。"},{"en":"Students should not guess from outside knowledge when the passage gives no information.","zh":"當文章沒有提供資料時，學生不應用外部知識猜測。"},{"en":"This phrase signals that the text is silent on a detail.","zh":"這個片語表示文本對某細節沒有說明。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":17},{"front":"use of pesticides","meaning":"使用殺蟲劑","examples":[{"en":"Rural wildlife has been reduced by the use of pesticides on farms.","zh":"鄉郊野生動植物因農場使用殺蟲劑而減少。"},{"en":"Use of pesticides means applying chemicals to kill pests, often insects or weeds.","zh":"use of pesticides 指使用化學品殺死害蟲，通常是昆蟲或雜草。"},{"en":"A farmer may reduce the use of pesticides by planting crops that resist pests naturally.","zh":"農民可能透過種植天然抗害蟲的作物來減少使用殺蟲劑。"},{"en":"If pesticide use kills insects, birds may lose an important food source.","zh":"如果殺蟲劑使用殺死昆蟲，鳥類可能失去重要食物來源。"},{"en":"This phrase connects farming methods with effects on wildlife.","zh":"這個片語把農業方法與對野生動植物的影響連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":17},{"front":"link different habitats","meaning":"連接不同棲息地","examples":[{"en":"Hedges on farms used to link different habitats.","zh":"農場上的樹籬過去連接不同棲息地。"},{"en":"To link different habitats means to connect separate living spaces so species can move between them.","zh":"link different habitats 指把分開的生活空間連接起來，讓物種能在其間移動。"},{"en":"A line of trees can link a school garden with a nearby park.","zh":"一排樹可以連接學校花園和附近公園。"},{"en":"If habitats are linked, animals are less likely to become trapped in isolated areas.","zh":"如果棲息地被連接，動物較不容易被困在孤立區域。"},{"en":"This phrase explains the value of ecological connections.","zh":"這個片語解釋生態連接的價值。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":17},{"front":"planned to provide","meaning":"被規劃用來提供……","examples":[{"en":"Some environments may be planned to provide ecological corridors.","zh":"一些環境可能被規劃用來提供生態走廊。"},{"en":"Planned to provide something means designed with the purpose of giving that thing.","zh":"planned to provide something 指以提供某物為目的來設計。"},{"en":"A school library may be planned to provide quiet study spaces and group rooms.","zh":"學校圖書館可能被規劃用來提供安靜溫習空間和小組房間。"},{"en":"If parks are planned to provide wildlife corridors, paths and planting must be arranged carefully.","zh":"如果公園被規劃用來提供野生動植物走廊，路徑和種植必須仔細安排。"},{"en":"This phrase shows purpose in design.","zh":"這個片語顯示設計中的目的。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":17},{"front":"ecological corridors for wildlife","meaning":"野生動植物的生態走廊","examples":[{"en":"Ecological corridors for wildlife allow species to move through towns.","zh":"野生動植物的生態走廊讓物種穿過城鎮。"},{"en":"Ecological corridors for wildlife are connected routes that help animals and plants move between habitats.","zh":"ecological corridors for wildlife 是幫助動植物在棲息地之間移動的連接路線。"},{"en":"A riverbank with trees can be an ecological corridor for wildlife in a city.","zh":"有樹木的河岸可以成為城市中的野生動植物生態走廊。"},{"en":"If corridors are broken, animals may struggle to find food, shelter, or mates.","zh":"如果走廊被切斷，動物可能難以尋找食物、庇護或伴侶。"},{"en":"This phrase explains how urban habitats can stay connected.","zh":"這個片語解釋城市棲息地如何保持連接。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":18},{"front":"public parks and gardens","meaning":"公園和花園","examples":[{"en":"The question asks whether public parks and gardens are being expanded.","zh":"題目問公園和花園是否正在擴展。"},{"en":"Public parks and gardens are green spaces open for people to use and enjoy.","zh":"public parks and gardens 是開放給人們使用和享受的綠色空間。"},{"en":"Families may use public parks and gardens for walking, resting, or children’s play.","zh":"家庭可能使用公園和花園散步、休息或讓孩子玩耍。"},{"en":"If public parks and gardens include wildlife areas, they can benefit both people and nature.","zh":"如果公園和花園包含野生動植物區，它們可以同時有益於人和自然。"},{"en":"This phrase refers to shared green spaces, not private back gardens.","zh":"這個片語指共享綠色空間，而不是私人後花園。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":18},{"front":"be expanded to encourage","meaning":"被擴展以鼓勵……","examples":[{"en":"The question asks whether parks are being expanded to encourage wildlife.","zh":"題目問公園是否被擴展以鼓勵野生動植物。"},{"en":"To be expanded to encourage something means to be made larger in order to support or promote it.","zh":"be expanded to encourage something 指為支持或促進某事而擴大。"},{"en":"A school playground may be expanded to encourage more outdoor exercise.","zh":"學校操場可能被擴展以鼓勵更多戶外運動。"},{"en":"If parks are expanded to encourage wildlife, new planting and ponds may be added.","zh":"如果公園被擴展以鼓勵野生動植物，可能會加入新植物和池塘。"},{"en":"This phrase links growth in size with a purpose.","zh":"這個片語把面積增長與目的連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":18},{"front":"old industrial wastelands","meaning":"舊工業荒地","examples":[{"en":"Old industrial wastelands can become valuable wildlife habitats.","zh":"舊工業荒地可以變成有價值的野生動植物棲息地。"},{"en":"Old industrial wastelands are unused land left after factories, railways, or industrial sites close.","zh":"old industrial wastelands 是工廠、鐵路或工業地點關閉後留下的閒置土地。"},{"en":"An old industrial wasteland may look messy but contain wildflowers, insects, and birds.","zh":"舊工業荒地可能看似雜亂，但包含野花、昆蟲和鳥類。"},{"en":"If such land is left undisturbed, nature may slowly return.","zh":"如果這類土地不受打擾，自然可能慢慢回歸。"},{"en":"This phrase shows that neglected urban land can have ecological value.","zh":"這個片語顯示被忽略的城市土地可以有生態價值。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":18},{"front":"damage wildlife habitats","meaning":"破壞野生動植物棲息地","examples":[{"en":"The question asks whether wastelands have damaged wildlife habitats.","zh":"題目問荒地是否破壞了野生動植物棲息地。"},{"en":"To damage wildlife habitats means to harm the places where wild plants and animals live.","zh":"damage wildlife habitats 指傷害野生植物和動物生活的地方。"},{"en":"Dumping chemicals into a pond can damage wildlife habitats for frogs and insects.","zh":"把化學品倒入池塘可以破壞青蛙和昆蟲的野生動植物棲息地。"},{"en":"If habitats are damaged, species may leave, decline, or disappear.","zh":"如果棲息地受破壞，物種可能離開、衰退或消失。"},{"en":"This phrase focuses on harm to living environments.","zh":"這個片語聚焦於對生活環境的傷害。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":18},{"front":"answer the questions below","meaning":"回答以下問題","examples":[{"en":"Candidates answer the questions below using words from the passage.","zh":"考生使用文章中的字詞回答以下問題。"},{"en":"Answer the questions below means respond to the questions that follow the instruction.","zh":"answer the questions below 指回答指示後面的問題。"},{"en":"Students should answer the questions below after reading the relevant paragraph carefully.","zh":"學生應在仔細閱讀相關段落後回答以下問題。"},{"en":"If answers must come from the passage, candidates should not use their own words freely.","zh":"如果答案必須來自文章，考生不應隨意使用自己的字詞。"},{"en":"This phrase is a standard reading-test instruction.","zh":"這個片語是標準閱讀測驗指示。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":18},{"front":"NO MORE THAN THREE WORDS AND/OR A NUMBER","meaning":"不超過三個詞及／或一個數字","examples":[{"en":"Candidates choose no more than three words and/or a number from the passage.","zh":"考生從文章中選擇不超過三個詞及／或一個數字。"},{"en":"No more than three words and/or a number means the answer can contain up to three words and possibly one number.","zh":"NO MORE THAN THREE WORDS AND/OR A NUMBER 指答案最多可包含三個詞，並可能包含一個數字。"},{"en":"If the instruction says no more than three words and/or a number, writing four words can lose marks.","zh":"如果指示說不超過三個詞及／或一個數字，寫四個詞可能失分。"},{"en":"Students should copy only the necessary words from the passage.","zh":"學生應只從文章中抄取必要字詞。"},{"en":"This instruction sets a strict answer limit.","zh":"這個指示設定嚴格答案限制。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":18},{"front":"type of wildlife","meaning":"野生動植物類型","examples":[{"en":"The question asks which type of wildlife benefits most from gardens.","zh":"題目問哪一類野生動植物從花園得益最多。"},{"en":"Type of wildlife means a kind or group of wild plants or animals.","zh":"type of wildlife 指一種或一類野生植物或動物。"},{"en":"Birds, insects, mammals, and amphibians are different types of wildlife.","zh":"鳥類、昆蟲、哺乳動物和兩棲動物都是不同野生動植物類型。"},{"en":"If a garden has trees and shrubs, woodland species may be the type of wildlife that benefits most.","zh":"如果花園有樹木和灌木，林地物種可能是得益最多的野生動植物類型。"},{"en":"This phrase asks for a category, not one individual animal.","zh":"這個片語問的是類別，而不是單一個體動物。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":18},{"front":"benefit most from","meaning":"從……得益最多","examples":[{"en":"Woodland species benefit most from urban gardens.","zh":"林地物種從城市花園得益最多。"},{"en":"To benefit most from something means to gain the greatest advantage from it.","zh":"benefit most from something 指從某事獲得最大好處。"},{"en":"Students who ask questions may benefit most from small-group lessons.","zh":"會提問的學生可能從小組課中得益最多。"},{"en":"If gardens resemble woodland, woodland species benefit most from them.","zh":"如果花園像林地，林地物種便從它們得益最多。"},{"en":"This phrase compares who gains the largest benefit.","zh":"這個片語比較誰獲得最大好處。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":18},{"front":"garden plants","meaning":"花園植物","examples":[{"en":"Some garden plants can benefit birds and insects.","zh":"一些花園植物可以令鳥類和昆蟲受益。"},{"en":"Garden plants are plants grown in gardens, including flowers, shrubs, trees, and herbs.","zh":"garden plants 是花園中種植的植物，包括花卉、灌木、樹木和香草。"},{"en":"Lavender and fruit trees are garden plants that may attract bees and birds.","zh":"薰衣草和果樹是可能吸引蜜蜂和鳥類的花園植物。"},{"en":"If garden plants flower at different times, they can provide food for longer.","zh":"如果花園植物在不同時間開花，它們可以提供更長時間的食物。"},{"en":"This phrase refers to cultivated plants that may also support wildlife.","zh":"這個片語指栽培植物，而它們也可能支持野生動植物。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":18},{"front":"benefit birds and insects","meaning":"令鳥類和昆蟲受益","examples":[{"en":"Exotic flowers can benefit birds and insects by extending food supply.","zh":"外來花卉可以透過延長食物供應令鳥類和昆蟲受益。"},{"en":"To benefit birds and insects means to help them survive, feed, or breed.","zh":"benefit birds and insects 指幫助鳥類和昆蟲生存、覓食或繁殖。"},{"en":"A small pond can benefit birds and insects by providing water.","zh":"小池塘可以透過提供水源令鳥類和昆蟲受益。"},{"en":"If flowers produce nectar for longer, they benefit insects and may also attract birds.","zh":"如果花朵更長時間產生花蜜，它們令昆蟲受益，也可能吸引鳥類。"},{"en":"This phrase describes positive effects on common garden wildlife.","zh":"這個片語描述對常見花園野生動物的正面影響。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":18},{"front":"represent a threat to","meaning":"對……構成威脅","examples":[{"en":"Domestic cats represent a threat to wildlife in gardens.","zh":"家貓對花園中的野生動植物構成威脅。"},{"en":"To represent a threat to something means to be a possible danger to it.","zh":"represent a threat to something 指對某物可能造成危險。"},{"en":"Heavy traffic represents a threat to children walking to school.","zh":"繁忙交通對步行上學的孩子構成威脅。"},{"en":"If cats hunt small birds, they can represent a threat to garden wildlife.","zh":"如果貓捕獵小鳥，牠們可以對花園野生動植物構成威脅。"},{"en":"This phrase describes danger, not necessarily certain harm every time.","zh":"這個片語描述危險，而不一定每次都造成實際傷害。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":19},{"front":"urban gardens","meaning":"城市花園","examples":[{"en":"Urban gardens can provide important habitats for wildlife.","zh":"城市花園可以為野生動植物提供重要棲息地。"},{"en":"Urban gardens are gardens located in towns or cities.","zh":"urban gardens 是位於城鎮或城市中的花園。"},{"en":"An urban garden may be small but still contain flowers, shrubs, insects, and birds.","zh":"城市花園可能很小，但仍包含花朵、灌木、昆蟲和鳥類。"},{"en":"If many urban gardens are connected, they can form a habitat network.","zh":"如果許多城市花園互相連接，它們可以形成棲息地網絡。"},{"en":"This phrase shows that private green spaces can matter in cities.","zh":"這個片語顯示私人綠地在城市中也很重要。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":19},{"front":"at the last count","meaning":"在最近一次統計中","examples":[{"en":"At the last count, many bird species were spotted in urban gardens.","zh":"在最近一次統計中，許多鳥類品種在城市花園中被發現。"},{"en":"At the last count means according to the most recent count or survey.","zh":"at the last count 指根據最近一次點算或調查。"},{"en":"At the last count, the school club had forty-two members.","zh":"在最近一次統計中，學校社團有四十二名會員。"},{"en":"If species numbers rise at the last count, conservation work may be helping.","zh":"如果最近一次統計中物種數量上升，保育工作可能正在發揮作用。"},{"en":"This phrase introduces the latest available number.","zh":"這個片語引入最新可用數字。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":19},{"front":"species of bird","meaning":"鳥類品種","examples":[{"en":"The number of species of bird at garden feeders increased sharply.","zh":"花園餵飼器旁的鳥類品種數目急劇增加。"},{"en":"Species of bird means different kinds of birds.","zh":"species of bird 指不同種類的鳥。"},{"en":"A park may have several species of bird, such as sparrows, robins, and ducks.","zh":"公園可能有幾種鳥類品種，例如麻雀、知更鳥和鴨子。"},{"en":"If more species of bird visit feeders, the garden may be supporting greater diversity.","zh":"如果更多鳥類品種到訪餵飼器，花園可能支持更大多樣性。"},{"en":"This phrase counts types of birds, not individual birds.","zh":"這個片語計算鳥的種類，而不是個別鳥的數量。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":19},{"front":"be spotted in","meaning":"在……被發現","examples":[{"en":"Many bird species were spotted in urban gardens.","zh":"許多鳥類品種在城市花園中被發現。"},{"en":"To be spotted in a place means to be seen or noticed there.","zh":"be spotted in a place 指在某地被看見或注意到。"},{"en":"A rare butterfly was spotted in the school garden after new flowers were planted.","zh":"種植新花後，一隻罕見蝴蝶在學校花園被發現。"},{"en":"If more birds are spotted in gardens, people may realise urban habitats are valuable.","zh":"如果更多鳥類在花園中被發現，人們可能意識到城市棲息地有價值。"},{"en":"This phrase is often used when reporting sightings.","zh":"這個片語常用於報告目擊紀錄。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":19},{"front":"choose three letters","meaning":"選擇三個字母","examples":[{"en":"Candidates choose three letters from the options.","zh":"考生從選項中選擇三個字母。"},{"en":"Choose three letters means select three answer choices, usually marked A, B, C, and so on.","zh":"choose three letters 指選擇三個答案選項，通常以 A、B、C 等標示。"},{"en":"In a reading test, students should choose three letters only if the instruction asks for three.","zh":"在閱讀測驗中，只有指示要求三個時，學生才應選擇三個字母。"},{"en":"If students choose too many letters, even correct choices may lose marks.","zh":"如果學生選太多字母，即使有正確選項也可能失分。"},{"en":"This phrase is a common multiple-answer exam instruction.","zh":"這個片語是常見多選答案考試指示。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":19},{"front":"in which three ways","meaning":"以哪三種方式","examples":[{"en":"The question asks in which three ways wildlife habitats benefit people.","zh":"題目問野生動植物棲息地以哪三種方式令人民受益。"},{"en":"In which three ways means asking for three different methods, effects, or reasons.","zh":"in which three ways 指要求三種不同方法、效果或原因。"},{"en":"A teacher may ask in which three ways exercise helps students learn better.","zh":"老師可能問運動以哪三種方式幫助學生學得更好。"},{"en":"If habitats clean air, absorb water, and reduce stress, these are three ways they benefit people.","zh":"如果棲息地淨化空氣、吸收水分和減少壓力，這些就是三種令人受益的方式。"},{"en":"This phrase signals that several answers are needed.","zh":"這個片語表示需要多個答案。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":19},{"front":"benefit people living in","meaning":"令居於……的人受益","examples":[{"en":"Wildlife habitats can benefit people living in urban areas.","zh":"野生動植物棲息地可以令居於市區的人受益。"},{"en":"To benefit people living in a place means to help the residents of that place.","zh":"benefit people living in a place 指幫助居於某地的人。"},{"en":"A new bus route can benefit people living in a remote village.","zh":"新巴士路線可以令居於偏遠村莊的人受益。"},{"en":"If parks reduce stress and flooding, they benefit people living in the city.","zh":"如果公園減少壓力和水浸，它們便令居於城市的人受益。"},{"en":"This phrase connects an improvement with the group who gains from it.","zh":"這個片語把改善與受益群體連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":19},{"front":"urban areas","meaning":"市區","examples":[{"en":"Wildlife habitats bring benefits to people in urban areas.","zh":"野生動植物棲息地為市區居民帶來好處。"},{"en":"Urban areas are towns and cities where many people live and buildings are concentrated.","zh":"urban areas 是人口多、建築密集的城鎮和城市地區。"},{"en":"Urban areas often need parks because many residents have limited private outdoor space.","zh":"市區常需要公園，因為許多居民私人戶外空間有限。"},{"en":"If urban areas include wildlife habitats, city life may become healthier and more pleasant.","zh":"如果市區包含野生動植物棲息地，城市生活可能變得更健康和更愉快。"},{"en":"This phrase contrasts with rural areas.","zh":"這個片語與鄉郊地區相對。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":19},{"front":"make cities greener","meaning":"令城市更綠化","examples":[{"en":"Wildlife habitats can make cities greener.","zh":"野生動植物棲息地可以令城市更綠化。"},{"en":"To make cities greener means to add more plants, trees, parks, or environmentally friendly spaces.","zh":"make cities greener 指增加更多植物、樹木、公園或環保空間。"},{"en":"Planting street trees can make cities greener and more comfortable in summer.","zh":"種植街樹可以令城市更綠化，並在夏天更舒適。"},{"en":"If cities become greener, residents may enjoy cleaner air and cooler streets.","zh":"如果城市更綠化，居民可能享受更清潔空氣和較涼街道。"},{"en":"This phrase can mean both more vegetation and better environmental quality.","zh":"這個片語可以指更多植被，也可以指更好的環境質素。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":19},{"front":"improve the climate","meaning":"改善氣候","examples":[{"en":"The option asks whether habitats can improve the climate.","zh":"這個選項問棲息地是否可以改善氣候。"},{"en":"To improve the climate means to make local or wider weather conditions more comfortable or stable.","zh":"improve the climate 指令本地或更廣泛天氣條件更舒適或更穩定。"},{"en":"More trees can improve the climate of a street by giving shade and reducing heat.","zh":"更多樹木可以透過遮蔭和減熱改善街道氣候。"},{"en":"If green spaces cool urban areas, they can improve the local climate.","zh":"如果綠地為城市地區降溫，它們可以改善本地氣候。"},{"en":"This phrase can refer to broad climate effects or small local conditions.","zh":"這個片語可以指廣泛氣候效果，也可以指小型本地條件。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":19},{"front":"promote human well-being","meaning":"促進人類身心健康","examples":[{"en":"Contact with wildlife can promote human well-being.","zh":"接觸野生動植物可以促進人類身心健康。"},{"en":"To promote human well-being means to improve people’s physical, mental, or emotional health.","zh":"promote human well-being 指改善人的身體、心理或情緒健康。"},{"en":"Quiet parks can promote human well-being by giving residents a place to rest.","zh":"安靜公園可以透過給居民休息地方來促進人類身心健康。"},{"en":"If people feel calmer after seeing nature, wildlife habitats support well-being.","zh":"如果人們看見自然後感覺更平靜，野生動植物棲息地便支持身心健康。"},{"en":"This phrase focuses on human health and quality of life.","zh":"這個片語聚焦於人類健康和生活質素。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":20},{"front":"extend the flowering season","meaning":"延長開花季節","examples":[{"en":"Some plants can extend the flowering season.","zh":"一些植物可以延長開花季節。"},{"en":"To extend the flowering season means to make flowers available for a longer time of year.","zh":"extend the flowering season 指讓一年中有花可見或可用的時間更長。"},{"en":"A garden with spring bulbs and autumn flowers can extend the flowering season.","zh":"有春季球根植物和秋季花卉的花園可以延長開花季節。"},{"en":"If the flowering season is extended, insects can find nectar for longer.","zh":"如果開花季節延長，昆蟲便能更長時間找到花蜜。"},{"en":"This phrase links plant choice with food supply for wildlife.","zh":"這個片語把植物選擇與野生動植物食物供應連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":20},{"front":"absorb excess water","meaning":"吸收多餘水分","examples":[{"en":"Ponds and wetlands can absorb excess water.","zh":"池塘和濕地可以吸收多餘水分。"},{"en":"To absorb excess water means to take in extra water that might otherwise cause flooding.","zh":"absorb excess water 指吸收額外水分，否則這些水可能造成水浸。"},{"en":"A sponge absorbs excess water from a kitchen counter.","zh":"海綿吸收廚房檯面的多餘水分。"},{"en":"If wetlands absorb excess water after storms, nearby streets may stay drier.","zh":"如果濕地在暴風雨後吸收多餘水分，附近街道可能保持較乾。"},{"en":"This phrase explains how natural areas help manage rainwater.","zh":"這個片語解釋自然區域如何幫助管理雨水。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":20},{"front":"attract wildlife","meaning":"吸引野生動植物","examples":[{"en":"Urban habitats can attract wildlife.","zh":"城市棲息地可以吸引野生動植物。"},{"en":"To attract wildlife means to bring wild plants or animals to a place by providing suitable conditions.","zh":"attract wildlife 指透過提供合適條件把野生植物或動物吸引到某地。"},{"en":"A pond can attract wildlife such as frogs, birds, and dragonflies.","zh":"池塘可以吸引青蛙、鳥類和蜻蜓等野生動植物。"},{"en":"If a garden has flowers, water, and shelter, it may attract more wildlife.","zh":"如果花園有花、水和庇護，它可能吸引更多野生動植物。"},{"en":"This phrase describes making a place appealing to nature.","zh":"這個片語描述令地方對自然有吸引力。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":20},{"front":"clean the urban atmosphere","meaning":"淨化城市空氣","examples":[{"en":"The urban forest can help clean the urban atmosphere.","zh":"城市森林可以幫助淨化城市空氣。"},{"en":"To clean the urban atmosphere means to reduce pollution in city air.","zh":"clean the urban atmosphere 指減少城市空氣中的污染。"},{"en":"Street trees can help clean the urban atmosphere by trapping dust and absorbing some gases.","zh":"街樹可以透過捕捉灰塵和吸收部分氣體來幫助淨化城市空氣。"},{"en":"If the urban atmosphere is cleaner, residents may breathe more easily.","zh":"如果城市空氣更清潔，居民可能呼吸得更舒服。"},{"en":"This phrase describes an air-quality benefit of green spaces.","zh":"這個片語描述綠地對空氣質素的好處。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":20},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Candidates choose the correct letter for the final question.","zh":"考生為最後一題選出正確字母。"},{"en":"To choose the correct letter means to select the answer option that best matches the passage.","zh":"choose the correct letter 指選擇最符合文章內容的答案選項。"},{"en":"In multiple-choice reading questions, students should eliminate wrong letters first.","zh":"在閱讀多項選擇題中，學生應先排除錯誤字母。"},{"en":"If two options look similar, candidates should choose the letter supported by exact meaning.","zh":"如果兩個選項相似，考生應選出由確切意思支持的字母。"},{"en":"This phrase is a standard exam instruction.","zh":"這個片語是標準考試指示。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":20},{"front":"the writer believes that","meaning":"作者認為","examples":[{"en":"The final question asks what the writer believes about sustainable development.","zh":"最後一題問作者認為可持續發展是甚麼。"},{"en":"The writer believes that means the author’s opinion or argument is that something is true.","zh":"the writer believes that 指作者的觀點或論點是某事為真。"},{"en":"A reading question may ask what the writer believes about city planning.","zh":"閱讀題可能問作者認為城市規劃應如何。"},{"en":"If the writer believes wildlife helps people, the correct answer should reflect that view.","zh":"如果作者認為野生動植物幫助人類，正確答案應反映這個看法。"},{"en":"This phrase asks students to identify the author’s position.","zh":"這個片語要求學生識別作者立場。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":20},{"front":"be dependent on","meaning":"取決於","examples":[{"en":"Sustainable development is dependent on working with wildlife.","zh":"可持續發展取決於與野生動植物合作。"},{"en":"To be dependent on something means to rely on it or need it in order to succeed.","zh":"be dependent on something 指依賴某事或需要某事才能成功。"},{"en":"A student’s progress is often dependent on regular practice and feedback.","zh":"學生進步常取決於定期練習和回饋。"},{"en":"If sustainable development depends on nature, cities must protect habitats.","zh":"如果可持續發展取決於自然，城市就必須保護棲息地。"},{"en":"This phrase shows a necessary relationship.","zh":"這個片語顯示必要關係。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":20},{"front":"urban economic policy","meaning":"城市經濟政策","examples":[{"en":"The option mentions urban economic policy.","zh":"這個選項提到城市經濟政策。"},{"en":"Urban economic policy means city-level planning about jobs, investment, land use, services, and growth.","zh":"urban economic policy 指城市層面關於工作、投資、土地使用、服務和增長的規劃。"},{"en":"A city may include green tourism in its urban economic policy.","zh":"城市可能把綠色旅遊納入城市經濟政策。"},{"en":"If wildlife sites attract visitors and reduce flood costs, they can matter to urban economic policy.","zh":"如果野生動植物地點吸引訪客並減低水浸成本，它們就可能對城市經濟政策重要。"},{"en":"This phrase connects city development with financial and social planning.","zh":"這個片語把城市發展與財務和社會規劃連接起來。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":20},{"front":"restoration schemes","meaning":"修復計劃","examples":[{"en":"The option refers to large restoration schemes.","zh":"這個選項指大型修復計劃。"},{"en":"Restoration schemes are organised plans to repair damaged places, buildings, habitats, or ecosystems.","zh":"restoration schemes 是修復受損地方、建築、棲息地或生態系統的有組織計劃。"},{"en":"A community may start restoration schemes to clean a river and replant its banks.","zh":"社區可能開始修復計劃，清潔河流並重新種植河岸。"},{"en":"If restoration schemes succeed, old habitats can support wildlife again.","zh":"如果修復計劃成功，舊棲息地可以再次支持野生動植物。"},{"en":"This phrase focuses on bringing damaged things back to a better state.","zh":"這個片語聚焦於把受損事物帶回較好狀態。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":20},{"front":"active nature conservation","meaning":"積極自然保育","examples":[{"en":"Active nature conservation is central to sustainable development.","zh":"積極自然保育是可持續發展的核心。"},{"en":"Active nature conservation means deliberate action to protect, create, or restore habitats and species.","zh":"active nature conservation 指有意識地保護、創造或修復棲息地和物種的行動。"},{"en":"Planting native trees and cleaning ponds are forms of active nature conservation.","zh":"種植本地樹木和清潔池塘都是積極自然保育的形式。"},{"en":"If cities practise active nature conservation, wildlife and residents can both benefit.","zh":"如果城市實踐積極自然保育，野生動植物和居民都可以受益。"},{"en":"This phrase stresses action, not just appreciation of nature.","zh":"這個片語強調行動，而不只是欣賞自然。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":20},{"front":"government projects","meaning":"政府項目","examples":[{"en":"The option refers to government projects.","zh":"這個選項指政府項目。"},{"en":"Government projects are plans or programmes organised or funded by public authorities.","zh":"government projects 是由公共當局組織或資助的計劃或項目。"},{"en":"A government project may build parks, restore wetlands, or improve public transport.","zh":"政府項目可能興建公園、修復濕地或改善公共交通。"},{"en":"If government projects include wildlife goals, urban habitats may receive stronger protection.","zh":"如果政府項目包含野生動植物目標，城市棲息地可能得到更強保護。"},{"en":"This phrase refers to official public initiatives, not private hobbies.","zh":"這個片語指官方公共倡議，而不是私人興趣。"}],"source":"109 - THE WILD SIDE OF TOWN.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 110":[{"front":"change in business organisations","meaning":"商業機構的轉變","examples":[{"en":"The passage examines change in business organisations over several historical periods.","zh":"文章考察了幾個歷史時期中商業機構的轉變。"},{"en":"Change in business organisations means the way companies alter their structure, work, goals, or methods over time.","zh":"商業機構的轉變是指公司隨時間改變其架構、工作、目標或方法。"},{"en":"A shop may experience change in its organisation when it moves from face-to-face sales to online orders.","zh":"當商店由面對面銷售轉向網上訂單時，可能經歷商業機構的轉變。"},{"en":"New technology, competition, or customer demand can create major change in business organisations.","zh":"新科技、競爭或顧客需求可以帶來商業機構的重大轉變。"},{"en":"This phrase focuses on how organisations adapt, not just on one small workplace decision.","zh":"這個片語著重組織如何適應，而不只是某一個小型工作決定。"}],"source":"110 - Change in business organisations.pdf","sourcePage":1},{"front":"forces that operate to","meaning":"發揮作用去……的力量","examples":[{"en":"The forces that operate to bring about change in organisations can vary greatly.","zh":"發揮作用去帶來組織變革的力量可以非常不同。"},{"en":"Forces that operate to do something are influences that work together to make something happen.","zh":"Forces that operate to do something 是指共同作用並令某事發生的影響力。"},{"en":"Rising rent and online shopping are forces that operate to change small retail businesses.","zh":"租金上升和網上購物是發揮作用去改變小型零售企業的力量。"},{"en":"If many forces operate at the same time, managers may find change hard to control.","zh":"如果許多力量同時發揮作用，管理者可能覺得變革難以控制。"},{"en":"This phrase describes active influences behind a result.","zh":"這個片語描述結果背後的主動影響因素。"}],"source":"110 - Change in business organisations.pdf","sourcePage":1},{"front":"bring about change","meaning":"帶來改變","examples":[{"en":"Economic and social forces can bring about change in organisations.","zh":"經濟和社會力量可以為組織帶來改變。"},{"en":"To bring about change means to cause a situation, system, or behaviour to become different.","zh":"To bring about change 指令某種情況、制度或行為變得不同。"},{"en":"A new headteacher can bring about change by introducing clearer rules and better support.","zh":"新校長可以透過引入更清晰規則和更好支援來帶來改變。"},{"en":"Customer complaints may bring about change in how a restaurant trains its staff.","zh":"顧客投訴可能為餐廳培訓員工的方式帶來改變。"},{"en":"This phrase links a cause with a noticeable transformation.","zh":"這個片語把原因與明顯轉變連接起來。"}],"source":"110 - Change in business organisations.pdf","sourcePage":1},{"front":"can be thought of as","meaning":"可被視為","examples":[{"en":"The forces of change can be thought of as winds.","zh":"變革力量可被視為風。"},{"en":"Can be thought of as means can be understood or imagined in a particular way.","zh":"Can be thought of as 指可以用某種方式理解或想像。"},{"en":"A school timetable can be thought of as a map of students’ daily energy.","zh":"學校時間表可被視為學生每日精力的地圖。"},{"en":"Thinking of change as wind helps readers imagine that it can be gentle or destructive.","zh":"把變革視為風，有助讀者想像它可以溫和，也可以具破壞力。"},{"en":"This phrase introduces a comparison that makes an abstract idea easier to understand.","zh":"這個片語引入比較，使抽象想法更易理解。"}],"source":"110 - Change in business organisations.pdf","sourcePage":1},{"front":"many and varied","meaning":"多而且各式各樣","examples":[{"en":"The forces affecting organisations are many and varied.","zh":"影響組織的力量多而且各式各樣。"},{"en":"Many and varied means numerous and different in type.","zh":"Many and varied 指數量多，而且種類不同。"},{"en":"The reasons students struggle with writing are many and varied, including vocabulary, grammar, and confidence.","zh":"學生寫作困難的原因多而且各式各樣，包括詞彙、文法和信心。"},{"en":"When causes are many and varied, one simple solution is rarely enough.","zh":"當原因多而且各式各樣，單一簡單方案通常不足夠。"},{"en":"This phrase emphasises both quantity and diversity.","zh":"這個片語同時強調數量和多樣性。"}],"source":"110 - Change in business organisations.pdf","sourcePage":1},{"front":"merely disturb","meaning":"只是干擾","examples":[{"en":"Small changes may merely disturb a few existing procedures.","zh":"小變化可能只是干擾少數現有程序。"},{"en":"To merely disturb something means to interrupt or affect it slightly, without destroying it.","zh":"To merely disturb something 指只是稍微打斷或影響某事，而不是摧毀它。"},{"en":"A short power cut may merely disturb one lesson if the school has backup lighting.","zh":"如果學校有後備照明，短暫停電可能只是干擾一堂課。"},{"en":"Minor software updates may merely disturb work for a few minutes.","zh":"小型軟件更新可能只是干擾工作幾分鐘。"},{"en":"This phrase suggests limited disruption rather than serious damage.","zh":"這個片語暗示有限干擾，而不是嚴重破壞。"}],"source":"110 - Change in business organisations.pdf","sourcePage":1},{"front":"mighty howling gales","meaning":"強烈呼嘯的狂風","examples":[{"en":"Major changes can be compared to mighty howling gales.","zh":"重大變化可以被比作強烈呼嘯的狂風。"},{"en":"Mighty howling gales are very strong winds, used here as a metaphor for powerful change.","zh":"Mighty howling gales 是非常強的風，在此比喻強大的變革。"},{"en":"A sudden economic crisis can feel like mighty howling gales hitting a small business.","zh":"突然的經濟危機對小企業而言，可能像強烈呼嘯的狂風襲來。"},{"en":"When change is as strong as a gale, old routines may no longer survive.","zh":"當變革像狂風一樣強烈，舊常規可能無法繼續存在。"},{"en":"This phrase makes organisational change sound forceful and dangerous.","zh":"這個片語令組織變革聽起來有力而危險。"}],"source":"110 - Change in business organisations.pdf","sourcePage":1},{"front":"cause devastation to","meaning":"對……造成破壞","examples":[{"en":"Powerful forces can cause devastation to structures and operations.","zh":"強大力量可以對架構和運作造成破壞。"},{"en":"To cause devastation to something means to damage it severely.","zh":"To cause devastation to something 指對某物造成嚴重損害。"},{"en":"A flood can cause devastation to homes, shops, and transport systems.","zh":"水災可以對住宅、商店和交通系統造成破壞。"},{"en":"A sudden collapse in demand can cause devastation to a factory’s business model.","zh":"需求突然崩潰可以對工廠的商業模式造成破壞。"},{"en":"This phrase describes serious harm, not small inconvenience.","zh":"這個片語描述嚴重傷害，而不是小不便。"}],"source":"110 - Change in business organisations.pdf","sourcePage":1},{"front":"structures and operations","meaning":"架構和運作","examples":[{"en":"Organisational change can affect both structures and operations.","zh":"組織變革可以同時影響架構和運作。"},{"en":"Structures and operations are the way an organisation is arranged and the way it works day to day.","zh":"Structures and operations 是組織如何被安排，以及它日常如何運作。"},{"en":"A school’s structures include departments, while its operations include lessons and administration.","zh":"學校的架構包括部門，而運作包括課堂和行政。"},{"en":"If a company changes both structures and operations, employees may need new roles and routines.","zh":"如果公司同時改變架構和運作，員工可能需要新角色和新常規。"},{"en":"This phrase covers both design and daily functioning.","zh":"這個片語涵蓋設計和日常運行。"}],"source":"110 - Change in business organisations.pdf","sourcePage":1},{"front":"consequent reorientation of purpose","meaning":"隨之而來的目標重新定位","examples":[{"en":"Severe change may cause a consequent reorientation of purpose.","zh":"嚴重變化可能導致隨之而來的目標重新定位。"},{"en":"A consequent reorientation of purpose is a resulting change in what an organisation is trying to achieve.","zh":"Consequent reorientation of purpose 是由某事造成的組織目標改變。"},{"en":"A library may shift its purpose from lending books only to supporting digital learning.","zh":"圖書館可能把目標由只借書轉向支援數碼學習。"},{"en":"When old goals no longer fit new conditions, a reorientation of purpose may be necessary.","zh":"當舊目標不再適合新環境時，目標重新定位可能有必要。"},{"en":"This phrase describes a deep change in direction after pressure or disruption.","zh":"這個片語描述壓力或擾亂後出現的深層方向改變。"}],"source":"110 - Change in business organisations.pdf","sourcePage":1},{"front":"reorientation of purpose","meaning":"目標重新定位","examples":[{"en":"Some organisations need a reorientation of purpose after major change.","zh":"一些組織在重大變化後需要目標重新定位。"},{"en":"Reorientation of purpose means changing the main aim or direction of an organisation.","zh":"Reorientation of purpose 指改變組織的主要目標或方向。"},{"en":"A charity may need a reorientation of purpose if the community’s needs change.","zh":"如果社區需要改變，慈善機構可能需要目標重新定位。"},{"en":"Without reorientation, an organisation may keep solving old problems while new ones grow.","zh":"如果沒有重新定位，組織可能繼續解決舊問題，而新問題卻擴大。"},{"en":"This phrase focuses on changing the “why” behind an organisation’s work.","zh":"這個片語著重改變組織工作背後的「為何」。"}],"source":"110 - Change in business organisations.pdf","sourcePage":1},{"front":"winds die down","meaning":"風勢減弱；變革力量減退","examples":[{"en":"Sometimes the winds of change die down.","zh":"有時變革之風會減弱。"},{"en":"If winds die down, they become weaker or calmer; metaphorically, pressure for change becomes less intense.","zh":"If winds die down，意思是風變弱或平靜；作比喻時指變革壓力減弱。"},{"en":"After exam season, the pressure in a school may die down and routines return.","zh":"考試季後，學校壓力可能減退，常規恢復。"},{"en":"When market uncertainty dies down, companies may stop making emergency changes.","zh":"當市場不確定性減退，公司可能停止作緊急改變。"},{"en":"This phrase suggests a return to calmer conditions.","zh":"這個片語暗示情況回到較平靜狀態。"}],"source":"110 - Change in business organisations.pdf","sourcePage":2},{"front":"periods of relative calm","meaning":"相對平靜的時期","examples":[{"en":"Organisations may experience periods of relative calm.","zh":"組織可能經歷相對平靜的時期。"},{"en":"Periods of relative calm are times when change or pressure is lower than usual.","zh":"Periods of relative calm 是變化或壓力比平時較低的時期。"},{"en":"A hospital may enjoy a period of relative calm after flu season ends.","zh":"流感季結束後，醫院可能有一段相對平靜的時期。"},{"en":"During relative calm, managers can review systems instead of only reacting to crises.","zh":"在相對平靜時期，管理者可以檢討制度，而不是只應付危機。"},{"en":"This phrase does not mean no change at all, only less disruption.","zh":"這個片語不是指完全沒有變化，而只是干擾較少。"}],"source":"110 - Change in business organisations.pdf","sourcePage":2},{"front":"organisational stability","meaning":"組織穩定","examples":[{"en":"The agricultural age was a period of relative organisational stability.","zh":"農業時代是一個相對組織穩定的時期。"},{"en":"Organisational stability means a situation in which structures, routines, and roles change little over time.","zh":"Organisational stability 指架構、常規和角色隨時間變化很少的情況。"},{"en":"A school has organisational stability when teachers, schedules, and rules remain steady for years.","zh":"當老師、時間表和規則多年保持穩定，學校便有組織穩定。"},{"en":"Stability can make planning easier, but it may also make people slow to adapt.","zh":"穩定可以令規劃更容易，但也可能令人適應得較慢。"},{"en":"This phrase describes steadiness inside an organisation.","zh":"這個片語描述組織內部的穩定性。"}],"source":"110 - Change in business organisations.pdf","sourcePage":2},{"front":"such a period","meaning":"這樣的一段時期","examples":[{"en":"Such a period of stability existed during the agricultural age.","zh":"這樣的一段穩定時期存在於農業時代。"},{"en":"Such a period means a period like the one just described.","zh":"Such a period 指像剛才描述的那種時期。"},{"en":"After several busy months, a company may finally enter such a period of calm.","zh":"經過幾個繁忙月份後，公司可能終於進入這樣一段平靜時期。"},{"en":"Writers use this phrase to refer back to an earlier description without repeating it.","zh":"作者使用這個片語來指回早前描述，而不用重複。"},{"en":"This phrase helps connect sentences smoothly.","zh":"這個片語有助句子自然連接。"}],"source":"110 - Change in business organisations.pdf","sourcePage":2},{"front":"the agricultural age","meaning":"農業時代","examples":[{"en":"The agricultural age prevailed in Europe until the early 1700s.","zh":"農業時代在歐洲盛行至十八世紀初。"},{"en":"The agricultural age was a period when farming was the main basis of economic and social life.","zh":"農業時代是農業作為經濟和社會生活主要基礎的時期。"},{"en":"In the agricultural age, many families lived near the land they worked.","zh":"在農業時代，許多家庭住在他們耕作的土地附近。"},{"en":"Because farming followed seasons, work patterns were often easier to predict.","zh":"因為農業跟隨季節，工作模式通常較容易預測。"},{"en":"This phrase contrasts farming-based society with later industrial society.","zh":"這個片語把以農業為本的社會與後來的工業社會作對比。"}],"source":"110 - Change in business organisations.pdf","sourcePage":2},{"front":"maintain that","meaning":"主張；認為","examples":[{"en":"Goodman maintains that the agricultural age lasted until the early 1700s.","zh":"Goodman主張農業時代持續到十八世紀初。"},{"en":"To maintain that something is true means to state or argue it firmly.","zh":"To maintain that something is true 指堅定地陳述或主張某事是真的。"},{"en":"A teacher may maintain that daily reading is more useful than last-minute revision.","zh":"老師可能主張每日閱讀比臨急溫習更有用。"},{"en":"Researchers maintain a claim when they believe the evidence supports it.","zh":"當研究人員相信證據支持某說法，他們便會維持該主張。"},{"en":"This phrase introduces a person’s stated view.","zh":"這個片語引出某人的明確觀點。"}],"source":"110 - Change in business organisations.pdf","sourcePage":2},{"front":"prevail in","meaning":"盛行於","examples":[{"en":"The agricultural age prevailed in Europe for many centuries.","zh":"農業時代在歐洲盛行了許多世紀。"},{"en":"To prevail in a place or period means to be common, dominant, or widely accepted there.","zh":"To prevail in a place or period 指在某地或某時期常見、占主導或被廣泛接受。"},{"en":"A quiet atmosphere may prevail in a library during exam season.","zh":"考試季期間，圖書館可能盛行安靜氣氛。"},{"en":"If one business model prevails, most companies may organise themselves around it.","zh":"如果某種商業模式盛行，大多數公司可能圍繞它組織自己。"},{"en":"This phrase describes something that is widespread or dominant.","zh":"這個片語描述某事廣泛存在或占主導地位。"}],"source":"110 - Change in business organisations.pdf","sourcePage":2},{"front":"western societies as a whole","meaning":"整個西方社會","examples":[{"en":"The agricultural age affected Western societies as a whole.","zh":"農業時代影響了整個西方社會。"},{"en":"Western societies as a whole means Western societies considered together, not one country or group only.","zh":"Western societies as a whole 指把西方社會整體考慮，而不是只看一個國家或群體。"},{"en":"A major technology can change schools, workplaces, and families in society as a whole.","zh":"重大科技可以改變整個社會中的學校、工作場所和家庭。"},{"en":"Looking at societies as a whole helps readers see broad historical patterns.","zh":"從整體社會角度看，有助讀者看見廣泛歷史模式。"},{"en":"This phrase gives a wide social perspective.","zh":"這個片語提供寬廣的社會視角。"}],"source":"110 - Change in business organisations.pdf","sourcePage":2},{"front":"until the early 1700s","meaning":"直至十八世紀初","examples":[{"en":"The agricultural age lasted until the early 1700s.","zh":"農業時代持續直至十八世紀初。"},{"en":"Until the early 1700s means up to the beginning years of the eighteenth century.","zh":"Until the early 1700s 指直到十八世紀最初的年份。"},{"en":"Some old farming methods remained common until the early 1700s in rural areas.","zh":"一些舊農耕方法在農村地區一直常見直至十八世紀初。"},{"en":"The phrase marks the end point of a historical period.","zh":"這個片語標示歷史時期的終點。"},{"en":"It helps readers place organisational change on a timeline.","zh":"它幫助讀者把組織變革放在時間線上。"}],"source":"110 - Change in business organisations.pdf","sourcePage":2},{"front":"wealth was created","meaning":"財富被創造","examples":[{"en":"Wealth was created in the context of an agriculturally based society.","zh":"財富是在以農業為本的社會背景下被創造出來的。"},{"en":"Wealth was created means economic value or income was produced.","zh":"Wealth was created 指經濟價值或收入被生產出來。"},{"en":"In a fishing village, wealth may be created through catching, selling, and preserving fish.","zh":"在漁村，財富可能透過捕魚、售賣和保存魚類而被創造。"},{"en":"In an agricultural society, wealth was created mainly through land, crops, and livestock.","zh":"在農業社會中，財富主要透過土地、農作物和牲畜被創造。"},{"en":"This phrase describes how a society produces economic value.","zh":"這個片語描述社會如何產生經濟價值。"}],"source":"110 - Change in business organisations.pdf","sourcePage":2},{"front":"in the context of","meaning":"在……的背景下","examples":[{"en":"Wealth was created in the context of an agricultural society.","zh":"財富是在農業社會的背景下被創造出來的。"},{"en":"In the context of means within the situation, background, or conditions of something.","zh":"In the context of 指在某事的情況、背景或條件之中。"},{"en":"A student’s behaviour should be understood in the context of family stress and school pressure.","zh":"學生行為應在家庭壓力和學校壓力的背景下理解。"},{"en":"Business decisions make more sense when viewed in the context of their time.","zh":"商業決定放在其時代背景下看會更合理。"},{"en":"This phrase helps explain the background around an idea.","zh":"這個片語幫助解釋某想法周圍的背景。"}],"source":"110 - Change in business organisations.pdf","sourcePage":2},{"front":"agriculturally based society","meaning":"以農業為本的社會","examples":[{"en":"The agricultural age was an agriculturally based society.","zh":"農業時代是一個以農業為本的社會。"},{"en":"An agriculturally based society is one whose economy and daily life depend mainly on farming.","zh":"Agriculturally based society 是經濟和日常生活主要依賴農業的社會。"},{"en":"In an agriculturally based society, the weather can affect income, food, and work.","zh":"在以農業為本的社會中，天氣可以影響收入、食物和工作。"},{"en":"Such societies often organise life around planting, harvest, and local markets.","zh":"這類社會常圍繞播種、收成和本地市場組織生活。"},{"en":"This phrase describes a society built around land and farming.","zh":"這個片語描述建基於土地和農業的社會。"}],"source":"110 - Change in business organisations.pdf","sourcePage":3},{"front":"influenced mainly by","meaning":"主要受……影響","examples":[{"en":"Economic activity was influenced mainly by local markets and the weather.","zh":"經濟活動主要受本地市場和天氣影響。"},{"en":"Influenced mainly by means affected most strongly by particular factors.","zh":"Influenced mainly by 指受到某些因素最強烈影響。"},{"en":"A student’s choice of subjects may be influenced mainly by interest and future plans.","zh":"學生選科可能主要受興趣和未來計劃影響。"},{"en":"If farming is influenced mainly by weather, people cannot fully control production.","zh":"如果農業主要受天氣影響，人們便無法完全控制生產。"},{"en":"This phrase identifies the strongest influences on a situation.","zh":"這個片語指出某情況最主要的影響因素。"}],"source":"110 - Change in business organisations.pdf","sourcePage":3},{"front":"local markets","meaning":"本地市場","examples":[{"en":"Local markets influenced agricultural societies.","zh":"本地市場影響了農業社會。"},{"en":"Local markets are nearby places or systems where people buy and sell goods and labour.","zh":"Local markets 是附近買賣商品和勞動力的地方或系統。"},{"en":"A farmer may sell vegetables in local markets rather than sending them abroad.","zh":"農夫可能在本地市場售賣蔬菜，而不是送往海外。"},{"en":"If local markets are small, producers may have limited customers.","zh":"如果本地市場很小，生產者可能顧客有限。"},{"en":"This phrase describes economic exchange close to home.","zh":"這個片語描述靠近家園的經濟交換。"}],"source":"110 - Change in business organisations.pdf","sourcePage":3},{"front":"customer and labour markets","meaning":"顧客和勞動市場","examples":[{"en":"Both customer and labour markets were mainly local.","zh":"顧客和勞動市場都主要是本地的。"},{"en":"Customer and labour markets are the markets for buyers and for workers.","zh":"Customer and labour markets 是買家市場和工人市場。"},{"en":"A small town may have local customer markets and labour markets because people buy and work nearby.","zh":"小鎮可能有本地顧客和勞動市場，因為人們在附近購買和工作。"},{"en":"If these markets are local, businesses depend heavily on nearby people.","zh":"如果這些市場是本地的，企業會非常依賴附近的人。"},{"en":"This phrase links demand for products with supply of workers.","zh":"這個片語把產品需求與工人供應連接起來。"}],"source":"110 - Change in business organisations.pdf","sourcePage":3},{"front":"factors outside people’s control","meaning":"人們無法控制的因素","examples":[{"en":"The weather was one of the factors outside people’s control.","zh":"天氣是人們無法控制的因素之一。"},{"en":"Factors outside people’s control are things people cannot directly manage or change.","zh":"Factors outside people’s control 是人們不能直接管理或改變的事情。"},{"en":"A family picnic may be affected by rain, a factor outside people’s control.","zh":"家庭野餐可能受下雨影響，而下雨是人們無法控制的因素。"},{"en":"When business depends on uncontrollable factors, planning becomes more difficult.","zh":"當企業依賴不可控制因素，規劃會變得更困難。"},{"en":"This phrase explains why some risks cannot simply be managed away.","zh":"這個片語解釋為何有些風險不能簡單地被管理掉。"}],"source":"110 - Change in business organisations.pdf","sourcePage":3},{"front":"predict something fairly well","meaning":"相當準確地預測……","examples":[{"en":"People could predict the cycle of activities fairly well.","zh":"人們可以相當準確地預測活動週期。"},{"en":"To predict something fairly well means to estimate what will happen with reasonable accuracy.","zh":"To predict something fairly well 指以合理準確度估計會發生甚麼。"},{"en":"A teacher can predict exam pressure fairly well because it rises before every test.","zh":"老師可以相當準確地預測考試壓力，因為它每次考試前都會上升。"},{"en":"Farmers could predict seasonal work fairly well because planting and harvest followed cycles.","zh":"農民可以相當準確地預測季節性工作，因為播種和收成遵循週期。"},{"en":"This phrase suggests useful but not perfect prediction.","zh":"這個片語暗示有用但並非完美的預測。"}],"source":"110 - Change in business organisations.pdf","sourcePage":3},{"front":"the cycle of activities","meaning":"活動週期","examples":[{"en":"People understood the cycle of activities required to maintain life.","zh":"人們了解維持生活所需的活動週期。"},{"en":"The cycle of activities is a repeated pattern of tasks that happens again and again.","zh":"The cycle of activities 是反覆出現的一系列任務模式。"},{"en":"A school year has a cycle of activities, including lessons, exams, holidays, and reports.","zh":"學年有活動週期，包括上課、考試、假期和成績報告。"},{"en":"Farming communities followed cycles of planting, growing, harvesting, and storing food.","zh":"農業社區遵循播種、生長、收成和儲存食物的週期。"},{"en":"This phrase describes repeated work patterns over time.","zh":"這個片語描述隨時間重複出現的工作模式。"}],"source":"110 - Change in business organisations.pdf","sourcePage":3},{"front":"required to maintain life","meaning":"維持生活所需的","examples":[{"en":"Farming communities followed activities required to maintain life.","zh":"農業社區遵循維持生活所需的活動。"},{"en":"Required to maintain life means necessary for survival and basic daily living.","zh":"Required to maintain life 指生存和基本日常生活所必需的。"},{"en":"Clean water, food, shelter, and rest are required to maintain life.","zh":"清潔食水、食物、住所和休息都是維持生活所需的。"},{"en":"If work produces only what is required to maintain life, there may be little extra wealth.","zh":"如果工作只生產維持生活所需的東西，額外財富可能很少。"},{"en":"This phrase points to basic needs rather than luxury.","zh":"這個片語指基本需要，而不是奢侈品。"}],"source":"110 - Change in business organisations.pdf","sourcePage":3},{"front":"little more than","meaning":"只是略高於……","examples":[{"en":"Life was often at little more than subsistence level.","zh":"生活往往只是略高於勉強維生水平。"},{"en":"Little more than means only slightly above a particular level or amount.","zh":"Little more than 指只是比某水平或數量稍微多一點。"},{"en":"After paying rent, a worker may have little more than enough money for food.","zh":"付完租金後，工人可能只剩略高於買食物所需的金錢。"},{"en":"If a family earns little more than survival income, saving becomes difficult.","zh":"如果家庭收入只是略高於生存收入，儲蓄會變得困難。"},{"en":"This phrase emphasises how low or limited something is.","zh":"這個片語強調某事很低或很有限。"}],"source":"110 - Change in business organisations.pdf","sourcePage":3},{"front":"subsistence level","meaning":"勉強維生水平","examples":[{"en":"Many people lived at little more than subsistence level.","zh":"許多人生活只是略高於勉強維生水平。"},{"en":"Subsistence level is the minimum level needed to survive with basic food, shelter, and clothing.","zh":"Subsistence level 是生存所需的最低水平，包括基本食物、住所和衣物。"},{"en":"A family living at subsistence level has little money for education, travel, or emergencies.","zh":"生活在勉強維生水平的家庭，幾乎沒有錢用於教育、旅遊或緊急情況。"},{"en":"If wages fall to subsistence level, people may work only to stay alive.","zh":"如果工資跌至勉強維生水平，人們可能只是為了活下去而工作。"},{"en":"This phrase describes survival, not comfort.","zh":"這個片語描述生存，而不是舒適。"}],"source":"110 - Change in business organisations.pdf","sourcePage":3},{"front":"maintain the metaphor","meaning":"延續比喻","examples":[{"en":"The writer maintains the meteorological metaphor in the next paragraph.","zh":"作者在下一段延續氣象比喻。"},{"en":"To maintain the metaphor means to continue using the same comparison or image.","zh":"To maintain the metaphor 指繼續使用同一比較或形象。"},{"en":"If a teacher compares learning to building a house, she maintains the metaphor by later discussing foundations.","zh":"如果老師把學習比作建屋，她之後談地基就是延續比喻。"},{"en":"Maintaining a metaphor can help readers follow a difficult idea more easily.","zh":"延續比喻可以幫助讀者更容易跟上困難想法。"},{"en":"This phrase describes a writing technique, not a physical action.","zh":"這個片語描述寫作技巧，而不是實體動作。"}],"source":"110 - Change in business organisations.pdf","sourcePage":3},{"front":"meteorological metaphor","meaning":"氣象比喻","examples":[{"en":"The passage uses a meteorological metaphor to describe organisational change.","zh":"文章使用氣象比喻來描述組織變革。"},{"en":"A meteorological metaphor uses weather images to explain another idea.","zh":"Meteorological metaphor 是使用天氣意象來解釋另一個想法的比喻。"},{"en":"Saying “storms of change” is a meteorological metaphor because it compares change to weather.","zh":"說「變革風暴」是氣象比喻，因為它把變革比作天氣。"},{"en":"Weather metaphors help show that change can be gentle, sudden, or destructive.","zh":"天氣比喻有助顯示變革可以溫和、突然或具破壞性。"},{"en":"This phrase describes figurative language based on climate or weather.","zh":"這個片語描述基於氣候或天氣的比喻語言。"}],"source":"110 - Change in business organisations.pdf","sourcePage":4},{"front":"stronger winds of change","meaning":"更強大的變革之風","examples":[{"en":"Stronger winds of change brought in the Industrial Revolution.","zh":"更強大的變革之風帶來了工業革命。"},{"en":"Stronger winds of change means more powerful forces causing transformation.","zh":"Stronger winds of change 指造成轉型的力量更強大。"},{"en":"The internet created stronger winds of change for newspapers and shops.","zh":"互聯網為報紙和商店帶來更強大的變革之風。"},{"en":"When stronger winds of change arrive, old systems may be replaced quickly.","zh":"當更強大的變革之風來臨，舊制度可能迅速被取代。"},{"en":"This phrase extends the weather metaphor for major social or economic shifts.","zh":"這個片語延續天氣比喻，用於重大社會或經濟轉變。"}],"source":"110 - Change in business organisations.pdf","sourcePage":4},{"front":"bring in","meaning":"帶來；引入","examples":[{"en":"Stronger forces brought in the Industrial Revolution.","zh":"更強力量帶來了工業革命。"},{"en":"To bring in something means to introduce it or cause it to begin.","zh":"To bring in something 指引入某事或令它開始。"},{"en":"A new principal may bring in a different homework policy.","zh":"新校長可能引入不同功課政策。"},{"en":"New machines brought in faster production and changed how people worked.","zh":"新機器帶來更快生產，並改變人們工作方式。"},{"en":"This phrase connects a force or decision with a new period or system.","zh":"這個片語把力量或決定與新時期或制度連接起來。"}],"source":"110 - Change in business organisations.pdf","sourcePage":4},{"front":"the Industrial Revolution","meaning":"工業革命","examples":[{"en":"The Industrial Revolution changed the structure of organisations.","zh":"工業革命改變了組織架構。"},{"en":"The Industrial Revolution was a period when machines, factories, and new production methods transformed society.","zh":"工業革命是機器、工廠和新生產方法改造社會的時期。"},{"en":"During the Industrial Revolution, many workers moved from farms to factories.","zh":"在工業革命期間，許多工人從農場移到工廠。"},{"en":"The Industrial Revolution created larger organisations with stricter management structures.","zh":"工業革命創造了更大型、管理架構更嚴格的組織。"},{"en":"This phrase marks a major shift from farming to industrial production.","zh":"這個片語標誌由農業轉向工業生產的重大轉變。"}],"source":"110 - Change in business organisations.pdf","sourcePage":4},{"front":"the industrial age","meaning":"工業時代","examples":[{"en":"The industrial age lasted until around 1945.","zh":"工業時代持續到約1945年。"},{"en":"The industrial age was a period when factory production and mechanised industry dominated economic life.","zh":"工業時代是工廠生產和機械化工業主導經濟生活的時期。"},{"en":"In the industrial age, organisations often focused on producing more goods efficiently.","zh":"在工業時代，組織常集中於有效率地生產更多商品。"},{"en":"Standardised work and strict hierarchy became common during this period.","zh":"標準化工作和嚴格等級制度在這時期變得常見。"},{"en":"This phrase contrasts with both the agricultural age and the post-industrial age.","zh":"這個片語與農業時代和後工業時代形成對比。"}],"source":"110 - Change in business organisations.pdf","sourcePage":4},{"front":"according to","meaning":"根據","examples":[{"en":"According to Goodman, the industrial age lasted for a long time.","zh":"根據Goodman，工業時代持續了很長時間。"},{"en":"According to means based on what a person, text, or source says.","zh":"According to 指根據某人、文本或來源所說。"},{"en":"According to the timetable, the meeting starts at nine.","zh":"根據時間表，會議九點開始。"},{"en":"Writers use this phrase to show where information or an opinion comes from.","zh":"作者使用這個片語來顯示資訊或觀點來自哪裡。"},{"en":"This phrase introduces a source, not necessarily a universal fact.","zh":"這個片語引出來源，而不一定是普遍事實。"}],"source":"110 - Change in business organisations.pdf","sourcePage":4},{"front":"last for a long time","meaning":"持續很長時間","examples":[{"en":"The industrial age lasted for a long time.","zh":"工業時代持續了很長時間。"},{"en":"To last for a long time means to continue for many years or a long period.","zh":"To last for a long time 指持續多年或一段很長時間。"},{"en":"A school tradition can last for a long time if students and teachers value it.","zh":"如果學生和老師重視某學校傳統，它可以持續很長時間。"},{"en":"When a business system lasts for a long time, people may treat it as normal.","zh":"當商業制度持續很長時間，人們可能把它視為正常。"},{"en":"This phrase emphasises duration.","zh":"這個片語強調時間長度。"}],"source":"110 - Change in business organisations.pdf","sourcePage":4},{"front":"until around 1945","meaning":"直至約1945年","examples":[{"en":"The industrial age lasted until around 1945.","zh":"工業時代持續直至約1945年。"},{"en":"Until around 1945 means up to approximately the year 1945.","zh":"Until around 1945 指直到大約1945年。"},{"en":"Some wartime controls continued until around 1945, when the war ended.","zh":"一些戰時管制持續到約1945年，即戰爭結束時。"},{"en":"The word “around” shows the date is approximate rather than exact.","zh":"“Around” 顯示日期是近似，而不是精確。"},{"en":"This phrase marks a rough historical endpoint.","zh":"這個片語標示粗略歷史終點。"}],"source":"110 - Change in business organisations.pdf","sourcePage":4},{"front":"be characterised by","meaning":"以……為特徵","examples":[{"en":"The industrial age was characterised by inventions and innovations.","zh":"工業時代以發明和創新為特徵。"},{"en":"To be characterised by something means to have it as a typical or defining feature.","zh":"To be characterised by something 指以某事作為典型或定義性特徵。"},{"en":"A good classroom may be characterised by trust, practice, and clear feedback.","zh":"好課室可能以信任、練習和清晰回饋為特徵。"},{"en":"A period characterised by rapid invention often changes how people work.","zh":"以快速發明為特徵的時期，常會改變人們工作方式。"},{"en":"This phrase identifies the main features of a thing or period.","zh":"這個片語指出某事或某時期的主要特徵。"}],"source":"110 - Change in business organisations.pdf","sourcePage":4},{"front":"a series of","meaning":"一連串","examples":[{"en":"The period was characterised by a series of inventions and innovations.","zh":"這個時期以一連串發明與創新為特徵。"},{"en":"A series of something means several things of the same kind happening one after another.","zh":"A series of something 指同類事物一個接一個發生。"},{"en":"A student may improve after a series of short practice tests.","zh":"學生在一連串短練習測驗後可能進步。"},{"en":"A series of small mistakes can eventually cause a major problem.","zh":"一連串小錯誤最終可以造成重大問題。"},{"en":"This phrase shows repeated or connected events.","zh":"這個片語顯示重複或相關事件。"}],"source":"110 - Change in business organisations.pdf","sourcePage":4},{"front":"inventions and innovations","meaning":"發明與創新","examples":[{"en":"Inventions and innovations transformed production.","zh":"發明與創新改變了生產。"},{"en":"Inventions and innovations are new tools, methods, or ideas that change how things are done.","zh":"Inventions and innovations 是改變做事方式的新工具、方法或想法。"},{"en":"The smartphone was an innovation that changed communication, shopping, and work.","zh":"智能手機是一項改變溝通、購物和工作的創新。"},{"en":"New machines can increase production and reduce the number of workers needed for some tasks.","zh":"新機器可以增加產量，並減少某些任務所需工人數量。"},{"en":"This phrase links creativity with practical change.","zh":"這個片語把創意與實際改變連接起來。"}],"source":"110 - Change in business organisations.pdf","sourcePage":4},{"front":"reduce the number of people needed to","meaning":"減少需要……的人數","examples":[{"en":"New machines reduced the number of people needed to work the land.","zh":"新機器減少了耕作土地所需的人數。"},{"en":"To reduce the number of people needed to do something means fewer workers are required for that task.","zh":"To reduce the number of people needed to do something 指完成某任務所需工人較少。"},{"en":"Self-checkout machines can reduce the number of staff needed to handle simple purchases.","zh":"自助收銀機可以減少處理簡單購物所需的員工人數。"},{"en":"When technology reduces labour needs, workers may move into different jobs.","zh":"當科技減少勞動需求，工人可能轉到不同工作。"},{"en":"This phrase describes how tools can change employment patterns.","zh":"這個片語描述工具如何改變就業模式。"}],"source":"110 - Change in business organisations.pdf","sourcePage":5},{"front":"work the land","meaning":"耕作土地","examples":[{"en":"Fewer people were needed to work the land.","zh":"耕作土地所需的人數減少了。"},{"en":"To work the land means to farm it by planting, caring for, and harvesting crops.","zh":"To work the land 指透過播種、照料和收割農作物來耕作土地。"},{"en":"A farming family may work the land from early morning during harvest season.","zh":"在收成季節，農家可能清晨開始耕作土地。"},{"en":"Machines can help people work the land faster and with less physical labour.","zh":"機器可以幫助人更快、更少體力地耕作土地。"},{"en":"This phrase describes agricultural work directly connected to soil and crops.","zh":"這個片語描述直接與泥土和農作物相關的農業工作。"}],"source":"110 - Change in business organisations.pdf","sourcePage":5},{"front":"in turn","meaning":"繼而；反過來","examples":[{"en":"These innovations, in turn, provided new means of production.","zh":"這些創新繼而提供了新的生產方式。"},{"en":"In turn means as the next result in a chain of events.","zh":"In turn 指作為一連串事件中的下一個結果。"},{"en":"Better sleep improves attention, which in turn helps students learn faster.","zh":"更好睡眠改善專注力，繼而幫助學生學得更快。"},{"en":"New machines reduced farm labour, which in turn supplied workers for factories.","zh":"新機器減少農業勞動需求，繼而為工廠提供工人。"},{"en":"This phrase connects one result to the next.","zh":"這個片語把一個結果連接到下一個結果。"}],"source":"110 - Change in business organisations.pdf","sourcePage":5},{"front":"means of production","meaning":"生產方式；生產手段","examples":[{"en":"Industry provided the means of production for many goods.","zh":"工業為許多商品提供了生產方式。"},{"en":"Means of production are the tools, machines, factories, land, and systems used to produce goods.","zh":"Means of production 是用來生產商品的工具、機器、工廠、土地和制度。"},{"en":"A bakery’s ovens, mixers, and workers form part of its means of production.","zh":"麵包店的焗爐、攪拌機和工人構成其生產手段的一部分。"},{"en":"When means of production change, the way people work also changes.","zh":"當生產方式改變，人們的工作方式也會改變。"},{"en":"This phrase explains what makes production possible.","zh":"這個片語解釋甚麼令生產成為可能。"}],"source":"110 - Change in business organisations.pdf","sourcePage":5},{"front":"hitherto rarely obtainable goods","meaning":"以往難以取得的貨品","examples":[{"en":"Factories produced goods that were hitherto rarely obtainable.","zh":"工廠生產了以往難以取得的貨品。"},{"en":"Hitherto rarely obtainable goods are products that had previously been difficult to get.","zh":"Hitherto rarely obtainable goods 是之前很難取得的產品。"},{"en":"Before mass production, some household items were hitherto rarely obtainable for poor families.","zh":"在大規模生產前，一些家居用品對貧困家庭而言以往難以取得。"},{"en":"When factories made goods cheaply, more people could buy items once reserved for the wealthy.","zh":"當工廠廉價製造商品，更多人能購買過去只屬富人的物品。"},{"en":"This phrase contrasts past scarcity with later availability.","zh":"這個片語對比過去稀缺與後來可得。"}],"source":"110 - Change in business organisations.pdf","sourcePage":5},{"front":"ever increasing numbers","meaning":"不斷增加的數量","examples":[{"en":"Organisations supplied goods in ever increasing numbers.","zh":"組織以不斷增加的數量供應商品。"},{"en":"Ever increasing numbers means quantities that keep growing over time.","zh":"Ever increasing numbers 指數量隨時間持續增長。"},{"en":"A popular school may receive applications in ever increasing numbers.","zh":"受歡迎學校可能收到不斷增加的申請數量。"},{"en":"If goods are produced in ever increasing numbers, supply may eventually exceed demand.","zh":"如果商品以不斷增加的數量被生產，供應最終可能超過需求。"},{"en":"This phrase emphasises continuous growth.","zh":"這個片語強調持續增長。"}],"source":"110 - Change in business organisations.pdf","sourcePage":5},{"front":"to a large extent","meaning":"在很大程度上","examples":[{"en":"To a large extent, demand and supply were predictable.","zh":"在很大程度上，需求與供應是可預測的。"},{"en":"To a large extent means mostly, but not completely.","zh":"To a large extent 指大多數情況如此，但不是完全如此。"},{"en":"A student’s success depends to a large extent on regular practice and feedback.","zh":"學生成功在很大程度上取決於定期練習和回饋。"},{"en":"If demand is predictable to a large extent, companies can plan production more easily.","zh":"如果需求在很大程度上可預測，公司可以更容易規劃生產。"},{"en":"This phrase allows a strong statement while leaving room for exceptions.","zh":"這個片語容許強烈說法，同時保留例外空間。"}],"source":"110 - Change in business organisations.pdf","sourcePage":5},{"front":"demand and supply","meaning":"需求與供應","examples":[{"en":"Demand and supply were more predictable in the industrial age.","zh":"需求與供應在工業時代較可預測。"},{"en":"Demand and supply are the amount people want to buy and the amount producers can offer.","zh":"Demand and supply 是人們想購買的數量和生產者能提供的數量。"},{"en":"If demand for masks rises suddenly but supply is low, prices may increase.","zh":"如果口罩需求突然上升但供應低，價格可能上升。"},{"en":"When supply catches up with demand, customers may have more choice.","zh":"當供應追上需求，顧客可能有更多選擇。"},{"en":"This phrase is central to understanding markets.","zh":"這個片語是理解市場的核心概念。"}],"source":"110 - Change in business organisations.pdf","sourcePage":5},{"front":"structure their organisations","meaning":"建構其組織架構","examples":[{"en":"Companies could structure their organisations in a mechanistic way.","zh":"公司可以以機械式方式建構其組織架構。"},{"en":"To structure their organisations means to arrange roles, departments, rules, and lines of authority.","zh":"To structure their organisations 指安排角色、部門、規則和權力線。"},{"en":"A school may structure its organisation into subject departments and year teams.","zh":"學校可能把其組織架構建構為科目部門和年級團隊。"},{"en":"If managers structure organisations too rigidly, workers may have little flexibility.","zh":"如果管理者把組織建構得太僵硬，工人可能幾乎沒有彈性。"},{"en":"This phrase describes how an organisation is designed internally.","zh":"這個片語描述組織內部如何設計。"}],"source":"110 - Change in business organisations.pdf","sourcePage":5},{"front":"along mechanistic lines","meaning":"按機械式方式","examples":[{"en":"Companies structured their organisations along mechanistic lines.","zh":"公司按機械式方式建構其組織架構。"},{"en":"Along mechanistic lines means organised like a machine, with fixed parts, clear rules, and strict control.","zh":"Along mechanistic lines 指像機器一樣組織，有固定部分、清晰規則和嚴格控制。"},{"en":"A call centre may be organised along mechanistic lines if every conversation follows a script.","zh":"如果每段對話都跟隨腳本，電話中心可能按機械式方式運作。"},{"en":"Mechanistic structures can improve efficiency but may reduce creativity.","zh":"機械式架構可以提高效率，但可能減少創意。"},{"en":"This phrase describes a rigid, machine-like approach to organisation.","zh":"這個片語描述僵硬、像機器一樣的組織方式。"}],"source":"110 - Change in business organisations.pdf","sourcePage":5},{"front":"strict hierarchical structures","meaning":"嚴格的等級架構","examples":[{"en":"Mechanistic organisations used strict hierarchical structures.","zh":"機械式組織使用嚴格的等級架構。"},{"en":"Strict hierarchical structures are systems where authority flows clearly from top to bottom.","zh":"Strict hierarchical structures 是權力從上到下清楚流動的制度。"},{"en":"In a strict hierarchy, junior staff must ask managers before making many decisions.","zh":"在嚴格等級制度中，初級員工作許多決定前必須先問經理。"},{"en":"Such structures can create order, but they may slow down responses to change.","zh":"這類架構可以創造秩序，但可能減慢對變化的反應。"},{"en":"This phrase describes clear levels of power in an organisation.","zh":"這個片語描述組織中清晰的權力層級。"}],"source":"110 - Change in business organisations.pdf","sourcePage":5},{"front":"firm means of control","meaning":"嚴格的控制手段","examples":[{"en":"Managers relied on firm means of control.","zh":"管理者依賴嚴格的控制手段。"},{"en":"Firm means of control are strict methods used to direct and supervise people’s work.","zh":"Firm means of control 是用來指導和監督人們工作的嚴格方法。"},{"en":"A factory may use firm control through rules, supervisors, and fixed schedules.","zh":"工廠可能透過規則、監工和固定時間表實施嚴格控制。"},{"en":"Strong control can increase consistency, but it may reduce workers’ independence.","zh":"強力控制可以增加一致性，但可能減少工人自主性。"},{"en":"This phrase describes management based on discipline and supervision.","zh":"這個片語描述基於紀律和監督的管理。"}],"source":"110 - Change in business organisations.pdf","sourcePage":6},{"front":"this situation prevailed","meaning":"這種情況持續存在","examples":[{"en":"This situation prevailed for some time.","zh":"這種情況持續存在了一段時間。"},{"en":"This situation prevailed means this condition continued or remained dominant.","zh":"This situation prevailed 指這種情況持續或保持主導。"},{"en":"If one teaching method prevailed for years, teachers may become used to it.","zh":"如果一種教學方法多年持續存在，老師可能會習慣它。"},{"en":"A market condition can prevail until new technology or competition changes it.","zh":"市場狀況可以持續存在，直到新科技或競爭改變它。"},{"en":"This phrase describes a situation that lasts and dominates.","zh":"這個片語描述持續並占主導的情況。"}],"source":"110 - Change in business organisations.pdf","sourcePage":6},{"front":"domestic market","meaning":"國內市場；本地市場","examples":[{"en":"Demand still came mainly from the domestic market.","zh":"需求仍主要來自國內市場。"},{"en":"The domestic market is the market within a country, not overseas.","zh":"Domestic market 是一個國家內部的市場，而不是海外市場。"},{"en":"A local bakery depends on the domestic market if most customers live nearby.","zh":"如果大多數顧客住在附近，本地麵包店便依賴本地市場。"},{"en":"If domestic demand is strong, companies may not need to search abroad immediately.","zh":"如果國內需求強勁，公司未必需要立即向海外尋找市場。"},{"en":"This phrase contrasts home-country customers with foreign customers.","zh":"這個片語把本國顧客與外國顧客作對比。"}],"source":"110 - Change in business organisations.pdf","sourcePage":6},{"front":"strive to fill","meaning":"努力填補","examples":[{"en":"Organisations were striving to fill the supply gap.","zh":"組織努力填補供應缺口。"},{"en":"To strive to fill something means to work hard to reduce or remove a shortage.","zh":"To strive to fill something 指努力減少或消除短缺。"},{"en":"A school may strive to fill a teacher shortage before term begins.","zh":"學校可能在學期開始前努力填補教師短缺。"},{"en":"When demand is higher than supply, companies strive to fill the gap by producing more.","zh":"當需求高於供應，公司會透過增加產量努力填補缺口。"},{"en":"This phrase suggests effort toward solving a shortage.","zh":"這個片語暗示為解決短缺而努力。"}],"source":"110 - Change in business organisations.pdf","sourcePage":6},{"front":"the supply gap","meaning":"供應缺口","examples":[{"en":"Companies tried to fill the supply gap.","zh":"公司試圖填補供應缺口。"},{"en":"The supply gap is the difference between what customers want and what producers can provide.","zh":"Supply gap 是顧客想要的數量與生產者能提供的數量之間的差距。"},{"en":"If many people want flu vaccines but clinics have too few, there is a supply gap.","zh":"如果很多人想接種流感疫苗，但診所供應太少，便有供應缺口。"},{"en":"A supply gap can push companies to expand production quickly.","zh":"供應缺口可以推動公司快速擴大生產。"},{"en":"This phrase describes shortage in the market.","zh":"這個片語描述市場中的短缺。"}],"source":"110 - Change in business organisations.pdf","sourcePage":6},{"front":"environmental influence on","meaning":"對……的外部環境影響","examples":[{"en":"Product demand was the most disturbing environmental influence on organisations.","zh":"產品需求是對組織最具干擾性的外部環境影響。"},{"en":"Environmental influence on an organisation means an outside condition that affects how it works.","zh":"Environmental influence on an organisation 指影響組織如何運作的外部條件。"},{"en":"New laws can be an environmental influence on how schools manage data.","zh":"新法律可以成為對學校如何管理數據的外部環境影響。"},{"en":"If customer demand changes suddenly, it becomes a strong external influence on business decisions.","zh":"如果顧客需求突然改變，它會成為商業決策的強大外部影響。"},{"en":"This phrase focuses on outside forces rather than internal choices.","zh":"這個片語著重外部力量，而不是內部選擇。"}],"source":"110 - Change in business organisations.pdf","sourcePage":6},{"front":"demand for products","meaning":"對產品的需求","examples":[{"en":"The demand for products outstripped supply.","zh":"對產品的需求超過供應。"},{"en":"Demand for products is the amount of goods customers want to buy.","zh":"Demand for products 是顧客想購買的商品數量。"},{"en":"During a festival, demand for certain foods may rise sharply.","zh":"節日期間，對某些食物的需求可能急劇上升。"},{"en":"If demand for products is high, companies may sell everything they make.","zh":"如果對產品的需求很高，公司可能賣出所有生產的東西。"},{"en":"This phrase describes customer desire in the market.","zh":"這個片語描述市場中的顧客需求。"}],"source":"110 - Change in business organisations.pdf","sourcePage":6},{"front":"outstrip supply","meaning":"超過供應","examples":[{"en":"Demand for products outstripped supply.","zh":"對產品的需求超過供應。"},{"en":"To outstrip supply means demand becomes greater than the amount available.","zh":"To outstrip supply 指需求大於可供應數量。"},{"en":"When a new phone is released, orders may outstrip supply for several weeks.","zh":"新手機推出時，訂單可能連續幾星期超過供應。"},{"en":"If demand outstrips supply, prices may rise and customers may wait longer.","zh":"如果需求超過供應，價格可能上升，顧客可能等更久。"},{"en":"This phrase describes a shortage caused by very strong demand.","zh":"這個片語描述由強烈需求造成的短缺。"}],"source":"110 - Change in business organisations.pdf","sourcePage":6},{"front":"attributed to","meaning":"歸於……；被認為出自……","examples":[{"en":"The saying is attributed to Henry Ford.","zh":"這句話被認為出自Henry Ford。"},{"en":"Attributed to means believed to have been said, written, created, or caused by someone.","zh":"Attributed to 指被認為由某人說出、寫出、創造或造成。"},{"en":"A famous quote may be attributed to a writer even if the exact source is uncertain.","zh":"一句名言可能被歸於某位作家，即使確切來源不確定。"},{"en":"When an idea is attributed to a famous person, it may gain more attention.","zh":"當一個想法被歸於名人，它可能得到更多注意。"},{"en":"This phrase identifies the supposed source.","zh":"這個片語指出假定來源。"}],"source":"110 - Change in business organisations.pdf","sourcePage":6},{"front":"give a flavour of","meaning":"讓人感受到……的特色","examples":[{"en":"The saying gives a flavour of the supply-led market.","zh":"這句話讓人感受到由供應主導市場的特色。"},{"en":"To give a flavour of something means to give a small but clear sense of what it is like.","zh":"To give a flavour of something 指給人一點清楚感覺，讓人知道某事大概是怎樣。"},{"en":"A short video can give a flavour of a university’s campus life.","zh":"短片可以讓人感受到大學校園生活的特色。"},{"en":"Ford’s saying gives readers a feeling for a market where customers had few choices.","zh":"Ford的話讓讀者感受到一個顧客選擇很少的市場。"},{"en":"This phrase means to provide an impression, not a complete explanation.","zh":"這個片語指提供印象，而不是完整解釋。"}],"source":"110 - Change in business organisations.pdf","sourcePage":6},{"front":"supply-led state of the market","meaning":"由供應主導的市場狀態","examples":[{"en":"Ford’s comment reflected the supply-led state of the market.","zh":"Ford的評論反映了由供應主導的市場狀態。"},{"en":"A supply-led state of the market is a situation where producers, not customers, mainly control what is available.","zh":"Supply-led state of the market 是生產者而非顧客主要控制可得商品的情況。"},{"en":"If shops sell everything they produce, the market may be supply-led.","zh":"如果商店能賣出所有生產的東西，市場可能由供應主導。"},{"en":"In a supply-led market, customer preferences may matter less than production capacity.","zh":"在由供應主導的市場中，顧客偏好可能不如生產能力重要。"},{"en":"This phrase describes a market where supply is the main driving force.","zh":"這個片語描述由供應作主要推動力的市場。"}],"source":"110 - Change in business organisations.pdf","sourcePage":6},{"front":"apart from","meaning":"除了……之外","examples":[{"en":"Apart from technical difficulties, Ford did not have to worry about colour preferences.","zh":"除了技術困難之外，Ford不必擔心顧客的顏色偏好。"},{"en":"Apart from means except for or besides.","zh":"Apart from 指除了或另外。"},{"en":"Apart from rent, the family’s biggest cost is food.","zh":"除了租金之外，這個家庭最大的開支是食物。"},{"en":"Apart from one late bus, the school trip went smoothly.","zh":"除了一班巴士遲到之外，學校旅行進行順利。"},{"en":"This phrase introduces an exception or additional point.","zh":"這個片語引出例外或額外重點。"}],"source":"110 - Change in business organisations.pdf","sourcePage":7},{"front":"technical difficulties","meaning":"技術困難","examples":[{"en":"There were technical difficulties in producing cars in different colours.","zh":"生產不同顏色汽車存在技術困難。"},{"en":"Technical difficulties are problems related to machines, methods, tools, or specialised processes.","zh":"Technical difficulties 是與機器、方法、工具或專門流程相關的問題。"},{"en":"A school may face technical difficulties when online lessons fail to load.","zh":"當網上課堂無法載入，學校可能面對技術困難。"},{"en":"Technical difficulties can delay production even when customer demand is strong.","zh":"即使顧客需求強勁，技術困難也可以延誤生產。"},{"en":"This phrase describes practical problems with how something is made or operated.","zh":"這個片語描述製造或操作方式上的實際問題。"}],"source":"110 - Change in business organisations.pdf","sourcePage":7},{"front":"colour preferences","meaning":"顏色偏好","examples":[{"en":"Ford did not have to worry about customers’ colour preferences.","zh":"Ford不必擔心顧客的顏色偏好。"},{"en":"Colour preferences are the colours people like or choose when buying something.","zh":"Colour preferences 是人們購買東西時喜歡或選擇的顏色。"},{"en":"A clothing shop studies colour preferences before ordering new stock.","zh":"服裝店在訂購新貨前會研究顏色偏好。"},{"en":"When supply is limited, companies may ignore colour preferences because customers buy whatever is available.","zh":"當供應有限，公司可能忽視顏色偏好，因為顧客會買任何可得商品。"},{"en":"This phrase describes customer taste in colour.","zh":"這個片語描述顧客在顏色上的品味。"}],"source":"110 - Change in business organisations.pdf","sourcePage":7},{"front":"sell all that he made","meaning":"賣出他所生產的一切","examples":[{"en":"Ford could sell all that he made.","zh":"Ford可以賣出他所生產的一切。"},{"en":"To sell all that someone made means to sell every product produced.","zh":"To sell all that someone made 指賣出所有已生產的產品。"},{"en":"A bakery may sell all that it makes if fresh bread is in high demand.","zh":"如果新鮮麵包需求很高，麵包店可能賣出它所生產的一切。"},{"en":"When a producer can sell everything, customer choice may become less important.","zh":"當生產者能賣出所有東西，顧客選擇可能變得較不重要。"},{"en":"This phrase shows very strong demand relative to supply.","zh":"這個片語顯示需求相對供應非常強。"}],"source":"110 - Change in business organisations.pdf","sourcePage":7},{"front":"be regarded as","meaning":"被視為","examples":[{"en":"Organisations of this period can be regarded as task-oriented.","zh":"這一時期的組織可被視為任務導向的。"},{"en":"To be regarded as something means to be considered or viewed in that way.","zh":"To be regarded as something 指被認為或被看作某種樣子。"},{"en":"A quiet student may be regarded as shy, even if they are simply careful.","zh":"安靜的學生可能被視為害羞，即使他只是謹慎。"},{"en":"A company may be regarded as innovative when it often introduces new services.","zh":"如果公司經常推出新服務，可能被視為具創新性。"},{"en":"This phrase shows how people classify or judge something.","zh":"這個片語顯示人們如何分類或判斷某事。"}],"source":"110 - Change in business organisations.pdf","sourcePage":7},{"front":"task-oriented","meaning":"任務導向的","examples":[{"en":"Industrial-age organisations were task-oriented.","zh":"工業時代組織是任務導向的。"},{"en":"Task-oriented means focused mainly on completing specific jobs efficiently.","zh":"Task-oriented 指主要集中於有效完成特定工作。"},{"en":"A task-oriented manager checks deadlines, procedures, and output closely.","zh":"任務導向的經理會密切檢查期限、程序和產出。"},{"en":"Task-oriented work can increase productivity but may ignore customer feelings.","zh":"任務導向工作可以提高生產力，但可能忽視顧客感受。"},{"en":"This phrase describes a focus on doing tasks rather than building relationships or value.","zh":"這個片語描述集中於完成任務，而不是建立關係或價值。"}],"source":"110 - Change in business organisations.pdf","sourcePage":7},{"front":"effort being put into","meaning":"努力被投放於","examples":[{"en":"Effort was put into increasing production.","zh":"努力被投放於增加產量。"},{"en":"Effort being put into something means time, energy, and resources are directed toward it.","zh":"Effort being put into something 指時間、精力和資源被投向某事。"},{"en":"A school may put effort into improving reading by adding daily practice.","zh":"學校可能透過加入每日練習，把努力投放於改善閱讀。"},{"en":"When effort is put into production, other areas such as service may receive less attention.","zh":"當努力被投放於生產，服務等其他方面可能得到較少注意。"},{"en":"This phrase shows where people concentrate their work.","zh":"這個片語顯示人們把工作集中在哪裡。"}],"source":"110 - Change in business organisations.pdf","sourcePage":7},{"front":"increasing production","meaning":"增加產量","examples":[{"en":"Companies focused on increasing production.","zh":"公司集中於增加產量。"},{"en":"Increasing production means making more goods or providing more output.","zh":"Increasing production 指製造更多商品或提供更多產出。"},{"en":"A restaurant may increase production by preparing more meals before lunchtime.","zh":"餐廳可能透過午餐前準備更多餐點來增加產量。"},{"en":"If demand exceeds supply, increasing production can help fill the gap.","zh":"如果需求超過供應，增加產量可以幫助填補缺口。"},{"en":"This phrase describes raising quantity, not necessarily improving quality.","zh":"這個片語描述提高數量，而不一定改善質素。"}],"source":"110 - Change in business organisations.pdf","sourcePage":7},{"front":"effective and efficient","meaning":"有成效而高效率的","examples":[{"en":"Factories aimed to create more effective and efficient processes.","zh":"工廠旨在創造更有成效而高效率的流程。"},{"en":"Effective means producing the desired result, while efficient means using time, money, or energy well.","zh":"Effective 指產生想要的結果，而 efficient 指善用時間、金錢或能源。"},{"en":"A lesson is effective if students learn, and efficient if it uses class time wisely.","zh":"如果學生學到東西，一堂課就是有成效的；如果善用課堂時間，就是高效率的。"},{"en":"A factory process becomes more effective and efficient when it produces better goods with less waste.","zh":"當工廠流程以更少浪費生產更好商品，它就變得更有成效而高效率。"},{"en":"This phrase combines success with good use of resources.","zh":"這個片語結合成功和善用資源。"}],"source":"110 - Change in business organisations.pdf","sourcePage":7},{"front":"production processes","meaning":"生產流程","examples":[{"en":"Organisations improved their production processes.","zh":"組織改善了其生產流程。"},{"en":"Production processes are the steps and methods used to make goods or deliver output.","zh":"Production processes 是用來製造商品或交付產出的步驟和方法。"},{"en":"A bakery’s production process includes mixing dough, baking, packaging, and delivery.","zh":"麵包店的生產流程包括攪拌麵糰、烘焙、包裝和送貨。"},{"en":"Improving production processes can reduce waste and speed up work.","zh":"改善生產流程可以減少浪費並加快工作。"},{"en":"This phrase focuses on how products are made.","zh":"這個片語著重產品如何被製造。"}],"source":"110 - Change in business organisations.pdf","sourcePage":7},{"front":"as time passed","meaning":"隨着時間過去","examples":[{"en":"As time passed, the favourable period for organisations began to decline.","zh":"隨着時間過去，組織的有利時期開始衰落。"},{"en":"As time passed means as years or a period gradually went by.","zh":"As time passed 指隨着年月或一段時間逐漸過去。"},{"en":"As time passed, students became more comfortable speaking English in class.","zh":"隨着時間過去，學生在課堂上說英語變得更自在。"},{"en":"A business advantage may weaken as time passes and competitors catch up.","zh":"隨着時間過去，商業優勢可能因競爭者追上而減弱。"},{"en":"This phrase marks gradual change over time.","zh":"這個片語標示隨時間逐漸出現的改變。"}],"source":"110 - Change in business organisations.pdf","sourcePage":7},{"front":"favourable period","meaning":"有利時期","examples":[{"en":"The favourable period for organisations began to decline.","zh":"組織的有利時期開始衰落。"},{"en":"A favourable period is a time when conditions are helpful or advantageous.","zh":"Favourable period 是條件有幫助或有優勢的時期。"},{"en":"A shop may enjoy a favourable period when rent is low and customer demand is high.","zh":"當租金低而顧客需求高，商店可能享有有利時期。"},{"en":"Favourable periods do not last forever because markets and technology change.","zh":"有利時期不會永遠持續，因為市場和科技會改變。"},{"en":"This phrase describes a time when success is easier than usual.","zh":"這個片語描述成功比平時更容易的時期。"}],"source":"110 - Change in business organisations.pdf","sourcePage":8},{"front":"begin to decline","meaning":"開始衰落","examples":[{"en":"The old supply-led period began to decline.","zh":"舊的由供應主導時期開始衰落。"},{"en":"To begin to decline means to start becoming weaker, less common, or less successful.","zh":"To begin to decline 指開始變弱、變少見或不再成功。"},{"en":"A shopping street may begin to decline when customers move to online shopping.","zh":"當顧客轉向網上購物，購物街可能開始衰落。"},{"en":"When supply exceeds demand, producers’ power may begin to decline.","zh":"當供應超過需求，生產者的力量可能開始下降。"},{"en":"This phrase marks the start of a downward trend.","zh":"這個片語標示下降趨勢的開始。"}],"source":"110 - Change in business organisations.pdf","sourcePage":8},{"front":"the neo-industrial age","meaning":"新工業時代","examples":[{"en":"In the neo-industrial age, consumers became more selective.","zh":"在新工業時代，消費者變得更有選擇性。"},{"en":"The neo-industrial age is a later stage of industrial society marked by higher productivity, competition, and consumer choice.","zh":"Neo-industrial age 是工業社會後期階段，以較高生產力、競爭和消費者選擇為特徵。"},{"en":"In this age, companies could no longer assume customers would buy whatever they made.","zh":"在這個時代，公司不能再假設顧客會購買任何它們生產的東西。"},{"en":"When supply overtakes demand, firms must pay more attention to value and service.","zh":"當供應超過需求，公司必須更重視價值和服務。"},{"en":"This phrase describes a shift away from simple production quantity.","zh":"這個片語描述由單純生產數量轉向其他重點。"}],"source":"110 - Change in business organisations.pdf","sourcePage":8},{"front":"become more discriminating","meaning":"變得更有辨別力；更挑剔","examples":[{"en":"People became more discriminating in the goods and services they bought.","zh":"人們在購買商品和服務時變得更有辨別力。"},{"en":"To become more discriminating means to become more selective and better at judging quality.","zh":"To become more discriminating 指變得更有選擇性，並更善於判斷質素。"},{"en":"After trying many restaurants, customers may become more discriminating about service and food.","zh":"嘗試許多餐廳後，顧客可能對服務和食物變得更挑剔。"},{"en":"When consumers become more discriminating, companies must improve design, quality, and service.","zh":"當消費者變得更有辨別力，公司必須改善設計、質素和服務。"},{"en":"This phrase suggests careful choice rather than blind buying.","zh":"這個片語暗示仔細選擇，而不是盲目購買。"}],"source":"110 - Change in business organisations.pdf","sourcePage":8},{"front":"goods and services","meaning":"商品和服務","examples":[{"en":"People became more discriminating in the goods and services they wished to buy.","zh":"人們在希望購買的商品和服務方面變得更有辨別力。"},{"en":"Goods and services are physical products and activities or help provided to customers.","zh":"Goods and services 是實體產品以及提供給顧客的活動或幫助。"},{"en":"A phone is a good, while repair support is a service.","zh":"手機是商品，而維修支援是服務。"},{"en":"Modern businesses often compete by improving both goods and services.","zh":"現代企業常透過改善商品和服務來競爭。"},{"en":"This phrase covers what companies sell in both product and service forms.","zh":"這個片語涵蓋公司以產品和服務形式出售的東西。"}],"source":"110 - Change in business organisations.pdf","sourcePage":8},{"front":"technological advancements","meaning":"科技進步","examples":[{"en":"Technological advancements brought about increased productivity.","zh":"科技進步帶來生產力提升。"},{"en":"Technological advancements are improvements in tools, machines, systems, or scientific knowledge.","zh":"Technological advancements 是工具、機器、系統或科學知識方面的改善。"},{"en":"Online booking is a technological advancement that makes appointments easier.","zh":"網上預約是一項令約見更方便的科技進步。"},{"en":"When technology improves, workers may produce more in less time.","zh":"當科技改善，工人可能用更少時間生產更多。"},{"en":"This phrase links progress in technology with changes in work and society.","zh":"這個片語把科技進展與工作和社會變化連接起來。"}],"source":"110 - Change in business organisations.pdf","sourcePage":8},{"front":"bring about increased productivity","meaning":"帶來生產力提升","examples":[{"en":"Technological advancements brought about increased productivity.","zh":"科技進步帶來生產力提升。"},{"en":"To bring about increased productivity means to cause people or machines to produce more output with the same or fewer resources.","zh":"To bring about increased productivity 指令人或機器用相同或更少資源產出更多。"},{"en":"A new ordering system can bring about increased productivity in a busy café.","zh":"新訂餐系統可以為繁忙咖啡店帶來生產力提升。"},{"en":"Increased productivity may lower costs, but it can also reduce the need for some jobs.","zh":"生產力提升可能降低成本，但也可能減少某些職位需求。"},{"en":"This phrase connects a cause with greater efficiency in production.","zh":"這個片語把原因與生產效率提高連接起來。"}],"source":"110 - Change in business organisations.pdf","sourcePage":8},{"front":"increased productivity","meaning":"提高了的生產力","examples":[{"en":"Increased productivity helped supply overtake demand.","zh":"提高了的生產力幫助供應超過需求。"},{"en":"Increased productivity means more output is produced from the same amount of labour, time, or resources.","zh":"Increased productivity 指用相同勞動、時間或資源生產更多產出。"},{"en":"A teacher’s marking productivity may increase after using clearer rubrics.","zh":"老師使用更清晰評分準則後，批改生產力可能提高。"},{"en":"If factories become more productive, they may produce more goods than customers want.","zh":"如果工廠生產力提高，它們可能生產比顧客需求更多的商品。"},{"en":"This phrase describes improvement in output efficiency.","zh":"這個片語描述產出效率提升。"}],"source":"110 - Change in business organisations.pdf","sourcePage":8},{"front":"supply overtook demand","meaning":"供應超過需求","examples":[{"en":"Supply overtook demand in the neo-industrial age.","zh":"在新工業時代，供應超過需求。"},{"en":"Supply overtook demand means producers could offer more than customers wanted to buy.","zh":"Supply overtook demand 指生產者能提供的數量超過顧客想購買的數量。"},{"en":"If many restaurants open in one street, supply may overtake demand.","zh":"如果一條街開了很多餐廳，供應可能超過需求。"},{"en":"When supply overtakes demand, businesses must compete harder for customers.","zh":"當供應超過需求，企業必須更努力爭奪顧客。"},{"en":"This phrase describes a market shift from shortage to surplus.","zh":"這個片語描述市場由短缺轉向過剩。"}],"source":"110 - Change in business organisations.pdf","sourcePage":8},{"front":"look abroad for","meaning":"向海外尋找……","examples":[{"en":"Companies began to look abroad for additional markets.","zh":"公司開始向海外尋找額外市場。"},{"en":"To look abroad for something means to search in other countries for it.","zh":"To look abroad for something 指在其他國家尋找某物。"},{"en":"A university may look abroad for students when local enrolment falls.","zh":"當本地收生下降，大學可能向海外尋找學生。"},{"en":"When domestic demand is weak, companies may look abroad for new customers.","zh":"當國內需求疲弱，公司可能向海外尋找新顧客。"},{"en":"This phrase describes expanding attention beyond the home country.","zh":"這個片語描述把注意力擴展到本國以外。"}],"source":"110 - Change in business organisations.pdf","sourcePage":8},{"front":"additional markets","meaning":"額外市場","examples":[{"en":"Companies searched for additional markets abroad.","zh":"公司在海外尋找額外市場。"},{"en":"Additional markets are extra groups of customers or places where goods can be sold.","zh":"Additional markets 是額外的顧客群或可銷售商品的地方。"},{"en":"A small food brand may find additional markets in nearby cities.","zh":"小型食品品牌可能在附近城市找到額外市場。"},{"en":"Companies seek additional markets when existing customers are not enough.","zh":"當現有顧客不足夠，公司會尋找額外市場。"},{"en":"This phrase describes new opportunities for selling products or services.","zh":"這個片語描述銷售產品或服務的新機會。"}],"source":"110 - Change in business organisations.pdf","sourcePage":8},{"front":"at the same time","meaning":"與此同時","examples":[{"en":"At the same time, organisations faced more foreign competition.","zh":"與此同時，組織面對更多外國競爭。"},{"en":"At the same time means while another thing was also happening.","zh":"At the same time 指另一件事也同時發生。"},{"en":"Students may work part-time and study for exams at the same time.","zh":"學生可能一邊兼職，一邊準備考試。"},{"en":"A company may search for new customers while facing stronger competition at the same time.","zh":"公司可能一方面尋找新顧客，與此同時面對更強競爭。"},{"en":"This phrase shows two parallel developments.","zh":"這個片語顯示兩個平行發展。"}],"source":"110 - Change in business organisations.pdf","sourcePage":9},{"front":"face more intensive competition","meaning":"面對更激烈競爭","examples":[{"en":"Organisations faced more intensive competition from abroad.","zh":"組織面對來自海外更激烈的競爭。"},{"en":"To face more intensive competition means to deal with stronger and more demanding rivalry.","zh":"To face more intensive competition 指面對更強、更具壓力的競爭。"},{"en":"Local shops face more intensive competition when large chains enter the area.","zh":"當大型連鎖店進入該區，本地商店面對更激烈競爭。"},{"en":"Intensive competition can force businesses to improve quality, service, and price.","zh":"激烈競爭可以迫使企業改善質素、服務和價格。"},{"en":"This phrase describes pressure from rivals becoming stronger.","zh":"這個片語描述來自競爭對手的壓力變強。"}],"source":"110 - Change in business organisations.pdf","sourcePage":9},{"front":"from abroad","meaning":"來自海外","examples":[{"en":"Competition increasingly came from abroad.","zh":"競爭越來越多來自海外。"},{"en":"From abroad means from other countries.","zh":"From abroad 指來自其他國家。"},{"en":"A school may receive exchange students from abroad.","zh":"學校可能接收來自海外的交換生。"},{"en":"Products from abroad can increase consumer choice and pressure local companies.","zh":"來自海外的產品可以增加消費者選擇，並給本地公司帶來壓力。"},{"en":"This phrase contrasts foreign sources with domestic ones.","zh":"這個片語把外國來源與本地來源作對比。"}],"source":"110 - Change in business organisations.pdf","sourcePage":9},{"front":"products and services","meaning":"產品和服務","examples":[{"en":"Companies faced competition for their products and services.","zh":"公司在其產品和服務方面面對競爭。"},{"en":"Products and services are the goods a company sells and the help or activities it provides.","zh":"Products and services 是公司出售的商品，以及它提供的幫助或活動。"},{"en":"A phone shop sells products such as phones and services such as repair plans.","zh":"手機店出售手機等產品，也提供維修計劃等服務。"},{"en":"Customers compare products and services when choosing where to spend money.","zh":"顧客在決定在哪裡花錢時，會比較產品和服務。"},{"en":"This phrase covers both physical items and non-physical value.","zh":"這個片語涵蓋實體物品和非實體價值。"}],"source":"110 - Change in business organisations.pdf","sourcePage":9},{"front":"be accompanied by","meaning":"伴隨着","examples":[{"en":"This development was accompanied by a shift in focus.","zh":"這項發展伴隨着重點轉移。"},{"en":"To be accompanied by something means to happen together with it.","zh":"To be accompanied by something 指與某事一起發生。"},{"en":"A new school policy may be accompanied by teacher training.","zh":"新校政可能伴隨着教師培訓。"},{"en":"Rising competition may be accompanied by lower prices and better service.","zh":"競爭上升可能伴隨着價格下降和服務改善。"},{"en":"This phrase links two developments that occur together.","zh":"這個片語連接同時出現的兩個發展。"}],"source":"110 - Change in business organisations.pdf","sourcePage":9},{"front":"a shift in focus","meaning":"重點轉移","examples":[{"en":"The West saw a shift in focus from manufacturing to service.","zh":"西方出現了由製造業轉向服務業的重點轉移。"},{"en":"A shift in focus is a change in what people or organisations pay most attention to.","zh":"Shift in focus 是人或組織最重視的事情出現改變。"},{"en":"A school may have a shift in focus from exams to student wellbeing.","zh":"學校可能出現由考試轉向學生福祉的重點轉移。"},{"en":"When customers become more selective, companies may shift focus from quantity to quality.","zh":"當顧客變得更有選擇性，公司可能把重點由數量轉向質素。"},{"en":"This phrase describes a change in priority.","zh":"這個片語描述優先次序改變。"}],"source":"110 - Change in business organisations.pdf","sourcePage":9},{"front":"from manufacturing to service","meaning":"由製造業轉向服務業","examples":[{"en":"The economy shifted from manufacturing to service.","zh":"經濟由製造業轉向服務業。"},{"en":"From manufacturing to service means moving focus from making goods to providing help, experiences, or support.","zh":"From manufacturing to service 指重點由製造商品轉向提供幫助、體驗或支援。"},{"en":"A computer company may shift from manufacturing devices to offering software services.","zh":"電腦公司可能由製造設備轉向提供軟件服務。"},{"en":"When economies move toward services, workers may need different skills.","zh":"當經濟轉向服務業，工人可能需要不同技能。"},{"en":"This phrase describes a major economic change.","zh":"這個片語描述重大經濟轉變。"}],"source":"110 - Change in business organisations.pdf","sourcePage":9},{"front":"add value to","meaning":"為……增值","examples":[{"en":"Service can add value to manufactured products.","zh":"服務可以為製成品增值。"},{"en":"To add value to something means to make it more useful, attractive, or valuable.","zh":"To add value to something 指令某物更有用、更吸引或更有價值。"},{"en":"A phone shop adds value to a phone by offering repair support and clear advice.","zh":"手機店透過提供維修支援和清晰建議為手機增值。"},{"en":"Good service can add value even when competing products look similar.","zh":"即使競爭產品看起來相似，良好服務也可以增值。"},{"en":"This phrase shows how extra support can increase worth.","zh":"這個片語顯示額外支援如何提高價值。"}],"source":"110 - Change in business organisations.pdf","sourcePage":9},{"front":"manufactured products","meaning":"製成品","examples":[{"en":"Service was used to add value to manufactured products.","zh":"服務被用來為製成品增值。"},{"en":"Manufactured products are goods made in factories or through organised production processes.","zh":"Manufactured products 是在工廠或透過有組織生產流程製造的商品。"},{"en":"Shoes, phones, cars, and furniture are manufactured products.","zh":"鞋、手機、汽車和家具都是製成品。"},{"en":"Companies may add service packages to manufactured products to stand out from rivals.","zh":"公司可能為製成品加入服務套餐，以有別於競爭對手。"},{"en":"This phrase refers to physical goods that have been produced.","zh":"這個片語指已被生產的實體商品。"}],"source":"110 - Change in business organisations.pdf","sourcePage":9},{"front":"in its own right","meaning":"本身；憑自身條件","examples":[{"en":"Service also became important in its own right.","zh":"服務本身也變得重要。"},{"en":"In its own right means because of its own value, not only because it supports something else.","zh":"In its own right 指因自身價值而重要，而不只是因支援其他東西。"},{"en":"A school library is valuable in its own right, not only as a place for homework.","zh":"學校圖書館本身就有價值，而不只是做功課的地方。"},{"en":"Service became a business area in its own right when customers paid for advice and support.","zh":"當顧客願意為建議和支援付款，服務便成為本身重要的商業領域。"},{"en":"This phrase shows independent importance.","zh":"這個片語顯示獨立的重要性。"}],"source":"110 - Change in business organisations.pdf","sourcePage":9},{"front":"the emphasis moved towards","meaning":"重點轉向","examples":[{"en":"The emphasis moved towards adding value to goods and services.","zh":"重點轉向為商品和服務增值。"},{"en":"The emphasis moved towards something means attention or priority shifted in that direction.","zh":"The emphasis moved towards something 指注意力或優先事項轉向該方向。"},{"en":"In many schools, the emphasis has moved towards critical thinking rather than memorisation alone.","zh":"在許多學校，重點已轉向批判思考，而不只是背誦。"},{"en":"When competition rises, businesses may move emphasis towards customer experience.","zh":"當競爭上升，企業可能把重點轉向顧客體驗。"},{"en":"This phrase describes changing priorities over time.","zh":"這個片語描述優先次序隨時間改變。"}],"source":"110 - Change in business organisations.pdf","sourcePage":9},{"front":"value-oriented time","meaning":"價值導向時期","examples":[{"en":"Goodman calls the neo-industrial age a value-oriented time.","zh":"Goodman把新工業時代稱為價值導向時期。"},{"en":"A value-oriented time is a period when organisations focus on creating value for customers, not only producing quantity.","zh":"Value-oriented time 是組織集中為顧客創造價值，而不只是生產數量的時期。"},{"en":"A café enters a value-oriented phase when it improves atmosphere, service, and menu quality.","zh":"當咖啡店改善氣氛、服務和餐牌質素，它便進入價值導向階段。"},{"en":"When customers have more choice, value becomes more important than mere availability.","zh":"當顧客有更多選擇，價值比單純可得性更重要。"},{"en":"This phrase contrasts with task-oriented production.","zh":"這個片語與任務導向式生產形成對比。"}],"source":"110 - Change in business organisations.pdf","sourcePage":10},{"front":"be contrasted with","meaning":"與……形成對比","examples":[{"en":"The value-oriented time is contrasted with earlier task-oriented periods.","zh":"價值導向時期與較早的任務導向時期形成對比。"},{"en":"To be contrasted with something means to be compared in a way that shows differences.","zh":"To be contrasted with something 指與某事比較，以顯示差異。"},{"en":"Online learning is often contrasted with traditional classroom teaching.","zh":"網上學習常與傳統課室教學形成對比。"},{"en":"Contrasting two periods helps readers see how priorities changed.","zh":"對比兩個時期幫助讀者看見優先事項如何改變。"},{"en":"This phrase highlights difference rather than similarity.","zh":"這個片語突顯差異，而不是相似。"}],"source":"110 - Change in business organisations.pdf","sourcePage":10},{"front":"task-oriented times","meaning":"任務導向時期","examples":[{"en":"The industrial age was one of the task-oriented times of the past.","zh":"工業時代是過去任務導向時期之一。"},{"en":"Task-oriented times are periods when completing tasks and increasing output are central priorities.","zh":"Task-oriented times 是完成任務和增加產出成為核心優先事項的時期。"},{"en":"A school may have a task-oriented term when teachers focus mainly on finishing the syllabus.","zh":"當老師主要集中完成課程，學校可能有一個任務導向學期。"},{"en":"Task-oriented periods can be efficient, but they may neglect service or creativity.","zh":"任務導向時期可以高效率，但可能忽略服務或創意。"},{"en":"This phrase describes times dominated by production and execution.","zh":"這個片語描述由生產和執行主導的時期。"}],"source":"110 - Change in business organisations.pdf","sourcePage":10},{"front":"products/services-oriented times","meaning":"產品／服務導向時期","examples":[{"en":"The past included products/services-oriented times.","zh":"過去包括產品／服務導向時期。"},{"en":"Products/services-oriented times are periods when organisations focus mainly on what goods or services they offer.","zh":"Products/services-oriented times 是組織主要集中於提供哪些商品或服務的時期。"},{"en":"A business becomes product-oriented when it thinks first about what it can make.","zh":"當企業首先思考自己能製造甚麼，它便變得產品導向。"},{"en":"A service-oriented period may focus on support, convenience, and customer care.","zh":"服務導向時期可能集中於支援、便利和顧客服務。"},{"en":"This phrase describes business periods organised around offerings to customers.","zh":"這個片語描述圍繞顧客供應內容而組織的商業時期。"}],"source":"110 - Change in business organisations.pdf","sourcePage":10},{"front":"the post-industrial age","meaning":"後工業時代","examples":[{"en":"In the post-industrial age, organisational life is becoming uncertain.","zh":"在後工業時代，組織生活變得不確定。"},{"en":"The post-industrial age is a period after industrial dominance, marked by services, knowledge work, technology, and rapid change.","zh":"Post-industrial age 是工業主導之後的時期，以服務、知識工作、科技和快速變化為特徵。"},{"en":"In the post-industrial age, people may work from home, online, or in flexible teams.","zh":"在後工業時代，人們可能在家、網上或彈性團隊中工作。"},{"en":"Organisations must adapt because old factory-style structures may no longer fit.","zh":"組織必須適應，因為舊式工廠架構可能不再適合。"},{"en":"This phrase describes a modern stage beyond traditional industrial production.","zh":"這個片語描述超越傳統工業生產的現代階段。"}],"source":"110 - Change in business organisations.pdf","sourcePage":10},{"front":"organisational life","meaning":"組織生活；機構運作","examples":[{"en":"Organisational life is becoming ever more uncertain.","zh":"組織生活正變得越來越不確定。"},{"en":"Organisational life means the daily working reality inside organisations, including roles, routines, culture, and relationships.","zh":"Organisational life 指組織內的日常工作現實，包括角色、常規、文化和關係。"},{"en":"In a school, organisational life includes meetings, lessons, duties, and communication.","zh":"在學校中，組織生活包括會議、課堂、職責和溝通。"},{"en":"When technology changes quickly, organisational life may become less predictable.","zh":"當科技快速改變，機構運作可能變得較難預測。"},{"en":"This phrase describes how it feels and functions to work inside an organisation.","zh":"這個片語描述在組織內工作時的感受和運作方式。"}],"source":"110 - Change in business organisations.pdf","sourcePage":10},{"front":"ever more uncertain","meaning":"越來越不確定","examples":[{"en":"Business organisations are becoming ever more uncertain.","zh":"商業機構正變得越來越不確定。"},{"en":"Ever more uncertain means increasingly difficult to predict or understand.","zh":"Ever more uncertain 指越來越難預測或理解。"},{"en":"A student’s future may feel ever more uncertain when exam rules and job markets keep changing.","zh":"當考試規則和就業市場持續改變，學生的未來可能感到越來越不確定。"},{"en":"If customer habits change quickly, business planning becomes ever more uncertain.","zh":"如果顧客習慣快速改變，商業規劃會變得越來越不確定。"},{"en":"This phrase emphasises uncertainty that grows over time.","zh":"這個片語強調隨時間增長的不確定性。"}],"source":"110 - Change in business organisations.pdf","sourcePage":10},{"front":"the pace of change quickens","meaning":"變革步伐加快","examples":[{"en":"The pace of change quickens in the post-industrial age.","zh":"後工業時代中，變革步伐加快。"},{"en":"The pace of change quickens means change starts happening faster.","zh":"The pace of change quickens 指變化開始發生得更快。"},{"en":"The pace of learning may quicken when students practise every day.","zh":"當學生每天練習，學習步伐可能加快。"},{"en":"When technology develops rapidly, companies may need to update systems more often.","zh":"當科技迅速發展，公司可能需要更頻繁更新制度。"},{"en":"This phrase focuses on speed of change.","zh":"這個片語著重變化速度。"}],"source":"110 - Change in business organisations.pdf","sourcePage":10},{"front":"less predictable","meaning":"較難預測","examples":[{"en":"The future is becoming less predictable.","zh":"未來正變得較難預測。"},{"en":"Less predictable means harder to forecast or know in advance.","zh":"Less predictable 指較難預先預測或知道。"},{"en":"A bus schedule becomes less predictable when traffic is heavy and weather is bad.","zh":"當交通繁忙且天氣差，巴士時間表會變得較難預測。"},{"en":"If markets become less predictable, managers need flexible plans.","zh":"如果市場變得較難預測，管理者需要彈性計劃。"},{"en":"This phrase describes uncertainty increasing.","zh":"這個片語描述不確定性增加。"}],"source":"110 - Change in business organisations.pdf","sourcePage":10},{"front":"poised on the eve of","meaning":"正處於……前夕","examples":[{"en":"Businesses were poised on the eve of the next century.","zh":"企業正處於下一個世紀的前夕。"},{"en":"Poised on the eve of something means standing just before an important new period or event.","zh":"Poised on the eve of something 指正站在重要新時期或事件之前。"},{"en":"A student may feel nervous when poised on the eve of university life.","zh":"學生在大學生活前夕可能感到緊張。"},{"en":"Organisations on the eve of major change must prepare for uncertainty.","zh":"處於重大變革前夕的組織必須為不確定性作準備。"},{"en":"This phrase gives a sense of being at a turning point.","zh":"這個片語帶出身處轉折點的感覺。"}],"source":"110 - Change in business organisations.pdf","sourcePage":10},{"front":"witness a profound transformation","meaning":"見證深刻轉變","examples":[{"en":"Researchers witnessed a profound transformation in business organisations.","zh":"研究人員見證了商業機構的深刻轉變。"},{"en":"To witness a profound transformation means to see a deep and important change happen.","zh":"To witness a profound transformation 指看見深層而重要的變化發生。"},{"en":"Teachers may witness a profound transformation when a shy student becomes confident.","zh":"當害羞學生變得自信，老師可能見證深刻轉變。"},{"en":"Digital technology has caused many businesses to undergo deep structural change.","zh":"數碼科技已令許多企業經歷深層架構改變。"},{"en":"This phrase describes observing major change, not a small adjustment.","zh":"這個片語描述觀察重大變化，而不是小調整。"}],"source":"110 - Change in business organisations.pdf","sourcePage":10},{"front":"the very nature of","meaning":"……的本質","examples":[{"en":"The very nature of business organisations is changing.","zh":"商業機構的本質正在改變。"},{"en":"The very nature of something means its basic character or essential qualities.","zh":"The very nature of something 指某事的基本特性或核心特質。"},{"en":"Online learning changed the very nature of classroom participation for some students.","zh":"對一些學生而言，網上學習改變了課堂參與的本質。"},{"en":"When work no longer depends on one office, the nature of organisations changes deeply.","zh":"當工作不再依賴單一辦公室，組織的本質便深刻改變。"},{"en":"This phrase emphasises fundamental identity, not surface details.","zh":"這個片語強調根本身份，而不是表面細節。"}],"source":"110 - Change in business organisations.pdf","sourcePage":11},{"front":"historic forces","meaning":"歷史力量","examples":[{"en":"Historic forces have converged to reshape enterprises.","zh":"歷史力量已匯聚起來重塑企業。"},{"en":"Historic forces are powerful long-term social, economic, political, or technological influences.","zh":"Historic forces 是強大的長期社會、經濟、政治或科技影響。"},{"en":"War, migration, and new technology can be historic forces that transform cities.","zh":"戰爭、移民和新科技可以是改變城市的歷史力量。"},{"en":"Historic forces are usually bigger than one company or one manager.","zh":"歷史力量通常大於單一公司或單一經理。"},{"en":"This phrase describes large forces that shape an era.","zh":"這個片語描述塑造時代的大力量。"}],"source":"110 - Change in business organisations.pdf","sourcePage":11},{"front":"converge to","meaning":"匯聚起來去……","examples":[{"en":"Several historic forces have converged to reshape business.","zh":"幾股歷史力量匯聚起來重塑商業。"},{"en":"To converge to do something means different forces come together and produce a shared effect.","zh":"To converge to do something 指不同力量聚合並產生共同效果。"},{"en":"Student pressure, parent concern, and poor results may converge to force school reform.","zh":"學生壓力、家長關注和差劣成績可能匯聚起來迫使學校改革。"},{"en":"When technology, competition, and consumer behaviour converge, organisations may change quickly.","zh":"當科技、競爭和消費者行為匯聚，組織可能迅速改變。"},{"en":"This phrase shows multiple causes coming together.","zh":"這個片語顯示多個原因聚合。"}],"source":"110 - Change in business organisations.pdf","sourcePage":11},{"front":"fundamentally reshape","meaning":"從根本上重塑","examples":[{"en":"Historic forces have fundamentally reshaped large enterprises.","zh":"歷史力量已從根本上重塑大型企業。"},{"en":"To fundamentally reshape something means to change its basic form, structure, or nature.","zh":"To fundamentally reshape something 指改變某物的基本形式、架構或本質。"},{"en":"Remote learning fundamentally reshaped how some schools deliver lessons.","zh":"遙距學習從根本上重塑了一些學校授課方式。"},{"en":"A new law may fundamentally reshape an industry if it changes what companies can do.","zh":"如果新法律改變公司能做甚麼，它可能從根本上重塑一個行業。"},{"en":"This phrase describes deep change, not a small improvement.","zh":"這個片語描述深層改變，而不是小改善。"}],"source":"110 - Change in business organisations.pdf","sourcePage":11},{"front":"scope, strategies, and structures","meaning":"範圍、策略和架構","examples":[{"en":"The scope, strategies, and structures of enterprises are changing.","zh":"企業的範圍、策略和架構正在改變。"},{"en":"Scope, strategies, and structures mean what an organisation does, how it plans to succeed, and how it is arranged.","zh":"Scope, strategies, and structures 指組織做甚麼、如何計劃成功，以及如何安排內部。"},{"en":"A school’s scope may expand, its strategy may change, and its structure may need new departments.","zh":"學校的範圍可能擴大，策略可能改變，架構可能需要新部門。"},{"en":"When all three change, an organisation is being transformed at several levels.","zh":"當三者都改變，組織正在多個層面被轉變。"},{"en":"This phrase covers the range, plans, and organisation of a business.","zh":"這個片語涵蓋企業的範圍、計劃和組織方式。"}],"source":"110 - Change in business organisations.pdf","sourcePage":11},{"front":"large enterprises","meaning":"大型企業","examples":[{"en":"Large enterprises are being reshaped by historic forces.","zh":"大型企業正被歷史力量重塑。"},{"en":"Large enterprises are big companies or organisations with many workers, departments, and operations.","zh":"Large enterprises 是擁有許多員工、部門和營運的大型公司或組織。"},{"en":"A multinational technology company is a large enterprise.","zh":"跨國科技公司是大型企業。"},{"en":"Large enterprises may change slowly because their structures are complex.","zh":"大型企業可能改變較慢，因為其架構複雜。"},{"en":"This phrase refers to major organisations, not small local shops.","zh":"這個片語指大型組織，而不是小型本地商店。"}],"source":"110 - Change in business organisations.pdf","sourcePage":11},{"front":"at a less general level of analysis","meaning":"在較具體的分析層面上","examples":[{"en":"At a less general level of analysis, economists predicted changes in working life.","zh":"在較具體的分析層面上，經濟學家預測工作生活的變化。"},{"en":"At a less general level of analysis means looking at a topic in a more specific and detailed way.","zh":"At a less general level of analysis 指以更具體、更詳細的方式看待主題。"},{"en":"A teacher may first discuss school problems generally, then at a less general level discuss homework deadlines.","zh":"老師可能先一般地討論學校問題，然後在較具體層面討論功課期限。"},{"en":"Moving to a more specific level helps readers see concrete examples.","zh":"轉向更具體層面幫助讀者看見具體例子。"},{"en":"This phrase signals a shift from broad ideas to detailed analysis.","zh":"這個片語標示由廣泛想法轉向詳細分析。"}],"source":"110 - Change in business organisations.pdf","sourcePage":11},{"front":"Chief Economist","meaning":"首席經濟師","examples":[{"en":"Graeme Leach was Chief Economist at the British Institute of Directors.","zh":"Graeme Leach是英國董事學會的首席經濟師。"},{"en":"A Chief Economist is a senior expert responsible for economic analysis and forecasts in an organisation.","zh":"Chief Economist 是組織中負責經濟分析和預測的高級專家。"},{"en":"A bank’s Chief Economist may explain how interest rates affect families and businesses.","zh":"銀行的首席經濟師可能解釋利率如何影響家庭和企業。"},{"en":"When a Chief Economist makes predictions, readers may treat them as informed expert views.","zh":"當首席經濟師作預測，讀者可能把它視為有根據的專家觀點。"},{"en":"This phrase names a senior professional role in economics.","zh":"這個片語命名經濟學中的高級專業角色。"}],"source":"110 - Change in business organisations.pdf","sourcePage":11},{"front":"nine-to-five rat race","meaning":"朝九晚五的競爭生活","examples":[{"en":"Leach predicted that the nine-to-five rat race would become extinct.","zh":"Leach預測朝九晚五的競爭生活會絕跡。"},{"en":"The nine-to-five rat race is a stressful routine of standard office hours and competitive working life.","zh":"Nine-to-five rat race 是標準辦公時間和競爭性工作生活構成的高壓常規。"},{"en":"Many people feel trapped in the nine-to-five rat race when commuting and office work fill every weekday.","zh":"當通勤和辦公室工作填滿每個工作日，許多人會覺得困在朝九晚五的競爭生活中。"},{"en":"Flexible work may reduce the old pattern of fixed hours and daily commuting.","zh":"彈性工作可能減少固定工時和每日通勤的舊模式。"},{"en":"This phrase is critical and suggests work that feels repetitive and pressured.","zh":"這個片語帶批評意味，暗示工作重複而有壓力。"}],"source":"110 - Change in business organisations.pdf","sourcePage":11},{"front":"be extinct","meaning":"絕跡；不復存在","examples":[{"en":"The traditional nine-to-five working pattern may become extinct.","zh":"傳統朝九晚五工作模式可能絕跡。"},{"en":"To be extinct means to disappear completely or no longer exist.","zh":"To be extinct 指完全消失或不再存在。"},{"en":"Some old jobs became extinct when machines replaced manual work.","zh":"當機器取代人手工作，一些舊職業變得不復存在。"},{"en":"If a work pattern becomes extinct, future workers may never experience it.","zh":"如果某工作模式絕跡，未來工人可能永遠不會經歷它。"},{"en":"This phrase describes total disappearance, not just decline.","zh":"這個片語描述完全消失，而不只是衰落。"}],"source":"110 - Change in business organisations.pdf","sourcePage":11},{"front":"present levels of","meaning":"目前……的水平","examples":[{"en":"Present levels of self-employment and commuting may change greatly.","zh":"目前自僱和通勤的水平可能大幅改變。"},{"en":"Present levels of something are the current amounts or rates of it.","zh":"Present levels of something 是某事目前的數量或比率。"},{"en":"Present levels of student stress may be higher than teachers realise.","zh":"目前學生壓力水平可能比老師意識到的更高。"},{"en":"If present levels of commuting fall, cities may need fewer crowded morning trains.","zh":"如果目前通勤水平下降，城市可能需要較少繁忙早班列車。"},{"en":"This phrase refers to the situation now, before future change.","zh":"這個片語指未來改變前的現時情況。"}],"source":"110 - Change in business organisations.pdf","sourcePage":11},{"front":"self-employment","meaning":"自僱","examples":[{"en":"Levels of self-employment were expected to change.","zh":"自僱水平預期會改變。"},{"en":"Self-employment means working for oneself rather than being employed by a company.","zh":"Self-employment 指為自己工作，而不是受僱於公司。"},{"en":"A tutor, designer, or taxi driver may work through self-employment.","zh":"導師、設計師或的士司機可能透過自僱工作。"},{"en":"Technology can increase self-employment by making it easier to find clients online.","zh":"科技可以透過讓人在網上更容易找到客戶來增加自僱。"},{"en":"This phrase describes independent work rather than regular salaried employment.","zh":"這個片語描述獨立工作，而不是固定受薪就業。"}],"source":"110 - Change in business organisations.pdf","sourcePage":12},{"front":"commuting","meaning":"通勤","examples":[{"en":"Commuting patterns may change beyond recognition.","zh":"通勤模式可能變得面目全非。"},{"en":"Commuting is travelling regularly between home and work or school.","zh":"Commuting 是定期往返住所與工作或學校之間。"},{"en":"A worker who takes the train to the office every morning is commuting.","zh":"每天早上乘火車到辦公室的工人正在通勤。"},{"en":"If more people work from home, commuting may decrease sharply.","zh":"如果更多人在家工作，通勤可能大幅減少。"},{"en":"This word describes routine travel, not holiday travel.","zh":"這個詞描述日常往返交通，而不是假期旅遊。"}],"source":"110 - Change in business organisations.pdf","sourcePage":12},{"front":"technology use","meaning":"科技使用","examples":[{"en":"Technology use in work may change greatly.","zh":"工作中的科技使用可能大幅改變。"},{"en":"Technology use means the way people use tools, machines, software, or digital systems.","zh":"Technology use 指人們使用工具、機器、軟件或數碼系統的方式。"},{"en":"A teacher’s technology use may include online quizzes and shared documents.","zh":"老師的科技使用可能包括網上小測和共享文件。"},{"en":"When technology use increases, workers may need new training.","zh":"當科技使用增加，工人可能需要新培訓。"},{"en":"This phrase describes practical use of technology, not technology itself.","zh":"這個片語描述科技的實際使用，而不是科技本身。"}],"source":"110 - Change in business organisations.pdf","sourcePage":12},{"front":"age and sex gaps","meaning":"年齡和性別差距","examples":[{"en":"Age and sex gaps in work may change beyond recognition.","zh":"工作中的年齡和性別差距可能變得面目全非。"},{"en":"Age and sex gaps are differences between groups based on age and gender.","zh":"Age and sex gaps 是基於年齡和性別的群體差異。"},{"en":"A workplace may have age gaps if older workers hold senior roles and younger workers hold temporary jobs.","zh":"如果年長工人擔任高級職位，而年輕工人做臨時工作，工作場所可能有年齡差距。"},{"en":"Flexible work may reduce some gender gaps if it helps parents balance work and family.","zh":"如果彈性工作幫助父母平衡工作和家庭，可能減少某些性別差距。"},{"en":"This phrase describes social differences in employment patterns.","zh":"這個片語描述就業模式中的社會差異。"}],"source":"110 - Change in business organisations.pdf","sourcePage":12},{"front":"change beyond recognition","meaning":"變得面目全非","examples":[{"en":"Working practices may change beyond recognition.","zh":"工作方式可能變得面目全非。"},{"en":"To change beyond recognition means to become so different that it is hard to recognise the original form.","zh":"To change beyond recognition 指變得非常不同，以至難以認出原本樣貌。"},{"en":"A neighbourhood may change beyond recognition after years of redevelopment.","zh":"多年重建後，社區可能變得面目全非。"},{"en":"If office work moves online, traditional workplaces may change beyond recognition.","zh":"如果辦公工作轉到網上，傳統工作場所可能變得面目全非。"},{"en":"This phrase describes extreme transformation.","zh":"這個片語描述極端轉變。"}],"source":"110 - Change in business organisations.pdf","sourcePage":12},{"front":"anticipate that","meaning":"預期","examples":[{"en":"Leach anticipates that many workers will become temporary or flexible.","zh":"Leach預期許多工人將成為臨時工或彈性工作者。"},{"en":"To anticipate that something will happen means to expect or predict it.","zh":"To anticipate that something will happen 指預期或預測某事會發生。"},{"en":"A school may anticipate that more students will need online support during bad weather.","zh":"學校可能預期惡劣天氣期間更多學生需要網上支援。"},{"en":"Companies anticipate change so they can prepare before pressure arrives.","zh":"公司預期變化，以便在壓力來臨前準備。"},{"en":"This phrase introduces a prediction or expectation.","zh":"這個片語引出預測或期望。"}],"source":"110 - Change in business organisations.pdf","sourcePage":12},{"front":"in 20 years’ time","meaning":"二十年後","examples":[{"en":"In 20 years’ time, many employees may work outside traditional offices.","zh":"二十年後，許多員工可能在傳統辦公室以外工作。"},{"en":"In 20 years’ time means twenty years from now or from the time being discussed.","zh":"In 20 years’ time 指從現在或所討論時間起二十年後。"},{"en":"In 20 years’ time, today’s students may be managers, teachers, or parents.","zh":"二十年後，今天的學生可能成為經理、老師或父母。"},{"en":"Predictions about work in 20 years’ time are uncertain because technology changes quickly.","zh":"對二十年後工作的預測不確定，因為科技變化很快。"},{"en":"This phrase places a prediction in the future.","zh":"這個片語把預測放在未來。"}],"source":"110 - Change in business organisations.pdf","sourcePage":12},{"front":"the workforce","meaning":"勞動人口","examples":[{"en":"A quarter of the workforce may become temporary workers.","zh":"四分之一勞動人口可能成為臨時工。"},{"en":"The workforce means all the people who are working or available for work.","zh":"Workforce 指所有正在工作或可工作的人。"},{"en":"A hospital’s workforce includes doctors, nurses, cleaners, and administrative staff.","zh":"醫院的勞動人口包括醫生、護士、清潔工和行政人員。"},{"en":"If the workforce becomes more flexible, companies may change how they hire and train people.","zh":"如果勞動人口變得更彈性，公司可能改變招聘和培訓方式。"},{"en":"This phrase describes workers as a whole group.","zh":"這個片語把工人描述為整體群體。"}],"source":"110 - Change in business organisations.pdf","sourcePage":12},{"front":"temporary workers","meaning":"臨時工","examples":[{"en":"Temporary workers may make up a large share of the workforce.","zh":"臨時工可能佔勞動人口很大比例。"},{"en":"Temporary workers are people employed for a limited period rather than permanently.","zh":"Temporary workers 是被聘用一段有限時間，而不是永久受聘的人。"},{"en":"A shop may hire temporary workers during the Christmas rush.","zh":"商店可能在聖誕繁忙期聘請臨時工。"},{"en":"Temporary work gives flexibility, but it may offer less security.","zh":"臨時工作提供彈性，但可能較少保障。"},{"en":"This phrase describes employment that is not long-term or permanent.","zh":"這個片語描述非長期或非永久就業。"}],"source":"110 - Change in business organisations.pdf","sourcePage":12},{"front":"flexible workers","meaning":"彈性工作者","examples":[{"en":"Many more workers will be flexible.","zh":"更多工人將成為彈性工作者。"},{"en":"Flexible workers are workers whose hours, location, or employment arrangements can change more easily.","zh":"Flexible workers 是工時、地點或僱用安排較容易改變的工人。"},{"en":"A flexible worker may work from home three days a week and visit the office twice.","zh":"彈性工作者可能每週三天在家工作，兩天到辦公室。"},{"en":"Flexible work can help families, but it may blur the boundary between work and rest.","zh":"彈性工作可以幫助家庭，但也可能模糊工作和休息的界線。"},{"en":"This phrase describes adaptability in work arrangements.","zh":"這個片語描述工作安排上的適應性。"}],"source":"110 - Change in business organisations.pdf","sourcePage":12},{"front":"no longer work in","meaning":"不再在……工作","examples":[{"en":"Many people may no longer work in a traditional office.","zh":"許多人可能不再在傳統辦公室工作。"},{"en":"No longer work in means used to work there, but do not work there anymore.","zh":"No longer work in 指過去在那裡工作，但現在不再在那裡工作。"},{"en":"Some tutors no longer work in classrooms because they teach online.","zh":"一些導師不再在課室工作，因為他們網上授課。"},{"en":"If employees no longer work in one office, managers need new ways to communicate.","zh":"如果員工不再在同一辦公室工作，管理者需要新的溝通方式。"},{"en":"This phrase describes a change away from an old workplace pattern.","zh":"這個片語描述離開舊工作模式的轉變。"}],"source":"110 - Change in business organisations.pdf","sourcePage":12},{"front":"traditional office","meaning":"傳統辦公室","examples":[{"en":"Some employees will no longer work in a traditional office.","zh":"一些員工將不再在傳統辦公室工作。"},{"en":"A traditional office is a fixed workplace where employees gather during regular working hours.","zh":"Traditional office 是員工在固定工作時間聚集的固定工作場所。"},{"en":"A traditional office may have desks, meeting rooms, managers, and set schedules.","zh":"傳統辦公室可能有辦公桌、會議室、經理和固定時間表。"},{"en":"Remote work challenges the idea that every employee must sit in a traditional office.","zh":"遙距工作挑戰每位員工都必須坐在傳統辦公室的想法。"},{"en":"This phrase contrasts with home-based, mobile, or flexible work.","zh":"這個片語與在家、流動或彈性工作形成對比。"}],"source":"110 - Change in business organisations.pdf","sourcePage":13},{"front":"work from home","meaning":"在家工作","examples":[{"en":"Half of workers may work from home in some form.","zh":"一半工人可能以某種形式在家工作。"},{"en":"To work from home means to do one’s job from home rather than a workplace.","zh":"To work from home 指在家中而不是工作場所完成工作。"},{"en":"A designer can work from home using video calls and shared files.","zh":"設計師可以透過視像會議和共享文件在家工作。"},{"en":"Working from home can reduce commuting, but it requires self-discipline and good communication.","zh":"在家工作可以減少通勤，但需要自律和良好溝通。"},{"en":"This phrase describes a major form of flexible work.","zh":"這個片語描述彈性工作的一種主要形式。"}],"source":"110 - Change in business organisations.pdf","sourcePage":13},{"front":"in some form","meaning":"以某種形式","examples":[{"en":"Many employees may work from home in some form.","zh":"許多員工可能以某種形式在家工作。"},{"en":"In some form means in one way or another, even if the exact arrangement differs.","zh":"In some form 指以某種方式，即使具體安排不同。"},{"en":"A school may offer online support in some form during bad weather.","zh":"惡劣天氣期間，學校可能以某種形式提供網上支援。"},{"en":"Work from home can exist in some form, such as one day a week or full-time remote work.","zh":"在家工作可以以某種形式存在，例如每週一天或全職遙距工作。"},{"en":"This phrase allows for different versions of the same idea.","zh":"這個片語容許同一想法有不同版本。"}],"source":"110 - Change in business organisations.pdf","sourcePage":13},{"front":"continuing the metaphor","meaning":"延續這個比喻","examples":[{"en":"Continuing the metaphor, the writer compares change to gale-force winds.","zh":"延續這個比喻，作者把變化比作烈風。"},{"en":"Continuing the metaphor means keeping the same comparison going in later sentences.","zh":"Continuing the metaphor 指在後面的句子繼續使用同一比較。"},{"en":"If a writer calls exams a marathon, continuing the metaphor may involve pacing and endurance.","zh":"如果作者把考試稱為馬拉松，延續這個比喻可能涉及配速和耐力。"},{"en":"Continuing a metaphor can make an argument feel more connected.","zh":"延續比喻可以令論點感覺更連貫。"},{"en":"This phrase describes how the writer develops figurative language.","zh":"這個片語描述作者如何發展比喻語言。"}],"source":"110 - Change in business organisations.pdf","sourcePage":13},{"front":"damaging gale-force winds","meaning":"具破壞力的烈風","examples":[{"en":"Damaging gale-force winds may create a need for rebuilding.","zh":"具破壞力的烈風可能造成重建的需要。"},{"en":"Damaging gale-force winds are extremely strong winds that can destroy structures; here they symbolise powerful change.","zh":"Damaging gale-force winds 是能摧毀結構的極強風，在此象徵強大的變革。"},{"en":"A sudden economic shock can be like damaging gale-force winds for a small company.","zh":"突然的經濟衝擊對小公司而言，可能像具破壞力的烈風。"},{"en":"After such forceful change, organisations may need to rebuild systems and habits.","zh":"經過這種強烈變革後，組織可能需要重建制度和習慣。"},{"en":"This phrase suggests change that is both powerful and destructive.","zh":"這個片語暗示變革既強大又具破壞性。"}],"source":"110 - Change in business organisations.pdf","sourcePage":13},{"front":"create a need for","meaning":"造成……的需要","examples":[{"en":"Rapid change may create a need for rebuilding.","zh":"快速變革可能造成重建的需要。"},{"en":"To create a need for something means to make that thing necessary.","zh":"To create a need for something 指令某事變得必要。"},{"en":"A larger student population can create a need for more classrooms.","zh":"學生人數增加可以造成需要更多課室。"},{"en":"If old procedures fail, change creates a need for new training.","zh":"如果舊程序失效，變革會造成新培訓的需要。"},{"en":"This phrase links a new situation with a required response.","zh":"這個片語把新情況與必要回應連接起來。"}],"source":"110 - Change in business organisations.pdf","sourcePage":13},{"front":"provide opportunities to","meaning":"提供機會去……","examples":[{"en":"Change can provide opportunities to incorporate new ideas.","zh":"變革可以提供機會去融入新意念。"},{"en":"To provide opportunities to do something means to make it possible to do it.","zh":"To provide opportunities to do something 指令某事有可能發生。"},{"en":"A new school project can provide opportunities for shy students to speak.","zh":"新學校項目可以為害羞學生提供發言機會。"},{"en":"Organisational change can provide opportunities to improve old systems.","zh":"組織變革可以提供機會去改善舊制度。"},{"en":"This phrase presents change as a chance, not only a threat.","zh":"這個片語把變革呈現為機會，而不只是威脅。"}],"source":"110 - Change in business organisations.pdf","sourcePage":13},{"front":"incorporate new ideas","meaning":"融入新意念","examples":[{"en":"Organisations can incorporate new ideas and ways of working.","zh":"組織可以融入新意念和工作方式。"},{"en":"To incorporate new ideas means to include them in an existing system or practice.","zh":"To incorporate new ideas 指把新想法加入現有制度或做法中。"},{"en":"A teacher may incorporate new ideas by adding group discussion to grammar lessons.","zh":"老師可能透過在文法課加入小組討論來融入新意念。"},{"en":"If companies incorporate new ideas carefully, change can improve performance.","zh":"如果公司謹慎融入新意念，變革可以改善表現。"},{"en":"This phrase describes adding innovation without necessarily destroying everything old.","zh":"這個片語描述加入創新，而不一定摧毀所有舊事物。"}],"source":"110 - Change in business organisations.pdf","sourcePage":13},{"front":"ways of working","meaning":"工作方式","examples":[{"en":"New ways of working may emerge after organisational change.","zh":"組織變革後可能出現新的工作方式。"},{"en":"Ways of working are the methods, habits, and arrangements people use to do their jobs.","zh":"Ways of working 是人們完成工作的方式、習慣和安排。"},{"en":"Remote meetings and shared online documents are modern ways of working.","zh":"遙距會議和網上共享文件是現代工作方式。"},{"en":"When ways of working change, employees may need training and time to adapt.","zh":"當工作方式改變，員工可能需要培訓和時間適應。"},{"en":"This phrase focuses on how work is actually done.","zh":"這個片語著重工作實際如何完成。"}],"source":"110 - Change in business organisations.pdf","sourcePage":13},{"front":"whether all this will happen","meaning":"這一切會否發生","examples":[{"en":"Whether all this will happen is arguable.","zh":"這一切會否發生是可商榷的。"},{"en":"Whether all this will happen means whether the predicted changes will actually take place.","zh":"Whether all this will happen 指所預測的變化是否真的會出現。"},{"en":"Whether students will all learn online in future is still uncertain.","zh":"未來是否所有學生都會網上學習仍然不確定。"},{"en":"Future predictions may sound confident, but whether they happen depends on many forces.","zh":"未來預測可能聽起來很肯定，但它們會否發生取決於許多力量。"},{"en":"This phrase introduces doubt about a forecast.","zh":"這個片語引出對預測的疑問。"}],"source":"110 - Change in business organisations.pdf","sourcePage":13},{"front":"be arguable","meaning":"有爭議；可商榷","examples":[{"en":"The accuracy of future predictions is arguable.","zh":"未來預測的準確性是可商榷的。"},{"en":"If something is arguable, people can reasonably disagree about it.","zh":"If something is arguable，意思是人們可以合理地有不同意見。"},{"en":"It is arguable whether homework should be reduced for older students.","zh":"年長學生是否應減少功課是可商榷的。"},{"en":"When evidence is incomplete, a conclusion may remain arguable.","zh":"當證據不完整，結論可能仍然有爭議。"},{"en":"This phrase shows that a claim is open to debate.","zh":"這個片語顯示某主張可以被討論。"}],"source":"110 - Change in business organisations.pdf","sourcePage":13},{"front":"forecasting the future","meaning":"預測未來","examples":[{"en":"Forecasting the future is always difficult.","zh":"預測未來總是困難的。"},{"en":"Forecasting the future means trying to predict what will happen later.","zh":"Forecasting the future 指嘗試預測之後會發生甚麼。"},{"en":"A school may forecast future enrolment by studying birth rates and housing plans.","zh":"學校可能透過研究出生率和房屋計劃來預測未來收生。"},{"en":"Forecasting is difficult because unexpected events can change trends suddenly.","zh":"預測困難，因為意外事件可以突然改變趨勢。"},{"en":"This phrase describes prediction under uncertainty.","zh":"這個片語描述不確定情況下的預測。"}],"source":"110 - Change in business organisations.pdf","sourcePage":14},{"front":"be fraught with difficulties","meaning":"充滿困難","examples":[{"en":"Forecasting the future is fraught with difficulties.","zh":"預測未來充滿困難。"},{"en":"To be fraught with difficulties means to be full of problems and risks.","zh":"To be fraught with difficulties 指充滿問題和風險。"},{"en":"Planning an outdoor event in typhoon season is fraught with difficulties.","zh":"在颱風季節規劃戶外活動充滿困難。"},{"en":"Predicting future work is difficult because technology, markets, and people all change.","zh":"預測未來工作很困難，因為科技、市場和人都會改變。"},{"en":"This phrase emphasises that a task is complicated and risky.","zh":"這個片語強調任務複雜且有風險。"}],"source":"110 - Change in business organisations.pdf","sourcePage":14},{"front":"for instance","meaning":"例如","examples":[{"en":"For instance, future studies combine art and science.","zh":"例如，未來研究結合藝術和科學。"},{"en":"For instance means for example.","zh":"For instance 意思是例如。"},{"en":"Some daily habits improve learning; for instance, sleeping enough helps memory.","zh":"一些日常習慣改善學習；例如，睡眠充足有助記憶。"},{"en":"Writers use “for instance” to introduce a concrete example.","zh":"作者使用 “for instance” 來引入具體例子。"},{"en":"This phrase helps make an abstract point clearer.","zh":"這個片語幫助把抽象重點說得更清楚。"}],"source":"110 - Change in business organisations.pdf","sourcePage":14},{"front":"future studies","meaning":"未來研究","examples":[{"en":"Future studies are part art and part science.","zh":"未來研究既是藝術亦是科學。"},{"en":"Future studies are attempts to understand possible future developments using evidence, imagination, and analysis.","zh":"Future studies 是使用證據、想像和分析來理解可能未來發展的嘗試。"},{"en":"A city may use future studies to plan transport for the next thirty years.","zh":"城市可能使用未來研究來規劃未來三十年的交通。"},{"en":"Because the future is uncertain, future studies cannot be purely mechanical prediction.","zh":"因為未來不確定，未來研究不能只是機械式預測。"},{"en":"This phrase describes systematic thinking about possible futures.","zh":"這個片語描述對可能未來的系統思考。"}],"source":"110 - Change in business organisations.pdf","sourcePage":14},{"front":"part art and part science","meaning":"既是藝術亦是科學","examples":[{"en":"Future studies are part art and part science.","zh":"未來研究既是藝術亦是科學。"},{"en":"Part art and part science means something requires both creativity and evidence-based method.","zh":"Part art and part science 指某事同時需要創意和以證據為本的方法。"},{"en":"Good teaching is part art and part science because teachers need data and human judgement.","zh":"好教學既是藝術亦是科學，因為老師需要數據和人的判斷。"},{"en":"Forecasting the future requires numbers, but also imagination about unexpected change.","zh":"預測未來需要數字，也需要對意外變化的想像。"},{"en":"This phrase describes work that combines intuition with analysis.","zh":"這個片語描述結合直覺和分析的工作。"}],"source":"110 - Change in business organisations.pdf","sourcePage":14},{"front":"full of surprises","meaning":"充滿驚喜；充滿意外","examples":[{"en":"The future is full of surprises and uncertainty.","zh":"未來充滿驚喜和不確定性。"},{"en":"Full of surprises means containing many unexpected events or results.","zh":"Full of surprises 指包含許多意想不到的事件或結果。"},{"en":"A school year can be full of surprises when new students, exams, and activities arrive.","zh":"當新學生、考試和活動到來，學年可以充滿意外。"},{"en":"Because the future is full of surprises, fixed plans may need revision.","zh":"因為未來充滿意外，固定計劃可能需要修訂。"},{"en":"This phrase highlights unpredictability.","zh":"這個片語突顯不可預測性。"}],"source":"110 - Change in business organisations.pdf","sourcePage":14},{"front":"uncertainty","meaning":"不確定性","examples":[{"en":"The future involves uncertainty and unexpected changes.","zh":"未來涉及不確定性和意外變化。"},{"en":"Uncertainty is a situation in which people do not know what will happen.","zh":"Uncertainty 是人們不知道會發生甚麼的情況。"},{"en":"Students may feel uncertainty when exam formats change suddenly.","zh":"當考試形式突然改變，學生可能感到不確定性。"},{"en":"In business, uncertainty makes long-term planning harder.","zh":"在商業中，不確定性令長期規劃更困難。"},{"en":"This word describes lack of clear knowledge about future outcomes.","zh":"這個詞描述對未來結果缺乏清晰認知。"}],"source":"110 - Change in business organisations.pdf","sourcePage":14},{"front":"trends and trend breaks","meaning":"趨勢與趨勢中斷","examples":[{"en":"The future includes trends and trend breaks.","zh":"未來包括趨勢與趨勢中斷。"},{"en":"Trends and trend breaks are continuing patterns and sudden interruptions to those patterns.","zh":"Trends and trend breaks 是持續模式和對這些模式的突然中斷。"},{"en":"A school may see a trend of rising enrolment, then a trend break when families move away.","zh":"學校可能看見收生上升趨勢，然後因家庭搬走而出現趨勢中斷。"},{"en":"Businesses must watch both long-term trends and sudden breaks caused by crises.","zh":"企業必須同時留意長期趨勢和由危機造成的突然中斷。"},{"en":"This phrase describes continuity and disruption together.","zh":"這個片語同時描述連續性和中斷。"}],"source":"110 - Change in business organisations.pdf","sourcePage":14},{"front":"irrationality and rationality","meaning":"非理性與理性","examples":[{"en":"The future contains both irrationality and rationality.","zh":"未來同時包含非理性與理性。"},{"en":"Irrationality and rationality mean unreasonable behaviour and logical behaviour existing together.","zh":"Irrationality and rationality 指不理性行為和合乎邏輯行為同時存在。"},{"en":"Consumers may act with rationality when comparing prices but with irrationality when following trends.","zh":"消費者比較價格時可能理性，但跟隨潮流時可能非理性。"},{"en":"Because people are not always logical, future markets can be hard to predict.","zh":"因為人不總是合乎邏輯，未來市場可能難以預測。"},{"en":"This phrase shows that human behaviour mixes reason and emotion.","zh":"這個片語顯示人類行為混合理性和情感。"}],"source":"110 - Change in business organisations.pdf","sourcePage":14},{"front":"escape from our hands","meaning":"從我們手中溜走","examples":[{"en":"The future seems to escape from our hands as time goes by.","zh":"隨着時間過去，未來似乎從我們手中溜走。"},{"en":"To escape from our hands means to become impossible for us to fully control or hold.","zh":"To escape from our hands 指變得無法被我們完全控制或掌握。"},{"en":"A project can escape from our hands if costs rise and deadlines keep changing.","zh":"如果成本上升且期限不斷改變，項目可能從我們手中溜走。"},{"en":"The future escapes from our hands because many people and events shape it.","zh":"未來從我們手中溜走，因為許多人和事件塑造它。"},{"en":"This phrase suggests loss of control.","zh":"這個片語暗示失去控制。"}],"source":"110 - Change in business organisations.pdf","sourcePage":14},{"front":"as time goes by","meaning":"隨着時間過去","examples":[{"en":"The future changes as time goes by.","zh":"隨着時間過去，未來會改變。"},{"en":"As time goes by means while time passes.","zh":"As time goes by 指隨着時間流逝。"},{"en":"As time goes by, students often become more confident with difficult grammar.","zh":"隨着時間過去，學生通常會對困難文法更有信心。"},{"en":"Plans may need updating as time goes by and conditions change.","zh":"隨着時間過去和條件改變，計劃可能需要更新。"},{"en":"This phrase shows gradual development over time.","zh":"這個片語顯示隨時間逐步發展。"}],"source":"110 - Change in business organisations.pdf","sourcePage":14},{"front":"the result of actions taken by","meaning":"由……所採取行動造成的結果","examples":[{"en":"The future is the result of actions taken by many forces.","zh":"未來是由許多力量所採取行動造成的結果。"},{"en":"The result of actions taken by someone or something means the outcome caused by what they do.","zh":"The result of actions taken by someone or something 指由某人或某物行動造成的結果。"},{"en":"A school’s culture is the result of actions taken by teachers, students, and parents.","zh":"學校文化是由老師、學生和家長所採取行動造成的結果。"},{"en":"Business futures are shaped by decisions made by companies, governments, customers, and workers.","zh":"商業未來由公司、政府、顧客和工人的決定塑造。"},{"en":"This phrase connects outcomes with the actions that create them.","zh":"這個片語把結果與創造它們的行動連接起來。"}],"source":"110 - Change in business organisations.pdf","sourcePage":15},{"front":"innumerable forces","meaning":"無數力量","examples":[{"en":"Organisational change is shaped by innumerable forces.","zh":"組織變革由無數力量塑造。"},{"en":"Innumerable forces are too many influences to count easily.","zh":"Innumerable forces 是多到難以輕易計算的影響力。"},{"en":"A child’s learning is shaped by innumerable forces, including sleep, family, teachers, and friends.","zh":"孩子學習由無數力量塑造，包括睡眠、家庭、老師和朋友。"},{"en":"When forces are innumerable, simple predictions become unreliable.","zh":"當力量無數，簡單預測便變得不可靠。"},{"en":"This phrase emphasises great complexity.","zh":"這個片語強調巨大複雜性。"}],"source":"110 - Change in business organisations.pdf","sourcePage":15},{"front":"more or less powerful forces","meaning":"強弱不一的力量","examples":[{"en":"The future is shaped by more or less powerful forces.","zh":"未來由強弱不一的力量塑造。"},{"en":"More or less powerful forces are influences that differ in strength.","zh":"More or less powerful forces 是強度不同的影響力。"},{"en":"A student’s study habits may be shaped by more or less powerful forces such as family support and peer pressure.","zh":"學生學習習慣可能受家庭支援和朋輩壓力等強弱不一的力量塑造。"},{"en":"Some forces change organisations deeply, while others only disturb small routines.","zh":"有些力量深刻改變組織，另一些只干擾小常規。"},{"en":"This phrase shows that not all influences are equally strong.","zh":"這個片語顯示並非所有影響都同樣強。"}],"source":"110 - Change in business organisations.pdf","sourcePage":15},{"front":"what seems certain is that","meaning":"似乎可以肯定的是","examples":[{"en":"What seems certain is that the organisational world is changing quickly.","zh":"似乎可以肯定的是，組織世界正在迅速改變。"},{"en":"What seems certain is that means the writer is confident about this point, even if other things are unclear.","zh":"What seems certain is that 指即使其他事情不清楚，作者對這一點有信心。"},{"en":"What seems certain is that students need clear feedback, even if teaching methods differ.","zh":"似乎可以肯定的是，學生需要清晰回饋，即使教學方法不同。"},{"en":"In uncertain times, one clear fact may still guide planning.","zh":"在不確定時期，一個清晰事實仍可指導規劃。"},{"en":"This phrase introduces a cautious but strong conclusion.","zh":"這個片語引出謹慎但強烈的結論。"}],"source":"110 - Change in business organisations.pdf","sourcePage":15},{"front":"the organisational world","meaning":"組織世界；機構環境","examples":[{"en":"The organisational world is changing at a fast rate.","zh":"組織世界正以很快速度改變。"},{"en":"The organisational world means the broad environment of businesses, institutions, workplaces, and management systems.","zh":"Organisational world 指企業、機構、工作場所和管理制度的廣泛環境。"},{"en":"Schools, companies, charities, and government departments are all part of the organisational world.","zh":"學校、公司、慈善機構和政府部門都是組織世界的一部分。"},{"en":"When the organisational world changes, workers may need new skills and expectations.","zh":"當機構環境改變，工人可能需要新技能和新期望。"},{"en":"This phrase describes the wider world of organisations.","zh":"這個片語描述更廣泛的組織世界。"}],"source":"110 - Change in business organisations.pdf","sourcePage":15},{"front":"at a fast rate","meaning":"以很快的速度","examples":[{"en":"Organisations are changing at a fast rate.","zh":"組織正以很快的速度改變。"},{"en":"At a fast rate means quickly or with high speed.","zh":"At a fast rate 指快速或以高速度。"},{"en":"A student’s vocabulary can grow at a fast rate with daily reading.","zh":"如果每天閱讀，學生詞彙量可以以很快速度增長。"},{"en":"If technology changes at a fast rate, businesses may struggle to keep up.","zh":"如果科技以很快速度改變，企業可能難以跟上。"},{"en":"This phrase describes speed of change or growth.","zh":"這個片語描述改變或增長的速度。"}],"source":"110 - Change in business organisations.pdf","sourcePage":15},{"front":"direction of change","meaning":"變化方向","examples":[{"en":"The direction of change is not always predictable.","zh":"變化方向並非總是可預測。"},{"en":"Direction of change means the way or path in which change is moving.","zh":"Direction of change 指變化正在走向的方式或路徑。"},{"en":"A school may know enrolment is changing but not know the direction of change next year.","zh":"學校可能知道收生正在改變，但不知道明年的變化方向。"},{"en":"If the direction of change is unclear, managers should prepare several options.","zh":"如果變化方向不清楚，管理者應準備幾個選項。"},{"en":"This phrase focuses on where change is heading.","zh":"這個片語著重變化正朝哪裡走。"}],"source":"110 - Change in business organisations.pdf","sourcePage":15},{"front":"not always predictable","meaning":"並非總是可預測","examples":[{"en":"The direction of change is not always predictable.","zh":"變化方向並非總是可預測。"},{"en":"Not always predictable means something cannot be forecast correctly every time.","zh":"Not always predictable 指某事不能每次都被正確預測。"},{"en":"Children’s reactions to a new rule are not always predictable.","zh":"兒童對新規則的反應並非總是可預測。"},{"en":"Markets are not always predictable because people may act emotionally or suddenly change habits.","zh":"市場並非總是可預測，因為人們可能情緒化行動或突然改變習慣。"},{"en":"This phrase warns against overconfidence in predictions.","zh":"這個片語提醒人不要過度自信於預測。"}],"source":"110 - Change in business organisations.pdf","sourcePage":15},{"front":"consequently","meaning":"因此","examples":[{"en":"Consequently, managers need to analyse the causes of change.","zh":"因此，管理者需要分析變化的原因。"},{"en":"Consequently means as a result.","zh":"Consequently 指因此或結果是。"},{"en":"The school library closed for repairs; consequently, students used online books.","zh":"學校圖書館因維修關閉；因此，學生使用網上書籍。"},{"en":"If change is unpredictable, consequently managers need better analysis and preparation.","zh":"如果變革不可預測，因此管理者需要更好分析和準備。"},{"en":"This phrase connects a reason with a logical result.","zh":"這個片語把原因與合乎邏輯的結果連接起來。"}],"source":"110 - Change in business organisations.pdf","sourcePage":15},{"front":"it is crucial that","meaning":"……是至關重要的","examples":[{"en":"It is crucial that managers understand the factors that trigger change.","zh":"管理者了解引發變革的因素是至關重要的。"},{"en":"It is crucial that means it is extremely important that something happens.","zh":"It is crucial that 指某事發生極其重要。"},{"en":"It is crucial that students read the question carefully before answering.","zh":"學生答題前仔細閱讀題目是至關重要的。"},{"en":"If leaders ignore causes of change, they may make poor decisions.","zh":"如果領導者忽視變革原因，可能作出差劣決定。"},{"en":"This phrase signals a point that is essential, not optional.","zh":"這個片語標示某重點是必要的，而不是可有可無。"}],"source":"110 - Change in business organisations.pdf","sourcePage":15},{"front":"organisational managers","meaning":"組織管理者","examples":[{"en":"Organisational managers must understand the causes of change.","zh":"組織管理者必須了解變化的原因。"},{"en":"Organisational managers are people responsible for planning, coordinating, and leading work inside organisations.","zh":"Organisational managers 是負責在組織內規劃、協調和領導工作的人。"},{"en":"A hospital manager must organise staff, budgets, and patient services.","zh":"醫院管理者必須安排員工、預算和病人服務。"},{"en":"Managers who understand change can help employees adapt more calmly.","zh":"了解變革的管理者可以幫助員工更冷靜地適應。"},{"en":"This phrase identifies the people responsible for guiding organisations.","zh":"這個片語指出負責引導組織的人。"}],"source":"110 - Change in business organisations.pdf","sourcePage":15},{"front":"decision makers","meaning":"決策者","examples":[{"en":"Decision makers must analyse the factors behind change.","zh":"決策者必須分析變化背後的因素。"},{"en":"Decision makers are people who have authority to choose actions or policies.","zh":"Decision makers 是有權選擇行動或政策的人。"},{"en":"In a school, decision makers may include principals, department heads, and board members.","zh":"在學校中，決策者可能包括校長、科主任和校董。"},{"en":"If decision makers misunderstand change, they may choose the wrong strategy.","zh":"如果決策者誤解變革，可能選擇錯誤策略。"},{"en":"This phrase focuses on people with responsibility for important choices.","zh":"這個片語著重負責重要選擇的人。"}],"source":"110 - Change in business organisations.pdf","sourcePage":16},{"front":"be aware of","meaning":"意識到","examples":[{"en":"Business leaders should be aware of change-triggering factors.","zh":"商業領袖應意識到引發變革的因素。"},{"en":"To be aware of something means to know about it and pay attention to it.","zh":"To be aware of something 指知道某事並留意它。"},{"en":"Students should be aware of exam deadlines before planning revision.","zh":"學生在規劃溫習前應意識到考試期限。"},{"en":"Managers aware of market trends can prepare earlier than competitors.","zh":"意識到市場趨勢的管理者可以比競爭對手更早準備。"},{"en":"This phrase means more than simply hearing about something; it includes attention and understanding.","zh":"這個片語不只是聽過某事，還包括關注和理解。"}],"source":"110 - Change in business organisations.pdf","sourcePage":16},{"front":"able to analyse","meaning":"能夠分析","examples":[{"en":"Managers must be able to analyse organisational change.","zh":"管理者必須能夠分析組織變革。"},{"en":"To be able to analyse something means to understand it by examining its parts, causes, and effects.","zh":"To be able to analyse something 指透過檢視其部分、原因和影響來理解它。"},{"en":"A teacher should be able to analyse why a class performed badly on a test.","zh":"老師應能夠分析一個班測驗表現差的原因。"},{"en":"Managers who analyse change can identify risks and choose better responses.","zh":"能分析變革的管理者可以辨認風險並選擇更好回應。"},{"en":"This phrase focuses on careful thinking, not quick guessing.","zh":"這個片語著重仔細思考，而不是快速猜測。"}],"source":"110 - Change in business organisations.pdf","sourcePage":16},{"front":"factors which trigger","meaning":"引發……的因素","examples":[{"en":"Managers need to understand the factors which trigger organisational change.","zh":"管理者需要了解引發組織變革的因素。"},{"en":"Factors which trigger something are causes that start it or set it in motion.","zh":"Factors which trigger something 是啟動某事或令其開始的原因。"},{"en":"A school may study factors which trigger student stress, such as exams and homework load.","zh":"學校可能研究引發學生壓力的因素，例如考試和功課量。"},{"en":"If managers know what triggers change, they can respond before problems grow.","zh":"如果管理者知道甚麼引發變革，便可以在問題擴大前回應。"},{"en":"This phrase focuses on starting causes.","zh":"這個片語著重起始原因。"}],"source":"110 - Change in business organisations.pdf","sourcePage":16},{"front":"organisational change","meaning":"組織變革","examples":[{"en":"Organisational change can be triggered by many external forces.","zh":"組織變革可以由許多外部力量引發。"},{"en":"Organisational change is a change in how an organisation is structured, managed, or operated.","zh":"Organisational change 是組織在架構、管理或運作方式上的改變。"},{"en":"A school undergoes organisational change when it creates new departments or changes leadership roles.","zh":"當學校建立新部門或改變領導角色，它就經歷組織變革。"},{"en":"Organisational change may be caused by technology, competition, law, or customer demand.","zh":"組織變革可能由科技、競爭、法律或顧客需求造成。"},{"en":"This phrase describes change at the level of the whole organisation.","zh":"這個片語描述整個組織層面的改變。"}],"source":"110 - Change in business organisations.pdf","sourcePage":16},{"front":"contains the following information","meaning":"包含以下資料","examples":[{"en":"Students must identify which paragraph contains the following information.","zh":"學生必須辨認哪一段包含以下資料。"},{"en":"Contains the following information means includes the details listed after the instruction.","zh":"Contains the following information 指包括指示後列出的細節。"},{"en":"In a reading test, students scan for the paragraph that contains the required idea.","zh":"在閱讀測驗中，學生掃讀包含所需意思的段落。"},{"en":"A paragraph may contain the information even if the wording is different.","zh":"即使用字不同，某段落仍可能包含該資料。"},{"en":"This phrase is common in paragraph-matching questions.","zh":"這個片語常見於段落配對題。"}],"source":"110 - Change in business organisations.pdf","sourcePage":16},{"front":"specific predictions","meaning":"具體預測","examples":[{"en":"The passage includes specific predictions about future work.","zh":"文章包括關於未來工作的具體預測。"},{"en":"Specific predictions are clear statements about what may happen in the future.","zh":"Specific predictions 是關於未來可能發生甚麼的清晰陳述。"},{"en":"A school may make specific predictions about next year’s student numbers.","zh":"學校可能對明年學生人數作出具體預測。"},{"en":"Specific predictions can be useful, but they may be wrong if conditions change.","zh":"具體預測可以有用，但如果條件改變，它們可能錯誤。"},{"en":"This phrase contrasts detailed forecasts with vague guesses.","zh":"這個片語把詳細預測與模糊猜測作對比。"}],"source":"110 - Change in business organisations.pdf","sourcePage":16},{"front":"businesses and working practices","meaning":"商業和工作模式","examples":[{"en":"The predictions concern businesses and working practices.","zh":"這些預測關於商業和工作模式。"},{"en":"Businesses and working practices means companies and the ways people do their work.","zh":"Businesses and working practices 指公司以及人們工作的方式。"},{"en":"Working from home affects both businesses and working practices.","zh":"在家工作同時影響商業和工作模式。"},{"en":"New technology can change business models and daily work routines at the same time.","zh":"新科技可以同時改變商業模式和日常工作常規。"},{"en":"This phrase connects organisations with everyday work methods.","zh":"這個片語把組織與日常工作方法連接起來。"}],"source":"110 - Change in business organisations.pdf","sourcePage":16},{"front":"a reference to","meaning":"對……的提及","examples":[{"en":"The question asks for a reference to how employees were managed.","zh":"問題要求找出對員工如何被管理的提及。"},{"en":"A reference to something is a mention of it in a text.","zh":"A reference to something 是文本中對某事的提及。"},{"en":"A passage may include a reference to school uniforms without discussing them in detail.","zh":"文章可能提及校服，但沒有詳細討論。"},{"en":"Finding a reference requires noticing both direct words and paraphrased ideas.","zh":"找出提及需要留意直接字詞和改寫意思。"},{"en":"This phrase is common in reading questions asking where an idea appears.","zh":"這個片語常見於詢問某想法出現在哪裡的閱讀題。"}],"source":"110 - Change in business organisations.pdf","sourcePage":16},{"front":"company employees","meaning":"公司僱員","examples":[{"en":"Company employees were managed through strict hierarchies.","zh":"公司僱員透過嚴格等級制度被管理。"},{"en":"Company employees are people who work for a business organisation.","zh":"Company employees 是為商業機構工作的人。"},{"en":"Company employees may include managers, clerks, factory workers, and sales staff.","zh":"公司僱員可能包括經理、文員、工廠工人和銷售員。"},{"en":"When employees are managed through strict structures, decision-making may be centralised.","zh":"當僱員透過嚴格架構被管理，決策可能集中於上層。"},{"en":"This phrase identifies workers inside a company.","zh":"這個片語指出公司內部的工人。"}],"source":"110 - Change in business organisations.pdf","sourcePage":16},{"front":"usually managed","meaning":"通常被管理","examples":[{"en":"The passage describes how employees were usually managed.","zh":"文章描述員工通常如何被管理。"},{"en":"Usually managed means commonly directed, controlled, or supervised in a particular way.","zh":"Usually managed 指通常以某種方式被指導、控制或監督。"},{"en":"In some schools, students are usually managed through clear routines and class rules.","zh":"在一些學校，學生通常透過清晰常規和班規被管理。"},{"en":"How people are managed affects their flexibility, motivation, and performance.","zh":"人們如何被管理會影響他們的彈性、動機和表現。"},{"en":"This phrase asks about the normal method of management.","zh":"這個片語詢問正常管理方式。"}],"source":"110 - Change in business organisations.pdf","sourcePage":16},{"front":"a warning for","meaning":"對……的警告","examples":[{"en":"The final paragraph gives a warning for business leaders.","zh":"最後一段給商業領袖一個警告。"},{"en":"A warning for someone is advice that alerts them to a risk or danger.","zh":"Warning for someone 是提醒某人注意風險或危險的建議。"},{"en":"A doctor may give a warning for patients who ignore high blood pressure.","zh":"醫生可能對忽視高血壓的病人發出警告。"},{"en":"A warning for leaders can help them prepare before problems become serious.","zh":"對領導者的警告可以幫助他們在問題變嚴重前準備。"},{"en":"This phrase introduces caution directed at a particular group.","zh":"這個片語引出針對特定群體的提醒。"}],"source":"110 - Change in business organisations.pdf","sourcePage":17},{"front":"business leaders","meaning":"商業領袖","examples":[{"en":"Business leaders must understand the factors that trigger change.","zh":"商業領袖必須了解引發變革的因素。"},{"en":"Business leaders are people who guide companies, make decisions, and set direction.","zh":"Business leaders 是引導公司、作決定和設定方向的人。"},{"en":"A business leader may decide whether a company should enter a new market.","zh":"商業領袖可能決定公司是否應進入新市場。"},{"en":"Leaders who understand change can help workers adapt instead of panic.","zh":"了解變革的領袖可以幫助工人適應，而不是恐慌。"},{"en":"This phrase refers to people with responsibility for organisational direction.","zh":"這個片語指負責組織方向的人。"}],"source":"110 - Change in business organisations.pdf","sourcePage":17},{"front":"an era notable for","meaning":"以……著稱的時代","examples":[{"en":"The agricultural age was an era notable for stability.","zh":"農業時代是以穩定著稱的時代。"},{"en":"An era notable for something is a period known especially for that feature.","zh":"An era notable for something 是特別以某特徵聞名的時期。"},{"en":"The early internet was an era notable for rapid experimentation.","zh":"早期互聯網是以快速實驗著稱的時代。"},{"en":"If an era is notable for stability, change may be slow and predictable.","zh":"如果一個時代以穩定著稱，變化可能緩慢而可預測。"},{"en":"This phrase identifies what makes a historical period stand out.","zh":"這個片語指出某歷史時期因何突出。"}],"source":"110 - Change in business organisations.pdf","sourcePage":17},{"front":"relative absence of change","meaning":"相對缺乏變化","examples":[{"en":"The agricultural age had a relative absence of change.","zh":"農業時代相對缺乏變化。"},{"en":"Relative absence of change means there was much less change compared with other periods.","zh":"Relative absence of change 指與其他時期相比變化少得多。"},{"en":"A small village may have a relative absence of change if families and jobs stay the same for decades.","zh":"如果家庭和工作數十年保持相同，小村莊可能相對缺乏變化。"},{"en":"Relative absence of change can make routines predictable but may limit innovation.","zh":"相對缺乏變化可以令常規可預測，但可能限制創新。"},{"en":"This phrase means change was low, not completely impossible.","zh":"這個片語表示變化較少，而不是完全不可能有變化。"}],"source":"110 - Change in business organisations.pdf","sourcePage":17},{"front":"customer satisfaction","meaning":"顧客滿意度","examples":[{"en":"Customer satisfaction was not always a high priority.","zh":"顧客滿意度並不總是高優先事項。"},{"en":"Customer satisfaction is how happy customers are with a product, service, or experience.","zh":"Customer satisfaction 是顧客對產品、服務或體驗有多滿意。"},{"en":"A restaurant improves customer satisfaction by serving food quickly and politely.","zh":"餐廳透過快速而有禮地上菜來改善顧客滿意度。"},{"en":"When supply is limited, companies may ignore customer satisfaction because customers have few alternatives.","zh":"當供應有限，公司可能忽視顧客滿意度，因為顧客選擇很少。"},{"en":"This phrase focuses on how customers judge value and service.","zh":"這個片語著重顧客如何評價價值和服務。"}],"source":"110 - Change in business organisations.pdf","sourcePage":17},{"front":"a high priority","meaning":"高優先事項","examples":[{"en":"Customer satisfaction was not a high priority when supply was limited.","zh":"當供應有限，顧客滿意度不是高優先事項。"},{"en":"A high priority is something considered very important and dealt with early.","zh":"High priority 是被視為非常重要並優先處理的事情。"},{"en":"In a hospital, patient safety is a high priority.","zh":"在醫院中，病人安全是高優先事項。"},{"en":"If production is the highest priority, customer choice may receive less attention.","zh":"如果生產是最高優先事項，顧客選擇可能得到較少注意。"},{"en":"This phrase shows what matters most in decision-making.","zh":"這個片語顯示決策中甚麼最重要。"}],"source":"110 - Change in business organisations.pdf","sourcePage":17},{"front":"look at the following characteristics","meaning":"查看以下特徵","examples":[{"en":"Students look at the following characteristics and match them to periods.","zh":"學生查看以下特徵，並把它們與時期配對。"},{"en":"Look at the following characteristics means read the listed features carefully before answering.","zh":"Look at the following characteristics 指答題前仔細閱讀列出的特徵。"},{"en":"In a matching task, students must connect each feature with the correct category.","zh":"在配對題中，學生必須把每個特徵連接到正確類別。"},{"en":"Looking at characteristics first can help students scan the passage more efficiently.","zh":"先查看特徵可以幫助學生更有效掃讀文章。"},{"en":"This phrase is a reading-test instruction.","zh":"這個片語是閱讀測驗指示。"}],"source":"110 - Change in business organisations.pdf","sourcePage":17},{"front":"list of periods","meaning":"時期列表","examples":[{"en":"The question provides a list of periods.","zh":"題目提供一份時期列表。"},{"en":"A list of periods is a set of historical times or stages given as answer choices.","zh":"List of periods 是作為答案選項提供的一組歷史時期或階段。"},{"en":"A history worksheet may give a list of periods such as ancient, medieval, and modern.","zh":"歷史工作紙可能提供古代、中世紀和現代等時期列表。"},{"en":"Students use the list to match details with the correct time period.","zh":"學生使用該列表，把細節與正確時期配對。"},{"en":"This phrase refers to answer options organised by time.","zh":"這個片語指按時間組織的答案選項。"}],"source":"110 - Change in business organisations.pdf","sourcePage":17},{"front":"match each characteristic with","meaning":"將每個特徵與……配對","examples":[{"en":"Students match each characteristic with the correct period.","zh":"學生將每個特徵與正確時期配對。"},{"en":"To match each characteristic with something means to connect each feature to the right answer.","zh":"To match each characteristic with something 指把每個特徵連接到正確答案。"},{"en":"Students may match each characteristic with a person, place, or historical period.","zh":"學生可能將每個特徵與人物、地方或歷史時期配對。"},{"en":"Careful matching requires understanding meaning, not just recognising words.","zh":"仔細配對需要理解意思，而不只是認出字詞。"},{"en":"This phrase describes a pairing task in reading tests.","zh":"這個片語描述閱讀測驗中的配對任務。"}],"source":"110 - Change in business organisations.pdf","sourcePage":17},{"front":"the correct period","meaning":"正確時期","examples":[{"en":"Each characteristic belongs to the correct historical period.","zh":"每個特徵屬於正確歷史時期。"},{"en":"The correct period is the time stage that matches the information accurately.","zh":"Correct period 是與資料準確相符的時間階段。"},{"en":"If a feature describes factories and machines, the correct period may be the industrial age.","zh":"如果某特徵描述工廠和機器，正確時期可能是工業時代。"},{"en":"Choosing the correct period requires evidence from the passage.","zh":"選擇正確時期需要來自文章的證據。"},{"en":"This phrase focuses on accurate historical matching.","zh":"這個片語著重準確歷史配對。"}],"source":"110 - Change in business organisations.pdf","sourcePage":17},{"front":"use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"The instructions say students may use any letter more than once.","zh":"指示說學生可重複使用任何字母。"},{"en":"Use any letter more than once means the same answer option can be repeated.","zh":"Use any letter more than once 指同一答案選項可以重複使用。"},{"en":"In a matching question, two characteristics may both belong to the same period.","zh":"在配對題中，兩個特徵可能都屬於同一時期。"},{"en":"Students should not force every answer to be different if repetition is allowed.","zh":"如果容許重複，學生不應強迫每個答案都不同。"},{"en":"This instruction prevents a common exam mistake.","zh":"這個指示防止常見考試錯誤。"}],"source":"110 - Change in business organisations.pdf","sourcePage":17},{"front":"a surplus of goods","meaning":"商品過剩","examples":[{"en":"A surplus of goods appeared when supply overtook demand.","zh":"當供應超過需求時，商品過剩出現。"},{"en":"A surplus of goods means more products are available than customers want to buy.","zh":"Surplus of goods 指可供應產品多於顧客想購買的數量。"},{"en":"A shop may have a surplus of umbrellas after a dry summer.","zh":"乾燥夏天過後，商店可能有雨傘過剩。"},{"en":"When there is a surplus, businesses may cut prices or search for new markets.","zh":"當出現過剩，企業可能減價或尋找新市場。"},{"en":"This phrase describes over-supply.","zh":"這個片語描述供應過多。"}],"source":"110 - Change in business organisations.pdf","sourcePage":18},{"front":"emphasis on production quantity","meaning":"強調生產數量","examples":[{"en":"The industrial age placed emphasis on production quantity.","zh":"工業時代強調生產數量。"},{"en":"Emphasis on production quantity means priority is given to making more goods.","zh":"Emphasis on production quantity 指把優先事項放在製造更多商品上。"},{"en":"A factory may place emphasis on quantity when demand is high and customers are waiting.","zh":"當需求高而顧客正在等待，工廠可能強調生產數量。"},{"en":"Focusing too much on quantity may reduce attention to quality or service.","zh":"過度集中於數量可能減少對質素或服務的注意。"},{"en":"This phrase describes a production-first mindset.","zh":"這個片語描述生產優先的思維。"}],"source":"110 - Change in business organisations.pdf","sourcePage":18},{"front":"proximity of consumers to workplaces","meaning":"消費者與工作場所相近","examples":[{"en":"The agricultural age involved the proximity of consumers to workplaces.","zh":"農業時代涉及消費者與工作場所相近。"},{"en":"Proximity of consumers to workplaces means customers and workers were physically close to where production happened.","zh":"Proximity of consumers to workplaces 指顧客和工人與生產地點在實體距離上接近。"},{"en":"In a village, consumers may buy food directly from farms near their homes.","zh":"在村莊中，消費者可能直接從家附近的農場購買食物。"},{"en":"When markets are local, distance between producers and consumers is often short.","zh":"當市場是本地的，生產者與消費者之間距離通常較短。"},{"en":"This phrase describes closeness between where people live, work, and buy.","zh":"這個片語描述人們居住、工作和購買地點之間的接近性。"}],"source":"110 - Change in business organisations.pdf","sourcePage":18},{"front":"focus on the quality of goods","meaning":"注重商品質素","examples":[{"en":"The neo-industrial age placed more focus on the quality of goods.","zh":"新工業時代更注重商品質素。"},{"en":"Focus on the quality of goods means paying more attention to how good, reliable, or useful products are.","zh":"Focus on the quality of goods 指更重視產品有多好、可靠或有用。"},{"en":"A clothing brand may focus on quality by using stronger fabric and better stitching.","zh":"服裝品牌可能透過使用更結實布料和更好車線來注重質素。"},{"en":"When customers have many choices, quality becomes a stronger selling point.","zh":"當顧客有很多選擇，質素便成為更強賣點。"},{"en":"This phrase contrasts with focusing only on producing more.","zh":"這個片語與只集中生產更多形成對比。"}],"source":"110 - Change in business organisations.pdf","sourcePage":18},{"front":"new products and new ways of working","meaning":"新產品和新工作方式","examples":[{"en":"Modern organisations face new products and new ways of working.","zh":"現代組織面對新產品和新工作方式。"},{"en":"New products and new ways of working are fresh goods, services, methods, and work arrangements.","zh":"New products and new ways of working 是新的商品、服務、方法和工作安排。"},{"en":"A school may use new products such as tablets and new ways of working such as online lessons.","zh":"學校可能使用平板電腦等新產品，以及網上課堂等新工作方式。"},{"en":"When new products appear, workers often need new processes and skills.","zh":"當新產品出現，工人常需要新流程和新技能。"},{"en":"This phrase links innovation in what is sold with innovation in how work is done.","zh":"這個片語把出售內容的創新與工作方式的創新連接起來。"}],"source":"110 - Change in business organisations.pdf","sourcePage":18},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students must complete the summary below using words from the passage.","zh":"學生必須使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in the missing words in the summary that follows.","zh":"Complete the summary below 指填寫下面摘要中的缺失字詞。"},{"en":"Students should read the whole summary first to understand the grammar and meaning.","zh":"學生應先閱讀整個摘要，以理解文法和意思。"},{"en":"Correct answers must fit the passage and the sentence structure.","zh":"正確答案必須符合文章和句子結構。"},{"en":"This phrase is a common reading-test instruction.","zh":"這個片語是常見閱讀測驗指示。"}],"source":"110 - Change in business organisations.pdf","sourcePage":18},{"front":"one word only","meaning":"只限一個詞","examples":[{"en":"The answers must use one word only from the passage.","zh":"答案必須只使用文章中的一個詞。"},{"en":"One word only means the answer must contain exactly one word and no more.","zh":"One word only 指答案只能包含一個詞，不能更多。"},{"en":"If the answer requires one word only, “working life” would be too long.","zh":"如果答案只限一個詞，“working life” 就太長。"},{"en":"Students should copy the exact word from the passage when the instruction is strict.","zh":"當指示嚴格，學生應從文章中抄寫準確的詞。"},{"en":"This phrase controls answer length very tightly.","zh":"這個片語非常嚴格地控制答案長度。"}],"source":"110 - Change in business organisations.pdf","sourcePage":18},{"front":"the Twenty-First Century","meaning":"二十一世紀","examples":[{"en":"The summary discusses businesses in the Twenty-First Century.","zh":"摘要討論二十一世紀的企業。"},{"en":"The Twenty-First Century means the years from 2001 to 2100.","zh":"Twenty-First Century 指2001年至2100年。"},{"en":"In the Twenty-First Century, many people use digital tools for work and study.","zh":"在二十一世紀，許多人使用數碼工具工作和學習。"},{"en":"Businesses in this century often face rapid technological and social change.","zh":"本世紀的企業常面對快速科技和社會變化。"},{"en":"This phrase places the discussion in the modern era.","zh":"這個片語把討論放在現代時代中。"}],"source":"110 - Change in business organisations.pdf","sourcePage":18},{"front":"it is generally agreed that","meaning":"一般認為","examples":[{"en":"It is generally agreed that organisational change is speeding up.","zh":"一般認為組織變革正在加速。"},{"en":"It is generally agreed that means most people or experts accept the statement as true.","zh":"It is generally agreed that 指大多數人或專家接受該說法為真。"},{"en":"It is generally agreed that children learn better when they feel safe.","zh":"一般認為孩子感到安全時學得更好。"},{"en":"When something is generally agreed, it is less controversial than a personal opinion.","zh":"當某事被一般認同，它比個人意見較少爭議。"},{"en":"This phrase introduces a broad consensus.","zh":"這個片語引出廣泛共識。"}],"source":"110 - Change in business organisations.pdf","sourcePage":18},{"front":"take place more quickly","meaning":"發生得更快","examples":[{"en":"Changes are taking place more quickly now.","zh":"變化現在發生得更快。"},{"en":"To take place more quickly means to happen faster than before.","zh":"To take place more quickly 指比以前更快發生。"},{"en":"Online trends take place more quickly than old newspaper trends.","zh":"網上潮流比舊報紙潮流發生得更快。"},{"en":"If workplace changes take place more quickly, workers need to learn faster.","zh":"如果工作場所變化發生得更快，工人需要學得更快。"},{"en":"This phrase describes increased speed of events.","zh":"這個片語描述事件速度增加。"}],"source":"110 - Change in business organisations.pdf","sourcePage":18},{"front":"organisations are being transformed","meaning":"機構正在被轉變","examples":[{"en":"Organisations are being transformed by rapid change.","zh":"機構正在被快速變化轉變。"},{"en":"Organisations are being transformed means they are undergoing deep and significant change.","zh":"Organisations are being transformed 指它們正在經歷深刻而重要的改變。"},{"en":"Schools are being transformed when digital tools change teaching, homework, and communication.","zh":"當數碼工具改變教學、功課和溝通，學校正在被轉變。"},{"en":"Transformation can affect structure, culture, jobs, and strategy.","zh":"轉變可以影響架構、文化、職位和策略。"},{"en":"This phrase describes major change happening now.","zh":"這個片語描述正在發生的重大改變。"}],"source":"110 - Change in business organisations.pdf","sourcePage":18},{"front":"one leading economist","meaning":"一位著名經濟師","examples":[{"en":"One leading economist made predictions about work by 2020.","zh":"一位著名經濟師對2020年前的工作作出預測。"},{"en":"One leading economist means one well-known or influential expert in economics.","zh":"One leading economist 指一位知名或有影響力的經濟學專家。"},{"en":"A leading economist may advise governments on jobs, inflation, and growth.","zh":"著名經濟師可能就就業、通脹和增長向政府提供建議。"},{"en":"Predictions from a leading economist may influence public debate.","zh":"著名經濟師的預測可能影響公共討論。"},{"en":"This phrase introduces an expert source.","zh":"這個片語引出專家來源。"}],"source":"110 - Change in business organisations.pdf","sourcePage":19},{"front":"up to a quarter of","meaning":"多達四分之一的……","examples":[{"en":"Up to a quarter of employees may become temporary workers.","zh":"多達四分之一的員工可能成為臨時工。"},{"en":"Up to a quarter of means as much as 25 per cent, but possibly less.","zh":"Up to a quarter of 指最多25%，但也可能較少。"},{"en":"Up to a quarter of a class may need extra help before an exam.","zh":"一個班多達四分之一學生可能在考試前需要額外幫助。"},{"en":"If up to a quarter of workers become temporary, employment patterns will change greatly.","zh":"如果多達四分之一工人成為臨時工，就業模式將大幅改變。"},{"en":"This phrase gives an upper-limit estimate.","zh":"這個片語提供上限估計。"}],"source":"110 - Change in business organisations.pdf","sourcePage":19},{"front":"be based in","meaning":"以……為工作基地","examples":[{"en":"Many employees may be based in the home.","zh":"許多員工可能以家中為工作基地。"},{"en":"To be based in a place means to have that place as the main location for work or activity.","zh":"To be based in a place 指以該地方作為工作或活動的主要地點。"},{"en":"A freelance designer may be based in a small home office.","zh":"自由設計師可能以家中的小辦公室為工作基地。"},{"en":"If workers are based at home, companies need strong online communication systems.","zh":"如果工人以家中為工作基地，公司需要強大的網上溝通系統。"},{"en":"This phrase describes the main working location.","zh":"這個片語描述主要工作地點。"}],"source":"110 - Change in business organisations.pdf","sourcePage":19},{"front":"although predictions can be wrong","meaning":"雖然預測可能錯誤","examples":[{"en":"Although predictions can be wrong, the speed of change is clear.","zh":"雖然預測可能錯誤，變化速度是清楚的。"},{"en":"Although predictions can be wrong means future forecasts may not come true.","zh":"Although predictions can be wrong 指對未來的預測未必會成真。"},{"en":"Although weather predictions can be wrong, carrying an umbrella may still be wise.","zh":"雖然天氣預測可能錯誤，帶雨傘仍可能明智。"},{"en":"Even when exact forecasts fail, the general trend may still be obvious.","zh":"即使精確預測失敗，一般趨勢仍可能明顯。"},{"en":"This phrase balances uncertainty with a broader point.","zh":"這個片語平衡不確定性和較廣泛重點。"}],"source":"110 - Change in business organisations.pdf","sourcePage":19},{"front":"not in doubt","meaning":"毫無疑問","examples":[{"en":"The speed of change is not in doubt.","zh":"變化速度毫無疑問。"},{"en":"Not in doubt means not uncertain or not seriously questioned.","zh":"Not in doubt 指不確定性不大，或沒有受到嚴重質疑。"},{"en":"The need for clean water is not in doubt, even if people argue about how to provide it.","zh":"清潔食水的需要毫無疑問，即使人們爭論如何提供。"},{"en":"Even if future details are uncertain, the fact that change is fast may not be in doubt.","zh":"即使未來細節不確定，變化快速這個事實可能毫無疑問。"},{"en":"This phrase marks something as clear or accepted.","zh":"這個片語把某事標示為清楚或被接受。"}],"source":"110 - Change in business organisations.pdf","sourcePage":19},{"front":"need to understand","meaning":"需要了解","examples":[{"en":"Business leaders need to understand the factors behind change.","zh":"商業領袖需要了解變化背後的因素。"},{"en":"Need to understand means must know and make sense of something.","zh":"Need to understand 指必須知道並理解某事。"},{"en":"Students need to understand the question before writing an answer.","zh":"學生在寫答案前需要了解題目。"},{"en":"Leaders who understand causes can respond more wisely than those who only react.","zh":"了解原因的領袖，比只作反應的領袖能更明智地回應。"},{"en":"This phrase shows that understanding is necessary, not optional.","zh":"這個片語顯示理解是必要的，而不是可有可無。"}],"source":"110 - Change in business organisations.pdf","sourcePage":19},{"front":"be influential","meaning":"具影響力","examples":[{"en":"Managers need to understand the factors that will be influential.","zh":"管理者需要了解將會具影響力的因素。"},{"en":"To be influential means to have the power to affect decisions, behaviour, or events.","zh":"To be influential 指有能力影響決定、行為或事件。"},{"en":"A teacher can be influential if students trust their advice and follow their habits.","zh":"如果學生信任老師的建議並跟隨其習慣，老師便可以很具影響力。"},{"en":"In business, technology and customer expectations can be highly influential forces.","zh":"在商業中，科技和顧客期望可以是高度具影響力的力量。"},{"en":"This phrase describes something that strongly shapes what happens next.","zh":"這個片語描述能強烈塑造下一步發展的事物。"}],"source":"110 - Change in business organisations.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 111":[{"front":"an assessment of","meaning":"對……的評估","examples":[{"en":"The passage gives an assessment of micro-wind turbines.","zh":"文章對微型風力渦輪機作出評估。"},{"en":"An assessment of something is a careful judgement about its value, quality, cost, or usefulness.","zh":"an assessment of something 指對某事的價值、質素、成本或用途作出仔細判斷。"},{"en":"A teacher may give an assessment of a student’s writing after reading several essays.","zh":"老師可能在閱讀幾篇作文後，對學生的寫作作出評估。"},{"en":"A good assessment of a product considers both its benefits and its hidden costs.","zh":"對產品的良好評估會同時考慮其好處和隱藏成本。"},{"en":"This phrase is often used when someone weighs evidence before giving an opinion.","zh":"這個短語常用於某人在給出意見前衡量證據。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":1},{"front":"micro-wind turbines","meaning":"微型風力渦輪機","examples":[{"en":"Micro-wind turbines can generate electricity for private use.","zh":"微型風力渦輪機可以為私人用途發電。"},{"en":"Micro-wind turbines are small wind turbines designed to produce electricity on a small scale.","zh":"micro-wind turbines 指設計用於小規模發電的小型風力渦輪機。"},{"en":"A farmer may install micro-wind turbines if the land is open and windy.","zh":"如果土地開闊而多風，農夫可能安裝微型風力渦輪機。"},{"en":"Micro-wind turbines can reduce electricity bills, but only if the site has enough wind.","zh":"微型風力渦輪機可以減少電費，但前提是地點有足夠風力。"},{"en":"This phrase refers to small private turbines, not large wind farms.","zh":"這個短語指小型私人渦輪機，而不是大型風電場。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":1},{"front":"in terms of","meaning":"就……而言","examples":[{"en":"In terms of micro-renewable energy sources, a 15-kW turbine is relatively large.","zh":"就微型可再生能源而言，十五千瓦渦輪機算是相對大型。"},{"en":"In terms of something means when considering that particular aspect or category.","zh":"in terms of something 指從某個特定方面或類別來看。"},{"en":"In terms of cost, taking the bus is usually cheaper than driving.","zh":"就成本而言，乘巴士通常比駕車便宜。"},{"en":"A school may be strong in terms of exam results but weak in terms of student wellbeing.","zh":"一所學校就考試成績而言可能很強，但就學生福祉而言可能較弱。"},{"en":"This phrase helps limit the discussion to one angle.","zh":"這個短語幫助把討論限制在某一角度。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":1},{"front":"micro-renewable energy sources","meaning":"微型可再生能源","examples":[{"en":"Micro-renewable energy sources are suitable for small-scale private use.","zh":"微型可再生能源適合小規模私人使用。"},{"en":"Micro-renewable energy sources are small systems that produce energy from natural sources such as wind or sunlight.","zh":"micro-renewable energy sources 指利用風力或陽光等自然來源生產能源的小型系統。"},{"en":"A household solar panel can be a micro-renewable energy source if it serves one home.","zh":"如果家用太陽能板只供一個家庭使用，它可以是微型可再生能源。"},{"en":"These sources can reduce dependence on the grid, but their output depends on local conditions.","zh":"這些能源可以減少對電網的依賴，但其輸出取決於本地條件。"},{"en":"This phrase focuses on small renewable systems rather than national energy projects.","zh":"這個短語著重小型可再生系統，而不是國家級能源項目。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":1},{"front":"suitable for private use","meaning":"適合私人使用","examples":[{"en":"Some renewable energy sources are suitable for private use.","zh":"有些可再生能源適合私人使用。"},{"en":"Suitable for private use means appropriate for individuals, households, or small organisations to own or operate.","zh":"suitable for private use 指適合個人、家庭或小型機構擁有或操作。"},{"en":"A small solar charger is suitable for private use because one person can use it easily.","zh":"小型太陽能充電器適合私人使用，因為一個人也能輕易使用。"},{"en":"Equipment may be unsuitable for private use if it is too large, dangerous, or expensive.","zh":"如果設備太大、危險或昂貴，就可能不適合私人使用。"},{"en":"This phrase contrasts personal use with industrial or public use.","zh":"這個短語把個人用途與工業或公共用途作對比。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":1},{"front":"a 15-kilowatt turbine","meaning":"十五千瓦渦輪機","examples":[{"en":"A 15-kilowatt turbine is at the largest end of the micro-turbine spectrum.","zh":"十五千瓦渦輪機屬於微型渦輪機範圍中最大型的一端。"},{"en":"A 15-kilowatt turbine is a wind turbine with a maximum power output of 15 kilowatts.","zh":"a 15-kilowatt turbine 指最大功率輸出為十五千瓦的風力渦輪機。"},{"en":"A small village school might consider a 15-kilowatt turbine if it has enough open windy land.","zh":"如果有足夠開闊而多風的土地，小村學校可能考慮十五千瓦渦輪機。"},{"en":"Because it is powerful for a micro-turbine, it needs space, money, and a suitable location.","zh":"因為它對微型渦輪機而言較有力，所以需要空間、金錢和合適地點。"},{"en":"This phrase describes the turbine’s output capacity, not its actual yearly production.","zh":"這個短語描述渦輪機的輸出能力，而不是實際全年發電量。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":1},{"front":"at the biggest end of the spectrum","meaning":"屬於最大型的一端","examples":[{"en":"A 15-kW turbine is at the biggest end of the spectrum.","zh":"十五千瓦渦輪機屬於最大型的一端。"},{"en":"At the biggest end of the spectrum means among the largest examples within a range.","zh":"at the biggest end of the spectrum 指在某個範圍中屬於最大型例子之一。"},{"en":"A family car is not at the biggest end of the vehicle spectrum, but a double-decker bus is.","zh":"家庭車不是車輛範圍中最大型的一端，但雙層巴士是。"},{"en":"When something is at the biggest end of the spectrum, it usually costs more and needs more space.","zh":"當某物屬於最大型的一端，它通常成本較高，也需要更多空間。"},{"en":"This phrase helps compare one item with smaller and larger options.","zh":"這個短語幫助把一件事物與較小和較大的選項比較。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":1},{"front":"a nine-metre diameter","meaning":"九米直徑","examples":[{"en":"The turbine has a nine-metre diameter.","zh":"這部渦輪機有九米直徑。"},{"en":"A nine-metre diameter means the circular part is nine metres across from one side to the other.","zh":"a nine-metre diameter 指圓形部分從一邊到另一邊相距九米。"},{"en":"A playground roundabout with a nine-metre diameter would need a very wide space.","zh":"一個九米直徑的遊樂場旋轉設施會需要很寬闊的空間。"},{"en":"A larger diameter can allow a turbine to catch more wind.","zh":"較大直徑可以讓渦輪機捕捉更多風力。"},{"en":"This phrase describes width across a circle, not height.","zh":"這個短語描述圓形的橫向寬度，而不是高度。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":1},{"front":"a pole as high as","meaning":"一支高度相當於……的柱","examples":[{"en":"The turbine has a pole as high as a four-storey house.","zh":"這部渦輪機有一支高度相當於四層高房屋的柱。"},{"en":"A pole as high as something means a pole reaching roughly the same height as that thing.","zh":"a pole as high as something 指一支柱的高度大約與某物相同。"},{"en":"A school flagpole as high as a small tree would be visible from the road.","zh":"一支高度相當於小樹的學校旗杆，從馬路也能看見。"},{"en":"A very high pole may catch stronger wind, but it may also require permission and safety checks.","zh":"很高的柱可能捕捉更強風力，但也可能需要許可和安全檢查。"},{"en":"This phrase helps readers imagine height through a familiar comparison.","zh":"這個短語透過熟悉比較幫助讀者想像高度。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":1},{"front":"a four-storey house","meaning":"四層高房屋","examples":[{"en":"The pole is as high as a four-storey house.","zh":"這支柱的高度相當於四層高房屋。"},{"en":"A four-storey house is a house with four levels or floors.","zh":"a four-storey house 指有四層或四個樓層的房屋。"},{"en":"A lift may be useful in a four-storey house if elderly people live there.","zh":"如果有長者居住，四層高房屋可能需要升降機。"},{"en":"Comparing a turbine pole with a four-storey house shows that it is very tall for private property.","zh":"把渦輪機支柱與四層高房屋比較，顯示它對私人地方而言非常高。"},{"en":"This phrase gives a concrete height reference.","zh":"這個短語提供具體高度參照。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":1},{"front":"the most efficient form of","meaning":"最有效率的……形式","examples":[{"en":"This is the most efficient form of wind micro-turbine.","zh":"這是最有效率的微型風力渦輪機形式。"},{"en":"The most efficient form of something is the type that produces the best result with the least waste.","zh":"the most efficient form of something 指以最少浪費產生最佳結果的類型。"},{"en":"Cycling may be the most efficient form of transport for short trips in a crowded city.","zh":"在擁擠城市中，踏單車可能是短途交通最有效率的形式。"},{"en":"An efficient turbine produces more electricity from the same amount of wind.","zh":"有效率的渦輪機能從同樣風量中產生更多電力。"},{"en":"This phrase compares different forms and identifies the best-performing one.","zh":"這個短語比較不同形式，並指出表現最佳的一種。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":2},{"front":"wind micro-turbine","meaning":"微型風力渦輪機","examples":[{"en":"A wind micro-turbine can produce electricity on a windy site.","zh":"微型風力渦輪機可以在多風地點發電。"},{"en":"A wind micro-turbine is a small wind-powered machine used to generate electricity.","zh":"wind micro-turbine 指用風力發電的小型機器。"},{"en":"A rural home may use a wind micro-turbine if solar panels do not work well in winter.","zh":"如果冬天太陽能板效果不好，鄉村住宅可能使用微型風力渦輪機。"},{"en":"Wind micro-turbines perform poorly in sheltered places with weak wind.","zh":"微型風力渦輪機在避風且風力弱的地方表現差。"},{"en":"This phrase describes a small-scale wind energy device.","zh":"這個短語描述小規模風能裝置。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":2},{"front":"the sort of thing you could install","meaning":"你可以安裝的那類東西","examples":[{"en":"This turbine is the sort of thing you could install only if you had enough space.","zh":"這部渦輪機是只有在有足夠空間時你才可以安裝的那類東西。"},{"en":"The sort of thing you could install means a type of equipment that is possible to put in place under the right conditions.","zh":"the sort of thing you could install 指在合適條件下可以安裝的某類設備。"},{"en":"A large water tank is the sort of thing you could install only if the roof is strong enough.","zh":"大型水箱是只有屋頂足夠堅固時才可以安裝的那類東西。"},{"en":"Some equipment sounds useful, but practical limits decide whether you can actually install it.","zh":"有些設備聽起來有用，但實際限制會決定你是否真的能安裝。"},{"en":"This phrase is conversational and helps judge whether something is realistic.","zh":"這個短語較口語，有助判斷某事是否現實。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":2},{"front":"plenty of space and money","meaning":"充足空間和金錢","examples":[{"en":"You would need plenty of space and money to install a large micro-turbine.","zh":"你需要充足空間和金錢才能安裝大型微型渦輪機。"},{"en":"Plenty of space and money means a large amount of room and financial resources.","zh":"plenty of space and money 指大量地方和財務資源。"},{"en":"A family needs plenty of space and money before building a large home extension.","zh":"家庭在興建大型家居擴建部分前，需要充足空間和金錢。"},{"en":"Without enough space or money, a project may be attractive but unrealistic.","zh":"如果沒有足夠空間或金錢，一個項目可能吸引但不現實。"},{"en":"This phrase stresses that both physical room and cost matter.","zh":"這個短語強調實體空間和成本同樣重要。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":2},{"front":"according to one estimate","meaning":"根據一項估計","examples":[{"en":"According to one estimate, the turbine could deliver 25,000 kWh each year.","zh":"根據一項估計，這部渦輪機每年可以提供二萬五千千瓦時電力。"},{"en":"According to one estimate means based on one calculation or informed guess.","zh":"according to one estimate 指根據一項計算或有根據的估算。"},{"en":"According to one estimate, a new bus route could save commuters twenty minutes a day.","zh":"根據一項估計，新巴士路線每天可為通勤者節省二十分鐘。"},{"en":"Estimates can be useful, but they may change when conditions are measured more accurately.","zh":"估計很有用，但當條件被更準確量度後可能改變。"},{"en":"This phrase signals that the number is not absolute fact.","zh":"這個短語表示該數字不是絕對事實。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":2},{"front":"maximum output","meaning":"最大輸出","examples":[{"en":"A 15-kW turbine is described as one with the maximum output.","zh":"十五千瓦渦輪機被描述為具有最大輸出的一種。"},{"en":"Maximum output is the highest amount of power or production a machine can deliver.","zh":"maximum output 指機器能提供的最高功率或最高產量。"},{"en":"A phone charger’s maximum output tells users how fast it can charge a device.","zh":"手機充電器的最大輸出告訴使用者它能多快充電。"},{"en":"A turbine may not reach maximum output if the wind is weak.","zh":"如果風力弱，渦輪機可能達不到最大輸出。"},{"en":"This phrase describes the upper limit, not the normal daily result.","zh":"這個短語描述上限，而不是正常每日結果。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":2},{"front":"costing…to purchase","meaning":"購買需花費……","examples":[{"en":"The turbine costs £41,000 to purchase.","zh":"這部渦輪機購買需花費四萬一千英鎊。"},{"en":"Costing an amount to purchase means requiring that amount of money to buy.","zh":"costing an amount to purchase 指購買某物需要該筆金錢。"},{"en":"A laptop costing £900 to purchase may still need extra money for software.","zh":"一部購買需花費九百英鎊的手提電腦，可能仍需要額外軟件費。"},{"en":"A high purchase cost can make a good product difficult for ordinary families to afford.","zh":"高購買成本可能令好產品難以被普通家庭負擔。"},{"en":"This phrase focuses on buying cost before installation or maintenance.","zh":"這個短語著重購買成本，而不是安裝或維修成本。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":2},{"front":"a further…to install","meaning":"另需……安裝","examples":[{"en":"The turbine costs a further £9,000 to install.","zh":"這部渦輪機另需九千英鎊安裝。"},{"en":"A further amount to install means extra money needed after purchase to put something in place.","zh":"a further amount to install 指購買後還需要額外金錢把某物安裝好。"},{"en":"A new air conditioner may cost a further fee to install after the unit is bought.","zh":"新冷氣機買下後，可能另需一筆費用安裝。"},{"en":"Installation costs can change the true price of a product.","zh":"安裝成本可以改變產品的真正價格。"},{"en":"This phrase reminds buyers to count costs beyond the item itself.","zh":"這個短語提醒買家計算物件本身以外的成本。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":2},{"front":"capable of delivering","meaning":"能夠提供","examples":[{"en":"The turbine is capable of delivering 25,000 kWh of electricity each year.","zh":"這部渦輪機每年能夠提供二萬五千千瓦時電力。"},{"en":"Capable of delivering something means able to provide or produce it under suitable conditions.","zh":"capable of delivering something 指在合適條件下能夠提供或產生某物。"},{"en":"A good school bus system is capable of delivering students safely and on time.","zh":"良好的校車系統能夠安全準時接送學生。"},{"en":"A device may be capable of delivering strong results only when it is used properly.","zh":"裝置可能只有在正確使用時才有能力提供強勁結果。"},{"en":"This phrase describes potential ability, not a guaranteed result in every situation.","zh":"這個短語描述潛在能力，而不是每種情況下都保證的結果。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":2},{"front":"kilowatt-hours of electricity","meaning":"千瓦時電力","examples":[{"en":"The turbine can produce thousands of kilowatt-hours of electricity.","zh":"這部渦輪機可以產生數千千瓦時電力。"},{"en":"Kilowatt-hours of electricity are units used to measure how much electrical energy is used or produced.","zh":"kilowatt-hours of electricity 是用來量度使用或產生了多少電能的單位。"},{"en":"A household electricity bill usually shows how many kilowatt-hours of electricity were used.","zh":"家庭電費單通常會顯示用了多少千瓦時電力。"},{"en":"More kilowatt-hours of electricity produced by a turbine can mean larger fuel savings.","zh":"渦輪機產生更多千瓦時電力，可能意味更大燃料節省。"},{"en":"This phrase measures energy amount, not the speed of production.","zh":"這個短語量度能源總量，而不是生產速度。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":2},{"front":"placed on","meaning":"放置於","examples":[{"en":"The turbine works well if placed on a suitably windy site.","zh":"如果放置於風力合適的地點，這部渦輪機運作良好。"},{"en":"Placed on means put or installed in a particular location.","zh":"placed on 指被放在或安裝在某個特定位置。"},{"en":"A solar panel works better when placed on a roof with strong sunlight.","zh":"太陽能板放置於陽光強烈的屋頂時，效果會更好。"},{"en":"If equipment is placed on the wrong site, its performance may fall sharply.","zh":"如果設備放置於錯誤地點，其表現可能大幅下降。"},{"en":"This phrase links location with effectiveness.","zh":"這個短語把位置與效果連繫起來。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":3},{"front":"a suitably windy site","meaning":"風力合適的地點","examples":[{"en":"A micro-turbine needs a suitably windy site to work efficiently.","zh":"微型渦輪機需要風力合適的地點才能有效運作。"},{"en":"A suitably windy site is a place with enough regular wind for a turbine to produce useful power.","zh":"suitably windy site 指有足夠穩定風力、可讓渦輪機產生有用電力的地方。"},{"en":"An open hill may be a suitably windy site, while a sheltered courtyard may not be.","zh":"開闊山丘可能是風力合適的地點，而受遮擋的庭院可能不是。"},{"en":"Without a suitably windy site, even an expensive turbine may produce little electricity.","zh":"沒有風力合適的地點，即使昂貴渦輪機也可能只產生少量電力。"},{"en":"This phrase shows that location is essential for wind energy.","zh":"這個短語顯示地點對風能至關重要。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":3},{"front":"credible studies","meaning":"可信的研究","examples":[{"en":"The writer does not know of any credible studies on turbine emissions.","zh":"作者不知道有任何關於渦輪機排放的可信研究。"},{"en":"Credible studies are research works that are trustworthy because they use sound methods and evidence.","zh":"credible studies 指因使用可靠方法和證據而值得信任的研究。"},{"en":"Doctors prefer credible studies over rumours when deciding whether a treatment works.","zh":"醫生判斷治療是否有效時，會較相信可信研究，而不是傳聞。"},{"en":"Without credible studies, estimates may be uncertain or disputed.","zh":"沒有可信研究，估算可能不確定或有爭議。"},{"en":"This phrase contrasts reliable research with weak claims.","zh":"這個短語把可靠研究與薄弱說法作對比。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":3},{"front":"greenhouse gas emissions","meaning":"溫室氣體排放","examples":[{"en":"Greenhouse gas emissions are produced during manufacture and installation.","zh":"製造和安裝期間會產生溫室氣體排放。"},{"en":"Greenhouse gas emissions are gases released into the air that trap heat and contribute to climate change.","zh":"greenhouse gas emissions 指釋放到空氣中、會困住熱力並造成氣候變化的氣體。"},{"en":"Driving a petrol car creates greenhouse gas emissions when fuel is burned.","zh":"駕駛汽油車燃燒燃料時會產生溫室氣體排放。"},{"en":"Lowering greenhouse gas emissions can reduce long-term climate damage.","zh":"降低溫室氣體排放可以減少長遠氣候損害。"},{"en":"This phrase refers to pollution linked to warming, not ordinary smoke only.","zh":"這個短語指與暖化相關的污染，而不只是普通煙霧。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":3},{"front":"involved in","meaning":"涉及；產生於","examples":[{"en":"The writer estimates the emissions involved in producing and installing turbines.","zh":"作者估算生產和安裝渦輪機所涉及的排放。"},{"en":"Involved in something means connected with or produced as part of that activity.","zh":"involved in something 指與某活動相關，或作為該活動一部分產生。"},{"en":"The costs involved in moving house include transport, deposits, and cleaning.","zh":"搬屋涉及的成本包括運輸、按金和清潔。"},{"en":"Hidden work involved in a project can make it more expensive than expected.","zh":"項目中涉及的隱藏工作可能令其比預期更昂貴。"},{"en":"This phrase points to things included in a process, even if they are not obvious.","zh":"這個短語指出包含在過程中的事物，即使它們不明顯。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":3},{"front":"producing and installing turbines","meaning":"生產和安裝渦輪機","examples":[{"en":"Producing and installing turbines creates greenhouse gas emissions.","zh":"生產和安裝渦輪機會產生溫室氣體排放。"},{"en":"Producing and installing turbines means manufacturing the machines and putting them into operation on site.","zh":"producing and installing turbines 指製造機器並在現場把它們投入運作。"},{"en":"A company must plan transport, foundations, and safety checks when producing and installing turbines.","zh":"公司生產和安裝渦輪機時，必須規劃運輸、地基和安全檢查。"},{"en":"Even renewable energy equipment can create emissions during production and installation.","zh":"即使是可再生能源設備，在生產和安裝期間也可能產生排放。"},{"en":"This phrase covers both factory work and on-site setup.","zh":"這個短語涵蓋工廠製造和現場設置。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":3},{"front":"estimates","meaning":"估算","examples":[{"en":"The writer’s estimates are broader than usual.","zh":"作者的估算比平時更粗略。"},{"en":"Estimates are approximate calculations made when exact numbers are not available.","zh":"estimates 指在沒有準確數字時作出的近似計算。"},{"en":"A builder may give estimates before the exact cost of repairs is known.","zh":"建築工人在確切維修成本未清楚前，可能先給出估算。"},{"en":"Estimates are useful for planning, but they can be wrong if assumptions are weak.","zh":"估算對規劃有用，但如果假設薄弱，就可能錯誤。"},{"en":"This word signals approximation rather than precise measurement.","zh":"這個詞表示近似，而不是精確量度。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":3},{"front":"broader than usual","meaning":"比平時更粗略","examples":[{"en":"The estimates are even broader than usual.","zh":"這些估算甚至比平時更粗略。"},{"en":"Broader than usual means less precise or covering a wider possible range than normal.","zh":"broader than usual 指比正常情況更不精確，或涵蓋更廣可能範圍。"},{"en":"A doctor’s estimate of recovery time may be broader than usual when symptoms are unusual.","zh":"當症狀不尋常，醫生對康復時間的估算可能比平時更粗略。"},{"en":"Broad estimates can still guide decisions, but they leave more uncertainty.","zh":"粗略估算仍可引導決策，但會留下更多不確定性。"},{"en":"This phrase warns readers not to treat the figures as exact.","zh":"這個短語提醒讀者不要把數字視為精確。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":3},{"front":"it is worth trying","meaning":"值得嘗試","examples":[{"en":"Even without exact studies, it is worth trying to estimate the carbon footprint.","zh":"即使沒有準確研究，仍值得嘗試估算碳足跡。"},{"en":"It is worth trying means the attempt is useful or reasonable even if success is not guaranteed.","zh":"it is worth trying 指即使不保證成功，嘗試仍有用或合理。"},{"en":"If a student is weak in speaking, it is worth trying short daily practice.","zh":"如果學生口語弱，每天短時間練習是值得嘗試的。"},{"en":"It is worth trying a rough estimate when no exact data are available.","zh":"當沒有準確數據時，作出粗略估算仍值得嘗試。"},{"en":"This phrase encourages a practical attempt despite uncertainty.","zh":"這個短語鼓勵在不確定下作出實際嘗試。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":3},{"front":"turbine manufacture","meaning":"渦輪機製造","examples":[{"en":"Turbine manufacture may be carbon intensive.","zh":"渦輪機製造可能是碳排放密集的。"},{"en":"Turbine manufacture is the process of making turbine parts and assembling the machine.","zh":"turbine manufacture 指製造渦輪機零件並組裝機器的過程。"},{"en":"Factories involved in turbine manufacture may use steel, transport, electricity, and skilled labour.","zh":"參與渦輪機製造的工廠可能使用鋼材、運輸、電力和熟練工人。"},{"en":"If manufacture uses a lot of energy, the product has a larger carbon footprint before it even operates.","zh":"如果製造過程使用大量能源，產品在運作前已經有較大碳足跡。"},{"en":"This phrase refers to making the turbine, not using it afterwards.","zh":"這個短語指製造渦輪機，而不是之後使用它。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":3},{"front":"carbon intensive","meaning":"碳排放密集的","examples":[{"en":"Turbine manufacture is probably carbon intensive.","zh":"渦輪機製造很可能是碳排放密集的。"},{"en":"Carbon intensive means producing a large amount of greenhouse gases compared with the value or output produced.","zh":"carbon intensive 指相對於所產生的價值或輸出而言，會產生大量溫室氣體。"},{"en":"Making cement is carbon intensive because it uses high heat and releases emissions.","zh":"製造水泥是碳排放密集的，因為它需要高溫並釋放排放。"},{"en":"Carbon-intensive products may reduce their benefit if they require many emissions before use.","zh":"如果產品在使用前已需要大量排放，其好處可能被削弱。"},{"en":"This phrase describes the emissions burden of a process.","zh":"這個短語描述某過程的排放負擔。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":4},{"front":"per pound sterling of product","meaning":"每英鎊產品價值","examples":[{"en":"The writer estimates carbon intensity per pound sterling of product.","zh":"作者估算每英鎊產品價值的碳強度。"},{"en":"Per pound sterling of product means for each British pound of product value.","zh":"per pound sterling of product 指每一英鎊產品價值。"},{"en":"A company may compare emissions per pound sterling of product to judge how carbon-heavy production is.","zh":"公司可能比較每英鎊產品價值的排放，以判斷生產有多高碳。"},{"en":"If emissions per pound are high, expensive products may carry a large carbon footprint.","zh":"如果每英鎊排放很高，昂貴產品可能帶有巨大碳足跡。"},{"en":"This phrase connects carbon emissions with product value.","zh":"這個短語把碳排放與產品價值連繫起來。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":4},{"front":"a reasonable assumption","meaning":"合理假設","examples":[{"en":"The comparison with electrical motors seems a reasonable assumption.","zh":"與電動摩打作比較似乎是一個合理假設。"},{"en":"A reasonable assumption is a sensible guess based on available evidence.","zh":"reasonable assumption 指基於可用證據作出的合理猜測。"},{"en":"If a student is absent with a fever, it is a reasonable assumption that they are ill.","zh":"如果學生發燒缺席，假設他生病是一個合理假設。"},{"en":"Reasonable assumptions help analysis continue when exact information is missing.","zh":"當缺少準確資訊時，合理假設可以幫助分析繼續。"},{"en":"This phrase does not mean certainty; it means the guess is defensible.","zh":"這個短語不是指確定，而是指猜測有理據。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":4},{"front":"carbon intensity of manufacture","meaning":"製造過程的碳強度","examples":[{"en":"The carbon intensity of manufacture is estimated at 640 kg per £1,000.","zh":"製造過程的碳強度估計為每一千英鎊六百四十公斤。"},{"en":"Carbon intensity of manufacture means the emissions produced while making a product compared with its value or output.","zh":"carbon intensity of manufacture 指製造產品時產生的排放相對於其價值或輸出。"},{"en":"A factory can reduce the carbon intensity of manufacture by using cleaner electricity.","zh":"工廠可以透過使用較清潔電力來降低製造過程的碳強度。"},{"en":"High carbon intensity of manufacture can delay the environmental payback of a green product.","zh":"高製造碳強度可能延遲綠色產品的環境回本期。"},{"en":"This phrase focuses on emissions from production, not use.","zh":"這個短語著重生產階段的排放，而不是使用階段。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":4},{"front":"installation","meaning":"安裝","examples":[{"en":"Installation adds to the turbine’s carbon footprint.","zh":"安裝會增加渦輪機的碳足跡。"},{"en":"Installation is the process of putting equipment in place so it can be used.","zh":"installation 指把設備放置好，使其可以使用的過程。"},{"en":"Air-conditioner installation may include fixing the unit, connecting wires, and testing safety.","zh":"冷氣機安裝可能包括固定機件、接駁電線和測試安全。"},{"en":"Installation can add cost and emissions even after the product has been bought.","zh":"即使產品已經購買，安裝仍可能增加成本和排放。"},{"en":"This word refers to setup work, not the purchase itself.","zh":"這個詞指設置工作，而不是購買本身。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":4},{"front":"typical construction","meaning":"一般建築工程","examples":[{"en":"Installation is probably as carbon intensive as typical construction.","zh":"安裝的碳排放密集程度可能與一般建築工程相若。"},{"en":"Typical construction means normal building work using common materials, labour, and machinery.","zh":"typical construction 指使用常見材料、勞工和機械的一般建築工作。"},{"en":"Building a small classroom block is an example of typical construction.","zh":"建造小型課室大樓就是一般建築工程的一個例子。"},{"en":"Typical construction can create emissions through cement, steel, transport, and machines.","zh":"一般建築工程可透過水泥、鋼材、運輸和機器產生排放。"},{"en":"This phrase is used as a practical comparison for estimating installation impact.","zh":"這個短語用作估算安裝影響的實際比較。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":4},{"front":"carbon footprint","meaning":"碳足跡","examples":[{"en":"The turbine’s carbon footprint is estimated at 30 tonnes.","zh":"這部渦輪機的碳足跡估計為三十噸。"},{"en":"A carbon footprint is the total greenhouse gas emissions caused by a person, product, activity, or organisation.","zh":"carbon footprint 指由個人、產品、活動或機構造成的溫室氣體排放總量。"},{"en":"Flying overseas can greatly increase a family’s carbon footprint.","zh":"飛往海外可以大幅增加家庭碳足跡。"},{"en":"A product with a large carbon footprint may need years of clean use to balance its emissions.","zh":"碳足跡大的產品可能需要多年清潔使用才能抵消其排放。"},{"en":"This phrase measures climate impact across a whole process.","zh":"這個短語量度整個過程的氣候影響。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":4},{"front":"the total amount of greenhouse gases","meaning":"溫室氣體總量","examples":[{"en":"The carbon footprint is the total amount of greenhouse gases created.","zh":"碳足跡是所產生的溫室氣體總量。"},{"en":"The total amount of greenhouse gases means all climate-warming gases released by an activity or product.","zh":"the total amount of greenhouse gases 指某活動或產品釋放的所有暖化氣體。"},{"en":"A school trip’s total amount of greenhouse gases may include bus fuel, food transport, and electricity use.","zh":"學校旅行的溫室氣體總量可能包括巴士燃料、食物運輸和用電。"},{"en":"Counting the total amount helps avoid ignoring hidden emissions.","zh":"計算總量有助避免忽略隱藏排放。"},{"en":"This phrase focuses on the full quantity, not one small source.","zh":"這個短語著重完整數量，而不是單一小來源。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":4},{"front":"created by installing","meaning":"由安裝……所產生","examples":[{"en":"The carbon footprint includes gases created by installing the turbine.","zh":"碳足跡包括由安裝渦輪機所產生的氣體。"},{"en":"Created by installing means produced as a result of putting equipment into place.","zh":"created by installing 指因安裝設備而產生。"},{"en":"Emissions created by installing a lift may come from machinery, transport, and construction materials.","zh":"由安裝升降機所產生的排放可能來自機械、運輸和建築材料。"},{"en":"Installation can create environmental costs before the equipment begins saving energy.","zh":"在設備開始節能前，安裝已可能產生環境成本。"},{"en":"This phrase highlights emissions from setup rather than operation.","zh":"這個短語突出設置階段而不是運作階段的排放。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":4},{"front":"carbon savings","meaning":"碳減排量","examples":[{"en":"The carbon savings from wind-powered electricity depend on what it replaces.","zh":"風力發電帶來的碳減排量取決於它取代甚麼。"},{"en":"Carbon savings are reductions in greenhouse gas emissions compared with another activity or energy source.","zh":"carbon savings 指相對於另一活動或能源來源而減少的溫室氣體排放。"},{"en":"Taking the train instead of flying may create carbon savings for a short trip.","zh":"短途旅行乘火車而不是飛機，可能帶來碳減排量。"},{"en":"Carbon savings are larger when clean energy replaces very dirty energy.","zh":"當清潔能源取代非常高污染能源時，碳減排量更大。"},{"en":"This phrase measures emissions avoided, not money saved.","zh":"這個短語量度避免的排放，而不是節省的金錢。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":4},{"front":"wind-powered electricity generation","meaning":"風力發電","examples":[{"en":"Wind-powered electricity generation can reduce carbon emissions.","zh":"風力發電可以減少碳排放。"},{"en":"Wind-powered electricity generation is the production of electricity using wind energy.","zh":"wind-powered electricity generation 指利用風能生產電力。"},{"en":"A coastal town may use wind-powered electricity generation if wind is strong and regular.","zh":"如果風力強而穩定，沿海城鎮可能使用風力發電。"},{"en":"It can reduce emissions when it replaces electricity from fossil fuels.","zh":"當它取代來自化石燃料的電力時，就可以減少排放。"},{"en":"This phrase describes the process of turning wind into electrical power.","zh":"這個短語描述把風轉化成電力的過程。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":5},{"front":"depend on","meaning":"取決於","examples":[{"en":"The carbon savings depend on the carbon intensity of the electricity replaced.","zh":"碳減排量取決於被取代電力的碳強度。"},{"en":"To depend on something means to be decided or affected by it.","zh":"depend on something 指由某事決定或受某事影響。"},{"en":"Whether a picnic goes ahead may depend on the weather.","zh":"野餐是否進行可能取決於天氣。"},{"en":"The value of a turbine depends on wind speed, location, and electricity prices.","zh":"渦輪機的價值取決於風速、位置和電價。"},{"en":"This phrase shows that one result changes according to another factor.","zh":"這個短語顯示一個結果會隨另一因素改變。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":5},{"front":"carbon intensity","meaning":"碳強度","examples":[{"en":"Coal-fired electricity has high carbon intensity.","zh":"燃煤電力有高碳強度。"},{"en":"Carbon intensity is the amount of greenhouse gas emitted for each unit of energy, product, or activity.","zh":"carbon intensity 指每單位能源、產品或活動所排放的溫室氣體量。"},{"en":"Electricity from coal usually has higher carbon intensity than electricity from wind.","zh":"燃煤電力通常比風力電力有更高碳強度。"},{"en":"Lower carbon intensity means less climate damage for the same amount of energy produced.","zh":"較低碳強度表示在生產同樣能源時造成較少氣候損害。"},{"en":"This phrase helps compare how dirty or clean different options are.","zh":"這個短語幫助比較不同選項有多污染或多清潔。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":5},{"front":"electricity that you’re replacing","meaning":"你正在取代的電力","examples":[{"en":"The carbon saving depends on the electricity that you’re replacing.","zh":"碳減排量取決於你正在取代的電力。"},{"en":"Electricity that you’re replacing means the original electricity source that a new system takes the place of.","zh":"electricity that you’re replacing 指被新系統取代的原本電力來源。"},{"en":"Solar panels save more carbon if the electricity they replace comes from coal rather than renewables.","zh":"如果太陽能板取代的是燃煤電力而不是可再生能源，節碳效果會更大。"},{"en":"To measure true benefit, you must ask what energy source is being displaced.","zh":"要量度真正好處，必須問哪種能源來源正被取代。"},{"en":"This phrase focuses on the comparison point for calculating savings.","zh":"這個短語著重計算減排時的比較基準。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":5},{"front":"let’s assume that","meaning":"讓我們假設","examples":[{"en":"Let’s assume that the turbine replaces coal-fuelled electricity.","zh":"讓我們假設渦輪機取代燃煤電力。"},{"en":"Let’s assume that means let us suppose something is true for the sake of calculation or discussion.","zh":"let’s assume that 指為了計算或討論而假設某事為真。"},{"en":"Let’s assume that a bus ticket costs £2 before comparing travel costs.","zh":"讓我們假設巴士票價為兩英鎊，再比較交通成本。"},{"en":"Assumptions help analysis begin, but wrong assumptions can change the conclusion.","zh":"假設幫助分析開始，但錯誤假設會改變結論。"},{"en":"This phrase introduces a working condition, not a proven fact.","zh":"這個短語引入工作假設，而不是已證明事實。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":5},{"front":"coal-fuelled part of","meaning":"燃煤部分","examples":[{"en":"The turbine may replace the coal-fuelled part of the energy mix.","zh":"渦輪機可能取代能源組合中的燃煤部分。"},{"en":"The coal-fuelled part of something is the portion powered or produced by coal.","zh":"coal-fuelled part of something 指由煤炭提供能源或產生的部分。"},{"en":"A country may try to reduce the coal-fuelled part of its electricity supply.","zh":"一個國家可能嘗試減少電力供應中的燃煤部分。"},{"en":"Cutting the coal-fuelled part usually reduces emissions more than replacing cleaner sources.","zh":"削減燃煤部分通常比取代較清潔來源更能減少排放。"},{"en":"This phrase identifies the high-carbon portion of a larger system.","zh":"這個短語指出較大系統中的高碳部分。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":5},{"front":"the country’s energy mix","meaning":"國家的能源組合","examples":[{"en":"The country’s energy mix includes coal, gas, oil and renewable sources.","zh":"國家的能源組合包括煤、天然氣、石油和可再生能源。"},{"en":"A country’s energy mix is the combination of energy sources it uses.","zh":"country’s energy mix 指一個國家使用的能源來源組合。"},{"en":"A country with more solar and wind in its energy mix may produce cleaner electricity.","zh":"如果一個國家的能源組合中有更多太陽能和風能，它可能生產較清潔電力。"},{"en":"Changing the energy mix can reduce emissions but may require new infrastructure.","zh":"改變能源組合可以減少排放，但可能需要新基建。"},{"en":"This phrase describes the balance of different energy sources.","zh":"這個短語描述不同能源來源之間的比例。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":5},{"front":"in other words","meaning":"換句話說","examples":[{"en":"In other words, the turbine reduces the use of coal-fired power stations.","zh":"換句話說，渦輪機減少燃煤發電廠的使用。"},{"en":"In other words is used to restate an idea more clearly or simply.","zh":"in other words 用來以更清楚或更簡單方式重述一個想法。"},{"en":"The shop lost money; in other words, its costs were higher than its sales.","zh":"商店虧損；換句話說，它的成本高於銷售額。"},{"en":"This phrase helps explain a technical point in easier language.","zh":"這個短語幫助用較容易語言解釋技術重點。"},{"en":"It tells readers that the next sentence gives the same idea in another form.","zh":"它告訴讀者下一句會用另一種形式表達同一想法。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":5},{"front":"rather than replacing","meaning":"而不是取代","examples":[{"en":"The writer focuses on replacing coal rather than replacing typical grid electricity.","zh":"作者集中於取代煤，而不是取代一般電網供電。"},{"en":"Rather than replacing means instead of taking the place of something else.","zh":"rather than replacing 指而不是取代另一事物。"},{"en":"A school may improve lunch quality rather than replacing the whole canteen system.","zh":"學校可能改善午餐質素，而不是取代整個食堂制度。"},{"en":"Clear contrast is important because replacing coal gives different carbon savings from replacing average electricity.","zh":"清楚對比很重要，因為取代煤與取代平均電力帶來不同碳減排。"},{"en":"This phrase separates one possible comparison from another.","zh":"這個短語把一個可能比較與另一個分開。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":5},{"front":"typical grid electricity","meaning":"一般電網供電","examples":[{"en":"Typical grid electricity comes from a mix of energy sources.","zh":"一般電網供電來自多種能源來源的混合。"},{"en":"Typical grid electricity is the normal electricity supplied through the public electricity network.","zh":"typical grid electricity 指透過公共電力網絡供應的普通電力。"},{"en":"A household usually uses typical grid electricity when it plugs appliances into wall sockets.","zh":"家庭把電器插入牆上插座時，通常使用一般電網供電。"},{"en":"Its carbon intensity depends on the energy sources used by the grid.","zh":"它的碳強度取決於電網所使用的能源來源。"},{"en":"This phrase contrasts average electricity supply with a specific source such as coal.","zh":"這個短語把平均電力供應與煤等特定來源作對比。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":5},{"front":"a mix of","meaning":"……的混合","examples":[{"en":"Grid electricity comes from a mix of coal, gas, oil and renewable sources.","zh":"電網供電來自煤、天然氣、石油和可再生能源的混合。"},{"en":"A mix of things means a combination of different types or parts.","zh":"a mix of things 指不同類型或部分的組合。"},{"en":"A healthy lunch may include a mix of vegetables, protein, and rice.","zh":"健康午餐可能包括蔬菜、蛋白質和米飯的混合。"},{"en":"A mix of energy sources can make electricity supply more flexible.","zh":"多種能源來源的混合可以令電力供應更靈活。"},{"en":"This phrase shows that something is not made from one source only.","zh":"這個短語表示某事不是只由單一來源構成。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":6},{"front":"renewable energy sources","meaning":"可再生能源","examples":[{"en":"Renewable energy sources form part of the electricity mix.","zh":"可再生能源構成電力組合的一部分。"},{"en":"Renewable energy sources are energy sources that naturally replenish, such as wind, sunlight, and flowing water.","zh":"renewable energy sources 指會自然補充的能源來源，例如風、陽光和流水。"},{"en":"A school may install solar panels to use renewable energy sources.","zh":"學校可能安裝太陽能板以使用可再生能源。"},{"en":"More renewable energy sources can reduce reliance on fossil fuels.","zh":"更多可再生能源可以減少對化石燃料的依賴。"},{"en":"This phrase refers to cleaner energy sources that do not run out in the same way as coal or oil.","zh":"這個短語指較清潔、不像煤和石油那樣耗盡的能源來源。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":6},{"front":"the effect of","meaning":"……的效果","examples":[{"en":"The effect of the turbine is to reduce coal use.","zh":"這部渦輪機的效果是減少煤炭使用。"},{"en":"The effect of something is the result or consequence it causes.","zh":"the effect of something 指某事造成的結果或後果。"},{"en":"The effect of better street lighting may be fewer accidents at night.","zh":"更好街燈的效果可能是減少夜間意外。"},{"en":"Understanding the effect of a policy helps people judge whether it works.","zh":"理解政策的效果有助人們判斷它是否有效。"},{"en":"This phrase focuses on what happens because of an action or object.","zh":"這個短語著重某行動或物件造成甚麼。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":6},{"front":"reduce the use of","meaning":"減少使用","examples":[{"en":"A wind turbine can reduce the use of coal-fired power stations.","zh":"風力渦輪機可以減少使用燃煤發電廠。"},{"en":"To reduce the use of something means to make people or systems use less of it.","zh":"reduce the use of something 指令人或系統較少使用某物。"},{"en":"Schools can reduce the use of paper by collecting homework online.","zh":"學校可以透過網上收功課來減少使用紙張。"},{"en":"Reducing the use of fossil fuels can lower greenhouse gas emissions.","zh":"減少使用化石燃料可以降低溫室氣體排放。"},{"en":"This phrase shows a decrease in dependence or consumption.","zh":"這個短語顯示依賴或消耗減少。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":6},{"front":"coal-fired power stations","meaning":"燃煤發電廠","examples":[{"en":"Coal-fired power stations produce carbon-intensive electricity.","zh":"燃煤發電廠生產碳強度高的電力。"},{"en":"Coal-fired power stations are electricity plants that burn coal to generate power.","zh":"coal-fired power stations 指燃燒煤炭來發電的電廠。"},{"en":"A city that relies on coal-fired power stations may have high electricity emissions.","zh":"依賴燃煤發電廠的城市可能有高電力排放。"},{"en":"Replacing coal-fired power stations with cleaner energy can reduce carbon output.","zh":"用較清潔能源取代燃煤發電廠可以減少碳排放。"},{"en":"This phrase refers to power plants using coal as fuel.","zh":"這個短語指以煤炭為燃料的發電廠。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":6},{"front":"the least preferable source","meaning":"最不理想的來源","examples":[{"en":"Coal is the least preferable source in the electricity mix.","zh":"在電力組合中，煤是最不理想的來源。"},{"en":"The least preferable source is the option people would choose last because it has more disadvantages.","zh":"least preferable source 指因缺點較多而最不會被優先選擇的來源。"},{"en":"In a school lunch plan, sugary drinks may be the least preferable source of energy for students.","zh":"在學校午餐計劃中，含糖飲品可能是學生最不理想的能量來源。"},{"en":"A source can be least preferable because it is costly, dirty, risky, or inefficient.","zh":"一個來源可能因昂貴、污染、危險或低效而最不理想。"},{"en":"This phrase ranks options and identifies the worst one.","zh":"這個短語排列選項並指出最差的一個。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":6},{"front":"in the electricity mix","meaning":"在電力組合中","examples":[{"en":"Coal is the least preferable source in the electricity mix.","zh":"在電力組合中，煤是最不理想的來源。"},{"en":"In the electricity mix means within the combination of sources used to produce electricity.","zh":"in the electricity mix 指在用來生產電力的多種來源組合之中。"},{"en":"Wind may become more important in the electricity mix if more turbines are built.","zh":"如果建造更多渦輪機，風能可能在電力組合中變得更重要。"},{"en":"The carbon footprint of electricity depends on what sources are in the mix.","zh":"電力的碳足跡取決於組合中有哪些來源。"},{"en":"This phrase places one energy source inside the wider power system.","zh":"這個短語把一種能源放在更廣泛電力系統之中。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":6},{"front":"in this case","meaning":"在這種情況下","examples":[{"en":"In this case, the carbon saving is roughly one kilogram per kWh.","zh":"在這種情況下，碳減排量大約是每千瓦時一公斤。"},{"en":"In this case means in the particular situation being discussed.","zh":"in this case 指在正在討論的特定情況下。"},{"en":"The bus is usually cheaper, but in this case the taxi is better because four people can share it.","zh":"巴士通常較便宜，但在這種情況下，的士較好，因為四個人可以分擔費用。"},{"en":"This phrase signals that the conclusion may change in another situation.","zh":"這個短語表示結論在另一情況下可能改變。"},{"en":"It helps limit a statement to the current example.","zh":"它幫助把說法限制在目前例子中。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":6},{"front":"roughly","meaning":"大約","examples":[{"en":"The carbon saving is roughly one kilogram per kWh.","zh":"碳減排量大約是每千瓦時一公斤。"},{"en":"Roughly means approximately, not exactly.","zh":"roughly 指大約，而不是準確。"},{"en":"The walk from the station to school takes roughly ten minutes.","zh":"從車站步行到學校大約需要十分鐘。"},{"en":"Rough numbers are useful for quick planning, but exact decisions may need better data.","zh":"粗略數字對快速規劃有用，但精確決定可能需要更好數據。"},{"en":"This word tells readers not to treat the figure as perfectly precise.","zh":"這個詞告訴讀者不要把數字視為完全精確。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":6},{"front":"per kWh","meaning":"每千瓦時","examples":[{"en":"The turbine saves roughly one kilogram of carbon per kWh.","zh":"這部渦輪機每千瓦時大約節省一公斤碳。"},{"en":"Per kWh means for each kilowatt-hour of electricity produced or used.","zh":"per kWh 指每產生或使用一千瓦時電力。"},{"en":"An electricity bill may show the price per kWh so families can calculate usage costs.","zh":"電費單可能顯示每千瓦時價格，讓家庭計算用電成本。"},{"en":"Comparing emissions per kWh helps people judge which electricity source is cleaner.","zh":"比較每千瓦時排放有助人們判斷哪種電力來源較清潔。"},{"en":"This phrase gives a rate based on energy amount.","zh":"這個短語給出基於能源量的比率。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":6},{"front":"pay back","meaning":"抵消；回本","examples":[{"en":"The turbine can pay back its embodied carbon in 14 months.","zh":"這部渦輪機可以在十四個月內抵消其內含碳。"},{"en":"To pay back something means to recover or offset an earlier cost or investment.","zh":"pay back something 指收回或抵消早前的成本或投資。"},{"en":"A new fridge may pay back its cost if it saves enough electricity over several years.","zh":"如果新雪櫃多年來節省足夠電力，它可能收回成本。"},{"en":"A carbon payback is reached when savings equal the emissions first created.","zh":"當節省的排放等於最初產生的排放時，就達到碳回本。"},{"en":"This phrase can refer to money, carbon, or effort being recovered.","zh":"這個短語可以指金錢、碳或努力被收回。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":7},{"front":"embodied carbon","meaning":"內含碳；隱含碳","examples":[{"en":"The turbine pays back its embodied carbon in just 14 months.","zh":"這部渦輪機僅在十四個月內抵消其內含碳。"},{"en":"Embodied carbon is the greenhouse gas emitted while making, transporting, and installing a product.","zh":"embodied carbon 指製造、運輸和安裝產品期間排放的溫室氣體。"},{"en":"A new building has embodied carbon before anyone even switches on the lights.","zh":"新建築在任何人開燈之前已經有內含碳。"},{"en":"Products with high embodied carbon need large later savings to justify their environmental cost.","zh":"內含碳高的產品需要之後大量節省，才能合理化其環境成本。"},{"en":"This phrase focuses on emissions built into an object before use.","zh":"這個短語著重物件使用前已包含的排放。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":7},{"front":"in just 14 months","meaning":"僅在十四個月內","examples":[{"en":"The embodied carbon is paid back in just 14 months.","zh":"內含碳僅在十四個月內被抵消。"},{"en":"In just 14 months means in only fourteen months, suggesting the period is short.","zh":"in just 14 months 指只用了十四個月，表示時間較短。"},{"en":"A student may improve greatly in just 14 months with regular practice.","zh":"學生若定期練習，可以僅在十四個月內大幅進步。"},{"en":"When an investment pays back in just 14 months, it looks quick compared with long-term projects.","zh":"當投資僅在十四個月內回本，相比長期項目就顯得很快。"},{"en":"This phrase emphasises speed.","zh":"這個短語強調速度。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":7},{"front":"a great start","meaning":"很好的開始","examples":[{"en":"Paying back the embodied carbon quickly is a great start.","zh":"快速抵消內含碳是一個很好的開始。"},{"en":"A great start is a strong or encouraging beginning, even if more work remains.","zh":"great start 指強而令人鼓舞的開端，即使之後仍有更多工作。"},{"en":"Saving one hour a day is a great start for a student trying to manage time better.","zh":"對嘗試改善時間管理的學生而言，每天省下一小時是很好的開始。"},{"en":"A good first result can build confidence and support for the next step.","zh":"良好初步結果可以建立信心並支持下一步。"},{"en":"This phrase praises the beginning without claiming the whole problem is solved.","zh":"這個短語讚揚開端，但不表示整個問題已解決。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":7},{"front":"recently introduced","meaning":"最近推出","examples":[{"en":"The UK government has recently introduced a subsidy for renewable energy.","zh":"英國政府最近推出了可再生能源補貼。"},{"en":"Recently introduced means newly brought in or started not long ago.","zh":"recently introduced 指不久前新引入或開始。"},{"en":"A school recently introduced online booking for parent meetings.","zh":"學校最近推出家長會網上預約。"},{"en":"Recently introduced policies may need time before their full effects are clear.","zh":"最近推出的政策可能需要時間才看清完整效果。"},{"en":"This phrase highlights that something is new in the current context.","zh":"這個短語突出某事在目前語境中是新的。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":7},{"front":"a subsidy for","meaning":"對……的補貼","examples":[{"en":"The government introduced a subsidy for renewable energy.","zh":"政府推出了對可再生能源的補貼。"},{"en":"A subsidy for something is money given to support or encourage that activity.","zh":"subsidy for something 指為支持或鼓勵某活動而提供的金錢。"},{"en":"A government may provide a subsidy for public transport to keep fares affordable.","zh":"政府可能為公共交通提供補貼，以保持票價可負擔。"},{"en":"Subsidies can make expensive technologies easier for individuals to adopt.","zh":"補貼可以令昂貴技術更容易被個人採用。"},{"en":"This phrase refers to financial support, usually from government or an organisation.","zh":"這個短語指財務支持，通常來自政府或機構。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":7},{"front":"renewable energy","meaning":"可再生能源","examples":[{"en":"The subsidy supports renewable energy production.","zh":"這項補貼支持可再生能源生產。"},{"en":"Renewable energy is energy from sources that naturally replenish, such as wind, sunlight, and water.","zh":"renewable energy 指來自會自然補充的來源的能源，例如風、陽光和水。"},{"en":"A family may use renewable energy by installing solar panels on the roof.","zh":"家庭可能透過在屋頂安裝太陽能板使用可再生能源。"},{"en":"Renewable energy can reduce emissions when it replaces fossil fuels.","zh":"當可再生能源取代化石燃料時，可以減少排放。"},{"en":"This phrase refers to energy sources that can be naturally renewed.","zh":"這個短語指可以自然更新的能源來源。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":7},{"front":"individual producers","meaning":"個人生產者","examples":[{"en":"The subsidy pays individual producers for each energy unit.","zh":"補貼按每個能源單位支付給個人生產者。"},{"en":"Individual producers are people or households that generate energy themselves.","zh":"individual producers 指自行生產能源的個人或家庭。"},{"en":"A homeowner with solar panels can become an individual producer of electricity.","zh":"擁有太陽能板的屋主可以成為電力個人生產者。"},{"en":"Paying individual producers can encourage more people to invest in small renewable systems.","zh":"向個人生產者付款可以鼓勵更多人投資小型可再生系統。"},{"en":"This phrase contrasts small private producers with large power companies.","zh":"這個短語把小型私人供應者與大型電力公司作對比。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":7},{"front":"per energy unit","meaning":"每個能源單位","examples":[{"en":"Individual producers receive 24p per energy unit.","zh":"個人生產者每個能源單位收到二十四便士。"},{"en":"Per energy unit means for each measured amount of energy produced.","zh":"per energy unit 指每一個被量度的能源產量單位。"},{"en":"A household may earn a small payment per energy unit sent to the grid.","zh":"家庭每把一個能源單位送回電網，可能獲得小額付款。"},{"en":"Payments per unit make income depend on how much energy is actually generated.","zh":"按每單位付款會令收入取決於實際產生多少能源。"},{"en":"This phrase describes a rate linked to production.","zh":"這個短語描述與產量相關的比率。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":7},{"front":"in addition to","meaning":"除……之外","examples":[{"en":"The subsidy is paid in addition to savings on fuel bills.","zh":"這項補貼是在燃料費賬單節省之外支付的。"},{"en":"In addition to means as well as or on top of something else.","zh":"in addition to 指除某事之外，還有另一事。"},{"en":"A student may receive feedback in addition to a final grade.","zh":"學生除了最終分數之外，還可能收到回饋。"},{"en":"Extra benefits can make an investment more attractive in addition to the main saving.","zh":"除了主要節省之外，額外好處可以令投資更吸引。"},{"en":"This phrase adds another item to the same calculation or situation.","zh":"這個短語把另一項目加入同一計算或情況。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":7},{"front":"fuel bills","meaning":"燃料費賬單","examples":[{"en":"Households can save money on their fuel bills.","zh":"家庭可以節省燃料費賬單上的金錢。"},{"en":"Fuel bills are charges for energy used in a home or building, such as gas or electricity.","zh":"fuel bills 指家庭或建築物使用天然氣或電力等能源的收費。"},{"en":"A family may lower fuel bills by using insulation and efficient appliances.","zh":"家庭可能透過隔熱和高效電器降低燃料費賬單。"},{"en":"Rising fuel bills can make renewable energy systems more attractive.","zh":"燃料費賬單上升可以令可再生能源系統更吸引。"},{"en":"This phrase refers to regular energy costs paid by households or businesses.","zh":"這個短語指家庭或企業定期支付的能源成本。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":8},{"front":"surplus electricity","meaning":"剩餘電力","examples":[{"en":"Producers can sell surplus electricity back to the grid.","zh":"生產者可以把剩餘電力回售予電網。"},{"en":"Surplus electricity is extra electricity produced beyond what the user needs.","zh":"surplus electricity 指生產量超過使用者所需的額外電力。"},{"en":"A sunny home with solar panels may have surplus electricity at midday.","zh":"有太陽能板的家居在中午可能有剩餘電力。"},{"en":"Selling surplus electricity can improve the financial return of a renewable system.","zh":"出售剩餘電力可以改善可再生系統的財務回報。"},{"en":"This phrase means electricity left over after personal use.","zh":"這個短語指個人使用後剩下的電力。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":8},{"front":"back to the grid","meaning":"回售予電網","examples":[{"en":"Households can sell surplus electricity back to the grid.","zh":"家庭可以把剩餘電力回售予電網。"},{"en":"Back to the grid means returning electricity to the public electricity network.","zh":"back to the grid 指把電力送回公共電力網絡。"},{"en":"A solar-powered home may send unused power back to the grid on a sunny day.","zh":"在晴天，太陽能家居可能把未用電力送回電網。"},{"en":"Selling energy back to the grid can reduce waste and create income.","zh":"把能源回售予電網可以減少浪費並創造收入。"},{"en":"This phrase connects private energy production with the wider electricity system.","zh":"這個短語把私人能源生產與更廣泛電力系統連繫起來。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":8},{"front":"approximately","meaning":"大約","examples":[{"en":"Surplus electricity can be sold at approximately 5p per unit.","zh":"剩餘電力可以以每單位大約五便士出售。"},{"en":"Approximately means about or nearly, not exactly.","zh":"approximately 指大約或接近，而不是完全準確。"},{"en":"The walk from the bus stop to school takes approximately eight minutes.","zh":"從巴士站步行到學校大約需要八分鐘。"},{"en":"Approximate figures are useful when exact numbers may vary slightly.","zh":"當準確數字可能略有變動，近似數字很有用。"},{"en":"This word tells readers that the number is close but not perfectly precise.","zh":"這個詞告訴讀者數字接近但不是完全精確。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":8},{"front":"per unit","meaning":"每單位","examples":[{"en":"The electricity is sold back to the grid at about 5p per unit.","zh":"電力以每單位約五便士回售予電網。"},{"en":"Per unit means for each single measured amount of something.","zh":"per unit 指每一個被量度的標準數量。"},{"en":"A shop may compare prices per unit to see which package is cheaper.","zh":"商店可能比較每單位價格，以判斷哪個包裝較便宜。"},{"en":"Payment per unit makes total income rise when more units are produced.","zh":"按每單位付款會令總收入隨產量增加而上升。"},{"en":"This phrase gives a rate based on one standard amount.","zh":"這個短語給出基於一個標準數量的比率。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":8},{"front":"taken into account","meaning":"納入考慮","examples":[{"en":"With all this taken into account, the financial return looks attractive.","zh":"把所有這些納入考慮後，財務回報看起來很吸引。"},{"en":"Taken into account means included when making a judgement or calculation.","zh":"taken into account 指在作判斷或計算時被包括在內。"},{"en":"When rent and transport are taken into account, a cheap flat far away may not be cheaper.","zh":"當租金和交通納入考慮後，遠處便宜單位未必更便宜。"},{"en":"Good decisions require hidden costs to be taken into account.","zh":"良好決定需要把隱藏成本納入考慮。"},{"en":"This phrase shows that several factors have been considered.","zh":"這個短語顯示多個因素已被考慮。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":8},{"front":"get back","meaning":"收回","examples":[{"en":"Individuals would get back £7,250 per year on their investment.","zh":"個人每年可從其投資中收回七千二百五十英鎊。"},{"en":"To get back money means to recover or receive money after spending or investing it.","zh":"get back money 指花費或投資後收回或收到金錢。"},{"en":"A student may get back a deposit after returning a rented locker key.","zh":"學生歸還租用儲物櫃鑰匙後，可能收回按金。"},{"en":"Investors care how quickly they can get back what they first spent.","zh":"投資者關心多久可以收回最初花費。"},{"en":"This phrase is informal and often used for financial return.","zh":"這個短語較口語，常用於財務回報。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":8},{"front":"on their investment","meaning":"從其投資中","examples":[{"en":"Individuals receive a return on their investment.","zh":"個人從其投資中獲得回報。"},{"en":"On their investment means in relation to the money they have put into something.","zh":"on their investment 指相對於他們投入某事的金錢。"},{"en":"A shop owner wants a good return on their investment after buying new equipment.","zh":"店主購買新設備後，希望從其投資中得到良好回報。"},{"en":"A high return can make a risky project look more attractive.","zh":"高回報可以令有風險項目看起來更吸引。"},{"en":"This phrase connects benefit with the original amount invested.","zh":"這個短語把好處與原本投資金額連繫起來。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":8},{"front":"pays back the costs","meaning":"收回成本","examples":[{"en":"The turbine pays back the costs in about six years.","zh":"這部渦輪機約六年內收回成本。"},{"en":"Pays back the costs means earns or saves enough money to cover the original expenses.","zh":"pays back the costs 指賺取或節省足夠金錢來覆蓋原本開支。"},{"en":"A new delivery bike pays back the costs if it helps a shop make more deliveries.","zh":"如果新送貨單車幫助店舖送更多貨，它就可以收回成本。"},{"en":"A long payback period can make an investment less attractive.","zh":"較長回本期可能令投資較不吸引。"},{"en":"This phrase focuses on recovering money spent at the beginning.","zh":"這個短語著重收回最初花費的金錢。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":8},{"front":"makes good financial sense","meaning":"在財務上合理","examples":[{"en":"The investment makes good financial sense for individuals.","zh":"這項投資對個人來說在財務上合理。"},{"en":"Makes good financial sense means is sensible or worthwhile from a money point of view.","zh":"makes good financial sense 指從金錢角度看是明智或值得的。"},{"en":"Buying a monthly travel pass makes good financial sense if you take the train every day.","zh":"如果你每天乘火車，購買月票在財務上合理。"},{"en":"A project may make financial sense for one person but not for the government.","zh":"一個項目對個人可能在財務上合理，但對政府未必如此。"},{"en":"This phrase judges whether the numbers make the decision reasonable.","zh":"這個短語判斷數字是否令決定合理。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":8},{"front":"for their own sake","meaning":"為其本身價值","examples":[{"en":"Some people care about carbon savings for their own sake.","zh":"有些人為碳減排本身的價值而重視它。"},{"en":"For their own sake means because they are valuable in themselves, not only for another benefit.","zh":"for their own sake 指因某事本身有價值，而不只是為了其他好處。"},{"en":"Some students read books for their own sake, not just for exams.","zh":"有些學生為閱讀本身的價值而讀書，不只是為了考試。"},{"en":"Protecting nature for its own sake means valuing it beyond money or human use.","zh":"為自然本身價值而保護它，表示重視自然超越金錢或人類用途。"},{"en":"This phrase separates intrinsic value from practical reward.","zh":"這個短語把內在價值與實際回報分開。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":9},{"front":"a fantastic move","meaning":"非常好的舉措","examples":[{"en":"For carbon-conscious people, installing a turbine looks like a fantastic move.","zh":"對有碳意識的人來說，安裝渦輪機看起來是非常好的舉措。"},{"en":"A fantastic move is a very good decision or action in a particular situation.","zh":"fantastic move 指在特定情況下非常好的決定或行動。"},{"en":"For a student who always loses notes, using one organised notebook may be a fantastic move.","zh":"對經常弄丟筆記的學生來說，使用一本有系統筆記簿可能是非常好的舉措。"},{"en":"A decision can look fantastic when it brings both practical and moral benefits.","zh":"當一個決定帶來實際和道德好處時，它可能看起來非常好。"},{"en":"This phrase is positive and informal.","zh":"這個短語語氣正面而較口語。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":9},{"front":"carbon investment","meaning":"碳投資","examples":[{"en":"The carbon investment pays back in just over a year.","zh":"碳投資在一年多一點後回本。"},{"en":"Carbon investment means the emissions created upfront in order to achieve later carbon savings.","zh":"carbon investment 指為了之後取得碳減排而先產生的排放。"},{"en":"A new electric bus has a carbon investment because making the battery creates emissions.","zh":"新電動巴士有碳投資，因為製造電池會產生排放。"},{"en":"If later savings are large, the carbon investment can be paid back quickly.","zh":"如果之後節省很大，碳投資可以很快回本。"},{"en":"This phrase treats carbon like an upfront cost that later benefits must repay.","zh":"這個短語把碳視為前期成本，需要由之後好處償還。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":9},{"front":"just over a year","meaning":"一年多一點","examples":[{"en":"The carbon investment pays back in just over a year.","zh":"碳投資在一年多一點後回本。"},{"en":"Just over a year means a little more than one year.","zh":"just over a year 指比一年稍多。"},{"en":"A student may move from beginner to intermediate English in just over a year with steady practice.","zh":"學生若穩定練習，可能在一年多一點內由初學者進步到中級英文。"},{"en":"If a project pays back in just over a year, the recovery is relatively quick.","zh":"如果項目在一年多一點後回本，回收速度相對很快。"},{"en":"This phrase gives an approximate time slightly longer than twelve months.","zh":"這個短語表示略多於十二個月的近似時間。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":9},{"front":"every year after that","meaning":"之後每一年","examples":[{"en":"Every year after that brings a 25-tonne carbon saving.","zh":"之後每一年都帶來二十五噸碳減排。"},{"en":"Every year after that means each year following the point already mentioned.","zh":"every year after that 指在已提及時間點之後的每一年。"},{"en":"A student may pay for a course in the first year; every year after that brings benefits from the skills learned.","zh":"學生可能第一年支付課程費；之後每一年都從所學技能中受益。"},{"en":"Long-term investments can look better when benefits continue every year after that.","zh":"當好處在之後每一年持續，長期投資會看起來更好。"},{"en":"This phrase focuses on repeated future benefits after an initial period.","zh":"這個短語著重初期之後重複出現的未來好處。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":9},{"front":"all these sums","meaning":"所有這些計算","examples":[{"en":"All these sums rely on the turbine having a good location.","zh":"所有這些計算都取決於渦輪機有良好位置。"},{"en":"All these sums means all these calculations or financial figures.","zh":"all these sums 指所有這些計算或財務數字。"},{"en":"All these sums show that renting is cheaper only if transport costs stay low.","zh":"所有這些計算顯示，只有在交通成本保持低時，租屋才較便宜。"},{"en":"Calculations can look convincing, but they depend on the assumptions behind them.","zh":"計算可以看起來有說服力，但取決於背後假設。"},{"en":"This phrase refers to numerical reasoning already discussed.","zh":"這個短語指前面已討論的數字推理。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":9},{"front":"rely on","meaning":"依賴；取決於","examples":[{"en":"The financial figures rely on a favourable location.","zh":"財務數字依賴有利位置。"},{"en":"To rely on something means to depend on it in order to succeed or be true.","zh":"rely on something 指依靠某事才能成功或成立。"},{"en":"A student’s exam result may rely on regular practice rather than last-minute revision.","zh":"學生的考試成績可能取決於定期練習，而不是臨急溫習。"},{"en":"If a plan relies on good weather, rain can make it fail.","zh":"如果計劃依賴好天氣，下雨就可能令它失敗。"},{"en":"This phrase shows dependence on a key condition.","zh":"這個短語顯示對關鍵條件的依賴。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":9},{"front":"a favourable location","meaning":"有利位置","examples":[{"en":"A wind turbine needs a favourable location to produce enough electricity.","zh":"風力渦輪機需要有利位置才能產生足夠電力。"},{"en":"A favourable location is a place with conditions that help something work well.","zh":"favourable location 指條件有助某事物良好運作的地方。"},{"en":"A shop near a busy station has a favourable location because many people pass by.","zh":"車站附近的商店有有利位置，因為很多人經過。"},{"en":"For a turbine, a favourable location means strong wind, open space, and few obstacles.","zh":"對渦輪機而言，有利位置指強風、開闊空間和少障礙物。"},{"en":"This phrase links place with success.","zh":"這個短語把地點與成功連繫起來。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":9},{"front":"at face value","meaning":"表面看來","examples":[{"en":"At face value, the turbine looks like a great environmental idea.","zh":"表面看來，這部渦輪機像是一個很好的環保想法。"},{"en":"At face value means based only on the first appearance, without deeper analysis.","zh":"at face value 指只根據初步表面情況，而未作深入分析。"},{"en":"At face value, a cheap flat looks attractive, but transport costs may make it expensive.","zh":"表面看來，便宜單位很吸引，但交通成本可能令它變貴。"},{"en":"Taking figures at face value can hide assumptions and hidden costs.","zh":"只按表面接受數字，可能隱藏假設和隱藏成本。"},{"en":"This phrase warns readers to look beyond the surface.","zh":"這個短語提醒讀者看表面以外的東西。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":9},{"front":"environmentally","meaning":"從環境角度而言","examples":[{"en":"The turbine looks attractive environmentally.","zh":"從環境角度而言，這部渦輪機看起來很吸引。"},{"en":"Environmentally means from the point of view of environmental impact.","zh":"environmentally 指從環境影響的角度來看。"},{"en":"Cycling is environmentally better than driving for short journeys.","zh":"對短途旅程而言，踏單車從環境角度比駕車更好。"},{"en":"A product may be cheap financially but costly environmentally.","zh":"一件產品在財務上可能便宜，但從環境角度可能昂貴。"},{"en":"This word helps separate environmental judgement from financial judgement.","zh":"這個詞幫助把環境判斷與財務判斷分開。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":9},{"front":"a long-term investment","meaning":"長期投資","examples":[{"en":"The turbine may be a good long-term investment.","zh":"這部渦輪機可能是一項良好長期投資。"},{"en":"A long-term investment is something bought or funded for benefits over many years.","zh":"long-term investment 指為多年後的好處而購買或資助的東西。"},{"en":"Education is often a long-term investment because its benefits continue after the course ends.","zh":"教育通常是長期投資，因為課程結束後好處仍會持續。"},{"en":"A long-term investment may be expensive at first but useful later.","zh":"長期投資一開始可能昂貴，但之後有用。"},{"en":"This phrase focuses on future value rather than immediate reward.","zh":"這個短語著重未來價值，而不是即時回報。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":10},{"front":"economically","meaning":"從經濟角度而言","examples":[{"en":"The turbine may be attractive economically for the person installing it.","zh":"從經濟角度而言，這部渦輪機對安裝它的人可能很吸引。"},{"en":"Economically means from the point of view of money, cost, income, or financial benefit.","zh":"economically 指從金錢、成本、收入或財務好處的角度看。"},{"en":"Taking the bus may be better economically if parking is expensive.","zh":"如果泊車費昂貴，乘巴士從經濟角度而言可能更好。"},{"en":"A project can be environmentally good but economically difficult for a household.","zh":"一個項目可以在環境上好，但對家庭而言在經濟上困難。"},{"en":"This word helps separate financial judgement from moral or environmental judgement.","zh":"這個詞幫助把財務判斷與道德或環境判斷分開。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":10},{"front":"the person installing it","meaning":"安裝它的人","examples":[{"en":"The financial benefit goes mainly to the person installing it.","zh":"財務好處主要歸安裝它的人所有。"},{"en":"The person installing it means the individual who puts the equipment on their property or pays for its installation.","zh":"person installing it 指把設備安裝在自己地方或支付安裝費的人。"},{"en":"If a homeowner buys solar panels, the person installing them receives the bill savings.","zh":"如果屋主購買太陽能板，安裝它的人會獲得賬單節省。"},{"en":"A policy may help individual owners more than the wider public.","zh":"一項政策可能比起整體公眾更幫到個別業主。"},{"en":"This phrase identifies who directly receives the benefit.","zh":"這個短語指出誰直接獲得好處。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":10},{"front":"a crucial perspective","meaning":"關鍵角度","examples":[{"en":"A crucial perspective is missing from the analysis.","zh":"分析中缺少一個關鍵角度。"},{"en":"A crucial perspective is an important angle or viewpoint needed for a fair judgement.","zh":"crucial perspective 指作出公平判斷所需要的重要角度或觀點。"},{"en":"A school decision may miss a crucial perspective if students are not asked for opinions.","zh":"如果學校決定沒有詢問學生意見，就可能缺少一個關鍵角度。"},{"en":"Without a crucial perspective, an argument can seem complete but still be misleading.","zh":"沒有關鍵角度，論點可能看似完整，但仍具誤導性。"},{"en":"This phrase highlights an important viewpoint that must be included.","zh":"這個短語突出必須包括的重要觀點。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":10},{"front":"missing from the analysis","meaning":"在分析中缺失","examples":[{"en":"The government’s role is missing from the analysis so far.","zh":"到目前為止，政府角色在分析中缺失。"},{"en":"Missing from the analysis means not included in the discussion or calculation.","zh":"missing from the analysis 指沒有被包括在討論或計算中。"},{"en":"If transport costs are missing from the analysis, a housing comparison may be unfair.","zh":"如果交通成本在分析中缺失，住屋比較可能不公平。"},{"en":"Important missing factors can change the final conclusion.","zh":"重要缺失因素可以改變最終結論。"},{"en":"This phrase points out an omission in reasoning.","zh":"這個短語指出推理中的遺漏。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":10},{"front":"so far","meaning":"到目前為止","examples":[{"en":"The analysis so far has focused on the individual owner.","zh":"到目前為止，分析集中於個別擁有人。"},{"en":"So far means up to this point in time or discussion.","zh":"so far 指直到目前這一刻或討論位置。"},{"en":"The lesson so far has covered grammar, but not writing practice.","zh":"到目前為止，課堂已涵蓋文法，但未涵蓋寫作練習。"},{"en":"A conclusion so far may change when new evidence is added.","zh":"到目前為止的結論可能在加入新證據後改變。"},{"en":"This phrase signals that the discussion is not finished yet.","zh":"這個短語表示討論尚未完成。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":10},{"front":"spent its money wisely","meaning":"明智地花錢","examples":[{"en":"The writer asks whether the government has spent its money wisely.","zh":"作者問政府是否明智地花錢。"},{"en":"To spend money wisely means to use money in a way that gives good value or results.","zh":"spend money wisely 指以帶來良好價值或成果的方式使用金錢。"},{"en":"A family spends money wisely when it repairs a leaking roof before buying luxury furniture.","zh":"家庭先維修漏水屋頂再買奢侈家具，就是明智地花錢。"},{"en":"Governments must spend money wisely because public funds are limited.","zh":"政府必須明智地花錢，因為公共資金有限。"},{"en":"This phrase judges whether spending choices are sensible.","zh":"這個短語判斷花費選擇是否合理。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":10},{"front":"works out at","meaning":"計算起來是","examples":[{"en":"The subsidy works out at £250 per tonne of carbon saved.","zh":"補貼計算起來是每減少一噸碳二百五十英鎊。"},{"en":"Works out at means calculates to a particular amount.","zh":"works out at 指計算後得出某個金額。"},{"en":"If five friends share a £50 taxi fare, it works out at £10 each.","zh":"如果五個朋友分擔五十英鎊的士費，計算起來每人十英鎊。"},{"en":"A policy can look cheap overall but work out expensive per unit of benefit.","zh":"一項政策整體看似便宜，但按每單位好處計算可能昂貴。"},{"en":"This phrase is used after doing a calculation.","zh":"這個短語用於完成計算之後。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":10},{"front":"a massive","meaning":"巨大的；高達","examples":[{"en":"The subsidy works out at a massive £250 per tonne.","zh":"補貼計算起來高達每噸二百五十英鎊。"},{"en":"A massive amount means a very large amount, often surprisingly large.","zh":"massive amount 指非常大的數量，通常大得令人意外。"},{"en":"A school may face a massive repair bill after a serious flood.","zh":"嚴重水災後，學校可能面對巨大的維修費。"},{"en":"Using “massive” shows that the writer thinks the figure is unusually high.","zh":"使用 massive 顯示作者認為該數字異常地高。"},{"en":"This word adds emphasis and often suggests concern.","zh":"這個詞加強語氣，常表示擔憂。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":10},{"front":"per tonne of carbon saved","meaning":"每減少一噸碳","examples":[{"en":"The government spends £250 per tonne of carbon saved.","zh":"政府每減少一噸碳花費二百五十英鎊。"},{"en":"Per tonne of carbon saved means for each tonne of emissions reduced or avoided.","zh":"per tonne of carbon saved 指每減少或避免一噸排放。"},{"en":"A climate policy may be judged by its cost per tonne of carbon saved.","zh":"氣候政策可按每減少一噸碳的成本來評估。"},{"en":"A lower cost per tonne usually means better value for public money.","zh":"每噸成本較低通常表示公共資金更物有所值。"},{"en":"This phrase links spending with the amount of carbon reduction achieved.","zh":"這個短語把支出與達成的碳減排量連繫起來。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":10},{"front":"calculations tell me that","meaning":"我的計算顯示","examples":[{"en":"The writer’s calculations tell him that offshore wind farms would be better.","zh":"作者的計算顯示離岸風電場會更好。"},{"en":"Calculations tell me that means the numbers lead me to this conclusion.","zh":"calculations tell me that 指數字引導我得出這個結論。"},{"en":"My calculations tell me that a monthly pass is cheaper than buying daily tickets.","zh":"我的計算顯示，月票比每天買票便宜。"},{"en":"Calculations can support an argument, but they depend on the assumptions used.","zh":"計算可以支持論點，但取決於所使用的假設。"},{"en":"This phrase presents a conclusion based on numbers.","zh":"這個短語呈現基於數字的結論。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":11},{"front":"had the government invested","meaning":"如果政府當初投資於","examples":[{"en":"Had the government invested in offshore wind farms, it would have broken even sooner.","zh":"如果政府當初投資於離岸風電場，它會更早收支平衡。"},{"en":"Had the government invested means if the government had invested in the past.","zh":"had the government invested 指如果政府過去曾經投資。"},{"en":"Had the school invested in better computers earlier, online lessons would have run more smoothly.","zh":"如果學校當初較早投資於更好電腦，網上課堂會運作得更順利。"},{"en":"This structure is a formal conditional about a missed past possibility.","zh":"這個結構是關於錯過的過去可能性的正式條件句。"},{"en":"It compares what happened with what could have happened.","zh":"它把實際發生的事與本可發生的事作比較。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":11},{"front":"offshore wind farms","meaning":"離岸風電場","examples":[{"en":"Offshore wind farms may be a better target for government investment.","zh":"離岸風電場可能是政府投資的更好目標。"},{"en":"Offshore wind farms are groups of wind turbines built in the sea to generate electricity.","zh":"offshore wind farms 指建在海上的一組風力渦輪機，用來發電。"},{"en":"A coastal country may build offshore wind farms where sea winds are strong and regular.","zh":"沿海國家可能在海風強而穩定的地方建造離岸風電場。"},{"en":"Offshore wind farms can produce large amounts of renewable electricity.","zh":"離岸風電場可以產生大量可再生電力。"},{"en":"This phrase refers to large sea-based wind projects, not small home turbines.","zh":"這個短語指大型海上風電項目，而不是小型家用渦輪機。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":11},{"front":"instead of subsidising","meaning":"而不是補貼","examples":[{"en":"The government could invest in offshore wind farms instead of subsidising domestic turbines.","zh":"政府可以投資離岸風電場，而不是補貼家用渦輪機。"},{"en":"Instead of subsidising means choosing another action rather than giving financial support to something.","zh":"instead of subsidising 指選擇另一行動，而不是向某事提供財務支持。"},{"en":"A school may buy shared tablets instead of subsidising every student’s personal device.","zh":"學校可能購買共用平板電腦，而不是補貼每名學生的個人設備。"},{"en":"The phrase clearly contrasts two possible uses of money.","zh":"這個短語清楚對比金錢的兩種可能用途。"},{"en":"It helps readers see what alternative the writer prefers.","zh":"它幫助讀者看見作者較偏好的替代方案。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":11},{"front":"smaller domestic turbines","meaning":"較小型家用渦輪機","examples":[{"en":"Smaller domestic turbines receive government subsidies.","zh":"較小型家用渦輪機獲得政府補貼。"},{"en":"Smaller domestic turbines are small wind turbines used for homes or private properties.","zh":"smaller domestic turbines 指用於住宅或私人地方的小型風力渦輪機。"},{"en":"A house in a windy rural area may install a smaller domestic turbine.","zh":"位於多風鄉郊地區的房屋可能安裝較小型家用渦輪機。"},{"en":"Domestic turbines are easier to own privately, but their output depends heavily on location.","zh":"家用渦輪機較容易私人擁有，但其輸出高度取決於位置。"},{"en":"This phrase contrasts home-scale turbines with large commercial wind farms.","zh":"這個短語把家用規模渦輪機與大型商業風電場作對比。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":11},{"front":"broken even","meaning":"收支平衡","examples":[{"en":"The government would have broken even after eight years.","zh":"政府會在八年後收支平衡。"},{"en":"Broken even means recovered the original cost, with neither profit nor loss overall.","zh":"broken even 指已收回原本成本，整體上既沒有盈利也沒有虧損。"},{"en":"A café breaks even when its sales exactly cover rent, wages, and food costs.","zh":"當咖啡店銷售額剛好覆蓋租金、工資和食材成本時，就是收支平衡。"},{"en":"Breaking even is important before an investment can start producing net benefit.","zh":"投資開始產生淨收益前，收支平衡很重要。"},{"en":"This phrase focuses on reaching the point where costs have been covered.","zh":"這個短語著重達到成本已被覆蓋的點。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":11},{"front":"works out as","meaning":"結果是；算起來是","examples":[{"en":"The micro-turbine works out as a good investment for individuals.","zh":"微型渦輪機算起來是對個人不錯的投資。"},{"en":"Works out as means proves to be or calculates to be after considering the details.","zh":"works out as 指在考慮細節後證明或計算起來是某結果。"},{"en":"Renting near school may work out as cheaper once transport costs are included.","zh":"把交通成本包括在內後，住在學校附近可能算起來更便宜。"},{"en":"A plan can work out as good for one group but poor for another.","zh":"一個計劃可能對某群體結果很好，但對另一群體很差。"},{"en":"This phrase gives a conclusion after calculation or practical judgement.","zh":"這個短語在計算或實際判斷後給出結論。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":11},{"front":"a good investment for individuals","meaning":"對個人來說不錯的投資","examples":[{"en":"The micro-turbine is a good investment for individuals because of subsidies.","zh":"由於補貼，微型渦輪機對個人來說是不錯的投資。"},{"en":"A good investment for individuals is something that gives private owners worthwhile financial returns.","zh":"good investment for individuals 指能為私人擁有人帶來值得的財務回報的東西。"},{"en":"A training course may be a good investment for individuals if it leads to better job opportunities.","zh":"如果培訓課程帶來更好工作機會，它對個人來說可能是不錯的投資。"},{"en":"Subsidies can turn an expensive item into a good investment for private buyers.","zh":"補貼可以把昂貴物件變成對私人買家不錯的投資。"},{"en":"This phrase focuses on personal financial benefit, not public value.","zh":"這個短語著重個人財務好處，而不是公共價值。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":11},{"front":"arguably wastes","meaning":"可以說是浪費","examples":[{"en":"The government arguably wastes money by subsidising micro-turbines.","zh":"政府補貼微型渦輪機可以說是浪費金錢。"},{"en":"Arguably wastes means could reasonably be said to use something badly or inefficiently.","zh":"arguably wastes 指可以合理地說某事物被不良或低效地使用。"},{"en":"A school arguably wastes money if it buys tablets that students rarely use.","zh":"如果學校購買學生很少使用的平板電腦，可以說是浪費金錢。"},{"en":"A policy may arguably waste resources when a cheaper alternative gives better results.","zh":"當較便宜替代方案帶來更好結果時，政策可以說是浪費資源。"},{"en":"This phrase presents a critical opinion while allowing debate.","zh":"這個短語提出批判意見，同時容許爭論。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":11},{"front":"so much money subsidising it","meaning":"花大量金錢補貼它","examples":[{"en":"The government spends so much money subsidising micro-turbines.","zh":"政府花大量金錢補貼微型渦輪機。"},{"en":"So much money subsidising something means a very large amount of public or private money is used to support it.","zh":"so much money subsidising something 指用非常大量公共或私人金錢支持某事。"},{"en":"A city may face criticism if it spends so much money subsidising a service few people use.","zh":"如果城市花大量金錢補貼很少人使用的服務，可能受到批評。"},{"en":"Large subsidies can be questioned when better alternatives exist.","zh":"當存在更好替代方案時，大額補貼可能受到質疑。"},{"en":"This phrase emphasises the scale of financial support.","zh":"這個短語強調財務支持的規模。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":11},{"front":"carbon savings are far lower","meaning":"碳減排量低得多","examples":[{"en":"Carbon savings are far lower than they would be with offshore wind farms.","zh":"碳減排量比使用離岸風電場時低得多。"},{"en":"Carbon savings are far lower means the reduction in emissions is much smaller.","zh":"carbon savings are far lower 指排放減少幅度小得多。"},{"en":"Taking a short bus ride instead of walking gives carbon savings far lower than replacing a long car journey.","zh":"短途乘巴士代替步行所帶來的碳減排量，遠低於取代長途駕車。"},{"en":"A policy may look green but still deliver far lower savings than another option.","zh":"一項政策可能看似環保，但仍比另一選項帶來低得多的減排量。"},{"en":"This phrase compares the size of environmental benefit.","zh":"這個短語比較環境好處的大小。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":12},{"front":"nevertheless","meaning":"然而；儘管如此","examples":[{"en":"Nevertheless, the subsidy still has some benefits.","zh":"然而，補貼仍有一些好處。"},{"en":"Nevertheless means despite what has just been said.","zh":"nevertheless 指儘管剛才所說如此。"},{"en":"The plan is expensive; nevertheless, it may help the poorest families.","zh":"這個計劃很昂貴；然而，它可能幫助最貧困家庭。"},{"en":"Writers use nevertheless to show a contrast between criticism and a remaining positive point.","zh":"作者使用 nevertheless 來顯示批評與仍然存在的正面點之間的對比。"},{"en":"This word signals that the next idea does not fully cancel the previous one.","zh":"這個詞表示下一個想法並不完全推翻前一點。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":12},{"front":"the very best way of","meaning":"最佳方法","examples":[{"en":"Subsidising micro-turbines may not be the very best way of using resources.","zh":"補貼微型渦輪機可能不是使用資源的最佳方法。"},{"en":"The very best way of doing something means the most effective or suitable method.","zh":"the very best way of doing something 指最有效或最合適的方法。"},{"en":"Memorising whole essays is not the very best way of improving writing.","zh":"背誦整篇文章不是改善寫作的最佳方法。"},{"en":"A method can be helpful without being the very best way available.","zh":"一種方法可以有幫助，但不一定是可用方法中的最佳方法。"},{"en":"This phrase makes a strong comparison among possible methods.","zh":"這個短語在不同可能方法之間作強烈比較。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":12},{"front":"spending government resources on","meaning":"把政府資源花在……上","examples":[{"en":"The passage evaluates spending government resources on climate action.","zh":"文章評估把政府資源花在氣候行動上。"},{"en":"Spending government resources on something means using public money, staff, or attention for that purpose.","zh":"spending government resources on something 指把公共金錢、人手或注意力用於某目的。"},{"en":"Citizens may debate spending government resources on roads rather than hospitals.","zh":"市民可能爭論把政府資源花在道路而不是醫院上。"},{"en":"Because public resources are limited, spending choices involve priorities.","zh":"因為公共資源有限，支出選擇涉及優先次序。"},{"en":"This phrase focuses on how government funds and capacity are allocated.","zh":"這個短語著重政府資金和能力如何分配。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":12},{"front":"climate change mitigation","meaning":"紓緩氣候變化","examples":[{"en":"Climate change mitigation requires effective investment.","zh":"紓緩氣候變化需要有效投資。"},{"en":"Climate change mitigation means actions that reduce greenhouse gas emissions or slow climate change.","zh":"climate change mitigation 指減少溫室氣體排放或減慢氣候變化的行動。"},{"en":"Planting trees, improving public transport, and using renewable energy can support climate change mitigation.","zh":"種樹、改善公共交通和使用可再生能源可以支持紓緩氣候變化。"},{"en":"Poorly chosen spending may reduce emissions less effectively.","zh":"選擇不當的開支可能較不能有效減排。"},{"en":"This phrase focuses on preventing or reducing climate damage, not simply adapting to it.","zh":"這個短語著重防止或減少氣候損害，而不只是適應它。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":12},{"front":"we are talking about","meaning":"我們談論的是","examples":[{"en":"We are talking about investing only a small percentage of GDP.","zh":"我們談論的是只投資本地生產總值的一小部分。"},{"en":"We are talking about means the discussion concerns a particular amount, issue, or situation.","zh":"we are talking about 指討論涉及某個特定數量、議題或情況。"},{"en":"We are talking about ten minutes of daily practice, not three hours.","zh":"我們談論的是每天十分鐘練習，而不是三小時。"},{"en":"This phrase clarifies the scale or focus of the discussion.","zh":"這個短語澄清討論的規模或焦點。"},{"en":"It helps prevent readers from imagining something larger or smaller than intended.","zh":"它幫助防止讀者想像成比原意更大或更小的事情。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":12},{"front":"investing only about","meaning":"只投資大約","examples":[{"en":"The proposal involves investing only about 0.075 per cent of GDP per year.","zh":"這項建議涉及每年只投資大約本地生產總值的百分之零點零七五。"},{"en":"Investing only about an amount means putting in roughly that limited amount of money.","zh":"investing only about an amount 指投入大約這個有限金額。"},{"en":"A student may improve by investing only about fifteen minutes a day in vocabulary review.","zh":"學生每天只投資大約十五分鐘溫習詞彙，也可能進步。"},{"en":"Small regular investment can still produce useful long-term results.","zh":"小而規律的投資仍可以產生有用長期結果。"},{"en":"This phrase emphasises that the amount is modest.","zh":"這個短語強調金額不大。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":12},{"front":"the nation’s GDP","meaning":"該國本地生產總值","examples":[{"en":"The investment is a very small percentage of the nation’s GDP.","zh":"這項投資是該國本地生產總值中非常小的百分比。"},{"en":"The nation’s GDP is the total value of goods and services produced by a country in a year.","zh":"nation’s GDP 指一個國家一年內生產的商品和服務總值。"},{"en":"Governments compare spending with the nation’s GDP to show whether a policy is large or small.","zh":"政府會把開支與該國本地生產總值比較，以顯示政策規模大小。"},{"en":"A tiny percentage of GDP may still represent a large amount of money.","zh":"本地生產總值的一小百分比仍可能代表一大筆金錢。"},{"en":"This phrase gives an economic scale for national spending.","zh":"這個短語為國家開支提供經濟規模。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":12},{"front":"a reduction in carbon emissions","meaning":"碳排放減少","examples":[{"en":"The investment could achieve a one per cent reduction in carbon emissions.","zh":"這項投資可以實現百分之一的碳排放減少。"},{"en":"A reduction in carbon emissions means a decrease in the amount of carbon-related greenhouse gases released.","zh":"reduction in carbon emissions 指與碳相關的溫室氣體釋放量下降。"},{"en":"Using buses instead of cars can create a reduction in carbon emissions.","zh":"使用巴士而不是私家車可以造成碳排放減少。"},{"en":"Reductions in emissions help slow climate change when they happen at scale.","zh":"當排放減少具有規模時，有助減慢氣候變化。"},{"en":"This phrase measures environmental improvement through lower pollution.","zh":"這個短語透過較低污染量度環境改善。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":12},{"front":"a worthwhile benefit","meaning":"值得的好處","examples":[{"en":"A one per cent reduction in emissions is a worthwhile benefit.","zh":"排放減少百分之一是值得的好處。"},{"en":"A worthwhile benefit is a positive result that is valuable enough to matter.","zh":"worthwhile benefit 指有足夠價值、值得重視的正面結果。"},{"en":"Better sleep is a worthwhile benefit of reducing late-night phone use.","zh":"更好睡眠是減少深夜使用手機帶來的值得好處。"},{"en":"Even a small benefit can be worthwhile if the cost is low and the effect is lasting.","zh":"如果成本低而效果持久，即使小好處也可能值得。"},{"en":"This phrase suggests the gain deserves attention.","zh":"這個短語表示該收益值得注意。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":12},{"front":"it could be much better, but…","meaning":"本可以好得多，但……","examples":[{"en":"The policy could be much better, but it could be worse.","zh":"這項政策本可以好得多，但也可以更差。"},{"en":"It could be much better, but means the situation is imperfect, though not completely bad.","zh":"it could be much better, but 指情況不完美，但並非完全差。"},{"en":"A student’s essay could be much better, but it already has clear examples.","zh":"學生的文章本可以好得多，但它已經有清楚例子。"},{"en":"This phrase gives a balanced judgement by recognising weakness and value together.","zh":"這個短語透過同時承認弱點和價值，給出平衡判斷。"},{"en":"It helps avoid both overpraise and total rejection.","zh":"它幫助避免過度稱讚和完全否定。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":13},{"front":"in addition","meaning":"此外","examples":[{"en":"In addition, the investment helps developing technology.","zh":"此外，這項投資幫助發展中的技術。"},{"en":"In addition means also or as another point.","zh":"in addition 指此外或作為另一點。"},{"en":"The course teaches grammar; in addition, it gives students speaking practice.","zh":"這課程教授文法；此外，它給學生口語練習。"},{"en":"This phrase adds another reason, result, or piece of evidence.","zh":"這個短語加入另一個原因、結果或證據。"},{"en":"It helps build an argument step by step.","zh":"它幫助逐步建立論點。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":13},{"front":"promote and sustain","meaning":"促進並維持","examples":[{"en":"Investment can promote and sustain developing technology.","zh":"投資可以促進並維持發展中的技術。"},{"en":"To promote and sustain something means to help it grow and keep it going over time.","zh":"promote and sustain something 指幫助某事發展並長期維持。"},{"en":"School funding can promote and sustain music programmes for young students.","zh":"學校資金可以促進並維持年輕學生的音樂課程。"},{"en":"New technology may fail without support that both encourages and maintains it.","zh":"新技術如果沒有既鼓勵又維持的支持，可能會失敗。"},{"en":"This phrase combines starting growth with continued support.","zh":"這個短語結合啟動發展和持續支持。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":13},{"front":"developing technology","meaning":"發展中的技術","examples":[{"en":"Subsidies can support developing technology.","zh":"補貼可以支持發展中的技術。"},{"en":"Developing technology is technology that is still improving and becoming more practical.","zh":"developing technology 指仍在改進並變得更實用的技術。"},{"en":"Early electric cars were developing technology before charging stations became common.","zh":"在充電站普及前，早期電動車屬於發展中的技術。"},{"en":"Supporting developing technology can help it become cheaper and more reliable later.","zh":"支持發展中的技術，可以幫助它日後變得更便宜和可靠。"},{"en":"This phrase suggests a tool is not yet fully mature.","zh":"這個短語表示工具尚未完全成熟。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":13},{"front":"one extra favourable way of looking at","meaning":"另一種較正面的看法","examples":[{"en":"There is one extra favourable way of looking at the micro-wind turbine.","zh":"對微型風力渦輪機，還有另一種較正面的看法。"},{"en":"One extra favourable way of looking at something means one additional positive perspective on it.","zh":"one extra favourable way of looking at something 指對某事的另一個正面角度。"},{"en":"A long commute is tiring, but one favourable way of looking at it is that it gives time for reading.","zh":"長途通勤令人疲倦，但另一種較正面的看法是它提供閱讀時間。"},{"en":"Changing perspective can reveal benefits that first calculations miss.","zh":"改變角度可以揭示初步計算錯過的好處。"},{"en":"This phrase introduces another positive interpretation.","zh":"這個短語引入另一種正面詮釋。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":13},{"front":"even if","meaning":"即使","examples":[{"en":"The subsidy may have benefits even if it is not the best investment.","zh":"即使補貼不是最佳投資，它仍可能有好處。"},{"en":"Even if means although something may be true.","zh":"even if 指即使某事可能是真的。"},{"en":"Students should keep practising even if progress feels slow.","zh":"即使進步感覺緩慢，學生仍應繼續練習。"},{"en":"A policy can have value even if another policy would be better.","zh":"即使另一項政策會更好，某政策仍可以有價值。"},{"en":"This phrase introduces a concession while keeping the main point.","zh":"這個短語引入讓步，同時保留主要觀點。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":13},{"front":"the single best way of","meaning":"唯一最佳方法","examples":[{"en":"The micro-turbine is not the single best way of cutting carbon.","zh":"微型渦輪機不是減少碳排放的唯一最佳方法。"},{"en":"The single best way of doing something means the one most effective method among all options.","zh":"single best way of doing something 指所有選項中唯一最有效的方法。"},{"en":"There is rarely a single best way of learning English because students need different methods.","zh":"學英文很少有唯一最佳方法，因為學生需要不同方法。"},{"en":"A method can be useful without being the single best way.","zh":"一種方法可以有用，但不一定是唯一最佳方法。"},{"en":"This phrase makes a strong claim about ranking among alternatives.","zh":"這個短語對不同替代方案之間的排名作出強烈說法。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":13},{"front":"cutting carbon","meaning":"減少碳排放","examples":[{"en":"Governments invest in technologies for cutting carbon.","zh":"政府投資於減少碳排放的技術。"},{"en":"Cutting carbon means reducing carbon emissions or carbon-related pollution.","zh":"cutting carbon 指減少碳排放或與碳相關的污染。"},{"en":"A company can start cutting carbon by using less electricity and cleaner transport.","zh":"公司可以透過少用電和使用較清潔交通開始減少碳排放。"},{"en":"Cutting carbon helps slow climate change when many people and organisations do it.","zh":"當許多人和機構一起減碳，就有助減慢氣候變化。"},{"en":"This phrase is informal but common in climate discussions.","zh":"這個短語較口語，但在氣候討論中常見。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":13},{"front":"input-output modelling","meaning":"投入產出模型","examples":[{"en":"Input-output modelling suggests that most spending has a carbon impact.","zh":"投入產出模型顯示大多數開支都有碳影響。"},{"en":"Input-output modelling is a method that estimates how spending in one area affects production and emissions in other areas.","zh":"input-output modelling 指估算某方面開支如何影響其他方面生產和排放的方法。"},{"en":"Economists may use input-output modelling to estimate the hidden effects of building a school.","zh":"經濟學家可能使用投入產出模型估算興建學校的隱藏影響。"},{"en":"This modelling can reveal emissions created indirectly through supply chains.","zh":"這種模型可以揭示透過供應鏈間接產生的排放。"},{"en":"This phrase refers to a calculation method linking purchases with wider economic effects.","zh":"這個短語指把購買與更廣泛經濟影響連繫起來的計算方法。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":13},{"front":"it is actually quite difficult to","meaning":"其實頗難去","examples":[{"en":"It is actually quite difficult to spend money without affecting carbon emissions.","zh":"花錢而不影響碳排放其實頗難。"},{"en":"It is actually quite difficult to do something means the task is harder than people may expect.","zh":"it is actually quite difficult to do something 指某事比人們可能預期更困難。"},{"en":"It is actually quite difficult to sleep well if a phone keeps buzzing beside the bed.","zh":"如果手機一直在床邊震動，要睡得好其實頗難。"},{"en":"This phrase corrects a possible assumption that something is easy.","zh":"這個短語修正某事很容易的可能假設。"},{"en":"It introduces a practical difficulty that may not be obvious.","zh":"它引入一個未必明顯的實際困難。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":13},{"front":"spend money without","meaning":"花錢而不……","examples":[{"en":"It is difficult to spend money without creating a carbon impact.","zh":"花錢而不產生碳影響是困難的。"},{"en":"To spend money without doing something means to make a purchase while avoiding a particular result.","zh":"spend money without doing something 指購買東西時避免某個結果。"},{"en":"It is hard to buy new clothes without creating some packaging waste.","zh":"購買新衣服而不產生任何包裝廢物很難。"},{"en":"Spending money often supports transport, factories, or services that create emissions.","zh":"花錢通常會支持會產生排放的運輸、工廠或服務。"},{"en":"This phrase highlights a consequence that is difficult to avoid.","zh":"這個短語突出一個難以避免的後果。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":14},{"front":"a negative carbon impact","meaning":"負面的碳影響","examples":[{"en":"Most spending has a negative carbon impact.","zh":"大多數開支都有負面的碳影響。"},{"en":"A negative carbon impact means an effect that increases greenhouse gas emissions.","zh":"negative carbon impact 指增加溫室氣體排放的影響。"},{"en":"Buying a petrol car can have a negative carbon impact because it leads to fuel use.","zh":"購買汽油車可能有負面的碳影響，因為它會導致燃料使用。"},{"en":"Even ordinary purchases can have hidden negative carbon impacts through manufacturing and transport.","zh":"即使普通購買，也可能透過製造和運輸產生隱藏的負面碳影響。"},{"en":"This phrase describes climate harm caused by an activity or purchase.","zh":"這個短語描述活動或購買造成的氣候傷害。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":14},{"front":"encourages people to","meaning":"鼓勵人們去","examples":[{"en":"The subsidy encourages people to spend money on carbon-reducing technology.","zh":"補貼鼓勵人們把錢花在減碳技術上。"},{"en":"Encourages people to do something means makes them more likely or willing to do it.","zh":"encourages people to do something 指令人們更可能或更願意做某事。"},{"en":"A discount encourages people to try a new bus service.","zh":"折扣鼓勵人們嘗試新巴士服務。"},{"en":"Government support can encourage people to choose cleaner technology.","zh":"政府支持可以鼓勵人們選擇較清潔技術。"},{"en":"This phrase shows how incentives influence behaviour.","zh":"這個短語顯示誘因如何影響行為。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":14},{"front":"carbon-reducing technology","meaning":"減碳技術","examples":[{"en":"A wind turbine is a carbon-reducing technology.","zh":"風力渦輪機是一種減碳技術。"},{"en":"Carbon-reducing technology is technology that lowers greenhouse gas emissions.","zh":"carbon-reducing technology 指降低溫室氣體排放的技術。"},{"en":"Heat pumps, solar panels, and efficient public transport can be carbon-reducing technologies.","zh":"熱泵、太陽能板和高效公共交通都可以是減碳技術。"},{"en":"Such technology helps most when it replaces high-carbon habits or equipment.","zh":"當這類技術取代高碳習慣或設備時，幫助最大。"},{"en":"This phrase focuses on tools that reduce emissions.","zh":"這個短語著重減少排放的工具。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":14},{"front":"rather than on","meaning":"而不是花在……上","examples":[{"en":"The subsidy shifts spending towards turbines rather than carbon-producing goods.","zh":"補貼把開支轉向渦輪機，而不是花在產生碳排放的商品上。"},{"en":"Rather than on means instead of spending effort, attention, or money on another thing.","zh":"rather than on 指而不是把努力、注意力或金錢花在另一事物上。"},{"en":"A student may spend time on revision rather than on social media before exams.","zh":"考試前，學生可能把時間花在溫習上，而不是社交媒體上。"},{"en":"This phrase clearly contrasts two possible targets for resources.","zh":"這個短語清楚對比資源的兩個可能目標。"},{"en":"It shows where money or attention is redirected.","zh":"它顯示金錢或注意力被轉移到哪裡。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":14},{"front":"carbon-producing goods","meaning":"產生碳排放的商品","examples":[{"en":"Cars are examples of carbon-producing goods.","zh":"汽車是產生碳排放的商品例子。"},{"en":"Carbon-producing goods are products whose manufacture or use creates greenhouse gas emissions.","zh":"carbon-producing goods 指製造或使用時會產生溫室氣體排放的產品。"},{"en":"A petrol lawnmower can be a carbon-producing good because it burns fuel.","zh":"汽油割草機可以是產生碳排放的商品，因為它燃燒燃料。"},{"en":"Buying fewer carbon-producing goods can lower a household’s indirect emissions.","zh":"少買產生碳排放的商品可以降低家庭間接排放。"},{"en":"This phrase identifies products linked to climate pollution.","zh":"這個短語指出與氣候污染相關的產品。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":14},{"front":"overseas holidays","meaning":"海外旅行","examples":[{"en":"Overseas holidays can increase carbon emissions.","zh":"海外旅行可以增加碳排放。"},{"en":"Overseas holidays are trips taken to another country for leisure.","zh":"overseas holidays 指前往另一個國家作休閒旅遊。"},{"en":"A family may take overseas holidays during school breaks if flights are affordable.","zh":"如果機票可負擔，家庭可能在學校假期進行海外旅行。"},{"en":"Overseas holidays often create emissions through air travel, hotels, and transport.","zh":"海外旅行常透過飛行、酒店和交通產生排放。"},{"en":"This phrase contrasts foreign leisure travel with local holidays.","zh":"這個短語把外國休閒旅遊與本地假期作對比。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":14},{"front":"reductions in emissions","meaning":"排放量減少","examples":[{"en":"The reductions in emissions may be greater than the writer’s simple sums suggest.","zh":"排放量減少可能比作者簡單計算所顯示的更大。"},{"en":"Reductions in emissions are decreases in the amount of greenhouse gases released.","zh":"reductions in emissions 指釋放的溫室氣體數量下降。"},{"en":"A city may achieve reductions in emissions by improving buses and cycling routes.","zh":"城市可以透過改善巴士和單車路線實現排放量減少。"},{"en":"Reductions in emissions can come directly from cleaner energy or indirectly from changed spending habits.","zh":"排放量減少可以直接來自較清潔能源，也可以間接來自消費習慣改變。"},{"en":"This phrase focuses on lower pollution levels.","zh":"這個短語著重污染水平下降。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":14},{"front":"simple sums","meaning":"簡單計算","examples":[{"en":"The writer’s simple sums may underestimate the wider benefit.","zh":"作者的簡單計算可能低估更廣泛的好處。"},{"en":"Simple sums are basic calculations that do not include every complex factor.","zh":"simple sums 指沒有包括每個複雜因素的基本計算。"},{"en":"A family’s simple sums may show that eating out is cheap, but service charges change the total.","zh":"家庭的簡單計算可能顯示外出用餐便宜，但服務費會改變總額。"},{"en":"Simple sums are useful for a first estimate but may miss hidden effects.","zh":"簡單計算對初步估算有用，但可能錯過隱藏影響。"},{"en":"This phrase suggests rough arithmetic rather than full analysis.","zh":"這個短語表示粗略算術，而不是完整分析。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":14},{"front":"have suggested","meaning":"所顯示；所暗示","examples":[{"en":"The reductions may be greater than the simple sums have suggested.","zh":"排放量減少可能比簡單計算所顯示的更大。"},{"en":"Have suggested means have indicated or implied based on available evidence.","zh":"have suggested 指根據可用證據顯示或暗示。"},{"en":"The early test results have suggested that students need more vocabulary practice.","zh":"早期測驗結果顯示學生需要更多詞彙練習。"},{"en":"What the numbers have suggested may change after more data are added.","zh":"數字所顯示的情況可能在加入更多數據後改變。"},{"en":"This phrase presents a conclusion that is possible but not final.","zh":"這個短語呈現可能但非最終的結論。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":14},{"front":"Reading Passage 2","meaning":"閱讀篇章二","examples":[{"en":"Reading Passage 2 has seven paragraphs.","zh":"閱讀篇章二有七段。"},{"en":"Reading Passage 2 means the second reading text in a test or exercise.","zh":"Reading Passage 2 指測驗或練習中的第二篇閱讀文章。"},{"en":"Students should check which passage a question refers to before answering.","zh":"學生作答前應檢查題目指的是哪篇文章。"},{"en":"If a test has several passages, confusing them can lead to wrong answers.","zh":"如果測驗有幾篇文章，混淆它們可能導致答案錯誤。"},{"en":"This phrase is a test label, not part of the article’s argument.","zh":"這個短語是測驗標籤，而不是文章論點的一部分。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":15},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Students choose the correct heading for each paragraph.","zh":"學生為每一段選出正確標題。"},{"en":"To choose the correct heading means to select the title that best matches the paragraph’s main idea.","zh":"choose the correct heading 指選擇最符合段落主旨的標題。"},{"en":"Students should read the whole paragraph before choosing the correct heading.","zh":"學生應閱讀整段後再選出正確標題。"},{"en":"Focusing on one small detail can lead to the wrong heading.","zh":"只集中於一個小細節可能導致選錯標題。"},{"en":"This task tests overall understanding rather than word-for-word matching.","zh":"這種題型測試整體理解，而不是逐字配對。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":15},{"front":"for each paragraph","meaning":"為每一段","examples":[{"en":"The task asks for a heading for each paragraph.","zh":"題目要求為每一段選一個標題。"},{"en":"For each paragraph means one answer is needed for every paragraph.","zh":"for each paragraph 指每一段都需要一個答案。"},{"en":"In a reading exercise, students may write one summary sentence for each paragraph.","zh":"在閱讀練習中，學生可能為每一段寫一句摘要。"},{"en":"Missing one paragraph can leave the answer set incomplete.","zh":"漏掉一段可能令答案不完整。"},{"en":"This phrase stresses that the task must be repeated across all paragraphs.","zh":"這個短語強調任務必須在所有段落中重複進行。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":15},{"front":"from the list of headings below","meaning":"從以下標題列表中","examples":[{"en":"The heading must be chosen from the list of headings below.","zh":"標題必須從以下標題列表中選出。"},{"en":"From the list of headings below means from the title options printed under the instruction.","zh":"from the list of headings below 指從指示下方列出的標題選項中。"},{"en":"Students should not create their own heading if they must choose from the list.","zh":"如果必須從列表中選擇，學生不應自己創作標題。"},{"en":"Reading all options first helps avoid choosing a heading too quickly.","zh":"先閱讀所有選項有助避免太快選擇標題。"},{"en":"This phrase tells students where the possible answers are.","zh":"這個短語告訴學生可能答案在哪裡。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":15},{"front":"write the correct number","meaning":"寫下正確編號","examples":[{"en":"Students write the correct number in the answer boxes.","zh":"學生在答案框中寫下正確編號。"},{"en":"To write the correct number means to put the matching numbered option in the answer space.","zh":"write the correct number 指在答案位置填上相應的編號選項。"},{"en":"In matching tasks, students may lose marks if they write the wrong number.","zh":"在配對題中，如果學生寫錯編號，可能會失分。"},{"en":"Checking the number carefully is as important as understanding the paragraph.","zh":"仔細檢查編號與理解段落同樣重要。"},{"en":"This phrase is an instruction about answer format.","zh":"這個短語是關於答案格式的指示。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":15},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生在答題紙上寫下答案。"},{"en":"An answer sheet is the paper or form where test answers must be written.","zh":"answer sheet 指必須寫下測驗答案的紙張或表格。"},{"en":"A student may know the answer but lose marks if it is written in the wrong place on the answer sheet.","zh":"學生可能知道答案，但如果寫在答題紙錯誤位置，仍可能失分。"},{"en":"Checking the answer sheet helps prevent numbering mistakes.","zh":"檢查答題紙有助防止編號錯誤。"},{"en":"This phrase refers to the official place for recording answers.","zh":"這個短語指記錄答案的正式位置。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":15},{"front":"large sums of money","meaning":"大筆金錢","examples":[{"en":"The heading refers to a better use for large sums of money.","zh":"這個標題指大筆金錢的更好用途。"},{"en":"Large sums of money means very big amounts of money.","zh":"large sums of money 指非常大量的金錢。"},{"en":"Building a hospital requires large sums of money for land, equipment, and staff.","zh":"建造醫院需要大筆金錢購買土地、設備和聘請員工。"},{"en":"When large sums of money are involved, people expect careful planning and strong results.","zh":"當涉及大筆金錢時，人們期望有仔細規劃和良好成果。"},{"en":"This phrase emphasises financial scale.","zh":"這個短語強調財務規模。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":15},{"front":"environmental costs","meaning":"環境成本","examples":[{"en":"The paragraph discusses the environmental costs of manufacture and installation.","zh":"該段討論製造和安裝的環境成本。"},{"en":"Environmental costs are harms to nature, climate, air, water, or land caused by an activity.","zh":"environmental costs 指某活動對自然、氣候、空氣、水或土地造成的傷害。"},{"en":"A cheap product may have hidden environmental costs if it creates waste or pollution.","zh":"如果便宜產品製造廢物或污染，它可能有隱藏環境成本。"},{"en":"Considering environmental costs can change whether a project seems worthwhile.","zh":"考慮環境成本可以改變一個項目是否看似值得。"},{"en":"This phrase measures damage beyond financial price.","zh":"這個短語量度金錢價格以外的損害。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":15},{"front":"manufacture and installation","meaning":"製造和安裝","examples":[{"en":"Manufacture and installation both create carbon emissions.","zh":"製造和安裝都會產生碳排放。"},{"en":"Manufacture and installation means making a product and then putting it in place for use.","zh":"manufacture and installation 指製造產品，然後把它安裝到可使用的位置。"},{"en":"A lift’s manufacture and installation can involve factories, transport, builders, and safety checks.","zh":"升降機的製造和安裝可能涉及工廠、運輸、建築工人和安全檢查。"},{"en":"Even green equipment may cause emissions during manufacture and installation.","zh":"即使是綠色設備，也可能在製造和安裝期間造成排放。"},{"en":"This phrase covers the stages before the product begins operating.","zh":"這個短語涵蓋產品開始運作前的階段。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":15},{"front":"estimates of the number of","meaning":"對……數量的估計","examples":[{"en":"The heading refers to estimates of the number of micro-turbines in use.","zh":"這個標題指對使用中的微型渦輪機數量的估計。"},{"en":"Estimates of the number of something are approximate counts when exact figures are unavailable.","zh":"estimates of the number of something 指在沒有準確數字時作出的近似數量計算。"},{"en":"A school may make estimates of the number of students needing lunch before ordering food.","zh":"學校訂餐前可能估計需要午餐的學生數量。"},{"en":"Estimates can guide planning, but they should be updated when better data arrive.","zh":"估計可以引導規劃，但在有更好數據時應更新。"},{"en":"This phrase focuses on rough quantity.","zh":"這個短語著重粗略數量。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":15},{"front":"in use","meaning":"使用中","examples":[{"en":"The heading mentions micro-turbines currently in use.","zh":"這個標題提到目前使用中的微型渦輪機。"},{"en":"In use means being used or operating at the moment.","zh":"in use 指正在被使用或正在運作。"},{"en":"A classroom is in use when a lesson is taking place inside it.","zh":"當課室內正在上課，該課室就是使用中。"},{"en":"Equipment in use needs maintenance because it can wear out over time.","zh":"使用中的設備需要保養，因為它會隨時間磨損。"},{"en":"This phrase contrasts active use with storage or planning.","zh":"這個短語把正在使用與儲存或規劃作對比。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":16},{"front":"environmental benefits","meaning":"環境好處","examples":[{"en":"The passage evaluates the environmental benefits of running a micro-turbine.","zh":"文章評估運作一部微型渦輪機的環境好處。"},{"en":"Environmental benefits are positive effects on nature, climate, air, water, or land.","zh":"environmental benefits 指對自然、氣候、空氣、水或土地的正面影響。"},{"en":"Planting trees can bring environmental benefits such as cleaner air and cooler streets.","zh":"種樹可以帶來較潔淨空氣和較涼街道等環境好處。"},{"en":"Environmental benefits may be smaller if manufacture creates high emissions.","zh":"如果製造過程產生高排放，環境好處可能較小。"},{"en":"This phrase focuses on ecological gain rather than financial gain.","zh":"這個短語著重生態收益，而不是財務收益。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":16},{"front":"running a micro-turbine","meaning":"運作一部微型渦輪機","examples":[{"en":"Running a micro-turbine can reduce carbon emissions.","zh":"運作一部微型渦輪機可以減少碳排放。"},{"en":"Running a micro-turbine means operating it so it produces electricity.","zh":"running a micro-turbine 指操作微型渦輪機，使其產生電力。"},{"en":"A household running a micro-turbine must check maintenance, safety, and electricity output.","zh":"運作微型渦輪機的家庭必須檢查保養、安全和電力輸出。"},{"en":"Running a turbine in a windy place can produce useful power, but a sheltered place may not.","zh":"在多風地方運作渦輪機可以產生有用電力，但受遮擋地方可能不行。"},{"en":"This phrase refers to using the turbine after it has been installed.","zh":"這個短語指渦輪機安裝後的使用。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":16},{"front":"size and output","meaning":"尺寸和輸出","examples":[{"en":"The first paragraph describes the size and output of the largest micro-turbine.","zh":"第一段描述最大型微型渦輪機的尺寸和輸出。"},{"en":"Size and output means how large something is and how much power or product it can produce.","zh":"size and output 指某物有多大，以及它能產生多少功率或產品。"},{"en":"When buying a fridge, families may compare size and output such as storage space and energy use.","zh":"買雪櫃時，家庭可能比較尺寸和輸出，例如儲存空間和能源使用。"},{"en":"A turbine’s size and output affect cost, location needs, and electricity production.","zh":"渦輪機的尺寸和輸出會影響成本、地點需求和發電量。"},{"en":"This phrase combines physical scale with performance.","zh":"這個短語結合實體規模和表現。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":16},{"front":"the largest type of","meaning":"最大型的……種類","examples":[{"en":"The heading refers to the largest type of micro-turbine.","zh":"這個標題指最大型的微型渦輪機種類。"},{"en":"The largest type of something means the biggest category within a group.","zh":"largest type of something 指某組別中最大的一類。"},{"en":"A double-decker bus is among the largest types of public road vehicles.","zh":"雙層巴士屬於最大型的公共道路車輛種類之一。"},{"en":"The largest type usually needs more space, more money, and stronger support.","zh":"最大型種類通常需要更多空間、更多金錢和更強支撐。"},{"en":"This phrase compares categories by size.","zh":"這個短語按大小比較類別。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":16},{"front":"a limited case for","meaning":"對……的有限支持理據","examples":[{"en":"The passage presents a limited case for subsidising micro-turbines.","zh":"文章提出對補貼微型渦輪機的有限支持理據。"},{"en":"A limited case for something is an argument that supports it only partly or under certain conditions.","zh":"limited case for something 指只在某些方面或特定條件下支持某事的論據。"},{"en":"There is a limited case for giving students homework if it is short and useful.","zh":"如果功課短而有用，就有有限理據支持給學生功課。"},{"en":"A limited argument accepts some benefits but does not claim the policy is the best option.","zh":"有限論據承認一些好處，但不聲稱該政策是最佳選項。"},{"en":"This phrase signals cautious support.","zh":"這個短語表示謹慎支持。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":16},{"front":"subsidising micro-turbines","meaning":"補貼微型渦輪機","examples":[{"en":"Subsidising micro-turbines may support developing technology.","zh":"補貼微型渦輪機可能支持發展中的技術。"},{"en":"Subsidising micro-turbines means using public money to help people buy or operate small wind turbines.","zh":"subsidising micro-turbines 指使用公共金錢幫助人們購買或運作小型風力渦輪機。"},{"en":"A government may subsidise home insulation to encourage lower energy use.","zh":"政府可能補貼家居隔熱，以鼓勵降低能源使用。"},{"en":"Subsidising technology can increase adoption, but it may not always be the cheapest carbon strategy.","zh":"補貼技術可以提高採用率，但未必總是最便宜的減碳策略。"},{"en":"This phrase focuses on financial support for small wind systems.","zh":"這個短語著重對小型風力系統的財務支持。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":16},{"front":"recent improvements in","meaning":"……方面的最新改良","examples":[{"en":"The heading refers to recent improvements in turbine design.","zh":"這個標題指渦輪機設計方面的最新改良。"},{"en":"Recent improvements in something are new changes that make it better.","zh":"recent improvements in something 指使某事變得更好的新近改變。"},{"en":"Recent improvements in school Wi-Fi made online lessons smoother.","zh":"學校 Wi-Fi 方面的最新改良令網上課堂更順暢。"},{"en":"Improvements can make old technology more useful, cheaper, or safer.","zh":"改良可以令舊技術更有用、更便宜或更安全。"},{"en":"This phrase focuses on progress that has happened not long ago.","zh":"這個短語著重不久前發生的進步。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":16},{"front":"the design of micro-turbines","meaning":"微型渦輪機設計","examples":[{"en":"The heading mentions the design of micro-turbines.","zh":"這個標題提到微型渦輪機設計。"},{"en":"The design of micro-turbines means how small turbines are shaped, built, and arranged to work.","zh":"design of micro-turbines 指小型渦輪機如何被塑形、建造和安排以便運作。"},{"en":"Engineers may improve the design of micro-turbines to make them quieter and more efficient.","zh":"工程師可能改善微型渦輪機設計，使其更安靜和更有效率。"},{"en":"Better design can increase output without increasing size too much.","zh":"更好設計可以在不大幅增加尺寸下提高輸出。"},{"en":"This phrase focuses on engineering features, not only appearance.","zh":"這個短語著重工程特徵，而不只是外觀。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":16},{"front":"an indirect method of","meaning":"……的間接方法","examples":[{"en":"The final paragraph describes an indirect method of reducing carbon emissions.","zh":"最後一段描述減少碳排放的間接方法。"},{"en":"An indirect method of doing something achieves a result through another effect or route.","zh":"indirect method of doing something 指透過另一效果或途徑達成結果的方法。"},{"en":"Teaching parents about sleep may be an indirect method of improving student concentration.","zh":"教育家長睡眠知識可能是改善學生專注力的間接方法。"},{"en":"Indirect methods can matter when they change behaviour behind the main problem.","zh":"當間接方法改變主要問題背後的行為時，它也可以重要。"},{"en":"This phrase contrasts direct action with a less obvious route.","zh":"這個短語把直接行動與較不明顯途徑作對比。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":16},{"front":"reducing carbon emissions","meaning":"減少碳排放","examples":[{"en":"Micro-turbines may help by reducing carbon emissions directly and indirectly.","zh":"微型渦輪機可能透過直接和間接減少碳排放來提供幫助。"},{"en":"Reducing carbon emissions means lowering the amount of carbon-related greenhouse gases released.","zh":"reducing carbon emissions 指降低與碳相關的溫室氣體釋放量。"},{"en":"Walking instead of driving short distances can help reduce carbon emissions.","zh":"短途步行而不是駕車可以幫助減少碳排放。"},{"en":"Reducing emissions is important because greenhouse gases contribute to climate change.","zh":"減少排放很重要，因為溫室氣體會導致氣候變化。"},{"en":"This phrase focuses on cutting climate-related pollution.","zh":"這個短語著重削減與氣候相關的污染。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":17},{"front":"financial benefits","meaning":"財務好處","examples":[{"en":"The paragraph discusses the financial benefits of running a micro-turbine.","zh":"該段討論運作微型渦輪機的財務好處。"},{"en":"Financial benefits are money-related advantages, such as income, savings, or returns.","zh":"financial benefits 指與金錢有關的好處，例如收入、節省或回報。"},{"en":"A student discount gives financial benefits because it lowers travel costs.","zh":"學生折扣帶來財務好處，因為它降低交通成本。"},{"en":"Financial benefits can make an expensive green product easier to accept.","zh":"財務好處可以令昂貴綠色產品較易被接受。"},{"en":"This phrase focuses on money, not environmental value.","zh":"這個短語著重金錢，而不是環境價值。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":17},{"front":"choose two letters","meaning":"選出兩個字母","examples":[{"en":"Students choose two letters from the answer options.","zh":"學生從答案選項中選出兩個字母。"},{"en":"Choose two letters means select exactly two lettered answers.","zh":"choose two letters 指準確選出兩個以字母標示的答案。"},{"en":"In a multiple-answer question, students should not choose three letters if the instruction says two.","zh":"在多答案題中，如果指示說兩個，學生不應選三個字母。"},{"en":"Careful reading of this instruction prevents format mistakes.","zh":"仔細閱讀這個指示可以防止格式錯誤。"},{"en":"This phrase tells students the required number of answers.","zh":"這個短語告訴學生所需答案數量。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":17},{"front":"statements about","meaning":"關於……的陳述","examples":[{"en":"The question asks which statements about micro-wind turbines are made by the writer.","zh":"題目問哪些關於微型風力渦輪機的陳述是作者提出的。"},{"en":"Statements about something are claims or sentences that give information or opinions on it.","zh":"statements about something 指給出關於某事資訊或意見的說法或句子。"},{"en":"Students should check whether statements about a passage are actually supported by the text.","zh":"學生應檢查關於文章的陳述是否真的由文本支持。"},{"en":"Unsupported statements can sound true but still be wrong in reading tests.","zh":"沒有支持的陳述可能聽起來真實，但在閱讀測驗中仍是錯的。"},{"en":"This phrase focuses on claims concerning a topic.","zh":"這個短語著重關於某主題的說法。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":17},{"front":"made by the writer","meaning":"由作者提出的","examples":[{"en":"The correct options are statements made by the writer.","zh":"正確選項是由作者提出的陳述。"},{"en":"Made by the writer means stated, suggested, or supported by the author in the passage.","zh":"made by the writer 指由作者在文章中說出、暗示或支持。"},{"en":"Students should not choose an answer just because they personally agree with it.","zh":"學生不應只因自己同意某答案就選它。"},{"en":"In reading tests, what matters is whether the point is made by the writer.","zh":"在閱讀測驗中，重要的是該點是否由作者提出。"},{"en":"This phrase directs attention back to the source text.","zh":"這個短語把注意力帶回原文。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":17},{"front":"in certain areas","meaning":"在某些地區","examples":[{"en":"In certain areas, permission may be required to install turbines.","zh":"在某些地區，安裝渦輪機可能需要許可。"},{"en":"In certain areas means in some particular places, but not everywhere.","zh":"in certain areas 指在某些特定地方，但不是所有地方。"},{"en":"In certain areas, parking is only allowed for residents.","zh":"在某些地區，只有居民可以泊車。"},{"en":"Rules can differ by location, so a plan may be legal in one place but restricted in another.","zh":"規則可以因地點而異，所以一個計劃在某地合法，在另一地可能受限制。"},{"en":"This phrase limits a statement to specific places.","zh":"這個短語把說法限制在特定地方。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":17},{"front":"permission is required to","meaning":"需要許可去","examples":[{"en":"Permission is required to install some energy equipment.","zh":"安裝某些能源設備需要許可。"},{"en":"Permission is required to do something means official approval is needed before doing it.","zh":"permission is required to do something 指做某事前需要官方批准。"},{"en":"Permission is required to use the school hall after normal hours.","zh":"正常時間後使用學校禮堂需要許可。"},{"en":"If permission is required, starting without approval may lead to fines or removal.","zh":"如果需要許可，未經批准就開始可能導致罰款或拆除。"},{"en":"This phrase highlights a legal or administrative requirement.","zh":"這個短語突出法律或行政要求。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":17},{"front":"install them","meaning":"安裝它們","examples":[{"en":"Some households may need permission to install them.","zh":"有些家庭可能需要許可去安裝它們。"},{"en":"To install them means to put the devices in place so they can operate.","zh":"install them 指把那些裝置放置好，使其可以運作。"},{"en":"A family may hire technicians to install solar panels on the roof.","zh":"家庭可能聘請技術員在屋頂安裝太陽能板。"},{"en":"Large equipment must be installed safely because poor installation can cause danger.","zh":"大型設備必須安全安裝，因為差劣安裝可能造成危險。"},{"en":"This phrase refers to setting up the devices, not simply buying them.","zh":"這個短語指設置裝置，而不只是購買它們。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":17},{"front":"exact energy output","meaning":"確切能源輸出","examples":[{"en":"The exact energy output depends on the turbine’s position.","zh":"確切能源輸出取決於渦輪機的位置。"},{"en":"Exact energy output is the precise amount of energy a device produces.","zh":"exact energy output 指裝置產生的精確能源量。"},{"en":"A solar panel’s exact energy output changes with sunlight, shade, and angle.","zh":"太陽能板的確切能源輸出會隨陽光、陰影和角度而改變。"},{"en":"Knowing exact output helps owners judge whether the investment is worthwhile.","zh":"知道確切輸出有助擁有人判斷投資是否值得。"},{"en":"This phrase focuses on measured production, not theoretical maximum capacity.","zh":"這個短語著重量度產量，而不是理論最大能力。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":17},{"front":"depends on their position","meaning":"取決於其位置","examples":[{"en":"Their energy output depends on their position.","zh":"它們的能源輸出取決於其位置。"},{"en":"Depends on their position means is affected by where they are placed.","zh":"depends on their position 指受它們放置地點影響。"},{"en":"A plant’s growth depends on its position because sunlight and shade matter.","zh":"植物生長取決於其位置，因為陽光和陰影很重要。"},{"en":"Wind turbines produce more power when positioned in open, windy places.","zh":"風力渦輪機放在開闊多風地方時，能產生更多電力。"},{"en":"This phrase links location with performance.","zh":"這個短語把位置與表現連繫起來。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":17},{"front":"take less energy to make","meaning":"製造所需能源較少","examples":[{"en":"The option asks whether turbines take less energy to make than other engines.","zh":"這個選項問渦輪機是否比其他引擎製造所需能源較少。"},{"en":"Take less energy to make means require less energy during manufacture.","zh":"take less energy to make 指製造過程需要較少能源。"},{"en":"A reusable bottle may take more energy to make than a plastic cup but last longer.","zh":"可重用水樽製造所需能源可能比膠杯多，但使用壽命更長。"},{"en":"Manufacturing energy matters because it affects the product’s embodied carbon.","zh":"製造能源很重要，因為它影響產品的內含碳。"},{"en":"This phrase compares production costs in energy terms.","zh":"這個短語用能源角度比較生產成本。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":18},{"front":"other engines","meaning":"其他引擎","examples":[{"en":"The option compares micro-turbines with other engines.","zh":"這個選項把微型渦輪機與其他引擎比較。"},{"en":"Other engines are different machines that convert energy into movement or power.","zh":"other engines 指把能源轉化為動力或功率的其他機器。"},{"en":"A car engine and a generator engine are examples of other engines.","zh":"汽車引擎和發電機引擎都是其他引擎例子。"},{"en":"Comparing turbines with other engines can show whether their manufacture is more or less carbon intensive.","zh":"把渦輪機與其他引擎比較，可以顯示其製造是否更高碳或較低碳。"},{"en":"This phrase simply means alternative engine types.","zh":"這個短語只是指其他類型的引擎。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":18},{"front":"contributes towards","meaning":"資助；支付部分……","examples":[{"en":"The option asks whether the UK government contributes towards their purchase cost.","zh":"這個選項問英國政府是否資助它們的購買成本。"},{"en":"Contributes towards something means pays part of the cost or helps support it.","zh":"contributes towards something 指支付部分成本或提供支援。"},{"en":"A school may contribute towards a student’s travel cost for a competition.","zh":"學校可能支付學生參加比賽的部分交通費。"},{"en":"A contribution can make an expensive purchase easier to afford.","zh":"資助可以令昂貴購買較容易負擔。"},{"en":"This phrase usually means partial support, not paying the whole amount.","zh":"這個短語通常表示部分支持，而不是支付全額。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":18},{"front":"purchase cost","meaning":"購買成本","examples":[{"en":"The option refers to the purchase cost of micro-wind turbines.","zh":"這個選項指微型風力渦輪機的購買成本。"},{"en":"Purchase cost is the amount of money needed to buy something.","zh":"purchase cost 指購買某物所需的金錢。"},{"en":"The purchase cost of a phone does not include monthly data charges.","zh":"手機的購買成本不包括每月數據費。"},{"en":"A low purchase cost may still lead to high maintenance costs later.","zh":"低購買成本之後仍可能帶來高維修成本。"},{"en":"This phrase focuses on the buying price before other expenses.","zh":"這個短語著重其他開支之前的購買價格。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":18},{"front":"produce more energy than","meaning":"產生比……更多的能源","examples":[{"en":"Some micro-turbines can produce more energy than a household needs.","zh":"有些微型渦輪機可以產生比一個家庭所需更多的能源。"},{"en":"Produce more energy than means generate a larger amount of energy than a comparison point.","zh":"produce more energy than 指產生的能源量高於某個比較基準。"},{"en":"A rooftop solar system may produce more energy than a family uses on sunny days.","zh":"在晴天，屋頂太陽能系統可能產生比家庭使用更多的能源。"},{"en":"Extra energy can sometimes be stored or sold back to the grid.","zh":"額外能源有時可以儲存或回售予電網。"},{"en":"This phrase compares production with demand.","zh":"這個短語把產量與需求作比較。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":18},{"front":"a household needs","meaning":"一個家庭所需","examples":[{"en":"A large turbine may produce more electricity than a household needs.","zh":"大型渦輪機可能產生比一個家庭所需更多的電力。"},{"en":"A household needs means the amount required by the people living in one home.","zh":"a household needs 指住在一個家中的人所需要的數量。"},{"en":"A household needs enough electricity for lighting, cooking, heating, appliances, and devices.","zh":"一個家庭需要足夠電力供照明、煮食、暖氣、電器和電子設備使用。"},{"en":"If a system produces more than a household needs, the extra power may become surplus electricity.","zh":"如果系統產生超過一個家庭所需，額外電力可能成為剩餘電力。"},{"en":"This phrase focuses on domestic demand.","zh":"這個短語著重家庭需求。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":18},{"front":"complete the sentences below","meaning":"完成以下句子","examples":[{"en":"Students complete the sentences below using words from the passage.","zh":"學生使用文章中的字詞完成以下句子。"},{"en":"Complete the sentences below means fill in missing words in the sentences under the instruction.","zh":"complete the sentences below 指填寫指示下方句子中的空缺字詞。"},{"en":"Students should check grammar and word limits before completing the sentences below.","zh":"學生完成以下句子前應檢查文法和字數限制。"},{"en":"A correct answer must fit both the passage meaning and the sentence structure.","zh":"正確答案必須同時符合文章意思和句子結構。"},{"en":"This phrase is a common reading-test instruction.","zh":"這個短語是常見閱讀測驗指示。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":18},{"front":"no more than three words","meaning":"不多於三個字","examples":[{"en":"Students choose no more than three words from the passage.","zh":"學生從文章中選擇不多於三個字。"},{"en":"No more than three words means one, two, or three words, but not four.","zh":"no more than three words 指一個、兩個或三個字，但不是四個。"},{"en":"If the answer limit is no more than three words, “offshore wind farms” is allowed.","zh":"如果答案限制是不多於三個字，“offshore wind farms” 是可以的。"},{"en":"Writing too many words can lose marks even if the idea is correct.","zh":"即使意思正確，寫太多字也可能失分。"},{"en":"This phrase gives a strict answer-length rule.","zh":"這個短語給出嚴格答案字數規則。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":18},{"front":"a more effective target for","meaning":"對……來說更有效的目標","examples":[{"en":"Offshore wind farms would be a more effective target for government investment.","zh":"離岸風電場會是政府投資更有效的目標。"},{"en":"A more effective target for something is a better place or option to direct money, effort, or attention.","zh":"more effective target for something 指更適合投放金錢、努力或注意力的地方或選項。"},{"en":"If many students fail grammar, grammar practice may be a more effective target for lesson time.","zh":"如果很多學生文法不及格，文法練習可能是課堂時間更有效的目標。"},{"en":"Choosing a more effective target can produce better results with the same resources.","zh":"選擇更有效的目標可以用同樣資源產生更好結果。"},{"en":"This phrase compares where resources should be aimed.","zh":"這個短語比較資源應投向哪裡。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":18},{"front":"government investment","meaning":"政府投資","examples":[{"en":"The passage compares different targets for government investment.","zh":"文章比較政府投資的不同目標。"},{"en":"Government investment is public money used to support projects, services, or infrastructure.","zh":"government investment 指用於支持項目、服務或基建的公共金錢。"},{"en":"Government investment in public transport can reduce traffic and pollution.","zh":"對公共交通的政府投資可以減少交通擠塞和污染。"},{"en":"Poor government investment may waste money if it supports weak projects.","zh":"如果政府投資支持薄弱項目，就可能浪費金錢。"},{"en":"This phrase focuses on how public funds are used for future benefit.","zh":"這個短語著重公共資金如何用於未來好處。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":18},{"front":"an indirect benefit of","meaning":"……的間接好處","examples":[{"en":"An indirect benefit of the subsidy is support for developing technology.","zh":"補貼的間接好處是支持發展中的技術。"},{"en":"An indirect benefit of something is a positive result that happens through another route, not as the main aim.","zh":"indirect benefit of something 指不是主要目標、而是透過另一途徑產生的正面結果。"},{"en":"An indirect benefit of school sports is that students may build friendships.","zh":"學校運動的間接好處是學生可能建立友誼。"},{"en":"Indirect benefits can make a policy more valuable than simple numbers suggest.","zh":"間接好處可以令政策比簡單數字所顯示更有價值。"},{"en":"This phrase points to a side benefit rather than the direct goal.","zh":"這個短語指出附帶好處，而不是直接目標。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":19},{"front":"support it provides for","meaning":"它為……提供的支持","examples":[{"en":"The subsidy is useful because of the support it provides for developing technology.","zh":"這項補貼有用，是因為它為發展中的技術提供支持。"},{"en":"Support it provides for something means the help or resources it gives to that thing.","zh":"support it provides for something 指它給予某事物的幫助或資源。"},{"en":"A school grant is valuable because of the support it provides for low-income students.","zh":"學校資助有價值，是因為它為低收入學生提供支持。"},{"en":"Support can keep a new programme alive until it becomes stable.","zh":"支持可以令新計劃維持下去，直到它變得穩定。"},{"en":"This phrase explains why something has value beyond its immediate result.","zh":"這個短語解釋某事為何有超越即時結果的價值。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":19},{"front":"most spending","meaning":"大多數開支","examples":[{"en":"Most spending has some effect on the environment.","zh":"大多數開支都對環境有某種影響。"},{"en":"Most spending means the majority of money used to buy goods or services.","zh":"most spending 指用於購買商品或服務的大部分金錢。"},{"en":"Most spending by a household goes on housing, food, transport, and bills.","zh":"家庭的大多數開支用於住屋、食物、交通和賬單。"},{"en":"Because purchases involve production and transport, most spending has some environmental effect.","zh":"因為購買涉及生產和運輸，大多數開支都有某種環境影響。"},{"en":"This phrase generalises across many types of purchases.","zh":"這個短語概括許多類型的購買。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":19},{"front":"effect on the environment","meaning":"對環境的影響","examples":[{"en":"Spending money often has a negative effect on the environment.","zh":"花錢通常對環境有負面影響。"},{"en":"An effect on the environment is a change caused to nature, climate, air, water, or land.","zh":"effect on the environment 指對自然、氣候、空氣、水或土地造成的改變。"},{"en":"A new road can have an effect on the environment by increasing traffic and noise.","zh":"新道路可以透過增加交通和噪音對環境產生影響。"},{"en":"Measuring environmental effects helps people judge whether a project is responsible.","zh":"量度環境影響有助人們判斷項目是否負責任。"},{"en":"This phrase focuses on environmental consequences.","zh":"這個短語著重環境後果。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":19},{"front":"have less money to spend on","meaning":"可花在……上的錢較少","examples":[{"en":"People who buy a micro-turbine have less money to spend on carbon-producing goods.","zh":"購買微型渦輪機的人，可花在產生碳排放商品上的錢較少。"},{"en":"Have less money to spend on something means have a smaller amount available for that purpose.","zh":"have less money to spend on something 指可用於某目的的金錢較少。"},{"en":"If a student buys an expensive laptop, they may have less money to spend on entertainment.","zh":"如果學生購買昂貴手提電腦，就可能有較少錢花在娛樂上。"},{"en":"Spending on one thing naturally reduces what remains for other purchases.","zh":"花錢在一件事上，自然會減少剩下可用於其他購買的金錢。"},{"en":"This phrase links one purchase with reduced spending elsewhere.","zh":"這個短語把一項購買與其他地方的開支減少連繫起來。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":19},{"front":"things such as","meaning":"例如……的東西","examples":[{"en":"People may spend money on things such as foreign holidays and cars.","zh":"人們可能把錢花在例如外國旅行和汽車的東西上。"},{"en":"Things such as is used to introduce examples.","zh":"things such as 用來引入例子。"},{"en":"A school bag may contain things such as books, pens, keys, and a water bottle.","zh":"書包可能包含例如書、筆、鑰匙和水樽的東西。"},{"en":"Examples after this phrase help readers understand the category being discussed.","zh":"這個短語後面的例子幫助讀者理解正在討論的類別。"},{"en":"This phrase means the list is not complete.","zh":"這個短語表示清單並不完整。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":19},{"front":"foreign holidays","meaning":"外國旅行","examples":[{"en":"Foreign holidays can increase a household’s carbon footprint.","zh":"外國旅行可以增加一個家庭的碳足跡。"},{"en":"Foreign holidays are leisure trips to other countries.","zh":"foreign holidays 指前往其他國家的休閒旅行。"},{"en":"A family may plan foreign holidays during long school breaks.","zh":"家庭可能在長學校假期計劃外國旅行。"},{"en":"Flights, hotels, and local transport can make foreign holidays carbon intensive.","zh":"航班、酒店和本地交通可以令外國旅行碳排放密集。"},{"en":"This phrase contrasts overseas leisure travel with staying in one’s own country.","zh":"這個短語把海外休閒旅遊與留在自己國家作對比。"}],"source":"111 - An assessment of micro-wind turbines.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 112":[{"front":"measures to combat","meaning":"應對……的措施","examples":[{"en":"The passage discusses measures to combat infectious disease in Tsarist Russia.","zh":"文章討論沙皇俄國應對傳染病的措施。"},{"en":"Measures to combat something are actions taken to fight, reduce, or control a serious problem.","zh":"measures to combat something 指為對抗、減少或控制嚴重問題而採取的行動。"},{"en":"Schools may introduce measures to combat bullying, such as reporting systems and counselling.","zh":"學校可能推出應對欺凌的措施，例如舉報系統和輔導。"},{"en":"Governments use measures to combat disease when they limit travel, isolate patients, or share health information.","zh":"政府限制出行、隔離病人或分享健康資訊時，就是使用應對疾病的措施。"},{"en":"The phrase suggests organised action, not just general worry.","zh":"這個短語暗示有組織的行動，而不只是一般擔心。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":1},{"front":"infectious disease","meaning":"傳染病","examples":[{"en":"Plague was a highly infectious disease that threatened Russia.","zh":"鼠疫是一種威脅俄國的高度傳染病。"},{"en":"An infectious disease is an illness that can spread from one person, animal, or place to another.","zh":"infectious disease 指可以由一個人、動物或地方傳播到另一處的疾病。"},{"en":"Flu is an infectious disease that can spread quickly in crowded classrooms.","zh":"流感是一種可以在擠迫課室中迅速傳播的傳染病。"},{"en":"If an infectious disease spreads through a city, hospitals and public services may come under pressure.","zh":"如果傳染病在城市中蔓延，醫院和公共服務可能承受壓力。"},{"en":"The phrase focuses on the ability of a disease to spread.","zh":"這個短語重點是疾病的傳播能力。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":1},{"front":"Tsarist Russia","meaning":"沙皇俄國","examples":[{"en":"Tsarist Russia introduced measures to prevent plague outbreaks.","zh":"沙皇俄國引入措施防止鼠疫爆發。"},{"en":"Tsarist Russia means Russia during the period when it was ruled by a tsar.","zh":"Tsarist Russia 指由沙皇統治時期的俄國。"},{"en":"In history lessons, students may compare Tsarist Russia with later Soviet Russia.","zh":"在歷史課中，學生可能把沙皇俄國與後來的蘇維埃俄國作比較。"},{"en":"Because Tsarist Russia was a large empire, controlling disease at its borders was difficult.","zh":"由於沙皇俄國是一個龐大帝國，在邊境控制疾病很困難。"},{"en":"The phrase refers to a historical political period, not modern Russia.","zh":"這個短語指歷史政治時期，而不是現代俄羅斯。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":1},{"front":"in the second half of","meaning":"在……的下半葉","examples":[{"en":"In the second half of the seventeenth century, Russia began border controls.","zh":"在十七世紀下半葉，俄國開始邊境管制。"},{"en":"In the second half of a period means during the later part of that period.","zh":"in the second half of a period 指在某段時期的較後部分。"},{"en":"In the second half of the school year, students often prepare more seriously for exams.","zh":"在學年下半段，學生通常更認真準備考試。"},{"en":"If reforms begin in the second half of a century, they happen after the midpoint of that century.","zh":"如果改革在某世紀下半葉開始，它們就是在該世紀中點之後發生。"},{"en":"The phrase gives an approximate time range, not an exact date.","zh":"這個短語提供大約時間範圍，而不是確切日期。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":1},{"front":"Russian authorities","meaning":"俄國當局","examples":[{"en":"Russian authorities began implementing controls at the borders.","zh":"俄國當局開始在邊境實施管制。"},{"en":"Russian authorities are the officials or government bodies responsible for decisions and enforcement in Russia.","zh":"Russian authorities 指在俄國負責決策和執行的官員或政府機構。"},{"en":"During an emergency, authorities may close roads, issue warnings, or organise medical help.","zh":"在緊急情況中，當局可能封路、發出警告或組織醫療協助。"},{"en":"If Russian authorities received news of plague abroad, they could restrict travel and trade.","zh":"如果俄國當局收到外國鼠疫消息，他們可以限制出行和貿易。"},{"en":"The phrase refers to official power, not ordinary citizens.","zh":"這個短語指官方權力，而不是普通市民。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":1},{"front":"implement controls","meaning":"實施管制","examples":[{"en":"Russian authorities began to implement controls at the borders of the empire.","zh":"俄國當局開始在帝國邊境實施管制。"},{"en":"To implement controls means to put rules or restrictions into actual use.","zh":"implement controls 指把規則或限制實際執行。"},{"en":"A school may implement controls on phone use during exams.","zh":"學校可能在考試期間實施手機使用管制。"},{"en":"Governments implement controls during disease outbreaks to reduce movement and contact.","zh":"政府在疾病爆發期間實施管制，以減少流動和接觸。"},{"en":"The phrase stresses action, not just planning.","zh":"這個短語強調行動，而不只是計劃。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":1},{"front":"at the borders of","meaning":"在……的邊境","examples":[{"en":"Controls were introduced at the borders of the Russian empire.","zh":"管制在俄羅斯帝國的邊境被引入。"},{"en":"At the borders of a place means at the edges where one territory meets another.","zh":"at the borders of a place 指在一個地區與另一地區相接的邊界位置。"},{"en":"Customs officers work at the borders of a country to check people and goods.","zh":"海關人員在一個國家的邊境工作，檢查人員和貨物。"},{"en":"Disease controls at the borders can stop infected travellers from entering.","zh":"邊境疾病管制可以阻止受感染旅客入境。"},{"en":"The phrase focuses on boundary areas between places.","zh":"這個短語重點是地方之間的邊界區域。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":1},{"front":"prevent the importation of","meaning":"防止……輸入","examples":[{"en":"Russia introduced controls to prevent the importation of plague.","zh":"俄國引入管制，以防止鼠疫輸入。"},{"en":"To prevent the importation of something means to stop it from being brought into a country or area.","zh":"prevent the importation of something 指阻止某物被帶入一個國家或地區。"},{"en":"Airports check food to prevent the importation of pests and animal diseases.","zh":"機場檢查食物，以防止害蟲和動物疾病輸入。"},{"en":"If officials prevent the importation of infection, they reduce the chance of local outbreaks.","zh":"如果官員防止感染輸入，他們就降低本地爆發機會。"},{"en":"The phrase is often used for disease, goods, or harmful organisms entering from outside.","zh":"這個短語常用於疾病、貨物或有害生物從外部進入。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":1},{"front":"plague","meaning":"鼠疫","examples":[{"en":"Plague was a highly infectious and dangerous disease.","zh":"鼠疫是一種高度傳染且危險的疾病。"},{"en":"Plague is a severe infectious disease that caused many deadly outbreaks in history.","zh":"plague 指一種嚴重傳染病，歷史上造成許多致命爆發。"},{"en":"History books often describe plague as a disease that could kill large numbers of people quickly.","zh":"歷史書常把鼠疫描述為能迅速殺死大量人口的疾病。"},{"en":"When plague appeared in a city, authorities often used quarantine and isolation.","zh":"當鼠疫在城市出現，當局通常使用檢疫和隔離。"},{"en":"The word is also used more generally for a serious widespread problem, but here it means the disease.","zh":"這個詞也可泛指嚴重廣泛問題，但在這裡指疾病。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":1},{"front":"highly infectious","meaning":"高度傳染性的","examples":[{"en":"Plague was a highly infectious and dangerous disease.","zh":"鼠疫是一種高度傳染性且危險的疾病。"},{"en":"Highly infectious means very able to spread from one person or place to another.","zh":"highly infectious 指非常容易在人與人或地方之間傳播。"},{"en":"A highly infectious illness can spread quickly in schools, buses, or markets.","zh":"高度傳染性的疾病可以在學校、巴士或市場中迅速傳播。"},{"en":"If a disease is highly infectious, early isolation becomes especially important.","zh":"如果疾病高度傳染，早期隔離就特別重要。"},{"en":"The phrase describes how easily something spreads.","zh":"這個短語描述某事傳播得有多容易。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":1},{"front":"dangerous disease","meaning":"危險疾病","examples":[{"en":"Plague was regarded as a dangerous disease.","zh":"鼠疫被視為危險疾病。"},{"en":"A dangerous disease is an illness that can seriously harm or kill people.","zh":"dangerous disease 指可以嚴重傷害或殺死人類的疾病。"},{"en":"A disease becomes dangerous when it spreads quickly and treatment is limited.","zh":"當疾病傳播迅速而治療有限，它就變得危險。"},{"en":"Dangerous diseases require careful reporting, medical care, and public health action.","zh":"危險疾病需要仔細通報、醫療照顧和公共衛生行動。"},{"en":"The phrase stresses the seriousness of the illness.","zh":"這個短語強調疾病的嚴重性。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":1},{"front":"disease outbreaks","meaning":"疾病爆發","examples":[{"en":"Information on disease outbreaks abroad was reported to the tsar’s court.","zh":"外國疾病爆發的資訊被匯報給沙皇宮廷。"},{"en":"Disease outbreaks are sudden increases in cases of illness in a place.","zh":"disease outbreaks 指某地疾病個案突然增加。"},{"en":"A school may close temporarily during disease outbreaks to reduce infection.","zh":"學校可能在疾病爆發期間暫時關閉，以減少感染。"},{"en":"Early information about disease outbreaks helps authorities prepare controls.","zh":"疾病爆發的早期資訊幫助當局準備管制。"},{"en":"The phrase describes a group-level health event, not one isolated patient.","zh":"這個短語描述群體層面的健康事件，而不是單一病人。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":2},{"front":"occur abroad","meaning":"在外國發生","examples":[{"en":"Russian officials collected information on outbreaks occurring abroad.","zh":"俄國官員收集在外國發生的疫情資訊。"},{"en":"To occur abroad means to happen in another country.","zh":"occur abroad 指在另一個國家發生。"},{"en":"If a financial crisis occurs abroad, local businesses may still be affected.","zh":"如果金融危機在外國發生，本地企業仍可能受影響。"},{"en":"Disease outbreaks occurring abroad can matter if trade and travel connect the countries.","zh":"如果貿易和旅行把各國連接起來，在外國發生的疾病爆發也可能重要。"},{"en":"The phrase focuses on events outside one’s own country.","zh":"這個短語重點是自己國家以外的事件。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":2},{"front":"be regularly reported to","meaning":"定期匯報給……","examples":[{"en":"Information on outbreaks was regularly reported to the tsar’s court.","zh":"疫情資訊定期匯報給沙皇宮廷。"},{"en":"To be regularly reported to someone means to be sent or told to them repeatedly and systematically.","zh":"be regularly reported to someone 指反覆並有系統地把資訊傳給某人。"},{"en":"Attendance problems may be regularly reported to the school principal.","zh":"出席問題可能定期匯報給校長。"},{"en":"If disease news is regularly reported to authorities, they can respond faster.","zh":"如果疾病消息定期匯報給當局，他們可以更快回應。"},{"en":"The phrase suggests an organised flow of information.","zh":"這個短語暗示有組織的資訊流動。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":2},{"front":"the tsar’s court","meaning":"沙皇宮廷","examples":[{"en":"News of disease outbreaks was reported to the tsar’s court.","zh":"疾病爆發的消息被匯報給沙皇宮廷。"},{"en":"The tsar’s court was the royal centre around the Russian ruler, including officials and advisers.","zh":"tsar’s court 指圍繞俄國統治者的皇家中心，包括官員和顧問。"},{"en":"Important foreign news could reach the tsar’s court through diplomats and merchants.","zh":"重要外國消息可以透過外交官和商人傳到沙皇宮廷。"},{"en":"If the tsar’s court received disease warnings, it could order border controls.","zh":"如果沙皇宮廷收到疾病警告，它可以下令邊境管制。"},{"en":"The phrase refers to the ruler’s political and royal circle.","zh":"這個短語指統治者的政治和皇家圈子。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":2},{"front":"through various means","meaning":"透過各種方式","examples":[{"en":"Information reached the tsar’s court through various means.","zh":"資訊透過各種方式傳到沙皇宮廷。"},{"en":"Through various means means by several different methods or channels.","zh":"through various means 指透過幾種不同方法或渠道。"},{"en":"A teacher may contact parents through various means, including email, phone calls, and letters.","zh":"老師可能透過電郵、電話和信件等各種方式聯絡家長。"},{"en":"When information comes through various means, authorities can compare different sources.","zh":"當資訊透過各種方式傳來，當局可以比較不同來源。"},{"en":"The phrase shows that there was not only one route.","zh":"這個短語顯示並非只有一條途徑。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":2},{"front":"commercial channels","meaning":"商業渠道","examples":[{"en":"Travelling merchants provided information through commercial channels.","zh":"往來商人透過商業渠道提供資訊。"},{"en":"Commercial channels are routes of communication created by trade and business activity.","zh":"commercial channels 指由貿易和商業活動形成的溝通途徑。"},{"en":"Shop owners may hear market news through commercial channels before newspapers report it.","zh":"店主可能在報紙報道前已透過商業渠道聽到市場消息。"},{"en":"Trade routes can become commercial channels for both goods and information.","zh":"貿易路線可以成為貨物和資訊的商業渠道。"},{"en":"The phrase connects business networks with communication.","zh":"這個短語把商業網絡與溝通連起來。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":2},{"front":"travelling merchants","meaning":"流動商人；往來商人","examples":[{"en":"Travelling merchants helped report disease outbreaks abroad.","zh":"往來商人幫助報告外國疾病爆發。"},{"en":"Travelling merchants are traders who move from place to place to buy and sell goods.","zh":"travelling merchants 指到不同地方買賣貨物的商人。"},{"en":"Travelling merchants may hear news from ports, markets, and border towns.","zh":"往來商人可能從港口、市場和邊境城鎮聽到消息。"},{"en":"Because they moved between regions, travelling merchants could spread information as well as goods.","zh":"由於他們在地區之間流動，往來商人既可以傳播貨物，也可以傳播資訊。"},{"en":"The phrase refers to mobile traders, not shopkeepers who stay in one place.","zh":"這個短語指流動商人，而不是固定在一處的店主。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":2},{"front":"military personnel","meaning":"軍事人員","examples":[{"en":"Military personnel deployed abroad reported information about outbreaks.","zh":"被派駐海外的軍事人員報告疫情資訊。"},{"en":"Military personnel are people who serve in the army, navy, air force, or other armed forces.","zh":"military personnel 指在陸軍、海軍、空軍或其他武裝力量服役的人。"},{"en":"Military personnel may be sent to border areas during emergencies.","zh":"軍事人員可能在緊急情況中被派往邊境地區。"},{"en":"Because military personnel travel for campaigns, they may notice disease conditions in other regions.","zh":"由於軍事人員因戰役而移動，他們可能注意到其他地區的疾病情況。"},{"en":"The phrase refers to service members, not civilians.","zh":"這個短語指服役人員，而不是平民。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":2},{"front":"be deployed abroad","meaning":"被派駐海外","examples":[{"en":"Military personnel were deployed abroad to serve the empire.","zh":"軍事人員被派駐海外為帝國服務。"},{"en":"To be deployed abroad means to be sent to another country for official duty, especially military work.","zh":"be deployed abroad 指被派到另一個國家執行官方職務，尤其是軍事工作。"},{"en":"Doctors may be deployed abroad after an earthquake to provide emergency care.","zh":"地震後，醫生可能被派駐海外提供緊急護理。"},{"en":"Soldiers deployed abroad can bring back information about war, trade, or disease.","zh":"被派駐海外的士兵可以帶回戰爭、貿易或疾病資訊。"},{"en":"The phrase suggests organised official assignment outside the country.","zh":"這個短語暗示有組織的海外官方派遣。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":2},{"front":"undercover agents","meaning":"秘密探員","examples":[{"en":"Undercover agents were one source of information about disease outbreaks.","zh":"秘密探員是疾病爆發資訊的一個來源。"},{"en":"Undercover agents are people who secretly gather information while hiding their real role.","zh":"undercover agents 指隱藏真實身份、秘密收集資訊的人。"},{"en":"Police may use undercover agents to investigate organised crime.","zh":"警方可能使用秘密探員調查有組織犯罪。"},{"en":"Undercover agents can collect information that ordinary officials may not easily receive.","zh":"秘密探員可以收集普通官員不容易取得的資訊。"},{"en":"The phrase suggests secrecy and intelligence-gathering.","zh":"這個短語暗示秘密和情報收集。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":2},{"front":"the network of","meaning":"……的網絡","examples":[{"en":"The network of embassies helped gather information from abroad.","zh":"大使館網絡幫助收集來自外國的資訊。"},{"en":"The network of something means a connected group of people, places, or organisations.","zh":"network of something 指相互連接的一組人、地方或機構。"},{"en":"A network of clinics can provide healthcare across a rural area.","zh":"診所網絡可以為鄉村地區提供醫療服務。"},{"en":"A network of embassies helped Russia receive news from many countries.","zh":"大使館網絡幫助俄國從多個國家接收消息。"},{"en":"The phrase stresses connection and coordination.","zh":"這個短語強調連接和協調。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":2},{"front":"Imperial Foreign Office","meaning":"帝國外交部","examples":[{"en":"The Imperial Foreign Office maintained embassies and representations abroad.","zh":"帝國外交部維持駐外大使館和代表處。"},{"en":"The Imperial Foreign Office was a government body responsible for foreign relations in the empire.","zh":"Imperial Foreign Office 指帝國中負責外交關係的政府機構。"},{"en":"A foreign office manages communication with other countries and diplomatic representatives.","zh":"外交部管理與其他國家和外交代表的溝通。"},{"en":"If the Imperial Foreign Office received disease reports, it could pass them to central authorities.","zh":"如果帝國外交部收到疾病報告，它可以把消息傳給中央當局。"},{"en":"The phrase names an official institution, so it should be translated carefully.","zh":"這個短語是官方機構名稱，因此應謹慎翻譯。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":3},{"front":"embassies and representations abroad","meaning":"駐外大使館及代表處","examples":[{"en":"Embassies and representations abroad reported information to Russia.","zh":"駐外大使館及代表處向俄國報告資訊。"},{"en":"Embassies and representations abroad are official offices that represent a country in foreign places.","zh":"embassies and representations abroad 指在外國代表本國的官方辦事處。"},{"en":"Embassies abroad may report political news, trade conditions, and public health warnings.","zh":"駐外大使館可能報告政治消息、貿易情況和公共衛生警告。"},{"en":"These offices help governments understand events beyond their own borders.","zh":"這些辦事處幫助政府了解本國邊境以外的事件。"},{"en":"The phrase refers to diplomatic presence in other countries.","zh":"這個短語指在其他國家的外交存在。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":3},{"front":"customs offices","meaning":"海關辦事處","examples":[{"en":"Customs offices helped collect information at the border.","zh":"海關辦事處幫助在邊境收集資訊。"},{"en":"Customs offices are official places where goods and travellers are checked when entering or leaving a country.","zh":"customs offices 指人員和貨物進出國家時接受檢查的官方地點。"},{"en":"Customs offices may inspect luggage, documents, and imported products.","zh":"海關辦事處可能檢查行李、文件和進口產品。"},{"en":"During disease threats, customs offices can question travellers about outbreaks abroad.","zh":"在疾病威脅期間，海關辦事處可以盤問旅客有關外國疫情。"},{"en":"The phrase connects border control with official inspection.","zh":"這個短語把邊境管制與官方檢查連起來。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":3},{"front":"for instance","meaning":"例如","examples":[{"en":"For instance, customs officials questioned foreigners entering Russia.","zh":"例如，海關官員盤問進入俄國的外國人。"},{"en":"For instance means for example.","zh":"for instance 指例如。"},{"en":"A school may improve safety in several ways; for instance, it can add clearer signs.","zh":"學校可以用幾種方式改善安全；例如，它可以加設更清晰標誌。"},{"en":"Writers use for instance to make a general point easier to understand.","zh":"寫作者使用 for instance 令一般論點更容易理解。"},{"en":"The phrase introduces a specific example.","zh":"這個短語引入具體例子。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":3},{"front":"heads of customs offices","meaning":"海關辦事處負責人","examples":[{"en":"The heads of customs offices were instructed to question foreigners.","zh":"海關辦事處負責人被指示盤問外國人。"},{"en":"Heads of customs offices are the officials in charge of customs offices.","zh":"heads of customs offices 指負責海關辦事處的官員。"},{"en":"The head of an office may give instructions to staff and report to higher authorities.","zh":"辦事處負責人可能向員工發出指示並向上級匯報。"},{"en":"If heads of customs offices receive disease warnings, they can strengthen border checks.","zh":"如果海關辦事處負責人收到疾病警告，他們可以加強邊境檢查。"},{"en":"The phrase identifies local leaders within the customs system.","zh":"這個短語指出海關系統中的地方領導者。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":3},{"front":"be instructed to","meaning":"被指示去","examples":[{"en":"Officials were instructed to question foreigners about possible epidemics.","zh":"官員被指示去盤問外國人有關可能出現的疫症。"},{"en":"To be instructed to do something means to be officially told to do it.","zh":"be instructed to do something 指被正式告知要做某事。"},{"en":"Students may be instructed to write their names at the top of the answer sheet.","zh":"學生可能被指示在答題紙上方寫上姓名。"},{"en":"If border officers are instructed to ask health questions, travellers must answer them.","zh":"如果邊境官員被指示詢問健康問題，旅客必須回答。"},{"en":"The phrase suggests an order or formal direction.","zh":"這個短語暗示命令或正式指示。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":3},{"front":"question foreigners","meaning":"盤問外國人","examples":[{"en":"Customs officials questioned foreigners entering Russia.","zh":"海關官員盤問進入俄國的外國人。"},{"en":"To question foreigners means to ask people from other countries for information.","zh":"question foreigners 指向來自其他國家的人詢問資料。"},{"en":"Border officers may question foreigners about travel routes and documents.","zh":"邊境官員可能盤問外國人的旅行路線和文件。"},{"en":"During an epidemic, officials question foreigners to learn whether they came from affected areas.","zh":"在疫症期間，官員盤問外國人以了解他們是否來自受影響地區。"},{"en":"The phrase means formal questioning, not casual conversation.","zh":"這個短語指正式詢問，而不是普通聊天。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":3},{"front":"possible epidemics","meaning":"可能出現的疫症","examples":[{"en":"Foreigners were asked about possible epidemics in their countries.","zh":"外國人被問及其國家可能出現的疫症。"},{"en":"Possible epidemics are disease outbreaks that may exist or may soon develop.","zh":"possible epidemics 指可能存在或可能很快發展的疾病爆發。"},{"en":"Hospitals watch for possible epidemics when many patients show similar symptoms.","zh":"當許多病人出現相似症狀，醫院會留意可能出現的疫症。"},{"en":"Asking about possible epidemics helps authorities act before infection spreads locally.","zh":"詢問可能出現的疫症幫助當局在感染本地傳播前行動。"},{"en":"The phrase shows uncertainty but also caution.","zh":"這個短語顯示不確定性，也顯示謹慎。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":3},{"front":"respective countries","meaning":"各自的國家","examples":[{"en":"Foreigners were questioned about epidemics in their respective countries.","zh":"外國人被盤問有關其各自國家的疫症。"},{"en":"Respective countries means each person’s own country in a group being discussed.","zh":"respective countries 指被討論群體中每個人自己的國家。"},{"en":"Students from Japan, Korea, and Italy talked about schools in their respective countries.","zh":"來自日本、韓國和意大利的學生談論各自國家的學校。"},{"en":"If travellers report conditions in their respective countries, officials can compare risks.","zh":"如果旅客報告各自國家的情況，官員可以比較風險。"},{"en":"The phrase links each person or group to its own country.","zh":"這個短語把每個人或群體與其自己的國家連起來。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":3},{"front":"news of an outbreak","meaning":"疫症爆發的消息","examples":[{"en":"If news of an outbreak came from abroad, Russia suspended relations.","zh":"如果疫症爆發的消息來自外國，俄國會暫停關係。"},{"en":"News of an outbreak means information that a disease has begun spreading in a place.","zh":"news of an outbreak 指某地疾病已開始傳播的消息。"},{"en":"News of an outbreak can make schools prepare hygiene rules and health notices.","zh":"疫症爆發的消息可以令學校準備衛生規則和健康告示。"},{"en":"If news of an outbreak is reliable, governments may restrict travel quickly.","zh":"如果疫症爆發的消息可靠，政府可能迅速限制旅行。"},{"en":"The phrase refers to reported disease information, not the outbreak itself.","zh":"這個短語指被報告的疾病資訊，而不是爆發本身。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":3},{"front":"come from abroad","meaning":"來自外國","examples":[{"en":"News of an outbreak could come from abroad.","zh":"疫症爆發的消息可能來自外國。"},{"en":"To come from abroad means to arrive or originate from another country.","zh":"come from abroad 指來自或源於另一個國家。"},{"en":"Imported food comes from abroad when it is produced outside the country.","zh":"進口食物在本國以外生產時，就是來自外國。"},{"en":"Health warnings from abroad can affect local border policy.","zh":"來自外國的健康警告可以影響本地邊境政策。"},{"en":"The phrase focuses on foreign origin.","zh":"這個短語重點是外國來源。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":3},{"front":"relations with","meaning":"與……的關係","examples":[{"en":"Relations with the affected country were suspended.","zh":"與受影響國家的關係被暫停。"},{"en":"Relations with a country means official, trade, or diplomatic connections with it.","zh":"relations with a country 指與該國的官方、貿易或外交聯繫。"},{"en":"A country may improve relations with its neighbours through trade agreements.","zh":"一個國家可能透過貿易協議改善與鄰國的關係。"},{"en":"If disease spreads abroad, relations with affected areas may be temporarily limited.","zh":"如果疾病在外國蔓延，與受影響地區的關係可能暫時受限。"},{"en":"The phrase describes connection between states or groups.","zh":"這個短語描述國家或群體之間的聯繫。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":4},{"front":"the affected country","meaning":"受影響國家","examples":[{"en":"Russia suspended relations with the affected country.","zh":"俄國暫停與受影響國家的關係。"},{"en":"The affected country is the country influenced or harmed by the problem being discussed.","zh":"affected country 指受正在討論的問題影響或傷害的國家。"},{"en":"If floods damage roads, the affected country may ask for international help.","zh":"如果洪水破壞道路，受影響國家可能尋求國際援助。"},{"en":"When a country is affected by plague, other states may restrict contact with it.","zh":"當一個國家受鼠疫影響，其他國家可能限制與它接觸。"},{"en":"The phrase identifies the place directly impacted by the event.","zh":"這個短語指出直接受事件影響的地方。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":4},{"front":"be suspended","meaning":"被暫停","examples":[{"en":"Relations with affected countries were suspended.","zh":"與受影響國家的關係被暫停。"},{"en":"To be suspended means to be officially stopped for a period of time.","zh":"be suspended 指被正式停止一段時間。"},{"en":"Classes may be suspended during a severe storm.","zh":"在嚴重暴風期間，課堂可能被暫停。"},{"en":"Trade can be suspended when authorities fear disease may enter through goods or travellers.","zh":"當當局擔心疾病可能透過貨物或旅客進入，貿易可以被暫停。"},{"en":"The phrase usually suggests a temporary stop, not always a permanent end.","zh":"這個短語通常暗示暫時停止，不一定是永久結束。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":4},{"front":"foreign vessels","meaning":"外國船隻","examples":[{"en":"Foreign vessels were not allowed to dock in Russian ports.","zh":"外國船隻不准停靠俄國港口。"},{"en":"Foreign vessels are ships from other countries.","zh":"foreign vessels 指來自其他國家的船隻。"},{"en":"A port may inspect foreign vessels before allowing goods to be unloaded.","zh":"港口可能在准許卸貨前檢查外國船隻。"},{"en":"If foreign vessels come from infected areas, authorities may refuse entry.","zh":"如果外國船隻來自受感染地區，當局可能拒絕入境。"},{"en":"The phrase refers to ships, not aircraft or land vehicles.","zh":"這個短語指船隻，而不是飛機或陸上車輛。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":4},{"front":"be allowed to dock","meaning":"獲准停靠","examples":[{"en":"Foreign vessels were not allowed to dock if epidemics were suspected.","zh":"如果懷疑有疫症，外國船隻不獲准停靠。"},{"en":"To be allowed to dock means to receive permission for a ship to stop at a port.","zh":"be allowed to dock 指船隻獲准停靠港口。"},{"en":"A cargo ship may be allowed to dock after health and customs checks.","zh":"貨船可能在健康和海關檢查後獲准停靠。"},{"en":"If a ship is not allowed to dock, people and goods cannot enter through that port.","zh":"如果船隻不獲准停靠，人員和貨物就不能透過該港口進入。"},{"en":"The phrase is used for ships arriving at ports.","zh":"這個短語用於船隻抵達港口。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":4},{"front":"Russian ports","meaning":"俄國港口","examples":[{"en":"Ships from affected countries could not dock in Russian ports.","zh":"來自受影響國家的船隻不能停靠俄國港口。"},{"en":"Russian ports are harbour areas in Russia where ships load, unload, or stop.","zh":"Russian ports 指俄國船隻裝卸貨物或停靠的港口地區。"},{"en":"Russian ports handled trade goods, travellers, and information from abroad.","zh":"俄國港口處理來自外國的貿易貨物、旅客和資訊。"},{"en":"Closing Russian ports to infected countries could reduce the risk of imported disease.","zh":"對受感染國家關閉俄國港口，可以降低疾病輸入風險。"},{"en":"The phrase refers to maritime entry points into Russia.","zh":"這個短語指進入俄國的海上入口。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":4},{"front":"credible information","meaning":"可靠資料","examples":[{"en":"Restrictions were imposed when there was credible information about epidemics.","zh":"當有關疫症的可靠資料出現時，限制被實施。"},{"en":"Credible information is information that seems reliable and believable.","zh":"credible information 指看來可靠並可信的資訊。"},{"en":"A school should act on credible information about a safety threat.","zh":"學校應根據有關安全威脅的可靠資料採取行動。"},{"en":"If officials receive credible information about disease, they can justify stronger controls.","zh":"如果官員收到有關疾病的可靠資料，他們可以合理化更嚴格管制。"},{"en":"The phrase contrasts trustworthy reports with rumours.","zh":"這個短語把可信報告與謠言作對比。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":4},{"front":"the existence of epidemics","meaning":"疫症的存在","examples":[{"en":"Russia acted when there was information about the existence of epidemics.","zh":"當有關疫症存在的資料出現時，俄國便採取行動。"},{"en":"The existence of epidemics means the fact that disease outbreaks are present.","zh":"existence of epidemics 指疾病爆發存在這一事實。"},{"en":"Evidence of the existence of an epidemic may include reports of many similar deaths.","zh":"疫症存在的證據可能包括許多相似死亡個案報告。"},{"en":"Once authorities know about the existence of epidemics, they may impose quarantine.","zh":"一旦當局知道疫症的存在，就可能實施檢疫。"},{"en":"The phrase focuses on whether outbreaks are actually happening.","zh":"這個短語重點是爆發是否真的正在發生。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":4},{"front":"depart from","meaning":"從……出發","examples":[{"en":"The vessels had departed from countries affected by epidemics.","zh":"這些船隻從受疫症影響的國家出發。"},{"en":"To depart from a place means to leave that place, especially on a journey.","zh":"depart from a place 指離開某地，尤其是開始旅程。"},{"en":"A train may depart from the station at seven in the morning.","zh":"火車可能早上七點從車站出發。"},{"en":"If ships depart from infected ports, the receiving country may require quarantine.","zh":"如果船隻從受感染港口出發，接收國可能要求檢疫。"},{"en":"The phrase focuses on the starting point of travel.","zh":"這個短語重點是旅程起點。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":4},{"front":"undergo quarantine","meaning":"接受檢疫","examples":[{"en":"Foreigners entering Russia from affected countries had to undergo quarantine.","zh":"從受影響國家進入俄國的外國人必須接受檢疫。"},{"en":"To undergo quarantine means to stay separated for a period to make sure one is not carrying disease.","zh":"undergo quarantine 指隔離一段時間，以確保自己沒有攜帶疾病。"},{"en":"Travellers may undergo quarantine after exposure to a serious infection.","zh":"旅客接觸嚴重感染後可能需要接受檢疫。"},{"en":"Quarantine can prevent illness from spreading before symptoms appear.","zh":"檢疫可以在症狀出現前防止疾病傳播。"},{"en":"The phrase refers to a controlled health isolation process.","zh":"這個短語指受控的健康隔離程序。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":4},{"front":"after receiving news about","meaning":"在收到關於……的消息後","examples":[{"en":"Russia acted after receiving news about a plague epidemic in England.","zh":"俄國在收到關於英格蘭鼠疫疫情的消息後採取行動。"},{"en":"After receiving news about something means once information about it has arrived.","zh":"after receiving news about something 指在相關資訊傳來之後。"},{"en":"A school may close early after receiving news about dangerous weather.","zh":"學校可能在收到危險天氣消息後提早關閉。"},{"en":"Governments may tighten border checks after receiving news about disease abroad.","zh":"政府可能在收到外國疾病消息後收緊邊境檢查。"},{"en":"The phrase links information arrival with later action.","zh":"這個短語把資訊到達與後續行動連起來。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":4},{"front":"plague epidemic","meaning":"鼠疫疫情","examples":[{"en":"A plague epidemic in England led Russia to suspend trade relations.","zh":"英格蘭的鼠疫疫情令俄國暫停貿易關係。"},{"en":"A plague epidemic is a widespread outbreak of plague in a population.","zh":"plague epidemic 指鼠疫在人群中大規模爆發。"},{"en":"A city facing a plague epidemic may close markets and isolate patients.","zh":"面對鼠疫疫情的城市可能關閉市場並隔離病人。"},{"en":"News of a plague epidemic can lead neighbouring countries to restrict ships and travellers.","zh":"鼠疫疫情的消息可以令鄰近國家限制船隻和旅客。"},{"en":"The phrase combines a specific disease with large-scale spread.","zh":"這個短語結合特定疾病與大規模傳播。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":5},{"front":"write a letter to","meaning":"寫信給","examples":[{"en":"Tsar Alexei wrote a letter to King Charles II.","zh":"沙皇 Alexei 寫信給 Charles II 國王。"},{"en":"To write a letter to someone means to send them a written message.","zh":"write a letter to someone 指向某人發送書面訊息。"},{"en":"A student may write a letter to the principal to request a change in school rules.","zh":"學生可能寫信給校長，要求改變校規。"},{"en":"Leaders write letters to other leaders when formal communication is needed.","zh":"當需要正式溝通時，領袖會寫信給其他領袖。"},{"en":"The phrase describes direct written communication.","zh":"這個短語描述直接書面溝通。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":5},{"front":"announce the cessation of","meaning":"宣布中止……","examples":[{"en":"The tsar announced the cessation of trade relations with England.","zh":"沙皇宣布中止與英格蘭的貿易關係。"},{"en":"To announce the cessation of something means to officially say that it will stop.","zh":"announce the cessation of something 指正式宣布某事將停止。"},{"en":"A company may announce the cessation of a service if too few people use it.","zh":"如果太少人使用某服務，公司可能宣布中止該服務。"},{"en":"When a government announces the cessation of trade, merchants must stop business with that country.","zh":"當政府宣布中止貿易，商人必須停止與該國做生意。"},{"en":"The phrase is formal and refers to an official ending.","zh":"這個短語較正式，指官方終止。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":5},{"front":"trade relations with","meaning":"與……的貿易關係","examples":[{"en":"Russia suspended trade relations with England and other foreign states.","zh":"俄國暫停與英格蘭和其他外國國家的貿易關係。"},{"en":"Trade relations with a country are business and exchange connections with that country.","zh":"trade relations with a country 指與該國的商業和交換聯繫。"},{"en":"Strong trade relations with neighbours can lower prices and increase choices.","zh":"與鄰國穩固的貿易關係可以降低價格並增加選擇。"},{"en":"During an epidemic, trade relations with affected states may be suspended to reduce risk.","zh":"在疫症期間，與受影響國家的貿易關係可能被暫停，以降低風險。"},{"en":"The phrase refers to economic links between countries.","zh":"這個短語指國家之間的經濟聯繫。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":5},{"front":"foreign states","meaning":"外國國家","examples":[{"en":"Russia suspended trade relations with England and other foreign states.","zh":"俄國暫停與英格蘭和其他外國國家的貿易關係。"},{"en":"Foreign states are other countries, especially when discussed in official or diplomatic language.","zh":"foreign states 指其他國家，尤其在官方或外交語言中。"},{"en":"Governments sign agreements with foreign states on trade, security, and travel.","zh":"政府與外國國家簽訂貿易、安全和旅行協議。"},{"en":"If foreign states report serious disease, neighbours may strengthen border controls.","zh":"如果外國國家報告嚴重疾病，鄰國可能加強邊境管制。"},{"en":"The phrase is formal and refers to countries outside one’s own.","zh":"這個短語較正式，指本國以外的國家。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":5},{"front":"protective measures","meaning":"保護措施","examples":[{"en":"The protective measures appeared to have been effective.","zh":"這些保護措施看來已經奏效。"},{"en":"Protective measures are actions taken to keep people, places, or systems safe.","zh":"protective measures 指為保護人、地方或系統安全而採取的行動。"},{"en":"Wearing masks, washing hands, and isolating patients can be protective measures during an outbreak.","zh":"在疫情期間，戴口罩、洗手和隔離病人都可以是保護措施。"},{"en":"Protective measures are useful when they reduce risk before harm spreads widely.","zh":"當保護措施在傷害廣泛蔓延前降低風險時，它們就很有用。"},{"en":"The phrase focuses on prevention and safety.","zh":"這個短語重點是預防和安全。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":5},{"front":"appear to have been effective","meaning":"看來已經奏效","examples":[{"en":"The protective measures appeared to have been effective.","zh":"這些保護措施看來已經奏效。"},{"en":"To appear to have been effective means to seem to have worked, based on the available result.","zh":"appear to have been effective 指根據現有結果看起來已經有效。"},{"en":"The new study plan appeared to have been effective when students’ scores improved.","zh":"當學生分數提高，新學習計劃看來已經奏效。"},{"en":"If no plague cases were recorded, the measures may appear to have been effective.","zh":"如果沒有記錄到鼠疫個案，措施可能看來已經奏效。"},{"en":"The phrase leaves room for uncertainty because it says appear.","zh":"這個短語因為使用 appear 而保留不確定性。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":5},{"front":"record any cases of","meaning":"記錄任何……個案","examples":[{"en":"Russia did not record any cases of plague that year.","zh":"俄國那一年沒有記錄任何鼠疫個案。"},{"en":"To record any cases of a disease means to officially note that people had it.","zh":"record any cases of a disease 指正式記下有人患上該疾病。"},{"en":"A school may record cases of flu to decide whether extra cleaning is needed.","zh":"學校可能記錄流感個案，以決定是否需要額外清潔。"},{"en":"If a city records no cases of infection, officials may believe controls worked.","zh":"如果城市沒有記錄感染個案，官員可能認為管制奏效。"},{"en":"The phrase refers to official reporting, not private rumours.","zh":"這個短語指官方記錄，而不是私人傳聞。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":5},{"front":"during that year","meaning":"在那一年期間","examples":[{"en":"Russia recorded no plague cases during that year.","zh":"俄國在那一年期間沒有記錄鼠疫個案。"},{"en":"During that year means within the period of that particular year.","zh":"during that year 指在該特定年份之內。"},{"en":"During that year, the school introduced new rules and built a library.","zh":"在那一年期間，學校引入新規則並建造圖書館。"},{"en":"If no cases appeared during that year, the immediate danger may have been avoided.","zh":"如果在那一年期間沒有個案出現，即時危險可能已被避開。"},{"en":"The phrase limits the statement to one specific year.","zh":"這個短語把陳述限制在某一年。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":5},{"front":"in the next three decades","meaning":"在隨後三十年","examples":[{"en":"No further plague cases were recorded in the next three decades.","zh":"在隨後三十年，沒有再記錄鼠疫個案。"},{"en":"In the next three decades means during the following thirty years.","zh":"in the next three decades 指在接下來三十年之內。"},{"en":"A city may grow rapidly in the next three decades if transport improves.","zh":"如果交通改善，一個城市可能在隨後三十年迅速增長。"},{"en":"If no outbreak occurs in the next three decades, a policy may seem successful.","zh":"如果在隨後三十年沒有爆發，政策可能看起來成功。"},{"en":"The phrase gives a long future or following time period.","zh":"這個短語提供較長的未來或後續時間段。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":5},{"front":"it was not until … that","meaning":"直到……才……","examples":[{"en":"It was not until 1692 that another plague outbreak was recorded.","zh":"直到1692年，才記錄到另一場鼠疫爆發。"},{"en":"It was not until … that means something happened only at that later time, not before.","zh":"it was not until … that 指某事直到較後時間才發生，而不是之前。"},{"en":"It was not until midnight that the students finished the group project.","zh":"直到午夜，學生才完成小組項目。"},{"en":"It was not until symptoms appeared that officials realised the disease had entered the city.","zh":"直到症狀出現，官員才意識到疾病已進入城市。"},{"en":"The structure emphasises delay.","zh":"這個句式強調延遲。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":5},{"front":"plague outbreak","meaning":"鼠疫爆發","examples":[{"en":"Another plague outbreak was recorded in Astrakhan in 1692.","zh":"1692年，阿斯特拉罕記錄到另一場鼠疫爆發。"},{"en":"A plague outbreak is a sudden spread of plague in a place.","zh":"plague outbreak 指鼠疫在某地突然傳播。"},{"en":"A plague outbreak in a port city could affect trade, travel, and public health.","zh":"港口城市的鼠疫爆發可能影響貿易、旅行和公共衛生。"},{"en":"When a plague outbreak is recorded, authorities may isolate patients and close routes.","zh":"當記錄到鼠疫爆發，當局可能隔離病人和封閉路線。"},{"en":"The phrase refers to an episode of disease spread.","zh":"這個短語指一次疾病傳播事件。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":6},{"front":"the Russian province of","meaning":"俄國的……省","examples":[{"en":"The outbreak occurred in the Russian province of Astrakhan.","zh":"疫情發生在俄國的阿斯特拉罕省。"},{"en":"The Russian province of a place means a province within Russia with that name.","zh":"the Russian province of a place 指俄國境內以該名稱命名的省份。"},{"en":"A report may describe events in the Russian province of a border region.","zh":"報告可能描述俄國某邊境地區省份中的事件。"},{"en":"Naming the province helps readers know where the outbreak happened.","zh":"說出省份名稱幫助讀者知道疫情發生地點。"},{"en":"The phrase gives administrative location.","zh":"這個短語提供行政地點。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":6},{"front":"Astrakhan","meaning":"阿斯特拉罕","examples":[{"en":"A serious plague outbreak was recorded in Astrakhan.","zh":"阿斯特拉罕記錄到一場嚴重鼠疫爆發。"},{"en":"Astrakhan is a place name referring to a Russian region or city in this historical context.","zh":"Astrakhan 在這個歷史語境中是一個指俄國地區或城市的地名。"},{"en":"When a passage names Astrakhan, students should treat it as a specific location.","zh":"當文章提到 Astrakhan，學生應把它視為特定地點。"},{"en":"An outbreak in Astrakhan mattered because it affected a real province, not an unnamed area.","zh":"阿斯特拉罕的疫情重要，因為它影響一個真實省份，而不是未命名地區。"},{"en":"The word is a proper noun and should not be translated freely.","zh":"這個詞是專有名詞，不應自由翻譯。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":6},{"front":"continue for","meaning":"持續了","examples":[{"en":"The epidemic continued for five months.","zh":"疫情持續了五個月。"},{"en":"To continue for a period means to last for that length of time.","zh":"continue for a period 指持續某段時間。"},{"en":"The rain continued for three days and flooded the streets.","zh":"大雨持續了三天，令街道水浸。"},{"en":"If an epidemic continues for months, hospitals and families may face severe pressure.","zh":"如果疫情持續數月，醫院和家庭可能面對嚴重壓力。"},{"en":"The phrase focuses on duration.","zh":"這個短語重點是持續時間。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":6},{"front":"city’s population","meaning":"城市人口","examples":[{"en":"The epidemic killed about 65 percent of the city’s population.","zh":"疫情奪去了該城市約65%人口的生命。"},{"en":"A city’s population is the number of people living in that city.","zh":"city’s population 指居住在該城市的人數。"},{"en":"A city’s population can grow when jobs and housing attract migrants.","zh":"當工作和住房吸引移民，城市人口可以增長。"},{"en":"If a disease kills a large share of a city’s population, the whole community is changed.","zh":"如果疾病殺死城市人口的一大部分，整個社區都會改變。"},{"en":"The phrase refers to people living in a city, not buildings or land.","zh":"這個短語指居住在城市的人，而不是建築或土地。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":6},{"front":"by the end of","meaning":"到……結束時","examples":[{"en":"By the end of the seventeenth century, preventive measures were widely introduced.","zh":"到十七世紀結束時，預防措施已被廣泛引入。"},{"en":"By the end of a period means before or at the time that period finishes.","zh":"by the end of a period 指在某段時期結束前或結束時。"},{"en":"By the end of the school year, students should understand the main grammar rules.","zh":"到學年結束時，學生應理解主要文法規則。"},{"en":"If a policy spreads by the end of a century, it has become established before that century closes.","zh":"如果政策到某世紀結束時已傳開，它就是在該世紀結束前確立。"},{"en":"The phrase marks a deadline or endpoint.","zh":"這個短語標示期限或終點。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":6},{"front":"preventive measures","meaning":"預防措施","examples":[{"en":"Preventive measures were widely introduced in Russia.","zh":"預防措施在俄國被廣泛引入。"},{"en":"Preventive measures are actions taken before or during a problem to stop it from getting worse.","zh":"preventive measures 指在問題發生前或期間採取、以阻止其惡化的行動。"},{"en":"Vaccination, hand washing, and clean water can be preventive measures against disease.","zh":"疫苗接種、洗手和清潔食水都可以是預防疾病的措施。"},{"en":"Preventive measures work best when they begin before a crisis spreads widely.","zh":"預防措施在危機廣泛蔓延前開始時效果最好。"},{"en":"The phrase focuses on avoiding harm rather than treating damage after it happens.","zh":"這個短語重點是避免傷害，而不是事後治療損害。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":6},{"front":"be widely introduced","meaning":"被廣泛引入","examples":[{"en":"Preventive measures had been widely introduced by the end of the century.","zh":"到該世紀結束時，預防措施已被廣泛引入。"},{"en":"To be widely introduced means to be brought into use in many places or among many people.","zh":"be widely introduced 指在許多地方或許多人之中被帶入使用。"},{"en":"Online payment was widely introduced in shops after customers began using phones more often.","zh":"當顧客更常使用手機，網上付款在商店中被廣泛引入。"},{"en":"If quarantine rules are widely introduced, more towns follow the same health practice.","zh":"如果檢疫規則被廣泛引入，更多城鎮會遵循相同衛生做法。"},{"en":"The phrase suggests broad adoption, not a single local experiment.","zh":"這個短語暗示廣泛採用，而不是單一地方實驗。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":6},{"front":"isolation of persons","meaning":"隔離人士","examples":[{"en":"The isolation of persons ill with plague was introduced.","zh":"患上鼠疫人士的隔離被引入。"},{"en":"Isolation of persons means separating people from others to prevent contact or spread.","zh":"isolation of persons 指把人與其他人分開，以防接觸或傳播。"},{"en":"Hospitals may use isolation of persons with serious infections to protect other patients.","zh":"醫院可能隔離患嚴重感染的人，以保護其他病人。"},{"en":"Isolation can reduce disease transmission when sick people would otherwise meet many others.","zh":"當病人原本會接觸許多人時，隔離可以減少疾病傳播。"},{"en":"The phrase focuses on separating people for health or safety reasons.","zh":"這個短語重點是為健康或安全原因分隔人群。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":6},{"front":"ill with plague","meaning":"患上鼠疫","examples":[{"en":"Persons ill with plague were isolated.","zh":"患上鼠疫的人被隔離。"},{"en":"Ill with plague means sick because of plague.","zh":"ill with plague 指因鼠疫而生病。"},{"en":"A patient ill with a dangerous infection may need separate care.","zh":"患上危險感染的病人可能需要分開照顧。"},{"en":"If people ill with plague are not isolated, the disease may spread to families and neighbours.","zh":"如果患上鼠疫的人沒有被隔離，疾病可能傳播給家人和鄰居。"},{"en":"The phrase describes a medical condition, not a general feeling of tiredness.","zh":"這個短語描述醫療狀況，而不是一般疲倦感。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":6},{"front":"imposition of quarantines","meaning":"實施檢疫","examples":[{"en":"The imposition of quarantines became one of the preventive measures.","zh":"實施檢疫成為預防措施之一。"},{"en":"Imposition of quarantines means officially requiring people or places to be isolated for health reasons.","zh":"imposition of quarantines 指基於健康原因正式要求人或地方隔離。"},{"en":"The imposition of quarantines can stop travellers from spreading disease immediately after arrival.","zh":"實施檢疫可以阻止旅客在抵達後立即傳播疾病。"},{"en":"If quarantine is imposed too late, an infection may already have spread.","zh":"如果檢疫太遲實施，感染可能已經傳播。"},{"en":"The phrase is formal and focuses on official enforcement.","zh":"這個短語較正式，重點是官方執行。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":6},{"front":"distribution of notices","meaning":"分發告示","examples":[{"en":"The distribution of public health notices helped inform people.","zh":"分發公共衛生告示幫助通知人們。"},{"en":"Distribution of notices means giving written messages to many people or places.","zh":"distribution of notices 指向許多人或地方派發書面訊息。"},{"en":"A school may use distribution of notices to tell parents about a flu outbreak.","zh":"學校可能透過分發告示告知家長有流感爆發。"},{"en":"When notices are distributed quickly, people can learn what actions to take.","zh":"當告示迅速分發，人們可以知道該採取甚麼行動。"},{"en":"The phrase focuses on spreading official written information.","zh":"這個短語重點是傳播官方書面資訊。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":7},{"front":"explanatory public health notices","meaning":"公共衛生說明告示","examples":[{"en":"Explanatory public health notices were distributed during plague outbreaks.","zh":"鼠疫爆發期間，公共衛生說明告示被分發。"},{"en":"Explanatory public health notices are written messages that explain health risks and instructions.","zh":"explanatory public health notices 指解釋健康風險和指示的書面訊息。"},{"en":"A notice explaining symptoms and quarantine rules can help people understand what to do.","zh":"解釋症狀和檢疫規則的告示可以幫助人們知道該怎樣做。"},{"en":"During outbreaks, clear notices reduce confusion and panic.","zh":"在疫情期間，清晰告示可以減少混亂和恐慌。"},{"en":"The phrase describes public information designed to teach, not just warn.","zh":"這個短語描述旨在教育公眾的資訊，而不只是警告。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":7},{"front":"public health notices","meaning":"公共衛生告示","examples":[{"en":"Public health notices explained information about plague outbreaks.","zh":"公共衛生告示解釋有關鼠疫爆發的資訊。"},{"en":"Public health notices are official messages that give health advice or warnings to the public.","zh":"public health notices 指向公眾提供健康建議或警告的官方訊息。"},{"en":"Public health notices may tell people to wash hands, avoid crowds, or report symptoms.","zh":"公共衛生告示可能告訴人們洗手、避免人群或報告症狀。"},{"en":"If public health notices are clear, people are more likely to follow safety rules.","zh":"如果公共衛生告示清晰，人們更可能遵守安全規則。"},{"en":"The phrase connects government communication with community health.","zh":"這個短語把政府溝通與社區健康連起來。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":7},{"front":"during the eighteenth century","meaning":"在十八世紀期間","examples":[{"en":"During the eighteenth century, plague appeared in Russia several times.","zh":"在十八世紀期間，鼠疫在俄國出現數次。"},{"en":"During the eighteenth century means in the years from 1701 to 1800.","zh":"during the eighteenth century 指1701年至1800年間。"},{"en":"During the eighteenth century, many European states changed their armies and governments.","zh":"在十八世紀期間，許多歐洲國家改變其軍隊和政府。"},{"en":"If a disease appeared several times during a century, it remained a recurring threat.","zh":"如果疾病在一個世紀中數次出現，它仍是一種反覆威脅。"},{"en":"The phrase gives a historical time period.","zh":"這個短語提供歷史時期。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":7},{"front":"on the same scale as","meaning":"規模與……相同","examples":[{"en":"No later outbreak was on the same scale as earlier epidemics.","zh":"後來的爆發沒有一次規模與早期疫情相同。"},{"en":"On the same scale as means similar in size, seriousness, or extent.","zh":"on the same scale as 指在大小、嚴重程度或範圍上相似。"},{"en":"A small school event is not on the same scale as a city-wide festival.","zh":"小型學校活動的規模與全市節日不同。"},{"en":"If later outbreaks were not on the same scale as earlier ones, the damage may have been smaller.","zh":"如果後來的爆發規模不及早期疫情，損害可能較小。"},{"en":"The phrase compares size or severity.","zh":"這個短語比較規模或嚴重程度。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":7},{"front":"appear in","meaning":"在……出現","examples":[{"en":"Plague appeared in Russia several times.","zh":"鼠疫在俄國出現數次。"},{"en":"To appear in a place means to show up or be found there.","zh":"appear in a place 指在某地出現或被發現。"},{"en":"New cafés may appear in a neighbourhood when more young people move in.","zh":"當更多年輕人搬入社區，新咖啡店可能在那裡出現。"},{"en":"When a disease appears in a region, authorities must decide whether it is spreading.","zh":"當疾病在某地區出現，當局必須判斷它是否正在傳播。"},{"en":"The phrase describes arrival or occurrence.","zh":"這個短語描述出現或發生。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":7},{"front":"ravage Istanbul","meaning":"重創伊斯坦堡","examples":[{"en":"A plague outbreak had ravaged Istanbul before spreading to Russia.","zh":"鼠疫爆發在傳到俄國前已重創伊斯坦堡。"},{"en":"To ravage a place means to badly damage it, often through war, disease, or disaster.","zh":"ravage a place 指透過戰爭、疾病或災難嚴重破壞某地。"},{"en":"A flood can ravage a village by destroying homes and roads.","zh":"洪水可以摧毀房屋和道路，重創村莊。"},{"en":"If plague ravaged Istanbul, many people may have died and daily life may have collapsed.","zh":"如果鼠疫重創伊斯坦堡，許多人可能死亡，日常生活可能崩潰。"},{"en":"The phrase is strong and suggests severe destruction.","zh":"這個短語語氣很強，暗示嚴重破壞。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":7},{"front":"spread to","meaning":"傳播到","examples":[{"en":"The plague spread to the Podolsk and Kiev provinces.","zh":"鼠疫傳播到波多爾斯克和基輔省。"},{"en":"To spread to a place means to move or extend into that place.","zh":"spread to a place 指移動或延伸到某地。"},{"en":"A cold can spread to a whole family if everyone shares cups and towels.","zh":"如果每個人共用杯子和毛巾，感冒可以傳播到整個家庭。"},{"en":"If disease spreads to new provinces, control becomes harder.","zh":"如果疾病傳播到新省份，控制會變得更困難。"},{"en":"The phrase describes movement from one area to another.","zh":"這個短語描述由一個地區移到另一個地區。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":7},{"front":"after defeating","meaning":"在擊敗……之後","examples":[{"en":"After defeating the Swedes, Peter I sent troops to Poland.","zh":"在擊敗瑞典人之後，彼得一世派軍隊到波蘭。"},{"en":"After defeating an enemy means after winning against that enemy.","zh":"after defeating an enemy 指在戰勝某敵人之後。"},{"en":"After defeating a rival team, a school basketball club may enter the final.","zh":"在擊敗對手球隊之後，學校籃球隊可能進入決賽。"},{"en":"A ruler may make new military plans after defeating one opponent.","zh":"統治者在擊敗一個對手之後，可能制定新的軍事計劃。"},{"en":"The phrase places one action after a victory.","zh":"這個短語把一項行動放在勝利之後。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":7},{"front":"the battle of Poltava","meaning":"波爾塔瓦戰役","examples":[{"en":"Peter I defeated the Swedes in the battle of Poltava.","zh":"彼得一世在波爾塔瓦戰役中擊敗瑞典人。"},{"en":"The battle of Poltava was a specific historical battle mentioned as the context for later events.","zh":"battle of Poltava 是一場特定歷史戰役，作為後續事件的背景。"},{"en":"In history writing, naming a battle helps readers understand when and why troops moved.","zh":"在歷史寫作中，說出戰役名稱幫助讀者理解軍隊何時和為何移動。"},{"en":"After the battle of Poltava, Russian military actions continued in nearby regions.","zh":"波爾塔瓦戰役後，俄國軍事行動在附近地區繼續。"},{"en":"The phrase is a proper noun and should be kept as a historical name.","zh":"這個短語是專有名詞，應保留為歷史名稱。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":7},{"front":"dispatch part of his army","meaning":"派遣部分軍隊","examples":[{"en":"Peter I dispatched part of his army to Poland.","zh":"彼得一世派遣部分軍隊到波蘭。"},{"en":"To dispatch part of an army means to send a portion of soldiers to another place for duty.","zh":"dispatch part of an army 指把一部分士兵派往另一地執行任務。"},{"en":"A commander may dispatch part of his army to protect a border town.","zh":"指揮官可能派遣部分軍隊保護邊境城鎮。"},{"en":"Dispatching troops to an infected area can expose soldiers to disease.","zh":"派兵到受感染地區可能令士兵接觸疾病。"},{"en":"The phrase is formal and military in tone.","zh":"這個短語較正式，帶軍事語氣。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":7},{"front":"plague had been raging","meaning":"鼠疫一直在肆虐","examples":[{"en":"Plague had been raging in Poland for two years.","zh":"鼠疫已在波蘭肆虐了兩年。"},{"en":"If plague had been raging, it had been spreading violently and causing serious harm for some time.","zh":"如果 plague had been raging，意思是鼠疫已經猛烈傳播並造成嚴重傷害一段時間。"},{"en":"A wildfire may rage for days if wind keeps pushing it through dry land.","zh":"如果風一直把火推過乾燥土地，山火可能肆虐數天。"},{"en":"When plague had been raging for years, troops entering the area faced high risk.","zh":"當鼠疫已肆虐多年，進入該地區的軍隊面對高風險。"},{"en":"The phrase suggests an uncontrolled and destructive situation.","zh":"這個短語暗示失控且具破壞性的情況。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":8},{"front":"despite preventive measures","meaning":"儘管有預防措施","examples":[{"en":"Despite preventive measures, the disease spread among Russian troops.","zh":"儘管有預防措施，疾病仍在俄國軍隊之間傳播。"},{"en":"Despite preventive measures means although actions had been taken to stop the problem.","zh":"despite preventive measures 指雖然已採取行動阻止問題。"},{"en":"Despite safety rules, accidents can still happen if people are tired or careless.","zh":"儘管有安全規則，如果人們疲倦或粗心，事故仍可能發生。"},{"en":"Disease may spread despite preventive measures when conditions are crowded and difficult.","zh":"當環境擠迫而艱難，疾病可能儘管有預防措施仍然傳播。"},{"en":"The phrase contrasts effort with an unwanted result.","zh":"這個短語把努力與不想要的結果作對比。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":8},{"front":"spread among","meaning":"在……之間傳播","examples":[{"en":"The disease spread among the Russian troops.","zh":"疾病在俄國軍隊之間傳播。"},{"en":"To spread among a group means to pass from person to person within that group.","zh":"spread among a group 指在該群體內由人傳人。"},{"en":"A rumour can spread among students before teachers know about it.","zh":"謠言可以在老師知道前已在學生之間傳播。"},{"en":"Disease spreads among soldiers easily when they live close together in camps.","zh":"當士兵在軍營中靠得很近生活，疾病容易在士兵之間傳播。"},{"en":"The phrase focuses on movement within a group.","zh":"這個短語重點是群體內部的傳播。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":8},{"front":"Russian troops","meaning":"俄國軍隊","examples":[{"en":"Plague spread among Russian troops in Poland.","zh":"鼠疫在波蘭的俄國軍隊之間傳播。"},{"en":"Russian troops are soldiers serving in the Russian army.","zh":"Russian troops 指在俄國軍隊服役的士兵。"},{"en":"Russian troops could carry disease if they moved from infected areas to new camps.","zh":"如果俄國軍隊從受感染地區移到新軍營，他們可能攜帶疾病。"},{"en":"When troops become sick, military campaigns can weaken quickly.","zh":"當軍隊生病，軍事行動可以迅速削弱。"},{"en":"The phrase refers to military forces, not ordinary Russian civilians.","zh":"這個短語指軍事力量，而不是普通俄國平民。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":8},{"front":"reach Riga","meaning":"傳到里加","examples":[{"en":"In 1710, the plague reached Riga.","zh":"1710年，鼠疫傳到里加。"},{"en":"To reach a place means to arrive there or spread there.","zh":"reach a place 指到達或傳播到某地。"},{"en":"A train may reach the city by noon if there are no delays.","zh":"如果沒有延誤，火車可能在中午前到達城市。"},{"en":"If plague reaches a port city, trade and military movement may become dangerous.","zh":"如果鼠疫傳到港口城市，貿易和軍事移動可能變得危險。"},{"en":"The phrase marks the arrival of something at a location.","zh":"這個短語標示某事物到達某地。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":8},{"front":"active until","meaning":"持續活躍至","examples":[{"en":"The plague was active in Riga until 1711.","zh":"鼠疫在里加持續活躍至1711年。"},{"en":"Active until a time means continuing to operate, spread, or have an effect until that time.","zh":"active until a time 指持續運作、傳播或產生影響直到某時間。"},{"en":"A storm warning may remain active until midnight.","zh":"暴風警告可能持續生效至午夜。"},{"en":"If disease is active until the next year, controls must continue longer than expected.","zh":"如果疾病持續活躍至下一年，管制就必須比預期更久。"},{"en":"The phrase gives the endpoint of an ongoing situation.","zh":"這個短語提供持續情況的終點。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":8},{"front":"claim lives","meaning":"奪去生命","examples":[{"en":"The plague claimed 60,000 lives in Riga.","zh":"鼠疫在里加奪去60,000條生命。"},{"en":"To claim lives means to cause people to die.","zh":"claim lives 指導致人死亡。"},{"en":"A serious earthquake can claim many lives if buildings collapse.","zh":"如果建築倒塌，嚴重地震可以奪去許多生命。"},{"en":"When disease claims thousands of lives, society may change its health policies.","zh":"當疾病奪去數千人生命，社會可能改變健康政策。"},{"en":"The phrase is formal and often used for disasters, wars, or epidemics.","zh":"這個短語較正式，常用於災難、戰爭或疫情。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":8},{"front":"during this period","meaning":"在此期間","examples":[{"en":"During this period, the Russians besieged Riga.","zh":"在此期間，俄國人圍攻里加。"},{"en":"During this period means in the time being discussed.","zh":"during this period 指在正在討論的這段時間內。"},{"en":"During this period, students had online lessons because the school was closed.","zh":"在此期間，由於學校關閉，學生上網課。"},{"en":"If war and disease happen during the same period, each problem can worsen the other.","zh":"如果戰爭和疾病在同一時期發生，兩個問題可能互相惡化。"},{"en":"The phrase links an event to a specific time span.","zh":"這個短語把事件與特定時間段連起來。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":8},{"front":"besiege Riga","meaning":"圍攻里加","examples":[{"en":"The Russians besieged Riga during the plague outbreak.","zh":"俄國人在鼠疫爆發期間圍攻里加。"},{"en":"To besiege a city means to surround it with military forces to force surrender.","zh":"besiege a city 指用軍隊包圍城市，以迫使其投降。"},{"en":"An army may besiege a fortress by blocking food, water, and escape routes.","zh":"軍隊可能透過阻斷食物、水和逃生路線圍攻堡壘。"},{"en":"If soldiers besiege a city during an epidemic, disease can spread among both armies and civilians.","zh":"如果士兵在疫情期間圍攻城市，疾病可能在軍隊和平民之間傳播。"},{"en":"The phrase is military and describes surrounding a place in war.","zh":"這個短語屬軍事用語，描述戰爭中包圍某地。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":8},{"front":"surrender the city","meaning":"交出城市","examples":[{"en":"The Swedes surrendered the city in 1710.","zh":"瑞典人在1710年交出該城市。"},{"en":"To surrender the city means to give control of the city to the enemy.","zh":"surrender the city 指把城市控制權交給敵人。"},{"en":"A defending army may surrender a city when food and supplies run out.","zh":"當食物和補給耗盡，守軍可能交出城市。"},{"en":"Once a city is surrendered, the winning army usually takes control of its gates and buildings.","zh":"一旦城市被交出，勝利軍隊通常接管城門和建築。"},{"en":"The phrase describes defeat and transfer of control.","zh":"這個短語描述戰敗和控制權轉移。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":8},{"front":"lose soldiers to plague","meaning":"因鼠疫失去士兵","examples":[{"en":"The Russian army lost 9,800 soldiers to plague.","zh":"俄國軍隊因鼠疫失去9,800名士兵。"},{"en":"To lose soldiers to plague means that soldiers died because of plague.","zh":"lose soldiers to plague 指士兵因鼠疫死亡。"},{"en":"An army can lose more soldiers to disease than to fighting if conditions are poor.","zh":"如果環境惡劣，軍隊因疾病失去的士兵可能比戰鬥更多。"},{"en":"Losing soldiers to plague weakens military strength without a battle.","zh":"因鼠疫失去士兵會在沒有戰鬥的情況下削弱軍力。"},{"en":"The phrase identifies disease as the cause of military deaths.","zh":"這個短語指出疾病是軍事死亡的原因。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":8},{"front":"military chronicles","meaning":"軍事編年史","examples":[{"en":"Russian military chronicles recorded the deaths after Riga was captured.","zh":"俄國軍事編年史記錄了里加被佔領後的死亡。"},{"en":"Military chronicles are historical records of military events, campaigns, and losses.","zh":"military chronicles 指記錄軍事事件、戰役和損失的歷史文獻。"},{"en":"Military chronicles may describe battles, sieges, troop movements, and disease among soldiers.","zh":"軍事編年史可能描述戰鬥、圍城、軍隊移動和士兵疾病。"},{"en":"Chronicles help historians understand what armies experienced at the time.","zh":"編年史幫助歷史學家了解當時軍隊經歷了甚麼。"},{"en":"The phrase refers to written military records, not modern news reports.","zh":"這個短語指書面軍事記錄，而不是現代新聞報道。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":9},{"front":"of the time","meaning":"當時的","examples":[{"en":"Military chronicles of the time described the effects of the plague.","zh":"當時的軍事編年史描述了鼠疫的影響。"},{"en":"Of the time means belonging to or written during that historical period.","zh":"of the time 指屬於或寫於該歷史時期。"},{"en":"Newspapers of the time show how people understood a disaster when it happened.","zh":"當時的報紙顯示人們在災難發生時如何理解它。"},{"en":"Records of the time can reveal details later writers might miss.","zh":"當時的記錄可以揭示後來作者可能錯過的細節。"},{"en":"The phrase connects a source or object to its period.","zh":"這個短語把來源或物件與其時期連起來。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":9},{"front":"the capture of Riga","meaning":"佔領里加","examples":[{"en":"More soldiers died of disease after the capture of Riga.","zh":"在佔領里加後，更多士兵死於疾病。"},{"en":"The capture of Riga means the taking of Riga by military force.","zh":"capture of Riga 指以軍事力量取得里加控制權。"},{"en":"After the capture of a city, the winning army may face disease, shortages, and unrest.","zh":"佔領一座城市後，勝利軍隊可能面對疾病、短缺和動亂。"},{"en":"The capture of Riga did not end the soldiers’ suffering because plague continued to kill them.","zh":"佔領里加並沒有終結士兵的苦難，因為鼠疫繼續奪命。"},{"en":"The phrase describes a military result, not a peaceful handover.","zh":"這個短語描述軍事結果，而不是和平移交。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":9},{"front":"enemy fire","meaning":"敵軍火力","examples":[{"en":"Fewer soldiers died from enemy fire during the siege.","zh":"在圍城期間，死於敵軍火力的士兵較少。"},{"en":"Enemy fire means shooting or attacks from the opposing army.","zh":"enemy fire 指來自敵方軍隊的射擊或攻擊。"},{"en":"Soldiers may take cover to avoid enemy fire.","zh":"士兵可能找掩護避開敵軍火力。"},{"en":"If disease kills more soldiers than enemy fire, illness becomes a major military threat.","zh":"如果疾病殺死的士兵多於敵軍火力，疾病就成為重大軍事威脅。"},{"en":"The phrase refers to direct attack in war.","zh":"這個短語指戰爭中的直接攻擊。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":9},{"front":"during the siege of","meaning":"在圍攻……期間","examples":[{"en":"More soldiers died of plague than from enemy fire during the siege of Riga.","zh":"在圍攻里加期間，死於鼠疫的士兵多於死於敵軍火力的士兵。"},{"en":"During the siege of a place means while that place is being surrounded by military forces.","zh":"during the siege of a place 指某地被軍隊包圍期間。"},{"en":"During the siege of a city, food and medicine may become scarce.","zh":"在圍攻城市期間，食物和藥物可能變得短缺。"},{"en":"Disease can spread quickly during a siege because people are trapped and crowded.","zh":"疾病可以在圍城期間迅速傳播，因為人們被困且擁擠。"},{"en":"The phrase gives the wartime setting for an event.","zh":"這個短語提供事件的戰時背景。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":9},{"front":"impose strict measures","meaning":"實施嚴厲措施","examples":[{"en":"Tsar Peter I imposed strict measures to prevent the spread of plague.","zh":"沙皇彼得一世實施嚴厲措施，以防止鼠疫傳播。"},{"en":"To impose strict measures means to officially enforce tough rules or actions.","zh":"impose strict measures 指正式執行嚴格規則或行動。"},{"en":"A school may impose strict measures after repeated cheating in exams.","zh":"在考試作弊多次發生後，學校可能實施嚴厲措施。"},{"en":"Strict disease measures may include isolation, checkpoints, and travel bans.","zh":"嚴厲疾病措施可能包括隔離、檢查站和旅行禁令。"},{"en":"The phrase suggests strong authority and limited choice.","zh":"這個短語暗示強大權威和有限選擇。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":9},{"front":"prevent the spread of","meaning":"防止……傳播","examples":[{"en":"The tsar tried to prevent the spread of plague.","zh":"沙皇試圖防止鼠疫傳播。"},{"en":"To prevent the spread of something means to stop it from moving to more people or places.","zh":"prevent the spread of something 指阻止某事傳到更多人或地方。"},{"en":"Washing hands can help prevent the spread of infection in schools.","zh":"洗手可以幫助防止感染在學校中傳播。"},{"en":"Border controls can prevent the spread of disease from one region to another.","zh":"邊境管制可以防止疾病從一個地區傳播到另一個地區。"},{"en":"The phrase focuses on stopping movement and transmission.","zh":"這個短語重點是阻止流動和傳播。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":9},{"front":"during these conflicts","meaning":"在這些衝突期間","examples":[{"en":"Strict measures were imposed during these conflicts.","zh":"在這些衝突期間，嚴厲措施被實施。"},{"en":"During these conflicts means while these wars or struggles were happening.","zh":"during these conflicts 指在這些戰爭或鬥爭發生期間。"},{"en":"During these conflicts, armies moved through towns and carried risks with them.","zh":"在這些衝突期間，軍隊穿過城鎮並帶來風險。"},{"en":"Disease control becomes harder during conflicts because soldiers and civilians move under pressure.","zh":"在衝突期間，疾病控制變得更難，因為士兵和平民在壓力下移動。"},{"en":"The phrase gives a wartime context.","zh":"這個短語提供戰時語境。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":9},{"front":"suspected of being infected","meaning":"被懷疑受感染","examples":[{"en":"Soldiers suspected of being infected were isolated.","zh":"被懷疑受感染的士兵被隔離。"},{"en":"Suspected of being infected means believed possibly to have a disease, though not yet confirmed.","zh":"suspected of being infected 指被認為可能患病，但尚未確認。"},{"en":"A student suspected of being infected may be sent home until a test result is clear.","zh":"被懷疑受感染的學生可能被送回家，直到測試結果清楚。"},{"en":"Isolating people suspected of infection can reduce risk before proof arrives.","zh":"在證據出現前隔離被懷疑感染的人，可以降低風險。"},{"en":"The phrase shows uncertainty and caution.","zh":"這個短語顯示不確定性和謹慎。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":9},{"front":"be isolated and taken to","meaning":"被隔離並帶到","examples":[{"en":"Infected soldiers were isolated and taken to distant areas.","zh":"受感染士兵被隔離並帶到遠離地區。"},{"en":"To be isolated and taken to a place means to be separated from others and moved there.","zh":"be isolated and taken to a place 指被與他人分開並移送到某地。"},{"en":"A patient may be isolated and taken to a special ward during a serious infection.","zh":"在嚴重感染期間，病人可能被隔離並帶到特別病房。"},{"en":"Moving sick people away from crowded camps can reduce contact with healthy people.","zh":"把病人移離擁擠軍營可以減少與健康人士接觸。"},{"en":"The phrase combines separation with relocation.","zh":"這個短語結合隔離和轉移位置。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":9},{"front":"far from military camps","meaning":"遠離軍營","examples":[{"en":"Sick soldiers were taken to areas far from military camps.","zh":"患病士兵被帶到遠離軍營的地方。"},{"en":"Far from military camps means at a distance away from places where soldiers live or train.","zh":"far from military camps 指距離士兵居住或訓練地點很遠。"},{"en":"A hospital tent may be placed far from a camp to stop infection spreading.","zh":"醫療帳篷可能設在遠離軍營的位置，以阻止感染傳播。"},{"en":"If sick soldiers stay far from military camps, healthy units are less likely to be exposed.","zh":"如果患病士兵遠離軍營，健康部隊較不容易暴露於感染。"},{"en":"The phrase describes physical separation for safety.","zh":"這個短語描述為安全而作的實體分隔。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":9},{"front":"be designed to separate","meaning":"被設計用來分隔","examples":[{"en":"Camps were designed to separate different military units.","zh":"軍營被設計用來分隔不同軍事單位。"},{"en":"To be designed to separate means to be planned so that groups are kept apart.","zh":"be designed to separate 指被規劃成能把不同群體分開。"},{"en":"A hospital may be designed to separate infectious patients from other patients.","zh":"醫院可能被設計用來分隔傳染病人和其他病人。"},{"en":"Separating units can reduce disease transmission if one group becomes infected.","zh":"如果某一群體受感染，分隔單位可以減少疾病傳播。"},{"en":"The phrase explains the purpose behind a design.","zh":"這個短語解釋設計背後的目的。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":10},{"front":"divisions, detachments and units","meaning":"師、支隊及小隊","examples":[{"en":"The camps separated divisions, detachments and smaller units.","zh":"軍營分隔師、支隊及更小的小隊。"},{"en":"Divisions, detachments and units are different sizes or types of military groups.","zh":"divisions, detachments and units 指不同規模或類型的軍事群體。"},{"en":"A large army may organise soldiers into divisions, smaller detachments, and local units.","zh":"大型軍隊可能把士兵組織成師、較小支隊和地方小隊。"},{"en":"Separating military groups can limit disease spread from one group to another.","zh":"分隔軍事群體可以限制疾病從一組傳到另一組。"},{"en":"The phrase lists military groupings from larger to smaller.","zh":"這個短語列出由較大到較小的軍事編組。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":10},{"front":"threaten to spread to","meaning":"威脅蔓延至","examples":[{"en":"The plague threatened to spread to St Petersburg.","zh":"鼠疫威脅蔓延至聖彼得堡。"},{"en":"To threaten to spread to a place means to create a risk of reaching that place soon.","zh":"threaten to spread to a place 指造成很快到達某地的風險。"},{"en":"A fire may threaten to spread to nearby houses if the wind is strong.","zh":"如果風很強，火災可能威脅蔓延至附近房屋。"},{"en":"If disease threatens to spread to a capital city, authorities may impose stronger controls.","zh":"如果疾病威脅蔓延至首都，當局可能實施更強管制。"},{"en":"The phrase signals danger that has not fully happened yet.","zh":"這個短語表示危險尚未完全發生。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":10},{"front":"newly built capital","meaning":"新建成的首都","examples":[{"en":"St Petersburg was the newly built capital of Russia.","zh":"聖彼得堡是俄國新建成的首都。"},{"en":"A newly built capital is a recently constructed city that serves as a country’s political centre.","zh":"newly built capital 指最近建成、作為國家政治中心的城市。"},{"en":"A newly built capital may need protection because its government offices are important.","zh":"新建成的首都可能需要保護，因為其政府辦公室很重要。"},{"en":"If disease reaches a newly built capital, the ruler’s authority and administration may be threatened.","zh":"如果疾病傳到新建成的首都，統治者權威和行政可能受威脅。"},{"en":"The phrase combines recent construction with political importance.","zh":"這個短語結合近期建造和政治重要性。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":10},{"front":"order the army to","meaning":"命令軍隊去","examples":[{"en":"Tsar Peter I ordered the army to cordon off the boundary.","zh":"沙皇彼得一世命令軍隊封鎖邊界。"},{"en":"To order the army to do something means to command soldiers to carry out an action.","zh":"order the army to do something 指命令士兵執行某行動。"},{"en":"A government may order the army to help after a flood.","zh":"政府可能在洪水後命令軍隊提供協助。"},{"en":"When ordinary officials cannot enforce rules, a ruler may order the army to control movement.","zh":"當普通官員無法執行規則，統治者可能命令軍隊控制流動。"},{"en":"The phrase shows military command from authority.","zh":"這個短語顯示來自權威的軍事命令。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":10},{"front":"cordon off","meaning":"封鎖","examples":[{"en":"The army was ordered to cordon off the entire boundary.","zh":"軍隊被命令封鎖整條邊界。"},{"en":"To cordon off an area means to block it so people cannot freely enter or leave.","zh":"cordon off an area 指封鎖某區，使人不能自由進出。"},{"en":"Police may cordon off a street after an accident.","zh":"意外後，警方可能封鎖街道。"},{"en":"Authorities cordon off infected areas to stop disease from spreading.","zh":"當局封鎖受感染地區，以阻止疾病傳播。"},{"en":"The phrase describes controlled physical closure.","zh":"這個短語描述受控的實體封閉。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":10},{"front":"entire boundary","meaning":"整條邊界","examples":[{"en":"The army cordoned off the entire boundary along the river.","zh":"軍隊封鎖了沿河的整條邊界。"},{"en":"Entire boundary means the whole border or edge of an area.","zh":"entire boundary 指一個地區的整個邊界或邊緣。"},{"en":"A school may fence the entire boundary to keep students safe.","zh":"學校可能圍起整條邊界，以保障學生安全。"},{"en":"If soldiers guard the entire boundary, movement across it becomes much harder.","zh":"如果士兵守住整條邊界，跨越邊界的流動會困難得多。"},{"en":"The phrase stresses complete coverage, not partial control.","zh":"這個短語強調全面覆蓋，而不是部分控制。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":10},{"front":"along the Luga River","meaning":"沿盧加河","examples":[{"en":"The boundary along the Luga River was cordoned off.","zh":"沿盧加河的邊界被封鎖。"},{"en":"Along the Luga River means following or beside the course of that river.","zh":"along the Luga River 指沿着或位於盧加河河道旁。"},{"en":"Villages along a river may depend on it for transport and water.","zh":"沿河村莊可能依靠河流作交通和用水。"},{"en":"If a boundary along a river is closed, boats and crossings may be restricted.","zh":"如果沿河邊界被關閉，船隻和渡口可能受限制。"},{"en":"The phrase gives a geographical line or route.","zh":"這個短語提供地理線路或路線。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":10},{"front":"temporarily halt","meaning":"暫時停止","examples":[{"en":"The authorities temporarily halted all activity on the river.","zh":"當局暫時停止河上的所有活動。"},{"en":"To temporarily halt something means to stop it for a limited time.","zh":"temporarily halt something 指在有限時間內停止某事。"},{"en":"A school may temporarily halt outdoor lessons during heavy rain.","zh":"學校可能在大雨期間暫時停止戶外課堂。"},{"en":"Authorities may temporarily halt river traffic to stop people and goods from carrying disease.","zh":"當局可能暫時停止河上交通，以阻止人員和貨物攜帶疾病。"},{"en":"The phrase suggests a pause, not a permanent ban.","zh":"這個短語暗示暫停，而不是永久禁止。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":10},{"front":"all activity on","meaning":"……上的所有活動","examples":[{"en":"All activity on the river was temporarily halted.","zh":"河上的所有活動被暫時停止。"},{"en":"All activity on a place means every movement, operation, or use happening there.","zh":"all activity on a place 指該處發生的所有移動、運作或使用。"},{"en":"All activity on a sports field may stop during a lightning warning.","zh":"在雷暴警告期間，運動場上的所有活動可能停止。"},{"en":"Stopping all activity on a river can prevent transport, trade, and crossing.","zh":"停止河上的所有活動可以阻止運輸、貿易和渡河。"},{"en":"The phrase stresses that no exceptions are allowed in that area.","zh":"這個短語強調該區域沒有例外。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":10},{"front":"prevent the movement of","meaning":"防止……流動","examples":[{"en":"Roadblocks were set up to prevent the movement of people and goods.","zh":"路障被設置，以防止人員和貨物流動。"},{"en":"To prevent the movement of something means to stop it from travelling from one place to another.","zh":"prevent the movement of something 指阻止某物由一處移到另一處。"},{"en":"Police may close roads to prevent the movement of crowds into a dangerous area.","zh":"警方可能封路，以防止人群進入危險地區。"},{"en":"During an epidemic, preventing movement can reduce contact between infected and healthy areas.","zh":"在疫情期間，防止流動可以減少受感染和健康地區之間的接觸。"},{"en":"The phrase focuses on controlling travel or transport.","zh":"這個短語重點是控制旅行或運輸。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":10},{"front":"people and goods","meaning":"人員和貨物","examples":[{"en":"The authorities restricted the movement of people and goods.","zh":"當局限制人員和貨物流動。"},{"en":"People and goods means travellers and items being transported or traded.","zh":"people and goods 指旅客以及被運輸或交易的物品。"},{"en":"Borders control people and goods to manage security, tax, and health risks.","zh":"邊境控制人員和貨物，以管理安全、稅務和健康風險。"},{"en":"In disease control, both people and goods may matter because infection can travel with them.","zh":"在疾病控制中，人員和貨物都可能重要，因為感染可以隨它們移動。"},{"en":"The phrase covers human movement and material movement together.","zh":"這個短語同時涵蓋人員流動和物資流動。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":11},{"front":"roadblocks and checkpoints","meaning":"路障和檢查站","examples":[{"en":"Roadblocks and checkpoints were set up on all roads.","zh":"所有道路上都設置了路障和檢查站。"},{"en":"Roadblocks and checkpoints are barriers and control points used to stop or inspect travellers.","zh":"roadblocks and checkpoints 指用來阻止或檢查旅客的障礙和控制點。"},{"en":"Police may use roadblocks and checkpoints during emergencies.","zh":"警方可能在緊急情況中使用路障和檢查站。"},{"en":"Roadblocks stop movement, while checkpoints allow officials to question or inspect people.","zh":"路障阻止流動，而檢查站讓官員盤問或檢查人員。"},{"en":"The phrase describes physical control of routes.","zh":"這個短語描述對路線的實體控制。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":11},{"front":"be set up","meaning":"被設置","examples":[{"en":"Checkpoints were set up on all roads.","zh":"檢查站被設置在所有道路上。"},{"en":"To be set up means to be established, installed, or arranged for use.","zh":"be set up 指被建立、安裝或安排使用。"},{"en":"A temporary clinic may be set up after a flood.","zh":"洪水後，臨時診所可能被設置。"},{"en":"If checkpoints are set up early, authorities can control movement more effectively.","zh":"如果檢查站及早設置，當局可以更有效控制流動。"},{"en":"The phrase describes putting something into operation.","zh":"這個短語描述把某事投入運作。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":11},{"front":"the tsar’s orders","meaning":"沙皇的命令","examples":[{"en":"The tsar’s orders were rigorously enforced.","zh":"沙皇的命令被嚴格執行。"},{"en":"The tsar’s orders are commands given by the Russian ruler.","zh":"tsar’s orders 指俄國統治者發出的命令。"},{"en":"Officials had to follow the tsar’s orders even when they were harsh.","zh":"即使命令嚴厲，官員也必須遵守沙皇的命令。"},{"en":"If the tsar’s orders controlled travel, disobedience could bring severe punishment.","zh":"如果沙皇的命令控制出行，違抗可能帶來嚴厲懲罰。"},{"en":"The phrase refers to commands from supreme authority.","zh":"這個短語指來自最高權威的命令。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":11},{"front":"be rigorously enforced","meaning":"被嚴格執行","examples":[{"en":"The tsar’s orders were rigorously enforced.","zh":"沙皇的命令被嚴格執行。"},{"en":"To be rigorously enforced means to be carried out very strictly.","zh":"be rigorously enforced 指被非常嚴格地執行。"},{"en":"Exam rules must be rigorously enforced to keep the test fair.","zh":"考試規則必須被嚴格執行，以保持考試公平。"},{"en":"If quarantine rules are rigorously enforced, fewer people can break isolation.","zh":"如果檢疫規則被嚴格執行，較少人可以違反隔離。"},{"en":"The phrase stresses strict implementation, not loose guidance.","zh":"這個短語強調嚴格實施，而不是寬鬆指引。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":11},{"front":"disobey","meaning":"違抗","examples":[{"en":"Those who disobeyed the tsar’s orders were hanged.","zh":"違抗沙皇命令的人被絞死。"},{"en":"To disobey means to refuse or fail to follow an order or rule.","zh":"disobey 指拒絕或未能遵守命令或規則。"},{"en":"A student who disobeys safety instructions in a laboratory may be removed from class.","zh":"在實驗室違抗安全指示的學生可能被帶離課堂。"},{"en":"In strict military situations, disobeying orders can bring severe punishment.","zh":"在嚴格軍事情況中，違抗命令可以帶來嚴重懲罰。"},{"en":"The word focuses on breaking authority’s command.","zh":"這個詞重點是違反權威命令。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":11},{"front":"be hanged","meaning":"被絞死","examples":[{"en":"People who disobeyed the orders were hanged.","zh":"違抗命令的人被絞死。"},{"en":"To be hanged means to be executed by hanging.","zh":"be hanged 指被處以絞刑。"},{"en":"In some historical societies, criminals were hanged for serious offences.","zh":"在一些歷史社會中，罪犯因嚴重罪行被絞死。"},{"en":"The threat of being hanged shows how severely the orders were enforced.","zh":"被絞死的威脅顯示命令被多麼嚴厲執行。"},{"en":"The phrase refers to capital punishment and should be used seriously.","zh":"這個短語指死刑，應嚴肅使用。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":11},{"front":"apply such methods to","meaning":"採用這些方法去","examples":[{"en":"The authorities applied such methods to contain the disease.","zh":"當局採用這些方法去遏止疾病。"},{"en":"To apply such methods to something means to use those methods for that purpose.","zh":"apply such methods to something 指把這些方法用於某目的。"},{"en":"A teacher may apply such methods to help weak students improve step by step.","zh":"老師可能採用這些方法去幫助能力較弱的學生逐步進步。"},{"en":"Authorities applied roadblocks, isolation, and checkpoints to stop plague from spreading.","zh":"當局採用路障、隔離和檢查站等方法去阻止鼠疫傳播。"},{"en":"The phrase links a set of actions with a target problem.","zh":"這個短語把一組行動與目標問題連起來。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":11},{"front":"contain the spread of","meaning":"遏止……蔓延","examples":[{"en":"The authorities tried to contain the spread of the disease.","zh":"當局試圖遏止疾病蔓延。"},{"en":"To contain the spread of something means to keep it from moving beyond control.","zh":"contain the spread of something 指防止某事失控地擴散。"},{"en":"Firefighters build barriers to contain the spread of a forest fire.","zh":"消防員建立阻隔帶，以遏止森林火災蔓延。"},{"en":"Isolation and checkpoints can contain the spread of disease by limiting contact.","zh":"隔離和檢查站可以透過限制接觸遏止疾病蔓延。"},{"en":"The phrase suggests holding a problem within limits.","zh":"這個短語暗示把問題控制在限度內。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":11},{"front":"limit the number of victims","meaning":"限制受害者人數","examples":[{"en":"The measures were intended to limit the number of victims.","zh":"這些措施旨在限制受害者人數。"},{"en":"To limit the number of victims means to reduce how many people are harmed or killed.","zh":"limit the number of victims 指減少受傷害或死亡的人數。"},{"en":"Better road design can limit the number of victims in traffic accidents.","zh":"更好的道路設計可以限制交通意外中的受害者人數。"},{"en":"During an epidemic, early action can limit the number of victims by slowing transmission.","zh":"在疫情期間，早期行動可以透過減慢傳播限制受害者人數。"},{"en":"The phrase focuses on reducing human suffering.","zh":"這個短語重點是減少人的痛苦。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":11},{"front":"provisional","meaning":"臨時的","examples":[{"en":"All of the measures were provisional.","zh":"所有措施都是臨時的。"},{"en":"Provisional means temporary and used until something more permanent is created.","zh":"provisional 指臨時使用，直到更永久的安排出現。"},{"en":"A school may use a provisional timetable while waiting for new teachers to arrive.","zh":"學校可能在等待新老師到任期間使用臨時時間表。"},{"en":"Provisional measures can solve immediate problems but may not form a long-term system.","zh":"臨時措施可以解決即時問題，但未必形成長期系統。"},{"en":"The word suggests temporary arrangement, not final policy.","zh":"這個詞暗示臨時安排，而不是最終政策。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":11},{"front":"be intended to respond to","meaning":"旨在應對","examples":[{"en":"The measures were intended to respond to specific outbreaks.","zh":"這些措施旨在應對特定爆發。"},{"en":"To be intended to respond to something means to be designed as a reaction to that problem.","zh":"be intended to respond to something 指被設計為對某問題作出反應。"},{"en":"A new homework rule may be intended to respond to repeated late submissions.","zh":"新功課規則可能旨在應對反覆遲交。"},{"en":"Measures intended to respond to one outbreak may not work for a different situation.","zh":"旨在應對一次爆發的措施，未必適用於另一情況。"},{"en":"The phrase shows purpose and reaction.","zh":"這個短語顯示目的和反應。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":12},{"front":"a specific outbreak","meaning":"某一次特定爆發","examples":[{"en":"Each measure responded to a specific outbreak.","zh":"每項措施都回應某一次特定爆發。"},{"en":"A specific outbreak is one particular episode of disease spreading in a place.","zh":"specific outbreak 指疾病在某地傳播的一次特定事件。"},{"en":"A city may design rules for a specific outbreak rather than for all future diseases.","zh":"城市可能為某一次特定爆發制定規則，而不是為所有未來疾病制定規則。"},{"en":"If measures address only a specific outbreak, they may not become a general system.","zh":"如果措施只處理某一次特定爆發，它們可能不會成為一般系統。"},{"en":"The phrase narrows attention to one event.","zh":"這個短語把注意力收窄到一件事件。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":12},{"front":"a coherent set of measures","meaning":"一套連貫的措施","examples":[{"en":"The early actions were not designed as a coherent set of measures.","zh":"早期行動並不是被設計成一套連貫的措施。"},{"en":"A coherent set of measures is a group of actions that fit together logically.","zh":"coherent set of measures 指一組彼此合邏輯配合的行動。"},{"en":"A school needs a coherent set of measures to improve reading, not separate random activities.","zh":"學校需要一套連貫的措施改善閱讀，而不是零散隨機活動。"},{"en":"Without a coherent set of measures, officials may react differently each time a disease appears.","zh":"如果沒有一套連貫措施，官員每次疾病出現時可能反應不同。"},{"en":"The phrase stresses organisation and consistency.","zh":"這個短語強調組織和一致性。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":12},{"front":"be implemented systematically","meaning":"被有系統地實施","examples":[{"en":"The measures were not designed to be implemented systematically.","zh":"這些措施並非設計成被有系統地實施。"},{"en":"To be implemented systematically means to be carried out in an organised, planned, and consistent way.","zh":"be implemented systematically 指以有組織、有計劃和一致的方式執行。"},{"en":"A study plan works better when it is implemented systematically every week.","zh":"學習計劃每週有系統地實施時效果更好。"},{"en":"Disease controls implemented systematically can help officials respond at the first warning sign.","zh":"有系統地實施的疾病管制可以幫助官員在最早警號出現時回應。"},{"en":"The phrase contrasts organised procedure with ad hoc reaction.","zh":"這個短語把有組織程序與臨時反應作對比。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":12},{"front":"at the first sign of","meaning":"在……初現跡象時","examples":[{"en":"The system would act at the first sign of plague.","zh":"該系統會在鼠疫初現跡象時行動。"},{"en":"At the first sign of something means as soon as the earliest warning appears.","zh":"at the first sign of something 指一有最早警號就行動。"},{"en":"Parents may call a doctor at the first sign of a high fever in a baby.","zh":"嬰兒一出現高燒跡象，父母可能就叫醫生。"},{"en":"Acting at the first sign of disease can stop a small problem becoming an outbreak.","zh":"在疾病初現跡象時行動，可以防止小問題變成爆發。"},{"en":"The phrase stresses early response.","zh":"這個短語強調早期回應。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":12},{"front":"the advent of","meaning":"……的出現","examples":[{"en":"The advent of a standard response system came later.","zh":"標準應對系統的出現來得較晚。"},{"en":"The advent of something means the arrival or beginning of an important development.","zh":"advent of something 指重要發展的到來或開始。"},{"en":"The advent of smartphones changed how students communicate and study.","zh":"智能手機的出現改變了學生溝通和學習方式。"},{"en":"The advent of a standard system can make responses more organised than before.","zh":"標準系統的出現可以令回應比以前更有組織。"},{"en":"The phrase is formal and often used for major changes.","zh":"這個短語較正式，常用於重大變化。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":12},{"front":"standard response system","meaning":"標準應對系統","examples":[{"en":"A standard response system was developed a few years later.","zh":"幾年後，一套標準應對系統被發展出來。"},{"en":"A standard response system is an organised set of procedures used whenever a problem appears.","zh":"standard response system 指每當問題出現時使用的一套有組織程序。"},{"en":"Schools may use a standard response system for fire alarms and medical emergencies.","zh":"學校可能為火警和醫療緊急情況使用標準應對系統。"},{"en":"A standard response system helps officials act quickly instead of inventing rules each time.","zh":"標準應對系統幫助官員迅速行動，而不是每次重新制定規則。"},{"en":"The phrase focuses on consistent procedure.","zh":"這個短語重點是一致程序。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":12},{"front":"organise procedures","meaning":"組織程序","examples":[{"en":"The first attempts to organise procedures came after the Astrakhan epidemic.","zh":"最早組織程序的嘗試出現在阿斯特拉罕疫情之後。"},{"en":"To organise procedures means to arrange steps and rules in a clear order.","zh":"organise procedures 指把步驟和規則清楚排序和安排。"},{"en":"A clinic may organise procedures for checking patients during flu season.","zh":"診所可能為流感季節檢查病人組織程序。"},{"en":"Organised procedures help staff know who reports, who isolates, and who informs others.","zh":"有組織的程序幫助員工知道誰報告、誰隔離、誰通知他人。"},{"en":"The phrase stresses structure and planning.","zh":"這個短語強調結構和計劃。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":12},{"front":"carry out proactive steps","meaning":"採取主動措施","examples":[{"en":"The authorities began to carry out proactive steps to control plague.","zh":"當局開始採取主動措施控制鼠疫。"},{"en":"To carry out proactive steps means to take action before a problem becomes worse.","zh":"carry out proactive steps 指在問題惡化前採取行動。"},{"en":"A school carries out proactive steps when it teaches study skills before exams begin.","zh":"學校在考試開始前教授學習技巧，就是採取主動措施。"},{"en":"Proactive disease steps can include surveillance, early reporting, and planned isolation.","zh":"主動疾病措施可以包括監測、早期報告和有計劃隔離。"},{"en":"The phrase contrasts early planning with waiting for disaster.","zh":"這個短語把早期計劃與等待災難作對比。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":12},{"front":"date from","meaning":"追溯至；始於","examples":[{"en":"The first proactive measures date from the aftermath of the epidemic.","zh":"最早的主動措施始於該疫情之後。"},{"en":"To date from a time means to begin or originate then.","zh":"date from a time 指在某時間開始或起源。"},{"en":"This school tradition dates from the 1960s.","zh":"這項學校傳統可追溯至1960年代。"},{"en":"If a health policy dates from an epidemic, the crisis likely pushed authorities to create it.","zh":"如果一項健康政策始於一次疫情，該危機很可能推動當局創立它。"},{"en":"The phrase is used to show historical origin.","zh":"這個短語用來表示歷史起源。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":12},{"front":"the aftermath of","meaning":"……的後果；之後時期","examples":[{"en":"The new procedures date from the aftermath of the 1727–1728 epidemic.","zh":"新程序始於1727至1728年疫情之後。"},{"en":"The aftermath of an event is the period and effects that follow it.","zh":"aftermath of an event 指某事件之後的時期和影響。"},{"en":"In the aftermath of a flood, families may need housing, food, and repairs.","zh":"洪水之後，家庭可能需要住屋、食物和維修。"},{"en":"In the aftermath of an epidemic, governments may create new health rules.","zh":"疫情之後，政府可能制定新的衛生規則。"},{"en":"The phrase focuses on consequences after the main event.","zh":"這個短語重點是主要事件之後的後果。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":12},{"front":"in response to this","meaning":"為回應此事","examples":[{"en":"In response to this, the imperial authorities issued several decrees.","zh":"為回應此事，帝國當局頒布數項法令。"},{"en":"In response to this means as a reaction to the situation just mentioned.","zh":"in response to this 指對剛提到的情況作出反應。"},{"en":"Students complained about noise; in response to this, the school changed the classroom arrangement.","zh":"學生投訴噪音；為回應此事，學校改變課室安排。"},{"en":"After a disease outbreak, authorities may issue rules in response to this danger.","zh":"疾病爆發後，當局可能為回應此危險而頒布規則。"},{"en":"The phrase connects a cause with an official reaction.","zh":"這個短語把原因與官方反應連起來。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":13},{"front":"imperial authorities","meaning":"帝國當局","examples":[{"en":"The imperial authorities issued decrees to control plague.","zh":"帝國當局頒布法令控制鼠疫。"},{"en":"Imperial authorities are officials or institutions acting for an empire.","zh":"imperial authorities 指代表帝國行事的官員或機構。"},{"en":"Imperial authorities may control provinces through governors and official orders.","zh":"帝國當局可能透過省長和官方命令控制省份。"},{"en":"When plague threatened the empire, imperial authorities created rules for reporting and isolation.","zh":"當鼠疫威脅帝國，帝國當局制定通報和隔離規則。"},{"en":"The phrase refers to central power within an empire.","zh":"這個短語指帝國內的中央權力。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":13},{"front":"issue decrees","meaning":"頒布法令","examples":[{"en":"The Russian authorities issued several decrees about plague control.","zh":"俄國當局頒布數項關於鼠疫控制的法令。"},{"en":"To issue decrees means to officially announce laws or commands.","zh":"issue decrees 指正式宣布法律或命令。"},{"en":"A ruler may issue decrees during an emergency to control movement and supplies.","zh":"統治者可能在緊急情況中頒布法令，以控制流動和物資。"},{"en":"Decrees make instructions official so local officials know what to do.","zh":"法令令指示正式化，使地方官員知道該做甚麼。"},{"en":"The phrase is formal and often used in historical or legal contexts.","zh":"這個短語較正式，常用於歷史或法律語境。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":13},{"front":"be aimed at controlling","meaning":"旨在控制","examples":[{"en":"The decrees were aimed at controlling the future spread of plague.","zh":"這些法令旨在控制鼠疫日後的傳播。"},{"en":"To be aimed at controlling something means to be designed to manage or limit it.","zh":"be aimed at controlling something 指被設計用來管理或限制某事。"},{"en":"School rules aimed at controlling noise may require students to keep phones silent.","zh":"旨在控制噪音的校規可能要求學生把手機調至靜音。"},{"en":"Health decrees aimed at controlling disease can include reporting, isolation, and quarantine.","zh":"旨在控制疾病的衛生法令可以包括通報、隔離和檢疫。"},{"en":"The phrase explains the purpose of a rule or action.","zh":"這個短語解釋規則或行動的目的。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":13},{"front":"future spread of plague","meaning":"鼠疫日後的傳播","examples":[{"en":"The decrees tried to control the future spread of plague.","zh":"這些法令試圖控制鼠疫日後的傳播。"},{"en":"Future spread of plague means the possible later movement of plague to more people or places.","zh":"future spread of plague 指鼠疫日後可能傳到更多人或地方。"},{"en":"Officials planned for future spread by ordering early reporting and checkpoints.","zh":"官員透過要求早期通報和設檢查站，為日後傳播作準備。"},{"en":"If future spread is controlled, an outbreak may remain local.","zh":"如果日後傳播受到控制，疫情可能保持在本地。"},{"en":"The phrase looks ahead to later disease transmission.","zh":"這個短語展望後來的疾病傳播。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":13},{"front":"heads of townships","meaning":"鄉鎮首長","examples":[{"en":"The instructions were addressed to governors and heads of townships.","zh":"指示發給省長和鄉鎮首長。"},{"en":"Heads of townships are local officials responsible for town or district administration.","zh":"heads of townships 指負責鄉鎮或地區行政的地方官員。"},{"en":"Heads of townships may organise records, local workers, and emergency responses.","zh":"鄉鎮首長可能組織記錄、本地工作人員和緊急回應。"},{"en":"During disease outbreaks, heads of townships help carry central orders into local communities.","zh":"在疾病爆發期間，鄉鎮首長幫助把中央命令帶入本地社區。"},{"en":"The phrase refers to local leaders.","zh":"這個短語指地方領導者。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":13},{"front":"inform the Senate","meaning":"通知參議院","examples":[{"en":"Governors had to inform the Senate if plague cases were detected.","zh":"如果發現鼠疫個案，省長必須通知參議院。"},{"en":"To inform the Senate means to officially tell that government body about something.","zh":"inform the Senate 指正式把某事告知該政府機構。"},{"en":"A school principal may inform the education board when a serious incident occurs.","zh":"當嚴重事件發生，校長可能通知教育局。"},{"en":"If governors inform the Senate quickly, central authorities can coordinate a response.","zh":"如果省長迅速通知參議院，中央當局可以協調回應。"},{"en":"The phrase focuses on formal reporting upward.","zh":"這個短語重點是正式向上匯報。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":13},{"front":"government body","meaning":"政府機構","examples":[{"en":"The Senate was a government body created by Peter I.","zh":"參議院是彼得一世創立的政府機構。"},{"en":"A government body is an official organisation that performs public duties.","zh":"government body 指執行公共職責的官方組織。"},{"en":"A health department is a government body that manages hospitals and disease control.","zh":"衞生部門是管理醫院和疾病控制的政府機構。"},{"en":"Government bodies create rules, collect information, and advise leaders.","zh":"政府機構制定規則、收集資訊並向領袖提供意見。"},{"en":"The phrase refers to an official institution, not a private group.","zh":"這個短語指官方機構，而不是私人團體。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":13},{"front":"advise the monarch","meaning":"向君主提供意見","examples":[{"en":"The Senate was created to advise the monarch.","zh":"參議院被創立，以向君主提供意見。"},{"en":"To advise the monarch means to give guidance or recommendations to the king, queen, or tsar.","zh":"advise the monarch 指向國王、女王或沙皇提供指引或建議。"},{"en":"Senior officials may advise the monarch on war, trade, and public health.","zh":"高級官員可能就戰爭、貿易和公共衛生向君主提供意見。"},{"en":"If advisers warn the monarch about plague, the ruler can issue stronger orders.","zh":"如果顧問向君主警告鼠疫，統治者可以頒布更強命令。"},{"en":"The phrase describes counsel given to a ruler.","zh":"這個短語描述向統治者提供建議。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":13},{"front":"be detected in","meaning":"在……被發現","examples":[{"en":"Governors had to report plague cases detected in their provinces.","zh":"省長必須報告在其省份被發現的鼠疫個案。"},{"en":"To be detected in a place means to be found or discovered there.","zh":"be detected in a place 指在某地被發現或察覺。"},{"en":"Pollution may be detected in a river after a factory leak.","zh":"工廠洩漏後，污染可能在河流中被發現。"},{"en":"If plague is detected in a province, local authorities must act immediately.","zh":"如果鼠疫在某省被發現，地方當局必須立即行動。"},{"en":"The phrase focuses on discovery through observation or testing.","zh":"這個短語重點是透過觀察或測試發現。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":13},{"front":"respective provinces","meaning":"各自的省份","examples":[{"en":"Governors reported cases in their respective provinces.","zh":"省長報告各自省份中的個案。"},{"en":"Respective provinces means each governor’s own province.","zh":"respective provinces 指每位省長自己的省份。"},{"en":"School principals reported problems in their respective schools.","zh":"校長報告各自學校中的問題。"},{"en":"If governors act in their respective provinces, disease control can happen locally and quickly.","zh":"如果省長在各自省份行動，疾病控制可以在本地快速進行。"},{"en":"The phrase links each official to the area they are responsible for.","zh":"這個短語把每位官員與其負責地區連起來。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":13},{"front":"ensure the physical examination of","meaning":"確保對……進行身體檢查","examples":[{"en":"Governors had to ensure the physical examination of suspected carriers.","zh":"省長必須確保對疑似帶菌者進行身體檢查。"},{"en":"To ensure the physical examination of someone means to make sure they are medically checked.","zh":"ensure the physical examination of someone 指確保某人接受醫學檢查。"},{"en":"A coach may ensure the physical examination of athletes before a competition.","zh":"教練可能在比賽前確保運動員接受身體檢查。"},{"en":"During an outbreak, examining suspected carriers helps identify who needs isolation.","zh":"在疫情期間，檢查疑似帶菌者有助辨認誰需要隔離。"},{"en":"The phrase combines official responsibility with medical checking.","zh":"這個短語結合官方責任和醫療檢查。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":14},{"front":"persons suspected of carrying","meaning":"被懷疑帶有……的人","examples":[{"en":"Persons suspected of carrying the disease had to be examined.","zh":"被懷疑帶有該疾病的人必須接受檢查。"},{"en":"Persons suspected of carrying a disease are people believed possibly to have and spread it.","zh":"persons suspected of carrying a disease 指被認為可能帶有並傳播該疾病的人。"},{"en":"Travellers suspected of carrying infection may need testing at the border.","zh":"被懷疑帶有感染的旅客可能需要在邊境接受測試。"},{"en":"Checking suspected carriers can stop disease before symptoms become obvious.","zh":"檢查疑似帶菌者可以在症狀明顯前阻止疾病。"},{"en":"The phrase focuses on possible transmission, not confirmed illness.","zh":"這個短語重點是可能傳播，而不是已確診疾病。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":14},{"front":"subsequent isolation","meaning":"隨後隔離","examples":[{"en":"The decree required physical examination and subsequent isolation.","zh":"該法令要求身體檢查和隨後隔離。"},{"en":"Subsequent isolation means isolation that happens after an earlier step, such as examination.","zh":"subsequent isolation 指在較早步驟之後發生的隔離，例如檢查之後。"},{"en":"A patient may receive a test first, with subsequent isolation if the result is worrying.","zh":"病人可能先接受測試，如果結果令人擔心，就隨後隔離。"},{"en":"Subsequent isolation protects others after officials identify possible infection.","zh":"隨後隔離在官員辨認可能感染後保護其他人。"},{"en":"The phrase shows sequence: first check, then isolate.","zh":"這個短語顯示次序：先檢查，後隔離。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":14},{"front":"sites where plague victims were found","meaning":"發現鼠疫受害者的地點","examples":[{"en":"Sites where plague victims were found had to be isolated.","zh":"發現鼠疫受害者的地點必須被隔離。"},{"en":"Sites where plague victims were found are places where infected or dead plague victims were discovered.","zh":"sites where plague victims were found 指發現受感染或死亡鼠疫受害者的地方。"},{"en":"A house, market, or camp could become a site where disease victims were found.","zh":"房屋、市場或軍營都可以成為發現疾病受害者的地點。"},{"en":"Isolating such sites prevents others from entering a possibly contaminated area.","zh":"隔離這些地點防止其他人進入可能受污染區域。"},{"en":"The phrase refers to locations linked to cases, not only people.","zh":"這個短語指與個案相關的位置，而不只是人。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":14},{"front":"be encircled by checkpoints","meaning":"被檢查站包圍","examples":[{"en":"Infected sites had to be encircled by checkpoints.","zh":"受感染地點必須被檢查站包圍。"},{"en":"To be encircled by checkpoints means to be surrounded by control points.","zh":"be encircled by checkpoints 指被控制點包圍。"},{"en":"A dangerous area may be encircled by checkpoints so officials can control entry and exit.","zh":"危險地區可能被檢查站包圍，以便官員控制進出。"},{"en":"Encircling an infected site helps stop people from carrying disease out.","zh":"用檢查站包圍受感染地點，有助阻止人們把疾病帶出去。"},{"en":"The phrase describes surrounding a place for control.","zh":"這個短語描述為控制而包圍某地。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":14},{"front":"for the duration of","meaning":"在……持續期間","examples":[{"en":"The sites were isolated for the duration of the outbreak.","zh":"這些地點在疫情持續期間被隔離。"},{"en":"For the duration of something means for the whole time that it lasts.","zh":"for the duration of something 指在某事整個持續時間內。"},{"en":"Students must remain silent for the duration of the exam.","zh":"學生必須在考試持續期間保持安靜。"},{"en":"If a town is closed for the duration of an outbreak, movement is restricted until the danger passes.","zh":"如果城鎮在疫情持續期間關閉，流動會受限制直到危險過去。"},{"en":"The phrase gives a time limit tied to an event.","zh":"這個短語提供與事件相連的時間限制。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":14},{"front":"remain operational","meaning":"維持運作","examples":[{"en":"The checkpoints were to remain operational for at least six weeks.","zh":"檢查站要維持運作至少六星期。"},{"en":"To remain operational means to continue working or functioning.","zh":"remain operational 指繼續工作或發揮功能。"},{"en":"A hospital generator must remain operational during a power cut.","zh":"醫院發電機在停電期間必須維持運作。"},{"en":"If checkpoints remain operational, officials can continue controlling movement.","zh":"如果檢查站維持運作，官員可以繼續控制流動。"},{"en":"The phrase focuses on continued function.","zh":"這個短語重點是持續功能。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":14},{"front":"for at least six weeks","meaning":"至少六星期","examples":[{"en":"The checkpoints remained operational for at least six weeks.","zh":"檢查站維持運作至少六星期。"},{"en":"For at least six weeks means for six weeks or longer.","zh":"for at least six weeks 指六星期或更長時間。"},{"en":"A broken bone may need rest for at least six weeks.","zh":"骨折可能需要休息至少六星期。"},{"en":"Keeping checkpoints open for at least six weeks allowed officials to monitor the area after cases appeared.","zh":"讓檢查站開放至少六星期，使官員能在個案出現後監察該區。"},{"en":"The phrase sets a minimum length of time.","zh":"這個短語設定最低時間長度。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":14},{"front":"infected persons","meaning":"受感染人士","examples":[{"en":"The houses of infected persons were to be burned.","zh":"受感染人士的房屋要被燒毀。"},{"en":"Infected persons are people who have caught a disease.","zh":"infected persons 指已感染疾病的人。"},{"en":"Infected persons may need medical care and isolation to protect others.","zh":"受感染人士可能需要醫療照顧和隔離，以保護其他人。"},{"en":"If infected persons remain in crowded places, disease may spread quickly.","zh":"如果受感染人士留在擁擠地方，疾病可能迅速傳播。"},{"en":"The phrase refers to people carrying illness, not merely people at risk.","zh":"這個短語指帶有疾病的人，而不只是有風險的人。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":14},{"front":"personal property","meaning":"個人財物","examples":[{"en":"The personal property of plague victims was burned.","zh":"鼠疫受害者的個人財物被燒毀。"},{"en":"Personal property means belongings owned by an individual, such as clothes, furniture, or tools.","zh":"personal property 指個人擁有的物品，例如衣物、家具或工具。"},{"en":"After a fire, families may lose personal property even if they survive.","zh":"火災後，即使家人生還，也可能失去個人財物。"},{"en":"Burning personal property was intended to remove possible sources of infection.","zh":"燒毀個人財物旨在移除可能感染來源。"},{"en":"The phrase refers to private belongings, not public land.","zh":"這個短語指私人財物，而不是公共土地。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":14},{"front":"farm animals and cattle","meaning":"農場動物和牛隻","examples":[{"en":"Farm animals and cattle were burned along with infected property.","zh":"農場動物和牛隻與受感染財物一同被燒毀。"},{"en":"Farm animals and cattle are animals kept on farms, with cattle usually meaning cows or bulls.","zh":"farm animals and cattle 指農場飼養的動物，而 cattle 通常指牛。"},{"en":"Farmers depend on farm animals and cattle for food, labour, and income.","zh":"農民依靠農場動物和牛隻提供食物、勞力和收入。"},{"en":"During disease control, animals may be destroyed if authorities believe they carry infection.","zh":"在疾病控制期間，如果當局認為動物帶有感染，它們可能被銷毀。"},{"en":"The phrase refers to livestock, not wild animals.","zh":"這個短語指牲畜，而不是野生動物。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":14},{"front":"neighbouring provinces and cities","meaning":"鄰近省份和城市","examples":[{"en":"Governors informed neighbouring provinces and cities about plague cases.","zh":"省長把鼠疫個案通知鄰近省份和城市。"},{"en":"Neighbouring provinces and cities are nearby administrative areas and urban centres.","zh":"neighbouring provinces and cities 指附近的行政地區和城市中心。"},{"en":"A town may warn neighbouring cities when a river flood is moving downstream.","zh":"當河水洪水向下游移動，城鎮可能警告鄰近城市。"},{"en":"Informing neighbouring provinces helps them prepare controls before disease arrives.","zh":"通知鄰近省份幫助它們在疾病到達前準備管制。"},{"en":"The phrase focuses on nearby places that may be affected next.","zh":"這個短語重點是下一步可能受影響的附近地方。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":15},{"front":"occurring in their territories","meaning":"在其管轄地區發生","examples":[{"en":"Governors reported plague cases occurring in their territories.","zh":"省長報告在其管轄地區發生的鼠疫個案。"},{"en":"Occurring in their territories means happening within the areas they control.","zh":"occurring in their territories 指在他們控制的地區內發生。"},{"en":"Police chiefs report crimes occurring in their districts.","zh":"警長報告在其轄區發生的罪案。"},{"en":"If disease cases occur in a governor’s territory, that governor must respond and inform others.","zh":"如果疾病個案在省長管轄地區發生，該省長必須回應並通知他人。"},{"en":"The phrase links events to official areas of responsibility.","zh":"這個短語把事件與官方責任地區連起來。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":15},{"front":"letters brought by couriers","meaning":"由信差送來的信件","examples":[{"en":"Letters brought by couriers were heated before being copied.","zh":"由信差送來的信件在被抄寫前會被烘熱。"},{"en":"Letters brought by couriers are messages delivered by people who carry them from place to place.","zh":"letters brought by couriers 指由信差從一地送到另一地的訊息。"},{"en":"Couriers may bring urgent letters when ordinary mail is too slow.","zh":"當普通郵件太慢時，信差可能送來緊急信件。"},{"en":"During plague fears, letters brought by couriers were treated carefully in case they carried infection.","zh":"在鼠疫恐懼期間，由信差送來的信件會被小心處理，以免帶有感染。"},{"en":"The phrase refers to delivered written communication.","zh":"這個短語指被送達的書面通訊。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":15},{"front":"be heated above a fire","meaning":"在火上烘熱","examples":[{"en":"Letters were heated above a fire before being copied.","zh":"信件在被抄寫前會在火上烘熱。"},{"en":"To be heated above a fire means to be held over flames or heat.","zh":"be heated above a fire 指被放在火焰或熱力上方加熱。"},{"en":"In the past, people sometimes heated objects above a fire to dry or disinfect them.","zh":"過去，人們有時在火上烘熱物件，以乾燥或消毒它們。"},{"en":"Heating letters above a fire was meant to reduce possible infection before handling them.","zh":"在火上烘熱信件旨在處理前減少可能感染。"},{"en":"The phrase describes a physical treatment using heat.","zh":"這個短語描述使用熱力的實體處理。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":15},{"front":"before being copied","meaning":"在被抄寫之前","examples":[{"en":"Letters were disinfected before being copied.","zh":"信件在被抄寫之前會被消毒。"},{"en":"Before being copied means before someone made a written duplicate of the text.","zh":"before being copied 指在有人把文本抄成副本之前。"},{"en":"Old documents may be cleaned before being copied into official records.","zh":"舊文件可能在被抄入官方記錄前先被清理。"},{"en":"If letters were heated before being copied, scribes could avoid touching untreated materials.","zh":"如果信件在被抄寫前先被烘熱，抄寫員就可避免接觸未處理材料。"},{"en":"The phrase shows that one action happened before another.","zh":"這個短語顯示一個行動發生在另一個行動之前。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":15},{"front":"implementation by the authorities","meaning":"當局的實施","examples":[{"en":"The implementation by the authorities showed practical understanding.","zh":"當局的實施顯示出實際理解。"},{"en":"Implementation by the authorities means the way officials put rules or measures into practice.","zh":"implementation by the authorities 指官員把規則或措施付諸實行的方式。"},{"en":"A law is only useful if implementation by the authorities is clear and fair.","zh":"法律只有在當局清晰而公平地實施時才有用。"},{"en":"Strong implementation by authorities can turn written decrees into real disease control.","zh":"當局有力實施可以把書面法令變成真正疾病控制。"},{"en":"The phrase focuses on action by officials, not just policy wording.","zh":"這個短語重點是官員行動，而不只是政策文字。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":15},{"front":"combined measures","meaning":"綜合措施","examples":[{"en":"The combined measures helped limit the spread of plague.","zh":"綜合措施幫助限制鼠疫傳播。"},{"en":"Combined measures are several actions used together rather than separately.","zh":"combined measures 指幾項行動一起使用，而不是分開使用。"},{"en":"A school may use combined measures, such as tutoring, parent contact, and study plans, to help weak students.","zh":"學校可能使用補習、聯絡家長和學習計劃等綜合措施，幫助能力較弱的學生。"},{"en":"Combined measures can work better because each action supports the others.","zh":"綜合措施可能更有效，因為每項行動支援其他行動。"},{"en":"The phrase stresses the effect of a whole package of actions.","zh":"這個短語強調整套行動的效果。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":15},{"front":"demonstrate an intuitive understanding of","meaning":"顯示對……的直覺理解","examples":[{"en":"The measures demonstrate an intuitive understanding of disease control.","zh":"這些措施顯示對疾病控制的直覺理解。"},{"en":"To demonstrate an intuitive understanding of something means to show a natural practical grasp of it, even without full theory.","zh":"demonstrate an intuitive understanding of something 指顯示對某事有自然、實用的掌握，即使沒有完整理論。"},{"en":"A child may demonstrate an intuitive understanding of fairness by sharing toys equally.","zh":"孩子平均分享玩具，可能顯示對公平的直覺理解。"},{"en":"Isolating patients shows an intuitive understanding that contact spreads disease.","zh":"隔離病人顯示人們直覺理解接觸會傳播疾病。"},{"en":"The phrase suggests practical insight rather than formal scientific explanation.","zh":"這個短語暗示實際洞察，而不是正式科學解釋。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":15},{"front":"timely isolation","meaning":"及時隔離","examples":[{"en":"Timely isolation of infected people was important.","zh":"及時隔離受感染人士很重要。"},{"en":"Timely isolation means separating infected people quickly enough to reduce risk.","zh":"timely isolation 指足夠快速地隔離受感染人士，以降低風險。"},{"en":"A hospital uses timely isolation when a patient with a serious infection arrives.","zh":"當患嚴重感染的病人抵達，醫院會使用及時隔離。"},{"en":"If isolation is timely, fewer people are exposed before symptoms spread.","zh":"如果隔離及時，在症狀傳開前接觸感染的人會較少。"},{"en":"The phrase stresses both separation and speed.","zh":"這個短語同時強調隔離和速度。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":15},{"front":"infected people","meaning":"受感染人士","examples":[{"en":"The timely isolation of infected people limited the spread of plague.","zh":"及時隔離受感染人士限制了鼠疫傳播。"},{"en":"Infected people are people who have caught a disease.","zh":"infected people 指已感染疾病的人。"},{"en":"Infected people may feel sick, but some may spread disease before symptoms appear.","zh":"受感染人士可能感到不適，但有些人在症狀出現前已可傳播疾病。"},{"en":"Separating infected people from others reduces direct contact and lowers transmission.","zh":"把受感染人士與其他人分開，可以減少直接接觸並降低傳播。"},{"en":"The phrase focuses on people carrying an illness.","zh":"這個短語重點是帶有疾病的人。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":15},{"front":"limit the spread of plague","meaning":"限制鼠疫傳播","examples":[{"en":"Timely isolation helped limit the spread of plague.","zh":"及時隔離有助限制鼠疫傳播。"},{"en":"To limit the spread of plague means to reduce how far and how quickly plague moves.","zh":"limit the spread of plague 指減少鼠疫傳播的範圍和速度。"},{"en":"Quarantine and checkpoints can limit the spread of plague between towns.","zh":"檢疫和檢查站可以限制鼠疫在城鎮之間傳播。"},{"en":"If authorities limit the spread early, fewer families and communities are affected.","zh":"如果當局及早限制傳播，受影響的家庭和社區會較少。"},{"en":"The phrase describes controlling transmission rather than curing patients.","zh":"這個短語描述控制傳播，而不是治癒病人。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":15},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Students choose the correct heading for each section.","zh":"學生為每個部分選出正確標題。"},{"en":"To choose the correct heading means to select the title that best matches a paragraph or section.","zh":"choose the correct heading 指選擇最符合段落或部分的標題。"},{"en":"In IELTS reading, students should read the whole paragraph before choosing the heading.","zh":"在 IELTS 閱讀中，學生應先讀完整段，再選標題。"},{"en":"A correct heading captures the main idea, not just one small detail.","zh":"正確標題捕捉主旨，而不只是某個小細節。"},{"en":"The phrase is an exam instruction about identifying main ideas.","zh":"這個短語是關於辨認主旨的考試指示。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":16},{"front":"from the list of headings","meaning":"從標題列表中","examples":[{"en":"The correct heading must be chosen from the list of headings.","zh":"正確標題必須從標題列表中選出。"},{"en":"From the list of headings means using only the titles provided in the question.","zh":"from the list of headings 指只使用題目提供的標題。"},{"en":"Students should not invent their own title if the answer must come from the list of headings.","zh":"如果答案必須來自標題列表，學生不應自創標題。"},{"en":"Checking all options in the list helps avoid choosing a heading that is too narrow.","zh":"檢查列表中所有選項，有助避免選擇太狹窄的標題。"},{"en":"The phrase sets the source of possible answers.","zh":"這個短語設定可能答案的來源。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":16},{"front":"write the correct number","meaning":"寫上正確編號","examples":[{"en":"Students write the correct number in the answer box.","zh":"學生在答案框中寫上正確編號。"},{"en":"To write the correct number means to record the option number that matches the answer.","zh":"write the correct number 指寫下與答案相符的選項編號。"},{"en":"If heading iv is correct, students must write that number, not the full heading.","zh":"如果標題 iv 正確，學生必須寫該編號，而不是完整標題。"},{"en":"Writing the wrong number can lose marks even if the student understood the paragraph.","zh":"即使學生理解段落，寫錯編號也可能失分。"},{"en":"The phrase focuses on answer format.","zh":"這個短語重點是答案格式。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":16},{"front":"resulting from military campaigns","meaning":"由軍事行動引起","examples":[{"en":"Some plague outbreaks resulted from military campaigns.","zh":"一些鼠疫爆發由軍事行動引起。"},{"en":"Resulting from military campaigns means caused by or following wars or army movements.","zh":"resulting from military campaigns 指由戰爭或軍隊移動造成或隨之出現。"},{"en":"Refugee movement can result from military campaigns when fighting reaches towns.","zh":"當戰鬥到達城鎮，難民流動可能由軍事行動引起。"},{"en":"Disease may result from military campaigns because troops travel, crowd together, and enter infected regions.","zh":"疾病可能由軍事行動引起，因為軍隊旅行、擠在一起並進入受感染地區。"},{"en":"The phrase explains a cause linked to war.","zh":"這個短語解釋與戰爭有關的原因。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":16},{"front":"systematic intelligence-gathering","meaning":"有系統的情報收集","examples":[{"en":"Russia used systematic intelligence-gathering about external cases of plague.","zh":"俄國對外國鼠疫個案使用有系統的情報收集。"},{"en":"Systematic intelligence-gathering is organised collection of useful information for decision-making.","zh":"systematic intelligence-gathering 指為決策而有組織地收集有用資訊。"},{"en":"A government may use systematic intelligence-gathering to monitor border risks.","zh":"政府可能使用有系統的情報收集來監察邊境風險。"},{"en":"When information is gathered systematically, officials can act before danger reaches them.","zh":"當資訊被有系統地收集，官員可以在危險到達前行動。"},{"en":"The phrase suggests planned information collection, not accidental rumours.","zh":"這個短語暗示有計劃地收集資訊，而不是偶然傳聞。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":16},{"front":"external cases of plague","meaning":"外國鼠疫個案","examples":[{"en":"Officials gathered information about external cases of plague.","zh":"官員收集有關外國鼠疫個案的資訊。"},{"en":"External cases of plague are plague cases occurring outside the country or region being discussed.","zh":"external cases of plague 指在正在討論的國家或地區外發生的鼠疫個案。"},{"en":"Border authorities monitor external cases of disease to assess importation risk.","zh":"邊境當局監察外國疾病個案，以評估輸入風險。"},{"en":"If external cases increase, a country may strengthen quarantine and port controls.","zh":"如果外國個案增加，一個國家可能加強檢疫和港口管制。"},{"en":"The phrase focuses on disease outside one’s own territory.","zh":"這個短語重點是本國領土以外的疾病。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":16},{"front":"early forms of treatment","meaning":"早期治療方式","examples":[{"en":"The heading refers to early forms of treatment for plague victims.","zh":"該標題指鼠疫受害者的早期治療方式。"},{"en":"Early forms of treatment are medical or practical ways people first used to help the sick.","zh":"early forms of treatment 指人們最初用來幫助病人的醫療或實際方法。"},{"en":"Early forms of treatment for many diseases were often based on limited knowledge.","zh":"許多疾病的早期治療方式常基於有限知識。"},{"en":"If treatment is early and organised, patients may have a better chance of survival.","zh":"如果治療及早且有組織，病人可能有較好生存機會。"},{"en":"The phrase focuses on methods of care, not prevention alone.","zh":"這個短語重點是照顧方法，而不只是預防。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":16},{"front":"plague victims","meaning":"鼠疫受害者","examples":[{"en":"The authorities introduced measures involving plague victims.","zh":"當局引入涉及鼠疫受害者的措施。"},{"en":"Plague victims are people who suffered or died because of plague.","zh":"plague victims 指因鼠疫受苦或死亡的人。"},{"en":"Families of plague victims may need help, isolation, or information from officials.","zh":"鼠疫受害者的家庭可能需要官員提供幫助、隔離或資訊。"},{"en":"If plague victims are not handled safely, infection may spread to caregivers.","zh":"如果鼠疫受害者沒有被安全處理，感染可能傳播給照顧者。"},{"en":"The phrase refers to people harmed by the disease.","zh":"這個短語指受疾病傷害的人。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":16},{"front":"general limitations","meaning":"一般限制","examples":[{"en":"The passage discusses the general limitations of early measures.","zh":"文章討論早期措施的一般限制。"},{"en":"General limitations are broad weaknesses or restrictions that affect how well something works.","zh":"general limitations 指影響某事效果的廣泛弱點或限制。"},{"en":"A study may have general limitations if its sample is small and data are incomplete.","zh":"如果研究樣本小且數據不完整，它可能有一般限制。"},{"en":"Early plague measures had limitations because they were often temporary and reactive.","zh":"早期鼠疫措施有限制，因為它們通常是臨時和被動的。"},{"en":"The phrase focuses on weaknesses, not complete failure.","zh":"這個短語重點是弱點，而不是完全失敗。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":16},{"front":"anti-plague measures","meaning":"抗鼠疫措施","examples":[{"en":"Russia developed anti-plague measures over time.","zh":"俄國隨時間發展出抗鼠疫措施。"},{"en":"Anti-plague measures are actions designed to prevent, control, or reduce plague.","zh":"anti-plague measures 指旨在預防、控制或減少鼠疫的行動。"},{"en":"Quarantine, isolation, and burning infected property can be anti-plague measures.","zh":"檢疫、隔離和焚燒受感染財物都可以是抗鼠疫措施。"},{"en":"Anti-plague measures became more organised after repeated outbreaks.","zh":"在反覆爆發後，抗鼠疫措施變得更有組織。"},{"en":"The phrase refers specifically to measures against plague.","zh":"這個短語專指針對鼠疫的措施。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":16},{"front":"bans against","meaning":"對……的禁令","examples":[{"en":"Russia introduced bans against foreign states affected by plague.","zh":"俄國對受鼠疫影響的外國國家引入禁令。"},{"en":"Bans against something are official rules that prohibit contact, trade, or activity involving it.","zh":"bans against something 指禁止涉及某物的接觸、貿易或活動的官方規則。"},{"en":"A school may introduce bans against smoking on campus.","zh":"學校可能引入校園吸煙禁令。"},{"en":"Bans against infected ships can reduce the chance of disease entering through ports.","zh":"對受感染船隻的禁令可以降低疾病經港口進入的機會。"},{"en":"The phrase suggests formal prohibition.","zh":"這個短語暗示正式禁止。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":16},{"front":"affected by plague","meaning":"受鼠疫影響","examples":[{"en":"Some foreign states were affected by plague.","zh":"一些外國國家受鼠疫影響。"},{"en":"Affected by plague means harmed or influenced by plague outbreaks.","zh":"affected by plague 指受鼠疫爆發傷害或影響。"},{"en":"A city affected by plague may lose population, trade, and public confidence.","zh":"受鼠疫影響的城市可能失去人口、貿易和公眾信心。"},{"en":"Countries affected by plague may face quarantine restrictions from neighbours.","zh":"受鼠疫影響的國家可能面對鄰國的檢疫限制。"},{"en":"The phrase identifies places or people impacted by the disease.","zh":"這個短語指出受疾病影響的地方或人。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":17},{"front":"hostile reactions","meaning":"敵對反應","examples":[{"en":"The heading mentions hostile reactions from foreign states.","zh":"該標題提到外國國家的敵對反應。"},{"en":"Hostile reactions are angry, unfriendly, or aggressive responses.","zh":"hostile reactions 指憤怒、不友善或具攻擊性的回應。"},{"en":"A strict trade ban may cause hostile reactions from businesses that lose money.","zh":"嚴格貿易禁令可能引起蒙受損失企業的敵對反應。"},{"en":"If foreign states feel unfairly blamed, they may respond with hostile reactions.","zh":"如果外國國家覺得被不公平指責，它們可能作出敵對反應。"},{"en":"The phrase describes negative responses, not calm disagreement.","zh":"這個短語描述負面反應，而不是冷靜不同意。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":17},{"front":"associated with war","meaning":"與戰爭有關","examples":[{"en":"Some plague outbreaks were associated with war.","zh":"一些鼠疫爆發與戰爭有關。"},{"en":"Associated with war means connected to war or happening because of wartime conditions.","zh":"associated with war 指與戰爭相關，或因戰時情況而發生。"},{"en":"Food shortages are often associated with war because transport and farming are disrupted.","zh":"糧食短缺常與戰爭有關，因為運輸和農業受干擾。"},{"en":"Disease outbreaks can be associated with war when troops move through infected areas.","zh":"當軍隊穿過受感染地區，疾病爆發可以與戰爭有關。"},{"en":"The phrase shows connection, not always direct proof of cause.","zh":"這個短語顯示關連，但不一定是直接因果證明。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":17},{"front":"formulation and publication","meaning":"制定和公布","examples":[{"en":"The formulation and publication of preventive strategies came later.","zh":"預防策略的制定和公布較後才出現。"},{"en":"Formulation and publication means creating ideas or rules and then making them publicly available.","zh":"formulation and publication 指創建想法或規則，然後公開發布。"},{"en":"A school policy requires formulation and publication before students can follow it clearly.","zh":"學校政策需要制定和公布，學生才可以清楚遵守。"},{"en":"Once health strategies are formulated and published, local officials know the official procedure.","zh":"一旦衛生策略被制定和公布，地方官員就知道官方程序。"},{"en":"The phrase combines planning with communication.","zh":"這個短語結合計劃和傳達。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":17},{"front":"preventive strategies","meaning":"預防策略","examples":[{"en":"Russia eventually published preventive strategies against plague.","zh":"俄國最終公布了對抗鼠疫的預防策略。"},{"en":"Preventive strategies are planned approaches used to stop problems before they spread or worsen.","zh":"preventive strategies 指用來在問題擴散或惡化前阻止它們的計劃方法。"},{"en":"A workplace may use preventive strategies to avoid accidents, such as training and safety checks.","zh":"工作場所可能使用培訓和安全檢查等預防策略避免意外。"},{"en":"Preventive strategies against disease include surveillance, isolation, and clear reporting.","zh":"針對疾病的預防策略包括監測、隔離和清晰通報。"},{"en":"The phrase suggests a planned system, not just one emergency action.","zh":"這個短語暗示有計劃的系統，而不只是一次緊急行動。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":17},{"front":"choose two letters","meaning":"選出兩個字母","examples":[{"en":"Students choose two letters from the options.","zh":"學生從選項中選出兩個字母。"},{"en":"Choose two letters means select two answer choices, usually marked A, B, C, and so on.","zh":"choose two letters 指選擇兩個答案選項，通常標為 A、B、C 等。"},{"en":"If the instruction says choose two letters, giving one answer is incomplete.","zh":"如果指示說選出兩個字母，只給一個答案就是不完整。"},{"en":"Students should check both chosen letters against the passage evidence.","zh":"學生應根據篇章證據檢查兩個所選字母。"},{"en":"The phrase is an exam instruction about answer format.","zh":"這個短語是關於答案格式的考試指示。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":17},{"front":"avoid plague outbreaks","meaning":"避免鼠疫爆發","examples":[{"en":"Russia took measures to avoid plague outbreaks.","zh":"俄國採取措施避免鼠疫爆發。"},{"en":"To avoid plague outbreaks means to prevent plague from spreading in a population.","zh":"avoid plague outbreaks 指防止鼠疫在人群中傳播。"},{"en":"A port city may inspect ships carefully to avoid disease outbreaks.","zh":"港口城市可能仔細檢查船隻，以避免疾病爆發。"},{"en":"Avoiding outbreaks requires early warnings, border controls, and isolation.","zh":"避免爆發需要早期警告、邊境管制和隔離。"},{"en":"The phrase focuses on prevention before large-scale spread happens.","zh":"這個短語重點是在大規模傳播發生前預防。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":17},{"front":"cooperation with foreign leaders","meaning":"與外國領袖合作","examples":[{"en":"The option refers to cooperation with foreign leaders.","zh":"選項提到與外國領袖合作。"},{"en":"Cooperation with foreign leaders means working together with rulers or officials from other countries.","zh":"cooperation with foreign leaders 指與其他國家的統治者或官員共同工作。"},{"en":"Countries may use cooperation with foreign leaders to share health warnings.","zh":"各國可能透過與外國領袖合作分享健康警告。"},{"en":"During disease threats, cooperation can reduce confusion between neighbouring states.","zh":"在疾病威脅期間，合作可以減少鄰國之間的混亂。"},{"en":"The phrase focuses on international collaboration.","zh":"這個短語重點是國際協作。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":17},{"front":"restrictions on access to","meaning":"對進入……施加限制","examples":[{"en":"Russia imposed restrictions on access to its ports.","zh":"俄國對進入其港口施加限制。"},{"en":"Restrictions on access to a place are rules limiting who or what can enter it.","zh":"restrictions on access to a place 指限制誰或甚麼可以進入某地的規則。"},{"en":"A hospital may set restrictions on access to an isolation ward.","zh":"醫院可能對進入隔離病房施加限制。"},{"en":"Restrictions on port access can stop ships from affected countries from entering.","zh":"對港口進入施加限制可以阻止來自受影響國家的船隻入境。"},{"en":"The phrase focuses on controlling entry.","zh":"這個短語重點是控制進入。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":17},{"front":"expulsion of foreigners","meaning":"驅逐外國人","examples":[{"en":"The option mentions the expulsion of foreigners.","zh":"選項提到驅逐外國人。"},{"en":"Expulsion of foreigners means forcing people from other countries to leave.","zh":"expulsion of foreigners 指強迫來自其他國家的人離開。"},{"en":"A government may consider expulsion of foreigners during extreme political conflict.","zh":"政府可能在極端政治衝突期間考慮驅逐外國人。"},{"en":"Expulsion is much stronger than questioning, quarantine, or temporary restriction.","zh":"驅逐比盤問、檢疫或暫時限制嚴厲得多。"},{"en":"The phrase refers to removal from a country or area.","zh":"這個短語指從國家或地區移除某人。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":17},{"front":"statements are made about","meaning":"有哪些關於……的陳述","examples":[{"en":"The question asks which statements are made about Russia.","zh":"題目問有哪些關於俄國的陳述。"},{"en":"Statements are made about something means claims or descriptions are given about it.","zh":"statements are made about something 指文本對某事作出聲稱或描述。"},{"en":"In a reading test, students check which statements are made about a person or event.","zh":"在閱讀測驗中，學生檢查有哪些關於人物或事件的陳述。"},{"en":"If a statement is not made in the passage, students should not assume it is true.","zh":"如果篇章沒有作出某陳述，學生不應假設它為真。"},{"en":"The phrase focuses on what the text actually says.","zh":"這個短語重點是文本實際說了甚麼。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":17},{"front":"in the early eighteenth century","meaning":"在十八世紀初","examples":[{"en":"Several plague outbreaks occurred in the early eighteenth century.","zh":"幾次鼠疫爆發發生在十八世紀初。"},{"en":"In the early eighteenth century means in the first part of the 1700s.","zh":"in the early eighteenth century 指1700年代的早期。"},{"en":"In the early eighteenth century, many European powers were involved in wars.","zh":"在十八世紀初，許多歐洲強國捲入戰爭。"},{"en":"If outbreaks occurred in the early eighteenth century, they happened after 1700 but before the century’s later decades.","zh":"如果爆發發生在十八世紀初，它們就是在1700年後、該世紀較後幾十年前發生。"},{"en":"The phrase gives a broad historical time period.","zh":"這個短語提供廣泛歷史時期。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":18},{"front":"consistently smaller than before","meaning":"一直比以前小","examples":[{"en":"The option says outbreaks were consistently smaller than before.","zh":"選項說疫情一直比以前小。"},{"en":"Consistently smaller than before means repeatedly lower in size or scale than earlier cases.","zh":"consistently smaller than before 指規模或大小反覆低於早前情況。"},{"en":"A class may have consistently smaller numbers after many students move schools.","zh":"如果許多學生轉校，一班人數可能一直比以前小。"},{"en":"If later outbreaks are consistently smaller than before, preventive measures may be working.","zh":"如果後來的爆發一直比以前小，預防措施可能有效。"},{"en":"The phrase requires a repeated pattern, not one small example.","zh":"這個短語需要反覆模式，而不是一個小例子。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":18},{"front":"military casualties","meaning":"軍事傷亡","examples":[{"en":"Military casualties were compared with plague deaths at Riga.","zh":"軍事傷亡與里加的鼠疫死亡人數被比較。"},{"en":"Military casualties are soldiers killed, wounded, missing, or otherwise lost during conflict.","zh":"military casualties 指衝突期間死亡、受傷、失蹤或其他損失的士兵。"},{"en":"Reports of military casualties help commanders understand the cost of a battle.","zh":"軍事傷亡報告幫助指揮官了解戰鬥代價。"},{"en":"If disease deaths exceed military casualties from fighting, illness is a major threat to the army.","zh":"如果疾病死亡超過戰鬥造成的軍事傷亡，疾病就是軍隊的重大威脅。"},{"en":"The phrase refers to military losses, not civilian deaths.","zh":"這個短語指軍事損失，而不是平民死亡。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":18},{"front":"exceed the number of","meaning":"超過……的數量","examples":[{"en":"The option asks whether military casualties exceeded the number of plague victims.","zh":"選項問軍事傷亡是否超過鼠疫受害者的數量。"},{"en":"To exceed the number of something means to be greater than that number.","zh":"exceed the number of something 指比某數量更大。"},{"en":"If applicants exceed the number of available places, the school must choose carefully.","zh":"如果申請人數超過可用名額，學校必須仔細選擇。"},{"en":"If plague deaths exceed battle deaths, disease caused more losses than combat.","zh":"如果鼠疫死亡數超過戰鬥死亡數，疾病造成的損失就比作戰更多。"},{"en":"The phrase is used for numerical comparison.","zh":"這個短語用於數字比較。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":18},{"front":"plague victims","meaning":"鼠疫死者；鼠疫受害者","examples":[{"en":"Plague victims outnumbered deaths from enemy fire.","zh":"鼠疫死者多於死於敵軍火力的人。"},{"en":"Plague victims are people who died or suffered because of plague.","zh":"plague victims 指因鼠疫死亡或受苦的人。"},{"en":"A city with many plague victims may lose workers, families, and community leaders.","zh":"有許多鼠疫受害者的城市可能失去工人、家庭和社區領袖。"},{"en":"If plague victims outnumber soldiers killed by weapons, disease is more destructive than battle.","zh":"如果鼠疫受害者多於被武器殺死的士兵，疾病就比戰鬥更具破壞性。"},{"en":"The phrase identifies people harmed by plague.","zh":"這個短語指出受鼠疫傷害的人。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":18},{"front":"allow plague to spread quickly","meaning":"令鼠疫迅速傳播","examples":[{"en":"The option asks whether camp design allowed plague to spread quickly.","zh":"選項問軍營設計是否令鼠疫迅速傳播。"},{"en":"To allow plague to spread quickly means to create conditions that make plague move fast among people.","zh":"allow plague to spread quickly 指創造讓鼠疫在人群中快速傳播的條件。"},{"en":"Crowded housing can allow infection to spread quickly if people cannot keep distance.","zh":"如果人們不能保持距離，擠迫住房可以令感染迅速傳播。"},{"en":"Poor camp design may allow plague to spread quickly when units are mixed together.","zh":"當不同單位混在一起，差劣軍營設計可能令鼠疫迅速傳播。"},{"en":"The phrase shows how an arrangement can worsen disease transmission.","zh":"這個短語顯示安排如何令疾病傳播惡化。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":18},{"front":"strictly implemented","meaning":"嚴格執行","examples":[{"en":"The tsar’s orders were strictly implemented.","zh":"沙皇的命令被嚴格執行。"},{"en":"Strictly implemented means carried out firmly and with little tolerance for disobedience.","zh":"strictly implemented 指堅決執行，而且幾乎不容許違抗。"},{"en":"Exam rules are strictly implemented when every student is checked before entering.","zh":"如果每名學生入場前都被檢查，考試規則就是被嚴格執行。"},{"en":"If quarantine is strictly implemented, fewer people can leave infected areas.","zh":"如果檢疫被嚴格執行，較少人可以離開受感染地區。"},{"en":"The phrase stresses strong enforcement.","zh":"這個短語強調強力執法。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":18},{"front":"reactive rather than strategic","meaning":"被動應對而非策略性","examples":[{"en":"Early anti-plague measures were reactive rather than strategic.","zh":"早期抗鼠疫措施是被動應對而非策略性。"},{"en":"Reactive rather than strategic means responding after problems appear instead of following a planned long-term approach.","zh":"reactive rather than strategic 指問題出現後才回應，而不是遵循長期計劃。"},{"en":"A student is reactive rather than strategic if he studies only after failing a test.","zh":"如果學生只在測驗不合格後才溫習，他就是被動應對而非策略性。"},{"en":"Disease policy is reactive rather than strategic when officials create rules only during each outbreak.","zh":"當官員只在每次爆發期間制定規則，疾病政策就是被動應對而非策略性。"},{"en":"The phrase contrasts emergency response with planned prevention.","zh":"這個短語把緊急回應與計劃性預防作對比。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":18},{"front":"complete the sentences below","meaning":"完成以下句子","examples":[{"en":"Students complete the sentences below using words from the passage.","zh":"學生使用文章中的字詞完成以下句子。"},{"en":"To complete the sentences below means to fill in missing words in the given sentences.","zh":"complete the sentences below 指填補所給句子中的空缺字詞。"},{"en":"In reading tests, students complete sentences by finding exact words from the text.","zh":"在閱讀測驗中，學生透過從文本找出準確字詞來完成句子。"},{"en":"Grammar matters because the chosen word must fit the sentence correctly.","zh":"文法很重要，因為所選字詞必須正確配合句子。"},{"en":"The phrase is an exam instruction.","zh":"這個短語是考試指示。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":18},{"front":"choose one word only","meaning":"只選一個字","examples":[{"en":"Students choose one word only from the passage.","zh":"學生只從文章中選一個字。"},{"en":"Choose one word only means write exactly one word and no more.","zh":"choose one word only 指準確寫一個詞，不能更多。"},{"en":"If the answer needs one word only, writing two words will break the instruction.","zh":"如果答案只需要一個詞，寫兩個詞就會違反指示。"},{"en":"Students must check spelling and word form carefully when only one word is allowed.","zh":"當只准一個詞時，學生必須仔細檢查拼寫和詞形。"},{"en":"The phrase sets a strict answer-length rule.","zh":"這個短語設定嚴格答案長度規則。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":18},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answer must come from the passage.","zh":"答案必須從文章中選出。"},{"en":"From the passage means using words or information found in the reading text.","zh":"from the passage 指使用閱讀文本中的字詞或資料。"},{"en":"Students should not use outside knowledge if the answer must come from the passage.","zh":"如果答案必須從文章中來，學生不應使用外部知識。"},{"en":"An answer from the passage is safer because it matches the examiner’s source.","zh":"從文章中找到的答案較安全，因為它符合考官的來源。"},{"en":"The phrase tells students where the evidence or wording must come from.","zh":"這個短語告訴學生證據或字詞必須來自哪裡。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":18},{"front":"prompted the publication of","meaning":"促使……公布","examples":[{"en":"An outbreak of plague prompted the publication of a preventive strategy.","zh":"一次鼠疫爆發促使預防策略公布。"},{"en":"To prompt the publication of something means to cause or encourage it to be officially published.","zh":"prompt the publication of something 指促成或推動某事正式公布。"},{"en":"A serious accident may prompt the publication of new safety rules.","zh":"嚴重意外可能促使新安全規則公布。"},{"en":"The Astrakhan epidemic prompted officials to publish a clearer plague-control strategy.","zh":"阿斯特拉罕疫情促使官員公布更清晰的鼠疫控制策略。"},{"en":"The phrase links an event with the release of an official document.","zh":"這個短語把事件與官方文件發布連起來。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":19},{"front":"coherent preventive strategy","meaning":"連貫的預防策略","examples":[{"en":"The epidemic led to a coherent preventive strategy.","zh":"該疫情導致一套連貫的預防策略。"},{"en":"A coherent preventive strategy is a clear, organised plan for stopping future problems.","zh":"coherent preventive strategy 指清晰而有組織、用來阻止未來問題的計劃。"},{"en":"A school needs a coherent preventive strategy for bullying, including reporting, support, and follow-up.","zh":"學校需要一套連貫的欺凌預防策略，包括舉報、支援和跟進。"},{"en":"A coherent plague strategy helps local officials respond in the same way across regions.","zh":"連貫的鼠疫策略幫助地方官員在不同地區以相同方式回應。"},{"en":"The phrase stresses planning, consistency, and prevention.","zh":"這個短語強調計劃、一致性和預防。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":19},{"front":"provincial governors","meaning":"省長","examples":[{"en":"Provincial governors were ordered to report plague cases.","zh":"省長被命令報告鼠疫個案。"},{"en":"Provincial governors are officials responsible for governing provinces.","zh":"provincial governors 指負責治理省份的官員。"},{"en":"Provincial governors may manage local administration, security, and emergency responses.","zh":"省長可能管理地方行政、安全和緊急回應。"},{"en":"If plague appears in a province, the governor must inform higher authorities quickly.","zh":"如果鼠疫在某省出現，省長必須迅速通知上級當局。"},{"en":"The phrase refers to regional officials.","zh":"這個短語指地區官員。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":19},{"front":"possessions of plague victims","meaning":"鼠疫受害者的財物","examples":[{"en":"The possessions of plague victims were burned.","zh":"鼠疫受害者的財物被燒毀。"},{"en":"Possessions of plague victims are the belongings owned by people affected by plague.","zh":"possessions of plague victims 指受鼠疫影響的人所擁有的物品。"},{"en":"Clothes, bedding, tools, and furniture can be possessions of plague victims.","zh":"衣物、床鋪、工具和家具都可以是鼠疫受害者的財物。"},{"en":"Burning possessions was intended to remove objects thought to carry infection.","zh":"燒毀財物旨在移除被認為可能帶有感染的物件。"},{"en":"The phrase focuses on personal belongings linked to infected people.","zh":"這個短語重點是與受感染人士相關的個人財物。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":19},{"front":"correspondence","meaning":"信件；通信","examples":[{"en":"Correspondence was heated above a fire before being copied.","zh":"信件在被抄寫前會放在火上烘熱。"},{"en":"Correspondence means letters or written communication between people or offices.","zh":"correspondence 指人與人或辦事處之間的信件或書面通訊。"},{"en":"A company keeps correspondence with clients to record decisions and agreements.","zh":"公司保存與客戶的通信，以記錄決定和協議。"},{"en":"During plague fears, correspondence could be treated before handling to reduce possible risk.","zh":"在鼠疫恐懼期間，信件可能在處理前先被處理，以降低可能風險。"},{"en":"The word is more formal than letters.","zh":"這個詞比 letters 更正式。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":19},{"front":"held over a fire","meaning":"放在火上烘","examples":[{"en":"Correspondence was held over a fire before it was copied.","zh":"信件在被抄寫前被放在火上烘。"},{"en":"Held over a fire means placed above flames or heat without necessarily touching them.","zh":"held over a fire 指放在火焰或熱力上方，不一定直接接觸火。"},{"en":"People may hold wet clothes over a fire to dry them carefully.","zh":"人們可能把濕衣服放在火上方小心烘乾。"},{"en":"Letters held over a fire were probably treated with heat before officials copied them.","zh":"被放在火上烘的信件，很可能是在官員抄寫前先用熱力處理。"},{"en":"The phrase describes using heat as a practical treatment.","zh":"這個短語描述把熱力作為實際處理方法。"}],"source":"112 - Measures to combat infectious disease in tsarist Russia.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 113":[{"front":"Early Occupations Around the River Thames","meaning":"泰晤士河一帶的早期職業","examples":[{"en":"The passage describes early occupations around the River Thames.","zh":"文章描述泰晤士河一帶的早期職業。"},{"en":"Early occupations around the River Thames were jobs people did near the river in earlier periods.","zh":"泰晤士河一帶的早期職業，是指早期人們在河邊從事的工作。"},{"en":"Boatmen, porters and fish workers were common early occupations around the River Thames.","zh":"船工、搬運工和漁業工人都是泰晤士河一帶常見的早期職業。"},{"en":"These jobs developed because the river carried goods, fish and people through London.","zh":"這些工作之所以發展，是因為河流運載貨物、魚類和人穿過倫敦。"},{"en":"The phrase connects a place with the kinds of work that grew around it.","zh":"這個短語把一個地方與圍繞該地形成的工作種類連繫起來。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":1},{"front":"pioneering survey","meaning":"開創性的調查研究","examples":[{"en":"Laura Wright wrote a pioneering survey about London English.","zh":"Laura Wright 寫了一份關於倫敦英語的開創性調查研究。"},{"en":"A pioneering survey is an early and important study that opens up a subject for later research.","zh":"開創性的調查研究是早期而重要的研究，為後來研究開啟一個課題。"},{"en":"A university may publish a pioneering survey of how young people use social media.","zh":"大學可能出版一份關於年輕人如何使用社交媒體的開創性調查研究。"},{"en":"If a survey is pioneering, later researchers often use it as a starting point.","zh":"如果一項調查研究具開創性，後來研究者常把它作為起點。"},{"en":"The phrase suggests that the study is original, important and influential.","zh":"這個短語暗示該研究具原創性、重要性和影響力。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":1},{"front":"Sources of London English","meaning":"《倫敦英語的來源》","examples":[{"en":"Sources of London English lists many medieval river workers.","zh":"《倫敦英語的來源》列出許多中世紀河上工人。"},{"en":"Sources of London English is the title of a study about where London English came from.","zh":"《倫敦英語的來源》是一項關於倫敦英語來源的研究名稱。"},{"en":"A book like Sources of London English may use old records to explain modern words.","zh":"像《倫敦英語的來源》這類書，可能使用舊記錄來解釋現代詞語。"},{"en":"If a study looks at sources of a dialect, it tries to trace its historical roots.","zh":"如果一項研究探討某種方言的來源，它就是嘗試追溯其歷史根源。"},{"en":"The phrase is a title, so it should be treated as the name of a specific work.","zh":"這個短語是一個書名，因此應視為一部特定作品的名稱。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":1},{"front":"list the variety of","meaning":"列出各種各樣的……","examples":[{"en":"Laura Wright has listed the variety of medieval workers connected with the Thames.","zh":"Laura Wright 列出了各種與泰晤士河相關的中世紀工人。"},{"en":"To list the variety of something means to name many different types of it.","zh":"list the variety of 某物，意思是列出它的許多不同種類。"},{"en":"A teacher may list the variety of jobs found in a hospital.","zh":"老師可能列出醫院中各種各樣的工作。"},{"en":"Listing the variety of river workers helps readers see how complex river life was.","zh":"列出各種河上工人，有助讀者看見河流生活有多複雜。"},{"en":"The phrase stresses range and diversity, not just one example.","zh":"這個短語強調範圍和多樣性，而不只是單一例子。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":1},{"front":"medieval workers","meaning":"中世紀工人","examples":[{"en":"The passage describes medieval workers who depended on the River Thames.","zh":"文章描述依賴泰晤士河的中世紀工人。"},{"en":"Medieval workers were people who did jobs during the Middle Ages.","zh":"medieval workers 是在中世紀從事各種工作的人。"},{"en":"Medieval workers in a city might include porters, boatmen, bakers and sellers.","zh":"城市中的中世紀工人可能包括搬運工、船工、麵包師和小販。"},{"en":"If medieval workers depended on the river, changes in trade affected their income.","zh":"如果中世紀工人依賴河流，貿易變化就會影響他們的收入。"},{"en":"The phrase places ordinary labour in a historical period.","zh":"這個短語把普通勞動放在一個歷史時期中。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":1},{"front":"earn their living from","meaning":"靠……謀生","examples":[{"en":"Many medieval workers earned their living from the River Thames.","zh":"許多中世紀工人靠泰晤士河謀生。"},{"en":"To earn one’s living from something means to get income through work connected with it.","zh":"earn one’s living from 某事，意思是透過與它相關的工作取得收入。"},{"en":"A fisherman earns his living from the sea by catching and selling fish.","zh":"漁民靠海洋捕魚並出售魚獲謀生。"},{"en":"If a family earns its living from tourism, fewer visitors can reduce its income.","zh":"如果一個家庭靠旅遊業謀生，遊客減少會令收入下降。"},{"en":"The phrase explains the source of a person’s livelihood.","zh":"這個短語解釋某人的生計來源。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":1},{"front":"River Thames","meaning":"泰晤士河","examples":[{"en":"The River Thames supported many early occupations in London.","zh":"泰晤士河支撐了倫敦許多早期職業。"},{"en":"The River Thames is the major river that runs through London.","zh":"River Thames 是流經倫敦的主要河流。"},{"en":"Tourists walk beside the River Thames to see bridges, boats and old buildings.","zh":"遊客沿着泰晤士河散步，觀看橋樑、船隻和古老建築。"},{"en":"Because the River Thames connected London with trade routes, many river jobs developed there.","zh":"因為泰晤士河把倫敦與貿易路線連接起來，許多河上工作在那裏發展。"},{"en":"The phrase refers to a real river that shaped London’s history and economy.","zh":"這個短語指一條真實河流，它塑造了倫敦的歷史和經濟。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":1},{"front":"baillies","meaning":"baillies；海關／市場管理人員","examples":[{"en":"The baillies of Queenhithe and Billingsgate acted as customs officers.","zh":"Queenhithe 和 Billingsgate 的 baillies 擔任海關人員。"},{"en":"Baillies were local officials who helped manage markets, ports or customs duties.","zh":"baillies 是協助管理市場、港口或關稅的地方官員。"},{"en":"In a medieval port, baillies might check goods and collect fees.","zh":"在中世紀港口，baillies 可能檢查貨物並收取費用。"},{"en":"If baillies controlled trading points, merchants had to deal with them before unloading goods.","zh":"如果 baillies 控制貿易地點，商人在卸貨前就要與他們打交道。"},{"en":"The word is historical and refers to an official role.","zh":"這個字屬歷史用語，指官方角色。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":1},{"front":"Queenhithe and Billingsgate","meaning":"Queenhithe 和 Billingsgate","examples":[{"en":"The baillies of Queenhithe and Billingsgate acted as customs officers.","zh":"Queenhithe 和 Billingsgate 的 baillies 擔任海關人員。"},{"en":"Queenhithe and Billingsgate were riverside trading places in London.","zh":"Queenhithe 和 Billingsgate 是倫敦河邊的貿易地點。"},{"en":"Merchants bringing fish or goods by river might arrive at Queenhithe and Billingsgate.","zh":"透過河流運送魚類或貨物的商人可能抵達 Queenhithe 和 Billingsgate。"},{"en":"If customs officers worked there, these places were important for trade.","zh":"如果海關人員在那裏工作，這些地方就是重要貿易地點。"},{"en":"The phrase names two specific locations linked with London’s river economy.","zh":"這個短語指出兩個與倫敦河流經濟相關的特定地點。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":1},{"front":"act as customs officers","meaning":"擔任海關人員","examples":[{"en":"The baillies acted as customs officers.","zh":"這些 baillies 擔任海關人員。"},{"en":"To act as customs officers means to check goods and collect trade duties.","zh":"act as customs officers 指檢查貨物並收取貿易稅。"},{"en":"At an airport, officials act as customs officers when they inspect luggage.","zh":"在機場，官員檢查行李時就是擔任海關人員。"},{"en":"If river officials acted as customs officers, they helped control what entered the city.","zh":"如果河上官員擔任海關人員，他們就協助控制進入城市的貨物。"},{"en":"The phrase shows the role someone performs, even if their title is different.","zh":"這個短語顯示某人所扮演的角色，即使其職銜不同。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":1},{"front":"conservators","meaning":"河道保護員；維護人員","examples":[{"en":"Conservators were responsible for maintaining the embankments and the weirs.","zh":"河道保護員負責維修保養堤岸和攔河堰。"},{"en":"Conservators are people who protect, manage or maintain important places or structures.","zh":"conservators 是保護、管理或維護重要地方或結構的人。"},{"en":"Museum conservators protect old paintings from light, moisture and damage.","zh":"博物館修復員保護舊畫免受光線、濕氣和損壞影響。"},{"en":"If river conservators fail to maintain banks and weirs, flooding may become more likely.","zh":"如果河道保護員未能維護河岸和攔河堰，水浸可能更容易發生。"},{"en":"The word suggests protection and careful maintenance.","zh":"這個字暗示保護和仔細維護。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":2},{"front":"be responsible for maintaining","meaning":"負責維修保養……","examples":[{"en":"Conservators were responsible for maintaining river structures.","zh":"河道保護員負責維修保養河流結構。"},{"en":"To be responsible for maintaining something means to have the duty of keeping it in good condition.","zh":"be responsible for maintaining 某物，意思是有責任保持它狀態良好。"},{"en":"A caretaker is responsible for maintaining classrooms, doors and lights.","zh":"校工負責維修保養課室、門和燈。"},{"en":"If nobody is responsible for maintaining a bridge, small damage can become dangerous.","zh":"如果沒有人負責維修保養橋樑，小損壞可能變成危險。"},{"en":"The phrase connects a person or group with an ongoing duty.","zh":"這個短語把某人或某群體與持續責任連繫起來。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":2},{"front":"embankments","meaning":"堤岸","examples":[{"en":"Conservators maintained the embankments along the river.","zh":"河道保護員維護河流沿岸的堤岸。"},{"en":"Embankments are raised banks built to hold back water or support a road or railway.","zh":"embankments 是建起的高岸，用來擋水或支撐道路、鐵路。"},{"en":"After heavy rain, workers inspect embankments for cracks or weakness.","zh":"大雨後，工人會檢查堤岸是否有裂縫或弱點。"},{"en":"If river embankments collapse, nearby homes and markets may flood.","zh":"如果河流堤岸倒塌，附近住宅和市場可能水浸。"},{"en":"The word describes protective structures beside water or transport routes.","zh":"這個字描述水邊或交通路線旁的保護結構。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":2},{"front":"weirs","meaning":"攔河堰；魚梁","examples":[{"en":"Conservators were responsible for maintaining the weirs.","zh":"河道保護員負責維護攔河堰。"},{"en":"Weirs are low barriers built across a river to control water flow or help catch fish.","zh":"weirs 是建在河上的低矮屏障，用來控制水流或協助捕魚。"},{"en":"A weir can slow river water and make the water level easier to manage.","zh":"攔河堰可以減慢河水流速，使水位較容易管理。"},{"en":"If weirs are damaged, water flow and fishing systems may be affected.","zh":"如果攔河堰受損，水流和捕魚系統可能受影響。"},{"en":"The word refers to a river structure, not a bridge.","zh":"這個字指河流結構，而不是橋樑。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":2},{"front":"garthmen","meaning":"魚欄工人","examples":[{"en":"Garthmen worked in the fish garths.","zh":"魚欄工人在魚欄裏工作。"},{"en":"Garthmen were workers connected with enclosed fishing areas in the river.","zh":"garthmen 是與河中圍起捕魚區相關的工人。"},{"en":"A garthman might repair fences, manage fish traps or handle the catch.","zh":"魚欄工人可能修補圍欄、管理魚陷阱或處理魚獲。"},{"en":"If fish garths were important to river trade, garthmen had a specialised role.","zh":"如果魚欄對河上貿易重要，魚欄工人就有專門角色。"},{"en":"The word is historical and linked to fishing work.","zh":"這個字屬歷史用語，與捕魚工作相關。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":2},{"front":"fish garths","meaning":"魚欄；捕魚圍欄","examples":[{"en":"Garthmen worked in the fish garths, or enclosures.","zh":"魚欄工人在魚欄，也就是圍欄區，工作。"},{"en":"Fish garths were enclosed areas or structures used for catching or holding fish.","zh":"fish garths 是用來捕捉或存放魚類的圍起區域或結構。"},{"en":"A river community might build fish garths where fish naturally gathered.","zh":"河邊社區可能在魚自然聚集的地方建魚欄。"},{"en":"If fish garths blocked too much water, authorities might treat them as illegal.","zh":"如果魚欄阻擋太多水流，當局可能把它們視為非法。"},{"en":"The phrase refers to a practical fishing structure.","zh":"這個短語指一種實用捕魚結構。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":2},{"front":"enclosures","meaning":"圍欄；圍起的地方","examples":[{"en":"Fish garths were enclosures used in river fishing.","zh":"魚欄是河中捕魚所用的圍起地方。"},{"en":"Enclosures are areas surrounded or fenced off from the surrounding space.","zh":"enclosures 是被圍起或與周圍空間隔開的地方。"},{"en":"A school playground may have small enclosures for younger children.","zh":"學校操場可能有給年幼兒童使用的小圍欄區。"},{"en":"If animals are kept in enclosures, they cannot move freely outside them.","zh":"如果動物被放在圍欄中，它們就不能自由走到外面。"},{"en":"The word focuses on a space being closed off.","zh":"這個字重點在於空間被封閉起來。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":2},{"front":"galleymen","meaning":"galley 船工","examples":[{"en":"Galleymen were called after the names of their boats.","zh":"galleymen 是以其船隻名稱命名的工人。"},{"en":"Galleymen were river workers whose job title came from a type of boat called a galley.","zh":"galleymen 是職稱來自一種叫 galley 的船的河上工人。"},{"en":"In a port, galleymen might carry people or goods along the water.","zh":"在港口，galley 船工可能沿水路運載人或貨物。"},{"en":"If workers were named after boats, their tools shaped their occupational identity.","zh":"如果工人以船隻命名，他們的工具就塑造了職業身份。"},{"en":"The word shows how river jobs often took names from vessels.","zh":"這個字顯示河上工作常以船隻名稱命名。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":2},{"front":"lightermen","meaning":"駁船工人","examples":[{"en":"Lightermen were river workers named after the boats they used.","zh":"lightermen 是以他們使用的船命名的河上工人。"},{"en":"Lightermen were workers who operated lighters, small boats used to move goods.","zh":"lightermen 是操作駁船的工人，駁船是用來運送貨物的小船。"},{"en":"Lightermen might carry cargo between large ships and the shore.","zh":"駁船工人可能在大船和岸邊之間運送貨物。"},{"en":"If large ships could not reach a quay, lightermen moved goods in smaller vessels.","zh":"如果大船不能靠近碼頭，駁船工人就用較小船隻搬運貨物。"},{"en":"The term is closely connected with river transport and cargo handling.","zh":"這個詞與河上運輸和貨物處理密切相關。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":2},{"front":"shoutmen","meaning":"shout 船工","examples":[{"en":"Shoutmen were called after the names of their boats.","zh":"shoutmen 是以其船隻名稱命名的工人。"},{"en":"Shoutmen were river workers whose name came from the boat they operated.","zh":"shoutmen 是名稱來自所操作船隻的河上工人。"},{"en":"Like lightermen, shoutmen belonged to a specialised river workforce.","zh":"像駁船工人一樣，shout 船工屬於專門化的河上勞動力。"},{"en":"If a job title came from a boat, people could quickly understand the worker’s role.","zh":"如果職稱來自船隻，人們可以很快理解工人的角色。"},{"en":"The word reflects the detailed naming system of Thames occupations.","zh":"這個字反映泰晤士河職業細緻的命名系統。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":2},{"front":"be called after","meaning":"以……命名","examples":[{"en":"Some river workers were called after the names of their boats.","zh":"一些河上工人以他們船隻的名稱命名。"},{"en":"To be called after something means to be named because of it.","zh":"be called after 某物，意思是因它而得名。"},{"en":"A street may be called after a famous local doctor.","zh":"一條街可能以一位著名本地醫生命名。"},{"en":"If workers are called after their tools, their names reveal what they use.","zh":"如果工人以工具命名，他們的名稱就透露他們使用甚麼。"},{"en":"The phrase explains the reason behind a name.","zh":"這個短語解釋名稱背後的原因。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":3},{"front":"be named after","meaning":"以……命名","examples":[{"en":"Hookers were named after the manner in which they caught fish.","zh":"hookers 是以他們捕魚的方式命名。"},{"en":"To be named after something means to receive a name because of that person, thing or method.","zh":"be named after 某人、某物或某方法，意思是因它而得到名稱。"},{"en":"A school may be named after a respected teacher.","zh":"學校可能以一位受尊敬的老師命名。"},{"en":"If workers are named after how they fish, their job title describes their method.","zh":"如果工人以捕魚方式命名，他們的職稱就描述了工作方法。"},{"en":"The phrase is similar to “be called after”.","zh":"這個短語與 be called after 相似。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":3},{"front":"the manner in which","meaning":"……的方式","examples":[{"en":"Hookers were named after the manner in which they caught their fish.","zh":"hookers 是以他們捕魚的方式命名。"},{"en":"The manner in which something is done means the way it is done.","zh":"the manner in which 某事完成，指完成它的方法。"},{"en":"A teacher may judge not only the answer but also the manner in which students explain it.","zh":"老師可能不只評估答案，也評估學生解釋答案的方式。"},{"en":"If the manner in which workers catch fish is unusual, it may become part of their name.","zh":"如果工人捕魚的方式很特別，它可能成為他們名稱的一部分。"},{"en":"The phrase is formal and useful for describing methods.","zh":"這個短語較正式，適合描述方法。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":3},{"front":"catch their fish","meaning":"捕魚","examples":[{"en":"Some workers were named after the way they caught their fish.","zh":"一些工人以他們捕魚的方式命名。"},{"en":"To catch their fish means to capture fish for food, sale or trade.","zh":"catch their fish 指捕捉魚類以作食用、出售或交易。"},{"en":"Fishermen may catch their fish with nets, hooks or traps.","zh":"漁民可能用網、魚鈎或陷阱捕魚。"},{"en":"If workers catch their fish in a distinctive way, people may use that method to identify them.","zh":"如果工人以特別方式捕魚，人們可能用該方法來辨認他們。"},{"en":"The phrase describes the practical action at the centre of fishing work.","zh":"這個短語描述捕魚工作的核心實際動作。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":3},{"front":"searcher","meaning":"搜查員；巡查員","examples":[{"en":"The searcher patrolled the Thames in search of illegal fish weirs.","zh":"搜查員巡查泰晤士河，尋找非法魚梁。"},{"en":"A searcher was an official or worker whose job was to look for illegal river structures or activities.","zh":"searcher 是負責尋找非法河流結構或活動的官員或工人。"},{"en":"A modern searcher might inspect a market for unsafe products.","zh":"現代巡查員可能檢查市場有沒有不安全產品。"},{"en":"If a searcher found an illegal weir, authorities could remove it.","zh":"如果搜查員找到非法魚梁，當局就可以移除它。"},{"en":"The word focuses on inspection and detection.","zh":"這個字重點在於檢查和發現。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":3},{"front":"patrol the Thames","meaning":"巡查泰晤士河","examples":[{"en":"The searcher patrolled the Thames looking for illegal fish weirs.","zh":"搜查員巡查泰晤士河，尋找非法魚梁。"},{"en":"To patrol the Thames means to move along the River Thames to watch, inspect or enforce rules.","zh":"patrol the Thames 指沿着泰晤士河巡視、檢查或執行規則。"},{"en":"Police may patrol a neighbourhood to prevent theft.","zh":"警察可能巡查社區以防止盜竊。"},{"en":"If officials patrol the Thames regularly, illegal structures are easier to find.","zh":"如果官員定期巡查泰晤士河，非法結構就更容易被發現。"},{"en":"The phrase describes active monitoring of the river.","zh":"這個短語描述對河流的主動監察。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":3},{"front":"in search of","meaning":"尋找……","examples":[{"en":"The searcher patrolled the river in search of illegal fish weirs.","zh":"搜查員巡查河流，尋找非法魚梁。"},{"en":"In search of something means looking for it.","zh":"in search of 某物，意思是尋找它。"},{"en":"A student may visit several libraries in search of a rare book.","zh":"學生可能走訪幾間圖書館，尋找一本罕見書。"},{"en":"If workers walk along the river in search of damage, they can repair problems early.","zh":"如果工人沿河尋找損壞，他們就能及早維修問題。"},{"en":"The phrase gives the purpose of looking or travelling.","zh":"這個短語說明尋找或行動的目的。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":3},{"front":"illegal fish weirs","meaning":"非法魚梁","examples":[{"en":"The searcher looked for illegal fish weirs on the Thames.","zh":"搜查員在泰晤士河尋找非法魚梁。"},{"en":"Illegal fish weirs are fish-catching barriers built without permission or against rules.","zh":"illegal fish weirs 是未經許可或違反規則建造的捕魚屏障。"},{"en":"A council may remove illegal fish weirs if they block boats or damage river life.","zh":"如果非法魚梁阻礙船隻或破壞河流生態，地方議會可能移除它們。"},{"en":"If illegal fish weirs disturb water flow, both trade and fishing can be affected.","zh":"如果非法魚梁干擾水流，貿易和捕魚都可能受影響。"},{"en":"The phrase combines fishing equipment with law-breaking.","zh":"這個短語把捕魚設備與違法行為連在一起。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":3},{"front":"tideman","meaning":"潮汐工人","examples":[{"en":"The tideman worked on the river’s banks whenever the tide permitted him to do so.","zh":"潮汐工人每當潮水容許時，就在河岸工作。"},{"en":"A tideman was a worker whose job depended on the river tide.","zh":"tideman 是工作取決於河水潮汐的工人。"},{"en":"A tideman might search the foreshore only when low tide exposed the ground.","zh":"潮汐工人可能只有在低潮露出前灘時才可搜尋。"},{"en":"If the tide rose, a tideman had to stop or move to safety.","zh":"如果潮水上漲，潮汐工人就必須停工或移到安全地方。"},{"en":"The word shows how river work followed natural conditions.","zh":"這個字顯示河邊工作如何跟隨自然條件。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":3},{"front":"banks and foreshores","meaning":"河岸和前灘","examples":[{"en":"The tideman worked on the banks and foreshores of the Thames.","zh":"潮汐工人在泰晤士河的河岸和前灘工作。"},{"en":"Banks and foreshores are the raised river edges and the exposed shore areas near the water.","zh":"banks and foreshores 指河流邊緣較高的岸和靠近水邊、潮退時露出的地帶。"},{"en":"At low tide, people may walk on the foreshore beside a river.","zh":"低潮時，人們可能在河邊前灘行走。"},{"en":"If work happens on banks and foreshores, workers must watch changing water levels.","zh":"如果工作在河岸和前灘進行，工人必須留意水位變化。"},{"en":"The phrase describes land beside and just below the river edge.","zh":"這個短語描述河邊及河邊以下的土地。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":3},{"front":"whenever the tide permitted","meaning":"每當潮水容許時","examples":[{"en":"The tideman worked whenever the tide permitted him to do so.","zh":"潮汐工人每當潮水容許時便工作。"},{"en":"Whenever the tide permitted means at any time when the water level made the work possible.","zh":"whenever the tide permitted 指任何水位使工作成為可能的時候。"},{"en":"Fishermen repaired nets on the shore whenever the tide permitted access.","zh":"漁民每當潮水容許他們到達岸邊時，就在岸上修補漁網。"},{"en":"If work depends on tides, people cannot choose their hours freely.","zh":"如果工作取決於潮汐，人們就不能自由選擇工作時間。"},{"en":"The phrase shows that nature controls the timing of the work.","zh":"這個短語顯示自然條件控制工作時間。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":4},{"front":"persist for many centuries","meaning":"持續多個世紀","examples":[{"en":"Many river occupations persisted for many centuries.","zh":"許多河上職業持續多個世紀。"},{"en":"To persist for many centuries means to continue existing for hundreds of years.","zh":"persist for many centuries 指繼續存在數百年。"},{"en":"Some market traditions persist for many centuries because local people keep using them.","zh":"有些市集傳統持續多個世紀，因為本地人一直使用它們。"},{"en":"If a job persists for many centuries, it must meet a long-term social need.","zh":"如果一種工作持續多個世紀，它必定滿足長期社會需要。"},{"en":"The phrase highlights survival over a very long time.","zh":"這個短語強調經過很長時間仍能延續。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":4},{"front":"depend upon","meaning":"依賴；取決於","examples":[{"en":"Some jobs depended upon the trade of the river.","zh":"有些工作依賴河上的貿易。"},{"en":"To depend upon something means to need it in order to exist, succeed or continue.","zh":"depend upon 某事，意思是需要它才能存在、成功或持續。"},{"en":"A restaurant may depend upon office workers for lunchtime business.","zh":"餐廳可能依賴辦公室員工帶來午餐生意。"},{"en":"If a town depends upon tourism, bad weather can reduce income.","zh":"如果小鎮依賴旅遊業，惡劣天氣可能減少收入。"},{"en":"The phrase shows reliance on a condition or source.","zh":"這個短語顯示對某條件或來源的依靠。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":4},{"front":"the trade of the river","meaning":"河上的貿易","examples":[{"en":"Many jobs depended upon the trade of the river.","zh":"許多工作依賴河上的貿易。"},{"en":"The trade of the river means the buying, selling and movement of goods by river.","zh":"the trade of the river 指透過河流進行的買賣和貨物流動。"},{"en":"A port city grows when the trade of the river brings merchants and ships.","zh":"當河上的貿易帶來商人和船隻，港口城市就會成長。"},{"en":"If the trade of the river declines, porters and boat workers may lose work.","zh":"如果河上的貿易衰落，搬運工和船工可能失去工作。"},{"en":"The phrase describes river-based commerce.","zh":"這個短語描述以河流為基礎的商業活動。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":4},{"front":"carry goods upon their backs","meaning":"背負貨物","examples":[{"en":"Workers carried most goods upon their backs.","zh":"工人大多把貨物背在背上搬運。"},{"en":"To carry goods upon their backs means to move goods by loading them onto workers’ backs.","zh":"carry goods upon their backs 指把貨物放在工人背上，以體力搬運。"},{"en":"In a narrow market street, workers may carry goods upon their backs when carts cannot pass.","zh":"在狹窄市集街道，如果手推車不能通過，工人可能背負貨物。"},{"en":"If goods are carried on people’s backs, the work is slow and physically demanding.","zh":"如果貨物靠人背負搬運，工作就緩慢且耗體力。"},{"en":"The phrase shows manual labour without machines or vehicles.","zh":"這個短語顯示沒有機器或車輛的人手勞動。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":4},{"front":"rough surfaces","meaning":"粗糙的表面","examples":[{"en":"The rough surfaces of the quays were unsuitable for wagons.","zh":"碼頭粗糙的表面不適合貨車。"},{"en":"Rough surfaces are uneven or bumpy surfaces that make movement difficult.","zh":"rough surfaces 是不平坦或凹凸不平、令人難以移動的表面。"},{"en":"A wheelchair is hard to push across rough surfaces in an old street.","zh":"在舊街道的粗糙表面上，輪椅很難推動。"},{"en":"If a quay has rough surfaces, barrels may roll better than carts.","zh":"如果碼頭表面粗糙，木桶可能比手推車更容易移動。"},{"en":"The phrase explains why some transport methods were inconvenient.","zh":"這個短語解釋為何某些運輸方法不方便。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":4},{"front":"quays","meaning":"碼頭；岸邊裝卸區","examples":[{"en":"The rough surfaces of the quays made transport difficult.","zh":"碼頭粗糙的表面令運輸變得困難。"},{"en":"Quays are platforms or areas beside water where ships load and unload goods.","zh":"quays 是水邊讓船隻裝卸貨物的平台或區域。"},{"en":"Workers on quays may move boxes, barrels and ropes from ships.","zh":"碼頭工人可能從船上搬運箱子、木桶和繩索。"},{"en":"If quays are crowded or uneven, unloading goods becomes slower.","zh":"如果碼頭擠迫或不平，卸貨就會變慢。"},{"en":"The word refers to a working waterfront area.","zh":"這個字指運作中的水邊裝卸區。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":4},{"front":"nearby streets","meaning":"附近街道","examples":[{"en":"The nearby streets were not suitable for large carts.","zh":"附近街道不適合大型手推車。"},{"en":"Nearby streets are roads close to the place being discussed.","zh":"nearby streets 是靠近所討論地點的道路。"},{"en":"When a concert ends, nearby streets may become crowded with people and taxis.","zh":"音樂會結束時，附近街道可能擠滿人和的士。"},{"en":"If nearby streets are narrow, moving heavy goods by cart is difficult.","zh":"如果附近街道狹窄，用手推車搬重貨就很困難。"},{"en":"The phrase gives the surrounding urban context.","zh":"這個短語提供周圍城市環境。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":4},{"front":"not suitable for","meaning":"不適合……","examples":[{"en":"The quays were not suitable for wagons or large carts.","zh":"碼頭不適合貨車或大型手推車。"},{"en":"Not suitable for something means not appropriate or not practical for that use.","zh":"not suitable for 某用途，意思是不合適或不實用。"},{"en":"A tiny classroom is not suitable for a large public meeting.","zh":"很小的課室不適合大型公開會議。"},{"en":"If a road is not suitable for heavy trucks, drivers must choose another route.","zh":"如果道路不適合重型貨車，司機必須選擇另一條路線。"},{"en":"The phrase explains a mismatch between a place or tool and a purpose.","zh":"這個短語解釋地方或工具與用途之間不配合。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":4},{"front":"wagons or large carts","meaning":"貨車或大型手推車","examples":[{"en":"Goods could not easily be moved by wagons or large carts.","zh":"貨物不容易由貨車或大型手推車搬運。"},{"en":"Wagons or large carts are wheeled vehicles used to carry heavy goods.","zh":"wagons or large carts 是用來運送重貨的有輪車輛。"},{"en":"Farmers once used wagons or large carts to move crops to market.","zh":"農民以前用貨車或大型手推車把農作物運到市場。"},{"en":"If streets are too narrow, wagons or large carts cannot turn safely.","zh":"如果街道太窄，貨車或大型手推車就不能安全轉彎。"},{"en":"The phrase refers to land transport for heavy loads.","zh":"這個短語指用於重物的陸上運輸工具。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":4},{"front":"merchandise","meaning":"商品；貨物","examples":[{"en":"The merchandise characteristically arrived in barrels.","zh":"這些貨物通常以木桶形式到達。"},{"en":"Merchandise means goods that are bought, sold or transported in business.","zh":"merchandise 指商業中被買賣或運送的貨物。"},{"en":"A shop’s merchandise may include clothes, books, food or tools.","zh":"商店的商品可能包括衣服、書本、食物或工具。"},{"en":"If merchandise arrives damaged, the seller may lose money.","zh":"如果貨物到達時受損，賣家可能損失金錢。"},{"en":"The word is a formal way to say goods or products.","zh":"這個字是 goods 或 products 的較正式說法。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":5},{"front":"characteristically arrive in","meaning":"通常以……形式到達","examples":[{"en":"The merchandise characteristically arrived in barrels.","zh":"貨物通常以木桶形式到達。"},{"en":"To characteristically arrive in a form means to usually arrive that way.","zh":"characteristically arrive in 某形式，意思是通常以那種方式到達。"},{"en":"Fresh milk characteristically arrives in bottles or cartons.","zh":"新鮮牛奶通常以瓶或紙盒形式到達。"},{"en":"If goods characteristically arrive in barrels, workers design ways to move barrels efficiently.","zh":"如果貨物通常以木桶形式到達，工人就會設計方法有效搬運木桶。"},{"en":"The phrase describes the normal pattern of arrival.","zh":"這個短語描述正常到貨模式。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":5},{"front":"barrels","meaning":"木桶","examples":[{"en":"The goods arrived in barrels that could be rolled along the quay.","zh":"貨物以木桶到達，可以沿碼頭滾動。"},{"en":"Barrels are round containers, often made of wood, used to store liquids or goods.","zh":"barrels 是圓形容器，通常由木製成，用來存放液體或貨物。"},{"en":"Wine, oil or salted food may be transported in barrels.","zh":"葡萄酒、油或鹽醃食品可能以木桶運送。"},{"en":"Because barrels are round, workers can roll them instead of lifting them.","zh":"因為木桶是圓形的，工人可以滾動它們而不是抬起它們。"},{"en":"The word names a practical container for trade goods.","zh":"這個字指一種用於貿易貨物的實用容器。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":5},{"front":"be rolled from","meaning":"從……滾動運送","examples":[{"en":"Barrels could be rolled from the ship along each quay.","zh":"木桶可以從船上沿每個碼頭滾動運送。"},{"en":"To be rolled from a place means to be moved by turning over and over from that starting point.","zh":"be rolled from 某處，意思是從該起點透過反覆滾動移動。"},{"en":"A heavy gas cylinder may be rolled from a storeroom instead of carried.","zh":"重型氣瓶可能從儲物室滾出，而不是被搬起。"},{"en":"If barrels can be rolled from a ship, workers save effort compared with lifting them.","zh":"如果木桶可以從船上滾動運送，工人就比抬起它們省力。"},{"en":"The phrase describes movement by rolling rather than carrying.","zh":"這個短語描述用滾動而非搬運移動。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":5},{"front":"along each quay","meaning":"沿着每個碼頭","examples":[{"en":"The barrels were rolled from the ship along each quay.","zh":"木桶從船上沿着每個碼頭滾動。"},{"en":"Along each quay means moving beside or across every loading area by the water.","zh":"along each quay 指沿水邊每個裝卸區旁邊或其上移動。"},{"en":"Workers may push trolleys along each quay to collect cargo.","zh":"工人可能沿着每個碼頭推手推車收集貨物。"},{"en":"If goods move along each quay, the surface must allow safe movement.","zh":"如果貨物沿着每個碼頭移動，地面必須讓移動安全進行。"},{"en":"The phrase describes direction across the waterfront working area.","zh":"這個短語描述在水邊工作區的移動方向。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":5},{"front":"the burden was too great","meaning":"負荷太重","examples":[{"en":"The burden was too great to be carried by a single man.","zh":"負荷太重，無法由一個人搬運。"},{"en":"The burden was too great means the load was too heavy or difficult.","zh":"the burden was too great 指負荷太重或太困難。"},{"en":"A large sofa may be too great a burden for one person to move upstairs.","zh":"大梳化對一個人來說可能負荷太重，無法搬上樓。"},{"en":"If the burden is too great, workers need tools or extra people.","zh":"如果負荷太重，工人就需要工具或更多人手。"},{"en":"The phrase can describe physical weight or a difficult responsibility.","zh":"這個短語可以描述實際重量，也可以描述沉重責任。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":5},{"front":"be carried by a single man","meaning":"由一個人搬運","examples":[{"en":"Some goods were too heavy to be carried by a single man.","zh":"有些貨物太重，不能由一個人搬運。"},{"en":"To be carried by a single man means to be lifted and moved by one person alone.","zh":"be carried by a single man 指由一個人單獨抬起並移動。"},{"en":"A small box can be carried by a single man, but a piano cannot.","zh":"小箱子可以由一個人搬運，但鋼琴不可以。"},{"en":"If a load cannot be carried by a single man, teamwork becomes necessary.","zh":"如果負荷不能由一個人搬運，團隊合作就變得必要。"},{"en":"The phrase stresses the physical limit of one worker.","zh":"這個短語強調單一工人的體力限制。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":5},{"front":"be slung on poles","meaning":"被吊掛在桿上","examples":[{"en":"The goods were slung on poles resting on two men’s shoulders.","zh":"貨物被吊掛在放在兩個人肩上的桿上。"},{"en":"To be slung on poles means to be hung or supported on long rods for carrying.","zh":"be slung on poles 指貨物被掛在或支撐在長桿上搬運。"},{"en":"Workers may sling heavy baskets on poles so two people can share the load.","zh":"工人可能把重籃子吊掛在桿上，讓兩人分擔重量。"},{"en":"If goods are slung on poles, the weight can be spread across two workers.","zh":"如果貨物被吊掛在桿上，重量就可以分散到兩名工人身上。"},{"en":"The phrase describes an old manual carrying method.","zh":"這個短語描述一種舊式人手搬運方法。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":5},{"front":"resting on the shoulders of","meaning":"放在……的肩上","examples":[{"en":"The poles rested on the shoulders of two men.","zh":"這些桿放在兩個人的肩上。"},{"en":"Resting on the shoulders of someone means being supported by that person’s shoulders.","zh":"resting on the shoulders of 某人，意思是由該人的肩膀支撐。"},{"en":"A long ladder may rest on the shoulders of two workers as they carry it.","zh":"兩名工人搬運長梯時，梯子可能放在他們肩上。"},{"en":"If a pole rests on workers’ shoulders, their bodies bear the weight directly.","zh":"如果桿放在工人肩上，他們的身體就直接承受重量。"},{"en":"The phrase describes the physical support point of a carried object.","zh":"這個短語描述被搬物件的實際支撐點。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":5},{"front":"a slow and expensive method","meaning":"緩慢而昂貴的方法","examples":[{"en":"Carrying goods by hand was a slow and expensive method of business.","zh":"以人手搬運貨物是一種緩慢而昂貴的作業方式。"},{"en":"A slow and expensive method is a way of doing something that takes time and costs a lot.","zh":"a slow and expensive method 指做某事既花時間又成本高的方法。"},{"en":"Printing every worksheet at home can be a slow and expensive method for a teacher.","zh":"老師在家列印每份工作紙可能是緩慢而昂貴的方法。"},{"en":"If transport is slow and expensive, goods become harder to sell cheaply.","zh":"如果運輸緩慢而昂貴，貨物就更難便宜出售。"},{"en":"The phrase explains why people look for better systems.","zh":"這個短語解釋為何人們尋找更好系統。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":5},{"front":"method of business","meaning":"經營方式；作業方式","examples":[{"en":"This was a slow and expensive method of business.","zh":"這是一種緩慢而昂貴的經營方式。"},{"en":"A method of business is the way commercial work is organised or carried out.","zh":"method of business 是商業工作被組織或執行的方式。"},{"en":"Online ordering is now a common method of business for small shops.","zh":"網上訂購現在是小店常見的經營方式。"},{"en":"If a method of business is inefficient, customers and merchants both lose time.","zh":"如果一種作業方式效率低，顧客和商人都會浪費時間。"},{"en":"The phrase focuses on how business is done in practice.","zh":"這個短語重點在於商業實際如何進行。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":6},{"front":"up to the eighteenth century","meaning":"直到18世紀","examples":[{"en":"Up to the eighteenth century, river work was seen favourably.","zh":"直到18世紀，河上工作仍被正面看待。"},{"en":"Up to the eighteenth century means until the period of the 1700s.","zh":"up to the eighteenth century 指直到1700年代。"},{"en":"Up to the eighteenth century, many messages still travelled slowly by horse or ship.","zh":"直到18世紀，許多訊息仍由馬匹或船隻緩慢傳送。"},{"en":"If attitudes stayed positive up to the eighteenth century, the change came later.","zh":"如果態度直到18世紀仍然正面，轉變就是後來才出現。"},{"en":"The phrase sets a historical limit in time.","zh":"這個短語設定歷史時間上的界線。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":6},{"front":"be seen in a favourable light","meaning":"被正面看待","examples":[{"en":"River work was seen in a generally favourable light.","zh":"河上工作一般被正面看待。"},{"en":"To be seen in a favourable light means to be viewed positively or with approval.","zh":"be seen in a favourable light 指被以正面或認可的方式看待。"},{"en":"Volunteer work is often seen in a favourable light by universities and employers.","zh":"義工服務常被大學和僱主正面看待。"},{"en":"If a job is seen in a favourable light, people respect those who do it.","zh":"如果一份工作被正面看待，人們就會尊重從事該工作的人。"},{"en":"The phrase describes positive public opinion.","zh":"這個短語描述正面的公眾看法。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":6},{"front":"writing in the fourteenth century","meaning":"在14世紀寫作時","examples":[{"en":"Langland, writing in the fourteenth century, described river workers as prosperous.","zh":"Langland 在14世紀寫作時，把河上工人描述為富裕。"},{"en":"Writing in the fourteenth century means producing work during the 1300s.","zh":"writing in the fourteenth century 指在1300年代創作作品。"},{"en":"A poet writing in the fourteenth century used language very different from modern English.","zh":"在14世紀寫作的詩人使用的語言與現代英語很不同。"},{"en":"If Langland was writing in the fourteenth century, his view reflects an earlier period.","zh":"如果 Langland 是在14世紀寫作，他的看法就反映較早時期。"},{"en":"The phrase locates an author’s work in historical time.","zh":"這個短語把作者作品放在歷史時間中。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":6},{"front":"river merchandise","meaning":"河上貨物","examples":[{"en":"Labourers working on river merchandise were relatively prosperous.","zh":"處理河上貨物的勞工相對富裕。"},{"en":"River merchandise means goods transported, loaded or unloaded through the river trade.","zh":"river merchandise 指透過河上貿易運送、裝載或卸下的貨物。"},{"en":"Porters handled river merchandise such as barrels, cloth and food supplies.","zh":"搬運工處理木桶、布料和食物供應等河上貨物。"},{"en":"If river merchandise increased, more workers were needed at the quays.","zh":"如果河上貨物增加，碼頭就需要更多工人。"},{"en":"The phrase connects goods with river-based commerce.","zh":"這個短語把貨物與河流商業連繫起來。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":6},{"front":"relatively prosperous","meaning":"相對富裕的","examples":[{"en":"River labourers were relatively prosperous in Langland’s view.","zh":"在 Langland 看來，河上勞工相對富裕。"},{"en":"Relatively prosperous means fairly well-off compared with other people or groups.","zh":"relatively prosperous 指與其他人或群體相比算是較富足。"},{"en":"A small shop may be relatively prosperous if neighbouring shops are struggling.","zh":"如果附近商店都在掙扎，一間小店可能算相對富裕。"},{"en":"If river workers earned steady money, they could seem relatively prosperous beside poorer labourers.","zh":"如果河上工人有穩定收入，與較貧困勞工相比就可能顯得相對富裕。"},{"en":"The phrase shows comparison, not absolute wealth.","zh":"這個短語顯示比較，而不是絕對富有。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":6},{"front":"porters","meaning":"搬運工人","examples":[{"en":"The porters of the seventeenth and early eighteenth centuries enjoyed high status.","zh":"17世紀和18世紀初的搬運工人享有高地位。"},{"en":"Porters are workers who carry goods, luggage or heavy loads.","zh":"porters 是搬運貨物、行李或重物的工人。"},{"en":"At a hotel, porters help guests move bags to their rooms.","zh":"在酒店，搬運工人幫客人把行李送到房間。"},{"en":"If porters handle valuable trade goods, their work can become important and respected.","zh":"如果搬運工人處理有價值的貿易貨物，他們的工作可以變得重要並受尊重。"},{"en":"The word refers to carriers, not gatekeepers here.","zh":"這個字在此指搬運者，而不是門衛。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":6},{"front":"if anything","meaning":"如果要說的話；甚至可以說","examples":[{"en":"The porters were, if anything, aristocrats of labour.","zh":"這些搬運工人如果要說的話，甚至可以說是勞工中的貴族。"},{"en":"If anything is used to strengthen a point by saying the truth is even more different from what people may expect.","zh":"if anything 用來加強某點，表示真相甚至比人們預期的更不同。"},{"en":"The lesson was not too easy; if anything, it was too difficult for beginners.","zh":"這堂課不是太容易；如果要說的話，對初學者來說是太難。"},{"en":"If people thought porters had low status, “if anything” corrects that idea strongly.","zh":"如果人們以為搬運工地位低，if anything 這個短語就有力地糾正這想法。"},{"en":"The phrase often means “actually, rather” or “if we must judge”.","zh":"這個短語常解作「其實反而」或「如果必須判斷的話」。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":6},{"front":"aristocrats of labour","meaning":"勞工中的貴族","examples":[{"en":"The porters were described as aristocrats of labour.","zh":"搬運工人被描述為勞工中的貴族。"},{"en":"Aristocrats of labour means workers who held unusually high status among labourers.","zh":"aristocrats of labour 指在勞工中地位異常高的工人。"},{"en":"Skilled technicians in a factory may be treated like aristocrats of labour if others depend on them.","zh":"如果工廠中其他人依賴熟練技術員，他們可能被視為勞工中的貴族。"},{"en":"If porters earned respect and good pay, people might call them aristocrats of labour.","zh":"如果搬運工人得到尊重和良好工資，人們可能稱他們為勞工中的貴族。"},{"en":"The phrase is metaphorical, comparing respected workers to nobles.","zh":"這個短語是比喻，把受尊重的工人比作貴族。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":6},{"front":"enjoy high status","meaning":"享有高地位","examples":[{"en":"Porters enjoyed high status in the seventeenth and early eighteenth centuries.","zh":"搬運工人在17世紀和18世紀初享有高地位。"},{"en":"To enjoy high status means to be respected and valued by others.","zh":"enjoy high status 指受到他人尊重和重視。"},{"en":"Doctors often enjoy high status because their work requires long training and saves lives.","zh":"醫生常享有高地位，因為他們的工作需要長期訓練並能拯救生命。"},{"en":"If a group enjoys high status, its members may have better pay and stronger respect.","zh":"如果某群體享有高地位，其成員可能有更好收入和更強尊重。"},{"en":"The phrase describes social position, not personal happiness only.","zh":"這個短語描述社會地位，而不只是個人快樂。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":6},{"front":"a marked change in attitude","meaning":"態度上的明顯轉變","examples":[{"en":"There was a marked change in attitude towards river work.","zh":"人們對河上工作的態度出現明顯轉變。"},{"en":"A marked change in attitude is a clear and noticeable shift in how people think or feel.","zh":"a marked change in attitude 指人們想法或感受上清楚而明顯的轉變。"},{"en":"There was a marked change in attitude towards online learning after schools used it successfully.","zh":"學校成功使用網上學習後，人們對它的態度出現明顯轉變。"},{"en":"If a job becomes associated with poverty or crime, a marked change in attitude may occur.","zh":"如果一份工作開始與貧窮或罪案相關，人們的態度可能出現明顯轉變。"},{"en":"The phrase highlights a visible change in public opinion.","zh":"這個短語突出公眾看法上的可見改變。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":7},{"front":"in part because","meaning":"部分原因是","examples":[{"en":"This change occurred in part because of the East End’s reputation.","zh":"這種轉變部分原因是倫敦東區的名聲。"},{"en":"In part because means partly for that reason, but not only for that reason.","zh":"in part because 指部分是因為該原因，但不只是因為它。"},{"en":"Students improved in part because the teacher gave clearer feedback.","zh":"學生有進步，部分原因是老師給了更清楚的回饋。"},{"en":"If an area is disliked in part because of crime reports, other social causes may also matter.","zh":"如果某區部分因罪案報道而不受歡迎，其他社會原因也可能重要。"},{"en":"The phrase introduces one cause among several possible causes.","zh":"這個短語引出多個可能原因中的其中一個。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":7},{"front":"the working river","meaning":"作為工作場所的河流","examples":[{"en":"The working river was within the region of the East End.","zh":"作為工作場所的河流位於倫敦東區一帶。"},{"en":"The working river means the part of the river used for labour, trade and industry.","zh":"the working river 指用於勞動、貿易和工業的河流部分。"},{"en":"A tourist may see a pretty river, while workers experience it as a working river.","zh":"遊客可能看見美麗河景，而工人則把它經驗為工作河流。"},{"en":"If a river is a working river, boats, cranes and warehouses shape daily life there.","zh":"如果一條河是工作場所，船隻、起重機和倉庫就會塑造那裏的日常生活。"},{"en":"The phrase contrasts work and industry with leisure or scenery.","zh":"這個短語把工作和工業與休閒或風景作對比。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":7},{"front":"the East End of London","meaning":"倫敦東區","examples":[{"en":"The working river was connected with the East End of London.","zh":"作為工作場所的河流與倫敦東區相關。"},{"en":"The East End of London is the eastern part of London, historically linked with docks, workers and immigration.","zh":"the East End of London 是倫敦東部，歷史上與碼頭、工人和移民相關。"},{"en":"A history walk in the East End of London may pass old markets and dock areas.","zh":"倫敦東區的歷史導賞可能經過舊市場和碼頭區。"},{"en":"If river work was tied to the East End, the area’s reputation affected how people saw the jobs.","zh":"如果河上工作與東區相連，該區名聲就會影響人們如何看待這些工作。"},{"en":"The phrase names a socially and historically important London district.","zh":"這個短語指出倫敦一個具社會和歷史重要性的地區。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":7},{"front":"acquire an unenviable reputation","meaning":"得到不值得羨慕的名聲","examples":[{"en":"The East End acquired an unenviable reputation.","zh":"倫敦東區得到不值得羨慕的名聲。"},{"en":"To acquire an unenviable reputation means to become known for something negative or undesirable.","zh":"acquire an unenviable reputation 指因負面或不受歡迎的事而出名。"},{"en":"A restaurant may acquire an unenviable reputation if customers often complain about dirty tables.","zh":"如果顧客常投訴餐桌骯髒，餐廳可能得到不值得羨慕的名聲。"},{"en":"If an area acquires an unenviable reputation, outsiders may judge its residents unfairly.","zh":"如果一個地區得到負面名聲，外人可能不公平地判斷居民。"},{"en":"The phrase describes gaining a bad name over time.","zh":"這個短語描述隨時間獲得壞名聲。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":7},{"front":"dockside labour","meaning":"碼頭勞工","examples":[{"en":"Dockside labour became the least desirable form of work.","zh":"碼頭勞工成為最不受歡迎的工作形式。"},{"en":"Dockside labour is physical work done near docks, usually loading, unloading or moving goods.","zh":"dockside labour 是在碼頭附近進行的體力工作，通常包括裝卸或搬運貨物。"},{"en":"Dockside labour may involve carrying heavy cargo in difficult weather.","zh":"碼頭勞工可能要在惡劣天氣下搬運重貨。"},{"en":"If dockside labour is casual and dangerous, many people may see it as undesirable.","zh":"如果碼頭勞工是臨時且危險的工作，許多人可能會認為它不吸引。"},{"en":"The phrase refers to work beside ships and warehouses.","zh":"這個短語指船隻和倉庫旁的工作。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":7},{"front":"be considered to be","meaning":"被認為是……","examples":[{"en":"Dockside labour was considered to be disreputable.","zh":"碼頭勞工被認為是不體面的。"},{"en":"To be considered to be something means to be judged or regarded in that way.","zh":"be considered to be 某事，意思是被判斷或被視為那樣。"},{"en":"A school may be considered to be strict if students must follow many rules.","zh":"如果學生必須遵守很多規則，一間學校可能被認為是嚴格的。"},{"en":"If work is considered to be low-status, fewer people may choose it willingly.","zh":"如果一份工作被認為地位低，較少人會自願選擇它。"},{"en":"The phrase reports public judgement rather than proven fact.","zh":"這個短語報告公眾判斷，而不是已證實事實。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":7},{"front":"disreputable","meaning":"名聲差的；不體面的","examples":[{"en":"Dockside labour was considered disreputable.","zh":"碼頭勞工被認為名聲差、不體面。"},{"en":"Disreputable means having a bad reputation or not being considered socially respectable.","zh":"disreputable 指名聲不好或不被社會視為體面。"},{"en":"A disreputable business may cheat customers or ignore safety rules.","zh":"名聲差的商店可能欺騙顧客或忽視安全規則。"},{"en":"If a job becomes seen as disreputable, workers may suffer social prejudice.","zh":"如果一份工作被視為不體面，工人可能受到社會偏見。"},{"en":"The word describes public judgement about respectability.","zh":"這個字描述公眾對體面程度的判斷。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":7},{"front":"the least desirable form of work","meaning":"最不受歡迎的工作形式","examples":[{"en":"Dockside labour became the least desirable form of work.","zh":"碼頭勞工成為最不受歡迎的工作形式。"},{"en":"The least desirable form of work means the kind of job people least want to do.","zh":"the least desirable form of work 指人們最不想做的工作種類。"},{"en":"Cleaning dangerous waste may be the least desirable form of work in a factory.","zh":"在工廠中，清理危險廢物可能是最不受歡迎的工作形式。"},{"en":"If a job is poorly paid, unsafe and unstable, it may become the least desirable form of work.","zh":"如果一份工作薪酬低、不安全且不穩定，它可能成為最不受歡迎的工作形式。"},{"en":"The phrase ranks work by attractiveness and social value.","zh":"這個短語按吸引力和社會價值排列工作。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":7},{"front":"industrial community","meaning":"工業社群","examples":[{"en":"The first industrial community in England grew up around the Thames.","zh":"英格蘭第一個工業社群在泰晤士河周圍形成。"},{"en":"An industrial community is a group of people and businesses centred on factories, trade or heavy work.","zh":"industrial community 是以工廠、貿易或重體力工作為中心的人群和商業組合。"},{"en":"A town with shipyards, warehouses and workers’ housing can become an industrial community.","zh":"有造船廠、倉庫和工人住宅的城鎮可以成為工業社群。"},{"en":"If an industrial community grows near a river, transport and labour often develop together.","zh":"如果工業社群在河邊形成，交通和勞動通常會一起發展。"},{"en":"The phrase links people, work and place.","zh":"這個短語把人、工作和地方連繫起來。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":7},{"front":"grow up around","meaning":"在……周圍形成","examples":[{"en":"An industrial community grew up around the Thames.","zh":"一個工業社群在泰晤士河周圍形成。"},{"en":"To grow up around a place means to develop gradually in that area.","zh":"grow up around 某地，意思是在該地方周圍逐漸發展。"},{"en":"Small cafés may grow up around a new university campus.","zh":"新大學校園周圍可能逐漸形成小咖啡店。"},{"en":"If jobs grow up around a port, homes and shops soon follow.","zh":"如果工作在港口周圍形成，住宅和商店很快也會出現。"},{"en":"The phrase describes gradual development around a centre.","zh":"這個短語描述圍繞中心逐漸發展。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":8},{"front":"a host of","meaning":"大量；許多","examples":[{"en":"A host of river workers lived and worked near the Thames.","zh":"大量河上工人在泰晤士河附近生活和工作。"},{"en":"A host of means a large number of people or things.","zh":"a host of 指大量的人或事物。"},{"en":"A school festival may need a host of volunteers, teachers and parents.","zh":"學校節慶可能需要大量義工、老師和家長。"},{"en":"If a host of workers gather in one area, shops and services often grow nearby.","zh":"如果大量工人聚集在一個地區，商店和服務通常會在附近發展。"},{"en":"The phrase is used to show abundance.","zh":"這個短語用來顯示數量很多。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":8},{"front":"river workers","meaning":"河上工人","examples":[{"en":"River workers formed part of a large industrial community.","zh":"河上工人構成大型工業社群的一部分。"},{"en":"River workers are people whose jobs are done on, beside or because of a river.","zh":"river workers 是在河上、河邊或因河流而工作的人。"},{"en":"Boatmen, dockers, fishers and porters can all be river workers.","zh":"船工、碼頭工人、漁民和搬運工都可以是河上工人。"},{"en":"If river trade expands, river workers may find more employment.","zh":"如果河上貿易擴展，河上工人可能找到更多工作。"},{"en":"The phrase groups many different jobs connected with river life.","zh":"這個短語概括許多與河流生活相關的不同工作。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":8},{"front":"vast assembly of","meaning":"大量集合","examples":[{"en":"There was a vast assembly of ancillary trades near the river.","zh":"河邊有大量輔助行業集合。"},{"en":"A vast assembly of something means a very large collection or gathering of it.","zh":"vast assembly of 某物，指非常大量的集合或聚集。"},{"en":"A city market may contain a vast assembly of food stalls, repair shops and small traders.","zh":"城市市場可能包含大量食物攤檔、維修店和小商販。"},{"en":"If a vast assembly of trades forms near a port, the local economy becomes diverse.","zh":"如果大量行業在港口附近形成，本地經濟就會變得多元。"},{"en":"The phrase emphasises size and variety.","zh":"這個短語強調規模和多樣性。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":8},{"front":"ancillary trades","meaning":"輔助行業","examples":[{"en":"Ancillary trades supported the river economy.","zh":"輔助行業支撐河流經濟。"},{"en":"Ancillary trades are supporting businesses that help a main industry function.","zh":"ancillary trades 是幫助主要行業運作的支援性生意。"},{"en":"Around a hospital, ancillary trades may include pharmacies, cafés and cleaning services.","zh":"醫院附近的輔助行業可能包括藥房、咖啡店和清潔服務。"},{"en":"If river work grows, ancillary trades such as food selling and repair services grow too.","zh":"如果河上工作增長，食物售賣和維修服務等輔助行業也會增長。"},{"en":"The phrase refers to secondary but necessary economic activities.","zh":"這個短語指次要但必要的經濟活動。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":8},{"front":"tavern-keepers","meaning":"酒館經營者","examples":[{"en":"Tavern-keepers were part of the riverside economy.","zh":"酒館經營者是河邊經濟的一部分。"},{"en":"Tavern-keepers were people who ran taverns, places where customers drank, ate or stayed.","zh":"tavern-keepers 是經營酒館的人，酒館供顧客飲酒、進食或住宿。"},{"en":"Tavern-keepers near docks served sailors, porters and travellers.","zh":"碼頭附近的酒館經營者服務水手、搬運工和旅客。"},{"en":"If many workers gathered by the river, tavern-keepers could earn money from food and drink.","zh":"如果許多工人聚集在河邊，酒館經營者就能靠食物和飲品賺錢。"},{"en":"The word describes an old occupation connected with hospitality.","zh":"這個字描述與款待服務相關的舊職業。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":8},{"front":"laundresses","meaning":"洗衣婦","examples":[{"en":"Laundresses worked among the ancillary trades near the river.","zh":"洗衣婦在河邊輔助行業中工作。"},{"en":"Laundresses were women who washed clothes for payment.","zh":"laundresses 是收費洗衣的女性。"},{"en":"A laundress might clean shirts, sheets and work clothes for river workers.","zh":"洗衣婦可能為河上工人清洗襯衫、床單和工作服。"},{"en":"If many workers lived nearby, laundresses had steady demand for washing services.","zh":"如果附近住着許多工人，洗衣婦的洗衣服務就有穩定需求。"},{"en":"The word is historical and gendered, referring to female laundry workers.","zh":"這個字屬歷史用語並帶有性別含義，指女性洗衣工人。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":8},{"front":"food-sellers","meaning":"食物小販","examples":[{"en":"Food-sellers served the large riverside workforce.","zh":"食物小販服務龐大的河邊勞動人口。"},{"en":"Food-sellers are people who sell meals, snacks or ingredients.","zh":"food-sellers 是出售餐食、小食或食材的人。"},{"en":"Food-sellers outside a school may sell rice, noodles or drinks to students.","zh":"學校外的食物小販可能向學生出售飯、麵或飲品。"},{"en":"If thousands of workers gather in one area, food-sellers can do good business.","zh":"如果數以千計工人聚集在一個地區，食物小販就能有好生意。"},{"en":"The phrase names a practical service job.","zh":"這個短語指出一種實用服務工作。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":8},{"front":"street-hawkers","meaning":"街頭小販","examples":[{"en":"Street-hawkers were among the trades near the Thames.","zh":"街頭小販屬於泰晤士河附近的行業之一。"},{"en":"Street-hawkers are people who sell goods in streets, often from baskets, carts or small stalls.","zh":"street-hawkers 是在街上出售貨物的人，常用籃子、手推車或小攤檔。"},{"en":"Street-hawkers may sell fruit, snacks, newspapers or household items.","zh":"街頭小販可能售賣水果、小食、報紙或家用品。"},{"en":"If a riverside area is crowded, street-hawkers can find many customers.","zh":"如果河邊地區擠迫，街頭小販就能找到許多顧客。"},{"en":"The phrase describes informal public selling.","zh":"這個短語描述街頭非正式售賣。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":8},{"front":"marine store dealers","meaning":"船舶用品商；海事雜貨商","examples":[{"en":"Marine store dealers formed part of the riverside business world.","zh":"船舶用品商構成河邊商業世界的一部分。"},{"en":"Marine store dealers were traders who bought and sold goods connected with ships or docks.","zh":"marine store dealers 是買賣與船隻或碼頭有關貨物的商人。"},{"en":"A marine store dealer near a port might sell old rope, canvas or tools.","zh":"港口附近的船舶用品商可能出售舊繩索、帆布或工具。"},{"en":"If shipping activity was high, marine store dealers had more goods to buy and sell.","zh":"如果航運活動頻繁，船舶用品商就有更多貨物可買賣。"},{"en":"The phrase refers to a specialised business linked with maritime work.","zh":"這個短語指與海事工作相關的專門生意。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":8},{"front":"a workforce of many thousands","meaning":"數以千計的勞動人口","examples":[{"en":"A workforce of many thousands gathered near the river.","zh":"數以千計的勞動人口聚集在河邊。"},{"en":"A workforce of many thousands means a working population made up of several thousand people.","zh":"a workforce of many thousands 指由數千人組成的工作人口。"},{"en":"A large airport needs a workforce of many thousands to run flights, security and shops.","zh":"大型機場需要數以千計的勞動人口來運作航班、保安和商店。"},{"en":"If a workforce of many thousands gathers in a small area, housing and food demand rises.","zh":"如果數以千計的勞動人口聚集在細小地區，住屋和食物需求就會上升。"},{"en":"The phrase stresses the scale of labour.","zh":"這個短語強調勞動力規模。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":9},{"front":"congregate in","meaning":"聚集於……","examples":[{"en":"Thousands of workers congregated in a relatively small area.","zh":"數以千計工人聚集於相對細小的地區。"},{"en":"To congregate in a place means to gather there in large numbers.","zh":"congregate in 某地，意思是大量人聚集在那裏。"},{"en":"Students congregate in the playground after the final bell.","zh":"放學鐘響後，學生聚集於操場。"},{"en":"If workers congregate in one district, services and shops may grow around them.","zh":"如果工人聚集在一個地區，服務和商店可能在周圍發展。"},{"en":"The phrase describes people coming together in one location.","zh":"這個短語描述人們集中到一個地點。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":9},{"front":"a relatively small area","meaning":"相對細小的地區","examples":[{"en":"Many workers lived and worked in a relatively small area.","zh":"許多工人在相對細小的地區生活和工作。"},{"en":"A relatively small area is an area that is small compared with the number of people or activities in it.","zh":"a relatively small area 指與其中的人數或活動相比顯得細小的地方。"},{"en":"A school can feel crowded when many classes share a relatively small area.","zh":"當許多班級共用相對細小的地方，學校可能顯得擠迫。"},{"en":"If many trades operate in a relatively small area, streets become busy and noisy.","zh":"如果許多行業在相對細小的地區運作，街道就會變得繁忙嘈雜。"},{"en":"The phrase shows size through comparison.","zh":"這個短語透過比較顯示大小。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":9},{"front":"varieties of business","meaning":"各式各樣的生意","examples":[{"en":"More varieties of business could be observed by the riverside.","zh":"河邊可以看到更多各式各樣的生意。"},{"en":"Varieties of business means different types of commercial activity.","zh":"varieties of business 指不同類型的商業活動。"},{"en":"In a shopping street, varieties of business may include cafés, clinics and repair shops.","zh":"在購物街，各式各樣的生意可能包括咖啡店、診所和維修店。"},{"en":"If many workers gather, more varieties of business appear to serve their needs.","zh":"如果許多工人聚集，更多不同生意就會出現以服務他們的需要。"},{"en":"The phrase highlights economic diversity.","zh":"這個短語突出經濟多樣性。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":9},{"front":"be observed by the riverside","meaning":"可在河邊看到","examples":[{"en":"Many types of business could be observed by the riverside.","zh":"許多種類的生意可在河邊看到。"},{"en":"To be observed by the riverside means to be seen or noticed near the riverbank.","zh":"be observed by the riverside 指在河岸附近可被看見或注意到。"},{"en":"Tourists may observe cafés, boats and markets by the riverside.","zh":"遊客可在河邊看到咖啡店、船隻和市集。"},{"en":"If many trades can be observed by the riverside, the river is a busy economic centre.","zh":"如果許多行業可在河邊看到，這條河就是繁忙的經濟中心。"},{"en":"The phrase describes what is visible in a river area.","zh":"這個短語描述河邊地區可見的事物。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":9},{"front":"with the possible exception of","meaning":"可能除了……之外","examples":[{"en":"The East End was very densely inhabited, with the possible exception of Seven Dials.","zh":"倫敦東區人口非常密集，可能除了 Seven Dials 之外。"},{"en":"With the possible exception of means except perhaps for one case that may be different.","zh":"with the possible exception of 指也許除了一個可能不同的個案之外。"},{"en":"Most students arrived early, with the possible exception of two who lived far away.","zh":"大多數學生都早到，可能除了兩個住得遠的學生之外。"},{"en":"If one district is the most crowded, with the possible exception of another, the comparison is cautious.","zh":"如果某區是最擠迫的，可能除另一區外，這種比較就是謹慎的。"},{"en":"The phrase allows uncertainty while making a general claim.","zh":"這個短語在作一般陳述時容許不確定性。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":9},{"front":"Seven Dials","meaning":"Seven Dials 地區","examples":[{"en":"Seven Dials was another densely inhabited area of London.","zh":"Seven Dials 是倫敦另一個人口密集地區。"},{"en":"Seven Dials is a London district mentioned as a possible comparison with the East End.","zh":"Seven Dials 是倫敦一個地區，在文中被用來與東區可能作比較。"},{"en":"A historian may compare Seven Dials with riverside districts to study urban crowding.","zh":"歷史學家可能把 Seven Dials 與河邊地區比較，以研究城市擠迫。"},{"en":"If Seven Dials was also crowded, it helps show how extreme the East End’s density was.","zh":"如果 Seven Dials 也很擠迫，它有助顯示東區人口密度有多極端。"},{"en":"The phrase names a specific London area.","zh":"這個短語指出倫敦一個特定地區。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":9},{"front":"intensively inhabited","meaning":"人口高度密集的","examples":[{"en":"The East End was the most intensively inhabited region of London.","zh":"倫敦東區是倫敦人口最高度密集的地區。"},{"en":"Intensively inhabited means very densely lived in by many people.","zh":"intensively inhabited 指有大量人口密集居住。"},{"en":"A high-rise district can be intensively inhabited if thousands of families live in a small area.","zh":"如果數以千計家庭住在一個小區，高樓住宅區就可說是人口高度密集。"},{"en":"If a neighbourhood is intensively inhabited, disease, noise and housing pressure may increase.","zh":"如果社區人口高度密集，疾病、噪音和住屋壓力可能增加。"},{"en":"The phrase describes population density, not emotional closeness.","zh":"這個短語描述人口密度，而不是情感親密。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":9},{"front":"a world apart","meaning":"截然不同的世界","examples":[{"en":"The riverside community was a world apart.","zh":"河邊社群是一個截然不同的世界。"},{"en":"A world apart means very different from other places, groups or ways of life.","zh":"a world apart 指與其他地方、群體或生活方式非常不同。"},{"en":"A rural village can feel a world apart from a busy financial district.","zh":"鄉村小村莊可能感覺與繁忙金融區是截然不同的世界。"},{"en":"If river workers had their own speech and rules, their community seemed a world apart.","zh":"如果河上工人有自己的語言和規矩，他們的社群就像截然不同的世界。"},{"en":"The phrase stresses strong social or cultural separation.","zh":"這個短語強調強烈的社會或文化分隔。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":9},{"front":"its own language and laws","meaning":"自己的語言和規矩","examples":[{"en":"The river world had its own language and laws.","zh":"河流世界有自己的語言和規矩。"},{"en":"Its own language and laws means a group has special words, customs and rules that outsiders may not know.","zh":"its own language and laws 指一個群體有外人未必知道的特殊詞語、習俗和規則。"},{"en":"A hospital has its own language and laws, with medical terms and strict routines.","zh":"醫院有自己的語言和規矩，包括醫學術語和嚴格流程。"},{"en":"If workers develop their own language and laws, they create a strong group identity.","zh":"如果工人發展出自己的語言和規矩，他們就創造出強烈群體身份。"},{"en":"The phrase shows cultural independence within a wider society.","zh":"這個短語顯示大社會之內的文化獨立性。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":9},{"front":"opium dens","meaning":"鴉片煙館","examples":[{"en":"Sailors were found in the opium dens of Limehouse.","zh":"水手出現在 Limehouse 的鴉片煙館中。"},{"en":"Opium dens were places where people gathered to smoke opium.","zh":"opium dens 是人們聚集吸食鴉片的地方。"},{"en":"Nineteenth-century writers often described opium dens as hidden and dangerous spaces.","zh":"19世紀作家常把鴉片煙館描述為隱蔽而危險的空間。"},{"en":"If sailors spent time in opium dens, outsiders might view the riverside world as morally suspect.","zh":"如果水手流連鴉片煙館，外人可能把河邊世界視為道德可疑。"},{"en":"The phrase carries a strong historical association with vice and urban poverty.","zh":"這個短語帶有與罪惡和城市貧困相關的強烈歷史聯想。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":10},{"front":"Limehouse","meaning":"Limehouse 地區","examples":[{"en":"Limehouse was associated with sailors and opium dens.","zh":"Limehouse 與水手和鴉片煙館相關。"},{"en":"Limehouse is an area of East London historically linked with docks and riverside life.","zh":"Limehouse 是倫敦東部一個地區，歷史上與碼頭和河邊生活相關。"},{"en":"A history tour of Limehouse may discuss sailors, warehouses and immigrant communities.","zh":"Limehouse 的歷史導賞可能討論水手、倉庫和移民社群。"},{"en":"If Limehouse was linked with opium dens, it helped shape the darker image of the docklands.","zh":"如果 Limehouse 與鴉片煙館相連，它就塑造了碼頭區較陰暗的形象。"},{"en":"The phrase names a specific riverside district.","zh":"這個短語指出一個特定河邊地區。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":10},{"front":"smugglers","meaning":"走私者","examples":[{"en":"Smugglers operated on the malarial flats of the estuary.","zh":"走私者在河口有瘧疾風險的平地活動。"},{"en":"Smugglers are people who secretly move goods illegally across borders or controlled areas.","zh":"smugglers 是秘密非法運送貨物穿越邊境或受管制地區的人。"},{"en":"Smugglers may hide goods in boats, trucks or luggage to avoid taxes or laws.","zh":"走私者可能把貨物藏在船、貨車或行李中，以逃避稅項或法律。"},{"en":"If a river has hidden landing places, smugglers can use them to escape officials.","zh":"如果河流有隱蔽登岸點，走私者可以利用它們避開官員。"},{"en":"The word is connected with illegal trade.","zh":"這個字與非法貿易有關。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":10},{"front":"malarial flats","meaning":"有瘧疾風險的平地","examples":[{"en":"The smugglers worked on the malarial flats of the estuary.","zh":"走私者在河口有瘧疾風險的平地活動。"},{"en":"Malarial flats are low, wet flatlands associated with malaria risk.","zh":"malarial flats 是與瘧疾風險相關的低窪潮濕平地。"},{"en":"Workers avoided malarial flats because mosquitoes and stagnant water could spread disease.","zh":"工人避開有瘧疾風險的平地，因為蚊和積水可能傳播疾病。"},{"en":"If smugglers used malarial flats, the danger of disease made the area even more threatening.","zh":"如果走私者使用這些平地，疾病危險就令該區更具威脅。"},{"en":"The phrase combines geography with health risk.","zh":"這個短語結合地理和健康風險。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":10},{"front":"estuary","meaning":"河口","examples":[{"en":"The estuary was part of the river environment.","zh":"河口是河流環境的一部分。"},{"en":"An estuary is the wide area where a river meets the sea.","zh":"estuary 是河流與大海相遇的寬闊地區。"},{"en":"Birds often feed in an estuary because river water and seawater mix there.","zh":"鳥類常在河口覓食，因為河水和海水在那裏混合。"},{"en":"If goods move through an estuary, ships can connect inland trade with overseas trade.","zh":"如果貨物經河口運送，船隻就能把內陸貿易與海外貿易連接起來。"},{"en":"The word describes a river mouth shaped by tides.","zh":"這個字描述受潮汐影響的河口地帶。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":10},{"front":"civilised society","meaning":"文明社會","examples":[{"en":"The river workers were described as outside civilised society.","zh":"河上工人被描述為在文明社會之外。"},{"en":"Civilised society means the respectable, orderly part of society as judged by mainstream standards.","zh":"civilised society 指按主流標準被視為體面、有秩序的社會部分。"},{"en":"In old newspapers, poor districts were sometimes unfairly described as outside civilised society.","zh":"在舊報章中，貧困地區有時被不公平地描述為文明社會之外。"},{"en":"If a group is labelled outside civilised society, prejudice against it may grow.","zh":"如果某群體被標籤為在文明社會之外，對他們的偏見可能增加。"},{"en":"The phrase reflects social judgement and should be read critically.","zh":"這個短語反映社會判斷，應批判地閱讀。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":10},{"front":"the alien world of the river","meaning":"河流那個陌生世界","examples":[{"en":"The alien world of the river had entered the workers.","zh":"河流那個陌生世界已進入工人身上。"},{"en":"The alien world of the river means the strange and separate culture surrounding river life.","zh":"the alien world of the river 指圍繞河流生活的陌生而分隔的文化。"},{"en":"To outsiders, a busy dock with its own slang may seem like an alien world.","zh":"對外人而言，一個有自己俚語的繁忙碼頭可能像陌生世界。"},{"en":"If workers live inside the alien world of the river for years, its habits shape their identity.","zh":"如果工人多年生活在河流那個陌生世界中，其習慣就會塑造他們的身份。"},{"en":"The phrase presents river life as unfamiliar and socially separate.","zh":"這個短語把河流生活呈現為陌生且與社會分隔。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":10},{"front":"alienation","meaning":"疏離感；異化","examples":[{"en":"Alienation was expressed in the slang of the docks.","zh":"疏離感透過碼頭俚語表達出來。"},{"en":"Alienation is a feeling of being separate, distant or not belonging.","zh":"alienation 是感到分隔、疏遠或不屬於某群體的感覺。"},{"en":"A new student may feel alienation if classmates ignore them every day.","zh":"如果同學每天忽視新學生，他可能感到疏離。"},{"en":"If workers feel alienation from mainstream society, they may develop their own speech and customs.","zh":"如果工人感到與主流社會疏離，他們可能發展自己的說話方式和習俗。"},{"en":"The word describes social or emotional distance.","zh":"這個字描述社會或情感上的距離。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":10},{"front":"be expressed in","meaning":"透過……表達","examples":[{"en":"Alienation was expressed in the slang of the docks.","zh":"疏離感透過碼頭俚語表達出來。"},{"en":"To be expressed in something means to be shown through that form.","zh":"be expressed in 某形式，意思是透過該形式展示出來。"},{"en":"A community’s pride can be expressed in its festivals and songs.","zh":"社區自豪感可以透過節日和歌曲表達。"},{"en":"If anger is expressed in graffiti, the writing becomes a public sign of frustration.","zh":"如果憤怒透過塗鴉表達，文字就成為挫折感的公共標誌。"},{"en":"The phrase links an inner feeling with an outward form.","zh":"這個短語把內在感受與外在形式連繫起來。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":10},{"front":"the slang of the docks","meaning":"碼頭俚語","examples":[{"en":"The slang of the docks reflected the alien world of the river.","zh":"碼頭俚語反映河流那個陌生世界。"},{"en":"The slang of the docks means informal words and expressions used by dock workers.","zh":"the slang of the docks 指碼頭工人使用的非正式詞語和表達。"},{"en":"New workers might struggle to understand the slang of the docks at first.","zh":"新工人起初可能難以理解碼頭俚語。"},{"en":"If the slang of the docks differed from ordinary speech, it helped create group identity.","zh":"如果碼頭俚語不同於普通說話，它就有助創造群體身份。"},{"en":"The phrase connects language with a workplace community.","zh":"這個短語把語言與工作場所社群連繫起來。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":10},{"front":"amount to","meaning":"等同於；實質上是","examples":[{"en":"The slang essentially amounted to backslang.","zh":"這種俚語實質上等同於倒讀俚語。"},{"en":"To amount to something means to be equal to it in meaning, effect or result.","zh":"amount to 某事，意思是在意思、效果或結果上等同於它。"},{"en":"Ignoring a student’s question may amount to refusing help.","zh":"忽視學生問題可能等同於拒絕幫助。"},{"en":"If a policy amounts to a ban, people experience it as a ban even if the word is not used.","zh":"如果一項政策實質上等同於禁令，即使沒有使用禁令一詞，人們也會把它當禁令經驗。"},{"en":"The phrase explains what something really is in practice.","zh":"這個短語解釋某事在實際上到底是甚麼。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":11},{"front":"backslang","meaning":"倒讀俚語","examples":[{"en":"Backslang involves the reversal of ordinary words.","zh":"倒讀俚語涉及普通詞語的倒轉。"},{"en":"Backslang is a type of slang made by reversing words or changing their order.","zh":"backslang 是一種透過倒轉詞語或改變順序形成的俚語。"},{"en":"Children sometimes create backslang to hide meaning from adults.","zh":"孩子有時創造倒讀俚語，以向成年人隱藏意思。"},{"en":"If workers use backslang, outsiders may find their speech difficult to understand.","zh":"如果工人使用倒讀俚語，外人可能覺得他們的說話難以理解。"},{"en":"The word describes a secretive or playful language practice.","zh":"這個字描述一種秘密或玩味性的語言做法。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":11},{"front":"the reversal of ordinary words","meaning":"普通詞語的倒轉","examples":[{"en":"Backslang was based on the reversal of ordinary words.","zh":"倒讀俚語建基於普通詞語的倒轉。"},{"en":"The reversal of ordinary words means turning normal words around or changing their order.","zh":"the reversal of ordinary words 指把正常詞語倒轉或改變其順序。"},{"en":"A secret code may use the reversal of ordinary words to hide meaning.","zh":"秘密代碼可能使用普通詞語的倒轉來隱藏意思。"},{"en":"If speech uses the reversal of ordinary words, listeners outside the group may be confused.","zh":"如果說話使用普通詞語的倒轉，群體外的聽者可能感到困惑。"},{"en":"The phrase explains the mechanism behind backslang.","zh":"這個短語解釋倒讀俚語背後的機制。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":11},{"front":"formulation of","meaning":"……的形成","examples":[{"en":"Backslang helped in the formulation of Cockney rhyming slang.","zh":"倒讀俚語有助倫敦東區押韻俚語的形成。"},{"en":"The formulation of something means the creation or development of it in a clear form.","zh":"formulation of 某物，指把它創造或發展成清楚形式。"},{"en":"Teachers help in the formulation of school rules by discussing students’ needs.","zh":"老師透過討論學生需要，協助校規的形成。"},{"en":"If one slang system helps the formulation of another, language develops through contact and creativity.","zh":"如果一套俚語系統有助另一套俚語形成，語言就透過接觸和創意發展。"},{"en":"The phrase is formal and often used for ideas, plans or systems.","zh":"這個短語較正式，常用於想法、計劃或系統。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":11},{"front":"Cockney rhyming slang","meaning":"倫敦東區押韻俚語","examples":[{"en":"Cockney rhyming slang was influenced by dockside backslang.","zh":"倫敦東區押韻俚語受到碼頭倒讀俚語影響。"},{"en":"Cockney rhyming slang is a London slang system that replaces a word with a rhyming phrase.","zh":"Cockney rhyming slang 是一種倫敦俚語系統，用押韻短語取代某個字。"},{"en":"In Cockney rhyming slang, a common word may be hidden behind a playful rhyme.","zh":"在倫敦東區押韻俚語中，常見字可能被藏在有趣押韻短語後面。"},{"en":"If dockside language shaped Cockney rhyming slang, river workers influenced London speech.","zh":"如果碼頭語言塑造了倫敦東區押韻俚語，河上工人就影響了倫敦語言。"},{"en":"The phrase names a distinctive form of London working-class language.","zh":"這個短語指倫敦工人階級語言的一種獨特形式。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":11},{"front":"vocabulary of Londoners","meaning":"倫敦人的詞彙","examples":[{"en":"The vocabulary of Londoners was affected by life on the Thames.","zh":"倫敦人的詞彙受到泰晤士河生活影響。"},{"en":"The vocabulary of Londoners means the words and expressions used by people in London.","zh":"vocabulary of Londoners 指倫敦人使用的詞語和表達。"},{"en":"The vocabulary of Londoners includes terms from markets, transport and local history.","zh":"倫敦人的詞彙包括來自市集、交通和本地歷史的用語。"},{"en":"If river workers created new slang, the vocabulary of Londoners could change over time.","zh":"如果河上工人創造新俚語，倫敦人的詞彙就可能隨時間改變。"},{"en":"The phrase connects language with a city’s people.","zh":"這個短語把語言與城市居民連繫起來。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":11},{"front":"be directly affected by","meaning":"直接受到……影響","examples":[{"en":"The vocabulary of Londoners was directly affected by river life.","zh":"倫敦人的詞彙直接受到河流生活影響。"},{"en":"To be directly affected by something means to be changed by it in a clear and immediate way.","zh":"be directly affected by 某事，意思是被它清楚而直接地改變。"},{"en":"A shop is directly affected by road closures if customers cannot reach it.","zh":"如果顧客無法到達店舖，道路封閉就直接影響該店。"},{"en":"If city speech is directly affected by workers’ slang, everyday language changes from below.","zh":"如果城市語言直接受到工人俚語影響，日常語言就由基層改變。"},{"en":"The phrase shows a strong and clear influence.","zh":"這個短語顯示強而明確的影響。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":11},{"front":"the life of the Thames","meaning":"泰晤士河上的生活","examples":[{"en":"The life of the Thames shaped London speech.","zh":"泰晤士河上的生活塑造了倫敦語言。"},{"en":"The life of the Thames means the work, trade, people and culture connected with the river.","zh":"the life of the Thames 指與這條河相關的工作、貿易、人群和文化。"},{"en":"The life of a market can shape the words used by sellers and customers.","zh":"市集生活可以塑造賣家和顧客使用的詞語。"},{"en":"If the life of the Thames was busy and varied, it could create many specialised terms.","zh":"如果泰晤士河上的生活繁忙而多樣，它就可能創造許多專門用語。"},{"en":"The phrase treats the river as a living social world.","zh":"這個短語把河流視為一個活生生的社會世界。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":11},{"front":"nineteenth-century press","meaning":"19世紀報章","examples":[{"en":"The nineteenth-century press reported on dock labour.","zh":"19世紀報章報道碼頭勞工。"},{"en":"The nineteenth-century press means newspapers and magazines published during the 1800s.","zh":"nineteenth-century press 指1800年代出版的報紙和雜誌。"},{"en":"The nineteenth-century press often described poverty, crime and city life in detail.","zh":"19世紀報章常詳細描述貧窮、罪案和城市生活。"},{"en":"If the nineteenth-century press focused on dock labour, it shaped public opinion about workers.","zh":"如果19世紀報章關注碼頭勞工，它就塑造了公眾對工人的看法。"},{"en":"The phrase refers to media from a specific historical period.","zh":"這個短語指特定歷史時期的媒體。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":11},{"front":"reveal a heterogeneous world","meaning":"揭示一個多元混雜的世界","examples":[{"en":"The reports reveal a heterogeneous world of dock labour.","zh":"這些報道揭示碼頭勞工一個多元混雜的世界。"},{"en":"To reveal a heterogeneous world means to show a mixed and varied social environment.","zh":"reveal a heterogeneous world 指展示一個混合而多樣的社會環境。"},{"en":"A school survey may reveal a heterogeneous world of languages, religions and family backgrounds.","zh":"學校調查可能揭示一個由語言、宗教和家庭背景組成的多元世界。"},{"en":"If dock reports reveal a heterogeneous world, dock labour was not made up of one simple group.","zh":"如果碼頭報道揭示多元混雜的世界，碼頭勞工就不是單一簡單群體。"},{"en":"The phrase shows hidden variety.","zh":"這個短語顯示隱藏的多樣性。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":11},{"front":"heterogeneous","meaning":"多元混雜的","examples":[{"en":"Dock labour was socially heterogeneous.","zh":"碼頭勞工在社會組成上是多元混雜的。"},{"en":"Heterogeneous means made up of different types, backgrounds or elements.","zh":"heterogeneous 指由不同類型、背景或元素組成。"},{"en":"A heterogeneous class may include students of different ages, languages and learning levels.","zh":"多元混雜的班級可能包括不同年齡、語言和學習水平的學生。"},{"en":"If a workforce is heterogeneous, workers may have very different life stories.","zh":"如果勞動人口是多元混雜的，工人可能有非常不同的人生故事。"},{"en":"The word means mixed rather than uniform.","zh":"這個字意思是混合，而不是一致。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":12},{"front":"dock labour","meaning":"碼頭勞工","examples":[{"en":"Dock labour included both permanent and casual workers.","zh":"碼頭勞工包括長工和臨時工。"},{"en":"Dock labour is work done at docks, especially loading, unloading and moving cargo.","zh":"dock labour 是在碼頭進行的工作，尤其是裝卸和搬運貨物。"},{"en":"Dock labour can be physically hard because workers handle heavy goods near ships.","zh":"碼頭勞工可能很辛苦，因為工人在船附近處理重貨。"},{"en":"If dock labour is divided into permanent and casual work, workers’ income stability differs.","zh":"如果碼頭勞工分為長工和臨時工，工人的收入穩定性就不同。"},{"en":"The phrase refers to port work rather than office work.","zh":"這個短語指港口工作，而不是辦公室工作。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":12},{"front":"crowds of casuals","meaning":"大批臨時工","examples":[{"en":"Crowds of casuals waited for work at the dock gates.","zh":"大批臨時工在碼頭閘口等候工作。"},{"en":"Crowds of casuals means large groups of temporary workers without guaranteed jobs.","zh":"crowds of casuals 指沒有固定工作保障的大群臨時工。"},{"en":"Outside a stadium, crowds of casuals may wait for one-day cleaning or security work.","zh":"在體育場外，大批臨時工可能等候一天清潔或保安工作。"},{"en":"If crowds of casuals compete for limited jobs, many people go home unpaid.","zh":"如果大批臨時工競爭有限工作，許多人會沒有收入地回家。"},{"en":"The phrase shows both labour insecurity and large numbers.","zh":"這個短語同時顯示工作不穩定和人數眾多。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":12},{"front":"wait for work","meaning":"等候工作","examples":[{"en":"Casual workers waited for work at the dock gates.","zh":"臨時工在碼頭閘口等候工作。"},{"en":"To wait for work means to stand by hoping to be hired.","zh":"wait for work 指在某處等候，希望被僱用。"},{"en":"Day labourers may wait for work outside a market early in the morning.","zh":"散工可能清晨在市場外等候工作。"},{"en":"If people wait for work but are not chosen, they earn nothing that day.","zh":"如果人們等候工作但沒有被選中，那天就沒有收入。"},{"en":"The phrase describes insecure employment.","zh":"這個短語描述不穩定就業。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":12},{"front":"dock gates","meaning":"碼頭閘口","examples":[{"en":"Casual workers gathered at the dock gates in the morning.","zh":"臨時工早上聚集在碼頭閘口。"},{"en":"Dock gates are the entrances to dock areas where ships are loaded and unloaded.","zh":"dock gates 是進入碼頭區的入口，碼頭區用來裝卸船隻。"},{"en":"Workers may line up at dock gates before a shift begins.","zh":"工人可能在班次開始前於碼頭閘口排隊。"},{"en":"If hiring happens at dock gates, workers must appear there early to compete.","zh":"如果招聘在碼頭閘口進行，工人就必須早到競爭。"},{"en":"The phrase marks a physical entrance and a labour gathering point.","zh":"這個短語標示實體入口，也標示勞工聚集點。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":12},{"front":"penniless refugees","meaning":"身無分文的難民","examples":[{"en":"Penniless refugees were among the casual workers.","zh":"身無分文的難民也在臨時工之中。"},{"en":"Penniless refugees are displaced people who have no money.","zh":"penniless refugees 是失去家園而且沒有金錢的人。"},{"en":"Penniless refugees may take any available work because they need food and shelter urgently.","zh":"身無分文的難民可能接受任何可得工作，因為他們急需食物和住所。"},{"en":"If penniless refugees compete for casual jobs, wages may be low and insecurity high.","zh":"如果身無分文的難民競爭臨時工作，工資可能低而不穩定性高。"},{"en":"The phrase highlights extreme vulnerability.","zh":"這個短語突出極端脆弱處境。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":12},{"front":"bankrupts","meaning":"破產者","examples":[{"en":"Bankrupts waited for casual work at the docks.","zh":"破產者在碼頭等候臨時工作。"},{"en":"Bankrupts are people who cannot pay their debts and have legally lost financial control.","zh":"bankrupts 是無法償還債務並在法律上失去財務控制的人。"},{"en":"A shop owner may become bankrupt if business fails and debts grow.","zh":"如果生意失敗且債務增加，店主可能成為破產者。"},{"en":"If bankrupts seek dock work, it shows the docks attracted people in financial distress.","zh":"如果破產者尋找碼頭工作，這顯示碼頭吸引財政困難的人。"},{"en":"The word identifies people ruined by debt.","zh":"這個字指出因債務而陷入困境的人。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":12},{"front":"broken-down gentlemen","meaning":"落魄紳士","examples":[{"en":"Broken-down gentlemen were included among the casual workers.","zh":"落魄紳士也包括在臨時工之中。"},{"en":"Broken-down gentlemen were once respectable men who had fallen into poverty or social decline.","zh":"broken-down gentlemen 是曾經體面但已陷入貧困或社會衰落的男性。"},{"en":"A broken-down gentleman might still speak politely but have no money or stable work.","zh":"落魄紳士可能仍說話有禮，但沒有金錢或穩定工作。"},{"en":"If broken-down gentlemen waited for dock work, the casual workforce crossed social classes.","zh":"如果落魄紳士也等候碼頭工作，臨時勞動人口就跨越了社會階層。"},{"en":"The phrase is historical and slightly judgemental.","zh":"這個短語屬歷史用語，帶有少許評判意味。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":12},{"front":"discharged servants","meaning":"被解僱的僕人","examples":[{"en":"Discharged servants were part of the casual workforce.","zh":"被解僱的僕人是臨時勞動人口的一部分。"},{"en":"Discharged servants are servants who have been dismissed from their jobs.","zh":"discharged servants 是被僱主解僱的僕人。"},{"en":"A discharged servant might look for day work after leaving a household position.","zh":"被解僱的僕人離開家僕工作後，可能尋找散工。"},{"en":"If discharged servants joined dock crowds, domestic job loss pushed people into casual labour.","zh":"如果被解僱的僕人加入碼頭人群，家僕工作流失就把人推向臨時勞動。"},{"en":"The phrase identifies people who lost service employment.","zh":"這個短語指出失去服務工作的人。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":12},{"front":"ex-convicts","meaning":"前囚犯","examples":[{"en":"Ex-convicts were among those waiting for dock work.","zh":"前囚犯也在等候碼頭工作的人之中。"},{"en":"Ex-convicts are people who have served prison sentences and been released.","zh":"ex-convicts 是服完刑並獲釋的人。"},{"en":"Ex-convicts may struggle to find regular work because employers distrust them.","zh":"前囚犯可能難以找到固定工作，因為僱主不信任他們。"},{"en":"If ex-convicts waited at the docks, casual labour offered work to people rejected elsewhere.","zh":"如果前囚犯在碼頭等候，臨時勞工就為其他地方拒絕的人提供工作。"},{"en":"The word describes former prisoners.","zh":"這個字描述曾經入獄的人。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":12},{"front":"permanent workers","meaning":"長工；固定工人","examples":[{"en":"There were about 400 to 500 permanent workers.","zh":"大約有400至500名長工。"},{"en":"Permanent workers are employees with stable, ongoing jobs rather than temporary shifts.","zh":"permanent workers 是有穩定持續職位，而不是臨時班次的員工。"},{"en":"A school’s permanent workers may include teachers, clerks and caretakers.","zh":"學校的固定工人可能包括老師、文員和校工。"},{"en":"If only a few dock workers were permanent, most others faced insecure employment.","zh":"如果只有少數碼頭工人是長工，大多數其他人就面對不穩定就業。"},{"en":"The phrase contrasts with casual workers.","zh":"這個短語與臨時工形成對比。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":13},{"front":"earn a regular wage","meaning":"賺取固定工資","examples":[{"en":"Permanent workers earned a regular wage.","zh":"長工賺取固定工資。"},{"en":"To earn a regular wage means to receive steady pay at predictable times.","zh":"earn a regular wage 指在可預期時間收到穩定工資。"},{"en":"A full-time shop assistant earns a regular wage every month.","zh":"全職店員每月賺取固定工資。"},{"en":"If workers earn a regular wage, they can plan rent and family expenses more easily.","zh":"如果工人賺取固定工資，就更容易計劃租金和家庭開支。"},{"en":"The phrase shows financial stability.","zh":"這個短語顯示財務穩定。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":13},{"front":"be considered the patricians of","meaning":"被視為……中的上層","examples":[{"en":"Permanent workers were considered the patricians of dockside labour.","zh":"長工被視為碼頭勞工中的上層。"},{"en":"To be considered the patricians of a group means to be seen as its elite or highest-status members.","zh":"be considered the patricians of 某群體，意思是被視為該群體中的精英或最高地位成員。"},{"en":"Senior surgeons may be considered the patricians of a hospital workforce.","zh":"資深外科醫生可能被視為醫院勞動人口中的上層。"},{"en":"If permanent workers had secure pay, casuals might view them as the patricians of dock labour.","zh":"如果長工有穩定工資，臨時工可能把他們視為碼頭勞工中的貴族。"},{"en":"The phrase uses an old social-class metaphor.","zh":"這個短語使用舊式社會階級比喻。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":13},{"front":"patricians of dockside labour","meaning":"碼頭勞工中的貴族","examples":[{"en":"Permanent workers were the patricians of dockside labour.","zh":"長工是碼頭勞工中的貴族。"},{"en":"Patricians of dockside labour means the highest-status workers among dock labourers.","zh":"patricians of dockside labour 指碼頭勞工中地位最高的工人。"},{"en":"In a kitchen, the head chefs might be treated as the patricians of restaurant labour.","zh":"在廚房中，主廚可能被視為餐廳勞工中的貴族。"},{"en":"If permanent dock workers were called patricians, their status was far above casuals.","zh":"如果固定碼頭工人被稱為貴族，他們的地位就遠高於臨時工。"},{"en":"The phrase is metaphorical and highlights hierarchy.","zh":"這個短語是比喻，突出階級層次。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":13},{"front":"casual workers","meaning":"臨時工","examples":[{"en":"There were about 2,500 casual workers at the docks.","zh":"碼頭大約有2,500名臨時工。"},{"en":"Casual workers are people hired temporarily, often without guaranteed hours or long-term security.","zh":"casual workers 是臨時受僱、通常沒有固定工時或長期保障的人。"},{"en":"A café may hire casual workers for weekends and holidays.","zh":"咖啡店可能在週末和假期聘請臨時工。"},{"en":"If casual workers are hired only when needed, their income can change every week.","zh":"如果臨時工只在有需要時被僱用，他們的收入可能每星期都不同。"},{"en":"The phrase contrasts with permanent employees.","zh":"這個短語與固定員工形成對比。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":13},{"front":"be hired by the shift","meaning":"按班次受僱","examples":[{"en":"Casual workers were hired by the shift.","zh":"臨時工按班次受僱。"},{"en":"To be hired by the shift means to be employed for one work period at a time.","zh":"be hired by the shift 指每次按一段工作班次受聘。"},{"en":"Event cleaners may be hired by the shift after concerts.","zh":"演唱會後，活動清潔工可能按班次受僱。"},{"en":"If workers are hired by the shift, they may not know whether they will work tomorrow.","zh":"如果工人按班次受僱，他們可能不知道明天是否有工開。"},{"en":"The phrase shows temporary and unstable employment.","zh":"這個短語顯示臨時而不穩定的就業。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":13},{"front":"compete fiercely","meaning":"激烈競爭","examples":[{"en":"Casual workers competed fiercely for dock work.","zh":"臨時工為碼頭工作激烈競爭。"},{"en":"To compete fiercely means to fight hard against others for limited opportunities.","zh":"compete fiercely 指為有限機會與他人激烈爭奪。"},{"en":"Students may compete fiercely for places in a popular university course.","zh":"學生可能為熱門大學課程名額激烈競爭。"},{"en":"If many workers compete fiercely for few jobs, wages and dignity may suffer.","zh":"如果許多工人為少量工作激烈競爭，工資和尊嚴可能受損。"},{"en":"The phrase suggests strong pressure and rivalry.","zh":"這個短語暗示強大壓力和競爭。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":13},{"front":"ever more unpleasant","meaning":"越來越令人厭惡","examples":[{"en":"The work became ever more unpleasant.","zh":"工作變得越來越令人厭惡。"},{"en":"Ever more unpleasant means increasingly unpleasant over time.","zh":"ever more unpleasant 指隨時間變得越來越不愉快。"},{"en":"A bus journey becomes ever more unpleasant if it is crowded, hot and delayed.","zh":"如果巴士旅程擠迫、炎熱又延誤，就會變得越來越令人厭惡。"},{"en":"If dock work becomes ever more unpleasant, workers may accept it only because they need money.","zh":"如果碼頭工作越來越令人厭惡，工人可能只是因為需要金錢才接受它。"},{"en":"The phrase shows a worsening situation.","zh":"這個短語顯示情況正在惡化。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":13},{"front":"steam power","meaning":"蒸汽動力","examples":[{"en":"Steam power could not be used for the cranes.","zh":"起重機不能使用蒸汽動力。"},{"en":"Steam power is energy produced by steam to drive machines.","zh":"steam power 是由蒸汽產生並推動機器的能量。"},{"en":"Early factories used steam power to run engines and machines.","zh":"早期工廠使用蒸汽動力運行引擎和機器。"},{"en":"If steam power creates fire risk near cargo, workers may need safer manual methods.","zh":"如果蒸汽動力在貨物附近造成火災風險，工人可能需要較安全的人手方法。"},{"en":"The phrase refers to a major industrial source of energy.","zh":"這個短語指一種重要工業能源。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":13},{"front":"cranes","meaning":"起重機","examples":[{"en":"The cranes were powered manually because of the danger of fire.","zh":"起重機因火災危險而以人手驅動。"},{"en":"Cranes are machines used to lift and move heavy objects.","zh":"cranes 是用來吊起和移動重物的機器。"},{"en":"Construction sites use cranes to lift steel, concrete and equipment.","zh":"建築地盤使用起重機吊起鋼材、混凝土和設備。"},{"en":"If cranes cannot use engines safely, workers may have to power them by hand or foot.","zh":"如果起重機不能安全使用引擎，工人可能要以手或腳提供動力。"},{"en":"The word refers to lifting equipment, not the bird here.","zh":"這個字在此指吊重設備，而不是鳥類。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":13},{"front":"the danger of fire","meaning":"火災危險","examples":[{"en":"Steam power could not be used because of the danger of fire.","zh":"因為火災危險，蒸汽動力不能使用。"},{"en":"The danger of fire means the risk that something may catch fire and burn.","zh":"the danger of fire 指某物可能着火燃燒的風險。"},{"en":"A kitchen with leaking gas has a serious danger of fire.","zh":"有煤氣洩漏的廚房有嚴重火災危險。"},{"en":"If warehouses contain flammable goods, the danger of fire limits what machines can be used.","zh":"如果倉庫存放易燃貨物，火災危險會限制可使用的機器。"},{"en":"The phrase explains a safety reason.","zh":"這個短語解釋安全原因。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":14},{"front":"be powered by treadmills","meaning":"由踏車驅動","examples":[{"en":"The cranes were powered by treadmills.","zh":"起重機由踏車驅動。"},{"en":"To be powered by treadmills means to be driven by people walking inside or on wheel-like machines.","zh":"be powered by treadmills 指由人在輪狀機器內或上面行走來驅動。"},{"en":"An old machine might be powered by treadmills before engines became safe or cheap.","zh":"在引擎變得安全或便宜前，舊機器可能由踏車驅動。"},{"en":"If cranes are powered by treadmills, human effort directly lifts the goods.","zh":"如果起重機由踏車驅動，人力就直接把貨物吊起。"},{"en":"The phrase describes human-powered machinery.","zh":"這個短語描述以人力推動的機械。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":14},{"front":"treadmills","meaning":"踏車；人力踏輪","examples":[{"en":"Workers powered the cranes by using treadmills.","zh":"工人透過使用踏車驅動起重機。"},{"en":"Treadmills were wheel-like machines that people walked on to produce power.","zh":"treadmills 是人們在上面行走以產生動力的輪狀機器。"},{"en":"Modern gym treadmills are for exercise, but older treadmills could drive machinery.","zh":"現代健身踏步機用於運動，但舊式踏車可以推動機械。"},{"en":"If men worked inside treadmills for hours, the labour was exhausting.","zh":"如果工人在踏車內工作數小時，勞動會非常疲累。"},{"en":"The word here refers to industrial human-powered equipment.","zh":"這個字在此指工業用人力踏輪設備。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":14},{"front":"wooden cylinder","meaning":"木製圓筒","examples":[{"en":"Six to eight men entered a wooden cylinder.","zh":"六至八名男子進入一個木製圓筒。"},{"en":"A wooden cylinder is a round tube-shaped structure made of wood.","zh":"wooden cylinder 是由木製成的圓筒形結構。"},{"en":"A barrel is a kind of wooden cylinder used to store goods.","zh":"木桶是一種用來儲存貨物的木製圓筒。"},{"en":"If workers entered a wooden cylinder, their walking could turn it like a wheel.","zh":"如果工人進入木製圓筒，他們的步行可以令它像輪子一樣轉動。"},{"en":"The phrase describes the shape and material of the treadmill mechanism.","zh":"這個短語描述踏車機制的形狀和材料。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":14},{"front":"laying hold of ropes","meaning":"抓住繩索","examples":[{"en":"The men lifted goods by laying hold of ropes.","zh":"工人透過抓住繩索吊起貨物。"},{"en":"Laying hold of ropes means gripping ropes firmly.","zh":"laying hold of ropes 指牢牢抓住繩索。"},{"en":"Sailors lay hold of ropes to pull a boat closer to the dock.","zh":"水手抓住繩索，把船拉近碼頭。"},{"en":"If workers lay hold of ropes inside a crane system, they can control heavy loads.","zh":"如果工人在起重機系統內抓住繩索，他們就能控制重物。"},{"en":"The phrase describes a physical action needed for manual lifting.","zh":"這個短語描述人手吊運所需的實際動作。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":14},{"front":"tread the wheel round","meaning":"踩動輪子轉動","examples":[{"en":"The men would tread the wheel round to power the crane.","zh":"工人會踩動輪子轉動，以驅動起重機。"},{"en":"To tread the wheel round means to walk on or inside a wheel so that it turns.","zh":"tread the wheel round 指在輪上或輪內行走，使輪子轉動。"},{"en":"A person treading a wheel round uses body weight and steps to create movement.","zh":"踩動輪子轉動的人利用體重和步伐產生動力。"},{"en":"If several men tread the wheel round together, the crane can lift heavier loads.","zh":"如果幾名男子一起踩動輪子轉動，起重機就能吊起更重貨物。"},{"en":"The phrase describes how human walking becomes mechanical power.","zh":"這個短語描述人類步行如何變成機械動力。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":14},{"front":"lift nearly 20 tonnes","meaning":"吊起接近20噸","examples":[{"en":"The workers could lift nearly 20 tonnes.","zh":"工人可以吊起接近20噸。"},{"en":"To lift nearly 20 tonnes means to raise a load weighing almost 20,000 kilograms.","zh":"lift nearly 20 tonnes 指吊起重近20,000公斤的負荷。"},{"en":"A modern crane may lift nearly 20 tonnes of steel at a construction site.","zh":"現代起重機可能在建築地盤吊起接近20噸鋼材。"},{"en":"If manual cranes could lift nearly 20 tonnes, the treadwheel system was powerful but exhausting.","zh":"如果人力起重機能吊起接近20噸，踏輪系統就很有力但非常疲累。"},{"en":"The phrase shows the heavy scale of dock labour.","zh":"這個短語顯示碼頭勞動的重型規模。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":14},{"front":"an average height of","meaning":"平均高度為……","examples":[{"en":"The cranes lifted goods to an average height of 27 feet.","zh":"起重機把貨物吊到平均27英尺的高度。"},{"en":"An average height of a number means the typical height reached across many cases.","zh":"an average height of 某數字，指多個情況中的典型高度。"},{"en":"The trees in the park grow to an average height of five metres.","zh":"公園中的樹木平均高度為五米。"},{"en":"If goods were lifted to an average height of 27 feet, workers moved cargo far above ground level.","zh":"如果貨物被吊到平均27英尺高度，工人就是把貨物移到離地很高的位置。"},{"en":"The phrase gives a measured typical height.","zh":"這個短語提供可量度的典型高度。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":14},{"front":"forty times in an hour","meaning":"一小時四十次","examples":[{"en":"The men could repeat the lifting process forty times in an hour.","zh":"工人可以在一小時內重複吊運過程四十次。"},{"en":"Forty times in an hour means forty repetitions within sixty minutes.","zh":"forty times in an hour 指六十分鐘內重複四十次。"},{"en":"A busy lift may travel up and down forty times in an hour.","zh":"繁忙升降機可能一小時上下四十次。"},{"en":"If workers lifted heavy goods forty times in an hour, the labour was intense.","zh":"如果工人在一小時內吊運重貨四十次，勞動強度就很高。"},{"en":"The phrase shows frequency and workload.","zh":"這個短語顯示頻率和工作量。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":14},{"front":"be intent upon","meaning":"專注於；一心看着","examples":[{"en":"Some observers were intent upon the river’s picturesque aspects.","zh":"一些觀察者專注於河流風景如畫的一面。"},{"en":"To be intent upon something means to focus strongly on it.","zh":"be intent upon 某事，意思是強烈專注於它。"},{"en":"A student intent upon passing the exam may practise every evening.","zh":"一心想通過考試的學生可能每天晚上練習。"},{"en":"If visitors are intent upon beautiful scenery, they may ignore the workers’ hardship.","zh":"如果訪客一心只看美景，他們可能忽略工人的艱辛。"},{"en":"The phrase suggests strong attention, sometimes too narrow.","zh":"這個短語暗示強烈注意，有時過於狹窄。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":14},{"front":"picturesque aspects","meaning":"風景如畫的一面","examples":[{"en":"Some observers focused only on the picturesque aspects of the river.","zh":"一些觀察者只專注於河流風景如畫的一面。"},{"en":"Picturesque aspects are the attractive, scenic or charming features of a place.","zh":"picturesque aspects 是一個地方吸引人、有景色或迷人的特徵。"},{"en":"A tourist may photograph the picturesque aspects of an old fishing village.","zh":"遊客可能拍下舊漁村風景如畫的一面。"},{"en":"If people see only picturesque aspects, they may miss poverty, labour and danger behind the view.","zh":"如果人們只看見風景如畫的一面，就可能錯過景色背後的貧窮、勞動和危險。"},{"en":"The phrase contrasts beauty with harsher realities.","zh":"這個短語把美感與較嚴酷現實作對比。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":15},{"front":"choose the correct heading","meaning":"選擇正確標題","examples":[{"en":"Students choose the correct heading for each paragraph.","zh":"學生為每段選擇正確標題。"},{"en":"To choose the correct heading means to select the title that best matches the paragraph’s main idea.","zh":"choose the correct heading 指選出最符合段落主旨的標題。"},{"en":"In reading practice, students choose the correct heading after identifying the topic sentence.","zh":"在閱讀練習中，學生識別主題句後選擇正確標題。"},{"en":"If students focus only on one detail, they may choose the wrong heading.","zh":"如果學生只集中一個細節，可能會選錯標題。"},{"en":"The phrase is common in IELTS-style paragraph matching.","zh":"這個短語常見於 IELTS 式段落配對題。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":15},{"front":"list of headings","meaning":"標題列表","examples":[{"en":"The question provides a list of headings.","zh":"題目提供一個標題列表。"},{"en":"A list of headings is a set of possible titles for paragraphs or sections.","zh":"list of headings 是一組可作為段落或章節標題的選項。"},{"en":"Students should read the list of headings before matching them to paragraphs.","zh":"學生應在配對段落前閱讀標題列表。"},{"en":"If a list of headings contains similar options, students must compare main ideas carefully.","zh":"如果標題列表包含相似選項，學生必須仔細比較主旨。"},{"en":"The phrase refers to answer choices in a reading task.","zh":"這個短語指閱讀題中的答案選項。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":15},{"front":"write the correct number","meaning":"寫上正確編號","examples":[{"en":"Students write the correct number on the answer sheet.","zh":"學生在答題紙上寫上正確編號。"},{"en":"To write the correct number means to record the number of the chosen option.","zh":"write the correct number 指寫下所選選項的編號。"},{"en":"In a matching task, students write the correct number beside each paragraph letter.","zh":"在配對題中，學生在每個段落字母旁寫上正確編號。"},{"en":"If students write the wrong number, the answer may be marked wrong even if they understood the text.","zh":"如果學生寫錯編號，即使理解文本，答案也可能被判錯。"},{"en":"The phrase tells candidates the required answer format.","zh":"這個短語告訴考生所需答案格式。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":15},{"front":"a mixture of languages and nationalities","meaning":"語言和國籍的混合","examples":[{"en":"The heading refers to a mixture of languages and nationalities.","zh":"這個標題指語言和國籍的混合。"},{"en":"A mixture of languages and nationalities means people from different countries speaking different languages together.","zh":"a mixture of languages and nationalities 指來自不同國家、說不同語言的人共處。"},{"en":"An international airport contains a mixture of languages and nationalities every day.","zh":"國際機場每天都有語言和國籍的混合。"},{"en":"If dock areas attract sailors and migrants, a mixture of languages and nationalities may develop.","zh":"如果碼頭地區吸引水手和移民，就可能發展出語言和國籍的混合。"},{"en":"The phrase highlights cultural diversity.","zh":"這個短語突出文化多樣性。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":15},{"front":"creation of an exclusive identity","meaning":"獨特身份的形成","examples":[{"en":"The paragraph describes the creation of an exclusive identity among river workers.","zh":"該段描述河上工人之間獨特身份的形成。"},{"en":"Creation of an exclusive identity means forming a group identity that feels separate from outsiders.","zh":"creation of an exclusive identity 指形成一種與外人分隔的群體身份。"},{"en":"A club may create an exclusive identity through special words, rituals and clothing.","zh":"一個會社可能透過特殊詞語、儀式和服裝形成獨特身份。"},{"en":"If dock workers used their own slang, it helped the creation of an exclusive identity.","zh":"如果碼頭工人使用自己的俚語，這有助獨特身份的形成。"},{"en":"The phrase connects language and customs with group separation.","zh":"這個短語把語言和習俗與群體分隔連繫起來。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":15},{"front":"duties involved in","meaning":"……所涉及的職責","examples":[{"en":"The heading asks about the duties involved in various occupations.","zh":"這個標題問各種職業所涉及的職責。"},{"en":"Duties involved in a job are the tasks and responsibilities that job includes.","zh":"duties involved in 一份工作，指該工作包含的任務和責任。"},{"en":"The duties involved in teaching include planning lessons, marking work and helping students.","zh":"教學所涉及的職責包括備課、批改和幫助學生。"},{"en":"If students know the duties involved in river jobs, they can understand why the jobs were specialised.","zh":"如果學生知道河上工作所涉及的職責，就能理解為何這些工作很專門。"},{"en":"The phrase focuses on what workers actually had to do.","zh":"這個短語重點在於工人實際需要做甚麼。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":15},{"front":"various occupations","meaning":"各種職業","examples":[{"en":"The paragraph lists various occupations connected with the Thames.","zh":"該段列出與泰晤士河相關的各種職業。"},{"en":"Various occupations are different kinds of jobs.","zh":"various occupations 指不同種類的工作。"},{"en":"A hospital has various occupations, including nurses, cleaners, doctors and clerks.","zh":"醫院有各種職業，包括護士、清潔工、醫生和文員。"},{"en":"If a river supports various occupations, it is economically important.","zh":"如果一條河支撐各種職業，它在經濟上就很重要。"},{"en":"The phrase stresses job diversity.","zh":"這個短語強調職業多樣性。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":15},{"front":"unprecedented population density","meaning":"前所未有的人口密度","examples":[{"en":"The heading refers to unprecedented population density in the East End.","zh":"這個標題指倫敦東區前所未有的人口密度。"},{"en":"Unprecedented population density means a level of crowding never seen before.","zh":"unprecedented population density 指以前從未見過的擠迫程度。"},{"en":"A new housing district may face unprecedented population density if towers are built too close together.","zh":"如果高樓建得太近，新住宅區可能面對前所未有的人口密度。"},{"en":"If population density is unprecedented, services like water, schools and clinics may be strained.","zh":"如果人口密度前所未有，供水、學校和診所等服務可能受壓。"},{"en":"The phrase highlights an extreme and new level of crowding.","zh":"這個短語突出極端而新的擠迫程度。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":15},{"front":"imports and exports","meaning":"進口與出口貨物","examples":[{"en":"Imports and exports were transported by river.","zh":"進口與出口貨物由河流運送。"},{"en":"Imports and exports are goods brought into and sent out of a country or city for trade.","zh":"imports and exports 是為貿易而被帶入和送出國家或城市的貨物。"},{"en":"A port handles imports and exports such as food, clothes, machines and raw materials.","zh":"港口處理食物、衣服、機器和原材料等進口與出口貨物。"},{"en":"If imports and exports increase, dock workers may have more cargo to move.","zh":"如果進口與出口貨物增加，碼頭工人可能有更多貨物要搬運。"},{"en":"The phrase describes trade flowing in both directions.","zh":"這個短語描述雙向流動的貿易。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":15},{"front":"transporting heavy loads manually","meaning":"以人手搬運重物","examples":[{"en":"The paragraph describes transporting heavy loads manually.","zh":"該段描述以人手搬運重物。"},{"en":"Transporting heavy loads manually means moving heavy goods by human strength rather than machines.","zh":"transporting heavy loads manually 指用人力而不是機器移動重貨。"},{"en":"Workers transporting heavy loads manually may use ropes, poles or teamwork.","zh":"以人手搬運重物的工人可能使用繩索、桿或團隊合作。"},{"en":"If heavy loads are transported manually, the work is slow, costly and physically exhausting.","zh":"如果重物以人手搬運，工作就緩慢、昂貴且非常耗體力。"},{"en":"The phrase focuses on human effort in moving weight.","zh":"這個短語重點在於用人力移動重量。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":16},{"front":"temporary work","meaning":"臨時工作","examples":[{"en":"Casual labour was a form of temporary work.","zh":"臨時勞工是一種臨時工作。"},{"en":"Temporary work is employment that lasts for a short time rather than permanently.","zh":"temporary work 是只持續短時間而非永久的工作。"},{"en":"A student may take temporary work during the summer holiday.","zh":"學生可能在暑假做臨時工作。"},{"en":"If people rely on temporary work, their income may be uncertain.","zh":"如果人們依賴臨時工作，他們的收入可能不穩定。"},{"en":"The phrase contrasts with permanent employment.","zh":"這個短語與固定工作形成對比。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":16},{"front":"large numbers of people","meaning":"大量人群","examples":[{"en":"Large numbers of people waited for casual dock work.","zh":"大量人群等候臨時碼頭工作。"},{"en":"Large numbers of people means many people.","zh":"large numbers of people 指很多人。"},{"en":"Large numbers of people use public transport during rush hour.","zh":"大量人群在繁忙時間使用公共交通。"},{"en":"If large numbers of people compete for few jobs, many will be disappointed.","zh":"如果大量人群競爭少量工作，許多人會失望。"},{"en":"The phrase stresses the size of a crowd or group.","zh":"這個短語強調人群或群體規模。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":16},{"front":"hazards associated with","meaning":"與……相關的危險","examples":[{"en":"The heading mentions hazards associated with riverside work.","zh":"這個標題提及與河邊工作相關的危險。"},{"en":"Hazards associated with something are dangers connected with that activity or place.","zh":"hazards associated with 某事，是與該活動或地方相關的危險。"},{"en":"Hazards associated with construction include falling objects and heavy machinery.","zh":"與建築工程相關的危險包括墜物和重型機械。"},{"en":"If hazards are associated with dock work, workers need safety rules and equipment.","zh":"如果碼頭工作有相關危險，工人就需要安全規則和設備。"},{"en":"The phrase introduces risks linked to a situation.","zh":"這個短語引出與某情況相關的風險。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":16},{"front":"riverside work","meaning":"河邊工作","examples":[{"en":"Riverside work could be physically demanding and dangerous.","zh":"河邊工作可能需要大量體力並有危險。"},{"en":"Riverside work is work done beside or on a river.","zh":"riverside work 是在河邊或河上進行的工作。"},{"en":"Riverside work may include loading boats, repairing banks or selling food to workers.","zh":"河邊工作可能包括裝船、維修河岸或向工人售賣食物。"},{"en":"If riverside work depends on tides and heavy goods, it can be risky.","zh":"如果河邊工作取決於潮汐和重貨，它可能很危險。"},{"en":"The phrase links labour with a river environment.","zh":"這個短語把勞動與河流環境連繫起來。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":16},{"front":"changing status","meaning":"地位轉變","examples":[{"en":"The passage describes the changing status of riverside occupations.","zh":"文章描述河邊職業的地位轉變。"},{"en":"Changing status means a shift in how respected or valued something is.","zh":"changing status 指某事受尊重或被重視程度的轉變。"},{"en":"Teaching has had changing status in different societies and periods.","zh":"教學在不同社會和時期有不同的地位轉變。"},{"en":"If dock work moves from respected to disreputable, its changing status affects workers’ dignity.","zh":"如果碼頭工作從受尊重變成不體面，其地位轉變會影響工人尊嚴。"},{"en":"The phrase focuses on social position over time.","zh":"這個短語重點在於隨時間變化的社會位置。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":16},{"front":"before the eighteenth century","meaning":"18世紀之前","examples":[{"en":"The question asks about work before the eighteenth century.","zh":"題目問18世紀之前的工作情況。"},{"en":"Before the eighteenth century means earlier than the 1700s.","zh":"before the eighteenth century 指早於1700年代。"},{"en":"Before the eighteenth century, many goods were moved without modern engines.","zh":"18世紀之前，許多貨物是在沒有現代引擎的情況下搬運。"},{"en":"If river work was respected before the eighteenth century, later attitudes had clearly changed.","zh":"如果河上工作在18世紀之前受尊重，後來態度就明顯改變了。"},{"en":"The phrase sets a historical period before a turning point.","zh":"這個短語設定轉折點之前的歷史時期。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":16},{"front":"goods were transported by cart","meaning":"貨物由手推車運送","examples":[{"en":"The option says that goods were transported from the river by cart.","zh":"選項說貨物由手推車從河邊運送。"},{"en":"Goods were transported by cart means goods were moved using wheeled vehicles.","zh":"goods were transported by cart 指貨物用有輪車輛搬運。"},{"en":"Farm produce was often transported by cart before trucks became common.","zh":"在貨車普及前，農產品常由手推車或馬車運送。"},{"en":"If streets were unsuitable, goods could not easily be transported by cart from the docks.","zh":"如果街道不合適，貨物就不容易由手推車從碼頭運出。"},{"en":"The phrase describes a possible transport method.","zh":"這個短語描述一種可能的運輸方法。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":16},{"front":"poorly paid","meaning":"薪酬低的","examples":[{"en":"The option asks whether the workforce was poorly paid.","zh":"這個選項問勞動人口是否薪酬低。"},{"en":"Poorly paid means receiving low wages for work.","zh":"poorly paid 指工作所得工資低。"},{"en":"Cleaners may be poorly paid even when their work is essential.","zh":"清潔工即使工作重要，也可能薪酬低。"},{"en":"If workers are poorly paid, they may need several jobs to support a family.","zh":"如果工人薪酬低，他們可能需要幾份工作才能養家。"},{"en":"The phrase focuses on unfair or low income.","zh":"這個短語重點在於不公平或偏低收入。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":16},{"front":"occupations were specialised","meaning":"職業分工專門化","examples":[{"en":"Many riverside occupations were specialised.","zh":"許多河邊職業分工專門化。"},{"en":"Occupations were specialised means jobs were divided into specific roles requiring particular skills or duties.","zh":"occupations were specialised 指工作被分成需要特定技能或職責的角色。"},{"en":"In a hospital, occupations are specialised because nurses, surgeons and pharmacists do different work.","zh":"在醫院中，職業分工專門化，因為護士、外科醫生和藥劑師做不同工作。"},{"en":"If river occupations were specialised, each worker handled a particular part of the river economy.","zh":"如果河邊職業分工專門化，每個工人就負責河流經濟中的特定部分。"},{"en":"The phrase shows division of labour.","zh":"這個短語顯示勞動分工。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":16},{"front":"be looked down upon","meaning":"被看不起","examples":[{"en":"Some kinds of labour were later looked down upon.","zh":"有些勞動後來被看不起。"},{"en":"To be looked down upon means to be treated as inferior or not respectable.","zh":"be looked down upon 指被視為低人一等或不體面。"},{"en":"Manual workers should not be looked down upon because society depends on their work.","zh":"體力勞動者不應被看不起，因為社會依賴他們的工作。"},{"en":"If dock labour is looked down upon, workers may suffer shame as well as hardship.","zh":"如果碼頭勞工被看不起，工人可能除了艱辛外還承受羞辱。"},{"en":"The phrase describes social disrespect.","zh":"這個短語描述社會上的不尊重。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":17},{"front":"physical strength was required","meaning":"需要體力","examples":[{"en":"River work required physical strength.","zh":"河上工作需要體力。"},{"en":"Physical strength was required means the job needed bodily power and endurance.","zh":"physical strength was required 指工作需要身體力量和耐力。"},{"en":"Moving furniture upstairs is a job where physical strength is required.","zh":"把家具搬上樓是一項需要體力的工作。"},{"en":"If workers had to lift barrels and pull ropes, physical strength was clearly required.","zh":"如果工人必須搬木桶和拉繩索，就明顯需要體力。"},{"en":"The phrase explains the bodily demands of work.","zh":"這個短語解釋工作的身體要求。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":17},{"front":"early nineteenth century","meaning":"19世紀初","examples":[{"en":"The question asks about life by the River Thames in the early nineteenth century.","zh":"題目問19世紀初泰晤士河畔的生活。"},{"en":"Early nineteenth century means the first part of the 1800s.","zh":"early nineteenth century 指1800年代早期。"},{"en":"In the early nineteenth century, many cities were changing because of industry.","zh":"19世紀初，許多城市因工業而改變。"},{"en":"If reports describe the early nineteenth century, they show London before many modern reforms.","zh":"如果報道描述19世紀初，它們就展示許多現代改革前的倫敦。"},{"en":"The phrase places events near the start of the 1800s.","zh":"這個短語把事件放在1800年代開端附近。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":17},{"front":"very crowded","meaning":"非常擠迫","examples":[{"en":"The East End was very crowded.","zh":"倫敦東區非常擠迫。"},{"en":"Very crowded means filled with too many people in a limited space.","zh":"very crowded 指有限空間中擠滿太多人。"},{"en":"The train was very crowded after the football match ended.","zh":"足球賽結束後，火車非常擠迫。"},{"en":"If an area is very crowded, housing, sanitation and transport become difficult.","zh":"如果一個地區非常擠迫，住屋、衛生和交通都會變得困難。"},{"en":"The phrase describes high density in a simple way.","zh":"這個短語以簡單方式描述高密度。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":17},{"front":"absence of crime","meaning":"沒有罪案","examples":[{"en":"The option asks whether there was an absence of crime.","zh":"選項問是否沒有罪案。"},{"en":"Absence of crime means crime is not present or is extremely rare.","zh":"absence of crime 指沒有犯罪活動或犯罪極罕見。"},{"en":"A small village may appear peaceful, but that does not prove an absence of crime.","zh":"小村莊可能看起來平靜，但這不證明沒有罪案。"},{"en":"If newspapers mention smugglers and opium dens, an absence of crime is unlikely.","zh":"如果報章提到走私者和鴉片煙館，就不太可能沒有罪案。"},{"en":"The phrase describes a condition with no criminal activity.","zh":"這個短語描述沒有犯罪活動的情況。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":17},{"front":"casual work","meaning":"臨時工作","examples":[{"en":"Casual work was in great demand at the docks.","zh":"碼頭臨時工作需求很高。"},{"en":"Casual work is temporary employment without a long-term contract.","zh":"casual work 是沒有長期合約的臨時工作。"},{"en":"Students sometimes do casual work at events or restaurants.","zh":"學生有時在活動或餐廳做臨時工作。"},{"en":"If casual work is the only option, workers may face uncertain income.","zh":"如果臨時工作是唯一選擇，工人可能面對不穩定收入。"},{"en":"The phrase refers to short-term jobs rather than stable careers.","zh":"這個短語指短期工作，而不是穩定職業。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":17},{"front":"in great demand","meaning":"需求很高","examples":[{"en":"Dock work was in great demand among casual workers.","zh":"碼頭工作在臨時工之間需求很高。"},{"en":"In great demand means strongly wanted by many people.","zh":"in great demand 指被許多人強烈需要或想要。"},{"en":"Experienced nurses are in great demand when hospitals are understaffed.","zh":"當醫院人手不足，有經驗護士需求很高。"},{"en":"If dock work is in great demand, many workers compete for each available shift.","zh":"如果碼頭工作需求很高，許多工人就會競爭每一個可用班次。"},{"en":"The phrase shows high demand compared with supply.","zh":"這個短語顯示需求相對供應很高。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":17},{"front":"languages were in use","meaning":"多種語言被使用","examples":[{"en":"The option asks whether several different languages were in use.","zh":"選項問是否有多種不同語言被使用。"},{"en":"Languages were in use means people were actively speaking or using those languages.","zh":"languages were in use 指人們正在實際說或使用那些語言。"},{"en":"At an international conference, many languages are in use at the same time.","zh":"在國際會議上，多種語言同時被使用。"},{"en":"If sailors from many countries gather at docks, several languages may be in use.","zh":"如果來自多國的水手聚集在碼頭，多種語言可能被使用。"},{"en":"The phrase describes real communication, not only languages listed in books.","zh":"這個短語描述真實溝通，而不只是書中列出的語言。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":17},{"front":"be known for","meaning":"以……聞名","examples":[{"en":"The option asks whether inhabitants were known for their friendliness.","zh":"選項問居民是否以友善聞名。"},{"en":"To be known for something means to be recognised because of that quality or feature.","zh":"be known for 某事，意思是因某種特質或特徵而被認識。"},{"en":"A restaurant may be known for fresh seafood and polite service.","zh":"餐廳可能以新鮮海鮮和有禮服務聞名。"},{"en":"If an area is known for crime, visitors may feel nervous even before arriving.","zh":"如果一個地區以罪案聞名，遊客未到達前可能已感到緊張。"},{"en":"The phrase describes reputation.","zh":"這個短語描述名聲。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":17},{"front":"complete the sentences below","meaning":"完成以下句子","examples":[{"en":"Students complete the sentences below using words from the passage.","zh":"學生使用文章中的字詞完成以下句子。"},{"en":"Complete the sentences below means fill in missing information in the following sentences.","zh":"complete the sentences below 指填寫以下句子中的缺失資料。"},{"en":"In reading exams, students complete the sentences below by finding exact words in the text.","zh":"在閱讀考試中，學生透過在文本中找原字完成以下句子。"},{"en":"If students ignore grammar, they may choose words that do not fit the sentence.","zh":"如果學生忽略文法，可能選出不適合句子的字詞。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":17},{"front":"no more than two words","meaning":"不多於兩個詞","examples":[{"en":"Students choose no more than two words from the passage.","zh":"學生從文章中選擇不多於兩個詞。"},{"en":"No more than two words means the answer may contain one or two words, but not three.","zh":"no more than two words 指答案可以包含一個或兩個英文詞，但不能有三個。"},{"en":"If the answer is “regular wage”, it follows a no more than two words rule.","zh":"如果答案是 regular wage，就符合不多於兩個詞的規則。"},{"en":"Students may lose marks if they write extra words beyond the limit.","zh":"如果學生寫超出限制的額外字詞，可能會失分。"},{"en":"The phrase gives a strict word limit.","zh":"這個短語給出嚴格字數限制。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":18},{"front":"only a minority of","meaning":"只有少數……","examples":[{"en":"Only a minority of dock workers received a regular wage.","zh":"只有少數碼頭工人收取固定工資。"},{"en":"Only a minority of a group means only a smaller part of that group.","zh":"only a minority of 某群體，指只有該群體中的較小部分。"},{"en":"Only a minority of students walk to school if most travel by bus.","zh":"如果大多數學生乘巴士，只有少數學生步行上學。"},{"en":"If only a minority of workers have stable pay, most face insecurity.","zh":"如果只有少數工人有穩定工資，大多數人就面對不穩定。"},{"en":"The phrase contrasts the smaller group with the majority.","zh":"這個短語把少數群體與大多數作對比。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":18},{"front":"receive a regular wage","meaning":"收取固定工資","examples":[{"en":"Only permanent dock workers received a regular wage.","zh":"只有固定碼頭工人收取固定工資。"},{"en":"To receive a regular wage means to be paid steadily and predictably.","zh":"receive a regular wage 指穩定而可預期地獲得工資。"},{"en":"Full-time office workers usually receive a regular wage every month.","zh":"全職辦公室員工通常每月收取固定工資。"},{"en":"If workers receive a regular wage, they can plan family expenses more confidently.","zh":"如果工人收取固定工資，他們就能更有信心計劃家庭開支。"},{"en":"The phrase shows income security.","zh":"這個短語顯示收入保障。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":18},{"front":"be operated manually","meaning":"以人手操作","examples":[{"en":"The cranes were operated manually.","zh":"起重機以人手操作。"},{"en":"To be operated manually means to be controlled or powered by human hands, feet or bodies rather than machines.","zh":"be operated manually 指由人的手、腳或身體控制或提供動力，而不是由機器控制。"},{"en":"A manual door is operated manually instead of opening by sensor.","zh":"手動門以人手操作，而不是由感應器自動開門。"},{"en":"If cranes were operated manually, lifting cargo required intense human effort.","zh":"如果起重機以人手操作，吊運貨物就需要強大人力。"},{"en":"The phrase contrasts human power with mechanical or automatic power.","zh":"這個短語把人力與機械或自動動力作對比。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":18},{"front":"create a risk of fire","meaning":"造成火災風險","examples":[{"en":"Steam power created a risk of fire.","zh":"蒸汽動力造成火災風險。"},{"en":"To create a risk of fire means to make fire more likely to happen.","zh":"create a risk of fire 指令火災更有可能發生。"},{"en":"Leaving paper near a heater can create a risk of fire.","zh":"把紙張放在暖爐附近可能造成火災風險。"},{"en":"If steam engines create a risk of fire near cargo, safer power sources must be used.","zh":"如果蒸汽引擎在貨物附近造成火災風險，就必須使用較安全的動力來源。"},{"en":"The phrase explains a danger caused by a method or object.","zh":"這個短語解釋某方法或物件造成的危險。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":18},{"front":"observers unfamiliar with","meaning":"對……不熟悉的觀察者","examples":[{"en":"Observers unfamiliar with London’s docks saw only the picturesque river.","zh":"對倫敦碼頭不熟悉的觀察者只看見風景如畫的河流。"},{"en":"Observers unfamiliar with something are people who do not know it well.","zh":"observers unfamiliar with 某事，是不太了解它的觀察者。"},{"en":"Visitors unfamiliar with a school’s rules may enter the wrong gate.","zh":"對學校規則不熟悉的訪客可能走錯入口。"},{"en":"If observers unfamiliar with dock work see only the view, they may miss the labour behind it.","zh":"如果對碼頭工作不熟悉的觀察者只看景色，他們可能錯過背後的勞動。"},{"en":"The phrase shows that limited knowledge affects perception.","zh":"這個短語顯示有限知識會影響看法。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":18},{"front":"find the River Thames picturesque","meaning":"覺得泰晤士河風景如畫","examples":[{"en":"Some observers found the River Thames picturesque.","zh":"一些觀察者覺得泰晤士河風景如畫。"},{"en":"To find the River Thames picturesque means to see it as beautiful, charming or scenic.","zh":"find the River Thames picturesque 指認為泰晤士河美麗、迷人或有景色。"},{"en":"Tourists may find the River Thames picturesque at sunset when boats pass under the bridges.","zh":"日落時船隻穿過橋下，遊客可能覺得泰晤士河風景如畫。"},{"en":"If people find the River Thames picturesque, they may overlook its history of hard labour.","zh":"如果人們覺得泰晤士河風景如畫，就可能忽略其艱辛勞動歷史。"},{"en":"The phrase describes an aesthetic judgement of the river.","zh":"這個短語描述對河流的美感判斷。"}],"source":"113 - Early occupations around the river Thames.pdf","sourcePage":18}],"ielts/reading/passage-2/Practice 114":[{"front":"acquiring the principles of","meaning":"掌握……的原理","examples":[{"en":"The passage discusses how students go about acquiring the principles of mathematics and science.","zh":"篇章討論學生如何掌握數學和科學原理。"},{"en":"Acquiring the principles of a subject means gradually understanding its basic ideas and rules.","zh":"掌握一門學科的原理，是指逐步理解其基本概念和規則。"},{"en":"A student begins acquiring the principles of grammar by learning how subjects and verbs work together.","zh":"學生透過學習主語和動詞如何配合，開始掌握文法原理。"},{"en":"Acquiring principles takes time because learners must use ideas, not just repeat them.","zh":"掌握原理需要時間，因為學習者必須運用概念，而不只是複述。"},{"en":"This phrase is useful when learning is deep and conceptual rather than simple memorisation.","zh":"當學習是深入和概念性的，而非單純記憶時，這個短語很有用。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":1},{"front":"principles of mathematics and science","meaning":"數學和科學原理","examples":[{"en":"Students need to understand the principles of mathematics and science, not just memorise facts.","zh":"學生需要理解數學和科學原理，而不只是記憶事實。"},{"en":"Principles of mathematics and science are the basic ideas that explain how numbers, objects, forces, and natural processes work.","zh":"數學和科學原理，是解釋數字、物件、力量和自然過程如何運作的基本概念。"},{"en":"In school, students learn principles such as measurement, motion, energy, and cause and effect.","zh":"在學校裡，學生學習量度、運動、能量和因果等原理。"},{"en":"Without these principles, students may know answers but fail to explain why they are true.","zh":"沒有這些原理，學生可能知道答案，卻不能解釋為何答案正確。"},{"en":"This phrase refers to deep understanding behind facts and formulae.","zh":"這個短語指事實和公式背後的深入理解。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":1},{"front":"it has been pointed out that","meaning":"有人指出","examples":[{"en":"It has been pointed out that learning science involves learning ways of thinking.","zh":"有人指出，學習科學涉及學習思考方式。"},{"en":"It has been pointed out that means someone has already noticed or stated an important idea.","zh":"有人指出，是指某人已經注意到或提出一個重要想法。"},{"en":"It has been pointed out that many students forget vocabulary if they never use it in speaking.","zh":"有人指出，如果學生從不在口語中使用詞彙，就很容易忘記。"},{"en":"This phrase is often used in academic writing to introduce an existing observation.","zh":"這個短語常用於學術寫作中，引入已有觀察。"},{"en":"It sounds more formal than simply saying “someone said.”","zh":"它比單純說「有人說」更正式。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":1},{"front":"not so much A as B","meaning":"與其說是A，不如說是B","examples":[{"en":"Learning mathematics is not so much learning facts as learning ways of thinking.","zh":"學習數學與其說是學習事實，不如說是學習思考方式。"},{"en":"Not so much A as B means B is more accurate or important than A.","zh":"與其說是 A，不如說是 B，是指 B 比 A 更準確或更重要。"},{"en":"Good writing is not so much using difficult words as expressing ideas clearly.","zh":"好寫作與其說是使用深字，不如說是清楚表達想法。"},{"en":"This structure corrects a common misunderstanding by shifting attention to the real point.","zh":"這個結構透過把注意力轉向真正重點，糾正常見誤解。"},{"en":"It is useful when something looks like one thing but is better understood as another.","zh":"當某事看似一回事，但其實應理解為另一回事時，這個句式很有用。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":1},{"front":"learning facts","meaning":"學習事實；記憶資料","examples":[{"en":"The writer argues that science is not simply a matter of learning facts.","zh":"作者認為，科學不只是學習事實。"},{"en":"Learning facts means memorising pieces of information, such as names, dates, or definitions.","zh":"學習事實，是指記憶名稱、日期或定義等資料。"},{"en":"A student may learn facts about planets without understanding why planets move.","zh":"學生可能記住關於行星的事實，卻不理解行星為何運動。"},{"en":"Learning facts is useful, but it does not always create deep understanding.","zh":"學習事實有用，但不一定產生深入理解。"},{"en":"This phrase contrasts memorisation with conceptual thinking.","zh":"這個短語把記憶資料與概念思考作對比。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":1},{"front":"ways of thinking","meaning":"思考方式","examples":[{"en":"Science education often requires students to change their ways of thinking.","zh":"科學教育常要求學生改變思考方式。"},{"en":"Ways of thinking are the habits people use to understand, explain, and solve problems.","zh":"思考方式是人們用來理解、解釋和解決問題的思維習慣。"},{"en":"A child may change their way of thinking when they learn that heavier objects do not always fall faster.","zh":"當孩子學到較重物件不一定下墜較快時，可能會改變思考方式。"},{"en":"New ways of thinking can make old explanations seem incomplete or wrong.","zh":"新的思考方式可以令舊解釋顯得不完整或錯誤。"},{"en":"This phrase refers to mental patterns, not just individual opinions.","zh":"這個短語指思維模式，而不只是個別意見。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":1},{"front":"it has also been emphasised that","meaning":"亦有人強調","examples":[{"en":"It has also been emphasised that science learning may require conceptual change.","zh":"亦有人強調，科學學習可能需要概念轉變。"},{"en":"It has also been emphasised that means another important point has been strongly highlighted.","zh":"亦有人強調，是指另一個重要觀點被強烈指出。"},{"en":"It has also been emphasised that students need practice, not only clear explanations.","zh":"亦有人強調，學生需要練習，而不只是清楚解釋。"},{"en":"This phrase adds a further point that writers want readers to notice.","zh":"這個短語加入作者希望讀者注意的另一重點。"},{"en":"It is formal and often appears in academic discussion.","zh":"它較正式，常見於學術討論。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":1},{"front":"in order to","meaning":"為了","examples":[{"en":"In order to learn science, students often need to rethink everyday ideas.","zh":"為了學習科學，學生常需要重新思考日常想法。"},{"en":"In order to means for the purpose of doing something.","zh":"為了，是指以做某事為目的。"},{"en":"In order to improve speaking, students need chances to answer real questions.","zh":"為了改善口語，學生需要有機會回答真實問題。"},{"en":"This phrase clearly connects an action with its purpose.","zh":"這個短語清楚連接行動與目的。"},{"en":"It is slightly more formal than simply saying “to.”","zh":"它比單純說 “to” 稍為正式。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":1},{"front":"change the way they think","meaning":"改變思考方式","examples":[{"en":"People often have to change the way they think in ordinary situations.","zh":"人們在日常情境中常常要改變思考方式。"},{"en":"To change the way they think means to replace an old mental habit with a new understanding.","zh":"改變思考方式，是指用新的理解取代舊的思維習慣。"},{"en":"A student may change the way they think about mistakes after learning that mistakes can guide improvement.","zh":"學生學到錯誤可以引導改進後，可能改變自己對錯誤的思考方式。"},{"en":"Changing thinking is difficult because familiar ideas feel natural and safe.","zh":"改變思考方式很困難，因為熟悉想法感覺自然又安全。"},{"en":"This phrase describes deep learning, not just adding new facts.","zh":"這個短語描述深入學習，而不只是增加新事實。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":1},{"front":"ordinary situations","meaning":"日常情境","examples":[{"en":"Scientific ideas may differ from the way people think in ordinary situations.","zh":"科學概念可能不同於人們在日常情境中的思考方式。"},{"en":"Ordinary situations are everyday events that people meet in normal life.","zh":"日常情境是人們在正常生活中遇到的 everyday 事件。"},{"en":"Pouring hot tea into a cold cup is an ordinary situation that can teach heat transfer.","zh":"把熱茶倒入冷杯，是可以用來教授熱傳遞的日常情境。"},{"en":"Students may use everyday thinking in ordinary situations, even when science requires another explanation.","zh":"學生在日常情境中可能使用生活化思維，即使科學需要另一種解釋。"},{"en":"This phrase contrasts daily experience with formal scientific reasoning.","zh":"這個短語把日常經驗與正式科學推理作對比。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":1},{"front":"simple concepts","meaning":"簡單概念","examples":[{"en":"Even simple concepts such as heat and temperature can be difficult to understand.","zh":"即使像熱和溫度這樣的簡單概念，也可能難以理解。"},{"en":"Simple concepts are ideas that look basic but may still need careful explanation.","zh":"簡單概念是看似基本但仍可能需要仔細解釋的想法。"},{"en":"“Speed” seems like a simple concept until students must explain distance and time together.","zh":"「速度」看似簡單概念，直到學生必須一起解釋距離和時間。"},{"en":"Simple concepts can be misunderstood when everyday language hides scientific differences.","zh":"當日常語言掩蓋科學差異時，簡單概念也可能被誤解。"},{"en":"This phrase warns that easy-looking ideas are not always easy to learn.","zh":"這個短語提醒人，看似容易的概念不一定容易學會。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":1},{"front":"heat and temperature","meaning":"熱和溫度","examples":[{"en":"Students need to learn the distinction between heat and temperature.","zh":"學生需要學會熱和溫度之間的區別。"},{"en":"Heat and temperature are related ideas, but they do not mean exactly the same thing.","zh":"熱和溫度是相關概念，但意思並不完全相同。"},{"en":"A small cup of hot tea can have a high temperature but less heat than a full pot.","zh":"一小杯熱茶可以有高溫度，但熱量少於一整壺茶。"},{"en":"Confusing heat and temperature can lead students to give wrong scientific explanations.","zh":"混淆熱和溫度會令學生給出錯誤科學解釋。"},{"en":"This phrase is often used to show why scientific concepts need careful definition.","zh":"這個短語常用來顯示科學概念為何需要仔細定義。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":2},{"front":"a measure of","meaning":"……的量度","examples":[{"en":"Temperature should not simply be treated as a measure of heat.","zh":"溫度不應被簡單視為熱的量度。"},{"en":"A measure of something is a way to show its amount, level, or degree.","zh":"某物的量度，是顯示其數量、水平或程度的方法。"},{"en":"Exam scores are one measure of progress, but they are not the only one.","zh":"考試分數是進步的一種量度，但不是唯一量度。"},{"en":"A poor measure can mislead people because it hides important differences.","zh":"差劣量度會誤導人，因為它隱藏重要差異。"},{"en":"This phrase is useful when explaining what a number or indicator represents.","zh":"當解釋數字或指標代表甚麼時，這個短語很有用。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":2},{"front":"must be abandoned","meaning":"必須被拋棄","examples":[{"en":"The idea of temperature as a measure of heat must be abandoned.","zh":"把溫度視為熱的量度這個想法必須被拋棄。"},{"en":"If an idea must be abandoned, people need to stop using it because it is wrong or unhelpful.","zh":"如果一個想法必須被拋棄，人們就需要停止使用它，因為它錯誤或沒有幫助。"},{"en":"A student must abandon the idea that every English sentence needs the same word order as Chinese.","zh":"學生必須拋棄每個英文句子都需要跟中文相同語序的想法。"},{"en":"Old ideas are hard to abandon when they seem to work in everyday life.","zh":"當舊想法在日常生活中看似有效時，就很難被拋棄。"},{"en":"This phrase describes giving up a belief, not simply forgetting a fact.","zh":"這個短語描述放棄一種信念，而不只是忘記一項事實。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":2},{"front":"make a distinction between","meaning":"區分……與……","examples":[{"en":"Students must learn to make a distinction between temperature and heat.","zh":"學生必須學會區分溫度與熱。"},{"en":"To make a distinction between two things means to clearly show how they are different.","zh":"區分兩件事，是指清楚顯示它們有何不同。"},{"en":"A teacher may make a distinction between formal writing and casual messages.","zh":"老師可能區分正式寫作與日常訊息。"},{"en":"Clear distinctions prevent students from using similar words wrongly.","zh":"清楚區分可以防止學生錯誤使用相似詞語。"},{"en":"This phrase is useful when two ideas are related but not identical.","zh":"當兩個概念相關但不相同時，這個短語很有用。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":2},{"front":"a distinction between…and…","meaning":"……與……之間的區別","examples":[{"en":"A distinction between temperature and heat must be learned.","zh":"必須學會溫度與熱之間的區別。"},{"en":"A distinction between two things is a clear difference that people need to notice.","zh":"兩者之間的區別，是人們需要注意到的清楚差異。"},{"en":"There is a distinction between being busy and being productive.","zh":"忙碌與有生產力之間有區別。"},{"en":"Understanding a distinction helps people avoid oversimplifying a problem.","zh":"理解區別有助人避免過度簡化問題。"},{"en":"This phrase often introduces an important conceptual difference.","zh":"這個短語常引入重要概念差異。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":2},{"front":"be referred to as","meaning":"被稱為","examples":[{"en":"These changes in thinking are referred to as conceptual changes.","zh":"這些思考上的改變被稱為概念轉變。"},{"en":"To be referred to as something means to be called by that name.","zh":"被稱為某物，是指用那個名稱來稱呼。"},{"en":"A young company that grows quickly may be referred to as a start-up.","zh":"一間快速成長的年輕公司可能被稱為初創企業。"},{"en":"Technical terms help people refer to complex ideas more precisely.","zh":"專門術語幫助人更準確稱呼複雜概念。"},{"en":"This phrase introduces the name used for a concept.","zh":"這個短語引入某概念所使用的名稱。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":2},{"front":"conceptual changes","meaning":"概念轉變","examples":[{"en":"Conceptual changes occur when students alter their basic ways of thinking.","zh":"當學生改變基本思考方式時，就會出現概念轉變。"},{"en":"Conceptual changes are deep changes in how people understand an idea.","zh":"概念轉變是人們理解某個想法的方式出現深層改變。"},{"en":"A child makes a conceptual change when they realise the Earth moves around the Sun.","zh":"孩子意識到地球繞太陽運行時，就是發生概念轉變。"},{"en":"Conceptual changes can be slow because old explanations may feel familiar.","zh":"概念轉變可能很慢，因為舊解釋可能感覺熟悉。"},{"en":"This phrase refers to changing mental frameworks, not just learning new vocabulary.","zh":"這個短語指改變思維框架，而不只是學新詞彙。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":2},{"front":"as they develop","meaning":"隨着他們成長","examples":[{"en":"Young people change their thinking as they develop.","zh":"年輕人隨着成長會改變思考方式。"},{"en":"As they develop means while they grow older, learn more, or become more mature.","zh":"隨着他們成長，是指當他們長大、學得更多或變得更成熟時。"},{"en":"Children become better at explaining reasons as they develop.","zh":"孩子隨着成長，會更善於解釋原因。"},{"en":"Development can change how learners solve problems and judge evidence.","zh":"成長可以改變學習者解決問題和判斷證據的方式。"},{"en":"This phrase links change with growth over time.","zh":"這個短語把變化與時間中的成長連接起來。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":2},{"front":"learn in school","meaning":"在學校學習","examples":[{"en":"Students may change their thinking as they learn in school.","zh":"學生在學校學習時，可能會改變思考方式。"},{"en":"To learn in school means to gain knowledge and skills through lessons and classroom activities.","zh":"在學校學習，是指透過課堂和學校活動獲得知識和技能。"},{"en":"Children learn in school when teachers guide them through reading, experiments, and discussion.","zh":"當老師透過閱讀、實驗和討論引導孩子時，他們就在學校學習。"},{"en":"School learning can challenge everyday ideas and replace them with more accurate concepts.","zh":"學校學習可以挑戰日常想法，並以更準確概念取代它們。"},{"en":"This phrase refers to formal education, not casual learning at home.","zh":"這個短語指正式教育，而不是在家中的隨意學習。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":2},{"front":"traditional instruction","meaning":"傳統教學","examples":[{"en":"Traditional instruction does not always produce deep understanding.","zh":"傳統教學不一定產生深入理解。"},{"en":"Traditional instruction is teaching that often relies on explanation, demonstration, and memorisation.","zh":"傳統教學是常依靠講解、示範和記憶的教學方式。"},{"en":"A traditional lesson may tell students the formula before they test the idea themselves.","zh":"傳統課堂可能先告訴學生公式，而不是讓他們自己測試概念。"},{"en":"Traditional instruction can be efficient, but it may leave old misconceptions unchanged.","zh":"傳統教學可以有效率，但可能令舊誤解保持不變。"},{"en":"This phrase contrasts with more active approaches such as discovery learning.","zh":"這個短語與發現式學習等更主動的方法形成對比。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":2},{"front":"based on","meaning":"以……為基礎","examples":[{"en":"Traditional instruction is often based on telling students how scientists think.","zh":"傳統教學常以告訴學生現代科學家如何思考為基礎。"},{"en":"Based on means built from or depending on a particular idea, fact, or method.","zh":"以某物為基礎，是指建立於或依靠某個想法、事實或方法。"},{"en":"A school rule may be based on safety concerns after an accident.","zh":"學校規則可能以事故後的安全顧慮為基礎。"},{"en":"If teaching is based only on explanation, students may not test ideas for themselves.","zh":"如果教學只以講解為基礎，學生可能不會親自測試想法。"},{"en":"This phrase shows the foundation of a method or argument.","zh":"這個短語顯示方法或論點的基礎。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":2},{"front":"modern scientists","meaning":"現代科學家","examples":[{"en":"Students are sometimes told how modern scientists think.","zh":"學生有時會被告知現代科學家如何思考。"},{"en":"Modern scientists are researchers who use current scientific methods to study the world.","zh":"現代科學家是使用當代科學方法研究世界的研究人員。"},{"en":"Modern scientists often test ideas through experiments, evidence, and careful measurement.","zh":"現代科學家常透過實驗、證據和仔細測量來測試想法。"},{"en":"Students may learn scientific language without truly thinking like modern scientists.","zh":"學生可能學會科學語言，卻未真正像現代科學家那樣思考。"},{"en":"This phrase refers to present-day scientific practice, not ancient belief.","zh":"這個短語指當代科學實踐，而不是古代信念。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":3},{"front":"does not seem to be","meaning":"似乎並不","examples":[{"en":"This kind of teaching does not seem to be very successful.","zh":"這種教學似乎並不十分成功。"},{"en":"Does not seem to be means appears not to be, though the speaker is somewhat cautious.","zh":"似乎並不，是指看起來不是如此，但說話者仍保持一定謹慎。"},{"en":"The new timetable does not seem to be helping students arrive earlier.","zh":"新時間表似乎並沒有幫助學生更早到達。"},{"en":"This phrase lets a writer make a careful judgement without sounding too absolute.","zh":"這個短語讓作者作出謹慎判斷，而不顯得過分絕對。"},{"en":"It is useful when evidence suggests a problem but does not prove every case.","zh":"當證據顯示有問題但未證明每個個案時，它很有用。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":3},{"front":"learn the definitions","meaning":"學會定義","examples":[{"en":"Students may learn the definitions without understanding the concepts.","zh":"學生可能學會定義，卻不理解概念。"},{"en":"To learn the definitions means to memorise what words or terms mean.","zh":"學會定義，是指記住詞語或術語的意思。"},{"en":"A student may learn the definition of “energy” but still fail to explain an experiment.","zh":"學生可能學會 “energy” 的定義，但仍未能解釋一個實驗。"},{"en":"Definitions help, but they do not guarantee real understanding.","zh":"定義有幫助，但不保證真正理解。"},{"en":"This phrase often contrasts word memory with conceptual use.","zh":"這個短語常把詞語記憶與概念運用作對比。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":3},{"front":"formulae","meaning":"公式","examples":[{"en":"Students may memorise formulae but fail to use the concepts behind them.","zh":"學生可能記住公式，卻未能使用其背後概念。"},{"en":"Formulae are mathematical rules written with symbols, numbers, or letters.","zh":"公式是用符號、數字或字母寫成的數學規則。"},{"en":"A physics student may use formulae to calculate speed, force, or energy.","zh":"物理學生可能用公式計算速度、力或能量。"},{"en":"Memorising formulae without meaning can lead to wrong use in unfamiliar questions.","zh":"沒有理解意思而記住公式，可能導致在陌生題目中錯用。"},{"en":"This word is the plural form of formula, often used in academic English.","zh":"這個詞是 formula 的複數形式，常見於學術英語。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":3},{"front":"terminology","meaning":"專門術語","examples":[{"en":"Students may learn the terminology of science without changing their thinking.","zh":"學生可能學會科學專門術語，卻沒有改變思考方式。"},{"en":"Terminology means the special words used in a subject or profession.","zh":"專門術語是某學科或專業中使用的特別詞語。"},{"en":"Medical terminology includes words such as diagnosis, symptom, and treatment.","zh":"醫學專門術語包括 diagnosis、symptom 和 treatment 等詞。"},{"en":"Learning terminology helps communication, but it does not always create understanding.","zh":"學會專門術語有助溝通，但不一定產生理解。"},{"en":"This phrase refers to specialist vocabulary.","zh":"這個短語指專業詞彙。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":3},{"front":"yet still maintain","meaning":"但仍然保持","examples":[{"en":"Students may learn scientific terminology and yet still maintain their old ideas.","zh":"學生可能學會科學專門術語，但仍然保持舊想法。"},{"en":"Yet still maintain means despite learning or experiencing something new, people continue to keep an old belief or habit.","zh":"但仍然保持，是指即使學到或經歷新事物，人們仍繼續保留舊信念或習慣。"},{"en":"A student may hear advice about sleep and yet still maintain a late-night routine.","zh":"學生可能聽過睡眠建議，但仍然保持深夜作息。"},{"en":"This phrase shows contrast between new input and unchanged thinking.","zh":"這個短語顯示新輸入與未改變思維之間的對比。"},{"en":"It is useful when learning appears successful on the surface but not underneath.","zh":"當學習表面上成功但內裡未改變時，這個短語很有用。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":3},{"front":"previous conceptions","meaning":"原有概念","examples":[{"en":"Students often maintain their previous conceptions after instruction.","zh":"學生在教學後常仍然保持原有概念。"},{"en":"Previous conceptions are ideas or beliefs students already had before new teaching.","zh":"原有概念是學生在新教學之前已經有的想法或信念。"},{"en":"A child may have the previous conception that heavier objects always fall faster.","zh":"孩子可能有「較重物件一定下墜較快」這個原有概念。"},{"en":"Previous conceptions can block learning when they conflict with scientific explanations.","zh":"當原有概念與科學解釋相衝突時，它們會阻礙學習。"},{"en":"This phrase is common in education research about misconceptions.","zh":"這個短語常見於關於誤解的教育研究。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":3},{"front":"this difficulty has been illustrated","meaning":"這個困難已被說明","examples":[{"en":"This difficulty has been illustrated many times in classroom research.","zh":"這個困難已在課堂研究中多次被說明。"},{"en":"This difficulty has been illustrated means the problem has been shown clearly through examples or evidence.","zh":"這個困難已被說明，是指問題已透過例子或證據清楚展示。"},{"en":"The difficulty of learning articles has been illustrated by many student writing samples.","zh":"學習冠詞的困難已由許多學生寫作樣本說明。"},{"en":"When a difficulty is illustrated repeatedly, it becomes harder to dismiss as rare.","zh":"當一個困難被反覆說明，就更難被視為罕見問題。"},{"en":"This phrase is used to introduce supporting evidence.","zh":"這個短語用來引入支持證據。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":3},{"front":"many times","meaning":"多次","examples":[{"en":"The problem has been observed many times in studies of science learning.","zh":"這個問題在科學學習研究中被多次觀察到。"},{"en":"Many times means repeatedly or on numerous occasions.","zh":"多次是指反覆或在許多場合。"},{"en":"Teachers have seen many times that students can copy answers without understanding them.","zh":"老師多次看見學生能抄答案卻不理解。"},{"en":"If something happens many times, researchers may treat it as a pattern.","zh":"如果某事發生多次，研究人員可能把它視為模式。"},{"en":"This phrase stresses repetition rather than a single example.","zh":"這個短語強調重複，而不是單一例子。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":3},{"front":"instructed students","meaning":"受過教導的學生","examples":[{"en":"Instructed students may still misunderstand heat and temperature.","zh":"受過教導的學生仍可能誤解熱和溫度。"},{"en":"Instructed students are students who have already received teaching on a topic.","zh":"受過教導的學生，是指已接受某主題教學的學生。"},{"en":"Instructed students may know the formula but still struggle with a real-life example.","zh":"受過教導的學生可能知道公式，但仍難以處理生活例子。"},{"en":"Teaching does not always remove misconceptions from instructed students.","zh":"教學不一定能消除受過教導學生的誤解。"},{"en":"This phrase contrasts students who have been taught with those who have not.","zh":"這個短語把已受教的學生與未受教的學生作對比。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":3},{"front":"be interviewed about","meaning":"被訪問有關……","examples":[{"en":"Students are often interviewed about heat and temperature.","zh":"學生常被訪問有關熱和溫度的問題。"},{"en":"To be interviewed about something means to be asked questions on that topic.","zh":"被訪問有關某事，是指被問及該主題。"},{"en":"Job applicants may be interviewed about their experience and problem-solving skills.","zh":"求職者可能被訪問有關經驗和解難能力。"},{"en":"Interviews can reveal what students really think beyond written answers.","zh":"訪問可以揭示學生在書面答案以外真正如何思考。"},{"en":"This phrase describes a method of collecting spoken information.","zh":"這個短語描述收集口頭資料的方法。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":3},{"front":"be identified by teachers as","meaning":"被教師識別為","examples":[{"en":"The problem is often identified by teachers as a difficulty in application.","zh":"這個問題常被教師識別為應用方面的困難。"},{"en":"To be identified by teachers as something means teachers recognise and describe it in that way.","zh":"被教師識別為某事，是指教師認出並以該方式描述它。"},{"en":"Poor punctuation may be identified by teachers as a common writing weakness.","zh":"標點差可能被教師識別為常見寫作弱點。"},{"en":"How teachers identify a problem affects how they try to solve it.","zh":"教師如何識別問題，會影響他們如何嘗試解決它。"},{"en":"This phrase introduces teachers’ interpretation of a learning difficulty.","zh":"這個短語引入教師對學習困難的理解。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":4},{"front":"difficulty in applying","meaning":"應用……方面的困難","examples":[{"en":"Students may have difficulty in applying concepts learned in class.","zh":"學生可能在應用課堂上學到的概念方面有困難。"},{"en":"Difficulty in applying something means trouble using knowledge in real or new situations.","zh":"應用某事方面的困難，是指難以在真實或新情境中使用知識。"},{"en":"A student may understand a grammar rule but have difficulty applying it in writing.","zh":"學生可能理解文法規則，但在寫作中應用它時有困難。"},{"en":"Application is harder when students memorise words without seeing examples.","zh":"當學生只記字而沒有看例子，應用會更困難。"},{"en":"This phrase describes the gap between knowing and using.","zh":"這個短語描述知道與使用之間的差距。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":4},{"front":"concepts learned in the classroom","meaning":"課堂上學到的概念","examples":[{"en":"Students may not apply concepts learned in the classroom to real events.","zh":"學生可能無法把課堂上學到的概念應用到真實事件。"},{"en":"Concepts learned in the classroom are ideas taught during formal lessons.","zh":"課堂上學到的概念，是指正式課堂中教授的想法。"},{"en":"A student may learn about friction in class but fail to connect it with bicycle brakes.","zh":"學生可能在課堂上學到摩擦力，卻未能把它與單車煞車連繫起來。"},{"en":"Classroom concepts become meaningful when learners use them outside the textbook.","zh":"當學習者在課本以外使用概念時，課堂概念才變得有意義。"},{"en":"This phrase contrasts school learning with real-world application.","zh":"這個短語把學校學習與現實應用作對比。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":4},{"front":"be able to repeat","meaning":"能夠複述","examples":[{"en":"A student may be able to repeat a formula without understanding it.","zh":"學生可能能夠複述公式，但不理解它。"},{"en":"To be able to repeat something means to say it again from memory.","zh":"能夠複述某事，是指能憑記憶再次說出它。"},{"en":"A child may be able to repeat a poem but not explain its meaning.","zh":"孩子可能能夠複述一首詩，卻不能解釋其意思。"},{"en":"Repetition can hide misunderstanding if teachers do not ask students to apply ideas.","zh":"如果老師不要求學生應用概念，複述可能掩蓋誤解。"},{"en":"This phrase describes memory, not necessarily understanding.","zh":"這個短語描述記憶，而不一定是理解。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":4},{"front":"fail to use","meaning":"未能使用","examples":[{"en":"Students may fail to use the concept represented by the formula.","zh":"學生可能未能使用由公式代表的概念。"},{"en":"To fail to use something means to not use it when it is needed.","zh":"未能使用某物，是指在需要時沒有使用它。"},{"en":"A driver may fail to use mirrors before changing lanes.","zh":"司機變線前可能未能使用倒後鏡。"},{"en":"Students may fail to use a concept if they only memorised its definition.","zh":"如果學生只記住定義，可能未能使用概念。"},{"en":"This phrase points to unsuccessful application.","zh":"這個短語指出應用失敗。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":4},{"front":"be represented by","meaning":"由……代表","examples":[{"en":"The concept represented by the formula may not be used correctly.","zh":"由公式代表的概念可能沒有被正確使用。"},{"en":"To be represented by something means to be shown or expressed through it.","zh":"由某物代表，是指透過它顯示或表達。"},{"en":"On a map, a school may be represented by a small building symbol.","zh":"在地圖上，學校可能由一個小建築符號代表。"},{"en":"A formula represents a relationship, but students must understand what the symbols mean.","zh":"公式代表一種關係，但學生必須理解符號意思。"},{"en":"This phrase connects an idea with the sign or form used to show it.","zh":"這個短語把概念與用來顯示它的符號或形式連接起來。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":4},{"front":"observed events","meaning":"觀察到的事件","examples":[{"en":"Students use scientific concepts to explain observed events.","zh":"學生使用科學概念來解釋觀察到的事件。"},{"en":"Observed events are things that people have seen, measured, or noticed directly.","zh":"觀察到的事件，是指人們直接看見、量度或注意到的事情。"},{"en":"A student may use science to explain why ice melts in a warm room.","zh":"學生可能用科學解釋為何冰在溫暖房間中融化。"},{"en":"Observed events help test whether a concept really works in practice.","zh":"觀察到的事件有助測試概念在實際中是否真正有效。"},{"en":"This phrase refers to real evidence rather than imagined examples.","zh":"這個短語指真實證據，而不是想像例子。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":4},{"front":"psychologist","meaning":"心理學家","examples":[{"en":"The psychologist Piaget proposed a theory of cognitive change.","zh":"心理學家皮亞傑提出了認知轉變理論。"},{"en":"A psychologist is a person who studies the mind, behaviour, learning, and emotion.","zh":"心理學家是研究心理、行為、學習和情緒的人。"},{"en":"A school psychologist may help students who struggle with anxiety or attention.","zh":"學校心理學家可能幫助有焦慮或專注困難的學生。"},{"en":"Psychologists study how children think so teaching can match development.","zh":"心理學家研究孩子如何思考，使教學能配合發展。"},{"en":"This word refers to a specialist in human thought and behaviour.","zh":"這個詞指研究人類思維和行為的專家。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":4},{"front":"suggest a hypothesis","meaning":"提出假說","examples":[{"en":"Piaget suggested a hypothesis about cognitive change in children.","zh":"皮亞傑提出了關於兒童認知轉變的假說。"},{"en":"To suggest a hypothesis means to propose a possible explanation that can be examined.","zh":"提出假說，是指提出一個可被檢驗的可能解釋。"},{"en":"A doctor may suggest a hypothesis about why a patient keeps feeling tired.","zh":"醫生可能提出假說，解釋病人為何一直感到疲倦。"},{"en":"A hypothesis is not a final answer; it needs evidence and testing.","zh":"假說不是最終答案；它需要證據和測試。"},{"en":"This phrase is common in scientific and academic discussion.","zh":"這個短語常見於科學和學術討論。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":4},{"front":"relating to","meaning":"與……有關","examples":[{"en":"The hypothesis related to the process of cognitive change.","zh":"這個假說與認知轉變的過程有關。"},{"en":"Relating to means connected with or about a particular topic.","zh":"與某事有關，是指與某個主題相連或關於該主題。"},{"en":"A school may send parents information relating to exam arrangements.","zh":"學校可能向家長發送與考試安排有關的資訊。"},{"en":"When evidence relates to a theory, it may support or challenge that theory.","zh":"當證據與理論有關，它可能支持或挑戰該理論。"},{"en":"This phrase is a formal way to show connection.","zh":"這個短語是表示連繫的正式說法。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":4},{"front":"process of cognitive change","meaning":"認知轉變的過程","examples":[{"en":"Piaget studied the process of cognitive change in children.","zh":"皮亞傑研究兒童認知轉變的過程。"},{"en":"The process of cognitive change is the way thinking develops or shifts over time.","zh":"認知轉變的過程，是思維隨時間發展或轉變的方式。"},{"en":"A child’s process of cognitive change can be seen when they move from guessing to explaining.","zh":"當孩子從猜測轉向解釋時，可以看見其認知轉變過程。"},{"en":"This process may involve conflict, questioning, and rebuilding ideas.","zh":"這個過程可能涉及衝突、提問和重建想法。"},{"en":"The phrase focuses on how mental development happens, not just the final result.","zh":"這個短語聚焦心智發展如何發生，而不只是最終結果。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":4},{"front":"cognitive change","meaning":"認知轉變","examples":[{"en":"Cognitive change may result from a child’s own intellectual activity.","zh":"認知轉變可能源於孩子自己的智力活動。"},{"en":"Cognitive change means a change in how someone thinks, reasons, or understands.","zh":"認知轉變是指某人思考、推理或理解方式的改變。"},{"en":"A student shows cognitive change when they stop believing that bigger always means heavier.","zh":"當學生不再相信越大一定越重時，就顯示認知轉變。"},{"en":"Cognitive change often happens when old ideas cannot explain new evidence.","zh":"當舊想法無法解釋新證據時，常會出現認知轉變。"},{"en":"This phrase is central to theories of learning and development.","zh":"這個短語是學習和發展理論的核心。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":5},{"front":"be expected to result from","meaning":"預期源於","examples":[{"en":"Cognitive change was expected to result from pupils’ own thinking.","zh":"認知轉變被預期源於學生自己的思考。"},{"en":"To be expected to result from something means to be thought likely to come from it.","zh":"預期源於某事，是指被認為很可能由它產生。"},{"en":"Better confidence is expected to result from regular speaking practice.","zh":"更好的信心預期源於定期口語練習。"},{"en":"If learning is expected to result from active thinking, passive listening may not be enough.","zh":"如果學習被預期源於主動思考，被動聆聽可能不足夠。"},{"en":"This phrase connects an expected outcome with its cause.","zh":"這個短語把預期結果與原因連接起來。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":5},{"front":"intellectual activity","meaning":"智力活動","examples":[{"en":"Piaget believed that children’s intellectual activity could produce cognitive change.","zh":"皮亞傑相信兒童的智力活動可以產生認知轉變。"},{"en":"Intellectual activity means mental work such as thinking, reasoning, comparing, and solving problems.","zh":"智力活動是指思考、推理、比較和解決問題等心智工作。"},{"en":"Reading a difficult article and explaining it in your own words is intellectual activity.","zh":"閱讀一篇困難文章並用自己的話解釋，就是智力活動。"},{"en":"Intellectual activity helps learners build understanding instead of only receiving answers.","zh":"智力活動幫助學習者建立理解，而不是只接收答案。"},{"en":"This phrase refers to active thinking by the learner.","zh":"這個短語指學習者的主動思考。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":5},{"front":"be confronted with","meaning":"面對","examples":[{"en":"Pupils may change their thinking when they are confronted with a challenging result.","zh":"當學生面對具挑戰性的結果時，可能會改變思考方式。"},{"en":"To be confronted with something means to face it directly, often when it is difficult or surprising.","zh":"面對某事，是指直接遇上它，通常是困難或令人意外的事。"},{"en":"A manager may be confronted with complaints after a service failure.","zh":"服務失誤後，經理可能面對投訴。"},{"en":"Students confronted with unexpected evidence may need to rethink their answer.","zh":"學生面對意外證據時，可能需要重新思考答案。"},{"en":"This phrase describes meeting a challenge that cannot easily be ignored.","zh":"這個短語描述遇到不能輕易忽視的挑戰。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":5},{"front":"challenge one’s thinking","meaning":"挑戰某人的思維","examples":[{"en":"A surprising result can challenge a pupil’s thinking.","zh":"令人驚訝的結果可以挑戰學生的思維。"},{"en":"To challenge someone’s thinking means to make them question their existing ideas.","zh":"挑戰某人的思維，是指令他們質疑原有想法。"},{"en":"A debate can challenge a student’s thinking if classmates give strong evidence.","zh":"如果同學提出有力證據，辯論可以挑戰學生的思維。"},{"en":"Challenging thinking can feel uncomfortable, but it can lead to better understanding.","zh":"思維被挑戰可能令人不舒服，但可以帶來更好理解。"},{"en":"This phrase is used when learning disturbs old assumptions.","zh":"當學習打亂舊假設時，可以使用這個短語。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":5},{"front":"that is","meaning":"也就是說","examples":[{"en":"When pupils face conflict, that is, when evidence challenges them, they may rethink.","zh":"當學生面對衝突，也就是說，當證據挑戰他們時，他們可能重新思考。"},{"en":"That is means in other words or more specifically.","zh":"也就是說，是指換句話說或更具體地說。"},{"en":"Some students need scaffolding, that is, step-by-step support before working alone.","zh":"有些學生需要 scaffolding，也就是說，在獨立工作前需要逐步支援。"},{"en":"This phrase helps clarify a difficult or technical idea.","zh":"這個短語幫助澄清困難或技術性概念。"},{"en":"It is useful when the writer wants to restate something more plainly.","zh":"當作者想用更清楚方式重述某事時，它很有用。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":5},{"front":"be faced with conflict","meaning":"面對衝突","examples":[{"en":"Pupils may make progress when they are faced with conflict.","zh":"學生面對衝突時可能取得進步。"},{"en":"To be faced with conflict means to meet a situation where ideas, evidence, or people disagree.","zh":"面對衝突，是指遇到想法、證據或人之間不一致的情況。"},{"en":"A team is faced with conflict when two members suggest opposite plans.","zh":"當兩名成員提出相反計劃，團隊就面對衝突。"},{"en":"Conflict can push learners to explain, defend, or revise their ideas.","zh":"衝突可以推動學習者解釋、捍衛或修正想法。"},{"en":"This phrase describes a difficult but potentially useful learning situation.","zh":"這個短語描述困難但可能有益的學習情境。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":5},{"front":"think again about","meaning":"重新思考","examples":[{"en":"Pupils need to think again about their ways of solving problems.","zh":"學生需要重新思考他們解決問題的方法。"},{"en":"To think again about something means to reconsider it because new evidence or difficulty appears.","zh":"重新思考某事，是指因新證據或困難出現而再次考慮它。"},{"en":"A student may think again about a study plan after failing a mock exam.","zh":"學生模擬考失敗後，可能重新思考溫習計劃。"},{"en":"Rethinking helps people notice weaknesses in old methods.","zh":"重新思考幫助人注意舊方法的弱點。"},{"en":"This phrase suggests reflection, not simple repetition.","zh":"這個短語暗示反思，而不是單純重複。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":5},{"front":"ways of solving problems","meaning":"解決問題的方法","examples":[{"en":"Children may need to change their ways of solving problems.","zh":"孩子可能需要改變解決問題的方法。"},{"en":"Ways of solving problems are the methods people use to find answers or deal with difficulties.","zh":"解決問題的方法，是人們用來找答案或處理困難的方式。"},{"en":"A student may solve a maths problem by drawing a diagram instead of guessing.","zh":"學生可以透過畫圖而不是猜測來解數學題。"},{"en":"New ways of solving problems can appear when old methods fail.","zh":"當舊方法失效，新解難方法可能出現。"},{"en":"This phrase focuses on process, not only the final answer.","zh":"這個短語聚焦過程，而不只是最後答案。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":5},{"front":"regardless of whether","meaning":"不論是否","examples":[{"en":"Pupils may face conflict regardless of whether the problem is mathematical or scientific.","zh":"不論問題是數學還是科學，學生都可能面對衝突。"},{"en":"Regardless of whether means it does not matter if one condition is true or not.","zh":"不論是否，是指某條件是否成立都不重要。"},{"en":"Students should check their work regardless of whether the exam feels easy or hard.","zh":"不論考試感覺容易還是困難，學生都應檢查答案。"},{"en":"This phrase shows that the main point applies in both cases.","zh":"這個短語顯示主要觀點適用於兩種情況。"},{"en":"It is useful when a rule or result is not limited by a condition.","zh":"當規則或結果不受某條件限制時，它很有用。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":5},{"front":"hypothesise that","meaning":"假設；提出假說認為","examples":[{"en":"Piaget hypothesised that conflict brings about disequilibrium.","zh":"皮亞傑提出假說認為，衝突會引起失衡狀態。"},{"en":"To hypothesise that means to suggest a possible explanation that needs evidence.","zh":"假設某事，是指提出一個需要證據支持的可能解釋。"},{"en":"A researcher may hypothesise that sleep improves memory in young children.","zh":"研究人員可能提出假說認為睡眠改善幼兒記憶。"},{"en":"A hypothesis guides investigation, but it must still be tested.","zh":"假說引導研究，但仍必須被測試。"},{"en":"This phrase is formal and common in research writing.","zh":"這個短語較正式，常見於研究寫作。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":5},{"front":"bring about","meaning":"引起；導致","examples":[{"en":"Conflict can bring about disequilibrium in a learner’s thinking.","zh":"衝突可以在學習者思維中引起失衡狀態。"},{"en":"To bring about something means to cause it to happen.","zh":"引起某事，是指導致它發生。"},{"en":"A new school rule can bring about better punctuality if students understand it.","zh":"如果學生理解新校規，它可以帶來更好準時情況。"},{"en":"Evidence that contradicts old ideas can bring about deep learning.","zh":"與舊想法矛盾的證據可以引起深入學習。"},{"en":"This phrase connects a cause with a result.","zh":"這個短語把原因與結果連接起來。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":6},{"front":"disequilibrium","meaning":"失衡狀態","examples":[{"en":"Disequilibrium may occur when new evidence conflicts with a learner’s ideas.","zh":"當新證據與學習者的想法相衝突時，可能出現失衡狀態。"},{"en":"Disequilibrium is a state of mental imbalance or uncertainty caused by conflict.","zh":"失衡狀態是由衝突造成的心理不平衡或不確定。"},{"en":"A child may feel disequilibrium when a science experiment gives an unexpected result.","zh":"當科學實驗出現意外結果時，孩子可能感到失衡。"},{"en":"This discomfort can push learners to rebuild their understanding.","zh":"這種不適可以推動學習者重建理解。"},{"en":"The word describes a temporary mental disturbance that may lead to learning.","zh":"這個詞描述可能導致學習的暫時心理擾動。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":6},{"front":"trigger","meaning":"觸發","examples":[{"en":"Conflict can trigger processes that lead to cognitive change.","zh":"衝突可以觸發導致認知轉變的過程。"},{"en":"To trigger something means to start or cause it suddenly.","zh":"觸發某事，是指突然開始或引起它。"},{"en":"A teacher’s question can trigger a lively discussion in class.","zh":"老師的一個問題可以觸發課堂上的熱烈討論。"},{"en":"A surprising result can trigger doubt about an old explanation.","zh":"令人意外的結果可以觸發對舊解釋的懷疑。"},{"en":"This verb is useful when one event sets another process in motion.","zh":"當一個事件啟動另一個過程時，可以使用這個動詞。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":6},{"front":"equilibration processes","meaning":"平衡化過程","examples":[{"en":"Piaget believed that equilibration processes could ultimately produce cognitive change.","zh":"皮亞傑相信平衡化過程最終可以產生認知轉變。"},{"en":"Equilibration processes are mental adjustments that help learners restore balance after conflict.","zh":"平衡化過程是學習者在衝突後恢復心理平衡的心智調整。"},{"en":"A child may adjust an old idea after repeated experiments challenge it.","zh":"孩子在反覆實驗挑戰舊想法後，可能調整原有概念。"},{"en":"These processes matter because confusion alone does not guarantee learning.","zh":"這些過程重要，因為混亂本身不保證學習。"},{"en":"This phrase belongs to Piaget’s theory of cognitive development.","zh":"這個短語屬於皮亞傑的認知發展理論。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":6},{"front":"ultimately produce","meaning":"最終產生","examples":[{"en":"Equilibration processes may ultimately produce cognitive change.","zh":"平衡化過程可能最終產生認知轉變。"},{"en":"Ultimately produce means eventually cause or create something after a process.","zh":"最終產生，是指經過一個過程後最終造成或創造某事。"},{"en":"Regular feedback may ultimately produce stronger writing skills.","zh":"定期回饋可能最終產生更強的寫作能力。"},{"en":"Learning may not change thinking immediately, but it can produce change later.","zh":"學習未必立即改變思維，但之後可以產生改變。"},{"en":"This phrase emphasises the final result after time and effort.","zh":"這個短語強調時間和努力之後的最後結果。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":6},{"front":"according to","meaning":"根據","examples":[{"en":"According to Piaget, pupils need to solve challenging problems.","zh":"根據皮亞傑，學生需要解決具挑戰性的問題。"},{"en":"According to someone means based on what that person says or believes.","zh":"根據某人，是指基於那個人所說或相信的內容。"},{"en":"According to the teacher, students should explain every answer with evidence.","zh":"根據老師所說，學生應用證據解釋每個答案。"},{"en":"This phrase is used to report a source without making it your own opinion.","zh":"這個短語用來報告來源，而不把它變成自己的意見。"},{"en":"It helps readers know whose view is being presented.","zh":"它幫助讀者知道正在呈現的是誰的觀點。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":6},{"front":"in order for someone to","meaning":"為了讓某人","examples":[{"en":"In order for pupils to progress, they must be actively engaged.","zh":"為了讓學生進步，他們必須積極參與。"},{"en":"In order for someone to do something means so that the person can achieve that result.","zh":"為了讓某人做某事，是指使那個人能達成該結果。"},{"en":"In order for students to improve, they need feedback they can understand.","zh":"為了讓學生進步，他們需要能理解的回饋。"},{"en":"This phrase links a required condition with a desired outcome.","zh":"這個短語把必要條件與想要的結果連接起來。"},{"en":"It is more formal than simply saying “for someone to.”","zh":"它比單純說 “for someone to” 更正式。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":6},{"front":"progress in one’s thinking","meaning":"思維上取得進步","examples":[{"en":"Pupils progress in their thinking by confronting difficult problems.","zh":"學生透過面對困難問題在思維上取得進步。"},{"en":"To progress in one’s thinking means to develop better reasoning or understanding.","zh":"在思維上取得進步，是指發展出更好的推理或理解。"},{"en":"A student progresses in thinking when they learn to explain why an answer works.","zh":"當學生學會解釋答案為何有效時，就是在思維上取得進步。"},{"en":"Progress in thinking often requires mistakes, feedback, and reflection.","zh":"思維進步通常需要錯誤、回饋和反思。"},{"en":"This phrase focuses on mental development rather than exam marks alone.","zh":"這個短語聚焦心智發展，而不只是考試分數。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":6},{"front":"be actively engaged in","meaning":"積極參與","examples":[{"en":"Pupils need to be actively engaged in solving problems.","zh":"學生需要積極參與解決問題。"},{"en":"To be actively engaged in something means to take part with attention and effort.","zh":"積極參與某事，是指帶着注意力和努力參與其中。"},{"en":"Students are actively engaged when they ask questions and test ideas themselves.","zh":"當學生提問並親自測試想法時，他們就是積極參與。"},{"en":"Active engagement helps learners build understanding instead of passively copying notes.","zh":"積極參與幫助學習者建立理解，而不是被動抄筆記。"},{"en":"This phrase is often used in education.","zh":"這個短語常用於教育。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":6},{"front":"solving problems","meaning":"解決問題","examples":[{"en":"Children develop by solving problems that challenge their reasoning.","zh":"孩子透過解決挑戰其推理的問題而發展。"},{"en":"Solving problems means finding answers or ways to deal with difficulties.","zh":"解決問題，是指找出答案或處理困難的方法。"},{"en":"A child solves a problem when they figure out why a toy car rolls faster on a slope.","zh":"當孩子弄明白玩具車為何在斜坡上滾得更快時，就是在解決問題。"},{"en":"Problem-solving can reveal gaps in understanding that memorisation hides.","zh":"解決問題可以揭示記憶所掩蓋的理解缺口。"},{"en":"This phrase describes active learning through challenge.","zh":"這個短語描述透過挑戰進行主動學習。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":6},{"front":"current mode of reasoning","meaning":"當前的推理方式","examples":[{"en":"Challenging tasks can disturb a pupil’s current mode of reasoning.","zh":"具挑戰性的任務可以打亂學生當前的推理方式。"},{"en":"A current mode of reasoning is the way a learner is presently thinking through a problem.","zh":"當前的推理方式，是學習者目前思考問題的方式。"},{"en":"A child may use a simple current mode of reasoning, such as “bigger means heavier.”","zh":"孩子可能使用簡單的當前推理方式，例如「越大代表越重」。"},{"en":"When evidence disturbs that reasoning, the child may need a new explanation.","zh":"當證據打亂這種推理，孩子可能需要新的解釋。"},{"en":"This phrase refers to a learner’s existing pattern of thought.","zh":"這個短語指學習者現有的思考模式。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":6},{"front":"point out that","meaning":"指出","examples":[{"en":"Piaget pointed out that children do not always abandon their ideas.","zh":"皮亞傑指出，孩子不一定會放棄自己的想法。"},{"en":"To point out that means to mention or draw attention to an important fact.","zh":"指出某事，是指提及或使人注意一個重要事實。"},{"en":"A teacher may point out that copying an answer is not the same as understanding it.","zh":"老師可能指出，抄答案不等於理解答案。"},{"en":"Pointing something out helps readers notice a detail they might miss.","zh":"指出某事幫助讀者注意可能錯過的細節。"},{"en":"This phrase is commonly used to introduce an observation.","zh":"這個短語常用來引入觀察。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":7},{"front":"discard ideas","meaning":"拋棄想法","examples":[{"en":"Young children do not always discard their ideas when evidence contradicts them.","zh":"當證據與想法相矛盾時，幼童不一定會拋棄自己的想法。"},{"en":"To discard ideas means to give up or reject them.","zh":"拋棄想法，是指放棄或拒絕它們。"},{"en":"A student may discard the idea that long sentences are always better after receiving feedback.","zh":"學生收到回饋後，可能拋棄「長句一定更好」這個想法。"},{"en":"People often resist discarding ideas that have worked for them before.","zh":"人們常抗拒拋棄曾經對自己有效的想法。"},{"en":"This phrase describes letting go of a belief or explanation.","zh":"這個短語描述放下一種信念或解釋。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":7},{"front":"in the face of","meaning":"面對……時","examples":[{"en":"Children may keep their theory in the face of contradictory evidence.","zh":"孩子在面對矛盾證據時，可能仍保留自己的理論。"},{"en":"In the face of something means when dealing with a difficult or opposing situation.","zh":"面對某事時，是指處理困難或相反的情況時。"},{"en":"A small shop stayed open in the face of rising rent and weak sales.","zh":"一間小店面對租金上升和銷售疲弱時仍然營業。"},{"en":"Learners may keep old ideas in the face of evidence because change feels uncomfortable.","zh":"學習者面對證據時仍可能保留舊想法，因為改變令人不舒服。"},{"en":"This phrase highlights resistance under pressure.","zh":"這個短語突出壓力下的抵抗。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":7},{"front":"contradictory evidence","meaning":"矛盾證據","examples":[{"en":"Children may reject contradictory evidence instead of changing their theory.","zh":"孩子可能拒絕矛盾證據，而不是改變自己的理論。"},{"en":"Contradictory evidence is information that goes against an existing idea or claim.","zh":"矛盾證據是與現有想法或主張相反的資料。"},{"en":"If a student thinks metal is always cold, warm metal gives contradictory evidence.","zh":"如果學生以為金屬永遠是冷的，溫暖的金屬就是矛盾證據。"},{"en":"Contradictory evidence can create conflict and force people to rethink.","zh":"矛盾證據可以造成衝突，迫使人重新思考。"},{"en":"This phrase is central to learning through challenge.","zh":"這個短語是透過挑戰學習的核心。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":7},{"front":"discard the evidence","meaning":"拋棄證據","examples":[{"en":"A child may discard the evidence and keep the theory.","zh":"孩子可能拋棄證據，並保留自己的理論。"},{"en":"To discard the evidence means to reject or ignore information that does not fit one’s belief.","zh":"拋棄證據，是指拒絕或忽視不符合自己信念的資料。"},{"en":"A person may discard evidence about health risks because they do not want to change habits.","zh":"一個人可能因不想改變習慣，而拋棄關於健康風險的證據。"},{"en":"Discarding evidence prevents learning because the old idea remains protected.","zh":"拋棄證據會阻礙學習，因為舊想法仍被保護。"},{"en":"This phrase describes rejecting facts instead of revising a theory.","zh":"這個短語描述拒絕事實，而不是修正理論。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":7},{"front":"keep their theory","meaning":"保留自己的理論","examples":[{"en":"Children may keep their theory even when evidence challenges it.","zh":"孩子即使在證據挑戰其理論時，也可能保留自己的理論。"},{"en":"To keep their theory means to continue believing an explanation.","zh":"保留自己的理論，是指繼續相信某個解釋。"},{"en":"A student may keep the theory that all heavy things sink until an experiment challenges it.","zh":"學生可能保留「所有重物都會下沉」的理論，直到實驗挑戰它。"},{"en":"People keep old theories when new evidence seems confusing or threatening.","zh":"當新證據令人困惑或感到威脅時，人們會保留舊理論。"},{"en":"This phrase shows resistance to conceptual change.","zh":"這個短語顯示對概念轉變的抗拒。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":7},{"front":"hypothesis about","meaning":"關於……的假說","examples":[{"en":"Piaget’s hypothesis about cognitive change influenced later education.","zh":"皮亞傑關於認知轉變的假說影響了後來的教育。"},{"en":"A hypothesis about something is a possible explanation concerning that topic.","zh":"關於某事的假說，是涉及該主題的可能解釋。"},{"en":"A teacher may form a hypothesis about why students struggle with reading speed.","zh":"老師可能形成關於學生閱讀速度困難原因的假說。"},{"en":"A useful hypothesis can guide new teaching methods and research.","zh":"有用的假說可以引導新教學方法和研究。"},{"en":"This phrase introduces the subject that the hypothesis tries to explain.","zh":"這個短語引入假說試圖解釋的主題。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":7},{"front":"be translated into","meaning":"被轉化為","examples":[{"en":"Piaget’s theory was later translated into an educational approach.","zh":"皮亞傑的理論後來被轉化為一種教育方法。"},{"en":"To be translated into something means to be changed into another form or practical use.","zh":"被轉化為某物，是指被改變成另一種形式或實際用途。"},{"en":"Research on memory can be translated into better study advice for students.","zh":"關於記憶的研究可以被轉化為更好的學生溫習建議。"},{"en":"A theory becomes useful in classrooms when it is translated into teaching practice.","zh":"當理論被轉化為教學實踐時，它才在課堂中變得有用。"},{"en":"This phrase does not always mean language translation; it can mean practical conversion.","zh":"這個短語不一定指語言翻譯；也可以指實際轉化。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":7},{"front":"educational approach","meaning":"教育方法","examples":[{"en":"Discovery learning became an important educational approach.","zh":"發現式學習成為重要的教育方法。"},{"en":"An educational approach is a general method or philosophy for teaching and learning.","zh":"教育方法是教與學的一般方法或理念。"},{"en":"Group discussion is an educational approach that encourages students to explain ideas aloud.","zh":"小組討論是一種鼓勵學生大聲解釋想法的教育方法。"},{"en":"Different approaches work better for different goals, ages, and subjects.","zh":"不同教育方法適合不同目標、年齡和學科。"},{"en":"This phrase refers to a broad teaching method, not one small activity.","zh":"這個短語指廣泛教學方法，而不是一個小活動。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":7},{"front":"be termed","meaning":"被稱為","examples":[{"en":"This educational approach is now termed discovery learning.","zh":"這種教育方法現在被稱為發現式學習。"},{"en":"To be termed something means to be given that name.","zh":"被稱為某物，是指被賦予那個名稱。"},{"en":"A sudden fall in market prices may be termed a crash.","zh":"市場價格突然下跌可能被稱為崩盤。"},{"en":"Naming an approach helps teachers discuss it clearly.","zh":"為一種方法命名，有助教師清楚討論它。"},{"en":"This phrase is formal and often used in academic explanation.","zh":"這個短語較正式，常用於學術解釋。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":7},{"front":"discovery learning","meaning":"發現式學習","examples":[{"en":"Discovery learning encourages pupils to learn through problem-solving.","zh":"發現式學習鼓勵學生透過解決問題來學習。"},{"en":"Discovery learning is an approach in which students learn by exploring, testing, and finding ideas themselves.","zh":"發現式學習是一種讓學生透過探索、測試和自行發現概念來學習的方法。"},{"en":"In a discovery-learning lesson, students may test which objects float before learning the rule.","zh":"在發現式學習課堂中，學生可能先測試哪些物件會浮起，再學習規則。"},{"en":"This approach can deepen understanding because learners actively build explanations.","zh":"這種方法可以加深理解，因為學習者主動建立解釋。"},{"en":"It contrasts with teaching that simply tells students the correct answer.","zh":"它與單純告訴學生正確答案的教學形成對比。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":7},{"front":"initially","meaning":"起初","examples":[{"en":"Discovery learning initially focused on the individual learner.","zh":"發現式學習起初集中於個別學習者。"},{"en":"Initially means at the beginning or in the early stage.","zh":"起初是指在開始時或早期階段。"},{"en":"Initially, a new student may feel nervous, but confidence can grow with practice.","zh":"起初，新學生可能感到緊張，但信心可以隨練習增長。"},{"en":"This word helps show how an idea or process later changed.","zh":"這個詞幫助顯示一個想法或過程後來如何改變。"},{"en":"It is useful when describing development over time.","zh":"它適合用來描述隨時間發展的情況。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":8},{"front":"be considered","meaning":"被認為","examples":[{"en":"The early approach is now considered the lone learner route.","zh":"早期方法現在被認為是單獨學習者路線。"},{"en":"To be considered something means to be regarded or thought of in that way.","zh":"被認為某物，是指被視為或被想成那樣。"},{"en":"A quiet library may be considered a good place for exam revision.","zh":"安靜圖書館可能被認為是溫習考試的好地方。"},{"en":"How something is considered can change when new research appears.","zh":"當新研究出現，人們對某事的看法可能改變。"},{"en":"This phrase introduces a judgement or classification.","zh":"這個短語引入判斷或分類。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":8},{"front":"the lone learner route","meaning":"單獨學習者路線","examples":[{"en":"Discovery learning initially took the lone learner route.","zh":"發現式學習起初採取單獨學習者路線。"},{"en":"The lone learner route is an approach that focuses on the individual student learning alone.","zh":"單獨學習者路線是一種集中於個別學生獨自學習的方法。"},{"en":"A child solving puzzles without classmates is following a lone learner route.","zh":"孩子不與同學合作而獨自解謎，就是採取單獨學習者路線。"},{"en":"This route may ignore how discussion with others helps thinking develop.","zh":"這條路線可能忽視與他人討論如何幫助思維發展。"},{"en":"The phrase contrasts individual learning with peer interaction.","zh":"這個短語把個人學習與同輩互動作對比。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":8},{"front":"the role of the teacher","meaning":"教師的角色","examples":[{"en":"The role of the teacher was to select challenging situations.","zh":"教師的角色是選擇具挑戰性的情境。"},{"en":"The role of the teacher means what the teacher is expected to do in learning.","zh":"教師的角色，是指教師在學習中被期望做甚麼。"},{"en":"In group work, the teacher’s role may be to guide discussion rather than give every answer.","zh":"在小組活動中，教師的角色可能是引導討論，而不是給出每個答案。"},{"en":"A clear teacher role helps students know how much support to expect.","zh":"清晰的教師角色幫助學生知道可以期待多少支援。"},{"en":"This phrase discusses responsibility inside a teaching method.","zh":"這個短語討論教學方法中的責任。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":8},{"front":"select situations","meaning":"選擇情境","examples":[{"en":"The teacher selected situations that challenged pupils’ reasoning.","zh":"教師選擇挑戰學生推理的情境。"},{"en":"To select situations means to choose particular tasks, examples, or contexts for learners.","zh":"選擇情境，是指為學習者挑選特定任務、例子或背景。"},{"en":"A teacher may select situations from daily life to explain scientific ideas.","zh":"老師可能從日常生活中選擇情境來解釋科學概念。"},{"en":"Carefully selected situations can reveal students’ misconceptions.","zh":"精心選擇的情境可以揭示學生的誤解。"},{"en":"This phrase shows planning by the teacher.","zh":"這個短語顯示教師的規劃。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":8},{"front":"challenge pupils’ reasoning","meaning":"挑戰學生的推理","examples":[{"en":"Teachers selected tasks that would challenge pupils’ reasoning.","zh":"教師選擇會挑戰學生推理的任務。"},{"en":"To challenge pupils’ reasoning means to make students question or improve how they think.","zh":"挑戰學生推理，是指令學生質疑或改善自己的思考方式。"},{"en":"A puzzle can challenge pupils’ reasoning if the obvious answer is wrong.","zh":"如果明顯答案是錯的，謎題可以挑戰學生推理。"},{"en":"Challenging reasoning can create productive confusion that leads to learning.","zh":"挑戰推理可以造成有益的困惑，從而帶來學習。"},{"en":"This phrase describes tasks designed to stretch students’ thinking.","zh":"這個短語描述旨在延展學生思維的任務。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":8},{"front":"pupils’ peers","meaning":"學生的同輩","examples":[{"en":"In the early model, pupils’ peers had no real role.","zh":"在早期模式中，學生的同輩沒有真正角色。"},{"en":"Pupils’ peers are classmates or children of a similar age and level.","zh":"學生的同輩是同學或年齡和程度相近的孩子。"},{"en":"A pupil may explain an answer differently after hearing a peer’s idea.","zh":"學生聽到同輩的想法後，可能以不同方式解釋答案。"},{"en":"Peers can influence learning because children often question one another naturally.","zh":"同輩可以影響學習，因為孩子常自然地互相提問。"},{"en":"This phrase refers to other students, not teachers.","zh":"這個短語指其他學生，而不是教師。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":8},{"front":"have no real role","meaning":"沒有真正角色","examples":[{"en":"Peers had no real role in the early discovery-learning process.","zh":"在早期發現式學習過程中，同輩沒有真正角色。"},{"en":"To have no real role means to not have any meaningful function or influence.","zh":"沒有真正角色，是指沒有有意義的功能或影響。"},{"en":"In some lessons, students have no real role except copying notes.","zh":"在有些課堂中，學生除了抄筆記外沒有真正角色。"},{"en":"If peers have no real role, learning is treated as an individual process.","zh":"如果同輩沒有真正角色，學習就被視為個人過程。"},{"en":"This phrase suggests that someone or something is present but not important.","zh":"這個短語暗示某人或某物存在，但不重要。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":8},{"front":"in this process","meaning":"在這個過程中","examples":[{"en":"Peers were not important in this process at first.","zh":"同輩起初在這個過程中並不重要。"},{"en":"In this process means during the series of actions or changes being discussed.","zh":"在這個過程中，是指在正在討論的一連串行動或變化之中。"},{"en":"In the writing process, feedback helps students improve the second draft.","zh":"在寫作過程中，回饋幫助學生改善第二稿。"},{"en":"Knowing who matters in a process helps explain how results happen.","zh":"知道誰在過程中重要，有助解釋結果如何發生。"},{"en":"This phrase points back to the process just described.","zh":"這個短語指回剛描述的過程。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":8},{"front":"be subsequently proposed","meaning":"其後有人提出","examples":[{"en":"It was subsequently proposed that peer conflict could help learning.","zh":"其後有人提出，同輩衝突可以幫助學習。"},{"en":"To be subsequently proposed means to be suggested later, after earlier ideas or research.","zh":"其後有人提出，是指在較早想法或研究之後，後來有人建議。"},{"en":"It was subsequently proposed that homework should include more reflection, not just drills.","zh":"其後有人提出，功課應包括更多反思，而不只是操練。"},{"en":"Later proposals can modify or extend an original theory.","zh":"後來提出的觀點可以修改或延伸原有理論。"},{"en":"This phrase shows development in academic thinking over time.","zh":"這個短語顯示學術思維隨時間發展。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":8},{"front":"interpersonal conflict","meaning":"人際衝突","examples":[{"en":"Interpersonal conflict may promote cognitive change.","zh":"人際衝突可能促進認知轉變。"},{"en":"Interpersonal conflict is disagreement or tension between people.","zh":"人際衝突是人與人之間的分歧或緊張。"},{"en":"Two students may experience interpersonal conflict when they defend different answers.","zh":"當兩名學生捍衛不同答案時，可能經歷人際衝突。"},{"en":"Conflict can help learning if it forces people to explain and compare ideas respectfully.","zh":"如果衝突迫使人尊重地解釋和比較想法，它可以幫助學習。"},{"en":"This phrase refers to conflict between individuals, not conflict inside one person’s mind.","zh":"這個短語指個人之間的衝突，而不是一個人內心的衝突。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":8},{"front":"especially with peers","meaning":"尤其是與同輩之間","examples":[{"en":"Conflict, especially with peers, may support cognitive development.","zh":"衝突，尤其是與同輩之間的衝突，可能支持認知發展。"},{"en":"Especially with peers means particularly when the interaction is with classmates or people of similar age.","zh":"尤其是與同輩之間，是指特別在互動對象是同學或年齡相近的人時。"},{"en":"Students may learn more from disagreement, especially with peers who explain ideas in familiar language.","zh":"學生可能從分歧中學得更多，尤其是與用熟悉語言解釋想法的同輩之間。"},{"en":"Peer conflict can feel more equal than teacher correction, so students may respond differently.","zh":"同輩衝突可能比教師糾正更平等，所以學生反應可能不同。"},{"en":"This phrase narrows a general idea to peer interaction.","zh":"這個短語把一般想法收窄到同輩互動。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":9},{"front":"play an important role in","meaning":"在……中發揮重要作用","examples":[{"en":"Peer interaction may play an important role in learning.","zh":"同輩互動可能在學習中發揮重要作用。"},{"en":"To play an important role in something means to be a major part of how it happens.","zh":"在某事中發揮重要作用，是指成為它如何發生的重要部分。"},{"en":"Sleep plays an important role in memory and concentration.","zh":"睡眠在記憶和專注中發揮重要作用。"},{"en":"If peer discussion affects understanding, it plays an important role in classroom learning.","zh":"如果同輩討論影響理解，它就在課堂學習中發揮重要作用。"},{"en":"This phrase highlights a key factor in a process.","zh":"這個短語突出過程中的關鍵因素。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":9},{"front":"promote cognitive change","meaning":"促進認知轉變","examples":[{"en":"Interpersonal conflict may promote cognitive change.","zh":"人際衝突可能促進認知轉變。"},{"en":"To promote cognitive change means to help learners develop new ways of thinking.","zh":"促進認知轉變，是指幫助學習者發展新的思考方式。"},{"en":"A debate can promote cognitive change when students must defend and revise ideas.","zh":"當學生必須捍衛和修正想法時，辯論可以促進認知轉變。"},{"en":"Conflict promotes learning only when students think carefully rather than simply argue.","zh":"只有當學生仔細思考而不是單純爭吵，衝突才會促進學習。"},{"en":"This phrase describes helping mental development happen.","zh":"這個短語描述幫助心智發展發生。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":9},{"front":"originally advanced by","meaning":"最初由……提出","examples":[{"en":"The hypothesis was originally advanced by Perret-Clermont and others.","zh":"這個假說最初由 Perret-Clermont 等人提出。"},{"en":"Originally advanced by someone means first proposed or put forward by that person.","zh":"最初由某人提出，是指首先由那個人提出或倡議。"},{"en":"A teaching idea may be originally advanced by one researcher and later tested by many others.","zh":"一個教學想法可能最初由一名研究者提出，後來由許多人測試。"},{"en":"Naming who advanced an idea helps trace its academic history.","zh":"說明誰提出某想法，有助追溯其學術歷史。"},{"en":"This phrase is formal and common in research writing.","zh":"這個短語較正式，常見於研究寫作。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":9},{"front":"be investigated in","meaning":"在……中被研究","examples":[{"en":"This hypothesis has been investigated in many recent studies.","zh":"這個假說已在許多近期研究中被研究。"},{"en":"To be investigated in studies means to be examined carefully through research.","zh":"在研究中被研究，是指透過研究被仔細檢驗。"},{"en":"The effect of sleep on learning has been investigated in many school studies.","zh":"睡眠對學習的影響已在許多學校研究中被探討。"},{"en":"Research investigation can support, weaken, or refine a hypothesis.","zh":"研究檢驗可以支持、削弱或完善假說。"},{"en":"This phrase shows that an idea has been tested rather than merely suggested.","zh":"這個短語顯示某想法已被測試，而不只是被提出。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":9},{"front":"recent studies of","meaning":"關於……的近期研究","examples":[{"en":"Recent studies of science teaching have examined peer disagreement.","zh":"關於科學教學的近期研究考察了同輩分歧。"},{"en":"Recent studies of something are newer research projects about that topic.","zh":"關於某事的近期研究，是較新的相關研究項目。"},{"en":"Recent studies of homework have examined stress, sleep, and learning outcomes.","zh":"關於功課的近期研究考察了壓力、睡眠和學習成果。"},{"en":"Recent studies can update older theories by adding new evidence.","zh":"近期研究可以透過加入新證據來更新舊理論。"},{"en":"This phrase introduces modern research evidence.","zh":"這個短語引入現代研究證據。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":9},{"front":"science teaching and learning","meaning":"科學教與學","examples":[{"en":"Researchers have studied the role of conflict in science teaching and learning.","zh":"研究人員研究了衝突在科學教與學中的作用。"},{"en":"Science teaching and learning refers to how science is taught by teachers and understood by students.","zh":"科學教與學，是指教師如何教授科學，以及學生如何理解科學。"},{"en":"Experiments, discussion, and questioning all belong to science teaching and learning.","zh":"實驗、討論和提問都屬於科學教與學。"},{"en":"Studying this area helps schools design lessons that build real understanding.","zh":"研究這個範疇幫助學校設計能建立真正理解的課堂。"},{"en":"This phrase covers both the teacher’s work and the learner’s progress.","zh":"這個短語同時涵蓋教師工作和學習者進展。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":9},{"front":"compare children’s progress","meaning":"比較兒童的進展","examples":[{"en":"Christine Howe and her colleagues compared children’s progress in understanding science concepts.","zh":"Christine Howe 和她的同事比較了兒童在理解科學概念上的進展。"},{"en":"To compare children’s progress means to look at how much different children improve.","zh":"比較兒童的進展，是指查看不同兒童改善了多少。"},{"en":"A teacher may compare children’s progress before and after a reading programme.","zh":"老師可能比較兒童在閱讀計劃前後的進展。"},{"en":"Comparing progress helps researchers see which teaching condition works better.","zh":"比較進展幫助研究人員看出哪種教學條件更有效。"},{"en":"This phrase focuses on improvement over time.","zh":"這個短語聚焦隨時間出現的改善。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":9},{"front":"several types of","meaning":"幾種類型的……","examples":[{"en":"The researchers studied several types of science concepts.","zh":"研究人員研究了幾種類型的科學概念。"},{"en":"Several types of something means more than one kind or category.","zh":"幾種類型的某物，是指多於一種種類或類別。"},{"en":"A school library may offer several types of books, including novels, comics, and reference works.","zh":"學校圖書館可能提供幾種類型的書，包括小說、漫畫和參考書。"},{"en":"Studying several types helps researchers avoid drawing conclusions from only one case.","zh":"研究幾種類型有助研究人員避免只從一個個案下結論。"},{"en":"This phrase introduces variety within a topic.","zh":"這個短語引入某主題內的多樣性。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":9},{"front":"science concepts","meaning":"科學概念","examples":[{"en":"The children were tested on their understanding of science concepts.","zh":"兒童被測試對科學概念的理解。"},{"en":"Science concepts are ideas used to explain natural events, such as force, energy, heat, and motion.","zh":"科學概念是用來解釋自然事件的想法，例如力、能量、熱和運動。"},{"en":"Students use science concepts when explaining why shadows change during the day.","zh":"學生解釋影子為何在一天中改變時，會使用科學概念。"},{"en":"Without clear science concepts, students may rely on everyday guesses.","zh":"沒有清楚科學概念，學生可能依靠日常猜測。"},{"en":"This phrase refers to scientific ideas, not isolated facts.","zh":"這個短語指科學想法，而不是孤立事實。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":9},{"front":"be given the opportunity to","meaning":"獲得機會去","examples":[{"en":"The children were given the opportunity to observe relevant events.","zh":"兒童獲得機會去觀察相關事件。"},{"en":"To be given the opportunity to do something means to be allowed or enabled to do it.","zh":"獲得機會去做某事，是指被允許或有條件去做該事。"},{"en":"Students should be given the opportunity to explain their answers in their own words.","zh":"學生應獲得機會用自己的話解釋答案。"},{"en":"Opportunities matter because learners cannot practise skills they never get to use.","zh":"機會很重要，因為學習者不能練習從未被允許使用的技能。"},{"en":"This phrase emphasises access to a learning experience.","zh":"這個短語強調接觸學習經驗的機會。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":9},{"front":"observe relevant events","meaning":"觀察相關事件","examples":[{"en":"Children observed relevant events before their understanding was assessed.","zh":"兒童在理解被評估前觀察相關事件。"},{"en":"To observe relevant events means to watch events that are directly connected to the topic being studied.","zh":"觀察相關事件，是指觀看與所學主題直接相關的事件。"},{"en":"Students may observe ice melting to understand heat transfer.","zh":"學生可能觀察冰融化，以理解熱傳遞。"},{"en":"Observation gives learners evidence they can compare with their own ideas.","zh":"觀察給學習者證據，讓他們與自己的想法比較。"},{"en":"This phrase describes learning through seeing real examples.","zh":"這個短語描述透過觀看真實例子學習。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":10},{"front":"aged 8 to 12","meaning":"8至12歲","examples":[{"en":"The study involved children aged 8 to 12.","zh":"這項研究涉及 8 至 12 歲的兒童。"},{"en":"Aged 8 to 12 means between eight and twelve years old.","zh":"8 至 12 歲，是指年齡介乎八歲至十二歲。"},{"en":"A summer course for children aged 8 to 12 may use games and simple experiments.","zh":"為 8 至 12 歲兒童設計的暑期課程，可能使用遊戲和簡單實驗。"},{"en":"Age matters because children at different ages may reason differently.","zh":"年齡很重要，因為不同年齡的孩子可能以不同方式推理。"},{"en":"This phrase identifies the age group in a study.","zh":"這個短語指出研究中的年齡組別。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":10},{"front":"understand what influences","meaning":"理解甚麼影響……","examples":[{"en":"The children studied what influences motion down a slope.","zh":"兒童研究甚麼影響沿斜坡向下的運動。"},{"en":"To understand what influences something means to know which factors affect it.","zh":"理解甚麼影響某事，是指知道哪些因素會影響它。"},{"en":"Students may study what influences plant growth, such as light, water, and soil.","zh":"學生可能研究甚麼影響植物生長，例如光、水和泥土。"},{"en":"Identifying influences helps learners move from guessing to explanation.","zh":"找出影響因素幫助學習者從猜測轉向解釋。"},{"en":"This phrase is useful in scientific investigation.","zh":"這個短語適用於科學探究。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":10},{"front":"motion down a slope","meaning":"沿斜坡向下的運動","examples":[{"en":"The experiment examined children’s ideas about motion down a slope.","zh":"這項實驗考察兒童對沿斜坡向下運動的想法。"},{"en":"Motion down a slope is movement along a surface that goes downward at an angle.","zh":"沿斜坡向下的運動，是指沿着向下傾斜的表面移動。"},{"en":"A toy car rolling down a ramp shows motion down a slope.","zh":"玩具車沿斜台滾下，就是沿斜坡向下的運動。"},{"en":"Studying this motion helps students think about speed, force, friction, and gravity.","zh":"研究這種運動幫助學生思考速度、力、摩擦和重力。"},{"en":"This phrase gives a concrete science topic for children to investigate.","zh":"這個短語提供兒童可探究的具體科學主題。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":10},{"front":"in order to ascertain","meaning":"為了確定","examples":[{"en":"The researchers created groups in order to ascertain the role of conflict.","zh":"研究人員建立小組，為了確定衝突的作用。"},{"en":"In order to ascertain means in order to find out or determine something clearly.","zh":"為了確定，是指為了清楚找出或判定某事。"},{"en":"A teacher may give a pre-test in order to ascertain students’ starting level.","zh":"老師可能進行前測，為了確定學生的起始水平。"},{"en":"Researchers design comparisons to ascertain which factor affects learning.","zh":"研究人員設計比較，為了確定哪個因素影響學習。"},{"en":"This phrase is formal and often used in research descriptions.","zh":"這個短語較正式，常用於研究描述。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":10},{"front":"the role of conflict","meaning":"衝突的作用","examples":[{"en":"The study examined the role of conflict in group work.","zh":"這項研究考察衝突在小組活動中的作用。"},{"en":"The role of conflict means how disagreement affects a process or result.","zh":"衝突的作用，是指分歧如何影響過程或結果。"},{"en":"A teacher may study the role of conflict in improving group presentations.","zh":"老師可能研究衝突在改善小組匯報中的作用。"},{"en":"Conflict can be harmful if unmanaged, but useful if it leads to explanation and reflection.","zh":"如果處理不當，衝突可能有害；但如果帶來解釋和反思，就可能有用。"},{"en":"This phrase asks what function conflict has in learning.","zh":"這個短語詢問衝突在學習中有甚麼功能。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":10},{"front":"group work","meaning":"小組活動；小組學習","examples":[{"en":"The researchers wanted to understand how conflict works in group work.","zh":"研究人員想理解衝突如何在小組活動中發揮作用。"},{"en":"Group work is learning or completing a task with other people.","zh":"小組活動是與他人一起學習或完成任務。"},{"en":"Students do group work when they design an experiment together.","zh":"學生一起設計實驗時，就是進行小組活動。"},{"en":"Group work can expose different ideas, but it needs clear rules to avoid confusion.","zh":"小組活動可以展示不同想法，但需要清晰規則以避免混亂。"},{"en":"This phrase refers to collaboration rather than individual study.","zh":"這個短語指合作，而不是個人學習。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":10},{"front":"create two kinds of groups","meaning":"建立兩類小組","examples":[{"en":"The researchers created two kinds of groups according to the pre-test.","zh":"研究人員按照前測建立兩類小組。"},{"en":"To create two kinds of groups means to divide participants into two different categories.","zh":"建立兩類小組，是指把參與者分成兩個不同類別。"},{"en":"A teacher may create two kinds of groups: one for revision and one for extension tasks.","zh":"老師可能建立兩類小組：一類做溫習，一類做延伸任務。"},{"en":"Dividing groups carefully helps researchers compare learning conditions.","zh":"仔細分組幫助研究人員比較學習條件。"},{"en":"This phrase describes experimental design.","zh":"這個短語描述實驗設計。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":10},{"front":"according to","meaning":"按照","examples":[{"en":"The groups were formed according to a pre-test.","zh":"這些小組按照前測結果組成。"},{"en":"According to can mean following or based on a rule, result, or source.","zh":"按照可以指跟隨或基於某個規則、結果或來源。"},{"en":"Students may be placed in classes according to their language level.","zh":"學生可能按照語言水平被安排到不同班別。"},{"en":"Grouping according to test results helps researchers control differences between learners.","zh":"按照測驗結果分組幫助研究人員控制學習者之間的差異。"},{"en":"In this context, it means “based on,” not “someone said.”","zh":"在這個語境中，它指「基於」，而不是「某人說」。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":10},{"front":"pre-test","meaning":"前測","examples":[{"en":"A pre-test was used to identify children’s initial views.","zh":"前測被用來識別兒童的初始觀點。"},{"en":"A pre-test is a test given before teaching or an experiment begins.","zh":"前測是在教學或實驗開始前進行的測驗。"},{"en":"A teacher may give a pre-test to see which grammar points students already know.","zh":"老師可能進行前測，以了解學生已掌握哪些文法點。"},{"en":"Pre-tests help compare students’ understanding before and after learning.","zh":"前測幫助比較學生學習前後的理解。"},{"en":"This phrase refers to measurement before the main activity.","zh":"這個短語指主要活動前的測量。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":10},{"front":"one in which","meaning":"其中一個是……的","examples":[{"en":"The researchers formed one group in which children had dissimilar views.","zh":"研究人員組成其中一組，在其中兒童有不相似的觀點。"},{"en":"One in which means one example or group where a particular condition exists.","zh":"其中一個是……的，是指某個例子或組別具有特定條件。"},{"en":"A teacher created one activity in which students had to defend different opinions.","zh":"老師設計其中一個活動，學生必須捍衛不同意見。"},{"en":"This phrase helps describe the defining feature of one category.","zh":"這個短語幫助描述一個類別的定義特徵。"},{"en":"It is common in formal descriptions of groups, studies, or situations.","zh":"它常見於對小組、研究或情境的正式描述。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":10},{"front":"dissimilar views","meaning":"不相似的觀點","examples":[{"en":"Some groups contained children with dissimilar views.","zh":"有些小組包含持不相似觀點的兒童。"},{"en":"Dissimilar views are opinions or ideas that are different from one another.","zh":"不相似的觀點，是指彼此不同的意見或想法。"},{"en":"Two students may have dissimilar views about why a ball rolls faster down a ramp.","zh":"兩名學生可能對球為何沿斜台滾得更快有不相似觀點。"},{"en":"Dissimilar views can create discussion because learners must explain disagreements.","zh":"不相似觀點可以引起討論，因為學習者必須解釋分歧。"},{"en":"This phrase is important when studying peer conflict.","zh":"這個短語在研究同輩衝突時很重要。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":11},{"front":"similar views","meaning":"相似的觀點","examples":[{"en":"Other groups contained children with similar views.","zh":"其他小組包含持相似觀點的兒童。"},{"en":"Similar views are ideas or opinions that are mostly alike.","zh":"相似的觀點，是指大致相同的想法或意見。"},{"en":"Students with similar views may agree quickly during group discussion.","zh":"持相似觀點的學生可能在小組討論中很快同意。"},{"en":"Similar views can make cooperation easier, but may create less challenge.","zh":"相似觀點可以令合作較容易，但可能產生較少挑戰。"},{"en":"This phrase contrasts with dissimilar views.","zh":"這個短語與不相似觀點形成對比。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":11},{"front":"find support for","meaning":"找到支持……的證據","examples":[{"en":"The researchers found support for the idea that disagreement can help learning.","zh":"研究人員找到支持「分歧可以幫助學習」這個想法的證據。"},{"en":"To find support for an idea means to find evidence that makes it more believable.","zh":"找到支持某想法的證據，是指找到令該想法更可信的證據。"},{"en":"A teacher may find support for a new method after students’ test scores improve.","zh":"學生成績提高後，老師可能找到支持新方法的證據。"},{"en":"Support from evidence does not always prove an idea completely, but it strengthens it.","zh":"證據支持不一定完全證明一個想法，但會加強它。"},{"en":"This phrase is common when discussing research findings.","zh":"這個短語常見於討論研究結果。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":11},{"front":"progress more","meaning":"取得更大進展","examples":[{"en":"Children with dissimilar views progressed more after the sessions.","zh":"持不相似觀點的兒童在課節後取得更大進展。"},{"en":"To progress more means to improve to a greater degree than others.","zh":"取得更大進展，是指比其他人改善更多。"},{"en":"Students may progress more when they receive feedback matched to their mistakes.","zh":"當學生收到符合自己錯誤的回饋時，可能取得更大進展。"},{"en":"Greater progress can show that a learning condition is more effective.","zh":"較大進展可以顯示某學習條件更有效。"},{"en":"This phrase compares the amount of improvement between groups.","zh":"這個短語比較不同組別之間的改善程度。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":11},{"front":"training sessions","meaning":"訓練課節","examples":[{"en":"The children’s progress was measured after their training sessions.","zh":"兒童的進展在訓練課節後被測量。"},{"en":"Training sessions are planned periods of practice or instruction.","zh":"訓練課節是有計劃的練習或教學時段。"},{"en":"A football team may have training sessions three times a week.","zh":"足球隊可能每週有三次訓練課節。"},{"en":"In education research, training sessions give students the learning experience being tested.","zh":"在教育研究中，訓練課節給學生接受被測試的學習經驗。"},{"en":"This phrase refers to structured learning or practice time.","zh":"這個短語指有結構的學習或練習時間。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":11},{"front":"be placed in groups with","meaning":"被安排在有……的小組中","examples":[{"en":"Some children were placed in groups with similar views.","zh":"有些兒童被安排在有相似觀點的小組中。"},{"en":"To be placed in groups with someone means to be assigned to work or learn with that type of person.","zh":"被安排在有某類人的小組中，是指被分配與那類人一起工作或學習。"},{"en":"Students may be placed in groups with classmates who have different reading levels.","zh":"學生可能被安排在有不同閱讀水平同學的小組中。"},{"en":"Group placement can affect discussion, confidence, and learning outcomes.","zh":"小組安排會影響討論、信心和學習結果。"},{"en":"This phrase describes how participants are arranged.","zh":"這個短語描述參與者如何被安排。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":11},{"front":"no evidence to support","meaning":"沒有證據支持","examples":[{"en":"The researchers found no evidence to support one part of the theory.","zh":"研究人員沒有證據支持該理論的一部分。"},{"en":"No evidence to support means there is no data or observation that backs up an idea.","zh":"沒有證據支持，是指沒有數據或觀察支持某個想法。"},{"en":"A teacher may find no evidence to support the claim that longer homework always helps.","zh":"老師可能沒有證據支持「功課越長一定越有幫助」的說法。"},{"en":"Without evidence, a theory may need to be revised or tested again.","zh":"沒有證據時，理論可能需要被修正或再次測試。"},{"en":"This phrase is used when research fails to confirm a claim.","zh":"這個短語用於研究未能確認某主張時。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":11},{"front":"work out new conceptions","meaning":"想出新概念","examples":[{"en":"The children did not appear to work out new conceptions during discussion.","zh":"兒童似乎沒有在討論期間想出新概念。"},{"en":"To work out new conceptions means to develop new ways of understanding something.","zh":"想出新概念，是指發展出理解某事的新方式。"},{"en":"Students may work out a new conception of gravity after comparing several falling-object experiments.","zh":"學生比較幾個下墜物體實驗後，可能想出關於重力的新概念。"},{"en":"New conceptions may not appear immediately during discussion; they may develop later.","zh":"新概念未必在討論中立即出現；它們可能之後才發展。"},{"en":"This phrase describes building new understanding through thinking.","zh":"這個短語描述透過思考建立新理解。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":11},{"front":"group discussions","meaning":"小組討論","examples":[{"en":"Progress was not observed immediately after the group discussions.","zh":"小組討論後沒有立即觀察到進展。"},{"en":"Group discussions are conversations in which several learners exchange ideas.","zh":"小組討論是幾名學習者交流想法的對話。"},{"en":"In group discussions, students may explain, question, and challenge one another.","zh":"在小組討論中，學生可能互相解釋、提問和挑戰。"},{"en":"Discussions can influence thinking even if improvement is not visible at once.","zh":"即使改善不是立即可見，討論仍可以影響思維。"},{"en":"This phrase refers to learning through conversation with others.","zh":"這個短語指透過與他人對話學習。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":11},{"front":"not actually observed","meaning":"並未真正觀察到","examples":[{"en":"The progress was not actually observed in the first post-test.","zh":"進展並未真正於第一次後測中被觀察到。"},{"en":"Not actually observed means not directly seen or measured in the results.","zh":"並未真正觀察到，是指結果中沒有被直接看到或測量到。"},{"en":"A teacher may expect improvement, but it may not actually be observed in the first quiz.","zh":"老師可能預期有改善，但第一次小測中並未真正觀察到。"},{"en":"This phrase warns that a claim needs evidence from real measurement.","zh":"這個短語提醒人，主張需要真實測量證據。"},{"en":"It separates expectation from what was found.","zh":"它把預期與實際發現分開。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":11},{"front":"post-test","meaning":"後測","examples":[{"en":"The researchers used a post-test to assess children’s progress.","zh":"研究人員使用後測來評估兒童的進展。"},{"en":"A post-test is a test given after teaching, training, or an experiment.","zh":"後測是在教學、訓練或實驗之後進行的測驗。"},{"en":"A language course may use a post-test to see what students learned.","zh":"語言課程可能使用後測來了解學生學到了甚麼。"},{"en":"Comparing a pre-test and post-test helps measure improvement.","zh":"比較前測和後測有助衡量進步。"},{"en":"This phrase refers to assessment after the main learning activity.","zh":"這個短語指主要學習活動之後的評估。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":11},{"front":"immediately after","meaning":"立即在……之後","examples":[{"en":"The first post-test was given immediately after the group work.","zh":"第一次後測立即在小組活動之後進行。"},{"en":"Immediately after means right after something happens, with almost no delay.","zh":"立即在……之後，是指某事發生後幾乎沒有延遲。"},{"en":"Students may discuss answers immediately after a mock exam while memory is fresh.","zh":"學生可能在模擬考後立即討論答案，因為記憶仍清晰。"},{"en":"Results measured immediately after learning may differ from results measured weeks later.","zh":"學習後立即測量的結果，可能不同於數星期後測量的結果。"},{"en":"This phrase highlights timing.","zh":"這個短語突出時間安排。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":12},{"front":"but rather","meaning":"而是","examples":[{"en":"Progress was observed not immediately, but rather several weeks later.","zh":"進展不是立即被觀察到，而是幾星期後才出現。"},{"en":"But rather means instead, especially when correcting the first idea.","zh":"而是指相反地，尤其用於糾正前一個想法。"},{"en":"The problem is not laziness, but rather lack of clear guidance.","zh":"問題不是懶惰，而是缺乏清晰指引。"},{"en":"This phrase shifts attention from a rejected idea to the more accurate one.","zh":"這個短語把注意力從被否定的想法轉向更準確的想法。"},{"en":"It is common in formal contrast.","zh":"它常見於正式對比。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":12},{"front":"a second test","meaning":"第二次測驗","examples":[{"en":"A second test was given around four weeks after the group work.","zh":"第二次測驗在小組活動約四星期後進行。"},{"en":"A second test is another assessment given after the first one.","zh":"第二次測驗是在第一次之後再進行的另一個評估。"},{"en":"A teacher may give a second test later to check whether students remember the skill.","zh":"老師可能稍後進行第二次測驗，以檢查學生是否記得技能。"},{"en":"A second test can reveal delayed learning that the first test misses.","zh":"第二次測驗可以揭示第一次測驗錯過的延後學習。"},{"en":"This phrase shows that assessment happened more than once.","zh":"這個短語顯示評估不只進行一次。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":12},{"front":"around four weeks after","meaning":"約四星期後","examples":[{"en":"Progress appeared around four weeks after the group work.","zh":"進展在小組活動約四星期後出現。"},{"en":"Around four weeks after means approximately four weeks later.","zh":"約四星期後，是指大約四個星期之後。"},{"en":"A student may feel more confident around four weeks after starting regular speaking practice.","zh":"學生開始定期口語練習約四星期後，可能感到更有信心。"},{"en":"Delayed results can appear weeks after the original learning activity.","zh":"延後結果可以在原本學習活動數星期後出現。"},{"en":"This phrase gives an approximate time gap.","zh":"這個短語給出大約時間間隔。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":12},{"front":"set out to investigate","meaning":"着手研究","examples":[{"en":"Howe and her colleagues set out to investigate pair work.","zh":"Howe 和她的同事着手研究二人合作學習。"},{"en":"To set out to investigate something means to begin research with the purpose of studying it.","zh":"着手研究某事，是指以研究它為目的開始調查。"},{"en":"A teacher may set out to investigate why students dislike reading aloud.","zh":"老師可能着手研究學生為何不喜歡朗讀。"},{"en":"This phrase shows the aim at the start of a study.","zh":"這個短語顯示研究開始時的目標。"},{"en":"It is useful when describing researchers’ intentions.","zh":"它適合用來描述研究人員的意圖。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":12},{"front":"progress obtained through","meaning":"透過……取得的進展","examples":[{"en":"The study examined progress obtained through pair work.","zh":"研究考察透過二人合作學習取得的進展。"},{"en":"Progress obtained through something means improvement achieved by using that method.","zh":"透過某方法取得的進展，是指使用該方法所達成的改善。"},{"en":"Progress obtained through daily reading may appear in better vocabulary and fluency.","zh":"透過每日閱讀取得的進展，可能體現在更好詞彙和流暢度上。"},{"en":"Researchers compare progress obtained through different methods to see which works better.","zh":"研究人員比較透過不同方法取得的進展，以看出哪種更有效。"},{"en":"This phrase links improvement with the activity that produced it.","zh":"這個短語把改善與產生改善的活動連接起來。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":12},{"front":"pair work","meaning":"二人合作學習","examples":[{"en":"The researchers investigated whether pair work helped pupils exchange ideas.","zh":"研究人員調查二人合作學習是否幫助學生交流想法。"},{"en":"Pair work is a learning activity in which two students work together.","zh":"二人合作學習是兩名學生一起工作的學習活動。"},{"en":"In pair work, one student may predict an answer while the other explains a reason.","zh":"在二人合作學習中，一名學生可能預測答案，另一名解釋理由。"},{"en":"Pair work can encourage quieter students to speak more than in a large group.","zh":"二人合作學習可以鼓勵較安靜的學生比在大組中說更多話。"},{"en":"This phrase refers to two-person collaboration.","zh":"這個短語指二人合作。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":12},{"front":"be a function of","meaning":"是……的結果；取決於","examples":[{"en":"Progress may be a function of the exchange of ideas.","zh":"進展可能是交流想法的結果。"},{"en":"To be a function of something means to depend on it or result from it.","zh":"是某事的結果或取決於某事，是指依賴它或由它產生。"},{"en":"A student’s confidence may be a function of practice and supportive feedback.","zh":"學生信心可能取決於練習和支持性回饋。"},{"en":"If progress is a function of idea exchange, discussion quality matters.","zh":"如果進展取決於想法交流，討論質素就很重要。"},{"en":"This phrase is formal and often used to explain what affects an outcome.","zh":"這個短語較正式，常用來解釋甚麼影響結果。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":12},{"front":"exchange of ideas","meaning":"交流想法","examples":[{"en":"Pair work may help learning through the exchange of ideas.","zh":"二人合作學習可能透過交流想法來幫助學習。"},{"en":"Exchange of ideas means people share, compare, and respond to one another’s thoughts.","zh":"交流想法，是指人們分享、比較並回應彼此的想法。"},{"en":"A class debate creates an exchange of ideas about a social issue.","zh":"課堂辯論創造關於社會議題的想法交流。"},{"en":"Idea exchange can reveal weaknesses and help students refine explanations.","zh":"想法交流可以揭示弱點，並幫助學生完善解釋。"},{"en":"This phrase describes learning through communication.","zh":"這個短語描述透過溝通學習。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":12},{"front":"progress made by pupils","meaning":"學生取得的進展","examples":[{"en":"The study measured progress made by pupils aged 12 to 15.","zh":"研究測量 12 至 15 歲學生取得的進展。"},{"en":"Progress made by pupils means the improvement students achieved.","zh":"學生取得的進展，是指學生達成的改善。"},{"en":"A teacher can measure progress made by pupils by comparing early and later writing samples.","zh":"老師可以透過比較早期和後期作文樣本，衡量學生取得的進展。"},{"en":"Measuring progress helps show whether teaching has changed understanding.","zh":"衡量進展有助顯示教學是否改變了理解。"},{"en":"This phrase focuses on students’ development over time.","zh":"這個短語聚焦學生隨時間發展。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":12},{"front":"aged 12 to 15","meaning":"12至15歲","examples":[{"en":"The second study involved pupils aged 12 to 15.","zh":"第二項研究涉及 12 至 15 歲的學生。"},{"en":"Aged 12 to 15 means between twelve and fifteen years old.","zh":"12 至 15 歲，是指年齡介乎十二至十五歲。"},{"en":"Pupils aged 12 to 15 may be ready for more abstract scientific explanations.","zh":"12 至 15 歲的學生可能已準備好理解較抽象的科學解釋。"},{"en":"Age group matters because older pupils may discuss ideas differently from younger children.","zh":"年齡組別很重要，因為較年長學生討論想法的方式可能不同於幼童。"},{"en":"This phrase identifies the participants’ age range.","zh":"這個短語指出參與者的年齡範圍。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":12},{"front":"the path of falling objects","meaning":"下墜物體的路徑","examples":[{"en":"The pupils studied the path of falling objects.","zh":"學生研究下墜物體的路徑。"},{"en":"The path of falling objects is the route objects take as they move downward.","zh":"下墜物體的路徑，是物體向下移動時所經過的路線。"},{"en":"A ball dropped from a moving cart may follow a path that surprises students.","zh":"從移動小車掉下的球，可能沿着令學生驚訝的路徑移動。"},{"en":"Studying falling paths helps learners connect motion, gravity, and prediction.","zh":"研究下墜路徑幫助學習者連接運動、重力和預測。"},{"en":"This phrase names a science topic involving movement.","zh":"這個短語命名一個涉及運動的科學主題。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":13},{"front":"a topic that usually involves","meaning":"一個通常涉及……的課題","examples":[{"en":"The path of falling objects is a topic that usually involves conceptual difficulties.","zh":"下墜物體的路徑是一個通常涉及概念困難的課題。"},{"en":"A topic that usually involves something is an area where that issue commonly appears.","zh":"一個通常涉及某事的課題，是指該問題常出現在該範疇中。"},{"en":"Fractions are a topic that usually involves confusion for younger students.","zh":"分數是一個通常令年幼學生感到困惑的課題。"},{"en":"When a topic usually involves difficulties, teachers need careful examples and activities.","zh":"當一個課題通常涉及困難，教師需要仔細例子和活動。"},{"en":"This phrase links a subject with a common learning challenge.","zh":"這個短語把主題與常見學習挑戰連接起來。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":13},{"front":"conceptual difficulties","meaning":"概念上的困難","examples":[{"en":"Some science topics involve conceptual difficulties for pupils.","zh":"有些科學課題對學生來說涉及概念上的困難。"},{"en":"Conceptual difficulties are problems in understanding the ideas behind a topic.","zh":"概念上的困難，是指理解某主題背後概念時遇到的問題。"},{"en":"Students may have conceptual difficulties with gravity because everyday experience can mislead them.","zh":"學生可能在理解重力時有概念困難，因為日常經驗會誤導他們。"},{"en":"These difficulties are deeper than spelling errors or memory mistakes.","zh":"這些困難比拼寫錯誤或記憶錯誤更深層。"},{"en":"This phrase refers to trouble with meaning and reasoning.","zh":"這個短語指理解和推理上的困難。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":13},{"front":"create pairs of pupils","meaning":"組成學生二人小組","examples":[{"en":"The researchers created pairs of pupils with different initial conceptions.","zh":"研究人員把有不同初始概念的學生組成二人小組。"},{"en":"To create pairs of pupils means to put students into groups of two.","zh":"組成學生二人小組，是指把學生安排成兩人一組。"},{"en":"A teacher may create pairs of pupils so each student has time to speak.","zh":"老師可能組成學生二人小組，讓每名學生都有時間發言。"},{"en":"Pairing students carefully can affect the quality of discussion.","zh":"仔細配對學生會影響討論質素。"},{"en":"This phrase describes arranging learners for two-person work.","zh":"這個短語描述為二人合作安排學習者。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":13},{"front":"varying levels of","meaning":"不同程度的……","examples":[{"en":"The pairs had varying levels of dissimilarity in their ideas.","zh":"這些二人組在想法差異性上有不同程度。"},{"en":"Varying levels of something means different degrees or amounts of it.","zh":"不同程度的某事，是指它有不同的程度或數量。"},{"en":"Students may have varying levels of confidence before a speaking test.","zh":"學生在口語測驗前可能有不同程度的信心。"},{"en":"Measuring different levels helps researchers see whether more difference leads to more progress.","zh":"測量不同程度有助研究人員看出更大差異是否帶來更多進展。"},{"en":"This phrase is useful when something is not simply present or absent.","zh":"當某事不是簡單地有或沒有時，這個短語很有用。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":13},{"front":"dissimilarity","meaning":"差異性；不相似程度","examples":[{"en":"The researchers measured dissimilarity in pupils’ initial conceptions.","zh":"研究人員測量學生初始概念中的差異性。"},{"en":"Dissimilarity means the degree to which two things are different.","zh":"差異性是指兩件事不同的程度。"},{"en":"A teacher may notice dissimilarity between two students’ explanations of the same experiment.","zh":"老師可能注意到兩名學生對同一實驗的解釋有差異性。"},{"en":"Greater dissimilarity can create more disagreement and more discussion.","zh":"更大差異性可以產生更多分歧和更多討論。"},{"en":"This word is the noun form of “dissimilar.”","zh":"這個詞是 “dissimilar” 的名詞形式。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":13},{"front":"initial conceptions","meaning":"初始概念","examples":[{"en":"The pupils’ initial conceptions were assessed before pair work.","zh":"學生的初始概念在二人合作學習前被評估。"},{"en":"Initial conceptions are the ideas students have at the beginning, before instruction or discussion.","zh":"初始概念是學生在教學或討論前一開始已有的想法。"},{"en":"A child’s initial conception may be that a heavier ball must fall faster.","zh":"孩子的初始概念可能是較重的球一定下墜較快。"},{"en":"Assessing initial conceptions helps teachers see what needs to change.","zh":"評估初始概念幫助教師看出甚麼需要改變。"},{"en":"This phrase refers to starting beliefs, not final understanding.","zh":"這個短語指起始信念，而不是最終理解。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":13},{"front":"predictions and explanations","meaning":"預測和解釋","examples":[{"en":"The pupils gave predictions and explanations about falling objects.","zh":"學生對下墜物體給出預測和解釋。"},{"en":"Predictions and explanations are guesses about what will happen and reasons for why it happens.","zh":"預測和解釋，是對將會發生甚麼的猜測，以及為何會發生的理由。"},{"en":"Before an experiment, students may give predictions and explanations about which object will fall first.","zh":"實驗前，學生可能預測並解釋哪個物體會先下墜。"},{"en":"Comparing predictions with results helps students test their thinking.","zh":"比較預測與結果有助學生測試思維。"},{"en":"This phrase connects scientific guessing with reasoning.","zh":"這個短語把科學猜測與推理連接起來。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":13},{"front":"be assessed before","meaning":"在……之前被評估","examples":[{"en":"The pupils’ ideas were assessed before they worked in pairs.","zh":"學生的想法在他們二人合作之前被評估。"},{"en":"To be assessed before something means to be evaluated prior to an activity or event.","zh":"在某事之前被評估，是指在活動或事件之前接受評價。"},{"en":"Students’ vocabulary may be assessed before a reading course begins.","zh":"學生詞彙量可能在閱讀課程開始前被評估。"},{"en":"Assessment before learning gives a baseline for measuring progress.","zh":"學習前評估提供衡量進展的基準。"},{"en":"This phrase indicates timing in a study or lesson.","zh":"這個短語指出研究或課堂中的時間安排。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":13},{"front":"be engaged in","meaning":"參與","examples":[{"en":"The pupils were engaged in pair work after the first assessment.","zh":"學生在第一次評估後參與二人合作學習。"},{"en":"To be engaged in something means to be taking part in it.","zh":"參與某事，是指正在加入或進行該活動。"},{"en":"Students engaged in discussion may ask questions and respond to classmates.","zh":"參與討論的學生可能會提問並回應同學。"},{"en":"Engagement matters because active participation can change understanding.","zh":"參與很重要，因為主動參與可以改變理解。"},{"en":"This phrase is more formal than “doing.”","zh":"這個短語比 “doing” 更正式。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":13},{"front":"work sessions","meaning":"學習課節","examples":[{"en":"The work sessions involved computer-presented problems.","zh":"學習課節涉及由電腦呈現的問題。"},{"en":"Work sessions are planned periods when learners complete tasks or activities.","zh":"學習課節是學習者完成任務或活動的有計劃時段。"},{"en":"A writing course may include short work sessions for planning, drafting, and revising.","zh":"寫作課程可能包括規劃、起草和修改的短課節。"},{"en":"Structured sessions help researchers know exactly what students experienced.","zh":"有結構的課節幫助研究人員清楚知道學生經歷了甚麼。"},{"en":"This phrase refers to organised activity time.","zh":"這個短語指有組織的活動時間。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":13},{"front":"involve solving","meaning":"涉及解決","examples":[{"en":"The sessions involved solving problems about falling objects.","zh":"這些課節涉及解決關於下墜物體的問題。"},{"en":"To involve solving something means to include the task of finding an answer or explanation.","zh":"涉及解決某事，是指包括找出答案或解釋的任務。"},{"en":"A maths lesson may involve solving word problems about shopping and change.","zh":"數學課可能涉及解決關於購物和找續的文字題。"},{"en":"Activities that involve solving problems require active reasoning from students.","zh":"涉及解決問題的活動要求學生主動推理。"},{"en":"This phrase shows what the task contains.","zh":"這個短語顯示任務包含甚麼。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":14},{"front":"computer-presented problems","meaning":"由電腦呈現的問題","examples":[{"en":"The pupils solved computer-presented problems about falling objects.","zh":"學生解決由電腦呈現的下墜物體問題。"},{"en":"Computer-presented problems are questions or tasks shown on a computer screen.","zh":"由電腦呈現的問題，是顯示在電腦螢幕上的問題或任務。"},{"en":"Students may solve computer-presented grammar exercises in an online class.","zh":"學生可能在網課中解答由電腦呈現的文法練習。"},{"en":"Using computers can standardise tasks so each pair sees the same problem.","zh":"使用電腦可以標準化任務，使每個二人組看到相同問題。"},{"en":"This phrase describes how the problems were delivered.","zh":"這個短語描述問題如何呈現。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":14},{"front":"predicting and explaining","meaning":"預測和解釋","examples":[{"en":"The task involved predicting and explaining the paths of falling objects.","zh":"任務涉及預測和解釋下墜物體的路徑。"},{"en":"Predicting and explaining means saying what will happen and giving reasons for it.","zh":"預測和解釋，是指說出將會發生甚麼，並給出原因。"},{"en":"In science class, students practise predicting and explaining before and after experiments.","zh":"在科學課中，學生在實驗前後練習預測和解釋。"},{"en":"Prediction without explanation may show guessing rather than understanding.","zh":"只有預測而沒有解釋，可能顯示只是猜測而非理解。"},{"en":"This phrase describes two linked scientific-thinking skills.","zh":"這個短語描述兩種相連的科學思維技能。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":14},{"front":"be given to individuals","meaning":"分別給個人進行","examples":[{"en":"The post-test was given to individuals, not pairs.","zh":"後測分別給個人進行，而不是給二人組進行。"},{"en":"To be given to individuals means to be administered to each person separately.","zh":"分別給個人進行，是指每個人分開接受測驗或任務。"},{"en":"A speaking test may be given to individuals so each student’s ability is clear.","zh":"口語測驗可能分別給個人進行，以清楚了解每名學生能力。"},{"en":"Individual testing helps researchers measure personal progress after group work.","zh":"個別測驗幫助研究人員衡量小組活動後的個人進展。"},{"en":"This phrase contrasts individual assessment with pair or group assessment.","zh":"這個短語把個人評估與二人或小組評估作對比。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":14},{"front":"assess the progress made by","meaning":"評估……取得的進展","examples":[{"en":"The post-test assessed the progress made by pupils.","zh":"後測評估學生取得的進展。"},{"en":"To assess the progress made by someone means to evaluate how much they have improved.","zh":"評估某人取得的進展，是指評價他們改善了多少。"},{"en":"A teacher may assess the progress made by students after a month of reading practice.","zh":"老師可能在一個月閱讀練習後評估學生取得的進展。"},{"en":"Assessment shows whether learning activities changed skills or understanding.","zh":"評估顯示學習活動是否改變了技能或理解。"},{"en":"This phrase focuses on measuring improvement.","zh":"這個短語聚焦衡量改善。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":14},{"front":"conceptions of what influenced","meaning":"對甚麼影響……的概念","examples":[{"en":"The test assessed pupils’ conceptions of what influenced falling objects.","zh":"測驗評估學生對甚麼影響下墜物體的概念。"},{"en":"Conceptions of what influenced something are ideas about the factors that affect it.","zh":"對甚麼影響某事的概念，是關於哪些因素影響它的想法。"},{"en":"Students may have conceptions of what influences plant growth before studying biology.","zh":"學生在學習生物前，可能已有對甚麼影響植物生長的概念。"},{"en":"Testing these conceptions reveals whether learners understand cause and effect.","zh":"測試這些概念可以揭示學習者是否理解因果。"},{"en":"This phrase describes beliefs about causal factors.","zh":"這個短語描述關於影響因素的信念。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":14},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Candidates must choose the correct heading for each paragraph.","zh":"考生必須為每段選出正確標題。"},{"en":"To choose the correct heading means to select the title that best matches a paragraph’s main idea.","zh":"選出正確標題，是指選擇最符合段落主旨的標題。"},{"en":"In a reading test, students choose headings by identifying the paragraph’s central point.","zh":"在閱讀測驗中，學生透過找出段落中心思想來選標題。"},{"en":"Choosing headings becomes easier when students ignore minor details.","zh":"當學生忽略次要細節時，選標題會變得更容易。"},{"en":"This phrase is common in IELTS-style reading tasks.","zh":"這個短語常見於 IELTS 式閱讀題。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":14},{"front":"from the list of headings below","meaning":"從以下標題列表中","examples":[{"en":"The answers should be chosen from the list of headings below.","zh":"答案應從以下標題列表中選取。"},{"en":"From the list of headings below means using only the heading options provided after the instruction.","zh":"從以下標題列表中，是指只使用指示後提供的標題選項。"},{"en":"Students should not invent their own headings if a list is given.","zh":"如果已提供列表，學生不應自己創作標題。"},{"en":"This instruction limits the possible answers and guides the matching task.","zh":"這項指示限制可能答案，並引導配對任務。"},{"en":"The phrase tells candidates where to find the answer choices.","zh":"這個短語告訴考生在哪裡找答案選項。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":14},{"front":"write the correct number","meaning":"寫上正確編號","examples":[{"en":"Candidates write the correct number on the answer sheet.","zh":"考生在答題紙上寫上正確編號。"},{"en":"To write the correct number means to record the number that matches the chosen answer.","zh":"寫上正確編號，是指記下與所選答案相符的編號。"},{"en":"In a matching task, students may write iii beside paragraph B if that heading fits.","zh":"在配對題中，如果 iii 符合 B 段，學生可能在 B 旁寫 iii。"},{"en":"Writing the wrong number can lose marks even if the student understood the paragraph.","zh":"即使學生理解段落，寫錯編號也可能失分。"},{"en":"This phrase describes the required answer format.","zh":"這個短語描述所需答案格式。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":14},{"front":"a suggested modification to","meaning":"對……提出的修改建議","examples":[{"en":"The heading refers to a suggested modification to a theory about learning.","zh":"該標題指對關於學習的理論提出的修改建議。"},{"en":"A suggested modification to something is a proposed change or adjustment to it.","zh":"對某事提出的修改建議，是指對它提出改變或調整。"},{"en":"A teacher may suggest a modification to a lesson plan after seeing students struggle.","zh":"老師看見學生有困難後，可能對教案提出修改建議。"},{"en":"Modifications are proposed when an original idea seems incomplete.","zh":"當原有想法似乎不完整時，就會提出修改。"},{"en":"This phrase often appears when theories are revised by later researchers.","zh":"這個短語常出現在後來研究者修正理論時。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":14},{"front":"a theory about learning","meaning":"關於學習的理論","examples":[{"en":"The passage discusses a theory about learning and cognitive change.","zh":"篇章討論關於學習和認知轉變的理論。"},{"en":"A theory about learning is an organised explanation of how people gain knowledge or understanding.","zh":"關於學習的理論，是對人們如何獲得知識或理解的有組織解釋。"},{"en":"A theory about learning may explain why practice, feedback, or conflict helps students improve.","zh":"學習理論可能解釋為何練習、回饋或衝突幫助學生進步。"},{"en":"Theories guide teaching methods, but they need evidence from classrooms.","zh":"理論引導教學方法，但需要課堂證據支持。"},{"en":"This phrase refers to an explanation of learning, not a single classroom tip.","zh":"這個短語指對學習的解釋，而不是單一課堂技巧。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":14},{"front":"superficial understanding","meaning":"表面理解","examples":[{"en":"Students may show superficial understanding when they can repeat formulae.","zh":"當學生能複述公式時，可能表現出表面理解。"},{"en":"Superficial understanding is shallow knowledge that looks correct but lacks depth.","zh":"表面理解是看似正確但缺乏深度的淺層知識。"},{"en":"A student may have superficial understanding if they know a grammar rule but cannot use it in writing.","zh":"如果學生知道文法規則但不能在寫作中使用，就可能只有表面理解。"},{"en":"Superficial understanding often appears when students memorise without applying.","zh":"當學生記憶而不應用時，表面理解常會出現。"},{"en":"This phrase contrasts surface performance with real comprehension.","zh":"這個短語把表面表現與真正理解作對比。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":15},{"front":"the relationship between…and…","meaning":"……與……之間的關係","examples":[{"en":"The heading mentions the relationship between scientific understanding and age.","zh":"該標題提到科學理解與年齡之間的關係。"},{"en":"The relationship between two things is the way they are connected or influence each other.","zh":"兩者之間的關係，是指它們如何連繫或互相影響。"},{"en":"Researchers may study the relationship between sleep and exam performance.","zh":"研究人員可能研究睡眠與考試表現之間的關係。"},{"en":"Understanding a relationship helps explain why one factor changes with another.","zh":"理解關係有助解釋為何一個因素隨另一個因素改變。"},{"en":"This phrase is common in research questions and headings.","zh":"這個短語常見於研究問題和標題。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":15},{"front":"scientific understanding","meaning":"科學理解","examples":[{"en":"The passage explores how scientific understanding develops.","zh":"篇章探討科學理解如何發展。"},{"en":"Scientific understanding is the ability to explain natural events using scientific ideas and evidence.","zh":"科學理解是使用科學概念和證據解釋自然事件的能力。"},{"en":"A student shows scientific understanding when they can explain why a shadow changes shape.","zh":"當學生能解釋影子為何改變形狀時，就顯示科學理解。"},{"en":"Scientific understanding grows when learners connect experiments with concepts.","zh":"當學習者把實驗與概念連接，科學理解就會增長。"},{"en":"This phrase means more than knowing scientific words.","zh":"這個短語不只是知道科學詞彙。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":15},{"front":"rejection of","meaning":"拒絕；否定","examples":[{"en":"One heading refers to the rejection of a widely held theory.","zh":"其中一個標題指否定一個廣泛持有的理論。"},{"en":"Rejection of something means refusing to accept it as true or useful.","zh":"拒絕或否定某事，是指不接受它為真或有用。"},{"en":"A researcher may propose the rejection of an old explanation after new evidence appears.","zh":"新證據出現後，研究人員可能提出否定舊解釋。"},{"en":"Rejection can happen when a theory no longer fits the facts.","zh":"當理論不再符合事實時，就可能被否定。"},{"en":"This phrase introduces opposition to an idea.","zh":"這個短語引入對某想法的反對。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":15},{"front":"a widely held theory","meaning":"廣泛持有的理論","examples":[{"en":"A widely held theory is a belief accepted by many people.","zh":"廣泛持有的理論是許多人接受的信念。"},{"en":"A widely held theory is an explanation or belief that many people support.","zh":"廣泛持有的理論，是許多人支持的解釋或信念。"},{"en":"A widely held theory in a school may be that more homework always means better results.","zh":"學校中一個廣泛持有的理論可能是功課越多成績越好。"},{"en":"Widely held theories can still be wrong if evidence challenges them.","zh":"如果證據挑戰它們，廣泛持有的理論仍可能是錯的。"},{"en":"This phrase describes popularity, not guaranteed truth.","zh":"這個短語描述普遍性，而不保證真實。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":15},{"front":"the need to develop","meaning":"發展……的需要","examples":[{"en":"The passage discusses the need to develop new concepts.","zh":"篇章討論發展新概念的需要。"},{"en":"The need to develop something means it is necessary to build or improve it.","zh":"發展某事的需要，是指有必要建立或改善它。"},{"en":"Students may have a need to develop better study habits before public exams.","zh":"學生在公開考試前可能有發展更好溫習習慣的需要。"},{"en":"A need appears when existing skills or ideas are not enough.","zh":"當現有技能或想法不足時，就會出現需要。"},{"en":"This phrase introduces a required improvement.","zh":"這個短語引入必要的改善。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":15},{"front":"new concepts","meaning":"新概念","examples":[{"en":"Students often need to develop new concepts in science.","zh":"學生在科學中常需要發展新概念。"},{"en":"New concepts are fresh ideas or ways of understanding a topic.","zh":"新概念是理解某主題的新想法或新方式。"},{"en":"A child may develop new concepts about floating after testing wood, metal, and plastic.","zh":"孩子測試木、金屬和塑膠後，可能發展關於浮沉的新概念。"},{"en":"New concepts help replace everyday explanations that do not fit evidence.","zh":"新概念幫助取代不符合證據的日常解釋。"},{"en":"This phrase refers to deeper ideas, not just new words.","zh":"這個短語指更深層想法，而不只是新詞語。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":15},{"front":"daily life","meaning":"日常生活","examples":[{"en":"Scientific learning may require changes in ideas used in daily life.","zh":"科學學習可能需要改變日常生活中使用的想法。"},{"en":"Daily life means ordinary activities and situations people experience every day.","zh":"日常生活是人們每天經歷的普通活動和情境。"},{"en":"Cooking, travelling to school, and using a phone are parts of daily life.","zh":"煮飯、上學和使用手機都是日常生活的一部分。"},{"en":"Everyday ideas from daily life can sometimes conflict with scientific explanations.","zh":"來自日常生活的想法有時會與科學解釋相衝突。"},{"en":"This phrase connects classroom learning with normal experience.","zh":"這個短語把課堂學習與正常經驗連接起來。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":15},{"front":"the claim that","meaning":"……的主張","examples":[{"en":"One heading presents the claim that contradiction can assist development.","zh":"其中一個標題提出矛盾可以幫助發展的主張。"},{"en":"The claim that introduces an idea someone says is true.","zh":"某主張，是指引入某人聲稱為真的想法。"},{"en":"A report may test the claim that smaller classes improve learning.","zh":"報告可能測試小班教學改善學習的主張。"},{"en":"Claims need evidence before readers should fully accept them.","zh":"主張需要證據，讀者才應完全接受。"},{"en":"This phrase is common when summarising an argument.","zh":"這個短語常用於概括論點。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":15},{"front":"perceived contradiction","meaning":"被察覺的矛盾","examples":[{"en":"A perceived contradiction can challenge a learner’s thinking.","zh":"被察覺的矛盾可以挑戰學習者的思維。"},{"en":"A perceived contradiction is a conflict that someone notices between ideas, evidence, or explanations.","zh":"被察覺的矛盾，是某人注意到想法、證據或解釋之間有衝突。"},{"en":"A student may notice a perceived contradiction when an experiment gives a different result from their prediction.","zh":"當實驗結果不同於預測時，學生可能注意到被察覺的矛盾。"},{"en":"Perceived contradictions can push learners to ask why their original idea failed.","zh":"被察覺的矛盾可以推動學習者追問原有想法為何失效。"},{"en":"This phrase refers to contradiction as experienced by the learner.","zh":"這個短語指學習者感受到的矛盾。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":15},{"front":"assist mental development","meaning":"幫助心智發展","examples":[{"en":"Conflict may assist mental development.","zh":"衝突可能幫助心智發展。"},{"en":"To assist mental development means to help a person’s thinking and reasoning grow.","zh":"幫助心智發展，是指幫助一個人的思考和推理成長。"},{"en":"Challenging puzzles can assist mental development by making children test ideas.","zh":"具挑戰性的謎題可以透過令孩子測試想法來幫助心智發展。"},{"en":"Supportive disagreement can help learners explain and improve their reasoning.","zh":"支持性的分歧可以幫助學習者解釋並改善推理。"},{"en":"This phrase describes helping the mind mature.","zh":"這個短語描述幫助心智成熟。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":15},{"front":"implications for","meaning":"對……的影響；啟示","examples":[{"en":"The heading refers to implications for the training of science teachers.","zh":"該標題指對科學教師培訓的影響或啟示。"},{"en":"Implications for something are the possible effects or lessons for that area.","zh":"對某事的啟示，是指對該範疇可能產生的影響或教訓。"},{"en":"Research on student stress has implications for school timetables.","zh":"關於學生壓力的研究對學校時間表有啟示。"},{"en":"If peer conflict helps learning, there may be implications for how teachers manage group work.","zh":"如果同輩衝突有助學習，這對教師如何管理小組活動可能有啟示。"},{"en":"This phrase asks what a finding means for future practice.","zh":"這個短語詢問某發現對未來實踐意味着甚麼。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":16},{"front":"training of science teachers","meaning":"科學教師培訓","examples":[{"en":"The question list mentions the training of science teachers.","zh":"題目列表提到科學教師培訓。"},{"en":"Training of science teachers means preparing teachers to teach science effectively.","zh":"科學教師培訓，是指準備教師有效教授科學。"},{"en":"Science-teacher training may include experiments, classroom questioning, and handling misconceptions.","zh":"科學教師培訓可能包括實驗、課堂提問和處理誤解。"},{"en":"Good training helps teachers move beyond definitions and support conceptual change.","zh":"良好培訓幫助教師超越定義，並支持概念轉變。"},{"en":"This phrase refers to professional preparation for science educators.","zh":"這個短語指科學教育者的專業準備。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":16},{"front":"an experiment to assess","meaning":"用以評估……的實驗","examples":[{"en":"The paragraph describes an experiment to assess the benefits of pair work.","zh":"該段描述一項用以評估二人合作學習好處的實驗。"},{"en":"An experiment to assess something is a planned test designed to evaluate it.","zh":"用以評估某事的實驗，是為評價它而設計的有計劃測試。"},{"en":"A school may run an experiment to assess whether shorter homework improves sleep.","zh":"學校可能進行實驗，以評估較短功課是否改善睡眠。"},{"en":"Experiments help researchers move from opinion to evidence.","zh":"實驗幫助研究人員從意見走向證據。"},{"en":"This phrase introduces the purpose of a study.","zh":"這個短語引入研究目的。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":16},{"front":"benefits of exchanging views","meaning":"交流觀點的好處","examples":[{"en":"The study examined the benefits of exchanging views with a partner.","zh":"研究考察與伙伴交流觀點的好處。"},{"en":"Benefits of exchanging views are the advantages gained from sharing and comparing opinions.","zh":"交流觀點的好處，是指分享和比較意見所帶來的優點。"},{"en":"Students may discover weaknesses in their answers through exchanging views.","zh":"學生可能透過交流觀點發現自己答案的弱點。"},{"en":"Exchanging views can improve learning because different explanations challenge assumptions.","zh":"交流觀點可以改善學習，因為不同解釋會挑戰假設。"},{"en":"This phrase highlights the value of discussion.","zh":"這個短語突出討論的價值。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":16},{"front":"with a partner","meaning":"與一名伙伴","examples":[{"en":"Pupils exchanged views with a partner during pair work.","zh":"學生在二人合作學習期間與一名伙伴交流觀點。"},{"en":"With a partner means together with one other person.","zh":"與一名伙伴，是指與另一個人一起。"},{"en":"Students may practise speaking with a partner before answering the teacher.","zh":"學生可能先與一名伙伴練習說話，再回答老師。"},{"en":"Working with a partner gives learners more chance to explain than whole-class discussion.","zh":"與伙伴合作讓學習者比全班討論有更多機會解釋。"},{"en":"This phrase describes two-person collaboration.","zh":"這個短語描述二人合作。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":16},{"front":"evidence for","meaning":"支持……的證據","examples":[{"en":"The heading asks for evidence for delayed benefits.","zh":"該標題要求找出支持延後出現好處的證據。"},{"en":"Evidence for something is information that supports or proves it.","zh":"支持某事的證據，是支持或證明它的資料。"},{"en":"Improved post-test scores can provide evidence for a new teaching method.","zh":"後測分數提高可以提供支持新教學方法的證據。"},{"en":"Evidence is important because attractive ideas may still be wrong.","zh":"證據很重要，因為吸引人的想法仍可能是錯的。"},{"en":"This phrase introduces support for a claim.","zh":"這個短語引入對主張的支持。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":16},{"front":"delayed benefits","meaning":"延後出現的好處","examples":[{"en":"The experiment suggested delayed benefits of disagreement between pupils.","zh":"實驗顯示學生之間分歧有延後出現的好處。"},{"en":"Delayed benefits are positive effects that appear later rather than immediately.","zh":"延後出現的好處，是指正面效果不是立即出現，而是之後才出現。"},{"en":"Regular exercise may have delayed benefits, such as better sleep after several weeks.","zh":"定期運動可能有延後好處，例如幾星期後睡眠改善。"},{"en":"Learning benefits may be delayed because students need time to reorganise ideas.","zh":"學習好處可能延後，因為學生需要時間重組想法。"},{"en":"This phrase contrasts later improvement with instant results.","zh":"這個短語把後來改善與即時結果作對比。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":16},{"front":"disagreement between pupils","meaning":"學生之間的分歧","examples":[{"en":"Disagreement between pupils may lead to later cognitive progress.","zh":"學生之間的分歧可能導致之後的認知進展。"},{"en":"Disagreement between pupils means students have different opinions or explanations.","zh":"學生之間的分歧，是指學生有不同意見或解釋。"},{"en":"Two pupils may disagree about why a ball falls in a curved path.","zh":"兩名學生可能對球為何沿曲線下墜有分歧。"},{"en":"Disagreement can help learning when students must justify their ideas.","zh":"當學生必須為想法提出理由時，分歧可以幫助學習。"},{"en":"This phrase refers to peer conflict in a learning setting.","zh":"這個短語指學習情境中的同輩衝突。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":16},{"front":"choose two letters","meaning":"選出兩個字母","examples":[{"en":"Candidates choose two letters from the options.","zh":"考生從選項中選出兩個字母。"},{"en":"To choose two letters means to select two answer choices, usually from a list.","zh":"選出兩個字母，是指通常從列表中選擇兩個答案選項。"},{"en":"In an exam, students may choose two letters if two statements are correct.","zh":"在考試中，如果兩個陳述正確，學生可能需要選出兩個字母。"},{"en":"This instruction warns candidates that one answer is not enough.","zh":"這項指示提醒考生，一個答案並不足夠。"},{"en":"It is common in multiple-answer reading questions.","zh":"它常見於多答案閱讀題。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":16},{"front":"statements about learning","meaning":"關於學習的陳述","examples":[{"en":"The question asks which statements about learning are attributed to Piaget.","zh":"題目問哪些關於學習的陳述被歸因於皮亞傑。"},{"en":"Statements about learning are sentences that express ideas or claims about how people learn.","zh":"關於學習的陳述，是表達人們如何學習的想法或主張的句子。"},{"en":"A statement about learning may say that feedback helps students improve faster.","zh":"關於學習的陳述可能說回饋幫助學生更快進步。"},{"en":"Such statements must be matched carefully to the person or theory that supports them.","zh":"這類陳述必須仔細配對到支持它們的人或理論。"},{"en":"This phrase refers to claims, not examples only.","zh":"這個短語指主張，而不只是例子。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":16},{"front":"be attributed to","meaning":"被歸因於","examples":[{"en":"Some statements about learning are attributed to Piaget.","zh":"有些關於學習的陳述被歸因於皮亞傑。"},{"en":"To be attributed to someone means to be credited to that person as the source.","zh":"被歸因於某人，是指被認為來源於那個人。"},{"en":"A quote may be wrongly attributed to a famous writer online.","zh":"網上一句引文可能被錯誤歸因於某位著名作家。"},{"en":"Attribution matters because it shows whose idea is being discussed.","zh":"歸因很重要，因為它顯示正在討論的是誰的想法。"},{"en":"This phrase is common in academic reading tasks.","zh":"這個短語常見於學術閱讀題。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":16},{"front":"assist learning","meaning":"協助學習","examples":[{"en":"The option says that teachers can assist learning by explaining concepts.","zh":"該選項說教師可以透過解釋概念來協助學習。"},{"en":"To assist learning means to help people learn more effectively.","zh":"協助學習，是指幫助人更有效地學習。"},{"en":"Clear examples assist learning because students can see how an idea works.","zh":"清楚例子能協助學習，因為學生可以看見概念如何運作。"},{"en":"Teachers can assist learning, but students also need to think actively.","zh":"教師可以協助學習，但學生也需要主動思考。"},{"en":"This phrase describes support that improves understanding.","zh":"這個短語描述改善理解的支援。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":17},{"front":"explain difficult concepts","meaning":"解釋困難概念","examples":[{"en":"Teachers may try to explain difficult concepts to students.","zh":"教師可能嘗試向學生解釋困難概念。"},{"en":"To explain difficult concepts means to make hard ideas easier to understand.","zh":"解釋困難概念，是指令艱深想法更容易理解。"},{"en":"A teacher may use water and cups to explain volume and capacity.","zh":"老師可能用水和杯子解釋體積和容量。"},{"en":"Explanations help, but students may still need experiments or discussion.","zh":"解釋有幫助，但學生仍可能需要實驗或討論。"},{"en":"This phrase describes one common teaching action.","zh":"這個短語描述一種常見教學行動。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":17},{"front":"mental challenge","meaning":"心智挑戰","examples":[{"en":"Piaget believed that mental challenge could stimulate learning.","zh":"皮亞傑相信心智挑戰可以刺激學習。"},{"en":"Mental challenge is a task or situation that makes someone think hard.","zh":"心智挑戰是令某人努力思考的任務或情境。"},{"en":"A puzzle that has no obvious answer can be a mental challenge.","zh":"沒有明顯答案的謎題可以是一種心智挑戰。"},{"en":"Mental challenge can help learning because it forces learners to question old ideas.","zh":"心智挑戰可以幫助學習，因為它迫使學習者質疑舊想法。"},{"en":"This phrase refers to difficulty in thinking, not physical effort.","zh":"這個短語指思考上的困難，而不是體力。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":17},{"front":"a stimulus to learning","meaning":"學習的刺激因素","examples":[{"en":"Mental challenge may be a stimulus to learning.","zh":"心智挑戰可能是學習的刺激因素。"},{"en":"A stimulus to learning is something that encourages or starts the learning process.","zh":"學習的刺激因素，是鼓勵或啟動學習過程的東西。"},{"en":"A surprising experiment can be a stimulus to learning because students want to know why it happened.","zh":"令人驚訝的實驗可以成為學習刺激因素，因為學生想知道為何會發生。"},{"en":"Good questions stimulate learning by creating curiosity and effort.","zh":"好問題透過產生好奇和努力來刺激學習。"},{"en":"This phrase describes what pushes learning forward.","zh":"這個短語描述推動學習前進的東西。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":17},{"front":"repetition and consistency of input","meaning":"輸入的重複和一致性","examples":[{"en":"The option refers to repetition and consistency of input.","zh":"該選項指輸入的重複和一致性。"},{"en":"Repetition and consistency of input means receiving the same kind of information steadily and repeatedly.","zh":"輸入的重複和一致性，是指穩定而反覆接收同類資訊。"},{"en":"Language learners benefit when useful phrases appear again and again in clear examples.","zh":"當有用短語在清楚例句中反覆出現，語言學習者會受益。"},{"en":"Repetition can help memory, but it may not be enough for conceptual change.","zh":"重複可以幫助記憶，但未必足以帶來概念轉變。"},{"en":"This phrase contrasts repeated information with mental challenge.","zh":"這個短語把重複資訊與心智挑戰作對比。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":17},{"front":"aid cognitive development","meaning":"幫助認知發展","examples":[{"en":"The option suggests that repetition may aid cognitive development.","zh":"該選項暗示重複可能幫助認知發展。"},{"en":"To aid cognitive development means to help thinking, reasoning, and understanding grow.","zh":"幫助認知發展，是指幫助思考、推理和理解成長。"},{"en":"Reading stories with children can aid cognitive development by building language and imagination.","zh":"與孩子閱讀故事可以透過建立語言和想像力來幫助認知發展。"},{"en":"Activities aid development best when children actively think, explain, and test ideas.","zh":"當孩子主動思考、解釋和測試想法時，活動最能幫助發展。"},{"en":"This phrase describes support for mental growth.","zh":"這個短語描述對心智成長的支援。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":17},{"front":"reject evidence","meaning":"拒絕證據","examples":[{"en":"Children sometimes reject evidence that conflicts with their ideas.","zh":"孩子有時會拒絕與自己想法相衝突的證據。"},{"en":"To reject evidence means to refuse to accept information as valid or important.","zh":"拒絕證據，是指不接受資料為有效或重要。"},{"en":"A student may reject evidence from an experiment if it does not match their prediction.","zh":"如果實驗結果不符合預測，學生可能拒絕證據。"},{"en":"Rejecting evidence can protect old beliefs but block learning.","zh":"拒絕證據可以保護舊信念，但會阻礙學習。"},{"en":"This phrase describes resistance to facts or observations.","zh":"這個短語描述對事實或觀察的抗拒。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":17},{"front":"conflict with preconceptions","meaning":"與先入為主的想法相衝突","examples":[{"en":"Evidence may conflict with children’s preconceptions.","zh":"證據可能與孩子先入為主的想法相衝突。"},{"en":"To conflict with preconceptions means to go against ideas people already had before learning.","zh":"與先入為主的想法相衝突，是指與人們學習前已有的想法相反。"},{"en":"A science result may conflict with a child’s belief that heavier objects always fall faster.","zh":"科學結果可能與孩子「較重物件一定下墜較快」的信念相衝突。"},{"en":"When evidence conflicts with preconceptions, learners may feel confused or defensive.","zh":"當證據與先入為主的想法相衝突時，學習者可能感到困惑或防衛。"},{"en":"This phrase explains why conceptual change can be difficult.","zh":"這個短語解釋為何概念轉變可能困難。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":17},{"front":"preconceptions","meaning":"先入為主的觀念","examples":[{"en":"Children’s preconceptions may resist new evidence.","zh":"孩子先入為主的觀念可能抗拒新證據。"},{"en":"Preconceptions are beliefs or ideas people already have before they learn more.","zh":"先入為主的觀念，是人們在進一步學習前已經有的信念或想法。"},{"en":"A student may have the preconception that science is only about memorising facts.","zh":"學生可能有「科學只是記憶事實」這種先入為主的觀念。"},{"en":"Preconceptions affect how learners interpret new information.","zh":"先入為主的觀念會影響學習者如何理解新資訊。"},{"en":"This word often refers to ideas that may need to be challenged.","zh":"這個詞常指可能需要被挑戰的想法。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":17},{"front":"help one another","meaning":"互相幫助","examples":[{"en":"The option suggests that children can help one another make progress.","zh":"該選項暗示孩子可以互相幫助取得進步。"},{"en":"To help one another means to support each other mutually.","zh":"互相幫助，是指彼此提供支持。"},{"en":"Students help one another when they explain difficult steps in a maths problem.","zh":"學生解釋數學題中的困難步驟時，就是互相幫助。"},{"en":"Helping one another can improve learning because students hear ideas in familiar language.","zh":"互相幫助可以改善學習，因為學生聽到用熟悉語言表達的想法。"},{"en":"This phrase describes mutual support, not one-way teaching only.","zh":"這個短語描述相互支持，而不只是單向教學。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":17},{"front":"make cognitive progress","meaning":"取得認知進步","examples":[{"en":"Children may make cognitive progress through challenging tasks.","zh":"孩子可能透過具挑戰性的任務取得認知進步。"},{"en":"To make cognitive progress means to improve in thinking, reasoning, or understanding.","zh":"取得認知進步，是指在思考、推理或理解上有所改善。"},{"en":"A child makes cognitive progress when they learn to explain evidence instead of guessing.","zh":"當孩子學會解釋證據而不是猜測時，就取得認知進步。"},{"en":"Cognitive progress may appear later, after students have time to rethink.","zh":"認知進步可能在學生有時間重新思考後才出現。"},{"en":"This phrase refers to mental improvement, not just higher marks.","zh":"這個短語指心智改善，而不只是分數提高。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":17},{"front":"describe an experiment","meaning":"描述一項實驗","examples":[{"en":"The question asks which statements describe Howe’s experiment.","zh":"題目問哪些陳述描述 Howe 的實驗。"},{"en":"To describe an experiment means to explain its participants, method, task, and results.","zh":"描述一項實驗，是指解釋其參與者、方法、任務和結果。"},{"en":"A student may describe an experiment by saying what was tested and what was measured.","zh":"學生可能透過說明測試甚麼和測量甚麼來描述實驗。"},{"en":"Clear descriptions help readers judge whether the conclusion is supported.","zh":"清楚描述幫助讀者判斷結論是否有支持。"},{"en":"This phrase refers to explaining research design and findings.","zh":"這個短語指解釋研究設計和發現。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":18},{"front":"ability to understand","meaning":"理解能力","examples":[{"en":"The children were assessed on their ability to understand a scientific problem.","zh":"兒童被評估其理解科學問題的能力。"},{"en":"Ability to understand means the capacity to make sense of an idea, question, or situation.","zh":"理解能力是明白一個想法、問題或情境的能力。"},{"en":"A reading test may assess a student’s ability to understand the writer’s argument.","zh":"閱讀測驗可能評估學生理解作者論點的能力。"},{"en":"Understanding ability matters because students may repeat words without grasping meaning.","zh":"理解能力很重要，因為學生可能複述詞語卻沒有掌握意思。"},{"en":"This phrase refers to comprehension, not memory alone.","zh":"這個短語指理解，而不只是記憶。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":18},{"front":"scientific problem","meaning":"科學問題","examples":[{"en":"The children worked on a scientific problem about motion.","zh":"兒童處理一個關於運動的科學問題。"},{"en":"A scientific problem is a question that can be explored using evidence, observation, and reasoning.","zh":"科學問題是可以用證據、觀察和推理探究的問題。"},{"en":"“Why does this object float?” is a simple scientific problem for children.","zh":"「為何這個物件會浮起？」是給孩子的簡單科學問題。"},{"en":"Scientific problems help students test ideas rather than simply accept answers.","zh":"科學問題幫助學生測試想法，而不是單純接受答案。"},{"en":"This phrase refers to a problem about how the natural world works.","zh":"這個短語指關於自然世界如何運作的問題。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":18},{"front":"mixed-ability groups","meaning":"混合能力小組","examples":[{"en":"The option refers to children working in mixed-ability groups.","zh":"該選項指兒童在混合能力小組中學習。"},{"en":"Mixed-ability groups contain learners with different levels of skill or understanding.","zh":"混合能力小組包含技能或理解水平不同的學習者。"},{"en":"A teacher may use mixed-ability groups so stronger students can explain ideas to others.","zh":"老師可能使用混合能力小組，讓能力較強學生向其他人解釋想法。"},{"en":"These groups can support learning, but they need good organisation to work well.","zh":"這些小組可以支持學習，但需要良好組織才有效。"},{"en":"This phrase focuses on differences in ability within a group.","zh":"這個短語聚焦小組內能力差異。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":18},{"front":"talk most","meaning":"說話最多","examples":[{"en":"The option asks whether the children who talked most made the least progress.","zh":"該選項問說話最多的兒童是否進展最少。"},{"en":"To talk most means to speak more than the other people in a group.","zh":"說話最多，是指在小組中比其他人說更多話。"},{"en":"In a discussion, the student who talks most is not always the one who learns most.","zh":"在討論中，說話最多的學生不一定學得最多。"},{"en":"Speaking a lot can help if it involves explanation, but it can also block others.","zh":"如果說話涉及解釋，說很多可以有幫助；但也可能阻礙別人。"},{"en":"This phrase describes amount of speech, not quality of thinking.","zh":"這個短語描述說話量，而不是思考質素。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":18},{"front":"make the least progress","meaning":"進展最少","examples":[{"en":"The option describes pupils who made the least progress.","zh":"該選項描述進展最少的學生。"},{"en":"To make the least progress means to improve less than everyone else or less than other groups.","zh":"進展最少，是指比所有其他人或其他組別改善得更少。"},{"en":"A student may make the least progress if the task is too easy or too confusing.","zh":"如果任務太容易或太混亂，學生可能進展最少。"},{"en":"Comparing who makes the least progress helps identify weak learning conditions.","zh":"比較誰進展最少，有助識別薄弱學習條件。"},{"en":"This phrase describes the smallest amount of improvement.","zh":"這個短語描述最小的改善幅度。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":18},{"front":"a total of three tests","meaning":"總共三次測驗","examples":[{"en":"The children were given a total of three tests at different times.","zh":"兒童在不同時間總共接受三次測驗。"},{"en":"A total of three tests means three tests altogether.","zh":"總共三次測驗，是指合共三個測驗。"},{"en":"A language course may include a total of three tests: before, immediately after, and one month later.","zh":"語言課程可能包括總共三次測驗：課前、課後立即、一個月後。"},{"en":"Several tests can show whether improvement is immediate or delayed.","zh":"多次測驗可以顯示改善是即時還是延後出現。"},{"en":"This phrase gives the complete number of assessments.","zh":"這個短語給出評估的完整數量。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":18},{"front":"at different times","meaning":"在不同時間","examples":[{"en":"The tests were given at different times.","zh":"測驗在不同時間進行。"},{"en":"At different times means not all at once, but on separate occasions.","zh":"在不同時間，是指不是同一時間，而是在分開的場合。"},{"en":"A teacher may check students’ writing at different times during the term.","zh":"老師可能在學期中不同時間檢查學生寫作。"},{"en":"Testing at different times can show whether learning lasts.","zh":"在不同時間測試可以顯示學習是否持久。"},{"en":"This phrase highlights timing differences.","zh":"這個短語突出時間上的差異。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":18},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Candidates complete the summary below using words from the passage.","zh":"考生使用篇章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the short text that follows.","zh":"完成以下摘要，是指填寫接下來短文中的缺失字詞。"},{"en":"Students complete a summary by finding exact information in the reading passage.","zh":"學生透過在閱讀篇章中找出準確資料來完成摘要。"},{"en":"This task checks whether learners understand the main ideas and sequence.","zh":"這項任務檢查學習者是否理解主要概念和次序。"},{"en":"The phrase is common in IELTS reading instructions.","zh":"這個短語常見於 IELTS 閱讀指示。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":18},{"front":"no more than two words","meaning":"不多於兩個字","examples":[{"en":"Candidates choose no more than two words from the passage.","zh":"考生從篇章中選取不多於兩個字。"},{"en":"No more than two words means the answer can have one word or two words, but not three.","zh":"不多於兩個字，是指答案可以有一個字或兩個字，但不能有三個。"},{"en":"“Peer conflict” fits the rule because it has two words.","zh":"“Peer conflict” 符合規則，因為它有兩個字。"},{"en":"Students lose marks if they write more words than the instruction allows.","zh":"如果學生寫超過指示允許的字數，就會失分。"},{"en":"This phrase tests both meaning and exact answer control.","zh":"這個短語同時測試意思和答案精準控制。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":18},{"front":"learning takes place","meaning":"學習發生","examples":[{"en":"Piaget proposed that learning takes place when children encounter conflict.","zh":"皮亞傑提出，當孩子遇到衝突時，學習就會發生。"},{"en":"Learning takes place means learning happens or occurs.","zh":"學習發生，是指學習出現或產生。"},{"en":"Learning takes place when students connect a mistake with a better explanation.","zh":"當學生把錯誤與更好的解釋連接起來時，學習就會發生。"},{"en":"Learning may take place during discussion, experiments, reflection, or feedback.","zh":"學習可能在討論、實驗、反思或回饋中發生。"},{"en":"This phrase is a formal way to say that learning happens.","zh":"這個短語是表達 learning happens 的正式說法。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":18},{"front":"encounter ideas","meaning":"遇到想法","examples":[{"en":"Children may learn when they encounter ideas that challenge their beliefs.","zh":"孩子遇到挑戰其信念的想法時，可能會學習。"},{"en":"To encounter ideas means to come across or meet new thoughts or explanations.","zh":"遇到想法，是指接觸或碰到新的思想或解釋。"},{"en":"Students encounter new ideas when they read articles from different viewpoints.","zh":"學生閱讀不同觀點的文章時，會遇到新想法。"},{"en":"New ideas can challenge old beliefs and start deeper learning.","zh":"新想法可以挑戰舊信念，並開始更深入學習。"},{"en":"This phrase describes meeting ideas, not physically meeting people.","zh":"這個短語描述接觸想法，而不是身體上遇見人。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":19},{"front":"correspond to","meaning":"與……相符","examples":[{"en":"New ideas may not correspond to a child’s current beliefs.","zh":"新想法可能與孩子目前信念不相符。"},{"en":"To correspond to something means to match, fit, or be consistent with it.","zh":"與某事相符，是指配合、符合或一致。"},{"en":"A map symbol should correspond to the object it represents.","zh":"地圖符號應與它代表的物件相符。"},{"en":"If evidence does not correspond to a student’s belief, conflict may occur.","zh":"如果證據與學生信念不相符，就可能出現衝突。"},{"en":"This phrase is useful when comparing ideas with facts or expectations.","zh":"當比較想法與事實或期望時，這個短語很有用。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":19},{"front":"current beliefs","meaning":"目前信念","examples":[{"en":"Learning may occur when new ideas conflict with current beliefs.","zh":"當新想法與目前信念相衝突時，學習可能發生。"},{"en":"Current beliefs are ideas a person holds at the present time.","zh":"目前信念是某人在當前持有的想法。"},{"en":"A student’s current belief may be that mistakes mean failure.","zh":"學生目前信念可能是錯誤代表失敗。"},{"en":"When current beliefs meet strong evidence, they may be revised.","zh":"當目前信念遇到有力證據時，它們可能被修正。"},{"en":"This phrase describes what someone believes before change happens.","zh":"這個短語描述改變發生前某人相信的內容。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":19},{"front":"application of this theory","meaning":"這套理論的應用","examples":[{"en":"The application of this theory led to a new teaching method.","zh":"這套理論的應用導致一種新教學方法。"},{"en":"Application of this theory means using the theory in practice.","zh":"這套理論的應用，是指在實踐中使用該理論。"},{"en":"A school may test the application of a learning theory in real classrooms.","zh":"學校可能在真實課堂中測試某學習理論的應用。"},{"en":"Theory becomes useful when application changes what teachers and students do.","zh":"當應用改變教師和學生所做的事，理論才變得有用。"},{"en":"This phrase connects academic ideas with practical teaching.","zh":"這個短語把學術想法與實際教學連接起來。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":19},{"front":"give rise to","meaning":"產生；引致","examples":[{"en":"The theory gave rise to a teaching method known as discovery learning.","zh":"這套理論產生了一種被稱為發現式學習的教學方法。"},{"en":"To give rise to something means to cause it to appear or develop.","zh":"產生某事，是指導致它出現或發展。"},{"en":"New technology can give rise to new jobs and new problems.","zh":"新科技可以產生新工作，也可以引致新問題。"},{"en":"A theory can give rise to teaching methods when educators apply it in classrooms.","zh":"當教育者在課堂應用理論，它可以產生教學方法。"},{"en":"This phrase connects an origin with a result.","zh":"這個短語把來源與結果連接起來。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":19},{"front":"teaching method","meaning":"教學方法","examples":[{"en":"Discovery learning is a teaching method based on active problem-solving.","zh":"發現式學習是一種以主動解決問題為基礎的教學方法。"},{"en":"A teaching method is a way teachers organise learning and help students understand.","zh":"教學方法是教師組織學習並幫助學生理解的方式。"},{"en":"Role-play is a teaching method that can help students practise speaking.","zh":"角色扮演是一種可以幫助學生練習口語的教學方法。"},{"en":"Different teaching methods create different kinds of student participation.","zh":"不同教學方法會產生不同形式的學生參與。"},{"en":"This phrase refers to how teaching is carried out.","zh":"這個短語指教學如何進行。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":19},{"front":"known as","meaning":"被稱為","examples":[{"en":"The method became known as discovery learning.","zh":"這種方法後來被稱為發現式學習。"},{"en":"Known as means called by a particular name.","zh":"被稱為，是指以某個特定名稱稱呼。"},{"en":"The city is known as a centre of trade and finance.","zh":"這座城市被稱為貿易和金融中心。"},{"en":"A method becomes easier to discuss when it is known by a clear label.","zh":"當方法有清楚名稱時，就更容易討論。"},{"en":"This phrase introduces a name or title.","zh":"這個短語引入名稱或標題。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":19},{"front":"at first","meaning":"起初","examples":[{"en":"At first, the approach focused on the individual learner.","zh":"起初，這種方法集中於個別學習者。"},{"en":"At first means in the beginning, before later changes happened.","zh":"起初是指在開始時，在後來改變發生之前。"},{"en":"At first, students may copy examples before they can write independently.","zh":"起初，學生可能先模仿例子，之後才能獨立寫作。"},{"en":"This phrase often prepares readers for a contrast with what happened later.","zh":"這個短語常為之後發生的對比作準備。"},{"en":"It helps show development over time.","zh":"它幫助顯示隨時間發展。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":19},{"front":"focus only on","meaning":"只集中於","examples":[{"en":"The early approach focused only on the individual pupil.","zh":"早期方法只集中於個別學生。"},{"en":"To focus only on something means to pay attention to that thing and ignore others.","zh":"只集中於某事，是指只注意該事而忽略其他。"},{"en":"A student who focuses only on grammar may forget ideas and organisation.","zh":"只集中於文法的學生可能忘記內容和組織。"},{"en":"Focusing only on the individual learner may overlook the value of peer discussion.","zh":"只集中於個別學習者，可能忽略同輩討論的價值。"},{"en":"This phrase often signals a limitation.","zh":"這個短語常表示局限。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":19},{"front":"relationship between…and…","meaning":"……與……之間的關係","examples":[{"en":"The approach focused on the relationship between pupils and learning situations.","zh":"這種方法集中於學生與學習情境之間的關係。"},{"en":"The relationship between two things is how they connect or affect each other.","zh":"兩者之間的關係，是指它們如何連接或互相影響。"},{"en":"Teachers may study the relationship between homework and student stress.","zh":"教師可能研究功課與學生壓力之間的關係。"},{"en":"Understanding relationships between factors helps explain learning outcomes.","zh":"理解因素之間的關係有助解釋學習結果。"},{"en":"This phrase is useful when two elements must be considered together.","zh":"當兩個元素必須一起考慮時，這個短語很有用。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":19},{"front":"individual pupils","meaning":"個別學生","examples":[{"en":"The early theory focused on individual pupils rather than peer interaction.","zh":"早期理論集中於個別學生，而不是同輩互動。"},{"en":"Individual pupils are single students considered separately from a group.","zh":"個別學生是把單一學生與群體分開來考慮。"},{"en":"A teacher may assess individual pupils to see what each one understands.","zh":"老師可能評估個別學生，以了解每個人明白甚麼。"},{"en":"Focusing on individual pupils can be useful, but it may miss the effect of discussion.","zh":"集中於個別學生可以有用，但可能錯過討論的影響。"},{"en":"This phrase contrasts personal learning with social learning.","zh":"這個短語把個人學習與社交學習作對比。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":19},{"front":"become interested in","meaning":"開始對……感興趣","examples":[{"en":"Researchers later became interested in the role of peer interaction.","zh":"研究人員後來開始對同輩互動的作用感興趣。"},{"en":"To become interested in something means to start wanting to study or know more about it.","zh":"開始對某事感興趣，是指開始想研究或了解更多。"},{"en":"A student may become interested in science after seeing a surprising experiment.","zh":"學生看到令人驚訝的實驗後，可能開始對科學感興趣。"},{"en":"Research interest can shift when earlier theories leave questions unanswered.","zh":"當早期理論留下未解問題，研究興趣可能轉移。"},{"en":"This phrase describes a change in attention or curiosity.","zh":"這個短語描述注意力或好奇心的改變。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":20},{"front":"the role that interaction with","meaning":"與……互動所起的作用","examples":[{"en":"The summary asks about the role that interaction with peers might play.","zh":"摘要問與同輩互動所起的作用。"},{"en":"The role that interaction with someone plays means the effect that communication with them has.","zh":"與某人互動所起的作用，是指與他們溝通所產生的影響。"},{"en":"Teachers may study the role that interaction with classmates plays in confidence building.","zh":"教師可能研究與同學互動在建立信心中所起的作用。"},{"en":"Interaction can affect learning because students explain, question, and compare ideas.","zh":"互動會影響學習，因為學生會解釋、提問和比較想法。"},{"en":"This phrase focuses on what social contact contributes.","zh":"這個短語聚焦社交接觸帶來甚麼貢獻。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":20},{"front":"might also play","meaning":"也可能發揮","examples":[{"en":"Researchers studied the role that peers might also play in development.","zh":"研究人員研究同輩在發展中也可能發揮的作用。"},{"en":"Might also play means may additionally have a part or influence.","zh":"也可能發揮，是指此外也可能有角色或影響。"},{"en":"Teachers guide learning, but classmates might also play an important role.","zh":"教師引導學習，但同學也可能發揮重要作用。"},{"en":"This phrase adds another possible factor to an explanation.","zh":"這個短語把另一個可能因素加入解釋中。"},{"en":"It is cautious because the role is being investigated rather than assumed.","zh":"它較謹慎，因為該作用正在被研究，而不是已被假定。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":20},{"front":"a pupil’s development","meaning":"學生的發展","examples":[{"en":"Peer interaction may influence a pupil’s development.","zh":"同輩互動可能影響學生的發展。"},{"en":"A pupil’s development means the growth of a student’s thinking, skills, behaviour, or understanding.","zh":"學生的發展，是指學生思考、技能、行為或理解的成長。"},{"en":"A pupil’s development can be shaped by teachers, classmates, family, and practice.","zh":"學生的發展可以受教師、同學、家庭和練習塑造。"},{"en":"Supportive discussion may help development by making the pupil explain ideas more clearly.","zh":"支持性討論可能透過令學生更清楚解釋想法來幫助發展。"},{"en":"This phrase refers to gradual growth in a learner.","zh":"這個短語指學習者的逐步成長。"}],"source":"114 - Acquiring the principles of mathematics and science.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 115":[{"front":"sustainable growth","meaning":"可持續增長","examples":[{"en":"The report discusses sustainable growth in the town of Didcot.","zh":"這份報告討論 Didcot 鎮的可持續增長。"},{"en":"Sustainable growth means development that can continue without creating serious long-term problems.","zh":"sustainable growth 指能持續下去，而不造成嚴重長遠問題的發展。"},{"en":"A town achieves sustainable growth when new homes are matched with schools, roads, healthcare and jobs.","zh":"當新住宅配合學校、道路、醫療和就業時，一個市鎮就能達致可持續增長。"},{"en":"If growth is not sustainable, residents may face traffic, overcrowded services and poorer quality of life.","zh":"如果增長不可持續，居民可能面對交通擠塞、服務過度擁擠和生活質素下降。"},{"en":"This phrase is useful when development must balance economic, social and environmental needs.","zh":"當發展必須平衡經濟、社會和環境需要時，這個短語很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":1},{"front":"the outline of a report","meaning":"報告概要","examples":[{"en":"The passage presents the outline of a report by South Oxfordshire District Council.","zh":"文章呈現 South Oxfordshire District Council 一份報告的概要。"},{"en":"The outline of a report is a summary of its main sections, ideas and direction.","zh":"the outline of a report 指報告主要部分、想法和方向的摘要。"},{"en":"A teacher may ask students to write the outline of a report before they draft the full text.","zh":"老師可能要求學生在撰寫完整報告前先寫報告概要。"},{"en":"A clear outline helps readers understand what the report will cover and how it is organised.","zh":"清晰概要幫助讀者理解報告會涵蓋甚麼，以及如何組織。"},{"en":"This phrase refers to the structure and main content, not every detail.","zh":"這個短語指結構和主要內容，而不是每個細節。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":1},{"front":"district council","meaning":"區議會；地方議會","examples":[{"en":"South Oxfordshire District Council produced a report on growth in Didcot.","zh":"South Oxfordshire District Council 就 Didcot 的增長製作了一份報告。"},{"en":"A district council is a local government body responsible for services and planning in a district.","zh":"district council 指負責某區服務和規劃的地方政府機構。"},{"en":"A district council may decide where new housing, roads or community facilities should be built.","zh":"區議會可能決定新房屋、道路或社區設施應建在哪裡。"},{"en":"Good council planning can reduce pressure on schools, transport and public services.","zh":"良好的議會規劃可以減少學校、交通和公共服務壓力。"},{"en":"This phrase is used mainly in local government contexts.","zh":"這個短語主要用於地方政府語境。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":1},{"front":"the South East Plan","meaning":"《東南部計劃》","examples":[{"en":"The UK Government’s South East Plan proposes additional housing growth in Didcot.","zh":"英國政府的《東南部計劃》提出 Didcot 額外房屋增長。"},{"en":"The South East Plan was a planning document concerning development in South East England.","zh":"the South East Plan 是一份關於英格蘭東南部發展的規劃文件。"},{"en":"A regional plan may identify towns where extra homes and infrastructure are expected.","zh":"區域規劃可能指出哪些市鎮預期要增加住宅和基建。"},{"en":"Such plans affect local councils because they shape housing targets and investment needs.","zh":"這類計劃會影響地方議會，因為它們塑造房屋目標和投資需要。"},{"en":"This phrase names a specific planning policy, not a general idea.","zh":"這個短語指一項特定規劃政策，而不是一般概念。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":1},{"front":"propose additional housing growth","meaning":"提出額外房屋增長","examples":[{"en":"The South East Plan proposes additional housing growth in Didcot.","zh":"《東南部計劃》提出 Didcot 額外房屋增長。"},{"en":"To propose additional housing growth means to suggest building more homes than previously planned.","zh":"propose additional housing growth 指建議興建比原先計劃更多的住宅。"},{"en":"A council may propose additional housing growth when population pressure increases.","zh":"當人口壓力增加，議會可能提出額外房屋增長。"},{"en":"More housing can help families find homes, but it also creates demand for roads, schools and services.","zh":"更多房屋可以幫助家庭找到住所，但也會增加道路、學校和服務需求。"},{"en":"This phrase connects planning decisions with future development needs.","zh":"這個短語把規劃決定與未來發展需要連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":1},{"front":"additional housing growth","meaning":"額外房屋增長","examples":[{"en":"Additional housing growth may place pressure on local infrastructure.","zh":"額外房屋增長可能對本地基建造成壓力。"},{"en":"Additional housing growth means extra development of new homes in an area.","zh":"additional housing growth 指某地額外興建新住宅的發展。"},{"en":"A town with additional housing growth may need more buses, clinics, parks and classrooms.","zh":"有額外房屋增長的市鎮可能需要更多巴士、診所、公園和課室。"},{"en":"If infrastructure does not grow at the same time, residents may feel the town is overcrowded.","zh":"如果基建沒有同時增長，居民可能覺得市鎮過度擁擠。"},{"en":"This phrase is often used in urban planning and local government reports.","zh":"這個短語常用於城市規劃和地方政府報告。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":1},{"front":"a designated growth area","meaning":"指定增長區","examples":[{"en":"Didcot has been a designated growth area since 1979.","zh":"Didcot 自 1979 年以來一直是指定增長區。"},{"en":"A designated growth area is a place officially chosen for future development and expansion.","zh":"designated growth area 指被官方選定作未來發展和擴展的地方。"},{"en":"A government may make a town a designated growth area because it has land and transport links.","zh":"政府可能因一個市鎮有土地和交通連接，而把它列為指定增長區。"},{"en":"Once an area receives this label, more housing and infrastructure planning usually follows.","zh":"一旦某地獲得這個標籤，通常會跟隨更多房屋和基建規劃。"},{"en":"This phrase shows that growth is planned by policy, not completely accidental.","zh":"這個短語顯示增長是由政策規劃，而不是完全偶然。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":1},{"front":"since 1979","meaning":"自 1979 年以來","examples":[{"en":"Didcot has been a designated growth area since 1979.","zh":"Didcot 自 1979 年以來一直是指定增長區。"},{"en":"Since 1979 means from the year 1979 up to the present or another stated time.","zh":"since 1979 指從 1979 年起直到現在或另一個指定時間。"},{"en":"The school has used the same sports field since 1979.","zh":"這間學校自 1979 年以來一直使用同一個運動場。"},{"en":"A policy that has existed since 1979 may have shaped several generations of local development.","zh":"自 1979 年以來存在的政策，可能塑造了幾代本地發展。"},{"en":"This phrase gives a starting point for a long period.","zh":"這個短語提供一段長時間的起點。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":1},{"front":"consider that","meaning":"認為","examples":[{"en":"The council considers that Didcot has potential for further growth.","zh":"議會認為 Didcot 有進一步增長的潛力。"},{"en":"To consider that something is true means to believe it after thinking about the evidence.","zh":"consider that something is true 指在思考證據後相信某事是真的。"},{"en":"A teacher may consider that a student needs more reading practice after checking several essays.","zh":"老師檢查幾篇文章後，可能認為學生需要更多閱讀練習。"},{"en":"When councils consider that growth is possible, they must also consider services and costs.","zh":"當議會認為增長可行時，也必須考慮服務和成本。"},{"en":"This phrase is formal and common in reports and official writing.","zh":"這個短語較正式，常見於報告和官方寫作。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":1},{"front":"have potential for","meaning":"有……的潛力","examples":[{"en":"Didcot has potential for further growth.","zh":"Didcot 有進一步增長的潛力。"},{"en":"To have potential for something means to have the ability or conditions to develop in that way.","zh":"have potential for something 指具備向某方向發展的能力或條件。"},{"en":"A student has potential for improvement if she works hard and receives clear feedback.","zh":"如果學生努力並得到清楚回饋，她就有進步的潛力。"},{"en":"A town has potential for growth when it has land, transport links and job opportunities.","zh":"當市鎮有土地、交通連接和就業機會，它就有增長潛力。"},{"en":"This phrase suggests possibility, not guaranteed success.","zh":"這個短語表示可能性，而不是保證成功。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":1},{"front":"further growth","meaning":"進一步增長","examples":[{"en":"Didcot may have potential for further growth.","zh":"Didcot 可能有進一步增長的潛力。"},{"en":"Further growth means more development or expansion beyond what has already happened.","zh":"further growth 指在已發生的發展以外再有更多擴展。"},{"en":"A business may plan further growth after opening several successful branches.","zh":"企業開設幾間成功分店後，可能計劃進一步增長。"},{"en":"Further growth can bring benefits, but only if the necessary support systems are ready.","zh":"進一步增長可以帶來好處，但前提是必要支援系統已準備好。"},{"en":"This phrase is useful when discussing the next stage of development.","zh":"討論下一階段發展時，這個短語很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":1},{"front":"such development","meaning":"這類發展","examples":[{"en":"The council believes that such development should be sustainable.","zh":"議會相信這類發展應該是可持續的。"},{"en":"Such development refers to the kind of development just mentioned earlier.","zh":"such development 指剛才提到的那種發展。"},{"en":"If a town adds thousands of new homes, such development must include roads and services.","zh":"如果一個市鎮增加數千間新住宅，這類發展必須包括道路和服務。"},{"en":"Without careful planning, such development can create pressure rather than improvement.","zh":"如果沒有仔細規劃，這類發展可能造成壓力，而不是改善。"},{"en":"This phrase helps avoid repeating the same long noun phrase.","zh":"這個短語有助避免重複同一個長名詞短語。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":2},{"front":"sustainable","meaning":"可持續的","examples":[{"en":"Future development should be sustainable and well planned.","zh":"未來發展應該是可持續且規劃完善的。"},{"en":"Sustainable means able to continue over time without causing serious harm or shortage.","zh":"sustainable 指能長期持續，而不造成嚴重傷害或短缺。"},{"en":"A sustainable school programme can continue because it has enough teachers, money and student support.","zh":"可持續的學校計劃能持續，因為它有足夠教師、資金和學生支持。"},{"en":"Unsustainable development may look successful at first but create long-term problems later.","zh":"不可持續的發展起初可能看似成功，但之後會造成長遠問題。"},{"en":"This word is used for growth, energy, communities, business and the environment.","zh":"這個詞可用於增長、能源、社區、商業和環境。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":2},{"front":"well-planned","meaning":"規劃完善的","examples":[{"en":"The council argues that new housing development must be well-planned.","zh":"議會認為新房屋發展必須規劃完善。"},{"en":"Well-planned means carefully prepared before action begins.","zh":"well-planned 指在行動開始前經過仔細準備。"},{"en":"A well-planned school trip includes transport, meals, safety rules and emergency contacts.","zh":"規劃完善的學校旅行包括交通、膳食、安全規則和緊急聯絡。"},{"en":"When development is well-planned, fewer problems appear after residents move in.","zh":"當發展規劃完善，居民入住後會出現較少問題。"},{"en":"This phrase contrasts careful preparation with rushed or careless action.","zh":"這個短語把仔細準備與倉促或草率行動作對比。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":2},{"front":"be supported by","meaning":"由……支撐","examples":[{"en":"Housing growth should be supported by adequate infrastructure and services.","zh":"房屋增長應由足夠基建和服務支撐。"},{"en":"To be supported by something means to depend on it for strength, success or proper operation.","zh":"be supported by something 指依靠某物來取得力量、成功或正常運作。"},{"en":"Online learning must be supported by stable internet and clear instructions.","zh":"網上學習必須由穩定網絡和清楚指示支撐。"},{"en":"If new homes are not supported by transport and services, daily life becomes difficult.","zh":"如果新住宅沒有交通和服務支撐，日常生活會變得困難。"},{"en":"This phrase shows what is needed behind a visible development.","zh":"這個短語顯示可見發展背後需要甚麼。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":2},{"front":"adequate infrastructure","meaning":"足夠基建","examples":[{"en":"New development requires adequate infrastructure.","zh":"新發展需要足夠基建。"},{"en":"Adequate infrastructure means enough basic systems such as roads, water, schools, transport and utilities.","zh":"adequate infrastructure 指足夠的基本系統，例如道路、供水、學校、交通和公用設施。"},{"en":"A new housing estate needs adequate infrastructure before many families move in.","zh":"新屋苑在許多家庭入住前需要足夠基建。"},{"en":"Without adequate infrastructure, growth can lead to congestion and poor public services.","zh":"沒有足夠基建，增長可能導致擠塞和公共服務欠佳。"},{"en":"This phrase is central to urban planning and sustainable communities.","zh":"這個短語是城市規劃和可持續社區的核心。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":2},{"front":"community services","meaning":"社區服務","examples":[{"en":"Growth areas need adequate infrastructure and community services.","zh":"增長區需要足夠基建和社區服務。"},{"en":"Community services are local services that support residents’ daily life and wellbeing.","zh":"community services 指支援居民日常生活和福祉的本地服務。"},{"en":"Libraries, clinics, childcare centres and youth clubs are examples of community services.","zh":"圖書館、診所、幼兒中心和青少年中心都是社區服務例子。"},{"en":"If community services do not grow with population, residents may struggle to get help.","zh":"如果社區服務沒有隨人口增長，居民可能難以取得幫助。"},{"en":"This phrase focuses on people’s needs, not only buildings and roads.","zh":"這個短語聚焦人的需要，而不只是建築和道路。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":2},{"front":"recent experience","meaning":"近期經驗","examples":[{"en":"Recent experience in Didcot has revealed problems with large housing developments.","zh":"Didcot 的近期經驗揭示大型房屋發展項目的問題。"},{"en":"Recent experience means what has happened not long ago and what people have learned from it.","zh":"recent experience 指不久前發生的事情，以及人們從中學到的東西。"},{"en":"A school may change its timetable because recent experience shows students are too tired after lunch.","zh":"學校可能因近期經驗顯示學生午飯後太疲倦而改變時間表。"},{"en":"Recent experience can warn planners about problems that statistics alone may not show.","zh":"近期經驗可以提醒規劃者注意單靠統計未必顯示的問題。"},{"en":"This phrase uses past events as evidence for future decisions.","zh":"這個短語用過去事件作未來決策的證據。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":2},{"front":"demonstrate that","meaning":"顯示；證明","examples":[{"en":"Recent experience has demonstrated that greenfield developments cannot fund every requirement.","zh":"近期經驗顯示，綠地發展項目不能資助每項需求。"},{"en":"To demonstrate that something is true means to show it clearly with evidence.","zh":"demonstrate that something is true 指用證據清楚顯示某事是真的。"},{"en":"A failed project can demonstrate that poor communication damages teamwork.","zh":"失敗項目可以證明溝通不良會損害團隊合作。"},{"en":"When evidence demonstrates a problem, decision-makers should adjust their plans.","zh":"當證據顯示存在問題，決策者應調整計劃。"},{"en":"This phrase is formal and stronger than simply say.","zh":"這個短語較正式，比 simply say 更強。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":2},{"front":"greenfield developments","meaning":"綠地發展項目","examples":[{"en":"Large greenfield developments cannot fund all necessary infrastructure.","zh":"大型綠地發展項目不能資助所有必要基建。"},{"en":"Greenfield developments are building projects on land that has not previously been built on.","zh":"greenfield developments 指在從未被發展的土地上進行的建設項目。"},{"en":"A new housing estate on former farmland is a greenfield development.","zh":"在前農地上興建新屋苑就是綠地發展項目。"},{"en":"Greenfield development can provide land for homes, but it may require new roads and services from scratch.","zh":"綠地發展可以提供住宅土地，但可能需要從零開始建道路和服務。"},{"en":"This phrase contrasts with development on already-used urban land.","zh":"這個短語與在已使用城市土地上發展相對。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":2},{"front":"fund all the necessary infrastructure","meaning":"資助所有必要基建","examples":[{"en":"Large developments cannot always fund all the necessary infrastructure.","zh":"大型發展項目不一定能資助所有必要基建。"},{"en":"To fund all the necessary infrastructure means to pay for every basic facility required by a development.","zh":"fund all the necessary infrastructure 指支付發展所需每項基本設施的費用。"},{"en":"Developers may help fund roads, drains and schools for a new housing area.","zh":"發展商可能幫助資助新住宅區的道路、排水系統和學校。"},{"en":"If they cannot fund all the necessary infrastructure, public money may be needed.","zh":"如果他們不能資助所有必要基建，就可能需要公帑。"},{"en":"This phrase highlights the financial burden behind physical growth.","zh":"這個短語突出實體增長背後的財政負擔。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":2},{"front":"low-cost housing requirements","meaning":"低成本房屋要求","examples":[{"en":"Developers may struggle to meet low-cost housing requirements.","zh":"發展商可能難以滿足低成本房屋要求。"},{"en":"Low-cost housing requirements are rules requiring some new homes to be affordable.","zh":"low-cost housing requirements 指要求部分新住宅價格可負擔的規則。"},{"en":"A council may require a new development to include homes for lower-income families.","zh":"議會可能要求新發展項目包括供較低收入家庭居住的住宅。"},{"en":"These requirements can help residents, but they may reduce developers’ funds for other facilities.","zh":"這些要求可以幫助居民，但可能減少發展商用於其他設施的資金。"},{"en":"This phrase is common in planning, housing and development finance.","zh":"這個短語常見於規劃、房屋和發展財務語境。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":2},{"front":"ensuing compromises","meaning":"隨之而來的妥協","examples":[{"en":"The ensuing compromises created long-term local deficits.","zh":"隨之而來的妥協造成長期本地不足。"},{"en":"Ensuing compromises are concessions or weaker decisions that happen as a result of earlier pressure.","zh":"ensuing compromises 指因早前壓力而出現的讓步或較弱決定。"},{"en":"If a school budget is cut, the ensuing compromises may include fewer clubs and larger classes.","zh":"如果學校預算被削減，隨之而來的妥協可能包括較少學會和較大班級。"},{"en":"Compromises can solve an immediate problem but leave hidden costs later.","zh":"妥協可以解決眼前問題，但日後留下隱藏成本。"},{"en":"This phrase suggests that later problems followed from earlier trade-offs.","zh":"這個短語表示後來問題來自早前取捨。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":3},{"front":"create a legacy of","meaning":"留下……的後遺問題","examples":[{"en":"Poor planning can create a legacy of infrastructure deficits.","zh":"規劃不善可能留下基建不足的後遺問題。"},{"en":"To create a legacy of something means to leave behind a long-lasting result, often a negative one.","zh":"create a legacy of something 指留下長期結果，通常是負面結果。"},{"en":"Poor waste management can create a legacy of polluted land for future residents.","zh":"廢物管理不善可能為未來居民留下土地污染的後遺問題。"},{"en":"If today’s decisions are weak, future communities may inherit the problems.","zh":"如果今天的決定薄弱，未來社區可能承受這些問題。"},{"en":"This phrase stresses long-term consequences.","zh":"這個短語強調長遠後果。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":3},{"front":"local transport deficits","meaning":"本地交通不足","examples":[{"en":"The development created local transport deficits.","zh":"這項發展造成本地交通不足。"},{"en":"Local transport deficits are shortages or weaknesses in buses, roads, rail links or crossings in an area.","zh":"local transport deficits 指某地巴士、道路、鐵路連接或交叉口方面的短缺或弱點。"},{"en":"A town may face local transport deficits if new homes are built without extra bus routes.","zh":"如果新住宅沒有配合新增巴士路線，市鎮可能面對本地交通不足。"},{"en":"Transport deficits can make commuting slower and reduce access to jobs or schools.","zh":"交通不足可以令通勤變慢，並減少到達工作或學校的機會。"},{"en":"This phrase points to gaps between travel demand and transport supply.","zh":"這個短語指出交通需求與供應之間的缺口。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":3},{"front":"infrastructure deficits","meaning":"基建不足","examples":[{"en":"Infrastructure deficits can remain after rapid housing growth.","zh":"快速房屋增長後，基建不足可能仍然存在。"},{"en":"Infrastructure deficits are gaps in basic facilities such as roads, schools, utilities and healthcare.","zh":"infrastructure deficits 指道路、學校、公用設施和醫療等基本設施上的缺口。"},{"en":"A fast-growing town may have infrastructure deficits if services are not expanded in time.","zh":"如果服務沒有及時擴展，快速增長的市鎮可能有基建不足。"},{"en":"These deficits can reduce residents’ quality of life and make growth feel poorly managed.","zh":"這些不足可以降低居民生活質素，並令增長感覺管理不善。"},{"en":"This phrase is used when development lacks enough practical support.","zh":"當發展缺乏足夠實際支援時，會使用這個短語。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":3},{"front":"community service deficits","meaning":"社區服務不足","examples":[{"en":"Community service deficits can damage the quality of life in growth areas.","zh":"社區服務不足會損害增長區的生活質素。"},{"en":"Community service deficits are shortages in local services such as clinics, childcare, libraries or social support.","zh":"community service deficits 指診所、幼兒服務、圖書館或社會支援等本地服務短缺。"},{"en":"A new neighbourhood may suffer if families arrive before community services are ready.","zh":"如果家庭在社區服務準備好之前入住，新社區可能受影響。"},{"en":"Service deficits can make residents feel ignored even if new homes look attractive.","zh":"即使新住宅看起來吸引，服務不足也會令居民感到被忽視。"},{"en":"This phrase focuses on social support, not only physical infrastructure.","zh":"這個短語聚焦社會支援，而不只是實體基建。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":3},{"front":"no obvious means of correction","meaning":"沒有明顯的糾正方法","examples":[{"en":"The deficits have no obvious means of correction.","zh":"這些不足沒有明顯的糾正方法。"},{"en":"No obvious means of correction means there is no clear way to fix the problem.","zh":"no obvious means of correction 指沒有清楚方法可以修正問題。"},{"en":"If a school is built in the wrong location, there may be no obvious means of correction later.","zh":"如果學校建在錯誤位置，之後可能沒有明顯的糾正方法。"},{"en":"Problems without clear solutions often become expensive and politically difficult.","zh":"沒有清晰解決方法的問題，往往變得昂貴且政治上困難。"},{"en":"This phrase warns that early mistakes may be hard to repair.","zh":"這個短語警告早期錯誤可能難以修補。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":3},{"front":"wish to ensure that","meaning":"希望確保","examples":[{"en":"The council wishes to ensure that housing growth is properly funded.","zh":"議會希望確保房屋增長得到適當資助。"},{"en":"To wish to ensure that something happens means to want to make certain it happens.","zh":"wish to ensure that something happens 指希望確保某事會發生。"},{"en":"A school may wish to ensure that every student has access to lunch.","zh":"學校可能希望確保每位學生都能吃到午餐。"},{"en":"When leaders wish to ensure success, they must plan resources before problems appear.","zh":"當領導者希望確保成功，他們必須在問題出現前規劃資源。"},{"en":"This phrase is formal and common in official documents.","zh":"這個短語較正式，常見於官方文件。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":3},{"front":"greater recognition of","meaning":"對……有更大認識","examples":[{"en":"The council wants greater recognition of the cost attached to housing growth.","zh":"議會希望人們對房屋增長相關成本有更大認識。"},{"en":"Greater recognition of something means more understanding, acceptance or attention given to it.","zh":"greater recognition of something 指對某事有更多理解、承認或關注。"},{"en":"Teachers may ask for greater recognition of the time needed to prepare good lessons.","zh":"老師可能要求社會更認識準備好課堂所需的時間。"},{"en":"When costs are recognised more clearly, plans are less likely to be underfunded.","zh":"當成本被更清楚認識，計劃較不容易資金不足。"},{"en":"This phrase is useful when a hidden issue needs more public attention.","zh":"當隱藏議題需要更多公共關注時，這個短語很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":3},{"front":"the cost attached to","meaning":"與……相關的成本","examples":[{"en":"There should be greater recognition of the cost attached to housing growth.","zh":"人們應更認識與房屋增長相關的成本。"},{"en":"The cost attached to something is the money, effort or consequence connected with it.","zh":"the cost attached to something 指與某事相關的金錢、努力或後果。"},{"en":"A cheap phone may still have hidden costs attached to repairs and accessories.","zh":"便宜手機仍可能有與維修和配件相關的隱藏成本。"},{"en":"Housing growth brings costs attached to transport, schools and community services.","zh":"房屋增長帶來與交通、學校和社區服務相關的成本。"},{"en":"This phrase reminds readers that benefits often come with responsibilities.","zh":"這個短語提醒讀者，好處往往伴隨責任。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":3},{"front":"a means is found to","meaning":"找到方法去","examples":[{"en":"The council wants a means to be found to fund sustainable communities.","zh":"議會希望找到方法去資助可持續社區。"},{"en":"A means is found to do something means a practical method is discovered or created.","zh":"a means is found to do something 指找到或創造出實際方法去做某事。"},{"en":"A school may hope a means is found to provide free lunches for low-income students.","zh":"學校可能希望找到方法為低收入學生提供免費午餐。"},{"en":"Without a means to pay for services, good plans may remain only ideas.","zh":"如果沒有方法支付服務費用，好計劃可能只停留在想法。"},{"en":"This phrase is formal and focuses on solving a practical problem.","zh":"這個短語較正式，聚焦解決實際問題。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":3},{"front":"fund the establishment of","meaning":"資助……的建立","examples":[{"en":"New funding is needed to fund the establishment of sustainable communities.","zh":"需要新資金來資助可持續社區的建立。"},{"en":"To fund the establishment of something means to pay for creating and setting it up.","zh":"fund the establishment of something 指支付創建和設立某事物的費用。"},{"en":"Donations may fund the establishment of a new community library.","zh":"捐款可能資助新社區圖書館的建立。"},{"en":"Establishing a community requires money for buildings, staff, services and maintenance.","zh":"建立社區需要建築、員工、服務和維修方面的資金。"},{"en":"This phrase connects financial support with the creation of something new.","zh":"這個短語把財政支援與新事物的創建連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":3},{"front":"sustainable communities","meaning":"可持續社區","examples":[{"en":"The council wants to establish sustainable communities in growth areas.","zh":"議會希望在增長區建立可持續社區。"},{"en":"Sustainable communities are places where people can live well over time with proper homes, jobs, services and environment.","zh":"sustainable communities 指人們能在其中長期良好生活，並有適當住宅、工作、服務和環境的地方。"},{"en":"A sustainable community has transport, schools, healthcare, green space and local employment.","zh":"可持續社區有交通、學校、醫療、綠化空間和本地就業。"},{"en":"If these parts are missing, new housing may not become a healthy community.","zh":"如果缺少這些部分，新住宅未必能成為健康社區。"},{"en":"This phrase focuses on long-term quality of life, not just building houses.","zh":"這個短語聚焦長遠生活質素，而不只是建屋。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":4},{"front":"growth areas","meaning":"增長區","examples":[{"en":"Sustainable communities must be properly funded in growth areas.","zh":"在增長區，可持續社區必須得到適當資助。"},{"en":"Growth areas are places selected or expected to expand in population, housing or jobs.","zh":"growth areas 指被選定或預期在人口、房屋或就業方面擴展的地方。"},{"en":"A growth area may need new schools before many families move in.","zh":"增長區可能在許多家庭搬入前需要新學校。"},{"en":"If growth areas lack funding, expansion can create shortages rather than opportunity.","zh":"如果增長區缺乏資金，擴展可能造成短缺，而不是機會。"},{"en":"This phrase is common in planning and regional development.","zh":"這個短語常見於規劃和區域發展。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":4},{"front":"until the 1950s","meaning":"直至 1950 年代","examples":[{"en":"Until the 1950s, Didcot’s expansion was driven by railway and military jobs.","zh":"直至 1950 年代，Didcot 的擴展由鐵路和軍事工作推動。"},{"en":"Until the 1950s means before and up to the period of the 1950s.","zh":"until the 1950s 指在 1950 年代以前並一直到該時期。"},{"en":"Until the 1950s, many families did not own a television.","zh":"直至 1950 年代，許多家庭仍沒有電視。"},{"en":"This phrase marks the end point of an earlier historical pattern.","zh":"這個短語標示較早歷史模式的終點。"},{"en":"It is useful when showing how a place changed after a certain period.","zh":"顯示某地在某時期後如何改變時，這個短語很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":4},{"front":"job opportunities","meaning":"就業機會","examples":[{"en":"Job opportunities in the railway industry encouraged Didcot’s expansion.","zh":"鐵路業的就業機會鼓勵了 Didcot 的擴展。"},{"en":"Job opportunities are chances for people to find paid work.","zh":"job opportunities 指人們找到有薪工作的機會。"},{"en":"A new hospital can create job opportunities for nurses, cleaners and office staff.","zh":"新醫院可以為護士、清潔工和辦公室職員創造就業機會。"},{"en":"When job opportunities increase, more people may move into an area.","zh":"當就業機會增加，更多人可能搬入某地區。"},{"en":"This phrase connects employment with population growth and local development.","zh":"這個短語把就業與人口增長和本地發展連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":4},{"front":"the railway industry","meaning":"鐵路業","examples":[{"en":"The railway industry was important to Didcot’s early expansion.","zh":"鐵路業對 Didcot 早期擴展很重要。"},{"en":"The railway industry includes businesses and workers involved in trains, tracks, stations and rail services.","zh":"the railway industry 指涉及火車、軌道、車站和鐵路服務的企業和工人。"},{"en":"A town with a strong railway industry may attract commuters and transport-related jobs.","zh":"鐵路業強大的市鎮可能吸引通勤者和交通相關工作。"},{"en":"Railways can shape housing because workers often need homes near stations or depots.","zh":"鐵路可以塑造住房，因為工人常需要住在車站或倉庫附近。"},{"en":"This phrase refers to an economic sector connected with rail transport.","zh":"這個短語指與鐵路交通相關的經濟界別。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":4},{"front":"a military ordnance depot","meaning":"軍火庫；軍需品倉庫","examples":[{"en":"A large military ordnance depot helped drive Didcot’s expansion.","zh":"一個大型軍火庫幫助推動 Didcot 的擴展。"},{"en":"A military ordnance depot is a place where weapons, ammunition or military supplies are stored.","zh":"military ordnance depot 指儲存武器、彈藥或軍事物資的地方。"},{"en":"Such a depot can create jobs for guards, drivers, clerks and maintenance workers.","zh":"這類倉庫可以為守衛、司機、文員和維修工人創造工作。"},{"en":"When a depot becomes a major employer, nearby housing may develop for its workers.","zh":"當軍需品倉庫成為主要僱主，附近可能發展住宅供工人居住。"},{"en":"This phrase belongs to military and logistics contexts.","zh":"這個短語屬於軍事和物流語境。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":4},{"front":"the spur to","meaning":"……的推動因素","examples":[{"en":"Railway jobs were the spur to Didcot’s expansion.","zh":"鐵路工作是 Didcot 擴展的推動因素。"},{"en":"The spur to something is the factor that encourages or pushes it to happen.","zh":"the spur to something 指鼓勵或推動某事發生的因素。"},{"en":"A scholarship may be the spur to a student’s decision to study abroad.","zh":"獎學金可能是學生決定出國留學的推動因素。"},{"en":"When jobs appear in a town, they can be the spur to new homes and shops.","zh":"當工作在市鎮出現，它們可以成為新住宅和商店的推動因素。"},{"en":"This phrase highlights the cause behind growth or action.","zh":"這個短語突出增長或行動背後的原因。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":4},{"front":"Didcot’s expansion","meaning":"Didcot 的擴展","examples":[{"en":"Didcot’s expansion was originally linked to railway and depot employment.","zh":"Didcot 的擴展最初與鐵路和倉庫就業有關。"},{"en":"Didcot’s expansion means the growth of the town in size, population or development.","zh":"Didcot’s expansion 指 Didcot 在面積、人口或發展方面的增長。"},{"en":"A town’s expansion often begins when new jobs attract workers and families.","zh":"一個市鎮的擴展常始於新工作吸引工人和家庭。"},{"en":"Expansion can change a place from a small settlement into a larger urban area.","zh":"擴展可以把一個小聚居地變成較大的城市地區。"},{"en":"This phrase refers specifically to how Didcot grew over time.","zh":"這個短語專指 Didcot 隨時間如何增長。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":4},{"front":"be geared to","meaning":"以……為目標；配合","examples":[{"en":"Development was geared to providing homes for local workers.","zh":"發展以為本地工人提供住所為目標。"},{"en":"To be geared to something means to be designed or directed toward that purpose.","zh":"be geared to something 指被設計或導向某個目的。"},{"en":"A beginner course is geared to students who have never studied English before.","zh":"初學者課程是為從未學過英文的學生而設。"},{"en":"If housing is geared to workers, its location and price should match their needs.","zh":"如果住房配合工人需要，其位置和價格應符合他們的需要。"},{"en":"This phrase shows the main aim behind a plan or design.","zh":"這個短語顯示計劃或設計背後的主要目標。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":4},{"front":"provide homes for","meaning":"為……提供住所","examples":[{"en":"The early development provided homes for railway and depot workers.","zh":"早期發展為鐵路和軍需庫工人提供住所。"},{"en":"To provide homes for people means to supply places where they can live.","zh":"provide homes for people 指供應人們可以居住的地方。"},{"en":"A housing project may provide homes for young families who cannot afford private flats.","zh":"房屋項目可能為負擔不起私人單位的年輕家庭提供住所。"},{"en":"Providing homes near workplaces can reduce commuting time and support local employment.","zh":"在工作地點附近提供住所可以減少通勤時間並支援本地就業。"},{"en":"This phrase connects housing supply with people’s needs.","zh":"這個短語把房屋供應與人的需要連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":4},{"front":"depot workers","meaning":"倉庫工人；軍需庫工人","examples":[{"en":"Development was designed to house railway and depot workers.","zh":"發展被設計來安置鐵路和軍需庫工人。"},{"en":"Depot workers are employees who work in a storage, transport or military supply depot.","zh":"depot workers 指在倉庫、運輸站或軍需品倉庫工作的員工。"},{"en":"Depot workers may handle records, goods, vehicles, equipment or security duties.","zh":"倉庫工人可能處理記錄、貨物、車輛、設備或保安工作。"},{"en":"If many depot workers move into a town, housing demand may rise.","zh":"如果許多倉庫工人搬入市鎮，住房需求可能上升。"},{"en":"This phrase identifies workers linked to a particular workplace.","zh":"這個短語指出與特定工作場所相關的工人。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":4},{"front":"limited investment in","meaning":"對……的有限投資","examples":[{"en":"There was limited investment in shopping and other services.","zh":"對購物和其他服務的投資有限。"},{"en":"Limited investment in something means only a small amount of money or resources was put into it.","zh":"limited investment in something 指只有少量金錢或資源投入某事。"},{"en":"A school with limited investment in computers may have too few devices for students.","zh":"對電腦投資有限的學校，可能沒有足夠設備給學生。"},{"en":"Limited investment can slow improvement and leave facilities below local needs.","zh":"有限投資會拖慢改善，並令設施低於本地需要。"},{"en":"This phrase suggests that development was not enough.","zh":"這個短語表示發展不足。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":5},{"front":"the local population","meaning":"本地居民","examples":[{"en":"Services for the local population were limited.","zh":"為本地居民提供的服務有限。"},{"en":"The local population means the people who live in a particular area.","zh":"the local population 指居住在某特定地區的人。"},{"en":"A clinic should plan its opening hours around the needs of the local population.","zh":"診所應根據本地居民需要規劃開放時間。"},{"en":"When the local population grows, demand for shops, schools and transport also rises.","zh":"當本地居民增加，對商店、學校和交通的需求也會上升。"},{"en":"This phrase focuses on residents, not visitors or commuters only.","zh":"這個短語聚焦居民，而不只是訪客或通勤者。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":5},{"front":"fail to develop","meaning":"未能發展","examples":[{"en":"Didcot failed to develop Broadway as a compact town centre.","zh":"Didcot 未能把 Broadway 發展成緊湊的市鎮中心。"},{"en":"To fail to develop something means not to successfully create or improve it as intended.","zh":"fail to develop something 指未能按原意成功創建或改善某事物。"},{"en":"A school may fail to develop a good library if it lacks space and funding.","zh":"如果缺乏空間和資金，學校可能未能發展良好圖書館。"},{"en":"Failure to develop a town centre can leave residents without enough shops and services.","zh":"未能發展市鎮中心，可能令居民沒有足夠商店和服務。"},{"en":"This phrase describes an unrealised plan or missed opportunity.","zh":"這個短語描述未實現的計劃或錯失機會。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":5},{"front":"Broadway","meaning":"Broadway","examples":[{"en":"Broadway was not developed as a compact town centre.","zh":"Broadway 沒有被發展成緊湊的市鎮中心。"},{"en":"Broadway is the name of a main street or area discussed in the passage.","zh":"Broadway 是文章中討論的一條主要街道或地區名稱。"},{"en":"A town’s Broadway may become important if shops and services gather there.","zh":"如果商店和服務集中在那裡，一個市鎮的 Broadway 可能變得重要。"},{"en":"If Broadway lacks a strong layout, it may not function well as a centre.","zh":"如果 Broadway 缺乏良好布局，它可能無法有效作為中心。"},{"en":"In this context, Broadway is a local place name, not the theatre district in New York.","zh":"在這個語境中，Broadway 是本地地名，不是紐約劇院區。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":5},{"front":"a compact town centre","meaning":"緊湊的市鎮中心","examples":[{"en":"Didcot failed to develop a compact town centre.","zh":"Didcot 未能發展出緊湊的市鎮中心。"},{"en":"A compact town centre is a closely arranged central area with shops, services and public facilities near one another.","zh":"compact town centre 指商店、服務和公共設施彼此靠近排列的中心區。"},{"en":"A compact town centre lets residents walk easily between the supermarket, library and bus stop.","zh":"緊湊的市鎮中心讓居民可以輕易步行往返超市、圖書館和巴士站。"},{"en":"If shops are spread out too widely, the centre may feel weak and inconvenient.","zh":"如果商店分散得太廣，中心區可能顯得薄弱而不方便。"},{"en":"This phrase is useful in urban design and planning.","zh":"這個短語適用於城市設計和規劃。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":5},{"front":"achieve only","meaning":"僅形成；只做到","examples":[{"en":"Didcot achieved only a strip of shops along one side of the main street.","zh":"Didcot 僅形成沿主要街道一邊的一排商店。"},{"en":"Achieve only means to reach a limited result that is less than hoped for.","zh":"achieve only 指只達到有限成果，少於原本期望。"},{"en":"A student may achieve only a basic pass if she prepares too late.","zh":"如果學生太遲準備，她可能只做到基本合格。"},{"en":"When investment is limited, a project may achieve only part of its original aim.","zh":"當投資有限，項目可能只達成原本目標的一部分。"},{"en":"This phrase often suggests disappointment or underperformance.","zh":"這個短語常暗示失望或表現不足。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":5},{"front":"a strip of shops","meaning":"一排商店","examples":[{"en":"Broadway had only a strip of shops along one side of the main street.","zh":"Broadway 只有沿主要街道一邊的一排商店。"},{"en":"A strip of shops is a row of shops built along a road or street.","zh":"strip of shops 指沿道路或街道建成的一排商店。"},{"en":"A small neighbourhood may have a strip of shops with a bakery, pharmacy and café.","zh":"小社區可能有一排商店，包括麵包店、藥房和咖啡店。"},{"en":"A strip of shops can serve daily needs, but it may not create a strong town centre.","zh":"一排商店可以滿足日常需要，但未必能形成強大的市鎮中心。"},{"en":"This phrase describes a simple linear shopping layout.","zh":"這個短語描述簡單的線性購物布局。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":5},{"front":"along one side of","meaning":"沿着……的一邊","examples":[{"en":"The shops were located along one side of the main street.","zh":"商店位於主要街道的一邊。"},{"en":"Along one side of something means positioned on only one edge or side of it.","zh":"along one side of something 指只位於某物的一側或邊緣。"},{"en":"Trees were planted along one side of the school playground.","zh":"樹木被種在學校操場的一邊。"},{"en":"If shops are only along one side of a street, the centre may feel less balanced.","zh":"如果商店只沿街道一邊排列，中心區可能感覺較不平衡。"},{"en":"This phrase describes physical location clearly.","zh":"這個短語清楚描述實體位置。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":5},{"front":"the main street","meaning":"主要街道","examples":[{"en":"The shops stood along one side of the main street.","zh":"商店位於主要街道的一邊。"},{"en":"The main street is the principal road in a town, often where shops and services are located.","zh":"main street 指市鎮中的主要道路，通常有商店和服務。"},{"en":"A town’s main street may contain banks, cafés, bus stops and small stores.","zh":"一個市鎮的主要街道可能有銀行、咖啡店、巴士站和小店。"},{"en":"If the main street is poorly designed, local shopping and movement can suffer.","zh":"如果主要街道設計欠佳，本地購物和出行都可能受影響。"},{"en":"This phrase identifies the central or most important street.","zh":"這個短語指出中心或最重要的街道。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":5},{"front":"hemmed in by","meaning":"被……限制；被……包圍","examples":[{"en":"The shops were hemmed in by low-density housing and service trade uses.","zh":"這些商店被低密度住宅和服務業用途限制。"},{"en":"To be hemmed in by something means to be surrounded or restricted by it.","zh":"be hemmed in by something 指被某物包圍或限制。"},{"en":"A small school may be hemmed in by tall buildings and have no space to expand.","zh":"小學校可能被高樓包圍，沒有空間擴展。"},{"en":"When a town centre is hemmed in, future improvement becomes harder.","zh":"當市鎮中心被限制，未來改善會變得更困難。"},{"en":"This phrase suggests physical limitation or lack of room.","zh":"這個短語暗示實體限制或缺乏空間。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":5},{"front":"low-density housing","meaning":"低密度住宅","examples":[{"en":"Low-density housing limited the development of the town centre.","zh":"低密度住宅限制了市鎮中心的發展。"},{"en":"Low-density housing means homes built with fewer dwellings per area, often spread out with more space.","zh":"low-density housing 指每片土地上住宅數量較少、通常較分散且空間較多的住房。"},{"en":"Detached houses with gardens are usually lower-density than apartment blocks.","zh":"有花園的獨立屋通常比公寓大樓密度低。"},{"en":"Low-density housing can feel spacious but may limit shops, transport and town-centre activity.","zh":"低密度住宅可以感覺寬敞，但可能限制商店、交通和市鎮中心活動。"},{"en":"This phrase is common in planning and housing discussions.","zh":"這個短語常見於規劃和房屋討論。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":5},{"front":"service trade uses","meaning":"服務業用途","examples":[{"en":"Service trade uses restricted the layout of Broadway.","zh":"服務業用途限制了 Broadway 的布局。"},{"en":"Service trade uses are land uses related to services such as repairs, storage, vehicle work or small business activities.","zh":"service trade uses 指與維修、儲存、車輛工作或小型商業活動等服務有關的土地用途。"},{"en":"A street with many garages and workshops may have several service trade uses.","zh":"有很多車房和工場的街道可能有多種服務業用途。"},{"en":"These uses can be useful, but they may not create a lively shopping centre.","zh":"這些用途可以有用，但未必能創造熱鬧購物中心。"},{"en":"This phrase belongs to planning and land-use language.","zh":"這個短語屬於規劃和土地用途語言。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":6},{"front":"strategic planning policies","meaning":"策略性規劃政策","examples":[{"en":"Strategic planning policies directed new housing development to Didcot.","zh":"策略性規劃政策把新房屋發展引向 Didcot。"},{"en":"Strategic planning policies are long-term rules or decisions guiding where and how development should happen.","zh":"strategic planning policies 指引導發展應在何處及如何發生的長遠規則或決定。"},{"en":"A region may use strategic planning policies to protect farmland and focus housing near rail stations.","zh":"一個地區可能使用策略性規劃政策保護農地，並把住宅集中在鐵路站附近。"},{"en":"Such policies can shape a town for decades because they direct investment and land use.","zh":"這類政策可以塑造市鎮數十年，因為它們引導投資和土地用途。"},{"en":"This phrase is formal and common in government planning.","zh":"這個短語較正式，常見於政府規劃。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":6},{"front":"direct development to","meaning":"把發展引向……","examples":[{"en":"Planning policies directed significant housing development to Didcot.","zh":"規劃政策把大量房屋發展引向 Didcot。"},{"en":"To direct development to a place means to guide or send new building activity there.","zh":"direct development to a place 指引導或安排新的建設活動到某地。"},{"en":"A council may direct development to areas with strong transport links.","zh":"議會可能把發展引向交通連接強的地區。"},{"en":"Directing development to one town can increase its population and service needs.","zh":"把發展引向一個市鎮，可以增加其人口和服務需求。"},{"en":"This phrase shows how policy shapes the location of growth.","zh":"這個短語顯示政策如何塑造增長地點。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":6},{"front":"significant new housing development","meaning":"大量新房屋發展","examples":[{"en":"Significant new housing development was directed to Didcot from the 1970s.","zh":"自 1970 年代起，大量新房屋發展被引向 Didcot。"},{"en":"Significant new housing development means a large or important amount of new home building.","zh":"significant new housing development 指大量或重要的新住宅建設。"},{"en":"A town may need new schools after significant new housing development.","zh":"市鎮在大量新房屋發展後，可能需要新學校。"},{"en":"Large housing growth can change traffic, shopping patterns and community life.","zh":"大型房屋增長可以改變交通、購物模式和社區生活。"},{"en":"This phrase stresses that the development is important, not minor.","zh":"這個短語強調發展重要，而不是小規模。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":6},{"front":"recognise Didcot’s potential","meaning":"認識到 Didcot 的潛力","examples":[{"en":"Planners recognised Didcot’s potential for growth.","zh":"規劃者認識到 Didcot 的增長潛力。"},{"en":"To recognise Didcot’s potential means to understand that Didcot could develop further.","zh":"recognise Didcot’s potential 指理解 Didcot 可以進一步發展。"},{"en":"A teacher recognises a student’s potential when she sees strong ideas in early drafts.","zh":"老師在學生早期草稿中看見強烈想法時，就認識到學生的潛力。"},{"en":"Recognising potential can lead to investment, planning and higher expectations.","zh":"認識到潛力可以帶來投資、規劃和更高期望。"},{"en":"This phrase shows that planners saw future possibilities in the town.","zh":"這個短語顯示規劃者看見該鎮的未來可能性。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":6},{"front":"rapid growth in","meaning":"……的快速增長","examples":[{"en":"There was rapid growth in local job opportunities.","zh":"本地就業機會出現快速增長。"},{"en":"Rapid growth in something means it increases quickly over a short period.","zh":"rapid growth in something 指某事在短時間內快速增加。"},{"en":"A city may see rapid growth in online delivery jobs after new apps become popular.","zh":"新應用程式流行後，城市可能出現網上外賣工作的快速增長。"},{"en":"Rapid growth can create opportunities, but it may also strain housing and transport.","zh":"快速增長可以創造機會，但也可能令住房和交通受壓。"},{"en":"This phrase highlights speed as well as increase.","zh":"這個短語同時突出速度和增加。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":6},{"front":"local job opportunities","meaning":"本地就業機會","examples":[{"en":"Didcot had rapid growth in local job opportunities.","zh":"Didcot 的本地就業機會快速增長。"},{"en":"Local job opportunities are chances to work within the nearby area.","zh":"local job opportunities 指在附近地區工作的機會。"},{"en":"A new business park can create local job opportunities for residents.","zh":"新商業園可以為居民創造本地就業機會。"},{"en":"When local jobs increase, fewer people may need to travel far for work.","zh":"當本地工作增加，較少人可能需要遠行上班。"},{"en":"This phrase connects employment with community and transport patterns.","zh":"這個短語把就業與社區和交通模式連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":6},{"front":"good rail connections","meaning":"良好的鐵路連接","examples":[{"en":"Didcot had good rail connections for commuters.","zh":"Didcot 為通勤者提供良好的鐵路連接。"},{"en":"Good rail connections mean convenient and reliable train links to other places.","zh":"good rail connections 指方便可靠、通往其他地方的火車連接。"},{"en":"A town with good rail connections may attract people who work in a nearby city.","zh":"有良好鐵路連接的市鎮可能吸引在附近城市工作的人。"},{"en":"Strong rail links can support housing growth because commuting becomes easier.","zh":"強大的鐵路連接可以支援房屋增長，因為通勤變得更容易。"},{"en":"This phrase is often used when discussing transport and regional development.","zh":"討論交通和區域發展時，常用這個短語。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":6},{"front":"work farther afield","meaning":"到較遠地方工作","examples":[{"en":"Some residents chose to work farther afield.","zh":"有些居民選擇到較遠地方工作。"},{"en":"To work farther afield means to work in places farther away from home or the local area.","zh":"work farther afield 指在離家或本地地區較遠的地方工作。"},{"en":"A nurse may live in a small town but work farther afield in a large city hospital.","zh":"護士可能住在小鎮，但到較遠的大城市醫院工作。"},{"en":"Good transport makes it easier for residents to work farther afield.","zh":"良好交通令居民更容易到較遠地方工作。"},{"en":"This phrase often appears when discussing commuting.","zh":"這個短語常出現在通勤討論中。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":6},{"front":"be bisected by","meaning":"被……分成兩部分","examples":[{"en":"The town is bisected by the east-west railway.","zh":"這個市鎮被東西向鐵路分成兩部分。"},{"en":"To be bisected by something means to be divided into two parts by it.","zh":"be bisected by something 指被某物分成兩部分。"},{"en":"A neighbourhood may be bisected by a motorway, making walking across it difficult.","zh":"社區可能被高速公路分成兩部分，使步行穿越變得困難。"},{"en":"When a town is bisected by a railway, communities on each side may feel separated.","zh":"當市鎮被鐵路分割，兩邊社區可能感到分離。"},{"en":"This phrase describes a physical division.","zh":"這個短語描述實體分隔。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":6},{"front":"the east-west railway","meaning":"東西向鐵路","examples":[{"en":"The east-west railway divides the town.","zh":"東西向鐵路把這個市鎮分開。"},{"en":"The east-west railway is a railway line running broadly from east to west.","zh":"east-west railway 指大致從東向西延伸的鐵路線。"},{"en":"An east-west railway can connect towns across a region while also creating a physical barrier.","zh":"東西向鐵路可以連接一個地區內的市鎮，同時也造成實體障礙。"},{"en":"If crossings are limited, a railway line can make parts of a town feel cut off.","zh":"如果過路點有限，鐵路線可以令市鎮部分地區感到隔絕。"},{"en":"This phrase identifies both direction and transport infrastructure.","zh":"這個短語同時指出方向和交通基建。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":6},{"front":"urban extension","meaning":"城市延伸區","examples":[{"en":"Ladygrove is an urban extension to the north of Didcot.","zh":"Ladygrove 是 Didcot 北面的城市延伸區。"},{"en":"An urban extension is a new built-up area added to the edge of an existing town or city.","zh":"urban extension 指在現有市鎮或城市邊緣新增的建成區。"},{"en":"A council may plan an urban extension when the existing town has little room left.","zh":"當現有市鎮剩餘空間有限，議會可能規劃城市延伸區。"},{"en":"Urban extensions need transport links so residents do not feel separate from the main town.","zh":"城市延伸區需要交通連接，居民才不會覺得與主要市鎮分離。"},{"en":"This phrase is common in planning and housing development.","zh":"這個短語常見於規劃和房屋發展。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":7},{"front":"to the north","meaning":"在北面","examples":[{"en":"Ladygrove lies to the north of the town.","zh":"Ladygrove 位於市鎮北面。"},{"en":"To the north means in the direction of north from a place.","zh":"to the north 指在某地方的北方方向。"},{"en":"The new school is to the north of the railway station.","zh":"新學校位於火車站北面。"},{"en":"Location matters because distance and direction affect access to services.","zh":"位置很重要，因為距離和方向會影響使用服務的便利。"},{"en":"This phrase is a simple way to describe geographical position.","zh":"這個短語是描述地理位置的簡單方式。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":7},{"front":"be built since","meaning":"自……以來建成","examples":[{"en":"Ladygrove has been built since the 1980s.","zh":"Ladygrove 自 1980 年代以來建成。"},{"en":"To be built since a time means construction began or has continued from that period onward.","zh":"be built since a time 指建設從某時期開始或自那時起持續。"},{"en":"Many apartment blocks have been built since the new station opened.","zh":"自新車站開放以來，許多公寓大樓已建成。"},{"en":"Development built over several decades can change the identity of a place.","zh":"跨越數十年的建設可以改變一個地方的身份。"},{"en":"This phrase links construction with a starting period.","zh":"這個短語把建設與起始時期連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":7},{"front":"feel cut off from","meaning":"感到與……隔絕","examples":[{"en":"People living in Ladygrove feel cut off from the town.","zh":"住在 Ladygrove 的人感到與市鎮隔絕。"},{"en":"To feel cut off from a place means to feel separated or poorly connected to it.","zh":"feel cut off from a place 指感到與某地分隔或連接不足。"},{"en":"Elderly residents may feel cut off from services if there is no bus route.","zh":"如果沒有巴士路線，長者居民可能感到與服務隔絕。"},{"en":"Physical barriers such as railways can make communities feel socially distant.","zh":"鐵路等實體障礙可以令社區在社交上感到疏離。"},{"en":"This phrase describes both practical and emotional separation.","zh":"這個短語同時描述實際和情感上的分離。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":7},{"front":"the town and its community","meaning":"該市鎮及其社區","examples":[{"en":"Some residents feel cut off from the town and its community.","zh":"有些居民感到與該市鎮及其社區隔絕。"},{"en":"The town and its community means both the physical place and the people who live and interact there.","zh":"the town and its community 指實體地方，以及在那裡生活和互動的人。"},{"en":"A new estate should be connected to the town and its community through roads, schools and local events.","zh":"新屋苑應透過道路、學校和本地活動與市鎮及其社區連接。"},{"en":"Without connection, residents may live nearby but not feel they belong.","zh":"沒有連接，居民可能住得很近卻沒有歸屬感。"},{"en":"This phrase links geography with social belonging.","zh":"這個短語把地理與社會歸屬連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":7},{"front":"population growth","meaning":"人口增長","examples":[{"en":"Population growth in new housing areas did not attract enough investment.","zh":"新住宅區的人口增長沒有吸引足夠投資。"},{"en":"Population growth means an increase in the number of people living in an area.","zh":"population growth 指居住在某地的人數增加。"},{"en":"A town may experience population growth when new homes are built and families move in.","zh":"當新住宅建成並有家庭搬入，市鎮可能經歷人口增長。"},{"en":"Population growth increases demand for schools, transport, healthcare and shops.","zh":"人口增長會增加對學校、交通、醫療和商店的需求。"},{"en":"This phrase is central to planning for services and infrastructure.","zh":"這個短語是服務和基建規劃的核心。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":7},{"front":"new housing areas","meaning":"新住宅區","examples":[{"en":"New housing areas increased Didcot’s population.","zh":"新住宅區增加了 Didcot 的人口。"},{"en":"New housing areas are newly built neighbourhoods mainly containing homes.","zh":"new housing areas 指新建、主要包含住宅的社區。"},{"en":"A new housing area may need parks, bus stops and childcare services.","zh":"新住宅區可能需要公園、巴士站和幼兒服務。"},{"en":"If new housing areas are poorly connected, residents may depend heavily on cars.","zh":"如果新住宅區連接不佳，居民可能高度依賴汽車。"},{"en":"This phrase focuses on residential development.","zh":"這個短語聚焦住宅發展。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":7},{"front":"fail to spark","meaning":"未能激發；未能帶動","examples":[{"en":"Population growth failed to spark adequate private-sector investment.","zh":"人口增長未能帶動足夠的私營界別投資。"},{"en":"To fail to spark something means not to cause or encourage it to happen.","zh":"fail to spark something 指未能引起或促使某事發生。"},{"en":"A school campaign may fail to spark interest if students do not see its purpose.","zh":"如果學生看不到目的，學校活動可能未能激發興趣。"},{"en":"More residents do not automatically spark investment unless businesses expect enough profit.","zh":"更多居民不會自動帶動投資，除非企業預期有足夠利潤。"},{"en":"This phrase shows that an expected reaction did not occur.","zh":"這個短語顯示預期反應沒有發生。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":7},{"front":"adequate private-sector investment","meaning":"足夠的私營界別投資","examples":[{"en":"The town centre did not receive adequate private-sector investment.","zh":"市鎮中心沒有得到足夠的私營界別投資。"},{"en":"Adequate private-sector investment means enough money from businesses or non-government investors.","zh":"adequate private-sector investment 指來自企業或非政府投資者的足夠資金。"},{"en":"A shopping centre may need private-sector investment before new shops open.","zh":"購物中心可能需要私營界別投資，才會有新商店開業。"},{"en":"If private investment is inadequate, public bodies may need to provide support.","zh":"如果私人投資不足，公共機構可能需要提供支援。"},{"en":"This phrase contrasts business funding with public finance.","zh":"這個短語把商業資金與公共資金作對比。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":7},{"front":"town centre uses","meaning":"市鎮中心用途","examples":[{"en":"Didcot needed a wider range of town centre uses.","zh":"Didcot 需要更廣泛的市鎮中心用途。"},{"en":"Town centre uses are activities and facilities normally found in a town centre, such as shops, offices, leisure and services.","zh":"town centre uses 指通常位於市鎮中心的活動和設施，例如商店、辦公室、休閒和服務。"},{"en":"A lively centre may combine cafés, libraries, health services and retail uses.","zh":"熱鬧的中心區可能結合咖啡店、圖書館、醫療服務和零售用途。"},{"en":"A limited range of uses can make a town centre quiet or unattractive.","zh":"用途種類有限可能令市鎮中心安靜或缺乏吸引力。"},{"en":"This phrase is planning language for how central land is used.","zh":"這個短語是描述中心土地如何使用的規劃語言。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":7},{"front":"limited investment","meaning":"有限投資","examples":[{"en":"Limited investment did take place in the early 1980s.","zh":"在 1980 年代初確實有有限投資。"},{"en":"Limited investment means some money was spent, but not enough for full development.","zh":"limited investment 指投入了一些資金，但不足以完成全面發展。"},{"en":"A school may receive limited investment for new books but not for a full library renovation.","zh":"學校可能得到有限投資購買新書，但不足以全面翻新圖書館。"},{"en":"Limited investment can improve part of a problem while leaving larger needs unmet.","zh":"有限投資可以改善問題的一部分，但仍未滿足更大需要。"},{"en":"This phrase suggests that action happened, but on a small scale.","zh":"這個短語表示有行動發生，但規模較小。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":7},{"front":"take place","meaning":"發生；進行","examples":[{"en":"Some investment did take place in Didcot Market Place.","zh":"Didcot Market Place 確實進行了一些投資。"},{"en":"To take place means to happen or occur.","zh":"take place 指發生或進行。"},{"en":"The parent meeting will take place in the school hall on Friday.","zh":"家長會將於星期五在學校禮堂舉行。"},{"en":"When investment takes place, money is actually spent rather than only promised.","zh":"當投資真正發生，金錢就實際被花出，而不只是承諾。"},{"en":"This phrase is neutral and common in formal writing.","zh":"這個短語中性，常見於正式寫作。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":8},{"front":"for instance","meaning":"例如","examples":[{"en":"Didcot Market Place development in 1982, for instance, did not meet all local needs.","zh":"例如，1982 年的 Didcot Market Place 發展項目沒有滿足所有本地需要。"},{"en":"For instance means for example.","zh":"for instance 指例如。"},{"en":"Some services, for instance libraries and clinics, must grow with the population.","zh":"有些服務，例如圖書館和診所，必須隨人口增長。"},{"en":"Writers use for instance to support a general point with a specific case.","zh":"作者使用 for instance，以具體例子支持一般觀點。"},{"en":"This phrase helps readers see exactly what the writer means.","zh":"這個短語幫助讀者清楚看見作者意思。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":8},{"front":"succeed in delivering","meaning":"成功提供","examples":[{"en":"The development did not succeed in delivering the needed facilities.","zh":"這項發展未能成功提供所需設施。"},{"en":"To succeed in delivering something means to successfully provide or achieve it.","zh":"succeed in delivering something 指成功提供或達成某事。"},{"en":"A school project succeeds in delivering results when students actually improve.","zh":"當學生真正進步，學校項目就是成功取得成果。"},{"en":"A development may fail if it builds homes but does not deliver enough services.","zh":"如果發展項目建了住宅卻沒有提供足夠服務，它可能失敗。"},{"en":"This phrase focuses on practical achievement, not just intention.","zh":"這個短語聚焦實際達成，而不只是意圖。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":8},{"front":"the number and range of","meaning":"……的數量和種類","examples":[{"en":"The project failed to provide the number and range of town centre uses needed.","zh":"這項項目未能提供所需市鎮中心用途的數量和種類。"},{"en":"The number and range of something means both how many there are and how varied they are.","zh":"the number and range of something 指某物的數量和多樣性。"},{"en":"A school library needs the number and range of books suitable for different ages.","zh":"學校圖書館需要適合不同年齡的書本數量和種類。"},{"en":"Having many facilities is not enough if they are all the same type.","zh":"設施很多並不足夠，如果它們全都是同一種類。"},{"en":"This phrase stresses quantity and variety together.","zh":"這個短語同時強調數量和多樣性。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":8},{"front":"growing population","meaning":"不斷增長的人口","examples":[{"en":"The facilities were not enough for the growing population.","zh":"這些設施不足以應付不斷增長的人口。"},{"en":"A growing population is a population that is increasing in size.","zh":"growing population 指正在增加的人口。"},{"en":"A growing population may require more school places, doctors and public transport.","zh":"不斷增長的人口可能需要更多學位、醫生和公共交通。"},{"en":"If facilities do not expand, growth can create pressure and frustration.","zh":"如果設施沒有擴展，增長可以造成壓力和不滿。"},{"en":"This phrase is often used in planning and public service discussions.","zh":"這個短語常用於規劃和公共服務討論。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":8},{"front":"public-sector finance","meaning":"公營部門資金","examples":[{"en":"Public-sector finance was used to buy land for the Orchard Centre.","zh":"公營部門資金被用來購買 Orchard Centre 的土地。"},{"en":"Public-sector finance is money provided by government or public bodies.","zh":"public-sector finance 指由政府或公共機構提供的資金。"},{"en":"A council may use public-sector finance to build a road or community hall.","zh":"議會可能使用公營部門資金興建道路或社區會堂。"},{"en":"Public finance is often needed when private investors cannot cover the full cost.","zh":"當私人投資者不能支付全部成本時，往往需要公共資金。"},{"en":"This phrase contrasts government funding with private-sector investment.","zh":"這個短語把政府資金與私營界別投資作對比。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":8},{"front":"be used to buy","meaning":"被用來購買","examples":[{"en":"Public money was used to buy the land required for the development.","zh":"公帑被用來購買該發展所需的土地。"},{"en":"To be used to buy something means money or resources are spent to purchase it.","zh":"be used to buy something 指金錢或資源被花費來購買某物。"},{"en":"School funds may be used to buy computers for a new classroom.","zh":"學校資金可能被用來購買新課室的電腦。"},{"en":"If public money is used to buy land, taxpayers have helped support the project.","zh":"如果公帑被用來購買土地，納稅人就幫助支持了該項目。"},{"en":"This phrase explains the purpose of spending.","zh":"這個短語解釋花費的目的。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":8},{"front":"the land required for","meaning":"……所需的土地","examples":[{"en":"The council bought the land required for the Orchard Centre development.","zh":"議會購買了 Orchard Centre 發展項目所需的土地。"},{"en":"The land required for something is the area of land needed to build or complete it.","zh":"the land required for something 指興建或完成某項目所需要的土地。"},{"en":"A new school project cannot begin until the land required for the classrooms is secured.","zh":"新學校項目要到教室所需土地被取得後才能開始。"},{"en":"If the required land is expensive, development may be delayed.","zh":"如果所需土地昂貴，發展可能延誤。"},{"en":"This phrase links physical space with project planning.","zh":"這個短語把實體空間與項目規劃連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":8},{"front":"Orchard Centre development","meaning":"Orchard Centre 發展項目","examples":[{"en":"The Orchard Centre development included shops, parking and a superstore.","zh":"Orchard Centre 發展項目包括商店、泊車位和大型超級市場。"},{"en":"The Orchard Centre development was a town-centre project involving retail and parking facilities.","zh":"Orchard Centre development 是一個涉及零售和泊車設施的市鎮中心項目。"},{"en":"A development like this can give residents more places to shop and park.","zh":"這類發展可以給居民更多購物和泊車地方。"},{"en":"Town-centre projects may take years if land purchase and funding are complicated.","zh":"如果土地購買和資金安排複雜，市鎮中心項目可能花多年完成。"},{"en":"This phrase names a specific project in Didcot.","zh":"這個短語指 Didcot 的一個特定項目。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":8},{"front":"comprising","meaning":"包括；由……組成","examples":[{"en":"The development comprised a superstore, parking and a new street of stores.","zh":"這項發展包括大型超級市場、泊車位和一條新的商店街。"},{"en":"Comprising means consisting of or including particular parts.","zh":"comprising 指由某些部分組成或包括某些部分。"},{"en":"The new centre comprises a library, café, clinic and study rooms.","zh":"新中心包括圖書館、咖啡店、診所和自修室。"},{"en":"Listing the parts helps readers understand what the project actually contains.","zh":"列出各部分有助讀者理解項目實際包含甚麼。"},{"en":"This word is formal and common in reports.","zh":"這個詞較正式，常見於報告。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":8},{"front":"a superstore","meaning":"大型超級市場","examples":[{"en":"The Orchard Centre development included a superstore.","zh":"Orchard Centre 發展項目包括一間大型超級市場。"},{"en":"A superstore is a very large shop, often selling food, household goods and other products.","zh":"superstore 指非常大型的商店，通常售賣食物、家居用品和其他產品。"},{"en":"A town may attract more shoppers if a superstore opens near the centre.","zh":"如果市鎮中心附近開設大型超級市場，可能吸引更多購物者。"},{"en":"Superstores can increase convenience but may also affect smaller local shops.","zh":"大型超級市場可以增加便利，但也可能影響較小本地商店。"},{"en":"This phrase refers to a large retail facility.","zh":"這個短語指大型零售設施。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":8},{"front":"a new street of stores","meaning":"一條新的商店街","examples":[{"en":"The development included a new street of stores running parallel to Broadway.","zh":"這項發展包括一條與 Broadway 平行的新商店街。"},{"en":"A new street of stores is a newly built row or street containing shops.","zh":"new street of stores 指新建、包含商店的一條街或一排店舖。"},{"en":"A town centre may add a new street of stores to increase shopping choices.","zh":"市鎮中心可能增加一條新的商店街，以增加購物選擇。"},{"en":"More stores can attract visitors, but they need good access and parking.","zh":"更多商店可以吸引訪客，但需要良好交通和泊車配套。"},{"en":"This phrase describes a physical retail layout.","zh":"這個短語描述實體零售布局。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":9},{"front":"run parallel to","meaning":"與……平行","examples":[{"en":"The new street of stores runs parallel to Broadway.","zh":"新商店街與 Broadway 平行。"},{"en":"To run parallel to something means to go in the same direction beside it without crossing it.","zh":"run parallel to something 指在某物旁邊朝相同方向延伸而不相交。"},{"en":"A cycle path may run parallel to a main road.","zh":"單車徑可能與主要道路平行。"},{"en":"Parallel streets can improve movement if they connect to the same town centre.","zh":"如果平行街道連接同一市鎮中心，它們可以改善人流。"},{"en":"This phrase describes physical direction and layout.","zh":"這個短語描述實體方向和布局。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":9},{"front":"take 13 years to complete","meaning":"花了十三年完成","examples":[{"en":"The development took 13 years to complete.","zh":"這項發展花了十三年完成。"},{"en":"To take 13 years to complete means the project required thirteen years before it was finished.","zh":"take 13 years to complete 指項目需要十三年才完成。"},{"en":"A railway project may take many years to complete if land and funding are difficult.","zh":"如果土地和資金問題困難，鐵路項目可能要多年才能完成。"},{"en":"Long completion times can delay benefits for residents and businesses.","zh":"完成時間長會延遲居民和企業得到好處。"},{"en":"This phrase stresses how slow or complex a project was.","zh":"這個短語強調項目緩慢或複雜。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":9},{"front":"oblige developers to","meaning":"要求發展商去","examples":[{"en":"The policy obliged developers to contribute to infrastructure costs.","zh":"這項政策要求發展商為基建成本作出貢獻。"},{"en":"To oblige developers to do something means to require them to do it by rule or agreement.","zh":"oblige developers to do something 指透過規則或協議要求發展商做某事。"},{"en":"A council may oblige developers to build playgrounds in a new estate.","zh":"議會可能要求發展商在新屋苑興建遊樂場。"},{"en":"Obligations help ensure private development pays for some public needs.","zh":"義務有助確保私人發展支付部分公共需要。"},{"en":"This phrase is formal and suggests legal or planning pressure.","zh":"這個短語較正式，帶有法律或規劃壓力。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":9},{"front":"developers of new housing","meaning":"新住宅發展商","examples":[{"en":"Developers of new housing were expected to help fund infrastructure.","zh":"新住宅發展商被期望幫助資助基建。"},{"en":"Developers of new housing are companies or people who build new residential projects.","zh":"developers of new housing 指興建新住宅項目的公司或人士。"},{"en":"A housing developer may buy land, design homes and apply for planning permission.","zh":"住宅發展商可能購買土地、設計住宅並申請規劃許可。"},{"en":"When developers create new demand, councils may ask them to help pay for services.","zh":"當發展商創造新需求，議會可能要求他們幫助支付服務費用。"},{"en":"This phrase identifies the builders responsible for new homes.","zh":"這個短語指出負責新住宅的建設者。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":9},{"front":"contribute to the cost of","meaning":"為……的成本作出貢獻","examples":[{"en":"Developers were asked to contribute to the cost of infrastructure.","zh":"發展商被要求為基建成本作出貢獻。"},{"en":"To contribute to the cost of something means to pay part of the money needed for it.","zh":"contribute to the cost of something 指支付某項所需費用的一部分。"},{"en":"Parents may contribute to the cost of a school trip.","zh":"家長可能為學校旅行費用作出貢獻。"},{"en":"Shared costs make expensive projects easier to fund.","zh":"分擔成本令昂貴項目較容易籌資。"},{"en":"This phrase shows that one party pays only part, not necessarily all, of the cost.","zh":"這個短語顯示一方只支付部分成本，不一定支付全部。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":9},{"front":"infrastructure and service requirements","meaning":"基建及服務需求","examples":[{"en":"New housing creates infrastructure and service requirements.","zh":"新住宅會產生基建及服務需求。"},{"en":"Infrastructure and service requirements are the roads, utilities and community services needed because of development.","zh":"infrastructure and service requirements 指因發展而需要的道路、公用設施和社區服務。"},{"en":"A new estate may create requirements for bus stops, drains, schools and health clinics.","zh":"新屋苑可能產生巴士站、排水系統、學校和診所需求。"},{"en":"Ignoring these requirements can make housing growth unsustainable.","zh":"忽視這些需求會令房屋增長不可持續。"},{"en":"This phrase links new building with the support systems it needs.","zh":"這個短語把新建築與其所需支援系統連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":9},{"front":"raise finance","meaning":"籌集資金","examples":[{"en":"The council hoped that all necessary finance could be raised through developers.","zh":"議會希望所有必要資金都能透過發展商籌集。"},{"en":"To raise finance means to obtain money for a project or purpose.","zh":"raise finance 指為某項目或目的取得資金。"},{"en":"A charity may raise finance through donations, grants and fundraising events.","zh":"慈善機構可能透過捐款、資助和籌款活動籌集資金。"},{"en":"If finance cannot be raised, projects may be delayed or reduced.","zh":"如果未能籌集資金，項目可能延誤或縮小規模。"},{"en":"This phrase focuses on finding money, not spending it.","zh":"這個短語聚焦找錢，而不是花錢。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":9},{"front":"prove unachievable","meaning":"證明無法實現","examples":[{"en":"The idea of raising all the finance from developers proved unachievable.","zh":"從發展商籌集所有資金的想法證明無法實現。"},{"en":"To prove unachievable means to turn out to be impossible to complete or reach.","zh":"prove unachievable 指結果顯示某事不可能完成或達成。"},{"en":"A school may find that building a new hall in three months proves unachievable.","zh":"學校可能發現在三個月內建成新禮堂證明無法實現。"},{"en":"When a target proves unachievable, planners must change the budget, timeline or goal.","zh":"當目標證明無法實現，規劃者必須改變預算、時間表或目標。"},{"en":"This phrase shows that reality defeated an earlier plan.","zh":"這個短語顯示現實打敗了早前計劃。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":9},{"front":"substantial public finance","meaning":"大量公帑；大量公共資金","examples":[{"en":"Substantial public finance was still needed for major projects.","zh":"大型項目仍然需要大量公共資金。"},{"en":"Substantial public finance means a large amount of government or public money.","zh":"substantial public finance 指大量政府或公共資金。"},{"en":"A new hospital may require substantial public finance because private funding is not enough.","zh":"新醫院可能需要大量公共資金，因為私人資金不足。"},{"en":"Major infrastructure often needs public finance because benefits are shared by the whole community.","zh":"大型基建常需要公共資金，因為利益由整個社區共享。"},{"en":"This phrase stresses both size and public source of funding.","zh":"這個短語同時強調資金規模和公共來源。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":9},{"front":"deliver major projects","meaning":"推行大型項目","examples":[{"en":"Public finance was needed to deliver major infrastructure projects.","zh":"需要公共資金來推行大型基建項目。"},{"en":"To deliver major projects means to complete and provide large planned developments successfully.","zh":"deliver major projects 指成功完成並提供大型計劃發展。"},{"en":"A city needs skilled managers to deliver major projects such as bridges or hospitals.","zh":"城市需要熟練管理人員來推行橋樑或醫院等大型項目。"},{"en":"Without funding and coordination, major projects may remain on paper.","zh":"沒有資金和協調，大型項目可能只停留在紙上。"},{"en":"This phrase focuses on turning plans into finished results.","zh":"這個短語聚焦把計劃變成完成成果。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":9},{"front":"a new link road","meaning":"新連接道路","examples":[{"en":"A new link road to the A34 was one of the major projects.","zh":"通往 A34 的新連接道路是其中一個大型項目。"},{"en":"A new link road is a newly built road that connects one route or area to another.","zh":"new link road 指新建、把一條路線或地區連接到另一處的道路。"},{"en":"A town may build a link road to reduce traffic through the centre.","zh":"市鎮可能興建連接道路，以減少中心區交通。"},{"en":"Link roads can improve access but often require major funding and land.","zh":"連接道路可以改善通達性，但通常需要大量資金和土地。"},{"en":"This phrase belongs to transport and infrastructure planning.","zh":"這個短語屬於交通和基建規劃。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":10},{"front":"on the outskirts of","meaning":"在……市郊","examples":[{"en":"The new link road was on the outskirts of the town.","zh":"新連接道路位於市鎮市郊。"},{"en":"On the outskirts of a place means near the outer edge of it.","zh":"on the outskirts of a place 指在某地的外圍邊緣附近。"},{"en":"A large supermarket may be built on the outskirts of a city where land is cheaper.","zh":"大型超級市場可能建在城市市郊，因為土地較便宜。"},{"en":"Outskirts locations can reduce pressure in the centre but may require car access.","zh":"市郊位置可以減少中心區壓力，但可能需要汽車通行。"},{"en":"This phrase describes a place outside or near the edge of a settlement.","zh":"這個短語描述聚居地外圍或邊緣附近的位置。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":10},{"front":"improved railway crossing","meaning":"改善後的鐵路交叉口","examples":[{"en":"An improved railway crossing at Marsh Bridge required public finance.","zh":"Marsh Bridge 改善後的鐵路交叉口需要公共資金。"},{"en":"An improved railway crossing is a safer or more efficient place for people or vehicles to cross a railway.","zh":"improved railway crossing 指更安全或更有效率、供人或車輛穿越鐵路的地點。"},{"en":"A town may improve a railway crossing to reduce delays and accidents.","zh":"市鎮可能改善鐵路交叉口，以減少延誤和意外。"},{"en":"Better crossings can reconnect areas separated by railway lines.","zh":"更好的交叉口可以重新連接被鐵路分隔的地區。"},{"en":"This phrase links transport safety with urban connection.","zh":"這個短語把交通安全與城市連接連繫起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":10},{"front":"Marsh Bridge","meaning":"Marsh Bridge","examples":[{"en":"Marsh Bridge was improved with the help of public finance.","zh":"Marsh Bridge 在公共資金幫助下得到改善。"},{"en":"Marsh Bridge is the name of a specific bridge or crossing mentioned in the passage.","zh":"Marsh Bridge 是文章提到的一座特定橋樑或交叉口名稱。"},{"en":"A named bridge may become important if it connects two divided parts of a town.","zh":"如果一座具名橋樑連接市鎮兩個被分隔部分，它可能變得重要。"},{"en":"Improvements to a bridge can reduce isolation and support local movement.","zh":"改善橋樑可以減少隔絕並支援本地出行。"},{"en":"In this context, Marsh Bridge is a local infrastructure reference.","zh":"在這個語境中，Marsh Bridge 是本地基建參照。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":10},{"front":"be delayed due to","meaning":"因……而延誤","examples":[{"en":"Several projects were delayed due to funding difficulties.","zh":"幾個項目因資金困難而延誤。"},{"en":"To be delayed due to something means to be slowed or postponed because of that cause.","zh":"be delayed due to something 指因某原因而變慢或被推遲。"},{"en":"A school trip may be delayed due to heavy rain.","zh":"學校旅行可能因大雨而延誤。"},{"en":"If funding is uncertain, construction may start later than planned.","zh":"如果資金不確定，工程可能比計劃更遲開始。"},{"en":"This phrase clearly connects delay with its cause.","zh":"這個短語清楚把延誤與原因連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":10},{"front":"difficulties in securing","meaning":"在取得……方面的困難","examples":[{"en":"The projects were delayed because of difficulties in securing public finance.","zh":"這些項目因取得公共資金方面的困難而延誤。"},{"en":"Difficulties in securing something are problems in obtaining or arranging it.","zh":"difficulties in securing something 指取得或安排某物方面的問題。"},{"en":"A charity may face difficulties in securing a venue for a community event.","zh":"慈善機構可能在取得社區活動場地方面遇到困難。"},{"en":"When funding is hard to secure, even necessary projects may wait.","zh":"當資金難以取得，即使必要項目也可能要等待。"},{"en":"This phrase is formal and often used in planning or finance.","zh":"這個短語較正式，常用於規劃或財務語境。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":10},{"front":"secure public finance","meaning":"取得公共資金","examples":[{"en":"The council had difficulty securing public finance for major projects.","zh":"議會難以為大型項目取得公共資金。"},{"en":"To secure public finance means to successfully obtain government or public funding.","zh":"secure public finance 指成功取得政府或公共資金。"},{"en":"A town may secure public finance for a new bus station after presenting a strong case.","zh":"市鎮提出有力理據後，可能為新巴士站取得公共資金。"},{"en":"Securing finance is often necessary before construction can begin.","zh":"在工程開始前，通常必須先取得資金。"},{"en":"This phrase focuses on obtaining funding, not merely requesting it.","zh":"這個短語聚焦取得資金，而不只是提出申請。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":10},{"front":"hold back expansion","meaning":"阻礙擴展","examples":[{"en":"The funding problem held back expansion of health and social services.","zh":"資金問題阻礙了醫療及社會服務的擴展。"},{"en":"To hold back expansion means to slow down or prevent growth from continuing.","zh":"hold back expansion 指拖慢或阻止增長繼續。"},{"en":"A lack of teachers can hold back expansion of after-school programmes.","zh":"缺乏教師可以阻礙課後活動擴展。"},{"en":"When money is missing, services may not expand even if demand rises.","zh":"當資金不足，即使需求上升，服務也可能無法擴展。"},{"en":"This phrase shows that one obstacle limits development.","zh":"這個短語顯示一個障礙限制發展。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":10},{"front":"health and social services","meaning":"醫療及社會服務","examples":[{"en":"Funding problems delayed the expansion of health and social services.","zh":"資金問題延誤了醫療及社會服務的擴展。"},{"en":"Health and social services are services that support people’s medical care, welfare and daily needs.","zh":"health and social services 指支援人們醫療、福利和日常需要的服務。"},{"en":"Clinics, care centres, counselling and support for older people are health and social services.","zh":"診所、護理中心、輔導和長者支援都屬於醫療及社會服務。"},{"en":"Growing towns need these services so residents are not left without help.","zh":"增長中的市鎮需要這些服務，居民才不會得不到幫助。"},{"en":"This phrase focuses on public wellbeing and social support.","zh":"這個短語聚焦公共福祉和社會支援。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":10},{"front":"in recent years","meaning":"近年來","examples":[{"en":"In recent years, government policy has affected housing economics.","zh":"近年來，政府政策影響了房屋發展的經濟因素。"},{"en":"In recent years means during the last few years before the time being discussed.","zh":"in recent years 指在所討論時間之前的最近幾年。"},{"en":"In recent years, many schools have used more online learning tools.","zh":"近年來，許多學校使用更多網上學習工具。"},{"en":"This phrase helps writers show a modern or current trend.","zh":"這個短語幫助作者顯示現代或當前趨勢。"},{"en":"It is useful when comparing recent changes with earlier patterns.","zh":"比較近期變化與早期模式時，它很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":10},{"front":"government policy","meaning":"政府政策","examples":[{"en":"Government policy has changed the economics of housing development.","zh":"政府政策改變了房屋發展的經濟因素。"},{"en":"Government policy means official decisions or rules made by the government.","zh":"government policy 指政府制定的官方決定或規則。"},{"en":"Government policy can affect schools, housing, transport, healthcare and business.","zh":"政府政策可以影響學校、房屋、交通、醫療和商業。"},{"en":"When policy changes, organisations may need to adjust their budgets and plans.","zh":"當政策改變，機構可能需要調整預算和計劃。"},{"en":"This phrase is common in public affairs and planning reports.","zh":"這個短語常見於公共事務和規劃報告。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":10},{"front":"in particular","meaning":"尤其是","examples":[{"en":"In particular, the low-cost housing requirement affected developers’ finances.","zh":"尤其是，低成本房屋要求影響了發展商的財務。"},{"en":"In particular means especially or more specifically.","zh":"in particular 指尤其或更具體地說。"},{"en":"Students should revise grammar, vocabulary and timing; in particular, they should practise weak areas.","zh":"學生應溫習文法、詞彙和時間控制；尤其應練習弱項。"},{"en":"This phrase helps writers move from a general point to a key detail.","zh":"這個短語幫助作者從一般觀點轉到關鍵細節。"},{"en":"It is useful when one factor deserves special attention.","zh":"當某因素值得特別注意時，它很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":11},{"front":"the requirement that","meaning":"……的要求","examples":[{"en":"The requirement that 40 per cent of new units be low-cost homes affected development economics.","zh":"40% 新住宅單位必須是低成本住宅的要求影響了發展經濟因素。"},{"en":"The requirement that something happen is a rule saying that it must happen.","zh":"the requirement that something happen 指規定某事必須發生的規則。"},{"en":"A school may have a requirement that students wear safety glasses in the laboratory.","zh":"學校可能有學生在實驗室必須戴安全眼鏡的要求。"},{"en":"Requirements can protect people, but they may also increase costs.","zh":"要求可以保護人們，但也可能增加成本。"},{"en":"This phrase is formal and often introduces a rule or condition.","zh":"這個短語較正式，常用來引出規則或條件。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":11},{"front":"housing units","meaning":"住宅單位","examples":[{"en":"Forty per cent of the units in a new housing development must be low-cost homes.","zh":"新房屋發展項目中 40% 的單位必須是低成本住宅。"},{"en":"Housing units are individual homes, flats or dwellings within a development.","zh":"housing units 指發展項目中的個別住宅、公寓或居住單位。"},{"en":"A new building may contain fifty housing units for families and single residents.","zh":"新大樓可能包含五十個供家庭和單身居民居住的住宅單位。"},{"en":"Counting housing units helps planners estimate population and service needs.","zh":"計算住宅單位有助規劃者估計人口和服務需求。"},{"en":"This phrase is more technical than simply homes.","zh":"這個短語比 simply homes 更技術性。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":11},{"front":"low-cost homes","meaning":"低成本住宅","examples":[{"en":"A proportion of new housing units must be low-cost homes.","zh":"新住宅單位中某一比例必須是低成本住宅。"},{"en":"Low-cost homes are homes designed to be more affordable for people with lower incomes.","zh":"low-cost homes 指為較低收入人士設計、較可負擔的住宅。"},{"en":"A nurse or shop worker may need low-cost homes near their workplace.","zh":"護士或店員可能需要工作地點附近的低成本住宅。"},{"en":"If low-cost homes are not included, some residents may be priced out of the town.","zh":"如果沒有包括低成本住宅，有些居民可能因價格太高而無法留在市鎮。"},{"en":"This phrase is common in housing policy and planning.","zh":"這個短語常見於房屋政策和規劃。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":11},{"front":"have a major impact on","meaning":"對……有重大影響","examples":[{"en":"The policy has had a major impact on development economics.","zh":"這項政策對發展經濟因素有重大影響。"},{"en":"To have a major impact on something means to affect it strongly.","zh":"have a major impact on something 指強烈影響某事。"},{"en":"A new train station can have a major impact on house prices nearby.","zh":"新火車站可以對附近樓價有重大影響。"},{"en":"Major impacts may change budgets, behaviour and long-term planning.","zh":"重大影響可能改變預算、行為和長遠規劃。"},{"en":"This phrase is useful when the effect is large and important.","zh":"當影響大而重要時，這個短語很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":11},{"front":"the economics of","meaning":"……的經濟因素","examples":[{"en":"The requirement changed the economics of new housing development.","zh":"這項要求改變了新房屋發展的經濟因素。"},{"en":"The economics of something refers to its costs, income, financial incentives and practical affordability.","zh":"the economics of something 指其成本、收入、財務誘因和實際可負擔性。"},{"en":"The economics of running a small café include rent, wages, food costs and customer spending.","zh":"經營小咖啡店的經濟因素包括租金、工資、食材成本和顧客消費。"},{"en":"If costs rise, the economics of a project may no longer work.","zh":"如果成本上升，項目的經濟因素可能不再可行。"},{"en":"This phrase examines whether something makes financial sense.","zh":"這個短語檢視某事在財務上是否合理。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":11},{"front":"limit someone’s contribution to","meaning":"限制某人對……的貢獻","examples":[{"en":"The policy limited developers’ contribution to infrastructure costs.","zh":"這項政策限制了發展商對基建成本的貢獻。"},{"en":"To limit someone’s contribution to something means to reduce or restrict how much they can provide.","zh":"limit someone’s contribution to something 指減少或限制某人能提供的數量。"},{"en":"A tight family budget may limit parents’ contribution to a school trip.","zh":"家庭預算緊張可能限制父母對學校旅行的出資。"},{"en":"If developers’ contributions are limited, public finance may need to cover more.","zh":"如果發展商貢獻受限，公共資金可能需要承擔更多。"},{"en":"This phrase connects restrictions with funding responsibility.","zh":"這個短語把限制與資金責任連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":11},{"front":"developers’ contribution","meaning":"發展商的貢獻","examples":[{"en":"The developers’ contribution to infrastructure costs became more limited.","zh":"發展商對基建成本的貢獻變得更有限。"},{"en":"Developers’ contribution means the money, land or facilities developers provide for public needs.","zh":"developers’ contribution 指發展商為公共需要提供的金錢、土地或設施。"},{"en":"A developer’s contribution may pay for a new junction or playground.","zh":"發展商的貢獻可能支付新路口或遊樂場費用。"},{"en":"When contributions fall, councils may have to delay or fund projects themselves.","zh":"當貢獻減少，議會可能要延遲項目或自行資助。"},{"en":"This phrase is common in planning finance.","zh":"這個短語常見於規劃財務。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":11},{"front":"planning authorities","meaning":"規劃當局","examples":[{"en":"Planning authorities face difficult choices about infrastructure priorities.","zh":"規劃當局面對關於基建優先次序的艱難選擇。"},{"en":"Planning authorities are official bodies responsible for controlling and approving development.","zh":"planning authorities 指負責控制和批准發展的官方機構。"},{"en":"A planning authority may decide whether a housing project can go ahead.","zh":"規劃當局可能決定房屋項目是否可以推行。"},{"en":"These authorities must balance housing demand, environmental protection and public services.","zh":"這些當局必須平衡房屋需求、環境保護和公共服務。"},{"en":"This phrase is formal and used in government and planning contexts.","zh":"這個短語較正式，用於政府和規劃語境。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":11},{"front":"face difficult choices","meaning":"面對艱難選擇","examples":[{"en":"The planning authorities are facing difficult choices.","zh":"規劃當局正面對艱難選擇。"},{"en":"To face difficult choices means to have to decide between options when none is easy.","zh":"face difficult choices 指必須在幾個都不容易的選項之間作決定。"},{"en":"A school may face difficult choices when it has too little money for both books and repairs.","zh":"當學校資金不足以同時購書和維修時，可能面對艱難選擇。"},{"en":"Difficult choices often involve trade-offs between urgent needs and long-term goals.","zh":"艱難選擇常涉及眼前需要與長遠目標之間的取捨。"},{"en":"This phrase shows pressure in decision-making.","zh":"這個短語顯示決策壓力。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":11},{"front":"prioritise the items of infrastructure","meaning":"排定基建項目的優先次序","examples":[{"en":"Authorities must prioritise the items of infrastructure to be funded.","zh":"當局必須排定要資助的基建項目優先次序。"},{"en":"To prioritise infrastructure items means to decide which facilities should be funded first.","zh":"prioritise the items of infrastructure 指決定哪些設施應先獲資助。"},{"en":"A council may prioritise a road crossing before a park if safety is urgent.","zh":"如果安全問題緊急，議會可能先處理道路交叉口，而不是公園。"},{"en":"Prioritising is necessary when money is not enough for every project.","zh":"當資金不足以應付每個項目時，排定優先次序是必要的。"},{"en":"This phrase is useful when resources are limited and choices must be made.","zh":"當資源有限而必須選擇時，這個短語很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":11},{"front":"be funded by development","meaning":"由發展項目資助","examples":[{"en":"Some infrastructure items must be funded by development.","zh":"有些基建項目必須由發展項目資助。"},{"en":"To be funded by development means to be paid for using money from new building projects.","zh":"be funded by development 指使用新建設項目的資金來支付。"},{"en":"A new road may be funded by development if it mainly serves a new housing estate.","zh":"如果新道路主要服務新屋苑，它可能由發展項目資助。"},{"en":"This approach links private building profit with public infrastructure needs.","zh":"這種做法把私人建設利潤與公共基建需要連接起來。"},{"en":"This phrase is common in planning finance.","zh":"這個短語常見於規劃財務。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":12},{"front":"this, in turn, means that","meaning":"這反過來意味着","examples":[{"en":"This, in turn, means that public finance will need to cover more costs.","zh":"這反過來意味着公共資金將需要承擔更多成本。"},{"en":"This, in turn, means that introduces a result that follows from the previous point.","zh":"this, in turn, means that 用來引出由上一點帶來的結果。"},{"en":"The school has more students; this, in turn, means that more teachers are needed.","zh":"學校有更多學生；這反過來意味着需要更多老師。"},{"en":"This phrase helps show a chain of cause and effect.","zh":"這個短語幫助顯示因果鏈。"},{"en":"It is useful in reports when one decision creates another consequence.","zh":"當一個決定造成另一個後果時，它在報告中很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":12},{"front":"from now on","meaning":"從現在起","examples":[{"en":"From now on, public finance will need to provide a greater proportion of costs.","zh":"從現在起，公共資金將需要提供更大比例的成本。"},{"en":"From now on means starting at this point and continuing into the future.","zh":"from now on 指從此刻開始並持續到未來。"},{"en":"From now on, students must submit homework online before midnight.","zh":"從現在起，學生必須在午夜前網上提交功課。"},{"en":"This phrase marks a change in future practice.","zh":"這個短語標示未來做法的改變。"},{"en":"It is useful when a new rule or expectation begins.","zh":"當新規則或期望開始時，它很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":12},{"front":"provide a greater proportion of","meaning":"提供更大比例的……","examples":[{"en":"Public finance will need to provide a greater proportion of infrastructure costs.","zh":"公共資金將需要提供更大比例的基建成本。"},{"en":"To provide a greater proportion of something means to pay or supply a larger share of it.","zh":"provide a greater proportion of something 指支付或提供某物更大的份額。"},{"en":"If parents cannot pay, the school may provide a greater proportion of trip costs.","zh":"如果家長無法支付，學校可能提供更大比例的旅行費用。"},{"en":"A larger public share may be needed when private contributions fall.","zh":"當私人貢獻下降，可能需要更大的公共份額。"},{"en":"This phrase focuses on changing the share of responsibility.","zh":"這個短語聚焦責任份額的改變。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":12},{"front":"infrastructure project costs","meaning":"基建項目成本","examples":[{"en":"Public finance may need to cover more infrastructure project costs.","zh":"公共資金可能需要承擔更多基建項目成本。"},{"en":"Infrastructure project costs are the expenses involved in building roads, crossings, utilities or public facilities.","zh":"infrastructure project costs 指興建道路、交叉口、公用設施或公共設施所涉及的開支。"},{"en":"A bridge project includes costs for design, materials, labour and safety checks.","zh":"橋樑項目包括設計、材料、工人和安全檢查成本。"},{"en":"If these costs rise, councils may need extra funding or a slower timetable.","zh":"如果這些成本上升，議會可能需要額外資金或較慢時間表。"},{"en":"This phrase refers to the financial side of physical development.","zh":"這個短語指實體發展的財務面。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":12},{"front":"Sustainable Communities Plan","meaning":"《可持續社區計劃》","examples":[{"en":"The Government’s Sustainable Communities Plan promotes a holistic approach.","zh":"政府的《可持續社區計劃》推動整體性方法。"},{"en":"The Sustainable Communities Plan is a government plan focused on building communities that can work well over time.","zh":"Sustainable Communities Plan 指一項政府計劃，重點是建立能長期良好運作的社區。"},{"en":"Such a plan may consider housing, jobs, services, environment and transport together.","zh":"這類計劃可能同時考慮房屋、工作、服務、環境和交通。"},{"en":"It matters because houses alone do not create a complete community.","zh":"它很重要，因為單靠房屋不能創造完整社區。"},{"en":"This phrase names a specific policy framework.","zh":"這個短語指一個特定政策框架。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":12},{"front":"seek a holistic approach","meaning":"尋求整體性方法","examples":[{"en":"The plan seeks a holistic approach to new urban development.","zh":"該計劃尋求對新城市發展採取整體性方法。"},{"en":"To seek a holistic approach means to look for a method that considers all connected parts together.","zh":"seek a holistic approach 指尋找一種同時考慮所有相關部分的方法。"},{"en":"A school may seek a holistic approach by supporting grades, mental health and family communication.","zh":"學校可能透過支援成績、心理健康和家庭溝通來尋求整體性方法。"},{"en":"Holistic planning reduces the risk of solving one problem while creating another.","zh":"整體規劃可以減少解決一個問題卻製造另一個問題的風險。"},{"en":"This phrase stresses complete, joined-up thinking.","zh":"這個短語強調完整而連貫的思考。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":12},{"front":"holistic approach","meaning":"整體性方法","examples":[{"en":"A holistic approach considers housing, employment, services and infrastructure together.","zh":"整體性方法同時考慮房屋、就業、服務和基建。"},{"en":"A holistic approach looks at the whole system rather than one part alone.","zh":"holistic approach 指看整個系統，而不是只看單一部分。"},{"en":"A doctor takes a holistic approach when considering sleep, diet, stress and symptoms together.","zh":"醫生同時考慮睡眠、飲食、壓力和症狀時，就是採取整體性方法。"},{"en":"In town planning, this approach helps connect homes with jobs and services.","zh":"在市鎮規劃中，這種方法幫助把住宅與工作和服務連接起來。"},{"en":"This phrase contrasts with narrow or single-issue thinking.","zh":"這個短語與狹窄或單一議題思維相對。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":12},{"front":"new urban development","meaning":"新城市發展","examples":[{"en":"The plan aims to improve new urban development.","zh":"該計劃旨在改善新城市發展。"},{"en":"New urban development means newly planned building and growth in towns or cities.","zh":"new urban development 指市鎮或城市中新規劃的建設和增長。"},{"en":"A new urban development may include homes, shops, public transport and green space.","zh":"新城市發展可能包括住宅、商店、公共交通和綠化空間。"},{"en":"If urban development is badly planned, traffic and service shortages may follow.","zh":"如果城市發展規劃不善，可能隨之出現交通和服務短缺。"},{"en":"This phrase is used in planning, housing and infrastructure discussions.","zh":"這個短語用於規劃、房屋和基建討論。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":12},{"front":"housing, employment, services and infrastructure","meaning":"房屋、就業、服務及基建","examples":[{"en":"Sustainable development must include housing, employment, services and infrastructure.","zh":"可持續發展必須包括房屋、就業、服務及基建。"},{"en":"Housing, employment, services and infrastructure are key parts of a functioning community.","zh":"housing, employment, services and infrastructure 是一個正常運作社區的關鍵部分。"},{"en":"A new town needs homes, jobs, schools, clinics, roads and utilities to work well.","zh":"新市鎮需要住宅、工作、學校、診所、道路和公用設施，才能良好運作。"},{"en":"If one part is missing, residents may have houses but still lack a good quality of life.","zh":"如果缺少其中一部分，居民可能有房子，但仍缺乏良好生活質素。"},{"en":"This phrase shows the main ingredients of sustainable urban growth.","zh":"這個短語顯示可持續城市增長的主要元素。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":12},{"front":"infrastructure of all kinds","meaning":"各類基建","examples":[{"en":"The plan covers infrastructure of all kinds.","zh":"該計劃涵蓋各類基建。"},{"en":"Infrastructure of all kinds means many different types of basic facilities and systems.","zh":"infrastructure of all kinds 指許多不同類型的基本設施和系統。"},{"en":"Roads, schools, drainage, public transport and healthcare buildings are infrastructure of all kinds.","zh":"道路、學校、排水、公共交通和醫療建築都屬於各類基建。"},{"en":"Considering many types prevents planners from focusing only on roads or houses.","zh":"考慮多種類型可以防止規劃者只聚焦道路或房屋。"},{"en":"This phrase stresses broad coverage.","zh":"這個短語強調涵蓋範圍廣。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":12},{"front":"be carefully planned and delivered","meaning":"被仔細規劃並提供","examples":[{"en":"Services and infrastructure should be carefully planned and delivered.","zh":"服務和基建應被仔細規劃並提供。"},{"en":"To be carefully planned and delivered means to be prepared thoughtfully and then provided successfully.","zh":"be carefully planned and delivered 指被周詳準備，然後成功提供。"},{"en":"A new clinic should be carefully planned and delivered so it opens before residents need it urgently.","zh":"新診所應仔細規劃並提供，使其在居民迫切需要前開放。"},{"en":"Poor delivery can ruin a good plan if services arrive too late.","zh":"如果服務太遲到位，執行不善可以破壞好計劃。"},{"en":"This phrase combines design with actual completion.","zh":"這個短語結合設計與實際完成。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":13},{"front":"avoid infrastructure deficits","meaning":"避免基建不足","examples":[{"en":"The plan aims to avoid infrastructure deficits.","zh":"該計劃旨在避免基建不足。"},{"en":"To avoid infrastructure deficits means to prevent shortages in roads, schools, transport and other basic facilities.","zh":"avoid infrastructure deficits 指防止道路、學校、交通和其他基本設施短缺。"},{"en":"A council can avoid deficits by planning services before new residents arrive.","zh":"議會可以在新居民到來前規劃服務，以避免不足。"},{"en":"If deficits are avoided, growth feels smoother and more acceptable to residents.","zh":"如果避免了不足，增長會讓居民感覺更順暢、更可接受。"},{"en":"This phrase focuses on prevention rather than repair.","zh":"這個短語聚焦預防，而不是修補。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":13},{"front":"occur in places like","meaning":"在像……這樣的地方出現","examples":[{"en":"Infrastructure deficits have occurred in places like Didcot.","zh":"基建不足曾在像 Didcot 這樣的地方出現。"},{"en":"To occur in places like somewhere means to happen in similar places or examples.","zh":"occur in places like somewhere 指在類似地方或例子中發生。"},{"en":"Traffic problems can occur in places like fast-growing suburbs.","zh":"交通問題可能在快速增長的郊區這類地方出現。"},{"en":"Mentioning places like Didcot helps readers connect a general issue to a real case.","zh":"提到像 Didcot 這樣的地方，幫助讀者把一般問題連接到真實個案。"},{"en":"This phrase is useful when giving examples of a wider pattern.","zh":"舉出更大模式的例子時，這個短語很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":13},{"front":"in the past","meaning":"在過去","examples":[{"en":"Didcot experienced infrastructure deficits in the past.","zh":"Didcot 在過去曾經歷基建不足。"},{"en":"In the past means during an earlier time, not now or not necessarily now.","zh":"in the past 指在較早時間，不是現在或不一定是現在。"},{"en":"In the past, many students carried heavy printed dictionaries to school.","zh":"在過去，許多學生帶着沉重的印刷字典上學。"},{"en":"Past experience can guide future decisions if people learn from mistakes.","zh":"如果人們從錯誤中學習，過去經驗可以指導未來決策。"},{"en":"This phrase is useful when comparing earlier and later situations.","zh":"比較早期和後期情況時，這個短語很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":13},{"front":"be structured around","meaning":"圍繞……組織","examples":[{"en":"The report is structured around the components of a sustainable community.","zh":"這份報告圍繞可持續社區的組成部分組織。"},{"en":"To be structured around something means to be organised according to that central idea or set of parts.","zh":"be structured around something 指根據某個核心想法或一組部分來組織。"},{"en":"A lesson may be structured around three skills: reading, speaking and writing.","zh":"課堂可以圍繞三項技能組織：閱讀、說話和寫作。"},{"en":"Clear structure helps readers follow a long report without getting lost.","zh":"清晰結構幫助讀者跟上長報告而不迷失。"},{"en":"This phrase describes organisation, not content alone.","zh":"這個短語描述組織方式，而不只是內容。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":13},{"front":"individual components","meaning":"個別組成部分","examples":[{"en":"The report discusses individual components of a sustainable community.","zh":"報告討論可持續社區的個別組成部分。"},{"en":"Individual components are separate parts that together form a whole system.","zh":"individual components 指共同組成整體系統的獨立部分。"},{"en":"In a school plan, individual components may include teaching, counselling, facilities and parent communication.","zh":"在學校計劃中，個別組成部分可能包括教學、輔導、設施和家長溝通。"},{"en":"Looking at each component helps planners see which part is weak.","zh":"查看每個組成部分有助規劃者看見哪部分較弱。"},{"en":"This phrase is useful when analysing complex systems piece by piece.","zh":"逐部分分析複雜系統時，這個短語很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":13},{"front":"baseline position","meaning":"基準情況","examples":[{"en":"The report shows the baseline position for each component.","zh":"報告顯示每個組成部分的基準情況。"},{"en":"A baseline position is the starting situation used for comparison later.","zh":"baseline position 指之後用作比較的起始情況。"},{"en":"A teacher records students’ baseline position before a course to measure progress afterwards.","zh":"老師在課程前記錄學生的基準情況，以便之後衡量進步。"},{"en":"Without a baseline, it is hard to know whether improvement has happened.","zh":"沒有基準，就難以知道是否有改善。"},{"en":"This phrase is common in reports, evaluation and planning.","zh":"這個短語常見於報告、評估和規劃。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":13},{"front":"be identified as","meaning":"被識別為；被列為","examples":[{"en":"Didcot has been identified as one of the towns in the government programme.","zh":"Didcot 已被列為政府計劃中的市鎮之一。"},{"en":"To be identified as something means to be officially recognised or selected as it.","zh":"be identified as something 指被官方認定或選定為某事物。"},{"en":"A school may be identified as needing extra support after an inspection.","zh":"學校在視察後可能被列為需要額外支援。"},{"en":"Once a town is identified for a programme, further study and funding may follow.","zh":"一旦市鎮被列入計劃，可能會有進一步研究和資金跟進。"},{"en":"This phrase is formal and often used in official reports.","zh":"這個短語較正式，常見於官方報告。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":13},{"front":"work to evaluate whether","meaning":"致力評估是否","examples":[{"en":"The Government is working to evaluate whether extra growth will help the town.","zh":"政府正致力評估額外增長是否會幫助該市鎮。"},{"en":"To work to evaluate whether something is true means to actively study and judge it.","zh":"work to evaluate whether something is true 指積極研究並判斷某事是否成立。"},{"en":"A school may work to evaluate whether smaller classes improve exam results.","zh":"學校可能致力評估小班教學是否改善考試成績。"},{"en":"Evaluation helps decision-makers avoid relying only on hopes or assumptions.","zh":"評估幫助決策者避免只依賴希望或假設。"},{"en":"This phrase connects ongoing work with careful judgement.","zh":"這個短語把進行中的工作與仔細判斷連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":13},{"front":"additional growth","meaning":"額外增長","examples":[{"en":"Additional growth may strengthen Didcot’s economic potential.","zh":"額外增長可能加強 Didcot 的經濟潛力。"},{"en":"Additional growth means extra expansion beyond what already exists or was planned.","zh":"additional growth 指在現有或已計劃之外的額外擴展。"},{"en":"A shop may need more staff if additional growth brings more customers.","zh":"如果額外增長帶來更多顧客，商店可能需要更多員工。"},{"en":"Extra growth can help an area, but only if infrastructure and services can cope.","zh":"額外增長可以幫助地區，但前提是基建和服務能承受。"},{"en":"This phrase is similar to further growth but often appears in planning targets.","zh":"這個短語與 further growth 相近，但常出現在規劃目標中。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":13},{"front":"strengthen the economic potential","meaning":"加強經濟潛力","examples":[{"en":"The programme will examine whether growth can strengthen the town’s economic potential.","zh":"該計劃將檢視增長能否加強該市鎮的經濟潛力。"},{"en":"To strengthen economic potential means to improve the ability of a place to create jobs, income and business activity.","zh":"strengthen economic potential 指改善某地創造工作、收入和商業活動的能力。"},{"en":"Better transport can strengthen a town’s economic potential by attracting employers.","zh":"更好的交通可以透過吸引僱主來加強市鎮經濟潛力。"},{"en":"If growth is supported by services, it may make the local economy stronger.","zh":"如果增長得到服務支撐，它可能令本地經濟更強。"},{"en":"This phrase links development with future economic opportunity.","zh":"這個短語把發展與未來經濟機會連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":13},{"front":"deliver the necessary infrastructure","meaning":"提供必要基建","examples":[{"en":"The plan must deliver the necessary infrastructure.","zh":"該計劃必須提供必要基建。"},{"en":"To deliver the necessary infrastructure means to provide the basic facilities required for a development to work.","zh":"deliver the necessary infrastructure 指提供發展正常運作所需的基本設施。"},{"en":"A new community must deliver the necessary infrastructure before residents face shortages.","zh":"新社區必須在居民面對短缺前提供必要基建。"},{"en":"If infrastructure is not delivered on time, growth may feel like a burden.","zh":"如果基建未能按時提供，增長可能感覺像負擔。"},{"en":"This phrase focuses on practical completion, not just planning.","zh":"這個短語聚焦實際完成，而不只是規劃。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":14},{"front":"improve environmental standards","meaning":"改善環境標準","examples":[{"en":"The programme aims to improve environmental standards.","zh":"該計劃旨在改善環境標準。"},{"en":"To improve environmental standards means to make conditions such as air quality, green space or sustainability better.","zh":"improve environmental standards 指改善空氣質素、綠化空間或可持續性等條件。"},{"en":"A town may improve environmental standards by planting trees and reducing traffic pollution.","zh":"市鎮可以透過種樹和減少交通污染來改善環境標準。"},{"en":"Better standards can make growth healthier and more acceptable to residents.","zh":"更好的標準可以令增長更健康，也更易被居民接受。"},{"en":"This phrase connects development with environmental quality.","zh":"這個短語把發展與環境質素連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":14},{"front":"a programme of work","meaning":"工作計劃","examples":[{"en":"A programme of work will be undertaken over the coming months.","zh":"一項工作計劃將在未來數月開展。"},{"en":"A programme of work is a planned set of tasks or activities carried out over time.","zh":"programme of work 指隨時間進行的一套已規劃任務或活動。"},{"en":"A council may create a programme of work to consult residents and prepare a master plan.","zh":"議會可能制定工作計劃，以諮詢居民並準備總體規劃。"},{"en":"Breaking work into a programme helps people know what will happen and when.","zh":"把工作分成計劃有助人們知道會發生甚麼以及何時發生。"},{"en":"This phrase is formal and common in reports.","zh":"這個短語較正式，常見於報告。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":14},{"front":"discussions with","meaning":"與……的討論","examples":[{"en":"The programme will include discussions with the local community.","zh":"該計劃將包括與本地社區的討論。"},{"en":"Discussions with someone are conversations held to exchange views, concerns or ideas.","zh":"discussions with someone 指與某人交談，以交換看法、憂慮或想法。"},{"en":"A school may hold discussions with parents before changing the timetable.","zh":"學校在改變時間表前可能與家長討論。"},{"en":"Discussions help decision-makers understand needs that may not appear in statistics.","zh":"討論幫助決策者理解統計未必顯示的需要。"},{"en":"This phrase suggests consultation rather than one-way announcement.","zh":"這個短語暗示諮詢，而不是單向宣布。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":14},{"front":"the local community","meaning":"本地社區","examples":[{"en":"The local community will be consulted about their aspirations.","zh":"本地社區將就他們的期望被諮詢。"},{"en":"The local community means the people who live, work or participate in a particular area.","zh":"local community 指在某特定地區生活、工作或參與的人。"},{"en":"A council should listen to the local community before changing a town centre.","zh":"議會在改變市鎮中心前應聆聽本地社區。"},{"en":"Community views can reveal worries about traffic, housing, safety and identity.","zh":"社區意見可以揭示對交通、房屋、安全和身份的憂慮。"},{"en":"This phrase focuses on residents and local stakeholders.","zh":"這個短語聚焦居民和本地持份者。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":14},{"front":"aspirations for","meaning":"對……的期望","examples":[{"en":"Residents will discuss their aspirations for the town.","zh":"居民將討論他們對該市鎮的期望。"},{"en":"Aspirations for something are hopes, ambitions or desired improvements for it.","zh":"aspirations for something 指對某事的希望、抱負或期望改善。"},{"en":"Students may discuss their aspirations for university, work and family life.","zh":"學生可能討論他們對大學、工作和家庭生活的期望。"},{"en":"A town plan should consider residents’ aspirations, not only technical data.","zh":"市鎮規劃應考慮居民期望，而不只是技術數據。"},{"en":"This phrase is useful when discussing future hopes.","zh":"討論未來希望時，這個短語很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":14},{"front":"stakeholders","meaning":"持份者","examples":[{"en":"Other stakeholders will also be consulted.","zh":"其他持份者也會被諮詢。"},{"en":"Stakeholders are people or organisations affected by a decision or able to influence it.","zh":"stakeholders 指受某決定影響或能影響該決定的人或組織。"},{"en":"In a school project, stakeholders may include students, parents, teachers and neighbours.","zh":"在學校項目中，持份者可能包括學生、家長、老師和鄰居。"},{"en":"Consulting stakeholders can reduce conflict because more voices are heard early.","zh":"諮詢持份者可以減少衝突，因為更多聲音較早被聽見。"},{"en":"This phrase is common in planning, business and policy.","zh":"這個短語常見於規劃、商業和政策。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":14},{"front":"be undertaken","meaning":"被進行；被開展","examples":[{"en":"The programme of work will be undertaken over the coming months.","zh":"這項工作計劃將在未來數月被開展。"},{"en":"To be undertaken means to be carried out or started formally.","zh":"be undertaken 指被正式進行或開始。"},{"en":"A safety review may be undertaken after an accident.","zh":"意外發生後，可能會進行安全檢討。"},{"en":"When work is undertaken officially, people expect clear steps and responsibility.","zh":"當工作被正式開展，人們會期望有清楚步驟和責任。"},{"en":"This phrase is formal and common in reports.","zh":"這個短語較正式，常見於報告。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":14},{"front":"over the coming months","meaning":"在未來數月","examples":[{"en":"Consultations will take place over the coming months.","zh":"諮詢將在未來數月進行。"},{"en":"Over the coming months means during the next several months.","zh":"over the coming months 指在接下來幾個月內。"},{"en":"The school will introduce new reading activities over the coming months.","zh":"學校將在未來數月引入新的閱讀活動。"},{"en":"This phrase gives a future time frame without naming exact dates.","zh":"這個短語提供未來時間框架，但不列明確切日期。"},{"en":"It is useful in plans, announcements and reports.","zh":"它適用於計劃、公告和報告。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":14},{"front":"lead to the development of","meaning":"促成……的制定","examples":[{"en":"The work will lead to the development of a strategic master plan.","zh":"這項工作將促成策略性總體規劃的制定。"},{"en":"To lead to the development of something means to result in its creation.","zh":"lead to the development of something 指導致某事物被創造或制定。"},{"en":"Parent feedback may lead to the development of a new homework policy.","zh":"家長回饋可能促成新功課政策的制定。"},{"en":"Early consultation can lead to better plans because problems are noticed sooner.","zh":"早期諮詢可以促成更好計劃，因為問題更早被注意到。"},{"en":"This phrase connects one stage of work with a later outcome.","zh":"這個短語把一個工作階段與後來成果連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":14},{"front":"strategic master plan","meaning":"策略性總體規劃","examples":[{"en":"The discussions will lead to a strategic master plan for the town.","zh":"這些討論將促成該市鎮的策略性總體規劃。"},{"en":"A strategic master plan is a long-term overall plan guiding future development.","zh":"strategic master plan 指引導未來發展的長遠整體計劃。"},{"en":"A town’s master plan may cover housing, transport, jobs, parks and services.","zh":"市鎮總體規劃可能涵蓋房屋、交通、就業、公園和服務。"},{"en":"A strong master plan helps different projects fit together instead of developing separately.","zh":"有力的總體規劃幫助不同項目互相配合，而不是各自發展。"},{"en":"This phrase is formal and common in urban planning.","zh":"這個短語較正式，常見於城市規劃。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":14},{"front":"the challenge will be in","meaning":"挑戰在於","examples":[{"en":"The challenge will be in optimising scarce resources.","zh":"挑戰在於優化稀缺資源。"},{"en":"The challenge will be in means the difficult part will involve a particular task.","zh":"the challenge will be in 指困難部分將涉及某項特定任務。"},{"en":"In a school event, the challenge will be in managing many students safely.","zh":"在學校活動中，挑戰在於安全管理大量學生。"},{"en":"This phrase points readers to the hardest part of a future plan.","zh":"這個短語把讀者注意力引向未來計劃最困難的部分。"},{"en":"It is useful when success depends on solving one key problem.","zh":"當成功取決於解決一個關鍵問題時，它很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":15},{"front":"optimise scarce resources","meaning":"優化稀缺資源","examples":[{"en":"The council must optimise scarce resources to achieve maximum benefits.","zh":"議會必須優化稀缺資源，以取得最大效益。"},{"en":"To optimise scarce resources means to use limited money, land, time or staff in the most effective way.","zh":"optimise scarce resources 指以最有效方式使用有限金錢、土地、時間或人手。"},{"en":"A school optimises scarce resources when it shares one classroom for several useful activities.","zh":"學校把同一課室用於幾種有用活動時，就是在優化稀缺資源。"},{"en":"If resources are scarce, poor choices can waste opportunities and delay benefits.","zh":"如果資源稀缺，錯誤選擇會浪費機會並延誤好處。"},{"en":"This phrase is useful in planning, budgeting and management.","zh":"這個短語適用於規劃、預算和管理。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":15},{"front":"scarce resources","meaning":"稀缺資源","examples":[{"en":"Scarce resources must be used carefully.","zh":"稀缺資源必須小心使用。"},{"en":"Scarce resources are resources that are limited and not enough for every need.","zh":"scarce resources 指有限且不足以滿足每項需要的資源。"},{"en":"A family with scarce resources must choose carefully between rent, food and transport.","zh":"資源稀缺的家庭必須在租金、食物和交通之間小心選擇。"},{"en":"Scarcity makes prioritising necessary because not everything can be funded.","zh":"稀缺性令排定優先次序變得必要，因為不是所有事情都能獲資助。"},{"en":"This phrase can refer to money, land, time, staff or materials.","zh":"這個短語可以指金錢、土地、時間、人手或材料。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":15},{"front":"achieve maximum benefits","meaning":"取得最大效益","examples":[{"en":"The aim is to achieve maximum benefits for the town.","zh":"目標是為該市鎮取得最大效益。"},{"en":"To achieve maximum benefits means to gain the greatest possible positive results.","zh":"achieve maximum benefits 指取得最大可能的正面成果。"},{"en":"A school may arrange resources carefully to achieve maximum benefits for students.","zh":"學校可能仔細安排資源，以為學生取得最大效益。"},{"en":"Maximum benefits are more likely when limited resources are used in the right places.","zh":"當有限資源用在正確地方，就更可能取得最大效益。"},{"en":"This phrase focuses on making choices as effective as possible.","zh":"這個短語聚焦令選擇盡可能有效。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":15},{"front":"land that has never previously been built on","meaning":"從未被發展的土地","examples":[{"en":"Greenfield land is land that has never previously been built on.","zh":"綠地是從未被發展的土地。"},{"en":"Land that has never previously been built on is undeveloped land without earlier buildings.","zh":"land that has never previously been built on 指沒有早前建築的未發展土地。"},{"en":"Farmland outside a town may be land that has never previously been built on.","zh":"市鎮外的農地可能是從未被發展的土地。"},{"en":"Building on such land can be easier, but it may reduce countryside or wildlife space.","zh":"在這類土地上建設可能較容易，但可能減少郊野或野生動物空間。"},{"en":"This phrase explains the meaning of greenfield land.","zh":"這個短語解釋 greenfield land 的意思。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":15},{"front":"reading passage","meaning":"閱讀篇章","examples":[{"en":"Reading Passage 2 has nine paragraphs.","zh":"閱讀篇章 2 有九段。"},{"en":"A reading passage is a text used for reading practice or examination questions.","zh":"reading passage 指用於閱讀練習或考試題目的文本。"},{"en":"Students should skim a reading passage first to understand its topic and structure.","zh":"學生應先略讀閱讀篇章，以理解主題和結構。"},{"en":"Careful reading helps students answer questions based on evidence, not guesses.","zh":"仔細閱讀幫助學生根據證據回答問題，而不是猜測。"},{"en":"This phrase is common in IELTS-style reading tasks.","zh":"這個短語常見於 IELTS 類閱讀題。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":15},{"front":"contain the following information","meaning":"包含以下資料","examples":[{"en":"Students identify which paragraph contains the following information.","zh":"學生辨認哪一段包含以下資料。"},{"en":"To contain the following information means to include the listed details or ideas.","zh":"contain the following information 指包含列出的細節或想法。"},{"en":"In a reading test, students scan paragraphs to find where each detail appears.","zh":"在閱讀測驗中，學生掃讀段落，找出每項細節出現的位置。"},{"en":"This task checks whether students can match meaning, not just identical words.","zh":"這項任務檢查學生是否能配對意思，而不只是相同字眼。"},{"en":"This phrase is common in paragraph-matching questions.","zh":"這個短語常見於段落配對題。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":15},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Students write the correct letter in the answer box.","zh":"學生在答案格中寫上正確字母。"},{"en":"To write the correct letter means to put the answer option’s letter in the required space.","zh":"write the correct letter 指把答案選項的字母寫在指定位置。"},{"en":"In a matching task, students may write A, B or C rather than a full sentence.","zh":"在配對題中，學生可能寫 A、B 或 C，而不是完整句子。"},{"en":"A correct idea may lose marks if the wrong letter is written.","zh":"即使意思正確，寫錯字母也可能失分。"},{"en":"This phrase reminds students to follow the exam format exactly.","zh":"這個短語提醒學生嚴格按照考試格式作答。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":15},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Answers should be written on the answer sheet.","zh":"答案應寫在答題紙上。"},{"en":"On your answer sheet means in the official place where exam answers must be recorded.","zh":"on your answer sheet 指在考試答案必須記錄的正式位置。"},{"en":"A correct answer in the question booklet may not count if it is not on your answer sheet.","zh":"如果正確答案只寫在題目冊上，而沒有寫在答題紙上，可能不會計分。"},{"en":"Students should check that each answer is written beside the correct number.","zh":"學生應檢查每個答案是否寫在正確題號旁邊。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":15},{"front":"a reference to","meaning":"提及……","examples":[{"en":"The question asks for a reference to the way the report is organised.","zh":"題目要求找出提及報告組織方式的地方。"},{"en":"A reference to something is a mention of it.","zh":"reference to something 指提到某事。"},{"en":"A reading question may ask for a reference to a problem, person or future plan.","zh":"閱讀題可能要求找出提及問題、人物或未來計劃的地方。"},{"en":"Finding references requires scanning for meaning, not only exact words.","zh":"找提及之處需要掃讀意思，而不只是找完全相同字眼。"},{"en":"This phrase is common in locating-information questions.","zh":"這個短語常見於定位資訊題。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":15},{"front":"the way the report is organised","meaning":"報告的組織方式","examples":[{"en":"The passage explains the way the council’s report is organised.","zh":"文章解釋議會報告的組織方式。"},{"en":"The way the report is organised means how its sections, topics and ideas are arranged.","zh":"the way the report is organised 指報告的部分、主題和想法如何排列。"},{"en":"A report may be organised by problem, cause, solution or future action.","zh":"報告可以按問題、原因、解決方法或未來行動組織。"},{"en":"Understanding organisation helps readers find information faster.","zh":"理解組織方式幫助讀者更快找到資訊。"},{"en":"This phrase focuses on structure rather than individual facts.","zh":"這個短語聚焦結構，而不是個別事實。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":15},{"front":"the reason why","meaning":"……的原因","examples":[{"en":"The task asks for the reason why some inhabitants are isolated.","zh":"這項任務要求找出有些居民感到孤立的原因。"},{"en":"The reason why means the cause or explanation for something.","zh":"the reason why 指某事的原因或解釋。"},{"en":"A teacher may ask the reason why a student keeps arriving late.","zh":"老師可能詢問學生經常遲到的原因。"},{"en":"Finding the reason helps readers move beyond description to explanation.","zh":"找出原因幫助讀者從描述進一步走向解釋。"},{"en":"This phrase is used when a question asks for cause.","zh":"當問題要求原因時，會使用這個短語。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":16},{"front":"inhabitants","meaning":"居民","examples":[{"en":"Inhabitants in one part of Didcot feel isolated from the town.","zh":"Didcot 某部分的居民感到與市鎮隔絕。"},{"en":"Inhabitants are people who live in a particular place.","zh":"inhabitants 指住在某個地方的人。"},{"en":"The inhabitants of a village may share a school, market and bus route.","zh":"村莊居民可能共用一間學校、市場和巴士路線。"},{"en":"When services are far away, inhabitants may feel neglected by planners.","zh":"當服務很遠，居民可能覺得被規劃者忽視。"},{"en":"This word is more formal than residents.","zh":"這個詞比 residents 更正式。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":16},{"front":"be isolated","meaning":"被隔離；感到孤立","examples":[{"en":"Some inhabitants are isolated by the railway line.","zh":"有些居民被鐵路線隔離。"},{"en":"To be isolated means to be separated from others physically or socially.","zh":"be isolated 指在實體或社交上與他人分離。"},{"en":"Elderly people may be isolated if there is no public transport near their homes.","zh":"如果家附近沒有公共交通，長者可能感到孤立。"},{"en":"Isolation can reduce access to shops, friends, services and community life.","zh":"孤立可以減少使用商店、朋友、服務和社區生活的機會。"},{"en":"This phrase can describe both physical separation and loneliness.","zh":"這個短語可以描述實體分隔，也可以描述孤獨。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":16},{"front":"a statement concerning","meaning":"關於……的陳述","examples":[{"en":"The task asks for a statement concerning future sources of investment.","zh":"這項任務要求找出關於未來投資來源的陳述。"},{"en":"A statement concerning something is a sentence or claim about that topic.","zh":"statement concerning something 指關於某主題的一句話或主張。"},{"en":"A reading question may ask for a statement concerning transport, funding or housing.","zh":"閱讀題可能要求找出關於交通、資金或房屋的陳述。"},{"en":"Students should locate the part that discusses the topic, not simply a repeated word.","zh":"學生應定位討論該主題的部分，而不只是找重複字眼。"},{"en":"This phrase is formal and common in exam instructions.","zh":"這個短語較正式，常見於考試指示。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":16},{"front":"future sources of investment","meaning":"未來投資來源","examples":[{"en":"The passage discusses future sources of investment for infrastructure.","zh":"文章討論基建的未來投資來源。"},{"en":"Future sources of investment are the places or organisations that may provide money later.","zh":"future sources of investment 指日後可能提供資金的地方或組織。"},{"en":"A town may look to government, developers and businesses as future sources of investment.","zh":"市鎮可能把政府、發展商和企業視為未來投資來源。"},{"en":"Identifying future sources helps planners decide whether projects are affordable.","zh":"找出未來投資來源幫助規劃者判斷項目是否可負擔。"},{"en":"This phrase focuses on where money will come from.","zh":"這個短語聚焦資金將來自哪裡。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":16},{"front":"the identification of","meaning":"對……的指出；識別","examples":[{"en":"The question asks for the identification of two major employers in Didcot.","zh":"題目要求指出 Didcot 的兩個主要僱主。"},{"en":"The identification of something means naming or recognising it correctly.","zh":"identification of something 指正確說出或認出某事物。"},{"en":"A reading task may require the identification of the cause of a problem.","zh":"閱讀任務可能要求識別問題的原因。"},{"en":"Accurate identification prevents students from choosing a similar but wrong detail.","zh":"準確識別可以防止學生選擇相似但錯誤的細節。"},{"en":"This phrase is formal and common in academic or exam language.","zh":"這個短語較正式，常見於學術或考試語言。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":16},{"front":"major employers","meaning":"主要僱主","examples":[{"en":"The railway industry and the ordnance depot were major employers.","zh":"鐵路業和軍需品倉庫是主要僱主。"},{"en":"Major employers are organisations or industries that provide many jobs in an area.","zh":"major employers 指在某地提供大量工作的組織或行業。"},{"en":"A hospital can be a major employer in a small town.","zh":"醫院可以是小鎮的主要僱主。"},{"en":"When major employers expand, local housing and services may also need to grow.","zh":"當主要僱主擴展，本地住房和服務也可能需要增長。"},{"en":"This phrase connects employment with local economic development.","zh":"這個短語把就業與本地經濟發展連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":16},{"front":"be consulted about","meaning":"就……被諮詢","examples":[{"en":"Groups will be consulted about a new development plan.","zh":"各群體將就新發展計劃被諮詢。"},{"en":"To be consulted about something means to be asked for views before a decision is made.","zh":"be consulted about something 指在決定作出前被詢問意見。"},{"en":"Parents may be consulted about changes to school lunch arrangements.","zh":"家長可能就學校午餐安排變動被諮詢。"},{"en":"Consultation can reduce opposition because people feel heard.","zh":"諮詢可以減少反對，因為人們感到被聆聽。"},{"en":"This phrase shows participation in decision-making.","zh":"這個短語顯示參與決策。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":16},{"front":"a new development plan","meaning":"新發展計劃","examples":[{"en":"The council will consult stakeholders about a new development plan.","zh":"議會將就新發展計劃諮詢持份者。"},{"en":"A new development plan is a fresh proposal for how an area should grow or change.","zh":"new development plan 指關於某地應如何增長或改變的新方案。"},{"en":"A town’s new development plan may include housing, shops, transport and green space.","zh":"市鎮的新發展計劃可能包括房屋、商店、交通和綠化空間。"},{"en":"A plan affects residents because it shapes future services and neighbourhoods.","zh":"計劃會影響居民，因為它塑造未來服務和社區。"},{"en":"This phrase belongs to planning and local government.","zh":"這個短語屬於規劃和地方政府語境。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":16},{"front":"an account of how","meaning":"關於……如何發生的描述","examples":[{"en":"The paragraph gives an account of how town-centre facilities were funded.","zh":"該段描述市鎮中心設施如何獲得資助。"},{"en":"An account of how something happened is a description or explanation of the process.","zh":"account of how something happened 指對某事如何發生的描述或解釋。"},{"en":"A report may give an account of how a school raised money for a library.","zh":"報告可能描述學校如何為圖書館籌款。"},{"en":"Such an account helps readers understand the steps behind an outcome.","zh":"這種描述幫助讀者理解結果背後的步驟。"},{"en":"This phrase is common in reading questions and report summaries.","zh":"這個短語常見於閱讀題和報告摘要。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":16},{"front":"additional town-centre facilities","meaning":"額外市鎮中心設施","examples":[{"en":"The Orchard Centre provided additional town-centre facilities.","zh":"Orchard Centre 提供了額外市鎮中心設施。"},{"en":"Additional town-centre facilities are extra shops, parking, services or public spaces in the centre of a town.","zh":"additional town-centre facilities 指市鎮中心額外的商店、泊車位、服務或公共空間。"},{"en":"A new library and supermarket can provide additional town-centre facilities for residents.","zh":"新圖書館和超級市場可以為居民提供額外市鎮中心設施。"},{"en":"Extra facilities can make a town centre more useful and attractive.","zh":"額外設施可以令市鎮中心更有用、更吸引。"},{"en":"This phrase focuses on improvements to the central area.","zh":"這個短語聚焦中心區改善。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":16},{"front":"be previously funded","meaning":"早前由……資助","examples":[{"en":"Some town-centre facilities were previously funded through public-sector finance.","zh":"有些市鎮中心設施早前由公營部門資金資助。"},{"en":"To be previously funded means to have received money earlier or in the past.","zh":"be previously funded 指早前或過去已獲得資金。"},{"en":"A sports hall may have been previously funded by a government grant.","zh":"體育館可能早前由政府補助資助。"},{"en":"Knowing how projects were previously funded helps planners decide future funding sources.","zh":"知道項目過去如何被資助，有助規劃者決定未來資金來源。"},{"en":"This phrase links past finance with current discussion.","zh":"這個短語把過去資金與當前討論連接起來。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":17},{"front":"look at the following places","meaning":"查看以下地點","examples":[{"en":"Students look at the following places and match them with statements.","zh":"學生查看以下地點，並把它們與陳述配對。"},{"en":"Look at the following places means read the listed place names carefully.","zh":"look at the following places 指仔細閱讀列出的地名。"},{"en":"In a matching task, students should underline each place before searching the passage.","zh":"在配對題中，學生應先在每個地名下畫線，再搜尋文章。"},{"en":"Careful reading prevents students from confusing similar locations.","zh":"仔細閱讀可以防止學生混淆相似地點。"},{"en":"This phrase is an instruction in reading exercises.","zh":"這個短語是閱讀練習中的指示。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":17},{"front":"list of statements","meaning":"陳述列表","examples":[{"en":"The question provides a list of statements.","zh":"題目提供一個陳述列表。"},{"en":"A list of statements is a set of sentences or claims given as answer options.","zh":"list of statements 指作為答案選項的一組句子或主張。"},{"en":"Students may compare each statement with the passage before choosing an answer.","zh":"學生選答案前，可以把每項陳述與文章比較。"},{"en":"Lists help organise options, but they can include distractors.","zh":"列表有助整理選項，但也可能包含干擾項。"},{"en":"This phrase is common in matching and multiple-choice tasks.","zh":"這個短語常見於配對題和選擇題。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":17},{"front":"match each place with","meaning":"把每個地點與……配對","examples":[{"en":"Students match each place with the correct statement.","zh":"學生把每個地點與正確陳述配對。"},{"en":"To match each place with something means to connect every place to the option that fits it.","zh":"match each place with something 指把每個地點連接到合適選項。"},{"en":"A geography worksheet may ask students to match each city with its main industry.","zh":"地理工作紙可能要求學生把每個城市與其主要產業配對。"},{"en":"Matching requires evidence from the passage, not guessing from general knowledge.","zh":"配對需要文章證據，而不是靠常識猜測。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":17},{"front":"the correct statement","meaning":"正確陳述","examples":[{"en":"Each place must be matched with the correct statement.","zh":"每個地點必須與正確陳述配對。"},{"en":"The correct statement is the option that accurately matches the information in the passage.","zh":"correct statement 指準確符合文章資料的選項。"},{"en":"In a reading test, students should choose the correct statement only after checking the text.","zh":"在閱讀測驗中，學生應查閱文本後才選正確陳述。"},{"en":"A statement may sound reasonable but still be wrong if the passage does not support it.","zh":"陳述即使聽起來合理，如果文章不支持，仍可能是錯的。"},{"en":"This phrase focuses on accuracy.","zh":"這個短語聚焦準確性。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":17},{"front":"provide extra facilities","meaning":"提供額外設施","examples":[{"en":"A development can provide extra facilities for shopping and cars.","zh":"發展項目可以為購物及汽車提供額外設施。"},{"en":"To provide extra facilities means to add more useful buildings, services or spaces.","zh":"provide extra facilities 指增加更多有用建築、服務或空間。"},{"en":"A school may provide extra facilities such as study rooms and sports areas.","zh":"學校可能提供額外設施，例如自修室和運動區。"},{"en":"Extra facilities can make an area more convenient for residents and visitors.","zh":"額外設施可以令地區對居民和訪客更方便。"},{"en":"This phrase focuses on added practical support.","zh":"這個短語聚焦新增實際支援。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":17},{"front":"shopping and cars","meaning":"購物及汽車","examples":[{"en":"The facilities were connected with shopping and cars.","zh":"這些設施與購物及汽車有關。"},{"en":"Shopping and cars refers to retail activity and vehicle access or parking.","zh":"shopping and cars 指零售活動以及車輛通行或泊車。"},{"en":"A retail park is often designed around shopping and cars rather than walking.","zh":"零售園區通常圍繞購物及汽車設計，而不是步行。"},{"en":"If a town centre focuses too much on cars, pedestrians may feel less comfortable.","zh":"如果市鎮中心太注重汽車，行人可能感到較不舒服。"},{"en":"This phrase combines consumer use with transport needs.","zh":"這個短語結合消費用途與交通需要。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":17},{"front":"take a long time to agree","meaning":"花很長時間達成共識","examples":[{"en":"A location can take a long time to agree.","zh":"一個地點可能花很長時間才能達成共識。"},{"en":"To take a long time to agree means that people need many discussions before reaching a decision.","zh":"take a long time to agree 指人們需要多次討論才能作出決定。"},{"en":"A school may take a long time to agree on a new uniform because parents have different views.","zh":"學校可能因家長看法不同，花很長時間才就新校服達成共識。"},{"en":"Projects can be delayed when land, design or funding decisions take years to settle.","zh":"當土地、設計或資金決定多年未定，項目可能延誤。"},{"en":"This phrase shows slow decision-making.","zh":"這個短語顯示決策緩慢。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":17},{"front":"its layout was unsuitable","meaning":"其布局並不合適","examples":[{"en":"The option says that the layout was unsuitable.","zh":"這個選項說其布局並不合適。"},{"en":"Its layout was unsuitable means its physical arrangement did not fit the intended purpose.","zh":"its layout was unsuitable 指其實體安排不符合原定用途。"},{"en":"A classroom layout may be unsuitable if students cannot see the board.","zh":"如果學生看不到黑板，課室布局可能不合適。"},{"en":"Poor layout can reduce convenience, safety and efficient movement.","zh":"差劣布局會降低便利性、安全性和移動效率。"},{"en":"This phrase judges the design or arrangement of a place.","zh":"這個短語評價某地的設計或排列。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":17},{"front":"construction was held up","meaning":"工程被拖延","examples":[{"en":"Construction was held up because of funding problems.","zh":"工程因資金問題被拖延。"},{"en":"Construction was held up means building work was delayed or slowed.","zh":"construction was held up 指建築工程被延誤或放慢。"},{"en":"A new school building may be held up if materials arrive late.","zh":"如果材料遲到，新校舍工程可能被拖延。"},{"en":"Delayed construction can increase costs and frustrate residents waiting for facilities.","zh":"工程延誤會增加成本，並令等待設施的居民不滿。"},{"en":"This phrase is informal but common in reporting delays.","zh":"這個短語較口語，但常用於報道延誤。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":17},{"front":"because of funding problems","meaning":"由於資金問題","examples":[{"en":"Some projects were delayed because of funding problems.","zh":"有些項目由於資金問題而延誤。"},{"en":"Because of funding problems means due to difficulties in obtaining enough money.","zh":"because of funding problems 指由於取得足夠金錢方面有困難。"},{"en":"A sports centre may open late because of funding problems.","zh":"體育中心可能由於資金問題而延遲開放。"},{"en":"Funding problems can force planners to reduce, postpone or cancel work.","zh":"資金問題可能迫使規劃者縮減、推遲或取消工作。"},{"en":"This phrase clearly gives the cause of delay or failure.","zh":"這個短語清楚說明延誤或失敗的原因。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":17},{"front":"privately funded","meaning":"由私人資金資助","examples":[{"en":"A project may be privately funded.","zh":"項目可能由私人資金資助。"},{"en":"Privately funded means paid for by businesses, individuals or private organisations rather than government.","zh":"privately funded 指由企業、個人或私人機構，而不是政府支付費用。"},{"en":"A private company may build a gym that is privately funded.","zh":"私人公司可能興建一個由私人資金資助的健身室。"},{"en":"Privately funded projects may move faster if investors expect profit.","zh":"如果投資者預期有利潤，私人資助項目可能推進較快。"},{"en":"This phrase contrasts private money with public finance.","zh":"這個短語把私人資金與公共資金作對比。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":18},{"front":"initially fail to","meaning":"起初未能","examples":[{"en":"A project may initially fail to receive approval.","zh":"項目可能起初未能獲得批准。"},{"en":"To initially fail to do something means to be unsuccessful at first.","zh":"initially fail to do something 指一開始未能成功做到某事。"},{"en":"A student may initially fail to understand a difficult grammar rule.","zh":"學生可能起初未能理解困難文法規則。"},{"en":"Initial failure does not mean final failure if changes are made.","zh":"起初失敗不代表最終失敗，只要作出改變。"},{"en":"This phrase focuses on the first stage of an attempt.","zh":"這個短語聚焦嘗試的第一階段。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":18},{"front":"receive council approval","meaning":"獲得議會批准","examples":[{"en":"A development may need to receive council approval.","zh":"發展項目可能需要獲得議會批准。"},{"en":"To receive council approval means to get official permission from the local council.","zh":"receive council approval 指取得地方議會的官方許可。"},{"en":"A builder may need to receive council approval before adding new flats.","zh":"建築商在加建新單位前，可能需要獲得議會批准。"},{"en":"Without approval, construction may be stopped or delayed.","zh":"沒有批准，工程可能被停止或延誤。"},{"en":"This phrase is common in planning and building contexts.","zh":"這個短語常見於規劃和建築語境。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":18},{"front":"complete the sentences below","meaning":"完成以下句子","examples":[{"en":"Students complete the sentences below using words from the passage.","zh":"學生使用文章中的詞語完成以下句子。"},{"en":"Complete the sentences below means fill in the missing words in the given sentences.","zh":"complete the sentences below 指填入所給句子中的缺失詞語。"},{"en":"In a reading test, students complete sentences by finding exact words in the text.","zh":"在閱讀測驗中，學生透過在文本中找出確切詞語來完成句子。"},{"en":"This task checks grammar, meaning and careful locating skills.","zh":"這項任務檢查文法、意思和仔細定位能力。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":18},{"front":"no more than three words","meaning":"不多於三個字","examples":[{"en":"Students must choose no more than three words from the passage.","zh":"學生必須從文章中選擇不多於三個字。"},{"en":"No more than three words means one, two or three words, but not four or more.","zh":"no more than three words 指一個、兩個或三個字，但不是四個或更多。"},{"en":"If the answer is low-cost homes, it follows the rule of no more than three words.","zh":"如果答案是 low-cost homes，就符合不多於三個字的規則。"},{"en":"Writing too many words can lose marks even if the idea is correct.","zh":"即使意思正確，寫太多字也可能失分。"},{"en":"This phrase controls answer length in reading tests.","zh":"這個短語控制閱讀測驗中的答案長度。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":18},{"front":"from the passage","meaning":"從篇章中選取","examples":[{"en":"The answers must be chosen from the passage.","zh":"答案必須從篇章中選取。"},{"en":"From the passage means taken directly from the reading text.","zh":"from the passage 指直接取自閱讀文本。"},{"en":"In IELTS reading, students should copy the answer from the passage when instructed.","zh":"在 IELTS 閱讀中，當題目要求時，學生應從文章中抄寫答案。"},{"en":"Using outside knowledge may lead to wrong answers even if it seems logical.","zh":"使用外部知識即使看似合理，也可能導致錯誤答案。"},{"en":"This phrase reminds students to use textual evidence.","zh":"這個短語提醒學生使用文本證據。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":18},{"front":"a certain proportion of","meaning":"某一比例的……","examples":[{"en":"A certain proportion of houses in new developments must be low-cost homes.","zh":"新發展項目中某一比例的房屋必須是低成本住宅。"},{"en":"A certain proportion of something means a particular share or percentage of it.","zh":"a certain proportion of something 指某物的特定份額或百分比。"},{"en":"A school may reserve a certain proportion of seats for local students.","zh":"學校可能保留某一比例的學位給本地學生。"},{"en":"Setting a proportion helps ensure one group or purpose is included.","zh":"設定比例有助確保某群體或目的被包括在內。"},{"en":"This phrase is useful when discussing percentages, quotas or shares.","zh":"討論百分比、配額或份額時，這個短語很有用。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":18},{"front":"of the low-cost type","meaning":"低成本類型的","examples":[{"en":"Some houses in any new development must be of the low-cost type.","zh":"任何新發展項目中的一些房屋必須是低成本類型的。"},{"en":"Of the low-cost type means belonging to the category of affordable or lower-priced homes.","zh":"of the low-cost type 指屬於可負擔或較低價格住宅類別。"},{"en":"A council may require some flats to be of the low-cost type for lower-income residents.","zh":"議會可能要求部分單位屬於低成本類型，以供較低收入居民入住。"},{"en":"This requirement can make housing more mixed and accessible.","zh":"這項要求可以令住房更混合、更容易負擔。"},{"en":"This phrase classifies homes by cost category.","zh":"這個短語按成本類別分類住宅。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":18},{"front":"be keen to ensure that","meaning":"熱切希望確保","examples":[{"en":"The government is keen to ensure that adequate infrastructure is provided.","zh":"政府熱切希望確保提供足夠基建。"},{"en":"To be keen to ensure that something happens means to strongly want to make certain it happens.","zh":"be keen to ensure that something happens 指強烈希望確保某事發生。"},{"en":"A headteacher may be keen to ensure that every child feels safe at school.","zh":"校長可能熱切希望確保每個孩子在學校感到安全。"},{"en":"Strong concern often leads to clearer rules, checks and planning.","zh":"強烈關注常帶來更清楚規則、檢查和規劃。"},{"en":"This phrase is formal but shows active concern.","zh":"這個短語較正式，但顯示積極關注。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":18},{"front":"adequate infrastructure will be provided","meaning":"將提供足夠基建","examples":[{"en":"The government wants adequate infrastructure to be provided for future developments.","zh":"政府希望未來發展項目將提供足夠基建。"},{"en":"Adequate infrastructure will be provided means enough basic facilities will be supplied.","zh":"adequate infrastructure will be provided 指將供應足夠基本設施。"},{"en":"Residents expect roads, schools and clinics to be provided when a new estate is built.","zh":"當新屋苑建成，居民期望會提供道路、學校和診所。"},{"en":"If infrastructure is provided early, new communities can function more smoothly.","zh":"如果基建及早提供，新社區可以更順暢運作。"},{"en":"This phrase expresses a future planning aim.","zh":"這個短語表達未來規劃目標。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":18},{"front":"future housing developments","meaning":"未來房屋發展項目","examples":[{"en":"Future housing developments should be supported by proper infrastructure.","zh":"未來房屋發展項目應由適當基建支撐。"},{"en":"Future housing developments are new residential projects planned for later years.","zh":"future housing developments 指計劃在未來年份興建的新住宅項目。"},{"en":"A council may plan future housing developments near rail stations to reduce car use.","zh":"議會可能把未來房屋發展項目規劃在鐵路站附近，以減少汽車使用。"},{"en":"These developments need services from the beginning, not only after problems appear.","zh":"這些發展從一開始就需要服務，而不是等問題出現後才補救。"},{"en":"This phrase refers to housing projects that have not yet been built.","zh":"這個短語指尚未建成的房屋項目。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":18},{"front":"the views of","meaning":"……的意見","examples":[{"en":"The views of Didcot’s inhabitants will help shape the plan.","zh":"Didcot 居民的意見將幫助塑造該計劃。"},{"en":"The views of people are their opinions, concerns or hopes about a topic.","zh":"the views of people 指人們對某主題的意見、憂慮或希望。"},{"en":"A school may ask for the views of parents before changing its homework policy.","zh":"學校在改變功課政策前，可能詢問家長的意見。"},{"en":"Listening to views can reveal problems that officials might miss.","zh":"聆聽意見可以揭示官員可能忽略的問題。"},{"en":"This phrase is common in consultation and decision-making.","zh":"這個短語常見於諮詢和決策。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":19},{"front":"form the basis of","meaning":"構成……的基礎","examples":[{"en":"The views of residents and stakeholders will form the basis of a strategic plan.","zh":"居民和持份者的意見將構成策略性計劃的基礎。"},{"en":"To form the basis of something means to become the main foundation for it.","zh":"form the basis of something 指成為某事物的主要基礎。"},{"en":"Student feedback can form the basis of changes to a course.","zh":"學生回饋可以構成課程改動的基礎。"},{"en":"If evidence forms the basis of a plan, the plan is more likely to match real needs.","zh":"如果證據構成計劃基礎，該計劃更可能符合真實需要。"},{"en":"This phrase shows what a decision or document is built on.","zh":"這個短語顯示決定或文件建立在甚麼之上。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":19},{"front":"Didcot’s inhabitants","meaning":"Didcot 居民","examples":[{"en":"Didcot’s inhabitants will be consulted about the town’s future.","zh":"Didcot 居民將就該鎮未來被諮詢。"},{"en":"Didcot’s inhabitants are the people who live in Didcot.","zh":"Didcot’s inhabitants 指居住在 Didcot 的人。"},{"en":"Didcot’s inhabitants may have views on housing, transport, services and green space.","zh":"Didcot 居民可能對房屋、交通、服務和綠化空間有意見。"},{"en":"Consulting inhabitants helps ensure planning reflects daily experience, not only official targets.","zh":"諮詢居民有助確保規劃反映日常經驗，而不只是官方目標。"},{"en":"This phrase refers specifically to local residents of Didcot.","zh":"這個短語專指 Didcot 的本地居民。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":19},{"front":"others","meaning":"其他人士","examples":[{"en":"The views of Didcot’s inhabitants and others will be considered.","zh":"Didcot 居民和其他人士的意見將被考慮。"},{"en":"Others means additional people or groups besides those already mentioned.","zh":"others 指除了已提到的人之外的其他人或群體。"},{"en":"In a town plan, others may include businesses, visitors, schools and service providers.","zh":"在市鎮規劃中，其他人士可能包括企業、訪客、學校和服務提供者。"},{"en":"Considering others can make a plan broader and fairer.","zh":"考慮其他人士可以令計劃更廣泛和公平。"},{"en":"This word avoids repeating a long list of extra groups.","zh":"這個詞避免重複一長串額外群體。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":19},{"front":"for the town","meaning":"為該市鎮","examples":[{"en":"The strategic master plan will guide future development for the town.","zh":"策略性總體規劃將指導該市鎮的未來發展。"},{"en":"For the town means intended to benefit, serve or guide that particular town.","zh":"for the town 指旨在惠及、服務或引導該特定市鎮。"},{"en":"A new library plan for the town should consider students, workers and older residents.","zh":"為該市鎮制定的新圖書館計劃應考慮學生、工人和長者居民。"},{"en":"If a plan is truly for the town, it should reflect local needs and long-term goals.","zh":"如果計劃真正是為該市鎮而設，就應反映本地需要和長遠目標。"},{"en":"This phrase shows the intended community or place affected by the plan.","zh":"這個短語顯示計劃所影響的目標社區或地方。"}],"source":"115 - Sustainable growth at Didcot The outline of a report by South Oxfordshire District Council.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 116":[{"front":"Neanderthals","meaning":"尼安德特人","examples":[{"en":"Neanderthals lived in Europe and parts of Asia for hundreds of thousands of years.","zh":"尼安德特人在歐洲和亞洲部分地區生活了數十萬年。"},{"en":"Neanderthals were an extinct human species closely related to modern humans.","zh":"尼安德特人是一種已滅絕、與現代人類關係密切的人類物種。"},{"en":"Students study Neanderthals to understand how earlier humans lived, moved, and survived.","zh":"學生研究尼安德特人，以理解早期人類如何生活、移動和生存。"},{"en":"Neanderthals disappeared after modern humans spread into some of the same regions.","zh":"在現代人類擴散到部分相同地區後，尼安德特人消失了。"},{"en":"Neanderthals are important because their DNA can still be found in many people today.","zh":"尼安德特人很重要，因為今天許多人身上仍可找到他們的DNA。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":1},{"front":"modern humans","meaning":"現代人類","examples":[{"en":"Modern humans spread out from Africa into other regions.","zh":"現代人類從非洲擴散到其他地區。"},{"en":"Modern humans are Homo sapiens, the human species living today.","zh":"現代人類是智人，即今天仍然存在的人類物種。"},{"en":"Scientists compare modern humans with extinct human species to understand what makes us different.","zh":"科學家把現代人類與已滅絕人類物種比較，以理解我們有何不同。"},{"en":"Modern humans developed complex language, culture, tools, and social systems over time.","zh":"現代人類隨時間發展出複雜語言、文化、工具和社會制度。"},{"en":"Studying modern humans alone is not enough; comparison with related species is also useful.","zh":"單研究現代人類並不足夠；與相關物種比較也很有用。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":1},{"front":"evolutionary processes","meaning":"演化過程","examples":[{"en":"The evolutionary processes that made modern humans different are hard to determine.","zh":"使現代人類變得不同的演化過程很難確定。"},{"en":"Evolutionary processes are long-term biological changes through which species develop over generations.","zh":"演化過程是物種經過多個世代發展的長期生物變化。"},{"en":"Natural selection is one evolutionary process that can make useful traits more common.","zh":"自然選擇是一種演化過程，可以令有用特徵變得更普遍。"},{"en":"Evolutionary processes are hard to study when the evidence comes from ancient bones and DNA.","zh":"當證據來自古代骨骼和DNA時，演化過程很難研究。"},{"en":"Understanding evolutionary processes helps explain why related species can become different.","zh":"理解演化過程有助解釋為何相關物種會變得不同。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":1},{"front":"make someone different from","meaning":"使某人與……不同","examples":[{"en":"Evolutionary processes have made modern humans different from other animals.","zh":"演化過程使現代人類與其他動物不同。"},{"en":"To make someone different from others means to give them features that separate them from others.","zh":"make someone different from others 是指賦予某人使其與別人分開的特徵。"},{"en":"A student’s life experience can make her different from classmates who grew up elsewhere.","zh":"學生的生活經驗可以使她與在其他地方長大的同學不同。"},{"en":"Language and culture make humans different from many other species.","zh":"語言和文化使人類與許多其他物種不同。"},{"en":"This phrase focuses on the features that create contrast between groups.","zh":"這個短語集中於造成群體之間差異的特徵。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":1},{"front":"be hard to determine","meaning":"難以確定","examples":[{"en":"The causes of these evolutionary changes are hard to determine.","zh":"這些演化變化的原因難以確定。"},{"en":"If something is hard to determine, it is difficult to know or decide with certainty.","zh":"如果某事難以確定，即是很難肯定地知道或判斷。"},{"en":"The exact cause of a headache can be hard to determine without a doctor’s examination.","zh":"沒有醫生檢查，頭痛的確切原因可能難以確定。"},{"en":"Ancient events are hard to determine when few records or remains survive.","zh":"當很少記錄或遺骸保存下來時，古代事件難以確定。"},{"en":"Scientists need strong evidence when a question is hard to determine.","zh":"當問題難以確定時，科學家需要有力證據。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":1},{"front":"without an ability to","meaning":"如果沒有……的能力","examples":[{"en":"It is hard to study human evolution without an ability to compare related species.","zh":"如果沒有比較相關物種的能力，就很難研究人類演化。"},{"en":"Without an ability to do something means lacking the skill or chance needed to do it.","zh":"without an ability to do something 是指缺乏做某事所需的技能或機會。"},{"en":"Students struggle with listening tests without an ability to recognise common sounds.","zh":"如果沒有辨認常見聲音的能力，學生會在聆聽測驗中吃力。"},{"en":"Doctors cannot diagnose well without an ability to compare symptoms and test results.","zh":"如果沒有比較症狀和檢查結果的能力，醫生很難作出良好診斷。"},{"en":"This phrase shows that a task depends on a necessary ability.","zh":"這個短語顯示某項任務依賴一種必要能力。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":1},{"front":"examine human species","meaning":"研究人類物種","examples":[{"en":"Scientists need to examine human species that developed differently.","zh":"科學家需要研究發展方式不同的人類物種。"},{"en":"To examine human species means to study different kinds of humans through fossils, DNA, and other evidence.","zh":"examine human species 是指透過化石、DNA和其他證據研究不同種類的人類。"},{"en":"Researchers examine human species to learn how bodies, brains, and behaviour changed.","zh":"研究人員研究人類物種，以了解身體、大腦和行為如何改變。"},{"en":"Examining extinct human species helps scientists avoid studying modern humans in isolation.","zh":"研究已滅絕人類物種幫助科學家避免孤立地研究現代人類。"},{"en":"This phrase refers to careful scientific study, not casual observation.","zh":"這個短語指仔細科學研究，而不是普通觀察。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":1},{"front":"achieve similar things","meaning":"取得類似成就","examples":[{"en":"Some human species did not achieve similar things to modern humans.","zh":"有些人類物種沒有取得與現代人類類似的成就。"},{"en":"To achieve similar things means to reach comparable results or accomplishments.","zh":"achieve similar things 是指達到可比較的結果或成就。"},{"en":"Two students may study the same hours but not achieve similar results.","zh":"兩名學生可能溫習相同時間，但沒有取得類似結果。"},{"en":"Some ancient human species made tools but did not achieve the same cultural complexity as modern humans.","zh":"有些古人類物種製造工具，但沒有取得與現代人類相同的文化複雜度。"},{"en":"This phrase compares outcomes, not simply effort.","zh":"這個短語比較的是結果，而不只是努力。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":1},{"front":"a scientific masterpiece","meaning":"科學傑作","examples":[{"en":"The genome analysis was described as a scientific masterpiece.","zh":"這項基因組分析被描述為科學傑作。"},{"en":"A scientific masterpiece is an outstanding piece of scientific work.","zh":"科學傑作是傑出的科學工作成果。"},{"en":"A vaccine developed after years of careful research may be called a scientific masterpiece.","zh":"經多年仔細研究而研發出的疫苗，可能被稱為科學傑作。"},{"en":"A scientific masterpiece often requires skill, patience, teamwork, and reliable evidence.","zh":"科學傑作通常需要技巧、耐性、團隊合作和可靠證據。"},{"en":"This phrase praises the quality and importance of a scientific achievement.","zh":"這個短語讚揚科學成就的質素和重要性。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":1},{"front":"colleagues from","meaning":"來自……的同事","examples":[{"en":"Svante Pääbo worked with colleagues from the Max Planck Institute.","zh":"Svante Pääbo 與來自馬克斯・普朗克研究所的同事合作。"},{"en":"Colleagues from a place are people who work with someone and belong to that organisation.","zh":"colleagues from a place 是指與某人共事且屬於該機構的人。"},{"en":"A teacher may plan a project with colleagues from another school.","zh":"老師可能與來自另一間學校的同事策劃項目。"},{"en":"Research improves when colleagues from different departments share skills.","zh":"當來自不同部門的同事分享技能時，研究會改善。"},{"en":"This phrase tells us where the co-workers or collaborators are based.","zh":"這個短語告訴我們合作者或同事來自哪裡。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":1},{"front":"Evolutionary Anthropology","meaning":"演化人類學","examples":[{"en":"The Max Planck Institute for Evolutionary Anthropology studies human evolution.","zh":"馬克斯・普朗克演化人類學研究所研究人類演化。"},{"en":"Evolutionary anthropology is the study of human origins, development, and biological change.","zh":"演化人類學是研究人類起源、發展和生物變化的學科。"},{"en":"Students of evolutionary anthropology may study fossils, genes, tools, and ancient behaviour.","zh":"演化人類學學生可能研究化石、基因、工具和古代行為。"},{"en":"Evolutionary anthropology helps explain how modern humans are related to earlier human species.","zh":"演化人類學幫助解釋現代人類如何與較早期人類物種有關。"},{"en":"This field connects biology, archaeology, genetics, and anthropology.","zh":"這個領域連接生物學、考古學、遺傳學和人類學。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":1},{"front":"make such a comparison possible","meaning":"使這種比較成為可能","examples":[{"en":"The researchers made such a comparison possible.","zh":"研究人員使這種比較成為可能。"},{"en":"To make such a comparison possible means to create the evidence or method needed to compare two things.","zh":"make such a comparison possible 是指創造比較兩事物所需的證據或方法。"},{"en":"Digital records make comparison possible between student results from different years.","zh":"數碼記錄使不同年份學生結果之間的比較成為可能。"},{"en":"Reading ancient DNA made it possible to compare Neanderthals with modern humans.","zh":"讀取古代DNA使比較尼安德特人與現代人類成為可能。"},{"en":"This phrase shows that one achievement opens the door to another.","zh":"這個短語顯示一項成就打開另一項工作的門。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":2},{"front":"at a meeting of","meaning":"在……的會議上","examples":[{"en":"The team presented its work at a meeting of a scientific association.","zh":"團隊在一個科學協會的會議上展示其工作。"},{"en":"At a meeting of means during an official gathering of a group or organisation.","zh":"at a meeting of 是指在某團體或組織的正式聚會期間。"},{"en":"A teacher may present new lesson plans at a meeting of the English department.","zh":"老師可能在英文科部門會議上展示新教案。"},{"en":"Scientists often share early findings at meetings before publishing full papers.","zh":"科學家常在發表完整論文前，於會議上分享早期發現。"},{"en":"This phrase identifies the event where information was presented.","zh":"這個短語指出資訊被展示的場合。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":2},{"front":"make public","meaning":"公開；發佈","examples":[{"en":"The researchers made public an analysis of the Neanderthal genome.","zh":"研究人員公開了對尼安德特人基因組的分析。"},{"en":"To make public means to announce, release, or share information openly.","zh":"make public 是指公開宣布、發佈或分享資訊。"},{"en":"A school may make public its exam timetable so parents can plan ahead.","zh":"學校可能公開考試時間表，讓家長提前計劃。"},{"en":"When scientists make results public, other experts can check and discuss them.","zh":"當科學家公開結果時，其他專家可以檢查和討論。"},{"en":"This phrase suggests information is no longer private or hidden.","zh":"這個短語暗示資訊不再私人或隱藏。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":2},{"front":"an analysis of","meaning":"對……的分析","examples":[{"en":"The team made public an analysis of the genome of Neanderthal man.","zh":"團隊公開了對尼安德特人基因組的分析。"},{"en":"An analysis of something is a careful study that breaks it down and explains it.","zh":"an analysis of something 是指仔細研究某事，把它拆解並解釋。"},{"en":"A teacher may give an analysis of an essay to show its strengths and weaknesses.","zh":"老師可能對文章作出分析，以顯示其優點和弱點。"},{"en":"Scientific analysis can reveal patterns that are not obvious at first sight.","zh":"科學分析可以揭示初看並不明顯的模式。"},{"en":"This phrase focuses on careful examination, not simple description.","zh":"這個短語集中於仔細檢查，而不是簡單描述。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":2},{"front":"the genome of","meaning":"……的基因組","examples":[{"en":"Scientists analysed the genome of Neanderthal man.","zh":"科學家分析了尼安德特人的基因組。"},{"en":"The genome of an organism is its complete set of genetic instructions.","zh":"某生物的基因組是其完整一套遺傳指令。"},{"en":"Doctors may study the genome of a virus to understand how it spreads.","zh":"醫生可能研究病毒的基因組，以理解它如何傳播。"},{"en":"Comparing the genome of two species can reveal shared ancestry and differences.","zh":"比較兩個物種的基因組可以揭示共同祖先和差異。"},{"en":"This phrase points to the full genetic information, not just one gene.","zh":"這個短語指完整遺傳資訊，而不只是單一基因。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":2},{"front":"Neanderthal man","meaning":"尼安德特人","examples":[{"en":"The genome of Neanderthal man was analysed by Svante Pääbo’s team.","zh":"Svante Pääbo 的團隊分析了尼安德特人的基因組。"},{"en":"Neanderthal man refers to Neanderthals, an extinct human group related to modern humans.","zh":"Neanderthal man 指尼安德特人，即與現代人類有關的已滅絕人類群體。"},{"en":"Older science texts often used the phrase Neanderthal man for this human species.","zh":"較舊的科學文本常使用 Neanderthal man 這個短語來指這種人類物種。"},{"en":"Studying Neanderthal man helps researchers understand ancient human diversity.","zh":"研究尼安德特人幫助研究人員理解古代人類多樣性。"},{"en":"Today, many writers simply use “Neanderthals” instead of “Neanderthal man.”","zh":"今天，許多作者會直接使用 “Neanderthals”，而不是 “Neanderthal man”。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":2},{"front":"to give its proper name","meaning":"說出其正式名稱","examples":[{"en":"Homo neanderthalensis, to give its proper name, lived in Europe and Asia.","zh":"說出其正式名稱，Homo neanderthalensis 生活在歐洲和亞洲。"},{"en":"To give its proper name means to state the correct formal or scientific name.","zh":"to give its proper name 是指說出正確的正式或科學名稱。"},{"en":"The red panda, to give its proper name, is Ailurus fulgens.","zh":"小熊貓，說出其正式名稱，是 Ailurus fulgens。"},{"en":"Writers use this phrase when moving from a common name to a formal name.","zh":"作者從普通名稱轉到正式名稱時會使用這個短語。"},{"en":"It helps readers recognise that the precise name may be different from everyday usage.","zh":"它幫助讀者明白精確名稱可能不同於日常用法。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":2},{"front":"Homo neanderthalensis","meaning":"尼安德特人","examples":[{"en":"Homo neanderthalensis is the proper name for Neanderthals.","zh":"Homo neanderthalensis 是尼安德特人的正式名稱。"},{"en":"Homo neanderthalensis is the scientific name for the extinct human species called Neanderthals.","zh":"Homo neanderthalensis 是被稱為尼安德特人的已滅絕人類物種的學名。"},{"en":"Students may use Homo neanderthalensis in formal biology or anthropology writing.","zh":"學生在正式生物學或人類學寫作中可能使用 Homo neanderthalensis。"},{"en":"Scientific names help researchers identify species clearly across languages.","zh":"科學名稱幫助研究人員跨語言清楚識別物種。"},{"en":"Homo neanderthalensis is often compared with Homo sapiens in studies of human evolution.","zh":"在人類演化研究中，Homo neanderthalensis 常與 Homo sapiens 比較。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":2},{"front":"live in Europe and parts of Asia","meaning":"生活在歐洲及亞洲部分地區","examples":[{"en":"Homo neanderthalensis lived in Europe and parts of Asia.","zh":"Homo neanderthalensis 生活在歐洲及亞洲部分地區。"},{"en":"To live in Europe and parts of Asia means to inhabit those regions over time.","zh":"live in Europe and parts of Asia 是指長期棲居於這些地區。"},{"en":"Some ancient animal species lived in Europe and parts of Asia before climate changed.","zh":"有些古代動物物種在氣候改變前生活在歐洲及亞洲部分地區。"},{"en":"Where a species lived can affect what food, climate, and competitors it faced.","zh":"一個物種住在哪裡會影響它面對的食物、氣候和競爭者。"},{"en":"Neanderthals’ range matters because it later overlapped with modern humans.","zh":"尼安德特人的分佈範圍很重要，因為後來與現代人類重疊。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":2},{"front":"from 400,000 years ago to 30,000 years ago","meaning":"從40萬年前至3萬年前","examples":[{"en":"Neanderthals lived from 400,000 years ago to 30,000 years ago.","zh":"尼安德特人生活於從40萬年前至3萬年前。"},{"en":"From 400,000 years ago to 30,000 years ago describes a long period in the distant past.","zh":"from 400,000 years ago to 30,000 years ago 描述遙遠過去的一段漫長時期。"},{"en":"Fossils from this period can help scientists track changes in ancient humans.","zh":"來自這段時期的化石可以幫助科學家追蹤古人類變化。"},{"en":"A date range is useful when exact years are impossible to know.","zh":"當確切年份無法知道時，日期範圍很有用。"},{"en":"This phrase shows that Neanderthals existed for a very long time.","zh":"這個短語顯示尼安德特人存在了很長時間。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":2},{"front":"towards the end of","meaning":"在……接近尾聲時","examples":[{"en":"Towards the end of this period, Neanderthals shared their range with Homo sapiens.","zh":"在這段時期接近尾聲時，尼安德特人與智人共享分佈範圍。"},{"en":"Towards the end of something means near its final part.","zh":"towards the end of something 是指接近某事的最後部分。"},{"en":"Towards the end of the lesson, the teacher summarised the main points.","zh":"在課堂接近尾聲時，老師總結了主要重點。"},{"en":"Important changes often appear towards the end of a long historical period.","zh":"重要變化常在漫長歷史時期接近尾聲時出現。"},{"en":"This phrase tells readers where an event sits in a timeline.","zh":"這個短語告訴讀者事件在時間線中的位置。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":2},{"front":"share its range with","meaning":"與……共享分佈範圍","examples":[{"en":"Homo neanderthalensis shared its range with Homo sapiens.","zh":"尼安德特人與智人共享其分佈範圍。"},{"en":"To share its range with another species means to live in some of the same areas.","zh":"share its range with another species 是指與另一物種生活在部分相同地區。"},{"en":"Two bird species may share their range if they nest in the same forests.","zh":"如果兩種鳥在同一森林築巢，它們可能共享分佈範圍。"},{"en":"Species that share a range may compete, avoid each other, or interbreed.","zh":"共享分佈範圍的物種可能競爭、避開彼此，或互相雜交。"},{"en":"This phrase is about geographical overlap.","zh":"這個短語關於地理上的重疊。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":3},{"front":"interlopers","meaning":"外來者；闖入者","examples":[{"en":"Homo sapiens appeared as interlopers in Neanderthal territory.","zh":"智人以外來者身份出現在尼安德特人的領地。"},{"en":"Interlopers are people or groups who enter a place where others already live or belong.","zh":"interlopers 是進入別人已生活或所屬地方的人或群體。"},{"en":"Residents may see a company as an interloper if it enters their neighbourhood without listening.","zh":"如果公司進入社區而不聆聽居民，居民可能視它為外來者。"},{"en":"Interlopers can create tension because their arrival changes existing relationships.","zh":"外來者可能造成緊張，因為其到來改變既有關係。"},{"en":"The word often suggests outsiders who are not fully welcome.","zh":"這個詞常暗示不太受歡迎的外人。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":3},{"front":"in the form of","meaning":"以……的形式","examples":[{"en":"The interlopers came in the form of Homo sapiens.","zh":"這些外來者以智人的形式出現。"},{"en":"In the form of means appearing as or taking the shape of something.","zh":"in the form of 是指以某種形式或樣貌出現。"},{"en":"Help may come in the form of money, advice, or extra staff.","zh":"幫助可以以金錢、建議或額外人手的形式出現。"},{"en":"Stress can appear in the form of headaches, poor sleep, or anger.","zh":"壓力可以以頭痛、睡眠差或憤怒的形式出現。"},{"en":"This phrase explains what kind of thing is being referred to.","zh":"這個短語解釋所指的是哪一種事物。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":3},{"front":"Homo sapiens","meaning":"智人；現代人類","examples":[{"en":"Homo sapiens spread out from Africa.","zh":"智人從非洲擴散出去。"},{"en":"Homo sapiens is the scientific name for modern humans.","zh":"Homo sapiens 是現代人類的學名。"},{"en":"Fossils and DNA help scientists study how Homo sapiens moved across the world.","zh":"化石和DNA幫助科學家研究智人如何遷移到世界各地。"},{"en":"Homo sapiens eventually shared some regions with Neanderthals.","zh":"智人最終與尼安德特人共享部分地區。"},{"en":"This species is the only human species still living today.","zh":"這個物種是今天唯一仍然存在的人類物種。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":3},{"front":"spread out from","meaning":"從……擴散出去","examples":[{"en":"Homo sapiens were spreading out from Africa.","zh":"智人正從非洲擴散出去。"},{"en":"To spread out from a place means to move from one origin into wider areas.","zh":"spread out from a place 是指從一個起點移向更廣泛地區。"},{"en":"A family business may spread out from one city into nearby towns.","zh":"家族企業可能從一個城市擴展到附近城鎮。"},{"en":"When a species spreads out, it may meet new climates, food sources, and rivals.","zh":"當物種擴散出去，它可能遇到新氣候、食物來源和競爭者。"},{"en":"This phrase describes movement from a starting point.","zh":"這個短語描述從起點向外移動。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":3},{"front":"settle down to","meaning":"安定下來進入……","examples":[{"en":"The two species did not settle down to stable cohabitation.","zh":"兩個物種沒有安定下來進入穩定共存。"},{"en":"To settle down to something means to begin a steady and lasting state or activity.","zh":"settle down to something 是指開始一種穩定而持久的狀態或活動。"},{"en":"After moving house, a family may settle down to a quieter routine.","zh":"搬家後，一個家庭可能安定下來進入較安靜的日常生活。"},{"en":"Two teams cannot settle down to cooperation if they keep competing for control.","zh":"如果兩個團隊一直爭奪控制權，就不能安定下來合作。"},{"en":"This phrase suggests stability after movement or uncertainty.","zh":"這個短語暗示在移動或不確定之後出現穩定。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":3},{"front":"stable cohabitation","meaning":"穩定共存","examples":[{"en":"Neanderthals and Homo sapiens did not achieve stable cohabitation.","zh":"尼安德特人和智人沒有達成穩定共存。"},{"en":"Stable cohabitation means living together in the same area peacefully or continuously.","zh":"stable cohabitation 是指在同一地區和平或持續地一起生活。"},{"en":"Two families need clear rules if they want stable cohabitation in one house.","zh":"如果兩個家庭想在同一房子穩定共存，就需要清晰規則。"},{"en":"Species may fail to achieve stable cohabitation if they compete for the same resources.","zh":"如果物種爭奪相同資源，可能無法達成穩定共存。"},{"en":"This phrase suggests long-term coexistence rather than brief contact.","zh":"這個短語暗示長期共存，而不是短暫接觸。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":3},{"front":"for reasons which are as yet unknown","meaning":"因為至今仍未知的原因","examples":[{"en":"For reasons which are as yet unknown, Neanderthals disappeared after Homo sapiens arrived.","zh":"因為至今仍未知的原因，尼安德特人在智人到來後消失。"},{"en":"For reasons which are as yet unknown means the causes are still not known.","zh":"for reasons which are as yet unknown 是指原因仍然未知。"},{"en":"For reasons as yet unknown, some patients recover faster than others.","zh":"因為至今仍未知的原因，有些病人康復得比其他人快。"},{"en":"Scientists use this phrase when evidence is incomplete and they cannot explain an event fully.","zh":"當證據不完整且科學家不能完全解釋事件時，會使用這個短語。"},{"en":"It signals uncertainty rather than a confirmed conclusion.","zh":"它表示不確定性，而不是已確認結論。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":3},{"front":"the arrival of","meaning":"……的到來","examples":[{"en":"The arrival of Homo sapiens was followed by the disappearance of Neanderthals.","zh":"智人的到來之後，尼安德特人消失了。"},{"en":"The arrival of someone or something means the time when they reach or enter a place.","zh":"the arrival of someone or something 是指某人或某物到達或進入某地的時候。"},{"en":"The arrival of new students can change the atmosphere of a class.","zh":"新生的到來可以改變班級氣氛。"},{"en":"The arrival of a new technology may create both opportunities and problems.","zh":"新科技的到來可能創造機會，也帶來問題。"},{"en":"This phrase often marks the beginning of a new situation.","zh":"這個短語常標誌新情況的開始。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":3},{"front":"in a region","meaning":"在一個地區","examples":[{"en":"The arrival of Homo sapiens in a region was followed by Neanderthal disappearance.","zh":"智人在一個地區的到來之後，尼安德特人消失。"},{"en":"In a region means in a particular area or part of the world.","zh":"in a region 是指在某個特定地區或世界某部分。"},{"en":"A disease may spread quickly in a region with poor sanitation.","zh":"在衛生條件差的地區，疾病可能快速傳播。"},{"en":"Climate, food, and geography in a region can affect how people live.","zh":"一個地區的氣候、食物和地理會影響人們如何生活。"},{"en":"This phrase limits the discussion to a specific area.","zh":"這個短語把討論限制在特定區域。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":3},{"front":"be followed by","meaning":"隨後出現……","examples":[{"en":"The arrival of Homo sapiens was followed by the disappearance of Neanderthals.","zh":"智人的到來隨後出現尼安德特人的消失。"},{"en":"To be followed by something means one event happens after another.","zh":"be followed by 是指一件事在另一件事之後發生。"},{"en":"Heavy rain was followed by flooding in low areas.","zh":"大雨之後，低窪地區隨後出現水浸。"},{"en":"A warning should be followed by clear instructions on what to do next.","zh":"警告之後應有清晰指示，說明下一步怎樣做。"},{"en":"This phrase shows sequence, but it does not always prove cause.","zh":"這個短語顯示先後次序，但不一定證明因果。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":3},{"front":"the disappearance of","meaning":"……的消失","examples":[{"en":"The disappearance of Neanderthals remains an important scientific question.","zh":"尼安德特人的消失仍是一個重要科學問題。"},{"en":"The disappearance of something means it stopped existing, being seen, or being present.","zh":"the disappearance of something 是指某事停止存在、被看見或出現。"},{"en":"The disappearance of a local language can happen when young people stop speaking it.","zh":"當年輕人停止使用某本地語言時，該語言可能消失。"},{"en":"Scientists study the disappearance of species to understand extinction and environmental change.","zh":"科學家研究物種消失，以理解滅絕和環境變化。"},{"en":"This phrase can refer to a mystery when the cause is unclear.","zh":"當原因不清楚時，這個短語可以指一個謎團。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":4},{"front":"conduct a comparison","meaning":"進行比較","examples":[{"en":"The team conducted a comparison between Neanderthal and modern human DNA.","zh":"團隊對尼安德特人和現代人類DNA進行比較。"},{"en":"To conduct a comparison means to carefully examine similarities and differences.","zh":"conduct a comparison 是指仔細檢視相似和差異。"},{"en":"A teacher may conduct a comparison between two essays to show different writing styles.","zh":"老師可能比較兩篇文章，以展示不同寫作風格。"},{"en":"Scientists conduct comparisons to find patterns that one sample alone cannot reveal.","zh":"科學家進行比較，以找出單一樣本無法揭示的模式。"},{"en":"This phrase suggests a planned and systematic comparison.","zh":"這個短語暗示有計劃且有系統的比較。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":4},{"front":"a superficial comparison","meaning":"表面比較；初步比較","examples":[{"en":"Before 2009, the team had conducted only a superficial comparison.","zh":"2009年前，團隊只進行了表面比較。"},{"en":"A superficial comparison is a limited or shallow comparison that does not examine details deeply.","zh":"superficial comparison 是有限或淺層的比較，沒有深入檢查細節。"},{"en":"Comparing two schools only by exam scores is a superficial comparison.","zh":"只用考試分數比較兩間學校，是表面比較。"},{"en":"A superficial comparison may miss important differences hidden in the details.","zh":"表面比較可能錯過隱藏在細節中的重要差異。"},{"en":"Researchers often begin with a superficial comparison before doing deeper analysis.","zh":"研究人員常先作初步比較，再進行更深入分析。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":4},{"front":"the DNA of","meaning":"……的DNA","examples":[{"en":"The team compared the DNA of Neanderthals and modern humans.","zh":"團隊比較了尼安德特人和現代人類的DNA。"},{"en":"The DNA of an organism is its genetic material carrying inherited information.","zh":"某生物的DNA是攜帶遺傳資訊的基因材料。"},{"en":"Doctors may study the DNA of a patient to understand certain disease risks.","zh":"醫生可能研究病人的DNA，以理解某些疾病風險。"},{"en":"Comparing the DNA of related species can show where they are similar and different.","zh":"比較相關物種的DNA可以顯示它們相似和不同之處。"},{"en":"This phrase refers to genetic evidence, not outward appearance.","zh":"這個短語指基因證據，而不是外貌。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":4},{"front":"since then","meaning":"自那時起","examples":[{"en":"Since then, the researchers have performed a more thorough study.","zh":"自那時起，研究人員進行了更深入的研究。"},{"en":"Since then means from that time until now or until a later point.","zh":"since then 是指從那時起直到現在或較後某一點。"},{"en":"She joined the club last year; since then, her confidence has grown.","zh":"她去年加入社團；自那時起，她的信心增加了。"},{"en":"Scientists made an early discovery and since then have collected more evidence.","zh":"科學家作出早期發現，自那時起收集了更多證據。"},{"en":"This phrase connects a past event with later developments.","zh":"這個短語把過去事件與後來發展連接起來。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":4},{"front":"perform a more thorough study","meaning":"進行更深入的研究","examples":[{"en":"The researchers performed a more thorough study of the two species.","zh":"研究人員對兩個物種進行了更深入的研究。"},{"en":"To perform a more thorough study means to examine something more carefully and completely.","zh":"perform a more thorough study 是指更仔細和完整地研究某事。"},{"en":"A doctor may perform a more thorough study if the first test gives unclear results.","zh":"如果第一次檢查結果不清楚，醫生可能進行更深入研究。"},{"en":"A more thorough study can correct mistakes from a first, shallow comparison.","zh":"更深入的研究可以修正第一次淺層比較中的錯誤。"},{"en":"This phrase suggests deeper evidence and more careful methods.","zh":"這個短語暗示更深入證據和更仔細方法。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":4},{"front":"in doing so","meaning":"在這樣做的過程中","examples":[{"en":"In doing so, they shed light on the history of the two species.","zh":"在這樣做的過程中，他們揭示了兩個物種的歷史。"},{"en":"In doing so means by doing the action just mentioned.","zh":"in doing so 是指透過剛才提到的行動。"},{"en":"The teacher asked students to compare sources; in doing so, they learned to spot bias.","zh":"老師要求學生比較資料來源；在這樣做的過程中，他們學會發現偏見。"},{"en":"Researchers analysed DNA; in doing so, they found evidence of ancient contact.","zh":"研究人員分析DNA；在這樣做的過程中，他們找到古代接觸的證據。"},{"en":"This phrase links an action with its result.","zh":"這個短語把行動與結果連接起來。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":4},{"front":"shed light on","meaning":"闡明；揭示","examples":[{"en":"The study shed light on the intertwined history of the two species.","zh":"這項研究揭示了兩個物種交織的歷史。"},{"en":"To shed light on something means to help explain or make it clearer.","zh":"shed light on 是指幫助解釋或令某事更清楚。"},{"en":"A diary can shed light on how ordinary people lived during a war.","zh":"日記可以揭示戰爭期間普通人如何生活。"},{"en":"New test results may shed light on why students are struggling.","zh":"新測驗結果可能闡明學生為何感到吃力。"},{"en":"This phrase suggests that evidence reduces confusion.","zh":"這個短語暗示證據減少了困惑。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":4},{"front":"a fascinating light on","meaning":"對……作出引人入勝的揭示","examples":[{"en":"The research shed a fascinating light on human evolution.","zh":"這項研究對人類演化作出引人入勝的揭示。"},{"en":"A fascinating light on something is an interesting new explanation or view of it.","zh":"a fascinating light on something 是指對某事作出有趣的新解釋或看法。"},{"en":"Old letters can shed a fascinating light on family history.","zh":"舊信件可以對家族歷史作出引人入勝的揭示。"},{"en":"DNA evidence can shed a fascinating light on relationships between ancient groups.","zh":"DNA證據可以對古代群體之間的關係作出引人入勝的揭示。"},{"en":"This phrase suggests that the new information is both useful and intriguing.","zh":"這個短語暗示新資訊既有用又耐人尋味。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":4},{"front":"intertwined history","meaning":"交織的歷史","examples":[{"en":"The two species had an intertwined history.","zh":"兩個物種有交織的歷史。"},{"en":"Intertwined history means the histories of two groups are closely connected.","zh":"intertwined history 是指兩個群體的歷史密切相連。"},{"en":"Neighbouring cities may have intertwined histories because people traded and married across borders.","zh":"鄰近城市可能因跨境貿易和通婚而有交織的歷史。"},{"en":"Intertwined history can make it hard to separate one group’s story from another’s.","zh":"交織的歷史會令人難以把一個群體的故事與另一個分開。"},{"en":"DNA evidence suggests that Neanderthals and modern humans had intertwined histories.","zh":"DNA證據顯示尼安德特人和現代人類有交織的歷史。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":4},{"front":"turn out to be","meaning":"結果是","examples":[{"en":"That history turned out to be more intertwined than expected.","zh":"那段歷史結果比預期更交織。"},{"en":"To turn out to be means to be discovered later as a particular thing.","zh":"turn out to be 是指後來被發現是某種情況。"},{"en":"The difficult student turned out to be nervous rather than lazy.","zh":"那個難教的學生結果是緊張，而不是懶惰。"},{"en":"A small mistake can turn out to be important if it changes the result.","zh":"如果小錯誤改變結果，它結果可能很重要。"},{"en":"This phrase shows that later evidence changed the original expectation.","zh":"這個短語顯示後來證據改變了原本預期。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":4},{"front":"previously believed","meaning":"以往所相信的","examples":[{"en":"The history was more complex than many had previously believed.","zh":"這段歷史比許多人以往所相信的更複雜。"},{"en":"Previously believed means thought to be true before new evidence appeared.","zh":"previously believed 是指在新證據出現前被認為是真實的。"},{"en":"The illness was more serious than doctors had previously believed.","zh":"這種疾病比醫生以往所相信的更嚴重。"},{"en":"A species may be older than scientists previously believed after new fossils are found.","zh":"發現新化石後，一個物種可能比科學家以往所相信的更古老。"},{"en":"This phrase contrasts old understanding with newer evidence.","zh":"這個短語把舊理解與新證據作對比。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":5},{"front":"compare something with","meaning":"將某物與……比較","examples":[{"en":"The researchers compared the Neanderthal genome with that of five living humans.","zh":"研究人員將尼安德特人基因組與五名現存人類的基因組比較。"},{"en":"To compare something with another thing means to examine similarities and differences between them.","zh":"compare something with another thing 是指檢視兩者之間的相似和差異。"},{"en":"Students compare one essay with another to understand different writing styles.","zh":"學生把一篇文章與另一篇比較，以理解不同寫作風格。"},{"en":"Scientists compare genomes to find shared genes and unique changes.","zh":"科學家比較基因組，以找出共有基因和獨有變化。"},{"en":"This phrase is useful when evidence from two sources is placed side by side.","zh":"當兩個來源的證據被並列檢視時，這個短語很有用。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":5},{"front":"painstakingly reconstructed","meaning":"費盡心力重建","examples":[{"en":"The Neanderthal genome was painstakingly reconstructed from bone samples.","zh":"尼安德特人基因組由骨骼樣本費盡心力重建出來。"},{"en":"Painstakingly reconstructed means rebuilt very carefully through difficult and detailed work.","zh":"painstakingly reconstructed 是指透過困難而細緻的工作，非常小心地重建。"},{"en":"Historians painstakingly reconstructed the old map from torn paper fragments.","zh":"歷史學家由撕裂紙片費盡心力重建舊地圖。"},{"en":"Ancient DNA must be painstakingly reconstructed because samples are damaged and incomplete.","zh":"古代DNA必須費盡心力重建，因為樣本受損且不完整。"},{"en":"This phrase emphasises patience, precision, and hard work.","zh":"這個短語強調耐性、精確和艱苦工作。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":5},{"front":"bone samples","meaning":"骨骼樣本","examples":[{"en":"The genome was reconstructed from three bone samples.","zh":"基因組由三份骨骼樣本重建而成。"},{"en":"Bone samples are small pieces of bone used for scientific testing or analysis.","zh":"骨骼樣本是用於科學測試或分析的小塊骨頭。"},{"en":"Doctors may take bone samples to investigate certain diseases.","zh":"醫生可能取骨骼樣本來調查某些疾病。"},{"en":"In archaeology, bone samples can preserve DNA even after thousands of years.","zh":"在考古學中，骨骼樣本即使經過數千年仍可能保存DNA。"},{"en":"Bone samples are valuable because they can reveal age, health, diet, and ancestry.","zh":"骨骼樣本很有價值，因為它們可以揭示年齡、健康、飲食和血統。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":5},{"front":"collected from","meaning":"從……收集得來","examples":[{"en":"The bone samples were collected from a cave in Croatia.","zh":"骨骼樣本從克羅地亞的一個洞穴收集得來。"},{"en":"Collected from means gathered or taken from a particular place or source.","zh":"collected from 是指從某個地方或來源收集或取得。"},{"en":"Water samples were collected from the river to check pollution levels.","zh":"水樣本從河流收集得來，以檢查污染水平。"},{"en":"Evidence collected from several sites can make a study more reliable.","zh":"從多個地點收集得來的證據，可以令研究更可靠。"},{"en":"This phrase identifies the origin of the material.","zh":"這個短語指出材料的來源。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":5},{"front":"a cave in Croatia","meaning":"克羅地亞的一個洞穴","examples":[{"en":"The Neanderthal bone samples came from a cave in Croatia.","zh":"尼安德特人的骨骼樣本來自克羅地亞的一個洞穴。"},{"en":"A cave in Croatia means an underground or hollow rock space located in Croatia.","zh":"a cave in Croatia 是指位於克羅地亞的地下或岩石空洞。"},{"en":"Archaeologists may search a cave in Croatia for bones, tools, and traces of ancient life.","zh":"考古學家可能在克羅地亞的一個洞穴中尋找骨骼、工具和古代生活痕跡。"},{"en":"Caves can preserve fossils because they protect remains from weather and disturbance.","zh":"洞穴可以保存化石，因為它們保護遺骸免受天氣和干擾影響。"},{"en":"This phrase gives the geographical source of the Neanderthal samples.","zh":"這個短語提供尼安德特人樣本的地理來源。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":5},{"front":"living humans","meaning":"現存人類","examples":[{"en":"The study compared Neanderthal DNA with DNA from living humans.","zh":"這項研究把尼安德特人DNA與現存人類DNA比較。"},{"en":"Living humans are people alive today, rather than ancient or extinct humans.","zh":"living humans 是今天仍然活著的人，而不是古代或已滅絕人類。"},{"en":"Genetic studies often compare fossils with living humans to trace ancestry.","zh":"基因研究常把化石與現存人類比較，以追蹤祖源。"},{"en":"DNA from living humans can reveal inherited links to ancient populations.","zh":"現存人類的DNA可以揭示與古代人群的遺傳連繫。"},{"en":"This phrase contrasts present-day people with ancient remains.","zh":"這個短語把今天的人與古代遺骸作對比。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":5},{"front":"various parts of","meaning":"……的不同地區","examples":[{"en":"The five living humans came from various parts of Africa and Eurasia.","zh":"這五名現存人類來自非洲和歐亞大陸的不同地區。"},{"en":"Various parts of a place means several different areas within that place.","zh":"various parts of a place 是指該地方內的幾個不同地區。"},{"en":"Students came from various parts of the city to join the competition.","zh":"學生從城市不同地區來參加比賽。"},{"en":"Samples from various parts of a region give researchers a broader picture.","zh":"來自一個地區不同部分的樣本，給研究人員更廣闊的圖像。"},{"en":"This phrase shows that the source is not limited to one location.","zh":"這個短語顯示來源不限於一個地點。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":5},{"front":"Africa and Eurasia","meaning":"非洲和歐亞大陸","examples":[{"en":"The comparison included humans from Africa and Eurasia.","zh":"這項比較包括來自非洲和歐亞大陸的人類。"},{"en":"Africa and Eurasia refers to Africa and the combined landmass of Europe and Asia.","zh":"Africa and Eurasia 指非洲以及歐洲和亞洲合成的陸塊。"},{"en":"Human migration studies often compare populations from Africa and Eurasia.","zh":"人類遷徙研究常比較來自非洲和歐亞大陸的人群。"},{"en":"Different regions can preserve different genetic histories.","zh":"不同地區可以保存不同基因歷史。"},{"en":"This phrase gives a broad geographical frame for the DNA comparison.","zh":"這個短語為DNA比較提供廣闊地理框架。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":5},{"front":"previous genetic analysis","meaning":"以往的基因分析","examples":[{"en":"Previous genetic analysis had suggested no interbreeding.","zh":"以往的基因分析曾顯示沒有雜交。"},{"en":"Previous genetic analysis means earlier study of DNA or genes.","zh":"previous genetic analysis 是指早期對DNA或基因的研究。"},{"en":"Previous genetic analysis may be revised when newer methods examine more data.","zh":"當新方法檢查更多數據時，以往的基因分析可能被修正。"},{"en":"In medicine, previous genetic analysis can guide later testing and treatment.","zh":"在醫學中，以往的基因分析可以指導後續檢測和治療。"},{"en":"This phrase contrasts older scientific results with new findings.","zh":"這個短語把較舊科學結果與新發現作對比。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":5},{"front":"examine DNA","meaning":"檢查DNA","examples":[{"en":"The earlier analysis examined DNA passed from mother to child.","zh":"較早分析檢查了由母親傳給子女的DNA。"},{"en":"To examine DNA means to study genetic material carefully.","zh":"examine DNA 是指仔細研究遺傳材料。"},{"en":"Doctors examine DNA to identify inherited disease risks.","zh":"醫生檢查DNA，以識別遺傳疾病風險。"},{"en":"Scientists examine ancient DNA to learn about extinct species and migration.","zh":"科學家檢查古代DNA，以了解已滅絕物種和遷徙。"},{"en":"This phrase refers to detailed genetic investigation.","zh":"這個短語指詳細基因調查。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":5},{"front":"passed from mother to child","meaning":"由母親傳給子女","examples":[{"en":"Mitochondrial DNA is passed from mother to child.","zh":"線粒體DNA由母親傳給子女。"},{"en":"Passed from mother to child means inherited through the mother’s line.","zh":"passed from mother to child 是指透過母系遺傳。"},{"en":"Some family traditions are passed from mother to child through daily practice.","zh":"有些家庭傳統透過日常實踐由母親傳給子女。"},{"en":"Mitochondrial DNA is useful because it follows a clear maternal inheritance path.","zh":"線粒體DNA有用，因為它跟隨清晰的母系遺傳路徑。"},{"en":"This phrase highlights how something moves from one generation to the next.","zh":"這個短語突顯某事如何由一代傳到下一代。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":6},{"front":"cellular structures","meaning":"細胞結構","examples":[{"en":"Mitochondria are cellular structures.","zh":"線粒體是細胞結構。"},{"en":"Cellular structures are parts inside a cell that perform particular functions.","zh":"細胞結構是細胞內執行特定功能的部分。"},{"en":"The nucleus and mitochondria are examples of cellular structures.","zh":"細胞核和線粒體都是細胞結構的例子。"},{"en":"Damage to cellular structures can affect how a cell works.","zh":"細胞結構受損會影響細胞如何運作。"},{"en":"This phrase refers to small biological parts within cells.","zh":"這個短語指細胞內的小型生物部分。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":6},{"front":"mitochondria","meaning":"線粒體","examples":[{"en":"Earlier analysis focused on DNA in mitochondria.","zh":"較早分析集中於線粒體中的DNA。"},{"en":"Mitochondria are small structures in cells that help produce energy.","zh":"線粒體是細胞中幫助產生能量的小結構。"},{"en":"Biology students learn that mitochondria are often called the cell’s powerhouses.","zh":"生物學生學到線粒體常被稱為細胞的能量工廠。"},{"en":"Mitochondria contain DNA that is usually inherited from the mother.","zh":"線粒體含有通常由母親遺傳的DNA。"},{"en":"Mitochondrial DNA can help trace ancestry through maternal lines.","zh":"線粒體DNA可以幫助透過母系追蹤祖源。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":6},{"front":"suggest no interbreeding","meaning":"顯示沒有雜交","examples":[{"en":"Previous genetic analysis suggested no interbreeding between the species.","zh":"以往基因分析顯示兩個物種之間沒有雜交。"},{"en":"To suggest no interbreeding means to indicate that two groups did not produce offspring together.","zh":"suggest no interbreeding 是指顯示兩個群體沒有共同產生後代。"},{"en":"Early evidence may suggest no mixing, but later data can change that conclusion.","zh":"早期證據可能顯示沒有混合，但後來數據可以改變該結論。"},{"en":"DNA studies suggest interbreeding only when genetic material from one group appears in another.","zh":"只有當一個群體的遺傳材料出現在另一群體中時，DNA研究才顯示有雜交。"},{"en":"This phrase expresses a scientific conclusion based on available evidence.","zh":"這個短語表達基於現有證據的科學結論。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":6},{"front":"interbreeding between","meaning":"……之間的雜交","examples":[{"en":"The older study suggested no interbreeding between Neanderthals and modern humans.","zh":"較舊研究顯示尼安德特人和現代人類之間沒有雜交。"},{"en":"Interbreeding between two groups means members of both groups produced children together.","zh":"interbreeding between two groups 是指兩個群體的成員共同產生後代。"},{"en":"Interbreeding between related animal populations can mix their genes.","zh":"相關動物族群之間的雜交可以混合其基因。"},{"en":"Evidence of interbreeding may appear as shared DNA in later generations.","zh":"雜交證據可能以後代共有DNA的形式出現。"},{"en":"This phrase is about biological reproduction across groups.","zh":"這個短語關於群體之間的生物繁殖。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":6},{"front":"a more extensive examination","meaning":"更廣泛的檢查","examples":[{"en":"The new, more extensive examination reached a different conclusion.","zh":"新的、更廣泛的檢查得出不同結論。"},{"en":"A more extensive examination is a broader and deeper investigation than an earlier one.","zh":"more extensive examination 是比早期檢查更廣和更深入的調查。"},{"en":"A doctor may order a more extensive examination if the first check is inconclusive.","zh":"如果第一次檢查沒有結論，醫生可能安排更廣泛檢查。"},{"en":"More extensive research can reveal evidence missed by a smaller study.","zh":"更廣泛研究可以揭示小型研究錯過的證據。"},{"en":"This phrase suggests wider coverage and stronger investigation.","zh":"這個短語暗示更廣覆蓋和更強調查。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":6},{"front":"look at DNA","meaning":"查看DNA","examples":[{"en":"The new examination looked at DNA in the cell nucleus.","zh":"新檢查查看了細胞核中的DNA。"},{"en":"To look at DNA means to study or analyse genetic material.","zh":"look at DNA 是指研究或分析遺傳材料。"},{"en":"Scientists look at DNA to compare ancestry and inherited traits.","zh":"科學家查看DNA，以比較祖源和遺傳特徵。"},{"en":"Looking at more types of DNA can lead to different conclusions.","zh":"查看更多種類的DNA可以導致不同結論。"},{"en":"This phrase is less formal than “analyse DNA,” but it means careful examination.","zh":"這個短語比 analyse DNA 較不正式，但意思是仔細檢查。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":6},{"front":"the cell nucleus","meaning":"細胞核","examples":[{"en":"The new study examined DNA in the cell nucleus.","zh":"新研究檢查了細胞核中的DNA。"},{"en":"The cell nucleus is the part of a cell that contains most of its DNA.","zh":"細胞核是細胞中含有大部分DNA的部分。"},{"en":"Biology students learn that the cell nucleus helps control cell activities.","zh":"生物學生學到細胞核幫助控制細胞活動。"},{"en":"DNA in the cell nucleus can reveal ancestry from both parents.","zh":"細胞核中的DNA可以揭示來自父母雙方的祖源。"},{"en":"This phrase contrasts nuclear DNA with mitochondrial DNA.","zh":"這個短語把核DNA與線粒體DNA作對比。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":6},{"front":"rather than","meaning":"而不是","examples":[{"en":"The new study examined nuclear DNA rather than mitochondrial DNA.","zh":"新研究檢查核DNA，而不是線粒體DNA。"},{"en":"Rather than means instead of one thing, another thing is chosen or true.","zh":"rather than 是指選擇或真正適用的是某事，而不是另一事。"},{"en":"A teacher may use discussion rather than a long lecture to keep students active.","zh":"老師可能使用討論而不是長講課，以令學生保持主動。"},{"en":"Scientists examined nuclear DNA rather than only maternal DNA because they needed broader evidence.","zh":"科學家檢查核DNA，而不只是母系DNA，因為他們需要更廣泛證據。"},{"en":"This phrase clearly shows contrast between two choices.","zh":"這個短語清楚顯示兩個選擇之間的對比。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":6},{"front":"show this conclusion is wrong","meaning":"顯示這個結論是錯誤的","examples":[{"en":"The new examination shows this conclusion is wrong.","zh":"新檢查顯示這個結論是錯誤的。"},{"en":"To show a conclusion is wrong means to provide evidence that disproves an earlier idea.","zh":"show a conclusion is wrong 是指提供證據證明早前想法不正確。"},{"en":"A second test may show the first diagnosis was wrong.","zh":"第二次檢查可能顯示第一次診斷是錯誤的。"},{"en":"New DNA evidence can show that an older theory needs to be rejected.","zh":"新DNA證據可以顯示舊理論需要被否定。"},{"en":"This phrase describes correction through evidence.","zh":"這個短語描述透過證據作出修正。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":6},{"front":"by comparing","meaning":"透過比較","examples":[{"en":"By comparing African and Eurasian DNA, the team found evidence of interbreeding.","zh":"透過比較非洲和歐亞DNA，團隊找到雜交證據。"},{"en":"By comparing means through the act of examining similarities and differences.","zh":"by comparing 是指透過檢視相似和差異。"},{"en":"By comparing two essays, students can see why one argument is clearer.","zh":"透過比較兩篇文章，學生可以看見為何其中一個論點更清楚。"},{"en":"Scientists discovered genetic patterns by comparing DNA from different populations.","zh":"科學家透過比較不同人群的DNA發現基因模式。"},{"en":"This phrase explains the method used to reach a finding.","zh":"這個短語解釋達成發現所使用的方法。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":6},{"front":"ancestors","meaning":"祖先","examples":[{"en":"The ancestors of Africans could not have crossbred with Neanderthals.","zh":"非洲人的祖先不可能與尼安德特人雜交。"},{"en":"Ancestors are earlier people from whom later generations descend.","zh":"ancestors 是後代所源自的早期人物。"},{"en":"People may learn about their ancestors through family stories and old documents.","zh":"人們可能透過家庭故事和舊文件了解祖先。"},{"en":"In genetics, ancestors matter because they pass DNA to later generations.","zh":"在遺傳學中，祖先很重要，因為他們把DNA傳給後代。"},{"en":"This word can refer to family forebears or ancient population groups.","zh":"這個詞可以指家族先人，也可以指古代人群。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":7},{"front":"crossbreed with","meaning":"與……雜交","examples":[{"en":"Some Eurasian ancestors could have crossbred with Neanderthals.","zh":"有些歐亞人的祖先可能曾與尼安德特人雜交。"},{"en":"To crossbreed with another group means to reproduce with members of that group.","zh":"crossbreed with another group 是指與另一群體的成員繁殖。"},{"en":"Farmers sometimes crossbreed animals to combine useful traits.","zh":"農民有時讓動物雜交，以結合有用特徵。"},{"en":"If two ancient groups crossbred, their descendants may carry DNA from both.","zh":"如果兩個古代群體曾雜交，其後代可能帶有雙方DNA。"},{"en":"This phrase is biological and refers to producing offspring.","zh":"這個短語屬於生物學用語，指產生後代。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":7},{"front":"overlap with","meaning":"與……重疊；與……同時同地存在","examples":[{"en":"African ancestors did not overlap with Neanderthals.","zh":"非洲祖先沒有與尼安德特人重疊。"},{"en":"To overlap with another group means to exist in the same place or time as that group.","zh":"overlap with another group 是指與該群體存在於相同地方或時間。"},{"en":"Two meetings overlap when they happen at the same time.","zh":"兩個會議在同一時間舉行時，就是時間重疊。"},{"en":"Species that overlap geographically may compete or interbreed.","zh":"地理上重疊的物種可能競爭或雜交。"},{"en":"This phrase can describe time, space, or both.","zh":"這個短語可以描述時間、空間，或兩者。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":7},{"front":"Eurasians","meaning":"歐亞人","examples":[{"en":"Eurasians carry a small amount of Neanderthal DNA.","zh":"歐亞人帶有少量尼安德特人DNA。"},{"en":"Eurasians are people whose ancestry is linked to Europe and Asia.","zh":"Eurasians 是祖源與歐洲和亞洲有關的人。"},{"en":"Genetic studies may compare Eurasians with Africans to trace ancient population history.","zh":"基因研究可能比較歐亞人與非洲人，以追蹤古代人口歷史。"},{"en":"Some Eurasians inherited Neanderthal DNA because their ancestors overlapped with Neanderthals.","zh":"有些歐亞人繼承尼安德特人DNA，因為他們的祖先與尼安德特人重疊。"},{"en":"This word refers to broad ancestry across Europe and Asia.","zh":"這個詞指跨越歐洲和亞洲的廣泛祖源。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":7},{"front":"between one per cent and four per cent","meaning":"介乎百分之一至百分之四","examples":[{"en":"Eurasians are between one per cent and four per cent Neanderthal.","zh":"歐亞人的尼安德特人成分介乎百分之一至百分之四。"},{"en":"Between one per cent and four per cent means within a small percentage range from 1% to 4%.","zh":"between one per cent and four per cent 是指在1%至4%的小百分比範圍內。"},{"en":"A discount between one per cent and four per cent is small but still measurable.","zh":"介乎百分之一至百分之四的折扣很小，但仍可量度。"},{"en":"Even a small DNA percentage can reveal important ancestry.","zh":"即使很小的DNA比例，也可以揭示重要祖源。"},{"en":"This phrase gives an approximate range, not one exact number.","zh":"這個短語給出近似範圍，而不是單一精確數字。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":7},{"front":"intriguing","meaning":"引人入勝的；耐人尋味的","examples":[{"en":"The genetic finding is intriguing.","zh":"這項基因發現耐人尋味。"},{"en":"Intriguing means interesting because it makes people curious or want to know more.","zh":"intriguing 是指因令人好奇或想知道更多而有趣。"},{"en":"A strange pattern in exam results may be intriguing to teachers.","zh":"測驗結果中的奇怪模式可能令老師覺得耐人尋味。"},{"en":"An intriguing discovery often leads researchers to ask new questions.","zh":"耐人尋味的發現常引導研究人員提出新問題。"},{"en":"This word is more thoughtful than simply saying “interesting.”","zh":"這個詞比 simply saying “interesting” 更有思考意味。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":7},{"front":"after several hundred thousand years of separation","meaning":"在分離數十萬年之後","examples":[{"en":"The two species were still interfertile after several hundred thousand years of separation.","zh":"兩個物種在分離數十萬年之後仍可互相繁殖。"},{"en":"After several hundred thousand years of separation means after the groups had developed apart for a very long time.","zh":"after several hundred thousand years of separation 是指群體分開發展了非常長時間之後。"},{"en":"Two communities may become culturally different after centuries of separation.","zh":"兩個社區在分離數百年後可能變得文化不同。"},{"en":"It is surprising if species can still interbreed after a very long evolutionary separation.","zh":"如果物種在很長演化分離後仍可雜交，是令人驚訝的。"},{"en":"This phrase stresses the length of time before contact happened again.","zh":"這個短語強調再次接觸前相隔時間之長。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":7},{"front":"interfertile","meaning":"可互相繁殖的","examples":[{"en":"Neanderthals and Homo sapiens were interfertile.","zh":"尼安德特人和智人可互相繁殖。"},{"en":"Interfertile means two groups can reproduce together and produce offspring.","zh":"interfertile 是指兩個群體可以一起繁殖並產生後代。"},{"en":"Some closely related animal species are interfertile, while others are not.","zh":"有些關係密切的動物物種可互相繁殖，另一些則不能。"},{"en":"If two human species were interfertile, their DNA could mix in later generations.","zh":"如果兩個人類物種可互相繁殖，其DNA可以在後代中混合。"},{"en":"This word is technical and refers to reproductive compatibility.","zh":"這個詞是技術用語，指繁殖上的相容性。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":7},{"front":"it is strange, though, that","meaning":"然而，奇怪的是","examples":[{"en":"It is strange, though, that no Neanderthal mitochondrial DNA has appeared in modern humans.","zh":"然而，奇怪的是，現代人類中沒有出現尼安德特人線粒體DNA。"},{"en":"It is strange, though, that means the following fact is surprising despite what was just said.","zh":"it is strange, though, that 是指雖然剛才說了某事，接下來的事實仍令人驚訝。"},{"en":"It is strange, though, that the shop is empty although its food is excellent.","zh":"然而，奇怪的是，雖然這間店食物很好，卻空無一人。"},{"en":"Researchers use this phrase when evidence creates a puzzle.","zh":"當證據造成謎團時，研究人員會使用這個短語。"},{"en":"This phrase signals contrast and curiosity.","zh":"這個短語表示對比和好奇。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":7},{"front":"mitochondrial DNA","meaning":"線粒體DNA","examples":[{"en":"No Neanderthal mitochondrial DNA has turned up in modern humans.","zh":"現代人類中沒有出現尼安德特人線粒體DNA。"},{"en":"Mitochondrial DNA is genetic material found in mitochondria and usually inherited from the mother.","zh":"線粒體DNA是存在於線粒體中，通常由母親遺傳的基因材料。"},{"en":"Scientists use mitochondrial DNA to trace maternal ancestry.","zh":"科學家使用線粒體DNA追蹤母系祖源。"},{"en":"If mitochondrial DNA is absent, researchers may ask whether interbreeding followed an unusual pattern.","zh":"如果線粒體DNA缺失，研究人員可能會問雜交是否遵循不尋常模式。"},{"en":"This type of DNA is different from DNA in the cell nucleus.","zh":"這種DNA不同於細胞核中的DNA。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":7},{"front":"turn up in","meaning":"在……中出現","examples":[{"en":"No Neanderthal mitochondrial DNA has turned up in modern humans.","zh":"現代人類中沒有出現尼安德特人線粒體DNA。"},{"en":"To turn up in something means to appear or be found there.","zh":"turn up in something 是指在某處出現或被找到。"},{"en":"A missing file may turn up in the wrong folder.","zh":"遺失文件可能出現在錯誤資料夾中。"},{"en":"If a gene turns up in another population, scientists ask how it got there.","zh":"如果某基因出現在另一人群中，科學家會問它如何到達那裡。"},{"en":"This phrase is common when something appears unexpectedly.","zh":"當某事物意外出現時，這個短語很常用。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":7},{"front":"the usual pattern of","meaning":"……的通常模式","examples":[{"en":"The usual pattern of invasion involved male invaders mating with local women.","zh":"入侵的通常模式涉及男性入侵者與本地女性繁殖。"},{"en":"The usual pattern of something means the common or typical way it happens.","zh":"the usual pattern of something 是指某事發生的常見或典型方式。"},{"en":"The usual pattern of a school day includes lessons, breaks, and homework.","zh":"學校一天的通常模式包括課堂、小息和功課。"},{"en":"If evidence does not match the usual pattern, researchers may need a new explanation.","zh":"如果證據不符合通常模式，研究人員可能需要新解釋。"},{"en":"This phrase compares one case with what normally happens.","zh":"這個短語把某個個案與通常情況比較。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":8},{"front":"invasion in historical times","meaning":"歷史時期的入侵","examples":[{"en":"Invasion in historical times often involved interbreeding.","zh":"歷史時期的入侵常涉及雜交。"},{"en":"Invasion in historical times means military or population movements recorded in written history.","zh":"invasion in historical times 是指文字歷史中有記錄的軍事或人口移動。"},{"en":"Invasion in historical times can leave evidence in documents, language, culture, and DNA.","zh":"歷史時期的入侵可以在文件、語言、文化和DNA中留下證據。"},{"en":"Such invasions often changed local societies by mixing people and traditions.","zh":"這類入侵常透過人群和傳統混合改變本地社會。"},{"en":"This phrase contrasts recorded history with prehistoric events.","zh":"這個短語把有記錄歷史與史前事件作對比。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":8},{"front":"male invaders","meaning":"男性入侵者","examples":[{"en":"Male invaders often mated with women from the invaded population.","zh":"男性入侵者常與被入侵人群中的女性繁殖。"},{"en":"Male invaders are men who enter and take control of another group’s territory.","zh":"male invaders 是進入並控制另一群體領土的男性。"},{"en":"Historical invasions often involved male soldiers entering local communities.","zh":"歷史入侵常涉及男性士兵進入本地社區。"},{"en":"If male invaders had children with local women, their genes could enter the local population.","zh":"如果男性入侵者與本地女性有孩子，他們的基因可能進入本地人群。"},{"en":"This phrase is used to describe a pattern seen in some historical conquests.","zh":"這個短語用來描述某些歷史征服中的模式。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":8},{"front":"mate with","meaning":"與……交配；與……繁殖","examples":[{"en":"Male invaders often mated with local women.","zh":"男性入侵者常與本地女性繁殖。"},{"en":"To mate with someone means to reproduce or have offspring with them.","zh":"mate with someone 是指與某人或某動物繁殖並產生後代。"},{"en":"In biology, animals mate with partners to produce young.","zh":"在生物學中，動物與伴侶交配以產生幼崽。"},{"en":"If two species can mate with each other, their genes may mix.","zh":"如果兩個物種可以彼此繁殖，其基因可能混合。"},{"en":"This phrase is biological and should be used carefully in human contexts.","zh":"這個短語屬於生物學用語，在人類語境中應小心使用。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":8},{"front":"the population they had invaded","meaning":"他們所入侵的人群","examples":[{"en":"Invaders often had children with women from the population they had invaded.","zh":"入侵者常與他們所入侵人群中的女性有孩子。"},{"en":"The population they had invaded means the group of people whose land or community was entered by force.","zh":"the population they had invaded 是指其土地或社區被武力進入的人群。"},{"en":"Historical records may describe how invaders treated the population they had invaded.","zh":"歷史記錄可能描述入侵者如何對待他們所入侵的人群。"},{"en":"Contact with an invaded population can leave cultural and genetic traces.","zh":"與被入侵人群接觸可以留下文化和基因痕跡。"},{"en":"This phrase identifies the local group affected by invasion.","zh":"這個短語指出受入侵影響的本地群體。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":8},{"front":"one piece of self-knowledge","meaning":"一項自我認識","examples":[{"en":"One piece of self-knowledge is that non-Africans have some Neanderthal ancestry.","zh":"一項自我認識是非非洲人有一些尼安德特人血統。"},{"en":"One piece of self-knowledge means one fact that helps people understand themselves better.","zh":"one piece of self-knowledge 是幫助人更理解自己的其中一項事實。"},{"en":"Knowing your learning style can be one piece of self-knowledge.","zh":"知道自己的學習方式可以是一項自我認識。"},{"en":"Genetic research can give humanity new pieces of self-knowledge about its origins.","zh":"基因研究可以給人類關於起源的新自我認識。"},{"en":"This phrase suggests knowledge about who we are.","zh":"這個短語暗示關於我們是誰的知識。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":8},{"front":"at least for","meaning":"至少對……而言","examples":[{"en":"At least for non-Africans, there is a dash of Neanderthal ancestry.","zh":"至少對非非洲人而言，他們有少量尼安德特人血統。"},{"en":"At least for means the statement is true for a particular group, even if not for everyone.","zh":"at least for 是指某說法對某特定群體成立，即使不一定對所有人成立。"},{"en":"At least for beginners, short examples are easier than long explanations.","zh":"至少對初學者而言，短例子比長解釋更容易。"},{"en":"This medicine works well, at least for patients with mild symptoms.","zh":"這種藥效果不錯，至少對症狀輕微的病人而言。"},{"en":"The phrase limits a claim so it does not become too broad.","zh":"這個短語限制主張，使它不會過於廣泛。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":8},{"front":"non-Africans","meaning":"非非洲人","examples":[{"en":"Non-Africans have a dash of Neanderthal DNA in them.","zh":"非非洲人體內有少量尼安德特人DNA。"},{"en":"Non-Africans are people whose ancestry is mainly outside Africa.","zh":"non-Africans 是祖源主要在非洲以外的人。"},{"en":"Genetic studies often compare Africans and non-Africans to understand ancient migrations.","zh":"基因研究常比較非洲人和非非洲人，以理解古代遷徙。"},{"en":"Many non-Africans inherited small amounts of Neanderthal DNA through ancient interbreeding.","zh":"許多非非洲人透過古代雜交繼承了少量尼安德特人DNA。"},{"en":"This term is broad and refers to ancestry, not nationality alone.","zh":"這個詞很廣泛，指祖源，而不只是國籍。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":8},{"front":"a dash of","meaning":"少量","examples":[{"en":"Many non-Africans have a dash of Neanderthal in them.","zh":"許多非非洲人體內有少量尼安德特人成分。"},{"en":"A dash of something means a small amount of it.","zh":"a dash of something 是指少量某物。"},{"en":"A soup may need a dash of salt to improve the flavour.","zh":"湯可能需要少量鹽來改善味道。"},{"en":"A small amount of inherited DNA can reveal a dash of ancient ancestry.","zh":"少量遺傳DNA可以揭示一點古代祖源。"},{"en":"This phrase is informal and often means “a little.”","zh":"這個短語較口語，通常表示「一點」。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":8},{"front":"illuminate the differences between","meaning":"闡明……之間的差異","examples":[{"en":"Dr Pääbo’s work illuminates the differences between the two species.","zh":"Pääbo 博士的工作闡明兩個物種之間的差異。"},{"en":"To illuminate the differences between things means to make those differences clearer.","zh":"illuminate the differences between things 是指令那些差異更清楚。"},{"en":"Comparing two essays can illuminate the differences between weak and strong arguments.","zh":"比較兩篇文章可以闡明薄弱和有力論點之間的差異。"},{"en":"DNA analysis can illuminate differences that bones alone cannot show.","zh":"DNA分析可以闡明單靠骨骼無法顯示的差異。"},{"en":"This phrase suggests explanation through evidence.","zh":"這個短語暗示透過證據作出解釋。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":8},{"front":"distinguish genetic changes","meaning":"區分基因變化","examples":[{"en":"Researchers can distinguish genetic changes shared by different human species.","zh":"研究人員可以區分不同人類物種共有的基因變化。"},{"en":"To distinguish genetic changes means to identify and separate different changes in DNA.","zh":"distinguish genetic changes 是指識別並分開DNA中的不同變化。"},{"en":"Scientists distinguish genetic changes by comparing DNA from several groups.","zh":"科學家透過比較幾個群體的DNA來區分基因變化。"},{"en":"Distinguishing shared and unique changes helps explain when evolution happened.","zh":"區分共有和獨有變化有助解釋演化何時發生。"},{"en":"This phrase is about telling one type of genetic change from another.","zh":"這個短語關於分辨不同種類的基因變化。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":8},{"front":"shared by","meaning":"由……共有","examples":[{"en":"Some genetic changes are shared by several species of human.","zh":"有些基因變化由幾種人類物種共有。"},{"en":"Shared by means possessed, used, or experienced by more than one person or group.","zh":"shared by 是指由多於一個人或群體擁有、使用或經歷。"},{"en":"A classroom may have books shared by all students.","zh":"課室可能有由所有學生共有的書。"},{"en":"Traits shared by two species may come from a common ancestor.","zh":"兩個物種共有的特徵可能來自共同祖先。"},{"en":"This phrase points to common features rather than unique ones.","zh":"這個短語指共同特徵，而不是獨有特徵。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":9},{"front":"evolution away from","meaning":"從……演化分離出來","examples":[{"en":"Some genetic changes occurred during evolution away from the great-ape lineage.","zh":"有些基因變化發生在人類從大型猿類譜系演化分離出來期間。"},{"en":"Evolution away from something means gradual development that separates one group from an earlier lineage.","zh":"evolution away from something 是指逐漸發展，使一個群體與較早譜系分離。"},{"en":"Human evolution away from other apes involved changes in walking, hands, and brain use.","zh":"人類從其他猿類演化分離出來，涉及行走、手部和大腦使用的變化。"},{"en":"As groups evolve away from one another, they may develop different traits.","zh":"當群體彼此演化分離出來時，它們可能發展出不同特徵。"},{"en":"This phrase describes divergence over long evolutionary time.","zh":"這個短語描述漫長演化時間中的分化。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":9},{"front":"the great-ape lineage","meaning":"大型猿類譜系","examples":[{"en":"Humans evolved away from the great-ape lineage.","zh":"人類從大型猿類譜系演化分離出來。"},{"en":"The great-ape lineage refers to the evolutionary line that includes great apes and their ancestors.","zh":"great-ape lineage 是指包括大型猿類及其祖先的演化線。"},{"en":"Chimpanzees, gorillas, orangutans, and humans are connected through the great-ape lineage.","zh":"黑猩猩、大猩猩、猩猩和人類都透過大型猿類譜系相連。"},{"en":"Studying the great-ape lineage helps scientists understand what humans share with apes.","zh":"研究大型猿類譜系幫助科學家理解人類與猿類共有甚麼。"},{"en":"This phrase is about evolutionary relationship, not modern family ancestry.","zh":"這個短語關於演化關係，而不是現代家族祖先。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":9},{"front":"be unique to","meaning":"為……所獨有","examples":[{"en":"Some genetic changes are unique to Homo sapiens.","zh":"有些基因變化為智人所獨有。"},{"en":"To be unique to a group means to belong only to that group.","zh":"be unique to a group 是指只屬於該群體。"},{"en":"A school tradition may be unique to one campus.","zh":"一項學校傳統可能為某一校園所獨有。"},{"en":"A genetic change unique to modern humans may help explain a special human trait.","zh":"為現代人類所獨有的基因變化，可能幫助解釋特殊人類特徵。"},{"en":"This phrase highlights difference rather than shared features.","zh":"這個短語強調差異，而不是共有特徵。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":9},{"front":"more than 90 per cent of","meaning":"超過百分之九十的……","examples":[{"en":"More than 90 per cent of the human accelerated regions are also found in Neanderthals.","zh":"超過百分之九十的人類加速區域也在尼安德特人中找到。"},{"en":"More than 90 per cent of something means a very large majority of it.","zh":"more than 90 per cent of something 是指某事物中極大多數。"},{"en":"More than 90 per cent of the class passed the test, so most students understood the topic.","zh":"超過百分之九十的學生通過測驗，所以大多數學生理解該題目。"},{"en":"A figure above 90 per cent suggests the pattern is widespread, not rare.","zh":"超過九成的數字暗示該模式很普遍，而不是罕見。"},{"en":"This phrase gives strong quantitative support to a claim.","zh":"這個短語為主張提供強烈量化支持。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":9},{"front":"human accelerated regions","meaning":"人類加速區域","examples":[{"en":"Human accelerated regions evolved very rapidly in the human genome.","zh":"人類加速區域在人類基因組中演化得非常迅速。"},{"en":"Human accelerated regions are parts of the human genome that changed unusually quickly in evolution.","zh":"human accelerated regions 是人類基因組中在演化中異常快速改變的部分。"},{"en":"Scientists study human accelerated regions to find DNA linked to human traits.","zh":"科學家研究人類加速區域，以尋找與人類特徵相關的DNA。"},{"en":"If a region evolved rapidly, it may have played an important role in adaptation.","zh":"如果某區域演化迅速，它可能在適應中扮演重要角色。"},{"en":"This phrase refers to fast-changing DNA areas, not physical regions of the body.","zh":"這個短語指快速變化的DNA區域，而不是身體的實體區域。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":9},{"front":"be identified in","meaning":"在……中被識別出來","examples":[{"en":"Human accelerated regions have been identified in modern people.","zh":"人類加速區域已在現代人中被識別出來。"},{"en":"To be identified in something means to be found or recognised there.","zh":"be identified in something 是指在某處被找到或辨認出來。"},{"en":"A mistake was identified in the report after a careful review.","zh":"經仔細審閱後，報告中一個錯誤被識別出來。"},{"en":"Genetic changes identified in a population can help explain inherited traits.","zh":"在人群中被識別出的基因變化，可以幫助解釋遺傳特徵。"},{"en":"This phrase suggests discovery through examination.","zh":"這個短語暗示透過檢查而發現。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":9},{"front":"modern people","meaning":"現代人","examples":[{"en":"Most human accelerated regions found in modern people are also found in Neanderthals.","zh":"在現代人中找到的大多數人類加速區域也在尼安德特人中找到。"},{"en":"Modern people are humans living today or in the present era.","zh":"modern people 是今天或當代生活的人類。"},{"en":"DNA from modern people can be compared with ancient DNA to trace shared ancestry.","zh":"現代人的DNA可以與古代DNA比較，以追蹤共同祖源。"},{"en":"Modern people may carry small amounts of DNA from extinct human groups.","zh":"現代人可能帶有少量已滅絕人類群體的DNA。"},{"en":"This phrase contrasts people alive now with ancient humans.","zh":"這個短語把今天活著的人與古代人類作對比。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":9},{"front":"the rest","meaning":"其餘部分","examples":[{"en":"The rest of these regions are not found in Neanderthals.","zh":"這些區域的其餘部分在尼安德特人中沒有找到。"},{"en":"The rest means the remaining part after some has already been mentioned.","zh":"the rest 是指在部分已提及後剩下的部分。"},{"en":"Three students stayed in class, and the rest went to the library.","zh":"三名學生留在課室，其餘學生去了圖書館。"},{"en":"In research, the rest of the data may still contain important exceptions.","zh":"在研究中，其餘數據仍可能包含重要例外。"},{"en":"This phrase helps divide a group into mentioned and remaining parts.","zh":"這個短語幫助把群體分成已提及和剩餘部分。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":9},{"front":"parts of the genome","meaning":"基因組的部分","examples":[{"en":"Dr Pääbo identified 212 parts of the genome.","zh":"Pääbo 博士識別出基因組的212個部分。"},{"en":"Parts of the genome are sections of genetic material within an organism’s complete DNA.","zh":"parts of the genome 是生物完整DNA中的基因材料片段。"},{"en":"Scientists may focus on parts of the genome linked to disease or development.","zh":"科學家可能集中研究與疾病或發育有關的基因組部分。"},{"en":"Some parts of the genome change faster than others during evolution.","zh":"基因組有些部分在演化中比其他部分變化得更快。"},{"en":"This phrase refers to DNA sections, not body parts.","zh":"這個短語指DNA片段，而不是身體部位。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":9},{"front":"seem to have undergone","meaning":"似乎經歷了","examples":[{"en":"Some parts of the genome seem to have undergone significant evolution.","zh":"基因組某些部分似乎經歷了顯著演化。"},{"en":"Seem to have undergone means appear to have experienced a particular process or change.","zh":"seem to have undergone 是指看來經歷了某個過程或變化。"},{"en":"The neighbourhood seems to have undergone major change after new transport arrived.","zh":"新交通到來後，這個社區似乎經歷了重大變化。"},{"en":"Scientists use this phrase when evidence suggests a process but certainty is limited.","zh":"當證據暗示某過程但確定性有限時，科學家會使用這個短語。"},{"en":"This wording is cautious rather than absolute.","zh":"這種措辭是謹慎的，而不是絕對的。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":9},{"front":"significant evolution","meaning":"顯著演化","examples":[{"en":"Certain parts of the genome underwent significant evolution.","zh":"基因組某些部分經歷了顯著演化。"},{"en":"Significant evolution means important biological change over time.","zh":"significant evolution 是指隨時間出現的重要生物變化。"},{"en":"A species may undergo significant evolution when its environment changes for many generations.","zh":"當環境經過多代改變時，物種可能經歷顯著演化。"},{"en":"Significant evolution in DNA can help explain new traits or abilities.","zh":"DNA中的顯著演化可以幫助解釋新特徵或能力。"},{"en":"This phrase suggests change large enough to matter scientifically.","zh":"這個短語暗示變化大到具有科學意義。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":10},{"front":"since the species split","meaning":"自物種分開以來","examples":[{"en":"Some DNA regions evolved after the species split.","zh":"有些DNA區域在物種分開後演化。"},{"en":"Since the species split means after two species separated in evolutionary history.","zh":"since the species split 是指兩個物種在演化史中分開之後。"},{"en":"Since two family branches split, their traditions may have developed differently.","zh":"自兩個家族分支分開以來，其傳統可能發展得不同。"},{"en":"DNA changes since the species split can show what became unique to each group.","zh":"自物種分開以來的DNA變化可以顯示每個群體變得獨有的特徵。"},{"en":"This phrase marks time after evolutionary separation.","zh":"這個短語標記演化分離之後的時間。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":10},{"front":"the state of genome science","meaning":"基因組科學的發展水平","examples":[{"en":"The state of genome science is still quite primitive.","zh":"基因組科學的發展水平仍然相當初步。"},{"en":"The state of genome science means the current level of knowledge and ability in genome research.","zh":"the state of genome science 是指基因組研究目前的知識和能力水平。"},{"en":"The state of medical technology can affect how accurately doctors diagnose illness.","zh":"醫療科技的發展水平會影響醫生診斷疾病的準確度。"},{"en":"If a field is still developing, scientists may not fully understand every result.","zh":"如果某領域仍在發展，科學家未必完全理解每個結果。"},{"en":"This phrase comments on how advanced or limited a field currently is.","zh":"這個短語評論一個領域目前有多先進或有限。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":10},{"front":"still quite primitive","meaning":"仍然相當初步","examples":[{"en":"Genome science is still quite primitive in some respects.","zh":"基因組科學在某些方面仍然相當初步。"},{"en":"Still quite primitive means still at an early or not fully developed stage.","zh":"still quite primitive 是指仍處於早期或未完全發展階段。"},{"en":"A school’s online system may still be quite primitive if it cannot save homework properly.","zh":"如果學校網上系統不能妥善保存功課，它可能仍然相當初步。"},{"en":"Early-stage science may produce useful findings while still being quite primitive.","zh":"早期階段科學即使仍然相當初步，也可能產生有用發現。"},{"en":"This phrase shows limitation without saying the field is useless.","zh":"這個短語顯示限制，但不是說該領域無用。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":10},{"front":"it is often unclear what","meaning":"往往不清楚……是甚麼","examples":[{"en":"It is often unclear what any given bit of DNA is actually doing.","zh":"往往不清楚任何一段特定DNA實際上在發揮甚麼作用。"},{"en":"It is often unclear what means people frequently do not know the exact role or meaning of something.","zh":"it is often unclear what 是指人們經常不知道某事的確切作用或意思。"},{"en":"It is often unclear what caused a student’s sudden improvement without more evidence.","zh":"沒有更多證據時，往往不清楚學生突然進步的原因是甚麼。"},{"en":"In genetics, scientists may identify DNA differences before knowing their function.","zh":"在遺傳學中，科學家可能先識別DNA差異，才知道其功能。"},{"en":"This phrase signals uncertainty in interpretation.","zh":"這個短語表示詮釋上的不確定性。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":10},{"front":"any given bit of DNA","meaning":"任何一段特定DNA","examples":[{"en":"Scientists may not know what any given bit of DNA does.","zh":"科學家可能不知道任何一段特定DNA有甚麼作用。"},{"en":"Any given bit of DNA means any particular small section of genetic material.","zh":"any given bit of DNA 是指任何一小段特定基因材料。"},{"en":"A tiny bit of DNA can sometimes affect an important biological function.","zh":"一小段DNA有時可以影響重要生物功能。"},{"en":"Researchers may find a DNA section before understanding why it matters.","zh":"研究人員可能先找到一段DNA，才理解它為何重要。"},{"en":"This phrase focuses on a specific piece chosen from a much larger genome.","zh":"這個短語集中於從更大基因組中選出的特定片段。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":10},{"front":"actually doing","meaning":"實際上在發揮甚麼作用","examples":[{"en":"It is unclear what the DNA is actually doing.","zh":"不清楚該DNA實際上在發揮甚麼作用。"},{"en":"Actually doing means performing in reality, not just appearing or being labelled in a certain way.","zh":"actually doing 是指實際上正在做甚麼，而不是表面上看起來或被標籤為甚麼。"},{"en":"A student may look busy, but the teacher wants to know what he is actually doing.","zh":"學生可能看起來很忙，但老師想知道他實際上在做甚麼。"},{"en":"Scientists need experiments to discover what a gene is actually doing in the body.","zh":"科學家需要實驗來發現某基因在身體中實際上發揮甚麼作用。"},{"en":"This phrase asks about real function or effect.","zh":"這個短語詢問真正功能或效果。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":10},{"front":"an examination of","meaning":"對……的檢查","examples":[{"en":"An examination of the largest DNA regions revealed important genes.","zh":"對最大DNA區域的檢查揭示了重要基因。"},{"en":"An examination of something is a careful study or inspection of it.","zh":"an examination of something 是對某事的仔細研究或檢查。"},{"en":"An examination of student essays can show common grammar problems.","zh":"對學生文章的檢查可以顯示常見文法問題。"},{"en":"An examination of DNA regions can reveal genes linked to important traits.","zh":"對DNA區域的檢查可以揭示與重要特徵相關的基因。"},{"en":"This phrase suggests careful checking for evidence.","zh":"這個短語暗示為尋找證據而仔細檢查。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":10},{"front":"regions of DNA","meaning":"DNA區域","examples":[{"en":"Some regions of DNA have evolved since the species split.","zh":"有些DNA區域自物種分開以來已經演化。"},{"en":"Regions of DNA are sections of genetic material within the genome.","zh":"regions of DNA 是基因組中的基因材料片段。"},{"en":"Certain DNA regions may control growth, brain development, or disease risk.","zh":"某些DNA區域可能控制生長、大腦發展或疾病風險。"},{"en":"Comparing regions of DNA helps scientists locate important genetic changes.","zh":"比較DNA區域幫助科學家定位重要基因變化。"},{"en":"This phrase refers to parts of DNA, not geographical regions.","zh":"這個短語指DNA的部分，而不是地理區域。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":10},{"front":"evolve in this way","meaning":"以這種方式演化","examples":[{"en":"The 20 largest regions of DNA evolved in this way.","zh":"最大的20個DNA區域以這種方式演化。"},{"en":"To evolve in this way means to change through the process just described.","zh":"evolve in this way 是指透過剛描述的過程改變。"},{"en":"A language can evolve in this way when speakers borrow words over many generations.","zh":"當使用者經過多代借用詞語時，語言可以以這種方式演化。"},{"en":"If DNA regions evolve in this way, they may mark changes after two species separated.","zh":"如果DNA區域以這種方式演化，它們可能標記兩個物種分開後的變化。"},{"en":"This phrase points back to a specific kind of development.","zh":"這個短語指回某種特定發展方式。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":10},{"front":"include several genes","meaning":"包括數個基因","examples":[{"en":"These regions include several genes associated with cognitive ability.","zh":"這些區域包括數個與認知能力有關的基因。"},{"en":"To include several genes means to contain more than one gene in a section of DNA.","zh":"include several genes 是指在一段DNA中包含多於一個基因。"},{"en":"A medical report may include several genes linked to inherited disease risk.","zh":"醫療報告可能包括數個與遺傳疾病風險相關的基因。"},{"en":"When a DNA region includes several genes, researchers must study each one carefully.","zh":"當DNA區域包括數個基因時，研究人員必須仔細研究每一個。"},{"en":"This phrase shows that a region contains multiple genetic elements.","zh":"這個短語顯示某區域包含多個遺傳元素。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":10},{"front":"be associated with","meaning":"與……有關","examples":[{"en":"Some genes are associated with cognitive ability.","zh":"有些基因與認知能力有關。"},{"en":"To be associated with something means to be connected or linked with it.","zh":"be associated with 是指與某事有連繫或關聯。"},{"en":"Poor sleep is associated with weaker concentration in class.","zh":"睡眠不足與課堂專注力較弱有關。"},{"en":"A gene associated with a trait may influence it, but further evidence is needed.","zh":"與某特徵有關的基因可能影響它，但仍需要更多證據。"},{"en":"This phrase shows connection, not always direct cause.","zh":"這個短語顯示關聯，不一定表示直接因果。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":11},{"front":"cognitive ability","meaning":"認知能力","examples":[{"en":"Several genes are associated with cognitive ability.","zh":"數個基因與認知能力有關。"},{"en":"Cognitive ability means mental skills such as learning, memory, reasoning, and problem-solving.","zh":"cognitive ability 是指學習、記憶、推理和解決問題等心理技能。"},{"en":"Teachers support cognitive ability by asking students to compare, explain, and evaluate ideas.","zh":"老師透過要求學生比較、解釋和評估想法來支持認知能力。"},{"en":"Brain injury can affect cognitive ability and make daily tasks harder.","zh":"腦部受傷會影響認知能力，令日常任務更困難。"},{"en":"This phrase refers to thinking ability, not physical strength.","zh":"這個短語指思考能力，而不是體力。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":11},{"front":"whose malfunction causes","meaning":"其功能失常會導致","examples":[{"en":"Some genes malfunction and cause serious mental problems.","zh":"有些基因功能失常並導致嚴重精神問題。"},{"en":"Whose malfunction causes means if that thing stops working properly, it leads to a problem.","zh":"whose malfunction causes 是指如果某事停止正常運作，就會導致問題。"},{"en":"A machine whose malfunction causes delays should be checked regularly.","zh":"其功能失常會導致延誤的機器應定期檢查。"},{"en":"A gene whose malfunction causes illness is important in medical research.","zh":"其功能失常會導致疾病的基因，在醫學研究中很重要。"},{"en":"This phrase links failure of function with a harmful result.","zh":"這個短語把功能失敗與有害結果連接起來。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":11},{"front":"malfunction","meaning":"功能失常","examples":[{"en":"The malfunction of certain genes can cause mental problems.","zh":"某些基因功能失常會導致精神問題。"},{"en":"A malfunction is a failure to work properly.","zh":"malfunction 是指未能正常運作。"},{"en":"A computer malfunction can delete files or stop a lesson suddenly.","zh":"電腦功能失常可能刪除文件或突然中斷課堂。"},{"en":"In the body, a genetic malfunction may affect development or health.","zh":"在身體中，基因功能失常可能影響發育或健康。"},{"en":"This word describes a breakdown in normal function.","zh":"這個詞描述正常功能的故障。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":11},{"front":"serious mental problems","meaning":"嚴重精神問題","examples":[{"en":"The malfunction of these genes causes serious mental problems.","zh":"這些基因功能失常會導致嚴重精神問題。"},{"en":"Serious mental problems are severe difficulties affecting thinking, emotion, behaviour, or daily functioning.","zh":"serious mental problems 是影響思考、情緒、行為或日常功能的嚴重困難。"},{"en":"A person with serious mental problems may need professional support and treatment.","zh":"有嚴重精神問題的人可能需要專業支援和治療。"},{"en":"Genetic and environmental factors can both influence mental health.","zh":"基因和環境因素都可能影響精神健康。"},{"en":"This phrase refers to major health issues, not ordinary stress alone.","zh":"這個短語指重大健康問題，而不只是普通壓力。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":11},{"front":"look like good places to start","meaning":"看來是開始尋找……的好地方","examples":[{"en":"These genes look like good places to start the search.","zh":"這些基因看來是開始尋找答案的好地方。"},{"en":"Look like good places to start means seem useful as the first areas to investigate.","zh":"look like good places to start 是指看起來適合作為最先研究的範圍。"},{"en":"If a student is weak in writing, sentence structure may be a good place to start.","zh":"如果學生寫作薄弱，句子結構可能是開始改善的好地方。"},{"en":"Scientists start with promising genes because they may lead to clearer answers.","zh":"科學家從有前景的基因開始，因為它們可能引向更清楚答案。"},{"en":"This phrase suggests a sensible beginning, not a final answer.","zh":"這個短語暗示合理起點，而不是最終答案。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":11},{"front":"the search for","meaning":"尋找……","examples":[{"en":"Scientists began the search for modern humanity’s essence.","zh":"科學家開始尋找現代人類的本質。"},{"en":"The search for something means the effort to find or understand it.","zh":"the search for something 是指尋找或理解某事的努力。"},{"en":"Police began the search for a missing child after the report was filed.","zh":"報案後，警方開始尋找失蹤兒童。"},{"en":"The search for answers may take years when evidence is limited.","zh":"當證據有限時，尋找答案可能需要多年。"},{"en":"This phrase suggests an active attempt to discover something.","zh":"這個短語暗示主動嘗試發現某事。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":11},{"front":"modern humanity’s essence","meaning":"現代人類的本質","examples":[{"en":"These genes may help explain modern humanity’s essence.","zh":"這些基因可能有助解釋現代人類的本質。"},{"en":"Modern humanity’s essence means the basic qualities that make modern humans what they are.","zh":"modern humanity’s essence 是指使現代人類成為現代人類的基本特質。"},{"en":"Language, culture, cooperation, and symbolic thinking may be part of humanity’s essence.","zh":"語言、文化、合作和符號思考可能是人類本質的一部分。"},{"en":"Scientists look for genetic clues to understand modern humanity’s essence.","zh":"科學家尋找基因線索，以理解現代人類的本質。"},{"en":"This phrase is abstract and refers to the deep nature of being human.","zh":"這個短語較抽象，指人之所以為人的深層本質。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":11},{"front":"newly evolved regions of DNA","meaning":"新近演化的DNA區域","examples":[{"en":"Newly evolved regions of DNA include a gene called RUNX2.","zh":"新近演化的DNA區域包括一個名為RUNX2的基因。"},{"en":"Newly evolved regions of DNA are DNA sections that changed recently in evolutionary history.","zh":"newly evolved regions of DNA 是演化史中較近期發生變化的DNA片段。"},{"en":"Scientists examine newly evolved DNA regions to find traits unique to one species.","zh":"科學家檢查新近演化的DNA區域，以尋找某物種獨有的特徵。"},{"en":"Such regions may help explain differences in bodies, brains, or behaviour.","zh":"這些區域可能幫助解釋身體、大腦或行為差異。"},{"en":"This phrase points to recent genetic changes, not ancient shared ones.","zh":"這個短語指較近期的基因變化，而不是古老共有變化。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":11},{"front":"a gene called RUNX2","meaning":"名為RUNX2的基因","examples":[{"en":"A gene called RUNX2 controls bone growth.","zh":"名為RUNX2的基因控制骨骼生長。"},{"en":"A gene called RUNX2 is a specific gene involved in skeletal development.","zh":"a gene called RUNX2 是一個涉及骨骼發育的特定基因。"},{"en":"Scientists may study RUNX2 to understand differences in skull shape.","zh":"科學家可能研究RUNX2，以理解頭骨形狀差異。"},{"en":"If a gene controls bone growth, changes in it may affect body structure.","zh":"如果一個基因控制骨骼生長，其變化可能影響身體結構。"},{"en":"This phrase introduces a particular gene by name.","zh":"這個短語按名稱介紹某個特定基因。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":11},{"front":"control bone growth","meaning":"控制骨骼生長","examples":[{"en":"RUNX2 controls bone growth.","zh":"RUNX2控制骨骼生長。"},{"en":"To control bone growth means to influence how bones form, develop, and change shape.","zh":"control bone growth 是指影響骨骼如何形成、發育和改變形狀。"},{"en":"Doctors study bone-growth genes when children have unusual skeletal development.","zh":"當兒童有不尋常骨骼發育時，醫生會研究骨骼生長基因。"},{"en":"If a gene controls bone growth, mutations in it can affect the skull or rib cage.","zh":"如果基因控制骨骼生長，其突變可能影響頭骨或胸廓。"},{"en":"This phrase links genetics with physical body structure.","zh":"這個短語把基因與身體結構連接起來。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":11},{"front":"account for differences in","meaning":"解釋……方面的差異","examples":[{"en":"The gene may account for differences in skull shape.","zh":"該基因可能解釋頭骨形狀方面的差異。"},{"en":"To account for differences in something means to explain why those differences exist.","zh":"account for differences in something 是指解釋那些差異為何存在。"},{"en":"Different teaching methods may account for differences in student confidence.","zh":"不同教學方法可能解釋學生信心方面的差異。"},{"en":"Genetic changes can account for physical differences between related species.","zh":"基因變化可以解釋相關物種之間的身體差異。"},{"en":"This phrase links a cause with observed variation.","zh":"這個短語把原因與可觀察變異連接起來。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":12},{"front":"the shape of the skull","meaning":"頭骨形狀","examples":[{"en":"RUNX2 may affect the shape of the skull.","zh":"RUNX2可能影響頭骨形狀。"},{"en":"The shape of the skull means the form or structure of the head bones.","zh":"the shape of the skull 是指頭部骨骼的形態或結構。"},{"en":"Doctors examine the shape of a child’s skull during early development.","zh":"醫生在早期發育中檢查兒童頭骨形狀。"},{"en":"Skull shape can reveal information about growth, ancestry, and species differences.","zh":"頭骨形狀可以揭示生長、祖源和物種差異的資訊。"},{"en":"This phrase refers to bone structure, not facial expression.","zh":"這個短語指骨骼結構，而不是面部表情。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":12},{"front":"the rib cage","meaning":"胸廓；肋骨架","examples":[{"en":"The gene may affect the rib cage.","zh":"該基因可能影響胸廓。"},{"en":"The rib cage is the structure of ribs that protects the heart and lungs.","zh":"rib cage 是保護心臟和肺部的肋骨結構。"},{"en":"Doctors check the rib cage when a patient has chest pain or breathing problems.","zh":"當病人有胸痛或呼吸問題時，醫生會檢查胸廓。"},{"en":"Changes in skeletal genes can influence the shape of the rib cage.","zh":"骨骼基因的變化可以影響胸廓形狀。"},{"en":"This phrase refers to a major part of the skeleton.","zh":"這個短語指骨骼中的一個主要部分。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":12},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, Neanderthals and modern humans share the same FOXP2 gene version.","zh":"相比之下，尼安德特人和現代人類共有相同版本的FOXP2基因。"},{"en":"By contrast means used to show a clear difference from the previous point.","zh":"by contrast 是指用來顯示與前一點的清楚差異。"},{"en":"Some students prefer videos; by contrast, others learn better from notes.","zh":"有些學生偏好影片；相比之下，另一些從筆記中學得更好。"},{"en":"Researchers use “by contrast” when a new fact points in the opposite direction.","zh":"當新事實指向相反方向時，研究人員會使用 by contrast。"},{"en":"This phrase helps organise comparison clearly.","zh":"這個短語幫助清楚組織比較。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":12},{"front":"an earlier phase of the study","meaning":"研究的早期階段","examples":[{"en":"An earlier phase of the study examined another gene.","zh":"研究的早期階段檢查了另一個基因。"},{"en":"An earlier phase of a study is a previous stage in a research project.","zh":"an earlier phase of a study 是研究項目中較早的階段。"},{"en":"In an earlier phase of a medical trial, researchers tested safety first.","zh":"在醫學試驗的早期階段，研究人員先測試安全性。"},{"en":"Later phases can build on results from an earlier phase.","zh":"後續階段可以建立在早期階段的結果之上。"},{"en":"This phrase places research work in a sequence.","zh":"這個短語把研究工作放在一個次序中。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":12},{"front":"share the same version of","meaning":"共有相同版本的……","examples":[{"en":"Neanderthals and modern humans share the same version of FOXP2.","zh":"尼安德特人和現代人類共有相同版本的FOXP2。"},{"en":"To share the same version of something means to have the same form of it.","zh":"share the same version of something 是指擁有某事物的相同形式。"},{"en":"Two classmates may share the same version of a textbook if the school orders one edition.","zh":"如果學校訂購同一版本，兩名同學可能共有相同版本的教科書。"},{"en":"If two species share the same gene version, that feature may have evolved before they separated.","zh":"如果兩個物種共有相同基因版本，該特徵可能在它們分開前已演化。"},{"en":"This phrase highlights genetic similarity.","zh":"這個短語強調基因相似性。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":12},{"front":"a gene called FOXP2","meaning":"名為FOXP2的基因","examples":[{"en":"A gene called FOXP2 is involved in the ability to speak.","zh":"名為FOXP2的基因涉及說話能力。"},{"en":"A gene called FOXP2 is a specific gene linked to speech and language ability.","zh":"a gene called FOXP2 是與說話和語言能力相關的特定基因。"},{"en":"Scientists study FOXP2 to understand biological factors behind speaking.","zh":"科學家研究FOXP2，以理解說話背後的生物因素。"},{"en":"Sharing this gene version does not prove two species spoke in the same way.","zh":"共有這個基因版本不代表兩個物種以相同方式說話。"},{"en":"This phrase introduces a named gene connected with language research.","zh":"這個短語介紹與語言研究相關的具名基因。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":12},{"front":"be involved in","meaning":"涉及；與……有關","examples":[{"en":"FOXP2 is involved in the ability to speak.","zh":"FOXP2涉及說話能力。"},{"en":"To be involved in something means to play a role in it or be connected with it.","zh":"be involved in something 是指在某事中扮演角色或與其有關。"},{"en":"Good sleep is involved in memory and concentration.","zh":"良好睡眠與記憶和專注有關。"},{"en":"A gene involved in speech may affect how the brain controls language.","zh":"涉及說話的基因可能影響大腦如何控制語言。"},{"en":"This phrase suggests connection, not the whole cause by itself.","zh":"這個短語暗示關聯，而不是本身就是全部原因。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":12},{"front":"the ability to speak","meaning":"說話能力","examples":[{"en":"FOXP2 is involved in the ability to speak.","zh":"FOXP2與說話能力有關。"},{"en":"The ability to speak means the capacity to produce spoken language.","zh":"the ability to speak 是指產生口語的能力。"},{"en":"Children develop the ability to speak through brain growth, hearing, and social interaction.","zh":"兒童透過大腦發育、聆聽和社交互動發展說話能力。"},{"en":"Damage to speech-related areas can affect the ability to speak.","zh":"與說話相關的區域受損可能影響說話能力。"},{"en":"This phrase refers to spoken communication, not general intelligence.","zh":"這個短語指口語溝通，而不是一般智力。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":12},{"front":"differ in chimpanzees","meaning":"在黑猩猩身上有所不同","examples":[{"en":"The FOXP2 gene differs in chimpanzees.","zh":"FOXP2基因在黑猩猩身上有所不同。"},{"en":"If a gene differs in chimpanzees, its version is not the same as in another species.","zh":"如果某基因在黑猩猩身上有所不同，即是其版本與另一物種不同。"},{"en":"A trait may differ in related animals because their evolutionary paths separated long ago.","zh":"相關動物的特徵可能因演化路徑很久以前分開而不同。"},{"en":"Genetic differences between humans and chimpanzees can help explain biological changes.","zh":"人類和黑猩猩之間的基因差異可以幫助解釋生物變化。"},{"en":"This phrase compares a gene across species.","zh":"這個短語比較跨物種的基因。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":12},{"front":"very promising","meaning":"非常有前景","examples":[{"en":"The research is very promising.","zh":"這項研究非常有前景。"},{"en":"Very promising means likely to produce useful or successful results in the future.","zh":"very promising 是指將來很可能產生有用或成功結果。"},{"en":"A student’s early writing is very promising if the ideas are clear and improving.","zh":"如果學生早期寫作想法清楚且正在進步，就非常有前景。"},{"en":"A promising study can encourage more funding and further research.","zh":"有前景的研究可以鼓勵更多資助和後續研究。"},{"en":"This phrase expresses hope based on signs of potential.","zh":"這個短語根據潛力跡象表達希望。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":12},{"front":"a second coup","meaning":"第二項重大成功","examples":[{"en":"The discovery was a second coup for Dr Pääbo.","zh":"這項發現是Pääbo博士的第二項重大成功。"},{"en":"A second coup means another major success or impressive achievement.","zh":"a second coup 是指另一項重大成功或令人印象深刻的成就。"},{"en":"Winning a second scholarship was a second coup for the student.","zh":"贏得第二項獎學金是該學生的第二項重大成功。"},{"en":"A research team gains prestige when it achieves one scientific coup after another.","zh":"當研究團隊接連取得科學重大成功時，聲望會提高。"},{"en":"This phrase praises repeated success.","zh":"這個短語讚揚重複成功。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":13},{"front":"in quick succession","meaning":"接連地；短時間內相繼","examples":[{"en":"Dr Pääbo achieved two major successes in quick succession.","zh":"Pääbo博士短時間內相繼取得兩項重大成功。"},{"en":"In quick succession means one after another with little time between them.","zh":"in quick succession 是指一件接一件，中間相隔很短時間。"},{"en":"The teacher asked three difficult questions in quick succession.","zh":"老師接連問了三條困難問題。"},{"en":"Two discoveries in quick succession can make a research field move forward rapidly.","zh":"兩項發現短時間內相繼出現，可以令研究領域快速前進。"},{"en":"This phrase stresses speed and closeness in time.","zh":"這個短語強調速度和時間上的接近。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":13},{"front":"reveal the existence of","meaning":"揭示……的存在","examples":[{"en":"Another team revealed the existence of a previously unknown human species.","zh":"另一團隊揭示了一個此前未知人類物種的存在。"},{"en":"To reveal the existence of something means to show that it exists.","zh":"reveal the existence of something 是指顯示某事物存在。"},{"en":"Satellite images may reveal the existence of an unknown settlement.","zh":"衛星圖片可能揭示未知聚落的存在。"},{"en":"DNA analysis can reveal the existence of a group not clearly visible from bones alone.","zh":"DNA分析可以揭示單靠骨骼不明顯的群體存在。"},{"en":"This phrase is used when evidence uncovers something previously unknown.","zh":"當證據揭開此前未知事物時，會使用這個短語。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":13},{"front":"hitherto unsuspected","meaning":"此前未被發現的；迄今不為人知的","examples":[{"en":"The team discovered a hitherto unsuspected species of human.","zh":"團隊發現了一個此前未被發現的人類物種。"},{"en":"Hitherto unsuspected means not known or not even suspected until now.","zh":"hitherto unsuspected 是指直到現在都不知道，甚至未曾懷疑存在。"},{"en":"A hitherto unsuspected illness may be discovered after doctors review new test results.","zh":"醫生審視新檢查結果後，可能發現此前未被發現的疾病。"},{"en":"A hitherto unsuspected link between two events can change a theory.","zh":"兩件事之間此前未被發現的關聯，可以改變理論。"},{"en":"This phrase is formal and means “previously unknown.”","zh":"這個短語較正式，意思是「以前未知的」。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":13},{"front":"species of human","meaning":"人類物種","examples":[{"en":"The researchers discovered another species of human.","zh":"研究人員發現了另一個人類物種。"},{"en":"A species of human means one kind of human in evolutionary history.","zh":"species of human 是指演化史中的一種人類。"},{"en":"Homo sapiens and Neanderthals are different species of human.","zh":"智人和尼安德特人是不同人類物種。"},{"en":"A newly discovered species of human can change our understanding of human evolution.","zh":"新發現的人類物種可以改變我們對人類演化的理解。"},{"en":"This phrase refers to human diversity across evolutionary time.","zh":"這個短語指演化時間中的人類多樣性。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":13},{"front":"using mitochondrial DNA","meaning":"使用線粒體DNA","examples":[{"en":"The team identified the species using mitochondrial DNA.","zh":"團隊使用線粒體DNA識別該物種。"},{"en":"Using mitochondrial DNA means using DNA from mitochondria as evidence.","zh":"using mitochondrial DNA 是指使用來自線粒體的DNA作為證據。"},{"en":"Scientists can trace maternal ancestry using mitochondrial DNA.","zh":"科學家可以使用線粒體DNA追蹤母系祖源。"},{"en":"Using mitochondrial DNA can help identify ancient remains when other evidence is limited.","zh":"當其他證據有限時，使用線粒體DNA可以幫助識別古代遺骸。"},{"en":"This phrase describes the method used in the discovery.","zh":"這個短語描述該發現所使用的方法。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":13},{"front":"a little-finger bone","meaning":"小指骨","examples":[{"en":"Mitochondrial DNA was found in a little-finger bone.","zh":"線粒體DNA在一塊小指骨中被找到。"},{"en":"A little-finger bone is a bone from the smallest finger of the hand.","zh":"little-finger bone 是手上最小手指的骨頭。"},{"en":"Even a little-finger bone can preserve DNA useful for scientific study.","zh":"即使是小指骨，也可以保存對科學研究有用的DNA。"},{"en":"A small bone fragment may lead to a major discovery if it contains genetic material.","zh":"如果小骨片含有基因材料，就可能導致重大發現。"},{"en":"This phrase shows that important evidence can come from a tiny remain.","zh":"這個短語顯示重要證據可以來自微小遺骸。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":13},{"front":"have its full genome read","meaning":"其完整基因組被讀取","examples":[{"en":"The new species may eventually have its full genome read.","zh":"這個新物種最終可能會有其完整基因組被讀取。"},{"en":"To have its full genome read means to have all its genetic information sequenced and analysed.","zh":"have its full genome read 是指其全部遺傳資訊被定序和分析。"},{"en":"A virus may have its full genome read so doctors can track new variants.","zh":"病毒可能有其完整基因組被讀取，以便醫生追蹤新變異。"},{"en":"If an ancient species has its full genome read, scientists can compare it with other humans.","zh":"如果古代物種的完整基因組被讀取，科學家可以將其與其他人類比較。"},{"en":"This phrase describes a complete genetic study.","zh":"這個短語描述完整基因研究。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":13},{"front":"humanity’s ability to know itself","meaning":"人類認識自身的能力","examples":[{"en":"Genome research enhances humanity’s ability to know itself.","zh":"基因組研究提升人類認識自身的能力。"},{"en":"Humanity’s ability to know itself means human beings’ capacity to understand their own origins, nature, and history.","zh":"humanity’s ability to know itself 是指人類理解自身起源、本質和歷史的能力。"},{"en":"History, biology, and archaeology all strengthen humanity’s ability to know itself.","zh":"歷史、生物學和考古學都加強人類認識自身的能力。"},{"en":"DNA research improves self-knowledge by showing links between ancient and modern people.","zh":"DNA研究透過顯示古代和現代人之間的連繫來改善自我認識。"},{"en":"This phrase presents science as a way for humans to understand who they are.","zh":"這個短語把科學呈現為人類理解自己是誰的一種方式。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":13},{"front":"be enhanced even further","meaning":"進一步提升","examples":[{"en":"Humanity’s self-knowledge could be enhanced even further.","zh":"人類的自我認識可以進一步提升。"},{"en":"To be enhanced even further means to be improved to an even greater degree.","zh":"be enhanced even further 是指被改善到更高程度。"},{"en":"A student’s writing can be enhanced further after feedback and revision.","zh":"學生寫作在回饋和修改後可以進一步提升。"},{"en":"Scientific understanding is enhanced further when new evidence confirms or extends earlier findings.","zh":"當新證據確認或延伸早期發現時，科學理解會進一步提升。"},{"en":"This phrase suggests improvement beyond an already useful level.","zh":"這個短語暗示在已有用水平之上的改善。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":13},{"front":"a complete set of genes","meaning":"完整的一套基因","examples":[{"en":"A genome is an individual’s complete set of genes.","zh":"基因組是一個個體完整的一套基因。"},{"en":"A complete set of genes means all the genetic instructions an organism has.","zh":"complete set of genes 是指生物所擁有的全部遺傳指令。"},{"en":"Scientists study a complete set of genes to understand inherited traits.","zh":"科學家研究完整一套基因，以理解遺傳特徵。"},{"en":"A complete genetic record gives more information than one gene alone.","zh":"完整基因記錄比單一基因提供更多資訊。"},{"en":"This phrase explains what a genome is.","zh":"這個短語解釋了甚麼是基因組。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":13},{"front":"the scientific name for","meaning":"……的學名","examples":[{"en":"Homo sapiens is the scientific name for modern humans.","zh":"Homo sapiens 是現代人類的學名。"},{"en":"The scientific name for something is its formal name used in science.","zh":"scientific name for something 是科學中使用的正式名稱。"},{"en":"Canis lupus is the scientific name for the grey wolf.","zh":"Canis lupus 是灰狼的學名。"},{"en":"Scientific names help people avoid confusion across languages.","zh":"學名幫助人們跨語言避免混淆。"},{"en":"This phrase introduces a precise biological name.","zh":"這個短語引入精確生物名稱。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":14},{"front":"evolve very rapidly","meaning":"演化得非常迅速","examples":[{"en":"Some regions of the human genome evolved very rapidly.","zh":"人類基因組某些區域演化得非常迅速。"},{"en":"To evolve very rapidly means to change unusually quickly over evolutionary time.","zh":"evolve very rapidly 是指在演化時間中異常快速地改變。"},{"en":"A virus can evolve rapidly when it spreads through many hosts.","zh":"病毒在許多宿主中傳播時，可以演化得很迅速。"},{"en":"Rapid evolution may show that a trait was important for adaptation.","zh":"快速演化可能顯示某特徵對適應很重要。"},{"en":"This phrase describes speed of biological change across generations.","zh":"這個短語描述跨世代生物變化的速度。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":14},{"front":"look at the following characteristics","meaning":"查看以下特徵","examples":[{"en":"Students look at the following characteristics and match them with species.","zh":"學生查看以下特徵，並將它們與物種配對。"},{"en":"Look at the following characteristics means read and consider the listed features.","zh":"look at the following characteristics 是指閱讀並考慮列出的特徵。"},{"en":"In a matching task, students look at the characteristics before choosing answers.","zh":"在配對題中，學生先查看特徵，再選答案。"},{"en":"This instruction asks students to focus on evidence, not guess from memory.","zh":"這個指示要求學生集中於證據，而不是憑記憶猜測。"},{"en":"The phrase is common in exam questions.","zh":"這個短語常見於考試題目。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":14},{"front":"the list of species below","meaning":"以下物種列表","examples":[{"en":"The list of species below gives the possible choices.","zh":"以下物種列表提供可能選項。"},{"en":"The list of species below means the set of species names printed after the instruction.","zh":"the list of species below 是指指示後列出的物種名稱組合。"},{"en":"Students should choose answers only from the list of species below.","zh":"學生應只從以下物種列表中選擇答案。"},{"en":"A list limits the possible answers and helps students avoid inventing names.","zh":"列表限制可能答案，幫助學生避免自創名稱。"},{"en":"This phrase tells students where the answer options are.","zh":"這個短語告訴學生答案選項在哪裡。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":14},{"front":"match each characteristic with","meaning":"將每項特徵與……配對","examples":[{"en":"Students match each characteristic with the correct species.","zh":"學生將每項特徵與正確物種配對。"},{"en":"To match each characteristic with something means to connect every feature to the right option.","zh":"match each characteristic with something 是指把每個特徵與正確選項連接。"},{"en":"Students may match each symptom with the correct illness in a health lesson.","zh":"學生可能在健康課中將每個症狀與正確疾病配對。"},{"en":"Matching requires careful reading because one detail may fit more than one option at first.","zh":"配對需要仔細閱讀，因為一個細節一開始可能看似符合多個選項。"},{"en":"This phrase describes a common exam task.","zh":"這個短語描述常見考試任務。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":14},{"front":"the correct species","meaning":"正確物種","examples":[{"en":"Each characteristic should be matched with the correct species.","zh":"每項特徵應與正確物種配對。"},{"en":"The correct species is the species that fits the evidence or description.","zh":"correct species 是符合證據或描述的物種。"},{"en":"In biology class, students identify the correct species by comparing features.","zh":"在生物課中，學生透過比較特徵識別正確物種。"},{"en":"Choosing the correct species requires checking the passage carefully.","zh":"選擇正確物種需要仔細查看文章。"},{"en":"This phrase focuses on accurate classification.","zh":"這個短語集中於準確分類。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":14},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Students write the correct letter on the answer sheet.","zh":"學生在答題紙上寫上正確字母。"},{"en":"To write the correct letter means to enter the option label that matches the answer.","zh":"write the correct letter 是指填入與答案相符的選項字母。"},{"en":"In matching questions, students may write A, B, or C rather than full words.","zh":"在配對題中，學生可能寫A、B或C，而不是完整詞語。"},{"en":"A correct answer can be lost if the letter is written in the wrong box.","zh":"如果字母寫在錯誤格子中，正確答案也可能失分。"},{"en":"This phrase reminds students to follow the required exam format.","zh":"這個短語提醒學生跟隨指定考試格式。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":14},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生把答案寫在答題紙上。"},{"en":"On your answer sheet means in the official place where exam answers must be recorded.","zh":"on your answer sheet 是指在考試答案必須記錄的正式位置。"},{"en":"Students should copy answers carefully onto the answer sheet before time ends.","zh":"學生應在時間結束前小心把答案抄到答題紙上。"},{"en":"Writing in the question booklet may not count if answers are not on the answer sheet.","zh":"如果答案不在答題紙上，寫在題簿中可能不計分。"},{"en":"This phrase is about answer location, not content.","zh":"這個短語關於答案位置，而不是內容。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":14},{"front":"may use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"Students may use any letter more than once.","zh":"學生可重複使用任何字母。"},{"en":"May use any letter more than once means an answer option can be repeated.","zh":"may use any letter more than once 是指某答案選項可以重複使用。"},{"en":"In some matching tasks, the same paragraph letter may answer several questions.","zh":"在某些配對題中，同一段落字母可能回答幾題。"},{"en":"Students should not force every option to be used only once if the instruction allows repeats.","zh":"如果指示允許重複，學生不應強迫每個選項只用一次。"},{"en":"This phrase prevents a common exam mistake.","zh":"這個短語防止常見考試錯誤。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":14},{"front":"once lived in","meaning":"曾經生活在……","examples":[{"en":"Neanderthals once lived in Europe and Asia.","zh":"尼安德特人曾經生活在歐洲和亞洲。"},{"en":"Once lived in means lived there in the past but no longer do so.","zh":"once lived in 是指過去生活在某地，但現在不再如此。"},{"en":"My grandparents once lived in a village before moving to the city.","zh":"我的祖父母搬到城市前曾經生活在一條村莊。"},{"en":"A species that once lived in an area may disappear because of climate change or competition.","zh":"曾經生活在某地的物種，可能因氣候變化或競爭而消失。"},{"en":"This phrase points to a past location or habitat.","zh":"這個短語指過去的地點或棲息地。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":14},{"front":"originate in","meaning":"起源於","examples":[{"en":"Modern humans originated in Africa.","zh":"現代人類起源於非洲。"},{"en":"To originate in a place means to begin or first develop there.","zh":"originate in a place 是指在某地開始或最初發展。"},{"en":"A festival may originate in an old farming tradition.","zh":"一個節日可能起源於古老農耕傳統。"},{"en":"If a species originates in one region, later migration may spread it elsewhere.","zh":"如果物種起源於一個地區，後來遷徙可能把它傳播到其他地方。"},{"en":"This phrase identifies the starting point of development.","zh":"這個短語指出發展的起點。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":14},{"front":"survive long after","meaning":"在……之後長期存活","examples":[{"en":"Neanderthals did not survive long after the arrival of Homo sapiens.","zh":"尼安德特人在智人到來後沒有長期存活。"},{"en":"To survive long after something means to continue living for a long time following that event.","zh":"survive long after something 是指在某事件之後繼續存活很長時間。"},{"en":"A small shop may not survive long after a large chain opens nearby.","zh":"大型連鎖店在附近開業後，小店可能無法長期存活。"},{"en":"Species may fail to survive long after a new competitor enters their habitat.","zh":"新競爭者進入棲息地後，物種可能無法長期存活。"},{"en":"This phrase connects survival with a later event.","zh":"這個短語把生存與後來事件連接起來。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":15},{"front":"the arrival of immigrants","meaning":"移入者的到來","examples":[{"en":"The arrival of immigrants was followed by the disappearance of Neanderthals.","zh":"移入者的到來之後，尼安德特人消失了。"},{"en":"The arrival of immigrants means the coming of people into a new region from elsewhere.","zh":"arrival of immigrants 是指人們從其他地方進入新地區。"},{"en":"The arrival of immigrants can change language, culture, jobs, and population patterns.","zh":"移入者的到來可以改變語言、文化、工作和人口模式。"},{"en":"In this passage, “immigrants” refers broadly to Homo sapiens entering Neanderthal territory.","zh":"在本文中，immigrants 廣義上指智人進入尼安德特人領地。"},{"en":"This phrase focuses on movement into a place.","zh":"這個短語集中於進入某地的移動。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":15},{"front":"interbreed with","meaning":"與……雜交","examples":[{"en":"Some human species interbred with another species.","zh":"有些人類物種與另一個物種雜交。"},{"en":"To interbreed with another species means to reproduce with it and produce mixed ancestry.","zh":"interbreed with another species 是指與另一物種繁殖並產生混合祖源。"},{"en":"Closely related animal groups may interbreed when their habitats overlap.","zh":"當關係密切的動物群體棲息地重疊時，可能會雜交。"},{"en":"Interbreeding can leave DNA from one group in the descendants of another.","zh":"雜交可以令一個群體的DNA留在另一群體的後代中。"},{"en":"This phrase is used in genetics and evolutionary biology.","zh":"這個短語用於遺傳學和演化生物學。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":15},{"front":"appears not to have passed","meaning":"看來沒有傳給","examples":[{"en":"Neanderthal mitochondrial DNA appears not to have passed to modern humans.","zh":"尼安德特人線粒體DNA看來沒有傳給現代人類。"},{"en":"Appears not to have passed means seems not to have been transmitted or inherited.","zh":"appears not to have passed 是指似乎沒有被傳遞或遺傳下去。"},{"en":"A family name may appear not to have passed to later generations if no children used it.","zh":"如果後代沒有孩子使用某姓氏，該姓氏看來沒有傳下去。"},{"en":"If a DNA type is absent, it may appear not to have passed into a population.","zh":"如果某種DNA缺失，它可能看來沒有傳入某人群。"},{"en":"This phrase is cautious because the evidence suggests, but may not prove, absence.","zh":"這個短語較謹慎，因為證據暗示但未必證明缺失。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":15},{"front":"pass mitochondrial DNA to","meaning":"將線粒體DNA傳給……","examples":[{"en":"One species may pass mitochondrial DNA to another species.","zh":"一個物種可能將線粒體DNA傳給另一物種。"},{"en":"To pass mitochondrial DNA to another group means to transmit maternal-line DNA through reproduction.","zh":"pass mitochondrial DNA to another group 是指透過繁殖傳遞母系DNA。"},{"en":"Mothers pass mitochondrial DNA to their children.","zh":"母親將線粒體DNA傳給子女。"},{"en":"If interbreeding involves female ancestors from one group, mitochondrial DNA may pass to another population.","zh":"如果雜交涉及某群體的女性祖先，線粒體DNA可能傳給另一人群。"},{"en":"This phrase focuses on genetic inheritance through the maternal line.","zh":"這個短語集中於透過母系的基因遺傳。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":15},{"front":"contain the following information","meaning":"包含以下資料","examples":[{"en":"Students identify which paragraph contains the following information.","zh":"學生識別哪一段包含以下資料。"},{"en":"Contain the following information means include the details listed after the instruction.","zh":"contain the following information 是指包括指示後列出的細節。"},{"en":"In reading tests, students scan paragraphs to find which one contains the required information.","zh":"在閱讀測驗中，學生掃讀段落，以找出哪一段包含所需資料。"},{"en":"A paragraph may contain the idea even if it does not repeat the exact words.","zh":"即使段落沒有重複原字，也可能包含該想法。"},{"en":"This phrase is common in paragraph-matching questions.","zh":"這個短語常見於段落配對題。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":15},{"front":"an account of","meaning":"對……的描述","examples":[{"en":"The paragraph gives an account of the rejection of a theory.","zh":"該段給出對某理論被否定的描述。"},{"en":"An account of something is a description or explanation of what happened.","zh":"an account of something 是對所發生事情的描述或解釋。"},{"en":"A witness gave an account of the accident to the police.","zh":"目擊者向警方描述了意外經過。"},{"en":"A history book may give an account of how a revolution began.","zh":"歷史書可能描述一場革命如何開始。"},{"en":"This phrase refers to a narrated explanation, not a bank account.","zh":"這個短語指敘述式解釋，而不是銀行戶口。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":15},{"front":"the rejection of a theory","meaning":"對某理論的否定","examples":[{"en":"The new DNA evidence led to the rejection of an earlier theory.","zh":"新DNA證據導致對早前理論的否定。"},{"en":"The rejection of a theory means deciding that an explanation is no longer supported by evidence.","zh":"rejection of a theory 是指判定某解釋不再受證據支持。"},{"en":"A medical theory may be rejected when repeated tests fail to support it.","zh":"當重複測試未能支持某醫學理論時，該理論可能被否定。"},{"en":"Scientific rejection is normal when better evidence appears.","zh":"當更好證據出現時，科學上的否定是正常的。"},{"en":"This phrase shows that evidence can overturn accepted ideas.","zh":"這個短語顯示證據可以推翻已接受的想法。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":15},{"front":"a reference to","meaning":"對……的提及","examples":[{"en":"The question asks for a reference to an unexplained link between two events.","zh":"題目要求找出對兩件事之間未能解釋關聯的提及。"},{"en":"A reference to something is a mention of it.","zh":"reference to something 是對某事的提及。"},{"en":"An essay may include a reference to a famous speech to support its argument.","zh":"文章可能提及著名演說，以支持其論點。"},{"en":"In reading tasks, students look for where the passage refers to a specific idea.","zh":"在閱讀任務中，學生尋找文章哪裡提到某個特定想法。"},{"en":"This phrase asks for the place where something is mentioned.","zh":"這個短語要求找出某事被提及的位置。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":15},{"front":"an unexplained link between","meaning":"……之間未能解釋的關聯","examples":[{"en":"The text describes an unexplained link between the arrival of Homo sapiens and Neanderthal disappearance.","zh":"文本描述智人的到來與尼安德特人消失之間未能解釋的關聯。"},{"en":"An unexplained link between two events is a connection whose cause is not yet understood.","zh":"unexplained link between two events 是指原因尚未被理解的兩件事之間的連繫。"},{"en":"Doctors may notice an unexplained link between a symptom and a medicine.","zh":"醫生可能注意到某症狀與某藥物之間未能解釋的關聯。"},{"en":"Scientists investigate unexplained links because they may reveal hidden causes.","zh":"科學家調查未能解釋的關聯，因為它們可能揭示隱藏原因。"},{"en":"This phrase shows connection plus uncertainty.","zh":"這個短語同時顯示關聯和不確定性。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":15},{"front":"the identification of","meaning":"對……的識別","examples":[{"en":"The passage includes the identification of a skill-related gene.","zh":"文章包括對一個與技能相關基因的識別。"},{"en":"The identification of something means finding and naming it clearly.","zh":"identification of something 是指清楚找到並命名某事物。"},{"en":"The identification of a disease can help doctors choose treatment.","zh":"對疾病的識別可以幫助醫生選擇治療。"},{"en":"Identifying a gene can be the first step toward understanding its function.","zh":"識別某基因可以是理解其功能的第一步。"},{"en":"This phrase focuses on recognising exactly what something is.","zh":"這個短語集中於準確辨認某事物是甚麼。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":15},{"front":"skill-related gene","meaning":"與技能相關的基因","examples":[{"en":"FOXP2 is a skill-related gene connected with speaking.","zh":"FOXP2是與說話相關的技能相關基因。"},{"en":"A skill-related gene is a gene linked to the development or use of a particular ability.","zh":"skill-related gene 是與某種能力的發展或使用有關的基因。"},{"en":"A gene related to speech may affect how the brain controls mouth movements.","zh":"與說話相關的基因可能影響大腦如何控制口部動作。"},{"en":"Skill-related genes do not work alone; environment and learning also matter.","zh":"與技能相關的基因不會單獨運作；環境和學習也很重要。"},{"en":"This phrase connects genetics with an ability such as speaking.","zh":"這個短語把基因與說話等能力連接起來。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":16},{"front":"common to","meaning":"……所共有","examples":[{"en":"FOXP2 is common to both Neanderthals and modern humans.","zh":"FOXP2為尼安德特人和現代人類所共有。"},{"en":"Common to two groups means found in both groups.","zh":"common to two groups 是指在兩個群體中都存在。"},{"en":"A school rule may be common to all classes.","zh":"一條校規可能為所有班級所共有。"},{"en":"Traits common to related species may come from a shared ancestor.","zh":"相關物種所共有的特徵可能來自共同祖先。"},{"en":"This phrase highlights similarity across groups.","zh":"這個短語強調群體之間的相似性。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":16},{"front":"a scientific breakthrough","meaning":"科學突破","examples":[{"en":"The genome analysis was a scientific breakthrough.","zh":"這項基因組分析是一項科學突破。"},{"en":"A scientific breakthrough is an important discovery that greatly advances knowledge.","zh":"scientific breakthrough 是大幅推進知識的重要發現。"},{"en":"A new treatment can be a scientific breakthrough if it saves many lives.","zh":"如果新治療方法拯救許多生命，它可以是一項科學突破。"},{"en":"Breakthroughs often happen after years of patient work and technical progress.","zh":"突破常在多年耐心工作和技術進步後出現。"},{"en":"This phrase shows that a discovery changes what scientists can understand or do.","zh":"這個短語顯示某發現改變科學家能理解或做到的事。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":16},{"front":"an interesting gap in existing knowledge","meaning":"現有知識中的有趣空白","examples":[{"en":"The absence of Neanderthal mitochondrial DNA is an interesting gap in existing knowledge.","zh":"尼安德特人線粒體DNA的缺失是現有知識中的有趣空白。"},{"en":"An interesting gap in existing knowledge is an unanswered question that stands out within what is already known.","zh":"interesting gap in existing knowledge 是在已知內容中突出的未解問題。"},{"en":"A missing explanation in a medical study can be an interesting gap in knowledge.","zh":"醫學研究中缺少的解釋可以是知識中的有趣空白。"},{"en":"Such gaps encourage researchers to design new studies and collect more evidence.","zh":"這類空白鼓勵研究人員設計新研究並收集更多證據。"},{"en":"This phrase suggests curiosity, not failure.","zh":"這個短語暗示好奇，而不是失敗。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":16},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the short text that follows.","zh":"complete the summary below 是指填補下面短文中的空缺字詞。"},{"en":"In reading exams, students complete summaries by finding words that fit meaning and grammar.","zh":"在閱讀考試中，學生透過找出符合意思和文法的字詞完成摘要。"},{"en":"This task tests both understanding and careful word choice.","zh":"這項任務同時測試理解和仔細選詞。"},{"en":"Students should check the word limit before writing answers.","zh":"學生寫答案前應檢查字數限制。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":16},{"front":"choose no more than three words","meaning":"選擇不超過三個字","examples":[{"en":"Students choose no more than three words from the passage.","zh":"學生從文章中選擇不超過三個字。"},{"en":"Choose no more than three words means the answer must contain three words or fewer.","zh":"choose no more than three words 是指答案必須包含三個字或以下。"},{"en":"If the instruction says no more than three words, a four-word answer is too long.","zh":"如果指示說不超過三個字，四個字答案就太長。"},{"en":"Students should copy only the necessary words from the passage.","zh":"學生應只從文章中抄寫必要字詞。"},{"en":"This phrase tests precision as well as comprehension.","zh":"這個短語既測試準確性，也測試理解力。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":16},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answer must come from the passage.","zh":"答案必須從文章中得來。"},{"en":"From the passage means taken directly from the reading text.","zh":"from the passage 是指直接取自閱讀文本。"},{"en":"In summary-completion tasks, answers from the passage should match the exact wording required.","zh":"在摘要填空題中，從文章中取出的答案應符合所需原字。"},{"en":"Students should not use outside knowledge if the answer must come from the passage.","zh":"如果答案必須來自文章，學生不應使用外部知識。"},{"en":"This phrase limits the source of the answer.","zh":"這個短語限制答案來源。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":16},{"front":"the nature of modern humans","meaning":"現代人類的本質","examples":[{"en":"The summary is about the nature of modern humans.","zh":"摘要關於現代人類的本質。"},{"en":"The nature of modern humans means the basic qualities, origins, and features that define us.","zh":"nature of modern humans 是指定義我們的基本特質、起源和特徵。"},{"en":"Scientists study genes, behaviour, and fossils to understand the nature of modern humans.","zh":"科學家研究基因、行為和化石，以理解現代人類的本質。"},{"en":"Comparing humans with Neanderthals can reveal what is shared and what is unique.","zh":"把人類與尼安德特人比較，可以揭示甚麼是共有、甚麼是獨有。"},{"en":"This phrase asks what modern humans fundamentally are like.","zh":"這個短語詢問現代人類根本上是怎樣的。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":16},{"front":"recent work in","meaning":"……方面的近期研究","examples":[{"en":"Recent work in evolutionary anthropology has changed our understanding.","zh":"演化人類學方面的近期研究改變了我們的理解。"},{"en":"Recent work in a field means new research or studies in that area.","zh":"recent work in a field 是指某領域中的新研究或研究成果。"},{"en":"Recent work in education shows that feedback helps students improve writing.","zh":"教育方面的近期研究顯示回饋幫助學生改善寫作。"},{"en":"Recent scientific work can challenge older explanations.","zh":"近期科學研究可以挑戰舊有解釋。"},{"en":"This phrase points to new research rather than long-established knowledge.","zh":"這個短語指新研究，而不是長期已確立的知識。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":16},{"front":"evolutionary anthropology","meaning":"演化人類學","examples":[{"en":"Evolutionary anthropology studies human origins and development.","zh":"演化人類學研究人類起源和發展。"},{"en":"Evolutionary anthropology is the study of how humans and their relatives evolved over time.","zh":"evolutionary anthropology 是研究人類及其親緣如何隨時間演化的學科。"},{"en":"Researchers in evolutionary anthropology may analyse fossils, DNA, tools, and behaviour.","zh":"演化人類學研究人員可能分析化石、DNA、工具和行為。"},{"en":"This field helps explain similarities and differences among human species.","zh":"這個領域幫助解釋人類物種之間的相似和差異。"},{"en":"It connects biological evidence with questions about what makes humans human.","zh":"它把生物證據與甚麼令人類成為人類的問題連接起來。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":16},{"front":"make it possible to compare","meaning":"使比較……成為可能","examples":[{"en":"Recent research made it possible to compare modern humans with related species.","zh":"近期研究使比較現代人類與相關物種成為可能。"},{"en":"To make it possible to compare means to create the evidence or tools needed for comparison.","zh":"make it possible to compare 是指創造比較所需的證據或工具。"},{"en":"Digital records make it possible to compare student progress across several years.","zh":"數碼記錄使比較學生多年進步成為可能。"},{"en":"Ancient genome analysis makes it possible to compare extinct and living humans.","zh":"古代基因組分析使比較已滅絕和現存人類成為可能。"},{"en":"This phrase shows that a new method opens a new kind of study.","zh":"這個短語顯示新方法打開一種新研究。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":16},{"front":"related species","meaning":"相關物種","examples":[{"en":"Modern humans can be compared with related species.","zh":"現代人類可以與相關物種比較。"},{"en":"Related species are species that share a common evolutionary ancestor.","zh":"related species 是共享共同演化祖先的物種。"},{"en":"Lions and tigers are related species because they belong to the same broader family.","zh":"獅子和老虎是相關物種，因為它們屬於同一較大科。"},{"en":"Comparing related species helps scientists identify shared traits and unique changes.","zh":"比較相關物種幫助科學家識別共有特徵和獨有變化。"},{"en":"This phrase is about evolutionary relationship, not personal family relationship.","zh":"這個短語關於演化關係，而不是個人家庭關係。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":17},{"front":"genetic analysis","meaning":"基因分析","examples":[{"en":"Genetic analysis produced several new findings.","zh":"基因分析得出了數項新發現。"},{"en":"Genetic analysis is the study of DNA to understand inheritance, ancestry, or biological traits.","zh":"genetic analysis 是研究DNA，以理解遺傳、祖源或生物特徵。"},{"en":"Doctors may use genetic analysis to assess inherited disease risk.","zh":"醫生可能使用基因分析評估遺傳疾病風險。"},{"en":"In anthropology, genetic analysis can reveal ancient relationships that bones cannot show clearly.","zh":"在人類學中，基因分析可以揭示骨骼無法清楚顯示的古代關係。"},{"en":"This phrase refers to studying genes as evidence.","zh":"這個短語指把基因作為證據來研究。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":17},{"front":"produce several new findings","meaning":"得出數項新發現","examples":[{"en":"The research produced several new findings about human evolution.","zh":"這項研究得出數項關於人類演化的新發現。"},{"en":"To produce several new findings means to lead to more than one new result or discovery.","zh":"produce several new findings 是指帶來多於一項新結果或發現。"},{"en":"A classroom survey may produce several new findings about how students study.","zh":"課堂調查可能得出數項關於學生如何學習的新發現。"},{"en":"Careful research produces findings when it reveals patterns not known before.","zh":"當仔細研究揭示以前未知的模式時，它會產生發現。"},{"en":"This phrase stresses that the work generated multiple pieces of new knowledge.","zh":"這個短語強調該工作產生多項新知識。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":17},{"front":"despite the length of time","meaning":"儘管時間長久","examples":[{"en":"Despite the length of time separating the two species, interbreeding occurred.","zh":"儘管兩個物種分隔時間長久，雜交仍然發生。"},{"en":"Despite the length of time means although a very long period had passed.","zh":"despite the length of time 是指雖然已經過很長時間。"},{"en":"Despite the length of time since graduation, old classmates still recognised one another.","zh":"儘管畢業後時間長久，舊同學仍認得彼此。"},{"en":"In evolution, a long separation usually makes interbreeding less expected.","zh":"在演化中，長時間分離通常令雜交較不被預期。"},{"en":"This phrase highlights surprise because time did not prevent the result.","zh":"這個短語突出令人驚訝之處，因為時間沒有阻止該結果。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":17},{"front":"develop separately","meaning":"分開發展","examples":[{"en":"Homo sapiens and Homo neanderthalensis developed separately for a long time.","zh":"智人和尼安德特人長時間分開發展。"},{"en":"To develop separately means to grow or evolve apart from another group.","zh":"develop separately 是指與另一群體分開成長或演化。"},{"en":"Two schools may develop separately if they follow different curricula for many years.","zh":"如果兩間學校多年來跟隨不同課程，它們可能分開發展。"},{"en":"Species that develop separately may become different in body, behaviour, and genes.","zh":"分開發展的物種可能在身體、行為和基因上變得不同。"},{"en":"This phrase suggests independent development after separation.","zh":"這個短語暗示分離後的獨立發展。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":17},{"front":"take place","meaning":"發生","examples":[{"en":"Interbreeding did take place between the two species.","zh":"兩個物種之間確實發生了雜交。"},{"en":"To take place means to happen or occur.","zh":"take place 是指發生或出現。"},{"en":"The meeting will take place in the library after school.","zh":"會議將在放學後於圖書館舉行。"},{"en":"Historical changes take place when many causes come together.","zh":"當許多原因結合時，歷史變化會發生。"},{"en":"This phrase simply states that an event happened.","zh":"這個短語只是說明某事件發生了。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":17},{"front":"genes that evolved after","meaning":"在……之後演化的基因","examples":[{"en":"Some genes evolved after modern humans split from Neanderthals.","zh":"有些基因在現代人類與尼安德特人分開之後演化。"},{"en":"Genes that evolved after an event are genes that changed later than that point.","zh":"genes that evolved after an event 是指在該時間點之後發生變化的基因。"},{"en":"Scientists study genes that evolved after species separated to identify unique traits.","zh":"科學家研究物種分開後演化的基因，以識別獨有特徵。"},{"en":"Changes after a split may explain why related species differ.","zh":"分開後的變化可能解釋相關物種為何不同。"},{"en":"This phrase connects genetic change with evolutionary timing.","zh":"這個短語把基因變化與演化時間連接起來。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":17},{"front":"split from","meaning":"與……分開","examples":[{"en":"Modern humans split from Neanderthals in evolutionary history.","zh":"現代人類在演化史中與尼安德特人分開。"},{"en":"To split from another group means to separate from it and develop independently.","zh":"split from another group 是指與另一群體分離並獨立發展。"},{"en":"A company may split from its parent organisation and operate alone.","zh":"公司可能與母公司分開並獨立營運。"},{"en":"Species that split from each other may become more different over time.","zh":"彼此分開的物種可能隨時間變得更不同。"},{"en":"This phrase describes separation, not physical breaking.","zh":"這個短語描述分離，而不是實體斷裂。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":17},{"front":"be connected with","meaning":"與……有關","examples":[{"en":"Some genes are connected with cognitive ability and skeletal development.","zh":"有些基因與認知能力和骨骼發育有關。"},{"en":"To be connected with something means to be linked or related to it.","zh":"be connected with 是指與某事有連繫或關係。"},{"en":"Poor sleep is connected with weak memory and low mood.","zh":"睡眠不足與記憶差和情緒低落有關。"},{"en":"A gene connected with bone growth may affect skull or rib shape.","zh":"與骨骼生長有關的基因可能影響頭骨或肋骨形狀。"},{"en":"This phrase shows relationship, not always direct cause.","zh":"這個短語顯示關係，但不一定是直接因果。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":17},{"front":"skeletal growth","meaning":"骨骼生長","examples":[{"en":"RUNX2 is connected with skeletal growth.","zh":"RUNX2與骨骼生長有關。"},{"en":"Skeletal growth means the development and change of bones in the body.","zh":"skeletal growth 是身體骨骼的發育和變化。"},{"en":"Doctors monitor skeletal growth when children grow unusually slowly or quickly.","zh":"當兒童生長異常慢或快時，醫生會監測骨骼生長。"},{"en":"Genes can influence skeletal growth by affecting how bones form.","zh":"基因可以透過影響骨骼如何形成來影響骨骼生長。"},{"en":"This phrase refers to bone development, not muscle growth.","zh":"這個短語指骨骼發育，而不是肌肉生長。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":17},{"front":"the potential for","meaning":"……的潛力","examples":[{"en":"The potential for this research is considerable.","zh":"這項研究的潛力相當大。"},{"en":"The potential for something means its possible value, effect, or future usefulness.","zh":"potential for something 是指某事可能有的價值、效果或未來用途。"},{"en":"A new teaching app has potential if it helps students practise more often.","zh":"如果新教學應用程式幫助學生更常練習，它就有潛力。"},{"en":"Research has greater potential when it can answer important unanswered questions.","zh":"當研究能回答重要未解問題時，它的潛力更大。"},{"en":"This phrase looks at what something may achieve later.","zh":"這個短語著眼於某事日後可能達成甚麼。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":17},{"front":"shed light on","meaning":"闡明；幫助理解","examples":[{"en":"The research may shed light on modern humans.","zh":"這項研究可能有助理解現代人類。"},{"en":"To shed light on something means to help explain or make it easier to understand.","zh":"shed light on 是指幫助解釋或令某事更容易理解。"},{"en":"Old photographs can shed light on how a neighbourhood changed.","zh":"舊照片可以闡明一個社區如何改變。"},{"en":"Genetic research can shed light on human origins and differences.","zh":"基因研究可以幫助理解人類起源和差異。"},{"en":"This phrase suggests that new evidence makes a topic clearer.","zh":"這個短語暗示新證據令題目更清楚。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":18},{"front":"be strengthened further","meaning":"進一步加強","examples":[{"en":"The potential of the research was strengthened further by a new discovery.","zh":"一項新發現進一步加強了這項研究的潛力。"},{"en":"To be strengthened further means to become even stronger or more convincing.","zh":"be strengthened further 是指變得更強或更具說服力。"},{"en":"A student’s argument is strengthened further when it includes clear evidence.","zh":"當學生論點包含清晰證據時，就會進一步加強。"},{"en":"A theory can be strengthened further if a separate study reaches a similar conclusion.","zh":"如果另一項獨立研究得出相似結論，理論可以進一步加強。"},{"en":"This phrase suggests added support beyond what already existed.","zh":"這個短語暗示在已有基礎上增加支持。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":18},{"front":"analysis of","meaning":"對……的分析","examples":[{"en":"Analysis of a little-finger bone led to a new discovery.","zh":"對小指骨的分析導致一項新發現。"},{"en":"Analysis of something means careful study of it to understand what it shows.","zh":"analysis of something 是指仔細研究某事，以理解它顯示甚麼。"},{"en":"Analysis of exam answers can reveal common student mistakes.","zh":"對考試答案的分析可以揭示學生常見錯誤。"},{"en":"Scientific analysis of a small sample may still produce important results.","zh":"對小樣本的科學分析仍可能產生重要結果。"},{"en":"This phrase refers to careful examination, not casual looking.","zh":"這個短語指仔細檢查，而不是隨便觀看。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":18},{"front":"lead to the discovery of","meaning":"導致……的發現","examples":[{"en":"Analysis of mitochondrial DNA led to the discovery of a new human species.","zh":"對線粒體DNA的分析導致一個新人類物種的發現。"},{"en":"To lead to the discovery of something means to cause researchers to find it.","zh":"lead to the discovery of something 是指使研究人員找到某事物。"},{"en":"A careful search of old records can lead to the discovery of forgotten family history.","zh":"仔細搜尋舊記錄可以導致被遺忘家族歷史的發現。"},{"en":"New technology may lead to discoveries that older methods missed.","zh":"新科技可能導致舊方法錯過的發現。"},{"en":"This phrase connects a method or event with a new finding.","zh":"這個短語把方法或事件與新發現連接起來。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":18},{"front":"a new human species","meaning":"新人類物種","examples":[{"en":"The analysis led to the discovery of a new human species.","zh":"這項分析導致一個新人類物種的發現。"},{"en":"A new human species means a previously unknown kind of human identified by scientific evidence.","zh":"new human species 是指由科學證據識別出的此前未知人類種類。"},{"en":"A new human species can be discovered through fossils, DNA, or both.","zh":"新人類物種可以透過化石、DNA或兩者被發現。"},{"en":"Discovering a new human species can change the family tree of human evolution.","zh":"發現新人類物種可以改變人類演化的家族樹。"},{"en":"This phrase does not mean a modern new type of person; it means an ancient species newly recognised by science.","zh":"這個短語不是指現代的新型人，而是指科學新近識別的古代物種。"}],"source":"116 - Neanderthals and modern humans.pdf","sourcePage":18}],"ielts/reading/passage-2/Practice 117":[{"front":"the dinosaurs’ footprints and extinction","meaning":"恐龍足印與滅絕","examples":[{"en":"The passage discusses the dinosaurs’ footprints and extinction.","zh":"文章討論恐龍足印與滅絕。"},{"en":"The dinosaurs’ footprints and extinction refers to evidence from tracks that helps explain how dinosaurs rose or disappeared.","zh":"恐龍足印與滅絕是指用足跡證據來幫助解釋恐龍如何崛起或消失。"},{"en":"A museum lesson on the dinosaurs’ footprints and extinction may use fossil tracks instead of bones.","zh":"關於恐龍足印與滅絕的博物館課堂，可能使用化石足跡而不是骨骼。"},{"en":"Studying the dinosaurs’ footprints and extinction can show when some animal groups vanished.","zh":"研究恐龍足印與滅絕可以顯示某些動物群體何時消失。"},{"en":"The phrase connects physical traces with a major event in natural history.","zh":"這個片語把實體痕跡與自然史中的重大事件連接起來。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":1},{"front":"everybody knows that","meaning":"人人都知道","examples":[{"en":"Everybody knows that the dinosaurs were killed by an asteroid.","zh":"人人都知道恐龍是被小行星殺死的。"},{"en":"Everybody knows that means something is treated as common knowledge.","zh":"everybody knows that 指某事被視為常識。"},{"en":"Everybody knows that sleep is important, but many students still stay up too late.","zh":"人人都知道睡眠很重要，但許多學生仍然太晚睡。"},{"en":"If everybody knows that a rule exists, breaking it is harder to excuse.","zh":"如果人人都知道某條規則存在，違反它就更難辯解。"},{"en":"The phrase can sound confident, but common belief may still need evidence.","zh":"這個片語聽起來很肯定，但普遍看法仍可能需要證據。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":1},{"front":"be killed by","meaning":"被……殺死","examples":[{"en":"The dinosaurs were killed by an asteroid.","zh":"恐龍被小行星殺死。"},{"en":"Be killed by means die because of a particular cause, person, event, or force.","zh":"be killed by 指因某個原因、人物、事件或力量而死亡。"},{"en":"Several trees were killed by disease after the long wet season.","zh":"長時間雨季後，幾棵樹被疾病殺死。"},{"en":"If fish are killed by pollution, the whole river ecosystem may suffer.","zh":"如果魚被污染殺死，整個河流生態系統可能受害。"},{"en":"The phrase identifies what caused death.","zh":"這個片語指出死亡原因。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":1},{"front":"asteroid","meaning":"小行星","examples":[{"en":"An asteroid may have caused the extinction of the dinosaurs.","zh":"小行星可能造成恐龍滅絕。"},{"en":"An asteroid is a rocky object that moves around the sun and can sometimes strike planets.","zh":"小行星是繞太陽運行的岩石物體，有時可能撞擊行星。"},{"en":"Students may learn about asteroids when studying the solar system.","zh":"學生學習太陽系時可能認識小行星。"},{"en":"If a large asteroid hits Earth, it can cause fires, dust clouds, and climate changes.","zh":"如果大型小行星撞擊地球，可能造成火災、塵雲和氣候變化。"},{"en":"The word refers to a space object, not an ordinary rock on the ground.","zh":"這個詞指太空物體，而不是地上的普通石頭。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":1},{"front":"hit the earth","meaning":"撞擊地球","examples":[{"en":"Something big hit the earth 65 million years ago.","zh":"六千五百萬年前，有大型物體撞擊地球。"},{"en":"Hit the earth means strike the planet with force.","zh":"hit the earth 指以力量撞擊地球。"},{"en":"A meteor may burn up before it can hit the earth.","zh":"流星可能在撞擊地球前已燃燒殆盡。"},{"en":"If a large object hits the earth, the impact can affect land, oceans, and climate.","zh":"如果大型物體撞擊地球，撞擊可影響陸地、海洋和氣候。"},{"en":"The phrase describes a collision with the planet.","zh":"這個片語描述與地球的碰撞。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":1},{"front":"65 million years ago","meaning":"六千五百萬年前","examples":[{"en":"The asteroid hit the earth 65 million years ago.","zh":"小行星在六千五百萬年前撞擊地球。"},{"en":"65 million years ago means a time sixty-five million years before the present.","zh":"65 million years ago 指距今六千五百萬年前。"},{"en":"Fossils help scientists study life from millions of years ago.","zh":"化石幫助科學家研究數百萬年前的生命。"},{"en":"If an event happened 65 million years ago, scientists must use rocks and fossils to investigate it.","zh":"如果事件發生在六千五百萬年前，科學家必須使用岩石和化石調查。"},{"en":"The phrase places the event in deep geological time.","zh":"這個片語把事件放在深遠地質時間中。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":1},{"front":"when the dust had fallen","meaning":"塵埃落定後","examples":[{"en":"When the dust had fallen, the great reptiles had disappeared.","zh":"塵埃落定後，這些大型爬行動物已經消失。"},{"en":"When the dust had fallen means after the confusion, debris, or immediate effects had settled.","zh":"when the dust had fallen 指混亂、碎屑或即時影響平息之後。"},{"en":"After a big school argument, when the dust had fallen, the teachers checked what really happened.","zh":"一場大型校園爭論後，塵埃落定後，老師才查清真正發生了甚麼。"},{"en":"If a disaster occurs, people may understand the full damage only when the dust has fallen.","zh":"如果災難發生，人們可能只有在塵埃落定後才理解全部損害。"},{"en":"The phrase can be literal or figurative.","zh":"這個片語可以是字面意思，也可以是比喻。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":1},{"front":"great reptiles","meaning":"大型爬行動物","examples":[{"en":"The great reptiles disappeared after the impact.","zh":"這些大型爬行動物在撞擊後消失。"},{"en":"Great reptiles refers to large reptile-like animals, especially dinosaurs in this context.","zh":"great reptiles 在此語境指大型爬行類動物，尤其是恐龍。"},{"en":"Children often imagine great reptiles as huge creatures with claws, tails, and heavy bodies.","zh":"孩子常把大型爬行動物想像成有爪、尾巴和沉重身體的巨大生物。"},{"en":"If great reptiles disappeared, smaller animals could later occupy their ecological spaces.","zh":"如果大型爬行動物消失，較小動物日後可能佔據牠們的生態位置。"},{"en":"The phrase gives dinosaurs a grand and ancient feeling.","zh":"這個片語令恐龍帶有宏大而古老的感覺。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":1},{"front":"nice, if ironic, symmetry","meaning":"妙趣而帶諷刺的對稱","examples":[{"en":"There is a nice, if ironic, symmetry in the theory.","zh":"這個理論中有一種妙趣而帶諷刺的對稱。"},{"en":"Nice, if ironic, symmetry means a pleasing balance that is surprising because it involves a twist.","zh":"nice, if ironic, symmetry 指一種令人覺得巧妙的平衡，但因帶有轉折而令人意外。"},{"en":"It has a nice, if ironic, symmetry when a strict teacher later learns from a former student.","zh":"嚴厲老師後來向舊學生學習，這件事有一種妙趣而帶諷刺的對稱。"},{"en":"If the same force helped dinosaurs rise and fall, the theory has ironic symmetry.","zh":"如果同一種力量幫助恐龍崛起又令牠們滅亡，這個理論就有諷刺性的對稱。"},{"en":"The phrase highlights a neat but slightly unexpected pattern.","zh":"這個片語強調整齊但略帶意外的模式。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":1},{"front":"similar impact","meaning":"類似撞擊","examples":[{"en":"A similar impact may have brought about the dinosaurs’ rise.","zh":"類似撞擊可能導致恐龍崛起。"},{"en":"A similar impact means another collision or event of the same kind.","zh":"similar impact 指另一場同類型的撞擊或事件。"},{"en":"A city hit by one storm may prepare better for a similar impact in future.","zh":"被風暴襲擊過的城市，可能為未來類似撞擊作更好準備。"},{"en":"If a similar impact happened earlier, it may have changed life on Earth in another way.","zh":"如果早前發生類似撞擊，它可能以另一方式改變地球生命。"},{"en":"The phrase compares one major event with another.","zh":"這個片語把一個重大事件與另一個相比。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":1},{"front":"bring about","meaning":"導致；帶來","examples":[{"en":"A similar impact may have brought about the dinosaurs’ rise.","zh":"類似撞擊可能導致恐龍崛起。"},{"en":"Bring about means cause something to happen.","zh":"bring about 指造成某事發生。"},{"en":"Better bus services can bring about less traffic if people drive less.","zh":"如果人們少開車，更好的巴士服務可以帶來較少交通擠塞。"},{"en":"A serious accident can bring about new safety rules.","zh":"嚴重意外可以帶來新的安全規則。"},{"en":"The phrase focuses on cause and result.","zh":"這個片語集中於原因和結果。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":2},{"front":"the dinosaurs’ rise","meaning":"恐龍的崛起","examples":[{"en":"Paul Olsen proposed a thesis about the dinosaurs’ rise.","zh":"Paul Olsen 提出了一個關於恐龍崛起的論點。"},{"en":"The dinosaurs’ rise means the process by which dinosaurs became more common and dominant.","zh":"the dinosaurs’ rise 指恐龍變得更普遍並佔據主導地位的過程。"},{"en":"A school project on the dinosaurs’ rise may compare small early dinosaurs with later giants.","zh":"關於恐龍崛起的學校項目可能比較早期小型恐龍與後來巨型恐龍。"},{"en":"If competitors disappeared, the dinosaurs’ rise could have happened more quickly.","zh":"如果競爭者消失，恐龍的崛起可能發生得更快。"},{"en":"The phrase describes growth in importance, not just physical growth.","zh":"這個片語描述重要性的上升，而不只是身體增長。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":2},{"front":"thesis proposed by","meaning":"由……提出的論點","examples":[{"en":"That is the thesis proposed by Paul Olsen and his colleagues.","zh":"那就是 Paul Olsen 和其同事提出的論點。"},{"en":"Thesis proposed by means an argument or main idea put forward by someone.","zh":"thesis proposed by 指某人提出的論點或主要想法。"},{"en":"A thesis proposed by a historian must be supported by documents and evidence.","zh":"歷史學家提出的論點必須由文件和證據支持。"},{"en":"If a thesis is proposed by a research team, other scientists may test it.","zh":"如果研究團隊提出論點，其他科學家可能測試它。"},{"en":"The phrase identifies both the idea and its source.","zh":"這個片語同時指出想法和來源。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":2},{"front":"fossil record","meaning":"化石記錄","examples":[{"en":"Dinosaurs first appeared in the fossil record 230 million years ago.","zh":"恐龍在二億三千萬年前首次出現在化石記錄中。"},{"en":"The fossil record is the collection of fossils that shows what life existed in the past.","zh":"fossil record 是顯示過去生命存在的化石總體。"},{"en":"Scientists use the fossil record to study animals that no longer live today.","zh":"科學家使用化石記錄研究現今不再存在的動物。"},{"en":"If a species disappears from the fossil record, it may suggest extinction or missing evidence.","zh":"如果某物種從化石記錄中消失，可能表示滅絕或證據缺失。"},{"en":"The phrase refers to evidence preserved in rocks.","zh":"這個片語指保存在岩石中的證據。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":2},{"front":"first appeared in","meaning":"首次出現在……","examples":[{"en":"Dinosaurs first appeared in the fossil record during the Triassic period.","zh":"恐龍在三疊紀期間首次出現在化石記錄中。"},{"en":"First appeared in means was seen or recorded for the first time in a particular source or period.","zh":"first appeared in 指首次在某來源或時期中被看見或記錄。"},{"en":"The word first appeared in school reports during the new education reform.","zh":"這個詞在新教育改革期間首次出現在學校報告中。"},{"en":"If an animal first appears in the fossil record at one time, scientists use that date carefully.","zh":"如果某動物在某時間首次出現在化石記錄中，科學家會謹慎使用該日期。"},{"en":"The phrase marks the earliest known evidence.","zh":"這個片語標記最早已知證據。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":2},{"front":"Triassic period","meaning":"三疊紀","examples":[{"en":"Dinosaurs first appeared during the Triassic period.","zh":"恐龍首次出現在三疊紀期間。"},{"en":"The Triassic period is a geological period before the Jurassic period.","zh":"Triassic period 是侏羅紀之前的一個地質時期。"},{"en":"Students studying prehistoric life learn that early dinosaurs lived in the Triassic period.","zh":"學習史前生命的學生會知道早期恐龍生活在三疊紀。"},{"en":"If fossils come from the Triassic period, they are much older than Cretaceous fossils.","zh":"如果化石來自三疊紀，它們比白堊紀化石古老得多。"},{"en":"The phrase identifies a specific era in Earth’s history.","zh":"這個片語指出地球歷史中的特定時代。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":2},{"front":"share the earth with","meaning":"與……共存於地球","examples":[{"en":"Early dinosaurs shared the earth with many other reptiles.","zh":"早期恐龍與許多其他爬行動物共存於地球。"},{"en":"Share the earth with means live on the planet at the same time as other living things.","zh":"share the earth with 指與其他生物在同一時期生活在地球上。"},{"en":"Humans share the earth with plants, insects, birds, and countless microbes.","zh":"人類與植物、昆蟲、鳥類和無數微生物共存於地球。"},{"en":"If one group shares the earth with strong competitors, it may not dominate immediately.","zh":"如果一個群體與強大競爭者共存於地球，它未必立即佔主導。"},{"en":"The phrase highlights coexistence.","zh":"這個片語強調共存。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":2},{"front":"other sorts of reptile","meaning":"其他種類的爬行動物","examples":[{"en":"Dinosaurs shared the earth with lots of other sorts of reptile.","zh":"恐龍與許多其他種類的爬行動物共存於地球。"},{"en":"Other sorts of reptile means other kinds of reptile-like animals.","zh":"other sorts of reptile 指其他類型的爬行類動物。"},{"en":"In a zoo, students may see many sorts of reptiles, such as snakes, turtles, and lizards.","zh":"在動物園中，學生可能看到許多種類的爬行動物，例如蛇、龜和蜥蜴。"},{"en":"If dinosaurs lived with other sorts of reptile, they had competitors and neighbours.","zh":"如果恐龍與其他種類的爬行動物共存，就有競爭者和鄰近物種。"},{"en":"The phrase groups animals broadly rather than naming exact species.","zh":"這個片語概括動物，而不是指出確切物種。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":2},{"front":"the subsequent Jurassic","meaning":"隨後的侏羅紀","examples":[{"en":"Dinosaurs became dominant in the subsequent Jurassic period.","zh":"恐龍在隨後的侏羅紀成為主導。"},{"en":"The subsequent Jurassic means the Jurassic period that came after the Triassic.","zh":"the subsequent Jurassic 指三疊紀之後的侏羅紀。"},{"en":"In history, the subsequent decade may show the results of earlier changes.","zh":"在歷史中，隨後的十年可能顯示早期變化的結果。"},{"en":"If dinosaurs expanded in the subsequent Jurassic, something before it may have opened space for them.","zh":"如果恐龍在隨後的侏羅紀擴張，之前可能有事情為牠們打開空間。"},{"en":"The phrase points to the next period in a sequence.","zh":"這個片語指出序列中的下一個時期。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":2},{"front":"overrun the planet","meaning":"佔據整個星球","examples":[{"en":"Dinosaurs overran the planet during the Jurassic period.","zh":"恐龍在侏羅紀期間佔據整個星球。"},{"en":"Overrun the planet means spread widely and become dominant across much of Earth.","zh":"overrun the planet 指廣泛擴散並在地球大部分地區佔主導。"},{"en":"A weed can overrun a garden if no one removes it.","zh":"如果沒有人清除，雜草可以佔據整個花園。"},{"en":"If one animal group overruns the planet, other groups may lose space and resources.","zh":"如果一個動物群體佔據整個星球，其他群體可能失去空間和資源。"},{"en":"The phrase suggests rapid and widespread expansion.","zh":"這個片語暗示快速而廣泛的擴張。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":2},{"front":"turn into","meaning":"變成","examples":[{"en":"Dinosaurs turned into the monsters shown in popular culture.","zh":"恐龍變成了流行文化中展示的怪獸。"},{"en":"Turn into means change and become something different.","zh":"turn into 指改變並變成另一種東西。"},{"en":"A quiet classroom can turn into a noisy room when the teacher leaves.","zh":"老師離開後，安靜課室可以變成嘈吵房間。"},{"en":"If small early dinosaurs turned into giant forms, their role in ecosystems changed.","zh":"如果早期小型恐龍變成巨型形態，牠們在生態系統中的角色就改變。"},{"en":"The phrase describes transformation.","zh":"這個片語描述轉變。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":3},{"front":"be depicted in","meaning":"被描繪於……","examples":[{"en":"The monsters were depicted in the book and movie Jurassic Park.","zh":"這些怪獸被描繪於《侏羅紀公園》的書和電影中。"},{"en":"Be depicted in means be shown, described, or represented in a work.","zh":"be depicted in 指在作品中被展示、描述或呈現。"},{"en":"A historical figure may be depicted in a film very differently from real life.","zh":"歷史人物在電影中可能被描繪得與現實很不同。"},{"en":"If dinosaurs are depicted in popular media, public imagination may be shaped by those images.","zh":"如果恐龍被描繪於大眾媒體，公眾想像可能受那些影像塑造。"},{"en":"The phrase focuses on representation.","zh":"這個片語集中於呈現方式。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":3},{"front":"Jurassic Park","meaning":"《侏羅紀公園》","examples":[{"en":"The dinosaurs in Jurassic Park were actually from a later period.","zh":"《侏羅紀公園》中的恐龍其實來自較後的時期。"},{"en":"Jurassic Park is a famous book and film title associated with dinosaurs.","zh":"Jurassic Park 是與恐龍有關的著名書名和電影名。"},{"en":"Many students first become interested in dinosaurs after watching Jurassic Park.","zh":"許多學生在觀看《侏羅紀公園》後首次對恐龍產生興趣。"},{"en":"If a film like Jurassic Park mixes periods, viewers may misunderstand dinosaur history.","zh":"如果像《侏羅紀公園》這樣的電影混合不同時期，觀眾可能誤解恐龍歷史。"},{"en":"The phrase names a popular cultural work, not a geological period itself.","zh":"這個片語指一部流行文化作品，而不是地質時期本身。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":3},{"front":"on screen","meaning":"在銀幕上","examples":[{"en":"The dinosaurs that appeared on screen were from the Cretaceous period.","zh":"在銀幕上出現的恐龍來自白堊紀。"},{"en":"On screen means shown in a film, television programme, or digital display.","zh":"on screen 指在電影、電視節目或數碼顯示中出現。"},{"en":"A teacher may show old photographs on screen during a history lesson.","zh":"老師可能在歷史課中於螢幕上展示舊照片。"},{"en":"If animals look frightening on screen, viewers may remember the image more than the facts.","zh":"如果動物在銀幕上看起來可怕，觀眾可能更記得影像而不是事實。"},{"en":"The phrase refers to visual media presentation.","zh":"這個片語指視覺媒體呈現。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":3},{"front":"still more recent","meaning":"更晚近的","examples":[{"en":"The Cretaceous period was still more recent than the Jurassic.","zh":"白堊紀比侏羅紀更晚近。"},{"en":"Still more recent means even later in time than something already mentioned.","zh":"still more recent 指在時間上比已提及事物更晚。"},{"en":"The 1990s are recent compared with the 1800s, but the 2020s are still more recent.","zh":"與十九世紀相比，1990年代較近，但2020年代更晚近。"},{"en":"If a fossil is from a still more recent period, it belongs to a later stage of history.","zh":"如果化石來自更晚近的時期，它屬於較後的歷史階段。"},{"en":"The phrase makes a time comparison stronger.","zh":"這個片語加強時間比較。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":3},{"front":"Cretaceous period","meaning":"白堊紀","examples":[{"en":"Some famous dinosaurs came from the Cretaceous period.","zh":"一些著名恐龍來自白堊紀。"},{"en":"The Cretaceous period is a geological period after the Jurassic and before the dinosaurs’ extinction.","zh":"Cretaceous period 是侏羅紀之後、恐龍滅絕之前的地質時期。"},{"en":"Tyrannosaurus is often linked with the Cretaceous period, not the early Jurassic.","zh":"暴龍常與白堊紀相關，而不是早期侏羅紀。"},{"en":"If a fossil is dated to the Cretaceous period, it belongs to a late dinosaur age.","zh":"如果化石被定年為白堊紀，它就屬於恐龍時代後期。"},{"en":"The phrase names a specific time in Earth history.","zh":"這個片語指出地球歷史中的特定時期。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":3},{"front":"inherit the earth","meaning":"繼承地球；成為地球主宰","examples":[{"en":"Some scientists suggest that dinosaurs inherited the earth after an asteroid strike.","zh":"有些科學家認為恐龍在小行星撞擊後繼承地球。"},{"en":"Inherit the earth means become the dominant group after others disappear or weaken.","zh":"inherit the earth 指在其他群體消失或變弱後成為主導群體。"},{"en":"After an old company closes, smaller competitors may inherit the market.","zh":"舊公司倒閉後，較小競爭者可能繼承市場。"},{"en":"If dinosaurs inherited the earth, they gained ecological space left by other reptiles.","zh":"如果恐龍繼承地球，牠們就取得其他爬行動物留下的生態空間。"},{"en":"The phrase is metaphorical and suggests taking over.","zh":"這個片語是比喻，暗示接管。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":3},{"front":"as the result of","meaning":"作為……的結果","examples":[{"en":"Dinosaurs may have inherited the earth as the result of an asteroid strike.","zh":"恐龍可能作為小行星撞擊的結果而繼承地球。"},{"en":"As the result of means because of something that happened.","zh":"as the result of 指因某事發生而造成。"},{"en":"The match was cancelled as the result of heavy rain.","zh":"比賽作為大雨的結果被取消。"},{"en":"If animal groups disappear as the result of disaster, survivors may expand quickly.","zh":"如果動物群體作為災難的結果消失，倖存者可能迅速擴張。"},{"en":"The phrase links an outcome to its cause.","zh":"這個片語把結果與原因連接起來。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":3},{"front":"asteroid strike","meaning":"小行星撞擊","examples":[{"en":"An asteroid strike may have helped dinosaurs become dominant.","zh":"小行星撞擊可能幫助恐龍成為主導。"},{"en":"An asteroid strike is a collision in which an asteroid hits a planet or moon.","zh":"asteroid strike 是小行星撞擊行星或月球的碰撞事件。"},{"en":"Scientists look for craters when they study evidence of an asteroid strike.","zh":"科學家研究小行星撞擊證據時會尋找隕石坑。"},{"en":"If an asteroid strike throws dust into the sky, climate can change for years.","zh":"如果小行星撞擊把塵埃拋入天空，氣候可能改變多年。"},{"en":"The phrase describes a violent event from space.","zh":"這個片語描述來自太空的猛烈事件。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":3},{"front":"show that","meaning":"顯示；證明","examples":[{"en":"Olsen’s team tried to show that the takeover happened quickly.","zh":"Olsen 的團隊試圖顯示接管發生得很快。"},{"en":"Show that means provide evidence or explanation proving a point.","zh":"show that 指提供證據或解釋來證明某觀點。"},{"en":"A graph can show that sales increased after advertising began.","zh":"圖表可以顯示廣告開始後銷售上升。"},{"en":"If fossils show that a change happened quickly, scientists may look for a sudden cause.","zh":"如果化石顯示變化發生得很快，科學家可能尋找突然原因。"},{"en":"The phrase introduces what evidence is meant to prove.","zh":"這個片語引出證據想證明的內容。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":3},{"front":"the takeover","meaning":"接管；佔據主導","examples":[{"en":"The takeover happened in a geological eyeblink.","zh":"這次接管在地質時間上的一瞬間發生。"},{"en":"The takeover means one group becoming dominant and replacing others.","zh":"the takeover 指一個群體成為主導並取代其他群體。"},{"en":"A new supermarket’s takeover of a small town market may hurt local shops.","zh":"新超市接管小鎮市場，可能傷害本地小店。"},{"en":"If dinosaurs completed the takeover quickly, the ecosystem changed in a short time.","zh":"如果恐龍迅速完成接管，生態系統就在短時間內改變。"},{"en":"The phrase suggests gaining control or dominance.","zh":"這個片語暗示取得控制或主導地位。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":4},{"front":"did, indeed, happen","meaning":"確實發生","examples":[{"en":"The takeover did, indeed, happen very quickly.","zh":"這次接管確實非常迅速地發生。"},{"en":"Did, indeed, happen means really happened, with emphasis added.","zh":"did, indeed, happen 指確實發生，並帶有強調。"},{"en":"The promised repair did, indeed, happen after many complaints.","zh":"經過多次投訴後，承諾的維修確實發生了。"},{"en":"If a sudden extinction did, indeed, happen, scientists need strong evidence for it.","zh":"如果突然滅絕確實發生，科學家需要強有力證據。"},{"en":"The phrase stresses that the event was real, not just suggested.","zh":"這個片語強調事件是真實的，而不只是被提出。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":4},{"front":"geological eyeblink","meaning":"地質時間上的一瞬間","examples":[{"en":"The takeover happened in a geological eyeblink.","zh":"這次接管發生在地質時間上的一瞬間。"},{"en":"A geological eyeblink is a very short time when measured against Earth’s long history.","zh":"geological eyeblink 指相對於地球漫長歷史而言非常短的時間。"},{"en":"Ten thousand years may seem long to humans but can be a geological eyeblink.","zh":"一萬年對人類而言可能很長，但可以是地質時間上的一瞬間。"},{"en":"If a species changes in a geological eyeblink, scientists may suspect a sudden event.","zh":"如果物種在地質時間上的一瞬間改變，科學家可能懷疑有突然事件。"},{"en":"The phrase compares deep time with an instant.","zh":"這個片語把深遠時間與瞬間作比較。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":4},{"front":"dinosaur skeletons","meaning":"恐龍骨骼","examples":[{"en":"Dinosaur skeletons are rare.","zh":"恐龍骨骼很罕見。"},{"en":"Dinosaur skeletons are fossilised bones that show the body structure of dinosaurs.","zh":"dinosaur skeletons 是顯示恐龍身體結構的化石骨頭。"},{"en":"A museum may display dinosaur skeletons to help visitors imagine their size.","zh":"博物館可能展示恐龍骨骼，幫助訪客想像牠們的大小。"},{"en":"Because dinosaur skeletons are rare, scientists also study footprints and other traces.","zh":"因為恐龍骨骼很罕見，科學家也研究足印和其他痕跡。"},{"en":"The phrase refers to preserved bones, not living animals.","zh":"這個片語指保存下來的骨頭，而不是活生物。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":4},{"front":"surprisingly abundant","meaning":"出乎意料地豐富","examples":[{"en":"Dinosaur footprints are surprisingly abundant.","zh":"恐龍足印出乎意料地豐富。"},{"en":"Surprisingly abundant means more common or plentiful than expected.","zh":"surprisingly abundant 指比預期更常見或更多。"},{"en":"After the rain, mushrooms were surprisingly abundant in the park.","zh":"下雨後，公園裏的蘑菇出乎意料地豐富。"},{"en":"If footprints are surprisingly abundant, they can provide more evidence than rare bones.","zh":"如果足印出乎意料地豐富，它們可提供比罕見骨頭更多的證據。"},{"en":"The phrase highlights an unexpected large amount.","zh":"這個片語強調意料之外的大量。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":4},{"front":"footprints","meaning":"足印","examples":[{"en":"Dinosaur footprints can provide important evidence.","zh":"恐龍足印可以提供重要證據。"},{"en":"Footprints are marks left on a surface by feet.","zh":"footprints 是腳在表面留下的痕跡。"},{"en":"Wet sand on a beach can record footprints for a short time.","zh":"海灘上的濕沙可以短暫記錄足印。"},{"en":"If footprints become fossilised, they can show where animals walked long ago.","zh":"如果足印變成化石，它們可以顯示很久以前動物走過哪裡。"},{"en":"The word refers to tracks, not the foot itself.","zh":"這個詞指足跡，而不是腳本身。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":4},{"front":"as good an indication of…as…","meaning":"與……一樣能很好顯示……","examples":[{"en":"The sizes of the prints are as good an indication of body size as skeletons.","zh":"足印大小與骨骼一樣能很好顯示身體大小。"},{"en":"As good an indication of something as another thing means equally useful for showing it.","zh":"as good an indication of something as another thing 指與另一事物同樣能顯示某事。"},{"en":"A student’s daily homework may be as good an indication of effort as exam marks.","zh":"學生日常功課可能與考試分數一樣能很好顯示努力程度。"},{"en":"If footprints are as good an indication of size as bones, scientists can use them confidently.","zh":"如果足印與骨頭一樣能很好顯示體型，科學家就可有信心使用它們。"},{"en":"The phrase compares two sources of evidence.","zh":"這個片語比較兩種證據來源。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":4},{"front":"the sizes of the beasts","meaning":"這些巨獸的體型","examples":[{"en":"The sizes of the prints show the sizes of the beasts.","zh":"足印的大小顯示這些巨獸的體型。"},{"en":"The sizes of the beasts means how large the animals were.","zh":"the sizes of the beasts 指這些動物有多大。"},{"en":"Zoo signs often show the sizes of the beasts so children can compare animals.","zh":"動物園標示常顯示巨獸的體型，讓孩子比較動物。"},{"en":"If footprints are large, scientists may infer the sizes of the beasts that made them.","zh":"如果足印很大，科學家可能推斷留下足印的巨獸體型。"},{"en":"The phrase sounds dramatic and often refers to large ancient animals.","zh":"這個片語語氣較戲劇化，常指大型古代動物。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":4},{"front":"concentrated on","meaning":"集中研究","examples":[{"en":"The researchers concentrated on prints, not bones.","zh":"研究人員集中研究足印，而不是骨頭。"},{"en":"Concentrated on means focused attention and effort on one subject.","zh":"concentrated on 指把注意力和努力集中在一個主題上。"},{"en":"A student may concentrate on grammar before improving essay style.","zh":"學生可能先集中研究文法，再改善作文風格。"},{"en":"If researchers concentrate on footprints, they may notice patterns missed in skeletons.","zh":"如果研究人員集中研究足印，可能注意到骨骼中看不到的模式。"},{"en":"The phrase shows the main focus of study or work.","zh":"這個片語顯示研究或工作的主要焦點。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":4},{"front":"prints, not bones","meaning":"足印，而不是骨頭","examples":[{"en":"The team studied prints, not bones.","zh":"團隊研究足印，而不是骨頭。"},{"en":"Prints, not bones means footprints were used as evidence instead of skeletons.","zh":"prints, not bones 指使用足印作證據，而不是骨骼。"},{"en":"In a muddy field, a tracker may study prints, not the animal itself.","zh":"在泥地中，追蹤者可能研究足印，而不是動物本身。"},{"en":"If bones are rare, studying prints, not bones, can still reveal animal size and movement.","zh":"如果骨頭罕見，研究足印而不是骨頭仍可揭示動物大小和行動。"},{"en":"The phrase creates a clear contrast between two evidence types.","zh":"這個片語在兩種證據之間形成清楚對比。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":4},{"front":"the prints in question","meaning":"相關足印","examples":[{"en":"The prints in question were made in eastern North America.","zh":"相關足印是在北美洲東部形成的。"},{"en":"The prints in question means the particular footprints being discussed.","zh":"the prints in question 指正在討論的特定足印。"},{"en":"The document in question was found in the school office yesterday.","zh":"相關文件昨天在校務處被找到。"},{"en":"If the prints in question are from one region, conclusions may focus on that area.","zh":"如果相關足印來自一個地區，結論可能集中於該地。"},{"en":"The phrase identifies the specific item under discussion.","zh":"這個片語指出正在討論的特定事物。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":5},{"front":"eastern North America","meaning":"北美洲東部","examples":[{"en":"The dinosaur prints were found in eastern North America.","zh":"恐龍足印在北美洲東部被發現。"},{"en":"Eastern North America refers to the eastern part of the North American continent.","zh":"eastern North America 指北美洲大陸東部。"},{"en":"Many old cities and forests are found in eastern North America.","zh":"北美洲東部有許多古老城市和森林。"},{"en":"If fossils are found in eastern North America, scientists study the region’s ancient environment.","zh":"如果化石在北美洲東部被發現，科學家會研究該地區的古環境。"},{"en":"The phrase identifies a broad geographical area.","zh":"這個片語指出廣闊地理區域。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":5},{"front":"a part of the world","meaning":"世界的一個地區","examples":[{"en":"Eastern North America was then a part of the world full of rift valleys.","zh":"北美洲東部當時是世界上一個充滿裂谷的地區。"},{"en":"A part of the world means a particular region or area on Earth.","zh":"a part of the world 指地球上的某個地區或區域。"},{"en":"In some parts of the world, children walk long distances to school.","zh":"在世界某些地區，孩子要走很遠上學。"},{"en":"If a part of the world has many lakes, it may preserve different fossils.","zh":"如果世界某個地區有許多湖泊，它可能保存不同化石。"},{"en":"The phrase is a general way to identify a region.","zh":"這個片語是指出地區的一般說法。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":5},{"front":"rift valleys","meaning":"裂谷","examples":[{"en":"The region was full of rift valleys.","zh":"該地區充滿裂谷。"},{"en":"Rift valleys are long low areas formed when Earth’s crust pulls apart.","zh":"rift valleys 是地殼拉開時形成的狹長低地。"},{"en":"Geography students may study rift valleys in East Africa.","zh":"地理學生可能研究東非裂谷。"},{"en":"If rift valleys contain lakes, sediments there can preserve ancient tracks.","zh":"如果裂谷含有湖泊，那裡的沉積物可以保存古代足跡。"},{"en":"The phrase refers to a geological landform.","zh":"這個片語指一種地質地貌。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":5},{"front":"similar to","meaning":"與……相似","examples":[{"en":"The ancient rift valleys were similar to those in East Africa today.","zh":"古代裂谷與今日東非的裂谷相似。"},{"en":"Similar to means like something else in important ways.","zh":"similar to 指在重要方面與另一事物相像。"},{"en":"This school system is similar to the one used in nearby cities.","zh":"這個學校制度與附近城市使用的制度相似。"},{"en":"If ancient valleys were similar to modern ones, scientists can use modern examples for comparison.","zh":"如果古代谷地與現代谷地相似，科學家可以用現代例子作比較。"},{"en":"The phrase shows resemblance, not exact sameness.","zh":"這個片語表示相似，而不是完全相同。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":5},{"front":"contain lakes","meaning":"含有湖泊","examples":[{"en":"The rift valleys contained lakes.","zh":"這些裂谷含有湖泊。"},{"en":"Contain lakes means have lakes inside a region or landform.","zh":"contain lakes 指一個地區或地貌內有湖泊。"},{"en":"Some national parks contain lakes where visitors can walk or boat.","zh":"有些國家公園含有湖泊，遊客可以散步或划船。"},{"en":"If valleys contain lakes, mud around the edges may record footprints.","zh":"如果谷地含有湖泊，湖邊泥土可能記錄足印。"},{"en":"The phrase describes what exists within a place.","zh":"這個片語描述某地內部存在甚麼。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":5},{"front":"grow and shrink","meaning":"擴大和縮小","examples":[{"en":"The lakes grew and shrank at regular intervals.","zh":"這些湖泊每隔固定時間擴大和縮小。"},{"en":"Grow and shrink means increase and decrease in size over time.","zh":"grow and shrink 指隨時間增加和減少大小。"},{"en":"A school club may grow and shrink depending on student interest each year.","zh":"學校學會可能每年根據學生興趣擴大和縮小。"},{"en":"If lakes grow and shrink repeatedly, they leave layers of sediment behind.","zh":"如果湖泊反覆擴大和縮小，它們會留下沉積層。"},{"en":"The phrase describes repeated expansion and reduction.","zh":"這個片語描述反覆擴張和收縮。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":5},{"front":"at regular intervals","meaning":"每隔固定時間","examples":[{"en":"The lakes grew and shrank at regular intervals.","zh":"這些湖泊每隔固定時間擴大和縮小。"},{"en":"At regular intervals means repeatedly after equal or predictable periods of time.","zh":"at regular intervals 指每隔相等或可預測的時間反覆發生。"},{"en":"The school bell rings at regular intervals during the day.","zh":"學校鐘聲在一天中每隔固定時間響起。"},{"en":"If climate changes happen at regular intervals, scientists can use them to date rocks.","zh":"如果氣候變化每隔固定時間發生，科學家可以用它們為岩石定年。"},{"en":"The phrase highlights a repeated pattern.","zh":"這個片語強調重複模式。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":5},{"front":"climatic changes","meaning":"氣候變化","examples":[{"en":"Climatic changes affected the size of the lakes.","zh":"氣候變化影響湖泊大小。"},{"en":"Climatic changes are changes in weather patterns over long periods.","zh":"climatic changes 是長期天氣模式的變化。"},{"en":"Farmers notice climatic changes when rainfall becomes less predictable over many years.","zh":"當多年來降雨變得較難預測時，農民會注意到氣候變化。"},{"en":"If climatic changes make lakes drier, shorelines may move and expose new sediments.","zh":"如果氣候變化令湖泊變乾，湖岸線可能移動並露出新沉積物。"},{"en":"The phrase refers to climate, not just one day’s weather.","zh":"這個片語指氣候，而不是一天的天氣。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":5},{"front":"caused by","meaning":"由……造成","examples":[{"en":"The climatic changes were caused by shifts in the earth’s orbit.","zh":"這些氣候變化由地球軌道轉變造成。"},{"en":"Caused by means produced or brought about by something.","zh":"caused by 指由某事產生或導致。"},{"en":"The delay was caused by a broken traffic light.","zh":"延誤由交通燈故障造成。"},{"en":"If lake changes are caused by climate, researchers look for repeated environmental patterns.","zh":"如果湖泊變化由氣候造成，研究人員會尋找重複環境模式。"},{"en":"The phrase identifies the reason something happened.","zh":"這個片語指出某事發生的原因。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":5},{"front":"periodic shifts","meaning":"周期性轉變","examples":[{"en":"Periodic shifts in the earth’s orbit caused climatic changes.","zh":"地球軌道的周期性轉變造成氣候變化。"},{"en":"Periodic shifts are changes that happen again and again at intervals.","zh":"periodic shifts 是每隔一段時間反覆發生的變化。"},{"en":"Periodic shifts in student numbers can make schools plan classrooms differently.","zh":"學生人數的周期性轉變可以令學校以不同方式規劃課室。"},{"en":"If periodic shifts affect climate, their timing can help date geological layers.","zh":"如果周期性轉變影響氣候，其時間可幫助為地質層定年。"},{"en":"The phrase highlights repeated changes, not random ones.","zh":"這個片語強調重複變化，而不是隨機變化。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":6},{"front":"the earth’s orbit","meaning":"地球軌道","examples":[{"en":"Periodic shifts in the earth’s orbit affected climate.","zh":"地球軌道的周期性轉變影響氣候。"},{"en":"The earth’s orbit is the path Earth follows around the sun.","zh":"the earth’s orbit 是地球繞太陽運行的路徑。"},{"en":"Science classes explain that the earth’s orbit helps shape seasons and climate patterns.","zh":"科學課解釋地球軌道如何幫助形成季節和氣候模式。"},{"en":"If the earth’s orbit changes slightly, sunlight patterns can change over long periods.","zh":"如果地球軌道稍有改變，陽光模式可能在長期中改變。"},{"en":"The phrase refers to planetary movement.","zh":"這個片語指行星運動。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":6},{"front":"a similar phenomenon","meaning":"類似現象","examples":[{"en":"A similar phenomenon is responsible for modern ice ages.","zh":"類似現象是現代冰河時期的成因。"},{"en":"A similar phenomenon means a similar event, process, or pattern.","zh":"a similar phenomenon 指相似的事件、過程或模式。"},{"en":"A rise in online shopping and a similar phenomenon in food delivery both changed city streets.","zh":"網上購物增長和外賣送遞中的類似現象，都改變了城市街道。"},{"en":"If a similar phenomenon explains two events, scientists may compare their causes.","zh":"如果類似現象解釋兩個事件，科學家可能比較其原因。"},{"en":"The phrase links one pattern to another.","zh":"這個片語把一種模式與另一種連接起來。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":6},{"front":"be responsible for","meaning":"是……的成因","examples":[{"en":"A similar phenomenon is responsible for modern ice ages.","zh":"類似現象是現代冰河時期的成因。"},{"en":"Be responsible for means be the cause of something.","zh":"be responsible for 指是某事的原因。"},{"en":"Poor drainage may be responsible for flooding after heavy rain.","zh":"排水不良可能是大雨後水浸的成因。"},{"en":"If orbital changes are responsible for climate cycles, they leave repeated geological signs.","zh":"如果軌道變化是氣候周期的成因，它們會留下重複地質跡象。"},{"en":"The phrase identifies causal responsibility.","zh":"這個片語指出因果責任。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":6},{"front":"modern ice ages","meaning":"現代冰河時期","examples":[{"en":"Periodic orbital changes are linked to modern ice ages.","zh":"周期性軌道變化與現代冰河時期有關。"},{"en":"Modern ice ages are relatively recent geological periods when large ice sheets expanded.","zh":"modern ice ages 是相對近期的大冰蓋擴張地質時期。"},{"en":"Students study modern ice ages to understand long-term climate change.","zh":"學生研究現代冰河時期，以理解長期氣候變化。"},{"en":"If orbital cycles influence modern ice ages, climate can be affected by astronomy.","zh":"如果軌道周期影響現代冰河時期，氣候就可受天文因素影響。"},{"en":"The phrase refers to geological cold periods, not ordinary winters.","zh":"這個片語指地質寒冷時期，而不是普通冬天。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":6},{"front":"combined with","meaning":"與……結合","examples":[{"en":"That regularity, combined with magnetic reversals, helps date the rocks.","zh":"那種規律性與磁場逆轉結合，有助為岩石定年。"},{"en":"Combined with means together with another factor.","zh":"combined with 指與另一因素一起。"},{"en":"Regular study, combined with feedback, can improve exam writing.","zh":"定期學習與回饋結合，可以改善考試寫作。"},{"en":"If lake cycles are combined with magnetic evidence, dating can become more accurate.","zh":"如果湖泊周期與磁場證據結合，定年可以更準確。"},{"en":"The phrase shows that two things work together.","zh":"這個片語顯示兩件事共同作用。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":6},{"front":"reversals in the earth’s magnetic field","meaning":"地球磁場逆轉","examples":[{"en":"Reversals in the earth’s magnetic field can help date rocks.","zh":"地球磁場逆轉可以幫助為岩石定年。"},{"en":"Reversals in the earth’s magnetic field are changes in which Earth’s magnetic north and south switch positions.","zh":"reversals in the earth’s magnetic field 是地球磁北和磁南位置互換的變化。"},{"en":"Geology students learn that magnetic reversals can be recorded in rocks.","zh":"地質學生會學到磁場逆轉可以被記錄在岩石中。"},{"en":"If rocks preserve magnetic reversals, scientists can compare them with known timelines.","zh":"如果岩石保存磁場逆轉，科學家可以把它們與已知時間線比較。"},{"en":"The phrase describes a major change in Earth’s magnetism.","zh":"這個片語描述地球磁性的重大變化。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":6},{"front":"magnetic field","meaning":"磁場","examples":[{"en":"The earth’s magnetic field has reversed in the past.","zh":"地球磁場在過去曾經逆轉。"},{"en":"A magnetic field is an invisible area of magnetic force around an object or planet.","zh":"magnetic field 是物體或行星周圍看不見的磁力範圍。"},{"en":"A compass works because it responds to Earth’s magnetic field.","zh":"指南針能運作，是因為它會回應地球磁場。"},{"en":"If the magnetic field changes, some minerals can record the change as they form.","zh":"如果磁場改變，有些礦物在形成時可以記錄該變化。"},{"en":"The phrase refers to magnetism, not gravity.","zh":"這個片語指磁性，而不是重力。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":6},{"front":"be detectable in","meaning":"可在……中被探測到","examples":[{"en":"Magnetic reversals are detectable in certain minerals.","zh":"磁場逆轉可在某些礦物中被探測到。"},{"en":"Be detectable in means be possible to find or observe inside something.","zh":"be detectable in 指可在某物中被發現或觀察到。"},{"en":"Tiny cracks may be detectable in a wall only after close inspection.","zh":"細小裂縫可能只有在仔細檢查後才可在牆中被探測到。"},{"en":"If magnetic changes are detectable in minerals, rocks can preserve ancient information.","zh":"如果磁場變化可在礦物中被探測到，岩石就能保存古代資訊。"},{"en":"The phrase focuses on evidence that can be found.","zh":"這個片語集中於可被找到的證據。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":6},{"front":"magnetic minerals","meaning":"磁性礦物","examples":[{"en":"Certain magnetic minerals record changes in the earth’s magnetic field.","zh":"某些磁性礦物記錄地球磁場的變化。"},{"en":"Magnetic minerals are minerals that respond to or preserve magnetic information.","zh":"magnetic minerals 是會回應或保存磁性資訊的礦物。"},{"en":"Scientists may test magnetic minerals to study ancient rocks.","zh":"科學家可能測試磁性礦物來研究古代岩石。"},{"en":"If magnetic minerals form during a reversal, they can record the field direction at that time.","zh":"如果磁性礦物在逆轉期間形成，它們可以記錄當時磁場方向。"},{"en":"The phrase refers to minerals useful for geological evidence.","zh":"這個片語指對地質證據有用的礦物。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":6},{"front":"be dated to within","meaning":"可精確定年到……之內","examples":[{"en":"The rocks can be dated to within a few thousand years.","zh":"這些岩石可精確定年到幾千年之內。"},{"en":"Be dated to within means have an age estimated with a particular margin of error.","zh":"be dated to within 指年齡可在某個誤差範圍內被估算。"},{"en":"An old document may be dated to within ten years by handwriting and paper evidence.","zh":"舊文件可透過筆跡和紙張證據精確定年到十年之內。"},{"en":"If rocks can be dated to within a few thousand years, scientists can compare events closely.","zh":"如果岩石可精確定年到幾千年之內，科學家就能更仔細比較事件。"},{"en":"The phrase describes dating precision.","zh":"這個片語描述定年精確度。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":7},{"front":"a few thousand years","meaning":"幾千年","examples":[{"en":"The rocks can be dated to within a few thousand years.","zh":"這些岩石可精確定年到幾千年之內。"},{"en":"A few thousand years means several thousand years, usually a small amount in geological time.","zh":"a few thousand years 指數千年，在地質時間中通常是較短時間。"},{"en":"A few thousand years is long for human history but short for dinosaur history.","zh":"幾千年對人類歷史很長，但對恐龍歷史很短。"},{"en":"If dating is accurate to a few thousand years, it is quite precise for ancient rocks.","zh":"如果定年可準確到幾千年，對古代岩石而言已相當精確。"},{"en":"The phrase gives an approximate time range.","zh":"這個片語給出大約時間範圍。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":7},{"front":"as a bonus","meaning":"額外好處是","examples":[{"en":"As a bonus, lake-edge sediments can record animal tracks.","zh":"額外好處是，湖邊沉積物可以記錄動物足跡。"},{"en":"As a bonus means as an extra advantage in addition to the main benefit.","zh":"as a bonus 指除了主要好處外，還有額外優點。"},{"en":"The flat is near school, and as a bonus, it has a quiet study room.","zh":"這個單位靠近學校，額外好處是有安靜自修室。"},{"en":"If sediments help date rocks and also record tracks, the tracks are a scientific bonus.","zh":"如果沉積物既能幫助定年，又能記錄足跡，這些足跡就是科學上的額外好處。"},{"en":"The phrase introduces an additional positive point.","zh":"這個片語引出額外正面重點。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":7},{"front":"squishy lake-edge sediments","meaning":"柔軟的湖邊沉積物","examples":[{"en":"Squishy lake-edge sediments are good for recording tracks.","zh":"柔軟的湖邊沉積物很適合記錄足跡。"},{"en":"Squishy lake-edge sediments are soft wet layers of mud or sand near a lake shore.","zh":"squishy lake-edge sediments 是湖岸附近柔軟潮濕的泥或沙層。"},{"en":"Children can leave footprints in squishy mud beside a pond after rain.","zh":"下雨後，孩子可以在池塘旁柔軟泥地留下足印。"},{"en":"If animals walk across squishy lake-edge sediments, their tracks may be preserved.","zh":"如果動物走過柔軟湖邊沉積物，其足跡可能被保存。"},{"en":"The phrase describes the soft material that can capture footprints.","zh":"這個片語描述能捕捉足印的柔軟物質。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":7},{"front":"record the tracks of","meaning":"記錄……的足跡","examples":[{"en":"The sediments recorded the tracks of passing animals.","zh":"這些沉積物記錄了路過動物的足跡。"},{"en":"Record the tracks of means preserve or show the footprints left by moving animals.","zh":"record the tracks of 指保存或顯示移動動物留下的足印。"},{"en":"Wet cement can record the tracks of a dog that walks across it.","zh":"濕水泥可以記錄走過的狗的足跡。"},{"en":"If mud records the tracks of animals, scientists can study their movement later.","zh":"如果泥土記錄動物足跡，科學家日後可以研究牠們的移動。"},{"en":"The phrase shows how surfaces keep evidence of movement.","zh":"這個片語顯示表面如何保留移動證據。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":7},{"front":"passing animals","meaning":"路過的動物","examples":[{"en":"The tracks were left by passing animals.","zh":"這些足跡由路過的動物留下。"},{"en":"Passing animals are animals that moved through an area without staying there permanently.","zh":"passing animals 是經過某地而沒有永久停留的動物。"},{"en":"A garden may show signs of passing animals, such as paw prints or disturbed soil.","zh":"花園可能顯示路過動物的跡象，例如爪印或被翻動的泥土。"},{"en":"If passing animals leave tracks, researchers can learn what visited the area.","zh":"如果路過的動物留下足跡，研究人員可以知道甚麼動物曾到訪該地。"},{"en":"The phrase focuses on animals moving through a place.","zh":"這個片語集中於經過某地的動物。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":7},{"front":"divide the labour between","meaning":"在……之間分工","examples":[{"en":"The ten authors divided the labour between themselves.","zh":"十位作者在彼此之間分工。"},{"en":"Divide the labour between means share different tasks among people.","zh":"divide the labour between 指在人與人之間分配不同任務。"},{"en":"Students can divide the labour between group members when preparing a presentation.","zh":"學生準備匯報時，可以在組員之間分工。"},{"en":"If researchers divide the labour well, a large project becomes easier to finish.","zh":"如果研究人員妥善分工，大型項目就更容易完成。"},{"en":"The phrase describes organised teamwork.","zh":"這個片語描述有組織的團隊合作。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":7},{"front":"study such tracks","meaning":"研究這類足跡","examples":[{"en":"The researchers were able to study such tracks at 80 sites.","zh":"研究人員能夠在80個地點研究這類足跡。"},{"en":"Study such tracks means examine footprints of this kind carefully.","zh":"study such tracks 指仔細檢查這類足印。"},{"en":"A wildlife worker may study such tracks to identify animals in a forest.","zh":"野生動物工作者可能研究這類足跡，以識別森林中的動物。"},{"en":"If scientists study such tracks across many sites, they can see wider patterns.","zh":"如果科學家在許多地點研究這類足跡，就能看見更廣泛模式。"},{"en":"The phrase refers to analysing trace evidence.","zh":"這個片語指分析痕跡證據。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":7},{"front":"80 sites","meaning":"80個地點","examples":[{"en":"The researchers studied tracks at 80 sites.","zh":"研究人員在80個地點研究足跡。"},{"en":"80 sites means eighty different locations where evidence was examined.","zh":"80 sites 指檢查證據的八十個不同地點。"},{"en":"A school survey across 80 sites would include many different neighbourhoods.","zh":"跨80個地點進行的學校調查會包括許多不同社區。"},{"en":"If researchers study 80 sites, their results may be stronger than from one place only.","zh":"如果研究人員研究80個地點，其結果可能比只來自一個地方更有力。"},{"en":"The phrase gives the scale of fieldwork.","zh":"這個片語給出野外工作的規模。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":7},{"front":"so-called ichnotaxa","meaning":"所謂的足跡分類單位","examples":[{"en":"The researchers looked at 18 so-called ichnotaxa.","zh":"研究人員研究了18種所謂的足跡分類單位。"},{"en":"So-called ichnotaxa are named categories of fossil footprints rather than confirmed animal species.","zh":"so-called ichnotaxa 是化石足印的命名分類，而不是已確認的動物物種。"},{"en":"Students may find so-called ichnotaxa confusing because they classify tracks, not bones.","zh":"學生可能覺得所謂的足跡分類單位令人困惑，因為它們分類的是足跡而不是骨頭。"},{"en":"If scientists use ichnotaxa, they can group footprints even when exact species are unknown.","zh":"如果科學家使用足跡分類單位，即使確切物種未知，也能把足印分組。"},{"en":"The phrase signals a technical label.","zh":"這個片語標示技術名稱。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":7},{"front":"recognisable types of footprint","meaning":"可辨認的足印類型","examples":[{"en":"Ichnotaxa are recognisable types of footprint.","zh":"足跡分類單位是可辨認的足印類型。"},{"en":"Recognisable types of footprint are track patterns that can be identified and grouped.","zh":"recognisable types of footprint 是可被識別和分組的足跡模式。"},{"en":"A tracker may know recognisable types of footprint left by dogs, birds, or deer.","zh":"追蹤者可能認識狗、鳥或鹿留下的可辨認足印類型。"},{"en":"If footprints have recognisable types, scientists can compare them across locations.","zh":"如果足印有可辨認類型，科學家可以跨地點比較它們。"},{"en":"The phrase describes footprints that are clear enough to classify.","zh":"這個片語描述清楚得足以分類的足印。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":8},{"front":"cannot be matched precisely with","meaning":"不能與……精確配對","examples":[{"en":"The footprints cannot be matched precisely with the species that made them.","zh":"這些足印不能與留下它們的物種精確配對。"},{"en":"Cannot be matched precisely with means cannot be connected exactly to one specific source.","zh":"cannot be matched precisely with 指不能與某個特定來源準確連接。"},{"en":"A shoeprint may not be matched precisely with one student if many shoes look alike.","zh":"如果許多鞋子看起來相似，鞋印未必能與某個學生精確配對。"},{"en":"If footprints cannot be matched precisely with species, conclusions must remain general.","zh":"如果足印不能與物種精確配對，結論就必須保持概括。"},{"en":"The phrase highlights uncertainty in identification.","zh":"這個片語強調識別上的不確定性。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":8},{"front":"species of animal","meaning":"動物物種","examples":[{"en":"The footprints cannot identify the exact species of animal.","zh":"這些足印不能識別確切動物物種。"},{"en":"A species of animal is a particular kind of animal that can usually breed within its own group.","zh":"species of animal 是一種特定動物，通常可在同類群體內繁殖。"},{"en":"A zoo sign may explain the species of animal in each enclosure.","zh":"動物園標示可能解釋每個圍欄中的動物物種。"},{"en":"If evidence cannot show the exact species of animal, researchers may identify only the broader group.","zh":"如果證據不能顯示確切動物物種，研究人員可能只識別較廣泛群體。"},{"en":"The phrase refers to biological classification.","zh":"這個片語指生物分類。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":8},{"front":"a general sort of animal","meaning":"大致一類動物","examples":[{"en":"The footprints can be matched with a general sort of animal.","zh":"這些足印可與大致一類動物配對。"},{"en":"A general sort of animal means a broad type or group, not an exact species.","zh":"a general sort of animal 指廣泛類型或群體，而不是確切物種。"},{"en":"A child may know a track came from a general sort of animal, such as a bird, without knowing which bird.","zh":"孩子可能知道足跡來自大致一類動物，例如鳥，但不知道是哪種鳥。"},{"en":"If fossils show only a general sort of animal, scientists must avoid overclaiming.","zh":"如果化石只顯示大致一類動物，科學家必須避免過度聲稱。"},{"en":"The phrase gives an approximate classification.","zh":"這個片語給出大約分類。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":8},{"front":"act as an indicator of","meaning":"作為……的指標","examples":[{"en":"Ichnotaxa can act as an indicator of a group’s fate.","zh":"足跡分類單位可以作為某群體命運的指標。"},{"en":"Act as an indicator of means serve as a sign that shows something larger.","zh":"act as an indicator of 指作為顯示更大事情的跡象。"},{"en":"Empty shops can act as an indicator of economic problems in a town.","zh":"空置店舖可以作為城鎮經濟問題的指標。"},{"en":"If footprints disappear, they may act as an indicator of extinction or migration.","zh":"如果足印消失，它們可能作為滅絕或遷移的指標。"},{"en":"The phrase describes evidence that points to a wider pattern.","zh":"這個片語描述指向更廣泛模式的證據。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":8},{"front":"the fate of that group","meaning":"該群體的命運","examples":[{"en":"The footprints indicate the fate of that group.","zh":"這些足印顯示該群體的命運。"},{"en":"The fate of that group means what happened to that group in the end.","zh":"the fate of that group 指該群體最終發生了甚麼。"},{"en":"Exam results may show the fate of a class after a year of different teaching methods.","zh":"考試成績可能顯示一班學生在一年不同教學方法後的命運。"},{"en":"If a group’s tracks vanish, the fate of that group may have been extinction.","zh":"如果某群體的足跡消失，該群體的命運可能是滅絕。"},{"en":"The phrase focuses on final outcome.","zh":"這個片語集中於最終結果。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":8},{"front":"tell the story","meaning":"說明情況；揭示故事","examples":[{"en":"Footprints can tell the story when bones are absent.","zh":"當骨頭缺失時，足印可以說明情況。"},{"en":"Tell the story means reveal what happened or explain the situation.","zh":"tell the story 指揭示發生了甚麼或解釋情況。"},{"en":"A bank statement can tell the story of where a student spent money.","zh":"銀行月結單可以說明學生把錢花在哪裡。"},{"en":"If bones are missing, footprints may tell the story of animal movement and survival.","zh":"如果骨頭缺失，足印可能揭示動物移動和生存情況。"},{"en":"The phrase means evidence can explain events.","zh":"這個片語表示證據可以解釋事件。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":8},{"front":"before the end of","meaning":"在……結束之前","examples":[{"en":"Five ichnotaxa disappear before the end of the Triassic.","zh":"五種足跡分類單位在三疊紀結束之前消失。"},{"en":"Before the end of means earlier than the finishing point of a period.","zh":"before the end of 指早於某個時期的結束點。"},{"en":"Students must submit the form before the end of the school day.","zh":"學生必須在上課日結束之前提交表格。"},{"en":"If species disappear before the end of a period, their loss began before the boundary event.","zh":"如果物種在某時期結束之前消失，它們的消失早於邊界事件。"},{"en":"The phrase gives timing relative to an ending.","zh":"這個片語給出相對於結束點的時間。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":8},{"front":"march confidently across","meaning":"穩定地跨越……","examples":[{"en":"Four ichnotaxa march confidently across the boundary into the Jurassic.","zh":"四種足跡分類單位穩定地跨越界線進入侏羅紀。"},{"en":"March confidently across means continue clearly and strongly across a dividing line.","zh":"march confidently across 指清楚而有力地跨越分界線並繼續存在。"},{"en":"A successful idea may march confidently across different schools if teachers find it useful.","zh":"如果老師覺得有用，一個成功想法可能穩定地跨越不同學校。"},{"en":"If footprints march confidently across a boundary, the animals likely survived the transition.","zh":"如果足印穩定地跨越界線，相關動物很可能在過渡中倖存。"},{"en":"The phrase gives a vivid image of strong continuation.","zh":"這個片語用生動方式表達強勢延續。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":8},{"front":"across the boundary","meaning":"跨越界線","examples":[{"en":"Some footprints continue across the boundary into the Jurassic.","zh":"一些足印跨越界線延續到侏羅紀。"},{"en":"Across the boundary means from one side of a dividing line into the other side.","zh":"across the boundary 指從分界線一邊到另一邊。"},{"en":"A river may carry pollution across the boundary between two towns.","zh":"河流可能把污染帶過兩個城鎮之間的界線。"},{"en":"If fossils continue across a geological boundary, the group survived that transition.","zh":"如果化石跨越地質界線延續，該群體就在過渡中倖存。"},{"en":"The phrase marks movement or continuation across a dividing point.","zh":"這個片語標示跨越分界點的移動或延續。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":8},{"front":"vanish at the boundary","meaning":"在界線處消失","examples":[{"en":"Six ichnotaxa vanish at the boundary.","zh":"六種足跡分類單位在界線處消失。"},{"en":"Vanish at the boundary means disappear exactly around a dividing point in time or rock layers.","zh":"vanish at the boundary 指在時間或岩層分界點附近消失。"},{"en":"A school rule may vanish at the boundary between old and new management.","zh":"學校規則可能在新舊管理層交替的界線處消失。"},{"en":"If many track types vanish at the boundary, scientists may suspect a major event.","zh":"如果許多足跡類型在界線處消失，科學家可能懷疑有重大事件。"},{"en":"The phrase points to sudden disappearance at a transition.","zh":"這個片語指出過渡點上的突然消失。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":9},{"front":"only just splutter across","meaning":"勉強延續過……","examples":[{"en":"Some ichnotaxa only just splutter across the boundary.","zh":"有些足跡分類單位只是勉強延續過界線。"},{"en":"Only just splutter across means barely continue beyond a boundary in a weak or irregular way.","zh":"only just splutter across 指以微弱或不穩定方式勉強越過分界線並延續。"},{"en":"A small business may only just splutter through a difficult year before closing.","zh":"小企業可能勉強熬過困難一年後便結業。"},{"en":"If a footprint type only just splutters across a boundary, the animal group may have been struggling.","zh":"如果一種足印類型只是勉強延續過界線，該動物群體可能一直在掙扎。"},{"en":"The phrase suggests weak survival rather than strong continuation.","zh":"這個片語暗示微弱生存，而不是強勢延續。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":9},{"front":"appear from nowhere","meaning":"突然出現","examples":[{"en":"Three ichnotaxa appear from nowhere after the Jurassic begins.","zh":"三種足跡分類單位在侏羅紀開始後突然出現。"},{"en":"Appear from nowhere means suddenly appear without an obvious earlier source.","zh":"appear from nowhere 指在沒有明顯先前來源下突然出現。"},{"en":"A new trend can appear from nowhere on social media and spread quickly.","zh":"新潮流可以在社交媒體上突然出現並迅速傳播。"},{"en":"If new footprints appear from nowhere in the rock record, scientists ask what changed.","zh":"如果新足印在岩石記錄中突然出現，科學家會問發生了甚麼變化。"},{"en":"The phrase stresses sudden and unexpected appearance.","zh":"這個片語強調突然和意外出現。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":9},{"front":"almost as soon as","meaning":"幾乎一……就……","examples":[{"en":"New ichnotaxa appeared almost as soon as the Jurassic began.","zh":"新足跡分類單位幾乎在侏羅紀一開始就出現。"},{"en":"Almost as soon as means very shortly after something happens.","zh":"almost as soon as 指某事發生後很快。"},{"en":"Students started asking questions almost as soon as the teacher introduced the topic.","zh":"老師一介紹主題，學生幾乎立即開始發問。"},{"en":"If new animal tracks appear almost as soon as a period begins, change happened quickly.","zh":"如果新動物足跡幾乎在某時期一開始就出現，變化就發生得很快。"},{"en":"The phrase shows a very short delay.","zh":"這個片語顯示非常短的延遲。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":9},{"front":"the boundary itself","meaning":"該界線本身","examples":[{"en":"The boundary itself is suggestive.","zh":"該界線本身具有暗示性。"},{"en":"The boundary itself means the dividing line alone, even before looking at other details.","zh":"the boundary itself 指單是分界線本身，即使還未看其他細節。"},{"en":"The date itself may be suggestive if many changes happened around it.","zh":"如果許多變化都在某日期附近發生，該日期本身可能具有暗示性。"},{"en":"If the boundary itself shows sudden disappearances, it may point to a major event.","zh":"如果該界線本身顯示突然消失，它可能指向重大事件。"},{"en":"The phrase focuses attention on the dividing point.","zh":"這個片語把注意力集中於分界點。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":9},{"front":"be suggestive","meaning":"具有暗示性","examples":[{"en":"The boundary itself is suggestive of a major event.","zh":"該界線本身暗示有重大事件。"},{"en":"Be suggestive means seem to point toward a possible explanation without proving it fully.","zh":"be suggestive 指似乎指向某種可能解釋，但未完全證明。"},{"en":"A sudden drop in attendance is suggestive of a problem at school.","zh":"出席率突然下降，暗示學校可能有問題。"},{"en":"If many fossils vanish at one boundary, the pattern is suggestive of disaster.","zh":"如果許多化石在同一界線消失，該模式暗示災難。"},{"en":"The phrase indicates a clue, not complete proof.","zh":"這個片語表示線索，而不是完整證明。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":9},{"front":"geological indication","meaning":"地質跡象","examples":[{"en":"The first geological indication of the impact was iridium.","zh":"撞擊的第一個地質跡象是銥。"},{"en":"A geological indication is evidence in rocks or Earth materials that points to an event.","zh":"geological indication 是岩石或地球物質中指向某事件的證據。"},{"en":"Layers of ash can be a geological indication of an old volcanic eruption.","zh":"火山灰層可以是古代火山爆發的地質跡象。"},{"en":"If iridium appears unusually in rocks, it may be a geological indication of an impact.","zh":"如果銥在岩石中異常出現，它可能是撞擊的地質跡象。"},{"en":"The phrase refers to physical Earth evidence.","zh":"這個片語指地球實體證據。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":9},{"front":"unusually high level of","meaning":"異常高水平的……","examples":[{"en":"An unusually high level of iridium was found in the rocks.","zh":"岩石中發現異常高水平的銥。"},{"en":"An unusually high level of means an amount much greater than normal.","zh":"an unusually high level of 指某物的數量遠高於正常。"},{"en":"An unusually high level of noise near a school may lead to complaints.","zh":"學校附近異常高水平的噪音可能導致投訴。"},{"en":"If rocks contain an unusually high level of a rare element, scientists look for an unusual cause.","zh":"如果岩石含有異常高水平的稀有元素，科學家會尋找異常原因。"},{"en":"The phrase signals that a measurement is abnormal.","zh":"這個片語表示量度結果不正常。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":9},{"front":"iridium","meaning":"銥","examples":[{"en":"Iridium is rare at the earth’s surface but common in meteorites.","zh":"銥在地球表面很罕見，但在隕石中常見。"},{"en":"Iridium is a chemical element that can be unusually concentrated in impact-related rocks.","zh":"iridium 是一種化學元素，可在與撞擊有關的岩石中異常集中。"},{"en":"Chemistry students may learn iridium as one of the rare metallic elements.","zh":"化學學生可能學到銥是稀有金屬元素之一。"},{"en":"If iridium is found at high levels in a boundary layer, it may suggest material from space.","zh":"如果邊界層中發現高水平銥，它可能暗示來自太空的物質。"},{"en":"The word names a specific element used as evidence in impact theory.","zh":"這個詞指撞擊理論中作為證據的特定元素。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":9},{"front":"at the end of the Cretaceous","meaning":"在白堊紀末期","examples":[{"en":"The iridium was found in rocks at the end of the Cretaceous.","zh":"銥在白堊紀末期的岩石中被發現。"},{"en":"At the end of the Cretaceous means near the final part of the Cretaceous period.","zh":"at the end of the Cretaceous 指接近白堊紀最後階段。"},{"en":"Many discussions of dinosaur extinction focus on events at the end of the Cretaceous.","zh":"許多關於恐龍滅絕的討論集中於白堊紀末期的事件。"},{"en":"If a rock layer dates to the end of the Cretaceous, it may preserve extinction evidence.","zh":"如果岩層定年為白堊紀末期，它可能保存滅絕證據。"},{"en":"The phrase gives a specific geological timing.","zh":"這個片語給出特定地質時間。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":9},{"front":"disappear from the fossil record","meaning":"從化石記錄中消失","examples":[{"en":"The beasts disappeared from the fossil record.","zh":"這些巨獸從化石記錄中消失。"},{"en":"Disappear from the fossil record means stop appearing in preserved fossil evidence.","zh":"disappear from the fossil record 指不再出現在保存下來的化石證據中。"},{"en":"If a shellfish species disappears from the fossil record, it may have died out or moved elsewhere.","zh":"如果某貝類物種從化石記錄中消失，它可能已滅絕或遷往別處。"},{"en":"When many animals disappear from the fossil record together, scientists suspect a major change.","zh":"當許多動物一起從化石記錄中消失，科學家會懷疑有重大變化。"},{"en":"The phrase describes loss from preserved evidence.","zh":"這個片語描述從保存證據中消失。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":10},{"front":"the earth’s surface","meaning":"地球表面","examples":[{"en":"Iridium is normally rare at the earth’s surface.","zh":"銥通常在地球表面很罕見。"},{"en":"The earth’s surface is the outer layer of land and sea where life and weather occur.","zh":"the earth’s surface 是生命和天氣發生的陸地與海洋外層。"},{"en":"Rain, wind, and rivers constantly change the earth’s surface.","zh":"雨、風和河流不斷改變地球表面。"},{"en":"If an element is rare at the earth’s surface but common in meteorites, high levels may suggest an impact.","zh":"如果某元素在地球表面罕見但在隕石中常見，高水平可能暗示撞擊。"},{"en":"The phrase refers to the outside of the planet.","zh":"這個片語指地球外部。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":10},{"front":"be more abundant in","meaning":"在……中更豐富","examples":[{"en":"Iridium is more abundant in meteorites.","zh":"銥在隕石中更豐富。"},{"en":"Be more abundant in means exist in greater amounts in one place or material.","zh":"be more abundant in 指在某地方或物質中數量更多。"},{"en":"Vitamin C is more abundant in some fruits than in sweets.","zh":"維他命C在某些水果中比在糖果中更豐富。"},{"en":"If iridium is more abundant in meteorites, high iridium in rocks may point to space material.","zh":"如果銥在隕石中更豐富，岩石中的高銥含量可能指向太空物質。"},{"en":"The phrase compares quantity across sources.","zh":"這個片語比較不同來源中的數量。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":10},{"front":"meteorites","meaning":"隕石","examples":[{"en":"Meteorites contain more iridium than the earth’s surface.","zh":"隕石含有比地球表面更多的銥。"},{"en":"Meteorites are pieces of rock or metal from space that reach Earth’s surface.","zh":"meteorites 是來自太空並到達地球表面的岩石或金屬碎片。"},{"en":"A museum may display meteorites so visitors can touch material from space.","zh":"博物館可能展示隕石，讓訪客觸摸來自太空的物質。"},{"en":"If meteorites contain high iridium, their chemical signature can support impact theories.","zh":"如果隕石含有高水平銥，其化學特徵可以支持撞擊理論。"},{"en":"The word refers to space material that survives the fall to Earth.","zh":"這個詞指經過墜落仍到達地球的太空物質。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":10},{"front":"impact theory","meaning":"撞擊理論","examples":[{"en":"Scientists began to believe the impact theory.","zh":"科學家開始相信撞擊理論。"},{"en":"Impact theory is the idea that a large collision from space caused a major event on Earth.","zh":"impact theory 是認為大型太空碰撞造成地球重大事件的想法。"},{"en":"Students learn the impact theory when studying dinosaur extinction.","zh":"學生研究恐龍滅絕時會學到撞擊理論。"},{"en":"If iridium and craters match the timing, the impact theory becomes stronger.","zh":"如果銥和隕石坑與時間吻合，撞擊理論就變得更強。"},{"en":"The phrase refers to an explanation based on collision evidence.","zh":"這個片語指基於碰撞證據的解釋。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":10},{"front":"start looking for","meaning":"開始尋找","examples":[{"en":"Scientists started looking for other anomalies.","zh":"科學家開始尋找其他異常現象。"},{"en":"Start looking for means begin trying to find something.","zh":"start looking for 指開始嘗試尋找某物。"},{"en":"After losing a key, a student may start looking for it in their bag and desk.","zh":"遺失鎖匙後，學生可能開始在書包和書桌尋找。"},{"en":"If one unusual clue is found, researchers may start looking for related evidence.","zh":"如果發現一個不尋常線索，研究人員可能開始尋找相關證據。"},{"en":"The phrase marks the beginning of a search.","zh":"這個片語標記搜尋的開始。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":10},{"front":"Cretaceous-end anomalies","meaning":"白堊紀末期異常現象","examples":[{"en":"Scientists looked for other Cretaceous-end anomalies.","zh":"科學家尋找其他白堊紀末期異常現象。"},{"en":"Cretaceous-end anomalies are unusual signs found around the end of the Cretaceous period.","zh":"Cretaceous-end anomalies 是在白堊紀末期附近發現的不尋常跡象。"},{"en":"A sudden change in plant fossils could be one Cretaceous-end anomaly.","zh":"植物化石突然改變可能是一種白堊紀末期異常現象。"},{"en":"If several Cretaceous-end anomalies occur together, they may support a major-event theory.","zh":"如果幾種白堊紀末期異常現象一起出現，它們可能支持重大事件理論。"},{"en":"The phrase combines timing with unusual evidence.","zh":"這個片語結合時間和異常證據。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":10},{"front":"turn up","meaning":"出現；被發現","examples":[{"en":"One anomaly that turned up was a fern spike.","zh":"被發現的一種異常現象是蕨類孢子激增。"},{"en":"Turn up means appear, be found, or become noticeable.","zh":"turn up 指出現、被找到或變得明顯。"},{"en":"A missing library book may turn up under a student’s desk.","zh":"遺失的圖書館書可能在學生桌下被發現。"},{"en":"If a new clue turns up, researchers may change their explanation.","zh":"如果新線索出現，研究人員可能改變解釋。"},{"en":"The phrase often describes unexpected discovery.","zh":"這個片語常描述意外發現。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":10},{"front":"surprising abundance of","meaning":"令人意外的大量……","examples":[{"en":"Scientists found a surprising abundance of fern spores.","zh":"科學家發現令人意外的大量蕨類孢子。"},{"en":"Surprising abundance of means an unexpectedly large amount of something.","zh":"surprising abundance of 指出乎意料地大量的某物。"},{"en":"After the festival, volunteers found a surprising abundance of plastic bottles in the park.","zh":"節日後，義工在公園發現令人意外的大量膠樽。"},{"en":"If rocks show a surprising abundance of one fossil type, something may have changed suddenly.","zh":"如果岩石顯示某一化石類型令人意外地大量出現，可能有事情突然改變。"},{"en":"The phrase stresses unexpected quantity.","zh":"這個片語強調意外的數量。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":10},{"front":"fern spores","meaning":"蕨類孢子","examples":[{"en":"Fern spores were abundant just above the boundary layer.","zh":"蕨類孢子在邊界層上方非常豐富。"},{"en":"Fern spores are tiny reproductive cells produced by ferns.","zh":"fern spores 是蕨類植物產生的細小繁殖細胞。"},{"en":"Biology students may observe fern spores under a microscope.","zh":"生物學生可能在顯微鏡下觀察蕨類孢子。"},{"en":"If fern spores suddenly become abundant, ferns may have rapidly colonised open land.","zh":"如果蕨類孢子突然變得豐富，蕨類可能迅速佔領空地。"},{"en":"The phrase refers to plant reproductive evidence.","zh":"這個片語指植物繁殖證據。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":10},{"front":"boundary layer","meaning":"邊界層","examples":[{"en":"Fern spores were found just above the boundary layer.","zh":"蕨類孢子在邊界層上方被發現。"},{"en":"A boundary layer is a rock layer marking the division between two geological periods or events.","zh":"boundary layer 是標示兩個地質時期或事件分界的岩層。"},{"en":"Scientists may study a boundary layer to see what changed before and after it.","zh":"科學家可能研究邊界層，以了解其前後發生了甚麼變化。"},{"en":"If unusual elements appear near a boundary layer, they may signal a major event.","zh":"如果異常元素出現在邊界層附近，它們可能標示重大事件。"},{"en":"The phrase refers to a physical layer in rocks.","zh":"這個片語指岩石中的實體層。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":11},{"front":"be known as","meaning":"被稱為","examples":[{"en":"The phenomenon is known as a fern spike.","zh":"這種現象被稱為蕨類孢子激增。"},{"en":"Be known as means be called by a particular name.","zh":"be known as 指被稱為某個特定名稱。"},{"en":"The city is known as a financial centre because many banks are located there.","zh":"這座城市因有許多銀行而被稱為金融中心。"},{"en":"If a pattern is known as a fern spike, scientists can discuss it more precisely.","zh":"如果某種模式被稱為蕨類孢子激增，科學家就能更精確討論它。"},{"en":"The phrase introduces a recognised name.","zh":"這個片語引出公認名稱。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":11},{"front":"fern spike","meaning":"蕨類孢子激增","examples":[{"en":"A fern spike can indicate a major ecological disaster.","zh":"蕨類孢子激增可以表示重大生態災難。"},{"en":"A fern spike is a sudden large increase in fern spores in rock layers.","zh":"fern spike 是岩層中蕨類孢子突然大量增加。"},{"en":"Geology students may learn about a fern spike when studying mass extinctions.","zh":"地質學生研究大滅絕時可能學到蕨類孢子激增。"},{"en":"If a fern spike appears after a boundary, it may show that ferns colonised cleared land.","zh":"如果蕨類孢子激增出現在邊界後，它可能顯示蕨類佔領了被清空的土地。"},{"en":"The phrase describes plant evidence after environmental disruption.","zh":"這個片語描述環境擾動後的植物證據。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":11},{"front":"match the theory nicely","meaning":"與該理論十分吻合","examples":[{"en":"The fern spike matched the theory nicely.","zh":"蕨類孢子激增與該理論十分吻合。"},{"en":"Match the theory nicely means fit well with what the theory predicts.","zh":"match the theory nicely 指與理論所預測的內容非常配合。"},{"en":"A student’s survey results may match the theory nicely if they show the expected trend.","zh":"如果學生調查結果顯示預期趨勢，就可能與該理論十分吻合。"},{"en":"If evidence matches the theory nicely, scientists may take the theory more seriously.","zh":"如果證據與理論十分吻合，科學家可能更認真看待該理論。"},{"en":"The phrase suggests supportive agreement between evidence and explanation.","zh":"這個片語暗示證據與解釋之間有支持性的配合。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":11},{"front":"opportunists","meaning":"機會主義物種","examples":[{"en":"Many modern ferns are opportunists.","zh":"許多現代蕨類是機會主義物種。"},{"en":"Opportunists are organisms or people that quickly take advantage of available chances.","zh":"opportunists 是能迅速利用可用機會的生物或人。"},{"en":"Weeds are often opportunists because they grow quickly on disturbed ground.","zh":"雜草常是機會主義物種，因為它們在受擾土地上快速生長。"},{"en":"If ferns are opportunists, they can spread fast after other plants are removed.","zh":"如果蕨類是機會主義物種，其他植物被移除後它們可以迅速擴散。"},{"en":"The word can be biological or social depending on context.","zh":"這個詞可用於生物或社會語境，視乎上下文而定。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":11},{"front":"compete against","meaning":"與……競爭","examples":[{"en":"Ferns cannot compete against plants with leaves.","zh":"蕨類不能與有葉植物競爭。"},{"en":"Compete against means try to survive, win, or succeed while facing another rival.","zh":"compete against 指面對另一競爭者時爭取生存、勝利或成功。"},{"en":"Small shops compete against supermarkets by offering personal service.","zh":"小店透過提供個人化服務與超市競爭。"},{"en":"If ferns cannot compete against stronger plants, they grow best when land is cleared.","zh":"如果蕨類不能與更強植物競爭，它們在土地被清空時生長得最好。"},{"en":"The phrase shows rivalry for space, food, customers, or success.","zh":"這個片語顯示對空間、食物、顧客或成功的競爭。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":11},{"front":"plants with leaves","meaning":"有葉植物","examples":[{"en":"Ferns struggle to compete against plants with leaves.","zh":"蕨類難以與有葉植物競爭。"},{"en":"Plants with leaves are plants that have leaf structures for capturing sunlight.","zh":"plants with leaves 是具有葉片結構以吸收陽光的植物。"},{"en":"In a garden, plants with leaves may shade smaller plants below them.","zh":"在花園中，有葉植物可能遮蔽下方較小植物。"},{"en":"If plants with leaves grow densely, ferns may receive too little light.","zh":"如果有葉植物生長得很密，蕨類可能得到太少光。"},{"en":"The phrase contrasts ferns with more competitive leafy plants.","zh":"這個片語把蕨類與競爭力較強的有葉植物作對比。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":11},{"front":"a piece of land is cleared","meaning":"一塊土地被清空","examples":[{"en":"Ferns grow quickly when a piece of land is cleared.","zh":"當一塊土地被清空，蕨類會快速生長。"},{"en":"A piece of land is cleared means plants, trees, or obstacles are removed from that area.","zh":"a piece of land is cleared 指該區植物、樹木或障礙物被移除。"},{"en":"A community garden can begin after a piece of land is cleared of rubbish.","zh":"一塊土地清走垃圾後，可以開始社區花園。"},{"en":"If a piece of land is cleared by fire, fast-growing plants may arrive first.","zh":"如果一塊土地被火清空，快速生長的植物可能最先到來。"},{"en":"The phrase describes land becoming open for new growth or use.","zh":"這個片語描述土地變得開放，可供新生長或使用。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":11},{"front":"volcanic eruption","meaning":"火山爆發","examples":[{"en":"A volcanic eruption can clear a piece of land.","zh":"火山爆發可以清空一塊土地。"},{"en":"A volcanic eruption is an event in which lava, ash, and gases come out of a volcano.","zh":"volcanic eruption 是岩漿、火山灰和氣體從火山噴出的事件。"},{"en":"People living near a volcano may evacuate before a volcanic eruption.","zh":"住在火山附近的人可能在火山爆發前撤離。"},{"en":"If a volcanic eruption covers land with ash, the old vegetation may be destroyed.","zh":"如果火山爆發用火山灰覆蓋土地，原有植被可能被摧毀。"},{"en":"The phrase describes a powerful geological event.","zh":"這個片語描述強大的地質事件。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":11},{"front":"the first things to","meaning":"最先……的東西","examples":[{"en":"Ferns are often the first things to set up shop on cleared land.","zh":"蕨類常是清空土地上最先佔地立足的植物。"},{"en":"The first things to means the earliest organisms, people, or items to do something.","zh":"the first things to 指最早做某事的生物、人或事物。"},{"en":"Buses are often the first things to restart after a storm because many people need transport.","zh":"風暴後，巴士常是最先恢復的交通，因為很多人需要出行。"},{"en":"If ferns are the first things to grow after disaster, their spores can become abundant.","zh":"如果蕨類是災難後最先生長的植物，其孢子可能變得豐富。"},{"en":"The phrase points to what appears or acts earliest.","zh":"這個片語指出最早出現或行動的事物。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":11},{"front":"set up shop","meaning":"佔地立足；開始生長","examples":[{"en":"Ferns are often the first plants to set up shop after land is cleared.","zh":"土地被清空後，蕨類常是最先佔地立足的植物。"},{"en":"Set up shop means establish oneself in a place and begin operating or growing there.","zh":"set up shop 指在某地站穩並開始運作或生長。"},{"en":"A new café may set up shop near a school to serve students and teachers.","zh":"新咖啡店可能在學校附近開業，服務學生和老師。"},{"en":"If ferns set up shop quickly, they can cover disturbed land before other plants return.","zh":"如果蕨類迅速佔地立足，它們可在其他植物回來前覆蓋受擾土地。"},{"en":"The phrase is informal and suggests settling into a space.","zh":"這個片語較口語，暗示在某空間定下來。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":12},{"front":"strip the earth of","meaning":"使地球失去……","examples":[{"en":"An asteroid strike would have stripped much of the earth of vegetation.","zh":"小行星撞擊會使地球大部分地區失去植被。"},{"en":"Strip the earth of means remove something widely from the planet’s surface.","zh":"strip the earth of 指大規模移除地球表面的某物。"},{"en":"A severe drought can strip farmland of healthy crops.","zh":"嚴重乾旱可以使農地失去健康作物。"},{"en":"If an impact stripped the earth of vegetation, open land would be left for ferns.","zh":"如果撞擊使地球失去植被，就會留下空地給蕨類。"},{"en":"The phrase suggests large-scale removal.","zh":"這個片語暗示大規模移除。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":12},{"front":"vegetation","meaning":"植被","examples":[{"en":"The asteroid strike stripped much of the earth of vegetation.","zh":"小行星撞擊使地球大部分地區失去植被。"},{"en":"Vegetation means plants growing in an area, including grasses, trees, shrubs, and ferns.","zh":"vegetation 指某地生長的植物，包括草、樹、灌木和蕨類。"},{"en":"Thick vegetation beside a path can make walking difficult.","zh":"小徑旁茂密植被可以令步行困難。"},{"en":"If vegetation disappears after a disaster, animals may lose food and shelter.","zh":"如果災難後植被消失，動物可能失去食物和庇護。"},{"en":"The word refers to plant cover in general.","zh":"這個詞泛指植物覆蓋。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":12},{"front":"provide a paradise for","meaning":"為……提供天堂","examples":[{"en":"The cleared land provided a paradise for ferns.","zh":"被清空的土地為蕨類提供天堂。"},{"en":"Provide a paradise for means create ideal conditions for something to grow or succeed.","zh":"provide a paradise for 指創造某物生長或成功的理想條件。"},{"en":"A warm, quiet library can provide a paradise for students who love reading.","zh":"溫暖安靜的圖書館可以為喜歡閱讀的學生提供天堂。"},{"en":"If competitors disappear, open land may provide a paradise for fast-growing plants.","zh":"如果競爭者消失，空地可能為快速生長植物提供天堂。"},{"en":"The phrase strongly suggests a very favourable environment.","zh":"這個片語強烈暗示非常有利的環境。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":12},{"front":"a good indication that","meaning":"……的有力跡象","examples":[{"en":"A fern spike is a good indication that something terrible has happened.","zh":"蕨類孢子激增是發生了可怕事情的有力跡象。"},{"en":"A good indication that means a strong sign suggesting something is true.","zh":"a good indication that 指有力地顯示某事很可能為真。"},{"en":"Empty shelves can be a good indication that a product is popular.","zh":"空貨架可以是產品受歡迎的有力跡象。"},{"en":"If many ferns appear suddenly, it may be a good indication that land was recently cleared.","zh":"如果許多蕨類突然出現，這可能是土地最近被清空的有力跡象。"},{"en":"The phrase signals useful evidence, not absolute proof.","zh":"這個片語表示有用證據，而不是絕對證明。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":12},{"front":"something terrible has happened","meaning":"發生了可怕的事情","examples":[{"en":"A fern spike suggests that something terrible has happened.","zh":"蕨類孢子激增暗示發生了可怕的事情。"},{"en":"Something terrible has happened means a serious damaging event has occurred.","zh":"something terrible has happened 指嚴重破壞性事件已經發生。"},{"en":"If a classroom is flooded and books are ruined, something terrible has happened.","zh":"如果課室水浸且書本被毀，就是發生了可怕的事情。"},{"en":"If a rock layer shows mass death, scientists may infer that something terrible happened.","zh":"如果岩層顯示大量死亡，科學家可能推斷發生了可怕的事情。"},{"en":"The phrase points to a severe event without naming it yet.","zh":"這個片語指出嚴重事件，但尚未命名。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":12},{"front":"iridium anomaly","meaning":"銥異常","examples":[{"en":"An iridium anomaly appears at the end of the Triassic.","zh":"銥異常出現在三疊紀末期。"},{"en":"An iridium anomaly is an unusual level of iridium found where it is not normally expected.","zh":"iridium anomaly 是在通常不預期的位置發現異常水平的銥。"},{"en":"A scientist may investigate an iridium anomaly to see whether it came from meteorites.","zh":"科學家可能調查銥異常，以了解它是否來自隕石。"},{"en":"If an iridium anomaly appears near an extinction boundary, it may support an impact theory.","zh":"如果銥異常出現在滅絕邊界附近，它可能支持撞擊理論。"},{"en":"The phrase describes abnormal chemical evidence.","zh":"這個片語描述異常化學證據。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":12},{"front":"account for","meaning":"解釋；說明……的原因","examples":[{"en":"The anomaly accounts for the disappearing ichnotaxa.","zh":"該異常解釋了消失的足跡分類單位。"},{"en":"Account for means explain the reason for something.","zh":"account for 指解釋某事的原因。"},{"en":"Poor weather may account for the low number of visitors.","zh":"天氣差可能解釋訪客人數少的原因。"},{"en":"If an impact accounts for disappearing tracks, it explains why some animals vanished.","zh":"如果撞擊能解釋消失的足跡，它就說明為何某些動物消失。"},{"en":"The phrase connects evidence with explanation.","zh":"這個片語把證據與解釋連接起來。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":12},{"front":"disappearing ichnotaxa","meaning":"消失的足跡分類單位","examples":[{"en":"The disappearing ichnotaxa suggest that many creatures died out.","zh":"消失的足跡分類單位顯示許多生物滅絕。"},{"en":"Disappearing ichnotaxa are footprint categories that stop appearing in the rock record.","zh":"disappearing ichnotaxa 是不再出現在岩石記錄中的足跡分類。"},{"en":"If a school register shows disappearing names, teachers ask where the students went.","zh":"如果學校名冊顯示名字消失，老師會問學生去了哪裡。"},{"en":"If ichnotaxa disappear suddenly, the animals that made them may have vanished too.","zh":"如果足跡分類單位突然消失，留下它們的動物也可能消失。"},{"en":"The phrase uses track evidence to discuss animal loss.","zh":"這個片語使用足跡證據討論動物消失。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":12},{"front":"survive the holocaust","meaning":"在大災難中倖存","examples":[{"en":"The creatures that made the tracks did not survive the holocaust.","zh":"留下這些足跡的生物沒有在大災難中倖存。"},{"en":"Survive the holocaust means live through a massive destructive disaster.","zh":"survive the holocaust 指在大規模破壞性災難中活下來。"},{"en":"Some trees may survive a wildfire, but smaller plants may not survive the disaster.","zh":"有些樹可能在山火中倖存，但較小植物可能無法在災難中活下來。"},{"en":"If animals did not survive the holocaust, their tracks would stop appearing afterward.","zh":"如果動物沒有在大災難中倖存，其足跡之後就會停止出現。"},{"en":"In this passage, holocaust means a great catastrophe, not the specific historical event.","zh":"在本文中，holocaust 指巨大災難，而不是特定歷史事件。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":12},{"front":"the surprise is","meaning":"令人意外的是","examples":[{"en":"The surprise is how rapidly the new ichnotaxa appear.","zh":"令人意外的是新足跡分類單位出現得多麼迅速。"},{"en":"The surprise is introduces the unexpected part of a situation.","zh":"the surprise is 用來引出情況中出乎意料的部分。"},{"en":"The surprise is not that students like games, but that games helped their grammar improve.","zh":"令人意外的不是學生喜歡遊戲，而是遊戲幫助他們改善文法。"},{"en":"If scientists expected slow recovery, the surprise is rapid new evidence after the boundary.","zh":"如果科學家預期恢復緩慢，令人意外的就是邊界後迅速出現的新證據。"},{"en":"The phrase points to what is most unexpected.","zh":"這個片語指出最出乎意料的地方。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":13},{"front":"how rapidly","meaning":"多麼迅速地","examples":[{"en":"The researchers were surprised by how rapidly new ichnotaxa appeared.","zh":"研究人員對新足跡分類單位出現得多麼迅速感到驚訝。"},{"en":"How rapidly means how quickly something happens.","zh":"how rapidly 指某事發生得多快。"},{"en":"A teacher may be surprised by how rapidly a beginner improves with daily practice.","zh":"初學者每天練習後進步得多麼迅速，可能令老師驚訝。"},{"en":"If new tracks appear rapidly, ecological change may have happened quickly.","zh":"如果新足跡迅速出現，生態變化可能發生得很快。"},{"en":"The phrase focuses on speed.","zh":"這個片語集中於速度。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":13},{"front":"a mere","meaning":"僅僅","examples":[{"en":"Eubrontes giganteus appears a mere 10,000 years after the anomaly.","zh":"巨型真雷龍足跡僅僅在該異常後一萬年出現。"},{"en":"A mere means only, used to stress that a number is surprisingly small.","zh":"a mere 指僅僅，用來強調數字小得令人意外。"},{"en":"The café is a mere five-minute walk from school.","zh":"咖啡店距離學校僅僅五分鐘步程。"},{"en":"In geological time, a mere 10,000 years can be extremely short.","zh":"在地質時間中，僅僅一萬年可以非常短。"},{"en":"The phrase makes the amount sound smaller than expected.","zh":"這個片語令數量聽起來比預期更小。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":13},{"front":"Eubrontes giganteus","meaning":"巨型真雷龍足跡","examples":[{"en":"Eubrontes giganteus appeared shortly after the iridium anomaly.","zh":"巨型真雷龍足跡在銥異常後不久出現。"},{"en":"Eubrontes giganteus is a large dinosaur footprint type linked with theropods.","zh":"Eubrontes giganteus 是與獸腳類恐龍有關的大型恐龍足跡類型。"},{"en":"A museum label may use Eubrontes giganteus to name a fossil track, not a whole skeleton.","zh":"博物館標籤可能用 Eubrontes giganteus 命名化石足跡，而不是整副骨骼。"},{"en":"If Eubrontes giganteus appears soon after a boundary, it may show rapid dinosaur expansion.","zh":"如果巨型真雷龍足跡在邊界後不久出現，它可能顯示恐龍迅速擴張。"},{"en":"The phrase names a specific ichnotaxon.","zh":"這個片語指一種特定足跡分類單位。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":13},{"front":"be made by","meaning":"由……造成","examples":[{"en":"The Eubrontes prints were made by theropods.","zh":"Eubrontes 足印由獸腳類恐龍造成。"},{"en":"Be made by means be created or produced by someone or something.","zh":"be made by 指由某人或某物創造或產生。"},{"en":"The marks on the wet floor were made by a dog’s paws.","zh":"濕地板上的痕跡是由狗爪造成的。"},{"en":"If footprints were made by theropods, they show where those dinosaurs walked.","zh":"如果足印由獸腳類恐龍造成，它們就顯示那些恐龍走過哪裡。"},{"en":"The phrase identifies the maker of evidence.","zh":"這個片語指出證據的製造者。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":13},{"front":"theropods","meaning":"獸腳類恐龍","examples":[{"en":"Theropods were the dinosaur group that later produced large predators.","zh":"獸腳類恐龍是後來產生大型掠食者的恐龍群體。"},{"en":"Theropods are a group of mostly meat-eating dinosaurs that walked on two legs.","zh":"theropods 是一群多數食肉、以兩足行走的恐龍。"},{"en":"Students often learn about theropods when studying Tyrannosaurus and similar dinosaurs.","zh":"學生研究暴龍和類似恐龍時常會認識獸腳類恐龍。"},{"en":"If theropods grew larger after competitors disappeared, ecological release may explain it.","zh":"如果獸腳類恐龍在競爭者消失後長得更大，生態釋放可能可解釋。"},{"en":"The word names a major dinosaur group.","zh":"這個詞指一個主要恐龍群體。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":13},{"front":"go on to produce","meaning":"後來產生","examples":[{"en":"Theropods went on to produce Allosaurus and Tyrannosaurus.","zh":"獸腳類恐龍後來產生異特龍和暴龍。"},{"en":"Go on to produce means later develop into or give rise to something.","zh":"go on to produce 指後來發展成或產生某事物。"},{"en":"A small school club may go on to produce successful musicians years later.","zh":"小型學校學會多年後可能產生成功音樂人。"},{"en":"If early theropods went on to produce giant predators, their later evolution was dramatic.","zh":"如果早期獸腳類恐龍後來產生巨型掠食者，其後續演化就很戲劇化。"},{"en":"The phrase links an earlier group with later results.","zh":"這個片語把早期群體與後來結果連接起來。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":13},{"front":"such nightmares as","meaning":"像……這樣可怕的生物","examples":[{"en":"Theropods produced such nightmares as Allosaurus and Tyrannosaurus.","zh":"獸腳類恐龍產生了像異特龍和暴龍這樣可怕的生物。"},{"en":"Such nightmares as means frightening examples such as the ones named.","zh":"such nightmares as 指像所列例子那樣令人恐懼的事物。"},{"en":"A horror film may include such nightmares as ghosts, monsters, and sudden attacks.","zh":"恐怖電影可能包括鬼、怪物和突然襲擊這樣可怕的東西。"},{"en":"If theropods produced such nightmares as large predators, they became powerful hunters.","zh":"如果獸腳類恐龍產生了這樣的大型掠食者，牠們就成為強大獵手。"},{"en":"The phrase is dramatic and slightly humorous.","zh":"這個片語語氣戲劇化並略帶幽默。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":13},{"front":"Allosaurus","meaning":"異特龍","examples":[{"en":"Allosaurus was one of the large predatory dinosaurs.","zh":"異特龍是大型掠食性恐龍之一。"},{"en":"Allosaurus is a large meat-eating dinosaur from the Jurassic period.","zh":"Allosaurus 是侏羅紀的一種大型食肉恐龍。"},{"en":"A museum may display Allosaurus teeth to show how it hunted prey.","zh":"博物館可能展示異特龍牙齒，以顯示牠如何捕獵獵物。"},{"en":"If Allosaurus descended from earlier theropods, it shows how large predators evolved.","zh":"如果異特龍由早期獸腳類恐龍演化而來，它就顯示大型掠食者如何演化。"},{"en":"The word names a specific dinosaur.","zh":"這個詞指一種特定恐龍。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":13},{"front":"Tyrannosaurus","meaning":"暴龍","examples":[{"en":"Tyrannosaurus was one of the famous large predatory dinosaurs.","zh":"暴龍是著名的大型掠食性恐龍之一。"},{"en":"Tyrannosaurus is a well-known meat-eating dinosaur from the late Cretaceous period.","zh":"Tyrannosaurus 是白堊紀晚期一種著名食肉恐龍。"},{"en":"Many children recognise Tyrannosaurus because of films and museum displays.","zh":"許多孩子因電影和博物館展示而認識暴龍。"},{"en":"If Tyrannosaurus appears in popular media, it often represents dinosaur power and danger.","zh":"如果暴龍出現在大眾媒體中，它常代表恐龍的力量和危險。"},{"en":"The word names a specific dinosaur often called T. rex.","zh":"這個詞指一種特定恐龍，常稱為 T. rex。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":13},{"front":"20 per cent bigger than","meaning":"比……大百分之二十","examples":[{"en":"Eubrontes was already 20 per cent bigger than any Triassic theropod track.","zh":"Eubrontes 已經比任何三疊紀獸腳類足跡大百分之二十。"},{"en":"20 per cent bigger than means one-fifth larger than something else.","zh":"20 per cent bigger than 指比另一事物大五分之一。"},{"en":"A classroom that is 20 per cent bigger than the old one can hold more students.","zh":"比舊課室大百分之二十的新課室可以容納更多學生。"},{"en":"If a footprint is 20 per cent bigger than earlier tracks, the animal may have been larger.","zh":"如果足印比早期足跡大百分之二十，該動物可能更大。"},{"en":"The phrase gives a precise size comparison.","zh":"這個片語給出精確大小比較。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":14},{"front":"track recorded from","meaning":"從……記錄到的足跡","examples":[{"en":"Eubrontes was larger than any theropod track recorded from the Triassic.","zh":"Eubrontes 比任何從三疊紀記錄到的獸腳類足跡都大。"},{"en":"Track recorded from means a footprint documented as coming from a particular time or place.","zh":"track recorded from 指被記錄為來自某時期或地點的足印。"},{"en":"A bird track recorded from a wetland can help show which species visited.","zh":"從濕地記錄到的鳥類足跡，可以幫助顯示哪些物種曾到訪。"},{"en":"If a dinosaur track recorded from one period is smaller, later larger tracks may show rapid growth.","zh":"如果從某時期記錄到的恐龍足跡較小，後來較大足跡可能顯示快速增長。"},{"en":"The phrase links evidence with its source period or location.","zh":"這個片語把證據與其來源時期或地點連接起來。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":14},{"front":"explanation for","meaning":"對……的解釋","examples":[{"en":"The researchers suggest an explanation for the rapid increase in size.","zh":"研究人員提出對體型快速增大的解釋。"},{"en":"An explanation for something is a reason that helps people understand why it happened.","zh":"explanation for 指幫助人理解某事為何發生的原因。"},{"en":"A doctor may look for an explanation for a patient’s repeated headaches.","zh":"醫生可能尋找病人反覆頭痛的解釋。"},{"en":"If there is an explanation for rapid growth, it should fit the evidence.","zh":"如果有對快速增長的解釋，它應符合證據。"},{"en":"The phrase introduces a reason or cause.","zh":"這個片語引出理由或原因。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":14},{"front":"rapid increase in size","meaning":"體型快速增大","examples":[{"en":"Ecological release may explain the rapid increase in size.","zh":"生態釋放可能解釋體型快速增大。"},{"en":"Rapid increase in size means becoming larger very quickly.","zh":"rapid increase in size 指非常迅速地變大。"},{"en":"A puppy may show a rapid increase in size during its first year.","zh":"小狗在第一年可能顯示體型快速增大。"},{"en":"If animals face fewer competitors, a rapid increase in size may occur over generations.","zh":"如果動物面對較少競爭者，體型可能在數代間快速增大。"},{"en":"The phrase focuses on fast physical growth.","zh":"這個片語集中於快速身體增長。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":14},{"front":"a phenomenon called","meaning":"一種稱為……的現象","examples":[{"en":"The explanation may be a phenomenon called ecological release.","zh":"解釋可能是一種稱為生態釋放的現象。"},{"en":"A phenomenon called means a process or event known by a particular name.","zh":"a phenomenon called 指以某個特定名稱為人所知的過程或事件。"},{"en":"A teacher may explain a phenomenon called evaporation using a cup of hot water.","zh":"老師可能用一杯熱水解釋一種稱為蒸發的現象。"},{"en":"If scientists identify a phenomenon called ecological release, they can compare modern and ancient examples.","zh":"如果科學家識別出一種稱為生態釋放的現象，就可以比較現代和古代例子。"},{"en":"The phrase introduces a named concept.","zh":"這個片語引出已命名概念。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":14},{"front":"ecological release","meaning":"生態釋放","examples":[{"en":"Ecological release may explain the dinosaurs’ rapid growth.","zh":"生態釋放可能解釋恐龍的快速增長。"},{"en":"Ecological release happens when a species expands or changes after competitors or predators disappear.","zh":"ecological release 指當競爭者或捕食者消失後，某物種擴張或改變。"},{"en":"Island animals may grow larger after ecological release because they face fewer rivals.","zh":"島嶼動物在生態釋放後可能長得更大，因為牠們面對較少競爭者。"},{"en":"If dinosaurs experienced ecological release, they could flourish after other reptiles died out.","zh":"如果恐龍經歷生態釋放，牠們可在其他爬行動物滅絕後蓬勃發展。"},{"en":"The phrase explains growth caused by reduced ecological pressure.","zh":"這個片語解釋由生態壓力減少造成的增長。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":14},{"front":"be seen today","meaning":"現今仍可見於","examples":[{"en":"This phenomenon is seen today when reptiles reach islands.","zh":"這種現象現今仍可見於爬行動物到達島嶼時。"},{"en":"Be seen today means can still be observed in the modern world.","zh":"be seen today 指現今世界仍可被觀察到。"},{"en":"Traditional cooking methods are still seen today in some village festivals.","zh":"傳統烹調方法現今仍可見於一些村莊節日。"},{"en":"If ecological release is seen today, it can help explain ancient patterns.","zh":"如果生態釋放現今仍可見，它就能幫助解釋古代模式。"},{"en":"The phrase links present evidence with past interpretation.","zh":"這個片語把現代證據與過去解釋連接起來。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":14},{"front":"face no competitors","meaning":"沒有競爭者","examples":[{"en":"Some reptiles grow larger when they face no competitors.","zh":"有些爬行動物在沒有競爭者時會長得更大。"},{"en":"Face no competitors means have no other rivals competing for the same resources.","zh":"face no competitors 指沒有其他對手競爭相同資源。"},{"en":"A small shop may grow quickly if it faces no competitors nearby.","zh":"如果附近沒有競爭者，小店可能迅速增長。"},{"en":"If island reptiles face no competitors, they may expand into new ecological roles.","zh":"如果島嶼爬行動物沒有競爭者，牠們可能擴展到新的生態角色。"},{"en":"The phrase explains why growth may become easier.","zh":"這個片語解釋為何增長可能變得更容易。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":14},{"front":"the most spectacular example","meaning":"最壯觀的例子","examples":[{"en":"The most spectacular example is on the island of Komodo.","zh":"最壯觀的例子是在科莫多島上。"},{"en":"The most spectacular example means the most impressive or striking case.","zh":"the most spectacular example 指最令人印象深刻或最突出的案例。"},{"en":"The city’s fireworks show is the most spectacular example of its festival tradition.","zh":"城市的煙花表演是其節日傳統最壯觀的例子。"},{"en":"If one island shows extreme animal growth, it may be the most spectacular example of the pattern.","zh":"如果一個島嶼顯示極端動物增長，它可能是該模式最壯觀的例子。"},{"en":"The phrase highlights the strongest illustration.","zh":"這個片語強調最有力的例證。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":14},{"front":"Indonesian island of Komodo","meaning":"印尼科莫多島","examples":[{"en":"Komodo is an Indonesian island famous for giant lizards.","zh":"科莫多是印尼一個以巨型蜥蜴聞名的島嶼。"},{"en":"The Indonesian island of Komodo is an island in Indonesia known for Komodo dragons.","zh":"Indonesian island of Komodo 是印尼一個以科莫多龍聞名的島嶼。"},{"en":"Travellers may visit the Indonesian island of Komodo to see wildlife with guides.","zh":"旅客可能到印尼科莫多島，在導遊帶領下觀看野生動物。"},{"en":"If local lizards became huge on Komodo, the island helps illustrate ecological release.","zh":"如果本地蜥蜴在科莫多島變得巨大，該島就有助說明生態釋放。"},{"en":"The phrase identifies a specific place.","zh":"這個片語指出特定地方。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":14},{"front":"local lizards","meaning":"本地蜥蜴","examples":[{"en":"Local lizards on Komodo have grown very large.","zh":"科莫多島上的本地蜥蜴已長得很大。"},{"en":"Local lizards are lizard species living naturally in a particular area.","zh":"local lizards 是自然生活在某特定地區的蜥蜴物種。"},{"en":"Children may see local lizards on walls in warm neighbourhoods.","zh":"孩子可能在溫暖社區的牆上看到本地蜥蜴。"},{"en":"If local lizards face few competitors, they may grow or behave differently over time.","zh":"如果本地蜥蜴面對較少競爭者，牠們可能隨時間長大或改變行為。"},{"en":"The phrase refers to animals native to or established in a place.","zh":"這個片語指原生於或定居於某地的動物。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":15},{"front":"grow so large that","meaning":"長得如此巨大以致……","examples":[{"en":"The lizards have grown so large that they are called dragons.","zh":"這些蜥蜴長得如此巨大，以致被稱為龍。"},{"en":"Grow so large that means become big enough to cause a particular result or reaction.","zh":"grow so large that 指長得大到造成某種結果或反應。"},{"en":"The tree grew so large that it blocked the classroom windows.","zh":"那棵樹長得如此巨大，以致擋住課室窗戶。"},{"en":"If lizards grow so large that people call them dragons, their size is extraordinary.","zh":"如果蜥蜴長得如此巨大，以致人們稱牠們為龍，牠們的體型就非常驚人。"},{"en":"The phrase links size with consequence.","zh":"這個片語把大小與結果連接起來。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":15},{"front":"be referred to as","meaning":"被稱為","examples":[{"en":"The lizards are referred to as dragons.","zh":"這些蜥蜴被稱為龍。"},{"en":"Be referred to as means be called or described by a particular name.","zh":"be referred to as 指被稱作或描述為某個名稱。"},{"en":"A school nurse may be referred to as the health officer in official documents.","zh":"學校護士在官方文件中可能被稱為健康主任。"},{"en":"If lizards are referred to as dragons, the name highlights their impressive size.","zh":"如果蜥蜴被稱為龍，這個名稱突出牠們驚人的體型。"},{"en":"The phrase introduces a label or title.","zh":"這個片語引出標籤或稱號。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":15},{"front":"in other words","meaning":"換言之","examples":[{"en":"In other words, dinosaurs could flourish only after competitors disappeared.","zh":"換言之，恐龍只有在競爭者消失後才能蓬勃發展。"},{"en":"In other words means saying the same idea more clearly or simply.","zh":"in other words 指用更清楚或簡單方式表達同一想法。"},{"en":"The bus is unreliable; in other words, students cannot depend on it every morning.","zh":"巴士不可靠；換言之，學生不能每天早上依賴它。"},{"en":"If competitors disappeared, in other words, dinosaurs had more ecological room.","zh":"如果競爭者消失，換言之，恐龍有更多生態空間。"},{"en":"The phrase introduces a clearer restatement.","zh":"這個片語引出更清楚的重述。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":15},{"front":"flourish","meaning":"蓬勃發展","examples":[{"en":"Dinosaurs could flourish only when competition had been removed.","zh":"只有當競爭被移除時，恐龍才能蓬勃發展。"},{"en":"Flourish means grow, succeed, or develop strongly.","zh":"flourish 指強健地生長、成功或發展。"},{"en":"A student can flourish when teachers give clear feedback and encouragement.","zh":"當老師給予清晰回饋和鼓勵，學生可以蓬勃發展。"},{"en":"If competition is removed, some species can flourish and spread quickly.","zh":"如果競爭被移除，有些物種可以蓬勃發展並迅速擴散。"},{"en":"The word suggests healthy and successful growth.","zh":"這個詞暗示健康而成功的增長。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":15},{"front":"competition had been knocked out","meaning":"競爭對手已被淘汰","examples":[{"en":"The dinosaurs flourished when the competition had been knocked out.","zh":"當競爭對手已被淘汰時，恐龍便蓬勃發展。"},{"en":"Competition had been knocked out means rivals had been removed or eliminated.","zh":"competition had been knocked out 指競爭者已被移除或消滅。"},{"en":"A shop may grow quickly after nearby competition has been knocked out by high rent.","zh":"附近競爭對手因高租金被淘汰後，商店可能迅速增長。"},{"en":"If other reptiles were knocked out, dinosaurs could take over more ecological roles.","zh":"如果其他爬行動物被淘汰，恐龍就能接管更多生態角色。"},{"en":"The phrase is informal and suggests sudden removal of rivals.","zh":"這個片語較口語，暗示競爭者突然被移除。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":15},{"front":"leave the question of","meaning":"留下……的問題","examples":[{"en":"That leaves the question of where the impact happened.","zh":"這留下了撞擊發生在哪裡的問題。"},{"en":"Leave the question of means leave one issue still unanswered.","zh":"leave the question of 指仍留下某個問題未解答。"},{"en":"The report explains the cost but leaves the question of who will pay.","zh":"報告解釋了成本，但留下了誰付款的問題。"},{"en":"If evidence supports an impact, it still leaves the question of where the crater is.","zh":"如果證據支持撞擊，它仍留下隕石坑在哪裡的問題。"},{"en":"The phrase introduces an unresolved issue.","zh":"這個片語引出未解決問題。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":15},{"front":"large crater","meaning":"大型隕石坑","examples":[{"en":"No large crater in the earth’s crust seems to be 202 million years old.","zh":"地殼中似乎沒有大型隕石坑是二億零二百萬年前形成的。"},{"en":"A large crater is a big bowl-shaped depression formed by impact, explosion, or eruption.","zh":"large crater 是由撞擊、爆炸或噴發形成的大型碗狀凹陷。"},{"en":"A meteor impact can leave a large crater visible from above.","zh":"隕石撞擊可以留下從高處可見的大型隕石坑。"},{"en":"If no large crater matches the date, scientists must consider other explanations.","zh":"如果沒有大型隕石坑符合日期，科學家必須考慮其他解釋。"},{"en":"The phrase refers to a major physical mark on Earth’s surface or crust.","zh":"這個片語指地球表面或地殼上的重大實體痕跡。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":15},{"front":"the earth’s crust","meaning":"地殼","examples":[{"en":"No large crater in the earth’s crust seems to match the date.","zh":"地殼中似乎沒有大型隕石坑符合該日期。"},{"en":"The earth’s crust is the outer solid layer of the planet.","zh":"the earth’s crust 是地球最外層的固體層。"},{"en":"Earthquakes happen when parts of the earth’s crust move suddenly.","zh":"當地殼部分突然移動時，地震便會發生。"},{"en":"If an impact crater lies in the earth’s crust, erosion may later hide it.","zh":"如果撞擊坑位於地殼中，侵蝕日後可能把它隱藏。"},{"en":"The phrase refers to the rocky outer shell of Earth.","zh":"這個片語指地球岩石外殼。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":15},{"front":"may have been overlooked","meaning":"可能被忽略","examples":[{"en":"The crater may have been overlooked.","zh":"該隕石坑可能被忽略。"},{"en":"May have been overlooked means might have been missed or not noticed.","zh":"may have been overlooked 指可能被錯過或沒有注意到。"},{"en":"A spelling mistake may have been overlooked during quick proofreading.","zh":"快速校對時，拼寫錯誤可能被忽略。"},{"en":"If a crater is buried or eroded, it may have been overlooked by scientists.","zh":"如果隕石坑被埋藏或侵蝕，它可能被科學家忽略。"},{"en":"The phrase suggests a possible missed detail.","zh":"這個片語暗示可能漏看了某個細節。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":15},{"front":"eroded and buried","meaning":"被侵蝕並埋藏","examples":[{"en":"Old craters are eroded and buried.","zh":"古老隕石坑會被侵蝕並埋藏。"},{"en":"Eroded and buried means worn away by natural forces and covered by later material.","zh":"eroded and buried 指被自然力量磨蝕，並被後來物質覆蓋。"},{"en":"An old road may be eroded and buried under soil after many years.","zh":"舊道路多年後可能被侵蝕並埋在泥土下。"},{"en":"If craters are eroded and buried, they become hard to recognise.","zh":"如果隕石坑被侵蝕並埋藏，就會變得難以辨認。"},{"en":"The phrase describes how geological evidence can be hidden over time.","zh":"這個片語描述地質證據如何隨時間被隱藏。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":16},{"front":"not always easy to find","meaning":"並不總是容易找到","examples":[{"en":"Old craters are not always easy to find.","zh":"古老隕石坑並不總是容易找到。"},{"en":"Not always easy to find means sometimes difficult to locate or identify.","zh":"not always easy to find 指有時難以定位或識別。"},{"en":"Old family records are not always easy to find in a crowded flat.","zh":"在擠迫單位中，舊家庭紀錄並不總是容易找到。"},{"en":"If evidence is eroded and buried, it is not always easy to find.","zh":"如果證據被侵蝕並埋藏，就並不總是容易找到。"},{"en":"The phrase warns that absence of discovery is not proof of absence.","zh":"這個片語提醒，沒有發現不等於不存在。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":16},{"front":"alternatively","meaning":"或者","examples":[{"en":"Alternatively, the crater may have vanished.","zh":"或者，該隕石坑可能已經消失。"},{"en":"Alternatively means as another possible explanation or choice.","zh":"alternatively 指作為另一個可能解釋或選擇。"},{"en":"We can take the bus; alternatively, we can walk if the weather is good.","zh":"我們可以乘巴士；或者，如果天氣好，可以步行。"},{"en":"If the crater was not overlooked, alternatively it may have been destroyed.","zh":"如果隕石坑不是被忽略，或者它可能已被摧毀。"},{"en":"The word introduces a different possibility.","zh":"這個詞引出另一種可能性。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":16},{"front":"have vanished","meaning":"已經消失","examples":[{"en":"The crater may have vanished.","zh":"該隕石坑可能已經消失。"},{"en":"Have vanished means have disappeared completely.","zh":"have vanished 指已完全消失。"},{"en":"The chalk marks on the playground have vanished after the rain.","zh":"操場上的粉筆痕跡在雨後已經消失。"},{"en":"If an ocean-floor crater has vanished, tectonic processes may have destroyed it.","zh":"如果海床隕石坑已經消失，板塊構造過程可能已摧毀它。"},{"en":"The phrase suggests no visible trace remains.","zh":"這個片語暗示沒有可見痕跡留下。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":16},{"front":"continental crust","meaning":"大陸地殼","examples":[{"en":"The continental crust is more or less permanent.","zh":"大陸地殼或多或少是永久的。"},{"en":"Continental crust is the thick outer rock layer that forms Earth’s continents.","zh":"continental crust 是形成地球大陸的厚外層岩石。"},{"en":"Geology students compare continental crust with oceanic crust.","zh":"地質學生會比較大陸地殼和海洋地殼。"},{"en":"If continental crust lasts for a very long time, old craters there may survive longer.","zh":"如果大陸地殼能維持很長時間，那裡的舊隕石坑可能保存更久。"},{"en":"The phrase refers to the crust beneath continents.","zh":"這個片語指大陸下方的地殼。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":16},{"front":"more or less permanent","meaning":"或多或少是永久的","examples":[{"en":"The continental crust is more or less permanent.","zh":"大陸地殼或多或少是永久的。"},{"en":"More or less permanent means mostly lasting for a very long time, though not absolutely forever.","zh":"more or less permanent 指大致上會維持很長時間，但並非絕對永遠。"},{"en":"A school building may be more or less permanent, while classroom posters change often.","zh":"校舍可能或多或少是永久的，而課室海報經常更換。"},{"en":"If a structure is more or less permanent, it can preserve evidence for longer.","zh":"如果一個結構或多或少是永久的，它可以保存證據更久。"},{"en":"The phrase softens a strong statement.","zh":"這個片語弱化一個強烈陳述。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":16},{"front":"ocean floor","meaning":"海床","examples":[{"en":"The ocean floor is constantly recycled.","zh":"海床不斷被循環再造。"},{"en":"The ocean floor is the seabed beneath the oceans.","zh":"ocean floor 是海洋下方的海底地面。"},{"en":"Scientists map the ocean floor to study mountains, trenches, and plate movement.","zh":"科學家繪製海床地圖，以研究山脈、海溝和板塊移動。"},{"en":"If a crater forms on the ocean floor, it may later be destroyed by geological processes.","zh":"如果隕石坑形成於海床，它日後可能被地質過程摧毀。"},{"en":"The phrase refers to the solid surface under seawater.","zh":"這個片語指海水下方的固體表面。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":16},{"front":"be constantly recycled","meaning":"不斷被循環再造","examples":[{"en":"The ocean floor is constantly recycled by tectonic processes.","zh":"海床不斷被板塊構造過程循環再造。"},{"en":"Be constantly recycled means be repeatedly destroyed and replaced over time.","zh":"be constantly recycled 指隨時間反覆被摧毀和取代。"},{"en":"Classroom paper can be constantly recycled if students put it in the correct bin.","zh":"如果學生把紙放進正確回收箱，課室紙張可以不斷被循環再用。"},{"en":"If the ocean floor is constantly recycled, very old ocean craters may not survive.","zh":"如果海床不斷被循環再造，非常古老的海洋隕石坑可能無法保存。"},{"en":"The phrase describes repeated renewal.","zh":"這個片語描述反覆更新。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":16},{"front":"tectonic processes","meaning":"板塊構造過程","examples":[{"en":"Tectonic processes can recycle the ocean floor.","zh":"板塊構造過程可以循環再造海床。"},{"en":"Tectonic processes are movements and interactions of Earth’s crustal plates.","zh":"tectonic processes 是地殼板塊的移動和相互作用。"},{"en":"Earthquakes and mountain building are linked to tectonic processes.","zh":"地震和造山運動都與板塊構造過程有關。"},{"en":"If tectonic processes pull ocean floor into Earth, old impact craters can disappear.","zh":"如果板塊構造過程把海床拉入地球內部，舊撞擊坑可以消失。"},{"en":"The phrase refers to large-scale geological movement.","zh":"這個片語指大規模地質運動。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":16},{"front":"continental drift","meaning":"大陸漂移","examples":[{"en":"Tectonic processes bring about continental drift.","zh":"板塊構造過程導致大陸漂移。"},{"en":"Continental drift is the slow movement of continents across Earth’s surface.","zh":"continental drift 是大陸在地球表面緩慢移動。"},{"en":"Students learn continental drift by fitting South America and Africa together on a map.","zh":"學生透過在地圖上把南美洲和非洲拼合來學習大陸漂移。"},{"en":"If continental drift moves land over millions of years, ancient climates and fossils shift positions.","zh":"如果大陸漂移使陸地在數百萬年間移動，古氣候和化石位置也會改變。"},{"en":"The phrase describes long-term movement of continents.","zh":"這個片語描述大陸的長期移動。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":16},{"front":"no ocean floor left","meaning":"沒有留下的海床","examples":[{"en":"There is no ocean floor left that is more than 200 million years old.","zh":"沒有留下超過二億年歷史的海床。"},{"en":"No ocean floor left means none of the old seabed remains today.","zh":"no ocean floor left 指舊海床如今沒有任何部分留下。"},{"en":"After redevelopment, there may be no old houses left on a street.","zh":"重建後，一條街上可能沒有舊房子留下。"},{"en":"If no ocean floor is left from that age, an ocean impact crater cannot be found there.","zh":"如果沒有那個年代的海床留下，就不能在那裡找到海洋撞擊坑。"},{"en":"The phrase stresses complete absence of surviving material.","zh":"這個片語強調沒有保存下來的材料。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":17},{"front":"be swallowed up","meaning":"被吞沒","examples":[{"en":"A crater formed in the ocean would have been swallowed up.","zh":"形成於海洋中的隕石坑會被吞沒。"},{"en":"Be swallowed up means be absorbed, covered, or destroyed by something larger.","zh":"be swallowed up 指被更大的東西吸收、覆蓋或摧毀。"},{"en":"A small shop can be swallowed up by a large shopping centre.","zh":"小店可以被大型商場吞併。"},{"en":"If an ocean crater is swallowed up by tectonic movement, no visible trace may remain.","zh":"如果海洋隕石坑被板塊運動吞沒，可能沒有可見痕跡留下。"},{"en":"The phrase suggests being completely taken in or lost.","zh":"這個片語暗示被完全吸收或失去。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":17},{"front":"by now","meaning":"到現在","examples":[{"en":"The ocean crater would have been swallowed up by now.","zh":"該海洋隕石坑到現在應已被吞沒。"},{"en":"By now means before or at the present time.","zh":"by now 指在現在之前或到現在這個時候。"},{"en":"The bus should have arrived by now if it left on schedule.","zh":"如果巴士準時出發，到現在應該已到達。"},{"en":"If an ocean crater formed long ago, it may have disappeared by now.","zh":"如果海洋隕石坑很久以前形成，到現在可能已經消失。"},{"en":"The phrase compares expected results with the present moment.","zh":"這個片語把預期結果與現在作比較。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":17},{"front":"a third possibility","meaning":"第三種可能性","examples":[{"en":"There is a third possibility about the missing crater.","zh":"關於消失的隕石坑，有第三種可能性。"},{"en":"A third possibility means another explanation after two have already been mentioned.","zh":"a third possibility 指在已有兩個解釋後的另一個解釋。"},{"en":"We can walk or take the bus; a third possibility is calling a taxi.","zh":"我們可以步行或乘巴士；第三種可能性是叫的士。"},{"en":"If two crater explanations fail, a third possibility may be misdating.","zh":"如果兩個隕石坑解釋都不成立，第三種可能性可能是定年錯誤。"},{"en":"The phrase adds another option to the discussion.","zh":"這個片語為討論加入另一選項。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":17},{"front":"be known but misdated","meaning":"已知但定年錯誤","examples":[{"en":"The crater may be known but misdated.","zh":"該隕石坑可能已知但定年錯誤。"},{"en":"Be known but misdated means already identified but given the wrong age.","zh":"be known but misdated 指已被識別，但被賦予錯誤年代。"},{"en":"A family photo may be known but misdated if relatives remember the wrong year.","zh":"如果親戚記錯年份，一張家庭照片可能已知但日期錯誤。"},{"en":"If a crater is known but misdated, scientists may need to recheck its age.","zh":"如果隕石坑已知但定年錯誤，科學家可能需要重新檢查其年代。"},{"en":"The phrase separates discovery from correct dating.","zh":"這個片語把發現與正確定年分開。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":17},{"front":"Manicouagan structure","meaning":"馬尼夸根結構","examples":[{"en":"The Manicouagan structure is a crater in Quebec.","zh":"馬尼夸根結構是魁北克的一個隕石坑。"},{"en":"The Manicouagan structure is a large geological feature believed to be an impact crater.","zh":"Manicouagan structure 是一個大型地質構造，被認為是撞擊坑。"},{"en":"Students may study the Manicouagan structure when learning about ancient impacts.","zh":"學生學習古代撞擊時可能研究馬尼夸根結構。"},{"en":"If the Manicouagan structure is misdated, it could change theories about the ancient impact.","zh":"如果馬尼夸根結構定年錯誤，它可能改變關於古代撞擊的理論。"},{"en":"The phrase names a specific geological structure.","zh":"這個片語指特定地質構造。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":17},{"front":"crater in Quebec","meaning":"魁北克的隕石坑","examples":[{"en":"The Manicouagan structure is a crater in Quebec.","zh":"馬尼夸根結構是魁北克的隕石坑。"},{"en":"A crater in Quebec means an impact or geological depression located in the Canadian province of Quebec.","zh":"crater in Quebec 指位於加拿大魁北克省的撞擊或地質凹陷。"},{"en":"A tourist might visit a crater in Quebec to see unusual landforms.","zh":"遊客可能到訪魁北克的隕石坑，以觀看不尋常地貌。"},{"en":"If a crater in Quebec matches the right age, it could support an impact theory.","zh":"如果魁北克的隕石坑符合正確年代，它可能支持撞擊理論。"},{"en":"The phrase identifies both the landform and its location.","zh":"這個片語同時指出地貌和位置。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":17},{"front":"be thought to be","meaning":"被認為是","examples":[{"en":"The crater is thought to be 214 million years old.","zh":"該隕石坑被認為是二億一千四百萬年前形成的。"},{"en":"Be thought to be means people believe or estimate something, though it may not be certain.","zh":"be thought to be 指人們相信或估計某事，但未必完全確定。"},{"en":"The old building is thought to be over 100 years old.","zh":"這座舊建築被認為已有超過一百年歷史。"},{"en":"If a crater is thought to be too old, new dating may change its relevance.","zh":"如果隕石坑被認為年代太早，新的定年可能改變其相關性。"},{"en":"The phrase shows uncertainty or accepted belief.","zh":"這個片語顯示不確定或公認看法。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":17},{"front":"some 100 km across","meaning":"直徑約100公里","examples":[{"en":"The crater is huge, some 100 km across.","zh":"該隕石坑很巨大，直徑約100公里。"},{"en":"Some 100 km across means approximately 100 kilometres wide.","zh":"some 100 km across 指寬度約為100公里。"},{"en":"A storm some 100 km across can affect several towns at once.","zh":"直徑約100公里的風暴可以同時影響幾個城鎮。"},{"en":"If a crater is some 100 km across, the impact that made it was enormous.","zh":"如果隕石坑直徑約100公里，造成它的撞擊必定巨大。"},{"en":"The phrase gives an approximate size.","zh":"這個片語給出大約大小。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":17},{"front":"the largest of between…and…","meaning":"在三至五個之中最大","examples":[{"en":"The crater seems to be the largest of between three and five craters.","zh":"該隕石坑似乎是在三至五個隕石坑之中最大的。"},{"en":"The largest of between…and means the biggest one among an estimated range of items.","zh":"the largest of between…and 指在估計數量範圍內最大的那一個。"},{"en":"This hall is the largest of between three and five venues being considered.","zh":"這個禮堂是在三至五個考慮場地之中最大的。"},{"en":"If one crater is the largest of several related craters, it may mark the biggest fragment impact.","zh":"如果一個隕石坑是幾個相關隕石坑中最大的，它可能標示最大碎片撞擊。"},{"en":"The phrase handles uncertainty in the total number.","zh":"這個片語處理總數不確定的情況。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":17},{"front":"within a few hours of each other","meaning":"相隔數小時內","examples":[{"en":"The craters formed within a few hours of each other.","zh":"這些隕石坑在相隔數小時內形成。"},{"en":"Within a few hours of each other means separated by only several hours.","zh":"within a few hours of each other 指彼此只相隔數小時。"},{"en":"Three students submitted their applications within a few hours of each other.","zh":"三名學生在相隔數小時內提交申請。"},{"en":"If craters formed within a few hours of each other, they may be linked to one broken object.","zh":"如果隕石坑在相隔數小時內形成，它們可能與同一個破裂物體有關。"},{"en":"The phrase shows very close timing.","zh":"這個片語顯示時間非常接近。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":18},{"front":"lumps of","meaning":"……的碎塊","examples":[{"en":"The craters were made by lumps of a disintegrated comet.","zh":"這些隕石坑由解體彗星的碎塊造成。"},{"en":"Lumps of means pieces or chunks of something.","zh":"lumps of 指某物的塊狀碎片。"},{"en":"A cook may add lumps of butter to flour before making pastry.","zh":"廚師製作酥皮前可能把牛油碎塊加入麵粉。"},{"en":"If lumps of a comet hit Earth, they can create several craters.","zh":"如果彗星碎塊撞擊地球，它們可以造成幾個隕石坑。"},{"en":"The phrase describes irregular pieces of material.","zh":"這個片語描述不規則物質碎片。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":18},{"front":"disintegrated comet","meaning":"解體的彗星","examples":[{"en":"The craters may have formed as a disintegrated comet hit the earth.","zh":"這些隕石坑可能是在解體的彗星撞擊地球時形成的。"},{"en":"A disintegrated comet is a comet that has broken into separate pieces.","zh":"disintegrated comet 是已分裂成多個碎片的彗星。"},{"en":"Astronomers may track a disintegrated comet if its fragments move near Earth.","zh":"如果解體的彗星碎片移近地球，天文學家可能追蹤它們。"},{"en":"If a disintegrated comet strikes a planet, it may produce several impacts instead of one.","zh":"如果解體的彗星撞擊行星，它可能造成多次撞擊，而不是一次。"},{"en":"The phrase describes a broken space object.","zh":"這個片語描述破裂的太空物體。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":18},{"front":"one by one","meaning":"一個接一個","examples":[{"en":"The lumps hit the earth one by one.","zh":"這些碎塊一個接一個撞擊地球。"},{"en":"One by one means separately and in sequence.","zh":"one by one 指逐個並按次序。"},{"en":"Students entered the exam room one by one after showing their ID cards.","zh":"學生出示身份證後，一個接一個進入試場。"},{"en":"If comet fragments hit Earth one by one, several craters may form close in time.","zh":"如果彗星碎片一個接一個撞擊地球，幾個隕石坑可能在相近時間形成。"},{"en":"The phrase emphasises order and separation.","zh":"這個片語強調次序和分開發生。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":18},{"front":"agree with the views of","meaning":"與……的觀點一致","examples":[{"en":"Students decide whether statements agree with the views of the writer.","zh":"學生判斷陳述是否與作者觀點一致。"},{"en":"Agree with the views of means match what someone thinks or argues.","zh":"agree with the views of 指與某人的想法或論點相符。"},{"en":"In a reading test, students check whether a statement agrees with the writer’s view.","zh":"在閱讀測驗中，學生檢查陳述是否與作者觀點一致。"},{"en":"If a sentence changes the writer’s opinion, it does not agree with the views of the writer.","zh":"如果句子改變作者意見，它就不與作者觀點一致。"},{"en":"The phrase is common in YES, NO, NOT GIVEN questions.","zh":"這個片語常見於 YES、NO、NOT GIVEN 題目。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":18},{"front":"contradict the views of","meaning":"與……的觀點相矛盾","examples":[{"en":"Students write NO if a statement contradicts the views of the writer.","zh":"如果陳述與作者觀點相矛盾，學生寫 NO。"},{"en":"Contradict the views of means oppose or say the opposite of someone’s opinion.","zh":"contradict the views of 指反對或說出與某人觀點相反的內容。"},{"en":"If a writer supports public transport, a statement praising car dependence may contradict the writer’s views.","zh":"如果作者支持公共交通，讚揚依賴私家車的陳述可能與作者觀點相矛盾。"},{"en":"If evidence contradicts the views of a researcher, the theory may need revision.","zh":"如果證據與研究者觀點相矛盾，理論可能需要修改。"},{"en":"The phrase shows disagreement with an expressed opinion.","zh":"這個片語顯示與已表達觀點不一致。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":18},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"Students write NOT GIVEN if it is impossible to say what the writer thinks.","zh":"如果無法判斷作者想法，學生寫 NOT GIVEN。"},{"en":"Impossible to say means there is not enough information to decide.","zh":"impossible to say 指沒有足夠資料作決定。"},{"en":"If a notice gives the opening time but not the closing time, it is impossible to say when the shop closes.","zh":"如果告示只給開門時間而沒有關門時間，就無法判斷商店何時關門。"},{"en":"If a passage never mentions the writer’s opinion, it is impossible to say whether they agree.","zh":"如果文章從未提及作者觀點，就無法判斷作者是否同意。"},{"en":"The phrase signals uncertainty due to missing evidence.","zh":"這個片語表示因缺乏證據而不確定。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":18},{"front":"lead to the rise of","meaning":"導致……崛起","examples":[{"en":"An asteroid impact may have led to the rise of the dinosaurs.","zh":"小行星撞擊可能導致恐龍崛起。"},{"en":"Lead to the rise of means cause a group, idea, or system to become powerful or important.","zh":"lead to the rise of 指導致某群體、想法或制度變得強大或重要。"},{"en":"Better internet access can lead to the rise of online learning.","zh":"更好的互聯網連接可以導致網上學習崛起。"},{"en":"If an impact removed competitors, it could lead to the rise of surviving dinosaurs.","zh":"如果撞擊移除競爭者，它可能導致倖存恐龍崛起。"},{"en":"The phrase links a cause with later dominance.","zh":"這個片語把原因與後來主導地位連接起來。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":18},{"front":"books and films such as","meaning":"例如……的書籍和電影","examples":[{"en":"Books and films such as Jurassic Park shape people’s view of dinosaurs.","zh":"例如《侏羅紀公園》的書籍和電影塑造人們對恐龍的看法。"},{"en":"Books and films such as means written and screen works like the example named.","zh":"books and films such as 指像所列例子那樣的書面和影像作品。"},{"en":"Books and films such as Harry Potter can influence how children imagine school and magic.","zh":"例如《哈利波特》的書籍和電影可以影響孩子如何想像學校和魔法。"},{"en":"If books and films such as Jurassic Park are popular, they can shape public ideas about science.","zh":"如果例如《侏羅紀公園》的書籍和電影很受歡迎，它們可以塑造公眾對科學的想法。"},{"en":"The phrase introduces examples from media.","zh":"這個片語引出媒體例子。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":18},{"front":"exaggerate the size of","meaning":"誇大……的大小","examples":[{"en":"The statement asks whether popular media exaggerate the size of dinosaurs.","zh":"該陳述問大眾媒體是否誇大恐龍的大小。"},{"en":"Exaggerate the size of means make something seem bigger than it really is.","zh":"exaggerate the size of 指令某物看起來比實際更大。"},{"en":"Advertisements may exaggerate the size of a hotel room by using wide-angle photos.","zh":"廣告可能用廣角照片誇大酒店房間大小。"},{"en":"If films exaggerate the size of animals, viewers may develop false ideas.","zh":"如果電影誇大動物大小，觀眾可能形成錯誤想法。"},{"en":"The phrase describes overstating physical size.","zh":"這個片語描述誇大實體大小。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":18},{"front":"provide more useful evidence than","meaning":"提供比……更有用的證據","examples":[{"en":"The question asks whether footprints provide more useful evidence than skeletons.","zh":"題目問足印是否提供比骨骼更有用的證據。"},{"en":"Provide more useful evidence than means give better or more helpful proof than another source.","zh":"provide more useful evidence than 指比另一來源提供更好或更有幫助的證據。"},{"en":"A video may provide more useful evidence than a memory in a traffic accident.","zh":"在交通意外中，影片可能提供比記憶更有用的證據。"},{"en":"If footprints are more common, they may provide more useful evidence than rare bones.","zh":"如果足印更常見，它們可能提供比罕見骨頭更有用的證據。"},{"en":"The phrase compares the value of two kinds of evidence.","zh":"這個片語比較兩種證據的價值。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":19},{"front":"dinosaur footprints","meaning":"恐龍足印","examples":[{"en":"Dinosaur footprints can be abundant evidence.","zh":"恐龍足印可以是豐富證據。"},{"en":"Dinosaur footprints are fossilised tracks left by dinosaurs walking on soft ground.","zh":"dinosaur footprints 是恐龍走過柔軟地面時留下並化石化的足跡。"},{"en":"Children may see dinosaur footprints in a museum and compare them with their own feet.","zh":"孩子可能在博物館看到恐龍足印，並把它們與自己的腳比較。"},{"en":"If dinosaur footprints are found in layers, they can help show when dinosaurs lived there.","zh":"如果恐龍足印在岩層中被發現，它們可幫助顯示恐龍何時生活在那裡。"},{"en":"The phrase refers to trace fossils, not bones.","zh":"這個片語指痕跡化石，而不是骨頭。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":19},{"front":"dinosaur skeletons","meaning":"恐龍骨骼","examples":[{"en":"Dinosaur skeletons are rarer than footprints.","zh":"恐龍骨骼比足印更罕見。"},{"en":"Dinosaur skeletons are preserved bone structures of dinosaurs.","zh":"dinosaur skeletons 是保存下來的恐龍骨骼結構。"},{"en":"A complete dinosaur skeleton can help scientists estimate body shape and posture.","zh":"完整恐龍骨骼可以幫助科學家估計身體形態和姿勢。"},{"en":"Because dinosaur skeletons are rare, footprints can become especially valuable evidence.","zh":"因為恐龍骨骼很罕見，足印可以成為特別有價值的證據。"},{"en":"The phrase refers to fossilised bones arranged as a body structure.","zh":"這個片語指作為身體結構保存的化石骨頭。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":19},{"front":"more detectable than","meaning":"比……更容易探測","examples":[{"en":"The question compares whether footprints are more detectable than magnetic evidence.","zh":"題目比較足印是否比磁場證據更容易探測。"},{"en":"More detectable than means easier to find, observe, or measure than something else.","zh":"more detectable than 指比另一事物更容易發現、觀察或量度。"},{"en":"A loud alarm is more detectable than a small warning light in a busy station.","zh":"在繁忙車站中，響亮警報比小警示燈更容易察覺。"},{"en":"If footprints are more detectable than chemical traces, fieldworkers may find them first.","zh":"如果足印比化學痕跡更容易探測，野外工作者可能先找到它們。"},{"en":"The phrase compares how easily evidence can be noticed.","zh":"這個片語比較證據有多容易被注意到。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":19},{"front":"evidence from the earth’s magnetic field","meaning":"來自地球磁場的證據","examples":[{"en":"Magnetic-field evidence can help date geological events.","zh":"磁場證據可以幫助為地質事件定年。"},{"en":"Evidence from the earth’s magnetic field is information preserved in rocks about past magnetic changes.","zh":"evidence from the earth’s magnetic field 是岩石中保存的關於過去磁場變化的資訊。"},{"en":"Scientists use evidence from the earth’s magnetic field to compare rock layers in different regions.","zh":"科學家使用來自地球磁場的證據，比較不同地區的岩層。"},{"en":"If magnetic evidence matches known reversals, it can help date ancient sediments.","zh":"如果磁場證據與已知逆轉吻合，它可以幫助為古代沉積物定年。"},{"en":"The phrase refers to geological evidence based on magnetism.","zh":"這個片語指基於磁性的地質證據。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":19},{"front":"dating geological events","meaning":"為地質事件定年","examples":[{"en":"Magnetic reversals help in dating geological events.","zh":"磁場逆轉有助為地質事件定年。"},{"en":"Dating geological events means estimating when Earth-history events happened.","zh":"dating geological events 指估計地球歷史事件何時發生。"},{"en":"Scientists date geological events by studying rocks, fossils, and chemical signals.","zh":"科學家透過研究岩石、化石和化學訊號為地質事件定年。"},{"en":"If researchers improve dating geological events, they can compare cause and effect more clearly.","zh":"如果研究人員改善為地質事件定年的方法，就能更清楚比較因果。"},{"en":"The phrase focuses on assigning time to ancient events.","zh":"這個片語集中於為古代事件指定時間。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":19},{"front":"to within a few thousand years","meaning":"精確至幾千年內","examples":[{"en":"The rocks can be dated to within a few thousand years.","zh":"這些岩石可精確至幾千年內定年。"},{"en":"To within a few thousand years means with an error range of only several thousand years.","zh":"to within a few thousand years 指誤差範圍只有數千年。"},{"en":"An old manuscript may be dated to within a few decades by paper and ink tests.","zh":"舊手稿可透過紙張和墨水測試精確至數十年內。"},{"en":"If rocks are dated to within a few thousand years, the timing is precise for deep history.","zh":"如果岩石精確至幾千年內定年，對深遠歷史而言已很精確。"},{"en":"The phrase describes a high level of dating accuracy.","zh":"這個片語描述高水平定年準確度。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":19},{"front":"be matched to","meaning":"與……配對","examples":[{"en":"The question asks whether footprints can be matched to exact species.","zh":"題目問足印能否與確切物種配對。"},{"en":"Be matched to means be connected correctly with a particular person, thing, or category.","zh":"be matched to 指與某個特定人物、事物或分類正確連接。"},{"en":"A lost key can be matched to a classroom by checking the label.","zh":"遺失鎖匙可以透過標籤與課室配對。"},{"en":"If footprints cannot be matched to exact species, scientists must use broader groups.","zh":"如果足印不能與確切物種配對，科學家就必須使用較廣泛群體。"},{"en":"The phrase describes accurate pairing.","zh":"這個片語描述準確配對。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":19},{"front":"exact species","meaning":"確切物種","examples":[{"en":"Ichnotaxa cannot be matched to exact species.","zh":"足跡分類單位不能與確切物種配對。"},{"en":"Exact species means the precise biological species, not just a general group.","zh":"exact species 指精確的生物物種，而不是大致群體。"},{"en":"A birdwatcher may know a bird is a duck but not the exact species.","zh":"觀鳥者可能知道一隻鳥是鴨，但不知道確切物種。"},{"en":"If fossils do not reveal exact species, researchers should avoid naming too specifically.","zh":"如果化石不能揭示確切物種，研究人員應避免命名得太具體。"},{"en":"The phrase emphasises precision in classification.","zh":"這個片語強調分類上的精確度。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":19},{"front":"be found at","meaning":"在……被發現","examples":[{"en":"The question asks where more iridium is found.","zh":"題目問更多銥在哪裡被發現。"},{"en":"Be found at means be located in a particular place or level.","zh":"be found at 指位於某個地方或層面。"},{"en":"The information desk can be found at the entrance of the library.","zh":"資訊櫃檯可在圖書館入口被找到。"},{"en":"If iridium is found at a boundary layer, it may be important evidence.","zh":"如果銥在邊界層被發現，它可能是重要證據。"},{"en":"The phrase identifies location.","zh":"這個片語指出位置。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":19},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Candidates complete the summary below using words from the passage.","zh":"考生使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the short text that follows.","zh":"complete the summary below 指在下方短文中填上缺失字詞。"},{"en":"In a reading test, candidates complete the summary below by locating key ideas in the passage.","zh":"在閱讀測驗中，考生透過定位文章中的關鍵意思完成以下摘要。"},{"en":"If candidates ignore the word limit, the summary answer may be marked wrong.","zh":"如果考生忽視字數限制，摘要答案可能被判錯。"},{"en":"The phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":20},{"front":"no more than two words","meaning":"不超過兩個詞","examples":[{"en":"Candidates choose no more than two words from the passage.","zh":"考生從文章中選擇不超過兩個詞。"},{"en":"No more than two words means one or two words only, not three or more.","zh":"no more than two words 指只能用一個或兩個詞，不能三個或以上。"},{"en":"If the answer is “fern spike”, it follows the no more than two words rule.","zh":"如果答案是 fern spike，它符合不超過兩個詞的規則。"},{"en":"If candidates write three words, the answer may be wrong even if the idea is correct.","zh":"如果考生寫三個詞，即使意思正確，答案也可能錯。"},{"en":"The phrase gives a strict word limit.","zh":"這個片語給出嚴格字數限制。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":20},{"front":"large size","meaning":"巨大體型","examples":[{"en":"Ecological release may explain the large size of Eubrontes.","zh":"生態釋放可能解釋 Eubrontes 的巨大體型。"},{"en":"Large size means being physically big compared with others.","zh":"large size 指與其他事物相比在身體上較大。"},{"en":"The large size of a classroom matters if thirty students need space to move.","zh":"如果三十名學生需要活動空間，課室巨大大小就很重要。"},{"en":"If a footprint has a large size, the animal that made it was probably large too.","zh":"如果足印體型巨大，留下它的動物很可能也很大。"},{"en":"The phrase describes physical scale.","zh":"這個片語描述實體規模。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":20},{"front":"native lizards","meaning":"本地蜥蜴","examples":[{"en":"Native lizards on Komodo grow very large.","zh":"科莫多島上的本地蜥蜴長得很大。"},{"en":"Native lizards are lizards that naturally live in a particular place.","zh":"native lizards 是自然生活在某特定地方的蜥蜴。"},{"en":"A wildlife guide may explain how native lizards differ from introduced species.","zh":"野生動物導遊可能解釋本地蜥蜴與外來物種有何不同。"},{"en":"If native lizards face no competitors, they may become unusually large over time.","zh":"如果本地蜥蜴沒有競爭者，牠們可能隨時間變得異常巨大。"},{"en":"The phrase refers to local animal species.","zh":"這個片語指本地動物物種。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":20},{"front":"no trace of","meaning":"沒有……的痕跡","examples":[{"en":"The question asks why no trace of the ancient impact has been found.","zh":"題目問為何沒有發現古代撞擊的痕跡。"},{"en":"No trace of means no sign, mark, or evidence of something.","zh":"no trace of 指沒有某事物的跡象、痕跡或證據。"},{"en":"After careful cleaning, there was no trace of paint on the floor.","zh":"仔細清潔後，地板上沒有油漆痕跡。"},{"en":"If there is no trace of a crater, scientists must explain why evidence disappeared.","zh":"如果沒有隕石坑痕跡，科學家必須解釋為何證據消失。"},{"en":"The phrase stresses complete lack of visible evidence.","zh":"這個片語強調完全缺乏可見證據。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":20},{"front":"ancient impact","meaning":"古代撞擊","examples":[{"en":"Scientists are searching for evidence of the ancient impact.","zh":"科學家正在尋找古代撞擊的證據。"},{"en":"An ancient impact is a collision that happened in the distant geological past.","zh":"ancient impact 是發生在遙遠地質過去的碰撞。"},{"en":"A crater, unusual minerals, or shocked rocks may provide evidence of an ancient impact.","zh":"隕石坑、異常礦物或受震岩石可能提供古代撞擊證據。"},{"en":"If an ancient impact occurred in the ocean, the crater may no longer exist.","zh":"如果古代撞擊發生在海洋中，隕石坑可能已不復存在。"},{"en":"The phrase refers to a very old collision event.","zh":"這個片語指非常古老的碰撞事件。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":20},{"front":"have overlooked the evidence","meaning":"忽略了證據","examples":[{"en":"One possibility is that scientists have overlooked the evidence.","zh":"一種可能性是科學家忽略了證據。"},{"en":"Have overlooked the evidence means have failed to notice important proof.","zh":"have overlooked the evidence 指沒有注意到重要證據。"},{"en":"A teacher may realise she has overlooked evidence of a student’s improvement.","zh":"老師可能意識到自己忽略了學生進步的證據。"},{"en":"If evidence is hard to see, even experts may have overlooked it.","zh":"如果證據難以看見，即使專家也可能忽略它。"},{"en":"The phrase suggests missing something that was already there.","zh":"這個片語暗示錯過了原本已存在的東西。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":20},{"front":"difficult to spot","meaning":"難以發現","examples":[{"en":"Old craters are difficult to spot.","zh":"古老隕石坑難以發現。"},{"en":"Difficult to spot means hard to see, notice, or identify.","zh":"difficult to spot 指難以看見、注意到或識別。"},{"en":"A small spelling mistake can be difficult to spot in a long essay.","zh":"長作文中的小拼寫錯誤可能難以發現。"},{"en":"If a crater is eroded and buried, it becomes difficult to spot from the surface.","zh":"如果隕石坑被侵蝕和埋藏，從地表看就會難以發現。"},{"en":"The phrase focuses on visual or practical difficulty in finding something.","zh":"這個片語集中於尋找某物的視覺或實際困難。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":20},{"front":"movements in the earth’s crust","meaning":"地殼運動","examples":[{"en":"The crater may have vanished because of movements in the earth’s crust.","zh":"該隕石坑可能因地殼運動而消失。"},{"en":"Movements in the earth’s crust are shifts of Earth’s outer rocky layer.","zh":"movements in the earth’s crust 是地球外層岩石的移動。"},{"en":"Earthquakes are caused by sudden movements in the earth’s crust.","zh":"地震由地殼突然運動造成。"},{"en":"If crustal movements destroy ocean floor, an ancient crater may vanish.","zh":"如果地殼運動摧毀海床，古代隕石坑可能消失。"},{"en":"The phrase explains geological change through plate movement.","zh":"這個片語透過板塊移動解釋地質變化。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":20},{"front":"crustal movement","meaning":"地殼運動","examples":[{"en":"A crater formed in the ocean could be swallowed up by crustal movement.","zh":"形成於海洋中的隕石坑可能被地殼運動吞沒。"},{"en":"Crustal movement is the movement of Earth’s outer rock layer.","zh":"crustal movement 是地球外層岩石的移動。"},{"en":"Crustal movement can raise mountains, open ocean basins, or cause earthquakes.","zh":"地殼運動可以抬升山脈、打開海盆或造成地震。"},{"en":"If crustal movement recycles the ocean floor, old impact evidence can disappear.","zh":"如果地殼運動循環再造海床，古老撞擊證據可以消失。"},{"en":"The phrase is a shorter way to discuss movements in the earth’s crust.","zh":"這個片語是討論地殼運動的較簡短說法。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":20},{"front":"potential evidence","meaning":"潛在證據","examples":[{"en":"The potential evidence may have been misdated.","zh":"潛在證據可能被錯誤定年。"},{"en":"Potential evidence means information or material that might support a claim.","zh":"potential evidence 指可能支持某主張的資料或材料。"},{"en":"A damaged CCTV video may be potential evidence in a school theft case.","zh":"受損閉路電視影片可能是學校盜竊案中的潛在證據。"},{"en":"If potential evidence is dated wrongly, it may be dismissed too quickly.","zh":"如果潛在證據被錯誤定年，它可能太快被排除。"},{"en":"The phrase suggests evidence that is possible but not yet certain.","zh":"這個片語暗示證據可能存在，但尚未確定。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":21},{"front":"one or more craters","meaning":"一個或多個隕石坑","examples":[{"en":"The potential evidence could be one or more craters.","zh":"潛在證據可能是一個或多個隕石坑。"},{"en":"One or more craters means at least one crater, and possibly several.","zh":"one or more craters 指至少一個隕石坑，也可能有幾個。"},{"en":"A field survey may find one or more holes that need further investigation.","zh":"實地調查可能發現一個或多個需要進一步調查的洞。"},{"en":"If one or more craters match an impact date, the theory gains support.","zh":"如果一個或多個隕石坑符合撞擊日期，該理論就得到支持。"},{"en":"The phrase allows for uncertainty in number.","zh":"這個片語容許數量上的不確定。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":21},{"front":"has been misdated","meaning":"被錯誤定年","examples":[{"en":"The crater may have been misdated.","zh":"該隕石坑可能被錯誤定年。"},{"en":"Has been misdated means has been assigned the wrong age or date.","zh":"has been misdated 指被賦予錯誤年代或日期。"},{"en":"A family photo has been misdated if the year written on the back is wrong.","zh":"如果家庭照片背面的年份寫錯，它就是被錯誤標日期。"},{"en":"If a crater has been misdated, it may actually belong to a different extinction event.","zh":"如果隕石坑被錯誤定年，它可能其實屬於另一場滅絕事件。"},{"en":"The phrase describes an error in dating evidence.","zh":"這個片語描述證據定年上的錯誤。"}],"source":"117 - The Dinosaurs Footprints and Extinction.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 118":[{"front":"effort and science to win","meaning":"爭勝所需的努力與科學","examples":[{"en":"Effort and science both play a role in helping athletes win.","zh":"努力和科學都在幫助運動員取勝方面發揮作用。"},{"en":"Effort and science to win means athletes need hard training as well as scientific support.","zh":"「effort and science to win」意思是運動員需要艱苦訓練，也需要科學支援。"},{"en":"A swimmer may train daily, but sports science can help improve breathing, recovery and technique.","zh":"游泳運動員可能每天訓練，但運動科學可以幫助改善呼吸、恢復和技術。"},{"en":"When effort is guided by science, athletes can avoid wasteful training and reduce injury risk.","zh":"當努力受到科學指導，運動員可以避免浪費訓練並減低受傷風險。"},{"en":"Winning at a high level is rarely about talent alone; it often needs both discipline and expert knowledge.","zh":"在高水平比賽中取勝很少只靠天分；通常需要紀律和專家知識。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":1},{"front":"not only a question of","meaning":"不只是……的問題","examples":[{"en":"Winning nowadays is not only a question of disciplined training.","zh":"如今取勝不只是有紀律訓練的問題。"},{"en":"Not only a question of means something cannot be explained by one factor alone.","zh":"「not only a question of」意思是某事不能只由一個因素解釋。"},{"en":"Exam success is not only a question of studying hard; sleep and exam technique also matter.","zh":"考試成功不只是努力溫習的問題；睡眠和考試技巧也很重要。"},{"en":"If health is not only a question of diet, then exercise and stress management must also be considered.","zh":"如果健康不只是飲食的問題，那麼運動和壓力管理也必須被考慮。"},{"en":"This phrase is useful when you want to widen the discussion beyond one simple cause.","zh":"當你想把討論擴展到不止一個簡單原因時，這個短語很有用。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":1},{"front":"disciplined training","meaning":"有紀律的訓練","examples":[{"en":"Winning requires more than disciplined training.","zh":"取勝需要的不只是有紀律的訓練。"},{"en":"Disciplined training means regular, controlled and serious practice.","zh":"「disciplined training」指定期、有控制和認真的練習。"},{"en":"A runner follows disciplined training when she practises at set times and records her progress.","zh":"跑手在固定時間練習並記錄進度，就是遵循有紀律的訓練。"},{"en":"Without disciplined training, natural talent may not turn into strong performance.","zh":"沒有有紀律的訓練，天生才能可能無法變成強大表現。"},{"en":"Disciplined training builds habits, but athletes may still need coaching, nutrition and recovery support.","zh":"有紀律的訓練建立習慣，但運動員仍可能需要教練、營養和恢復支援。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":1},{"front":"involve collaboration among","meaning":"涉及……之間的合作","examples":[{"en":"Success today involves collaboration among medical specialists.","zh":"今天的成功涉及醫學專家之間的合作。"},{"en":"Involve collaboration among means require different people to work together.","zh":"「involve collaboration among」意思是需要不同人一起合作。"},{"en":"A school project may involve collaboration among teachers, parents and social workers.","zh":"學校項目可能涉及老師、家長和社工之間的合作。"},{"en":"If sports success involves collaboration among experts, one coach alone may not be enough.","zh":"如果運動成功涉及專家之間的合作，單靠一名教練可能不足夠。"},{"en":"The phrase highlights teamwork between several groups or professionals.","zh":"這個短語強調幾個群體或專業人士之間的團隊合作。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":1},{"front":"medical specialists","meaning":"醫學專家","examples":[{"en":"Medical specialists combine their expertise to help athletes.","zh":"醫學專家結合各自專業知識來幫助運動員。"},{"en":"Medical specialists are doctors or health experts trained in particular areas.","zh":"「medical specialists」是受過特定範疇訓練的醫生或健康專家。"},{"en":"An injured athlete may see medical specialists such as physiotherapists, nutritionists and sports doctors.","zh":"受傷運動員可能會見物理治療師、營養師和運動醫生等醫學專家。"},{"en":"If medical specialists work together, they can treat both injury and performance problems.","zh":"如果醫學專家一起合作，他們可以同時處理傷患和表現問題。"},{"en":"The phrase refers to expert healthcare professionals, not general helpers.","zh":"這個短語指專業醫療人員，而不是一般幫手。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":1},{"front":"combine their expertise","meaning":"結合各自專業知識","examples":[{"en":"Specialists combine their expertise to support each athlete.","zh":"專家結合各自專業知識來支援每位運動員。"},{"en":"To combine their expertise means to put different professional knowledge together.","zh":"「combine their expertise」意思是把不同專業知識結合起來。"},{"en":"Doctors and teachers may combine their expertise to support a child with learning difficulties.","zh":"醫生和老師可能結合各自專業知識，支援有學習困難的孩子。"},{"en":"When experts combine their expertise, they can solve problems that one person cannot handle alone.","zh":"當專家結合各自專業知識，他們可以解決一個人無法獨自處理的問題。"},{"en":"This phrase suggests shared knowledge, not separate advice.","zh":"這個短語暗示共享知識，而不是各自分開給意見。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":1},{"front":"help each athlete reach their potential","meaning":"幫助每位運動員發揮潛能","examples":[{"en":"Medical specialists help each athlete reach his or her potential.","zh":"醫學專家幫助每位運動員發揮他或她的潛能。"},{"en":"To help each athlete reach their potential means to support every athlete so they can perform as well as possible.","zh":"「help each athlete reach their potential」意思是支援每位運動員，使他們盡可能發揮最佳表現。"},{"en":"A coach helps each athlete reach their potential by giving training that matches their body and goals.","zh":"教練透過提供符合身體條件和目標的訓練，幫助每位運動員發揮潛能。"},{"en":"If support is personalised, weaker areas can improve and hidden strengths can develop.","zh":"如果支援是個人化的，弱項可以改善，隱藏優勢也可以發展。"},{"en":"The phrase focuses on individual growth, not only medals.","zh":"這個短語集中於個人成長，而不只是獎牌。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":1},{"front":"reach one’s potential","meaning":"發揮某人的潛能","examples":[{"en":"Every athlete wants to reach their full potential.","zh":"每位運動員都想充分發揮自己的潛能。"},{"en":"To reach one’s potential means to develop one’s ability as fully as possible.","zh":"「reach one’s potential」意思是盡可能充分發展自己的能力。"},{"en":"A student may reach her potential when she receives clear feedback and enough practice.","zh":"學生在得到清楚回饋和足夠練習時，可能發揮自己的潛能。"},{"en":"Without the right support, talented people may never reach their potential.","zh":"沒有適當支援，有才能的人可能永遠無法發揮潛能。"},{"en":"The phrase describes becoming as good as one realistically can be.","zh":"這個短語描述一個人盡可能成為自己能達到的最佳狀態。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":1},{"front":"Directorate of Medicine and Applied Sciences","meaning":"醫學及應用科學局","examples":[{"en":"The Directorate of Medicine and Applied Sciences analyses sports science in Mexico.","zh":"醫學及應用科學局在墨西哥分析運動科學。"},{"en":"The Directorate of Medicine and Applied Sciences is an organisation or department focused on medical and applied scientific support.","zh":"「Directorate of Medicine and Applied Sciences」是一個專注於醫學和應用科學支援的組織或部門。"},{"en":"Such a directorate may test athletes, study performance data and guide training plans.","zh":"這類機構可能測試運動員、研究表現數據並指導訓練計劃。"},{"en":"If a sports team has this kind of directorate, athletes can receive more organised scientific support.","zh":"如果運動隊有這類機構，運動員可以得到更有組織的科學支援。"},{"en":"The phrase names the official body responsible for the scientific work.","zh":"這個短語指出負責科學工作的官方機構。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":1},{"front":"National Sports Commission","meaning":"國家體育委員會","examples":[{"en":"The National Sports Commission supports sports science in Mexico.","zh":"國家體育委員會支援墨西哥的運動科學。"},{"en":"A National Sports Commission is a government or official body that manages or supports sport.","zh":"「National Sports Commission」是管理或支援體育的政府或官方機構。"},{"en":"A national sports body may fund training centres, coaches and scientific research.","zh":"國家體育機構可能資助訓練中心、教練和科學研究。"},{"en":"If the National Sports Commission invests in research, athletes may receive better support.","zh":"如果國家體育委員會投資研究，運動員可能得到更好支援。"},{"en":"The phrase refers to an institution, not a competition.","zh":"這個短語指一個機構，而不是一場比賽。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":1},{"front":"analyse every aspect of","meaning":"分析……的每一方面","examples":[{"en":"The facility analyses every aspect of sports science.","zh":"該中心分析運動科學的每一方面。"},{"en":"To analyse every aspect of something means to study all its parts carefully.","zh":"「analyse every aspect of」某事，意思是仔細研究它的所有部分。"},{"en":"A teacher may analyse every aspect of a student’s essay, including ideas, grammar and organisation.","zh":"老師可能分析學生作文的每一方面，包括想法、文法和組織。"},{"en":"If coaches analyse every aspect of performance, small weaknesses can be found and improved.","zh":"如果教練分析表現的每一方面，小弱點就可以被找出並改善。"},{"en":"The phrase suggests a complete and detailed examination.","zh":"這個短語暗示全面而詳細的檢查。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":1},{"front":"sports science","meaning":"運動科學","examples":[{"en":"Sports science is used to improve athletic performance.","zh":"運動科學被用來提升運動表現。"},{"en":"Sports science studies how training, medicine, psychology and equipment affect sport.","zh":"「sports science」研究訓練、醫學、心理學和裝備如何影響運動。"},{"en":"A runner may use sports science to improve speed, recovery and injury prevention.","zh":"跑手可能使用運動科學來改善速度、恢復和預防受傷。"},{"en":"When sports science is applied well, training can become safer and more effective.","zh":"當運動科學被良好應用，訓練可以變得更安全和更有效。"},{"en":"The phrase connects scientific knowledge with practical athletic results.","zh":"這個短語把科學知識與實際運動成果連繫起來。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":2},{"front":"the role of","meaning":"……的作用","examples":[{"en":"Researchers study the role of the auditory system in sporting achievement.","zh":"研究人員研究聽覺系統在運動成就中的作用。"},{"en":"The role of something means the part it plays in causing or influencing a result.","zh":"「the role of」某事物，意思是它在造成或影響結果方面扮演的部分。"},{"en":"Teachers study the role of sleep in students’ memory and attention.","zh":"老師研究睡眠在學生記憶和注意力中的作用。"},{"en":"If hearing affects balance or timing, it may play a role in athletic success.","zh":"如果聽覺影響平衡或節奏，它可能在運動成功中發揮作用。"},{"en":"This phrase is useful when discussing how one factor contributes to a larger outcome.","zh":"當討論某因素如何促成較大結果時，這個短語很有用。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":2},{"front":"auditory system","meaning":"聽覺系統","examples":[{"en":"The auditory system may influence sporting achievement.","zh":"聽覺系統可能影響運動成就。"},{"en":"The auditory system is the body system that allows people to hear and process sound.","zh":"「auditory system」是讓人聽見並處理聲音的身體系統。"},{"en":"A musician depends on the auditory system to hear rhythm and pitch accurately.","zh":"音樂家依賴聽覺系統準確聽到節奏和音高。"},{"en":"In sport, sound may help athletes react to signals, timing or movement around them.","zh":"在運動中，聲音可能幫助運動員回應信號、節奏或周圍動作。"},{"en":"The phrase refers to hearing, not eyesight.","zh":"這個短語指聽覺，而不是視覺。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":2},{"front":"sporting achievement","meaning":"運動成就","examples":[{"en":"The researchers examine factors that affect sporting achievement.","zh":"研究人員考察影響運動成就的因素。"},{"en":"Sporting achievement means success or strong performance in sport.","zh":"「sporting achievement」指在運動中的成功或強勁表現。"},{"en":"Winning a school race can be a sporting achievement for a young athlete.","zh":"對年輕運動員來說，贏得學校賽跑可以是一項運動成就。"},{"en":"Sporting achievement may depend on training, health, mental strength and equipment.","zh":"運動成就可能取決於訓練、健康、心理力量和裝備。"},{"en":"The phrase can refer to medals, records or personal improvement.","zh":"這個短語可以指獎牌、紀錄或個人進步。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":2},{"front":"the power of the mind","meaning":"心智力量","examples":[{"en":"The centre studies the power of the mind and its role in winning.","zh":"該中心研究心智力量及其在取勝中的作用。"},{"en":"The power of the mind means how thoughts, focus and confidence can affect behaviour and results.","zh":"「the power of the mind」指思想、專注和信心如何影響行為和結果。"},{"en":"A student uses the power of the mind when calm thinking helps them handle exam pressure.","zh":"當冷靜思考幫助學生處理考試壓力時，他們就在使用心智力量。"},{"en":"If an athlete loses confidence, physical skill alone may not be enough.","zh":"如果運動員失去信心，單靠身體技能可能不足夠。"},{"en":"The phrase highlights mental strength, not only physical ability.","zh":"這個短語強調心理力量，而不只是身體能力。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":2},{"front":"open to scrutiny","meaning":"可接受仔細審視","examples":[{"en":"Everything in sports performance is open to scrutiny.","zh":"運動表現中的一切都可接受仔細審視。"},{"en":"Open to scrutiny means available to be examined, questioned or checked carefully.","zh":"「open to scrutiny」意思是可以被仔細檢查、質疑或核對。"},{"en":"A school budget is open to scrutiny when parents can see how money is spent.","zh":"當家長可以看到金錢如何使用，學校預算就是可接受仔細審視的。"},{"en":"If training methods are open to scrutiny, weak ideas can be corrected.","zh":"如果訓練方法可接受仔細審視，薄弱想法就可以被修正。"},{"en":"The phrase suggests careful examination rather than blind acceptance.","zh":"這個短語暗示仔細檢查，而不是盲目接受。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":2},{"front":"focus on evaluating","meaning":"專注於評估","examples":[{"en":"Researchers have focused on evaluating athletes’ visual acuity.","zh":"研究人員專注於評估運動員的視敏度。"},{"en":"To focus on evaluating something means to give special attention to judging or measuring it.","zh":"「focus on evaluating」某事，意思是特別注意判斷或量度它。"},{"en":"A teacher may focus on evaluating students’ speaking fluency before an oral exam.","zh":"老師可能在口試前專注於評估學生的口語流暢度。"},{"en":"If doctors focus on evaluating recovery, they can adjust training before injury worsens.","zh":"如果醫生專注於評估恢復情況，他們可以在傷患惡化前調整訓練。"},{"en":"The phrase combines attention with assessment.","zh":"這個短語結合注意力和評估。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":2},{"front":"visual acuity","meaning":"視敏度","examples":[{"en":"The team evaluates the visual acuity of cyclists and long-distance runners.","zh":"團隊評估單車運動員和長跑運動員的視敏度。"},{"en":"Visual acuity means how clearly a person can see details.","zh":"「visual acuity」指一個人看清細節的能力。"},{"en":"An eye test checks visual acuity by asking people to read letters from a distance.","zh":"視力測試透過要求人從遠處讀字母來檢查視敏度。"},{"en":"If an athlete has poor visual acuity, they may react more slowly to movement or signals.","zh":"如果運動員視敏度差，他們可能對動作或信號反應較慢。"},{"en":"The phrase refers to sharpness of vision.","zh":"這個短語指視覺清晰度。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":2},{"front":"cyclists","meaning":"單車運動員","examples":[{"en":"Researchers study the visual acuity of cyclists.","zh":"研究人員研究單車運動員的視敏度。"},{"en":"Cyclists are people who ride bicycles, especially in sport or regular travel.","zh":"「cyclists」是騎單車的人，尤其是在運動或日常出行中騎單車的人。"},{"en":"Cyclists need good balance, leg strength and awareness of traffic or competitors.","zh":"單車運動員需要良好平衡、腿部力量，以及對交通或競爭者的意識。"},{"en":"If cyclists cannot see clearly, they may misjudge distance and speed.","zh":"如果單車運動員看不清楚，他們可能誤判距離和速度。"},{"en":"The word can refer to professional racers or ordinary bike riders.","zh":"這個詞可以指職業賽手，也可以指普通騎單車人士。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":2},{"front":"long-distance runners","meaning":"長跑運動員","examples":[{"en":"Long-distance runners are included in the research programme.","zh":"長跑運動員被納入研究計劃。"},{"en":"Long-distance runners are athletes who compete in races over long distances.","zh":"「long-distance runners」是參加長距離賽跑的運動員。"},{"en":"A long-distance runner must manage breathing, pace and endurance for a long time.","zh":"長跑運動員必須長時間管理呼吸、步速和耐力。"},{"en":"If long-distance runners train too hard without recovery, injury risk increases.","zh":"如果長跑運動員訓練太多而沒有恢復，受傷風險會增加。"},{"en":"The phrase refers to endurance athletes, not short sprint runners.","zh":"這個短語指耐力運動員，而不是短跑選手。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":2},{"front":"traditional areas","meaning":"傳統範疇","examples":[{"en":"The researchers also study more traditional areas of sports science.","zh":"研究人員也研究運動科學中較傳統的範疇。"},{"en":"Traditional areas are familiar or long-established fields of study or practice.","zh":"「traditional areas」指熟悉或長期建立的研究或實踐領域。"},{"en":"In school, reading and writing are traditional areas of language learning.","zh":"在學校中，閱讀和寫作是語言學習的傳統範疇。"},{"en":"If researchers study both new and traditional areas, their work becomes more complete.","zh":"如果研究人員同時研究新範疇和傳統範疇，他們的工作會更完整。"},{"en":"The phrase contrasts older familiar fields with newer or less expected ones.","zh":"這個短語把較舊、熟悉的領域與較新或較意想不到的領域作對比。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":2},{"front":"psychology","meaning":"心理學","examples":[{"en":"Psychology is one of the areas studied at Deporte.","zh":"心理學是 Deporte 研究的範疇之一。"},{"en":"Psychology is the study of the mind, emotions and behaviour.","zh":"「psychology」是研究心智、情緒和行為的學問。"},{"en":"A sports psychologist may help an athlete handle pressure before a final.","zh":"運動心理學家可能幫助運動員在決賽前處理壓力。"},{"en":"If anxiety affects performance, psychology can help explain and manage it.","zh":"如果焦慮影響表現，心理學可以幫助解釋並管理它。"},{"en":"The word refers to mental processes, not only feelings.","zh":"這個詞指心理過程，而不只是感受。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":3},{"front":"nutrition","meaning":"營養學","examples":[{"en":"Nutrition is important in athletic performance.","zh":"營養學對運動表現很重要。"},{"en":"Nutrition is the study and practice of getting the right food for health and energy.","zh":"「nutrition」是研究和實踐如何取得適合健康和能量需要的食物。"},{"en":"A student athlete needs good nutrition to train, recover and concentrate at school.","zh":"學生運動員需要良好營養，以便訓練、恢復和在學校專注。"},{"en":"Poor nutrition can reduce strength and slow recovery after exercise.","zh":"營養不良可以降低力量並減慢運動後恢復。"},{"en":"The phrase is about food quality and body needs, not just eating more.","zh":"這個短語關於食物質素和身體需要，而不只是吃更多。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":3},{"front":"anthropology","meaning":"人類學","examples":[{"en":"The centre studies anthropology as part of sports science.","zh":"該中心把人類學作為運動科學的一部分來研究。"},{"en":"Anthropology is the study of humans, cultures and societies.","zh":"「anthropology」是研究人類、文化和社會的學問。"},{"en":"Anthropology can help explain how culture affects attitudes to sport and training.","zh":"人類學可以幫助解釋文化如何影響人們對運動和訓練的態度。"},{"en":"If researchers understand a community’s values, they can design better sports programmes.","zh":"如果研究人員理解社群價值，他們可以設計更好的體育計劃。"},{"en":"The word connects human behaviour with social context.","zh":"這個詞把人類行為與社會背景連繫起來。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":3},{"front":"biochemistry","meaning":"生物化學","examples":[{"en":"Biochemistry helps researchers understand athletes’ bodies.","zh":"生物化學幫助研究人員理解運動員的身體。"},{"en":"Biochemistry studies the chemical processes inside living organisms.","zh":"「biochemistry」研究生物體內的化學過程。"},{"en":"Doctors may use biochemistry to understand how muscles use energy during exercise.","zh":"醫生可能使用生物化學來理解肌肉在運動中如何使用能量。"},{"en":"If an athlete’s body chemistry is unbalanced, performance and recovery may suffer.","zh":"如果運動員的身體化學失衡，表現和恢復可能受影響。"},{"en":"The word links biology with chemistry.","zh":"這個詞把生物學與化學連繫起來。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":3},{"front":"odontology","meaning":"牙科學","examples":[{"en":"Odontology is one of the specialised areas studied at Deporte.","zh":"牙科學是 Deporte 研究的專門範疇之一。"},{"en":"Odontology is the scientific study of teeth and dental health.","zh":"「odontology」是研究牙齒和牙齒健康的科學。"},{"en":"A dentist uses odontology to understand tooth structure, bite and oral disease.","zh":"牙醫使用牙科學來理解牙齒結構、咬合和口腔疾病。"},{"en":"In sport, dental problems may affect comfort, diet and even concentration.","zh":"在運動中，牙齒問題可能影響舒適度、飲食甚至專注力。"},{"en":"The word is more formal than dentistry and often appears in specialist contexts.","zh":"這個詞比 dentistry 更正式，常出現在專門語境中。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":3},{"front":"promising child athletes","meaning":"有潛質的兒童運動員","examples":[{"en":"The facility works with promising child athletes as young as nine.","zh":"該中心與年僅九歲的有潛質兒童運動員合作。"},{"en":"Promising child athletes are young sportspeople who show strong future potential.","zh":"「promising child athletes」是顯示強大未來潛力的年輕運動員。"},{"en":"A school may support promising child athletes with coaching and flexible study time.","zh":"學校可能透過教練和彈性學習時間支援有潛質的兒童運動員。"},{"en":"If promising child athletes receive good guidance early, they may develop safely and steadily.","zh":"如果有潛質的兒童運動員早期得到良好指導，他們可能安全而穩定地發展。"},{"en":"The phrase suggests talent, but also the need for careful support.","zh":"這個短語暗示才能，也暗示需要細心支援。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":3},{"front":"as young as nine","meaning":"年僅九歲","examples":[{"en":"Some athletes at the facility are as young as nine.","zh":"該中心有些運動員年僅九歲。"},{"en":"As young as nine means only nine years old, which is surprisingly young in the context.","zh":"「as young as nine」意思是只有九歲，在該語境中顯得特別年幼。"},{"en":"Some children start learning music as young as five.","zh":"有些孩子年僅五歲便開始學音樂。"},{"en":"If athletes are tested as young as nine, sports development begins very early.","zh":"如果運動員年僅九歲便接受測試，體育發展就開始得很早。"},{"en":"The phrase emphasises how young someone is.","zh":"這個短語強調某人年紀很小。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":3},{"front":"older sportspeople","meaning":"年紀較大的運動員","examples":[{"en":"The programme also supports older sportspeople.","zh":"該計劃也支援年紀較大的運動員。"},{"en":"Older sportspeople are athletes or active people who are no longer very young.","zh":"「older sportspeople」是不再年輕的運動員或活躍運動人士。"},{"en":"Older sportspeople may need different recovery plans from teenagers.","zh":"年紀較大的運動員可能需要不同於青少年的恢復計劃。"},{"en":"If training ignores age, older sportspeople may face higher injury risk.","zh":"如果訓練忽視年齡，年紀較大的運動員可能面對較高受傷風險。"},{"en":"The phrase shows that sports science can help people at different life stages.","zh":"這個短語顯示運動科學可以幫助不同人生階段的人。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":3},{"front":"the facility","meaning":"設施；中心","examples":[{"en":"The facility has attracted famous athletes and Olympic hopefuls.","zh":"該中心吸引了著名運動員和有望參加奧運的選手。"},{"en":"The facility means the sports-science centre or place where athletes receive support.","zh":"「the facility」指運動員接受支援的運動科學中心或場所。"},{"en":"A school sports facility may include a gym, running track and testing rooms.","zh":"學校體育設施可能包括健身室、跑道和測試室。"},{"en":"If a facility has expert staff and equipment, athletes may travel there for training.","zh":"如果一個中心有專家人員和設備，運動員可能前往那裡訓練。"},{"en":"The phrase refers to the physical centre and its services.","zh":"這個短語指實體中心及其服務。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":3},{"front":"attract famous athletes","meaning":"吸引著名運動員","examples":[{"en":"The facility has attracted some of Mexico’s most famous athletes.","zh":"該中心吸引了一些墨西哥最著名的運動員。"},{"en":"To attract famous athletes means to make well-known sportspeople want to come or use the service.","zh":"「attract famous athletes」意思是令知名運動員想前來或使用服務。"},{"en":"A new training centre may attract famous athletes if it has excellent coaches and equipment.","zh":"如果新訓練中心有出色教練和設備，它可能吸引著名運動員。"},{"en":"If famous athletes use a facility, younger athletes may trust it more.","zh":"如果著名運動員使用某中心，年輕運動員可能更信任它。"},{"en":"The phrase shows that a place has status and appeal.","zh":"這個短語顯示某地有地位和吸引力。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":3},{"front":"Olympic hopefuls","meaning":"有望參加奧運的選手","examples":[{"en":"Olympic hopefuls receive scientific support at Deporte.","zh":"有望參加奧運的選手在 Deporte 接受科學支援。"},{"en":"Olympic hopefuls are athletes who may have a chance to compete in the Olympic Games.","zh":"「Olympic hopefuls」是可能有機會參加奧運會的運動員。"},{"en":"An Olympic hopeful may train for years before knowing whether they will be selected.","zh":"有望參加奧運的選手可能訓練多年，才知道自己會否被選中。"},{"en":"If Olympic hopefuls get strong support, their chance of qualifying may improve.","zh":"如果有望參加奧運的選手得到強大支援，他們的晉級機會可能提高。"},{"en":"The phrase suggests ambition and possibility, not guaranteed success.","zh":"這個短語暗示抱負和可能性，而不是保證成功。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":3},{"front":"elite athletes","meaning":"精英運動員","examples":[{"en":"The study of elite athletes is now more scientific than ever.","zh":"對精英運動員的研究現在比以往任何時候都更科學化。"},{"en":"Elite athletes are top-level sportspeople who compete at very high standards.","zh":"「elite athletes」是在極高標準下競賽的頂尖運動員。"},{"en":"Elite athletes may have coaches, doctors, nutritionists and psychologists supporting them.","zh":"精英運動員可能有教練、醫生、營養師和心理學家支援。"},{"en":"Because small differences decide medals, elite athletes need very precise training.","zh":"因為微小差異決定獎牌，精英運動員需要非常精準的訓練。"},{"en":"The phrase refers to the highest level of sport.","zh":"這個短語指最高水平的運動。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":4},{"front":"more scientific than ever","meaning":"比以往任何時候都更科學化","examples":[{"en":"Sports training is now more scientific than ever.","zh":"運動訓練現在比以往任何時候都更科學化。"},{"en":"More scientific than ever means using more evidence, testing and expert knowledge than in the past.","zh":"「more scientific than ever」意思是比過去更多使用證據、測試和專家知識。"},{"en":"Modern hospitals are more scientific than ever because decisions often rely on data and scans.","zh":"現代醫院比以往任何時候都更科學化，因為決定常依賴數據和掃描。"},{"en":"If training is more scientific than ever, athletes may avoid guesswork and train more safely.","zh":"如果訓練比以往任何時候都更科學化，運動員可以避免猜測並更安全地訓練。"},{"en":"The phrase compares today with all earlier periods.","zh":"這個短語把今天與所有過去時期比較。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":4},{"front":"undergo thorough medical examinations","meaning":"接受全面身體檢查","examples":[{"en":"Athletes undergo thorough medical examinations after each competition.","zh":"運動員在每次比賽後接受全面身體檢查。"},{"en":"To undergo thorough medical examinations means to receive detailed health checks.","zh":"「undergo thorough medical examinations」意思是接受詳細健康檢查。"},{"en":"A patient may undergo thorough medical examinations before major surgery.","zh":"病人在大型手術前可能接受全面身體檢查。"},{"en":"If athletes are examined after competition, hidden injuries can be found early.","zh":"如果運動員在比賽後接受檢查，隱藏傷患可以及早被發現。"},{"en":"The phrase describes a careful medical process, not a quick check.","zh":"這個短語描述仔細醫療程序，而不是快速檢查。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":4},{"front":"thorough medical examinations","meaning":"全面身體檢查","examples":[{"en":"Thorough medical examinations help doctors understand athletes’ condition.","zh":"全面身體檢查幫助醫生了解運動員的狀況。"},{"en":"Thorough medical examinations are detailed health checks that look at several body systems.","zh":"「thorough medical examinations」是檢查多個身體系統的詳細健康檢查。"},{"en":"A thorough examination may include blood tests, heart checks and injury assessment.","zh":"全面檢查可能包括血液測試、心臟檢查和傷患評估。"},{"en":"If examinations are thorough, doctors are less likely to miss serious problems.","zh":"如果檢查全面，醫生較不容易錯過嚴重問題。"},{"en":"The phrase emphasises completeness and care.","zh":"這個短語強調完整和細心。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":4},{"front":"follow-up training","meaning":"跟進訓練","examples":[{"en":"Athletes receive follow-up training after medical examinations.","zh":"運動員在身體檢查後接受跟進訓練。"},{"en":"Follow-up training is training given after an assessment, event or earlier stage.","zh":"「follow-up training」是在評估、事件或早前階段後提供的訓練。"},{"en":"After a fitness test, a student may receive follow-up training to improve weak areas.","zh":"體能測試後，學生可能接受跟進訓練以改善弱項。"},{"en":"If medical checks reveal tight muscles, follow-up training can target flexibility.","zh":"如果身體檢查顯示肌肉繃緊，跟進訓練可以針對柔韌性。"},{"en":"The phrase shows that support continues after the first test.","zh":"這個短語顯示支援在首次測試後繼續。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":4},{"front":"devise a tailor-made programme","meaning":"制定度身訂造的計劃","examples":[{"en":"Doctors devise a tailor-made programme for each athlete.","zh":"醫生為每位運動員制定度身訂造的計劃。"},{"en":"To devise a tailor-made programme means to design a plan specially for one person’s needs.","zh":"「devise a tailor-made programme」意思是為某人的需要特別設計計劃。"},{"en":"A tutor may devise a tailor-made programme for a student who struggles with writing.","zh":"導師可能為寫作吃力的學生制定度身訂造的計劃。"},{"en":"If training is tailor-made, it can target the athlete’s exact weaknesses and goals.","zh":"如果訓練是度身訂造的，它可以針對運動員的準確弱點和目標。"},{"en":"The phrase suggests careful planning, not a standard routine.","zh":"這個短語暗示仔細規劃，而不是標準流程。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":4},{"front":"tailor-made programme","meaning":"度身訂造的計劃","examples":[{"en":"A tailor-made programme is created for each athlete.","zh":"每位運動員都有一個度身訂造的計劃。"},{"en":"A tailor-made programme is a plan designed for a particular person, not for everyone.","zh":"「tailor-made programme」是為特定個人而設計的計劃，不是給所有人使用。"},{"en":"A language learner may need a tailor-made programme if grammar is strong but speaking is weak.","zh":"如果語言學習者文法強但口語弱，他可能需要度身訂造的計劃。"},{"en":"Tailor-made programmes can save time because they focus on what the person actually needs.","zh":"度身訂造的計劃可以節省時間，因為它集中於個人真正需要的東西。"},{"en":"The phrase contrasts individual support with a one-size-fits-all approach.","zh":"這個短語把個人化支援與一刀切方法作對比。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":4},{"front":"big business","meaning":"大生意；龐大產業","examples":[{"en":"Elite sport has become big business.","zh":"精英運動已成為龐大產業。"},{"en":"Big business means an activity has become a large and profitable industry.","zh":"「big business」意思是某活動已成為大型且有利可圖的行業。"},{"en":"Online shopping is big business because millions of people buy products every day.","zh":"網上購物是大生意，因為每天有數百萬人購買產品。"},{"en":"When sport becomes big business, training, sponsorship and media rights involve huge money.","zh":"當運動成為龐大產業，訓練、贊助和媒體權利都涉及巨額金錢。"},{"en":"The phrase suggests commercial importance, not just popularity.","zh":"這個短語暗示商業重要性，而不只是受歡迎。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":4},{"front":"no longer","meaning":"不再","examples":[{"en":"There is no longer a one-size-fits-all approach.","zh":"現在不再有一刀切的方法。"},{"en":"No longer means something was true before but is not true now.","zh":"「no longer」意思是某事以前是真的，但現在不再是。"},{"en":"The old library card is no longer valid after the system changed.","zh":"系統改變後，舊圖書證不再有效。"},{"en":"If training is no longer general, athletes may receive individual plans.","zh":"如果訓練不再是一般化的，運動員可能獲得個人化計劃。"},{"en":"The phrase marks a change from the past to the present.","zh":"這個短語標示從過去到現在的變化。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":4},{"front":"one-size-fits-all approach","meaning":"一刀切的方法","examples":[{"en":"Elite sport no longer uses a one-size-fits-all approach.","zh":"精英運動不再使用一刀切的方法。"},{"en":"A one-size-fits-all approach is one method used for everyone, even if people have different needs.","zh":"「one-size-fits-all approach」是對所有人使用同一方法，即使人們有不同需要。"},{"en":"A school uses a one-size-fits-all approach if every student gets the same homework despite different levels.","zh":"如果學校不管學生程度不同都給同一份功課，就是使用一刀切的方法。"},{"en":"In sport, this approach can fail because athletes have different bodies and weaknesses.","zh":"在運動中，這種方法可能失敗，因為運動員有不同身體和弱點。"},{"en":"The phrase is often used to criticise overly general solutions.","zh":"這個短語常用來批評過於籠統的解決方案。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":4},{"front":"athletic-conditioning programme","meaning":"運動體能訓練計劃","examples":[{"en":"In the past, similar athletes received the same athletic-conditioning programme.","zh":"在過去，相似的運動員接受相同的運動體能訓練計劃。"},{"en":"An athletic-conditioning programme is a plan designed to build fitness, strength and endurance for sport.","zh":"「athletic-conditioning programme」是為運動建立體能、力量和耐力的計劃。"},{"en":"A football team may follow an athletic-conditioning programme before the season begins.","zh":"足球隊可能在賽季開始前遵循運動體能訓練計劃。"},{"en":"If the programme ignores individual needs, some athletes may overtrain while others improve too slowly.","zh":"如果計劃忽略個人需要，有些運動員可能過度訓練，而另一些則進步太慢。"},{"en":"The phrase refers to physical preparation for sport.","zh":"這個短語指為運動而作的體能準備。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":4},{"front":"obsolete","meaning":"過時的","examples":[{"en":"The old one-size-fits-all idea is now obsolete.","zh":"舊有的一刀切想法現在已經過時。"},{"en":"Obsolete means no longer useful because something newer or better has replaced it.","zh":"「obsolete」意思是因為被更新或更好的東西取代而不再有用。"},{"en":"Old phone chargers can become obsolete when new models use different ports.","zh":"當新型號使用不同接口，舊手機充電器可能變得過時。"},{"en":"A training method becomes obsolete if science shows it is unsafe or ineffective.","zh":"如果科學顯示某訓練方法不安全或無效，它就會變得過時。"},{"en":"The word is stronger than old; it means out of date and no longer suitable.","zh":"這個詞比 old 更強；它表示落伍且不再適合。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":5},{"front":"despite having","meaning":"儘管有……","examples":[{"en":"The second athlete may have more fat despite having the same height and weight.","zh":"第二位運動員儘管有相同身高和體重，脂肪可能更多。"},{"en":"Despite having means although someone or something has a particular feature.","zh":"「despite having」意思是儘管某人或某物有某個特徵。"},{"en":"Two students may get different marks despite having the same teacher.","zh":"兩名學生儘管有同一位老師，成績可能不同。"},{"en":"Athletes can have different body compositions despite having similar measurements.","zh":"運動員儘管有相似測量數據，身體組成仍可能不同。"},{"en":"The phrase highlights contrast between what we expect and what is true.","zh":"這個短語強調預期與事實之間的對比。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":5},{"front":"height and weight","meaning":"身高和體重","examples":[{"en":"Two athletes may have the same height and weight but different body composition.","zh":"兩名運動員可能有相同身高和體重，但身體組成不同。"},{"en":"Height and weight are basic body measurements of how tall and heavy someone is.","zh":"「height and weight」是某人有多高和多重的基本身體測量。"},{"en":"A doctor may record a child’s height and weight during a health check.","zh":"醫生可能在健康檢查中記錄孩子的身高和體重。"},{"en":"Height and weight alone cannot show how much muscle or fat a person has.","zh":"單靠身高和體重不能顯示一個人有多少肌肉或脂肪。"},{"en":"The phrase gives basic data, not a complete picture of fitness.","zh":"這個短語提供基本數據，而不是完整體能圖像。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":5},{"front":"detailed scientific evaluation","meaning":"詳細科學評估","examples":[{"en":"Detailed scientific evaluation helps create individual training programmes.","zh":"詳細科學評估有助制定個人訓練計劃。"},{"en":"Detailed scientific evaluation means careful testing and analysis based on evidence.","zh":"「detailed scientific evaluation」指基於證據的仔細測試和分析。"},{"en":"A doctor may use detailed evaluation before deciding on a treatment plan.","zh":"醫生在決定治療計劃前可能使用詳細評估。"},{"en":"If athletes receive detailed evaluation, coaches can see hidden strengths and weaknesses.","zh":"如果運動員接受詳細評估，教練可以看見隱藏優勢和弱點。"},{"en":"The phrase suggests precise assessment rather than guesswork.","zh":"這個短語暗示精準評估，而不是猜測。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":5},{"front":"construct a programme","meaning":"制定計劃","examples":[{"en":"Scientists can construct a specific training programme for each individual.","zh":"科學家可以為每個人制定特定訓練計劃。"},{"en":"To construct a programme means to design and build a plan step by step.","zh":"「construct a programme」意思是一步一步設計和建立計劃。"},{"en":"A tutor may construct a programme that starts with grammar and later adds writing practice.","zh":"導師可能制定一個先從文法開始、再加入寫作練習的計劃。"},{"en":"If experts construct a programme from test results, it can match real needs better.","zh":"如果專家根據測試結果制定計劃，它可以更符合真實需要。"},{"en":"The phrase suggests careful planning and structure.","zh":"這個短語暗示仔細規劃和結構。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":5},{"front":"highly specific training programme","meaning":"高度針對性的訓練計劃","examples":[{"en":"Each athlete receives a highly specific training programme.","zh":"每位運動員都接受高度針對性的訓練計劃。"},{"en":"A highly specific training programme is a plan designed for very particular needs or goals.","zh":"「highly specific training programme」是為非常特定的需要或目標而設計的計劃。"},{"en":"A sprinter may need a highly specific programme focused on explosive speed.","zh":"短跑運動員可能需要高度針對爆發速度的訓練計劃。"},{"en":"If training is highly specific, it can target exact weaknesses rather than general fitness only.","zh":"如果訓練高度針對性，它可以針對確切弱點，而不只是一般體能。"},{"en":"The phrase means detailed and personalised.","zh":"這個短語意思是詳細和個人化。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":5},{"front":"for each individual","meaning":"為每一個人","examples":[{"en":"The programme is designed for each individual.","zh":"該計劃為每一個人而設計。"},{"en":"For each individual means separately for every person.","zh":"「for each individual」意思是分別為每一個人。"},{"en":"A doctor may choose a different treatment for each individual patient.","zh":"醫生可能為每一位病人選擇不同治療。"},{"en":"If training is planned for each individual, athletes are not forced into the same routine.","zh":"如果訓練為每一個人而計劃，運動員就不會被迫使用同一流程。"},{"en":"The phrase stresses personal differences.","zh":"這個短語強調個人差異。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":5},{"front":"whereas","meaning":"然而；相對而言","examples":[{"en":"Whereas many countries glorify the champion, Mexico stresses teamwork.","zh":"許多國家歌頌冠軍，然而墨西哥強調團隊合作。"},{"en":"Whereas is used to show contrast between two facts or ideas.","zh":"「whereas」用來顯示兩個事實或想法之間的對比。"},{"en":"Some students prefer studying alone, whereas others learn better in groups.","zh":"有些學生喜歡獨自學習，而另一些學生在小組中學得更好。"},{"en":"Whereas talent may start an athlete’s career, careful support may sustain it.","zh":"天分可能開啟運動員的生涯，然而仔細支援可能維持它。"},{"en":"The word is formal and useful for comparing different situations.","zh":"這個詞較正式，適合比較不同情況。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":5},{"front":"glorify the champion","meaning":"美化冠軍；歌頌冠軍","examples":[{"en":"Many countries focus on glorifying the champion.","zh":"許多國家集中於歌頌冠軍。"},{"en":"To glorify the champion means to praise the winner as if they alone deserve all the honour.","zh":"「glorify the champion」意思是把勝利者讚揚得好像只有他們值得所有榮譽。"},{"en":"News reports may glorify the champion while ignoring the coach and support team.","zh":"新聞報道可能歌頌冠軍，卻忽略教練和支援團隊。"},{"en":"If people glorify only the winner, they may forget the teamwork behind success.","zh":"如果人們只歌頌勝利者，他們可能忘記成功背後的團隊合作。"},{"en":"The phrase can suggest too much praise of one person.","zh":"這個短語可能暗示對一個人過度讚揚。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":5},{"front":"take a different approach","meaning":"採取不同方法","examples":[{"en":"The Mexican Olympic team takes a slightly different approach.","zh":"墨西哥奧運隊採取稍微不同的方法。"},{"en":"To take a different approach means to use another way of dealing with something.","zh":"「take a different approach」意思是用另一種方式處理某事。"},{"en":"A teacher may take a different approach if students do not understand the first explanation.","zh":"如果學生不明白第一次解釋，老師可能採取不同方法。"},{"en":"If one training method fails, coaches may take a different approach based on new data.","zh":"如果一種訓練方法失敗，教練可能根據新數據採取不同方法。"},{"en":"The phrase suggests changing method rather than changing the goal.","zh":"這個短語暗示改變方法，而不是改變目標。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":5},{"front":"psychologically speaking","meaning":"從心理角度來說","examples":[{"en":"Psychologically speaking, athletes need humility.","zh":"從心理角度來說，運動員需要謙遜。"},{"en":"Psychologically speaking means from the point of view of the mind or emotions.","zh":"「psychologically speaking」意思是從心智或情緒角度來看。"},{"en":"Psychologically speaking, a student may perform better when they feel safe to make mistakes.","zh":"從心理角度來說，當學生覺得犯錯也安全時，他們可能表現更好。"},{"en":"If an athlete becomes overconfident, psychologically speaking, they may stop listening to advice.","zh":"如果運動員變得過分自信，從心理角度來說，他們可能停止聽取建議。"},{"en":"The phrase introduces a mental or emotional explanation.","zh":"這個短語引入心理或情緒解釋。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":5},{"front":"a healthy dose of","meaning":"適量的……","examples":[{"en":"An athlete must bring a healthy dose of humility to the endeavour.","zh":"運動員必須為這項奮鬥帶來適量的謙遜。"},{"en":"A healthy dose of something means a useful and balanced amount of it.","zh":"「a healthy dose of」某物，意思是有用而平衡的適量。"},{"en":"A team needs a healthy dose of confidence before a difficult match.","zh":"球隊在困難比賽前需要適量信心。"},{"en":"If students have a healthy dose of curiosity, they ask questions without becoming careless.","zh":"如果學生有適量好奇心，他們會提問而不變得粗心。"},{"en":"The phrase suggests enough of a quality to help, but not too much.","zh":"這個短語暗示某種品質足夠有幫助，但不過量。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":6},{"front":"humility","meaning":"謙遜","examples":[{"en":"Successful athletes need humility as well as confidence.","zh":"成功運動員需要信心，也需要謙遜。"},{"en":"Humility means not thinking you are better than everyone else, even when you are skilled.","zh":"「humility」意思是即使有能力，也不認為自己比所有人優越。"},{"en":"A student shows humility when they accept feedback after getting a high mark.","zh":"學生取得高分後仍接受回饋，就是展現謙遜。"},{"en":"Humility helps athletes keep learning because they do not assume they know everything.","zh":"謙遜幫助運動員繼續學習，因為他們不會以為自己什麼都懂。"},{"en":"The word is not weakness; it is a balanced attitude toward one’s ability.","zh":"這個詞不是軟弱；它是對自身能力的平衡態度。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":6},{"front":"the endeavour","meaning":"努力追求的事業；奮鬥目標","examples":[{"en":"The Olympic endeavour requires both effort and humility.","zh":"奧運奮鬥目標需要努力和謙遜。"},{"en":"The endeavour means the serious attempt or difficult goal being pursued.","zh":"「the endeavour」指正在追求的認真嘗試或困難目標。"},{"en":"Starting a small business is an endeavour that requires planning and persistence.","zh":"創辦小企業是一項需要規劃和堅持的奮鬥事業。"},{"en":"If the endeavour is demanding, people need discipline and support to continue.","zh":"如果奮鬥目標很艱巨，人們需要紀律和支援才能繼續。"},{"en":"The phrase sounds formal and often refers to an important effort.","zh":"這個短語較正式，常指重要努力。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":6},{"front":"team effort","meaning":"團隊努力","examples":[{"en":"A Mexican athletic victory is seen as a combined team effort.","zh":"墨西哥運動勝利被視為共同的團隊努力。"},{"en":"A team effort is success produced by many people working together.","zh":"「team effort」是許多人合作產生的成功。"},{"en":"A school concert is a team effort involving students, teachers and backstage helpers.","zh":"學校音樂會是學生、老師和幕後助手參與的團隊努力。"},{"en":"If a medal is treated as a team effort, coaches and doctors also receive credit.","zh":"如果獎牌被視為團隊努力，教練和醫生也會得到肯定。"},{"en":"The phrase reminds us that one person’s success may depend on many others.","zh":"這個短語提醒我們，一個人的成功可能依賴許多人。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":6},{"front":"combined team effort","meaning":"共同的團隊努力","examples":[{"en":"Winning is the result of a combined team effort.","zh":"取勝是共同團隊努力的結果。"},{"en":"A combined team effort is a joint effort made by several people or groups together.","zh":"「combined team effort」是由幾個人或群體一起作出的共同努力。"},{"en":"A hospital recovery plan may be a combined team effort by doctors, nurses and family members.","zh":"醫院康復計劃可能是醫生、護士和家人共同的團隊努力。"},{"en":"When experts combine their work, the final result can be stronger than separate efforts.","zh":"當專家結合工作，最終結果可以比分開努力更強。"},{"en":"The phrase strongly emphasises shared contribution.","zh":"這個短語強烈強調共同貢獻。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":6},{"front":"behind the scenes","meaning":"在幕後","examples":[{"en":"Many people work behind the scenes to support athletes.","zh":"許多人在幕後工作以支援運動員。"},{"en":"Behind the scenes means not visible to the public but still important.","zh":"「behind the scenes」意思是不被公眾看見，但仍然重要。"},{"en":"At a school play, many students work behind the scenes with lights, sound and costumes.","zh":"在學校話劇中，許多學生在幕後處理燈光、音響和服裝。"},{"en":"If support staff work behind the scenes, the audience may see only the final performance.","zh":"如果支援人員在幕後工作，觀眾可能只看見最終表演。"},{"en":"The phrase shows hidden work that makes success possible.","zh":"這個短語顯示令成功成為可能的隱藏工作。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":6},{"front":"make the achievement possible","meaning":"令成就得以實現","examples":[{"en":"Support staff help make the achievement possible.","zh":"支援人員幫助令成就得以實現。"},{"en":"To make the achievement possible means to create the conditions needed for success.","zh":"「make the achievement possible」意思是創造成功所需的條件。"},{"en":"Parents may make a child’s achievement possible by giving time, support and encouragement.","zh":"家長可能透過給予時間、支援和鼓勵，令孩子的成就得以實現。"},{"en":"Without doctors and coaches, an athlete’s victory might not be possible.","zh":"沒有醫生和教練，運動員的勝利可能無法實現。"},{"en":"The phrase connects hidden support with visible success.","zh":"這個短語把隱藏支援與可見成功連繫起來。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":6},{"front":"stand on the podium","meaning":"站上頒獎台","examples":[{"en":"An athlete stands on the podium after winning a medal.","zh":"運動員贏得獎牌後站上頒獎台。"},{"en":"To stand on the podium means to be placed among the winners in a sports event.","zh":"「stand on the podium」意思是在體育賽事中位列獲獎者之中。"},{"en":"A runner who finishes first may stand on the podium while receiving a gold medal.","zh":"跑手取得第一名時，可能站上頒獎台領取金牌。"},{"en":"Standing on the podium is the visible result of years of training and support.","zh":"站上頒獎台是多年訓練和支援的可見結果。"},{"en":"The phrase is often used to represent public sporting success.","zh":"這個短語常用來代表公開的運動成功。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":6},{"front":"make a great effort","meaning":"付出巨大努力","examples":[{"en":"Many people have made a great effort before an athlete wins.","zh":"在運動員取勝前，許多人已付出巨大努力。"},{"en":"To make a great effort means to work very hard toward a goal.","zh":"「make a great effort」意思是為目標非常努力。"},{"en":"A student makes a great effort when they practise speaking every day before an exam.","zh":"學生在考試前每天練習口語，就是付出巨大努力。"},{"en":"If many people make a great effort together, a difficult project becomes possible.","zh":"如果許多人一起付出巨大努力，困難項目就變得可能。"},{"en":"The phrase emphasises serious work and persistence.","zh":"這個短語強調認真工作和堅持。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":6},{"front":"as is often the case","meaning":"正如經常出現的情況","examples":[{"en":"As is often the case in poorer countries, athletes can lack resources.","zh":"正如較貧窮國家經常出現的情況，運動員可能缺乏資源。"},{"en":"As is often the case means as commonly happens in similar situations.","zh":"「as is often the case」意思是正如類似情況中常見的那樣。"},{"en":"As is often the case before exams, students feel nervous even when they have prepared.","zh":"正如考試前常見的情況，學生即使已準備好也會緊張。"},{"en":"If a problem is common, this phrase helps introduce it as a familiar pattern.","zh":"如果某問題很常見，這個短語可以把它作為熟悉模式引入。"},{"en":"The phrase does not mean always; it means frequently.","zh":"這個短語不是指永遠如此；它是指經常如此。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":6},{"front":"poorer countries","meaning":"較貧窮國家","examples":[{"en":"Poorer countries may face financial limits in sport.","zh":"較貧窮國家在體育方面可能面對財政限制。"},{"en":"Poorer countries are countries with fewer economic resources than richer nations.","zh":"「poorer countries」是經濟資源少於富裕國家的國家。"},{"en":"Schools in poorer countries may lack sports facilities, equipment and trained coaches.","zh":"較貧窮國家的學校可能缺乏體育設施、設備和受訓教練。"},{"en":"If a country has limited money, athletes may struggle to train at international standards.","zh":"如果一個國家資金有限，運動員可能難以按國際標準訓練。"},{"en":"The phrase refers to national economic conditions, not the effort of the athletes.","zh":"這個短語指國家經濟條件，而不是運動員的努力。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":6},{"front":"sportsmen and women","meaning":"男女運動員","examples":[{"en":"Sportsmen and women can be hindered by budgetary constraints.","zh":"男女運動員可能受預算限制阻礙。"},{"en":"Sportsmen and women are male and female athletes.","zh":"「sportsmen and women」指男性和女性運動員。"},{"en":"Sportsmen and women need training spaces, equipment, coaching and medical support.","zh":"男女運動員需要訓練場地、設備、教練和醫療支援。"},{"en":"If sportsmen and women lack resources, talent may not develop fully.","zh":"如果男女運動員缺乏資源，才能可能無法充分發展。"},{"en":"The phrase includes athletes of both sexes.","zh":"這個短語包括兩種性別的運動員。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":7},{"front":"be hindered by","meaning":"受……阻礙","examples":[{"en":"Athletes can be hindered by a lack of funding.","zh":"運動員可能受缺乏資金阻礙。"},{"en":"To be hindered by something means to be slowed down or blocked by it.","zh":"「be hindered by」某事，意思是被它拖慢或阻擋。"},{"en":"Students may be hindered by poor internet when taking online lessons.","zh":"學生上網課時可能受網絡差阻礙。"},{"en":"If training is hindered by injury, progress may become slower.","zh":"如果訓練受傷患阻礙，進步可能變慢。"},{"en":"The phrase describes an obstacle that makes success harder.","zh":"這個短語描述令成功更困難的障礙。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":7},{"front":"budgetary constraints","meaning":"預算限制","examples":[{"en":"Budgetary constraints can limit sports development.","zh":"預算限制可以限制體育發展。"},{"en":"Budgetary constraints are limits caused by not having enough money in a budget.","zh":"「budgetary constraints」是因預算中沒有足夠金錢而造成的限制。"},{"en":"A school may cancel a trip because of budgetary constraints.","zh":"學校可能因預算限制而取消旅行。"},{"en":"If a sports programme faces budgetary constraints, it may buy less equipment or hire fewer coaches.","zh":"如果體育計劃面對預算限制，它可能購買較少設備或聘請較少教練。"},{"en":"The phrase is formal and often used in planning or policy discussions.","zh":"這個短語較正式，常用於規劃或政策討論。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":7},{"front":"not been a problem for","meaning":"對……來說並非問題","examples":[{"en":"Budgetary constraints have not been a problem for the Mexican team.","zh":"預算限制對墨西哥隊來說並非問題。"},{"en":"Not been a problem for means something has not caused difficulty for a person or group.","zh":"「not been a problem for」意思是某事沒有為某人或某群體造成困難。"},{"en":"Transport has not been a problem for students because the school provides buses.","zh":"交通對學生來說並非問題，因為學校提供巴士。"},{"en":"If funding has not been a problem, a team can invest in better equipment and research.","zh":"如果資金並非問題，隊伍可以投資更好設備和研究。"},{"en":"The phrase shows that one expected obstacle did not apply.","zh":"這個短語顯示某個預期障礙並不適用。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":7},{"front":"allocate a substantial sum","meaning":"撥出一大筆款項","examples":[{"en":"The government has allocated a substantial sum for sports research.","zh":"政府已為體育研究撥出一大筆款項。"},{"en":"To allocate a substantial sum means to officially set aside a large amount of money.","zh":"「allocate a substantial sum」意思是正式預留一大筆金錢。"},{"en":"A city may allocate a substantial sum to repair old bridges.","zh":"城市可能撥出一大筆款項來維修舊橋。"},{"en":"If the government allocates a large sum to sport, facilities and research can improve.","zh":"如果政府為體育撥出大筆款項，設施和研究可以改善。"},{"en":"The phrase suggests planned financial support.","zh":"這個短語暗示有計劃的財政支援。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":7},{"front":"substantial sum","meaning":"一大筆款項","examples":[{"en":"A substantial sum has been spent on equipment and laboratories.","zh":"一大筆款項已用於設備和實驗室。"},{"en":"A substantial sum is a large amount of money.","zh":"「substantial sum」是一大筆金錢。"},{"en":"Buying a flat usually requires a substantial sum for the deposit.","zh":"買樓通常需要一大筆款項作首期。"},{"en":"If a school receives a substantial sum, it may improve classrooms and technology.","zh":"如果學校收到一大筆款項，它可能改善課室和科技設備。"},{"en":"The phrase emphasises that the amount is significant.","zh":"這個短語強調金額相當可觀。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":7},{"front":"sports-research equipment","meaning":"體育研究設備","examples":[{"en":"The government funded the latest sports-research equipment.","zh":"政府資助了最新的體育研究設備。"},{"en":"Sports-research equipment is equipment used to measure and study athletic performance.","zh":"「sports-research equipment」是用來量度和研究運動表現的設備。"},{"en":"A sports lab may use heart monitors, cameras and oxygen-measuring devices as research equipment.","zh":"運動實驗室可能使用心率監測器、攝影機和量氧裝置作研究設備。"},{"en":"If athletes have better sports-research equipment, coaches can make more accurate decisions.","zh":"如果運動員有更好的體育研究設備，教練可以作出更準確決定。"},{"en":"The phrase refers to tools for scientific testing, not ordinary gym machines only.","zh":"這個短語指科學測試工具，而不只是普通健身器材。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":7},{"front":"laboratories","meaning":"實驗室","examples":[{"en":"Modern laboratories support Mexican sports science.","zh":"現代實驗室支援墨西哥運動科學。"},{"en":"Laboratories are rooms or buildings where scientific tests and research are carried out.","zh":"「laboratories」是進行科學測試和研究的房間或建築物。"},{"en":"Students use school laboratories to do chemistry and biology experiments safely.","zh":"學生在學校實驗室安全地做化學和生物實驗。"},{"en":"If sports laboratories collect accurate data, training plans can become more reliable.","zh":"如果運動實驗室收集準確數據，訓練計劃可以變得更可靠。"},{"en":"The word refers to places designed for scientific work.","zh":"這個詞指為科學工作而設計的場所。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":7},{"front":"the quality of facilities","meaning":"設施質素","examples":[{"en":"The quality of Mexico’s facilities is high.","zh":"墨西哥的設施質素很高。"},{"en":"The quality of facilities means how good the buildings, equipment and services are.","zh":"「the quality of facilities」指建築、設備和服務有多好。"},{"en":"Parents may judge a school by the quality of its classrooms, library and sports areas.","zh":"家長可能根據課室、圖書館和運動場地質素評價學校。"},{"en":"If the quality of sports facilities is high, athletes can train more safely and effectively.","zh":"如果體育設施質素高，運動員可以更安全和有效地訓練。"},{"en":"The phrase evaluates the standard of a place and its resources.","zh":"這個短語評估一個場所及其資源的標準。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":7},{"front":"on a par with","meaning":"與……不相上下","examples":[{"en":"Mexico’s facilities are on a par with those in Italy and Germany.","zh":"墨西哥的設施與意大利和德國的設施不相上下。"},{"en":"On a par with means equal or similar in quality or level.","zh":"「on a par with」意思是在質素或水平上相等或相近。"},{"en":"This small school’s science lab is on a par with those of larger schools.","zh":"這所小學校的科學實驗室與較大學校的不相上下。"},{"en":"If facilities are on a par with richer countries, athletes are not disadvantaged by equipment.","zh":"如果設施與較富裕國家不相上下，運動員就不會因設備而處於劣勢。"},{"en":"The phrase is used for comparison between similar standards.","zh":"這個短語用於比較相似標準。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":7},{"front":"sophisticated equipment","meaning":"先進設備","examples":[{"en":"The Mexican facility contains sophisticated equipment.","zh":"墨西哥中心配備先進設備。"},{"en":"Sophisticated equipment is advanced, complex and carefully designed equipment.","zh":"「sophisticated equipment」是先進、複雜且設計精密的設備。"},{"en":"A hospital uses sophisticated equipment to scan the body and monitor patients.","zh":"醫院使用先進設備掃描身體和監測病人。"},{"en":"If athletes use sophisticated equipment, their performance can be measured more precisely.","zh":"如果運動員使用先進設備，他們的表現可以被更精確地量度。"},{"en":"The phrase suggests high technology, not simple tools.","zh":"這個短語暗示高科技，而不是簡單工具。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":7},{"front":"hyperbaric chamber","meaning":"高壓氧艙","examples":[{"en":"A hyperbaric chamber is used to speed recovery after exercise.","zh":"高壓氧艙用於加快運動後恢復。"},{"en":"A hyperbaric chamber is a sealed room or container with higher-than-normal air pressure.","zh":"「hyperbaric chamber」是一個密封房間或容器，內部氣壓高於正常水平。"},{"en":"Athletes may sit in a hyperbaric chamber after hard training to support recovery.","zh":"運動員可能在艱苦訓練後坐進高壓氧艙，以支援恢復。"},{"en":"Increased pressure can help oxygen enter body tissues more effectively.","zh":"增加了的壓力可以幫助氧氣更有效進入身體組織。"},{"en":"The phrase names a specialised medical or recovery device.","zh":"這個短語指出一種專門醫療或恢復裝置。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":8},{"front":"speed recovery","meaning":"加快康復","examples":[{"en":"The hyperbaric chamber helps speed recovery after vigorous exercise.","zh":"高壓氧艙有助在劇烈運動後加快康復。"},{"en":"To speed recovery means to make the body return to normal more quickly.","zh":"「speed recovery」意思是令身體更快回復正常。"},{"en":"Good sleep can speed recovery after illness or hard training.","zh":"良好睡眠可以在生病或艱苦訓練後加快康復。"},{"en":"If recovery is faster, athletes may return to training sooner and more safely.","zh":"如果恢復更快，運動員可以更早且更安全地恢復訓練。"},{"en":"The phrase focuses on reducing recovery time.","zh":"這個短語集中於縮短恢復時間。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":8},{"front":"vigorous exercise","meaning":"劇烈運動","examples":[{"en":"Athletes use the chamber after vigorous exercise.","zh":"運動員在劇烈運動後使用該氧艙。"},{"en":"Vigorous exercise is hard physical activity that uses a lot of energy.","zh":"「vigorous exercise」是耗費大量能量的高強度身體活動。"},{"en":"Fast running, competitive swimming and intense cycling are forms of vigorous exercise.","zh":"快跑、競技游泳和高強度踩單車都是劇烈運動。"},{"en":"Vigorous exercise can improve fitness, but it also requires proper recovery.","zh":"劇烈運動可以改善體能，但也需要適當恢復。"},{"en":"The phrase describes exercise that is demanding, not gentle.","zh":"這個短語描述要求高的運動，而不是溫和活動。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":8},{"front":"the natural state of","meaning":"……的自然狀態","examples":[{"en":"The natural state of oxygen does not change in the chamber.","zh":"氧氣在艙內的自然狀態沒有改變。"},{"en":"The natural state of something means its normal form or condition.","zh":"「the natural state of」某物，意思是它的正常形式或狀態。"},{"en":"Water’s natural state may be liquid at room temperature.","zh":"水在室溫下的自然狀態可能是液體。"},{"en":"If technology changes pressure but not oxygen itself, the natural state of oxygen remains the same.","zh":"如果科技改變壓力但沒有改變氧氣本身，氧氣的自然狀態仍然相同。"},{"en":"The phrase describes what something is like before special treatment or change.","zh":"這個短語描述某物在特殊處理或改變前的樣子。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":8},{"front":"green plants","meaning":"綠色植物","examples":[{"en":"Green plants produce oxygen.","zh":"綠色植物產生氧氣。"},{"en":"Green plants are plants with chlorophyll that use sunlight to make food.","zh":"「green plants」是含有葉綠素並使用陽光製造食物的植物。"},{"en":"Trees, grass and many vegetables are green plants.","zh":"樹木、草和許多蔬菜都是綠色植物。"},{"en":"Because green plants produce oxygen, they are important for life on Earth.","zh":"因為綠色植物產生氧氣，它們對地球生命很重要。"},{"en":"The phrase refers to ordinary plants that carry out photosynthesis.","zh":"這個短語指會進行光合作用的普通植物。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":8},{"front":"modern technology","meaning":"現代科技","examples":[{"en":"Modern technology increases the air pressure.","zh":"現代科技增加氣壓。"},{"en":"Modern technology means advanced tools, machines or systems used today.","zh":"「modern technology」指今天使用的先進工具、機器或系統。"},{"en":"Modern technology allows doctors to scan the body without surgery.","zh":"現代科技讓醫生不用手術也能掃描身體。"},{"en":"If modern technology measures athletes accurately, training can become more precise.","zh":"如果現代科技能準確量度運動員，訓練可以變得更精準。"},{"en":"The phrase contrasts today’s tools with older methods.","zh":"這個短語把今天的工具與舊方法作對比。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":8},{"front":"increase air pressure","meaning":"增加氣壓","examples":[{"en":"The hyperbaric chamber increases air pressure.","zh":"高壓氧艙增加氣壓。"},{"en":"To increase air pressure means to make the air push more strongly inside a space.","zh":"「increase air pressure」意思是令空氣在某空間內施加更大壓力。"},{"en":"A tyre pump increases air pressure inside a bicycle tyre.","zh":"單車打氣筒增加單車輪胎內的氣壓。"},{"en":"In a hyperbaric chamber, increased air pressure changes how oxygen enters the body.","zh":"在高壓氧艙中，增加氣壓會改變氧氣進入身體的方式。"},{"en":"The phrase describes a physical change in the surrounding air.","zh":"這個短語描述周圍空氣的物理變化。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":8},{"front":"alter molecular composition","meaning":"改變分子組成","examples":[{"en":"The chamber does not alter oxygen’s molecular composition.","zh":"該艙不會改變氧氣的分子組成。"},{"en":"To alter molecular composition means to change what a substance is made of at the molecular level.","zh":"「alter molecular composition」意思是在分子層面改變一種物質由什麼組成。"},{"en":"Heating ice changes its state, but it does not alter the molecular composition of water.","zh":"加熱冰會改變其狀態，但不會改變水的分子組成。"},{"en":"If oxygen’s molecular composition is not altered, it remains oxygen despite pressure changes.","zh":"如果氧氣的分子組成沒有被改變，即使壓力改變，它仍是氧氣。"},{"en":"The phrase is scientific and refers to chemical structure.","zh":"這個短語較科學，指化學結構。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":8},{"front":"molecular composition","meaning":"分子組成","examples":[{"en":"The molecular composition of oxygen remains unchanged.","zh":"氧氣的分子組成保持不變。"},{"en":"Molecular composition means the kinds and arrangement of molecules in a substance.","zh":"「molecular composition」指一種物質中分子的種類和排列。"},{"en":"Scientists study molecular composition to understand what a material is made of.","zh":"科學家研究分子組成，以理解材料由什麼構成。"},{"en":"If two substances have different molecular composition, they may behave very differently.","zh":"如果兩種物質分子組成不同，它們的表現可能非常不同。"},{"en":"The phrase explains chemical identity at a tiny scale.","zh":"這個短語在微小尺度上解釋化學身份。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":8},{"front":"increased pressure","meaning":"增加了的壓力","examples":[{"en":"Increased pressure allows oxygen to enter tissues more effectively.","zh":"增加了的壓力讓氧氣更有效進入身體組織。"},{"en":"Increased pressure means pressure that has been raised above the normal level.","zh":"「increased pressure」指被提高至正常水平以上的壓力。"},{"en":"Increased water pressure can make a shower feel stronger.","zh":"增加了的水壓可以令淋浴感覺更強。"},{"en":"In a recovery chamber, increased pressure changes how gases move into the body.","zh":"在恢復艙中，增加了的壓力會改變氣體進入身體的方式。"},{"en":"The phrase describes a higher level of force pushing on something.","zh":"這個短語描述作用於某物的更高力量水平。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":8},{"front":"allow oxygen to enter tissues","meaning":"讓氧氣進入組織","examples":[{"en":"Increased pressure allows oxygen to enter tissues more effectively.","zh":"增加了的壓力讓氧氣更有效進入身體組織。"},{"en":"To allow oxygen to enter tissues means to help oxygen move into body cells and structures.","zh":"「allow oxygen to enter tissues」意思是幫助氧氣進入身體細胞和結構。"},{"en":"Good blood flow allows oxygen to enter working muscles during exercise.","zh":"良好血液流動讓氧氣在運動期間進入工作的肌肉。"},{"en":"If oxygen enters tissues efficiently, recovery after effort may improve.","zh":"如果氧氣有效進入組織，用力後恢復可能改善。"},{"en":"The phrase explains how oxygen reaches parts of the body.","zh":"這個短語解釋氧氣如何到達身體各部分。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":8},{"front":"tissues","meaning":"身體組織","examples":[{"en":"Oxygen enters body tissues more effectively under increased pressure.","zh":"在增加了的壓力下，氧氣更有效進入身體組織。"},{"en":"Tissues are groups of cells in the body that work together.","zh":"「tissues」是身體中一起工作的細胞群。"},{"en":"Muscle tissue helps the body move, while skin tissue protects the body.","zh":"肌肉組織幫助身體活動，而皮膚組織保護身體。"},{"en":"If tissues receive more oxygen, they may recover better after intense exercise.","zh":"如果身體組織獲得更多氧氣，它們在劇烈運動後可能恢復得更好。"},{"en":"The word refers to body material, not paper tissues in this context.","zh":"在這個語境中，這個詞指身體組織，而不是紙巾。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":9},{"front":"more effectively","meaning":"更有效地","examples":[{"en":"Oxygen enters tissues more effectively in a hyperbaric chamber.","zh":"氧氣在高壓氧艙中更有效地進入身體組織。"},{"en":"More effectively means in a way that works better or produces better results.","zh":"「more effectively」意思是以更好或產生更好結果的方式。"},{"en":"Students learn more effectively when examples are clear and connected to daily life.","zh":"當例子清楚並連接日常生活，學生會更有效地學習。"},{"en":"If athletes recover more effectively, they may train again sooner without overloading the body.","zh":"如果運動員更有效地恢復，他們可能更快再次訓練而不會令身體過度負荷。"},{"en":"The phrase compares better performance or results.","zh":"這個短語比較更好的表現或結果。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":9},{"front":"recover from","meaning":"從……中恢復","examples":[{"en":"Athletes can recover from an intense workout more quickly.","zh":"運動員可以更快從高強度訓練中恢復。"},{"en":"To recover from something means to return to a normal or healthy state after it.","zh":"「recover from」某事，意思是在其後回到正常或健康狀態。"},{"en":"A student may need a weekend to recover from a week of exams.","zh":"學生可能需要一個週末從一週考試中恢復。"},{"en":"If athletes do not recover from hard training, their performance may decline.","zh":"如果運動員沒有從艱苦訓練中恢復，他們的表現可能下降。"},{"en":"The phrase is used after illness, effort, injury or stress.","zh":"這個短語可用於疾病、用力、受傷或壓力之後。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":9},{"front":"intense workout","meaning":"高強度訓練","examples":[{"en":"The chamber helps athletes recover from an intense workout.","zh":"該氧艙幫助運動員從高強度訓練中恢復。"},{"en":"An intense workout is a very hard training session that demands a lot of effort.","zh":"「intense workout」是需要大量努力的非常艱苦訓練。"},{"en":"A gym class with sprinting, lifting and little rest can be an intense workout.","zh":"包括短跑、舉重和很少休息的健身課可以是高強度訓練。"},{"en":"After an intense workout, muscles may feel tired and need recovery time.","zh":"高強度訓練後，肌肉可能感到疲倦並需要恢復時間。"},{"en":"The phrase describes high effort, not light exercise.","zh":"這個短語描述高強度用力，而不是輕度運動。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":9},{"front":"typically use","meaning":"通常使用","examples":[{"en":"The team typically uses the chamber three times a week.","zh":"隊伍通常每星期使用該氧艙三次。"},{"en":"Typically use means usually use something as part of a normal routine.","zh":"「typically use」意思是通常把某物作為正常流程的一部分使用。"},{"en":"Students typically use dictionaries when writing in a second language.","zh":"學生用第二語言寫作時通常使用字典。"},{"en":"If athletes typically use recovery equipment after training, it becomes part of their schedule.","zh":"如果運動員通常在訓練後使用恢復設備，它就成為時間表的一部分。"},{"en":"The phrase describes what normally happens, not what always happens.","zh":"這個短語描述通常發生的事，而不是永遠如此。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":9},{"front":"sessions of 45 to 60 minutes","meaning":"45至60分鐘的療程","examples":[{"en":"Athletes use the chamber for sessions of 45 to 60 minutes.","zh":"運動員使用該氧艙進行45至60分鐘的療程。"},{"en":"Sessions of 45 to 60 minutes are periods of activity lasting between three-quarters of an hour and one hour.","zh":"「sessions of 45 to 60 minutes」是持續四十五分鐘至一小時的活動時段。"},{"en":"A tutor may teach in sessions of 45 to 60 minutes to keep students focused.","zh":"導師可能以45至60分鐘的課節教學，以保持學生專注。"},{"en":"If recovery sessions are too long, athletes may find them difficult to fit into training schedules.","zh":"如果恢復療程太長，運動員可能難以把它們放進訓練時間表。"},{"en":"The phrase gives the length of each session.","zh":"這個短語說明每次療程的長度。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":9},{"front":"three times a week","meaning":"每星期三次","examples":[{"en":"Athletes may use the chamber three times a week.","zh":"運動員可能每星期三次使用該氧艙。"},{"en":"Three times a week means on three separate occasions each week.","zh":"「three times a week」意思是每週三個不同時間。"},{"en":"A student who practises speaking three times a week may improve steadily.","zh":"每星期三次練習口語的學生可能穩定進步。"},{"en":"If recovery treatment happens three times a week, it is a regular routine.","zh":"如果恢復治療每星期三次進行，它就是一個定期流程。"},{"en":"The phrase describes frequency.","zh":"這個短語描述頻率。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":9},{"front":"be pushed to the limit","meaning":"被推至極限","examples":[{"en":"Athletes are often pushed to the limit in training.","zh":"運動員在訓練中常被推至極限。"},{"en":"To be pushed to the limit means to be made to work as hard as one can safely manage.","zh":"「be pushed to the limit」意思是被要求盡可能努力工作或訓練。"},{"en":"A student may feel pushed to the limit during exam season if there is no rest.","zh":"如果沒有休息，學生在考試季可能感到被推至極限。"},{"en":"If athletes are pushed to the limit too often, recovery becomes essential.","zh":"如果運動員太常被推至極限，恢復就變得必要。"},{"en":"The phrase describes extreme demand on body or mind.","zh":"這個短語描述身體或心智上的極高要求。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":9},{"front":"true indicator of fitness","meaning":"體能的真正指標","examples":[{"en":"The true indicator of fitness is how quickly the heart recovers.","zh":"體能的真正指標是心臟恢復得有多快。"},{"en":"A true indicator of fitness is a reliable sign that shows how fit someone really is.","zh":"「true indicator of fitness」是可靠顯示某人真正體能狀況的跡象。"},{"en":"A fast run time may be impressive, but recovery speed can be another true indicator of fitness.","zh":"快速跑步成績可能令人印象深刻，但恢復速度也可以是體能的真正指標。"},{"en":"If the heart returns to normal quickly after exercise, it may show strong fitness.","zh":"如果心臟在運動後很快回復正常，這可能顯示強健體能。"},{"en":"The phrase points to a deeper measure, not just obvious effort.","zh":"這個短語指更深層的量度，而不只是明顯努力。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":9},{"front":"how hard the heart works","meaning":"心臟運作得有多吃力","examples":[{"en":"Fitness is not measured only by how hard the heart works.","zh":"體能不只由心臟運作得有多吃力來量度。"},{"en":"How hard the heart works means how much effort the heart makes during activity.","zh":"「how hard the heart works」意思是心臟在活動期間付出多少努力。"},{"en":"During a sprint, how hard the heart works can be seen in a rapid heartbeat.","zh":"短跑時，心跳快速可以顯示心臟運作得有多吃力。"},{"en":"If the heart works very hard but recovers slowly, fitness may still need improvement.","zh":"如果心臟非常吃力但恢復很慢，體能可能仍需改善。"},{"en":"The phrase describes effort, not the whole picture of heart health.","zh":"這個短語描述用力程度，而不是心臟健康的全部圖像。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":9},{"front":"recover after","meaning":"在……之後恢復","examples":[{"en":"The heart must recover quickly after an extreme workout.","zh":"心臟必須在極限訓練之後快速恢復。"},{"en":"Recover after means return to normal following an event or activity.","zh":"「recover after」意思是在某事件或活動之後回復正常。"},{"en":"Students need time to recover after several days of exams.","zh":"學生在連續幾天考試之後需要時間恢復。"},{"en":"If muscles recover after training, the next session can be safer and more productive.","zh":"如果肌肉在訓練之後恢復，下一次訓練可以更安全和更有效。"},{"en":"The phrase focuses on what happens after effort or stress.","zh":"這個短語集中於努力或壓力之後發生的事。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":9},{"front":"extreme workout","meaning":"極限訓練","examples":[{"en":"The athlete’s recovery is measured after an extreme workout.","zh":"運動員的恢復情況在極限訓練後被量度。"},{"en":"An extreme workout is a very demanding exercise session that pushes the body hard.","zh":"「extreme workout」是非常高要求、令身體高度用力的運動訓練。"},{"en":"A workout with repeated sprints and heavy lifting may be extreme for many people.","zh":"包含反覆短跑和重訓的訓練，對許多人來說可能是極限訓練。"},{"en":"After an extreme workout, doctors may check how quickly the heart and muscles recover.","zh":"極限訓練後，醫生可能檢查心臟和肌肉恢復得有多快。"},{"en":"The phrase suggests training near the athlete’s physical limit.","zh":"這個短語暗示接近運動員身體極限的訓練。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":10},{"front":"heart endurance","meaning":"心臟耐力","examples":[{"en":"Heart endurance has become an area of focus.","zh":"心臟耐力已成為一個重點範疇。"},{"en":"Heart endurance means the heart’s ability to keep working during effort and recover afterwards.","zh":"「heart endurance」指心臟在用力期間持續工作並在之後恢復的能力。"},{"en":"Long-distance running can improve heart endurance when training is gradual and safe.","zh":"當訓練循序漸進且安全時，長跑可以改善心臟耐力。"},{"en":"If heart endurance is weak, an athlete may tire quickly during long events.","zh":"如果心臟耐力弱，運動員可能在長時間項目中很快疲倦。"},{"en":"The phrase focuses on lasting cardiovascular performance.","zh":"這個短語集中於持久的心血管表現。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":10},{"front":"area of focus","meaning":"重點範疇","examples":[{"en":"Heart endurance is another area of focus for the Mexican team.","zh":"心臟耐力是墨西哥隊另一個重點範疇。"},{"en":"An area of focus is a subject that receives special attention.","zh":"「area of focus」是受到特別注意的主題。"},{"en":"Reading fluency may be an area of focus in an English course.","zh":"閱讀流暢度可能是英語課程中的重點範疇。"},{"en":"If recovery becomes an area of focus, training plans may include more rest and monitoring.","zh":"如果恢復成為重點範疇，訓練計劃可能包括更多休息和監測。"},{"en":"The phrase identifies what people are concentrating on.","zh":"這個短語指出人們正在集中注意的地方。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":10},{"front":"electroencephalograph","meaning":"腦電圖儀","examples":[{"en":"An electroencephalograph is used to measure recovery rate.","zh":"腦電圖儀用於量度恢復速度。"},{"en":"An electroencephalograph is a machine that records electrical activity in the brain.","zh":"「electroencephalograph」是一部記錄大腦電活動的機器。"},{"en":"Doctors may use an electroencephalograph to monitor brainwave patterns during a test.","zh":"醫生可能使用腦電圖儀在測試期間監測腦電波模式。"},{"en":"In sports research, such equipment can help track how the body responds after intense effort.","zh":"在運動研究中，這類設備可以幫助追蹤身體在劇烈用力後的反應。"},{"en":"The word is often shortened to EEG.","zh":"這個詞常縮寫為 EEG。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":10},{"front":"EEG","meaning":"腦電圖儀","examples":[{"en":"An EEG helps doctors monitor athletes during recovery.","zh":"腦電圖儀幫助醫生在恢復期間監測運動員。"},{"en":"EEG is the short form of electroencephalograph or electroencephalogram.","zh":"「EEG」是 electroencephalograph 或 electroencephalogram 的縮寫。"},{"en":"A hospital may use an EEG to record brainwave activity.","zh":"醫院可能使用 EEG 記錄腦電波活動。"},{"en":"If EEG data changes after exertion, doctors may study how the athlete is recovering.","zh":"如果 EEG 數據在用力後改變，醫生可能研究運動員如何恢復。"},{"en":"The abbreviation is common in medical and sports-science contexts.","zh":"這個縮寫常見於醫學和運動科學語境。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":10},{"front":"measure recovery rate","meaning":"量度恢復速度","examples":[{"en":"The EEG is used to measure the athlete’s recovery rate.","zh":"腦電圖儀用於量度運動員的恢復速度。"},{"en":"To measure recovery rate means to check how quickly someone returns to normal after effort.","zh":"「measure recovery rate」意思是檢查某人在用力後多快回復正常。"},{"en":"A fitness watch may measure recovery rate by tracking heart rate after exercise.","zh":"健身手錶可能透過追蹤運動後心率來量度恢復速度。"},{"en":"If recovery rate is slow, the athlete may need more rest or a different training plan.","zh":"如果恢復速度慢，運動員可能需要更多休息或不同訓練計劃。"},{"en":"The phrase connects measurement with post-exercise recovery.","zh":"這個短語把量度與運動後恢復連繫起來。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":10},{"front":"recovery rate","meaning":"恢復速度","examples":[{"en":"The recovery rate shows how quickly the athlete’s body recovers.","zh":"恢復速度顯示運動員的身體恢復得有多快。"},{"en":"Recovery rate is the speed at which someone returns to normal after effort, illness or injury.","zh":"「recovery rate」是某人在用力、生病或受傷後回復正常的速度。"},{"en":"A coach may compare recovery rates after the same running test.","zh":"教練可能比較同一跑步測試後的恢復速度。"},{"en":"A faster recovery rate can suggest better fitness or better rest.","zh":"較快恢復速度可以顯示較好體能或較好休息。"},{"en":"The phrase is useful when judging how well the body handles stress.","zh":"這個短語適合用來判斷身體如何處理壓力。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":10},{"front":"sensors placed on the scalp","meaning":"放在頭皮上的感應器","examples":[{"en":"Sensors placed on the scalp monitor brainwave activity.","zh":"放在頭皮上的感應器監測腦電波活動。"},{"en":"Sensors placed on the scalp are small devices attached to the skin on the head to collect signals.","zh":"「sensors placed on the scalp」是貼在頭部皮膚上收集訊號的小裝置。"},{"en":"In a medical test, sensors placed on the scalp can record brain activity without surgery.","zh":"在醫學測試中，放在頭皮上的感應器可以不用手術記錄大腦活動。"},{"en":"If sensors are not placed correctly, the results may be less accurate.","zh":"如果感應器放置不正確，結果可能較不準確。"},{"en":"The phrase describes both the equipment and its location.","zh":"這個短語同時描述設備和位置。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":10},{"front":"scalp","meaning":"頭皮","examples":[{"en":"The sensors are placed on the athlete’s scalp.","zh":"感應器被放在運動員的頭皮上。"},{"en":"The scalp is the skin on the top of the head where hair grows.","zh":"「scalp」是頭頂長頭髮的皮膚。"},{"en":"A doctor may check the scalp if a patient has a head injury or skin problem.","zh":"如果病人有頭部受傷或皮膚問題，醫生可能檢查頭皮。"},{"en":"Sensors are placed on the scalp because brain signals can be recorded from the head surface.","zh":"感應器放在頭皮上，因為大腦訊號可以從頭部表面記錄。"},{"en":"The word refers to skin on the head, not the skull bone itself.","zh":"這個詞指頭部皮膚，而不是頭骨本身。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":10},{"front":"monitor brainwave activity","meaning":"監測腦電波活動","examples":[{"en":"Doctors use sensors to monitor brainwave activity.","zh":"醫生使用感應器監測腦電波活動。"},{"en":"To monitor brainwave activity means to watch and record electrical patterns in the brain.","zh":"「monitor brainwave activity」意思是觀察和記錄大腦中的電活動模式。"},{"en":"Hospitals monitor brainwave activity during some sleep or seizure tests.","zh":"醫院在一些睡眠或癲癇測試中監測腦電波活動。"},{"en":"If brainwave activity changes after exercise, researchers may study the recovery process.","zh":"如果腦電波活動在運動後改變，研究人員可能研究恢復過程。"},{"en":"The phrase describes careful observation of brain signals.","zh":"這個短語描述對大腦訊號的仔細觀察。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":10},{"front":"brainwave activity","meaning":"腦電波活動","examples":[{"en":"Brainwave activity is monitored during the test.","zh":"測試期間會監測腦電波活動。"},{"en":"Brainwave activity means the electrical patterns produced by the brain.","zh":"「brainwave activity」指大腦產生的電活動模式。"},{"en":"Sleep studies often examine brainwave activity to understand different stages of sleep.","zh":"睡眠研究常檢查腦電波活動，以理解不同睡眠階段。"},{"en":"Changes in brainwave activity may show how the body responds to stress or recovery.","zh":"腦電波活動的變化可能顯示身體如何回應壓力或恢復。"},{"en":"The phrase belongs to medical and neuroscience contexts.","zh":"這個短語屬於醫學和神經科學語境。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":10},{"front":"exert intense effort","meaning":"付出高強度努力","examples":[{"en":"Athletes exert intense effort for a sustained period.","zh":"運動員在持續一段時間內付出高強度努力。"},{"en":"To exert intense effort means to use a very high level of physical or mental energy.","zh":"「exert intense effort」意思是使用非常高水平的身體或心理能量。"},{"en":"A student may exert intense effort when writing a difficult essay under time pressure.","zh":"學生在時間壓力下寫困難作文時，可能付出高強度努力。"},{"en":"If athletes exert intense effort for too long, their bodies need careful recovery.","zh":"如果運動員付出高強度努力太久，他們的身體需要仔細恢復。"},{"en":"The phrase describes strong and active use of energy.","zh":"這個短語描述強烈而主動地使用能量。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":11},{"front":"sustained period","meaning":"持續一段時間","examples":[{"en":"The athletes exercise intensely for a sustained period.","zh":"運動員持續一段時間進行高強度運動。"},{"en":"A sustained period is a length of time that continues without stopping quickly.","zh":"「sustained period」是一段持續而不是很快停止的時間。"},{"en":"Students need concentration for a sustained period during long exams.","zh":"學生在長時間考試中需要持續一段時間保持專注。"},{"en":"If effort continues for a sustained period, tiredness and recovery become important.","zh":"如果努力持續一段時間，疲勞和恢復就變得重要。"},{"en":"The phrase emphasises duration, not just intensity.","zh":"這個短語強調持續時間，而不只是強度。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":11},{"front":"be given time to","meaning":"獲給予時間去……","examples":[{"en":"Athletes are then given time to rest and recover.","zh":"運動員之後獲給予時間去休息和恢復。"},{"en":"To be given time to do something means to be allowed a period for that action.","zh":"「be given time to」做某事，意思是被允許有一段時間去做那件事。"},{"en":"Students should be given time to read instructions before starting an exam.","zh":"學生在開始考試前應獲給予時間閱讀指示。"},{"en":"If athletes are given time to recover, injury risk may decrease.","zh":"如果運動員獲給予時間恢復，受傷風險可能下降。"},{"en":"The phrase shows that time is deliberately provided.","zh":"這個短語顯示時間是被刻意提供的。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":11},{"front":"rest and recover","meaning":"休息和恢復","examples":[{"en":"Athletes need time to rest and recover after exertion.","zh":"運動員在用力後需要時間休息和恢復。"},{"en":"To rest and recover means to stop working hard so the body or mind can return to normal.","zh":"「rest and recover」意思是停止高強度工作，使身體或心智回復正常。"},{"en":"After a long school day, students may need to rest and recover before doing homework.","zh":"漫長上課日後，學生可能需要休息和恢復，再做功課。"},{"en":"If athletes never rest and recover, training can harm rather than help them.","zh":"如果運動員從不休息和恢復，訓練可能傷害他們，而不是幫助他們。"},{"en":"The phrase combines stopping activity with healing or regaining energy.","zh":"這個短語結合停止活動與復原或恢復能量。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":11},{"front":"transition from…to…","meaning":"從……到……的過渡","examples":[{"en":"Doctors monitor the transition from intense exertion to recovery.","zh":"醫生監測從劇烈用力到恢復的過渡。"},{"en":"A transition from one state to another is the change between the two.","zh":"「transition from…to…」指從一種狀態轉到另一種狀態的變化。"},{"en":"The transition from primary school to secondary school can be stressful for students.","zh":"從小學到中學的過渡可能令學生有壓力。"},{"en":"If the transition from exercise to recovery is slow, doctors may adjust training.","zh":"如果從運動到恢復的過渡很慢，醫生可能調整訓練。"},{"en":"The phrase focuses on movement between stages.","zh":"這個短語集中於階段之間的轉變。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":11},{"front":"intense exertion","meaning":"劇烈用力","examples":[{"en":"Intense exertion is followed by a period of recovery.","zh":"劇烈用力之後是一段恢復期。"},{"en":"Intense exertion means very hard physical or mental effort.","zh":"「intense exertion」意思是非常高強度的身體或心理努力。"},{"en":"Carrying heavy boxes upstairs can involve intense exertion for someone not used to it.","zh":"對不習慣的人來說，把重箱搬上樓可能涉及劇烈用力。"},{"en":"After intense exertion, the heart, lungs and muscles need time to settle down.","zh":"劇烈用力後，心臟、肺部和肌肉需要時間平復。"},{"en":"The phrase is more formal than hard effort.","zh":"這個短語比 hard effort 更正式。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":11},{"front":"monitor weaknesses","meaning":"監測弱點","examples":[{"en":"Doctors can monitor weaknesses in the way the heart responds.","zh":"醫生可以監測心臟反應方式中的弱點。"},{"en":"To monitor weaknesses means to watch and measure areas that may not be working well.","zh":"「monitor weaknesses」意思是觀察和量度可能運作不佳的地方。"},{"en":"A teacher may monitor weaknesses in students’ grammar before planning lessons.","zh":"老師可能在設計課堂前監測學生文法弱點。"},{"en":"If doctors monitor weaknesses early, they can prevent small problems becoming serious.","zh":"如果醫生及早監測弱點，他們可以防止小問題變嚴重。"},{"en":"The phrase combines observation with problem detection.","zh":"這個短語結合觀察和問題偵測。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":11},{"front":"the way the heart responds","meaning":"心臟作出反應的方式","examples":[{"en":"The test shows the way the heart responds after exertion.","zh":"測試顯示心臟在用力後作出反應的方式。"},{"en":"The way the heart responds means how the heart reacts to effort, stress or recovery.","zh":"「the way the heart responds」意思是心臟如何對努力、壓力或恢復作出反應。"},{"en":"A doctor may study the way the heart responds during a treadmill test.","zh":"醫生可能在跑步機測試中研究心臟作出反應的方式。"},{"en":"If the heart responds slowly after exercise, the athlete may need more recovery training.","zh":"如果心臟在運動後反應緩慢，運動員可能需要更多恢復訓練。"},{"en":"The phrase focuses on reaction, not just heart size or strength.","zh":"這個短語集中於反應，而不只是心臟大小或力量。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":11},{"front":"have a major impact on","meaning":"對……有重大影響","examples":[{"en":"The EEG has had a major impact on measuring endurance.","zh":"腦電圖儀對量度耐力有重大影響。"},{"en":"To have a major impact on something means to strongly affect it.","zh":"「have a major impact on」某事，意思是強烈影響它。"},{"en":"A good teacher can have a major impact on a student’s confidence.","zh":"好老師可以對學生信心有重大影響。"},{"en":"If new equipment improves testing, it can have a major impact on training decisions.","zh":"如果新設備改善測試，它可以對訓練決定有重大影響。"},{"en":"The phrase describes a strong influence, not a small effect.","zh":"這個短語描述強烈影響，而不是小效果。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":11},{"front":"muscular endurance","meaning":"肌肉耐力","examples":[{"en":"The EEG helps measure the heart’s muscular endurance.","zh":"腦電圖儀幫助量度心臟的肌肉耐力。"},{"en":"Muscular endurance is the ability of muscles to keep working over time.","zh":"「muscular endurance」是肌肉持續工作一段時間的能力。"},{"en":"Holding a plank for a long time tests muscular endurance.","zh":"長時間做平板支撐可以測試肌肉耐力。"},{"en":"If muscular endurance is low, an athlete may tire before the event ends.","zh":"如果肌肉耐力低，運動員可能在比賽結束前已疲倦。"},{"en":"The phrase focuses on lasting muscle performance, not one short burst of strength.","zh":"這個短語集中於持久肌肉表現，而不是一次短暫爆發力。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":11},{"front":"human life expectancy","meaning":"人類預期壽命","examples":[{"en":"Human life expectancy has increased greatly over time.","zh":"人類預期壽命隨時間大幅增加。"},{"en":"Human life expectancy means the average number of years people are expected to live.","zh":"「human life expectancy」指人們預期可活到的平均年數。"},{"en":"Better sanitation and medical care can raise human life expectancy.","zh":"更好的公共衛生和醫療可以提高人類預期壽命。"},{"en":"If life expectancy increases, more people live into older age.","zh":"如果預期壽命增加，更多人會活到較高年齡。"},{"en":"The phrase describes population averages, not the exact age one person will reach.","zh":"這個短語描述人口平均數，而不是某個人會活到的準確年齡。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":11},{"front":"between…and…","meaning":"介乎……與……之間","examples":[{"en":"In 1796, human life expectancy was between 25 and 36 years.","zh":"在1796年，人類預期壽命介乎25至36歲之間。"},{"en":"Between…and… gives a range with a lower and upper limit.","zh":"「between…and…」給出有下限和上限的範圍。"},{"en":"The meeting will take place between 2 p.m. and 4 p.m.","zh":"會議將於下午二時至四時之間舉行。"},{"en":"If a value is between two numbers, it is not lower than the first or higher than the second.","zh":"如果數值介乎兩個數字之間，它不低於第一個，也不高於第二個。"},{"en":"The phrase is used for time, numbers, places and comparisons.","zh":"這個短語可用於時間、數字、地方和比較。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":12},{"front":"nearly doubled","meaning":"幾乎翻倍","examples":[{"en":"By 1886, life expectancy had nearly doubled.","zh":"到1886年，預期壽命已幾乎翻倍。"},{"en":"Nearly doubled means became almost twice as much as before.","zh":"「nearly doubled」意思是幾乎變成以前的兩倍。"},{"en":"The number of students in the club nearly doubled after the new teacher arrived.","zh":"新老師到任後，社團學生人數幾乎翻倍。"},{"en":"If life expectancy nearly doubles, people live much longer than earlier generations.","zh":"如果預期壽命幾乎翻倍，人們比早期世代長壽得多。"},{"en":"The phrase describes a very large increase, but not exactly two times.","zh":"這個短語描述非常大的增長，但不是準確兩倍。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":12},{"front":"average Mexican","meaning":"一般墨西哥人","examples":[{"en":"In 1996, the average Mexican could expect to live for about 75 years.","zh":"在1996年，一般墨西哥人預期可活到約75歲。"},{"en":"The average Mexican means a typical person in Mexico, based on general population data.","zh":"「average Mexican」指根據一般人口數據所得出的典型墨西哥人。"},{"en":"A report may say the average Mexican uses public healthcare in a certain way.","zh":"報告可能說一般墨西哥人以某種方式使用公共醫療。"},{"en":"Average figures describe a population, but individuals may live very different lives.","zh":"平均數字描述人口，但個人生活可能非常不同。"},{"en":"The phrase uses one typical example to describe a broader national pattern.","zh":"這個短語用一個典型例子描述更廣泛的全國模式。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":12},{"front":"expect to live for","meaning":"預期可活到","examples":[{"en":"The average Mexican could expect to live for about 75 years.","zh":"一般墨西哥人預期可活到約75歲。"},{"en":"Expect to live for means be predicted to live for a certain length of time.","zh":"「expect to live for」意思是被預測可活某段時間。"},{"en":"People in countries with good healthcare may expect to live for longer than previous generations.","zh":"在醫療良好的國家，人們可能預期可活得比前幾代更久。"},{"en":"If life expectancy rises, children born today may expect to live for more years.","zh":"如果預期壽命上升，今天出生的孩子可能預期可活更多年。"},{"en":"The phrase is used for statistical prediction, not personal certainty.","zh":"這個短語用於統計預測，而不是個人確定性。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":12},{"front":"largely because of","meaning":"主要因為","examples":[{"en":"People are living longer largely because of modern science.","zh":"人們壽命更長，主要因為現代科學。"},{"en":"Largely because of means mainly due to a particular reason.","zh":"「largely because of」意思是主要由於某個原因。"},{"en":"The shop became popular largely because of friendly service and fair prices.","zh":"這間店受歡迎，主要因為服務友善和價格公平。"},{"en":"If athletes recover faster largely because of technology, equipment is a major factor.","zh":"如果運動員恢復更快主要因為科技，設備就是主要因素。"},{"en":"The phrase identifies the main cause while allowing other causes too.","zh":"這個短語指出主要原因，同時容許還有其他原因。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":12},{"front":"advances in modern science","meaning":"現代科學進步","examples":[{"en":"Life expectancy has increased because of advances in modern science.","zh":"預期壽命因現代科學進步而增加。"},{"en":"Advances in modern science are improvements in scientific knowledge, methods and technology.","zh":"「advances in modern science」是科學知識、方法和技術上的改善。"},{"en":"Vaccines and cleaner medical procedures are examples of advances in modern science.","zh":"疫苗和更清潔的醫療程序是現代科學進步的例子。"},{"en":"Such advances can help people live longer and recover from illness more safely.","zh":"這些進步可以幫助人們更長壽，並更安全地從疾病中恢復。"},{"en":"The phrase describes progress made through scientific development.","zh":"這個短語描述透過科學發展取得的進展。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":12},{"front":"sophisticated medical equipment","meaning":"先進醫療設備","examples":[{"en":"Sophisticated medical equipment is not the only factor.","zh":"先進醫療設備並非唯一因素。"},{"en":"Sophisticated medical equipment is advanced medical technology used for testing, diagnosis or treatment.","zh":"「sophisticated medical equipment」是用於測試、診斷或治療的先進醫療科技。"},{"en":"Hospitals use sophisticated medical equipment such as scanners and monitoring machines.","zh":"醫院使用掃描儀和監測機器等先進醫療設備。"},{"en":"If doctors have better equipment, they may detect health problems earlier.","zh":"如果醫生有更好的設備，他們可能更早發現健康問題。"},{"en":"The phrase suggests high-level technology, but the sentence reminds us other factors also matter.","zh":"這個短語暗示高水平科技，但句子提醒我們其他因素也重要。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":12},{"front":"not the only factor","meaning":"並非唯一因素","examples":[{"en":"Medical equipment is not the only factor behind longer lives.","zh":"醫療設備並非延長壽命背後的唯一因素。"},{"en":"Not the only factor means one cause matters, but other causes also matter.","zh":"「not the only factor」意思是某個原因重要，但其他原因也重要。"},{"en":"Exam technique is not the only factor in success; preparation and sleep also count.","zh":"考試技巧並非成功的唯一因素；準備和睡眠也有作用。"},{"en":"If better shoes reduce injuries, they are helpful but not the only factor in performance.","zh":"如果更好的鞋減少受傷，它們有幫助，但並非表現的唯一因素。"},{"en":"The phrase prevents an explanation from becoming too simple.","zh":"這個短語防止解釋變得過於簡單。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":12},{"front":"basic advances in engineering","meaning":"工程學的基本進步","examples":[{"en":"Basic advances in engineering also help protect athletes.","zh":"工程學的基本進步也幫助保護運動員。"},{"en":"Basic advances in engineering are practical improvements in design, materials and construction.","zh":"「basic advances in engineering」是設計、材料和建造方面的實用改善。"},{"en":"Better bicycle helmets are a basic engineering advance that can reduce injury.","zh":"更好的單車頭盔是一項可以減少受傷的基本工程進步。"},{"en":"If shoes are designed better, athletes may avoid repeated stress on their joints.","zh":"如果鞋履設計更好，運動員可能避免關節反覆受壓。"},{"en":"The phrase shows that even simple technical progress can matter.","zh":"這個短語顯示即使簡單技術進步也可以重要。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":12},{"front":"consider, for example","meaning":"以……為例","examples":[{"en":"Consider, for example, a professional tennis player.","zh":"以職業網球員為例。"},{"en":"Consider, for example introduces a specific example for readers to think about.","zh":"「consider, for example」用來引入一個具體例子，讓讀者思考。"},{"en":"Consider, for example, a student who studies hard but sleeps only four hours.","zh":"以一名努力溫習但只睡四小時的學生為例。"},{"en":"Writers use this phrase to make an abstract point easier to understand.","zh":"作者使用這個短語令抽象觀點更容易理解。"},{"en":"The phrase signals that an example will support the argument.","zh":"這個短語表示接下來的例子會支持論點。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":12},{"front":"professional tennis player","meaning":"職業網球員","examples":[{"en":"A professional tennis player benefits from better shoe design.","zh":"職業網球員受益於更好的鞋履設計。"},{"en":"A professional tennis player is someone who earns a living by competing in tennis.","zh":"「professional tennis player」是透過參加網球比賽謀生的人。"},{"en":"A professional tennis player trains footwork, strength, timing and mental focus.","zh":"職業網球員訓練步法、力量、時機和心理專注。"},{"en":"If shoes are poorly designed, a tennis player may suffer foot or hip injuries.","zh":"如果鞋履設計不良，網球員可能受到足部或髖部傷害。"},{"en":"The phrase refers to an athlete who plays tennis as a career.","zh":"這個短語指以網球為職業的運動員。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":12},{"front":"in the past","meaning":"在過去","examples":[{"en":"In the past, most tennis shoes had a simple design.","zh":"在過去，大多數網球鞋設計簡單。"},{"en":"In the past means during an earlier time.","zh":"「in the past」意思是在較早的時間。"},{"en":"In the past, students wrote letters by hand more often than they do today.","zh":"在過去，學生比今天更常手寫信件。"},{"en":"If equipment was simpler in the past, athletes may have faced more injury risks.","zh":"如果過去設備較簡單，運動員可能面對更多受傷風險。"},{"en":"The phrase contrasts earlier conditions with the present.","zh":"這個短語把早期情況與現在作對比。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":13},{"front":"fabric","meaning":"布料","examples":[{"en":"Most tennis shoes were once made of fabric.","zh":"大多數網球鞋曾經由布料製成。"},{"en":"Fabric is cloth or woven material used to make clothing, shoes or other items.","zh":"「fabric」是用來製作衣服、鞋或其他物品的布或織物材料。"},{"en":"A school uniform may be made from strong fabric that can be washed often.","zh":"校服可能由可經常清洗的耐用布料製成。"},{"en":"If shoes use only simple fabric, they may not provide enough support for intense sport.","zh":"如果鞋只使用簡單布料，它們可能無法為劇烈運動提供足夠支撐。"},{"en":"The word refers to material, not design.","zh":"這個詞指材料，而不是設計。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":13},{"front":"solid rubber sole","meaning":"實心橡膠鞋底","examples":[{"en":"Old tennis shoes had a solid rubber sole.","zh":"舊網球鞋有實心橡膠鞋底。"},{"en":"A solid rubber sole is a firm bottom part of a shoe made from rubber.","zh":"「solid rubber sole」是由橡膠製成、位於鞋底部的堅實部分。"},{"en":"A shoe’s sole touches the ground and affects grip, comfort and shock absorption.","zh":"鞋底接觸地面，並影響抓地力、舒適度和減震。"},{"en":"If the sole is too hard, repeated movement may put stress on the foot and hip.","zh":"如果鞋底太硬，重複動作可能對足部和髖部造成壓力。"},{"en":"The phrase describes one part of shoe construction.","zh":"這個短語描述鞋履結構的一部分。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":13},{"front":"poor design","meaning":"設計不良","examples":[{"en":"Poor design resulted in hip and foot injuries.","zh":"設計不良導致髖部和足部受傷。"},{"en":"Poor design means something is badly planned or made for its purpose.","zh":"「poor design」意思是某物在用途上規劃或製造得不好。"},{"en":"A chair with poor design may cause back pain after long use.","zh":"設計不良的椅子在長時間使用後可能造成背痛。"},{"en":"If sports shoes have poor design, they may fail to support movement safely.","zh":"如果運動鞋設計不良，它們可能無法安全支撐動作。"},{"en":"The phrase links bad planning with practical problems.","zh":"這個短語把差劣規劃與實際問題連繫起來。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":13},{"front":"result in","meaning":"導致","examples":[{"en":"Poor shoe design resulted in injuries.","zh":"鞋履設計不良導致受傷。"},{"en":"To result in something means to cause it to happen.","zh":"「result in」某事，意思是導致它發生。"},{"en":"Poor sleep can result in weak concentration the next day.","zh":"睡眠不足可以導致第二天專注力差。"},{"en":"If equipment is badly designed, it can result in injury or lower performance.","zh":"如果設備設計差劣，它可能導致受傷或較差表現。"},{"en":"The phrase clearly shows a cause-and-effect relationship.","zh":"這個短語清楚顯示因果關係。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":13},{"front":"hip and foot injuries","meaning":"髖部和足部受傷","examples":[{"en":"Badly designed shoes caused hip and foot injuries.","zh":"設計不良的鞋造成髖部和足部受傷。"},{"en":"Hip and foot injuries are injuries affecting the hip joint or feet.","zh":"「hip and foot injuries」是影響髖關節或足部的傷患。"},{"en":"A runner may suffer foot injuries if shoes do not absorb impact well.","zh":"如果鞋不能良好吸收衝擊，跑手可能足部受傷。"},{"en":"If the foot is not supported properly, stress can move upward and affect the hip.","zh":"如果足部沒有得到適當支撐，壓力可以向上移動並影響髖部。"},{"en":"The phrase names body areas harmed by poor equipment.","zh":"這個短語指出被差劣設備傷害的身體部位。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":13},{"front":"shoe technology","meaning":"鞋履科技","examples":[{"en":"Shoe technology has changed radically.","zh":"鞋履科技已徹底改變。"},{"en":"Shoe technology means the materials, design and engineering used to make shoes perform better.","zh":"「shoe technology」指用來令鞋表現更好的材料、設計和工程。"},{"en":"Running shoes use shoe technology to cushion impact and support movement.","zh":"跑鞋使用鞋履科技來緩衝衝擊並支撐動作。"},{"en":"Improved shoe technology can reduce injury risk for both elite and recreational athletes.","zh":"改良鞋履科技可以降低精英和業餘運動員的受傷風險。"},{"en":"The phrase treats shoes as engineered equipment, not just clothing.","zh":"這個短語把鞋視為工程設備，而不只是衣物。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":13},{"front":"change radically","meaning":"徹底改變","examples":[{"en":"Shoe technology has changed radically over time.","zh":"鞋履科技隨時間徹底改變。"},{"en":"To change radically means to change in a major and deep way.","zh":"「change radically」意思是發生重大而深層的改變。"},{"en":"Mobile phones changed radically when they became smartphones.","zh":"當手機變成智能手機時，它們徹底改變。"},{"en":"If sports equipment changes radically, athletes may train and compete differently.","zh":"如果運動裝備徹底改變，運動員可能以不同方式訓練和比賽。"},{"en":"The phrase describes a large transformation, not a small update.","zh":"這個短語描述重大轉變，而不是小更新。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":13},{"front":"contain silicone","meaning":"含有矽膠","examples":[{"en":"Some modern shoes contain silicone.","zh":"一些現代鞋含有矽膠。"},{"en":"To contain silicone means to include silicone as one of the materials.","zh":"「contain silicone」意思是把矽膠作為其中一種材料。"},{"en":"Some phone cases contain silicone because it is flexible and protective.","zh":"一些手機殼含有矽膠，因為它有彈性且具保護作用。"},{"en":"If shoes contain silicone, they may absorb shock or improve comfort.","zh":"如果鞋含有矽膠，它們可能吸收震動或提高舒適度。"},{"en":"The phrase describes what a product is made with.","zh":"這個短語描述產品由什麼材料製成。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":13},{"front":"ergonomic design","meaning":"人體工學設計","examples":[{"en":"Modern shoes often have a more comfortable, ergonomic design.","zh":"現代鞋通常有更舒適的人體工學設計。"},{"en":"Ergonomic design means design that fits the human body and supports safe movement.","zh":"「ergonomic design」意思是符合人體並支援安全動作的設計。"},{"en":"An ergonomic chair can reduce back pain during long hours of study or work.","zh":"人體工學椅可以減少長時間學習或工作時的背痛。"},{"en":"If sports shoes have ergonomic design, they can protect feet during repeated movement.","zh":"如果運動鞋有人體工學設計，它們可以在重複動作中保護雙腳。"},{"en":"The phrase connects comfort, body shape and function.","zh":"這個短語連接舒適度、人體形狀和功能。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":13},{"front":"be adapted to","meaning":"適應……","examples":[{"en":"Ergonomic products are adapted to the shape of the human body.","zh":"人體工學產品適應人體形狀。"},{"en":"To be adapted to something means to be changed or designed to fit it.","zh":"「be adapted to」某物，意思是被改變或設計成適合它。"},{"en":"Lessons can be adapted to younger students by using simpler examples.","zh":"課堂可以透過使用較簡單例子來適應年幼學生。"},{"en":"If equipment is adapted to the body, it may feel more comfortable and safer.","zh":"如果設備適應身體，它可能更舒適和安全。"},{"en":"The phrase shows adjustment for a particular need or condition.","zh":"這個短語顯示為特定需要或條件作出調整。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":13},{"front":"the shape of the human body","meaning":"人體形狀","examples":[{"en":"Ergonomic design fits the shape of the human body.","zh":"人體工學設計符合人體形狀。"},{"en":"The shape of the human body means the natural form and structure of people’s bodies.","zh":"「the shape of the human body」指人的身體自然形態和結構。"},{"en":"A backpack should match the shape of the human body to reduce shoulder strain.","zh":"背包應符合人體形狀，以減少肩膀壓力。"},{"en":"If a product ignores body shape, it may cause discomfort during long use.","zh":"如果產品忽略身體形狀，長時間使用時可能造成不適。"},{"en":"The phrase explains why ergonomic products are designed carefully.","zh":"這個短語解釋人體工學產品為何需要仔細設計。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":14},{"front":"protect the bodies of","meaning":"保護……的身體","examples":[{"en":"Better shoe technology protects the bodies of sportspeople.","zh":"更好的鞋履科技保護運動人士的身體。"},{"en":"To protect the bodies of people means to reduce physical harm to them.","zh":"「protect the bodies of」某些人，意思是減少對他們身體的傷害。"},{"en":"Safety helmets protect the bodies of cyclists by reducing head injury risk.","zh":"安全頭盔透過降低頭部受傷風險來保護單車手的身體。"},{"en":"If shoes absorb impact well, they can protect athletes’ feet, knees and hips.","zh":"如果鞋能良好吸收衝擊，它們可以保護運動員的腳、膝和髖部。"},{"en":"The phrase focuses on physical safety.","zh":"這個短語集中於身體安全。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":14},{"front":"recreational sportspeople","meaning":"業餘運動人士","examples":[{"en":"Recreational sportspeople also benefit from better equipment.","zh":"業餘運動人士也受益於更好的裝備。"},{"en":"Recreational sportspeople are people who play sport for enjoyment, health or leisure rather than as professionals.","zh":"「recreational sportspeople」是為了樂趣、健康或休閒而運動的人，而不是職業運動員。"},{"en":"Weekend runners and casual tennis players are recreational sportspeople.","zh":"週末跑手和休閒網球玩家都是業餘運動人士。"},{"en":"If recreational sportspeople use better shoes, they may reduce injury during exercise.","zh":"如果業餘運動人士使用更好的鞋，他們可能減少運動時受傷。"},{"en":"The phrase contrasts ordinary active people with elite athletes.","zh":"這個短語把普通活躍人士與精英運動員作對比。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":14},{"front":"as well as","meaning":"以及；也包括","examples":[{"en":"Recreational as well as elite sportspeople benefit from better shoes.","zh":"業餘運動人士以及精英運動員都受益於更好的鞋。"},{"en":"As well as means in addition to or also.","zh":"「as well as」意思是以及、也包括。"},{"en":"The course teaches speaking as well as writing.","zh":"這門課教授口語以及寫作。"},{"en":"If both recreational and elite athletes benefit, the technology helps a wide range of people.","zh":"如果業餘和精英運動員都受益，這項科技就幫助廣泛人群。"},{"en":"The phrase adds another group or item without replacing the first.","zh":"這個短語加入另一個群體或項目，而不是取代第一個。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":14},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"Students must decide which paragraph contains the information.","zh":"學生必須判斷哪一段包含該資料。"},{"en":"Which paragraph contains asks students to find the part of the text where certain information appears.","zh":"「which paragraph contains」要求學生找出文本中哪一部分出現某些資料。"},{"en":"In a reading test, students scan headings and key words to see which paragraph contains the answer.","zh":"在閱讀測驗中，學生掃讀標題和關鍵詞，以找出哪一段包含答案。"},{"en":"If students choose the wrong paragraph, they may have found a similar idea but not the exact information.","zh":"如果學生選錯段落，他們可能找到相似想法，但不是準確資料。"},{"en":"The phrase gives an instruction for locating information in a passage.","zh":"這個短語是定位文章資料的題目指示。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":14},{"front":"the following information","meaning":"以下資料","examples":[{"en":"The question asks students to locate the following information.","zh":"問題要求學生定位以下資料。"},{"en":"The following information means the details listed immediately after the instruction.","zh":"「the following information」指指示後面立即列出的細節。"},{"en":"Students should read the following information before searching the passage.","zh":"學生應先閱讀以下資料，再搜尋文章。"},{"en":"If the following information includes names or numbers, those can help with scanning.","zh":"如果以下資料包括名字或數字，那些可以幫助掃讀。"},{"en":"The phrase points forward to the details that must be found.","zh":"這個短語指向接下來必須找到的細節。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":14},{"front":"use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"The instructions say students may use any letter more than once.","zh":"指示說學生可重複使用任何字母。"},{"en":"Use any letter more than once means the same option can be chosen for more than one answer.","zh":"「use any letter more than once」意思是同一選項可以用於多於一個答案。"},{"en":"In a matching task, one paragraph may match two pieces of information.","zh":"在配對題中，一段可能對應兩項資料。"},{"en":"If students assume each letter can be used only once, they may make avoidable mistakes.","zh":"如果學生以為每個字母只能用一次，他們可能犯可避免的錯誤。"},{"en":"The phrase changes how answer choices should be managed.","zh":"這個短語改變處理答案選項的方式。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":14},{"front":"natural process of oxygen production","meaning":"氧氣產生的自然過程","examples":[{"en":"The paragraph explains the natural process of oxygen production.","zh":"該段解釋氧氣產生的自然過程。"},{"en":"The natural process of oxygen production means how oxygen is produced in nature, especially by green plants.","zh":"「natural process of oxygen production」指氧氣在自然中如何產生，尤其是由綠色植物產生。"},{"en":"Students learn about this process when they study photosynthesis in biology.","zh":"學生在生物課學習光合作用時，會認識這個過程。"},{"en":"If plants produce oxygen naturally, technology may change pressure without changing oxygen itself.","zh":"如果植物自然產生氧氣，科技可能改變壓力，但不改變氧氣本身。"},{"en":"The phrase connects biology with the explanation of oxygen use.","zh":"這個短語把生物學與氧氣使用的解釋連繫起來。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":14},{"front":"standard post-competition procedures","meaning":"賽後標準程序","examples":[{"en":"The passage describes standard post-competition procedures for athletes.","zh":"文章描述運動員的賽後標準程序。"},{"en":"Standard post-competition procedures are normal steps followed after a competition.","zh":"「standard post-competition procedures」是比賽後遵循的正常步驟。"},{"en":"After a match, standard procedures may include medical checks, stretching and recovery planning.","zh":"比賽後，標準程序可能包括身體檢查、伸展和恢復規劃。"},{"en":"If athletes follow standard post-competition procedures, injuries can be noticed earlier.","zh":"如果運動員遵循賽後標準程序，傷患可以更早被注意到。"},{"en":"The phrase refers to routine actions after competing.","zh":"這個短語指比賽後的例行行動。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":14},{"front":"areas studied","meaning":"被研究的範疇","examples":[{"en":"The centre covers many areas studied to improve sports performance.","zh":"該中心涵蓋許多為提升運動表現而被研究的範疇。"},{"en":"Areas studied are the subjects or fields that researchers examine.","zh":"「areas studied」是研究人員考察的主題或領域。"},{"en":"In education research, areas studied may include memory, motivation and classroom behaviour.","zh":"在教育研究中，被研究的範疇可能包括記憶、動機和課堂行為。"},{"en":"If many areas are studied together, researchers can understand a problem more completely.","zh":"如果許多範疇一起被研究，研究人員可以更完整理解問題。"},{"en":"The phrase identifies the scope of research.","zh":"這個短語指出研究範圍。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":14},{"front":"improve athletic performance","meaning":"提升運動表現","examples":[{"en":"Sports science is used to improve athletic performance.","zh":"運動科學被用來提升運動表現。"},{"en":"To improve athletic performance means to help athletes compete or train better.","zh":"「improve athletic performance」意思是幫助運動員更好比賽或訓練。"},{"en":"Better sleep, nutrition and coaching can improve athletic performance.","zh":"更好睡眠、營養和教練指導可以提升運動表現。"},{"en":"If performance improves, athletes may run faster, recover sooner or avoid injury.","zh":"如果表現提升，運動員可能跑得更快、恢復更快或避免受傷。"},{"en":"The phrase focuses on practical improvement in sport.","zh":"這個短語集中於運動中的實際改善。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":14},{"front":"Mexican viewpoint on winning","meaning":"墨西哥對勝利的看法","examples":[{"en":"The Mexican viewpoint on winning emphasises team effort.","zh":"墨西哥對勝利的看法強調團隊努力。"},{"en":"A viewpoint on winning is a way of thinking about what victory means and how it is achieved.","zh":"「viewpoint on winning」是對勝利意味什麼以及如何達成勝利的看法。"},{"en":"Some people see winning as individual glory, while others see it as shared effort.","zh":"有些人把勝利看成個人榮耀，而另一些人把它看成共同努力。"},{"en":"If the Mexican viewpoint stresses teamwork, support staff are part of the success story.","zh":"如果墨西哥觀點強調團隊合作，支援人員就是成功故事的一部分。"},{"en":"The phrase describes a cultural or national attitude toward victory.","zh":"這個短語描述對勝利的文化或國家態度。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":15},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students must choose the correct letter from the options.","zh":"學生必須從選項中選出正確字母。"},{"en":"To choose the correct letter means to select the option letter that matches the answer.","zh":"「choose the correct letter」意思是選擇與答案相符的選項字母。"},{"en":"In multiple-choice questions, students should read all options before choosing the correct letter.","zh":"在多項選擇題中，學生應先閱讀所有選項再選出正確字母。"},{"en":"If two options look similar, careful reading helps avoid choosing the wrong letter.","zh":"如果兩個選項看似相似，仔細閱讀有助避免選錯字母。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":15},{"front":"write your answers","meaning":"寫下答案","examples":[{"en":"Students write their answers in the answer boxes.","zh":"學生在答案框中寫下答案。"},{"en":"Write your answers means record the chosen responses in the correct place.","zh":"「write your answers」意思是在正確位置記錄所選答案。"},{"en":"During an exam, students should write their answers clearly so they can be marked.","zh":"在考試中，學生應清楚寫下答案，以便批改。"},{"en":"If answers are written in the wrong box, correct understanding may still lose marks.","zh":"如果答案寫在錯誤框中，即使理解正確也可能失分。"},{"en":"The phrase gives a practical test instruction.","zh":"這個短語給出實際考試指示。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":15},{"front":"recovery time","meaning":"恢復時間","examples":[{"en":"The hyperbaric chamber speeds up athletes’ recovery time.","zh":"高壓氧艙加快運動員的恢復時間。"},{"en":"Recovery time is the period needed to return to normal after effort, injury or illness.","zh":"「recovery time」是用力、受傷或生病後回復正常所需的時間。"},{"en":"After a hard race, a runner may need longer recovery time than after light jogging.","zh":"艱苦比賽後，跑手可能比輕鬆慢跑後需要更長恢復時間。"},{"en":"If recovery time becomes shorter, athletes may train more often without excessive strain.","zh":"如果恢復時間變短，運動員可能更常訓練而不過度受壓。"},{"en":"The phrase measures how long recovery takes.","zh":"這個短語量度恢復需要多久。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":15},{"front":"identify heart problems","meaning":"識別心臟問題","examples":[{"en":"The option says the EEG helps doctors identify heart problems.","zh":"該選項說腦電圖儀幫助醫生識別心臟問題。"},{"en":"To identify heart problems means to find signs that the heart may not be working properly.","zh":"「identify heart problems」意思是找出心臟可能運作不正常的跡象。"},{"en":"Doctors may identify heart problems through tests, symptoms and medical history.","zh":"醫生可能透過測試、症狀和病歷識別心臟問題。"},{"en":"If heart problems are identified early, treatment or training changes can begin sooner.","zh":"如果心臟問題及早被識別，治療或訓練改變可以更早開始。"},{"en":"The phrase focuses on recognising a medical issue.","zh":"這個短語集中於辨認醫療問題。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":15},{"front":"strengthen heart muscles","meaning":"強化心臟肌肉","examples":[{"en":"The option suggests that the EEG strengthens athletes’ heart muscles.","zh":"該選項暗示腦電圖儀強化運動員的心臟肌肉。"},{"en":"To strengthen heart muscles means to make the heart stronger through suitable activity or treatment.","zh":"「strengthen heart muscles」意思是透過適當活動或治療令心臟更強。"},{"en":"Regular aerobic exercise can help strengthen the heart over time.","zh":"定期帶氧運動可以隨時間幫助強化心臟。"},{"en":"If a device only measures recovery, it does not necessarily strengthen heart muscles.","zh":"如果一部裝置只是量度恢復，它不一定會強化心臟肌肉。"},{"en":"The phrase describes improvement in heart strength, not measurement.","zh":"這個短語描述心臟力量的改善，而不是量度。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":15},{"front":"life expectancy in Mexico","meaning":"墨西哥的預期壽命","examples":[{"en":"Life expectancy in Mexico has increased over time.","zh":"墨西哥的預期壽命隨時間增加。"},{"en":"Life expectancy in Mexico means the average number of years people in Mexico are expected to live.","zh":"「life expectancy in Mexico」指墨西哥人預期可活到的平均年數。"},{"en":"A report on life expectancy in Mexico may compare past and present health conditions.","zh":"關於墨西哥預期壽命的報告可能比較過去和現在的健康狀況。"},{"en":"If life expectancy rises, public health and medical progress may be part of the reason.","zh":"如果預期壽命上升，公共衛生和醫療進步可能是部分原因。"},{"en":"The phrase focuses on population health in one country.","zh":"這個短語集中於一個國家的人口健康。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":15},{"front":"medical advances","meaning":"醫學進步","examples":[{"en":"Medical advances have helped increase life expectancy.","zh":"醫學進步幫助提高預期壽命。"},{"en":"Medical advances are improvements in healthcare knowledge, treatment and equipment.","zh":"「medical advances」是醫療知識、治療和設備方面的改善。"},{"en":"Antibiotics, vaccines and better surgery are examples of medical advances.","zh":"抗生素、疫苗和更好的手術都是醫學進步的例子。"},{"en":"If medical advances reduce deaths from disease, people may live longer.","zh":"如果醫學進步減少疾病死亡，人們可能更長壽。"},{"en":"The phrase describes progress in medicine.","zh":"這個短語描述醫學方面的進展。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":15},{"front":"committed doctors","meaning":"更投入的醫生","examples":[{"en":"The option mentions more committed doctors.","zh":"該選項提到更投入的醫生。"},{"en":"Committed doctors are doctors who are strongly dedicated to caring for patients.","zh":"「committed doctors」是非常致力於照顧病人的醫生。"},{"en":"A committed doctor may spend extra time explaining treatment to a worried patient.","zh":"投入的醫生可能花額外時間向擔心的病人解釋治療。"},{"en":"If doctors are committed, healthcare quality may improve, but equipment and systems still matter.","zh":"如果醫生投入，醫療質素可能改善，但設備和制度仍然重要。"},{"en":"The phrase focuses on attitude and dedication.","zh":"這個短語集中於態度和奉獻。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":15},{"front":"better-made sporting equipment","meaning":"製作更好的運動裝備","examples":[{"en":"Better-made sporting equipment can protect athletes’ bodies.","zh":"製作更好的運動裝備可以保護運動員的身體。"},{"en":"Better-made sporting equipment is sports gear designed and built with higher quality.","zh":"「better-made sporting equipment」是設計和製作質素較高的運動裝備。"},{"en":"Better-made helmets, shoes and rackets can improve safety and comfort.","zh":"製作更好的頭盔、鞋和球拍可以提高安全和舒適度。"},{"en":"If equipment is better-made, athletes may suffer fewer injuries from repeated movement.","zh":"如果裝備製作更好，運動員可能因重複動作而受傷較少。"},{"en":"The phrase connects product quality with performance and protection.","zh":"這個短語把產品質素與表現和保護連繫起來。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":15},{"front":"advances in ergonomics","meaning":"人體工學進步","examples":[{"en":"Advances in ergonomics have improved sports equipment.","zh":"人體工學進步改善了運動裝備。"},{"en":"Advances in ergonomics are improvements in designing products to fit the human body better.","zh":"「advances in ergonomics」是在把產品設計得更符合人體方面的進步。"},{"en":"Office chairs improved through advances in ergonomics that support the back.","zh":"辦公椅透過支撐背部的人體工學進步而改善。"},{"en":"In sport, ergonomic progress can make shoes safer and more comfortable.","zh":"在運動中，人體工學進步可以令鞋更安全和更舒適。"},{"en":"The phrase links design progress with human comfort and safety.","zh":"這個短語把設計進步與人體舒適和安全連繫起來。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":15},{"front":"agree with the information given","meaning":"與所給資料一致","examples":[{"en":"Students decide whether statements agree with the information given.","zh":"學生判斷陳述是否與所給資料一致。"},{"en":"Agree with the information given means match what the passage or source says.","zh":"「agree with the information given」意思是符合文章或來源所說。"},{"en":"In a reading test, an answer agrees with the information only if the text supports it clearly.","zh":"在閱讀測驗中，只有文本清楚支持答案，它才與所給資料一致。"},{"en":"If a statement sounds reasonable but is not in the passage, it may not agree with the information given.","zh":"如果陳述聽起來合理但不在文章中，它可能不與所給資料一致。"},{"en":"The phrase reminds students to use evidence, not opinion.","zh":"這個短語提醒學生使用證據，而不是意見。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":16},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與文章中的資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the source says.","zh":"「contradict the information」意思是說出與來源相反的內容。"},{"en":"If the passage says the facility is well funded but the statement says it lacks money, the statement contradicts the information.","zh":"如果文章說該中心資金充足，但陳述說它缺乏金錢，該陳述就與資料相矛盾。"},{"en":"Students should choose FALSE only when there is a clear conflict with the text.","zh":"學生只應在與文本有清楚衝突時選 FALSE。"},{"en":"The phrase is used when checking accuracy against a source.","zh":"這個短語用於根據來源檢查準確性。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":16},{"front":"no information on this","meaning":"沒有這方面的資料","examples":[{"en":"Write NOT GIVEN if there is no information on this.","zh":"如果沒有這方面的資料，寫 NOT GIVEN。"},{"en":"No information on this means the passage does not clearly say anything about that point.","zh":"「no information on this」意思是文章沒有清楚說明該點。"},{"en":"If the text never mentions an athlete’s age, there is no information on this.","zh":"如果文本從未提及運動員年齡，便沒有這方面的資料。"},{"en":"A statement may seem likely, but without evidence it should not be treated as true.","zh":"某陳述可能看似合理，但沒有證據時不應當作真實。"},{"en":"The phrase helps students avoid guessing in reading questions.","zh":"這個短語幫助學生在閱讀題中避免猜測。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":16},{"front":"limits to the scope of","meaning":"……範圍的限制","examples":[{"en":"The statement asks whether there are limits to the scope of sporting research.","zh":"該陳述問體育研究的範圍是否有限制。"},{"en":"Limits to the scope of something are boundaries on what it covers or includes.","zh":"「limits to the scope of」某事，是它涵蓋或包括內容上的邊界。"},{"en":"A school project may have limits to its scope if students can study only one neighbourhood.","zh":"如果學生只能研究一個社區，學校項目可能有範圍限制。"},{"en":"If there are no clear limits to research, the topic may become too wide to manage.","zh":"如果研究沒有清楚範圍限制，主題可能變得太廣而難以處理。"},{"en":"The phrase is useful when discussing how broad a study or activity can be.","zh":"當討論研究或活動可以有多廣時，這個短語很有用。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":16},{"front":"sporting research","meaning":"體育研究","examples":[{"en":"Sporting research covers many scientific areas.","zh":"體育研究涵蓋許多科學範疇。"},{"en":"Sporting research is research into sport, athletes, training, equipment and performance.","zh":"「sporting research」是關於運動、運動員、訓練、裝備和表現的研究。"},{"en":"A university may do sporting research on injury prevention and recovery.","zh":"大學可能進行關於預防受傷和恢復的體育研究。"},{"en":"If sporting research is applied well, athletes and ordinary exercisers can both benefit.","zh":"如果體育研究被良好應用，運動員和普通運動人士都可以受益。"},{"en":"The phrase refers to scientific study related to sport.","zh":"這個短語指與體育相關的科學研究。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":16},{"front":"athletic programmes","meaning":"運動員訓練計劃","examples":[{"en":"Athletic programmes are now designed for individual athletes.","zh":"運動員訓練計劃現在為個別運動員而設計。"},{"en":"Athletic programmes are planned systems of training and support for athletes.","zh":"「athletic programmes」是為運動員制定的訓練和支援系統。"},{"en":"A school may create athletic programmes for running, swimming and basketball teams.","zh":"學校可能為跑步、游泳和籃球隊制定運動員訓練計劃。"},{"en":"If athletic programmes are personalised, athletes can train according to their own needs.","zh":"如果訓練計劃個人化，運動員可以根據自己的需要訓練。"},{"en":"The phrase refers to organised training plans, not single exercises.","zh":"這個短語指有組織的訓練計劃，而不是單一運動。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":16},{"front":"differ mainly between","meaning":"主要在……之間不同","examples":[{"en":"The statement asks whether programmes differ mainly between men and women.","zh":"該陳述問訓練計劃是否主要在男女之間不同。"},{"en":"Differ mainly between means be different mostly according to two groups or categories.","zh":"「differ mainly between」意思是差異主要根據兩個群體或類別而出現。"},{"en":"School uniforms may differ mainly between younger and older students.","zh":"校服可能主要在年幼學生和年長學生之間不同。"},{"en":"If training programmes differ mainly between men and women, gender is the main basis for difference.","zh":"如果訓練計劃主要在男女之間不同，性別就是差異的主要基礎。"},{"en":"The phrase is useful when identifying the main source of variation.","zh":"這個短語適合用來辨認變化的主要來源。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":16},{"front":"sporting resources","meaning":"體育資源","examples":[{"en":"Mexico and Germany are described as having similar sporting resources.","zh":"墨西哥和德國被描述為擁有相似體育資源。"},{"en":"Sporting resources are the money, facilities, equipment and expert support available for sport.","zh":"「sporting resources」是可用於體育的金錢、設施、設備和專家支援。"},{"en":"A school with strong sporting resources may have coaches, pitches and medical support.","zh":"擁有強大體育資源的學校可能有教練、球場和醫療支援。"},{"en":"If a country lacks sporting resources, talented athletes may not receive enough help.","zh":"如果一個國家缺乏體育資源，有天分的運動員可能得不到足夠幫助。"},{"en":"The phrase refers to the support system behind sport.","zh":"這個短語指體育背後的支援系統。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":16},{"front":"a lack of money","meaning":"缺乏金錢","examples":[{"en":"A lack of money can hinder athletes in poorer countries.","zh":"缺乏金錢可以阻礙較貧窮國家的運動員。"},{"en":"A lack of money means there is not enough funding to pay for what is needed.","zh":"「a lack of money」意思是沒有足夠資金支付所需項目。"},{"en":"A student may miss a school trip because of a lack of money.","zh":"學生可能因缺乏金錢而錯過學校旅行。"},{"en":"If sports teams face a lack of money, they may struggle to buy equipment or hire coaches.","zh":"如果運動隊面對缺乏金錢，他們可能難以購買設備或聘請教練。"},{"en":"The phrase describes a financial shortage.","zh":"這個短語描述財政短缺。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":16},{"front":"prevent athletic development","meaning":"阻礙運動發展","examples":[{"en":"The statement asks whether money problems prevent athletic development.","zh":"該陳述問金錢問題是否阻礙運動發展。"},{"en":"To prevent athletic development means to stop athletes from improving or reaching higher levels.","zh":"「prevent athletic development」意思是阻止運動員進步或達到更高水平。"},{"en":"Lack of safe training spaces can prevent athletic development in young players.","zh":"缺乏安全訓練場地可以阻礙年輕球員的運動發展。"},{"en":"If athletes cannot afford coaching, their development may slow down.","zh":"如果運動員負擔不起教練費，他們的發展可能變慢。"},{"en":"The phrase connects an obstacle with blocked sporting progress.","zh":"這個短語把障礙與受阻的體育進步連繫起來。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":16},{"front":"wealthy countries","meaning":"富裕國家","examples":[{"en":"The statement refers to athletic success in wealthy countries.","zh":"該陳述提到富裕國家的運動成功。"},{"en":"Wealthy countries are countries with high levels of income and resources.","zh":"「wealthy countries」是收入和資源水平高的國家。"},{"en":"Wealthy countries may have better sports facilities, coaches and medical support.","zh":"富裕國家可能有更好的體育設施、教練和醫療支援。"},{"en":"However, wealth alone does not guarantee athletic success.","zh":"然而，財富本身並不保證運動成功。"},{"en":"The phrase describes national economic status.","zh":"這個短語描述國家經濟狀況。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":16},{"front":"athletic success","meaning":"運動成功","examples":[{"en":"The passage does not simply link athletic success to national wealth.","zh":"文章並不簡單地把運動成功與國家財富連繫起來。"},{"en":"Athletic success means strong achievement in sport, such as medals, records or improved performance.","zh":"「athletic success」指運動中的強大成就，例如獎牌、紀錄或表現提升。"},{"en":"A school may celebrate athletic success when its team wins a regional competition.","zh":"當學校隊伍贏得區域比賽，學校可能慶祝運動成功。"},{"en":"Athletic success can depend on training, science, teamwork, funding and personal effort.","zh":"運動成功可以取決於訓練、科學、團隊合作、資金和個人努力。"},{"en":"The phrase describes sporting achievement, not academic success.","zh":"這個短語描述體育成就，而不是學業成功。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":17},{"front":"have the support of","meaning":"得到……支持","examples":[{"en":"Mexican athletes have the support of their government.","zh":"墨西哥運動員得到政府支持。"},{"en":"To have the support of someone means to receive help, approval or resources from them.","zh":"「have the support of」某人，意思是得到他們的幫助、認可或資源。"},{"en":"A student may improve faster when they have the support of family and teachers.","zh":"當學生得到家人和老師支持，他們可能進步更快。"},{"en":"If athletes have government support, they may gain better facilities and scientific services.","zh":"如果運動員得到政府支持，他們可能獲得更好設施和科學服務。"},{"en":"The phrase shows that success is helped by backing from others.","zh":"這個短語顯示成功受到他人支持幫助。"}],"source":"118 -  EFFORT AND SCIENCE TO WIN.pdf","sourcePage":17}],"ielts/reading/passage-2/Practice 119":[{"front":"believe our own eyes","meaning":"相信自己的眼睛","examples":[{"en":"The passage asks whether we can believe our own eyes.","zh":"文章問我們是否可以相信自己的眼睛。"},{"en":"To believe our own eyes means to trust what we see without doubting it.","zh":"“Believe our own eyes” 指毫不懷疑地相信自己所看見的東西。"},{"en":"A child may believe his own eyes when he sees a coin disappear in a magic trick.","zh":"孩子看見魔術中硬幣消失時，可能會相信自己的眼睛。"},{"en":"Optical illusions show that we cannot always believe our own eyes.","zh":"視覺錯覺顯示我們不能總是相信自己的眼睛。"},{"en":"The phrase is often used when what we see seems surprising or unbelievable.","zh":"當我們看見的東西令人驚訝或難以置信時，常使用這個短語。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":1},{"front":"an optical illusion","meaning":"視覺錯覺","examples":[{"en":"An optical illusion can make people misinterpret what they see.","zh":"視覺錯覺可以令人誤解自己所看見的東西。"},{"en":"An optical illusion is a visual trick that makes something appear different from reality.","zh":"視覺錯覺是一種視覺上的錯覺，使某物看起來與現實不同。"},{"en":"A drawing may create an optical illusion if two equal lines look unequal.","zh":"如果兩條相等的線看起來不相等，圖畫便可能造成視覺錯覺。"},{"en":"Optical illusions happen because the eyes and brain do not always judge images accurately.","zh":"視覺錯覺出現，是因為眼睛和大腦不一定準確判斷影像。"},{"en":"The phrase is used for images or scenes that mislead vision.","zh":"這個短語用於描述誤導視覺的影像或場景。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":1},{"front":"visually perceived image","meaning":"視覺上感知到的影像","examples":[{"en":"An optical illusion is a visually perceived image that may be deceptive.","zh":"視覺錯覺是一種可能具欺騙性的視覺上感知到的影像。"},{"en":"A visually perceived image is an image as it appears to the eyes and brain.","zh":"視覺上感知到的影像是眼睛和大腦所看見的影像。"},{"en":"A shadow on the wall can become a visually perceived image that looks like a person.","zh":"牆上的影子可以成為一個看似人形的視覺上感知到的影像。"},{"en":"If the brain interprets a visually perceived image wrongly, people may misjudge its shape or size.","zh":"如果大腦錯誤解讀視覺上感知到的影像，人們可能誤判其形狀或大小。"},{"en":"The phrase focuses on what is seen, not necessarily what is physically real.","zh":"這個短語強調所看見的東西，不一定是物理上真實的東西。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":1},{"front":"deceptive or misleading","meaning":"具欺騙性或誤導性的","examples":[{"en":"An optical illusion is deceptive or misleading because the brain processes visual information incorrectly.","zh":"視覺錯覺具欺騙性或誤導性，因為大腦錯誤處理視覺資料。"},{"en":"Deceptive or misleading means likely to make people believe something false.","zh":"“Deceptive or misleading” 指可能令人相信錯誤事情。"},{"en":"A photo taken from a strange angle can be deceptive or misleading.","zh":"從奇怪角度拍攝的照片可能具欺騙性或誤導性。"},{"en":"If a chart hides important numbers, it may be deceptive or misleading.","zh":"如果圖表隱藏重要數字，它可能具欺騙性或誤導性。"},{"en":"The phrase warns that appearance may not match truth.","zh":"這個短語提醒我們，外觀未必符合真相。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":1},{"front":"information transmitted from…to…","meaning":"從……傳送到……的資料","examples":[{"en":"Information transmitted from the eye to the brain may be processed inaccurately.","zh":"從眼睛傳送到大腦的資料可能被不準確地處理。"},{"en":"Information transmitted from one place to another is data sent between two points.","zh":"從一處傳送到另一處的資料，是在兩點之間傳遞的數據。"},{"en":"A message transmitted from a phone to a computer may fail if the signal is weak.","zh":"如果訊號弱，從手機傳送到電腦的信息可能失敗。"},{"en":"If visual information is transmitted incorrectly, the brain may form a wrong impression.","zh":"如果視覺資料被錯誤傳送，大腦可能形成錯誤印象。"},{"en":"The phrase is useful when describing how signals move through a system.","zh":"這個短語適合描述訊號如何在系統中移動。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":1},{"front":"from the eye to the brain","meaning":"從眼睛到大腦","examples":[{"en":"Visual information is transmitted from the eye to the brain.","zh":"視覺資料從眼睛傳送到大腦。"},{"en":"From the eye to the brain describes the path visual signals take after light enters the eye.","zh":"“From the eye to the brain” 描述光進入眼睛後視覺訊號所走的路徑。"},{"en":"When we read, information travels from the eye to the brain almost instantly.","zh":"我們閱讀時，資料幾乎立即從眼睛傳到大腦。"},{"en":"If the signal from the eye to the brain is interpreted wrongly, an illusion may occur.","zh":"如果從眼睛到大腦的訊號被錯誤解讀，就可能出現錯覺。"},{"en":"The phrase explains the biological route of seeing.","zh":"這個短語解釋觀看的生物路徑。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":1},{"front":"processed in such a way that","meaning":"以某種方式處理，以致……","examples":[{"en":"The image is processed in such a way that the final judgement is misleading.","zh":"影像以某種方式處理，以致最終判斷具誤導性。"},{"en":"Processed in such a way that means handled in a particular manner, causing a certain result.","zh":"“Processed in such a way that” 指以某種特定方式處理，從而造成某結果。"},{"en":"The data was processed in such a way that small differences looked much larger.","zh":"數據以某種方式處理，以致細小差異看起來大得多。"},{"en":"If an image is processed in such a way that depth appears wrong, people may misread it.","zh":"如果影像以某種方式處理，以致深度看起來錯誤，人們可能誤讀它。"},{"en":"The phrase links a method of processing with its outcome.","zh":"這個短語把處理方法與結果連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":1},{"front":"resulting assumption","meaning":"由此產生的假設","examples":[{"en":"The resulting assumption may not represent physical reality.","zh":"由此產生的假設可能並不代表物理現實。"},{"en":"A resulting assumption is the belief formed after seeing, hearing, or processing information.","zh":"由此產生的假設，是人在看見、聽見或處理資料後形成的信念。"},{"en":"If a student sees a closed door, the resulting assumption may be that the room is empty.","zh":"如果學生看見門關着，由此產生的假設可能是房間沒有人。"},{"en":"In an illusion, the resulting assumption may be wrong because the image is misleading.","zh":"在錯覺中，由此產生的假設可能錯誤，因為影像具誤導性。"},{"en":"The phrase shows what conclusion people reach from earlier information.","zh":"這個短語顯示人們從先前資料得出甚麼結論。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":1},{"front":"deduction","meaning":"推論","examples":[{"en":"A deduction based on visual information may be wrong.","zh":"基於視覺資料的推論可能是錯的。"},{"en":"A deduction is a conclusion reached by using evidence or reasoning.","zh":"推論是透過證據或推理得出的結論。"},{"en":"If the floor is wet, a student may make the deduction that someone spilled water.","zh":"如果地板濕了，學生可能作出有人倒瀉水的推論。"},{"en":"A deduction can be wrong if the evidence is incomplete or misleading.","zh":"如果證據不完整或具誤導性，推論可能錯誤。"},{"en":"The word is useful when talking about reasoning from clues.","zh":"這個詞適合用於談論從線索作出的推理。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":1},{"front":"does not represent","meaning":"並不代表","examples":[{"en":"The resulting deduction does not represent physical reality.","zh":"由此產生的推論並不代表物理現實。"},{"en":"Does not represent means does not show, match, or stand for something accurately.","zh":"“Does not represent” 指不能準確顯示、符合或代表某事。"},{"en":"One bad test result does not represent a student’s full ability.","zh":"一次差的測驗成績並不代表學生的全部能力。"},{"en":"If an image is distorted, what it seems to show may not represent the real object.","zh":"如果影像被扭曲，它看似顯示的東西可能並不代表真實物件。"},{"en":"The phrase warns that appearance and reality may differ.","zh":"這個短語提醒我們，外觀和現實可能不同。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":1},{"front":"physical reality","meaning":"物理現實","examples":[{"en":"An optical illusion may not match physical reality.","zh":"視覺錯覺可能不符合物理現實。"},{"en":"Physical reality is what actually exists in the material world, not just what we think we see.","zh":"物理現實是物質世界中實際存在的東西，而不只是我們以為看見的東西。"},{"en":"A mirror can make a room look larger, but physical reality has not changed.","zh":"鏡子可以令房間看起來更大，但物理現實沒有改變。"},{"en":"If two lines look unequal but are measured as equal, physical reality differs from perception.","zh":"如果兩條線看起來不相等但量度後相等，物理現實就不同於感知。"},{"en":"The phrase contrasts real measurable facts with mental impressions.","zh":"這個短語把可量度的真實事實與心理印象作對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":1},{"front":"our perception of","meaning":"我們對……的感知","examples":[{"en":"Our perception of what we see can be influenced by external factors.","zh":"我們對所看見事物的感知可能受外在因素影響。"},{"en":"Our perception of something is the way we notice, interpret, or understand it.","zh":"我們對某事的感知，是我們注意、解讀或理解它的方式。"},{"en":"Our perception of a teacher may change after we learn how much work she does outside class.","zh":"當我們知道老師課外做了多少工作後，對她的感知可能改變。"},{"en":"Lighting, colour, and background can change our perception of an image.","zh":"光線、顏色和背景可以改變我們對影像的感知。"},{"en":"The phrase focuses on personal interpretation, not only the object itself.","zh":"這個短語強調個人解讀，而不只是物件本身。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":2},{"front":"what we see","meaning":"我們所看見的東西","examples":[{"en":"What we see is not always the same as physical reality.","zh":"我們所看見的東西不一定與物理現實相同。"},{"en":"What we see means the visual information that appears to our eyes and mind.","zh":"“What we see” 指出現在我們眼睛和心智中的視覺資料。"},{"en":"In a dark room, what we see may be unclear or incomplete.","zh":"在黑暗房間中，我們所看見的東西可能不清楚或不完整。"},{"en":"If what we see is affected by an illusion, our judgement may be wrong.","zh":"如果我們所看見的東西受錯覺影響，我們的判斷可能錯誤。"},{"en":"The phrase reminds us that sight is interpreted, not simply recorded.","zh":"這個短語提醒我們，視覺是被解讀的，而不是單純被記錄的。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":2},{"front":"be influenced by","meaning":"受……影響","examples":[{"en":"Perception can be influenced by several external factors.","zh":"感知可以受幾個外在因素影響。"},{"en":"To be influenced by something means to be affected or changed by it.","zh":"“Be influenced by” 某事指被它影響或改變。"},{"en":"A student’s mood can be influenced by sleep, hunger, and stress.","zh":"學生的心情可以受睡眠、飢餓和壓力影響。"},{"en":"If perception is influenced by background lines, people may misjudge size.","zh":"如果感知受背景線條影響，人們可能誤判大小。"},{"en":"The phrase shows that something is shaped by another factor.","zh":"這個短語顯示某事由另一因素塑造。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":2},{"front":"external factors","meaning":"外在因素","examples":[{"en":"External factors can affect how we perceive an image.","zh":"外在因素可以影響我們如何感知影像。"},{"en":"External factors are outside conditions or influences that change a result.","zh":"外在因素是會改變結果的外部條件或影響。"},{"en":"Noise, lighting, and time pressure are external factors that can affect exam performance.","zh":"噪音、光線和時間壓力都是可以影響考試表現的外在因素。"},{"en":"In vision, external factors such as brightness and background may distort judgement.","zh":"在視覺中，亮度和背景等外在因素可能扭曲判斷。"},{"en":"The phrase contrasts outside influences with internal ability.","zh":"這個短語把外部影響與內在能力作對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":2},{"front":"fall into two main categories","meaning":"分為兩大類","examples":[{"en":"Illusions fall into two main categories.","zh":"錯覺分為兩大類。"},{"en":"To fall into two main categories means to be divided into two large groups.","zh":"“Fall into two main categories” 指被分成兩個主要群組。"},{"en":"School problems may fall into two main categories: academic and social.","zh":"學校問題可能分為兩大類：學業和社交。"},{"en":"Dividing illusions into categories helps students understand their causes more clearly.","zh":"把錯覺分成類別，幫助學生更清楚理解其原因。"},{"en":"The phrase is used when organising information into broad types.","zh":"這個短語用於把資料組織成廣泛類型。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":2},{"front":"physiological illusions","meaning":"生理錯覺","examples":[{"en":"Physiological illusions result from excessive stimulation of the eyes and brain.","zh":"生理錯覺由眼睛和大腦的過度刺激引起。"},{"en":"Physiological illusions are illusions caused by how the body’s visual system reacts.","zh":"生理錯覺是由身體視覺系統反應造成的錯覺。"},{"en":"Looking at a bright light may create physiological illusions when the eyes are overstimulated.","zh":"觀看強光可能在眼睛被過度刺激時造成生理錯覺。"},{"en":"These illusions may fade after the eyes and brain recover from stimulation.","zh":"這些錯覺可能在眼睛和大腦從刺激中恢復後消退。"},{"en":"The phrase focuses on physical processes in vision.","zh":"這個短語強調視覺中的身體過程。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":2},{"front":"cognitive illusions","meaning":"認知錯覺","examples":[{"en":"Cognitive illusions arise from assumptions based on knowledge and experience.","zh":"認知錯覺源於基於知識和經驗的假設。"},{"en":"Cognitive illusions are illusions caused by how the mind interprets information.","zh":"認知錯覺是由心智如何解讀資料造成的錯覺。"},{"en":"A person may see depth in a flat drawing because of a cognitive illusion.","zh":"一個人可能因認知錯覺而在平面圖中看見深度。"},{"en":"These illusions happen when past experience leads the brain to make a wrong assumption.","zh":"這些錯覺出現，是因為過去經驗令大腦作出錯誤假設。"},{"en":"The phrase focuses on thinking and interpretation rather than eye fatigue.","zh":"這個短語強調思考和解讀，而不是眼睛疲勞。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":2},{"front":"be divided into","meaning":"可分為","examples":[{"en":"Cognitive illusions can be divided into four subtypes.","zh":"認知錯覺可分為四個子類型。"},{"en":"To be divided into groups means to be separated into smaller categories.","zh":"“Be divided into” 多個群組指被分成較小類別。"},{"en":"A textbook may be divided into chapters so students can study step by step.","zh":"教科書可以分為多章，讓學生逐步學習。"},{"en":"When a topic is divided into parts, it becomes easier to compare and remember.","zh":"當題目被分成多個部分，就更容易比較和記住。"},{"en":"The phrase is useful for classification.","zh":"這個短語適合用於分類。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":2},{"front":"four subtypes","meaning":"四個子類型","examples":[{"en":"Cognitive illusions can be divided into four subtypes.","zh":"認知錯覺可分為四個子類型。"},{"en":"Four subtypes means four smaller categories within a larger group.","zh":"四個子類型指一個較大群組內的四個較小類別。"},{"en":"A teacher may divide writing mistakes into four subtypes: grammar, vocabulary, organisation, and spelling.","zh":"老師可能把寫作錯誤分成四個子類型：文法、詞彙、組織和拼字。"},{"en":"If students know the four subtypes of cognitive illusion, they can classify examples more easily.","zh":"如果學生知道認知錯覺的四個子類型，就能更容易分類例子。"},{"en":"The phrase helps make a broad topic more manageable.","zh":"這個短語幫助把廣泛題目變得較易處理。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":2},{"front":"result from","meaning":"由……引起","examples":[{"en":"Physiological illusions result from excessive stimulation.","zh":"生理錯覺由過度刺激引起。"},{"en":"To result from something means to be caused by it.","zh":"“Result from” 某事指由它造成。"},{"en":"Headaches may result from too little sleep or too much screen time.","zh":"頭痛可能由睡眠不足或螢幕時間太長引起。"},{"en":"If an illusion results from bright light, resting the eyes may help.","zh":"如果錯覺由強光引起，讓眼睛休息可能有幫助。"},{"en":"The phrase connects a cause with an effect.","zh":"這個短語把原因與結果連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":2},{"front":"excessive stimulation","meaning":"過度刺激","examples":[{"en":"Excessive stimulation of the eyes and brain can create confusion.","zh":"眼睛和大腦的過度刺激可以造成混亂。"},{"en":"Excessive stimulation means too much input or activity for the body or mind to handle comfortably.","zh":"過度刺激指身體或心智難以舒適處理的過多輸入或活動。"},{"en":"Loud music and flashing lights may cause excessive stimulation for young children.","zh":"大聲音樂和閃光可能對年幼孩子造成過度刺激。"},{"en":"When excessive stimulation affects the eyes, people may see temporary visual effects.","zh":"當過度刺激影響眼睛，人們可能看見暫時視覺效果。"},{"en":"The phrase suggests overload rather than ordinary experience.","zh":"這個短語暗示過度負荷，而不是普通經驗。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":2},{"front":"the eyes and brain","meaning":"眼睛和大腦","examples":[{"en":"Physiological illusions involve the eyes and brain.","zh":"生理錯覺涉及眼睛和大腦。"},{"en":"The eyes and brain work together to receive and interpret visual information.","zh":"眼睛和大腦共同接收和解讀視覺資料。"},{"en":"When reading, the eyes and brain cooperate to turn marks on a page into meaning.","zh":"閱讀時，眼睛和大腦合作，把頁面上的符號變成意思。"},{"en":"If the eyes and brain receive too much stimulation, perception may become confused.","zh":"如果眼睛和大腦接收太多刺激，感知可能變得混亂。"},{"en":"The phrase names the two key parts of human vision.","zh":"這個短語指出人類視覺的兩個關鍵部分。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":3},{"front":"a temporary state of","meaning":"暫時的……狀態","examples":[{"en":"Excessive stimulation creates a temporary state of confusion.","zh":"過度刺激造成暫時的混亂狀態。"},{"en":"A temporary state of something is a condition that lasts only for a short time.","zh":"“A temporary state of” 某狀態指只持續短時間的情況。"},{"en":"After spinning quickly, a child may enter a temporary state of dizziness.","zh":"快速旋轉後，孩子可能進入暫時的頭暈狀態。"},{"en":"If bright light causes a temporary state of visual confusion, vision may return to normal soon.","zh":"如果強光造成暫時的視覺混亂狀態，視覺可能很快恢復正常。"},{"en":"The phrase stresses that the condition is not permanent.","zh":"這個短語強調該情況不是永久的。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":3},{"front":"confusion and mixed messages","meaning":"混亂和混雜訊息","examples":[{"en":"The brain may experience confusion and mixed messages.","zh":"大腦可能經歷混亂和混雜訊息。"},{"en":"Confusion and mixed messages mean unclear or conflicting signals that make judgement difficult.","zh":"混亂和混雜訊息指不清楚或互相衝突的訊號，使判斷變得困難。"},{"en":"A student may feel confusion and mixed messages when two teachers give opposite instructions.","zh":"當兩位老師給出相反指示，學生可能感到混亂和收到混雜訊息。"},{"en":"If the eyes send competing signals, the brain may struggle to form a clear image.","zh":"如果眼睛傳送互相競爭的訊號，大腦可能難以形成清晰影像。"},{"en":"The phrase describes uncertainty caused by inconsistent information.","zh":"這個短語描述由不一致資料造成的不確定。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":3},{"front":"after exposure to","meaning":"在接觸……之後","examples":[{"en":"After exposure to vivid light, the eyes may need time to adapt.","zh":"在接觸強烈光線之後，眼睛可能需要時間適應。"},{"en":"After exposure to something means after coming into contact with it.","zh":"“After exposure to” 某物指接觸它之後。"},{"en":"After exposure to cold weather, a person may need warm clothes and rest.","zh":"在接觸寒冷天氣之後，人可能需要保暖衣物和休息。"},{"en":"After exposure to bright light, colours may appear strange for a short time.","zh":"在接觸強光之後，顏色可能短時間內顯得奇怪。"},{"en":"The phrase connects contact with a later effect.","zh":"這個短語把接觸與後續效果連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":3},{"front":"extremely vivid light","meaning":"極強烈的光","examples":[{"en":"Extremely vivid light can affect visual perception.","zh":"極強烈的光可以影響視覺感知。"},{"en":"Extremely vivid light is very bright or intense light that strongly affects the eyes.","zh":"極強烈的光是非常明亮或強烈、會強烈影響眼睛的光。"},{"en":"A camera flash can feel like extremely vivid light in a dark room.","zh":"在黑暗房間中，相機閃光燈可能感覺像極強烈的光。"},{"en":"If someone looks at extremely vivid light, they may briefly see spots afterwards.","zh":"如果有人看着極強烈的光，之後可能短暫看見光點。"},{"en":"The phrase describes light strong enough to influence vision.","zh":"這個短語描述強到足以影響視覺的光。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":3},{"front":"need time to adapt","meaning":"需要時間適應","examples":[{"en":"The eyes may need time to adapt after bright light exposure.","zh":"眼睛在接觸強光後可能需要時間適應。"},{"en":"Need time to adapt means require a short period to adjust to a new condition.","zh":"“Need time to adapt” 指需要一段短時間來調整至新情況。"},{"en":"Students may need time to adapt when they move to a new school.","zh":"學生轉到新學校時可能需要時間適應。"},{"en":"After entering a dark cinema, your eyes need time to adapt before you can see clearly.","zh":"進入黑暗戲院後，眼睛需要時間適應，才可以看清楚。"},{"en":"The phrase is useful when change cannot happen instantly.","zh":"當改變不能即時發生時，這個短語很有用。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":3},{"front":"briefly see","meaning":"短暫看見","examples":[{"en":"People may briefly see things that are not normally present.","zh":"人們可能短暫看見通常不存在的東西。"},{"en":"To briefly see something means to see it for a very short time.","zh":"“Briefly see” 某物指只看見它很短時間。"},{"en":"After a camera flash, you may briefly see a bright spot.","zh":"相機閃光後，你可能短暫看見一個亮點。"},{"en":"If the brain is overloaded, people may briefly see colours or shapes that disappear quickly.","zh":"如果大腦過度負荷，人們可能短暫看見很快消失的顏色或形狀。"},{"en":"The phrase stresses short duration.","zh":"這個短語強調時間短。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":3},{"front":"not normally present","meaning":"通常不存在的","examples":[{"en":"Some visual effects are not normally present.","zh":"一些視覺效果通常不存在。"},{"en":"Not normally present means not usually there in ordinary conditions.","zh":"“Not normally present” 指在普通情況下通常不在那裡。"},{"en":"A shadow may look like an object that is not normally present in the room.","zh":"影子可能看起來像房間中通常不存在的物件。"},{"en":"If someone sees colours that are not normally present, the cause may be an after-effect.","zh":"如果有人看見通常不存在的顏色，原因可能是後效。"},{"en":"The phrase separates unusual appearances from ordinary reality.","zh":"這個短語把不尋常外觀與普通現實分開。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":3},{"front":"in the same way","meaning":"同樣地","examples":[{"en":"In the same way, a perceptual after-effect may occur after staring at a colour.","zh":"同樣地，在凝視某種顏色後，知覺後效可能出現。"},{"en":"In the same way means by a similar process or for a similar reason.","zh":"“In the same way” 指透過相似過程或出於相似原因。"},{"en":"A student learns spelling through practice; in the same way, pronunciation improves through repeated speaking.","zh":"學生透過練習學拼字；同樣地，發音透過反覆說話改善。"},{"en":"If bright light affects vision, staring at one colour can affect later perception in the same way.","zh":"如果強光影響視覺，凝視一種顏色也可以同樣地影響之後的感知。"},{"en":"The phrase connects two similar examples.","zh":"這個短語連接兩個相似例子。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":3},{"front":"contingent perceptual after-effect","meaning":"條件性知覺後效","examples":[{"en":"A contingent perceptual after-effect may occur after someone stares at a particular colour.","zh":"在某人凝視某種特定顏色後，條件性知覺後效可能出現。"},{"en":"A contingent perceptual after-effect is a temporary change in perception caused by previous exposure.","zh":"條件性知覺後效是由先前接觸造成的暫時感知變化。"},{"en":"After staring at red, a person may see later colours differently because of this effect.","zh":"凝視紅色後，人可能因這種效果而以不同方式看見之後的顏色。"},{"en":"Such an effect occurs when the visual system has been overloaded or adjusted by a stimulus.","zh":"當視覺系統被刺激過度負荷或調整時，這種效果會出現。"},{"en":"The phrase describes a specialised kind of visual after-effect.","zh":"這個短語描述一種專門的視覺後效。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":3},{"front":"may occur after","meaning":"可能在……之後出現","examples":[{"en":"A visual after-effect may occur after prolonged exposure to one colour.","zh":"視覺後效可能在長時間接觸一種顏色之後出現。"},{"en":"May occur after means may happen following a particular event or condition.","zh":"“May occur after” 指可能在某事件或情況之後發生。"},{"en":"A headache may occur after staring at a screen for too long.","zh":"長時間盯着螢幕後，頭痛可能出現。"},{"en":"If someone focuses on one colour for a long time, a colour after-effect may occur after that.","zh":"如果某人長時間集中於一種顏色，顏色後效可能在之後出現。"},{"en":"The phrase connects a possible result with an earlier cause.","zh":"這個短語把可能結果與先前原因連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":3},{"front":"stares at","meaning":"凝視","examples":[{"en":"A person may experience an after-effect after staring at a particular colour.","zh":"一個人在凝視某種特定顏色後可能經歷後效。"},{"en":"To stare at something means to look at it steadily for a long time.","zh":"“Stare at” 某物指長時間穩定地看着它。"},{"en":"A child may stare at a moving toy because it seems fascinating.","zh":"孩子可能因為覺得會動的玩具很吸引而凝視它。"},{"en":"If you stare at a bright screen for too long, your eyes may feel tired.","zh":"如果你凝視明亮螢幕太久，眼睛可能感到疲倦。"},{"en":"The phrase suggests focused looking, not a quick glance.","zh":"這個短語暗示集中觀看，而不是快速一瞥。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":4},{"front":"a particular colour","meaning":"某種特定顏色","examples":[{"en":"A particular colour can affect how later colours are perceived.","zh":"某種特定顏色可以影響之後顏色被感知的方式。"},{"en":"A particular colour means one specific colour, not any colour in general.","zh":"“A particular colour” 指某一種特定顏色，而不是泛指任何顏色。"},{"en":"A designer may choose a particular colour because it feels calm or professional.","zh":"設計師可能選擇某種特定顏色，因為它感覺平靜或專業。"},{"en":"If someone stares at a particular colour, later colours may briefly look different.","zh":"如果某人凝視某種特定顏色，之後的顏色可能短暫看起來不同。"},{"en":"The phrase narrows attention to one exact colour.","zh":"這個短語把注意力收窄到一種確切顏色。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":4},{"front":"receptors in the brain","meaning":"大腦中的受體","examples":[{"en":"Receptors in the brain may process later colours inaccurately.","zh":"大腦中的受體可能不準確地處理之後的顏色。"},{"en":"Receptors in the brain are specialised structures involved in receiving or responding to signals.","zh":"大腦中的受體是參與接收或回應訊號的專門結構。"},{"en":"Scientists study receptors in the brain to understand vision, mood, and memory.","zh":"科學家研究大腦中的受體，以理解視覺、情緒和記憶。"},{"en":"If receptors are overloaded, later signals may be interpreted incorrectly for a short time.","zh":"如果受體過度負荷，之後的訊號可能短時間內被錯誤解讀。"},{"en":"The phrase connects perception with biological signal processing.","zh":"這個短語把感知與生物訊號處理連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":4},{"front":"subsequent colours","meaning":"隨後出現的顏色","examples":[{"en":"The brain may process subsequent colours inaccurately.","zh":"大腦可能不準確地處理隨後出現的顏色。"},{"en":"Subsequent colours are colours seen after an earlier visual experience.","zh":"隨後出現的顏色，是在較早視覺經驗後看見的顏色。"},{"en":"After staring at a red sign, subsequent colours may appear slightly altered.","zh":"凝視紅色標誌後，隨後出現的顏色可能略有改變。"},{"en":"If the brain is still adapting, subsequent colours may not be judged correctly.","zh":"如果大腦仍在適應，隨後出現的顏色可能不能被正確判斷。"},{"en":"The phrase refers to colours that come later in time.","zh":"這個短語指時間上較後出現的顏色。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":4},{"front":"process…inaccurately","meaning":"不準確地處理……","examples":[{"en":"Receptors may process subsequent colours inaccurately.","zh":"受體可能不準確地處理隨後出現的顏色。"},{"en":"To process something inaccurately means to handle or interpret it wrongly.","zh":"“Process something inaccurately” 指錯誤地處理或解讀某事。"},{"en":"A scanner may process a document inaccurately if the page is tilted.","zh":"如果頁面傾斜，掃描器可能不準確地處理文件。"},{"en":"If the brain processes colour inaccurately, a person may see a colour that is not really there.","zh":"如果大腦不準確地處理顏色，人可能看見實際不存在的顏色。"},{"en":"The phrase describes incorrect interpretation of information.","zh":"這個短語描述對資料的錯誤解讀。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":4},{"front":"until the overload has passed","meaning":"直到過度負荷消退","examples":[{"en":"The effect may continue until the overload has passed.","zh":"這種效果可能持續，直到過度負荷消退。"},{"en":"Until the overload has passed means until the excessive stimulation has faded or ended.","zh":"“Until the overload has passed” 指直到過度刺激減弱或結束。"},{"en":"After a loud concert, your ears may ring until the overload has passed.","zh":"大聲演唱會後，你的耳朵可能鳴響，直到過度負荷消退。"},{"en":"If visual receptors are overloaded, perception may stay strange until the overload has passed.","zh":"如果視覺受體過度負荷，感知可能保持奇怪，直到過度負荷消退。"},{"en":"The phrase marks the point when normal processing returns.","zh":"這個短語標示正常處理恢復的時間點。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":4},{"front":"on the other hand","meaning":"另一方面","examples":[{"en":"Cognitive illusions, on the other hand, arise from assumptions.","zh":"另一方面，認知錯覺源於假設。"},{"en":"On the other hand introduces a contrasting point or different side of an argument.","zh":"“On the other hand” 用來引出對比重點或論點的另一面。"},{"en":"Online lessons are convenient; on the other hand, students may feel lonely.","zh":"網課很方便；另一方面，學生可能感到孤獨。"},{"en":"Physiological illusions involve overstimulation; on the other hand, cognitive illusions involve interpretation.","zh":"生理錯覺涉及過度刺激；另一方面，認知錯覺涉及解讀。"},{"en":"The phrase helps compare two different ideas.","zh":"這個短語幫助比較兩個不同想法。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":4},{"front":"are said to arise from","meaning":"據說源於","examples":[{"en":"Cognitive illusions are said to arise from conscious assumptions.","zh":"認知錯覺據說源於有意識的假設。"},{"en":"Are said to arise from means people explain them as coming from a particular cause.","zh":"“Are said to arise from” 指人們解釋它們來自某個特定原因。"},{"en":"Some classroom problems are said to arise from lack of sleep and poor routines.","zh":"一些課堂問題據說源於睡眠不足和習慣差。"},{"en":"If illusions are said to arise from assumptions, the mind’s interpretation is central.","zh":"如果錯覺據說源於假設，心智的解讀就是核心。"},{"en":"The phrase reports an explanation without stating it too forcefully.","zh":"這個短語報告一種解釋，而不把語氣說得太絕對。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":4},{"front":"neurone activity","meaning":"神經元活動","examples":[{"en":"Cognitive illusions are not mainly explained by neurone activity.","zh":"認知錯覺並非主要由神經元活動解釋。"},{"en":"Neurone activity refers to the signalling and firing of nerve cells in the brain or nervous system.","zh":"神經元活動指大腦或神經系統中神經細胞的訊號傳遞和激發。"},{"en":"Scientists measure neurone activity to understand how people see, move, and remember.","zh":"科學家量度神經元活動，以理解人如何觀看、移動和記憶。"},{"en":"If an illusion is explained by neurone activity, the focus is biological processing.","zh":"如果錯覺由神經元活動解釋，焦點就是生物處理。"},{"en":"The phrase belongs to neuroscience and brain function.","zh":"這個短語屬於神經科學和腦功能。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":4},{"front":"assumptions we consciously make","meaning":"我們有意識作出的假設","examples":[{"en":"Cognitive illusions arise from assumptions we consciously make.","zh":"認知錯覺源於我們有意識作出的假設。"},{"en":"Assumptions we consciously make are beliefs or guesses we are aware of forming.","zh":"我們有意識作出的假設，是我們知道自己正在形成的信念或猜測。"},{"en":"A student may consciously assume a test will be easy because the last one was simple.","zh":"學生可能因上次測驗簡單，而有意識地假設這次測驗會容易。"},{"en":"If we consciously assume that light comes from above, we may interpret shadows in a certain way.","zh":"如果我們有意識地假設光線從上方來，便可能以某種方式解讀陰影。"},{"en":"The phrase connects deliberate thinking with perception.","zh":"這個短語把刻意思考與感知連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":4},{"front":"based on","meaning":"基於","examples":[{"en":"Our assumptions are based on knowledge and experience.","zh":"我們的假設基於知識和經驗。"},{"en":"Based on something means built from, supported by, or using that information.","zh":"“Based on” 某事指以該資料作基礎、支持或依據。"},{"en":"A teacher may give advice based on a student’s past writing.","zh":"老師可能基於學生過去的寫作給予建議。"},{"en":"If perception is based on experience, people from different backgrounds may see differently.","zh":"如果感知基於經驗，來自不同背景的人可能有不同看法。"},{"en":"The phrase explains the foundation of an idea or decision.","zh":"這個短語解釋想法或決定的基礎。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":4},{"front":"knowledge and experience","meaning":"知識和經驗","examples":[{"en":"Cognitive illusions are linked to knowledge and experience of the world.","zh":"認知錯覺與對世界的知識和經驗有關。"},{"en":"Knowledge and experience are what people know and what they have learned through life.","zh":"知識和經驗是人們知道的事情，以及透過生活學到的東西。"},{"en":"A driver’s knowledge and experience help them notice danger on the road.","zh":"司機的知識和經驗幫助他們注意道路危險。"},{"en":"If the brain uses knowledge and experience to interpret images, it may sometimes guess wrongly.","zh":"如果大腦使用知識和經驗解讀影像，它有時可能猜錯。"},{"en":"The phrase combines learned facts with lived practice.","zh":"這個短語結合學到的事實與生活實踐。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":5},{"front":"categories","meaning":"類別","examples":[{"en":"The four categories include ambiguous, distorting, paradox and fictional illusions.","zh":"這四個類別包括模稜兩可、扭曲、悖論和虛構錯覺。"},{"en":"Categories are groups used to organise things with similar features.","zh":"類別是用來整理具有相似特徵的事物的群組。"},{"en":"A library uses categories so readers can find books more easily.","zh":"圖書館使用類別，讓讀者更容易找到書。"},{"en":"If illusions are placed into categories, students can compare their causes and effects.","zh":"如果錯覺被放入不同類別，學生可以比較其原因和效果。"},{"en":"The word helps organise complex information.","zh":"這個詞幫助整理複雜資料。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":5},{"front":"ambiguous illusions","meaning":"模稜兩可錯覺","examples":[{"en":"Ambiguous illusions can be perceived in more than one way.","zh":"模稜兩可錯覺可以用多於一種方式感知。"},{"en":"Ambiguous illusions are images that allow more than one reasonable interpretation.","zh":"模稜兩可錯覺是容許多於一種合理解讀的影像。"},{"en":"A drawing may look like either a young woman or an old woman, depending on how you view it.","zh":"一幅圖可能看起來像年輕女子，也可能像老婦人，視乎你如何觀看。"},{"en":"These illusions happen because the brain can organise the same image in different ways.","zh":"這些錯覺出現，是因為大腦可以用不同方式組織同一影像。"},{"en":"The phrase focuses on uncertainty and multiple meanings in vision.","zh":"這個短語強調視覺中的不確定和多重意思。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":5},{"front":"distorting illusions","meaning":"扭曲錯覺","examples":[{"en":"Distorting illusions affect judgement of size, length or curvature.","zh":"扭曲錯覺影響對大小、長度或曲度的判斷。"},{"en":"Distorting illusions make shapes, lines, or spaces look different from their real measurements.","zh":"扭曲錯覺令形狀、線條或空間看起來不同於其真實量度。"},{"en":"A hallway may make two equal objects look unequal if background lines distort perception.","zh":"如果背景線條扭曲感知，走廊可能令兩個相等物件看起來不相等。"},{"en":"These illusions can cause people to misjudge length, angle, or curve.","zh":"這些錯覺可以令人誤判長度、角度或曲線。"},{"en":"The phrase focuses on visual mismeasurement.","zh":"這個短語強調視覺上的錯誤量度。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":5},{"front":"paradox illusions","meaning":"悖論錯覺","examples":[{"en":"Paradox illusions make people believe they are seeing something impossible.","zh":"悖論錯覺令人相信自己正在看見不可能的東西。"},{"en":"Paradox illusions show objects or scenes that appear logical locally but impossible as a whole.","zh":"悖論錯覺展示局部看似合理、但整體不可能的物件或場景。"},{"en":"A staircase may seem to keep going up while returning to the starting point.","zh":"樓梯可能看似一直向上，卻回到起點。"},{"en":"These illusions confuse rational judgement because the image seems possible and impossible at once.","zh":"這些錯覺令理性判斷混亂，因為影像似乎同時可能又不可能。"},{"en":"The phrase focuses on visual contradiction.","zh":"這個短語強調視覺矛盾。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":5},{"front":"fictional illusions","meaning":"虛構錯覺","examples":[{"en":"Fictional illusions are seen only by an individual in a particular situation.","zh":"虛構錯覺只由某人在某個特定情況下看見。"},{"en":"Fictional illusions are private visual experiences that do not have a real external object.","zh":"虛構錯覺是沒有真實外部物件的私人視覺經驗。"},{"en":"A person with a high fever may see something that no one else sees.","zh":"發高燒的人可能看見其他人看不見的東西。"},{"en":"These illusions may be linked to illness, drugs, or unusual brain conditions.","zh":"這些錯覺可能與疾病、藥物或特殊腦部狀況有關。"},{"en":"The phrase is close to hallucination in this passage.","zh":"在本文中，這個短語接近「幻覺」。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":5},{"front":"somewhat misleading","meaning":"有點誤導","examples":[{"en":"Including fictional illusions in the cognitive group is somewhat misleading.","zh":"把虛構錯覺包括在認知組別中有點誤導。"},{"en":"Somewhat misleading means partly inaccurate or likely to give the wrong impression.","zh":"“Somewhat misleading” 指部分不準確或可能給人錯誤印象。"},{"en":"A photo of a tiny room taken with a wide lens may be somewhat misleading.","zh":"用廣角鏡拍攝很小的房間可能有點誤導。"},{"en":"If a label gives only half the facts, it can be somewhat misleading.","zh":"如果標籤只提供一半事實，它可能有點誤導。"},{"en":"The phrase softens criticism but still signals a problem.","zh":"這個短語語氣較溫和，但仍表示有問題。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":5},{"front":"in the cognitive group","meaning":"在認知組別中","examples":[{"en":"Fictional illusions are sometimes included in the cognitive group.","zh":"虛構錯覺有時被包括在認知組別中。"},{"en":"In the cognitive group means placed among illusions related to thinking and interpretation.","zh":"“In the cognitive group” 指被放在與思考和解讀有關的錯覺類別中。"},{"en":"A teacher may place a question in the grammar group if it tests sentence structure.","zh":"如果題目測試句子結構，老師可能把它放在文法組別中。"},{"en":"If a fictional illusion is placed in the cognitive group, readers may wrongly think it works like other cognitive illusions.","zh":"如果虛構錯覺被放在認知組別中，讀者可能錯誤地以為它像其他認知錯覺一樣運作。"},{"en":"The phrase identifies a classification location.","zh":"這個短語指出分類位置。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":5},{"front":"in a particular situation","meaning":"在某個特定情況下","examples":[{"en":"A fictional illusion is seen only by an individual in a particular situation.","zh":"虛構錯覺只由某人在某個特定情況下看見。"},{"en":"In a particular situation means under one specific set of conditions.","zh":"“In a particular situation” 指在一組特定條件下。"},{"en":"A student may speak confidently in a small group but not in a particular situation like a public speech.","zh":"學生可能在小組中自信說話，但在公開演講這種特定情況下不行。"},{"en":"If an illusion appears only in a particular situation, it may not be shared by others.","zh":"如果錯覺只在某個特定情況下出現，它可能不是其他人共同看見的。"},{"en":"The phrase narrows the context.","zh":"這個短語收窄語境。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":5},{"front":"no tangible form","meaning":"沒有實體形態","examples":[{"en":"A fictional illusion has no tangible form.","zh":"虛構錯覺沒有實體形態。"},{"en":"No tangible form means no physical shape or object that can be touched or measured.","zh":"“No tangible form” 指沒有可觸摸或量度的物理形狀或物件。"},{"en":"A dream may feel real, but it has no tangible form in the room.","zh":"夢可能感覺真實，但它在房間中沒有實體形態。"},{"en":"If an image has no tangible form, other people cannot point to it or photograph it.","zh":"如果影像沒有實體形態，其他人就不能指着它或拍下它。"},{"en":"The phrase contrasts mental experience with physical object.","zh":"這個短語把心理經驗與物理物件作對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":5},{"front":"in fact","meaning":"事實上","examples":[{"en":"A fictional illusion is, in fact, a hallucination.","zh":"虛構錯覺事實上是幻覺。"},{"en":"In fact introduces the truth, often correcting or strengthening what was just said.","zh":"“In fact” 引出真相，常用來糾正或加強剛才所說的內容。"},{"en":"The shop looked closed; in fact, the entrance was around the corner.","zh":"商店看似關門；事實上，入口在轉角處。"},{"en":"A fictional illusion may sound like an illusion, but in fact it is closer to a hallucination.","zh":"虛構錯覺聽起來像錯覺，但事實上更接近幻覺。"},{"en":"The phrase helps clarify the real situation.","zh":"這個短語幫助澄清真實情況。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":5},{"front":"a hallucination","meaning":"幻覺","examples":[{"en":"A fictional illusion is a hallucination caused by drugs or illness.","zh":"虛構錯覺是由藥物或疾病引起的幻覺。"},{"en":"A hallucination is seeing, hearing, or sensing something that is not actually present.","zh":"幻覺是看見、聽見或感覺到實際不存在的東西。"},{"en":"A very sick person may experience a hallucination during a high fever.","zh":"發高燒的人可能在病得很重時經歷幻覺。"},{"en":"Hallucinations can be serious because they may signal a medical or mental health problem.","zh":"幻覺可能很嚴重，因為它可能顯示醫療或心理健康問題。"},{"en":"The word describes a private perception without a real external object.","zh":"這個詞描述沒有真實外部物件的私人感知。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":6},{"front":"caused by","meaning":"由……引起","examples":[{"en":"A hallucination may be caused by drug use or a brain condition.","zh":"幻覺可能由藥物使用或腦部疾病引起。"},{"en":"Caused by means produced or brought about by something.","zh":"“Caused by” 指由某事造成或引起。"},{"en":"A traffic jam may be caused by an accident on the road.","zh":"交通擠塞可能由路上意外引起。"},{"en":"If hallucinations are caused by illness, medical help may be needed.","zh":"如果幻覺由疾病引起，可能需要醫療協助。"},{"en":"The phrase directly identifies the reason for a result.","zh":"這個短語直接指出結果的原因。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":6},{"front":"drug use","meaning":"藥物使用；吸毒","examples":[{"en":"Drug use can cause hallucinations.","zh":"藥物使用可以造成幻覺。"},{"en":"Drug use means taking substances that affect the body or mind, especially harmful or illegal ones in this context.","zh":"“Drug use” 指服用會影響身體或心智的物質，在此語境中尤其指有害或非法藥物。"},{"en":"Schools warn students that drug use can damage health and judgement.","zh":"學校提醒學生，吸毒可以損害健康和判斷力。"},{"en":"If drug use changes brain activity, a person may see or hear things that are not there.","zh":"如果藥物使用改變腦部活動，人可能看見或聽見不存在的東西。"},{"en":"The phrase should be read here as a possible medical cause of hallucination.","zh":"這個短語在此應理解為幻覺的一個可能醫學原因。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":6},{"front":"a brain condition","meaning":"腦部疾病","examples":[{"en":"A brain condition such as schizophrenia may cause hallucinations.","zh":"精神分裂症等腦部疾病可能造成幻覺。"},{"en":"A brain condition is an illness or disorder affecting how the brain works.","zh":"腦部疾病是影響大腦運作的疾病或障礙。"},{"en":"A doctor may investigate a brain condition if a patient reports unusual visions.","zh":"如果病人報告異常視覺，醫生可能調查是否有腦部疾病。"},{"en":"If a brain condition affects perception, the person may need specialist care.","zh":"如果腦部疾病影響感知，患者可能需要專科照顧。"},{"en":"The phrase is a broad medical term.","zh":"這個短語是廣泛的醫學用語。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":6},{"front":"schizophrenia","meaning":"精神分裂症","examples":[{"en":"Schizophrenia can cause hallucinations.","zh":"精神分裂症可以造成幻覺。"},{"en":"Schizophrenia is a serious mental health condition that can affect thoughts, perception, and behaviour.","zh":"精神分裂症是一種嚴重心理健康疾病，可以影響思想、感知和行為。"},{"en":"A person with schizophrenia may need medication, therapy, and long-term support.","zh":"患有精神分裂症的人可能需要藥物、治療和長期支援。"},{"en":"If schizophrenia causes hallucinations, the person may hear or see things others do not.","zh":"如果精神分裂症造成幻覺，患者可能聽見或看見其他人沒有感知到的東西。"},{"en":"The word names a specific medical condition and should be used carefully.","zh":"這個詞指特定醫學疾病，使用時應小心。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":6},{"front":"pictures or objects structured so that","meaning":"結構使其……的圖像或物件","examples":[{"en":"Ambiguous illusions are pictures or objects structured so that they can be seen in different ways.","zh":"模稜兩可錯覺是結構使其能以不同方式觀看的圖像或物件。"},{"en":"Pictures or objects structured so that something happens are designed or arranged to create that result.","zh":"“Pictures or objects structured so that” 某事發生，指圖像或物件被設計或安排來造成該結果。"},{"en":"A puzzle picture may be structured so that it shows both a face and a vase.","zh":"謎題圖可能被構造成同時顯示一張臉和一個花瓶。"},{"en":"If an object is structured so that depth is unclear, viewers may interpret it differently.","zh":"如果物件結構令深度不清楚，觀看者可能以不同方式解讀它。"},{"en":"The phrase links design with visual effect.","zh":"這個短語把設計與視覺效果連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":6},{"front":"be perceived in more than one way","meaning":"可以用多於一種方式感知","examples":[{"en":"An ambiguous illusion can be perceived in more than one way.","zh":"模稜兩可錯覺可以用多於一種方式感知。"},{"en":"To be perceived in more than one way means to be seen or understood differently.","zh":"“Be perceived in more than one way” 指可以被不同地看見或理解。"},{"en":"A simple drawing may be perceived in more than one way by different viewers.","zh":"一幅簡單圖畫可能被不同觀看者用多於一種方式感知。"},{"en":"If an image has two possible forms, the brain may switch between them.","zh":"如果影像有兩種可能形態，大腦可能在兩者之間切換。"},{"en":"The phrase is central to ambiguous illusions.","zh":"這個短語是模稜兩可錯覺的核心。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":6},{"front":"one individual","meaning":"一個人","examples":[{"en":"One individual may perceive an image differently from another.","zh":"一個人可能以不同於另一人的方式感知影像。"},{"en":"One individual means one person considered separately from others.","zh":"“One individual” 指把一個人與其他人分開來看。"},{"en":"One individual in a class may find a picture funny while others do not.","zh":"班上一個人可能覺得一幅圖有趣，而其他人不覺得。"},{"en":"If one individual sees a cube one way, another person may see it differently.","zh":"如果一個人以某種方式看見立方體，另一個人可能看法不同。"},{"en":"The phrase focuses on personal difference.","zh":"這個短語強調個人差異。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":6},{"front":"perceive an image differently","meaning":"以不同方式感知影像","examples":[{"en":"Different people may perceive an image differently.","zh":"不同的人可能以不同方式感知影像。"},{"en":"To perceive an image differently means to see or interpret the same image in another way.","zh":"“Perceive an image differently” 指以另一種方式觀看或解讀同一影像。"},{"en":"Two students may perceive an image differently if one focuses on the background and the other on the foreground.","zh":"如果一名學生集中背景，另一名集中前景，兩人可能以不同方式感知影像。"},{"en":"Ambiguous designs can make people perceive an image differently.","zh":"模稜兩可設計可以令人以不同方式感知影像。"},{"en":"The phrase highlights variation in visual interpretation.","zh":"這個短語強調視覺解讀的差異。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":6},{"front":"interpret it in more than one form","meaning":"以多於一種形式解讀","examples":[{"en":"The same person can interpret an ambiguous image in more than one form.","zh":"同一個人可以把模稜兩可影像以多於一種形式解讀。"},{"en":"To interpret it in more than one form means to understand the same thing as having different possible shapes or meanings.","zh":"“Interpret it in more than one form” 指把同一事物理解為有不同可能形狀或意思。"},{"en":"A viewer may interpret one drawing as either a duck or a rabbit.","zh":"觀看者可能把同一幅圖解讀為鴨子或兔子。"},{"en":"If the brain switches interpretation, the same image can seem to change form.","zh":"如果大腦切換解讀，同一影像可能看似改變形態。"},{"en":"The phrase describes flexible visual meaning.","zh":"這個短語描述靈活的視覺意思。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":6},{"front":"a classic example","meaning":"經典例子","examples":[{"en":"The Necker cube is a classic example of an ambiguous illusion.","zh":"內克爾立方體是模稜兩可錯覺的經典例子。"},{"en":"A classic example is a well-known case that clearly shows an idea.","zh":"經典例子是清楚展示某想法的著名案例。"},{"en":"A crowded bus is a classic example of why public transport planning matters.","zh":"擁擠巴士是公共交通規劃為何重要的經典例子。"},{"en":"If students understand a classic example, they can understand the wider concept more easily.","zh":"如果學生理解經典例子，就能更容易理解更廣泛概念。"},{"en":"The phrase points to a familiar and useful model.","zh":"這個短語指熟悉而有用的模型。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":6},{"front":"the Necker cube","meaning":"內克爾立方體","examples":[{"en":"The Necker cube is a standard line drawing.","zh":"內克爾立方體是一種標準線條圖。"},{"en":"The Necker cube is a simple drawing of a cube that can be seen in two different orientations.","zh":"內克爾立方體是一幅簡單立方體圖，可以被看成兩種不同方向。"},{"en":"A teacher may use the Necker cube to show that perception can switch.","zh":"老師可能用內克爾立方體來顯示感知可以切換。"},{"en":"Because its depth is unclear, the Necker cube can look like two different boxes.","zh":"因為其深度不清楚，內克爾立方體可以看起來像兩個不同盒子。"},{"en":"The phrase names a famous ambiguous illusion.","zh":"這個短語指一種著名的模稜兩可錯覺。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":7},{"front":"a standard line drawing","meaning":"標準線條圖","examples":[{"en":"The Necker cube is a standard line drawing interpreted as a box.","zh":"內克爾立方體是一幅被解讀為盒子的標準線條圖。"},{"en":"A standard line drawing is a simple picture made mainly from lines.","zh":"標準線條圖是主要由線條組成的簡單圖畫。"},{"en":"A map of a classroom can be a standard line drawing if it shows only walls and desks.","zh":"如果課室地圖只顯示牆壁和桌子，它可以是一幅標準線條圖。"},{"en":"If a standard line drawing lacks depth clues, viewers may interpret it differently.","zh":"如果標準線條圖缺乏深度線索，觀看者可能以不同方式解讀它。"},{"en":"The phrase describes a simple visual form rather than a detailed picture.","zh":"這個短語描述簡單視覺形式，而不是詳細圖畫。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":7},{"front":"visual system","meaning":"視覺系統","examples":[{"en":"Our visual system generally interprets the Necker cube as a three-dimensional box.","zh":"我們的視覺系統通常把內克爾立方體解讀為三維盒子。"},{"en":"The visual system is the eyes and brain processes that allow us to see and interpret images.","zh":"視覺系統是讓我們看見和解讀影像的眼睛與大腦過程。"},{"en":"The visual system helps us judge colour, distance, movement, and shape.","zh":"視覺系統幫助我們判斷顏色、距離、移動和形狀。"},{"en":"If the visual system receives unclear clues, it may choose one interpretation over another.","zh":"如果視覺系統接收不清楚的線索，它可能選擇其中一種解讀。"},{"en":"The phrase describes the whole seeing system, not just the eyes.","zh":"這個短語描述整個觀看系統，而不只是眼睛。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":7},{"front":"generally interprets…as…","meaning":"通常把……解讀為……","examples":[{"en":"The visual system generally interprets the drawing as a three-dimensional box.","zh":"視覺系統通常把該圖畫解讀為三維盒子。"},{"en":"Generally interprets something as something means usually understands it in that way.","zh":"“Generally interprets something as something” 指通常以某種方式理解某事物。"},{"en":"A teacher generally interprets silence as confusion if students avoid eye contact.","zh":"如果學生避免眼神接觸，老師通常把沉默解讀為困惑。"},{"en":"If the brain generally interprets lines as depth, a flat drawing can seem three-dimensional.","zh":"如果大腦通常把線條解讀為深度，平面圖也可以看似三維。"},{"en":"The phrase shows a usual mental reading of information.","zh":"這個短語顯示對資料的通常心理解讀。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":7},{"front":"a three-dimensional box","meaning":"三維盒子","examples":[{"en":"The Necker cube is usually seen as a three-dimensional box.","zh":"內克爾立方體通常被看成三維盒子。"},{"en":"A three-dimensional box has height, width, and depth.","zh":"三維盒子有高度、闊度和深度。"},{"en":"A shoebox is a real three-dimensional box, while a drawing of one is flat.","zh":"鞋盒是真正的三維盒子，而鞋盒圖畫是平面的。"},{"en":"If a flat drawing looks like a three-dimensional box, the brain has added depth.","zh":"如果平面圖看起來像三維盒子，大腦就加入了深度。"},{"en":"The phrase contrasts real depth with drawn depth.","zh":"這個短語把真實深度與繪畫深度作對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":7},{"front":"where the lines cross","meaning":"在線條交叉之處","examples":[{"en":"Where the lines cross, the drawing does not define depth clearly.","zh":"在線條交叉之處，該圖畫沒有清楚界定深度。"},{"en":"Where the lines cross means at the points where two or more lines meet or overlap.","zh":"“Where the lines cross” 指兩條或以上線條相遇或重疊的位置。"},{"en":"On a map, where the lines cross may show a road junction.","zh":"在地圖上，線條交叉之處可能顯示道路交界。"},{"en":"In the Necker cube, unclear crossings make the front and back uncertain.","zh":"在內克爾立方體中，不清楚的交叉令前方和後方不確定。"},{"en":"The phrase identifies a specific location in a drawing.","zh":"這個短語指出圖畫中的特定位置。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":7},{"front":"deliberately does not define","meaning":"故意不界定","examples":[{"en":"The drawing deliberately does not define which line is in front.","zh":"該圖畫故意不界定哪條線在前面。"},{"en":"Deliberately does not define means intentionally leaves something unclear.","zh":"“Deliberately does not define” 指有意地把某事留下不清楚。"},{"en":"A puzzle may deliberately not define who is speaking so readers must guess.","zh":"謎題可能故意不界定誰在說話，讓讀者必須猜測。"},{"en":"If a drawing deliberately does not define depth, the viewer’s mind must choose an interpretation.","zh":"如果圖畫故意不界定深度，觀看者的心智就必須選擇一種解讀。"},{"en":"The phrase suggests planned ambiguity.","zh":"這個短語暗示有意設計的模糊。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":7},{"front":"in front","meaning":"在前面","examples":[{"en":"The drawing does not define which line is in front.","zh":"該圖畫沒有界定哪條線在前面。"},{"en":"In front means closer to the viewer or placed before something else.","zh":"“In front” 指較接近觀看者，或位於其他東西之前。"},{"en":"A student sitting in front of the class can see the board clearly.","zh":"坐在課室前面的學生可以清楚看見白板。"},{"en":"If a line is judged to be in front, the cube appears one way.","zh":"如果某條線被判斷為在前面，立方體就會以某種方式呈現。"},{"en":"The phrase describes position and depth.","zh":"這個短語描述位置和深度。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":7},{"front":"behind","meaning":"在後面","examples":[{"en":"The drawing does not define which line is behind.","zh":"該圖畫沒有界定哪條線在後面。"},{"en":"Behind means farther back or at the rear of something.","zh":"“Behind” 指較後方或位於某物後部。"},{"en":"A bag left behind a chair may be hard to notice.","zh":"放在椅子後面的袋可能難以注意到。"},{"en":"If the brain decides one line is behind another, it creates a sense of depth.","zh":"如果大腦判斷一條線在另一條線後面，就會創造深度感。"},{"en":"The phrase contrasts with “in front”.","zh":"這個短語與 “in front” 形成對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":7},{"front":"the mind nevertheless interprets","meaning":"大腦仍然解讀","examples":[{"en":"The mind nevertheless interprets what it sees.","zh":"大腦仍然解讀它所看見的東西。"},{"en":"The mind nevertheless interprets means the brain still gives meaning even when information is incomplete.","zh":"“The mind nevertheless interprets” 指即使資料不完整，大腦仍然賦予意思。"},{"en":"Even if a sentence has missing words, the mind nevertheless interprets the message.","zh":"即使句子有缺字，大腦仍然解讀信息。"},{"en":"In an ambiguous drawing, the mind nevertheless interprets the lines as an object.","zh":"在模稜兩可圖畫中，大腦仍然把線條解讀為物件。"},{"en":"The phrase shows the brain’s active role in making sense of input.","zh":"這個短語顯示大腦在理解輸入時的主動角色。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":7},{"front":"what it sees","meaning":"它所看見的東西","examples":[{"en":"The mind tries to interpret what it sees.","zh":"大腦嘗試解讀它所看見的東西。"},{"en":"What it sees means the visual information received by the mind or visual system.","zh":"“What it sees” 指心智或視覺系統接收到的視覺資料。"},{"en":"A child may not understand what he sees if a shadow looks like a monster.","zh":"如果影子看起來像怪物，孩子可能不理解他所看見的東西。"},{"en":"If the brain receives unclear lines, it tries to organise what it sees into a familiar shape.","zh":"如果大腦接收到不清楚線條，它會嘗試把所看見的東西組織成熟悉形狀。"},{"en":"The phrase refers to visual input before or during interpretation.","zh":"這個短語指解讀之前或期間的視覺輸入。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":7},{"front":"view objects from above","meaning":"從上方觀看物件","examples":[{"en":"People generally view objects from above.","zh":"人們通常從上方觀看物件。"},{"en":"To view objects from above means to see them from a higher position looking downward.","zh":"“View objects from above” 指從較高位置向下看物件。"},{"en":"A teacher looking at desks from the front may view objects from above slightly.","zh":"老師在課室前方看桌子時，可能略微從上方觀看物件。"},{"en":"Because people often view objects from above, they may assume one face of a cube is the front.","zh":"因為人們常從上方觀看物件，可能假設立方體某一面是前方。"},{"en":"The phrase explains a habit that affects visual interpretation.","zh":"這個短語解釋影響視覺解讀的習慣。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":8},{"front":"interpret the cube’s lower-left face as","meaning":"把立方體左下方面解讀為……","examples":[{"en":"Many people interpret the cube’s lower-left face as the front.","zh":"許多人把立方體左下方面解讀為前方。"},{"en":"To interpret one face as the front means to decide that this surface is closest to the viewer.","zh":"“Interpret one face as the front” 指判斷某一面最接近觀看者。"},{"en":"In a simple box drawing, viewers may interpret the lower face as the front because of daily viewing habits.","zh":"在簡單盒子圖中，觀看者可能因日常觀看習慣把下方面解讀為前方。"},{"en":"If people interpret a different face as the front, the cube appears to flip.","zh":"如果人們把另一個面解讀為前方，立方體看起來就會翻轉。"},{"en":"The phrase describes one possible reading of the Necker cube.","zh":"這個短語描述內克爾立方體的一種可能解讀。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":8},{"front":"parallel to the floor","meaning":"與地面平行","examples":[{"en":"The base of that face appears parallel to the floor.","zh":"該面的底部看起來與地面平行。"},{"en":"Parallel to the floor means running in the same direction as the floor without meeting it.","zh":"“Parallel to the floor” 指與地面朝同一方向延伸而不相交。"},{"en":"A table top is usually parallel to the floor.","zh":"桌面通常與地面平行。"},{"en":"If a line appears parallel to the floor, the brain may treat it as a stable base.","zh":"如果線條看起來與地面平行，大腦可能把它視為穩定底部。"},{"en":"The phrase describes spatial alignment.","zh":"這個短語描述空間排列。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":8},{"front":"it is also possible to","meaning":"也可以","examples":[{"en":"It is also possible to interpret a different face as the front.","zh":"也可以把另一個面解讀為前方。"},{"en":"It is also possible to means another option can happen or be done.","zh":"“It is also possible to” 指另一個選項可以發生或可以做到。"},{"en":"It is also possible to study at night if a student works during the day.","zh":"如果學生白天工作，也可以在晚上學習。"},{"en":"In an ambiguous image, it is also possible to switch to a second interpretation.","zh":"在模稜兩可影像中，也可以切換到第二種解讀。"},{"en":"The phrase introduces an additional possibility.","zh":"這個短語引出額外可能性。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":8},{"front":"a different face","meaning":"另一個面","examples":[{"en":"A different face of the cube may be interpreted as the front.","zh":"立方體的另一個面可能被解讀為前方。"},{"en":"A different face means another surface of the same object.","zh":"“A different face” 指同一物件的另一個表面。"},{"en":"A cube has six faces, so a different face may point toward the viewer.","zh":"立方體有六個面，所以另一個面可能朝向觀看者。"},{"en":"If viewers choose a different face as the front, the whole cube appears to change direction.","zh":"如果觀看者選擇另一個面作為前方，整個立方體看起來會改變方向。"},{"en":"The phrase helps describe alternative interpretations of a 3D object.","zh":"這個短語幫助描述三維物件的不同解讀。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":8},{"front":"contributed to","meaning":"促成；有助於","examples":[{"en":"The Necker cube contributed to researchers’ understanding of vision.","zh":"內克爾立方體有助於研究人員對視覺的理解。"},{"en":"To contribute to something means to help cause or improve it.","zh":"“Contribute to” 某事指幫助造成或改善它。"},{"en":"Regular practice contributes to better pronunciation.","zh":"定期練習有助於更好發音。"},{"en":"Studying illusions contributes to knowledge about how the brain processes images.","zh":"研究錯覺有助於了解大腦如何處理影像。"},{"en":"The phrase shows a helpful role in a larger result.","zh":"這個短語顯示某事在較大結果中的幫助角色。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":8},{"front":"researchers’ understanding of","meaning":"研究人員對……的理解","examples":[{"en":"The Necker cube contributed to researchers’ understanding of the visual system.","zh":"內克爾立方體有助於研究人員對視覺系統的理解。"},{"en":"Researchers’ understanding of something means what scientists know about it through study.","zh":"研究人員對某事的理解，是科學家透過研究所知道的內容。"},{"en":"Patients’ records can improve researchers’ understanding of a disease.","zh":"病人紀錄可以改善研究人員對某疾病的理解。"},{"en":"If an illusion reveals how perception switches, it deepens researchers’ understanding of vision.","zh":"如果錯覺揭示感知如何切換，它會加深研究人員對視覺的理解。"},{"en":"The phrase connects evidence with scientific knowledge.","zh":"這個短語把證據與科學知識連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":8},{"front":"the human visual system","meaning":"人類視覺系統","examples":[{"en":"The Necker cube helped researchers understand the human visual system.","zh":"內克爾立方體幫助研究人員理解人類視覺系統。"},{"en":"The human visual system is the eye-brain system that lets people see and interpret the world.","zh":"人類視覺系統是讓人看見和解讀世界的眼腦系統。"},{"en":"The human visual system helps us recognise faces, read signs, and avoid obstacles.","zh":"人類視覺系統幫助我們辨認面孔、閱讀標誌和避開障礙物。"},{"en":"Illusions show that the human visual system can sometimes make wrong assumptions.","zh":"錯覺顯示人類視覺系統有時會作出錯誤假設。"},{"en":"The phrase refers to human seeing as a biological and mental process.","zh":"這個短語指作為生物和心理過程的人類觀看能力。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":8},{"front":"providing evidence that","meaning":"提供證據證明","examples":[{"en":"The cube provided evidence that the brain is a neural network.","zh":"該立方體提供證據證明大腦是一個神經網絡。"},{"en":"Providing evidence that something is true means giving support for that claim.","zh":"“Providing evidence that” 某事為真指為該主張提供支持。"},{"en":"Better exam results may provide evidence that a new teaching method works.","zh":"更好的考試成績可能提供證據證明新教學方法有效。"},{"en":"If an illusion switches between two states, it may provide evidence that perception is actively constructed.","zh":"如果錯覺在兩種狀態之間切換，它可能提供證據證明感知是主動建構的。"},{"en":"The phrase links proof or support with an idea.","zh":"這個短語把證明或支持與想法連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":8},{"front":"a neural network","meaning":"神經網絡","examples":[{"en":"The brain can be understood as a neural network.","zh":"大腦可以被理解為一個神經網絡。"},{"en":"A neural network is a system of connected nerve cells or connected processing units.","zh":"神經網絡是由相互連接的神經細胞或處理單元組成的系統。"},{"en":"The brain’s neural network helps people learn from repeated experience.","zh":"大腦的神經網絡幫助人們從反覆經驗中學習。"},{"en":"If one part of a neural network changes, the final interpretation may also change.","zh":"如果神經網絡的一部分改變，最終解讀也可能改變。"},{"en":"The phrase describes connected processing rather than one isolated part.","zh":"這個短語描述連接式處理，而不是單一孤立部分。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":8},{"front":"two distinct, interchangeable states","meaning":"兩種不同而可互換的狀態","examples":[{"en":"The brain may have two distinct, interchangeable states.","zh":"大腦可能有兩種不同而可互換的狀態。"},{"en":"Two distinct, interchangeable states are two clearly different conditions that can switch with each other.","zh":"兩種不同而可互換的狀態，是兩種清楚不同且可以互相切換的情況。"},{"en":"A light switch has two distinct states: on and off.","zh":"電燈開關有兩種不同狀態：開和關。"},{"en":"In the Necker cube, perception may switch between two distinct states.","zh":"在內克爾立方體中，感知可能在兩種不同狀態之間切換。"},{"en":"The phrase describes clear alternatives that can replace one another.","zh":"這個短語描述可以互相替換的清晰選項。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":8},{"front":"has also been used in","meaning":"也被用於","examples":[{"en":"The Necker cube has also been used in epistemology.","zh":"內克爾立方體也被用於知識論。"},{"en":"Has also been used in means has served a purpose in another field or context as well.","zh":"“Has also been used in” 指也在另一領域或語境中發揮用途。"},{"en":"A story from history has also been used in leadership training.","zh":"一個歷史故事也被用於領導力培訓。"},{"en":"If an illusion has also been used in philosophy, it has meaning beyond psychology.","zh":"如果錯覺也被用於哲學，它就有超越心理學的意義。"},{"en":"The phrase adds another area of use.","zh":"這個短語加入另一個使用範疇。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":9},{"front":"epistemology","meaning":"知識論","examples":[{"en":"Epistemology is the study of knowledge.","zh":"知識論是對知識的研究。"},{"en":"Epistemology asks what knowledge is and how people can know something is true.","zh":"知識論探問知識是甚麼，以及人如何知道某事為真。"},{"en":"A philosophy class may study epistemology by asking whether seeing is always believing.","zh":"哲學課可能透過問「眼見是否總為真」來研究知識論。"},{"en":"Optical illusions interest epistemology because they challenge trust in perception.","zh":"視覺錯覺令知識論感興趣，因為它們挑戰對感知的信任。"},{"en":"The word names a branch of philosophy.","zh":"這個詞指哲學的一個分支。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":9},{"front":"the study of knowledge","meaning":"對知識的研究","examples":[{"en":"Epistemology is the study of knowledge.","zh":"知識論是對知識的研究。"},{"en":"The study of knowledge examines how people know, justify, and doubt beliefs.","zh":"對知識的研究探討人如何知道、證明和懷疑信念。"},{"en":"A student studying knowledge may ask whether memory is always reliable.","zh":"研究知識的學生可能問記憶是否總是可靠。"},{"en":"Illusions matter to the study of knowledge because they show perception can mislead us.","zh":"錯覺對知識研究很重要，因為它們顯示感知可以誤導我們。"},{"en":"The phrase explains epistemology in simple words.","zh":"這個短語用簡單語言解釋 epistemology。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":9},{"front":"challenge direct realism","meaning":"質疑直接實在論","examples":[{"en":"The Necker cube has been used to challenge direct realism.","zh":"內克爾立方體曾被用來質疑直接實在論。"},{"en":"To challenge direct realism means to question the belief that we see the world exactly as it is.","zh":"“Challenge direct realism” 指質疑我們如實看見世界這種信念。"},{"en":"An illusion challenges direct realism because one object can appear in two different ways.","zh":"錯覺質疑直接實在論，因為同一物件可以以兩種不同方式呈現。"},{"en":"If perception changes while the object stays the same, direct realism becomes harder to defend.","zh":"如果物件保持不變而感知改變，直接實在論就更難維護。"},{"en":"The phrase connects visual illusion with philosophy.","zh":"這個短語把視覺錯覺與哲學連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":9},{"front":"direct realism","meaning":"直接實在論","examples":[{"en":"Direct realism claims that the world is exactly as the mind perceives it.","zh":"直接實在論主張世界正如心智所感知的一樣。"},{"en":"Direct realism is the theory that perception gives us direct access to the world as it really is.","zh":"直接實在論是一種理論，認為感知讓我們直接接觸真實世界本身。"},{"en":"A person who accepts direct realism may say that seeing a table means knowing the table as it is.","zh":"接受直接實在論的人可能說，看見桌子就是知道桌子本來的樣子。"},{"en":"Optical illusions create problems for direct realism because sight can be misleading.","zh":"視覺錯覺為直接實在論帶來問題，因為視覺可以具誤導性。"},{"en":"The phrase names a philosophical view about perception.","zh":"這個短語指關於感知的哲學觀點。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":9},{"front":"the theory that","meaning":"……的理論","examples":[{"en":"Direct realism is the theory that we perceive the world exactly as it is.","zh":"直接實在論是我們如實感知世界的理論。"},{"en":"The theory that something is true means an organised explanation or belief about it.","zh":"“The theory that” 某事為真指關於它的一套有組織解釋或信念。"},{"en":"The theory that sleep improves memory is supported by many studies.","zh":"睡眠改善記憶的理論得到許多研究支持。"},{"en":"If a theory is challenged by evidence, researchers must rethink it.","zh":"如果一個理論受到證據挑戰，研究人員必須重新思考它。"},{"en":"The phrase introduces a formal idea or explanation.","zh":"這個短語引出正式想法或解釋。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":9},{"front":"exactly as","meaning":"正正如……一樣","examples":[{"en":"Direct realism suggests that the world is exactly as the human mind perceives it.","zh":"直接實在論認為世界正正如人類心智所感知的一樣。"},{"en":"Exactly as means in precisely the same way as something else.","zh":"“Exactly as” 指與另一事物完全同樣地。"},{"en":"The room looked exactly as it did in the photograph.","zh":"房間看起來正正如照片中一樣。"},{"en":"If we do not see the world exactly as it is, perception must involve interpretation.","zh":"如果我們不是正正如世界本來那樣看見世界，感知就必然涉及解讀。"},{"en":"The phrase stresses perfect sameness.","zh":"這個短語強調完全相同。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":9},{"front":"the human mind perceives it","meaning":"人類心智感知它的方式","examples":[{"en":"The theory concerns how the human mind perceives the world.","zh":"這個理論關乎人類心智感知世界的方式。"},{"en":"How the human mind perceives it means the way people mentally see or understand something.","zh":"“How the human mind perceives it” 指人們在心智上觀看或理解某事的方式。"},{"en":"A painting may look different depending on how the human mind perceives colour and depth.","zh":"一幅畫可能因人類心智如何感知顏色和深度而看起來不同。"},{"en":"If the human mind perceives an image incorrectly, perception and reality can separate.","zh":"如果人類心智錯誤感知影像，感知和現實就可能分離。"},{"en":"The phrase focuses on mental interpretation.","zh":"這個短語強調心理解讀。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":9},{"front":"either or both versions","meaning":"其中一個或兩個版本","examples":[{"en":"People can often see either or both versions of the cube.","zh":"人們通常可以看見立方體其中一個或兩個版本。"},{"en":"Either or both versions means one version, the other version, or both versions at different times.","zh":"“Either or both versions” 指一個版本、另一個版本，或在不同時間看見兩個版本。"},{"en":"A reader may understand either or both versions of an ambiguous joke.","zh":"讀者可能理解模稜兩可笑話的其中一個或兩個版本。"},{"en":"In the Necker cube, the viewer may switch between either or both versions.","zh":"在內克爾立方體中，觀看者可能在其中一個或兩個版本之間切換。"},{"en":"The phrase allows multiple possible interpretations.","zh":"這個短語容許多種可能解讀。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":9},{"front":"a two-dimensional drawing","meaning":"二維圖畫","examples":[{"en":"The Necker cube is only a two-dimensional drawing.","zh":"內克爾立方體只是一幅二維圖畫。"},{"en":"A two-dimensional drawing has height and width but no real depth.","zh":"二維圖畫有高度和闊度，但沒有真實深度。"},{"en":"A picture on paper is two-dimensional even if it looks like a deep room.","zh":"紙上的圖片即使看起來像深房間，也是二維的。"},{"en":"If a two-dimensional drawing looks three-dimensional, the brain has interpreted depth from lines.","zh":"如果二維圖畫看起來像三維，大腦就是從線條中解讀出深度。"},{"en":"The phrase contrasts flat images with real 3D objects.","zh":"這個短語把平面影像與真實三維物件作對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":9},{"front":"made up of","meaning":"由……組成","examples":[{"en":"The drawing is made up of 12 lines.","zh":"該圖畫由12條線組成。"},{"en":"Made up of means consisting of or formed from particular parts.","zh":"“Made up of” 指由特定部分構成或形成。"},{"en":"A sentence is made up of words arranged in order.","zh":"句子由按順序排列的詞語組成。"},{"en":"If a drawing is made up of only lines, the brain may still see a complete object.","zh":"如果圖畫只由線條組成，大腦仍可能看見完整物件。"},{"en":"The phrase describes the parts that form a whole.","zh":"這個短語描述形成整體的部分。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":9},{"front":"affect a person’s ability to","meaning":"影響某人……的能力","examples":[{"en":"Distorting illusions affect a person’s ability to judge size.","zh":"扭曲錯覺影響人判斷大小的能力。"},{"en":"To affect a person’s ability to do something means to change how well they can do it.","zh":"“Affect a person’s ability to” 做某事指改變某人做該事的能力。"},{"en":"Lack of sleep can affect a person’s ability to concentrate in class.","zh":"睡眠不足可以影響人在課堂上集中精神的能力。"},{"en":"If an illusion affects the ability to judge length, people may give wrong answers.","zh":"如果錯覺影響判斷長度的能力，人們可能給出錯誤答案。"},{"en":"The phrase links a cause with a change in performance.","zh":"這個短語把原因與表現改變連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":10},{"front":"judge size, length or curvature","meaning":"判斷大小、長度或曲度","examples":[{"en":"Distorting illusions affect how people judge size, length or curvature.","zh":"扭曲錯覺影響人們如何判斷大小、長度或曲度。"},{"en":"To judge size, length or curvature means to estimate how big, long, or curved something is.","zh":"“Judge size, length or curvature” 指估計某物有多大、多長或多彎。"},{"en":"A tailor must judge size and length carefully before cutting cloth.","zh":"裁縫在裁布前必須仔細判斷大小和長度。"},{"en":"If background lines mislead the eye, people may judge size or length wrongly.","zh":"如果背景線條誤導眼睛，人們可能錯誤判斷大小或長度。"},{"en":"The phrase describes visual measurement by the mind.","zh":"這個短語描述由心智進行的視覺量度。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":10},{"front":"curvature","meaning":"曲度；彎曲程度","examples":[{"en":"Some illusions affect a person’s judgement of curvature.","zh":"一些錯覺影響人對曲度的判斷。"},{"en":"Curvature means the degree to which a line or surface bends.","zh":"曲度指線條或表面彎曲的程度。"},{"en":"A road with strong curvature can be difficult for drivers to see around.","zh":"曲度很大的道路可能令司機難以看見彎位後方。"},{"en":"If an illusion changes perceived curvature, a straight line may seem slightly bent.","zh":"如果錯覺改變感知到的曲度，直線可能看似略為彎曲。"},{"en":"The word is useful for describing curves and bends.","zh":"這個詞適合描述曲線和彎曲。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":10},{"front":"the Müller-Lyer illusion","meaning":"繆勒－萊爾錯覺","examples":[{"en":"The Müller-Lyer illusion is a prime example of a distorting illusion.","zh":"繆勒－萊爾錯覺是扭曲錯覺的典型例子。"},{"en":"The Müller-Lyer illusion is a line illusion in which equal lines appear unequal because of arrow-like ends.","zh":"繆勒－萊爾錯覺是一種線條錯覺，其中相等線條因像箭頭的末端而看似不相等。"},{"en":"A psychology teacher may use the Müller-Lyer illusion to show how context affects judgement.","zh":"心理學老師可能使用繆勒－萊爾錯覺，展示背景如何影響判斷。"},{"en":"It works because the ends of the lines change how people judge their length.","zh":"它之所以有效，是因為線條末端改變了人們對長度的判斷。"},{"en":"The phrase names a famous illusion about perceived length.","zh":"這個短語指一種關於感知長度的著名錯覺。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":10},{"front":"consists of","meaning":"由……組成","examples":[{"en":"The Müller-Lyer illusion consists of three lines with arrow-like ends.","zh":"繆勒－萊爾錯覺由三條帶有像箭頭末端的線組成。"},{"en":"Consists of means is made up of particular parts.","zh":"“Consists of” 指由特定部分組成。"},{"en":"A simple breakfast may consist of bread, eggs, and tea.","zh":"簡單早餐可能由麵包、雞蛋和茶組成。"},{"en":"If an illusion consists of only lines, small design changes can still mislead perception.","zh":"如果錯覺只由線條組成，細小設計變化仍可誤導感知。"},{"en":"The phrase describes what something contains.","zh":"這個短語描述某物包含甚麼。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":10},{"front":"arrow-like ends","meaning":"像箭頭的末端","examples":[{"en":"The lines in the Müller-Lyer illusion have arrow-like ends.","zh":"繆勒－萊爾錯覺中的線條有像箭頭的末端。"},{"en":"Arrow-like ends are line tips shaped like arrows or arrowheads.","zh":"像箭頭的末端是形狀像箭或箭頭的線端。"},{"en":"Road signs often use arrow-like ends to show direction.","zh":"路牌常使用像箭頭的末端來顯示方向。"},{"en":"In the Müller-Lyer illusion, arrow-like ends change how long the lines appear.","zh":"在繆勒－萊爾錯覺中，像箭頭的末端改變線條看起來的長度。"},{"en":"The phrase describes a shape feature at the end of a line.","zh":"這個短語描述線條末端的形狀特徵。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":10},{"front":"a prime example","meaning":"典型例子","examples":[{"en":"The Müller-Lyer illusion is a prime example of a distorting illusion.","zh":"繆勒－萊爾錯覺是扭曲錯覺的典型例子。"},{"en":"A prime example is an especially clear or important example of something.","zh":"典型例子是某事特別清楚或重要的例子。"},{"en":"A missed train because of poor planning is a prime example of why time management matters.","zh":"因規劃差而錯過火車，是時間管理為何重要的典型例子。"},{"en":"If an illusion clearly distorts perceived length, it is a prime example of a distorting illusion.","zh":"如果一種錯覺清楚扭曲感知長度，它就是扭曲錯覺的典型例子。"},{"en":"The phrase points to a strong model case.","zh":"這個短語指有力的代表案例。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":10},{"front":"outward-pointing ends","meaning":"向外指的末端","examples":[{"en":"The middle line has two outward-pointing ends.","zh":"中間線有兩個向外指的末端。"},{"en":"Outward-pointing ends are tips that point away from the centre of a line or shape.","zh":"向外指的末端是指向線條或形狀中心以外的端點。"},{"en":"A sign may use outward-pointing arrows to show two exits in opposite directions.","zh":"標誌可能使用向外指的箭頭顯示相反方向的兩個出口。"},{"en":"In the illusion, outward-pointing ends can make a line appear longer.","zh":"在錯覺中，向外指的末端可以令線條看似較長。"},{"en":"The phrase describes direction at the ends of a line.","zh":"這個短語描述線條末端的方向。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":10},{"front":"inward-pointing ends","meaning":"向內指的末端","examples":[{"en":"The line above it has two inward-pointing ends.","zh":"它上方的線有兩個向內指的末端。"},{"en":"Inward-pointing ends are tips that point toward the centre of a line or shape.","zh":"向內指的末端是指向線條或形狀中心的端點。"},{"en":"Arrows pointing toward a box can show where items should be placed.","zh":"指向盒子的箭頭可以顯示物件應放在哪裡。"},{"en":"In the Müller-Lyer illusion, inward-pointing ends can make a line seem shorter or longer depending on context.","zh":"在繆勒－萊爾錯覺中，向內指的末端可以視乎語境令線條看似較短或較長。"},{"en":"The phrase contrasts with outward-pointing ends.","zh":"這個短語與向外指的末端形成對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":10},{"front":"one of each","meaning":"各有一個","examples":[{"en":"The third line has one of each type of end.","zh":"第三條線各有一個類型的末端。"},{"en":"One of each means one item from each of two or more types.","zh":"“One of each” 指每一種類型各一個。"},{"en":"A customer may buy one of each flavour to try them all.","zh":"顧客可能每種口味各買一個來試。"},{"en":"If a line has one of each arrow end, it combines both visual cues.","zh":"如果一條線各有一個箭頭末端，它就結合兩種視覺線索。"},{"en":"The phrase shows a mixed selection.","zh":"這個短語顯示混合選擇。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":10},{"front":"respondents from certain backgrounds","meaning":"來自某些背景的受訪者","examples":[{"en":"Respondents from certain backgrounds may misjudge the line lengths.","zh":"來自某些背景的受訪者可能誤判線條長度。"},{"en":"Respondents from certain backgrounds are survey or study participants with particular cultural or life experiences.","zh":"來自某些背景的受訪者，是具有特定文化或生活經驗的調查或研究參與者。"},{"en":"Respondents from urban backgrounds may answer differently from those raised in rural areas.","zh":"來自城市背景的受訪者，回答可能不同於在鄉村長大的人。"},{"en":"If background affects perception, respondents from certain backgrounds may be more likely to see an illusion.","zh":"如果背景影響感知，來自某些背景的受訪者可能較容易看見錯覺。"},{"en":"The phrase connects people’s responses with their experience.","zh":"這個短語把人的回應與其經驗連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":10},{"front":"the longest","meaning":"最長的","examples":[{"en":"Many respondents say that the middle line is the longest.","zh":"許多受訪者說中間線是最長的。"},{"en":"The longest means greater in length than all the others being compared.","zh":"“The longest” 指在被比較的事物中長度最大。"},{"en":"In a race, the longest route takes the most time to finish.","zh":"在比賽中，最長的路線需要最多時間完成。"},{"en":"If equal lines look different, people may wrongly choose one as the longest.","zh":"如果相等線條看起來不同，人們可能錯誤地選其中一條為最長。"},{"en":"The phrase is used when comparing length.","zh":"這個短語用於比較長度。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":11},{"front":"although all three are equal","meaning":"儘管三者相等","examples":[{"en":"Many people misjudge the lines although all three are equal.","zh":"儘管三者相等，許多人仍誤判這些線。"},{"en":"Although all three are equal means even though the three items have the same measurement or value.","zh":"“Although all three are equal” 指即使三個項目有相同量度或價值。"},{"en":"Three cups may look different although all three are equal in volume.","zh":"三個杯子可能看起來不同，儘管三者容量相等。"},{"en":"If viewers choose one line as longer although all three are equal, an illusion is affecting judgement.","zh":"如果觀看者在三條線相等時仍選一條為較長，錯覺正在影響判斷。"},{"en":"The phrase highlights contrast between appearance and fact.","zh":"這個短語強調外觀與事實之間的對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":11},{"front":"cultural background","meaning":"文化背景","examples":[{"en":"Cultural background affects perceptions of this illusion.","zh":"文化背景影響對這種錯覺的感知。"},{"en":"Cultural background means the customs, environments, and experiences a person grows up with.","zh":"文化背景指一個人成長時接觸的習俗、環境和經驗。"},{"en":"A student’s cultural background may affect how they understand humour or politeness.","zh":"學生的文化背景可能影響他如何理解幽默或禮貌。"},{"en":"If people grow up around many rectangular buildings, their cultural background may shape visual habits.","zh":"如果人在許多長方形建築物周圍長大，其文化背景可能塑造視覺習慣。"},{"en":"The phrase links culture and experience with interpretation.","zh":"這個短語把文化和經驗與解讀連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":11},{"front":"affects perceptions of","meaning":"影響對……的感知","examples":[{"en":"Cultural background affects perceptions of the Müller-Lyer illusion.","zh":"文化背景影響對繆勒－萊爾錯覺的感知。"},{"en":"Affects perceptions of means changes how people see or understand something.","zh":"“Affects perceptions of” 指改變人們如何看見或理解某事。"},{"en":"Lighting affects perceptions of colour in a clothing shop.","zh":"光線會影響對服裝店中顏色的感知。"},{"en":"If culture affects perception of an illusion, people from different societies may respond differently.","zh":"如果文化影響對錯覺的感知，來自不同社會的人可能有不同回應。"},{"en":"The phrase connects an influence with people’s interpretation.","zh":"這個短語把一種影響與人的解讀連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":11},{"front":"international research","meaning":"國際研究","examples":[{"en":"International research has shown differences in perception.","zh":"國際研究顯示感知上的差異。"},{"en":"International research is research carried out across different countries or cultures.","zh":"國際研究是在不同國家或文化中進行的研究。"},{"en":"International research may compare how students in different places learn languages.","zh":"國際研究可能比較不同地方學生如何學習語言。"},{"en":"If international research finds different illusion responses, culture may be part of the explanation.","zh":"如果國際研究發現對錯覺的不同反應，文化可能是解釋的一部分。"},{"en":"The phrase suggests evidence beyond one local group.","zh":"這個短語暗示證據超越單一本地群體。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":11},{"front":"non-Western subjects","meaning":"非西方受試者","examples":[{"en":"Non-Western subjects are less likely to misjudge the lines.","zh":"非西方受試者較不可能誤判線條。"},{"en":"Non-Western subjects are research participants from cultures outside Western societies.","zh":"非西方受試者是來自西方社會以外文化的研究參與者。"},{"en":"Non-Western subjects may have different visual habits if their built environments differ.","zh":"如果建築環境不同，非西方受試者可能有不同視覺習慣。"},{"en":"If non-Western subjects misjudge an illusion less often, experience may affect perception.","zh":"如果非西方受試者較少誤判錯覺，經驗可能影響感知。"},{"en":"The phrase is used in research comparisons across cultures.","zh":"這個短語用於跨文化研究比較。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":11},{"front":"particularly those who","meaning":"尤其是那些……的人","examples":[{"en":"Non-Western subjects, particularly those not exposed to rectangular buildings, may judge the lines more accurately.","zh":"非西方受試者，尤其是那些沒有接觸長方形建築物的人，可能更準確判斷線條。"},{"en":"Particularly those who means especially the people in a larger group who meet a certain condition.","zh":"“Particularly those who” 指在較大群體中特別符合某條件的人。"},{"en":"Students, particularly those who practise daily, improve faster.","zh":"學生，尤其是那些每天練習的人，進步更快。"},{"en":"If a visual habit comes from buildings, people particularly those without such exposure may respond differently.","zh":"如果視覺習慣來自建築物，尤其是那些沒有這種接觸的人可能有不同反應。"},{"en":"The phrase narrows a group to an important subgroup.","zh":"這個短語把一個群體收窄至重要子群體。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":11},{"front":"regularly exposed to","meaning":"經常接觸","examples":[{"en":"Some subjects are not regularly exposed to rectangular buildings.","zh":"一些受試者沒有經常接觸長方形建築物。"},{"en":"Regularly exposed to means often in contact with or often seeing something.","zh":"“Regularly exposed to” 指經常接觸或看見某事物。"},{"en":"Children regularly exposed to books may develop stronger reading habits.","zh":"經常接觸書籍的孩子可能形成更強閱讀習慣。"},{"en":"If people are regularly exposed to rectangular buildings, they may learn certain depth cues.","zh":"如果人們經常接觸長方形建築物，他們可能學會某些深度線索。"},{"en":"The phrase describes repeated experience.","zh":"這個短語描述重複經驗。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":11},{"front":"rectangular buildings","meaning":"長方形建築物","examples":[{"en":"Rectangular buildings may influence visual habits.","zh":"長方形建築物可能影響視覺習慣。"},{"en":"Rectangular buildings are buildings with many straight lines, right angles, and rectangular shapes.","zh":"長方形建築物是有許多直線、直角和長方形形狀的建築。"},{"en":"Offices and apartment blocks are often rectangular buildings.","zh":"辦公室和住宅大廈通常是長方形建築物。"},{"en":"Living around rectangular buildings may train the brain to interpret angles in a certain way.","zh":"生活在長方形建築物周圍，可能訓練大腦以某種方式解讀角度。"},{"en":"The phrase connects built environment with perception.","zh":"這個短語把建築環境與感知連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":11},{"front":"door frames","meaning":"門框","examples":[{"en":"Door frames can affect people’s perception of geometric illusions.","zh":"門框可以影響人們對幾何錯覺的感知。"},{"en":"Door frames are the rectangular structures around doors.","zh":"門框是圍繞門的長方形結構。"},{"en":"A carpenter must measure door frames accurately before installing doors.","zh":"木匠在安裝門前必須準確量度門框。"},{"en":"Because door frames contain straight lines and angles, they may shape visual expectations.","zh":"因為門框包含直線和角度，它們可能塑造視覺預期。"},{"en":"The phrase gives a familiar example of a rectangular environment.","zh":"這個短語提供長方形環境的熟悉例子。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":11},{"front":"less likely to","meaning":"較不可能","examples":[{"en":"Some subjects are less likely to misjudge the lines.","zh":"一些受試者較不可能誤判線條。"},{"en":"Less likely to do something means having a lower chance of doing it.","zh":"“Less likely to” 做某事指做該事的機會較低。"},{"en":"Students who revise early are less likely to panic before exams.","zh":"及早溫習的學生較不可能在考試前慌張。"},{"en":"If people are less likely to misjudge an illusion, their background may provide different visual habits.","zh":"如果人們較不可能誤判錯覺，其背景可能提供不同視覺習慣。"},{"en":"The phrase compares probability.","zh":"這個短語比較可能性。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":11},{"front":"misjudge","meaning":"判斷錯誤","examples":[{"en":"People may misjudge the true lengths of the lines.","zh":"人們可能判斷錯誤這些線條的真實長度。"},{"en":"To misjudge something means to judge it wrongly.","zh":"“Misjudge” 某事指錯誤地判斷它。"},{"en":"A driver may misjudge the distance to another car when parking.","zh":"司機泊車時可能判斷錯誤與另一輛車的距離。"},{"en":"If an illusion changes appearance, people may misjudge size, length, or direction.","zh":"如果錯覺改變外觀，人們可能判斷錯誤大小、長度或方向。"},{"en":"The word describes an error in judgement.","zh":"這個詞描述判斷上的錯誤。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":12},{"front":"true lengths","meaning":"真實長度","examples":[{"en":"The lines’ true lengths are actually equal.","zh":"這些線條的真實長度其實相等。"},{"en":"True lengths are the real measured lengths, not the lengths that appear to the eye.","zh":"真實長度是實際量度出的長度，而不是眼睛看見的長度。"},{"en":"Two ribbons may look different, but their true lengths can be checked with a ruler.","zh":"兩條絲帶可能看起來不同，但其真實長度可以用尺檢查。"},{"en":"In the Müller-Lyer illusion, perceived length differs from true length.","zh":"在繆勒－萊爾錯覺中，感知長度不同於真實長度。"},{"en":"The phrase contrasts measurement with appearance.","zh":"這個短語把量度與外觀作對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":12},{"front":"encourage the mind to","meaning":"促使大腦去","examples":[{"en":"Paradox illusions encourage the mind to believe something impossible.","zh":"悖論錯覺促使大腦相信不可能的東西。"},{"en":"To encourage the mind to do something means to lead the brain toward a particular interpretation.","zh":"“Encourage the mind to” 做某事指引導大腦作出某種解讀。"},{"en":"A clever advertisement can encourage the mind to connect a product with happiness.","zh":"巧妙廣告可以促使大腦把產品與快樂連繫起來。"},{"en":"If an image encourages the mind to accept an impossible object, rational judgement is challenged.","zh":"如果影像促使大腦接受不可能物件，理性判斷就受到挑戰。"},{"en":"The phrase shows how visual design guides thought.","zh":"這個短語顯示視覺設計如何引導思想。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":12},{"front":"known to be impossible","meaning":"已知不可能的","examples":[{"en":"The mind may believe that it is seeing something known to be impossible.","zh":"大腦可能相信它正在看見已知不可能的東西。"},{"en":"Known to be impossible means understood as unable to exist or happen in reality.","zh":"“Known to be impossible” 指被理解為在現實中不能存在或發生。"},{"en":"A staircase that climbs forever is known to be impossible in real life.","zh":"永遠向上爬的樓梯在現實中已知不可能。"},{"en":"If viewers see something known to be impossible, they may still feel the image makes sense locally.","zh":"如果觀看者看見已知不可能的東西，他們仍可能覺得影像局部合理。"},{"en":"The phrase creates contrast between knowledge and perception.","zh":"這個短語在知識與感知之間形成對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":12},{"front":"the Penrose Stairs","meaning":"彭羅斯階梯","examples":[{"en":"The Penrose Stairs are an example of a paradox illusion.","zh":"彭羅斯階梯是悖論錯覺的一個例子。"},{"en":"The Penrose Stairs show a staircase that appears to rise continuously while forming a loop.","zh":"彭羅斯階梯顯示一條看似不斷上升並形成循環的樓梯。"},{"en":"An art teacher may use the Penrose Stairs to explain impossible objects.","zh":"美術老師可能使用彭羅斯階梯來解釋不可能物件。"},{"en":"The illusion works because each part seems reasonable, but the whole structure cannot exist.","zh":"這種錯覺有效，是因為每一部分看似合理，但整體結構不能存在。"},{"en":"The phrase names a famous impossible-staircase illusion.","zh":"這個短語指著名的不可能階梯錯覺。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":12},{"front":"the Penrose Triangle","meaning":"彭羅斯三角形","examples":[{"en":"The Penrose Triangle illustrates a paradox illusion.","zh":"彭羅斯三角形說明悖論錯覺。"},{"en":"The Penrose Triangle is an impossible triangular object that looks connected but cannot exist in 3D space.","zh":"彭羅斯三角形是一個看似相連但不能在三維空間存在的不可能三角物件。"},{"en":"A designer may use the Penrose Triangle to create a puzzling logo.","zh":"設計師可能使用彭羅斯三角形來創造令人困惑的標誌。"},{"en":"The shape tricks the brain because its corners seem possible separately but impossible together.","zh":"這個形狀欺騙大腦，因為其角位分開看似可能，但合起來不可能。"},{"en":"The phrase names a classic impossible-object illusion.","zh":"這個短語指經典的不可能物件錯覺。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":12},{"front":"developed by","meaning":"由……發展；由……設計","examples":[{"en":"The Penrose Stairs and Penrose Triangle were developed by Lionel Penrose.","zh":"彭羅斯階梯和彭羅斯三角形由 Lionel Penrose 設計。"},{"en":"Developed by someone means designed, created, or improved by that person.","zh":"“Developed by” 某人指由該人設計、創造或改良。"},{"en":"A learning app developed by teachers may match classroom needs better.","zh":"由老師開發的學習應用程式可能更配合課堂需要。"},{"en":"If an illusion was developed by a researcher, it may have been made to test a specific idea.","zh":"如果錯覺由研究人員設計，它可能是用來測試某個特定想法。"},{"en":"The phrase identifies the creator or designer.","zh":"這個短語指出創作者或設計者。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":12},{"front":"models created to illustrate","meaning":"用作說明……的模型","examples":[{"en":"The Penrose models were created to illustrate paradox illusions.","zh":"彭羅斯模型是用作說明悖論錯覺的模型。"},{"en":"Models created to illustrate something are examples designed to explain or show an idea clearly.","zh":"用作說明某事的模型，是為清楚解釋或展示某想法而設計的例子。"},{"en":"A science teacher may use a water-cycle model created to illustrate evaporation and rain.","zh":"科學老師可能使用用作說明蒸發和降雨的水循環模型。"},{"en":"If a model is created to illustrate an illusion, it helps viewers understand the principle.","zh":"如果模型用作說明錯覺，它幫助觀看者理解原理。"},{"en":"The phrase connects design with teaching or explanation.","zh":"這個短語把設計與教學或解釋連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":12},{"front":"this phenomenon","meaning":"這個現象","examples":[{"en":"The Penrose models illustrate this phenomenon.","zh":"彭羅斯模型說明這個現象。"},{"en":"This phenomenon means the event, effect, or pattern just mentioned.","zh":"“This phenomenon” 指剛才提到的事件、效果或模式。"},{"en":"If students keep forgetting homework after long school days, this phenomenon may be linked to tiredness.","zh":"如果學生在漫長上課日後不斷忘記功課，這個現象可能與疲勞有關。"},{"en":"In paradox illusions, this phenomenon is the mind accepting an impossible image.","zh":"在悖論錯覺中，這個現象是大腦接受不可能影像。"},{"en":"The phrase points back to a specific observed effect.","zh":"這個短語回指某個特定觀察效果。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":12},{"front":"naturally occurring optical illusions","meaning":"自然出現的視覺錯覺","examples":[{"en":"Naturally occurring optical illusions also exist.","zh":"自然出現的視覺錯覺也存在。"},{"en":"Naturally occurring optical illusions are visual illusions found in real environments, not just drawings.","zh":"自然出現的視覺錯覺是在真實環境中發現的視覺錯覺，而不只是圖畫。"},{"en":"A road on a gravity hill can create a naturally occurring optical illusion.","zh":"怪坡上的道路可以造成自然出現的視覺錯覺。"},{"en":"These illusions may happen because land, trees, and horizons create misleading reference points.","zh":"這些錯覺可能因土地、樹木和地平線造成誤導性參照點而出現。"},{"en":"The phrase contrasts natural scenes with artificial illusion pictures.","zh":"這個短語把自然場景與人工錯覺圖片作對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":12},{"front":"in various places around the world","meaning":"在世界各地不同地方","examples":[{"en":"Gravity hills exist in various places around the world.","zh":"怪坡存在於世界各地不同地方。"},{"en":"In various places around the world means in several different locations globally.","zh":"“In various places around the world” 指在全球幾個不同地點。"},{"en":"Similar street foods can be found in various places around the world.","zh":"相似街頭食物可以在世界各地不同地方找到。"},{"en":"If an illusion appears in various places around the world, it is not limited to one country.","zh":"如果一種錯覺出現在世界各地不同地方，它就不限於一個國家。"},{"en":"The phrase shows wide geographical distribution.","zh":"這個短語顯示廣泛地理分布。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":12},{"front":"appear to roll uphill","meaning":"看似向上坡滾動","examples":[{"en":"Objects appear to roll uphill at some locations.","zh":"物件在一些地點看似向上坡滾動。"},{"en":"Appear to roll uphill means seem to move up a slope, even if they are not really doing so.","zh":"“Appear to roll uphill” 指看似向斜坡上方移動，即使實際上並非如此。"},{"en":"A ball on a strange road may appear to roll uphill because of visual perspective.","zh":"怪異道路上的球可能因視覺透視而看似向上坡滾動。"},{"en":"If the surrounding land is misleading, downhill movement can appear to be uphill movement.","zh":"如果周圍地形具誤導性，向下坡移動也可以看似向上坡移動。"},{"en":"The phrase describes appearance, not actual physical motion.","zh":"這個短語描述外觀，而不是真實物理運動。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":13},{"front":"even though","meaning":"即使；儘管","examples":[{"en":"Objects appear to roll uphill even though this is impossible.","zh":"物件看似向上坡滾動，即使這是不可能的。"},{"en":"Even though means despite the fact that something is true.","zh":"“Even though” 指儘管某事屬實。"},{"en":"She went to class even though she was tired.","zh":"即使她很疲倦，她仍去上課。"},{"en":"A car may appear to roll uphill even though gravity is pulling it downhill.","zh":"汽車可能看似向上坡滾動，即使重力正在把它拉向下坡。"},{"en":"The phrase introduces contrast between fact and situation.","zh":"這個短語引出事實與情況之間的對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":13},{"front":"our knowledge tells us","meaning":"我們的知識告訴我們","examples":[{"en":"Our knowledge tells us that objects cannot roll uphill without force.","zh":"我們的知識告訴我們，物件不能在沒有外力下向上坡滾動。"},{"en":"Our knowledge tells us means what we know leads us to a clear conclusion.","zh":"“Our knowledge tells us” 指我們所知道的事情引導我們得出清晰結論。"},{"en":"Our knowledge tells us that ice melts when it gets warm.","zh":"我們的知識告訴我們，冰受熱會融化。"},{"en":"Even when our eyes are confused, our knowledge tells us gravity pulls objects downward.","zh":"即使眼睛感到混亂，我們的知識告訴我們重力把物件向下拉。"},{"en":"The phrase contrasts learned understanding with visual appearance.","zh":"這個短語把學到的理解與視覺外觀作對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":13},{"front":"visual information","meaning":"視覺資料","examples":[{"en":"Visual information may conflict with rational judgement.","zh":"視覺資料可能與理性判斷衝突。"},{"en":"Visual information is information received through sight.","zh":"視覺資料是透過視覺接收到的資料。"},{"en":"Road signs provide visual information to drivers and pedestrians.","zh":"路牌向司機和行人提供視覺資料。"},{"en":"If visual information is misleading, people may trust what they see over what they know.","zh":"如果視覺資料具誤導性，人們可能相信所看見的多於所知道的。"},{"en":"The phrase refers to data gained by looking.","zh":"這個短語指透過觀看取得的資料。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":13},{"front":"conflicts with","meaning":"與……衝突","examples":[{"en":"Visual information conflicts with rational judgement.","zh":"視覺資料與理性判斷衝突。"},{"en":"Conflicts with means does not agree with or goes against something.","zh":"“Conflicts with” 指與某事不一致或相反。"},{"en":"A student’s excuse conflicts with the teacher’s record of attendance.","zh":"學生的藉口與老師的出席紀錄衝突。"},{"en":"If what we see conflicts with what physics tells us, an illusion may be involved.","zh":"如果我們所看見的與物理學告訴我們的東西衝突，可能涉及錯覺。"},{"en":"The phrase shows contradiction between two sources of information.","zh":"這個短語顯示兩個資料來源之間的矛盾。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":13},{"front":"rational judgement","meaning":"理性判斷","examples":[{"en":"Paradox illusions can challenge rational judgement.","zh":"悖論錯覺可以挑戰理性判斷。"},{"en":"Rational judgement is careful thinking based on reason, evidence, and logic.","zh":"理性判斷是基於理由、證據和邏輯的謹慎思考。"},{"en":"A buyer uses rational judgement when comparing price, quality, and need before buying.","zh":"買家在購買前比較價格、品質和需要時，就是使用理性判斷。"},{"en":"If an image seems impossible, rational judgement may reject what the eyes suggest.","zh":"如果影像看似不可能，理性判斷可能拒絕眼睛所暗示的東西。"},{"en":"The phrase contrasts logical thinking with misleading appearance.","zh":"這個短語把邏輯思考與誤導性外觀作對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":13},{"front":"gravity hills","meaning":"重力山；怪坡","examples":[{"en":"Gravity hills are locations where objects appear to roll uphill.","zh":"重力山是物件看似向上坡滾動的地點。"},{"en":"Gravity hills are places where the layout of the land makes downhill movement look like uphill movement.","zh":"重力山是地形佈局令向下坡移動看似向上坡移動的地方。"},{"en":"Tourists may visit gravity hills to watch cars seem to move against gravity.","zh":"遊客可能到訪怪坡，觀看汽車看似逆重力移動。"},{"en":"The effect happens because reference points and slopes mislead observers.","zh":"這種效果出現，是因為參照點和斜坡誤導觀察者。"},{"en":"The phrase describes a natural optical illusion, not real anti-gravity.","zh":"這個短語描述自然視覺錯覺，而不是真正反重力。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":13},{"front":"magnetic hills","meaning":"磁力山；怪坡","examples":[{"en":"Magnetic hills are popular with tourists because of their strange appearance.","zh":"磁力山因其奇怪外觀而受遊客歡迎。"},{"en":"Magnetic hills are gravity-hill sites often named as if magnetism were pulling objects uphill.","zh":"磁力山是怪坡地點，名稱常像是磁力把物件拉上坡。"},{"en":"A guide may call a road a magnetic hill to make the place sound mysterious.","zh":"導遊可能把道路稱為磁力山，令該地聽起來神秘。"},{"en":"Despite the name, the effect is usually explained by slope and perspective, not magnetism.","zh":"儘管有這個名稱，這種效果通常由斜坡和透視解釋，而不是磁力。"},{"en":"The phrase is a popular name for a visual illusion location.","zh":"這個短語是視覺錯覺地點的常見名稱。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":13},{"front":"popular with tourists","meaning":"受遊客歡迎","examples":[{"en":"Gravity hills are popular with tourists.","zh":"怪坡受遊客歡迎。"},{"en":"Popular with tourists means liked or often visited by travellers.","zh":"“Popular with tourists” 指受旅客喜愛或經常被旅客到訪。"},{"en":"Night markets are popular with tourists because they offer food, souvenirs, and local atmosphere.","zh":"夜市因提供食物、紀念品和本地氣氛而受遊客歡迎。"},{"en":"If a place seems mysterious, it may become popular with tourists quickly.","zh":"如果一個地方看似神秘，它可能很快變得受遊客歡迎。"},{"en":"The phrase describes visitor appeal.","zh":"這個短語描述對訪客的吸引力。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":13},{"front":"supposed mystical properties","meaning":"所謂神秘特性","examples":[{"en":"The locations’ supposed mystical properties are promoted to attract visitors.","zh":"這些地點的所謂神秘特性被宣傳來吸引訪客。"},{"en":"Supposed mystical properties are claimed magical or mysterious qualities that may not be real.","zh":"所謂神秘特性是聲稱具有的神奇或神秘特質，但未必真實。"},{"en":"A shop may advertise a stone’s supposed mystical properties to sell it at a higher price.","zh":"商店可能宣傳石頭的所謂神秘特性，以較高價格出售它。"},{"en":"If a hill’s strange effect is advertised as mystical, tourists may become more curious.","zh":"如果山坡的奇怪效果被宣傳為神秘，遊客可能更好奇。"},{"en":"The phrase suggests a claim rather than proven fact.","zh":"這個短語暗示主張，而不是已證實事實。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":13},{"front":"vigorously promoted","meaning":"被大力宣傳","examples":[{"en":"The mystical properties are vigorously promoted.","zh":"這些神秘特性被大力宣傳。"},{"en":"Vigorously promoted means advertised or supported very strongly and actively.","zh":"“Vigorously promoted” 指非常積極而有力地宣傳或支持。"},{"en":"A new sports centre may be vigorously promoted through posters and social media.","zh":"新運動中心可能透過海報和社交媒體被大力宣傳。"},{"en":"If a tourist site is vigorously promoted, more visitors may come even before they understand the science.","zh":"如果旅遊景點被大力宣傳，更多訪客可能在理解科學前已前來。"},{"en":"The phrase shows energetic publicity.","zh":"這個短語顯示積極宣傳。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":13},{"front":"add intrigue","meaning":"增添神秘感","examples":[{"en":"The supposed mystical properties add intrigue to the locations.","zh":"所謂神秘特性為這些地點增添神秘感。"},{"en":"To add intrigue means to make something more mysterious, interesting, or attractive.","zh":"“Add intrigue” 指令某事更神秘、有趣或吸引。"},{"en":"A locked old door can add intrigue to a museum story.","zh":"一扇上鎖的舊門可以為博物館故事增添神秘感。"},{"en":"If a hill is said to have strange powers, the claim can add intrigue and attract tourists.","zh":"如果山坡被說成有奇怪力量，這種說法可以增添神秘感並吸引遊客。"},{"en":"The phrase describes increasing curiosity.","zh":"這個短語描述增加好奇心。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":14},{"front":"attributed to","meaning":"被歸因於","examples":[{"en":"The effect is sometimes attributed to magnetic properties of the land.","zh":"這種效果有時被歸因於土地的磁性。"},{"en":"Attributed to means explained as being caused by something.","zh":"“Attributed to” 指被解釋為由某事造成。"},{"en":"A student’s improvement may be attributed to regular practice and better sleep.","zh":"學生進步可能被歸因於定期練習和更好睡眠。"},{"en":"If an illusion is attributed to magnetism, people may ignore the role of perspective.","zh":"如果錯覺被歸因於磁力，人們可能忽視透視的作用。"},{"en":"The phrase identifies a claimed cause.","zh":"這個短語指出被聲稱的原因。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":14},{"front":"special magnetic properties","meaning":"特殊磁性","examples":[{"en":"Some people attribute the illusion to special magnetic properties.","zh":"一些人把錯覺歸因於特殊磁性。"},{"en":"Special magnetic properties are unusual magnetic qualities that people claim a place or object has.","zh":"特殊磁性是人們聲稱某地方或物件具有的不尋常磁力特質。"},{"en":"A tourist sign may mention special magnetic properties to make a hill sound mysterious.","zh":"旅遊標誌可能提到特殊磁性，使山坡聽起來神秘。"},{"en":"If objects seem to roll uphill, visitors may wrongly blame special magnetic properties.","zh":"如果物件看似向上坡滾動，訪客可能錯誤地歸咎於特殊磁性。"},{"en":"The phrase refers to a popular explanation, not necessarily a scientific one.","zh":"這個短語指流行解釋，不一定是科學解釋。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":14},{"front":"the scientific explanation","meaning":"科學解釋","examples":[{"en":"The scientific explanation is based on slope and perspective.","zh":"科學解釋基於斜坡和透視。"},{"en":"The scientific explanation is the reason supported by observation, measurement, and logic.","zh":"科學解釋是由觀察、量度和邏輯支持的原因。"},{"en":"A science teacher gives the scientific explanation for rain by discussing evaporation and clouds.","zh":"科學老師透過討論蒸發和雲來給出下雨的科學解釋。"},{"en":"For gravity hills, the scientific explanation removes the need for magical forces.","zh":"對怪坡而言，科學解釋不需要神奇力量。"},{"en":"The phrase contrasts evidence-based reasoning with rumours or myths.","zh":"這個短語把有證據的推理與傳聞或神話作對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":14},{"front":"slightly sloping ground","meaning":"輕微傾斜的地面","examples":[{"en":"These areas lie on slightly sloping ground.","zh":"這些地區位於輕微傾斜的地面上。"},{"en":"Slightly sloping ground is land that rises or falls gently rather than being flat.","zh":"輕微傾斜的地面是緩慢上升或下降，而不是平坦的土地。"},{"en":"A playground on slightly sloping ground may make a ball roll slowly to one side.","zh":"位於輕微傾斜地面的遊樂場可能令球慢慢滾向一邊。"},{"en":"If the slope is slight, people may not notice the true direction of downhill movement.","zh":"如果坡度很輕微，人們可能注意不到真正的下坡方向。"},{"en":"The phrase describes a gentle land angle.","zh":"這個短語描述溫和的地面角度。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":14},{"front":"a visible horizon","meaning":"可見地平線","examples":[{"en":"A visible horizon helps people establish perspective.","zh":"可見地平線幫助人們建立透視感。"},{"en":"A visible horizon is the line where the land or sea seems to meet the sky.","zh":"可見地平線是陸地或海面看似與天空相接的線。"},{"en":"Drivers in open countryside can use a visible horizon to judge whether a road is rising or falling.","zh":"在開闊鄉郊，司機可以利用可見地平線判斷道路是上升還是下降。"},{"en":"Without a visible horizon, people may misjudge slope and direction.","zh":"沒有可見地平線，人們可能誤判坡度和方向。"},{"en":"The phrase names an important visual reference point.","zh":"這個短語指重要視覺參照點。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":14},{"front":"against which to establish perspective","meaning":"用來建立透視感的參照","examples":[{"en":"There may be no visible horizon against which to establish perspective.","zh":"可能沒有可見地平線可作為建立透視感的參照。"},{"en":"Against which to establish perspective means used as a reference for judging direction, depth, or level.","zh":"“Against which to establish perspective” 指用作判斷方向、深度或水平的參照。"},{"en":"A straight wall can be a reference against which to establish perspective in a painting.","zh":"一面直牆可以作為繪畫中建立透視感的參照。"},{"en":"Without a clear reference, viewers may not know whether the ground slopes up or down.","zh":"沒有清晰參照，觀看者可能不知道地面是上斜還是下斜。"},{"en":"The phrase explains the need for a visual standard.","zh":"這個短語解釋視覺標準的需要。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":14},{"front":"surrounding reference points","meaning":"周圍參照物","examples":[{"en":"Surrounding reference points may themselves be misleading.","zh":"周圍參照物本身可能具誤導性。"},{"en":"Surrounding reference points are nearby objects used to judge position, slope, or direction.","zh":"周圍參照物是用來判斷位置、坡度或方向的附近物件。"},{"en":"Trees, walls, and buildings can act as surrounding reference points.","zh":"樹木、牆壁和建築物可以作為周圍參照物。"},{"en":"If those reference points are tilted, they can make a downhill road seem uphill.","zh":"如果那些參照物傾斜，它們可以令下坡路看似上坡。"},{"en":"The phrase describes the visual cues around an observer.","zh":"這個短語描述觀察者周圍的視覺線索。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":14},{"front":"perpendicular","meaning":"垂直的","examples":[{"en":"Trees are usually expected to be perpendicular.","zh":"人們通常預期樹木是垂直的。"},{"en":"Perpendicular means standing at a right angle, especially upright relative to the ground.","zh":"“Perpendicular” 指成直角，尤其是相對於地面直立。"},{"en":"A wall should be perpendicular to the floor if it is built correctly.","zh":"如果牆壁建得正確，它應與地板垂直。"},{"en":"If trees are not perpendicular but we assume they are, they may mislead our sense of slope.","zh":"如果樹木並非垂直，但我們假設它們是，它們可能誤導我們對坡度的感覺。"},{"en":"The word is useful for describing vertical alignment.","zh":"這個詞適合描述垂直排列。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":14},{"front":"on a slope","meaning":"在斜坡上","examples":[{"en":"Reference points such as trees may themselves be on a slope.","zh":"樹木等參照物本身可能在斜坡上。"},{"en":"On a slope means located on land that rises or falls at an angle.","zh":"“On a slope” 指位於以角度上升或下降的土地上。"},{"en":"Houses built on a slope may need special foundations.","zh":"建在斜坡上的房屋可能需要特殊地基。"},{"en":"If trees grow on a slope, they may not provide a reliable vertical reference.","zh":"如果樹木長在斜坡上，它們可能不能提供可靠垂直參照。"},{"en":"The phrase describes position on inclined ground.","zh":"這個短語描述位於傾斜地面上的位置。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":14},{"front":"observers’ interpretations","meaning":"觀察者的解讀","examples":[{"en":"Observers’ interpretations are confused by misleading reference points.","zh":"觀察者的解讀被誤導性參照物弄混。"},{"en":"Observers’ interpretations are the ways viewers understand what they see.","zh":"觀察者的解讀是觀看者理解所見事物的方式。"},{"en":"In a classroom experiment, observers’ interpretations may differ even when they see the same image.","zh":"在課堂實驗中，即使看見同一影像，觀察者的解讀也可能不同。"},{"en":"If reference points are misleading, observers’ interpretations of slope may be wrong.","zh":"如果參照物具誤導性，觀察者對坡度的解讀可能錯誤。"},{"en":"The phrase focuses on the viewer’s mental judgement.","zh":"這個短語強調觀看者的心理判斷。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":14},{"front":"downward slopes","meaning":"下坡","examples":[{"en":"Downward slopes may seem horizontal or tilted upwards.","zh":"下坡可能看似水平或向上傾斜。"},{"en":"Downward slopes are surfaces or roads that go down from a higher point to a lower point.","zh":"下坡是由較高位置下降至較低位置的表面或道路。"},{"en":"A bike rolls faster on downward slopes because gravity helps it move.","zh":"單車在下坡時較快，因為重力幫助它移動。"},{"en":"If a downward slope is visually misread, a car moving downhill may seem to roll uphill.","zh":"如果下坡被視覺上誤讀，向下坡移動的汽車可能看似向上坡滾動。"},{"en":"The phrase describes real ground direction.","zh":"這個短語描述真實地面方向。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":15},{"front":"seem horizontal","meaning":"看似水平","examples":[{"en":"A downward slope may seem horizontal.","zh":"下坡可能看似水平。"},{"en":"Seem horizontal means appear flat or level, even if it may not be truly flat.","zh":"“Seem horizontal” 指看起來平坦或水平，即使未必真正平坦。"},{"en":"A table may seem horizontal until a ball slowly rolls across it.","zh":"桌子可能看似水平，直到球慢慢滾過去。"},{"en":"If a road seems horizontal but is actually sloping, observers may misjudge movement.","zh":"如果道路看似水平但實際傾斜，觀察者可能誤判移動。"},{"en":"The phrase describes appearance rather than measurement.","zh":"這個短語描述外觀，而不是量度。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":15},{"front":"tilted upwards","meaning":"向上傾斜","examples":[{"en":"A downward slope may seem tilted upwards.","zh":"下坡可能看似向上傾斜。"},{"en":"Tilted upwards means slanted toward a higher point.","zh":"“Tilted upwards” 指朝較高位置傾斜。"},{"en":"A photo can make a flat road seem tilted upwards if the camera angle is strange.","zh":"如果相機角度奇怪，照片可以令平路看似向上傾斜。"},{"en":"If a downhill road seems tilted upwards, a rolling car may appear to defy gravity.","zh":"如果下坡路看似向上傾斜，滾動的汽車可能看似違反重力。"},{"en":"The phrase describes perceived upward slant.","zh":"這個短語描述感知到的上斜。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":15},{"front":"with their handbrakes released","meaning":"鬆開手掣後","examples":[{"en":"Cars with their handbrakes released may appear to roll uphill.","zh":"鬆開手掣後的汽車可能看似向上坡滾動。"},{"en":"With their handbrakes released means after the parking brakes have been loosened or turned off.","zh":"“With their handbrakes released” 指停車制動器被鬆開或關掉之後。"},{"en":"A parked car with its handbrake released may move if the road slopes.","zh":"鬆開手掣後的停泊汽車，如果道路傾斜，可能會移動。"},{"en":"On a gravity hill, cars with their handbrakes released move downhill but may seem to go uphill.","zh":"在怪坡上，鬆開手掣後的汽車實際向下坡移動，但可能看似上坡。"},{"en":"The phrase describes the condition that allows the car to move.","zh":"這個短語描述讓汽車能移動的條件。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":15},{"front":"roll uphill","meaning":"向上坡滾動","examples":[{"en":"Cars may appear to roll uphill.","zh":"汽車可能看似向上坡滾動。"},{"en":"To roll uphill means to move up a slope while turning or rolling.","zh":"“Roll uphill” 指一邊滾動一邊向斜坡上方移動。"},{"en":"A ball cannot roll uphill by itself unless a force pushes it.","zh":"除非有外力推動，球不能自己向上坡滾動。"},{"en":"If a car seems to roll uphill, the road may actually slope downward in a hidden way.","zh":"如果汽車看似向上坡滾動，道路實際上可能以隱蔽方式向下傾斜。"},{"en":"The phrase often signals an illusion when no force is present.","zh":"當沒有外力存在時，這個短語常表示錯覺。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":15},{"front":"actually moving downhill","meaning":"實際上向下坡移動","examples":[{"en":"The cars are actually moving downhill under gravity.","zh":"這些汽車實際上在重力作用下向下坡移動。"},{"en":"Actually moving downhill means really travelling down a slope, despite how it appears.","zh":"“Actually moving downhill” 指真正在斜坡上向下移動，儘管外觀看來不同。"},{"en":"A toy car may look still in a video but actually be moving downhill slowly.","zh":"玩具車在影片中可能看似靜止，但實際上正慢慢向下坡移動。"},{"en":"On a gravity hill, cars seem to go up but are actually moving downhill.","zh":"在怪坡上，汽車看似上坡，但實際上向下坡移動。"},{"en":"The phrase corrects misleading appearance with real motion.","zh":"這個短語用真實運動糾正誤導性外觀。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":15},{"front":"under gravity","meaning":"在重力作用下","examples":[{"en":"The cars move downhill under gravity.","zh":"汽車在重力作用下向下坡移動。"},{"en":"Under gravity means because of the pulling force of gravity.","zh":"“Under gravity” 指因重力拉動而發生。"},{"en":"Water flows downhill under gravity.","zh":"水在重力作用下向下流。"},{"en":"If a car moves under gravity, it does not need an engine or magnet to pull it.","zh":"如果汽車在重力作用下移動，就不需要引擎或磁力拉動它。"},{"en":"The phrase explains the natural force behind movement.","zh":"這個短語解釋運動背後的自然力量。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":15},{"front":"innate sense of balance","meaning":"天生的平衡感","examples":[{"en":"Our innate sense of balance helps us judge slopes.","zh":"我們天生的平衡感幫助我們判斷斜坡。"},{"en":"An innate sense of balance is the natural ability to feel body position and steadiness.","zh":"天生的平衡感是感覺身體位置和穩定性的自然能力。"},{"en":"A child uses an innate sense of balance when learning to walk.","zh":"孩子學走路時使用天生的平衡感。"},{"en":"This sense helps us notice whether ground rises, falls, or stays level.","zh":"這種感覺幫助我們注意地面是上升、下降還是保持水平。"},{"en":"The phrase describes a built-in ability, not a learned rule.","zh":"這個短語描述內建能力，而不是學來的規則。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":15},{"front":"determine the ground’s inclination","meaning":"判斷地面的傾斜度","examples":[{"en":"Balance helps us determine the ground’s inclination.","zh":"平衡感幫助我們判斷地面的傾斜度。"},{"en":"To determine the ground’s inclination means to judge how much the ground slopes.","zh":"“Determine the ground’s inclination” 指判斷地面傾斜多少。"},{"en":"A builder must determine the ground’s inclination before laying a floor.","zh":"建築工人在鋪地板前必須判斷地面的傾斜度。"},{"en":"If visual cues are misleading, people may fail to determine the ground’s true inclination.","zh":"如果視覺線索具誤導性，人們可能無法判斷地面的真實傾斜度。"},{"en":"The phrase describes judging the angle of land.","zh":"這個短語描述判斷土地角度。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":15},{"front":"misleading visual stimuli","meaning":"誤導性的視覺刺激","examples":[{"en":"Misleading visual stimuli can override our sense of balance.","zh":"誤導性的視覺刺激可以凌駕我們的平衡感。"},{"en":"Misleading visual stimuli are sights that push the brain toward an incorrect interpretation.","zh":"誤導性的視覺刺激是把大腦推向錯誤解讀的視覺景象。"},{"en":"Slanted trees and hidden horizons can be misleading visual stimuli.","zh":"傾斜樹木和隱藏地平線可以是誤導性的視覺刺激。"},{"en":"If misleading visual stimuli are strong, people may trust their eyes over their body balance.","zh":"如果誤導性的視覺刺激很強，人們可能相信眼睛多於身體平衡感。"},{"en":"The phrase describes visual cues that create mistaken judgement.","zh":"這個短語描述造成錯誤判斷的視覺線索。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":15},{"front":"the lack of a horizon","meaning":"缺乏地平線","examples":[{"en":"The lack of a horizon can make the slope hard to judge.","zh":"缺乏地平線可以令斜坡難以判斷。"},{"en":"The lack of a horizon means there is no clear line where land or sea meets the sky.","zh":"缺乏地平線指沒有清晰的陸地或海面與天空相接的線。"},{"en":"In a dense forest, the lack of a horizon may make direction and slope less obvious.","zh":"在茂密森林中，缺乏地平線可能令方向和坡度不明顯。"},{"en":"If there is no horizon, surrounding objects may become misleading reference points.","zh":"如果沒有地平線，周圍物件可能變成誤導性參照物。"},{"en":"The phrase explains why perspective becomes uncertain.","zh":"這個短語解釋為何透視感變得不確定。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":15},{"front":"override that ability","meaning":"凌駕那種能力","examples":[{"en":"Misleading visual cues can override the ability to judge slope.","zh":"誤導性視覺線索可以凌駕判斷坡度的能力。"},{"en":"To override that ability means to overpower or block that ability.","zh":"“Override that ability” 指壓過或阻礙那種能力。"},{"en":"Fear can override a student’s ability to think calmly during an exam.","zh":"恐懼可以在考試中凌駕學生冷靜思考的能力。"},{"en":"If visual information overrides balance, people may misread the ground’s direction.","zh":"如果視覺資料凌駕平衡感，人們可能誤讀地面方向。"},{"en":"The phrase shows one influence becoming stronger than another.","zh":"這個短語顯示一種影響變得比另一種更強。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":16},{"front":"especially when","meaning":"尤其當……時","examples":[{"en":"The illusion is stronger especially when the gradient is gentle.","zh":"這種錯覺更強，尤其當坡度平緩時。"},{"en":"Especially when means particularly in the situation where something happens.","zh":"“Especially when” 指尤其在某情況發生時。"},{"en":"Students need clear instructions, especially when the task is new.","zh":"學生需要清晰指示，尤其當任務是新的時。"},{"en":"A slope illusion may be stronger especially when the real slope is slight.","zh":"斜坡錯覺可能更強，尤其當真實坡度很輕微時。"},{"en":"The phrase highlights a condition that matters most.","zh":"這個短語突出最重要的條件。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":16},{"front":"the gradient is gentle","meaning":"坡度平緩","examples":[{"en":"The illusion can be stronger when the gradient is gentle.","zh":"當坡度平緩時，錯覺可能更強。"},{"en":"The gradient is gentle means the slope rises or falls only slightly.","zh":"“The gradient is gentle” 指斜坡只輕微上升或下降。"},{"en":"A gentle gradient is easier to walk up than a steep hill.","zh":"平緩坡度比陡峭山坡更容易走上去。"},{"en":"If the gradient is gentle, people may not feel the slope clearly through balance.","zh":"如果坡度平緩，人們可能無法透過平衡感清楚感覺斜度。"},{"en":"The phrase describes a small change in height over distance.","zh":"這個短語描述距離中的高度變化很小。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":16},{"front":"answer the questions below","meaning":"回答以下問題","examples":[{"en":"Students answer the questions below using words from the passage.","zh":"學生使用文章中的詞語回答以下問題。"},{"en":"Answer the questions below means respond to the questions written after the instruction.","zh":"“Answer the questions below” 指回答指示後列出的問題。"},{"en":"In a reading test, students should answer the questions below with information from the text.","zh":"在閱讀測驗中，學生應使用文本資料回答以下問題。"},{"en":"If students ignore the word limit, their answers may be marked wrong.","zh":"如果學生忽略字數限制，答案可能被判錯。"},{"en":"The phrase is a standard exam instruction.","zh":"這個短語是標準考試指示。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":16},{"front":"choose no more than three words","meaning":"選擇不多於三個字","examples":[{"en":"Students choose no more than three words from the passage.","zh":"學生從文章中選擇不多於三個字。"},{"en":"Choose no more than three words means the answer must contain three words or fewer.","zh":"“Choose no more than three words” 指答案必須包含三個字或更少。"},{"en":"If the limit is three words, “the visual system” is acceptable but four words are not.","zh":"如果限制是三個字，“the visual system” 可以接受，但四個字不可以。"},{"en":"Students may lose marks for giving the right idea in too many words.","zh":"如果學生用太多字表達正確意思，也可能失分。"},{"en":"The phrase gives a strict answer limit.","zh":"這個短語給出嚴格答案限制。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":16},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must come from the passage.","zh":"答案必須從文章中找出。"},{"en":"From the passage means using words or information found in the reading text.","zh":"“From the passage” 指使用閱讀文本中的詞語或資料。"},{"en":"Students should not use outside knowledge when the answer must come from the passage.","zh":"當答案必須從文章中找出時，學生不應使用外部知識。"},{"en":"If a word is not in the passage, it may not be accepted in a completion task.","zh":"如果某詞不在文章中，它在填充題中可能不被接受。"},{"en":"The phrase reminds candidates to rely on the text.","zh":"這個短語提醒考生依賴文本。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":16},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生把答案寫在答題紙上。"},{"en":"An answer sheet is the paper or form where candidates record their answers.","zh":"答題紙是考生記錄答案的紙張或表格。"},{"en":"In exams, students should check the answer sheet before time runs out.","zh":"在考試中，學生應在時間結束前檢查答題紙。"},{"en":"If an answer is written in the wrong box, the answer sheet may be marked incorrectly.","zh":"如果答案寫在錯誤方格中，答題紙可能被錯誤評分。"},{"en":"The phrase refers to the official place for exam responses.","zh":"這個短語指考試作答的正式位置。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":16},{"front":"interference with","meaning":"對……的干擾","examples":[{"en":"The question asks about interference with neurone activity.","zh":"題目問對神經元活動的干擾。"},{"en":"Interference with something means disruption that prevents it from working normally.","zh":"“Interference with” 某事指妨礙它正常運作的干擾。"},{"en":"Loud noise can cause interference with a phone call.","zh":"嘈雜聲可以對電話通話造成干擾。"},{"en":"If a chemical causes interference with brain signals, perception may change.","zh":"如果化學物質對腦部訊號造成干擾，感知可能改變。"},{"en":"The phrase describes something getting in the way of a normal process.","zh":"這個短語描述某事阻礙正常過程。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":16},{"front":"at a cognitive level","meaning":"在認知層面","examples":[{"en":"Knowledge and experience influence processing at a cognitive level.","zh":"知識和經驗在認知層面影響處理。"},{"en":"At a cognitive level means in the area of thinking, understanding, and interpretation.","zh":"“At a cognitive level” 指在思考、理解和解讀的層面。"},{"en":"A student may know a word at a cognitive level before using it fluently in speech.","zh":"學生可能先在認知層面知道一個詞，之後才在說話中流利使用它。"},{"en":"If an illusion works at a cognitive level, the mind’s assumptions are involved.","zh":"如果錯覺在認知層面運作，心智假設就會參與其中。"},{"en":"The phrase contrasts thinking processes with purely physical reactions.","zh":"這個短語把思考過程與純粹身體反應作對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":16},{"front":"process information","meaning":"處理資料","examples":[{"en":"People process information using knowledge and experience.","zh":"人們使用知識和經驗處理資料。"},{"en":"To process information means to receive, organise, interpret, and use data.","zh":"“Process information” 指接收、組織、解讀和使用資料。"},{"en":"Students process information better when notes are clear and examples are concrete.","zh":"當筆記清晰且例子具體時，學生能更好處理資料。"},{"en":"If the brain processes visual information wrongly, an illusion may result.","zh":"如果大腦錯誤處理視覺資料，就可能產生錯覺。"},{"en":"The phrase describes active mental handling of input.","zh":"這個短語描述對輸入的主動心理處理。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":16},{"front":"holds that","meaning":"主張；認為","examples":[{"en":"Direct realism holds that people perceive the world as it is.","zh":"直接實在論主張人們如實感知世界。"},{"en":"Holds that means believes or claims that something is true.","zh":"“Holds that” 指相信或主張某事為真。"},{"en":"The school policy holds that all students should arrive before 8:00.","zh":"學校政策規定所有學生應在8點前到達。"},{"en":"If a theory holds that sight is direct, illusions create a serious challenge.","zh":"如果一個理論主張視覺是直接的，錯覺就構成嚴重挑戰。"},{"en":"The phrase is formal and common in academic writing.","zh":"這個短語較正式，常見於學術寫作。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":16},{"front":"perceive the world exactly as it is","meaning":"如實感知世界","examples":[{"en":"The theory claims that people perceive the world exactly as it is.","zh":"該理論聲稱人們如實感知世界。"},{"en":"To perceive the world exactly as it is means to see reality without distortion or interpretation.","zh":"“Perceive the world exactly as it is” 指不經扭曲或解讀地看見現實。"},{"en":"A person may believe they perceive the world exactly as it is until an illusion proves otherwise.","zh":"一個人可能相信自己如實感知世界，直到錯覺證明並非如此。"},{"en":"If people truly perceived the world exactly as it is, optical illusions would be hard to explain.","zh":"如果人們真的如實感知世界，視覺錯覺就很難解釋。"},{"en":"The phrase expresses the main claim of direct realism.","zh":"這個短語表達直接實在論的主要主張。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":17},{"front":"classify each statement as","meaning":"把每項陳述分類為","examples":[{"en":"Students classify each statement as relating to one type of illusion.","zh":"學生把每項陳述分類為關於某一類錯覺。"},{"en":"To classify each statement as something means to place every statement into the correct category.","zh":"“Classify each statement as” 某類指把每項陳述放入正確類別。"},{"en":"A teacher may ask students to classify each sentence as fact, opinion, or example.","zh":"老師可能要求學生把每句分類為事實、意見或例子。"},{"en":"If students classify each statement correctly, they understand the differences between illusion types.","zh":"如果學生正確分類每項陳述，就理解錯覺類型之間的差異。"},{"en":"The phrase is common in matching and categorisation questions.","zh":"這個短語常見於配對和分類題。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":17},{"front":"relating to","meaning":"關於；涉及","examples":[{"en":"The statement may relate to fictional, paradox, distorting or ambiguous illusions.","zh":"該陳述可能關於虛構、悖論、扭曲或模稜兩可錯覺。"},{"en":"Relating to means connected with or about something.","zh":"“Relating to” 指與某事有關或關於某事。"},{"en":"A notice relating to school fees should be sent to parents clearly.","zh":"關於學費的通告應清楚發給家長。"},{"en":"If a statement relates to judgement of length, it may belong to distorting illusions.","zh":"如果陳述涉及長度判斷，它可能屬於扭曲錯覺。"},{"en":"The phrase identifies the topic or connection.","zh":"這個短語指出題目或關聯。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":17},{"front":"may be perceived differently","meaning":"可能被不同地感知","examples":[{"en":"Some illusions may be perceived differently by people from different backgrounds.","zh":"一些錯覺可能被來自不同背景的人不同地感知。"},{"en":"May be perceived differently means may be seen or understood in different ways.","zh":"“May be perceived differently” 指可能被以不同方式看見或理解。"},{"en":"A joke may be perceived differently by children and adults.","zh":"笑話可能被孩子和成年人不同地感知。"},{"en":"If culture shapes vision, an illusion may be perceived differently across societies.","zh":"如果文化塑造視覺，錯覺可能在不同社會中被不同地感知。"},{"en":"The phrase stresses possible variation in interpretation.","zh":"這個短語強調解讀上的可能差異。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":17},{"front":"ethnic backgrounds","meaning":"種族背景","examples":[{"en":"People from different ethnic backgrounds may respond differently to some illusions.","zh":"來自不同種族背景的人可能對某些錯覺有不同反應。"},{"en":"Ethnic backgrounds are people’s cultural, ancestral, or community origins.","zh":"種族背景是人們的文化、祖先或社群來源。"},{"en":"Students from different ethnic backgrounds may celebrate different festivals at home.","zh":"來自不同種族背景的學生可能在家中慶祝不同節日。"},{"en":"If ethnic backgrounds affect experience, they may also influence visual interpretation.","zh":"如果種族背景影響經驗，它們也可能影響視覺解讀。"},{"en":"The phrase is used when comparing groups with different cultural origins.","zh":"這個短語用於比較不同文化來源的群體。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":17},{"front":"override our natural ability","meaning":"凌駕我們的自然能力","examples":[{"en":"Misleading visual stimuli may override our natural ability to judge slopes.","zh":"誤導性的視覺刺激可能凌駕我們判斷斜坡的自然能力。"},{"en":"To override our natural ability means to overpower a built-in skill or instinct.","zh":"“Override our natural ability” 指壓過一種天生技能或本能。"},{"en":"Panic can override our natural ability to speak clearly.","zh":"恐慌可以凌駕我們清楚說話的自然能力。"},{"en":"If visual cues override our natural ability to sense balance, slopes may be misread.","zh":"如果視覺線索凌駕我們感受平衡的自然能力，斜坡可能被誤讀。"},{"en":"The phrase shows one force blocking a normal human capacity.","zh":"這個短語顯示一種力量阻礙正常人類能力。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":17},{"front":"make rational judgements","meaning":"作出理性判斷","examples":[{"en":"Some illusions affect our ability to make rational judgements.","zh":"一些錯覺影響我們作出理性判斷的能力。"},{"en":"To make rational judgements means to decide based on reason, evidence, and logic.","zh":"“Make rational judgements” 指基於理由、證據和邏輯作決定。"},{"en":"A shopper makes rational judgements by comparing price, need, and quality.","zh":"購物者透過比較價格、需要和品質作出理性判斷。"},{"en":"If an illusion makes the impossible seem real, rational judgement becomes harder.","zh":"如果錯覺令不可能的事物看似真實，理性判斷會變得更困難。"},{"en":"The phrase contrasts careful thinking with emotional or visual confusion.","zh":"這個短語把謹慎思考與情緒或視覺混亂作對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":17},{"front":"may be interpreted differently","meaning":"可能被不同地解讀","examples":[{"en":"Ambiguous illusions may be interpreted differently by the same person.","zh":"模稜兩可錯覺可能被同一個人不同地解讀。"},{"en":"May be interpreted differently means may be understood in more than one way.","zh":"“May be interpreted differently” 指可能以多於一種方式理解。"},{"en":"A message without tone may be interpreted differently by different readers.","zh":"沒有語氣的信息可能被不同讀者不同地解讀。"},{"en":"If the same person switches views, an image may be interpreted differently over time.","zh":"如果同一人切換看法，影像可能隨時間被不同地解讀。"},{"en":"The phrase highlights flexible meaning.","zh":"這個短語強調意思的靈活性。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":17},{"front":"result from chemical stimulation","meaning":"由化學刺激引起","examples":[{"en":"Fictional illusions may result from chemical stimulation.","zh":"虛構錯覺可能由化學刺激引起。"},{"en":"To result from chemical stimulation means to be caused by chemicals affecting the body or brain.","zh":"“Result from chemical stimulation” 指由化學物質影響身體或大腦而造成。"},{"en":"Some medicines can result in unusual feelings if they stimulate the nervous system.","zh":"如果某些藥物刺激神經系統，可能導致不尋常感覺。"},{"en":"If a hallucination results from chemical stimulation, the cause is biological rather than a normal visual trick.","zh":"如果幻覺由化學刺激引起，其原因是生物性的，而不是普通視覺把戲。"},{"en":"The phrase links chemicals with changes in perception.","zh":"這個短語把化學物質與感知變化連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":17},{"front":"question the validity of","meaning":"質疑……的有效性","examples":[{"en":"The Necker cube has been used to question the validity of direct realism.","zh":"內克爾立方體曾被用來質疑直接實在論的有效性。"},{"en":"To question the validity of something means to doubt whether it is correct or reliable.","zh":"“Question the validity of” 某事指懷疑它是否正確或可靠。"},{"en":"A scientist may question the validity of a study if the sample size is too small.","zh":"如果樣本太小，科學家可能質疑研究的有效性。"},{"en":"If an illusion shows perception can change, it questions the validity of theories claiming direct sight.","zh":"如果錯覺顯示感知可以改變，它就質疑聲稱視覺直接反映現實的理論的有效性。"},{"en":"The phrase is formal and used for challenging ideas or evidence.","zh":"這個短語較正式，用於挑戰想法或證據。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":17},{"front":"arguments in another field","meaning":"另一領域的論證","examples":[{"en":"An illusion can be used to question arguments in another field.","zh":"錯覺可以被用來質疑另一領域的論證。"},{"en":"Arguments in another field are claims or debates from a different area of study.","zh":"另一領域的論證是來自不同研究範疇的主張或辯論。"},{"en":"A maths example may help explain arguments in philosophy or economics.","zh":"數學例子可能幫助解釋哲學或經濟學中的論證。"},{"en":"If a visual illusion is used in epistemology, it supports arguments in another field.","zh":"如果視覺錯覺被用於知識論，它就支持另一領域的論證。"},{"en":"The phrase shows that evidence can travel across subjects.","zh":"這個短語顯示證據可以跨學科使用。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":17},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter for each answer.","zh":"學生為每個答案選出正確字母。"},{"en":"Choose the correct letter means select the answer option marked by the right letter.","zh":"“Choose the correct letter” 指選出由正確字母標示的答案選項。"},{"en":"In multiple-choice questions, students should write A, B, C, or D clearly.","zh":"在選擇題中，學生應清楚寫出 A、B、C 或 D。"},{"en":"If students choose the correct letter but put it in the wrong box, they may lose marks.","zh":"如果學生選出正確字母但放在錯誤方格中，可能會失分。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":18},{"front":"according to","meaning":"根據","examples":[{"en":"According to the passage, fictional illusions are subjective.","zh":"根據文章，虛構錯覺是主觀的。"},{"en":"According to means as stated by or based on a particular source.","zh":"“According to” 指根據某個來源所述。"},{"en":"According to the timetable, the train leaves at 8:15.","zh":"根據時間表，火車在8:15開出。"},{"en":"In reading exams, answers should be based on the passage, not personal opinion.","zh":"在閱讀考試中，答案應根據文章，而不是個人意見。"},{"en":"The phrase tells readers where the information comes from.","zh":"這個短語告訴讀者資料來源。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":18},{"front":"may eventually lead to","meaning":"可能最終導致","examples":[{"en":"The option asks whether fictional illusions may eventually lead to schizophrenia.","zh":"該選項問虛構錯覺是否可能最終導致精神分裂症。"},{"en":"May eventually lead to means may cause something to happen later after a period of time.","zh":"“May eventually lead to” 指可能在一段時間後造成某事發生。"},{"en":"Poor sleep may eventually lead to health problems if it continues for years.","zh":"如果長期持續，睡眠不足可能最終導致健康問題。"},{"en":"A question using “may eventually lead to” asks about a possible long-term result.","zh":"使用 “may eventually lead to” 的題目詢問可能的長期結果。"},{"en":"The phrase describes a future consequence, not an immediate effect.","zh":"這個短語描述未來後果，而不是即時效果。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":18},{"front":"completely subjective","meaning":"完全主觀的","examples":[{"en":"Fictional illusions are completely subjective experiences.","zh":"虛構錯覺是完全主觀的經驗。"},{"en":"Completely subjective means based entirely on one person’s private experience or perception.","zh":"“Completely subjective” 指完全基於一個人的私人經驗或感知。"},{"en":"Taste in music is often subjective because different people enjoy different sounds.","zh":"音樂品味通常是主觀的，因為不同人喜歡不同聲音。"},{"en":"If an illusion is completely subjective, others may not be able to see or verify it.","zh":"如果錯覺完全主觀，其他人可能不能看見或驗證它。"},{"en":"The phrase contrasts personal experience with shared objective evidence.","zh":"這個短語把個人經驗與共同客觀證據作對比。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":18},{"front":"very similar to","meaning":"與……非常相似","examples":[{"en":"The option asks whether fictional illusions are very similar to paradox illusions.","zh":"該選項問虛構錯覺是否與悖論錯覺非常相似。"},{"en":"Very similar to means almost the same as something else in important ways.","zh":"“Very similar to” 指在重要方面幾乎與另一事物相同。"},{"en":"Two phones may look very similar to each other but have different batteries.","zh":"兩部手機可能看起來非常相似，但電池不同。"},{"en":"If two illusion types are very similar, students may confuse their definitions.","zh":"如果兩種錯覺類型非常相似，學生可能混淆其定義。"},{"en":"The phrase compares closeness in form, meaning, or function.","zh":"這個短語比較形式、意思或功能上的接近程度。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":18},{"front":"typical of","meaning":"是……的典型","examples":[{"en":"The option asks whether fictional illusions are typical of cognitive illusions.","zh":"該選項問虛構錯覺是否是認知錯覺的典型。"},{"en":"Typical of something means showing the usual features of that group or situation.","zh":"“Typical of” 某事指顯示該群體或情況的通常特徵。"},{"en":"Heavy homework before exams is typical of many schools.","zh":"考試前功課繁重是許多學校的典型情況。"},{"en":"If hallucination-like experiences are not typical of cognitive illusions, classification may be misleading.","zh":"如果類似幻覺的經驗不是認知錯覺的典型，分類就可能具誤導性。"},{"en":"The phrase asks whether something is representative.","zh":"這個短語詢問某事是否具有代表性。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":18},{"front":"according to ambiguous-illusion theory","meaning":"根據模稜兩可錯覺理論","examples":[{"en":"According to ambiguous-illusion theory, the Necker cube can be seen in different ways.","zh":"根據模稜兩可錯覺理論，內克爾立方體可以用不同方式觀看。"},{"en":"According to ambiguous-illusion theory means based on the explanation of illusions with multiple interpretations.","zh":"“According to ambiguous-illusion theory” 指根據對具有多重解讀錯覺的解釋。"},{"en":"According to this theory, one image can support more than one reasonable perception.","zh":"根據這個理論，一個影像可以支持多於一種合理感知。"},{"en":"If the Necker cube changes in the viewer’s mind, ambiguous-illusion theory explains why.","zh":"如果內克爾立方體在觀看者心中改變，模稜兩可錯覺理論可解釋原因。"},{"en":"The phrase links an example to a specific theory.","zh":"這個短語把例子與特定理論連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":18},{"front":"tend to view objects from above","meaning":"傾向從上方觀看物件","examples":[{"en":"People tend to view objects from above.","zh":"人們傾向從上方觀看物件。"},{"en":"Tend to view objects from above means usually or habitually see things from a slightly higher position.","zh":"“Tend to view objects from above” 指通常或習慣從稍高位置看東西。"},{"en":"Adults tend to view children’s toys from above because they are taller.","zh":"成年人因為較高，通常傾向從上方觀看孩子的玩具。"},{"en":"If people tend to view objects from above, they may interpret cube drawings in a predictable way.","zh":"如果人們傾向從上方觀看物件，他們可能以可預測方式解讀立方體圖。"},{"en":"The phrase describes a common viewing habit.","zh":"這個短語描述常見觀看習慣。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":18},{"front":"represents","meaning":"代表；顯示","examples":[{"en":"The question asks which diagram represents the Müller-Lyer illusion.","zh":"題目問哪個圖代表繆勒－萊爾錯覺。"},{"en":"Represents means shows, stands for, or is an example of something.","zh":"“Represents” 指顯示、代表或作為某事的例子。"},{"en":"A red cross often represents medical help.","zh":"紅十字通常代表醫療援助。"},{"en":"If a diagram represents an illusion, it should contain the key visual features of that illusion.","zh":"如果圖表代表某種錯覺，它應包含該錯覺的關鍵視覺特徵。"},{"en":"The word is useful when matching images with ideas.","zh":"這個詞適合用於把影像與想法配對。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":18},{"front":"a model that","meaning":"一個……的模型","examples":[{"en":"The Penrose Stairs are a model that illustrates an impossible object.","zh":"彭羅斯階梯是一個說明不可能物件的模型。"},{"en":"A model that does something is an example or structure designed to show a particular idea.","zh":"“A model that” 做某事，指為展示特定想法而設計的例子或結構。"},{"en":"A globe is a model that helps students understand Earth’s shape.","zh":"地球儀是一個幫助學生理解地球形狀的模型。"},{"en":"If a model illustrates an impossible object, it helps viewers see the paradox clearly.","zh":"如果模型說明不可能物件，它能幫助觀看者清楚看見悖論。"},{"en":"The phrase introduces the purpose of a model.","zh":"這個短語引出模型的用途。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":18},{"front":"persuade viewers that","meaning":"使觀看者相信","examples":[{"en":"The model can persuade viewers that they are seeing something impossible.","zh":"該模型可以使觀看者相信他們正在看見不可能的東西。"},{"en":"To persuade viewers that something is true means to make them believe it through what they see.","zh":"“Persuade viewers that” 某事為真，指透過他們所見令他們相信它。"},{"en":"A realistic film scene can persuade viewers that a fictional city exists.","zh":"逼真的電影場景可以使觀看者相信虛構城市存在。"},{"en":"If a paradox illusion persuades viewers that an impossible object is real, the image is powerful.","zh":"如果悖論錯覺使觀看者相信不可能物件是真實的，該影像就很有力量。"},{"en":"The phrase connects visual design with belief.","zh":"這個短語把視覺設計與信念連繫起來。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":18},{"front":"seeing something impossible","meaning":"看見不可能的事物","examples":[{"en":"Paradox illusions can make people believe they are seeing something impossible.","zh":"悖論錯覺可以令人相信自己正在看見不可能的事物。"},{"en":"Seeing something impossible means visually experiencing something that cannot exist in physical reality.","zh":"“Seeing something impossible” 指在視覺上經歷物理現實中不能存在的東西。"},{"en":"A staircase that returns to its start while always rising feels like seeing something impossible.","zh":"一條一直上升卻回到起點的樓梯，感覺就像看見不可能的事物。"},{"en":"If viewers think they are seeing something impossible, logic and vision are in conflict.","zh":"如果觀看者以為自己看見不可能的事物，邏輯和視覺就發生衝突。"},{"en":"The phrase captures the effect of paradox illusions.","zh":"這個短語捕捉悖論錯覺的效果。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":19},{"front":"disproved established theories","meaning":"推翻既定理論","examples":[{"en":"The option asks whether the model has disproved established theories of knowledge.","zh":"該選項問該模型是否推翻既定知識理論。"},{"en":"Disproved established theories means shown that widely accepted theories are false.","zh":"“Disproved established theories” 指證明被廣泛接受的理論是錯的。"},{"en":"A single classroom mistake does not disprove established theories about learning.","zh":"單一課堂錯誤並不會推翻關於學習的既定理論。"},{"en":"If an illusion only challenges a theory, it has not necessarily disproved it.","zh":"如果錯覺只是挑戰一個理論，它不一定已經推翻該理論。"},{"en":"The phrase is strong and requires clear evidence.","zh":"這個短語語氣強，需要清晰證據。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":19},{"front":"established theories of knowledge","meaning":"既定知識理論","examples":[{"en":"Epistemology deals with theories of knowledge.","zh":"知識論處理知識理論。"},{"en":"Established theories of knowledge are widely recognised explanations about how people know things.","zh":"既定知識理論是關於人如何知道事情的廣泛認可解釋。"},{"en":"A philosophy course may compare established theories of knowledge with newer ideas.","zh":"哲學課可能比較既定知識理論與較新想法。"},{"en":"If perception can mislead us, established theories of knowledge may need careful examination.","zh":"如果感知可以誤導我們，既定知識理論可能需要仔細檢視。"},{"en":"The phrase belongs to philosophy and debates about knowing.","zh":"這個短語屬於哲學和關於認知的辯論。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":19},{"front":"naturally occurring paradox illusion","meaning":"自然出現的悖論錯覺","examples":[{"en":"The option asks whether the Penrose Stairs are a naturally occurring paradox illusion.","zh":"該選項問彭羅斯階梯是否是自然出現的悖論錯覺。"},{"en":"A naturally occurring paradox illusion would be an impossible-looking illusion found in nature or real surroundings.","zh":"自然出現的悖論錯覺，是在自然或真實環境中發現的看似不可能錯覺。"},{"en":"Gravity hills may be natural illusions, but the Penrose Stairs are designed models.","zh":"怪坡可能是自然錯覺，但彭羅斯階梯是被設計的模型。"},{"en":"If something is naturally occurring, it is not simply drawn or invented by an artist.","zh":"如果某物是自然出現的，它就不是單純由藝術家繪畫或發明的。"},{"en":"The phrase combines real-world occurrence with paradoxical appearance.","zh":"這個短語結合現實世界出現與悖論外觀。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":19},{"front":"several locations around the world","meaning":"世界各地幾個地點","examples":[{"en":"Gravity hills can be seen in several locations around the world.","zh":"怪坡可以在世界各地幾個地點看見。"},{"en":"Several locations around the world means a number of places in different countries or regions.","zh":"“Several locations around the world” 指不同國家或地區中的若干地方。"},{"en":"Similar street markets can be found in several locations around the world.","zh":"相似街市可以在世界各地幾個地點找到。"},{"en":"If gravity hills exist in several locations, the illusion depends on common visual conditions.","zh":"如果怪坡存在於幾個地點，這種錯覺就依賴常見視覺條件。"},{"en":"The phrase shows that a phenomenon is geographically widespread.","zh":"這個短語顯示現象在地理上分布廣泛。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":19},{"front":"occurrences on gravity hills","meaning":"怪坡上的現象","examples":[{"en":"Occurrences on gravity hills result from misleading visual cues.","zh":"怪坡上的現象由誤導性視覺線索引起。"},{"en":"Occurrences on gravity hills are the strange events or effects observed at those sites.","zh":"怪坡上的現象是在那些地點觀察到的奇怪事件或效果。"},{"en":"A car appearing to roll uphill is one of the occurrences on gravity hills.","zh":"汽車看似向上坡滾動是怪坡上的現象之一。"},{"en":"These occurrences happen because observers misread the slope of the land.","zh":"這些現象出現，是因為觀察者誤讀土地坡度。"},{"en":"The phrase refers to what people see happening at gravity hills.","zh":"這個短語指人們在怪坡看見發生的事。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":19},{"front":"mineral content of the soil","meaning":"土壤礦物含量","examples":[{"en":"The option asks whether the effect is caused by mineral content of the soil.","zh":"該選項問這種效果是否由土壤礦物含量造成。"},{"en":"Mineral content of the soil means the minerals present in the ground.","zh":"土壤礦物含量指地面中存在的礦物質。"},{"en":"Farmers test the mineral content of the soil before choosing fertiliser.","zh":"農民在選擇肥料前會測試土壤礦物含量。"},{"en":"In the passage, the gravity-hill effect is not explained by mineral content but by visual perspective.","zh":"在文章中，怪坡效果不是由礦物含量解釋，而是由視覺透視解釋。"},{"en":"The phrase refers to soil chemistry, not visual reference points.","zh":"這個短語指土壤化學，而不是視覺參照點。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":19},{"front":"cannot currently explain","meaning":"目前無法解釋","examples":[{"en":"The option suggests that science cannot currently explain the phenomenon.","zh":"該選項暗示科學目前無法解釋該現象。"},{"en":"Cannot currently explain means does not have an explanation at the present time.","zh":"“Cannot currently explain” 指目前沒有解釋。"},{"en":"Doctors may not currently explain every symptom until more tests are done.","zh":"在做更多檢查前，醫生可能目前無法解釋每個症狀。"},{"en":"If science can explain gravity hills through perspective, it is wrong to say it cannot currently explain them.","zh":"如果科學能透過透視解釋怪坡，說它目前無法解釋就是錯的。"},{"en":"The phrase describes a present limit in understanding.","zh":"這個短語描述目前理解上的限制。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":19},{"front":"misleading natural reference points","meaning":"誤導性的自然參照物","examples":[{"en":"Misleading natural reference points can confuse observers.","zh":"誤導性的自然參照物可以令觀察者混亂。"},{"en":"Misleading natural reference points are natural objects, such as trees or hills, that give a wrong sense of direction or level.","zh":"誤導性的自然參照物是樹木或山丘等自然物件，會給出錯誤方向或水平感。"},{"en":"Tilted trees can become misleading natural reference points on a sloping road.","zh":"傾斜樹木可以成為斜坡道路上的誤導性自然參照物。"},{"en":"If observers trust misleading natural reference points, they may think downhill is uphill.","zh":"如果觀察者相信誤導性的自然參照物，可能以為下坡是上坡。"},{"en":"The phrase explains how the environment can trick perception.","zh":"這個短語解釋環境如何欺騙感知。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":19},{"front":"rising slopes","meaning":"上坡","examples":[{"en":"The option refers to rising slopes being misinterpreted.","zh":"該選項提到上坡被誤解。"},{"en":"Rising slopes are surfaces or roads that go upward from a lower point to a higher point.","zh":"上坡是由較低位置上升至較高位置的表面或道路。"},{"en":"Cyclists slow down on rising slopes because they must work against gravity.","zh":"單車手在上坡會放慢，因為他們必須對抗重力。"},{"en":"In gravity-hill illusions, people may confuse real downward slopes with rising slopes.","zh":"在怪坡錯覺中，人們可能把真正的下坡與上坡混淆。"},{"en":"The phrase describes upward land direction.","zh":"這個短語描述向上的地面方向。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":19},{"front":"misinterpreted as","meaning":"被誤解為","examples":[{"en":"Some slopes may be misinterpreted as going uphill.","zh":"一些斜坡可能被誤解為向上坡。"},{"en":"Misinterpreted as means wrongly understood or seen as something else.","zh":"“Misinterpreted as” 指被錯誤理解或看成另一事物。"},{"en":"A quiet student may be misinterpreted as rude when he is only shy.","zh":"安靜學生可能被誤解為無禮，但他其實只是害羞。"},{"en":"If a downhill road is misinterpreted as uphill, rolling objects seem to behave impossibly.","zh":"如果下坡路被誤解為上坡，滾動物件就看似不可能地運作。"},{"en":"The phrase describes an incorrect reading of a situation.","zh":"這個短語描述對情況的錯誤解讀。"}],"source":"119 - CAN WE BELIEVE OUR OWN EYES?.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 120":[{"front":"psychology of new product adoption","meaning":"新產品採用心理","examples":[{"en":"The passage examines the psychology of new product adoption.","zh":"文章探討新產品採用心理。"},{"en":"The psychology of new product adoption means how people think and feel when deciding whether to use a new product.","zh":"新產品採用心理指人們在決定是否使用新產品時的想法和感受。"},{"en":"A student may like a new study app but still avoid it because the old notebook feels safer.","zh":"學生可能喜歡一個新的學習應用程式，但仍避開它，因為舊筆記本感覺更安全。"},{"en":"If companies ignore the psychology of new product adoption, even useful inventions may fail.","zh":"如果公司忽視新產品採用心理，即使有用的發明也可能失敗。"},{"en":"This phrase focuses on consumer attitudes, habits, fear of loss, and willingness to change.","zh":"這個片語聚焦於消費者態度、習慣、對損失的恐懼，以及改變意願。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":1},{"front":"hypercompetitive marketplace","meaning":"競爭極度激烈的市場","examples":[{"en":"Companies operate in today’s hypercompetitive marketplace.","zh":"公司在今日競爭極度激烈的市場中運作。"},{"en":"A hypercompetitive marketplace is a business environment where many firms fight intensely for customers.","zh":"競爭極度激烈的市場是許多企業激烈爭奪顧客的商業環境。"},{"en":"In a hypercompetitive marketplace, restaurants may change menus quickly to attract diners.","zh":"在競爭極度激烈的市場中，餐廳可能快速更換餐牌以吸引食客。"},{"en":"When competition is extreme, companies must innovate or risk losing market share.","zh":"當競爭極端激烈，公司必須創新，否則可能失去市場佔有率。"},{"en":"This phrase describes a market where ordinary effort may not be enough to survive.","zh":"這個片語描述一個普通努力未必足以生存的市場。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":1},{"front":"successfully introduce new products","meaning":"成功推出新產品","examples":[{"en":"Companies that successfully introduce new products are more likely to flourish.","zh":"成功推出新產品的公司較有可能蓬勃發展。"},{"en":"To successfully introduce new products means to launch new items that customers actually buy and use.","zh":"successfully introduce new products 指推出顧客真正購買和使用的新商品。"},{"en":"A bakery successfully introduces a new cake when regular customers keep coming back for it.","zh":"當常客不斷回來購買新蛋糕，麵包店便成功推出新產品。"},{"en":"If a company understands customer habits, it is more likely to introduce new products successfully.","zh":"如果公司理解顧客習慣，便較有可能成功推出新產品。"},{"en":"This phrase means more than creating a product; it includes acceptance by the market.","zh":"這個片語不只是指創造產品，也包括市場接受。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":1},{"front":"be more likely to flourish","meaning":"較有可能蓬勃發展","examples":[{"en":"Successful innovators are more likely to flourish than their competitors.","zh":"成功創新者比競爭者較有可能蓬勃發展。"},{"en":"To be more likely to flourish means to have a better chance of growing, succeeding, or becoming strong.","zh":"be more likely to flourish 指有較大機會成長、成功或變得強大。"},{"en":"A school with good teachers and clear support is more likely to flourish.","zh":"擁有好老師和清晰支援的學校較有可能蓬勃發展。"},{"en":"If a small business listens to customers, it is more likely to flourish than one that ignores complaints.","zh":"如果小企業聆聽顧客，它比忽視投訴的企業較有可能蓬勃發展。"},{"en":"This phrase suggests a higher chance of long-term success, not a guarantee.","zh":"這個片語暗示較高的長期成功機會，而不是保證。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":1},{"front":"spend billions of dollars","meaning":"花費數十億美元","examples":[{"en":"Businesses spend billions of dollars developing new products.","zh":"企業花費數十億美元開發新產品。"},{"en":"To spend billions of dollars means to use extremely large amounts of money.","zh":"spend billions of dollars 指使用極其龐大的金錢。"},{"en":"Governments may spend billions of dollars building railways, hospitals, and public housing.","zh":"政府可能花費數十億美元興建鐵路、醫院和公共房屋。"},{"en":"If companies spend billions of dollars but misread consumers, the investment may still fail.","zh":"如果公司花費數十億美元卻誤判消費者，投資仍可能失敗。"},{"en":"This phrase stresses the huge financial scale of an activity.","zh":"這個片語強調活動的巨大財務規模。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":1},{"front":"make better mousetraps","meaning":"製造更好的產品；改良產品","examples":[{"en":"Businesses spend money making better mousetraps, but consumers may still reject them.","zh":"企業花錢製造更好的產品，但消費者仍可能拒絕它們。"},{"en":"To make better mousetraps means to improve products or invent supposedly superior ones.","zh":"make better mousetraps 指改良產品或發明理應更優秀的產品。"},{"en":"A phone company may make a better mousetrap by adding a faster camera and longer battery life.","zh":"電話公司可能透過加入更快相機和更長電池續航來改良產品。"},{"en":"If customers dislike changing habits, making better mousetraps alone may not increase sales.","zh":"如果顧客不喜歡改變習慣，單靠改良產品未必能增加銷量。"},{"en":"This phrase is often used ironically when better design does not guarantee success.","zh":"這個片語常帶反諷意味，表示更好設計不保證成功。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":1},{"front":"only to find","meaning":"結果卻發現","examples":[{"en":"Companies develop new products only to find consumers rejecting them.","zh":"公司開發新產品，結果卻發現消費者拒絕它們。"},{"en":"Only to find means that someone does something but then discovers an unexpected or disappointing result.","zh":"only to find 指某人做了某事後，卻發現意想不到或令人失望的結果。"},{"en":"A student studied the wrong chapter, only to find the test covered a different topic.","zh":"學生溫習了錯誤章節，結果卻發現測驗考另一個題目。"},{"en":"A shop may order extra stock only to find customers prefer the old version.","zh":"商店可能訂購額外存貨，結果卻發現顧客較喜歡舊版本。"},{"en":"This phrase often introduces a frustrating surprise after effort.","zh":"這個片語常引入努力之後令人沮喪的意外。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":1},{"front":"roundly reject","meaning":"斷然拒絕；完全不接受","examples":[{"en":"Consumers sometimes roundly reject new products.","zh":"消費者有時會斷然拒絕新產品。"},{"en":"To roundly reject something means to refuse it completely and strongly.","zh":"roundly reject something 指完全而強烈地拒絕某物。"},{"en":"Parents may roundly reject a school rule if they think it is unfair.","zh":"如果家長認為校規不公平，可能會斷然拒絕它。"},{"en":"If customers roundly reject a new design, the company may return to the old model.","zh":"如果顧客完全不接受新設計，公司可能回到舊型號。"},{"en":"This phrase is stronger than simply dislike because it suggests clear refusal.","zh":"這個片語比 simply dislike 更強，因為它暗示清楚拒絕。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":1},{"front":"fail at a stunning rate","meaning":"以驚人的比率失敗","examples":[{"en":"New products fail at a stunning rate in many categories.","zh":"新產品在許多類別中以驚人的比率失敗。"},{"en":"To fail at a stunning rate means to fail very often and in a surprising way.","zh":"fail at a stunning rate 指非常頻繁並令人驚訝地失敗。"},{"en":"New restaurants may fail at a stunning rate if rent is high and customer habits are hard to change.","zh":"如果租金高而顧客習慣難改，新餐廳可能以驚人的比率失敗。"},{"en":"When products fail at a stunning rate, companies must ask why customers resist them.","zh":"當產品以驚人的比率失敗，公司必須問為何顧客抗拒它們。"},{"en":"This phrase stresses both frequency and shock.","zh":"這個片語同時強調頻率和震驚程度。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":1},{"front":"depending on the category","meaning":"視乎類別而定","examples":[{"en":"The failure rate varies depending on the category.","zh":"失敗率視乎類別而有所不同。"},{"en":"Depending on the category means the result changes according to the type of product or group.","zh":"depending on the category 指結果會根據產品或組別類型而改變。"},{"en":"A delivery fee may be different depending on the category of goods ordered.","zh":"送貨費可能視乎訂購貨品類別而不同。"},{"en":"If failure rates depend on the category, snacks and electronics may not face the same risk.","zh":"如果失敗率視乎類別而定，零食和電子產品未必面對相同風險。"},{"en":"This phrase reminds readers that one general number may hide important differences.","zh":"這個片語提醒讀者，一個整體數字可能掩蓋重要差異。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":1},{"front":"the odds haven’t changed much","meaning":"成功機會沒有太大改變","examples":[{"en":"The odds of success haven’t changed much in the past 25 years.","zh":"在過去25年，成功機會沒有太大改變。"},{"en":"The odds haven’t changed much means the chances are still nearly the same as before.","zh":"the odds haven’t changed much 指機會仍然幾乎與以前相同。"},{"en":"Even with new study apps, the odds of passing have not changed much for students who never practise.","zh":"即使有新的學習應用程式，從不練習的學生合格機會也沒有太大改變。"},{"en":"If companies keep making the same mistakes, the odds of success may not change much.","zh":"如果公司繼續犯同樣錯誤，成功機會可能沒有太大改變。"},{"en":"This phrase suggests that time has passed but the basic probability remains similar.","zh":"這個片語暗示時間過去了，但基本概率仍相近。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":1},{"front":"packaged goods industry","meaning":"包裝消費品行業","examples":[{"en":"The U.S. packaged goods industry introduces thousands of products each year.","zh":"美國包裝消費品行業每年推出數以千計產品。"},{"en":"The packaged goods industry sells everyday products packed in boxes, bottles, cans, or bags.","zh":"packaged goods industry 指銷售以盒、瓶、罐或袋包裝的日用品的行業。"},{"en":"Supermarkets depend on the packaged goods industry for snacks, drinks, soap, and cleaning products.","zh":"超級市場依賴包裝消費品行業供應零食、飲品、肥皂和清潔用品。"},{"en":"If a product fails in the packaged goods industry, it may disappear from shelves quickly.","zh":"如果產品在包裝消費品行業中失敗，它可能很快從貨架上消失。"},{"en":"This phrase refers to mass-market consumer goods, not custom-made items.","zh":"這個片語指大眾消費品，而不是訂製產品。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":2},{"front":"for instance","meaning":"例如","examples":[{"en":"For instance, many new products disappear from store shelves quickly.","zh":"例如，許多新產品很快從商店貨架上消失。"},{"en":"For instance means for example and introduces a specific case.","zh":"for instance 意思是「例如」，用來引入具體例子。"},{"en":"Some students learn better with visuals; for instance, diagrams can help them understand grammar.","zh":"有些學生用視覺材料學得更好；例如，圖表可以幫助他們理解文法。"},{"en":"A company may lose customers for several reasons; for instance, service may be slow.","zh":"公司可能因多個原因失去顧客；例如，服務可能很慢。"},{"en":"This phrase helps make a general point clearer with an example.","zh":"這個片語透過例子令一般論點更清楚。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":2},{"front":"introduce products","meaning":"推出產品","examples":[{"en":"Companies introduce 30,000 products every year.","zh":"公司每年推出30,000件產品。"},{"en":"To introduce products means to bring new goods or services into the market.","zh":"introduce products 指把新商品或服務帶入市場。"},{"en":"A café may introduce products like seasonal drinks to attract regular customers.","zh":"咖啡店可能推出季節性飲品等產品，以吸引常客。"},{"en":"If companies introduce products too quickly, they may not understand customer needs well enough.","zh":"如果公司太快推出產品，可能未充分理解顧客需要。"},{"en":"This phrase focuses on launching products, not simply designing them privately.","zh":"這個片語聚焦於推出到市場，而不是私下設計。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":2},{"front":"stay on store shelves","meaning":"留在商店貨架上","examples":[{"en":"Many new products do not stay on store shelves for long.","zh":"許多新產品不能長時間留在商店貨架上。"},{"en":"To stay on store shelves means to continue being sold in shops.","zh":"stay on store shelves 指繼續在商店出售。"},{"en":"A snack will stay on store shelves if customers keep buying it every week.","zh":"如果顧客每星期持續購買某款零食，它就會留在商店貨架上。"},{"en":"If sales are weak, supermarkets may remove a product from store shelves.","zh":"如果銷售疲弱，超級市場可能把產品從貨架上移走。"},{"en":"This phrase shows whether a product survives in retail, not just whether it was launched.","zh":"這個片語顯示產品是否在零售中生存，而不只是是否推出。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":2},{"front":"for more than 12 months","meaning":"超過十二個月","examples":[{"en":"Many products do not stay on store shelves for more than 12 months.","zh":"許多產品不能在商店貨架上停留超過十二個月。"},{"en":"For more than 12 months means for longer than one year.","zh":"for more than 12 months 指長過一年。"},{"en":"A gym membership that lasts for more than 12 months requires long-term commitment.","zh":"持續超過十二個月的健身會籍需要長期承諾。"},{"en":"If a new product cannot survive for more than 12 months, its early sales were probably too weak.","zh":"如果新產品不能生存超過十二個月，它早期銷售很可能太弱。"},{"en":"This phrase gives a clear time threshold.","zh":"這個片語給出清晰時間界線。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":2},{"front":"innovative products","meaning":"創新產品","examples":[{"en":"Most innovative products are also unsuccessful.","zh":"大多數創新產品也不成功。"},{"en":"Innovative products are new or original products that use fresh ideas, designs, or technology.","zh":"innovative products 是使用新想法、新設計或新科技的新穎產品。"},{"en":"A foldable phone was an innovative product because it changed the usual screen design.","zh":"摺疊手機是創新產品，因為它改變了一般螢幕設計。"},{"en":"Innovative products may fail if customers do not see enough reason to change habits.","zh":"如果顧客看不到足夠理由改變習慣，創新產品可能失敗。"},{"en":"This phrase does not automatically mean successful products; innovation and adoption are different.","zh":"這個片語不自動表示成功產品；創新和採用是不同事情。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":2},{"front":"create new product categories","meaning":"創造新的產品類別","examples":[{"en":"Some innovative products create new product categories.","zh":"一些創新產品創造新的產品類別。"},{"en":"To create new product categories means to start a new type of product market.","zh":"create new product categories 指開創一種新的產品市場類型。"},{"en":"The first tablet computers helped create a new product category between phones and laptops.","zh":"早期平板電腦幫助在手機和手提電腦之間創造新的產品類別。"},{"en":"If a product creates a new category, customers may need time to understand why they need it.","zh":"如果產品創造新類別，顧客可能需要時間理解自己為何需要它。"},{"en":"This phrase suggests changing the market structure, not merely improving an old item.","zh":"這個片語暗示改變市場結構，而不只是改良舊產品。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":2},{"front":"revolutionize old ones","meaning":"徹底改變舊有類別","examples":[{"en":"Some products revolutionize old product categories.","zh":"一些產品徹底改變舊有產品類別。"},{"en":"To revolutionize old ones means to change existing categories completely and dramatically.","zh":"revolutionize old ones 指完全而劇烈地改變現有類別。"},{"en":"Online banking revolutionized old banking services by letting people transfer money at home.","zh":"網上銀行讓人們在家轉帳，徹底改變了舊有銀行服務。"},{"en":"A product can revolutionize an old category if it changes how customers use it every day.","zh":"如果產品改變顧客每天使用某類產品的方式，它就能徹底改變舊類別。"},{"en":"This phrase describes major transformation, not a small upgrade.","zh":"這個片語描述重大轉變，而不是小升級。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":2},{"front":"according to one study","meaning":"根據一項研究","examples":[{"en":"According to one study, many first movers have failed.","zh":"根據一項研究，許多先行者都失敗了。"},{"en":"According to one study means based on the findings of a particular piece of research.","zh":"according to one study 指根據某一項研究的結果。"},{"en":"According to one study, students remember vocabulary better when examples are concrete.","zh":"根據一項研究，當例子具體時，學生更容易記住詞彙。"},{"en":"If a claim comes from one study, readers should still consider whether other studies agree.","zh":"如果某主張來自一項研究，讀者仍應考慮其他研究是否同意。"},{"en":"This phrase introduces research evidence, but it does not mean all research says the same thing.","zh":"這個片語引入研究證據，但不表示所有研究都這樣說。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":2},{"front":"first movers","meaning":"先行者；率先進入市場者","examples":[{"en":"Almost half of first movers later failed.","zh":"幾乎一半先行者後來失敗。"},{"en":"First movers are companies that enter a new market or product category before competitors.","zh":"first movers 是在競爭者之前進入新市場或新產品類別的公司。"},{"en":"A company that launches the first home delivery app in a city is a first mover.","zh":"在城市中推出第一個家居送貨應用程式的公司就是先行者。"},{"en":"First movers may gain attention, but they also face uncertainty and education costs.","zh":"先行者可能獲得關注，但也面對不確定性和教育市場的成本。"},{"en":"This phrase does not guarantee leadership forever; early entrants can still fail.","zh":"這個片語不保證永遠領先；早期進入者仍可能失敗。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":2},{"front":"approximately half","meaning":"大約一半","examples":[{"en":"Approximately half the companies later pulled out of those businesses.","zh":"大約一半公司後來退出那些業務。"},{"en":"Approximately half means about 50 percent, not necessarily exactly one half.","zh":"approximately half 指大約50%，不一定正好一半。"},{"en":"Approximately half the class chose online learning, while the rest preferred lessons in person.","zh":"大約一半班級選擇網上學習，其餘則較喜歡面授課。"},{"en":"If approximately half of new ventures fail, success is far from certain.","zh":"如果大約一半新商業項目失敗，成功遠非確定。"},{"en":"This phrase gives a rough proportion rather than an exact count.","zh":"這個片語給出粗略比例，而不是精確數字。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":2},{"front":"pioneer new product categories","meaning":"開創新的產品類別","examples":[{"en":"Some companies pioneered new product categories but later failed.","zh":"一些公司開創新的產品類別，但後來失敗。"},{"en":"To pioneer new product categories means to be among the first to create or enter new types of products.","zh":"pioneer new product categories 指率先創造或進入新的產品類型。"},{"en":"A firm may pioneer a new product category by selling the first smart home device of its kind.","zh":"公司可能透過銷售首款同類智能家居裝置來開創新的產品類別。"},{"en":"Pioneering a category can be risky because customers may not yet understand the product.","zh":"開創類別可能有風險，因為顧客可能尚未理解產品。"},{"en":"This phrase stresses early innovation, not guaranteed long-term success.","zh":"這個片語強調早期創新，而不是保證長期成功。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":3},{"front":"pull out of","meaning":"退出","examples":[{"en":"Some companies later pulled out of those businesses.","zh":"一些公司後來退出那些業務。"},{"en":"To pull out of a business means to stop being involved in it and leave that market.","zh":"pull out of a business 指停止參與並退出該市場。"},{"en":"A restaurant chain may pull out of a city if rent becomes too high.","zh":"如果租金變得太高，連鎖餐廳可能退出某個城市。"},{"en":"If sales stay weak, a company may pull out of a product category to reduce losses.","zh":"如果銷售持續疲弱，公司可能退出某個產品類別以減少損失。"},{"en":"This phrase describes withdrawal, not temporary delay.","zh":"這個片語描述撤出，而不是暫時延誤。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":3},{"front":"after the fact","meaning":"事後","examples":[{"en":"After the fact, people often dismiss unsuccessful innovations as bad ideas.","zh":"事後，人們往往把失敗的創新輕易否定為壞主意。"},{"en":"After the fact means after something has already happened.","zh":"after the fact 指某事已經發生之後。"},{"en":"After the fact, it is easy to say the school should have cancelled the trip earlier.","zh":"事後說學校應該早點取消旅行很容易。"},{"en":"People often judge business failures differently after the fact because they already know the outcome.","zh":"人們事後常以不同方式評判商業失敗，因為他們已知道結果。"},{"en":"This phrase warns that hindsight can make events seem more obvious than they were.","zh":"這個片語提醒我們，事後看來事情可能比當時更明顯。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":3},{"front":"experts and novices alike","meaning":"專家和新手同樣","examples":[{"en":"Experts and novices alike may misjudge failed innovations.","zh":"專家和新手同樣可能誤判失敗的創新。"},{"en":"Experts and novices alike means both highly knowledgeable people and beginners.","zh":"experts and novices alike 指知識豐富的人和初學者同樣如此。"},{"en":"Experts and novices alike can make mistakes when instructions are unclear.","zh":"當指示不清晰時，專家和新手同樣可能犯錯。"},{"en":"If a bias is strong, experts and novices alike may be affected by it.","zh":"如果偏誤很強，專家和新手同樣可能受其影響。"},{"en":"This phrase stresses that a problem is not limited to inexperienced people.","zh":"這個片語強調問題不只限於缺乏經驗的人。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":3},{"front":"tend to dismiss","meaning":"往往不把……當一回事；輕易否定","examples":[{"en":"People tend to dismiss failed innovations as bad ideas.","zh":"人們往往把失敗創新輕易否定為壞主意。"},{"en":"To tend to dismiss something means to often reject it without giving it full consideration.","zh":"tend to dismiss something 指經常在未充分考慮下拒絕或否定某事。"},{"en":"Teachers should not tend to dismiss quiet students as uninterested.","zh":"老師不應往往把安靜學生視為沒有興趣。"},{"en":"If investors tend to dismiss unusual ideas too quickly, they may miss good opportunities.","zh":"如果投資者太快否定不尋常想法，可能錯過好機會。"},{"en":"This phrase suggests a repeated habit of judging too fast.","zh":"這個片語暗示反覆出現的過快判斷習慣。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":3},{"front":"unsuccessful innovations","meaning":"失敗的創新","examples":[{"en":"Unsuccessful innovations are often judged harshly after they fail.","zh":"失敗的創新在失敗後常被嚴厲評判。"},{"en":"Unsuccessful innovations are new ideas or products that do not achieve market success.","zh":"unsuccessful innovations 是沒有取得市場成功的新想法或產品。"},{"en":"A useful kitchen gadget may become an unsuccessful innovation if customers think it is too hard to clean.","zh":"如果顧客覺得某個實用廚房小工具太難清潔，它可能成為失敗的創新。"},{"en":"Unsuccessful innovations can teach companies why consumers resist change.","zh":"失敗的創新可以教公司理解消費者為何抗拒改變。"},{"en":"This phrase reminds us that failure does not always mean the idea had no value.","zh":"這個片語提醒我們，失敗不一定表示想法毫無價值。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":3},{"front":"be destined to fail","meaning":"注定失敗","examples":[{"en":"Some people think unsuccessful innovations were destined to fail.","zh":"有些人認為失敗的創新注定失敗。"},{"en":"To be destined to fail means to seem certain to fail from the beginning.","zh":"be destined to fail 指似乎從一開始就必定失敗。"},{"en":"A project with no budget, no plan, and no users may appear destined to fail.","zh":"沒有預算、沒有計劃、沒有使用者的項目可能看似注定失敗。"},{"en":"After a product fails, people may wrongly say it was destined to fail all along.","zh":"產品失敗後，人們可能錯誤地說它一直注定失敗。"},{"en":"This phrase suggests inevitability, but it may reflect hindsight rather than truth.","zh":"這個片語暗示不可避免，但可能只是事後偏見而非真相。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":3},{"front":"offer distinct improvements over","meaning":"相比……提供明顯改進","examples":[{"en":"Some innovative products offer distinct improvements over existing ones.","zh":"一些創新產品相比現有產品提供明顯改進。"},{"en":"To offer distinct improvements over something means to provide clear advantages compared with it.","zh":"offer distinct improvements over something 指與某物相比提供清晰優勢。"},{"en":"A new bus app may offer distinct improvements over paper timetables by showing live arrival times.","zh":"新巴士應用程式透過顯示即時到站時間，相比紙本時間表提供明顯改進。"},{"en":"Even when a product offers improvements, customers may resist if switching feels costly.","zh":"即使產品提供改進，如果轉換感覺成本高，顧客仍可能抗拒。"},{"en":"This phrase focuses on visible advantages, not automatic adoption.","zh":"這個片語聚焦於明顯優勢，而不是自動採用。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":3},{"front":"existing products","meaning":"現有產品","examples":[{"en":"Consumers may reject new products even when they improve on existing products.","zh":"即使新產品比現有產品有所改進，消費者仍可能拒絕它們。"},{"en":"Existing products are products that are already available and being used.","zh":"existing products 是已經可供購買並被使用的產品。"},{"en":"A new coffee machine must compete with existing products that customers already understand.","zh":"新咖啡機必須與顧客已經理解的現有產品競爭。"},{"en":"If existing products are familiar, consumers may keep using them despite better alternatives.","zh":"如果現有產品令人熟悉，消費者可能即使有更好替代品也繼續使用它們。"},{"en":"This phrase contrasts what people already have with what companies want them to try.","zh":"這個片語對比人們已擁有的東西與公司希望他們嘗試的東西。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":3},{"front":"invariably have more faith in","meaning":"總是對……更有信心","examples":[{"en":"Companies invariably have more faith in new products than consumers do.","zh":"公司總是比消費者更相信新產品。"},{"en":"To invariably have more faith in something means to consistently trust it more than others do.","zh":"invariably have more faith in something 指一貫地比其他人更信任某事。"},{"en":"Teachers may have more faith in a new reading method than students who have not tried it yet.","zh":"老師可能比尚未嘗試的學生更相信一種新閱讀方法。"},{"en":"If developers have too much faith in their product, they may underestimate customer resistance.","zh":"如果開發者對自己的產品太有信心，可能低估顧客抗拒。"},{"en":"This phrase suggests a repeated gap between creator confidence and user hesitation.","zh":"這個片語暗示創作者信心與使用者猶豫之間的反覆差距。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":3},{"front":"more than is warranted","meaning":"超出合理程度","examples":[{"en":"Companies may have more faith in new products than is warranted.","zh":"公司對新產品的信心可能超出合理程度。"},{"en":"More than is warranted means more than is reasonable or supported by the evidence.","zh":"more than is warranted 指超過合理範圍或證據所支持的程度。"},{"en":"A student may feel more confident than is warranted if they revise only the easy topics.","zh":"如果學生只溫習容易題目，他的信心可能超出合理程度。"},{"en":"If early testers like a product, managers may show more optimism than is warranted.","zh":"如果早期測試者喜歡產品，管理層可能表現出超出合理程度的樂觀。"},{"en":"This phrase warns that confidence may exceed reality.","zh":"這個片語警告信心可能超過現實。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":3},{"front":"objective advantages","meaning":"客觀優勢","examples":[{"en":"Many innovations have objective advantages over existing alternatives.","zh":"許多創新相比現有替代選擇有客觀優勢。"},{"en":"Objective advantages are benefits that can be measured or compared fairly.","zh":"objective advantages 是可以公平量度或比較的好處。"},{"en":"A washing machine that uses less electricity has an objective advantage over an older model.","zh":"一部用電較少的洗衣機相比舊型號有客觀優勢。"},{"en":"Objective advantages may not persuade consumers if they feel the old product is safer or easier.","zh":"如果消費者覺得舊產品更安全或更容易，客觀優勢未必能說服他們。"},{"en":"This phrase contrasts measurable benefits with feelings and habits.","zh":"這個片語對比可量度好處與感受和習慣。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":4},{"front":"existing alternatives","meaning":"現有替代選擇","examples":[{"en":"Innovations may improve on existing alternatives.","zh":"創新產品可能比現有替代選擇有所改進。"},{"en":"Existing alternatives are the current choices people can already use instead.","zh":"existing alternatives 是人們已經可以使用的現有選擇。"},{"en":"A new payment app competes with existing alternatives such as cash and credit cards.","zh":"新付款應用程式與現金和信用卡等現有替代選擇競爭。"},{"en":"If existing alternatives are convenient, customers may not switch to a new option.","zh":"如果現有替代選擇方便，顧客未必會轉用新選項。"},{"en":"This phrase helps compare a new product with choices already in the market.","zh":"這個片語幫助把新產品與市場上已有選擇作比較。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":4},{"front":"not enough for something to succeed","meaning":"不足以令……成功","examples":[{"en":"Objective superiority is often not enough for a product to succeed.","zh":"客觀上更優越往往不足以令產品成功。"},{"en":"Not enough for something to succeed means one good quality alone cannot guarantee success.","zh":"not enough for something to succeed 指單一優點不能保證成功。"},{"en":"Good food is not enough for a restaurant to succeed if service is rude and rent is too high.","zh":"如果服務粗魯而租金太高，好食物不足以令餐廳成功。"},{"en":"A product may be better, but that is not enough if customers fear the cost of switching.","zh":"產品可能較好，但如果顧客害怕轉換成本，這仍不足夠。"},{"en":"This phrase reminds us that success usually depends on several conditions.","zh":"這個片語提醒我們，成功通常取決於多個條件。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":4},{"front":"live up to expectations","meaning":"符合期望","examples":[{"en":"Many new products fail to live up to companies’ expectations.","zh":"許多新產品未能符合公司的期望。"},{"en":"To live up to expectations means to perform as well as people hoped or predicted.","zh":"live up to expectations 指表現達到人們希望或預測的水平。"},{"en":"A new phone may not live up to expectations if its battery runs out quickly.","zh":"如果新手機電池很快耗盡，它可能未能符合期望。"},{"en":"If customers do not adopt a product, it cannot live up to the company’s sales expectations.","zh":"如果顧客不採用產品，它就不能符合公司的銷售期望。"},{"en":"This phrase is often used when reality disappoints earlier hopes.","zh":"當現實令早前希望落空時，常使用這個片語。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":4},{"front":"delve into","meaning":"深入探究","examples":[{"en":"To understand product failure, we must delve into consumer psychology.","zh":"要理解產品失敗，我們必須深入探究消費者心理。"},{"en":"To delve into something means to examine it deeply and carefully.","zh":"delve into something 指深入而仔細地研究某事。"},{"en":"A teacher may delve into a student’s mistakes to find the real grammar problem.","zh":"老師可能深入探究學生錯誤，以找出真正文法問題。"},{"en":"If companies delve into consumer behaviour, they may discover hidden fears about switching.","zh":"如果公司深入探究消費者行為，可能發現關於轉換的隱藏恐懼。"},{"en":"This phrase suggests deeper investigation than a quick look.","zh":"這個片語暗示比快速查看更深入的調查。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":4},{"front":"psychology of behavior change","meaning":"行為改變的心理","examples":[{"en":"The passage explores the psychology of behavior change.","zh":"文章探討行為改變的心理。"},{"en":"The psychology of behavior change means how people think and feel when they are asked to change habits.","zh":"psychology of behavior change 指當人們被要求改變習慣時的想法和感受。"},{"en":"A person may know exercise is healthy but still resist changing a comfortable routine.","zh":"一個人可能知道運動健康，但仍抗拒改變舒服的日常習慣。"},{"en":"If a new product requires behaviour change, fear of loss may slow adoption.","zh":"如果新產品要求行為改變，對損失的恐懼可能減慢採用。"},{"en":"This phrase focuses on the mental barriers behind changing what people do.","zh":"這個片語聚焦於人們改變行為背後的心理障礙。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":4},{"front":"require consumers to","meaning":"要求消費者去","examples":[{"en":"New products often require consumers to change their behavior.","zh":"新產品常要求消費者改變行為。"},{"en":"Require consumers to means make customers need to do something.","zh":"require consumers to 指令顧客需要做某事。"},{"en":"A new banking app may require consumers to learn a new login process.","zh":"新銀行應用程式可能要求消費者學習新的登入流程。"},{"en":"If a product requires consumers to change too much, some may stay with the old option.","zh":"如果產品要求消費者改變太多，一些人可能繼續使用舊選項。"},{"en":"This phrase shows a demand placed on customers, not just a product feature.","zh":"這個片語顯示加在顧客身上的要求，而不只是產品功能。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":4},{"front":"change their behavior","meaning":"改變行為","examples":[{"en":"New products often require consumers to change their behavior.","zh":"新產品常要求消費者改變行為。"},{"en":"To change their behavior means to alter what people normally do.","zh":"change their behavior 指改變人們平常做事的方式。"},{"en":"A new recycling system asks residents to change their behavior by sorting rubbish carefully.","zh":"新回收系統要求居民透過仔細分類垃圾來改變行為。"},{"en":"If changing behaviour feels inconvenient, people may reject even a better product.","zh":"如果改變行為感覺不方便，人們可能拒絕即使更好的產品。"},{"en":"This phrase is central to adoption because many products demand new habits.","zh":"這個片語對採用新產品很核心，因為許多產品要求新習慣。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":4},{"front":"entail costs","meaning":"涉及成本","examples":[{"en":"Behavior changes entail costs for consumers.","zh":"行為改變對消費者涉及成本。"},{"en":"To entail costs means to involve costs or make costs necessary.","zh":"entail costs 指涉及成本或令成本變得必要。"},{"en":"Moving house entails costs such as deposits, transport, and new furniture.","zh":"搬屋涉及按金、交通和新家具等成本。"},{"en":"If adopting a new product entails costs, customers may hesitate before switching.","zh":"如果採用新產品涉及成本，顧客轉換前可能猶豫。"},{"en":"This phrase can refer to money, time, effort, or emotional discomfort.","zh":"這個片語可以指金錢、時間、努力或心理不適。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":4},{"front":"incur transaction costs","meaning":"承擔交易成本","examples":[{"en":"Consumers incur transaction costs when switching services.","zh":"消費者轉換服務時會承擔交易成本。"},{"en":"To incur transaction costs means to face extra expenses during a purchase, change, or deal.","zh":"incur transaction costs 指在購買、轉換或交易過程中面對額外費用。"},{"en":"A bank customer may incur transaction costs when transferring money abroad.","zh":"銀行客戶向海外轉帳時可能承擔交易成本。"},{"en":"If switching phone plans incurs fees, consumers may avoid moving to a better provider.","zh":"如果轉換電話計劃涉及費用，消費者可能避免轉到更好的供應商。"},{"en":"This phrase refers to costs connected with making a transaction happen.","zh":"這個片語指與完成交易相關的成本。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":4},{"front":"transaction costs","meaning":"交易成本","examples":[{"en":"Activation fees are an example of transaction costs.","zh":"啟用費是交易成本的一個例子。"},{"en":"Transaction costs are extra costs involved in changing, buying, selling, or arranging something.","zh":"transaction costs 是在轉換、購買、出售或安排某事時涉及的額外成本。"},{"en":"Delivery charges and service fees can be transaction costs for online shopping.","zh":"送貨費和服務費可以是網購的交易成本。"},{"en":"High transaction costs can make customers stay with their current provider.","zh":"高交易成本可以令顧客留在現有供應商。"},{"en":"This phrase covers the cost of doing the deal, not only the product price.","zh":"這個片語涵蓋完成交易的成本，而不只是產品價格。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":4},{"front":"activation fees","meaning":"啟用費","examples":[{"en":"Consumers may pay activation fees when they change service providers.","zh":"消費者轉換服務供應商時可能要支付啟用費。"},{"en":"Activation fees are charges paid to start using a new service.","zh":"activation fees 是開始使用新服務時支付的費用。"},{"en":"A mobile phone company may charge activation fees when a customer opens a new account.","zh":"流動電話公司可能在顧客開設新戶口時收取啟用費。"},{"en":"If activation fees are high, customers may decide not to switch providers.","zh":"如果啟用費很高，顧客可能決定不轉換供應商。"},{"en":"This phrase refers to a start-up charge, not a monthly bill.","zh":"這個片語指啟動服務的收費，而不是每月帳單。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":5},{"front":"switch from one provider to another","meaning":"從一個供應商轉到另一個","examples":[{"en":"Consumers may switch from one cellular service provider to another.","zh":"消費者可能從一個流動電話服務供應商轉到另一個。"},{"en":"To switch from one provider to another means to stop using one company and start using a different one.","zh":"switch from one provider to another 指停止使用一間公司，並開始使用另一間公司。"},{"en":"A family may switch from one internet provider to another if the connection is slow.","zh":"如果網絡連接很慢，家庭可能從一個互聯網供應商轉到另一個。"},{"en":"Switching providers can involve fees, paperwork, and learning a new system.","zh":"轉換供應商可能涉及費用、文件和學習新系統。"},{"en":"This phrase describes a change in service supplier.","zh":"這個片語描述服務供應商的改變。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":5},{"front":"cellular service provider","meaning":"流動電話服務供應商","examples":[{"en":"A cellular service provider may charge activation fees.","zh":"流動電話服務供應商可能收取啟用費。"},{"en":"A cellular service provider is a company that offers mobile phone network services.","zh":"cellular service provider 是提供流動電話網絡服務的公司。"},{"en":"People choose a cellular service provider based on price, signal quality, and data plans.","zh":"人們根據價格、訊號質素和數據計劃選擇流動電話服務供應商。"},{"en":"If a provider has poor coverage, customers may switch to another company.","zh":"如果供應商覆蓋差，顧客可能轉到另一間公司。"},{"en":"This phrase refers to mobile network service, not the phone itself.","zh":"這個片語指流動網絡服務，而不是電話本身。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":5},{"front":"bear learning costs","meaning":"承擔學習成本","examples":[{"en":"Consumers bear learning costs when using unfamiliar products.","zh":"消費者使用不熟悉產品時會承擔學習成本。"},{"en":"To bear learning costs means to spend time and effort learning how to use something new.","zh":"bear learning costs 指花時間和精力學習如何使用新事物。"},{"en":"Older workers may bear learning costs when a company changes its software.","zh":"當公司更換軟件，年長員工可能承擔學習成本。"},{"en":"If learning costs are high, people may avoid a product even if it is useful.","zh":"如果學習成本高，人們即使覺得產品有用也可能避開它。"},{"en":"This phrase shows that learning itself can feel like a cost.","zh":"這個片語顯示學習本身也可以感覺像成本。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":5},{"front":"learning costs","meaning":"學習成本","examples":[{"en":"Learning costs arise when consumers must learn a new system.","zh":"當消費者必須學習新系統時，學習成本便出現。"},{"en":"Learning costs are the time, effort, and frustration involved in learning something unfamiliar.","zh":"learning costs 是學習陌生事物所涉及的時間、努力和挫敗感。"},{"en":"A new school platform creates learning costs for teachers and students.","zh":"新學校平台為老師和學生造成學習成本。"},{"en":"When learning costs feel too high, people may keep using old tools.","zh":"當學習成本感覺太高，人們可能繼續使用舊工具。"},{"en":"This phrase explains why simple familiarity can beat a better design.","zh":"這個片語解釋為何單純熟悉感可以勝過更好的設計。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":5},{"front":"shift from manual to automatic","meaning":"從手動轉為自動","examples":[{"en":"Drivers may face learning costs when they shift from manual to automatic transmissions.","zh":"司機從手動變速箱轉為自動變速箱時，可能面對學習成本。"},{"en":"To shift from manual to automatic means to move from a hand-controlled system to one that works automatically.","zh":"shift from manual to automatic 指從手動控制系統轉到自動運作系統。"},{"en":"A driver who shifts from manual to automatic may need time to adjust to using fewer controls.","zh":"從手動轉為自動的司機可能需要時間適應使用較少控制。"},{"en":"If people shift from manual processes to automatic ones, they may gain convenience but lose familiar control.","zh":"如果人們從手動流程轉為自動流程，他們可能獲得方便，但失去熟悉的控制感。"},{"en":"This phrase describes a change in operating method.","zh":"這個片語描述操作方式的轉變。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":5},{"front":"automobile transmissions","meaning":"汽車變速箱","examples":[{"en":"Changing automobile transmissions can involve learning costs.","zh":"改變汽車變速箱可能涉及學習成本。"},{"en":"Automobile transmissions are systems that transfer engine power to a car’s wheels.","zh":"automobile transmissions 是把引擎動力傳送到車輪的系統。"},{"en":"Manual and automatic transmissions feel different to drivers.","zh":"手動和自動變速箱對司機來說感覺不同。"},{"en":"If a driver changes transmissions, they may need practice before feeling comfortable.","zh":"如果司機轉換變速箱，可能需要練習才感到舒服。"},{"en":"This phrase refers to a car’s gear system, not the whole vehicle.","zh":"這個片語指汽車的換檔系統，而不是整輛車。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":5},{"front":"sustain obsolescence costs","meaning":"承受過時成本","examples":[{"en":"Consumers sustain obsolescence costs when old collections become useless.","zh":"當舊收藏變得無用時，消費者會承受過時成本。"},{"en":"To sustain obsolescence costs means to suffer losses because older items no longer work or are no longer useful.","zh":"sustain obsolescence costs 指因舊物品不能再運作或不再有用而承受損失。"},{"en":"A family may sustain obsolescence costs when old chargers no longer fit new phones.","zh":"當舊充電器不再適用於新手機，家庭可能承受過時成本。"},{"en":"If a new technology replaces an old one, customers may lose value in what they already own.","zh":"如果新科技取代舊科技，顧客已擁有的東西可能失去價值。"},{"en":"This phrase shows the cost of products becoming outdated.","zh":"這個片語顯示產品變得過時的成本。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":5},{"front":"obsolescence costs","meaning":"過時成本；淘汰成本","examples":[{"en":"Obsolescence costs occur when older possessions lose their usefulness.","zh":"當較舊擁有物失去用途時，過時成本便出現。"},{"en":"Obsolescence costs are losses caused by old products becoming outdated or unusable.","zh":"obsolescence costs 是舊產品變得過時或不能使用所造成的損失。"},{"en":"A school may face obsolescence costs when old computers cannot run new software.","zh":"當舊電腦不能運行新軟件，學校可能面對過時成本。"},{"en":"Obsolescence costs can make consumers resist switching to a new format.","zh":"過時成本可以令消費者抗拒轉用新格式。"},{"en":"This phrase includes the wasted value of things people already bought.","zh":"這個片語包括人們已購買物品的浪費價值。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":5},{"front":"switch from VCRs to DVD players","meaning":"從錄影機轉用 DVD 播放機","examples":[{"en":"Consumers faced obsolescence costs when they switched from VCRs to DVD players.","zh":"消費者從錄影機轉用 DVD 播放機時面對過時成本。"},{"en":"To switch from VCRs to DVD players means to stop using videotape machines and start using DVD machines.","zh":"switch from VCRs to DVD players 指停止使用錄影帶機，並開始使用 DVD 播放機。"},{"en":"A family switching from VCRs to DVD players may find old tapes difficult to use.","zh":"從錄影機轉用 DVD 播放機的家庭可能發現舊錄影帶難以使用。"},{"en":"When people switch technologies, their old collections may lose value.","zh":"當人們轉換科技，舊收藏可能失去價值。"},{"en":"This phrase gives a clear example of one media format replacing another.","zh":"這個片語提供一種媒體格式取代另一種格式的清楚例子。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":5},{"front":"become useless","meaning":"變得無用","examples":[{"en":"Videotape collections became useless when people switched to DVD players.","zh":"當人們轉用 DVD 播放機，錄影帶收藏便變得無用。"},{"en":"To become useless means to lose practical value or no longer serve a purpose.","zh":"become useless 指失去實際價值或不再有用途。"},{"en":"An old charger becomes useless if it cannot fit any modern device.","zh":"如果舊充電器不能配合任何現代裝置，它就變得無用。"},{"en":"If a new product makes old accessories useless, consumers may resist adopting it.","zh":"如果新產品令舊配件變得無用，消費者可能抗拒採用它。"},{"en":"This phrase describes loss of function, not just age.","zh":"這個片語描述功能喪失，而不只是變舊。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":5},{"front":"economic switching costs","meaning":"經濟上的轉換成本","examples":[{"en":"Companies routinely anticipate economic switching costs.","zh":"公司慣常預計經濟上的轉換成本。"},{"en":"Economic switching costs are money-related costs people face when changing from one product or service to another.","zh":"economic switching costs 是人們從一種產品或服務轉到另一種時面對的金錢相關成本。"},{"en":"A customer may face economic switching costs when changing banks because of fees and paperwork.","zh":"顧客更換銀行時可能因費用和文件面對經濟轉換成本。"},{"en":"If switching costs are high, consumers may stay with an inferior product.","zh":"如果轉換成本高，消費者可能留在較差產品。"},{"en":"This phrase refers to financial barriers to change.","zh":"這個片語指改變時的財務障礙。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":6},{"front":"routinely anticipate","meaning":"慣常預計","examples":[{"en":"Most companies routinely anticipate economic switching costs.","zh":"大多數公司慣常預計經濟上的轉換成本。"},{"en":"To routinely anticipate something means to expect it regularly and plan for it.","zh":"routinely anticipate something 指經常預期某事並為其作計劃。"},{"en":"Schools routinely anticipate student absences during flu season.","zh":"學校在流感季節慣常預計學生缺席。"},{"en":"Companies may routinely anticipate fees but forget emotional resistance.","zh":"公司可能慣常預計費用，卻忘記情感上的抗拒。"},{"en":"This phrase suggests a normal part of planning, not a rare guess.","zh":"這個片語暗示計劃中的常規部分，而不是罕見猜測。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":6},{"front":"take something into account","meaning":"把……考慮在內","examples":[{"en":"Businesses often fail to take psychological costs into account.","zh":"企業常未能把心理成本考慮在內。"},{"en":"To take something into account means to consider it when making a decision.","zh":"take something into account 指在作決定時考慮某因素。"},{"en":"Teachers should take students’ stress into account before setting long homework.","zh":"老師在布置長功課前應把學生壓力考慮在內。"},{"en":"If companies do not take consumer habits into account, a better product may fail.","zh":"如果公司沒有把消費者習慣考慮在內，更好的產品也可能失敗。"},{"en":"This phrase means including a factor in judgement or planning.","zh":"這個片語指在判斷或計劃中包括某因素。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":6},{"front":"psychological costs","meaning":"心理成本","examples":[{"en":"Psychological costs are associated with behavior change.","zh":"心理成本與行為改變有關。"},{"en":"Psychological costs are emotional or mental burdens, such as fear, stress, or discomfort.","zh":"psychological costs 是情緒或心理負擔，例如恐懼、壓力或不適。"},{"en":"A student may face psychological costs when moving to a new school.","zh":"學生轉到新學校時可能面對心理成本。"},{"en":"If switching products creates anxiety, psychological costs may outweigh technical benefits.","zh":"如果轉換產品造成焦慮，心理成本可能大於技術好處。"},{"en":"This phrase explains why change can feel costly even when no money is paid.","zh":"這個片語解釋為何即使不付錢，改變仍可感覺有成本。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":6},{"front":"be associated with","meaning":"與……有關","examples":[{"en":"Psychological costs are associated with behavior change.","zh":"心理成本與行為改變有關。"},{"en":"To be associated with something means to be connected with it.","zh":"be associated with something 指與某事有連繫。"},{"en":"Poor sleep is often associated with weak concentration.","zh":"睡眠不足常與專注力弱有關。"},{"en":"If a product is associated with confusion, consumers may avoid it.","zh":"如果產品與混亂感有關，消費者可能避開它。"},{"en":"This phrase shows connection, not always direct cause.","zh":"這個片語顯示關聯，不一定是直接原因。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":6},{"front":"behavior change","meaning":"行為改變","examples":[{"en":"Behavior change can involve both economic and psychological costs.","zh":"行為改變可以涉及經濟和心理成本。"},{"en":"Behavior change means altering habits, actions, or routines.","zh":"behavior change 指改變習慣、行動或日常做法。"},{"en":"A family makes a behavior change when it starts separating rubbish for recycling.","zh":"當家庭開始分類垃圾回收，就是作出行為改變。"},{"en":"If a product requires major behavior change, adoption may be slower.","zh":"如果產品要求重大行為改變，採用速度可能較慢。"},{"en":"This phrase focuses on what people actually do, not only what they believe.","zh":"這個片語聚焦於人們實際做甚麼，而不只是相信甚麼。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":6},{"front":"largely ignored","meaning":"大多被忽視的","examples":[{"en":"A largely ignored psychological bias can cause products to fail.","zh":"一種大多被忽視的心理偏誤可以導致產品失敗。"},{"en":"Largely ignored means mostly not noticed, discussed, or considered.","zh":"largely ignored 指大多沒有被注意、討論或考慮。"},{"en":"A largely ignored safety problem may become serious after an accident.","zh":"大多被忽視的安全問題可能在事故後變得嚴重。"},{"en":"If consumer fear is largely ignored, companies may overestimate demand.","zh":"如果消費者恐懼大多被忽視，公司可能高估需求。"},{"en":"This phrase suggests that an important factor has been overlooked.","zh":"這個片語暗示重要因素被忽略。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":6},{"front":"psychological bias","meaning":"心理偏誤","examples":[{"en":"A psychological bias affects how people evaluate new products.","zh":"心理偏誤影響人們如何評估新產品。"},{"en":"A psychological bias is a mental tendency that can make judgement unfair or inaccurate.","zh":"psychological bias 是可能令判斷不公平或不準確的心理傾向。"},{"en":"A student may show a bias by thinking a familiar teacher is always clearer than a new one.","zh":"學生認為熟悉老師總是比新老師講得清楚，可能顯示偏誤。"},{"en":"Psychological bias can make consumers overvalue products they already own.","zh":"心理偏誤可以令消費者高估自己已擁有的產品。"},{"en":"This phrase explains hidden patterns in human judgement.","zh":"這個片語解釋人類判斷中的隱藏模式。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":6},{"front":"irrationally overvalue","meaning":"非理性地高估","examples":[{"en":"People irrationally overvalue benefits they currently possess.","zh":"人們會非理性地高估自己目前擁有的好處。"},{"en":"To irrationally overvalue something means to value it too highly without a good reason.","zh":"irrationally overvalue something 指在沒有充分理由下把某物看得過高。"},{"en":"A child may irrationally overvalue an old toy simply because it is theirs.","zh":"孩子可能只因舊玩具屬於自己而非理性地高估它。"},{"en":"If consumers irrationally overvalue old products, better alternatives may struggle.","zh":"如果消費者非理性地高估舊產品，更好的替代選擇可能難以成功。"},{"en":"This phrase shows that feelings of ownership can distort judgement.","zh":"這個片語顯示擁有感可以扭曲判斷。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":6},{"front":"currently possess","meaning":"目前擁有","examples":[{"en":"People value benefits they currently possess more than new benefits.","zh":"人們重視目前擁有的好處，多於新的好處。"},{"en":"Currently possess means have at the present time.","zh":"currently possess 指在現在擁有。"},{"en":"A family may currently possess an old car, so replacing it feels like losing something familiar.","zh":"家庭可能目前擁有一輛舊車，所以更換它感覺像失去熟悉事物。"},{"en":"If people focus on what they currently possess, they may undervalue what they could gain.","zh":"如果人們專注於目前擁有的東西，可能低估自己可以得到的東西。"},{"en":"This phrase refers to present ownership, not future possibility.","zh":"這個片語指現在的擁有，而不是未來可能性。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":6},{"front":"relative to","meaning":"相對於","examples":[{"en":"People overvalue what they possess relative to what they do not.","zh":"人們相對於自己沒有的東西，會高估自己擁有的東西。"},{"en":"Relative to means compared with something else.","zh":"relative to 指與其他事物相比。"},{"en":"A cheap meal may seem expensive relative to a student’s small weekly budget.","zh":"相對於學生很少的每週預算，一餐便宜飯也可能顯得昂貴。"},{"en":"Consumers judge a new product relative to the one they already use.","zh":"消費者會相對於自己已使用的產品來判斷新產品。"},{"en":"This phrase is useful when meaning depends on comparison.","zh":"當意思取決於比較時，這個片語很有用。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":6},{"front":"value the advantages of","meaning":"重視……的優勢","examples":[{"en":"Consumers value the advantages of products they already own.","zh":"消費者重視自己已擁有產品的優勢。"},{"en":"To value the advantages of something means to care about its benefits and see them as important.","zh":"value the advantages of something 指在意某物的好處並視其為重要。"},{"en":"A commuter may value the advantages of a familiar bus route because it feels predictable.","zh":"通勤者可能重視熟悉巴士路線的優勢，因為它感覺可預測。"},{"en":"If people value old advantages too strongly, they may ignore new improvements.","zh":"如果人們過度重視舊優勢，可能忽視新改進。"},{"en":"This phrase shows how benefits are judged from the user’s point of view.","zh":"這個片語顯示好處如何從使用者角度被判斷。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":7},{"front":"products they own","meaning":"他們擁有的產品","examples":[{"en":"People overvalue the products they own.","zh":"人們會高估他們擁有的產品。"},{"en":"Products they own are items that consumers already have and use.","zh":"products they own 是消費者已經擁有並使用的物品。"},{"en":"A person may prefer the headphones they own because they know exactly how they feel.","zh":"一個人可能較喜歡自己擁有的耳機，因為他清楚知道它們的感覺。"},{"en":"If people overvalue products they own, they may reject better replacements.","zh":"如果人們高估他們擁有的產品，可能拒絕更好的替代品。"},{"en":"This phrase connects ownership with emotional attachment.","zh":"這個片語把擁有權與情感依附連接起來。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":7},{"front":"executives","meaning":"企業高層","examples":[{"en":"Executives may overvalue the innovations they have developed.","zh":"企業高層可能高估他們開發的創新產品。"},{"en":"Executives are senior managers who make important business decisions.","zh":"executives 是作出重要商業決策的高級管理人員。"},{"en":"Company executives decide which products receive funding and marketing support.","zh":"公司高層決定哪些產品獲得資金和市場推廣支持。"},{"en":"If executives become too confident, they may ignore warning signs from customers.","zh":"如果企業高層變得過度自信，可能忽略來自顧客的警號。"},{"en":"This word refers to decision-makers near the top of an organisation.","zh":"這個詞指組織高層附近的決策者。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":7},{"front":"innovations they’ve developed","meaning":"他們開發的創新產品","examples":[{"en":"Executives value the benefits of innovations they’ve developed.","zh":"企業高層重視他們開發的創新產品的好處。"},{"en":"Innovations they’ve developed are new products or ideas created by the company or team itself.","zh":"innovations they’ve developed 是公司或團隊自己創造的新產品或新想法。"},{"en":"A teacher may feel proud of a lesson plan she has developed and value it highly.","zh":"老師可能為自己開發的教案感到自豪，並高度重視它。"},{"en":"If executives are attached to innovations they’ve developed, they may underestimate consumer resistance.","zh":"如果企業高層依戀他們開發的創新產品，可能低估消費者抗拒。"},{"en":"This phrase highlights the creator’s relationship with the new idea.","zh":"這個片語突出創作者與新想法之間的關係。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":7},{"front":"incumbent products","meaning":"既有產品","examples":[{"en":"Executives may underestimate the advantages of incumbent products.","zh":"企業高層可能低估既有產品的優勢。"},{"en":"Incumbent products are existing products already used by consumers in a market.","zh":"incumbent products 是市場上消費者已使用的現有產品。"},{"en":"A new payment app must compete with incumbent products like cash and credit cards.","zh":"新付款應用程式必須與現金和信用卡等既有產品競爭。"},{"en":"If incumbent products are trusted, consumers may not switch quickly.","zh":"如果既有產品值得信任，消費者未必會很快轉換。"},{"en":"This phrase refers to the products already holding a place in customers’ lives.","zh":"這個片語指已在顧客生活中佔有位置的產品。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":7},{"front":"have long assumed","meaning":"長久以來一直假設","examples":[{"en":"Companies have long assumed that consumers will adopt superior products.","zh":"公司長久以來一直假設消費者會採用較優越的產品。"},{"en":"To have long assumed something means to have believed it for a long time without questioning it enough.","zh":"have long assumed something 指長時間相信某事，而沒有充分質疑。"},{"en":"Teachers may have long assumed that more homework always leads to better learning.","zh":"老師可能長久以來一直假設更多功課必然帶來更好學習。"},{"en":"If companies have long assumed customers act rationally, they may ignore psychological bias.","zh":"如果公司長久以來一直假設顧客理性行動，可能忽視心理偏誤。"},{"en":"This phrase often introduces an old belief that may be wrong.","zh":"這個片語常引入一個可能錯誤的舊信念。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":7},{"front":"adopt new products","meaning":"採用新產品","examples":[{"en":"People do not always adopt new products that offer more value.","zh":"人們不一定會採用提供更多價值的新產品。"},{"en":"To adopt new products means to start buying, using, or accepting them.","zh":"adopt new products 指開始購買、使用或接受新產品。"},{"en":"A school may adopt new products like digital whiteboards after teacher training.","zh":"學校可能在教師培訓後採用電子白板等新產品。"},{"en":"Consumers may refuse to adopt new products if they fear losing familiar benefits.","zh":"如果消費者害怕失去熟悉好處，可能拒絕採用新產品。"},{"en":"This phrase focuses on real use, not just awareness.","zh":"這個片語聚焦於實際使用，而不只是知道產品存在。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":7},{"front":"deliver more value or utility","meaning":"提供更多價值或效用","examples":[{"en":"Companies expect consumers to adopt products that deliver more value or utility.","zh":"公司預期消費者會採用提供更多價值或效用的產品。"},{"en":"To deliver more value or utility means to provide greater usefulness, benefit, or satisfaction.","zh":"deliver more value or utility 指提供更大的實用性、好處或滿足感。"},{"en":"A cheaper phone plan delivers more value if it offers more data for the same price.","zh":"如果較便宜電話計劃以相同價格提供更多數據，它便提供更多價值。"},{"en":"Even products that deliver more utility may fail if customers fear switching costs.","zh":"即使產品提供更多效用，如果顧客害怕轉換成本，仍可能失敗。"},{"en":"This phrase reflects a rational view of consumer choice.","zh":"這個片語反映對消費者選擇的理性看法。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":7},{"front":"utility","meaning":"效用","examples":[{"en":"Consumers may not adopt a product even if it offers greater utility.","zh":"即使產品提供更大效用，消費者也未必採用它。"},{"en":"Utility means usefulness, benefit, or practical value.","zh":"utility 指有用性、好處或實際價值。"},{"en":"A backpack with strong straps and many pockets has high utility for students.","zh":"有堅固肩帶和多個口袋的背包對學生有高效用。"},{"en":"If consumers focus on losses, greater utility may not be enough to persuade them.","zh":"如果消費者聚焦於損失，更大效用未必足以說服他們。"},{"en":"This word is common in economics when discussing how useful something is to people.","zh":"這個詞常見於經濟學，用來討論某物對人的有用程度。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":7},{"front":"objectively superior to","meaning":"客觀上優於","examples":[{"en":"Companies try to develop products that are objectively superior to existing ones.","zh":"公司嘗試開發客觀上優於現有產品的產品。"},{"en":"Objectively superior to something means better according to measurable facts, not personal feelings.","zh":"objectively superior to something 指根據可量度事實較好，而不是基於個人感受。"},{"en":"A lamp that uses less electricity and lasts longer is objectively superior to an older one.","zh":"一盞用電較少且壽命較長的燈，客觀上優於舊燈。"},{"en":"A product can be objectively superior but still unpopular if consumers dislike changing habits.","zh":"產品可以客觀上優越，但如果消費者不喜歡改變習慣，仍可能不受歡迎。"},{"en":"This phrase separates measurable improvement from perceived attractiveness.","zh":"這個片語把可量度改進與感知吸引力分開。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":7},{"front":"sufficient incentive to","meaning":"足夠誘因去","examples":[{"en":"Consumers need sufficient incentive to purchase a new product.","zh":"消費者需要足夠誘因去購買新產品。"},{"en":"Sufficient incentive to do something means enough reason or motivation to take action.","zh":"sufficient incentive to do something 指有足夠理由或動機去採取行動。"},{"en":"A student needs sufficient incentive to join an extra class after school.","zh":"學生需要足夠誘因才會放學後參加額外課堂。"},{"en":"If the benefit is small, customers may not have sufficient incentive to switch products.","zh":"如果好處很小，顧客可能沒有足夠誘因去轉換產品。"},{"en":"This phrase explains why people act only when the reward feels strong enough.","zh":"這個片語解釋為何人們只在回報感覺足夠強時才行動。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":7},{"front":"relative advantage","meaning":"相對優勢","examples":[{"en":"Everett Rogers identified relative advantage as a key driver of adoption.","zh":"Everett Rogers 將相對優勢識別為採用的關鍵推動因素。"},{"en":"Relative advantage means how much better a new product seems compared with what people already use.","zh":"relative advantage 指新產品相比人們已使用的東西看起來好多少。"},{"en":"A new bus pass has a relative advantage if it is cheaper and works on more routes.","zh":"如果新巴士通行證更便宜且適用於更多路線，它便有相對優勢。"},{"en":"If consumers see little relative advantage, they may not adopt the new product.","zh":"如果消費者看不到多少相對優勢，可能不採用新產品。"},{"en":"This phrase measures advantage through comparison with the current option.","zh":"這個片語透過與現有選項比較來衡量優勢。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":8},{"front":"critical driver of","meaning":"……的關鍵推動因素","examples":[{"en":"Relative advantage was identified as the most critical driver of adoption.","zh":"相對優勢被識別為採用的最關鍵推動因素。"},{"en":"A critical driver of something is a very important factor that causes it to happen.","zh":"critical driver of something 是導致某事發生的非常重要因素。"},{"en":"Good feedback is a critical driver of improvement in language learning.","zh":"良好回饋是語言學習進步的關鍵推動因素。"},{"en":"If relative advantage is a critical driver, companies must show why switching is clearly worthwhile.","zh":"如果相對優勢是關鍵推動因素，公司必須顯示轉換為何明顯值得。"},{"en":"This phrase points to a main force behind a result.","zh":"這個片語指出結果背後的主要力量。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":8},{"front":"new-product adoption","meaning":"新產品採用","examples":[{"en":"Relative advantage is important in new-product adoption.","zh":"相對優勢在新產品採用中很重要。"},{"en":"New-product adoption means consumers begin to buy and use a newly introduced product.","zh":"new-product adoption 指消費者開始購買和使用新推出的產品。"},{"en":"Free trials can support new-product adoption by letting customers test before paying.","zh":"免費試用可以讓顧客先試後付，從而支持新產品採用。"},{"en":"New-product adoption may slow down when people fear losing familiar benefits.","zh":"當人們害怕失去熟悉好處時，新產品採用可能放慢。"},{"en":"This phrase describes the process by which a product becomes accepted by users.","zh":"這個片語描述產品被使用者接受的過程。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":8},{"front":"unbiased assessments","meaning":"不偏不倚的評估","examples":[{"en":"The argument assumes that companies make unbiased assessments.","zh":"這個論點假設公司會作出不偏不倚的評估。"},{"en":"Unbiased assessments are fair judgements not distorted by personal interest or preference.","zh":"unbiased assessments 是不受個人利益或偏好扭曲的公平判斷。"},{"en":"A teacher should make an unbiased assessment of every student’s writing.","zh":"老師應對每位學生的寫作作出不偏不倚的評估。"},{"en":"If companies lack unbiased assessments, they may overestimate their own innovations.","zh":"如果公司缺乏不偏不倚的評估，可能高估自己的創新產品。"},{"en":"This phrase highlights the need for fair evaluation.","zh":"這個片語強調公平評價的需要。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":8},{"front":"likelihood of adopting","meaning":"採用……的可能性","examples":[{"en":"Companies often misjudge consumers’ likelihood of adopting innovations.","zh":"公司常誤判消費者採用創新的可能性。"},{"en":"Likelihood of adopting means the chance that people will accept and use something new.","zh":"likelihood of adopting 指人們接受並使用新事物的機會。"},{"en":"A school may estimate students’ likelihood of adopting a new learning platform.","zh":"學校可能估計學生採用新學習平台的可能性。"},{"en":"If companies misread adoption likelihood, they may produce too many units.","zh":"如果公司誤判採用可能性，可能生產太多貨品。"},{"en":"This phrase refers to probability, not actual adoption yet.","zh":"這個片語指概率，而不是已經實際採用。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":8},{"front":"although compelling","meaning":"雖然有說服力","examples":[{"en":"Although compelling, the theory has one major flaw.","zh":"雖然有說服力，這個理論有一個主要缺陷。"},{"en":"Although compelling means even though an idea sounds strong, persuasive, or attractive.","zh":"although compelling 指即使某想法聽起來強而有力、有說服力或吸引。"},{"en":"Although compelling, a student’s argument still needs evidence from the passage.","zh":"雖然學生的論點有說服力，但仍需要文章中的證據。"},{"en":"A business plan may be compelling but still fail if it ignores customer habits.","zh":"商業計劃可能有說服力，但如果忽視顧客習慣仍會失敗。"},{"en":"This phrase introduces a contrast between appeal and weakness.","zh":"這個片語引入吸引力與弱點之間的對比。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":8},{"front":"one major flaw","meaning":"一個主要缺陷","examples":[{"en":"The theory has one major flaw.","zh":"這個理論有一個主要缺陷。"},{"en":"One major flaw is one serious weakness in an idea, plan, or argument.","zh":"one major flaw 是想法、計劃或論點中的一個嚴重弱點。"},{"en":"A study plan may have one major flaw if it leaves no time for revision.","zh":"如果學習計劃沒有留下溫習時間，它可能有一個主要缺陷。"},{"en":"If a product theory ignores psychology, that can become a major flaw.","zh":"如果產品理論忽視心理，那可以成為主要缺陷。"},{"en":"This phrase points to a problem important enough to weaken the whole idea.","zh":"這個片語指出足以削弱整個想法的重要問題。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":8},{"front":"fail to capture","meaning":"未能捕捉；未能反映","examples":[{"en":"The theory fails to capture psychological biases in decision making.","zh":"這個理論未能捕捉決策中的心理偏誤。"},{"en":"To fail to capture something means to fail to include, explain, or represent it accurately.","zh":"fail to capture something 指未能準確包括、解釋或反映某事。"},{"en":"Exam marks may fail to capture a student’s creativity and kindness.","zh":"考試分數可能未能反映學生的創意和善良。"},{"en":"If a model fails to capture consumer fear, it may predict too much adoption.","zh":"如果模型未能捕捉消費者恐懼，可能預測過高採用率。"},{"en":"This phrase shows that an explanation misses an important part of reality.","zh":"這個片語顯示解釋遺漏了現實中的重要部分。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":8},{"front":"affect decision making","meaning":"影響決策","examples":[{"en":"Psychological biases affect decision making.","zh":"心理偏誤會影響決策。"},{"en":"To affect decision making means to influence how people choose between options.","zh":"affect decision making 指影響人們如何在選項之間作選擇。"},{"en":"Stress can affect decision making by making people choose quickly without thinking.","zh":"壓力可以令人不思考便快速選擇，從而影響決策。"},{"en":"If loss aversion affects decision making, consumers may keep old products too long.","zh":"如果損失厭惡影響決策，消費者可能過久地保留舊產品。"},{"en":"This phrase focuses on what shapes choices.","zh":"這個片語聚焦於塑造選擇的因素。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":8},{"front":"a body of work","meaning":"一系列研究成果","examples":[{"en":"Kahneman won the Nobel Prize for a body of work on economic behavior.","zh":"Kahneman 因一系列關於經濟行為的研究成果獲得諾貝爾獎。"},{"en":"A body of work is a collection of research, writing, or creative output built over time.","zh":"a body of work 是隨時間建立的一系列研究、寫作或創作成果。"},{"en":"A musician’s body of work may include albums, concerts, and film scores.","zh":"音樂人的作品系列可能包括專輯、演唱會和電影配樂。"},{"en":"If a scholar’s body of work changes how people think, it may become highly influential.","zh":"如果學者的一系列研究成果改變人們思考方式，它可能變得很有影響力。"},{"en":"This phrase refers to many related works, not one single article.","zh":"這個片語指多個相關作品，而不是單篇文章。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":8},{"front":"explore why and when","meaning":"探究為何及何時","examples":[{"en":"Kahneman’s work explores why and when people deviate from rational behavior.","zh":"Kahneman 的研究探究人們為何及何時偏離理性行為。"},{"en":"To explore why and when something happens means to study its causes and timing.","zh":"explore why and when something happens 指研究某事發生的原因和時機。"},{"en":"Teachers explore why and when students lose focus during long lessons.","zh":"老師探究學生為何及何時在長課堂中失去專注。"},{"en":"If researchers explore why and when consumers resist change, they can design better products.","zh":"如果研究人員探究消費者為何及何時抗拒改變，就能設計更好的產品。"},{"en":"This phrase asks for both explanation and conditions.","zh":"這個片語同時詢問解釋和條件。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":8},{"front":"deviate from","meaning":"偏離","examples":[{"en":"Individuals often deviate from rational economic behavior.","zh":"個人經常偏離理性經濟行為。"},{"en":"To deviate from something means to move away from a standard, rule, or expected pattern.","zh":"deviate from something 指離開某標準、規則或預期模式。"},{"en":"A driver may deviate from the usual route to avoid heavy traffic.","zh":"司機可能偏離平常路線以避開嚴重交通。"},{"en":"People deviate from rational behaviour when emotions shape their choices.","zh":"當情緒塑造選擇，人們會偏離理性行為。"},{"en":"This phrase suggests departure from what is expected or normal.","zh":"這個片語暗示離開預期或正常情況。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":9},{"front":"rational economic behavior","meaning":"理性經濟行為","examples":[{"en":"Kahneman studied deviations from rational economic behavior.","zh":"Kahneman 研究人們偏離理性經濟行為的情況。"},{"en":"Rational economic behavior means making choices by logically comparing costs and benefits.","zh":"rational economic behavior 指透過邏輯比較成本和利益來作選擇。"},{"en":"Buying the cheaper identical product is often seen as rational economic behavior.","zh":"購買較便宜但完全相同的產品常被視為理性經濟行為。"},{"en":"Loss aversion can stop people from showing rational economic behavior.","zh":"損失厭惡可以阻止人們表現出理性經濟行為。"},{"en":"This phrase describes how people are expected to act in traditional economic theory.","zh":"這個片語描述傳統經濟理論預期人們如何行動。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":9},{"front":"one of the cornerstones of","meaning":"……的基石之一","examples":[{"en":"Prospect theory is one of the cornerstones of that research.","zh":"前景理論是該研究的基石之一。"},{"en":"One of the cornerstones of something means one of its most important foundations.","zh":"one of the cornerstones of something 指某事物最重要的基礎之一。"},{"en":"Regular practice is one of the cornerstones of language learning.","zh":"定期練習是語言學習的基石之一。"},{"en":"If loss aversion is a cornerstone of consumer psychology, companies must consider it.","zh":"如果損失厭惡是消費者心理的基石之一，公司便必須考慮它。"},{"en":"This phrase describes a basic idea that supports a larger field.","zh":"這個片語描述支撐較大領域的基本概念。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":9},{"front":"value prospects","meaning":"評估前景；評估選項","examples":[{"en":"Kahneman and Tversky studied how individuals value prospects.","zh":"Kahneman 和 Tversky 研究個人如何評估前景。"},{"en":"To value prospects means to judge the attractiveness of possible outcomes or choices.","zh":"value prospects 指評判可能結果或選擇的吸引力。"},{"en":"A student values prospects when choosing between a safe job and a risky business idea.","zh":"學生在安全工作和有風險創業想法之間選擇時，就是在評估前景。"},{"en":"If people value losses more strongly than gains, their choices may seem cautious.","zh":"如果人們比收益更重視損失，他們的選擇可能顯得謹慎。"},{"en":"This phrase focuses on how people evaluate possible futures.","zh":"這個片語聚焦於人們如何評估可能的未來。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":9},{"front":"alternatives before them","meaning":"面前的替代選擇","examples":[{"en":"People respond differently to the alternatives before them.","zh":"人們對面前的替代選擇有不同反應。"},{"en":"Alternatives before them are the choices currently available to people.","zh":"alternatives before them 是人們目前可選的選項。"},{"en":"A customer comparing two phone plans is judging the alternatives before them.","zh":"比較兩個電話計劃的顧客正在判斷面前的替代選擇。"},{"en":"If one option feels familiar, people may choose it even when other alternatives look better.","zh":"如果其中一個選項感覺熟悉，人們即使其他替代選擇看似更好，也可能選它。"},{"en":"This phrase refers to choices people are actually facing now.","zh":"這個片語指人們現在實際面對的選擇。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":9},{"front":"distinct characteristics","meaning":"明顯特徵","examples":[{"en":"People’s responses have four distinct characteristics.","zh":"人們的反應有四個明顯特徵。"},{"en":"Distinct characteristics are clear features that make something identifiable or different.","zh":"distinct characteristics 是令某事可被識別或與眾不同的清楚特徵。"},{"en":"A good school may have distinct characteristics such as strong support and clear discipline.","zh":"好學校可能有強大支援和清晰紀律等明顯特徵。"},{"en":"If consumer choices have distinct characteristics, researchers can describe them systematically.","zh":"如果消費者選擇有明顯特徵，研究人員便可以有系統地描述它們。"},{"en":"This phrase points to noticeable features, not vague impressions.","zh":"這個片語指可注意到的特徵，而不是模糊印象。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":9},{"front":"evaluate the attractiveness of","meaning":"評估……的吸引力","examples":[{"en":"People evaluate the attractiveness of an alternative subjectively.","zh":"人們主觀地評估某個替代選擇的吸引力。"},{"en":"To evaluate the attractiveness of something means to judge how appealing or worthwhile it seems.","zh":"evaluate the attractiveness of something 指評估某事看起來有多吸引或值得。"},{"en":"A family may evaluate the attractiveness of a flat by considering rent, location, and safety.","zh":"家庭可能透過考慮租金、地點和安全來評估單位的吸引力。"},{"en":"Consumers evaluate new products differently because each person has a different reference point.","zh":"消費者以不同方式評估新產品，因為每個人都有不同參照點。"},{"en":"This phrase focuses on judgement of appeal, not only objective quality.","zh":"這個片語聚焦於吸引力判斷，而不只是客觀質素。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":9},{"front":"based not on … but on …","meaning":"不是基於……而是基於……","examples":[{"en":"People judge alternatives based not on actual value but on perceived value.","zh":"人們判斷替代選擇，不是基於實際價值，而是基於感知價值。"},{"en":"Based not on A but on B means A is not the real basis; B is.","zh":"based not on A but on B 指 A 不是真正基礎，B 才是。"},{"en":"A student may choose a course based not on difficulty but on future career goals.","zh":"學生選課可能不是基於難度，而是基於未來職業目標。"},{"en":"If consumers choose based not on objective value but on perceived value, marketing and framing matter.","zh":"如果消費者選擇不是基於客觀價值，而是基於感知價值，市場推廣和框架便很重要。"},{"en":"This structure clearly contrasts the wrong basis with the real basis.","zh":"這個結構清楚對比錯誤基礎與真正基礎。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":9},{"front":"objective value","meaning":"客觀價值","examples":[{"en":"Consumers do not judge products only by objective value.","zh":"消費者不只根據客觀價值判斷產品。"},{"en":"Objective value is measurable worth based on facts such as price, speed, or durability.","zh":"objective value 是基於價格、速度或耐用度等事實的可量度價值。"},{"en":"A laptop with longer battery life has higher objective value for many students.","zh":"對許多學生來說，電池續航較長的手提電腦有較高客觀價值。"},{"en":"If consumers ignore objective value, a technically better product may fail.","zh":"如果消費者忽視客觀價值，技術上更好的產品可能失敗。"},{"en":"This phrase contrasts factual worth with feelings and perceptions.","zh":"這個片語對比事實價值與感受和感知。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":9},{"front":"subjective value","meaning":"主觀價值","examples":[{"en":"Consumers often judge products by subjective value.","zh":"消費者常根據主觀價值判斷產品。"},{"en":"Subjective value is the worth something has in a person’s own feelings or judgement.","zh":"subjective value 是某物在個人感受或判斷中的價值。"},{"en":"An old bag may have high subjective value because it was a gift from a parent.","zh":"舊袋可能有很高主觀價值，因為它是父母送的禮物。"},{"en":"If subjective value is strong, people may keep an inferior product.","zh":"如果主觀價值很強，人們可能保留較差產品。"},{"en":"This phrase shows that value is not always measured by price or performance.","zh":"這個片語顯示價值不一定由價格或性能量度。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":9},{"front":"perceived value","meaning":"感知價值","examples":[{"en":"Perceived value can differ from actual value.","zh":"感知價值可以與實際價值不同。"},{"en":"Perceived value is the value people believe something has, whether or not that belief is accurate.","zh":"perceived value 是人們相信某物具有的價值，不論該相信是否準確。"},{"en":"A branded bottle may have high perceived value even if it works like a cheaper one.","zh":"名牌水樽可能有很高感知價值，即使它功能與較便宜水樽相同。"},{"en":"If perceived value is low, customers may ignore a product’s objective advantages.","zh":"如果感知價值低，顧客可能忽視產品的客觀優勢。"},{"en":"This phrase explains why customer belief matters in the market.","zh":"這個片語解釋為何顧客信念在市場中重要。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":9},{"front":"reference point","meaning":"參照點","examples":[{"en":"People evaluate new products relative to a reference point.","zh":"人們相對於一個參照點來評估新產品。"},{"en":"A reference point is the standard or starting comparison people use to judge something.","zh":"reference point 是人們用來判斷某事的標準或起始比較。"},{"en":"A student may use last term’s grade as a reference point for judging progress.","zh":"學生可能用上學期成績作為判斷進步的參照點。"},{"en":"If consumers use their current product as a reference point, new products are judged against it.","zh":"如果消費者用目前產品作為參照點，新產品便會與它相比。"},{"en":"This phrase explains why the same offer can feel good or bad to different people.","zh":"這個片語解釋為何同一提議對不同人感覺好壞不同。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":10},{"front":"already own or consume","meaning":"已經擁有或使用","examples":[{"en":"The reference point is usually what consumers already own or consume.","zh":"參照點通常是消費者已經擁有或使用的東西。"},{"en":"Already own or consume means currently possess or regularly use.","zh":"already own or consume 指目前擁有或經常使用。"},{"en":"A customer may judge a new coffee brand against the one they already consume every morning.","zh":"顧客可能把新咖啡品牌與每天早上已經飲用的品牌比較。"},{"en":"If people compare new products with what they already own, losses can feel more obvious than gains.","zh":"如果人們把新產品與已經擁有的東西比較，損失可能比收益更明顯。"},{"en":"This phrase links present habits with future choices.","zh":"這個片語把目前習慣與未來選擇連接起來。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":10},{"front":"view something as gains","meaning":"把……視為收益","examples":[{"en":"Consumers view improvements as gains.","zh":"消費者把改進視為收益。"},{"en":"To view something as gains means to see it as a benefit or positive increase.","zh":"view something as gains 指把某事看成好處或正面增加。"},{"en":"A student may view extra feedback as a gain because it helps improve writing.","zh":"學生可能把額外回饋視為收益，因為它幫助改善寫作。"},{"en":"If consumers view faster speed as a gain, it may make a new product more attractive.","zh":"如果消費者把更快速度視為收益，新產品可能更吸引。"},{"en":"This phrase contrasts positive improvements with losses or shortcomings.","zh":"這個片語把正面改進與損失或缺點作對比。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":10},{"front":"treat something as losses","meaning":"把……視為損失","examples":[{"en":"Consumers treat shortcomings as losses.","zh":"消費者把缺點視為損失。"},{"en":"To treat something as losses means to see it as something painful or negative that is being given up.","zh":"treat something as losses 指把某事看成痛苦或負面的失去。"},{"en":"A commuter may treat a longer walk to the station as a loss, even if the new flat is cheaper.","zh":"通勤者可能把到車站較長的步行距離視為損失，即使新單位較便宜。"},{"en":"If consumers treat missing familiar features as losses, they may reject the new product.","zh":"如果消費者把缺少熟悉功能視為損失，他們可能拒絕新產品。"},{"en":"This phrase shows why small disadvantages can feel powerful.","zh":"這個片語顯示為何小缺點也可以感覺很有力量。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":10},{"front":"shortcomings","meaning":"缺點；不足之處","examples":[{"en":"Consumers treat shortcomings as losses.","zh":"消費者把缺點視為損失。"},{"en":"Shortcomings are weaknesses, disadvantages, or missing qualities.","zh":"shortcomings 是弱點、不利之處或缺少的質素。"},{"en":"A good phone may still have shortcomings, such as weak battery life or poor sound.","zh":"好手機仍可能有缺點，例如電池續航弱或音質差。"},{"en":"If a product’s shortcomings affect daily use, customers may ignore its strengths.","zh":"如果產品缺點影響日常使用，顧客可能忽視它的優勢。"},{"en":"This word is softer than failures but still points to problems.","zh":"這個詞比 failures 較溫和，但仍指出問題。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":10},{"front":"have a far greater impact on","meaning":"對……有大得多的影響","examples":[{"en":"Losses have a far greater impact on people than gains.","zh":"損失對人的影響遠大於收益。"},{"en":"To have a far greater impact on someone means to affect them much more strongly.","zh":"have a far greater impact on someone 指對某人的影響強得多。"},{"en":"One harsh comment may have a far greater impact on a student than several short compliments.","zh":"一句嚴厲評語對學生的影響，可能遠大於幾句簡短稱讚。"},{"en":"If losses have a greater impact, consumers may avoid switching even when gains are real.","zh":"如果損失影響更大，即使收益真實，消費者也可能避免轉換。"},{"en":"This phrase compares the strength of two effects.","zh":"這個片語比較兩種效果的強度。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":10},{"front":"similarly sized gains","meaning":"大小相若的收益","examples":[{"en":"Losses matter more than similarly sized gains.","zh":"損失比大小相若的收益更重要。"},{"en":"Similarly sized gains are benefits of about the same size or value as the losses being compared.","zh":"similarly sized gains 是與被比較損失大小或價值相近的好處。"},{"en":"Losing $10 may feel worse than gaining a similarly sized $10 feels good.","zh":"失去10美元的難受程度，可能大於得到大小相若的10美元所帶來的愉快。"},{"en":"If losses feel stronger than similarly sized gains, customers need larger benefits to switch.","zh":"如果損失比大小相若的收益感覺更強，顧客需要更大好處才會轉換。"},{"en":"This phrase helps explain why equal gains and losses do not feel equal.","zh":"這個片語幫助解釋為何相等收益與損失感覺並不相等。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":10},{"front":"loss aversion","meaning":"損失厭惡","examples":[{"en":"Loss aversion makes consumers reluctant to give up existing products.","zh":"損失厭惡令消費者不願放棄現有產品。"},{"en":"Loss aversion is the tendency to feel losses more strongly than equal gains.","zh":"loss aversion 是人們對損失的感受強於相等收益的傾向。"},{"en":"A person may keep an old phone because losing familiar features feels painful.","zh":"一個人可能保留舊手機，因為失去熟悉功能感覺痛苦。"},{"en":"Because of loss aversion, customers may demand large benefits before switching.","zh":"由於損失厭惡，顧客可能在轉換前要求巨大好處。"},{"en":"This phrase explains why people often protect what they already have.","zh":"這個片語解釋為何人們常保護已擁有的東西。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":10},{"front":"accept a bet","meaning":"接受賭注","examples":[{"en":"Most people will not accept a bet with equal chances of gain and loss.","zh":"大多數人不會接受一個收益和損失機會相等的賭注。"},{"en":"To accept a bet means to agree to take a risk for a possible reward.","zh":"accept a bet 指同意承擔風險以換取可能回報。"},{"en":"A student may refuse to accept a bet if losing lunch money feels worse than winning extra cash.","zh":"如果失去午餐錢比贏得額外現金更難受，學生可能拒絕接受賭注。"},{"en":"If people will not accept a fair-looking bet, loss aversion may be influencing them.","zh":"如果人們不接受看似公平的賭注，損失厭惡可能正在影響他們。"},{"en":"This phrase is used to illustrate risk-taking decisions.","zh":"這個片語用來說明承擔風險的決策。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":10},{"front":"chance of winning","meaning":"獲勝機會","examples":[{"en":"The bet involved a 50 per cent chance of winning money.","zh":"這個賭注涉及50%的獲勝機會。"},{"en":"Chance of winning means the probability of getting a successful or favourable result.","zh":"chance of winning 指得到成功或有利結果的概率。"},{"en":"A lottery ticket has a very small chance of winning a prize.","zh":"彩票獲獎機會非常小。"},{"en":"If the chance of winning is equal to the chance of losing, people may still refuse the bet.","zh":"如果獲勝機會與失敗機會相等，人們仍可能拒絕賭注。"},{"en":"This phrase focuses on probability, not the size of the prize.","zh":"這個片語聚焦於概率，而不是獎金大小。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":10},{"front":"chance of losing","meaning":"失去……的機會","examples":[{"en":"The bet involved a 50 per cent chance of losing money.","zh":"這個賭注涉及50%的失去金錢機會。"},{"en":"Chance of losing means the probability of suffering an unfavourable result.","zh":"chance of losing 指遭受不利結果的概率。"},{"en":"A risky investment may have a high chance of losing money.","zh":"高風險投資可能有很高失去金錢的機會。"},{"en":"If the chance of losing feels painful, people may ignore an equal chance of winning.","zh":"如果失去的機會感覺痛苦，人們可能忽視相等的獲勝機會。"},{"en":"This phrase helps explain why possible losses shape decisions.","zh":"這個片語幫助解釋為何可能損失塑造決策。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":10},{"front":"gains from the wager","meaning":"賭注帶來的收益","examples":[{"en":"The gains from the wager must outweigh the losses.","zh":"賭注帶來的收益必須超過損失。"},{"en":"Gains from the wager are the possible benefits or money won from a bet.","zh":"gains from the wager 是賭注可能帶來的好處或贏得的金錢。"},{"en":"A person may accept a wager only if the possible gain is much larger than the loss.","zh":"一個人可能只有在可能收益遠大於損失時才接受賭注。"},{"en":"If gains from the wager are too small, loss aversion makes the bet unattractive.","zh":"如果賭注帶來的收益太小，損失厭惡會令賭注不吸引。"},{"en":"This phrase focuses on the positive side of taking a risk.","zh":"這個片語聚焦於承擔風險的正面一面。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":11},{"front":"outweigh the losses","meaning":"超過損失","examples":[{"en":"Potential gains must outweigh the losses by a large margin.","zh":"潛在收益必須大幅超過損失。"},{"en":"To outweigh the losses means to be greater or more important than the possible disadvantages.","zh":"outweigh the losses 指大於或比可能缺點更重要。"},{"en":"A longer commute may be acceptable if the lower rent clearly outweighs the losses.","zh":"如果較低租金明顯超過損失，較長通勤可能可以接受。"},{"en":"If a new product’s benefits do not outweigh the losses, consumers may reject it.","zh":"如果新產品好處沒有超過損失，消費者可能拒絕它。"},{"en":"This phrase compares gains with what people must give up.","zh":"這個片語比較收益與人們必須放棄的東西。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":11},{"front":"by a factor of","meaning":"以……倍數","examples":[{"en":"The gains must outweigh the losses by a factor of two or three.","zh":"收益必須以兩倍或三倍超過損失。"},{"en":"By a factor of means by a multiplied amount.","zh":"by a factor of 指以倍數增加或比較。"},{"en":"If rent rises by a factor of two, it becomes twice as expensive.","zh":"如果租金以兩倍上升，它就變成原本兩倍貴。"},{"en":"If gains must exceed losses by a factor of three, a $10 loss needs about a $30 gain.","zh":"如果收益必須以三倍超過損失，10美元損失便需要大約30美元收益。"},{"en":"This phrase is used to show how many times larger one amount is than another.","zh":"這個片語用來顯示一個數量比另一個大多少倍。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":11},{"front":"find such a bet attractive","meaning":"覺得這樣的賭注吸引","examples":[{"en":"People find such a bet attractive only when the gains are much larger.","zh":"只有當收益大很多時，人們才覺得這樣的賭注吸引。"},{"en":"To find such a bet attractive means to think the risk is worth taking.","zh":"find such a bet attractive 指認為這個風險值得承擔。"},{"en":"A student may find a study challenge attractive if the reward is clearly valuable.","zh":"如果獎勵明顯有價值，學生可能覺得學習挑戰吸引。"},{"en":"If possible losses feel painful, people find a bet attractive only when gains are high enough.","zh":"如果可能損失感覺痛苦，人們只有在收益足夠高時才覺得賭注吸引。"},{"en":"This phrase links risk appeal with the balance between gain and loss.","zh":"這個片語把風險吸引力與收益和損失的平衡連接起來。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":11},{"front":"a survey of","meaning":"一項關於……的調查","examples":[{"en":"A survey of customers revealed a strong loss-aversion effect.","zh":"一項關於顧客的調查顯示強烈的損失厭惡效果。"},{"en":"A survey of a group is a study that asks people questions to collect information.","zh":"a survey of a group 是向人們提問以收集資訊的研究。"},{"en":"A survey of students may ask which learning app they actually use.","zh":"一項關於學生的調查可能詢問他們實際使用哪個學習應用程式。"},{"en":"If a survey of customers reveals resistance, a company may need to rethink its product launch.","zh":"如果一項關於顧客的調查顯示抗拒，公司可能需要重新思考產品推出。"},{"en":"This phrase introduces evidence gathered from people’s answers.","zh":"這個片語引入從人們回答中收集的證據。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":11},{"front":"reveal that","meaning":"顯示","examples":[{"en":"The survey revealed that consumers demand high compensation for losses.","zh":"調查顯示消費者要求高補償以彌補損失。"},{"en":"To reveal that something is true means to show or make it clear.","zh":"reveal that something is true 指顯示或令某事變得清楚。"},{"en":"A health check may reveal that a patient needs more sleep.","zh":"健康檢查可能顯示病人需要更多睡眠。"},{"en":"If research reveals that customers fear loss, companies should not ignore that fear.","zh":"如果研究顯示顧客害怕損失，公司不應忽視這種恐懼。"},{"en":"This phrase introduces a finding that was discovered or made clear.","zh":"這個片語引入被發現或被清楚顯示的結果。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":11},{"front":"demand compensation","meaning":"要求補償","examples":[{"en":"Consumers demand compensation to endure a power outage.","zh":"消費者要求補償以忍受停電。"},{"en":"To demand compensation means to ask for money or benefits because of a loss or inconvenience.","zh":"demand compensation 指因損失或不便而要求金錢或好處。"},{"en":"Passengers may demand compensation if a flight is cancelled without warning.","zh":"如果航班無預警取消，乘客可能要求補償。"},{"en":"If customers suffer a service failure, they may demand compensation before forgiving the company.","zh":"如果顧客遭遇服務故障，他們可能在原諒公司前要求補償。"},{"en":"This phrase shows that people want repayment for harm or discomfort.","zh":"這個片語顯示人們希望因傷害或不適得到彌補。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":11},{"front":"endure a power outage","meaning":"忍受停電","examples":[{"en":"Consumers demand compensation to endure a power outage.","zh":"消費者要求補償以忍受停電。"},{"en":"To endure a power outage means to tolerate a period when electricity is unavailable.","zh":"endure a power outage 指忍受一段沒有電力供應的時間。"},{"en":"Families may endure a power outage by using candles and portable chargers.","zh":"家庭可能透過使用蠟燭和流動充電器忍受停電。"},{"en":"If a power outage lasts for hours, people may lose food, work time, and comfort.","zh":"如果停電持續數小時，人們可能失去食物、工作時間和舒適感。"},{"en":"This phrase describes suffering through a service interruption.","zh":"這個片語描述承受服務中斷。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":11},{"front":"suffer a loss","meaning":"承受損失","examples":[{"en":"Consumers demand more compensation when they suffer a loss.","zh":"當消費者承受損失時，他們要求更多補償。"},{"en":"To suffer a loss means to experience losing money, value, comfort, or something important.","zh":"suffer a loss 指經歷失去金錢、價值、舒適或重要事物。"},{"en":"A shop may suffer a loss when unsold food must be thrown away.","zh":"當未售出的食物必須丟棄，商店可能承受損失。"},{"en":"If customers suffer a loss, they may feel more upset than when they miss a gain.","zh":"如果顧客承受損失，他們可能比錯過收益時更不快。"},{"en":"This phrase focuses on negative experience, not just missed opportunity.","zh":"這個片語聚焦於負面經歷，而不只是錯過機會。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":11},{"front":"be willing to pay","meaning":"願意支付","examples":[{"en":"Consumers are willing to pay less to avoid the same problem.","zh":"消費者願意支付較少金錢來避免同一問題。"},{"en":"To be willing to pay means to be prepared to spend money for something.","zh":"be willing to pay 指準備為某事花錢。"},{"en":"Parents may be willing to pay more for a safe school bus service.","zh":"家長可能願意為安全校巴服務支付更多。"},{"en":"If customers are not willing to pay enough, a product may not survive.","zh":"如果顧客不願意支付足夠金額，產品可能無法生存。"},{"en":"This phrase shows the price people accept for a benefit or solution.","zh":"這個片語顯示人們為好處或解決方案接受的價格。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":11},{"front":"avoid the problem","meaning":"避免問題","examples":[{"en":"Consumers are willing to pay to avoid the problem.","zh":"消費者願意付款以避免問題。"},{"en":"To avoid the problem means to prevent the difficulty from happening.","zh":"avoid the problem 指防止困難發生。"},{"en":"A student may leave home earlier to avoid the problem of late buses.","zh":"學生可能早點出門，以避免巴士遲到的問題。"},{"en":"If customers can avoid the problem cheaply, they may prefer prevention to compensation.","zh":"如果顧客可以低成本避免問題，可能較喜歡預防而不是補償。"},{"en":"This phrase focuses on stopping trouble before it occurs.","zh":"這個片語聚焦於在麻煩發生前阻止它。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":11},{"front":"potential gain","meaning":"潛在收益","examples":[{"en":"Avoiding a power outage represents a potential gain.","zh":"避免停電代表一項潛在收益。"},{"en":"A potential gain is a possible benefit that may happen in the future.","zh":"potential gain 是未來可能發生的好處。"},{"en":"A better bus route offers the potential gain of shorter travel time.","zh":"更好的巴士路線提供縮短通勤時間的潛在收益。"},{"en":"People may value a potential gain less than avoiding a direct loss.","zh":"人們對潛在收益的重視可能低於避免直接損失。"},{"en":"This phrase describes a possible positive outcome, not something already received.","zh":"這個片語描述可能的正面結果，而不是已經得到的東西。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":12},{"front":"losses loom larger than gains","meaning":"損失比收益更顯著","examples":[{"en":"Kahneman and Tversky wrote that losses loom larger than gains.","zh":"Kahneman 和 Tversky 寫道，損失比收益更顯著。"},{"en":"Losses loom larger than gains means losses feel more powerful than equal-sized benefits.","zh":"losses loom larger than gains 指損失比同等大小的好處感覺更有力量。"},{"en":"Losing a favourite mug may upset someone more than receiving a similar new mug pleases them.","zh":"失去喜愛的杯子可能比收到相似新杯子帶來的快樂更令人難受。"},{"en":"If losses loom larger than gains, customers need strong reasons to switch products.","zh":"如果損失比收益更顯著，顧客需要強烈理由才會轉換產品。"},{"en":"This phrase summarises the emotional imbalance between loss and benefit.","zh":"這個片語概括損失與好處之間的情感不平衡。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":12},{"front":"lead people to","meaning":"導致人們……","examples":[{"en":"Loss aversion leads people to value what they already possess.","zh":"損失厭惡導致人們重視自己已經擁有的東西。"},{"en":"To lead people to do something means to cause or guide them toward that action.","zh":"lead people to do something 指造成或引導人們做某事。"},{"en":"Clear feedback can lead students to revise more carefully.","zh":"清晰回饋可以引導學生更仔細修改。"},{"en":"Loss aversion leads consumers to protect old products even when better options exist.","zh":"損失厭惡導致消費者即使有更好選項，也保護舊產品。"},{"en":"This phrase explains how one factor creates a behaviour.","zh":"這個片語解釋一個因素如何造成某種行為。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":12},{"front":"already possess","meaning":"已經擁有","examples":[{"en":"People value products they already possess more highly.","zh":"人們會更高度重視自己已經擁有的產品。"},{"en":"Already possess means already own or have.","zh":"already possess 指已經擁有或持有。"},{"en":"A child may value the stickers they already possess more than new ones in a shop.","zh":"孩子可能比商店中新貼紙更重視自己已經擁有的貼紙。"},{"en":"If consumers already possess a product, giving it up may feel like a loss.","zh":"如果消費者已經擁有某產品，放棄它可能感覺像損失。"},{"en":"This phrase highlights the role of ownership in judgement.","zh":"這個片語突出擁有權在判斷中的作用。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":12},{"front":"part of their endowment","meaning":"屬於他們擁有物的一部分","examples":[{"en":"Owned products become part of a person’s endowment.","zh":"已擁有產品成為一個人擁有物的一部分。"},{"en":"Part of their endowment means part of what people feel they own and are entitled to keep.","zh":"part of their endowment 指屬於人們覺得自己擁有並有權保留的東西。"},{"en":"A familiar desk at school may feel like part of a student’s endowment after months of use.","zh":"學生使用幾個月後，熟悉的課桌可能感覺像屬於自己擁有物的一部分。"},{"en":"If a product becomes part of someone’s endowment, giving it up feels like losing property.","zh":"如果產品成為某人擁有物的一部分，放棄它就像失去財物。"},{"en":"This phrase explains why ownership changes value in people’s minds.","zh":"這個片語解釋為何擁有權會改變人們心中的價值。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":12},{"front":"behavioral economist","meaning":"行為經濟學家","examples":[{"en":"Richard Thaler is a behavioral economist.","zh":"Richard Thaler 是一位行為經濟學家。"},{"en":"A behavioral economist studies how real people make economic decisions, including irrational habits and biases.","zh":"behavioral economist 研究真實人類如何作經濟決策，包括非理性習慣和偏誤。"},{"en":"A behavioral economist may study why consumers keep old products even when better ones exist.","zh":"行為經濟學家可能研究為何即使有更好產品，消費者仍保留舊產品。"},{"en":"If economic theory ignores psychology, behavioral economists can reveal what it misses.","zh":"如果經濟理論忽視心理，行為經濟學家可以揭示它遺漏的東西。"},{"en":"This phrase combines economics with psychology.","zh":"這個片語結合經濟學與心理學。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":12},{"front":"give up","meaning":"放棄","examples":[{"en":"Consumers value what they might have to give up.","zh":"消費者重視自己可能必須放棄的東西。"},{"en":"To give up something means to stop having, using, or keeping it.","zh":"give up something 指停止擁有、使用或保留某物。"},{"en":"A student may hesitate to give up a familiar study method before exams.","zh":"學生在考試前可能猶豫是否放棄熟悉的學習方法。"},{"en":"If customers must give up old features, they may see switching as a loss.","zh":"如果顧客必須放棄舊功能，他們可能把轉換視為損失。"},{"en":"This phrase often carries the feeling of sacrifice.","zh":"這個片語常帶有犧牲感。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":12},{"front":"could obtain","meaning":"可以取得","examples":[{"en":"Consumers undervalue what they do not own but could obtain.","zh":"消費者低估自己尚未擁有但可以取得的東西。"},{"en":"Could obtain means could get, buy, receive, or gain.","zh":"could obtain 指可以得到、購買、接收或獲得。"},{"en":"A student may ignore free library books they could obtain because they already like their own notes.","zh":"學生可能忽視可以取得的免費圖書館書籍，因為他已喜歡自己的筆記。"},{"en":"If people focus on what they own, they may undervalue benefits they could obtain later.","zh":"如果人們聚焦於已擁有的東西，可能低估日後可以取得的好處。"},{"en":"This phrase refers to possible future possession.","zh":"這個片語指未來可能擁有。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":12},{"front":"endowment effect","meaning":"稟賦效應","examples":[{"en":"Thaler called this bias the endowment effect.","zh":"Thaler 把這種偏誤稱為稟賦效應。"},{"en":"The endowment effect is the tendency to value something more highly simply because one owns it.","zh":"endowment effect 是只因擁有某物而把它看得更有價值的傾向。"},{"en":"A child may value an ordinary pencil more after it becomes their own pencil.","zh":"孩子可能在普通鉛筆成為自己的鉛筆後，更重視它。"},{"en":"Because of the endowment effect, sellers often ask for more than buyers are willing to pay.","zh":"由於稟賦效應，賣方要價常高於買方願意支付的價格。"},{"en":"This phrase explains why ownership can inflate perceived value.","zh":"這個片語解釋為何擁有權會抬高感知價值。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":12},{"front":"a series of experiments","meaning":"一系列實驗","examples":[{"en":"Thaler and his colleagues described a series of experiments.","zh":"Thaler 和他的同事描述了一系列實驗。"},{"en":"A series of experiments is several related tests carried out to study a question.","zh":"a series of experiments 是為研究某問題而進行的幾個相關測試。"},{"en":"A science class may conduct a series of experiments to compare plant growth under different light.","zh":"科學課可能進行一系列實驗，比較植物在不同光線下的生長。"},{"en":"If several experiments show the same pattern, the evidence becomes stronger.","zh":"如果幾個實驗顯示相同模式，證據會變得更強。"},{"en":"This phrase suggests repeated testing, not one isolated trial.","zh":"這個片語暗示重複測試，而不是單一孤立試驗。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":12},{"front":"conduct experiments","meaning":"進行實驗","examples":[{"en":"The researchers conducted experiments to measure the endowment effect.","zh":"研究人員進行實驗以衡量稟賦效應。"},{"en":"To conduct experiments means to carry out controlled tests to learn something.","zh":"conduct experiments 指進行受控制的測試以了解某事。"},{"en":"Students conduct experiments in the lab to see how temperature affects reaction speed.","zh":"學生在實驗室進行實驗，觀察溫度如何影響反應速度。"},{"en":"Researchers conduct experiments because observation alone may not show cause clearly.","zh":"研究人員進行實驗，因為單靠觀察未必能清楚顯示原因。"},{"en":"This phrase describes organised scientific testing.","zh":"這個片語描述有組織的科學測試。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":12},{"front":"measure the magnitude of","meaning":"衡量……的幅度","examples":[{"en":"The experiments measured the magnitude of the endowment effect.","zh":"這些實驗衡量稟賦效應的幅度。"},{"en":"To measure the magnitude of something means to find out how large or strong it is.","zh":"measure the magnitude of something 指找出某事有多大或多強。"},{"en":"A doctor may measure the magnitude of pain by asking patients to rate it.","zh":"醫生可能透過要求病人評分來衡量疼痛幅度。"},{"en":"If researchers measure the magnitude of a bias, they can show how powerful it is.","zh":"如果研究人員衡量某偏誤的幅度，就能顯示它有多強。"},{"en":"This phrase focuses on size, strength, or scale.","zh":"這個片語聚焦於大小、強度或規模。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":13},{"front":"price point","meaning":"價格點","examples":[{"en":"The Sellers were asked to name a price point for the mugs.","zh":"賣方被要求為杯子說出一個價格點。"},{"en":"A price point is a particular price at which a product is offered or accepted.","zh":"price point 是產品被提供或接受的某個特定價格。"},{"en":"A shop may test whether customers prefer a $20 or $25 price point.","zh":"商店可能測試顧客較喜歡20美元還是25美元的價格點。"},{"en":"If the price point feels too high, buyers may choose a cheaper alternative.","zh":"如果價格點感覺太高，買方可能選擇較便宜替代品。"},{"en":"This phrase is common in sales, marketing, and experiments about value.","zh":"這個片語常見於銷售、市場推廣和價值實驗。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":13},{"front":"be willing to part with","meaning":"願意放棄","examples":[{"en":"The Sellers stated the price at which they would be willing to part with the mugs.","zh":"賣方說出他們願意放棄杯子的價格。"},{"en":"To be willing to part with something means to agree to give it up.","zh":"be willing to part with something 指同意放棄某物。"},{"en":"A child may not be willing to part with an old toy even for a new one.","zh":"孩子可能即使用新玩具交換，也不願意放棄舊玩具。"},{"en":"If sellers value ownership highly, they demand more before parting with an item.","zh":"如果賣方高度重視擁有權，便會在放棄物品前要求更多。"},{"en":"This phrase often shows emotional attachment to what one owns.","zh":"這個片語常顯示對所擁有東西的情感依附。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":13},{"front":"indicate whether","meaning":"表明是否","examples":[{"en":"The Choosers indicated whether they would choose the mug or the money.","zh":"選擇者表明他們是否會選杯子或金錢。"},{"en":"To indicate whether means to show or state which of two possibilities is true or preferred.","zh":"indicate whether 指顯示或說明兩個可能性中哪一個為真或較受偏好。"},{"en":"Students must indicate whether each statement is TRUE, FALSE, or NOT GIVEN.","zh":"學生必須表明每個陳述是否為 TRUE、FALSE 或 NOT GIVEN。"},{"en":"If participants indicate whether they prefer cash or a mug, researchers can compare values.","zh":"如果參加者表明自己較喜歡現金還是杯子，研究人員便可比較價值。"},{"en":"This phrase is useful in surveys, forms, and experiments.","zh":"這個片語適用於調查、表格和實驗。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":13},{"front":"in objective terms","meaning":"從客觀角度而言","examples":[{"en":"In objective terms, both groups faced the same choice.","zh":"從客觀角度而言，兩組人面對相同選擇。"},{"en":"In objective terms means judged by facts rather than feelings or ownership.","zh":"in objective terms 指根據事實而不是感受或擁有權來判斷。"},{"en":"In objective terms, the two tickets cost the same amount.","zh":"從客觀角度而言，兩張門票價格相同。"},{"en":"In objective terms, sellers and choosers compared the same mug and the same money.","zh":"從客觀角度而言，賣方和選擇者比較的是同一個杯子和同一筆金錢。"},{"en":"This phrase helps separate measurable reality from subjective perception.","zh":"這個片語幫助把可量度現實與主觀感知分開。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":13},{"front":"a sum of money","meaning":"一筆金錢","examples":[{"en":"Participants chose between a mug and a sum of money.","zh":"參加者在杯子和一筆金錢之間選擇。"},{"en":"A sum of money is an amount of money.","zh":"a sum of money 指一筆金錢。"},{"en":"A student may save a small sum of money every week for books.","zh":"學生可能每星期儲起一小筆金錢買書。"},{"en":"If a person chooses an object over a sum of money, ownership or preference may be influencing them.","zh":"如果一個人選擇物品而不是一筆金錢，擁有權或偏好可能正在影響他。"},{"en":"This phrase is neutral and does not say whether the amount is large or small.","zh":"這個片語是中性的，沒有說明金額大或小。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":13},{"front":"in one trial","meaning":"在其中一次試驗中","examples":[{"en":"In one trial, the Sellers valued the mug much more highly.","zh":"在其中一次試驗中，賣方對杯子的估值高得多。"},{"en":"In one trial means in one particular test or experiment.","zh":"in one trial 指在某一次特定測試或實驗中。"},{"en":"In one trial, students remembered more words after using picture cards.","zh":"在其中一次試驗中，學生使用圖卡後記得更多詞語。"},{"en":"If one trial shows a large difference, researchers may repeat the test to confirm it.","zh":"如果一次試驗顯示巨大差異，研究人員可能重複測試以確認。"},{"en":"This phrase refers to one instance within a wider experiment.","zh":"這個片語指較大實驗中的一次情況。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":13},{"front":"on average","meaning":"平均而言","examples":[{"en":"The Sellers priced the mug at $7.12 on average.","zh":"賣方平均把杯子定價為7.12美元。"},{"en":"On average means when the total is divided across all cases or people.","zh":"on average 指把總數分攤到所有個案或人身上後。"},{"en":"On average, students in the class read for twenty minutes a day.","zh":"平均而言，班上學生每天閱讀二十分鐘。"},{"en":"A higher average price suggests sellers valued the mug more than choosers did.","zh":"較高平均價格顯示賣方比選擇者更重視杯子。"},{"en":"This phrase describes a general pattern, not every individual result.","zh":"這個片語描述一般模式，而不是每個個別結果。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":13},{"front":"be willing to pay","meaning":"願意支付","examples":[{"en":"The Choosers were willing to pay only $3.12.","zh":"選擇者只願意支付3.12美元。"},{"en":"To be willing to pay means to accept spending a certain amount for something.","zh":"be willing to pay 指接受為某物支付某個金額。"},{"en":"A commuter may be willing to pay more for a faster train.","zh":"通勤者可能願意為更快的火車支付更多。"},{"en":"If buyers are willing to pay much less than sellers demand, no exchange may happen.","zh":"如果買方願意支付的金額遠低於賣方要求，交易可能不會發生。"},{"en":"This phrase reveals how much value a person places on an item.","zh":"這個片語揭示一個人賦予物品多少價值。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":13},{"front":"respectively","meaning":"分別地","examples":[{"en":"The Sellers and Choosers valued the mug at $7.00 and $3.50, respectively.","zh":"賣方和選擇者分別把杯子估值為7.00美元和3.50美元。"},{"en":"Respectively means in the same order as the items just mentioned.","zh":"respectively 指按剛提及項目的相同順序分別對應。"},{"en":"Tom and Amy scored 80 and 90 respectively, so Tom scored 80 and Amy scored 90.","zh":"Tom 和 Amy 分別得到80和90分，即 Tom 得80分，Amy 得90分。"},{"en":"This word helps match two lists without writing two separate sentences.","zh":"這個詞幫助配對兩組列表，而不用寫兩句句子。"},{"en":"Use respectively only when the order is clear.","zh":"只有當順序清楚時，才使用 respectively。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":13},{"front":"overall","meaning":"整體而言","examples":[{"en":"Overall, the Sellers demanded more than the Choosers would pay.","zh":"整體而言，賣方要求的金額高於選擇者願意支付的金額。"},{"en":"Overall means considering the whole situation or all the results together.","zh":"overall 指考慮整體情況或所有結果。"},{"en":"Overall, the school trip was successful, although the bus arrived late.","zh":"整體而言，學校旅行是成功的，雖然巴士遲到了。"},{"en":"If overall seller prices are higher than buyer offers, ownership may be affecting value.","zh":"如果整體賣方價格高於買方出價，擁有權可能正在影響價值。"},{"en":"This word introduces a general conclusion after details.","zh":"這個詞在細節後引入一般結論。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":13},{"front":"demand at least twice as much","meaning":"要求至少兩倍的金額","examples":[{"en":"The Sellers demanded at least twice as much to give up the mugs.","zh":"賣方要求至少兩倍的金額才願意放棄杯子。"},{"en":"To demand at least twice as much means to ask for no less than double the amount.","zh":"demand at least twice as much 指要求不少於雙倍的金額。"},{"en":"A landlord who demands at least twice as much rent may lose many tenants.","zh":"要求至少兩倍租金的業主可能失去很多租客。"},{"en":"If owners demand twice as much as buyers offer, exchange becomes difficult.","zh":"如果擁有者要求買方出價兩倍的金額，交換會變得困難。"},{"en":"This phrase shows a large gap between selling and buying values.","zh":"這個片語顯示賣價與買價之間的巨大差距。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":14},{"front":"obtain something","meaning":"取得……","examples":[{"en":"The Choosers would pay less to obtain the mugs.","zh":"選擇者願意支付較少金額來取得杯子。"},{"en":"To obtain something means to get, receive, or acquire it.","zh":"obtain something 指得到、接收或取得某物。"},{"en":"A student can obtain a library card by filling in a short form.","zh":"學生可以透過填寫簡短表格取得圖書證。"},{"en":"People may pay less to obtain an item than they would demand to give it up.","zh":"人們為取得某物願意支付的金額，可能低於他們放棄它時要求的金額。"},{"en":"This phrase focuses on acquiring something one does not yet have.","zh":"這個片語聚焦於取得尚未擁有的東西。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":14},{"front":"tend to stick with","meaning":"傾向維持使用","examples":[{"en":"People tend to stick with what they have.","zh":"人們傾向維持使用自己已有的東西。"},{"en":"To tend to stick with something means to usually continue using or choosing it.","zh":"tend to stick with something 指通常繼續使用或選擇某物。"},{"en":"A student may stick with the same pen because it feels comfortable.","zh":"學生可能維持使用同一支筆，因為它感覺舒服。"},{"en":"If consumers stick with what they have, new products face a harder market.","zh":"如果消費者維持使用已有產品，新產品會面對更困難市場。"},{"en":"This phrase describes preference for the familiar.","zh":"這個片語描述對熟悉事物的偏好。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":14},{"front":"what they have","meaning":"他們已經擁有的東西","examples":[{"en":"People often stick with what they have.","zh":"人們常維持使用他們已經擁有的東西。"},{"en":"What they have means the things people already own, use, or know.","zh":"what they have 指人們已擁有、使用或熟悉的東西。"},{"en":"A family may keep what they have instead of buying new furniture.","zh":"家庭可能保留已有家具，而不是購買新家具。"},{"en":"If people are satisfied with what they have, new benefits may not feel urgent.","zh":"如果人們滿意自己已有的東西，新好處可能不感覺迫切。"},{"en":"This phrase points to the current situation or possessions.","zh":"這個片語指目前情況或擁有物。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":14},{"front":"a better alternative exists","meaning":"存在更好的替代選擇","examples":[{"en":"People may keep old products even if a better alternative exists.","zh":"即使存在更好的替代選擇，人們也可能保留舊產品。"},{"en":"A better alternative exists means there is another option that is objectively or practically better.","zh":"a better alternative exists 指有另一個客觀上或實際上更好的選項。"},{"en":"A student may keep using messy notes even when a clearer textbook exists.","zh":"即使有更清晰的教科書，學生仍可能繼續使用混亂筆記。"},{"en":"If a better alternative exists but switching feels costly, people may stay with the old choice.","zh":"如果存在更好的替代選擇但轉換感覺有成本，人們可能留在舊選擇。"},{"en":"This phrase shows that better options do not automatically win.","zh":"這個片語顯示更好的選項不會自動勝出。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":14},{"front":"compelling demonstration","meaning":"有力示範","examples":[{"en":"Knetsch provided a compelling demonstration of status quo bias.","zh":"Knetsch 提供了現狀偏誤的有力示範。"},{"en":"A compelling demonstration is a clear and persuasive example showing how something works.","zh":"compelling demonstration 是清楚而有說服力地展示某事如何運作的例子。"},{"en":"A science teacher may use melting ice as a compelling demonstration of heat transfer.","zh":"科學老師可能使用融冰作為熱傳遞的有力示範。"},{"en":"If an experiment clearly shows bias, it becomes a compelling demonstration.","zh":"如果實驗清楚顯示偏誤，它就成為有力示範。"},{"en":"This phrase describes evidence that is easy to understand and hard to ignore.","zh":"這個片語描述容易理解且難以忽視的證據。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":14},{"front":"status quo bias","meaning":"現狀偏誤","examples":[{"en":"Status quo bias makes people prefer what they already have.","zh":"現狀偏誤令人偏好自己已經擁有的東西。"},{"en":"Status quo bias is the tendency to prefer the current situation simply because it is familiar.","zh":"status quo bias 是只因現況熟悉而偏好維持現況的傾向。"},{"en":"A student may keep an old study method because changing feels uncomfortable.","zh":"學生可能保留舊學習方法，因為改變感覺不舒服。"},{"en":"Status quo bias can make consumers reject new products even when they are better.","zh":"現狀偏誤可以令消費者即使新產品較好也拒絕它。"},{"en":"This phrase explains the pull of habit and familiarity.","zh":"這個片語解釋習慣和熟悉感的拉力。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":14},{"front":"choose between","meaning":"在……之間選擇","examples":[{"en":"Students were asked to choose between a mug and chocolate.","zh":"學生被要求在杯子和朱古力之間選擇。"},{"en":"To choose between two things means to select one of them.","zh":"choose between two things 指在兩者中選一個。"},{"en":"A customer may choose between a cheaper plan and a faster plan.","zh":"顧客可能在較便宜計劃和較快計劃之間選擇。"},{"en":"If people must choose between keeping and exchanging an item, ownership may affect their decision.","zh":"如果人們必須在保留和交換物品之間選擇，擁有權可能影響決定。"},{"en":"This phrase introduces a comparison between options.","zh":"這個片語引入選項之間的比較。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":14},{"front":"a large bar of Swiss chocolate","meaning":"一大塊瑞士朱古力","examples":[{"en":"Some students received a large bar of Swiss chocolate.","zh":"一些學生收到一大塊瑞士朱古力。"},{"en":"A large bar of Swiss chocolate is a sizeable piece of chocolate made in Switzerland.","zh":"a large bar of Swiss chocolate 是一大塊在瑞士製造的朱古力。"},{"en":"A teacher may give a large bar of Swiss chocolate as a prize in a classroom game.","zh":"老師可能把一大塊瑞士朱古力作為課堂遊戲獎品。"},{"en":"If students already own the chocolate, giving it up may feel like a loss.","zh":"如果學生已擁有朱古力，放棄它可能感覺像損失。"},{"en":"This phrase names a concrete item used in the experiment.","zh":"這個片語指出實驗中使用的具體物品。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":14},{"front":"allow someone to exchange","meaning":"允許某人交換","examples":[{"en":"Knetsch allowed students to exchange one product for another.","zh":"Knetsch 允許學生把一件產品交換成另一件。"},{"en":"To allow someone to exchange something means to let them swap one item for another.","zh":"allow someone to exchange something 指讓某人把一件物品換成另一件。"},{"en":"A shop may allow customers to exchange a shirt if the size is wrong.","zh":"如果尺碼不合，商店可能允許顧客交換恤衫。"},{"en":"If people refuse to exchange, researchers may infer that ownership changed preference.","zh":"如果人們拒絕交換，研究人員可能推斷擁有權改變了偏好。"},{"en":"This phrase shows permission to trade or swap.","zh":"這個片語顯示交換或互換的許可。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":14},{"front":"at the outset","meaning":"一開始","examples":[{"en":"At the outset, the students showed a near even split in preferences.","zh":"一開始，學生的偏好顯示接近平均分佈。"},{"en":"At the outset means at the beginning.","zh":"at the outset 指在開始時。"},{"en":"At the outset of a course, students may feel nervous and unsure.","zh":"課程一開始，學生可能感到緊張和不確定。"},{"en":"If preferences are even at the outset, later differences may come from the experiment itself.","zh":"如果一開始偏好平均，後來差異可能來自實驗本身。"},{"en":"This phrase marks the starting point of a process.","zh":"這個片語標示過程的起點。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":14},{"front":"near even split","meaning":"接近平均分佈","examples":[{"en":"The initial choice showed a near even split between the two products.","zh":"初始選擇顯示兩件產品之間接近平均分佈。"},{"en":"A near even split means the two choices are divided almost equally.","zh":"near even split 指兩個選擇幾乎平均分開。"},{"en":"In a class vote, a near even split means almost half choose each option.","zh":"在班級投票中，接近平均分佈表示兩個選項幾乎各佔一半。"},{"en":"If there is a near even split at first, strong later preference may need explanation.","zh":"如果起初接近平均分佈，之後出現強烈偏好就需要解釋。"},{"en":"This phrase shows balance rather than a clear majority.","zh":"這個片語顯示平衡，而不是明顯多數。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":15},{"front":"preferences between","meaning":"對……之間的偏好","examples":[{"en":"The experiment revealed preferences between mugs and chocolate bars.","zh":"實驗揭示了對杯子和朱古力條之間的偏好。"},{"en":"Preferences between two things are people’s choices or likes when comparing them.","zh":"preferences between two things 是人們比較兩者時的選擇或喜好。"},{"en":"A survey may ask students about preferences between online and face-to-face lessons.","zh":"調查可能詢問學生對網上課和面授課之間的偏好。"},{"en":"If preferences between two products change after ownership, bias may be involved.","zh":"如果兩件產品之間的偏好在擁有後改變，偏誤可能涉及其中。"},{"en":"This phrase focuses on comparative likes.","zh":"這個片語聚焦於比較性的喜好。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":15},{"front":"logically","meaning":"按邏輯而言","examples":[{"en":"Logically, about half the students should have traded their products.","zh":"按邏輯而言，大約一半學生應該交換自己的產品。"},{"en":"Logically means according to reason, evidence, or expected rules.","zh":"logically 指根據道理、證據或預期規則。"},{"en":"Logically, a student who missed three lessons should ask for notes.","zh":"按邏輯而言，缺席三堂課的學生應該索取筆記。"},{"en":"If preferences were evenly split, logically about half should choose to exchange.","zh":"如果偏好平均分佈，按邏輯而言約一半人應選擇交換。"},{"en":"This word introduces what should make sense before emotion or bias interferes.","zh":"這個詞引入在情緒或偏誤干擾前應合理成立的事情。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":15},{"front":"trade for","meaning":"換取","examples":[{"en":"About half the students should have traded for the other product.","zh":"大約一半學生本應換取另一件產品。"},{"en":"To trade for something means to exchange one thing in order to get another.","zh":"trade for something 指用一物交換以取得另一物。"},{"en":"A child may trade stickers for a toy card they like more.","zh":"孩子可能用貼紙換取更喜歡的玩具卡。"},{"en":"If students do not trade for the item they preferred earlier, ownership may be influencing them.","zh":"如果學生沒有換取自己早前較喜歡的物品，擁有權可能正在影響他們。"},{"en":"This phrase describes exchange rather than ordinary purchase.","zh":"這個片語描述交換，而不是普通購買。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":15},{"front":"vice versa","meaning":"反之亦然","examples":[{"en":"Students with chocolate should have traded for mugs, and vice versa.","zh":"擁有朱古力的學生本應換取杯子，反之亦然。"},{"en":"Vice versa means the same is true with the two things reversed.","zh":"vice versa 指把兩件事倒轉後同樣成立。"},{"en":"Parents can learn from children, and vice versa.","zh":"父母可以向孩子學習，反之亦然。"},{"en":"If mug owners should trade for chocolate and chocolate owners should trade for mugs, the logic works vice versa.","zh":"如果杯子持有人應換朱古力，而朱古力持有人應換杯子，這個邏輯便反之亦然。"},{"en":"This phrase avoids repeating the same idea in reverse order.","zh":"這個片語避免重複倒轉次序後的同一想法。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":15},{"front":"giving up what they already had","meaning":"放棄已擁有的東西","examples":[{"en":"Giving up what they already had seemed like a painful loss.","zh":"放棄已擁有的東西看似痛苦的損失。"},{"en":"Giving up what they already had means losing or surrendering something they already owned.","zh":"giving up what they already had 指失去或交出自己已擁有的東西。"},{"en":"A student may dislike giving up a familiar seat, even if another seat has a better view.","zh":"學生可能不喜歡放棄熟悉座位，即使另一個座位視野更好。"},{"en":"If giving up an owned item feels painful, people may refuse a fair exchange.","zh":"如果放棄已擁有物品感覺痛苦，人們可能拒絕公平交換。"},{"en":"This phrase explains why ownership makes change emotionally difficult.","zh":"這個片語解釋為何擁有權令改變在情感上困難。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":15},{"front":"painful loss","meaning":"痛苦的損失","examples":[{"en":"Giving up an owned item felt like a painful loss.","zh":"放棄已擁有物品感覺像痛苦的損失。"},{"en":"A painful loss is a loss that feels emotionally difficult or unpleasant.","zh":"painful loss 是在情感上困難或不愉快的損失。"},{"en":"Losing a favourite notebook may feel like a painful loss before an exam.","zh":"考試前失去最喜歡的筆記本可能感覺像痛苦的損失。"},{"en":"If customers see switching as a painful loss, discounts may not be enough.","zh":"如果顧客把轉換視為痛苦的損失，折扣可能不足夠。"},{"en":"This phrase shows that loss can be emotional, not only financial.","zh":"這個片語顯示損失可以是情感上的，而不只是金錢上的。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":15},{"front":"shrink one’s desire to","meaning":"減低某人……的意欲","examples":[{"en":"The feeling of loss shrank students’ desire to trade.","zh":"損失感減低了學生交換的意欲。"},{"en":"To shrink one’s desire to do something means to reduce one’s wish or motivation to do it.","zh":"shrink one’s desire to do something 指降低某人做某事的願望或動機。"},{"en":"Long waiting times can shrink a customer’s desire to visit a restaurant again.","zh":"長時間輪候可以減低顧客再次光顧餐廳的意欲。"},{"en":"If giving up a product feels like loss, it can shrink the desire to switch.","zh":"如果放棄產品感覺像損失，它可以減低轉換的意欲。"},{"en":"This phrase shows how negative feelings reduce motivation.","zh":"這個片語顯示負面感受如何降低動機。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":15},{"front":"desire to trade","meaning":"交換的意欲","examples":[{"en":"Status quo bias reduced their desire to trade.","zh":"現狀偏誤降低了他們交換的意欲。"},{"en":"Desire to trade means willingness or wish to exchange one item for another.","zh":"desire to trade 指把一件物品換成另一件的意願或願望。"},{"en":"A child’s desire to trade stickers may disappear if they become attached to their own set.","zh":"如果孩子依戀自己的貼紙收藏，交換貼紙的意欲可能消失。"},{"en":"If ownership reduces desire to trade, people may keep items they do not objectively prefer.","zh":"如果擁有權降低交換意欲，人們可能保留客觀上並不較喜歡的物品。"},{"en":"This phrase focuses on exchange motivation.","zh":"這個片語聚焦於交換動機。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":15},{"front":"seem oblivious to","meaning":"似乎沒有察覺","examples":[{"en":"Most people seem oblivious to their own biases.","zh":"大多數人似乎沒有察覺自己的偏誤。"},{"en":"To seem oblivious to something means to appear unaware of it.","zh":"seem oblivious to something 指看似沒有意識到某事。"},{"en":"A student may seem oblivious to the noise they make while tapping a pen.","zh":"學生敲筆時可能似乎沒有察覺自己製造的噪音。"},{"en":"If consumers are oblivious to their biases, they may believe their choices are purely rational.","zh":"如果消費者沒有察覺自己的偏誤，可能相信自己的選擇完全理性。"},{"en":"This phrase suggests lack of awareness, not deliberate denial.","zh":"這個片語暗示缺乏意識，而不是刻意否認。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":15},{"front":"the existence of","meaning":"……的存在","examples":[{"en":"People are often unaware of the existence of these biases.","zh":"人們常不知道這些偏誤的存在。"},{"en":"The existence of something means the fact that it is real or present.","zh":"the existence of something 指某事真實存在這一事實。"},{"en":"A school may inform parents about the existence of a new counselling service.","zh":"學校可能通知家長一項新輔導服務的存在。"},{"en":"If people do not know the existence of a bias, they cannot easily correct it.","zh":"如果人們不知道偏誤的存在，就不容易修正它。"},{"en":"This phrase points to whether something is present at all.","zh":"這個片語指出某事是否存在。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":15},{"front":"be implicit in","meaning":"隱含於……之中","examples":[{"en":"These behaviors are implicit in the endowment effect.","zh":"這些行為隱含於稟賦效應之中。"},{"en":"To be implicit in something means to be included or suggested without being stated directly.","zh":"be implicit in something 指包含或暗示於某事之中，但沒有直接說出。"},{"en":"Respect is implicit in a good classroom rule, even if the word is not written.","zh":"尊重隱含於良好課室規則之中，即使沒有寫出這個詞。"},{"en":"If overvaluing owned items is implicit in the endowment effect, the behaviour is part of the bias.","zh":"如果高估已擁有物品隱含於稟賦效應之中，該行為便是偏誤的一部分。"},{"en":"This phrase describes something hidden inside an idea or pattern.","zh":"這個片語描述藏在想法或模式內的東西。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":16},{"front":"study after study","meaning":"一項又一項研究","examples":[{"en":"Study after study showed that people overvalue the status quo.","zh":"一項又一項研究顯示人們高估現狀。"},{"en":"Study after study means many studies repeatedly show the same result.","zh":"study after study 指許多研究反覆顯示相同結果。"},{"en":"Study after study shows that sleep affects memory and concentration.","zh":"一項又一項研究顯示睡眠影響記憶和專注力。"},{"en":"If study after study finds the same bias, the pattern becomes difficult to dismiss.","zh":"如果一項又一項研究都發現同一偏誤，這個模式便難以否定。"},{"en":"This phrase stresses repeated research evidence.","zh":"這個片語強調重複的研究證據。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":16},{"front":"present someone with evidence","meaning":"向某人展示證據","examples":[{"en":"Researchers presented people with evidence of their own bias.","zh":"研究人員向人們展示他們自身偏誤的證據。"},{"en":"To present someone with evidence means to show them information that supports a claim.","zh":"present someone with evidence 指向某人展示支持某主張的資訊。"},{"en":"A teacher may present students with evidence that their answers copied the same mistake.","zh":"老師可能向學生展示證據，說明他們的答案抄了同一錯誤。"},{"en":"When people are presented with evidence of bias, they may still resist accepting it.","zh":"當人們被展示偏誤證據時，仍可能抗拒接受。"},{"en":"This phrase describes giving proof for someone to consider.","zh":"這個片語描述提供證據讓某人考慮。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":16},{"front":"irrationally overvalue","meaning":"非理性地高估","examples":[{"en":"People irrationally overvalue the status quo.","zh":"人們非理性地高估現狀。"},{"en":"To irrationally overvalue something means to judge it as more valuable than reason supports.","zh":"irrationally overvalue something 指把某物判斷得比理性支持的價值更高。"},{"en":"A worker may irrationally overvalue an old system simply because it is familiar.","zh":"員工可能只因舊系統熟悉而非理性地高估它。"},{"en":"If customers irrationally overvalue the status quo, innovation faces resistance.","zh":"如果顧客非理性地高估現狀，創新會面對抗拒。"},{"en":"This phrase shows how bias can make familiar options seem too important.","zh":"這個片語顯示偏誤如何令熟悉選項顯得過分重要。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":16},{"front":"the status quo","meaning":"現狀","examples":[{"en":"People often prefer the status quo.","zh":"人們常偏好現狀。"},{"en":"The status quo is the current situation or the way things are now.","zh":"the status quo 是目前情況或事情現在的樣子。"},{"en":"A school keeps the status quo when it refuses to change its timetable.","zh":"當學校拒絕改變時間表時，它就是維持現狀。"},{"en":"If people prefer the status quo, they may avoid new products even when benefits exist.","zh":"如果人們偏好現狀，即使有好處也可能避開新產品。"},{"en":"This phrase is often used when discussing resistance to change.","zh":"這個片語常用於討論對改變的抗拒。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":16},{"front":"skeptical","meaning":"懷疑的","examples":[{"en":"People were skeptical when shown evidence of their bias.","zh":"當人們看到自己偏誤的證據時，他們感到懷疑。"},{"en":"Skeptical means doubtful and not easily convinced.","zh":"skeptical 指抱懷疑態度，不容易被說服。"},{"en":"Parents may be skeptical of a new school policy until they see clear results.","zh":"家長可能在看到清楚結果前，對新校政感到懷疑。"},{"en":"If consumers are skeptical, advertisements alone may not persuade them.","zh":"如果消費者懷疑，單靠廣告未必能說服他們。"},{"en":"This word describes a questioning attitude.","zh":"這個詞描述質疑態度。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":16},{"front":"more than a bit defensive","meaning":"相當有戒心；頗為自辯","examples":[{"en":"People became more than a bit defensive when confronted with the evidence.","zh":"當面對證據時，人們變得相當有戒心。"},{"en":"More than a bit defensive means quite defensive or strongly ready to protect oneself from criticism.","zh":"more than a bit defensive 指頗為自辯，或強烈準備保護自己免受批評。"},{"en":"A student may become more than a bit defensive when a teacher points out repeated mistakes.","zh":"當老師指出反覆錯誤，學生可能變得相當自辯。"},{"en":"If people feel accused of bias, they may become defensive instead of learning from the evidence.","zh":"如果人們覺得自己被指有偏誤，可能變得自辯，而不是從證據中學習。"},{"en":"This phrase suggests a stronger reaction than mild discomfort.","zh":"這個片語暗示比輕微不適更強的反應。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":16},{"front":"behavioral tendencies","meaning":"行為傾向","examples":[{"en":"These behavioral tendencies are universal.","zh":"這些行為傾向是普遍的。"},{"en":"Behavioral tendencies are common patterns in how people usually act.","zh":"behavioral tendencies 是人們通常如何行動的常見模式。"},{"en":"A tendency to avoid difficult homework is a behavioral tendency many students recognise.","zh":"避免困難功課的傾向，是許多學生都認得的行為傾向。"},{"en":"If behavioral tendencies are universal, they appear across many groups and cultures.","zh":"如果行為傾向是普遍的，它們會出現在許多群體和文化中。"},{"en":"This phrase describes repeated habits of action, not one-time choices.","zh":"這個片語描述反覆出現的行動習慣，而不是一次性選擇。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":16},{"front":"awareness of them","meaning":"對它們的認知","examples":[{"en":"These tendencies are universal, but awareness of them is not.","zh":"這些傾向是普遍的，但對它們的認知並非如此。"},{"en":"Awareness of them means knowing that these tendencies exist and may affect behaviour.","zh":"awareness of them 指知道這些傾向存在，並可能影響行為。"},{"en":"Awareness of bad study habits helps students change them earlier.","zh":"對不良學習習慣的認知幫助學生更早改變它們。"},{"en":"If people lack awareness of their biases, they may keep making the same choices.","zh":"如果人們缺乏對自己偏誤的認知，可能繼續作出相同選擇。"},{"en":"This phrase separates having a tendency from knowing about it.","zh":"這個片語把擁有傾向與知道它存在分開。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":16},{"front":"match each person with","meaning":"將每個人物與……配對","examples":[{"en":"Students match each person with the opinion or action attributed to them.","zh":"學生將每個人物與歸因於他們的觀點或行動配對。"},{"en":"To match each person with something means to connect every named person to the correct item.","zh":"match each person with something 指把每個具名人物與正確項目連接。"},{"en":"In a reading task, students may match each researcher with their view.","zh":"在閱讀題中，學生可能把每位研究者與其觀點配對。"},{"en":"If several people are mentioned, matching helps test careful understanding of who said what.","zh":"如果提到幾個人物，配對有助測試是否仔細理解誰說了甚麼。"},{"en":"This phrase is common in exam instructions.","zh":"這個片語常見於考試指示。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":16},{"front":"opinion or action attributed to","meaning":"歸因於……的觀點或行動","examples":[{"en":"The task asks for the opinion or action attributed to each person.","zh":"這項任務要求找出歸因於每個人物的觀點或行動。"},{"en":"An opinion or action attributed to someone is a view or behaviour linked to that person in the text.","zh":"opinion or action attributed to someone 是文本中連繫到某人的看法或行為。"},{"en":"A reading question may ask which opinion is attributed to a scientist.","zh":"閱讀題可能要求找出哪個觀點歸因於某位科學家。"},{"en":"If students confuse who an action is attributed to, they may choose the wrong answer.","zh":"如果學生混淆某行動歸因於誰，可能選錯答案。"},{"en":"This phrase tests source tracking, not just general understanding.","zh":"這個片語測試來源追蹤，而不只是一般理解。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":16},{"front":"proposed a theory","meaning":"提出理論","examples":[{"en":"One scholar proposed a theory about new-product adoption.","zh":"一位學者提出了一個關於新產品採用的理論。"},{"en":"To propose a theory means to suggest an explanation for how or why something happens.","zh":"propose a theory 指提出一個解釋某事如何或為何發生的想法。"},{"en":"A teacher may propose a theory about why students forget vocabulary quickly.","zh":"老師可能提出一個理論，解釋學生為何很快忘記詞彙。"},{"en":"If a theory is proposed, other researchers can test whether evidence supports it.","zh":"如果理論被提出，其他研究人員可以測試證據是否支持它。"},{"en":"This phrase introduces an explanatory idea, not a proven fact by itself.","zh":"這個片語引入解釋性想法，而不是本身已證明的事實。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":17},{"front":"potential flaw","meaning":"潛在缺陷","examples":[{"en":"The theory had a potential flaw in its application.","zh":"這個理論在其應用方面有一個潛在缺陷。"},{"en":"A potential flaw is a possible weakness that may cause problems later.","zh":"potential flaw 是日後可能造成問題的弱點。"},{"en":"A timetable may have a potential flaw if it gives students no lunch break.","zh":"如果時間表沒有午膳時間，它可能有一個潛在缺陷。"},{"en":"If a theory ignores psychological bias, that potential flaw may affect real-world use.","zh":"如果理論忽視心理偏誤，該潛在缺陷可能影響現實應用。"},{"en":"This phrase warns that something may be weaker than it first appears.","zh":"這個片語警告某事可能比起初看來更薄弱。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":17},{"front":"in its application","meaning":"在其應用方面","examples":[{"en":"The flaw became clear in the theory’s application.","zh":"這個缺陷在該理論的應用方面變得清楚。"},{"en":"In its application means when an idea is used in real situations.","zh":"in its application 指當某想法被用於真實情況時。"},{"en":"A grammar rule may seem simple, but problems appear in its application to real sentences.","zh":"文法規則可能看似簡單，但在應用到真實句子時會出現問題。"},{"en":"If a business theory fails in its application, the market may not behave as expected.","zh":"如果商業理論在應用方面失敗，市場可能不按預期行動。"},{"en":"This phrase contrasts theory with practical use.","zh":"這個片語對比理論與實際使用。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":17},{"front":"identify several features of","meaning":"識別……的幾個特徵","examples":[{"en":"Researchers identified several features of consumer behavior.","zh":"研究人員識別了消費者行為的幾個特徵。"},{"en":"To identify several features of something means to find and name a number of important characteristics.","zh":"identify several features of something 指找出並指出某事的幾個重要特徵。"},{"en":"A teacher may identify several features of strong writing, such as clarity and examples.","zh":"老師可能識別優秀寫作的幾個特徵，例如清晰和例子。"},{"en":"If researchers identify features of behaviour, companies can understand consumers more clearly.","zh":"如果研究人員識別行為特徵，公司就能更清楚理解消費者。"},{"en":"This phrase is useful for analysis and classification.","zh":"這個片語適用於分析和分類。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":17},{"front":"consumer behavior","meaning":"消費者行為","examples":[{"en":"The passage discusses consumer behavior when people face alternatives.","zh":"文章討論人們面對替代選擇時的消費者行為。"},{"en":"Consumer behavior means how people choose, buy, use, or reject products and services.","zh":"consumer behavior 指人們如何選擇、購買、使用或拒絕產品和服務。"},{"en":"Supermarkets study consumer behavior to decide where to place snacks and drinks.","zh":"超級市場研究消費者行為，以決定零食和飲品放在哪裡。"},{"en":"If consumer behavior is shaped by bias, sales may not follow objective product quality.","zh":"如果消費者行為受偏誤塑造，銷售未必跟隨客觀產品質素。"},{"en":"This phrase focuses on real customer actions and decisions.","zh":"這個片語聚焦於真實顧客行動和決策。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":17},{"front":"face alternatives","meaning":"面對替代選擇","examples":[{"en":"Consumers behave differently when they face alternatives.","zh":"當消費者面對替代選擇時，他們會有不同行為。"},{"en":"To face alternatives means to have different choices available.","zh":"face alternatives 指有不同選擇可用。"},{"en":"A student faces alternatives when choosing between a part-time job and extra study time.","zh":"學生在兼職和額外溫習時間之間選擇時，就是面對替代選擇。"},{"en":"If consumers face alternatives, they compare gains and losses against what they already have.","zh":"如果消費者面對替代選擇，他們會把收益和損失與自己已擁有的東西比較。"},{"en":"This phrase describes a decision situation with more than one option.","zh":"這個片語描述有多於一個選項的決策情況。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":17},{"front":"argue that","meaning":"主張；認為","examples":[{"en":"Thaler argued that customers value possessions highly.","zh":"Thaler 主張顧客高度重視擁有物。"},{"en":"To argue that something is true means to give reasons for believing it.","zh":"argue that something is true 指提出理由支持某事為真。"},{"en":"A student may argue that homework should be shorter but more focused.","zh":"學生可能主張功課應較短但更集中。"},{"en":"Researchers argue that ownership changes value when experiments show sellers demand more.","zh":"當實驗顯示賣方要求更多時，研究人員主張擁有權會改變價值。"},{"en":"This phrase introduces a claim supported by reasoning.","zh":"這個片語引入由理由支持的主張。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":17},{"front":"value possessions","meaning":"重視擁有物","examples":[{"en":"Customers value possessions they may give up more highly.","zh":"顧客更高度重視自己可能放棄的擁有物。"},{"en":"To value possessions means to place importance or worth on things one owns.","zh":"value possessions 指重視自己擁有物品的重要性或價值。"},{"en":"A family may value possessions like old photos because they carry memories.","zh":"家庭可能重視舊照片等擁有物，因為它們承載回憶。"},{"en":"If people value possessions too highly, they may avoid exchanging them for better items.","zh":"如果人們過度重視擁有物，可能避免用它們交換更好的物品。"},{"en":"This phrase links ownership with emotional and perceived value.","zh":"這個片語把擁有權與情感和感知價值連接起來。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":17},{"front":"replace existing products","meaning":"替換現有產品","examples":[{"en":"Status quo bias explains why people do not replace existing products.","zh":"現狀偏誤解釋為何人們不替換現有產品。"},{"en":"To replace existing products means to stop using current products and use new ones instead.","zh":"replace existing products 指停止使用目前產品，改用新產品。"},{"en":"A school may replace existing textbooks with digital materials.","zh":"學校可能用電子材料替換現有教科書。"},{"en":"If replacing existing products feels risky, customers may keep the old ones.","zh":"如果替換現有產品感覺有風險，顧客可能保留舊產品。"},{"en":"This phrase describes substitution, not simply adding one more product.","zh":"這個片語描述替代，而不只是多加一件產品。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":17},{"front":"agree with the information","meaning":"與資料一致","examples":[{"en":"Students decide whether each statement agrees with the information.","zh":"學生判斷每個陳述是否與資料一致。"},{"en":"To agree with the information means to match what the passage says.","zh":"agree with the information 指與文章所說內容相符。"},{"en":"If a passage says products often fail, a statement saying all products succeed does not agree with the information.","zh":"如果文章說產品常常失敗，而陳述說所有產品都成功，便不是與資料一致。"},{"en":"Students must compare meaning, not just identical words.","zh":"學生必須比較意思，而不只是相同字眼。"},{"en":"This phrase is common in TRUE/FALSE/NOT GIVEN reading tasks.","zh":"這個片語常見於 TRUE/FALSE/NOT GIVEN 閱讀題。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":17},{"front":"contradicts the information","meaning":"與資料相矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與文章中的資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"contradict the information 指說出與文本內容相反的意思。"},{"en":"If the passage says many products fail, “almost none fail” contradicts the information.","zh":"如果文章說許多產品失敗，「幾乎沒有產品失敗」便與資料相矛盾。"},{"en":"Students should choose FALSE when the statement clearly contradicts the passage.","zh":"當陳述清楚與文章矛盾時，學生應選 FALSE。"},{"en":"This phrase is different from NOT GIVEN because the passage gives opposite information.","zh":"這個片語不同於 NOT GIVEN，因為文章提供了相反資料。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":17},{"front":"there is no information on this","meaning":"沒有關於這方面的資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有關於這方面的資料，學生則寫 NOT GIVEN。"},{"en":"There is no information on this means the passage does not mention that point.","zh":"there is no information on this 指文章沒有提及該點。"},{"en":"If the text discusses customer bias but not gender differences, there is no information on gender.","zh":"如果文本討論顧客偏誤但沒有討論性別差異，便沒有關於性別方面的資料。"},{"en":"Students should not guess from outside knowledge when there is no information on this.","zh":"當沒有關於這方面的資料時，學生不應用外部知識猜測。"},{"en":"This phrase signals absence of evidence in the passage.","zh":"這個片語表示文章中缺乏證據。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":18},{"front":"outperform existing alternatives","meaning":"表現優於現有替代選擇","examples":[{"en":"Innovative products may outperform existing alternatives.","zh":"創新產品可能表現優於現有替代選擇。"},{"en":"To outperform existing alternatives means to work better than current available choices.","zh":"outperform existing alternatives 指比目前可用的選擇表現更好。"},{"en":"A new train app may outperform paper timetables by giving live updates.","zh":"新火車應用程式透過提供即時更新，可能表現優於紙本時間表。"},{"en":"Even if a product outperforms alternatives, customers may resist if switching feels costly.","zh":"即使產品表現優於替代選擇，如果轉換感覺有成本，顧客仍可能抗拒。"},{"en":"This phrase compares performance, not emotional acceptance.","zh":"這個片語比較性能，而不是情感接受度。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":18},{"front":"be guaranteed to","meaning":"保證會","examples":[{"en":"Superior products are not guaranteed to gain market share.","zh":"較優越產品並不保證會增加市場佔有率。"},{"en":"To be guaranteed to do something means to be certain to do it.","zh":"be guaranteed to do something 指肯定會做某事。"},{"en":"A high exam mark is not guaranteed just because a student buys expensive notes.","zh":"學生買昂貴筆記並不保證會取得高分。"},{"en":"A better product is not guaranteed to succeed if consumers dislike change.","zh":"如果消費者不喜歡改變，更好的產品也不保證會成功。"},{"en":"This phrase separates possibility from certainty.","zh":"這個片語把可能性與確定性分開。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":18},{"front":"gain market share","meaning":"增加市場佔有率","examples":[{"en":"A new product may fail even if it should gain market share.","zh":"即使新產品理應增加市場佔有率，它也可能失敗。"},{"en":"To gain market share means to increase the percentage of sales a company or product holds in a market.","zh":"gain market share 指增加公司或產品在市場銷售中的百分比。"},{"en":"A small café can gain market share if customers leave a larger chain for better service.","zh":"如果顧客因更好服務離開大型連鎖店，小咖啡店可以增加市場佔有率。"},{"en":"If consumers reject a product, it will not gain market share even with strong features.","zh":"如果消費者拒絕產品，即使功能強大，它也不會增加市場佔有率。"},{"en":"This phrase measures business success against competitors.","zh":"這個片語以競爭者為基準衡量商業成功。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":18},{"front":"recognition of the benefits of","meaning":"對……好處的認識","examples":[{"en":"Companies’ recognition of the benefits of switching does not guarantee success.","zh":"公司對轉換好處的認識並不保證成功。"},{"en":"Recognition of the benefits of something means understanding or acknowledging its advantages.","zh":"recognition of the benefits of something 指理解或承認某事的優勢。"},{"en":"A school’s recognition of the benefits of exercise may lead to more sports time.","zh":"學校對運動好處的認識可能帶來更多體育時間。"},{"en":"Even if companies recognise benefits, consumers may focus on losses instead.","zh":"即使公司認識到好處，消費者可能反而聚焦於損失。"},{"en":"This phrase shows awareness of advantages, not necessarily action.","zh":"這個片語顯示對優勢的認知，而不一定是行動。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":18},{"front":"benefits of switching","meaning":"轉換的好處","examples":[{"en":"Consumers may ignore the benefits of switching to a new product.","zh":"消費者可能忽視轉用新產品的好處。"},{"en":"Benefits of switching are the advantages gained by changing from one option to another.","zh":"benefits of switching 是從一個選項轉到另一個選項後獲得的優勢。"},{"en":"The benefits of switching banks may include lower fees and better online service.","zh":"轉換銀行的好處可能包括較低費用和更好網上服務。"},{"en":"If the benefits of switching are not large enough, people may stay with the old product.","zh":"如果轉換的好處不夠大，人們可能留在舊產品。"},{"en":"This phrase contrasts gains from change with losses from giving something up.","zh":"這個片語把改變帶來的收益與放棄某物的損失作對比。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":18},{"front":"perceptions of losses and gains","meaning":"對損失和收益的看法","examples":[{"en":"The statement asks whether gender affects perceptions of losses and gains.","zh":"該陳述問性別是否影響對損失和收益的看法。"},{"en":"Perceptions of losses and gains are the ways people feel and judge what they lose or receive.","zh":"perceptions of losses and gains 是人們感受和判斷自己失去或得到甚麼的方式。"},{"en":"Two students may have different perceptions of losses and gains when choosing between study time and free time.","zh":"兩名學生在溫習時間和自由時間之間選擇時，可能對損失和收益有不同看法。"},{"en":"If perceptions of losses are stronger, people may reject offers with real benefits.","zh":"如果對損失的感受更強，人們可能拒絕有真實好處的提議。"},{"en":"This phrase focuses on how gains and losses are experienced, not just measured.","zh":"這個片語聚焦於收益和損失如何被體驗，而不只是量度。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":18},{"front":"in the marketplace","meaning":"在市場中","examples":[{"en":"Consumer choices in the marketplace are affected by bias.","zh":"市場中的消費者選擇受偏誤影響。"},{"en":"In the marketplace means in the world of buying and selling products or services.","zh":"in the marketplace 指在買賣產品或服務的世界中。"},{"en":"A new drink must compete with many familiar brands in the marketplace.","zh":"新飲品必須在市場中與許多熟悉品牌競爭。"},{"en":"If bias affects behaviour in the marketplace, better products may not win automatically.","zh":"如果偏誤影響市場中的行為，更好的產品未必會自動勝出。"},{"en":"This phrase refers to real commercial settings, not only theory.","zh":"這個片語指真實商業環境，而不只是理論。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":18},{"front":"a large gap between","meaning":"……之間的巨大差距","examples":[{"en":"The experiment showed a large gap between sellers’ prices and choosers’ offers.","zh":"實驗顯示賣方價格與選擇者出價之間的巨大差距。"},{"en":"A large gap between two things means a big difference separates them.","zh":"a large gap between two things 指兩者之間有很大差異。"},{"en":"There may be a large gap between what students think they know and what the test shows.","zh":"學生以為自己懂的內容與測驗顯示的結果之間，可能有巨大差距。"},{"en":"If there is a large gap between selling and buying prices, trade may not happen.","zh":"如果賣價和買價之間有巨大差距，交易可能不會發生。"},{"en":"This phrase highlights a clear difference between two measures or groups.","zh":"這個片語突出兩個量度或群體之間的清楚差異。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":18},{"front":"asking prices","meaning":"要價","examples":[{"en":"Sellers’ asking prices were much higher than choosers’ offers.","zh":"賣方要價遠高於選擇者出價。"},{"en":"Asking prices are the prices sellers request for selling something.","zh":"asking prices 是賣方出售某物時要求的價格。"},{"en":"A flat may have a high asking price even if buyers offer much less.","zh":"單位要價可能很高，即使買方出價低得多。"},{"en":"If asking prices are too high, products may remain unsold.","zh":"如果要價太高，產品可能賣不出去。"},{"en":"This phrase refers to what sellers want, not necessarily what buyers pay.","zh":"這個片語指賣方想要的價格，不一定是買方實付價格。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":18},{"front":"choosers’ offers","meaning":"選擇者的出價","examples":[{"en":"Choosers’ offers were lower than sellers’ asking prices.","zh":"選擇者的出價低於賣方要價。"},{"en":"Choosers’ offers are the amounts that people without the item are willing to pay.","zh":"choosers’ offers 是沒有該物品的人願意支付的金額。"},{"en":"In a class experiment, choosers’ offers may show how much students value a prize they do not own.","zh":"在課堂實驗中，選擇者的出價可能顯示學生如何估值自己未擁有的獎品。"},{"en":"If choosers’ offers are low, ownership may explain why sellers ask for more.","zh":"如果選擇者的出價低，擁有權可能解釋為何賣方要求更多。"},{"en":"This phrase represents buyer-side valuation.","zh":"這個片語代表買方角度的估值。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":18},{"front":"calmly accept evidence","meaning":"平靜接受證據","examples":[{"en":"People do not always calmly accept evidence of their own bias.","zh":"人們不一定會平靜接受自己偏誤的證據。"},{"en":"To calmly accept evidence means to receive proof without becoming angry, defensive, or dismissive.","zh":"calmly accept evidence 指在不生氣、不自辯、不否定的情況下接受證據。"},{"en":"A student calmly accepts evidence when they admit an answer is wrong after checking the passage.","zh":"學生核對文章後承認答案錯誤，就是平靜接受證據。"},{"en":"If people cannot calmly accept evidence, correcting bias becomes harder.","zh":"如果人們不能平靜接受證據，修正偏誤會更困難。"},{"en":"This phrase contrasts open-minded response with emotional resistance.","zh":"這個片語對比開放心態回應與情緒抗拒。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":19},{"front":"exhibit status quo bias","meaning":"表現出現狀偏誤","examples":[{"en":"Consumers may exhibit status quo bias without realizing it.","zh":"消費者可能在沒有察覺下表現出現狀偏誤。"},{"en":"To exhibit status quo bias means to show a preference for keeping the current situation.","zh":"exhibit status quo bias 指表現出偏好維持現況的傾向。"},{"en":"A worker exhibits status quo bias when they refuse new software only because the old one is familiar.","zh":"員工只因舊軟件熟悉而拒絕新軟件，就是表現出現狀偏誤。"},{"en":"If customers exhibit status quo bias, they may ignore a product’s objective benefits.","zh":"如果顧客表現出現狀偏誤，可能忽視產品的客觀好處。"},{"en":"This phrase describes bias shown through behaviour.","zh":"這個片語描述透過行為顯示出的偏誤。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":19},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter for each answer.","zh":"學生為每個答案選出正確字母。"},{"en":"To choose the correct letter means to select the answer option that matches the passage.","zh":"choose the correct letter 指選擇與文章相符的答案選項。"},{"en":"In a reading test, students may choose the correct letter after comparing all options carefully.","zh":"在閱讀測驗中，學生可能在仔細比較所有選項後選出正確字母。"},{"en":"If students rush, they may choose the wrong letter even when they understand the passage.","zh":"如果學生匆忙，即使理解文章，也可能選錯字母。"},{"en":"This phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":19},{"front":"illustrate about","meaning":"說明關於……","examples":[{"en":"The question asks what paragraph A illustrates about business ventures.","zh":"題目問 A 段說明關於商業項目的甚麼。"},{"en":"To illustrate about something means to show or explain a point about it through an example.","zh":"illustrate about something 指透過例子展示或解釋關於某事的重點。"},{"en":"A story about a failed shop can illustrate how rent affects small businesses.","zh":"一個失敗小店的故事可以說明租金如何影響小企業。"},{"en":"If a paragraph illustrates product failure, students should identify the general lesson it shows.","zh":"如果某段說明產品失敗，學生應識別它展示的一般教訓。"},{"en":"This phrase asks what example or evidence demonstrates.","zh":"這個片語問例子或證據展示甚麼。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":19},{"front":"innovative business ventures","meaning":"創新商業項目","examples":[{"en":"Many innovative business ventures fail.","zh":"許多創新商業項目失敗。"},{"en":"Innovative business ventures are new business projects based on fresh ideas or products.","zh":"innovative business ventures 是基於新想法或新產品的商業項目。"},{"en":"A food delivery start-up can be an innovative business venture.","zh":"食物外送初創公司可以是一個創新商業項目。"},{"en":"Innovative business ventures may fail if customers do not change habits quickly enough.","zh":"如果顧客沒有足夠快地改變習慣，創新商業項目可能失敗。"},{"en":"This phrase describes new commercial attempts, not guaranteed success.","zh":"這個片語描述新的商業嘗試，而不是保證成功。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":19},{"front":"remain in warehouses","meaning":"留在倉庫中","examples":[{"en":"The option says many products remain in warehouses.","zh":"這個選項說許多產品留在倉庫中。"},{"en":"To remain in warehouses means to stay stored and unsold instead of reaching customers.","zh":"remain in warehouses 指被儲存起來而沒有售出或到達顧客手中。"},{"en":"Unsold winter coats may remain in warehouses if the weather is unusually warm.","zh":"如果天氣異常溫暖，未售出的冬季外套可能留在倉庫中。"},{"en":"If products remain in warehouses, the company may lose money on storage and production.","zh":"如果產品留在倉庫中，公司可能在儲存和生產上虧損。"},{"en":"This phrase suggests poor sales or failed distribution.","zh":"這個片語暗示銷售差或配送失敗。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":19},{"front":"roughly half","meaning":"大約一半","examples":[{"en":"Roughly half of some new-product ventures fail.","zh":"某些新產品商業項目中大約一半會失敗。"},{"en":"Roughly half means about one out of every two, not exactly half.","zh":"roughly half 指大約每兩個中有一個，不一定正好一半。"},{"en":"Roughly half the class preferred online quizzes to paper worksheets.","zh":"大約一半班級較喜歡網上小測而不是紙本工作紙。"},{"en":"If roughly half of ventures fail, innovation is risky even for early movers.","zh":"如果大約一半項目失敗，即使對先行者來說創新也有風險。"},{"en":"This phrase gives an approximate proportion.","zh":"這個片語給出近似比例。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":19},{"front":"new-product ventures","meaning":"新產品商業項目","examples":[{"en":"New-product ventures can fail despite innovation.","zh":"新產品商業項目即使具有創新，也可能失敗。"},{"en":"New-product ventures are business projects built around launching new products.","zh":"new-product ventures 是圍繞推出新產品而建立的商業項目。"},{"en":"A company’s smart kitchen device may become a new-product venture.","zh":"公司的智能廚房裝置可能成為新產品商業項目。"},{"en":"If consumers reject the product, the whole venture may fail.","zh":"如果消費者拒絕該產品，整個商業項目可能失敗。"},{"en":"This phrase focuses on the commercial attempt behind a new product.","zh":"這個片語聚焦於新產品背後的商業嘗試。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":19},{"front":"have a long lifespan","meaning":"有很長壽命","examples":[{"en":"Many new products do not have a long lifespan.","zh":"許多新產品沒有很長壽命。"},{"en":"To have a long lifespan means to last for a long time before disappearing or being replaced.","zh":"have a long lifespan 指在消失或被取代前持續很長時間。"},{"en":"A school textbook has a long lifespan if it is used for many years.","zh":"如果學校教科書被使用多年，它就有很長壽命。"},{"en":"If a product does not have a long lifespan, it may be removed from shelves quickly.","zh":"如果產品沒有很長壽命，它可能很快從貨架上被移走。"},{"en":"This phrase describes durability or survival over time.","zh":"這個片語描述耐用性或隨時間生存的能力。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":19},{"front":"tend to believe","meaning":"往往相信","examples":[{"en":"Experts and novices tend to believe failed products were bad ideas.","zh":"專家和新手往往相信失敗產品本來就是壞主意。"},{"en":"To tend to believe something means to usually think it is true.","zh":"tend to believe something 指通常認為某事是真的。"},{"en":"Students may tend to believe grammar is difficult if early lessons feel confusing.","zh":"如果早期課堂感覺混亂，學生可能往往相信文法很難。"},{"en":"If people tend to believe failure proves a bad idea, they may ignore market psychology.","zh":"如果人們往往相信失敗證明想法差，可能忽略市場心理。"},{"en":"This phrase describes a common mental habit.","zh":"這個片語描述常見心理習慣。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":19},{"front":"make a product sell well","meaning":"令產品暢銷","examples":[{"en":"The question asks what makes a product sell well.","zh":"題目問甚麼令產品暢銷。"},{"en":"To make a product sell well means to help it attract many buyers.","zh":"make a product sell well 指幫助產品吸引許多買家。"},{"en":"Clear benefits and easy use can make a product sell well.","zh":"清楚好處和易用性可以令產品暢銷。"},{"en":"If consumers fear switching costs, objective quality alone may not make a product sell well.","zh":"如果消費者害怕轉換成本，單靠客觀質素未必令產品暢銷。"},{"en":"This phrase focuses on real sales, not only product design.","zh":"這個片語聚焦於真實銷售，而不只是產品設計。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":19},{"front":"sufficiently creative and innovative","meaning":"具足夠創意和創新性","examples":[{"en":"A product may be creative and innovative but still fail.","zh":"產品可能具創意和創新性，但仍然失敗。"},{"en":"Sufficiently creative and innovative means having enough originality and newness.","zh":"sufficiently creative and innovative 指有足夠原創性和新穎性。"},{"en":"A lesson can be creative and innovative if it uses games, stories, and technology well.","zh":"如果課堂善用遊戲、故事和科技，它可以具創意和創新性。"},{"en":"Even a sufficiently innovative product may fail if consumers do not want to change behaviour.","zh":"即使產品具足夠創新性，如果消費者不想改變行為，也可能失敗。"},{"en":"This phrase shows that creativity alone may not solve adoption problems.","zh":"這個片語顯示單靠創意未必能解決採用問題。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":20},{"front":"chain stores","meaning":"連鎖店","examples":[{"en":"The option mentions having more chain stores.","zh":"這個選項提到擁有更多連鎖店。"},{"en":"Chain stores are shops with the same brand and management in many locations.","zh":"chain stores 是在多個地點有相同品牌和管理的店舖。"},{"en":"A coffee chain may open chain stores near stations and shopping malls.","zh":"咖啡連鎖品牌可能在車站和商場附近開設連鎖店。"},{"en":"More chain stores can increase access, but they do not guarantee product adoption.","zh":"更多連鎖店可以增加接觸機會，但不保證產品被採用。"},{"en":"This phrase refers to retail expansion through repeated store formats.","zh":"這個片語指透過重複店舖形式進行零售擴張。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":20},{"front":"learn from a famous company","meaning":"向著名公司學習","examples":[{"en":"The option mentions learning from a famous company.","zh":"這個選項提到向著名公司學習。"},{"en":"To learn from a famous company means to study its methods, success, or mistakes.","zh":"learn from a famous company 指研究其方法、成功或錯誤。"},{"en":"A small shop may learn from a famous company by improving customer service.","zh":"小店可能透過改善顧客服務向著名公司學習。"},{"en":"If a famous company failed, others can learn from its mistakes before launching a product.","zh":"如果著名公司失敗，其他公司可以在推出產品前從其錯誤中學習。"},{"en":"This phrase focuses on using another company as a lesson or model.","zh":"這個片語聚焦於把另一公司作為教訓或模式。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":20},{"front":"such as","meaning":"例如","examples":[{"en":"A famous company such as Webvan may be used as an example.","zh":"Webvan 這樣的著名公司可能被用作例子。"},{"en":"Such as means for example and introduces one or more examples.","zh":"such as 意思是「例如」，用來引入一個或多個例子。"},{"en":"Students need basic tools such as pens, notebooks, and dictionaries.","zh":"學生需要基本工具，例如筆、筆記本和字典。"},{"en":"Companies such as failed pioneers can show why innovation alone is not enough.","zh":"失敗先行者等公司可以顯示為何單靠創新不足夠。"},{"en":"This phrase helps make a general category more concrete.","zh":"這個片語幫助把一般類別變得更具體。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":20},{"front":"according to the passage","meaning":"根據文章","examples":[{"en":"According to the passage, many products fail because companies ignore psychology.","zh":"根據文章，許多產品失敗是因為公司忽視心理。"},{"en":"According to the passage means based on what the reading text says.","zh":"according to the passage 指根據閱讀文本所說。"},{"en":"According to the passage, students should not use outside knowledge for TRUE/FALSE questions.","zh":"根據文章，學生不應在 TRUE/FALSE 題使用外部知識。"},{"en":"If an answer is according to the passage, it must be supported by the text.","zh":"如果答案根據文章，它必須有文本支持。"},{"en":"This phrase reminds students to rely on source information.","zh":"這個片語提醒學生依賴來源資料。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":20},{"front":"ignore the fact that","meaning":"忽視……這一事實","examples":[{"en":"Companies ignore the fact that people overvalue products they own.","zh":"公司忽視人們高估自己擁有產品這一事實。"},{"en":"To ignore the fact that something is true means to fail or refuse to consider it.","zh":"ignore the fact that something is true 指未能或拒絕考慮某事實。"},{"en":"A school should not ignore the fact that tired students learn less effectively.","zh":"學校不應忽視疲倦學生學習效率較低這一事實。"},{"en":"If companies ignore the fact that consumers fear loss, their product launches may fail.","zh":"如果公司忽視消費者害怕損失這一事實，產品推出可能失敗。"},{"en":"This phrase points to an important truth being overlooked.","zh":"這個片語指出重要真相被忽略。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":20},{"front":"lack confidence in","meaning":"對……缺乏信心","examples":[{"en":"The passage does not suggest that companies lack confidence in their products.","zh":"文章並沒有指出公司對自己的產品缺乏信心。"},{"en":"To lack confidence in something means to have little trust or belief in it.","zh":"lack confidence in something 指對某事缺乏信任或信念。"},{"en":"A student may lack confidence in speaking English after several mistakes.","zh":"學生在犯幾次錯後可能對說英語缺乏信心。"},{"en":"If companies lacked confidence in a product, they might not invest heavily in it.","zh":"如果公司對產品缺乏信心，可能不會大力投資。"},{"en":"This phrase describes doubt, not simple caution.","zh":"這個片語描述懷疑，而不是簡單謹慎。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":20},{"front":"be familiar with","meaning":"熟悉","examples":[{"en":"Companies are often not familiar with consumers’ psychological biases.","zh":"公司常不熟悉消費者的心理偏誤。"},{"en":"To be familiar with something means to know or understand it well.","zh":"be familiar with something 指熟悉或充分理解某事。"},{"en":"A student who is familiar with exam instructions makes fewer format mistakes.","zh":"熟悉考試指示的學生會少犯格式錯誤。"},{"en":"If managers are not familiar with loss aversion, they may misread customer resistance.","zh":"如果管理層不熟悉損失厭惡，可能誤讀顧客抗拒。"},{"en":"This phrase describes knowledge gained through learning or experience.","zh":"這個片語描述透過學習或經驗獲得的認識。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":20},{"front":"psychological states","meaning":"心理狀態","examples":[{"en":"The option refers to consumers’ psychological states.","zh":"這個選項指消費者的心理狀態。"},{"en":"Psychological states are people’s mental or emotional conditions at a particular time.","zh":"psychological states 是人在某一時間的心理或情緒狀況。"},{"en":"Stress, confidence, fear, and excitement are psychological states that affect decisions.","zh":"壓力、信心、恐懼和興奮都是影響決策的心理狀態。"},{"en":"If customers’ psychological states include anxiety, they may avoid unfamiliar products.","zh":"如果顧客的心理狀態包括焦慮，他們可能避開不熟悉產品。"},{"en":"This phrase focuses on inner feelings and mental conditions.","zh":"這個片語聚焦於內在感受和心理情況。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":20},{"front":"fail to mention","meaning":"未有提及","examples":[{"en":"The option suggests that companies fail to mention product advantages.","zh":"這個選項指出公司未有提及產品優勢。"},{"en":"To fail to mention something means not to say or include it.","zh":"fail to mention something 指沒有說出或包括某事。"},{"en":"A student may fail to mention the main reason in a summary answer.","zh":"學生可能在摘要答案中未有提及主要原因。"},{"en":"If an advertisement fails to mention switching costs, customers may still notice them later.","zh":"如果廣告未有提及轉換成本，顧客之後仍可能注意到它們。"},{"en":"This phrase points to missing information in speech or writing.","zh":"這個片語指出說話或寫作中遺漏的資訊。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":20},{"front":"the status quo bias experiment","meaning":"現狀偏誤實驗","examples":[{"en":"The status quo bias experiment showed that people avoid exchanging products.","zh":"現狀偏誤實驗顯示人們避免交換產品。"},{"en":"The status quo bias experiment is a test showing people’s tendency to keep what they already have.","zh":"status quo bias experiment 是顯示人們傾向保留已擁有物品的測試。"},{"en":"In a classroom, a similar experiment could compare whether students keep a pen they were given.","zh":"在課室中，相似實驗可以比較學生是否保留派給他們的筆。"},{"en":"If few people exchange items, the experiment suggests ownership affects choice.","zh":"如果很少人交換物品，實驗便暗示擁有權影響選擇。"},{"en":"This phrase refers to evidence about preference for the current situation.","zh":"這個片語指關於偏好現況的證據。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":20},{"front":"suggest","meaning":"顯示；暗示","examples":[{"en":"The experiment suggests that ownership affects preference.","zh":"實驗顯示擁有權會影響偏好。"},{"en":"To suggest means to show indirectly or make something seem likely.","zh":"suggest 指間接顯示或令某事看似可能。"},{"en":"A student’s repeated mistakes may suggest that they need clearer grammar practice.","zh":"學生反覆犯錯可能顯示他需要更清晰文法練習。"},{"en":"If many owners refuse to exchange, the result suggests status quo bias.","zh":"如果許多擁有者拒絕交換，結果便暗示現狀偏誤。"},{"en":"This word is weaker than prove but still points toward a conclusion.","zh":"這個詞比 prove 弱，但仍指向結論。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":21},{"front":"participants","meaning":"參加者","examples":[{"en":"The participants were students in the experiment.","zh":"參加者是實驗中的學生。"},{"en":"Participants are people who take part in a study, event, or activity.","zh":"participants 是參與研究、活動或事件的人。"},{"en":"Participants in a school survey may answer questions about homework habits.","zh":"學校調查的參加者可能回答關於功課習慣的問題。"},{"en":"If participants behave differently after receiving an item, researchers can study ownership effects.","zh":"如果參加者在收到物品後行為不同，研究人員便可以研究擁有權效應。"},{"en":"This word refers to the people involved in the test.","zh":"這個詞指參與測試的人。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":21},{"front":"be willing to exchange","meaning":"願意交換","examples":[{"en":"Only a small percentage of participants were willing to exchange their products.","zh":"只有小部分參加者願意交換自己的產品。"},{"en":"To be willing to exchange means to be ready to swap one item for another.","zh":"be willing to exchange 指準備把一件物品換成另一件。"},{"en":"A customer may be willing to exchange a shirt if the colour is wrong.","zh":"如果顏色不合，顧客可能願意交換恤衫。"},{"en":"If few people are willing to exchange, ownership may have made the original item feel more valuable.","zh":"如果很少人願意交換，擁有權可能令原有物品感覺更有價值。"},{"en":"This phrase focuses on readiness to trade.","zh":"這個片語聚焦於交換意願。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":21},{"front":"welcome new items","meaning":"歡迎新物品","examples":[{"en":"The experiment did not show that students always welcome new items.","zh":"實驗沒有顯示學生總是歡迎新物品。"},{"en":"To welcome new items means to accept or respond positively to new things.","zh":"welcome new items 指接受新事物或對新事物有正面反應。"},{"en":"Children may welcome new items in a classroom if they are colourful and easy to use.","zh":"如果課室中新物品色彩鮮明且容易使用，孩子可能歡迎它們。"},{"en":"If people fear giving up what they own, they may not welcome new items.","zh":"如果人們害怕放棄已擁有的東西，可能不歡迎新物品。"},{"en":"This phrase describes openness to new things, not automatic adoption.","zh":"這個片語描述對新事物開放，而不是自動採用。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":21},{"front":"have no preference","meaning":"沒有偏好","examples":[{"en":"The initial choice suggested that students did not strongly prefer one item over the other.","zh":"初始選擇顯示學生沒有強烈偏好其中一件物品。"},{"en":"To have no preference means not to favour one option more than another.","zh":"have no preference 指沒有比另一個選項更偏好某一選項。"},{"en":"A student may have no preference between two lunch boxes if both are equally useful.","zh":"如果兩個飯盒同樣實用，學生可能沒有偏好。"},{"en":"If people have no preference at first but later refuse to trade, ownership may have changed their judgement.","zh":"如果人們起初沒有偏好，但之後拒絕交換，擁有權可能改變了判斷。"},{"en":"This phrase shows neutrality between options.","zh":"這個片語顯示在選項之間保持中立。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":21},{"front":"chocolate-bar owners","meaning":"朱古力條持有人","examples":[{"en":"Only a small number of chocolate-bar owners were willing to exchange.","zh":"只有少數朱古力條持有人願意交換。"},{"en":"Chocolate-bar owners are participants who already possess a chocolate bar.","zh":"chocolate-bar owners 是已經擁有朱古力條的參加者。"},{"en":"Chocolate-bar owners may value the chocolate more after it becomes theirs.","zh":"朱古力條持有人可能在朱古力成為自己的東西後更重視它。"},{"en":"If chocolate-bar owners refuse to exchange, the endowment effect may be present.","zh":"如果朱古力條持有人拒絕交換，稟賦效應可能存在。"},{"en":"This phrase identifies the group by what they own in the experiment.","zh":"這個片語按實驗中擁有的物品識別群體。"}],"source":"120 - Psychology of new product adoption.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 121":[{"front":"A Decibel Hell","meaning":"分貝地獄","examples":[{"en":"The title A Decibel Hell suggests that modern life can be painfully noisy.","zh":"標題《分貝地獄》暗示現代生活可以嘈雜得令人痛苦。"},{"en":"A Decibel Hell is a situation where noise is so loud or constant that it feels unbearable.","zh":"分貝地獄是指噪音大到或持續到令人難以忍受的情況。"},{"en":"A flat beside a busy road can feel like a decibel hell if engines and horns continue all night.","zh":"如果引擎聲和響號整晚不停，住在繁忙道路旁的單位可能像分貝地獄。"},{"en":"Too much traffic, construction, and loud music can turn a city into a decibel hell.","zh":"過多交通、建築工程和大聲音樂可以把城市變成分貝地獄。"},{"en":"This phrase is dramatic because it compares noise pollution to a form of suffering.","zh":"這個片語語氣強烈，因為它把噪音污染比作一種痛苦。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":1},{"front":"the effects of living in","meaning":"生活在……中的影響","examples":[{"en":"The passage discusses the effects of living in a noisy world.","zh":"文章討論生活在嘈雜世界中的影響。"},{"en":"The effects of living in a place are the results that daily life there has on people.","zh":"生活在某地方的影響，是指日常生活在該環境中對人造成的結果。"},{"en":"The effects of living in a small flat may include less privacy and more family conflict.","zh":"生活在細小單位中的影響可能包括私隱較少和家庭衝突較多。"},{"en":"Living in a noisy area can affect sleep, concentration, hearing, and mood.","zh":"生活在嘈雜地區可以影響睡眠、專注力、聽力和情緒。"},{"en":"This phrase helps discuss how an environment changes people’s health or behaviour.","zh":"這個片語有助討論環境如何改變人的健康或行為。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":1},{"front":"a noisy world","meaning":"嘈雜的世界","examples":[{"en":"Many people now live in a noisy world.","zh":"許多人現在生活在嘈雜的世界中。"},{"en":"A noisy world is a society or environment where loud sound is common and hard to escape.","zh":"嘈雜的世界是指巨大聲音常見而且難以避開的社會或環境。"},{"en":"A city with traffic, trains, phones, music, and construction can feel like a noisy world.","zh":"有交通、火車、電話、音樂和建築工程的城市，可以令人感覺像嘈雜的世界。"},{"en":"Living in a noisy world may make silence feel rare and valuable.","zh":"生活在嘈雜的世界中，可能令人覺得寧靜稀有而珍貴。"},{"en":"This phrase describes modern life where sound surrounds people almost everywhere.","zh":"這個片語描述現代生活中聲音幾乎到處包圍人。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":1},{"front":"encounter sound at levels that","meaning":"接觸到達……水平的聲音","examples":[{"en":"People can encounter sound at levels that cause health problems.","zh":"人們可能接觸到達會造成健康問題水平的聲音。"},{"en":"To encounter sound at levels that do something means to experience noise loud enough to produce that effect.","zh":"To encounter sound at levels that do something 指經歷足以產生某種影響的噪音水平。"},{"en":"Factory workers may encounter sound at levels that require ear protection.","zh":"工廠工人可能接觸到達需要耳部保護水平的聲音。"},{"en":"If children encounter sound at levels that disturb sleep, learning may suffer.","zh":"如果兒童接觸到達干擾睡眠水平的聲音，學習可能受損。"},{"en":"This phrase links the loudness of sound with its possible consequence.","zh":"這個片語把聲音大小與可能後果連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":1},{"front":"adverse health effects","meaning":"不良健康影響","examples":[{"en":"Loud noise can cause adverse health effects.","zh":"巨大噪音可以造成不良健康影響。"},{"en":"Adverse health effects are harmful changes in the body or mind caused by something.","zh":"不良健康影響是由某事造成的身體或心理上的有害變化。"},{"en":"Poor air quality can have adverse health effects such as coughing and breathing problems.","zh":"空氣質素差可以造成咳嗽和呼吸問題等不良健康影響。"},{"en":"Long-term noise exposure may create adverse health effects beyond hearing loss.","zh":"長期噪音暴露可能造成聽力喪失以外的不良健康影響。"},{"en":"This phrase is formal and often used in medical or public-health writing.","zh":"這個片語較正式，常用於醫學或公共衛生寫作。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":1},{"front":"during a single day","meaning":"在一天之內","examples":[{"en":"During a single day, urban residents may hear many loud sounds.","zh":"在一天之內，城市居民可能聽到許多巨大聲音。"},{"en":"During a single day means within one day only.","zh":"During a single day 指只在一天之內。"},{"en":"During a single day, a student may hear alarms, traffic, school bells, and loud music.","zh":"在一天之內，學生可能聽到警報、交通、校鐘和大聲音樂。"},{"en":"If exposure happens many times during a single day, the total effect may build up.","zh":"如果暴露在一天之內發生多次，總體影響可能累積。"},{"en":"This phrase emphasises how much can happen in a short period.","zh":"這個片語強調短時間內可以發生很多事情。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":1},{"front":"typical urban environment","meaning":"典型城市環境","examples":[{"en":"People in a typical urban environment experience a wide range of sounds.","zh":"典型城市環境中的人會經歷各式各樣的聲音。"},{"en":"A typical urban environment is an ordinary city setting with roads, buildings, people, and services.","zh":"典型城市環境是有道路、建築、人群和服務的一般城市場景。"},{"en":"A typical urban environment may include buses, shops, construction sites, schools, and apartment blocks.","zh":"典型城市環境可能包括巴士、商店、工地、學校和住宅大廈。"},{"en":"Because many activities happen close together, a typical urban environment can become noisy.","zh":"因為許多活動集中在一起，典型城市環境可能變得嘈雜。"},{"en":"This phrase describes normal city life, not an unusual disaster area.","zh":"這個片語描述正常城市生活，而不是不尋常災區。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":1},{"front":"experience a wide range of","meaning":"經歷各式各樣的……","examples":[{"en":"City residents experience a wide range of sounds every day.","zh":"城市居民每天經歷各式各樣的聲音。"},{"en":"To experience a wide range of something means to go through many different types of it.","zh":"To experience a wide range of something 指經歷許多不同種類的某事。"},{"en":"Students experience a wide range of emotions before an important exam.","zh":"學生在重要考試前會經歷各式各樣的情緒。"},{"en":"People who live near transport hubs may experience a wide range of noise sources.","zh":"住在交通樞紐附近的人可能經歷各式各樣的噪音來源。"},{"en":"This phrase shows variety, not just quantity.","zh":"這個片語顯示種類多，而不只是數量多。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":1},{"front":"once-quiet locales","meaning":"曾經寧靜的地方","examples":[{"en":"Even once-quiet locales have become polluted with noise.","zh":"甚至曾經寧靜的地方也受到噪音污染。"},{"en":"Once-quiet locales are places that used to be peaceful but are no longer quiet.","zh":"Once-quiet locales 是過去寧靜但現在不再安靜的地方。"},{"en":"A village near a new highway may become one of those once-quiet locales.","zh":"位於新高速公路附近的村莊，可能成為這類曾經寧靜的地方。"},{"en":"Tourism, traffic, and construction can change once-quiet locales into noisy areas.","zh":"旅遊、交通和建築工程可以把曾經寧靜的地方變成嘈雜地區。"},{"en":"This phrase highlights loss of peace over time.","zh":"這個片語突顯寧靜隨時間流失。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":1},{"front":"be polluted with noise","meaning":"受到噪音污染","examples":[{"en":"Many formerly quiet places have become polluted with noise.","zh":"許多從前安靜的地方已受到噪音污染。"},{"en":"To be polluted with noise means to be harmed or disturbed by unwanted sound.","zh":"To be polluted with noise 指被不想要的聲音傷害或干擾。"},{"en":"A park can be polluted with noise if loud traffic surrounds it all day.","zh":"如果公園整天被繁忙交通包圍，就可能受到噪音污染。"},{"en":"When homes are polluted with noise, people may sleep badly and feel stressed.","zh":"當家居受到噪音污染，人們可能睡得差並感到壓力。"},{"en":"This phrase treats unwanted sound as a form of environmental pollution.","zh":"這個片語把不想要的聲音視為一種環境污染。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":1},{"front":"escape sound completely","meaning":"完全避開聲音","examples":[{"en":"It is difficult today to escape sound completely.","zh":"今天很難完全避開聲音。"},{"en":"To escape sound completely means to avoid all sound and be in total silence.","zh":"To escape sound completely 指避開所有聲音，處於完全寂靜之中。"},{"en":"Even at home, people may not escape sound completely because of neighbours or traffic.","zh":"即使在家，人們也可能因鄰居或交通而無法完全避開聲音。"},{"en":"If a city never sleeps, residents may struggle to escape sound completely.","zh":"如果城市從不入睡，居民可能難以完全避開聲音。"},{"en":"This phrase shows how rare true silence has become.","zh":"這個片語顯示真正寂靜變得多麼稀有。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":1},{"front":"Guidelines for Community Noise","meaning":"《社區噪音指引》","examples":[{"en":"The World Health Organization published Guidelines for Community Noise in 1999.","zh":"世界衞生組織於1999年發表《社區噪音指引》。"},{"en":"Guidelines for Community Noise is a document giving advice about noise and public health.","zh":"《社區噪音指引》是一份就噪音和公共健康提供建議的文件。"},{"en":"City planners may use noise guidelines when deciding where to build schools or housing.","zh":"城市規劃者在決定在哪裡興建學校或住宅時，可能使用噪音指引。"},{"en":"Such guidelines help governments understand when everyday noise becomes a health issue.","zh":"這類指引幫助政府理解日常噪音何時變成健康問題。"},{"en":"This title connects community noise with official health standards.","zh":"這個標題把社區噪音與官方健康標準連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":2},{"front":"World Health Organization","meaning":"世界衞生組織","examples":[{"en":"The World Health Organization warned about noise-induced hearing impairment.","zh":"世界衞生組織警告噪音引致的聽力受損。"},{"en":"The World Health Organization is an international body that gives guidance on global health.","zh":"世界衞生組織是一個就全球健康提供指導的國際機構。"},{"en":"Governments may use World Health Organization advice when creating public-health rules.","zh":"政府制定公共衛生規則時，可能使用世界衞生組織的建議。"},{"en":"When the World Health Organization warns about a risk, the issue can receive more attention.","zh":"當世界衞生組織警告某風險，該議題可能得到更多關注。"},{"en":"This phrase names a global health organisation, not a local clinic.","zh":"這個片語命名一個全球健康組織，而不是本地診所。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":2},{"front":"declare that","meaning":"宣稱；指出","examples":[{"en":"The World Health Organization declared that noise-induced hearing impairment is widespread.","zh":"世界衞生組織指出噪音引致的聽力受損十分普遍。"},{"en":"To declare that something is true means to state it clearly and officially.","zh":"To declare that something is true 指清楚而正式地陳述某事是真的。"},{"en":"A school may declare that mobile phones are not allowed during exams.","zh":"學校可能宣布考試期間不准使用手機。"},{"en":"When an organisation declares a health risk, people may take the warning more seriously.","zh":"當機構指出某項健康風險，人們可能更認真看待警告。"},{"en":"This phrase is stronger than simply “say”.","zh":"這個片語比單純 “say” 更強。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":2},{"front":"worldwide","meaning":"在全球；全球而言","examples":[{"en":"Worldwide, many people suffer from disabling hearing difficulties.","zh":"全球而言，許多人患有造成障礙的聽力困難。"},{"en":"Worldwide means across the whole world or in many countries.","zh":"Worldwide 指遍及全世界或許多國家。"},{"en":"Air pollution is a worldwide problem because it affects cities on every continent.","zh":"空氣污染是全球問題，因為它影響每個大洲的城市。"},{"en":"If hearing loss is common worldwide, international health agencies may issue guidelines.","zh":"如果聽力喪失在全球都普遍，國際衛生機構可能發出指引。"},{"en":"This word gives a global scale to a problem.","zh":"這個詞為問題帶出全球規模。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":2},{"front":"noise-induced hearing impairment","meaning":"噪音引致的聽力受損","examples":[{"en":"Noise-induced hearing impairment is a serious occupational hazard.","zh":"噪音引致的聽力受損是嚴重的職業危害。"},{"en":"Noise-induced hearing impairment is hearing damage caused by exposure to loud noise.","zh":"噪音引致的聽力受損是由暴露於巨大噪音所造成的聽力損害。"},{"en":"Factory workers may develop noise-induced hearing impairment if machines are too loud.","zh":"如果機器太嘈，工廠工人可能出現噪音引致的聽力受損。"},{"en":"Ear protection can reduce the risk of noise-induced hearing impairment.","zh":"耳部保護可以降低噪音引致聽力受損的風險。"},{"en":"This phrase focuses on hearing loss caused by sound, not by age alone.","zh":"這個片語著重由聲音造成的聽力喪失，而不只是年齡造成的。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":2},{"front":"the most prevalent","meaning":"最普遍的","examples":[{"en":"Noise-induced hearing impairment is the most prevalent irreversible occupational hazard.","zh":"噪音引致的聽力受損是最普遍的不可逆轉職業危害。"},{"en":"The most prevalent means the most common or widespread.","zh":"The most prevalent 指最常見或最廣泛存在。"},{"en":"In some schools, poor sleep may be the most prevalent problem affecting concentration.","zh":"在一些學校，睡眠不足可能是影響專注力最普遍的問題。"},{"en":"If a hazard is the most prevalent, many workers may be affected by it.","zh":"如果某危害最普遍，許多工人都可能受它影響。"},{"en":"This phrase compares frequency with other problems.","zh":"這個片語把某問題的出現頻率與其他問題比較。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":2},{"front":"irreversible occupational hazard","meaning":"不可逆轉的職業危害","examples":[{"en":"Noise-induced hearing impairment is an irreversible occupational hazard.","zh":"噪音引致的聽力受損是不可逆轉的職業危害。"},{"en":"An irreversible occupational hazard is a workplace danger that can cause permanent harm.","zh":"不可逆轉的職業危害是工作場所中可能造成永久傷害的危險。"},{"en":"A chemical that permanently damages the lungs can be an irreversible occupational hazard.","zh":"永久損害肺部的化學物可以是不可逆轉的職業危害。"},{"en":"If hearing loss is irreversible, prevention is more important than later treatment.","zh":"如果聽力喪失不可逆轉，預防便比事後治療更重要。"},{"en":"This phrase combines workplace risk with damage that cannot easily be undone.","zh":"這個片語結合工作場所風險和難以逆轉的傷害。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":2},{"front":"be estimated that","meaning":"據估計","examples":[{"en":"It is estimated that 120 million people worldwide have disabling hearing difficulties.","zh":"據估計，全球有1.2億人有造成障礙的聽力困難。"},{"en":"It is estimated that means experts believe a number is likely, based on available data.","zh":"It is estimated that 指專家根據現有數據相信某數字很可能接近真實。"},{"en":"It is estimated that many students travel more than an hour to school each day.","zh":"據估計，許多學生每天上學需時超過一小時。"},{"en":"Estimates are useful when exact numbers are difficult to collect.","zh":"當精確數字難以收集時，估計很有用。"},{"en":"This phrase introduces an informed approximate figure.","zh":"這個片語引出有根據的近似數字。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":2},{"front":"disabling hearing difficulties","meaning":"造成障礙的聽力困難","examples":[{"en":"Millions of people have disabling hearing difficulties.","zh":"數以百萬計的人有造成障礙的聽力困難。"},{"en":"Disabling hearing difficulties are hearing problems serious enough to limit daily life.","zh":"Disabling hearing difficulties 是嚴重到限制日常生活的聽力問題。"},{"en":"A child with disabling hearing difficulties may miss instructions in class.","zh":"有造成障礙的聽力困難的孩子，可能在課堂上聽漏指示。"},{"en":"Adults with serious hearing problems may struggle at work and in conversations.","zh":"有嚴重聽力問題的成年人，可能在工作和對話中遇到困難。"},{"en":"This phrase describes hearing loss that affects function, not just mild inconvenience.","zh":"這個片語描述影響功能的聽力喪失，而不只是輕微不便。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":2},{"front":"growing evidence","meaning":"越來越多證據","examples":[{"en":"Growing evidence points to other health effects of too much noise.","zh":"越來越多證據指向過多噪音的其他健康影響。"},{"en":"Growing evidence means an increasing amount of information or research supports an idea.","zh":"Growing evidence 指支持某想法的資訊或研究越來越多。"},{"en":"Growing evidence shows that sleep affects learning and memory.","zh":"越來越多證據顯示睡眠影響學習和記憶。"},{"en":"When evidence grows, doctors and governments may take a risk more seriously.","zh":"當證據增加，醫生和政府可能更認真看待某風險。"},{"en":"This phrase suggests that support for an idea is becoming stronger over time.","zh":"這個片語暗示某想法的支持隨時間變得更強。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":2},{"front":"point to","meaning":"指向；顯示","examples":[{"en":"Growing evidence points to many health effects of excessive volume.","zh":"越來越多證據顯示過大音量有許多健康影響。"},{"en":"To point to something means to suggest, indicate, or provide evidence for it.","zh":"To point to something 指暗示、顯示或為某事提供證據。"},{"en":"Repeated lateness may point to transport problems rather than laziness.","zh":"反覆遲到可能指向交通問題，而不是懶惰。"},{"en":"If research points to health risks, experts may call for stronger protection.","zh":"如果研究指向健康風險，專家可能呼籲更強保護。"},{"en":"This phrase connects evidence with a likely conclusion.","zh":"這個片語把證據與可能結論連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":2},{"front":"health effects of","meaning":"……的健康影響","examples":[{"en":"Researchers study the health effects of too much volume.","zh":"研究人員研究過大音量的健康影響。"},{"en":"The health effects of something are the ways it changes physical or mental health.","zh":"Health effects of something 是某事改變身體或心理健康的方式。"},{"en":"Doctors study the health effects of poor sleep on children.","zh":"醫生研究睡眠不足對兒童的健康影響。"},{"en":"If the health effects of noise include stress and hearing loss, prevention becomes important.","zh":"如果噪音的健康影響包括壓力和聽力喪失，預防便變得重要。"},{"en":"This phrase is useful for discussing risks and consequences.","zh":"這個片語適合討論風險和後果。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":3},{"front":"too much volume","meaning":"過大音量","examples":[{"en":"Too much volume can damage hearing and affect health.","zh":"過大音量可以損害聽力並影響健康。"},{"en":"Too much volume means sound is louder than is safe, comfortable, or necessary.","zh":"Too much volume 指聲音大到超過安全、舒適或必要水平。"},{"en":"Listening to music with too much volume through headphones can harm the ears.","zh":"用耳機以過大音量聽音樂可以傷害耳朵。"},{"en":"Too much volume in a classroom can make it hard for students to concentrate.","zh":"課室中的過大音量可以令學生難以集中。"},{"en":"This phrase warns that loudness can become a health problem.","zh":"這個片語提醒人，音量過大可以變成健康問題。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":3},{"front":"Ohio-based","meaning":"駐俄亥俄州的","examples":[{"en":"Mark Stephenson is an Ohio-based senior research audiologist.","zh":"Mark Stephenson是一名駐俄亥俄州的高級研究聽力學家。"},{"en":"Ohio-based means located in or working mainly from Ohio.","zh":"Ohio-based 指位於俄亥俄州或主要在俄亥俄州工作。"},{"en":"An Ohio-based company may serve customers across the United States.","zh":"一間駐俄亥俄州的公司可能服務全美顧客。"},{"en":"A researcher can be Ohio-based but still work on national health issues.","zh":"研究人員可以駐俄亥俄州，但仍研究全國健康議題。"},{"en":"This phrase identifies a person’s or organisation’s main location.","zh":"這個片語指出某人或機構的主要所在地。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":3},{"front":"senior research audiologist","meaning":"高級研究聽力學家","examples":[{"en":"Mark Stephenson is a senior research audiologist at NIOSH.","zh":"Mark Stephenson是NIOSH的高級研究聽力學家。"},{"en":"A senior research audiologist is an experienced expert who studies hearing and hearing loss.","zh":"Senior research audiologist 是研究聽力和聽力喪失的資深專家。"},{"en":"A senior research audiologist may test how workplace noise affects workers’ ears.","zh":"高級研究聽力學家可能測試工作場所噪音如何影響工人耳朵。"},{"en":"Such experts help create guidelines for preventing hearing damage.","zh":"這類專家幫助制定預防聽力損害的指引。"},{"en":"This phrase combines hearing science with advanced research experience.","zh":"這個片語結合聽力科學與高級研究經驗。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":3},{"front":"National Institute for Occupational Safety and Health","meaning":"美國國家職業安全與健康研究所","examples":[{"en":"The National Institute for Occupational Safety and Health studies workplace hazards.","zh":"美國國家職業安全與健康研究所研究工作場所危害。"},{"en":"The National Institute for Occupational Safety and Health is a U.S. institute focused on worker safety and health research.","zh":"美國國家職業安全與健康研究所是一個專注於工人安全和健康研究的美國機構。"},{"en":"It may study noise, chemicals, injuries, and other risks in workplaces.","zh":"它可能研究工作場所中的噪音、化學物、傷害和其他風險。"},{"en":"Research from this institute can help employers protect workers from harm.","zh":"該研究所的研究可以幫助僱主保護工人免受傷害。"},{"en":"This phrase names an organisation concerned with occupational health.","zh":"這個片語命名一個關注職業健康的機構。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":3},{"front":"hazardous noise","meaning":"有害噪音","examples":[{"en":"Hazardous noise exceeds a time-weighted average of 85 dBA.","zh":"有害噪音超過85分貝A的時間加權平均值。"},{"en":"Hazardous noise is noise loud enough to create a risk to hearing or health.","zh":"Hazardous noise 是大到會對聽力或健康造成風險的噪音。"},{"en":"Workers near heavy machines may need earplugs because the noise is hazardous.","zh":"靠近重型機器工作的工人可能需要耳塞，因為噪音有害。"},{"en":"Repeated exposure to hazardous noise can slowly damage inner-ear cells.","zh":"反覆暴露於有害噪音可以慢慢損害內耳細胞。"},{"en":"This phrase describes noise that is dangerous, not merely annoying.","zh":"這個片語描述危險噪音，而不只是令人煩躁的噪音。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":3},{"front":"exceed","meaning":"超過","examples":[{"en":"Hazardous noise exceeds the time-weighted average of 85 dBA.","zh":"有害噪音超過85分貝A的時間加權平均值。"},{"en":"To exceed a limit means to go above it.","zh":"To exceed a limit 指超出某個限制。"},{"en":"A car exceeds the speed limit when it travels faster than the law allows.","zh":"當汽車行駛速度高於法律容許，它就超過速度限制。"},{"en":"If workplace noise exceeds safety limits, employers must provide protection.","zh":"如果工作場所噪音超過安全限制，僱主必須提供保護。"},{"en":"This word is often used with numbers, rules, and standards.","zh":"這個字常與數字、規則和標準一起使用。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":3},{"front":"time-weighted average","meaning":"時間加權平均值","examples":[{"en":"The time-weighted average measures noise exposure over a typical workday.","zh":"時間加權平均值量度典型工作日中的噪音暴露。"},{"en":"A time-weighted average is an average that considers both level and length of exposure.","zh":"Time-weighted average 是同時考慮暴露水平和暴露時間長短的平均值。"},{"en":"A worker may hear very loud noise briefly and quieter noise for the rest of the day.","zh":"工人可能短時間聽到極大噪音，其餘時間聽到較低噪音。"},{"en":"Time-weighted averages help judge total exposure more fairly than one moment of measurement.","zh":"時間加權平均值比單一時刻量度更公平地判斷總暴露量。"},{"en":"This phrase is useful when risk depends on both intensity and duration.","zh":"當風險取決於強度和時間長短時，這個片語很有用。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":3},{"front":"85 dBA","meaning":"85 分貝A","examples":[{"en":"NIOSH defines hazardous noise as sound above 85 dBA on average.","zh":"NIOSH把平均超過85分貝A的聲音定義為有害噪音。"},{"en":"85 dBA is a noise level measured using an A-weighted decibel scale.","zh":"85 dBA 是使用A加權分貝刻度量度的噪音水平。"},{"en":"A workplace above 85 dBA may require a hearing conservation program.","zh":"超過85分貝A的工作場所可能需要聽力保護計劃。"},{"en":"Long exposure near or above 85 dBA can increase the risk of hearing damage.","zh":"長時間接近或超過85分貝A的暴露，可以增加聽力損害風險。"},{"en":"This term is a technical safety threshold for noise exposure.","zh":"這個術語是噪音暴露的技術安全門檻。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":3},{"front":"noise exposure","meaning":"噪音暴露","examples":[{"en":"Noise exposure is measured over an eight-hour workday.","zh":"噪音暴露在八小時工作日內量度。"},{"en":"Noise exposure means the amount and length of time a person experiences noise.","zh":"Noise exposure 指一個人接觸噪音的音量和時間長短。"},{"en":"A gardener may have noise exposure from lawnmowers and leaf blowers.","zh":"園丁可能因割草機和吹葉機而有噪音暴露。"},{"en":"Higher noise exposure can increase the chance of hearing loss.","zh":"較高噪音暴露可以增加聽力喪失的機會。"},{"en":"This phrase includes both loudness and duration.","zh":"這個片語同時包括音量和持續時間。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":3},{"front":"measured over","meaning":"在……期間量度","examples":[{"en":"The average noise exposure is measured over a typical workday.","zh":"平均噪音暴露在典型工作日期間量度。"},{"en":"Measured over a period means calculated across that length of time.","zh":"Measured over a period 指在該段時間內計算。"},{"en":"A student’s progress may be measured over a whole term, not one lesson.","zh":"學生進步可能在整個學期期間量度，而不是只看一堂課。"},{"en":"Noise measured over eight hours gives a better picture than one short sound burst.","zh":"在八小時期間量度噪音，比只看一次短暫聲響更能反映情況。"},{"en":"This phrase explains the time frame of a measurement.","zh":"這個片語解釋量度的時間範圍。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":3},{"front":"typical eight-hour workday","meaning":"典型八小時工作日","examples":[{"en":"The standard measurement is based on a typical eight-hour workday.","zh":"標準量度基於典型八小時工作日。"},{"en":"A typical eight-hour workday is an ordinary work shift lasting about eight hours.","zh":"Typical eight-hour workday 是約八小時的一般工作更次。"},{"en":"Many offices use a typical eight-hour workday as the standard full-time schedule.","zh":"許多辦公室使用典型八小時工作日作為全職時間表標準。"},{"en":"Noise rules often use this period to estimate daily worker exposure.","zh":"噪音規則常使用這段時間估算工人每日暴露量。"},{"en":"This phrase gives a normal work-time reference point.","zh":"這個片語提供正常工作時間參考點。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":4},{"front":"other measures and definitions","meaning":"其他量度方法和定義","examples":[{"en":"Other measures and definitions are used for other purposes.","zh":"其他量度方法和定義用於其他目的。"},{"en":"Other measures and definitions are different ways of measuring or defining the same issue.","zh":"Other measures and definitions 是量度或定義同一議題的不同方式。"},{"en":"A teacher may use different measures and definitions of progress for speaking and writing.","zh":"老師可能對口語和寫作進步使用不同量度方法和定義。"},{"en":"Different noise standards may be needed for workplaces, homes, and schools.","zh":"工作場所、家居和學校可能需要不同噪音標準。"},{"en":"This phrase shows that one definition does not fit every situation.","zh":"這個片語顯示一個定義不適用於所有情況。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":4},{"front":"be used for other purposes","meaning":"用於其他目的","examples":[{"en":"Different noise measures are used for other purposes.","zh":"不同噪音量度方法用於其他目的。"},{"en":"To be used for other purposes means to serve different needs or goals.","zh":"To be used for other purposes 指服務於不同需要或目標。"},{"en":"A school hall may be used for exams, concerts, and parent meetings.","zh":"學校禮堂可以用於考試、音樂會和家長會。"},{"en":"A noise measurement for factories may not be suitable for studying sleep at home.","zh":"適用於工廠的噪音量度，未必適合研究家中睡眠。"},{"en":"This phrase explains why different tools or standards may be chosen.","zh":"這個片語解釋為何可能選擇不同工具或標準。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":4},{"front":"Growing Volume","meaning":"音量日增","examples":[{"en":"The section Growing Volume discusses rising exposure to loud noise at work.","zh":"“音量日增”這一部分討論工作中巨大噪音暴露上升。"},{"en":"Growing Volume suggests that noise levels or noise exposure are increasing.","zh":"Growing Volume 暗示噪音水平或噪音暴露正在增加。"},{"en":"A city may experience growing volume as traffic and construction expand.","zh":"當交通和建築工程擴大，城市可能出現音量日增。"},{"en":"Growing volume at work can create greater pressure for safety rules.","zh":"工作場所音量日增可以為安全規則帶來更大壓力。"},{"en":"This title signals a section about increasing loudness and exposure.","zh":"這個標題提示該部分關於音量和暴露增加。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":4},{"front":"be exposed to","meaning":"暴露於……","examples":[{"en":"Many workers are exposed to hazardous sound levels on the job.","zh":"許多工人在工作中暴露於有害聲音水平。"},{"en":"To be exposed to something means to come into contact with it.","zh":"To be exposed to something 指接觸到某事物。"},{"en":"Nurses may be exposed to infections if protective rules are weak.","zh":"如果保護規則薄弱，護士可能暴露於感染。"},{"en":"Workers exposed to loud machines may need hearing protection.","zh":"暴露於巨大機器聲的工人可能需要聽力保護。"},{"en":"This phrase is common when discussing health risks.","zh":"這個片語常用於討論健康風險。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":4},{"front":"hazardous sound levels","meaning":"有害聲音水平","examples":[{"en":"About 30 million workers are exposed to hazardous sound levels.","zh":"約三千萬工人暴露於有害聲音水平。"},{"en":"Hazardous sound levels are levels of noise that may harm hearing or health.","zh":"Hazardous sound levels 是可能傷害聽力或健康的噪音水平。"},{"en":"A worker using a drill all day may face hazardous sound levels.","zh":"整天使用電鑽的工人可能面對有害聲音水平。"},{"en":"If sound levels are hazardous, employers should reduce exposure or provide protection.","zh":"如果聲音水平有害，僱主應減少暴露或提供保護。"},{"en":"This phrase describes dangerous loudness, not ordinary background sound.","zh":"這個片語描述危險音量，而不是普通背景聲。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":4},{"front":"on the job","meaning":"在工作中","examples":[{"en":"Many workers face loud noise on the job.","zh":"許多工人在工作中面對巨大噪音。"},{"en":"On the job means while working or during work duties.","zh":"On the job 指在工作期間或履行工作職責時。"},{"en":"A delivery driver may face heavy traffic on the job every day.","zh":"送貨司機每天在工作中可能面對繁忙交通。"},{"en":"If a risk occurs on the job, employers may have legal duties to reduce it.","zh":"如果風險在工作中出現，僱主可能有法律責任減低它。"},{"en":"This phrase connects a condition with the workplace.","zh":"這個片語把某情況與工作場所連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":4},{"front":"according to","meaning":"根據……","examples":[{"en":"About 30 million workers are exposed to loud sound, according to NIOSH.","zh":"根據NIOSH，約三千萬工人暴露於巨大聲響。"},{"en":"According to means based on what a person, report, or organisation says.","zh":"According to 指根據某人、報告或機構所說。"},{"en":"According to the timetable, the last bus leaves at midnight.","zh":"根據時間表，最後一班巴士午夜開出。"},{"en":"According to health experts, long exposure to loud noise can damage hearing.","zh":"根據健康專家，長期暴露於巨大噪音可以損害聽力。"},{"en":"This phrase shows the source of information.","zh":"這個片語顯示資訊來源。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":4},{"front":"industries having","meaning":"擁有……的行業","examples":[{"en":"Industries having many exposed workers include construction and manufacturing.","zh":"擁有許多暴露工人的行業包括建築業和製造業。"},{"en":"Industries having a feature are industries that possess or contain that feature.","zh":"Industries having a feature 指擁有或包含某特徵的行業。"},{"en":"Industries having night shifts may face more problems with worker fatigue.","zh":"擁有夜班的行業可能面對更多工人疲勞問題。"},{"en":"Industries having many loud machines need stronger hearing protection plans.","zh":"擁有許多嘈雜機器的行業需要更強聽力保護計劃。"},{"en":"This phrase is formal and means “industries with”.","zh":"這個片語較正式，意思是「有……的行業」。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":4},{"front":"a high number of workers","meaning":"大量工人","examples":[{"en":"Some industries have a high number of workers exposed to loud sounds.","zh":"一些行業有大量工人暴露於巨大聲響。"},{"en":"A high number of workers means many workers.","zh":"A high number of workers 指很多工人。"},{"en":"A large hospital may have a high number of workers on night shifts.","zh":"大型醫院可能有大量工人上夜班。"},{"en":"If a high number of workers face the same risk, safety policies become urgent.","zh":"如果大量工人面對同一風險，安全政策便變得迫切。"},{"en":"This phrase emphasises the scale of the affected workforce.","zh":"這個片語強調受影響勞動力的規模。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":4},{"front":"exposed to loud sounds","meaning":"暴露於巨大聲響","examples":[{"en":"Workers in construction and mining are often exposed to loud sounds.","zh":"建築業和採礦業工人常暴露於巨大聲響。"},{"en":"Exposed to loud sounds means regularly hearing noise that may be intense or harmful.","zh":"Exposed to loud sounds 指經常聽到強烈或可能有害的噪音。"},{"en":"Road workers may be exposed to loud sounds from drills, trucks, and traffic.","zh":"道路工人可能暴露於電鑽、貨車和交通的巨大聲響。"},{"en":"People exposed to loud sounds for years may develop hearing loss.","zh":"長年暴露於巨大聲響的人可能出現聽力喪失。"},{"en":"This phrase describes contact with noise as a health risk.","zh":"這個片語把接觸噪音描述為健康風險。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":4},{"front":"construction","meaning":"建築業","examples":[{"en":"Construction is an industry with many workers exposed to loud sounds.","zh":"建築業是一個有許多工人暴露於巨大聲響的行業。"},{"en":"Construction is the work of building roads, bridges, homes, offices, and other structures.","zh":"Construction 是建造道路、橋樑、住宅、辦公室和其他結構的工作。"},{"en":"Construction workers may hear drills, hammers, trucks, and heavy machines every day.","zh":"建築工人每天可能聽到電鑽、錘子、貨車和重型機器聲。"},{"en":"Because construction sites are noisy, workers often need hearing protection.","zh":"因為建築工地嘈雜，工人常需要聽力保護。"},{"en":"This word refers to building work, not only the finished building.","zh":"這個詞指建造工作，而不只是已完成的建築物。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":5},{"front":"agriculture","meaning":"農業","examples":[{"en":"Agriculture can expose workers to hazardous sound levels.","zh":"農業可以令工人暴露於有害聲音水平。"},{"en":"Agriculture is the work of farming, growing crops, and raising animals.","zh":"Agriculture 是耕作、種植農作物和飼養動物的工作。"},{"en":"Farm workers may hear tractors, harvesters, pumps, and other loud machines.","zh":"農場工人可能聽到拖拉機、收割機、水泵和其他巨大機器聲。"},{"en":"Noise in agriculture can be overlooked because farms are often thought of as quiet places.","zh":"農業噪音可能被忽視，因為農場常被視為安靜地方。"},{"en":"This word refers to farming as an industry.","zh":"這個詞指作為行業的耕作活動。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":5},{"front":"mining","meaning":"採礦業","examples":[{"en":"Mining is one of the industries associated with loud noise.","zh":"採礦業是與巨大噪音相關的行業之一。"},{"en":"Mining is the work of extracting coal, metal, stone, or minerals from the earth.","zh":"Mining 是從地下開採煤、金屬、石材或礦物的工作。"},{"en":"Miners may work near drills, crushers, engines, and underground machinery.","zh":"礦工可能在電鑽、碎石機、引擎和地下機械附近工作。"},{"en":"Mining noise can damage hearing if workers are not protected.","zh":"如果工人沒有保護，採礦噪音可以損害聽力。"},{"en":"This industry often involves both physical danger and noise exposure.","zh":"這個行業常涉及身體危險和噪音暴露。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":5},{"front":"manufacturing","meaning":"製造業","examples":[{"en":"Manufacturing workers may be exposed to hazardous noise.","zh":"製造業工人可能暴露於有害噪音。"},{"en":"Manufacturing is the process of making products in factories or workshops.","zh":"Manufacturing 是在工廠或工作坊製造產品的過程。"},{"en":"Manufacturing may involve machines that cut, press, drill, or package materials.","zh":"製造業可能涉及切割、壓製、鑽孔或包裝材料的機器。"},{"en":"If machines run all day, manufacturing workers may receive long noise exposure.","zh":"如果機器整天運作，製造業工人可能長時間暴露於噪音。"},{"en":"This word refers to production work, not sales or office administration.","zh":"這個詞指生產工作，而不是銷售或辦公行政。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":5},{"front":"utilities","meaning":"公用事業","examples":[{"en":"Utilities are listed among industries with loud sound exposure.","zh":"公用事業被列為有巨大聲音暴露的行業之一。"},{"en":"Utilities are services such as electricity, gas, water, and waste management.","zh":"Utilities 是電力、煤氣、水務和廢物管理等服務。"},{"en":"Utility workers may operate generators, pumps, repair vehicles, and heavy tools.","zh":"公用事業工人可能操作發電機、水泵、維修車輛和重型工具。"},{"en":"Because utilities keep cities running, workers may face noise during repairs and emergencies.","zh":"因為公用事業維持城市運作，工人在維修和緊急情況中可能面對噪音。"},{"en":"This word refers to essential public services.","zh":"這個詞指基本公共服務。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":5},{"front":"transportation","meaning":"運輸業","examples":[{"en":"Transportation workers may encounter hazardous sound levels.","zh":"運輸業工人可能接觸有害聲音水平。"},{"en":"Transportation is the movement of people or goods by road, rail, air, or sea.","zh":"Transportation 是透過道路、鐵路、航空或海路運送人或貨物。"},{"en":"Bus drivers, airport workers, and train staff may work around loud engines and announcements.","zh":"巴士司機、機場工人和鐵路職員可能在巨大引擎聲和廣播聲附近工作。"},{"en":"Noise in transportation can affect both workers and nearby residents.","zh":"運輸業噪音可以影響工人和附近居民。"},{"en":"This word refers to systems that move people and goods.","zh":"這個詞指運送人和貨物的系統。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":5},{"front":"the military","meaning":"軍方；軍隊","examples":[{"en":"The military is included among sectors with loud noise exposure.","zh":"軍方被包括在有巨大噪音暴露的部門之中。"},{"en":"The military means a country’s armed forces, such as the army, navy, and air force.","zh":"The military 指一個國家的武裝力量，例如陸軍、海軍和空軍。"},{"en":"Soldiers may be exposed to loud noise from weapons, aircraft, vehicles, and training exercises.","zh":"士兵可能暴露於武器、飛機、車輛和訓練演習的巨大噪音。"},{"en":"Military noise can damage hearing if protection is not used properly.","zh":"如果沒有正確使用保護，軍事噪音可以損害聽力。"},{"en":"This phrase refers to defence forces, not ordinary police work.","zh":"這個片語指國防力量，而不是普通警務工作。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":5},{"front":"an extremely difficult problem to monitor","meaning":"極難監察的問題","examples":[{"en":"Noise in U.S. industry is an extremely difficult problem to monitor.","zh":"美國工業中的噪音是極難監察的問題。"},{"en":"An extremely difficult problem to monitor is a problem that is very hard to measure or track regularly.","zh":"極難監察的問題，是非常難以定期量度或追蹤的問題。"},{"en":"Bullying can be an extremely difficult problem to monitor if students hide it from teachers.","zh":"如果學生向老師隱瞞，欺凌可能是極難監察的問題。"},{"en":"Industrial noise is hard to monitor because levels change across machines, shifts, and workplaces.","zh":"工業噪音難以監察，因為水平會隨機器、更次和工作場所而變。"},{"en":"This phrase shows that the problem is not only serious but also hard to observe.","zh":"這個片語顯示問題不只嚴重，也難以觀察。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":5},{"front":"acknowledge","meaning":"承認","examples":[{"en":"Craig Moulton acknowledges that industrial noise is difficult to monitor.","zh":"Craig Moulton承認工業噪音難以監察。"},{"en":"To acknowledge something means to admit or accept that it is true.","zh":"To acknowledge something 指承認或接受某事是真的。"},{"en":"A teacher may acknowledge that a test was too difficult for the class.","zh":"老師可能承認測驗對全班來說太難。"},{"en":"Acknowledging a problem is often the first step toward solving it.","zh":"承認問題通常是解決問題的第一步。"},{"en":"This word often shows honesty or cautious agreement.","zh":"這個詞常顯示誠實或謹慎同意。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":5},{"front":"senior industrial hygienist","meaning":"高級工業衞生師","examples":[{"en":"Craig Moulton is a senior industrial hygienist for OSHA.","zh":"Craig Moulton是OSHA的高級工業衞生師。"},{"en":"A senior industrial hygienist is an experienced expert who studies workplace health hazards.","zh":"Senior industrial hygienist 是研究工作場所健康危害的資深專家。"},{"en":"An industrial hygienist may measure noise, dust, chemicals, and heat in factories.","zh":"工業衞生師可能量度工廠中的噪音、塵埃、化學物和熱力。"},{"en":"Their work helps employers reduce risks before workers become ill or injured.","zh":"他們的工作幫助僱主在工人生病或受傷前降低風險。"},{"en":"This phrase describes a specialist in workplace health protection.","zh":"這個片語描述工作場所健康保護專家。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":5},{"front":"Occupational Safety and Health Administration","meaning":"美國職業安全與健康管理局","examples":[{"en":"The Occupational Safety and Health Administration requires employers to protect workers.","zh":"美國職業安全與健康管理局要求僱主保護工人。"},{"en":"The Occupational Safety and Health Administration is a U.S. agency responsible for workplace safety rules.","zh":"美國職業安全與健康管理局是負責工作場所安全規則的美國機構。"},{"en":"It may inspect workplaces and set standards for hazards such as noise or chemicals.","zh":"它可能檢查工作場所，並為噪音或化學物等危害制定標準。"},{"en":"When OSHA sets rules, employers must take worker protection seriously.","zh":"當OSHA制定規則，僱主必須認真保護工人。"},{"en":"This phrase names a government body concerned with job safety.","zh":"這個片語命名關注工作安全的政府機構。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":5},{"front":"require that","meaning":"要求","examples":[{"en":"OSHA requires that employers protect workers from harmful noise.","zh":"OSHA要求僱主保護工人免受有害噪音影響。"},{"en":"Require that means officially demand that something must happen.","zh":"Require that 指正式要求某事必須發生。"},{"en":"A school may require that students wear safety glasses in the laboratory.","zh":"學校可能要求學生在實驗室佩戴安全眼鏡。"},{"en":"If rules require protection, employers cannot treat it as optional.","zh":"如果規則要求保護，僱主不能把它視為可有可無。"},{"en":"This phrase is formal and often appears in laws or regulations.","zh":"這個片語較正式，常出現在法律或規例中。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":6},{"front":"employer","meaning":"僱主","examples":[{"en":"An employer must protect workers who are overexposed to noise.","zh":"僱主必須保護過度暴露於噪音的工人。"},{"en":"An employer is a person or organisation that hires and pays workers.","zh":"Employer 是聘用並支付工人工資的人或機構。"},{"en":"A restaurant owner is an employer if they hire cooks and waiters.","zh":"如果餐廳老闆聘用廚師和侍應，他就是僱主。"},{"en":"Employers must create safe working conditions, not only pay salaries.","zh":"僱主不只支付薪金，也必須創造安全工作條件。"},{"en":"This word identifies the side responsible for managing workers.","zh":"這個詞指出負責管理工人的一方。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":6},{"front":"overexposed to noise","meaning":"過度暴露於噪音","examples":[{"en":"Workers overexposed to noise should receive protection.","zh":"過度暴露於噪音的工人應得到保護。"},{"en":"Overexposed to noise means exposed to too much noise for too long or at unsafe levels.","zh":"Overexposed to noise 指接觸噪音太多、太久或達到不安全水平。"},{"en":"A machine operator may be overexposed to noise if they work beside loud equipment all day.","zh":"如果機器操作員整天在嘈雜設備旁工作，可能過度暴露於噪音。"},{"en":"Workers who are overexposed to noise may develop hearing damage over time.","zh":"過度暴露於噪音的工人可能隨時間出現聽力損害。"},{"en":"This phrase shows that the exposure exceeds a safe amount.","zh":"這個片語顯示暴露量超過安全程度。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":6},{"front":"provide protection for","meaning":"為……提供保護","examples":[{"en":"Employers must provide protection for employees against harmful noise.","zh":"僱主必須為僱員提供保護，免受有害噪音影響。"},{"en":"To provide protection for someone means to give tools, rules, or support that keep them safe.","zh":"To provide protection for someone 指提供工具、規則或支援，使人保持安全。"},{"en":"A school provides protection for students by checking playground equipment.","zh":"學校透過檢查遊樂場設備為學生提供保護。"},{"en":"Earplugs and quieter machines can provide protection for workers in loud factories.","zh":"耳塞和較安靜機器可以為嘈雜工廠中的工人提供保護。"},{"en":"This phrase focuses on preventing harm before it happens.","zh":"這個片語著重在傷害發生前預防。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":6},{"front":"harmful effects of","meaning":"……的有害影響","examples":[{"en":"Employees need protection against the harmful effects of noise.","zh":"僱員需要保護，免受噪音的有害影響。"},{"en":"Harmful effects of something are the damaging results it can cause.","zh":"Harmful effects of something 是某事可能造成的損害結果。"},{"en":"Sunscreen protects skin from the harmful effects of strong sunlight.","zh":"防曬霜保護皮膚免受強烈陽光的有害影響。"},{"en":"The harmful effects of noise may include hearing loss, stress, and sleep problems.","zh":"噪音的有害影響可能包括聽力喪失、壓力和睡眠問題。"},{"en":"This phrase is useful when explaining why protection is needed.","zh":"這個片語適合解釋為何需要保護。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":6},{"front":"implement","meaning":"實施；執行","examples":[{"en":"Employers must implement a hearing conservation program.","zh":"僱主必須實施聽力保護計劃。"},{"en":"To implement a plan means to put it into action.","zh":"To implement a plan 指把計劃付諸實行。"},{"en":"A school may implement a new reading programme after poor test results.","zh":"學校可能在測驗成績差後實施新的閱讀計劃。"},{"en":"A policy has little value if nobody implements it properly.","zh":"如果沒有人妥善執行，政策就沒有太大價值。"},{"en":"This word focuses on action, not only planning.","zh":"這個詞著重行動，而不只是計劃。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":6},{"front":"continuing, effective","meaning":"持續而有效的","examples":[{"en":"OSHA requires a continuing, effective hearing conservation program.","zh":"OSHA要求一個持續而有效的聽力保護計劃。"},{"en":"Continuing, effective means ongoing and actually working well.","zh":"Continuing, effective 指持續進行並真正有效。"},{"en":"A school needs continuing, effective support for weak readers, not one short workshop.","zh":"學校需要對閱讀薄弱學生提供持續而有效的支援，而不是一次短工作坊。"},{"en":"A safety programme must be continuing and effective to protect workers over time.","zh":"安全計劃必須持續而有效，才能長期保護工人。"},{"en":"This phrase stresses both duration and real results.","zh":"這個片語同時強調時間長度和實際成果。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":6},{"front":"hearing conservation program","meaning":"聽力保護計劃","examples":[{"en":"Employers must implement a hearing conservation program.","zh":"僱主必須實施聽力保護計劃。"},{"en":"A hearing conservation program is a workplace plan to protect workers from hearing damage.","zh":"Hearing conservation program 是工作場所中保護工人免受聽力損害的計劃。"},{"en":"Such a program may include noise testing, ear protection, training, and hearing checks.","zh":"這類計劃可能包括噪音測試、耳部保護、培訓和聽力檢查。"},{"en":"A good hearing conservation program can catch early hearing changes before they become severe.","zh":"良好聽力保護計劃可以在聽力變化變嚴重前及早發現。"},{"en":"This phrase refers to prevention and monitoring of workplace hearing loss.","zh":"這個片語指預防和監察工作場所聽力喪失。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":6},{"front":"as outlined in","meaning":"如……所概述","examples":[{"en":"The program must follow the requirements outlined in OSHA’s Noise Standard.","zh":"該計劃必須遵守OSHA噪音標準所概述的要求。"},{"en":"As outlined in means as described or explained in a document or rule.","zh":"As outlined in 指如某文件或規則中所描述或解釋。"},{"en":"Students must follow the steps outlined in the exam instructions.","zh":"學生必須遵守考試指示中所概述的步驟。"},{"en":"If safety duties are outlined in a standard, employers should follow them clearly.","zh":"如果安全責任在標準中有所概述，僱主應清楚遵守。"},{"en":"This phrase points to an official source of detail.","zh":"這個片語指向細節的官方來源。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":6},{"front":"Noise Standard","meaning":"噪音標準","examples":[{"en":"OSHA’s Noise Standard outlines hearing-protection requirements.","zh":"OSHA的噪音標準概述聽力保護要求。"},{"en":"A Noise Standard is an official rule or guideline setting acceptable noise exposure levels.","zh":"Noise Standard 是設定可接受噪音暴露水平的官方規則或指引。"},{"en":"A factory may check the Noise Standard before deciding what ear protection workers need.","zh":"工廠在決定工人需要甚麼耳部保護前，可能查閱噪音標準。"},{"en":"Noise standards help turn health research into workplace rules.","zh":"噪音標準幫助把健康研究轉化為工作場所規則。"},{"en":"This phrase refers to a formal safety standard.","zh":"這個片語指正式安全標準。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":6},{"front":"Scary Sound Effects","meaning":"可怕的聲音影響","examples":[{"en":"The section Scary Sound Effects explains how noise can damage hearing.","zh":"“可怕的聲音影響”這一部分解釋噪音如何損害聽力。"},{"en":"Scary Sound Effects suggests that sound can have frightening health consequences.","zh":"Scary Sound Effects 暗示聲音可能有令人害怕的健康後果。"},{"en":"A lesson called Scary Sound Effects might show how loud music harms the inner ear.","zh":"一堂名為“可怕的聲音影響”的課，可能展示大聲音樂如何傷害內耳。"},{"en":"The title prepares readers to learn about hearing loss, tinnitus, and other damage.","zh":"這個標題讓讀者準備了解聽力喪失、耳鳴和其他損害。"},{"en":"This phrase makes the health effects of sound feel serious and memorable.","zh":"這個片語令聲音的健康影響顯得嚴重而易記。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":6},{"front":"numerous scientific studies","meaning":"大量科學研究","examples":[{"en":"Numerous scientific studies have confirmed the risks of loud sound.","zh":"大量科學研究已證實巨大聲音的風險。"},{"en":"Numerous scientific studies are many research projects using scientific methods.","zh":"Numerous scientific studies 是許多使用科學方法的研究項目。"},{"en":"Numerous scientific studies have shown that poor sleep affects concentration.","zh":"大量科學研究顯示睡眠不足影響專注力。"},{"en":"When numerous scientific studies agree, the evidence becomes harder to dismiss.","zh":"當大量科學研究得出一致結果，證據便更難被忽視。"},{"en":"This phrase suggests strong support from repeated research.","zh":"這個片語暗示來自反覆研究的強力支持。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":7},{"front":"over the years","meaning":"多年來","examples":[{"en":"Over the years, many studies have examined noise exposure.","zh":"多年來，許多研究檢視了噪音暴露。"},{"en":"Over the years means during a long period of time.","zh":"Over the years 指在很長一段時間中。"},{"en":"Over the years, a quiet village may become a busy suburb.","zh":"多年來，一條安靜村莊可能變成繁忙郊區。"},{"en":"Repeated research over the years can make a health risk clearer.","zh":"多年來反覆研究可以令健康風險更清楚。"},{"en":"This phrase shows gradual accumulation over time.","zh":"這個片語顯示隨時間逐漸累積。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":7},{"front":"exposure to certain levels of sound","meaning":"暴露於某些聲音水平","examples":[{"en":"Exposure to certain levels of sound can damage hearing.","zh":"暴露於某些聲音水平可以損害聽力。"},{"en":"Exposure to certain levels of sound means contact with noise at particular loudness levels.","zh":"Exposure to certain levels of sound 指接觸特定音量水平的噪音。"},{"en":"Workers may be tested if exposure to certain levels of sound happens every day.","zh":"如果工人每天暴露於某些聲音水平，可能需要接受檢查。"},{"en":"The higher and longer the exposure, the greater the risk to hearing.","zh":"暴露水平越高、時間越長，聽力風險越大。"},{"en":"This phrase connects sound level with health risk.","zh":"這個片語把聲音水平與健康風險連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":7},{"front":"damage hearing","meaning":"損害聽力","examples":[{"en":"High noise levels can damage hearing.","zh":"高噪音水平可以損害聽力。"},{"en":"To damage hearing means to harm the ability to hear clearly.","zh":"To damage hearing 指傷害清楚聽聲音的能力。"},{"en":"Listening to loud music through headphones every day can damage hearing.","zh":"每天用耳機聽大聲音樂可以損害聽力。"},{"en":"Once hearing is damaged, it may not fully recover.","zh":"一旦聽力受損，可能無法完全恢復。"},{"en":"This phrase describes harm to one of the senses.","zh":"這個片語描述對其中一種感官的傷害。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":7},{"front":"prolonged exposure","meaning":"長時間暴露","examples":[{"en":"Prolonged exposure can change the structure of inner-ear hair cells.","zh":"長時間暴露可以改變內耳毛細胞的結構。"},{"en":"Prolonged exposure means being exposed to something for a long time.","zh":"Prolonged exposure 指長時間接觸某事物。"},{"en":"Prolonged exposure to sunlight can damage skin without protection.","zh":"沒有保護下長時間暴露於陽光可以傷害皮膚。"},{"en":"Prolonged exposure to loud machines can slowly harm the ear.","zh":"長時間暴露於巨大機器聲可以慢慢傷害耳朵。"},{"en":"This phrase focuses on duration as a cause of damage.","zh":"這個片語著重時間長短作為傷害原因。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":7},{"front":"change the structure of","meaning":"改變……的結構","examples":[{"en":"Prolonged exposure can change the structure of hair cells.","zh":"長時間暴露可以改變毛細胞的結構。"},{"en":"To change the structure of something means to alter how its parts are shaped or arranged.","zh":"To change the structure of something 指改變其部分的形狀或排列方式。"},{"en":"A fire can change the structure of a building by weakening its beams.","zh":"火災可以透過削弱橫樑改變建築物的結構。"},{"en":"If noise changes the structure of ear cells, hearing may be permanently affected.","zh":"如果噪音改變耳部細胞的結構，聽力可能永久受影響。"},{"en":"This phrase describes physical change, not only temporary discomfort.","zh":"這個片語描述物理改變，而不只是暫時不適。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":7},{"front":"hair cells","meaning":"毛細胞","examples":[{"en":"Hair cells in the inner ear can be damaged by noise.","zh":"內耳中的毛細胞可能被噪音損害。"},{"en":"Hair cells are tiny sensory cells in the inner ear that help turn sound into nerve signals.","zh":"毛細胞是內耳中的微小感覺細胞，幫助把聲音轉化為神經訊號。"},{"en":"Loud noise can bend or damage hair cells, making hearing less clear.","zh":"巨大噪音可以令毛細胞彎曲或受損，使聽力變得不清楚。"},{"en":"Damaged hair cells may not grow back, so prevention matters.","zh":"受損毛細胞可能不會再生，所以預防很重要。"},{"en":"This phrase refers to ear cells, not ordinary hair on the head.","zh":"這個片語指耳部細胞，而不是頭上的普通頭髮。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":7},{"front":"inner ear","meaning":"內耳","examples":[{"en":"The inner ear contains hair cells that are sensitive to sound.","zh":"內耳含有對聲音敏感的毛細胞。"},{"en":"The inner ear is the deep part of the ear that helps with hearing and balance.","zh":"內耳是耳朵深處幫助聽力和平衡的部分。"},{"en":"Doctors may examine the inner ear when a patient reports dizziness or hearing problems.","zh":"當病人報告暈眩或聽力問題，醫生可能檢查內耳。"},{"en":"Damage inside the inner ear can affect hearing even if the outer ear looks normal.","zh":"即使外耳看起來正常，內耳損傷也可以影響聽力。"},{"en":"This phrase refers to a delicate part of the hearing system.","zh":"這個片語指聽覺系統中精細的部分。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":7},{"front":"result in hearing loss","meaning":"導致聽力喪失","examples":[{"en":"Damage to hair cells can result in hearing loss.","zh":"毛細胞受損可以導致聽力喪失。"},{"en":"To result in hearing loss means to cause a reduced ability to hear.","zh":"To result in hearing loss 指造成聽力能力下降。"},{"en":"Long exposure to loud headphones can result in hearing loss over time.","zh":"長時間暴露於大聲耳機可以隨時間導致聽力喪失。"},{"en":"If hearing loss results from cell damage, it may be difficult to reverse.","zh":"如果聽力喪失源於細胞損傷，可能難以逆轉。"},{"en":"This phrase links a cause with a hearing-related outcome.","zh":"這個片語把原因與聽力相關結果連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":7},{"front":"tinnitus","meaning":"耳鳴","examples":[{"en":"Loud noise can cause tinnitus.","zh":"巨大噪音可以造成耳鳴。"},{"en":"Tinnitus is hearing sounds such as ringing or buzzing when no outside sound is present.","zh":"Tinnitus 是在沒有外界聲音時仍聽到鈴聲或嗡嗡聲等聲音。"},{"en":"After a loud concert, a person may notice temporary tinnitus in the ears.","zh":"在很嘈的音樂會後，人可能注意到耳中有暫時性耳鳴。"},{"en":"Persistent tinnitus can disturb sleep, concentration, and mood.","zh":"持續耳鳴可以干擾睡眠、專注力和情緒。"},{"en":"This word describes a hearing symptom, not an external noise source.","zh":"這個詞描述聽覺症狀，而不是外部噪音來源。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":7},{"front":"ringing, roaring, buzzing, or clicking","meaning":"鈴聲、轟鳴聲、嗡嗡聲或咔嗒聲","examples":[{"en":"Tinnitus may involve ringing, roaring, buzzing, or clicking in the ears.","zh":"耳鳴可能包括耳中的鈴聲、轟鳴聲、嗡嗡聲或咔嗒聲。"},{"en":"Ringing, roaring, buzzing, or clicking are different sounds people may hear during tinnitus.","zh":"Ringing, roaring, buzzing, or clicking 是耳鳴時人可能聽到的不同聲音。"},{"en":"One person may hear ringing, while another hears buzzing or clicking.","zh":"一個人可能聽到鈴聲，另一個人則聽到嗡嗡聲或咔嗒聲。"},{"en":"These sounds can be stressful if they continue during quiet moments or sleep.","zh":"如果這些聲音在安靜時刻或睡眠時持續，可能令人有壓力。"},{"en":"This phrase lists common forms of unwanted ear noise.","zh":"這個片語列出常見的不想要耳內聲音形式。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":7},{"front":"coal miners","meaning":"煤礦工人","examples":[{"en":"NIOSH studies showed serious hearing impairment among coal miners.","zh":"NIOSH研究顯示煤礦工人中有嚴重聽力受損。"},{"en":"Coal miners are workers who extract coal from underground or surface mines.","zh":"煤礦工人是從地下或露天礦場開採煤炭的工人。"},{"en":"Coal miners may work near drills, conveyor belts, explosions, and heavy machinery.","zh":"煤礦工人可能在電鑽、輸送帶、爆破和重型機械附近工作。"},{"en":"Because mining is noisy, coal miners face a high risk of hearing loss.","zh":"因為採礦嘈雜，煤礦工人面對高聽力喪失風險。"},{"en":"This phrase identifies a worker group exposed to occupational noise.","zh":"這個片語指出一個暴露於職業噪音的工人群體。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":8},{"front":"hearing impairment","meaning":"聽力受損","examples":[{"en":"Many coal miners have hearing impairment by age 52.","zh":"許多煤礦工人到52歲時有聽力受損。"},{"en":"Hearing impairment is reduced ability to hear sounds clearly.","zh":"Hearing impairment 是清楚聽到聲音的能力下降。"},{"en":"A person with hearing impairment may ask others to repeat themselves often.","zh":"有聽力受損的人可能經常請別人重複說話。"},{"en":"Workplace noise can cause hearing impairment gradually over many years.","zh":"工作場所噪音可以多年來逐漸造成聽力受損。"},{"en":"This phrase is more formal than “hearing problem”.","zh":"這個片語比「聽力問題」更正式。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":8},{"front":"by age 52","meaning":"到52歲時","examples":[{"en":"Many coal miners have hearing impairment by age 52.","zh":"許多煤礦工人到52歲時已有聽力受損。"},{"en":"By age 52 means before or when a person reaches 52 years old.","zh":"By age 52 指在一個人到52歲之前或到52歲時。"},{"en":"Some workers develop back pain by age 40 if their job involves heavy lifting.","zh":"如果工作涉及搬重物，有些工人到40歲時可能出現背痛。"},{"en":"If many people have hearing loss by age 52, the damage may begin much earlier.","zh":"如果許多人到52歲時已有聽力喪失，損害可能早得多開始。"},{"en":"This phrase marks the age by which a condition appears.","zh":"這個片語標示某狀況出現的年齡界線。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":8},{"front":"compared to","meaning":"與……相比","examples":[{"en":"The figure is very high compared to the general population.","zh":"與一般人口相比，這個數字非常高。"},{"en":"Compared to means measured or judged beside another person, group, or thing.","zh":"Compared to 指與另一個人、群體或事物並列衡量或判斷。"},{"en":"This classroom is quiet compared to the one beside the road.","zh":"與道路旁邊的課室相比，這間課室很安靜。"},{"en":"A health risk may look serious when compared to the general population.","zh":"與一般人口相比，某健康風險可能顯得嚴重。"},{"en":"This phrase helps show contrast or relative size.","zh":"這個片語有助顯示對比或相對大小。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":8},{"front":"general population","meaning":"一般人口","examples":[{"en":"The general population has a much lower rate of hearing impairment.","zh":"一般人口的聽力受損比率低得多。"},{"en":"The general population means ordinary people as a whole, not a special worker or patient group.","zh":"General population 指整體普通人，而不是特定工人或病人群體。"},{"en":"Doctors compare miners with the general population to see whether their job adds risk.","zh":"醫生把礦工與一般人口比較，以了解其工作是否增加風險。"},{"en":"If a disease is more common in one job than in the general population, workplace factors may matter.","zh":"如果某疾病在某職業中比在一般人口中更常見，工作場所因素可能重要。"},{"en":"This phrase gives a broad comparison group.","zh":"這個片語提供廣泛比較群體。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":8},{"front":"male metal/nonmetal miners","meaning":"男性金屬／非金屬礦工","examples":[{"en":"Many male metal/nonmetal miners experience hearing impairment by age 60.","zh":"許多男性金屬／非金屬礦工到60歲時出現聽力受損。"},{"en":"Male metal/nonmetal miners are men who work in mines extracting metals or nonmetal minerals.","zh":"Male metal/nonmetal miners 是在金屬或非金屬礦場工作的男性礦工。"},{"en":"These miners may hear drilling, blasting, crushing, and vehicle noise during work.","zh":"這些礦工在工作中可能聽到鑽探、爆破、碎石和車輛噪音。"},{"en":"Long exposure to mining noise can make hearing problems common by later adulthood.","zh":"長期暴露於採礦噪音，可以令聽力問題在較後成年期變得常見。"},{"en":"This phrase identifies a specific group in occupational health research.","zh":"這個片語指出職業健康研究中的特定群體。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":8},{"front":"experience hearing impairment","meaning":"出現聽力受損","examples":[{"en":"Many miners experience hearing impairment as they age.","zh":"許多礦工隨着年齡增長出現聽力受損。"},{"en":"To experience hearing impairment means to suffer from reduced hearing ability.","zh":"To experience hearing impairment 指出現聽力能力下降。"},{"en":"A musician may experience hearing impairment after years of loud performances.","zh":"音樂人多年進行大聲演出後，可能出現聽力受損。"},{"en":"People who experience hearing impairment may find conversations tiring.","zh":"出現聽力受損的人可能覺得對話很費力。"},{"en":"This phrase describes living with a hearing problem.","zh":"這個片語描述經歷聽力問題。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":8},{"front":"adolescence onward","meaning":"從青春期開始","examples":[{"en":"From adolescence onward, females tend to have better hearing than males.","zh":"從青春期開始，女性往往比男性有更好聽力。"},{"en":"Adolescence onward means from the teenage years and continuing after that.","zh":"Adolescence onward 指從青少年時期開始並持續之後。"},{"en":"From adolescence onward, sleep habits can strongly affect school performance.","zh":"從青春期開始，睡眠習慣可以強烈影響學業表現。"},{"en":"If hearing differences appear from adolescence onward, researchers may look at behaviour and exposure.","zh":"如果聽力差異從青春期開始出現，研究人員可能查看行為和暴露。"},{"en":"This phrase marks the beginning of a long-term pattern.","zh":"這個片語標示長期模式的開始。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":8},{"front":"tend to have","meaning":"往往有","examples":[{"en":"Females tend to have better hearing than males.","zh":"女性往往有比男性更好的聽力。"},{"en":"Tend to have means usually have, though not always.","zh":"Tend to have 指通常有，但不是永遠如此。"},{"en":"Students who read daily tend to have stronger vocabulary.","zh":"每天閱讀的學生往往有較強詞彙量。"},{"en":"People who work in quiet offices tend to have less occupational noise exposure.","zh":"在安靜辦公室工作的人往往有較少職業噪音暴露。"},{"en":"This phrase describes a general pattern, not a rule without exceptions.","zh":"這個片語描述一般模式，而不是沒有例外的規則。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":8},{"front":"some degree of hearing loss","meaning":"某程度的聽力喪失","examples":[{"en":"Nearly half of all construction workers have some degree of hearing loss.","zh":"幾乎一半建築工人有某程度的聽力喪失。"},{"en":"Some degree of hearing loss means a small, moderate, or serious reduction in hearing.","zh":"Some degree of hearing loss 指輕微、中等或嚴重的聽力下降。"},{"en":"A person with some degree of hearing loss may still hear speech but miss soft sounds.","zh":"有某程度聽力喪失的人可能仍聽到說話，但聽漏細小聲音。"},{"en":"Early hearing loss can worsen if noise exposure continues.","zh":"如果噪音暴露持續，早期聽力喪失可能惡化。"},{"en":"This phrase shows that hearing loss can exist on a scale.","zh":"這個片語顯示聽力喪失有程度之分。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":8},{"front":"reveal that","meaning":"顯示","examples":[{"en":"NIOSH research reveals that noise affects carpenters’ hearing early.","zh":"NIOSH研究顯示噪音早期已影響木匠聽力。"},{"en":"Reveal that means show or make clear something that was not fully known.","zh":"Reveal that 指顯示或弄清楚之前未被完全知道的事情。"},{"en":"Test results may reveal that a student needs glasses.","zh":"測試結果可能顯示學生需要配眼鏡。"},{"en":"Research can reveal hidden health effects before people notice symptoms.","zh":"研究可以在人們注意到症狀前揭示隱藏健康影響。"},{"en":"This phrase introduces evidence that makes something clearer.","zh":"這個片語引出令事情更清楚的證據。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":8},{"front":"equivalent to","meaning":"相當於","examples":[{"en":"The average carpenter’s hearing is equivalent to that of a much older person.","zh":"普通木匠的聽力相當於年長得多的人。"},{"en":"Equivalent to means equal or very similar in value, level, or effect.","zh":"Equivalent to 指在價值、水平或作用上相等或非常相似。"},{"en":"Walking thirty minutes may be equivalent to light exercise for some beginners.","zh":"對一些初學者來說，步行三十分鐘可能相當於輕量運動。"},{"en":"If a young worker’s hearing is equivalent to an older person’s, noise may have aged the ear.","zh":"如果年輕工人的聽力相當於年長者，噪音可能令耳朵提早老化。"},{"en":"This phrase helps compare two things at the same level.","zh":"這個片語有助比較兩件事是否處於同一水平。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":9},{"front":"otherwise healthy","meaning":"其他方面健康的","examples":[{"en":"The comparison is with an otherwise healthy fifty-year-old male.","zh":"這個比較對象是一名其他方面健康的五十歲男性。"},{"en":"Otherwise healthy means healthy in other respects except for the specific issue being discussed.","zh":"Otherwise healthy 指除了正在討論的特定問題外，其他方面健康。"},{"en":"An otherwise healthy child may still suffer from poor sleep because of noise.","zh":"其他方面健康的孩子仍可能因噪音而睡眠差。"},{"en":"If an otherwise healthy adult has hearing loss, workplace exposure may be examined.","zh":"如果一名其他方面健康的成年人有聽力喪失，可能需要檢視工作場所暴露。"},{"en":"This phrase narrows attention to one health problem.","zh":"這個片語把注意力收窄到一個健康問題。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":9},{"front":"be exposed to noise","meaning":"暴露於噪音","examples":[{"en":"A healthy fifty-year-old male may not have been exposed to noise.","zh":"一名健康的五十歲男性可能未曾暴露於噪音。"},{"en":"To be exposed to noise means to experience noise, especially for a period of time.","zh":"To be exposed to noise 指接觸噪音，尤其是一段時間。"},{"en":"Office workers may be exposed to noise if they sit beside a construction site.","zh":"如果辦公室員工坐在工地旁邊，可能暴露於噪音。"},{"en":"People exposed to noise repeatedly may need hearing tests.","zh":"反覆暴露於噪音的人可能需要聽力測試。"},{"en":"This phrase describes contact with sound as a possible risk.","zh":"這個片語把接觸聲音描述為可能風險。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":9},{"front":"medical director","meaning":"醫療總監","examples":[{"en":"William Luxford is the medical director of the House Ear Clinic.","zh":"William Luxford是House Ear Clinic的醫療總監。"},{"en":"A medical director is a senior doctor responsible for medical leadership in a clinic or organisation.","zh":"Medical director 是負責診所或機構醫療領導工作的資深醫生。"},{"en":"A medical director may decide treatment standards and supervise clinical staff.","zh":"醫療總監可能決定治療標準並監督臨床員工。"},{"en":"When a medical director comments on health, readers may treat the opinion as expert advice.","zh":"當醫療總監評論健康問題，讀者可能把該意見視為專家建議。"},{"en":"This phrase describes a leadership role in healthcare.","zh":"這個片語描述醫療中的領導角色。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":9},{"front":"House Ear Clinic","meaning":"House Ear Clinic 耳科診所","examples":[{"en":"The House Ear Clinic is mentioned in relation to hearing health.","zh":"文章在聽力健康方面提到House Ear Clinic耳科診所。"},{"en":"The House Ear Clinic is a clinic name connected with ear and hearing treatment.","zh":"House Ear Clinic 是與耳部和聽力治療相關的診所名稱。"},{"en":"A clinic focused on ears may treat hearing loss, tinnitus, and balance problems.","zh":"專注耳科的診所可能治療聽力喪失、耳鳴和平衡問題。"},{"en":"Expert clinics can help explain how noise affects hearing over time.","zh":"專科診所可以幫助解釋噪音如何隨時間影響聽力。"},{"en":"This phrase names a medical institution in the passage.","zh":"這個片語命名文章中的醫療機構。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":9},{"front":"point out","meaning":"指出","examples":[{"en":"William Luxford points out one piece of good news.","zh":"William Luxford指出一項好消息。"},{"en":"To point out something means to mention it because it is important or useful.","zh":"To point out something 指因某事重要或有用而提及它。"},{"en":"A teacher may point out a common grammar mistake before an exam.","zh":"老師可能在考試前指出常見文法錯誤。"},{"en":"Doctors point out risks so patients can make safer choices.","zh":"醫生指出風險，讓病人作出較安全選擇。"},{"en":"This phrase often introduces a detail the speaker wants others to notice.","zh":"這個片語常引出說話者希望他人注意的細節。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":9},{"front":"one piece of good news","meaning":"一項好消息","examples":[{"en":"One piece of good news is that hearing loss can stop worsening when exposure stops.","zh":"一項好消息是，當暴露停止，聽力喪失可以停止惡化。"},{"en":"One piece of good news means one positive fact in a difficult situation.","zh":"One piece of good news 指困難情況中的一個正面事實。"},{"en":"After a poor test result, one piece of good news may be that the student knows what to practise.","zh":"在測驗成績差後，一項好消息可能是學生知道要練習甚麼。"},{"en":"In noise health, the good news is that reducing exposure can prevent further damage.","zh":"在噪音健康方面，好消息是減少暴露可以防止進一步損害。"},{"en":"This phrase softens bad news by adding hope.","zh":"這個片語透過加入希望來緩和壞消息。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":9},{"front":"continuous noise exposure","meaning":"持續噪音暴露","examples":[{"en":"Continuous noise exposure can lead to continued hearing loss.","zh":"持續噪音暴露可以導致聽力喪失持續惡化。"},{"en":"Continuous noise exposure means ongoing contact with noise without enough quiet breaks.","zh":"Continuous noise exposure 指持續接觸噪音，而沒有足夠安靜休息。"},{"en":"A worker beside a loud machine all day faces continuous noise exposure.","zh":"整天在巨大機器旁的工人面對持續噪音暴露。"},{"en":"Continuous exposure can be more harmful than a short loud sound if it lasts for years.","zh":"如果多年持續暴露，它可能比短暫巨大聲響更有害。"},{"en":"This phrase stresses uninterrupted or repeated exposure.","zh":"這個片語強調不間斷或反覆暴露。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":9},{"front":"lead to","meaning":"導致","examples":[{"en":"Continuous noise exposure can lead to hearing loss.","zh":"持續噪音暴露可以導致聽力喪失。"},{"en":"Lead to means cause or result in something.","zh":"Lead to 指造成或導致某結果。"},{"en":"Poor sleep can lead to weak concentration in class.","zh":"睡眠不足可以導致課堂專注力差。"},{"en":"If loud noise leads to hearing loss, prevention should start early.","zh":"如果巨大噪音導致聽力喪失，預防應及早開始。"},{"en":"This phrase connects a cause with its effect.","zh":"這個片語把原因與結果連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":9},{"front":"continuation of hearing loss","meaning":"聽力喪失持續惡化","examples":[{"en":"Ongoing exposure can lead to the continuation of hearing loss.","zh":"持續暴露可以導致聽力喪失持續惡化。"},{"en":"Continuation of hearing loss means hearing keeps getting worse over time.","zh":"Continuation of hearing loss 指聽力隨時間繼續變差。"},{"en":"A musician who keeps playing without ear protection may face continuation of hearing loss.","zh":"如果音樂人持續不戴耳部保護演奏，可能面對聽力喪失持續惡化。"},{"en":"Stopping exposure can prevent hearing loss from continuing further.","zh":"停止暴露可以防止聽力喪失繼續惡化。"},{"en":"This phrase focuses on worsening that does not stop.","zh":"這個片語著重不停止的惡化。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":9},{"front":"as soon as","meaning":"一……就……","examples":[{"en":"As soon as the exposure is stopped, the hearing loss stops.","zh":"一旦暴露停止，聽力喪失便停止。"},{"en":"As soon as means immediately after something happens.","zh":"As soon as 指某事發生後立即。"},{"en":"As soon as the bell rings, students leave the classroom.","zh":"鐘聲一響，學生就離開課室。"},{"en":"As soon as loud exposure stops, further hearing damage may stop progressing.","zh":"一旦巨大噪音暴露停止，進一步聽力損害可能停止惡化。"},{"en":"This phrase shows a very close time connection.","zh":"這個片語顯示非常緊密的時間關係。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":9},{"front":"a change in environment","meaning":"環境改變","examples":[{"en":"A change in environment can improve a person’s hearing health.","zh":"環境改變可以改善一個人的聽力健康。"},{"en":"A change in environment means moving to or creating a different surrounding condition.","zh":"A change in environment 指搬到或創造一種不同的周圍條件。"},{"en":"A student may sleep better after a change in environment from a noisy room to a quiet one.","zh":"學生從嘈雜房間換到安靜房間後，可能睡得更好。"},{"en":"Reducing noise at work is a change in environment that can protect hearing.","zh":"減少工作噪音是一種可以保護聽力的環境改變。"},{"en":"This phrase shows how surroundings affect health.","zh":"這個片語顯示周圍環境如何影響健康。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":10},{"front":"improve hearing health","meaning":"改善聽力健康","examples":[{"en":"Reducing noise exposure can improve hearing health.","zh":"減少噪音暴露可以改善聽力健康。"},{"en":"To improve hearing health means to protect or strengthen a person’s ability to hear well.","zh":"To improve hearing health 指保護或強化一個人良好聽聲音的能力。"},{"en":"Wearing ear protection at concerts can improve hearing health by preventing damage.","zh":"在音樂會戴耳部保護可以透過防止損害來改善聽力健康。"},{"en":"Quieter workplaces can improve hearing health for employees over many years.","zh":"較安靜工作場所可以多年來改善僱員聽力健康。"},{"en":"This phrase focuses on prevention as well as recovery.","zh":"這個片語著重預防，也包括恢復。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":10},{"front":"catch up with","meaning":"趕上；逐漸證實","examples":[{"en":"Research is catching up with anecdotal evidence.","zh":"研究正在趕上軼事證據。"},{"en":"To catch up with something means to reach the same level after being behind.","zh":"To catch up with something 指在落後後追到同一水平。"},{"en":"A student who missed lessons can catch up with the class through extra practice.","zh":"缺課學生可以透過額外練習趕上全班。"},{"en":"Research catches up with experience when studies begin to confirm what people have long noticed.","zh":"當研究開始證實人們長期注意到的事情，研究便逐漸證實經驗。"},{"en":"This phrase suggests delayed confirmation or progress.","zh":"這個片語暗示延遲的確認或進展。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":10},{"front":"anecdotal evidence","meaning":"軼事證據；個案經驗證據","examples":[{"en":"Anecdotal evidence suggests that changing environment can protect hearing.","zh":"軼事證據顯示改變環境可以保護聽力。"},{"en":"Anecdotal evidence is information based on personal stories rather than systematic research.","zh":"Anecdotal evidence 是基於個人故事，而不是系統研究的資訊。"},{"en":"A teacher may hear anecdotal evidence that students sleep better after less homework.","zh":"老師可能聽到個案經驗證據，說學生功課較少後睡得更好。"},{"en":"Anecdotal evidence can suggest a problem, but studies are needed to test it.","zh":"軼事證據可以提示問題，但仍需要研究測試。"},{"en":"This phrase is useful when experience comes before formal proof.","zh":"這個片語適用於經驗先於正式證據時。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":10},{"front":"issue of Pediatrics","meaning":"《Pediatrics》期刊某期","examples":[{"en":"The study appeared in the July 2001 issue of Pediatrics.","zh":"該研究刊登於2001年7月的《Pediatrics》期刊某期。"},{"en":"An issue of a journal is one published edition of that journal.","zh":"期刊的 issue 是該期刊出版的一期。"},{"en":"A medical article may appear in the January issue of a health journal.","zh":"醫學文章可能刊登於健康期刊一月號。"},{"en":"Knowing the issue helps readers find the exact study.","zh":"知道期號有助讀者找到確切研究。"},{"en":"This phrase identifies where and when an article was published.","zh":"這個片語指出文章在哪裡和何時發表。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":10},{"front":"Centers for Disease Control and Prevention","meaning":"美國疾病控制及預防中心","examples":[{"en":"The Centers for Disease Control and Prevention reported hearing problems among children.","zh":"美國疾病控制及預防中心報告了兒童中的聽力問題。"},{"en":"The Centers for Disease Control and Prevention is a U.S. public-health agency.","zh":"美國疾病控制及預防中心是美國公共衛生機構。"},{"en":"It studies diseases, injuries, and health risks affecting the population.","zh":"它研究影響人口的疾病、傷害和健康風險。"},{"en":"CDC reports can influence schools, doctors, and health policies.","zh":"CDC報告可以影響學校、醫生和健康政策。"},{"en":"This phrase names an organisation involved in public-health research.","zh":"這個片語命名參與公共衛生研究的機構。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":10},{"front":"report that","meaning":"報告指出","examples":[{"en":"Researchers reported that many American children had noise-induced hearing changes.","zh":"研究人員報告指出，許多美國兒童有噪音引致的聽力變化。"},{"en":"To report that something happened means to state it based on research or observation.","zh":"To report that something happened 指根據研究或觀察陳述某事發生。"},{"en":"Doctors reported that fewer patients slept well during the noisy construction period.","zh":"醫生報告指出，在嘈雜施工期間睡得好的病人較少。"},{"en":"Reports can draw public attention to problems that families may not notice early.","zh":"報告可以把公眾注意力帶到家庭未必早期察覺的問題上。"},{"en":"This phrase introduces a stated finding.","zh":"這個片語引出一項被陳述的發現。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":10},{"front":"based on","meaning":"基於","examples":[{"en":"The estimate was based on audiometric testing of children.","zh":"這項估計基於兒童的聽力測試。"},{"en":"Based on means supported by or using particular evidence.","zh":"Based on 指由特定證據支持或使用特定證據。"},{"en":"A teacher’s advice should be based on the student’s actual work.","zh":"老師的建議應基於學生的實際作品。"},{"en":"If a health estimate is based on testing, it is stronger than a guess.","zh":"如果健康估計基於測試，便比猜測更有力。"},{"en":"This phrase shows the evidence behind a claim.","zh":"這個片語顯示主張背後的證據。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":10},{"front":"audiometric testing","meaning":"聽力測試","examples":[{"en":"Audiometric testing was used to assess children’s hearing.","zh":"聽力測試被用來評估兒童的聽力。"},{"en":"Audiometric testing is a hearing test that measures how well a person hears different sounds.","zh":"Audiometric testing 是量度一個人聽到不同聲音能力的測試。"},{"en":"A clinic may use audiometric testing when a child often asks people to repeat themselves.","zh":"當孩子經常請別人重複說話時，診所可能使用聽力測試。"},{"en":"Audiometric testing can detect hearing changes before they become obvious in daily life.","zh":"聽力測試可以在聽力變化於日常生活中變明顯前偵測到它。"},{"en":"This phrase describes a formal method of checking hearing.","zh":"這個片語描述正式檢查聽力的方法。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":10},{"front":"National Health and Nutrition Examination Survey","meaning":"全國健康與營養檢查調查","examples":[{"en":"The children were tested as part of the Third National Health and Nutrition Examination Survey.","zh":"這些兒童作為第三次全國健康與營養檢查調查的一部分接受測試。"},{"en":"The National Health and Nutrition Examination Survey is a large health survey that collects data on people’s health and diet.","zh":"National Health and Nutrition Examination Survey 是收集人們健康和飲食數據的大型健康調查。"},{"en":"Such surveys can include interviews, physical exams, and medical tests.","zh":"這類調查可以包括訪問、身體檢查和醫療測試。"},{"en":"Large surveys help researchers see health patterns across a population.","zh":"大型調查幫助研究人員看見人口中的健康模式。"},{"en":"This phrase names a data source for public-health research.","zh":"這個片語命名公共衛生研究的數據來源。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":10},{"front":"an estimated 12.5 per cent","meaning":"估計12.5%","examples":[{"en":"An estimated 12.5 per cent of American children had dulled hearing.","zh":"估計12.5%的美國兒童有聽力變鈍。"},{"en":"An estimated 12.5 per cent means about 12.5 per cent, based on available data.","zh":"An estimated 12.5 per cent 指根據現有數據，大約12.5%。"},{"en":"An estimated 20 per cent of students may need extra reading support in a school.","zh":"一所學校中估計20%的學生可能需要額外閱讀支援。"},{"en":"Using an estimate shows that the number is informed but not perfectly exact.","zh":"使用估計顯示數字有根據，但不一定完全精確。"},{"en":"This phrase introduces an approximate percentage.","zh":"這個片語引出近似百分比。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":10},{"front":"noise-induced hearing threshold shifts","meaning":"噪音引致的聽閾位移","examples":[{"en":"Some children have noise-induced hearing threshold shifts.","zh":"一些兒童有噪音引致的聽閾位移。"},{"en":"Noise-induced hearing threshold shifts are changes in the quietest sounds a person can hear because of noise exposure.","zh":"Noise-induced hearing threshold shifts 是因噪音暴露而導致一個人能聽到的最細聲音水平改變。"},{"en":"A child with a threshold shift may need louder sounds before they notice them.","zh":"有聽閾位移的孩子可能需要較大聲音才注意到。"},{"en":"Continued loud noise can turn small hearing changes into more serious loss.","zh":"持續巨大噪音可以把細小聽力變化變成更嚴重喪失。"},{"en":"This technical phrase describes early measurable hearing change.","zh":"這個技術片語描述早期可量度的聽力變化。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":11},{"front":"dulled hearing","meaning":"聽力變鈍","examples":[{"en":"Noise-induced hearing threshold shifts mean dulled hearing.","zh":"噪音引致的聽閾位移意思是聽力變鈍。"},{"en":"Dulled hearing means hearing becomes less sharp or less sensitive.","zh":"Dulled hearing 指聽力變得不夠敏銳或不夠敏感。"},{"en":"After a loud concert, a person may have temporary dulled hearing.","zh":"在大聲音樂會後，人可能暫時聽力變鈍。"},{"en":"If dulled hearing continues, children may miss soft speech sounds in class.","zh":"如果聽力變鈍持續，兒童可能在課堂上聽漏細小語音。"},{"en":"This phrase describes reduced hearing clarity.","zh":"這個片語描述聽力清晰度下降。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":11},{"front":"in one or both ears","meaning":"在一隻或兩隻耳朵","examples":[{"en":"Some children had dulled hearing in one or both ears.","zh":"一些兒童在一隻或兩隻耳朵有聽力變鈍。"},{"en":"In one or both ears means affecting either one ear or both ears.","zh":"In one or both ears 指影響其中一隻耳朵或兩隻耳朵。"},{"en":"A child may hear ringing in one or both ears after loud noise exposure.","zh":"兒童在暴露於巨大噪音後，可能在一隻或兩隻耳朵聽到耳鳴。"},{"en":"Hearing tests check each ear separately because damage may not be equal.","zh":"聽力測試會分別檢查每隻耳朵，因為損害未必相同。"},{"en":"This phrase specifies where the hearing problem occurs.","zh":"這個片語指出聽力問題出現的位置。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":11},{"front":"limited hearing damage","meaning":"有限的聽力損害","examples":[{"en":"Most affected children had only limited hearing damage.","zh":"大多數受影響兒童只有有限的聽力損害。"},{"en":"Limited hearing damage means the damage is not severe or widespread.","zh":"Limited hearing damage 指損害不嚴重或不廣泛。"},{"en":"A child may have limited hearing damage that appears only at high frequencies.","zh":"孩子可能只有在高頻聲音上出現有限的聽力損害。"},{"en":"Limited damage can still matter if continued noise makes it worse.","zh":"如果持續噪音令它惡化，有限損害仍然重要。"},{"en":"This phrase suggests a smaller problem, not no problem at all.","zh":"這個片語暗示問題較小，但不是完全沒有問題。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":11},{"front":"continued exposure to","meaning":"持續暴露於……","examples":[{"en":"Continued exposure to excessive noise can harm children’s hearing.","zh":"持續暴露於過量噪音可以傷害兒童聽力。"},{"en":"Continued exposure to something means repeated or ongoing contact with it.","zh":"Continued exposure to something 指反覆或持續接觸某事物。"},{"en":"Continued exposure to bright screens at night can disturb sleep.","zh":"夜間持續暴露於明亮螢幕可以干擾睡眠。"},{"en":"Children’s hearing may worsen if continued exposure to loud toys or music continues.","zh":"如果兒童持續暴露於嘈雜玩具或音樂，聽力可能惡化。"},{"en":"This phrase shows risk building over time.","zh":"這個片語顯示風險隨時間累積。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":11},{"front":"excessive noise","meaning":"過量噪音","examples":[{"en":"Excessive noise can lead to difficulties with sound discrimination.","zh":"過量噪音可以導致聲音辨別困難。"},{"en":"Excessive noise means more noise than is safe, healthy, or reasonable.","zh":"Excessive noise 指超過安全、健康或合理程度的噪音。"},{"en":"A classroom beside roadworks may suffer from excessive noise during lessons.","zh":"位於道路工程旁邊的課室，課堂期間可能受過量噪音影響。"},{"en":"Excessive noise can make it difficult to sleep, learn, or hear speech clearly.","zh":"過量噪音可以令人難以睡眠、學習或清楚聽到說話。"},{"en":"This phrase describes noise as a harmful excess.","zh":"這個片語把噪音描述為有害的過量。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":11},{"front":"high-frequency sound discrimination","meaning":"高頻聲音辨別","examples":[{"en":"Excessive noise can cause difficulties with high-frequency sound discrimination.","zh":"過量噪音可以造成高頻聲音辨別困難。"},{"en":"High-frequency sound discrimination is the ability to tell apart high-pitched sounds.","zh":"High-frequency sound discrimination 是分辨高音調聲音的能力。"},{"en":"Children need sound discrimination to hear small differences in speech.","zh":"兒童需要聲音辨別能力來聽出語音中的細小差異。"},{"en":"If high-frequency discrimination weakens, a child may confuse similar speech sounds.","zh":"如果高頻辨別能力變弱，孩子可能混淆相似語音。"},{"en":"This phrase describes a specific listening skill.","zh":"這個片語描述一項特定聆聽技能。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":11},{"front":"potentially harmful sounds","meaning":"可能有害的聲音","examples":[{"en":"Stereos, concerts, toys and fireworks can produce potentially harmful sounds.","zh":"立體聲音響、音樂會、玩具和煙花可以產生可能有害的聲音。"},{"en":"Potentially harmful sounds are sounds that may damage hearing or health.","zh":"Potentially harmful sounds 是可能損害聽力或健康的聲音。"},{"en":"A toy held close to a baby’s ear can produce potentially harmful sounds.","zh":"貼近嬰兒耳朵的玩具可能產生可能有害的聲音。"},{"en":"If a sound is potentially harmful, people should reduce volume or distance.","zh":"如果聲音可能有害，人們應降低音量或拉遠距離。"},{"en":"This phrase shows possible danger, even before damage is proven in one person.","zh":"這個片語顯示可能危險，即使尚未在某人身上證明損害。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":11},{"front":"stereos","meaning":"立體聲音響","examples":[{"en":"Stereos can produce potentially harmful sounds.","zh":"立體聲音響可以產生可能有害的聲音。"},{"en":"Stereos are sound systems used to play music through speakers.","zh":"Stereos 是透過揚聲器播放音樂的音響系統。"},{"en":"A teenager may turn up a stereo so loudly that neighbours complain.","zh":"青少年可能把立體聲音響開得很大聲，令鄰居投訴。"},{"en":"Loud stereos can damage hearing if people listen too close for too long.","zh":"如果人們太近、太久聽大聲音響，立體聲音響可以損害聽力。"},{"en":"This word refers to music equipment, not the music itself.","zh":"這個詞指音樂設備，而不是音樂本身。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":11},{"front":"music concerts","meaning":"音樂會","examples":[{"en":"Music concerts can expose people to very loud sound.","zh":"音樂會可以令人在巨大聲音中暴露。"},{"en":"Music concerts are live events where musicians perform for an audience.","zh":"Music concerts 是音樂人為觀眾現場演出的活動。"},{"en":"People at music concerts may stand close to large speakers for hours.","zh":"音樂會上的人可能數小時站在大型揚聲器附近。"},{"en":"Earplugs can reduce the risk of hearing damage at loud concerts.","zh":"耳塞可以降低在大聲音樂會中聽力受損的風險。"},{"en":"This phrase identifies a common leisure source of loud noise.","zh":"這個片語指出常見休閒噪音來源。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":11},{"front":"toy telephones","meaning":"玩具電話","examples":[{"en":"Toy telephones may produce potentially harmful sounds.","zh":"玩具電話可能產生可能有害的聲音。"},{"en":"Toy telephones are children’s toys shaped like phones, often with buttons and sound effects.","zh":"Toy telephones 是形狀像電話的兒童玩具，通常有按鈕和聲音效果。"},{"en":"A toy telephone held against the ear may be louder than parents expect.","zh":"貼着耳朵使用的玩具電話，可能比父母預期更大聲。"},{"en":"If a toy makes very loud sounds, it may not be safe for young children.","zh":"如果玩具發出很大聲音，對幼兒可能不安全。"},{"en":"This phrase shows that even toys can be noise sources.","zh":"這個片語顯示即使玩具也可以是噪音來源。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":11},{"front":"rattles","meaning":"搖鈴玩具","examples":[{"en":"Certain rattles can produce potentially harmful sounds.","zh":"某些搖鈴玩具可以產生可能有害的聲音。"},{"en":"Rattles are baby toys that make noise when shaken.","zh":"Rattles 是搖動時會發出聲音的嬰兒玩具。"},{"en":"A rattle may seem harmless, but some can be loud near a baby’s ear.","zh":"搖鈴看似無害，但有些在嬰兒耳旁可能很大聲。"},{"en":"Parents can protect children by choosing quieter toys.","zh":"父母可以透過選擇較安靜玩具來保護孩子。"},{"en":"This word refers to simple sound-making toys for babies.","zh":"這個詞指給嬰兒使用的簡單發聲玩具。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":12},{"front":"lawnmowers","meaning":"割草機","examples":[{"en":"Lawnmowers are listed as a source of potentially harmful sound.","zh":"割草機被列為可能有害聲音的來源。"},{"en":"Lawnmowers are machines used to cut grass.","zh":"Lawnmowers 是用來割草的機器。"},{"en":"Gardeners may use lawnmowers for long periods during warm seasons.","zh":"園丁在溫暖季節可能長時間使用割草機。"},{"en":"Loud lawnmowers can contribute to noise exposure for workers and neighbours.","zh":"嘈雜割草機可以增加工人和鄰居的噪音暴露。"},{"en":"This word names a common household and workplace noise source.","zh":"這個詞命名常見家居和工作場所噪音來源。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":12},{"front":"fireworks","meaning":"煙花","examples":[{"en":"Fireworks can produce potentially harmful sounds.","zh":"煙花可以產生可能有害的聲音。"},{"en":"Fireworks are explosive displays used in celebrations and public events.","zh":"Fireworks 是用於慶祝和公共活動的爆炸性表演。"},{"en":"Fireworks can be beautiful, but their sudden loud bangs may hurt ears.","zh":"煙花可以很美，但突然的巨大爆炸聲可能傷耳。"},{"en":"Standing too close to fireworks can increase the risk of hearing damage.","zh":"站得太近煙花可以增加聽力受損風險。"},{"en":"This word connects celebration with possible noise danger.","zh":"這個詞把慶祝與可能的噪音危險連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":12},{"front":"Beyond the Ears","meaning":"不止影響耳朵","examples":[{"en":"The section Beyond the Ears explains effects of noise beyond hearing loss.","zh":"“不止影響耳朵”這一部分解釋噪音在聽力喪失以外的影響。"},{"en":"Beyond the Ears means noise affects more than the hearing system.","zh":"Beyond the Ears 指噪音影響的不只是聽覺系統。"},{"en":"A lesson called Beyond the Ears might discuss sleep, blood pressure, and learning.","zh":"一堂名為“不止影響耳朵”的課，可能討論睡眠、血壓和學習。"},{"en":"Noise can harm the body even when the ears are not the only concern.","zh":"即使耳朵不是唯一憂慮，噪音仍可以傷害身體。"},{"en":"This title signals a wider health discussion.","zh":"這個標題提示更廣泛的健康討論。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":12},{"front":"do not stop with","meaning":"不止於……","examples":[{"en":"The effects of sound do not stop with the ears.","zh":"聲音的影響不止於耳朵。"},{"en":"Do not stop with something means continue beyond that thing.","zh":"Do not stop with something 指不只限於某事，而是延伸到其他方面。"},{"en":"The effects of poor sleep do not stop with tiredness; they can affect mood and learning.","zh":"睡眠不足的影響不止於疲倦；它可以影響情緒和學習。"},{"en":"Noise effects do not stop with hearing because stress and blood pressure may also change.","zh":"噪音影響不止於聽力，因為壓力和血壓也可能改變。"},{"en":"This phrase expands the reader’s attention beyond the first obvious effect.","zh":"這個片語把讀者注意力擴展到第一個明顯影響之外。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":12},{"front":"nonauditory effects","meaning":"非聽覺影響","examples":[{"en":"Nonauditory effects of noise include changes in blood pressure and sleep.","zh":"噪音的非聽覺影響包括血壓和睡眠變化。"},{"en":"Nonauditory effects are effects that do not directly involve hearing.","zh":"Nonauditory effects 是不直接涉及聽力的影響。"},{"en":"Noise may cause nonauditory effects such as stress, poor sleep, and faster heart rate.","zh":"噪音可能造成壓力、睡眠差和心率加快等非聽覺影響。"},{"en":"These effects matter because noise can harm the whole body, not only the ears.","zh":"這些影響很重要，因為噪音可以傷害整個身體，而不只是耳朵。"},{"en":"This phrase separates hearing effects from wider health effects.","zh":"這個片語把聽覺影響與更廣泛健康影響分開。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":12},{"front":"noise exposure","meaning":"噪音暴露","examples":[{"en":"Noise exposure can have effects beyond hearing loss.","zh":"噪音暴露可以有聽力喪失以外的影響。"},{"en":"Noise exposure means contact with noise over a period of time.","zh":"Noise exposure 指在一段時間內接觸噪音。"},{"en":"A child living near train tracks may have daily noise exposure.","zh":"住在鐵路旁的孩子可能每天都有噪音暴露。"},{"en":"Long noise exposure can affect sleep, stress, hearing, and learning.","zh":"長期噪音暴露可以影響睡眠、壓力、聽力和學習。"},{"en":"This phrase is used to measure or describe contact with sound.","zh":"這個片語用來量度或描述與聲音的接觸。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":12},{"front":"be measured","meaning":"被量度","examples":[{"en":"Some nonauditory effects of noise can be measured.","zh":"一些噪音的非聽覺影響可以被量度。"},{"en":"To be measured means to be checked or recorded using numbers or instruments.","zh":"To be measured 指用數字或儀器檢查或記錄。"},{"en":"Blood pressure can be measured with a machine at a clinic.","zh":"血壓可以在診所用機器量度。"},{"en":"If an effect can be measured, researchers can compare before and after conditions.","zh":"如果某影響可以被量度，研究人員便可以比較前後情況。"},{"en":"This phrase shows that evidence can be made more objective.","zh":"這個片語顯示證據可以變得更客觀。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":12},{"front":"elevated blood pressure","meaning":"血壓升高","examples":[{"en":"Noise exposure can cause elevated blood pressure.","zh":"噪音暴露可以造成血壓升高。"},{"en":"Elevated blood pressure means blood pressure is higher than normal.","zh":"Elevated blood pressure 指血壓高於正常水平。"},{"en":"Stress, poor sleep, and loud noise can contribute to elevated blood pressure.","zh":"壓力、睡眠不足和巨大噪音可以促成血壓升高。"},{"en":"If blood pressure stays elevated, health risks may increase over time.","zh":"如果血壓持續升高，健康風險可能隨時間增加。"},{"en":"This phrase describes a measurable body response.","zh":"這個片語描述可量度的身體反應。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":12},{"front":"loss of sleep","meaning":"睡眠不足","examples":[{"en":"Noise exposure may lead to loss of sleep.","zh":"噪音暴露可能導致睡眠不足。"},{"en":"Loss of sleep means not getting enough sleep or losing sleep quality.","zh":"Loss of sleep 指睡眠時間不足或睡眠質素下降。"},{"en":"A baby crying all night can cause loss of sleep for parents.","zh":"嬰兒整晚哭鬧可以令父母睡眠不足。"},{"en":"Loss of sleep can reduce concentration, patience, and memory the next day.","zh":"睡眠不足可以在翌日降低專注力、耐性和記憶力。"},{"en":"This phrase describes both shorter sleep and disturbed sleep.","zh":"這個片語既描述睡得少，也描述睡得不安穩。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":12},{"front":"increased heart rate","meaning":"心率上升","examples":[{"en":"Noise can cause an increased heart rate.","zh":"噪音可以造成心率上升。"},{"en":"Increased heart rate means the heart beats faster than usual.","zh":"Increased heart rate 指心臟跳得比平時快。"},{"en":"A sudden alarm can cause an increased heart rate because the body feels stress.","zh":"突然警報可以造成心率上升，因為身體感到壓力。"},{"en":"Repeated noise may keep the body alert even when a person wants to rest.","zh":"反覆噪音可能令身體保持警覺，即使人想休息。"},{"en":"This phrase describes a physical stress response.","zh":"這個片語描述身體壓力反應。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":12},{"front":"cardiovascular constriction","meaning":"心血管收縮","examples":[{"en":"Noise exposure may cause cardiovascular constriction.","zh":"噪音暴露可能造成心血管收縮。"},{"en":"Cardiovascular constriction means narrowing or tightening in the heart and blood vessel system.","zh":"Cardiovascular constriction 指心臟和血管系統中的收窄或繃緊。"},{"en":"Stress can cause blood vessels to tighten temporarily.","zh":"壓力可以令血管暫時收縮。"},{"en":"If noise repeatedly causes cardiovascular constriction, it may affect long-term health.","zh":"如果噪音反覆造成心血管收縮，可能影響長期健康。"},{"en":"This phrase is technical and relates noise to the circulatory system.","zh":"這個片語較技術性，把噪音與循環系統連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":13},{"front":"labored breathing","meaning":"呼吸困難；費力呼吸","examples":[{"en":"Noise can be associated with labored breathing.","zh":"噪音可能與呼吸困難相關。"},{"en":"Labored breathing means breathing that feels difficult, heavy, or effortful.","zh":"Labored breathing 指感覺困難、沉重或費力的呼吸。"},{"en":"A person with asthma may experience labored breathing after climbing stairs.","zh":"哮喘患者爬樓梯後可能出現呼吸困難。"},{"en":"Stress from loud noise may make breathing feel less calm and natural.","zh":"巨大噪音造成的壓力可能令呼吸感覺較不平靜自然。"},{"en":"This phrase describes breathing difficulty, not ordinary deep breathing.","zh":"這個片語描述呼吸困難，而不是普通深呼吸。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":13},{"front":"changes in brain chemistry","meaning":"腦部化學變化","examples":[{"en":"Noise exposure may cause changes in brain chemistry.","zh":"噪音暴露可能造成腦部化學變化。"},{"en":"Changes in brain chemistry are changes in the chemicals that help the brain send signals.","zh":"Changes in brain chemistry 是幫助大腦傳遞訊號的化學物出現變化。"},{"en":"Stress and lack of sleep can affect brain chemistry and mood.","zh":"壓力和睡眠不足可以影響腦部化學和情緒。"},{"en":"If noise changes brain chemistry, it may influence attention, stress, or emotions.","zh":"如果噪音改變腦部化學，可能影響注意力、壓力或情緒。"},{"en":"This phrase links environmental noise with internal body processes.","zh":"這個片語把環境噪音與身體內部過程連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":13},{"front":"be noted as early as","meaning":"早於……已被注意到","examples":[{"en":"The nonauditory effects of noise were noted as early as 1930.","zh":"噪音的非聽覺影響早於1930年已被注意到。"},{"en":"To be noted as early as a time means people had already observed it by that early date.","zh":"To be noted as early as a time 指人們早在那個日期已經觀察到某事。"},{"en":"The effects of poor housing on health were noted as early as the nineteenth century.","zh":"住房差對健康的影響早於十九世紀已被注意到。"},{"en":"If a problem was noted as early as 1930, it has been known for a long time.","zh":"如果某問題早於1930年已被注意到，它已被認識很久。"},{"en":"This phrase emphasises early recognition.","zh":"這個片語強調早期認識。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":13},{"front":"exposure to noise","meaning":"暴露於噪音","examples":[{"en":"Exposure to noise caused stomach contractions in healthy people.","zh":"暴露於噪音令健康的人出現胃部收縮。"},{"en":"Exposure to noise means experiencing sound, especially unwanted or loud sound.","zh":"Exposure to noise 指經歷聲音，尤其是不想要或巨大的聲音。"},{"en":"Exposure to noise at night can disturb sleep even if people do not fully wake up.","zh":"夜間暴露於噪音可以干擾睡眠，即使人沒有完全醒來。"},{"en":"Repeated exposure to noise can create stress responses in the body.","zh":"反覆暴露於噪音可以在身體中造成壓力反應。"},{"en":"This phrase treats noise as something the body receives and reacts to.","zh":"這個片語把噪音視為身體接收並反應的東西。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":13},{"front":"stomach contractions","meaning":"胃部收縮","examples":[{"en":"A 1930 study showed that noise caused stomach contractions.","zh":"一項1930年的研究顯示噪音造成胃部收縮。"},{"en":"Stomach contractions are tightening movements of the stomach muscles.","zh":"Stomach contractions 是胃部肌肉收緊的動作。"},{"en":"Stress can sometimes cause stomach contractions or discomfort.","zh":"壓力有時可以造成胃部收縮或不適。"},{"en":"If noise causes stomach contractions, its effects clearly go beyond hearing.","zh":"如果噪音造成胃部收縮，其影響明顯不止於聽力。"},{"en":"This phrase describes a physical reaction inside the digestive system.","zh":"這個片語描述消化系統內的身體反應。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":13},{"front":"healthy human beings","meaning":"健康的人類","examples":[{"en":"Noise caused stomach contractions in healthy human beings.","zh":"噪音令健康的人類出現胃部收縮。"},{"en":"Healthy human beings are people without obvious illness in the context being studied.","zh":"Healthy human beings 是在研究語境中沒有明顯疾病的人。"},{"en":"Researchers sometimes test healthy human beings to see how normal bodies react.","zh":"研究人員有時測試健康的人，以了解正常身體如何反應。"},{"en":"If noise affects healthy people, vulnerable groups may need even more protection.","zh":"如果噪音影響健康的人，脆弱群體可能更需要保護。"},{"en":"This phrase identifies ordinary healthy participants.","zh":"這個片語指出普通健康參與者。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":13},{"front":"pioneering study","meaning":"開創性研究","examples":[{"en":"The 1930 study was a pioneering study of noise’s nonauditory effects.","zh":"1930年的研究是噪音非聽覺影響的開創性研究。"},{"en":"A pioneering study is an early study that opens a new area of research.","zh":"Pioneering study 是開拓新研究領域的早期研究。"},{"en":"A pioneering study on school sleep may inspire later research on timetables.","zh":"關於學校睡眠的開創性研究可能啟發後來對時間表的研究。"},{"en":"Pioneering studies may be small, but they can change what scientists investigate.","zh":"開創性研究可能規模較小，但可以改變科學家調查的內容。"},{"en":"This phrase praises research for being early and path-breaking.","zh":"這個片語讚揚研究早期且具開路作用。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":13},{"front":"contradictory and controversial","meaning":"互相矛盾且具爭議","examples":[{"en":"Reports on nonauditory noise effects have been contradictory and controversial.","zh":"關於噪音非聽覺影響的報告互相矛盾且具爭議。"},{"en":"Contradictory and controversial means reports disagree with each other and are debated.","zh":"Contradictory and controversial 指報告彼此不一致，而且受到爭論。"},{"en":"Studies about a new diet may be contradictory and controversial if results differ.","zh":"如果結果不同，關於新飲食法的研究可能互相矛盾且具爭議。"},{"en":"When evidence is contradictory, experts need better methods and more data.","zh":"當證據互相矛盾，專家需要更好方法和更多數據。"},{"en":"This phrase warns readers that the issue is not fully settled.","zh":"這個片語提醒讀者，該議題尚未完全定論。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":13},{"front":"in some areas","meaning":"在某些方面","examples":[{"en":"The evidence has been controversial in some areas.","zh":"證據在某些方面一直具爭議。"},{"en":"In some areas means in certain parts of a topic, field, or place.","zh":"In some areas 指在某個主題、領域或地方的某些部分。"},{"en":"A school may improve overall but still struggle in some areas, such as writing.","zh":"學校整體可能改善，但在寫作等某些方面仍然吃力。"},{"en":"Noise research may be clear in hearing loss but controversial in some other health areas.","zh":"噪音研究在聽力喪失方面可能清楚，但在其他健康方面可能具爭議。"},{"en":"This phrase limits a statement so it does not sound too broad.","zh":"這個片語限制說法，使其不會過於廣泛。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":13},{"front":"be shown to affect","meaning":"已被證明會影響……","examples":[{"en":"Noise has been shown to affect learning ability.","zh":"噪音已被證明會影響學習能力。"},{"en":"To be shown to affect something means evidence has demonstrated an influence on it.","zh":"To be shown to affect something 指證據已顯示對某事有影響。"},{"en":"Sleep has been shown to affect memory and attention.","zh":"睡眠已被證明會影響記憶和注意力。"},{"en":"If noise is shown to affect learning, schools should reduce classroom noise.","zh":"如果噪音已被證明會影響學習，學校應減少課室噪音。"},{"en":"This phrase introduces a finding supported by research.","zh":"這個片語引出有研究支持的發現。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":13},{"front":"learning ability","meaning":"學習能力","examples":[{"en":"Noise can affect children’s learning ability.","zh":"噪音可以影響兒童學習能力。"},{"en":"Learning ability is the ability to understand, remember, and use new information.","zh":"Learning ability 是理解、記住和使用新資訊的能力。"},{"en":"A child’s learning ability can suffer if the classroom is too noisy.","zh":"如果課室太嘈，孩子的學習能力可能受損。"},{"en":"Good sleep, quiet space, and clear teaching can support learning ability.","zh":"良好睡眠、安靜空間和清晰教學可以支援學習能力。"},{"en":"This phrase describes capacity to learn, not just exam results.","zh":"這個片語描述學習能力，而不只是考試成績。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":14},{"front":"collaborate on a study","meaning":"合作進行一項研究","examples":[{"en":"Bronzaft collaborated on a study of children near a train track.","zh":"Bronzaft合作進行一項關於鐵路附近兒童的研究。"},{"en":"To collaborate on a study means to work with others to carry out research.","zh":"To collaborate on a study 指與他人合作進行研究。"},{"en":"Teachers and doctors may collaborate on a study about children’s sleep.","zh":"老師和醫生可能合作進行一項關於兒童睡眠的研究。"},{"en":"Collaboration can bring together different skills and better data.","zh":"合作可以結合不同技能和更好數據。"},{"en":"This phrase describes joint research work.","zh":"這個片語描述共同研究工作。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":14},{"front":"elevated train track","meaning":"高架鐵路軌道","examples":[{"en":"The school was located near an elevated train track.","zh":"這所學校位於高架鐵路軌道附近。"},{"en":"An elevated train track is a railway track raised above ground level.","zh":"Elevated train track 是高於地面的鐵路軌道。"},{"en":"Classrooms near an elevated train track may hear trains passing overhead.","zh":"位於高架鐵路軌道附近的課室，可能聽到列車在上方經過。"},{"en":"Elevated tracks can create noise because sound travels from the raised structure.","zh":"高架路軌可能造成噪音，因為聲音會從升高結構傳出。"},{"en":"This phrase describes both the railway type and its position.","zh":"這個片語同時描述鐵路類型和位置。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":14},{"front":"affect children’s reading ability","meaning":"影響兒童閱讀能力","examples":[{"en":"Noise exposure can affect children’s reading ability.","zh":"噪音暴露可以影響兒童閱讀能力。"},{"en":"To affect children’s reading ability means to change how well children read and understand text.","zh":"To affect children’s reading ability 指改變兒童閱讀和理解文本的能力。"},{"en":"Loud train noise may interrupt lessons and affect children’s reading ability.","zh":"巨大火車噪音可能打斷課堂並影響兒童閱讀能力。"},{"en":"If students miss words during instruction, reading progress may slow.","zh":"如果學生在指導中聽漏字詞，閱讀進度可能放慢。"},{"en":"This phrase links environmental noise with school learning.","zh":"這個片語把環境噪音與學校學習連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":14},{"front":"classrooms facing","meaning":"面向……的課室","examples":[{"en":"Half of the students were in classrooms facing the train track.","zh":"一半學生在面向鐵路軌道的課室。"},{"en":"Classrooms facing something are rooms whose windows or front side look toward it.","zh":"Classrooms facing something 是窗戶或正面朝向某物的課室。"},{"en":"Students in classrooms facing a busy road may hear more traffic.","zh":"在面向繁忙道路的課室中，學生可能聽到更多交通聲。"},{"en":"Where a classroom faces can affect light, view, and noise level.","zh":"課室面向哪裡可以影響光線、景觀和噪音水平。"},{"en":"This phrase describes room position relative to an outside feature.","zh":"這個片語描述課室相對外部事物的位置。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":14},{"front":"quieter back section","meaning":"較安靜的後方區域","examples":[{"en":"The other students were in the school’s quieter back section.","zh":"其他學生位於學校較安靜的後方區域。"},{"en":"A quieter back section is a part at the rear of a building where noise is lower.","zh":"Quieter back section 是建築後方噪音較低的部分。"},{"en":"A library may place study desks in the quieter back section away from the entrance.","zh":"圖書館可能把自修桌放在遠離入口的較安靜後方區域。"},{"en":"Students in quieter areas may concentrate better during reading lessons.","zh":"位於較安靜區域的學生可能在閱讀課中更能集中。"},{"en":"This phrase contrasts a calmer area with a noisier front or side.","zh":"這個片語把較平靜區域與較嘈雜的前方或側邊作對比。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":14},{"front":"findings","meaning":"研究結果","examples":[{"en":"The findings showed that quieter classrooms helped reading performance.","zh":"研究結果顯示較安靜課室有助閱讀表現。"},{"en":"Findings are results or conclusions from a study or investigation.","zh":"Findings 是研究或調查所得的結果或結論。"},{"en":"A school survey’s findings may show that students need more quiet study space.","zh":"學校問卷的研究結果可能顯示學生需要更多安靜自修空間。"},{"en":"Research findings can influence policy when they are clear and repeated.","zh":"當研究結果清楚且反覆出現，它們可以影響政策。"},{"en":"This word refers to what the evidence revealed.","zh":"這個詞指證據揭示了甚麼。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":14},{"front":"perform better on","meaning":"在……表現較好","examples":[{"en":"Students on the quieter side performed better on reading tests.","zh":"較安靜一邊的學生在閱讀測驗中表現較好。"},{"en":"To perform better on something means to achieve stronger results in that task or test.","zh":"To perform better on something 指在某項任務或測驗中取得較好成績。"},{"en":"Students often perform better on exams when they sleep well.","zh":"學生睡得好時，往往在考試中表現較好。"},{"en":"Quieter classrooms may help children perform better on reading tasks.","zh":"較安靜課室可能幫助兒童在閱讀任務中表現較好。"},{"en":"This phrase compares achievement in a specific activity.","zh":"這個片語比較特定活動中的成果。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":14},{"front":"reading tests","meaning":"閱讀測驗","examples":[{"en":"Students in quieter classrooms did better on reading tests.","zh":"較安靜課室中的學生在閱讀測驗中表現較好。"},{"en":"Reading tests measure how well students understand written words and passages.","zh":"Reading tests 量度學生理解文字和文章的能力。"},{"en":"A reading test may ask students to find details, infer meaning, and summarise ideas.","zh":"閱讀測驗可能要求學生找細節、推斷意思和總結想法。"},{"en":"Noise can affect reading tests if students cannot concentrate.","zh":"如果學生無法集中，噪音可以影響閱讀測驗。"},{"en":"This phrase refers to assessments of reading ability.","zh":"這個片語指閱讀能力評估。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":14},{"front":"by sixth grade","meaning":"到六年級時","examples":[{"en":"By sixth grade, students in quieter classrooms were ahead.","zh":"到六年級時，較安靜課室中的學生已領先。"},{"en":"By sixth grade means before or when students reach sixth grade.","zh":"By sixth grade 指在學生到六年級之前或到六年級時。"},{"en":"By sixth grade, many children can read longer books independently.","zh":"到六年級時，許多孩子能獨立閱讀較長書籍。"},{"en":"If noise affects learning for years, differences may become clear by sixth grade.","zh":"如果噪音多年影響學習，到六年級時差異可能變得清楚。"},{"en":"This phrase marks a school-year point for comparison.","zh":"這個片語標示用來比較的學年時間點。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":14},{"front":"a full grade point ahead of","meaning":"領先整整一個年級水平","examples":[{"en":"Students on the quieter side were a full grade point ahead of the others.","zh":"較安靜一邊的學生領先其他學生整整一個年級水平。"},{"en":"A full grade point ahead of means one complete school level more advanced than another group.","zh":"A full grade point ahead of 指比另一組完整高出一個學校年級水平。"},{"en":"A child reading at a full grade point ahead may understand books meant for older students.","zh":"閱讀能力領先整整一個年級水平的孩子，可能理解較高年級學生的書。"},{"en":"If one group is a full grade point ahead, the learning gap is serious.","zh":"如果一組學生領先整整一個年級水平，學習差距便很嚴重。"},{"en":"This phrase describes a clear educational advantage.","zh":"這個片語描述清晰教育優勢。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":14},{"front":"persuade someone to","meaning":"說服某人去……","examples":[{"en":"Bronzaft persuaded the school board to install acoustical tile.","zh":"Bronzaft說服校董會安裝吸音天花板。"},{"en":"To persuade someone to do something means to convince them to take an action.","zh":"To persuade someone to do something 指說服某人採取某行動。"},{"en":"Students may persuade a teacher to give more revision time before an exam.","zh":"學生可能說服老師在考試前給更多溫習時間。"},{"en":"Strong evidence can persuade officials to change a policy.","zh":"強有力證據可以說服官員改變政策。"},{"en":"This phrase shows influence through reasons or argument.","zh":"這個片語顯示透過理由或論證影響他人。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":15},{"front":"school board","meaning":"校董會；教育委員會","examples":[{"en":"The school board was persuaded to install sound-reducing material.","zh":"校董會被說服安裝減音材料。"},{"en":"A school board is a group responsible for major decisions about a school or school district.","zh":"School board 是負責學校或學區重大決定的小組。"},{"en":"A school board may decide budgets, buildings, policies, and student services.","zh":"校董會可能決定預算、建築、政策和學生服務。"},{"en":"If research shows noise affects learning, the school board may approve changes.","zh":"如果研究顯示噪音影響學習，校董會可能批准改變。"},{"en":"This phrase refers to an educational decision-making body.","zh":"這個片語指教育決策機構。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":15},{"front":"acoustical tile","meaning":"吸音天花板；吸音磚","examples":[{"en":"Acoustical tile was installed in classrooms near the tracks.","zh":"靠近路軌的課室安裝了吸音天花板。"},{"en":"Acoustical tile is material designed to absorb sound and reduce noise.","zh":"Acoustical tile 是設計來吸收聲音和減少噪音的材料。"},{"en":"Schools may use acoustical tile on ceilings to make classrooms quieter.","zh":"學校可能在天花板使用吸音磚，令課室較安靜。"},{"en":"By absorbing echoes and outside noise, acoustical tile can help students hear teachers better.","zh":"透過吸收回聲和外來噪音，吸音天花板可以幫助學生更好聽到老師。"},{"en":"This phrase names a building material used for sound control.","zh":"這個片語命名用於聲音控制的建築材料。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":15},{"front":"be installed in","meaning":"被安裝在……","examples":[{"en":"Acoustical tile was installed in the classrooms.","zh":"吸音天花板被安裝在課室中。"},{"en":"To be installed in a place means to be put there for use.","zh":"To be installed in a place 指被放置在某地方以供使用。"},{"en":"Air purifiers may be installed in classrooms with poor ventilation.","zh":"空氣淨化機可能被安裝在通風差的課室中。"},{"en":"If sound-reducing materials are installed in noisy rooms, learning conditions may improve.","zh":"如果減音材料被安裝在嘈雜房間中，學習條件可能改善。"},{"en":"This phrase describes adding equipment or material to a place.","zh":"這個片語描述把設備或材料加入某地方。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":15},{"front":"adjacent to","meaning":"鄰近……","examples":[{"en":"The classrooms adjacent to the tracks received acoustical tile.","zh":"鄰近路軌的課室安裝了吸音天花板。"},{"en":"Adjacent to means next to or very near something.","zh":"Adjacent to 指在某物旁邊或非常接近。"},{"en":"A classroom adjacent to the playground may be noisy during recess.","zh":"鄰近操場的課室在小息時可能很嘈。"},{"en":"Homes adjacent to a highway may need better sound insulation.","zh":"鄰近高速公路的住宅可能需要更好隔音。"},{"en":"This phrase describes close physical location.","zh":"這個片語描述實體位置接近。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":15},{"front":"Transit Authority","meaning":"運輸管理局","examples":[{"en":"The Transit Authority treated the tracks near the school.","zh":"運輸管理局處理了學校附近的路軌。"},{"en":"A Transit Authority is an organisation responsible for public transport systems.","zh":"Transit Authority 是負責公共交通系統的組織。"},{"en":"A Transit Authority may manage trains, buses, stations, and tracks.","zh":"運輸管理局可能管理火車、巴士、車站和路軌。"},{"en":"If train noise affects schools, the Transit Authority may be asked to reduce it.","zh":"如果火車噪音影響學校，運輸管理局可能被要求減少噪音。"},{"en":"This phrase names a transport management body.","zh":"這個片語命名交通管理機構。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":15},{"front":"treat the tracks","meaning":"處理路軌","examples":[{"en":"The Transit Authority treated the tracks to make them less noisy.","zh":"運輸管理局處理路軌，使它們較不嘈吵。"},{"en":"To treat the tracks means to modify or repair railway tracks to improve a problem.","zh":"To treat the tracks 指改裝或維修鐵路軌道，以改善問題。"},{"en":"Engineers may treat the tracks by smoothing surfaces or adding noise-reducing materials.","zh":"工程師可能透過磨平表面或加入減音材料來處理路軌。"},{"en":"Treating tracks can reduce sound before it reaches nearby classrooms.","zh":"處理路軌可以在聲音到達附近課室前減少它。"},{"en":"This phrase describes a practical engineering intervention.","zh":"這個片語描述實際工程介入。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":15},{"front":"make them less noisy","meaning":"令它們較不嘈吵","examples":[{"en":"The tracks were treated to make them less noisy.","zh":"路軌被處理，以令它們較不嘈吵。"},{"en":"To make something less noisy means to reduce the sound it produces.","zh":"To make something less noisy 指減少某物產生的聲音。"},{"en":"A school can make a hallway less noisy by adding soft floor materials.","zh":"學校可以加入柔軟地面材料，令走廊較不嘈吵。"},{"en":"Quieter tracks can help students concentrate during lessons.","zh":"較安靜的路軌可以幫助學生在課堂中集中。"},{"en":"This phrase describes reducing noise, not removing all sound.","zh":"這個片語描述減少噪音，而不是移除所有聲音。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":15},{"front":"follow-up study","meaning":"跟進研究","examples":[{"en":"A follow-up study found that reading scores improved.","zh":"跟進研究發現閱讀分數有所改善。"},{"en":"A follow-up study is later research done to check what happened after an earlier study or intervention.","zh":"Follow-up study 是在早前研究或介入後進行、用來檢查後續情況的研究。"},{"en":"A school may run a follow-up study after changing its timetable.","zh":"學校改變時間表後，可能進行跟進研究。"},{"en":"Follow-up studies help show whether a solution has lasting effects.","zh":"跟進研究幫助顯示解決方案是否有持久效果。"},{"en":"This phrase describes research that comes after an initial investigation.","zh":"這個片語描述初步調查之後的研究。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":15},{"front":"Journal of Environmental Psychology","meaning":"《環境心理學期刊》","examples":[{"en":"The follow-up study was published in the Journal of Environmental Psychology.","zh":"跟進研究發表於《環境心理學期刊》。"},{"en":"The Journal of Environmental Psychology is an academic journal about how environments affect people’s behaviour and wellbeing.","zh":"《環境心理學期刊》是關於環境如何影響人的行為和福祉的學術期刊。"},{"en":"A study on noise and learning would fit this kind of journal because classrooms are environments.","zh":"關於噪音和學習的研究適合這類期刊，因為課室是環境。"},{"en":"Publishing in a journal allows other researchers to read and evaluate the study.","zh":"在期刊發表讓其他研究人員閱讀和評估研究。"},{"en":"This phrase names a source for research on environment and psychology.","zh":"這個片語命名關於環境和心理學研究的來源。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":15},{"front":"reading scores","meaning":"閱讀分數","examples":[{"en":"Children’s reading scores improved after noise-reduction measures.","zh":"減噪措施後，兒童閱讀分數有所改善。"},{"en":"Reading scores are marks or results that show how well students perform in reading.","zh":"Reading scores 是顯示學生閱讀表現的分數或結果。"},{"en":"A teacher may compare reading scores before and after a new programme.","zh":"老師可能比較新計劃前後的閱讀分數。"},{"en":"If reading scores rise after classrooms become quieter, noise may have affected learning.","zh":"如果課室變安靜後閱讀分數上升，噪音可能曾影響學習。"},{"en":"This phrase gives a measurable result for reading ability.","zh":"這個片語提供閱讀能力的可量度結果。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":15},{"front":"improve after","meaning":"在……之後改善","examples":[{"en":"Reading scores improved after the interventions.","zh":"閱讀分數在介入措施之後改善。"},{"en":"To improve after something means to become better following that event or action.","zh":"To improve after something 指在某事件或行動之後變得更好。"},{"en":"A student’s spelling may improve after regular practice.","zh":"學生的拼字可能在定期練習後改善。"},{"en":"If health improves after noise is reduced, the intervention may be effective.","zh":"如果減少噪音後健康改善，介入措施可能有效。"},{"en":"This phrase connects a positive change with what came before it.","zh":"這個片語把正面變化與之前發生的事情連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":16},{"front":"interventions","meaning":"介入措施","examples":[{"en":"The interventions included classroom materials and quieter tracks.","zh":"介入措施包括課室材料和較安靜的路軌。"},{"en":"Interventions are actions taken to improve a problem.","zh":"Interventions 是為改善問題而採取的行動。"},{"en":"A school intervention may include tutoring, counselling, or a quieter study room.","zh":"學校介入措施可能包括補習、輔導或較安靜自修室。"},{"en":"If interventions are well designed, they can reduce harm and improve outcomes.","zh":"如果介入措施設計良好，它們可以減少傷害並改善結果。"},{"en":"This word describes planned actions, not random changes.","zh":"這個詞描述有計劃的行動，而不是隨機改變。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":16},{"front":"be put in place","meaning":"被實施；被落實","examples":[{"en":"Children’s scores improved after the interventions were put in place.","zh":"介入措施被落實後，兒童分數有所改善。"},{"en":"To be put in place means to be introduced, set up, or made ready to work.","zh":"To be put in place 指被引入、設立或準備好運作。"},{"en":"New safety rules were put in place after several accidents.","zh":"幾次意外後，新安全規則被實施。"},{"en":"Once sound-reducing materials are put in place, classrooms may become quieter.","zh":"一旦減音材料被落實，課室可能變得較安靜。"},{"en":"This phrase describes implementation of a plan or measure.","zh":"這個片語描述計劃或措施的實施。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":16},{"front":"Fighting for Quiet","meaning":"爭取寧靜","examples":[{"en":"The section Fighting for Quiet discusses efforts to reduce noise pollution.","zh":"“爭取寧靜”這一部分討論減少噪音污染的努力。"},{"en":"Fighting for Quiet means actively trying to protect or create quieter environments.","zh":"Fighting for Quiet 指積極嘗試保護或創造較安靜環境。"},{"en":"Residents may be fighting for quiet when they ask officials to reduce traffic noise.","zh":"居民要求官員減少交通噪音時，就是在爭取寧靜。"},{"en":"Fighting for quiet can involve laws, research, city planning, and public pressure.","zh":"爭取寧靜可以涉及法律、研究、城市規劃和公眾壓力。"},{"en":"This title presents silence as something people must work to defend.","zh":"這個標題把寧靜呈現為人們必須努力捍衛的東西。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":16},{"front":"anti-noise activists","meaning":"反噪音倡議者","examples":[{"en":"Anti-noise activists argue for stronger policies against noise.","zh":"反噪音倡議者主張制定更強政策對抗噪音。"},{"en":"Anti-noise activists are people who campaign to reduce harmful or excessive noise.","zh":"Anti-noise activists 是推動減少有害或過量噪音的人。"},{"en":"Anti-noise activists may collect complaints from residents near airports or highways.","zh":"反噪音倡議者可能收集機場或高速公路附近居民的投訴。"},{"en":"Their campaigns can push governments to measure noise and set limits.","zh":"他們的倡議可以推動政府量度噪音並設定限制。"},{"en":"This phrase describes social campaigners focused on noise pollution.","zh":"這個片語描述專注於噪音污染的社會倡議者。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":16},{"front":"more advanced than","meaning":"比……更先進","examples":[{"en":"Europe is more advanced than the United States in combating noise.","zh":"歐洲在對抗噪音方面比美國更先進。"},{"en":"More advanced than means further developed or more progressive than another person, place, or system.","zh":"More advanced than 指比另一個人、地方或制度發展得更前或更進步。"},{"en":"One hospital may be more advanced than another in using digital patient records.","zh":"一間醫院在使用數碼病歷方面可能比另一間更先進。"},{"en":"A city with noise maps and strict planning rules may be more advanced in noise control.","zh":"有噪音地圖和嚴格規劃規則的城市，在噪音控制方面可能更先進。"},{"en":"This phrase compares levels of development.","zh":"這個片語比較發展水平。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":16},{"front":"in terms of","meaning":"在……方面","examples":[{"en":"Some regions are more advanced in terms of combating noise.","zh":"一些地區在對抗噪音方面更先進。"},{"en":"In terms of means when considering a particular aspect or standard.","zh":"In terms of 指從某個特定方面或標準來考慮。"},{"en":"In terms of cost, the bus is cheaper than a taxi.","zh":"在成本方面，巴士比的士便宜。"},{"en":"In terms of health, reducing noise may be as important as reducing air pollution.","zh":"在健康方面，減少噪音可能與減少空氣污染一樣重要。"},{"en":"This phrase narrows the comparison to one area.","zh":"這個片語把比較收窄到某一方面。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":16},{"front":"combat noise","meaning":"對抗噪音","examples":[{"en":"Some countries have moved quickly to combat noise.","zh":"一些國家已快速行動來對抗噪音。"},{"en":"To combat noise means to take action to reduce or control noise pollution.","zh":"To combat noise 指採取行動減少或控制噪音污染。"},{"en":"Schools can combat noise by adding soft materials and closing windows during lessons.","zh":"學校可以透過加入柔軟材料和上課時關窗來對抗噪音。"},{"en":"Cities combat noise through planning, road design, and limits on loud activities.","zh":"城市透過規劃、道路設計和限制嘈雜活動來對抗噪音。"},{"en":"This phrase treats noise as a problem that must be fought.","zh":"這個片語把噪音視為必須對抗的問題。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":16},{"front":"population pressure","meaning":"人口壓力","examples":[{"en":"Population pressure has pushed Europe to act on noise.","zh":"人口壓力推動歐洲處理噪音問題。"},{"en":"Population pressure means stress created when many people live close together and compete for space.","zh":"Population pressure 指許多人密集居住並競爭空間時造成的壓力。"},{"en":"Population pressure can increase traffic, housing density, and public noise.","zh":"人口壓力可以增加交通、住宅密度和公共噪音。"},{"en":"When population pressure rises, governments may need stronger environmental rules.","zh":"當人口壓力上升，政府可能需要更強環境規則。"},{"en":"This phrase links crowded living with policy action.","zh":"這個片語把擁擠生活與政策行動連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":16},{"front":"prompt someone to","meaning":"促使某人去……","examples":[{"en":"Population pressure has prompted Europe to move more quickly.","zh":"人口壓力促使歐洲更快行動。"},{"en":"To prompt someone to do something means to cause or encourage them to act.","zh":"To prompt someone to do something 指促使或鼓勵某人採取行動。"},{"en":"Complaints from parents may prompt a school to improve classroom soundproofing.","zh":"家長投訴可能促使學校改善課室隔音。"},{"en":"Health evidence can prompt governments to create stronger noise policies.","zh":"健康證據可以促使政府制定更強噪音政策。"},{"en":"This phrase connects a cause with a response.","zh":"這個片語把原因與回應連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":16},{"front":"move more quickly on","meaning":"在……議題上行動更快","examples":[{"en":"Europe has moved more quickly on the noise issue.","zh":"歐洲在噪音問題上行動更快。"},{"en":"To move more quickly on an issue means to act faster to deal with it.","zh":"To move more quickly on an issue 指更快採取行動處理某議題。"},{"en":"A school may move more quickly on bullying after parents provide clear evidence.","zh":"家長提供清晰證據後，學校可能在欺凌議題上行動更快。"},{"en":"Governments move more quickly when public pressure and research both increase.","zh":"當公眾壓力和研究都增加，政府行動會更快。"},{"en":"This phrase describes faster policy or practical action.","zh":"這個片語描述更快的政策或實際行動。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":16},{"front":"the noise issue","meaning":"噪音問題","examples":[{"en":"Governments need to act on the noise issue.","zh":"政府需要處理噪音問題。"},{"en":"The noise issue means the public problem of excessive or harmful noise.","zh":"The noise issue 指過量或有害噪音這個公共問題。"},{"en":"The noise issue can involve traffic, airports, construction, schools, and workplaces.","zh":"噪音問題可以涉及交通、機場、建築工程、學校和工作場所。"},{"en":"If the noise issue is ignored, health and learning problems may continue.","zh":"如果噪音問題被忽視，健康和學習問題可能持續。"},{"en":"This phrase frames noise as a social and policy problem.","zh":"這個片語把噪音視為社會和政策問題。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":17},{"front":"European Union","meaning":"歐盟","examples":[{"en":"The European Union has required large cities to create noise maps.","zh":"歐盟已要求大型城市製作噪音地圖。"},{"en":"The European Union is a political and economic union of European countries.","zh":"European Union 是由歐洲國家組成的政治和經濟聯盟。"},{"en":"The European Union can set rules that member countries must follow.","zh":"歐盟可以制定成員國必須遵守的規則。"},{"en":"If the European Union requires noise maps, cities must collect noise data more systematically.","zh":"如果歐盟要求噪音地圖，城市必須更有系統地收集噪音數據。"},{"en":"This phrase names a regional organisation with policy power.","zh":"這個片語命名具有政策權力的區域組織。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":17},{"front":"noise maps","meaning":"噪音地圖","examples":[{"en":"Large European cities are creating noise maps.","zh":"歐洲大型城市正在製作噪音地圖。"},{"en":"Noise maps are maps that show where noise levels are high or low in an area.","zh":"Noise maps 是顯示某地區噪音水平高低的地圖。"},{"en":"A city can use noise maps to find streets where residents suffer the most noise.","zh":"城市可以使用噪音地圖找出居民受噪音影響最嚴重的街道。"},{"en":"Noise maps help planners decide where barriers, quieter roads, or restrictions are needed.","zh":"噪音地圖幫助規劃者決定哪裡需要屏障、較安靜道路或限制。"},{"en":"This phrase describes a planning tool for noise control.","zh":"這個片語描述噪音控制的規劃工具。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":17},{"front":"determine noise pollution policies","meaning":"制定噪音污染政策","examples":[{"en":"Noise maps help leaders determine noise pollution policies.","zh":"噪音地圖幫助領導者制定噪音污染政策。"},{"en":"To determine noise pollution policies means to decide rules and actions for controlling noise.","zh":"To determine noise pollution policies 指決定控制噪音的規則和行動。"},{"en":"City officials may use data to determine noise pollution policies near schools.","zh":"城市官員可能使用數據來制定學校附近的噪音污染政策。"},{"en":"Better maps can lead to better decisions about road design and construction hours.","zh":"更好地圖可以帶來關於道路設計和施工時間的更好決定。"},{"en":"This phrase links information with government action.","zh":"這個片語把資訊與政府行動連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":17},{"front":"prepare its first noise maps","meaning":"製作首批噪音地圖","examples":[{"en":"Paris has already prepared its first noise maps.","zh":"巴黎已製作首批噪音地圖。"},{"en":"To prepare its first noise maps means to create the first official maps showing noise levels.","zh":"To prepare its first noise maps 指製作第一批顯示噪音水平的官方地圖。"},{"en":"A city may prepare its first noise maps before changing traffic rules.","zh":"城市可能在改變交通規則前製作首批噪音地圖。"},{"en":"Preparing noise maps helps officials see where the worst noise problems are.","zh":"製作噪音地圖幫助官員看見最嚴重的噪音問題在哪裡。"},{"en":"This phrase describes an early step in noise policy.","zh":"這個片語描述噪音政策的早期步驟。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":17},{"front":"map data","meaning":"地圖數據","examples":[{"en":"The map data will be fed into computer models.","zh":"地圖數據將被輸入到電腦模型。"},{"en":"Map data are information collected and displayed on maps.","zh":"Map data 是被收集並顯示在地圖上的資訊。"},{"en":"Map data may show noise levels, traffic flow, buildings, and population density.","zh":"地圖數據可能顯示噪音水平、交通流量、建築物和人口密度。"},{"en":"When map data are accurate, computer models can make better predictions.","zh":"當地圖數據準確，電腦模型可以作出更好預測。"},{"en":"This phrase refers to information used for planning and analysis.","zh":"這個片語指用於規劃和分析的資訊。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":17},{"front":"be fed into","meaning":"被輸入到……","examples":[{"en":"The noise data will be fed into computer models.","zh":"噪音數據將被輸入到電腦模型。"},{"en":"To be fed into a system means to be entered into it for processing or analysis.","zh":"To be fed into a system 指被輸入系統以作處理或分析。"},{"en":"Survey answers can be fed into a database after students complete them.","zh":"學生完成問卷後，答案可以被輸入到數據庫。"},{"en":"Once noise data are fed into a model, planners can test different designs.","zh":"一旦噪音數據被輸入模型，規劃者便可以測試不同設計。"},{"en":"This phrase describes putting information into a system.","zh":"這個片語描述把資訊放入系統。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":17},{"front":"computer models","meaning":"電腦模型","examples":[{"en":"Computer models will test the sound impact of new designs.","zh":"電腦模型將測試新設計的聲音影響。"},{"en":"Computer models are digital systems that simulate real-world situations using data.","zh":"Computer models 是使用數據模擬現實情況的數碼系統。"},{"en":"Weather forecasts use computer models to predict storms.","zh":"天氣預報使用電腦模型預測風暴。"},{"en":"City planners can use computer models to test noise before building new roads.","zh":"城市規劃者可以使用電腦模型，在建造新道路前測試噪音。"},{"en":"This phrase describes a tool for prediction and planning.","zh":"這個片語描述用於預測和規劃的工具。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":17},{"front":"sound impact","meaning":"聲音影響","examples":[{"en":"The models will test the sound impact of street designs.","zh":"模型將測試街道設計的聲音影響。"},{"en":"Sound impact means the effect that a design or activity has on noise levels and hearing conditions.","zh":"Sound impact 指某設計或活動對噪音水平和聽覺環境造成的影響。"},{"en":"A new flyover may have a strong sound impact on nearby homes.","zh":"新天橋可能對附近住宅有強烈聲音影響。"},{"en":"Testing sound impact before construction can prevent future complaints.","zh":"在施工前測試聲音影響，可以防止未來投訴。"},{"en":"This phrase connects design decisions with noise effects.","zh":"這個片語把設計決定與噪音效果連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":17},{"front":"street designs","meaning":"街道設計","examples":[{"en":"Computer models can test the sound impact of street designs.","zh":"電腦模型可以測試街道設計的聲音影響。"},{"en":"Street designs are plans for how roads, pavements, buildings, trees, and traffic are arranged.","zh":"Street designs 是道路、行人路、建築、樹木和交通如何安排的規劃。"},{"en":"A street design with trees and slower traffic may reduce noise.","zh":"有樹木和較慢車速的街道設計可能減少噪音。"},{"en":"Poor street designs can trap sound between tall buildings.","zh":"差劣街道設計可以把聲音困在高樓之間。"},{"en":"This phrase shows that urban design can affect noise levels.","zh":"這個片語顯示城市設計可以影響噪音水平。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":17},{"front":"before construction begins","meaning":"在施工開始之前","examples":[{"en":"The sound impact can be tested before construction begins.","zh":"聲音影響可以在施工開始之前被測試。"},{"en":"Before construction begins means before building work starts.","zh":"Before construction begins 指建築工程開始之前。"},{"en":"Schools should check safety plans before construction begins near classrooms.","zh":"學校應在課室附近施工開始之前檢查安全計劃。"},{"en":"Testing noise before construction begins can save money and prevent future problems.","zh":"在施工開始之前測試噪音可以節省金錢並防止未來問題。"},{"en":"This phrase marks a planning stage before physical work.","zh":"這個片語標示實體工程前的規劃階段。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":17},{"front":"play a greater leadership role","meaning":"發揮更大的領導作用","examples":[{"en":"Activists want the United States to play a greater leadership role.","zh":"倡議者希望美國發揮更大的領導作用。"},{"en":"To play a greater leadership role means to take more responsibility and guide others more actively.","zh":"To play a greater leadership role 指承擔更多責任並更積極引導他人。"},{"en":"A school principal may play a greater leadership role in improving student wellbeing.","zh":"校長可能在改善學生福祉方面發揮更大的領導作用。"},{"en":"If a country leads on noise policy, others may follow its example.","zh":"如果一個國家在噪音政策上領先，其他國家可能跟隨其例子。"},{"en":"This phrase describes stronger public responsibility.","zh":"這個片語描述更強公共責任。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":18},{"front":"as in other areas of","meaning":"正如在其他……範疇","examples":[{"en":"As in other areas of environmental health, regulation alone is not enough.","zh":"正如在其他環境健康範疇一樣，單靠規管並不足夠。"},{"en":"As in other areas of means similar to what happens in other parts of a wider field.","zh":"As in other areas of 指與更廣泛領域中的其他部分相似。"},{"en":"As in other areas of education, testing alone cannot solve every problem.","zh":"正如在其他教育範疇一樣，單靠測驗不能解決所有問題。"},{"en":"As in other health issues, prevention and research are needed as well as rules.","zh":"正如其他健康議題一樣，除了規則，也需要預防和研究。"},{"en":"This phrase connects one topic with a broader pattern.","zh":"這個片語把一個主題與更廣泛模式連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":18},{"front":"environmental health","meaning":"環境健康","examples":[{"en":"Noise pollution is an issue of environmental health.","zh":"噪音污染是環境健康議題。"},{"en":"Environmental health studies how surroundings such as air, water, noise, and buildings affect people’s health.","zh":"Environmental health 研究空氣、水、噪音和建築等周圍環境如何影響人的健康。"},{"en":"Poor housing, dirty air, and loud traffic are environmental health concerns.","zh":"惡劣住房、污濁空氣和繁忙交通聲都是環境健康憂慮。"},{"en":"Good environmental health policy protects people before illness appears.","zh":"良好環境健康政策在疾病出現前保護人。"},{"en":"This phrase connects the environment with public wellbeing.","zh":"這個片語把環境與公共福祉連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":18},{"front":"powerful government agency","meaning":"強大的政府機構","examples":[{"en":"A powerful government agency is not the ultimate answer.","zh":"強大的政府機構並不是最終答案。"},{"en":"A powerful government agency is a public body with strong authority, money, or enforcement power.","zh":"Powerful government agency 是擁有強大權力、資金或執法能力的公共機構。"},{"en":"A powerful government agency can set rules, inspect workplaces, and punish violations.","zh":"強大的政府機構可以制定規則、檢查工作場所並懲罰違規。"},{"en":"Even a powerful agency may fail if research, funding, and public cooperation are weak.","zh":"即使是強大機構，如果研究、資金和公眾合作薄弱，也可能失敗。"},{"en":"This phrase describes official strength, not a complete solution.","zh":"這個片語描述官方力量，而不是完整解決方法。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":18},{"front":"in place","meaning":"已設立；已存在","examples":[{"en":"Having a stronger agency in place is not the ultimate answer.","zh":"即使已有更強機構，也不是最終答案。"},{"en":"In place means set up, existing, and ready to operate.","zh":"In place 指已設立、已存在並準備好運作。"},{"en":"A school should have emergency plans in place before a typhoon arrives.","zh":"學校應在颱風到來前已有應急計劃。"},{"en":"Having rules in place does not help if nobody enforces them.","zh":"已有規則不代表有用，如果沒有人執行它們。"},{"en":"This phrase describes something already established.","zh":"這個片語描述某物已被建立。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":18},{"front":"set more regulations","meaning":"制定更多規例","examples":[{"en":"A government agency can set more regulations.","zh":"政府機構可以制定更多規例。"},{"en":"To set more regulations means to create additional official rules.","zh":"To set more regulations 指制定額外官方規則。"},{"en":"A city may set more regulations on night construction to reduce noise.","zh":"城市可能對夜間施工制定更多規例，以減少噪音。"},{"en":"More regulations can help, but they need enforcement and public understanding.","zh":"更多規例可以有幫助，但需要執法和公眾理解。"},{"en":"This phrase focuses on law-making or rule-setting.","zh":"這個片語著重立法或制定規則。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":18},{"front":"the ultimate answer","meaning":"最終答案；根本解決方法","examples":[{"en":"More regulation alone is not the ultimate answer.","zh":"單靠更多規管並不是最終答案。"},{"en":"The ultimate answer is the final or best solution to a problem.","zh":"Ultimate answer 是問題的最終或最佳解決方法。"},{"en":"Smaller class size may help, but it is not the ultimate answer to weak learning.","zh":"較小班級人數可能有幫助，但不是學習薄弱的最終答案。"},{"en":"For noise pollution, the ultimate answer may require research, planning, technology, and public action.","zh":"對噪音污染而言，根本解決方法可能需要研究、規劃、科技和公眾行動。"},{"en":"This phrase asks what truly solves the problem.","zh":"這個片語詢問甚麼真正解決問題。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":18},{"front":"stress that","meaning":"強調","examples":[{"en":"Bronzaft stresses that governments need to fund more noise research.","zh":"Bronzaft強調政府需要資助更多噪音研究。"},{"en":"To stress that something is true means to emphasise it strongly.","zh":"To stress that something is true 指強烈強調某事是真的。"},{"en":"A doctor may stress that sleep is essential for recovery.","zh":"醫生可能強調睡眠對康復很重要。"},{"en":"Experts stress key points when they want decision-makers to act.","zh":"專家在希望決策者行動時，會強調關鍵重點。"},{"en":"This phrase shows strong emphasis, not casual mention.","zh":"這個片語顯示強烈重視，而不是隨便提及。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":18},{"front":"increase funding for","meaning":"增加對……的資助","examples":[{"en":"Governments should increase funding for noise research.","zh":"政府應增加對噪音研究的資助。"},{"en":"To increase funding for something means to give it more money.","zh":"To increase funding for something 指給某事更多金錢。"},{"en":"A school may increase funding for counselling after student stress rises.","zh":"學生壓力上升後，學校可能增加對輔導的資助。"},{"en":"More funding for noise research can help scientists test solutions properly.","zh":"更多噪音研究資助可以幫助科學家妥善測試解決方案。"},{"en":"This phrase connects money with stronger action.","zh":"這個片語把金錢與更強行動連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":18},{"front":"noise research","meaning":"噪音研究","examples":[{"en":"Experts call for more noise research.","zh":"專家呼籲更多噪音研究。"},{"en":"Noise research is the study of how noise is produced, measured, reduced, and linked to health.","zh":"Noise research 是研究噪音如何產生、量度、減少，以及如何與健康相關。"},{"en":"Noise research may examine airports, schools, factories, roads, and homes.","zh":"噪音研究可能檢視機場、學校、工廠、道路和家居。"},{"en":"Better noise research can guide laws, building design, and public-health advice.","zh":"更好的噪音研究可以指導法律、建築設計和公共衛生建議。"},{"en":"This phrase describes scientific study of noise problems.","zh":"這個片語描述對噪音問題的科學研究。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":18},{"front":"coordinate efforts","meaning":"協調工作","examples":[{"en":"Governments should coordinate their noise pollution efforts.","zh":"政府應協調其噪音污染工作。"},{"en":"To coordinate efforts means to organise different actions so they work together effectively.","zh":"To coordinate efforts 指組織不同工作，使它們有效配合。"},{"en":"Teachers must coordinate efforts when helping a student with learning difficulties.","zh":"老師在幫助有學習困難的學生時，必須協調工作。"},{"en":"Noise control needs coordination among transport, planning, health, and education departments.","zh":"噪音控制需要交通、規劃、衛生和教育部門協調。"},{"en":"This phrase stresses teamwork across people or organisations.","zh":"這個片語強調人或機構之間的合作。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":18},{"front":"establish policies","meaning":"制定政策","examples":[{"en":"Governments should establish policies based on solid research.","zh":"政府應根據可靠研究制定政策。"},{"en":"To establish policies means to create official plans, rules, or principles for action.","zh":"To establish policies 指制定正式計劃、規則或行動原則。"},{"en":"A school may establish policies on phone use to reduce classroom distraction.","zh":"學校可能制定手機使用政策，以減少課堂分心。"},{"en":"Policies based on evidence are more likely to solve real problems.","zh":"基於證據的政策較可能解決真正問題。"},{"en":"This phrase describes formal decision-making.","zh":"這個片語描述正式決策。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":19},{"front":"solid scientific research","meaning":"可靠的科學研究","examples":[{"en":"Health and environmental policies should be based on solid scientific research.","zh":"健康和環境政策應基於可靠的科學研究。"},{"en":"Solid scientific research is reliable research using careful methods and strong evidence.","zh":"Solid scientific research 是使用仔細方法和強力證據的可靠研究。"},{"en":"A school health policy should rely on solid scientific research, not rumours.","zh":"學校健康政策應依靠可靠科學研究，而不是謠言。"},{"en":"Solid research can prevent governments from wasting money on weak solutions.","zh":"可靠研究可以防止政府把錢浪費在薄弱方案上。"},{"en":"This phrase emphasises trustworthy evidence.","zh":"這個片語強調可信證據。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":19},{"front":"have a responsibility to","meaning":"有責任去……","examples":[{"en":"Governments have a responsibility to protect their citizens.","zh":"政府有責任保護市民。"},{"en":"To have a responsibility to do something means to have a duty to do it.","zh":"To have a responsibility to do something 指有義務做某事。"},{"en":"Parents have a responsibility to keep young children safe.","zh":"父母有責任保護年幼孩子安全。"},{"en":"Governments have a responsibility to act when environmental risks harm public health.","zh":"當環境風險損害公共健康，政府有責任行動。"},{"en":"This phrase expresses moral, legal, or social duty.","zh":"這個片語表達道德、法律或社會責任。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":19},{"front":"protect their citizens","meaning":"保護市民","examples":[{"en":"Governments should protect their citizens from noise pollution.","zh":"政府應保護市民免受噪音污染影響。"},{"en":"To protect their citizens means to keep people safe from harm.","zh":"To protect their citizens 指保護人民免受傷害。"},{"en":"A city can protect its citizens by reducing dangerous road noise near homes.","zh":"城市可以透過減少住宅附近危險道路噪音來保護市民。"},{"en":"Public-health policies protect citizens when they prevent illness before it starts.","zh":"公共衛生政策在疾病開始前預防它，就是在保護市民。"},{"en":"This phrase connects government duty with public safety.","zh":"這個片語把政府責任與公共安全連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":19},{"front":"curb noise pollution","meaning":"遏制噪音污染","examples":[{"en":"Governments should curb noise pollution.","zh":"政府應遏制噪音污染。"},{"en":"To curb noise pollution means to reduce or control harmful unwanted sound.","zh":"To curb noise pollution 指減少或控制有害而不想要的聲音。"},{"en":"A city can curb noise pollution by limiting night construction.","zh":"城市可以透過限制夜間施工來遏制噪音污染。"},{"en":"Quieter buses and better road surfaces can help curb traffic noise.","zh":"較安靜巴士和更好路面可以幫助遏制交通噪音。"},{"en":"This phrase describes active control of a public problem.","zh":"這個片語描述對公共問題的積極控制。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":19},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the following summary.","zh":"Complete the summary below 指填寫下面摘要中的缺失字詞。"},{"en":"Students should read the whole summary before choosing answers.","zh":"學生應先閱讀整個摘要，再選擇答案。"},{"en":"The correct words must match both the passage and the grammar of the sentence.","zh":"正確字詞必須同時符合文章和句子文法。"},{"en":"This phrase is a common reading-test instruction.","zh":"這個片語是常見閱讀測驗指示。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":19},{"front":"no more than two words","meaning":"不多於兩個詞","examples":[{"en":"Students should choose no more than two words from the passage.","zh":"學生應從文章中選擇不多於兩個詞。"},{"en":"No more than two words means the answer may contain one or two words only.","zh":"No more than two words 指答案只能包含一個或兩個詞。"},{"en":"If the answer has three words, it breaks the instruction even if the idea is correct.","zh":"如果答案有三個詞，即使意思正確也違反指示。"},{"en":"Students should copy only the necessary words from the passage.","zh":"學生應只從文章中抄寫必要字詞。"},{"en":"This phrase controls the maximum answer length.","zh":"這個片語控制答案的最長長度。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":19},{"front":"avoid the effects of","meaning":"避免……的影響","examples":[{"en":"It is difficult to avoid the effects of living in a noisy world.","zh":"要避免生活在嘈雜世界中的影響是困難的。"},{"en":"To avoid the effects of something means to escape or prevent its results.","zh":"To avoid the effects of something 指逃避或防止某事的結果。"},{"en":"Students cannot avoid the effects of poor sleep if they stay up every night.","zh":"如果學生每晚熬夜，就無法避免睡眠不足的影響。"},{"en":"People may reduce but not fully avoid the effects of city noise.","zh":"人們可以減少但未必能完全避免城市噪音的影響。"},{"en":"This phrase connects prevention with consequences.","zh":"這個片語把預防與後果連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":19},{"front":"according to NIOSH","meaning":"根據 NIOSH","examples":[{"en":"According to NIOSH, hazardous noise exceeds 85 dBA.","zh":"根據NIOSH，有害噪音超過85分貝A。"},{"en":"According to NIOSH means based on information from the National Institute for Occupational Safety and Health.","zh":"According to NIOSH 指根據美國國家職業安全與健康研究所的資訊。"},{"en":"According to NIOSH, workers should be protected from unsafe noise exposure.","zh":"根據NIOSH，工人應受到保護，免受不安全噪音暴露影響。"},{"en":"Citing NIOSH gives the statement an occupational-health source.","zh":"引用NIOSH使該說法有職業健康來源。"},{"en":"This phrase identifies where the information comes from.","zh":"這個片語指出資訊來自哪裡。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":19},{"front":"by a certain age","meaning":"到某個年齡時","examples":[{"en":"Some workers develop hearing loss by a certain age.","zh":"一些工人到某個年齡時出現聽力喪失。"},{"en":"By a certain age means before or when people reach a specified age.","zh":"By a certain age 指在人們到達指定年齡之前或當時。"},{"en":"Some children can read simple books by a certain age, but development varies.","zh":"一些孩子到某個年齡時能讀簡單書，但發展各有不同。"},{"en":"If many workers lose hearing by a certain age, the workplace may be unsafe.","zh":"如果許多工人到某個年齡時失去聽力，工作場所可能不安全。"},{"en":"This phrase marks an age-related point of comparison.","zh":"這個片語標示與年齡相關的比較點。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":19},{"front":"be continually exposed to","meaning":"持續暴露於……","examples":[{"en":"Children who are continually exposed to excessive noise may have hearing problems.","zh":"持續暴露於過量噪音的兒童可能有聽力問題。"},{"en":"To be continually exposed to something means to face it again and again or for a long time.","zh":"To be continually exposed to something 指反覆或長時間面對某事物。"},{"en":"Children continually exposed to loud television may become used to unsafe volume.","zh":"持續暴露於大聲電視的兒童，可能習慣不安全音量。"},{"en":"Continual exposure can turn a small risk into a serious long-term problem.","zh":"持續暴露可以把小風險變成嚴重長期問題。"},{"en":"This phrase stresses repeated contact.","zh":"這個片語強調反覆接觸。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":19},{"front":"have difficulty with","meaning":"在……方面有困難","examples":[{"en":"Children may have difficulty with high-frequency sound discrimination.","zh":"兒童可能在高頻聲音辨別方面有困難。"},{"en":"To have difficulty with something means to find it hard to do or understand.","zh":"To have difficulty with something 指覺得做某事或理解某事困難。"},{"en":"Students may have difficulty with long reading passages if the room is noisy.","zh":"如果房間嘈雜，學生可能在長篇閱讀文章方面有困難。"},{"en":"Hearing damage can make children have difficulty with certain speech sounds.","zh":"聽力損害可以令兒童在某些語音方面有困難。"},{"en":"This phrase describes a specific area of struggle.","zh":"這個片語描述特定困難範疇。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":20},{"front":"residents","meaning":"居民","examples":[{"en":"European cities with many residents are creating noise maps.","zh":"擁有許多居民的歐洲城市正在製作噪音地圖。"},{"en":"Residents are people who live in a particular place.","zh":"Residents 是居住在某特定地方的人。"},{"en":"Residents near an airport may complain about aircraft noise at night.","zh":"機場附近的居民可能投訴夜間飛機噪音。"},{"en":"If many residents are affected, noise becomes a public issue rather than a private annoyance.","zh":"如果許多居民受影響，噪音便成為公共議題，而不是私人煩惱。"},{"en":"This word focuses on people living in an area.","zh":"這個詞著重居住在某地區的人。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":20},{"front":"look at the following researchers and organisations","meaning":"查看以下研究人員和組織","examples":[{"en":"Students look at the following researchers and organisations before matching findings.","zh":"學生在配對研究結果前查看以下研究人員和組織。"},{"en":"This instruction means students should read the listed names before choosing answers.","zh":"這個指示意思是學生在選答案前應閱讀列出的名稱。"},{"en":"In a matching task, students may need to connect each finding to the correct person or group.","zh":"在配對題中，學生可能需要把每項發現連接到正確人物或組織。"},{"en":"Looking at the list first helps students scan the passage more efficiently.","zh":"先查看列表可以幫助學生更有效掃讀文章。"},{"en":"This phrase is a reading-test instruction about matching information.","zh":"這個片語是關於配對資料的閱讀測驗指示。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":20},{"front":"list of findings","meaning":"研究結果列表","examples":[{"en":"The question provides a list of findings.","zh":"問題提供一份研究結果列表。"},{"en":"A list of findings is a set of research results or conclusions arranged for students to match or analyse.","zh":"List of findings 是一組被排列出來供學生配對或分析的研究結果或結論。"},{"en":"A science worksheet may give a list of findings from different experiments.","zh":"科學工作紙可能提供不同實驗的研究結果列表。"},{"en":"Students should match each finding with evidence in the passage.","zh":"學生應把每項發現與文章中的證據配對。"},{"en":"This phrase refers to results, not questions or names.","zh":"這個片語指結果，而不是問題或名稱。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":20},{"front":"match each finding with","meaning":"將每項發現與……配對","examples":[{"en":"Students match each finding with the correct researcher or organisation.","zh":"學生將每項發現與正確研究人員或組織配對。"},{"en":"To match each finding with something means to connect each result to the right source.","zh":"To match each finding with something 指把每項結果連接到正確來源。"},{"en":"Students may match each finding with a paragraph, name, or organisation in a reading test.","zh":"在閱讀測驗中，學生可能把每項發現與段落、姓名或組織配對。"},{"en":"Careful matching requires meaning, not just repeated words.","zh":"仔細配對需要理解意思，而不只是找重複字。"},{"en":"This phrase describes a pairing task.","zh":"這個片語描述配對任務。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":20},{"front":"researcher or organisation","meaning":"研究人員或組織","examples":[{"en":"Each finding is linked to a researcher or organisation.","zh":"每項發現都與一名研究人員或一個組織相關。"},{"en":"A researcher or organisation is a person or group responsible for a study, claim, or finding.","zh":"Researcher or organisation 是負責某研究、主張或發現的人或團體。"},{"en":"A finding about hearing loss may come from a university researcher or a health agency.","zh":"關於聽力喪失的發現可能來自大學研究人員或衛生機構。"},{"en":"Identifying the researcher or organisation helps students trace who said what.","zh":"辨認研究人員或組織幫助學生追蹤誰說了甚麼。"},{"en":"This phrase combines individual and institutional sources.","zh":"這個片語結合個人和機構來源。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":20},{"front":"changing the environment","meaning":"改變環境","examples":[{"en":"Changing the environment can improve hearing health.","zh":"改變環境可以改善聽力健康。"},{"en":"Changing the environment means altering the surroundings where people live, study, or work.","zh":"Changing the environment 指改變人們生活、學習或工作的周圍條件。"},{"en":"Moving a classroom away from traffic is one way of changing the environment.","zh":"把課室搬離交通噪音是一種改變環境的方法。"},{"en":"If the environment becomes quieter, people may sleep and learn better.","zh":"如果環境變得較安靜，人們可能睡得和學得更好。"},{"en":"This phrase shows that health can improve through changes around people.","zh":"這個片語顯示健康可以透過周圍改變而改善。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":20},{"front":"fund continued research into","meaning":"資助對……的持續研究","examples":[{"en":"Governments should fund continued research into controlling noise.","zh":"政府應資助對控制噪音的持續研究。"},{"en":"To fund continued research into something means to provide money for ongoing study of that topic.","zh":"To fund continued research into something 指為該主題的持續研究提供金錢。"},{"en":"A city may fund continued research into cleaner transport after pollution rises.","zh":"污染上升後，城市可能資助對更清潔交通的持續研究。"},{"en":"Continued research needs money for equipment, staff, testing, and analysis.","zh":"持續研究需要資金購買設備、聘請人員、進行測試和分析。"},{"en":"This phrase links public funding with long-term investigation.","zh":"這個片語把公共資助與長期調查連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":20},{"front":"controlling noise","meaning":"控制噪音","examples":[{"en":"Experts want more research into controlling noise.","zh":"專家希望有更多關於控制噪音的研究。"},{"en":"Controlling noise means reducing, limiting, or managing unwanted sound.","zh":"Controlling noise 指減少、限制或管理不想要的聲音。"},{"en":"A school can control noise by adding soft surfaces and closing windows during lessons.","zh":"學校可以透過加入柔軟表面和上課時關窗來控制噪音。"},{"en":"Cities control noise through traffic rules, building design, and quiet zones.","zh":"城市透過交通規則、建築設計和安靜區控制噪音。"},{"en":"This phrase focuses on practical management of noise pollution.","zh":"這個片語著重對噪音污染的實際管理。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":20},{"front":"protect employees from","meaning":"保護僱員免受……","examples":[{"en":"Companies should protect employees from harmful noise.","zh":"公司應保護僱員免受有害噪音影響。"},{"en":"To protect employees from something means to prevent workers from being harmed by it.","zh":"To protect employees from something 指防止工人受到某事傷害。"},{"en":"Employers protect employees from chemicals by providing masks and training.","zh":"僱主透過提供口罩和培訓，保護僱員免受化學物傷害。"},{"en":"Companies can protect employees from noise by reducing machine sound and providing ear protection.","zh":"公司可以透過降低機器聲和提供耳部保護，保護僱員免受噪音影響。"},{"en":"This phrase describes a workplace duty.","zh":"這個片語描述工作場所責任。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":20},{"front":"harmful noise","meaning":"有害噪音","examples":[{"en":"Workers need protection from harmful noise.","zh":"工人需要保護，免受有害噪音影響。"},{"en":"Harmful noise is noise that can damage hearing, sleep, health, or concentration.","zh":"Harmful noise 是可以損害聽力、睡眠、健康或專注力的噪音。"},{"en":"A drill used for hours can create harmful noise for construction workers.","zh":"使用數小時的電鑽可以為建築工人造成有害噪音。"},{"en":"Harmful noise should be reduced at the source whenever possible.","zh":"有害噪音應盡可能從源頭減少。"},{"en":"This phrase describes noise as a real risk, not just an annoyance.","zh":"這個片語把噪音描述為真實風險，而不只是煩擾。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":20},{"front":"affect children’s hearing","meaning":"影響兒童聽力","examples":[{"en":"Noise affects American children’s hearing.","zh":"噪音影響美國兒童的聽力。"},{"en":"To affect children’s hearing means to change how well children can hear sounds.","zh":"To affect children’s hearing 指改變兒童聽聲音的能力。"},{"en":"Loud toys and headphones can affect children’s hearing if used carelessly.","zh":"如果使用不慎，嘈雜玩具和耳機可以影響兒童聽力。"},{"en":"If children’s hearing is affected, speech and reading development may also suffer.","zh":"如果兒童聽力受影響，語言和閱讀發展也可能受損。"},{"en":"This phrase links sound exposure with young people’s hearing ability.","zh":"這個片語把聲音暴露與年輕人的聽力能力連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":21},{"front":"seriously affect hearing worldwide","meaning":"在全球嚴重影響聽力","examples":[{"en":"Noise seriously affects hearing worldwide.","zh":"噪音在全球嚴重影響聽力。"},{"en":"To seriously affect hearing worldwide means to cause major hearing problems across many countries.","zh":"To seriously affect hearing worldwide 指在許多國家造成重大聽力問題。"},{"en":"Loud workplaces and urban noise can seriously affect hearing on a global scale.","zh":"嘈雜工作場所和城市噪音可以在全球範圍嚴重影響聽力。"},{"en":"If a problem affects hearing worldwide, international guidelines may be needed.","zh":"如果問題在全球影響聽力，可能需要國際指引。"},{"en":"This phrase stresses both severity and global reach.","zh":"這個片語同時強調嚴重性和全球範圍。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":21},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter from the options.","zh":"學生從選項中選出正確字母。"},{"en":"Choose the correct letter means select the letter that matches the right answer.","zh":"Choose the correct letter 指選擇與正確答案相符的字母。"},{"en":"In a multiple-choice question, students should write A, B, C, or D clearly.","zh":"在多項選擇題中，學生應清楚寫A、B、C或D。"},{"en":"Choosing the correct letter requires understanding the passage, not just guessing.","zh":"選出正確字母需要理解文章，而不只是猜測。"},{"en":"This phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":21},{"front":"move the classrooms away from","meaning":"把課室搬離……","examples":[{"en":"The option says the school board moved the classrooms away from the tracks.","zh":"選項說校董會把課室搬離路軌。"},{"en":"To move classrooms away from something means to relocate them farther from that source.","zh":"To move classrooms away from something 指把課室遷到離該來源更遠的位置。"},{"en":"A school may move classrooms away from a noisy playground during exams.","zh":"學校可能在考試期間把課室搬離嘈雜操場。"},{"en":"Moving rooms away from noise can reduce exposure, but it may not always be practical.","zh":"把房間搬離噪音可以減少暴露，但未必總是實際可行。"},{"en":"This phrase describes a physical relocation.","zh":"這個片語描述實體搬遷。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":21},{"front":"noisy tracks","meaning":"嘈雜的路軌","examples":[{"en":"Children studied in classrooms near noisy tracks.","zh":"兒童在靠近嘈雜路軌的課室中學習。"},{"en":"Noisy tracks are railway tracks that produce loud sound when trains pass.","zh":"Noisy tracks 是列車經過時產生巨大聲音的鐵路軌道。"},{"en":"Noisy tracks beside a school can interrupt lessons several times an hour.","zh":"學校旁邊的嘈雜路軌可能每小時多次打斷課堂。"},{"en":"Treating noisy tracks may reduce sound before it reaches classrooms.","zh":"處理嘈雜路軌可以在聲音到達課室前減少它。"},{"en":"This phrase identifies a specific source of transport noise.","zh":"這個片語指出特定交通噪音來源。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":21},{"front":"reduce the use of","meaning":"減少使用……","examples":[{"en":"The option says the board reduced the use of the tracks.","zh":"選項說校董會減少使用路軌。"},{"en":"To reduce the use of something means to use it less often or less heavily.","zh":"To reduce the use of something 指較少或較低程度地使用某物。"},{"en":"A school may reduce the use of loud speakers during lesson time.","zh":"學校可能在上課時間減少使用揚聲器。"},{"en":"Reducing the use of noisy equipment can lower noise exposure.","zh":"減少使用嘈雜設備可以降低噪音暴露。"},{"en":"This phrase describes cutting down frequency or amount of use.","zh":"這個片語描述降低使用頻率或用量。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":21},{"front":"install special material","meaning":"安裝特殊材料","examples":[{"en":"The school board installed special material to reduce outside noise.","zh":"校董會安裝特殊材料以減少外來噪音。"},{"en":"To install special material means to put in a material designed for a particular purpose.","zh":"To install special material 指安裝為特定目的而設計的材料。"},{"en":"A library may install special material on walls to absorb echoes.","zh":"圖書館可能在牆上安裝特殊材料以吸收回聲。"},{"en":"Special sound-absorbing material can make a room quieter without moving the room.","zh":"特殊吸音材料可以令房間較安靜，而不用搬遷房間。"},{"en":"This phrase describes a practical building improvement.","zh":"這個片語描述實際建築改善。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":21},{"front":"reduce outside noise","meaning":"減少外來噪音","examples":[{"en":"Acoustical tile helped reduce outside noise in classrooms.","zh":"吸音天花板幫助減少課室中的外來噪音。"},{"en":"To reduce outside noise means to lower sound coming from outside a room or building.","zh":"To reduce outside noise 指降低來自房間或建築物外的聲音。"},{"en":"Thick windows can reduce outside noise from traffic.","zh":"厚窗戶可以減少來自交通的外來噪音。"},{"en":"Reducing outside noise can help students hear teachers more clearly.","zh":"減少外來噪音可以幫助學生更清楚聽到老師。"},{"en":"This phrase focuses on blocking or absorbing external sound.","zh":"這個片語著重阻擋或吸收外部聲音。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":21},{"front":"organise a follow-up study","meaning":"組織跟進研究","examples":[{"en":"The option says the school board organised a follow-up study.","zh":"選項說校董會組織跟進研究。"},{"en":"To organise a follow-up study means to arrange later research to check results after an action.","zh":"To organise a follow-up study 指安排後續研究，以檢查某行動後的結果。"},{"en":"A hospital may organise a follow-up study after introducing a new treatment.","zh":"醫院引入新治療後，可能組織跟進研究。"},{"en":"Follow-up studies help show whether an intervention really worked.","zh":"跟進研究幫助顯示介入措施是否真的有效。"},{"en":"This phrase describes planning later research.","zh":"這個片語描述安排後續研究。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":21},{"front":"research into noise","meaning":"噪音研究","examples":[{"en":"Research into noise helps authorities make better city-management decisions.","zh":"噪音研究幫助當局作出更好的城市管理決定。"},{"en":"Research into noise is the study of noise sources, levels, effects, and possible controls.","zh":"Research into noise 是研究噪音來源、水平、影響和可能控制方法。"},{"en":"A city may use research into noise before redesigning roads near schools.","zh":"城市在重新設計學校附近道路前，可能使用噪音研究。"},{"en":"Noise research can show where policy should focus first.","zh":"噪音研究可以顯示政策應先集中在哪裡。"},{"en":"This phrase connects scientific study with practical planning.","zh":"這個片語把科學研究與實際規劃連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":21},{"front":"be intended to","meaning":"旨在","examples":[{"en":"Noise mapping is intended to help authorities manage cities better.","zh":"噪音地圖旨在幫助當局更好管理城市。"},{"en":"To be intended to do something means to be designed or planned for that purpose.","zh":"To be intended to do something 指被設計或計劃用於某目的。"},{"en":"A school notice is intended to remind parents about exam arrangements.","zh":"學校通告旨在提醒家長考試安排。"},{"en":"Noise maps are intended to guide decisions before construction and policy changes.","zh":"噪音地圖旨在於施工和政策改變前指導決定。"},{"en":"This phrase explains purpose.","zh":"這個片語解釋目的。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":21},{"front":"record every detail of","meaning":"記錄……的每個細節","examples":[{"en":"The option says maps record every detail of urban pollution.","zh":"選項說地圖記錄城市污染的每個細節。"},{"en":"To record every detail of something means to collect and note all parts of it very completely.","zh":"To record every detail of something 指非常完整地收集並記下所有部分。"},{"en":"A teacher cannot record every detail of a student’s day, but key patterns matter.","zh":"老師不能記錄學生一天的每個細節，但關鍵模式很重要。"},{"en":"Noise maps may record important sound levels, not every detail of all pollution.","zh":"噪音地圖可能記錄重要聲音水平，而不是所有污染的每個細節。"},{"en":"This phrase suggests complete documentation.","zh":"這個片語暗示完整記錄。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":22},{"front":"urban pollution","meaning":"城市污染","examples":[{"en":"Noise pollution is one form of urban pollution.","zh":"噪音污染是城市污染的一種形式。"},{"en":"Urban pollution is pollution found in cities, such as dirty air, waste, noise, or contaminated water.","zh":"Urban pollution 是城市中的污染，例如污濁空氣、廢物、噪音或受污染水。"},{"en":"Traffic can create both air pollution and noise pollution in urban areas.","zh":"交通可以在城市地區造成空氣污染和噪音污染。"},{"en":"Urban pollution affects many people because city populations are dense.","zh":"城市污染影響很多人，因為城市人口密集。"},{"en":"This phrase describes environmental problems in cities.","zh":"這個片語描述城市中的環境問題。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":22},{"front":"population movement","meaning":"人口流動","examples":[{"en":"The option mentions the effect of noise on population movement.","zh":"選項提到噪音對人口流動的影響。"},{"en":"Population movement means people moving from one place to another to live or work.","zh":"Population movement 指人們從一個地方搬到另一個地方生活或工作。"},{"en":"High rent can cause population movement from city centres to outer districts.","zh":"高租金可以造成從市中心到外圍地區的人口流動。"},{"en":"If noise becomes unbearable, some residents may move away.","zh":"如果噪音變得難以忍受，一些居民可能搬走。"},{"en":"This phrase describes changes in where people live.","zh":"這個片語描述人們居住地點的變化。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":22},{"front":"make better decisions about","meaning":"就……作出更好決定","examples":[{"en":"Noise maps help authorities make better decisions about city management.","zh":"噪音地圖幫助當局就城市管理作出更好決定。"},{"en":"To make better decisions about something means to choose more wisely because of better information.","zh":"To make better decisions about something 指因有更好資訊而作出更明智選擇。"},{"en":"Parents can make better decisions about sleep if they know how tired their child is.","zh":"如果父母知道孩子有多疲倦，就能就睡眠作出更好決定。"},{"en":"City leaders can make better decisions about roads when they understand noise effects.","zh":"城市領導者了解噪音影響後，可以就道路作出更好決定。"},{"en":"This phrase connects evidence with improved judgement.","zh":"這個片語把證據與改善判斷連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":22},{"front":"city management","meaning":"城市管理","examples":[{"en":"Noise research can improve city management.","zh":"噪音研究可以改善城市管理。"},{"en":"City management is the planning and running of urban services, spaces, transport, and rules.","zh":"City management 是對城市服務、空間、交通和規則的規劃與運作。"},{"en":"Good city management includes traffic control, waste collection, housing, and public safety.","zh":"良好城市管理包括交通控制、垃圾收集、住房和公共安全。"},{"en":"Noise maps can improve city management by showing where quieter design is needed.","zh":"噪音地圖可以顯示哪裡需要較安靜設計，從而改善城市管理。"},{"en":"This phrase describes how a city is organised and governed.","zh":"這個片語描述城市如何被組織和治理。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":22},{"front":"the best title for","meaning":"……的最佳標題","examples":[{"en":"The question asks for the best title for the passage.","zh":"問題要求選出文章的最佳標題。"},{"en":"The best title for a passage is the title that most accurately captures its main idea.","zh":"The best title for a passage 是最準確概括文章主旨的標題。"},{"en":"Students should choose the best title by considering the whole passage, not one paragraph.","zh":"學生應考慮整篇文章，而不是一段，來選出最佳標題。"},{"en":"A good title reflects the topic, focus, and argument of the text.","zh":"好標題反映文本的主題、焦點和論點。"},{"en":"This phrase is common in reading comprehension questions.","zh":"這個片語常見於閱讀理解題。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":22},{"front":"cope with noise pollution","meaning":"應對噪音污染","examples":[{"en":"The option asks how people cope with noise pollution.","zh":"選項問人們如何應對噪音污染。"},{"en":"To cope with noise pollution means to manage or live with unwanted harmful sound.","zh":"To cope with noise pollution 指管理或忍受不想要的有害聲音。"},{"en":"Residents may cope with noise pollution by using double-glazed windows.","zh":"居民可能透過使用雙層玻璃窗應對噪音污染。"},{"en":"Coping with noise is not the same as solving the noise problem at its source.","zh":"應對噪音不等於從源頭解決噪音問題。"},{"en":"This phrase focuses on dealing with difficulty.","zh":"這個片語著重處理困難。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":22},{"front":"fight noise with technology","meaning":"用科技對抗噪音","examples":[{"en":"Some policies try to fight noise with technology.","zh":"一些政策嘗試用科技對抗噪音。"},{"en":"To fight noise with technology means to use machines, materials, data, or models to reduce noise.","zh":"To fight noise with technology 指使用機器、材料、數據或模型來減少噪音。"},{"en":"Cities can fight noise with technology such as sound barriers and noise maps.","zh":"城市可以用隔音屏障和噪音地圖等科技對抗噪音。"},{"en":"Technology can help, but laws and public behaviour may also be needed.","zh":"科技可以有幫助，但也可能需要法律和公眾行為配合。"},{"en":"This phrase connects noise control with technical solutions.","zh":"這個片語把噪音控制與技術方案連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":22},{"front":"effects of noise on","meaning":"噪音對……的影響","examples":[{"en":"The passage discusses the effects of noise on health and learning.","zh":"文章討論噪音對健康和學習的影響。"},{"en":"The effects of noise on something are the ways noise changes or harms that area.","zh":"Effects of noise on something 是噪音改變或傷害該方面的方式。"},{"en":"Researchers study the effects of noise on sleep, memory, and blood pressure.","zh":"研究人員研究噪音對睡眠、記憶和血壓的影響。"},{"en":"If noise affects learning, schools should consider classroom location and materials.","zh":"如果噪音影響學習，學校應考慮課室位置和材料。"},{"en":"This phrase connects noise with a specific result or target.","zh":"這個片語把噪音與特定結果或對象連接起來。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":22},{"front":"children’s learning","meaning":"兒童學習","examples":[{"en":"Noise can damage children’s learning.","zh":"噪音可以損害兒童學習。"},{"en":"Children’s learning means how children understand, remember, practise, and use new knowledge.","zh":"Children’s learning 指兒童如何理解、記住、練習和使用新知識。"},{"en":"Children’s learning improves when classrooms are quiet enough for them to hear instructions.","zh":"當課室安靜到足以讓兒童聽清指示，兒童學習會改善。"},{"en":"Constant noise can damage children’s learning by interrupting attention and reading practice.","zh":"持續噪音可以透過打斷注意力和閱讀練習損害兒童學習。"},{"en":"This phrase focuses on children’s educational development.","zh":"這個片語著重兒童教育發展。"}],"source":"121 - A decibel Hell (The Effects of Living in a Noisy World).pdf","sourcePage":22}],"ielts/reading/passage-2/Practice 122":[{"front":"life code","meaning":"生命密碼","examples":[{"en":"The article describes how scientists tried to unlock the life code of gene regulation.","zh":"文章描述科學家如何嘗試破解基因調控的生命密碼。"},{"en":"A life code is a hidden set of biological rules that explains how living systems work.","zh":"生命密碼是一套隱藏的生物規則，用來解釋生命系統如何運作。"},{"en":"Students can think of DNA as part of the life code because it carries instructions for cells.","zh":"學生可以把 DNA 視為生命密碼的一部分，因為它攜帶細胞指令。"},{"en":"When scientists understand the life code better, they can explain why cells behave differently.","zh":"當科學家更了解生命密碼，就能解釋為何細胞有不同行為。"},{"en":"The life code is not a simple password; it is a complex system of genetic instructions and controls.","zh":"生命密碼不是簡單密碼，而是一套複雜的遺傳指令和控制系統。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":1},{"front":"unlock","meaning":"解開；破解","examples":[{"en":"Machine learning helped researchers unlock hidden rules in biological data.","zh":"機器學習幫助研究人員破解生物數據中的隱藏規則。"},{"en":"To unlock something means to discover, explain, or make it accessible.","zh":"unlock something 指發現、解釋或使某事變得可理解。"},{"en":"A good teacher can unlock a difficult grammar point by using clear examples.","zh":"好老師可以透過清楚例子解開困難文法點。"},{"en":"New evidence may unlock the answer to a problem that confused scientists for years.","zh":"新證據可能破解困擾科學家多年的問題答案。"},{"en":"This verb often suggests that something valuable was closed, hidden, or hard to understand.","zh":"這個動詞常表示某些有價值的東西原本被關閉、隱藏或難以理解。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":1},{"front":"airport shuttle bus","meaning":"機場接駁巴士","examples":[{"en":"Wiggins opened the spreadsheet on an airport shuttle bus to the Kavli Institute.","zh":"Wiggins 在前往 Kavli Institute 的機場接駁巴士上打開試算表。"},{"en":"An airport shuttle bus is a bus that carries passengers between an airport and another nearby place.","zh":"airport shuttle bus 指接載乘客往返機場和附近地方的巴士。"},{"en":"A hotel may provide an airport shuttle bus so guests do not need to take a taxi.","zh":"酒店可能提供機場接駁巴士，讓住客不用乘搭的士。"},{"en":"Airport shuttle buses save time when many people are travelling to the same destination.","zh":"當多人前往同一目的地時，機場接駁巴士可以節省時間。"},{"en":"This phrase refers to transport connected with the airport, not a normal city bus route.","zh":"這個短語指與機場相關的交通，而不是普通市區巴士路線。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":1},{"front":"theoretical physics","meaning":"理論物理學","examples":[{"en":"Chris Wiggins was travelling to a theoretical physics institute in California.","zh":"Chris Wiggins 正前往加州一所理論物理學研究所。"},{"en":"Theoretical physics is the study of physical laws using ideas, mathematics, and models.","zh":"理論物理學是用概念、數學和模型研究物理定律的學科。"},{"en":"A student interested in black holes may read books about theoretical physics.","zh":"對黑洞有興趣的學生可能會閱讀理論物理學書籍。"},{"en":"Theoretical physics can guide experiments by predicting what scientists should look for.","zh":"理論物理學可以透過預測科學家應尋找甚麼來指導實驗。"},{"en":"Unlike practical engineering, theoretical physics often begins with equations and explanations.","zh":"與實用工程不同，理論物理學常從方程式和解釋開始。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":1},{"front":"take a colleague’s advice","meaning":"聽從同事的建議","examples":[{"en":"Wiggins took a colleague’s advice and opened the spreadsheet.","zh":"Wiggins 聽從同事的建議，打開了試算表。"},{"en":"To take a colleague’s advice means to follow a suggestion given by someone you work with.","zh":"take a colleague’s advice 指聽從工作同事提出的建議。"},{"en":"A new teacher may take a colleague’s advice about how to manage a noisy class.","zh":"新老師可能聽從同事關於如何管理嘈雜班級的建議。"},{"en":"Taking a colleague’s advice can save time when that person has useful experience.","zh":"當同事有有用經驗時，聽從同事的建議可以節省時間。"},{"en":"This phrase shows that the speaker trusted someone else’s professional judgement.","zh":"這個短語表示說話者信任別人的專業判斷。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":1},{"front":"Microsoft Excel spreadsheet","meaning":"Microsoft Excel試算表","examples":[{"en":"The data were stored in a Microsoft Excel spreadsheet.","zh":"數據儲存在一個 Microsoft Excel 試算表中。"},{"en":"A Microsoft Excel spreadsheet is a digital table used to organise numbers, text, and calculations.","zh":"Microsoft Excel 試算表是用來整理數字、文字和計算的數碼表格。"},{"en":"A small business may use a Microsoft Excel spreadsheet to track sales and expenses.","zh":"小企業可能用 Microsoft Excel 試算表追蹤銷售和開支。"},{"en":"When data are stored in a spreadsheet, researchers can sort, compare, and calculate them more easily.","zh":"當數據儲存在試算表中，研究人員可以更容易排序、比較和計算。"},{"en":"This phrase refers to the file format or tool, not the scientific meaning of the data.","zh":"這個短語指檔案格式或工具，而不是數據的科學意義。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":1},{"front":"have nothing to do with","meaning":"與……毫無關係","examples":[{"en":"The spreadsheet had nothing to do with the talk he was invited to give.","zh":"這份試算表與他受邀發表的演講毫無關係。"},{"en":"To have nothing to do with something means to be completely unrelated to it.","zh":"have nothing to do with something 指與某事完全無關。"},{"en":"A student’s late homework may have nothing to do with laziness if the internet was down.","zh":"如果網絡壞了，學生遲交功課可能與懶惰毫無關係。"},{"en":"If a question has nothing to do with the lesson, the teacher may answer it later.","zh":"如果問題與課堂毫無關係，老師可能稍後再回答。"},{"en":"This phrase separates one issue from another clearly.","zh":"這個短語清楚把一件事與另一件事分開。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":1},{"front":"a talk on","meaning":"關於……的演講","examples":[{"en":"Wiggins was invited to give a talk on biopolymer physics.","zh":"Wiggins 獲邀發表一場關於生物聚合物物理學的演講。"},{"en":"A talk on a topic is a speech or presentation about that subject.","zh":"a talk on a topic 指關於某主題的演說或簡報。"},{"en":"A doctor may give a talk on healthy eating at a community centre.","zh":"醫生可能在社區中心發表關於健康飲食的演講。"},{"en":"A talk on exam skills can help students understand what to practise first.","zh":"關於考試技巧的演講可以幫助學生了解應先練習甚麼。"},{"en":"This phrase is used when naming the subject of a speech.","zh":"這個短語用於指出演講的主題。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":1},{"front":"biopolymer physics","meaning":"生物聚合物物理學","examples":[{"en":"The talk was supposed to be about biopolymer physics.","zh":"這場演講原本應該是關於生物聚合物物理學。"},{"en":"Biopolymer physics studies the physical behaviour of large biological molecules such as DNA, RNA, and proteins.","zh":"生物聚合物物理學研究 DNA、RNA 和蛋白質等大型生物分子的物理行為。"},{"en":"A scientist may use biopolymer physics to understand how DNA bends or folds.","zh":"科學家可能用生物聚合物物理學理解 DNA 如何彎曲或摺疊。"},{"en":"Studying biopolymer physics can help explain how biological molecules work inside cells.","zh":"研究生物聚合物物理學可以幫助解釋生物分子如何在細胞內運作。"},{"en":"This phrase connects biology with physical laws and mathematical models.","zh":"這個短語把生物學與物理定律和數學模型連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":1},{"front":"be invited to give","meaning":"獲邀發表","examples":[{"en":"Wiggins was invited to give a talk at the institute.","zh":"Wiggins 獲邀在該研究所發表演講。"},{"en":"To be invited to give a talk means to be asked formally to speak to an audience.","zh":"be invited to give a talk 指正式受邀向觀眾演講。"},{"en":"A professor may be invited to give a lecture at another university.","zh":"教授可能獲邀到另一所大學發表講座。"},{"en":"Being invited to give a talk often shows that people respect the speaker’s expertise.","zh":"獲邀發表演講通常表示人們尊重講者的專業知識。"},{"en":"This phrase focuses on a formal speaking opportunity.","zh":"這個短語著重正式發言機會。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":1},{"front":"rather","meaning":"而是；相反","examples":[{"en":"The spreadsheet was not about his talk; rather, it contained genetic data.","zh":"這份試算表不是關於他的演講；而是包含遺傳數據。"},{"en":"Rather is used to correct or replace one idea with a different one.","zh":"rather 用來修正或以另一個想法取代前一個想法。"},{"en":"The problem was not lack of effort; rather, the instructions were unclear.","zh":"問題不是缺乏努力；而是指示不清楚。"},{"en":"A museum is not only a place for old objects; rather, it can be a learning space.","zh":"博物館不只是存放舊物件的地方；而是可以成為學習空間。"},{"en":"This word helps show contrast between what is rejected and what is actually true.","zh":"這個詞幫助顯示被否定的想法與實際情況之間的對比。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":2},{"front":"columns and rows of numbers","meaning":"一欄欄和一行行數字","examples":[{"en":"The columns and rows of numbers referred to yeast genes.","zh":"一欄欄和一行行數字指的是酵母基因。"},{"en":"Columns and rows of numbers are data arranged vertically and horizontally in a table.","zh":"columns and rows of numbers 指在表格中縱向和橫向排列的數據。"},{"en":"A shop manager may study columns and rows of numbers to compare daily sales.","zh":"店舖經理可能研究一欄欄和一行行數字，以比較每日銷售。"},{"en":"When data are arranged in columns and rows, patterns become easier to find.","zh":"當數據排列成行和列時，模式會較容易找出。"},{"en":"This phrase often describes spreadsheet data before its meaning is understood.","zh":"這個短語常描述人們理解其意義前的試算表數據。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":2},{"front":"stare back at someone","meaning":"映入某人眼簾；直直地呈現在某人眼前","examples":[{"en":"The columns and rows of numbers stared back at Wiggins.","zh":"一欄欄和一行行數字直直地呈現在 Wiggins 眼前。"},{"en":"If something stares back at someone, it appears clearly in front of them and demands attention.","zh":"stare back at someone 指某物清楚出現在某人面前，令人不得不注意。"},{"en":"When a student opens a difficult exam paper, many unfamiliar questions may seem to stare back at them.","zh":"當學生打開困難試卷時，許多陌生問題可能像直直地呈現在眼前。"},{"en":"A long list of unpaid bills can stare back at a person and make the problem impossible to ignore.","zh":"一長串未付帳單可以直直地呈現在某人眼前，令問題不能被忽視。"},{"en":"This phrase gives lifeless information a strong, almost personal presence.","zh":"這個短語令沒有生命的資料帶有強烈、近乎個人化的存在感。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":2},{"front":"refer to","meaning":"指的是","examples":[{"en":"The numbers referred to the genetic activity of budding yeast.","zh":"這些數字指的是出芽酵母的基因活動。"},{"en":"To refer to something means to mean, describe, or point to it.","zh":"refer to something 指表示、描述或指向某事物。"},{"en":"In a timetable, the numbers may refer to classroom locations rather than lesson times.","zh":"在時間表中，數字可能指的是課室位置，而不是上課時間。"},{"en":"If a word refers to several things, readers must use context to choose the right meaning.","zh":"如果一個詞指向多個事物，讀者必須用上下文選擇正確意思。"},{"en":"This phrase connects a sign, word, or number with what it represents.","zh":"這個短語把符號、詞語或數字與它代表的事物連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":2},{"front":"genetic activity","meaning":"基因活動","examples":[{"en":"The spreadsheet recorded the genetic activity of budding yeast.","zh":"試算表記錄了出芽酵母的基因活動。"},{"en":"Genetic activity is the process by which genes are turned on, turned off, or used to make products.","zh":"genetic activity 指基因被開啟、關閉或用來製造產物的過程。"},{"en":"Scientists may compare genetic activity in healthy and diseased cells.","zh":"科學家可能比較健康細胞和患病細胞中的基因活動。"},{"en":"Changes in genetic activity can affect how a cell grows, repairs itself, or responds to stress.","zh":"基因活動的變化可以影響細胞如何生長、修復自身或回應壓力。"},{"en":"This phrase focuses on what genes are doing, not just where they are located.","zh":"這個短語著重基因正在做甚麼，而不只是基因位於哪裡。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":2},{"front":"budding yeast","meaning":"出芽酵母","examples":[{"en":"The data came from the genetic activity of budding yeast.","zh":"這些數據來自出芽酵母的基因活動。"},{"en":"Budding yeast is a single-celled organism that reproduces by forming a small new cell from the old one.","zh":"出芽酵母是一種單細胞生物，透過從舊細胞長出小新細胞來繁殖。"},{"en":"Scientists often study budding yeast because it grows quickly and is easy to handle in the lab.","zh":"科學家經常研究出芽酵母，因為它生長快，且在實驗室中容易處理。"},{"en":"Research on budding yeast can reveal basic rules that also matter in more complex organisms.","zh":"對出芽酵母的研究可以揭示在更複雜生物中也重要的基本規則。"},{"en":"Although budding yeast is simple, it can teach scientists a lot about cells.","zh":"雖然出芽酵母很簡單，但它能教科學家許多關於細胞的知識。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":2},{"front":"specifically","meaning":"具體來說","examples":[{"en":"Specifically, the numbers represented the amount of mRNA expressed by the genes.","zh":"具體來說，這些數字代表基因所表達的 mRNA 數量。"},{"en":"Specifically is used to give a clearer or more exact explanation.","zh":"specifically 用來給出更清楚或更精確的解釋。"},{"en":"The school needs more support; specifically, it needs two extra teachers for science.","zh":"學校需要更多支援；具體來說，它需要兩名額外科學老師。"},{"en":"Using “specifically” helps readers see which detail matters most.","zh":"使用 specifically 可以幫助讀者看見哪個細節最重要。"},{"en":"This word narrows a general statement into a precise point.","zh":"這個詞把一般說法收窄成精確重點。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":2},{"front":"represent the amount of","meaning":"代表……的數量","examples":[{"en":"The numbers represented the amount of messenger RNA in the yeast.","zh":"這些數字代表酵母中信使 RNA 的數量。"},{"en":"To represent the amount of something means to show its quantity in numbers, symbols, or data.","zh":"represent the amount of something 指用數字、符號或數據顯示某物的數量。"},{"en":"A bar chart may represent the amount of money spent by each department.","zh":"柱狀圖可以代表每個部門花費的金錢數量。"},{"en":"If a number represents the amount of sugar in a drink, people can compare drinks more easily.","zh":"如果一個數字代表飲品中的糖分數量，人們就能更容易比較飲品。"},{"en":"This phrase connects data with the real quantity being measured.","zh":"這個短語把數據與被量度的真實數量連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":2},{"front":"messenger RNA","meaning":"信使RNA","examples":[{"en":"Messenger RNA carries genetic instructions for protein production.","zh":"信使 RNA 攜帶製造蛋白質的遺傳指令。"},{"en":"Messenger RNA is a molecule that copies genetic information from DNA and helps cells make proteins.","zh":"信使 RNA 是一種分子，會從 DNA 複製遺傳資訊，並幫助細胞製造蛋白質。"},{"en":"In a classroom explanation, messenger RNA can be compared to a temporary instruction note.","zh":"在課堂解釋中，信使 RNA 可以比作一張臨時指令紙。"},{"en":"If messenger RNA levels change, the amount of protein made by a cell may also change.","zh":"如果信使 RNA 水平改變，細胞製造的蛋白質數量也可能改變。"},{"en":"This phrase is often shortened to mRNA in biology.","zh":"這個短語在生物學中常縮寫為 mRNA。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":2},{"front":"be expressed by","meaning":"由……表達","examples":[{"en":"The spreadsheet showed how much mRNA was expressed by each gene.","zh":"試算表顯示每個基因表達了多少 mRNA。"},{"en":"If mRNA is expressed by a gene, the gene is being used to produce that RNA message.","zh":"如果 mRNA is expressed by a gene，意思是該基因正被用來產生那段 RNA 訊息。"},{"en":"Scientists measure what is expressed by genes to learn which genes are active.","zh":"科學家量度由基因表達的東西，以了解哪些基因活躍。"},{"en":"More mRNA expressed by a gene may lead to more related protein being produced.","zh":"某基因表達更多 mRNA，可能導致更多相關蛋白質被製造。"},{"en":"This phrase describes gene activity, not emotional expression.","zh":"這個短語描述基因活動，而不是情感表達。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":2},{"front":"over the course of","meaning":"在……期間","examples":[{"en":"The data covered gene activity over the course of the yeast’s reproductive cycle.","zh":"這些數據涵蓋酵母繁殖週期期間的基因活動。"},{"en":"Over the course of a period means during the whole period as time passes.","zh":"over the course of a period 指在整段期間隨時間發生。"},{"en":"A student’s confidence may improve over the course of a school year.","zh":"學生的信心可能在一個學年期間提升。"},{"en":"Measuring something over the course of many days can show changes that one measurement misses.","zh":"在許多日子期間量度某物，可以顯示單次量度看不到的變化。"},{"en":"This phrase emphasises a process across time.","zh":"這個短語強調跨時間的過程。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":3},{"front":"reproductive cycle","meaning":"繁殖週期","examples":[{"en":"The yeast genes were measured over the course of the reproductive cycle.","zh":"酵母基因在繁殖週期期間被量度。"},{"en":"A reproductive cycle is the repeated biological process through which an organism prepares to produce offspring.","zh":"reproductive cycle 指生物準備產生後代的重複生物過程。"},{"en":"In plants, the reproductive cycle may include flowering, pollination, and seed formation.","zh":"在植物中，繁殖週期可能包括開花、授粉和種子形成。"},{"en":"Studying the reproductive cycle helps scientists know when important genetic changes happen.","zh":"研究繁殖週期幫助科學家知道重要基因變化何時發生。"},{"en":"This phrase refers to reproduction as a sequence, not a single moment.","zh":"這個短語把繁殖視為一連串過程，而不是單一時刻。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":3},{"front":"it was the first time","meaning":"那是第一次","examples":[{"en":"It was the first time Wiggins had seen data like this.","zh":"那是 Wiggins 第一次看見這樣的數據。"},{"en":"It was the first time means the event had never happened before for that person or group.","zh":"it was the first time 指某事件對某人或某群體而言以前從未發生過。"},{"en":"It was the first time the student had spoken English in front of the whole class.","zh":"那是學生第一次在全班面前說英語。"},{"en":"First experiences can feel confusing because people have no past example to follow.","zh":"第一次經驗可能令人困惑，因為人們沒有過去例子可跟隨。"},{"en":"This phrase highlights novelty and lack of previous experience.","zh":"這個短語強調新鮮感和缺乏過往經驗。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":3},{"front":"make sense of","meaning":"理解；弄明白","examples":[{"en":"Wiggins wanted to make sense of all the biological data.","zh":"Wiggins 想弄明白所有生物數據。"},{"en":"To make sense of something means to understand it clearly or find meaning in it.","zh":"make sense of something 指清楚理解某事或在其中找出意義。"},{"en":"A student may draw a mind map to make sense of a long history chapter.","zh":"學生可能畫思維導圖來理解一章很長的歷史內容。"},{"en":"Charts can help people make sense of numbers that look confusing in a table.","zh":"圖表可以幫助人理解表格中看起來混亂的數字。"},{"en":"This phrase is useful when information is messy, complex, or unfamiliar.","zh":"當資訊混亂、複雜或陌生時，這個短語很有用。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":3},{"front":"shy away from","meaning":"迴避；退縮","examples":[{"en":"Wiggins did not shy away from the challenge of analysing the data.","zh":"Wiggins 沒有迴避分析數據的挑戰。"},{"en":"To shy away from something means to avoid it because it seems difficult, risky, or uncomfortable.","zh":"shy away from something 指因某事困難、有風險或令人不舒服而避開它。"},{"en":"A student should not shy away from asking questions when the lesson is confusing.","zh":"當課堂令人困惑時，學生不應迴避提問。"},{"en":"People may shy away from public speaking because they fear making mistakes.","zh":"人們可能因害怕犯錯而迴避公開演說。"},{"en":"This phrase often contrasts avoidance with courage or willingness to try.","zh":"這個短語常把逃避與勇氣或願意嘗試作對比。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":3},{"front":"applied mathematician","meaning":"應用數學家","examples":[{"en":"Wiggins was an applied mathematician at Columbia University.","zh":"Wiggins 是哥倫比亞大學的應用數學家。"},{"en":"An applied mathematician uses mathematical ideas to solve real-world problems.","zh":"applied mathematician 指使用數學概念解決現實問題的人。"},{"en":"An applied mathematician may help hospitals predict patient flow or help companies plan delivery routes.","zh":"應用數學家可能幫助醫院預測病人流量，或幫助公司規劃送貨路線。"},{"en":"Applied mathematicians are useful when complex problems need models and data analysis.","zh":"當複雜問題需要模型和數據分析時，應用數學家很有用。"},{"en":"This phrase connects mathematics with practical use, not pure theory only.","zh":"這個短語把數學與實際用途連繫起來，而不只是純理論。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":3},{"front":"physicist","meaning":"物理學家","examples":[{"en":"Wiggins was both an applied mathematician and a physicist.","zh":"Wiggins 既是應用數學家，也是物理學家。"},{"en":"A physicist is a scientist who studies matter, energy, forces, and the laws of nature.","zh":"physicist 指研究物質、能量、力和自然定律的科學家。"},{"en":"A physicist may study light, sound, electricity, atoms, or the movement of planets.","zh":"物理學家可能研究光、聲、電、原子或行星運動。"},{"en":"Physicists often use experiments and mathematics to explain how the world works.","zh":"物理學家常使用實驗和數學解釋世界如何運作。"},{"en":"This word refers to a scientific role, not simply someone who likes science.","zh":"這個詞指科學角色，而不只是喜歡科學的人。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":3},{"front":"embrace a question","meaning":"欣然接受問題；正面迎接問題","examples":[{"en":"Instead of avoiding the problem, Wiggins embraced the question.","zh":"Wiggins 沒有避開問題，而是正面迎接它。"},{"en":"To embrace a question means to accept it willingly and treat it as worth exploring.","zh":"embrace a question 指願意接受某個問題，並把它視為值得探索。"},{"en":"A teacher may embrace a difficult question from a student and turn it into a class discussion.","zh":"老師可能欣然接受學生提出的困難問題，並把它變成課堂討論。"},{"en":"When researchers embrace a question, they may enter new fields and methods.","zh":"當研究人員正面迎接問題，他們可能進入新領域和新方法。"},{"en":"This phrase suggests curiosity and courage rather than avoidance.","zh":"這個短語表示好奇和勇氣，而不是逃避。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":3},{"front":"venture into","meaning":"涉足；踏入","examples":[{"en":"Wiggins ventured into fields outside his own.","zh":"Wiggins 涉足了自己專業以外的領域。"},{"en":"To venture into a field means to enter a new area that may be unfamiliar or risky.","zh":"venture into a field 指進入一個可能陌生或有風險的新領域。"},{"en":"A teacher may venture into video production to create better online lessons.","zh":"老師可能涉足影片製作，以創造更好的網上課程。"},{"en":"Venturing into a new field can lead to mistakes, but it can also create fresh ideas.","zh":"踏入新領域可能導致錯誤，但也可能創造新想法。"},{"en":"This phrase suggests exploration beyond one’s usual comfort zone.","zh":"這個短語表示探索自己舒適圈以外的地方。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":3},{"front":"fields outside one’s own","meaning":"自己專業以外的領域","examples":[{"en":"He used ideas from fields outside his own.","zh":"他使用了來自自己專業以外領域的想法。"},{"en":"Fields outside one’s own are areas of knowledge or work beyond a person’s main specialty.","zh":"fields outside one’s own 指某人主要專長以外的知識或工作範圍。"},{"en":"A doctor may learn from design, a field outside her own, to improve hospital signs.","zh":"醫生可能向設計這個自己專業以外的領域學習，以改善醫院標示。"},{"en":"Using ideas from fields outside one’s own can create solutions that one discipline alone may miss.","zh":"使用自己專業以外領域的想法，可以創造單一學科可能錯過的解決方法。"},{"en":"This phrase highlights cross-disciplinary learning.","zh":"這個短語強調跨學科學習。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":3},{"front":"draw on tools from","meaning":"借助來自……的工具","examples":[{"en":"Wiggins drew on tools from artificial intelligence.","zh":"Wiggins 借助了來自人工智能的工具。"},{"en":"To draw on tools from a field means to use its methods, skills, or resources.","zh":"draw on tools from a field 指使用某領域的方法、技能或資源。"},{"en":"A teacher may draw on tools from psychology to understand student motivation.","zh":"老師可能借助來自心理學的工具來理解學生動機。"},{"en":"Researchers draw on tools from statistics when they need to find patterns in data.","zh":"當研究人員需要在數據中找模式時，會借助統計學工具。"},{"en":"This phrase shows borrowing useful methods from another area.","zh":"這個短語表示從另一領域借用有用方法。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":4},{"front":"a branch of","meaning":"……的一個分支","examples":[{"en":"Machine learning is a branch of artificial intelligence.","zh":"機器學習是人工智能的一個分支。"},{"en":"A branch of a subject is one part or area within a larger field.","zh":"a branch of a subject 指較大領域中的一個部分或範圍。"},{"en":"Grammar is a branch of language study that focuses on sentence structure.","zh":"文法是語言研究的一個分支，著重句子結構。"},{"en":"Knowing which branch of a field something belongs to helps students organise knowledge.","zh":"知道某事屬於哪個領域分支，可以幫助學生整理知識。"},{"en":"This phrase is used for classification inside a broader subject.","zh":"這個短語用於較大學科內部的分類。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":4},{"front":"artificial intelligence","meaning":"人工智能","examples":[{"en":"Artificial intelligence provided tools for modelling biological data.","zh":"人工智能提供了為生物數據建立模型的工具。"},{"en":"Artificial intelligence is computer technology that can perform tasks usually linked to human thinking.","zh":"artificial intelligence 指能執行通常與人類思考相關任務的電腦技術。"},{"en":"A phone uses artificial intelligence when it recognises speech or suggests words.","zh":"手機識別語音或建議文字時，就是使用人工智能。"},{"en":"Artificial intelligence can help scientists find patterns in data too large for humans to inspect manually.","zh":"人工智能可以幫助科學家在過大、難以人工檢查的數據中找出模式。"},{"en":"This phrase refers to machine-based problem solving, not human intelligence itself.","zh":"這個短語指基於機器的問題解決，而不是人類智能本身。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":4},{"front":"machine learning","meaning":"機器學習","examples":[{"en":"Machine learning helped Wiggins model gene activity.","zh":"機器學習幫助 Wiggins 為基因活動建立模型。"},{"en":"Machine learning is a method in which computers learn patterns from data instead of following only fixed instructions.","zh":"machine learning 指電腦從數據中學習模式，而不只是跟隨固定指令的方法。"},{"en":"Email services use machine learning to recognise spam messages.","zh":"電郵服務使用機器學習來識別垃圾郵件。"},{"en":"Machine learning becomes useful when data are too complex for simple rules.","zh":"當數據過於複雜，不能用簡單規則處理時，機器學習就變得有用。"},{"en":"This phrase focuses on learning from examples and improving predictions.","zh":"這個短語著重從例子中學習並改善預測。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":4},{"front":"model activity","meaning":"為活動建立模型","examples":[{"en":"The researchers used machine learning to model gene activity.","zh":"研究人員使用機器學習為基因活動建立模型。"},{"en":"To model activity means to create a simplified mathematical or computer representation of how something behaves.","zh":"model activity 指建立數學或電腦簡化表示，以呈現某事如何運作。"},{"en":"A city may model traffic activity to predict where jams will form.","zh":"城市可能為交通活動建立模型，以預測哪裡會出現擠塞。"},{"en":"Modelling activity helps researchers test ideas without watching every event directly.","zh":"為活動建立模型幫助研究人員測試想法，而不需要直接觀察每個事件。"},{"en":"This phrase shows that a complex process is being represented in a usable form.","zh":"這個短語表示複雜過程被轉化成可使用的表示形式。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":4},{"front":"collective protein-making activity","meaning":"集體蛋白質製造活動","examples":[{"en":"The model examined the collective protein-making activity of genes.","zh":"該模型研究基因的集體蛋白質製造活動。"},{"en":"Collective protein-making activity means the combined way many genes help produce proteins.","zh":"collective protein-making activity 指許多基因共同幫助製造蛋白質的方式。"},{"en":"In a classroom, group work is collective activity because many students contribute to one result.","zh":"在課室中，小組工作是集體活動，因為許多學生共同產生一個結果。"},{"en":"If many genes change their protein-making activity together, the cell’s behaviour may change.","zh":"如果許多基因一起改變其蛋白質製造活動，細胞行為可能改變。"},{"en":"This phrase focuses on genes acting as a group, not one gene alone.","zh":"這個短語著重基因作為群體行動，而不是單一基因。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":4},{"front":"real-world biological data","meaning":"真實世界的生物數據","examples":[{"en":"Wiggins applied machine learning to real-world biological data.","zh":"Wiggins 把機器學習應用於真實世界的生物數據。"},{"en":"Real-world biological data are measurements taken from actual living systems rather than made-up examples.","zh":"real-world biological data 指來自真實生命系統的量度，而不是虛構例子。"},{"en":"A hospital study using patient blood tests contains real-world biological data.","zh":"使用病人血液檢測的醫院研究包含真實世界的生物數據。"},{"en":"Real-world biological data can be messy, but they reflect what happens in actual organisms.","zh":"真實世界的生物數據可能混亂，但能反映實際生物中發生的情況。"},{"en":"This phrase contrasts laboratory-style examples with data from real biological situations.","zh":"這個短語把實驗室式例子與真實生物情境中的數據作對比。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":4},{"front":"be originally designed to","meaning":"原本被設計用來","examples":[{"en":"The tools were originally designed to predict output from input.","zh":"這些工具原本被設計用來從輸入預測輸出。"},{"en":"To be originally designed to do something means to be first created for that purpose.","zh":"be originally designed to do something 指最初被創造出來是為了某目的。"},{"en":"A school hall may be originally designed to hold assemblies, not concerts.","zh":"學校禮堂原本可能被設計用來舉行早會，而不是音樂會。"},{"en":"Tools originally designed for one field can later be useful in another field.","zh":"原本為一個領域設計的工具，後來可以在另一領域有用。"},{"en":"This phrase highlights the first intended use before later changes.","zh":"這個短語強調後來改變前的最初用途。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":4},{"front":"predict output from input","meaning":"從輸入預測輸出","examples":[{"en":"Engineers designed these tools to predict output from input.","zh":"工程師設計這些工具來從輸入預測輸出。"},{"en":"To predict output from input means to estimate a result based on the information given.","zh":"predict output from input 指根據提供的資料估計結果。"},{"en":"A weather app predicts tomorrow’s temperature from input such as pressure, wind, and humidity.","zh":"天氣應用程式根據氣壓、風和濕度等輸入預測明天氣溫。"},{"en":"If the input is poor or incomplete, the predicted output may be unreliable.","zh":"如果輸入質素差或不完整，預測輸出可能不可靠。"},{"en":"This phrase describes the basic logic behind many computer models.","zh":"這個短語描述許多電腦模型背後的基本邏輯。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":4},{"front":"bring something to","meaning":"將……帶入","examples":[{"en":"Wiggins brought machine learning to the natural sciences.","zh":"Wiggins 將機器學習帶入自然科學。"},{"en":"To bring something to a field means to introduce it into that area so people can use it there.","zh":"bring something to a field 指把某事物引入某領域，讓人們在那裡使用。"},{"en":"A teacher may bring storytelling to science lessons to make ideas easier to remember.","zh":"老師可能把講故事帶入科學課，使概念更易記。"},{"en":"Bringing new tools to a field can change the questions people are able to ask.","zh":"將新工具帶入一個領域，可以改變人們能提出的問題。"},{"en":"This phrase shows movement of an idea, method, or tool into a new context.","zh":"這個短語表示想法、方法或工具進入新背景。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":4},{"front":"the natural sciences","meaning":"自然科學","examples":[{"en":"Machine learning was brought into the natural sciences.","zh":"機器學習被帶入自然科學。"},{"en":"The natural sciences are fields that study the physical and living world, such as physics, chemistry, and biology.","zh":"natural sciences 指研究物理世界和生命世界的領域，例如物理、化學和生物。"},{"en":"Students study the natural sciences when they learn about cells, forces, rocks, and chemicals.","zh":"學生學習細胞、力、岩石和化學物質時，就是在學自然科學。"},{"en":"The natural sciences often use observation, experiments, and models to explain nature.","zh":"自然科學常使用觀察、實驗和模型來解釋自然。"},{"en":"This phrase contrasts science about nature with subjects such as history or literature.","zh":"這個短語把研究自然的科學與歷史或文學等科目作對比。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":5},{"front":"tweak","meaning":"微調；修改","examples":[{"en":"The researchers tweaked machine-learning tools for biological research.","zh":"研究人員為生物研究微調了機器學習工具。"},{"en":"To tweak something means to make small changes to improve or adapt it.","zh":"tweak something 指作出小改動，以改善或適應某事物。"},{"en":"A teacher may tweak a worksheet after noticing that students find one section too hard.","zh":"老師發現學生覺得某部分太難後，可能微調工作紙。"},{"en":"Small tweaks can make a tool work better in a new situation.","zh":"小幅微調可以令工具在新情況下運作得更好。"},{"en":"This verb suggests adjustment, not a complete redesign.","zh":"這個動詞表示調整，而不是完全重新設計。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":5},{"front":"tell a story","meaning":"說明背後的情況；呈現脈絡","examples":[{"en":"The model could tell a story about gene regulation.","zh":"該模型能說明基因調控背後的情況。"},{"en":"To tell a story in this context means to explain how events or parts are connected.","zh":"在這個語境中，tell a story 指解釋事件或部分如何互相連繫。"},{"en":"A chart can tell a story about why a shop loses customers after prices rise.","zh":"圖表可以說明為何商店加價後失去顧客的情況。"},{"en":"A good model tells a story by showing not only what happens, but why it happens.","zh":"好模型會呈現脈絡，不只顯示發生甚麼，還顯示為何發生。"},{"en":"This phrase does not mean fiction; it means making patterns meaningful.","zh":"這個短語不是指小說故事，而是令模式變得有意義。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":5},{"front":"not only about…but also about","meaning":"不只是關於……也是關於……","examples":[{"en":"The model was not only about input and output but also about internal mechanisms.","zh":"該模型不只是關於輸入和輸出，也是關於內部機制。"},{"en":"Not only about…but also about shows that two ideas are both important.","zh":"not only about…but also about 表示兩個想法同樣重要。"},{"en":"Good teaching is not only about exam results but also about confidence and understanding.","zh":"好教學不只是關於考試成績，也是關於信心和理解。"},{"en":"A health plan is not only about diet but also about sleep, exercise, and stress.","zh":"健康計劃不只是關於飲食，也是關於睡眠、運動和壓力。"},{"en":"This phrase adds a second focus and makes the meaning broader.","zh":"這個短語加入第二個焦點，令意思更廣。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":5},{"front":"gene regulation","meaning":"基因調控","examples":[{"en":"The model helped explain what happens inside gene regulation.","zh":"該模型幫助解釋基因調控內部發生的事情。"},{"en":"Gene regulation is the process that controls when, where, and how strongly genes are used.","zh":"gene regulation 指控制基因何時、何地以及以多強程度被使用的過程。"},{"en":"In a school analogy, gene regulation is like deciding which instructions a team should follow at a certain time.","zh":"用學校比喻，基因調控就像決定團隊在某時刻應跟隨哪些指令。"},{"en":"If gene regulation changes, a cell may produce different proteins or behave differently.","zh":"如果基因調控改變，細胞可能製造不同蛋白質或有不同行為。"},{"en":"This phrase focuses on control of gene activity, not simply the presence of genes.","zh":"這個短語著重基因活動的控制，而不只是基因是否存在。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":5},{"front":"the black box","meaning":"黑箱；未知的內部過程","examples":[{"en":"Machine learning helped examine the black box between input and output.","zh":"機器學習幫助研究輸入和輸出之間的黑箱。"},{"en":"The black box is an unknown internal process whose inputs and outputs can be seen but whose inner workings are unclear.","zh":"black box 指一個未知內部過程，人們能看見輸入和輸出，但不清楚內部如何運作。"},{"en":"A student may know that a calculator gives the right answer but not understand the black box inside it.","zh":"學生可能知道計算機給出正確答案，但不理解其內部黑箱。"},{"en":"Opening the black box helps people understand why a result happens, not just what the result is.","zh":"打開黑箱幫助人理解結果為何發生，而不只是結果是甚麼。"},{"en":"This phrase is useful when a system works but its hidden process is difficult to see.","zh":"當系統能運作但隱藏過程難以看見時，這個短語很有用。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":5},{"front":"in between","meaning":"介乎兩者之間","examples":[{"en":"The researchers studied the black box in between input and output.","zh":"研究人員研究輸入和輸出之間的黑箱。"},{"en":"In between means in the middle of two things, stages, or positions.","zh":"in between 指位於兩件事、兩個階段或兩個位置之間。"},{"en":"A student may have lunch in between two lessons.","zh":"學生可能在兩堂課之間吃午餐。"},{"en":"The steps in between a question and an answer often show how the answer was reached.","zh":"問題和答案之間的步驟常顯示答案如何得出。"},{"en":"This phrase focuses on what lies between a beginning and an end.","zh":"這個短語著重起點和終點之間的東西。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":5},{"front":"the impetus for","meaning":"……的推動力","examples":[{"en":"The impetus for this work began in the late 1990s.","zh":"這項工作的推動力始於九十年代末。"},{"en":"The impetus for something is the force, reason, or event that pushes it to begin or develop.","zh":"impetus for something 指推動某事開始或發展的力量、原因或事件。"},{"en":"A serious accident may provide the impetus for new road safety rules.","zh":"嚴重意外可能成為新道路安全規則的推動力。"},{"en":"New technology can be the impetus for changes in how teachers teach.","zh":"新科技可以成為教師教學方式改變的推動力。"},{"en":"This phrase explains what started or accelerated a process.","zh":"這個短語解釋某過程是由甚麼開始或加速。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":5},{"front":"high-throughput techniques","meaning":"高通量技術","examples":[{"en":"High-throughput techniques generated huge amounts of genetic data.","zh":"高通量技術產生了大量遺傳數據。"},{"en":"High-throughput techniques are methods that process or measure many samples quickly and at large scale.","zh":"high-throughput techniques 指快速、大規模處理或量度大量樣本的方法。"},{"en":"A laboratory uses high-throughput techniques when it tests thousands of samples in a short time.","zh":"當實驗室在短時間內檢測數千個樣本時，就是使用高通量技術。"},{"en":"These techniques create large datasets, so scientists need computers to analyse the results.","zh":"這些技術創造大型數據集，因此科學家需要電腦分析結果。"},{"en":"This phrase suggests speed, scale, and repeated measurement.","zh":"這個短語表示速度、規模和重複量度。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":5},{"front":"generate","meaning":"產生","examples":[{"en":"New techniques generated more biological data than ever before.","zh":"新技術產生了比以往任何時候都多的生物數據。"},{"en":"To generate something means to produce or create it.","zh":"generate something 指產生或創造某物。"},{"en":"A school survey can generate useful information about students’ study habits.","zh":"學校問卷可以產生關於學生學習習慣的有用資訊。"},{"en":"Machines that generate large amounts of data also create a need for better analysis.","zh":"產生大量數據的機器也會創造更好分析方法的需要。"},{"en":"This verb often connects a method or process with the output it produces.","zh":"這個動詞常把方法或過程與其產生的輸出連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":5},{"front":"mRNA expression profiles","meaning":"mRNA表達譜","examples":[{"en":"Scientists generated many mRNA expression profiles.","zh":"科學家產生了許多 mRNA 表達譜。"},{"en":"mRNA expression profiles are records showing the levels of mRNA produced by many genes under certain conditions.","zh":"mRNA expression profiles 指顯示許多基因在特定條件下產生多少 mRNA 的記錄。"},{"en":"A researcher may compare mRNA expression profiles from healthy and diseased cells.","zh":"研究人員可能比較健康細胞和患病細胞的 mRNA 表達譜。"},{"en":"These profiles help scientists see which genes become more or less active.","zh":"這些表達譜幫助科學家看見哪些基因變得更活躍或較不活躍。"},{"en":"This phrase refers to patterns of gene activity recorded through mRNA levels.","zh":"這個短語指透過 mRNA 水平記錄的基因活動模式。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":6},{"front":"DNA sequences","meaning":"DNA序列","examples":[{"en":"High-throughput techniques produced many DNA sequences.","zh":"高通量技術產生了許多 DNA 序列。"},{"en":"DNA sequences are the ordered patterns of genetic letters in DNA.","zh":"DNA sequences 指 DNA 中遺傳字母的排列次序。"},{"en":"A biology class may compare short DNA sequences to see how two organisms differ.","zh":"生物課可能比較短 DNA 序列，以觀察兩種生物有何不同。"},{"en":"Changes in DNA sequences can affect how proteins are made.","zh":"DNA 序列的變化可以影響蛋白質如何被製造。"},{"en":"This phrase focuses on the order of genetic information, not just the amount of DNA.","zh":"這個短語著重遺傳資訊的次序，而不只是 DNA 的數量。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":6},{"front":"than ever before","meaning":"比以往任何時候都","examples":[{"en":"Researchers had more genetic data than ever before.","zh":"研究人員擁有比以往任何時候都多的遺傳數據。"},{"en":"Than ever before means more than at any earlier time.","zh":"than ever before 指比過去任何時候都更多。"},{"en":"Students today have access to more online learning materials than ever before.","zh":"今天的學生能接觸比以往任何時候都多的網上學習材料。"},{"en":"When people have more data than ever before, they also need better ways to organise it.","zh":"當人們擁有比以往任何時候都多的數據，也需要更好的整理方法。"},{"en":"This phrase emphasises a historical increase.","zh":"這個短語強調歷史上的增加。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":6},{"front":"open up","meaning":"開啟；打開","examples":[{"en":"These techniques opened up a new way of thinking about biology.","zh":"這些技術開啟了一種思考生物學的新方式。"},{"en":"To open up something means to make a new possibility, opportunity, or area available.","zh":"open up something 指使新的可能性、機會或領域變得可用。"},{"en":"Learning English can open up study and work opportunities abroad.","zh":"學習英語可以打開海外升學和工作機會。"},{"en":"New tools open up new questions because people can now see things they missed before.","zh":"新工具開啟新問題，因為人們現在能看見以前錯過的東西。"},{"en":"This phrase often suggests that a closed door has become accessible.","zh":"這個短語常表示原本關閉的門變得可以進入。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":6},{"front":"a completely different way of thinking","meaning":"一種完全不同的思考方式","examples":[{"en":"The new data opened up a completely different way of thinking.","zh":"新數據開啟了一種完全不同的思考方式。"},{"en":"A completely different way of thinking is a new approach that changes how people understand a problem.","zh":"completely different way of thinking 指改變人們理解問題方式的新取向。"},{"en":"A teacher may introduce a completely different way of thinking about mistakes as chances to learn.","zh":"老師可能介紹一種完全不同的思考方式，把錯誤視為學習機會。"},{"en":"New evidence can force people to use a completely different way of thinking.","zh":"新證據可以迫使人們使用一種完全不同的思考方式。"},{"en":"This phrase suggests a major shift, not a small adjustment.","zh":"這個短語表示重大轉變，而不是小調整。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":6},{"front":"biological phenomena","meaning":"生物現象","examples":[{"en":"Scientists began to think differently about biological phenomena.","zh":"科學家開始以不同方式思考生物現象。"},{"en":"Biological phenomena are events or processes that happen in living organisms.","zh":"biological phenomena 指發生在生物體中的事件或過程。"},{"en":"Growth, ageing, disease, and reproduction are biological phenomena.","zh":"生長、衰老、疾病和繁殖都是生物現象。"},{"en":"Studying biological phenomena helps scientists understand how life works.","zh":"研究生物現象幫助科學家理解生命如何運作。"},{"en":"This phrase is formal and refers to observable processes in biology.","zh":"這個短語較正式，指生物學中可觀察的過程。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":6},{"front":"key among","meaning":"其中最重要的是","examples":[{"en":"Key among these techniques were DNA microarrays.","zh":"在這些技術中，其中最重要的是 DNA 微陣列。"},{"en":"Key among a group means one of the most important items within that group.","zh":"key among a group 指某物是該組中最重要的項目之一。"},{"en":"Key among the school’s problems is the lack of qualified teachers.","zh":"在學校的問題中，其中最重要的是缺乏合資格教師。"},{"en":"When one factor is key among many, it deserves special attention.","zh":"當一個因素在眾多因素中最重要，它就值得特別注意。"},{"en":"This phrase highlights the most important member of a larger set.","zh":"這個短語突出較大集合中最重要的成員。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":6},{"front":"DNA microarrays","meaning":"DNA微陣列","examples":[{"en":"DNA microarrays gave scientists a broad view of gene activity.","zh":"DNA 微陣列讓科學家廣泛觀察基因活動。"},{"en":"DNA microarrays are laboratory tools used to measure the activity of many genes at the same time.","zh":"DNA microarrays 是用來同時量度許多基因活動的實驗室工具。"},{"en":"A researcher may use DNA microarrays to compare gene activity in two types of cells.","zh":"研究人員可能使用 DNA 微陣列比較兩種細胞中的基因活動。"},{"en":"DNA microarrays helped biology move from studying one gene to studying many genes together.","zh":"DNA 微陣列幫助生物學從研究單一基因轉向一起研究許多基因。"},{"en":"This phrase refers to a technology for large-scale gene measurement.","zh":"這個短語指大規模基因量度技術。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":6},{"front":"provide a panoramic view of","meaning":"提供……的全景式視野","examples":[{"en":"Microarrays provide a panoramic view of gene activity.","zh":"微陣列提供基因活動的全景式視野。"},{"en":"To provide a panoramic view of something means to give a wide, overall picture of it.","zh":"provide a panoramic view of something 指提供某事的廣闊整體圖像。"},{"en":"A school report can provide a panoramic view of attendance, grades, and student wellbeing.","zh":"學校報告可以提供出席率、成績和學生福祉的全景式視野。"},{"en":"A panoramic view helps people see patterns that are invisible in small details.","zh":"全景式視野幫助人們看見小細節中看不到的模式。"},{"en":"This phrase suggests broad coverage rather than a narrow close-up.","zh":"這個短語表示廣泛涵蓋，而不是狹窄特寫。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":6},{"front":"activity of genes","meaning":"基因活動","examples":[{"en":"DNA microarrays show the activity of genes in cells.","zh":"DNA 微陣列顯示細胞中的基因活動。"},{"en":"The activity of genes means how active genes are in producing RNA or affecting cell processes.","zh":"activity of genes 指基因在產生 RNA 或影響細胞過程方面有多活躍。"},{"en":"Scientists may measure the activity of genes after a cell is exposed to heat or medicine.","zh":"科學家可能量度細胞接觸高溫或藥物後的基因活動。"},{"en":"Changes in the activity of genes can change what proteins a cell makes.","zh":"基因活動的變化可以改變細胞製造哪些蛋白質。"},{"en":"This phrase focuses on gene use, not merely gene presence.","zh":"這個短語著重基因的使用，而不只是基因存在。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":6},{"front":"expression levels","meaning":"表達水平","examples":[{"en":"Microarrays measure the expression levels of genes.","zh":"微陣列量度基因的表達水平。"},{"en":"Expression levels show how strongly or weakly genes are being used to produce RNA.","zh":"expression levels 顯示基因被用來產生 RNA 的強弱程度。"},{"en":"A scientist may compare expression levels before and after a drug treatment.","zh":"科學家可能比較藥物處理前後的表達水平。"},{"en":"High expression levels can suggest that a gene is very active in a cell.","zh":"高表達水平可能表示某基因在細胞中非常活躍。"},{"en":"This phrase gives a measurable way to discuss gene activity.","zh":"這個短語提供一種可量度方式來討論基因活動。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":7},{"front":"cell type","meaning":"細胞類型","examples":[{"en":"Gene expression can be studied in any cell type.","zh":"基因表達可以在任何細胞類型中研究。"},{"en":"A cell type is a category of cells with a particular structure or function.","zh":"cell type 指具有特定結構或功能的細胞類別。"},{"en":"Nerve cells, blood cells, and muscle cells are different cell types.","zh":"神經細胞、血細胞和肌肉細胞都是不同細胞類型。"},{"en":"Different cell types use different genes, so their behaviour and roles differ.","zh":"不同細胞類型使用不同基因，因此行為和角色不同。"},{"en":"This phrase helps classify cells by what they are and what they do.","zh":"這個短語幫助根據細胞是甚麼和做甚麼來分類。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":7},{"front":"simultaneously","meaning":"同時地","examples":[{"en":"Microarrays measure many genes simultaneously.","zh":"微陣列同時量度許多基因。"},{"en":"Simultaneously means at the same time.","zh":"simultaneously 指在同一時間。"},{"en":"A teacher cannot easily answer ten students’ questions simultaneously.","zh":"老師難以同時回答十名學生的問題。"},{"en":"Measuring many things simultaneously saves time and shows how they change together.","zh":"同時量度許多事物可以節省時間，並顯示它們如何一起變化。"},{"en":"This word is useful when several actions happen at once.","zh":"當幾個動作同時發生時，這個詞很有用。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":7},{"front":"under myriad conditions","meaning":"在無數條件下","examples":[{"en":"Researchers can study gene activity under myriad conditions.","zh":"研究人員可以在無數條件下研究基因活動。"},{"en":"Under myriad conditions means in a very large number of different situations.","zh":"under myriad conditions 指在非常多不同情況下。"},{"en":"A phone app should be tested under myriad conditions, such as weak signal, low battery, and heavy use.","zh":"手機應用程式應在無數條件下測試，例如訊號弱、電量低和大量使用。"},{"en":"Studying cells under many conditions helps reveal which rules stay stable.","zh":"在許多條件下研究細胞，有助揭示哪些規則保持穩定。"},{"en":"This phrase emphasises variety and large numbers of conditions.","zh":"這個短語強調條件的多樣性和數量龐大。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":7},{"front":"as noisy and incomplete as","meaning":"儘管……嘈雜且不完整","examples":[{"en":"As noisy and incomplete as the data were, they were still useful.","zh":"儘管數據嘈雜且不完整，它們仍然有用。"},{"en":"As noisy and incomplete as something is means although it contains errors, gaps, or confusion.","zh":"as noisy and incomplete as something is 指儘管某物包含錯誤、空缺或混亂。"},{"en":"As messy and incomplete as a student’s notes are, they may still help before an exam.","zh":"儘管學生筆記凌亂且不完整，考試前仍可能有幫助。"},{"en":"Noisy data can still reveal patterns if researchers use careful methods.","zh":"嘈雜數據如果用仔細方法處理，仍可以揭示模式。"},{"en":"This phrase balances a weakness with a positive result.","zh":"這個短語把弱點與正面結果放在一起。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":7},{"front":"query","meaning":"查詢；探問","examples":[{"en":"Biologists could query which genes turn on or off.","zh":"生物學家可以查詢哪些基因開啟或關閉。"},{"en":"To query something means to ask a question about it or search for specific information.","zh":"query something 指詢問某事或搜尋特定資訊。"},{"en":"A student may query a database to find books about climate change.","zh":"學生可能查詢資料庫，尋找關於氣候變化的書。"},{"en":"When scientists query large datasets, they can find patterns that manual reading would miss.","zh":"當科學家查詢大型數據集時，可以找到人工閱讀會錯過的模式。"},{"en":"This verb is common when using computers to search data.","zh":"這個動詞常用於使用電腦搜尋數據時。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":7},{"front":"turn on or off","meaning":"開啟或關閉","examples":[{"en":"Biologists could identify which genes turn on or off in different cells.","zh":"生物學家可以識別不同細胞中哪些基因開啟或關閉。"},{"en":"When genes turn on or off, they become active or inactive.","zh":"當基因 turn on or off，意思是它們變得活躍或不活躍。"},{"en":"A classroom light can turn on or off, and genes can be described in a similar control sense.","zh":"課室燈可以開啟或關閉，基因也可以用類似控制概念來描述。"},{"en":"If a gene turns on, it may begin producing RNA that affects the cell.","zh":"如果某基因開啟，它可能開始產生影響細胞的 RNA。"},{"en":"This phrase uses a simple switch image to explain gene activity.","zh":"這個短語用簡單的開關意象來解釋基因活動。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":7},{"front":"determine the collection of","meaning":"確定……的集合","examples":[{"en":"Scientists could determine the collection of proteins in a cell.","zh":"科學家可以確定細胞中的蛋白質集合。"},{"en":"To determine the collection of something means to identify the full set or group present.","zh":"determine the collection of something 指識別存在的完整集合或群組。"},{"en":"A librarian may determine the collection of books needed for a new reading corner.","zh":"圖書館員可能確定新閱讀角需要的書籍集合。"},{"en":"Determining the collection of proteins helps scientists understand what a cell can do.","zh":"確定蛋白質集合幫助科學家理解細胞能做甚麼。"},{"en":"This phrase focuses on identifying a complete group, not one item.","zh":"這個短語著重識別完整群組，而不是單一項目。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":7},{"front":"give rise to","meaning":"產生；導致","examples":[{"en":"Proteins give rise to a cell’s characteristic features.","zh":"蛋白質產生細胞的特徵。"},{"en":"To give rise to something means to cause it to happen or appear.","zh":"give rise to something 指導致某事發生或出現。"},{"en":"Poor road design can give rise to traffic accidents.","zh":"差劣道路設計可以導致交通意外。"},{"en":"Different proteins can give rise to different cell shapes and functions.","zh":"不同蛋白質可以產生不同細胞形狀和功能。"},{"en":"This phrase is formal and often links causes with results.","zh":"這個短語較正式，常把原因與結果連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":7},{"front":"characteristic features","meaning":"特徵","examples":[{"en":"The proteins influence a cell’s characteristic features.","zh":"蛋白質影響細胞的特徵。"},{"en":"Characteristic features are qualities that make something recognisable or different from others.","zh":"characteristic features 指使某事物可被辨認或不同於其他事物的特質。"},{"en":"A school’s characteristic features may include small classes and strong language support.","zh":"學校的特徵可能包括小班教學和強大語言支援。"},{"en":"In cells, characteristic features may come from which proteins are made.","zh":"在細胞中，特徵可能來自哪些蛋白質被製造。"},{"en":"This phrase focuses on identifying traits.","zh":"這個短語著重識別特質。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":7},{"front":"healthy or diseased","meaning":"健康或患病的","examples":[{"en":"Gene activity may differ between healthy or diseased cells.","zh":"健康或患病細胞之間的基因活動可能不同。"},{"en":"Healthy or diseased means either functioning normally or affected by illness.","zh":"healthy or diseased 指功能正常或受到疾病影響。"},{"en":"Doctors compare healthy and diseased tissue to understand what has changed.","zh":"醫生比較健康和患病組織，以了解甚麼發生了變化。"},{"en":"If gene activity differs between healthy and diseased cells, it may help explain a condition.","zh":"如果健康和患病細胞之間的基因活動不同，可能有助解釋某疾病。"},{"en":"This phrase creates a contrast between normal and illness-related states.","zh":"這個短語在正常狀態和疾病相關狀態之間建立對比。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":8},{"front":"predict gene activity","meaning":"預測基因活動","examples":[{"en":"Predicting gene activity requires finding the rules that govern it.","zh":"預測基因活動需要找出支配它的規則。"},{"en":"To predict gene activity means to estimate which genes will become active or inactive under certain conditions.","zh":"predict gene activity 指估計哪些基因會在特定條件下變得活躍或不活躍。"},{"en":"Scientists may try to predict gene activity after a cell receives a drug.","zh":"科學家可能嘗試預測細胞接受藥物後的基因活動。"},{"en":"Better prediction can help researchers understand how cells respond to stress or disease.","zh":"更好的預測可以幫助研究人員理解細胞如何回應壓力或疾病。"},{"en":"This phrase connects future behaviour with biological rules.","zh":"這個短語把未來行為與生物規則連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":8},{"front":"require uncovering","meaning":"需要揭示","examples":[{"en":"Predicting gene activity requires uncovering basic biological rules.","zh":"預測基因活動需要揭示基本生物規則。"},{"en":"To require uncovering something means to need hidden information to be discovered first.","zh":"require uncovering something 指需要先發現隱藏資訊。"},{"en":"Solving repeated absences may require uncovering problems at home or on the journey to school.","zh":"解決學生反覆缺席問題，可能需要揭示家庭或上學路程中的問題。"},{"en":"A complex disease may require uncovering several causes before treatment improves.","zh":"複雜疾病可能需要揭示多個原因，治療才會改善。"},{"en":"This phrase shows that discovery is necessary before progress can happen.","zh":"這個短語表示在取得進展前必須先發現某些東西。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":8},{"front":"fundamental rules","meaning":"基本規則","examples":[{"en":"Scientists wanted to uncover the fundamental rules of gene activity.","zh":"科學家想揭示基因活動的基本規則。"},{"en":"Fundamental rules are basic principles that explain how a system works.","zh":"fundamental rules 指解釋一個系統如何運作的基本原則。"},{"en":"In grammar, subject-verb agreement is one fundamental rule students must learn.","zh":"在文法中，主謂一致是學生必須學習的一條基本規則。"},{"en":"Knowing fundamental rules helps people predict what may happen in new situations.","zh":"了解基本規則幫助人們預測新情況中可能發生甚麼。"},{"en":"This phrase points to deep basic principles, not small details.","zh":"這個短語指深層基本原則，而不是小細節。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":8},{"front":"govern","meaning":"支配；控制","examples":[{"en":"These rules govern gene activity.","zh":"這些規則支配基因活動。"},{"en":"To govern something means to control, guide, or determine how it works.","zh":"govern something 指控制、引導或決定某事如何運作。"},{"en":"School rules govern how students use classrooms, phones, and common areas.","zh":"校規控制學生如何使用課室、手機和公共空間。"},{"en":"If hidden rules govern a system, understanding them helps people predict its behaviour.","zh":"如果隱藏規則支配某系統，理解它們有助人們預測系統行為。"},{"en":"This verb is often used for rules, laws, or principles that control actions.","zh":"這個動詞常用於控制行動的規則、法律或原則。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":8},{"front":"over time","meaning":"隨時間推移","examples":[{"en":"Gene and protein activity changes over time.","zh":"基因和蛋白質活動會隨時間推移而改變。"},{"en":"Over time means gradually as time passes.","zh":"over time 指隨著時間過去而逐漸發生。"},{"en":"A student’s writing improves over time with regular feedback.","zh":"學生的寫作會在定期回饋下隨時間推移而進步。"},{"en":"Small changes over time can become large differences later.","zh":"隨時間推移的小變化，之後可以變成巨大差異。"},{"en":"This phrase focuses on gradual development, not instant change.","zh":"這個短語著重逐漸發展，而不是即時變化。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":8},{"front":"be locked in by","meaning":"被……固定下來","examples":[{"en":"Useful biological rules have been locked in by cells.","zh":"有用的生物規則已被細胞固定下來。"},{"en":"To be locked in by something means to be fixed, preserved, or strongly maintained by it.","zh":"be locked in by something 指被某事固定、保留或強力維持。"},{"en":"A family habit can be locked in by years of repeating the same routine.","zh":"家庭習慣可以因多年重複同一規律而被固定下來。"},{"en":"Biological rules that help survival may be locked in by evolution over many generations.","zh":"有助生存的生物規則可能經過許多世代被進化固定下來。"},{"en":"This phrase suggests that something becomes difficult to change.","zh":"這個短語表示某事變得難以改變。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":8},{"front":"evolution has kept","meaning":"進化保留下來","examples":[{"en":"Evolution has kept the useful biological rules.","zh":"進化保留下了有用的生物規則。"},{"en":"Evolution has kept something means natural selection has preserved it because it helps organisms survive or reproduce.","zh":"evolution has kept something 指自然選擇因某物有助生物生存或繁殖而保留它。"},{"en":"Evolution has kept certain warning colours because they help animals avoid danger.","zh":"進化保留了某些警告顏色，因為它們幫助動物避開危險。"},{"en":"If a biological rule is useful, evolution may keep it across many generations.","zh":"如果某生物規則有用，進化可能在許多世代中保留下來。"},{"en":"This phrase links survival value with long-term preservation.","zh":"這個短語把生存價值與長期保留連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":8},{"front":"infer the interaction between","meaning":"推斷……之間的相互作用","examples":[{"en":"Statistics helped scientists infer the interaction between genes and proteins.","zh":"統計學幫助科學家推斷基因和蛋白質之間的相互作用。"},{"en":"To infer the interaction between things means to work out how they affect one another from evidence.","zh":"infer the interaction between things 指根據證據推斷事物如何互相影響。"},{"en":"A teacher may infer the interaction between sleep and test scores by comparing student data.","zh":"老師可能透過比較學生數據，推斷睡眠與考試成績之間的相互作用。"},{"en":"Scientists infer interactions when direct observation is difficult or impossible.","zh":"當直接觀察困難或不可能時，科學家會推斷相互作用。"},{"en":"This phrase shows reasoning from data, not simply guessing.","zh":"這個短語表示根據數據推理，而不是單純猜測。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":8},{"front":"regulate","meaning":"調控","examples":[{"en":"Proteins can regulate the activity of genes.","zh":"蛋白質可以調控基因活動。"},{"en":"To regulate something means to control or adjust how it works.","zh":"regulate something 指控制或調整某事如何運作。"},{"en":"A thermostat regulates room temperature by turning heating on and off.","zh":"恆溫器透過開關暖氣來調控室溫。"},{"en":"If proteins regulate genes, they help decide when those genes become active.","zh":"如果蛋白質調控基因，它們幫助決定那些基因何時變得活躍。"},{"en":"This verb is about control, balance, and adjustment.","zh":"這個動詞關乎控制、平衡和調整。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":8},{"front":"mathematically describe","meaning":"以數學方式描述","examples":[{"en":"Scientists wanted to mathematically describe the network’s structure.","zh":"科學家想以數學方式描述該網絡的結構。"},{"en":"To mathematically describe something means to explain it using numbers, equations, or formal models.","zh":"mathematically describe something 指用數字、方程式或正式模型解釋某事。"},{"en":"Engineers mathematically describe traffic flow to predict where roads will become crowded.","zh":"工程師以數學方式描述交通流量，以預測道路哪裡會擠塞。"},{"en":"A mathematical description can make a complex system easier to test and compare.","zh":"數學描述可以令複雜系統更容易測試和比較。"},{"en":"This phrase shows that an idea is being turned into a precise model.","zh":"這個短語顯示某個想法正被轉化成精確模型。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":9},{"front":"underlying structure","meaning":"底層結構","examples":[{"en":"The researchers studied the network’s underlying structure.","zh":"研究人員研究該網絡的底層結構。"},{"en":"Underlying structure is the hidden arrangement or organisation beneath what we can see.","zh":"underlying structure 指可見表面之下隱藏的安排或組織。"},{"en":"A teacher may study the underlying structure of a student’s essay, not just the grammar mistakes.","zh":"老師可能研究學生文章的底層結構，而不只是文法錯誤。"},{"en":"Understanding underlying structure helps people explain why a system behaves as it does.","zh":"理解底層結構幫助人們解釋系統為何如此運作。"},{"en":"This phrase points to deeper organisation rather than surface details.","zh":"這個短語指更深層組織，而不是表面細節。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":9},{"front":"dynamic pattern","meaning":"動態模式","examples":[{"en":"The model described the dynamic pattern of gene and protein activity.","zh":"該模型描述了基因和蛋白質活動的動態模式。"},{"en":"A dynamic pattern is a pattern that changes over time rather than staying fixed.","zh":"dynamic pattern 指會隨時間改變，而不是保持固定的模式。"},{"en":"A teacher may notice a dynamic pattern in class mood across the school day.","zh":"老師可能注意到課堂氣氛在一天中有動態模式。"},{"en":"Dynamic patterns help scientists understand when activity rises, falls, or shifts.","zh":"動態模式幫助科學家理解活動何時上升、下降或轉移。"},{"en":"This phrase combines repeated structure with movement and change.","zh":"這個短語結合重複結構、移動和變化。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":9},{"front":"particles","meaning":"粒子","examples":[{"en":"Some physicists worked with particles rather than biological systems.","zh":"有些物理學家研究粒子，而不是生物系統。"},{"en":"Particles are extremely small pieces of matter, such as electrons or atoms.","zh":"particles 指極小的物質單位，例如電子或原子。"},{"en":"In science class, students may learn that air is made of tiny particles.","zh":"在科學課上，學生可能學到空氣由微小粒子構成。"},{"en":"Studying particles helps physicists understand matter at a very small scale.","zh":"研究粒子幫助物理學家理解非常微小尺度上的物質。"},{"en":"This word refers to tiny physical units, not large living systems.","zh":"這個詞指微小物理單位，而不是大型生命系統。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":9},{"front":"for that matter","meaning":"就此而言；同樣地","examples":[{"en":"Some physicists did not work with particles or planets, for that matter.","zh":"有些物理學家不研究粒子，就此而言，也不研究行星。"},{"en":"For that matter is used to add another related example or make a statement broader.","zh":"for that matter 用來加入另一個相關例子，或令說法更廣。"},{"en":"The rule applies to students and teachers, for that matter.","zh":"這條規則適用於學生，就此而言，也適用於老師。"},{"en":"If the plan is unclear, parents, staff, and visitors, for that matter, may feel confused.","zh":"如果計劃不清楚，家長、員工，同樣地，訪客也可能感到困惑。"},{"en":"This phrase often adds an extra point after the main point has been made.","zh":"這個短語常在主要觀點提出後加入額外一點。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":9},{"front":"view something as","meaning":"將……視為","examples":[{"en":"Some physicists viewed statistics as anathema.","zh":"有些物理學家將統計學視為極其厭惡之物。"},{"en":"To view something as something means to consider or judge it in that way.","zh":"view something as something 指把某事物看作或判斷為某種東西。"},{"en":"Some students view mistakes as failure, while others view them as feedback.","zh":"有些學生將錯誤視為失敗，而另一些則將它們視為回饋。"},{"en":"How people view a problem affects the solution they choose.","zh":"人們如何看待問題會影響他們選擇的解決方法。"},{"en":"This phrase focuses on attitude or interpretation.","zh":"這個短語著重態度或詮釋。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":9},{"front":"nothing short of","meaning":"簡直是；完全是","examples":[{"en":"Statistics seemed nothing short of anathema to some physicists.","zh":"對有些物理學家而言，統計學簡直是禁忌。"},{"en":"Nothing short of something means completely or almost exactly that thing, often in a strong sense.","zh":"nothing short of something 指完全或幾乎就是某事，語氣通常很強。"},{"en":"For a tired nurse, an extra day off may feel nothing short of a gift.","zh":"對疲倦護士而言，多一天假期可能簡直是一份禮物。"},{"en":"Calling something nothing short of a disaster shows very strong judgement.","zh":"稱某事 nothing short of a disaster 表示非常強烈的判斷。"},{"en":"This phrase intensifies the description that follows it.","zh":"這個短語強化後面的描述。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":9},{"front":"anathema","meaning":"極其厭惡之物；禁忌","examples":[{"en":"Some physicists regarded statistics as anathema.","zh":"有些物理學家把統計學視為極其厭惡之物。"},{"en":"Anathema is something that a person or group strongly dislikes or rejects.","zh":"anathema 指某人或某群體強烈不喜歡或拒絕的事物。"},{"en":"For a strict health coach, smoking may be anathema.","zh":"對嚴格健康教練而言，吸煙可能是極其厭惡之物。"},{"en":"If a method is treated as anathema, people may refuse to consider it even when it is useful.","zh":"如果一種方法被視為禁忌，人們即使它有用也可能拒絕考慮。"},{"en":"This word is formal and carries a very strong negative feeling.","zh":"這個詞較正式，帶有非常強烈的負面感覺。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":9},{"front":"ought to have done","meaning":"本應做","examples":[{"en":"Rutherford said that if an experiment required statistics, one ought to have done a better experiment.","zh":"Rutherford 說，如果一個實驗需要統計學，一個人本應做一個更好的實驗。"},{"en":"Ought to have done something means someone should have done it in the past but did not.","zh":"ought to have done something 指某人過去本應做某事，但沒有做。"},{"en":"A student who fails because of careless mistakes ought to have checked the paper more carefully.","zh":"因粗心錯誤而失敗的學生，本應更仔細檢查試卷。"},{"en":"This phrase can express regret, criticism, or a missed duty.","zh":"這個短語可以表達後悔、批評或錯過的責任。"},{"en":"It looks back at the past and judges what should have happened.","zh":"它回望過去，判斷本來應該發生甚麼。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":9},{"front":"in working with","meaning":"在處理……時","examples":[{"en":"In working with microarrays, scientists must analyse data produced by others.","zh":"在處理微陣列時，科學家必須分析由他人產生的數據。"},{"en":"In working with something means when using, handling, or dealing with it.","zh":"in working with something 指在使用、處理或應對某事物時。"},{"en":"In working with young children, teachers need patience and clear routines.","zh":"在處理幼童時，老師需要耐性和清楚規律。"},{"en":"In working with complex data, researchers must check for errors and missing values.","zh":"在處理複雜數據時，研究人員必須檢查錯誤和缺失值。"},{"en":"This phrase introduces the situation in which an action happens.","zh":"這個短語引入某行動發生的情境。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":9},{"front":"hand someone a model","meaning":"給予某人現成模型","examples":[{"en":"Biology does not hand researchers a ready-made model.","zh":"生物學不會給研究人員一個現成模型。"},{"en":"To hand someone a model means to give them a prepared framework they can use immediately.","zh":"hand someone a model 指給某人一個可立即使用的準備好框架。"},{"en":"A teacher may hand students a model answer before asking them to write their own.","zh":"老師可能先給學生一個範文模型，再要求他們自己寫。"},{"en":"If no one hands you a model, you must build one from evidence and reasoning.","zh":"如果沒有人給你現成模型，你就必須根據證據和推理自己建立。"},{"en":"This phrase suggests receiving a useful structure without having to create it yourself.","zh":"這個短語表示收到有用結構，而不用自己創造。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":10},{"front":"make sense of the data","meaning":"理解數據","examples":[{"en":"Researchers needed a model to make sense of the data.","zh":"研究人員需要一個模型來理解數據。"},{"en":"To make sense of the data means to understand what the numbers or records show.","zh":"make sense of the data 指理解數字或記錄顯示甚麼。"},{"en":"A shop owner may use charts to make sense of daily sales data.","zh":"店主可能使用圖表來理解每日銷售數據。"},{"en":"Without a clear method, large datasets can be hard to make sense of.","zh":"沒有清楚方法，大型數據集可能難以理解。"},{"en":"This phrase focuses on turning raw information into meaning.","zh":"這個短語著重把原始資訊轉化成意義。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":10},{"front":"even more challenging","meaning":"更具挑戰的是","examples":[{"en":"Even more challenging, biological building blocks interact in many ways.","zh":"更具挑戰的是，生物基本構件以許多方式相互作用。"},{"en":"Even more challenging means that the next point makes the problem harder than before.","zh":"even more challenging 指下一點令問題比之前更困難。"},{"en":"The homework was long; even more challenging, the instructions were unclear.","zh":"功課很長；更具挑戰的是，指示並不清楚。"},{"en":"In research, an already difficult task becomes even more challenging when data are incomplete.","zh":"在研究中，如果數據不完整，原本困難的任務會變得更具挑戰。"},{"en":"This phrase signals an added level of difficulty.","zh":"這個短語表示增加了一層困難。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":10},{"front":"building blocks","meaning":"組成部分；基本構件","examples":[{"en":"DNA, RNA and proteins are biological building blocks.","zh":"DNA、RNA 和蛋白質是生物基本構件。"},{"en":"Building blocks are basic parts that combine to form a larger system.","zh":"building blocks 指組合成較大系統的基本部分。"},{"en":"Letters are the building blocks of words, and words are the building blocks of sentences.","zh":"字母是詞語的基本構件，而詞語是句子的基本構件。"},{"en":"If the building blocks change, the whole structure or system may change.","zh":"如果基本構件改變，整個結構或系統也可能改變。"},{"en":"This phrase helps explain complex systems by starting with their basic parts.","zh":"這個短語透過基本部分來幫助解釋複雜系統。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":10},{"front":"make up","meaning":"構成","examples":[{"en":"DNA, RNA and proteins make up living systems.","zh":"DNA、RNA 和蛋白質構成生命系統。"},{"en":"To make up something means to form or compose it.","zh":"make up something 指形成或構成某事物。"},{"en":"Students, teachers, and staff make up a school community.","zh":"學生、老師和職員構成學校社群。"},{"en":"The parts that make up a system affect how the system works.","zh":"構成系統的部分會影響系統如何運作。"},{"en":"This phrase explains what something is composed of.","zh":"這個短語解釋某事由甚麼組成。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":10},{"front":"be assembled in myriad ways","meaning":"以無數方式組合","examples":[{"en":"Biological building blocks are assembled in myriad ways.","zh":"生物基本構件以無數方式組合。"},{"en":"To be assembled in myriad ways means to be put together in a very large number of different patterns.","zh":"be assembled in myriad ways 指以非常多不同模式被組合起來。"},{"en":"The same toy bricks can be assembled in myriad ways to make houses, cars, or animals.","zh":"同一批玩具積木可以以無數方式組合成房屋、汽車或動物。"},{"en":"When basic parts are assembled differently, they can produce very different results.","zh":"當基本部分以不同方式組合，就能產生非常不同的結果。"},{"en":"This phrase emphasises huge variety in how parts combine.","zh":"這個短語強調部分結合方式的巨大多樣性。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":10},{"front":"moreover","meaning":"此外","examples":[{"en":"Moreover, different rules govern their activity.","zh":"此外，不同規則支配它們的活動。"},{"en":"Moreover means in addition, and it introduces another important point.","zh":"moreover 指此外，用來引入另一個重要觀點。"},{"en":"The bus is cheaper than a taxi; moreover, it stops near the school.","zh":"巴士比的士便宜；此外，它停在學校附近。"},{"en":"Writers use moreover when the second point strengthens the first.","zh":"當第二點加強第一點時，作者會使用 moreover。"},{"en":"This word is formal and useful in explanations or essays.","zh":"這個詞較正式，適合用於解釋或文章中。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":10},{"front":"subtly different","meaning":"細微不同的","examples":[{"en":"Subtly different rules of interaction govern biological activity.","zh":"細微不同的相互作用規則支配生物活動。"},{"en":"Subtly different means slightly different in a way that is not immediately obvious.","zh":"subtly different 指有輕微差異，而且差異不一定立即明顯。"},{"en":"Two English words may be subtly different even if students translate them the same way.","zh":"兩個英文字即使學生翻譯成同一意思，也可能有細微不同。"},{"en":"Subtle differences can matter because they may change meaning or behaviour.","zh":"細微差異可能很重要，因為它們可能改變意思或行為。"},{"en":"This phrase warns readers to notice small but important differences.","zh":"這個短語提醒讀者注意細小但重要的差異。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":10},{"front":"rules of interaction","meaning":"相互作用規則","examples":[{"en":"Scientists studied the rules of interaction among genes and proteins.","zh":"科學家研究基因和蛋白質之間的相互作用規則。"},{"en":"Rules of interaction are patterns that explain how different parts affect one another.","zh":"rules of interaction 指解釋不同部分如何互相影響的模式。"},{"en":"In a classroom, rules of interaction may decide when students speak, listen, or work together.","zh":"在課室中，相互作用規則可能決定學生何時說話、聆聽或合作。"},{"en":"If scientists know the rules of interaction, they can better predict system behaviour.","zh":"如果科學家知道相互作用規則，就能更好預測系統行為。"},{"en":"This phrase focuses on relationships between parts, not isolated parts alone.","zh":"這個短語著重部分之間的關係，而不只是孤立部分。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":10},{"front":"making it difficult, if not impossible, to","meaning":"使……即使不是不可能，也很困難","examples":[{"en":"The complexity makes it difficult, if not impossible, to reduce the system to laws.","zh":"這種複雜性使把系統簡化為定律即使不是不可能，也很困難。"},{"en":"Making it difficult, if not impossible, to do something means making it very hard and perhaps impossible.","zh":"making it difficult, if not impossible, to do something 指令做某事非常困難，甚至可能不可能。"},{"en":"Heavy rain made it difficult, if not impossible, to hold the outdoor concert safely.","zh":"大雨使安全舉行戶外音樂會即使不是不可能，也很困難。"},{"en":"Too many unknown factors can make it difficult, if not impossible, to predict an outcome exactly.","zh":"太多未知因素可以使準確預測結果即使不是不可能，也很困難。"},{"en":"This phrase expresses strong difficulty while leaving room for a small possibility.","zh":"這個短語表達強烈困難，同時保留一點可能性。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":10},{"front":"reduce something to","meaning":"將……簡化為","examples":[{"en":"It is hard to reduce biological interactions to fundamental laws.","zh":"很難將生物相互作用簡化為基本定律。"},{"en":"To reduce something to something else means to simplify it into a smaller set of ideas or rules.","zh":"reduce something to something else 指把某事簡化成較少的概念或規則。"},{"en":"A teacher may reduce a long chapter to three key points for revision.","zh":"老師可能把很長的一章簡化為三個重點來溫習。"},{"en":"Some problems cannot be reduced to one cause because many factors are involved.","zh":"有些問題不能簡化為單一原因，因為涉及許多因素。"},{"en":"This phrase can suggest useful simplification or oversimplification, depending on context.","zh":"這個短語可以表示有用簡化，也可以表示過度簡化，視乎語境。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":11},{"front":"patterns of interaction","meaning":"相互作用模式","examples":[{"en":"The patterns of interaction among DNA, RNA and proteins are complex.","zh":"DNA、RNA 和蛋白質之間的相互作用模式很複雜。"},{"en":"Patterns of interaction are repeated ways in which different parts affect one another.","zh":"patterns of interaction 指不同部分互相影響的重複方式。"},{"en":"Teachers may notice patterns of interaction between quiet students and group work.","zh":"老師可能注意到安靜學生與小組工作之間的相互作用模式。"},{"en":"Understanding interaction patterns helps people predict how a system will respond to change.","zh":"理解相互作用模式幫助人們預測系統如何回應變化。"},{"en":"This phrase focuses on repeated relationships, not single events.","zh":"這個短語著重重複關係，而不是單一事件。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":11},{"front":"fundamental laws","meaning":"基本定律","examples":[{"en":"Biology cannot always be reduced to simple fundamental laws.","zh":"生物學不能總是被簡化為簡單基本定律。"},{"en":"Fundamental laws are basic rules that explain how a system works at a deep level.","zh":"fundamental laws 指在深層次解釋系統如何運作的基本規則。"},{"en":"In physics, gravity is often treated as a fundamental law affecting falling objects.","zh":"在物理學中，重力常被視為影響下落物體的基本定律。"},{"en":"Fundamental laws are useful because they can explain many different cases.","zh":"基本定律很有用，因為它們可以解釋許多不同情況。"},{"en":"This phrase suggests basic principles, but biology may be too complex for only a few laws.","zh":"這個短語表示基本原則，但生物學可能太複雜，不能只靠少數定律。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":11},{"front":"find something compelling about","meaning":"找出關於……的有力發現","examples":[{"en":"Scientists try to find something compelling about the natural world.","zh":"科學家嘗試找出關於自然世界的有力發現。"},{"en":"To find something compelling about a subject means to discover something powerful, convincing, or deeply interesting in it.","zh":"find something compelling about a subject 指在某主題中發現有力、令人信服或非常有趣的東西。"},{"en":"A student may find something compelling about history when she reads a diary from wartime.","zh":"學生讀到戰時日記時，可能找出關於歷史的有力而吸引人的內容。"},{"en":"Strong evidence can help researchers find something compelling about a confusing problem.","zh":"強證據可以幫助研究人員在混亂問題中找出有力發現。"},{"en":"This phrase suggests a meaningful discovery that attracts attention.","zh":"這個短語表示吸引注意的有意義發現。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":11},{"front":"the natural world","meaning":"自然世界","examples":[{"en":"The model aimed to reveal something compelling about the natural world.","zh":"該模型旨在揭示關於自然世界的有力發現。"},{"en":"The natural world means nature, including living things, physical forces, Earth systems, and the universe.","zh":"natural world 指自然，包括生物、物理力量、地球系統和宇宙。"},{"en":"Children learn about the natural world when they study plants, weather, animals, and rocks.","zh":"孩子學習植物、天氣、動物和岩石時，就是在了解自然世界。"},{"en":"Science helps people explain patterns in the natural world rather than only admire them.","zh":"科學幫助人們解釋自然世界中的模式，而不只是欣賞它們。"},{"en":"This phrase contrasts nature with human-made systems.","zh":"這個短語把自然與人造系統作對比。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":11},{"front":"in a context where","meaning":"在……的背景下","examples":[{"en":"The research took place in a context where many variables were unknown.","zh":"這項研究是在許多變量未知的背景下進行。"},{"en":"In a context where means in a situation or setting in which something is true.","zh":"in a context where 指在某情況或背景中某事成立。"},{"en":"In a context where students lack internet access, online homework may be unfair.","zh":"在學生缺乏網絡的背景下，網上功課可能不公平。"},{"en":"Decisions change in a context where time, money, or information is limited.","zh":"在時間、金錢或資訊有限的背景下，決定會改變。"},{"en":"This phrase helps explain the conditions surrounding an action.","zh":"這個短語幫助解釋圍繞某行動的條件。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":11},{"front":"be forced to be agnostic","meaning":"被迫保持不可知立場","examples":[{"en":"Researchers were forced to be agnostic when little was known.","zh":"當所知甚少時，研究人員被迫保持不可知立場。"},{"en":"To be forced to be agnostic means to have to avoid fixed assumptions because there is not enough evidence.","zh":"be forced to be agnostic 指因證據不足而必須避免固定假設。"},{"en":"A doctor may be forced to be agnostic before test results show what illness a patient has.","zh":"在檢測結果顯示病人患甚麼病之前，醫生可能被迫保持不可知立場。"},{"en":"In early research, being agnostic can prevent scientists from choosing answers too quickly.","zh":"在早期研究中，保持不可知立場可以防止科學家太快選定答案。"},{"en":"This phrase means staying open because certainty is not yet possible.","zh":"這個短語表示因尚不能確定而保持開放。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":11},{"front":"machine-learning algorithms","meaning":"機器學習算法","examples":[{"en":"Machine-learning algorithms can work well with unknown variables.","zh":"機器學習算法能很好地處理未知變量。"},{"en":"Machine-learning algorithms are computer procedures that learn patterns from data and make predictions or decisions.","zh":"machine-learning algorithms 指從數據中學習模式並作出預測或決定的電腦程序。"},{"en":"A shopping website may use machine-learning algorithms to recommend products.","zh":"購物網站可能使用機器學習算法推薦產品。"},{"en":"These algorithms can improve when they are trained on more useful examples.","zh":"當這些算法以更多有用例子訓練時，可以有所改善。"},{"en":"This phrase refers to the step-by-step computer methods behind machine learning.","zh":"這個短語指機器學習背後一步一步的電腦方法。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":11},{"front":"perform well under","meaning":"在……下表現良好","examples":[{"en":"Many algorithms perform well under uncertain conditions.","zh":"許多算法在不確定條件下表現良好。"},{"en":"To perform well under certain conditions means to work effectively in those circumstances.","zh":"perform well under certain conditions 指在那些情況下有效運作。"},{"en":"Some students perform well under pressure, while others need quiet time.","zh":"有些學生在壓力下表現良好，而另一些需要安靜時間。"},{"en":"A tool that performs well under messy conditions is useful for real-world problems.","zh":"在混亂條件下仍表現良好的工具，對現實問題很有用。"},{"en":"This phrase links performance with the situation surrounding it.","zh":"這個短語把表現與周圍情況連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":11},{"front":"precisely these conditions","meaning":"正是在這些條件下","examples":[{"en":"Machine learning performs well under precisely these conditions.","zh":"機器學習正是在這些條件下表現良好。"},{"en":"Precisely these conditions means exactly the situations just described.","zh":"precisely these conditions 指正正是剛描述的那些情況。"},{"en":"A calm leader is useful in precisely these conditions: when time is short and people are nervous.","zh":"冷靜領袖正是在這些條件下有用：時間短而人們緊張。"},{"en":"If a method works under precisely these conditions, it matches the problem very closely.","zh":"如果一種方法正是在這些條件下有效，它就非常切合問題。"},{"en":"This phrase stresses exact fit between the situation and the tool.","zh":"這個短語強調情況與工具之間的精確配合。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":11},{"front":"unknown variables","meaning":"未知變量","examples":[{"en":"Machine learning is useful when there are many unknown variables.","zh":"當有許多未知變量時，機器學習很有用。"},{"en":"Unknown variables are factors that may affect a result but are not yet known or measured.","zh":"unknown variables 指可能影響結果但尚未被知道或量度的因素。"},{"en":"A doctor faces unknown variables when symptoms are unclear and test results are incomplete.","zh":"當症狀不清楚且檢測結果不完整時，醫生面對未知變量。"},{"en":"Too many unknown variables make simple prediction difficult.","zh":"太多未知變量會令簡單預測變得困難。"},{"en":"This phrase highlights uncertainty inside a problem.","zh":"這個短語突出問題中的不確定性。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":12},{"front":"let the data decide","meaning":"讓數據決定","examples":[{"en":"Machine learning lets the data decide what is worth studying.","zh":"機器學習讓數據決定甚麼值得研究。"},{"en":"To let the data decide means to allow evidence and patterns in the data to guide conclusions.","zh":"let the data decide 指讓數據中的證據和模式引導結論。"},{"en":"A teacher may let the data decide which grammar mistakes need more practice.","zh":"老師可能讓數據決定哪些文法錯誤需要更多練習。"},{"en":"Letting the data decide can reduce personal bias, but the data must still be checked carefully.","zh":"讓數據決定可以減少個人偏見，但數據仍必須仔細檢查。"},{"en":"This phrase suggests following evidence instead of guessing first.","zh":"這個短語表示跟隨證據，而不是先行猜測。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":12},{"front":"be worth looking at","meaning":"值得研究；值得留意","examples":[{"en":"The algorithm identifies what is worth looking at.","zh":"算法識別甚麼值得研究。"},{"en":"If something is worth looking at, it deserves attention or further study.","zh":"如果某事 be worth looking at，意思是它值得注意或進一步研究。"},{"en":"A teacher may decide that one repeated mistake is worth looking at before the next lesson.","zh":"老師可能決定在下一課前研究一個反覆出現的錯誤。"},{"en":"In large data, a pattern worth looking at may lead to a useful discovery.","zh":"在大型數據中，值得留意的模式可能帶來有用發現。"},{"en":"This phrase helps separate important details from background noise.","zh":"這個短語幫助把重要細節與背景雜訊分開。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":12},{"front":"gene regulatory network","meaning":"基因調控網絡","examples":[{"en":"Wiggins began building a model of a gene regulatory network in yeast.","zh":"Wiggins 開始建立酵母基因調控網絡的模型。"},{"en":"A gene regulatory network is a system of genes and regulators that control gene activity.","zh":"gene regulatory network 指控制基因活動的一套基因和調控因子系統。"},{"en":"Scientists may map a gene regulatory network to see which genes influence others.","zh":"科學家可能繪製基因調控網絡，以觀察哪些基因影響其他基因。"},{"en":"Understanding this network can help explain how cells respond to changing conditions.","zh":"理解這個網絡可以幫助解釋細胞如何回應變化中的條件。"},{"en":"This phrase presents gene control as a connected system, not isolated switches.","zh":"這個短語把基因控制呈現為連接系統，而不是孤立開關。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":12},{"front":"a set of rules","meaning":"一套規則","examples":[{"en":"The network is a set of rules governing gene activity.","zh":"這個網絡是一套支配基因活動的規則。"},{"en":"A set of rules is a group of instructions or principles that guide behaviour.","zh":"a set of rules 指一組引導行為的指示或原則。"},{"en":"A classroom has a set of rules about speaking, homework, and phones.","zh":"課室有一套關於說話、功課和手機的規則。"},{"en":"A clear set of rules helps people predict what is allowed and what will happen next.","zh":"清楚的一套規則幫助人們預測甚麼被允許，以及接下來會發生甚麼。"},{"en":"This phrase suggests organised guidance rather than random action.","zh":"這個短語表示有組織的引導，而不是隨機行動。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":12},{"front":"by which","meaning":"藉以；透過……","examples":[{"en":"The network contains rules by which genes control transcription.","zh":"這個網絡包含基因藉以控制轉錄的規則。"},{"en":"By which means through which or using which.","zh":"by which 指藉以或透過某事。"},{"en":"A school has rules by which students borrow books from the library.","zh":"學校有學生藉以從圖書館借書的規則。"},{"en":"Scientists look for mechanisms by which cells respond to danger.","zh":"科學家尋找細胞藉以回應危險的機制。"},{"en":"This phrase connects a rule, method, or tool with the action it enables.","zh":"這個短語把規則、方法或工具與它所促成的行動連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":12},{"front":"selectively orchestrate","meaning":"有選擇地協調","examples":[{"en":"Genes selectively orchestrate how DNA is transcribed into mRNA.","zh":"基因有選擇地協調 DNA 如何被轉錄成 mRNA。"},{"en":"To selectively orchestrate something means to carefully control selected parts of a process.","zh":"selectively orchestrate something 指仔細控制過程中被選中的部分。"},{"en":"A music teacher may selectively orchestrate a performance by choosing which instruments play at each moment.","zh":"音樂老師可能透過選擇每一刻哪些樂器演奏，來有選擇地協調表演。"},{"en":"In cells, selective control helps ensure that the right genes are active at the right time.","zh":"在細胞中，選擇性控制有助確保正確基因在正確時間活躍。"},{"en":"This phrase suggests careful coordination, not random action.","zh":"這個短語表示仔細協調，而不是隨機行動。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":12},{"front":"how vigorously","meaning":"以多強烈的程度","examples":[{"en":"The model predicts how vigorously DNA is transcribed.","zh":"該模型預測 DNA 以多強烈的程度被轉錄。"},{"en":"How vigorously means how strongly, actively, or intensely something happens.","zh":"how vigorously 指某事發生得有多強、活躍或密集。"},{"en":"A coach may watch how vigorously students train before a competition.","zh":"教練可能觀察學生在比賽前訓練得有多強烈。"},{"en":"If a gene is transcribed more vigorously, more RNA may be produced.","zh":"如果某基因更強烈地被轉錄，可能會產生更多 RNA。"},{"en":"This phrase focuses on degree of activity, not simply whether something happens.","zh":"這個短語著重活動程度，而不只是某事是否發生。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":12},{"front":"be transcribed into","meaning":"被轉錄成","examples":[{"en":"DNA is transcribed into messenger RNA.","zh":"DNA 被轉錄成信使 RNA。"},{"en":"To be transcribed into something means to be copied into another written or biological form.","zh":"be transcribed into something 指被複製成另一種書面或生物形式。"},{"en":"In biology, genetic information in DNA can be transcribed into RNA.","zh":"在生物學中，DNA 中的遺傳資訊可以被轉錄成 RNA。"},{"en":"If DNA is not transcribed properly, the cell may not make the correct protein.","zh":"如果 DNA 沒有正確被轉錄，細胞可能無法製造正確蛋白質。"},{"en":"This phrase describes a copying step in gene expression.","zh":"這個短語描述基因表達中的複製步驟。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":12},{"front":"work with algorithms","meaning":"使用算法","examples":[{"en":"Wiggins worked with different algorithms.","zh":"Wiggins 使用不同算法。"},{"en":"To work with algorithms means to use computer procedures to solve problems or analyse data.","zh":"work with algorithms 指使用電腦程序來解決問題或分析數據。"},{"en":"A data analyst may work with algorithms to find patterns in customer behaviour.","zh":"數據分析員可能使用算法尋找顧客行為模式。"},{"en":"Working with algorithms requires understanding both the data and the question being asked.","zh":"使用算法需要理解數據，也要理解正在提出的問題。"},{"en":"This phrase focuses on using computational methods in practical work.","zh":"這個短語著重在實際工作中使用計算方法。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":12},{"front":"attend discussions on","meaning":"參與關於……的討論","examples":[{"en":"He attended discussions on gene regulation.","zh":"他參與關於基因調控的討論。"},{"en":"To attend discussions on a topic means to go to meetings or conversations about that subject.","zh":"attend discussions on a topic 指參加關於某主題的會議或對話。"},{"en":"Teachers may attend discussions on how to support students with anxiety.","zh":"老師可能參與關於如何支援焦慮學生的討論。"},{"en":"Attending discussions can expose people to ideas outside their own work.","zh":"參與討論可以讓人接觸自己工作以外的想法。"},{"en":"This phrase suggests active learning through professional conversation.","zh":"這個短語表示透過專業對話主動學習。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":13},{"front":"be led by","meaning":"由……主持","examples":[{"en":"The discussions were led by Christina Leslie.","zh":"這些討論由 Christina Leslie 主持。"},{"en":"To be led by someone means to be guided, organised, or directed by that person.","zh":"be led by someone 指由某人引導、組織或主持。"},{"en":"The school meeting was led by the principal.","zh":"學校會議由校長主持。"},{"en":"A project led by an experienced person may run more smoothly.","zh":"由有經驗的人主持的項目可能運作得更順利。"},{"en":"This phrase identifies who is responsible for guiding an activity.","zh":"這個短語指出誰負責引導某項活動。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":13},{"front":"computational biology group","meaning":"計算生物學小組","examples":[{"en":"Leslie ran the computational biology group at Columbia.","zh":"Leslie 在哥倫比亞大學管理計算生物學小組。"},{"en":"A computational biology group uses computer methods to study biological questions.","zh":"computational biology group 指使用電腦方法研究生物問題的小組。"},{"en":"Such a group may analyse DNA data, protein structures, or disease patterns.","zh":"這類小組可能分析 DNA 數據、蛋白質結構或疾病模式。"},{"en":"Computational biology groups are important when biological datasets become too large for manual study.","zh":"當生物數據集大到不能人工研究時，計算生物學小組很重要。"},{"en":"This phrase combines biology with computing and data analysis.","zh":"這個短語結合生物學、電腦和數據分析。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":13},{"front":"at the time","meaning":"當時","examples":[{"en":"Christina Leslie ran the group at Columbia at the time.","zh":"Christina Leslie 當時在哥倫比亞大學管理該小組。"},{"en":"At the time means during the particular period being discussed.","zh":"at the time 指在所討論的特定時期。"},{"en":"I did not understand the decision at the time, but it makes sense now.","zh":"我當時不理解那個決定，但現在覺得合理。"},{"en":"Information may be true at the time but change later.","zh":"資料在當時可能正確，但之後可能改變。"},{"en":"This phrase anchors a statement to a specific past moment.","zh":"這個短語把一句說話固定在特定過去時刻。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":13},{"front":"suggest using","meaning":"建議使用","examples":[{"en":"Leslie suggested using a classifier.","zh":"Leslie 建議使用分類器。"},{"en":"To suggest using something means to recommend it as a possible method or tool.","zh":"suggest using something 指推薦某物作為可能的方法或工具。"},{"en":"A teacher may suggest using flashcards to remember difficult vocabulary.","zh":"老師可能建議使用詞卡來記住困難詞彙。"},{"en":"When one method is not working, a colleague may suggest using another approach.","zh":"當一種方法無效時，同事可能建議使用另一種方法。"},{"en":"This phrase presents advice rather than a command.","zh":"這個短語表示建議，而不是命令。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":13},{"front":"a specific machine-learning tool","meaning":"一種特定的機器學習工具","examples":[{"en":"A classifier is a specific machine-learning tool.","zh":"分類器是一種特定的機器學習工具。"},{"en":"A specific machine-learning tool is one particular method used for a defined learning task.","zh":"specific machine-learning tool 指用於特定學習任務的一種具體方法。"},{"en":"A spam filter is a specific machine-learning tool that sorts emails into groups.","zh":"垃圾郵件過濾器是一種特定的機器學習工具，會把電郵分類。"},{"en":"Choosing the right tool matters because different tasks need different methods.","zh":"選擇正確工具很重要，因為不同任務需要不同方法。"},{"en":"This phrase narrows machine learning from a broad field to one usable tool.","zh":"這個短語把機器學習從廣闊領域收窄到一個可用工具。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":13},{"front":"classifier","meaning":"分類器","examples":[{"en":"A classifier learns rules for separating examples into groups.","zh":"分類器學習把例子分成不同組別的規則。"},{"en":"A classifier is a machine-learning tool that sorts new items into categories.","zh":"classifier 是一種把新項目分入不同類別的機器學習工具。"},{"en":"An email classifier can decide whether a message is spam or not.","zh":"電郵分類器可以判斷一封訊息是否垃圾郵件。"},{"en":"A classifier needs examples first so it can learn what features matter.","zh":"分類器首先需要例子，才能學會哪些特徵重要。"},{"en":"This word is about grouping things according to learned rules.","zh":"這個詞關乎根據學到的規則把事物分組。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":13},{"front":"discriminate between","meaning":"區分","examples":[{"en":"The algorithm must discriminate between pictures with bicycles and pictures without them.","zh":"算法必須區分有單車和沒有單車的圖片。"},{"en":"To discriminate between things means to tell the difference between them.","zh":"discriminate between things 指分辨事物之間的差別。"},{"en":"A child learns to discriminate between similar letters such as b and d.","zh":"小孩學習區分 b 和 d 等相似字母。"},{"en":"Good data help a model discriminate between true signals and background noise.","zh":"良好數據幫助模型區分真實信號和背景雜訊。"},{"en":"In this context, the phrase means distinguish, not treat people unfairly.","zh":"在這個語境中，這個短語指分辨，而不是不公平對待人。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":13},{"front":"sift through","meaning":"篩選；仔細檢視","examples":[{"en":"A classifier sifts through labelled examples.","zh":"分類器會仔細檢視已標籤的例子。"},{"en":"To sift through something means to examine many items carefully to find what matters.","zh":"sift through something 指仔細檢查大量項目，以找出重要內容。"},{"en":"A student may sift through notes to find the facts needed for an essay.","zh":"學生可能翻查筆記，找出文章需要的事實。"},{"en":"Researchers sift through data because useful patterns may be hidden among irrelevant details.","zh":"研究人員篩選數據，因為有用模式可能隱藏在無關細節中。"},{"en":"This phrase suggests careful searching through a large amount of material.","zh":"這個短語表示在大量材料中仔細搜尋。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":13},{"front":"labelled examples","meaning":"已標籤的例子","examples":[{"en":"The classifier learns from labelled examples.","zh":"分類器從已標籤的例子中學習。"},{"en":"Labelled examples are examples already marked with the correct category or answer.","zh":"labelled examples 指已標明正確類別或答案的例子。"},{"en":"A set of photos labelled “cat” or “dog” can train a simple image classifier.","zh":"一組標記為「貓」或「狗」的照片，可以訓練簡單圖像分類器。"},{"en":"Labelled examples help the computer learn what patterns belong to each group.","zh":"已標籤的例子幫助電腦學習哪些模式屬於哪個組別。"},{"en":"Without labelled examples, some classifiers cannot learn the correct categories easily.","zh":"沒有已標籤的例子，有些分類器難以學會正確類別。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":13},{"front":"measure everything it can about","meaning":"盡可能量度關於……的一切","examples":[{"en":"The classifier measures everything it can about the examples.","zh":"分類器盡可能量度關於這些例子的一切。"},{"en":"To measure everything it can about something means to collect as many relevant features as possible.","zh":"measure everything it can about something 指盡可能收集相關特徵。"},{"en":"A doctor may measure everything she can about a patient before deciding on treatment.","zh":"醫生在決定治療前，可能盡可能量度關於病人的一切。"},{"en":"More measurements can help a model learn, but irrelevant measurements may add noise.","zh":"更多量度可以幫助模型學習，但無關量度可能增加雜訊。"},{"en":"This phrase shows thorough data collection before decision-making.","zh":"這個短語顯示在作決定前進行全面數據收集。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":14},{"front":"gradually learn","meaning":"逐漸學會","examples":[{"en":"The algorithm gradually learns decision rules.","zh":"算法逐漸學會決策規則。"},{"en":"To gradually learn something means to learn it slowly through repeated examples or practice.","zh":"gradually learn something 指透過反覆例子或練習慢慢學會某事。"},{"en":"A student gradually learns pronunciation by listening and speaking every day.","zh":"學生透過每天聆聽和說話逐漸學會發音。"},{"en":"Algorithms gradually learn when training data allow them to adjust again and again.","zh":"當訓練數據讓算法反覆調整時，算法就會逐漸學會。"},{"en":"This phrase suggests steady improvement rather than sudden understanding.","zh":"這個短語表示穩定改善，而不是突然理解。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":14},{"front":"decision rules","meaning":"決策規則","examples":[{"en":"Decision rules help the classifier group new examples.","zh":"決策規則幫助分類器把新例子分組。"},{"en":"Decision rules are guidelines that explain how to choose between possible outcomes.","zh":"decision rules 指解釋如何在可能結果之間作選擇的指引。"},{"en":"A school may use decision rules to decide when students need extra support.","zh":"學校可能使用決策規則來決定學生何時需要額外支援。"},{"en":"Clear decision rules make choices more consistent and less random.","zh":"清楚的決策規則使選擇更一致，較不隨機。"},{"en":"This phrase is common when explaining how a model makes classifications.","zh":"這個短語常用於解釋模型如何進行分類。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":14},{"front":"govern the grouping","meaning":"支配分類","examples":[{"en":"The classifier learns rules that govern the grouping.","zh":"分類器學會支配分類的規則。"},{"en":"Rules that govern the grouping control how items are placed into different categories.","zh":"govern the grouping 的規則控制項目如何被放入不同類別。"},{"en":"A teacher may set rules that govern the grouping of students for a project.","zh":"老師可能設定支配學生分組的規則來進行項目。"},{"en":"If the grouping rules are wrong, similar items may be separated or mixed incorrectly.","zh":"如果分類規則錯誤，相似項目可能被錯誤分開或混合。"},{"en":"This phrase connects control rules with classification.","zh":"這個短語把控制規則與分類連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":14},{"front":"from these rules","meaning":"根據這些規則","examples":[{"en":"From these rules, the algorithm generates a model.","zh":"根據這些規則，算法生成模型。"},{"en":"From these rules means using these rules as the basis or starting point.","zh":"from these rules 指以這些規則作為基礎或起點。"},{"en":"From these rules, a teacher can design a fair marking scheme.","zh":"根據這些規則，老師可以設計公平的評分標準。"},{"en":"A model built from clear rules is easier to explain than one built from guesses.","zh":"根據清楚規則建立的模型，比根據猜測建立的模型更容易解釋。"},{"en":"This phrase shows that one thing is created based on another.","zh":"這個短語顯示一件事物是基於另一件事物而產生。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":14},{"front":"generate a model","meaning":"生成模型","examples":[{"en":"The algorithm generates a model from the decision rules.","zh":"算法根據決策規則生成模型。"},{"en":"To generate a model means to create a structured representation that can explain or predict something.","zh":"generate a model 指創造一個可以解釋或預測某事的結構化表示。"},{"en":"A city may generate a traffic model from data about roads and travel times.","zh":"城市可能根據道路和行車時間數據生成交通模型。"},{"en":"A generated model can help people test ideas before making real changes.","zh":"生成的模型可以幫助人們在作出真實改變前測試想法。"},{"en":"This phrase connects data or rules with a usable explanation.","zh":"這個短語把數據或規則與可用解釋連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":14},{"front":"determine whether or not","meaning":"判斷是否","examples":[{"en":"The model can determine whether or not a new picture contains a bicycle.","zh":"模型可以判斷新圖片是否包含單車。"},{"en":"To determine whether or not something is true means to decide if it is true or false.","zh":"determine whether or not something is true 指判斷某事是真是假。"},{"en":"A doctor may run a test to determine whether or not a patient has an infection.","zh":"醫生可能進行檢測，以判斷病人是否受感染。"},{"en":"Clear evidence helps people determine whether or not a claim is reliable.","zh":"清楚證據幫助人們判斷某說法是否可靠。"},{"en":"This phrase presents a yes-or-no judgement.","zh":"這個短語表示是或否的判斷。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":14},{"front":"learning task","meaning":"學習任務","examples":[{"en":"In gene networks, the learning task is to predict changes in activity.","zh":"在基因網絡中，學習任務是預測活動變化。"},{"en":"A learning task is the specific problem a machine-learning system is trained to solve.","zh":"learning task 指機器學習系統被訓練去解決的特定問題。"},{"en":"For an email filter, the learning task is to separate spam from normal messages.","zh":"對電郵過濾器而言，學習任務是把垃圾郵件與正常訊息分開。"},{"en":"A clear learning task helps researchers choose the right data and algorithm.","zh":"清楚的學習任務幫助研究人員選擇正確數據和算法。"},{"en":"This phrase defines what the system is supposed to learn.","zh":"這個短語定義系統應該學會甚麼。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":14},{"front":"the problem of predicting","meaning":"預測……的問題","examples":[{"en":"The learning task becomes the problem of predicting gene activity.","zh":"學習任務變成預測基因活動的問題。"},{"en":"The problem of predicting something is the challenge of estimating what will happen.","zh":"the problem of predicting something 指估計將會發生甚麼的挑戰。"},{"en":"Weather forecasting is the problem of predicting temperature, rain, and wind.","zh":"天氣預報是預測氣溫、雨量和風力的問題。"},{"en":"Predicting becomes difficult when many causes affect the result.","zh":"當許多原因影響結果時，預測就會變得困難。"},{"en":"This phrase turns a goal into a specific analytical challenge.","zh":"這個短語把目標變成特定分析挑戰。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":14},{"front":"increase or decrease","meaning":"增加或減少","examples":[{"en":"The model predicts whether genes increase or decrease their activity.","zh":"模型預測基因是否增加或減少其活動。"},{"en":"Increase or decrease means become greater or become smaller.","zh":"increase or decrease 指變多或變少。"},{"en":"A shop tracks whether sales increase or decrease after a discount campaign.","zh":"商店追蹤折扣活動後銷售額是增加還是減少。"},{"en":"If gene activity increases or decreases, the amount of related protein may change.","zh":"如果基因活動增加或減少，相關蛋白質的數量可能改變。"},{"en":"This phrase compares movement in two opposite directions.","zh":"這個短語比較兩個相反方向的變化。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":14},{"front":"protein-making activity","meaning":"製造蛋白質的活動","examples":[{"en":"Genes can increase or decrease their protein-making activity.","zh":"基因可以增加或減少其製造蛋白質的活動。"},{"en":"Protein-making activity is the process by which genes help cells produce proteins.","zh":"protein-making activity 指基因幫助細胞製造蛋白質的過程。"},{"en":"A biology teacher may explain protein-making activity as using genetic instructions to build cell tools.","zh":"生物老師可能把製造蛋白質的活動解釋為使用遺傳指令建立細胞工具。"},{"en":"Changes in protein-making activity can affect cell shape, growth, and repair.","zh":"製造蛋白質活動的變化可以影響細胞形狀、生長和修復。"},{"en":"This phrase describes what genes help cells produce, not physical exercise.","zh":"這個短語描述基因幫助細胞製造甚麼，而不是身體運動。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":15},{"front":"be trained on","meaning":"以……作訓練","examples":[{"en":"The algorithm was trained on DNA sequences and mRNA levels.","zh":"算法以 DNA 序列和 mRNA 水平作訓練。"},{"en":"To be trained on data means to learn patterns from that data.","zh":"be trained on data 指從那些數據中學習模式。"},{"en":"A speech-recognition system may be trained on thousands of recorded voices.","zh":"語音識別系統可能以數千段錄音聲音作訓練。"},{"en":"If a model is trained on poor data, its predictions may also be poor.","zh":"如果模型以差劣數據作訓練，它的預測也可能很差。"},{"en":"This phrase explains what examples a learning system uses to learn.","zh":"這個短語解釋學習系統使用哪些例子來學習。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":15},{"front":"mRNA levels","meaning":"mRNA水平","examples":[{"en":"The algorithm used mRNA levels measured in yeast.","zh":"該算法使用了在酵母中量度的 mRNA 水平。"},{"en":"mRNA levels are the amounts of messenger RNA present in cells under certain conditions.","zh":"mRNA levels 指在特定條件下細胞中信使 RNA 的數量。"},{"en":"Scientists compare mRNA levels to see which genes are more active.","zh":"科學家比較 mRNA 水平，以觀察哪些基因較活躍。"},{"en":"When mRNA levels rise, the cell may produce more of a related protein.","zh":"當 mRNA 水平上升，細胞可能製造更多相關蛋白質。"},{"en":"This phrase gives a measurable sign of gene expression.","zh":"這個短語提供了基因表達的可量度指標。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":15},{"front":"regulators","meaning":"調控因子","examples":[{"en":"The model examined regulators expressed under different conditions.","zh":"該模型研究在不同條件下表達的調控因子。"},{"en":"Regulators are factors that control or influence the activity of other parts of a system.","zh":"regulators 指控制或影響系統其他部分活動的因素。"},{"en":"In a school, rules and timetables act as regulators of daily behaviour.","zh":"在學校中，規則和時間表充當日常行為的調控因子。"},{"en":"In cells, regulators can turn genes up, down, on, or off.","zh":"在細胞中，調控因子可以提高、降低、開啟或關閉基因。"},{"en":"This word focuses on control and adjustment.","zh":"這個詞著重控制和調整。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":15},{"front":"be expressed during","meaning":"在……期間表達","examples":[{"en":"Regulators were expressed during a range of conditions in yeast.","zh":"調控因子在酵母的一系列條件期間表達。"},{"en":"To be expressed during a period or condition means to be produced or active at that time.","zh":"be expressed during a period or condition 指在某時間或條件下被產生或變得活躍。"},{"en":"Some genes are expressed during stress, while others are expressed during growth.","zh":"有些基因在壓力期間表達，另一些在生長期間表達。"},{"en":"Knowing what is expressed during different conditions helps scientists understand cell responses.","zh":"知道不同條件期間甚麼被表達，幫助科學家理解細胞反應。"},{"en":"This phrase connects gene activity with time or environment.","zh":"這個短語把基因活動與時間或環境連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":15},{"front":"a range of conditions","meaning":"一系列條件","examples":[{"en":"The yeast was studied under a range of conditions.","zh":"酵母在一系列條件下被研究。"},{"en":"A range of conditions means several different situations or environments.","zh":"a range of conditions 指多種不同情況或環境。"},{"en":"A new phone should be tested under a range of conditions, such as heat, cold, and low battery.","zh":"新手機應在一系列條件下測試，例如高溫、低溫和低電量。"},{"en":"Studying cells under a range of conditions helps reveal how flexible they are.","zh":"在一系列條件下研究細胞，有助揭示它們有多靈活。"},{"en":"This phrase suggests variety, not just one fixed situation.","zh":"這個短語表示多樣性，而不是單一固定情況。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":15},{"front":"motif element discrimination","meaning":"基序元素辨別","examples":[{"en":"MEDUSA stands for motif element discrimination using sequence agglomeration.","zh":"MEDUSA 代表使用序列聚合的基序元素辨別。"},{"en":"Motif element discrimination is a technical phrase about identifying useful DNA pattern elements.","zh":"motif element discrimination 是關於識別有用 DNA 模式元素的技術短語。"},{"en":"In simple terms, it is like teaching a computer to notice which DNA patterns matter.","zh":"簡單來說，它就像教電腦注意哪些 DNA 模式重要。"},{"en":"This process helps the model separate important genetic signals from less useful ones.","zh":"這個過程幫助模型把重要遺傳信號與較沒用的信號分開。"},{"en":"The phrase is specialised, so students should focus on the idea of distinguishing DNA patterns.","zh":"這個短語較專門，學生應集中理解辨別 DNA 模式的概念。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":15},{"front":"sequence agglomeration","meaning":"序列聚合","examples":[{"en":"The name MEDUSA includes the phrase sequence agglomeration.","zh":"MEDUSA 這個名稱包含 sequence agglomeration 這個短語。"},{"en":"Sequence agglomeration means grouping or combining sequence information into larger patterns.","zh":"sequence agglomeration 指把序列資訊分組或結合成較大模式。"},{"en":"A simple classroom version would be grouping similar word endings to find spelling patterns.","zh":"簡單課堂例子是把相似字尾分組，以找出拼寫模式。"},{"en":"Combining sequence details can help a model see relationships that single pieces do not show.","zh":"結合序列細節可以幫助模型看見單一片段不能顯示的關係。"},{"en":"This phrase is technical and focuses on clustering sequence information.","zh":"這個短語較技術性，著重把序列資訊聚類。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":15},{"front":"scan every possible pairing","meaning":"掃描每一個可能配對","examples":[{"en":"MEDUSA scans every possible pairing between motifs and regulators.","zh":"MEDUSA 掃描基序與調控因子之間每一個可能配對。"},{"en":"To scan every possible pairing means to check all possible matches between two sets of items.","zh":"scan every possible pairing 指檢查兩組項目之間所有可能配對。"},{"en":"A teacher may scan every possible pairing of students before choosing project partners.","zh":"老師可能在選擇項目伙伴前，檢查學生之間每一個可能配對。"},{"en":"Checking every pairing can be slow, but it helps avoid missing a useful match.","zh":"檢查每個配對可能很慢，但有助避免錯過有用配對。"},{"en":"This phrase emphasises a complete search through possible combinations.","zh":"這個短語強調完整搜尋所有可能組合。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":15},{"front":"DNA promoter sequences","meaning":"DNA啟動子序列","examples":[{"en":"MEDUSA examines DNA promoter sequences called motifs.","zh":"MEDUSA 檢查稱為基序的 DNA 啟動子序列。"},{"en":"DNA promoter sequences are DNA regions that help control when nearby genes are used.","zh":"DNA promoter sequences 指幫助控制附近基因何時被使用的 DNA 區域。"},{"en":"A biology teacher may compare promoter sequences to switches that help start gene activity.","zh":"生物老師可能把啟動子序列比作幫助啟動基因活動的開關。"},{"en":"Changes in promoter sequences can affect how strongly a gene is expressed.","zh":"啟動子序列的變化可以影響基因表達的強度。"},{"en":"This phrase refers to control regions in DNA, not protein-coding instructions alone.","zh":"這個短語指 DNA 中的控制區域，而不只是製造蛋白質的指令。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":15},{"front":"motifs","meaning":"基序","examples":[{"en":"Motifs are DNA promoter sequences used in the model.","zh":"基序是模型中使用的 DNA 啟動子序列。"},{"en":"Motifs are repeated or recognisable patterns in DNA that may have biological meaning.","zh":"motifs 指 DNA 中重複或可辨認、可能有生物意義的模式。"},{"en":"A student can think of motifs like repeated patterns in music or wallpaper.","zh":"學生可以把基序想像成音樂或牆紙中的重複圖案。"},{"en":"If a motif appears near certain genes, it may help regulate their activity.","zh":"如果某基序出現在某些基因附近，它可能幫助調控其活動。"},{"en":"This word means a meaningful pattern, not a random piece of sequence.","zh":"這個詞指有意義的模式，而不是隨機序列片段。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":16},{"front":"much like","meaning":"很像","examples":[{"en":"MEDUSA matches motifs and regulators much like a child matches words and definitions.","zh":"MEDUSA 配對基序和調控因子，很像孩子配對詞語和定義。"},{"en":"Much like means very similar to.","zh":"much like 指非常相似於。"},{"en":"A teacher organises flashcards much like a librarian organises books by topic.","zh":"老師整理詞卡，很像圖書館員按主題整理書籍。"},{"en":"Comparisons using “much like” help explain difficult ideas through familiar examples.","zh":"使用 much like 的比較，可以透過熟悉例子解釋困難概念。"},{"en":"This phrase makes an unfamiliar process easier to imagine.","zh":"這個短語令陌生過程更容易想像。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":16},{"front":"match A with B","meaning":"將A與B配對","examples":[{"en":"A child might match a list of words with their definitions.","zh":"孩子可能把一列詞語與它們的定義配對。"},{"en":"To match A with B means to connect two things that belong together.","zh":"match A with B 指把兩個相屬的東西連接起來。"},{"en":"Students match questions with answers in a reading exercise.","zh":"學生在閱讀練習中把問題與答案配對。"},{"en":"Correct matching helps show that a person understands the relationship between two items.","zh":"正確配對有助顯示一個人理解兩項事物之間的關係。"},{"en":"This phrase is common in tests, games, and data analysis.","zh":"這個短語常見於測驗、遊戲和數據分析。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":16},{"front":"draw a line between","meaning":"在……之間畫線連接","examples":[{"en":"A child may draw a line between a word and its definition.","zh":"孩子可能在詞語和其定義之間畫線連接。"},{"en":"To draw a line between two things can literally mean to connect them with a line.","zh":"draw a line between two things 可以字面意思指用線把兩者連接。"},{"en":"In a worksheet, students draw a line between pictures and matching vocabulary.","zh":"在工作紙中，學生在圖片和相配詞彙之間畫線連接。"},{"en":"Drawing a line between paired items helps learners show the connection clearly.","zh":"在配對項目之間畫線，有助學習者清楚顯示連繫。"},{"en":"In other contexts, the phrase can also mean to separate two ideas, but here it means connect.","zh":"在其他語境中，這個短語也可以表示分隔兩個概念，但這裡意思是連接。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":16},{"front":"improve the fit between","meaning":"改善……之間的吻合度","examples":[{"en":"MEDUSA finds the pairing that best improves the fit between the model and the data.","zh":"MEDUSA 找出最能改善模型與數據之間吻合度的配對。"},{"en":"To improve the fit between two things means to make them match more closely.","zh":"improve the fit between two things 指令兩者更貼近、更吻合。"},{"en":"A tailor improves the fit between a jacket and the person wearing it.","zh":"裁縫改善外套與穿著者之間的合身度。"},{"en":"In research, improving the fit between a model and data makes the model more accurate.","zh":"在研究中，改善模型與數據之間的吻合度會令模型更準確。"},{"en":"This phrase focuses on reducing the gap between prediction and reality.","zh":"這個短語著重減少預測與現實之間的差距。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":16},{"front":"emulate","meaning":"模擬","examples":[{"en":"The model tries to emulate the biological data.","zh":"該模型嘗試模擬生物數據。"},{"en":"To emulate something means to copy or reproduce its behaviour as closely as possible.","zh":"emulate something 指盡可能複製或重現某事物的行為。"},{"en":"A flight simulator tries to emulate the experience of flying a real plane.","zh":"飛行模擬器嘗試模擬駕駛真飛機的體驗。"},{"en":"If a model emulates data well, its output looks similar to real observations.","zh":"如果模型很好地模擬數據，它的輸出會與真實觀察相似。"},{"en":"This verb suggests imitation for learning, testing, or prediction.","zh":"這個動詞表示為了學習、測試或預測而模仿。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":16},{"front":"refer to something as","meaning":"將……稱為","examples":[{"en":"Wiggins refers to these pairings as edges.","zh":"Wiggins 將這些配對稱為邊。"},{"en":"To refer to something as a name means to call it by that name.","zh":"refer to something as a name 指用某個名稱稱呼某事物。"},{"en":"Teachers may refer to common mistakes as “danger points” to help students remember them.","zh":"老師可能將常見錯誤稱為「危險點」，幫助學生記住。"},{"en":"Giving something a name helps people discuss it more clearly.","zh":"給某事物一個名稱，有助人們更清楚討論它。"},{"en":"This phrase introduces terminology.","zh":"這個短語用來引入術語。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":16},{"front":"edges","meaning":"邊；連接線","examples":[{"en":"In the model, Wiggins calls the pairings edges.","zh":"在模型中，Wiggins 把這些配對稱為邊。"},{"en":"Edges are connections between points or items in a network model.","zh":"edges 指網絡模型中點或項目之間的連接。"},{"en":"In a friendship network, an edge can represent a friendship between two people.","zh":"在友誼網絡中，一條邊可以代表兩人之間的友誼。"},{"en":"In gene models, edges can show possible links between regulators and gene activity.","zh":"在基因模型中，邊可以顯示調控因子與基因活動之間的可能連繫。"},{"en":"This word is used in network diagrams to describe connections.","zh":"這個詞用於網絡圖中描述連接。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":16},{"front":"update the model","meaning":"更新模型","examples":[{"en":"MEDUSA updates the model after finding a pairing.","zh":"MEDUSA 找到配對後會更新模型。"},{"en":"To update the model means to change it using new information so it becomes more accurate or useful.","zh":"update the model 指使用新資訊改變模型，使它更準確或更有用。"},{"en":"A weather app updates its model when new temperature and wind data arrive.","zh":"當新的氣溫和風力數據到達時，天氣應用程式會更新模型。"},{"en":"Updating a model helps it learn from mistakes and improve predictions.","zh":"更新模型幫助它從錯誤中學習並改善預測。"},{"en":"This phrase shows that a model changes over time rather than staying fixed.","zh":"這個短語顯示模型會隨時間改變，而不是保持固定。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":16},{"front":"add a new rule","meaning":"加入新規則","examples":[{"en":"The algorithm adds a new rule to guide the next search.","zh":"算法加入新規則來引導下一次搜尋。"},{"en":"To add a new rule means to include another instruction or principle in a system.","zh":"add a new rule 指在系統中加入另一條指示或原則。"},{"en":"A teacher may add a new rule after students keep forgetting to submit homework online.","zh":"當學生不斷忘記網上交功課時，老師可能加入新規則。"},{"en":"Adding a new rule can change what choices are made next.","zh":"加入新規則可以改變之後作出的選擇。"},{"en":"This phrase shows how a system becomes more guided or restricted.","zh":"這個短語顯示系統變得更受引導或限制。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":16},{"front":"guide its search for","meaning":"引導其尋找","examples":[{"en":"The new rule guides the algorithm’s search for the next pairing.","zh":"新規則引導算法尋找下一個配對。"},{"en":"To guide its search for something means to direct how it looks for the next target.","zh":"guide its search for something 指引導它如何尋找下一個目標。"},{"en":"A map guides a tourist’s search for the nearest train station.","zh":"地圖引導遊客尋找最近的火車站。"},{"en":"Good rules guide a search by reducing wasted effort.","zh":"良好規則透過減少浪費力氣來引導搜尋。"},{"en":"This phrase connects guidance with finding something specific.","zh":"這個短語把引導與尋找特定事物連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":17},{"front":"determine the strength of","meaning":"確定……的強度","examples":[{"en":"MEDUSA determines the strength of each pairing.","zh":"MEDUSA 確定每個配對的強度。"},{"en":"To determine the strength of something means to measure or judge how powerful or important it is.","zh":"determine the strength of something 指量度或判斷某事有多強或多重要。"},{"en":"A coach may determine the strength of each player before choosing a team.","zh":"教練可能在選隊前判斷每名球員的實力。"},{"en":"Knowing the strength of a connection helps scientists decide which links matter most.","zh":"知道連繫的強度幫助科學家決定哪些連結最重要。"},{"en":"This phrase focuses on degree, not simply existence.","zh":"這個短語著重程度，而不只是存在與否。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":17},{"front":"existing model","meaning":"現有模型","examples":[{"en":"The rule improves the existing model.","zh":"該規則改善了現有模型。"},{"en":"An existing model is a model that is already built or already being used.","zh":"existing model 指已經建立或正在使用的模型。"},{"en":"A teacher may improve an existing lesson plan instead of writing a new one from zero.","zh":"老師可能改善現有教案，而不是從零開始寫一份新的。"},{"en":"Updating an existing model can be faster than creating a completely new model.","zh":"更新現有模型可以比創建全新模型更快。"},{"en":"This phrase contrasts something already present with something newly added.","zh":"這個短語把已存在的東西與新加入的東西作對比。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":17},{"front":"hierarchy of numbers","meaning":"數字層級","examples":[{"en":"The hierarchy of numbers shows which pairings are more important.","zh":"數字層級顯示哪些配對較重要。"},{"en":"A hierarchy of numbers is an ordered ranking that shows higher and lower importance or strength.","zh":"hierarchy of numbers 指顯示重要性或強度高低的有序排名。"},{"en":"A school may use a hierarchy of numbers to rank repair tasks by urgency.","zh":"學校可能使用數字層級按緊急程度排列維修任務。"},{"en":"A numerical hierarchy helps people see priorities quickly.","zh":"數字層級幫助人們快速看見優先次序。"},{"en":"This phrase means the numbers are organised by importance, not listed randomly.","zh":"這個短語表示數字按重要性排列，而不是隨機列出。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":17},{"front":"enable someone to determine","meaning":"使某人能夠判斷","examples":[{"en":"The numbers enable scientists to determine the importance of pairings.","zh":"這些數字使科學家能夠判斷配對的重要性。"},{"en":"To enable someone to determine something means to give them the ability or information needed to decide it.","zh":"enable someone to determine something 指給予某人能力或資訊去判斷某事。"},{"en":"Clear test results enable doctors to determine which treatment is needed.","zh":"清楚檢測結果使醫生能夠判斷需要哪種治療。"},{"en":"Good data enable researchers to determine whether a pattern is real.","zh":"良好數據使研究人員能夠判斷某模式是否真實。"},{"en":"This phrase connects information with the power to make a judgement.","zh":"這個短語把資訊與作出判斷的能力連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":17},{"front":"more important than others","meaning":"比其他更重要","examples":[{"en":"Some pairings are more important than others.","zh":"有些配對比其他更重要。"},{"en":"More important than others means having greater value, influence, or effect than the rest.","zh":"more important than others 指比其餘項目有更大價值、影響或效果。"},{"en":"In an exam, some questions may be more important than others because they carry more marks.","zh":"在考試中，有些題目可能比其他更重要，因為分數更高。"},{"en":"Identifying what is more important than others helps people use time wisely.","zh":"辨認甚麼比其他更重要，可以幫助人善用時間。"},{"en":"This phrase expresses comparison and priority.","zh":"這個短語表達比較和優先次序。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":17},{"front":"collectively influence","meaning":"共同影響","examples":[{"en":"The pairings collectively influence gene activity.","zh":"這些配對共同影響基因活動。"},{"en":"To collectively influence something means to affect it together as a group.","zh":"collectively influence something 指作為一組一起影響某事。"},{"en":"Sleep, diet, and exercise collectively influence a person’s health.","zh":"睡眠、飲食和運動共同影響一個人的健康。"},{"en":"Several small factors can collectively influence a result more than one factor alone.","zh":"幾個小因素可以共同影響結果，比單一因素更大。"},{"en":"This phrase highlights combined effect.","zh":"這個短語強調合併效果。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":17},{"front":"one pairing at a time","meaning":"每次一個配對","examples":[{"en":"MEDUSA builds the model one pairing at a time.","zh":"MEDUSA 每次一個配對地建立模型。"},{"en":"One pairing at a time means adding or dealing with one match before moving to the next.","zh":"one pairing at a time 指先加入或處理一個配對，再處理下一個。"},{"en":"A student can learn vocabulary one word at a time instead of memorising everything at once.","zh":"學生可以每次學一個詞，而不是一次過記住所有詞。"},{"en":"Working one step at a time makes a difficult task more manageable.","zh":"每次一步地工作，能令困難任務更易處理。"},{"en":"This phrase suggests gradual, orderly progress.","zh":"這個短語表示逐步而有秩序的進展。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":17},{"front":"ratchet up","meaning":"逐步提高；加大","examples":[{"en":"Some genes ratchet up their RNA production.","zh":"有些基因逐步提高其 RNA 生產。"},{"en":"To ratchet up something means to increase it gradually or step by step.","zh":"ratchet up something 指逐步或一級一級地增加某事。"},{"en":"A school may ratchet up security after several visitors enter without signing in.","zh":"學校可能在幾名訪客未登記進入後逐步加強保安。"},{"en":"If a gene ratchets up RNA production, the amount produced rises in stages.","zh":"如果基因逐步提高 RNA 生產，產量會分階段上升。"},{"en":"This phrase suggests controlled increase, not a sudden jump.","zh":"這個短語表示受控制的增加，而不是突然跳升。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":17},{"front":"RNA production","meaning":"RNA生產","examples":[{"en":"MEDUSA predicts changes in RNA production.","zh":"MEDUSA 預測 RNA 生產的變化。"},{"en":"RNA production is the process by which cells make RNA from genetic information.","zh":"RNA production 指細胞根據遺傳資訊製造 RNA 的過程。"},{"en":"Scientists measure RNA production to see which genes are active.","zh":"科學家量度 RNA 生產，以觀察哪些基因活躍。"},{"en":"Changes in RNA production can affect how much protein a cell later makes.","zh":"RNA 生產的變化可以影響細胞之後製造多少蛋白質。"},{"en":"This phrase describes an important step between DNA instructions and protein production.","zh":"這個短語描述 DNA 指令與蛋白質製造之間的重要步驟。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":17},{"front":"clamp something down","meaning":"壓低；抑制","examples":[{"en":"Some genes clamp RNA production down.","zh":"有些基因會壓低 RNA 生產。"},{"en":"To clamp something down means to strongly reduce, restrict, or hold it under control.","zh":"clamp something down 指大幅減少、限制或控制某事。"},{"en":"A school may clamp noise down by closing classroom doors during exams.","zh":"學校可能在考試期間關上課室門，以壓低噪音。"},{"en":"If a regulator clamps RNA production down, less RNA may be made.","zh":"如果調控因子抑制 RNA 生產，可能會製造較少 RNA。"},{"en":"This phrase suggests firm control that lowers activity.","zh":"這個短語表示強力控制並降低活動。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":18},{"front":"as well as","meaning":"以及","examples":[{"en":"MEDUSA predicts gene activity as well as revealing mechanisms.","zh":"MEDUSA 預測基因活動，以及揭示機制。"},{"en":"As well as means in addition to.","zh":"as well as 指以及或除了……之外。"},{"en":"A good dictionary gives pronunciation as well as meaning.","zh":"好字典提供發音以及意思。"},{"en":"A science model can be useful if it explains causes as well as predicts results.","zh":"如果科學模型能解釋原因以及預測結果，它就很有用。"},{"en":"This phrase adds another function or benefit.","zh":"這個短語加入另一個功能或好處。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":18},{"front":"reveal the collective mechanisms","meaning":"揭示集體機制","examples":[{"en":"The model can reveal the collective mechanisms behind gene activity.","zh":"該模型可以揭示基因活動背後的集體機制。"},{"en":"To reveal the collective mechanisms means to show how several parts work together to produce a result.","zh":"reveal the collective mechanisms 指顯示多個部分如何共同作用以產生結果。"},{"en":"A school survey may reveal the collective mechanisms behind poor attendance, such as transport, sleep, and stress.","zh":"學校問卷可能揭示低出席率背後的集體機制，例如交通、睡眠和壓力。"},{"en":"Revealing mechanisms helps people understand causes instead of only seeing outcomes.","zh":"揭示機制幫助人們理解原因，而不只是看見結果。"},{"en":"This phrase focuses on hidden group processes.","zh":"這個短語著重隱藏的群體過程。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":18},{"front":"organism’s transcriptional logic","meaning":"生物體的轉錄邏輯","examples":[{"en":"MEDUSA reveals an organism’s transcriptional logic.","zh":"MEDUSA 揭示生物體的轉錄邏輯。"},{"en":"An organism’s transcriptional logic is the pattern of rules controlling how its DNA is transcribed into RNA.","zh":"organism’s transcriptional logic 指控制其 DNA 如何被轉錄成 RNA 的規則模式。"},{"en":"In simple terms, it is like the cell’s decision system for which genetic messages to copy.","zh":"簡單來說，它就像細胞決定要複製哪些遺傳訊息的系統。"},{"en":"Understanding transcriptional logic helps scientists explain why genes become active under certain conditions.","zh":"理解轉錄邏輯幫助科學家解釋為何基因在某些條件下變得活躍。"},{"en":"This phrase is technical, but the key idea is organised control of transcription.","zh":"這個短語較技術性，但核心概念是對轉錄的有組織控制。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":18},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Candidates choose the correct heading for each paragraph.","zh":"考生為每一段選出正確標題。"},{"en":"To choose the correct heading means to select the title that best matches the paragraph’s main idea.","zh":"choose the correct heading 指選擇最符合段落主旨的標題。"},{"en":"In a reading test, students should read the whole paragraph before choosing the correct heading.","zh":"在閱讀測驗中，學生應先閱讀整段，再選出正確標題。"},{"en":"Focusing only on one detail can lead to the wrong heading.","zh":"只集中於一個細節可能導致選錯標題。"},{"en":"This task tests overall understanding, not just word matching.","zh":"這種題型測試整體理解，而不只是詞語配對。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":18},{"front":"from the list below","meaning":"從以下列表中","examples":[{"en":"The headings are chosen from the list below.","zh":"標題從以下列表中選出。"},{"en":"From the list below means from the options printed under the instruction.","zh":"from the list below 指從指示下方列出的選項中。"},{"en":"Students should choose from the list below rather than invent their own answer.","zh":"學生應從以下列表中選擇，而不是自己創作答案。"},{"en":"Reading every option from the list below can prevent quick but careless choices.","zh":"閱讀以下列表中的每個選項，可以避免快速但粗心的選擇。"},{"en":"This phrase tells students where the possible answers are.","zh":"這個短語告訴學生可能答案在哪裡。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":18},{"front":"write the correct number","meaning":"寫上正確編號","examples":[{"en":"Candidates write the correct number on the answer sheet.","zh":"考生在答題紙上寫上正確編號。"},{"en":"To write the correct number means to put the matching numbered option in the answer space.","zh":"write the correct number 指在答案位置填上相應的編號選項。"},{"en":"In matching questions, students may understand the answer but lose marks if they write the wrong number.","zh":"在配對題中，學生可能明白答案，但如果寫錯編號仍會失分。"},{"en":"Checking the number carefully helps avoid careless mistakes.","zh":"仔細檢查編號有助避免粗心錯誤。"},{"en":"This phrase is an instruction about answer format.","zh":"這個短語是關於答案格式的指示。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":18},{"front":"recollection of","meaning":"對……的回憶","examples":[{"en":"The heading refers to Wiggins’s recollection of the beginning of the project.","zh":"這個標題指 Wiggins 對項目開始的回憶。"},{"en":"A recollection of something is a memory or remembered account of it.","zh":"recollection of something 指對某事的記憶或回想敘述。"},{"en":"A grandparent’s recollection of childhood can help children understand the past.","zh":"祖父母對童年的回憶可以幫助孩子理解過去。"},{"en":"Recollections may be personal, so they often include details that official reports miss.","zh":"回憶可能很個人化，因此常包含官方報告沒有的細節。"},{"en":"This phrase focuses on remembered experience rather than objective data alone.","zh":"這個短語著重被記起的經驗，而不只是客觀數據。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":18},{"front":"far-reaching breakthrough","meaning":"影響深遠的突破","examples":[{"en":"The passage describes the beginning of a far-reaching breakthrough.","zh":"文章描述一項影響深遠的突破的開端。"},{"en":"A far-reaching breakthrough is an important discovery that has effects across many areas or for a long time.","zh":"far-reaching breakthrough 指在許多領域或長時間內產生影響的重要發現。"},{"en":"The invention of antibiotics was a far-reaching breakthrough in medicine.","zh":"抗生素的發明是醫學上一項影響深遠的突破。"},{"en":"A far-reaching breakthrough can change what researchers study and how they work.","zh":"影響深遠的突破可以改變研究人員研究甚麼和如何工作。"},{"en":"This phrase suggests both success and wide influence.","zh":"這個短語同時表示成功和廣泛影響。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":18},{"front":"drawing a map of genes","meaning":"繪製基因圖譜","examples":[{"en":"One heading refers to drawing a map of genes.","zh":"其中一個標題指繪製基因圖譜。"},{"en":"Drawing a map of genes means creating a visual or structured guide to how genes are arranged or connected.","zh":"drawing a map of genes 指建立視覺或結構化指南，顯示基因如何排列或連接。"},{"en":"Scientists may draw a map of genes to show which genes influence one another.","zh":"科學家可能繪製基因圖譜，以顯示哪些基因互相影響。"},{"en":"A gene map helps researchers see relationships that are hard to understand from raw data.","zh":"基因圖譜幫助研究人員看見原始數據中難以理解的關係。"},{"en":"This phrase uses “map” to mean organised representation, not a road map.","zh":"這個短語中的 map 指有組織的表示，而不是道路地圖。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":18},{"front":"jointly applied by","meaning":"由……共同應用","examples":[{"en":"The algorithm was jointly applied by Wiggins and another scientist.","zh":"該算法由 Wiggins 和另一位科學家共同應用。"},{"en":"Jointly applied by two people means used together by them in a shared project.","zh":"jointly applied by two people 指由兩人在共同項目中一起使用。"},{"en":"A teaching method may be jointly applied by two teachers in the same class.","zh":"一種教學方法可能由兩位老師在同一班共同應用。"},{"en":"When a tool is jointly applied, different experts can bring different strengths.","zh":"當工具被共同應用，不同專家可以帶來不同強項。"},{"en":"This phrase emphasises cooperation in using a method.","zh":"這個短語強調在使用方法上的合作。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":19},{"front":"identify new examples","meaning":"識別新例子","examples":[{"en":"A classifier can identify new examples after learning from labelled data.","zh":"分類器從已標籤數據學習後，可以識別新例子。"},{"en":"To identify new examples means to recognise and classify items the system has not seen before.","zh":"identify new examples 指辨認並分類系統以前未見過的項目。"},{"en":"After seeing many labelled photos, a model may identify new examples of cats.","zh":"看過許多已標籤照片後，模型可能識別新的貓例子。"},{"en":"A classifier must learn general patterns so it can handle new examples correctly.","zh":"分類器必須學會一般模式，才能正確處理新例子。"},{"en":"This phrase focuses on applying learned rules to unfamiliar cases.","zh":"這個短語著重把學到的規則應用於陌生個案。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":19},{"front":"technical advances","meaning":"技術進步","examples":[{"en":"The passage discusses technical advances that enabled gene research.","zh":"文章討論使基因研究成為可能的技術進步。"},{"en":"Technical advances are improvements in tools, methods, or technology.","zh":"technical advances 指工具、方法或科技上的改善。"},{"en":"Better internet was a technical advance that made online lessons easier.","zh":"更好的互聯網是一項技術進步，使網上課堂更容易進行。"},{"en":"Technical advances can make old questions answerable in new ways.","zh":"技術進步可以使舊問題以新方式得到回答。"},{"en":"This phrase connects progress in tools with progress in knowledge.","zh":"這個短語把工具進步與知識進步連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":19},{"front":"enable detailed gene research","meaning":"使詳細基因研究成為可能","examples":[{"en":"Microarrays enabled detailed gene research.","zh":"微陣列使詳細基因研究成為可能。"},{"en":"To enable detailed gene research means to make careful, specific study of genes possible.","zh":"enable detailed gene research 指使對基因進行仔細而具體的研究成為可能。"},{"en":"Better microscopes enabled detailed study of cells in earlier science.","zh":"更好的顯微鏡在早期科學中使詳細細胞研究成為可能。"},{"en":"When technology enables detailed research, scientists can ask more precise questions.","zh":"當科技使詳細研究成為可能，科學家就能提出更精確的問題。"},{"en":"This phrase shows that a tool makes deeper investigation possible.","zh":"這個短語顯示工具令更深入調查成為可能。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":19},{"front":"decide which data are worth investigating","meaning":"決定哪些數據值得研究","examples":[{"en":"Machine learning helps researchers decide which data are worth investigating.","zh":"機器學習幫助研究人員決定哪些數據值得研究。"},{"en":"To decide which data are worth investigating means to choose which information deserves further study.","zh":"decide which data are worth investigating 指選擇哪些資訊值得進一步研究。"},{"en":"A teacher may decide which exam mistakes are worth investigating by checking which ones many students made.","zh":"老師可能透過檢查哪些錯誤很多學生都犯，決定哪些考試錯誤值得研究。"},{"en":"When data are too large, researchers need methods to choose where to focus.","zh":"當數據太大時，研究人員需要方法選擇焦點。"},{"en":"This phrase links selection with importance.","zh":"這個短語把選擇與重要性連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":19},{"front":"a difficult obstacle to","meaning":"……的艱難障礙","examples":[{"en":"The complexity of biological data is a difficult obstacle to discovering rules.","zh":"生物數據的複雜性是發現規則的艱難障礙。"},{"en":"A difficult obstacle to something is a serious problem that makes the goal hard to achieve.","zh":"difficult obstacle to something 指令目標難以達成的嚴重問題。"},{"en":"Lack of time can be a difficult obstacle to regular exercise.","zh":"缺乏時間可以是規律運動的艱難障礙。"},{"en":"In research, messy data can be a difficult obstacle to clear conclusions.","zh":"在研究中，混亂數據可以是得出清楚結論的艱難障礙。"},{"en":"This phrase shows what blocks progress.","zh":"這個短語顯示阻礙進展的是甚麼。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":19},{"front":"discover the rules governing","meaning":"發現支配……的規則","examples":[{"en":"Scientists want to discover the rules governing gene activity.","zh":"科學家想發現支配基因活動的規則。"},{"en":"To discover the rules governing something means to find the principles that control how it works.","zh":"discover the rules governing something 指找出控制某事如何運作的原則。"},{"en":"A teacher may discover the rules governing student participation by watching when students speak up.","zh":"老師可能透過觀察學生何時發言，發現支配學生參與的規則。"},{"en":"Discovering governing rules helps people predict and influence future behaviour.","zh":"發現支配規則幫助人們預測並影響未來行為。"},{"en":"This phrase connects discovery with hidden control.","zh":"這個短語把發現與隱藏控制連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":19},{"front":"agree with the information given in","meaning":"與文中資料一致","examples":[{"en":"Candidates decide whether statements agree with the information given in the passage.","zh":"考生判斷陳述是否與文中資料一致。"},{"en":"To agree with the information given in a passage means to match what the passage says.","zh":"agree with the information given in a passage 指與文章所說內容相符。"},{"en":"In a reading test, students should use the passage, not outside knowledge, to judge agreement.","zh":"在閱讀測驗中，學生應使用文章，而不是外部知識，來判斷是否一致。"},{"en":"If a statement partly matches but changes one key detail, it may not agree with the passage.","zh":"如果陳述部分相符但改變了一個關鍵細節，它可能不與文章一致。"},{"en":"This phrase is common in TRUE, FALSE, and NOT GIVEN questions.","zh":"這個短語常見於 TRUE、FALSE 和 NOT GIVEN 題型。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":19},{"front":"write TRUE, FALSE or NOT GIVEN","meaning":"寫上TRUE、FALSE或NOT GIVEN","examples":[{"en":"Candidates write TRUE, FALSE or NOT GIVEN in the answer boxes.","zh":"考生在答案框中寫上 TRUE、FALSE 或 NOT GIVEN。"},{"en":"To write TRUE, FALSE or NOT GIVEN means to choose whether a statement matches, contradicts, or is not covered by the passage.","zh":"write TRUE, FALSE or NOT GIVEN 指選擇陳述是與文章一致、矛盾，還是文章沒有提及。"},{"en":"Students must not write long explanations when the instruction asks for TRUE, FALSE or NOT GIVEN.","zh":"當指示要求寫 TRUE、FALSE 或 NOT GIVEN 時，學生不應寫長解釋。"},{"en":"Careful reading is needed because NOT GIVEN means the passage does not provide enough information.","zh":"需要仔細閱讀，因為 NOT GIVEN 表示文章沒有提供足夠資料。"},{"en":"This phrase is a strict test-answer instruction.","zh":"這個短語是嚴格的測驗作答指示。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":19},{"front":"contradict the information","meaning":"與資料矛盾","examples":[{"en":"A statement is false if it contradicts the information in the passage.","zh":"如果陳述與文章中的資料矛盾，它就是 false。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"contradict the information 指說法與文本所說相反。"},{"en":"If a passage says a study began in 1998, a statement saying 2008 contradicts the information.","zh":"如果文章說研究於 1998 年開始，而陳述說 2008 年，就與資料矛盾。"},{"en":"Students should choose FALSE only when the statement clearly conflicts with the text.","zh":"只有當陳述明顯與文本衝突時，學生才應選 FALSE。"},{"en":"This phrase means there is conflict, not just missing detail.","zh":"這個短語表示有衝突，而不只是缺少細節。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":19},{"front":"there is no information on this","meaning":"文中沒有相關資料","examples":[{"en":"Students choose NOT GIVEN if there is no information on this.","zh":"如果文中沒有相關資料，學生選 NOT GIVEN。"},{"en":"There is no information on this means the passage does not clearly say anything about the point.","zh":"there is no information on this 指文章沒有清楚說明該點。"},{"en":"If a passage describes a scientist’s work but not his age, there is no information on his age.","zh":"如果文章描述科學家的工作但沒有說他的年齡，文中就沒有關於年齡的相關資料。"},{"en":"Students should not guess TRUE or FALSE when there is no information on this.","zh":"當文中沒有相關資料時，學生不應猜 TRUE 或 FALSE。"},{"en":"This phrase is used when the answer cannot be proved from the text.","zh":"這個短語用於答案不能從文本中證明的情況。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":20},{"front":"the first person to","meaning":"第一個……的人","examples":[{"en":"The statement asks whether Wiggins was the first person to use DNA microarrays.","zh":"該陳述問 Wiggins 是否是第一個使用 DNA 微陣列的人。"},{"en":"The first person to do something is the earliest person known to have done it.","zh":"the first person to do something 指已知最早做某事的人。"},{"en":"A school may celebrate the first person to win a national prize.","zh":"學校可能慶祝第一個贏得全國獎項的人。"},{"en":"Claims about being the first person to do something need strong evidence.","zh":"關於第一個做某事的說法需要強力證據。"},{"en":"This phrase focuses on order in time.","zh":"這個短語著重時間先後次序。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":20},{"front":"study genes","meaning":"研究基因","examples":[{"en":"DNA microarrays can be used to study genes.","zh":"DNA 微陣列可以用來研究基因。"},{"en":"To study genes means to examine how genes are structured, used, or passed on.","zh":"study genes 指研究基因的結構、使用方式或遺傳方式。"},{"en":"Biology students study genes when they learn why children may look like their parents.","zh":"生物學生學習為何孩子可能像父母時，就是在研究基因。"},{"en":"Scientists study genes to understand disease, development, and cell behaviour.","zh":"科學家研究基因，以理解疾病、發育和細胞行為。"},{"en":"This phrase covers many kinds of genetic investigation.","zh":"這個短語涵蓋多種遺傳研究。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":20},{"front":"almost impossible to","meaning":"幾乎不可能","examples":[{"en":"The question asks whether it is almost impossible to reduce interactions to laws.","zh":"題目問把相互作用簡化為定律是否幾乎不可能。"},{"en":"Almost impossible to do something means extremely difficult, but not fully impossible.","zh":"almost impossible to do something 指極度困難，但並非完全不可能。"},{"en":"It is almost impossible to study well if a student sleeps only two hours a night.","zh":"如果學生一晚只睡兩小時，幾乎不可能好好溫習。"},{"en":"A task becomes almost impossible when there are too many unknowns and too little time.","zh":"當未知因素太多而時間太少，任務會變得幾乎不可能。"},{"en":"This phrase expresses very strong difficulty without saying zero chance.","zh":"這個短語表達非常強烈的困難，但不是說完全沒有機會。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":20},{"front":"interaction patterns","meaning":"相互作用模式","examples":[{"en":"Interaction patterns among DNA, RNA and proteins are highly complex.","zh":"DNA、RNA 和蛋白質之間的相互作用模式高度複雜。"},{"en":"Interaction patterns are repeated ways in which parts of a system affect one another.","zh":"interaction patterns 指系統各部分互相影響的重複方式。"},{"en":"A teacher may notice interaction patterns between group size and student participation.","zh":"老師可能注意到小組大小和學生參與之間的相互作用模式。"},{"en":"Complex interaction patterns make simple explanations difficult.","zh":"複雜相互作用模式會令簡單解釋變得困難。"},{"en":"This phrase focuses on repeated relationships inside a system.","zh":"這個短語著重系統內部的重複關係。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":20},{"front":"optimistic about","meaning":"對……樂觀","examples":[{"en":"The statement asks whether Wiggins is optimistic about genetic research.","zh":"該陳述問 Wiggins 是否對基因研究樂觀。"},{"en":"To be optimistic about something means to believe it will develop well or have good results.","zh":"optimistic about something 指相信某事會良好發展或有好結果。"},{"en":"A teacher may be optimistic about a student’s progress after seeing steady improvement.","zh":"老師看見學生穩定進步後，可能對其進展感到樂觀。"},{"en":"People become optimistic when they see evidence that a problem can be solved.","zh":"當人們看見問題可以解決的證據，就會變得樂觀。"},{"en":"This phrase expresses positive expectation, not certainty.","zh":"這個短語表達正面期望，而不是確定。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":20},{"front":"genetic research","meaning":"基因研究","examples":[{"en":"Machine learning may change the future of genetic research.","zh":"機器學習可能改變基因研究的未來。"},{"en":"Genetic research is scientific study of genes, heredity, and gene activity.","zh":"genetic research 指對基因、遺傳和基因活動的科學研究。"},{"en":"Genetic research can help doctors understand inherited diseases.","zh":"基因研究可以幫助醫生理解遺傳疾病。"},{"en":"New tools can make genetic research faster, deeper, and more data-driven.","zh":"新工具可以令基因研究更快、更深入、更以數據為本。"},{"en":"This phrase refers to research about genes and genetic information.","zh":"這個短語指關於基因和遺傳資訊的研究。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":20},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Candidates complete the summary below using words from the passage.","zh":"考生使用文章中的字詞完成以下摘要。"},{"en":"To complete the summary below means to fill in missing words in the summary under the instruction.","zh":"complete the summary below 指填寫指示下方摘要中的空缺字詞。"},{"en":"Students should check grammar before completing the summary below.","zh":"學生在完成以下摘要前應檢查文法。"},{"en":"Reading the relevant paragraph carefully helps students choose words that fit both meaning and form.","zh":"仔細閱讀相關段落，幫助學生選擇意思和形式都合適的字詞。"},{"en":"This phrase is common in reading tests with short-answer gaps.","zh":"這個短語常見於有短答案空格的閱讀測驗。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":20},{"front":"no more than three words","meaning":"不多於三個字","examples":[{"en":"Students must choose no more than three words from the passage.","zh":"學生必須從文章中選擇不多於三個字。"},{"en":"No more than three words means one, two, or three words, but not four.","zh":"no more than three words 指一個、兩個或三個字，但不是四個。"},{"en":"If the answer limit is no more than three words, “machine learning algorithms” is allowed.","zh":"如果答案限制是不多於三個字，“machine learning algorithms” 是可以的。"},{"en":"Writing too many words can lose marks even if the idea is correct.","zh":"即使意思正確，寫太多字也可能失分。"},{"en":"This phrase gives a strict limit on answer length.","zh":"這個短語對答案長度作出嚴格限制。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":20},{"front":"rapid advances in","meaning":"……方面的快速進步","examples":[{"en":"Rapid advances in techniques changed biological research.","zh":"技術方面的快速進步改變了生物研究。"},{"en":"Rapid advances in something are fast improvements or developments in that area.","zh":"rapid advances in something 指某方面快速改善或發展。"},{"en":"Rapid advances in mobile technology changed how people study and work.","zh":"流動科技方面的快速進步改變了人們學習和工作的方式。"},{"en":"Rapid advances can create new opportunities, but they can also make old skills outdated.","zh":"快速進步可以創造新機會，但也可能令舊技能過時。"},{"en":"This phrase highlights quick progress.","zh":"這個短語強調快速發展。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":20},{"front":"genetic components","meaning":"遺傳組成部分","examples":[{"en":"Researchers used new techniques to study genetic components.","zh":"研究人員使用新技術研究遺傳組成部分。"},{"en":"Genetic components are parts of the genetic system, such as DNA, genes, RNA, or related regulators.","zh":"genetic components 指遺傳系統的部分，例如 DNA、基因、RNA 或相關調控因子。"},{"en":"In biology class, students learn that genes are important genetic components.","zh":"在生物課中，學生學到基因是重要的遺傳組成部分。"},{"en":"Studying genetic components helps scientists understand how cells develop and function.","zh":"研究遺傳組成部分幫助科學家理解細胞如何發育和運作。"},{"en":"This phrase refers to the parts that make up genetic processes.","zh":"這個短語指構成遺傳過程的部分。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":21},{"front":"prompt someone to","meaning":"促使某人去","examples":[{"en":"New techniques prompted researchers to rethink biological phenomena.","zh":"新技術促使研究人員重新思考生物現象。"},{"en":"To prompt someone to do something means to cause or encourage them to do it.","zh":"prompt someone to do something 指促使或鼓勵某人做某事。"},{"en":"A low test score may prompt a student to change study habits.","zh":"低測驗分數可能促使學生改變學習習慣。"},{"en":"New evidence can prompt researchers to ask different questions.","zh":"新證據可以促使研究人員提出不同問題。"},{"en":"This phrase links a cause with a response or action.","zh":"這個短語把原因與回應或行動連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":21},{"front":"look at something in a new way","meaning":"以新方式看待……","examples":[{"en":"Researchers began to look at biological phenomena in a completely new way.","zh":"研究人員開始以一種全新方式看待生物現象。"},{"en":"To look at something in a new way means to understand or examine it from a different perspective.","zh":"look at something in a new way 指從不同角度理解或研究某事。"},{"en":"A teacher may help students look at mistakes in a new way, as feedback rather than failure.","zh":"老師可能幫助學生以新方式看待錯誤，把它們視為回饋而不是失敗。"},{"en":"New tools can make people look at old problems in a new way.","zh":"新工具可以令人以新方式看待舊問題。"},{"en":"This phrase suggests a change in perspective.","zh":"這個短語表示視角改變。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":21},{"front":"central to","meaning":"對……至關重要","examples":[{"en":"DNA microarrays are central to these research techniques.","zh":"DNA 微陣列對這些研究技術至關重要。"},{"en":"Central to something means extremely important to it.","zh":"central to something 指對某事極為重要。"},{"en":"Clear communication is central to good teamwork.","zh":"清楚溝通對良好團隊合作至關重要。"},{"en":"If a tool is central to research, the research depends heavily on it.","zh":"如果某工具對研究至關重要，該研究就高度依賴它。"},{"en":"This phrase marks the most important part of a process or idea.","zh":"這個短語標示過程或概念中最重要的部分。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":21},{"front":"despite the conditions under which","meaning":"儘管是在……條件下","examples":[{"en":"The data were useful despite the conditions under which measurements were taken.","zh":"儘管量度是在某些條件下進行，數據仍然有用。"},{"en":"Despite the conditions under which something happens means although the surrounding situation was difficult or imperfect.","zh":"despite the conditions under which something happens 指儘管某事發生時的周圍情況困難或不完美。"},{"en":"The outdoor lesson was successful despite the conditions under which it was held, including heat and noise.","zh":"儘管戶外課是在炎熱和嘈雜等條件下舉行，它仍然成功。"},{"en":"Data can still be useful despite imperfect measurement conditions if patterns remain clear.","zh":"如果模式仍清楚，即使量度條件不完美，數據仍可能有用。"},{"en":"This phrase contrasts difficult conditions with a positive result.","zh":"這個短語把困難條件與正面結果作對比。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":21},{"front":"measurements were taken","meaning":"進行量度","examples":[{"en":"Measurements were taken under many different conditions.","zh":"量度在許多不同條件下進行。"},{"en":"Measurements were taken means data were collected by measuring something.","zh":"measurements were taken 指透過量度收集數據。"},{"en":"Temperature measurements were taken every hour during the science experiment.","zh":"在科學實驗期間，每小時進行一次溫度量度。"},{"en":"If measurements are taken carefully, the results become more reliable.","zh":"如果量度仔細進行，結果會更可靠。"},{"en":"This phrase is common in scientific reporting.","zh":"這個短語常見於科學報告。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":21},{"front":"in every type of cell","meaning":"在每一類細胞中","examples":[{"en":"Gene activity can be measured in every type of cell.","zh":"基因活動可以在每一類細胞中被量度。"},{"en":"In every type of cell means across all categories of cells being considered.","zh":"in every type of cell 指在所考慮的所有細胞類別中。"},{"en":"Scientists may ask whether a certain gene is active in every type of cell or only in some.","zh":"科學家可能問某基因是在每一類細胞中都活躍，還是只在某些細胞中活躍。"},{"en":"If a method works in every type of cell, it can be widely useful.","zh":"如果一種方法在每一類細胞中都有效，它就可以廣泛有用。"},{"en":"This phrase stresses complete coverage across cell categories.","zh":"這個短語強調涵蓋所有細胞類別。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":21},{"front":"switch on or off","meaning":"開啟或關閉","examples":[{"en":"Scientists can identify which genes switch on or off.","zh":"科學家可以識別哪些基因開啟或關閉。"},{"en":"When genes switch on or off, they become active or inactive.","zh":"當基因 switch on or off，意思是它們變得活躍或不活躍。"},{"en":"A lamp switches on or off, and scientists use the same image to explain gene control.","zh":"燈可以開啟或關閉，科學家使用同一意象來解釋基因控制。"},{"en":"If a gene switches on, it may begin producing RNA.","zh":"如果基因開啟，它可能開始產生 RNA。"},{"en":"This phrase makes gene activity easier to understand through the idea of a switch.","zh":"這個短語透過開關概念令基因活動更容易理解。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":21},{"front":"affect protein production","meaning":"影響蛋白質生產","examples":[{"en":"Genes that switch on or off can affect protein production.","zh":"開啟或關閉的基因可以影響蛋白質生產。"},{"en":"To affect protein production means to change how much or what kind of protein a cell makes.","zh":"affect protein production 指改變細胞製造多少蛋白質或製造哪種蛋白質。"},{"en":"A mutation may affect protein production if it changes the genetic instructions.","zh":"如果突變改變遺傳指令，它可能影響蛋白質生產。"},{"en":"When protein production changes, cell behaviour may also change.","zh":"當蛋白質生產改變，細胞行為也可能改變。"},{"en":"This phrase links gene activity with the proteins cells produce.","zh":"這個短語把基因活動與細胞製造的蛋白質連繫起來。"}],"source":"122 - Life code - unlocked!.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 123":[{"front":"flight from reality","meaning":"逃離現實；空中現實議題","examples":[{"en":"The title “Flight from Reality” suggests a debate about technology use during air travel.","zh":"標題 “Flight from Reality” 暗示一場關於航空旅程中使用科技的討論。"},{"en":"Flight from reality can mean escaping ordinary life, but here it also plays on the word flight as air travel.","zh":"flight from reality 可以指逃離日常現實，但在這裡也利用 flight 作「飛行」的意思。"},{"en":"A film, game, or long journey can offer a flight from reality when people want a break from daily stress.","zh":"電影、遊戲或長途旅程可以在人們想暫時避開日常壓力時，提供逃離現實的感覺。"},{"en":"If technology lets passengers work or call others in the air, the flight from reality becomes less complete.","zh":"如果科技讓乘客在空中工作或打電話，這種逃離現實就變得不再完整。"},{"en":"The phrase is clever because it connects emotional escape with an actual plane flight.","zh":"這個短語很巧妙，因為它把情感上的逃避與真正的飛行連起來。"}],"source":"123 - Flight from reality.pdf","sourcePage":1},{"front":"mobiles are barred","meaning":"手提電話被禁止","examples":[{"en":"Mobiles are barred on planes, but passengers can still use laptops.","zh":"飛機上手提電話被禁止，但乘客仍可以使用手提電腦。"},{"en":"If mobiles are barred, people are officially not allowed to use mobile phones.","zh":"如果 mobiles are barred，意思是人們被正式禁止使用手提電話。"},{"en":"Mobiles may be barred in exam rooms so students cannot search for answers.","zh":"考試室可能禁止手提電話，以免學生搜尋答案。"},{"en":"When mobiles are barred during take-off, passengers must switch them off or use airplane mode.","zh":"當起飛期間手提電話被禁止，乘客必須關機或使用飛行模式。"},{"en":"The phrase is formal and means prohibited, not merely discouraged.","zh":"這個短語較正式，意思是被禁止，而不只是被勸阻。"}],"source":"123 - Flight from reality.pdf","sourcePage":1},{"front":"tap away on","meaning":"不停敲打；不停使用","examples":[{"en":"Passengers can tap away on their laptops during a flight.","zh":"乘客可以在航班上不停敲打手提電腦鍵盤。"},{"en":"To tap away on a device means to keep typing or pressing keys for some time.","zh":"tap away on a device 指持續在裝置上打字或按鍵一段時間。"},{"en":"A student may tap away on a laptop while taking notes in class.","zh":"學生可能在課堂上不停敲打手提電腦做筆記。"},{"en":"If someone taps away during dinner, others may feel ignored.","zh":"如果有人晚飯時不停打字，其他人可能覺得被忽視。"},{"en":"The phrase suggests repeated light typing, not one single touch.","zh":"這個短語暗示反覆輕按或打字，而不是單一觸碰。"}],"source":"123 - Flight from reality.pdf","sourcePage":1},{"front":"to their hearts’ content","meaning":"盡情地；隨心所欲地","examples":[{"en":"Passengers can use laptops to their hearts’ content.","zh":"乘客可以盡情使用手提電腦。"},{"en":"To do something to your hearts’ content means to do it as much as you want.","zh":"do something to your hearts’ content 指隨心所欲地做某事，做到自己滿足為止。"},{"en":"Children can play in the park to their hearts’ content after finishing homework.","zh":"孩子完成功課後，可以在公園盡情玩耍。"},{"en":"If passengers use laptops to their hearts’ content, they may work or watch films for the whole flight.","zh":"如果乘客盡情使用手提電腦，他們可能整個航班都工作或看電影。"},{"en":"The phrase suggests freedom and satisfaction without a strict limit.","zh":"這個短語暗示自由和滿足，而沒有嚴格限制。"}],"source":"123 - Flight from reality.pdf","sourcePage":1},{"front":"safer than","meaning":"比……更安全","examples":[{"en":"The article asks whether one electronic device is safer than another.","zh":"文章問一種電子裝置是否比另一種更安全。"},{"en":"Safer than means having less danger or risk compared with something else.","zh":"safer than 指與另一事物相比危險或風險較低。"},{"en":"Wearing a seat belt is safer than sitting in a car without one.","zh":"繫安全帶比在車內不繫安全帶更安全。"},{"en":"If laptops are safer than phones on planes, airlines may allow one but ban the other.","zh":"如果手提電腦在飛機上比電話更安全，航空公司可能准許一種而禁止另一種。"},{"en":"The phrase clearly compares two levels of risk.","zh":"這個短語清楚比較兩種風險水平。"}],"source":"123 - Flight from reality.pdf","sourcePage":1},{"front":"Congressional subcommittee","meaning":"國會小組委員會","examples":[{"en":"A Congressional subcommittee discussed the use of mobile phones on planes.","zh":"一個國會小組委員會討論飛機上使用手提電話的問題。"},{"en":"A Congressional subcommittee is a smaller group within the US Congress that examines a specific issue.","zh":"Congressional subcommittee 指美國國會內負責審視特定議題的較小小組。"},{"en":"A Congressional subcommittee may question experts before suggesting new rules.","zh":"國會小組委員會可能在建議新規則前盤問專家。"},{"en":"When safety worries increase, a Congressional subcommittee can hold hearings to gather evidence.","zh":"當安全憂慮增加，國會小組委員會可以舉行聽證會收集證據。"},{"en":"The phrase refers to an official political body, not an ordinary discussion group.","zh":"這個短語指正式政治機構，而不是普通討論小組。"}],"source":"123 - Flight from reality.pdf","sourcePage":1},{"front":"grill someone about","meaning":"就……盤問某人","examples":[{"en":"The subcommittee grilled airline representatives and regulators about the issue.","zh":"該小組委員會就該議題盤問航空公司代表和監管機構人員。"},{"en":"To grill someone about something means to question them very closely and forcefully.","zh":"grill someone about something 指就某事仔細而強硬地盤問某人。"},{"en":"A teacher may grill a student about missing homework if the excuse sounds unclear.","zh":"如果理由聽起來不清楚，老師可能就欠交功課盤問學生。"},{"en":"Politicians grill officials when the public wants clear answers about safety.","zh":"當公眾希望獲得清晰安全答案，政客會盤問官員。"},{"en":"The phrase suggests intense questioning, not casual conversation.","zh":"這個短語暗示強烈追問，而不是普通聊天。"}],"source":"123 - Flight from reality.pdf","sourcePage":1},{"front":"airline representatives","meaning":"航空公司代表","examples":[{"en":"Airline representatives were questioned about electronic devices on planes.","zh":"航空公司代表被問及飛機上的電子裝置問題。"},{"en":"Airline representatives are people who speak or answer questions on behalf of airlines.","zh":"airline representatives 指代表航空公司發言或回答問題的人。"},{"en":"Airline representatives may explain ticket policies, safety rules, or passenger complaints.","zh":"航空公司代表可能解釋機票政策、安全規則或乘客投訴。"},{"en":"If a flight is delayed, airline representatives must tell passengers what options they have.","zh":"如果航班延誤，航空公司代表必須告訴乘客有哪些選擇。"},{"en":"The phrase focuses on people representing a company, not ordinary passengers.","zh":"這個短語重點是代表公司的人，而不是普通乘客。"}],"source":"123 - Flight from reality.pdf","sourcePage":1},{"front":"regulators","meaning":"監管機構人員","examples":[{"en":"Regulators were asked whether mobile phones pose a risk on aircraft.","zh":"監管機構人員被問到手提電話是否對飛機構成風險。"},{"en":"Regulators are officials or organisations that make and enforce rules for an industry.","zh":"regulators 指為某行業制定並執行規則的官員或機構。"},{"en":"Aviation regulators check whether airlines follow safety standards.","zh":"航空監管機構檢查航空公司是否遵守安全標準。"},{"en":"When technology changes quickly, regulators must decide whether old rules still work.","zh":"當科技快速改變，監管者必須決定舊規則是否仍有效。"},{"en":"The word refers to rule-makers and supervisors, not company sales staff.","zh":"這個詞指制定規則和監督的人，而不是公司銷售人員。"}],"source":"123 - Flight from reality.pdf","sourcePage":1},{"front":"the issue","meaning":"該議題；該問題","examples":[{"en":"The issue was whether mobile phones are dangerous on planes.","zh":"該議題是手提電話在飛機上是否危險。"},{"en":"The issue means the main question, problem, or topic being discussed.","zh":"the issue 指正在討論的主要問題、難題或主題。"},{"en":"In a school meeting, the issue may be whether phones should be allowed in class.","zh":"在學校會議中，該議題可能是課堂上是否應准許使用手機。"},{"en":"If people misunderstand the issue, they may argue about the wrong problem.","zh":"如果人們誤解該問題，他們可能會爭論錯誤的焦點。"},{"en":"The phrase helps identify the central point of a debate.","zh":"這個短語幫助指出辯論的核心。"}],"source":"123 - Flight from reality.pdf","sourcePage":1},{"front":"pose a risk","meaning":"構成風險","examples":[{"en":"Using cellphones in planes may indeed pose a risk.","zh":"在飛機上使用手提電話確實可能構成風險。"},{"en":"To pose a risk means to create a possible danger.","zh":"pose a risk 指造成可能的危險。"},{"en":"Wet floors pose a risk because people may slip and fall.","zh":"濕滑地板會構成風險，因為人們可能滑倒。"},{"en":"If a device emits strong signals, it may pose a risk to sensitive equipment.","zh":"如果裝置發出強訊號，它可能對敏感設備構成風險。"},{"en":"The phrase means danger is possible, not always certain.","zh":"這個短語表示危險有可能存在，而不一定必然發生。"}],"source":"123 - Flight from reality.pdf","sourcePage":1},{"front":"albeit a slight one","meaning":"雖然只是輕微的","examples":[{"en":"Mobile-phone use may pose a risk, albeit a slight one.","zh":"使用手提電話可能構成風險，雖然只是輕微的。"},{"en":"Albeit a slight one means although the risk or problem is small.","zh":"albeit a slight one 指雖然該風險或問題很小。"},{"en":"The medicine caused a side effect, albeit a slight one, so the doctor continued treatment.","zh":"藥物造成副作用，雖然只是輕微的，所以醫生繼續治療。"},{"en":"A small signal may still matter on aircraft, albeit a slight one in normal conditions.","zh":"一個小訊號在飛機上仍可能重要，雖然在正常情況下只是輕微風險。"},{"en":"The phrase admits a limitation while keeping the main point.","zh":"這個短語承認限制，同時保留主要觀點。"}],"source":"123 - Flight from reality.pdf","sourcePage":2},{"front":"seem to vindicate","meaning":"似乎證明……是合理的","examples":[{"en":"The findings seem to vindicate the treatment of Neil Whitehouse.","zh":"研究結果似乎證明 Neil Whitehouse 所受處理是合理的。"},{"en":"To seem to vindicate something means to appear to prove that it was right or justified.","zh":"seem to vindicate something 指似乎證明某事是正確或有理據的。"},{"en":"New test results may seem to vindicate a teacher’s decision to give extra practice.","zh":"新測驗結果可能似乎證明老師安排額外練習是合理的。"},{"en":"If later evidence shows a rule reduced danger, it may vindicate the strict policy.","zh":"如果後來證據顯示某規則降低危險，它可能證明嚴格政策合理。"},{"en":"The phrase suggests support, but seem to leaves some uncertainty.","zh":"這個短語暗示支持，但 seem to 保留一些不確定性。"}],"source":"123 - Flight from reality.pdf","sourcePage":2},{"front":"be sentenced to","meaning":"被判處","examples":[{"en":"Neil Whitehouse was sentenced to a year in jail.","zh":"Neil Whitehouse 被判處一年監禁。"},{"en":"To be sentenced to a punishment means to receive that punishment from a court.","zh":"be sentenced to a punishment 指由法庭判決接受某種懲罰。"},{"en":"A driver may be sentenced to community service after a serious traffic offence.","zh":"司機可能因嚴重交通罪行被判處社會服務令。"},{"en":"If someone is sentenced to jail, the court has decided imprisonment is the penalty.","zh":"如果某人被判處監禁，法庭已決定以入獄作為刑罰。"},{"en":"The phrase is legal and should be used for formal punishment.","zh":"這個短語屬法律用語，應用於正式懲罰。"}],"source":"123 - Flight from reality.pdf","sourcePage":2},{"front":"a year in jail","meaning":"一年監禁","examples":[{"en":"The passenger was sentenced to a year in jail for refusing to turn off his phone.","zh":"該乘客因拒絕關掉電話而被判一年監禁。"},{"en":"A year in jail means twelve months of imprisonment.","zh":"a year in jail 指十二個月監禁。"},{"en":"A person may receive a year in jail if a court treats the offence as serious.","zh":"如果法庭認為罪行嚴重，一個人可能被判一年監禁。"},{"en":"The threat of a year in jail can show how seriously authorities view safety rules.","zh":"一年監禁的可能性可以顯示當局多麼重視安全規則。"},{"en":"The phrase refers to punishment by imprisonment, not a fine.","zh":"這個短語指以監禁作懲罰，而不是罰款。"}],"source":"123 - Flight from reality.pdf","sourcePage":2},{"front":"refuse to turn off","meaning":"拒絕關掉","examples":[{"en":"He refused to turn off his mobile phone on the flight.","zh":"他在航班上拒絕關掉手提電話。"},{"en":"To refuse to turn off a device means to say no when asked to switch it off.","zh":"refuse to turn off a device 指被要求關機時拒絕照做。"},{"en":"A student may get into trouble if he refuses to turn off his phone during an exam.","zh":"如果學生在考試期間拒絕關掉手機，他可能惹上麻煩。"},{"en":"Refusing to turn off a device can create conflict when safety rules require it.","zh":"當安全規則要求關機，拒絕關掉裝置可能造成衝突。"},{"en":"The phrase shows deliberate non-compliance, not forgetting.","zh":"這個短語表示故意不遵守，而不是忘記。"}],"source":"123 - Flight from reality.pdf","sourcePage":2},{"front":"on a flight home from","meaning":"在從……回家的航班上","examples":[{"en":"He refused to turn off his phone on a flight home from Madrid.","zh":"他在從馬德里回家的航班上拒絕關掉電話。"},{"en":"On a flight home from a place means during a plane journey returning from that place.","zh":"on a flight home from a place 指在從某地回家的飛行旅程中。"},{"en":"A traveller may feel tired on a flight home from a long business trip.","zh":"旅客在長途公幹後回家的航班上可能感到疲倦。"},{"en":"Problems on a flight home from holiday can feel especially frustrating because people want to rest.","zh":"假期後回家的航班上出現問題，會特別令人沮喪，因為人們想休息。"},{"en":"The phrase gives both travel setting and direction.","zh":"這個短語同時提供旅程情境和方向。"}],"source":"123 - Flight from reality.pdf","sourcePage":2},{"front":"type a message","meaning":"輸入訊息","examples":[{"en":"He was only typing a message to be sent after landing.","zh":"他只是在輸入一條着陸後才發送的訊息。"},{"en":"To type a message means to write words on a phone, computer, or other device.","zh":"type a message 指在電話、電腦或其他裝置上輸入文字。"},{"en":"A passenger may type a message during a flight and send it after reaching the airport.","zh":"乘客可能在航班上輸入訊息，抵達機場後才發送。"},{"en":"Typing a message can still break rules if using the device itself is not allowed.","zh":"如果使用裝置本身不被准許，輸入訊息仍可能違反規則。"},{"en":"The phrase describes writing text, not making a voice call.","zh":"這個短語描述寫文字，而不是打語音電話。"}],"source":"123 - Flight from reality.pdf","sourcePage":2},{"front":"to be sent on landing","meaning":"着陸後才發送","examples":[{"en":"The message was to be sent on landing.","zh":"該訊息是着陸後才發送的。"},{"en":"To be sent on landing means planned to be sent after the plane has landed.","zh":"to be sent on landing 指計劃在飛機着陸後才發送。"},{"en":"A passenger may write an email during the flight to be sent on landing.","zh":"乘客可能在飛行期間寫電郵，準備着陸後才發送。"},{"en":"If a message is to be sent on landing, it is not actually transmitted while the plane is in the air.","zh":"如果訊息是着陸後才發送，它在飛行中其實沒有傳輸。"},{"en":"The phrase shows future timing after arrival on the ground.","zh":"這個短語顯示抵達地面後的未來時間。"}],"source":"123 - Flight from reality.pdf","sourcePage":2},{"front":"make a call","meaning":"打電話","examples":[{"en":"He was typing a message, not actually making a call.","zh":"他是在輸入訊息，而不是真的在打電話。"},{"en":"To make a call means to use a phone to speak to someone.","zh":"make a call 指用電話與某人說話。"},{"en":"A passenger may want to make a call after landing to tell family they have arrived.","zh":"乘客可能想在着陸後打電話告訴家人自己已抵達。"},{"en":"Making a call can produce signals that worry aviation regulators.","zh":"打電話可能產生令航空監管者擔心的訊號。"},{"en":"The phrase refers to voice communication, not simply holding a phone.","zh":"這個短語指語音通訊，而不是單純拿着電話。"}],"source":"123 - Flight from reality.pdf","sourcePage":2},{"front":"put the flight at risk","meaning":"使航班陷入危險","examples":[{"en":"The court decided that he was putting the flight at risk.","zh":"法庭裁定他正在使航班陷入危險。"},{"en":"To put the flight at risk means to create possible danger for the plane, passengers, or crew.","zh":"put the flight at risk 指對飛機、乘客或機組人員造成可能危險。"},{"en":"Ignoring safety instructions can put a bus journey or flight at risk.","zh":"忽視安全指示可以使巴士旅程或航班陷入危險。"},{"en":"If a device interferes with equipment, it may put the flight at risk even without visible damage.","zh":"如果裝置干擾設備，即使沒有可見損害，也可能使航班陷入危險。"},{"en":"The phrase describes a serious safety concern.","zh":"這個短語描述嚴重安全憂慮。"}],"source":"123 - Flight from reality.pdf","sourcePage":2},{"front":"potential for problems","meaning":"出現問題的可能性","examples":[{"en":"The potential for problems is certainly there.","zh":"出現問題的可能性確實存在。"},{"en":"Potential for problems means the possibility that difficulties or dangers may happen.","zh":"potential for problems 指困難或危險可能發生的可能性。"},{"en":"A crowded event has potential for problems if exits are narrow and staff are few.","zh":"如果出口狹窄而職員太少，擠迫活動就有出現問題的可能性。"},{"en":"The potential for problems increases when rules are unclear or equipment is old.","zh":"當規則不清或設備老舊，出現問題的可能性會增加。"},{"en":"The phrase means trouble is possible, not guaranteed.","zh":"這個短語表示可能有麻煩，而不是一定會發生。"}],"source":"123 - Flight from reality.pdf","sourcePage":2},{"front":"modern airliners","meaning":"現代客機","examples":[{"en":"Modern airliners are packed with electronic devices.","zh":"現代客機充滿電子裝置。"},{"en":"Modern airliners are large passenger aircraft used today for commercial flights.","zh":"modern airliners 指現今用於商業航班的大型客運飛機。"},{"en":"Modern airliners rely on computers to help with navigation, communication, and safety monitoring.","zh":"現代客機依靠電腦協助導航、通訊和安全監察。"},{"en":"Because modern airliners use many electronic systems, interference is taken seriously.","zh":"由於現代客機使用許多電子系統，干擾問題會被認真看待。"},{"en":"The phrase refers to current commercial planes, not old military aircraft.","zh":"這個短語指現代商業客機，而不是舊式軍機。"}],"source":"123 - Flight from reality.pdf","sourcePage":3},{"front":"be packed with","meaning":"充滿；裝滿","examples":[{"en":"Modern aircraft are packed with electronic systems.","zh":"現代飛機充滿電子系統。"},{"en":"To be packed with something means to be full of it.","zh":"be packed with something 指充滿或裝滿某物。"},{"en":"A student’s bag may be packed with books before an exam.","zh":"考試前，學生的書包可能裝滿書本。"},{"en":"If a plane is packed with electronics, even small signals may be considered carefully.","zh":"如果飛機充滿電子設備，即使小訊號也可能要仔細考慮。"},{"en":"The phrase suggests a large amount in a limited space.","zh":"這個短語暗示有限空間中有大量東西。"}],"source":"123 - Flight from reality.pdf","sourcePage":3},{"front":"electronic devices","meaning":"電子裝置","examples":[{"en":"Aircraft contain many electronic devices that control key systems.","zh":"飛機包含許多控制關鍵系統的電子裝置。"},{"en":"Electronic devices are machines or tools that use electricity and circuits to work.","zh":"electronic devices 指使用電力和電路運作的機器或工具。"},{"en":"Phones, laptops, tablets, and digital watches are electronic devices.","zh":"電話、手提電腦、平板電腦和電子手錶都是電子裝置。"},{"en":"Electronic devices can be useful, but on aircraft their signals may raise safety questions.","zh":"電子裝置可以有用，但在飛機上，它們的訊號可能引起安全問題。"},{"en":"The phrase covers many kinds of powered equipment, not only mobile phones.","zh":"這個短語涵蓋多種有電力設備，而不只是手提電話。"}],"source":"123 - Flight from reality.pdf","sourcePage":3},{"front":"control the plane","meaning":"控制飛機","examples":[{"en":"Electronic devices control the plane and handle navigation.","zh":"電子裝置控制飛機並處理導航。"},{"en":"To control the plane means to manage the aircraft’s movement, direction, or operation.","zh":"control the plane 指管理飛機的移動、方向或運作。"},{"en":"Pilots use instruments and systems to control the plane safely.","zh":"機師使用儀器和系統安全地控制飛機。"},{"en":"If equipment that helps control the plane fails, the flight crew may face serious pressure.","zh":"如果協助控制飛機的設備失效，機組人員可能面對嚴重壓力。"},{"en":"The phrase refers to aircraft operation, not passenger behaviour.","zh":"這個短語指飛機操作，而不是乘客行為。"}],"source":"123 - Flight from reality.pdf","sourcePage":3},{"front":"handle navigation and communications","meaning":"處理導航及通訊","examples":[{"en":"Modern aircraft systems handle navigation and communications.","zh":"現代飛機系統處理導航及通訊。"},{"en":"To handle navigation and communications means to manage direction-finding and message exchange.","zh":"handle navigation and communications 指管理定位方向和訊息交流。"},{"en":"Ships also need systems that handle navigation and communications at sea.","zh":"船隻在海上也需要處理導航及通訊的系統。"},{"en":"If these systems fail, crews may struggle to know where they are or contact others.","zh":"如果這些系統失效，機組人員可能難以知道位置或聯絡他人。"},{"en":"The phrase describes two essential transport functions.","zh":"這個短語描述兩項重要交通功能。"}],"source":"123 - Flight from reality.pdf","sourcePage":3},{"front":"meet stringent safeguards","meaning":"符合嚴格安全要求","examples":[{"en":"Each aircraft device must meet stringent safeguards.","zh":"每個飛機裝置都必須符合嚴格安全要求。"},{"en":"To meet stringent safeguards means to satisfy very strict safety protections or requirements.","zh":"meet stringent safeguards 指符合非常嚴格的安全保護或要求。"},{"en":"Hospital equipment must meet stringent safeguards before it is used on patients.","zh":"醫院設備在用於病人前必須符合嚴格安全要求。"},{"en":"If aircraft electronics meet stringent safeguards, they are less likely to interfere with one another.","zh":"如果飛機電子設備符合嚴格安全要求，它們互相干擾的可能性較低。"},{"en":"The phrase stresses strict safety control.","zh":"這個短語強調嚴格安全控制。"}],"source":"123 - Flight from reality.pdf","sourcePage":3},{"front":"stringent safeguards","meaning":"嚴格安全措施","examples":[{"en":"Stringent safeguards help prevent electronic interference.","zh":"嚴格安全措施有助防止電子干擾。"},{"en":"Stringent safeguards are strict rules, tests, or protections designed to reduce danger.","zh":"stringent safeguards 指旨在降低危險的嚴格規則、測試或保護措施。"},{"en":"Laboratories use stringent safeguards when handling dangerous chemicals.","zh":"實驗室處理危險化學品時會使用嚴格安全措施。"},{"en":"Strong safeguards can prevent small technical faults from becoming serious accidents.","zh":"強力安全措施可以防止小技術故障變成嚴重事故。"},{"en":"The phrase suggests protection that is careful and demanding.","zh":"這個短語暗示保護措施仔細而要求高。"}],"source":"123 - Flight from reality.pdf","sourcePage":3},{"front":"make sure","meaning":"確保","examples":[{"en":"Standards make sure devices do not interfere with one another.","zh":"標準確保裝置不會互相干擾。"},{"en":"To make sure means to check or arrange things so that something happens correctly.","zh":"make sure 指檢查或安排事情，以確保某事正確發生。"},{"en":"A teacher may make sure every student understands the instructions before an exam.","zh":"老師可能在考試前確保每名學生都明白指示。"},{"en":"Airlines make sure safety rules are followed to reduce risk.","zh":"航空公司確保安全規則被遵守，以降低風險。"},{"en":"The phrase is common and practical, meaning ensure.","zh":"這個短語常見且實用，意思是 ensure。"}],"source":"123 - Flight from reality.pdf","sourcePage":3},{"front":"emit radiation","meaning":"發出輻射","examples":[{"en":"Devices must not emit radiation that interferes with other equipment.","zh":"裝置不得發出會干擾其他設備的輻射。"},{"en":"To emit radiation means to send out energy waves or signals.","zh":"emit radiation 指發出能量波或訊號。"},{"en":"A phone can emit radiation when it communicates with a network.","zh":"電話與網絡通訊時可以發出輻射。"},{"en":"If a device emits radiation near sensitive equipment, interference may become possible.","zh":"如果裝置在敏感設備附近發出輻射，干擾就可能發生。"},{"en":"The phrase is technical and focuses on energy being sent out.","zh":"這個短語較技術性，重點是能量被發出。"}],"source":"123 - Flight from reality.pdf","sourcePage":3},{"front":"interfere with","meaning":"干擾","examples":[{"en":"Radiation may interfere with other devices in the plane.","zh":"輻射可能干擾飛機內其他裝置。"},{"en":"To interfere with something means to disturb it or stop it from working properly.","zh":"interfere with something 指干擾某事或阻止其正常運作。"},{"en":"Loud noise can interfere with students’ concentration during a test.","zh":"巨大噪音可以在測驗期間干擾學生專注力。"},{"en":"A strong signal may interfere with aircraft equipment if it reaches the wrong system.","zh":"如果強訊號到達錯誤系統，可能干擾飛機設備。"},{"en":"The phrase suggests harmful disturbance, not helpful involvement.","zh":"這個短語暗示有害干擾，而不是有益參與。"}],"source":"123 - Flight from reality.pdf","sourcePage":3},{"front":"personal electronic devices","meaning":"個人電子裝置","examples":[{"en":"Passengers’ personal electronic devices may not meet aircraft standards.","zh":"乘客的個人電子裝置可能不符合飛機標準。"},{"en":"Personal electronic devices are privately owned devices such as phones, laptops, tablets, and game machines.","zh":"personal electronic devices 指私人擁有的裝置，例如電話、手提電腦、平板電腦和遊戲機。"},{"en":"Passengers often carry personal electronic devices for work, entertainment, or communication.","zh":"乘客常攜帶個人電子裝置作工作、娛樂或通訊用途。"},{"en":"Because personal devices are not built for aircraft use, they may raise safety concerns.","zh":"由於個人裝置不是為飛機使用而設計，它們可能引起安全疑慮。"},{"en":"The phrase contrasts passenger-owned devices with aircraft equipment.","zh":"這個短語把乘客擁有的裝置與飛機設備作對比。"}],"source":"123 - Flight from reality.pdf","sourcePage":3},{"front":"don’t necessarily meet","meaning":"不一定符合","examples":[{"en":"Personal devices don’t necessarily meet the same safety standards.","zh":"個人裝置不一定符合相同安全標準。"},{"en":"Don’t necessarily meet means do not always satisfy a requirement or standard.","zh":"don’t necessarily meet 指不一定總是符合某項要求或標準。"},{"en":"Cheap chargers don’t necessarily meet strict safety rules.","zh":"便宜充電器不一定符合嚴格安全規則。"},{"en":"If devices don’t necessarily meet aircraft standards, regulators may restrict their use.","zh":"如果裝置不一定符合飛機標準，監管者可能限制其使用。"},{"en":"The phrase avoids saying all devices fail; it says uncertainty remains.","zh":"這個短語不是說所有裝置都不合格，而是說仍有不確定性。"}],"source":"123 - Flight from reality.pdf","sourcePage":4},{"front":"emissions from inside","meaning":"來自內部的發射訊號","examples":[{"en":"Emissions from inside the plane could interfere with antennae.","zh":"來自飛機內部的發射訊號可能干擾天線。"},{"en":"Emissions from inside are signals or energy sent out from devices within a place.","zh":"emissions from inside 指從某地方內部的裝置發出的訊號或能量。"},{"en":"Emissions from inside a building can sometimes disturb nearby electronic equipment.","zh":"建築物內部的發射訊號有時可能干擾附近電子設備。"},{"en":"If emissions from inside an aircraft reach sensitive systems, they may cause interference.","zh":"如果飛機內部的發射訊號到達敏感系統，它們可能造成干擾。"},{"en":"The phrase focuses on signals coming from within, not from outside.","zh":"這個短語重點是來自內部，而不是外部的訊號。"}],"source":"123 - Flight from reality.pdf","sourcePage":4},{"front":"sensitive antennae","meaning":"敏感天線","examples":[{"en":"Emissions could interfere with sensitive antennae on the plane.","zh":"發射訊號可能干擾飛機上的敏感天線。"},{"en":"Sensitive antennae are antennae that can detect weak signals but may also be affected by interference.","zh":"sensitive antennae 指能偵測微弱訊號，但也可能受干擾影響的天線。"},{"en":"A radio station uses antennae to receive or send signals.","zh":"電台使用天線接收或發送訊號。"},{"en":"If sensitive antennae pick up unwanted signals, communication may become less clear.","zh":"如果敏感天線接收到不想要的訊號，通訊可能變得不清楚。"},{"en":"The phrase describes equipment that reacts easily to signals.","zh":"這個短語描述容易對訊號作出反應的設備。"}],"source":"123 - Flight from reality.pdf","sourcePage":4},{"front":"fixed exterior","meaning":"固定外部","examples":[{"en":"The antennae are located on the fixed exterior of the aircraft.","zh":"天線位於飛機的固定外部。"},{"en":"The fixed exterior means the stable outside surface or structure of something.","zh":"fixed exterior 指某物穩定的外部表面或結構。"},{"en":"Cameras may be attached to the fixed exterior of a building for security.","zh":"攝影機可能安裝在建築物的固定外部以保安。"},{"en":"Equipment on the fixed exterior of an aircraft can be exposed to signals and weather.","zh":"飛機固定外部的設備可能暴露於訊號和天氣之中。"},{"en":"The phrase describes location on the outside, not inside the cabin.","zh":"這個短語描述外部位置，而不是機艙內部。"}],"source":"123 - Flight from reality.pdf","sourcePage":4},{"front":"despite running studies","meaning":"儘管進行了研究","examples":[{"en":"Despite running studies, researchers found no clear evidence of major problems.","zh":"儘管進行了研究，研究人員沒有找到重大問題的明確證據。"},{"en":"Despite running studies means although studies were carried out.","zh":"despite running studies 指雖然已進行研究。"},{"en":"Despite running surveys, the school still did not know why students were absent.","zh":"儘管進行了調查，學校仍不知道學生缺席原因。"},{"en":"Sometimes, despite running studies, experts cannot prove a suspected risk.","zh":"有時儘管進行了研究，專家仍無法證明被懷疑的風險。"},{"en":"The phrase contrasts research effort with an uncertain result.","zh":"這個短語把研究努力與不確定結果作對比。"}],"source":"123 - Flight from reality.pdf","sourcePage":4},{"front":"a number of studies","meaning":"多項研究","examples":[{"en":"Boeing and Airbus have run a number of studies on electronic devices.","zh":"波音和空中巴士已對電子裝置進行多項研究。"},{"en":"A number of studies means several research projects or investigations.","zh":"a number of studies 指數項研究或調查。"},{"en":"A number of studies have examined how screen time affects sleep.","zh":"多項研究已檢視螢幕時間如何影響睡眠。"},{"en":"If a number of studies find no clear problem, the evidence may still remain incomplete.","zh":"如果多項研究都沒有發現明確問題，證據仍可能不完整。"},{"en":"The phrase is formal and avoids giving an exact count.","zh":"這個短語較正式，並避免給出確切數量。"}],"source":"123 - Flight from reality.pdf","sourcePage":4},{"front":"government agencies","meaning":"政府機構","examples":[{"en":"Government agencies have studied whether personal devices affect aircraft systems.","zh":"政府機構已研究個人裝置是否影響飛機系統。"},{"en":"Government agencies are official organisations that carry out public duties for the state.","zh":"government agencies 指為國家執行公共職責的官方組織。"},{"en":"Health agencies may issue advice during a disease outbreak.","zh":"衞生機構可能在疾病爆發期間發布建議。"},{"en":"When public safety is involved, government agencies may investigate and set rules.","zh":"當涉及公共安全，政府機構可能調查並制定規則。"},{"en":"The phrase refers to official bodies, not private companies.","zh":"這個短語指官方機構，而不是私人公司。"}],"source":"123 - Flight from reality.pdf","sourcePage":4},{"front":"clear evidence of","meaning":"……的明確證據","examples":[{"en":"Researchers have not found clear evidence of problems caused by mobile phones.","zh":"研究人員尚未找到手提電話造成問題的明確證據。"},{"en":"Clear evidence of something means strong and understandable proof that it exists.","zh":"clear evidence of something 指有力而清楚的證據，證明某事存在。"},{"en":"A doctor needs clear evidence of infection before giving certain medicine.","zh":"醫生在開某些藥前需要有感染的明確證據。"},{"en":"Without clear evidence of danger, a ban may be difficult to justify fully.","zh":"如果沒有危險的明確證據，禁令可能難以完全合理化。"},{"en":"The phrase points to proof, not rumours or guesses.","zh":"這個短語指證明，而不是傳聞或猜測。"}],"source":"123 - Flight from reality.pdf","sourcePage":4},{"front":"caused by","meaning":"由……引起","examples":[{"en":"Problems caused by personal electronic devices have been difficult to prove.","zh":"由個人電子裝置引起的問題一直難以證明。"},{"en":"Caused by means produced or brought about by something.","zh":"caused by 指由某事產生或導致。"},{"en":"A delay caused by heavy rain may affect hundreds of passengers.","zh":"由大雨引起的延誤可能影響數百名乘客。"},{"en":"If interference is caused by a laptop, switching it off should stop the problem.","zh":"如果干擾由手提電腦引起，關掉它應能停止問題。"},{"en":"The phrase identifies the source of a result.","zh":"這個短語指出結果的來源。"}],"source":"123 - Flight from reality.pdf","sourcePage":4},{"front":"have no impact on","meaning":"對……沒有影響","examples":[{"en":"Airbus found that cellphones have no impact on the navigation system.","zh":"空中巴士發現手提電話對導航系統沒有影響。"},{"en":"To have no impact on something means not to affect or change it.","zh":"have no impact on something 指不影響或不改變某事。"},{"en":"Changing a classroom poster may have no impact on exam scores.","zh":"更換課室海報可能對考試成績沒有影響。"},{"en":"If phones have no impact on navigation, the safety argument becomes weaker for that system.","zh":"如果電話對導航沒有影響，針對該系統的安全論點就變弱。"},{"en":"The phrase means there is no noticeable effect in that area.","zh":"這個短語表示在該方面沒有明顯效果。"}],"source":"123 - Flight from reality.pdf","sourcePage":4},{"front":"navigation system","meaning":"導航系統","examples":[{"en":"Cellphones were found to have no impact on the navigation system.","zh":"研究發現手提電話對導航系統沒有影響。"},{"en":"A navigation system helps a vehicle or aircraft know its position and direction.","zh":"navigation system 幫助車輛或飛機知道位置和方向。"},{"en":"Drivers use a navigation system to find the fastest route.","zh":"司機使用導航系統尋找最快路線。"},{"en":"In aircraft, a navigation system is important because pilots must know exactly where the plane is.","zh":"在飛機上，導航系統很重要，因為機師必須準確知道飛機位置。"},{"en":"The phrase refers to guidance and location technology.","zh":"這個短語指引導和定位技術。"}],"source":"123 - Flight from reality.pdf","sourcePage":4},{"front":"critical systems","meaning":"關鍵系統","examples":[{"en":"Airbus said cellphones do not affect other critical systems.","zh":"空中巴士表示手提電話不影響其他關鍵系統。"},{"en":"Critical systems are systems that are essential for safety or operation.","zh":"critical systems 指對安全或運作必不可少的系統。"},{"en":"A hospital’s power supply is one of its critical systems.","zh":"醫院供電是其關鍵系統之一。"},{"en":"If critical systems fail on an aircraft, the crew may face serious danger.","zh":"如果飛機上的關鍵系統失效，機組人員可能面對嚴重危險。"},{"en":"The phrase describes systems too important to ignore.","zh":"這個短語描述重要到不能忽視的系統。"}],"source":"123 - Flight from reality.pdf","sourcePage":5},{"front":"the only impact","meaning":"唯一影響","examples":[{"en":"The only impact was a slight beep in the pilot’s headset.","zh":"唯一影響是機師耳機中出現輕微嗶聲。"},{"en":"The only impact means the single effect found or reported.","zh":"the only impact 指被發現或報告的唯一效果。"},{"en":"After the timetable change, the only impact was a shorter lunch break.","zh":"時間表改動後，唯一影響是午餐時間縮短。"},{"en":"If the only impact is a small sound, the danger may appear limited.","zh":"如果唯一影響只是小聲響，危險可能看起來有限。"},{"en":"The phrase narrows the result to one effect.","zh":"這個短語把結果收窄至一個影響。"}],"source":"123 - Flight from reality.pdf","sourcePage":5},{"front":"start or finish a phone call","meaning":"開始或結束通話","examples":[{"en":"A slight sound may occur when a passenger starts or finishes a phone call.","zh":"當乘客開始或結束通話時，可能出現輕微聲響。"},{"en":"To start or finish a phone call means to begin or end speaking by phone.","zh":"start or finish a phone call 指開始或結束電話交談。"},{"en":"A phone may send signals when users start or finish a phone call.","zh":"使用者開始或結束通話時，電話可能發出訊號。"},{"en":"If equipment reacts only when calls start or finish, the interference may be brief.","zh":"如果設備只在通話開始或結束時有反應，干擾可能很短暫。"},{"en":"The phrase focuses on the beginning and ending of a call.","zh":"這個短語重點是通話的開始和結束。"}],"source":"123 - Flight from reality.pdf","sourcePage":5},{"front":"a very slight beep","meaning":"非常輕微的嗶聲","examples":[{"en":"The pilot may hear a very slight beep in the headset.","zh":"機師可能在耳機中聽到非常輕微的嗶聲。"},{"en":"A very slight beep is a very small, short electronic sound.","zh":"a very slight beep 指非常細小、短暫的電子聲。"},{"en":"A phone charger may make a very slight beep when it connects.","zh":"電話充電器接上時可能發出非常輕微的嗶聲。"},{"en":"A very slight beep can be harmless, but in a cockpit it may still attract attention.","zh":"非常輕微的嗶聲可以是無害的，但在駕駛艙中仍可能吸引注意。"},{"en":"The phrase suggests a minor sound, not a loud alarm.","zh":"這個短語暗示小聲響，而不是響亮警報。"}],"source":"123 - Flight from reality.pdf","sourcePage":5},{"front":"in the headset","meaning":"在耳機中","examples":[{"en":"The pilot heard a slight beep in the headset.","zh":"機師在耳機中聽到輕微嗶聲。"},{"en":"In the headset means through the headphones or communication device worn on the head.","zh":"in the headset 指透過戴在頭上的耳機或通訊裝置聽到。"},{"en":"A call-centre worker hears customers in the headset during work.","zh":"呼叫中心員工工作時在耳機中聽到顧客聲音。"},{"en":"If a pilot hears unexpected sounds in the headset, it may distract from communication.","zh":"如果機師在耳機中聽到意外聲響，可能干擾通訊。"},{"en":"The phrase gives the place where the sound is heard.","zh":"這個短語指出聲音被聽到的位置。"}],"source":"123 - Flight from reality.pdf","sourcePage":5},{"front":"the best evidence yet","meaning":"迄今最有力的證據","examples":[{"en":"The best evidence yet of a problem came from a British report.","zh":"關於問題的迄今最有力證據來自一份英國報告。"},{"en":"The best evidence yet means the strongest evidence found so far.","zh":"the best evidence yet 指截至目前找到的最強證據。"},{"en":"A new X-ray may provide the best evidence yet of what caused a patient’s pain.","zh":"新 X 光片可能提供迄今最有力的證據，顯示病人痛楚的原因。"},{"en":"If the best evidence yet is still limited, experts may continue to be cautious.","zh":"如果迄今最有力的證據仍有限，專家可能繼續保持謹慎。"},{"en":"The phrase compares current proof with earlier weaker proof.","zh":"這個短語把現有證據與早前較弱證據作比較。"}],"source":"123 - Flight from reality.pdf","sourcePage":5},{"front":"released this year","meaning":"今年發表的","examples":[{"en":"A report released this year discussed possible cellphone interference.","zh":"今年發表的一份報告討論可能的手提電話干擾。"},{"en":"Released this year means published or made available during the current year.","zh":"released this year 指在今年出版或公開。"},{"en":"A school report released this year may include the latest student survey results.","zh":"今年發表的學校報告可能包括最新學生調查結果。"},{"en":"If a study was released this year, people may treat it as more current than older research.","zh":"如果研究今年發表，人們可能視它為比舊研究更新。"},{"en":"The phrase gives publication timing.","zh":"這個短語提供發表時間。"}],"source":"123 - Flight from reality.pdf","sourcePage":5},{"front":"Britain’s Civil Aviation Authority","meaning":"英國民航局","examples":[{"en":"Britain’s Civil Aviation Authority studied cellphone transmissions inside aircraft.","zh":"英國民航局研究飛機內的手提電話傳輸訊號。"},{"en":"Britain’s Civil Aviation Authority is the UK body responsible for civil aviation safety regulation.","zh":"Britain’s Civil Aviation Authority 指英國負責民用航空安全監管的機構。"},{"en":"An aviation authority may test whether new technology creates safety risks.","zh":"航空管理機構可能測試新科技是否造成安全風險。"},{"en":"Reports from Britain’s Civil Aviation Authority can influence airline rules.","zh":"英國民航局的報告可以影響航空公司規則。"},{"en":"The phrase names an official organisation, so it should be translated accurately.","zh":"這個短語是官方機構名稱，因此應準確翻譯。"}],"source":"123 - Flight from reality.pdf","sourcePage":5},{"front":"generate simulated transmissions","meaning":"產生模擬傳輸訊號","examples":[{"en":"Researchers generated simulated cellphone transmissions inside two aircraft.","zh":"研究人員在兩架飛機內產生模擬手提電話傳輸訊號。"},{"en":"To generate simulated transmissions means to create artificial signals for testing.","zh":"generate simulated transmissions 指創造人工訊號作測試。"},{"en":"Engineers may generate simulated radio signals to see whether equipment reacts safely.","zh":"工程師可能產生模擬無線電訊號，看看設備是否安全反應。"},{"en":"Simulated transmissions let researchers test risk without using real passenger calls.","zh":"模擬傳輸訊號讓研究人員不用真正乘客通話也能測試風險。"},{"en":"The phrase combines creating signals with laboratory-style testing.","zh":"這個短語結合產生訊號與實驗式測試。"}],"source":"123 - Flight from reality.pdf","sourcePage":5},{"front":"simulated cellphone transmissions","meaning":"模擬手提電話傳輸訊號","examples":[{"en":"Simulated cellphone transmissions were tested inside Boeing aircraft.","zh":"模擬手提電話傳輸訊號在波音飛機內被測試。"},{"en":"Simulated cellphone transmissions are artificial mobile-phone signals created for experiments.","zh":"simulated cellphone transmissions 指為實驗而創造的人工手提電話訊號。"},{"en":"Researchers use simulated cellphone transmissions when real calls are too difficult or unsafe to test.","zh":"當真實通話太難或太不安全時，研究人員會使用模擬手提電話傳輸訊號。"},{"en":"These transmissions can show whether aircraft equipment reacts to phone-like signals.","zh":"這些傳輸訊號可以顯示飛機設備是否對類似電話訊號有反應。"},{"en":"The phrase refers to test signals, not ordinary passenger communication.","zh":"這個短語指測試訊號，而不是普通乘客通訊。"}],"source":"123 - Flight from reality.pdf","sourcePage":5},{"front":"inside two Boeing aircraft","meaning":"在兩架波音飛機內","examples":[{"en":"The tests were conducted inside two Boeing aircraft.","zh":"測試在兩架波音飛機內進行。"},{"en":"Inside two Boeing aircraft means within the cabins or structures of two planes made by Boeing.","zh":"inside two Boeing aircraft 指在兩架波音製造的飛機機艙或結構內。"},{"en":"Engineers may test devices inside an aircraft to copy real flight conditions more closely.","zh":"工程師可能在飛機內測試裝置，以更接近真實飛行情況。"},{"en":"Testing inside two aircraft gives more evidence than testing only on a desk.","zh":"在兩架飛機內測試比只在桌上測試提供更多證據。"},{"en":"The phrase gives the exact testing location.","zh":"這個短語提供確切測試地點。"}],"source":"123 - Flight from reality.pdf","sourcePage":5},{"front":"conclude that","meaning":"得出結論認為","examples":[{"en":"The researchers concluded that transmissions could create risky signals.","zh":"研究人員得出結論認為，傳輸訊號可能產生有風險的訊號。"},{"en":"To conclude that something is true means to decide it after considering evidence.","zh":"conclude that something is true 指考慮證據後判定某事為真。"},{"en":"A doctor may conclude that a cough is caused by infection after test results arrive.","zh":"醫生可能在測試結果出來後得出結論認為咳嗽由感染引起。"},{"en":"Researchers conclude that a risk exists only when evidence points in that direction.","zh":"研究人員只有在證據指向某方向時，才會得出結論認為風險存在。"},{"en":"The phrase introduces a careful judgment, not a random opinion.","zh":"這個短語引入仔細判斷，而不是隨意意見。"}],"source":"123 - Flight from reality.pdf","sourcePage":6},{"front":"create signals","meaning":"產生訊號","examples":[{"en":"Cellphone transmissions could create signals at certain power levels.","zh":"手提電話傳輸訊號可能在某些功率水平產生訊號。"},{"en":"To create signals means to produce electronic or radio waves that can be detected.","zh":"create signals 指產生可被偵測的電子或無線電波。"},{"en":"A Wi-Fi router creates signals so phones and computers can connect to the internet.","zh":"Wi-Fi 路由器產生訊號，讓電話和電腦連上互聯網。"},{"en":"If a device creates signals near sensitive systems, engineers must check for interference.","zh":"如果裝置在敏感系統附近產生訊號，工程師必須檢查是否有干擾。"},{"en":"The phrase focuses on producing detectable electronic output.","zh":"這個短語重點是產生可偵測的電子輸出。"}],"source":"123 - Flight from reality.pdf","sourcePage":6},{"front":"power and frequency levels","meaning":"功率及頻率水平","examples":[{"en":"The signals reached power and frequency levels that might affect older equipment.","zh":"這些訊號達到可能影響較舊設備的功率及頻率水平。"},{"en":"Power and frequency levels describe how strong a signal is and how often its wave repeats.","zh":"power and frequency levels 描述訊號有多強，以及其波動重複得多頻密。"},{"en":"Engineers check power and frequency levels before approving wireless equipment.","zh":"工程師批准無線設備前會檢查功率及頻率水平。"},{"en":"If power and frequency levels match sensitive equipment, interference becomes more possible.","zh":"如果功率及頻率水平與敏感設備相近，干擾就更可能發生。"},{"en":"The phrase is technical and describes signal characteristics.","zh":"這個短語較技術性，描述訊號特徵。"}],"source":"123 - Flight from reality.pdf","sourcePage":6},{"front":"affect the latest equipment","meaning":"影響最新設備","examples":[{"en":"The signals would not affect the latest equipment.","zh":"這些訊號不會影響最新設備。"},{"en":"To affect the latest equipment means to influence or disturb the newest devices or systems.","zh":"affect the latest equipment 指影響或干擾最新裝置或系統。"},{"en":"A software bug may affect the latest equipment if it was designed for older machines.","zh":"如果軟件錯誤是為舊機設計而造成，它可能影響最新設備。"},{"en":"If signals do not affect the latest equipment, newer aircraft may be safer from that problem.","zh":"如果訊號不影響最新設備，較新的飛機可能較不受該問題威脅。"},{"en":"The phrase compares risk for modern devices with older ones.","zh":"這個短語比較現代設備與舊設備的風險。"}],"source":"123 - Flight from reality.pdf","sourcePage":6},{"front":"exceed the safety threshold","meaning":"超出安全門檻","examples":[{"en":"The signals could exceed the safety threshold established in 1984.","zh":"這些訊號可能超出1984年制定的安全門檻。"},{"en":"To exceed the safety threshold means to go above the level considered safe.","zh":"exceed the safety threshold 指超過被視為安全的水平。"},{"en":"Noise levels exceed the safety threshold when workers need ear protection.","zh":"當工人需要耳塞保護時，噪音水平可能已超出安全門檻。"},{"en":"If a signal exceeds the safety threshold, regulators may restrict the device.","zh":"如果訊號超出安全門檻，監管者可能限制該裝置。"},{"en":"The phrase indicates a limit has been passed.","zh":"這個短語表示某個限度已被超越。"}],"source":"123 - Flight from reality.pdf","sourcePage":6},{"front":"safety threshold","meaning":"安全門檻","examples":[{"en":"The safety threshold was established in 1984.","zh":"安全門檻於1984年制定。"},{"en":"A safety threshold is the limit below which something is considered acceptably safe.","zh":"safety threshold 指某水平以下被視為可接受安全的限度。"},{"en":"Air quality rules set safety thresholds for harmful pollutants.","zh":"空氣質素規則為有害污染物設定安全門檻。"},{"en":"When a reading passes the safety threshold, action may be needed immediately.","zh":"當讀數超過安全門檻，可能需要立即採取行動。"},{"en":"The phrase refers to a safety limit, not a goal to reach.","zh":"這個短語指安全限度，而不是要達到的目標。"}],"source":"123 - Flight from reality.pdf","sourcePage":6},{"front":"established in","meaning":"於……制定","examples":[{"en":"The safety threshold was established in 1984.","zh":"安全門檻於1984年制定。"},{"en":"Established in a year means created, set up, or officially fixed in that year.","zh":"established in a year 指在某一年創立、設立或正式確定。"},{"en":"A school rule established in 2005 may need updating today.","zh":"於2005年制定的校規今天可能需要更新。"},{"en":"If a safety standard was established in the past, new technology may challenge it.","zh":"如果安全標準於過去制定，新科技可能挑戰它。"},{"en":"The phrase gives the time when something was formally created.","zh":"這個短語提供某事正式建立的時間。"}],"source":"123 - Flight from reality.pdf","sourcePage":6},{"front":"on board","meaning":"在機上","examples":[{"en":"Older equipment on board might be affected by cellphone signals.","zh":"機上的較舊設備可能受手提電話訊號影響。"},{"en":"On board means inside or carried on a vehicle, ship, or aircraft.","zh":"on board 指在車輛、船隻或飛機內，或被攜帶在其上。"},{"en":"Passengers must follow safety rules once they are on board.","zh":"乘客一旦在機上，就必須遵守安全規則。"},{"en":"If dangerous equipment is on board, the crew must manage the risk carefully.","zh":"如果危險設備在機上，機組人員必須小心管理風險。"},{"en":"The phrase refers to being inside the transport system, not near it outside.","zh":"這個短語指在交通工具內，而不是在外面附近。"}],"source":"123 - Flight from reality.pdf","sourcePage":6},{"front":"mission critical equipment","meaning":"任務關鍵設備","examples":[{"en":"The study did not suggest that mission critical equipment would fail.","zh":"該研究沒有顯示任務關鍵設備會失效。"},{"en":"Mission critical equipment is equipment essential for the main task and safety of an operation.","zh":"mission critical equipment 指對主要任務和安全必不可少的設備。"},{"en":"In a hospital, life-support machines are mission critical equipment.","zh":"在醫院，維生機器是任務關鍵設備。"},{"en":"If mission critical equipment fails on a plane, the consequences can be serious.","zh":"如果飛機上的任務關鍵設備失效，後果可能嚴重。"},{"en":"The phrase describes equipment that must work reliably.","zh":"這個短語描述必須可靠運作的設備。"}],"source":"123 - Flight from reality.pdf","sourcePage":6},{"front":"flight controls","meaning":"飛行控制系統","examples":[{"en":"Navigation systems and flight controls are mission critical equipment.","zh":"導航系統和飛行控制系統是任務關鍵設備。"},{"en":"Flight controls are systems that help pilots control the movement of an aircraft.","zh":"flight controls 指幫助機師控制飛機移動的系統。"},{"en":"Flight controls affect how a plane climbs, turns, descends, or stays level.","zh":"飛行控制系統影響飛機如何爬升、轉向、下降或保持水平。"},{"en":"If flight controls malfunction, pilots may have difficulty managing the aircraft safely.","zh":"如果飛行控制系統發生故障，機師可能難以安全管理飛機。"},{"en":"The phrase refers to core aircraft-control systems.","zh":"這個短語指核心飛機控制系統。"}],"source":"123 - Flight from reality.pdf","sourcePage":6},{"front":"smoke detectors","meaning":"煙霧探測器","examples":[{"en":"Smoke detectors could create serious problems if they malfunction.","zh":"如果煙霧探測器發生故障，可能造成嚴重問題。"},{"en":"Smoke detectors are devices that sense smoke and warn people of possible fire.","zh":"smoke detectors 指偵測煙霧並警告人們可能有火警的裝置。"},{"en":"Homes, schools, and aircraft use smoke detectors for safety.","zh":"家居、學校和飛機都使用煙霧探測器以保障安全。"},{"en":"If smoke detectors fail, people may not notice a fire early enough.","zh":"如果煙霧探測器失效，人們可能無法及早察覺火警。"},{"en":"The phrase refers to warning devices, not fire extinguishers.","zh":"這個短語指警報裝置，而不是滅火筒。"}],"source":"123 - Flight from reality.pdf","sourcePage":6},{"front":"fuel level indicators","meaning":"燃油水平顯示器","examples":[{"en":"Fuel level indicators could be affected by cellphone signals.","zh":"燃油水平顯示器可能受手提電話訊號影響。"},{"en":"Fuel level indicators are devices that show how much fuel remains.","zh":"fuel level indicators 指顯示剩餘燃油量的裝置。"},{"en":"Drivers and pilots use fuel level indicators to plan safe travel.","zh":"司機和機師使用燃油水平顯示器來規劃安全行程。"},{"en":"If fuel level indicators show wrong information, the crew may misjudge how much fuel is available.","zh":"如果燃油水平顯示器顯示錯誤資料，機組人員可能誤判可用燃油量。"},{"en":"The phrase refers to measurement displays, not the fuel itself.","zh":"這個短語指量度顯示器，而不是燃油本身。"}],"source":"123 - Flight from reality.pdf","sourcePage":7},{"front":"serious problems for","meaning":"對……造成嚴重問題","examples":[{"en":"Faulty indicators could create serious problems for the flight crew.","zh":"有故障的顯示器可能對機組人員造成嚴重問題。"},{"en":"Serious problems for someone are difficulties that may cause danger, delay, or major pressure.","zh":"serious problems for someone 指可能造成危險、延誤或重大壓力的困難。"},{"en":"A broken lift can create serious problems for elderly residents in a tall building.","zh":"壞掉的升降機可以對高樓中的長者居民造成嚴重問題。"},{"en":"Wrong fuel information can create serious problems for pilots during a flight.","zh":"錯誤燃油資訊可以在飛行期間對機師造成嚴重問題。"},{"en":"The phrase shows who is affected by the difficulty.","zh":"這個短語顯示誰受到困難影響。"}],"source":"123 - Flight from reality.pdf","sourcePage":7},{"front":"flight crew","meaning":"機組人員","examples":[{"en":"The flight crew could face problems if safety devices malfunction.","zh":"如果安全裝置發生故障，機組人員可能面對問題。"},{"en":"The flight crew are the pilots and staff responsible for operating and managing a flight.","zh":"flight crew 指負責操作和管理航班的機師和工作人員。"},{"en":"The flight crew gives safety instructions before take-off.","zh":"機組人員在起飛前提供安全指示。"},{"en":"If passengers ignore rules, the flight crew may have to intervene.","zh":"如果乘客忽視規則，機組人員可能需要介入。"},{"en":"The phrase refers to working staff on the aircraft, not passengers.","zh":"這個短語指飛機上的工作人員，而不是乘客。"}],"source":"123 - Flight from reality.pdf","sourcePage":7},{"front":"malfunction","meaning":"發生故障","examples":[{"en":"Smoke detectors and fuel indicators could cause problems if they malfunction.","zh":"如果煙霧探測器和燃油顯示器發生故障，可能造成問題。"},{"en":"To malfunction means to stop working correctly.","zh":"malfunction 指停止正常運作。"},{"en":"A printer may malfunction and produce blank pages.","zh":"打印機可能發生故障，印出空白頁。"},{"en":"If aircraft equipment malfunctions, the crew must quickly identify and manage the problem.","zh":"如果飛機設備發生故障，機組人員必須迅速辨認並處理問題。"},{"en":"The word describes technical failure, not normal operation.","zh":"這個詞描述技術失效，而不是正常運作。"}],"source":"123 - Flight from reality.pdf","sourcePage":7},{"front":"be certified to","meaning":"被認證符合","examples":[{"en":"Many planes still use equipment certified to older standards.","zh":"許多飛機仍使用被認證符合較舊標準的設備。"},{"en":"To be certified to a standard means to be officially judged as meeting that standard.","zh":"be certified to a standard 指被正式判定符合某標準。"},{"en":"A helmet may be certified to a safety standard before it is sold.","zh":"頭盔在出售前可能被認證符合安全標準。"},{"en":"Equipment certified to older standards may not reflect newer electronic risks.","zh":"被認證符合較舊標準的設備，可能未能反映較新的電子風險。"},{"en":"The phrase refers to formal approval against rules or requirements.","zh":"這個短語指根據規則或要求作出的正式認可。"}],"source":"123 - Flight from reality.pdf","sourcePage":7},{"front":"older standards","meaning":"較舊標準","examples":[{"en":"Some aircraft equipment is still certified to older standards.","zh":"一些飛機設備仍被認證符合較舊標準。"},{"en":"Older standards are rules or requirements created in the past.","zh":"older standards 指過去制定的規則或要求。"},{"en":"A building built to older standards may not meet today’s fire-safety rules.","zh":"按較舊標準興建的建築物可能不符合今日消防安全規則。"},{"en":"If technology changes, older standards may leave some risks untested.","zh":"如果科技改變，較舊標準可能令某些風險未被測試。"},{"en":"The phrase contrasts past requirements with newer ones.","zh":"這個短語把過去要求與較新要求作對比。"}],"source":"123 - Flight from reality.pdf","sourcePage":7},{"front":"head of avionics","meaning":"航空電子設備主管","examples":[{"en":"Dan Hawkes is head of avionics at the CAA’s Safety Regulation Group.","zh":"Dan Hawkes 是英國民航局安全規管組的航空電子設備主管。"},{"en":"Head of avionics means the person responsible for aircraft electronic systems in an organisation.","zh":"head of avionics 指機構中負責飛機電子系統的人。"},{"en":"A head of avionics may review safety reports about navigation and communication equipment.","zh":"航空電子設備主管可能審視有關導航和通訊設備的安全報告。"},{"en":"If electronic interference is suspected, the head of avionics may help judge the technical risk.","zh":"如果懷疑有電子干擾，航空電子設備主管可能協助判斷技術風險。"},{"en":"The phrase identifies a senior technical role.","zh":"這個短語指出高級技術職位。"}],"source":"123 - Flight from reality.pdf","sourcePage":7},{"front":"avionics","meaning":"航空電子設備","examples":[{"en":"Avionics refers to the electronic systems used in aircraft.","zh":"avionics 指飛機使用的電子系統。"},{"en":"Avionics includes aircraft electronics for navigation, communication, control, and monitoring.","zh":"avionics 包括用於導航、通訊、控制和監察的飛機電子設備。"},{"en":"Pilots depend on avionics to read flight information accurately.","zh":"機師依靠航空電子設備準確讀取飛行資訊。"},{"en":"If avionics are affected by interference, aircraft safety may be questioned.","zh":"如果航空電子設備受干擾影響，飛機安全可能受到質疑。"},{"en":"The word combines aviation and electronics.","zh":"這個詞結合 aviation 和 electronics 的意思。"}],"source":"123 - Flight from reality.pdf","sourcePage":7},{"front":"Safety Regulation Group","meaning":"安全規管組","examples":[{"en":"The Safety Regulation Group studies risks in aviation systems.","zh":"安全規管組研究航空系統中的風險。"},{"en":"A Safety Regulation Group is a body that helps create or enforce safety rules.","zh":"Safety Regulation Group 指幫助制定或執行安全規則的組織。"},{"en":"A safety regulation group may examine accident reports to improve future standards.","zh":"安全規管組可能檢視意外報告，以改善未來標準。"},{"en":"If new devices create uncertainty, a Safety Regulation Group may require further tests.","zh":"如果新裝置造成不確定性，安全規管組可能要求進一步測試。"},{"en":"The phrase refers to organised safety oversight.","zh":"這個短語指有組織的安全監管。"}],"source":"123 - Flight from reality.pdf","sourcePage":7},{"front":"prove something will fail","meaning":"證明……會失效","examples":[{"en":"The CAA study does not prove that the equipment will actually fail.","zh":"英國民航局的研究沒有證明該設備實際上會失效。"},{"en":"To prove something will fail means to show with evidence that it will stop working.","zh":"prove something will fail 指用證據顯示某物會停止運作。"},{"en":"A small warning sign does not prove a machine will fail, but it may justify inspection.","zh":"一個小警號不一定證明機器會失效，但可能足以支持檢查。"},{"en":"If researchers cannot prove equipment will fail, they may still warn about possible risk.","zh":"如果研究人員不能證明設備會失效，他們仍可能警告可能風險。"},{"en":"The phrase separates definite failure from possible danger.","zh":"這個短語區分確定失效與可能危險。"}],"source":"123 - Flight from reality.pdf","sourcePage":7},{"front":"be subjected to","meaning":"受到……影響；承受","examples":[{"en":"The equipment may be subjected to cellphone signals.","zh":"該設備可能受到手提電話訊號影響。"},{"en":"To be subjected to something means to be exposed to it or forced to experience it.","zh":"be subjected to something 指接觸到某事或被迫承受某事。"},{"en":"Students should not be subjected to constant noise while taking an exam.","zh":"學生考試時不應承受持續噪音。"},{"en":"Equipment subjected to strong signals may behave differently from equipment in a quiet lab.","zh":"受到強訊號影響的設備，可能與安靜實驗室中的設備表現不同。"},{"en":"The phrase often suggests pressure, exposure, or testing.","zh":"這個短語常暗示壓力、暴露或測試。"}],"source":"123 - Flight from reality.pdf","sourcePage":7},{"front":"take uncertainty out of","meaning":"減少……中的不確定性","examples":[{"en":"The study has taken some of the uncertainty out of these beliefs.","zh":"該研究減少了這些看法中的一些不確定性。"},{"en":"To take uncertainty out of something means to make it clearer or less doubtful.","zh":"take uncertainty out of something 指令某事更清楚或較少疑問。"},{"en":"A clear timetable can take uncertainty out of a school trip.","zh":"清晰時間表可以減少學校旅行中的不確定性。"},{"en":"Good testing can take uncertainty out of safety decisions by showing what actually happens.","zh":"良好測試可以透過顯示實際情況，減少安全決策中的不確定性。"},{"en":"The phrase means reducing doubt, not removing every question completely.","zh":"這個短語表示減少疑問，而不是完全消除所有問題。"}],"source":"123 - Flight from reality.pdf","sourcePage":8},{"front":"cause devices to fail","meaning":"導致裝置失效","examples":[{"en":"A later study will test whether cellphone signals cause devices to fail.","zh":"後續研究將測試手提電話訊號是否導致裝置失效。"},{"en":"To cause devices to fail means to make equipment stop working properly.","zh":"cause devices to fail 指令設備停止正常運作。"},{"en":"Water can cause devices to fail if it reaches the circuits.","zh":"如果水接觸電路，可能導致裝置失效。"},{"en":"If phone signals cause devices to fail, airlines would need much stricter controls.","zh":"如果電話訊號導致裝置失效，航空公司就需要更嚴格控制。"},{"en":"The phrase describes a direct harmful technical result.","zh":"這個短語描述直接有害的技術結果。"}],"source":"123 - Flight from reality.pdf","sourcePage":8},{"front":"conduct tests","meaning":"進行測試","examples":[{"en":"RTCA was hired to conduct tests for the FAA.","zh":"RTCA 受聘為美國聯邦航空管理局進行測試。"},{"en":"To conduct tests means to carry out planned checks or experiments.","zh":"conduct tests 指進行有計劃的檢查或實驗。"},{"en":"A hospital may conduct tests before deciding on treatment.","zh":"醫院可能在決定治療前進行測試。"},{"en":"Engineers conduct tests to find out whether a device is safe under real conditions.","zh":"工程師進行測試，以找出裝置在真實情況下是否安全。"},{"en":"The phrase is formal and focuses on organised testing.","zh":"這個短語較正式，重點是有組織的測試。"}],"source":"123 - Flight from reality.pdf","sourcePage":8},{"front":"determine that","meaning":"判定；確定","examples":[{"en":"RTCA determined that potential problems from personal devices were low.","zh":"RTCA 判定個人裝置造成潛在問題的風險很低。"},{"en":"To determine that something is true means to decide it after examination or analysis.","zh":"determine that something is true 指經檢查或分析後判定某事為真。"},{"en":"A teacher may determine that a student needs grammar support after marking several essays.","zh":"老師批改幾篇作文後，可能判定學生需要文法支援。"},{"en":"Investigators determine that a risk is low only after checking the evidence.","zh":"調查人員只有在檢查證據後，才判定風險較低。"},{"en":"The phrase introduces an informed decision.","zh":"這個短語引入有根據的判斷。"}],"source":"123 - Flight from reality.pdf","sourcePage":8},{"front":"potential problems","meaning":"潛在問題","examples":[{"en":"RTCA described potential problems from personal electronic devices as low.","zh":"RTCA 把個人電子裝置帶來的潛在問題描述為低風險。"},{"en":"Potential problems are difficulties that may happen, even if they have not happened yet.","zh":"potential problems 指可能發生的困難，即使尚未真正發生。"},{"en":"A manager checks potential problems before launching a new service.","zh":"經理在推出新服務前會檢查潛在問題。"},{"en":"Identifying potential problems early can prevent accidents or delays later.","zh":"及早辨認潛在問題可以防止之後發生事故或延誤。"},{"en":"The phrase refers to possible future trouble.","zh":"這個短語指可能出現的未來麻煩。"}],"source":"123 - Flight from reality.pdf","sourcePage":8},{"front":"nevertheless","meaning":"然而；儘管如此","examples":[{"en":"The risk was considered low; nevertheless, RTCA recommended restrictions.","zh":"該風險被認為很低；然而，RTCA 仍建議限制。"},{"en":"Nevertheless means however or despite that fact.","zh":"nevertheless 指然而或儘管如此。"},{"en":"The weather was bad; nevertheless, the students arrived on time.","zh":"天氣很差；然而，學生仍準時到達。"},{"en":"A risk may be small; nevertheless, safety rules can still be necessary.","zh":"風險可能很小；儘管如此，安全規則仍可能有必要。"},{"en":"The word connects a contrast between expectation and action.","zh":"這個詞連接預期與行動之間的對比。"}],"source":"123 - Flight from reality.pdf","sourcePage":8},{"front":"recommend a ban on","meaning":"建議禁止","examples":[{"en":"RTCA recommended a ban on electronic devices during critical periods.","zh":"RTCA 建議在關鍵時段禁止電子裝置。"},{"en":"To recommend a ban on something means to advise that it should be officially prohibited.","zh":"recommend a ban on something 指建議正式禁止某物。"},{"en":"A school may recommend a ban on phones during exams.","zh":"學校可能建議考試期間禁止手機。"},{"en":"If experts recommend a ban on a device, they believe restriction may reduce risk.","zh":"如果專家建議禁止某裝置，他們認為限制可能降低風險。"},{"en":"The phrase gives advice for prohibition, not necessarily a law already passed.","zh":"這個短語表示禁止的建議，而不一定是已通過的法律。"}],"source":"123 - Flight from reality.pdf","sourcePage":8},{"front":"critical periods of flight","meaning":"飛行關鍵時段","examples":[{"en":"Take-off and landing are critical periods of flight.","zh":"起飛及降落是飛行關鍵時段。"},{"en":"Critical periods of flight are stages when pilots and aircraft systems need special attention.","zh":"critical periods of flight 指機師和飛機系統需要特別注意的階段。"},{"en":"During take-off, small mistakes can matter more because the plane is close to the ground.","zh":"起飛期間，由於飛機接近地面，小錯誤可能更重要。"},{"en":"Devices may be restricted during critical periods of flight to reduce distraction and interference.","zh":"在飛行關鍵時段，電子裝置可能被限制，以減少分心和干擾。"},{"en":"The phrase refers to high-risk or high-attention moments in a flight.","zh":"這個短語指飛行中高風險或需要高度注意的時刻。"}],"source":"123 - Flight from reality.pdf","sourcePage":8},{"front":"take-off and landing","meaning":"起飛及降落","examples":[{"en":"Electronic devices may be banned during take-off and landing.","zh":"電子裝置可能在起飛及降落期間被禁止。"},{"en":"Take-off and landing are the stages when a plane leaves the ground and returns to it.","zh":"take-off and landing 指飛機離開地面和返回地面的階段。"},{"en":"Passengers must fasten seat belts during take-off and landing.","zh":"乘客在起飛及降落期間必須扣好安全帶。"},{"en":"Because take-off and landing require careful control, airlines often set stricter rules then.","zh":"由於起飛及降落需要仔細控制，航空公司通常在這些時段設更嚴格規則。"},{"en":"The phrase describes two important phases of a flight.","zh":"這個短語描述航班的兩個重要階段。"}],"source":"123 - Flight from reality.pdf","sourcePage":8},{"front":"wholesale ban","meaning":"全面禁止","examples":[{"en":"RTCA recommended a wholesale ban on cellphones during flights.","zh":"RTCA 建議在飛行期間全面禁止手提電話。"},{"en":"A wholesale ban is a complete ban that applies broadly, not just to a few cases.","zh":"wholesale ban 指廣泛適用的全面禁止，而不是只針對少數情況。"},{"en":"A school may impose a wholesale ban on smoking anywhere on campus.","zh":"學校可能在整個校園全面禁止吸煙。"},{"en":"A wholesale ban is easier to enforce than checking each device separately.","zh":"全面禁止比逐一檢查每個裝置更容易執行。"},{"en":"The phrase suggests broad prohibition rather than limited restriction.","zh":"這個短語暗示廣泛禁止，而不是有限限制。"}],"source":"123 - Flight from reality.pdf","sourcePage":8},{"front":"better safe than sorry","meaning":"寧可安全為上","examples":[{"en":"The policy follows the idea of better safe than sorry.","zh":"該政策遵循寧可安全為上的想法。"},{"en":"Better safe than sorry means it is wiser to avoid risk than regret harm later.","zh":"better safe than sorry 指避免風險比事後後悔更明智。"},{"en":"A parent may pack medicine for a trip because it is better safe than sorry.","zh":"父母旅行時可能帶備藥物，因為寧可安全為上。"},{"en":"Airlines may ban phones even with uncertain evidence because they prefer caution.","zh":"即使證據不確定，航空公司也可能禁止電話，因為它們偏好謹慎。"},{"en":"The phrase supports cautious action before proof of disaster appears.","zh":"這個短語支持在災難證明出現前先採取謹慎行動。"}],"source":"123 - Flight from reality.pdf","sourcePage":8},{"front":"current policy","meaning":"現行政策","examples":[{"en":"The current policy bans mobile phones on aircraft.","zh":"現行政策禁止在飛機上使用手提電話。"},{"en":"Current policy means the rule or approach being used now.","zh":"current policy 指目前正在使用的規則或做法。"},{"en":"A school’s current policy may allow laptops but ban phones in class.","zh":"學校的現行政策可能准許手提電腦，但禁止課堂使用手機。"},{"en":"If evidence changes, the current policy may need to be reviewed.","zh":"如果證據改變，現行政策可能需要檢討。"},{"en":"The phrase contrasts present rules with past or future rules.","zh":"這個短語把現在規則與過去或未來規則作對比。"}],"source":"123 - Flight from reality.pdf","sourcePage":9},{"front":"be applied inconsistently","meaning":"被不一致地執行","examples":[{"en":"The policy is applied inconsistently because laptops are still allowed.","zh":"該政策被不一致地執行，因為手提電腦仍被准許。"},{"en":"To be applied inconsistently means to be used in an uneven or not fully logical way.","zh":"be applied inconsistently 指以不平均或不完全合邏輯的方式執行。"},{"en":"A school rule is applied inconsistently if some classes enforce it and others ignore it.","zh":"如果有些班執行某校規而其他班忽視它，該規則就是被不一致地執行。"},{"en":"If phones are banned but riskier laptops are allowed, the policy may seem inconsistent.","zh":"如果電話被禁止，但風險更高的手提電腦被准許，政策可能顯得不一致。"},{"en":"The phrase criticises unequal or unclear enforcement.","zh":"這個短語批評執行不平等或不清楚。"}],"source":"123 - Flight from reality.pdf","sourcePage":9},{"front":"be outlawed","meaning":"被禁止","examples":[{"en":"Cellphones are outlawed on planes.","zh":"手提電話在飛機上被禁止。"},{"en":"To be outlawed means to be made illegal or officially banned.","zh":"be outlawed 指被列為非法或被正式禁止。"},{"en":"Smoking is outlawed in many indoor public places.","zh":"在許多室內公共場所，吸煙被禁止。"},{"en":"If a device is outlawed on flights, passengers can be punished for using it.","zh":"如果某裝置在航班上被禁止，乘客使用它可能受罰。"},{"en":"The phrase is stronger than discouraged.","zh":"這個短語比 discouraged 語氣更強。"}],"source":"123 - Flight from reality.pdf","sourcePage":9},{"front":"no one considers a ban on","meaning":"沒有人考慮禁止……","examples":[{"en":"No one seriously considers a ban on laptops.","zh":"沒有人認真考慮禁止手提電腦。"},{"en":"No one considers a ban on something means people are not seriously thinking about prohibiting it.","zh":"no one considers a ban on something 指人們沒有認真考慮禁止某物。"},{"en":"No one considers a ban on books because some students read too slowly.","zh":"沒有人會因為有些學生閱讀太慢而考慮禁止書本。"},{"en":"If no one considers a ban on laptops, the phone ban may look inconsistent.","zh":"如果沒有人考慮禁止手提電腦，電話禁令可能顯得不一致。"},{"en":"The phrase points to what is absent from policy debate.","zh":"這個短語指出政策討論中缺少的部分。"}],"source":"123 - Flight from reality.pdf","sourcePage":9},{"front":"a little bit technical","meaning":"有點技術性的","examples":[{"en":"The reason is a little bit technical, economic and political.","zh":"原因有點技術性、經濟性和政治性。"},{"en":"A little bit technical means partly connected with specialist knowledge or equipment.","zh":"a little bit technical 指部分與專門知識或設備有關。"},{"en":"The explanation of Wi-Fi speed is a little bit technical because it involves signals and routers.","zh":"Wi-Fi 速度的解釋有點技術性，因為涉及訊號和路由器。"},{"en":"A policy may be hard to explain when the reason is a little bit technical.","zh":"當原因有點技術性，政策可能較難解釋。"},{"en":"The phrase softens the idea that the topic is difficult.","zh":"這個短語弱化了主題困難的感覺。"}],"source":"123 - Flight from reality.pdf","sourcePage":9},{"front":"a little bit economic","meaning":"有點經濟因素的","examples":[{"en":"The policy is partly technical and partly economic.","zh":"該政策部分有技術因素，部分有經濟因素。"},{"en":"A little bit economic means partly related to money, cost, profit, or business incentives.","zh":"a little bit economic 指部分與金錢、成本、利潤或商業誘因有關。"},{"en":"A school’s decision to offer online classes may be a little bit economic because classrooms cost money.","zh":"學校決定提供網上課程可能有點經濟因素，因為課室需要成本。"},{"en":"If airlines see little profit in allowing phones, the issue becomes a little bit economic.","zh":"如果航空公司看不到准許電話有太大利潤，該議題就有點經濟因素。"},{"en":"The phrase shows money is one factor, not the whole explanation.","zh":"這個短語顯示金錢是一個因素，而不是全部解釋。"}],"source":"123 - Flight from reality.pdf","sourcePage":9},{"front":"a little bit political","meaning":"有點政治因素的","examples":[{"en":"The ban is partly political as well as technical.","zh":"該禁令既有技術因素，也有點政治因素。"},{"en":"A little bit political means partly affected by public pressure, lawmaking, or government interests.","zh":"a little bit political 指部分受公眾壓力、立法或政府利益影響。"},{"en":"A transport decision can be a little bit political when voters complain loudly.","zh":"當選民強烈投訴，交通決策可能有點政治因素。"},{"en":"If lawmakers question airlines in public, the phone ban becomes a little bit political.","zh":"如果立法者公開質詢航空公司，電話禁令就變得有點政治性。"},{"en":"The phrase shows politics is involved but not the only cause.","zh":"這個短語顯示政治有參與，但不是唯一原因。"}],"source":"123 - Flight from reality.pdf","sourcePage":9},{"front":"write a report for","meaning":"為……撰寫報告","examples":[{"en":"Mega Wave wrote a report for the FAA in 1998.","zh":"Mega Wave 在1998年為美國聯邦航空管理局撰寫報告。"},{"en":"To write a report for someone means to prepare a formal document for that person or organisation.","zh":"write a report for someone 指為某人或機構準備正式文件。"},{"en":"A consultant may write a report for a school about student safety.","zh":"顧問可能為學校撰寫關於學生安全的報告。"},{"en":"Reports written for regulators can influence later rules and restrictions.","zh":"為監管機構撰寫的報告可以影響後來的規則和限制。"},{"en":"The phrase shows both the task and the intended recipient.","zh":"這個短語同時顯示任務和接收者。"}],"source":"123 - Flight from reality.pdf","sourcePage":9},{"front":"on-board system","meaning":"機上系統","examples":[{"en":"An on-board system could detect dangerous electronic signals.","zh":"機上系統可以偵測危險電子訊號。"},{"en":"An on-board system is equipment installed and used inside a vehicle or aircraft.","zh":"on-board system 指安裝並用於車輛或飛機內的設備。"},{"en":"An on-board entertainment system lets passengers watch films during a flight.","zh":"機上娛樂系統讓乘客在航班上觀看電影。"},{"en":"If an on-board system detects interference, staff can respond quickly.","zh":"如果機上系統偵測到干擾，職員可以快速回應。"},{"en":"The phrase means located on the aircraft, not outside at the airport.","zh":"這個短語指位於飛機上，而不是機場外部。"}],"source":"123 - Flight from reality.pdf","sourcePage":9},{"front":"detect dangerous signals","meaning":"偵測危險訊號","examples":[{"en":"The system could detect dangerous signals from electronic devices.","zh":"該系統可以偵測來自電子裝置的危險訊號。"},{"en":"To detect dangerous signals means to find or notice electronic signals that may cause harm.","zh":"detect dangerous signals 指找到或察覺可能造成傷害的電子訊號。"},{"en":"Security equipment can detect dangerous signals before they disrupt communication.","zh":"保安設備可以在危險訊號干擾通訊前偵測到它們。"},{"en":"If detectors identify risky emissions, flight staff can ask passengers to switch off devices.","zh":"如果探測器辨認出高風險發射訊號，機組人員可以要求乘客關掉裝置。"},{"en":"The phrase focuses on warning before damage happens.","zh":"這個短語重點是在損害發生前作出警告。"}],"source":"123 - Flight from reality.pdf","sourcePage":9},{"front":"personal conclusion","meaning":"個人結論","examples":[{"en":"Cross’s personal conclusion is that mobile phones are not the real threat.","zh":"Cross 的個人結論是手提電話不是真正威脅。"},{"en":"A personal conclusion is someone’s own judgment after thinking about evidence or experience.","zh":"personal conclusion 指某人思考證據或經驗後得出的個人判斷。"},{"en":"After comparing prices, my personal conclusion is that the cheaper plan is enough.","zh":"比較價格後，我的個人結論是較便宜的方案已足夠。"},{"en":"A personal conclusion can be useful, but it may not represent an official position.","zh":"個人結論可以有用，但未必代表官方立場。"},{"en":"The phrase separates one person’s view from formal policy.","zh":"這個短語把個人看法與正式政策區分開來。"}],"source":"123 - Flight from reality.pdf","sourcePage":9},{"front":"the real threat","meaning":"真正威脅","examples":[{"en":"Cross argues that mobile phones are not the real threat.","zh":"Cross 認為手提電話不是真正威脅。"},{"en":"The real threat means the actual source of danger, not the thing people first suspect.","zh":"real threat 指真正的危險來源，而不是人們首先懷疑的事物。"},{"en":"In a school, the real threat to learning may be lack of sleep rather than difficult homework.","zh":"在學校中，學習的真正威脅可能是睡眠不足，而不是功課困難。"},{"en":"If laptops create stronger interference, they may be the real threat rather than phones.","zh":"如果手提電腦造成更強干擾，它們可能才是真正威脅，而不是電話。"},{"en":"The phrase helps redirect attention to the true danger.","zh":"這個短語幫助把注意力轉向真正危險。"}],"source":"123 - Flight from reality.pdf","sourcePage":10},{"front":"stretch things pretty far","meaning":"勉強推論；牽強地解釋","examples":[{"en":"You would have to stretch things pretty far to show that a cellphone interferes with aircraft systems.","zh":"要顯示手提電話會干擾飛機系統，你就要相當牽強地解釋。"},{"en":"To stretch things pretty far means to make an explanation or argument seem forced and unrealistic.","zh":"stretch things pretty far 指把解釋或論點拉得很勉強、不太現實。"},{"en":"It would stretch things pretty far to blame one missed bus for an entire failed project.","zh":"把整個項目失敗歸咎於錯過一班巴士，就相當牽強。"},{"en":"If evidence is weak, people may have to stretch things pretty far to support their claim.","zh":"如果證據薄弱，人們可能要牽強推論才能支持自己的聲稱。"},{"en":"The phrase suggests the reasoning is not convincing.","zh":"這個短語暗示推理不令人信服。"}],"source":"123 - Flight from reality.pdf","sourcePage":10},{"front":"figure out how","meaning":"弄清楚如何","examples":[{"en":"It is hard to figure out how a cellphone could interfere with the plane.","zh":"很難弄清楚手提電話如何會干擾飛機。"},{"en":"To figure out how something happens means to understand the method or process behind it.","zh":"figure out how something happens 指理解某事背後的方法或過程。"},{"en":"A student may figure out how to solve a grammar problem after seeing examples.","zh":"學生看到例子後，可能弄清楚如何解決文法問題。"},{"en":"Engineers try to figure out how signals move through an aircraft cabin.","zh":"工程師嘗試弄清楚訊號如何穿過飛機機艙。"},{"en":"The phrase is common and means work out through thinking.","zh":"這個短語常見，意思是透過思考找出答案。"}],"source":"123 - Flight from reality.pdf","sourcePage":10},{"front":"interfere with a plane’s systems","meaning":"干擾飛機系統","examples":[{"en":"Cross doubts that a cellphone could interfere with a plane’s systems.","zh":"Cross 懷疑手提電話會干擾飛機系統。"},{"en":"To interfere with a plane’s systems means to disturb aircraft equipment or make it work incorrectly.","zh":"interfere with a plane’s systems 指干擾飛機設備或令其運作不正常。"},{"en":"Strong electronic noise could interfere with a plane’s systems if it reaches sensitive circuits.","zh":"如果強烈電子噪音到達敏感電路，可能干擾飛機系統。"},{"en":"If passengers fear devices may interfere with a plane’s systems, they may accept stricter rules.","zh":"如果乘客擔心裝置可能干擾飛機系統，他們可能接受更嚴格規則。"},{"en":"The phrase describes a safety-related technical risk.","zh":"這個短語描述與安全有關的技術風險。"}],"source":"123 - Flight from reality.pdf","sourcePage":10},{"front":"transmit in ranges of","meaning":"以……範圍傳輸","examples":[{"en":"Cellphones transmit in ranges of around 400, 800 or 1800 megahertz.","zh":"手提電話以約400、800或1800兆赫範圍傳輸。"},{"en":"To transmit in ranges of certain frequencies means to send signals within those frequency bands.","zh":"transmit in ranges of certain frequencies 指在那些頻段內發送訊號。"},{"en":"Radio stations transmit in ranges that receivers are designed to pick up.","zh":"電台以接收器設計能接收的範圍傳輸。"},{"en":"If aircraft equipment does not operate in the same ranges, interference may be less likely.","zh":"如果飛機設備不在相同範圍運作，干擾可能較不可能。"},{"en":"The phrase is technical and describes signal frequency bands.","zh":"這個短語較技術性，描述訊號頻段。"}],"source":"123 - Flight from reality.pdf","sourcePage":10},{"front":"megahertz","meaning":"兆赫","examples":[{"en":"Cellphones transmit at frequencies measured in megahertz.","zh":"手提電話以兆赫為單位量度的頻率傳輸。"},{"en":"Megahertz is a unit used to measure frequency, equal to one million cycles per second.","zh":"megahertz 是量度頻率的單位，等於每秒一百萬次循環。"},{"en":"Radio and phone signals are often described in megahertz.","zh":"無線電和電話訊號常以兆赫描述。"},{"en":"If two systems use very different megahertz ranges, they may be less likely to interfere.","zh":"如果兩個系統使用非常不同的兆赫範圍，它們互相干擾的可能性可能較低。"},{"en":"The word is technical and usually appears in discussions of signals.","zh":"這個詞較技術性，通常出現在訊號討論中。"}],"source":"123 - Flight from reality.pdf","sourcePage":10},{"front":"operate at those frequencies","meaning":"在那些頻率運作","examples":[{"en":"No important aircraft equipment operates at those frequencies.","zh":"沒有重要飛機設備在那些頻率運作。"},{"en":"To operate at those frequencies means to work using those signal frequency ranges.","zh":"operate at those frequencies 指使用那些訊號頻率範圍工作。"},{"en":"A radio receiver operates at certain frequencies so it can pick up the right station.","zh":"無線電接收器在某些頻率運作，以接收正確電台。"},{"en":"If no critical system operates at phone frequencies, direct interference may be less likely.","zh":"如果沒有關鍵系統在電話頻率運作，直接干擾可能較不可能。"},{"en":"The phrase connects equipment function with frequency range.","zh":"這個短語把設備功能與頻率範圍連起來。"}],"source":"123 - Flight from reality.pdf","sourcePage":10},{"front":"possibility of interference","meaning":"干擾的可能性","examples":[{"en":"The possibility of interference from cellphones is very low.","zh":"手提電話造成干擾的可能性很低。"},{"en":"Possibility of interference means the chance that one device may disturb another system.","zh":"possibility of interference 指一個裝置可能干擾另一系統的機會。"},{"en":"Engineers test the possibility of interference before allowing new equipment on board.","zh":"工程師在准許新設備上機前會測試干擾的可能性。"},{"en":"Even a low possibility of interference may matter in aviation safety.","zh":"即使干擾的可能性很低，在航空安全中仍可能重要。"},{"en":"The phrase refers to risk, not confirmed damage.","zh":"這個短語指風險，而不是已確認損害。"}],"source":"123 - Flight from reality.pdf","sourcePage":10},{"front":"much more worrying","meaning":"令人擔心得多","examples":[{"en":"Computers and electronic games are much more worrying, according to Cross.","zh":"根據 Cross 的說法，電腦和電子遊戲機令人擔心得多。"},{"en":"Much more worrying means causing far greater concern than something else.","zh":"much more worrying 指比其他事物造成大得多的憂慮。"},{"en":"A small delay is annoying, but a safety fault is much more worrying.","zh":"小延誤令人煩惱，但安全故障令人擔心得多。"},{"en":"If laptops produce stronger signals, they may be much more worrying than phones.","zh":"如果手提電腦產生更強訊號，它們可能比電話令人擔心得多。"},{"en":"The phrase compares levels of concern strongly.","zh":"這個短語強烈比較憂慮程度。"}],"source":"123 - Flight from reality.pdf","sourcePage":10},{"front":"electronic game systems","meaning":"電子遊戲系統","examples":[{"en":"Electronic game systems may generate strong signals.","zh":"電子遊戲系統可能產生強訊號。"},{"en":"Electronic game systems are devices used to play digital games.","zh":"electronic game systems 指用來玩數碼遊戲的裝置。"},{"en":"A handheld console is a type of electronic game system.","zh":"掌上遊戲機是一種電子遊戲系統。"},{"en":"If an electronic game system sends strong signals, airlines may treat it as a safety concern.","zh":"如果電子遊戲系統發出強訊號，航空公司可能把它視為安全疑慮。"},{"en":"The phrase refers to gaming devices, not games as ideas.","zh":"這個短語指遊戲裝置，而不是遊戲概念。"}],"source":"123 - Flight from reality.pdf","sourcePage":10},{"front":"generate strong signals","meaning":"產生強訊號","examples":[{"en":"Computers can generate strong signals at risky frequencies.","zh":"電腦可以在有風險的頻率產生強訊號。"},{"en":"To generate strong signals means to produce powerful electronic emissions.","zh":"generate strong signals 指產生強力電子發射訊號。"},{"en":"A damaged charger may generate strong signals that disturb nearby speakers.","zh":"受損充電器可能產生強訊號，干擾附近揚聲器。"},{"en":"If computers generate strong signals near aircraft electronics, interference may become possible.","zh":"如果電腦在飛機電子系統附近產生強訊號，干擾可能發生。"},{"en":"The phrase focuses on signal strength and possible disruption.","zh":"這個短語重點是訊號強度和可能干擾。"}],"source":"123 - Flight from reality.pdf","sourcePage":10},{"front":"at frequencies that","meaning":"在……的頻率","examples":[{"en":"Some devices generate signals at frequencies that could interfere with aircraft electronics.","zh":"一些裝置在可能干擾飛機電子系統的頻率產生訊號。"},{"en":"At frequencies that means within signal ranges that have a particular effect or feature.","zh":"at frequencies that 指在具有某種效果或特徵的訊號範圍內。"},{"en":"A radio works at frequencies that match the station it receives.","zh":"收音機在與接收電台相匹配的頻率運作。"},{"en":"Devices operating at risky frequencies can create problems for nearby systems.","zh":"在高風險頻率運作的裝置可能對附近系統造成問題。"},{"en":"The phrase introduces the frequency condition that matters.","zh":"這個短語引入重要的頻率條件。"}],"source":"123 - Flight from reality.pdf","sourcePage":11},{"front":"plane electronics","meaning":"飛機電子系統","examples":[{"en":"Strong signals could interfere with plane electronics.","zh":"強訊號可能干擾飛機電子系統。"},{"en":"Plane electronics are the electronic systems and equipment used inside an aircraft.","zh":"plane electronics 指飛機內使用的電子系統和設備。"},{"en":"Plane electronics help with navigation, communication, monitoring, and control.","zh":"飛機電子系統協助導航、通訊、監察和控制。"},{"en":"If plane electronics receive unwanted signals, pilots may need to check whether systems are working normally.","zh":"如果飛機電子系統接收到不想要的訊號，機師可能需要檢查系統是否正常運作。"},{"en":"The phrase refers to aircraft systems, not passenger gadgets.","zh":"這個短語指飛機系統，而不是乘客小工具。"}],"source":"123 - Flight from reality.pdf","sourcePage":11},{"front":"especially if","meaning":"尤其如果","examples":[{"en":"Computers may be riskier, especially if a mouse is attached.","zh":"電腦可能風險更高，尤其如果接駁了滑鼠。"},{"en":"Especially if means particularly in the situation where something is true.","zh":"especially if 指尤其在某情況成立時。"},{"en":"A road is dangerous, especially if it is wet and dark.","zh":"道路很危險，尤其如果又濕又黑。"},{"en":"A laptop may create more interference, especially if extra wires act like antennae.","zh":"手提電腦可能造成更多干擾，尤其如果額外電線像天線一樣運作。"},{"en":"The phrase highlights a condition that increases risk or importance.","zh":"這個短語突出會增加風險或重要性的條件。"}],"source":"123 - Flight from reality.pdf","sourcePage":11},{"front":"a mouse is attached","meaning":"接駁了滑鼠","examples":[{"en":"A computer may create more risk if a mouse is attached.","zh":"如果接駁了滑鼠，電腦可能造成更多風險。"},{"en":"If a mouse is attached, an external computer mouse is connected to the computer.","zh":"a mouse is attached 指外置電腦滑鼠已連接到電腦。"},{"en":"A student may work faster when a mouse is attached to a laptop.","zh":"當手提電腦接駁了滑鼠，學生可能工作更快。"},{"en":"In this passage, a mouse wire may increase risk because it can act as an antenna.","zh":"在這篇文章中，滑鼠線可能增加風險，因為它可以充當天線。"},{"en":"The phrase describes an added device connection.","zh":"這個短語描述額外裝置連接。"}],"source":"123 - Flight from reality.pdf","sourcePage":11},{"front":"act as an antenna","meaning":"充當天線","examples":[{"en":"The wire of a mouse can act as an antenna.","zh":"滑鼠的電線可以充當天線。"},{"en":"To act as an antenna means to behave like something that receives or sends signals.","zh":"act as an antenna 指像接收或發送訊號的天線一樣運作。"},{"en":"A long wire can sometimes act as an antenna and pick up radio noise.","zh":"長電線有時可以充當天線並接收無線電雜訊。"},{"en":"If a cable acts as an antenna in a plane, it may increase the chance of interference.","zh":"如果電線在飛機上充當天線，可能增加干擾機會。"},{"en":"The phrase means functioning like an antenna, even if it was not designed as one.","zh":"這個短語指功能像天線，即使原本不是設計成天線。"}],"source":"123 - Flight from reality.pdf","sourcePage":11},{"front":"built-in shielding","meaning":"內置屏蔽","examples":[{"en":"Electronic devices are safer when their built-in shielding is undamaged.","zh":"電子裝置的內置屏蔽未受損時會較安全。"},{"en":"Built-in shielding is protective material or design inside a device that reduces unwanted signals.","zh":"built-in shielding 指裝置內用來減少不想要訊號的保護材料或設計。"},{"en":"A well-made cable may have built-in shielding to prevent noise from affecting sound.","zh":"製作良好的電線可能有內置屏蔽，以防雜訊影響聲音。"},{"en":"If built-in shielding is damaged, a device may emit more interference than expected.","zh":"如果內置屏蔽受損，裝置可能發出比預期更多的干擾。"},{"en":"The phrase refers to internal protection, not an external case.","zh":"這個短語指內部保護，而不是外部保護殼。"}],"source":"123 - Flight from reality.pdf","sourcePage":11},{"front":"be damaged","meaning":"受損","examples":[{"en":"Built-in shielding may fail if it is damaged.","zh":"如果內置屏蔽受損，它可能失效。"},{"en":"To be damaged means to be harmed so that something works less well or looks broken.","zh":"be damaged 指受到損害，以致某物運作變差或看起來破損。"},{"en":"A phone screen may be damaged if it falls onto concrete.","zh":"如果手機跌在石屎地上，螢幕可能受損。"},{"en":"If shielding is damaged, a device may no longer block signals properly.","zh":"如果屏蔽受損，裝置可能不再能正確阻隔訊號。"},{"en":"The phrase describes harm to condition or function.","zh":"這個短語描述狀態或功能受到損害。"}],"source":"123 - Flight from reality.pdf","sourcePage":11},{"front":"put sockets in seatbacks","meaning":"在椅背安裝插座","examples":[{"en":"Some airlines are planning to put sockets for laptops in seatbacks.","zh":"一些航空公司正計劃在椅背安裝手提電腦插座。"},{"en":"To put sockets in seatbacks means to install power outlets in the backs of aircraft seats.","zh":"put sockets in seatbacks 指在飛機座椅背部安裝電源插座。"},{"en":"A train company may put sockets in seatbacks so passengers can charge phones.","zh":"火車公司可能在椅背安裝插座，讓乘客為手機充電。"},{"en":"If airlines put sockets in seatbacks, passengers may use laptops for longer periods.","zh":"如果航空公司在椅背安裝插座，乘客可能更長時間使用手提電腦。"},{"en":"The phrase describes adding power access to passenger seats.","zh":"這個短語描述為乘客座位增加電源。"}],"source":"123 - Flight from reality.pdf","sourcePage":11},{"front":"seatbacks","meaning":"椅背","examples":[{"en":"Laptop sockets may be installed in seatbacks.","zh":"手提電腦插座可能安裝在椅背。"},{"en":"Seatbacks are the back parts of seats.","zh":"seatbacks 指座椅的背部。"},{"en":"Airlines often place tray tables and screens in seatbacks.","zh":"航空公司常把餐桌板和螢幕放在椅背上。"},{"en":"If sockets are built into seatbacks, passengers can plug in devices more easily.","zh":"如果插座內置於椅背，乘客可以更容易插入裝置。"},{"en":"The word refers to seat structure, not the seat cushion.","zh":"這個詞指座椅結構，而不是坐墊。"}],"source":"123 - Flight from reality.pdf","sourcePage":11},{"front":"fairly convincing anecdotal evidence","meaning":"頗具說服力的軼事證據","examples":[{"en":"There is fairly convincing anecdotal evidence of device interference.","zh":"有頗具說服力的軼事證據顯示裝置干擾。"},{"en":"Fairly convincing anecdotal evidence means personal reports that seem believable but are not full scientific proof.","zh":"fairly convincing anecdotal evidence 指看似可信的個人報告，但不是完整科學證明。"},{"en":"A teacher may have anecdotal evidence that shorter homework improves sleep, but still need data.","zh":"老師可能有軼事證據顯示較短功課改善睡眠，但仍需要數據。"},{"en":"Anecdotal evidence can raise concern when several people report similar events.","zh":"當多人報告類似事件，軼事證據可以引起關注。"},{"en":"The phrase suggests useful clues, not final proof.","zh":"這個短語暗示有用線索，而不是最終證明。"}],"source":"123 - Flight from reality.pdf","sourcePage":11},{"front":"interfere with systems","meaning":"干擾系統","examples":[{"en":"Some personal electronic devices may have interfered with aircraft systems.","zh":"一些個人電子裝置可能曾干擾飛機系統。"},{"en":"To interfere with systems means to disturb equipment or make it work incorrectly.","zh":"interfere with systems 指干擾設備或令其運作不正常。"},{"en":"A faulty cable can interfere with sound systems during a school performance.","zh":"故障電線可以在學校表演期間干擾音響系統。"},{"en":"If a passenger device interferes with systems on a plane, crew must locate it quickly.","zh":"如果乘客裝置干擾飛機系統，機組人員必須迅速找出它。"},{"en":"The phrase describes technical disruption.","zh":"這個短語描述技術干擾。"}],"source":"123 - Flight from reality.pdf","sourcePage":11},{"front":"aircrew","meaning":"機組人員","examples":[{"en":"Aircrew on one flight found that the autopilot was disconnecting.","zh":"某航班上的機組人員發現自動駕駛系統正在中斷。"},{"en":"Aircrew are the staff who operate or serve on an aircraft during a flight.","zh":"aircrew 指在飛行期間操作或服務於飛機上的工作人員。"},{"en":"Aircrew must respond calmly when passengers ignore safety instructions.","zh":"當乘客忽視安全指示，機組人員必須冷靜回應。"},{"en":"If aircrew notice unusual equipment behaviour, they may ask passengers to turn off devices.","zh":"如果機組人員注意到設備異常，他們可能要求乘客關掉裝置。"},{"en":"The word is similar to flight crew and refers to aircraft staff.","zh":"這個詞與 flight crew 相似，指飛機工作人員。"}],"source":"123 - Flight from reality.pdf","sourcePage":12},{"front":"autopilot","meaning":"自動駕駛系統","examples":[{"en":"The autopilot was being disconnected during one reported incident.","zh":"在一宗已報告事件中，自動駕駛系統正在被中斷。"},{"en":"Autopilot is a system that can help control an aircraft automatically.","zh":"autopilot 指可以協助自動控制飛機的系統。"},{"en":"Pilots use autopilot during some stages of flight to reduce workload.","zh":"機師在部分飛行階段使用自動駕駛系統，以減少工作負荷。"},{"en":"If the autopilot disconnects unexpectedly, pilots must take manual control.","zh":"如果自動駕駛系統意外中斷，機師必須手動控制。"},{"en":"The phrase refers to automatic aircraft control, not a robot pilot.","zh":"這個短語指自動飛機控制，而不是機械人機師。"}],"source":"123 - Flight from reality.pdf","sourcePage":12},{"front":"be disconnected","meaning":"被中斷；被斷開","examples":[{"en":"The autopilot was being disconnected when a portable computer was switched on.","zh":"當一部手提電腦被開啟時，自動駕駛系統正在被中斷。"},{"en":"To be disconnected means to be cut off, stopped, or separated from a system.","zh":"be disconnected 指被切斷、停止或與系統分離。"},{"en":"A video call may be disconnected if the internet fails.","zh":"如果網絡失效，視像通話可能被中斷。"},{"en":"If autopilot is disconnected unexpectedly, pilots must check the aircraft immediately.","zh":"如果自動駕駛系統意外被中斷，機師必須立即檢查飛機。"},{"en":"The phrase can describe technical interruption or physical separation.","zh":"這個短語可以描述技術中斷或實體分離。"}],"source":"123 - Flight from reality.pdf","sourcePage":12},{"front":"narrow the problem down to","meaning":"把問題範圍縮小至","examples":[{"en":"The crew narrowed the problem down to a passenger’s portable computer.","zh":"機組人員把問題範圍縮小至一名乘客的手提電腦。"},{"en":"To narrow the problem down to something means to identify the likely cause from many possibilities.","zh":"narrow the problem down to something 指從多種可能中找出最可能原因。"},{"en":"A doctor may narrow the problem down to one allergy after several tests.","zh":"醫生可能經過幾項測試後，把問題範圍縮小至一種過敏。"},{"en":"Engineers narrow a fault down by turning devices off one by one.","zh":"工程師透過逐一關掉裝置來縮小故障範圍。"},{"en":"The phrase describes reducing uncertainty about the cause.","zh":"這個短語描述減少對原因的不確定性。"}],"source":"123 - Flight from reality.pdf","sourcePage":12},{"front":"portable computer","meaning":"手提電腦","examples":[{"en":"A passenger’s portable computer was suspected of causing interference.","zh":"一名乘客的手提電腦被懷疑造成干擾。"},{"en":"A portable computer is a computer that can be carried easily, such as a laptop.","zh":"portable computer 指可以容易攜帶的電腦，例如手提電腦。"},{"en":"Students use portable computers to take notes and submit assignments.","zh":"學生使用手提電腦做筆記和提交功課。"},{"en":"If a portable computer emits signals, it may need to be checked during sensitive situations.","zh":"如果手提電腦發出訊號，在敏感情況中可能需要檢查。"},{"en":"The phrase is older and more formal than laptop.","zh":"這個短語比 laptop 較舊式和正式。"}],"source":"123 - Flight from reality.pdf","sourcePage":12},{"front":"switch something on","meaning":"開啟","examples":[{"en":"The autopilot disconnected when they switched the computer on.","zh":"當他們開啟電腦時，自動駕駛系統中斷了。"},{"en":"To switch something on means to turn a device on so it starts working.","zh":"switch something on 指開啟裝置，使它開始運作。"},{"en":"A teacher may switch the projector on before showing slides.","zh":"老師可能在展示投影片前開啟投影機。"},{"en":"If a device causes interference when switched on, turning it off may stop the problem.","zh":"如果裝置在開啟時造成干擾，關掉它可能停止問題。"},{"en":"The phrase is the opposite of switch off.","zh":"這個短語是 switch off 的相反。"}],"source":"123 - Flight from reality.pdf","sourcePage":12},{"front":"airline’s labs","meaning":"航空公司的實驗室","examples":[{"en":"Boeing tested the computer in the airline’s labs.","zh":"波音在航空公司的實驗室測試該電腦。"},{"en":"An airline’s labs are testing facilities used by an airline or its partners.","zh":"airline’s labs 指航空公司或其合作伙伴使用的測試設施。"},{"en":"Engineers in an airline’s labs may examine equipment after a reported incident.","zh":"航空公司實驗室中的工程師可能在報告事故後檢查設備。"},{"en":"Testing in labs can control conditions better than testing during a normal passenger flight.","zh":"在實驗室測試比在正常客運航班中測試更能控制條件。"},{"en":"The phrase refers to technical testing spaces, not passenger lounges.","zh":"這個短語指技術測試空間，而不是乘客休息室。"}],"source":"123 - Flight from reality.pdf","sourcePage":12},{"front":"empty flight","meaning":"無乘客航班","examples":[{"en":"The computer was even tested on an empty flight.","zh":"該電腦甚至在無乘客航班上被測試。"},{"en":"An empty flight is a flight with no passengers on board.","zh":"empty flight 指機上沒有乘客的航班。"},{"en":"Airlines may use an empty flight to test equipment without risking passengers.","zh":"航空公司可能使用無乘客航班測試設備，以免乘客承受風險。"},{"en":"Testing on an empty flight can copy aircraft conditions better than a ground lab.","zh":"在無乘客航班上測試比地面實驗室更能模擬飛機情況。"},{"en":"The phrase means the aircraft flies or operates without ordinary passengers.","zh":"這個短語指飛機在沒有普通乘客下飛行或運作。"}],"source":"123 - Flight from reality.pdf","sourcePage":12},{"front":"reported instance","meaning":"已報告個案","examples":[{"en":"Technicians could not replicate any reported instance of interference.","zh":"技術人員無法重現任何已報告的干擾個案。"},{"en":"A reported instance is a case or event that someone has described or recorded.","zh":"reported instance 指有人描述或記錄的個案或事件。"},{"en":"A school may investigate every reported instance of bullying.","zh":"學校可能調查每宗已報告的欺凌個案。"},{"en":"If technicians cannot repeat a reported instance, the cause remains uncertain.","zh":"如果技術人員無法重現已報告個案，原因仍不確定。"},{"en":"The phrase refers to a claimed or recorded case.","zh":"這個短語指被聲稱或記錄的個案。"}],"source":"123 - Flight from reality.pdf","sourcePage":12},{"front":"be unable to replicate","meaning":"無法重現","examples":[{"en":"Technicians were unable to replicate the problem.","zh":"技術人員無法重現該問題。"},{"en":"To be unable to replicate something means to fail to reproduce the same result again.","zh":"be unable to replicate something 指未能再次產生相同結果。"},{"en":"Scientists may be unable to replicate a result if the original data were incomplete.","zh":"如果原始數據不完整，科學家可能無法重現結果。"},{"en":"If engineers cannot replicate an aircraft fault, the exact cause is harder to prove.","zh":"如果工程師無法重現飛機故障，確切原因就較難證明。"},{"en":"The phrase is common in research and testing.","zh":"這個短語常見於研究和測試。"}],"source":"123 - Flight from reality.pdf","sourcePage":12},{"front":"common sense suggests","meaning":"常識顯示","examples":[{"en":"Common sense suggests that phones may be riskier than laptops.","zh":"常識顯示，電話可能比手提電腦風險更高。"},{"en":"Common sense suggests means ordinary practical judgment points to a likely idea.","zh":"common sense suggests 指一般實際判斷指向某個可能想法。"},{"en":"Common sense suggests that tired drivers should not continue on a long road trip.","zh":"常識顯示，疲倦司機不應繼續長途駕駛。"},{"en":"Common sense may suggest one answer, but technical evidence can sometimes disagree.","zh":"常識可能顯示某個答案，但技術證據有時可能不同意。"},{"en":"The phrase relies on practical intuition, not formal proof.","zh":"這個短語依靠實際直覺，而不是正式證明。"}],"source":"123 - Flight from reality.pdf","sourcePage":12},{"front":"be capable of producing","meaning":"能夠產生","examples":[{"en":"A phone is capable of producing a strong emission.","zh":"電話能夠產生強烈發射訊號。"},{"en":"To be capable of producing something means to have the ability to create or generate it.","zh":"be capable of producing something 指有能力創造或產生某物。"},{"en":"A small printer is capable of producing clear documents if it is maintained well.","zh":"如果保養良好，小型打印機也能夠產生清晰文件。"},{"en":"If a device is capable of producing strong signals, regulators may examine it carefully.","zh":"如果裝置能夠產生強訊號，監管者可能仔細檢查它。"},{"en":"The phrase describes ability, not whether it always happens.","zh":"這個短語描述能力，而不是它總是發生。"}],"source":"123 - Flight from reality.pdf","sourcePage":13},{"front":"strong emission","meaning":"強烈發射訊號","examples":[{"en":"A mobile phone can produce a strong intentional emission.","zh":"手提電話可以產生強烈的有意發射訊號。"},{"en":"A strong emission is a powerful signal or energy output sent from a device.","zh":"strong emission 指裝置發出的強力訊號或能量輸出。"},{"en":"A radio transmitter creates strong emissions so messages can travel far.","zh":"無線電發射器產生強烈發射訊號，使訊息能傳得遠。"},{"en":"Strong emissions near sensitive equipment may increase interference risk.","zh":"敏感設備附近的強烈發射訊號可能增加干擾風險。"},{"en":"The phrase focuses on signal strength.","zh":"這個短語重點是訊號強度。"}],"source":"123 - Flight from reality.pdf","sourcePage":13},{"front":"intentional emission","meaning":"有意發出的訊號","examples":[{"en":"A mobile phone produces intentional emissions.","zh":"手提電話會產生有意發出的訊號。"},{"en":"Intentional emission means a signal deliberately produced by a device to communicate.","zh":"intentional emission 指裝置為了通訊而刻意產生的訊號。"},{"en":"A Wi-Fi router creates intentional emissions so devices can connect.","zh":"Wi-Fi 路由器產生有意發出的訊號，讓裝置連接。"},{"en":"Intentional emissions differ from accidental electronic noise because they are part of the device’s function.","zh":"有意發出的訊號不同於意外電子雜訊，因為它們是裝置功能的一部分。"},{"en":"The phrase is technical and explains why phones are treated differently.","zh":"這個短語較技術性，解釋為何電話被不同對待。"}],"source":"123 - Flight from reality.pdf","sourcePage":13},{"front":"prohibited","meaning":"被禁止","examples":[{"en":"Cellphones are prohibited on flights, but computers are not.","zh":"手提電話在航班上被禁止，但電腦沒有。"},{"en":"Prohibited means officially not allowed.","zh":"prohibited 指被正式禁止。"},{"en":"Smoking is prohibited in many restaurants and public buildings.","zh":"在許多餐廳和公共建築內，吸煙被禁止。"},{"en":"If phones are prohibited on flights, passengers must follow the rule even if they disagree.","zh":"如果電話在航班上被禁止，即使乘客不同意，也必須遵守規則。"},{"en":"The word is formal and stronger than not recommended.","zh":"這個詞較正式，比 not recommended 語氣更強。"}],"source":"123 - Flight from reality.pdf","sourcePage":13},{"front":"illogical","meaning":"不合邏輯的","examples":[{"en":"Many experts think it is illogical that phones are banned while computers are allowed.","zh":"許多專家認為禁止電話但准許電腦是不合邏輯的。"},{"en":"Illogical means not reasonable or not following clear logic.","zh":"illogical 指不合理或不符合清晰邏輯。"},{"en":"It is illogical to punish late students but ignore late teachers.","zh":"懲罰遲到學生卻忽視遲到老師是不合邏輯的。"},{"en":"A policy seems illogical when it bans one device but allows another riskier one.","zh":"當政策禁止一種裝置卻准許另一種風險更高的裝置，它就顯得不合邏輯。"},{"en":"The word criticises weak reasoning.","zh":"這個詞批評薄弱推理。"}],"source":"123 - Flight from reality.pdf","sourcePage":13},{"front":"besides","meaning":"此外","examples":[{"en":"Besides, the problem is more complicated than power and frequency alone.","zh":"此外，問題比單看功率和頻率更複雜。"},{"en":"Besides means in addition or also.","zh":"besides 指此外或也。"},{"en":"The train is cheaper; besides, it is more comfortable than the bus.","zh":"火車較便宜；此外，它比巴士更舒適。"},{"en":"Besides technical risk, airlines may also consider cost and passenger behaviour.","zh":"除了技術風險，航空公司也可能考慮成本和乘客行為。"},{"en":"The word adds another reason or point.","zh":"這個詞加入另一個原因或要點。"}],"source":"123 - Flight from reality.pdf","sourcePage":13},{"front":"more complicated than","meaning":"比……更複雜","examples":[{"en":"The issue is more complicated than simply looking at power and frequency.","zh":"該問題比只是看功率和頻率更複雜。"},{"en":"More complicated than means involving more factors or difficulty than something else suggests.","zh":"more complicated than 指涉及的因素或困難比某事所暗示的更多。"},{"en":"Choosing a school is more complicated than comparing exam results only.","zh":"選學校比單純比較考試成績更複雜。"},{"en":"Aircraft interference is more complicated than checking one device in isolation.","zh":"飛機干擾比孤立檢查一個裝置更複雜。"},{"en":"The phrase warns that a simple explanation is not enough.","zh":"這個短語提醒我們簡單解釋不足夠。"}],"source":"123 - Flight from reality.pdf","sourcePage":13},{"front":"simply looking at","meaning":"只是看……","examples":[{"en":"The problem cannot be solved by simply looking at power and frequency.","zh":"問題不能透過只是看功率和頻率來解決。"},{"en":"Simply looking at something means considering only that thing in a basic way.","zh":"simply looking at something 指只以基本方式考慮某事。"},{"en":"You cannot judge a student by simply looking at one test score.","zh":"你不能只是看一次測驗分數就判斷學生。"},{"en":"Simply looking at signal strength may miss how signals combine in the cabin.","zh":"只是看訊號強度可能會忽略訊號在機艙內如何結合。"},{"en":"The phrase often criticises an overly narrow approach.","zh":"這個短語常批評過於狹窄的做法。"}],"source":"123 - Flight from reality.pdf","sourcePage":13},{"front":"operate in a soup of","meaning":"在大量混雜的……中運作","examples":[{"en":"In the air, a plane operates in a soup of electronic emissions.","zh":"在空中，飛機在大量混雜的電子發射訊號中運作。"},{"en":"To operate in a soup of something means to work in a messy mixture of many things.","zh":"operate in a soup of something 指在大量混雜的事物中運作。"},{"en":"A city hospital operates in a soup of noise, pressure, and urgent decisions.","zh":"城市醫院在噪音、壓力和緊急決策混雜的環境中運作。"},{"en":"Aircraft electronics operate in a soup of signals from the ground, cabin, and other systems.","zh":"飛機電子系統在來自地面、機艙和其他系統的混雜訊號中運作。"},{"en":"The phrase is metaphorical and suggests a complex mixed environment.","zh":"這個短語是比喻用法，暗示複雜混合環境。"}],"source":"123 - Flight from reality.pdf","sourcePage":13},{"front":"electronic emissions","meaning":"電子發射訊號","examples":[{"en":"The aircraft is surrounded by electronic emissions.","zh":"飛機被電子發射訊號包圍。"},{"en":"Electronic emissions are signals or energy outputs produced by electronic equipment.","zh":"electronic emissions 指電子設備產生的訊號或能量輸出。"},{"en":"Computers, phones, and radios can all produce electronic emissions.","zh":"電腦、電話和無線電都可以產生電子發射訊號。"},{"en":"Too many electronic emissions near sensitive devices may increase interference risk.","zh":"敏感裝置附近過多電子發射訊號可能增加干擾風險。"},{"en":"The phrase is technical and often used in safety discussions.","zh":"這個短語較技術性，常用於安全討論。"}],"source":"123 - Flight from reality.pdf","sourcePage":13},{"front":"ground-based radiation","meaning":"地面輻射","examples":[{"en":"Ground-based radiation also contributes to the aircraft’s electronic environment.","zh":"地面輻射也構成飛機的電子環境。"},{"en":"Ground-based radiation means signals or energy coming from equipment on the ground.","zh":"ground-based radiation 指來自地面設備的訊號或能量。"},{"en":"Radio towers and base stations can produce ground-based radiation.","zh":"無線電塔和基站可以產生地面輻射。"},{"en":"Aircraft may receive ground-based radiation while flying over cities or communication networks.","zh":"飛機飛越城市或通訊網絡時，可能接收到地面輻射。"},{"en":"The phrase contrasts signals from the ground with signals inside the aircraft.","zh":"這個短語把來自地面的訊號與飛機內部訊號作對比。"}],"source":"123 - Flight from reality.pdf","sourcePage":13},{"front":"in the cabin","meaning":"在機艙內","examples":[{"en":"Electronic devices in the cabin can behave unpredictably.","zh":"機艙內的電子裝置可能表現難以預測。"},{"en":"In the cabin means inside the passenger area of an aircraft.","zh":"in the cabin 指在飛機乘客區內。"},{"en":"Passengers store bags in the cabin during a flight.","zh":"乘客在飛行期間把行李放在機艙內。"},{"en":"Devices in the cabin may be closer to passengers than to external aircraft antennae.","zh":"機艙內的裝置可能比外部飛機天線更接近乘客。"},{"en":"The phrase refers to the inside passenger space, not the cockpit or outside.","zh":"這個短語指乘客內部空間，而不是駕駛艙或外部。"}],"source":"123 - Flight from reality.pdf","sourcePage":14},{"front":"emit a strong signal","meaning":"發出強訊號","examples":[{"en":"Devices emitting a strong signal may disrupt other systems.","zh":"發出強訊號的裝置可能干擾其他系統運作。"},{"en":"To emit a strong signal means to send out a powerful electronic or radio signal.","zh":"emit a strong signal 指發出強力電子或無線電訊號。"},{"en":"A wireless router may emit a strong signal so users can connect from another room.","zh":"無線路由器可能發出強訊號，讓使用者在另一個房間連接。"},{"en":"If a device emits a strong signal on a plane, staff may ask for it to be turned off.","zh":"如果裝置在飛機上發出強訊號，職員可能要求關掉它。"},{"en":"The phrase focuses on signal output and possible interference.","zh":"這個短語重點是訊號輸出和可能干擾。"}],"source":"123 - Flight from reality.pdf","sourcePage":14},{"front":"behave unpredictably","meaning":"表現難以預測","examples":[{"en":"Electronic devices can behave unpredictably in the air.","zh":"電子裝置在空中可能表現難以預測。"},{"en":"To behave unpredictably means to act in a way that is hard to foresee or control.","zh":"behave unpredictably 指以難以預見或控制的方式運作。"},{"en":"A damaged phone may behave unpredictably by switching off at random.","zh":"受損電話可能隨機關機，表現難以預測。"},{"en":"If devices behave unpredictably near aircraft systems, safety engineers become concerned.","zh":"如果裝置在飛機系統附近表現難以預測，安全工程師會擔心。"},{"en":"The phrase describes uncertain behaviour, not normal reliable operation.","zh":"這個短語描述不確定行為，而不是正常可靠運作。"}],"source":"123 - Flight from reality.pdf","sourcePage":14},{"front":"reinforce other signals","meaning":"加強其他訊號","examples":[{"en":"A device may reinforce other signals inside the aircraft.","zh":"裝置可能加強飛機內其他訊號。"},{"en":"To reinforce other signals means to strengthen or add to signals already present.","zh":"reinforce other signals 指增強或疊加已存在的訊號。"},{"en":"A microphone too close to a speaker can reinforce sound and create feedback.","zh":"麥克風太接近揚聲器時，可以加強聲音並造成回音。"},{"en":"If one electronic emission reinforces other signals, the combined effect may be stronger than expected.","zh":"如果一個電子發射訊號加強其他訊號，綜合效果可能比預期更強。"},{"en":"The phrase suggests signals interacting with each other.","zh":"這個短語暗示訊號之間互相作用。"}],"source":"123 - Flight from reality.pdf","sourcePage":14},{"front":"unforeseen harmonics","meaning":"無法預見的諧波","examples":[{"en":"Devices may create unforeseen harmonics that disrupt systems.","zh":"裝置可能產生無法預見的諧波，干擾系統運作。"},{"en":"Unforeseen harmonics are unexpected signal patterns produced when electronic waves interact.","zh":"unforeseen harmonics 指電子波互相作用時產生的意外訊號模式。"},{"en":"Engineers worry about unforeseen harmonics because they may appear only in complex real conditions.","zh":"工程師擔心無法預見的諧波，因為它們可能只在複雜真實環境中出現。"},{"en":"If unforeseen harmonics disrupt aircraft electronics, simple frequency checks may miss the risk.","zh":"如果無法預見的諧波干擾飛機電子系統，簡單頻率檢查可能錯過風險。"},{"en":"The phrase is technical and means unexpected signal effects.","zh":"這個短語較技術性，意思是意外訊號效應。"}],"source":"123 - Flight from reality.pdf","sourcePage":14},{"front":"disrupt systems","meaning":"干擾系統運作","examples":[{"en":"Unforeseen harmonics may disrupt aircraft systems.","zh":"無法預見的諧波可能干擾飛機系統運作。"},{"en":"To disrupt systems means to interrupt or disturb their normal operation.","zh":"disrupt systems 指打斷或干擾系統的正常運作。"},{"en":"A power cut can disrupt computer systems in an office.","zh":"停電可以干擾辦公室電腦系統運作。"},{"en":"If signals disrupt systems on a plane, the crew may receive wrong information.","zh":"如果訊號干擾飛機系統運作，機組人員可能收到錯誤資訊。"},{"en":"The phrase suggests serious interference with normal function.","zh":"這個短語暗示對正常功能的嚴重干擾。"}],"source":"123 - Flight from reality.pdf","sourcePage":14},{"front":"despite the hearings","meaning":"儘管舉行了聽證會","examples":[{"en":"Despite the hearings, no technical solution is being seriously developed.","zh":"儘管舉行了聽證會，仍沒有技術解決方案被認真開發。"},{"en":"Despite the hearings means although official discussions or questioning sessions took place.","zh":"despite the hearings 指雖然已舉行正式討論或質詢會議。"},{"en":"Despite the hearings, the school board did not change the phone policy.","zh":"儘管舉行了聽證會，校董會仍沒有改變手機政策。"},{"en":"Hearings can raise public attention, but they do not always lead to action.","zh":"聽證會可以提高公眾關注，但不一定帶來行動。"},{"en":"The phrase contrasts discussion with lack of progress.","zh":"這個短語把討論與缺乏進展作對比。"}],"source":"123 - Flight from reality.pdf","sourcePage":14},{"front":"technical solution","meaning":"技術解決方案","examples":[{"en":"No one is seriously working on a technical solution for cellphone use in planes.","zh":"沒有人認真研究讓飛機上使用手提電話的技術解決方案。"},{"en":"A technical solution is a practical answer based on technology or engineering.","zh":"technical solution 指基於科技或工程的實際解決方法。"},{"en":"Installing better filters may be a technical solution to signal interference.","zh":"安裝更好的濾波器可能是訊號干擾的技術解決方案。"},{"en":"A technical solution can reduce risk without banning the activity completely.","zh":"技術解決方案可以降低風險，而不必完全禁止該活動。"},{"en":"The phrase refers to solving a problem through tools, systems, or design.","zh":"這個短語指透過工具、系統或設計解決問題。"}],"source":"123 - Flight from reality.pdf","sourcePage":14},{"front":"allow passengers to","meaning":"讓乘客能夠","examples":[{"en":"A technical solution might allow passengers to use their phones.","zh":"技術解決方案可能讓乘客能夠使用電話。"},{"en":"To allow passengers to do something means to permit travellers to do it.","zh":"allow passengers to do something 指准許旅客做某事。"},{"en":"Airlines may allow passengers to use laptops after take-off.","zh":"航空公司可能在起飛後讓乘客能夠使用手提電腦。"},{"en":"If safety improves, regulators may allow passengers to use more devices in the cabin.","zh":"如果安全性改善，監管者可能讓乘客能夠在機艙內使用更多裝置。"},{"en":"The phrase focuses on permission given to travellers.","zh":"這個短語重點是給予旅客許可。"}],"source":"123 - Flight from reality.pdf","sourcePage":14},{"front":"no one seems to be working seriously on","meaning":"似乎沒有人認真研究","examples":[{"en":"No one seems to be working seriously on a solution to allow phone use.","zh":"似乎沒有人認真研究讓電話使用成為可能的解決方案。"},{"en":"No one seems to be working seriously on something means there is little real effort to develop it.","zh":"no one seems to be working seriously on something 指幾乎沒有真正努力去發展某事。"},{"en":"If no one works seriously on a timetable problem, delays will continue.","zh":"如果沒有人認真研究時間表問題，延誤會繼續。"},{"en":"A solution may remain theoretical when no company is working seriously on it.","zh":"當沒有公司認真研究某方案，它可能仍停留在理論層面。"},{"en":"The phrase suggests lack of commitment, not complete impossibility.","zh":"這個短語暗示缺乏投入，而不是完全不可能。"}],"source":"123 - Flight from reality.pdf","sourcePage":14},{"front":"besides cellphone users themselves","meaning":"除了手提電話用戶本身","examples":[{"en":"Besides cellphone users themselves, few groups would gain much from allowing phones.","zh":"除了手提電話用戶本身，很少群體會從准許電話使用中得到很多好處。"},{"en":"Besides cellphone users themselves means apart from the passengers who want to use phones.","zh":"besides cellphone users themselves 指除了想使用電話的乘客之外。"},{"en":"Besides students themselves, few people may benefit from cancelling homework entirely.","zh":"除了學生本身，很少人可能會從完全取消功課中受益。"},{"en":"If only users benefit, businesses may not invest in a technical solution.","zh":"如果只有用戶受益，企業可能不會投資技術解決方案。"},{"en":"The phrase narrows the group that would gain from a change.","zh":"這個短語收窄會從改變中得益的群體。"}],"source":"123 - Flight from reality.pdf","sourcePage":14},{"front":"stand to gain","meaning":"有望得益","examples":[{"en":"Few companies stand to gain a lot if phones are allowed in the air.","zh":"如果飛行中准許使用電話，很少公司有望得到很大好處。"},{"en":"To stand to gain means to be likely to benefit from something.","zh":"stand to gain 指很可能從某事中受益。"},{"en":"Shops near a new station stand to gain more customers.","zh":"新車站附近的商店有望得到更多顧客。"},{"en":"If airlines do not stand to gain money from phone use, they may not push for change.","zh":"如果航空公司無法從電話使用中得益，它們可能不會推動改變。"},{"en":"The phrase focuses on expected benefit.","zh":"這個短語重點是預期好處。"}],"source":"123 - Flight from reality.pdf","sourcePage":15},{"front":"in the air","meaning":"在空中；飛行中","examples":[{"en":"Cellphone use is banned while passengers are in the air.","zh":"乘客在空中時，手提電話使用被禁止。"},{"en":"In the air means during flight, when the aircraft is not on the ground.","zh":"in the air 指飛行期間，即飛機不在地面時。"},{"en":"Passengers may feel more relaxed once the plane is safely in the air.","zh":"當飛機安全在空中，乘客可能感到較放鬆。"},{"en":"Signals behave differently in the air because they may reach many stations at once.","zh":"訊號在空中的表現不同，因為它們可能同時到達許多基站。"},{"en":"The phrase refers to the flying stage of travel.","zh":"這個短語指旅程中的飛行階段。"}],"source":"123 - Flight from reality.pdf","sourcePage":15},{"front":"be concerned that","meaning":"擔心","examples":[{"en":"Cellphone companies are concerned that airborne signals could cause network problems.","zh":"手提電話公司擔心空中訊號可能造成網絡問題。"},{"en":"To be concerned that something may happen means to worry that it may happen.","zh":"be concerned that something may happen 指擔心某事可能發生。"},{"en":"Parents are concerned that too much screen time may affect sleep.","zh":"父母擔心過多螢幕時間可能影響睡眠。"},{"en":"Companies may be concerned that new rules will increase costs.","zh":"公司可能擔心新規則會增加成本。"},{"en":"The phrase introduces a worry or risk.","zh":"這個短語引入憂慮或風險。"}],"source":"123 - Flight from reality.pdf","sourcePage":15},{"front":"airborne signals","meaning":"空中訊號","examples":[{"en":"Airborne signals can reach many base stations at once.","zh":"空中訊號可以同時到達許多基站。"},{"en":"Airborne signals are signals sent from a device while it is in the air.","zh":"airborne signals 指裝置在空中發出的訊號。"},{"en":"A phone used on a plane may create airborne signals over a wide area.","zh":"在飛機上使用電話可能在大範圍產生空中訊號。"},{"en":"Because airborne signals travel from high above the ground, they may reach more receivers.","zh":"由於空中訊號從地面上方高處傳播，它們可能到達更多接收器。"},{"en":"The phrase contrasts signals from aircraft with ordinary ground-level signals.","zh":"這個短語把來自飛機的訊號與普通地面訊號作對比。"}],"source":"123 - Flight from reality.pdf","sourcePage":15},{"front":"flooding base stations","meaning":"令基站同時收到大量訊號","examples":[{"en":"Airborne signals could cause problems by flooding base stations with the same signal.","zh":"空中訊號可能透過令基站同時收到大量同一訊號而造成問題。"},{"en":"Flooding base stations means sending so much signal to many stations that the network may be overloaded.","zh":"flooding base stations 指向許多基站發送大量訊號，以致網絡可能負荷過重。"},{"en":"A sudden rush of emergency calls can flood phone networks after an earthquake.","zh":"地震後突然湧現的緊急電話可以令電話網絡負荷過重。"},{"en":"If one airborne phone floods base stations, the network may waste resources handling repeated signals.","zh":"如果一部空中電話令基站同時收到大量訊號，網絡可能浪費資源處理重複訊號。"},{"en":"The phrase describes overload caused by too many received signals.","zh":"這個短語描述由太多接收訊號造成的負荷過重。"}],"source":"123 - Flight from reality.pdf","sourcePage":15},{"front":"base stations","meaning":"基站","examples":[{"en":"Cellphone signals normally connect to one or two base stations.","zh":"手提電話訊號通常連接一至兩個基站。"},{"en":"Base stations are fixed communication points that connect mobile phones to a network.","zh":"base stations 指把手提電話連接到網絡的固定通訊點。"},{"en":"A city needs many base stations so phones can keep signal in different districts.","zh":"城市需要許多基站，好讓電話在不同地區保持訊號。"},{"en":"If too many base stations receive the same signal, network management becomes harder.","zh":"如果太多基站接收到同一訊號，網絡管理會變得較困難。"},{"en":"The phrase refers to phone-network infrastructure.","zh":"這個短語指電話網絡基礎設施。"}],"source":"123 - Flight from reality.pdf","sourcePage":15},{"front":"at once","meaning":"同時","examples":[{"en":"Airborne cellphone signals may reach many base stations at once.","zh":"空中手提電話訊號可能同時到達許多基站。"},{"en":"At once means at the same time.","zh":"at once 指同一時間。"},{"en":"If many students speak at once, the teacher cannot hear any answer clearly.","zh":"如果許多學生同時說話，老師就不能清楚聽到任何答案。"},{"en":"A signal reaching many receivers at once can create network confusion.","zh":"訊號同時到達許多接收器可能造成網絡混亂。"},{"en":"The phrase focuses on simultaneous action.","zh":"這個短語重點是同時發生的行動。"}],"source":"123 - Flight from reality.pdf","sourcePage":15},{"front":"the same signal","meaning":"同一訊號","examples":[{"en":"Many base stations may receive the same signal from an airborne phone.","zh":"許多基站可能接收到來自空中電話的同一訊號。"},{"en":"The same signal means one identical transmission received in more than one place.","zh":"the same signal 指同一個傳輸訊號在多於一個地方被接收。"},{"en":"Several radios can pick up the same signal from one broadcast tower.","zh":"多部收音機可以接收到來自同一廣播塔的同一訊號。"},{"en":"If many base stations receive the same signal, the network may not know which one should handle it.","zh":"如果許多基站接收到同一訊號，網絡可能不知道應由哪一個處理。"},{"en":"The phrase highlights duplication, not different messages.","zh":"這個短語強調重複，而不是不同訊息。"}],"source":"123 - Flight from reality.pdf","sourcePage":15},{"front":"bigfooting","meaning":"大腳效應","examples":[{"en":"Bigfooting happens when airborne cellphone signals reach many base stations at once.","zh":"當空中手提電話訊號同時到達許多基站時，就會發生大腳效應。"},{"en":"Bigfooting is a network problem where one airborne phone signal covers too wide an area.","zh":"bigfooting 指一個空中電話訊號覆蓋範圍過廣的網絡問題。"},{"en":"A phone in the air can cause bigfooting because it can be seen by many base stations.","zh":"飛行中的電話可能造成大腳效應，因為許多基站都能接收到它。"},{"en":"Bigfooting may waste network capacity and confuse call handling.","zh":"大腳效應可能浪費網絡容量並令通話處理混亂。"},{"en":"The term is technical and linked to mobile networks, not the mythical creature.","zh":"這個術語較技術性，與流動網絡有關，而不是神秘生物。"}],"source":"123 - Flight from reality.pdf","sourcePage":15},{"front":"tend to","meaning":"傾向於","examples":[{"en":"Airborne cellphone signals tend to go to many base stations at once.","zh":"空中手提電話訊號傾向於同時傳到許多基站。"},{"en":"Tend to means usually or are likely to.","zh":"tend to 指通常會或很可能會。"},{"en":"Students tend to remember examples better when they are connected to daily life.","zh":"當例子與日常生活有關，學生傾向於記得更好。"},{"en":"Signals from high places tend to travel farther than signals blocked by buildings.","zh":"來自高處的訊號傾向於比被建築物阻隔的訊號傳得更遠。"},{"en":"The phrase describes a common pattern, not an absolute rule.","zh":"這個短語描述常見模式，而不是絕對規則。"}],"source":"123 - Flight from reality.pdf","sourcePage":15},{"front":"land calls","meaning":"地面通話","examples":[{"en":"Land calls usually go to just one or two base stations.","zh":"地面通話通常只傳到一至兩個基站。"},{"en":"Land calls are mobile-phone calls made from the ground rather than from the air.","zh":"land calls 指從地面而不是空中打出的手提電話通話。"},{"en":"Land calls in a city are usually handled by nearby base stations.","zh":"城市中的地面通話通常由附近基站處理。"},{"en":"Because land calls stay low, they normally reach fewer stations than airborne calls.","zh":"由於地面通話位置較低，它們通常比空中通話到達較少基站。"},{"en":"The phrase contrasts ordinary ground calls with calls made from aircraft.","zh":"這個短語把普通地面通話與飛機上通話作對比。"}],"source":"123 - Flight from reality.pdf","sourcePage":15},{"front":"prohibit cellphones","meaning":"禁止手提電話","examples":[{"en":"FAA and FCC regulations prohibit cellphones in the air.","zh":"美國聯邦航空管理局和聯邦通訊委員會的規例禁止在空中使用手提電話。"},{"en":"To prohibit cellphones means to officially ban the use of mobile phones.","zh":"prohibit cellphones 指正式禁止使用手提電話。"},{"en":"Schools may prohibit cellphones during exams to prevent cheating.","zh":"學校可能在考試期間禁止手提電話，以防作弊。"},{"en":"Regulators prohibit cellphones on flights when they believe risk or network problems may occur.","zh":"當監管者認為可能出現風險或網絡問題，就會禁止航班上使用手提電話。"},{"en":"The phrase is formal and policy-focused.","zh":"這個短語較正式，偏向政策用語。"}],"source":"123 - Flight from reality.pdf","sourcePage":16},{"front":"Federal Communications Commission","meaning":"聯邦通訊委員會","examples":[{"en":"The Federal Communications Commission also restricts cellphone use in the air.","zh":"聯邦通訊委員會也限制空中手提電話使用。"},{"en":"The Federal Communications Commission is the US agency that regulates communications such as radio, television, and phone networks.","zh":"Federal Communications Commission 指監管無線電、電視和電話網絡等通訊的美國機構。"},{"en":"The FCC may make rules about how wireless signals can be used.","zh":"FCC 可能制定有關無線訊號如何使用的規則。"},{"en":"Because airborne phone signals affect networks, the Federal Communications Commission has a role in the issue.","zh":"由於空中電話訊號影響網絡，聯邦通訊委員會在該議題中有角色。"},{"en":"The phrase is a formal organisation name.","zh":"這個短語是正式機構名稱。"}],"source":"123 - Flight from reality.pdf","sourcePage":16},{"front":"possible solutions","meaning":"可能的解決方案","examples":[{"en":"Possible solutions include better insulation and signal detectors.","zh":"可能的解決方案包括更好絕緣和訊號探測器。"},{"en":"Possible solutions are actions or ideas that may solve a problem.","zh":"possible solutions 指可能解決問題的行動或想法。"},{"en":"For traffic jams, possible solutions include better buses, road pricing, and flexible work hours.","zh":"對於交通擠塞，可能的解決方案包括更好的巴士、道路收費和彈性工作時間。"},{"en":"Possible solutions must be tested before they become official policy.","zh":"可能的解決方案必須先測試，才成為正式政策。"},{"en":"The phrase presents options, not guaranteed answers.","zh":"這個短語提出選項，而不是保證有效的答案。"}],"source":"123 - Flight from reality.pdf","sourcePage":16},{"front":"enhance electronic insulation","meaning":"加強電子絕緣","examples":[{"en":"Airliners could enhance electronic insulation to reduce interference.","zh":"客機可以加強電子絕緣以減少干擾。"},{"en":"To enhance electronic insulation means to improve protection against unwanted electronic signals.","zh":"enhance electronic insulation 指改善對不想要電子訊號的保護。"},{"en":"A hospital may enhance electronic insulation around sensitive scanning machines.","zh":"醫院可能在敏感掃描機周圍加強電子絕緣。"},{"en":"Better insulation can reduce the chance that one device disrupts another.","zh":"更好的絕緣可以降低一個裝置干擾另一裝置的機會。"},{"en":"The phrase refers to strengthening technical protection.","zh":"這個短語指加強技術保護。"}],"source":"123 - Flight from reality.pdf","sourcePage":16},{"front":"fit detectors","meaning":"安裝探測器","examples":[{"en":"Airlines could fit detectors to warn staff about dangerous signals.","zh":"航空公司可以安裝探測器，以警告職員有危險訊號。"},{"en":"To fit detectors means to install devices that can sense or identify a problem.","zh":"fit detectors 指安裝可以感應或辨認問題的裝置。"},{"en":"A building owner may fit smoke detectors in every corridor.","zh":"業主可能在每條走廊安裝煙霧探測器。"},{"en":"If aircraft fit detectors for interference, crews may know when a device emits risky signals.","zh":"如果飛機安裝干擾探測器，機組人員可能知道何時有裝置發出高風險訊號。"},{"en":"The phrase focuses on installing warning equipment.","zh":"這個短語重點是安裝警報設備。"}],"source":"123 - Flight from reality.pdf","sourcePage":16},{"front":"warn flight staff","meaning":"警告機組人員","examples":[{"en":"Detectors could warn flight staff when devices emit dangerous signals.","zh":"當裝置發出危險訊號時，探測器可以警告機組人員。"},{"en":"To warn flight staff means to alert aircraft workers to a possible danger.","zh":"warn flight staff 指提醒飛機工作人員有可能危險。"},{"en":"A cabin alarm can warn flight staff that smoke has been detected.","zh":"機艙警報可以警告機組人員已偵測到煙霧。"},{"en":"If detectors warn flight staff early, they can ask passengers to switch off devices.","zh":"如果探測器及早警告機組人員，他們可以要求乘客關掉裝置。"},{"en":"The phrase focuses on giving staff time to respond.","zh":"這個短語重點是給職員時間回應。"}],"source":"123 - Flight from reality.pdf","sourcePage":16},{"front":"emit dangerous signals","meaning":"發出危險訊號","examples":[{"en":"Passenger devices may emit dangerous signals.","zh":"乘客裝置可能發出危險訊號。"},{"en":"To emit dangerous signals means to send out electronic signals that may cause harm or interference.","zh":"emit dangerous signals 指發出可能造成傷害或干擾的電子訊號。"},{"en":"A faulty device may emit dangerous signals without the user noticing.","zh":"故障裝置可能在使用者不察覺下發出危險訊號。"},{"en":"If equipment emits dangerous signals near aircraft electronics, staff may need to shut it down.","zh":"如果設備在飛機電子系統附近發出危險訊號，職員可能需要關掉它。"},{"en":"The phrase describes signal output that creates risk.","zh":"這個短語描述造成風險的訊號輸出。"}],"source":"123 - Flight from reality.pdf","sourcePage":16},{"front":"show much interest in","meaning":"對……表現出很大興趣","examples":[{"en":"The FAA, airlines and manufacturers show little interest in developing detectors.","zh":"美國聯邦航空管理局、航空公司和製造商對開發探測器表現出很少興趣。"},{"en":"To show much interest in something means to appear eager to support, discuss, or invest in it.","zh":"show much interest in something 指看起來願意支持、討論或投資某事。"},{"en":"Students show much interest in a topic when they ask many questions.","zh":"當學生提出很多問題，他們就是對某主題表現出很大興趣。"},{"en":"If companies show little interest in a detector, it may not become a product quickly.","zh":"如果公司對探測器表現出很少興趣，它可能不會很快成為產品。"},{"en":"The phrase describes visible attention or enthusiasm.","zh":"這個短語描述可見的注意或熱情。"}],"source":"123 - Flight from reality.pdf","sourcePage":16},{"front":"Congressional suspicions","meaning":"國會疑慮","examples":[{"en":"Congressional suspicions did not change the industry’s policy.","zh":"國會疑慮沒有改變該行業的政策。"},{"en":"Congressional suspicions are doubts or concerns held by members of Congress.","zh":"Congressional suspicions 指國會成員持有的懷疑或憂慮。"},{"en":"Congressional suspicions may lead to hearings, questions, or requests for evidence.","zh":"國會疑慮可能帶來聽證會、質詢或要求提供證據。"},{"en":"If suspicions are not supported by strong evidence, policy may remain unchanged.","zh":"如果疑慮沒有強力證據支持，政策可能保持不變。"},{"en":"The phrase connects political doubt with official investigation.","zh":"這個短語把政治懷疑與官方調查連起來。"}],"source":"123 - Flight from reality.pdf","sourcePage":16},{"front":"the occasional irritated user","meaning":"偶爾感到不滿的用戶","examples":[{"en":"The occasional irritated mobile user may object to the ban.","zh":"偶爾感到不滿的手提電話用戶可能反對禁令。"},{"en":"The occasional irritated user means a few users who sometimes feel annoyed.","zh":"occasional irritated user 指少數有時感到惱怒的用戶。"},{"en":"The occasional irritated passenger may complain when Wi-Fi is unavailable.","zh":"偶爾感到不滿的乘客可能在沒有 Wi-Fi 時投訴。"},{"en":"If only occasional irritated users object, companies may not change policy.","zh":"如果只有偶爾感到不滿的用戶反對，公司可能不會改變政策。"},{"en":"The phrase minimises the size and force of opposition.","zh":"這個短語弱化反對者的數量和力量。"}],"source":"123 - Flight from reality.pdf","sourcePage":16},{"front":"better safe than sorry policy","meaning":"寧可安全為上的政策","examples":[{"en":"The industry’s better safe than sorry policy is likely to continue.","zh":"該行業寧可安全為上的政策很可能繼續。"},{"en":"A better safe than sorry policy chooses caution even when the risk is uncertain.","zh":"better safe than sorry policy 指即使風險不確定，也選擇謹慎的政策。"},{"en":"A school may follow a better safe than sorry policy by closing during a severe storm warning.","zh":"學校可能在嚴重暴風警告期間停課，採取寧可安全為上的政策。"},{"en":"Airlines may keep a better safe than sorry policy because even a tiny risk seems unacceptable.","zh":"航空公司可能維持寧可安全為上的政策，因為即使微小風險也似乎不能接受。"},{"en":"The phrase describes cautious rule-making.","zh":"這個短語描述謹慎制定規則。"}],"source":"123 - Flight from reality.pdf","sourcePage":16},{"front":"be likely to continue","meaning":"很可能繼續","examples":[{"en":"The mobile-phone ban seems likely to continue.","zh":"手提電話禁令似乎很可能繼續。"},{"en":"To be likely to continue means to probably keep happening or remain in place.","zh":"be likely to continue 指很可能繼續發生或維持。"},{"en":"If student demand is strong, the evening class is likely to continue next term.","zh":"如果學生需求強烈，晚間課程下學期很可能繼續。"},{"en":"A safety rule is likely to continue when no strong evidence supports removing it.","zh":"當沒有強證據支持取消安全規則，它很可能繼續。"},{"en":"The phrase expresses probability, not certainty.","zh":"這個短語表達可能性，而不是確定性。"}],"source":"123 - Flight from reality.pdf","sourcePage":17},{"front":"in the absence of","meaning":"在缺乏……的情況下","examples":[{"en":"In the absence of firm evidence, the cautious policy will remain.","zh":"在缺乏確鑿證據的情況下，謹慎政策會保留。"},{"en":"In the absence of something means when that thing is not available or does not exist.","zh":"in the absence of something 指當某物不存在或不能取得時。"},{"en":"In the absence of a teacher, students should follow the written instructions.","zh":"在缺乏老師的情況下，學生應按照書面指示。"},{"en":"In the absence of clear proof, regulators may choose the safer option.","zh":"在缺乏明確證明的情況下，監管者可能選擇較安全方案。"},{"en":"The phrase explains what happens when something important is missing.","zh":"這個短語解釋當重要事物缺失時會發生甚麼。"}],"source":"123 - Flight from reality.pdf","sourcePage":17},{"front":"firm evidence","meaning":"確鑿證據","examples":[{"en":"There is no firm evidence of a vast airline conspiracy.","zh":"沒有確鑿證據顯示存在大型航空公司陰謀。"},{"en":"Firm evidence is strong, reliable proof that supports a claim.","zh":"firm evidence 指支持某聲稱的有力可靠證據。"},{"en":"A doctor needs firm evidence before diagnosing a serious disease.","zh":"醫生在診斷嚴重疾病前需要確鑿證據。"},{"en":"Without firm evidence, accusations can become unfair or misleading.","zh":"如果沒有確鑿證據，指控可能變得不公平或具誤導性。"},{"en":"The phrase contrasts solid proof with suspicion or rumour.","zh":"這個短語把堅實證明與懷疑或傳聞作對比。"}],"source":"123 - Flight from reality.pdf","sourcePage":17},{"front":"be engaged in","meaning":"參與；從事","examples":[{"en":"The passage rejects the idea that the airline industry is engaged in a conspiracy.","zh":"文章否定航空業參與陰謀的想法。"},{"en":"To be engaged in something means to be involved in or taking part in it.","zh":"be engaged in something 指參與或從事某事。"},{"en":"A student engaged in group work should listen and contribute ideas.","zh":"參與小組工作的學生應聆聽並貢獻想法。"},{"en":"If companies are engaged in unfair pricing, regulators may investigate them.","zh":"如果公司從事不公平定價，監管者可能調查它們。"},{"en":"The phrase is formal and describes involvement.","zh":"這個短語較正式，描述參與狀態。"}],"source":"123 - Flight from reality.pdf","sourcePage":17},{"front":"a vast conspiracy","meaning":"大型陰謀","examples":[{"en":"There is no evidence of a vast conspiracy to overcharge customers.","zh":"沒有證據顯示存在向顧客濫收費用的大型陰謀。"},{"en":"A vast conspiracy is a large secret plan by many people to do something dishonest or harmful.","zh":"vast conspiracy 指許多人秘密策劃做不誠實或有害事情的大型計劃。"},{"en":"Claiming a vast conspiracy without evidence can distract from real policy problems.","zh":"在沒有證據下聲稱有大型陰謀，可能令人忽視真正政策問題。"},{"en":"If many organisations secretly agreed to overcharge customers, that would be a vast conspiracy.","zh":"如果許多機構秘密同意向顧客濫收費用，那就是大型陰謀。"},{"en":"The phrase is dramatic and serious.","zh":"這個短語戲劇性且嚴重。"}],"source":"123 - Flight from reality.pdf","sourcePage":17},{"front":"overcharge its customers","meaning":"向顧客濫收費用","examples":[{"en":"The passage doubts that airlines are trying to overcharge their customers.","zh":"文章懷疑航空公司是否試圖向顧客濫收費用。"},{"en":"To overcharge customers means to make them pay more than is fair or correct.","zh":"overcharge customers 指要求顧客支付超出公平或正確水平的費用。"},{"en":"A shop may overcharge customers if it adds hidden fees at the checkout.","zh":"如果商店在付款時加入隱藏費用，它可能向顧客濫收費用。"},{"en":"If passengers think airlines overcharge them, trust in the industry may fall.","zh":"如果乘客認為航空公司濫收費用，他們對該行業的信任可能下降。"},{"en":"The phrase describes unfair pricing.","zh":"這個短語描述不公平定價。"}],"source":"123 - Flight from reality.pdf","sourcePage":17},{"front":"a delayed phone call","meaning":"延遲一通電話","examples":[{"en":"A delayed phone call seems a small price to pay for safety.","zh":"為了安全而延遲一通電話似乎是值得付出的小代價。"},{"en":"A delayed phone call is a call made later than planned or desired.","zh":"delayed phone call 指比計劃或希望時間更遲才打出的電話。"},{"en":"A passenger may accept a delayed phone call if it reduces possible flight risk.","zh":"如果延遲一通電話可以降低可能的飛行風險，乘客可能會接受。"},{"en":"Delaying one call is usually less serious than endangering a whole aircraft.","zh":"延遲一通電話通常比危及整架飛機小事得多。"},{"en":"The phrase treats waiting as a minor inconvenience.","zh":"這個短語把等待視為小小不便。"}],"source":"123 - Flight from reality.pdf","sourcePage":17},{"front":"a small price to pay","meaning":"值得付出的小代價","examples":[{"en":"A delayed phone call is a small price to pay for reducing risk.","zh":"為了降低風險，延遲一通電話是值得付出的小代價。"},{"en":"A small price to pay means a minor cost or inconvenience worth accepting for a bigger benefit.","zh":"small price to pay 指為了更大好處而值得接受的小成本或不便。"},{"en":"Wearing a helmet is a small price to pay for protecting your head.","zh":"為了保護頭部，戴頭盔是值得付出的小代價。"},{"en":"Turning off a phone may be a small price to pay for even a tiny safety improvement.","zh":"為了哪怕是微小的安全改善而關掉電話，可能是值得付出的小代價。"},{"en":"The phrase compares a small sacrifice with a larger benefit.","zh":"這個短語把小犧牲與較大好處作比較。"}],"source":"123 - Flight from reality.pdf","sourcePage":17},{"front":"the tiniest reduction in","meaning":"……的最微小降低","examples":[{"en":"Even the tiniest reduction in crash risk may justify the ban.","zh":"即使飛機失事風險的最微小降低，也可能令禁令合理。"},{"en":"The tiniest reduction in something means the smallest possible decrease.","zh":"the tiniest reduction in something 指某事最小可能的下降。"},{"en":"The tiniest reduction in infection risk can matter in a hospital.","zh":"在醫院中，感染風險的最微小降低也可能重要。"},{"en":"In aviation, even a tiny reduction in danger may be valuable because consequences are severe.","zh":"在航空中，即使危險的微小降低也可能有價值，因為後果嚴重。"},{"en":"The phrase stresses that even a very small improvement can matter.","zh":"這個短語強調即使非常小的改善也重要。"}],"source":"123 - Flight from reality.pdf","sourcePage":17},{"front":"chances of a plane crash","meaning":"飛機失事的機會","examples":[{"en":"The policy aims to reduce the chances of a plane crash.","zh":"該政策旨在降低飛機失事的機會。"},{"en":"Chances of a plane crash means the probability that an aircraft accident will happen.","zh":"chances of a plane crash 指飛機事故發生的可能性。"},{"en":"Safety checks reduce the chances of a plane crash before take-off.","zh":"安全檢查在起飛前降低飛機失事的機會。"},{"en":"Even if the chances of a plane crash are already low, airlines try to make them lower.","zh":"即使飛機失事的機會已經很低，航空公司仍嘗試令其更低。"},{"en":"The phrase describes risk probability, not a certain event.","zh":"這個短語描述風險概率，而不是確定事件。"}],"source":"123 - Flight from reality.pdf","sourcePage":17},{"front":"while that remains the case","meaning":"只要情況仍是這樣","examples":[{"en":"While laptops are still allowed, the policy seems illogical.","zh":"只要手提電腦仍被准許，該政策就顯得不合邏輯。"},{"en":"While that remains the case means as long as that situation continues to be true.","zh":"while that remains the case 指只要該情況繼續成立。"},{"en":"While that remains the case, students without internet at home will need printed materials.","zh":"只要情況仍是這樣，家中沒有互聯網的學生就需要印刷材料。"},{"en":"If laptops remain allowed but phones are banned, the rule may continue to look inconsistent.","zh":"如果手提電腦仍被准許但電話被禁止，規則可能繼續顯得不一致。"},{"en":"The phrase links a continuing situation with a continuing conclusion.","zh":"這個短語把持續情況與持續結論連起來。"}],"source":"123 - Flight from reality.pdf","sourcePage":17},{"front":"can hardly claim that","meaning":"很難聲稱","examples":[{"en":"Airlines can hardly claim that logic has prevailed.","zh":"航空公司很難聲稱邏輯已佔上風。"},{"en":"Can hardly claim that means cannot reasonably say that something is true.","zh":"can hardly claim that 指不能合理地說某事是真的。"},{"en":"A school can hardly claim that a rule is fair if only some students must follow it.","zh":"如果只有部分學生必須遵守規則，學校很難聲稱該規則公平。"},{"en":"If laptops may be riskier but remain allowed, airlines can hardly claim perfect logic.","zh":"如果手提電腦可能風險更高但仍被准許，航空公司很難聲稱邏輯完美。"},{"en":"The phrase is a polite but strong criticism.","zh":"這個短語是禮貌但強烈的批評。"}],"source":"123 - Flight from reality.pdf","sourcePage":18},{"front":"logic has prevailed","meaning":"邏輯已佔上風","examples":[{"en":"Airlines can hardly claim that logic has prevailed.","zh":"航空公司很難聲稱邏輯已佔上風。"},{"en":"Logic has prevailed means the final decision follows reason and evidence.","zh":"logic has prevailed 指最終決定符合理性和證據。"},{"en":"In a fair debate, logic has prevailed when the strongest argument wins.","zh":"在公平辯論中，當最強論點勝出，就是邏輯已佔上風。"},{"en":"If policy contradicts technical evidence, people may doubt that logic has prevailed.","zh":"如果政策與技術證據矛盾，人們可能懷疑邏輯是否已佔上風。"},{"en":"The phrase suggests reason has won over confusion, pressure, or habit.","zh":"這個短語暗示理性戰勝混亂、壓力或習慣。"}],"source":"123 - Flight from reality.pdf","sourcePage":18},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"To complete the summary below means to fill in missing words in the short text that follows.","zh":"complete the summary below 指填補下面短文中的空缺字詞。"},{"en":"In a reading test, students complete the summary below by locating exact words in the passage.","zh":"在閱讀測驗中，學生透過在篇章中定位準確字詞完成以下摘要。"},{"en":"Correct spelling matters because the answer is copied into a formal test box.","zh":"正確拼寫很重要，因為答案會抄到正式答題框中。"},{"en":"The phrase is an exam instruction, not a content phrase from the article.","zh":"這個短語是考試指示，而不是文章內容短語。"}],"source":"123 - Flight from reality.pdf","sourcePage":18},{"front":"no more than three words","meaning":"不多於三個字","examples":[{"en":"The answer should use no more than three words from the passage.","zh":"答案應使用文章中不多於三個字。"},{"en":"No more than three words means one, two, or three words, but not four.","zh":"no more than three words 指一個、兩個或三個詞，但不能四個。"},{"en":"If the answer is four words long, it breaks the instruction even if the idea is correct.","zh":"如果答案有四個詞，即使意思正確，也違反指示。"},{"en":"Students must count words carefully in IELTS reading questions.","zh":"學生在 IELTS 閱讀題中必須仔細數詞數。"},{"en":"The phrase sets a strict word limit.","zh":"這個短語設定嚴格字數限制。"}],"source":"123 - Flight from reality.pdf","sourcePage":18},{"front":"write your answers in","meaning":"把答案寫在……","examples":[{"en":"Students write their answers in the boxes on the answer sheet.","zh":"學生把答案寫在答題紙上的方格內。"},{"en":"To write your answers in a place means to put your final responses there.","zh":"write your answers in a place 指把最終答案填寫在某處。"},{"en":"Students may underline words in the passage but must write answers in the answer boxes.","zh":"學生可以在篇章中劃線，但必須把答案寫在答案框中。"},{"en":"If answers are written in the wrong place, they may not be marked correctly.","zh":"如果答案寫在錯誤位置，可能不能被正確評分。"},{"en":"The phrase tells test takers where to record responses.","zh":"這個短語告訴考生在哪裡記錄答案。"}],"source":"123 - Flight from reality.pdf","sourcePage":18},{"front":"potential risk","meaning":"潛在風險","examples":[{"en":"A potential risk certainly exists because aircraft systems are electronic.","zh":"由於飛機系統是電子化的，潛在風險確實存在。"},{"en":"A potential risk is a danger that could happen, even if it has not happened yet.","zh":"potential risk 指可能發生的危險，即使尚未真正發生。"},{"en":"Leaving a bag in a doorway is a potential risk because people may trip over it.","zh":"把袋放在門口是潛在風險，因為人們可能被絆倒。"},{"en":"Electronic aircraft systems create potential risk when outside signals might interfere with them.","zh":"當外來訊號可能干擾飛機電子系統，就會產生潛在風險。"},{"en":"The phrase describes possible danger, not confirmed harm.","zh":"這個短語描述可能危險，而不是已確認傷害。"}],"source":"123 - Flight from reality.pdf","sourcePage":18},{"front":"aircraft systems","meaning":"飛機系統","examples":[{"en":"Aircraft systems manage navigation, communications and control.","zh":"飛機系統管理導航、通訊和控制。"},{"en":"Aircraft systems are the mechanical and electronic systems that help a plane operate safely.","zh":"aircraft systems 指幫助飛機安全運作的機械和電子系統。"},{"en":"Aircraft systems include engines, navigation equipment, radios, and warning devices.","zh":"飛機系統包括引擎、導航設備、無線電和警報裝置。"},{"en":"If aircraft systems give wrong information, pilots may have to act quickly.","zh":"如果飛機系統提供錯誤資訊，機師可能必須迅速行動。"},{"en":"The phrase refers to the plane’s operating systems, not airport services.","zh":"這個短語指飛機的運作系統，而不是機場服務。"}],"source":"123 - Flight from reality.pdf","sourcePage":18},{"front":"manage navigation","meaning":"管理導航","examples":[{"en":"Modern aircraft systems manage navigation and communications.","zh":"現代飛機系統管理導航和通訊。"},{"en":"To manage navigation means to control or support the process of finding direction and position.","zh":"manage navigation 指控制或支援尋找方向和位置的過程。"},{"en":"Ships use maps, radar, and satellites to manage navigation at sea.","zh":"船隻使用地圖、雷達和衛星在海上管理導航。"},{"en":"If aircraft systems cannot manage navigation properly, pilots may lose accurate position information.","zh":"如果飛機系統不能妥善管理導航，機師可能失去準確位置資訊。"},{"en":"The phrase describes direction-finding control.","zh":"這個短語描述定位方向的控制。"}],"source":"123 - Flight from reality.pdf","sourcePage":18},{"front":"standards designed to ensure","meaning":"旨在確保……的標準","examples":[{"en":"Devices must meet standards designed to ensure safety.","zh":"裝置必須符合旨在確保安全的標準。"},{"en":"Standards designed to ensure something are rules created to make that result more certain.","zh":"standards designed to ensure something 指為令某結果更確定而制定的規則。"},{"en":"Schools use standards designed to ensure students receive fair assessment.","zh":"學校使用旨在確保學生獲公平評估的標準。"},{"en":"Aviation standards designed to ensure safety may limit how equipment can emit signals.","zh":"旨在確保安全的航空標準可能限制設備如何發出訊號。"},{"en":"The phrase links rules with their protective purpose.","zh":"這個短語把規則與其保護目的連起來。"}],"source":"123 - Flight from reality.pdf","sourcePage":18},{"front":"disrupt sensitive equipment","meaning":"干擾敏感設備","examples":[{"en":"Emissions from mobile phones could disrupt sensitive equipment.","zh":"來自手提電話的發射訊號可能干擾敏感設備。"},{"en":"To disrupt sensitive equipment means to disturb delicate systems so they may not work properly.","zh":"disrupt sensitive equipment 指干擾精密系統，使它們可能無法正常運作。"},{"en":"Strong magnets can disrupt sensitive equipment in a hospital scanning room.","zh":"強力磁石可以干擾醫院掃描室中的敏感設備。"},{"en":"If phone signals disrupt sensitive aircraft equipment, flight safety may be affected.","zh":"如果電話訊號干擾敏感飛機設備，飛行安全可能受影響。"},{"en":"The phrase describes interference with equipment that reacts easily.","zh":"這個短語描述對容易受影響設備的干擾。"}],"source":"123 - Flight from reality.pdf","sourcePage":18},{"front":"external antennae","meaning":"外部天線","examples":[{"en":"External antennae may be affected by emissions from inside the aircraft.","zh":"外部天線可能受飛機內部發射訊號影響。"},{"en":"External antennae are antennae fixed on the outside of a vehicle or building.","zh":"external antennae 指固定在車輛或建築物外部的天線。"},{"en":"Aircraft use external antennae to receive and send communication signals.","zh":"飛機使用外部天線接收和發送通訊訊號。"},{"en":"If signals from inside reach external antennae, they may interfere with normal communication.","zh":"如果內部訊號到達外部天線，它們可能干擾正常通訊。"},{"en":"The phrase contrasts outside signal equipment with devices inside the cabin.","zh":"這個短語把外部訊號設備與機艙內裝置作對比。"}],"source":"123 - Flight from reality.pdf","sourcePage":18},{"front":"interference with","meaning":"對……的干擾","examples":[{"en":"Interference with flight-control equipment has not been proved.","zh":"對飛行控制設備的干擾尚未被證明。"},{"en":"Interference with something means disturbance that affects how it works.","zh":"interference with something 指影響某物運作的干擾。"},{"en":"Interference with hospital machines can put patients at risk.","zh":"對醫院機器的干擾可能令病人承受風險。"},{"en":"If there is no proof of interference with flight controls, the strongest safety claim is harder to make.","zh":"如果沒有證據證明對飛行控制的干擾，最強安全聲稱就較難成立。"},{"en":"The phrase identifies the system being disturbed.","zh":"這個短語指出被干擾的系統。"}],"source":"123 - Flight from reality.pdf","sourcePage":19},{"front":"flight-control equipment","meaning":"飛行控制設備","examples":[{"en":"Interference with flight-control equipment has not been proved.","zh":"對飛行控制設備的干擾尚未被證明。"},{"en":"Flight-control equipment is equipment used to control the aircraft’s movement and direction.","zh":"flight-control equipment 指用來控制飛機移動和方向的設備。"},{"en":"Pilots rely on flight-control equipment during take-off, cruising, and landing.","zh":"機師在起飛、巡航和降落期間依靠飛行控制設備。"},{"en":"If flight-control equipment fails, the aircraft may become difficult to manage safely.","zh":"如果飛行控制設備失效，飛機可能變得難以安全操控。"},{"en":"The phrase refers to essential aircraft-control technology.","zh":"這個短語指必要的飛機控制技術。"}],"source":"123 - Flight from reality.pdf","sourcePage":19},{"front":"detect smoke","meaning":"探測煙霧","examples":[{"en":"Some devices detect smoke or indicate fuel levels.","zh":"一些裝置探測煙霧或顯示燃油水平。"},{"en":"To detect smoke means to sense smoke and warn people of possible fire.","zh":"detect smoke 指感應煙霧並警告人們可能有火警。"},{"en":"Smoke alarms detect smoke in homes so families can escape early.","zh":"煙霧警報器在家中探測煙霧，使家人能及早逃生。"},{"en":"If aircraft devices fail to detect smoke, a fire may not be noticed quickly enough.","zh":"如果飛機裝置未能探測煙霧，火警可能不能足夠快被察覺。"},{"en":"The phrase describes a safety warning function.","zh":"這個短語描述安全警報功能。"}],"source":"123 - Flight from reality.pdf","sourcePage":19},{"front":"indicate fuel levels","meaning":"顯示燃油水平","examples":[{"en":"Some devices indicate fuel levels for the flight crew.","zh":"一些裝置向機組人員顯示燃油水平。"},{"en":"To indicate fuel levels means to show how much fuel remains.","zh":"indicate fuel levels 指顯示剩餘燃油量。"},{"en":"A car dashboard indicates fuel levels so drivers know when to refill.","zh":"汽車儀表板顯示燃油水平，讓司機知道何時入油。"},{"en":"If fuel levels are shown incorrectly, the crew may make unsafe decisions.","zh":"如果燃油水平顯示錯誤，機組人員可能作出不安全決定。"},{"en":"The phrase describes giving important measurement information.","zh":"這個短語描述提供重要量度資訊。"}],"source":"123 - Flight from reality.pdf","sourcePage":19},{"front":"match each opinion or action with","meaning":"把每項意見或行動與……配對","examples":[{"en":"Students match each opinion or action with the correct person or organisation.","zh":"學生把每項意見或行動與正確人物或機構配對。"},{"en":"To match each opinion or action with someone means to connect it to the right source.","zh":"match each opinion or action with someone 指把它連接到正確來源。"},{"en":"In a reading test, students may match each claim with the researcher who said it.","zh":"在閱讀測驗中，學生可能把每項聲稱與提出它的研究人員配對。"},{"en":"Matching opinions requires careful reading because wording may be paraphrased.","zh":"配對意見需要仔細閱讀，因為措辭可能被改寫。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"123 - Flight from reality.pdf","sourcePage":19},{"front":"the correct person or organisation","meaning":"正確人物或機構","examples":[{"en":"The task asks students to choose the correct person or organisation.","zh":"任務要求學生選擇正確人物或機構。"},{"en":"The correct person or organisation is the source that matches the information in the passage.","zh":"correct person or organisation 指與篇章資料相符的來源。"},{"en":"A student should check names carefully before choosing the correct person or organisation.","zh":"學生在選擇正確人物或機構前應仔細核對姓名。"},{"en":"Choosing the wrong source can make an answer incorrect even if the idea is understood.","zh":"即使理解意思，選錯來源也會令答案錯誤。"},{"en":"The phrase focuses on accurate matching.","zh":"這個短語重點是準確配對。"}],"source":"123 - Flight from reality.pdf","sourcePage":19},{"front":"specific phases of flight","meaning":"飛行的特定階段","examples":[{"en":"Take-off and landing are specific phases of flight.","zh":"起飛和降落是飛行的特定階段。"},{"en":"Specific phases of flight are particular stages in a plane journey.","zh":"specific phases of flight 指飛機旅程中的特定階段。"},{"en":"Boarding, take-off, cruising, descent, and landing are phases of flight.","zh":"登機、起飛、巡航、下降和降落都是飛行階段。"},{"en":"Rules may change during specific phases of flight because risks and tasks change.","zh":"規則可能在飛行的特定階段改變，因為風險和任務會改變。"},{"en":"The phrase points to exact flight stages, not the whole journey.","zh":"這個短語指確切飛行階段，而不是整個旅程。"}],"source":"123 - Flight from reality.pdf","sourcePage":19},{"front":"pose little risk to","meaning":"對……構成很小風險","examples":[{"en":"Some experts believe mobile phones pose little risk to navigation systems.","zh":"一些專家認為手提電話對導航系統構成很小風險。"},{"en":"To pose little risk to something means to create only a small possible danger to it.","zh":"pose little risk to something 指對某物只造成很小可能危險。"},{"en":"A quiet electric fan may pose little risk to office computers.","zh":"安靜電風扇可能對辦公室電腦構成很小風險。"},{"en":"If phones pose little risk to navigation, a total ban may seem harder to explain.","zh":"如果電話對導航構成很小風險，全面禁令可能較難解釋。"},{"en":"The phrase does not mean zero risk; it means low risk.","zh":"這個短語不是指零風險，而是低風險。"}],"source":"123 - Flight from reality.pdf","sourcePage":19},{"front":"laptops pose less risk than","meaning":"手提電腦比……風險較低","examples":[{"en":"Some engineers argue that laptops pose less risk than mobile phones.","zh":"一些工程師認為手提電腦比手提電話風險較低。"},{"en":"Laptops pose less risk than something means laptops create a smaller danger in comparison.","zh":"laptops pose less risk than something 指手提電腦相比某物造成較小危險。"},{"en":"A tablet may pose less risk than a laptop if it emits weaker signals.","zh":"如果平板電腦發出的訊號較弱，它可能比手提電腦風險較低。"},{"en":"If laptops pose less risk than phones, allowing them while banning phones may seem logical.","zh":"如果手提電腦比電話風險較低，准許前者而禁止後者可能顯得合理。"},{"en":"The phrase compares relative danger between devices.","zh":"這個短語比較裝置之間的相對危險。"}],"source":"123 - Flight from reality.pdf","sourcePage":19},{"front":"may affect older equipment","meaning":"可能影響較舊設備","examples":[{"en":"Mobile-phone signals may affect older equipment on board.","zh":"手提電話訊號可能影響機上的較舊設備。"},{"en":"May affect older equipment means could influence or disturb equipment built to earlier standards.","zh":"may affect older equipment 指可能影響或干擾按較早標準製造的設備。"},{"en":"New software may affect older equipment if the hardware cannot support it.","zh":"如果硬件不能支援，新軟件可能影響較舊設備。"},{"en":"If signals affect older equipment, older aircraft may need extra caution.","zh":"如果訊號影響較舊設備，較舊飛機可能需要額外謹慎。"},{"en":"The phrase suggests possible impact on outdated systems.","zh":"這個短語暗示對過時系統的可能影響。"}],"source":"123 - Flight from reality.pdf","sourcePage":19},{"front":"agree with the information given","meaning":"與文中資料一致","examples":[{"en":"Students decide whether statements agree with the information given in the passage.","zh":"學生判斷陳述是否與篇章中給出的資料一致。"},{"en":"To agree with the information given means to match what the passage says.","zh":"agree with the information given 指與篇章所說內容相符。"},{"en":"If the passage says phones are banned and the statement says the same, it agrees with the information given.","zh":"如果篇章說電話被禁止，而陳述也這樣說，它就與文中資料一致。"},{"en":"Students should not use outside knowledge when checking whether a statement agrees with the passage.","zh":"學生判斷陳述是否與篇章一致時，不應使用外部知識。"},{"en":"The phrase is common in True, False, Not Given questions.","zh":"這個短語常見於 True, False, Not Given 題目。"}],"source":"123 - Flight from reality.pdf","sourcePage":19},{"front":"contradict the information","meaning":"與文中資料相矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與篇章資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the passage says.","zh":"contradict the information 指說出與篇章相反的內容。"},{"en":"If the text says laptops are allowed but the statement says they are banned, it contradicts the information.","zh":"如果文本說手提電腦被准許，但陳述說它們被禁止，就是與資料相矛盾。"},{"en":"Students must find a direct conflict before choosing FALSE.","zh":"學生必須找到直接衝突，才選 FALSE。"},{"en":"The phrase means conflict with the text, not simply missing information.","zh":"這個短語指與文本衝突，而不是單純沒有資料。"}],"source":"123 - Flight from reality.pdf","sourcePage":20},{"front":"there is no information on this","meaning":"沒有相關資料","examples":[{"en":"Students choose NOT GIVEN when there is no information on this.","zh":"當文中沒有相關資料時，學生選擇 NOT GIVEN。"},{"en":"There is no information on this means the passage does not say whether the statement is true or false.","zh":"there is no information on this 指篇章沒有說明該陳述是真還是假。"},{"en":"If the passage mentions phone bans but not ticket prices, there is no information on ticket prices.","zh":"如果篇章提到電話禁令但沒有提到票價，就沒有票價方面的相關資料。"},{"en":"Students should choose NOT GIVEN when the text gives no evidence either way.","zh":"當文本沒有提供任何方向的證據，學生應選 NOT GIVEN。"},{"en":"The phrase warns learners not to guess beyond the passage.","zh":"這個短語提醒學習者不要超出篇章猜測。"}],"source":"123 - Flight from reality.pdf","sourcePage":20},{"front":"almost all scientists agree that","meaning":"幾乎所有科學家都同意","examples":[{"en":"The statement claims that almost all scientists agree about emissions.","zh":"該陳述聲稱幾乎所有科學家都同意發射訊號的看法。"},{"en":"Almost all scientists agree that means nearly every scientist accepts a certain idea.","zh":"almost all scientists agree that 指幾乎每位科學家都接受某個想法。"},{"en":"Almost all doctors agree that smoking harms health.","zh":"幾乎所有醫生都同意吸煙損害健康。"},{"en":"A claim that almost all scientists agree needs strong evidence from the text.","zh":"聲稱幾乎所有科學家都同意，需要文本中的強力證據。"},{"en":"The phrase expresses a very broad consensus.","zh":"這個短語表達非常廣泛的共識。"}],"source":"123 - Flight from reality.pdf","sourcePage":20},{"front":"produce stronger emissions than","meaning":"產生比……更強的發射訊號","examples":[{"en":"The option compares whether mobile phones produce stronger emissions than computers.","zh":"選項比較手提電話是否產生比電腦更強的發射訊號。"},{"en":"To produce stronger emissions than something means to send out more powerful signals in comparison.","zh":"produce stronger emissions than something 指相比某物發出更強力的訊號。"},{"en":"A radio tower may produce stronger emissions than a home Wi-Fi router.","zh":"無線電塔可能產生比家用 Wi-Fi 路由器更強的發射訊號。"},{"en":"If laptops produce stronger emissions than phones, common assumptions may be wrong.","zh":"如果手提電腦產生比電話更強的發射訊號，常識假設可能是錯的。"},{"en":"The phrase compares signal strength between two devices.","zh":"這個短語比較兩種裝置之間的訊號強度。"}],"source":"123 - Flight from reality.pdf","sourcePage":20},{"front":"radio emissions","meaning":"無線電發射訊號","examples":[{"en":"Some people believe that radio emissions can disrupt equipment.","zh":"有些人相信無線電發射訊號可以干擾設備。"},{"en":"Radio emissions are wireless signals sent out as radio waves.","zh":"radio emissions 指以無線電波形式發出的無線訊號。"},{"en":"Phones, radios, and transmitters can all create radio emissions.","zh":"電話、收音機和發射器都可以產生無線電發射訊號。"},{"en":"Radio emissions near sensitive equipment may cause interference if they are strong enough.","zh":"如果足夠強，敏感設備附近的無線電發射訊號可能造成干擾。"},{"en":"The phrase is technical and often appears in communication safety discussions.","zh":"這個短語較技術性，常出現在通訊安全討論中。"}],"source":"123 - Flight from reality.pdf","sourcePage":20},{"front":"signal-interference detector","meaning":"訊號干擾探測器","examples":[{"en":"A signal-interference detector could warn staff about dangerous emissions.","zh":"訊號干擾探測器可以警告職員有危險發射訊號。"},{"en":"A signal-interference detector is a device that finds electronic signals that may disturb other systems.","zh":"signal-interference detector 指尋找可能干擾其他系統的電子訊號的裝置。"},{"en":"A factory may use a signal-interference detector to protect sensitive machines.","zh":"工廠可能使用訊號干擾探測器保護敏感機器。"},{"en":"If aircraft had signal-interference detectors, crews could identify risky passenger devices faster.","zh":"如果飛機有訊號干擾探測器，機組人員可以更快找出高風險乘客裝置。"},{"en":"The phrase refers to a warning tool for electronic interference.","zh":"這個短語指電子干擾警報工具。"}],"source":"123 - Flight from reality.pdf","sourcePage":20},{"front":"regulatory priority","meaning":"監管優先事項","examples":[{"en":"The detector has not become a regulatory priority.","zh":"該探測器尚未成為監管優先事項。"},{"en":"A regulatory priority is an issue that rule-making bodies treat as especially important.","zh":"regulatory priority 指制定規則的機構視為特別重要的議題。"},{"en":"Road safety may become a regulatory priority after several serious accidents.","zh":"在幾宗嚴重意外後，道路安全可能成為監管優先事項。"},{"en":"If detectors are not a regulatory priority, agencies may not require airlines to install them.","zh":"如果探測器不是監管優先事項，機構可能不要求航空公司安裝它們。"},{"en":"The phrase refers to what regulators choose to focus on first.","zh":"這個短語指監管者選擇優先關注的事情。"}],"source":"123 - Flight from reality.pdf","sourcePage":20},{"front":"economic opportunity","meaning":"經濟機會","examples":[{"en":"The detector has not become a major economic opportunity.","zh":"該探測器尚未成為重大經濟機會。"},{"en":"An economic opportunity is a chance to make money, create business, or grow a market.","zh":"economic opportunity 指賺錢、創造生意或擴大市場的機會。"},{"en":"A new train station can be an economic opportunity for nearby shops.","zh":"新火車站可以成為附近商店的經濟機會。"},{"en":"If airlines and manufacturers see no economic opportunity, they may not develop a detector quickly.","zh":"如果航空公司和製造商看不到經濟機會，它們可能不會快速開發探測器。"},{"en":"The phrase focuses on financial benefit.","zh":"這個短語重點是財政利益。"}],"source":"123 - Flight from reality.pdf","sourcePage":20},{"front":"initiate an open debate","meaning":"發起公開辯論","examples":[{"en":"The option says the FAA initiated an open debate with another agency.","zh":"該選項說美國聯邦航空管理局與另一機構發起公開辯論。"},{"en":"To initiate an open debate means to start a public or transparent discussion.","zh":"initiate an open debate 指開始一場公開或透明的討論。"},{"en":"A school may initiate an open debate before changing its uniform policy.","zh":"學校可能在改變校服政策前發起公開辯論。"},{"en":"An open debate can help people compare evidence, costs, and safety concerns.","zh":"公開辯論可以幫助人們比較證據、成本和安全憂慮。"},{"en":"The phrase describes beginning a visible discussion, not making a private decision.","zh":"這個短語描述開始可見討論，而不是作出私人決定。"}],"source":"123 - Flight from reality.pdf","sourcePage":20},{"front":"Federal Aviation Administration","meaning":"美國聯邦航空管理局","examples":[{"en":"The Federal Aviation Administration regulates aviation safety in the US.","zh":"美國聯邦航空管理局監管美國航空安全。"},{"en":"The Federal Aviation Administration is the US government agency responsible for civil aviation safety.","zh":"Federal Aviation Administration 指負責民用航空安全的美國政府機構。"},{"en":"The FAA sets rules for pilots, aircraft, airports, and flight operations.","zh":"FAA 為機師、飛機、機場和飛行運作制定規則。"},{"en":"When aircraft technology changes, the Federal Aviation Administration may review safety standards.","zh":"當飛機科技改變，美國聯邦航空管理局可能檢討安全標準。"},{"en":"The phrase is a formal agency name and is often shortened to FAA.","zh":"這個短語是正式機構名稱，常縮寫為 FAA。"}],"source":"123 - Flight from reality.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 124":[{"front":"tools for ancient writing","meaning":"古代書寫工具","examples":[{"en":"The passage describes tools for ancient writing.","zh":"文章描述古代書寫工具。"},{"en":"Tools for ancient writing are objects people used long ago to record words, symbols, or pictures.","zh":"古代書寫工具是古人用來記錄文字、符號或圖畫的物件。"},{"en":"Clay tablets, reed pens, ink, and quill pens were all tools for ancient writing.","zh":"黏土板、蘆葦筆、墨水和羽毛筆都是古代書寫工具。"},{"en":"If tools for ancient writing improved, people could write faster and keep records more easily.","zh":"如果古代書寫工具有所改良，人們就能更快書寫並更容易保存記錄。"},{"en":"This phrase focuses on the practical objects used before modern pens and paper.","zh":"這個短語重點在於現代紙筆出現前所使用的實用物件。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":1},{"front":"with time","meaning":"隨着時間過去","examples":[{"en":"With time, record-keepers developed systematised symbols from their drawings.","zh":"隨着時間過去，記錄員從圖畫發展出系統化符號。"},{"en":"With time means gradually as days, years, or centuries pass.","zh":"with time 指隨着日子、年份或世紀過去而逐漸發生。"},{"en":"With time, a new student becomes more confident speaking English in class.","zh":"隨着時間過去，新學生在課堂上說英語會變得更有信心。"},{"en":"With time, repeated drawings became simpler symbols that were easier to use.","zh":"隨着時間過去，反覆使用的圖畫變成較簡單、較易使用的符號。"},{"en":"The phrase shows slow development rather than sudden change.","zh":"這個短語顯示緩慢發展，而不是突然改變。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":1},{"front":"record-keepers","meaning":"記錄員；記錄保存者","examples":[{"en":"Record-keepers developed symbols from their drawings.","zh":"記錄員從圖畫發展出符號。"},{"en":"Record-keepers are people who write down and preserve information, accounts, or events.","zh":"record-keepers 是負責寫下並保存資料、帳目或事件的人。"},{"en":"A school record-keeper may store attendance, exam results, and student files.","zh":"學校記錄員可能保存出席紀錄、考試成績和學生檔案。"},{"en":"If record-keepers use clear symbols, later readers can understand the information more easily.","zh":"如果記錄員使用清楚符號，後來的讀者就能更容易理解資料。"},{"en":"The phrase refers to people responsible for keeping written evidence.","zh":"這個短語指負責保存書面證據的人。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":1},{"front":"systematised symbols","meaning":"系統化符號","examples":[{"en":"With time, record-keepers developed systematised symbols from their drawings.","zh":"隨着時間過去，記錄員從圖畫發展出系統化符號。"},{"en":"Systematised symbols are signs organised into a clear and regular system.","zh":"systematised symbols 是被組織成清楚而有規律系統的符號。"},{"en":"Traffic signs are systematised symbols because drivers learn what each shape and colour means.","zh":"交通標誌是系統化符號，因為司機會學習每種形狀和顏色的意思。"},{"en":"When drawings become systematised symbols, people can record information more quickly.","zh":"當圖畫變成系統化符號，人們就能更快記錄資料。"},{"en":"The phrase suggests order, consistency, and shared meaning.","zh":"這個短語暗示秩序、一致性和共同理解的意思。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":1},{"front":"represent words and sentences","meaning":"代表字詞和句子","examples":[{"en":"These symbols represented words and sentences.","zh":"這些符號代表字詞和句子。"},{"en":"To represent words and sentences means to stand for spoken language in written form.","zh":"represent words and sentences 指以書面形式表示口語。"},{"en":"Letters represent sounds, and together they can represent words and sentences.","zh":"字母代表聲音，合起來可以代表字詞和句子。"},{"en":"If symbols represent words and sentences, people can record more than simple objects or numbers.","zh":"如果符號能代表字詞和句子，人們就能記錄不只是物件或數字的內容。"},{"en":"The phrase shows how writing moves from pictures to language.","zh":"這個短語顯示書寫如何從圖畫走向語言。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":1},{"front":"universally understood","meaning":"普遍被理解","examples":[{"en":"The symbols were easier to draw and universally understood.","zh":"這些符號較容易繪畫，並且普遍被理解。"},{"en":"Universally understood means understood by almost everyone in a group or society.","zh":"universally understood 指幾乎被某個群體或社會中的所有人理解。"},{"en":"A red traffic light is universally understood as a sign to stop in many places.","zh":"在許多地方，紅燈普遍被理解為停下的標誌。"},{"en":"If writing symbols are universally understood, merchants and officials can share records more reliably.","zh":"如果書寫符號普遍被理解，商人和官員就能更可靠地分享記錄。"},{"en":"The phrase stresses common understanding, not personal interpretation.","zh":"這個短語強調共同理解，而不是個人解讀。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":1},{"front":"the discovery of clay","meaning":"黏土的發現","examples":[{"en":"The discovery of clay made portable records possible.","zh":"黏土的發現使可攜式記錄成為可能。"},{"en":"The discovery of clay means people found that clay could be shaped and used for writing or storage.","zh":"the discovery of clay 指人們發現黏土可以被塑形並用於書寫或儲存。"},{"en":"The discovery of clay helped ancient communities make pots, tablets, and building materials.","zh":"黏土的發現幫助古代社群製作陶器、泥板和建材。"},{"en":"If clay could hold marks, records no longer had to stay on cave walls.","zh":"如果黏土可以留下痕跡，記錄就不再必須留在洞穴牆壁上。"},{"en":"The phrase points to a material discovery that changed how people recorded information.","zh":"這個短語指出一項改變人類記錄資料方式的材料發現。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":1},{"front":"portable records","meaning":"可攜式記錄","examples":[{"en":"The discovery of clay made portable records possible.","zh":"黏土的發現使可攜式記錄成為可能。"},{"en":"Portable records are records that can be carried from one place to another.","zh":"portable records 是可以從一個地方帶到另一個地方的記錄。"},{"en":"A notebook is a portable record because students can take it home after class.","zh":"筆記本是可攜式記錄，因為學生可以下課後把它帶回家。"},{"en":"Portable records helped merchants bring trade information with them during journeys.","zh":"可攜式記錄幫助商人在旅途中攜帶交易資料。"},{"en":"The phrase contrasts movable records with records fixed on walls or stones.","zh":"這個短語把可移動記錄與固定在牆上或石上的記錄作對比。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":1},{"front":"carry a cave wall around","meaning":"隨身帶着洞穴牆壁","examples":[{"en":"You cannot carry a cave wall around with you.","zh":"你不能隨身帶着洞穴牆壁。"},{"en":"To carry a cave wall around means to take an impossible fixed surface with you from place to place.","zh":"carry a cave wall around 指把一個不可能移動的固定表面從一地帶到另一地。"},{"en":"A teacher may joke that students need notebooks because they cannot carry a classroom wall around.","zh":"老師可能開玩笑說學生需要筆記本，因為他們不能隨身帶着課室牆壁。"},{"en":"Since people could not carry a cave wall around, clay tablets made records more useful.","zh":"由於人們不能隨身帶着洞穴牆壁，黏土板令記錄變得更有用。"},{"en":"The phrase humorously shows why portable writing materials were important.","zh":"這個短語以幽默方式顯示可攜式書寫材料為何重要。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":1},{"front":"early merchants","meaning":"早期商人","examples":[{"en":"Early merchants used clay tokens to record trade.","zh":"早期商人使用黏土符記記錄交易。"},{"en":"Early merchants were traders from ancient times who bought, sold, or transported goods.","zh":"early merchants 是古代買賣或運送貨物的商人。"},{"en":"Early merchants needed records because they handled grain, animals, cloth, and other goods.","zh":"早期商人需要記錄，因為他們處理穀物、牲畜、布匹和其他貨物。"},{"en":"If early merchants travelled between towns, portable records helped them remember deals.","zh":"如果早期商人在城鎮之間旅行，可攜式記錄可以幫助他們記住交易。"},{"en":"The phrase refers to business people before modern shops, banks, and receipts.","zh":"這個短語指現代商店、銀行和收據出現前的商業人士。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":1},{"front":"clay tokens","meaning":"黏土符記","examples":[{"en":"Early merchants used clay tokens with pictographs.","zh":"早期商人使用帶有圖畫符號的黏土符記。"},{"en":"Clay tokens are small pieces of clay used to represent goods, quantities, or records.","zh":"clay tokens 是用來代表貨物、數量或記錄的小塊黏土。"},{"en":"A clay token might stand for one jar of oil or one bag of grain.","zh":"一個黏土符記可能代表一罐油或一袋穀物。"},{"en":"If clay tokens were easy to carry, merchants could record trade without writing long sentences.","zh":"如果黏土符記容易攜帶，商人就能不用寫長句也記錄交易。"},{"en":"The phrase describes a simple ancient recording tool.","zh":"這個短語描述一種簡單的古代記錄工具。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":1},{"front":"pictographs","meaning":"圖畫符號；圖畫文字","examples":[{"en":"Clay tokens with pictographs were used to record quantities.","zh":"帶有圖畫符號的黏土符記被用來記錄數量。"},{"en":"Pictographs are picture-like symbols that represent objects, ideas, or information.","zh":"pictographs 是像圖畫的符號，用來代表物件、想法或資料。"},{"en":"A drawing of a fish can be a pictograph if it is used to mean fish in a record.","zh":"如果魚的圖畫在記錄中用來表示魚，它就可以是圖畫符號。"},{"en":"If pictographs are repeated many times, they may become simpler and more abstract.","zh":"如果圖畫符號被反覆使用很多次，它們可能變得更簡單和更抽象。"},{"en":"The phrase refers to early writing based on pictures rather than letters.","zh":"這個短語指以圖畫而不是字母為基礎的早期文字。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":2},{"front":"record the quantities of","meaning":"記錄……的數量","examples":[{"en":"Merchants used clay tokens to record the quantities of materials.","zh":"商人用黏土符記記錄材料的數量。"},{"en":"To record the quantities of something means to write down or mark how much of it there is.","zh":"record the quantities of 某物，意思是寫下或標記某物有多少。"},{"en":"A shopkeeper records the quantities of rice and oil left in the storeroom.","zh":"店主記錄儲物室剩下多少米和油。"},{"en":"If merchants record the quantities of goods accurately, fewer trade disputes happen.","zh":"如果商人準確記錄貨物數量，交易爭議就會減少。"},{"en":"The phrase is useful for business, inventory, and shipment records.","zh":"這個短語適用於商業、庫存和運輸記錄。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":2},{"front":"materials traded or shipped","meaning":"被交易或運送的材料","examples":[{"en":"The tokens recorded the quantities of materials traded or shipped.","zh":"這些符記記錄被交易或運送的材料數量。"},{"en":"Materials traded or shipped are goods that are bought, sold, or transported to another place.","zh":"materials traded or shipped 是被買賣或運送到另一地方的貨物。"},{"en":"A warehouse records materials traded or shipped so workers know what has left the building.","zh":"倉庫會記錄被交易或運送的材料，讓員工知道甚麼已離開大樓。"},{"en":"If materials traded or shipped are not recorded, customers may receive the wrong amount.","zh":"如果被交易或運送的材料沒有被記錄，顧客可能收到錯誤數量。"},{"en":"The phrase connects trade records with the movement of goods.","zh":"這個短語把交易記錄與貨物流動連繫起來。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":2},{"front":"date back to","meaning":"追溯至","examples":[{"en":"These tokens date back to about 8,500 B.C.","zh":"這些符記可追溯至約公元前8500年。"},{"en":"To date back to a time means to have existed since that time.","zh":"date back to 某時期，意思是自該時期已經存在。"},{"en":"This temple dates back to the twelfth century.","zh":"這座寺廟可追溯至十二世紀。"},{"en":"If a tool dates back thousands of years, it shows that people needed it very early.","zh":"如果一種工具可追溯至數千年前，這顯示人們很早已有這種需要。"},{"en":"The phrase is commonly used for history, buildings, objects, and traditions.","zh":"這個短語常用於歷史、建築、物件和傳統。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":2},{"front":"the high volume of","meaning":"大量的……","examples":[{"en":"The high volume of record keeping changed pictographs.","zh":"大量記錄工作改變了圖畫符號。"},{"en":"The high volume of something means a large amount or frequent occurrence of it.","zh":"the high volume of 某事，指其數量很多或發生頻密。"},{"en":"The high volume of messages made it hard for the office to reply quickly.","zh":"大量訊息令辦公室難以迅速回覆。"},{"en":"If there is a high volume of records, people need faster and simpler symbols.","zh":"如果有大量記錄，人們就需要更快、更簡單的符號。"},{"en":"The phrase explains pressure caused by large quantities.","zh":"這個短語解釋由大量數量造成的壓力。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":2},{"front":"repetition inherent in","meaning":"……中固有的重複性","examples":[{"en":"Repetition inherent in record keeping caused pictographs to evolve.","zh":"記錄工作中固有的重複性促使圖畫符號演變。"},{"en":"Repetition inherent in something means repeated action that naturally belongs to that activity.","zh":"repetition inherent in 某活動，指自然存在於該活動中的重複動作。"},{"en":"The repetition inherent in piano practice helps students build muscle memory.","zh":"鋼琴練習中固有的重複性幫助學生建立肌肉記憶。"},{"en":"If record keeping requires the same marks again and again, symbols tend to become simpler.","zh":"如果記錄工作需要一次又一次使用相同標記，符號往往會變得更簡單。"},{"en":"The phrase points to a feature built into an activity, not added from outside.","zh":"這個短語指出某活動本身內在的特點，而不是外加因素。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":2},{"front":"record keeping","meaning":"記錄保存；記錄工作","examples":[{"en":"The repetition inherent in record keeping changed early symbols.","zh":"記錄工作中固有的重複性改變了早期符號。"},{"en":"Record keeping is the activity of writing down and preserving information for later use.","zh":"record keeping 是寫下並保存資料以供日後使用的活動。"},{"en":"Good record keeping helps a doctor know what medicine a patient received before.","zh":"良好的記錄保存幫助醫生知道病人以前接受過甚麼藥物。"},{"en":"If record keeping is poor, businesses may lose money or make wrong decisions.","zh":"如果記錄工作差，企業可能損失金錢或作出錯誤決定。"},{"en":"The phrase focuses on organised storage of information.","zh":"這個短語重點在於有組織地保存資料。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":2},{"front":"slowly lose detail","meaning":"慢慢失去細節","examples":[{"en":"Pictographs evolved and slowly lost their picture detail.","zh":"圖畫符號逐漸演變，慢慢失去圖像細節。"},{"en":"To slowly lose detail means to become less detailed little by little over time.","zh":"slowly lose detail 指隨時間一點一點變得較少細節。"},{"en":"A copied drawing may slowly lose detail if each student redraws it quickly.","zh":"如果每位學生都快速重畫，一幅被複製的圖可能慢慢失去細節。"},{"en":"If symbols are used thousands of times, they may slowly lose detail and become easier to write.","zh":"如果符號被使用數千次，它們可能慢慢失去細節並變得更容易書寫。"},{"en":"The phrase describes gradual simplification.","zh":"這個短語描述逐漸簡化。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":2},{"front":"picture detail","meaning":"圖像細節","examples":[{"en":"Pictographs gradually lost their picture detail.","zh":"圖畫符號逐漸失去圖像細節。"},{"en":"Picture detail means the small visual parts that make a drawing look realistic or recognisable.","zh":"picture detail 指令圖畫看起來真實或可辨認的小型視覺部分。"},{"en":"A quick sketch has less picture detail than a careful painting.","zh":"快速草圖比仔細畫作有較少圖像細節。"},{"en":"If writing symbols need speed, too much picture detail becomes inconvenient.","zh":"如果書寫符號需要速度，太多圖像細節就會變得不方便。"},{"en":"The phrase refers to visual detail, not written explanation.","zh":"這個短語指視覺細節，而不是文字解釋。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":2},{"front":"abstract figures","meaning":"抽象圖形","examples":[{"en":"Pictographs became abstract figures representing sounds.","zh":"圖畫符號變成代表聲音的抽象圖形。"},{"en":"Abstract figures are shapes or marks that do not look like real objects but carry meaning.","zh":"abstract figures 是不像真實物件但有意思的形狀或標記。"},{"en":"A traffic arrow is an abstract figure because it does not show a real road but gives direction.","zh":"交通箭咀是一種抽象圖形，因為它不是畫出真實道路，而是給出方向。"},{"en":"When pictographs became abstract figures, writing could represent sounds more easily.","zh":"當圖畫符號變成抽象圖形，書寫就能更容易代表聲音。"},{"en":"The phrase contrasts symbolic shapes with detailed pictures.","zh":"這個短語把象徵性形狀與詳細圖畫作對比。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":2},{"front":"represent sounds","meaning":"代表聲音","examples":[{"en":"Abstract figures represented sounds in spoken communication.","zh":"抽象圖形代表口語溝通中的聲音。"},{"en":"To represent sounds means to stand for spoken noises or speech units in writing.","zh":"represent sounds 指在書寫中代表說話聲音或語音單位。"},{"en":"Letters represent sounds, which is why children can sound out new words.","zh":"字母代表聲音，所以孩子可以拼讀新字。"},{"en":"If symbols represent sounds, people can write names and sentences more flexibly.","zh":"如果符號代表聲音，人們就能更靈活地寫名字和句子。"},{"en":"The phrase explains a major step from picture writing to alphabetic writing.","zh":"這個短語解釋從圖畫文字走向字母文字的重要一步。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":2},{"front":"spoken communication","meaning":"口語溝通","examples":[{"en":"Early abstract figures represented sounds in spoken communication.","zh":"早期抽象圖形代表口語溝通中的聲音。"},{"en":"Spoken communication is communication through speech rather than writing.","zh":"spoken communication 是透過說話而非書寫進行的溝通。"},{"en":"A phone call is spoken communication because people exchange words aloud.","zh":"電話通話是口語溝通，因為人們以聲音交換字句。"},{"en":"If writing represents spoken communication, it can record what people say.","zh":"如果書寫代表口語溝通，它就能記錄人們所說的話。"},{"en":"The phrase contrasts speech with written symbols.","zh":"這個短語把說話與書面符號作對比。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":3},{"front":"replace pictographs","meaning":"取代圖畫文字","examples":[{"en":"The alphabet replaced pictographs between 1700 and 1500 B.C.","zh":"字母在公元前1700至1500年間取代圖畫文字。"},{"en":"To replace pictographs means to take the place of picture-based writing symbols.","zh":"replace pictographs 指取代以圖畫為基礎的書寫符號。"},{"en":"Typed messages replaced many handwritten notes in modern offices.","zh":"在現代辦公室中，打字訊息取代了許多手寫便條。"},{"en":"If alphabets replaced pictographs, writing became less dependent on drawing pictures.","zh":"如果字母取代圖畫文字，書寫就變得較少依賴畫圖。"},{"en":"The phrase shows one writing system taking over from another.","zh":"這個短語顯示一種書寫系統取代另一種。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":3},{"front":"the Sinaitic world","meaning":"西奈地區；西奈文明圈","examples":[{"en":"The alphabet replaced pictographs in the Sinaitic world.","zh":"字母在西奈地區取代了圖畫文字。"},{"en":"The Sinaitic world refers to the ancient cultural region connected with Sinai and nearby areas.","zh":"the Sinaitic world 指與西奈及附近地區相關的古代文化區域。"},{"en":"Writing systems in the Sinaitic world influenced later alphabets.","zh":"西奈文明圈中的書寫系統影響了後來的字母。"},{"en":"If a symbol system spread through the Sinaitic world, it could affect trade and communication.","zh":"如果一套符號系統在西奈地區傳播，它可能影響貿易和溝通。"},{"en":"The phrase identifies a historical region, not a modern country.","zh":"這個短語指出一個歷史區域，而不是現代國家。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":3},{"front":"the current Hebrew alphabet","meaning":"現代希伯來字母","examples":[{"en":"The current Hebrew alphabet became popular around 600 B.C.","zh":"現代希伯來字母大約在公元前600年變得流行。"},{"en":"The current Hebrew alphabet is the alphabet used for Hebrew in its later familiar form.","zh":"the current Hebrew alphabet 是希伯來文後來較熟悉形式中使用的字母系統。"},{"en":"Students of ancient languages may compare the current Hebrew alphabet with earlier scripts.","zh":"古代語言學生可能把現代希伯來字母與較早文字作比較。"},{"en":"If the current Hebrew alphabet became popular, more writers likely used the same letter forms.","zh":"如果現代希伯來字母變得流行，更多書寫者很可能使用相同字母形態。"},{"en":"The phrase refers to a writing system, not the spoken language itself.","zh":"這個短語指書寫系統，而不是口語本身。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":3},{"front":"become popular around","meaning":"大約在……變得流行","examples":[{"en":"The Hebrew alphabet became popular around 600 B.C.","zh":"希伯來字母大約在公元前600年變得流行。"},{"en":"Become popular around a time means start being widely used or accepted at about that time.","zh":"become popular around 某時間，指大約在那時開始被廣泛使用或接受。"},{"en":"Smartphones became popular around the late 2000s in many cities.","zh":"智能手機大約在2000年代後期於許多城市變得流行。"},{"en":"If a script becomes popular around a certain date, historians can trace cultural change.","zh":"如果一種文字大約在某日期變得流行，歷史學家可以追蹤文化變化。"},{"en":"The phrase gives an approximate historical time, not an exact day.","zh":"這個短語提供大概歷史時間，而不是精確日期。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":3},{"front":"the Greek alphabet","meaning":"希臘字母","examples":[{"en":"The Greek alphabet was developed about 400 B.C.","zh":"希臘字母大約在公元前400年發展出來。"},{"en":"The Greek alphabet is the writing system used to write the Greek language.","zh":"the Greek alphabet 是用來書寫希臘語的書寫系統。"},{"en":"The Greek alphabet includes letters that later influenced Roman and other scripts.","zh":"希臘字母包含後來影響羅馬文字和其他文字的字母。"},{"en":"If students study the Greek alphabet, they can better understand the history of European writing.","zh":"如果學生研究希臘字母，就能更好理解歐洲書寫歷史。"},{"en":"The phrase refers to a specific historical and linguistic writing system.","zh":"這個短語指一套特定的歷史和語言書寫系統。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":3},{"front":"the first script written from left to right","meaning":"第一種從左至右書寫的文字","examples":[{"en":"Greek was the first script written from left to right.","zh":"希臘文是第一種從左至右書寫的文字。"},{"en":"The first script written from left to right means the earliest known writing system arranged in that direction.","zh":"the first script written from left to right 指已知最早按這個方向排列的書寫系統。"},{"en":"English is written from left to right, so readers begin each line on the left side.","zh":"英文從左至右書寫，所以讀者從每行左邊開始讀。"},{"en":"If Greek was the first script written from left to right, it changed the direction of later writing traditions.","zh":"如果希臘文是第一種從左至右書寫的文字，它就改變了後來書寫傳統的方向。"},{"en":"The phrase describes both historical order and writing direction.","zh":"這個短語同時描述歷史先後和書寫方向。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":3},{"front":"written from left to right","meaning":"從左至右書寫","examples":[{"en":"Greek was written from left to right.","zh":"希臘文從左至右書寫。"},{"en":"Written from left to right means the text begins on the left side and moves toward the right.","zh":"written from left to right 指文字從左邊開始並向右移動。"},{"en":"English, Italian, and Spanish are written from left to right.","zh":"英文、意大利文和西班牙文都是從左至右書寫。"},{"en":"If a learner is used to a different direction, writing from left to right may take practice.","zh":"如果學習者習慣另一種方向，從左至右書寫可能需要練習。"},{"en":"The phrase describes how text is arranged on a page.","zh":"這個短語描述文字在頁面上的排列方式。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":3},{"front":"Byzantine and Roman scripts","meaning":"拜占庭及羅馬文字","examples":[{"en":"Byzantine and Roman scripts subsequently developed from Greek.","zh":"拜占庭及羅馬文字其後由希臘文發展而成。"},{"en":"Byzantine and Roman scripts are writing styles or systems connected with Byzantine and Roman cultures.","zh":"Byzantine and Roman scripts 是與拜占庭和羅馬文化相關的書寫風格或系統。"},{"en":"Historians study Byzantine and Roman scripts to understand old manuscripts and inscriptions.","zh":"歷史學家研究拜占庭及羅馬文字，以理解古老手稿和銘文。"},{"en":"If Byzantine and Roman scripts developed from Greek, Greek influenced later European writing.","zh":"如果拜占庭及羅馬文字由希臘文發展而成，希臘文就影響了後來歐洲書寫。"},{"en":"The phrase refers to historical scripts, not modern handwriting styles only.","zh":"這個短語指歷史文字，而不只是現代手寫風格。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":3},{"front":"subsequently developed from","meaning":"其後由……發展而成","examples":[{"en":"Latin script subsequently developed from Greek.","zh":"拉丁文字其後由希臘文發展而成。"},{"en":"Subsequently developed from means later grew out of or was based on an earlier source.","zh":"subsequently developed from 指後來由較早來源發展出來或以其為基礎。"},{"en":"Many modern classroom tools subsequently developed from older teaching methods.","zh":"許多現代課堂工具其後由較舊教學方法發展而成。"},{"en":"If one script subsequently developed from another, the older script helped shape its letters.","zh":"如果一種文字其後由另一種文字發展而成，較舊文字就幫助塑造其字母。"},{"en":"The phrase shows historical sequence and origin.","zh":"這個短語顯示歷史先後和來源。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":3},{"front":"initially","meaning":"最初","examples":[{"en":"Initially, all writing systems used only uppercase letters.","zh":"最初，所有書寫系統只使用大楷字母。"},{"en":"Initially means at the beginning or in the first stage.","zh":"initially 指在開始時或最早階段。"},{"en":"Initially, the new app was used only by teachers, but later students used it too.","zh":"最初，這個新應用程式只由老師使用，但後來學生也使用。"},{"en":"If a system is simple initially, more features may be added over time.","zh":"如果一套系統最初很簡單，之後可能逐步加入更多功能。"},{"en":"The word helps mark the earliest stage of a process.","zh":"這個字幫助標示一個過程的最早階段。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":3},{"front":"writing systems","meaning":"書寫系統","examples":[{"en":"Initially, all writing systems used only uppercase letters.","zh":"最初，所有書寫系統只使用大楷字母。"},{"en":"Writing systems are organised ways of recording language with symbols, letters, or characters.","zh":"writing systems 是用符號、字母或文字有組織地記錄語言的方法。"},{"en":"The Roman alphabet and Chinese characters are different writing systems.","zh":"羅馬字母和中文字是不同書寫系統。"},{"en":"If a society develops writing systems, it can record laws, stories, and trade more permanently.","zh":"如果社會發展出書寫系統，它就能更永久地記錄法律、故事和貿易。"},{"en":"The phrase refers to the whole method of writing, not just one letter.","zh":"這個短語指整套書寫方法，而不是單一字母。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":4},{"front":"uppercase letters","meaning":"大楷字母","examples":[{"en":"The earliest writing systems used only uppercase letters.","zh":"最早期的書寫系統只使用大楷字母。"},{"en":"Uppercase letters are capital letters, such as A, B, and C.","zh":"uppercase letters 是大寫字母，例如 A、B 和 C。"},{"en":"A form may ask students to write their names in uppercase letters for clarity.","zh":"表格可能要求學生用大楷字母寫姓名，以便清楚閱讀。"},{"en":"If early writing used only uppercase letters, lowercase forms came later.","zh":"如果早期書寫只使用大楷字母，小楷形式就是後來才出現。"},{"en":"The phrase contrasts with lowercase letters, such as a, b, and c.","zh":"這個短語與小楷字母，例如 a、b 和 c，形成對比。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":4},{"front":"writing instruments","meaning":"書寫工具","examples":[{"en":"Writing instruments became refined enough to produce detailed letter forms.","zh":"書寫工具變得精細到足以產生細緻的字母形態。"},{"en":"Writing instruments are tools used for writing, such as pens, styluses, brushes, or pencils.","zh":"writing instruments 是用於書寫的工具，例如筆、尖筆、毛筆或鉛筆。"},{"en":"A pencil and a fountain pen are both writing instruments used in school and work.","zh":"鉛筆和鋼筆都是在學校和工作中使用的書寫工具。"},{"en":"When writing instruments improve, letters can become clearer, smaller, and more detailed.","zh":"當書寫工具改良，字母可以變得更清楚、更細小和更細緻。"},{"en":"The phrase focuses on the tool used to make marks.","zh":"這個短語重點在於用來留下痕跡的工具。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":4},{"front":"refined enough to","meaning":"精細到足以","examples":[{"en":"Writing instruments became refined enough to produce detailed letters.","zh":"書寫工具變得精細到足以寫出細緻字母。"},{"en":"Refined enough to do something means improved or precise enough to make that action possible.","zh":"refined enough to do something 指被改良或精準到足以做到某事。"},{"en":"A camera may be refined enough to photograph tiny details on a leaf.","zh":"相機可能精細到足以拍攝葉子上的微小細節。"},{"en":"If a pen is refined enough to make thin lines, writers can create smaller letters.","zh":"如果一支筆精細到足以畫出細線，書寫者就能創造更小的字母。"},{"en":"The phrase shows that a tool has reached the needed level of quality.","zh":"這個短語顯示工具已達到所需質素水平。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":4},{"front":"detailed letter forms","meaning":"細緻的字母形態","examples":[{"en":"Improved writing instruments could produce detailed letter forms.","zh":"改良後的書寫工具可以產生細緻的字母形態。"},{"en":"Detailed letter forms are carefully shaped letters with clear curves, lines, and differences.","zh":"detailed letter forms 是有清楚曲線、線條和差異的精細字母形狀。"},{"en":"A calligraphy teacher shows students how to create detailed letter forms slowly.","zh":"書法老師慢慢示範學生如何創造細緻的字母形態。"},{"en":"If writing tools become sharper, detailed letter forms become easier to make.","zh":"如果書寫工具變得更尖，細緻的字母形態就更容易形成。"},{"en":"The phrase describes the visual shape of letters, not their meaning.","zh":"這個短語描述字母的視覺形狀，而不是其意思。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":4},{"front":"lowercase letters","meaning":"小楷字母","examples":[{"en":"Lowercase letters were introduced around 600 A.D.","zh":"小楷字母大約在公元600年被引入。"},{"en":"Lowercase letters are small letters, such as a, b, and c.","zh":"lowercase letters 是小寫字母，例如 a、b 和 c。"},{"en":"Children usually learn both uppercase and lowercase letters in early English lessons.","zh":"孩子通常在早期英文課學習大楷和小楷字母。"},{"en":"If lowercase letters are used, writing can look faster and less heavy than all capitals.","zh":"如果使用小楷字母，書寫看起來可以比全大楷更快和較不沉重。"},{"en":"The phrase contrasts with uppercase letters.","zh":"這個短語與大楷字母形成對比。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":4},{"front":"be introduced","meaning":"被引入","examples":[{"en":"Lowercase letters were introduced when writing tools became more refined.","zh":"當書寫工具變得更精細時，小楷字母被引入。"},{"en":"To be introduced means to be brought in, started, or made available for the first time.","zh":"be introduced 指被引入、開始或首次提供。"},{"en":"A new timetable may be introduced when a school wants shorter lunch breaks.","zh":"當學校想縮短午膳時間，新時間表可能被引入。"},{"en":"If a new writing style is introduced, people may need time to learn it.","zh":"如果新書寫風格被引入，人們可能需要時間學習。"},{"en":"The phrase marks the beginning of a new system, tool, or practice.","zh":"這個短語標示新制度、工具或做法的開始。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":4},{"front":"the earliest means of writing","meaning":"最早期的書寫方法","examples":[{"en":"The earliest means of writing similar to pen and paper was developed by the Greeks.","zh":"最早期類似紙筆的書寫方法由希臘人發展出來。"},{"en":"The earliest means of writing means the first practical method people used to write.","zh":"the earliest means of writing 指人們用來書寫的最早實用方法。"},{"en":"A clay tablet and stylus were among the earliest means of writing in some ancient cultures.","zh":"在一些古代文化中，黏土板和尖筆屬於最早期的書寫方法。"},{"en":"If the earliest means of writing became portable, messages could travel more easily.","zh":"如果最早期的書寫方法變得可攜，訊息就能更容易傳送。"},{"en":"The phrase refers to early methods, not only early alphabets.","zh":"這個短語指早期方法，而不只是早期字母。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":4},{"front":"approach pen and paper","meaning":"接近紙筆形式","examples":[{"en":"Greek writing tools approached pen and paper as we know them today.","zh":"希臘書寫工具接近我們今日所認識的紙筆形式。"},{"en":"To approach pen and paper means to become similar to the modern idea of writing with a tool on a surface.","zh":"approach pen and paper 指變得類似現代用工具在表面上書寫的概念。"},{"en":"A tablet and stylus approach pen and paper because one tool makes marks on one surface.","zh":"寫字板和尖筆接近紙筆形式，因為一件工具在一個表面上留下痕跡。"},{"en":"If an ancient method approached pen and paper, writing became more flexible and personal.","zh":"如果古代方法接近紙筆形式，書寫就變得更靈活和個人化。"},{"en":"The phrase describes a step toward the familiar writing system we use now.","zh":"這個短語描述朝向我們今天熟悉書寫系統的一步。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":4},{"front":"as we know them today","meaning":"正如我們今日所認識的","examples":[{"en":"The Greeks developed writing tools close to pen and paper as we know them today.","zh":"希臘人發展出接近我們今日所認識的紙筆形式的書寫工具。"},{"en":"As we know them today means in the form familiar to people in the present.","zh":"as we know them today 指以今日人們熟悉的形式。"},{"en":"Phones as we know them today are very different from early telephones.","zh":"正如我們今日所認識的電話，與早期電話非常不同。"},{"en":"If writing tools approached pen and paper as we know them today, they felt closer to modern writing.","zh":"如果書寫工具接近我們今日所認識的紙筆形式，它們就更接近現代書寫。"},{"en":"The phrase compares an older form with the present familiar form.","zh":"這個短語把較舊形式與今天熟悉形式作比較。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":4},{"front":"employ a writing stylus","meaning":"使用書寫尖筆","examples":[{"en":"The Greeks employed a writing stylus made of metal, bone, or ivory.","zh":"希臘人使用由金屬、骨或象牙製成的書寫尖筆。"},{"en":"To employ a writing stylus means to use a pointed tool for making marks on a writing surface.","zh":"employ a writing stylus 指使用尖形工具在書寫表面留下痕跡。"},{"en":"A child using a touchscreen pen is, in a modern way, employing a stylus to write.","zh":"孩子使用觸控筆時，以現代方式來說，就是使用尖筆書寫。"},{"en":"If people employ a writing stylus on wax, they can scratch letters into the surface.","zh":"如果人們在蠟面上使用書寫尖筆，就能把字母刻進表面。"},{"en":"The phrase describes the tool and action used for early handwriting.","zh":"這個短語描述早期手寫所用的工具和動作。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":4},{"front":"writing stylus","meaning":"書寫尖筆","examples":[{"en":"A writing stylus was used to mark wax-coated tablets.","zh":"書寫尖筆被用來在塗蠟寫字板上留下痕跡。"},{"en":"A writing stylus is a pointed tool used to scratch or press marks into a surface.","zh":"writing stylus 是用來在表面刻畫或壓出痕跡的尖形工具。"},{"en":"Ancient students might use a writing stylus instead of a pen with ink.","zh":"古代學生可能使用書寫尖筆，而不是有墨水的筆。"},{"en":"If a writing stylus is sharp, it can make clearer marks on wax or clay.","zh":"如果書寫尖筆夠尖，它可以在蠟或黏土上留下更清楚痕跡。"},{"en":"The phrase refers to a writing tool, not the written message itself.","zh":"這個短語指書寫工具，而不是書寫訊息本身。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":5},{"front":"made of metal, bone, or ivory","meaning":"由金屬、骨或象牙製成","examples":[{"en":"The stylus was made of metal, bone, or ivory.","zh":"這支尖筆由金屬、骨或象牙製成。"},{"en":"Made of metal, bone, or ivory means formed from one of these hard materials.","zh":"made of metal, bone, or ivory 指由其中一種堅硬材料製成。"},{"en":"A museum may display tools made of metal, bone, or ivory to show ancient craftsmanship.","zh":"博物館可能展示由金屬、骨或象牙製成的工具，以顯示古代工藝。"},{"en":"If a stylus is made of metal, bone, or ivory, it is hard enough to scratch wax.","zh":"如果尖筆由金屬、骨或象牙製成，它就夠硬，可以刮寫蠟面。"},{"en":"The phrase describes the material used to make an object.","zh":"這個短語描述製造物件所用的材料。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":5},{"front":"place marks upon","meaning":"在……上留下痕跡","examples":[{"en":"The stylus placed marks upon wax-coated tablets.","zh":"尖筆在塗蠟寫字板上留下痕跡。"},{"en":"To place marks upon a surface means to make visible lines, signs, or scratches on it.","zh":"place marks upon 某表面，意思是在其上形成可見線條、符號或刮痕。"},{"en":"A pencil places marks upon paper when a child draws a picture.","zh":"孩子畫圖時，鉛筆在紙上留下痕跡。"},{"en":"If a stylus places marks upon wax, the writer can form letters without ink.","zh":"如果尖筆在蠟面上留下痕跡，書寫者就可以不用墨水也形成字母。"},{"en":"The phrase is formal and describes the act of making written marks.","zh":"這個短語較正式，描述留下書寫痕跡的動作。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":5},{"front":"wax-coated tablets","meaning":"塗蠟寫字板","examples":[{"en":"The Greeks wrote on wax-coated tablets.","zh":"希臘人在塗蠟寫字板上書寫。"},{"en":"Wax-coated tablets are flat writing boards covered with a layer of wax.","zh":"wax-coated tablets 是覆蓋一層蠟的平面書寫板。"},{"en":"A stylus can scratch letters into wax-coated tablets and smooth them out later.","zh":"尖筆可以把字母刻進塗蠟寫字板，之後再抹平。"},{"en":"If wax-coated tablets can be reused, they are useful for notes and practice.","zh":"如果塗蠟寫字板可以重複使用，它們就很適合筆記和練習。"},{"en":"The phrase describes an ancient writing surface.","zh":"這個短語描述一種古代書寫表面。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":5},{"front":"hinged pairs","meaning":"鉸接成對","examples":[{"en":"The tablets were made in hinged pairs.","zh":"這些寫字板鉸接成對。"},{"en":"Hinged pairs are two connected pieces that can open and close like a small book.","zh":"hinged pairs 是兩塊相連並可像小書一樣打開和關上的部分。"},{"en":"A glasses case uses a hinged pair of sides to protect what is inside.","zh":"眼鏡盒使用鉸接成對的兩邊來保護內裏物件。"},{"en":"If writing tablets are made in hinged pairs, they can close to protect the writing.","zh":"如果寫字板鉸接成對，它們就可以合上來保護文字。"},{"en":"The phrase describes both the structure and movement of the object.","zh":"這個短語同時描述物件的結構和活動方式。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":5},{"front":"protect the scribe’s notes","meaning":"保護書吏的筆記","examples":[{"en":"The tablets closed to protect the scribe’s notes.","zh":"寫字板可以合上，以保護書吏的筆記。"},{"en":"To protect the scribe’s notes means to keep the writer’s records safe from damage.","zh":"protect the scribe’s notes 指保護書寫者的記錄免受損壞。"},{"en":"A student puts notes in a folder to protect them from rain and tearing.","zh":"學生把筆記放入文件夾，以防雨水和撕裂。"},{"en":"If wax tablets close, they protect the scribe’s notes from being rubbed away.","zh":"如果蠟板可以合上，它們就能保護書吏的筆記不被擦掉。"},{"en":"The phrase shows the practical purpose of the hinged design.","zh":"這個短語顯示鉸接設計的實際用途。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":5},{"front":"scribe’s notes","meaning":"書吏的筆記","examples":[{"en":"The hinged tablets protected the scribe’s notes.","zh":"鉸接寫字板保護書吏的筆記。"},{"en":"Scribe’s notes are written records made by a scribe, a person trained to write.","zh":"scribe’s notes 是由受訓書寫者，即書吏，所寫的記錄。"},{"en":"A scribe’s notes might record laws, trade details, or messages from officials.","zh":"書吏的筆記可能記錄法律、交易細節或官員訊息。"},{"en":"If a scribe’s notes are damaged, important information may be lost.","zh":"如果書吏的筆記受損，重要資料可能會遺失。"},{"en":"The phrase connects writing with trained record-keepers in ancient society.","zh":"這個短語把書寫與古代社會中的受訓記錄員連繫起來。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":5},{"front":"examples of handwriting","meaning":"手寫文字的例子","examples":[{"en":"The first examples of handwriting originated in Greece.","zh":"最早的手寫文字例子起源於希臘。"},{"en":"Examples of handwriting are pieces of text written by hand rather than printed or carved.","zh":"examples of handwriting 是由人手書寫而非印刷或雕刻的文字樣本。"},{"en":"A teacher may compare examples of handwriting to see how students form letters.","zh":"老師可能比較手寫文字的例子，以了解學生如何寫字母。"},{"en":"If early examples of handwriting survive, historians can study how people wrote daily notes.","zh":"如果早期手寫文字例子保存下來，歷史學家就能研究人們如何寫日常筆記。"},{"en":"The phrase refers to visible samples of hand-written text.","zh":"這個短語指可見的手寫文字樣本。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":5},{"front":"purely text messages","meaning":"純文字訊息","examples":[{"en":"Handwriting refers to purely text messages made by hand.","zh":"手寫文字指以人手書寫的純文字訊息。"},{"en":"Purely text messages are messages made only of words or letters, without pictures.","zh":"purely text messages 是只由字詞或字母組成、沒有圖畫的訊息。"},{"en":"A note saying “Meet me at noon” is a purely text message.","zh":"寫着「中午見」的便條就是純文字訊息。"},{"en":"If writing moves from pictures to purely text messages, it becomes closer to modern handwriting.","zh":"如果書寫從圖畫變成純文字訊息，它就更接近現代手寫。"},{"en":"The phrase contrasts words with drawings or pictographs.","zh":"這個短語把文字與圖畫或圖畫符號作對比。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":5},{"front":"made by hand","meaning":"以人手書寫","examples":[{"en":"Handwriting consists of text messages made by hand.","zh":"手寫文字由以人手書寫的文字訊息組成。"},{"en":"Made by hand means created using human hands rather than machines.","zh":"made by hand 指用人手而不是機器製作。"},{"en":"A birthday card made by hand can feel more personal than a printed one.","zh":"手工製作的生日卡可能比印刷卡更有個人感覺。"},{"en":"If a message is made by hand, the writer’s style may be visible in the letters.","zh":"如果訊息以人手書寫，書寫者的風格可能在字母中可見。"},{"en":"The phrase contrasts hand-made work with machine-made work.","zh":"這個短語把人手製作與機器製作作對比。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":5},{"front":"originate in","meaning":"起源於","examples":[{"en":"The first examples of handwriting originated in Greece.","zh":"最早的手寫文字例子起源於希臘。"},{"en":"To originate in a place means to begin or first appear there.","zh":"originate in 某地，意思是在該地開始或首次出現。"},{"en":"The dish may originate in a small coastal town before spreading nationwide.","zh":"這道菜可能起源於一個小沿海城鎮，之後傳遍全國。"},{"en":"If handwriting originated in Greece, Greece played an important role in writing history.","zh":"如果手寫文字起源於希臘，希臘就在書寫歷史中扮演重要角色。"},{"en":"The phrase points to the starting place of an idea, object, or practice.","zh":"這個短語指出想法、物件或做法的起始地點。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":5},{"front":"be credited with","meaning":"被認為有……的功勞","examples":[{"en":"Cadmus is credited with inventing written correspondence.","zh":"Cadmus 被認為有發明書面通信的功勞。"},{"en":"To be credited with something means to be recognised as responsible for an achievement.","zh":"be credited with 某事，意思是被認可為某項成就的負責者。"},{"en":"A scientist may be credited with discovering a new medicine.","zh":"科學家可能被認為有發現新藥的功勞。"},{"en":"If someone is credited with an invention, later writers often connect their name with it.","zh":"如果某人被認為有一項發明的功勞，後來的作者常會把他的名字與該發明連繫起來。"},{"en":"The phrase gives recognition for a contribution, though historical certainty may vary.","zh":"這個短語承認某人的貢獻，雖然歷史確定性可能不同。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":6},{"front":"written correspondence","meaning":"書面通信","examples":[{"en":"Cadmus is credited with inventing written correspondence.","zh":"Cadmus 被認為發明了書面通信。"},{"en":"Written correspondence is communication through written messages sent between people.","zh":"written correspondence 是人與人之間透過書面訊息進行的溝通。"},{"en":"Emails, letters, and postcards are modern forms of written correspondence.","zh":"電郵、信件和明信片都是現代書面通信形式。"},{"en":"If written correspondence develops, people can communicate across distance without speaking face to face.","zh":"如果書面通信發展起來，人們就能不用面對面說話也跨距離溝通。"},{"en":"The phrase refers to exchanged writing, not private notes kept by one person.","zh":"這個短語指互相傳送的書寫訊息，而不是一個人保存的私人筆記。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":6},{"front":"sent from one person to another","meaning":"由一人送往另一人","examples":[{"en":"Written correspondence involves messages sent from one person to another.","zh":"書面通信涉及由一人送往另一人的訊息。"},{"en":"Sent from one person to another means passed or delivered between two people.","zh":"sent from one person to another 指在兩個人之間傳遞或送達。"},{"en":"A text message is sent from one person to another in a few seconds.","zh":"短訊可以在幾秒內由一人送往另一人。"},{"en":"If written messages can be sent from one person to another, communication becomes more flexible.","zh":"如果書面訊息可以由一人送往另一人，溝通就變得更靈活。"},{"en":"The phrase highlights movement of a message between sender and receiver.","zh":"這個短語強調訊息在發送者和接收者之間移動。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":6},{"front":"advance beyond","meaning":"超越……而發展","examples":[{"en":"Writing was advancing beyond pictures carved into stone.","zh":"書寫正在超越刻在石上的圖畫而發展。"},{"en":"To advance beyond something means to develop past an earlier or simpler stage.","zh":"advance beyond 某物，意思是發展到超越較早或較簡單的階段。"},{"en":"A student advances beyond basic words when they can write full paragraphs.","zh":"當學生能寫完整段落，就超越基本單字而發展。"},{"en":"If writing advanced beyond pictures, it could record speech and ideas more directly.","zh":"如果書寫超越圖畫，它就能更直接地記錄語言和想法。"},{"en":"The phrase shows progress from an older method to a more developed one.","zh":"這個短語顯示從舊方法進步到更發展的方法。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":6},{"front":"chisel pictures into stone","meaning":"將圖畫鑿刻在石上","examples":[{"en":"Early writing involved chiselling pictures into stone.","zh":"早期書寫涉及將圖畫鑿刻在石上。"},{"en":"To chisel pictures into stone means to cut images into stone using a sharp tool.","zh":"chisel pictures into stone 指用尖銳工具把圖像刻進石頭。"},{"en":"Ancient workers chiselled pictures into stone walls to record rulers, battles, or gods.","zh":"古代工人把圖畫鑿刻在石牆上，以記錄統治者、戰爭或神明。"},{"en":"If people had to chisel pictures into stone, writing was slow and difficult to move.","zh":"如果人們必須將圖畫鑿刻在石上，書寫就會很慢，而且難以移動。"},{"en":"The phrase describes a hard, permanent but labour-intensive writing method.","zh":"這個短語描述一種堅固、永久但耗力的書寫方法。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":6},{"front":"wedge pictographs into wet clay","meaning":"將圖畫符號壓入濕黏土","examples":[{"en":"People once wedged pictographs into wet clay.","zh":"人們曾經將圖畫符號壓入濕黏土。"},{"en":"To wedge pictographs into wet clay means to press picture symbols into soft clay.","zh":"wedge pictographs into wet clay 指把圖畫符號壓進柔軟的黏土中。"},{"en":"A child pressing shapes into soft dough is doing something similar to wedging marks into clay.","zh":"孩子把形狀壓進軟麵團中，做法類似把標記壓入黏土。"},{"en":"If pictographs are wedged into wet clay, they can remain visible after the clay dries.","zh":"如果圖畫符號被壓入濕黏土，黏土乾後它們仍可看見。"},{"en":"The phrase describes a physical method of making early written records.","zh":"這個短語描述製作早期書面記錄的實體方法。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":6},{"front":"wet clay","meaning":"濕黏土","examples":[{"en":"Pictographs were wedged into wet clay.","zh":"圖畫符號被壓入濕黏土中。"},{"en":"Wet clay is soft clay that contains water and can be shaped or marked.","zh":"wet clay 是含水、柔軟並可以被塑形或留下痕跡的黏土。"},{"en":"Potters shape wet clay before it dries and hardens.","zh":"陶工在濕黏土變乾變硬前塑造它。"},{"en":"If wet clay is pressed with a stylus, it can keep the shape of the mark.","zh":"如果濕黏土被尖筆壓下，它可以保留標記形狀。"},{"en":"The phrase describes a material useful for early writing because it is soft before drying.","zh":"這個短語描述一種適合早期書寫的材料，因為它乾前很柔軟。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":6},{"front":"invent and perfect","meaning":"發明並完善","examples":[{"en":"The Chinese invented and perfected Indian ink.","zh":"中國人發明並完善了墨汁。"},{"en":"To invent and perfect something means to create it and then improve it until it works very well.","zh":"invent and perfect 某物，意思是創造它，並不斷改良至運作良好。"},{"en":"Engineers invent and perfect machines by testing them again and again.","zh":"工程師透過反覆測試來發明並完善機器。"},{"en":"If a culture invents and perfects ink, writing can become clearer and more durable.","zh":"如果一種文化發明並完善墨水，書寫就能變得更清楚和更持久。"},{"en":"The phrase combines first creation with later improvement.","zh":"這個短語結合最初創造和後來改良。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":6},{"front":"Indian ink","meaning":"墨汁；印度墨","examples":[{"en":"The Chinese invented and perfected Indian ink.","zh":"中國人發明並完善了墨汁。"},{"en":"Indian ink is a deep black ink traditionally used for writing, drawing, and calligraphy.","zh":"Indian ink 是傳統上用於書寫、繪畫和書法的深黑色墨水。"},{"en":"Artists may use Indian ink to draw strong black lines on paper.","zh":"藝術家可能使用印度墨在紙上畫出強烈黑線。"},{"en":"If Indian ink is stable and dark, written marks can remain clear for a long time.","zh":"如果墨汁穩定而深黑，書寫痕跡就能長時間保持清晰。"},{"en":"The phrase names a specific type of ink, not ink from India in this context.","zh":"這個短語指一種特定墨水，在此語境中不一定指來自印度的墨水。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":6},{"front":"originally designed for","meaning":"原本為……而設計","examples":[{"en":"The ink was originally designed for blacking stone-carved hieroglyphics.","zh":"這種墨原本為塗黑石刻象形文字而設計。"},{"en":"Originally designed for something means first created for that purpose.","zh":"originally designed for 某用途，指最初為該目的而創造。"},{"en":"Some school buildings were originally designed for small classes, not hundreds of students.","zh":"有些校舍原本為小班教學而設計，而不是為數百名學生而設。"},{"en":"If ink was originally designed for carved symbols, its first purpose was not ordinary handwriting.","zh":"如果墨水原本為雕刻符號而設計，它最初用途就不是普通手寫。"},{"en":"The phrase shows the earliest intended use of an object.","zh":"這個短語顯示物件最早的設計用途。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":6},{"front":"blacking the surfaces of","meaning":"將……的表面塗黑","examples":[{"en":"The ink was used for blacking the surfaces of raised carvings.","zh":"這種墨用於將凸起雕刻的表面塗黑。"},{"en":"Blacking the surfaces of something means making its outer parts black.","zh":"blacking the surfaces of 某物，指令其外層部分變黑。"},{"en":"A designer may black the surface of a sign so white letters stand out clearly.","zh":"設計師可能將標誌表面塗黑，使白色字母更突出。"},{"en":"If ink blacks the surfaces of raised carvings, the carved symbols become easier to see.","zh":"如果墨水將凸起雕刻的表面塗黑，雕刻符號就更容易看見。"},{"en":"The phrase describes applying black colour to a surface.","zh":"這個短語描述把黑色塗到表面上的動作。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":6},{"front":"raised stone-carved hieroglyphics","meaning":"凸起的石刻象形文字","examples":[{"en":"The ink was used on raised stone-carved hieroglyphics.","zh":"這種墨用於凸起的石刻象形文字。"},{"en":"Raised stone-carved hieroglyphics are picture-like symbols carved so they stand out from a stone surface.","zh":"raised stone-carved hieroglyphics 是刻在石面上並凸起的圖像式符號。"},{"en":"A museum wall may show raised stone-carved hieroglyphics from an ancient temple.","zh":"博物館牆上可能展示來自古代神廟的凸起石刻象形文字。"},{"en":"If raised carvings are blackened, their shapes become clearer to readers.","zh":"如果凸起雕刻被塗黑，其形狀就會更清楚讓讀者看見。"},{"en":"The phrase describes both the material, stone, and the raised picture-writing form.","zh":"這個短語同時描述材料，即石頭，以及凸起的圖像文字形式。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":7},{"front":"a mixture of","meaning":"……的混合物","examples":[{"en":"The ink was a mixture of soot, oil, gelatin and musk.","zh":"這種墨是煤煙、油、膠和麝香的混合物。"},{"en":"A mixture of things means a combination of two or more materials.","zh":"a mixture of 多種東西，指兩種或以上材料的組合。"},{"en":"Soup is often a mixture of water, vegetables, meat, and seasoning.","zh":"湯通常是水、蔬菜、肉和調味料的混合物。"},{"en":"If ink is a mixture of several ingredients, each one may affect colour, smell, or texture.","zh":"如果墨水是幾種材料的混合物，每種材料都可能影響顏色、氣味或質地。"},{"en":"The phrase explains what something is made from.","zh":"這個短語解釋某物由甚麼製成。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":7},{"front":"soot from pine smoke","meaning":"松煙煤","examples":[{"en":"The ink contained soot from pine smoke.","zh":"這種墨含有松煙煤。"},{"en":"Soot from pine smoke is black powder produced when pine wood or resin burns incompletely.","zh":"soot from pine smoke 是松木或松脂不完全燃燒時產生的黑色粉末。"},{"en":"A fireplace can leave soot on the wall if smoke does not escape properly.","zh":"如果煙不能正常排出，壁爐可能在牆上留下煤煙。"},{"en":"If soot from pine smoke is mixed with oil, it can help create dark ink.","zh":"如果松煙煤與油混合，它可以幫助製造深色墨水。"},{"en":"The phrase identifies the black colouring material in the ink.","zh":"這個短語指出墨水中的黑色顏料材料。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":7},{"front":"lamp oil","meaning":"燈油","examples":[{"en":"Lamp oil was one ingredient in early Chinese ink.","zh":"燈油是早期中國墨的一種成分。"},{"en":"Lamp oil is oil burned in a lamp to produce light.","zh":"lamp oil 是在燈中燃燒以產生光的油。"},{"en":"Before electric lights, families used lamp oil to light rooms at night.","zh":"在電燈出現前，家庭晚上用燈油照亮房間。"},{"en":"If lamp oil is mixed with soot, it can help form a usable ink mixture.","zh":"如果燈油與煤煙混合，它可以幫助形成可用的墨水混合物。"},{"en":"The phrase refers to a practical fuel used before modern lighting.","zh":"這個短語指現代照明出現前使用的實用燃料。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":7},{"front":"mixed with","meaning":"與……混合","examples":[{"en":"The soot and oil were mixed with donkey-skin gelatin and musk.","zh":"煤煙和油與驢皮膠及麝香混合。"},{"en":"Mixed with means combined together with another substance.","zh":"mixed with 指與另一種物質結合在一起。"},{"en":"Flour mixed with water can become dough.","zh":"麵粉與水混合後可以變成麵團。"},{"en":"If ink ingredients are mixed with a binding material, the ink may stick better to the surface.","zh":"如果墨水材料與黏合材料混合，墨水可能更好附着在表面。"},{"en":"The phrase shows materials being joined into one mixture.","zh":"這個短語顯示材料被結合成一種混合物。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":7},{"front":"gelatin of donkey skin","meaning":"驢皮膠","examples":[{"en":"Early ink used gelatin of donkey skin.","zh":"早期墨水使用驢皮膠。"},{"en":"Gelatin of donkey skin is a sticky substance made by boiling donkey skin.","zh":"gelatin of donkey skin 是透過熬煮驢皮製成的黏性物質。"},{"en":"Traditional mixtures sometimes used animal gelatin to bind materials together.","zh":"傳統混合物有時使用動物膠把材料黏合在一起。"},{"en":"If gelatin of donkey skin was added to ink, it could help hold the ingredients together.","zh":"如果驢皮膠被加入墨水中，它可以幫助把材料結合起來。"},{"en":"The phrase describes an animal-based ingredient used in an old formula.","zh":"這個短語描述舊配方中使用的動物性材料。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":7},{"front":"musk","meaning":"麝香","examples":[{"en":"Musk was used in the mixture for early ink.","zh":"麝香被用於早期墨水的混合物中。"},{"en":"Musk is a strong-smelling substance traditionally used in perfumes and special mixtures.","zh":"musk 是一種氣味強烈的物質，傳統上用於香水和特殊混合物。"},{"en":"A perfume may contain musk to give it a deep, lasting smell.","zh":"香水可能含有麝香，以帶來深厚而持久的氣味。"},{"en":"If musk was added to ink, it may have affected the scent of the mixture.","zh":"如果麝香被加入墨水，它可能影響混合物的氣味。"},{"en":"The word refers to an aromatic ingredient, not a writing tool itself.","zh":"這個字指芳香成分，而不是書寫工具本身。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":7},{"front":"become common by","meaning":"到……時變得普遍","examples":[{"en":"The ink became common by the year 1200 B.C.","zh":"這種墨到公元前1200年時變得普遍。"},{"en":"Become common by a time means be widely used or familiar no later than that time.","zh":"become common by 某時間，指不遲於該時間已被廣泛使用或熟悉。"},{"en":"Mobile payment became common by the time many shops stopped requiring cash.","zh":"到許多商店不再要求現金時，流動支付已變得普遍。"},{"en":"If an ink became common by 1200 B.C., many people or institutions were already using it then.","zh":"如果一種墨到公元前1200年已變得普遍，當時很多人或機構已在使用它。"},{"en":"The phrase gives a latest point by which something had spread.","zh":"這個短語給出某事物已傳播開來的最遲時間點。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":7},{"front":"natural dyes","meaning":"天然染料","examples":[{"en":"Other cultures developed inks using natural dyes.","zh":"其他文化使用天然染料發展墨水。"},{"en":"Natural dyes are colouring substances taken from plants, animals, or minerals.","zh":"natural dyes 是從植物、動物或礦物取得的着色物質。"},{"en":"Onion skins, berries, and some flowers can be used as natural dyes.","zh":"洋蔥皮、漿果和一些花可以用作天然染料。"},{"en":"If ink uses natural dyes, its colour depends on materials found in the environment.","zh":"如果墨水使用天然染料，其顏色就取決於環境中找到的材料。"},{"en":"The phrase contrasts natural colour sources with artificial chemicals.","zh":"這個短語把天然顏色來源與人工化學物作對比。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":7},{"front":"colours derived from","meaning":"源自……的顏色","examples":[{"en":"Some inks used colours derived from berries, plants and minerals.","zh":"有些墨水使用源自漿果、植物和礦物的顏色。"},{"en":"Colours derived from something are colours obtained or made from that source.","zh":"colours derived from 某物，是從該來源取得或製成的顏色。"},{"en":"A red dye may use colours derived from flowers or fruit skins.","zh":"紅色染料可能使用源自花朵或果皮的顏色。"},{"en":"If colours are derived from plants, different seasons may affect supply.","zh":"如果顏色源自植物，不同季節可能影響供應。"},{"en":"The phrase explains where a colour comes from.","zh":"這個短語解釋顏色來自哪裏。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":7},{"front":"berries, plants, and minerals","meaning":"漿果、植物和礦物","examples":[{"en":"Natural colours were derived from berries, plants, and minerals.","zh":"天然顏色源自漿果、植物和礦物。"},{"en":"Berries, plants, and minerals are natural sources that can provide pigments or dyes.","zh":"berries, plants, and minerals 是可以提供顏料或染料的天然來源。"},{"en":"People may use berries, plants, and minerals to colour cloth or paper naturally.","zh":"人們可能使用漿果、植物和礦物來自然地為布或紙着色。"},{"en":"If dyes come from berries, plants, and minerals, local resources shape the colours available.","zh":"如果染料來自漿果、植物和礦物，本地資源就會塑造可用顏色。"},{"en":"The phrase lists common natural colour sources.","zh":"這個短語列出常見天然顏色來源。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":7},{"front":"ritual meanings","meaning":"儀式意義","examples":[{"en":"Different coloured inks had ritual meanings.","zh":"不同顏色的墨水有儀式意義。"},{"en":"Ritual meanings are symbolic meanings connected with ceremonies, religion, or formal customs.","zh":"ritual meanings 是與典禮、宗教或正式習俗相關的象徵意思。"},{"en":"White clothing may have ritual meanings in weddings or funerals, depending on culture.","zh":"白色衣服在婚禮或葬禮中可能有儀式意義，視乎文化而定。"},{"en":"If ink colours have ritual meanings, choosing a colour is not only an artistic decision.","zh":"如果墨水顏色有儀式意義，選擇顏色就不只是藝術決定。"},{"en":"The phrase connects objects or colours with ceremony and belief.","zh":"這個短語把物件或顏色與儀式和信仰連繫起來。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":8},{"front":"attached to","meaning":"附加於……；與……相關","examples":[{"en":"Ritual meanings were attached to each colour.","zh":"儀式意義與每種顏色相關。"},{"en":"Attached to something means connected with it or associated with it.","zh":"attached to 某物，意思是與它連接或相關。"},{"en":"A family story may be attached to an old watch.","zh":"一隻舊手錶可能附有一個家庭故事。"},{"en":"If special meanings are attached to colours, people choose them carefully.","zh":"如果特殊意思與顏色相關，人們就會小心選擇顏色。"},{"en":"The phrase can describe physical connection or symbolic association.","zh":"這個短語可以描述實體連接或象徵性關聯。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":8},{"front":"parallel the introduction of","meaning":"與……同步發展","examples":[{"en":"The invention of inks paralleled the introduction of paper.","zh":"墨水的發明與紙張的引入同步發展。"},{"en":"To parallel the introduction of something means to develop at the same time as it.","zh":"parallel the introduction of 某物，意思是與它的引入同時發展。"},{"en":"The growth of online shopping paralleled the introduction of mobile payment.","zh":"網上購物的增長與流動支付的引入同步發展。"},{"en":"If ink development paralleled the introduction of paper, both writing materials improved together.","zh":"如果墨水發展與紙張引入同步，兩種書寫材料就一同改善。"},{"en":"The phrase shows two developments happening side by side.","zh":"這個短語顯示兩項發展並行發生。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":8},{"front":"the introduction of paper","meaning":"紙張的引入","examples":[{"en":"The invention of inks paralleled the introduction of paper.","zh":"墨水的發明與紙張的引入同步發展。"},{"en":"The introduction of paper means the beginning of paper being used in a place or culture.","zh":"the introduction of paper 指紙張在某地或文化中開始被使用。"},{"en":"The introduction of paper made schools and offices less dependent on heavier writing surfaces.","zh":"紙張的引入使學校和辦公室較少依賴更重的書寫表面。"},{"en":"If the introduction of paper spread slowly, writing practices also changed slowly.","zh":"如果紙張的引入傳播緩慢，書寫做法也會慢慢改變。"},{"en":"The phrase marks the arrival of a major writing material.","zh":"這個短語標示一種重要書寫材料的出現。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":8},{"front":"papyrus and parchment","meaning":"紙莎草紙和羊皮紙","examples":[{"en":"The early Egyptians, Romans, Greeks and Hebrews used papyrus and parchment.","zh":"早期埃及人、羅馬人、希臘人和希伯來人使用紙莎草紙和羊皮紙。"},{"en":"Papyrus and parchment are early writing materials made from plant fibres and animal skin.","zh":"papyrus and parchment 是由植物纖維和動物皮製成的早期書寫材料。"},{"en":"Ancient letters and religious texts were sometimes written on papyrus and parchment.","zh":"古代信件和宗教文本有時寫在紙莎草紙和羊皮紙上。"},{"en":"If people used papyrus and parchment, writing became more portable than stone carving.","zh":"如果人們使用紙莎草紙和羊皮紙，書寫就比石刻更可攜。"},{"en":"The phrase names two important materials used before modern paper became common.","zh":"這個短語指出現代紙張普及前使用的兩種重要材料。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":8},{"front":"one of the oldest pieces of writing","meaning":"最古老的文字作品之一","examples":[{"en":"The Prisse Papyrus is one of the oldest pieces of writing on papyrus.","zh":"《普里斯紙草書》是紙莎草紙上最古老的文字作品之一。"},{"en":"One of the oldest pieces of writing means among the earliest written texts still known.","zh":"one of the oldest pieces of writing 指仍為人所知的最早書面文本之一。"},{"en":"A museum may protect one of the oldest pieces of writing in a dark, dry room.","zh":"博物館可能把最古老的文字作品之一存放在陰暗乾爽的房間。"},{"en":"If a text is one of the oldest pieces of writing, it helps historians study early language and society.","zh":"如果一份文本是最古老的文字作品之一，它就幫助歷史學家研究早期語言和社會。"},{"en":"The phrase highlights great historical age and importance.","zh":"這個短語強調極高的歷史年代和重要性。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":8},{"front":"known to us today","meaning":"今日為我們所知的","examples":[{"en":"The Prisse Papyrus is one of the oldest examples known to us today.","zh":"《普里斯紙草書》是今日為我們所知的最古老例子之一。"},{"en":"Known to us today means discovered, preserved, and recognised by people in the present.","zh":"known to us today 指被今天的人發現、保存並認識。"},{"en":"Some ancient songs are not known to us today because no written record survived.","zh":"有些古代歌曲今日不為我們所知，因為沒有書面記錄保存下來。"},{"en":"If an object is known to us today, it has somehow survived time, damage, and loss.","zh":"如果一件物件今日為我們所知，它必定以某種方式經歷時間、損壞和失落後保存下來。"},{"en":"The phrase reminds readers that many ancient things may have disappeared.","zh":"這個短語提醒讀者，許多古代事物可能已經消失。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":8},{"front":"the Egyptian Prisse Papyrus","meaning":"埃及《普里斯紙草書》","examples":[{"en":"The Egyptian Prisse Papyrus dates back to 2000 B.C.","zh":"埃及《普里斯紙草書》可追溯至公元前2000年。"},{"en":"The Egyptian Prisse Papyrus is an ancient Egyptian text written on papyrus.","zh":"the Egyptian Prisse Papyrus 是寫在紙莎草紙上的古埃及文本。"},{"en":"Scholars study the Egyptian Prisse Papyrus to understand early writing and thought.","zh":"學者研究埃及《普里斯紙草書》，以了解早期書寫和思想。"},{"en":"If the Egyptian Prisse Papyrus dates back thousands of years, it is valuable historical evidence.","zh":"如果埃及《普里斯紙草書》可追溯至數千年前，它就是有價值的歷史證據。"},{"en":"The phrase names a specific ancient document.","zh":"這個短語指出一份特定古代文件。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":8},{"front":"reed pens","meaning":"蘆葦筆","examples":[{"en":"The Romans made reed pens suited to parchment and ink.","zh":"羅馬人製作適合羊皮紙和墨水的蘆葦筆。"},{"en":"Reed pens are writing tools made from hollow plant stems.","zh":"reed pens 是由空心植物莖製成的書寫工具。"},{"en":"A reed pen can hold ink and release it through a cut nib.","zh":"蘆葦筆可以盛載墨水，並透過切出的筆尖釋放墨水。"},{"en":"If reed pens work well with parchment, writers can produce clearer text than with rougher tools.","zh":"如果蘆葦筆適合羊皮紙，書寫者就能比使用較粗糙工具寫出更清楚文字。"},{"en":"The phrase describes an early pen made from plant material.","zh":"這個短語描述由植物材料製成的早期筆。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":8},{"front":"suited to","meaning":"適合……","examples":[{"en":"Reed pens were suited to parchment and ink.","zh":"蘆葦筆適合羊皮紙和墨水。"},{"en":"Suited to something means appropriate or useful for that purpose or material.","zh":"suited to 某物，意思是適合或有助於該用途或材料。"},{"en":"Waterproof shoes are suited to rainy walks.","zh":"防水鞋適合雨天步行。"},{"en":"If a pen is suited to parchment and ink, it writes smoothly on that surface.","zh":"如果一支筆適合羊皮紙和墨水，它就能在該表面上順暢書寫。"},{"en":"The phrase shows a good match between tool and use.","zh":"這個短語顯示工具與用途之間的良好配合。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":8},{"front":"hollow stems","meaning":"空心莖","examples":[{"en":"The pens were made from the hollow stems of marsh grasses.","zh":"這些筆由沼澤草的空心莖製成。"},{"en":"Hollow stems are plant stems with empty spaces inside.","zh":"hollow stems 是內部有空間的植物莖。"},{"en":"Some children use hollow stems as simple straws when playing outdoors.","zh":"有些孩子在戶外玩耍時用空心莖作簡單吸管。"},{"en":"If a stem is hollow, it can hold writing fluid like a tiny tube.","zh":"如果莖是空心的，它就能像小管一樣盛載書寫液。"},{"en":"The phrase explains why certain plants could be turned into pens.","zh":"這個短語解釋為何某些植物可以被製成筆。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":8},{"front":"marsh grasses","meaning":"沼澤草","examples":[{"en":"Reed pens were made from marsh grasses.","zh":"蘆葦筆由沼澤草製成。"},{"en":"Marsh grasses are grasses that grow in wet, swampy places.","zh":"marsh grasses 是生長在潮濕、沼澤地方的草。"},{"en":"Birds often hide among marsh grasses near lakes and rivers.","zh":"鳥類常藏在湖泊和河流附近的沼澤草中。"},{"en":"If marsh grasses have hollow stems, they can be useful for making reed pens.","zh":"如果沼澤草有空心莖，它們就可用於製作蘆葦筆。"},{"en":"The phrase identifies the wetland plants used as writing materials.","zh":"這個短語指出被用作書寫材料的濕地植物。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":9},{"front":"jointed bamboo","meaning":"有節竹","examples":[{"en":"Jointed bamboo was used to make early reed pens.","zh":"有節竹被用來製作早期蘆葦筆。"},{"en":"Jointed bamboo is bamboo with natural sections or nodes along its stem.","zh":"jointed bamboo 是莖上有天然節點或分段的竹。"},{"en":"Gardeners can see jointed bamboo clearly because the stem is divided into segments.","zh":"園丁很容易看見有節竹，因為竹莖被分成一節一節。"},{"en":"If jointed bamboo is hollow between joints, it can hold ink inside.","zh":"如果有節竹在節點之間是空心的，它就可以在內部盛載墨水。"},{"en":"The phrase describes the structure of the plant material.","zh":"這個短語描述植物材料的結構。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":9},{"front":"convert something into","meaning":"將某物轉化成……","examples":[{"en":"The Romans converted bamboo stems into a primitive fountain pen.","zh":"羅馬人將竹莖轉化成原始鋼筆。"},{"en":"To convert something into something else means to change it into a new form or use.","zh":"convert something into something else 指把某物變成另一種形式或用途。"},{"en":"A family can convert an old bedroom into a study room.","zh":"一個家庭可以把舊睡房改成書房。"},{"en":"If bamboo stems are converted into pens, natural materials become writing tools.","zh":"如果竹莖被轉化成筆，天然材料就變成書寫工具。"},{"en":"The phrase focuses on transformation from one purpose to another.","zh":"這個短語重點在於從一種用途轉變成另一種用途。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":9},{"front":"a primitive form of","meaning":"……的原始形式","examples":[{"en":"Bamboo stems became a primitive form of a fountain pen.","zh":"竹莖成為鋼筆的原始形式。"},{"en":"A primitive form of something is an early, simple version of a later more developed object.","zh":"a primitive form of 某物，指後來較發達物件的早期簡單版本。"},{"en":"A basic wheel cart was a primitive form of modern transport.","zh":"簡單輪車是現代交通工具的原始形式。"},{"en":"If a reed pen stored ink in its stem, it worked like a primitive form of a fountain pen.","zh":"如果蘆葦筆把墨水存於莖中，它就像鋼筆的原始形式般運作。"},{"en":"The phrase compares an early tool with a later advanced version.","zh":"這個短語把早期工具與後來更先進版本作比較。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":9},{"front":"fountain pen","meaning":"鋼筆","examples":[{"en":"The bamboo stem worked like a primitive fountain pen.","zh":"竹莖像一支原始鋼筆般運作。"},{"en":"A fountain pen is a pen that holds ink inside and feeds it to the nib while writing.","zh":"fountain pen 是內部盛載墨水，並在書寫時把墨水送到筆尖的筆。"},{"en":"A student may use a fountain pen to write neatly in a journal.","zh":"學生可能用鋼筆在日記中整齊書寫。"},{"en":"If a pen stores ink inside, writers do not need to dip it constantly into ink.","zh":"如果一支筆能在內部儲存墨水，書寫者就不用不停蘸墨。"},{"en":"The phrase refers to a refillable ink pen, not a ballpoint pen.","zh":"這個短語指可補充墨水的筆，而不是原子筆。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":9},{"front":"cut one end into","meaning":"將一端切成……","examples":[{"en":"The Romans cut one end into the form of a pen nib.","zh":"羅馬人將一端切成筆尖形狀。"},{"en":"To cut one end into a shape means to shape the end of a material by cutting it.","zh":"cut one end into 某形狀，指透過切割把材料的一端塑造成該形狀。"},{"en":"A craft teacher may cut one end of a straw into a point for a simple art tool.","zh":"手工老師可能把飲管一端切成尖形，作簡單藝術工具。"},{"en":"If one end of a reed is cut into a nib, ink can flow through it onto the page.","zh":"如果蘆葦一端被切成筆尖，墨水就能經它流到頁面上。"},{"en":"The phrase describes changing the shape of a tool’s tip.","zh":"這個短語描述改變工具尖端形狀。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":9},{"front":"pen nib","meaning":"筆尖","examples":[{"en":"One end of the reed was cut into a pen nib.","zh":"蘆葦的一端被切成筆尖。"},{"en":"A pen nib is the pointed writing tip of a pen where ink comes out.","zh":"pen nib 是筆上出墨並接觸紙面的尖端部分。"},{"en":"A damaged pen nib can scratch the paper or make uneven lines.","zh":"損壞的筆尖可能刮紙或寫出不均勻線條。"},{"en":"If a nib is cut carefully, the writer can control the thickness of the line.","zh":"如果筆尖被小心切割，書寫者就能控制線條粗幼。"},{"en":"The phrase names the small part of a pen that touches the writing surface.","zh":"這個短語指出筆接觸書寫表面的小部分。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":9},{"front":"writing fluid","meaning":"書寫液","examples":[{"en":"A writing fluid or ink filled the stem.","zh":"書寫液或墨水填滿莖部。"},{"en":"Writing fluid is liquid used to make marks when writing.","zh":"writing fluid 是用於書寫時留下痕跡的液體。"},{"en":"Ink is the most common writing fluid used in pens.","zh":"墨水是筆中最常見的書寫液。"},{"en":"If a writing fluid flows smoothly, the pen can make steady lines.","zh":"如果書寫液流動順暢，筆就能寫出穩定線條。"},{"en":"The phrase is a general term for liquid used in writing.","zh":"這個短語是書寫用液體的概括說法。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":9},{"front":"fill the stem","meaning":"填滿莖部","examples":[{"en":"Ink filled the stem of the reed pen.","zh":"墨水填滿蘆葦筆的莖部。"},{"en":"To fill the stem means to put liquid into the hollow part of the plant stem.","zh":"fill the stem 指把液體放進植物莖的空心部分。"},{"en":"A child might fill a hollow straw with water during a science activity.","zh":"孩子在科學活動中可能把水注入空心飲管。"},{"en":"If ink fills the stem, the pen can store liquid before it reaches the nib.","zh":"如果墨水填滿莖部，筆就能在墨水到達筆尖前先儲存液體。"},{"en":"The phrase explains how a simple plant tube could act like a pen.","zh":"這個短語解釋簡單植物管如何能像筆一樣運作。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":9},{"front":"squeeze the reed","meaning":"擠壓蘆葦","examples":[{"en":"Squeezing the reed forced the fluid to the nib.","zh":"擠壓蘆葦會把液體推向筆尖。"},{"en":"To squeeze the reed means to press the reed so liquid inside moves forward.","zh":"squeeze the reed 指按壓蘆葦，使內部液體向前移動。"},{"en":"A student squeezing a dropper pushes liquid out in a similar way.","zh":"學生擠壓滴管時，也以類似方式把液體推出。"},{"en":"If writers squeezed the reed gently, they could send ink toward the writing tip.","zh":"如果書寫者輕輕擠壓蘆葦，就能把墨水送向書寫尖端。"},{"en":"The phrase describes the action that made the primitive pen work.","zh":"這個短語描述令原始筆運作的動作。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":9},{"front":"force the fluid to","meaning":"將液體推向……","examples":[{"en":"Squeezing the reed forced the fluid to the nib.","zh":"擠壓蘆葦將液體推向筆尖。"},{"en":"To force the fluid to a place means to push liquid there by pressure.","zh":"force the fluid to 某處，指透過壓力把液體推到那裏。"},{"en":"Pressing a sauce bottle forces the sauce to the opening.","zh":"按壓醬汁瓶會將醬汁推向出口。"},{"en":"If pressure forces the fluid to the nib, ink can appear on the writing surface.","zh":"如果壓力將液體推向筆尖，墨水就能出現在書寫表面上。"},{"en":"The phrase shows movement caused by pressure, not by free flow alone.","zh":"這個短語顯示由壓力造成的移動，而不只是自然流動。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":9},{"front":"stable ink","meaning":"穩定墨水","examples":[{"en":"A stable ink had been developed by 400 A.D.","zh":"到公元400年，穩定墨水已被開發出來。"},{"en":"Stable ink is ink that keeps its colour and works reliably over time.","zh":"stable ink 是能長時間保持顏色並可靠使用的墨水。"},{"en":"Schools need stable ink for certificates that must remain readable for years.","zh":"學校需要穩定墨水來製作必須多年仍可閱讀的證書。"},{"en":"If ink is stable, documents are less likely to fade or become unclear quickly.","zh":"如果墨水穩定，文件就較不容易迅速褪色或變得不清楚。"},{"en":"The phrase highlights durability and reliability.","zh":"這個短語強調耐久性和可靠性。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":10},{"front":"iron salts","meaning":"鐵鹽","examples":[{"en":"The stable ink was made from iron salts, nutgalls and gum.","zh":"這種穩定墨水由鐵鹽、沒食子和樹膠製成。"},{"en":"Iron salts are chemical compounds containing iron used in some traditional inks.","zh":"iron salts 是含鐵的化合物，用於某些傳統墨水。"},{"en":"A chemistry teacher may explain iron salts when discussing old ink formulas.","zh":"化學老師在討論舊墨水配方時，可能解釋鐵鹽。"},{"en":"If iron salts react with other ingredients, they can help produce dark writing ink.","zh":"如果鐵鹽與其他成分反應，它們可以幫助產生深色書寫墨水。"},{"en":"The phrase names one chemical ingredient in the ink formula.","zh":"這個短語指出墨水配方中的一種化學成分。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":10},{"front":"nutgalls","meaning":"沒食子","examples":[{"en":"Nutgalls were used in the formula for stable ink.","zh":"沒食子被用於穩定墨水的配方中。"},{"en":"Nutgalls are growths on plants caused by insects, traditionally used to make ink.","zh":"nutgalls 是植物上由昆蟲造成的瘤狀物，傳統上用來製墨。"},{"en":"Old ink makers collected nutgalls because they contained useful chemicals.","zh":"舊時製墨者收集沒食子，因為其中含有有用化學物質。"},{"en":"If nutgalls are mixed with iron salts, they can help create dark ink.","zh":"如果沒食子與鐵鹽混合，它們可以幫助製造深色墨水。"},{"en":"The word refers to a natural ingredient, not ordinary nuts for eating.","zh":"這個字指天然材料，而不是普通可食用果仁。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":10},{"front":"gum","meaning":"樹膠","examples":[{"en":"Gum was one ingredient in stable ink.","zh":"樹膠是穩定墨水的一種成分。"},{"en":"Gum is a sticky natural substance that can help bind materials together.","zh":"gum 是一種黏性的天然物質，可以幫助把材料結合在一起。"},{"en":"Traditional paints may use gum to hold colour particles in place.","zh":"傳統顏料可能使用樹膠來固定顏色粒子。"},{"en":"If gum is added to ink, it can help the mixture stick to paper.","zh":"如果樹膠被加入墨水，它可以幫助混合物附着在紙上。"},{"en":"The word here means a binding material, not chewing gum.","zh":"這裏的 gum 指黏合材料，而不是口香糖。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":10},{"front":"basic formula","meaning":"基本配方","examples":[{"en":"This basic formula remained in use for centuries.","zh":"這個基本配方沿用了數百年。"},{"en":"A basic formula is a simple set of ingredients or steps used to make something.","zh":"basic formula 是用來製作某物的一套簡單成分或步驟。"},{"en":"A bakery may keep the same basic formula for bread but change toppings.","zh":"麵包店可能保持同一個麵包基本配方，但改變配料。"},{"en":"If a basic formula works well, people may continue using it for a long time.","zh":"如果基本配方效果良好，人們可能長時間繼續使用。"},{"en":"The phrase points to the core recipe or method.","zh":"這個短語指出核心配方或方法。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":10},{"front":"remain in use for centuries","meaning":"沿用數百年","examples":[{"en":"The ink formula remained in use for centuries.","zh":"這個墨水配方沿用數百年。"},{"en":"To remain in use for centuries means to continue being used for hundreds of years.","zh":"remain in use for centuries 指繼續被使用數百年。"},{"en":"Some traditional farming tools remained in use for centuries because they were simple and reliable.","zh":"一些傳統農具沿用數百年，因為它們簡單可靠。"},{"en":"If an ink formula remained in use for centuries, it must have worked well enough for many generations.","zh":"如果一個墨水配方沿用數百年，它必定對許多世代都足夠有效。"},{"en":"The phrase highlights long-lasting usefulness.","zh":"這個短語強調長期有用。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":10},{"front":"first applied to paper","meaning":"最初塗在紙上時","examples":[{"en":"The ink was bluish-black when first applied to paper.","zh":"這種墨最初塗在紙上時呈藍黑色。"},{"en":"First applied to paper means when the ink was first put onto the paper surface.","zh":"first applied to paper 指墨水第一次被塗到紙面上時。"},{"en":"Paint may look lighter when first applied to paper but darker after drying.","zh":"顏料最初塗在紙上時可能較淡，但乾後變深。"},{"en":"If ink changes colour after being first applied to paper, readers may see different colours over time.","zh":"如果墨水最初塗在紙上後會變色，讀者隨時間可能看見不同顏色。"},{"en":"The phrase describes the first moment of contact between ink and paper.","zh":"這個短語描述墨水與紙張首次接觸的一刻。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":10},{"front":"bluish-black","meaning":"藍黑色","examples":[{"en":"The ink was bluish-black when first applied to paper.","zh":"這種墨最初塗在紙上時是藍黑色。"},{"en":"Bluish-black means very dark, but with a slight blue colour.","zh":"bluish-black 指非常深色，但帶有少許藍色。"},{"en":"A bruise may look bluish-black before it slowly fades.","zh":"瘀傷在慢慢消退前可能看起來是藍黑色。"},{"en":"If ink is bluish-black at first, it may later darken or fade into another colour.","zh":"如果墨水起初是藍黑色，它之後可能變深或褪成另一種顏色。"},{"en":"The phrase describes a colour between blue and black.","zh":"這個短語描述介乎藍色與黑色之間的顏色。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":10},{"front":"rapidly turn into","meaning":"迅速變成","examples":[{"en":"The ink rapidly turned into a darker black.","zh":"這種墨迅速變成更深的黑色。"},{"en":"To rapidly turn into something means to change quickly into another form, colour, or state.","zh":"rapidly turn into 某物，指快速變成另一種形式、顏色或狀態。"},{"en":"Rain clouds can rapidly turn into a storm during summer.","zh":"夏天時，雨雲可以迅速變成暴風雨。"},{"en":"If ink rapidly turns into darker black, the colour changes soon after writing.","zh":"如果墨水迅速變成更深黑色，顏色就在書寫後不久改變。"},{"en":"The phrase stresses quick transformation.","zh":"這個短語強調快速轉變。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":10},{"front":"over the years","meaning":"多年以來","examples":[{"en":"Over the years, the ink faded to dull brown.","zh":"多年以來，這種墨褪成暗啡色。"},{"en":"Over the years means gradually during many years.","zh":"over the years 指在很多年中逐漸發生。"},{"en":"Over the years, a teacher may collect hundreds of useful examples.","zh":"多年以來，老師可能收集數百個有用例子。"},{"en":"If ink changes over the years, old documents may look different from when they were written.","zh":"如果墨水多年以來有所改變，舊文件可能看起來與剛寫成時不同。"},{"en":"The phrase shows slow change across a long period.","zh":"這個短語顯示長時間中的緩慢變化。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":10},{"front":"fade to","meaning":"褪成","examples":[{"en":"The ink faded to a familiar dull brown colour.","zh":"這種墨褪成熟悉的暗啡色。"},{"en":"To fade to a colour means to slowly lose strength and become that colour.","zh":"fade to 某顏色，指慢慢失去原本強度並變成該顏色。"},{"en":"A black T-shirt may fade to grey after many washes.","zh":"黑色T恤洗很多次後可能褪成灰色。"},{"en":"If old ink fades to brown, documents may still be readable but look aged.","zh":"如果舊墨褪成啡色，文件可能仍可閱讀，但看起來老舊。"},{"en":"The phrase describes gradual colour change caused by time or exposure.","zh":"這個短語描述由時間或暴露造成的逐漸變色。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":10},{"front":"dull brown colour","meaning":"暗啡色","examples":[{"en":"Old ink often becomes a dull brown colour.","zh":"舊墨水常變成暗啡色。"},{"en":"Dull brown colour means a brown shade that is not bright or shiny.","zh":"dull brown colour 指不鮮亮、不閃亮的啡色。"},{"en":"Old paper may have a dull brown colour after years in storage.","zh":"舊紙張存放多年後可能呈暗啡色。"},{"en":"If ink fades to a dull brown colour, the document may look antique.","zh":"如果墨水褪成暗啡色，文件可能看起來古舊。"},{"en":"The phrase describes a muted aged colour.","zh":"這個短語描述一種暗淡而老舊的顏色。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":11},{"front":"commonly seen in","meaning":"常見於……","examples":[{"en":"This colour is commonly seen in old documents.","zh":"這種顏色常見於舊文件。"},{"en":"Commonly seen in something means often found or noticed there.","zh":"commonly seen in 某處，指經常在那裏被找到或注意到。"},{"en":"Bright warning signs are commonly seen in construction sites.","zh":"鮮明警告標誌常見於建築工地。"},{"en":"If dull brown ink is commonly seen in old documents, it may be the result of ageing.","zh":"如果暗啡色墨水常見於舊文件，這可能是老化的結果。"},{"en":"The phrase describes something usual in a particular place or context.","zh":"這個短語描述某事物在特定地方或語境中很常見。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":11},{"front":"old documents","meaning":"舊文件","examples":[{"en":"Dull brown ink is commonly seen in old documents.","zh":"暗啡色墨水常見於舊文件。"},{"en":"Old documents are written or printed records from the past.","zh":"old documents 是來自過去的書面或印刷記錄。"},{"en":"Libraries keep old documents in special rooms to protect them from light and moisture.","zh":"圖書館把舊文件存放在特別房間，以防光線和濕氣破壞。"},{"en":"If old documents fade, historians may need special tools to read them.","zh":"如果舊文件褪色，歷史學家可能需要特殊工具閱讀。"},{"en":"The phrase refers to aged records, not just documents that are no longer useful.","zh":"這個短語指年代久遠的記錄，而不只是已沒有用的文件。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":11},{"front":"wood-fibre paper","meaning":"木纖維紙","examples":[{"en":"Wood-fibre paper was invented in China in 105 A.D.","zh":"木纖維紙於公元105年在中國被發明。"},{"en":"Wood-fibre paper is paper made from fibres taken from wood or plant material.","zh":"wood-fibre paper 是由木材或植物材料中的纖維製成的紙。"},{"en":"Most modern notebooks use paper related to wood-fibre paper.","zh":"大多數現代筆記本使用與木纖維紙相關的紙張。"},{"en":"If wood-fibre paper can be made cheaply, writing materials become more widely available.","zh":"如果木纖維紙可以低成本製造，書寫材料就能更廣泛取得。"},{"en":"The phrase names an important kind of paper in writing history.","zh":"這個短語指出書寫歷史中一種重要紙張。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":11},{"front":"keep the process secret","meaning":"將工藝保密","examples":[{"en":"The Chinese kept the papermaking process secret.","zh":"中國人將造紙工藝保密。"},{"en":"To keep the process secret means to prevent others from learning how something is made.","zh":"keep the process secret 指阻止他人學會某物的製作方法。"},{"en":"A bakery may keep the process secret so competitors cannot copy its recipe.","zh":"麵包店可能將工藝保密，使競爭者不能複製其配方。"},{"en":"If inventors keep the process secret, the technology may spread more slowly.","zh":"如果發明者將工藝保密，技術傳播可能較慢。"},{"en":"The phrase links secrecy with control over knowledge.","zh":"這個短語把保密與控制知識連繫起來。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":11},{"front":"knowledge of it reached","meaning":"關於它的知識傳到……","examples":[{"en":"Knowledge of wood-fibre papermaking reached Japan around 700 A.D.","zh":"關於木纖維造紙的知識大約在公元700年傳到日本。"},{"en":"Knowledge of it reached a place means information about the method arrived there.","zh":"knowledge of it reached 某地，指有關方法的知識到達該地。"},{"en":"Knowledge of the new farming method reached nearby villages through travelling workers.","zh":"關於新耕作方法的知識透過流動工人傳到附近村莊。"},{"en":"If knowledge of papermaking reached another country, people there could begin making paper too.","zh":"如果關於造紙的知識傳到另一個國家，當地人也可以開始造紙。"},{"en":"The phrase describes the spread of know-how, not the movement of one object.","zh":"這個短語描述技術知識的傳播，而不是單一物件的移動。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":11},{"front":"be brought to","meaning":"被帶到……","examples":[{"en":"Papermaking knowledge was brought to Spain by the Arabs.","zh":"造紙知識由阿拉伯人帶到西班牙。"},{"en":"To be brought to a place means to be carried, introduced, or transferred there.","zh":"be brought to 某地，意思是被攜帶、引入或轉移到該地。"},{"en":"Tea was brought to many countries through trade routes.","zh":"茶透過貿易路線被帶到許多國家。"},{"en":"If a technology is brought to a new region, local people may adapt it to their needs.","zh":"如果一項技術被帶到新地區，當地人可能按需要改造它。"},{"en":"The phrase describes arrival through people, trade, or contact.","zh":"這個短語描述透過人、貿易或接觸而到達。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":11},{"front":"not widely used throughout","meaning":"未在……廣泛使用","examples":[{"en":"Paper was not widely used throughout Europe until the late 14th century.","zh":"紙張直到14世紀末才在歐洲廣泛使用。"},{"en":"Not widely used throughout a place means not commonly used across the whole area.","zh":"not widely used throughout 某地，指未在整個地區普遍使用。"},{"en":"Electric cars were not widely used throughout the city until charging stations increased.","zh":"電動車直到充電站增加後，才在全市廣泛使用。"},{"en":"If paper was not widely used throughout Europe, many writers still depended on other materials.","zh":"如果紙張未在歐洲廣泛使用，許多書寫者仍依賴其他材料。"},{"en":"The phrase describes limited spread across a region.","zh":"這個短語描述某物在一個地區中的傳播有限。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":11},{"front":"throughout Europe","meaning":"遍及歐洲","examples":[{"en":"Paper was not widely used throughout Europe for many centuries.","zh":"紙張在許多世紀中未遍及歐洲廣泛使用。"},{"en":"Throughout Europe means across many or all parts of Europe.","zh":"throughout Europe 指橫跨歐洲許多或所有地方。"},{"en":"Rail networks connect cities throughout Europe.","zh":"鐵路網絡連接遍及歐洲的城市。"},{"en":"If paper spread throughout Europe, writing and printing could become easier across the region.","zh":"如果紙張遍及歐洲傳播，整個地區的書寫和印刷都會變得更容易。"},{"en":"The phrase describes a broad geographical range.","zh":"這個短語描述廣泛地理範圍。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":11},{"front":"paper mills","meaning":"造紙廠","examples":[{"en":"Paper mills were built in Europe in the late 14th century.","zh":"造紙廠於14世紀末在歐洲建成。"},{"en":"Paper mills are factories or workshops where paper is made.","zh":"paper mills 是製造紙張的工廠或作坊。"},{"en":"A town with a river may build paper mills because water helps power the process.","zh":"有河流的城鎮可能建造造紙廠，因為水能幫助推動工序。"},{"en":"If paper mills increase, paper becomes easier to obtain and cheaper to use.","zh":"如果造紙廠增加，紙張就會更容易取得並更便宜使用。"},{"en":"The phrase refers to production sites, not shops that sell paper.","zh":"這個短語指生產地點，而不是售賣紙張的商店。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":11},{"front":"the late 14th century","meaning":"14世紀末","examples":[{"en":"Paper became more common in Europe in the late 14th century.","zh":"紙張在14世紀末於歐洲變得更常見。"},{"en":"The late 14th century means the later part of the 1300s.","zh":"the late 14th century 指1300年代後期。"},{"en":"A castle built in the late 14th century was built near the end of the 1300s.","zh":"一座建於14世紀末的城堡，是在1300年代接近末期建成。"},{"en":"If paper mills appeared in the late 14th century, paper use expanded during that period.","zh":"如果造紙廠在14世紀末出現，紙張使用就在該時期擴大。"},{"en":"The phrase places an event in a specific historical period.","zh":"這個短語把事件放在特定歷史時期中。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":11},{"front":"dominate for the longest period","meaning":"佔主導地位最長時間","examples":[{"en":"The quill pen dominated for the longest period in history.","zh":"羽毛筆在歷史上佔主導地位最長時間。"},{"en":"To dominate for the longest period means to remain the most important or common for the greatest length of time.","zh":"dominate for the longest period 指在最長時間內保持最重要或最常用地位。"},{"en":"In one school, paper textbooks may dominate for the longest period before tablets become common.","zh":"在一間學校中，紙本課本可能在平板電腦普及前佔主導地位最長時間。"},{"en":"If quill pens dominated for the longest period, generations of writers depended on them.","zh":"如果羽毛筆佔主導地位最長時間，多個世代的書寫者都依賴它們。"},{"en":"The phrase stresses long-term importance compared with other tools.","zh":"這個短語強調相較其他工具的長期重要性。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":12},{"front":"over one thousand years","meaning":"超過一千年","examples":[{"en":"The quill pen dominated writing for over one thousand years.","zh":"羽毛筆主導書寫超過一千年。"},{"en":"Over one thousand years means more than a thousand years.","zh":"over one thousand years 指多於一千年。"},{"en":"Some temples have stood for over one thousand years because they were carefully maintained.","zh":"有些寺廟因被小心維護而屹立超過一千年。"},{"en":"If a writing tool lasts over one thousand years, it must be practical and widely accepted.","zh":"如果一種書寫工具沿用超過一千年，它必定實用並被廣泛接受。"},{"en":"The phrase indicates an extremely long historical period.","zh":"這個短語表示極長的歷史時期。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":12},{"front":"quill pen","meaning":"羽毛筆","examples":[{"en":"The quill pen was made from a bird feather.","zh":"羽毛筆由鳥羽毛製成。"},{"en":"A quill pen is a writing pen made from the hollow feather of a bird.","zh":"quill pen 是由鳥類空心羽毛製成的書寫筆。"},{"en":"Historical films often show writers dipping a quill pen into ink.","zh":"歷史電影常展示書寫者把羽毛筆蘸入墨水中。"},{"en":"If a quill pen becomes blunt, the writer must cut and sharpen it again.","zh":"如果羽毛筆變鈍，書寫者必須再次切削和削尖。"},{"en":"The phrase names the main writing tool used for many centuries before modern pens.","zh":"這個短語指出現代筆之前沿用多個世紀的主要書寫工具。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":12},{"front":"introduced around","meaning":"大約在……被引入","examples":[{"en":"The quill pen was introduced around 700 A.D.","zh":"羽毛筆大約在公元700年被引入。"},{"en":"Introduced around a time means first brought into use at about that time.","zh":"introduced around 某時間，指大約在那時首次被使用。"},{"en":"The new school uniform was introduced around the beginning of the term.","zh":"新校服大約在學期開始時被引入。"},{"en":"If quill pens were introduced around 700 A.D., they became part of medieval writing culture.","zh":"如果羽毛筆大約在公元700年被引入，它們就成為中世紀書寫文化的一部分。"},{"en":"The phrase gives an approximate date for the start of use.","zh":"這個短語提供開始使用的大概日期。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":12},{"front":"made from a bird feather","meaning":"由鳥羽毛製成","examples":[{"en":"The quill was made from a bird feather.","zh":"羽毛筆由鳥羽毛製成。"},{"en":"Made from a bird feather means produced using a feather as the main material.","zh":"made from a bird feather 指以羽毛作為主要材料製成。"},{"en":"A craft decoration may be made from a bird feather, thread, and paper.","zh":"手工裝飾可能由鳥羽毛、線和紙製成。"},{"en":"If a pen is made from a bird feather, the hollow shaft can hold or guide ink.","zh":"如果一支筆由鳥羽毛製成，空心羽軸就可以盛載或引導墨水。"},{"en":"The phrase identifies the natural source of the object.","zh":"這個短語指出物件的天然來源。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":12},{"front":"the strongest quills","meaning":"最堅韌的羽毛筆","examples":[{"en":"The strongest quills came from the left wings of living birds.","zh":"最堅韌的羽毛筆來自活鳥左翼。"},{"en":"The strongest quills are the firmest and most durable feather pens.","zh":"the strongest quills 是最堅硬和最耐用的羽毛筆。"},{"en":"A writer would prefer the strongest quills because they lasted longer and wrote better.","zh":"書寫者會偏好最堅韌的羽毛筆，因為它們更耐用並更好書寫。"},{"en":"If the strongest quills came from certain feathers, not every bird feather was equally useful.","zh":"如果最堅韌的羽毛筆來自特定羽毛，並非每根鳥羽毛都同樣有用。"},{"en":"The phrase compares quills by strength and quality.","zh":"這個短語按強度和品質比較羽毛筆。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":12},{"front":"outer feathers","meaning":"外層羽毛","examples":[{"en":"The strongest quills were the five outer feathers.","zh":"最堅韌的羽毛筆是五根外層羽毛。"},{"en":"Outer feathers are feathers located on the outside edge of a bird’s wing.","zh":"outer feathers 是位於鳥翼外側邊緣的羽毛。"},{"en":"A bird’s outer feathers help with flight and may be stronger than smaller inner feathers.","zh":"鳥的外層羽毛幫助飛行，可能比內側較小羽毛更堅硬。"},{"en":"If outer feathers are stronger, they are better suited for making quill pens.","zh":"如果外層羽毛較堅韌，它們就更適合製作羽毛筆。"},{"en":"The phrase identifies a specific part of a bird’s wing.","zh":"這個短語指出鳥翼的特定部分。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":12},{"front":"taken from","meaning":"取自","examples":[{"en":"The feathers were taken from the left wings of living birds.","zh":"這些羽毛取自活鳥左翼。"},{"en":"Taken from means removed or obtained from a particular source.","zh":"taken from 指從特定來源移除或取得。"},{"en":"A quotation taken from a book should be copied accurately.","zh":"取自書本的引用應該準確抄錄。"},{"en":"If quills are taken from bird wings, the material comes directly from animals.","zh":"如果羽毛筆取自鳥翼，材料就直接來自動物。"},{"en":"The phrase tells us the source of something.","zh":"這個短語告訴我們某物的來源。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":12},{"front":"living birds","meaning":"活鳥","examples":[{"en":"The strongest quills came from living birds.","zh":"最堅韌的羽毛筆來自活鳥。"},{"en":"Living birds are birds that are alive, not dead or preserved.","zh":"living birds 是仍然活着的鳥，而不是死亡或標本鳥。"},{"en":"A wildlife centre protects living birds that cannot survive safely in the wild.","zh":"野生動物中心保護無法安全在野外生存的活鳥。"},{"en":"If feathers were taken from living birds, the process involved real animals, not fallen feathers only.","zh":"如果羽毛取自活鳥，過程涉及真正動物，而不只是撿起掉落羽毛。"},{"en":"The phrase clarifies the condition of the birds when the feathers were obtained.","zh":"這個短語說明取得羽毛時鳥的狀態。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":12},{"front":"be favoured","meaning":"受偏愛；較常被選用","examples":[{"en":"The left wing was favoured by right-handed writers.","zh":"左翼羽毛受右撇子書寫者偏愛。"},{"en":"To be favoured means to be preferred or chosen more often.","zh":"be favoured 指被偏好或較常被選擇。"},{"en":"Online lessons may be favoured by students who live far from school.","zh":"住得離學校很遠的學生可能較偏好網課。"},{"en":"If left-wing feathers were favoured, their curve probably made writing easier.","zh":"如果左翼羽毛受偏愛，其彎曲方向大概令書寫更容易。"},{"en":"The phrase shows preference based on usefulness or convenience.","zh":"這個短語顯示基於實用性或方便性的偏好。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":12},{"front":"curve outward and away","meaning":"向外並遠離方向彎曲","examples":[{"en":"The feathers curved outward and away from a right-handed writer.","zh":"這些羽毛向外並遠離右撇子書寫者的方向彎曲。"},{"en":"To curve outward and away means to bend away from the person or central position.","zh":"curve outward and away 指向外並遠離某人或中心位置彎曲。"},{"en":"A desk lamp arm can curve outward and away so it does not block the page.","zh":"書枱燈的支架可以向外並遠離方向彎曲，使它不阻擋頁面。"},{"en":"If a quill curves outward and away, it may not interfere with the writer’s hand.","zh":"如果羽毛筆向外並遠離方向彎曲，它可能不會妨礙書寫者的手。"},{"en":"The phrase describes direction and shape.","zh":"這個短語描述方向和形狀。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":12},{"front":"right-handed writer","meaning":"右撇子書寫者","examples":[{"en":"The left-wing feather suited a right-handed writer.","zh":"左翼羽毛適合右撇子書寫者。"},{"en":"A right-handed writer is someone who writes mainly with their right hand.","zh":"right-handed writer 是主要用右手書寫的人。"},{"en":"A right-handed writer may place the paper slightly to the left for comfort.","zh":"右撇子書寫者可能把紙稍微放左一點，以便更舒服。"},{"en":"If a quill curves away from a right-handed writer, writing becomes less awkward.","zh":"如果羽毛筆向遠離右撇子書寫者的方向彎曲，書寫就較不彆扭。"},{"en":"The phrase identifies the writer by writing hand.","zh":"這個短語按書寫用手辨認書寫者。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":13},{"front":"goose feathers","meaning":"鵝毛","examples":[{"en":"Goose feathers were the most common quills.","zh":"鵝毛是最常見的羽毛筆材料。"},{"en":"Goose feathers are feathers from geese, often large and strong enough for quill pens.","zh":"goose feathers 是來自鵝的羽毛，通常大而堅韌，足以製作羽毛筆。"},{"en":"A farm with many geese could provide goose feathers for writing tools.","zh":"有很多鵝的農場可以提供鵝毛作書寫工具材料。"},{"en":"If goose feathers were common, they were likely cheaper and easier to obtain.","zh":"如果鵝毛很常見，它們很可能較便宜且較易取得。"},{"en":"The phrase names the usual material for quill pens.","zh":"這個短語指出羽毛筆的常用材料。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":13},{"front":"swan feathers","meaning":"天鵝羽毛","examples":[{"en":"Swan feathers were scarcer and more expensive.","zh":"天鵝羽毛較稀少且較昂貴。"},{"en":"Swan feathers are feathers from swans, large water birds often seen as graceful.","zh":"swan feathers 是來自天鵝這種大型水鳥的羽毛，天鵝常被視為優雅。"},{"en":"A fine quill made from swan feathers may have been used for special writing.","zh":"由天鵝羽毛製成的精美羽毛筆可能用於特別書寫。"},{"en":"If swan feathers were scarce, only wealthier writers might afford them.","zh":"如果天鵝羽毛稀少，可能只有較富裕的書寫者能負擔。"},{"en":"The phrase identifies a rarer, higher-status quill material.","zh":"這個短語指出較罕有、較高級的羽毛筆材料。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":13},{"front":"scarce and expensive","meaning":"稀少而昂貴","examples":[{"en":"Swan feathers were scarcer and more expensive than goose feathers.","zh":"天鵝羽毛比鵝毛更稀少而昂貴。"},{"en":"Scarce and expensive means hard to find and costly to buy.","zh":"scarce and expensive 指難以找到並且購買成本高。"},{"en":"Fresh fruit can become scarce and expensive after a storm damages farms.","zh":"風暴破壞農田後，新鮮水果可能變得稀少而昂貴。"},{"en":"If a writing material is scarce and expensive, ordinary people may use cheaper alternatives.","zh":"如果書寫材料稀少而昂貴，普通人可能使用較便宜替代品。"},{"en":"The phrase connects limited supply with high price.","zh":"這個短語把供應有限與高價格連繫起來。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":13},{"front":"premium grade","meaning":"高級品質","examples":[{"en":"Swan feathers were considered premium grade.","zh":"天鵝羽毛被視為高級品質。"},{"en":"Premium grade means higher quality than ordinary versions.","zh":"premium grade 指品質高於普通版本。"},{"en":"A shop may sell premium grade paper for formal certificates.","zh":"商店可能出售高級品質紙張，用於正式證書。"},{"en":"If swan feathers were premium grade, writers valued them for quality, not just appearance.","zh":"如果天鵝羽毛屬高級品質，書寫者重視的是其質素，而不只是外觀。"},{"en":"The phrase is often used to mark a superior class of material or product.","zh":"這個短語常用來標示材料或產品的較高級別。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":13},{"front":"fine lines","meaning":"細線","examples":[{"en":"Crow feathers were best for making fine lines.","zh":"烏鴉羽毛最適合畫細線。"},{"en":"Fine lines are thin, delicate lines made by a sharp or narrow writing tip.","zh":"fine lines 是由尖細書寫端製成的幼細精緻線條。"},{"en":"An artist uses fine lines to draw small details on a face.","zh":"藝術家使用細線畫出面部上的小細節。"},{"en":"If a feather can make fine lines, it is useful for small handwriting or detailed decoration.","zh":"如果羽毛可以畫出細線，它就適合小字或細緻裝飾。"},{"en":"The phrase describes line thickness and precision.","zh":"這個短語描述線條粗幼和精準度。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":13},{"front":"crow feathers","meaning":"烏鴉羽毛","examples":[{"en":"Crow feathers were best for making fine lines.","zh":"烏鴉羽毛最適合畫細線。"},{"en":"Crow feathers are feathers from crows, smaller birds with dark feathers.","zh":"crow feathers 是來自烏鴉這種有深色羽毛的小型鳥類的羽毛。"},{"en":"A calligrapher might choose crow feathers when very thin writing is needed.","zh":"當需要非常幼細書寫時，書法家可能選擇烏鴉羽毛。"},{"en":"If crow feathers make fine lines, they are useful for detail rather than broad writing.","zh":"如果烏鴉羽毛能畫細線，它們就適合細節而不是粗大書寫。"},{"en":"The phrase names a specific bird feather used for delicate work.","zh":"這個短語指出用於精細工作的特定鳥羽毛。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":13},{"front":"feathers of the eagle, owl, hawk, and turkey","meaning":"鷹、貓頭鷹、隼和火雞的羽毛","examples":[{"en":"Feathers of the eagle, owl, hawk, and turkey were also used for writing.","zh":"鷹、貓頭鷹、隼和火雞的羽毛也被用於書寫。"},{"en":"Feathers of the eagle, owl, hawk, and turkey are bird feathers from several species used as quill materials.","zh":"feathers of the eagle, owl, hawk, and turkey 是來自幾種鳥類、可用作羽毛筆材料的羽毛。"},{"en":"A museum display may compare feathers of the eagle, owl, hawk, and turkey to show different writing tools.","zh":"博物館展覽可能比較鷹、貓頭鷹、隼和火雞的羽毛，以展示不同書寫工具。"},{"en":"If many bird feathers were used, writers could choose materials based on size, strength, and line quality.","zh":"如果許多鳥類羽毛都可使用，書寫者就能按大小、強度和線條質素選擇材料。"},{"en":"The phrase shows that quill pens came from several kinds of birds.","zh":"這個短語顯示羽毛筆來自多種鳥類。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":13},{"front":"disadvantages associated with","meaning":"與……相關的缺點","examples":[{"en":"There were disadvantages associated with the use of quill pens.","zh":"使用羽毛筆有一些相關缺點。"},{"en":"Disadvantages associated with something are problems or drawbacks connected with it.","zh":"disadvantages associated with 某事，指與其相關的問題或不利之處。"},{"en":"There are disadvantages associated with living far from school, such as long travel time.","zh":"住得離學校很遠有相關缺點，例如通勤時間長。"},{"en":"If disadvantages are associated with a tool, people may eventually seek a better replacement.","zh":"如果一種工具有相關缺點，人們最終可能尋找更好的替代品。"},{"en":"The phrase introduces negative features linked to a choice or method.","zh":"這個短語引出與某選擇或方法相關的負面特徵。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":13},{"front":"the use of quill pens","meaning":"使用羽毛筆","examples":[{"en":"The use of quill pens involved lengthy preparation.","zh":"使用羽毛筆涉及漫長準備。"},{"en":"The use of quill pens means writing with feather pens and ink.","zh":"the use of quill pens 指用羽毛筆和墨水書寫。"},{"en":"The use of quill pens required writers to dip, sharpen, and care for the nib.","zh":"使用羽毛筆要求書寫者蘸墨、削尖並照顧筆尖。"},{"en":"If the use of quill pens was slow, writers welcomed tools that reduced preparation time.","zh":"如果使用羽毛筆很慢，書寫者就會歡迎能減少準備時間的工具。"},{"en":"The phrase refers to the practice of writing with quills, not just owning them.","zh":"這個短語指用羽毛筆書寫的做法，而不只是擁有羽毛筆。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":13},{"front":"lengthy preparation time","meaning":"漫長準備時間","examples":[{"en":"Quill pens required a lengthy preparation time.","zh":"羽毛筆需要漫長準備時間。"},{"en":"Lengthy preparation time means a long period needed before something is ready to use.","zh":"lengthy preparation time 指某物可使用前需要很長時間準備。"},{"en":"A school play has a lengthy preparation time because students must rehearse and make costumes.","zh":"校園話劇有漫長準備時間，因為學生必須排練和製作服裝。"},{"en":"If a writing tool needs lengthy preparation time, quick notes become difficult.","zh":"如果書寫工具需要漫長準備時間，快速筆記就會變得困難。"},{"en":"The phrase explains why a process can feel inconvenient.","zh":"這個短語解釋為何某過程會令人覺得不方便。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":13},{"front":"sheets of parchment","meaning":"羊皮紙張","examples":[{"en":"Early European sheets of parchment were made from animal skins.","zh":"早期歐洲羊皮紙張由動物皮製成。"},{"en":"Sheets of parchment are flat pieces of prepared animal skin used for writing.","zh":"sheets of parchment 是經處理後用於書寫的平面動物皮。"},{"en":"A medieval manuscript might be written on sheets of parchment.","zh":"中世紀手稿可能寫在羊皮紙張上。"},{"en":"If sheets of parchment were costly to prepare, writers had to use them carefully.","zh":"如果羊皮紙張製作成本高，書寫者就必須小心使用。"},{"en":"The phrase describes individual writing surfaces made from parchment.","zh":"這個短語描述由羊皮紙製成的一張張書寫表面。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":14},{"front":"animal skins","meaning":"動物皮","examples":[{"en":"Parchment was made from animal skins.","zh":"羊皮紙由動物皮製成。"},{"en":"Animal skins are the hides or outer coverings of animals.","zh":"animal skins 是動物的皮革或外層覆蓋物。"},{"en":"Leather shoes, bags, and parchment can all be made from animal skins.","zh":"皮鞋、皮袋和羊皮紙都可以由動物皮製成。"},{"en":"If writing material comes from animal skins, preparing it requires cleaning and scraping.","zh":"如果書寫材料來自動物皮，製作它就需要清潔和刮削。"},{"en":"The phrase identifies the raw material used to make parchment.","zh":"這個短語指出製作羊皮紙的原材料。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":14},{"front":"require much scraping and cleaning","meaning":"需要大量刮削和清潔","examples":[{"en":"Parchment required much scraping and cleaning.","zh":"羊皮紙需要大量刮削和清潔。"},{"en":"To require much scraping and cleaning means to need a lot of removal and washing before use.","zh":"require much scraping and cleaning 指在使用前需要大量刮除和清洗。"},{"en":"An old wooden table may require much scraping and cleaning before it can be painted.","zh":"舊木枱在上油漆前可能需要大量刮削和清潔。"},{"en":"If parchment requires much scraping and cleaning, preparing writing material takes time and effort.","zh":"如果羊皮紙需要大量刮削和清潔，準備書寫材料就很花時間和力氣。"},{"en":"The phrase explains why parchment production was labour-intensive.","zh":"這個短語解釋為何羊皮紙製作很費工。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":14},{"front":"margins","meaning":"頁邊；邊界","examples":[{"en":"Margins were drawn with lead and a ruler.","zh":"頁邊用鉛和間尺畫出。"},{"en":"Margins are the blank spaces around the edges of a page.","zh":"margins 是頁面邊緣周圍的空白位置。"},{"en":"Teachers may ask students to write comments in the margins of an essay.","zh":"老師可能要求學生在文章頁邊寫評語。"},{"en":"If margins are drawn clearly, writing can stay neat and evenly arranged.","zh":"如果頁邊畫得清楚，書寫就能保持整齊和排列平均。"},{"en":"The word refers to page boundaries, not profit margins in business here.","zh":"這個字在此指頁面邊界，而不是商業中的利潤率。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":14},{"front":"drawn with lead and a ruler","meaning":"用鉛和間尺畫出","examples":[{"en":"Margins were drawn with lead and a ruler.","zh":"頁邊用鉛和間尺畫出。"},{"en":"Drawn with lead and a ruler means marked using a lead tool and a straight measuring edge.","zh":"drawn with lead and a ruler 指用鉛筆類工具和直尺畫線。"},{"en":"A student can draw table lines with a pencil and ruler before writing notes.","zh":"學生可以先用鉛筆和間尺畫表格線，再寫筆記。"},{"en":"If margins are drawn with lead and a ruler, the page layout becomes more orderly.","zh":"如果頁邊用鉛和間尺畫出，頁面布局就會更有秩序。"},{"en":"The phrase describes a careful method for making straight guide lines.","zh":"這個短語描述製作直引導線的仔細方法。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":14},{"front":"sharpen the quill","meaning":"削尖羽毛筆","examples":[{"en":"The writer needed a special knife to sharpen the quill.","zh":"書寫者需要特製小刀來削尖羽毛筆。"},{"en":"To sharpen the quill means to cut the feather tip so it writes clearly again.","zh":"sharpen the quill 指切削羽毛筆尖，使它再次清楚書寫。"},{"en":"A pencil must be sharpened when its point becomes too blunt to write neatly.","zh":"當鉛筆尖太鈍而不能整齊書寫時，就必須削尖。"},{"en":"If writers had to sharpen the quill often, writing took more preparation time.","zh":"如果書寫者必須經常削尖羽毛筆，書寫就需要更多準備時間。"},{"en":"The phrase describes maintenance needed for feather pens.","zh":"這個短語描述羽毛筆所需的保養工作。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":14},{"front":"special knife","meaning":"特製小刀","examples":[{"en":"A special knife was needed to sharpen the quill.","zh":"削尖羽毛筆需要特製小刀。"},{"en":"A special knife is a knife made or chosen for a particular task.","zh":"special knife 是為特定工作而製造或選用的小刀。"},{"en":"A craft worker may use a special knife to cut paper cleanly.","zh":"手工藝人可能使用特製小刀把紙切得整齊。"},{"en":"If quill pens need a special knife, writers must carry extra tools before writing.","zh":"如果羽毛筆需要特製小刀，書寫者在書寫前就必須攜帶額外工具。"},{"en":"The phrase shows that the tool was not just any ordinary knife.","zh":"這個短語顯示該工具不只是普通小刀。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":14},{"front":"the origin of the term","meaning":"某詞語的來源","examples":[{"en":"The special knife was the origin of the term “penknife”.","zh":"這把特製小刀是 “penknife” 一詞的來源。"},{"en":"The origin of the term means the source or beginning of a word or phrase.","zh":"the origin of the term 指一個字或短語的來源或起點。"},{"en":"A teacher may explain the origin of the term “deadline” in a vocabulary lesson.","zh":"老師可能在詞彙課解釋 “deadline” 一詞的來源。"},{"en":"If a word’s origin is linked to an old tool, its history becomes easier to remember.","zh":"如果一個字的來源與舊工具有關，其歷史就更容易記住。"},{"en":"The phrase focuses on where a word came from.","zh":"這個短語重點在於一個詞來自哪裏。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":14},{"front":"penknife","meaning":"小刀；筆刀","examples":[{"en":"The word “penknife” comes from a knife used to sharpen quills.","zh":"“penknife” 這個字來自用來削尖羽毛筆的小刀。"},{"en":"A penknife is a small folding knife, originally associated with preparing pens.","zh":"penknife 是一種小型摺刀，原本與準備筆有關。"},{"en":"Today, a penknife may be used for small tasks such as cutting string or opening packages.","zh":"今天，小刀可用於剪繩或開包裹等小任務。"},{"en":"If the word penknife comes from quill writing, it preserves a piece of writing history.","zh":"如果 penknife 一詞來自羽毛筆書寫，它就保存了一段書寫歷史。"},{"en":"The phrase names a small knife, not a writing pen.","zh":"這個短語指小刀，而不是書寫筆。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":14},{"front":"beneath the writer’s desk","meaning":"在書寫者的書桌下","examples":[{"en":"A coal stove was placed beneath the writer’s desk.","zh":"煤爐被放在書寫者的書桌下。"},{"en":"Beneath the writer’s desk means under the desk used by the person writing.","zh":"beneath the writer’s desk 指在書寫者使用的書桌下面。"},{"en":"A small footrest may be placed beneath a student’s desk for comfort.","zh":"小腳踏可能放在學生書桌下，以增加舒適度。"},{"en":"If a stove was placed beneath the writer’s desk, heat could help dry ink quickly.","zh":"如果煤爐放在書寫者的書桌下，熱力可以幫助墨水迅速變乾。"},{"en":"The phrase identifies the position of an object under the writing area.","zh":"這個短語指出物件位於書寫區域下方的位置。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":14},{"front":"high-top desk","meaning":"高身書桌","examples":[{"en":"The writer used a high-top desk.","zh":"書寫者使用高身書桌。"},{"en":"A high-top desk is a tall desk that may be used while standing or sitting high.","zh":"high-top desk 是較高的書桌，可讓人站着或坐在較高位置使用。"},{"en":"A shop counter can feel like a high-top desk because workers write on a raised surface.","zh":"商店櫃枱可能像高身書桌，因為員工在較高表面書寫。"},{"en":"If a writer used a high-top desk, there was space beneath it for a small stove.","zh":"如果書寫者使用高身書桌，下方就有空間放小煤爐。"},{"en":"The phrase describes the height and design of the writing furniture.","zh":"這個短語描述書寫家具的高度和設計。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":14},{"front":"coal stove","meaning":"煤爐","examples":[{"en":"A coal stove was used to dry the ink quickly.","zh":"煤爐被用來迅速烘乾墨水。"},{"en":"A coal stove is a heating device that burns coal to produce heat.","zh":"coal stove 是燃燒煤以產生熱力的加熱裝置。"},{"en":"Old houses often used coal stoves before modern electric heaters became common.","zh":"在現代電暖爐普及前，舊房子常使用煤爐。"},{"en":"If a coal stove sat under a desk, its heat could help wet ink dry faster.","zh":"如果煤爐放在書桌下，其熱力可以幫助濕墨水更快變乾。"},{"en":"The phrase refers to a heat source, not a cooking tool only.","zh":"這個短語指熱源，而不只是煮食工具。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":15},{"front":"dry the ink","meaning":"使墨水變乾","examples":[{"en":"The coal stove helped dry the ink as fast as possible.","zh":"煤爐幫助墨水盡快變乾。"},{"en":"To dry the ink means to make wet ink become dry and fixed on the surface.","zh":"dry the ink 指令濕墨水變乾並固定在表面。"},{"en":"Students should let the ink dry before closing a notebook.","zh":"學生應該讓墨水變乾，才合上筆記本。"},{"en":"If ink does not dry quickly, it can smudge across the page.","zh":"如果墨水不能迅速變乾，它可能在頁面上被抹花。"},{"en":"The phrase describes an important step after writing with liquid ink.","zh":"這個短語描述用液體墨水書寫後的重要步驟。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":15},{"front":"as fast as possible","meaning":"盡快","examples":[{"en":"The stove dried the ink as fast as possible.","zh":"煤爐盡快把墨水烘乾。"},{"en":"As fast as possible means as quickly as one can manage.","zh":"as fast as possible 指盡一切可能快速地做某事。"},{"en":"Students should leave the building as fast as possible during a fire alarm.","zh":"火警鐘響時，學生應盡快離開大樓。"},{"en":"If ink must dry as fast as possible, heat or absorbent paper may help.","zh":"如果墨水必須盡快變乾，熱力或吸水紙可能有幫助。"},{"en":"The phrase stresses speed and urgency.","zh":"這個短語強調速度和急切性。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":15},{"front":"plant-fibre paper","meaning":"植物纖維紙","examples":[{"en":"Plant-fibre paper became the primary medium for writing.","zh":"植物纖維紙成為主要書寫媒介。"},{"en":"Plant-fibre paper is paper made from fibres taken from plants.","zh":"plant-fibre paper 是由植物纖維製成的紙。"},{"en":"Many notebooks are made from plant-fibre paper because it is light and easy to write on.","zh":"許多筆記本由植物纖維紙製成，因為它輕便且易於書寫。"},{"en":"If plant-fibre paper becomes common, writing can spread beyond expensive materials like parchment.","zh":"如果植物纖維紙變得常見，書寫就能超越羊皮紙等昂貴材料而傳播。"},{"en":"The phrase identifies paper by the material used to make it.","zh":"這個短語按製造材料指出紙張種類。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":15},{"front":"primary medium for writing","meaning":"主要書寫媒介","examples":[{"en":"Plant-fibre paper became the primary medium for writing.","zh":"植物纖維紙成為主要書寫媒介。"},{"en":"The primary medium for writing is the main material or surface people use to write on.","zh":"primary medium for writing 是人們用來書寫的主要材料或表面。"},{"en":"In most classrooms today, paper is still a primary medium for writing notes and tests.","zh":"在今天大多數課室中，紙張仍是寫筆記和測驗的主要書寫媒介。"},{"en":"If paper becomes the primary medium for writing, pens and inks must suit it well.","zh":"如果紙張成為主要書寫媒介，筆和墨水就必須適合它。"},{"en":"The phrase identifies the main writing surface of a period.","zh":"這個短語指出某一時期的主要書寫表面。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":15},{"front":"dramatic invention","meaning":"重大發明","examples":[{"en":"Gutenberg’s dramatic invention changed writing and printing.","zh":"Gutenberg 的重大發明改變了書寫和印刷。"},{"en":"A dramatic invention is an invention that brings a major and noticeable change.","zh":"dramatic invention 是帶來重大而明顯變化的發明。"},{"en":"The smartphone was a dramatic invention because it changed communication, shopping, and work.","zh":"智能手機是一項重大發明，因為它改變了溝通、購物和工作。"},{"en":"If a dramatic invention reduces the cost of books, more people can read.","zh":"如果一項重大發明降低書本成本，更多人就能閱讀。"},{"en":"The phrase stresses the large impact of an invention.","zh":"這個短語強調發明帶來的巨大影響。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":15},{"front":"the printing press","meaning":"印刷機","examples":[{"en":"Johannes Gutenberg invented the printing press with replaceable letters.","zh":"Johannes Gutenberg 發明了使用可替換字母的印刷機。"},{"en":"The printing press is a machine used to print text or images onto paper.","zh":"the printing press 是把文字或圖像印到紙上的機器。"},{"en":"A printing press can produce many copies of the same page faster than handwriting.","zh":"印刷機可以比手寫更快製作同一頁的許多副本。"},{"en":"If the printing press uses movable letters, books can be made more efficiently.","zh":"如果印刷機使用可移動字母，書本就能更有效率地製作。"},{"en":"The phrase names a machine that transformed the spread of written information.","zh":"這個短語指出改變書面資訊傳播方式的機器。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":15},{"front":"replaceable wooden or metal letters","meaning":"可替換的木或金屬活字","examples":[{"en":"The printing press used replaceable wooden or metal letters.","zh":"印刷機使用可替換的木或金屬活字。"},{"en":"Replaceable wooden or metal letters are individual letter blocks that can be moved and reused.","zh":"replaceable wooden or metal letters 是可移動和重複使用的單個字母塊。"},{"en":"A printer could arrange replaceable wooden or metal letters to form a page of text.","zh":"印刷工可以排列可替換的木或金屬活字，組成一頁文字。"},{"en":"If letters are replaceable, one set can print many different words and pages.","zh":"如果字母可以替換，一套活字就能印出許多不同字詞和頁面。"},{"en":"The phrase describes movable type used in early printing.","zh":"這個短語描述早期印刷使用的活字。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":15},{"front":"simpler kinds of printing","meaning":"較簡單的印刷方式","examples":[{"en":"Simpler kinds of printing had been used earlier in China.","zh":"較簡單的印刷方式較早在中國被使用。"},{"en":"Simpler kinds of printing are earlier or less complex methods for copying text or images.","zh":"simpler kinds of printing 是較早或較不複雜的複製文字或圖像方法。"},{"en":"Name stamps are simpler kinds of printing because they press a fixed mark onto a surface.","zh":"名字印章是較簡單的印刷方式，因為它把固定標記壓到表面上。"},{"en":"If simpler kinds of printing existed first, Gutenberg’s machine was part of a longer history.","zh":"如果較簡單的印刷方式先存在，Gutenberg 的機器就是更長歷史的一部分。"},{"en":"The phrase contrasts basic printing methods with more advanced machines.","zh":"這個短語把基本印刷方法與更先進機器作對比。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":15},{"front":"name stamps","meaning":"名字印章","examples":[{"en":"Name stamps were used much earlier in China.","zh":"名字印章很早以前已在中國使用。"},{"en":"Name stamps are small tools that print a person’s name or mark when pressed onto ink and paper.","zh":"name stamps 是小型工具，蘸墨並壓在紙上時可印出個人名字或標記。"},{"en":"A teacher may use a name stamp to mark books quickly.","zh":"老師可能使用名字印章快速標記書本。"},{"en":"If name stamps existed early, people could reproduce personal marks without handwriting each time.","zh":"如果名字印章很早已存在，人們就不用每次手寫也能重複個人標記。"},{"en":"The phrase refers to a simple printing device.","zh":"這個短語指一種簡單印刷工具。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":15},{"front":"find their way to","meaning":"傳入……","examples":[{"en":"Some Chinese printing methods did not find their way to Europe.","zh":"有些中國印刷方法沒有傳入歐洲。"},{"en":"To find their way to a place means to reach or spread there gradually.","zh":"find their way to 某地，指逐漸到達或傳播到那裏。"},{"en":"A local snack may find its way to supermarkets after becoming popular online.","zh":"本地小食在網上走紅後，可能傳入超級市場。"},{"en":"If a technology does not find its way to another region, people there may develop different methods.","zh":"如果一項技術沒有傳入另一地區，當地人可能發展不同方法。"},{"en":"The phrase describes movement or spread, often over time.","zh":"這個短語描述移動或傳播，通常隨時間發生。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":15},{"front":"over subsequent centuries","meaning":"在隨後數個世紀","examples":[{"en":"Over subsequent centuries, many printing technologies developed.","zh":"在隨後數個世紀，許多印刷技術發展起來。"},{"en":"Over subsequent centuries means during the centuries that followed.","zh":"over subsequent centuries 指在之後的多個世紀中。"},{"en":"Over subsequent centuries, small villages grew into large cities.","zh":"在隨後數個世紀，小村莊成長為大城市。"},{"en":"If printing improved over subsequent centuries, Gutenberg’s invention led to later innovations.","zh":"如果印刷在隨後數個世紀改善，Gutenberg 的發明就導致後來創新。"},{"en":"The phrase connects an event with long-term developments after it.","zh":"這個短語把一件事件與之後的長期發展連繫起來。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":16},{"front":"printing technologies","meaning":"印刷技術","examples":[{"en":"Many printing technologies developed from Gutenberg’s machine.","zh":"許多印刷技術由 Gutenberg 的機器發展而來。"},{"en":"Printing technologies are methods, machines, and processes used to reproduce text or images.","zh":"printing technologies 是用來複製文字或圖像的方法、機器和工序。"},{"en":"Offset printing and digital printing are printing technologies used for books and posters.","zh":"柯式印刷和數碼印刷是用於書籍和海報的印刷技術。"},{"en":"If printing technologies improve, information can be copied faster and more cheaply.","zh":"如果印刷技術改良，資訊就能更快和更低成本地被複製。"},{"en":"The phrase covers more than one printing method.","zh":"這個短語涵蓋多於一種印刷方法。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":16},{"front":"offset printing","meaning":"柯式印刷","examples":[{"en":"Offset printing developed from earlier printing technology.","zh":"柯式印刷由較早印刷技術發展而來。"},{"en":"Offset printing is a printing method in which an image is transferred through an intermediate surface before reaching paper.","zh":"offset printing 是一種印刷方法，圖像先經中間表面轉移，再印到紙上。"},{"en":"Many newspapers, magazines, and brochures have been produced by offset printing.","zh":"許多報紙、雜誌和小冊子曾以柯式印刷製作。"},{"en":"If offset printing is efficient, publishers can print large quantities with consistent quality.","zh":"如果柯式印刷有效率，出版社就能以穩定質素大量印刷。"},{"en":"The phrase names a later printing technology, not an ancient writing tool.","zh":"這個短語指出一種後來的印刷技術，而不是古代書寫工具。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":16},{"front":"be developed from","meaning":"由……發展而成","examples":[{"en":"Many printing technologies were developed from Gutenberg’s machine.","zh":"許多印刷技術由 Gutenberg 的機器發展而成。"},{"en":"To be developed from something means to grow out of or be based on an earlier invention or idea.","zh":"be developed from 某物，意思是由較早發明或想法發展出來或以其為基礎。"},{"en":"Modern bicycles were developed from simpler two-wheeled machines.","zh":"現代單車由較簡單的兩輪機器發展而成。"},{"en":"If new printing methods are developed from an older press, the old machine still matters historically.","zh":"如果新印刷方法由舊印刷機發展而成，舊機器在歷史上仍然重要。"},{"en":"The phrase shows origin and improvement.","zh":"這個短語顯示來源和改良。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":16},{"front":"written by hand","meaning":"手寫的","examples":[{"en":"Articles written by hand once resembled printed letters.","zh":"手寫的文章曾經與印刷字母相似。"},{"en":"Written by hand means produced manually with a pen, brush, stylus, or similar tool.","zh":"written by hand 指用筆、毛筆、尖筆或類似工具以人手寫成。"},{"en":"A thank-you card written by hand can feel more personal than a typed message.","zh":"手寫的感謝卡可能比打字訊息更有個人感覺。"},{"en":"If texts written by hand resemble print, readers may find them neat but slower to produce.","zh":"如果手寫文本像印刷字，讀者可能覺得整齊，但製作較慢。"},{"en":"The phrase contrasts handwriting with printing or typing.","zh":"這個短語把手寫與印刷或打字作對比。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":16},{"front":"resemble printed letters","meaning":"與印刷字母相似","examples":[{"en":"Handwritten articles had resembled printed letters.","zh":"手寫文章曾與印刷字母相似。"},{"en":"To resemble printed letters means to look similar to letters made by printing.","zh":"resemble printed letters 指看起來像印刷製成的字母。"},{"en":"A student’s neat handwriting may resemble printed letters because each letter is separate.","zh":"學生整齊的手寫可能與印刷字母相似，因為每個字母都分開。"},{"en":"If handwriting resembles printed letters, it may be easy to read but slower to write.","zh":"如果手寫與印刷字母相似，它可能容易閱讀，但書寫較慢。"},{"en":"The phrase describes visual similarity.","zh":"這個短語描述視覺上的相似。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":16},{"front":"the form of writing","meaning":"書寫形式","examples":[{"en":"Scholars began to change the form of writing.","zh":"學者開始改變書寫形式。"},{"en":"The form of writing means the shape, style, or arrangement of written letters and words.","zh":"the form of writing 指書面字母和字詞的形狀、風格或排列。"},{"en":"Cursive changed the form of writing by connecting letters.","zh":"草書透過連接字母改變了書寫形式。"},{"en":"If the form of writing changes, people may write faster or more beautifully.","zh":"如果書寫形式改變，人們可能寫得更快或更美觀。"},{"en":"The phrase focuses on how writing looks and is produced.","zh":"這個短語重點在於書寫看起來如何及如何產生。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":16},{"front":"capitals and small letters","meaning":"大楷和小楷","examples":[{"en":"Scholars used capitals and small letters in handwriting.","zh":"學者在手寫中使用大楷和小楷。"},{"en":"Capitals and small letters are uppercase and lowercase forms of letters.","zh":"capitals and small letters 是字母的大寫和小寫形式。"},{"en":"Children learn capitals and small letters when they learn to write their names properly.","zh":"孩子學習正確寫自己名字時，會學大楷和小楷。"},{"en":"If writing uses capitals and small letters, readers can see sentence beginnings and names more clearly.","zh":"如果書寫使用大楷和小楷，讀者可以更清楚看見句子開頭和名字。"},{"en":"The phrase describes two letter forms used together.","zh":"這個短語描述兩種字母形式一同使用。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":16},{"front":"with more of a slant","meaning":"帶有更大傾斜度","examples":[{"en":"Writers began writing with more of a slant.","zh":"書寫者開始以更大傾斜度書寫。"},{"en":"With more of a slant means with letters leaning more to one side.","zh":"with more of a slant 指字母向一邊傾斜得更多。"},{"en":"A person writing quickly may write with more of a slant than when writing slowly.","zh":"一個人快速書寫時，可能比慢慢書寫時有更大傾斜度。"},{"en":"If handwriting has more of a slant, the letters may connect more easily.","zh":"如果手寫帶有更大傾斜度，字母可能更容易連接。"},{"en":"The phrase describes the angle of handwriting.","zh":"這個短語描述手寫的角度。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":16},{"front":"connect letters","meaning":"連接字母","examples":[{"en":"Writers began connecting letters in handwriting.","zh":"書寫者開始在手寫中連接字母。"},{"en":"To connect letters means to join letters together while writing.","zh":"connect letters 指書寫時把字母連在一起。"},{"en":"In cursive, children learn to connect letters so words flow across the page.","zh":"在草書中，孩子學習連接字母，使字詞在頁面上流暢延伸。"},{"en":"If writers connect letters, they can often write faster than by lifting the pen after every letter.","zh":"如果書寫者連接字母，通常能比每寫一個字母就提筆更快。"},{"en":"The phrase explains a key feature of cursive handwriting.","zh":"這個短語解釋草書體的一個關鍵特點。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":16},{"front":"gradually","meaning":"逐漸","examples":[{"en":"Gradually, writing became better suited to faster writing.","zh":"書寫逐漸變得更適合快速書寫。"},{"en":"Gradually means slowly and step by step over time.","zh":"gradually 指隨時間慢慢地、一步一步地發生。"},{"en":"A student gradually improves pronunciation by practising a little every day.","zh":"學生透過每天少量練習，逐漸改善發音。"},{"en":"If handwriting changes gradually, people can adapt to new forms without sudden difficulty.","zh":"如果手寫逐漸改變，人們就能適應新形式，而不會突然感到困難。"},{"en":"The word shows slow development rather than immediate change.","zh":"這個字顯示緩慢發展，而不是即時改變。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":16},{"front":"better suited to","meaning":"更適合……","examples":[{"en":"Cursive handwriting was better suited to faster writing.","zh":"草書體更適合快速書寫。"},{"en":"Better suited to something means more appropriate or useful for that purpose.","zh":"better suited to 某事，指對該目的更合適或更有用。"},{"en":"A quiet library is better suited to exam revision than a noisy café.","zh":"安靜圖書館比嘈吵咖啡店更適合考試溫習。"},{"en":"If cursive is better suited to speed, writers can produce long texts more efficiently.","zh":"如果草書更適合速度，書寫者就能更有效率地寫長文。"},{"en":"The phrase shows a stronger match between a method and a need.","zh":"這個短語顯示方法與需要之間有更強配合。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":17},{"front":"writing speed","meaning":"書寫速度","examples":[{"en":"New instruments permitted greater writing speed.","zh":"新工具容許更快書寫速度。"},{"en":"Writing speed is how quickly a person can write words by hand or with a tool.","zh":"writing speed 是一個人用手或工具寫字的速度。"},{"en":"Students often need good writing speed during timed exams.","zh":"學生在限時考試中常需要良好書寫速度。"},{"en":"If writing speed increases, people can copy notes or documents more quickly.","zh":"如果書寫速度提高，人們就能更快抄寫筆記或文件。"},{"en":"The phrase measures speed in producing written text.","zh":"這個短語衡量產生書面文字的速度。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":17},{"front":"permitted by","meaning":"由……所容許","examples":[{"en":"Writing speed was permitted by the new instruments.","zh":"書寫速度由新工具所容許。"},{"en":"Permitted by something means made possible or allowed by it.","zh":"permitted by 某物，意思是由它使某事成為可能或被允許。"},{"en":"Remote learning was permitted by video-call technology during school closures.","zh":"停課期間，視像通話技術使遙距學習成為可能。"},{"en":"If faster writing is permitted by better pens, tool design affects communication.","zh":"如果更快書寫由更好的筆所容許，工具設計就影響溝通。"},{"en":"The phrase shows what enables an action or result.","zh":"這個短語顯示甚麼使某行動或結果成為可能。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":17},{"front":"the credit for inventing","meaning":"發明……的功勞","examples":[{"en":"The credit for inventing cursive handwriting goes to Aldus Manutius.","zh":"發明草書體的功勞歸於 Aldus Manutius。"},{"en":"The credit for inventing something means recognition for creating it.","zh":"the credit for inventing 某物，指創造某物所獲得的認可。"},{"en":"The credit for inventing a useful app usually goes to the team that designed and built it.","zh":"發明有用應用程式的功勞通常歸於設計和製作它的團隊。"},{"en":"If one person receives the credit for inventing a writing style, history links their name to it.","zh":"如果某人獲得發明書寫風格的功勞，歷史就把他的名字與它連繫起來。"},{"en":"The phrase is about recognition, not money.","zh":"這個短語關於認可，而不是金錢。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":17},{"front":"running hand","meaning":"連筆字","examples":[{"en":"Italian running hand was a form of cursive handwriting.","zh":"意大利連筆字是一種草書體。"},{"en":"Running hand is a flowing style of handwriting in which letters are connected for speed.","zh":"running hand 是一種流暢的手寫風格，字母為了速度而相連。"},{"en":"A diary written in running hand may look elegant but difficult for beginners to read.","zh":"以連筆字寫成的日記可能看起來優雅，但初學者較難閱讀。"},{"en":"If running hand connects letters smoothly, writers can write faster than with separate letters.","zh":"如果連筆字順暢連接字母，書寫者就能比寫分開字母更快。"},{"en":"The phrase refers to a cursive writing style.","zh":"這個短語指一種草書手寫風格。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":17},{"front":"cursive handwriting","meaning":"草書體；連筆手寫體","examples":[{"en":"Cursive handwriting connected letters and increased writing speed.","zh":"草書體連接字母並提高書寫速度。"},{"en":"Cursive handwriting is a style of handwriting in which many letters are joined together.","zh":"cursive handwriting 是一種許多字母連在一起的手寫風格。"},{"en":"Some schools teach cursive handwriting so students can write smoothly and quickly.","zh":"有些學校教授草書體，讓學生能順暢快速地書寫。"},{"en":"If cursive handwriting is unclear, readers may struggle even if the writer wrote quickly.","zh":"如果草書體不清楚，即使書寫者寫得快，讀者也可能看得吃力。"},{"en":"The phrase focuses on connected, flowing handwritten letters.","zh":"這個短語重點在於相連而流暢的手寫字母。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":17},{"front":"Roman capitals","meaning":"羅馬大楷字母","examples":[{"en":"Cursive handwriting used Roman capitals and small letters.","zh":"草書體使用羅馬大楷字母和小楷字母。"},{"en":"Roman capitals are uppercase letter forms developed from Roman writing traditions.","zh":"Roman capitals 是由羅馬書寫傳統發展而來的大寫字母形式。"},{"en":"Museum inscriptions often use Roman capitals because they look formal and clear.","zh":"博物館銘文常使用羅馬大楷字母，因為它們看起來正式而清楚。"},{"en":"If handwriting combines Roman capitals with small letters, it can mark sentence beginnings and names.","zh":"如果手寫結合羅馬大楷字母和小楷字母，就能標示句子開頭和名字。"},{"en":"The phrase refers to capital letter shapes, not the capital city of Rome.","zh":"這個短語指大寫字母形態，而不是羅馬這座首都。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":17},{"front":"Aldus Manutius of Venice","meaning":"威尼斯的Aldus Manutius","examples":[{"en":"Aldus Manutius of Venice is credited with inventing Italian running hand.","zh":"威尼斯的 Aldus Manutius 被認為有發明意大利連筆字的功勞。"},{"en":"Aldus Manutius of Venice was a historical figure associated with printing and writing development.","zh":"Aldus Manutius of Venice 是一位與印刷和書寫發展相關的歷史人物。"},{"en":"Students of book history may learn about Aldus Manutius of Venice when studying early printed books.","zh":"書籍史學生研究早期印刷書時，可能學到威尼斯的 Aldus Manutius。"},{"en":"If Aldus Manutius is credited with a writing style, his work influenced how people wrote by hand.","zh":"如果 Aldus Manutius 被認為創造了一種書寫風格，他的工作就影響了人們如何手寫。"},{"en":"The phrase identifies the person and his city.","zh":"這個短語指出人物和他的城市。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":17},{"front":"depart from","meaning":"擺脫；偏離","examples":[{"en":"Aldus Manutius departed from the old set forms.","zh":"Aldus Manutius 擺脫了舊有固定形式。"},{"en":"To depart from something means to move away from an old rule, style, or pattern.","zh":"depart from 某事，意思是離開舊規則、風格或模式。"},{"en":"A teacher may depart from the textbook when students need more practical examples.","zh":"當學生需要更實用例子時，老師可能偏離課本。"},{"en":"If a writer departs from old letter forms, handwriting can become faster and more personal.","zh":"如果書寫者擺脫舊字母形式，手寫就能變得更快和更個人化。"},{"en":"The phrase shows change away from tradition.","zh":"這個短語顯示離開傳統的改變。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":17},{"front":"old set forms","meaning":"舊有固定形式","examples":[{"en":"The new handwriting departed from old set forms.","zh":"新手寫體擺脫了舊有固定形式。"},{"en":"Old set forms are fixed traditional shapes or patterns used before.","zh":"old set forms 是以前使用的固定傳統形狀或模式。"},{"en":"A school may depart from old set forms of teaching by using projects instead of lectures only.","zh":"學校可能透過使用專題研習而不只是講課，擺脫舊有固定教學形式。"},{"en":"If handwriting keeps old set forms, it may remain neat but slow.","zh":"如果手寫保留舊有固定形式，它可能整齊但緩慢。"},{"en":"The phrase suggests something established, fixed, and resistant to change.","zh":"這個短語暗示某物已建立、固定並不易改變。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":17},{"front":"by the end of","meaning":"到……結束時","examples":[{"en":"By the end of the 16th century, the alphabet had changed.","zh":"到16世紀結束時，字母已經改變。"},{"en":"By the end of a period means no later than the final part of that period.","zh":"by the end of 某時期，指不遲於該時期的最後部分。"},{"en":"By the end of the school year, students should know all the key grammar rules.","zh":"到學年結束時，學生應該知道所有主要文法規則。"},{"en":"If letters changed by the end of a century, the transformation was complete by then.","zh":"如果字母到某世紀結束時已改變，轉變在那時已完成。"},{"en":"The phrase gives a deadline or endpoint in time.","zh":"這個短語給出時間上的期限或終點。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":17},{"front":"transform into","meaning":"轉變成","examples":[{"en":"Old letterforms transformed into the 26 letters we know today.","zh":"舊字母形態轉變成我們今日所知的26個字母。"},{"en":"To transform into something means to change completely into a new form.","zh":"transform into 某物，指完全改變成一種新形式。"},{"en":"An empty shop can transform into a community library.","zh":"空置商店可以轉變成社區圖書館。"},{"en":"If old letterforms transform into modern letters, readers can see the history behind the alphabet.","zh":"如果舊字母形態轉變成現代字母，讀者就能看見字母背後的歷史。"},{"en":"The phrase describes major change, not a tiny adjustment.","zh":"這個短語描述重大改變，而不是小調整。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":18},{"front":"the 26 letters of the alphabet","meaning":"26個英文字母","examples":[{"en":"The old letterforms became the 26 letters of the alphabet.","zh":"舊字母形態變成26個英文字母。"},{"en":"The 26 letters of the alphabet are the letters A to Z used in modern English writing.","zh":"the 26 letters of the alphabet 是現代英文書寫中使用的 A 至 Z 字母。"},{"en":"Children learn the 26 letters of the alphabet before spelling simple words.","zh":"孩子在拼寫簡單單字前，會學習26個英文字母。"},{"en":"If old symbols became the 26 letters of the alphabet, many historical changes led to modern writing.","zh":"如果舊符號變成26個英文字母，現代書寫背後就有許多歷史變化。"},{"en":"The phrase refers to the complete English alphabet.","zh":"這個短語指完整英文字母表。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":18},{"front":"as we know today","meaning":"正如我們今日所認識的","examples":[{"en":"The alphabet developed into the form we know today.","zh":"字母發展成我們今日所認識的形式。"},{"en":"As we know today means in the form familiar to people now.","zh":"as we know today 指以現在人們熟悉的形式。"},{"en":"Schools as we know today are very different from small ancient learning groups.","zh":"正如我們今日所認識的學校，與古代小型學習群體非常不同。"},{"en":"If the alphabet became the form we know today, earlier scripts had been reshaped over time.","zh":"如果字母變成我們今日所認識的形式，早期文字就已隨時間被重塑。"},{"en":"The phrase compares the present familiar version with earlier forms.","zh":"這個短語把今天熟悉版本與早期形式作比較。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":18},{"front":"upper and lower-case letters","meaning":"大楷及小楷字母","examples":[{"en":"The alphabet developed both upper and lower-case letters.","zh":"字母發展出大楷及小楷字母。"},{"en":"Upper and lower-case letters are capital and small forms of alphabet letters.","zh":"upper and lower-case letters 是字母的大寫和小寫形式。"},{"en":"A password may require both upper and lower-case letters for security.","zh":"密碼可能要求同時有大楷及小楷字母以提高安全性。"},{"en":"If writing uses upper and lower-case letters, readers can recognise sentence structure more easily.","zh":"如果書寫使用大楷及小楷字母，讀者就更容易辨認句子結構。"},{"en":"The phrase refers to two letter sizes or forms used together.","zh":"這個短語指兩種字母大小或形式一同使用。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":18},{"front":"better inks and paper","meaning":"更好的墨水和紙張","examples":[{"en":"Writers eventually had both better inks and paper.","zh":"書寫者最終擁有更好的墨水和紙張。"},{"en":"Better inks and paper means improved writing liquids and writing surfaces.","zh":"better inks and paper 指改良了的書寫液和書寫表面。"},{"en":"Better inks and paper help students produce cleaner notes that last longer.","zh":"更好的墨水和紙張幫助學生寫出更整潔並保存更久的筆記。"},{"en":"If writers have better inks and paper, handwriting can become smoother and more reliable.","zh":"如果書寫者有更好的墨水和紙張，手寫就能變得更流暢和更可靠。"},{"en":"The phrase connects tool improvement with better writing quality.","zh":"這個短語把工具改良與更好書寫質素連繫起來。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":18},{"front":"develop into an art form","meaning":"發展成一種藝術形式","examples":[{"en":"Handwriting developed into an art form.","zh":"手寫發展成一種藝術形式。"},{"en":"To develop into an art form means to become a skilled and beautiful creative practice.","zh":"develop into an art form 指變成一種需要技巧且美觀的創意實踐。"},{"en":"Cake decorating can develop into an art form when bakers design detailed patterns.","zh":"當糕餅師設計細緻圖案時，蛋糕裝飾可以發展成一種藝術形式。"},{"en":"If handwriting develops into an art form, people value its beauty as well as its message.","zh":"如果手寫發展成一種藝術形式，人們就會重視其美感以及訊息。"},{"en":"The phrase shows a practical skill becoming artistic.","zh":"這個短語顯示實用技能變成藝術。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":18},{"front":"everyday occurrence","meaning":"日常事情","examples":[{"en":"Handwriting became an everyday occurrence.","zh":"手寫成為日常事情。"},{"en":"An everyday occurrence is something that happens regularly in normal life.","zh":"everyday occurrence 是在日常生活中經常發生的事情。"},{"en":"Sending messages by phone is an everyday occurrence for many people.","zh":"用手機發訊息對許多人來說是日常事情。"},{"en":"If handwriting became an everyday occurrence, ordinary people used it more often, not just specialists.","zh":"如果手寫成為日常事情，普通人就更常使用它，而不只是專家使用。"},{"en":"The phrase describes something becoming common and routine.","zh":"這個短語描述某事變得常見和例行。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":18},{"front":"humanity’s inventive nature","meaning":"人類的創造本性","examples":[{"en":"Humanity’s inventive nature led to better writing tools.","zh":"人類的創造本性帶來更好的書寫工具。"},{"en":"Humanity’s inventive nature means people’s natural tendency to create and improve things.","zh":"humanity’s inventive nature 指人類自然傾向於創造和改良事物。"},{"en":"Humanity’s inventive nature can be seen in tools, medicine, transport, and communication.","zh":"人類的創造本性可以在工具、醫學、交通和溝通中看見。"},{"en":"If humanity’s inventive nature keeps improving writing tools, pens will continue to change.","zh":"如果人類的創造本性持續改良書寫工具，筆就會繼續改變。"},{"en":"The phrase presents invention as a basic human quality.","zh":"這個短語把發明呈現為一種基本人類特質。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":18},{"front":"once again turned to","meaning":"再次轉向","examples":[{"en":"Humanity’s inventive nature once again turned to improving writing instruments.","zh":"人類的創造本性再次轉向改良書寫工具。"},{"en":"Once again turned to something means returned to focus on that activity or problem again.","zh":"once again turned to 某事，意思是再次回到並專注於該活動或問題。"},{"en":"After exams, the school once again turned to improving student wellbeing.","zh":"考試後，學校再次轉向改善學生身心健康。"},{"en":"If people once again turned to writing tools, they were trying to solve old writing problems in new ways.","zh":"如果人們再次轉向書寫工具，他們就是嘗試以新方法解決舊書寫問題。"},{"en":"The phrase shows a renewed focus.","zh":"這個短語顯示重新聚焦。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":18},{"front":"improve the writing instrument","meaning":"改良書寫工具","examples":[{"en":"People continued to improve the writing instrument.","zh":"人們繼續改良書寫工具。"},{"en":"To improve the writing instrument means to make the tool for writing work better.","zh":"improve the writing instrument 指令書寫工具運作得更好。"},{"en":"Designers improve the writing instrument by making pens smoother, lighter, and less messy.","zh":"設計師透過令筆更順滑、更輕和更少弄污來改良書寫工具。"},{"en":"If people improve the writing instrument, writing can become faster and more comfortable.","zh":"如果人們改良書寫工具，書寫就能變得更快和更舒服。"},{"en":"The phrase focuses on better tools rather than better language.","zh":"這個短語重點在於更好的工具，而不是更好的語言。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":18},{"front":"lead to the development of","meaning":"導致……的發展","examples":[{"en":"Improved writing tools led to the development of the modern fountain pen.","zh":"改良書寫工具導致現代鋼筆的發展。"},{"en":"To lead to the development of something means to cause or help bring it into existence.","zh":"lead to the development of 某物，意思是造成或幫助它出現。"},{"en":"Better batteries led to the development of smaller mobile devices.","zh":"更好的電池導致較小型流動裝置的發展。"},{"en":"If earlier pens led to the development of the fountain pen, invention happened step by step.","zh":"如果早期筆導致鋼筆的發展，發明就是一步一步發生的。"},{"en":"The phrase shows a cause that produces a later innovation.","zh":"這個短語顯示導致後來創新的原因。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":18},{"front":"the modern fountain pen","meaning":"現代鋼筆","examples":[{"en":"The modern fountain pen developed from earlier writing instruments.","zh":"現代鋼筆由較早書寫工具發展而來。"},{"en":"The modern fountain pen is a pen with an internal ink supply and a nib for writing.","zh":"the modern fountain pen 是內部有墨水供應並有筆尖用於書寫的筆。"},{"en":"A writer may choose a modern fountain pen because it feels smooth and elegant.","zh":"書寫者可能選擇現代鋼筆，因為它感覺順滑而優雅。"},{"en":"If the modern fountain pen solved older ink problems, it made writing more convenient.","zh":"如果現代鋼筆解決了舊有墨水問題，它就令書寫更方便。"},{"en":"The phrase refers to the later developed version of ink pens.","zh":"這個短語指後來發展出的墨水筆版本。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":19},{"front":"choose two letters","meaning":"選擇兩個字母","examples":[{"en":"Students choose two letters from the options.","zh":"學生從選項中選擇兩個字母。"},{"en":"Choose two letters means select exactly two answer choices marked by letters.","zh":"choose two letters 指選出剛好兩個以字母標示的答案選項。"},{"en":"In a reading test, students may choose two letters such as A and D.","zh":"在閱讀測驗中，學生可能選擇 A 和 D 兩個字母。"},{"en":"If the question says choose two letters, choosing only one or three may lose marks.","zh":"如果題目說選擇兩個字母，只選一個或三個都可能失分。"},{"en":"The phrase tells candidates the required number and format of answers.","zh":"這個短語告訴考生答案所需數量和格式。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":19},{"front":"features inherent in","meaning":"……固有的特點","examples":[{"en":"The question asks which features are inherent in record keeping.","zh":"題目問哪些特點是記錄工作固有的。"},{"en":"Features inherent in something are qualities naturally built into it.","zh":"features inherent in 某事，是自然存在於其中的特質。"},{"en":"Repetition is a feature inherent in practising handwriting because letters are written again and again.","zh":"重複是練習手寫固有的特點，因為字母會一再書寫。"},{"en":"If large volume is inherent in record keeping, people need systems to manage it.","zh":"如果大量資料是記錄工作固有的特點，人們就需要系統來管理它。"},{"en":"The phrase asks about internal characteristics, not outside additions.","zh":"這個短語問的是內在特徵，而不是外加因素。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":19},{"front":"large volume","meaning":"大量；龐大數量","examples":[{"en":"Large volume is one feature of record keeping.","zh":"大量是記錄工作的一個特點。"},{"en":"Large volume means a great amount or high quantity.","zh":"large volume 指大量或高數量。"},{"en":"A customer service team may receive a large volume of emails after a product problem.","zh":"產品出問題後，客服團隊可能收到大量電郵。"},{"en":"If record keeping involves large volume, symbols must be quick and consistent.","zh":"如果記錄工作涉及大量資料，符號就必須快速而一致。"},{"en":"The phrase refers to quantity, not loudness here.","zh":"這個短語在此指數量，而不是音量。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":19},{"front":"portability","meaning":"可攜性","examples":[{"en":"Portability made clay records useful for merchants.","zh":"可攜性使黏土記錄對商人有用。"},{"en":"Portability is the quality of being easy to carry or move.","zh":"portability 是容易攜帶或移動的特質。"},{"en":"A laptop has portability because students can take it from home to school.","zh":"手提電腦有可攜性，因為學生可以把它從家帶到學校。"},{"en":"If records have portability, traders can bring information with them during travel.","zh":"如果記錄具可攜性，商人就能在旅途中帶着資料。"},{"en":"The phrase explains why movable writing materials were practical.","zh":"這個短語解釋可移動書寫材料為何實用。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":19},{"front":"delayed the spread of","meaning":"延誤……的傳播","examples":[{"en":"Secrecy delayed the spread of wood-fibre papermaking.","zh":"保密延誤了木纖維造紙的傳播。"},{"en":"To delay the spread of something means to slow down how quickly it reaches other people or places.","zh":"delay the spread of 某事，指減慢它傳到其他人或地方的速度。"},{"en":"Poor internet access delayed the spread of online learning in some rural areas.","zh":"網絡接入不足延誤了網上學習在一些鄉村地區的傳播。"},{"en":"If secrecy delayed the spread of papermaking, fewer regions could use the technology early.","zh":"如果保密延誤造紙傳播，較少地區能早期使用該技術。"},{"en":"The phrase links slow diffusion with a cause.","zh":"這個短語把傳播緩慢與原因連繫起來。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":19},{"front":"wood-fibre papermaking","meaning":"木纖維造紙","examples":[{"en":"Wood-fibre papermaking began in China.","zh":"木纖維造紙始於中國。"},{"en":"Wood-fibre papermaking is the process of making paper from wood or plant fibres.","zh":"wood-fibre papermaking 是用木材或植物纖維製造紙張的過程。"},{"en":"Workers in a paper mill may learn wood-fibre papermaking through repeated practice.","zh":"造紙廠工人可能透過反覆練習學習木纖維造紙。"},{"en":"If wood-fibre papermaking spreads, paper can become more available for writing and printing.","zh":"如果木纖維造紙傳播，紙張就能更容易用於書寫和印刷。"},{"en":"The phrase refers to the production process, not just the finished paper.","zh":"這個短語指生產過程，而不只是成品紙張。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":19},{"front":"scarcity","meaning":"稀缺","examples":[{"en":"Scarcity can delay the spread of a technology.","zh":"稀缺可以延誤一項技術的傳播。"},{"en":"Scarcity means there is not enough of something available.","zh":"scarcity 指某物供應不足。"},{"en":"Water scarcity can force families to walk far to collect clean water.","zh":"食水稀缺可以迫使家庭走很遠去收集潔淨水。"},{"en":"If materials are scarce, a new writing tool may remain expensive and uncommon.","zh":"如果材料稀缺，新的書寫工具可能仍然昂貴且不常見。"},{"en":"The word describes limited supply.","zh":"這個字描述供應有限。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":19},{"front":"complexity","meaning":"複雜性","examples":[{"en":"Complexity can make a process harder to spread.","zh":"複雜性可以令一個過程更難傳播。"},{"en":"Complexity means having many parts, steps, or details that make something difficult.","zh":"complexity 指某事有很多部分、步驟或細節，因此變得困難。"},{"en":"The complexity of a maths problem can make students read it several times.","zh":"數學題的複雜性可以令學生讀幾次才明白。"},{"en":"If papermaking has high complexity, learners need more time and training.","zh":"如果造紙有高度複雜性，學習者就需要更多時間和訓練。"},{"en":"The word explains why a method may not be easy to copy.","zh":"這個字解釋為何一種方法不容易被複製。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":19},{"front":"secrecy among","meaning":"……之間的保密","examples":[{"en":"Secrecy among its inventors delayed the spread of papermaking.","zh":"發明者之間的保密延誤了造紙的傳播。"},{"en":"Secrecy among a group means members of that group keep knowledge hidden from outsiders.","zh":"secrecy among 某群人，指該群體成員把知識向外人隱藏。"},{"en":"Secrecy among company engineers may protect a new product before launch.","zh":"公司工程師之間的保密可能在產品推出前保護新產品。"},{"en":"If there is secrecy among inventors, other regions may not learn the process quickly.","zh":"如果發明者之間有保密，其他地區可能不能很快學到工序。"},{"en":"The phrase identifies who kept the information private.","zh":"這個短語指出是誰把資料保密。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":19},{"front":"high cost","meaning":"高成本","examples":[{"en":"High cost can prevent a technology from becoming widespread.","zh":"高成本可以阻止一項技術普及。"},{"en":"High cost means something is expensive to make, buy, or use.","zh":"high cost 指某物製造、購買或使用都昂貴。"},{"en":"High cost may stop small schools from buying advanced science equipment.","zh":"高成本可能令小型學校無法購買先進科學設備。"},{"en":"If paper has a high cost, ordinary people may not use it for daily writing.","zh":"如果紙張成本高，普通人可能不會用它作日常書寫。"},{"en":"The phrase explains a financial barrier.","zh":"這個短語解釋財政障礙。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":19},{"front":"contain the following information","meaning":"包含以下資料","examples":[{"en":"Students identify which paragraph contains the following information.","zh":"學生找出哪一段包含以下資料。"},{"en":"Contain the following information means include the details listed after the instruction.","zh":"contain the following information 指包括指示後列出的細節。"},{"en":"A reading question may ask which paragraph contains the following information about an invention.","zh":"閱讀題可能問哪一段包含以下關於發明的資料。"},{"en":"If a paragraph contains the following information, students should match it with the correct item.","zh":"如果某段包含以下資料，學生就應把它與正確項目配對。"},{"en":"The phrase is common in paragraph-matching tasks.","zh":"這個短語常見於段落配對題。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":20},{"front":"operating principle","meaning":"運作原理","examples":[{"en":"The paragraph explains the operating principle of primitive reed pens.","zh":"該段解釋原始蘆葦筆的運作原理。"},{"en":"An operating principle is the basic idea that explains how a machine or tool works.","zh":"operating principle 是解釋機器或工具如何運作的基本概念。"},{"en":"The operating principle of a bicycle is that pedalling turns the wheels through a chain.","zh":"單車的運作原理是踩踏板透過鏈條帶動車輪。"},{"en":"If students understand a pen’s operating principle, they know how ink moves to the nib.","zh":"如果學生理解筆的運作原理，他們就知道墨水如何移到筆尖。"},{"en":"The phrase focuses on how something functions.","zh":"這個短語重點在於某物如何運作。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":20},{"front":"primitive pens","meaning":"原始筆","examples":[{"en":"Primitive pens were made from plant stems.","zh":"原始筆由植物莖製成。"},{"en":"Primitive pens are early, simple writing tools used before modern pens existed.","zh":"primitive pens 是現代筆出現前使用的早期簡單書寫工具。"},{"en":"A reed with a cut tip could act as one of the primitive pens of the ancient world.","zh":"一根切出尖端的蘆葦可以作為古代世界的原始筆之一。"},{"en":"If primitive pens stored ink poorly, writers had to prepare and control them carefully.","zh":"如果原始筆儲墨效果差，書寫者就必須小心準備和控制它們。"},{"en":"The phrase describes early pen-like tools, not modern ballpoint pens.","zh":"這個短語描述早期像筆的工具，而不是現代原子筆。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":20},{"front":"plant stems","meaning":"植物莖","examples":[{"en":"Plant stems were converted into early pens.","zh":"植物莖被轉化成早期筆。"},{"en":"Plant stems are the main stalks of plants that support leaves, flowers, or seeds.","zh":"plant stems 是支撐葉、花或種子的植物主要莖部。"},{"en":"Some plant stems are hollow, so they can hold liquid like a small tube.","zh":"有些植物莖是空心的，所以可以像小管一樣盛載液體。"},{"en":"If plant stems are strong and hollow, they can be turned into simple writing tools.","zh":"如果植物莖堅韌且空心，它們就可以變成簡單書寫工具。"},{"en":"The phrase identifies the natural material used for early pens.","zh":"這個短語指出早期筆使用的天然材料。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":20},{"front":"writing tool used for the longest period","meaning":"使用時間最長的書寫工具","examples":[{"en":"The quill was the writing tool used for the longest period.","zh":"羽毛筆是使用時間最長的書寫工具。"},{"en":"A writing tool used for the longest period is the tool that stayed in common use longer than the others.","zh":"writing tool used for the longest period 是比其他工具更長時間被普遍使用的工具。"},{"en":"In school history, pencils may be the writing tool used for the longest period by many students.","zh":"在學校歷史中，鉛筆可能是許多學生使用時間最長的書寫工具。"},{"en":"If quills were used for the longest period, they were practical despite their disadvantages.","zh":"如果羽毛筆使用時間最長，即使有缺點，它們仍然實用。"},{"en":"The phrase compares the duration of use among writing tools.","zh":"這個短語比較不同書寫工具的使用時長。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":20},{"front":"a writing fluid first developed by the Chinese","meaning":"最早由中國人發展的書寫液","examples":[{"en":"Indian ink was a writing fluid first developed by the Chinese.","zh":"墨汁是最早由中國人發展的書寫液。"},{"en":"A writing fluid first developed by the Chinese means a liquid for writing that was originally created in China.","zh":"a writing fluid first developed by the Chinese 指最初在中國創造的書寫用液體。"},{"en":"A museum label may describe ink as a writing fluid first developed by the Chinese.","zh":"博物館標籤可能把墨水描述為最早由中國人發展的書寫液。"},{"en":"If a writing fluid was first developed by the Chinese, China played an important role in writing technology.","zh":"如果一種書寫液最早由中國人發展，中國就在書寫技術中扮演重要角色。"},{"en":"The phrase combines function, origin, and historical importance.","zh":"這個短語結合功能、來源和歷史重要性。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":20},{"front":"only original letter form","meaning":"唯一原始字母形式","examples":[{"en":"Uppercase letters were the only original letter form.","zh":"大楷字母是唯一原始字母形式。"},{"en":"The only original letter form means the sole letter style used at the beginning.","zh":"only original letter form 指最初唯一使用的字母樣式。"},{"en":"In early English lessons, printed capitals may be the only original letter form children learn first.","zh":"在早期英文課中，印刷大楷可能是孩子首先學到的唯一原始字母形式。"},{"en":"If uppercase letters were the only original letter form, lowercase letters were later additions.","zh":"如果大楷字母是唯一原始字母形式，小楷字母就是後來增加的。"},{"en":"The phrase highlights what existed first before later changes.","zh":"這個短語突出後來改變前最初存在的形式。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":20},{"front":"the origin of written correspondence","meaning":"書面通信的起源","examples":[{"en":"The passage explains the origin of written correspondence.","zh":"文章解釋書面通信的起源。"},{"en":"The origin of written correspondence means how sending written messages between people began.","zh":"the origin of written correspondence 指人與人之間傳送書面訊息如何開始。"},{"en":"A history lesson may discuss the origin of written correspondence before studying letters and emails.","zh":"歷史課可能在研究信件和電郵前討論書面通信的起源。"},{"en":"If scholars study the origin of written correspondence, they can understand how long-distance communication developed.","zh":"如果學者研究書面通信的起源，就能理解遠距離溝通如何發展。"},{"en":"The phrase focuses on the beginning of written message exchange.","zh":"這個短語重點在於書面訊息交換的開始。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":20},{"front":"parallel development","meaning":"同步發展","examples":[{"en":"The passage describes the parallel development of ink and paper.","zh":"文章描述墨水和紙張的同步發展。"},{"en":"Parallel development means two things developing at the same time or in closely related ways.","zh":"parallel development 指兩件事同時或以密切相關的方式發展。"},{"en":"The parallel development of phones and apps changed how people communicate.","zh":"手機和應用程式的同步發展改變了人們溝通方式。"},{"en":"If ink and paper show parallel development, improvements in one supported the other.","zh":"如果墨水和紙張呈現同步發展，其中一方的改良就支持另一方。"},{"en":"The phrase shows linked progress happening side by side.","zh":"這個短語顯示並行發生的相關進步。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":20},{"front":"basic writing materials","meaning":"基本書寫材料","examples":[{"en":"Ink and paper are basic writing materials.","zh":"墨水和紙張是基本書寫材料。"},{"en":"Basic writing materials are the essential things needed to write.","zh":"basic writing materials 是書寫所需的基本物品。"},{"en":"Students usually need basic writing materials such as paper, pens, and pencils.","zh":"學生通常需要紙、筆和鉛筆等基本書寫材料。"},{"en":"If basic writing materials are cheap and available, more people can learn to write.","zh":"如果基本書寫材料便宜且容易取得，更多人就能學習書寫。"},{"en":"The phrase refers to simple necessary supplies, not advanced machines.","zh":"這個短語指簡單必需用品，而不是先進機器。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":20},{"front":"protected written content","meaning":"保護書寫內容","examples":[{"en":"The hinged tablets protected written content.","zh":"鉸接寫字板保護書寫內容。"},{"en":"Protected written content means kept words or notes safe from damage or loss.","zh":"protected written content 指保護文字或筆記免受損壞或遺失。"},{"en":"A plastic folder protected written content from rain during the journey home.","zh":"膠文件夾在回家途中保護書寫內容免受雨水破壞。"},{"en":"If tablets close over the writing, they protect written content from being rubbed away.","zh":"如果寫字板能合上覆蓋文字，就能保護書寫內容不被擦掉。"},{"en":"The phrase focuses on preserving what has been written.","zh":"這個短語重點在於保存已寫下的內容。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":20},{"front":"answer the questions below","meaning":"回答以下問題","examples":[{"en":"Students answer the questions below using words from the passage.","zh":"學生使用文章中的字詞回答以下問題。"},{"en":"Answer the questions below means respond to the questions that follow the instruction.","zh":"answer the questions below 指回答指示後面的問題。"},{"en":"In a worksheet, students answer the questions below after reading the text carefully.","zh":"在工作紙中，學生仔細閱讀文本後回答以下問題。"},{"en":"If students skip the questions below, they may miss word limits or special instructions.","zh":"如果學生跳過以下問題，可能錯過字數限制或特別指示。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":21},{"front":"no more than three words and/or a number","meaning":"不超過三個字及／或一個數字","examples":[{"en":"Students should use no more than three words and/or a number.","zh":"學生應使用不超過三個字及／或一個數字。"},{"en":"No more than three words and/or a number means the answer may contain up to three words, a number, or both.","zh":"no more than three words and/or a number 指答案可包含最多三個英文單字、一個數字，或兩者。"},{"en":"If the answer is “400 A.D.”, it fits because the instruction allows a number.","zh":"如果答案是 “400 A.D.”，它符合要求，因為指示容許數字。"},{"en":"If students write a full sentence, they may exceed no more than three words and/or a number.","zh":"如果學生寫完整句子，可能超出不超過三個字及／或一個數字的限制。"},{"en":"The phrase sets both the word limit and the allowed answer form.","zh":"這個短語同時設定字數限制和可用答案形式。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":21},{"front":"made quill pens inconvenient to use","meaning":"令羽毛筆使用不便","examples":[{"en":"Lengthy preparation time made quill pens inconvenient to use.","zh":"漫長準備時間令羽毛筆使用不便。"},{"en":"Made quill pens inconvenient to use means caused quill pens to be less easy or practical.","zh":"made quill pens inconvenient to use 指令羽毛筆變得較不方便或較不實用。"},{"en":"A pen that leaks ink can be inconvenient to use during an exam.","zh":"一支會漏墨的筆在考試中使用不便。"},{"en":"If quill pens required sharpening and drying arrangements, they were inconvenient for quick writing.","zh":"如果羽毛筆需要削尖和安排烘乾，它們就不適合快速書寫。"},{"en":"The phrase explains why people wanted better writing instruments.","zh":"這個短語解釋為何人們想要更好的書寫工具。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":21},{"front":"another breakthrough","meaning":"另一項突破","examples":[{"en":"Another breakthrough occurred after plant-fibre paper became common.","zh":"植物纖維紙變得普遍後，另一項突破出現了。"},{"en":"Another breakthrough means one more important advance or successful development.","zh":"another breakthrough 指另一個重要進展或成功發展。"},{"en":"A new medicine can be another breakthrough after years of research.","zh":"經過多年研究後，新藥可以是另一項突破。"},{"en":"If another breakthrough follows better paper, writing technology continues to improve.","zh":"如果更好的紙張之後又出現另一項突破，書寫技術就繼續改良。"},{"en":"The phrase marks a further major step forward.","zh":"這個短語標示進一步重大進展。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":21},{"front":"the main writing medium","meaning":"主要書寫媒介","examples":[{"en":"Plant-fibre paper became the main writing medium.","zh":"植物纖維紙成為主要書寫媒介。"},{"en":"The main writing medium is the primary surface or material used for writing.","zh":"the main writing medium 是用於書寫的主要表面或材料。"},{"en":"In modern schools, paper and digital screens are common writing media.","zh":"在現代學校，紙張和數碼螢幕都是常見書寫媒介。"},{"en":"If paper becomes the main writing medium, ink and pens must be designed to work on it.","zh":"如果紙張成為主要書寫媒介，墨水和筆就必須設計到適合在紙上使用。"},{"en":"The phrase identifies the most important material for writing.","zh":"這個短語指出最重要的書寫材料。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":21},{"front":"result from","meaning":"由……產生","examples":[{"en":"The modern fountain pen resulted from humanity’s ingenuity.","zh":"現代鋼筆由人類巧思產生。"},{"en":"To result from something means to happen because of it.","zh":"result from 某事，意思是因它而發生。"},{"en":"Better exam results may result from steady practice and clear feedback.","zh":"更好的考試成績可能由穩定練習和清楚回饋產生。"},{"en":"If the fountain pen resulted from human ingenuity, it was caused by repeated problem-solving.","zh":"如果鋼筆由人類巧思產生，它就是反覆解決問題的結果。"},{"en":"The phrase introduces the cause of an outcome.","zh":"這個短語引出結果的原因。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":21},{"front":"humanity’s ingenuity","meaning":"人類巧思；人類創意","examples":[{"en":"The modern fountain pen resulted from humanity’s ingenuity in improving tools.","zh":"現代鋼筆源自人類在改良工具方面的巧思。"},{"en":"Humanity’s ingenuity means human cleverness and creativity in solving problems.","zh":"humanity’s ingenuity 指人類解決問題時展現的聰明才智和創意。"},{"en":"Humanity’s ingenuity can turn simple materials into tools, machines, and medical treatments.","zh":"人類巧思可以把簡單材料變成工具、機器和醫療方法。"},{"en":"If writing problems persisted, humanity’s ingenuity pushed people to design better pens.","zh":"如果書寫問題持續存在，人類巧思就推動人們設計更好的筆。"},{"en":"The phrase praises human creativity and practical intelligence.","zh":"這個短語讚揚人類創意和實用智慧。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":21},{"front":"improving writing tools","meaning":"改良書寫工具","examples":[{"en":"Humanity’s ingenuity led to improvements in writing tools.","zh":"人類巧思帶來書寫工具的改良。"},{"en":"Improving writing tools means making pens, inks, paper, or other writing devices better.","zh":"improving writing tools 指令筆、墨水、紙張或其他書寫裝置變得更好。"},{"en":"Designers improve writing tools by reducing ink leaks and making pens easier to hold.","zh":"設計師透過減少漏墨和令筆更易握持來改良書寫工具。"},{"en":"If people keep improving writing tools, writing becomes faster, cleaner, and more comfortable.","zh":"如果人們持續改良書寫工具，書寫就會變得更快、更乾淨和更舒適。"},{"en":"The phrase focuses on practical upgrades to the objects used for writing.","zh":"這個短語重點在於對書寫物件作出的實用升級。"}],"source":"124 - Tool for ancient writing.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 125":[{"front":"too nice for their own good","meaning":"太溫馴反而對自己不利","examples":[{"en":"Koalas are just too nice for their own good.","zh":"樹熊實在太溫馴，反而對自己不利。"},{"en":"Too nice for their own good means so gentle or passive that it creates problems.","zh":"太溫馴反而對自己不利，是指過分溫和或被動，以致造成問題。"},{"en":"A student who never refuses extra work may be too nice for their own good.","zh":"從不拒絕額外工作的學生，可能太好人反而對自己不利。"},{"en":"Being too nice for your own good can let other people take advantage of you.","zh":"太好人反而對自己不利，可能讓別人利用你。"},{"en":"The phrase often sounds sympathetic, but it also points to a weakness.","zh":"這個短語通常帶同情意味，但也指出一種弱點。"}],"source":"125 - Koalas.pdf","sourcePage":1},{"front":"except for","meaning":"除了……之外","examples":[{"en":"Except for the occasional baby taken by birds of prey, koalas have no natural enemies.","zh":"除了偶爾有幼崽被猛禽抓走之外，樹熊沒有天敵。"},{"en":"Except for means not including one person, thing, or case.","zh":"除了……之外，是指不包括某一個人、事物或情況。"},{"en":"Except for one spelling mistake, the student’s essay was excellent.","zh":"除了一個拼寫錯誤之外，學生的作文非常出色。"},{"en":"This phrase is used when a statement is almost completely true but has one exception.","zh":"當一個說法幾乎完全正確但有一個例外時，可以使用這個短語。"},{"en":"It helps readers notice the only thing that does not fit the general rule.","zh":"它幫助讀者注意唯一不符合一般規則的事情。"}],"source":"125 - Koalas.pdf","sourcePage":1},{"front":"the occasional baby","meaning":"偶爾有幼崽","examples":[{"en":"The occasional baby koala may be taken by birds of prey.","zh":"偶爾有樹熊幼崽可能會被猛禽抓走。"},{"en":"The occasional baby means a baby that is affected only from time to time, not often.","zh":"偶爾有幼崽，是指幼崽只是有時受影響，並不經常。"},{"en":"The occasional baby in a nursery may cry during nap time.","zh":"托兒所裡偶爾有嬰兒會在午睡時間哭。"},{"en":"This phrase suggests something happens rarely, not regularly.","zh":"這個短語暗示某事很少發生，而不是定期發生。"},{"en":"In the passage, it shows that koala babies face a small but real danger.","zh":"在篇章中，它顯示樹熊幼崽面對細小但真實的危險。"}],"source":"125 - Koalas.pdf","sourcePage":1},{"front":"birds of prey","meaning":"猛禽","examples":[{"en":"Birds of prey sometimes take baby koalas.","zh":"猛禽有時會抓走樹熊幼崽。"},{"en":"Birds of prey are hunting birds that catch and eat other animals.","zh":"猛禽是會捕捉並吃其他動物的獵食性鳥類。"},{"en":"Eagles, hawks, and owls are common examples of birds of prey.","zh":"鷹、鷂和貓頭鷹都是常見猛禽例子。"},{"en":"Small animals are more vulnerable when birds of prey hunt from above.","zh":"當猛禽從上方捕獵時，小動物更容易受害。"},{"en":"This phrase refers to predators, not ordinary garden birds.","zh":"這個短語指捕食者，而不是普通花園鳥類。"}],"source":"125 - Koalas.pdf","sourcePage":1},{"front":"natural enemies","meaning":"天敵","examples":[{"en":"Koalas have no natural enemies apart from a few threats to babies.","zh":"除了幼崽面對少數威脅外，樹熊沒有天敵。"},{"en":"Natural enemies are animals that normally hunt or harm another species in nature.","zh":"天敵是在自然界中通常捕獵或傷害另一物種的動物。"},{"en":"Mice have many natural enemies, including cats, snakes, and owls.","zh":"老鼠有很多天敵，包括貓、蛇和貓頭鷹。"},{"en":"A species with few natural enemies may still suffer from disease or human activity.","zh":"即使某物種天敵很少，仍可能受疾病或人類活動影響。"},{"en":"This phrase is often used when discussing survival in the wild.","zh":"這個短語常用於討論野外生存。"}],"source":"125 - Koalas.pdf","sourcePage":1},{"front":"in an ideal world","meaning":"在理想情況下","examples":[{"en":"In an ideal world, a koala’s life would be safe.","zh":"在理想情況下，樹熊的生活會很安全。"},{"en":"In an ideal world means if everything were perfect and fair.","zh":"在理想情況下，是指如果一切都完美而公平。"},{"en":"In an ideal world, every student would have enough sleep before exams.","zh":"在理想情況下，每個學生考試前都有足夠睡眠。"},{"en":"People use this phrase to contrast a perfect situation with real problems.","zh":"人們使用這個短語，把完美情況與現實問題作對比。"},{"en":"It often introduces something that should happen but does not fully happen in reality.","zh":"它常引入本應發生但現實中未必完全發生的事情。"}],"source":"125 - Koalas.pdf","sourcePage":1},{"front":"arboreal couch potato","meaning":"樹上懶洋洋的動物","examples":[{"en":"The koala is described humorously as an arboreal couch potato.","zh":"樹熊被幽默地描述為樹上懶洋洋的動物。"},{"en":"An arboreal couch potato is a humorous way to describe an animal that lives in trees and moves very little.","zh":"樹上懶洋洋的動物，是幽默地形容住在樹上且很少活動的動物。"},{"en":"A lazy cat sleeping on a high shelf might be jokingly called an indoor couch potato.","zh":"睡在高架上的懶貓，可能被開玩笑地稱為室內懶蟲。"},{"en":"The phrase makes the koala sound cute, slow, and inactive.","zh":"這個短語令樹熊聽起來可愛、慢吞吞和不活躍。"},{"en":"It combines a scientific word, arboreal, with a casual phrase, couch potato.","zh":"它把科學詞 arboreal 和口語 couch potato 結合起來。"}],"source":"125 - Koalas.pdf","sourcePage":1},{"front":"perfectly safe and acceptable","meaning":"完全安全且可接受","examples":[{"en":"The life of an arboreal couch potato would be perfectly safe and acceptable.","zh":"樹上懶洋洋動物的生活本會完全安全且可接受。"},{"en":"Perfectly safe and acceptable means completely free from danger and considered fine.","zh":"完全安全且可接受，是指完全沒有危險，而且被認為沒有問題。"},{"en":"A school trip is perfectly safe and acceptable if teachers check transport, food, and emergency plans.","zh":"如果老師檢查交通、食物和緊急計劃，學校旅行就是完全安全且可接受的。"},{"en":"Something may seem safe in theory but become risky when conditions change.","zh":"某事在理論上可能安全，但當情況改變就會變得有風險。"},{"en":"This phrase describes a situation where there should be no serious problem.","zh":"這個短語描述理應沒有嚴重問題的情況。"}],"source":"125 - Koalas.pdf","sourcePage":1},{"front":"two hundred years ago","meaning":"二百年前","examples":[{"en":"Two hundred years ago, koalas flourished across Australia.","zh":"二百年前，樹熊在澳洲各地繁盛。"},{"en":"Two hundred years ago means two centuries before the present time being discussed.","zh":"二百年前，是指距離正在討論的現在兩個世紀以前。"},{"en":"Two hundred years ago, many people travelled by horse rather than by car.","zh":"二百年前，許多人以馬匹而不是汽車出行。"},{"en":"This phrase helps readers compare the past with the present.","zh":"這個短語幫助讀者比較過去和現在。"},{"en":"It often introduces a major change over a long period.","zh":"它常引入長時間內發生的重大改變。"}],"source":"125 - Koalas.pdf","sourcePage":1},{"front":"flourish across","meaning":"在……各地繁盛","examples":[{"en":"Koalas once flourished across Australia.","zh":"樹熊曾在澳洲各地繁盛。"},{"en":"To flourish across a place means to live, grow, or succeed widely there.","zh":"在某地各地繁盛，是指在那裡廣泛生存、生長或成功。"},{"en":"Small cafés may flourish across a city when more people enjoy local coffee.","zh":"當更多人喜歡本地咖啡，小咖啡店可能在城市各地繁盛。"},{"en":"A species flourishes across an area when food, habitat, and safety are available.","zh":"當有食物、棲息地和安全條件時，物種會在某地區繁盛。"},{"en":"This phrase suggests wide success, not just survival in one small place.","zh":"這個短語暗示廣泛成功，而不只是留在一個小地方生存。"}],"source":"125 - Koalas.pdf","sourcePage":1},{"front":"seem to be in decline","meaning":"似乎正在減少","examples":[{"en":"Koalas now seem to be in decline.","zh":"樹熊現在似乎正在減少。"},{"en":"To seem to be in decline means to appear to be decreasing or becoming weaker.","zh":"似乎正在減少，是指看起來數量下降或變弱。"},{"en":"A school club may seem to be in decline if fewer students join each year.","zh":"如果每年加入的學生越來越少，學會可能似乎正在衰落。"},{"en":"A population can seem to be in decline before exact numbers are fully known.","zh":"在確切數字完全清楚之前，族群可能已似乎正在減少。"},{"en":"This phrase is cautious because it suggests a trend without claiming complete certainty.","zh":"這個短語較謹慎，因為它提出趨勢但不聲稱完全確定。"}],"source":"125 - Koalas.pdf","sourcePage":1},{"front":"exact numbers","meaning":"確切數目","examples":[{"en":"Exact numbers of koalas are not available.","zh":"樹熊的確切數目無法取得。"},{"en":"Exact numbers are precise figures, not rough guesses.","zh":"確切數目是精準數字，而不是粗略估計。"},{"en":"A teacher needs exact numbers before ordering lunch boxes for a class trip.","zh":"老師在為班級旅行訂飯盒前需要確切數目。"},{"en":"Without exact numbers, it is harder to judge whether a problem is improving or worsening.","zh":"沒有確切數目，就較難判斷問題正在改善還是惡化。"},{"en":"This phrase is important when discussing population size or statistics.","zh":"這個短語在討論族群大小或統計時很重要。"}],"source":"125 - Koalas.pdf","sourcePage":2},{"front":"be not available","meaning":"無法取得；沒有提供","examples":[{"en":"Exact numbers are not available because the species is not officially under threat.","zh":"確切數字無法取得，因為該物種官方上未被列為受威脅。"},{"en":"If information is not available, people cannot obtain or access it.","zh":"如果資料無法取得，人們就不能得到或查看它。"},{"en":"The exam timetable is not available yet, so students cannot plan the final week.","zh":"考試時間表尚未提供，所以學生不能規劃最後一週。"},{"en":"When data is not available, decisions may need to rely on estimates.","zh":"當數據無法取得，決策可能需要依靠估計。"},{"en":"This phrase explains why a clear answer cannot be given.","zh":"這個短語解釋為何不能給出清楚答案。"}],"source":"125 - Koalas.pdf","sourcePage":2},{"front":"the species","meaning":"物種","examples":[{"en":"The species does not appear to be under threat.","zh":"該物種似乎沒有受到威脅。"},{"en":"The species means a group of living things that share the same biological type.","zh":"物種是指具有相同生物類型的一群生物。"},{"en":"The giant panda is a species that receives strong conservation attention.","zh":"大熊貓是一個受到強烈保育關注的物種。"},{"en":"When a species loses habitat, its future population may be affected.","zh":"當一個物種失去棲息地，其未來族群可能受影響。"},{"en":"This phrase is used when discussing animals or plants scientifically.","zh":"這個短語用於以科學方式討論動植物。"}],"source":"125 - Koalas.pdf","sourcePage":2},{"front":"under threat","meaning":"受到威脅","examples":[{"en":"The koala does not officially appear to be under threat.","zh":"樹熊官方上似乎沒有被列為受到威脅。"},{"en":"Under threat means facing danger or possible harm.","zh":"受到威脅，是指面對危險或可能傷害。"},{"en":"A small shop may be under threat when a large chain opens nearby.","zh":"當大型連鎖店在附近開業，小店可能受到威脅。"},{"en":"Wildlife becomes under threat when habitat is destroyed or disease spreads.","zh":"當棲息地被破壞或疾病傳播，野生動物就會受到威脅。"},{"en":"This phrase can describe people, places, businesses, or species.","zh":"這個短語可以描述人、地方、企業或物種。"}],"source":"125 - Koalas.pdf","sourcePage":2},{"front":"human activity","meaning":"人類活動","examples":[{"en":"Human activity has caused many problems for koalas.","zh":"人類活動為樹熊造成許多問題。"},{"en":"Human activity means actions done by people, such as building, farming, driving, or hunting.","zh":"人類活動是指人做出的行動，例如建設、耕作、駕駛或捕獵。"},{"en":"Human activity near rivers can pollute water and harm fish.","zh":"河流附近的人類活動可能污染水源並傷害魚類。"},{"en":"When human activity removes habitat, animals may struggle to find food and shelter.","zh":"當人類活動移除棲息地，動物可能難以找到食物和庇護。"},{"en":"This phrase often explains environmental change caused by people.","zh":"這個短語常解釋由人造成的環境變化。"}],"source":"125 - Koalas.pdf","sourcePage":2},{"front":"particularly since","meaning":"尤其自從……以來","examples":[{"en":"Koalas have suffered particularly since European settlement.","zh":"樹熊尤其自從歐洲人定居以來受苦。"},{"en":"Particularly since means especially after a certain time or event.","zh":"尤其自從……以來，是指特別在某個時間或事件之後。"},{"en":"The road has become busier, particularly since the new mall opened.","zh":"這條路變得更繁忙，尤其自從新商場開業以來。"},{"en":"This phrase links a problem strongly to what happened after a point in time.","zh":"這個短語把問題與某個時間點之後發生的事強烈連繫起來。"},{"en":"It helps show when a situation became worse.","zh":"它幫助顯示情況何時變差。"}],"source":"125 - Koalas.pdf","sourcePage":2},{"front":"European settlement","meaning":"歐洲人定居","examples":[{"en":"European settlement changed the koala’s environment.","zh":"歐洲人定居改變了樹熊的環境。"},{"en":"European settlement means Europeans arriving and establishing homes, farms, towns, and systems in a place.","zh":"歐洲人定居，是指歐洲人到達某地並建立住所、農場、城鎮和制度。"},{"en":"European settlement in Australia changed land use, animals, and Indigenous communities.","zh":"歐洲人在澳洲定居改變了土地使用、動物和原住民社群。"},{"en":"Settlement can transform habitats when forests are cleared for farms and roads.","zh":"當森林被清除來建農場和道路，定居可以改變棲息地。"},{"en":"This phrase gives historical background to the koala’s decline.","zh":"這個短語提供樹熊數量下降的歷史背景。"}],"source":"125 - Koalas.pdf","sourcePage":2},{"front":"Aboriginal Australians","meaning":"澳洲原住民","examples":[{"en":"Koalas and Aboriginal Australians had coexisted peacefully for centuries.","zh":"樹熊和澳洲原住民幾個世紀以來和平共存。"},{"en":"Aboriginal Australians are the Indigenous peoples of Australia.","zh":"澳洲原住民是澳洲的原住民族。"},{"en":"Aboriginal Australians have long histories, languages, lands, and cultural traditions.","zh":"澳洲原住民擁有悠久歷史、語言、土地和文化傳統。"},{"en":"Mentioning Aboriginal Australians helps contrast earlier coexistence with later disruption.","zh":"提到澳洲原住民，有助對比早期共存與後來破壞。"},{"en":"This phrase refers to people, not animals or a single tribe.","zh":"這個短語指人群，而不是動物或單一部落。"}],"source":"125 - Koalas.pdf","sourcePage":2},{"front":"coexist peacefully","meaning":"和平共存","examples":[{"en":"Koalas and Aboriginal Australians coexisted peacefully for centuries.","zh":"樹熊和澳洲原住民幾個世紀以來和平共存。"},{"en":"To coexist peacefully means to live together without serious conflict.","zh":"和平共存，是指一起生活而沒有嚴重衝突。"},{"en":"Different religious groups can coexist peacefully when people respect each other’s customs.","zh":"當人們尊重彼此習俗，不同宗教群體可以和平共存。"},{"en":"Peaceful coexistence becomes harder when land, food, or safety is threatened.","zh":"當土地、食物或安全受到威脅，和平共存會變得更困難。"},{"en":"This phrase describes harmony between groups sharing the same place.","zh":"這個短語描述共享同一地方的群體之間的和諧。"}],"source":"125 - Koalas.pdf","sourcePage":2},{"front":"for centuries","meaning":"幾個世紀以來","examples":[{"en":"The two groups had coexisted peacefully for centuries.","zh":"這兩個群體幾個世紀以來和平共存。"},{"en":"For centuries means for hundreds of years.","zh":"幾個世紀以來，是指長達數百年。"},{"en":"Some temples have stood in the same village for centuries.","zh":"有些寺廟幾個世紀以來一直矗立在同一條村。"},{"en":"This phrase shows that a situation lasted a very long time.","zh":"這個短語顯示某情況持續了很長時間。"},{"en":"It often makes a later change feel more dramatic.","zh":"它常令後來的改變顯得更戲劇性。"}],"source":"125 - Koalas.pdf","sourcePage":2},{"front":"scattered pockets of","meaning":"零散分布的小區域","examples":[{"en":"Koalas are found only in scattered pockets of southeast Australia.","zh":"樹熊只在澳洲東南部零散分布的小區域中出現。"},{"en":"Scattered pockets of something are small, separated areas where it still exists.","zh":"某物零散分布的小區域，是指它仍存在但彼此分隔的小地方。"},{"en":"A language may survive in scattered pockets of older communities.","zh":"一種語言可能在年長社群的零散小區域中存續。"},{"en":"When a species remains only in scattered pockets, it may be harder to protect.","zh":"當物種只留在零散小區域中，就可能更難保護。"},{"en":"This phrase suggests limited and uneven distribution.","zh":"這個短語暗示分布有限而不均勻。"}],"source":"125 - Koalas.pdf","sourcePage":2},{"front":"southeast Australia","meaning":"澳洲東南部","examples":[{"en":"Koalas are now mainly found in southeast Australia.","zh":"樹熊現在主要分布於澳洲東南部。"},{"en":"Southeast Australia means the south-eastern part of Australia.","zh":"澳洲東南部是指澳洲的東南方部分。"},{"en":"Wildlife maps may show where animals live in southeast Australia.","zh":"野生動物地圖可能顯示動物在澳洲東南部的分布。"},{"en":"If koalas are mainly found in southeast Australia, their range is narrower than before.","zh":"如果樹熊主要分布於澳洲東南部，牠們的分布範圍就比以前狹窄。"},{"en":"This phrase gives the geographical location of remaining koala populations.","zh":"這個短語給出剩餘樹熊族群的地理位置。"}],"source":"125 - Koalas.pdf","sourcePage":3},{"front":"be at risk on several fronts","meaning":"在多方面面臨風險","examples":[{"en":"Koalas seem to be at risk on several fronts.","zh":"樹熊似乎在多方面面臨風險。"},{"en":"To be at risk on several fronts means to face danger from several different directions.","zh":"在多方面面臨風險，是指從幾個不同方向面對危險。"},{"en":"A small business may be at risk on several fronts if rent, wages, and competition all rise.","zh":"如果租金、工資和競爭都上升，小企業可能在多方面面臨風險。"},{"en":"Koalas face several risks because habitat loss, disease, cars, and fires can all harm them.","zh":"樹熊面對多種風險，因為棲息地流失、疾病、車輛和火災都可以傷害牠們。"},{"en":"This phrase stresses that the problem is not caused by one single threat.","zh":"這個短語強調問題不是由單一威脅造成。"}],"source":"125 - Koalas.pdf","sourcePage":3},{"front":"food source","meaning":"食物來源","examples":[{"en":"The eucalyptus tree is the koala’s only food source.","zh":"桉樹是樹熊唯一的食物來源。"},{"en":"A food source is something an animal or person depends on for food.","zh":"食物來源是動物或人依靠來取得食物的東西。"},{"en":"Rice is a major food source for many families in Asia.","zh":"稻米是亞洲許多家庭的主要食物來源。"},{"en":"If an animal loses its food source, its survival becomes more difficult.","zh":"如果動物失去食物來源，生存會變得更困難。"},{"en":"This phrase is useful when discussing diet, habitat, and survival.","zh":"這個短語適合用於討論飲食、棲息地和生存。"}],"source":"125 - Koalas.pdf","sourcePage":3},{"front":"eucalyptus tree","meaning":"桉樹","examples":[{"en":"The eucalyptus tree has become less abundant.","zh":"桉樹變得較少。"},{"en":"A eucalyptus tree is a tree whose leaves are the main food for koalas.","zh":"桉樹是一種其葉子是樹熊主要食物的樹。"},{"en":"Eucalyptus trees can provide food and shelter for many Australian animals.","zh":"桉樹可以為許多澳洲動物提供食物和棲息地。"},{"en":"When eucalyptus trees disappear, koalas lose both food and habitat.","zh":"當桉樹消失，樹熊會失去食物和棲息地。"},{"en":"This phrase is central to understanding koala survival.","zh":"這個短語是理解樹熊生存的核心。"}],"source":"125 - Koalas.pdf","sourcePage":3},{"front":"become less abundant","meaning":"變得較少","examples":[{"en":"The koala’s food source has become less abundant.","zh":"樹熊的食物來源變得較少。"},{"en":"To become less abundant means to become less common or available.","zh":"變得較少，是指變得較不常見或較難取得。"},{"en":"Public phone boxes have become less abundant since mobile phones became common.","zh":"自從手機普及後，公用電話亭變得較少。"},{"en":"When a food source becomes less abundant, animals must travel farther to eat.","zh":"當食物來源變得較少，動物必須走更遠才找到食物。"},{"en":"This phrase describes a decline in supply or presence.","zh":"這個短語描述供應或存在數量下降。"}],"source":"125 - Koalas.pdf","sourcePage":3},{"front":"a third of","meaning":"三分之一的……","examples":[{"en":"A third of Australia’s eucalyptus forests have disappeared.","zh":"澳洲三分之一的桉樹林已經消失。"},{"en":"A third of something means one part out of three equal parts.","zh":"三分之一的某物，是指三個相等部分中的一部分。"},{"en":"A third of the class chose biology as their favourite subject.","zh":"班上三分之一的學生選生物為最喜歡的科目。"},{"en":"Losing a third of a forest is serious because it removes a large part of habitat.","zh":"失去三分之一的森林很嚴重，因為它移除了大量棲息地。"},{"en":"This phrase is used to express a clear proportion.","zh":"這個短語用來表達清楚比例。"}],"source":"125 - Koalas.pdf","sourcePage":3},{"front":"eucalyptus forests","meaning":"桉樹林","examples":[{"en":"Australia has lost many eucalyptus forests.","zh":"澳洲已失去許多桉樹林。"},{"en":"Eucalyptus forests are forests mainly made up of eucalyptus trees.","zh":"桉樹林是主要由桉樹組成的森林。"},{"en":"Eucalyptus forests provide koalas with leaves, shelter, and places to rest.","zh":"桉樹林為樹熊提供葉子、庇護和休息地方。"},{"en":"Clearing eucalyptus forests reduces the space where koalas can live safely.","zh":"清除桉樹林會減少樹熊能安全生活的空間。"},{"en":"This phrase describes the habitat that koalas depend on.","zh":"這個短語描述樹熊依賴的棲息地。"}],"source":"125 - Koalas.pdf","sourcePage":3},{"front":"parasites","meaning":"寄生蟲","examples":[{"en":"Koalas have been killed by parasites.","zh":"樹熊曾被寄生蟲殺死。"},{"en":"Parasites are organisms that live on or inside another living thing and harm it.","zh":"寄生蟲是生活在另一生物表面或體內並傷害它的生物。"},{"en":"Fleas are parasites that can live on cats and dogs.","zh":"跳蚤是可以生活在貓狗身上的寄生蟲。"},{"en":"Parasites can weaken animals by taking nutrients or spreading disease.","zh":"寄生蟲可以透過吸取養分或傳播疾病削弱動物。"},{"en":"This phrase refers to a biological threat, not a predator.","zh":"這個短語指生物性威脅，而不是捕食者。"}],"source":"125 - Koalas.pdf","sourcePage":3},{"front":"chlamydia epidemics","meaning":"衣原體疫症","examples":[{"en":"Chlamydia epidemics have killed many koalas.","zh":"衣原體疫症殺死了許多樹熊。"},{"en":"Chlamydia epidemics are widespread outbreaks of chlamydia infection.","zh":"衣原體疫症是衣原體感染的大規模爆發。"},{"en":"An epidemic spreads when many individuals in a population become infected.","zh":"當族群中許多個體受到感染，疫症就會傳播。"},{"en":"Disease epidemics can reduce animal populations even when food is available.","zh":"疾病疫症即使在食物充足時，也可以減少動物數量。"},{"en":"This phrase describes a health threat affecting many koalas at once.","zh":"這個短語描述同時影響許多樹熊的健康威脅。"}],"source":"125 - Koalas.pdf","sourcePage":3},{"front":"tumour-causing retrovirus","meaning":"引致腫瘤的逆轉錄病毒","examples":[{"en":"Koalas have also been affected by a tumour-causing retrovirus.","zh":"樹熊也受到一種引致腫瘤的逆轉錄病毒影響。"},{"en":"A tumour-causing retrovirus is a virus that can lead to the growth of tumours.","zh":"引致腫瘤的逆轉錄病毒，是指可以導致腫瘤生長的病毒。"},{"en":"A disease-causing virus can damage health even when symptoms are hidden at first.","zh":"致病病毒即使症狀起初隱藏，也可以損害健康。"},{"en":"If a virus causes tumours, an animal may appear healthy until the illness becomes serious.","zh":"如果病毒引致腫瘤，動物可能看似健康，直到病情變嚴重。"},{"en":"This phrase explains a hidden biological danger to koalas.","zh":"這個短語解釋樹熊面對的隱藏生物危險。"}],"source":"125 - Koalas.pdf","sourcePage":3},{"front":"ironically","meaning":"諷刺的是","examples":[{"en":"Ironically, many koalas are killed by cars in wildlife sanctuaries.","zh":"諷刺的是，許多樹熊在野生動物保護區被車撞死。"},{"en":"Ironically means in a surprising or opposite way to what people would expect.","zh":"諷刺的是，是指事情以令人意外或與預期相反的方式發生。"},{"en":"Ironically, the umbrella shop closed on the rainiest day of the year.","zh":"諷刺的是，雨傘店在全年最多雨的一天關門。"},{"en":"It is ironic when a place meant to protect animals becomes dangerous for them.","zh":"當一個本應保護動物的地方反而對牠們有危險，這就是諷刺。"},{"en":"This word often introduces a contrast between purpose and result.","zh":"這個詞常引入目的與結果之間的對比。"}],"source":"125 - Koalas.pdf","sourcePage":3},{"front":"wildlife sanctuaries","meaning":"野生動物保護區","examples":[{"en":"Many koalas are killed by cars in wildlife sanctuaries.","zh":"許多樹熊在野生動物保護區被車撞死。"},{"en":"Wildlife sanctuaries are protected places where wild animals are meant to live safely.","zh":"野生動物保護區是讓野生動物安全生活的受保護地方。"},{"en":"A wildlife sanctuary may rescue injured birds and give them space to recover.","zh":"野生動物保護區可能救助受傷鳥類，並給牠們空間恢復。"},{"en":"If roads cross a sanctuary, animals may still face danger from vehicles.","zh":"如果道路穿過保護區，動物仍可能面對車輛危險。"},{"en":"This phrase describes a place intended for protection.","zh":"這個短語描述旨在保護的地方。"}],"source":"125 - Koalas.pdf","sourcePage":4},{"front":"poachers","meaning":"偷獵者","examples":[{"en":"Thousands of koalas are killed by poachers.","zh":"數以千計的樹熊被偷獵者殺死。"},{"en":"Poachers are people who illegally hunt, capture, or kill animals.","zh":"偷獵者是非法捕獵、捕捉或殺死動物的人。"},{"en":"Poachers may target rare animals because they can sell them for money.","zh":"偷獵者可能瞄準稀有動物，因為可以把牠們賣錢。"},{"en":"Poaching harms wildlife populations and can push species closer to danger.","zh":"偷獵會傷害野生動物族群，並可能使物種更接近危險。"},{"en":"This word describes illegal hunters, not ordinary visitors.","zh":"這個詞描述非法獵人，而不是普通遊客。"}],"source":"125 - Koalas.pdf","sourcePage":4},{"front":"be taken illegally as pets","meaning":"被非法捕捉作寵物","examples":[{"en":"Some koalas are taken illegally as pets.","zh":"有些樹熊被非法捕捉作寵物。"},{"en":"To be taken illegally as pets means to be captured against the law and kept by people.","zh":"被非法捕捉作寵物，是指被違法捕捉並由人飼養。"},{"en":"Wild birds may be taken illegally as pets if buyers want rare animals at home.","zh":"如果買家想在家養稀有動物，野鳥可能被非法捕捉作寵物。"},{"en":"Taking wild animals as pets can harm them because their needs are difficult to meet.","zh":"把野生動物作寵物飼養可能傷害牠們，因為牠們的需要很難滿足。"},{"en":"This phrase shows that cuteness can create danger for wildlife.","zh":"這個短語顯示可愛也可以為野生動物帶來危險。"}],"source":"125 - Koalas.pdf","sourcePage":4},{"front":"easily replace them","meaning":"輕易替換牠們","examples":[{"en":"Poachers can easily replace koalas that die.","zh":"偷獵者可以輕易替換死亡的樹熊。"},{"en":"To easily replace them means to get new ones without much difficulty when the old ones are lost.","zh":"輕易替換牠們，是指舊的失去後，不太困難就能取得新的。"},{"en":"A shop can easily replace cheap cups, but not rare handmade bowls.","zh":"商店可以輕易替換便宜杯子，但不能輕易替換稀有手製碗。"},{"en":"If criminals can easily replace captured animals, illegal trade may continue.","zh":"如果罪犯能輕易替換被捕動物，非法交易可能繼續。"},{"en":"This phrase suggests that the animals are treated like objects, not living beings.","zh":"這個短語暗示動物被當作物品，而不是生命。"}],"source":"125 - Koalas.pdf","sourcePage":4},{"front":"bushfires","meaning":"山火；叢林火災","examples":[{"en":"Bushfires pose another threat to koalas.","zh":"山火對樹熊構成另一威脅。"},{"en":"Bushfires are large fires that burn through bushland, forests, or dry natural areas.","zh":"山火是燃燒灌木林、森林或乾燥自然地區的大型火災。"},{"en":"Families in rural areas may prepare emergency bags during bushfire season.","zh":"鄉郊家庭在山火季節可能準備緊急袋。"},{"en":"Bushfires can destroy food, shelter, and safe movement routes for animals.","zh":"山火可以破壞動物的食物、庇護所和安全移動路線。"},{"en":"This word is especially common in Australian environmental contexts.","zh":"這個詞在澳洲環境背景中特別常見。"}],"source":"125 - Koalas.pdf","sourcePage":4},{"front":"pose another threat","meaning":"構成另一威脅","examples":[{"en":"Bushfires pose another threat to koalas.","zh":"山火對樹熊構成另一威脅。"},{"en":"To pose another threat means to create one more danger in addition to existing dangers.","zh":"構成另一威脅，是指在已有危險之外再造成一個危險。"},{"en":"Rising rent poses another threat to small shops already facing weak sales.","zh":"租金上升對已面對銷售疲弱的小店構成另一威脅。"},{"en":"When a species faces several problems, each new threat makes survival harder.","zh":"當物種面對幾個問題，每個新威脅都令生存更困難。"},{"en":"This phrase adds one more risk to a list of risks.","zh":"這個短語把另一個風險加入風險列表中。"}],"source":"125 - Koalas.pdf","sourcePage":4},{"front":"horrific fires","meaning":"可怕的火災","examples":[{"en":"Horrific fires recently killed many koalas.","zh":"最近可怕的火災殺死了許多樹熊。"},{"en":"Horrific fires are extremely terrible fires that cause serious damage or suffering.","zh":"可怕的火災是極其嚴重、造成重大破壞或痛苦的火災。"},{"en":"A horrific fire in an apartment block can leave many families homeless.","zh":"公寓大廈中的可怕火災可以令許多家庭無家可歸。"},{"en":"Horrific fires destroy habitats quickly and can injure animals that cannot escape.","zh":"可怕的火災迅速摧毀棲息地，並可傷害無法逃走的動物。"},{"en":"This phrase expresses both scale and emotional shock.","zh":"這個短語同時表達規模和情緒震撼。"}],"source":"125 - Koalas.pdf","sourcePage":4},{"front":"rage in","meaning":"在……肆虐","examples":[{"en":"The bushfires raged in New South Wales.","zh":"山火在新南威爾斯州肆虐。"},{"en":"To rage in a place means to burn, spread, or continue violently there.","zh":"在某地肆虐，是指在那裡猛烈燃燒、蔓延或持續。"},{"en":"A storm may rage in a coastal town for hours.","zh":"暴風雨可能在海邊小鎮肆虐數小時。"},{"en":"When fires rage in forests, animals may lose safe routes to escape.","zh":"當火災在森林肆虐，動物可能失去安全逃生路線。"},{"en":"This phrase suggests uncontrolled and intense force.","zh":"這個短語暗示失控而強烈的力量。"}],"source":"125 - Koalas.pdf","sourcePage":4},{"front":"New South Wales","meaning":"新南威爾斯州","examples":[{"en":"The fires raged in New South Wales.","zh":"火災在新南威爾斯州肆虐。"},{"en":"New South Wales is used here as the Australian state where the fires occurred.","zh":"新南威爾斯州在此指火災發生的澳洲州份。"},{"en":"A news report may mention New South Wales when discussing Australian bushfires.","zh":"新聞報道討論澳洲山火時，可能提到新南威爾斯州。"},{"en":"Naming the place helps readers understand where the koalas were affected.","zh":"說出地點幫助讀者理解樹熊在哪裡受影響。"},{"en":"This phrase gives a specific geographical setting.","zh":"這個短語提供具體地理背景。"}],"source":"125 - Koalas.pdf","sourcePage":4},{"front":"be taken into sanctuaries and shelters","meaning":"被送往保護區和收容所","examples":[{"en":"Injured koalas were taken into sanctuaries and shelters.","zh":"受傷樹熊被送往保護區和收容所。"},{"en":"To be taken into sanctuaries and shelters means to be brought to safe places for care.","zh":"被送往保護區和收容所，是指被帶到安全地方接受照顧。"},{"en":"After a flood, injured dogs may be taken into shelters by rescue workers.","zh":"洪水後，受傷狗隻可能被救援人員送往收容所。"},{"en":"Animals are taken into sanctuaries when they cannot survive safely on their own.","zh":"當動物不能靠自己安全生存時，就會被送往保護區。"},{"en":"This phrase describes rescue and protection after danger.","zh":"這個短語描述危險後的拯救和保護。"}],"source":"125 - Koalas.pdf","sourcePage":4},{"front":"burn their paws","meaning":"燒傷腳掌","examples":[{"en":"Many koalas had burnt their paws on the embers.","zh":"許多樹熊在餘燼上燒傷了腳掌。"},{"en":"To burn their paws means to injure the soft parts of their feet with heat or fire.","zh":"燒傷腳掌，是指因高溫或火而傷到腳部柔軟部分。"},{"en":"A dog may burn its paws on very hot pavement in summer.","zh":"狗隻在夏天很熱的行人路上可能燒傷腳掌。"},{"en":"Burnt paws make it painful for animals to climb, walk, or escape.","zh":"腳掌燒傷會令動物攀爬、行走或逃走時感到痛楚。"},{"en":"This phrase shows the physical harm caused by fires.","zh":"這個短語顯示火災造成的身體傷害。"}],"source":"125 - Koalas.pdf","sourcePage":4},{"front":"glowing embers","meaning":"發紅餘燼","examples":[{"en":"Koalas burnt their paws on glowing embers.","zh":"樹熊在發紅餘燼上燒傷腳掌。"},{"en":"Glowing embers are hot pieces of wood or material that still shine after a fire.","zh":"發紅餘燼是火後仍然發熱發光的木塊或物料。"},{"en":"Campers should not step on glowing embers because they can still burn skin.","zh":"露營者不應踩在發紅餘燼上，因為它們仍能燒傷皮膚。"},{"en":"Embers can remain dangerous even after flames are gone.","zh":"即使火焰已消失，餘燼仍可能危險。"},{"en":"This phrase explains why the ground after a fire can still injure animals.","zh":"這個短語解釋為何火災後地面仍會傷害動物。"}],"source":"125 - Koalas.pdf","sourcePage":5},{"front":"the species should recover","meaning":"該物種應能恢復","examples":[{"en":"Zoologists say that the species should recover.","zh":"動物學家表示該物種應能恢復。"},{"en":"The species should recover means the animal population is expected to improve again.","zh":"該物種應能恢復，是指動物族群預期會再次改善。"},{"en":"A plant species may recover after rain returns and new shoots grow.","zh":"雨水回來並長出新芽後，植物物種可能恢復。"},{"en":"Recovery is more likely when food and habitat return after damage.","zh":"當食物和棲息地在破壞後回復，恢復更有可能。"},{"en":"This phrase expresses cautious hope about survival.","zh":"這個短語表達對生存的謹慎希望。"}],"source":"125 - Koalas.pdf","sourcePage":5},{"front":"be aided by","meaning":"得到……幫助","examples":[{"en":"The koalas will be aided by the fast-growing eucalyptus.","zh":"樹熊會得到生長迅速的桉樹幫助。"},{"en":"To be aided by something means to be helped by it.","zh":"得到某物幫助，是指受到它的協助。"},{"en":"A student may be aided by clear notes before an exam.","zh":"學生考試前可能得到清晰筆記的幫助。"},{"en":"Animal recovery can be aided by the return of food plants.","zh":"動物恢復可以得到食物植物回復的幫助。"},{"en":"This phrase is a formal way to say “be helped by.”","zh":"這個短語是 “be helped by” 的正式說法。"}],"source":"125 - Koalas.pdf","sourcePage":5},{"front":"regenerate after the fires","meaning":"在火災後重新生長","examples":[{"en":"The eucalyptus is already regenerating after the fires.","zh":"桉樹已經在火災後重新生長。"},{"en":"To regenerate after the fires means to grow back after being damaged by fire.","zh":"在火災後重新生長，是指被火破壞後再次生長。"},{"en":"Grass may regenerate after a fire if roots remain alive underground.","zh":"如果根部仍在地下存活，草可能在火災後重新生長。"},{"en":"When food plants regenerate, animals have a better chance of returning.","zh":"當食物植物重新生長，動物較有機會回來。"},{"en":"This phrase describes natural recovery after destruction.","zh":"這個短語描述破壞後的自然恢復。"}],"source":"125 - Koalas.pdf","sourcePage":5},{"front":"main threat to","meaning":"對……的主要威脅","examples":[{"en":"The main threat to koalas’ survival is their slow reproductive rate.","zh":"對樹熊生存的主要威脅是牠們緩慢的繁殖率。"},{"en":"The main threat to something is the biggest or most important danger facing it.","zh":"對某事的主要威脅，是指它面對的最大或最重要危險。"},{"en":"The main threat to a small shop may be rising rent.","zh":"對小店的主要威脅可能是租金上升。"},{"en":"Identifying the main threat helps people decide what problem to solve first.","zh":"找出主要威脅有助人們決定先解決甚麼問題。"},{"en":"This phrase ranks one danger as more serious than others.","zh":"這個短語把一個危險列為比其他更嚴重。"}],"source":"125 - Koalas.pdf","sourcePage":5},{"front":"survival","meaning":"生存","examples":[{"en":"Their slow reproductive rate threatens their survival.","zh":"牠們緩慢的繁殖率威脅牠們的生存。"},{"en":"Survival means continuing to live or exist despite danger or difficulty.","zh":"生存是指在危險或困難中繼續活着或存在。"},{"en":"Clean water is essential for the survival of people after a disaster.","zh":"災難後，清潔食水對人的生存至關重要。"},{"en":"A species’ survival depends on food, habitat, health, and reproduction.","zh":"物種的生存取決於食物、棲息地、健康和繁殖。"},{"en":"This word is used when life or continued existence is at risk.","zh":"當生命或持續存在有風險時，會使用這個詞。"}],"source":"125 - Koalas.pdf","sourcePage":5},{"front":"slow reproductive rate","meaning":"緩慢繁殖率","examples":[{"en":"Koalas have a slow reproductive rate.","zh":"樹熊有緩慢繁殖率。"},{"en":"A slow reproductive rate means a species produces offspring slowly or in small numbers.","zh":"緩慢繁殖率，是指一個物種產生後代速度慢或數量少。"},{"en":"Animals with a slow reproductive rate recover more slowly after disease or fire.","zh":"繁殖率慢的動物在疾病或火災後恢復較慢。"},{"en":"If many adults die, a slow reproductive rate makes population recovery difficult.","zh":"如果許多成年個體死亡，緩慢繁殖率會令族群恢復困難。"},{"en":"This phrase explains why koala numbers cannot quickly bounce back.","zh":"這個短語解釋為何樹熊數量不能迅速回升。"}],"source":"125 - Koalas.pdf","sourcePage":5},{"front":"reproductive lifespan","meaning":"繁殖壽命","examples":[{"en":"Koalas produce only one baby a year over a reproductive lifespan of about nine years.","zh":"樹熊在約九年的繁殖壽命中每年只生一隻幼崽。"},{"en":"Reproductive lifespan is the period during which an animal can produce offspring.","zh":"繁殖壽命是動物能產生後代的時期。"},{"en":"A species with a short reproductive lifespan may have fewer chances to replace lost individuals.","zh":"繁殖壽命短的物種，替補失去個體的機會可能較少。"},{"en":"If reproduction is slow and the reproductive lifespan is limited, population growth is weak.","zh":"如果繁殖緩慢而繁殖壽命有限，族群增長就會較弱。"},{"en":"This phrase links biology with long-term survival.","zh":"這個短語把生物學與長期生存連接起來。"}],"source":"125 - Koalas.pdf","sourcePage":5},{"front":"the latest problem","meaning":"最新問題","examples":[{"en":"The latest problem for koalas is more insidious.","zh":"樹熊面對的最新問題更隱伏難察。"},{"en":"The latest problem means the newest difficulty or danger in a situation.","zh":"最新問題是某情況中最新出現的困難或危險。"},{"en":"The latest problem for the school is a shortage of substitute teachers.","zh":"學校面對的最新問題是代課老師短缺。"},{"en":"New problems can be harder to solve when old problems remain.","zh":"當舊問題仍未解決，新問題可能更難處理。"},{"en":"This phrase introduces a recent or newly noticed issue.","zh":"這個短語引入近期或新被注意到的問題。"}],"source":"125 - Koalas.pdf","sourcePage":5},{"front":"more insidious","meaning":"更隱伏難察","examples":[{"en":"The latest problem for the species is perhaps more insidious.","zh":"該物種面對的最新問題也許更隱伏難察。"},{"en":"More insidious means more dangerous because it is hidden, gradual, or not obvious at first.","zh":"更隱伏難察，是指因隱藏、漸進或起初不明顯而更危險。"},{"en":"Constant stress can be more insidious than one dramatic accident because it slowly damages health.","zh":"持續壓力可能比一次戲劇性意外更隱伏難察，因為它慢慢損害健康。"},{"en":"An insidious problem may be ignored until serious harm has already happened.","zh":"隱伏難察的問題可能被忽視，直到已造成嚴重傷害。"},{"en":"This phrase describes danger that is quiet rather than obvious.","zh":"這個短語描述安靜而非明顯的危險。"}],"source":"125 - Koalas.pdf","sourcePage":5},{"front":"plush, grey fur","meaning":"毛茸茸的灰色皮毛","examples":[{"en":"Koalas have plush, grey fur.","zh":"樹熊有毛茸茸的灰色皮毛。"},{"en":"Plush, grey fur means soft, thick, grey hair covering an animal’s body.","zh":"毛茸茸的灰色皮毛，是指覆蓋動物身體的柔軟、厚實灰色毛。"},{"en":"A soft toy may be made with plush grey fabric to look like a koala.","zh":"毛公仔可能用毛茸茸的灰色布料製成，使它看起來像樹熊。"},{"en":"Soft fur can make an animal look cute and touchable, even when touching is harmful.","zh":"柔軟皮毛可以令動物看起來可愛又想摸，即使觸摸會有害。"},{"en":"This phrase helps explain why people want to cuddle koalas.","zh":"這個短語幫助解釋為何人們想抱樹熊。"}],"source":"125 - Koalas.pdf","sourcePage":5},{"front":"dark amber eyes","meaning":"深琥珀色眼睛","examples":[{"en":"Koalas have dark amber eyes.","zh":"樹熊有深琥珀色眼睛。"},{"en":"Dark amber eyes are eyes with a deep yellow-brown colour.","zh":"深琥珀色眼睛，是指深黃褐色的眼睛。"},{"en":"A cat with dark amber eyes may look gentle and serious at the same time.","zh":"有深琥珀色眼睛的貓，可能同時看起來溫柔又認真。"},{"en":"Eye colour can affect how people emotionally respond to an animal.","zh":"眼睛顏色會影響人們對動物的情感反應。"},{"en":"This phrase adds to the image of koalas as soft and appealing.","zh":"這個短語增加樹熊柔和而吸引人的形象。"}],"source":"125 - Koalas.pdf","sourcePage":6},{"front":"button nose","meaning":"小巧圓鼻","examples":[{"en":"The koala’s button nose makes it look especially cute.","zh":"樹熊的小巧圓鼻令牠看起來特別可愛。"},{"en":"A button nose is a small, round nose that looks neat and cute.","zh":"小巧圓鼻是細小、圓圓的鼻子，看起來整齊可愛。"},{"en":"Children’s storybooks often draw animals with button noses to make them lovable.","zh":"兒童故事書常畫有小巧圓鼻的動物，使牠們更討人喜歡。"},{"en":"Cute features can encourage people to treat wild animals like toys.","zh":"可愛特徵可能鼓勵人們把野生動物當成玩具。"},{"en":"This phrase helps explain the koala’s cuddly image.","zh":"這個短語幫助解釋樹熊令人想抱的形象。"}],"source":"125 - Koalas.pdf","sourcePage":6},{"front":"the very image of","meaning":"正是……的形象","examples":[{"en":"Koalas are the very image of cuddliness.","zh":"樹熊正是可愛得令人想抱的形象。"},{"en":"The very image of something means the perfect example or picture of that quality.","zh":"正是某種特質的形象，是指那種特質的完美例子或畫面。"},{"en":"A clean, quiet library may be the very image of calm study.","zh":"乾淨安靜的圖書館可能正是平靜學習的形象。"},{"en":"When an animal is the very image of cuteness, people may forget it is still wild.","zh":"當動物正是可愛的形象，人們可能忘記牠仍是野生動物。"},{"en":"This phrase strongly links someone or something with one clear quality.","zh":"這個短語強烈把某人或某物與一種清晰特質連接起來。"}],"source":"125 - Koalas.pdf","sourcePage":6},{"front":"cuddliness","meaning":"可愛得令人想抱","examples":[{"en":"Koalas are often seen as the image of cuddliness.","zh":"樹熊常被視為可愛得令人想抱的形象。"},{"en":"Cuddliness is the quality of looking soft, cute, and pleasant to hug.","zh":"可愛得令人想抱，是指看起來柔軟、可愛、令人想擁抱的特質。"},{"en":"A teddy bear is designed to create a feeling of cuddliness.","zh":"泰迪熊的設計就是為了營造可愛得令人想抱的感覺。"},{"en":"Cuddliness can make people want to touch animals even when they should not.","zh":"可愛感會令人想觸摸動物，即使他們不應該這樣做。"},{"en":"This word describes appearance and emotional appeal, not the animal’s actual needs.","zh":"這個詞描述外表和情感吸引力，而不是動物的實際需要。"}],"source":"125 - Koalas.pdf","sourcePage":6},{"front":"wildlife parks","meaning":"野生動物園","examples":[{"en":"Australian zoos and wildlife parks use koalas to attract visitors.","zh":"澳洲動物園和野生動物園利用樹熊吸引遊客。"},{"en":"Wildlife parks are places where people can see animals, often in more natural-looking settings than ordinary cages.","zh":"野生動物園是讓人觀看動物的地方，環境通常比普通籠子更接近自然。"},{"en":"A wildlife park may teach visitors about conservation and animal behaviour.","zh":"野生動物園可能教遊客認識保育和動物行為。"},{"en":"Wildlife parks can help education, but they must avoid stressing animals.","zh":"野生動物園可以幫助教育，但必須避免令動物受壓。"},{"en":"This phrase refers to visitor attractions involving wild animals.","zh":"這個短語指涉及野生動物的遊客景點。"}],"source":"125 - Koalas.pdf","sourcePage":6},{"front":"take advantage of","meaning":"利用","examples":[{"en":"Wildlife parks have taken advantage of koalas’ uncomplaining attitudes.","zh":"野生動物園利用了樹熊逆來順受的態度。"},{"en":"To take advantage of someone or something means to use them for benefit, sometimes unfairly.","zh":"利用某人或某物，是指為了好處而使用他們，有時是不公平地使用。"},{"en":"A boss may take advantage of a quiet worker by giving them extra unpaid tasks.","zh":"老闆可能利用沉默的員工，把額外無薪工作交給他。"},{"en":"People can take advantage of an animal’s gentleness if the animal does not resist.","zh":"如果動物不反抗，人們可能利用牠的溫馴。"},{"en":"This phrase often suggests exploitation, not just ordinary use.","zh":"這個短語常暗示剝削，而不只是普通使用。"}],"source":"125 - Koalas.pdf","sourcePage":6},{"front":"uncomplaining attitudes","meaning":"逆來順受的態度","examples":[{"en":"Koalas’ uncomplaining attitudes make them easy to exploit.","zh":"樹熊逆來順受的態度令牠們容易被剝削。"},{"en":"Uncomplaining attitudes mean accepting discomfort without protesting.","zh":"逆來順受的態度，是指接受不適而不抗議。"},{"en":"A patient with an uncomplaining attitude may hide pain instead of asking for help.","zh":"有逆來順受態度的病人可能隱藏痛楚，而不是求助。"},{"en":"If someone never complains, others may fail to notice that they are suffering.","zh":"如果某人從不投訴，其他人可能未能注意到他正在受苦。"},{"en":"This phrase shows why koalas’ quietness can become dangerous for them.","zh":"這個短語顯示樹熊的安靜為何會對牠們變得危險。"}],"source":"125 - Koalas.pdf","sourcePage":6},{"front":"charge visitors to","meaning":"向遊客收費以……","examples":[{"en":"Wildlife parks charge visitors to be photographed with koalas.","zh":"野生動物園向遊客收費，讓他們與樹熊合照。"},{"en":"To charge visitors to do something means to ask them to pay money for that activity.","zh":"向遊客收費以做某事，是指要求遊客為該活動付款。"},{"en":"A museum may charge visitors to join a special guided tour.","zh":"博物館可能向遊客收費，讓他們參加特別導賞團。"},{"en":"Charging visitors for animal photos can create income but also pressure animals.","zh":"向遊客收費拍動物照片可以創造收入，但也會令動物受壓。"},{"en":"This phrase links a visitor activity with payment.","zh":"這個短語把遊客活動與付款連接起來。"}],"source":"125 - Koalas.pdf","sourcePage":6},{"front":"be photographed hugging","meaning":"被拍下擁抱……的照片","examples":[{"en":"Visitors pay to be photographed hugging koalas.","zh":"遊客付款，讓自己被拍下擁抱樹熊的照片。"},{"en":"To be photographed hugging an animal means to have a picture taken while holding it closely.","zh":"被拍下擁抱動物的照片，是指抱着動物時被拍照。"},{"en":"Tourists may want to be photographed hugging a famous mascot at a theme park.","zh":"遊客可能想在主題公園被拍下擁抱著名吉祥物的照片。"},{"en":"Being photographed hugging wildlife may look harmless but can stress the animal.","zh":"被拍下擁抱野生動物的照片看似無害，但可能令動物受壓。"},{"en":"This phrase describes a photo opportunity involving physical contact.","zh":"這個短語描述涉及身體接觸的拍照機會。"}],"source":"125 - Koalas.pdf","sourcePage":6},{"front":"furry bundles","meaning":"毛茸茸的一團","examples":[{"en":"The passage describes koalas as furry bundles.","zh":"篇章把樹熊描述為毛茸茸的一團。"},{"en":"Furry bundles are small-looking, soft, round animals or objects covered in fur.","zh":"毛茸茸的一團，是指看起來小巧、柔軟、圓圓且覆滿毛的動物或物件。"},{"en":"A sleeping kitten can look like a furry bundle on a blanket.","zh":"睡在毛毯上的小貓可能看起來像毛茸茸的一團。"},{"en":"Calling koalas furry bundles makes them sound cute, soft, and harmless.","zh":"稱樹熊為毛茸茸的一團，令牠們聽起來可愛、柔軟又無害。"},{"en":"This phrase explains why visitors may forget that koalas are sensitive wild animals.","zh":"這個短語解釋為何遊客可能忘記樹熊是敏感的野生動物。"}],"source":"125 - Koalas.pdf","sourcePage":6},{"front":"realise how cruel this is","meaning":"意識到這有多殘忍","examples":[{"en":"People may not realise how cruel koala cuddling is.","zh":"人們可能沒有意識到抱樹熊有多殘忍。"},{"en":"To realise how cruel this is means to understand how much suffering an action causes.","zh":"意識到這有多殘忍，是指明白某行為造成多少痛苦。"},{"en":"Children may not realise how cruel teasing is until they see someone cry.","zh":"孩子可能直到看見別人哭，才意識到取笑有多殘忍。"},{"en":"People often fail to realise cruelty when the victim stays quiet.","zh":"當受害者保持沉默，人們常未能意識到殘忍。"},{"en":"This phrase asks readers to look beyond the cute appearance of the activity.","zh":"這個短語要求讀者看穿活動可愛外表背後的問題。"}],"source":"125 - Koalas.pdf","sourcePage":6},{"front":"delicate disposition","meaning":"敏感脆弱的性情","examples":[{"en":"The koala’s delicate disposition makes constant handling harmful.","zh":"樹熊敏感脆弱的性情令頻繁抱摸有害。"},{"en":"A delicate disposition is a sensitive nature that reacts easily to stress or disturbance.","zh":"敏感脆弱的性情，是指容易受壓力或干擾影響的性格。"},{"en":"A child with a delicate disposition may become upset in very noisy places.","zh":"性情敏感的孩子可能在非常嘈雜的地方變得不安。"},{"en":"Animals with delicate dispositions need calm routines and careful handling.","zh":"性情敏感的動物需要平靜常規和小心處理。"},{"en":"This phrase explains why koalas may suffer even when they do not fight back.","zh":"這個短語解釋為何樹熊即使不反抗也可能受苦。"}],"source":"125 - Koalas.pdf","sourcePage":7},{"front":"constant handling","meaning":"不斷被人接觸；頻繁抱摸","examples":[{"en":"Constant handling can harm koalas.","zh":"頻繁抱摸會傷害樹熊。"},{"en":"Constant handling means being touched, held, or moved again and again.","zh":"不斷被人接觸，是指一次又一次被觸摸、抱起或移動。"},{"en":"A fragile museum object can be damaged by constant handling from visitors.","zh":"脆弱的博物館物件可能因遊客不斷觸摸而受損。"},{"en":"Constant handling can stress animals because they cannot rest naturally.","zh":"頻繁抱摸會令動物受壓，因為牠們不能自然休息。"},{"en":"This phrase shows that repeated contact, not just one touch, is the problem.","zh":"這個短語顯示問題在於重複接觸，而不只是一次觸摸。"}],"source":"125 - Koalas.pdf","sourcePage":7},{"front":"push something beyond its limits","meaning":"令……超出極限","examples":[{"en":"Constant handling can push a koala’s physiology beyond its limits.","zh":"頻繁抱摸會令樹熊的生理狀態超出極限。"},{"en":"To push something beyond its limits means to force it to do more than it can safely handle.","zh":"令某物超出極限，是指迫使它承受超過安全能力的事情。"},{"en":"Studying all night can push a student’s body beyond its limits before an exam.","zh":"通宵溫習可能在考試前令學生身體超出極限。"},{"en":"If stress pushes an animal beyond its limits, illness may follow.","zh":"如果壓力令動物超出極限，之後可能生病。"},{"en":"This phrase warns that too much pressure can cause breakdown.","zh":"這個短語警告過多壓力會造成崩潰。"}],"source":"125 - Koalas.pdf","sourcePage":7},{"front":"precariously balanced physiology","meaning":"脆弱而勉強平衡的生理狀態","examples":[{"en":"Koalas have a precariously balanced physiology.","zh":"樹熊有脆弱而勉強平衡的生理狀態。"},{"en":"Precariously balanced physiology means a body system that works only under narrow, easily disturbed conditions.","zh":"脆弱而勉強平衡的生理狀態，是指身體系統只能在狹窄且容易被打亂的條件下正常運作。"},{"en":"A person with serious allergies may have a health balance that is easily disturbed.","zh":"有嚴重過敏的人，健康平衡可能很容易被干擾。"},{"en":"When physiology is precariously balanced, stress, poor food, or illness can cause serious problems.","zh":"當生理狀態脆弱而勉強平衡，壓力、食物不足或疾病都可能造成嚴重問題。"},{"en":"This phrase explains why koalas need quiet and careful care.","zh":"這個短語解釋為何樹熊需要安靜和小心照顧。"}],"source":"125 - Koalas.pdf","sourcePage":7},{"front":"foliage","meaning":"葉子；植物葉叢","examples":[{"en":"Koalas eat large amounts of eucalyptus foliage each day.","zh":"樹熊每天吃大量桉樹葉。"},{"en":"Foliage means the leaves of plants or trees.","zh":"葉叢是指植物或樹木的葉子。"},{"en":"Gardeners trim dense foliage so sunlight can reach smaller plants.","zh":"園丁修剪茂密葉叢，使陽光能照到較小植物。"},{"en":"Animals that depend on one kind of foliage suffer when those trees disappear.","zh":"依賴一種葉子的動物，在那些樹消失時會受苦。"},{"en":"This word is more formal than simply saying leaves.","zh":"這個詞比單純說 leaves 更正式。"}],"source":"125 - Koalas.pdf","sourcePage":7},{"front":"certain eucalyptus species","meaning":"某些桉樹品種","examples":[{"en":"Koalas eat foliage from certain eucalyptus species.","zh":"樹熊吃某些桉樹品種的葉子。"},{"en":"Certain eucalyptus species means particular types of eucalyptus trees, not all of them.","zh":"某些桉樹品種，是指特定種類的桉樹，而不是所有桉樹。"},{"en":"A picky animal may eat only certain plant species and ignore others.","zh":"挑食的動物可能只吃某些植物品種，而忽略其他。"},{"en":"If only certain eucalyptus species are suitable, habitat loss becomes more serious.","zh":"如果只有某些桉樹品種適合，棲息地流失就變得更嚴重。"},{"en":"This phrase shows that koalas’ diet is highly specialised.","zh":"這個短語顯示樹熊飲食高度專門化。"}],"source":"125 - Koalas.pdf","sourcePage":7},{"front":"be packed with","meaning":"充滿","examples":[{"en":"The tough leaves are packed with cellulose and toxins.","zh":"堅韌的葉子充滿纖維素和毒素。"},{"en":"To be packed with something means to contain a large amount of it.","zh":"充滿某物，是指含有大量該物。"},{"en":"A busy lunch box may be packed with fruit, rice, and snacks.","zh":"豐富的午餐盒可能充滿水果、飯和小食。"},{"en":"If food is packed with sugar, eating too much can affect health.","zh":"如果食物充滿糖分，吃太多會影響健康。"},{"en":"This phrase often suggests something is full of many substances or details.","zh":"這個短語常暗示某物裝滿許多物質或細節。"}],"source":"125 - Koalas.pdf","sourcePage":7},{"front":"cellulose","meaning":"纖維素","examples":[{"en":"Eucalyptus leaves are packed with cellulose.","zh":"桉樹葉充滿纖維素。"},{"en":"Cellulose is a tough plant fibre found in cell walls.","zh":"纖維素是植物細胞壁中的堅韌植物纖維。"},{"en":"Humans cannot digest cellulose easily, but some animals use bacteria to break it down.","zh":"人類不容易消化纖維素，但有些動物用細菌分解它。"},{"en":"Food high in cellulose can require a specialised digestive system.","zh":"富含纖維素的食物可能需要特殊消化系統。"},{"en":"This word helps explain why koala digestion is unusual.","zh":"這個詞幫助解釋為何樹熊消化很不尋常。"}],"source":"125 - Koalas.pdf","sourcePage":7},{"front":"tannins","meaning":"單寧","examples":[{"en":"Eucalyptus leaves contain tannins.","zh":"桉樹葉含有單寧。"},{"en":"Tannins are bitter plant chemicals found in leaves, bark, tea, and some fruits.","zh":"單寧是葉、樹皮、茶和某些水果中的苦味植物化學物質。"},{"en":"Strong tea can taste dry or bitter because it contains tannins.","zh":"濃茶可能因含有單寧而有乾澀或苦味。"},{"en":"Tannins can make leaves harder for animals to digest.","zh":"單寧可以令葉子對動物來說更難消化。"},{"en":"This word names one of the chemical challenges in eucalyptus leaves.","zh":"這個詞指出桉樹葉中的其中一種化學挑戰。"}],"source":"125 - Koalas.pdf","sourcePage":7},{"front":"aromatic oils","meaning":"芳香油","examples":[{"en":"Eucalyptus leaves contain aromatic oils.","zh":"桉樹葉含有芳香油。"},{"en":"Aromatic oils are strong-smelling oils naturally produced by plants.","zh":"芳香油是植物自然產生、有強烈氣味的油。"},{"en":"Mint leaves contain aromatic oils that make them smell fresh.","zh":"薄荷葉含有芳香油，使它們聞起來清新。"},{"en":"Aromatic oils can attract humans but may be difficult for animals to process.","zh":"芳香油可以吸引人類，但對動物來說可能難以處理。"},{"en":"This phrase explains part of the strong smell and chemical content of eucalyptus leaves.","zh":"這個短語解釋桉樹葉強烈氣味和化學成分的一部分。"}],"source":"125 - Koalas.pdf","sourcePage":7},{"front":"precursors of toxic cyanides","meaning":"有毒氰化物的前體","examples":[{"en":"The leaves contain precursors of toxic cyanides.","zh":"這些葉子含有有毒氰化物的前體。"},{"en":"Precursors of toxic cyanides are substances that can lead to or form poisonous cyanide compounds.","zh":"有毒氰化物的前體，是指可以導致或形成有毒氰化物化合物的物質。"},{"en":"Some harmless-looking plants contain chemicals that become toxic after digestion.","zh":"有些看似無害的植物含有消化後會變成有毒的化學物質。"},{"en":"If food contains toxic precursors, the body needs ways to process them safely.","zh":"如果食物含有毒性前體，身體需要方法安全處理它們。"},{"en":"This phrase explains why eucalyptus leaves are chemically difficult to eat.","zh":"這個短語解釋為何桉樹葉在化學上很難食用。"}],"source":"125 - Koalas.pdf","sourcePage":7},{"front":"handle this cocktail","meaning":"處理這種複雜混合物","examples":[{"en":"Koalas need a specialised digestive system to handle this cocktail.","zh":"樹熊需要特殊消化系統來處理這種複雜混合物。"},{"en":"To handle this cocktail means to deal with a complex mixture of substances safely.","zh":"處理這種複雜混合物，是指安全應對多種物質混在一起的情況。"},{"en":"A hospital lab needs special equipment to handle a dangerous chemical mixture.","zh":"醫院實驗室需要特別設備來處理危險化學混合物。"},{"en":"Koalas need special digestion because eucalyptus leaves contain fibre and toxins together.","zh":"樹熊需要特殊消化，因為桉樹葉同時含有纖維和毒素。"},{"en":"Here, cocktail means a mixture, not an alcoholic drink.","zh":"在這裡，cocktail 指混合物，而不是酒精飲品。"}],"source":"125 - Koalas.pdf","sourcePage":8},{"front":"specialised digestive system","meaning":"特殊消化系統","examples":[{"en":"Koalas have a specialised digestive system.","zh":"樹熊有特殊消化系統。"},{"en":"A specialised digestive system is a body system adapted to process a particular kind of food.","zh":"特殊消化系統，是適應處理特定食物的身體系統。"},{"en":"Cows have specialised digestion that helps them use tough grass.","zh":"牛有特殊消化系統，幫助牠們利用堅韌草料。"},{"en":"Koalas need specialised digestion because their food is fibrous and toxic.","zh":"樹熊需要特殊消化，因為牠們的食物含纖維又有毒素。"},{"en":"This phrase links the koala’s diet with its unusual body structure.","zh":"這個短語把樹熊飲食與其不尋常身體結構連接起來。"}],"source":"125 - Koalas.pdf","sourcePage":8},{"front":"cellulose-digesting bacteria","meaning":"消化纖維素的細菌","examples":[{"en":"Cellulose-digesting bacteria help koalas digest eucalyptus leaves.","zh":"消化纖維素的細菌幫助樹熊消化桉樹葉。"},{"en":"Cellulose-digesting bacteria are tiny organisms that break down tough plant fibre.","zh":"消化纖維素的細菌是分解堅韌植物纖維的微小生物。"},{"en":"Some animals depend on gut bacteria to digest food they cannot break down alone.","zh":"有些動物依靠腸道細菌消化牠們不能單獨分解的食物。"},{"en":"Without these bacteria, koalas could not get enough nutrition from eucalyptus leaves.","zh":"沒有這些細菌，樹熊無法從桉樹葉取得足夠營養。"},{"en":"This phrase explains the biological help inside the koala’s gut.","zh":"這個短語解釋樹熊腸道內的生物幫助。"}],"source":"125 - Koalas.pdf","sourcePage":8},{"front":"caecum","meaning":"盲腸","examples":[{"en":"Bacteria in the caecum break down fibre.","zh":"盲腸中的細菌分解纖維。"},{"en":"The caecum is a part of the intestine where some animals ferment and digest plant material.","zh":"盲腸是腸道的一部分，有些動物在其中發酵並消化植物材料。"},{"en":"A biology teacher may explain the caecum when teaching herbivore digestion.","zh":"生物老師教授草食動物消化時，可能會解釋盲腸。"},{"en":"In koalas, the caecum helps process tough eucalyptus leaves.","zh":"在樹熊身上，盲腸幫助處理堅韌的桉樹葉。"},{"en":"This word names an important digestive organ.","zh":"這個詞命名一個重要消化器官。"}],"source":"125 - Koalas.pdf","sourcePage":8},{"front":"break down fibre","meaning":"分解纖維","examples":[{"en":"Bacteria in the caecum break down fibre.","zh":"盲腸中的細菌分解纖維。"},{"en":"To break down fibre means to split tough plant material into simpler substances.","zh":"分解纖維，是指把堅韌植物材料分解成較簡單物質。"},{"en":"Some gut bacteria break down fibre that humans cannot digest alone.","zh":"有些腸道細菌會分解人類不能單獨消化的纖維。"},{"en":"Breaking down fibre helps animals extract energy from leaves and grass.","zh":"分解纖維幫助動物從葉和草中提取能量。"},{"en":"This phrase describes an important step in digestion.","zh":"這個短語描述消化中的重要步驟。"}],"source":"125 - Koalas.pdf","sourcePage":8},{"front":"specially adapted gut and liver","meaning":"特別適應的腸道和肝臟","examples":[{"en":"A specially adapted gut and liver process the toxins.","zh":"特別適應的腸道和肝臟處理毒素。"},{"en":"A specially adapted gut and liver are digestive organs that have developed to handle unusual food.","zh":"特別適應的腸道和肝臟，是已發展出來處理不尋常食物的消化器官。"},{"en":"Animals that eat toxic plants may need specially adapted organs to stay alive.","zh":"吃有毒植物的動物可能需要特別適應的器官才能生存。"},{"en":"Koalas can eat eucalyptus because their gut and liver help deal with toxins.","zh":"樹熊能吃桉樹葉，因為牠們的腸道和肝臟幫助處理毒素。"},{"en":"This phrase shows how body structure matches diet.","zh":"這個短語顯示身體結構如何配合飲食。"}],"source":"125 - Koalas.pdf","sourcePage":8},{"front":"process the toxins","meaning":"處理毒素","examples":[{"en":"Koalas’ gut and liver process the toxins in eucalyptus leaves.","zh":"樹熊的腸道和肝臟處理桉樹葉中的毒素。"},{"en":"To process the toxins means to break down or manage poisonous substances safely.","zh":"處理毒素，是指安全分解或應對有毒物質。"},{"en":"The liver helps the human body process alcohol and other chemicals.","zh":"肝臟幫助人體處理酒精和其他化學物質。"},{"en":"If an animal cannot process toxins, its food can poison it.","zh":"如果動物不能處理毒素，食物可能毒害牠。"},{"en":"This phrase describes how the body protects itself from harmful substances.","zh":"這個短語描述身體如何保護自己免受有害物質傷害。"}],"source":"125 - Koalas.pdf","sourcePage":8},{"front":"digest their food properly","meaning":"正確消化食物","examples":[{"en":"Koalas must sit still to digest their food properly.","zh":"樹熊必須靜坐才能正確消化食物。"},{"en":"To digest their food properly means to break food down in a healthy and effective way.","zh":"正確消化食物，是指以健康而有效的方式分解食物。"},{"en":"People may digest food better if they eat slowly and avoid rushing.","zh":"如果人慢慢進食而不急促，可能更好地消化食物。"},{"en":"Koalas need long periods of stillness because their food is hard to process.","zh":"樹熊需要長時間靜止，因為牠們的食物很難處理。"},{"en":"This phrase connects behaviour with the body’s ability to use food.","zh":"這個短語把行為與身體利用食物的能力連接起來。"}],"source":"125 - Koalas.pdf","sourcePage":8},{"front":"sit still for","meaning":"靜坐……時間","examples":[{"en":"Koalas must sit still for 21 hours every day.","zh":"樹熊每天必須靜坐 21 小時。"},{"en":"To sit still for a period means to remain in one place without much movement for that time.","zh":"靜坐某段時間，是指在那段時間內留在一處而不太移動。"},{"en":"A child may find it hard to sit still for a long lesson.","zh":"孩子可能覺得長課很難一直靜坐。"},{"en":"Koalas sit still for many hours so their bodies can digest difficult leaves.","zh":"樹熊靜坐許多小時，使身體能消化難處理的葉子。"},{"en":"This phrase emphasises long inactivity.","zh":"這個短語強調長時間不活動。"}],"source":"125 - Koalas.pdf","sourcePage":8},{"front":"the epitome of","meaning":"……的典範","examples":[{"en":"Koalas are the epitome of innocence and inoffensiveness.","zh":"樹熊是天真無害的典範。"},{"en":"The epitome of something means the perfect example of that quality.","zh":"某特質的典範，是指該特質的完美例子。"},{"en":"A teacher who listens patiently may be the epitome of kindness.","zh":"耐心聆聽的老師可能是善良的典範。"},{"en":"If an animal is the epitome of harmlessness, people may underestimate its needs.","zh":"如果動物是無害的典範，人們可能低估牠的需要。"},{"en":"This phrase strongly highlights one defining feature.","zh":"這個短語強烈突出一個定義性特徵。"}],"source":"125 - Koalas.pdf","sourcePage":8},{"front":"innocence and inoffensiveness","meaning":"天真無害","examples":[{"en":"Koalas are the epitome of innocence and inoffensiveness.","zh":"樹熊是天真無害的典範。"},{"en":"Innocence and inoffensiveness mean looking harmless, gentle, and unlikely to attack.","zh":"天真無害，是指看起來沒有危險、溫和且不太可能攻擊。"},{"en":"A small child holding a flower may seem full of innocence and inoffensiveness.","zh":"拿着花的小孩可能顯得充滿天真無害。"},{"en":"Animals that appear harmless can still suffer greatly when people handle them carelessly.","zh":"看似無害的動物，在人們粗心抱摸時仍可能受苦。"},{"en":"This phrase explains why koalas seem safe to cuddle.","zh":"這個短語解釋為何樹熊看似適合被擁抱。"}],"source":"125 - Koalas.pdf","sourcePage":8},{"front":"be capable of","meaning":"有能力……","examples":[{"en":"Koalas are capable of injuring a person, but they rarely attack.","zh":"樹熊有能力傷害人，但牠們很少攻擊。"},{"en":"To be capable of doing something means to have the ability to do it.","zh":"有能力做某事，是指具備做該事的能力。"},{"en":"A quiet student may still be capable of giving a strong speech.","zh":"安靜的學生仍可能有能力發表有力演說。"},{"en":"Being capable of harm does not mean an animal usually behaves aggressively.","zh":"有能力造成傷害，不代表動物通常具攻擊性。"},{"en":"This phrase separates ability from actual behaviour.","zh":"這個短語把能力與實際行為分開。"}],"source":"125 - Koalas.pdf","sourcePage":9},{"front":"rip open","meaning":"撕開","examples":[{"en":"A koala could rip open a person’s arm with its claws.","zh":"樹熊可以用爪撕開人的手臂。"},{"en":"To rip open something means to tear it badly, usually with force.","zh":"撕開某物，是指通常用力把它嚴重撕裂。"},{"en":"A sharp nail can rip open a shopping bag if it catches the plastic.","zh":"如果尖釘勾住塑膠，可能撕開購物袋。"},{"en":"Strong claws can rip open skin even if the animal does not intend to attack.","zh":"即使動物無意攻擊，強壯爪子也可以撕開皮膚。"},{"en":"This phrase describes serious tearing damage.","zh":"這個短語描述嚴重撕裂傷害。"}],"source":"125 - Koalas.pdf","sourcePage":9},{"front":"needle-sharp claws","meaning":"針般鋒利的爪","examples":[{"en":"Koalas have needle-sharp claws.","zh":"樹熊有針般鋒利的爪。"},{"en":"Needle-sharp claws are claws that are extremely sharp, like needles.","zh":"針般鋒利的爪，是指像針一樣極鋒利的爪。"},{"en":"A cat with needle-sharp claws can scratch furniture easily.","zh":"有針般鋒利爪子的貓很容易抓花家具。"},{"en":"Koalas use sharp claws to climb, but those claws can injure people accidentally.","zh":"樹熊用鋒利爪子攀爬，但那些爪可能意外傷人。"},{"en":"This phrase makes the danger of the claws easy to imagine.","zh":"這個短語令爪子的危險容易想像。"}],"source":"125 - Koalas.pdf","sourcePage":9},{"front":"deliver a nasty bite","meaning":"狠狠咬一口","examples":[{"en":"A koala is capable of delivering a nasty bite.","zh":"樹熊有能力狠狠咬一口。"},{"en":"To deliver a nasty bite means to bite someone hard enough to cause pain or injury.","zh":"狠狠咬一口，是指用力咬人，造成痛楚或傷害。"},{"en":"A frightened dog may deliver a nasty bite if someone grabs it suddenly.","zh":"如果有人突然抓住受驚的狗，牠可能狠狠咬一口。"},{"en":"Even gentle animals can bite when they feel trapped or handled badly.","zh":"即使溫和動物感到被困或被粗暴對待，也可能咬人。"},{"en":"This phrase describes a serious bite, not a playful nip.","zh":"這個短語描述嚴重咬傷，而不是玩耍式輕咬。"}],"source":"125 - Koalas.pdf","sourcePage":9},{"front":"simply do not attack","meaning":"根本不會攻擊","examples":[{"en":"Koalas simply do not attack.","zh":"樹熊根本不會攻擊。"},{"en":"Simply do not attack means they just do not normally fight or strike first.","zh":"根本不會攻擊，是指牠們通常就是不會打鬥或先動手。"},{"en":"Some shy dogs bark loudly but simply do not attack people.","zh":"有些害羞的狗會大聲吠叫，但根本不會攻擊人。"},{"en":"An animal may be able to injure someone but still avoid aggression.","zh":"動物可能有能力傷人，但仍避免攻擊。"},{"en":"This phrase stresses the gap between ability and behaviour.","zh":"這個短語強調能力與行為之間的差距。"}],"source":"125 - Koalas.pdf","sourcePage":9},{"front":"upset a koala","meaning":"令樹熊受驚或不安","examples":[{"en":"If you upset a koala, it may show small signs of distress.","zh":"如果你令樹熊不安，牠可能會表現出細微的不安跡象。"},{"en":"To upset a koala means to make it frightened, stressed, or uncomfortable.","zh":"令樹熊受驚或不安，是指令牠害怕、有壓力或不舒服。"},{"en":"Loud noise or rough handling may upset a sensitive animal.","zh":"嘈雜聲或粗暴抱摸可能令敏感動物不安。"},{"en":"If a koala is upset, it may not fight back but may still suffer internally.","zh":"如果樹熊不安，牠未必反擊，但內在仍可能受苦。"},{"en":"This phrase reminds readers that quiet animals can still feel stress.","zh":"這個短語提醒讀者，安靜的動物仍然會感到壓力。"}],"source":"125 - Koalas.pdf","sourcePage":9},{"front":"blink or swallow","meaning":"眨眼或吞嚥","examples":[{"en":"An upset koala may blink or swallow.","zh":"不安的樹熊可能會眨眼或吞嚥。"},{"en":"To blink or swallow means to make small physical movements with the eyes or throat.","zh":"眨眼或吞嚥，是指眼睛或喉嚨作出細小身體動作。"},{"en":"A nervous student may blink or swallow before answering a difficult question.","zh":"緊張的學生回答難題前可能會眨眼或吞嚥。"},{"en":"Small body movements can show stress when an animal does not cry or fight.","zh":"當動物不叫喊或反擊時，細小身體動作可以顯示壓力。"},{"en":"This phrase points to subtle signs rather than obvious aggression.","zh":"這個短語指出細微跡象，而不是明顯攻擊。"}],"source":"125 - Koalas.pdf","sourcePage":9},{"front":"hiccup","meaning":"打嗝","examples":[{"en":"An upset koala may hiccup.","zh":"不安的樹熊可能會打嗝。"},{"en":"To hiccup means to make a small sudden sound or movement caused by the diaphragm.","zh":"打嗝，是指橫隔膜引起的細小突然聲音或動作。"},{"en":"A baby may hiccup after drinking milk too quickly.","zh":"嬰兒喝奶太快後可能會打嗝。"},{"en":"In this context, hiccuping can be a small sign of stress in a koala.","zh":"在這個語境中，打嗝可能是樹熊壓力的細小跡象。"},{"en":"This word usually describes a minor body reaction, but here it signals distress.","zh":"這個詞通常描述輕微身體反應，但在這裡表示不安。"}],"source":"125 - Koalas.pdf","sourcePage":9},{"front":"no way","meaning":"絕不；不可能","examples":[{"en":"The passage says, “But attack? No way!”","zh":"篇章說：「但攻擊？絕不可能！」"},{"en":"No way means absolutely not or impossible.","zh":"絕不或不可能，是指完全不會或絕對不是。"},{"en":"If someone asks me to finish ten essays tonight, I might say, “No way!”","zh":"如果有人叫我今晚完成十篇作文，我可能會說：「不可能！」"},{"en":"This phrase is informal and very strong.","zh":"這個短語較口語，而且語氣很強。"},{"en":"In the passage, it stresses that koalas are not aggressive attackers.","zh":"在篇章中，它強調樹熊不是具攻擊性的襲擊者。"}],"source":"125 - Koalas.pdf","sourcePage":9},{"front":"aggressive","meaning":"具攻擊性的","examples":[{"en":"Koalas are just not aggressive.","zh":"樹熊就是不具攻擊性。"},{"en":"Aggressive means likely to attack, fight, or behave in a hostile way.","zh":"具攻擊性，是指可能攻擊、打鬥或以敵意方式行為。"},{"en":"A dog that growls and bites strangers may be aggressive.","zh":"對陌生人咆哮和咬人的狗可能具攻擊性。"},{"en":"Koalas may be physically able to hurt people, but they are not usually aggressive.","zh":"樹熊身體上可能能傷人，但通常不具攻擊性。"},{"en":"This word describes behaviour, not physical strength.","zh":"這個詞描述行為，而不是身體力量。"}],"source":"125 - Koalas.pdf","sourcePage":9},{"front":"grip the bark of","meaning":"抓緊……的樹皮","examples":[{"en":"Koalas use their claws to grip the bark of eucalyptus trees.","zh":"樹熊用爪抓緊桉樹的樹皮。"},{"en":"To grip the bark of a tree means to hold tightly onto its outer surface.","zh":"抓緊樹皮，是指牢牢抓住樹的外層表面。"},{"en":"A climber may grip the bark of a tree to avoid slipping.","zh":"攀爬者可能抓緊樹皮以避免滑倒。"},{"en":"Koalas need sharp claws because smooth bark can be difficult to hold.","zh":"樹熊需要鋒利爪子，因為光滑樹皮很難抓住。"},{"en":"This phrase explains the climbing purpose of their claws.","zh":"這個短語解釋牠們爪子的攀爬用途。"}],"source":"125 - Koalas.pdf","sourcePage":9},{"front":"hard smooth bark","meaning":"堅硬光滑的樹皮","examples":[{"en":"Koalas grip the hard smooth bark of eucalyptus trees.","zh":"樹熊抓緊桉樹堅硬光滑的樹皮。"},{"en":"Hard smooth bark is a tough outer tree surface that has little roughness.","zh":"堅硬光滑的樹皮，是堅韌而少有粗糙感的樹外層表面。"},{"en":"Shoes need good grip on hard smooth floors to prevent slipping.","zh":"鞋子在堅硬光滑的地板上需要良好抓地力，以免滑倒。"},{"en":"Sharp claws help koalas hold onto bark that would otherwise be difficult to grip.","zh":"鋒利爪子幫助樹熊抓住否則很難抓緊的樹皮。"},{"en":"This phrase describes the surface koalas climb on.","zh":"這個短語描述樹熊攀爬的表面。"}],"source":"125 - Koalas.pdf","sourcePage":10},{"front":"very sensitive","meaning":"非常敏感","examples":[{"en":"Koalas are very sensitive animals.","zh":"樹熊是非常敏感的動物。"},{"en":"Very sensitive means easily affected by stress, noise, handling, or change.","zh":"非常敏感，是指容易受壓力、噪音、接觸或改變影響。"},{"en":"A very sensitive child may cry when a room is too loud.","zh":"非常敏感的孩子可能在房間太嘈雜時哭。"},{"en":"Sensitive animals need calm routines because small disturbances can affect health.","zh":"敏感動物需要平靜常規，因為小干擾也可能影響健康。"},{"en":"This phrase explains why koalas require careful treatment.","zh":"這個短語解釋為何樹熊需要小心對待。"}],"source":"125 - Koalas.pdf","sourcePage":10},{"front":"the slightest upset","meaning":"最輕微的不安","examples":[{"en":"The slightest upset can affect koalas badly.","zh":"最輕微的不安也可以嚴重影響樹熊。"},{"en":"The slightest upset means even a very small disturbance or stress.","zh":"最輕微的不安，是指即使非常小的干擾或壓力。"},{"en":"A very sick patient may be affected by the slightest upset in routine.","zh":"病得很重的病人可能受日常安排中最輕微的不安影響。"},{"en":"If the slightest upset harms an animal, handlers must avoid unnecessary contact.","zh":"如果最輕微的不安也會傷害動物，照顧者必須避免不必要接觸。"},{"en":"This phrase stresses extreme sensitivity.","zh":"這個短語強調極高敏感度。"}],"source":"125 - Koalas.pdf","sourcePage":10},{"front":"prevent them from breeding","meaning":"阻止牠們繁殖","examples":[{"en":"Stress can prevent koalas from breeding.","zh":"壓力可以阻止樹熊繁殖。"},{"en":"To prevent them from breeding means to stop them from producing babies.","zh":"阻止牠們繁殖，是指令牠們不能產生後代。"},{"en":"Poor living conditions can prevent animals from breeding in captivity.","zh":"差劣生活環境可以阻止圈養動物繁殖。"},{"en":"If stress prevents breeding, a population may decline even when adults survive.","zh":"如果壓力阻止繁殖，即使成年個體存活，族群仍可能下降。"},{"en":"This phrase links emotional or physical pressure with reproduction.","zh":"這個短語把情緒或身體壓力與繁殖連接起來。"}],"source":"125 - Koalas.pdf","sourcePage":10},{"front":"go off their food","meaning":"失去食慾","examples":[{"en":"Stress can cause koalas to go off their food.","zh":"壓力可以令樹熊失去食慾。"},{"en":"To go off their food means to lose appetite and stop eating normally.","zh":"失去食慾，是指胃口下降並停止正常進食。"},{"en":"A dog may go off its food when it is ill or anxious.","zh":"狗隻生病或焦慮時可能失去食慾。"},{"en":"If koalas go off their food, they can quickly lose weight and become weaker.","zh":"如果樹熊失去食慾，牠們可以很快體重下降並變弱。"},{"en":"This phrase describes a warning sign of illness or stress.","zh":"這個短語描述疾病或壓力的警號。"}],"source":"125 - Koalas.pdf","sourcePage":10},{"front":"make them susceptible to","meaning":"使牠們容易患上……","examples":[{"en":"Stress can make koalas susceptible to gut infections.","zh":"壓力會使樹熊容易患上腸道感染。"},{"en":"To make someone susceptible to something means to make them more likely to suffer from it.","zh":"使某人容易患上某病，是指令他們較可能受其影響。"},{"en":"Lack of sleep can make students susceptible to colds.","zh":"睡眠不足可以使學生容易患上感冒。"},{"en":"Stress weakens the body and can make animals more vulnerable to disease.","zh":"壓力削弱身體，並可使動物更容易患病。"},{"en":"This phrase describes increased risk.","zh":"這個短語描述風險增加。"}],"source":"125 - Koalas.pdf","sourcePage":10},{"front":"gut infections","meaning":"腸道感染","examples":[{"en":"Koalas may become susceptible to gut infections.","zh":"樹熊可能變得容易患上腸道感染。"},{"en":"Gut infections are illnesses caused by harmful organisms in the digestive system.","zh":"腸道感染是由消化系統中的有害生物引起的疾病。"},{"en":"People may get gut infections from contaminated food or water.","zh":"人們可能因受污染食物或水而患上腸道感染。"},{"en":"Gut infections can reduce appetite, cause weight loss, and weaken the body.","zh":"腸道感染可以減少食慾、造成體重下降並削弱身體。"},{"en":"This phrase refers to disease inside the stomach or intestines.","zh":"這個短語指胃或腸內的疾病。"}],"source":"125 - Koalas.pdf","sourcePage":10},{"front":"stoic creatures","meaning":"堅忍不露痛苦的動物","examples":[{"en":"Koalas are stoic creatures that hide signs of illness.","zh":"樹熊是堅忍不露痛苦的動物，會隱藏疾病跡象。"},{"en":"Stoic creatures are animals that endure pain or discomfort without showing much reaction.","zh":"堅忍不露痛苦的動物，是指忍受痛楚或不適卻沒有太多反應的動物。"},{"en":"Some pets are stoic and do not cry even when they are injured.","zh":"有些寵物很能忍，即使受傷也不叫。"},{"en":"Stoicism can make illness harder to notice until it becomes serious.","zh":"堅忍不露痛苦會令疾病更難被察覺，直到變得嚴重。"},{"en":"This phrase explains why keepers must watch koalas carefully.","zh":"這個短語解釋為何飼養員必須仔細觀察樹熊。"}],"source":"125 - Koalas.pdf","sourcePage":10},{"front":"put on a brave face","meaning":"強裝沒事；裝作堅強","examples":[{"en":"Koalas put on a brave face until they are very ill.","zh":"樹熊會強裝沒事，直到牠們病得很重。"},{"en":"To put on a brave face means to hide fear, pain, or sadness and look calm.","zh":"強裝沒事，是指隱藏恐懼、痛苦或悲傷，並看起來平靜。"},{"en":"A student may put on a brave face after failing an exam.","zh":"學生考試不及格後，可能裝作堅強。"},{"en":"When animals put on a brave face, illness may not be noticed early.","zh":"當動物強裝沒事，疾病可能不會及早被發現。"},{"en":"This phrase describes hiding distress from others.","zh":"這個短語描述向別人隱藏痛苦。"}],"source":"125 - Koalas.pdf","sourcePage":10},{"front":"at death’s door","meaning":"瀕臨死亡","examples":[{"en":"Koalas may look healthy until they are at death’s door.","zh":"樹熊可能看起來健康，直到瀕臨死亡。"},{"en":"At death’s door means extremely ill and close to dying.","zh":"瀕臨死亡，是指病得極重並接近死亡。"},{"en":"A patient may look fine for weeks and then suddenly be at death’s door.","zh":"病人可能幾星期看似正常，然後突然瀕臨死亡。"},{"en":"If signs appear only at death’s door, early detection is very difficult.","zh":"如果跡象只在瀕臨死亡時出現，早期發現就非常困難。"},{"en":"This phrase is dramatic and describes a very serious health condition.","zh":"這個短語很戲劇性，描述非常嚴重的健康狀況。"}],"source":"125 - Koalas.pdf","sourcePage":10},{"front":"appear healthy","meaning":"看似健康","examples":[{"en":"One day a koala may appear healthy, and the next it may be dead.","zh":"樹熊某天可能看似健康，翌日卻可能死亡。"},{"en":"To appear healthy means to look well on the outside, even if hidden illness exists.","zh":"看似健康，是指外表看起來良好，即使內裡有隱藏疾病。"},{"en":"A plant may appear healthy while its roots are already rotting.","zh":"植物可能看似健康，但根部已經腐爛。"},{"en":"If an animal appears healthy but hides sickness, keepers need other checks.","zh":"如果動物看似健康但隱藏病情，飼養員就需要其他檢查。"},{"en":"This phrase contrasts outward appearance with real condition.","zh":"這個短語對比外表與真實狀況。"}],"source":"125 - Koalas.pdf","sourcePage":10},{"front":"captive koalas","meaning":"圈養樹熊","examples":[{"en":"Captive koalas have to be weighed daily.","zh":"圈養樹熊必須每天被磅重。"},{"en":"Captive koalas are koalas kept in zoos, parks, or care facilities rather than living freely in the wild.","zh":"圈養樹熊是指被養在動物園、公園或照護設施中，而不是在野外自由生活的樹熊。"},{"en":"Captive animals need regular health checks because they cannot choose their own environment.","zh":"圈養動物需要定期健康檢查，因為牠們不能選擇自己的環境。"},{"en":"Captive koalas may seem calm, but keepers must monitor stress and feeding.","zh":"圈養樹熊可能看似平靜，但飼養員必須監察壓力和進食。"},{"en":"This phrase refers to koalas under human care.","zh":"這個短語指由人類照顧的樹熊。"}],"source":"125 - Koalas.pdf","sourcePage":11},{"front":"be weighed daily","meaning":"每日被磅重","examples":[{"en":"Captive koalas are weighed daily to check their health.","zh":"圈養樹熊每日被磅重以檢查健康。"},{"en":"To be weighed daily means to have body weight measured every day.","zh":"每日被磅重，是指每天測量體重。"},{"en":"A hospital patient may be weighed daily if sudden weight change is dangerous.","zh":"如果突然體重變化很危險，醫院病人可能每日被磅重。"},{"en":"Daily weighing can reveal health problems before obvious symptoms appear.","zh":"每日磅重可以在明顯症狀出現前揭示健康問題。"},{"en":"This phrase describes a routine health-monitoring practice.","zh":"這個短語描述日常健康監測做法。"}],"source":"125 - Koalas.pdf","sourcePage":11},{"front":"feed properly","meaning":"正常進食","examples":[{"en":"Keepers check whether captive koalas are feeding properly.","zh":"飼養員檢查圈養樹熊是否正常進食。"},{"en":"To feed properly means to eat enough suitable food in a healthy way.","zh":"正常進食，是指以健康方式吃足夠合適食物。"},{"en":"Parents may worry if a baby is not feeding properly.","zh":"如果嬰兒沒有正常進食，父母可能會擔心。"},{"en":"If koalas do not feed properly, weight loss may be the first warning sign.","zh":"如果樹熊沒有正常進食，體重下降可能是第一個警號。"},{"en":"This phrase connects eating behaviour with health.","zh":"這個短語把進食行為與健康連接起來。"}],"source":"125 - Koalas.pdf","sourcePage":11},{"front":"sudden loss of weight","meaning":"體重突然下降","examples":[{"en":"A sudden loss of weight is often the only warning sign.","zh":"體重突然下降通常是唯一警號。"},{"en":"A sudden loss of weight means body weight drops quickly and unexpectedly.","zh":"體重突然下降，是指體重快速且意外地下跌。"},{"en":"A pet owner should call a vet if a cat has a sudden loss of weight.","zh":"如果貓體重突然下降，寵物主人應該聯絡獸醫。"},{"en":"Sudden weight loss can signal hidden illness or poor feeding.","zh":"體重突然下降可以表示隱藏疾病或進食不足。"},{"en":"This phrase describes a serious change that should not be ignored.","zh":"這個短語描述不應忽視的嚴重變化。"}],"source":"125 - Koalas.pdf","sourcePage":11},{"front":"warning keepers have","meaning":"飼養員得到的警號","examples":[{"en":"Weight loss may be the only warning keepers have.","zh":"體重下降可能是飼養員得到的唯一警號。"},{"en":"The warning keepers have means the sign or clue available to animal carers.","zh":"飼養員得到的警號，是指動物照顧者可用的跡象或線索。"},{"en":"If a bird stops singing, that may be the only warning keepers have that it is ill.","zh":"如果鳥停止唱叫，那可能是飼養員得到的唯一生病警號。"},{"en":"When animals hide pain, keepers must rely on small warning signs.","zh":"當動物隱藏痛楚，飼養員必須依賴細小警號。"},{"en":"This phrase focuses on the limited information available to carers.","zh":"這個短語聚焦照顧者可取得的有限資訊。"}],"source":"125 - Koalas.pdf","sourcePage":11},{"front":"their charge","meaning":"他們照顧的動物","examples":[{"en":"Keepers may not know their charge is ill until it loses weight.","zh":"飼養員可能直到他們照顧的動物體重下降，才知道牠病了。"},{"en":"Their charge means the animal or person they are responsible for caring for.","zh":"他們照顧的動物，是指他們負責照顧的動物或人。"},{"en":"A nurse checks whether her charge has eaten and taken medicine.","zh":"護士會檢查自己照顧的病人是否已進食和服藥。"},{"en":"If a charge cannot speak, carers must watch behaviour and body changes carefully.","zh":"如果照顧對象不能說話，照顧者必須仔細觀察行為和身體變化。"},{"en":"This phrase is formal and shows responsibility for care.","zh":"這個短語較正式，並顯示照顧責任。"}],"source":"125 - Koalas.pdf","sourcePage":11},{"front":"be allowed to handle","meaning":"獲准接觸；獲准處理","examples":[{"en":"Only two keepers and a vet were allowed to handle the koalas.","zh":"只有兩名飼養員和一名獸醫獲准接觸樹熊。"},{"en":"To be allowed to handle an animal means to have permission to touch, hold, or move it.","zh":"獲准接觸動物，是指有許可觸摸、抱起或移動牠。"},{"en":"Only trained staff are allowed to handle fragile laboratory equipment.","zh":"只有受訓員工獲准處理脆弱實驗室設備。"},{"en":"Limiting who can handle animals reduces stress and accidental injury.","zh":"限制可接觸動物的人可以減少壓力和意外受傷。"},{"en":"This phrase shows that handling requires control and permission.","zh":"這個短語顯示處理動物需要控制和許可。"}],"source":"125 - Koalas.pdf","sourcePage":11},{"front":"be comfortable with","meaning":"對……感到自在","examples":[{"en":"Koalas are only comfortable with people they know.","zh":"樹熊只對牠們認識的人感到自在。"},{"en":"To be comfortable with someone means to feel safe and relaxed around them.","zh":"對某人感到自在，是指在他們身邊感到安全和放鬆。"},{"en":"A shy child may be comfortable with family but nervous around strangers.","zh":"害羞的孩子可能對家人感到自在，但在陌生人身邊緊張。"},{"en":"Animals are less stressed when handled by people they are comfortable with.","zh":"當動物由牠們感到自在的人處理，壓力會較少。"},{"en":"This phrase describes trust and ease.","zh":"這個短語描述信任和放鬆。"}],"source":"125 - Koalas.pdf","sourcePage":11},{"front":"a request for someone to","meaning":"要求某人去……","examples":[{"en":"A request for the koala to meet the Queen was refused.","zh":"要求樹熊去見女王的請求被拒絕。"},{"en":"A request for someone to do something is a formal or polite asking that they do it.","zh":"要求某人去做某事，是正式或有禮貌地要求他們做該事。"},{"en":"A request for students to arrive early may be sent before a school trip.","zh":"學校旅行前，可能發出要求學生早到的請求。"},{"en":"A request can be refused if it would cause risk, stress, or inconvenience.","zh":"如果要求會造成風險、壓力或不便，它可以被拒絕。"},{"en":"This phrase introduces what someone is being asked to do.","zh":"這個短語引入某人被要求去做的事。"}],"source":"125 - Koalas.pdf","sourcePage":11},{"front":"be refused because of","meaning":"因……而被拒絕","examples":[{"en":"The request was refused because of the distress it would cause.","zh":"該請求因會造成不安而被拒絕。"},{"en":"To be refused because of something means to be rejected for that reason.","zh":"因某事而被拒絕，是指因該原因而不被接受。"},{"en":"A school trip may be refused because of safety concerns.","zh":"學校旅行可能因安全顧慮而被拒絕。"},{"en":"Requests involving animals may be refused if they would cause stress.","zh":"涉及動物的要求如果會造成壓力，可能被拒絕。"},{"en":"This phrase clearly links a rejection with its cause.","zh":"這個短語清楚把拒絕與原因連接起來。"}],"source":"125 - Koalas.pdf","sourcePage":11},{"front":"distress","meaning":"痛苦；不安","examples":[{"en":"The visit would have caused distress to the koala.","zh":"這次探訪本會令樹熊感到痛苦或不安。"},{"en":"Distress means strong discomfort, anxiety, pain, or suffering.","zh":"痛苦或不安，是指強烈不適、焦慮、痛楚或受苦。"},{"en":"A loud alarm can cause distress to young children or animals.","zh":"嘈雜警鐘可以令幼童或動物感到不安。"},{"en":"Distress may appear through small signs when an animal does not cry out.","zh":"當動物不叫喊時，不安可能透過細小跡象出現。"},{"en":"This word describes serious emotional or physical discomfort.","zh":"這個詞描述嚴重情緒或身體不適。"}],"source":"125 - Koalas.pdf","sourcePage":11},{"front":"marsupial","meaning":"有袋類動物","examples":[{"en":"The koala is a sensitive marsupial.","zh":"樹熊是一種敏感的有袋類動物。"},{"en":"A marsupial is a mammal whose young often continue developing in a pouch.","zh":"有袋類動物是幼崽通常在育兒袋中繼續發育的哺乳動物。"},{"en":"Kangaroos and wombats are also marsupials.","zh":"袋鼠和袋熊也是有袋類動物。"},{"en":"Calling a koala a marsupial classifies it scientifically, not emotionally.","zh":"稱樹熊為有袋類動物，是科學分類，而不是情感描述。"},{"en":"This word helps describe what kind of animal the koala is.","zh":"這個詞幫助描述樹熊屬於哪類動物。"}],"source":"125 - Koalas.pdf","sourcePage":12},{"front":"no longer has","meaning":"不再擁有","examples":[{"en":"London Zoo no longer has a koala.","zh":"倫敦動物園不再有樹熊。"},{"en":"No longer has means had something before but does not have it now.","zh":"不再擁有，是指以前有某物，但現在沒有。"},{"en":"The library no longer has late-night opening hours.","zh":"圖書館不再有深夜開放時間。"},{"en":"This phrase shows that a past situation has changed.","zh":"這個短語顯示過去情況已改變。"},{"en":"It is useful when comparing what existed before with what exists now.","zh":"它適合用於比較過去存在和現在存在的東西。"}],"source":"125 - Koalas.pdf","sourcePage":12},{"front":"die of","meaning":"死於","examples":[{"en":"The female koala died of cancer.","zh":"那隻雌性樹熊死於癌症。"},{"en":"To die of a disease means to die because that disease caused death.","zh":"死於某疾病，是指因該疾病而死亡。"},{"en":"Many people died of infections before modern medicine improved treatment.","zh":"在現代醫學改善治療前，許多人死於感染。"},{"en":"Animals can die of diseases that are not obvious from the outside.","zh":"動物可能死於外表不明顯的疾病。"},{"en":"This phrase connects the cause of death with the illness.","zh":"這個短語把死亡原因與疾病連接起來。"}],"source":"125 - Koalas.pdf","sourcePage":12},{"front":"caused by","meaning":"由……引起","examples":[{"en":"The cancer was caused by a retrovirus.","zh":"癌症是由逆轉錄病毒引起的。"},{"en":"Caused by means produced or brought about by something.","zh":"由某物引起，是指由它造成或導致。"},{"en":"The delay was caused by heavy traffic near the tunnel.","zh":"延誤是由隧道附近交通繁忙引起的。"},{"en":"Knowing what caused a problem helps people prevent it from happening again.","zh":"知道問題由甚麼引起，有助人們防止它再次發生。"},{"en":"This phrase identifies the source or reason for an effect.","zh":"這個短語指出結果的來源或原因。"}],"source":"125 - Koalas.pdf","sourcePage":12},{"front":"retrovirus","meaning":"逆轉錄病毒","examples":[{"en":"A retrovirus caused the female koala’s cancer.","zh":"逆轉錄病毒引起那隻雌性樹熊的癌症。"},{"en":"A retrovirus is a type of virus that can insert genetic material into a host’s cells.","zh":"逆轉錄病毒是一種可以把遺傳物質插入宿主細胞的病毒。"},{"en":"Some viruses can remain hidden in the body before causing serious disease.","zh":"有些病毒在造成嚴重疾病前，可以隱藏在身體內。"},{"en":"In koalas, a retrovirus can be linked to tumours and cancer.","zh":"在樹熊身上，逆轉錄病毒可能與腫瘤和癌症有關。"},{"en":"This word names a biological cause of illness.","zh":"這個詞命名疾病的生物原因。"}],"source":"125 - Koalas.pdf","sourcePage":12},{"front":"come into heat","meaning":"發情","examples":[{"en":"Female koalas become more active when they come into heat.","zh":"雌性樹熊發情時會變得更活躍。"},{"en":"To come into heat means a female animal enters a period when it can mate.","zh":"發情，是指雌性動物進入可以交配的時期。"},{"en":"A vet may explain that a female cat becomes restless when she comes into heat.","zh":"獸醫可能解釋雌貓發情時會變得不安。"},{"en":"Animals may change behaviour or appetite during this reproductive period.","zh":"動物在這個繁殖時期可能改變行為或食慾。"},{"en":"This phrase is used for animal reproduction, not human romance.","zh":"這個短語用於動物繁殖，而不是人類戀愛。"}],"source":"125 - Koalas.pdf","sourcePage":12},{"front":"start losing weight","meaning":"開始體重下降","examples":[{"en":"Female koalas start losing weight when they come into heat.","zh":"雌性樹熊發情時開始體重下降。"},{"en":"To start losing weight means to begin becoming lighter in body weight.","zh":"開始體重下降，是指身體重量開始減少。"},{"en":"A sick pet may start losing weight before other symptoms appear.","zh":"生病寵物可能在其他症狀出現前開始體重下降。"},{"en":"Weight loss can be normal in some periods but worrying in others.","zh":"體重下降在某些時期可能正常，但在其他時候令人擔心。"},{"en":"This phrase describes the beginning of a physical change.","zh":"這個短語描述身體變化的開始。"}],"source":"125 - Koalas.pdf","sourcePage":12},{"front":"oestrus ends","meaning":"發情期結束","examples":[{"en":"After about sixteen days, oestrus ends.","zh":"約十六天後，發情期結束。"},{"en":"Oestrus ends means the female animal’s fertile or mating period finishes.","zh":"發情期結束，是指雌性動物可受孕或交配的時期完結。"},{"en":"A breeder may record when oestrus ends to understand an animal’s cycle.","zh":"繁殖員可能記錄發情期何時結束，以了解動物週期。"},{"en":"After oestrus ends, behaviour and weight may return to normal.","zh":"發情期結束後，行為和體重可能回復正常。"},{"en":"This phrase describes the end of a reproductive stage.","zh":"這個短語描述繁殖階段的結束。"}],"source":"125 - Koalas.pdf","sourcePage":12},{"front":"weight piles back on","meaning":"體重迅速回升","examples":[{"en":"After oestrus ends, the weight usually piles back on.","zh":"發情期結束後，體重通常迅速回升。"},{"en":"Weight piles back on means body weight returns quickly or increases again.","zh":"體重迅速回升，是指身體重量快速回來或再次增加。"},{"en":"A child who was ill may have weight pile back on after appetite returns.","zh":"生病孩子胃口恢復後，體重可能迅速回升。"},{"en":"If expected weight gain does not happen, carers may suspect illness.","zh":"如果預期體重增加沒有發生，照顧者可能懷疑有疾病。"},{"en":"This phrase suggests a noticeable return of weight.","zh":"這個短語暗示體重明顯回復。"}],"source":"125 - Koalas.pdf","sourcePage":12},{"front":"surgery revealed","meaning":"手術顯示","examples":[{"en":"Surgery revealed hundreds of pea-sized tumours.","zh":"手術顯示有數百個豌豆大小的腫瘤。"},{"en":"Surgery revealed something means doctors discovered it during an operation.","zh":"手術顯示某事，是指醫生在手術期間發現它。"},{"en":"Surgery may reveal damage that scans did not clearly show.","zh":"手術可能顯示掃描未能清楚看到的損傷。"},{"en":"Hidden illness can be discovered only when the body is examined directly.","zh":"隱藏疾病可能只有在直接檢查身體時才被發現。"},{"en":"This phrase introduces a medical finding from an operation.","zh":"這個短語引入手術中的醫療發現。"}],"source":"125 - Koalas.pdf","sourcePage":12},{"front":"pea-sized tumours","meaning":"豌豆大小的腫瘤","examples":[{"en":"Surgery revealed hundreds of pea-sized tumours.","zh":"手術顯示有數百個豌豆大小的腫瘤。"},{"en":"Pea-sized tumours are small abnormal growths about the size of peas.","zh":"豌豆大小的腫瘤，是指大小約如豌豆的小型異常增生物。"},{"en":"A doctor may describe a small lump as pea-sized to help patients imagine it.","zh":"醫生可能把小腫塊形容為豌豆大小，幫助病人想像。"},{"en":"Even small tumours can be serious if there are many of them.","zh":"即使腫瘤很小，如果數量很多也可能很嚴重。"},{"en":"This phrase describes both size and medical concern.","zh":"這個短語同時描述大小和醫療關注。"}],"source":"125 - Koalas.pdf","sourcePage":12},{"front":"almost every zoo","meaning":"幾乎每間動物園","examples":[{"en":"Almost every zoo in Australia has koalas.","zh":"澳洲幾乎每間動物園都有樹熊。"},{"en":"Almost every zoo means nearly all zoos, with very few exceptions.","zh":"幾乎每間動物園，是指差不多所有動物園，只有很少例外。"},{"en":"Almost every school in the district has a library.","zh":"該區幾乎每間學校都有圖書館。"},{"en":"If almost every zoo has koalas, the animal is widely used as an attraction.","zh":"如果幾乎每間動物園都有樹熊，表示這種動物被廣泛用作景點。"},{"en":"This phrase shows something is very common but not absolutely universal.","zh":"這個短語顯示某事非常常見，但不是絕對全部。"}],"source":"125 - Koalas.pdf","sourcePage":13},{"front":"Animal Ambassador of the nation","meaning":"國家的動物大使","examples":[{"en":"The koala has become the Animal Ambassador of Australia.","zh":"樹熊已成為澳洲的動物大使。"},{"en":"An Animal Ambassador of a nation is an animal used to represent the country’s image.","zh":"國家的動物大使，是指被用來代表國家形象的動物。"},{"en":"A panda often acts as an animal ambassador for China in tourism and diplomacy.","zh":"熊貓常在旅遊和外交中作為中國的動物大使。"},{"en":"When an animal becomes a national symbol, people may use it to attract visitors.","zh":"當動物成為國家象徵，人們可能用牠吸引遊客。"},{"en":"This phrase shows how koalas became part of Australia’s public image.","zh":"這個短語顯示樹熊如何成為澳洲公眾形象的一部分。"}],"source":"125 - Koalas.pdf","sourcePage":13},{"front":"nowhere outside Australia","meaning":"澳洲以外沒有地方","examples":[{"en":"Nowhere outside Australia would public handling be allowed.","zh":"澳洲以外沒有地方會允許公眾抱摸。"},{"en":"Nowhere outside Australia means in no place beyond Australia.","zh":"澳洲以外沒有地方，是指澳洲之外任何地方都沒有。"},{"en":"Nowhere outside the school can students use this special library card.","zh":"學校以外沒有地方可以使用這張特別圖書證。"},{"en":"This phrase strongly limits a rule to one country or area.","zh":"這個短語把規則強烈限制在一個國家或地區之外。"},{"en":"It suggests that Australia is unusually permissive in this case.","zh":"它暗示澳洲在這件事上異常寬鬆。"}],"source":"125 - Koalas.pdf","sourcePage":13},{"front":"handling by the public","meaning":"由公眾抱摸","examples":[{"en":"Handling by the public would not be allowed outside Australia.","zh":"澳洲以外不會允許由公眾抱摸。"},{"en":"Handling by the public means ordinary visitors touching, holding, or carrying an animal.","zh":"由公眾抱摸，是指普通遊客觸摸、抱起或攜帶動物。"},{"en":"Handling by the public is often banned when animals are fragile or easily stressed.","zh":"當動物脆弱或容易受壓時，通常會禁止公眾抱摸。"},{"en":"Public handling can spread stress because many strangers touch the animal.","zh":"公眾抱摸會造成壓力，因為許多陌生人接觸動物。"},{"en":"This phrase refers to contact by visitors, not trained keepers.","zh":"這個短語指遊客接觸，而不是受訓飼養員接觸。"}],"source":"125 - Koalas.pdf","sourcePage":13},{"front":"koala cuddling","meaning":"抱樹熊活動","examples":[{"en":"Koala cuddling is criticised as harmful.","zh":"抱樹熊活動被批評為有害。"},{"en":"Koala cuddling means holding a koala closely, often for a tourist photograph.","zh":"抱樹熊活動，是指近距離抱着樹熊，通常用於旅遊照片。"},{"en":"A visitor may think koala cuddling is cute because the animal looks calm.","zh":"遊客可能因動物看起來平靜，而覺得抱樹熊活動很可愛。"},{"en":"Koala cuddling can stress the animal even if it does not struggle.","zh":"抱樹熊活動即使在動物沒有掙扎時，也可能令牠受壓。"},{"en":"This phrase names the activity the article wants to question.","zh":"這個短語命名文章想質疑的活動。"}],"source":"125 - Koalas.pdf","sourcePage":13},{"front":"fly in the face of","meaning":"公然違反","examples":[{"en":"Koala cuddling flies in the face of every rule of good care.","zh":"抱樹熊活動公然違反每一條良好照顧守則。"},{"en":"To fly in the face of something means to openly go against it.","zh":"公然違反某事，是指明顯地與它相反。"},{"en":"Letting children play near traffic flies in the face of basic safety rules.","zh":"讓孩子在車流旁玩耍公然違反基本安全規則。"},{"en":"If an activity flies in the face of good care, it ignores what experts say is safe.","zh":"如果活動公然違反良好照顧守則，它就是忽視專家所說的安全做法。"},{"en":"This phrase expresses strong criticism.","zh":"這個短語表達強烈批評。"}],"source":"125 - Koalas.pdf","sourcePage":13},{"front":"rules of good care","meaning":"良好照顧守則","examples":[{"en":"Koala cuddling breaks the rules of good care.","zh":"抱樹熊活動違反良好照顧守則。"},{"en":"Rules of good care are standards for treating animals or people safely and kindly.","zh":"良好照顧守則是安全而善待動物或人的標準。"},{"en":"A hospital’s rules of good care include hygiene, privacy, and careful monitoring.","zh":"醫院的良好照顧守則包括衛生、私隱和仔細監察。"},{"en":"Animal care rules may limit handling, noise, and stress.","zh":"動物照顧守則可能限制抱摸、噪音和壓力。"},{"en":"This phrase refers to responsible treatment, not entertainment value.","zh":"這個短語指負責任的對待，而不是娛樂價值。"}],"source":"125 - Koalas.pdf","sourcePage":13},{"front":"pass from stranger to stranger","meaning":"在陌生人之間傳來傳去","examples":[{"en":"Some zoos allow koalas to be passed from stranger to stranger.","zh":"有些動物園允許樹熊在陌生人之間傳來傳去。"},{"en":"To be passed from stranger to stranger means to be handed from one unfamiliar person to another.","zh":"在陌生人之間傳來傳去，是指從一個不熟悉的人手中交到另一個不熟悉的人手中。"},{"en":"A baby animal may become frightened if it is passed from stranger to stranger.","zh":"如果幼小動物在陌生人之間傳來傳去，可能會受驚。"},{"en":"Repeated contact with strangers can create stress even if no one means harm.","zh":"反覆接觸陌生人即使沒有人有惡意，也會造成壓力。"},{"en":"This phrase shows the loss of control experienced by the animal.","zh":"這個短語顯示動物失去控制感。"}],"source":"125 - Koalas.pdf","sourcePage":13},{"front":"love to squeeze them","meaning":"喜歡緊抱牠們","examples":[{"en":"Many children love to squeeze koalas.","zh":"許多孩子喜歡緊抱樹熊。"},{"en":"To love to squeeze them means to enjoy holding them tightly.","zh":"喜歡緊抱牠們，是指享受把牠們抱得很緊。"},{"en":"Children may squeeze soft toys because they feel warm and comforting.","zh":"孩子可能緊抱毛公仔，因為它感覺溫暖舒服。"},{"en":"Squeezing a real animal can hurt or frighten it, even if the child means affection.","zh":"緊抱真正動物可能傷害或嚇到牠，即使孩子只是表達喜愛。"},{"en":"This phrase shows how human affection can become harmful.","zh":"這個短語顯示人類的愛意如何變成傷害。"}],"source":"125 - Koalas.pdf","sourcePage":13},{"front":"have no idea how to","meaning":"完全不知道如何……","examples":[{"en":"Most people have no idea how to handle koalas.","zh":"大多數人完全不知道如何抱摸樹熊。"},{"en":"To have no idea how to do something means to completely lack the knowledge or skill.","zh":"完全不知道如何做某事，是指完全缺乏相關知識或技能。"},{"en":"A new driver may have no idea how to change a tyre.","zh":"新手司機可能完全不知道如何換輪胎。"},{"en":"If visitors have no idea how to handle animals, accidents and stress can happen.","zh":"如果遊客完全不知道如何抱摸動物，就可能發生意外和壓力。"},{"en":"This phrase stresses ignorance, not just mild uncertainty.","zh":"這個短語強調無知，而不只是輕微不確定。"}],"source":"125 - Koalas.pdf","sourcePage":13},{"front":"handle the animals","meaning":"抱摸或處理這些動物","examples":[{"en":"Most people do not know how to handle the animals.","zh":"大多數人不知道如何抱摸或處理這些動物。"},{"en":"To handle the animals means to touch, hold, move, or manage them safely.","zh":"抱摸或處理動物，是指安全地觸摸、抱起、移動或管理牠們。"},{"en":"Zoo staff learn how to handle animals without frightening or injuring them.","zh":"動物園員工學習如何處理動物而不嚇到或傷害牠們。"},{"en":"Poor handling can stress animals even when people are gentle in intention.","zh":"不當處理即使出於溫柔意圖，也可能令動物受壓。"},{"en":"This phrase refers to physical contact and care.","zh":"這個短語指身體接觸和照顧。"}],"source":"125 - Koalas.pdf","sourcePage":13},{"front":"cling to their handler","meaning":"抱緊照顧者","examples":[{"en":"Koalas like to cling to their handler.","zh":"樹熊喜歡抱緊牠們的照顧者。"},{"en":"To cling to their handler means to hold tightly onto the person caring for or holding them.","zh":"抱緊照顧者，是指緊緊抓住照顧或抱着牠們的人。"},{"en":"A frightened child may cling to a parent in a crowded station.","zh":"受驚孩子可能在擁擠車站抱緊父母。"},{"en":"Koalas cling because a person’s arm can feel like a tree branch.","zh":"樹熊會抱緊，因為人的手臂可能感覺像樹枝。"},{"en":"This phrase shows the animal seeking security.","zh":"這個短語顯示動物尋求安全感。"}],"source":"125 - Koalas.pdf","sourcePage":14},{"front":"in their own time","meaning":"按自己的節奏","examples":[{"en":"Koalas like to cling to their handler in their own time.","zh":"樹熊喜歡按自己的節奏抱緊照顧者。"},{"en":"In their own time means at their own pace, when they are ready.","zh":"按自己的節奏，是指以自己的速度，在自己準備好時進行。"},{"en":"A shy student may answer questions in their own time after feeling safe.","zh":"害羞學生感到安全後，可能按自己的節奏回答問題。"},{"en":"Animals become less stressed when they are allowed to move in their own time.","zh":"當動物被允許按自己的節奏移動，壓力會較少。"},{"en":"This phrase emphasises patience and control for the animal or person.","zh":"這個短語強調給動物或人耐心和控制感。"}],"source":"125 - Koalas.pdf","sourcePage":14},{"front":"use someone’s arm as a tree","meaning":"把某人的手臂當成樹","examples":[{"en":"Koalas use the handler’s arm as a tree.","zh":"樹熊把照顧者的手臂當成樹。"},{"en":"To use someone’s arm as a tree means to grip the arm as if it were a tree trunk or branch.","zh":"把某人的手臂當成樹，是指像抓住樹幹或樹枝一樣抓住手臂。"},{"en":"A small child may use an adult’s arm as support when learning to climb.","zh":"小孩學攀爬時，可能把成人手臂當作支撐。"},{"en":"Koalas grip arms because their claws and instincts are made for trees.","zh":"樹熊會抓住手臂，因為牠們的爪和本能是為樹而設。"},{"en":"This phrase explains why handling can be uncomfortable or risky for both sides.","zh":"這個短語解釋為何抱摸對雙方都可能不舒服或有風險。"}],"source":"125 - Koalas.pdf","sourcePage":14},{"front":"for these reasons","meaning":"基於這些原因","examples":[{"en":"For these reasons, a conservation society is campaigning to ban koala cuddling.","zh":"基於這些原因，一個保育組織正在發起運動禁止抱樹熊活動。"},{"en":"For these reasons means because of the points just mentioned.","zh":"基於這些原因，是指因為剛才提到的幾點。"},{"en":"The road is narrow, dark, and busy; for these reasons, students should not walk there alone.","zh":"這條路狹窄、昏暗又繁忙；基於這些原因，學生不應獨自走那裡。"},{"en":"This phrase helps connect evidence with a conclusion or action.","zh":"這個短語幫助把證據與結論或行動連接起來。"},{"en":"It is useful when several causes support one decision.","zh":"當幾個原因支持一個決定時，它很有用。"}],"source":"125 - Koalas.pdf","sourcePage":14},{"front":"Association of Fauna and Marine Parks","meaning":"動物及海洋公園協會","examples":[{"en":"The Association of Fauna and Marine Parks is campaigning to ban koala cuddling.","zh":"動物及海洋公園協會正在發起運動禁止抱樹熊活動。"},{"en":"The Association of Fauna and Marine Parks is named as a group involved in animal protection.","zh":"動物及海洋公園協會被指為參與動物保護的組織。"},{"en":"An association can represent parks, experts, or organisations with shared goals.","zh":"協會可以代表有共同目標的公園、專家或組織。"},{"en":"When an association campaigns, it tries to change public policy or behaviour.","zh":"當協會發起運動，它會嘗試改變公共政策或行為。"},{"en":"This name identifies who is taking action against koala cuddling.","zh":"這個名稱指出誰正在採取行動反對抱樹熊活動。"}],"source":"125 - Koalas.pdf","sourcePage":14},{"front":"conservation society","meaning":"保育組織","examples":[{"en":"The association is an Australian conservation society.","zh":"該協會是一個澳洲保育組織。"},{"en":"A conservation society is an organisation that works to protect animals, plants, or natural places.","zh":"保育組織是致力保護動物、植物或自然地方的組織。"},{"en":"A conservation society may run campaigns, research wildlife, and educate the public.","zh":"保育組織可能發起運動、研究野生動物並教育公眾。"},{"en":"Such groups often act when human activities harm animals.","zh":"當人類活動傷害動物時，這類組織常會採取行動。"},{"en":"This phrase describes an organisation focused on protection.","zh":"這個短語描述專注於保護的組織。"}],"source":"125 - Koalas.pdf","sourcePage":14},{"front":"campaign to ban","meaning":"發起運動禁止……","examples":[{"en":"The association is campaigning to ban koala cuddling.","zh":"該協會正在發起運動禁止抱樹熊活動。"},{"en":"To campaign to ban something means to organise public action to stop it legally or officially.","zh":"發起運動禁止某事，是指組織公眾行動，以法律或官方方式停止它。"},{"en":"Parents may campaign to ban junk food advertising near schools.","zh":"家長可能發起運動禁止學校附近的垃圾食品廣告。"},{"en":"A campaign to ban a harmful activity needs evidence and public support.","zh":"禁止有害活動的運動需要證據和公眾支持。"},{"en":"This phrase connects activism with a legal or official goal.","zh":"這個短語把行動倡議與法律或官方目標連接起來。"}],"source":"125 - Koalas.pdf","sourcePage":14},{"front":"policy on","meaning":"關於……的政策","examples":[{"en":"Policy on koala handling is determined by state authorities.","zh":"關於樹熊抱摸的政策由州政府當局決定。"},{"en":"Policy on something means the official rules or approach about that issue.","zh":"關於某事的政策，是指對該議題的官方規則或做法。"},{"en":"A school’s policy on phones may say students must keep them in lockers.","zh":"學校關於手機的政策可能規定學生必須把手機放在儲物櫃。"},{"en":"Policy on animal handling affects what visitors and staff are allowed to do.","zh":"關於動物抱摸的政策會影響遊客和員工獲准做甚麼。"},{"en":"This phrase introduces the area covered by a rule.","zh":"這個短語引入規則涵蓋的範圍。"}],"source":"125 - Koalas.pdf","sourcePage":14},{"front":"be determined by","meaning":"由……決定","examples":[{"en":"Policy on koala handling is determined by state government authorities.","zh":"關於樹熊抱摸的政策由州政府當局決定。"},{"en":"To be determined by something means to be decided or controlled by it.","zh":"由某物決定，是指由它作出決定或控制。"},{"en":"School holiday dates are determined by the education authority.","zh":"學校假期日期由教育當局決定。"},{"en":"If rules are determined by local authorities, they may differ from place to place.","zh":"如果規則由地方當局決定，各地可能不同。"},{"en":"This phrase explains who or what has decision-making power.","zh":"這個短語解釋誰或甚麼擁有決策權。"}],"source":"125 - Koalas.pdf","sourcePage":14},{"front":"state government authorities","meaning":"州政府當局","examples":[{"en":"State government authorities determine koala-handling policy.","zh":"州政府當局決定樹熊抱摸政策。"},{"en":"State government authorities are official bodies that make rules within a state.","zh":"州政府當局是在州內制定規則的官方機構。"},{"en":"State government authorities may manage schools, transport, health, or wildlife rules.","zh":"州政府當局可能管理學校、交通、健康或野生動物規則。"},{"en":"When state authorities control policy, national rules may not be uniform.","zh":"當州當局控制政策，全國規則可能不一致。"},{"en":"This phrase identifies the official decision-makers.","zh":"這個短語指出官方決策者。"}],"source":"125 - Koalas.pdf","sourcePage":14},{"front":"lobby","meaning":"游說","examples":[{"en":"The association is lobbying the Australian Nature Conservation Agency.","zh":"該協會正在游說澳洲自然保育機構。"},{"en":"To lobby means to try to persuade officials or organisations to change a policy.","zh":"游說，是指嘗試說服官員或組織改變政策。"},{"en":"Parents may lobby the school to improve road safety near the gate.","zh":"家長可能游說學校改善校門附近道路安全。"},{"en":"Lobbying can lead to new rules if the evidence and public pressure are strong.","zh":"如果證據和公眾壓力強，游說可以導致新規則。"},{"en":"This word describes organised persuasion, not casual complaining.","zh":"這個詞描述有組織的說服，而不是隨口抱怨。"}],"source":"125 - Koalas.pdf","sourcePage":14},{"front":"Australian Nature Conservation Agency","meaning":"澳洲自然保育機構","examples":[{"en":"The association is lobbying the Australian Nature Conservation Agency.","zh":"該協會正在游說澳洲自然保育機構。"},{"en":"The Australian Nature Conservation Agency is named as the body being asked to act on koala care.","zh":"澳洲自然保育機構被指出是被要求就樹熊照顧採取行動的機構。"},{"en":"Conservation agencies often create guidance to protect wildlife and habitats.","zh":"保育機構常制定指引來保護野生動物和棲息地。"},{"en":"When a national agency is involved, local rules may become more consistent.","zh":"當全國機構參與，地方規則可能變得更一致。"},{"en":"This phrase identifies the official conservation body in the passage.","zh":"這個短語指出篇章中的官方保育機構。"}],"source":"125 - Koalas.pdf","sourcePage":15},{"front":"with the aim of","meaning":"旨在","examples":[{"en":"The association is lobbying with the aim of establishing national guidelines.","zh":"該協會正在游說，旨在制定全國指引。"},{"en":"With the aim of means with the purpose of achieving something.","zh":"旨在，是指以達成某事為目的。"},{"en":"A school may hold extra classes with the aim of helping weak students catch up.","zh":"學校可能開設額外課堂，旨在幫助成績較弱的學生追回進度。"},{"en":"This phrase clearly links an action with its intended goal.","zh":"這個短語清楚把行動與預期目標連接起來。"},{"en":"It is common in formal writing about campaigns and policies.","zh":"它常見於關於運動和政策的正式寫作。"}],"source":"125 - Koalas.pdf","sourcePage":15},{"front":"establish national guidelines","meaning":"制定全國指引","examples":[{"en":"The association wants to establish national guidelines.","zh":"該協會希望制定全國指引。"},{"en":"To establish national guidelines means to create official advice or rules for the whole country.","zh":"制定全國指引，是指為整個國家建立官方建議或規則。"},{"en":"Health authorities may establish national guidelines for school lunches.","zh":"衛生當局可能制定學校午餐的全國指引。"},{"en":"National guidelines can reduce confusion when local rules are inconsistent.","zh":"當地方規則不一致，全國指引可以減少混亂。"},{"en":"This phrase describes creating a shared standard.","zh":"這個短語描述建立共同標準。"}],"source":"125 - Koalas.pdf","sourcePage":15},{"front":"following a wave of publicity","meaning":"在一輪廣泛報道之後","examples":[{"en":"Following a wave of publicity, some parks stopped using koalas as props.","zh":"在一輪廣泛報道之後，有些公園停止把樹熊用作道具。"},{"en":"Following a wave of publicity means after strong media attention or public discussion.","zh":"在一輪廣泛報道之後，是指在強烈媒體關注或公眾討論之後。"},{"en":"Following a wave of publicity about food safety, a restaurant may change its kitchen rules.","zh":"在一輪關於食物安全的廣泛報道之後，餐廳可能改變廚房規則。"},{"en":"Public attention can pressure organisations to change harmful practices.","zh":"公眾關注可以迫使組織改變有害做法。"},{"en":"This phrase shows that media coverage helped trigger action.","zh":"這個短語顯示媒體報道幫助觸發行動。"}],"source":"125 - Koalas.pdf","sourcePage":15},{"front":"wildlife parks","meaning":"野生動物園","examples":[{"en":"Some wildlife parks stopped using koalas as photographic props.","zh":"有些野生動物園停止把樹熊用作拍照道具。"},{"en":"Wildlife parks are visitor sites where wild animals are displayed or cared for.","zh":"野生動物園是展示或照顧野生動物的遊客場所。"},{"en":"A wildlife park may combine education, tourism, and animal conservation.","zh":"野生動物園可能結合教育、旅遊和動物保育。"},{"en":"Wildlife parks must balance visitor interest with animal welfare.","zh":"野生動物園必須平衡遊客興趣與動物福利。"},{"en":"This phrase refers to parks where people can see wildlife up close.","zh":"這個短語指人們能近距離觀看野生動物的公園。"}],"source":"125 - Koalas.pdf","sourcePage":15},{"front":"photographic props","meaning":"拍照道具","examples":[{"en":"Some zoos used koalas as photographic props.","zh":"有些動物園把樹熊用作拍照道具。"},{"en":"Photographic props are objects or living things used mainly to make a photo look interesting.","zh":"拍照道具是主要用來令照片有趣的物件或生物。"},{"en":"A studio may use chairs, flowers, and signs as photographic props.","zh":"攝影棚可能使用椅子、花和標誌作拍照道具。"},{"en":"Treating animals as props can ignore their comfort and welfare.","zh":"把動物當作道具可能忽視牠們的舒適和福利。"},{"en":"This phrase criticises using koalas as objects for tourist photos.","zh":"這個短語批評把樹熊當作旅遊照片中的物件。"}],"source":"125 - Koalas.pdf","sourcePage":15},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Candidates choose the correct letter for each question.","zh":"考生為每條題目選出正確字母。"},{"en":"To choose the correct letter means to select the option letter that gives the right answer.","zh":"選出正確字母，是指選擇代表正確答案的選項字母。"},{"en":"In a multiple-choice test, students may choose A, B, C, or D.","zh":"在選擇題測驗中，學生可能選 A、B、C 或 D。"},{"en":"Choosing the correct letter requires understanding the passage, not just guessing.","zh":"選出正確字母需要理解篇章，而不只是猜測。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"125 - Koalas.pdf","sourcePage":15},{"front":"decline for the following reasons","meaning":"因以下原因而下降","examples":[{"en":"Koala numbers have declined for several reasons.","zh":"樹熊數量因幾個原因而下降。"},{"en":"To decline for the following reasons means to decrease because of the reasons listed next.","zh":"因以下原因而下降，是指因接下來列出的原因而減少。"},{"en":"A club may decline for the following reasons: weak leadership, poor planning, and few new members.","zh":"學會可能因以下原因而衰落：領導薄弱、規劃差和新成員少。"},{"en":"Listing reasons helps readers see that decline is caused by several factors.","zh":"列出原因幫助讀者看見下降由幾個因素造成。"},{"en":"This phrase introduces an explanation for falling numbers.","zh":"這個短語引入數量下降的解釋。"}],"source":"125 - Koalas.pdf","sourcePage":15},{"front":"all the following reasons except","meaning":"以下所有原因，除了……","examples":[{"en":"The question asks for the reason that is not mentioned.","zh":"題目要求找出沒有被提及的原因。"},{"en":"All the following reasons except means every listed reason is correct except one.","zh":"以下所有原因，除了……，是指列出的原因全部正確，除了一個。"},{"en":"In a test, “all except” questions require students to find the odd one out.","zh":"在測驗中，“all except” 題要求學生找出不屬於的一項。"},{"en":"This question type checks careful reading because one option may sound possible but is not in the text.","zh":"這種題型測試仔細閱讀，因為一個選項可能聽起來合理但文本沒有提及。"},{"en":"The phrase tells students to look for the missing or incorrect item.","zh":"這個短語告訴學生要找缺失或錯誤的一項。"}],"source":"125 - Koalas.pdf","sourcePage":15},{"front":"frequent births","meaning":"頻繁生育","examples":[{"en":"The option mentions frequent births from which few offspring survive.","zh":"該選項提到頻繁生育，但很少後代存活。"},{"en":"Frequent births mean babies are born often or at short intervals.","zh":"頻繁生育，是指幼崽經常或以短間隔出生。"},{"en":"Some animals have frequent births so that enough young survive in difficult environments.","zh":"有些動物會頻繁生育，使足夠幼崽在艱難環境中存活。"},{"en":"Frequent births would usually help a population recover faster.","zh":"頻繁生育通常會幫助族群更快恢復。"},{"en":"In this passage, the issue is the opposite: koalas reproduce slowly.","zh":"在這篇文章中，問題相反：樹熊繁殖緩慢。"}],"source":"125 - Koalas.pdf","sourcePage":15},{"front":"offspring survive","meaning":"後代存活","examples":[{"en":"The question asks whether few offspring survive.","zh":"題目問是否很少後代存活。"},{"en":"Offspring survive means young animals live after birth and grow successfully.","zh":"後代存活，是指幼小動物出生後活下來並成功成長。"},{"en":"In harsh weather, fewer offspring may survive to adulthood.","zh":"在惡劣天氣中，較少後代可能能存活到成年。"},{"en":"If many offspring survive, a population can recover more quickly.","zh":"如果許多後代存活，族群可以更快恢復。"},{"en":"This phrase is used when discussing reproduction and population growth.","zh":"這個短語用於討論繁殖和族群增長。"}],"source":"125 - Koalas.pdf","sourcePage":15},{"front":"fully digest their food","meaning":"完全消化食物","examples":[{"en":"The question asks what helps koalas fully digest their food.","zh":"題目問甚麼幫助樹熊完全消化食物。"},{"en":"To fully digest their food means to break it down enough to use its nutrients.","zh":"完全消化食物，是指把食物分解到足以利用其營養。"},{"en":"People chew food well to help their bodies digest it more fully.","zh":"人們仔細咀嚼食物，以幫助身體更完全地消化。"},{"en":"Koalas need time, bacteria, and special organs to fully digest eucalyptus leaves.","zh":"樹熊需要時間、細菌和特殊器官才能完全消化桉樹葉。"},{"en":"This phrase focuses on complete digestion, not just eating.","zh":"這個短語聚焦完整消化，而不只是吃東西。"}],"source":"125 - Koalas.pdf","sourcePage":16},{"front":"toxic substances","meaning":"有毒物質","examples":[{"en":"Eucalyptus leaves contain toxic substances.","zh":"桉樹葉含有有毒物質。"},{"en":"Toxic substances are materials that can poison or harm living things.","zh":"有毒物質是可以毒害或傷害生物的材料。"},{"en":"Cleaning products may contain toxic substances and should be kept away from children.","zh":"清潔產品可能含有有毒物質，應放在兒童接觸不到的地方。"},{"en":"If food contains toxic substances, the body must remove or process them safely.","zh":"如果食物含有有毒物質，身體必須安全移除或處理它們。"},{"en":"This phrase describes harmful chemicals or materials.","zh":"這個短語描述有害化學品或材料。"}],"source":"125 - Koalas.pdf","sourcePage":16},{"front":"dissolve fibre","meaning":"溶解纖維","examples":[{"en":"The option refers to organs that dissolve fibre.","zh":"該選項指能溶解纖維的器官。"},{"en":"To dissolve fibre means to break plant fibre down into simpler material.","zh":"溶解纖維，是指把植物纖維分解成較簡單材料。"},{"en":"In science class, students may learn that some substances dissolve in water while others do not.","zh":"在科學課中，學生可能學到有些物質會溶於水，有些不會。"},{"en":"Koalas do not simply dissolve fibre with organs; bacteria help break it down.","zh":"樹熊不是單純用器官溶解纖維；細菌幫助分解它。"},{"en":"This phrase relates to digestion of tough plant material.","zh":"這個短語與堅韌植物材料的消化有關。"}],"source":"125 - Koalas.pdf","sourcePage":16},{"front":"remain inactive","meaning":"保持不活動","examples":[{"en":"Koalas remain inactive for a long period to digest food.","zh":"樹熊長時間保持不活動來消化食物。"},{"en":"To remain inactive means to stay still or do very little movement.","zh":"保持不活動，是指保持靜止或很少移動。"},{"en":"After surgery, a patient may remain inactive for several hours to recover safely.","zh":"手術後，病人可能保持不活動數小時以安全恢復。"},{"en":"Koalas remain inactive because their digestion requires long rest.","zh":"樹熊保持不活動，因為牠們的消化需要長時間休息。"},{"en":"This phrase describes a continued state of low movement.","zh":"這個短語描述持續的低活動狀態。"}],"source":"125 - Koalas.pdf","sourcePage":16},{"front":"react when threatened","meaning":"受威脅時作出反應","examples":[{"en":"The question asks how koalas react when threatened.","zh":"題目問樹熊受威脅時如何反應。"},{"en":"To react when threatened means to respond when danger or stress is felt.","zh":"受威脅時作出反應，是指感到危險或壓力時作出回應。"},{"en":"A cat may hide under a bed when threatened by loud noise.","zh":"貓受嘈雜聲威脅時，可能躲到床下。"},{"en":"Koalas may show small signs of distress rather than attack when threatened.","zh":"樹熊受威脅時可能表現出細小不安跡象，而不是攻擊。"},{"en":"This phrase focuses on behaviour under danger.","zh":"這個短語聚焦危險下的行為。"}],"source":"125 - Koalas.pdf","sourcePage":16},{"front":"show signs of distress","meaning":"表現出不安跡象","examples":[{"en":"Koalas may show signs of distress when upset.","zh":"樹熊不安時可能表現出不安跡象。"},{"en":"To show signs of distress means to display clues that something is frightened, stressed, or suffering.","zh":"表現出不安跡象，是指顯示害怕、受壓或痛苦的線索。"},{"en":"A child may show signs of distress by becoming quiet and avoiding eye contact.","zh":"孩子可能透過變得安靜和避免眼神接觸來表現出不安跡象。"},{"en":"Small signs can matter when an animal does not express pain loudly.","zh":"當動物不大聲表達痛楚時，細小跡象也很重要。"},{"en":"This phrase describes visible evidence of inner discomfort.","zh":"這個短語描述內在不適的可見證據。"}],"source":"125 - Koalas.pdf","sourcePage":16},{"front":"counterattack furiously","meaning":"猛烈反擊","examples":[{"en":"The option asks whether koalas counterattack furiously.","zh":"該選項問樹熊是否會猛烈反擊。"},{"en":"To counterattack furiously means to fight back with strong anger and force.","zh":"猛烈反擊，是指以強烈憤怒和力量回擊。"},{"en":"A team may counterattack furiously after losing the first goal.","zh":"球隊失第一球後可能猛烈反擊。"},{"en":"Koalas do not usually counterattack furiously; they tend to show subtle distress instead.","zh":"樹熊通常不會猛烈反擊；牠們反而傾向表現細微不安。"},{"en":"This phrase describes aggressive resistance.","zh":"這個短語描述具攻擊性的抵抗。"}],"source":"125 - Koalas.pdf","sourcePage":16},{"front":"sharp claws","meaning":"鋒利爪子","examples":[{"en":"Koalas have sharp claws, but they use them mainly for gripping bark.","zh":"樹熊有鋒利爪子，但主要用來抓緊樹皮。"},{"en":"Sharp claws are pointed claws that can cut, scratch, or grip strongly.","zh":"鋒利爪子是尖銳的爪，可以切割、抓傷或有力抓住東西。"},{"en":"Cats use sharp claws to climb curtains or defend themselves.","zh":"貓用鋒利爪子爬窗簾或保護自己。"},{"en":"Koalas’ sharp claws help them climb trees, not attack people.","zh":"樹熊的鋒利爪子幫助牠們爬樹，而不是攻擊人。"},{"en":"This phrase identifies a physical feature and its function.","zh":"這個短語指出身體特徵及其功能。"}],"source":"125 - Koalas.pdf","sourcePage":16},{"front":"injure people","meaning":"傷害人","examples":[{"en":"The option asks whether koalas use their claws to injure people.","zh":"該選項問樹熊是否用爪傷害人。"},{"en":"To injure people means to hurt them physically.","zh":"傷害人，是指對人造成身體損傷。"},{"en":"Broken glass can injure people if it is left on the floor.","zh":"如果碎玻璃留在地上，可能傷害人。"},{"en":"Animals may injure people accidentally if handled wrongly.","zh":"如果被錯誤抱摸，動物可能意外傷害人。"},{"en":"This phrase focuses on physical harm to humans.","zh":"這個短語聚焦對人類的身體傷害。"}],"source":"125 - Koalas.pdf","sourcePage":16},{"front":"exploit koalas","meaning":"利用樹熊圖利","examples":[{"en":"The question asks how Australian zoos exploit koalas.","zh":"題目問澳洲動物園如何利用樹熊圖利。"},{"en":"To exploit koalas means to use them unfairly for money, attention, or benefit.","zh":"利用樹熊圖利，是指不公平地利用牠們來賺錢、吸引注意或取得好處。"},{"en":"A business exploits workers if it pays very little while making large profits.","zh":"如果企業支付很低工資但賺取大利潤，就是剝削工人。"},{"en":"Zoos exploit koalas when they use them mainly as photo attractions despite stress.","zh":"當動物園不顧壓力，主要把樹熊用作拍照景點，就是利用牠們圖利。"},{"en":"This phrase carries a negative judgement.","zh":"這個短語帶有負面判斷。"}],"source":"125 - Koalas.pdf","sourcePage":16},{"front":"encourage people to breed","meaning":"鼓勵人們繁殖……","examples":[{"en":"The option says zoos encourage people to breed koalas as pets.","zh":"該選項說動物園鼓勵人們把樹熊作寵物繁殖。"},{"en":"To encourage people to breed animals means to push or persuade them to produce more animals.","zh":"鼓勵人們繁殖動物，是指推動或說服他們讓動物繁殖更多。"},{"en":"A shelter should not encourage people to breed pets when many abandoned animals need homes.","zh":"當許多被遺棄動物需要家園時，收容所不應鼓勵人們繁殖寵物。"},{"en":"Encouraging breeding can increase animal numbers but may also create welfare problems.","zh":"鼓勵繁殖可以增加動物數量，但也可能造成福利問題。"},{"en":"This phrase describes promoting reproduction by people.","zh":"這個短語描述推動人類安排繁殖。"}],"source":"125 - Koalas.pdf","sourcePage":16},{"front":"breed koalas as pets","meaning":"將樹熊作寵物繁殖","examples":[{"en":"The option mentions breeding koalas as pets.","zh":"該選項提到將樹熊作寵物繁殖。"},{"en":"To breed koalas as pets means to produce koalas for private people to keep at home.","zh":"將樹熊作寵物繁殖，是指繁殖樹熊，讓私人在家飼養。"},{"en":"Wild animals are usually unsuitable as pets because their needs are complex.","zh":"野生動物通常不適合作寵物，因為牠們的需要很複雜。"},{"en":"Breeding wild animals as pets can encourage illegal trade and poor care.","zh":"將野生動物作寵物繁殖可能鼓勵非法交易和不當照顧。"},{"en":"This phrase describes a harmful or unrealistic use of wildlife.","zh":"這個短語描述對野生動物有害或不現實的用途。"}],"source":"125 - Koalas.pdf","sourcePage":17},{"front":"allow tourists to hug","meaning":"允許遊客擁抱……","examples":[{"en":"Some zoos allow tourists to hug koalas for photographs.","zh":"有些動物園允許遊客擁抱樹熊拍照。"},{"en":"To allow tourists to hug an animal means to permit visitors to hold it closely.","zh":"允許遊客擁抱動物，是指准許遊客近距離抱着牠。"},{"en":"A wildlife park may allow tourists to feed animals but not touch them.","zh":"野生動物園可能允許遊客餵動物，但不允許觸摸。"},{"en":"Allowing tourists to hug koalas can create income but also animal stress.","zh":"允許遊客擁抱樹熊可以創造收入，但也會令動物受壓。"},{"en":"This phrase describes a tourist activity involving direct contact.","zh":"這個短語描述涉及直接接觸的旅遊活動。"}],"source":"125 - Koalas.pdf","sourcePage":17},{"front":"establish campaigns","meaning":"發起運動","examples":[{"en":"The option says zoos establish koala campaigns.","zh":"該選項說動物園發起樹熊運動。"},{"en":"To establish campaigns means to create organised efforts to achieve a goal.","zh":"發起運動，是指創立有組織的努力去達成目標。"},{"en":"Schools may establish campaigns to reduce plastic waste.","zh":"學校可能發起減少塑膠垃圾的運動。"},{"en":"Campaigns need clear messages, public support, and practical action.","zh":"運動需要清晰訊息、公眾支持和實際行動。"},{"en":"This phrase describes starting structured public action.","zh":"這個短語描述開始有結構的公眾行動。"}],"source":"125 - Koalas.pdf","sourcePage":17},{"front":"authorities","meaning":"當局","examples":[{"en":"The authorities may introduce guidelines to protect koalas.","zh":"當局可能引入指引來保護樹熊。"},{"en":"Authorities are official organisations or people with power to make decisions and rules.","zh":"當局是有權作決定和制定規則的官方組織或人員。"},{"en":"Transport authorities may change bus routes after public complaints.","zh":"交通當局可能在公眾投訴後更改巴士路線。"},{"en":"When authorities introduce guidelines, they can influence how people behave.","zh":"當當局引入指引，就能影響人們的行為。"},{"en":"This word refers to official decision-makers.","zh":"這個詞指官方決策者。"}],"source":"125 - Koalas.pdf","sourcePage":17},{"front":"introduce national guidelines","meaning":"引入全國指引","examples":[{"en":"The authorities may introduce national guidelines for handling koalas.","zh":"當局可能引入關於抱摸樹熊的全國指引。"},{"en":"To introduce national guidelines means to bring in official advice or rules for the whole country.","zh":"引入全國指引，是指帶入適用於全國的官方建議或規則。"},{"en":"A government may introduce national guidelines for school food safety.","zh":"政府可能引入學校食物安全的全國指引。"},{"en":"National guidelines can make local practices more consistent.","zh":"全國指引可以令地方做法更一致。"},{"en":"This phrase describes an official step toward standard rules.","zh":"這個短語描述走向統一規則的官方步驟。"}],"source":"125 - Koalas.pdf","sourcePage":17},{"front":"handling koalas","meaning":"抱摸或處理樹熊","examples":[{"en":"Guidelines may control the handling of koalas.","zh":"指引可能規管抱摸或處理樹熊。"},{"en":"Handling koalas means touching, holding, moving, or managing koalas.","zh":"抱摸或處理樹熊，是指觸摸、抱起、移動或管理樹熊。"},{"en":"Handling koalas requires training because they are sensitive and easily stressed.","zh":"處理樹熊需要訓練，因為牠們敏感且容易受壓。"},{"en":"Poor handling can harm koalas even if visitors think they are being gentle.","zh":"不當抱摸即使遊客以為自己很溫柔，也可能傷害樹熊。"},{"en":"This phrase refers to physical contact and care procedures.","zh":"這個短語指身體接觸和照顧程序。"}],"source":"125 - Koalas.pdf","sourcePage":17},{"front":"discourage the public from","meaning":"勸阻公眾不要……","examples":[{"en":"The option asks whether authorities discourage the public from visiting zoos.","zh":"該選項問當局是否勸阻公眾不要參觀動物園。"},{"en":"To discourage the public from doing something means to make ordinary people less willing to do it.","zh":"勸阻公眾不要做某事，是指令普通人較不願意做該事。"},{"en":"Health warnings discourage the public from smoking in public places.","zh":"健康警告勸阻公眾不要在公共場所吸煙。"},{"en":"Authorities may discourage harmful behaviour without banning all related activities.","zh":"當局可以勸阻有害行為，而不禁止所有相關活動。"},{"en":"This phrase describes reducing public willingness.","zh":"這個短語描述降低公眾意願。"}],"source":"125 - Koalas.pdf","sourcePage":17},{"front":"views of the writer","meaning":"作者觀點","examples":[{"en":"Students compare statements with the views of the writer.","zh":"學生把陳述與作者觀點作比較。"},{"en":"Views of the writer are the opinions or attitudes expressed by the author.","zh":"作者觀點是作者表達的意見或態度。"},{"en":"In reading tests, students must separate the writer’s views from factual information.","zh":"在閱讀測驗中，學生必須區分作者觀點和事實資料。"},{"en":"A statement matches the writer’s view only if the author clearly supports it.","zh":"只有當作者清楚支持某陳述，它才符合作者觀點。"},{"en":"This phrase is common in Yes, No, Not Given questions.","zh":"這個短語常見於 Yes、No、Not Given 題。"}],"source":"125 - Koalas.pdf","sourcePage":17},{"front":"agree with the views of","meaning":"與……的觀點一致","examples":[{"en":"Students write YES if the statement agrees with the views of the writer.","zh":"如果陳述與作者觀點一致，學生寫 YES。"},{"en":"To agree with the views of someone means to match that person’s opinion.","zh":"與某人的觀點一致，是指符合那個人的意見。"},{"en":"A statement agrees with the writer’s views if it reflects the attitude shown in the text.","zh":"如果陳述反映文本中顯示的態度，它就與作者觀點一致。"},{"en":"Students should choose YES only when the writer clearly supports the idea.","zh":"只有當作者清楚支持該想法時，學生才應選 YES。"},{"en":"This phrase tests understanding of opinion, not just facts.","zh":"這個短語測試對意見的理解，而不只是事實。"}],"source":"125 - Koalas.pdf","sourcePage":17},{"front":"contradict the views of","meaning":"與……的觀點相矛盾","examples":[{"en":"Students write NO if the statement contradicts the views of the writer.","zh":"如果陳述與作者觀點相矛盾，學生寫 NO。"},{"en":"To contradict the views of someone means to go against that person’s opinion.","zh":"與某人的觀點相矛盾，是指與那人的意見相反。"},{"en":"If the writer criticises koala cuddling, a statement praising it would contradict the writer’s views.","zh":"如果作者批評抱樹熊活動，而陳述稱讚它，就與作者觀點相矛盾。"},{"en":"Students should choose NO only when the statement clearly opposes the author’s attitude.","zh":"只有當陳述清楚反對作者態度時，學生才應選 NO。"},{"en":"This phrase helps identify conflict with the writer’s opinion.","zh":"這個短語幫助識別與作者意見的衝突。"}],"source":"125 - Koalas.pdf","sourcePage":17},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"Students write NOT GIVEN if it is impossible to say what the writer thinks.","zh":"如果無法判斷作者想法，學生寫 NOT GIVEN。"},{"en":"Impossible to say means there is not enough information to decide.","zh":"無法判斷，是指資料不足以作出決定。"},{"en":"If a passage mentions a zoo but not its ticket price, it is impossible to say whether it is expensive.","zh":"如果篇章提到一間動物園但沒有說票價，就無法判斷它是否昂貴。"},{"en":"This phrase warns students not to guess from outside knowledge.","zh":"這個短語提醒學生不要用外部知識猜測。"},{"en":"It is used when the text does not reveal the answer.","zh":"當文本沒有透露答案時，就使用它。"}],"source":"125 - Koalas.pdf","sourcePage":17},{"front":"newly arrived human settlers","meaning":"新來的人類定居者","examples":[{"en":"Newly arrived human settlers posed a danger to koalas.","zh":"新來的人類定居者對樹熊構成危險。"},{"en":"Newly arrived human settlers are people who have recently come to live permanently in a place.","zh":"新來的人類定居者，是指最近來到某地永久居住的人。"},{"en":"Newly arrived settlers may change land use by building farms, roads, and towns.","zh":"新來定居者可能透過建農場、道路和城鎮改變土地使用。"},{"en":"New settlement can harm wildlife if it destroys habitat or changes food sources.","zh":"如果新定居破壞棲息地或改變食物來源，就會傷害野生動物。"},{"en":"This phrase links human arrival with environmental impact.","zh":"這個短語把人類到來與環境影響連接起來。"}],"source":"125 - Koalas.pdf","sourcePage":18},{"front":"pose a danger to","meaning":"對……構成危險","examples":[{"en":"Human settlers posed a danger to koalas.","zh":"人類定居者對樹熊構成危險。"},{"en":"To pose a danger to someone or something means to create a risk of harm.","zh":"對某人或某物構成危險，是指造成傷害風險。"},{"en":"Broken stairs pose a danger to elderly residents.","zh":"破損樓梯對長者居民構成危險。"},{"en":"Habitat destruction poses a danger to animals that depend on one type of food.","zh":"棲息地破壞對依賴一種食物的動物構成危險。"},{"en":"This phrase describes a threat caused by a person, thing, or situation.","zh":"這個短語描述由人、事物或情況造成的威脅。"}],"source":"125 - Koalas.pdf","sourcePage":18},{"front":"throughout most of Australia","meaning":"遍佈澳洲大部分地區","examples":[{"en":"The statement asks whether koalas can still be seen throughout most of Australia.","zh":"該陳述問樹熊是否仍可在澳洲大部分地區看見。"},{"en":"Throughout most of Australia means across the majority of the country.","zh":"遍佈澳洲大部分地區，是指分布在該國大多數地方。"},{"en":"A bird found throughout most of a country is common in many regions.","zh":"如果一種鳥遍佈某國大部分地區，它就在許多地區常見。"},{"en":"If koalas are only in scattered pockets, they are not found throughout most of Australia.","zh":"如果樹熊只在零散小區域出現，就不是遍佈澳洲大部分地區。"},{"en":"This phrase describes wide geographical distribution.","zh":"這個短語描述廣泛地理分布。"}],"source":"125 - Koalas.pdf","sourcePage":18},{"front":"take decades to","meaning":"需要數十年去……","examples":[{"en":"The statement asks whether eucalyptus trees take decades to recover.","zh":"該陳述問桉樹是否需要數十年才能恢復。"},{"en":"To take decades to do something means to need many tens of years to complete it.","zh":"需要數十年去做某事，是指需要很多個十年才能完成。"},{"en":"A forest may take decades to return after heavy logging.","zh":"森林在嚴重伐木後可能需要數十年才能恢復。"},{"en":"If recovery takes decades, animals depending on that habitat may suffer for a long time.","zh":"如果恢復需要數十年，依賴該棲息地的動物可能長期受苦。"},{"en":"This phrase stresses a very long timescale.","zh":"這個短語強調非常長的時間尺度。"}],"source":"125 - Koalas.pdf","sourcePage":18},{"front":"recover after a fire","meaning":"火災後恢復","examples":[{"en":"Eucalyptus trees can recover after a fire.","zh":"桉樹可以在火災後恢復。"},{"en":"To recover after a fire means to grow back or return to a healthier state after burning.","zh":"火災後恢復，是指燃燒後重新生長或回到較健康狀態。"},{"en":"Some plants recover after a fire when new shoots grow from protected roots.","zh":"有些植物在火災後會從受保護根部長出新芽而恢復。"},{"en":"Fast recovery of trees helps animals regain food and shelter.","zh":"樹木快速恢復幫助動物重新獲得食物和庇護。"},{"en":"This phrase describes ecological healing after fire damage.","zh":"這個短語描述火災破壞後的生態修復。"}],"source":"125 - Koalas.pdf","sourcePage":18},{"front":"food becomes scarce","meaning":"食物變得稀少","examples":[{"en":"The question asks whether koalas fight when food becomes scarce.","zh":"題目問當食物變得稀少時，樹熊是否會打鬥。"},{"en":"Food becomes scarce means food becomes difficult to find or not enough for everyone.","zh":"食物變得稀少，是指食物變得難以找到或不足以供應所有個體。"},{"en":"During a drought, grass may become scarce for farm animals.","zh":"在乾旱期間，農場動物的草可能變得稀少。"},{"en":"When food becomes scarce, some animals compete more strongly.","zh":"當食物變得稀少，有些動物會更激烈競爭。"},{"en":"This phrase describes a shortage of food.","zh":"這個短語描述食物短缺。"}],"source":"125 - Koalas.pdf","sourcePage":18},{"front":"difficult to notice","meaning":"難以察覺","examples":[{"en":"It is difficult to notice when koalas are ill.","zh":"樹熊生病時很難察覺。"},{"en":"Difficult to notice means hard to see, detect, or recognise.","zh":"難以察覺，是指很難看見、發現或辨認。"},{"en":"Early signs of stress can be difficult to notice in a quiet student.","zh":"安靜學生的早期壓力跡象可能難以察覺。"},{"en":"If illness is difficult to notice, regular checks become important.","zh":"如果疾病難以察覺，定期檢查就變得重要。"},{"en":"This phrase describes a problem that is hidden or subtle.","zh":"這個短語描述隱藏或細微的問題。"}],"source":"125 - Koalas.pdf","sourcePage":18},{"front":"contagious human diseases","meaning":"人類傳染病","examples":[{"en":"The statement mentions contagious human diseases.","zh":"該陳述提到人類傳染病。"},{"en":"Contagious human diseases are illnesses that can spread from one person to another.","zh":"人類傳染病是可以在人與人之間傳播的疾病。"},{"en":"Flu is a contagious human disease that spreads through droplets and close contact.","zh":"流感是透過飛沫和近距離接觸傳播的人類傳染病。"},{"en":"In reading questions, a disease may be mentioned in an option even if it is not in the passage.","zh":"在閱讀題中，疾病可能出現在選項中，即使篇章沒有提及。"},{"en":"This phrase refers specifically to infectious diseases among humans.","zh":"這個短語特指人類之間的傳染性疾病。"}],"source":"125 - Koalas.pdf","sourcePage":18},{"front":"through cuddling","meaning":"透過擁抱","examples":[{"en":"The statement asks whether koalas catch diseases through cuddling.","zh":"該陳述問樹熊是否透過擁抱感染疾病。"},{"en":"Through cuddling means by close physical hugging or holding.","zh":"透過擁抱，是指經由近距離抱住或接觸。"},{"en":"A child may calm down through cuddling a soft toy.","zh":"孩子可能透過擁抱毛公仔平靜下來。"},{"en":"Diseases can sometimes spread through close contact, but the passage must state it for an exam answer.","zh":"疾病有時可以透過近距離接觸傳播，但考試答案必須由篇章支持。"},{"en":"This phrase describes the method or route by which something happens.","zh":"這個短語描述某事發生的方法或途徑。"}],"source":"125 - Koalas.pdf","sourcePage":18},{"front":"hold a person’s arm","meaning":"抱住人的手臂","examples":[{"en":"Koalas like to hold a person’s arm as if it were a tree.","zh":"樹熊喜歡抱住人的手臂，好像那是樹一樣。"},{"en":"To hold a person’s arm means to grip or cling to someone’s arm.","zh":"抱住人的手臂，是指抓住或緊貼某人的手臂。"},{"en":"A nervous child may hold a parent’s arm while crossing a busy road.","zh":"緊張的孩子過繁忙馬路時可能抱住父母的手臂。"},{"en":"Koalas hold arms because their natural behaviour is to cling to trees.","zh":"樹熊抱住手臂，因為牠們的自然行為是抱緊樹。"},{"en":"This phrase describes physical contact that may seem cute but is based on climbing instinct.","zh":"這個短語描述看似可愛但基於攀爬本能的身體接觸。"}],"source":"125 - Koalas.pdf","sourcePage":18},{"front":"be embraced","meaning":"被擁抱","examples":[{"en":"The question asks whether koalas like holding an arm when they are embraced.","zh":"題目問樹熊被擁抱時是否喜歡抱住手臂。"},{"en":"To be embraced means to be held closely in someone’s arms.","zh":"被擁抱，是指被某人用手臂近距離抱住。"},{"en":"A child may feel safe when embraced by a parent.","zh":"孩子被父母擁抱時可能感到安全。"},{"en":"For a sensitive wild animal, being embraced by strangers can be stressful.","zh":"對敏感野生動物來說，被陌生人擁抱可能有壓力。"},{"en":"This phrase describes being hugged, not simply being near someone.","zh":"這個短語描述被抱住，而不只是靠近某人。"}],"source":"125 - Koalas.pdf","sourcePage":18},{"front":"in your opinion","meaning":"依你看","examples":[{"en":"The final question asks for the reader’s opinion about the article type.","zh":"最後一題要求讀者依自己看法判斷文章類型。"},{"en":"In your opinion means according to what you think or judge.","zh":"依你看，是指根據你的想法或判斷。"},{"en":"In your opinion, is online learning better for shy students?","zh":"依你看，網上學習對害羞學生是否更好？"},{"en":"This phrase invites personal judgement rather than a fact copied from the text.","zh":"這個短語邀請個人判斷，而不是從文本抄事實。"},{"en":"It is common in discussion, writing, and speaking questions.","zh":"它常見於討論、寫作和口語題。"}],"source":"125 - Koalas.pdf","sourcePage":19},{"front":"article was written by","meaning":"文章由……撰寫","examples":[{"en":"The question asks who the article was written by.","zh":"題目問文章由誰撰寫。"},{"en":"Article was written by means the question asks about the author or type of writer.","zh":"文章由……撰寫，是指題目詢問作者或作者類型。"},{"en":"A news article may be written by a journalist, expert, or guest writer.","zh":"新聞文章可能由記者、專家或特約作者撰寫。"},{"en":"Identifying who wrote an article helps readers judge tone and purpose.","zh":"識別文章由誰撰寫，有助讀者判斷語氣和目的。"},{"en":"This phrase focuses on authorship.","zh":"這個短語聚焦作者身份。"}],"source":"125 - Koalas.pdf","sourcePage":19},{"front":"journalist writing for a magazine","meaning":"為雜誌撰稿的記者","examples":[{"en":"The article sounds like it was written by a journalist for a magazine.","zh":"這篇文章聽起來像由為雜誌撰稿的記者寫成。"},{"en":"A journalist writing for a magazine is a reporter or writer producing an article for magazine readers.","zh":"為雜誌撰稿的記者，是為雜誌讀者撰寫文章的報道員或作者。"},{"en":"Magazine journalists often mix facts, description, interviews, and opinionated tone.","zh":"雜誌記者常混合事實、描述、訪問和帶觀點的語氣。"},{"en":"A lively style and broad explanation can make an article sound like magazine journalism.","zh":"生動風格和廣泛解釋可以令文章聽起來像雜誌新聞寫作。"},{"en":"This phrase identifies a likely writer and publication type.","zh":"這個短語指出可能的作者和出版類型。"}],"source":"125 - Koalas.pdf","sourcePage":19},{"front":"keeper at London Zoo","meaning":"倫敦動物園飼養員","examples":[{"en":"The option suggests the writer may be a keeper at London Zoo.","zh":"該選項暗示作者可能是倫敦動物園飼養員。"},{"en":"A keeper at London Zoo is a staff member who cares for animals at that zoo.","zh":"倫敦動物園飼養員，是在該動物園照顧動物的員工。"},{"en":"A zoo keeper feeds animals, checks health, cleans enclosures, and observes behaviour.","zh":"動物園飼養員餵飼動物、檢查健康、清潔圍欄並觀察行為。"},{"en":"A keeper may know animal care deeply, but the article style may suggest a journalist instead.","zh":"飼養員可能深知動物照顧，但文章風格可能更像記者。"},{"en":"This phrase names one possible author identity in the question.","zh":"這個短語指出題目中的一個可能作者身份。"}],"source":"125 - Koalas.pdf","sourcePage":19},{"front":"tourist returning from Australia","meaning":"從澳洲回來的遊客","examples":[{"en":"The option suggests the writer may be a tourist returning from Australia.","zh":"該選項暗示作者可能是從澳洲回來的遊客。"},{"en":"A tourist returning from Australia is a traveller who has visited Australia and come back home.","zh":"從澳洲回來的遊客，是曾到澳洲旅行並回到家的人。"},{"en":"A tourist might describe personal experiences, photos, and impressions after a trip.","zh":"遊客旅行後可能描述個人經歷、照片和印象。"},{"en":"If an article uses research and policy details, it may be more than a tourist account.","zh":"如果文章使用研究和政策細節，它可能不只是遊客記述。"},{"en":"This phrase names another possible writer type in the question.","zh":"這個短語指出題目中的另一種可能作者類型。"}],"source":"125 - Koalas.pdf","sourcePage":19},{"front":"government official","meaning":"政府官員","examples":[{"en":"The option suggests the writer may be a government official.","zh":"該選項暗示作者可能是政府官員。"},{"en":"A government official is a person who works for the government and helps carry out public duties.","zh":"政府官員是在政府工作並協助執行公共職責的人。"},{"en":"A government official may write reports, inspect services, or prepare policy advice.","zh":"政府官員可能撰寫報告、檢查服務或準備政策建議。"},{"en":"Official writing is often formal and policy-focused, while magazine writing may be more descriptive.","zh":"官方寫作通常正式並聚焦政策，而雜誌寫作可能更具描述性。"},{"en":"This phrase names a possible professional role.","zh":"這個短語指出一種可能的專業角色。"}],"source":"125 - Koalas.pdf","sourcePage":19},{"front":"draft legislation","meaning":"草擬法例","examples":[{"en":"A government official may study koalas to draft legislation.","zh":"政府官員可能研究樹熊以草擬法例。"},{"en":"To draft legislation means to prepare the written form of a proposed law.","zh":"草擬法例，是指準備擬議法律的書面文本。"},{"en":"Officials may draft legislation to protect children from unsafe products.","zh":"官員可能草擬法例，以保護兒童免受不安全產品傷害。"},{"en":"Before laws are passed, draft legislation is often reviewed and changed.","zh":"法律通過前，草擬法例通常會被審閱和修改。"},{"en":"This phrase describes the early writing stage of making a law.","zh":"這個短語描述制定法律的早期寫作階段。"}],"source":"125 - Koalas.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 126":[{"front":"hunting perfume in Madagascar","meaning":"在馬達加斯加尋找香氣","examples":[{"en":"The expedition was hunting perfume in Madagascar.","zh":"考察隊正在馬達加斯加尋找香氣。"},{"en":"Hunting perfume means searching for natural smells that could be used to create new fragrances.","zh":"hunting perfume 指尋找可用來創造新香水的天然氣味。"},{"en":"A perfume company may send researchers into a forest to hunt perfume from flowers, bark, or resin.","zh":"香水公司可能派研究人員進入森林，從花、樹皮或樹脂中尋找香氣。"},{"en":"This search can lead to new scents that customers have never smelled before.","zh":"這種搜尋可能帶來顧客從未聞過的新氣味。"},{"en":"The phrase sounds adventurous because the team is “hunting” smells, not animals.","zh":"這個短語帶有冒險感，因為團隊「獵尋」的是氣味，而不是動物。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":1},{"front":"ever since","meaning":"自……以來","examples":[{"en":"Ever since ancient Rome, perfumers have had to follow changing fashions.","zh":"自古羅馬以來，香水師一直要跟上不斷變化的潮流。"},{"en":"Ever since means from a particular time in the past until now.","zh":"ever since 指從過去某個時間一直到現在。"},{"en":"Ever since primary school, she has loved collecting interesting words.","zh":"自小學以來，她一直喜歡收集有趣詞語。"},{"en":"If a habit continues ever since childhood, it may feel natural and hard to change.","zh":"如果一個習慣自童年以來一直持續，它可能感覺自然且難以改變。"},{"en":"This phrase shows a long connection between the past and the present.","zh":"這個短語顯示過去與現在之間的長期連繫。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":1},{"front":"unguentari","meaning":"古羅馬香膏商人","examples":[{"en":"The unguentari plied their trade in ancient Rome.","zh":"古羅馬香膏商人在古羅馬從事買賣。"},{"en":"Unguentari were ancient Roman sellers or makers of scented oils, ointments, and perfumes.","zh":"unguentari 指古羅馬售賣或製作香油、香膏和香水的人。"},{"en":"Wealthy Romans might buy scented oils from unguentari before a bath or public event.","zh":"富有的羅馬人可能在沐浴或公共活動前向香膏商人購買香油。"},{"en":"Their work shows that people have valued pleasant smells for thousands of years.","zh":"他們的工作顯示人類數千年來一直重視宜人氣味。"},{"en":"This word is historical and should be used mainly when discussing ancient Roman perfume trade.","zh":"這個詞屬歷史用語，主要適合討論古羅馬香水貿易時使用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":1},{"front":"ply their trade","meaning":"從事某行業；做買賣","examples":[{"en":"The unguentari plied their trade in ancient Rome.","zh":"古羅馬香膏商人在古羅馬從事買賣。"},{"en":"To ply their trade means to practise their job or business regularly.","zh":"ply their trade 指定期從事某種工作或生意。"},{"en":"Street vendors ply their trade near busy train stations every morning.","zh":"街頭小販每天早上在繁忙火車站附近做買賣。"},{"en":"People who ply a trade need skill, customers, and a place to work.","zh":"從事某行業的人需要技能、顧客和工作地點。"},{"en":"This phrase often sounds slightly old-fashioned or formal.","zh":"這個短語通常帶有一點舊式或正式語氣。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":1},{"front":"ancient Rome","meaning":"古羅馬","examples":[{"en":"Perfumers have existed since ancient Rome.","zh":"香水師自古羅馬以來已經存在。"},{"en":"Ancient Rome refers to the civilisation centred on Rome in the ancient world.","zh":"ancient Rome 指以羅馬為中心的古代文明。"},{"en":"Students study ancient Rome to learn about law, roads, armies, trade, and daily life.","zh":"學生研究古羅馬，以了解法律、道路、軍隊、貿易和日常生活。"},{"en":"Ancient Rome had markets where people bought goods such as oil, wine, cloth, and perfume.","zh":"古羅馬有市場，人們在那裡購買油、酒、布料和香水等貨品。"},{"en":"This phrase gives a historical setting, not a modern place name.","zh":"這個短語提供歷史背景，而不是現代地名。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":1},{"front":"perfumers","meaning":"香水師；調香師","examples":[{"en":"Perfumers create new scents from many ingredients.","zh":"香水師用許多成分創造新香氣。"},{"en":"Perfumers are people who design and mix smells for perfumes or scented products.","zh":"perfumers 指為香水或香味產品設計和混合氣味的人。"},{"en":"A perfumer may test hundreds of small samples before choosing one final scent.","zh":"調香師可能測試數百個小樣本，才選定最終香氣。"},{"en":"Perfumers need a strong sense of smell and knowledge of how ingredients work together.","zh":"香水師需要敏銳嗅覺，並了解成分如何互相配合。"},{"en":"This word can refer to creators of fine perfume or scents for everyday products.","zh":"這個詞可指高級香水的創作者，也可指日常用品香氣的設計者。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":1},{"front":"keep abreast of","meaning":"緊貼；跟上","examples":[{"en":"Perfumers have to keep abreast of changing fashions.","zh":"香水師必須緊貼不斷變化的潮流。"},{"en":"To keep abreast of something means to stay informed about the latest changes.","zh":"keep abreast of something 指持續掌握某事的最新變化。"},{"en":"Teachers keep abreast of new exam formats so they can prepare students properly.","zh":"老師緊貼新的考試格式，才能妥善準備學生。"},{"en":"If a company fails to keep abreast of customer tastes, its products may feel outdated.","zh":"如果公司未能跟上顧客口味，其產品可能顯得過時。"},{"en":"This phrase is useful when trends or knowledge change quickly.","zh":"當潮流或知識快速變化時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":1},{"front":"changing fashions","meaning":"不斷變化的潮流","examples":[{"en":"Perfumers must keep abreast of changing fashions.","zh":"香水師必須緊貼不斷變化的潮流。"},{"en":"Changing fashions are tastes or styles that shift over time.","zh":"changing fashions 指隨時間轉變的品味或風格。"},{"en":"A clothing shop must follow changing fashions if young customers want new styles.","zh":"如果年輕顧客想要新款式，服裝店就必須跟上不斷變化的潮流。"},{"en":"Changing fashions can make a product popular one year and old-fashioned the next.","zh":"不斷變化的潮流可以令產品今年受歡迎，明年卻顯得過時。"},{"en":"This phrase is useful for trends in clothes, music, design, food, or perfume.","zh":"這個短語適用於衣服、音樂、設計、食物或香水潮流。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":1},{"front":"ingredients to choose from","meaning":"可供選擇的成分","examples":[{"en":"Perfumers have several thousand ingredients to choose from.","zh":"香水師有數千種可供選擇的成分。"},{"en":"Ingredients to choose from are the available materials someone can select when making something.","zh":"ingredients to choose from 指製作某物時可以選用的材料。"},{"en":"A cook with many ingredients to choose from can create more varied meals.","zh":"廚師如果有許多可供選擇的食材，就能做出更多元的菜式。"},{"en":"More choices can help creativity, but they can also make decisions harder.","zh":"更多選擇可以幫助創意，但也可能令決定更困難。"},{"en":"This phrase is useful when discussing food, design, perfume, or any creative process.","zh":"這個短語適用於食物、設計、香水或任何創作過程。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":1},{"front":"create new scents","meaning":"創造新香氣","examples":[{"en":"Perfumers use many ingredients to create new scents.","zh":"香水師使用許多成分來創造新香氣。"},{"en":"To create new scents means to make new smells by mixing or discovering ingredients.","zh":"create new scents 指透過混合或發現成分來製作新氣味。"},{"en":"A candle maker may create new scents by blending vanilla, wood, and citrus notes.","zh":"蠟燭製造者可能透過混合雲呢拿、木香和柑橘調來創造新香氣。"},{"en":"Creating new scents can help a brand stand out in a crowded market.","zh":"創造新香氣可以幫助品牌在競爭激烈的市場中突出。"},{"en":"This phrase focuses on producing smells that feel fresh or distinctive.","zh":"這個短語聚焦製造新鮮或獨特的氣味。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":1},{"front":"demand for","meaning":"對……的需求","examples":[{"en":"There is always demand for new combinations of smells.","zh":"人們一直對新氣味組合有需求。"},{"en":"Demand for something is the need or desire people have for it.","zh":"demand for something 指人們對某物的需要或渴望。"},{"en":"There is high demand for air conditioners during a very hot summer.","zh":"在非常炎熱的夏天，人們對冷氣機的需求很高。"},{"en":"When demand rises, companies may produce more goods or raise prices.","zh":"當需求上升，公司可能生產更多商品或提高價格。"},{"en":"This phrase is common in business, shopping, and market discussions.","zh":"這個短語常見於商業、購物和市場討論。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":1},{"front":"new combinations","meaning":"新組合","examples":[{"en":"The perfume industry is always looking for new combinations.","zh":"香水業一直在尋找新組合。"},{"en":"New combinations are fresh mixtures of different things.","zh":"new combinations 指不同事物的新鮮混合。"},{"en":"A café may try new combinations of fruit and tea to attract young customers.","zh":"咖啡店可能嘗試水果和茶的新組合，以吸引年輕顧客。"},{"en":"New combinations can create surprise because familiar ingredients produce a different result together.","zh":"新組合可以帶來驚喜，因為熟悉成分放在一起會產生不同結果。"},{"en":"This phrase is useful for perfume, food, music, fashion, and design.","zh":"這個短語適用於香水、食物、音樂、時裝和設計。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":2},{"front":"palette of smells","meaning":"氣味調色板；氣味選擇範圍","examples":[{"en":"The bigger the palette of smells, the better the perfumer’s chance of success.","zh":"氣味選擇範圍越大，香水師成功的機會就越高。"},{"en":"A palette of smells is the range of odours a perfumer can use creatively.","zh":"palette of smells 指調香師可創意使用的氣味範圍。"},{"en":"A painter uses colours, while a perfumer uses a palette of smells.","zh":"畫家使用顏色，而香水師使用氣味調色板。"},{"en":"A larger smell palette gives more freedom to create unusual or memorable fragrances.","zh":"較大的氣味選擇範圍給人更多自由去創造不尋常或難忘的香氣。"},{"en":"This phrase compares smell creation to visual art.","zh":"這個短語把氣味創作比作視覺藝術。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":2},{"front":"the bigger…, the better…","meaning":"越……就越……","examples":[{"en":"The bigger the palette of smells, the better the chance of creating something fresh.","zh":"氣味調色板越大，創造新鮮氣味的機會就越高。"},{"en":"The bigger…, the better… means that when one thing increases, another thing improves.","zh":"the bigger…, the better… 表示一件事增加時，另一件事會改善。"},{"en":"The more examples students read, the better their writing usually becomes.","zh":"學生閱讀的例子越多，寫作通常越好。"},{"en":"If the practice is useful, more practice often leads to better skill.","zh":"如果練習有用，練習越多，技能通常越好。"},{"en":"This structure is useful for showing a clear relationship between two changes.","zh":"這個結構適合顯示兩種變化之間的清楚關係。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":2},{"front":"chance of creating","meaning":"創造……的機會","examples":[{"en":"A larger palette gives perfumers a better chance of creating something appealing.","zh":"較大的氣味選擇範圍給香水師更大機會創造吸引人的東西。"},{"en":"A chance of creating something means the possibility of producing it successfully.","zh":"chance of creating something 指成功製造某物的可能性。"},{"en":"A student has a better chance of creating a strong essay if she plans before writing.","zh":"如果學生寫作前先計劃，她創造一篇好文章的機會會更高。"},{"en":"More resources can increase the chance of creating a useful product.","zh":"更多資源可以增加創造有用產品的機會。"},{"en":"This phrase links preparation or opportunity with creative success.","zh":"這個短語把準備或機會與創作成功連接起來。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":2},{"front":"fresh and appealing","meaning":"新鮮而吸引","examples":[{"en":"Perfumers want to create something fresh and appealing.","zh":"香水師想創造新鮮而吸引人的東西。"},{"en":"Fresh and appealing means new, pleasant, and attractive to people.","zh":"fresh and appealing 指新穎、令人愉快且有吸引力。"},{"en":"A shop window should look fresh and appealing if it wants customers to enter.","zh":"商店櫥窗若想吸引顧客進入，就應看起來新鮮而吸引。"},{"en":"Products feel fresh and appealing when they offer something familiar in a new way.","zh":"當產品以新方式呈現熟悉事物時，會顯得新鮮而吸引。"},{"en":"This phrase is useful for smells, designs, food, writing, and advertisements.","zh":"這個短語適用於氣味、設計、食物、寫作和廣告。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":2},{"front":"everyday products","meaning":"日常用品","examples":[{"en":"Fragrances are used in everyday products such as shampoo and soap.","zh":"香氣被用於洗頭水和肥皂等日常用品中。"},{"en":"Everyday products are ordinary items people use regularly in daily life.","zh":"everyday products 指人們日常生活中經常使用的普通物品。"},{"en":"Toothpaste, soap, detergent, and tissues are everyday products found in many homes.","zh":"牙膏、肥皂、洗衣液和紙巾都是許多家庭中的日常用品。"},{"en":"Because people use them often, small changes in their smell or design can affect customers’ choices.","zh":"因為人們經常使用它們，其氣味或設計的小改變也會影響顧客選擇。"},{"en":"This phrase refers to common products, not luxury goods only.","zh":"這個短語指常見用品，而不只是奢侈品。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":2},{"front":"kitchen cleaners","meaning":"廚房清潔劑","examples":[{"en":"Kitchen cleaners often contain artificial fragrances.","zh":"廚房清潔劑常含有人造香氣。"},{"en":"Kitchen cleaners are products used to clean kitchen surfaces, sinks, ovens, or floors.","zh":"kitchen cleaners 指用來清潔廚房表面、水槽、焗爐或地板的產品。"},{"en":"A family may use kitchen cleaners after cooking oily food.","zh":"家庭在煮完油膩食物後可能使用廚房清潔劑。"},{"en":"Strong cleaners may need fragrances to cover chemical smells.","zh":"強效清潔劑可能需要香氣來掩蓋化學氣味。"},{"en":"This phrase refers to cleaning products designed for kitchen use.","zh":"這個短語指專為廚房使用而設的清潔產品。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":2},{"front":"washing powders","meaning":"洗衣粉","examples":[{"en":"Washing powders need fragrances that can survive tough treatment.","zh":"洗衣粉需要能經受嚴苛處理的香氣。"},{"en":"Washing powders are powdered detergents used for washing clothes.","zh":"washing powders 指用於洗衣的粉狀清潔劑。"},{"en":"A household may choose washing powders that leave clothes smelling clean.","zh":"家庭可能選擇能令衣服聞起來乾淨的洗衣粉。"},{"en":"The fragrance must survive water, heat, and other chemicals during washing.","zh":"香氣必須在洗衣期間經受水、熱力和其他化學物。"},{"en":"This phrase is common in discussions of laundry products.","zh":"這個短語常見於洗衣產品討論。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":2},{"front":"become increasingly fussy","meaning":"變得越來越挑剔","examples":[{"en":"Consumers are becoming increasingly fussy about fragrances.","zh":"消費者對香氣變得越來越挑剔。"},{"en":"To become increasingly fussy means to become more demanding and harder to satisfy.","zh":"become increasingly fussy 指變得要求更高、更難滿足。"},{"en":"Customers may become increasingly fussy if they have many brands to choose from.","zh":"如果顧客有許多品牌可選，他們可能變得越來越挑剔。"},{"en":"Fussy consumers force companies to improve quality, smell, packaging, and price.","zh":"挑剔的消費者迫使公司改善質素、氣味、包裝和價格。"},{"en":"This phrase often describes rising expectations.","zh":"這個短語常描述期望上升。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":2},{"front":"fragrances","meaning":"香氣；香味","examples":[{"en":"Many fragrances have to survive tougher treatment than before.","zh":"許多香氣必須經受比以前更嚴苛的處理。"},{"en":"Fragrances are pleasant smells used in perfumes, soaps, cleaners, or other products.","zh":"fragrances 指用於香水、肥皂、清潔劑或其他產品中的宜人氣味。"},{"en":"A shampoo fragrance may make hair smell fresh after washing.","zh":"洗頭水香氣可以令頭髮洗後聞起來清新。"},{"en":"Fragrances can influence buying decisions because smell creates memory and mood.","zh":"香氣可以影響購買決定，因為氣味會創造記憶和情緒。"},{"en":"This word is broader than perfume because it can refer to many scented products.","zh":"這個詞比 perfume 更廣，因為它可指多種帶香味產品。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":2},{"front":"survive tougher treatment","meaning":"經受更嚴苛的處理","examples":[{"en":"Today’s fragrances have to survive tougher treatment than ever before.","zh":"今天的香氣必須經受比以往任何時候都更嚴苛的處理。"},{"en":"To survive tougher treatment means to continue working or remaining noticeable under harsher conditions.","zh":"survive tougher treatment 指在更惡劣條件下仍能持續發揮作用或保持明顯。"},{"en":"A laundry fragrance must survive hot water, detergent, and long washing cycles.","zh":"洗衣香氣必須經受熱水、洗衣劑和長時間洗衣程序。"},{"en":"If a scent cannot survive tough treatment, customers may not smell it after use.","zh":"如果氣味不能經受嚴苛處理，顧客使用後可能聞不到它。"},{"en":"This phrase is useful when a product must remain effective under pressure.","zh":"當產品必須在壓力下保持有效時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":2},{"front":"than ever before","meaning":"比以往任何時候都……","examples":[{"en":"Fragrances now face tougher treatment than ever before.","zh":"香氣現在面對比以往任何時候都更嚴苛的處理。"},{"en":"Than ever before means more than at any earlier time.","zh":"than ever before 指比過去任何時候都更多或更強。"},{"en":"Students today use online resources more than ever before.","zh":"今天學生使用網上資源比以往任何時候都多。"},{"en":"When competition is stronger than ever before, companies must improve quickly.","zh":"當競爭比以往任何時候都強，公司必須迅速改善。"},{"en":"This phrase emphasises that the present level is historically high.","zh":"這個短語強調目前水平在歷史上很高。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":3},{"front":"resist the destructive power of","meaning":"抵抗……的破壞力","examples":[{"en":"Some fragrances must resist the destructive power of bleach.","zh":"有些香氣必須抵抗漂白劑的破壞力。"},{"en":"To resist the destructive power of something means to avoid being damaged or destroyed by it.","zh":"resist the destructive power of something 指避免被某物損害或破壞。"},{"en":"Outdoor paint must resist the destructive power of sunlight and rain.","zh":"戶外油漆必須抵抗陽光和雨水的破壞力。"},{"en":"If a fragrance cannot resist bleach, it may disappear during cleaning.","zh":"如果香氣不能抵抗漂白劑，它可能在清潔過程中消失。"},{"en":"This phrase is useful when something must stay strong against a harmful force.","zh":"當某物必須抵禦有害力量時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":3},{"front":"bleach","meaning":"漂白劑","examples":[{"en":"Bleach can destroy many delicate fragrances.","zh":"漂白劑可以破壞許多細緻香氣。"},{"en":"Bleach is a strong chemical used to whiten, disinfect, or remove stains.","zh":"bleach 指用來漂白、消毒或去除污漬的強效化學物。"},{"en":"A cleaner may use bleach to disinfect a bathroom floor.","zh":"清潔工可能使用漂白劑為浴室地板消毒。"},{"en":"Bleach is powerful, so it can damage colours, fabrics, and smells if used carelessly.","zh":"漂白劑效力強，因此若使用不慎，可能損害顏色、布料和氣味。"},{"en":"This word is common in cleaning and laundry contexts.","zh":"這個詞常見於清潔和洗衣語境。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":3},{"front":"high-temperature wash cycle","meaning":"高溫洗衣程序","examples":[{"en":"A fragrance may need to survive a high-temperature wash cycle.","zh":"香氣可能需要經受高溫洗衣程序。"},{"en":"A high-temperature wash cycle is a washing-machine programme that uses hot water.","zh":"high-temperature wash cycle 指使用熱水的洗衣機程序。"},{"en":"Families may use a high-temperature wash cycle for towels or heavily soiled clothes.","zh":"家庭可能用高溫洗衣程序洗毛巾或很髒的衣服。"},{"en":"Heat can remove dirt, but it can also weaken delicate fragrance molecules.","zh":"高溫可以去除污垢，但也可能削弱細緻香氣分子。"},{"en":"This phrase is useful when discussing laundry performance.","zh":"討論洗衣表現時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":3},{"front":"chemists","meaning":"化學家","examples":[{"en":"Chemists can create new smells from synthetic molecules.","zh":"化學家可以用合成分子創造新氣味。"},{"en":"Chemists are scientists who study substances and how they react or combine.","zh":"chemists 指研究物質以及它們如何反應或結合的科學家。"},{"en":"A chemist may design a safer cleaner for household use.","zh":"化學家可能設計較安全的家用清潔劑。"},{"en":"Chemists help industries create materials, medicines, flavours, and fragrances.","zh":"化學家幫助各行業創造材料、藥物、味道和香氣。"},{"en":"This word refers to trained science specialists, not shop workers in every context.","zh":"這個詞指受訓科學專家，不是在每個語境中都指藥房職員。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":3},{"front":"synthetic molecules","meaning":"合成分子","examples":[{"en":"Chemists can create new smells from synthetic molecules.","zh":"化學家可以用合成分子創造新氣味。"},{"en":"Synthetic molecules are human-made chemical structures rather than molecules taken directly from nature.","zh":"synthetic molecules 指人造化學結構，而不是直接取自大自然的分子。"},{"en":"A perfume may use synthetic molecules to copy the smell of a rare flower.","zh":"香水可能使用合成分子來模仿罕見花朵的氣味。"},{"en":"Synthetic molecules can be useful when natural ingredients are expensive or difficult to collect.","zh":"當天然成分昂貴或難以收集時，合成分子很有用。"},{"en":"This phrase is common in chemistry, perfume, medicine, and materials science.","zh":"這個短語常見於化學、香水、醫藥和材料科學。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":3},{"front":"a growing number of","meaning":"越來越多的……","examples":[{"en":"A growing number of odours on the perfumer’s palette are artificial.","zh":"調香師氣味調色板上越來越多的氣味是人造的。"},{"en":"A growing number of means more and more over time.","zh":"a growing number of 指隨時間越來越多。"},{"en":"A growing number of students use online dictionaries when reading English.","zh":"越來越多學生閱讀英文時使用網上字典。"},{"en":"When a growing number of customers ask for eco-friendly products, companies may change their materials.","zh":"當越來越多顧客要求環保產品，公司可能改變材料。"},{"en":"This phrase shows a trend that is increasing.","zh":"這個短語顯示正在增加的趨勢。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":3},{"front":"odours","meaning":"氣味","examples":[{"en":"Many odours used by perfumers are now artificial.","zh":"許多香水師使用的氣味現在是人造的。"},{"en":"Odours are smells, which may be pleasant, unpleasant, strong, or weak.","zh":"odours 指氣味，可以是宜人、不宜人、強烈或微弱。"},{"en":"A kitchen may have odours from spices, rubbish, or cleaning products.","zh":"廚房可能有來自香料、垃圾或清潔產品的氣味。"},{"en":"Strong odours can affect mood, memory, and how clean a place feels.","zh":"強烈氣味可以影響心情、記憶和一個地方是否感覺乾淨。"},{"en":"This word is more general and slightly more scientific than smells.","zh":"這個詞比 smells 更一般，也稍微更科學。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":3},{"front":"artificial","meaning":"人造的","examples":[{"en":"Many modern fragrance molecules are artificial.","zh":"許多現代香氣分子是人造的。"},{"en":"Artificial means made by humans rather than occurring naturally.","zh":"artificial 指由人類製造，而不是自然出現。"},{"en":"Some drinks contain artificial colours to make them look brighter.","zh":"有些飲品含有人造色素，使它們看起來更鮮艷。"},{"en":"Artificial ingredients can be cheaper or more stable, but some customers prefer natural ones.","zh":"人造成分可以較便宜或較穩定，但有些顧客較喜歡天然成分。"},{"en":"This word contrasts human-made products with natural materials.","zh":"這個詞把人造產品與天然材料作對比。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":3},{"front":"be in the business","meaning":"從事這門行業；早已做這件事","examples":[{"en":"Nature has been in the business of creating smells far longer.","zh":"大自然早已更長久地從事創造氣味這件事。"},{"en":"To be in the business of doing something means to be involved in that activity seriously or regularly.","zh":"be in the business of doing something 指認真或定期參與某活動。"},{"en":"Schools are in the business of helping students learn, not just giving tests.","zh":"學校是從事幫助學生學習的機構，而不只是給測驗。"},{"en":"A company in the business of solving customer problems must listen carefully to complaints.","zh":"從事解決顧客問題的公司必須仔細聆聽投訴。"},{"en":"This phrase can be literal for companies or figurative for nature and institutions.","zh":"這個短語可字面用於公司，也可比喻用於大自然和機構。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":3},{"front":"far longer","meaning":"久得多","examples":[{"en":"Nature has been creating smells far longer than chemists have.","zh":"大自然創造氣味的時間比化學家久得多。"},{"en":"Far longer means for a much greater length of time.","zh":"far longer 指長得多的時間。"},{"en":"Libraries have preserved knowledge far longer than the internet has existed.","zh":"圖書館保存知識的時間比互聯網存在的時間久得多。"},{"en":"If a method has lasted far longer, there may be practical reasons for its survival.","zh":"如果一種方法持續得久得多，它能存在可能有實際原因。"},{"en":"This phrase strongly emphasises a difference in time.","zh":"這個短語強烈強調時間上的差異。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":3},{"front":"evolutionary hot spot","meaning":"演化熱點","examples":[{"en":"Madagascar is an evolutionary hot spot.","zh":"馬達加斯加是一個演化熱點。"},{"en":"An evolutionary hot spot is a place where many unusual species have developed over time.","zh":"evolutionary hot spot 指許多不尋常物種隨時間發展出來的地方。"},{"en":"An island can become an evolutionary hot spot when plants and animals evolve separately from the mainland.","zh":"當動植物與大陸分隔並獨立演化，島嶼可以成為演化熱點。"},{"en":"Such places interest scientists because they may contain rare species and unusual chemicals.","zh":"這些地方吸引科學家，因為它們可能含有罕見物種和不尋常化學物。"},{"en":"This phrase is useful in biology and biodiversity discussions.","zh":"這個短語適用於生物學和生物多樣性討論。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":4},{"front":"be unique","meaning":"獨有的","examples":[{"en":"Many plants in Madagascar are unique.","zh":"馬達加斯加的許多植物是獨有的。"},{"en":"To be unique means to be the only one of its kind or very different from others.","zh":"be unique 指同類中唯一，或與其他事物非常不同。"},{"en":"A family recipe may be unique because only one grandmother knows the exact method.","zh":"家庭食譜可能很獨特，因為只有一位祖母知道確切做法。"},{"en":"Unique plants can be valuable because they may contain chemicals found nowhere else.","zh":"獨有植物可能很有價值，因為它們可能含有其他地方沒有的化學物。"},{"en":"This word should be used when something is truly special or rare.","zh":"當某物真正特別或罕見時，才適合使用這個詞。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":4},{"front":"ideal source for","meaning":"……的理想來源","examples":[{"en":"Madagascar is an ideal source for novel fragrances.","zh":"馬達加斯加是新奇香氣的理想來源。"},{"en":"An ideal source for something is a very suitable place or thing to get it from.","zh":"ideal source for something 指取得某物的非常合適地方或事物。"},{"en":"A local market can be an ideal source for fresh vegetables.","zh":"本地市場可以是新鮮蔬菜的理想來源。"},{"en":"A source is ideal when it offers quality, variety, or rare materials.","zh":"當來源提供質素、多樣性或稀有材料時，它就是理想來源。"},{"en":"This phrase explains why people choose one place or material over others.","zh":"這個短語解釋人們為何選擇某地或某材料。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":4},{"front":"novel fragrances","meaning":"新奇香氣","examples":[{"en":"Madagascar is an ideal source for novel fragrances.","zh":"馬達加斯加是新奇香氣的理想來源。"},{"en":"Novel fragrances are new or unusual smells that are different from familiar scents.","zh":"novel fragrances 指不同於熟悉氣味的新或不尋常香氣。"},{"en":"A perfume brand may look for novel fragrances to create a product customers remember.","zh":"香水品牌可能尋找新奇香氣，以創造令顧客記得的產品。"},{"en":"Novel fragrances can make a perfume feel fresh in a crowded market.","zh":"新奇香氣可以令香水在競爭激烈的市場中感覺新鮮。"},{"en":"This phrase is used when the smell is original, rare, or surprising.","zh":"當氣味原創、罕見或令人驚訝時，會使用這個短語。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":4},{"front":"delicate perfumes","meaning":"精緻香水","examples":[{"en":"The company develops fragrances for delicate perfumes and cleaning products.","zh":"這家公司為精緻香水和清潔產品研發香氣。"},{"en":"Delicate perfumes are fine, subtle perfumes with gentle or complex smells.","zh":"delicate perfumes 指氣味細緻、柔和或複雜的高雅香水。"},{"en":"A delicate perfume may smell soft rather than strong or heavy.","zh":"精緻香水可能聞起來柔和，而不是強烈或沉重。"},{"en":"Delicate perfumes need careful mixing because one strong ingredient can overpower the whole scent.","zh":"精緻香水需要仔細調配，因為一種強烈成分可能壓過整體香氣。"},{"en":"This phrase contrasts refined perfume with rough or harsh smells.","zh":"這個短語把精緻香水與粗糙或刺鼻氣味作對比。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":4},{"front":"develop fragrances for","meaning":"為……研發香氣","examples":[{"en":"Quest International develops fragrances for many different products.","zh":"Quest International 為許多不同產品研發香氣。"},{"en":"To develop fragrances for products means to design scents that suit those products.","zh":"develop fragrances for products 指設計適合那些產品的氣味。"},{"en":"A company may develop fragrances for shampoo, soap, candles, and laundry products.","zh":"公司可能為洗頭水、肥皂、蠟燭和洗衣產品研發香氣。"},{"en":"The scent must fit the product’s purpose, price, and customers.","zh":"氣味必須配合產品用途、價格和顧客。"},{"en":"This phrase is common in product design and fragrance industry contexts.","zh":"這個短語常見於產品設計和香水業語境。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":4},{"front":"cleaning products","meaning":"清潔產品","examples":[{"en":"Fragrances are used in cleaning products as well as perfumes.","zh":"香氣既用於香水，也用於清潔產品。"},{"en":"Cleaning products are substances used to remove dirt, stains, germs, or bad smells.","zh":"cleaning products 指用來去除污垢、污漬、細菌或臭味的物質。"},{"en":"Households use cleaning products for floors, bathrooms, kitchens, and laundry.","zh":"家庭使用清潔產品清潔地板、浴室、廚房和衣物。"},{"en":"Pleasant fragrances can make cleaning products feel fresher and more effective.","zh":"宜人香氣可以令清潔產品感覺更清新和更有效。"},{"en":"This phrase covers many items, from sprays to detergents.","zh":"這個短語涵蓋許多物品，從噴霧到洗衣劑都包括在內。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":4},{"front":"send an expedition to","meaning":"派出考察隊到……","examples":[{"en":"The company sent an expedition to Madagascar.","zh":"這家公司派出考察隊到馬達加斯加。"},{"en":"To send an expedition to a place means to organise a team to travel there for research or exploration.","zh":"send an expedition to a place 指組織團隊前往某地進行研究或探索。"},{"en":"A university may send an expedition to a remote island to study rare plants.","zh":"大學可能派出考察隊到偏遠島嶼研究罕見植物。"},{"en":"Expeditions require planning, equipment, safety checks, and local knowledge.","zh":"考察需要計劃、設備、安全檢查和本地知識。"},{"en":"This phrase suggests purposeful travel, not ordinary tourism.","zh":"這個短語表示有目的的旅行，而不是普通旅遊。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":4},{"front":"in pursuit of","meaning":"為了尋找……","examples":[{"en":"The expedition went to Madagascar in pursuit of novel fragrances.","zh":"考察隊前往馬達加斯加，為了尋找新奇香氣。"},{"en":"In pursuit of something means trying to find, achieve, or obtain it.","zh":"in pursuit of something 指努力尋找、達成或取得某物。"},{"en":"A student may move abroad in pursuit of better education.","zh":"學生可能為了尋找更好教育而移居海外。"},{"en":"People may take risks in pursuit of success, discovery, or safety.","zh":"人們可能為了追求成功、發現或安全而冒險。"},{"en":"This phrase is more formal than looking for.","zh":"這個短語比 looking for 更正式。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":4},{"front":"nature’s most novel fragrances","meaning":"大自然中最新奇的香氣","examples":[{"en":"The team searched for some of nature’s most novel fragrances.","zh":"團隊尋找大自然中一些最新奇的香氣。"},{"en":"Nature’s most novel fragrances are unusual smells produced naturally by plants, resins, flowers, or other living things.","zh":"nature’s most novel fragrances 指植物、樹脂、花朵或其他生物自然產生的不尋常氣味。"},{"en":"A rainforest may contain nature’s most novel fragrances because many species grow close together.","zh":"雨林可能含有大自然中最新奇的香氣，因為許多物種密集生長。"},{"en":"These smells interest perfumers because they can inspire new products.","zh":"這些氣味吸引香水師，因為它們可以啟發新產品。"},{"en":"This phrase suggests rare and surprising scents from the natural world.","zh":"這個短語暗示來自自然界的罕見而令人驚訝的氣味。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":4},{"front":"borrowed from","meaning":"借用自……","examples":[{"en":"The team used technology borrowed from the pollution monitoring industry.","zh":"團隊使用借用自污染監測行業的技術。"},{"en":"Borrowed from means taken or adapted from another field, person, or source.","zh":"borrowed from 指取自或改編自另一個領域、人物或來源。"},{"en":"A teacher may use a game idea borrowed from drama class to teach vocabulary.","zh":"老師可能使用借用自戲劇課的遊戲點子來教詞彙。"},{"en":"Borrowing a method can save time because the tool has already been tested elsewhere.","zh":"借用方法可以節省時間，因為工具已在其他地方測試過。"},{"en":"This phrase is useful when an idea moves from one area to another.","zh":"當想法從一個領域轉到另一個領域時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":4},{"front":"pollution monitoring industry","meaning":"污染監測行業","examples":[{"en":"The technique was borrowed from the pollution monitoring industry.","zh":"這項技術借用自污染監測行業。"},{"en":"The pollution monitoring industry uses tools to detect and measure harmful substances in air, water, or soil.","zh":"pollution monitoring industry 使用工具偵測和測量空氣、水或土壤中的有害物質。"},{"en":"A city may use pollution monitoring equipment to check air quality near roads.","zh":"城市可能使用污染監測設備檢查道路附近的空氣質素。"},{"en":"Techniques from this industry can also help capture tiny molecules in fragrance research.","zh":"這個行業的技術也可以幫助香氣研究捕捉微小分子。"},{"en":"This phrase refers to environmental testing and measurement work.","zh":"這個短語指環境測試和測量工作。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":5},{"front":"a fair amount of ingenuity","meaning":"相當多的巧思","examples":[{"en":"The perfume hunters used a fair amount of ingenuity.","zh":"香氣獵人使用了相當多的巧思。"},{"en":"A fair amount of ingenuity means quite a lot of cleverness and practical creativity.","zh":"a fair amount of ingenuity 指相當多的聰明才智和實用創意。"},{"en":"A teacher may need a fair amount of ingenuity to explain grammar to tired students.","zh":"老師向疲倦學生解釋文法時，可能需要相當多的巧思。"},{"en":"Ingenuity helps people solve problems when ordinary tools are not enough.","zh":"當普通工具不足夠時，巧思可以幫助人解決問題。"},{"en":"This phrase praises clever problem-solving without sounding exaggerated.","zh":"這個短語讚揚聰明解難，但語氣不算誇張。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":5},{"front":"perfume hunters","meaning":"香氣獵人","examples":[{"en":"The perfume hunters collected promising new aromas in the rainforest.","zh":"香氣獵人在雨林中收集有潛力的新香氣。"},{"en":"Perfume hunters are people who search for new natural smells that can inspire fragrances.","zh":"perfume hunters 指尋找可啟發香水的新天然氣味的人。"},{"en":"Perfume hunters may smell flowers, leaves, bark, resin, and wet soil during fieldwork.","zh":"香氣獵人在野外工作時可能嗅聞花、葉、樹皮、樹脂和濕泥土。"},{"en":"Their discoveries can give perfumers new materials or ideas.","zh":"他們的發現可以給調香師新的材料或靈感。"},{"en":"This phrase makes scientific fieldwork sound like an adventure.","zh":"這個短語令科學野外工作聽起來像冒險。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":5},{"front":"bag promising new aromas","meaning":"成功取得有潛力的新香氣","examples":[{"en":"The perfume hunters bagged 20 promising new aromas.","zh":"香氣獵人成功取得20種有潛力的新香氣。"},{"en":"To bag promising new aromas means to successfully collect new smells that seem useful or valuable.","zh":"bag promising new aromas 指成功收集看似有用或有價值的新氣味。"},{"en":"A research team may bag a promising aroma after tracking a smell to a rare flower.","zh":"研究團隊追蹤氣味到一朵罕見花後，可能成功取得一種有潛力的香氣。"},{"en":"If the aroma proves stable and attractive, it may later be used in a product.","zh":"如果該香氣證明穩定而吸引，日後可能用於產品中。"},{"en":"The verb bag is informal and gives the sentence a hunting-like feeling.","zh":"bag 這個動詞較非正式，令句子有像狩獵般的感覺。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":5},{"front":"promising new aromas","meaning":"有潛力的新香氣","examples":[{"en":"The team found 20 promising new aromas in the rainforest.","zh":"團隊在雨林中發現20種有潛力的新香氣。"},{"en":"Promising new aromas are new smells that seem likely to be useful, attractive, or successful.","zh":"promising new aromas 指看起來可能有用、吸引或成功的新氣味。"},{"en":"A soap company may test promising new aromas before choosing one for a new product.","zh":"肥皂公司可能先測試有潛力的新香氣，再為新產品選定一種。"},{"en":"A smell is promising if customers like it and it remains stable during production.","zh":"如果顧客喜歡某氣味，而且它在生產期間保持穩定，它就是有潛力的。"},{"en":"This phrase suggests early potential, not guaranteed success.","zh":"這個短語表示早期潛力，而不是保證成功。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":5},{"front":"Madagascan rainforest","meaning":"馬達加斯加雨林","examples":[{"en":"The perfume hunters worked in the Madagascan rainforest.","zh":"香氣獵人在馬達加斯加雨林中工作。"},{"en":"The Madagascan rainforest is rainforest found in Madagascar, rich in plants and wildlife.","zh":"Madagascan rainforest 指位於馬達加斯加、植物和野生生物豐富的雨林。"},{"en":"Researchers may explore a Madagascan rainforest to find rare leaves, flowers, or resins.","zh":"研究人員可能探索馬達加斯加雨林，以尋找罕見葉子、花朵或樹脂。"},{"en":"Rainforests can contain many scents because they have dense and varied plant life.","zh":"雨林可能含有許多氣味，因為那裡有茂密而多樣的植物生命。"},{"en":"This phrase gives the expedition a specific natural setting.","zh":"這個短語為考察提供具體自然背景。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":5},{"front":"set out from","meaning":"從……出發","examples":[{"en":"Each day the team set out from their wooden hut.","zh":"團隊每天從木屋出發。"},{"en":"To set out from a place means to begin a journey from that place.","zh":"set out from a place 指從某地開始旅程。"},{"en":"Hikers set out from the village early to avoid the afternoon heat.","zh":"遠足者清早從村莊出發，以避開下午炎熱天氣。"},{"en":"Starting from a fixed base helps a team return safely after fieldwork.","zh":"從固定基地出發有助團隊在野外工作後安全返回。"},{"en":"This phrase focuses on the starting point of a journey.","zh":"這個短語聚焦旅程的起點。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":5},{"front":"wooden hut","meaning":"木屋","examples":[{"en":"The team stayed in a wooden hut lit by kerosene lamps.","zh":"團隊住在一間由火水燈照明的木屋中。"},{"en":"A wooden hut is a small simple shelter made mainly of wood.","zh":"wooden hut 指主要由木材建成的小型簡單住所。"},{"en":"Field researchers may sleep in a wooden hut when working far from towns.","zh":"野外研究人員在遠離城鎮工作時，可能住在木屋中。"},{"en":"Such huts offer basic protection but may lack electricity, running water, or comfort.","zh":"這類木屋提供基本保護，但可能沒有電、自來水或舒適設施。"},{"en":"This phrase suggests simple living conditions during an expedition.","zh":"這個短語暗示考察期間的簡樸生活條件。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":5},{"front":"lit by kerosene lamps","meaning":"由火水燈照明","examples":[{"en":"Their wooden hut was lit by kerosene lamps.","zh":"他們的木屋由火水燈照明。"},{"en":"Lit by kerosene lamps means illuminated using lamps that burn kerosene fuel.","zh":"lit by kerosene lamps 指用燃燒火水的燈來照明。"},{"en":"A remote village house may be lit by kerosene lamps when there is no electricity.","zh":"偏遠村屋在沒有電力時，可能由火水燈照明。"},{"en":"Kerosene lighting can help people work at night but may produce smoke and smell.","zh":"火水燈可以幫助人在夜間工作，但可能產生煙和氣味。"},{"en":"This phrase suggests a basic or remote setting.","zh":"這個短語暗示環境簡陋或偏遠。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":5},{"front":"trail up and down","meaning":"沿着……上下走動","examples":[{"en":"The team trailed up and down paths in the rainforest.","zh":"團隊在雨林小徑上來回上下走動。"},{"en":"To trail up and down means to walk repeatedly along paths, often slowly while searching.","zh":"trail up and down 指反覆沿着路徑行走，常是慢慢搜尋。"},{"en":"Volunteers trailed up and down the beach looking for lost rubbish after a festival.","zh":"節日後，義工在海灘上來回走動尋找遺下的垃圾。"},{"en":"Repeated walking helps searchers cover an area carefully.","zh":"反覆行走幫助搜尋者仔細覆蓋一個區域。"},{"en":"This phrase suggests patient movement rather than quick travel.","zh":"這個短語表示耐心移動，而不是快速旅行。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":5},{"front":"animal tracks","meaning":"動物蹤跡；獸徑","examples":[{"en":"The hunters followed paths and animal tracks.","zh":"獵人沿着小徑和動物蹤跡前行。"},{"en":"Animal tracks are marks or paths left by animals as they move through an area.","zh":"animal tracks 指動物在某地移動時留下的痕跡或路徑。"},{"en":"Hikers may notice animal tracks in mud after rain.","zh":"下雨後，遠足者可能在泥地中注意到動物腳印。"},{"en":"Following animal tracks can help people move through thick forest where human paths are unclear.","zh":"在人類路徑不清楚的茂密森林中，跟隨獸徑可以幫助人前進。"},{"en":"This phrase can mean footprints or narrow routes made by animals.","zh":"這個短語可以指腳印，也可以指動物走出的狹窄路線。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":5},{"front":"thick vegetation","meaning":"茂密植被","examples":[{"en":"The team explored the thick vegetation near the trail.","zh":"團隊探索小徑附近的茂密植被。"},{"en":"Thick vegetation means dense plant growth that may be hard to walk through.","zh":"thick vegetation 指密集生長、可能難以穿越的植物。"},{"en":"A hiker may move slowly through thick vegetation because branches and leaves block the way.","zh":"遠足者可能在茂密植被中走得很慢，因為樹枝和葉子擋路。"},{"en":"Thick vegetation can hide flowers, insects, and smells from easy view.","zh":"茂密植被可以把花、昆蟲和氣味藏起來，不易看見。"},{"en":"This phrase describes a crowded natural environment.","zh":"這個短語描述植物密集的自然環境。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":6},{"front":"up to 10 metres","meaning":"遠至10米","examples":[{"en":"The team explored vegetation up to 10 metres from the trail.","zh":"團隊探索離小徑遠至10米的植被。"},{"en":"Up to 10 metres means as far as 10 metres, but not beyond that distance.","zh":"up to 10 metres 指最遠到10米，但不超過該距離。"},{"en":"Children were allowed to play up to 10 metres from the picnic area.","zh":"孩子被允許在離野餐區遠至10米的地方玩耍。"},{"en":"Setting a distance limit helps searchers stay safe and avoid getting lost.","zh":"設定距離限制有助搜尋者保持安全並避免迷路。"},{"en":"This phrase gives a maximum range.","zh":"這個短語提供最大範圍。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":6},{"front":"on either side of","meaning":"在……兩旁","examples":[{"en":"The hunters searched on either side of the trail.","zh":"獵人在小徑兩旁搜尋。"},{"en":"On either side of something means on both sides of it.","zh":"on either side of something 指在某物的兩邊。"},{"en":"Trees grew on either side of the road, giving drivers shade.","zh":"道路兩旁長着樹，為司機提供陰影。"},{"en":"Searching both sides of a path reduces the chance of missing something nearby.","zh":"搜尋路徑兩旁可以減少錯過附近東西的機會。"},{"en":"This phrase is useful for describing position around a central line.","zh":"這個短語適合描述中央線兩側的位置。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":6},{"front":"obvious places","meaning":"明顯的地方","examples":[{"en":"Some smells came from obvious places.","zh":"有些氣味來自明顯的地方。"},{"en":"Obvious places are locations that are easy to notice or guess as possible sources.","zh":"obvious places 指容易注意到或猜到可能是來源的位置。"},{"en":"In a kitchen, a strong garlic smell may come from an obvious place: the frying pan.","zh":"在廚房中，濃烈蒜味可能來自明顯的地方：煎鍋。"},{"en":"Starting with obvious places saves time before searching hidden sources.","zh":"先從明顯地方開始，可以在搜尋隱藏來源前節省時間。"},{"en":"This phrase contrasts clear sources with harder-to-find ones.","zh":"這個短語把清楚來源與較難找的來源作對比。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":6},{"front":"showy flowers","meaning":"鮮艷奪目的花","examples":[{"en":"Some smells came from big showy flowers.","zh":"有些氣味來自大型鮮艷奪目的花。"},{"en":"Showy flowers are large, bright, or attractive flowers that easily catch attention.","zh":"showy flowers 指大型、鮮艷或吸引眼球的花。"},{"en":"Garden centres often display showy flowers near the entrance to attract customers.","zh":"園藝店常把鮮艷奪目的花放在入口附近，以吸引顧客。"},{"en":"Showy flowers may attract insects, birds, and humans because of their colour and smell.","zh":"鮮艷奪目的花可能因顏色和氣味吸引昆蟲、鳥類和人類。"},{"en":"This phrase describes flowers that are visually striking.","zh":"這個短語描述視覺上非常突出的花。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":6},{"front":"within easy reach","meaning":"觸手可及","examples":[{"en":"Many showy flowers were within easy reach.","zh":"許多鮮艷奪目的花都觸手可及。"},{"en":"Within easy reach means close enough to touch or get without difficulty.","zh":"within easy reach 指距離近到可以輕易觸碰或取得。"},{"en":"A teacher keeps chalk within easy reach during a lesson.","zh":"老師在上課時把粉筆放在觸手可及的地方。"},{"en":"If tools are within easy reach, people can work faster and more safely.","zh":"如果工具觸手可及，人們可以更快、更安全地工作。"},{"en":"This phrase describes convenient physical access.","zh":"這個短語描述方便的實體取得位置。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":6},{"front":"hard to pin down","meaning":"難以確定；難以找出來源","examples":[{"en":"Some smells were much harder to pin down.","zh":"有些氣味更難以確定來源。"},{"en":"Hard to pin down means difficult to identify, locate, or explain clearly.","zh":"hard to pin down 指難以清楚辨認、定位或解釋。"},{"en":"A strange sound in a car can be hard to pin down if it appears only sometimes.","zh":"如果汽車中的怪聲只偶爾出現，就可能難以確定來源。"},{"en":"If the source of a smell is hard to pin down, searchers may need to test several possible places.","zh":"如果氣味來源難以確定，搜尋者可能需要測試幾個可能位置。"},{"en":"This phrase is useful for problems that are unclear or slippery.","zh":"這個短語適用於不清楚或難掌握的問題。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":6},{"front":"the luxuriance of the rainforest","meaning":"雨林的茂盛繁密","examples":[{"en":"The team left the luxuriance of the rainforest for Nosy Hara.","zh":"團隊離開雨林的茂盛繁密，前往 Nosy Hara。"},{"en":"The luxuriance of the rainforest means the rich, thick, and abundant growth of rainforest plants.","zh":"the luxuriance of the rainforest 指雨林植物豐富、茂密而大量生長的狀態。"},{"en":"Visitors may be amazed by the luxuriance of a rainforest after seeing dry farmland.","zh":"遊客在看過乾旱農田後，可能驚訝於雨林的茂盛繁密。"},{"en":"Luxuriant growth can hide animals, flowers, and paths from view.","zh":"茂盛生長可以把動物、花朵和路徑藏起來。"},{"en":"This phrase creates a strong image of dense natural richness.","zh":"這個短語營造出自然界密集豐富的強烈畫面。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":6},{"front":"little-known island","meaning":"鮮為人知的島嶼","examples":[{"en":"Nosy Hara was a little-known island.","zh":"Nosy Hara 是一個鮮為人知的島嶼。"},{"en":"A little-known island is an island that few people know about.","zh":"little-known island 指很少人知道的島嶼。"},{"en":"Travellers may enjoy a little-known island because it is quieter than famous resorts.","zh":"旅客可能喜歡鮮為人知的島嶼，因為它比著名度假區安靜。"},{"en":"Little-known places can contain unusual plants or traditions that have not been widely studied.","zh":"鮮為人知的地方可能含有未被廣泛研究的不尋常植物或傳統。"},{"en":"This phrase suggests obscurity, not necessarily lack of importance.","zh":"這個短語表示不為人熟知，不一定表示不重要。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":6},{"front":"stark, dry place","meaning":"荒涼乾燥的地方","examples":[{"en":"Nosy Hara was a stark, dry place.","zh":"Nosy Hara 是一個荒涼乾燥的地方。"},{"en":"A stark, dry place is bare, harsh, and lacking lush vegetation or moisture.","zh":"stark, dry place 指光禿、嚴酷、缺乏茂密植物或水分的地方。"},{"en":"A desert edge can feel like a stark, dry place after heavy green farmland.","zh":"在大片綠色農田之後，沙漠邊緣可能感覺像荒涼乾燥的地方。"},{"en":"Such conditions may support very different plants from those in a rainforest.","zh":"這種環境可能孕育出與雨林非常不同的植物。"},{"en":"This phrase creates a contrast with rich, wet environments.","zh":"這個短語與豐富濕潤的環境形成對比。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":6},{"front":"geologically and biologically","meaning":"在地質和生物方面","examples":[{"en":"The island was geologically and biologically different from the mainland.","zh":"這個島在地質和生物方面與大陸不同。"},{"en":"Geologically and biologically means in terms of rocks, land formation, living things, and ecosystems.","zh":"geologically and biologically 指在岩石、地形、生物和生態系統方面。"},{"en":"Two islands may be geologically and biologically different even if they are close together.","zh":"即使兩個島嶼相距很近，它們在地質和生物方面也可能不同。"},{"en":"Such differences can explain why one place has plants or smells that another place lacks.","zh":"這些差異可以解釋為何一個地方有另一個地方沒有的植物或氣味。"},{"en":"This phrase combines earth science and life science.","zh":"這個短語結合地球科學和生命科學。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":6},{"front":"different from the mainland","meaning":"與大陸不同","examples":[{"en":"Nosy Hara was very different from the mainland.","zh":"Nosy Hara 與大陸非常不同。"},{"en":"Different from the mainland means unlike the larger land area nearby.","zh":"different from the mainland 指不同於附近較大的陸地地區。"},{"en":"An island may have weather and plants different from the mainland.","zh":"島嶼可能有與大陸不同的天氣和植物。"},{"en":"Isolation can make island species develop in unusual ways.","zh":"隔離可以令島上物種以不尋常方式發展。"},{"en":"This phrase is useful when comparing islands with nearby continental areas.","zh":"比較島嶼與附近大陸地區時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":7},{"front":"apart from","meaning":"除了……之外","examples":[{"en":"Apart from two beaches, the island was impenetrable.","zh":"除了兩個海灘之外，這個島難以進入。"},{"en":"Apart from means except for or not including.","zh":"apart from 指除了或不包括。"},{"en":"Apart from one small café, the village had no shops.","zh":"除了一間小咖啡店之外，這條村沒有商店。"},{"en":"This phrase helps show the only exception to a general statement.","zh":"這個短語幫助指出一般說法中的唯一例外。"},{"en":"It is useful when most of a situation is one way, but one part is different.","zh":"當大部分情況相同，但有一部分不同時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":7},{"front":"impenetrable","meaning":"難以穿越的；無法進入的","examples":[{"en":"Most of the island was impenetrable without cutting through the bush.","zh":"如果不劈開灌木叢，島上大部分地方都難以穿越。"},{"en":"Impenetrable means impossible or very difficult to enter, pass through, or understand.","zh":"impenetrable 指無法或很難進入、穿過或理解。"},{"en":"A forest can be impenetrable if thick branches block every path.","zh":"如果濃密樹枝阻塞每條路，森林可能難以穿越。"},{"en":"If an area is impenetrable, explorers may need tools to cut a route.","zh":"如果某地難以進入，探險者可能需要工具開路。"},{"en":"This word can describe physical barriers or difficult writing.","zh":"這個詞可描述實體障礙，也可描述難懂文章。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":7},{"front":"hack through the bush","meaning":"劈開灌木叢前進","examples":[{"en":"The team had to hack through the bush to explore the island.","zh":"團隊必須劈開灌木叢前進，才能探索這個島。"},{"en":"To hack through the bush means to cut through dense plants in order to move forward.","zh":"hack through the bush 指劈開茂密植物，以便向前行。"},{"en":"Rescue workers may hack through the bush to reach a lost hiker.","zh":"救援人員可能要劈開灌木叢前進，才能到達迷路的遠足者。"},{"en":"This action is tiring because thick branches and thorny plants block movement.","zh":"這個動作很累，因為濃密樹枝和帶刺植物會阻礙前進。"},{"en":"The phrase suggests difficult physical progress through wild vegetation.","zh":"這個短語表示在野生植被中艱難地實體前進。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":7},{"front":"one of the biggest prizes","meaning":"最大收穫之一","examples":[{"en":"One of the biggest prizes was a sweet-smelling sap.","zh":"最大收穫之一是一種帶甜香的樹液。"},{"en":"One of the biggest prizes means one of the most valuable or exciting discoveries.","zh":"one of the biggest prizes 指最有價值或最令人興奮的發現之一。"},{"en":"In a science fair, one of the biggest prizes may be a chance to visit a research lab.","zh":"在科學展中，最大獎勵之一可能是參觀研究實驗室的機會。"},{"en":"A discovery becomes a big prize when it is rare, useful, or surprising.","zh":"當一項發現罕見、有用或令人驚訝時，它就成為重大收穫。"},{"en":"This phrase can describe rewards or important findings.","zh":"這個短語可以描述獎勵，也可以描述重要發現。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":7},{"front":"sweet-smelling sap","meaning":"帶甜香的樹液","examples":[{"en":"The team found sweet-smelling sap on ancient shrubby trees.","zh":"團隊在古老灌木狀樹木上發現帶甜香的樹液。"},{"en":"Sweet-smelling sap is sticky liquid from a plant or tree that has a pleasant sweet smell.","zh":"sweet-smelling sap 指來自植物或樹木、帶宜人甜味的黏性液體。"},{"en":"A child may notice sweet-smelling sap on a tree trunk during a walk.","zh":"孩子散步時可能注意到樹幹上的帶甜香樹液。"},{"en":"Such sap can interest perfumers because it may contain unusual fragrance molecules.","zh":"這類樹液可能含有不尋常香氣分子，因此吸引香水師。"},{"en":"This phrase describes both the substance and its smell.","zh":"這個短語同時描述物質和其氣味。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":7},{"front":"weep from","meaning":"從……滲出","examples":[{"en":"The sap was weeping from the gnarled branches.","zh":"樹液從扭曲粗糙的樹枝中滲出。"},{"en":"To weep from something means to slowly ooze or drip out from it.","zh":"weep from something 指慢慢從某物滲出或滴出。"},{"en":"Resin may weep from a cut in a tree’s bark.","zh":"樹脂可能從樹皮切口中滲出。"},{"en":"If liquid weeps from a plant, researchers may collect it carefully for testing.","zh":"如果液體從植物滲出，研究人員可能小心收集來測試。"},{"en":"This verb gives the movement a slow, natural feeling.","zh":"這個動詞令動作帶有緩慢、自然的感覺。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":7},{"front":"gnarled branches","meaning":"扭曲粗糙的樹枝","examples":[{"en":"The sap came from the gnarled branches of ancient trees.","zh":"樹液來自古老樹木扭曲粗糙的樹枝。"},{"en":"Gnarled branches are twisted, rough, and old-looking branches.","zh":"gnarled branches 指扭曲、粗糙、看起來古老的樹枝。"},{"en":"An old tree in a park may have gnarled branches that children like to draw.","zh":"公園中的老樹可能有孩子喜歡畫的扭曲粗糙樹枝。"},{"en":"Gnarled branches suggest age, weathering, and slow growth.","zh":"扭曲粗糙的樹枝暗示年歲、風霜和緩慢生長。"},{"en":"This phrase creates a strong visual image of old trees.","zh":"這個短語營造出老樹的鮮明視覺形象。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":7},{"front":"ancient shrubby trees","meaning":"古老灌木狀樹木","examples":[{"en":"The sap came from ancient shrubby trees.","zh":"樹液來自古老灌木狀樹木。"},{"en":"Ancient shrubby trees are very old trees with a low, bush-like shape.","zh":"ancient shrubby trees 指非常古老、外形低矮像灌木的樹木。"},{"en":"In dry areas, ancient shrubby trees may grow slowly and stay small.","zh":"在乾旱地區，古老灌木狀樹木可能生長緩慢並保持矮小。"},{"en":"Old trees may produce resins or saps that have unusual smells.","zh":"老樹可能產生帶有不尋常氣味的樹脂或樹液。"},{"en":"This phrase describes both age and physical form.","zh":"這個短語同時描述年齡和外形。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":7},{"front":"parched interior","meaning":"乾旱的內陸","examples":[{"en":"The trees grew in the parched interior of the island.","zh":"這些樹生長在島上乾旱的內陸。"},{"en":"A parched interior is a very dry inland area.","zh":"parched interior 指非常乾燥的內陸地區。"},{"en":"Farmers in a parched interior may struggle to find enough water for crops.","zh":"乾旱內陸的農民可能難以找到足夠水源種植作物。"},{"en":"Dry interiors often support different plants from wet coastal or forest areas.","zh":"乾旱內陸常孕育出與潮濕沿海或森林地區不同的植物。"},{"en":"This phrase combines dryness with location away from the coast.","zh":"這個短語結合乾燥和遠離海岸的位置。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":7},{"front":"so far","meaning":"到目前為止","examples":[{"en":"So far, no one has been able to identify the plant.","zh":"到目前為止，沒有人能辨認出這種植物。"},{"en":"So far means up to the present point in time.","zh":"so far 指直到目前這一刻為止。"},{"en":"So far, the class has learned ten new grammar patterns.","zh":"到目前為止，全班已學了十個新文法句式。"},{"en":"This phrase suggests the situation may change later if new information appears.","zh":"這個短語暗示如果出現新資料，情況日後可能改變。"},{"en":"It is useful when giving an update on progress.","zh":"匯報進展時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":7},{"front":"be able to identify","meaning":"能夠辨認出","examples":[{"en":"No one has been able to identify the plant.","zh":"沒有人能夠辨認出這種植物。"},{"en":"To be able to identify something means to recognise what it is or name it correctly.","zh":"be able to identify something 指能認出某物是甚麼或正確說出名稱。"},{"en":"A doctor may be able to identify an illness after checking symptoms and test results.","zh":"醫生檢查症狀和測試結果後，可能能夠辨認出疾病。"},{"en":"Identification is easier when there are clear features, records, or expert knowledge.","zh":"當有清楚特徵、記錄或專家知識時，辨認會更容易。"},{"en":"This phrase focuses on recognition, not just seeing something.","zh":"這個短語聚焦辨認，而不只是看見某物。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":8},{"front":"technique originally designed to","meaning":"原本為……而設計的技術","examples":[{"en":"The hunters used a technique originally designed to trap air pollutants.","zh":"獵人使用了一種原本為捕捉空氣污染物而設計的技術。"},{"en":"A technique originally designed to do something was first created for that purpose.","zh":"technique originally designed to do something 指最初為某目的而創造的技術。"},{"en":"A classroom app may use a system originally designed to manage business meetings.","zh":"課堂應用程式可能使用原本為管理商業會議而設計的系統。"},{"en":"Techniques can be adapted when a different field has a similar problem.","zh":"當另一領域有相似問題時，技術可以被改編。"},{"en":"This phrase shows how one invention can be reused in a new context.","zh":"這個短語顯示一項發明如何在新語境中被再用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":8},{"front":"trap and identify","meaning":"捕捉並識別","examples":[{"en":"The technique was designed to trap and identify air pollutants.","zh":"這項技術被設計來捕捉並識別空氣污染物。"},{"en":"To trap and identify something means to capture it and then find out what it is.","zh":"trap and identify something 指先捕捉某物，然後查明它是甚麼。"},{"en":"Scientists may trap and identify insects to study disease spread.","zh":"科學家可能捕捉並識別昆蟲，以研究疾病傳播。"},{"en":"Capturing a sample first makes later identification possible in the laboratory.","zh":"先捕捉樣本，才使之後在實驗室識別成為可能。"},{"en":"This phrase describes a two-step scientific process.","zh":"這個短語描述兩步科學過程。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":8},{"front":"air pollutants","meaning":"空氣污染物","examples":[{"en":"The technique was first used to identify air pollutants.","zh":"這項技術最初用於識別空氣污染物。"},{"en":"Air pollutants are harmful substances in the air, such as smoke, chemicals, or tiny particles.","zh":"air pollutants 指空氣中的有害物質，例如煙、化學物或微粒。"},{"en":"Cities monitor air pollutants near factories and busy roads.","zh":"城市監測工廠和繁忙道路附近的空氣污染物。"},{"en":"High levels of air pollutants can affect breathing and public health.","zh":"高水平空氣污染物可以影響呼吸和公共健康。"},{"en":"This phrase is common in environmental science and public health.","zh":"這個短語常見於環境科學和公共健康。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":8},{"front":"relatively simple","meaning":"相對簡單","examples":[{"en":"The technique itself is relatively simple.","zh":"這項技術本身相對簡單。"},{"en":"Relatively simple means simple compared with other things or with what people might expect.","zh":"relatively simple 指與其他事物或人們預期相比較簡單。"},{"en":"The recipe is relatively simple because it needs only three ingredients.","zh":"這個食譜相對簡單，因為只需要三種材料。"},{"en":"A simple method can still be powerful if it solves the right problem.","zh":"如果簡單方法能解決正確問題，它仍可以很有力。"},{"en":"This phrase is careful because it says simple in comparison, not absolutely easy.","zh":"這個短語較謹慎，因為它表示相對上簡單，而不是絕對容易。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":8},{"front":"glass bell jar","meaning":"玻璃鐘罩","examples":[{"en":"A glass bell jar is fitted over the flower.","zh":"玻璃鐘罩被套在花上。"},{"en":"A glass bell jar is a clear dome-shaped container used to cover or enclose something.","zh":"glass bell jar 指用來覆蓋或包圍某物的透明鐘形容器。"},{"en":"A science class may use a glass bell jar to show how air affects a candle flame.","zh":"科學課可能使用玻璃鐘罩展示空氣如何影響蠟燭火焰。"},{"en":"Covering a flower with a jar helps trap the air and smell around it.","zh":"用罩蓋住花朵有助困住其周圍的空氣和氣味。"},{"en":"This phrase describes a specific piece of laboratory or display equipment.","zh":"這個短語描述特定的實驗室或展示設備。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":8},{"front":"flask","meaning":"燒瓶","examples":[{"en":"A flask may be fitted over the flower to trap fragrance molecules.","zh":"燒瓶可能被套在花上，以捕捉香氣分子。"},{"en":"A flask is a glass container used in laboratories to hold liquids, gases, or samples.","zh":"flask 指實驗室中用來盛載液體、氣體或樣本的玻璃容器。"},{"en":"A student may use a flask during a chemistry experiment.","zh":"學生在化學實驗中可能使用燒瓶。"},{"en":"In fragrance collection, a flask can help hold the air around a scented object.","zh":"在香氣採集中，燒瓶可以幫助保存帶香物件周圍的空氣。"},{"en":"This word is common in science and laboratory contexts.","zh":"這個詞常見於科學和實驗室語境。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":8},{"front":"be fitted over","meaning":"被套在……上","examples":[{"en":"A glass bell jar is fitted over the flower.","zh":"玻璃鐘罩被套在花上。"},{"en":"To be fitted over something means to be placed around or above it so it covers it closely.","zh":"be fitted over something 指被放在某物周圍或上方，使其緊密覆蓋。"},{"en":"A protective cover may be fitted over a machine to keep dust out.","zh":"保護罩可能被套在機器上，以防灰塵進入。"},{"en":"Fitting a container over a flower helps trap the scent before it escapes.","zh":"把容器套在花上有助在香氣散走前困住它。"},{"en":"This phrase describes careful physical placement.","zh":"這個短語描述仔細的實體放置。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":8},{"front":"fragrance molecules","meaning":"香氣分子","examples":[{"en":"The fragrance molecules are trapped in the headspace.","zh":"香氣分子被困在頂空中。"},{"en":"Fragrance molecules are tiny chemical particles that create a smell.","zh":"fragrance molecules 指形成氣味的微小化學粒子。"},{"en":"When perfume evaporates, fragrance molecules move through the air to the nose.","zh":"當香水揮發時，香氣分子穿過空氣到達鼻子。"},{"en":"Capturing these molecules allows scientists to study what makes a smell special.","zh":"捕捉這些分子讓科學家研究某種氣味有何特別。"},{"en":"This phrase links chemistry with scent.","zh":"這個短語把化學與氣味連接起來。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":8},{"front":"be trapped in","meaning":"被困在……之中","examples":[{"en":"The fragrance molecules are trapped in the headspace.","zh":"香氣分子被困在頂空中。"},{"en":"To be trapped in something means to be held inside it and unable to escape easily.","zh":"be trapped in something 指被困在某物裏面，難以逃出。"},{"en":"Heat may be trapped in a small room if the windows are closed.","zh":"如果窗戶關上，熱力可能被困在小房間中。"},{"en":"Trapping scent molecules allows researchers to collect and analyse them later.","zh":"困住香氣分子讓研究人員日後收集和分析它們。"},{"en":"This phrase can describe physical capture or being stuck in a situation.","zh":"這個短語可描述實體捕捉，也可描述困於某種情況。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":8},{"front":"headspace","meaning":"頂空；樣本上方空間","examples":[{"en":"The fragrance molecules are trapped in the headspace around the flower.","zh":"香氣分子被困在花朵周圍的頂空中。"},{"en":"Headspace is the air space above or around a sample where smell molecules collect.","zh":"headspace 指樣本上方或周圍、氣味分子聚集的空氣空間。"},{"en":"In a sealed jar of fruit, the headspace may contain the fruit’s aroma.","zh":"在密封水果瓶中，頂空可能含有水果香氣。"},{"en":"Studying headspace helps scientists capture scent without cutting up the plant.","zh":"研究頂空幫助科學家在不切開植物的情況下捕捉氣味。"},{"en":"This word is technical and common in fragrance analysis.","zh":"這個詞較技術性，常見於香氣分析。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":8},{"front":"be extracted by","meaning":"透過……被提取","examples":[{"en":"The molecules can be extracted by pumping the air through filters.","zh":"這些分子可以透過將空氣抽過過濾器而被提取。"},{"en":"To be extracted by a method means to be removed or collected using that method.","zh":"be extracted by a method 指用某方法移除或收集某物。"},{"en":"Juice can be extracted by pressing fruit.","zh":"果汁可以透過壓榨水果被提取。"},{"en":"In scent collection, molecules are extracted so they can be studied separately.","zh":"在氣味採集中，分子被提取出來，以便單獨研究。"},{"en":"This phrase explains the method used to obtain something.","zh":"這個短語解釋取得某物的方法。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":9},{"front":"pump the air out","meaning":"將空氣抽出","examples":[{"en":"The hunters pump the air out over a series of filters.","zh":"獵人把空氣抽出，讓它通過一系列過濾器。"},{"en":"To pump the air out means to move air out of a space using a pump.","zh":"pump the air out 指用泵把空氣從某空間移出。"},{"en":"A technician may pump the air out of a sealed bag to test for leaks.","zh":"技術員可能把密封袋中的空氣抽出，以測試是否漏氣。"},{"en":"Moving air through filters allows tiny particles or molecules to be collected.","zh":"讓空氣通過過濾器，可以收集微小粒子或分子。"},{"en":"This phrase describes a controlled movement of air.","zh":"這個短語描述受控制的空氣移動。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":9},{"front":"a series of filters","meaning":"一系列過濾器","examples":[{"en":"The air passes over a series of filters.","zh":"空氣通過一系列過濾器。"},{"en":"A series of filters is several filters arranged one after another.","zh":"a series of filters 指幾個過濾器一個接一個排列。"},{"en":"A water purifier may use a series of filters to remove dirt and chemicals.","zh":"淨水器可能使用一系列過濾器去除污垢和化學物。"},{"en":"Different filters can catch different particles or molecules.","zh":"不同過濾器可以捕捉不同粒子或分子。"},{"en":"This phrase suggests a step-by-step filtering process.","zh":"這個短語表示逐步過濾的過程。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":9},{"front":"absorb different types of","meaning":"吸收不同種類的……","examples":[{"en":"The filters absorb different types of volatile molecules.","zh":"過濾器吸收不同種類的揮發性分子。"},{"en":"To absorb different types of something means to take in several kinds of it.","zh":"absorb different types of something 指吸收幾種不同類型的某物。"},{"en":"A sponge can absorb different types of liquid spills in a kitchen.","zh":"海綿可以吸收廚房中不同種類的液體潑灑物。"},{"en":"Special filters are useful because different materials trap different molecules.","zh":"特殊過濾器很有用，因為不同材料會捕捉不同分子。"},{"en":"This phrase describes selective collection or intake.","zh":"這個短語描述選擇性收集或吸收。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":9},{"front":"volatile molecules","meaning":"揮發性分子","examples":[{"en":"The filters collect volatile molecules from the air.","zh":"過濾器從空氣中收集揮發性分子。"},{"en":"Volatile molecules are molecules that evaporate easily and can travel through the air.","zh":"volatile molecules 指容易揮發並能在空氣中移動的分子。"},{"en":"The smell of fresh coffee comes from volatile molecules reaching the nose.","zh":"新鮮咖啡的氣味來自到達鼻子的揮發性分子。"},{"en":"Because volatile molecules move easily, they can be captured from the air around a sample.","zh":"由於揮發性分子容易移動，它們可以從樣本周圍的空氣中被捕捉。"},{"en":"This phrase is common in chemistry and fragrance science.","zh":"這個短語常見於化學和香氣科學。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":9},{"front":"back home in the laboratory","meaning":"回到實驗室後","examples":[{"en":"Back home in the laboratory, the molecules are analysed.","zh":"回到實驗室後，這些分子會被分析。"},{"en":"Back home in the laboratory means after returning from fieldwork to a research lab.","zh":"back home in the laboratory 指野外工作後回到研究實驗室。"},{"en":"Back home in the laboratory, scientists check samples collected during the expedition.","zh":"回到實驗室後，科學家檢查考察期間收集的樣本。"},{"en":"Fieldwork gathers material, while lab work explains what the material contains.","zh":"野外工作收集材料，而實驗室工作解釋材料包含甚麼。"},{"en":"This phrase contrasts outdoor collection with indoor analysis.","zh":"這個短語把戶外收集與室內分析作對比。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":9},{"front":"be flushed out of","meaning":"從……沖洗出來","examples":[{"en":"The molecules are flushed out of the filters.","zh":"分子從過濾器中被沖洗出來。"},{"en":"To be flushed out of something means to be washed or forced out from inside it.","zh":"be flushed out of something 指從某物內部被沖洗或迫出。"},{"en":"Dirt can be flushed out of a pipe with strong water pressure.","zh":"污垢可以用強水壓從水管中沖洗出來。"},{"en":"In a lab, trapped molecules may be flushed out so they can be measured.","zh":"在實驗室中，被困住的分子可能被沖洗出來，以便測量。"},{"en":"This phrase describes removal from a container or material.","zh":"這個短語描述從容器或材料中移除某物。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":9},{"front":"be injected into","meaning":"被注入……","examples":[{"en":"The molecules are injected into a gas chromatograph.","zh":"這些分子被注入氣相色譜儀。"},{"en":"To be injected into something means to be put into it using a controlled flow or instrument.","zh":"be injected into something 指用受控制的流動或儀器把某物放入其中。"},{"en":"A nurse injects medicine into a patient’s arm using a needle.","zh":"護士用針把藥物注入病人手臂。"},{"en":"Scientists inject samples into machines so the machines can analyse them.","zh":"科學家把樣本注入機器，以便機器分析。"},{"en":"This phrase is used in both medical and laboratory contexts.","zh":"這個短語可用於醫療和實驗室語境。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":9},{"front":"gas chromatograph","meaning":"氣相色譜儀","examples":[{"en":"A gas chromatograph is used to analyse fragrance molecules.","zh":"氣相色譜儀被用來分析香氣分子。"},{"en":"A gas chromatograph is a laboratory machine that separates and measures chemicals in a gas sample.","zh":"gas chromatograph 指一種分離和測量氣體樣本中化學物的實驗室機器。"},{"en":"Scientists may use a gas chromatograph to study the smell of flowers or food.","zh":"科學家可能使用氣相色譜儀研究花或食物的氣味。"},{"en":"The machine helps identify which molecules create a fragrance.","zh":"這台機器幫助識別哪些分子創造香氣。"},{"en":"This phrase is technical and belongs to chemical analysis.","zh":"這個短語較技術性，屬於化學分析。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":9},{"front":"for analysis","meaning":"作分析之用","examples":[{"en":"The molecules are injected into a gas chromatograph for analysis.","zh":"這些分子被注入氣相色譜儀作分析之用。"},{"en":"For analysis means for careful scientific study or examination.","zh":"for analysis 指為了仔細科學研究或檢查。"},{"en":"A doctor may send a blood sample to a laboratory for analysis.","zh":"醫生可能把血液樣本送到實驗室作分析之用。"},{"en":"Analysis helps people understand what a sample contains and what it means.","zh":"分析幫助人們理解樣本包含甚麼及其意義。"},{"en":"This phrase explains the purpose of collecting or sending a sample.","zh":"這個短語解釋收集或送出樣本的目的。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":9},{"front":"attach the headspace gear","meaning":"安裝頂空採樣設備","examples":[{"en":"Sometimes it is impossible to attach the headspace gear.","zh":"有時不可能安裝頂空採樣設備。"},{"en":"To attach the headspace gear means to fix the equipment for collecting scent molecules around a sample.","zh":"attach the headspace gear 指把收集樣本周圍香氣分子的設備固定好。"},{"en":"Researchers may not be able to attach the gear if the plant is too high or fragile.","zh":"如果植物太高或太脆弱，研究人員可能無法安裝設備。"},{"en":"When equipment cannot be attached, scientists need another method for collecting scent.","zh":"當設備不能安裝時，科學家需要另一種收集氣味的方法。"},{"en":"This phrase describes setting up specialised sampling equipment.","zh":"這個短語描述設置專門採樣設備。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":9},{"front":"absorbent probe","meaning":"吸收探針","examples":[{"en":"The hunters fix an absorbent probe close to the smell.","zh":"獵人把吸收探針固定在氣味附近。"},{"en":"An absorbent probe is a small device that takes in molecules from the air.","zh":"absorbent probe 指從空氣中吸收分子的小型裝置。"},{"en":"Scientists may use an absorbent probe when a flower cannot be covered by a jar.","zh":"當花不能被玻璃罩蓋住時，科學家可能使用吸收探針。"},{"en":"The probe collects scent molecules so they can be analysed later.","zh":"探針收集香氣分子，以便日後分析。"},{"en":"This phrase refers to a tool for sampling smells.","zh":"這個短語指用於採集氣味的工具。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":10},{"front":"close to the source of","meaning":"靠近……的來源","examples":[{"en":"The probe is placed close to the source of the smell.","zh":"探針被放在靠近氣味來源的位置。"},{"en":"Close to the source of something means near the place where it begins or comes from.","zh":"close to the source of something 指接近某事開始或產生的地方。"},{"en":"A cleaner may stand close to the source of a bad smell to find the problem.","zh":"清潔工可能靠近臭味來源站着，以找出問題。"},{"en":"Being near the source helps collect a stronger and more accurate sample.","zh":"靠近來源有助收集更強、更準確的樣本。"},{"en":"This phrase is useful when tracing smells, sounds, or problems.","zh":"追蹤氣味、聲音或問題時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":10},{"front":"source of the smell","meaning":"氣味來源","examples":[{"en":"The hunters try to locate the source of the smell.","zh":"獵人嘗試找出氣味來源。"},{"en":"The source of the smell is the object or place producing the smell.","zh":"source of the smell 指產生該氣味的物件或地方。"},{"en":"In a fridge, old food may be the source of the smell.","zh":"在雪櫃中，舊食物可能是氣味來源。"},{"en":"Finding the source helps people remove, collect, or study the smell properly.","zh":"找到來源有助人們正確移除、收集或研究氣味。"},{"en":"This phrase is useful when a smell is noticeable but its origin is unclear.","zh":"當氣味明顯但來源不清楚時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":10},{"front":"look something like","meaning":"看起來有點像……","examples":[{"en":"The probe looks something like a hypodermic syringe.","zh":"探針看起來有點像皮下注射器。"},{"en":"To look something like something else means to look a little similar to it.","zh":"look something like something else 指外觀與另一物有點相似。"},{"en":"The new library looks something like a glass box from the outside.","zh":"新圖書館從外面看起來有點像玻璃盒。"},{"en":"This phrase is useful when the comparison is approximate, not exact.","zh":"當比較只是大約相似，而非完全相同時，這個短語很有用。"},{"en":"It helps readers imagine an unfamiliar object.","zh":"它幫助讀者想像陌生物件。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":10},{"front":"hypodermic syringe","meaning":"皮下注射器","examples":[{"en":"The probe looks like a hypodermic syringe.","zh":"探針看起來像皮下注射器。"},{"en":"A hypodermic syringe is a medical tool with a needle used to inject or remove liquid.","zh":"hypodermic syringe 指帶有針頭、用來注射或抽取液體的醫療工具。"},{"en":"Nurses use hypodermic syringes to give some vaccines or medicines.","zh":"護士使用皮下注射器注射某些疫苗或藥物。"},{"en":"Because the probe looks like a syringe, readers can imagine its thin tube and needle-like shape.","zh":"因為探針看起來像注射器，讀者可以想像其細管和針狀外形。"},{"en":"This phrase belongs mainly to medical and scientific contexts.","zh":"這個短語主要屬於醫療和科學語境。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":10},{"front":"except that","meaning":"只是；不同的是","examples":[{"en":"The probe looks like a syringe, except that the needle is made of silicone rubber.","zh":"探針看起來像注射器，只是針頭由矽橡膠製成。"},{"en":"Except that introduces a difference or exception to what has just been said.","zh":"except that 用來引出剛才說法中的差異或例外。"},{"en":"The two bags look the same, except that one has a red handle.","zh":"這兩個袋子看起來一樣，只是其中一個有紅色手柄。"},{"en":"This phrase helps compare two similar things while pointing out the key difference.","zh":"這個短語幫助比較兩件相似事物，同時指出關鍵差異。"},{"en":"It is useful when something is mostly true but needs qualification.","zh":"當某事大致正確但需要補充限制時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":10},{"front":"silicone rubber","meaning":"矽橡膠","examples":[{"en":"The needle is made of silicone rubber.","zh":"針頭由矽橡膠製成。"},{"en":"Silicone rubber is a flexible synthetic material often used in medical, kitchen, or scientific tools.","zh":"silicone rubber 指一種有彈性的人造材料，常用於醫療、廚房或科學工具。"},{"en":"A baby bottle teat may be made of silicone rubber because it is soft and washable.","zh":"奶瓶奶嘴可能由矽橡膠製成，因為它柔軟且可清洗。"},{"en":"In scent collection, silicone rubber can absorb molecules from the air.","zh":"在氣味採集中，矽橡膠可以從空氣中吸收分子。"},{"en":"This phrase refers to a material, not ordinary natural rubber.","zh":"這個短語指一種材料，不是普通天然橡膠。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":10},{"front":"soak up molecules","meaning":"吸收分子","examples":[{"en":"The silicone rubber soaks up molecules from the air.","zh":"矽橡膠從空氣中吸收分子。"},{"en":"To soak up molecules means to absorb tiny chemical particles.","zh":"soak up molecules 指吸收微小化學粒子。"},{"en":"A sponge soaks up water, while special materials can soak up smell molecules.","zh":"海綿吸收水，而特殊材料可以吸收氣味分子。"},{"en":"Soaking up molecules allows researchers to keep them until laboratory analysis.","zh":"吸收分子讓研究人員保存它們，直到實驗室分析。"},{"en":"This phrase explains how the probe collects scent.","zh":"這個短語解釋探針如何收集氣味。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":10},{"front":"retract the rubber needle","meaning":"收回橡膠針","examples":[{"en":"The hunters retract the rubber needle after a few hours.","zh":"獵人在幾小時後收回橡膠針。"},{"en":"To retract the rubber needle means to pull the rubber needle back into the tube or holder.","zh":"retract the rubber needle 指把橡膠針拉回管子或支架中。"},{"en":"A worker may retract a measuring probe after collecting a sample.","zh":"工人收集樣本後可能收回測量探針。"},{"en":"Retracting the needle protects the sample and prevents contamination.","zh":"收回針頭可以保護樣本並防止污染。"},{"en":"This phrase describes the careful closing step after collection.","zh":"這個短語描述收集後小心完成的步驟。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":10},{"front":"seal the tube","meaning":"密封管子","examples":[{"en":"The hunters seal the tube to keep the odour molecules inside.","zh":"獵人密封管子，以把氣味分子保存在裏面。"},{"en":"To seal the tube means to close it tightly so nothing can enter or escape.","zh":"seal the tube 指緊密關閉管子，使任何東西不能進出。"},{"en":"A nurse may seal a sample tube before sending it to the laboratory.","zh":"護士可能在把樣本送到實驗室前密封管子。"},{"en":"Sealing protects the sample from air, dirt, and loss of material.","zh":"密封可以保護樣本免受空氣、污垢和材料流失影響。"},{"en":"This phrase is common in laboratory and packaging contexts.","zh":"這個短語常見於實驗室和包裝語境。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":10},{"front":"keep molecules inside","meaning":"將分子保存在裏面","examples":[{"en":"The tube keeps the odour molecules inside until analysis.","zh":"管子將氣味分子保存在裏面，直到分析為止。"},{"en":"To keep molecules inside means to prevent tiny chemical particles from escaping.","zh":"keep molecules inside 指防止微小化學粒子逃逸。"},{"en":"A sealed bottle keeps fragrance molecules inside so the perfume does not lose its smell.","zh":"密封瓶把香氣分子保存在裏面，使香水不會失去氣味。"},{"en":"If molecules escape, the sample may become weaker or inaccurate.","zh":"如果分子逃走，樣本可能變弱或變得不準確。"},{"en":"This phrase explains why sealing is important.","zh":"這個短語解釋為何密封很重要。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":10},{"front":"promising fragrances","meaning":"有潛力的香氣","examples":[{"en":"Some of the most promising fragrances came from tree resins.","zh":"一些最有潛力的香氣來自樹脂。"},{"en":"Promising fragrances are smells that seem likely to become useful or successful in products.","zh":"promising fragrances 指看起來可能在產品中有用或成功的氣味。"},{"en":"A perfume maker may test promising fragrances on paper strips before choosing one.","zh":"香水製造者可能先在試香紙上測試有潛力的香氣，再作選擇。"},{"en":"A fragrance is promising if it smells attractive and can be recreated reliably.","zh":"如果一種香氣聞起來吸引，而且能可靠重現，它就有潛力。"},{"en":"This phrase suggests potential rather than final success.","zh":"這個短語表示潛力，而不是最終成功。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":11},{"front":"be given off by","meaning":"由……散發出","examples":[{"en":"The fragrances were given off by resins from trees.","zh":"這些香氣由樹木的樹脂散發出。"},{"en":"To be given off by something means to be released or produced by it.","zh":"be given off by something 指由某物釋放或產生出來。"},{"en":"Heat may be given off by a laptop after long use.","zh":"手提電腦長時間使用後可能散發熱力。"},{"en":"Flowers give off smells to attract insects or other animals.","zh":"花朵散發氣味以吸引昆蟲或其他動物。"},{"en":"This phrase describes something coming out from a source.","zh":"這個短語描述某物從來源中散發出來。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":11},{"front":"resins","meaning":"樹脂","examples":[{"en":"Resins are the source of many traditional perfumes.","zh":"樹脂是許多傳統香水的來源。"},{"en":"Resins are sticky substances produced by some trees and plants.","zh":"resins 指某些樹木和植物產生的黏性物質。"},{"en":"A tree may produce resin when its bark is cut or damaged.","zh":"當樹皮被切開或受損時，樹木可能產生樹脂。"},{"en":"Resins can have strong smells, so they have long been used in incense and perfume.","zh":"樹脂可以有強烈氣味，因此長久以來被用於焚香和香水。"},{"en":"This word is common in botany, perfume, and traditional medicine contexts.","zh":"這個詞常見於植物學、香水和傳統醫藥語境。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":11},{"front":"ooze from","meaning":"從……滲出","examples":[{"en":"The resins oozed from the bark of trees.","zh":"樹脂從樹皮中滲出。"},{"en":"To ooze from something means to flow out slowly and thickly.","zh":"ooze from something 指緩慢而濃稠地流出。"},{"en":"Honey may ooze from a cracked jar if it is not closed properly.","zh":"如果瓶子沒有關好，蜜糖可能從裂縫中慢慢滲出。"},{"en":"When resin oozes from bark, it may harden after contact with air.","zh":"當樹脂從樹皮滲出，接觸空氣後可能變硬。"},{"en":"This verb suggests slow movement of a thick liquid.","zh":"這個動詞表示濃稠液體緩慢移動。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":11},{"front":"bark of trees","meaning":"樹皮","examples":[{"en":"The resins came from the bark of trees.","zh":"樹脂來自樹皮。"},{"en":"The bark of trees is the outer protective layer covering tree trunks and branches.","zh":"bark of trees 指覆蓋樹幹和樹枝外面的保護層。"},{"en":"Children can feel the rough bark of trees during a nature walk.","zh":"孩子在自然步行時可以摸到粗糙的樹皮。"},{"en":"Bark protects trees, but it may release resin when damaged.","zh":"樹皮保護樹木，但受損時可能釋放樹脂。"},{"en":"This phrase refers to the outside layer, not the wood inside.","zh":"這個短語指外層，而不是內部木材。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":11},{"front":"the source of","meaning":"……的來源","examples":[{"en":"Resins are the source of many traditional perfumes.","zh":"樹脂是許多傳統香水的來源。"},{"en":"The source of something is the place, material, or cause it comes from.","zh":"the source of something 指某物來自的地方、材料或原因。"},{"en":"A teacher may ask students to find the source of a quotation.","zh":"老師可能要求學生找出引文的來源。"},{"en":"Knowing the source helps people judge quality, safety, or reliability.","zh":"知道來源有助人們判斷質素、安全性或可靠性。"},{"en":"This phrase is useful for origins, causes, and materials.","zh":"這個短語適用於起源、原因和材料。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":11},{"front":"traditional perfumes","meaning":"傳統香水","examples":[{"en":"Frankincense and myrrh are used in traditional perfumes.","zh":"乳香和沒藥被用於傳統香水中。"},{"en":"Traditional perfumes are perfumes made with long-used natural materials or old fragrance practices.","zh":"traditional perfumes 指使用長久以來使用的天然材料或古老香氣做法製成的香水。"},{"en":"A traditional perfume may use flower oils, resins, herbs, or spices.","zh":"傳統香水可能使用花油、樹脂、草藥或香料。"},{"en":"Such perfumes can preserve cultural memories through familiar smells.","zh":"這些香水可以透過熟悉氣味保存文化記憶。"},{"en":"This phrase contrasts older fragrance traditions with modern synthetic perfumes.","zh":"這個短語把古老香氣傳統與現代合成香水作對比。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":11},{"front":"frankincense and myrrh","meaning":"乳香和沒藥","examples":[{"en":"Frankincense and myrrh are examples of traditional perfume resins.","zh":"乳香和沒藥是傳統香水樹脂的例子。"},{"en":"Frankincense and myrrh are aromatic resins long used in incense, ritual, and perfume.","zh":"frankincense and myrrh 指長久用於焚香、儀式和香水的芳香樹脂。"},{"en":"A church or temple may smell of frankincense and myrrh during a ceremony.","zh":"教堂或寺廟在儀式期間可能有乳香和沒藥的氣味。"},{"en":"Their strong scent made them valuable in older fragrance traditions.","zh":"它們濃烈的氣味令其在古老香氣傳統中十分有價值。"},{"en":"This phrase often appears in religious, historical, and perfume contexts.","zh":"這個短語常出現在宗教、歷史和香水語境中。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":11},{"front":"Calophyllum tree","meaning":"胡桐樹","examples":[{"en":"The most exciting resin came from a Calophyllum tree.","zh":"最令人興奮的樹脂來自一棵胡桐樹。"},{"en":"A Calophyllum tree is a type of tree that can produce scented resin or oil.","zh":"Calophyllum tree 指一種可以產生帶香樹脂或油的樹木。"},{"en":"Researchers may collect samples from a Calophyllum tree to study its smell.","zh":"研究人員可能從胡桐樹收集樣本，以研究其氣味。"},{"en":"A tree becomes important to perfumers when its resin has an unusual scent.","zh":"當樹木的樹脂有不尋常氣味時，它對香水師就變得重要。"},{"en":"This phrase names a specific plant source.","zh":"這個短語指出一種特定植物來源。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":11},{"front":"strongly scented","meaning":"氣味濃烈的","examples":[{"en":"The Calophyllum tree produces a strongly scented medicinal oil.","zh":"胡桐樹產生一種氣味濃烈的藥用油。"},{"en":"Strongly scented means having a powerful or easily noticeable smell.","zh":"strongly scented 指具有強烈或容易注意到的氣味。"},{"en":"Garlic is strongly scented, so a small amount can change the smell of a whole dish.","zh":"大蒜氣味濃烈，所以少量也可以改變整道菜的氣味。"},{"en":"Strong scents can attract attention, but they may also be too heavy for some people.","zh":"濃烈氣味可以吸引注意，但對有些人來說也可能太重。"},{"en":"This phrase describes smell intensity.","zh":"這個短語描述氣味強度。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":11},{"front":"medicinal oil","meaning":"藥用油","examples":[{"en":"The tree produces a strongly scented medicinal oil.","zh":"這棵樹產生一種氣味濃烈的藥用油。"},{"en":"Medicinal oil is oil used or believed to be useful for health or healing.","zh":"medicinal oil 指被使用或被認為有助健康或療癒的油。"},{"en":"Some families use medicinal oil for muscle pain or insect bites.","zh":"有些家庭使用藥用油舒緩肌肉痛或蚊叮蟲咬。"},{"en":"Medicinal oils may have strong smells because they contain active plant chemicals.","zh":"藥用油可能有強烈氣味，因為它們含有活性植物化學物。"},{"en":"This phrase refers to oil with health-related use, not cooking oil.","zh":"這個短語指與健康用途有關的油，而不是食用油。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":11},{"front":"rich and aromatic","meaning":"濃郁而芳香","examples":[{"en":"The sap smelt rich and aromatic.","zh":"樹液聞起來濃郁而芳香。"},{"en":"Rich and aromatic means deep, full, and pleasantly fragrant.","zh":"rich and aromatic 指氣味深厚、飽滿而芬芳。"},{"en":"Freshly brewed coffee can smell rich and aromatic in the morning.","zh":"早上新沖咖啡可以聞起來濃郁而芳香。"},{"en":"A rich aroma can make a product feel warm, expensive, or memorable.","zh":"濃郁香氣可以令產品感覺溫暖、高級或難忘。"},{"en":"This phrase is often used for perfume, food, coffee, tea, and incense.","zh":"這個短語常用於香水、食物、咖啡、茶和焚香。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":12},{"front":"church incense","meaning":"教堂焚香","examples":[{"en":"The sap smelt a little like church incense.","zh":"樹液聞起來有點像教堂焚香。"},{"en":"Church incense is fragrant smoke burned during some Christian religious services.","zh":"church incense 指某些基督教宗教儀式中燃燒的芳香煙霧。"},{"en":"Visitors may notice church incense during a ceremony in an old cathedral.","zh":"訪客在古老大教堂的儀式中可能注意到教堂焚香。"},{"en":"Comparing a smell to church incense suggests a warm, resinous, and ceremonial aroma.","zh":"把氣味比作教堂焚香，暗示溫暖、樹脂感和儀式感香氣。"},{"en":"This phrase gives readers a familiar religious smell reference.","zh":"這個短語給讀者一個熟悉的宗教氣味參照。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":12},{"front":"fragrance industry","meaning":"香水業","examples":[{"en":"The fragrance industry no longer uses some animal products.","zh":"香水業不再使用某些動物製品。"},{"en":"The fragrance industry includes companies and specialists who create scents for perfumes and scented products.","zh":"fragrance industry 指為香水和帶香產品創造氣味的公司和專家。"},{"en":"The fragrance industry supplies smells for shampoo, soap, candles, cleaners, and luxury perfumes.","zh":"香水業為洗頭水、肥皂、蠟燭、清潔劑和高級香水提供氣味。"},{"en":"Industry rules and customer values can change which ingredients companies use.","zh":"行業規則和顧客價值觀可以改變公司使用哪些成分。"},{"en":"This phrase refers to a business sector based on scent design.","zh":"這個短語指以氣味設計為基礎的商業領域。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":12},{"front":"learn to live without","meaning":"學會沒有……也能照樣運作","examples":[{"en":"The fragrance industry has learnt to live without castoreum.","zh":"香水業已學會沒有海狸香也能照樣運作。"},{"en":"To learn to live without something means to adapt to not having it anymore.","zh":"learn to live without something 指適應不再擁有某物。"},{"en":"A student may learn to live without a phone during exam revision.","zh":"學生可能在備考期間學會沒有手機也能生活。"},{"en":"People learn to live without an old tool when a safer or more acceptable substitute appears.","zh":"當更安全或更可接受的替代品出現，人們會學會沒有舊工具也能運作。"},{"en":"This phrase suggests adjustment after losing or giving up something.","zh":"這個短語表示失去或放棄某物後的適應。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":12},{"front":"castoreum","meaning":"海狸香","examples":[{"en":"Castoreum was once a key ingredient in many perfumes.","zh":"海狸香曾是許多香水的主要成分。"},{"en":"Castoreum is a strong-smelling substance historically taken from beavers and used in fragrance.","zh":"castoreum 指歷史上從海狸取得、用於香氣中的強烈氣味物質。"},{"en":"Old perfume formulas sometimes used castoreum to add an animal-like depth.","zh":"舊香水配方有時使用海狸香來增加動物感的深度。"},{"en":"Ethical concerns can lead companies to stop using ingredients such as castoreum.","zh":"道德考慮可能令公司停止使用海狸香等成分。"},{"en":"This word refers to a specific animal-derived perfume material.","zh":"這個詞指一種特定的動物來源香水材料。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":12},{"front":"substance extracted from","meaning":"從……提取的物質","examples":[{"en":"Castoreum is a substance extracted from the musk glands of beavers.","zh":"海狸香是從海狸麝香腺提取的物質。"},{"en":"A substance extracted from something is material taken out of a natural or chemical source.","zh":"substance extracted from something 指從天然或化學來源取出的材料。"},{"en":"Olive oil is a substance extracted from olives.","zh":"橄欖油是從橄欖提取的物質。"},{"en":"Extraction can be useful, but it may raise ethical or environmental concerns.","zh":"提取可以有用，但也可能引起道德或環境問題。"},{"en":"This phrase describes the origin and method of obtaining a material.","zh":"這個短語描述材料的來源和取得方法。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":12},{"front":"musk glands","meaning":"麝香腺","examples":[{"en":"Castoreum comes from the musk glands of beavers.","zh":"海狸香來自海狸的麝香腺。"},{"en":"Musk glands are animal glands that produce strong-smelling secretions.","zh":"musk glands 指產生強烈氣味分泌物的動物腺體。"},{"en":"Some animals use musk glands to mark territory or communicate.","zh":"有些動物使用麝香腺標記領地或溝通。"},{"en":"Substances from musk glands were once valued in perfume because of their lasting smell.","zh":"來自麝香腺的物質曾因氣味持久而在香水中有價值。"},{"en":"This phrase belongs to biology and traditional fragrance materials.","zh":"這個短語屬於生物學和傳統香水材料語境。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":12},{"front":"beavers","meaning":"海狸","examples":[{"en":"Castoreum was extracted from beavers.","zh":"海狸香是從海狸提取的。"},{"en":"Beavers are semi-aquatic mammals known for building dams and lodges.","zh":"beavers 指以築壩和築巢聞名的半水生哺乳動物。"},{"en":"A nature reserve may protect beavers because they help shape wetland habitats.","zh":"自然保護區可能保護海狸，因為牠們幫助塑造濕地棲息地。"},{"en":"In older perfume making, some animal substances from beavers were once used.","zh":"在舊式香水製作中，曾使用一些來自海狸的動物物質。"},{"en":"This word names an animal, not a plant or synthetic ingredient.","zh":"這個詞指一種動物，不是植物或合成成分。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":12},{"front":"key ingredient in","meaning":"……的主要成分","examples":[{"en":"Castoreum was once a key ingredient in many perfumes.","zh":"海狸香曾是許多香水的主要成分。"},{"en":"A key ingredient in something is one of the most important materials used to make it.","zh":"key ingredient in something 指製作某物時最重要的材料之一。"},{"en":"Flour is a key ingredient in bread.","zh":"麵粉是麵包的主要成分。"},{"en":"If a key ingredient disappears, makers may need to find a substitute.","zh":"如果主要成分消失，製造者可能需要尋找替代品。"},{"en":"This phrase is useful for recipes, products, medicines, and perfumes.","zh":"這個短語適用於食譜、產品、藥物和香水。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":12},{"front":"animal products","meaning":"動物製品","examples":[{"en":"The company does not use animal products any longer.","zh":"這家公司不再使用動物製品。"},{"en":"Animal products are materials that come from animals.","zh":"animal products 指來自動物的材料。"},{"en":"Leather, wool, honey, and some traditional fragrance materials are animal products.","zh":"皮革、羊毛、蜂蜜和一些傳統香氣材料都是動物製品。"},{"en":"Some companies avoid animal products because of ethical, legal, or customer concerns.","zh":"有些公司因道德、法律或顧客顧慮而避免使用動物製品。"},{"en":"This phrase contrasts animal-derived materials with plant-based or synthetic materials.","zh":"這個短語把動物來源材料與植物或合成材料作對比。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":12},{"front":"any longer","meaning":"不再","examples":[{"en":"The company does not use animal products any longer.","zh":"這家公司不再使用動物製品。"},{"en":"Any longer means anymore, usually after a negative verb.","zh":"any longer 指 anymore，通常用於否定動詞之後。"},{"en":"She does not work at that shop any longer.","zh":"她不再在那間商店工作。"},{"en":"This phrase shows that a past situation has changed.","zh":"這個短語顯示過去的情況已經改變。"},{"en":"It is often used when something used to happen but has stopped.","zh":"當某事過去曾發生但現在停止時，常用這個短語。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":12},{"front":"a tree with an animal smell","meaning":"帶有動物氣味的樹","examples":[{"en":"It was wonderful to find a tree with an animal smell.","zh":"找到一棵帶有動物氣味的樹實在太好了。"},{"en":"A tree with an animal smell is a tree whose scent resembles an animal-derived fragrance.","zh":"a tree with an animal smell 指氣味像動物來源香氣的樹。"},{"en":"Perfumers may value a tree with an animal smell if it can replace an animal product.","zh":"如果一棵帶有動物氣味的樹能取代動物製品，香水師可能很重視它。"},{"en":"Such a discovery can reduce the need to use ingredients taken from animals.","zh":"這種發現可以減少使用來自動物的成分的需要。"},{"en":"This phrase is surprising because trees usually smell woody, green, or floral.","zh":"這個短語令人驚訝，因為樹通常聞起來像木香、綠葉或花香。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":13},{"front":"capture the smell of","meaning":"捕捉……的氣味","examples":[{"en":"The group set out to capture the smell of coral reefs.","zh":"團隊出發去捕捉珊瑚礁的氣味。"},{"en":"To capture the smell of something means to collect and preserve its scent for study or recreation.","zh":"capture the smell of something 指收集並保存某物的氣味，以便研究或重現。"},{"en":"A candle maker may try to capture the smell of a rainy garden.","zh":"蠟燭製造者可能嘗試捕捉雨後花園的氣味。"},{"en":"Capturing a smell allows perfumers to analyse and recreate it later.","zh":"捕捉氣味讓香水師日後分析和重現它。"},{"en":"This phrase is useful when a scent is temporary or hard to bring back physically.","zh":"當氣味短暫或難以實體帶回時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":13},{"front":"coral reefs","meaning":"珊瑚礁","examples":[{"en":"The team tried to capture the smell of coral reefs.","zh":"團隊嘗試捕捉珊瑚礁的氣味。"},{"en":"Coral reefs are underwater structures formed by coral animals and home to many sea creatures.","zh":"coral reefs 指由珊瑚動物形成、為許多海洋生物提供棲息地的水下結構。"},{"en":"Divers visit coral reefs to see fish, colourful corals, and marine life.","zh":"潛水員到訪珊瑚礁，觀賞魚類、彩色珊瑚和海洋生命。"},{"en":"Coral reefs may have distinctive smells because many organisms live closely together.","zh":"珊瑚礁可能有獨特氣味，因為許多生物密集生活在一起。"},{"en":"This phrase belongs to marine biology and ocean environments.","zh":"這個短語屬於海洋生物學和海洋環境語境。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":13},{"front":"conjure up","meaning":"令人聯想到；喚起","examples":[{"en":"Some odours conjure up sun-kissed seas.","zh":"有些氣味令人聯想到陽光普照的海洋。"},{"en":"To conjure up something means to make people imagine or remember it vividly.","zh":"conjure up something 指令人鮮明地想像或記起某事。"},{"en":"The smell of fresh bread can conjure up memories of breakfast at home.","zh":"新鮮麵包的氣味可以喚起在家吃早餐的記憶。"},{"en":"A good fragrance can create an emotional image before a person sees anything.","zh":"好香氣可以在人看到任何東西之前創造情感畫面。"},{"en":"This phrase is often used for smells, music, stories, and memories.","zh":"這個短語常用於氣味、音樂、故事和記憶。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":13},{"front":"sun-kissed seas","meaning":"陽光普照的海洋","examples":[{"en":"The perfume industry wants odours that conjure up sun-kissed seas.","zh":"香水業想要能令人聯想到陽光普照海洋的氣味。"},{"en":"Sun-kissed seas are seas imagined as warm, bright, and touched by sunlight.","zh":"sun-kissed seas 指被想像成溫暖、明亮、被陽光照耀的海洋。"},{"en":"A travel advertisement may show sun-kissed seas to suggest relaxation and holidays.","zh":"旅遊廣告可能展示陽光普照的海洋，以暗示放鬆和假期。"},{"en":"Scents that suggest sun-kissed seas may make customers think of beaches and summer.","zh":"暗示陽光海洋的氣味可能令顧客想起海灘和夏天。"},{"en":"This phrase is poetic and creates a pleasant visual image.","zh":"這個短語有詩意，營造出愉快視覺畫面。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":13},{"front":"highly sought after","meaning":"大受追捧","examples":[{"en":"Ocean-like odours are highly sought after by the perfume industry.","zh":"海洋般的氣味在香水業中大受追捧。"},{"en":"Highly sought after means wanted by many people or organisations.","zh":"highly sought after 指受到許多人或機構渴望得到。"},{"en":"Graduates with strong language skills are highly sought after by international companies.","zh":"具備強大語言能力的畢業生大受國際公司追捧。"},{"en":"When something is highly sought after, its value or price may rise.","zh":"當某物大受追捧，其價值或價格可能上升。"},{"en":"This phrase describes strong demand.","zh":"這個短語描述強烈需求。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":13},{"front":"seaweed","meaning":"海藻","examples":[{"en":"Seaweed is one of the few ocean smells already available to perfumers.","zh":"海藻是香水師已可取得的少數海洋氣味之一。"},{"en":"Seaweed is a plant-like organism that grows in the sea.","zh":"seaweed 指生長在海中的植物狀生物。"},{"en":"People may notice the smell of seaweed on a beach after the tide goes out.","zh":"退潮後，人們可能在海灘上注意到海藻氣味。"},{"en":"Seaweed can give perfumes a salty, marine, or earthy quality.","zh":"海藻可以給香水帶來鹹味、海洋感或泥土感。"},{"en":"This word is common in food, ecology, and ocean-scent discussions.","zh":"這個詞常見於食物、生態和海洋香氣討論。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":13},{"front":"dark and heavy aroma","meaning":"深沉濃重的香氣","examples":[{"en":"Seaweed has a dark and heavy aroma.","zh":"海藻有深沉濃重的香氣。"},{"en":"A dark and heavy aroma is a deep, strong smell that may feel rich or serious.","zh":"dark and heavy aroma 指深厚、強烈，可能感覺濃郁或嚴肅的氣味。"},{"en":"Strong black coffee can have a dark and heavy aroma in a small room.","zh":"濃黑咖啡在小房間中可以有深沉濃重的香氣。"},{"en":"Heavy aromas can be memorable, but they may not suit every product.","zh":"濃重香氣可以令人難忘，但未必適合每種產品。"},{"en":"This phrase describes the character and weight of a smell.","zh":"這個短語描述氣味的性格和重量感。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":13},{"front":"unique among","meaning":"在……之中獨特的","examples":[{"en":"The team hoped to find something unique among the corals.","zh":"團隊希望在珊瑚之中找到獨特的東西。"},{"en":"Unique among something means special or unlike the others in that group.","zh":"unique among something 指在同一群體中與其他不同或特別。"},{"en":"A student’s idea may be unique among all the class projects.","zh":"學生的想法可能在全班項目之中獨特。"},{"en":"Finding something unique can give researchers a discovery worth studying further.","zh":"找到獨特事物可以給研究人員值得進一步研究的發現。"},{"en":"This phrase compares one item with others in the same category.","zh":"這個短語把一項事物與同類其他事物比較。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":13},{"front":"the challenge for","meaning":"對……來說的挑戰","examples":[{"en":"The challenge for the hunters was to extract a smell from water.","zh":"對獵人來說，挑戰是從水中提取氣味。"},{"en":"The challenge for someone is the difficult task or problem they must solve.","zh":"the challenge for someone 指某人必須解決的困難任務或問題。"},{"en":"The challenge for new teachers is to explain clearly while managing a whole class.","zh":"對新老師來說，挑戰是一邊清楚解釋，一邊管理整班學生。"},{"en":"A clear challenge helps people understand why a task requires skill or invention.","zh":"清楚的挑戰有助人們理解為何任務需要技巧或發明。"},{"en":"This phrase identifies who faces the difficulty.","zh":"這個短語指出誰面對困難。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":13},{"front":"extract a smell from water","meaning":"從水中提取氣味","examples":[{"en":"The hunters tried to extract a smell from water rather than air.","zh":"獵人嘗試從水中而不是空氣中提取氣味。"},{"en":"To extract a smell from water means to collect scent molecules that are dissolved or carried in water.","zh":"extract a smell from water 指收集溶於或存在於水中的氣味分子。"},{"en":"Scientists may try to extract a smell from seawater near coral or seaweed.","zh":"科學家可能嘗試從珊瑚或海藻附近的海水中提取氣味。"},{"en":"This is harder than collecting smells from air because the equipment must work underwater.","zh":"這比從空氣中收集氣味更困難，因為設備必須在水底運作。"},{"en":"The phrase describes a special form of scent collection.","zh":"這個短語描述一種特殊的氣味採集方式。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":13},{"front":"rather than air","meaning":"而不是空氣","examples":[{"en":"The team had to work with water rather than air.","zh":"團隊必須處理水，而不是空氣。"},{"en":"Rather than air means instead of using air as the medium or source.","zh":"rather than air 指不是使用空氣作為媒介或來源。"},{"en":"A swimmer breathes through a tube rather than air directly when the face is underwater.","zh":"游泳者臉在水下時，透過呼吸管呼吸，而不是直接呼吸空氣。"},{"en":"Choosing water rather than air changes the tools and methods needed.","zh":"選擇水而不是空氣，會改變所需工具和方法。"},{"en":"This phrase clearly contrasts two possible working conditions.","zh":"這個短語清楚對比兩種可能工作條件。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":14},{"front":"an opportunity to try","meaning":"嘗試……的機會","examples":[{"en":"The coral project was an opportunity to try a new apparatus.","zh":"珊瑚項目是嘗試新裝置的機會。"},{"en":"An opportunity to try something is a chance to test or use it.","zh":"an opportunity to try something 指測試或使用某物的機會。"},{"en":"A school fair can be an opportunity to try a new teaching game with students.","zh":"學校嘉年華可以是與學生嘗試新教學遊戲的機會。"},{"en":"Trying a new tool in a real situation shows whether it works outside the laboratory.","zh":"在真實情境中嘗試新工具，可以顯示它在實驗室外是否有效。"},{"en":"This phrase connects chance with experimentation.","zh":"這個短語把機會與實驗連接起來。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":14},{"front":"aquaspace apparatus","meaning":"水中氣味採集裝置","examples":[{"en":"Clery developed an aquaspace apparatus for underwater smells.","zh":"Clery 研發了一種用於水中氣味的水中氣味採集裝置。"},{"en":"An aquaspace apparatus is equipment designed to collect scent molecules from water.","zh":"aquaspace apparatus 指設計來從水中收集氣味分子的設備。"},{"en":"Researchers may use an aquaspace apparatus to study the smell around coral.","zh":"研究人員可能使用水中氣味採集裝置研究珊瑚周圍的氣味。"},{"en":"The apparatus is needed because ordinary headspace equipment works with air, not water.","zh":"這種裝置是必要的，因為普通頂空設備處理的是空氣，而不是水。"},{"en":"This phrase names a specialised underwater smell-collecting device.","zh":"這個短語指一種專門的水底氣味採集裝置。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":14},{"front":"work underwater","meaning":"在水底運作","examples":[{"en":"The aquaspace filters work underwater.","zh":"水中氣味採集裝置的過濾器在水底運作。"},{"en":"To work underwater means to function while submerged in water.","zh":"work underwater 指在浸於水中的情況下仍能運作。"},{"en":"A camera must work underwater if divers use it to film coral reefs.","zh":"如果潛水員用相機拍攝珊瑚礁，相機就必須能在水底運作。"},{"en":"Equipment that works underwater must resist pressure, movement, and water damage.","zh":"在水底運作的設備必須抵抗壓力、水流和水損。"},{"en":"This phrase describes both location and operating condition.","zh":"這個短語同時描述位置和運作條件。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":14},{"front":"be fixed over","meaning":"被固定在……上","examples":[{"en":"Jars were fixed over knobs of coral.","zh":"罐子被固定在珊瑚塊上。"},{"en":"To be fixed over something means to be securely placed above or around it.","zh":"be fixed over something 指被牢固地放在某物上方或周圍。"},{"en":"A protective cover may be fixed over a delicate machine part.","zh":"保護罩可能被固定在精密機器部件上。"},{"en":"Fixing a jar over coral helps collect the water and molecules around it.","zh":"把罐子固定在珊瑚上，有助收集其周圍的水和分子。"},{"en":"This phrase describes stable placement for a practical purpose.","zh":"這個短語描述為實際目的而作的穩定放置。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":14},{"front":"knobs of coral","meaning":"珊瑚塊","examples":[{"en":"Jars were fixed over knobs of coral about two metres down.","zh":"罐子被固定在水下約兩米的珊瑚塊上。"},{"en":"Knobs of coral are small rounded lumps or pieces of coral.","zh":"knobs of coral 指小而圓凸的珊瑚塊或珊瑚部分。"},{"en":"A diver may see knobs of coral growing on a reef surface.","zh":"潛水員可能看見珊瑚塊生長在珊瑚礁表面。"},{"en":"Covering small coral knobs makes it easier to collect water from a controlled area.","zh":"覆蓋小珊瑚塊更容易從受控區域收集水樣本。"},{"en":"This phrase describes the shape and size of the coral sample.","zh":"這個短語描述珊瑚樣本的形狀和大小。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":14},{"front":"absorbent filters","meaning":"吸收過濾器","examples":[{"en":"Water was pumped over the absorbent filters.","zh":"水被抽過吸收過濾器。"},{"en":"Absorbent filters are filters that take in molecules or particles from a liquid or gas.","zh":"absorbent filters 指能從液體或氣體中吸收分子或粒子的過濾器。"},{"en":"A water purifier uses absorbent filters to remove unwanted substances.","zh":"淨水器使用吸收過濾器去除不需要的物質。"},{"en":"In scent research, absorbent filters collect molecules that carry smell.","zh":"在氣味研究中，吸收過濾器收集帶有氣味的分子。"},{"en":"This phrase describes equipment that captures material from a flowing sample.","zh":"這個短語描述從流動樣本中捕捉物質的設備。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":14},{"front":"smell like","meaning":"聞起來像……","examples":[{"en":"Coral smells a bit like lobster and crab.","zh":"珊瑚聞起來有點像龍蝦和蟹。"},{"en":"To smell like something means to have a similar odour to it.","zh":"smell like something 指具有與某物相似的氣味。"},{"en":"A candle may smell like fresh oranges or warm bread.","zh":"蠟燭可能聞起來像新鮮橙子或暖麵包。"},{"en":"Comparing smells helps people imagine a scent they have never experienced directly.","zh":"比較氣味可以幫助人想像自己未曾直接經歷的香氣。"},{"en":"This phrase is simple and common in daily description.","zh":"這個短語簡單，常用於日常描述。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":14},{"front":"lobster and crab","meaning":"龍蝦和蟹","examples":[{"en":"Clery said coral smells a bit like lobster and crab.","zh":"Clery 說珊瑚聞起來有點像龍蝦和蟹。"},{"en":"Lobster and crab are shellfish often associated with a salty, marine smell.","zh":"lobster and crab 指常帶有鹹味和海洋氣味聯想的甲殼類海鮮。"},{"en":"A seafood market may smell of lobster and crab in the morning.","zh":"海鮮市場早上可能有龍蝦和蟹的氣味。"},{"en":"Comparing coral to lobster and crab helps readers imagine a sea-like scent.","zh":"把珊瑚比作龍蝦和蟹，有助讀者想像海洋般氣味。"},{"en":"This phrase gives a concrete food-based smell reference.","zh":"這個短語提供具體的食物氣味參照。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":14},{"front":"recreate the best of","meaning":"重現最好的……","examples":[{"en":"The team’s task is to recreate the best of the captured smells.","zh":"團隊的任務是重現已捕捉氣味中最好的部分。"},{"en":"To recreate the best of something means to make a new version that captures its strongest qualities.","zh":"recreate the best of something 指製作新版本，捕捉其最強特質。"},{"en":"A chef may recreate the best of a childhood meal without copying every detail.","zh":"廚師可能重現童年餐點中最好的部分，而不複製每個細節。"},{"en":"Recreating the best parts helps turn a raw experience into a usable product.","zh":"重現最好的部分有助把原始經驗轉化成可用產品。"},{"en":"This phrase focuses on preserving the most valuable features.","zh":"這個短語聚焦保留最有價值的特徵。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":14},{"front":"captured smells","meaning":"已捕捉到的氣味","examples":[{"en":"The team now has to recreate the captured smells.","zh":"團隊現在必須重現已捕捉到的氣味。"},{"en":"Captured smells are scents that have been collected and preserved for study.","zh":"captured smells 指已被收集並保存以供研究的氣味。"},{"en":"A scientist may compare captured smells from different flowers in the laboratory.","zh":"科學家可能在實驗室比較來自不同花朵的已捕捉氣味。"},{"en":"Once a smell is captured, its molecules can be analysed and copied.","zh":"一旦氣味被捕捉，其分子就可以被分析和複製。"},{"en":"This phrase describes smells after the collection stage.","zh":"這個短語描述收集階段之後的氣味。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":14},{"front":"make up each fragrance","meaning":"構成每種香氣","examples":[{"en":"The team must identify the molecules that make up each fragrance.","zh":"團隊必須識別構成每種香氣的分子。"},{"en":"To make up each fragrance means to form or compose each smell.","zh":"make up each fragrance 指形成或組成每種氣味。"},{"en":"A perfume may be made up of floral, woody, citrus, and spicy notes.","zh":"香水可能由花香、木香、柑橘香和辛香調構成。"},{"en":"Knowing what molecules make up a fragrance helps perfumers recreate it.","zh":"知道哪些分子構成香氣，有助香水師重現它。"},{"en":"This phrase explains the parts that form a whole scent.","zh":"這個短語解釋形成整體氣味的部分。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":15},{"front":"common chemicals","meaning":"常見化學物","examples":[{"en":"Some fragrance ingredients may be common chemicals.","zh":"有些香氣成分可能是常見化學物。"},{"en":"Common chemicals are substances that are widely available or frequently used.","zh":"common chemicals 指廣泛可得或經常使用的物質。"},{"en":"Salt and vinegar contain common chemicals found in many kitchens.","zh":"鹽和醋含有許多廚房中常見的化學物。"},{"en":"If a fragrance can be made from common chemicals, it may be cheaper to produce.","zh":"如果香氣可以由常見化學物製成，生產成本可能較低。"},{"en":"This phrase contrasts ordinary substances with rare or novel ones.","zh":"這個短語把普通物質與罕見或新奇物質作對比。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":15},{"front":"completely novel","meaning":"全新的","examples":[{"en":"Some ingredients may be completely novel.","zh":"有些成分可能是全新的。"},{"en":"Completely novel means entirely new or not known before.","zh":"completely novel 指完全新或以前不為人知。"},{"en":"A scientist may discover a completely novel material during an experiment.","zh":"科學家可能在實驗中發現一種全新的材料。"},{"en":"Completely novel ingredients can be exciting, but they may require extra safety testing.","zh":"全新成分令人興奮，但可能需要額外安全測試。"},{"en":"This phrase stresses newness more strongly than simply new.","zh":"這個短語比 simply new 更強調新穎性。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":15},{"front":"too complex or expensive to","meaning":"太複雜或太昂貴而不能……","examples":[{"en":"Some molecules may be too complex or expensive to make in the lab.","zh":"有些分子可能太複雜或太昂貴，不能在實驗室製造。"},{"en":"Too complex or expensive to do something means too difficult or costly to do practically.","zh":"too complex or expensive to do something 指實際上太困難或太高成本而難以做到。"},{"en":"A small school may find a new sports hall too expensive to build immediately.","zh":"小學校可能覺得新體育館太昂貴，不能立即興建。"},{"en":"If a process is too complex, companies may look for a simpler substitute.","zh":"如果過程太複雜，公司可能尋找較簡單的替代方法。"},{"en":"This phrase explains why an idea may not be practical.","zh":"這個短語解釋為何一個想法可能不實際。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":15},{"front":"make in the lab","meaning":"在實驗室製造","examples":[{"en":"Some fragrance molecules are difficult to make in the lab.","zh":"有些香氣分子很難在實驗室製造。"},{"en":"To make something in the lab means to produce it under controlled laboratory conditions.","zh":"make something in the lab 指在受控制的實驗室條件下製造某物。"},{"en":"Scientists can make some medicines in the lab instead of extracting them from plants.","zh":"科學家可以在實驗室製造某些藥物，而不是從植物中提取。"},{"en":"Lab production is useful when natural sources are rare, protected, or unreliable.","zh":"當天然來源罕見、受保護或不可靠時，實驗室製造很有用。"},{"en":"This phrase contrasts laboratory manufacture with natural collection.","zh":"這個短語把實驗室製造與天然採集作對比。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":15},{"front":"conjure up the fragrances","meaning":"調配出那些香氣","examples":[{"en":"The challenge is to conjure up the fragrances with available materials.","zh":"挑戰是用可用材料調配出那些香氣。"},{"en":"To conjure up the fragrances means to recreate or evoke the original smells.","zh":"conjure up the fragrances 指重現或喚起原本氣味。"},{"en":"A perfumer may conjure up the smell of a forest using wood, leaf, and earth notes.","zh":"香水師可能用木香、葉香和泥土調來調配出森林氣味。"},{"en":"If the real molecules cannot be used, similar materials must create the same impression.","zh":"如果不能使用真正分子，就必須用相似材料創造同樣印象。"},{"en":"This phrase focuses on producing the feeling of a scent, not copying every molecule.","zh":"這個短語聚焦製造氣味感覺，而不是複製每個分子。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":15},{"front":"readily available materials","meaning":"容易取得的材料","examples":[{"en":"Perfumers try to use readily available materials.","zh":"香水師嘗試使用容易取得的材料。"},{"en":"Readily available materials are materials that are easy to obtain and use.","zh":"readily available materials 指容易取得和使用的材料。"},{"en":"A teacher may design a craft activity using readily available materials like paper and string.","zh":"老師可能使用紙張和繩子等容易取得的材料設計手工活動。"},{"en":"Using available materials reduces cost, delay, and dependence on rare sources.","zh":"使用容易取得的材料可以減少成本、延誤和對罕見來源的依賴。"},{"en":"This phrase is useful in production, teaching, design, and research.","zh":"這個短語適用於生產、教學、設計和研究。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":15},{"front":"avoid the need to","meaning":"避免需要……","examples":[{"en":"The company can avoid the need to import rainforest plants.","zh":"公司可以避免需要進口雨林植物。"},{"en":"To avoid the need to do something means to prevent that action from being necessary.","zh":"avoid the need to do something 指使某行動不再必要。"},{"en":"A student can avoid the need to rush by starting homework early.","zh":"學生可以透過早點開始做功課，避免需要趕工。"},{"en":"If a scent can be recreated in the lab, companies avoid the need to collect rare plants.","zh":"如果氣味能在實驗室重現，公司就能避免需要採集罕見植物。"},{"en":"This phrase focuses on preventing an inconvenient or harmful requirement.","zh":"這個短語聚焦避免不方便或有害的需要。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":15},{"front":"import plants from","meaning":"從……進口植物","examples":[{"en":"The company wants to avoid importing plants from the rainforest.","zh":"公司想避免從雨林進口植物。"},{"en":"To import plants from a place means to bring plants from that place into another country or region.","zh":"import plants from a place 指把植物從某地帶入另一國家或地區。"},{"en":"A garden centre may import plants from warmer countries for customers.","zh":"園藝店可能從較溫暖國家進口植物給顧客。"},{"en":"Importing plants can be expensive and may raise conservation or legal concerns.","zh":"進口植物可能昂貴，並可能引起保育或法律問題。"},{"en":"This phrase describes movement of plants across places for use or sale.","zh":"這個短語描述植物跨地區移動以供使用或銷售。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":15},{"front":"original material","meaning":"原材料","examples":[{"en":"The new chemicals may differ from those in the original material.","zh":"新化學物可能與原材料中的化學物不同。"},{"en":"Original material is the natural or first source that something is based on.","zh":"original material 指某物所基於的天然或最初來源。"},{"en":"A copy of a painting may use different colours from the original material.","zh":"一幅畫的複製品可能使用與原作材料不同的顏色。"},{"en":"When replacing a natural ingredient, scientists compare the substitute with the original material.","zh":"取代天然成分時，科學家會把替代品與原材料比較。"},{"en":"This phrase is useful when comparing a source with a recreated version.","zh":"比較來源與重製版本時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":15},{"front":"get it right","meaning":"做對；成功掌握","examples":[{"en":"If they get it right, the sample will recreate the rainforest smell.","zh":"如果他們做對，樣本就會重現雨林氣味。"},{"en":"To get it right means to do something correctly or successfully.","zh":"get it right 指正確或成功地完成某事。"},{"en":"A student gets it right when the answer fits both the grammar and the meaning.","zh":"當答案同時符合文法和意思時，學生就是做對了。"},{"en":"In perfume making, getting it right may require many tests and adjustments.","zh":"在香水製作中，要成功掌握可能需要多次測試和調整。"},{"en":"This phrase is informal and often used when success depends on accuracy.","zh":"這個短語較非正式，常用於成功取決於準確性的情況。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":15},{"front":"sniff the sample","meaning":"聞一聞樣本","examples":[{"en":"You can sniff the sample and recall the rainforest.","zh":"你可以聞一聞樣本，然後想起雨林。"},{"en":"To sniff the sample means to smell a small amount carefully through the nose.","zh":"sniff the sample 指用鼻子仔細聞少量樣本。"},{"en":"A perfumer may sniff the sample several times before judging the scent.","zh":"香水師可能多次聞一聞樣本，才判斷氣味。"},{"en":"Sniffing helps people notice small differences between similar smells.","zh":"仔細嗅聞幫助人注意相似氣味之間的微小差異。"},{"en":"This phrase describes careful smelling, not casual breathing.","zh":"這個短語描述仔細聞，而不是隨意呼吸。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":16},{"front":"transport someone straight back to","meaning":"使某人立刻回到……的感覺","examples":[{"en":"The smell can transport you straight back to the rainforest.","zh":"這種氣味可以使你立刻回到雨林的感覺。"},{"en":"To transport someone straight back to a place means to make them feel as if they are there again.","zh":"transport someone straight back to a place 指令人感覺好像再次身處某地。"},{"en":"The smell of school lunch may transport an adult straight back to childhood.","zh":"學校午餐的氣味可能使成年人立刻回到童年。"},{"en":"Strong sensory memories can make the past feel immediate and vivid.","zh":"強烈感官記憶可以令過去感覺即時而鮮明。"},{"en":"This phrase is emotional and often used for smell, music, or memory.","zh":"這個短語帶有情感，常用於氣味、音樂或記憶。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":16},{"front":"the moment you smelt it","meaning":"你聞到它的那一刻","examples":[{"en":"The sample can take you back to the moment you smelt it.","zh":"樣本可以帶你回到你聞到它的那一刻。"},{"en":"The moment you smelt it means the exact time when you first noticed the smell.","zh":"the moment you smelt it 指你第一次注意到那種氣味的確切時刻。"},{"en":"A perfume can remind someone of the moment they smelt it on a holiday.","zh":"香水可以令人想起假期中聞到它的那一刻。"},{"en":"Strong smells often connect memory to a very specific time and place.","zh":"強烈氣味常把記憶與非常具體的時間和地點連接起來。"},{"en":"This phrase focuses on a precise sensory memory.","zh":"這個短語聚焦精確的感官記憶。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":16},{"front":"contains each of the following details","meaning":"包含以下每項細節","examples":[{"en":"The task asks which paragraph contains each of the following details.","zh":"題目問哪一段包含以下每項細節。"},{"en":"Contains each of the following details means includes the listed pieces of information.","zh":"contains each of the following details 指包含列出的每一項資料。"},{"en":"In a reading test, students must find which paragraph contains each detail about a person or event.","zh":"在閱讀測驗中，學生必須找出哪一段包含關於人物或事件的每項細節。"},{"en":"This task requires scanning for meaning, not reading only the first sentence.","zh":"這項任務需要掃讀意思，而不是只讀第一句。"},{"en":"This phrase is common in paragraph-matching questions.","zh":"這個短語常見於段落配對題。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":16},{"front":"use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"The instructions say that students may use any letter more than once.","zh":"指示說學生可重複使用任何字母。"},{"en":"Use any letter more than once means the same answer option can be chosen repeatedly.","zh":"use any letter more than once 指同一答案選項可以重複選用。"},{"en":"In a matching task, paragraph B may answer two different questions, so students use B more than once.","zh":"在配對題中，B 段可能回答兩條不同問題，所以學生可重複使用 B。"},{"en":"This rule prevents students from wrongly assuming every answer must be different.","zh":"這條規則防止學生錯誤地以為每個答案都必須不同。"},{"en":"This phrase is important in exam instructions.","zh":"這個短語在考試指示中很重要。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":16},{"front":"currently favoured place","meaning":"目前受青睞的地方","examples":[{"en":"Madagascar is a currently favoured place to seek novel plants.","zh":"馬達加斯加是目前受青睞的尋找新奇植物之地。"},{"en":"A currently favoured place is a place people presently prefer or choose for a purpose.","zh":"currently favoured place 指人們目前較喜歡或選擇用於某目的的地方。"},{"en":"A quiet library may be a currently favoured place for students during exam season.","zh":"考試季節期間，安靜圖書館可能是學生目前受青睞的地方。"},{"en":"A place becomes favoured when it offers special advantages at that time.","zh":"當某地方在當時提供特殊優勢，它就會受到青睞。"},{"en":"This phrase describes present preference, not permanent status.","zh":"這個短語描述目前偏好，而不是永久地位。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":16},{"front":"seek novel plants","meaning":"尋找新奇植物","examples":[{"en":"The company went to Madagascar to seek novel plants for fragrances.","zh":"這家公司前往馬達加斯加尋找用於香氣的新奇植物。"},{"en":"To seek novel plants means to look for new or unusual plant species.","zh":"seek novel plants 指尋找新或不尋常的植物物種。"},{"en":"Scientists may seek novel plants in remote forests to study their chemicals.","zh":"科學家可能在偏遠森林尋找新奇植物，以研究其化學物。"},{"en":"Novel plants can lead to new medicines, materials, or fragrances.","zh":"新奇植物可以帶來新藥物、材料或香氣。"},{"en":"This phrase suggests purposeful scientific searching.","zh":"這個短語表示有目的的科學搜尋。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":16},{"front":"promising new undertaking","meaning":"有前景的新嘗試","examples":[{"en":"Capturing coral smells was a promising new undertaking.","zh":"捕捉珊瑚氣味是一項有前景的新嘗試。"},{"en":"A promising new undertaking is a new project that seems likely to produce useful results.","zh":"promising new undertaking 指看起來可能產生有用結果的新項目。"},{"en":"A school’s new reading club may be a promising new undertaking if students join eagerly.","zh":"如果學生踴躍參加，學校的新閱讀會可能是一項有前景的新嘗試。"},{"en":"Early success can encourage people to continue a new undertaking.","zh":"早期成功可以鼓勵人們繼續新嘗試。"},{"en":"This phrase suggests hope and potential in a new effort.","zh":"這個短語表示新努力中的希望和潛力。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":16},{"front":"limited existing fragrance sources","meaning":"現有香氣來源有限","examples":[{"en":"The ocean offers limited existing fragrance sources.","zh":"海洋提供的現有香氣來源有限。"},{"en":"Limited existing fragrance sources means there are only a few known places or materials for getting certain smells.","zh":"limited existing fragrance sources 指已知可取得某些氣味的地方或材料很少。"},{"en":"If a product has limited ingredient sources, companies may search for substitutes.","zh":"如果產品的成分來源有限，公司可能尋找替代品。"},{"en":"Limited sources make new discoveries more valuable.","zh":"來源有限會令新發現更有價值。"},{"en":"This phrase explains why researchers look for fresh materials.","zh":"這個短語解釋研究人員為何尋找新材料。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":16},{"front":"demanding conditions","meaning":"苛刻條件","examples":[{"en":"Modern fragrances must withstand demanding conditions.","zh":"現代香氣必須承受苛刻條件。"},{"en":"Demanding conditions are difficult situations that require strength, stability, or high performance.","zh":"demanding conditions 指需要強度、穩定性或高表現的困難情況。"},{"en":"Outdoor workers face demanding conditions during storms or extreme heat.","zh":"戶外工人在暴風雨或極端高溫中面對苛刻條件。"},{"en":"Products used in demanding conditions must be tested carefully before sale.","zh":"在苛刻條件下使用的產品，出售前必須仔細測試。"},{"en":"This phrase is useful when something must perform under pressure.","zh":"當某物必須在壓力下表現良好時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":16},{"front":"must withstand","meaning":"必須承受","examples":[{"en":"Fragrances must withstand bleach and high-temperature washing.","zh":"香氣必須承受漂白劑和高溫洗衣。"},{"en":"Must withstand means must resist damage or remain effective under difficult conditions.","zh":"must withstand 指必須抵抗損害，或在困難條件下保持有效。"},{"en":"A school bag must withstand heavy books and daily use.","zh":"書包必須承受沉重書本和日常使用。"},{"en":"If a material cannot withstand stress, it may break or fail quickly.","zh":"如果材料不能承受壓力，它可能很快破裂或失效。"},{"en":"This phrase is used when durability is necessary.","zh":"當耐用性必要時，會使用這個短語。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":16},{"front":"substitute for","meaning":"……的替代品","examples":[{"en":"The Calophyllum sap may provide a substitute for castoreum.","zh":"胡桐樹液可能提供海狸香的替代品。"},{"en":"A substitute for something is a replacement that can be used instead of it.","zh":"substitute for something 指可以用來代替某物的替代物。"},{"en":"Plant milk can be a substitute for cow’s milk for some people.","zh":"對有些人來說，植物奶可以是牛奶的替代品。"},{"en":"A good substitute solves the same problem without the same disadvantages.","zh":"好替代品能解決同一問題，而沒有相同缺點。"},{"en":"This phrase is useful when an original material is unavailable, expensive, or unacceptable.","zh":"當原材料不可得、昂貴或不可接受時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":17},{"front":"no longer used by","meaning":"不再被……使用","examples":[{"en":"Castoreum is no longer used by some perfumers.","zh":"海狸香不再被一些香水師使用。"},{"en":"No longer used by someone means that they used it in the past but do not use it now.","zh":"no longer used by someone 指某人過去使用某物，但現在不再使用。"},{"en":"Paper forms are no longer used by some banks because customers apply online.","zh":"有些銀行不再使用紙本表格，因為顧客在網上申請。"},{"en":"A material may stop being used because of cost, safety, ethics, or new substitutes.","zh":"材料可能因成本、安全、道德或新替代品而停止被使用。"},{"en":"This phrase shows a change in practice over time.","zh":"這個短語顯示做法隨時間改變。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":17},{"front":"land expedition","meaning":"陸地考察","examples":[{"en":"The passage describes a land expedition seeking new scents.","zh":"文章描述了一次尋找新香氣的陸地考察。"},{"en":"A land expedition is a research or exploration trip carried out on land.","zh":"land expedition 指在陸地上進行的研究或探索旅程。"},{"en":"A land expedition may cross forests, deserts, mountains, or islands.","zh":"陸地考察可能穿越森林、沙漠、山區或島嶼。"},{"en":"Land expeditions need walking routes, supplies, maps, and safety planning.","zh":"陸地考察需要步行路線、補給、地圖和安全計劃。"},{"en":"This phrase contrasts land-based exploration with underwater or sea work.","zh":"這個短語把陸上探索與水下或海上工作作對比。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":17},{"front":"seeking new scents","meaning":"尋找新香氣","examples":[{"en":"The expedition spent days seeking new scents in the rainforest.","zh":"考察隊花了幾天在雨林中尋找新香氣。"},{"en":"Seeking new scents means looking for smells that have not been used or studied before.","zh":"seeking new scents 指尋找以前未被使用或研究過的氣味。"},{"en":"A candle company may send designers to markets seeking new scents from spices and flowers.","zh":"蠟燭公司可能派設計師到市場，從香料和花朵中尋找新香氣。"},{"en":"Finding new scents can help products feel original and memorable.","zh":"找到新香氣可以令產品感覺原創和難忘。"},{"en":"This phrase describes an active search for smell ideas.","zh":"這個短語描述主動尋找氣味靈感。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":17},{"front":"agree with the information given","meaning":"與所給資料一致","examples":[{"en":"Students decide whether the statements agree with the information given.","zh":"學生判斷陳述是否與所給資料一致。"},{"en":"To agree with the information given means to match what the passage says.","zh":"agree with the information given 指與文章所說內容相符。"},{"en":"In a reading test, students must check whether a statement agrees with the text, not with their own opinion.","zh":"在閱讀測驗中，學生必須檢查陳述是否與文本一致，而不是是否符合個人意見。"},{"en":"If the wording changes the meaning, the statement may not agree with the information.","zh":"如果用字改變意思，陳述可能不與資料一致。"},{"en":"This phrase is common in True, False, Not Given questions.","zh":"這個短語常見於 True, False, Not Given 題。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":17},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與文章中的資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the passage says.","zh":"contradict the information 指說出與文章內容相反的意思。"},{"en":"If a text says the team used borrowed technology, an answer saying they invented it entirely would contradict the information.","zh":"如果文本說團隊使用借用技術，而答案說他們完全自己發明，就與資料相矛盾。"},{"en":"Contradiction is different from no information; it directly conflicts with the source.","zh":"矛盾不同於沒有資料；它是直接與來源衝突。"},{"en":"This phrase helps students identify false answers.","zh":"這個短語幫助學生辨認錯誤答案。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":17},{"front":"no information on this","meaning":"沒有這方面的資料","examples":[{"en":"Write NOT GIVEN if there is no information on this.","zh":"如果沒有這方面的資料，寫 NOT GIVEN。"},{"en":"No information on this means the passage does not say whether the statement is true or false.","zh":"no information on this 指文章沒有說明該陳述是真還是假。"},{"en":"If the text describes a plant’s smell but not its price, there is no information on the price.","zh":"如果文本描述植物氣味，但沒有描述價格，就沒有這方面的價格資料。"},{"en":"Students should not guess when the passage gives no information on this.","zh":"當文章沒有這方面的資料時，學生不應猜測。"},{"en":"This phrase is important for avoiding unsupported answers.","zh":"這個短語對避免無根據答案很重要。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":17},{"front":"manufacturers","meaning":"製造商","examples":[{"en":"Manufacturers can now choose synthetic odours for perfumes.","zh":"製造商現在可以為香水選擇合成氣味。"},{"en":"Manufacturers are companies or people who produce goods in quantity.","zh":"manufacturers 指大量生產商品的公司或人士。"},{"en":"A soap manufacturer may buy fragrance ingredients before making a new product.","zh":"肥皂製造商可能在製作新產品前購買香氣成分。"},{"en":"Manufacturers choose materials based on cost, safety, supply, and customer demand.","zh":"製造商根據成本、安全、供應和顧客需求選擇材料。"},{"en":"This word is common in business and production contexts.","zh":"這個詞常見於商業和生產語境。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":17},{"front":"synthetic odours","meaning":"合成氣味","examples":[{"en":"Manufacturers can use synthetic odours in perfumes.","zh":"製造商可以在香水中使用合成氣味。"},{"en":"Synthetic odours are human-made smells created from chemical compounds.","zh":"synthetic odours 指由化學化合物製造的人造氣味。"},{"en":"A detergent may use synthetic odours to smell like flowers or fresh air.","zh":"洗衣劑可能使用合成氣味，使其聞起來像花或清新空氣。"},{"en":"Synthetic odours can replace rare natural smells and reduce pressure on plants or animals.","zh":"合成氣味可以取代罕見天然氣味，並減少對植物或動物的壓力。"},{"en":"This phrase contrasts artificial smells with natural odours.","zh":"這個短語把人造氣味與天然氣味作對比。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":17},{"front":"rare elsewhere in the world","meaning":"在世界其他地方罕見","examples":[{"en":"Many plants in Madagascar are rare elsewhere in the world.","zh":"馬達加斯加的許多植物在世界其他地方罕見。"},{"en":"Rare elsewhere in the world means uncommon or difficult to find in other places.","zh":"rare elsewhere in the world 指在其他地方不常見或難以找到。"},{"en":"A local fruit may be common in one island but rare elsewhere in the world.","zh":"一種本地水果可能在某島很常見，但在世界其他地方罕見。"},{"en":"If a species is rare elsewhere, protecting its habitat becomes more important.","zh":"如果某物種在其他地方罕見，保護其棲息地就更重要。"},{"en":"This phrase explains why a particular place may attract researchers.","zh":"這個短語解釋為何某地會吸引研究人員。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":17},{"front":"capturing a smell","meaning":"捕捉氣味","examples":[{"en":"Capturing a smell is an important step in creating new aromas.","zh":"捕捉氣味是創造新香氣的重要一步。"},{"en":"Capturing a smell means collecting scent molecules so the smell can be studied or recreated.","zh":"capturing a smell 指收集香氣分子，使氣味能被研究或重現。"},{"en":"A researcher may capture a smell from a flower using a jar and filters.","zh":"研究人員可能用罩和過濾器從花朵捕捉氣味。"},{"en":"Without capturing the smell, perfumers may rely only on memory or description.","zh":"如果沒有捕捉氣味，香水師可能只能依靠記憶或描述。"},{"en":"This phrase describes the first step before analysis and reproduction.","zh":"這個短語描述分析和重製之前的第一步。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":17},{"front":"creating new aromas","meaning":"創造新香氣","examples":[{"en":"Perfumers need captured smells when creating new aromas.","zh":"香水師在創造新香氣時需要已捕捉的氣味。"},{"en":"Creating new aromas means making new pleasant smells by mixing or copying scent molecules.","zh":"creating new aromas 指透過混合或複製香氣分子來製造新的宜人氣味。"},{"en":"A candle brand may spend months creating new aromas for winter products.","zh":"蠟燭品牌可能花幾個月為冬季產品創造新香氣。"},{"en":"New aromas can attract customers who want something different from familiar scents.","zh":"新香氣可以吸引想要不同於熟悉氣味的顧客。"},{"en":"This phrase focuses on smell design and invention.","zh":"這個短語聚焦氣味設計和發明。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":18},{"front":"fragrance-trapping technique","meaning":"香氣捕捉技術","examples":[{"en":"The fragrance-trapping technique was adapted from pollution monitoring.","zh":"香氣捕捉技術改編自污染監測。"},{"en":"A fragrance-trapping technique is a method used to capture scent molecules for study.","zh":"fragrance-trapping technique 指用來捕捉香氣分子以供研究的方法。"},{"en":"Scientists may use a fragrance-trapping technique on a rare flower without damaging it.","zh":"科學家可能在不損害罕見花朵的情況下使用香氣捕捉技術。"},{"en":"Trapping scent first allows later laboratory analysis.","zh":"先捕捉香氣，才可以之後在實驗室分析。"},{"en":"This phrase describes the method used before recreating a smell.","zh":"這個短語描述重現氣味之前使用的方法。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":18},{"front":"entirely their own invention","meaning":"完全由他們自己發明","examples":[{"en":"The technique was not entirely their own invention.","zh":"這項技術並不是完全由他們自己發明。"},{"en":"Entirely their own invention means created completely by them, without borrowing from others.","zh":"entirely their own invention 指完全由他們創造，沒有借用他人想法。"},{"en":"A student’s project is not entirely her own invention if she adapts an idea from a textbook.","zh":"如果學生從教科書改編一個想法，她的項目就不是完全由自己發明。"},{"en":"Many useful methods are improved from earlier inventions rather than created from nothing.","zh":"許多有用方法是從早期發明改進而來，而不是從零創造。"},{"en":"This phrase is useful when discussing originality and borrowing.","zh":"討論原創性和借用時，這個短語很有用。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":18},{"front":"substances extracted from","meaning":"從……提取的物質","examples":[{"en":"Some traditional perfume ingredients were substances extracted from animals.","zh":"有些傳統香水成分是從動物提取的物質。"},{"en":"Substances extracted from something are materials taken out of a source.","zh":"substances extracted from something 指從某來源取出的材料。"},{"en":"Essential oils are substances extracted from plants such as lavender or mint.","zh":"精油是從薰衣草或薄荷等植物提取的物質。"},{"en":"Extracted substances may be useful, but their source can raise ethical or environmental questions.","zh":"提取物質可能有用，但其來源可能引起道德或環境問題。"},{"en":"This phrase explains where a material comes from.","zh":"這個短語解釋材料來自哪裡。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":18},{"front":"animals’ musk glands","meaning":"動物麝香腺","examples":[{"en":"Castoreum was extracted from animals’ musk glands.","zh":"海狸香是從動物麝香腺提取的。"},{"en":"Animals’ musk glands are scent-producing glands found in some animals.","zh":"animals’ musk glands 指某些動物身上產生氣味的腺體。"},{"en":"Some animals use musk glands to communicate, attract mates, or mark territory.","zh":"有些動物使用麝香腺溝通、吸引配偶或標記領地。"},{"en":"Ingredients from animals’ musk glands were once valued for strong and lasting smells.","zh":"來自動物麝香腺的成分曾因濃烈而持久的氣味而有價值。"},{"en":"This phrase is connected with animal-derived fragrance materials.","zh":"這個短語與動物來源香氣材料有關。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":18},{"front":"complete the diagram below","meaning":"完成下方圖表","examples":[{"en":"Students must complete the diagram below using words from the passage.","zh":"學生必須使用文章中的詞語完成下方圖表。"},{"en":"Complete the diagram below means fill in the missing labels or steps in the diagram.","zh":"complete the diagram below 指填入圖表中缺失的標籤或步驟。"},{"en":"In a science reading task, students may complete the diagram below with equipment names.","zh":"在科學閱讀任務中，學生可能用設備名稱完成下方圖表。"},{"en":"This task checks whether students understand a process and its sequence.","zh":"這項任務檢查學生是否理解過程及其順序。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":18},{"front":"one word only","meaning":"只限一個詞","examples":[{"en":"The instructions require one word only from the passage.","zh":"指示要求只限使用文章中的一個詞。"},{"en":"One word only means the answer must contain exactly one word.","zh":"one word only 指答案必須只包含一個詞。"},{"en":"If the answer is filters, it follows the rule of one word only.","zh":"如果答案是 filters，就符合只限一個詞的規則。"},{"en":"Writing two words can lose marks even if the idea is correct.","zh":"即使意思正確，寫兩個詞也可能失分。"},{"en":"This phrase controls answer length in reading tests.","zh":"這個短語控制閱讀測驗中的答案長度。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":18},{"front":"from the passage","meaning":"來自文章","examples":[{"en":"The answers must be chosen from the passage.","zh":"答案必須來自文章。"},{"en":"From the passage means taken directly from the reading text, not invented by the student.","zh":"from the passage 指直接取自閱讀文章，而不是由學生自己創作。"},{"en":"In a reading exam, students should copy the exact word from the passage when instructed.","zh":"在閱讀考試中，當題目要求時，學生應抄寫文章中的確切詞語。"},{"en":"Using words outside the passage may be wrong even if they have a similar meaning.","zh":"使用文章以外的詞，即使意思相近，也可能錯。"},{"en":"This phrase reminds students to base answers on textual evidence.","zh":"這個短語提醒學生答案要基於文本證據。"}],"source":"126 - Hunting Perfume in Madagascar.pdf","sourcePage":18}],"ielts/reading/passage-2/Practice 127":[{"front":"New Ways of Teaching History","meaning":"教授歷史的新方法","examples":[{"en":"The passage discusses new ways of teaching history in a digital age.","zh":"文章討論在數碼時代教授歷史的新方法。"},{"en":"New ways of teaching history are fresh methods that help students learn about the past more effectively.","zh":"教授歷史的新方法，是幫助學生更有效學習過去的新鮮教學方式。"},{"en":"A teacher may use videos, maps, games, and online archives as new ways of teaching history.","zh":"老師可能使用影片、地圖、遊戲和網上檔案作為教授歷史的新方法。"},{"en":"New ways of teaching history can make old events feel closer to students’ lives.","zh":"教授歷史的新方法可以令舊事件感覺更貼近學生生活。"},{"en":"These methods should support historical thinking, not replace careful reading and evidence.","zh":"這些方法應支持歷史思考，而不是取代仔細閱讀和證據。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":1},{"front":"technology- and media-driven world","meaning":"科技和媒體主導的世界","examples":[{"en":"In today’s technology- and media-driven world, teachers face new classroom challenges.","zh":"在今天科技和媒體主導的世界中，老師面對新的課堂挑戰。"},{"en":"A technology- and media-driven world is a society strongly shaped by digital tools, screens, and online information.","zh":"科技和媒體主導的世界，是指深受數碼工具、螢幕和網上資訊塑造的社會。"},{"en":"In a technology- and media-driven world, students may expect lessons to include images, sound, and interaction.","zh":"在科技和媒體主導的世界中，學生可能期望課堂包含圖像、聲音和互動。"},{"en":"This world can make learning faster, but it can also make attention harder to keep.","zh":"這個世界可以令學習更快，但也可以令注意力更難維持。"},{"en":"Teachers need to adapt because students’ daily habits are shaped by media outside school.","zh":"老師需要適應，因為學生在校外的日常習慣受到媒體塑造。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":1},{"front":"increasingly difficult to","meaning":"越來越難去……","examples":[{"en":"It is becoming increasingly difficult to get students’ attention.","zh":"吸引學生注意正變得越來越難。"},{"en":"Increasingly difficult to means becoming harder and harder to do something.","zh":"increasingly difficult to 是指做某事變得越來越困難。"},{"en":"It is increasingly difficult to study quietly when phones keep sending notifications.","zh":"當手機不斷發出通知時，安靜溫習變得越來越難。"},{"en":"A city may find it increasingly difficult to control traffic as car numbers rise.","zh":"隨著車輛數量上升，城市可能越來越難控制交通。"},{"en":"This phrase shows that the problem is growing over time.","zh":"這個短語顯示問題正隨時間加劇。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":1},{"front":"get students’ attention","meaning":"吸引學生注意","examples":[{"en":"Teachers often struggle to get students’ attention.","zh":"老師常常難以吸引學生注意。"},{"en":"To get students’ attention means to make students notice, listen, and focus on the lesson.","zh":"get students’ attention 是指令學生留意、聆聽並集中於課堂。"},{"en":"A teacher may use a surprising photo to get students’ attention at the start of class.","zh":"老師可能在課堂開始時使用一張令人驚訝的照片來吸引學生注意。"},{"en":"If students are tired or distracted, it becomes harder to get their attention.","zh":"如果學生疲倦或分心，要吸引他們注意就會更困難。"},{"en":"Getting students’ attention is only the first step; teachers must also keep them engaged.","zh":"吸引學生注意只是第一步；老師還要令他們持續投入。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":1},{"front":"keep them absorbed in","meaning":"令他們投入於……","examples":[{"en":"Teachers want to keep students absorbed in classroom discussions.","zh":"老師希望令學生投入於課堂討論。"},{"en":"To keep someone absorbed in something means to keep them deeply interested and focused on it.","zh":"keep someone absorbed in something 是指令某人深感興趣並集中於某事。"},{"en":"A good story can keep children absorbed in reading for a long time.","zh":"好故事可以令孩子長時間投入於閱讀。"},{"en":"Interactive tasks keep students absorbed in a lesson because they have to think and respond.","zh":"互動任務令學生投入於課堂，因為他們必須思考和回應。"},{"en":"If an activity is too passive, it may fail to keep learners absorbed.","zh":"如果活動太被動，可能無法令學習者投入。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":1},{"front":"classroom discussions","meaning":"課堂討論","examples":[{"en":"Technology can help students take part in classroom discussions.","zh":"科技可以幫助學生參與課堂討論。"},{"en":"Classroom discussions are conversations in class where students share ideas, questions, and opinions.","zh":"課堂討論是學生在課堂中分享想法、問題和意見的對話。"},{"en":"In classroom discussions, students learn to listen, disagree politely, and support answers with evidence.","zh":"在課堂討論中，學生學會聆聽、禮貌地不同意，並用證據支持答案。"},{"en":"Good classroom discussions can make quiet students more confident over time.","zh":"良好的課堂討論可以隨時間令安靜學生更有信心。"},{"en":"Digital tools can support classroom discussions by showing images, questions, or short videos.","zh":"數碼工具可以透過展示圖片、問題或短片來支持課堂討論。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":1},{"front":"this generation","meaning":"這一代","examples":[{"en":"This generation has brought new challenges to education.","zh":"這一代為教育帶來了新挑戰。"},{"en":"This generation means the group of young people living and learning in the present period.","zh":"this generation 是指在當前時期生活和學習的年輕人群體。"},{"en":"This generation often grows up with phones, videos, games, and instant information.","zh":"這一代通常伴隨手機、影片、遊戲和即時資訊成長。"},{"en":"Because this generation learns differently, teachers may need to change classroom methods.","zh":"因為這一代學習方式不同，老師可能需要改變課堂方法。"},{"en":"Talking about this generation helps compare today’s students with earlier learners.","zh":"談及這一代，有助比較今天學生與較早期學習者。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":1},{"front":"in particular","meaning":"尤其是","examples":[{"en":"This generation, in particular, has brought challenges to the educational table.","zh":"尤其是這一代，為教育議題帶來了挑戰。"},{"en":"In particular means especially or more specifically than others.","zh":"in particular 是指尤其是，或比其他事物更具體地說。"},{"en":"Many subjects are difficult, but history, in particular, can feel distant to students.","zh":"許多科目都困難，但歷史尤其可能令學生感到遙遠。"},{"en":"A teacher may focus on weak vocabulary, in particular, before an exam.","zh":"老師可能在考試前尤其集中處理薄弱詞彙。"},{"en":"This phrase highlights one item from a wider group.","zh":"這個短語從較大群組中突出某一項。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":1},{"front":"a unique set of challenges","meaning":"一套獨特挑戰","examples":[{"en":"Digital learners have brought a unique set of challenges to the classroom.","zh":"數碼學習者為課室帶來了一套獨特挑戰。"},{"en":"A unique set of challenges means a special group of difficulties that is different from previous problems.","zh":"a unique set of challenges 是指一組不同於以往問題的特殊困難。"},{"en":"Teaching online brings a unique set of challenges, such as unstable internet and low interaction.","zh":"網上教學帶來一套獨特挑戰，例如網絡不穩和互動少。"},{"en":"A new school may face a unique set of challenges because its students come from many backgrounds.","zh":"新學校可能面對一套獨特挑戰，因為學生來自許多背景。"},{"en":"This phrase suggests that old solutions may not fully solve the new problems.","zh":"這個短語暗示舊方法未必能完全解決新問題。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":1},{"front":"to the educational table","meaning":"帶到教育議題上","examples":[{"en":"This generation has brought new issues to the educational table.","zh":"這一代把新問題帶到教育議題上。"},{"en":"To bring something to the educational table means to introduce it into discussions about education.","zh":"bring something to the educational table 是指把某事引入教育討論之中。"},{"en":"Smartphones have brought new questions about attention to the educational table.","zh":"智能手機把關於注意力的新問題帶到教育議題上。"},{"en":"Mental health concerns have brought student wellbeing to the educational table.","zh":"心理健康關注把學生福祉帶到教育議題上。"},{"en":"This phrase treats education as a place where problems are discussed and decisions are made.","zh":"這個短語把教育視為一個討論問題和作出決定的地方。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":1},{"front":"whereas","meaning":"然而；相比之下","examples":[{"en":"Whereas students enjoy digital media, they may dislike traditional textbooks.","zh":"學生喜歡數碼媒體，然而他們可能不喜歡傳統教科書。"},{"en":"Whereas is used to contrast two different facts or situations.","zh":"whereas 用於對比兩個不同事實或情況。"},{"en":"Some students learn well through pictures, whereas others prefer reading quietly.","zh":"有些學生透過圖片學得好，相比之下，另一些學生偏好安靜閱讀。"},{"en":"A small shop offers personal service, whereas a large chain may offer lower prices.","zh":"小店提供個人化服務，而大型連鎖店可能提供較低價格。"},{"en":"This word helps show a clear difference between two sides.","zh":"這個詞有助顯示兩方面的清楚差異。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":1},{"front":"easily enraptured by","meaning":"容易被……吸引","examples":[{"en":"Young people are easily enraptured by high-definition television and video games.","zh":"年輕人容易被高清電視和電子遊戲吸引。"},{"en":"To be easily enraptured by something means to be quickly fascinated or deeply attracted by it.","zh":"easily enraptured by 是指很快被某事迷住或深深吸引。"},{"en":"Children may be easily enraptured by bright animation and exciting music.","zh":"孩子可能容易被鮮明動畫和刺激音樂吸引。"},{"en":"Students are harder to teach if entertainment easily enraptures them more than textbooks do.","zh":"如果娛樂比教科書更容易吸引學生，教學就更困難。"},{"en":"This phrase suggests strong attraction, not just mild interest.","zh":"這個短語暗示強烈吸引，而不只是輕微興趣。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":2},{"front":"high-definition television","meaning":"高清電視","examples":[{"en":"High-definition television is one example of modern media.","zh":"高清電視是現代媒體的一個例子。"},{"en":"High-definition television shows images with clear detail and sharp quality.","zh":"高清電視以清晰細節和銳利畫質顯示影像。"},{"en":"Students used to watching high-definition television may expect classroom visuals to be clear and attractive.","zh":"習慣觀看高清電視的學生，可能期望課堂視覺材料清楚且吸引。"},{"en":"Clear images can hold attention, but they do not automatically create deep learning.","zh":"清晰影像可以維持注意力，但不會自動產生深度學習。"},{"en":"The phrase represents modern visual media that competes with older classroom materials.","zh":"這個短語代表與較舊課堂材料競爭的現代視覺媒體。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":2},{"front":"less than enthralled by","meaning":"對……並不着迷","examples":[{"en":"Many students are less than enthralled by old textbooks.","zh":"許多學生對舊教科書並不着迷。"},{"en":"Less than enthralled by means not very interested, excited, or impressed by something.","zh":"less than enthralled by 是指對某事不太感興趣、不興奮或印象不深。"},{"en":"Children may be less than enthralled by a long lecture with no examples.","zh":"如果講課很長又沒有例子，孩子可能對它並不着迷。"},{"en":"Workers are less than enthralled by training if it repeats information they already know.","zh":"如果培訓重複員工已知道的資訊，他們會對它並不着迷。"},{"en":"This phrase politely suggests boredom or weak interest.","zh":"這個短語較委婉地表示沉悶或興趣不大。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":2},{"front":"obsolete textbooks","meaning":"過時的教科書","examples":[{"en":"Some students see traditional textbooks as obsolete textbooks.","zh":"有些學生把傳統教科書視為過時的教科書。"},{"en":"Obsolete textbooks are textbooks that seem outdated, old-fashioned, or no longer suitable for current learning needs.","zh":"過時的教科書是看起來落伍、老派或不再適合當前學習需要的教科書。"},{"en":"A science textbook becomes obsolete if it ignores major new discoveries.","zh":"如果科學教科書忽略重大新發現，它就會變成過時的教科書。"},{"en":"Obsolete textbooks can make students feel that school is disconnected from modern life.","zh":"過時的教科書會令學生覺得學校與現代生活脫節。"},{"en":"A textbook is not obsolete just because it is printed; it becomes obsolete when its content or method no longer works.","zh":"教科書不會只因為是印刷品就過時；當內容或方法不再有效時，才算過時。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":2},{"front":"boring classroom lectures","meaning":"沉悶的課堂講授","examples":[{"en":"Students may find traditional classroom lectures boring.","zh":"學生可能覺得傳統課堂講授很沉悶。"},{"en":"Boring classroom lectures are lessons where students mainly listen passively and feel little interest.","zh":"沉悶的課堂講授是學生主要被動聆聽且興趣不大的課堂。"},{"en":"A long lecture with no images, questions, or examples may become boring for many students.","zh":"沒有圖像、問題或例子的長講課，對許多學生可能變得沉悶。"},{"en":"Boring classroom lectures can reduce attention and make students remember less.","zh":"沉悶的課堂講授會降低注意力，令學生記得更少。"},{"en":"Teachers can improve lectures by adding stories, discussion, and clear visual support.","zh":"老師可以加入故事、討論和清晰視覺支援來改善講授。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":2},{"front":"in a digital age","meaning":"在數碼時代","examples":[{"en":"Teachers must consider how to teach history in a digital age.","zh":"老師必須考慮如何在數碼時代教授歷史。"},{"en":"In a digital age means in a time when computers, the internet, and media technology shape daily life.","zh":"in a digital age 是指在電腦、互聯網和媒體科技塑造日常生活的時代。"},{"en":"In a digital age, students often search for information online before opening a textbook.","zh":"在數碼時代，學生常在打開教科書前先上網搜尋資訊。"},{"en":"Schools must teach source checking because false information spreads quickly in a digital age.","zh":"學校必須教授資料核查，因為假資訊在數碼時代傳播很快。"},{"en":"This phrase explains why education cannot ignore technology.","zh":"這個短語解釋了為何教育不能忽視科技。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":2},{"front":"contentious","meaning":"具爭議性的","examples":[{"en":"The question of digital technology in history teaching is often contentious.","zh":"數碼科技在歷史教學中的問題常具爭議性。"},{"en":"Contentious means likely to cause disagreement or argument.","zh":"contentious 是指很可能引起分歧或爭論。"},{"en":"School uniform rules can be contentious when students and parents have different views.","zh":"當學生和家長有不同看法時，校服規則可能具爭議性。"},{"en":"A contentious policy may need public discussion before it is introduced.","zh":"具爭議性的政策在推出前可能需要公開討論。"},{"en":"Technology in education is contentious because people disagree about its benefits and risks.","zh":"教育中的科技具爭議性，因為人們對其好處和風險有分歧。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":2},{"front":"on the one side","meaning":"一方面","examples":[{"en":"On the one side, some historians worry about digital technology.","zh":"一方面，有些歷史學家擔心數碼科技。"},{"en":"On the one side introduces one viewpoint in a debate with two or more positions.","zh":"on the one side 用來引入辯論中其中一個觀點。"},{"en":"On the one side, parents want more homework; on the other side, students need rest.","zh":"一方面，家長想要更多功課；另一方面，學生需要休息。"},{"en":"This phrase helps writers organise contrasting opinions clearly.","zh":"這個短語幫助作者清楚組織相反意見。"},{"en":"It often prepares readers for “on the other side” later.","zh":"它通常為後面的 “on the other side” 作準備。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":2},{"front":"the old guard","meaning":"守舊派","examples":[{"en":"The old guard fears that digital tools may damage serious historical study.","zh":"守舊派擔心數碼工具可能損害嚴肅的歷史研究。"},{"en":"The old guard means traditional people in a field who resist new ideas or methods.","zh":"the old guard 是指某領域中抗拒新思想或新方法的傳統人士。"},{"en":"In some schools, the old guard prefers chalkboards and printed notes to online platforms.","zh":"在有些學校，守舊派偏好黑板和印刷筆記，而不是網上平台。"},{"en":"The old guard may protect valuable standards, but it may also slow useful change.","zh":"守舊派可能保護有價值的標準，但也可能拖慢有用改變。"},{"en":"This phrase can sound slightly critical because it suggests resistance to innovation.","zh":"這個短語可能帶有少許批評意味，因為它暗示抗拒創新。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":2},{"front":"the professional study of history","meaning":"對歷史的專業研究","examples":[{"en":"Some people worry about the professional study of history.","zh":"有些人擔心對歷史的專業研究。"},{"en":"The professional study of history means serious academic research into the past using evidence and methods.","zh":"對歷史的專業研究，是指使用證據和方法對過去進行嚴肅學術研究。"},{"en":"Universities support the professional study of history through archives, seminars, and research training.","zh":"大學透過檔案、研討會和研究訓練支持對歷史的專業研究。"},{"en":"Digital tools can help the professional study of history if they improve access to sources.","zh":"如果數碼工具改善資料來源的可及性，它們可以幫助對歷史的專業研究。"},{"en":"The phrase is different from casual interest in history because it implies expert work.","zh":"這個短語不同於對歷史的一般興趣，因為它暗示專家工作。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":2},{"front":"in mortal danger","meaning":"處於致命危險中","examples":[{"en":"The old guard thinks historical study is in mortal danger.","zh":"守舊派認為歷史研究處於致命危險中。"},{"en":"In mortal danger means facing a very serious threat that could destroy or severely harm something.","zh":"in mortal danger 是指面對可能摧毀或嚴重傷害某事物的嚴重威脅。"},{"en":"A language may be in mortal danger if only a few elderly speakers remain.","zh":"如果只剩少數年長使用者，一種語言可能處於致命危險中。"},{"en":"A small business is in mortal danger when debts rise and customers disappear.","zh":"當債務上升且顧客消失，小企業就處於致命危險中。"},{"en":"The phrase is dramatic and suggests extreme fear about the future.","zh":"這個短語很戲劇化，暗示對未來的極大恐懼。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":2},{"front":"flash-in-the-pan challenges","meaning":"曇花一現的挑戰","examples":[{"en":"Some critics dismiss digital technology as a flash-in-the-pan challenge.","zh":"有些批評者把數碼科技視為曇花一現的挑戰而不予理會。"},{"en":"A flash-in-the-pan challenge is a problem or trend that seems exciting or worrying but disappears quickly.","zh":"曇花一現的挑戰，是看似令人興奮或擔心，但很快消失的問題或潮流。"},{"en":"A school should not redesign everything for a flash-in-the-pan trend without evidence.","zh":"學校不應在沒有證據下為曇花一現的潮流重新設計所有東西。"},{"en":"Some apps become popular for a month and then vanish, proving they were flash-in-the-pan tools.","zh":"有些應用程式流行一個月後便消失，證明它們只是曇花一現的工具。"},{"en":"The phrase suggests something temporary rather than deeply important.","zh":"這個短語暗示某事是短暫的，而不是深層重要的。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":3},{"front":"all show and no substance","meaning":"華而不實","examples":[{"en":"Critics say some digital technology is all show and no substance.","zh":"批評者說有些數碼科技華而不實。"},{"en":"All show and no substance means something looks impressive but has little real value or depth.","zh":"all show and no substance 是指某事看起來令人印象深刻，但幾乎沒有真正價值或深度。"},{"en":"A beautiful presentation with no clear ideas is all show and no substance.","zh":"一份漂亮但沒有清晰想法的簡報是華而不實。"},{"en":"A lesson becomes all show and no substance if videos entertain students but teach them nothing.","zh":"如果影片只娛樂學生卻沒有教到任何東西，課堂就變得華而不實。"},{"en":"This phrase warns that appearance should not replace real learning.","zh":"這個短語提醒人們，外觀不應取代真正學習。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":3},{"front":"on the other side","meaning":"另一方面","examples":[{"en":"On the other side, supporters claim that technology has changed everything.","zh":"另一方面，支持者聲稱科技已改變一切。"},{"en":"On the other side introduces the opposite or contrasting viewpoint in a debate.","zh":"on the other side 用來引入辯論中相反或對比的觀點。"},{"en":"On one side, teachers worry about screen time; on the other side, students enjoy digital learning.","zh":"一方面，老師擔心螢幕時間；另一方面，學生喜歡數碼學習。"},{"en":"This phrase helps readers compare two sides fairly.","zh":"這個短語幫助讀者公平比較兩方。"},{"en":"It often follows “on the one side” in balanced writing.","zh":"它在平衡寫作中常跟在 “on the one side” 之後。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":3},{"front":"self-styled disruptors","meaning":"自稱顛覆者的人","examples":[{"en":"Self-styled disruptors argue that digital technology has transformed education.","zh":"自稱顛覆者的人主張數碼科技已改變教育。"},{"en":"Self-styled disruptors are people who describe themselves as bold changers of an old system.","zh":"self-styled disruptors 是指自稱為舊制度大膽改革者的人。"},{"en":"A self-styled disruptor may claim that schools must abandon all traditional teaching.","zh":"自稱顛覆者的人可能聲稱學校必須放棄所有傳統教學。"},{"en":"Such people can bring fresh ideas, but they may also exaggerate their importance.","zh":"這類人可以帶來新想法，但也可能誇大自己的重要性。"},{"en":"The phrase can sound sceptical because it suggests they gave themselves the label.","zh":"這個短語可能帶有懷疑意味，因為它暗示這個標籤是他們自己給自己的。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":3},{"front":"overblown rhetoric","meaning":"誇張言論","examples":[{"en":"The writer criticises overblown rhetoric about digital technology.","zh":"作者批評關於數碼科技的誇張言論。"},{"en":"Overblown rhetoric means exaggerated language that makes something sound more dramatic than it really is.","zh":"overblown rhetoric 是指把某事說得比實際更戲劇化的誇張語言。"},{"en":"Saying one app will save all education is overblown rhetoric.","zh":"說一個應用程式會拯救所有教育，就是誇張言論。"},{"en":"Overblown rhetoric can make debates less useful because people stop discussing evidence.","zh":"誇張言論會令辯論變得較無用，因為人們停止討論證據。"},{"en":"Good arguments avoid exaggeration and explain what technology can actually do.","zh":"好論點避免誇張，並解釋科技實際上能做甚麼。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":3},{"front":"has changed everything","meaning":"已改變一切","examples":[{"en":"Some people claim that digital technology has changed everything.","zh":"有些人聲稱數碼科技已改變一切。"},{"en":"Has changed everything means has completely altered how people think, work, or behave.","zh":"has changed everything 是指已完全改變人們思考、工作或行為的方式。"},{"en":"Smartphones have changed everything about how many people communicate and find information.","zh":"智能手機已改變許多人溝通和尋找資訊的一切。"},{"en":"When people say technology has changed everything, they may be emphasising a major shift.","zh":"當人們說科技已改變一切時，他們可能是在強調重大轉變。"},{"en":"The phrase can be true in some ways, but it may also exaggerate the situation.","zh":"這個短語在某些方面可以是真的，但也可能誇大情況。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":3},{"front":"moribund profession","meaning":"垂死的行業；停滯的專業","examples":[{"en":"Supporters of change describe traditional history as a moribund profession.","zh":"改革支持者把傳統歷史描述為垂死的專業。"},{"en":"A moribund profession is a field of work that seems dying, inactive, or unable to develop.","zh":"moribund profession 是指看似正在死亡、停滯或無法發展的工作領域。"},{"en":"A newspaper business may look moribund if readers and advertisers all move online.","zh":"如果讀者和廣告商都轉到網上，報業可能看似垂死。"},{"en":"Calling a profession moribund can be unfair if it is actually adapting quietly.","zh":"如果一個專業其實正在靜靜適應，稱它垂死可能不公平。"},{"en":"The phrase is strongly negative and suggests that change is urgently needed.","zh":"這個短語非常負面，暗示迫切需要改變。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":3},{"front":"obstructs all progress","meaning":"阻礙所有進步","examples":[{"en":"They argue that the profession obstructs all progress.","zh":"他們主張該專業阻礙所有進步。"},{"en":"To obstruct all progress means to block every attempt to improve or move forward.","zh":"obstructs all progress 是指阻止每一次改善或前進的嘗試。"},{"en":"Too much paperwork can obstruct progress in a hospital reform project.","zh":"過多文書工作可以阻礙醫院改革項目的進步。"},{"en":"A manager obstructs progress if they reject every new idea without listening.","zh":"如果經理不聆聽就拒絕每個新想法，就是阻礙進步。"},{"en":"This phrase is extreme because it suggests complete resistance to change.","zh":"這個短語很極端，因為它暗示完全抗拒改變。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":3},{"front":"in the name of","meaning":"以……之名","examples":[{"en":"Some people resist change in the name of outdated ideals.","zh":"有些人以過時理念之名抗拒改變。"},{"en":"In the name of means claiming that an action is done for a particular principle, cause, or value.","zh":"in the name of 是指聲稱某行動是為了某個原則、事業或價值而做。"},{"en":"A school may ban phones in the name of concentration.","zh":"學校可能以專注之名禁止手機。"},{"en":"Leaders can make mistakes in the name of tradition if they refuse useful improvement.","zh":"如果領袖拒絕有用改善，他們可能以傳統之名犯錯。"},{"en":"This phrase can be neutral, but it often suggests that the reason may be questionable.","zh":"這個短語可以是中性的，但常暗示該理由可能值得質疑。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":3},{"front":"outdated ideals","meaning":"過時的理念","examples":[{"en":"The passage mentions outdated ideals in the debate about technology.","zh":"文章在關於科技的辯論中提到過時的理念。"},{"en":"Outdated ideals are old beliefs or values that no longer fit present needs or realities.","zh":"過時的理念是指不再符合當前需要或現實的舊信念或價值。"},{"en":"The idea that girls should not study science is an outdated ideal.","zh":"女孩不應學科學這個想法是過時的理念。"},{"en":"Outdated ideals can slow progress when people defend them without reason.","zh":"當人們毫無理由地捍衛過時理念時，它們會拖慢進步。"},{"en":"Not every old idea is outdated; an ideal becomes outdated when it no longer helps people.","zh":"並非所有舊想法都是過時的；當理念不再幫助人時，才算過時。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":3},{"front":"a parody of","meaning":"對……的誇張模仿","examples":[{"en":"The writer says this is a parody of how the debate proceeds.","zh":"作者說這是對辯論如何進行的誇張模仿。"},{"en":"A parody of something is an exaggerated imitation that makes its style or weakness obvious.","zh":"a parody of something 是對某事的誇張模仿，使其風格或弱點變得明顯。"},{"en":"A comedy show may create a parody of political speeches by making them sound ridiculous.","zh":"喜劇節目可能透過令政治演說顯得荒謬，創作對政治演說的誇張模仿。"},{"en":"Calling a debate a parody suggests that both sides may be acting in a predictable and exaggerated way.","zh":"稱一場辯論為 parody，暗示雙方可能都以可預測且誇張的方式行事。"},{"en":"This phrase often carries criticism rather than simple description.","zh":"這個短語常帶有批評意味，而不只是描述。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":3},{"front":"not much of one","meaning":"並非誇張得太多","examples":[{"en":"The writer suggests the parody may not be much of an exaggeration.","zh":"作者暗示這個誇張模仿可能並非誇張得太多。"},{"en":"Not much of one means not a very strong or serious example of the thing just mentioned.","zh":"not much of one 是指不太算是剛才提到的那種事物。"},{"en":"The apology was not much of one because it never admitted the mistake.","zh":"那個道歉不太算道歉，因為它從未承認錯誤。"},{"en":"If a “choice” has only one option, it is not much of a choice.","zh":"如果「選擇」只有一個選項，它就不太算選擇。"},{"en":"This phrase is often used to weaken or question the previous noun.","zh":"這個短語常用來削弱或質疑前面那個名詞。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":4},{"front":"how the debate proceeds","meaning":"辯論如何進行","examples":[{"en":"The passage describes how the debate proceeds.","zh":"文章描述辯論如何進行。"},{"en":"How the debate proceeds means the way the discussion develops, moves, or is argued.","zh":"how the debate proceeds 是指討論如何發展、推進或被爭論。"},{"en":"A teacher may watch how a debate proceeds to see whether students use evidence fairly.","zh":"老師可能觀察辯論如何進行，以了解學生是否公平使用證據。"},{"en":"If both sides only exaggerate, the debate proceeds badly.","zh":"如果雙方只會誇張，辯論就進行得很差。"},{"en":"This phrase focuses on the process of argument, not only the final conclusion.","zh":"這個短語集中於論辯過程，而不只是最終結論。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":4},{"front":"supporters and opponents","meaning":"支持者和反對者","examples":[{"en":"Supporters and opponents of digital technology share some common ground.","zh":"數碼科技的支持者和反對者有一些共同基礎。"},{"en":"Supporters and opponents are people who agree with and disagree with an idea or policy.","zh":"支持者和反對者是同意和不同意某個想法或政策的人。"},{"en":"In a school debate, supporters and opponents of homework may both care about learning.","zh":"在學校辯論中，功課的支持者和反對者可能都關心學習。"},{"en":"Supporters and opponents can disagree strongly but still share some values.","zh":"支持者和反對者可以強烈不同意，但仍分享某些價值。"},{"en":"Identifying both groups helps explain why an issue is controversial.","zh":"識別兩個群體有助解釋為何某議題具爭議性。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":4},{"front":"digital technology","meaning":"數碼科技","examples":[{"en":"Digital technology can change how history is taught.","zh":"數碼科技可以改變歷史的教學方式。"},{"en":"Digital technology includes computers, tablets, software, online platforms, and digital media.","zh":"數碼科技包括電腦、平板、軟件、網上平台和數碼媒體。"},{"en":"A teacher may use digital technology to show old maps, speeches, and photographs in class.","zh":"老師可能使用數碼科技在課堂中展示舊地圖、演說和照片。"},{"en":"Digital technology can increase access to sources, but students still need critical thinking.","zh":"數碼科技可以增加資料來源的可及性，但學生仍需要批判思考。"},{"en":"Good teaching uses digital technology as a tool, not as a substitute for understanding.","zh":"良好教學把數碼科技用作工具，而不是用它取代理解。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":4},{"front":"disciplinary common ground","meaning":"學科上的共同基礎","examples":[{"en":"Both sides share more disciplinary common ground than they admit.","zh":"雙方分享的學科共同基礎比他們承認的更多。"},{"en":"Disciplinary common ground means shared ideas, methods, or values within the same academic field.","zh":"disciplinary common ground 是指同一學術領域中共享的思想、方法或價值。"},{"en":"Historians may disagree about technology but still value evidence, sources, and careful interpretation.","zh":"歷史學家可能不同意科技的使用，但仍重視證據、資料來源和仔細詮釋。"},{"en":"Disciplinary common ground can make debate more productive because both sides start from some shared standards.","zh":"學科上的共同基礎可以令辯論更有成效，因為雙方以某些共同標準開始。"},{"en":"This phrase suggests that opponents are not as different as they seem.","zh":"這個短語暗示反對雙方並不像表面那麼不同。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":4},{"front":"than either admits","meaning":"比任何一方承認的更多","examples":[{"en":"Both groups have more in common than either admits.","zh":"兩個群體的共同之處比任何一方承認的更多。"},{"en":"Than either admits means more than any one of the two sides is willing to acknowledge.","zh":"than either admits 是指比兩方中任何一方願意承認的都更多。"},{"en":"Two arguing friends may care about each other more than either admits.","zh":"兩個爭吵中的朋友可能比任何一方承認的更關心彼此。"},{"en":"Teachers and students may want successful learning more than either side admits during conflict.","zh":"在衝突中，老師和學生可能都比任何一方承認的更想學習成功。"},{"en":"This phrase suggests that pride or disagreement hides shared interests.","zh":"這個短語暗示驕傲或分歧掩蓋了共同利益。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":4},{"front":"provided with merely","meaning":"只獲提供……","examples":[{"en":"Students were provided with merely a textbook as a learning tool.","zh":"學生只獲提供一本教科書作為學習工具。"},{"en":"Provided with merely something means given only that thing and nothing more.","zh":"provided with merely something 是指只得到該事物，沒有其他東西。"},{"en":"New workers cannot learn well if they are provided with merely a short rule sheet.","zh":"如果新員工只獲提供一張簡短規則表，他們很難學得好。"},{"en":"Students provided with merely a textbook may struggle to picture events clearly.","zh":"只獲提供教科書的學生可能難以清楚想像事件。"},{"en":"This phrase stresses that the support is limited or insufficient.","zh":"這個短語強調支援有限或不足夠。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":4},{"front":"supplemental learning tool","meaning":"輔助學習工具","examples":[{"en":"A textbook can be used as a supplemental learning tool.","zh":"教科書可以被用作輔助學習工具。"},{"en":"A supplemental learning tool is an extra resource that supports the main lesson.","zh":"輔助學習工具是支持主要課堂的額外資源。"},{"en":"Flashcards can be a supplemental learning tool for vocabulary revision.","zh":"生字卡可以成為詞彙複習的輔助學習工具。"},{"en":"A video becomes a supplemental learning tool when it helps explain what the teacher has already introduced.","zh":"當影片幫助解釋老師已介紹的內容時，它就成為輔助學習工具。"},{"en":"Supplemental tools should strengthen learning, not distract students from the main goal.","zh":"輔助工具應加強學習，而不是令學生偏離主要目標。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":4},{"front":"test results have revealed that","meaning":"測驗結果顯示","examples":[{"en":"Test results have revealed that many students do not understand historical significance.","zh":"測驗結果顯示，許多學生不理解歷史重要性。"},{"en":"Test results have revealed that means exam scores or answers have shown a particular problem or fact.","zh":"test results have revealed that 是指考試分數或答案顯示了某個問題或事實。"},{"en":"Test results have revealed that some students need more practice with reading instructions.","zh":"測驗結果顯示，有些學生需要更多練習閱讀指示。"},{"en":"If test results reveal weakness, teachers can adjust lessons to target the problem.","zh":"如果測驗結果顯示弱點，老師可以調整課堂以針對問題。"},{"en":"This phrase connects evidence from assessment with a conclusion.","zh":"這個短語把評估證據與結論連接起來。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":4},{"front":"fail to pinpoint","meaning":"未能準確指出","examples":[{"en":"Many students fail to pinpoint the significance of historical events.","zh":"許多學生未能準確指出歷史事件的重要性。"},{"en":"To fail to pinpoint something means to be unable to identify it exactly or clearly.","zh":"fail to pinpoint 是指無法準確或清楚識別某事。"},{"en":"A doctor may fail to pinpoint the cause of pain without further tests.","zh":"如果沒有進一步檢查，醫生可能未能準確指出疼痛原因。"},{"en":"Students fail to pinpoint the main idea when they only memorise details.","zh":"當學生只背細節時，可能未能準確指出主旨。"},{"en":"This phrase suggests that the answer is not just missing but not accurately located.","zh":"這個短語暗示答案不只是缺失，而是沒有被準確定位。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":4},{"front":"the significance of","meaning":"……的重要性","examples":[{"en":"Students often miss the significance of historical events.","zh":"學生常錯過歷史事件的重要性。"},{"en":"The significance of something is its importance, meaning, or wider effect.","zh":"the significance of something 是指某事的重要性、意義或更廣泛影響。"},{"en":"Students may know the date of a war but miss the significance of its consequences.","zh":"學生可能知道一場戰爭的日期，但錯過其後果的重要性。"},{"en":"Understanding the significance of an event helps people see why it still matters today.","zh":"理解事件的重要性，有助人們看見它為何至今仍重要。"},{"en":"This phrase is useful when moving from facts to meaning.","zh":"這個短語在從事實轉向意義時很有用。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":4},{"front":"historical events and individuals","meaning":"歷史事件和人物","examples":[{"en":"Students need to understand historical events and individuals.","zh":"學生需要理解歷史事件和人物。"},{"en":"Historical events and individuals are important past happenings and the people connected with them.","zh":"歷史事件和人物是重要的過去事件及與其相關的人。"},{"en":"A lesson on civil rights should include both historical events and individuals who shaped the movement.","zh":"關於民權的課堂應包括塑造運動的歷史事件和人物。"},{"en":"Studying only names without events can make history feel disconnected.","zh":"只學名字而不學事件，會令歷史感覺脫節。"},{"en":"Students understand history better when people and events are linked together.","zh":"當人物和事件被連接起來時，學生會更好理解歷史。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":5},{"front":"fewer still","meaning":"更少人能夠","examples":[{"en":"Fewer still are able to cite primary historical sources.","zh":"更少人能夠引用第一手歷史資料。"},{"en":"Fewer still means an even smaller number of people or things than the group just mentioned.","zh":"fewer still 是指比剛才提到的群體還要更少的人或事物。"},{"en":"Many students can name the event, but fewer still can explain its causes.","zh":"許多學生能說出事件名稱，但更少人能解釋其原因。"},{"en":"Some workers know the rule, but fewer still apply it correctly under pressure.","zh":"有些員工知道規則，但更少人能在壓力下正確應用。"},{"en":"This phrase shows a further drop from an already small number.","zh":"這個短語顯示在已經少的數量上進一步下降。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":5},{"front":"cite and substantiate","meaning":"引用並證實","examples":[{"en":"Students often struggle to cite and substantiate historical sources.","zh":"學生常難以引用並證實歷史資料。"},{"en":"To cite and substantiate means to quote a source and use evidence to support a claim.","zh":"cite and substantiate 是指引用來源，並用證據支持主張。"},{"en":"In essays, students cite and substantiate arguments by referring to documents and explaining their relevance.","zh":"在文章中，學生透過提及文件並解釋其相關性來引用並證實論點。"},{"en":"A claim is weak if the writer cites a source but fails to substantiate the point.","zh":"如果作者引用來源卻未能證實觀點，該主張仍然薄弱。"},{"en":"This skill matters because history depends on evidence, not only opinion.","zh":"這項技能很重要，因為歷史依賴證據，而不只是意見。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":5},{"front":"primary historical sources","meaning":"第一手歷史資料","examples":[{"en":"Students need to learn how to use primary historical sources.","zh":"學生需要學習如何使用第一手歷史資料。"},{"en":"Primary historical sources are original materials from the time being studied, such as letters, diaries, speeches, or photographs.","zh":"第一手歷史資料是所研究時代的原始材料，例如信件、日記、演說或照片。"},{"en":"A soldier’s diary from a war is a primary historical source.","zh":"戰爭中士兵的日記是一份第一手歷史資料。"},{"en":"Primary historical sources help students hear voices from the past more directly.","zh":"第一手歷史資料幫助學生更直接聽到過去的聲音。"},{"en":"Students must still interpret these sources carefully because every source has a context.","zh":"學生仍必須小心詮釋這些資料，因為每份來源都有背景。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":5},{"front":"the way educators are presenting information","meaning":"教育工作者呈現資料的方式","examples":[{"en":"The results raise questions about the way educators are presenting information.","zh":"這些結果引發對教育工作者呈現資料方式的質疑。"},{"en":"The way educators are presenting information means how teachers organise, explain, and deliver knowledge to students.","zh":"教育工作者呈現資料的方式，是指老師如何組織、解釋和傳達知識給學生。"},{"en":"If students remember facts but not meaning, the way educators present information may need change.","zh":"如果學生記得事實但不懂意義，教育工作者呈現資料的方式可能需要改變。"},{"en":"A teacher can improve presentation by using stories, visuals, and source analysis.","zh":"老師可以透過故事、視覺材料和來源分析來改善呈現方式。"},{"en":"This phrase shifts attention from students’ failure to teaching methods.","zh":"這個短語把注意力由學生失敗轉向教學方法。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":5},{"front":"these observations","meaning":"這些觀察","examples":[{"en":"These observations come from an early report on students’ historical knowledge.","zh":"這些觀察來自一份關於學生歷史知識的早期報告。"},{"en":"These observations means the points or comments noticed from evidence or experience.","zh":"these observations 是指從證據或經驗中注意到的要點或評論。"},{"en":"These observations from the survey show that students prefer short videos to long lectures.","zh":"這些來自調查的觀察顯示，學生偏好短片而不是長講課。"},{"en":"Careful observations can reveal classroom problems that test scores alone may hide.","zh":"仔細觀察可以揭示單靠測驗分數可能隱藏的課堂問題。"},{"en":"This phrase points back to ideas already mentioned.","zh":"這個短語指回前面已提及的想法。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":5},{"front":"a report on","meaning":"關於……的報告","examples":[{"en":"The observations come from a report on a 1917 test.","zh":"這些觀察來自一份關於1917年測驗的報告。"},{"en":"A report on something is a written account that studies, describes, or explains that topic.","zh":"a report on something 是指研究、描述或解釋某題目的書面記錄。"},{"en":"A school may publish a report on student reading habits.","zh":"學校可能發表一份關於學生閱讀習慣的報告。"},{"en":"A report on exam performance can help teachers identify common weaknesses.","zh":"關於考試表現的報告可以幫助老師識別常見弱點。"},{"en":"This phrase tells readers the subject of the report.","zh":"這個短語告訴讀者報告的主題。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":5},{"front":"school-age children","meaning":"學齡兒童","examples":[{"en":"Few school-age children attended high school in 1917.","zh":"1917年很少學齡兒童就讀中學。"},{"en":"School-age children are children old enough to attend school.","zh":"學齡兒童是指年齡已足以入學的兒童。"},{"en":"Public libraries often design reading programmes for school-age children.","zh":"公共圖書館常為學齡兒童設計閱讀計劃。"},{"en":"If many school-age children cannot attend school, society loses future skills and opportunities.","zh":"如果許多學齡兒童不能上學，社會會失去未來技能和機會。"},{"en":"This phrase refers to age group, not academic ability.","zh":"這個短語指年齡群體，而不是學業能力。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":5},{"front":"attended high school","meaning":"就讀中學","examples":[{"en":"Less than 10 per cent of school-age children attended high school.","zh":"少於百分之十的學齡兒童就讀中學。"},{"en":"Attended high school means went to or studied at a secondary school.","zh":"attended high school 是指上中學或在中學學習。"},{"en":"My grandmother attended high school only after her family moved to the city.","zh":"我祖母在家人搬到城市後才就讀中學。"},{"en":"In the past, fewer children attended high school because many had to work.","zh":"過去較少兒童就讀中學，因為許多人必須工作。"},{"en":"This phrase describes school participation, not exam success.","zh":"這個短語描述入學情況，而不是考試成績。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":5},{"front":"enrolments are nearly universal","meaning":"入學率幾乎普及","examples":[{"en":"Today, school enrolments are nearly universal.","zh":"今天，入學率幾乎普及。"},{"en":"Enrolments are nearly universal means almost everyone in the relevant group is registered in school.","zh":"enrolments are nearly universal 是指相關群體中幾乎所有人都已註冊入學。"},{"en":"In many cities, primary school enrolments are nearly universal because education is compulsory.","zh":"在許多城市，小學入學率幾乎普及，因為教育是強制性的。"},{"en":"Nearly universal enrolment can increase basic literacy across society.","zh":"入學率幾乎普及可以提升整個社會的基本識字能力。"},{"en":"This phrase shows a major change from a time when many children did not attend school.","zh":"這個短語顯示與許多兒童不上學的年代相比有重大改變。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":5},{"front":"has turned on its head","meaning":"徹底改變","examples":[{"en":"The whole world has turned on its head during the last century.","zh":"在過去一個世紀，整個世界已徹底改變。"},{"en":"Has turned on its head means has changed completely or been reversed.","zh":"has turned on its head 是指已完全改變或被顛倒。"},{"en":"Online shopping has turned retail on its head by changing how people buy goods.","zh":"網上購物透過改變人們購買商品的方式，徹底改變了零售。"},{"en":"A new discovery can turn an old theory on its head.","zh":"新發現可以徹底推翻舊理論。"},{"en":"This phrase suggests dramatic change, not a small adjustment.","zh":"這個短語暗示劇烈變化，而不是小調整。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":5},{"front":"during the last century","meaning":"在過去一個世紀","examples":[{"en":"Education has changed greatly during the last century.","zh":"教育在過去一個世紀大大改變。"},{"en":"During the last century means over the past one hundred years.","zh":"during the last century 是指在過去一百年期間。"},{"en":"During the last century, transport became faster and communication became easier.","zh":"在過去一個世紀，交通變得更快，溝通變得更容易。"},{"en":"Schools changed during the last century as more children gained access to education.","zh":"在過去一個世紀，隨著更多兒童能接受教育，學校也改變了。"},{"en":"This phrase places change within a broad historical period.","zh":"這個短語把變化放在一個廣闊歷史時期中。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":6},{"front":"stayed the same","meaning":"保持不變","examples":[{"en":"One thing has stayed the same across generations.","zh":"有一件事跨世代保持不變。"},{"en":"Stayed the same means did not change.","zh":"stayed the same 是指沒有改變。"},{"en":"The school building changed, but the morning bell stayed the same.","zh":"校舍改變了，但早上的鐘聲保持不變。"},{"en":"If teaching problems stay the same, new tools alone may not solve them.","zh":"如果教學問題保持不變，單靠新工具未必能解決它們。"},{"en":"This phrase is useful for contrasting change with continuity.","zh":"這個短語適合用來對比變化與延續。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":6},{"front":"woefully ignorant of","meaning":"對……極度無知","examples":[{"en":"Young people remain woefully ignorant of history.","zh":"年輕人仍然對歷史極度無知。"},{"en":"Woefully ignorant of something means knowing very little about it in a worrying or disappointing way.","zh":"woefully ignorant of 是指對某事知道得很少，程度令人擔心或失望。"},{"en":"A voter who is woefully ignorant of basic laws may be easily misled.","zh":"對基本法律極度無知的選民可能容易被誤導。"},{"en":"Students can become woefully ignorant of history if they memorise dates without understanding meaning.","zh":"如果學生只背日期而不理解意義，可能會對歷史極度無知。"},{"en":"This phrase is strong and critical, not neutral.","zh":"這個短語語氣強烈且帶批評意味，並不中性。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":6},{"front":"as reflected in","meaning":"反映於","examples":[{"en":"Their ignorance is reflected in test results.","zh":"他們的無知反映於測驗結果。"},{"en":"As reflected in means as shown or revealed by something.","zh":"as reflected in 是指由某事顯示或揭示出來。"},{"en":"Student stress is reflected in higher absence rates before exams.","zh":"學生壓力反映於考試前較高缺席率。"},{"en":"A company’s poor service may be reflected in customer complaints.","zh":"公司的差劣服務可能反映於顧客投訴。"},{"en":"This phrase connects a hidden condition with visible evidence.","zh":"這個短語把隱藏情況與可見證據連接起來。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":6},{"front":"test results","meaning":"測驗結果","examples":[{"en":"Test results suggest that students lack historical knowledge.","zh":"測驗結果顯示學生缺乏歷史知識。"},{"en":"Test results are scores or answers that show how people performed on an exam.","zh":"測驗結果是顯示人們在考試中表現如何的分數或答案。"},{"en":"Teachers use test results to find which topics students have not understood.","zh":"老師使用測驗結果找出學生未理解哪些題目。"},{"en":"Test results can reveal weaknesses, but they do not measure every kind of knowledge.","zh":"測驗結果可以揭示弱點，但不能量度每一種知識。"},{"en":"In history, test results may show memory of facts more than deep understanding.","zh":"在歷史科中，測驗結果可能更顯示事實記憶，而不是深層理解。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":6},{"front":"equate historical knowledge with","meaning":"把歷史知識等同於……","examples":[{"en":"We should not equate historical knowledge with quiz performance.","zh":"我們不應把歷史知識等同於小測表現。"},{"en":"To equate historical knowledge with quiz performance means to treat test scores as the same thing as real understanding of history.","zh":"equate historical knowledge with quiz performance 是指把測驗分數視為與真正理解歷史相同。"},{"en":"A student may fail a quiz but still understand why an event matters.","zh":"學生可能小測不合格，但仍理解某事件為何重要。"},{"en":"Equating knowledge with marks can make teachers ignore discussion, interpretation, and evidence use.","zh":"把知識等同於分數，可能令老師忽略討論、詮釋和使用證據。"},{"en":"This phrase warns against confusing one measurement with the whole skill.","zh":"這個短語提醒人們不要把一種量度方式與整項能力混淆。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":6},{"front":"did just fine","meaning":"表現相當不錯","examples":[{"en":"Specialists in American history did just fine on the test.","zh":"美國歷史專家在測驗中表現相當不錯。"},{"en":"Did just fine means performed acceptably or quite well, though not necessarily perfectly.","zh":"did just fine 是指表現可以接受或相當好，但不一定完美。"},{"en":"The student was nervous before the interview, but she did just fine.","zh":"那名學生面試前很緊張，但她表現相當不錯。"},{"en":"A simple teaching method can do just fine if it helps students understand clearly.","zh":"如果簡單教學方法能幫助學生清楚理解，它也可以相當不錯。"},{"en":"This phrase is informal and reassuring.","zh":"這個短語較口語，帶有安慰意味。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":6},{"front":"specialities in","meaning":"……方面的專門範疇","examples":[{"en":"Some historians had specialities in medieval, European and African history.","zh":"有些歷史學家的專門範疇是中世紀、歐洲和非洲歷史。"},{"en":"Specialities in something are areas a person studies or works in deeply.","zh":"specialities in something 是指某人深入研究或工作的範疇。"},{"en":"A doctor may have specialities in heart disease and elderly care.","zh":"醫生的專門範疇可能是心臟病和長者護理。"},{"en":"Historians with specialities in one region may not know every fact about another region.","zh":"在某地區有專門範疇的歷史學家，未必知道另一地區的每個事實。"},{"en":"This phrase helps explain why experts can still struggle outside their field.","zh":"這個短語有助解釋為何專家在自己領域以外仍可能吃力。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":6},{"front":"failed miserably","meaning":"慘敗；表現極差","examples":[{"en":"Some historians failed miserably when asked about American history.","zh":"有些歷史學家在被問及美國歷史時表現極差。"},{"en":"Failed miserably means performed very badly or completely failed.","zh":"failed miserably 是指表現非常差或完全失敗。"},{"en":"A student who never reads the passage may fail miserably on detailed questions.","zh":"從不閱讀文章的學生，可能在細節題上慘敗。"},{"en":"A project can fail miserably if nobody understands the goal or deadline.","zh":"如果沒有人理解目標或期限，項目可能慘敗。"},{"en":"This phrase is strong and often slightly humorous or critical.","zh":"這個短語語氣強烈，常帶有少許幽默或批評意味。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":6},{"front":"when confronted by","meaning":"當面對……時","examples":[{"en":"Some experts struggled when confronted by unfamiliar textbook items.","zh":"有些專家當面對不熟悉的教科書題目時感到吃力。"},{"en":"When confronted by something means when faced with a problem, question, or situation directly.","zh":"when confronted by something 是指直接面對某個問題、題目或情況時。"},{"en":"A shy student may freeze when confronted by a difficult speaking task.","zh":"害羞學生當面對困難口語任務時，可能會僵住。"},{"en":"Workers may feel stressed when confronted by new software without training.","zh":"員工在沒有培訓下當面對新軟件時，可能感到壓力。"},{"en":"This phrase often suggests pressure or challenge.","zh":"這個短語常暗示壓力或挑戰。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":6},{"front":"taken from","meaning":"取自","examples":[{"en":"The test items were taken from a typical textbook.","zh":"測驗題目取自一本典型教科書。"},{"en":"Taken from means copied, selected, or drawn from a particular source.","zh":"taken from 是指從某個來源複製、選取或抽取。"},{"en":"The reading passage was taken from a newspaper article.","zh":"閱讀篇章取自一篇報章文章。"},{"en":"Questions taken from old exams can help students practise familiar formats.","zh":"取自舊試卷的題目可以幫助學生練習熟悉格式。"},{"en":"This phrase tells readers where the material came from.","zh":"這個短語告訴讀者材料來自哪裡。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":6},{"front":"according to","meaning":"根據","examples":[{"en":"According to the testers, young people are abysmally ignorant of history.","zh":"根據測驗者，年輕人對歷史極其無知。"},{"en":"According to means based on what a person, source, or report says.","zh":"according to 是指根據某人、來源或報告所說。"},{"en":"According to the timetable, the last bus leaves at eleven.","zh":"根據時間表，最後一班巴士十一點開出。"},{"en":"According to the doctor, the patient needs more rest.","zh":"根據醫生所說，病人需要更多休息。"},{"en":"This phrase reports information without necessarily saying the writer agrees with it.","zh":"這個短語報告資訊，但不一定表示作者同意。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":7},{"front":"National Assessment in History","meaning":"全國歷史評估","examples":[{"en":"The National Assessment in History showed weak test performance.","zh":"全國歷史評估顯示測驗表現薄弱。"},{"en":"The National Assessment in History is a formal test or assessment of students’ historical knowledge.","zh":"全國歷史評估是對學生歷史知識的正式測驗或評估。"},{"en":"Education officials may use a national assessment to compare student performance across regions.","zh":"教育官員可能使用全國評估來比較不同地區的學生表現。"},{"en":"Weak results in such an assessment can create public concern about teaching quality.","zh":"這類評估中的薄弱結果會引起公眾對教學質素的關注。"},{"en":"This phrase refers to an official measurement, not a casual classroom quiz.","zh":"這個短語指官方量度，而不是普通課堂小測。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":7},{"front":"scores from earlier tests","meaning":"較早測驗的分數","examples":[{"en":"Recent scores resemble scores from earlier tests.","zh":"近期分數與較早測驗的分數相似。"},{"en":"Scores from earlier tests are results from previous exams or assessments.","zh":"scores from earlier tests 是指以前考試或評估的結果。"},{"en":"Teachers compare current results with scores from earlier tests to see whether students improved.","zh":"老師把目前結果與較早測驗的分數比較，以了解學生是否進步。"},{"en":"If scores from earlier tests are similar, the same problem may have continued over time.","zh":"如果較早測驗的分數相似，同一問題可能多年來一直存在。"},{"en":"This phrase helps show patterns across different years.","zh":"這個短語有助顯示不同年份之間的模式。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":7},{"front":"abysmally ignorant","meaning":"極其無知的","examples":[{"en":"The testers claimed that young people are abysmally ignorant of history.","zh":"測驗者聲稱年輕人對歷史極其無知。"},{"en":"Abysmally ignorant means extremely lacking in knowledge, to a shocking degree.","zh":"abysmally ignorant 是指缺乏知識到令人震驚的程度。"},{"en":"A person who cannot name any basic safety rule may be abysmally ignorant of workplace risks.","zh":"一個連任何基本安全規則都說不出的人，可能對工作場所風險極其無知。"},{"en":"Calling students abysmally ignorant is a harsh judgement that may ignore what tests cannot measure.","zh":"稱學生極其無知是一種嚴厲判斷，可能忽略測驗無法量度的東西。"},{"en":"This phrase is much stronger than simply saying “uninformed.”","zh":"這個短語比 simply saying “uninformed” 強烈得多。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":7},{"front":"invoking the tragedy of","meaning":"援引……的悲劇","examples":[{"en":"The historian invoked the tragedy of last September in her argument.","zh":"那位歷史學家在論點中援引去年九月的悲劇。"},{"en":"Invoking the tragedy of something means referring to a sad or serious event to support a point.","zh":"invoking the tragedy of something 是指提及某個悲傷或嚴重事件來支持觀點。"},{"en":"A speaker may invoke the tragedy of a flood to argue for better emergency planning.","zh":"演講者可能援引洪水悲劇來主張更好的應急規劃。"},{"en":"Invoking tragedy can make an argument emotional, so evidence is still needed.","zh":"援引悲劇可以令論點更具情感，因此仍需要證據。"},{"en":"This phrase suggests using a painful event as part of persuasion.","zh":"這個短語暗示把痛苦事件用作說服的一部分。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":7},{"front":"hitched her worries to","meaning":"把擔憂與……聯繫起來","examples":[{"en":"Diane Ravitch hitched her worries about the future to poor history scores.","zh":"Diane Ravitch 把她對未來的擔憂與差劣歷史分數聯繫起來。"},{"en":"To hitch one worry to something means to connect that concern with a particular issue or evidence.","zh":"hitch one worry to something 是指把某種憂慮與某個議題或證據連接起來。"},{"en":"A parent may hitch worries about children’s health to rising screen time.","zh":"家長可能把對孩子健康的擔憂與螢幕時間上升聯繫起來。"},{"en":"A politician may hitch economic fears to unemployment figures.","zh":"政治人物可能把經濟恐懼與失業數字聯繫起來。"},{"en":"This phrase can suggest that the connection is strategic or not fully proven.","zh":"這個短語可能暗示該連繫帶有策略性或未完全證明。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":7},{"front":"our nation’s strength","meaning":"國家的實力","examples":[{"en":"She argued that the nation’s strength was endangered.","zh":"她主張國家的實力受到威脅。"},{"en":"Our nation’s strength means the power, unity, knowledge, and stability of a country.","zh":"our nation’s strength 是指一個國家的力量、團結、知識和穩定。"},{"en":"Good education can support a nation’s strength by preparing informed citizens.","zh":"良好教育可以透過培養有知識的公民來支持國家的實力。"},{"en":"Poor public trust may weaken a nation’s strength during crises.","zh":"公眾信任不足可能在危機中削弱國家的實力。"},{"en":"This phrase is often used in serious political or civic arguments.","zh":"這個短語常用於嚴肅的政治或公民論述。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":7},{"front":"endangered by","meaning":"受……威脅","examples":[{"en":"The nation’s strength may be endangered by poor historical knowledge.","zh":"國家的實力可能受差劣歷史知識威脅。"},{"en":"Endangered by means put at risk or threatened by something.","zh":"endangered by 是指被某事置於風險中或受到威脅。"},{"en":"Children’s safety may be endangered by careless driving near schools.","zh":"學校附近的粗心駕駛可能威脅兒童安全。"},{"en":"A rare language can be endangered by younger people no longer using it.","zh":"如果年輕人不再使用，一種稀有語言可能受威脅。"},{"en":"This phrase shows that one factor may seriously harm another thing.","zh":"這個短語顯示某因素可能嚴重傷害另一事物。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":7},{"front":"do poorly on","meaning":"在……表現差","examples":[{"en":"Some students do poorly on history tests.","zh":"有些學生在歷史測驗中表現差。"},{"en":"To do poorly on something means to perform badly in a test, task, or activity.","zh":"do poorly on 是指在測驗、任務或活動中表現不好。"},{"en":"A student may do poorly on a listening test if the audio is too fast.","zh":"如果錄音太快，學生可能在聆聽測驗中表現差。"},{"en":"Doing poorly on one quiz does not always mean a student lacks real understanding.","zh":"一次小測表現差不一定代表學生缺乏真正理解。"},{"en":"This phrase describes performance, not a person’s worth.","zh":"這個短語描述表現，而不是人的價值。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":7},{"front":"gone down the tubes","meaning":"走向衰敗；完蛋","examples":[{"en":"The writer jokes that the nation would have gone down the tubes long ago.","zh":"作者開玩笑說國家早就會走向衰敗。"},{"en":"Gone down the tubes means failed badly, collapsed, or become ruined.","zh":"gone down the tubes 是指嚴重失敗、崩潰或毀掉。"},{"en":"A project can go down the tubes if funding disappears and no one manages it.","zh":"如果資金消失且沒有人管理，項目可能完蛋。"},{"en":"Saying a country has gone down the tubes is informal and exaggerated.","zh":"說一個國家 gone down the tubes 是非正式且誇張的說法。"},{"en":"This phrase is often used jokingly or critically, not in very formal writing.","zh":"這個短語常帶玩笑或批評語氣，不適合非常正式寫作。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":7},{"front":"a huge difference between","meaning":"……之間的巨大差異","examples":[{"en":"There is a huge difference between two claims about historical knowledge.","zh":"關於歷史知識的兩種說法之間有巨大差異。"},{"en":"A huge difference between two things means they are very different in meaning, size, or effect.","zh":"a huge difference between two things 是指兩者在意義、大小或影響上非常不同。"},{"en":"There is a huge difference between forgetting one date and not understanding history at all.","zh":"忘記一個日期與完全不懂歷史之間有巨大差異。"},{"en":"A huge difference between two policies can change how students learn.","zh":"兩項政策之間的巨大差異可以改變學生學習方式。"},{"en":"This phrase helps prevent people from treating unlike things as the same.","zh":"這個短語有助防止人們把不同事物視為相同。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":7},{"front":"the history we want them to know","meaning":"我們希望他們知道的歷史","examples":[{"en":"Students may not know the history we want them to know.","zh":"學生可能不知道我們希望他們知道的歷史。"},{"en":"The history we want them to know means the particular facts, stories, and interpretations adults think students should learn.","zh":"the history we want them to know 是指成年人認為學生應學習的特定事實、故事和詮釋。"},{"en":"Schools must decide what history they want students to know and why it matters.","zh":"學校必須決定希望學生知道甚麼歷史，以及它為何重要。"},{"en":"Students may know family or popular history even if they do not know textbook history.","zh":"即使學生不知道教科書歷史，他們也可能知道家庭或流行歷史。"},{"en":"This phrase reminds us that historical knowledge is partly shaped by educational choices.","zh":"這個短語提醒我們，歷史知識部分由教育選擇塑造。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":8},{"front":"not at all","meaning":"完全不","examples":[{"en":"The writer rejects the claim that students do not know history at all.","zh":"作者拒絕學生完全不懂歷史的說法。"},{"en":"Not at all means completely not or in no way.","zh":"not at all 是指完全不或一點也不。"},{"en":"A student may not know the exact date, but that does not mean they understand history not at all.","zh":"學生可能不知道確切日期，但這不代表他完全不理解歷史。"},{"en":"If someone says “not at all,” they are strongly denying something.","zh":"如果有人說 not at all，他是在強烈否定某事。"},{"en":"This phrase is useful for correcting an extreme statement.","zh":"這個短語適合用來糾正極端說法。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":8},{"front":"historical knowledge","meaning":"歷史知識","examples":[{"en":"Historical knowledge is not limited to textbook facts.","zh":"歷史知識不限於教科書事實。"},{"en":"Historical knowledge means understanding past events, people, causes, evidence, and significance.","zh":"歷史知識是指理解過去事件、人物、原因、證據和重要性。"},{"en":"A student has historical knowledge when they can explain why a war changed society.","zh":"當學生能解釋一場戰爭為何改變社會時，他就有歷史知識。"},{"en":"Historical knowledge grows when students connect dates with sources and human stories.","zh":"當學生把日期與資料來源和人的故事連接起來，歷史知識會增長。"},{"en":"Memorising facts is part of historical knowledge, but it is not the whole of it.","zh":"背誦事實是歷史知識的一部分，但不是全部。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":8},{"front":"burrows itself into","meaning":"深深滲入","examples":[{"en":"Historical knowledge burrows itself into our cultural pores.","zh":"歷史知識深深滲入我們的文化肌理。"},{"en":"To burrow itself into something means to enter deeply and become hard to separate from it.","zh":"burrow itself into 是指深入進入某事物，並變得難以分開。"},{"en":"Childhood stories can burrow themselves into a person’s memory for decades.","zh":"童年故事可以深深滲入一個人的記憶數十年。"},{"en":"National history can burrow itself into language, festivals, and public symbols.","zh":"國家歷史可以深深滲入語言、節日和公共符號。"},{"en":"This phrase is metaphorical and suggests something becomes deeply embedded.","zh":"這個短語是比喻，暗示某事變得深深嵌入。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":8},{"front":"cultural pores","meaning":"文化肌理；文化細胞","examples":[{"en":"History becomes part of our cultural pores.","zh":"歷史成為我們文化肌理的一部分。"},{"en":"Cultural pores is a metaphor for the deep, tiny spaces of culture where ideas and memories settle.","zh":"cultural pores 是一個比喻，指文化中讓思想和記憶沉澱的深層細小空間。"},{"en":"A song can enter a community’s cultural pores if people sing it for generations.","zh":"如果一首歌被人們傳唱幾代，它可以進入社區的文化肌理。"},{"en":"Historical stories in films, holidays, and street names become part of our cultural pores.","zh":"電影、假日和街名中的歷史故事成為我們文化肌理的一部分。"},{"en":"This phrase means history is absorbed into everyday culture, not only studied in school.","zh":"這個短語表示歷史被吸收到日常文化中，而不只是學校中的學科。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":8},{"front":"marshal it","meaning":"有條理地運用","examples":[{"en":"Young people may not be able to marshal historical knowledge in a test.","zh":"年輕人可能未能在測驗中有條理地運用歷史知識。"},{"en":"To marshal knowledge means to organise and use it clearly for a purpose.","zh":"marshal knowledge 是指為了某目的清楚組織和使用知識。"},{"en":"A student may know many facts but fail to marshal them into a strong essay.","zh":"學生可能知道許多事實，但未能把它們有條理地運用成有力文章。"},{"en":"Good planning helps writers marshal evidence before they start writing.","zh":"良好計劃幫助作者在開始寫作前有條理地整理證據。"},{"en":"This phrase suggests organised use, not just possession of information.","zh":"這個短語暗示有組織地使用，而不只是擁有資訊。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":8},{"front":"when faced with","meaning":"當面對……時","examples":[{"en":"Students may struggle when faced with a multiple-choice test.","zh":"學生當面對多項選擇題測驗時可能感到吃力。"},{"en":"When faced with means when someone has to deal with a particular situation or problem.","zh":"when faced with 是指某人必須處理某個情況或問題時。"},{"en":"A student may panic when faced with a long reading passage.","zh":"學生當面對長篇閱讀文章時可能會慌張。"},{"en":"Workers need training so they know what to do when faced with customer complaints.","zh":"員工需要培訓，才知道當面對顧客投訴時應如何處理。"},{"en":"This phrase often introduces a challenge that tests someone’s ability.","zh":"這個短語常引入考驗某人能力的挑戰。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":8},{"front":"multiple-choice test","meaning":"多項選擇題測驗","examples":[{"en":"A multiple-choice test may not fully measure historical knowledge.","zh":"多項選擇題測驗未必能完全量度歷史知識。"},{"en":"A multiple-choice test is an exam where students choose answers from given options.","zh":"多項選擇題測驗是學生從給定選項中選擇答案的考試。"},{"en":"Multiple-choice tests are easy to mark, but they may not show how students explain ideas.","zh":"多項選擇題測驗容易批改，但未必顯示學生如何解釋想法。"},{"en":"A student can sometimes guess correctly on a multiple-choice test without deep understanding.","zh":"學生有時可以在多項選擇題測驗中猜中答案，而沒有深層理解。"},{"en":"This test format measures recognition more than extended reasoning.","zh":"這種測驗形式量度辨認能力多於延伸推理。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":8},{"front":"hypocrites","meaning":"偽善者","examples":[{"en":"The writer suggests that adults may be hypocrites about students’ ignorance.","zh":"作者暗示成年人在學生無知這件事上可能是偽善者。"},{"en":"Hypocrites are people who criticise others for faults they also have themselves.","zh":"hypocrites 是指批評別人有某種缺點，但自己也有同樣缺點的人。"},{"en":"Adults are hypocrites if they complain that students forget history while they cannot answer the same questions.","zh":"如果成年人抱怨學生忘記歷史，但自己也答不到同樣問題，他們就是偽善者。"},{"en":"A leader becomes a hypocrite when they demand honesty but hide their own mistakes.","zh":"當領袖要求誠實卻隱藏自己的錯誤時，他就成為偽善者。"},{"en":"This word is strongly critical and should be used carefully.","zh":"這個詞批評意味很強，應小心使用。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":8},{"front":"follow in our own footsteps","meaning":"追隨我們的腳步","examples":[{"en":"Today’s students follow in our own footsteps.","zh":"今天的學生追隨我們自己的腳步。"},{"en":"To follow in someone’s footsteps means to behave in a similar way or repeat what earlier people did.","zh":"follow in someone’s footsteps 是指以相似方式行事，或重複前人所做的事。"},{"en":"A child may follow in her mother’s footsteps by becoming a teacher.","zh":"孩子可能追隨母親的腳步成為老師。"},{"en":"Students follow in adults’ footsteps if they also struggle to remember textbook facts.","zh":"如果學生同樣難以記住教科書事實，他們就是追隨成年人的腳步。"},{"en":"This phrase can describe inheritance, imitation, or repeating an old pattern.","zh":"這個短語可以描述繼承、模仿或重複舊模式。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":8},{"front":"for too long","meaning":"太長時間以來","examples":[{"en":"For too long, educators have relied on textbook revision.","zh":"太長時間以來，教育工作者一直依賴教科書修訂。"},{"en":"For too long means for a longer period than is reasonable or helpful.","zh":"for too long 是指持續時間長過合理或有幫助的程度。"},{"en":"For too long, the school ignored students’ stress before changing its timetable.","zh":"太長時間以來，學校忽視學生壓力，後來才改變時間表。"},{"en":"A problem becomes worse when people leave it unsolved for too long.","zh":"當人們太長時間不解決問題時，問題會惡化。"},{"en":"This phrase suggests criticism of delay or old habits.","zh":"這個短語暗示對延誤或舊習慣的批評。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":8},{"front":"fantasized that","meaning":"幻想","examples":[{"en":"Educators have fantasized that rewriting textbooks could change learning.","zh":"教育工作者幻想重寫教科書可以改變學習。"},{"en":"Fantasized that means imagined or hoped something would happen, often unrealistically.","zh":"fantasized that 是指想像或希望某事會發生，通常不太現實。"},{"en":"A student may fantasize that buying new notebooks will automatically improve grades.","zh":"學生可能幻想買新筆記簿就會自動提升成績。"},{"en":"Schools may fantasize that one new policy will solve every learning problem.","zh":"學校可能幻想一項新政策能解決所有學習問題。"},{"en":"This phrase suggests wishful thinking rather than realistic planning.","zh":"這個短語暗示一廂情願，而不是現實計劃。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":9},{"front":"rewriting textbooks","meaning":"重寫教科書","examples":[{"en":"Rewriting textbooks may not solve the problem of history learning.","zh":"重寫教科書未必能解決歷史學習的問題。"},{"en":"Rewriting textbooks means changing or producing textbook content again.","zh":"rewriting textbooks 是指再次修改或編寫教科書內容。"},{"en":"A school may consider rewriting textbooks when the old content is inaccurate or outdated.","zh":"當舊內容不準確或過時時，學校可能考慮重寫教科書。"},{"en":"Rewriting textbooks can improve materials, but it cannot guarantee better teaching.","zh":"重寫教科書可以改善材料，但不能保證更好教學。"},{"en":"The passage suggests the problem may be the textbook model itself, not only the wording.","zh":"文章暗示問題可能是教科書模式本身，而不只是措辭。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":9},{"front":"how history is learned","meaning":"歷史如何被學習","examples":[{"en":"The debate concerns how history is learned.","zh":"這場辯論關乎歷史如何被學習。"},{"en":"How history is learned means the process through which students understand, remember, and use historical knowledge.","zh":"how history is learned 是指學生理解、記住和運用歷史知識的過程。"},{"en":"History is learned better when students connect facts with causes, people, and evidence.","zh":"當學生把事實與原因、人物和證據連接起來，歷史會學得更好。"},{"en":"If history is learned only by memorising dates, students may miss its meaning.","zh":"如果歷史只透過背日期來學習，學生可能會錯過其意義。"},{"en":"This phrase focuses on learning process rather than only teaching content.","zh":"這個短語集中於學習過程，而不只是教學內容。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":9},{"front":"the content of textbooks","meaning":"教科書內容","examples":[{"en":"The problem is not simply the content of textbooks.","zh":"問題不只是教科書內容。"},{"en":"The content of textbooks means the information, topics, examples, and explanations inside textbooks.","zh":"the content of textbooks 是指教科書中的資訊、題目、例子和解釋。"},{"en":"Teachers may update the content of textbooks when new research appears.","zh":"當新研究出現時，老師可能更新教科書內容。"},{"en":"Even good content can fail if students do not know how to use it.","zh":"即使內容很好，如果學生不知道如何使用它，也可能失效。"},{"en":"This phrase separates what textbooks say from how students learn from them.","zh":"這個短語把教科書說甚麼與學生如何從中學習分開。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":9},{"front":"the very idea of","meaning":"……這個概念本身","examples":[{"en":"The writer questions the very idea of textbooks.","zh":"作者質疑教科書這個概念本身。"},{"en":"The very idea of something means the basic concept itself, not just one example of it.","zh":"the very idea of something 是指基本概念本身，而不只是其中一個例子。"},{"en":"The teacher questioned the very idea of grading creativity with numbers.","zh":"老師質疑用分數評改創意這個概念本身。"},{"en":"If someone questions the very idea of exams, they are challenging the whole system of testing.","zh":"如果有人質疑考試這個概念本身，他就是在挑戰整個測驗制度。"},{"en":"This phrase makes the criticism deeper and more fundamental.","zh":"這個短語令批評更深入和更根本。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":9},{"front":"retain the information","meaning":"記住所載資料","examples":[{"en":"No human mind could retain all the information in a textbook.","zh":"沒有人腦能記住教科書中的所有資料。"},{"en":"To retain the information means to remember and keep it in the mind for later use.","zh":"retain the information 是指記住資訊，並把它保留在腦中以供日後使用。"},{"en":"Students retain information better when they connect it with stories and examples.","zh":"當學生把資訊與故事和例子連接起來時，他們更容易記住資料。"},{"en":"Too much information at once makes it harder to retain anything clearly.","zh":"一次過太多資訊會令人更難清楚記住任何內容。"},{"en":"This phrase focuses on memory, not just reading.","zh":"這個短語集中於記憶，而不只是閱讀。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":9},{"front":"crammed into","meaning":"塞進","examples":[{"en":"Too much information is crammed into history textbooks.","zh":"太多資訊被塞進歷史教科書。"},{"en":"Crammed into means forced into a small space or limited format.","zh":"crammed into 是指被強行塞進狹小空間或有限形式中。"},{"en":"Students feel overwhelmed when too many topics are crammed into one lesson.","zh":"當太多題目被塞進一堂課，學生會感到吃不消。"},{"en":"A suitcase can break if too many clothes are crammed into it.","zh":"如果太多衣服被塞進行李箱，行李箱可能會壞。"},{"en":"This phrase suggests overcrowding and lack of breathing room.","zh":"這個短語暗示過度擁擠和缺乏空間。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":9},{"front":"applied to","meaning":"應用於","examples":[{"en":"One lesson from history can be applied to every time period.","zh":"一個歷史教訓可以應用於每個時期。"},{"en":"Applied to means used in a particular situation or case.","zh":"applied to 是指被用於某個特定情況或個案。"},{"en":"A grammar rule can be applied to many sentences if students understand the pattern.","zh":"如果學生理解模式，一條文法規則可以應用於許多句子。"},{"en":"A safety lesson learned in one workplace can be applied to another.","zh":"在一個工作場所學到的安全教訓可以應用於另一個工作場所。"},{"en":"This phrase shows that an idea can be transferred beyond its original example.","zh":"這個短語顯示一個想法可以轉移到原本例子以外。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":9},{"front":"every time period","meaning":"每個時期","examples":[{"en":"Change can be observed in every time period.","zh":"變化可以在每個時期被觀察到。"},{"en":"Every time period means each historical era or span of years being discussed.","zh":"every time period 是指正在討論的每個歷史年代或時間跨度。"},{"en":"Students can study family life in every time period, from ancient societies to modern cities.","zh":"學生可以研究每個時期的家庭生活，從古代社會到現代城市。"},{"en":"Comparing every time period helps students see both change and continuity.","zh":"比較每個時期幫助學生看見變化和延續。"},{"en":"This phrase is broad and includes all stages of history under discussion.","zh":"這個短語很廣泛，包括討論中的所有歷史階段。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":9},{"front":"the only constant is change","meaning":"唯一不變的是變化","examples":[{"en":"History teaches us that the only constant is change.","zh":"歷史教導我們，唯一不變的是變化。"},{"en":"The only constant is change means the one thing that always continues is that things keep changing.","zh":"the only constant is change 是指唯一一直持續的事，就是事情不斷改變。"},{"en":"In technology, the only constant is change because new tools appear every year.","zh":"在科技中，唯一不變的是變化，因為新工具每年都出現。"},{"en":"Schools must adapt if the only constant is change in students’ lives.","zh":"如果學生生活中唯一不變的是變化，學校就必須適應。"},{"en":"This phrase reminds people not to treat old methods as permanently fixed.","zh":"這個短語提醒人們不要把舊方法視為永遠固定。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":9},{"front":"for that matter","meaning":"就此而言","examples":[{"en":"The teaching of any subject, for that matter, is no exception.","zh":"就此而言，任何科目的教學也不例外。"},{"en":"For that matter means the same point also applies to the thing just mentioned.","zh":"for that matter 是指同一點也適用於剛提到的事物。"},{"en":"History changes, and education, for that matter, must change too.","zh":"歷史會變，就此而言，教育也必須改變。"},{"en":"Good examples help in English, science, and maths, for that matter.","zh":"好例子對英文有幫助；就此而言，對科學和數學也有幫助。"},{"en":"This phrase adds another related case to strengthen the point.","zh":"這個短語加入另一個相關例子來加強重點。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":9},{"front":"no exception","meaning":"也不例外","examples":[{"en":"The teaching of history is no exception to the rule of change.","zh":"歷史教學對變化這條規則也不例外。"},{"en":"No exception means included in the same rule or pattern as everything else.","zh":"no exception 是指包含在與其他所有事物相同的規則或模式之中。"},{"en":"Every student must follow the safety rule; new students are no exception.","zh":"每位學生都必須遵守安全規則；新生也不例外。"},{"en":"Technology changes many jobs, and teaching is no exception.","zh":"科技改變許多工作，教學也不例外。"},{"en":"This phrase shows that one case should not be treated as separate.","zh":"這個短語顯示某個個案不應被視為例外。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":10},{"front":"bring new technologies into","meaning":"把新科技引入……","examples":[{"en":"The question is no longer whether to bring new technologies into education.","zh":"問題不再是是否把新科技引入教育。"},{"en":"To bring new technologies into something means to introduce digital tools or modern devices into that area.","zh":"bring new technologies into something 是指把數碼工具或現代設備引入某領域。"},{"en":"Schools bring new technologies into classrooms when they use tablets and online quizzes.","zh":"學校使用平板電腦和網上小測時，就是把新科技引入課室。"},{"en":"Bringing technology into education can support learning, but it needs clear teaching goals.","zh":"把科技引入教育可以支持學習，但需要清晰教學目標。"},{"en":"This phrase focuses on adoption, not whether the tool is automatically useful.","zh":"這個短語集中於採用，而不是科技是否自動有用。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":10},{"front":"everyday education","meaning":"日常教育","examples":[{"en":"Digital tools are now part of everyday education.","zh":"數碼工具現在是日常教育的一部分。"},{"en":"Everyday education means normal teaching and learning that happens regularly in schools or homes.","zh":"everyday education 是指在學校或家中定期發生的普通教與學。"},{"en":"Online homework platforms have become part of everyday education in many schools.","zh":"網上功課平台已成為許多學校日常教育的一部分。"},{"en":"When technology enters everyday education, teachers need rules for attention and source checking.","zh":"當科技進入日常教育時，老師需要關於注意力和資料核查的規則。"},{"en":"This phrase suggests that technology is no longer rare or special in learning.","zh":"這個短語暗示科技在學習中不再罕見或特別。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":10},{"front":"suitable for","meaning":"適合……","examples":[{"en":"Teachers must decide which technologies are suitable for history classrooms.","zh":"老師必須決定哪些科技適合歷史課室。"},{"en":"Suitable for means fitting the needs, level, or purpose of a situation.","zh":"suitable for 是指符合某情況的需要、水平或目的。"},{"en":"A short video may be suitable for younger students who need visual support.","zh":"短片可能適合需要視覺支援的年幼學生。"},{"en":"A tool is not suitable for class if it entertains students but confuses the topic.","zh":"如果工具只娛樂學生卻令題目混亂，它就不適合課堂。"},{"en":"Teachers should choose technology suitable for learning goals, not just because it looks modern.","zh":"老師應選擇適合學習目標的科技，而不是只因它看起來現代。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":10},{"front":"a range of topics","meaning":"一系列題材","examples":[{"en":"Technology must suit a range of topics in history lessons.","zh":"科技必須適合歷史課中的一系列題材。"},{"en":"A range of topics means several different subjects or areas within a course.","zh":"a range of topics 是指課程中的幾個不同主題或範疇。"},{"en":"A history teacher may cover a range of topics, including wars, revolutions, trade, and daily life.","zh":"歷史老師可能教授一系列題材，包括戰爭、革命、貿易和日常生活。"},{"en":"One teaching tool may not work equally well for every topic.","zh":"一種教學工具未必對每個題材都同樣有效。"},{"en":"This phrase shows variety rather than one narrow subject.","zh":"這個短語顯示多樣性，而不是單一狹窄主題。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":10},{"front":"junior high","meaning":"初中","examples":[{"en":"Junior high students may benefit from multimedia teaching.","zh":"初中學生可能受益於多媒體教學。"},{"en":"Junior high refers to the lower years of secondary school, usually for early teenagers.","zh":"junior high 是指中學較低年級，通常是早期青少年。"},{"en":"Junior high students often need clear examples and active tasks to stay engaged.","zh":"初中學生通常需要清晰例子和主動任務來保持投入。"},{"en":"Multimedia can help junior high learners understand difficult historical events.","zh":"多媒體可以幫助初中學習者理解困難歷史事件。"},{"en":"This phrase refers to school level, not student ability.","zh":"這個短語指學校年級，而不是學生能力。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":10},{"front":"high school history classrooms","meaning":"高中歷史課室","examples":[{"en":"Technology can be used in high school history classrooms.","zh":"科技可以用於高中歷史課室。"},{"en":"High school history classrooms are secondary school settings where older students learn history.","zh":"high school history classrooms 是較年長中學生學習歷史的中學課堂環境。"},{"en":"In high school history classrooms, students may analyse sources, timelines, and causes of events.","zh":"在高中歷史課室中，學生可能分析資料來源、時間線和事件原因。"},{"en":"Technology can support these classrooms by showing maps, speeches, and photographs.","zh":"科技可以透過展示地圖、演說和照片來支援這些課室。"},{"en":"The phrase points to a specific teaching environment.","zh":"這個短語指向一個特定教學環境。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":10},{"front":"fortunately","meaning":"幸好","examples":[{"en":"Fortunately, technology has provided new teaching opportunities.","zh":"幸好，科技提供了新的教學機會。"},{"en":"Fortunately means luckily or thankfully.","zh":"fortunately 是指幸運地或令人感到慶幸地。"},{"en":"The projector failed, but fortunately the teacher had printed copies.","zh":"投影機壞了，但幸好老師有印刷副本。"},{"en":"Fortunately, online archives allow students to see old documents without travelling.","zh":"幸好，網上檔案讓學生不用旅行也能看見舊文件。"},{"en":"This word introduces a positive fact after a problem or concern.","zh":"這個詞在問題或擔憂後引入正面事實。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":10},{"front":"provided us with opportunities to","meaning":"為我們提供機會去……","examples":[{"en":"Technology has provided teachers with opportunities to present lessons differently.","zh":"科技為老師提供機會，以不同方式呈現課堂。"},{"en":"Provided us with opportunities to means gave us chances to do something.","zh":"provided us with opportunities to 是指給我們機會去做某事。"},{"en":"Online platforms have provided students with opportunities to practise speaking after class.","zh":"網上平台為學生提供課後練習口語的機會。"},{"en":"A museum visit can provide learners with opportunities to see history directly.","zh":"博物館參觀可以為學習者提供直接看見歷史的機會。"},{"en":"This phrase links a resource with the useful actions it makes possible.","zh":"這個短語把某種資源與它所帶來的有用行動連接起來。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":10},{"front":"Civil War lesson plans","meaning":"美國南北戰爭教案","examples":[{"en":"Teachers can present Civil War lesson plans in new ways.","zh":"老師可以以新方式呈現美國南北戰爭教案。"},{"en":"Civil War lesson plans are teaching materials and activities about the American Civil War.","zh":"Civil War lesson plans 是關於美國南北戰爭的教學材料和活動。"},{"en":"A Civil War lesson plan may include maps, soldiers’ letters, photographs, and discussion questions.","zh":"美國南北戰爭教案可能包括地圖、士兵信件、照片和討論問題。"},{"en":"Good lesson plans help students understand causes, battles, and social consequences.","zh":"良好教案幫助學生理解原因、戰役和社會後果。"},{"en":"Multimedia can make Civil War lesson plans more vivid without replacing source analysis.","zh":"多媒體可以令美國南北戰爭教案更生動，而不取代資料來源分析。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":10},{"front":"American Revolution lesson plans","meaning":"美國獨立戰爭教案","examples":[{"en":"Teachers can use multimedia for American Revolution lesson plans.","zh":"老師可以把多媒體用於美國獨立戰爭教案。"},{"en":"American Revolution lesson plans are teaching plans about the struggle that led to the United States’ independence.","zh":"American Revolution lesson plans 是關於導致美國獨立的鬥爭的教學計劃。"},{"en":"Such plans may include speeches, political cartoons, timelines, and debates.","zh":"這類教案可能包括演說、政治漫畫、時間線和辯論。"},{"en":"Multimedia can help students see why revolution happened and how different groups reacted.","zh":"多媒體可以幫助學生看見革命為何發生，以及不同群體如何反應。"},{"en":"A good lesson plan connects dramatic events with evidence and historical context.","zh":"好教案會把戲劇性事件與證據和歷史背景連接起來。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":10},{"front":"in a variety of new ways","meaning":"以多種新方式","examples":[{"en":"Technology allows teachers to present history in a variety of new ways.","zh":"科技讓老師能以多種新方式呈現歷史。"},{"en":"In a variety of new ways means through many different fresh methods.","zh":"in a variety of new ways 是指透過許多不同的新鮮方法。"},{"en":"A teacher can explain vocabulary in a variety of new ways, such as games, pictures, and short dialogues.","zh":"老師可以透過遊戲、圖片和短對話，以多種新方式解釋詞彙。"},{"en":"Presenting information in varied ways can help students with different learning needs.","zh":"以多種方式呈現資訊，可以幫助有不同學習需要的學生。"},{"en":"This phrase stresses choice and flexibility.","zh":"這個短語強調選擇和彈性。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":11},{"front":"target and engage","meaning":"針對並吸引","examples":[{"en":"Teachers can target and engage today’s learners through multimedia.","zh":"老師可以透過多媒體針對並吸引今天的學習者。"},{"en":"To target and engage learners means to design teaching for them and keep them interested.","zh":"target and engage learners 是指為學習者設計教學並令他們保持興趣。"},{"en":"A teacher targets and engages shy students by using small-group tasks before whole-class speaking.","zh":"老師先用小組任務再全班發言，就是針對並吸引害羞學生。"},{"en":"Lessons engage students better when examples match their age, interests, and needs.","zh":"當例子符合學生年齡、興趣和需要時，課堂更能吸引學生。"},{"en":"This phrase combines planning for learners with holding their attention.","zh":"這個短語結合了針對學習者設計和維持注意力。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":11},{"front":"learners of this generation","meaning":"這一代學習者","examples":[{"en":"Multimedia can engage the learners of this generation.","zh":"多媒體可以吸引這一代學習者。"},{"en":"Learners of this generation are today’s students, who often grow up with digital media.","zh":"learners of this generation 是指今天的學生，他們通常伴隨數碼媒體成長。"},{"en":"Learners of this generation may respond well to images, short clips, and interactive tasks.","zh":"這一代學習者可能對圖片、短片和互動任務反應良好。"},{"en":"Teachers need to understand these learners’ habits before choosing teaching tools.","zh":"老師在選擇教學工具前，需要理解這些學習者的習慣。"},{"en":"This phrase links learning style with the time period students live in.","zh":"這個短語把學習方式與學生所處時代連接起來。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":11},{"front":"effectively combining","meaning":"有效結合","examples":[{"en":"Teachers can engage students by effectively combining history with multimedia.","zh":"老師可以透過有效結合歷史與多媒體來吸引學生。"},{"en":"Effectively combining means joining two things in a way that works well and produces a useful result.","zh":"effectively combining 是指把兩件事以有效並產生有用結果的方式結合。"},{"en":"A teacher can improve writing lessons by effectively combining grammar practice with real examples.","zh":"老師可以透過有效結合文法練習和真實例子來改善寫作課。"},{"en":"Combining tools effectively requires purpose; adding technology without reason may distract students.","zh":"有效結合工具需要目的；沒有理由地加入科技可能分散學生注意力。"},{"en":"This phrase stresses successful integration, not random mixing.","zh":"這個短語強調成功整合，而不是隨意混合。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":11},{"front":"the study of history","meaning":"歷史學習","examples":[{"en":"The study of history can be combined with innovative multimedia.","zh":"歷史學習可以與創新多媒體結合。"},{"en":"The study of history means learning about the past through events, people, causes, sources, and interpretations.","zh":"the study of history 是指透過事件、人物、原因、資料來源和詮釋來學習過去。"},{"en":"The study of history helps students understand how today’s society was shaped.","zh":"歷史學習幫助學生理解今天社會如何被塑造。"},{"en":"When students study history, they learn to ask what happened, why it happened, and why it matters.","zh":"當學生學習歷史時，他們學會問發生了甚麼、為何發生，以及為何重要。"},{"en":"History study becomes richer when facts are connected with evidence and human stories.","zh":"當事實與證據和人的故事連接起來時，歷史學習會更豐富。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":11},{"front":"innovative multimedia","meaning":"創新多媒體","examples":[{"en":"Innovative multimedia can make history lessons more engaging.","zh":"創新多媒體可以令歷史課更吸引。"},{"en":"Innovative multimedia means creative use of images, sound, video, animation, or interactive tools.","zh":"innovative multimedia 是指創意地使用圖像、聲音、影片、動畫或互動工具。"},{"en":"A museum uses innovative multimedia when visitors can hear old speeches while viewing photographs.","zh":"當博物館讓訪客一邊看照片一邊聽舊演說時，就是使用創新多媒體。"},{"en":"Innovative multimedia can help explain complex events, but it must be historically accurate.","zh":"創新多媒體可以幫助解釋複雜事件，但必須符合歷史準確性。"},{"en":"This phrase suggests new teaching resources that go beyond plain text.","zh":"這個短語暗示超越純文字的新教學資源。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":11},{"front":"PowerPoint presentations","meaning":"PowerPoint 簡報","examples":[{"en":"PowerPoint presentations can support history teaching.","zh":"PowerPoint 簡報可以支援歷史教學。"},{"en":"PowerPoint presentations are slide-based talks that combine text, images, charts, audio, or video.","zh":"PowerPoint 簡報是以投影片為基礎的講解，可結合文字、圖片、圖表、音訊或影片。"},{"en":"A teacher may use PowerPoint presentations to show a timeline beside historical photographs.","zh":"老師可能使用 PowerPoint 簡報，把時間線與歷史照片並列展示。"},{"en":"Good PowerPoint presentations organise information clearly and avoid overcrowded slides.","zh":"好的 PowerPoint 簡報會清楚組織資訊，避免投影片過度擁擠。"},{"en":"Slides should support explanation, not become a textbook copied onto a screen.","zh":"投影片應支援解釋，而不是把教科書複製到螢幕上。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":11},{"front":"in particular","meaning":"尤其是","examples":[{"en":"PowerPoint presentations, in particular, can expand classroom discussion.","zh":"尤其是 PowerPoint 簡報，可以擴大課堂討論。"},{"en":"In particular means especially one example from a wider group.","zh":"in particular 是指在較大群組中特別指出一個例子。"},{"en":"Visual sources, in particular, can help students imagine historical places.","zh":"尤其是視覺資料，可以幫助學生想像歷史地點。"},{"en":"PowerPoint, in particular, is useful when teachers need to combine text, images, and video.","zh":"尤其是 PowerPoint，當老師需要結合文字、圖片和影片時很有用。"},{"en":"This phrase points to one tool as especially relevant.","zh":"這個短語指出某一工具特別相關。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":11},{"front":"expand the scope of","meaning":"擴大……的範圍","examples":[{"en":"Multimedia can expand the scope of classroom discussion.","zh":"多媒體可以擴大課堂討論的範圍。"},{"en":"To expand the scope of something means to make it cover more topics, examples, or possibilities.","zh":"expand the scope of something 是指令某事涵蓋更多題目、例子或可能性。"},{"en":"A teacher can expand the scope of a lesson by adding local stories and global comparisons.","zh":"老師可以透過加入本地故事和全球比較來擴大課堂範圍。"},{"en":"Videos and images expand discussion because students can respond to more than written text.","zh":"影片和圖片擴大討論，因為學生可以回應不只是文字的材料。"},{"en":"This phrase suggests widening the range of learning.","zh":"這個短語暗示擴闊學習範圍。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":11},{"front":"traditional classroom discussion","meaning":"傳統課堂討論","examples":[{"en":"PowerPoint can add visual and audio support to traditional classroom discussion.","zh":"PowerPoint 可以為傳統課堂討論加入視覺和音訊支援。"},{"en":"Traditional classroom discussion means face-to-face conversation in class, usually led by a teacher.","zh":"traditional classroom discussion 是指課堂中面對面的對話，通常由老師引導。"},{"en":"Traditional classroom discussion can be effective when students prepare and listen carefully.","zh":"當學生有準備並仔細聆聽時，傳統課堂討論可以很有效。"},{"en":"Digital tools can enrich traditional discussion by adding images, maps, and recordings.","zh":"數碼工具可以透過加入圖片、地圖和錄音來豐富傳統討論。"},{"en":"The goal is not to replace discussion but to make it clearer and more engaging.","zh":"目標不是取代討論，而是令它更清楚和更吸引。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":11},{"front":"abstract concepts","meaning":"抽象概念","examples":[{"en":"Teachers can use multimedia to explain abstract concepts.","zh":"老師可以使用多媒體解釋抽象概念。"},{"en":"Abstract concepts are ideas that cannot be touched or easily seen, such as justice, power, or nationalism.","zh":"抽象概念是不能觸摸或不易看見的想法，例如正義、權力或民族主義。"},{"en":"A timeline can help explain the abstract concept of historical change.","zh":"時間線可以幫助解釋歷史變化這個抽象概念。"},{"en":"Students understand abstract concepts better when teachers give concrete examples.","zh":"當老師給出具體例子時，學生更容易理解抽象概念。"},{"en":"Multimedia can turn difficult ideas into images, stories, and comparisons.","zh":"多媒體可以把困難概念變成圖像、故事和比較。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":11},{"front":"accommodating","meaning":"配合；照顧","examples":[{"en":"PowerPoint can help teachers while accommodating different learning styles.","zh":"PowerPoint 可以幫助老師，同時配合不同學習方式。"},{"en":"Accommodating means making space for different needs, preferences, or situations.","zh":"accommodating 是指為不同需要、偏好或情況作出安排。"},{"en":"A school accommodates students with hearing difficulties by providing captions.","zh":"學校透過提供字幕來照顧有聽力困難的學生。"},{"en":"Teachers accommodate different learners when they combine speech, pictures, and written notes.","zh":"老師結合講解、圖片和文字筆記，就是照顧不同學習者。"},{"en":"This word suggests adjustment rather than one fixed method for everyone.","zh":"這個詞暗示調整，而不是對所有人使用一種固定方法。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":12},{"front":"unique learning styles","meaning":"獨特學習方式","examples":[{"en":"Students have unique learning styles.","zh":"學生有獨特學習方式。"},{"en":"Unique learning styles are the different ways students prefer to receive, process, and remember information.","zh":"unique learning styles 是學生偏好接收、處理和記住資訊的不同方式。"},{"en":"Some students learn well through images, while others need discussion or written notes.","zh":"有些學生透過圖像學得好，另一些則需要討論或文字筆記。"},{"en":"Recognising unique learning styles can help teachers design more balanced lessons.","zh":"認識獨特學習方式可以幫助老師設計更平衡的課堂。"},{"en":"The phrase should not mean labelling students permanently; learning preferences can change.","zh":"這個短語不應意味著永久標籤學生；學習偏好可以改變。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":12},{"front":"PowerPoint study units","meaning":"PowerPoint 學習單元","examples":[{"en":"PowerPoint study units can be prepared for history classrooms.","zh":"PowerPoint 學習單元可以為歷史課室準備。"},{"en":"PowerPoint study units are organised slide sets designed to teach a particular topic.","zh":"PowerPoint study units 是為教授特定題目而設計的有組織投影片組。"},{"en":"A study unit on World War II may include maps, photos, key dates, and questions.","zh":"關於第二次世界大戰的學習單元可能包括地圖、照片、重要日期和問題。"},{"en":"PowerPoint study units save teachers time if the materials are accurate and well designed.","zh":"如果材料準確且設計良好，PowerPoint 學習單元可以為老師節省時間。"},{"en":"Good units guide learning step by step rather than simply decorating a lecture.","zh":"好單元會一步步引導學習，而不是只裝飾講課。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":12},{"front":"pre-prepared for","meaning":"預先準備給……","examples":[{"en":"Some study units have been pre-prepared for history classrooms.","zh":"有些學習單元已預先準備給歷史課室使用。"},{"en":"Pre-prepared for something means made in advance for a particular use or audience.","zh":"pre-prepared for 是指為特定用途或對象預先製作。"},{"en":"A teacher may use worksheets pre-prepared for beginner learners.","zh":"老師可能使用預先準備給初學者的工作紙。"},{"en":"Pre-prepared materials save time, but teachers still need to adapt them to their class.","zh":"預先準備好的材料可以節省時間，但老師仍需要按班級調整。"},{"en":"This phrase stresses that the material is ready before the lesson begins.","zh":"這個短語強調材料在課堂開始前已準備好。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":12},{"front":"all manner of","meaning":"各式各樣的","examples":[{"en":"PowerPoint units may include all manner of visual and audio materials.","zh":"PowerPoint 單元可能包括各式各樣的視覺和音訊材料。"},{"en":"All manner of means many different kinds of something.","zh":"all manner of 是指許多不同種類的某事物。"},{"en":"A library offers all manner of books, magazines, maps, and digital resources.","zh":"圖書館提供各式各樣的書籍、雜誌、地圖和數碼資源。"},{"en":"A history lesson can use all manner of sources, from letters to photographs.","zh":"歷史課可以使用各式各樣的資料來源，從信件到照片。"},{"en":"This phrase gives a sense of wide variety.","zh":"這個短語帶出種類繁多的感覺。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":12},{"front":"audio clips","meaning":"音訊片段","examples":[{"en":"Audio clips can make history lessons more vivid.","zh":"音訊片段可以令歷史課更生動。"},{"en":"Audio clips are short pieces of recorded sound.","zh":"audio clips 是短錄音片段。"},{"en":"A teacher may play audio clips of speeches to help students hear historical voices.","zh":"老師可能播放演說音訊片段，幫助學生聽到歷史聲音。"},{"en":"Audio clips can support learners who understand better through listening.","zh":"音訊片段可以支援透過聆聽理解得更好的學習者。"},{"en":"They should be short and purposeful so students know what to listen for.","zh":"它們應簡短且有目的，讓學生知道要聽甚麼。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":12},{"front":"video clips","meaning":"影片片段","examples":[{"en":"Video clips can support classroom history teaching.","zh":"影片片段可以支援課堂歷史教學。"},{"en":"Video clips are short pieces of moving image, often with sound.","zh":"video clips 是短的活動影像片段，通常有聲音。"},{"en":"A teacher may use video clips to show historical footage or a museum explanation.","zh":"老師可能使用影片片段展示歷史影像或博物館解說。"},{"en":"Video clips can attract attention, but students still need questions to guide thinking.","zh":"影片片段可以吸引注意，但學生仍需要問題引導思考。"},{"en":"A good clip helps students see context, not just watch passively.","zh":"好片段幫助學生看見背景，而不只是被動觀看。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":12},{"front":"primary sources","meaning":"第一手資料","examples":[{"en":"Primary sources help students connect with historical evidence.","zh":"第一手資料幫助學生接觸歷史證據。"},{"en":"Primary sources are original materials from the time being studied.","zh":"primary sources 是來自所研究時代的原始材料。"},{"en":"Letters, diaries, photographs, speeches, and official documents can be primary sources.","zh":"信件、日記、照片、演說和官方文件都可以是第一手資料。"},{"en":"Primary sources make history feel more real because students examine evidence directly.","zh":"第一手資料令歷史更真實，因為學生直接檢視證據。"},{"en":"Students must ask who created the source, when, why, and for whom.","zh":"學生必須問來源由誰創作、何時創作、為何創作，以及為誰而創作。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":12},{"front":"make learning interactive and stimulating","meaning":"令學習互動且有趣","examples":[{"en":"Multimedia materials help make learning interactive and stimulating.","zh":"多媒體材料幫助令學習互動且有趣。"},{"en":"To make learning interactive and stimulating means to make students take part actively and feel interested.","zh":"make learning interactive and stimulating 是指令學生主動參與並感到有興趣。"},{"en":"A quiz game can make learning interactive because students must answer and discuss.","zh":"小測遊戲可以令學習具互動性，因為學生必須回答和討論。"},{"en":"Learning becomes stimulating when students see, hear, question, and connect ideas.","zh":"當學生能看、聽、提問和連接想法時，學習會變得有趣。"},{"en":"This phrase suggests active engagement rather than passive listening.","zh":"這個短語暗示主動投入，而不是被動聆聽。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":12},{"front":"enticing formats","meaning":"吸引人的形式","examples":[{"en":"Lessons in enticing formats may help students remember historical information.","zh":"以吸引人形式呈現的課堂可能幫助學生記住歷史資訊。"},{"en":"Enticing formats are attractive ways of presenting information that make people want to pay attention.","zh":"enticing formats 是吸引人的資訊呈現方式，令人想注意。"},{"en":"A timeline with images may be a more enticing format than a plain list of dates.","zh":"有圖片的時間線可能比純日期列表更吸引人。"},{"en":"Enticing formats can improve interest, but the content must still be accurate.","zh":"吸引人的形式可以提高興趣，但內容仍必須準確。"},{"en":"This phrase focuses on presentation style and appeal.","zh":"這個短語集中於呈現風格和吸引力。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":12},{"front":"technology-driven students","meaning":"科技主導的一代學生","examples":[{"en":"Technology-driven students may respond well to multimedia lessons.","zh":"科技主導的一代學生可能對多媒體課堂反應良好。"},{"en":"Technology-driven students are learners whose habits and expectations are strongly shaped by digital tools.","zh":"technology-driven students 是學習習慣和期望深受數碼工具塑造的學生。"},{"en":"Technology-driven students may prefer quick visual explanations before long reading tasks.","zh":"科技主導的學生可能在長閱讀任務前偏好快速視覺解釋。"},{"en":"Teachers can reach technology-driven students by using digital tools with clear learning aims.","zh":"老師可以透過有清晰學習目標的數碼工具接觸科技主導的學生。"},{"en":"This phrase does not mean students only like technology; it means technology influences how they learn.","zh":"這個短語不代表學生只喜歡科技；它表示科技影響他們如何學習。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":12},{"front":"retain the historical information","meaning":"記住歷史資料","examples":[{"en":"Students need to retain the historical information for exams.","zh":"學生需要為考試記住歷史資料。"},{"en":"To retain historical information means to remember facts, names, dates, and meanings about the past.","zh":"retain historical information 是指記住關於過去的事實、姓名、日期和意義。"},{"en":"Students retain historical information better when they link it to stories and causes.","zh":"當學生把歷史資料與故事和原因連接起來時，他們更容易記住。"},{"en":"Multimedia may help memory by giving students visual and auditory clues.","zh":"多媒體可以透過給學生視覺和聽覺線索來幫助記憶。"},{"en":"Retaining information is useful, but students also need to understand significance.","zh":"記住資料很有用，但學生也需要理解重要性。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":13},{"front":"standard exams","meaning":"標準考試","examples":[{"en":"Students need historical knowledge for standard exams.","zh":"學生需要歷史知識應付標準考試。"},{"en":"Standard exams are formal tests that many students take under the same rules and format.","zh":"standard exams 是許多學生在相同規則和格式下參加的正式測驗。"},{"en":"Schools prepare students for standard exams by practising common question types.","zh":"學校透過練習常見題型來幫學生準備標準考試。"},{"en":"Standard exams can measure shared knowledge, but they may not show every skill.","zh":"標準考試可以量度共同知識，但未必顯示每項能力。"},{"en":"This phrase refers to official or regular assessment, not casual class activities.","zh":"這個短語指官方或常規評估，而不是普通課堂活動。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":13},{"front":"whether you’re covering","meaning":"無論你正在教授……","examples":[{"en":"Whether you’re covering war or revolution, multimedia units can support the lesson.","zh":"無論你正在教授戰爭還是革命，多媒體單元都可以支援課堂。"},{"en":"Whether you’re covering something means no matter which topic you are teaching or discussing.","zh":"whether you’re covering something 是指無論你正在教授或討論哪個題目。"},{"en":"Whether you’re covering grammar or vocabulary, clear examples help students learn.","zh":"無論你正在教授文法還是詞彙，清晰例子都有助學生學習。"},{"en":"Whether a teacher covers politics or daily life, sources should be accurate.","zh":"無論老師教授政治還是日常生活，資料來源都應準確。"},{"en":"This phrase introduces different possible topics under the same general point.","zh":"這個短語在同一大重點下引入不同可能題目。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":13},{"front":"Revolutionary War lesson plans","meaning":"美國獨立戰爭教案","examples":[{"en":"PowerPoint units can support Revolutionary War lesson plans.","zh":"PowerPoint 單元可以支援美國獨立戰爭教案。"},{"en":"Revolutionary War lesson plans are teaching plans about the American War of Independence.","zh":"Revolutionary War lesson plans 是關於美國獨立戰爭的教學計劃。"},{"en":"These lesson plans may include maps, causes of conflict, important figures, and primary sources.","zh":"這些教案可能包括地圖、衝突原因、重要人物和第一手資料。"},{"en":"Multimedia can help students understand why different groups supported or opposed revolution.","zh":"多媒體可以幫助學生理解為何不同群體支持或反對革命。"},{"en":"A good plan connects battles with political ideas and ordinary people’s experiences.","zh":"好教案會把戰役與政治思想和普通人的經歷連接起來。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":13},{"front":"World War II lesson plans","meaning":"第二次世界大戰教案","examples":[{"en":"Multimedia can be used in World War II lesson plans.","zh":"多媒體可以用於第二次世界大戰教案。"},{"en":"World War II lesson plans are teaching materials about the causes, events, people, and consequences of the Second World War.","zh":"World War II lesson plans 是關於第二次世界大戰的原因、事件、人物和後果的教學材料。"},{"en":"A teacher may include maps, speeches, photographs, and survivor accounts in a World War II lesson.","zh":"老師可能在第二次世界大戰課堂中加入地圖、演說、照片和倖存者敘述。"},{"en":"Multimedia can help students understand the scale and human cost of the war.","zh":"多媒體可以幫助學生理解戰爭規模和人類代價。"},{"en":"These lessons should balance powerful images with careful explanation and context.","zh":"這些課堂應平衡震撼影像與仔細解釋和背景。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":13},{"front":"available in formats to suit","meaning":"有適合……的格式","examples":[{"en":"PowerPoint study units are available in formats to suit classroom needs.","zh":"PowerPoint 學習單元有適合課堂需要的格式。"},{"en":"Available in formats to suit means offered in versions designed for different purposes or situations.","zh":"available in formats to suit 是指以不同版本提供，以配合不同目的或情況。"},{"en":"Study notes may be available in formats to suit beginners, advanced learners, or exam revision.","zh":"溫習筆記可能有適合初學者、高階學習者或考試複習的格式。"},{"en":"Materials suit a class better when teachers can choose the right level and style.","zh":"當老師能選擇合適程度和風格時，材料會更適合班級。"},{"en":"This phrase highlights flexibility in how resources are prepared.","zh":"這個短語突顯資源準備方式的彈性。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":13},{"front":"suit the needs of","meaning":"配合……的需要","examples":[{"en":"Different teaching materials can suit the needs of different classrooms.","zh":"不同教學材料可以配合不同課室的需要。"},{"en":"To suit the needs of someone means to fit what that person or group requires.","zh":"suit the needs of someone 是指符合某人或某群體所需要的東西。"},{"en":"A beginner class needs materials that suit the needs of students with limited vocabulary.","zh":"初學班需要配合詞彙有限學生需要的材料。"},{"en":"Lessons suit students’ needs better when teachers know their level and goals.","zh":"當老師知道學生程度和目標時，課堂會更配合學生需要。"},{"en":"This phrase focuses on usefulness for a particular group.","zh":"這個短語集中於對特定群體的實用性。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":13},{"front":"multimedia teaching instruments","meaning":"多媒體教學工具","examples":[{"en":"Multimedia teaching instruments can improve student engagement.","zh":"多媒體教學工具可以改善學生投入度。"},{"en":"Multimedia teaching instruments are tools that use text, sound, images, video, or interaction to support teaching.","zh":"multimedia teaching instruments 是使用文字、聲音、圖片、影片或互動來支援教學的工具。"},{"en":"Slides, audio recordings, videos, and digital maps can be multimedia teaching instruments.","zh":"投影片、錄音、影片和數碼地圖都可以是多媒體教學工具。"},{"en":"These instruments can help students understand difficult ideas through more than one sense.","zh":"這些工具可以透過多於一種感官幫助學生理解困難概念。"},{"en":"They work best when teachers use them with clear questions and learning goals.","zh":"當老師配合清晰問題和學習目標使用它們時，效果最好。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":13},{"front":"producing positive results","meaning":"產生正面效果","examples":[{"en":"PowerPoint and similar tools are producing positive results worldwide.","zh":"PowerPoint 和類似工具正在全球各地產生正面效果。"},{"en":"Producing positive results means creating good effects or successful outcomes.","zh":"producing positive results 是指創造良好效果或成功結果。"},{"en":"Daily reading practice can produce positive results in vocabulary and confidence.","zh":"每日閱讀練習可以在詞彙和信心方面產生正面效果。"},{"en":"A teaching tool produces positive results only if students learn more clearly from it.","zh":"只有當學生從工具中學得更清楚時，教學工具才算產生正面效果。"},{"en":"This phrase focuses on actual benefits, not just attractive appearance.","zh":"這個短語集中於實際好處，而不只是吸引外觀。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":13},{"front":"worldwide","meaning":"全球各地","examples":[{"en":"Multimedia teaching tools are being used worldwide.","zh":"多媒體教學工具正在全球各地被使用。"},{"en":"Worldwide means in many countries or across the whole world.","zh":"worldwide 是指在許多國家或整個世界範圍內。"},{"en":"Online lessons can reach students worldwide if internet access is available.","zh":"如果有互聯網，網上課程可以接觸全球各地學生。"},{"en":"A teaching method used worldwide may still need local adaptation.","zh":"全球各地使用的教學方法仍可能需要本地調整。"},{"en":"This word emphasises broad international use.","zh":"這個詞強調廣泛的國際使用。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":13},{"front":"framing conventional lectures with","meaning":"以……配合傳統講課","examples":[{"en":"Multimedia tools frame conventional lectures with written, auditory and visual content.","zh":"多媒體工具以文字、聽覺和視覺內容配合傳統講課。"},{"en":"Framing conventional lectures with something means surrounding or supporting traditional talks with extra materials.","zh":"framing conventional lectures with something 是指用額外材料包圍或支援傳統講授。"},{"en":"A teacher can frame a lecture with photos and questions to make students think actively.","zh":"老師可以用照片和問題配合講課，令學生主動思考。"},{"en":"Framing a lecture with visuals can make abstract information easier to follow.","zh":"用視覺材料配合講課，可以令抽象資訊更容易跟上。"},{"en":"This phrase suggests adding structure and support around a lecture.","zh":"這個短語暗示在講課周圍加入結構和支援。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":13},{"front":"conventional lectures","meaning":"傳統講課","examples":[{"en":"Conventional lectures can be strengthened with multimedia support.","zh":"傳統講課可以透過多媒體支援而加強。"},{"en":"Conventional lectures are traditional teacher-led talks where students mainly listen and take notes.","zh":"conventional lectures 是由老師主導、學生主要聆聽和記筆記的傳統講授。"},{"en":"Conventional lectures work well when the teacher explains clearly and organises ideas logically.","zh":"當老師解釋清楚並有邏輯地組織想法時，傳統講課可以有效。"},{"en":"They may become boring if students only listen without questions, examples, or interaction.","zh":"如果學生只聽而沒有問題、例子或互動，講課可能變得沉悶。"},{"en":"Multimedia can improve conventional lectures by adding evidence, images, and sound.","zh":"多媒體可以透過加入證據、圖像和聲音來改善傳統講課。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":14},{"front":"captivating written, auditory and visual content","meaning":"引人入勝的文字、聽覺和視覺內容","examples":[{"en":"Multimedia lessons include captivating written, auditory and visual content.","zh":"多媒體課堂包括引人入勝的文字、聽覺和視覺內容。"},{"en":"Captivating written, auditory and visual content means attractive text, sound, and images that hold attention.","zh":"captivating written, auditory and visual content 是指能吸引注意的文字、聲音和圖像。"},{"en":"A history slide with a diary excerpt, a speech recording, and a photograph can be captivating.","zh":"一張包含日記摘錄、演說錄音和照片的歷史投影片可以很引人入勝。"},{"en":"Such content helps students remember because it gives several kinds of learning clues.","zh":"這類內容提供幾種學習線索，因此幫助學生記憶。"},{"en":"Captivating content should still be accurate and connected to the lesson aim.","zh":"引人入勝的內容仍應準確並與課堂目標有關。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":14},{"front":"recall names, dates and causal relationships","meaning":"記起姓名、日期和因果關係","examples":[{"en":"Multimedia can help students recall names, dates and causal relationships.","zh":"多媒體可以幫助學生記起姓名、日期和因果關係。"},{"en":"To recall names, dates and causal relationships means to remember people, times, and why events happened.","zh":"recall names, dates and causal relationships 是指記住人物、時間，以及事件為何發生。"},{"en":"A timeline can help students recall dates, while a diagram can show causes and effects.","zh":"時間線可以幫助學生記起日期，而圖表可以顯示因果。"},{"en":"Students remember history better when names and dates are connected to clear stories.","zh":"當姓名和日期與清晰故事連接起來時，學生更容易記住歷史。"},{"en":"This phrase includes both factual memory and understanding of connections.","zh":"這個短語包括事實記憶和對關係的理解。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":14},{"front":"causal relationships","meaning":"因果關係","examples":[{"en":"History students need to understand causal relationships.","zh":"歷史學生需要理解因果關係。"},{"en":"Causal relationships are connections showing how one event, action, or condition leads to another.","zh":"causal relationships 是顯示一個事件、行動或條件如何導致另一個結果的連繫。"},{"en":"Students study causal relationships when they ask why a war began or why a revolution spread.","zh":"學生問戰爭為何開始或革命為何擴散時，就是在研究因果關係。"},{"en":"Understanding causal relationships prevents history from becoming only a list of dates.","zh":"理解因果關係可以防止歷史變成只有日期列表。"},{"en":"This phrase is about cause and effect, not just sequence.","zh":"這個短語關於因與果，而不只是先後次序。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":14},{"front":"within a historical context","meaning":"在歷史背景中","examples":[{"en":"Students should understand events within a historical context.","zh":"學生應在歷史背景中理解事件。"},{"en":"Within a historical context means considering the time, place, beliefs, conditions, and events surrounding something.","zh":"within a historical context 是指考慮某事周圍的時間、地點、信念、條件和事件。"},{"en":"A law may seem strange unless students study it within its historical context.","zh":"如果學生不在歷史背景中研究某條法律，它可能顯得奇怪。"},{"en":"Understanding context helps students avoid judging the past only by today’s standards.","zh":"理解背景幫助學生避免只用今天標準判斷過去。"},{"en":"This phrase reminds learners that events do not happen in isolation.","zh":"這個短語提醒學習者，事件不是孤立發生的。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":14},{"front":"continues to show us that","meaning":"繼續向我們顯示","examples":[{"en":"History continues to show us that new times bring new realities.","zh":"歷史繼續向我們顯示，新時代帶來新現實。"},{"en":"Continues to show us that means keeps giving evidence or lessons about something.","zh":"continues to show us that 是指持續給我們關於某事的證據或教訓。"},{"en":"Experience continues to show us that students learn better with clear feedback.","zh":"經驗繼續向我們顯示，學生在有清晰回饋時學得更好。"},{"en":"History continues to show us that societies change when technology changes.","zh":"歷史繼續向我們顯示，當科技改變時，社會也會改變。"},{"en":"This phrase suggests an ongoing lesson, not a one-time discovery.","zh":"這個短語暗示持續性的教訓，而不是一次性的發現。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":14},{"front":"new times bring new realities","meaning":"新時代帶來新現實","examples":[{"en":"New times bring new realities in education.","zh":"新時代為教育帶來新現實。"},{"en":"New times bring new realities means new periods create new conditions, problems, and expectations.","zh":"new times bring new realities 是指新時期創造新的條件、問題和期望。"},{"en":"Online work shows that new times bring new realities for offices and families.","zh":"網上工作顯示，新時代為辦公室和家庭帶來新現實。"},{"en":"When students grow up with digital media, education faces new realities.","zh":"當學生伴隨數碼媒體成長，教育就面對新現實。"},{"en":"This phrase explains why old methods may need adjustment.","zh":"這個短語解釋了為何舊方法可能需要調整。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":14},{"front":"no exception to the rule","meaning":"不例外","examples":[{"en":"Education is no exception to the rule of change.","zh":"教育對變化這條規則並不例外。"},{"en":"No exception to the rule means included in the same general pattern as everything else.","zh":"no exception to the rule 是指包含在與其他事物相同的一般規律之中。"},{"en":"Technology changes work, shopping, and transport; schools are no exception to the rule.","zh":"科技改變工作、購物和交通；學校也不例外。"},{"en":"A student’s routine must change during exam season, and rest is no exception to the rule.","zh":"考試季節學生作息必須改變，休息也不例外。"},{"en":"This phrase shows that one case follows a wider principle.","zh":"這個短語顯示某個個案符合更廣泛原則。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":14},{"front":"educational environment","meaning":"教育環境","examples":[{"en":"Technology now belongs in the educational environment.","zh":"科技現在屬於教育環境的一部分。"},{"en":"Educational environment means the setting, tools, relationships, and conditions in which learning happens.","zh":"educational environment 是指學習發生時的環境、工具、關係和條件。"},{"en":"A quiet classroom, supportive teacher, and useful resources create a good educational environment.","zh":"安靜課室、支持性的老師和有用資源創造良好的教育環境。"},{"en":"Digital tools change the educational environment by adding new ways to access information.","zh":"數碼工具透過加入取得資訊的新方式，改變教育環境。"},{"en":"This phrase includes more than the classroom building; it includes how learning is organised.","zh":"這個短語不只包括課室建築，也包括學習如何被組織。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":14},{"front":"rather","meaning":"而是","examples":[{"en":"The question is not whether to use technology; rather, it is which technology to use.","zh":"問題不是是否使用科技；而是使用哪種科技。"},{"en":"Rather is used to correct or replace one idea with a more accurate one.","zh":"rather 用於糾正或取代一個想法，並提出更準確的說法。"},{"en":"The problem is not that students dislike history; rather, they may dislike how it is taught.","zh":"問題不是學生不喜歡歷史；而是他們可能不喜歡歷史的教學方式。"},{"en":"A teacher should not ask whether examples matter; rather, the question is which examples work best.","zh":"老師不應問例子是否重要；而是應問哪些例子最有效。"},{"en":"This word helps shift the focus of an argument.","zh":"這個詞幫助轉移論點焦點。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":14},{"front":"U.S. and world history subjects","meaning":"美國及世界歷史科目","examples":[{"en":"Teachers use multimedia for U.S. and world history subjects.","zh":"老師把多媒體用於美國及世界歷史科目。"},{"en":"U.S. and world history subjects are courses about American history and global historical events.","zh":"U.S. and world history subjects 是關於美國歷史和全球歷史事件的課程。"},{"en":"A school may teach U.S. history in one year and world history in another.","zh":"學校可能一年教授美國歷史，另一年教授世界歷史。"},{"en":"Multimedia can help students compare national events with wider world changes.","zh":"多媒體可以幫助學生比較國家事件與更廣泛世界變化。"},{"en":"This phrase covers both local national history and international history.","zh":"這個短語涵蓋本國歷史和國際歷史。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":14},{"front":"Cold War lesson plans","meaning":"冷戰教案","examples":[{"en":"PowerPoint presentations can support Cold War lesson plans.","zh":"PowerPoint 簡報可以支援冷戰教案。"},{"en":"Cold War lesson plans are teaching materials about the political tension between the United States and the Soviet Union after World War II.","zh":"Cold War lesson plans 是關於二戰後美國與蘇聯之間政治緊張的教學材料。"},{"en":"A Cold War lesson may include maps, speeches, propaganda posters, and timelines.","zh":"冷戰課堂可能包括地圖、演說、宣傳海報和時間線。"},{"en":"Multimedia can help students understand fear, ideology, and global competition during the Cold War.","zh":"多媒體可以幫助學生理解冷戰期間的恐懼、意識形態和全球競爭。"},{"en":"Good lesson plans explain not only events but also causes and consequences.","zh":"好教案不只解釋事件，也解釋原因和後果。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":15},{"front":"pre-packaged formats","meaning":"預先包裝好的格式","examples":[{"en":"PowerPoint presentations are available in pre-packaged formats.","zh":"PowerPoint 簡報有預先包裝好的格式。"},{"en":"Pre-packaged formats are ready-made versions prepared for easy use.","zh":"pre-packaged formats 是為方便使用而預先製作好的版本。"},{"en":"Teachers may download pre-packaged formats for quizzes, revision slides, or lesson summaries.","zh":"老師可能下載用於小測、複習投影片或課堂摘要的預先包裝格式。"},{"en":"Pre-packaged formats save time, but they may need adaptation for a specific class.","zh":"預先包裝好的格式節省時間，但可能需要按特定班級調整。"},{"en":"This phrase suggests convenience, not necessarily perfect quality.","zh":"這個短語暗示方便，但不一定代表完美質素。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":15},{"front":"meanwhile","meaning":"與此同時","examples":[{"en":"Meanwhile, some academic historians hold a different view.","zh":"與此同時，有些學院派歷史學家持不同看法。"},{"en":"Meanwhile means at the same time or in contrast with what has just been described.","zh":"meanwhile 是指同時，或與剛才描述的情況形成對照。"},{"en":"Students worked on the project; meanwhile, the teacher prepared feedback.","zh":"學生做項目；與此同時，老師準備回饋。"},{"en":"Technology supporters praise multimedia; meanwhile, some historians remain cautious.","zh":"科技支持者讚揚多媒體；與此同時，有些歷史學家仍然謹慎。"},{"en":"This word helps move to another related situation happening at the same time.","zh":"這個詞幫助轉到同時發生的另一個相關情況。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":15},{"front":"academic historians","meaning":"學院派歷史學家","examples":[{"en":"Some academic historians are cautious about technology in teaching.","zh":"有些學院派歷史學家對教學中的科技保持謹慎。"},{"en":"Academic historians are scholars who study and teach history in universities or research institutions.","zh":"academic historians 是在大學或研究機構研究和教授歷史的學者。"},{"en":"Academic historians often focus on evidence, sources, interpretation, and historical method.","zh":"學院派歷史學家常集中於證據、資料來源、詮釋和歷史方法。"},{"en":"Some academic historians worry that flashy media may weaken careful source analysis.","zh":"有些學院派歷史學家擔心花巧媒體可能削弱仔細資料分析。"},{"en":"This phrase refers to professional historians, not casual history fans.","zh":"這個短語指專業歷史學家，而不是一般歷史愛好者。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":15},{"front":"hold a different view on","meaning":"對……持不同看法","examples":[{"en":"Some historians hold a different view on the use of technology.","zh":"有些歷史學家對科技的使用持不同看法。"},{"en":"To hold a different view on something means to have another opinion about it.","zh":"hold a different view on something 是指對某事有另一種意見。"},{"en":"Parents may hold different views on how much homework children need.","zh":"家長可能對孩子需要多少功課持不同看法。"},{"en":"Historians can hold different views on technology while still caring about good teaching.","zh":"歷史學家可以對科技持不同看法，同時仍關心良好教學。"},{"en":"This phrase is useful for showing disagreement politely.","zh":"這個短語適合用來禮貌地表示分歧。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":15},{"front":"the use of technology","meaning":"科技的使用","examples":[{"en":"The use of technology in history teaching remains debated.","zh":"科技在歷史教學中的使用仍然受到爭論。"},{"en":"The use of technology means the act of applying digital tools, devices, or systems to a task.","zh":"the use of technology 是指把數碼工具、設備或系統應用於某項任務。"},{"en":"The use of technology in class can include videos, online quizzes, and digital archives.","zh":"課堂中科技的使用可以包括影片、網上小測和數碼檔案。"},{"en":"Technology use becomes helpful when it supports clear learning goals.","zh":"當科技支持清晰學習目標時，其使用就有幫助。"},{"en":"This phrase focuses on how tools are used, not just whether they exist.","zh":"這個短語集中於工具如何被使用，而不只是科技是否存在。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":15},{"front":"not all facts can be recorded","meaning":"並非所有事實都能被記錄","examples":[{"en":"Some historians argue that not all facts can be recorded on film or video.","zh":"有些歷史學家主張，並非所有事實都能以電影或影片形式記錄。"},{"en":"Not all facts can be recorded means some information cannot be captured directly in a visual or audio form.","zh":"not all facts can be recorded 是指有些資訊不能直接以視覺或音訊形式捕捉。"},{"en":"A person’s private thoughts cannot always be recorded in a photograph.","zh":"一個人的私人想法不一定能在照片中被記錄。"},{"en":"Some historical facts survive only in letters, documents, or later accounts.","zh":"有些歷史事實只保存在信件、文件或後來記述中。"},{"en":"This phrase warns that video evidence has limits.","zh":"這個短語提醒人們，影片證據有其限制。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":15},{"front":"on film or video","meaning":"以電影或影片形式","examples":[{"en":"Not all historical facts can be recorded on film or video.","zh":"並非所有歷史事實都能以電影或影片形式記錄。"},{"en":"On film or video means captured as moving images, usually with sound.","zh":"on film or video 是指以活動影像形式捕捉，通常帶有聲音。"},{"en":"Modern protests may be recorded on video, but people’s motives still need explanation.","zh":"現代抗議可能以影片形式記錄，但人們的動機仍需要解釋。"},{"en":"Events before cameras existed cannot be shown directly on film or video.","zh":"相機出現前的事件無法直接以電影或影片形式展示。"},{"en":"This phrase contrasts visual recording with written or other sources.","zh":"這個短語把視覺記錄與書面或其他資料來源作對比。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":15},{"front":"written sources","meaning":"書面資料","examples":[{"en":"Written sources may be more suitable than video in some cases.","zh":"在某些情況下，書面資料可能比影片更合適。"},{"en":"Written sources are texts such as letters, books, reports, diaries, laws, or newspapers.","zh":"written sources 是文字資料，例如信件、書籍、報告、日記、法律或報紙。"},{"en":"Historians use written sources to study ideas, decisions, and personal experiences from the past.","zh":"歷史學家使用書面資料研究過去的思想、決策和個人經驗。"},{"en":"Written sources can preserve facts that were never filmed or photographed.","zh":"書面資料可以保存從未被拍攝或攝影的事實。"},{"en":"Students must read written sources carefully because wording and context matter.","zh":"學生必須仔細閱讀書面資料，因為措辭和背景都重要。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":15},{"front":"more suitable in such cases","meaning":"在這些情況下更合適","examples":[{"en":"Written sources are more suitable in such cases.","zh":"書面資料在這些情況下更合適。"},{"en":"More suitable in such cases means better fitted to those particular situations.","zh":"more suitable in such cases 是指更符合那些特定情況。"},{"en":"A written instruction sheet may be more suitable than a video when students need exact wording.","zh":"當學生需要精確措辭時，書面指示可能比影片更合適。"},{"en":"Maps are more suitable in some cases because they show location more clearly than paragraphs.","zh":"在某些情況下，地圖更合適，因為它比段落更清楚顯示位置。"},{"en":"This phrase compares usefulness in a specific context.","zh":"這個短語是在特定背景中比較實用性。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":15},{"front":"another challenge","meaning":"另一個挑戰","examples":[{"en":"Another challenge is the difficulty of learning new technologies.","zh":"另一個挑戰是學習新科技的困難。"},{"en":"Another challenge means an additional problem or difficulty besides those already mentioned.","zh":"another challenge 是指除了已提到的問題之外的另一個困難。"},{"en":"Online teaching saves travel time, but another challenge is keeping students focused.","zh":"網上教學節省交通時間，但另一個挑戰是令學生保持專注。"},{"en":"A project may solve one issue and still face another challenge later.","zh":"項目可能解決一個問題，但之後仍面對另一個挑戰。"},{"en":"This phrase helps add a new problem to a discussion.","zh":"這個短語幫助在討論中加入新問題。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":15},{"front":"the difficult process of","meaning":"……的困難過程","examples":[{"en":"Some teachers face the difficult process of learning new technologies.","zh":"有些老師面對學習新科技的困難過程。"},{"en":"The difficult process of something means the hard series of steps needed to do or learn it.","zh":"the difficult process of something 是指完成或學習某事所需的一連串困難步驟。"},{"en":"New nurses go through the difficult process of learning hospital systems.","zh":"新護士經歷學習醫院系統的困難過程。"},{"en":"The difficult process of changing teaching habits can take time and support.","zh":"改變教學習慣的困難過程可能需要時間和支援。"},{"en":"This phrase stresses that success requires effort over several stages.","zh":"這個短語強調成功需要經過多個階段的努力。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":16},{"front":"learning new technologies","meaning":"學習新科技","examples":[{"en":"Learning new technologies can be difficult for some historians.","zh":"對有些歷史學家而言，學習新科技可能很困難。"},{"en":"Learning new technologies means gaining the skills to use new digital tools or systems.","zh":"learning new technologies 是指獲得使用新數碼工具或系統的技能。"},{"en":"Teachers may need training when learning new technologies such as editing software.","zh":"老師學習剪輯軟件等新科技時，可能需要培訓。"},{"en":"Learning new technologies can feel stressful if people fear making mistakes.","zh":"如果人們害怕犯錯，學習新科技可能令人感到壓力。"},{"en":"With support and practice, new tools can become part of normal teaching.","zh":"有支援和練習時，新工具可以成為正常教學的一部分。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":16},{"front":"creating PowerPoint presentations","meaning":"製作 PowerPoint 簡報","examples":[{"en":"Creating PowerPoint presentations can be challenging for some teachers.","zh":"對有些老師而言，製作 PowerPoint 簡報可能具挑戰性。"},{"en":"Creating PowerPoint presentations means designing slide shows with text, images, and sometimes sound or video.","zh":"creating PowerPoint presentations 是指設計包含文字、圖片，有時包含聲音或影片的投影片。"},{"en":"A teacher creating PowerPoint presentations must decide what to put on slides and what to explain orally.","zh":"製作 PowerPoint 簡報的老師必須決定哪些內容放在投影片上，哪些口頭解釋。"},{"en":"Poor slide design can make a presentation confusing even if the content is useful.","zh":"即使內容有用，差劣投影片設計也會令簡報混亂。"},{"en":"This task becomes easier when teachers use clear templates and avoid overcrowding.","zh":"當老師使用清晰模板並避免過度擁擠時，這項任務會更容易。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":16},{"front":"editing audio and video clips","meaning":"剪輯音訊和影片片段","examples":[{"en":"Some teachers find editing audio and video clips difficult.","zh":"有些老師覺得剪輯音訊和影片片段很困難。"},{"en":"Editing audio and video clips means cutting, arranging, shortening, or improving recorded sound and moving images.","zh":"editing audio and video clips 是指剪裁、排列、縮短或改善錄音和活動影像。"},{"en":"A teacher may edit a long documentary into a short clip for class.","zh":"老師可能把長紀錄片剪輯成課堂用的短片段。"},{"en":"Editing clips takes time because teachers must choose the most relevant parts.","zh":"剪輯片段需要時間，因為老師必須選擇最相關的部分。"},{"en":"Good editing supports learning by removing distractions and highlighting key evidence.","zh":"良好剪輯透過移除干擾和突出關鍵證據來支援學習。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":16},{"front":"particularly understandable for","meaning":"對……尤其可以理解","examples":[{"en":"This difficulty is particularly understandable for some older historians.","zh":"這種困難對有些年長歷史學家尤其可以理解。"},{"en":"Particularly understandable for someone means especially easy to sympathise with in that person’s situation.","zh":"particularly understandable for someone 是指在某人的情況下特別容易理解或同情。"},{"en":"Fear of online banking is particularly understandable for people who have never used computers.","zh":"對從未使用電腦的人而言，害怕網上銀行尤其可以理解。"},{"en":"Difficulty with new software is understandable when teachers were trained before digital tools became common.","zh":"當老師在數碼工具普及前受訓時，難以使用新軟件是可以理解的。"},{"en":"This phrase explains why a problem is reasonable for a specific group.","zh":"這個短語解釋為何某問題對特定群體而言是合理的。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":16},{"front":"older historians","meaning":"年長歷史學家","examples":[{"en":"Older historians may find new technologies harder to learn.","zh":"年長歷史學家可能覺得新科技較難學習。"},{"en":"Older historians are historians who belong to an earlier generation or have worked for many years.","zh":"older historians 是屬於較早世代或已工作多年的歷史學家。"},{"en":"Older historians may have strong experience with written sources and archives.","zh":"年長歷史學家可能在書面資料和檔案方面有豐富經驗。"},{"en":"Some older historians may resist technology because it was not part of their original training.","zh":"有些年長歷史學家可能抗拒科技，因為它不是他們原本訓練的一部分。"},{"en":"Age alone does not decide ability, but experience can shape comfort with new tools.","zh":"年齡本身不決定能力，但經驗會塑造對新工具的熟悉程度。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":16},{"front":"Reading Passage 2","meaning":"閱讀篇章二","examples":[{"en":"Reading Passage 2 has seven paragraphs.","zh":"閱讀篇章二有七段。"},{"en":"Reading Passage 2 means the second reading text in a test or exercise.","zh":"Reading Passage 2 是測驗或練習中的第二篇閱讀文章。"},{"en":"Students should check the instructions for Reading Passage 2 before answering questions.","zh":"學生回答問題前應檢查閱讀篇章二的指示。"},{"en":"If Reading Passage 2 has seven paragraphs, heading questions may ask students to match each paragraph.","zh":"如果閱讀篇章二有七段，標題配對題可能要求學生配對每段。"},{"en":"This phrase is mainly used in exam instructions.","zh":"這個短語主要用於考試指示。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":16},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Students choose the correct heading for each paragraph.","zh":"學生為每一段選出正確標題。"},{"en":"To choose the correct heading means to select the title that best matches a paragraph’s main idea.","zh":"choose the correct heading 是指選擇最符合段落主旨的標題。"},{"en":"In reading exams, students should read the whole paragraph before choosing a heading.","zh":"在閱讀考試中，學生應讀完整段後才選標題。"},{"en":"A wrong heading may match one detail but miss the paragraph’s overall purpose.","zh":"錯誤標題可能符合某個細節，但錯過段落整體目的。"},{"en":"This task tests main-idea understanding, not just word matching.","zh":"這項任務測試主旨理解，而不只是詞語配對。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":16},{"front":"for each paragraph","meaning":"為每一段","examples":[{"en":"The task requires one heading for each paragraph.","zh":"任務要求為每一段選一個標題。"},{"en":"For each paragraph means for every separate paragraph in the passage.","zh":"for each paragraph 是指為文章中的每一個獨立段落。"},{"en":"Students should write one answer for each paragraph listed in the question.","zh":"學生應為題目列出的每一段寫一個答案。"},{"en":"If there are seven paragraphs, students may need to choose seven headings.","zh":"如果有七段，學生可能需要選七個標題。"},{"en":"This phrase prevents students from answering only part of the task.","zh":"這個短語防止學生只完成部分任務。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":16},{"front":"from the list of headings below","meaning":"從以下標題列表中","examples":[{"en":"The heading must be chosen from the list of headings below.","zh":"標題必須從以下標題列表中選出。"},{"en":"From the list of headings below means using only the options provided under the instruction.","zh":"from the list of headings below 是指只使用指示下提供的選項。"},{"en":"Students should not create their own heading if the answer must come from the list.","zh":"如果答案必須來自列表，學生不應自己創作標題。"},{"en":"The correct heading is usually one of several options, not a sentence copied from the paragraph.","zh":"正確標題通常是幾個選項之一，而不是從段落抄一句。"},{"en":"This phrase limits the answer choices.","zh":"這個短語限制答案選項。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":16},{"front":"write the correct number","meaning":"寫下正確編號","examples":[{"en":"Students write the correct number in the answer boxes.","zh":"學生在答案格中寫下正確編號。"},{"en":"To write the correct number means to enter the number that matches the chosen answer.","zh":"write the correct number 是指填入與所選答案相符的編號。"},{"en":"In heading questions, students may write Roman numerals instead of letters.","zh":"在標題配對題中，學生可能寫羅馬數字而不是字母。"},{"en":"A student can lose marks if the correct number is written in the wrong answer box.","zh":"如果正確編號寫在錯誤答案格中，學生可能失分。"},{"en":"This phrase reminds students to follow the required answer format.","zh":"這個短語提醒學生跟隨指定答案格式。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":16},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生把答案寫在答題紙上。"},{"en":"An answer sheet is the paper or digital form where test-takers record their answers.","zh":"answer sheet 是考生記錄答案的紙張或電子表格。"},{"en":"Students should check the answer sheet before time ends.","zh":"學生應在時間結束前檢查答題紙。"},{"en":"A correct answer may be lost if it is written in the wrong box on the answer sheet.","zh":"如果正確答案寫在答題紙錯誤格子中，可能會失分。"},{"en":"In exams, accurate answer-sheet marking is part of good test technique.","zh":"在考試中，準確填寫答題紙是良好應試技巧的一部分。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":17},{"front":"the inevitability of change","meaning":"變化的必然性","examples":[{"en":"The heading refers to the inevitability of change when choosing technology.","zh":"這個標題指選擇科技時變化的必然性。"},{"en":"The inevitability of change means change cannot be avoided.","zh":"the inevitability of change 是指變化無法避免。"},{"en":"The inevitability of change is clear when old jobs require new digital skills.","zh":"當舊工作需要新數碼技能時，變化的必然性很清楚。"},{"en":"Schools must plan for change because society and students keep changing.","zh":"學校必須為變化作計劃，因為社會和學生不斷改變。"},{"en":"This phrase presents change as something unavoidable, not optional.","zh":"這個短語把變化呈現為不可避免，而不是可選擇的事。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":17},{"front":"selecting technologies","meaning":"選擇科技","examples":[{"en":"Teachers must consider several factors when selecting technologies.","zh":"老師在選擇科技時必須考慮幾個因素。"},{"en":"Selecting technologies means choosing which digital tools or systems to use.","zh":"selecting technologies 是指選擇使用哪些數碼工具或系統。"},{"en":"A teacher selecting technologies should consider student age, lesson aim, cost, and ease of use.","zh":"老師選擇科技時，應考慮學生年齡、課堂目標、成本和易用性。"},{"en":"Poor selection can waste time if the tool looks impressive but does not teach clearly.","zh":"如果工具看似令人印象深刻卻教得不清楚，差劣選擇會浪費時間。"},{"en":"This phrase focuses on careful choice rather than using technology for its own sake.","zh":"這個短語集中於仔細選擇，而不是為科技而科技。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":17},{"front":"the contested place of","meaning":"……具爭議的地位","examples":[{"en":"The heading concerns the contested place of new technology in history teaching.","zh":"這個標題關於新科技在歷史教學中具爭議的地位。"},{"en":"The contested place of something means its role or position is debated and not agreed on.","zh":"the contested place of something 是指某事物的角色或位置受到爭論，未有共識。"},{"en":"The contested place of homework in education reflects disagreement about stress and learning.","zh":"功課在教育中具爭議的地位，反映人們對壓力和學習有分歧。"},{"en":"Technology has a contested place when some teachers see it as useful and others see it as risky.","zh":"當有些老師認為科技有用，而另一些認為有風險時，科技就有具爭議的地位。"},{"en":"This phrase shows uncertainty about whether something belongs and how it should be used.","zh":"這個短語顯示人們對某事是否應存在及如何使用仍不確定。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":17},{"front":"history teaching","meaning":"歷史教學","examples":[{"en":"The passage focuses on technology in history teaching.","zh":"文章集中於歷史教學中的科技。"},{"en":"History teaching means the methods teachers use to help students learn about the past.","zh":"history teaching 是指老師幫助學生學習過去所使用的方法。"},{"en":"Good history teaching includes facts, sources, causes, consequences, and interpretation.","zh":"良好歷史教學包括事實、資料來源、原因、後果和詮釋。"},{"en":"History teaching becomes stronger when students learn to ask questions, not just memorise dates.","zh":"當學生學會提問，而不只是背日期時，歷史教學會更強。"},{"en":"Technology can support history teaching if it helps students understand evidence and context.","zh":"如果科技幫助學生理解證據和背景，它就能支援歷史教學。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":17},{"front":"engaging students through","meaning":"透過……吸引學生","examples":[{"en":"Teachers may have difficulty engaging students through traditional methods.","zh":"老師可能難以透過傳統方法吸引學生。"},{"en":"Engaging students through something means using that method to make students interested and involved.","zh":"engaging students through something 是指使用某方法令學生感興趣並參與。"},{"en":"Teachers can engage students through stories that connect history with ordinary people.","zh":"老師可以透過把歷史與普通人連接起來的故事吸引學生。"},{"en":"If a method is too passive, it may fail to engage students.","zh":"如果方法太被動，可能無法吸引學生。"},{"en":"This phrase focuses on the route or method used to gain student interest.","zh":"這個短語集中於用甚麼途徑或方法取得學生興趣。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":17},{"front":"traditional teaching methods","meaning":"傳統教學方法","examples":[{"en":"Traditional teaching methods may not fully engage modern students.","zh":"傳統教學方法未必能完全吸引現代學生。"},{"en":"Traditional teaching methods are older classroom practices such as lectures, textbooks, copying notes, and memorisation.","zh":"traditional teaching methods 是較舊的課堂做法，例如講課、教科書、抄筆記和背誦。"},{"en":"Traditional teaching methods can work well when they are clear and well structured.","zh":"當傳統教學方法清晰且結構良好時，它們可以有效。"},{"en":"They may fail when students need interaction, visual support, or source-based tasks.","zh":"當學生需要互動、視覺支援或資料來源任務時，它們可能失效。"},{"en":"The passage suggests that traditional methods should be reconsidered, not simply abandoned.","zh":"文章暗示傳統方法應被重新考慮，而不是簡單拋棄。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":17},{"front":"emerging multimedia","meaning":"新興多媒體","examples":[{"en":"Emerging multimedia can serve as a teaching tool.","zh":"新興多媒體可以作為教學工具。"},{"en":"Emerging multimedia means new or developing forms of media that combine text, image, sound, video, or interaction.","zh":"emerging multimedia 是指新出現或正在發展、結合文字、圖像、聲音、影片或互動的媒體形式。"},{"en":"Virtual museum tours are an example of emerging multimedia in education.","zh":"虛擬博物館導覽是教育中新興多媒體的一個例子。"},{"en":"Emerging multimedia can make lessons more engaging, but teachers need to check quality and accuracy.","zh":"新興多媒體可以令課堂更吸引，但老師需要檢查質素和準確性。"},{"en":"This phrase suggests resources that are still growing in use.","zh":"這個短語暗示使用仍在增長中的資源。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":17},{"front":"teaching tools","meaning":"教學工具","examples":[{"en":"Digital resources can be used as teaching tools.","zh":"數碼資源可以被用作教學工具。"},{"en":"Teaching tools are materials or methods that help teachers explain ideas and guide learning.","zh":"teaching tools 是幫助老師解釋想法和引導學習的材料或方法。"},{"en":"Pictures, timelines, maps, worksheets, and videos can all be teaching tools.","zh":"圖片、時間線、地圖、工作紙和影片都可以是教學工具。"},{"en":"A tool becomes useful when it helps students understand better, not just when it looks attractive.","zh":"當工具幫助學生更好理解時才有用，而不只是看起來吸引。"},{"en":"Teachers should choose tools that match the lesson aim.","zh":"老師應選擇符合課堂目標的工具。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":17},{"front":"poor test performance","meaning":"測驗表現差","examples":[{"en":"The paragraph discusses poor test performance by students and professionals.","zh":"該段討論學生和專業人士測驗表現差。"},{"en":"Poor test performance means weak results or low scores on an assessment.","zh":"poor test performance 是指評估中的薄弱結果或低分。"},{"en":"Poor test performance may show lack of knowledge, poor preparation, or an unsuitable test format.","zh":"測驗表現差可能顯示知識不足、準備不足或測驗形式不合適。"},{"en":"Teachers should investigate poor performance before blaming students alone.","zh":"老師在只責怪學生前，應先調查表現差的原因。"},{"en":"This phrase describes exam results, not necessarily a person’s full ability.","zh":"這個短語描述考試結果，不一定代表一個人的完整能力。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":17},{"front":"students and professionals","meaning":"學生和專業人士","examples":[{"en":"Both students and professionals may perform poorly on certain history tests.","zh":"學生和專業人士都可能在某些歷史測驗中表現差。"},{"en":"Students and professionals means learners and people with specialist work or training.","zh":"students and professionals 是指學習者以及有專門工作或訓練的人。"},{"en":"A test can challenge both students and professionals if its questions are outside their usual knowledge.","zh":"如果題目超出平常知識範圍，一個測驗可以同時難倒學生和專業人士。"},{"en":"Comparing students and professionals may show that test scores do not equal total understanding.","zh":"比較學生和專業人士，可能顯示測驗分數不等於完整理解。"},{"en":"This phrase brings together beginners and experts in one discussion.","zh":"這個短語把初學者和專家放在同一討論中。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":17},{"front":"a concrete example of","meaning":"……的具體例子","examples":[{"en":"The heading asks for a concrete example of multimedia in lessons.","zh":"這個標題要求找出多媒體在課堂中的具體例子。"},{"en":"A concrete example of something is a clear, specific case that shows the idea in practice.","zh":"a concrete example of something 是清楚、具體地展示某想法如何實踐的個案。"},{"en":"A teacher may give a concrete example of cause and effect by using a real historical event.","zh":"老師可能用真實歷史事件給出因果關係的具體例子。"},{"en":"Concrete examples help students understand abstract ideas more easily.","zh":"具體例子幫助學生更容易理解抽象想法。"},{"en":"This phrase asks for something specific, not a general statement.","zh":"這個短語要求具體事物，而不是一般陳述。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":18},{"front":"bringing history lessons to life","meaning":"令歷史課變得生動","examples":[{"en":"Multimedia can bring history lessons to life.","zh":"多媒體可以令歷史課變得生動。"},{"en":"Bringing history lessons to life means making the past feel vivid, real, and interesting for students.","zh":"bringing history lessons to life 是指令過去對學生而言變得鮮明、真實和有趣。"},{"en":"A recording of a speech can bring a history lesson to life by letting students hear the speaker’s voice.","zh":"演說錄音可以讓學生聽到講者聲音，從而令歷史課變得生動。"},{"en":"Lessons come to life when students see people, places, and evidence rather than only dates.","zh":"當學生看見人物、地方和證據，而不只是日期時，課堂會變得生動。"},{"en":"This phrase suggests making learning active and memorable.","zh":"這個短語暗示令學習主動且令人記得。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":18},{"front":"comparisons among","meaning":"……之間的比較","examples":[{"en":"The heading refers to comparisons among technologies used in classrooms.","zh":"這個標題指課室中所用科技之間的比較。"},{"en":"Comparisons among things are studies of similarities and differences within a group.","zh":"comparisons among things 是對一組事物內部相似和差異的研究。"},{"en":"Teachers make comparisons among apps before choosing one for homework.","zh":"老師在選擇功課應用程式前，會比較不同應用程式。"},{"en":"Comparisons among teaching tools help schools decide which tool fits which lesson.","zh":"教學工具之間的比較幫助學校決定哪種工具適合哪堂課。"},{"en":"This phrase focuses on more than two items, not just a simple pair.","zh":"這個短語集中於多於兩項事物，而不只是簡單兩者比較。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":18},{"front":"major technological breakthroughs","meaning":"重大科技突破","examples":[{"en":"The heading mentions major technological breakthroughs.","zh":"這個標題提到重大科技突破。"},{"en":"Major technological breakthroughs are important new inventions or developments that greatly change what people can do.","zh":"major technological breakthroughs 是大幅改變人們能做甚麼的重要新發明或發展。"},{"en":"The internet was a major technological breakthrough for communication and education.","zh":"互聯網是溝通和教育方面的重大科技突破。"},{"en":"Such breakthroughs can create new opportunities but also new problems.","zh":"這類突破可以創造新機會，也可以帶來新問題。"},{"en":"This phrase refers to big advances, not small updates.","zh":"這個短語指重大進展，而不是小型更新。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":18},{"front":"resistance from","meaning":"來自……的抗拒","examples":[{"en":"The final paragraph describes resistance from some historians.","zh":"最後一段描述來自一些歷史學家的抗拒。"},{"en":"Resistance from someone means opposition or unwillingness to accept a change.","zh":"resistance from someone 是指來自某人的反對或不願接受改變。"},{"en":"A new school policy may face resistance from parents if they do not understand its purpose.","zh":"如果家長不理解新校政目的，它可能面對來自家長的抗拒。"},{"en":"Resistance from experienced teachers may come from fear, workload, or concern about quality.","zh":"來自有經驗老師的抗拒可能源於恐懼、工作量或對質素的擔心。"},{"en":"This phrase identifies who is pushing back against an idea.","zh":"這個短語指出誰在反對某個想法。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":18},{"front":"deciding which technologies to use","meaning":"決定使用哪些科技","examples":[{"en":"The issue is deciding which technologies to use in education.","zh":"問題是決定在教育中使用哪些科技。"},{"en":"Deciding which technologies to use means choosing the tools that best fit the learning purpose.","zh":"deciding which technologies to use 是指選擇最符合學習目的的工具。"},{"en":"A school must decide which technologies to use before spending money on new equipment.","zh":"學校在花錢購買新設備前，必須決定使用哪些科技。"},{"en":"Teachers should consider age, topic, cost, access, and accuracy when choosing technology.","zh":"老師選擇科技時應考慮年齡、題目、成本、可及性和準確性。"},{"en":"This phrase treats technology choice as a careful decision, not an automatic answer.","zh":"這個短語把科技選擇視為仔細決定，而不是自動答案。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":18},{"front":"instead of revising textbooks","meaning":"而不是修訂教科書","examples":[{"en":"The writer suggests focusing on technology instead of revising textbooks.","zh":"作者建議集中於科技，而不是修訂教科書。"},{"en":"Instead of revising textbooks means choosing another solution rather than simply changing textbook content.","zh":"instead of revising textbooks 是指選擇另一個解決方法，而不是只改變教科書內容。"},{"en":"A teacher may improve lessons by adding source activities instead of revising every handout.","zh":"老師可以透過加入資料來源活動來改善課堂，而不是修訂每份筆記。"},{"en":"Revising textbooks can help, but it may not change how students actually learn.","zh":"修訂教科書可以有幫助，但未必改變學生實際如何學習。"},{"en":"This phrase creates a contrast between two possible responses to the problem.","zh":"這個短語在兩種可能回應之間建立對比。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":18},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"Students decide whether the statements agree with the writer’s views.","zh":"學生判斷以下陳述是否與作者觀點一致。"},{"en":"Do the following statements agree with asks whether each statement matches what the text says.","zh":"do the following statements agree with 是在問每句陳述是否符合文本內容。"},{"en":"In reading exams, students must check evidence before deciding if a statement agrees with the writer.","zh":"在閱讀考試中，學生在判斷陳述是否與作者一致前，必須檢查證據。"},{"en":"A statement may sound reasonable but still not agree with the passage.","zh":"陳述可能聽起來合理，但仍未必與文章一致。"},{"en":"This instruction tests careful comparison between statement and text.","zh":"這個指示測試學生能否仔細比較陳述與文本。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":18},{"front":"the views of the writer","meaning":"作者的觀點","examples":[{"en":"The task asks about the views of the writer.","zh":"任務詢問作者的觀點。"},{"en":"The views of the writer are the opinions, attitudes, or arguments expressed by the author.","zh":"the views of the writer 是作者表達的意見、態度或論點。"},{"en":"Students should answer according to the writer’s views, not their own beliefs.","zh":"學生應根據作者觀點作答，而不是自己的信念。"},{"en":"The writer’s views may be shown directly or suggested through tone and examples.","zh":"作者觀點可能直接表達，也可能透過語氣和例子暗示。"},{"en":"This phrase focuses on the author’s position.","zh":"這個短語集中於作者立場。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":18},{"front":"if the statement agrees with","meaning":"如果陳述與……一致","examples":[{"en":"Students write YES if the statement agrees with the writer’s view.","zh":"如果陳述與作者觀點一致，學生寫 YES。"},{"en":"If the statement agrees with means if the sentence matches or supports what the source says.","zh":"if the statement agrees with 是指如果句子與來源內容相符或支持它。"},{"en":"A statement agrees with the passage only when clear evidence supports it.","zh":"只有在清晰證據支持時，陳述才與文章一致。"},{"en":"Students should not choose YES just because the statement sounds true in real life.","zh":"學生不應只因陳述在現實中聽起來正確就選 YES。"},{"en":"This phrase reminds students to compare the statement with the text.","zh":"這個短語提醒學生把陳述與文本比較。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":18},{"front":"if the statement contradicts","meaning":"如果陳述與……矛盾","examples":[{"en":"Students write NO if the statement contradicts the writer’s view.","zh":"如果陳述與作者觀點矛盾，學生寫 NO。"},{"en":"If the statement contradicts means if it says the opposite of what the text says.","zh":"if the statement contradicts 是指如果句子說出與文本相反的內容。"},{"en":"A statement contradicts the passage if the passage says technology helps but the statement says it cannot help.","zh":"如果文章說科技有幫助，而陳述說科技不能幫助，它就與文章矛盾。"},{"en":"Contradiction requires clear opposite evidence, not simply missing information.","zh":"矛盾需要清楚的相反證據，而不只是資料缺失。"},{"en":"This phrase is important in YES/NO/NOT GIVEN questions.","zh":"這個短語在 YES/NO/NOT GIVEN 題中很重要。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":18},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"Students write NOT GIVEN if it is impossible to say what the writer thinks.","zh":"如果無法判斷作者怎樣想，學生寫 NOT GIVEN。"},{"en":"Impossible to say means there is not enough information to decide.","zh":"impossible to say 是指沒有足夠資料作出判斷。"},{"en":"It is impossible to say whether a teacher prefers videos if the passage never mentions her preference.","zh":"如果文章從未提到老師偏好，就無法判斷她是否喜歡影片。"},{"en":"In reading exams, students should choose NOT GIVEN when evidence is absent.","zh":"在閱讀考試中，當證據不存在時，學生應選 NOT GIVEN。"},{"en":"This phrase warns students not to guess beyond the text.","zh":"這個短語提醒學生不要超出文本猜測。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":19},{"front":"modern people","meaning":"現代人","examples":[{"en":"The statement compares modern people with their ancestors.","zh":"該陳述把現代人與他們的祖先作比較。"},{"en":"Modern people are people living in the present or recent period.","zh":"modern people 是生活在現在或近代的人。"},{"en":"Modern people often use phones, computers, and online information in daily life.","zh":"現代人日常生活中常使用手機、電腦和網上資訊。"},{"en":"Modern people may have more access to information, but that does not mean they remember history better.","zh":"現代人可能有更多資訊渠道，但這不代表他們更能記住歷史。"},{"en":"This phrase contrasts people today with people in earlier generations.","zh":"這個短語把今天的人與較早世代的人作對比。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":19},{"front":"remember historical information better than","meaning":"比……更能記住歷史資料","examples":[{"en":"The question asks whether modern people remember historical information better than their ancestors.","zh":"題目問現代人是否比祖先更能記住歷史資料。"},{"en":"To remember historical information better than others means to recall facts about the past more successfully.","zh":"remember historical information better than others 是指比其他人更成功記起過去事實。"},{"en":"Students may remember historical information better than before if lessons include stories and images.","zh":"如果課堂包含故事和圖片，學生可能比以前更能記住歷史資料。"},{"en":"More access to information does not automatically mean people remember it better.","zh":"更多資訊渠道不會自動代表人們更能記住資訊。"},{"en":"This phrase compares memory ability between two groups.","zh":"這個短語比較兩個群體的記憶能力。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":19},{"front":"ancestors","meaning":"祖先；前人","examples":[{"en":"The statement compares today’s learners with their ancestors.","zh":"該陳述把今天的學習者與他們的祖先作比較。"},{"en":"Ancestors are people from earlier generations in a family, society, or human history.","zh":"ancestors 是家庭、社會或人類歷史中較早世代的人。"},{"en":"Many families learn about their ancestors through photographs, stories, and old documents.","zh":"許多家庭透過照片、故事和舊文件了解祖先。"},{"en":"Comparing students with their ancestors can show how education has changed.","zh":"把學生與前人比較，可以顯示教育如何改變。"},{"en":"This word can refer to family forebears or earlier people more generally.","zh":"這個詞可以指家族祖先，也可以較廣泛指前人。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":19},{"front":"make historical details more vivid","meaning":"令歷史細節更生動","examples":[{"en":"New technologies can make historical details more vivid.","zh":"新科技可以令歷史細節更生動。"},{"en":"To make historical details more vivid means to make past facts, scenes, and experiences feel clearer and more alive.","zh":"make historical details more vivid 是指令過去的事實、場景和經歷感覺更清楚和更鮮活。"},{"en":"A photo of a battlefield can make historical details more vivid than a plain paragraph.","zh":"戰場照片可以比純文字段落更能令歷史細節生動。"},{"en":"Vivid details help students imagine the people and places behind historical events.","zh":"生動細節幫助學生想像歷史事件背後的人和地方。"},{"en":"This phrase describes stronger mental images and clearer understanding.","zh":"這個短語描述更強的腦海圖像和更清晰理解。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":19},{"front":"memorable for students","meaning":"令學生更容易記住","examples":[{"en":"Multimedia can make historical information more memorable for students.","zh":"多媒體可以令歷史資訊更容易被學生記住。"},{"en":"Memorable for students means easy for students to remember after the lesson.","zh":"memorable for students 是指學生課後容易記住。"},{"en":"A dramatic speech recording can make a historical event memorable for students.","zh":"戲劇性的演說錄音可以令歷史事件更容易被學生記住。"},{"en":"Information becomes more memorable when students connect it with images, emotions, and stories.","zh":"當學生把資訊與圖像、情感和故事連接起來時，它會更容易記住。"},{"en":"This phrase focuses on lasting memory, not only momentary interest.","zh":"這個短語集中於持久記憶，而不只是短暫興趣。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":19},{"front":"traditional media","meaning":"傳統媒介","examples":[{"en":"The question refers to traditional media such as written sources.","zh":"題目指書面資料等傳統媒介。"},{"en":"Traditional media are older forms of communication, such as books, newspapers, radio, film, or printed documents.","zh":"traditional media 是較舊的溝通形式，例如書籍、報紙、電台、電影或印刷文件。"},{"en":"In history classes, traditional media may include textbooks and written sources.","zh":"在歷史課中，傳統媒介可能包括教科書和書面資料。"},{"en":"Traditional media can still be valuable because they preserve detailed information.","zh":"傳統媒介仍可有價值，因為它們保存詳細資訊。"},{"en":"New technology does not automatically make traditional media useless.","zh":"新科技不會自動令傳統媒介變得無用。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":19},{"front":"gradually becoming obsolete","meaning":"逐漸變得過時","examples":[{"en":"The statement asks whether written sources are gradually becoming obsolete.","zh":"該陳述問書面資料是否逐漸變得過時。"},{"en":"Gradually becoming obsolete means slowly becoming outdated or no longer useful.","zh":"gradually becoming obsolete 是指慢慢變得過時或不再有用。"},{"en":"Some old software is gradually becoming obsolete as newer systems replace it.","zh":"隨著新系統取代舊系統，有些舊軟件正逐漸變得過時。"},{"en":"A teaching method becomes obsolete when it no longer helps students learn well.","zh":"當教學方法不再幫助學生有效學習時，它就變得過時。"},{"en":"The phrase suggests a slow process of losing relevance.","zh":"這個短語暗示逐步失去相關性的過程。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":19},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below with words from the passage.","zh":"學生用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the short text that follows.","zh":"complete the summary below 是指填補下面短文中的空缺字詞。"},{"en":"In reading exams, students complete summaries by finding words that fit meaning and grammar.","zh":"在閱讀考試中，學生透過找出符合意思和文法的字詞完成摘要。"},{"en":"This task tests both comprehension and careful word choice.","zh":"這項任務同時測試理解和仔細選詞。"},{"en":"Students should check the word limit before writing answers.","zh":"學生寫答案前應檢查字數限制。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":19},{"front":"no more than three words","meaning":"不多於三個字","examples":[{"en":"Students choose no more than three words from the passage.","zh":"學生從文章中選擇不多於三個字。"},{"en":"No more than three words means the answer must contain three words or fewer.","zh":"no more than three words 是指答案必須包含三個字或以下。"},{"en":"If the instruction says no more than three words, a four-word answer is too long.","zh":"如果指示說不多於三個字，四個字答案就太長。"},{"en":"Students should copy only the necessary words from the passage.","zh":"學生應只從文章中抄寫必要字詞。"},{"en":"This phrase tests precision as well as understanding.","zh":"這個短語既測試準確性，也測試理解力。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":19},{"front":"contemporary students","meaning":"當代學生","examples":[{"en":"Contemporary students may respond well to multimedia materials.","zh":"當代學生可能對多媒體材料反應良好。"},{"en":"Contemporary students are students living and learning in the present time.","zh":"contemporary students 是生活和學習於當前時代的學生。"},{"en":"Contemporary students often use digital devices in both school and daily life.","zh":"當代學生常在學校和日常生活中使用數碼設備。"},{"en":"Teachers may adapt lessons because contemporary students are used to fast-moving media.","zh":"老師可能調整課堂，因為當代學生習慣快速變化的媒體。"},{"en":"This phrase contrasts present-day learners with students from earlier generations.","zh":"這個短語把今天的學習者與早期世代學生作對比。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":19},{"front":"be engaged more easily","meaning":"更容易被吸引","examples":[{"en":"Students can be engaged more easily through multimedia.","zh":"學生可以透過多媒體更容易被吸引。"},{"en":"To be engaged more easily means to become interested and involved with less difficulty.","zh":"be engaged more easily 是指較容易變得感興趣並參與其中。"},{"en":"Younger learners may be engaged more easily when lessons include pictures and activities.","zh":"當課堂包含圖片和活動時，年幼學習者可能更容易被吸引。"},{"en":"Students are engaged more easily when examples connect with their own lives.","zh":"當例子與學生自己的生活有關時，他們更容易投入。"},{"en":"This phrase describes improved attention and participation.","zh":"這個短語描述注意力和參與度的改善。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":20},{"front":"combining the study of history with","meaning":"把歷史學習與……結合","examples":[{"en":"Teachers can engage students by combining the study of history with multimedia.","zh":"老師可以透過把歷史學習與多媒體結合來吸引學生。"},{"en":"Combining the study of history with something means joining history learning with another method or tool.","zh":"combining the study of history with something 是指把歷史學習與另一種方法或工具連接起來。"},{"en":"A teacher may combine history study with role-play to help students understand different viewpoints.","zh":"老師可能把歷史學習與角色扮演結合，幫助學生理解不同觀點。"},{"en":"Combining history with multimedia can support memory if the materials are carefully chosen.","zh":"如果材料經仔細選擇，把歷史與多媒體結合可以支援記憶。"},{"en":"This phrase stresses connection between content and teaching method.","zh":"這個短語強調內容與教學方法之間的連接。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":20},{"front":"expand conventional classroom discussion","meaning":"擴展傳統課堂討論","examples":[{"en":"Multimedia can expand conventional classroom discussion.","zh":"多媒體可以擴展傳統課堂討論。"},{"en":"To expand conventional classroom discussion means to make ordinary class talk broader, richer, or more varied.","zh":"expand conventional classroom discussion 是指令普通課堂對話更廣、更豐富或更多樣。"},{"en":"Showing a photograph can expand discussion because students can analyse visual evidence.","zh":"展示照片可以擴展討論，因為學生可以分析視覺證據。"},{"en":"Audio and video materials expand discussion by giving students more evidence to respond to.","zh":"音訊和影片材料透過給學生更多可回應的證據來擴展討論。"},{"en":"This phrase suggests improving discussion rather than replacing it.","zh":"這個短語暗示改善討論，而不是取代討論。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":20},{"front":"helping teachers explain","meaning":"幫助老師解釋","examples":[{"en":"Multimedia tools help teachers explain abstract concepts.","zh":"多媒體工具幫助老師解釋抽象概念。"},{"en":"Helping teachers explain means making it easier for teachers to present and clarify ideas.","zh":"helping teachers explain 是指令老師更容易呈現和澄清想法。"},{"en":"A diagram helps teachers explain how a government system works.","zh":"圖表幫助老師解釋政府制度如何運作。"},{"en":"Short clips can help teachers explain events that students have never seen.","zh":"短片可以幫助老師解釋學生從未見過的事件。"},{"en":"This phrase focuses on support for teaching, not just student entertainment.","zh":"這個短語集中於支援教學，而不只是娛樂學生。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":20},{"front":"accommodating students’ different learning styles","meaning":"配合學生不同學習方式","examples":[{"en":"Multimedia can support students by accommodating their different learning styles.","zh":"多媒體可以透過配合學生不同學習方式來支援學生。"},{"en":"Accommodating students’ different learning styles means adjusting teaching to support varied ways of learning.","zh":"accommodating students’ different learning styles 是指調整教學以支援不同學習方式。"},{"en":"Pictures can help visual learners, while audio clips can help students who learn by listening.","zh":"圖片可以幫助視覺型學習者，而音訊片段可以幫助透過聆聽學習的學生。"},{"en":"A balanced lesson accommodates different styles without separating students into fixed labels.","zh":"平衡的課堂會配合不同方式，而不把學生固定標籤化。"},{"en":"This phrase suggests flexibility and inclusion in teaching.","zh":"這個短語暗示教學上的彈性和包容。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":20},{"front":"pre-prepared PowerPoint units","meaning":"預先準備好的 PowerPoint 單元","examples":[{"en":"Pre-prepared PowerPoint units contain many useful materials.","zh":"預先準備好的 PowerPoint 單元包含許多有用材料。"},{"en":"Pre-prepared PowerPoint units are ready-made slide lessons designed before class.","zh":"pre-prepared PowerPoint units 是課前已設計好的現成投影片課堂。"},{"en":"A teacher may use a pre-prepared unit on the Cold War to save planning time.","zh":"老師可能使用關於冷戰的預先準備單元來節省備課時間。"},{"en":"These units can be helpful, but teachers should check accuracy and adapt examples.","zh":"這些單元可以有幫助，但老師應檢查準確性並調整例子。"},{"en":"This phrase suggests convenience, structure, and classroom readiness.","zh":"這個短語暗示方便、有結構和可供課堂使用。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":20},{"front":"contain a wide variety of materials","meaning":"包含各式各樣的材料","examples":[{"en":"PowerPoint units contain a wide variety of materials.","zh":"PowerPoint 單元包含各式各樣的材料。"},{"en":"To contain a wide variety of materials means to include many different kinds of resources.","zh":"contain a wide variety of materials 是指包括許多不同種類的資源。"},{"en":"A history unit may contain maps, timelines, letters, photographs, and questions.","zh":"歷史單元可能包含地圖、時間線、信件、照片和問題。"},{"en":"Variety can help students learn because different materials show different sides of an event.","zh":"多樣材料可以幫助學生學習，因為不同材料顯示事件的不同面向。"},{"en":"This phrase emphasises diversity within one teaching resource.","zh":"這個短語強調一項教學資源內部的多樣性。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":20},{"front":"making learning interactive","meaning":"令學習具互動性","examples":[{"en":"Multimedia materials can make learning interactive.","zh":"多媒體材料可以令學習具互動性。"},{"en":"Making learning interactive means allowing students to respond, discuss, choose, or take part actively.","zh":"making learning interactive 是指讓學生回應、討論、選擇或主動參與。"},{"en":"A classroom poll can make learning interactive because students must give answers immediately.","zh":"課堂投票可以令學習具互動性，因為學生必須即時回答。"},{"en":"Interactive learning can increase attention because students are not only listening.","zh":"互動學習可以提高注意力，因為學生不只是聆聽。"},{"en":"This phrase describes participation, not just colourful presentation.","zh":"這個短語描述參與，而不只是色彩豐富的呈現。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":20},{"front":"lessons of this kind","meaning":"這類課堂","examples":[{"en":"Lessons of this kind can help students prepare for exams.","zh":"這類課堂可以幫助學生準備考試。"},{"en":"Lessons of this kind means lessons like the type just described.","zh":"lessons of this kind 是指像剛才描述那種類型的課堂。"},{"en":"Lessons of this kind often use multimedia, examples, and discussion together.","zh":"這類課堂通常把多媒體、例子和討論結合起來。"},{"en":"Students may remember more from lessons of this kind because they see and hear the material.","zh":"學生可能從這類課堂記住更多，因為他們能看見和聽到材料。"},{"en":"This phrase points back to a teaching approach already mentioned.","zh":"這個短語指回前面已提到的教學取向。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":20},{"front":"prepare for standard examinations","meaning":"準備標準考試","examples":[{"en":"Multimedia lessons can help students prepare for standard examinations.","zh":"多媒體課堂可以幫助學生準備標準考試。"},{"en":"To prepare for standard examinations means to get ready for formal tests with fixed formats and requirements.","zh":"prepare for standard examinations 是指為有固定格式和要求的正式考試作準備。"},{"en":"Students prepare for standard examinations by revising content and practising question types.","zh":"學生透過複習內容和練習題型來準備標準考試。"},{"en":"Multimedia can support exam preparation if it helps students remember key facts and understand causes.","zh":"如果多媒體幫助學生記住重要事實並理解原因，它就能支援備考。"},{"en":"Preparation should include both memory and the ability to explain historical significance.","zh":"準備應包括記憶，也包括解釋歷史重要性的能力。"}],"source":"127 - New ways of teaching history.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 128":[{"front":"Lighting Up the Lies","meaning":"揭示謊言","examples":[{"en":"The passage examines whether brain scans can light up the lies people tell.","zh":"文章探討腦部掃描是否能揭示人們所說的謊言。"},{"en":"Lighting up the lies means revealing deception by showing signs of it clearly.","zh":"Lighting up the lies 指透過清楚顯示跡象來揭示欺騙。"},{"en":"A detective story may describe new evidence as lighting up the lies of a suspect.","zh":"偵探故事可能把新證據描述為揭示嫌疑人的謊言。"},{"en":"If a test could light up the lies people tell, it might change courts and police work.","zh":"如果測試能揭示人們所說的謊言，它可能改變法庭和警務工作。"},{"en":"The phrase is metaphorical because lies do not literally shine.","zh":"這個片語是比喻，因為謊言不會真的發光。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":1},{"front":"professor at the school of medicine","meaning":"醫學院教授","examples":[{"en":"Sean A. Spence was a professor at the school of medicine at the University of Sheffield.","zh":"Sean A. Spence 是謝菲爾德大學醫學院教授。"},{"en":"A professor at the school of medicine is a senior academic who teaches or researches medical topics.","zh":"醫學院教授是在醫學領域教學或研究的資深學者。"},{"en":"A professor at the school of medicine may train doctors and lead clinical studies.","zh":"醫學院教授可能培訓醫生並主持臨床研究。"},{"en":"If a professor at the school of medicine joins a project, the research may gain credibility.","zh":"如果醫學院教授參與項目，研究可能更具可信度。"},{"en":"The phrase identifies both the person’s rank and academic field.","zh":"這個片語同時指出人的職級和學術領域。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":1},{"front":"perform brain scans","meaning":"進行腦部掃描","examples":[{"en":"The professor performed brain scans on a convicted woman.","zh":"教授對一名被定罪的女子進行腦部掃描。"},{"en":"Perform brain scans means use medical imaging equipment to examine activity or structure inside the brain.","zh":"perform brain scans 指使用醫學影像設備檢查大腦內部活動或結構。"},{"en":"Doctors may perform brain scans after a patient has repeated headaches.","zh":"醫生可能在病人反覆頭痛後進行腦部掃描。"},{"en":"If researchers perform brain scans during a task, they can compare brain activity patterns.","zh":"如果研究人員在任務期間進行腦部掃描，就能比較大腦活動模式。"},{"en":"The phrase describes the action of carrying out the scan, not interpreting it.","zh":"這個片語描述進行掃描的行動，而不是解讀結果。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":1},{"front":"brain scans","meaning":"腦部掃描","examples":[{"en":"Brain scans may reveal activity linked to deception.","zh":"腦部掃描可能揭示與欺騙有關的活動。"},{"en":"Brain scans are medical images or readings that show structures or activity inside the brain.","zh":"腦部掃描是顯示大腦內部結構或活動的醫學影像或讀數。"},{"en":"A hospital may use brain scans to check for injury after an accident.","zh":"醫院可能在意外後使用腦部掃描檢查傷勢。"},{"en":"Brain scans can provide useful data, but they still need careful interpretation.","zh":"腦部掃描可以提供有用數據，但仍需要仔細解讀。"},{"en":"The phrase refers to imaging results, not ordinary photographs.","zh":"這個片語指影像結果，而不是普通照片。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":1},{"front":"be convicted of","meaning":"被裁定犯有……罪","examples":[{"en":"The woman was convicted of poisoning a child in her care.","zh":"該女子被裁定犯有毒害她照顧兒童的罪。"},{"en":"Be convicted of means be found guilty of a crime by a court.","zh":"be convicted of 指被法庭裁定犯有某項罪行。"},{"en":"A driver may be convicted of dangerous driving after a serious accident.","zh":"司機在嚴重意外後可能被裁定犯有危險駕駛罪。"},{"en":"If someone is convicted of a crime, they may face punishment or a criminal record.","zh":"如果某人被裁定犯有罪行，可能面臨懲罰或留下刑事紀錄。"},{"en":"The phrase is legal and should not be used for mere suspicion.","zh":"這個片語屬法律用語，不應用於單純懷疑。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":1},{"front":"poison a child","meaning":"毒害兒童","examples":[{"en":"The woman was convicted of poisoning a child.","zh":"該女子被裁定毒害兒童。"},{"en":"Poison a child means give a child a harmful substance that can injure or kill.","zh":"poison a child 指給兒童有害物質，可能造成傷害或死亡。"},{"en":"Medicine bottles must be locked away so no one accidentally poisons a child.","zh":"藥瓶必須鎖好，以免有人意外毒害兒童。"},{"en":"If someone poisons a child, the case becomes extremely serious and criminal.","zh":"如果有人毒害兒童，案件會變得極其嚴重並涉及刑事責任。"},{"en":"The phrase describes a harmful act, not ordinary illness.","zh":"這個片語描述有害行為，而不是普通疾病。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":1},{"front":"in her care","meaning":"由她照顧","examples":[{"en":"The child was in the woman’s care.","zh":"該兒童由該女子照顧。"},{"en":"In her care means under her responsibility, protection, or supervision.","zh":"in her care 指在她的責任、保護或監管之下。"},{"en":"A teacher is responsible for students in her care during a school trip.","zh":"在學校旅行期間，老師要對由她照顧的學生負責。"},{"en":"If a child is injured while in her care, people may ask whether she acted safely.","zh":"如果兒童在由她照顧期間受傷，人們可能會問她是否安全行事。"},{"en":"The phrase shows a duty to look after someone.","zh":"這個片語顯示照顧某人的責任。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":1},{"front":"appear to be telling the truth","meaning":"看似正在說真話","examples":[{"en":"The woman appeared to be telling the truth when she denied the crime.","zh":"該女子否認犯罪時，看似正在說真話。"},{"en":"Appear to be telling the truth means seem honest, although this may not prove honesty.","zh":"appear to be telling the truth 指看起來誠實，但這未必證明真的誠實。"},{"en":"A student may appear to be telling the truth, but the teacher still checks the facts.","zh":"學生可能看似正在說真話，但老師仍會查證事實。"},{"en":"If someone appears to be telling the truth, others may feel less suspicious at first.","zh":"如果某人看似正在說真話，其他人起初可能較少懷疑。"},{"en":"The phrase describes outward impression, not confirmed reality.","zh":"這個片語描述外在印象，而不是已確認的事實。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":1},{"front":"deny committing the crime","meaning":"否認犯案","examples":[{"en":"She denied committing the crime.","zh":"她否認犯案。"},{"en":"Deny committing the crime means say that one did not do the illegal act.","zh":"deny committing the crime 指聲稱自己沒有做該違法行為。"},{"en":"A suspect may deny committing the crime during a police interview.","zh":"嫌疑人在警方會面中可能否認犯案。"},{"en":"If a person denies committing the crime, investigators must look for supporting evidence.","zh":"如果某人否認犯案，調查人員必須尋找支持證據。"},{"en":"The phrase does not prove innocence; it only reports what the person says.","zh":"這個片語不證明清白；它只報告那人所說的話。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":1},{"front":"deception study","meaning":"欺騙研究；測謊研究","examples":[{"en":"The deception study was later published in a medical journal.","zh":"這項欺騙研究後來刊登於醫學期刊。"},{"en":"A deception study is research that examines lying, dishonesty, or the detection of false statements.","zh":"deception study 是研究說謊、不誠實或偵測虛假陳述的研究。"},{"en":"A university may run a deception study to see how people react when asked to lie.","zh":"大學可能進行欺騙研究，觀察人們被要求說謊時的反應。"},{"en":"If a deception study uses artificial tasks, its results may not apply to real crimes.","zh":"如果欺騙研究使用人為任務，其結果未必適用於真實罪案。"},{"en":"The phrase describes research about deception, not deception by the researchers.","zh":"這個片語描述關於欺騙的研究，而不是研究人員作出欺騙。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":1},{"front":"along with","meaning":"連同；以及","examples":[{"en":"This deception study, along with two others, was funded by Quickfire Media.","zh":"這項欺騙研究連同另外兩項研究，由 Quickfire Media 資助。"},{"en":"Along with means together with or in addition to something else.","zh":"along with 指連同或以及其他事物。"},{"en":"The teacher collected homework, along with signed permission forms.","zh":"老師收功課，連同已簽署的同意書。"},{"en":"If one report is reviewed along with others, the conclusion may be stronger.","zh":"如果一份報告連同其他報告一起審視，結論可能更有力。"},{"en":"The phrase adds related items to the same situation.","zh":"這個片語把相關項目加入同一情況。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":2},{"front":"be funded by","meaning":"由……資助","examples":[{"en":"The Sheffield group’s studies were funded by a television production company.","zh":"謝菲爾德團隊的研究由一間電視製作公司資助。"},{"en":"Be funded by means receive money from a person or organisation to support work.","zh":"be funded by 指從個人或機構取得金錢以支持工作。"},{"en":"A school project may be funded by a local charity.","zh":"學校項目可能由本地慈善機構資助。"},{"en":"If research is funded by a company, readers may ask whether funding affects the study.","zh":"如果研究由公司資助，讀者可能會問資金是否影響研究。"},{"en":"The phrase identifies the source of financial support.","zh":"這個片語指出財政支持的來源。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":2},{"front":"television production company","meaning":"電視製作公司","examples":[{"en":"Quickfire Media was a television production company working for Channel 4.","zh":"Quickfire Media 是一間為 Channel 4 工作的電視製作公司。"},{"en":"A television production company makes programmes, documentaries, or series for broadcast.","zh":"電視製作公司製作節目、紀錄片或系列節目供播放。"},{"en":"A television production company may hire camera crews, editors, presenters, and researchers.","zh":"電視製作公司可能聘用攝影隊、剪接師、主持人和研究員。"},{"en":"If a television production company funds research, the results may become part of a programme.","zh":"如果電視製作公司資助研究，結果可能成為節目的一部分。"},{"en":"The phrase refers to a media business, not a TV channel itself.","zh":"這個片語指媒體公司，而不一定是電視頻道本身。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":2},{"front":"broadcast videos of","meaning":"播放……的影片","examples":[{"en":"Channel 4 broadcast videos of the researchers at work.","zh":"Channel 4 播放了研究人員工作的影片。"},{"en":"Broadcast videos of means show video recordings on television, online, or through media channels.","zh":"broadcast videos of 指在電視、網上或媒體渠道播放影片紀錄。"},{"en":"A school may broadcast videos of a graduation ceremony for parents at home.","zh":"學校可能播放畢業典禮影片，讓在家的家長觀看。"},{"en":"If a channel broadcasts videos of scientists working, viewers can see the research process.","zh":"如果頻道播放科學家工作的影片，觀眾可以看到研究過程。"},{"en":"The phrase focuses on making video material public.","zh":"這個片語集中於公開播放影片材料。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":2},{"front":"researchers at work","meaning":"研究人員工作的情況","examples":[{"en":"The programme showed researchers at work in the laboratory.","zh":"該節目展示了研究人員在實驗室工作的情況。"},{"en":"Researchers at work are researchers actively doing experiments, interviews, analysis, or observations.","zh":"researchers at work 指研究人員正在做實驗、訪談、分析或觀察。"},{"en":"A documentary may show researchers at work to make science feel more real.","zh":"紀錄片可能展示研究人員工作的情況，令科學感覺更真實。"},{"en":"Seeing researchers at work can help students understand that research involves careful steps.","zh":"看見研究人員工作的情況，可以幫助學生理解研究涉及仔細步驟。"},{"en":"The phrase describes people doing research, not just talking about it.","zh":"這個片語描述人們正在做研究，而不只是談論研究。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":2},{"front":"as part of","meaning":"作為……的一部分","examples":[{"en":"The videos were broadcast as part of a three-part series.","zh":"這些影片作為三集系列節目的一部分播放。"},{"en":"As part of means included within a larger activity, project, or whole.","zh":"as part of 指包含在較大的活動、項目或整體之中。"},{"en":"Students visited the museum as part of their history course.","zh":"學生參觀博物館，作為歷史課程的一部分。"},{"en":"If a video appears as part of a series, it should be understood with the other episodes.","zh":"如果影片作為系列節目的一部分出現，就應與其他集數一起理解。"},{"en":"The phrase shows that something belongs to a bigger structure.","zh":"這個片語顯示某事物屬於更大結構。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":2},{"front":"three-part series","meaning":"三集系列節目","examples":[{"en":"The research appeared in a three-part series called Lie Lab.","zh":"這項研究出現在一個名為 Lie Lab 的三集系列節目中。"},{"en":"A three-part series is a programme, article, or story divided into three sections or episodes.","zh":"three-part series 是分成三部分或三集的節目、文章或故事。"},{"en":"A TV channel may show a three-part series about climate change.","zh":"電視頻道可能播放關於氣候變化的三集系列節目。"},{"en":"If a topic is complex, a three-part series can explain it more slowly.","zh":"如果主題複雜，三集系列節目可以較慢地解釋它。"},{"en":"The phrase describes structure and number of parts.","zh":"這個片語描述結構和部分數量。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":2},{"front":"later appeared in","meaning":"後來刊登於","examples":[{"en":"The brain study later appeared in European Psychiatry.","zh":"這項腦部研究後來刊登於《European Psychiatry》。"},{"en":"Later appeared in means was published or shown in a place after an earlier event.","zh":"later appeared in 指在較早事件之後，被刊登或出現在某處。"},{"en":"A school interview later appeared in the local newspaper.","zh":"一次學校訪問後來刊登於本地報紙。"},{"en":"If research later appears in a journal, it becomes easier for other scholars to examine.","zh":"如果研究後來刊登於期刊，其他學者就更容易審視它。"},{"en":"The phrase connects earlier work with later publication.","zh":"這個片語把早期工作與後來發表連接起來。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":2},{"front":"medical journal","meaning":"醫學期刊","examples":[{"en":"The brain study appeared in a medical journal.","zh":"這項腦部研究刊登於醫學期刊。"},{"en":"A medical journal is a publication where doctors and researchers share health-related studies.","zh":"medical journal 是醫生和研究人員發表健康相關研究的刊物。"},{"en":"A hospital doctor may read a medical journal to learn about new treatments.","zh":"醫院醫生可能閱讀醫學期刊，以了解新治療方法。"},{"en":"If a study appears in a medical journal, specialists can review its methods and results.","zh":"如果研究刊登於醫學期刊，專家可以審視其方法和結果。"},{"en":"The phrase refers to an academic source, not a popular magazine.","zh":"這個片語指學術來源，而不是大眾雜誌。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":2},{"front":"functional magnetic resonance imaging","meaning":"功能性磁力共振成像","examples":[{"en":"Functional magnetic resonance imaging is used to observe activity inside the brain.","zh":"功能性磁力共振成像用於觀察大腦內部活動。"},{"en":"Functional magnetic resonance imaging is a scanning method that shows changes linked to brain activity.","zh":"功能性磁力共振成像是一種顯示與大腦活動相關變化的掃描方法。"},{"en":"Doctors and researchers may use functional magnetic resonance imaging during memory or language tasks.","zh":"醫生和研究人員可能在記憶或語言任務期間使用功能性磁力共振成像。"},{"en":"If a brain area becomes more active, this method may show related blood-flow changes.","zh":"如果某腦區變得更活躍，這種方法可能顯示相關血流變化。"},{"en":"The phrase is the full technical name often shortened to fMRI.","zh":"這個片語是常縮寫為 fMRI 的完整技術名稱。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":2},{"front":"fMRI","meaning":"功能性磁力共振掃描","examples":[{"en":"fMRI purports to detect lies by observing brain activity.","zh":"fMRI 聲稱能透過觀察大腦活動偵測謊言。"},{"en":"fMRI is a brain-scanning technique that measures activity-related changes in blood flow.","zh":"fMRI 是一種腦部掃描技術，量度與活動相關的血流變化。"},{"en":"A researcher may use fMRI to study how the brain responds to decisions.","zh":"研究人員可能使用 fMRI 研究大腦如何回應決策。"},{"en":"If fMRI is used for lie detection, scientists must show that the results are reliable.","zh":"如果 fMRI 用於測謊，科學家必須證明結果可靠。"},{"en":"The term is short for functional magnetic resonance imaging.","zh":"這個詞是 functional magnetic resonance imaging 的縮寫。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":3},{"front":"purport to","meaning":"聲稱能夠","examples":[{"en":"fMRI purports to detect mendacity by seeing inside the brain.","zh":"fMRI 聲稱能透過觀察大腦內部偵測謊言。"},{"en":"Purport to means claim to do something, especially when the claim may be questioned.","zh":"purport to 指聲稱能做某事，尤其是該聲稱可能受質疑。"},{"en":"A cheap app may purport to diagnose illness, but doctors may not trust it.","zh":"便宜應用程式可能聲稱能診斷疾病，但醫生未必信任。"},{"en":"If a product purports to solve every problem, consumers should ask for evidence.","zh":"如果產品聲稱能解決所有問題，消費者應要求證據。"},{"en":"The phrase often carries doubt about whether the claim is true.","zh":"這個片語常帶有對聲稱是否真實的懷疑。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":3},{"front":"detect mendacity","meaning":"偵測謊言","examples":[{"en":"Some companies claim that fMRI can detect mendacity.","zh":"有些公司聲稱 fMRI 能偵測謊言。"},{"en":"Detect mendacity means identify lying or dishonesty.","zh":"detect mendacity 指識別說謊或不誠實。"},{"en":"A teacher cannot detect mendacity simply by looking at a student’s face.","zh":"老師不能單靠看學生表情就偵測謊言。"},{"en":"If a machine claims to detect mendacity, it must be tested carefully before serious use.","zh":"如果機器聲稱能偵測謊言，在嚴肅使用前必須仔細測試。"},{"en":"The phrase is formal; in daily speech, people usually say detect lies.","zh":"這個片語較正式；日常英語通常說 detect lies。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":3},{"front":"see inside the brain","meaning":"觀察大腦內部","examples":[{"en":"fMRI attempts to detect lies by seeing inside the brain.","zh":"fMRI 試圖透過觀察大腦內部來偵測謊言。"},{"en":"See inside the brain means examine brain activity or structure using imaging technology.","zh":"see inside the brain 指使用影像技術檢查大腦活動或結構。"},{"en":"Doctors use scans to see inside the brain after a serious head injury.","zh":"醫生在嚴重頭部受傷後使用掃描觀察大腦內部。"},{"en":"If scientists can see inside the brain during a task, they may identify active regions.","zh":"如果科學家能在任務期間觀察大腦內部，可能識別活躍區域。"},{"en":"The phrase is not literal eyesight; it refers to medical imaging.","zh":"這個片語不是字面上的用眼看，而是指醫學影像。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":3},{"front":"instead of","meaning":"而不是","examples":[{"en":"fMRI examines brain activity instead of tracking anxiety measures.","zh":"fMRI 檢查大腦活動，而不是追蹤焦慮指標。"},{"en":"Instead of shows that one thing replaces or is chosen over another.","zh":"instead of 顯示一件事取代或被選來代替另一件事。"},{"en":"A student may revise with past papers instead of only rereading notes.","zh":"學生可能用歷屆試題溫習，而不是只重讀筆記。"},{"en":"If a clinic uses online booking instead of phone calls, waiting time may fall.","zh":"如果診所使用網上預約而不是電話預約，等候時間可能下降。"},{"en":"The phrase makes a clear contrast between two choices.","zh":"這個片語在兩個選擇之間作出清楚對比。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":3},{"front":"track peripheral measures","meaning":"追蹤周邊生理指標","examples":[{"en":"A polygraph tracks peripheral measures of anxiety.","zh":"測謊機追蹤焦慮的周邊生理指標。"},{"en":"Track peripheral measures means monitor indirect physical signs rather than the central mental process itself.","zh":"track peripheral measures 指監察間接身體跡象，而不是直接監察核心心理過程。"},{"en":"A fitness watch may track peripheral measures such as heart rate and sleep time.","zh":"健身手錶可能追蹤心率和睡眠時間等周邊生理指標。"},{"en":"If a test tracks only peripheral measures, it may miss the real cause of behaviour.","zh":"如果測試只追蹤周邊指標，可能錯過行為真正原因。"},{"en":"The phrase suggests observing surrounding signs, not the main event directly.","zh":"這個片語暗示觀察周邊跡象，而不是直接觀察主要事件。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":3},{"front":"peripheral measures of anxiety","meaning":"焦慮的周邊生理指標","examples":[{"en":"A polygraph measures peripheral measures of anxiety such as pulse and blood pressure.","zh":"測謊機量度脈搏和血壓等焦慮的周邊生理指標。"},{"en":"Peripheral measures of anxiety are physical signs that may change when a person feels nervous.","zh":"焦慮的周邊生理指標是人在緊張時可能改變的身體跡象。"},{"en":"Sweating hands can be one peripheral measure of anxiety in a stressful interview.","zh":"手心出汗可以是壓力面試中焦慮的一種周邊生理指標。"},{"en":"If peripheral measures of anxiety rise, it does not always mean someone is lying.","zh":"如果焦慮的周邊生理指標上升，並不一定表示某人在說謊。"},{"en":"The phrase refers to body signals around emotion, not the emotion itself.","zh":"這個片語指圍繞情緒的身體訊號，而不是情緒本身。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":3},{"front":"changes in pulse","meaning":"脈搏變化","examples":[{"en":"A polygraph may track changes in pulse.","zh":"測謊機可能追蹤脈搏變化。"},{"en":"Changes in pulse are rises or falls in heart rate.","zh":"changes in pulse 指心率上升或下降。"},{"en":"A nurse may notice changes in pulse when a patient is frightened or in pain.","zh":"當病人害怕或疼痛時，護士可能注意到脈搏變化。"},{"en":"If changes in pulse occur during questioning, they may reflect stress rather than lying.","zh":"如果盤問期間出現脈搏變化，它們可能反映壓力，而不是說謊。"},{"en":"The phrase describes a measurable body response.","zh":"這個片語描述可量度的身體反應。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":3},{"front":"blood pressure","meaning":"血壓","examples":[{"en":"Blood pressure can change when a person feels anxious.","zh":"當人感到焦慮時，血壓可能改變。"},{"en":"Blood pressure is the force of blood pushing against the walls of blood vessels.","zh":"blood pressure 是血液推壓血管壁的力量。"},{"en":"Doctors often check blood pressure during a routine health visit.","zh":"醫生在例行健康檢查中常會量度血壓。"},{"en":"If blood pressure becomes too high, a person may need lifestyle changes or treatment.","zh":"如果血壓變得太高，一個人可能需要改變生活方式或接受治療。"},{"en":"The phrase is a common health measurement.","zh":"這個片語是常見健康量度。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":3},{"front":"respiration","meaning":"呼吸","examples":[{"en":"A polygraph can measure changes in respiration.","zh":"測謊機可以量度呼吸變化。"},{"en":"Respiration means breathing, especially the process of taking in and releasing air.","zh":"respiration 指呼吸，尤其是吸入和呼出空氣的過程。"},{"en":"A doctor may check respiration if a patient feels short of breath.","zh":"如果病人感到氣促，醫生可能檢查呼吸。"},{"en":"Stress can affect respiration by making breathing faster or shallower.","zh":"壓力可以令呼吸變快或變淺，從而影響呼吸。"},{"en":"The word is more formal than breathing.","zh":"這個詞比 breathing 更正式。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":3},{"front":"be measured by","meaning":"由……量度","examples":[{"en":"Pulse and blood pressure are measured by a polygraph.","zh":"脈搏和血壓由測謊機量度。"},{"en":"Be measured by means be recorded or checked using a particular tool or method.","zh":"be measured by 指使用某種工具或方法記錄或檢查。"},{"en":"Body temperature is measured by a thermometer.","zh":"體溫由溫度計量度。"},{"en":"If progress is measured by exam scores only, other skills may be ignored.","zh":"如果進步只由考試分數量度，其他技能可能被忽視。"},{"en":"The phrase identifies the instrument or standard used for measurement.","zh":"這個片語指出用於量度的工具或標準。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":4},{"front":"polygraph","meaning":"測謊機","examples":[{"en":"A polygraph tracks physical signs of anxiety.","zh":"測謊機追蹤焦慮的身體跡象。"},{"en":"A polygraph is a machine that records body responses such as pulse, breathing, and blood pressure.","zh":"polygraph 是記錄脈搏、呼吸和血壓等身體反應的機器。"},{"en":"Police dramas often show suspects being questioned while connected to a polygraph.","zh":"警匪劇常展示嫌疑人接駁測謊機接受盤問。"},{"en":"If a polygraph measures stress, it may not prove whether a person is lying.","zh":"如果測謊機量度的是壓力，它未必證明某人是否說謊。"},{"en":"The word is commonly translated as lie detector, though its accuracy is debated.","zh":"這個詞常譯作測謊機，雖然其準確性有爭議。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":4},{"front":"draw hundreds of thousands of viewers","meaning":"吸引數以十萬計觀眾","examples":[{"en":"The television series drew hundreds of thousands of viewers.","zh":"這個電視系列節目吸引數以十萬計觀眾。"},{"en":"Draw hundreds of thousands of viewers means attract a very large audience.","zh":"draw hundreds of thousands of viewers 指吸引非常龐大的觀眾群。"},{"en":"A popular final match can draw hundreds of thousands of viewers online.","zh":"受歡迎的決賽可以在網上吸引數以十萬計觀眾。"},{"en":"If a science programme draws many viewers, public interest in the topic may rise.","zh":"如果科學節目吸引很多觀眾，公眾對該主題的興趣可能上升。"},{"en":"The phrase focuses on audience size and attraction.","zh":"這個片語集中於觀眾數量和吸引力。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":4},{"front":"pull in entrepreneurs","meaning":"吸引企業家","examples":[{"en":"fMRI has pulled in entrepreneurs as well as viewers.","zh":"fMRI 不但吸引觀眾，也吸引企業家。"},{"en":"Pull in entrepreneurs means attract businesspeople who see a possible opportunity.","zh":"pull in entrepreneurs 指吸引看見潛在機會的商業人士。"},{"en":"A new payment app may pull in entrepreneurs looking for a profitable market.","zh":"新付款應用程式可能吸引尋找有利可圖市場的企業家。"},{"en":"If a technology pulls in entrepreneurs before evidence is strong, commercial claims may grow too quickly.","zh":"如果技術在證據充分前已吸引企業家，商業聲稱可能增長太快。"},{"en":"The phrase suggests business interest being drawn toward something.","zh":"這個片語暗示商業興趣被吸引過來。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":4},{"front":"claim to predict","meaning":"聲稱能預測","examples":[{"en":"Two companies claim to predict whether a person is telling the truth.","zh":"兩間公司聲稱能預測一個人是否在說真話。"},{"en":"Claim to predict means say that one can forecast or identify a result in advance.","zh":"claim to predict 指聲稱能預先預測或識別結果。"},{"en":"Some apps claim to predict exam scores, but students should check the evidence.","zh":"有些應用程式聲稱能預測考試分數，但學生應檢查證據。"},{"en":"If a company claims to predict truthfulness, it must show clear testing results.","zh":"如果公司聲稱能預測真誠程度，就必須展示清晰測試結果。"},{"en":"The phrase may imply that the claim is not yet fully proven.","zh":"這個片語可能暗示該聲稱尚未完全證明。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":4},{"front":"with 90 percent or greater certainty","meaning":"準確度達九成或以上","examples":[{"en":"The companies claim to predict truthfulness with 90 percent or greater certainty.","zh":"這些公司聲稱能以九成或以上把握預測真誠程度。"},{"en":"With 90 percent or greater certainty means with at least a claimed 90% level of confidence.","zh":"with 90 percent or greater certainty 指聲稱至少有90%的信心或準確度。"},{"en":"A weather service may predict rain with 90 percent or greater certainty before issuing a warning.","zh":"天氣服務可能在有九成或以上把握預測下雨時發出警告。"},{"en":"If a legal tool claims 90 percent certainty, mistakes still remain possible.","zh":"如果法律工具聲稱有九成準確度，錯誤仍然可能存在。"},{"en":"The phrase sounds precise, so the evidence behind it matters.","zh":"這個片語聽起來精確，因此背後證據很重要。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":4},{"front":"tell the truth","meaning":"說真話","examples":[{"en":"The companies claim to know whether someone is telling the truth.","zh":"這些公司聲稱知道某人是否在說真話。"},{"en":"Tell the truth means say what is real or correct rather than lie.","zh":"tell the truth 指說出真實或正確的事，而不是說謊。"},{"en":"A child may be afraid to tell the truth after breaking a cup.","zh":"孩子打破杯子後可能害怕說真話。"},{"en":"If people tell the truth in court, judges can make fairer decisions.","zh":"如果人們在法庭上說真話，法官可以作出更公平判決。"},{"en":"The phrase describes honest speech.","zh":"這個片語描述誠實說話。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":4},{"front":"evoke casual familiarity","meaning":"喚起輕鬆熟悉的感覺","examples":[{"en":"The company name evokes the casual familiarity of a walk-in clinic.","zh":"這個公司名稱喚起免預約診所那種輕鬆熟悉的感覺。"},{"en":"Evoke casual familiarity means create a relaxed feeling that something is ordinary and easy to approach.","zh":"evoke casual familiarity 指營造某物普通、輕鬆、容易接近的感覺。"},{"en":"A shop name with friendly wording can evoke casual familiarity for new customers.","zh":"帶有友善字眼的店名可以為新顧客喚起輕鬆熟悉的感覺。"},{"en":"If a medical-sounding company evokes casual familiarity, people may trust it too quickly.","zh":"如果帶醫療感的公司名稱喚起輕鬆熟悉感，人們可能太快信任它。"},{"en":"The phrase describes the feeling a name or image creates.","zh":"這個片語描述名稱或形象所創造的感覺。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":4},{"front":"walk-in dental clinic","meaning":"免預約牙科診所","examples":[{"en":"The name sounds like a walk-in dental clinic in a strip mall.","zh":"這個名稱聽起來像小型商場中的免預約牙科診所。"},{"en":"A walk-in dental clinic is a dental clinic where patients can arrive without an appointment.","zh":"walk-in dental clinic 是病人不用預約即可到訪的牙科診所。"},{"en":"A busy parent may visit a walk-in dental clinic when a child suddenly has tooth pain.","zh":"當孩子突然牙痛，忙碌家長可能到免預約牙科診所求診。"},{"en":"If a business name sounds like a walk-in dental clinic, it may seem ordinary and approachable.","zh":"如果公司名稱聽起來像免預約牙科診所，它可能顯得普通而易接近。"},{"en":"The phrase suggests convenient everyday healthcare.","zh":"這個片語暗示方便的日常醫療服務。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":4},{"front":"strip mall","meaning":"小型商場；路邊商場","examples":[{"en":"The company name evokes a clinic in a strip mall.","zh":"這個公司名稱令人想到路邊商場中的診所。"},{"en":"A strip mall is a row of small shops usually beside a road with parking spaces.","zh":"strip mall 是通常位於道路旁、帶停車位的一排小商店。"},{"en":"A strip mall may include a pharmacy, dentist, café, and convenience store.","zh":"小型商場可能包括藥房、牙醫、咖啡店和便利店。"},{"en":"If a clinic is in a strip mall, it may feel familiar rather than prestigious.","zh":"如果診所位於小型商場，它可能感覺熟悉，而不是高級。"},{"en":"The phrase describes a common suburban shopping area.","zh":"這個片語描述常見的郊區購物地點。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":4},{"front":"risk reduction","meaning":"風險降低","examples":[{"en":"The company suggests that the technique may be used for risk reduction in dating.","zh":"該公司建議這項技術可用於約會中的風險降低。"},{"en":"Risk reduction means lowering the chance of harm, loss, or danger.","zh":"risk reduction 指降低傷害、損失或危險出現的機會。"},{"en":"Wearing a helmet is a simple form of risk reduction when cycling.","zh":"騎單車時戴頭盔是一種簡單的風險降低方法。"},{"en":"If people use a test for risk reduction, they hope it will help them avoid danger.","zh":"如果人們使用測試來降低風險，他們希望它幫助避開危險。"},{"en":"The phrase does not mean risk disappears completely.","zh":"這個片語不表示風險完全消失。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":5},{"front":"in dating","meaning":"在約會中","examples":[{"en":"No Lie MRI suggests that lie detection may be used in dating.","zh":"No Lie MRI 建議測謊可用於約會中。"},{"en":"In dating means in situations where people meet romantically or explore a relationship.","zh":"in dating 指在人們以戀愛方式認識或探索關係的情況中。"},{"en":"Honesty is important in dating because trust develops slowly.","zh":"在約會中誠實很重要，因為信任是慢慢建立的。"},{"en":"If technology is used in dating, privacy and consent become serious concerns.","zh":"如果科技用於約會中，私隱和同意會成為嚴重關注。"},{"en":"The phrase limits the discussion to romantic or relationship contexts.","zh":"這個片語把討論限制於戀愛或關係語境。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":5},{"front":"neuroscientists and legal scholars","meaning":"神經科學家和法律學者","examples":[{"en":"Many neuroscientists and legal scholars doubt the claims about fMRI lie detection.","zh":"許多神經科學家和法律學者懷疑關於 fMRI 測謊的聲稱。"},{"en":"Neuroscientists and legal scholars are experts in the brain and in law.","zh":"neuroscientists and legal scholars 是研究大腦和法律的專家。"},{"en":"Neuroscientists and legal scholars may work together when brain evidence enters court.","zh":"當腦部證據進入法庭時，神經科學家和法律學者可能合作。"},{"en":"If both groups doubt a technology, its courtroom use may face strong resistance.","zh":"如果兩類專家都懷疑某技術，其法庭使用可能面對強烈阻力。"},{"en":"The phrase joins scientific and legal expertise.","zh":"這個片語結合科學和法律專業。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":5},{"front":"doubt such claims","meaning":"懷疑這類聲稱","examples":[{"en":"Many scholars doubt such claims about fMRI.","zh":"許多學者懷疑這類關於 fMRI 的聲稱。"},{"en":"Doubt such claims means question whether those statements are true or reliable.","zh":"doubt such claims 指質疑那些說法是否真實或可靠。"},{"en":"Consumers may doubt such claims when a product promises perfect results.","zh":"當產品承諾完美效果時，消費者可能懷疑這類聲稱。"},{"en":"If evidence is weak, scientists are likely to doubt such claims.","zh":"如果證據薄弱，科學家很可能懷疑這類聲稱。"},{"en":"The phrase shows scepticism, not automatic rejection.","zh":"這個片語顯示懷疑，而不是自動否定。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":5},{"front":"question whether","meaning":"質疑是否","examples":[{"en":"Some scholars question whether brain scans will ever be useful outside research.","zh":"有些學者質疑腦部掃描是否會在研究以外有用。"},{"en":"Question whether means ask seriously if something is true, possible, or appropriate.","zh":"question whether 指認真質疑某事是否真實、可能或合適。"},{"en":"Parents may question whether extra homework really helps tired children.","zh":"家長可能質疑額外功課是否真的幫到疲倦的孩子。"},{"en":"If experts question whether a test is reliable, more evidence is needed.","zh":"如果專家質疑某測試是否可靠，就需要更多證據。"},{"en":"The phrase introduces doubt about a possibility.","zh":"這個片語引出對某種可能性的懷疑。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":5},{"front":"brain scans for lie detection","meaning":"用於測謊的腦部掃描","examples":[{"en":"Brain scans for lie detection may not be ready for courtroom use.","zh":"用於測謊的腦部掃描可能尚未準備好用於法庭。"},{"en":"Brain scans for lie detection are scans used or proposed to identify lying through brain activity.","zh":"brain scans for lie detection 是用或被建議用來透過大腦活動識別說謊的掃描。"},{"en":"A court may hesitate before accepting brain scans for lie detection as evidence.","zh":"法庭可能會猶豫是否接納用於測謊的腦部掃描作為證據。"},{"en":"If brain scans for lie detection are inaccurate, innocent people could be harmed.","zh":"如果用於測謊的腦部掃描不準確，無辜的人可能受害。"},{"en":"The phrase describes a specific use of brain imaging.","zh":"這個片語描述腦部影像的一種特定用途。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":5},{"front":"be ready for","meaning":"已準備好用於","examples":[{"en":"Brain scans may not be ready for anything beyond research.","zh":"腦部掃描可能尚未準備好用於研究以外的任何用途。"},{"en":"Be ready for means be sufficiently developed, tested, or prepared for a use or situation.","zh":"be ready for 指已充分發展、測試或準備好應付某用途或情況。"},{"en":"A new vaccine must be ready for public use before hospitals offer it widely.","zh":"新疫苗必須準備好供公眾使用，醫院才可廣泛提供。"},{"en":"If a technology is not ready for court, judges should treat it cautiously.","zh":"如果技術尚未準備好用於法庭，法官應謹慎對待。"},{"en":"The phrase focuses on preparedness and reliability.","zh":"這個片語集中於準備程度和可靠性。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":5},{"front":"anything but","meaning":"除了……之外的任何事；只適合……以外","examples":[{"en":"Some scholars think the scans are suitable for anything but real-world lie detection.","zh":"有些學者認為這些掃描適合除了現實測謊以外的任何事。"},{"en":"Anything but means every kind of thing except the one mentioned.","zh":"anything but 指除了所提到的一件事之外的所有事。"},{"en":"The room is quiet enough for anything but a noisy party.","zh":"這個房間夠安靜，適合任何事，但不適合嘈吵派對。"},{"en":"If a test is suitable for anything but real cases, it may work in labs but not in practice.","zh":"如果測試適合任何事但不適合真實案件，它可能在實驗室有效但實際上無用。"},{"en":"The phrase creates a strong exclusion.","zh":"這個片語形成強烈排除。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":5},{"front":"the nature of deception","meaning":"欺騙的本質","examples":[{"en":"More research is needed on the nature of deception and the brain.","zh":"關於欺騙的本質和大腦，仍需要更多研究。"},{"en":"The nature of deception means what deception really is and how it works.","zh":"the nature of deception 指欺騙真正是甚麼，以及它如何運作。"},{"en":"Psychologists study the nature of deception by examining motives, fear, and social pressure.","zh":"心理學家透過研究動機、恐懼和社會壓力來研究欺騙的本質。"},{"en":"If we misunderstand the nature of deception, lie-detection tools may be too simple.","zh":"如果我們誤解欺騙的本質，測謊工具可能過於簡單。"},{"en":"The phrase points to deeper features, not just examples of lying.","zh":"這個片語指更深層特徵，而不只是說謊例子。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":5},{"front":"track blood flow","meaning":"追蹤血流","examples":[{"en":"An fMRI machine tracks blood flow to activated brain areas.","zh":"fMRI 機器追蹤流向被激活腦區的血流。"},{"en":"Track blood flow means monitor where blood is moving or increasing in the body.","zh":"track blood flow 指監察血液在身體中流向哪裡或在哪裡增加。"},{"en":"Doctors may track blood flow to check whether a blocked vessel is causing symptoms.","zh":"醫生可能追蹤血流，以檢查血管阻塞是否造成症狀。"},{"en":"If a brain region works harder, tracking blood flow may show increased activity there.","zh":"如果某腦區運作更努力，追蹤血流可能顯示那裡活動增加。"},{"en":"The phrase describes measurement of circulation.","zh":"這個片語描述對循環的量度。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":5},{"front":"activated brain areas","meaning":"被激活的腦區","examples":[{"en":"Blood flows to activated brain areas during certain mental tasks.","zh":"在某些心理任務期間，血液會流向被激活的腦區。"},{"en":"Activated brain areas are parts of the brain that become more active during a task.","zh":"activated brain areas 是在任務期間變得更活躍的大腦部分。"},{"en":"Reading a sentence may activate brain areas involved in language.","zh":"閱讀句子可能激活與語言有關的腦區。"},{"en":"If activated brain areas appear during a scan, researchers ask what mental process caused them.","zh":"如果掃描中出現被激活的腦區，研究人員會問是甚麼心理過程造成。"},{"en":"The phrase does not automatically prove a person is lying.","zh":"這個片語不會自動證明某人在說謊。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":6},{"front":"the assumption in lie detection","meaning":"測謊中的假設","examples":[{"en":"The assumption in lie detection is that lying requires extra mental effort.","zh":"測謊中的假設是說謊需要額外心理努力。"},{"en":"The assumption in lie detection is the basic idea that a test depends on.","zh":"the assumption in lie detection 是測試所依賴的基本想法。"},{"en":"In a classroom test, the assumption may be that higher scores show better understanding.","zh":"在課堂測驗中，假設可能是較高分數顯示較好理解。"},{"en":"If the assumption in lie detection is wrong, the test may interpret results badly.","zh":"如果測謊中的假設錯誤，測試可能錯誤解讀結果。"},{"en":"The phrase highlights the hidden belief behind a method.","zh":"這個片語強調方法背後的隱含信念。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":6},{"front":"exert extra effort","meaning":"付出額外努力","examples":[{"en":"The brain may exert extra effort when a person tells a lie.","zh":"當一個人說謊時，大腦可能付出額外努力。"},{"en":"Exert extra effort means use more energy or concentration than usual.","zh":"exert extra effort 指比平常使用更多能量或專注力。"},{"en":"A student may exert extra effort when solving a difficult maths problem.","zh":"學生解困難數學題時可能付出額外努力。"},{"en":"If lying requires someone to remember false details, the brain may exert extra effort.","zh":"如果說謊需要記住虛假細節，大腦可能付出額外努力。"},{"en":"The phrase suggests added mental or physical work.","zh":"這個片語暗示額外的心理或身體工作。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":6},{"front":"tell a lie","meaning":"說謊","examples":[{"en":"The brain may work harder when someone tells a lie.","zh":"當某人說謊時，大腦可能運作得更努力。"},{"en":"Tell a lie means say something false on purpose.","zh":"tell a lie 指故意說出虛假的話。"},{"en":"A child may tell a lie to avoid punishment after breaking a toy.","zh":"孩子打破玩具後，可能為避免懲罰而說謊。"},{"en":"If someone tells a lie, they may need to remember both the truth and the false story.","zh":"如果某人說謊，可能需要同時記住真相和虛假故事。"},{"en":"The phrase describes intentional false speech.","zh":"這個片語描述有意的虛假說話。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":6},{"front":"regions that do more work","meaning":"運作較多的區域","examples":[{"en":"The regions that do more work get more blood.","zh":"運作較多的區域會獲得更多血液。"},{"en":"Regions that do more work are brain areas that become more active during a task.","zh":"regions that do more work 是在任務期間變得更活躍的腦區。"},{"en":"When students solve problems, brain regions that do more work may need more oxygen.","zh":"當學生解題時，運作較多的腦區可能需要更多氧氣。"},{"en":"If regions that do more work receive more blood, scanners can sometimes detect the change.","zh":"如果運作較多的區域獲得更多血液，掃描器有時能偵測到變化。"},{"en":"The phrase links brain effort with blood flow.","zh":"這個片語把大腦努力與血流連接起來。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":6},{"front":"light up in scans","meaning":"在掃描中亮起","examples":[{"en":"Active brain areas light up in scans.","zh":"活躍腦區會在掃描中亮起。"},{"en":"Light up in scans means appear as more active or highlighted in imaging results.","zh":"light up in scans 指在影像結果中顯示為更活躍或被突出。"},{"en":"Certain brain areas may light up in scans when a person reads familiar words.","zh":"當人閱讀熟悉字詞時，某些腦區可能在掃描中亮起。"},{"en":"If many areas light up in scans, researchers must decide what the activity means.","zh":"如果很多區域在掃描中亮起，研究人員必須判斷活動的意思。"},{"en":"The phrase is visual and simplified; the brain is not literally glowing.","zh":"這個片語形象化且簡化；大腦並不是真的發光。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":6},{"front":"illuminated regions","meaning":"亮起的區域","examples":[{"en":"The illuminated regions are mainly involved in decision making.","zh":"亮起的區域主要涉及決策。"},{"en":"Illuminated regions are areas that appear highlighted or active in a scan.","zh":"illuminated regions 是在掃描中顯示為被突出或活躍的區域。"},{"en":"A brain image may show illuminated regions when someone listens to music.","zh":"當人聽音樂時，腦部影像可能顯示亮起的區域。"},{"en":"If illuminated regions serve many functions, they cannot prove one mental state alone.","zh":"如果亮起的區域有許多功能，它們不能單獨證明一種心理狀態。"},{"en":"The phrase describes what researchers see on the scan image.","zh":"這個片語描述研究人員在掃描影像上看到的東西。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":6},{"front":"be primarily involved in","meaning":"主要涉及","examples":[{"en":"The illuminated brain regions are primarily involved in decision making.","zh":"亮起的腦區主要涉及決策。"},{"en":"Be primarily involved in means be mainly connected with a particular activity or function.","zh":"be primarily involved in 指主要與某活動或功能有關。"},{"en":"A school counsellor is primarily involved in student wellbeing.","zh":"學校輔導員主要涉及學生身心健康。"},{"en":"If a brain area is primarily involved in planning, it may activate during many different tasks.","zh":"如果某腦區主要涉及計劃，它可能在許多不同任務中被激活。"},{"en":"The phrase shows the main role, not the only role.","zh":"這個片語顯示主要角色，而不是唯一角色。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":6},{"front":"decision making","meaning":"決策","examples":[{"en":"Some activated brain regions are involved in decision making.","zh":"一些被激活的腦區涉及決策。"},{"en":"Decision making is the process of choosing between options.","zh":"decision making 是在不同選項之間作選擇的過程。"},{"en":"Students use decision making when choosing which subject to study first.","zh":"學生選擇先溫習哪一科時，就是在進行決策。"},{"en":"Poor decision making can lead to unsafe choices or wasted money.","zh":"差劣決策可能導致不安全選擇或浪費金錢。"},{"en":"The phrase refers to mental selection, not just final action.","zh":"這個片語指心理上的選擇過程，而不只是最終行動。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":6},{"front":"assess how","meaning":"評估……如何","examples":[{"en":"The project aims to assess how neuroscience findings affect the law.","zh":"該項目旨在評估神經科學研究結果如何影響法律。"},{"en":"Assess how means examine the way something happens or influences another thing.","zh":"assess how 指檢視某事如何發生或如何影響另一事物。"},{"en":"A teacher may assess how homework affects student confidence.","zh":"老師可能評估功課如何影響學生信心。"},{"en":"If researchers assess how a tool works in court, they look at evidence and consequences.","zh":"如果研究人員評估工具如何在法庭運作，他們會看證據和後果。"},{"en":"The phrase introduces careful evaluation of a relationship.","zh":"這個片語引出對關係的仔細評估。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":6},{"front":"neuroscience findings","meaning":"神經科學研究結果","examples":[{"en":"Neuroscience findings may affect legal decisions.","zh":"神經科學研究結果可能影響法律判決。"},{"en":"Neuroscience findings are research results about the brain and nervous system.","zh":"neuroscience findings 是關於大腦和神經系統的研究結果。"},{"en":"Neuroscience findings can help doctors understand memory, emotion, and disease.","zh":"神經科學研究結果可以幫助醫生理解記憶、情緒和疾病。"},{"en":"If neuroscience findings are used in court, judges must know what they really prove.","zh":"如果神經科學研究結果用於法庭，法官必須知道它們真正證明甚麼。"},{"en":"The phrase refers to evidence from brain science.","zh":"這個片語指來自腦科學的證據。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":7},{"front":"affect the law","meaning":"影響法律","examples":[{"en":"Brain-scanning technology may affect the law.","zh":"腦部掃描技術可能影響法律。"},{"en":"Affect the law means influence legal rules, court decisions, or legal practice.","zh":"affect the law 指影響法律規則、法庭判決或法律實務。"},{"en":"New privacy technology can affect the law by creating questions about data ownership.","zh":"新私隱科技可以透過提出數據擁有權問題來影響法律。"},{"en":"If brain scans affect the law, lawyers and judges need scientific understanding.","zh":"如果腦部掃描影響法律，律師和法官就需要科學理解。"},{"en":"The phrase links technology or evidence with legal change.","zh":"這個片語把科技或證據與法律變化連接起來。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":7},{"front":"provide funding","meaning":"提供資金","examples":[{"en":"The MacArthur Foundation provided funding for the Law and Neuroscience Project.","zh":"麥克阿瑟基金會為法律與神經科學項目提供資金。"},{"en":"Provide funding means give money to support a project, study, or organisation.","zh":"provide funding 指提供金錢以支持項目、研究或機構。"},{"en":"A charity may provide funding for free school lunches.","zh":"慈善機構可能為免費校餐提供資金。"},{"en":"If a foundation provides funding, researchers can hire staff and collect data.","zh":"如果基金會提供資金，研究人員就能聘請員工和收集數據。"},{"en":"The phrase focuses on financial support.","zh":"這個片語集中於財政支持。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":7},{"front":"run a project","meaning":"運作一個項目","examples":[{"en":"The funding helped run the Law and Neuroscience Project.","zh":"這筆資金幫助運作法律與神經科學項目。"},{"en":"Run a project means manage and carry out its activities.","zh":"run a project 指管理並執行項目的活動。"},{"en":"A teacher may run a project to help students practise speaking English.","zh":"老師可能運作一個項目，幫助學生練習英語口語。"},{"en":"If a team runs a project well, deadlines and responsibilities become clearer.","zh":"如果團隊妥善運作項目，期限和責任會更清晰。"},{"en":"The phrase describes active management, not just starting an idea.","zh":"這個片語描述主動管理，而不只是開始一個想法。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":7},{"front":"three-year pilot","meaning":"三年試行計劃","examples":[{"en":"The Law and Neuroscience Project began as a three-year pilot.","zh":"法律與神經科學項目一開始是一項三年試行計劃。"},{"en":"A three-year pilot is a trial programme lasting three years before possible expansion.","zh":"three-year pilot 是為期三年的試驗計劃，之後可能擴展。"},{"en":"A school may run a three-year pilot to test a new teaching method.","zh":"學校可能進行三年試行計劃，以測試新教學方法。"},{"en":"If a three-year pilot succeeds, leaders may make it permanent.","zh":"如果三年試行計劃成功，領導者可能使它成為永久安排。"},{"en":"The phrase combines a time period with experimental testing.","zh":"這個片語結合時間長度和試驗性測試。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":7},{"front":"set criteria for","meaning":"設定……的標準","examples":[{"en":"Part of the funding will attempt to set criteria for reliable lie detection.","zh":"部分資金將嘗試設定可靠測謊的標準。"},{"en":"Set criteria for means decide the standards used to judge something.","zh":"set criteria for 指決定用來判斷某事的標準。"},{"en":"A school may set criteria for choosing scholarship students.","zh":"學校可能設定選擇獎學金學生的標準。"},{"en":"If researchers set criteria for reliability, tests can be judged more fairly.","zh":"如果研究人員設定可靠性的標準，測試就能被更公平地評估。"},{"en":"The phrase focuses on creating clear standards.","zh":"這個片語集中於建立清晰標準。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":7},{"front":"accurate and reliable","meaning":"準確而可靠的","examples":[{"en":"The project aims to define accurate and reliable lie detection.","zh":"該項目旨在界定準確而可靠的測謊。"},{"en":"Accurate and reliable means correct and consistently dependable.","zh":"accurate and reliable 指正確且穩定可信。"},{"en":"A thermometer must be accurate and reliable if doctors use it for treatment decisions.","zh":"如果醫生用溫度計作治療決定，它必須準確而可靠。"},{"en":"If a lie detector is not accurate and reliable, it should not affect someone’s freedom.","zh":"如果測謊工具不準確而可靠，它就不應影響某人的自由。"},{"en":"The phrase combines correctness with repeatable trustworthiness.","zh":"這個片語結合正確性和可重複的可信度。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":7},{"front":"brain-scanning technology","meaning":"腦部掃描技術","examples":[{"en":"The project studies fMRI and other brain-scanning technology.","zh":"該項目研究 fMRI 和其他腦部掃描技術。"},{"en":"Brain-scanning technology is technology used to create images or measurements of the brain.","zh":"brain-scanning technology 是用來產生大腦影像或量度數據的技術。"},{"en":"Hospitals use brain-scanning technology to investigate injuries and diseases.","zh":"醫院使用腦部掃描技術調查傷害和疾病。"},{"en":"If brain-scanning technology enters court, legal users need to understand its limits.","zh":"如果腦部掃描技術進入法庭，法律使用者需要理解其限制。"},{"en":"The phrase refers to a group of imaging tools, not one machine only.","zh":"這個片語指一組影像工具，而不只是單一機器。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":7},{"front":"given the current technology","meaning":"鑑於目前技術","examples":[{"en":"Given the current technology, Raichle does not trust the results.","zh":"鑑於目前技術，Raichle 不信任這些結果。"},{"en":"Given the current technology means considering the tools and abilities available now.","zh":"given the current technology 指考慮目前可用的工具和能力。"},{"en":"Given the current technology, some hospitals still cannot offer instant test results.","zh":"鑑於目前技術，有些醫院仍不能提供即時檢測結果。"},{"en":"If a goal is impossible given the current technology, more research is needed.","zh":"如果目標鑑於目前技術不可能達成，就需要更多研究。"},{"en":"The phrase limits judgment to present conditions.","zh":"這個片語把判斷限制於當前條件。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":7},{"front":"trust the results","meaning":"信任結果","examples":[{"en":"Some scientists do not yet trust the results of fMRI lie detection.","zh":"有些科學家尚未信任 fMRI 測謊的結果。"},{"en":"Trust the results means believe that the findings are accurate and dependable.","zh":"trust the results 指相信研究結果準確而可靠。"},{"en":"A patient may not trust the results if the test machine was broken.","zh":"如果測試機器壞了，病人可能不信任結果。"},{"en":"If researchers cannot trust the results, they should not use them for serious decisions.","zh":"如果研究人員不能信任結果，就不應把它們用於嚴肅決定。"},{"en":"The phrase focuses on confidence in evidence.","zh":"這個片語集中於對證據的信心。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":7},{"front":"set up a research program","meaning":"設立研究計劃","examples":[{"en":"Researchers can set up a research program to test the technology.","zh":"研究人員可以設立研究計劃來測試這項技術。"},{"en":"Set up a research program means organise a structured plan for scientific study.","zh":"set up a research program 指組織一套有結構的科學研究計劃。"},{"en":"A university may set up a research program on teenage sleep habits.","zh":"大學可能設立關於青少年睡眠習慣的研究計劃。"},{"en":"If scientists set up a research program properly, they can collect better evidence.","zh":"如果科學家妥善設立研究計劃，就能收集更好證據。"},{"en":"The phrase suggests organised, long-term investigation.","zh":"這個片語暗示有組織的長期調查。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":8},{"front":"determine whether","meaning":"判斷是否","examples":[{"en":"The project may determine whether reliable lie detection is possible.","zh":"該項目可能判斷可靠測謊是否可能。"},{"en":"Determine whether means find out if something is true, possible, or suitable.","zh":"determine whether 指查明某事是否真實、可能或合適。"},{"en":"A doctor may run tests to determine whether a patient has an infection.","zh":"醫生可能進行檢查，以判斷病人是否感染。"},{"en":"If researchers determine whether a tool works, policy decisions become safer.","zh":"如果研究人員判斷某工具是否有效，政策決定會更安全。"},{"en":"The phrase introduces investigation of a yes-or-no question.","zh":"這個片語引出對是非問題的調查。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":8},{"front":"major review article","meaning":"重要綜述文章","examples":[{"en":"A major review article examined the weaknesses of fMRI lie-detection research.","zh":"一篇重要綜述文章檢視了 fMRI 測謊研究的弱點。"},{"en":"A major review article is an important paper that summarises and evaluates many studies.","zh":"major review article 是總結和評估多項研究的重要論文。"},{"en":"Students may read a major review article before writing a research proposal.","zh":"學生在撰寫研究計劃前可能閱讀重要綜述文章。"},{"en":"If a major review article finds weaknesses, the field may need better experiments.","zh":"如果重要綜述文章發現弱點，該領域可能需要更好的實驗。"},{"en":"The phrase refers to a broad academic evaluation.","zh":"這個片語指廣泛的學術評估。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":8},{"front":"American Journal of Law and Medicine","meaning":"《美國法律與醫學期刊》","examples":[{"en":"The article appeared in the American Journal of Law and Medicine.","zh":"該文章刊登於《美國法律與醫學期刊》。"},{"en":"The American Journal of Law and Medicine is an academic journal about legal and medical issues.","zh":"American Journal of Law and Medicine 是關於法律和醫學議題的學術期刊。"},{"en":"A paper in the American Journal of Law and Medicine may discuss patient rights or medical evidence.","zh":"刊登於《美國法律與醫學期刊》的論文可能討論病人權利或醫學證據。"},{"en":"If a lie-detection article appears there, it likely concerns both science and law.","zh":"如果測謊文章刊登在該期刊，它很可能同時涉及科學和法律。"},{"en":"The phrase names a specific scholarly publication.","zh":"這個片語指一份特定學術刊物。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":8},{"front":"explore the deficiencies of","meaning":"探討……的不足之處","examples":[{"en":"The article explores the deficiencies of existing research.","zh":"該文章探討現有研究的不足之處。"},{"en":"Explore the deficiencies of means examine the weaknesses or limitations of something.","zh":"explore the deficiencies of 指檢視某事的弱點或限制。"},{"en":"A school review may explore the deficiencies of its online learning system.","zh":"學校檢討可能探討其網上學習系統的不足之處。"},{"en":"If researchers explore the deficiencies of earlier studies, future work can improve.","zh":"如果研究人員探討早期研究的不足之處，未來工作就能改善。"},{"en":"The phrase is formal and critical, but not necessarily hostile.","zh":"這個片語較正式並帶批判性，但不一定帶敵意。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":8},{"front":"existing research","meaning":"現有研究","examples":[{"en":"Existing research has not proved that fMRI works as a real-world lie detector.","zh":"現有研究尚未證明 fMRI 可作為現實世界的測謊工具。"},{"en":"Existing research is the body of studies already completed on a topic.","zh":"existing research 是某主題上已完成的研究總體。"},{"en":"Before starting a project, students should read existing research to avoid repeating old work.","zh":"開始項目前，學生應閱讀現有研究，以避免重複舊工作。"},{"en":"If existing research is weak, strong claims should be treated carefully.","zh":"如果現有研究薄弱，強烈聲稱應被謹慎對待。"},{"en":"The phrase refers to current evidence available so far.","zh":"這個片語指目前已有的證據。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":8},{"front":"move the technology forward","meaning":"推動技術向前發展","examples":[{"en":"Researchers discussed what may be needed to move the technology forward.","zh":"研究人員討論可能需要甚麼來推動技術向前發展。"},{"en":"Move the technology forward means improve or develop the technology to a more advanced stage.","zh":"move the technology forward 指改善或發展技術，使其進入更先進階段。"},{"en":"Better batteries can move electric-car technology forward.","zh":"更好的電池可以推動電動車技術向前發展。"},{"en":"If scientists want to move the technology forward, they need stronger tests and clearer standards.","zh":"如果科學家想推動技術向前發展，就需要更強測試和更清晰標準。"},{"en":"The phrase suggests progress from a limited state.","zh":"這個片語暗示從有限狀態取得進步。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":8},{"front":"conducted so far","meaning":"到目前為止進行的","examples":[{"en":"Lie-detection studies conducted so far are still limited in number.","zh":"到目前為止進行的測謊研究數量仍然有限。"},{"en":"Conducted so far means carried out up to the present point.","zh":"conducted so far 指截至目前已進行的。"},{"en":"Surveys conducted so far suggest that students want more speaking practice.","zh":"到目前為止進行的調查顯示，學生希望有更多口語練習。"},{"en":"If studies conducted so far are few, conclusions should remain cautious.","zh":"如果到目前為止進行的研究很少，結論就應保持謹慎。"},{"en":"The phrase limits the discussion to existing work.","zh":"這個片語把討論限制於現有工作。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":8},{"front":"fail to prove","meaning":"未能證明","examples":[{"en":"The studies failed to prove that fMRI is effective in the real world.","zh":"這些研究未能證明 fMRI 在現實世界中有效。"},{"en":"Fail to prove means not provide enough evidence to show that something is true.","zh":"fail to prove 指未能提供足夠證據顯示某事為真。"},{"en":"A small survey may fail to prove that a new app improves learning.","zh":"小型調查可能未能證明新應用程式改善學習。"},{"en":"If research fails to prove a claim, companies should not advertise it as certain.","zh":"如果研究未能證明某聲稱，公司就不應把它宣傳為確定。"},{"en":"The phrase does not mean the claim is false; it means proof is insufficient.","zh":"這個片語不表示聲稱必然錯誤；它表示證據不足。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":8},{"front":"effective as a lie detector","meaning":"作為測謊工具有效","examples":[{"en":"The research failed to prove that fMRI is effective as a lie detector.","zh":"研究未能證明 fMRI 作為測謊工具有效。"},{"en":"Effective as a lie detector means able to identify lies accurately and reliably.","zh":"effective as a lie detector 指能準確而可靠地識別謊言。"},{"en":"A machine may look impressive but still not be effective as a lie detector.","zh":"機器可能看起來很先進，但仍未必作為測謊工具有效。"},{"en":"If a test is not effective as a lie detector, it should not decide legal guilt.","zh":"如果測試作為測謊工具無效，就不應決定法律罪責。"},{"en":"The phrase judges usefulness for one specific purpose.","zh":"這個片語評估某物對一個特定目的是否有用。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":8},{"front":"in the real world","meaning":"在現實世界中","examples":[{"en":"The technology has not been proved effective in the real world.","zh":"這項技術尚未被證明在現實世界中有效。"},{"en":"In the real world means in actual life, outside controlled experiments or theory.","zh":"in the real world 指在實際生活中，而不是受控實驗或理論中。"},{"en":"A study habit may sound good in theory but fail in the real world.","zh":"學習習慣在理論上可能聽起來很好，但在現實世界中失效。"},{"en":"If a lie-detection method works only in a lab, it may not work in the real world.","zh":"如果測謊方法只在實驗室有效，它可能在現實世界中無效。"},{"en":"The phrase contrasts practical reality with artificial settings.","zh":"這個片語把實際現實與人為環境作對比。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":9},{"front":"at any accuracy level","meaning":"在任何準確度水平上","examples":[{"en":"The studies did not prove effectiveness at any accuracy level.","zh":"這些研究未能在任何準確度水平上證明有效性。"},{"en":"At any accuracy level means at any stated degree of correctness.","zh":"at any accuracy level 指在任何聲稱的正確程度上。"},{"en":"A test should not be used if it cannot prove reliability at any accuracy level.","zh":"如果測試不能在任何準確度水平上證明可靠，就不應使用。"},{"en":"If researchers cannot show performance at any accuracy level, the claim remains weak.","zh":"如果研究人員不能顯示任何準確度水平上的表現，聲稱仍然薄弱。"},{"en":"The phrase emphasises the absence of proven accuracy.","zh":"這個片語強調缺乏已證明的準確性。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":9},{"front":"examine groups, not individuals","meaning":"研究群體而非個人","examples":[{"en":"Most studies examined groups, not individuals.","zh":"大多數研究研究群體，而非個人。"},{"en":"Examine groups, not individuals means study average patterns across people rather than diagnose one person.","zh":"examine groups, not individuals 指研究多人平均模式，而不是診斷單一個人。"},{"en":"A school survey may examine groups, not individuals, when comparing class habits.","zh":"學校調查比較班級習慣時，可能研究群體而非個人。"},{"en":"If research examines groups, not individuals, it may not predict one person’s result well.","zh":"如果研究研究群體而非個人，它未必能準確預測某個人的結果。"},{"en":"The phrase highlights a limit of general research findings.","zh":"這個片語強調一般研究結果的限制。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":9},{"front":"healthy young adults","meaning":"健康年輕成年人","examples":[{"en":"The subjects in the studies were healthy young adults.","zh":"研究中的受試者是健康年輕成年人。"},{"en":"Healthy young adults are adults in good health, usually in the younger age range.","zh":"healthy young adults 是身體健康、通常年齡較輕的成年人。"},{"en":"Many university studies use healthy young adults because students are easy to recruit.","zh":"許多大學研究使用健康年輕成年人，因為學生較容易招募。"},{"en":"If only healthy young adults are tested, results may not apply to older or ill people.","zh":"如果只測試健康年輕成年人，結果未必適用於年長或患病人士。"},{"en":"The phrase describes a narrow participant group.","zh":"這個片語描述一個狹窄受試者群體。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":9},{"front":"make it unclear how","meaning":"令……如何變得不清楚","examples":[{"en":"The subjects’ narrow profile makes it unclear how the results apply to others.","zh":"受試者背景狹窄，令結果如何適用於其他人變得不清楚。"},{"en":"Make it unclear how means create uncertainty about the way something works or applies.","zh":"make it unclear how 指造成不確定，使某事如何運作或適用變得不清楚。"},{"en":"Missing records make it unclear how the money was spent.","zh":"缺失紀錄令金錢如何花費變得不清楚。"},{"en":"If a study includes only one type of person, it makes it unclear how results apply widely.","zh":"如果研究只包括一類人，就會令結果如何廣泛適用變得不清楚。"},{"en":"The phrase points to uncertainty caused by limited information.","zh":"這個片語指出由有限資料造成的不確定。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":9},{"front":"apply to someone","meaning":"適用於某人","examples":[{"en":"The results may not apply to people with medical conditions.","zh":"這些結果未必適用於有醫療狀況的人。"},{"en":"Apply to someone means be relevant, suitable, or true for that person.","zh":"apply to someone 指對某人相關、合適或成立。"},{"en":"A student discount may not apply to someone who has already graduated.","zh":"學生折扣未必適用於已畢業的人。"},{"en":"If research is done on young adults, it may not apply to older patients.","zh":"如果研究以年輕成年人進行，它未必適用於年長病人。"},{"en":"The phrase shows whether a rule or finding fits a person.","zh":"這個片語顯示規則或研究結果是否適合某人。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":9},{"front":"take a drug","meaning":"服用藥物","examples":[{"en":"The findings may not apply to someone who takes a drug affecting blood pressure.","zh":"這些發現未必適用於服用影響血壓藥物的人。"},{"en":"Take a drug means use a medicine or chemical substance, usually for treatment.","zh":"take a drug 指使用藥物或化學物質，通常作治療用途。"},{"en":"A patient should tell the doctor if they take a drug every morning.","zh":"如果病人每天早上服用藥物，應告訴醫生。"},{"en":"If someone takes a drug that changes blood pressure, scan results may be harder to interpret.","zh":"如果某人服用會改變血壓的藥物，掃描結果可能更難解讀。"},{"en":"The phrase is neutral; it can refer to prescribed medicine.","zh":"這個片語是中性的，可指處方藥。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":9},{"front":"affect blood pressure","meaning":"影響血壓","examples":[{"en":"Some drugs affect blood pressure.","zh":"有些藥物會影響血壓。"},{"en":"Affect blood pressure means change the force of blood moving through the body.","zh":"affect blood pressure 指改變血液在身體中流動時的壓力。"},{"en":"Stress, exercise, salt, and medicine can affect blood pressure.","zh":"壓力、運動、鹽分和藥物都可以影響血壓。"},{"en":"If a drug affects blood pressure, it may also affect scans based on blood flow.","zh":"如果藥物影響血壓，它也可能影響基於血流的掃描。"},{"en":"The phrase describes a medical effect on circulation.","zh":"這個片語描述對循環的醫學影響。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":9},{"front":"blockage in an artery","meaning":"動脈阻塞","examples":[{"en":"The findings may not apply to someone with a blockage in an artery.","zh":"這些發現未必適用於有動脈阻塞的人。"},{"en":"A blockage in an artery is an obstruction that limits blood flow through a blood vessel.","zh":"blockage in an artery 是限制血液通過血管的阻塞。"},{"en":"Doctors may order tests if they suspect a blockage in an artery.","zh":"如果醫生懷疑有動脈阻塞，可能安排檢查。"},{"en":"If someone has a blockage in an artery, blood-flow measurements may be affected.","zh":"如果某人有動脈阻塞，血流量度可能受影響。"},{"en":"The phrase describes a serious medical condition.","zh":"這個片語描述嚴重醫療狀況。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":9},{"front":"question the specificity of","meaning":"質疑……的特異性","examples":[{"en":"The researchers questioned the specificity of the lit-up areas.","zh":"研究人員質疑亮起區域的特異性。"},{"en":"Question the specificity of means doubt whether something points to one exact cause or function.","zh":"question the specificity of 指懷疑某跡象是否指向單一確切原因或功能。"},{"en":"A doctor may question the specificity of a symptom that appears in many illnesses.","zh":"如果某症狀出現在許多疾病中，醫生可能質疑其特異性。"},{"en":"If a brain region activates during many tasks, researchers may question its specificity for lying.","zh":"如果某腦區在許多任務中被激活，研究人員可能質疑它對說謊的特異性。"},{"en":"The phrase is useful when a sign may have several meanings.","zh":"當一個跡象可能有多種意思時，這個片語很有用。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":9},{"front":"lit-up areas","meaning":"亮起的區域","examples":[{"en":"The lit-up areas may be linked to many different mental processes.","zh":"亮起的區域可能與許多不同心理過程有關。"},{"en":"Lit-up areas are parts of a scan that appear active or highlighted.","zh":"lit-up areas 是掃描中看似活躍或被突出顯示的部分。"},{"en":"Lit-up areas in a brain scan may appear during memory, attention, or decision tasks.","zh":"腦部掃描中亮起的區域可能在記憶、注意力或決策任務中出現。"},{"en":"If lit-up areas are not specific, researchers cannot link them to lying alone.","zh":"如果亮起的區域不具特異性，研究人員不能把它們只連繫到說謊。"},{"en":"The phrase is informal and visual.","zh":"這個片語較口語且形象化。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":10},{"front":"correlate with","meaning":"與……相關","examples":[{"en":"The regions correlate with a wide range of cognitive behaviours.","zh":"這些區域與廣泛的認知行為相關。"},{"en":"Correlate with means show a relationship or pattern with something else.","zh":"correlate with 指與另一事物顯示關係或模式。"},{"en":"Poor sleep may correlate with lower concentration in class.","zh":"睡眠不足可能與課堂專注力較低相關。"},{"en":"If brain activity correlates with many behaviours, it may not identify one behaviour clearly.","zh":"如果大腦活動與許多行為相關，它未必能清楚識別一種行為。"},{"en":"The phrase shows connection, not necessarily direct cause.","zh":"這個片語表示關聯，不一定表示直接原因。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":10},{"front":"a wide range of","meaning":"廣泛的……","examples":[{"en":"The brain regions correlate with a wide range of cognitive behaviours.","zh":"這些腦區與廣泛的認知行為相關。"},{"en":"A wide range of means many different kinds of something.","zh":"a wide range of 指許多不同種類的某事物。"},{"en":"A library offers a wide range of books for children, adults, and researchers.","zh":"圖書館提供廣泛的書籍，給兒童、成人和研究人員。"},{"en":"If a test reacts to a wide range of behaviours, it may be hard to interpret.","zh":"如果測試對廣泛行為都有反應，就可能難以解讀。"},{"en":"The phrase emphasises variety and breadth.","zh":"這個片語強調種類多和範圍廣。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":10},{"front":"cognitive behaviours","meaning":"認知行為","examples":[{"en":"The lit-up regions are linked to several cognitive behaviours.","zh":"亮起的區域與幾種認知行為有關。"},{"en":"Cognitive behaviours are mental activities such as thinking, remembering, deciding, and monitoring oneself.","zh":"cognitive behaviours 是思考、記憶、決定和自我監察等心理活動。"},{"en":"Solving puzzles involves cognitive behaviours like attention and reasoning.","zh":"解謎涉及注意力和推理等認知行為。"},{"en":"If a brain area is linked to many cognitive behaviours, its meaning in a scan may be unclear.","zh":"如果某腦區與許多認知行為有關，它在掃描中的意思可能不清楚。"},{"en":"The phrase focuses on mental processes, not physical actions alone.","zh":"這個片語集中於心理過程，而不只是身體動作。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":10},{"front":"self-monitoring","meaning":"自我監察","examples":[{"en":"The regions may be involved in self-monitoring.","zh":"這些區域可能涉及自我監察。"},{"en":"Self-monitoring is the process of watching and checking one’s own behaviour or thoughts.","zh":"self-monitoring 是觀察和檢查自己行為或思想的過程。"},{"en":"A student uses self-monitoring when checking whether an essay answers the question.","zh":"學生檢查作文是否回答題目時，就是在使用自我監察。"},{"en":"If someone lies, self-monitoring may increase because they must control what they say.","zh":"如果某人說謊，自我監察可能增加，因為他們必須控制自己所說的話。"},{"en":"The phrase describes internal checking.","zh":"這個片語描述內在檢查。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":10},{"front":"conscious self-awareness","meaning":"有意識的自我覺察","examples":[{"en":"The regions also correlate with conscious self-awareness.","zh":"這些區域也與有意識的自我覺察相關。"},{"en":"Conscious self-awareness is the active awareness of one’s own thoughts, actions, or identity.","zh":"conscious self-awareness 是對自己的思想、行動或身份的主動覺察。"},{"en":"A speaker uses conscious self-awareness when noticing they are talking too fast.","zh":"演講者注意到自己說話太快時，就是在使用有意識的自我覺察。"},{"en":"If brain regions relate to conscious self-awareness, they may activate in many personal tasks.","zh":"如果腦區與有意識的自我覺察有關，它們可能在許多個人任務中被激活。"},{"en":"The phrase describes knowing what one is doing or thinking.","zh":"這個片語描述知道自己正在做甚麼或想甚麼。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":10},{"front":"the biggest challenge","meaning":"最大挑戰","examples":[{"en":"The biggest challenge is to reduce the artificiality of the test protocol.","zh":"最大挑戰是減低測試程序的人為性。"},{"en":"The biggest challenge means the most difficult problem to solve.","zh":"the biggest challenge 指最難解決的問題。"},{"en":"For a new teacher, the biggest challenge may be managing a noisy class.","zh":"對新老師而言，最大挑戰可能是管理嘈吵班級。"},{"en":"If the biggest challenge is artificiality, researchers must make tests more realistic.","zh":"如果最大挑戰是人為性，研究人員必須令測試更貼近現實。"},{"en":"The phrase identifies the main obstacle.","zh":"這個片語指出主要障礙。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":10},{"front":"fund research to address","meaning":"資助研究以處理","examples":[{"en":"The project is funding research to address the challenge.","zh":"該項目正在資助研究以處理這個挑戰。"},{"en":"Fund research to address means provide money for studies that try to solve a problem.","zh":"fund research to address 指提供資金給嘗試解決問題的研究。"},{"en":"A charity may fund research to address childhood asthma.","zh":"慈善機構可能資助研究以處理兒童哮喘。"},{"en":"If a foundation funds research to address a weakness, better evidence may follow.","zh":"如果基金會資助研究以處理弱點，之後可能出現更好證據。"},{"en":"The phrase connects financial support with problem-solving research.","zh":"這個片語把財政支持與解難研究連接起來。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":10},{"front":"diminish the artificiality of","meaning":"減低……的人為性","examples":[{"en":"Researchers want to diminish the artificiality of the test protocol.","zh":"研究人員希望減低測試程序的人為性。"},{"en":"Diminish the artificiality of means reduce how unrealistic or laboratory-like something feels.","zh":"diminish the artificiality of 指減少某事不自然或像實驗室情境的程度。"},{"en":"Teachers can diminish the artificiality of speaking practice by using real conversations.","zh":"老師可以透過使用真實對話，減低口語練習的人為性。"},{"en":"If researchers diminish the artificiality of a test, results may apply better to real life.","zh":"如果研究人員減低測試的人為性，結果可能更適用於現實生活。"},{"en":"The phrase focuses on making a method more natural.","zh":"這個片語集中於令方法更自然。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":10},{"front":"test protocol","meaning":"測試程序","examples":[{"en":"The artificiality of the test protocol is a major challenge.","zh":"測試程序的人為性是一項主要挑戰。"},{"en":"A test protocol is the set of rules and steps used when running a test.","zh":"test protocol 是進行測試時使用的一套規則和步驟。"},{"en":"Nurses follow a test protocol when collecting blood samples.","zh":"護士採集血液樣本時會遵循測試程序。"},{"en":"If the test protocol is unrealistic, the results may not reflect real situations.","zh":"如果測試程序不貼近現實，結果可能不能反映真實情況。"},{"en":"The phrase describes the procedure, not the final result.","zh":"這個片語描述程序，而不是最終結果。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":10},{"front":"lie about whether","meaning":"就……是否屬實而說謊","examples":[{"en":"Lying about whether a card is the seven of spades may be unlike real deception.","zh":"就一張牌是否是黑桃七而說謊，可能不同於真實欺騙。"},{"en":"Lie about whether means give a false answer to a yes-or-no factual question.","zh":"lie about whether 指對一個是非事實問題作出虛假回答。"},{"en":"A child may lie about whether they finished homework.","zh":"孩子可能就自己是否完成功課而說謊。"},{"en":"If people lie about whether a card is correct, the lie may feel harmless and artificial.","zh":"如果人們就一張牌是否正確而說謊，這種謊言可能感覺無害且人為。"},{"en":"The phrase usually introduces the exact point being denied or hidden.","zh":"這個片語通常引出被否認或隱藏的確切事項。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":11},{"front":"seven of spades","meaning":"黑桃七","examples":[{"en":"A subject may be asked to lie about whether a card is the seven of spades.","zh":"受試者可能被要求就一張牌是否是黑桃七而說謊。"},{"en":"The seven of spades is a playing card with the number seven and the spade symbol.","zh":"seven of spades 是一張有數字七和黑桃符號的撲克牌。"},{"en":"In a simple experiment, a student may be shown the seven of spades and asked to answer falsely.","zh":"在簡單實驗中，學生可能被展示黑桃七並被要求作出虛假回答。"},{"en":"If the lie is only about the seven of spades, the emotional pressure may be low.","zh":"如果謊言只關於黑桃七，情緒壓力可能很低。"},{"en":"The phrase names a specific playing card used in a test example.","zh":"這個片語指測試例子中使用的一張特定撲克牌。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":11},{"front":"activate the same areas","meaning":"激活相同區域","examples":[{"en":"A trivial lie may not activate the same areas of the cortex as a serious lie.","zh":"微不足道的謊言未必像嚴重謊言一樣激活大腦皮層相同區域。"},{"en":"Activate the same areas means cause the same parts of the brain to become active.","zh":"activate the same areas 指令大腦相同部分變得活躍。"},{"en":"Reading and listening may not activate the same areas in exactly the same way.","zh":"閱讀和聆聽未必以完全相同方式激活相同區域。"},{"en":"If different lies do not activate the same areas, one general lie pattern may be unreliable.","zh":"如果不同謊言不會激活相同區域，單一說謊模式可能不可靠。"},{"en":"The phrase compares brain responses across tasks.","zh":"這個片語比較不同任務中的大腦反應。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":11},{"front":"cortex","meaning":"大腦皮層","examples":[{"en":"Different lies may activate different areas of the cortex.","zh":"不同謊言可能激活大腦皮層的不同區域。"},{"en":"The cortex is the outer layer of the brain involved in many complex mental functions.","zh":"cortex 是大腦外層，涉及許多複雜心理功能。"},{"en":"Neuroscience lessons often explain how the cortex helps with thinking and planning.","zh":"神經科學課常解釋大腦皮層如何幫助思考和計劃。"},{"en":"If an area of the cortex becomes active, researchers ask which task triggered it.","zh":"如果大腦皮層某區域變得活躍，研究人員會問是哪項任務觸發它。"},{"en":"The word is technical and refers to a part of the brain.","zh":"這個詞較技術性，指大腦的一部分。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":11},{"front":"rob the corner store","meaning":"搶劫街角店舖","examples":[{"en":"A serious question might ask whether someone robbed the corner store.","zh":"嚴肅問題可能問某人是否搶劫街角店舖。"},{"en":"Rob the corner store means steal from a small local shop by force or threat.","zh":"rob the corner store 指以武力或威脅搶劫一間本地小店。"},{"en":"Police may ask a suspect whether they robbed the corner store near the bus stop.","zh":"警方可能問嫌疑人是否搶劫巴士站附近的街角店舖。"},{"en":"If the question is about robbing a store, the lie may carry serious legal consequences.","zh":"如果問題關於搶劫店舖，謊言可能帶有嚴重法律後果。"},{"en":"The phrase describes a real crime scenario, unlike a harmless card lie.","zh":"這個片語描述真實罪案情境，而不是無害的紙牌謊言。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":11},{"front":"realistic studies to date","meaning":"至今最貼近現實的研究","examples":[{"en":"The most realistic studies to date may have come from television programmes.","zh":"至今最貼近現實的研究可能來自電視節目。"},{"en":"Realistic studies to date means the studies so far that best resemble real-life situations.","zh":"realistic studies to date 指到目前為止最像現實情況的研究。"},{"en":"Realistic classroom studies to date often include actual students and real lessons.","zh":"至今最貼近現實的課堂研究通常包括真實學生和真實課堂。"},{"en":"If realistic studies to date are still limited, strong claims remain premature.","zh":"如果至今最貼近現實的研究仍有限，強烈聲稱仍屬過早。"},{"en":"The phrase compares current research by how close it is to reality.","zh":"這個片語按研究接近現實的程度作比較。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":11},{"front":"market the technology","meaning":"推銷這項技術","examples":[{"en":"Two companies are already marketing the technology.","zh":"兩間公司已經在推銷這項技術。"},{"en":"Market the technology means promote and sell the technology to possible users.","zh":"market the technology 指向潛在使用者宣傳和銷售該技術。"},{"en":"A company may market the technology to schools by emphasising safety and convenience.","zh":"公司可能透過強調安全和方便，向學校推銷這項技術。"},{"en":"If companies market the technology before it is proven, buyers may misunderstand its reliability.","zh":"如果公司在技術被證明前推銷它，買家可能誤解其可靠性。"},{"en":"The phrase focuses on commercial promotion.","zh":"這個片語集中於商業推廣。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":11},{"front":"wait for more data","meaning":"等待更多數據","examples":[{"en":"The companies are not waiting for more data before marketing the scans.","zh":"這些公司沒有在推銷掃描前等待更多數據。"},{"en":"Wait for more data means delay action until additional evidence has been collected.","zh":"wait for more data 指在收集額外證據前暫緩行動。"},{"en":"Doctors may wait for more data before changing a patient’s treatment.","zh":"醫生可能等待更多數據才改變病人的治療。"},{"en":"If companies do not wait for more data, their claims may be ahead of the evidence.","zh":"如果公司不等待更多數據，它們的聲稱可能超前於證據。"},{"en":"The phrase suggests caution before decision-making.","zh":"這個片語暗示決策前的謹慎。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":11},{"front":"offer scans without charge","meaning":"免費提供掃描","examples":[{"en":"Cephos offers scans without charge to some people.","zh":"Cephos 向某些人免費提供掃描。"},{"en":"Offer scans without charge means provide scans for free.","zh":"offer scans without charge 指免費提供掃描。"},{"en":"A clinic may offer checks without charge during a public health campaign.","zh":"診所可能在公共健康活動期間免費提供檢查。"},{"en":"If a company offers scans without charge, it may hope to collect data or gain attention.","zh":"如果公司免費提供掃描，它可能希望收集數據或獲得關注。"},{"en":"The phrase means no payment is required from the recipient.","zh":"這個片語表示接受者不需要付款。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":11},{"front":"falsely accused","meaning":"被誣告","examples":[{"en":"Cephos offers scans to people who claim they were falsely accused.","zh":"Cephos 向聲稱自己被誣告的人提供掃描。"},{"en":"Falsely accused means wrongly blamed or charged for something one did not do.","zh":"falsely accused 指因自己沒有做的事而被錯誤指責或控告。"},{"en":"A student may feel falsely accused if blamed for cheating without evidence.","zh":"如果學生在沒有證據下被指作弊，可能覺得自己被誣告。"},{"en":"If someone is falsely accused of a crime, reliable evidence becomes extremely important.","zh":"如果某人被誣告犯罪，可靠證據就變得極其重要。"},{"en":"The phrase describes an accusation claimed to be untrue.","zh":"這個片語描述被聲稱不真實的指控。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":11},{"front":"meet certain criteria","meaning":"符合某些標準","examples":[{"en":"People must meet certain criteria to receive a free scan.","zh":"人們必須符合某些標準才能獲得免費掃描。"},{"en":"Meet certain criteria means satisfy specific conditions or standards.","zh":"meet certain criteria 指符合特定條件或標準。"},{"en":"Students must meet certain criteria before receiving a scholarship.","zh":"學生必須符合某些標準才可獲得獎學金。"},{"en":"If applicants do not meet the criteria, they may not qualify for help.","zh":"如果申請者不符合標準，可能沒有資格獲得幫助。"},{"en":"The phrase is common in applications, tests, and official programmes.","zh":"這個片語常見於申請、測試和官方計劃。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":12},{"front":"in an effort to","meaning":"為了","examples":[{"en":"The company offers scans in an effort to gain court acceptance.","zh":"該公司提供掃描，為了獲得法庭接納。"},{"en":"In an effort to means with the purpose of trying to achieve something.","zh":"in an effort to 指為了嘗試達成某事。"},{"en":"A school may add speaking clubs in an effort to improve students’ confidence.","zh":"學校可能增加口語學會，為了提升學生信心。"},{"en":"If a company acts in an effort to gain approval, its actions have a strategic aim.","zh":"如果公司為了取得批准而行動，其行動有策略目的。"},{"en":"The phrase explains intention behind an action.","zh":"這個片語解釋行動背後的意圖。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":12},{"front":"get scans accepted by the courts","meaning":"令掃描獲法庭接納","examples":[{"en":"The company wants to get scans accepted by the courts.","zh":"該公司希望令掃描獲法庭接納。"},{"en":"Get scans accepted by the courts means persuade courts to allow scan results as evidence.","zh":"get scans accepted by the courts 指說服法庭容許掃描結果作為證據。"},{"en":"Lawyers may try to get new scientific tests accepted by the courts.","zh":"律師可能嘗試令新科學測試獲法庭接納。"},{"en":"If scans are accepted by the courts, the technology could gain legal influence.","zh":"如果掃描獲法庭接納，這項技術可能取得法律影響力。"},{"en":"The phrase focuses on legal approval.","zh":"這個片語集中於法律批准。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":12},{"front":"legal evidence","meaning":"法庭證據","examples":[{"en":"Allowing scans as legal evidence could create a large market.","zh":"容許掃描作為法庭證據可能創造巨大市場。"},{"en":"Legal evidence is information or material that can be used in court to support a case.","zh":"legal evidence 是可在法庭中用來支持案件的資料或材料。"},{"en":"Messages, documents, witness statements, and test results may become legal evidence.","zh":"訊息、文件、證人陳述和測試結果都可能成為法庭證據。"},{"en":"If unreliable scans become legal evidence, court decisions may be unfair.","zh":"如果不可靠掃描成為法庭證據，法庭判決可能不公平。"},{"en":"The phrase refers to evidence recognised in a legal process.","zh":"這個片語指在法律程序中被承認的證據。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":12},{"front":"potentially huge and lucrative market","meaning":"潛在龐大而有利可圖的市場","examples":[{"en":"Legal acceptance could open a potentially huge and lucrative market.","zh":"法律接納可能開啟一個潛在龐大而有利可圖的市場。"},{"en":"A potentially huge and lucrative market is a possible market that could become very large and profitable.","zh":"potentially huge and lucrative market 是可能變得非常龐大且有利可圖的市場。"},{"en":"A new health app may enter a potentially huge and lucrative market if hospitals adopt it.","zh":"如果醫院採用新健康應用程式，它可能進入一個潛在龐大而有利可圖的市場。"},{"en":"If courts accept brain scans, companies may see a potentially huge and lucrative market.","zh":"如果法庭接納腦部掃描，公司可能看見潛在龐大而有利可圖的市場。"},{"en":"The phrase combines possibility, size, and profit.","zh":"這個片語結合可能性、規模和利潤。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":12},{"front":"take many shots on goal","meaning":"多次嘗試","examples":[{"en":"The company may have to take many shots on goal before reaching court.","zh":"該公司可能要多次嘗試，才有機會進入法庭。"},{"en":"Take many shots on goal means make many attempts before succeeding.","zh":"take many shots on goal 指成功前作出多次嘗試。"},{"en":"A salesperson may take many shots on goal before winning one major client.","zh":"銷售員可能要多次嘗試，才贏得一個重要客戶。"},{"en":"If courts reject early cases, a company may need many attempts before acceptance.","zh":"如果法庭拒絕早期案件，公司可能需要多次嘗試才獲接納。"},{"en":"The phrase comes from sports and means repeated tries.","zh":"這個片語來自運動，意思是反覆嘗試。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":12},{"front":"see a courtroom","meaning":"進入法庭","examples":[{"en":"The technology may face many attempts before it sees a courtroom.","zh":"這項技術可能要經過多次嘗試才進入法庭。"},{"en":"See a courtroom means be used, tested, or presented in court.","zh":"see a courtroom 指被用於、測試於或呈交於法庭。"},{"en":"A new type of evidence may not see a courtroom for years.","zh":"一種新證據可能多年都不會進入法庭。"},{"en":"If brain scans see a courtroom too early, mistakes could affect real cases.","zh":"如果腦部掃描太早進入法庭，錯誤可能影響真實案件。"},{"en":"The phrase personifies the technology as if it enters court.","zh":"這個片語把技術擬人化，好像它進入法庭一樣。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":12},{"front":"chief executive","meaning":"行政總裁","examples":[{"en":"Steven Laken is the chief executive of Cephos.","zh":"Steven Laken 是 Cephos 的行政總裁。"},{"en":"A chief executive is the top manager who leads an organisation or company.","zh":"chief executive 是領導機構或公司的最高管理者。"},{"en":"A chief executive may decide strategy, funding, hiring, and public messages.","zh":"行政總裁可能決定策略、資金、招聘和公開訊息。"},{"en":"If a chief executive makes strong claims, reporters may ask for evidence.","zh":"如果行政總裁作出強烈聲稱，記者可能要求證據。"},{"en":"The phrase refers to senior leadership.","zh":"這個片語指高層領導。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":12},{"front":"assert that","meaning":"斷言","examples":[{"en":"Laken asserts that the technology has achieved 97 percent accuracy.","zh":"Laken 斷言這項技術已達到97%準確度。"},{"en":"Assert that means state something confidently as true.","zh":"assert that 指自信地聲稱某事為真。"},{"en":"A student may assert that the answer is correct, but still needs proof.","zh":"學生可能斷言答案正確，但仍需要證明。"},{"en":"If a company asserts that its test is accurate, independent evidence becomes important.","zh":"如果公司斷言其測試準確，獨立證據就變得重要。"},{"en":"The phrase suggests confidence, not necessarily proof.","zh":"這個片語暗示信心，但不一定代表證明。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":12},{"front":"achieve 97 percent accuracy","meaning":"達到百分之九十七準確度","examples":[{"en":"The company claims that its technology has achieved 97 percent accuracy.","zh":"該公司聲稱其技術已達到百分之九十七準確度。"},{"en":"Achieve 97 percent accuracy means reach a claimed correctness rate of 97%.","zh":"achieve 97 percent accuracy 指達到聲稱為97%的正確率。"},{"en":"A spelling app that achieves 97 percent accuracy still makes some mistakes.","zh":"達到百分之九十七準確度的串字應用程式仍會犯一些錯。"},{"en":"If a test achieves 97 percent accuracy in a lab, it must still be tested in real conditions.","zh":"如果測試在實驗室達到百分之九十七準確度，仍須在真實環境測試。"},{"en":"The phrase sounds impressive but depends on how accuracy was measured.","zh":"這個片語聽起來令人印象深刻，但取決於準確度如何量度。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":12},{"front":"provide data","meaning":"提供數據","examples":[{"en":"The people scanned using the protocol have provided data.","zh":"使用該程序接受掃描的人已提供數據。"},{"en":"Provide data means give information, measurements, or records for analysis.","zh":"provide data 指提供資料、量度結果或記錄供分析。"},{"en":"Students provide data when they answer an anonymous survey.","zh":"學生回答匿名調查時，就是提供數據。"},{"en":"If participants provide data, researchers can test whether a pattern exists.","zh":"如果參與者提供數據，研究人員就能測試是否存在模式。"},{"en":"The phrase focuses on supplying evidence for study.","zh":"這個片語集中於提供研究證據。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":13},{"front":"resolve many of the issues","meaning":"解決許多問題","examples":[{"en":"Laken says the data have resolved many of the issues raised by critics.","zh":"Laken 說這些數據已解決批評者提出的許多問題。"},{"en":"Resolve many of the issues means solve or answer many of the problems or doubts.","zh":"resolve many of the issues 指解決或回答許多問題或疑慮。"},{"en":"A clear timetable can resolve many of the issues in a group project.","zh":"清晰時間表可以解決小組項目中的許多問題。"},{"en":"If new data resolve many issues, critics may still ask whether all concerns are answered.","zh":"如果新數據解決許多問題，批評者仍可能問是否已回答所有關注。"},{"en":"The phrase suggests progress in dealing with objections.","zh":"這個片語暗示在處理反對意見上取得進展。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":13},{"front":"cite issues","meaning":"提出問題；引述問題","examples":[{"en":"Greely and Illes cited several issues with existing research.","zh":"Greely 和 Illes 提出了現有研究中的幾個問題。"},{"en":"Cite issues means mention or list problems as evidence or reasons.","zh":"cite issues 指提及或列出問題作為證據或理由。"},{"en":"A parent may cite safety issues when opposing a school trip route.","zh":"家長反對學校旅行路線時，可能提出安全問題。"},{"en":"If scholars cite issues with a study, later researchers should address them.","zh":"如果學者提出研究中的問題，後來研究人員應處理它們。"},{"en":"The phrase is formal and means point out concerns.","zh":"這個片語較正式，意思是指出關注。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":13},{"front":"formal clinical trials","meaning":"正式臨床試驗","examples":[{"en":"Formal clinical trials are needed to test the machines.","zh":"測試這些機器需要正式臨床試驗。"},{"en":"Formal clinical trials are carefully designed medical studies used to test safety and effectiveness.","zh":"formal clinical trials 是用來測試安全和成效的仔細設計醫學研究。"},{"en":"A new medicine usually needs formal clinical trials before public use.","zh":"新藥通常需要正式臨床試驗才可公開使用。"},{"en":"If machines are tested in formal clinical trials, results become more trustworthy.","zh":"如果機器在正式臨床試驗中測試，結果會更可信。"},{"en":"The phrase suggests strict scientific testing with rules.","zh":"這個片語暗示有規則的嚴格科學測試。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":13},{"front":"prove that","meaning":"證明","examples":[{"en":"Clinical trials must prove that the machines meet safety criteria.","zh":"臨床試驗必須證明這些機器符合安全標準。"},{"en":"Prove that means show with evidence that something is true.","zh":"prove that 指用證據顯示某事為真。"},{"en":"A receipt can prove that a customer paid for an item.","zh":"收據可以證明顧客已為物品付款。"},{"en":"If research cannot prove that a machine is safe, it should not be used widely.","zh":"如果研究不能證明機器安全，它就不應被廣泛使用。"},{"en":"The phrase requires evidence, not just belief.","zh":"這個片語需要證據，而不只是信念。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":13},{"front":"meet safety and effectiveness criteria","meaning":"符合安全和成效標準","examples":[{"en":"The machines must meet safety and effectiveness criteria.","zh":"這些機器必須符合安全和成效標準。"},{"en":"Meet safety and effectiveness criteria means satisfy standards for being safe and working properly.","zh":"meet safety and effectiveness criteria 指符合安全和正常有效運作的標準。"},{"en":"Medical devices must meet safety and effectiveness criteria before hospitals buy them.","zh":"醫療裝置在醫院購買前必須符合安全和成效標準。"},{"en":"If a product fails to meet these criteria, regulators may reject it.","zh":"如果產品未能符合這些標準，監管機構可能拒絕它。"},{"en":"The phrase combines protection from harm with proof of usefulness.","zh":"這個片語結合避免傷害和證明有用。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":13},{"front":"call for a ban on","meaning":"要求禁止","examples":[{"en":"Greely and Illes have called for a ban on non-research uses.","zh":"Greely 和 Illes 要求禁止非研究用途。"},{"en":"Call for a ban on means publicly demand that something be prohibited.","zh":"call for a ban on 指公開要求禁止某事。"},{"en":"Parents may call for a ban on dangerous toys after accidents occur.","zh":"事故發生後，家長可能要求禁止危險玩具。"},{"en":"If experts call for a ban on a technology, they believe the risk is too high.","zh":"如果專家要求禁止某技術，他們認為風險太高。"},{"en":"The phrase describes a strong public request for prohibition.","zh":"這個片語描述強烈的公開禁令要求。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":13},{"front":"non-research uses","meaning":"非研究用途","examples":[{"en":"Some scholars oppose non-research uses of lie-detection scans.","zh":"有些學者反對測謊掃描的非研究用途。"},{"en":"Non-research uses are uses outside scientific study, such as business, courts, or personal decisions.","zh":"non-research uses 是科學研究以外的用途，例如商業、法庭或個人決定。"},{"en":"A medical scan may be acceptable in research but risky in non-research uses.","zh":"醫學掃描在研究中可能可接受，但用於非研究用途可能有風險。"},{"en":"If non-research uses begin too early, people may rely on unproven results.","zh":"如果非研究用途太早開始，人們可能依賴未證實結果。"},{"en":"The phrase contrasts practical application with controlled investigation.","zh":"這個片語把實際應用與受控調查作對比。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":13},{"front":"regulatory approval","meaning":"監管批准","examples":[{"en":"Trials for regulatory approval reveal technical challenges.","zh":"為取得監管批准而進行的試驗揭示技術挑戰。"},{"en":"Regulatory approval is official permission from authorities before a product or method can be used.","zh":"regulatory approval 是產品或方法使用前由當局給予的官方許可。"},{"en":"A new medical device needs regulatory approval before being sold to hospitals.","zh":"新醫療裝置在售予醫院前需要監管批准。"},{"en":"If a company seeks regulatory approval, it must provide safety and effectiveness data.","zh":"如果公司尋求監管批准，就必須提供安全和成效數據。"},{"en":"The phrase refers to official oversight.","zh":"這個片語指官方監督。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":13},{"front":"hint at","meaning":"暗示","examples":[{"en":"The proposed trials hint at the technical challenges involved.","zh":"擬議試驗暗示其中涉及的技術挑戰。"},{"en":"Hint at means suggest something indirectly rather than say it fully.","zh":"hint at 指間接暗示某事，而不是完全說明。"},{"en":"A sudden price cut may hint at weak sales.","zh":"突然減價可能暗示銷售疲弱。"},{"en":"If a trial design is complicated, it may hint at how difficult the technology is to test.","zh":"如果試驗設計複雜，它可能暗示測試該技術有多困難。"},{"en":"The phrase gives a clue without complete explanation.","zh":"這個片語提供線索，而不是完整解釋。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":13},{"front":"technical challenges","meaning":"技術挑戰","examples":[{"en":"Testing fMRI lie detection involves many technical challenges.","zh":"測試 fMRI 測謊涉及許多技術挑戰。"},{"en":"Technical challenges are difficult practical problems involving equipment, design, measurement, or interpretation.","zh":"technical challenges 是涉及設備、設計、量度或解讀的困難實際問題。"},{"en":"A hospital faces technical challenges when installing a new scanning machine.","zh":"醫院安裝新掃描機時會面對技術挑戰。"},{"en":"If technical challenges are ignored, test results may become unreliable.","zh":"如果技術挑戰被忽視，測試結果可能變得不可靠。"},{"en":"The phrase focuses on practical scientific difficulty.","zh":"這個片語集中於實際科學難題。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":14},{"front":"professional poker players","meaning":"職業撲克玩家","examples":[{"en":"Professional poker players may be included in testing.","zh":"職業撲克玩家可能被包括在測試中。"},{"en":"Professional poker players are people who earn money by playing poker seriously or competitively.","zh":"professional poker players 是認真或競技地打撲克賺錢的人。"},{"en":"Researchers may study professional poker players because they practise controlling facial expression.","zh":"研究人員可能研究職業撲克玩家，因為他們練習控制表情。"},{"en":"If professional poker players respond differently in scans, ordinary test results may not apply to them.","zh":"如果職業撲克玩家在掃描中反應不同，普通測試結果未必適用於他們。"},{"en":"The phrase identifies a group skilled in bluffing and risk.","zh":"這個片語指出一群擅長虛張聲勢和風險判斷的人。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":14},{"front":"sociopaths","meaning":"反社會人格者","examples":[{"en":"Sociopaths may be compared with average participants in trials.","zh":"反社會人格者可能在試驗中與普通參與者比較。"},{"en":"Sociopaths are people described as showing a persistent lack of regard for others’ rights or feelings.","zh":"sociopaths 指被描述為長期缺乏對他人權利或感受重視的人。"},{"en":"Researchers may include sociopaths to test whether emotional differences affect lie detection.","zh":"研究人員可能包括反社會人格者，以測試情緒差異是否影響測謊。"},{"en":"If sociopaths react differently to deception, one lie-detection method may not fit everyone.","zh":"如果反社會人格者對欺騙有不同反應，單一測謊方法未必適合所有人。"},{"en":"The term should be used carefully because it is a serious psychological label.","zh":"這個詞應謹慎使用，因為它是嚴肅心理標籤。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":14},{"front":"average Joes","meaning":"普通人","examples":[{"en":"Average Joes may be compared with actors and poker players.","zh":"普通人可能與演員和撲克玩家作比較。"},{"en":"Average Joes are ordinary people without special status, training, or expertise.","zh":"average Joes 是沒有特殊身份、訓練或專長的普通人。"},{"en":"A company may test a product on average Joes to see how normal users respond.","zh":"公司可能在普通人身上測試產品，看看一般使用者如何反應。"},{"en":"If only experts are tested, results may not reflect how average Joes behave.","zh":"如果只測試專家，結果可能不能反映普通人的行為。"},{"en":"The phrase is informal and means ordinary people.","zh":"這個片語較口語，意思是普通人。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":14},{"front":"the devout","meaning":"虔誠信徒","examples":[{"en":"The devout would be tested after nonbelievers.","zh":"虔誠信徒會在非信徒之後接受測試。"},{"en":"The devout are people who are deeply religious or strongly committed to their faith.","zh":"the devout 是非常宗教化或強烈投入其信仰的人。"},{"en":"The devout may follow prayer, rituals, and moral rules very seriously.","zh":"虔誠信徒可能非常認真地遵循祈禱、儀式和道德規則。"},{"en":"If the devout respond differently to religious questions, context may affect lie detection.","zh":"如果虔誠信徒對宗教問題反應不同，語境可能影響測謊。"},{"en":"The phrase refers to a group defined by strong religious belief.","zh":"這個片語指由強烈宗教信念界定的群體。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":14},{"front":"nonbelievers","meaning":"非信徒","examples":[{"en":"Nonbelievers would also take part in scanner testing.","zh":"非信徒也會參與掃描儀測試。"},{"en":"Nonbelievers are people who do not accept a particular religious belief.","zh":"nonbelievers 是不接受某種宗教信仰的人。"},{"en":"A study comparing believers and nonbelievers must define the groups clearly.","zh":"比較信徒和非信徒的研究必須清楚界定群體。"},{"en":"If nonbelievers and the devout react differently, belief may affect the test context.","zh":"如果非信徒和虔誠信徒反應不同，信念可能影響測試語境。"},{"en":"The phrase describes belief status, not intelligence or morality.","zh":"這個片語描述信仰狀態，而不是智力或道德。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":14},{"front":"go in the scanner","meaning":"進入掃描儀","examples":[{"en":"Different groups would go in the scanner for testing.","zh":"不同群體會進入掃描儀接受測試。"},{"en":"Go in the scanner means enter the scanning machine to be tested or imaged.","zh":"go in the scanner 指進入掃描機接受測試或影像檢查。"},{"en":"A patient may feel nervous before going in the scanner for the first time.","zh":"病人第一次進入掃描儀前可能感到緊張。"},{"en":"If many groups go in the scanner, researchers can compare their results.","zh":"如果許多群體進入掃描儀，研究人員就能比較結果。"},{"en":"The phrase describes the physical act of entering the machine.","zh":"這個片語描述進入機器的實際動作。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":14},{"front":"take into account","meaning":"考慮到","examples":[{"en":"Testing would take into account social settings.","zh":"測試會考慮到社交情境。"},{"en":"Take into account means consider something when making a judgment or plan.","zh":"take into account 指在作判斷或計劃時考慮某事。"},{"en":"A teacher should take into account a student’s illness before marking late work.","zh":"老師批改遲交功課前，應考慮到學生生病。"},{"en":"If lie-detection tests take social settings into account, they may become more realistic.","zh":"如果測謊測試考慮到社交情境，就可能更貼近現實。"},{"en":"The phrase means not ignoring an important factor.","zh":"這個片語表示不忽視重要因素。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":14},{"front":"social settings","meaning":"社交情境","examples":[{"en":"Lie-detection tests must consider different social settings.","zh":"測謊測試必須考慮不同社交情境。"},{"en":"Social settings are situations involving people, relationships, roles, and expectations.","zh":"social settings 是涉及人、關係、角色和期望的情況。"},{"en":"A joke may feel different in family, school, and workplace social settings.","zh":"同一個笑話在家庭、學校和工作場所等社交情境中可能感覺不同。"},{"en":"If a lie happens in a serious social setting, the brain may react differently.","zh":"如果謊言發生在嚴肅社交情境中，大腦反應可能不同。"},{"en":"The phrase highlights the surrounding human context.","zh":"這個片語強調周圍的人際背景。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":14},{"front":"white lies","meaning":"善意謊言","examples":[{"en":"White lies would have to be compared with more serious untruths.","zh":"善意謊言必須與較嚴重的不實說法作比較。"},{"en":"White lies are small lies often told to avoid hurting someone’s feelings.","zh":"white lies 是常為避免傷害別人感受而說的小謊。"},{"en":"A friend may tell a white lie by saying the meal tastes fine.","zh":"朋友可能說食物味道不錯，作為善意謊言。"},{"en":"If white lies create less stress than serious lies, scan results may differ.","zh":"如果善意謊言造成的壓力少於嚴重謊言，掃描結果可能不同。"},{"en":"The phrase describes minor socially motivated deception.","zh":"這個片語描述較輕微、帶社交動機的欺騙。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":14},{"front":"be compared against","meaning":"與……作比較","examples":[{"en":"White lies would be compared against untruths about sexual behaviour.","zh":"善意謊言會與關於性行為的不實說法作比較。"},{"en":"Be compared against means be examined side by side with something else to find differences.","zh":"be compared against 指與另一事物並列檢視，以找出差異。"},{"en":"A new medicine is compared against an older treatment in clinical trials.","zh":"新藥在臨床試驗中會與舊治療作比較。"},{"en":"If one type of lie is compared against another, researchers can test whether the brain reacts differently.","zh":"如果一類謊言與另一類謊言作比較，研究人員可以測試大腦反應是否不同。"},{"en":"The phrase shows structured comparison.","zh":"這個片語顯示有結構的比較。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":15},{"front":"untruths about","meaning":"關於……的不實說法","examples":[{"en":"Researchers may compare white lies with untruths about personal behaviour.","zh":"研究人員可能把善意謊言與關於個人行為的不實說法作比較。"},{"en":"Untruths about means false statements concerning a particular subject.","zh":"untruths about 指關於某主題的虛假陳述。"},{"en":"A job applicant should not tell untruths about past experience.","zh":"求職者不應說關於過往經驗的不實說法。"},{"en":"If untruths about serious behaviour are tested, participants may feel more pressure.","zh":"如果測試關於嚴重行為的不實說法，參與者可能感到更大壓力。"},{"en":"The phrase is a formal way to say lies about.","zh":"這個片語是 lies about 的較正式說法。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":15},{"front":"sexual peccadilloes","meaning":"性方面的小過失","examples":[{"en":"The trials might include untruths about sexual peccadilloes.","zh":"試驗可能包括關於性方面小過失的不實說法。"},{"en":"Sexual peccadilloes are minor sexual wrongdoings or embarrassing private behaviours.","zh":"sexual peccadilloes 指性方面較輕微的不當行為或令人尷尬的私人行為。"},{"en":"A questionnaire about sexual peccadilloes would require privacy and careful consent.","zh":"關於性方面小過失的問卷需要私隱和清楚同意。"},{"en":"If people lie about sexual peccadilloes, shame may affect their physical and brain responses.","zh":"如果人們就性方面小過失說謊，羞恥感可能影響身體和大腦反應。"},{"en":"The phrase is formal and slightly old-fashioned.","zh":"這個片語較正式，並帶有一點舊式語氣。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":15},{"front":"ensure that","meaning":"確保","examples":[{"en":"Researchers must ensure that the brain reacts identically.","zh":"研究人員必須確保大腦作出相同反應。"},{"en":"Ensure that means make certain that something happens or is true.","zh":"ensure that 指確保某事發生或成立。"},{"en":"Teachers check attendance to ensure that every student is safe.","zh":"老師點名以確保每名學生安全。"},{"en":"If researchers ensure that conditions are the same, results become fairer.","zh":"如果研究人員確保條件相同，結果會更公平。"},{"en":"The phrase shows active effort to guarantee something.","zh":"這個片語顯示主動努力去保證某事。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":15},{"front":"react identically","meaning":"作出相同反應","examples":[{"en":"The tests must show whether the brain reacts identically to different lies.","zh":"測試必須顯示大腦是否對不同謊言作出相同反應。"},{"en":"React identically means respond in exactly the same way.","zh":"react identically 指以完全相同方式回應。"},{"en":"Two students may not react identically to the same criticism.","zh":"兩名學生未必對同一批評作出相同反應。"},{"en":"If the brain does not react identically to all lies, one simple lie detector may fail.","zh":"如果大腦不會對所有謊言作出相同反應，單一簡單測謊器可能失效。"},{"en":"The phrase focuses on sameness of response.","zh":"這個片語集中於反應是否相同。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":15},{"front":"potential for abuse","meaning":"濫用的可能性","examples":[{"en":"The potential for abuse prompts caution.","zh":"濫用的可能性促使人們謹慎。"},{"en":"Potential for abuse means the possibility that something could be misused to harm people.","zh":"potential for abuse 指某物可能被誤用來傷害人的可能性。"},{"en":"Personal data has potential for abuse if companies collect it without clear rules.","zh":"如果公司在沒有清楚規則下收集個人資料，資料就有被濫用的可能性。"},{"en":"If a technology has potential for abuse, regulation and transparency become important.","zh":"如果技術有濫用的可能性，監管和透明度就變得重要。"},{"en":"The phrase warns about misuse, not only normal use.","zh":"這個片語警告誤用，而不只是正常使用。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":15},{"front":"prompt caution","meaning":"促使人們謹慎","examples":[{"en":"The potential for abuse prompts caution among scholars.","zh":"濫用的可能性促使學者謹慎。"},{"en":"Prompt caution means cause people to act carefully or hesitate.","zh":"prompt caution 指使人們小心行事或猶豫。"},{"en":"A rise in accidents may prompt caution among parents and teachers.","zh":"意外增加可能促使家長和老師謹慎。"},{"en":"If a new test can harm people’s reputation, that risk should prompt caution.","zh":"如果新測試能傷害人的名譽，該風險應促使人們謹慎。"},{"en":"The phrase connects risk with careful behaviour.","zh":"這個片語把風險與小心行為連接起來。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":15},{"front":"people’s lives can be changed","meaning":"人生可能被改變","examples":[{"en":"People’s lives can be changed in bad ways by technological mistakes.","zh":"技術錯誤可以以不好的方式改變人的人生。"},{"en":"People’s lives can be changed means their future, reputation, work, or relationships can be seriously affected.","zh":"people’s lives can be changed 指人的未來、名譽、工作或關係可能受到嚴重影響。"},{"en":"A wrong medical result can change a patient’s life by causing unnecessary fear.","zh":"錯誤醫療結果可以因造成不必要恐懼而改變病人的人生。"},{"en":"If legal technology makes mistakes, people’s lives can be changed unfairly.","zh":"如果法律科技犯錯，人的人生可能被不公平地改變。"},{"en":"The phrase stresses real human consequences.","zh":"這個片語強調真實的人類後果。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":15},{"front":"in bad ways","meaning":"以不好的方式","examples":[{"en":"Errors in the technology could change people’s lives in bad ways.","zh":"技術錯誤可能以不好的方式改變人的人生。"},{"en":"In bad ways means with harmful, unfair, or damaging effects.","zh":"in bad ways 指帶來有害、不公平或破壞性的影響。"},{"en":"A rumour can affect a student in bad ways if classmates believe it.","zh":"如果同學相信謠言，它可能以不好的方式影響學生。"},{"en":"If a machine wrongly labels someone as dishonest, it can affect them in bad ways.","zh":"如果機器錯誤地把某人標記為不誠實，就可能以不好的方式影響他。"},{"en":"The phrase focuses on negative consequences.","zh":"這個片語集中於負面後果。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":15},{"front":"mistakes in the technology","meaning":"技術上的錯誤","examples":[{"en":"Mistakes in the technology could harm people.","zh":"技術上的錯誤可能傷害人。"},{"en":"Mistakes in the technology are errors in how a tool measures, interprets, or reports results.","zh":"mistakes in the technology 是工具在量度、解讀或報告結果時出現的錯誤。"},{"en":"Mistakes in medical software can delay treatment or give wrong warnings.","zh":"醫療軟件中的技術錯誤可能延誤治療或發出錯誤警告。"},{"en":"If mistakes in the technology affect court evidence, innocent people may suffer.","zh":"如果技術錯誤影響法庭證據，無辜者可能受害。"},{"en":"The phrase highlights technical error with human consequences.","zh":"這個片語強調帶有人類後果的技術錯誤。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":15},{"front":"danger for science","meaning":"對科學的危險","examples":[{"en":"The danger for science is that neuroimaging could get a bad reputation.","zh":"對科學的危險是神經影像技術可能名聲受損。"},{"en":"Danger for science means a risk that could damage public trust in scientific work.","zh":"danger for science 指可能損害公眾對科學工作的信任的風險。"},{"en":"Exaggerated health claims can create danger for science if people later feel misled.","zh":"誇張健康聲稱可能造成對科學的危險，因為人們日後可能覺得被誤導。"},{"en":"If a technology is misused, the danger for science is loss of credibility.","zh":"如果技術被濫用，對科學的危險就是可信度下降。"},{"en":"The phrase focuses on harm to science’s reputation.","zh":"這個片語集中於對科學聲譽的傷害。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":16},{"front":"get a black eye","meaning":"名聲受損","examples":[{"en":"Science could get a black eye if the technology is misused.","zh":"如果這項技術被誤用，科學可能名聲受損。"},{"en":"Get a black eye means suffer damage to reputation or public image.","zh":"get a black eye 指聲譽或公眾形象受損。"},{"en":"A school can get a black eye if it ignores repeated safety complaints.","zh":"如果學校忽視反覆安全投訴，它可能名聲受損。"},{"en":"If a famous experiment fails publicly, the whole field may get a black eye.","zh":"如果著名實驗公開失敗，整個領域可能名聲受損。"},{"en":"The phrase is idiomatic and does not usually mean a physical injury here.","zh":"這個片語是習語，這裡通常不是指身體受傷。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":16},{"front":"high-profile use","meaning":"高調使用","examples":[{"en":"A high-profile use of neuroimaging could go wrong.","zh":"神經影像技術一次高調使用可能出錯。"},{"en":"High-profile use means public, widely noticed, or important use of something.","zh":"high-profile use 指公開、廣受注意或重要的使用。"},{"en":"A high-profile use of facial recognition at an airport would attract media attention.","zh":"在機場高調使用面部識別會吸引媒體關注。"},{"en":"If a high-profile use fails, public trust may fall quickly.","zh":"如果高調使用失敗，公眾信任可能迅速下降。"},{"en":"The phrase highlights visibility and public importance.","zh":"這個片語強調可見度和公眾重要性。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":16},{"front":"neuroimaging","meaning":"神經影像技術","examples":[{"en":"Neuroimaging must be used carefully in legal contexts.","zh":"神經影像技術在法律語境中必須小心使用。"},{"en":"Neuroimaging is the use of scanning methods to create images or measurements of the brain.","zh":"neuroimaging 是使用掃描方法產生大腦影像或量度資料。"},{"en":"Doctors use neuroimaging to study strokes, tumours, and brain injuries.","zh":"醫生使用神經影像技術研究中風、腫瘤和腦損傷。"},{"en":"If neuroimaging is used in law, scientific limits must be explained clearly.","zh":"如果神經影像技術用於法律，就必須清楚解釋科學限制。"},{"en":"The word refers to brain imaging techniques as a group.","zh":"這個詞指一組腦部影像技術。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":16},{"front":"go wrong","meaning":"出錯","examples":[{"en":"A high-profile use of neuroimaging could go wrong.","zh":"神經影像技術一次高調使用可能出錯。"},{"en":"Go wrong means fail, produce a bad result, or develop problems.","zh":"go wrong 指失敗、產生壞結果或出現問題。"},{"en":"A school trip can go wrong if buses arrive late and students get lost.","zh":"如果巴士遲到而學生迷路，學校旅行可能出錯。"},{"en":"If a public use of technology goes wrong, many people may lose trust.","zh":"如果科技的公開使用出錯，許多人可能失去信任。"},{"en":"The phrase is simple and common for describing failure.","zh":"這個片語簡單常用，用來描述失敗。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":16},{"front":"long and controversial history","meaning":"長久而具爭議的歷史","examples":[{"en":"The polygraph has a long and controversial history.","zh":"測謊機有長久而具爭議的歷史。"},{"en":"A long and controversial history means a subject has been debated for many years.","zh":"long and controversial history 指某主題多年來一直受到爭議。"},{"en":"Standardised testing has a long and controversial history in education.","zh":"標準化考試在教育中有長久而具爭議的歷史。"},{"en":"If a tool has a long and controversial history, people may disagree about its value.","zh":"如果工具有長久而具爭議的歷史，人們可能不同意其價值。"},{"en":"The phrase combines duration with disagreement.","zh":"這個片語結合時間長度和分歧。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":16},{"front":"gradualism","meaning":"漸進做法；漸進主義","examples":[{"en":"Gradualism may be the wisest course for adopting the new diagnostic.","zh":"漸進做法可能是採用新診斷方法的最明智路線。"},{"en":"Gradualism is an approach that introduces change slowly and step by step.","zh":"gradualism 是以緩慢而逐步方式引入改變的方法。"},{"en":"A school may use gradualism when introducing a new timetable over several terms.","zh":"學校在數個學期中引入新時間表時，可能採用漸進做法。"},{"en":"If a technology is risky, gradualism can reduce harm by testing it carefully first.","zh":"如果技術有風險，漸進做法可透過先仔細測試來減少傷害。"},{"en":"The phrase contrasts with sudden full adoption.","zh":"這個片語與突然全面採用形成對比。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":16},{"front":"the wisest course to follow","meaning":"最明智的做法","examples":[{"en":"Gradualism may be the wisest course to follow.","zh":"漸進做法可能是最明智的做法。"},{"en":"The wisest course to follow means the most sensible plan or direction to take.","zh":"the wisest course to follow 指最合理的計劃或方向。"},{"en":"When money is limited, saving first may be the wisest course to follow.","zh":"當金錢有限時，先儲蓄可能是最明智的做法。"},{"en":"If evidence is uncertain, cautious testing may be the wisest course to follow.","zh":"如果證據不確定，謹慎測試可能是最明智的做法。"},{"en":"The phrase recommends a prudent path.","zh":"這個片語建議審慎路線。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":16},{"front":"new diagnostic","meaning":"新診斷方法","examples":[{"en":"Brain-based lie detection is a new diagnostic tool.","zh":"基於大腦的測謊是一種新診斷工具。"},{"en":"A new diagnostic is a new method or tool used to identify a condition, state, or problem.","zh":"new diagnostic 是用來識別狀況、狀態或問題的新方法或工具。"},{"en":"A hospital may test a new diagnostic for detecting early disease.","zh":"醫院可能測試用於早期發現疾病的新診斷方法。"},{"en":"If a new diagnostic affects legal decisions, it needs strong validation.","zh":"如果新診斷方法影響法律決定，它需要強力驗證。"},{"en":"The phrase focuses on identifying something, not treating it.","zh":"這個片語集中於識別某事，而不是治療。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":16},{"front":"probe an essential quality","meaning":"探測一種重要特質","examples":[{"en":"The new diagnostic probes an essential quality of social interaction.","zh":"這種新診斷方法探測社交互動中的一種重要特質。"},{"en":"Probe an essential quality means investigate a very important feature deeply.","zh":"probe an essential quality 指深入調查某個非常重要的特徵。"},{"en":"A teacher may probe an essential quality of good writing by asking what makes an argument clear.","zh":"老師可能透過詢問甚麼令論點清晰，探究好文章的一種重要特質。"},{"en":"If lie detection probes truthfulness, it touches a basic part of human relationships.","zh":"如果測謊探測真誠，它就觸及人際關係的基本部分。"},{"en":"The phrase suggests deep examination of something fundamental.","zh":"這個片語暗示對根本事物的深入檢查。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":16},{"front":"social interaction","meaning":"社交互動","examples":[{"en":"Truthfulness is an essential quality governing social interaction.","zh":"真誠是支配社交互動的一種重要特質。"},{"en":"Social interaction means communication and behaviour between people.","zh":"social interaction 指人與人之間的溝通和行為。"},{"en":"Group projects require social interaction because students must discuss and share tasks.","zh":"小組項目需要社交互動，因為學生必須討論和分工。"},{"en":"If trust breaks down, social interaction becomes tense and difficult.","zh":"如果信任崩潰，社交互動會變得緊張困難。"},{"en":"The phrase covers everyday human contact.","zh":"這個片語涵蓋日常人際接觸。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":17},{"front":"match each opinion or action with","meaning":"將每項意見或行動與……配對","examples":[{"en":"Students match each opinion or action with the correct person or group.","zh":"學生將每項意見或行動與正確人物或團體配對。"},{"en":"Match each opinion or action with means connect each statement or deed to the right source.","zh":"match each opinion or action with 指把每項陳述或事蹟連接到正確來源。"},{"en":"In a reading task, students may match each opinion with the researcher who said it.","zh":"在閱讀題中，學生可能把每項意見與說出它的研究人員配對。"},{"en":"If students match an action with the wrong person, the answer becomes incorrect.","zh":"如果學生把行動與錯誤人物配對，答案就會錯。"},{"en":"The phrase describes a common exam-matching instruction.","zh":"這個片語描述常見考試配對指示。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":17},{"front":"correct person or group","meaning":"正確人物或團體","examples":[{"en":"The task asks students to choose the correct person or group.","zh":"題目要求學生選擇正確人物或團體。"},{"en":"Correct person or group means the individual or organisation that matches the information.","zh":"correct person or group 指與資料相符的個人或組織。"},{"en":"In a history quiz, students choose the correct person or group for each action.","zh":"在歷史小測中，學生為每項行動選擇正確人物或團體。"},{"en":"If two people have similar views, choosing the correct person or group requires careful reading.","zh":"如果兩人觀點相似，選擇正確人物或團體就需要仔細閱讀。"},{"en":"The phrase focuses on accurate matching.","zh":"這個片語集中於準確配對。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":17},{"front":"use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"Students may use any letter more than once.","zh":"學生可以重複使用任何字母。"},{"en":"Use any letter more than once means the same option can be chosen repeatedly.","zh":"use any letter more than once 指同一選項可以重複選用。"},{"en":"In paragraph-matching questions, students may use any letter more than once if two answers are in the same paragraph.","zh":"在段落配對題中，如果兩個答案在同一段，學生可以重複使用任何字母。"},{"en":"If this instruction is given, students should not force each letter to appear only once.","zh":"如果題目給出這個指示，學生不應強行令每個字母只出現一次。"},{"en":"The phrase prevents a common test-taking mistake.","zh":"這個片語防止常見考試錯誤。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":17},{"front":"apparently impossible goal","meaning":"看似不可能的目標","examples":[{"en":"The question refers to an apparently impossible goal that may still be achievable.","zh":"題目提到一個看似不可能但可能仍可達成的目標。"},{"en":"An apparently impossible goal is a goal that seems impossible at first but may not be.","zh":"apparently impossible goal 是起初看似不可能，但未必真的不可能的目標。"},{"en":"Learning a new language in adulthood can feel like an apparently impossible goal at the beginning.","zh":"成年後學一門新語言，開始時可能感覺像看似不可能的目標。"},{"en":"If research improves, an apparently impossible goal may become realistic later.","zh":"如果研究改善，看似不可能的目標日後可能變得現實。"},{"en":"The phrase highlights the gap between first impression and actual possibility.","zh":"這個片語強調第一印象與實際可能性之間的差距。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":17},{"front":"may still be achievable","meaning":"可能仍可達成","examples":[{"en":"A difficult goal may still be achievable through research.","zh":"困難目標可能仍可透過研究達成。"},{"en":"May still be achievable means might be possible despite difficulty or doubt.","zh":"may still be achievable 指儘管困難或存疑，仍可能做到。"},{"en":"Passing the exam may still be achievable if the student changes study methods now.","zh":"如果學生現在改變學習方法，通過考試可能仍可達成。"},{"en":"If scientists solve key problems, reliable lie detection may still be achievable.","zh":"如果科學家解決關鍵問題，可靠測謊可能仍可達成。"},{"en":"The phrase gives cautious hope.","zh":"這個片語帶有謹慎希望。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":17},{"front":"doubt the effectiveness of","meaning":"懷疑……的有效性","examples":[{"en":"Some scholars doubt the effectiveness of fMRI for detecting lies.","zh":"有些學者懷疑 fMRI 偵測謊言的有效性。"},{"en":"Doubt the effectiveness of means question whether something really works well.","zh":"doubt the effectiveness of 指質疑某物是否真的有效。"},{"en":"Parents may doubt the effectiveness of a study app if grades do not improve.","zh":"如果成績沒有進步，家長可能懷疑學習應用程式的有效性。"},{"en":"If experts doubt the effectiveness of a tool, users should wait for stronger evidence.","zh":"如果專家懷疑工具的有效性，使用者應等待更強證據。"},{"en":"The phrase expresses scepticism about usefulness.","zh":"這個片語表達對用途的懷疑。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":17},{"front":"detecting lies","meaning":"偵測謊言","examples":[{"en":"The passage discusses the difficulty of detecting lies with brain scans.","zh":"文章討論用腦部掃描偵測謊言的困難。"},{"en":"Detecting lies means identifying when someone is not telling the truth.","zh":"detecting lies 指識別某人沒有說真話的情況。"},{"en":"Detecting lies is difficult because nervousness and dishonesty can look similar.","zh":"偵測謊言很困難，因為緊張和不誠實可能看起來相似。"},{"en":"If a method for detecting lies is inaccurate, it can create serious injustice.","zh":"如果偵測謊言的方法不準確，可能造成嚴重不公。"},{"en":"The phrase describes the process of finding deception.","zh":"這個片語描述找出欺騙的過程。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":17},{"front":"warn of the dangers behind","meaning":"警告……背後的危險","examples":[{"en":"One scholar warns of the dangers behind lie-detection technology.","zh":"一位學者警告測謊技術背後的危險。"},{"en":"Warn of the dangers behind means alert people to hidden or serious risks connected with something.","zh":"warn of the dangers behind 指提醒人們注意某事背後隱藏或嚴重的風險。"},{"en":"Doctors warn of the dangers behind buying medicine from unknown websites.","zh":"醫生警告從不明網站購買藥物背後的危險。"},{"en":"If scholars warn of dangers behind a technology, they want people to slow down and think.","zh":"如果學者警告技術背後的危險，他們希望人們放慢並思考。"},{"en":"The phrase focuses on caution about risks that may not be obvious.","zh":"這個片語集中於對不明顯風險的謹慎。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":17},{"front":"lie-detection technology","meaning":"測謊技術","examples":[{"en":"Lie-detection technology may have serious legal consequences.","zh":"測謊技術可能有嚴重法律後果。"},{"en":"Lie-detection technology is technology designed to identify whether someone is lying.","zh":"lie-detection technology 是設計來識別某人是否說謊的技術。"},{"en":"Police dramas often show lie-detection technology being used during questioning.","zh":"警匪劇常展示測謊技術在盤問期間被使用。"},{"en":"If lie-detection technology is unreliable, it can damage reputations and court cases.","zh":"如果測謊技術不可靠，它可以損害名譽和法庭案件。"},{"en":"The phrase covers tools such as polygraphs and brain-based scans.","zh":"這個片語涵蓋測謊機和基於大腦的掃描等工具。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":17},{"front":"limit something to research","meaning":"把……限制於研究用途","examples":[{"en":"Some scholars call for limiting the technology to research.","zh":"有些學者要求把這項技術限制於研究用途。"},{"en":"Limit something to research means allow it only in scientific study, not wider public use.","zh":"limit something to research 指只容許它用於科學研究，而非更廣泛公眾用途。"},{"en":"A risky medical test may be limited to research until safety is proven.","zh":"有風險的醫學測試可能被限制於研究用途，直到安全性被證明。"},{"en":"If a technology is limited to research, companies cannot freely sell it for everyday use.","zh":"如果技術被限制於研究用途，公司就不能自由把它售作日常用途。"},{"en":"The phrase shows restricted use for safety or evidence reasons.","zh":"這個片語顯示出於安全或證據原因而限制使用。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":18},{"front":"successful real-world applications","meaning":"成功的現實應用","examples":[{"en":"The company reports successful real-world applications of the technology.","zh":"該公司報告這項技術有成功的現實應用。"},{"en":"Successful real-world applications are uses that work well in actual situations outside the laboratory.","zh":"successful real-world applications 是在實驗室以外實際情況中有效運作的用途。"},{"en":"A classroom app has successful real-world applications if students use it effectively in normal lessons.","zh":"如果學生在正常課堂中有效使用課堂應用程式，它就有成功的現實應用。"},{"en":"If a company claims successful real-world applications, independent checks are important.","zh":"如果公司聲稱有成功的現實應用，獨立檢查很重要。"},{"en":"The phrase contrasts practical success with laboratory results.","zh":"這個片語把實際成功與實驗室結果作對比。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":18},{"front":"identify shortcomings in","meaning":"指出……的不足之處","examples":[{"en":"Researchers identify shortcomings in current lie-detection research.","zh":"研究人員指出目前測謊研究的不足之處。"},{"en":"Identify shortcomings in means point out weaknesses, gaps, or limits in something.","zh":"identify shortcomings in 指指出某事的弱點、缺口或限制。"},{"en":"A teacher may identify shortcomings in a student’s essay before revision.","zh":"老師可能在學生修改前指出作文的不足之處。"},{"en":"If experts identify shortcomings in research, later studies can be designed better.","zh":"如果專家指出研究的不足之處，後續研究可以設計得更好。"},{"en":"The phrase is critical but useful for improvement.","zh":"這個片語帶批判性，但有助改善。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":18},{"front":"current lie-detection research","meaning":"目前的測謊研究","examples":[{"en":"Current lie-detection research still has many weaknesses.","zh":"目前的測謊研究仍有許多弱點。"},{"en":"Current lie-detection research means the existing studies now being discussed about detecting lies.","zh":"current lie-detection research 指目前正在討論的關於偵測謊言的現有研究。"},{"en":"Current lie-detection research may not include enough older adults or real criminal cases.","zh":"目前的測謊研究可能沒有包括足夠年長成人或真實刑事案件。"},{"en":"If current lie-detection research is limited, public use should remain cautious.","zh":"如果目前的測謊研究有限，公眾使用應保持謹慎。"},{"en":"The phrase refers to the present state of research evidence.","zh":"這個片語指研究證據的當前狀態。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":18},{"front":"further work is needed","meaning":"仍需要進一步工作","examples":[{"en":"Further work is needed to improve lie-detection technology.","zh":"仍需要進一步工作來改善測謊技術。"},{"en":"Further work is needed means more study, testing, or development must be done.","zh":"further work is needed 指仍必須進行更多研究、測試或發展。"},{"en":"A teacher may say further work is needed before an essay is ready.","zh":"老師可能說作文準備好之前仍需要進一步工作。"},{"en":"If further work is needed, a technology should not be treated as settled.","zh":"如果仍需要進一步工作，就不應把技術視為已定論。"},{"en":"The phrase signals that the job is not complete.","zh":"這個片語表示工作尚未完成。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":18},{"front":"improve lie-detection technology","meaning":"改善測謊技術","examples":[{"en":"Researchers need more evidence to improve lie-detection technology.","zh":"研究人員需要更多證據來改善測謊技術。"},{"en":"Improve lie-detection technology means make tools for detecting lies more accurate, fair, and reliable.","zh":"improve lie-detection technology 指令偵測謊言的工具更準確、公平和可靠。"},{"en":"Better test design can improve lie-detection technology by reducing artificial tasks.","zh":"更好的測試設計可以透過減少人為任務來改善測謊技術。"},{"en":"If scientists improve lie-detection technology, courts may still need strict rules for use.","zh":"如果科學家改善測謊技術，法庭仍可能需要嚴格使用規則。"},{"en":"The phrase focuses on developing a risky tool more carefully.","zh":"這個片語集中於更小心地發展一種有風險的工具。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":18},{"front":"agree with the information given in","meaning":"與文章提供的資料一致","examples":[{"en":"Students decide whether statements agree with the information given in the passage.","zh":"學生判斷陳述是否與文章提供的資料一致。"},{"en":"Agree with the information given in means match what the text clearly says.","zh":"agree with the information given in 指與文本清楚說明的內容相符。"},{"en":"In a reading test, an answer agrees with the information only if the passage supports it.","zh":"在閱讀測驗中，只有當文章支持答案，它才與資料一致。"},{"en":"If a statement changes one key detail, it may not agree with the information given.","zh":"如果陳述改變一個關鍵細節，它可能不與所給資料一致。"},{"en":"The phrase is common in TRUE, FALSE, NOT GIVEN tasks.","zh":"這個片語常見於 TRUE、FALSE、NOT GIVEN 題。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":18},{"front":"if the statement agrees with","meaning":"如果陳述與……一致","examples":[{"en":"Students write TRUE if the statement agrees with the information.","zh":"如果陳述與資料一致，學生寫 TRUE。"},{"en":"If the statement agrees with means if the sentence matches what the passage says.","zh":"if the statement agrees with 指如果句子與文章所說內容相符。"},{"en":"If the statement agrees with the timetable, students should mark it correct.","zh":"如果陳述與時間表一致，學生應把它標為正確。"},{"en":"If a statement agrees with one paragraph but contradicts another, students must read carefully.","zh":"如果陳述與一段一致但與另一段矛盾，學生必須仔細閱讀。"},{"en":"The phrase introduces the condition for choosing TRUE.","zh":"這個片語引出選 TRUE 的條件。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":18},{"front":"contradicts the information","meaning":"與資料相矛盾","examples":[{"en":"Students write FALSE if the statement contradicts the information.","zh":"如果陳述與資料相矛盾，學生寫 FALSE。"},{"en":"Contradicts the information means says the opposite of what the passage states.","zh":"contradicts the information 指說出與文章陳述相反的內容。"},{"en":"If a notice says the library closes at six, “it closes at eight” contradicts the information.","zh":"如果告示說圖書館六點關門，「它八點關門」就與資料相矛盾。"},{"en":"A statement can contradict the information by changing a date, number, or cause.","zh":"陳述可以透過改變日期、數字或原因而與資料相矛盾。"},{"en":"The phrase is different from not mentioned.","zh":"這個片語不同於沒有提及。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":18},{"front":"there is no information on this","meaning":"沒有關於這方面的資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有關於這方面的資料，學生寫 NOT GIVEN。"},{"en":"There is no information on this means the passage does not say enough to decide.","zh":"there is no information on this 指文章沒有足夠資料作判斷。"},{"en":"If an article describes a company but not its profits, there is no information on this profit question.","zh":"如果文章描述公司但沒有說利潤，就沒有關於這個利潤問題的資料。"},{"en":"When there is no information on this, students should not use outside knowledge.","zh":"當沒有關於這方面的資料時，學生不應使用外部知識。"},{"en":"The phrase signals a NOT GIVEN answer.","zh":"這個片語表示答案是 NOT GIVEN。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":18},{"front":"convicted woman","meaning":"被定罪的女子","examples":[{"en":"The convicted woman denied committing the crime.","zh":"被定罪的女子否認犯案。"},{"en":"A convicted woman is a woman who has been found guilty of a crime by a court.","zh":"convicted woman 是被法庭裁定犯有罪行的女子。"},{"en":"A reporter may describe a convicted woman carefully to avoid implying more than the court found.","zh":"記者可能小心描述被定罪的女子，以避免暗示超出法庭裁決的內容。"},{"en":"If a convicted woman denies the crime, the denial does not erase the conviction.","zh":"如果被定罪的女子否認犯罪，否認並不會消除定罪。"},{"en":"The phrase describes legal status, not personality.","zh":"這個片語描述法律身份，而不是性格。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":19},{"front":"first conducted by","meaning":"首先由……進行","examples":[{"en":"The question asks whether the test was first conducted by European researchers.","zh":"題目問該測試是否首先由歐洲研究人員進行。"},{"en":"First conducted by means originally carried out by a particular person or group.","zh":"first conducted by 指最初由某人或某群體進行。"},{"en":"A study may be first conducted by university researchers before companies use it.","zh":"研究可能首先由大學研究人員進行，之後公司才使用。"},{"en":"If a test was first conducted by one group, later studies may try to repeat it.","zh":"如果測試首先由一個團隊進行，後來研究可能嘗試重複它。"},{"en":"The phrase focuses on who did something first.","zh":"這個片語集中於誰首先做某事。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":19},{"front":"European researchers","meaning":"歐洲研究人員","examples":[{"en":"The brain-scan study was carried out by researchers in Europe.","zh":"這項腦部掃描研究由歐洲研究人員進行。"},{"en":"European researchers are researchers working in or from European countries.","zh":"European researchers 是在歐洲國家工作或來自歐洲國家的研究人員。"},{"en":"European researchers may collaborate with American and Asian universities.","zh":"歐洲研究人員可能與美國和亞洲大學合作。"},{"en":"If European researchers publish a study, other teams may test whether results apply elsewhere.","zh":"如果歐洲研究人員發表研究，其他團隊可能測試結果是否適用於其他地方。"},{"en":"The phrase identifies researchers by region.","zh":"這個片語按地區識別研究人員。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":19},{"front":"allowing scans as evidence","meaning":"容許掃描作為證據","examples":[{"en":"Allowing scans as evidence in court could create a new market.","zh":"容許掃描在法庭中作為證據，可能創造新市場。"},{"en":"Allowing scans as evidence means permitting scan results to support legal arguments.","zh":"allowing scans as evidence 指容許掃描結果支持法律論點。"},{"en":"A judge may hesitate before allowing scans as evidence if the science is uncertain.","zh":"如果科學不確定，法官可能會猶豫是否容許掃描作為證據。"},{"en":"If courts allow scans as evidence, lawyers may request them more often.","zh":"如果法庭容許掃描作為證據，律師可能更常要求使用。"},{"en":"The phrase focuses on legal acceptance of scientific material.","zh":"這個片語集中於法律對科學材料的接納。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":19},{"front":"evidence in court","meaning":"法庭證據","examples":[{"en":"Brain scans might one day be offered as evidence in court.","zh":"腦部掃描有一天可能作為法庭證據提交。"},{"en":"Evidence in court is information presented to help prove or disprove a legal claim.","zh":"evidence in court 是為證明或反駁法律主張而提交的資料。"},{"en":"A video recording can become evidence in court if it is relevant and accepted.","zh":"如果錄影片段相關並獲接納，就可以成為法庭證據。"},{"en":"If brain scans are used as evidence in court, judges must understand their limits.","zh":"如果腦部掃描用作法庭證據，法官必須理解其限制。"},{"en":"The phrase refers to material used in legal proceedings.","zh":"這個片語指法律程序中使用的材料。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":19},{"front":"promising and profitable business","meaning":"有前景而有利可圖的生意","examples":[{"en":"The use of scans in court could become a promising and profitable business.","zh":"在法庭中使用掃描可能成為有前景而有利可圖的生意。"},{"en":"A promising and profitable business is one that seems likely to succeed and earn money.","zh":"promising and profitable business 是看似可能成功並賺錢的生意。"},{"en":"Online tutoring can be a promising and profitable business if demand is strong.","zh":"如果需求強勁，網上補習可以是有前景而有利可圖的生意。"},{"en":"If courts accept scan evidence, companies may see a promising and profitable business opportunity.","zh":"如果法庭接納掃描證據，公司可能看見有前景而有利可圖的商機。"},{"en":"The phrase combines future potential with financial gain.","zh":"這個片語結合未來潛力和財務收益。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":19},{"front":"invariably produces incorrect results","meaning":"總是產生錯誤結果","examples":[{"en":"The statement claims that neuroimaging invariably produces incorrect results.","zh":"該陳述聲稱神經影像技術總是產生錯誤結果。"},{"en":"Invariably produces incorrect results means always gives wrong results.","zh":"invariably produces incorrect results 指總是給出錯誤結果。"},{"en":"A broken calculator does not invariably produce incorrect results; sometimes it may still show a correct number by chance.","zh":"壞了的計算機不一定總是產生錯誤結果；有時可能碰巧顯示正確數字。"},{"en":"If a test invariably produces incorrect results, it should never be trusted.","zh":"如果測試總是產生錯誤結果，就絕不應被信任。"},{"en":"The phrase is very strong because invariably means always.","zh":"這個片語語氣很強，因為 invariably 指總是。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":19},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill missing words in the short text that follows.","zh":"complete the summary below 指在下方短文中填上缺失字詞。"},{"en":"In a reading test, students complete the summary below by locating exact ideas in the passage.","zh":"在閱讀測驗中，學生透過定位文章中的確切意思來完成以下摘要。"},{"en":"If students choose words that do not fit grammatically, the summary may be wrong.","zh":"如果學生選擇文法上不合適的字詞，摘要可能錯。"},{"en":"The phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":19},{"front":"no more than three words","meaning":"不超過三個字","examples":[{"en":"Students should choose no more than three words from the passage.","zh":"學生應從文章中選擇不超過三個字。"},{"en":"No more than three words means one, two, or three words only.","zh":"no more than three words 指只能用一個、兩個或三個詞。"},{"en":"If the answer is “blood pressure”, it follows the no more than three words rule.","zh":"如果答案是 blood pressure，它符合不超過三個詞的規則。"},{"en":"If students write four words, the answer may be marked wrong even if the idea is correct.","zh":"如果學生寫四個詞，即使意思正確，也可能被判錯。"},{"en":"The phrase gives a strict word limit.","zh":"這個片語給出嚴格字數限制。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":19},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must come from the passage.","zh":"答案必須從文章中得出。"},{"en":"From the passage means taken directly from the reading text provided.","zh":"from the passage 指直接取自所提供的閱讀文本。"},{"en":"In exam tasks, students should not use outside knowledge when answers must come from the passage.","zh":"在考試題中，如果答案必須從文章中得出，學生不應使用外部知識。"},{"en":"If a word is not from the passage, it may not be accepted in a summary task.","zh":"如果某詞不是來自文章，在摘要題中可能不被接受。"},{"en":"The phrase tells students where the evidence and wording should come from.","zh":"這個片語告訴學生證據和用字應來自哪裡。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":19},{"front":"it is claimed that","meaning":"有人聲稱","examples":[{"en":"It is claimed that fMRI can detect lies by observing brain activity.","zh":"有人聲稱 fMRI 可以透過觀察大腦活動偵測謊言。"},{"en":"It is claimed that means someone says something is true, but the writer may not fully accept it.","zh":"it is claimed that 指有人說某事為真，但作者未必完全接受。"},{"en":"It is claimed that the new app improves memory, but the study is small.","zh":"有人聲稱新應用程式改善記憶，但研究規模很小。"},{"en":"If it is claimed that a machine is accurate, readers should ask who made the claim.","zh":"如果有人聲稱機器準確，讀者應問是誰作出聲稱。"},{"en":"The phrase creates distance between the writer and the claim.","zh":"這個片語在作者與聲稱之間保持距離。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":20},{"front":"observing activity inside the brain","meaning":"觀察大腦內部活動","examples":[{"en":"fMRI detects lies by observing activity inside the brain.","zh":"fMRI 透過觀察大腦內部活動來偵測謊言。"},{"en":"Observing activity inside the brain means watching or measuring which brain areas become active.","zh":"observing activity inside the brain 指觀察或量度哪些腦區變得活躍。"},{"en":"Researchers may observe activity inside the brain while a person reads or solves puzzles.","zh":"研究人員可能在人閱讀或解謎時觀察大腦內部活動。"},{"en":"If scientists observe activity inside the brain during lying tasks, they can compare patterns.","zh":"如果科學家在說謊任務中觀察大腦內部活動，就能比較模式。"},{"en":"The phrase refers to measurement through imaging, not direct eyesight.","zh":"這個片語指透過影像量度，而不是直接用眼看。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":20},{"front":"rather than monitoring","meaning":"而不是監察","examples":[{"en":"fMRI observes brain activity rather than monitoring peripheral anxiety signs.","zh":"fMRI 觀察大腦活動，而不是監察周邊焦慮跡象。"},{"en":"Rather than monitoring means instead of watching or measuring something.","zh":"rather than monitoring 指而不是觀察或量度某事。"},{"en":"A teacher may assess speaking through real conversation rather than monitoring only test scores.","zh":"老師可能透過真實對話評估口語，而不是只監察考試分數。"},{"en":"If researchers study brain activity rather than monitoring pulse, they use a different kind of evidence.","zh":"如果研究人員研究大腦活動，而不是監察脈搏，他們使用的是不同類型證據。"},{"en":"The phrase creates a clear contrast between two methods.","zh":"這個片語在兩種方法之間形成清楚對比。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":20},{"front":"television audiences","meaning":"電視觀眾","examples":[{"en":"Television audiences were fascinated by the lie-detection technology.","zh":"電視觀眾對測謊技術着迷。"},{"en":"Television audiences are the people who watch programmes on television or related media.","zh":"television audiences 是觀看電視或相關媒體節目的人。"},{"en":"Television audiences may enjoy science shows when complex ideas are explained clearly.","zh":"當複雜概念被清楚解釋時，電視觀眾可能喜歡科學節目。"},{"en":"If television audiences become excited about a technology, public attention can grow quickly.","zh":"如果電視觀眾對某技術感到興奮，公眾關注可以迅速增長。"},{"en":"The phrase refers to viewers as a group.","zh":"這個片語把觀眾視為一個群體。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":20},{"front":"be fascinated by","meaning":"對……着迷","examples":[{"en":"Both television audiences and entrepreneurs have been fascinated by the technology.","zh":"電視觀眾和企業家都對這項技術着迷。"},{"en":"Be fascinated by means be very interested in or strongly attracted to something.","zh":"be fascinated by 指對某事非常感興趣或強烈被吸引。"},{"en":"Children may be fascinated by magnets when they see metal objects move.","zh":"孩子看到金屬物件移動時，可能對磁鐵着迷。"},{"en":"If investors are fascinated by a new technology, money may arrive before proof is complete.","zh":"如果投資者對新技術着迷，資金可能在證據完整前已湧入。"},{"en":"The phrase shows strong curiosity or attraction.","zh":"這個片語顯示強烈好奇或吸引。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":20},{"front":"lie-detection technology","meaning":"測謊技術","examples":[{"en":"Lie-detection technology attracts both scientists and entrepreneurs.","zh":"測謊技術吸引科學家和企業家。"},{"en":"Lie-detection technology is technology used to judge whether a person is lying.","zh":"lie-detection technology 是用來判斷某人是否說謊的技術。"},{"en":"A company may promote lie-detection technology for security or legal purposes.","zh":"公司可能為安全或法律用途推廣測謊技術。"},{"en":"If lie-detection technology becomes popular before it is reliable, people may be harmed.","zh":"如果測謊技術在可靠前已變得流行，人們可能受害。"},{"en":"The phrase describes a field where science, business, and law overlap.","zh":"這個片語描述科學、商業和法律重疊的領域。"}],"source":"128 - Lighting up the lies.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 129":[{"front":"New Agriculture in Oregon","meaning":"俄勒岡州的新農業","examples":[{"en":"The passage describes new agriculture in Oregon, US.","zh":"文章描述美國俄勒岡州的新農業。"},{"en":"New agriculture in Oregon refers to farming methods that save resources and reduce environmental harm.","zh":"「俄勒岡州的新農業」指節省資源並減少環境傷害的耕作方法。"},{"en":"Farmers in Oregon are testing new agriculture by using less water, fewer pesticides and better soil protection.","zh":"俄勒岡州農民透過少用水、少用農藥和更好保護土壤來測試新農業。"},{"en":"New agriculture can help farms stay productive while reducing damage to land and water.","zh":"新農業可以幫助農場保持產量，同時減少對土地和水的破壞。"},{"en":"This topic shows that farming can change through science, local testing and cooperation.","zh":"這個主題顯示農業可以透過科學、本地測試和合作而改變。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":1},{"front":"onion growers","meaning":"洋蔥種植者","examples":[{"en":"Onion growers in eastern Oregon are adopting a new system.","zh":"俄勒岡州東部的洋蔥種植者正在採用一套新系統。"},{"en":"Onion growers are farmers who grow onions for sale or food production.","zh":"「onion growers」是種植洋蔥作銷售或食物生產的農民。"},{"en":"Onion growers may need irrigation because onions require steady moisture to develop well.","zh":"洋蔥種植者可能需要灌溉，因為洋蔥需要穩定水分才能長得好。"},{"en":"If onion growers save water, they can reduce costs and protect local streams.","zh":"如果洋蔥種植者節省用水，他們可以降低成本並保護本地溪流。"},{"en":"The phrase names a specific group of farmers, not all farmers in general.","zh":"這個短語指特定一類農民，而不是所有農民。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":1},{"front":"eastern Oregon","meaning":"俄勒岡州東部","examples":[{"en":"Onion growers in eastern Oregon are adopting a system that saves water.","zh":"俄勒岡州東部的洋蔥種植者正在採用一套節省用水的系統。"},{"en":"Eastern Oregon means the eastern part of the US state of Oregon.","zh":"「eastern Oregon」指美國俄勒岡州的東部地區。"},{"en":"Farmers in eastern Oregon may face dry conditions and need careful irrigation.","zh":"俄勒岡州東部的農民可能面對乾燥環境，需要小心灌溉。"},{"en":"If water is limited in eastern Oregon, saving water becomes especially important.","zh":"如果俄勒岡州東部水源有限，節省用水就特別重要。"},{"en":"The phrase gives the location of the farming example.","zh":"這個短語指出農業例子的地點。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":1},{"front":"adopt a system","meaning":"採用一套系統","examples":[{"en":"Farmers can adopt a system that saves water and protects soil.","zh":"農民可以採用一套節省用水並保護土壤的系統。"},{"en":"To adopt a system means to start using a planned method or set of practices.","zh":"「adopt a system」意思是開始使用一套有規劃的方法或做法。"},{"en":"A school may adopt a system for recording homework online.","zh":"學校可能採用一套網上記錄功課的系統。"},{"en":"If farmers adopt a better system, they may reduce waste and improve results.","zh":"如果農民採用更好的系統，他們可能減少浪費並改善成果。"},{"en":"The phrase suggests choosing and using a method, not just discussing it.","zh":"這個短語暗示選擇並使用方法，而不只是討論它。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":1},{"front":"save water","meaning":"節省用水","examples":[{"en":"The new farming system saves water.","zh":"這套新農業系統節省用水。"},{"en":"To save water means to use less water or avoid wasting it.","zh":"「save water」意思是使用較少水或避免浪費水。"},{"en":"Families can save water by fixing leaking taps and taking shorter showers.","zh":"家庭可以透過修理漏水水龍頭和縮短淋浴時間節省用水。"},{"en":"Farms that save water can lower costs and protect rivers during dry periods.","zh":"節省用水的農場可以降低成本，並在乾旱時期保護河流。"},{"en":"Saving water is important when water supplies are limited.","zh":"當供水有限時，節省用水很重要。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":1},{"front":"keep topsoil in place","meaning":"固定表土；防止表土流失","examples":[{"en":"The system saves water and keeps topsoil in place.","zh":"這套系統節省用水並固定表土。"},{"en":"To keep topsoil in place means to stop the upper layer of soil from being blown or washed away.","zh":"「keep topsoil in place」意思是防止上層泥土被風吹走或水沖走。"},{"en":"Plant cover can keep topsoil in place during heavy rain.","zh":"植物覆蓋可以在大雨期間固定表土。"},{"en":"If topsoil is not kept in place, farms may lose nutrients and become less productive.","zh":"如果表土沒有被固定，農場可能失去養分並降低產量。"},{"en":"The phrase is about preventing soil erosion.","zh":"這個短語關於防止土壤侵蝕。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":1},{"front":"topsoil","meaning":"表土","examples":[{"en":"Protecting topsoil is important for sustainable farming.","zh":"保護表土對可持續農業很重要。"},{"en":"Topsoil is the upper layer of soil where many nutrients and roots are found.","zh":"「topsoil」是含有許多養分和根部的上層泥土。"},{"en":"Gardeners improve topsoil by adding compost and avoiding unnecessary digging.","zh":"園丁透過加入堆肥和避免不必要挖掘來改善表土。"},{"en":"When topsoil is lost, crops may grow poorly because the best soil has disappeared.","zh":"當表土流失，農作物可能長得差，因為最好的泥土消失了。"},{"en":"Healthy topsoil is a basic resource for farming.","zh":"健康表土是農業的基本資源。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":1},{"front":"produce the highest quality","meaning":"生產最高質素的……","examples":[{"en":"The system produces the highest quality onions.","zh":"這套系統生產最高質素的洋蔥。"},{"en":"To produce the highest quality means to make products that meet a very high standard.","zh":"「produce the highest quality」意思是製造或生產符合很高標準的產品。"},{"en":"A bakery can produce the highest quality bread by using fresh ingredients and careful methods.","zh":"麵包店可以透過使用新鮮材料和仔細方法生產最高質素的麵包。"},{"en":"If farms produce the highest quality crops, they may earn better prices.","zh":"如果農場生產最高質素的作物，它們可能取得更好價格。"},{"en":"The phrase focuses on excellence, not just quantity.","zh":"這個短語集中於卓越質素，而不只是數量。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":1},{"front":"super-colossal onions","meaning":"特大型洋蔥","examples":[{"en":"Oregon growers produce high-quality super-colossal onions.","zh":"俄勒岡州種植者生產高質素的特大型洋蔥。"},{"en":"Super-colossal onions are extremely large onions that meet a special size grade.","zh":"「super-colossal onions」是符合特殊尺寸等級的極大型洋蔥。"},{"en":"Restaurants may prefer super-colossal onions because one onion can make many slices.","zh":"餐廳可能偏好特大型洋蔥，因為一個洋蔥可以切出許多片。"},{"en":"If a system produces super-colossal onions, growers may reach a valuable market.","zh":"如果一套系統能生產特大型洋蔥，種植者可能進入有價值的市場。"},{"en":"The phrase describes both size and commercial value.","zh":"這個短語同時描述尺寸和商業價值。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":1},{"front":"pear growers","meaning":"梨種植者","examples":[{"en":"Pear growers in southern Oregon have reduced their use of toxic pesticides.","zh":"俄勒岡州南部的梨種植者已減少使用有毒農藥。"},{"en":"Pear growers are farmers who grow pears for sale or processing.","zh":"「pear growers」是種植梨作銷售或加工的農民。"},{"en":"Pear growers must protect fruit from insects while keeping the fruit attractive.","zh":"梨種植者必須保護水果免受昆蟲侵害，同時保持外觀吸引。"},{"en":"If pear growers reduce pesticide use, they may lower environmental and health risks.","zh":"如果梨種植者減少農藥使用，他們可能降低環境和健康風險。"},{"en":"The phrase names a specific group within fruit farming.","zh":"這個短語指水果種植中的特定群體。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":1},{"front":"southern Oregon","meaning":"俄勒岡州南部","examples":[{"en":"Pear growers in southern Oregon have changed their pesticide use.","zh":"俄勒岡州南部的梨種植者已改變農藥使用方式。"},{"en":"Southern Oregon means the southern part of the US state of Oregon.","zh":"「southern Oregon」指美國俄勒岡州的南部地區。"},{"en":"Farms in southern Oregon may grow fruit that needs careful pest control.","zh":"俄勒岡州南部的農場可能種植需要仔細害蟲控制的水果。"},{"en":"If researchers work with growers in southern Oregon, local conditions can guide the solution.","zh":"如果研究人員與俄勒岡州南部的種植者合作，本地條件可以引導解決方案。"},{"en":"The phrase gives the regional setting of the pear example.","zh":"這個短語提供梨子例子的地區背景。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":1},{"front":"reduce their use of","meaning":"減少使用……","examples":[{"en":"Pear growers have reduced their use of toxic pesticides.","zh":"梨種植者已減少使用有毒農藥。"},{"en":"To reduce their use of something means to use less of it than before.","zh":"「reduce their use of」某物，意思是比以前少用它。"},{"en":"Offices can reduce their use of paper by sending documents online.","zh":"辦公室可以透過網上發送文件減少使用紙張。"},{"en":"Farmers may reduce their use of chemicals when safer methods become available.","zh":"當有更安全的方法可用，農民可能減少使用化學品。"},{"en":"The phrase suggests a decrease, not a complete stop.","zh":"這個短語表示減少，而不是完全停止。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":2},{"front":"toxic pesticides","meaning":"有毒農藥","examples":[{"en":"Some pear growers have reduced their use of toxic pesticides.","zh":"一些梨種植者已減少使用有毒農藥。"},{"en":"Toxic pesticides are chemicals used to kill pests but harmful to people, animals or the environment.","zh":"「toxic pesticides」是用來殺害害蟲但對人、動物或環境有害的化學品。"},{"en":"Farm workers need protection when handling toxic pesticides.","zh":"農場工人處理有毒農藥時需要保護。"},{"en":"If toxic pesticides enter rivers, they can harm fish and drinking water.","zh":"如果有毒農藥進入河流，它們可以傷害魚類和飲用水。"},{"en":"The phrase highlights danger, not just pest control.","zh":"這個短語強調危險，而不只是害蟲控制。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":2},{"front":"by up to two-thirds","meaning":"多達三分之二","examples":[{"en":"Pear growers have reduced some pesticide use by up to two-thirds.","zh":"梨種植者已將部分農藥使用量減少多達三分之二。"},{"en":"By up to two-thirds means by as much as about 66 percent.","zh":"「by up to two-thirds」意思是幅度最高可達約百分之六十六。"},{"en":"A shop may cut prices by up to two-thirds during a clearance sale.","zh":"商店清貨時可能把價格削減多達三分之二。"},{"en":"If pesticide use falls by up to two-thirds, the reduction is very large.","zh":"如果農藥使用量下降多達三分之二，減幅就非常大。"},{"en":"The phrase gives a maximum amount, not necessarily the result everywhere.","zh":"這個短語提供最高幅度，不一定代表每處結果都一樣。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":2},{"front":"still producing","meaning":"仍然生產","examples":[{"en":"The growers are using fewer pesticides while still producing top-quality pears.","zh":"種植者使用較少農藥，同時仍然生產優質梨。"},{"en":"Still producing means continuing to make or grow something despite a change or difficulty.","zh":"「still producing」意思是在改變或困難下仍繼續製造或種植某物。"},{"en":"A factory can reduce energy use while still producing the same number of goods.","zh":"工廠可以減少能源使用，同時仍然生產相同數量的貨品。"},{"en":"If farmers use fewer chemicals while still producing good crops, the new method is practical.","zh":"如果農民少用化學品但仍然生產好作物，新方法就是實際可行的。"},{"en":"The phrase highlights that quality or output continues.","zh":"這個短語強調質素或產量仍然持續。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":2},{"front":"top-quality pears","meaning":"優質梨","examples":[{"en":"Oregon pear growers are still producing top-quality pears.","zh":"俄勒岡州梨種植者仍然生產優質梨。"},{"en":"Top-quality pears are pears with excellent taste, appearance and market value.","zh":"「top-quality pears」是味道、外觀和市場價值都很高的梨。"},{"en":"Shoppers often choose top-quality pears that look fresh and have no serious marks.","zh":"購物者常選擇看起來新鮮且沒有嚴重痕跡的優質梨。"},{"en":"If growers can produce top-quality pears with fewer chemicals, both farmers and consumers benefit.","zh":"如果種植者能用較少化學品生產優質梨，農民和消費者都受益。"},{"en":"The phrase describes high standards in fruit production.","zh":"這個短語描述水果生產中的高標準。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":2},{"front":"range managers","meaning":"牧場管理人員","examples":[{"en":"Range managers throughout Oregon have controlled a poisonous weed.","zh":"俄勒岡州各地的牧場管理人員已控制一種有毒雜草。"},{"en":"Range managers are people who manage land used for grazing animals.","zh":"「range managers」是管理用於放牧牲畜土地的人員。"},{"en":"Range managers may check grass, water, weeds and livestock health.","zh":"牧場管理人員可能檢查草地、水源、雜草和牲畜健康。"},{"en":"If range managers control poisonous plants, they can protect cattle and sheep.","zh":"如果牧場管理人員控制有毒植物，他們可以保護牛羊。"},{"en":"The phrase refers to land-management workers, not shop managers.","zh":"這個短語指土地管理人員，而不是商店經理。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":2},{"front":"throughout the state","meaning":"遍及全州","examples":[{"en":"Range managers throughout the state have used insect predators.","zh":"遍及全州的牧場管理人員使用了捕食性昆蟲。"},{"en":"Throughout the state means in many parts of the whole state.","zh":"「throughout the state」意思是在整個州的許多地方。"},{"en":"Schools throughout the state may follow the same exam rules.","zh":"遍及全州的學校可能遵循相同考試規則。"},{"en":"If a method is used throughout the state, it has spread beyond one local area.","zh":"如果一種方法遍及全州使用，它已傳播到不止一個本地地區。"},{"en":"The phrase describes wide geographical coverage.","zh":"這個短語描述廣泛地理覆蓋。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":2},{"front":"control a poisonous weed","meaning":"控制有毒雜草","examples":[{"en":"Range managers have controlled a poisonous weed with insect predators.","zh":"牧場管理人員用捕食性昆蟲控制有毒雜草。"},{"en":"To control a poisonous weed means to stop a harmful plant from spreading or causing damage.","zh":"「control a poisonous weed」意思是阻止有害植物擴散或造成傷害。"},{"en":"Farmers may control a poisonous weed before animals eat it by mistake.","zh":"農民可能在動物誤食前控制有毒雜草。"},{"en":"If a poisonous weed spreads, livestock may become sick or die.","zh":"如果有毒雜草擴散，牲畜可能生病或死亡。"},{"en":"The phrase is about managing a dangerous plant, not removing all plants.","zh":"這個短語關於管理危險植物，而不是清除所有植物。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":2},{"front":"tansy ragwort","meaning":"艾菊千里光","examples":[{"en":"Tansy ragwort is a poisonous weed that threatens livestock.","zh":"艾菊千里光是一種威脅牲畜的有毒雜草。"},{"en":"Tansy ragwort is a harmful weed that can poison grazing animals.","zh":"「tansy ragwort」是一種有害雜草，可以毒害放牧動物。"},{"en":"A farmer who finds tansy ragwort in a field may need to remove or control it quickly.","zh":"農民如果在田中發現艾菊千里光，可能需要迅速移除或控制它。"},{"en":"If livestock eat too much tansy ragwort, the farm may suffer animal losses.","zh":"如果牲畜吃太多艾菊千里光，農場可能遭受動物損失。"},{"en":"The phrase names a specific poisonous plant.","zh":"這個短語指出一種特定有毒植物。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":2},{"front":"insect predators","meaning":"捕食性昆蟲","examples":[{"en":"Insect predators can help control poisonous weeds.","zh":"捕食性昆蟲可以幫助控制有毒雜草。"},{"en":"Insect predators are insects that feed on other organisms or harmful plants.","zh":"「insect predators」是捕食其他生物或有害植物的昆蟲。"},{"en":"Ladybirds can act as insect predators when they eat aphids in gardens.","zh":"瓢蟲吃花園中的蚜蟲時，可以作為捕食性昆蟲。"},{"en":"If insect predators control pests naturally, farmers may need fewer chemical sprays.","zh":"如果捕食性昆蟲自然控制害蟲，農民可能需要較少化學噴劑。"},{"en":"The phrase describes biological control through living organisms.","zh":"這個短語描述透過生物進行的生物控制。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":2},{"front":"livestock industry","meaning":"畜牧業","examples":[{"en":"Biological control has saved the Oregon livestock industry millions of dollars.","zh":"生物控制為俄勒岡州畜牧業節省了數百萬美元。"},{"en":"The livestock industry includes businesses that raise animals such as cattle, sheep and goats.","zh":"「livestock industry」包括飼養牛、羊和山羊等動物的企業。"},{"en":"The livestock industry depends on healthy animals, safe pasture and reliable markets.","zh":"畜牧業依賴健康動物、安全牧場和穩定市場。"},{"en":"If poisonous weeds harm animals, the livestock industry can lose money quickly.","zh":"如果有毒雜草傷害動物，畜牧業可能很快損失金錢。"},{"en":"The phrase refers to animal farming as an economic sector.","zh":"這個短語指作為經濟部門的動物養殖業。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":2},{"front":"up to $4.8 million a year","meaning":"每年多達480萬美元","examples":[{"en":"The method has saved the industry up to $4.8 million a year.","zh":"這種方法每年為該行業節省多達480萬美元。"},{"en":"Up to $4.8 million a year means as much as 4.8 million dollars each year.","zh":"「up to $4.8 million a year」意思是每年最高可達480萬美元。"},{"en":"A company may save up to $10,000 a year by reducing electricity waste.","zh":"公司可能透過減少電力浪費每年節省多達一萬美元。"},{"en":"If a farming method saves up to millions each year, it has major economic value.","zh":"如果農業方法每年節省多達數百萬，它就有重大經濟價值。"},{"en":"The phrase gives the maximum yearly saving.","zh":"這個短語提供最高年度節省額。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":3},{"front":"results achieved in collaboration with","meaning":"與……合作取得的成果","examples":[{"en":"These are results achieved in collaboration with OSU researchers.","zh":"這些是與俄勒岡州立大學研究人員合作取得的成果。"},{"en":"Results achieved in collaboration with someone are outcomes produced by working together with them.","zh":"「results achieved in collaboration with」某人，指與他們合作產生的成果。"},{"en":"A school project can show results achieved in collaboration with parents and teachers.","zh":"學校項目可以展示與家長和老師合作取得的成果。"},{"en":"When farmers and scientists cooperate, they may achieve results neither group could reach alone.","zh":"當農民和科學家合作，他們可能取得任何一方單獨無法達到的成果。"},{"en":"The phrase highlights teamwork behind the success.","zh":"這個短語強調成功背後的團隊合作。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":3},{"front":"Oregon growers","meaning":"俄勒岡州種植者","examples":[{"en":"Oregon growers have tested new farming methods with university researchers.","zh":"俄勒岡州種植者與大學研究人員測試了新的耕作方法。"},{"en":"Oregon growers are farmers in Oregon who grow crops for sale.","zh":"「Oregon growers」是在俄勒岡州種植作物作銷售的農民。"},{"en":"Oregon growers may produce onions, pears, apples or other crops depending on the region.","zh":"俄勒岡州種植者可能因地區不同而生產洋蔥、梨、蘋果或其他作物。"},{"en":"If Oregon growers test new methods, local agriculture can become more efficient.","zh":"如果俄勒岡州種植者測試新方法，本地農業可以變得更有效率。"},{"en":"The phrase refers to crop producers in the state of Oregon.","zh":"這個短語指俄勒岡州的作物生產者。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":3},{"front":"Oregon State University","meaning":"俄勒岡州立大學","examples":[{"en":"Oregon State University researchers have worked with local growers.","zh":"俄勒岡州立大學研究人員與本地種植者合作。"},{"en":"Oregon State University is a university involved in agricultural research in Oregon.","zh":"俄勒岡州立大學是一所參與俄勒岡州農業研究的大學。"},{"en":"Farmers may work with Oregon State University when they need scientific testing on farms.","zh":"當農民需要在農場進行科學測試時，可能與俄勒岡州立大學合作。"},{"en":"If a university supports growers, research can move from laboratories into fields.","zh":"如果大學支援種植者，研究就可以從實驗室走進田地。"},{"en":"The phrase identifies the institution behind much of the research.","zh":"這個短語指出許多研究背後的機構。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":3},{"front":"OSU researchers","meaning":"俄勒岡州立大學研究人員","examples":[{"en":"OSU researchers help farmers test new agricultural methods.","zh":"俄勒岡州立大學研究人員幫助農民測試新的農業方法。"},{"en":"OSU researchers are researchers from Oregon State University.","zh":"「OSU researchers」是來自俄勒岡州立大學的研究人員。"},{"en":"OSU researchers may collect data from farms to see whether a method really works.","zh":"俄勒岡州立大學研究人員可能從農場收集數據，以了解某方法是否真的有效。"},{"en":"If OSU researchers work closely with growers, solutions can fit local problems better.","zh":"如果俄勒岡州立大學研究人員與種植者密切合作，解決方案可以更符合本地問題。"},{"en":"The phrase names the scientific partners in the passage.","zh":"這個短語指出文章中的科學合作夥伴。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":3},{"front":"test new farming methods","meaning":"測試新的耕作方法","examples":[{"en":"Growers and researchers test new farming methods together.","zh":"種植者和研究人員一起測試新的耕作方法。"},{"en":"To test new farming methods means to try new ways of growing crops and measure the results.","zh":"「test new farming methods」意思是嘗試新的種植方式並測量結果。"},{"en":"A farmer may test a new method on one field before using it everywhere.","zh":"農民可能先在一塊田測試新方法，再到所有田地使用。"},{"en":"Testing new methods helps farmers avoid costly mistakes.","zh":"測試新方法幫助農民避免昂貴錯誤。"},{"en":"The phrase shows practical experimentation, not just theory.","zh":"這個短語顯示實際實驗，而不只是理論。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":3},{"front":"integrated pest management","meaning":"綜合害蟲管理","examples":[{"en":"Integrated pest management can reduce pesticide use.","zh":"綜合害蟲管理可以減少農藥使用。"},{"en":"Integrated pest management is a pest-control approach that combines several methods instead of relying only on chemicals.","zh":"「integrated pest management」是一種結合多種方法、而不是只依賴化學品的害蟲控制方式。"},{"en":"A farm using integrated pest management may monitor insects, protect beneficial predators and spray only when needed.","zh":"使用綜合害蟲管理的農場可能監測昆蟲、保護有益捕食者，並只在需要時噴藥。"},{"en":"If integrated pest management works, it can reduce costs and environmental harm.","zh":"如果綜合害蟲管理有效，它可以降低成本和環境傷害。"},{"en":"The phrase means balanced pest control, not simply pesticide-free farming.","zh":"這個短語指平衡的害蟲控制，而不只是完全不用農藥的耕作。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":3},{"front":"IPM","meaning":"綜合害蟲管理","examples":[{"en":"IPM refers to integrated pest management.","zh":"IPM 指綜合害蟲管理。"},{"en":"IPM is the short form of integrated pest management.","zh":"「IPM」是 integrated pest management 的縮寫。"},{"en":"Farmers may use IPM to decide when pests truly need chemical control.","zh":"農民可能使用 IPM 來判斷害蟲何時真的需要化學控制。"},{"en":"If IPM is taught clearly, growers can choose safer and more effective pest-control methods.","zh":"如果 IPM 被清楚教授，種植者可以選擇更安全和更有效的害蟲控制方法。"},{"en":"The abbreviation is common in agricultural discussions.","zh":"這個縮寫常見於農業討論。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":3},{"front":"nationwide","meaning":"在全國範圍內","examples":[{"en":"Nationwide, IPM has not delivered the same results as in Oregon.","zh":"在全國範圍內，IPM 未能取得與俄勒岡州相同的成果。"},{"en":"Nationwide means across the whole country.","zh":"「nationwide」意思是在整個國家範圍內。"},{"en":"A nationwide health campaign reaches people in many cities and rural areas.","zh":"全國健康宣傳可以接觸許多城市和鄉郊地區的人。"},{"en":"If a policy works locally but not nationwide, conditions may differ across regions.","zh":"如果政策在本地有效但在全國範圍內無效，各地條件可能不同。"},{"en":"The phrase widens the discussion from one state to the whole country.","zh":"這個短語把討論從一個州擴展到整個國家。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":3},{"front":"deliver results comparable to","meaning":"取得可與……相比的成果","examples":[{"en":"IPM has not delivered results comparable to those in Oregon.","zh":"IPM 未能取得可與俄勒岡州相比的成果。"},{"en":"To deliver results comparable to something means to produce outcomes similar in quality or level.","zh":"「deliver results comparable to」某事，意思是產生在質素或水平上相似的成果。"},{"en":"A new school programme must deliver results comparable to the old one before it is expanded.","zh":"新學校計劃在擴展前，必須取得可與舊計劃相比的成果。"},{"en":"If a method does not deliver comparable results, people may question whether it works everywhere.","zh":"如果一種方法未能取得可相比成果，人們可能質疑它是否到處有效。"},{"en":"The phrase compares achievement, not just effort.","zh":"這個短語比較成就，而不只是努力。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":3},{"front":"comparable to","meaning":"可與……相比的","examples":[{"en":"National IPM results are not comparable to Oregon’s results.","zh":"全國 IPM 成果不可與俄勒岡州的成果相比。"},{"en":"Comparable to means similar enough to be fairly compared.","zh":"「comparable to」意思是相似到可以公平比較。"},{"en":"A small local shop may not be comparable to a large supermarket chain.","zh":"一間小本地店舖可能不可與大型超市連鎖店相比。"},{"en":"If two exam scores are not comparable, they may have come from very different tests.","zh":"如果兩個考試分數不可相比，它們可能來自非常不同的測驗。"},{"en":"The phrase helps judge whether a comparison is fair.","zh":"這個短語幫助判斷比較是否公平。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":3},{"front":"U.S. General Accounting Office","meaning":"美國總審計署","examples":[{"en":"The U.S. General Accounting Office issued a report on IPM.","zh":"美國總審計署發表了一份關於 IPM 的報告。"},{"en":"The U.S. General Accounting Office was a government office that reviewed federal programmes and spending.","zh":"「U.S. General Accounting Office」是審查聯邦計劃和開支的政府部門。"},{"en":"A government office may issue a report to show whether a policy is working.","zh":"政府部門可能發表報告，以顯示政策是否有效。"},{"en":"If the U.S. General Accounting Office criticises a programme, officials may need to respond.","zh":"如果美國總審計署批評某計劃，官員可能需要回應。"},{"en":"The phrase identifies the official source of the report.","zh":"這個短語指出報告的官方來源。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":4},{"front":"GAO report","meaning":"GAO 報告；總審計署報告","examples":[{"en":"The GAO report discusses the use of integrated pest management.","zh":"GAO 報告討論綜合害蟲管理的使用。"},{"en":"A GAO report is a report issued by the U.S. General Accounting Office.","zh":"「GAO report」是由美國總審計署發出的報告。"},{"en":"A GAO report may examine whether public money is being used effectively.","zh":"GAO 報告可能檢視公共資金是否被有效使用。"},{"en":"If a GAO report finds weak results, agencies may face pressure to improve.","zh":"如果 GAO 報告發現成果薄弱，機構可能面對改善壓力。"},{"en":"The phrase refers to an official review document.","zh":"這個短語指官方審查文件。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":4},{"front":"indicate that","meaning":"表示；顯示","examples":[{"en":"The report indicates that IPM can reduce pesticide use.","zh":"報告顯示 IPM 可以減少農藥使用。"},{"en":"Indicate that means show, suggest or point to a conclusion.","zh":"「indicate that」意思是顯示、暗示或指向某個結論。"},{"en":"Dark clouds may indicate that rain is coming soon.","zh":"烏雲可能表示快要下雨。"},{"en":"If test results indicate that a method works, people may use it more widely.","zh":"如果測試結果顯示某方法有效，人們可能更廣泛使用它。"},{"en":"The phrase is common when evidence supports a point.","zh":"當證據支持某一點時，這個短語很常見。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":4},{"front":"result in","meaning":"導致；帶來","examples":[{"en":"Integrated pest management can result in dramatically reduced pesticide use.","zh":"綜合害蟲管理可以帶來大幅減少農藥使用。"},{"en":"To result in something means to cause it to happen.","zh":"「result in」某事，意思是導致它發生。"},{"en":"Poor sleep can result in low concentration the next day.","zh":"睡眠不足可以導致第二天專注力低。"},{"en":"Better planning can result in fewer delays and lower costs.","zh":"更好規劃可以帶來較少延誤和較低成本。"},{"en":"The phrase clearly links cause and effect.","zh":"這個短語清楚連接原因和結果。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":4},{"front":"dramatically reduced pesticide use","meaning":"大幅減少農藥使用","examples":[{"en":"IPM can result in dramatically reduced pesticide use.","zh":"IPM 可以帶來大幅減少農藥使用。"},{"en":"Dramatically reduced pesticide use means pesticide use has fallen by a very large amount.","zh":"「dramatically reduced pesticide use」意思是農藥使用量大幅下降。"},{"en":"A farm may achieve dramatically reduced pesticide use by monitoring pests before spraying.","zh":"農場可以透過噴藥前監測害蟲來大幅減少農藥使用。"},{"en":"Dramatically reduced pesticide use can lower risks to workers, water and wildlife.","zh":"大幅減少農藥使用可以降低對工人、水源和野生動物的風險。"},{"en":"The phrase describes a major decrease, not a small improvement.","zh":"這個短語描述重大減少，而不是小改善。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":4},{"front":"federal government","meaning":"聯邦政府","examples":[{"en":"The federal government has failed to promote IPM effectively.","zh":"聯邦政府未能有效推廣 IPM。"},{"en":"The federal government is the national government of a country such as the United States.","zh":"「federal government」是美國等國家的全國性政府。"},{"en":"The federal government can fund research, set rules and support public programmes.","zh":"聯邦政府可以資助研究、制定規則和支援公共計劃。"},{"en":"If the federal government does not support a farming method, adoption may be slower.","zh":"如果聯邦政府不支援某種耕作方法，採用速度可能較慢。"},{"en":"The phrase refers to national-level authority, not local government.","zh":"這個短語指國家層面的權力，而不是地方政府。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":4},{"front":"fail to promote","meaning":"未能推廣","examples":[{"en":"The report says the government failed to promote IPM effectively.","zh":"報告說政府未能有效推廣 IPM。"},{"en":"To fail to promote something means not to encourage or spread it successfully.","zh":"「fail to promote」某事，意思是未能成功鼓勵或傳播它。"},{"en":"A school may fail to promote a reading programme if students never hear about it.","zh":"如果學生從未聽過閱讀計劃，學校可能未能推廣該計劃。"},{"en":"If agencies fail to promote safer farming methods, farmers may keep using old habits.","zh":"如果機構未能推廣更安全的耕作方法，農民可能繼續使用舊習慣。"},{"en":"The phrase shows that an effort was weak or unsuccessful.","zh":"這個短語顯示努力薄弱或不成功。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":4},{"front":"implement IPM","meaning":"實施綜合害蟲管理","examples":[{"en":"The federal government has failed to implement IPM effectively.","zh":"聯邦政府未能有效實施綜合害蟲管理。"},{"en":"To implement IPM means to put integrated pest management into actual use.","zh":"「implement IPM」意思是把綜合害蟲管理實際使用起來。"},{"en":"A farm can implement IPM by monitoring pests and using chemicals only when needed.","zh":"農場可以透過監測害蟲並只在需要時使用化學品來實施 IPM。"},{"en":"If farmers cannot implement IPM easily, the policy may remain only on paper.","zh":"如果農民不能輕易實施 IPM，政策可能只停留在紙上。"},{"en":"The phrase focuses on real practice, not just planning.","zh":"這個短語集中於實際做法，而不只是計劃。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":4},{"front":"pest-management options","meaning":"害蟲管理選項","examples":[{"en":"Farmers want pest-management options to be more attractive.","zh":"農民希望害蟲管理選項更具吸引力。"},{"en":"Pest-management options are different ways farmers can control insects, weeds or disease.","zh":"「pest-management options」是農民可用來控制昆蟲、雜草或疾病的不同方法。"},{"en":"A grower may compare pest-management options before choosing sprays or natural predators.","zh":"種植者可能在選擇噴劑或天然捕食者前比較害蟲管理選項。"},{"en":"If safer options are expensive, farmers may not use them even if they work.","zh":"如果較安全選項昂貴，即使有效，農民也可能不用。"},{"en":"The phrase refers to choices for dealing with pests.","zh":"這個短語指處理害蟲的選擇。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":4},{"front":"make something attractive","meaning":"使……具吸引力","examples":[{"en":"The government has not made the new pest-management options attractive.","zh":"政府未能使新的害蟲管理選項具吸引力。"},{"en":"To make something attractive means to make people want to choose or use it.","zh":"「make something attractive」意思是令人想選擇或使用某物。"},{"en":"A school can make reading attractive by offering books students actually enjoy.","zh":"學校可以透過提供學生真正喜歡的書，使閱讀具吸引力。"},{"en":"Tax support can make new farming methods attractive by reducing the financial risk.","zh":"稅務支援可以透過降低財務風險，使新耕作方法具吸引力。"},{"en":"The phrase is about encouraging adoption.","zh":"這個短語關於鼓勵採用。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":4},{"front":"make wholesale changes to","meaning":"對……作出全面改變","examples":[{"en":"Making wholesale changes to pest control is expensive.","zh":"對害蟲控制作出全面改變很昂貴。"},{"en":"To make wholesale changes to something means to change it completely or on a large scale.","zh":"「make wholesale changes to」某事，意思是完全或大規模改變它。"},{"en":"A company may make wholesale changes to its delivery system after repeated delays.","zh":"公司在多次延誤後，可能對配送系統作出全面改變。"},{"en":"Farmers may hesitate to make wholesale changes if new equipment costs too much.","zh":"如果新設備成本太高，農民可能猶豫是否作出全面改變。"},{"en":"The phrase suggests major change, not small adjustment.","zh":"這個短語暗示重大改變，而不是小調整。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":4},{"front":"control pests","meaning":"控制害蟲","examples":[{"en":"Farmers need practical ways to control pests on their farms.","zh":"農民需要實用方法來控制農場上的害蟲。"},{"en":"To control pests means to reduce harmful insects, weeds or animals that damage crops.","zh":"「control pests」意思是減少破壞作物的有害昆蟲、雜草或動物。"},{"en":"Gardeners can control pests by removing diseased leaves and protecting helpful insects.","zh":"園丁可以透過移除染病葉片和保護有益昆蟲來控制害蟲。"},{"en":"If farmers cannot control pests, crop quality and income may fall.","zh":"如果農民不能控制害蟲，作物質素和收入可能下降。"},{"en":"The phrase does not always mean killing every pest.","zh":"這個短語不一定表示殺死所有害蟲。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":5},{"front":"tax breaks","meaning":"稅務寬減","examples":[{"en":"Farmers say tax breaks would help them adopt new practices.","zh":"農民說稅務寬減會幫助他們採用新做法。"},{"en":"Tax breaks are reductions in tax that make costs lower for people or businesses.","zh":"「tax breaks」是降低個人或企業稅款的安排。"},{"en":"A government may offer tax breaks to encourage companies to use clean energy.","zh":"政府可能提供稅務寬減，以鼓勵公司使用清潔能源。"},{"en":"If farmers receive tax breaks, they may afford new equipment more easily.","zh":"如果農民獲得稅務寬減，他們可能更容易負擔新設備。"},{"en":"The phrase refers to financial support through the tax system.","zh":"這個短語指透過稅制提供的財務支援。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":5},{"front":"offset the expenditure","meaning":"抵銷開支","examples":[{"en":"Tax breaks could offset the expenditure of changing farming methods.","zh":"稅務寬減可以抵銷改變耕作方法的開支。"},{"en":"To offset the expenditure means to balance or reduce the money spent.","zh":"「offset the expenditure」意思是平衡或減少花費。"},{"en":"A travel allowance can offset the expenditure of commuting to work.","zh":"交通津貼可以抵銷上班通勤開支。"},{"en":"If government support offsets the expenditure, farmers may be more willing to change.","zh":"如果政府支援抵銷開支，農民可能更願意改變。"},{"en":"The phrase is about making costs easier to bear.","zh":"這個短語關於令成本較易承擔。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":5},{"front":"willingly adopt","meaning":"願意採用","examples":[{"en":"Farmers would willingly adopt new practices if costs were offset.","zh":"如果成本被抵銷，農民會願意採用新做法。"},{"en":"To willingly adopt something means to choose to use it without being forced.","zh":"「willingly adopt」某物，意思是在不被迫的情況下選擇使用它。"},{"en":"Students may willingly adopt a study plan if they can see quick improvement.","zh":"如果學生看到快速進步，他們可能願意採用學習計劃。"},{"en":"If new farming methods save money, growers may willingly adopt them.","zh":"如果新耕作方法省錢，種植者可能願意採用。"},{"en":"The phrase shows voluntary acceptance.","zh":"這個短語顯示自願接受。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":5},{"front":"new practices","meaning":"新做法","examples":[{"en":"Many farmers are interested in new practices that reduce pesticides.","zh":"許多農民對能減少農藥的新做法感興趣。"},{"en":"New practices are new ways of doing work or solving problems.","zh":"「new practices」是做事或解決問題的新方法。"},{"en":"A school may introduce new practices for checking homework online.","zh":"學校可能引入網上檢查功課的新做法。"},{"en":"New practices can spread when people see that they save time or money.","zh":"當人們看到新做法能節省時間或金錢，它們就可能傳播。"},{"en":"The phrase often refers to practical changes, not just new ideas.","zh":"這個短語常指實際改變，而不只是新想法。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":5},{"front":"go on to note that","meaning":"進一步指出","examples":[{"en":"The report goes on to note that pesticide use has changed nationally.","zh":"報告進一步指出，全國農藥使用情況已有改變。"},{"en":"To go on to note that means to continue by adding another point.","zh":"「go on to note that」意思是繼續補充另一點。"},{"en":"The teacher explained the rule and went on to note that there were exceptions.","zh":"老師解釋規則後，進一步指出有例外情況。"},{"en":"A report may go on to note a problem after first describing progress.","zh":"報告可能先描述進展，再進一步指出問題。"},{"en":"The phrase helps writers add further information.","zh":"這個短語幫助作者加入進一步資料。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":5},{"front":"riskiest pesticides","meaning":"風險最高的農藥","examples":[{"en":"The use of the riskiest pesticides has declined nationwide.","zh":"風險最高的農藥使用量已在全國下降。"},{"en":"The riskiest pesticides are the pesticides most likely to harm health or the environment.","zh":"「riskiest pesticides」是最可能傷害健康或環境的農藥。"},{"en":"Farmers may replace the riskiest pesticides with safer pest-control methods.","zh":"農民可能用更安全的害蟲控制方法取代風險最高的農藥。"},{"en":"Reducing the riskiest pesticides can lower danger even if total pesticide use remains high.","zh":"減少風險最高的農藥，即使總農藥使用量仍高，也可以降低危險。"},{"en":"The phrase compares pesticides by level of risk.","zh":"這個短語按風險水平比較農藥。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":5},{"front":"decline nationwide","meaning":"在全國下降","examples":[{"en":"The use of some risky pesticides has declined nationwide.","zh":"一些高風險農藥的使用量已在全國下降。"},{"en":"To decline nationwide means to decrease across the whole country.","zh":"「decline nationwide」意思是在整個國家範圍內下降。"},{"en":"Smoking rates may decline nationwide after strong public health campaigns.","zh":"強力公共健康宣傳後，吸煙率可能在全國下降。"},{"en":"If pesticide use declines nationwide, the change is broader than one state.","zh":"如果農藥使用量在全國下降，變化就不只限於一個州。"},{"en":"The phrase combines decrease with national scope.","zh":"這個短語結合下降和全國範圍。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":5},{"front":"make up more than","meaning":"佔超過……","examples":[{"en":"The riskiest pesticides still make up more than 40 percent of all pesticides.","zh":"風險最高的農藥仍佔所有農藥超過四成。"},{"en":"Make up more than means form a larger share than the amount stated.","zh":"「make up more than」意思是所佔比例大於所述數量。"},{"en":"Online orders may make up more than half of a shop’s sales.","zh":"網上訂單可能佔一間店銷售額超過一半。"},{"en":"If risky pesticides make up more than 40 percent, they remain a major part of pesticide use.","zh":"如果高風險農藥佔超過四成，它們仍是農藥使用中的主要部分。"},{"en":"The phrase describes proportion.","zh":"這個短語描述比例。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":5},{"front":"40 percent of","meaning":"……的40%","examples":[{"en":"Risky pesticides still make up over 40 percent of those used today.","zh":"高風險農藥仍佔今天使用農藥的40%以上。"},{"en":"40 percent of something means four out of every ten parts of it.","zh":"「40 percent of」某物，意思是每十份中有四份。"},{"en":"If 40 percent of students take the bus, transport planning must consider them.","zh":"如果40%的學生乘巴士，交通規劃必須考慮他們。"},{"en":"When 40 percent of a product group is risky, the problem is still large.","zh":"當一類產品中40%有風險，問題仍然很大。"},{"en":"The phrase gives a clear proportion.","zh":"這個短語提供清楚比例。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":5},{"front":"pesticide use","meaning":"農藥使用量","examples":[{"en":"National pesticide use has risen since 1992.","zh":"全國農藥使用量自1992年以來上升。"},{"en":"Pesticide use means the amount or practice of applying chemicals to control pests.","zh":"「pesticide use」指使用化學品控制害蟲的數量或做法。"},{"en":"A farm can reduce pesticide use by checking pest levels before spraying.","zh":"農場可以透過噴藥前檢查害蟲水平來減少農藥使用量。"},{"en":"High pesticide use may increase costs and environmental risks.","zh":"高農藥使用量可能增加成本和環境風險。"},{"en":"The phrase measures how much pest-control chemical is being used.","zh":"這個短語衡量害蟲控制化學品使用了多少。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":5},{"front":"rise by","meaning":"增加了……","examples":[{"en":"National pesticide use has risen by 40 million kilograms.","zh":"全國農藥使用量增加了四千萬公斤。"},{"en":"Rise by means increase by a particular amount.","zh":"「rise by」意思是增加某個數量。"},{"en":"A bus fare may rise by two dollars after a policy change.","zh":"政策改變後，巴士票價可能增加兩元。"},{"en":"If costs rise by a large amount, families may change their spending.","zh":"如果成本大幅增加，家庭可能改變開支。"},{"en":"The phrase tells us the size of an increase.","zh":"這個短語告訴我們增加幅度。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":6},{"front":"food supply","meaning":"食物供應","examples":[{"en":"Patrick Leahy says the food supply remains very safe.","zh":"Patrick Leahy 說食物供應仍然非常安全。"},{"en":"Food supply means the food available to a country, region or community.","zh":"「food supply」指一個國家、地區或社群可獲得的食物。"},{"en":"A strong food supply depends on farms, transport, storage and shops.","zh":"穩定食物供應依賴農場、運輸、儲存和商店。"},{"en":"If pests damage crops, the food supply may become smaller or more expensive.","zh":"如果害蟲破壞作物，食物供應可能變少或變貴。"},{"en":"The phrase refers to the system that provides food, not one meal.","zh":"這個短語指提供食物的系統，而不是一餐飯。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":6},{"front":"remain the safest and highest quality","meaning":"仍然是最安全及最高質素的","examples":[{"en":"He argues that the food supply remains the safest and highest quality on Earth.","zh":"他認為食物供應仍然是地球上最安全及最高質素的。"},{"en":"Remain the safest and highest quality means continue to be the best in safety and standard.","zh":"「remain the safest and highest quality」意思是在安全和標準上繼續保持最佳。"},{"en":"A hospital must work hard to remain the safest and highest quality care provider in its region.","zh":"醫院必須努力，才能仍然是區內最安全及最高質素的護理提供者。"},{"en":"If food remains safe and high quality, consumers may trust the system more.","zh":"如果食物仍然安全且高質素，消費者可能更信任該系統。"},{"en":"The phrase makes a strong positive claim.","zh":"這個短語作出強烈正面說法。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":6},{"front":"overdose farmland with","meaning":"對農地過量使用……","examples":[{"en":"The report criticises farmers for overdosing farmland with toxic pesticides.","zh":"報告批評農民對農地過量使用有毒農藥。"},{"en":"To overdose farmland with something means to apply too much of it to the land.","zh":"「overdose farmland with」某物，意思是在土地上施用過量的它。"},{"en":"A gardener can damage plants by overdosing soil with fertiliser.","zh":"園丁可能因對泥土過量使用肥料而傷害植物。"},{"en":"If farmers overdose farmland with pesticides, chemicals may harm soil, water and wildlife.","zh":"如果農民對農地過量使用農藥，化學品可能傷害土壤、水和野生動物。"},{"en":"The phrase is critical because it suggests excessive use.","zh":"這個短語帶批評意味，因為它暗示過度使用。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":6},{"front":"powerful and toxic pesticides","meaning":"強效而有毒的農藥","examples":[{"en":"Some farmland is treated with powerful and toxic pesticides.","zh":"一些農地使用強效而有毒的農藥處理。"},{"en":"Powerful and toxic pesticides are strong chemicals that kill pests but can also cause harm.","zh":"「powerful and toxic pesticides」是能殺害害蟲但也可能造成傷害的強力化學品。"},{"en":"Workers need masks and training when using powerful and toxic pesticides.","zh":"工人使用強效而有毒的農藥時需要口罩和訓練。"},{"en":"If powerful pesticides are overused, they may damage more than the target pests.","zh":"如果強效農藥被過度使用，它們可能傷害目標害蟲以外的生物。"},{"en":"The phrase stresses both effectiveness and danger.","zh":"這個短語同時強調效力和危險。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":6},{"front":"underuse safe alternatives","meaning":"未充分使用安全替代方案","examples":[{"en":"Farmers may underuse safe alternatives to toxic pesticides.","zh":"農民可能未充分使用有毒農藥的安全替代方案。"},{"en":"To underuse safe alternatives means to use safer options less than they could or should be used.","zh":"「underuse safe alternatives」意思是使用安全選項的程度低於可用或應用水平。"},{"en":"A school may underuse online tools if teachers are not trained.","zh":"如果老師沒有受訓，學校可能未充分使用網上工具。"},{"en":"If farmers underuse safe alternatives, chemical risks may remain high.","zh":"如果農民未充分使用安全替代方案，化學風險可能仍然高。"},{"en":"The phrase suggests a missed opportunity.","zh":"這個短語暗示錯失機會。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":6},{"front":"safe and effective alternatives","meaning":"安全而有效的替代方案","examples":[{"en":"Integrated methods can provide safe and effective alternatives.","zh":"綜合方法可以提供安全而有效的替代方案。"},{"en":"Safe and effective alternatives are options that work well while causing less harm.","zh":"「safe and effective alternatives」是既有效又造成較少傷害的選項。"},{"en":"A doctor may choose a safe and effective alternative if a medicine has strong side effects.","zh":"如果一種藥副作用強，醫生可能選擇安全而有效的替代方案。"},{"en":"If farmers find safe and effective alternatives, they may depend less on toxic pesticides.","zh":"如果農民找到安全而有效的替代方案，他們可能較少依賴有毒農藥。"},{"en":"The phrase balances safety with usefulness.","zh":"這個短語平衡安全和實用性。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":6},{"front":"commission the report","meaning":"委託撰寫報告","examples":[{"en":"Patrick Leahy commissioned the report on pesticide use.","zh":"Patrick Leahy 委託撰寫關於農藥使用的報告。"},{"en":"To commission a report means to officially ask someone to prepare it.","zh":"「commission the report」意思是正式要求某人準備報告。"},{"en":"A company may commission a report to study why sales are falling.","zh":"公司可能委託撰寫報告，以研究銷售額為何下降。"},{"en":"If a senator commissions a report, the findings may influence public policy.","zh":"如果參議員委託撰寫報告，調查結果可能影響公共政策。"},{"en":"The phrase shows that the report was formally requested.","zh":"這個短語顯示報告是被正式要求撰寫的。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":6},{"front":"green action groups","meaning":"環保行動團體","examples":[{"en":"Green action groups disagree about the safety issue.","zh":"環保行動團體對安全問題有不同意見。"},{"en":"Green action groups are organisations that campaign for environmental protection.","zh":"「green action groups」是為環境保護發起行動的組織。"},{"en":"Green action groups may ask farms to reduce chemicals and protect wildlife.","zh":"環保行動團體可能要求農場減少化學品並保護野生動物。"},{"en":"If green action groups raise concerns, companies may face pressure to change.","zh":"如果環保行動團體提出關注，公司可能面對改變壓力。"},{"en":"The phrase refers to environmental campaign organisations.","zh":"這個短語指環境運動組織。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":6},{"front":"safety issue","meaning":"安全問題","examples":[{"en":"Some lobbyists disagree about the food-safety issue.","zh":"一些游說人士對食物安全問題有不同意見。"},{"en":"A safety issue is a problem or concern about whether something may cause harm.","zh":"「safety issue」是關於某物是否可能造成傷害的問題或關注。"},{"en":"A broken lift is a safety issue because people could be injured.","zh":"壞掉的升降機是安全問題，因為人們可能受傷。"},{"en":"If pesticide residues remain on food, consumers may see it as a safety issue.","zh":"如果農藥殘留在食物上，消費者可能把它視為安全問題。"},{"en":"The phrase focuses on risk and protection.","zh":"這個短語集中於風險和保護。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":6},{"front":"habitual consumption","meaning":"習慣性食用","examples":[{"en":"Habitual consumption of chemically grown food may worry consumers.","zh":"習慣性食用以化學品種植的食物可能令消費者擔心。"},{"en":"Habitual consumption means regularly eating or using something as a habit.","zh":"「habitual consumption」意思是作為習慣定期食用或使用某物。"},{"en":"Habitual consumption of sugary drinks can affect health over time.","zh":"習慣性飲用含糖飲品可能隨時間影響健康。"},{"en":"If people habitually consume food with chemical residues, critics may worry about long-term effects.","zh":"如果人們習慣性食用有化學殘留的食物，批評者可能擔心長期影響。"},{"en":"The phrase stresses repeated behaviour, not one-time use.","zh":"這個短語強調重複行為，而不是一次性使用。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":6},{"front":"foodstuffs","meaning":"食品","examples":[{"en":"Some foodstuffs are grown using toxic chemicals.","zh":"一些食品是使用有毒化學品種植的。"},{"en":"Foodstuffs are foods or food materials that people eat or use in cooking.","zh":"「foodstuffs」是人們食用或烹調時使用的食物或食物材料。"},{"en":"Rice, fruit, flour and oil are common foodstuffs in many homes.","zh":"米、水果、麵粉和油是許多家庭常見食品。"},{"en":"If foodstuffs contain harmful residues, consumers may lose confidence.","zh":"如果食品含有有害殘留，消費者可能失去信心。"},{"en":"The word is more formal than food.","zh":"這個詞比 food 更正式。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":7},{"front":"toxic chemicals","meaning":"有毒化學品","examples":[{"en":"Food grown using toxic chemicals may be unsafe.","zh":"使用有毒化學品種植的食物可能不安全。"},{"en":"Toxic chemicals are substances that can harm living things.","zh":"「toxic chemicals」是可以傷害生物的物質。"},{"en":"Cleaners containing toxic chemicals should be kept away from children.","zh":"含有有毒化學品的清潔劑應遠離兒童。"},{"en":"If toxic chemicals enter soil or water, they can affect plants, animals and people.","zh":"如果有毒化學品進入土壤或水，它們可以影響植物、動物和人類。"},{"en":"The phrase highlights chemical danger.","zh":"這個短語強調化學危險。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":7},{"front":"of the kind found on","meaning":"屬於在……可見的那類","examples":[{"en":"Some toxic chemicals are of the kind found on today’s farms.","zh":"一些有毒化學品屬於今天農場上可見的那類。"},{"en":"Of the kind found on means belonging to the type commonly seen in a particular place.","zh":"「of the kind found on」意思是屬於某地常見的那一類。"},{"en":"The tools were of the kind found in many school science labs.","zh":"這些工具屬於許多學校科學實驗室可見的那類。"},{"en":"If chemicals are of the kind found on farms, they are not imaginary but used in real agriculture.","zh":"如果化學品屬於農場上可見的那類，它們就不是想像出來的，而是真實農業中使用的。"},{"en":"The phrase identifies a type by where it is found.","zh":"這個短語透過出現地點指出類型。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":7},{"front":"be healthy for consumers","meaning":"對消費者健康","examples":[{"en":"Some critics doubt that such food can be healthy for consumers.","zh":"一些批評者懷疑這類食物是否對消費者健康。"},{"en":"To be healthy for consumers means to be safe and good for people who eat or use it.","zh":"「be healthy for consumers」意思是對食用或使用它的人安全且有益健康。"},{"en":"Food with too much salt may not be healthy for consumers who have high blood pressure.","zh":"含鹽太多的食物可能不利於高血壓消費者健康。"},{"en":"If crops contain harmful chemicals, critics may question whether they are healthy for consumers.","zh":"如果作物含有有害化學品，批評者可能質疑它們是否對消費者健康。"},{"en":"The phrase focuses on the effect on people buying and eating food.","zh":"這個短語集中於對購買和食用食物的人造成的影響。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":7},{"front":"spokesman for","meaning":"……的發言人","examples":[{"en":"Bill Bowler is a spokesman for Green Action.","zh":"Bill Bowler 是 Green Action 的發言人。"},{"en":"A spokesman for a group is a person who speaks publicly on its behalf.","zh":"「spokesman for」某團體，是代表該團體公開發言的人。"},{"en":"A company spokesman may explain a product recall to the media.","zh":"公司發言人可能向媒體解釋產品回收。"},{"en":"If a spokesman speaks clearly, the public can understand the group’s position.","zh":"如果發言人說得清楚，公眾可以理解該團體的立場。"},{"en":"The phrase identifies the person representing an organisation.","zh":"這個短語指出代表某組織的人。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":7},{"front":"lobbyists interested in","meaning":"關注……的游說人士","examples":[{"en":"Many lobbyists are interested in the pesticide issue.","zh":"許多游說人士關注農藥問題。"},{"en":"Lobbyists interested in an issue are people who try to influence decisions about that issue.","zh":"「lobbyists interested in」某議題，是試圖影響該議題決策的人。"},{"en":"Lobbyists interested in transport may speak to officials about railway funding.","zh":"關注交通的游說人士可能與官員討論鐵路資助。"},{"en":"If lobbyists are interested in pesticide rules, political debate may become stronger.","zh":"如果游說人士關注農藥規則，政治辯論可能變得更強烈。"},{"en":"The phrase links political influence with a specific topic.","zh":"這個短語把政治影響與特定主題連繫起來。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":7},{"front":"single out","meaning":"特別指出","examples":[{"en":"The GAO report singles out Oregon’s apple and pear producers.","zh":"GAO 報告特別指出俄勒岡州的蘋果和梨生產者。"},{"en":"To single out someone means to choose them for special attention or mention.","zh":"「single out」某人，意思是特別選出他們加以注意或提及。"},{"en":"A teacher may single out one essay because it shows excellent structure.","zh":"老師可能特別指出一篇作文，因為它結構出色。"},{"en":"If a report singles out Oregon farmers, it treats them as especially important examples.","zh":"如果報告特別指出俄勒岡州農民，它把他們視為特別重要的例子。"},{"en":"The phrase can be positive or critical depending on context.","zh":"這個短語可正面或批判，視乎語境。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":7},{"front":"apple and pear producers","meaning":"蘋果和梨生產者","examples":[{"en":"Oregon’s apple and pear producers have used IPM techniques successfully.","zh":"俄勒岡州的蘋果和梨生產者已成功使用 IPM 技術。"},{"en":"Apple and pear producers are growers who farm apples and pears for sale.","zh":"「apple and pear producers」是種植蘋果和梨作銷售的種植者。"},{"en":"Apple and pear producers must protect fruit from insects while keeping it attractive to buyers.","zh":"蘋果和梨生產者必須保護水果免受昆蟲侵害，同時保持吸引買家的外觀。"},{"en":"If these producers reduce pesticides, they can improve environmental performance without losing quality.","zh":"如果這些生產者減少農藥，他們可以改善環境表現而不失去質素。"},{"en":"The phrase names a specific fruit-growing sector.","zh":"這個短語指出特定水果種植部門。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":7},{"front":"with growing success","meaning":"越來越成功","examples":[{"en":"Some Oregon producers have used IPM techniques with growing success.","zh":"一些俄勒岡州生產者越來越成功地使用 IPM 技術。"},{"en":"With growing success means with results that are becoming better over time.","zh":"「with growing success」意思是成果隨時間變得更好。"},{"en":"A new reading programme may be used with growing success as teachers improve it.","zh":"隨着老師改進，新閱讀計劃可能越來越成功地被使用。"},{"en":"If farmers use a method with growing success, more growers may copy it.","zh":"如果農民越來越成功地使用某方法，更多種植者可能仿效。"},{"en":"The phrase suggests steady improvement.","zh":"這個短語暗示穩定改善。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":7},{"front":"clearly ahead of","meaning":"明顯領先於……","examples":[{"en":"Oregon is clearly ahead of the nation in some IPM practices.","zh":"俄勒岡州在一些 IPM 做法上明顯領先於全國。"},{"en":"Clearly ahead of means obviously more advanced or successful than others.","zh":"「clearly ahead of」意思是明顯比其他人更先進或更成功。"},{"en":"A school may be clearly ahead of others in using digital learning tools.","zh":"一所學校在使用數碼學習工具方面可能明顯領先其他學校。"},{"en":"If one state is clearly ahead, its methods may become models for other regions.","zh":"如果一個州明顯領先，它的方法可能成為其他地區的榜樣。"},{"en":"The phrase expresses a strong comparison.","zh":"這個短語表達強烈比較。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":7},{"front":"take criticisms seriously","meaning":"認真看待批評","examples":[{"en":"OSU scientists are taking the GAO’s criticisms seriously.","zh":"俄勒岡州立大學科學家正在認真看待 GAO 的批評。"},{"en":"To take criticisms seriously means to listen to negative comments and respond thoughtfully.","zh":"「take criticisms seriously」意思是聆聽負面意見並認真回應。"},{"en":"A student who takes criticism seriously can improve the next essay.","zh":"認真看待批評的學生可以改善下一篇作文。"},{"en":"If researchers take criticisms seriously, they may adjust their work instead of ignoring problems.","zh":"如果研究人員認真看待批評，他們可能調整工作而不是忽視問題。"},{"en":"The phrase shows responsibility and willingness to improve.","zh":"這個短語顯示責任感和改善意願。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":7},{"front":"continue to develop","meaning":"繼續發展","examples":[{"en":"Researchers must continue to develop alternative practices.","zh":"研究人員必須繼續發展替代做法。"},{"en":"To continue to develop something means to keep improving or creating it over time.","zh":"「continue to develop」某物，意思是隨時間繼續改進或創造它。"},{"en":"A teacher may continue to develop lesson materials after seeing students’ mistakes.","zh":"老師可能在看到學生錯誤後繼續發展教材。"},{"en":"If farming problems change, scientists must continue to develop better methods.","zh":"如果農業問題改變，科學家必須繼續發展更好方法。"},{"en":"The phrase shows that the work is not finished.","zh":"這個短語顯示工作尚未完成。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":8},{"front":"effective alternative practices","meaning":"有效的替代做法","examples":[{"en":"Scientists are developing effective alternative practices.","zh":"科學家正在發展有效的替代做法。"},{"en":"Effective alternative practices are different methods that actually work well.","zh":"「effective alternative practices」是實際有效的不同方法。"},{"en":"A school may need effective alternative practices when old discipline methods fail.","zh":"當舊紀律方法失效時，學校可能需要有效的替代做法。"},{"en":"If farmers find effective alternatives, they can reduce harmful chemical use.","zh":"如果農民找到有效替代做法，他們可以減少有害化學品使用。"},{"en":"The phrase stresses both difference and usefulness.","zh":"這個短語同時強調不同和有用。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":8},{"front":"reduce environmental hazards","meaning":"減少環境危害","examples":[{"en":"Alternative practices can reduce environmental hazards.","zh":"替代做法可以減少環境危害。"},{"en":"To reduce environmental hazards means to lower dangers to air, water, soil, wildlife or people.","zh":"「reduce environmental hazards」意思是降低對空氣、水、土壤、野生動物或人類的危險。"},{"en":"Recycling batteries properly can reduce environmental hazards from toxic metals.","zh":"妥善回收電池可以減少有毒金屬造成的環境危害。"},{"en":"If farms reduce chemical runoff, they reduce environmental hazards for rivers.","zh":"如果農場減少化學徑流，它們就減少河流的環境危害。"},{"en":"The phrase focuses on making nature and communities safer.","zh":"這個短語集中於使自然和社區更安全。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":8},{"front":"environmental hazards","meaning":"環境危害","examples":[{"en":"Pesticide use can create environmental hazards.","zh":"農藥使用可以造成環境危害。"},{"en":"Environmental hazards are dangers that can harm nature or human surroundings.","zh":"「environmental hazards」是可以傷害自然或人類周圍環境的危險。"},{"en":"Oil spills, polluted rivers and toxic waste are environmental hazards.","zh":"漏油、受污染河流和有毒廢物都是環境危害。"},{"en":"Environmental hazards can damage health, farming and wildlife habitats.","zh":"環境危害可以損害健康、農業和野生動物棲息地。"},{"en":"The phrase refers to risk in the natural or built environment.","zh":"這個短語指自然或建成環境中的風險。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":8},{"front":"high-quality products","meaning":"高質素產品","examples":[{"en":"Farmers need methods that still produce high-quality products.","zh":"農民需要仍能生產高質素產品的方法。"},{"en":"High-quality products are goods that meet strong standards for performance, appearance or taste.","zh":"「high-quality products」是符合高性能、外觀或味道標準的貨品。"},{"en":"A bakery gains loyal customers by selling high-quality products every day.","zh":"麵包店透過每天售賣高質素產品來獲得忠實顧客。"},{"en":"If safer farming methods still produce high-quality products, growers can protect both business and environment.","zh":"如果較安全的耕作方法仍能生產高質素產品，種植者便能保護生意和環境。"},{"en":"The phrase emphasises quality, not simply output.","zh":"這個短語強調質素，而不只是產量。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":8},{"front":"professor of entomology","meaning":"昆蟲學教授","examples":[{"en":"Paul Jepson is a professor of entomology at OSU.","zh":"Paul Jepson 是俄勒岡州立大學的昆蟲學教授。"},{"en":"A professor of entomology teaches and researches insects.","zh":"「professor of entomology」是教授和研究昆蟲的人。"},{"en":"A professor of entomology may help farmers understand which insects damage crops and which ones help.","zh":"昆蟲學教授可能幫助農民理解哪些昆蟲破壞作物，哪些昆蟲有益。"},{"en":"Because pest control often involves insects, entomology is important in agriculture.","zh":"因為害蟲控制常涉及昆蟲，昆蟲學在農業中很重要。"},{"en":"The title shows specialist knowledge about insect-related problems.","zh":"這個職銜顯示關於昆蟲問題的專門知識。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":8},{"front":"entomology","meaning":"昆蟲學","examples":[{"en":"Entomology is important in research on pest control.","zh":"昆蟲學在害蟲控制研究中很重要。"},{"en":"Entomology is the scientific study of insects.","zh":"「entomology」是研究昆蟲的科學。"},{"en":"Students studying entomology may learn about beetles, flies, moths and bees.","zh":"學習昆蟲學的學生可能研究甲蟲、蒼蠅、蛾和蜜蜂。"},{"en":"Entomology helps farmers separate harmful pests from beneficial insects.","zh":"昆蟲學幫助農民區分有害害蟲和有益昆蟲。"},{"en":"The word names a branch of biology.","zh":"這個詞指出生物學的一個分支。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":8},{"front":"director of","meaning":"……的主任","examples":[{"en":"Paul Jepson is the director of OSU’s Integrated Plant Protection Centre.","zh":"Paul Jepson 是俄勒岡州立大學綜合植物保護中心的主任。"},{"en":"Director of an organisation means the person who leads or manages it.","zh":"「director of」某組織，意思是領導或管理該組織的人。"},{"en":"The director of a hospital department decides priorities and coordinates staff.","zh":"醫院部門主任決定優先事項並協調員工。"},{"en":"If someone is director of a research centre, they help guide its work and goals.","zh":"如果某人是研究中心主任，他會幫助指導其工作和目標。"},{"en":"The phrase identifies a leadership role.","zh":"這個短語指出領導角色。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":8},{"front":"Integrated Plant Protection Centre","meaning":"綜合植物保護中心","examples":[{"en":"The Integrated Plant Protection Centre coordinates research on safer farming.","zh":"綜合植物保護中心協調關於更安全農業的研究。"},{"en":"The Integrated Plant Protection Centre is a research centre focused on protecting crops through combined methods.","zh":"「Integrated Plant Protection Centre」是一個專注於透過綜合方法保護作物的研究中心。"},{"en":"Such a centre may bring together scientists who study insects, soil, crops and chemicals.","zh":"這類中心可能集合研究昆蟲、土壤、作物和化學品的科學家。"},{"en":"If the Centre links research with farms, new methods can be tested in real fields.","zh":"如果中心把研究與農場連繫起來，新方法就可在真實田地中測試。"},{"en":"The phrase names the organisation supporting integrated plant protection.","zh":"這個短語指出支援綜合植物保護的組織。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":8},{"front":"bring together","meaning":"匯聚；集合","examples":[{"en":"The IPPC brings together scientists and farmers.","zh":"IPPC 匯聚科學家和農民。"},{"en":"To bring together people means to gather them so they can cooperate or share ideas.","zh":"「bring together」人們，意思是集合他們，使他們能合作或分享想法。"},{"en":"A community meeting can bring together parents, teachers and local officials.","zh":"社區會議可以集合家長、老師和本地官員。"},{"en":"If a project brings together experts and users, the solution may be more practical.","zh":"如果項目匯聚專家和使用者，解決方案可能更實際。"},{"en":"The phrase highlights cooperation across groups.","zh":"這個短語強調跨群體合作。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":8},{"front":"Agricultural Experiment Station","meaning":"農業實驗站","examples":[{"en":"OSU’s Agricultural Experiment Station works with farmers on new methods.","zh":"俄勒岡州立大學農業實驗站與農民合作研究新方法。"},{"en":"An Agricultural Experiment Station is a place where farming methods are tested through research.","zh":"「Agricultural Experiment Station」是透過研究測試耕作方法的地方。"},{"en":"Farmers may use results from an experiment station before changing their own fields.","zh":"農民在改變自己田地前，可能使用實驗站的結果。"},{"en":"If an experiment station studies irrigation, it can help farms save water.","zh":"如果實驗站研究灌溉，它可以幫助農場節省用水。"},{"en":"The phrase names a research unit for practical agriculture.","zh":"這個短語指出實用農業的研究單位。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":8},{"front":"Extension Service","meaning":"推廣服務","examples":[{"en":"The OSU Extension Service helps connect research with farming practice.","zh":"俄勒岡州立大學推廣服務幫助把研究與農業實踐連接起來。"},{"en":"An Extension Service shares university research with farmers and communities.","zh":"「Extension Service」把大學研究分享給農民和社區。"},{"en":"Extension workers may visit farms, give workshops and answer practical questions.","zh":"推廣服務人員可能探訪農場、舉辦工作坊並回答實際問題。"},{"en":"If an Extension Service communicates well, research is more likely to be used.","zh":"如果推廣服務溝通良好，研究更可能被使用。"},{"en":"The phrase refers to the bridge between science and practice.","zh":"這個短語指科學與實踐之間的橋樑。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":9},{"front":"U.S. Department of Agriculture","meaning":"美國農業部","examples":[{"en":"The U.S. Department of Agriculture is involved in the IPPC’s work.","zh":"美國農業部參與 IPPC 的工作。"},{"en":"The U.S. Department of Agriculture is the federal department concerned with farming, food and rural issues.","zh":"「U.S. Department of Agriculture」是關注農業、食物和鄉郊議題的聯邦部門。"},{"en":"Farmers may receive information or support from the U.S. Department of Agriculture.","zh":"農民可能從美國農業部獲得資訊或支援。"},{"en":"If the department supports safer farming, growers may have more resources to change.","zh":"如果該部門支援更安全農業，種植者可能有更多資源去改變。"},{"en":"The phrase identifies a national agricultural agency.","zh":"這個短語指出國家農業機構。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":9},{"front":"agricultural systems","meaning":"農業系統","examples":[{"en":"The Centre helps develop agricultural systems that save water and soil.","zh":"該中心幫助發展節省用水並保護土壤的農業系統。"},{"en":"Agricultural systems are organised ways of growing crops or raising animals.","zh":"「agricultural systems」是種植作物或飼養動物的有組織方式。"},{"en":"An agricultural system may include irrigation, soil care, pest control and harvesting methods.","zh":"農業系統可能包括灌溉、土壤保護、害蟲控制和收割方法。"},{"en":"If an agricultural system saves resources, farms can become more sustainable.","zh":"如果農業系統節省資源，農場可以變得更可持續。"},{"en":"The phrase looks at farming as a whole system, not one tool.","zh":"這個短語把農業看成整個系統，而不是單一工具。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":9},{"front":"save water and soil","meaning":"節省用水並保護土壤","examples":[{"en":"Researchers develop systems that save water and soil.","zh":"研究人員發展節省用水並保護土壤的系統。"},{"en":"To save water and soil means to reduce water waste and protect soil from erosion or damage.","zh":"「save water and soil」意思是減少水浪費，並保護土壤免受侵蝕或損害。"},{"en":"Drip irrigation and mulch can help farms save water and soil.","zh":"滴灌和覆蓋物可以幫助農場節省用水並保護土壤。"},{"en":"If farms save water and soil, they protect two key resources for future crops.","zh":"如果農場節省用水並保護土壤，它們就保護未來作物所需的兩項關鍵資源。"},{"en":"The phrase connects environmental protection with farming productivity.","zh":"這個短語把環境保護與農業產量連繫起來。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":9},{"front":"in response to","meaning":"回應……","examples":[{"en":"In response to the GAO report, the Centre is changing its emphasis.","zh":"回應 GAO 報告，該中心正在改變其重點。"},{"en":"In response to something means as a reaction to it.","zh":"「in response to」某事，意思是作為對它的反應。"},{"en":"A school may change its rules in response to parents’ complaints.","zh":"學校可能回應家長投訴而改變規則。"},{"en":"If a report criticises weak communication, an organisation may respond by improving outreach.","zh":"如果報告批評溝通薄弱，組織可能透過改善外展來回應。"},{"en":"The phrase explains why an action happens.","zh":"這個短語解釋行動為何發生。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":9},{"front":"put more emphasis on","meaning":"更加重視……","examples":[{"en":"The Centre is putting more emphasis on integrating research and farming practices.","zh":"該中心更加重視整合研究與農業實踐。"},{"en":"To put more emphasis on something means to give it greater attention or importance.","zh":"「put more emphasis on」某事，意思是給予它更多注意或重要性。"},{"en":"A teacher may put more emphasis on speaking practice before an oral exam.","zh":"老師可能在口試前更加重視口語練習。"},{"en":"If researchers put more emphasis on communication, farmers may understand new methods better.","zh":"如果研究人員更加重視溝通，農民可能更好理解新方法。"},{"en":"The phrase shows a shift in priority.","zh":"這個短語顯示優先事項轉變。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":9},{"front":"integrate research and farming practices","meaning":"整合研究與農業實踐","examples":[{"en":"The Centre aims to integrate research and farming practices.","zh":"該中心旨在整合研究與農業實踐。"},{"en":"To integrate research and farming practices means to connect scientific findings with real farm work.","zh":"「integrate research and farming practices」意思是把科學發現與真實農場工作連接起來。"},{"en":"A university can integrate research and practice by testing ideas on local farms.","zh":"大學可以透過在本地農場測試想法來整合研究與實踐。"},{"en":"If research is integrated with farming, useful discoveries are more likely to be adopted.","zh":"如果研究與農業整合，有用發現更可能被採用。"},{"en":"The phrase means combining knowledge with action.","zh":"這個短語意思是把知識與行動結合。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":9},{"front":"environmentally and economically","meaning":"在環境和經濟方面","examples":[{"en":"The Centre wants to improve Oregon agriculture environmentally and economically.","zh":"該中心希望在環境和經濟方面改善俄勒岡州農業。"},{"en":"Environmentally and economically means in terms of nature and money.","zh":"「environmentally and economically」意思是從自然環境和金錢角度來看。"},{"en":"A new transport plan should work environmentally and economically if it reduces pollution and stays affordable.","zh":"如果新交通計劃減少污染又保持負擔得起，它就在環境和經濟方面都可行。"},{"en":"Farming methods must make sense environmentally and economically to last.","zh":"耕作方法必須在環境和經濟方面合理，才能長久維持。"},{"en":"The phrase checks both ecological and financial effects.","zh":"這個短語檢視生態和財務兩方面影響。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":9},{"front":"criticize agencies for","meaning":"批評機構……","examples":[{"en":"The GAO report criticizes agencies for poor communication of IPM goals.","zh":"GAO 報告批評機構未能良好傳達 IPM 目標。"},{"en":"To criticize agencies for something means to blame official organisations for a problem.","zh":"「criticize agencies for」某事，意思是因某問題責備官方機構。"},{"en":"Residents may criticize agencies for slow repairs after a storm.","zh":"居民可能批評機構在風暴後維修緩慢。"},{"en":"If agencies fail to explain new policies, reports may criticize them for weak communication.","zh":"如果機構未能解釋新政策，報告可能批評它們溝通薄弱。"},{"en":"The phrase identifies both the target and reason for criticism.","zh":"這個短語指出批評對象和原因。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":9},{"front":"communicate the goals of","meaning":"清楚傳達……的目標","examples":[{"en":"Agencies must clearly communicate the goals of IPM.","zh":"機構必須清楚傳達 IPM 的目標。"},{"en":"To communicate the goals of something means to explain its aims clearly to others.","zh":"「communicate the goals of」某事，意思是向他人清楚解釋其目的。"},{"en":"A manager must communicate the goals of a project before asking staff to start.","zh":"經理在要求員工開始前，必須清楚傳達項目的目標。"},{"en":"If researchers communicate goals clearly, farmers can understand why a change matters.","zh":"如果研究人員清楚傳達目標，農民就能理解改變為何重要。"},{"en":"The phrase focuses on making purpose understood.","zh":"這個短語集中於讓目的被理解。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":9},{"front":"our challenge is to","meaning":"我們的挑戰是……","examples":[{"en":"Jepson says their challenge is to improve communication with growers.","zh":"Jepson 說他們的挑戰是改善與種植者的溝通。"},{"en":"Our challenge is to means the difficult task we must deal with is to do something.","zh":"「our challenge is to」意思是我們必須處理的困難任務是做某事。"},{"en":"Our challenge is to help students practise daily without making them feel overwhelmed.","zh":"我們的挑戰是幫助學生每日練習，而不令他們感到不知所措。"},{"en":"If new research is hard to understand, the challenge is to explain it clearly.","zh":"如果新研究難以理解，挑戰就是把它解釋清楚。"},{"en":"The phrase introduces the main problem to solve.","zh":"這個短語引出要解決的主要問題。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":9},{"front":"improve communication with","meaning":"改善與……的溝通","examples":[{"en":"Researchers must improve communication with growers.","zh":"研究人員必須改善與種植者的溝通。"},{"en":"To improve communication with someone means to share information more clearly and effectively with them.","zh":"「improve communication with」某人，意思是更清楚有效地與他們分享資訊。"},{"en":"A school can improve communication with parents by sending clear weekly updates.","zh":"學校可以透過發出清楚每週更新來改善與家長的溝通。"},{"en":"If researchers improve communication with farmers, good methods may be adopted faster.","zh":"如果研究人員改善與農民的溝通，好方法可能更快被採用。"},{"en":"The phrase is about better understanding between groups.","zh":"這個短語關於群體之間更好理解。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":10},{"front":"growers","meaning":"種植者","examples":[{"en":"Researchers need to learn what works for growers.","zh":"研究人員需要了解甚麼對種植者可行。"},{"en":"Growers are people or businesses that grow crops.","zh":"「growers」是種植作物的人或企業。"},{"en":"Growers may choose methods based on cost, weather, soil and market demand.","zh":"種植者可能根據成本、天氣、土壤和市場需求選擇方法。"},{"en":"If a method does not work for growers, it will not spread widely.","zh":"如果某方法對種植者不可行，它就不會廣泛傳播。"},{"en":"The word is often used for farmers who produce specific crops.","zh":"這個詞常用於生產特定作物的農民。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":10},{"front":"what works and what doesn’t","meaning":"甚麼可行、甚麼不可行","examples":[{"en":"Researchers need to learn what works and what doesn’t.","zh":"研究人員需要了解甚麼可行、甚麼不可行。"},{"en":"What works and what doesn’t means which methods succeed and which fail.","zh":"「what works and what doesn’t」意思是哪些方法成功、哪些方法失敗。"},{"en":"A teacher tests different activities to see what works and what doesn’t for students.","zh":"老師測試不同活動，以了解甚麼對學生可行、甚麼不可行。"},{"en":"If farmers share what works and what doesn’t, researchers can improve their advice.","zh":"如果農民分享甚麼可行、甚麼不可行，研究人員就能改善建議。"},{"en":"The phrase is practical and results-focused.","zh":"這個短語實用且重視結果。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":10},{"front":"work coming from","meaning":"由……產出的研究工作","examples":[{"en":"The work coming from OSU researchers must be adopted in the field.","zh":"由俄勒岡州立大學研究人員產出的研究工作必須在實地被採用。"},{"en":"Work coming from someone means research, ideas or results produced by that person or group.","zh":"「work coming from」某人，指由該人或團隊產出的研究、想法或成果。"},{"en":"The work coming from a hospital team may change how patients are treated.","zh":"由醫院團隊產出的研究工作可能改變病人治療方式。"},{"en":"If the work coming from scientists is not shared clearly, it may not help farmers.","zh":"如果由科學家產出的研究工作沒有清楚分享，它可能幫不到農民。"},{"en":"The phrase points to the source of the work.","zh":"這個短語指出工作的來源。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":10},{"front":"be adopted in the field","meaning":"在實地被採用","examples":[{"en":"Research findings must be adopted in the field.","zh":"研究結果必須在實地被採用。"},{"en":"To be adopted in the field means to be used in real working conditions, not only in research.","zh":"「be adopted in the field」意思是在真實工作環境中被使用，而不只是停留在研究中。"},{"en":"A teaching method is adopted in the field when real schools start using it.","zh":"當真實學校開始使用某教學方法，它就是在實地被採用。"},{"en":"If a farming technique is adopted in the field, growers actually apply it on farms.","zh":"如果耕作技術在實地被採用，種植者就真的在農場上應用它。"},{"en":"The phrase contrasts practice with theory.","zh":"這個短語把實踐與理論作對比。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":10},{"front":"languish in scientific journals","meaning":"被埋沒在科學期刊中","examples":[{"en":"Useful research should not simply languish in scientific journals.","zh":"有用研究不應只是被埋沒在科學期刊中。"},{"en":"To languish in scientific journals means to remain unread or unused in academic publications.","zh":"「languish in scientific journals」意思是留在學術刊物中，無人閱讀或未被使用。"},{"en":"A good teaching idea should not languish in a report if schools could use it.","zh":"如果學校可以使用一個好教學想法，它不應被埋沒在報告中。"},{"en":"If farm research languishes in journals, growers may never benefit from it.","zh":"如果農業研究被埋沒在期刊中，種植者可能永遠不能受益。"},{"en":"The phrase criticises useful knowledge that fails to reach practice.","zh":"這個短語批評有用知識未能進入實踐。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":10},{"front":"scientific journals","meaning":"科學期刊","examples":[{"en":"Research should lead to practice, not stay only in scientific journals.","zh":"研究應導向實踐，而不是只留在科學期刊中。"},{"en":"Scientific journals are publications where researchers share studies and findings.","zh":"「scientific journals」是研究人員分享研究和發現的刊物。"},{"en":"Scientists read scientific journals to learn what other researchers have discovered.","zh":"科學家閱讀科學期刊，以了解其他研究人員發現了什麼。"},{"en":"If research stays only in scientific journals, ordinary users may never see it.","zh":"如果研究只留在科學期刊中，普通使用者可能永遠看不到它。"},{"en":"The phrase refers to formal academic publications.","zh":"這個短語指正式學術刊物。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":10},{"front":"work together to","meaning":"合作去……","examples":[{"en":"Growers and scientists are working together to implement new practices.","zh":"種植者和科學家正在合作去實施新做法。"},{"en":"To work together to do something means to cooperate in order to achieve it.","zh":"「work together to」做某事，意思是合作以達成它。"},{"en":"Parents and teachers can work together to help a child improve reading.","zh":"家長和老師可以合作去幫助孩子改善閱讀。"},{"en":"If farmers and scientists work together, solutions can be both practical and evidence-based.","zh":"如果農民和科學家合作，解決方案可以既實際又有證據支持。"},{"en":"The phrase highlights shared effort toward one goal.","zh":"這個短語強調為同一目標共同努力。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":10},{"front":"implement new practices","meaning":"實施新做法","examples":[{"en":"Oregon growers and scientists implement new practices together.","zh":"俄勒岡州種植者和科學家一起實施新做法。"},{"en":"To implement new practices means to put new methods into real use.","zh":"「implement new practices」意思是把新方法實際使用起來。"},{"en":"A school may implement new practices for checking attendance online.","zh":"學校可能實施網上點名的新做法。"},{"en":"If growers implement new practices carefully, they can test whether results improve.","zh":"如果種植者仔細實施新做法，他們可以測試結果是否改善。"},{"en":"The phrase is about action, not just planning.","zh":"這個短語關於行動，而不只是計劃。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":10},{"front":"Malheur Experiment Station","meaning":"Malheur 實驗站","examples":[{"en":"Scientists at OSU’s Malheur Experiment Station tested drip irrigation.","zh":"俄勒岡州立大學 Malheur 實驗站的科學家測試了滴灌。"},{"en":"Malheur Experiment Station is a research station where agricultural methods are tested.","zh":"「Malheur Experiment Station」是一個測試農業方法的研究站。"},{"en":"Farmers may use results from Malheur Experiment Station to decide whether to change irrigation.","zh":"農民可能使用 Malheur 實驗站的結果來決定是否改變灌溉方式。"},{"en":"If a local experiment station tests a method, results may fit local soil and weather better.","zh":"如果本地實驗站測試某方法，結果可能更符合本地土壤和天氣。"},{"en":"The phrase names the research site for the onion example.","zh":"這個短語指出洋蔥例子的研究地點。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":10},{"front":"begin testing","meaning":"開始測試","examples":[{"en":"Scientists began testing a new drip irrigation system.","zh":"科學家開始測試新的滴灌系統。"},{"en":"To begin testing something means to start trying it and checking the results.","zh":"「begin testing」某物，意思是開始試用它並檢查結果。"},{"en":"A school may begin testing a new timetable before using it permanently.","zh":"學校可能在永久使用前開始測試新時間表。"},{"en":"If farmers begin testing a new system on a small area, they can reduce risk.","zh":"如果農民在小範圍開始測試新系統，他們可以降低風險。"},{"en":"The phrase marks the start of experimentation.","zh":"這個短語標誌實驗的開始。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":10},{"front":"drip irrigation system","meaning":"滴灌系統","examples":[{"en":"A new drip irrigation system replaced old ditches.","zh":"新的滴灌系統取代了舊溝渠。"},{"en":"A drip irrigation system delivers water slowly and directly to plant roots.","zh":"「drip irrigation system」把水緩慢而直接地送到植物根部。"},{"en":"Gardeners may use a drip irrigation system to water vegetables without wasting water.","zh":"園丁可能使用滴灌系統為蔬菜澆水，而不浪費水。"},{"en":"If water reaches roots directly, a drip irrigation system can reduce evaporation and runoff.","zh":"如果水直接到達根部，滴灌系統可以減少蒸發和徑流。"},{"en":"The phrase names a water-saving farming technology.","zh":"這個短語指出一種節水農業技術。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":11},{"front":"replace old ditches","meaning":"取代舊溝渠","examples":[{"en":"The new irrigation system replaced old ditches.","zh":"新灌溉系統取代了舊溝渠。"},{"en":"To replace old ditches means to stop using older water channels and use another system instead.","zh":"「replace old ditches」意思是不再使用舊水渠，而改用另一系統。"},{"en":"A farm may replace old pipes if they leak too much water.","zh":"如果舊水管漏水太多，農場可能更換它們。"},{"en":"Replacing old ditches can reduce water loss and soil movement.","zh":"取代舊溝渠可以減少水分流失和泥土移動。"},{"en":"The phrase shows a change from an old method to a new one.","zh":"這個短語顯示從舊方法轉向新方法。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":11},{"front":"waste water","meaning":"浪費用水","examples":[{"en":"Old ditches wasted water.","zh":"舊溝渠浪費用水。"},{"en":"To waste water means to use water carelessly or lose it without benefit.","zh":"「waste water」意思是粗心使用水，或讓水無益地流失。"},{"en":"Leaving a tap running while brushing teeth wastes water.","zh":"刷牙時讓水龍頭一直開着會浪費用水。"},{"en":"If irrigation ditches waste water, less water reaches the crops that need it.","zh":"如果灌溉溝渠浪費用水，到達需要水的作物的水就更少。"},{"en":"The phrase points to avoidable loss of water.","zh":"這個短語指出可避免的水分損失。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":11},{"front":"wash soil and fertilizer into streams","meaning":"把泥土和肥料沖入溪流","examples":[{"en":"Old ditches washed soil and fertilizer into streams.","zh":"舊溝渠把泥土和肥料沖入溪流。"},{"en":"To wash soil and fertilizer into streams means to carry them away with water into small rivers.","zh":"「wash soil and fertilizer into streams」意思是水把泥土和肥料帶入小河。"},{"en":"Heavy rain can wash garden soil into drains if the ground is bare.","zh":"如果地面裸露，大雨可以把花園泥土沖入排水渠。"},{"en":"When fertilizer enters streams, it can damage water quality and aquatic life.","zh":"當肥料進入溪流，它可以破壞水質和水生生物。"},{"en":"The phrase describes harmful runoff.","zh":"這個短語描述有害徑流。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":11},{"front":"fertilizer","meaning":"肥料","examples":[{"en":"The new system reduced fertilizer use.","zh":"新系統減少了肥料使用。"},{"en":"Fertilizer is a substance added to soil or plants to help crops grow.","zh":"「fertilizer」是加入泥土或植物中幫助作物生長的物質。"},{"en":"Gardeners may use fertilizer when vegetables lack nutrients.","zh":"當蔬菜缺乏養分時，園丁可能使用肥料。"},{"en":"Too much fertilizer can wash into rivers and cause pollution.","zh":"過多肥料可能被沖入河流並造成污染。"},{"en":"The word refers to plant nutrients, not pesticides.","zh":"這個詞指植物養分，而不是農藥。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":11},{"front":"cut use by half","meaning":"將使用量減半","examples":[{"en":"The new system cut water and fertilizer use by half.","zh":"新系統將水和肥料使用量減半。"},{"en":"To cut use by half means to reduce use to 50 percent of the previous amount.","zh":"「cut use by half」意思是把使用量減至原來的50%。"},{"en":"A family can cut electricity use by half by replacing old appliances and switching off lights.","zh":"家庭可以透過更換舊電器和關燈，將用電量減半。"},{"en":"If a farm cuts water use by half, the saving is substantial.","zh":"如果農場將用水量減半，節省幅度就很大。"},{"en":"The phrase describes a large reduction.","zh":"這個短語描述大幅減少。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":11},{"front":"protect water quality","meaning":"保護水質","examples":[{"en":"The new system protected water quality.","zh":"新系統保護了水質。"},{"en":"To protect water quality means to keep water clean and safe for people, animals and ecosystems.","zh":"「protect water quality」意思是保持水清潔，並對人、動物和生態系統安全。"},{"en":"Cities protect water quality by treating sewage before it enters rivers.","zh":"城市透過在污水進入河流前處理它來保護水質。"},{"en":"If farms stop fertilizer from washing into streams, they help protect water quality.","zh":"如果農場阻止肥料被沖入溪流，它們就幫助保護水質。"},{"en":"The phrase focuses on preventing pollution.","zh":"這個短語集中於防止污染。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":11},{"front":"in addition","meaning":"此外","examples":[{"en":"In addition, the new system produced very large onions.","zh":"此外，新系統生產了非常大的洋蔥。"},{"en":"In addition means also or as another point.","zh":"「in addition」意思是此外、另外或作為另一點。"},{"en":"The school improved exam results; in addition, attendance also rose.","zh":"學校改善了考試成績；此外，出席率也上升。"},{"en":"A method that saves water and, in addition, improves crop size is especially valuable.","zh":"一種節省用水而且此外改善作物大小的方法特別有價值。"},{"en":"The phrase adds extra information.","zh":"這個短語加入額外資料。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":11},{"front":"produce crops of","meaning":"生產……作物","examples":[{"en":"The new system produced crops of very large onions.","zh":"新系統生產非常大的洋蔥作物。"},{"en":"To produce crops of something means to grow and harvest that kind of crop.","zh":"「produce crops of」某物，意思是種植並收成該類作物。"},{"en":"A farm may produce crops of potatoes, carrots and onions for local markets.","zh":"農場可能為本地市場生產薯仔、紅蘿蔔和洋蔥作物。"},{"en":"If new irrigation produces larger crops, growers may earn more money.","zh":"如果新灌溉方式生產更大型作物，種植者可能賺更多錢。"},{"en":"The phrase connects a farming method with what it grows.","zh":"這個短語把耕作方法與它種出的作物連繫起來。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":11},{"front":"be rated","meaning":"被評為……","examples":[{"en":"The onions were rated super-colossal.","zh":"這些洋蔥被評為特大型。"},{"en":"To be rated something means to be judged or classified at that level.","zh":"「be rated」某等級，意思是被判定或分類為該級別。"},{"en":"A hotel may be rated five stars if it meets high service standards.","zh":"如果酒店符合高服務標準，可能被評為五星級。"},{"en":"If onions are rated super-colossal, buyers know they meet a large-size grade.","zh":"如果洋蔥被評為特大型，買家就知道它們符合大型尺寸等級。"},{"en":"The phrase describes official or agreed classification.","zh":"這個短語描述官方或公認分類。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":11},{"front":"highly valued by","meaning":"深受……重視","examples":[{"en":"Super-colossal onions are highly valued by restaurants and processors.","zh":"特大型洋蔥深受餐廳和加工商重視。"},{"en":"Highly valued by someone means considered very useful, important or desirable by them.","zh":"「highly valued by」某人，意思是被他們認為非常有用、重要或值得擁有。"},{"en":"Clear communication is highly valued by employers.","zh":"清晰溝通深受僱主重視。"},{"en":"If large onions are highly valued by restaurants, growers can sell them at better prices.","zh":"如果大型洋蔥深受餐廳重視，種植者可以以更好價格出售。"},{"en":"The phrase shows who appreciates the product.","zh":"這個短語顯示誰重視該產品。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":11},{"front":"restaurant industry","meaning":"餐飲業","examples":[{"en":"The restaurant industry values very large onions.","zh":"餐飲業重視非常大的洋蔥。"},{"en":"The restaurant industry includes businesses that prepare and serve meals to customers.","zh":"「restaurant industry」包括為顧客準備和供應餐點的企業。"},{"en":"The restaurant industry needs reliable supplies of fresh food.","zh":"餐飲業需要穩定的新鮮食物供應。"},{"en":"If a crop suits restaurant needs, farmers may gain a stable market.","zh":"如果作物符合餐廳需要，農民可能獲得穩定市場。"},{"en":"The phrase refers to restaurants as a business sector.","zh":"這個短語把餐廳視為一個商業部門。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":12},{"front":"food processors","meaning":"食品加工商","examples":[{"en":"Food processors value large, high-quality onions.","zh":"食品加工商重視大型、高質素洋蔥。"},{"en":"Food processors are companies that turn raw food into packaged, prepared or processed products.","zh":"「food processors」是把原材料食物變成包裝、預製或加工產品的公司。"},{"en":"Food processors may cut, freeze, cook or pack vegetables for sale.","zh":"食品加工商可能切割、冷凍、烹煮或包裝蔬菜出售。"},{"en":"If onions are large and uniform, food processors can handle them more efficiently.","zh":"如果洋蔥又大又均勻，食品加工商可以更有效處理它們。"},{"en":"The phrase refers to businesses that process food after harvest.","zh":"這個短語指收成後加工食物的企業。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":12},{"front":"find that","meaning":"發現","examples":[{"en":"Growers are finding that environmentally benign practices can work well.","zh":"種植者發現對環境較溫和的做法可以很有效。"},{"en":"Find that means discover or realise that something is true.","zh":"「find that」意思是發現或意識到某事是真實的。"},{"en":"Students may find that short daily revision works better than last-minute studying.","zh":"學生可能發現每日短時間溫習比臨急抱佛腳更有效。"},{"en":"If farmers find that safer methods still produce good crops, they may change their habits.","zh":"如果農民發現較安全方法仍能生產好作物，他們可能改變習慣。"},{"en":"The phrase introduces a discovered result.","zh":"這個短語引出被發現的結果。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":12},{"front":"environmentally benign practices","meaning":"對環境較溫和的做法","examples":[{"en":"Environmentally benign practices can produce excellent results.","zh":"對環境較溫和的做法可以產生出色成果。"},{"en":"Environmentally benign practices are methods that cause little or less harm to the environment.","zh":"「environmentally benign practices」是對環境造成很少或較少傷害的方法。"},{"en":"Using compost instead of excessive chemical fertiliser can be an environmentally benign practice.","zh":"使用堆肥而不是過量化學肥料，可以是對環境較溫和的做法。"},{"en":"If environmentally benign practices also help profits, farmers have a strong reason to use them.","zh":"如果對環境較溫和的做法也有助利潤，農民就有強烈理由使用它們。"},{"en":"The phrase describes methods that are gentle on nature.","zh":"這個短語描述對自然較溫和的方法。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":12},{"front":"excellent results","meaning":"出色成果","examples":[{"en":"The new practices can have excellent results.","zh":"新做法可以有出色成果。"},{"en":"Excellent results are very good outcomes.","zh":"「excellent results」是非常好的結果。"},{"en":"A student can get excellent results after regular practice and careful feedback.","zh":"學生在定期練習和仔細回饋後，可以取得出色成果。"},{"en":"If a farming method gives excellent results, more growers may be willing to try it.","zh":"如果耕作方法帶來出色成果，更多種植者可能願意嘗試。"},{"en":"The phrase shows strong success.","zh":"這個短語顯示強烈成功。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":12},{"front":"benefit the environment","meaning":"對環境有益","examples":[{"en":"The new practices benefit the environment.","zh":"新做法對環境有益。"},{"en":"To benefit the environment means to help nature by reducing harm or improving conditions.","zh":"「benefit the environment」意思是透過減少傷害或改善狀況來幫助自然。"},{"en":"Planting trees can benefit the environment by improving air and soil quality.","zh":"種樹可以透過改善空氣和土壤質素而對環境有益。"},{"en":"If farms use less toxic pesticide, they may benefit the environment around them.","zh":"如果農場少用有毒農藥，它們可能對周邊環境有益。"},{"en":"The phrase focuses on positive environmental effects.","zh":"這個短語集中於正面環境影響。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":12},{"front":"help growers succeed","meaning":"幫助種植者成功","examples":[{"en":"The new practices help growers succeed.","zh":"新做法幫助種植者成功。"},{"en":"To help growers succeed means to support farmers so they can produce crops and earn income.","zh":"「help growers succeed」意思是支援農民，使他們能生產作物並賺取收入。"},{"en":"Better weather information can help growers succeed by guiding planting decisions.","zh":"更好的天氣資訊可以透過指導種植決定來幫助種植者成功。"},{"en":"If a method saves money and improves crop quality, it can help growers succeed.","zh":"如果一種方法省錢並改善作物質素，它可以幫助種植者成功。"},{"en":"The phrase links practical support with farming success.","zh":"這個短語把實際支援與農業成功連繫起來。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":12},{"front":"straw mulch","meaning":"稻草覆蓋物","examples":[{"en":"OSU researchers tested straw mulch in onion fields.","zh":"俄勒岡州立大學研究人員在洋蔥田測試稻草覆蓋物。"},{"en":"Straw mulch is a layer of straw placed on soil to protect it and hold moisture.","zh":"「straw mulch」是鋪在泥土上以保護泥土並保持水分的一層稻草。"},{"en":"Gardeners use straw mulch around vegetables to reduce weeds and keep soil cool.","zh":"園丁在蔬菜周圍使用稻草覆蓋物，以減少雜草並保持泥土涼爽。"},{"en":"If straw mulch prevents soil from blowing away, it can protect farmland.","zh":"如果稻草覆蓋物防止泥土被風吹走，它就可以保護農地。"},{"en":"The phrase names a simple material used for soil protection.","zh":"這個短語指出用於土壤保護的簡單材料。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":12},{"front":"hold soil in place","meaning":"固定泥土","examples":[{"en":"Straw mulch successfully held soil in place.","zh":"稻草覆蓋物成功固定泥土。"},{"en":"To hold soil in place means to stop soil from moving away by wind or water.","zh":"「hold soil in place」意思是防止泥土被風或水帶走。"},{"en":"Grass roots can hold soil in place on a hillside.","zh":"草根可以在山坡上固定泥土。"},{"en":"If soil is held in place, farms lose fewer nutrients during storms.","zh":"如果泥土被固定，農場在風暴期間流失的養分較少。"},{"en":"The phrase describes preventing erosion.","zh":"這個短語描述防止侵蝕。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":12},{"front":"keep the ground moist","meaning":"保持泥土濕潤","examples":[{"en":"Straw mulch kept the ground moist with less irrigation.","zh":"稻草覆蓋物在較少灌溉下保持泥土濕潤。"},{"en":"To keep the ground moist means to help soil stay slightly wet.","zh":"「keep the ground moist」意思是幫助泥土保持微濕。"},{"en":"A gardener may cover soil with leaves to keep the ground moist in hot weather.","zh":"園丁可能用葉子覆蓋泥土，在炎熱天氣保持泥土濕潤。"},{"en":"If the ground stays moist, crops may need less watering.","zh":"如果泥土保持濕潤，作物可能需要較少澆水。"},{"en":"The phrase focuses on holding water in soil.","zh":"這個短語集中於把水分留在土壤中。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":12},{"front":"less irrigation","meaning":"較少灌溉","examples":[{"en":"Straw mulch allowed crops to grow with less irrigation.","zh":"稻草覆蓋物讓作物在較少灌溉下生長。"},{"en":"Less irrigation means less artificial watering of crops or land.","zh":"「less irrigation」意思是對作物或土地進行較少人工澆水。"},{"en":"Plants that survive with less irrigation are useful in dry gardens.","zh":"能在較少灌溉下存活的植物適合乾燥花園。"},{"en":"If a farm needs less irrigation, it can save water and energy.","zh":"如果農場需要較少灌溉，它可以節省水和能源。"},{"en":"The phrase compares water use with a previous or normal level.","zh":"這個短語把用水量與以前或正常水平比較。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":12},{"front":"unexpectedly","meaning":"出乎意料地","examples":[{"en":"Unexpectedly, mulched soil created a home for helpful insects.","zh":"出乎意料地，覆蓋了草料的泥土為有益昆蟲創造了棲息地。"},{"en":"Unexpectedly means in a way that was not predicted or planned.","zh":"「unexpectedly」意思是以沒有預測或計劃到的方式。"},{"en":"Unexpectedly, the quiet student gave the strongest presentation.","zh":"出乎意料地，那位安靜的學生做出了最有力的演講。"},{"en":"If a farming experiment unexpectedly helps beneficial insects, researchers may study the effect further.","zh":"如果農業實驗出乎意料地幫助有益昆蟲，研究人員可能進一步研究該效果。"},{"en":"The word signals surprise.","zh":"這個詞表示驚訝。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":13},{"front":"mulched soil","meaning":"覆蓋了草料的泥土","examples":[{"en":"Mulched soil created a home for beneficial beetles and spiders.","zh":"覆蓋了草料的泥土為有益的甲蟲和蜘蛛創造了棲息地。"},{"en":"Mulched soil is soil covered with material such as straw, leaves or wood chips.","zh":"「mulched soil」是覆蓋了稻草、葉子或木屑等材料的泥土。"},{"en":"Mulched soil stays cooler and wetter than bare soil in hot weather.","zh":"在炎熱天氣中，覆蓋了草料的泥土比裸露泥土更涼爽和濕潤。"},{"en":"If mulched soil shelters helpful insects, it can support natural pest control.","zh":"如果覆蓋了草料的泥土庇護有益昆蟲，它可以支援自然害蟲控制。"},{"en":"The phrase describes soil protected by a covering layer.","zh":"這個短語描述受覆蓋層保護的泥土。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":13},{"front":"create a home for","meaning":"為……創造棲息地","examples":[{"en":"The mulched soil created a home for beneficial insects.","zh":"覆蓋了草料的泥土為有益昆蟲創造棲息地。"},{"en":"To create a home for living things means to provide a place where they can live or shelter.","zh":"「create a home for」生物，意思是提供牠們可以生活或躲藏的地方。"},{"en":"Planting flowers can create a home for bees and butterflies.","zh":"種花可以為蜜蜂和蝴蝶創造棲息地。"},{"en":"If farm soil creates a home for helpful insects, pests may be controlled naturally.","zh":"如果農田泥土為有益昆蟲創造棲息地，害蟲可能被自然控制。"},{"en":"The phrase connects habitat with protection.","zh":"這個短語把棲息地與保護連繫起來。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":13},{"front":"beneficial beetles and spiders","meaning":"有益的甲蟲和蜘蛛","examples":[{"en":"Beneficial beetles and spiders can help control pests.","zh":"有益的甲蟲和蜘蛛可以幫助控制害蟲。"},{"en":"Beneficial beetles and spiders are insects and arachnids that help farmers by eating pests.","zh":"「beneficial beetles and spiders」是透過吃害蟲幫助農民的昆蟲和蛛形動物。"},{"en":"Gardeners may welcome beneficial beetles and spiders because they reduce harmful insects naturally.","zh":"園丁可能歡迎有益的甲蟲和蜘蛛，因為牠們自然減少有害昆蟲。"},{"en":"If pesticides kill beneficial beetles and spiders, pest problems may worsen later.","zh":"如果農藥殺死有益的甲蟲和蜘蛛，害蟲問題日後可能惡化。"},{"en":"The phrase identifies helpful creatures, not harmful pests.","zh":"這個短語指出有幫助的生物，而不是有害害蟲。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":13},{"front":"prey on","meaning":"捕食……","examples":[{"en":"Some beetles and spiders prey on onion thrips.","zh":"一些甲蟲和蜘蛛捕食洋蔥薊馬。"},{"en":"To prey on something means to hunt, catch and eat it.","zh":"「prey on」某物，意思是獵捕並吃掉它。"},{"en":"Cats may prey on small birds or mice.","zh":"貓可能捕食小鳥或老鼠。"},{"en":"If beneficial insects prey on crop pests, farmers may need fewer sprays.","zh":"如果有益昆蟲捕食作物害蟲，農民可能需要較少噴劑。"},{"en":"The phrase describes a natural feeding relationship.","zh":"這個短語描述自然覓食關係。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":13},{"front":"onion thrips","meaning":"洋蔥薊馬","examples":[{"en":"Onion thrips are a notorious pest in commercial onion fields.","zh":"洋蔥薊馬是商業洋蔥田中惡名昭著的害蟲。"},{"en":"Onion thrips are tiny insects that damage onion plants.","zh":"「onion thrips」是破壞洋蔥植物的微小昆蟲。"},{"en":"Farmers may look for onion thrips by checking leaves for silver marks or damage.","zh":"農民可能透過檢查葉片是否有銀色痕跡或損害來尋找洋蔥薊馬。"},{"en":"If onion thrips spread widely, onion quality and yield may fall.","zh":"如果洋蔥薊馬廣泛擴散，洋蔥質素和產量可能下降。"},{"en":"The phrase names a specific pest of onions.","zh":"這個短語指出洋蔥的一種特定害蟲。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":13},{"front":"notorious pest","meaning":"惡名昭著的害蟲","examples":[{"en":"Onion thrips are a notorious pest in onion fields.","zh":"洋蔥薊馬是洋蔥田中惡名昭著的害蟲。"},{"en":"A notorious pest is a pest that is well known for causing serious problems.","zh":"「notorious pest」是因造成嚴重問題而廣為人知的害蟲。"},{"en":"Mosquitoes are a notorious pest in many warm and wet areas.","zh":"在許多溫暖潮濕地區，蚊子是惡名昭著的害蟲。"},{"en":"If a pest is notorious, farmers may already expect it to be difficult to control.","zh":"如果一種害蟲惡名昭著，農民可能已預期它難以控制。"},{"en":"The phrase has a negative meaning and suggests a bad reputation.","zh":"這個短語有負面意思，暗示壞名聲。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":13},{"front":"commercial onion fields","meaning":"商業洋蔥田","examples":[{"en":"Onion thrips are common pests in commercial onion fields.","zh":"洋蔥薊馬是商業洋蔥田中的常見害蟲。"},{"en":"Commercial onion fields are fields where onions are grown for sale, not just personal use.","zh":"「commercial onion fields」是種植洋蔥作銷售，而不是只供個人使用的田地。"},{"en":"Commercial onion fields must produce enough onions to meet market demand.","zh":"商業洋蔥田必須生產足夠洋蔥以滿足市場需求。"},{"en":"If pests damage commercial onion fields, farmers may lose serious income.","zh":"如果害蟲破壞商業洋蔥田，農民可能損失嚴重收入。"},{"en":"The phrase connects farming with business production.","zh":"這個短語把耕作與商業生產連繫起來。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":13},{"front":"reduce the need for pesticides","meaning":"減少對農藥的需求","examples":[{"en":"The discovery could reduce the need for pesticides.","zh":"這項發現可以減少對農藥的需求。"},{"en":"To reduce the need for pesticides means to make chemical pest control less necessary.","zh":"「reduce the need for pesticides」意思是令化學害蟲控制較不必要。"},{"en":"Beneficial insects can reduce the need for pesticides by eating harmful pests.","zh":"有益昆蟲可以透過吃有害害蟲來減少對農藥的需求。"},{"en":"If pest numbers fall naturally, farmers may not need to spray as often.","zh":"如果害蟲數量自然下降，農民可能不需要那麼常噴藥。"},{"en":"The phrase focuses on lowering dependence on chemicals.","zh":"這個短語集中於降低對化學品的依賴。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":13},{"front":"would never have believed that","meaning":"從未想過……","examples":[{"en":"The farmer would never have believed that natural methods could work so well.","zh":"那位農民從未想過自然方法可以如此有效。"},{"en":"Would never have believed that means would not have expected something to be true before seeing evidence.","zh":"「would never have believed that」意思是在看到證據前不會預期某事是真的。"},{"en":"I would never have believed that a short daily walk could improve my sleep so much.","zh":"我從未想過每天短短散步可以大幅改善睡眠。"},{"en":"If results surpass expectations, people may say they would never have believed it.","zh":"如果結果超出預期，人們可能說自己從未想過。"},{"en":"The phrase expresses strong surprise.","zh":"這個短語表達強烈驚訝。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":13},{"front":"artificial pest controls","meaning":"人工害蟲控制方法","examples":[{"en":"The growers had previously used artificial pest controls.","zh":"種植者以前使用人工害蟲控制方法。"},{"en":"Artificial pest controls are human-made methods, often chemical or mechanical, used to manage pests.","zh":"「artificial pest controls」是人造的害蟲管理方法，通常是化學或機械方法。"},{"en":"Sprays, traps and treated materials can be artificial pest controls.","zh":"噴劑、陷阱和經處理材料都可以是人工害蟲控制方法。"},{"en":"If artificial pest controls are reduced, farmers may need natural predators or better field management.","zh":"如果人工害蟲控制方法減少，農民可能需要天然捕食者或更好田地管理。"},{"en":"The phrase contrasts human-made methods with natural control.","zh":"這個短語把人造方法與自然控制作對比。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":13},{"front":"keep good results","meaning":"保持良好成效","examples":[{"en":"The farmer was surprised that they could keep good results without old controls.","zh":"農民驚訝於他們不用舊控制方法也能保持良好成效。"},{"en":"To keep good results means to maintain strong outcomes even after a change.","zh":"「keep good results」意思是在改變後仍維持強勁成果。"},{"en":"A student may keep good results by revising regularly instead of studying only before exams.","zh":"學生可以透過定期溫習，而不是只在考試前讀書，保持良好成績。"},{"en":"If growers keep good results with fewer chemicals, the new system becomes more convincing.","zh":"如果種植者用較少化學品仍保持良好成效，新系統就更令人信服。"},{"en":"The phrase focuses on maintaining success.","zh":"這個短語集中於維持成功。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":14},{"front":"surpass expectations","meaning":"超出預期","examples":[{"en":"The new methods actually surpassed expectations.","zh":"新方法實際上超出預期。"},{"en":"To surpass expectations means to do better than people expected.","zh":"「surpass expectations」意思是表現比人們預期更好。"},{"en":"A quiet student may surpass expectations by giving an excellent speech.","zh":"安靜的學生可能透過精彩演講超出預期。"},{"en":"If a farming method surpasses expectations, more farmers may become interested in it.","zh":"如果耕作方法超出預期，更多農民可能對它感興趣。"},{"en":"The phrase signals a better-than-expected result.","zh":"這個短語表示結果比預期更好。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":14},{"front":"reduce dependence on","meaning":"減少對……的依賴","examples":[{"en":"Researchers are working to reduce dependence on chemical sprays.","zh":"研究人員正努力減少對化學噴劑的依賴。"},{"en":"To reduce dependence on something means to rely on it less.","zh":"「reduce dependence on」某物，意思是較少依賴它。"},{"en":"A city can reduce dependence on cars by improving public transport.","zh":"城市可以透過改善公共交通來減少對汽車的依賴。"},{"en":"If farmers reduce dependence on chemical sprays, they may lower costs and environmental risks.","zh":"如果農民減少對化學噴劑的依賴，他們可能降低成本和環境風險。"},{"en":"The phrase focuses on becoming less reliant.","zh":"這個短語集中於變得較不依賴。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":14},{"front":"broad-spectrum chemical sprays","meaning":"廣譜化學噴劑","examples":[{"en":"Broad-spectrum chemical sprays are toxic to many organisms.","zh":"廣譜化學噴劑對多種生物有毒。"},{"en":"Broad-spectrum chemical sprays are pesticides that affect many kinds of pests and other living things.","zh":"「broad-spectrum chemical sprays」是影響多種害蟲和其他生物的農藥噴劑。"},{"en":"A broad-spectrum spray may kill harmful insects but also beneficial ones.","zh":"廣譜噴劑可能殺死有害昆蟲，也殺死有益昆蟲。"},{"en":"If broad-spectrum sprays are overused, farm ecosystems may lose helpful predators.","zh":"如果廣譜噴劑被過度使用，農場生態系統可能失去有益捕食者。"},{"en":"The phrase suggests wide effect, not targeted action.","zh":"這個短語暗示影響廣泛，而不是針對性行動。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":14},{"front":"toxic to","meaning":"對……有毒","examples":[{"en":"Some chemical sprays are toxic to humans and other organisms.","zh":"一些化學噴劑對人類和其他生物有毒。"},{"en":"Toxic to something means poisonous or harmful to that living thing.","zh":"「toxic to」某物，意思是對該生物有毒或有害。"},{"en":"Chocolate can be toxic to dogs even if humans can eat it safely.","zh":"巧克力對狗可能有毒，即使人類可以安全食用。"},{"en":"If a spray is toxic to beneficial insects, it may create new pest problems.","zh":"如果噴劑對有益昆蟲有毒，它可能造成新的害蟲問題。"},{"en":"The phrase identifies who or what may be harmed.","zh":"這個短語指出誰或什麼可能受害。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":14},{"front":"many kinds of organisms","meaning":"多種生物","examples":[{"en":"Broad-spectrum sprays can harm many kinds of organisms.","zh":"廣譜噴劑可以傷害多種生物。"},{"en":"Many kinds of organisms means many types of living things.","zh":"「many kinds of organisms」意思是許多種類的生物。"},{"en":"A pond contains many kinds of organisms, including fish, insects, plants and microbes.","zh":"池塘包含多種生物，包括魚、昆蟲、植物和微生物。"},{"en":"If chemicals harm many kinds of organisms, the whole ecosystem may be affected.","zh":"如果化學品傷害多種生物，整個生態系統可能受影響。"},{"en":"The phrase is broader than “many animals” because it includes plants and tiny life forms too.","zh":"這個短語比「許多動物」更廣，因為也包括植物和微小生命。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":14},{"front":"rightly put pressure on","meaning":"正當地向……施壓","examples":[{"en":"Consumers are rightly putting pressure on the industry to change.","zh":"消費者正正當地向業界施壓，要求改變。"},{"en":"To rightly put pressure on someone means to justifiably urge them to act differently.","zh":"「rightly put pressure on」某人，意思是有正當理由地促使他們改變行動。"},{"en":"Parents may rightly put pressure on schools to improve safety after repeated accidents.","zh":"多次事故後，家長可能正當地向學校施壓，要求改善安全。"},{"en":"If consumers worry about pesticides, they may rightly pressure producers to reduce risks.","zh":"如果消費者擔心農藥，他們可能正當地向生產者施壓以減少風險。"},{"en":"The word rightly suggests the pressure is reasonable.","zh":"rightly 這個詞暗示壓力是合理的。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":14},{"front":"the industry","meaning":"業界","examples":[{"en":"Consumers are pressuring the industry to reduce chemical pesticides.","zh":"消費者正在向業界施壓，要求減少化學農藥。"},{"en":"The industry means the businesses and organisations involved in a particular economic activity.","zh":"「the industry」指參與某項經濟活動的企業和組織。"},{"en":"The restaurant industry includes restaurants, suppliers and related workers.","zh":"餐飲業界包括餐廳、供應商和相關工人。"},{"en":"If the farming industry changes its methods, many growers and buyers are affected.","zh":"如果農業界改變方法，許多種植者和買家都會受影響。"},{"en":"The phrase refers to a business sector as a whole.","zh":"這個短語指整個商業部門。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":14},{"front":"change its reliance on","meaning":"改變對……的依賴","examples":[{"en":"The industry is under pressure to change its reliance on chemical pesticides.","zh":"業界正面對壓力，要改變對化學農藥的依賴。"},{"en":"To change its reliance on something means to alter how much it depends on that thing.","zh":"「change its reliance on」某物，意思是改變依賴該物的程度。"},{"en":"A city may change its reliance on private cars by building better trains.","zh":"城市可以透過建造更好的鐵路改變對私家車的依賴。"},{"en":"If farming changes its reliance on chemicals, new pest-control systems are needed.","zh":"如果農業改變對化學品的依賴，就需要新的害蟲控制系統。"},{"en":"The phrase describes a shift in dependence.","zh":"這個短語描述依賴程度的轉變。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":14},{"front":"chemical pesticides","meaning":"化學農藥","examples":[{"en":"Pear growers are trying to reduce chemical pesticides.","zh":"梨種植者正試圖減少化學農藥。"},{"en":"Chemical pesticides are manufactured substances used to kill or control pests.","zh":"「chemical pesticides」是用來殺死或控制害蟲的人造物質。"},{"en":"Chemical pesticides can protect crops, but they may also create health and environmental concerns.","zh":"化學農藥可以保護作物，但也可能造成健康和環境關注。"},{"en":"If chemical pesticides are reduced, farmers may need other control methods.","zh":"如果化學農藥被減少，農民可能需要其他控制方法。"},{"en":"The phrase refers to pest-control chemicals.","zh":"這個短語指害蟲控制化學品。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":14},{"front":"picture-perfect product","meaning":"外觀完美的產品","examples":[{"en":"Consumers still want a picture-perfect product.","zh":"消費者仍然想要外觀完美的產品。"},{"en":"A picture-perfect product looks flawless and attractive, as if it were made for a photograph.","zh":"「picture-perfect product」是看起來毫無瑕疵、很吸引，像為照片而製作的產品。"},{"en":"Shoppers may choose picture-perfect fruit even when slightly marked fruit tastes the same.","zh":"即使有小痕跡的水果味道一樣，購物者也可能選外觀完美的水果。"},{"en":"If consumers demand picture-perfect produce, growers may feel pressure to use more chemicals.","zh":"如果消費者要求外觀完美的農產品，種植者可能感到壓力要使用更多化學品。"},{"en":"The phrase focuses on appearance.","zh":"這個短語集中於外觀。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":14},{"front":"research and extension centre","meaning":"研究及推廣中心","examples":[{"en":"Researchers at the centre help pear growers reduce pesticide use.","zh":"該中心的研究人員幫助梨種植者減少農藥使用。"},{"en":"A research and extension centre connects scientific research with practical advice for farmers.","zh":"「research and extension centre」把科學研究與給農民的實用建議連接起來。"},{"en":"Farmers may attend training at a research and extension centre before trying a new method.","zh":"農民可能在嘗試新方法前，到研究及推廣中心參加培訓。"},{"en":"If such a centre communicates well, research can reach real farms faster.","zh":"如果這類中心溝通良好，研究可以更快到達真實農場。"},{"en":"The phrase combines study with public outreach.","zh":"這個短語結合研究和公共外展。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":15},{"front":"highly toxic pesticides","meaning":"高毒性農藥","examples":[{"en":"Pear growers are reducing the need for highly toxic pesticides.","zh":"梨種植者正在減少對高毒性農藥的需求。"},{"en":"Highly toxic pesticides are pesticides that can cause serious harm even in small amounts.","zh":"「highly toxic pesticides」是即使少量也可能造成嚴重傷害的農藥。"},{"en":"Workers must handle highly toxic pesticides with strict safety equipment.","zh":"工人必須用嚴格安全裝備處理高毒性農藥。"},{"en":"Reducing highly toxic pesticides can protect farm workers, consumers and wildlife.","zh":"減少高毒性農藥可以保護農場工人、消費者和野生動物。"},{"en":"The phrase stresses a high level of danger.","zh":"這個短語強調高危險程度。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":15},{"front":"traditionally require","meaning":"傳統上需要","examples":[{"en":"Picture-perfect pears have traditionally required lots of chemicals.","zh":"外觀完美的梨傳統上需要大量化學品。"},{"en":"Traditionally require means have usually needed something according to past practice.","zh":"「traditionally require」意思是按照過去做法通常需要某物。"},{"en":"Some exams have traditionally required handwritten answers.","zh":"有些考試傳統上需要手寫答案。"},{"en":"If perfect-looking fruit traditionally requires chemicals, growers need new methods to change that pattern.","zh":"如果外觀完美的水果傳統上需要化學品，種植者就需要新方法改變這個模式。"},{"en":"The phrase contrasts old practice with possible new approaches.","zh":"這個短語把舊做法與可能的新方法作對比。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":15},{"front":"lots of chemicals","meaning":"大量化學品","examples":[{"en":"Perfect-looking pears once required lots of chemicals.","zh":"外觀完美的梨曾經需要大量化學品。"},{"en":"Lots of chemicals means a large amount of chemical substances.","zh":"「lots of chemicals」意思是大量化學物質。"},{"en":"Cleaning products with lots of chemicals may irritate sensitive skin.","zh":"含有大量化學品的清潔產品可能刺激敏感皮膚。"},{"en":"If fruit production needs lots of chemicals, environmental and health concerns may rise.","zh":"如果水果生產需要大量化學品，環境和健康關注可能上升。"},{"en":"The phrase is informal and stresses quantity.","zh":"這個短語較口語化，強調數量。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":15},{"front":"in recent years","meaning":"近年","examples":[{"en":"In recent years, the pear industry has faced overseas competition.","zh":"近年，梨產業面對海外競爭。"},{"en":"In recent years means during the last few years.","zh":"「in recent years」意思是在過去幾年。"},{"en":"In recent years, many schools have used more online learning tools.","zh":"近年，許多學校使用了更多網上學習工具。"},{"en":"If competition has increased in recent years, older business methods may no longer be enough.","zh":"如果近年競爭增加，舊商業方法可能不再足夠。"},{"en":"The phrase gives a recent time frame.","zh":"這個短語提供近期時間框架。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":15},{"front":"face stiff competition from","meaning":"面對來自……的激烈競爭","examples":[{"en":"The industry has faced stiff competition from overseas producers.","zh":"該產業面對來自海外生產商的激烈競爭。"},{"en":"To face stiff competition from someone means to compete against very strong rivals.","zh":"「face stiff competition from」某人，意思是面對很強競爭對手。"},{"en":"Small shops face stiff competition from large online stores.","zh":"小商店面對來自大型網店的激烈競爭。"},{"en":"If growers face stiff competition, they must control costs and maintain quality.","zh":"如果種植者面對激烈競爭，他們必須控制成本並維持質素。"},{"en":"The phrase suggests a difficult business challenge.","zh":"這個短語暗示困難的商業挑戰。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":15},{"front":"overseas producers","meaning":"海外生產商","examples":[{"en":"Overseas producers compete with Oregon pear growers.","zh":"海外生產商與俄勒岡州梨種植者競爭。"},{"en":"Overseas producers are companies or farmers in other countries that make or grow goods.","zh":"「overseas producers」是在其他國家製造或種植貨品的公司或農民。"},{"en":"Local shops may face lower prices from overseas producers.","zh":"本地商店可能面對來自海外生產商的較低價格。"},{"en":"If overseas producers sell cheaper fruit, local growers may need to improve efficiency.","zh":"如果海外生產商出售較便宜水果，本地種植者可能需要提高效率。"},{"en":"The phrase identifies competitors from outside the country.","zh":"這個短語指出來自國外的競爭者。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":15},{"front":"make sense economically","meaning":"在經濟上合理","examples":[{"en":"New methods must make sense economically as well as environmentally.","zh":"新方法必須在經濟上合理，也要在環境方面合理。"},{"en":"To make sense economically means to be affordable or financially reasonable.","zh":"「make sense economically」意思是負擔得起或在財務上合理。"},{"en":"A family budget must make sense economically before a holiday is booked.","zh":"家庭在預訂假期前，預算必須在經濟上合理。"},{"en":"If a farming method is too expensive, it may not make sense economically even if it helps nature.","zh":"如果耕作方法太昂貴，即使有助自然，也可能在經濟上不合理。"},{"en":"The phrase checks whether an idea works financially.","zh":"這個短語檢查一個想法在財務上是否可行。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":15},{"front":"as well as environmentally","meaning":"亦在環境方面","examples":[{"en":"New farming methods must work economically as well as environmentally.","zh":"新耕作方法必須在經濟上可行，亦在環境方面可行。"},{"en":"As well as environmentally means also in terms of environmental effects.","zh":"「as well as environmentally」意思是也從環境影響方面來看。"},{"en":"A building plan should be practical as well as environmentally responsible.","zh":"建築計劃應該實用，亦在環境方面負責任。"},{"en":"If a farming method saves money as well as protecting nature, growers are more likely to adopt it.","zh":"如果耕作方法既省錢又保護自然，種植者更可能採用。"},{"en":"The phrase adds the environmental side to another consideration.","zh":"這個短語把環境方面加入另一項考慮。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":15},{"front":"growth regulator","meaning":"生長調節劑","examples":[{"en":"Hilton is testing a growth regulator.","zh":"Hilton 正在測試一種生長調節劑。"},{"en":"A growth regulator is a substance that changes how an organism grows or develops.","zh":"「growth regulator」是改變生物如何生長或發育的物質。"},{"en":"Farmers may use a growth regulator to affect insects or plant growth.","zh":"農民可能使用生長調節劑來影響昆蟲或植物生長。"},{"en":"If a growth regulator stops pest larvae from developing normally, it can reduce crop damage.","zh":"如果生長調節劑阻止害蟲幼蟲正常發育，它可以減少作物損害。"},{"en":"The phrase names a targeted biological or chemical tool.","zh":"這個短語指出一種針對性的生物或化學工具。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":15},{"front":"interfere with","meaning":"干擾……","examples":[{"en":"The growth regulator interferes with the molting of larvae.","zh":"生長調節劑干擾幼蟲蛻皮。"},{"en":"To interfere with something means to disturb it or stop it from working normally.","zh":"「interfere with」某事，意思是打擾它或阻止它正常運作。"},{"en":"Loud noise can interfere with students’ concentration.","zh":"噪音可以干擾學生專注。"},{"en":"If a chemical interferes with insect development, the pest may not survive.","zh":"如果化學品干擾昆蟲發育，害蟲可能無法存活。"},{"en":"The phrase shows disruption of a process.","zh":"這個短語顯示對過程的干擾。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":15},{"front":"molting","meaning":"蛻皮","examples":[{"en":"The growth regulator affects the molting of codling moth larvae.","zh":"生長調節劑影響蘋果蠹蛾幼蟲的蛻皮。"},{"en":"Molting is the process in which an insect or animal sheds its outer skin or covering as it grows.","zh":"「molting」是昆蟲或動物生長時脫去外皮或外殼的過程。"},{"en":"A crab molts when it outgrows its old shell.","zh":"螃蟹長大到舊殼不合身時會蛻皮。"},{"en":"If molting is disrupted, larvae may fail to develop properly.","zh":"如果蛻皮被干擾，幼蟲可能無法正常發育。"},{"en":"The word describes an important growth stage.","zh":"這個詞描述重要生長階段。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":16},{"front":"codling moth larvae","meaning":"蘋果蠹蛾幼蟲","examples":[{"en":"Codling moth larvae can damage fruit crops.","zh":"蘋果蠹蛾幼蟲可以破壞水果作物。"},{"en":"Codling moth larvae are the young stage of moths that can feed inside apples and pears.","zh":"「codling moth larvae」是蛾的幼年階段，可以在蘋果和梨內取食。"},{"en":"Fruit growers check for codling moth larvae because they can ruin fruit quality.","zh":"水果種植者檢查蘋果蠹蛾幼蟲，因為牠們可以破壞水果質素。"},{"en":"If larvae enter fruit, the crop may become unsellable.","zh":"如果幼蟲進入水果，作物可能無法出售。"},{"en":"The phrase names a specific pest stage.","zh":"這個短語指出特定害蟲階段。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":16},{"front":"pheromone dispensers","meaning":"信息素釋放器","examples":[{"en":"Another study used pheromone dispensers to disrupt mating.","zh":"另一項研究使用信息素釋放器來干擾交配。"},{"en":"Pheromone dispensers are devices that release chemical signals used by insects for communication.","zh":"「pheromone dispensers」是釋放昆蟲用於溝通的化學訊號的裝置。"},{"en":"Farmers may place pheromone dispensers in orchards to confuse moths.","zh":"農民可能在果園放置信息素釋放器來混淆蛾。"},{"en":"If insects cannot find mates, their population may fall without heavy pesticide use.","zh":"如果昆蟲找不到交配對象，牠們的種群可能下降，而不需大量使用農藥。"},{"en":"The phrase names a pest-control tool based on insect behaviour.","zh":"這個短語指出一種基於昆蟲行為的害蟲控制工具。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":16},{"front":"disrupt mating","meaning":"干擾交配","examples":[{"en":"Pheromone dispensers can disrupt codling moth mating.","zh":"信息素釋放器可以干擾蘋果蠹蛾交配。"},{"en":"To disrupt mating means to interfere with animals finding partners and reproducing.","zh":"「disrupt mating」意思是干擾動物尋找伴侶和繁殖。"},{"en":"Bright city lights can disrupt mating signals in some insects.","zh":"明亮城市燈光可以干擾一些昆蟲的交配訊號。"},{"en":"If pest mating is disrupted, fewer young pests may appear later.","zh":"如果害蟲交配被干擾，之後出現的年幼害蟲可能更少。"},{"en":"The phrase describes stopping reproduction rather than killing adults directly.","zh":"這個短語描述阻止繁殖，而不是直接殺死成年個體。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":16},{"front":"organophosphates","meaning":"有機磷農藥","examples":[{"en":"Pear growers reduced their use of organophosphates by two-thirds.","zh":"梨種植者將有機磷農藥的使用量減少三分之二。"},{"en":"Organophosphates are a class of chemical pesticides that can be highly toxic.","zh":"「organophosphates」是一類可能高毒性的化學農藥。"},{"en":"Farm workers need safety training when handling organophosphates.","zh":"農場工人處理有機磷農藥時需要安全訓練。"},{"en":"Reducing organophosphates can lower risk to people and beneficial insects.","zh":"減少有機磷農藥可以降低對人和有益昆蟲的風險。"},{"en":"The phrase names a specific type of pesticide.","zh":"這個短語指出一種特定農藥。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":16},{"front":"synthetic pesticides","meaning":"合成農藥","examples":[{"en":"Growers reduced all other synthetic pesticides by even more.","zh":"種植者將所有其他合成農藥減少得更多。"},{"en":"Synthetic pesticides are human-made chemicals used to control pests.","zh":"「synthetic pesticides」是用來控制害蟲的人造化學品。"},{"en":"A farm may reduce synthetic pesticides by using traps, predators or careful monitoring.","zh":"農場可以透過使用陷阱、捕食者或仔細監測來減少合成農藥。"},{"en":"If synthetic pesticides are used too often, pests may become resistant.","zh":"如果合成農藥使用太頻繁，害蟲可能產生抗藥性。"},{"en":"The phrase contrasts manufactured chemicals with natural or biological methods.","zh":"這個短語把人造化學品與自然或生物方法作對比。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":16},{"front":"part of the effort to","meaning":"……努力的一部分","examples":[{"en":"The studies are part of the effort to find alternative practices.","zh":"這些研究是尋找替代做法努力的一部分。"},{"en":"Part of the effort to do something means one piece of a larger attempt.","zh":"「part of the effort to」做某事，意思是較大嘗試中的一部分。"},{"en":"Recycling bins are part of the effort to reduce household waste.","zh":"回收箱是減少家庭廢物努力的一部分。"},{"en":"Research trials can be part of the effort to change farming safely.","zh":"研究試驗可以是安全改變農業努力的一部分。"},{"en":"The phrase connects one action with a wider goal.","zh":"這個短語把一個行動與更大目標連繫起來。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":16},{"front":"alternative farming practices","meaning":"替代農業做法","examples":[{"en":"The IPPC seeks alternative farming practices.","zh":"IPPC 尋求替代農業做法。"},{"en":"Alternative farming practices are different ways of farming that replace or reduce older methods.","zh":"「alternative farming practices」是取代或減少舊方法的不同耕作方式。"},{"en":"Using natural predators instead of heavy sprays is an alternative farming practice.","zh":"使用天然捕食者而不是大量噴劑，是一種替代農業做法。"},{"en":"If alternative practices work well, farms can reduce environmental harm.","zh":"如果替代做法有效，農場可以減少環境傷害。"},{"en":"The phrase suggests practical replacements, not just ideas.","zh":"這個短語暗示實際替代方案，而不只是想法。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":16},{"front":"benefit both the economy and the environment","meaning":"同時有利於經濟和環境","examples":[{"en":"Researchers want practices that benefit both the economy and the environment.","zh":"研究人員希望有同時有利於經濟和環境的做法。"},{"en":"To benefit both the economy and the environment means to help financial activity and nature at the same time.","zh":"「benefit both the economy and the environment」意思是同時幫助經濟活動和自然環境。"},{"en":"Energy-saving buildings can benefit both the economy and the environment by lowering bills and emissions.","zh":"節能建築可以透過降低帳單和排放，同時有利於經濟和環境。"},{"en":"If farming methods protect soil and increase profit, they benefit both sides.","zh":"如果耕作方法保護土壤並增加利潤，它就同時有利於兩方面。"},{"en":"The phrase highlights a win-win goal.","zh":"這個短語強調雙贏目標。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":16},{"front":"match each opinion or action with","meaning":"將每項意見或行動與……配對","examples":[{"en":"Students match each opinion or action with the correct person.","zh":"學生將每項意見或行動與正確人物配對。"},{"en":"To match each opinion or action with someone means to connect each statement to the person who said or did it.","zh":"「match each opinion or action with」某人，意思是把每項陳述連到說出或做出它的人。"},{"en":"In a reading exercise, students match each idea with the correct researcher.","zh":"在閱讀練習中，學生把每個想法與正確研究人員配對。"},{"en":"If two people have similar opinions, this task can be difficult.","zh":"如果兩個人有相似意見，這種題目可能困難。"},{"en":"The phrase gives an instruction for a matching question.","zh":"這個短語是配對題指示。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":16},{"front":"correct person","meaning":"正確人物","examples":[{"en":"Each opinion should be matched with the correct person.","zh":"每項意見應與正確人物配對。"},{"en":"The correct person is the person who truly said, did or believed the thing mentioned.","zh":"「correct person」是真正說過、做過或相信所提事情的人。"},{"en":"In a history test, students must match each quote with the correct person.","zh":"在歷史測驗中，學生必須把每句引文與正確人物配對。"},{"en":"If students choose the wrong person, the answer may not match the text.","zh":"如果學生選錯人物，答案可能不符合文本。"},{"en":"The phrase focuses on accurate attribution.","zh":"這個短語集中於準確歸屬。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":16},{"front":"use any letter more than once","meaning":"可使用任何字母多於一次","examples":[{"en":"Students may use any letter more than once.","zh":"學生可使用任何字母多於一次。"},{"en":"Use any letter more than once means the same option can be chosen for more than one answer.","zh":"「use any letter more than once」意思是同一選項可以用於多於一個答案。"},{"en":"In a matching task, one person may match two different statements.","zh":"在配對題中，一個人物可能對應兩項不同陳述。"},{"en":"If students think each letter can be used only once, they may make avoidable mistakes.","zh":"如果學生以為每個字母只能用一次，他們可能犯可避免錯誤。"},{"en":"The phrase changes how answer choices should be managed.","zh":"這個短語改變處理答案選項的方式。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":17},{"front":"offer two distinct advantages","meaning":"提供兩項不同好處","examples":[{"en":"The new techniques offer two distinct advantages.","zh":"新技術提供兩項不同好處。"},{"en":"To offer two distinct advantages means to provide two clearly different benefits.","zh":"「offer two distinct advantages」意思是提供兩項清楚不同的好處。"},{"en":"Online lessons offer two distinct advantages: flexible time and no travel.","zh":"網上課堂提供兩項不同好處：時間彈性和不用交通。"},{"en":"If a farming method saves water and improves crop quality, it offers two distinct advantages.","zh":"如果耕作方法節省用水並改善作物質素，它就提供兩項不同好處。"},{"en":"The phrase highlights separate benefits, not one repeated benefit.","zh":"這個短語強調分開的好處，而不是重複同一好處。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":17},{"front":"work on developing alternative techniques","meaning":"研發替代技術的工作","examples":[{"en":"Work on developing alternative techniques is not yet complete.","zh":"研發替代技術的工作尚未完成。"},{"en":"Work on developing alternative techniques means the effort to create different methods is still continuing.","zh":"「work on developing alternative techniques」意思是創造不同方法的努力仍在繼續。"},{"en":"Scientists may work on developing alternative techniques when old methods cause side effects.","zh":"當舊方法造成副作用，科學家可能研發替代技術。"},{"en":"If this work is not complete, farmers may still need temporary solutions.","zh":"如果這項工作尚未完成，農民可能仍需要臨時解決方案。"},{"en":"The phrase describes ongoing research and development.","zh":"這個短語描述持續進行的研究和發展。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":17},{"front":"eating food produced with","meaning":"食用以……生產的食物","examples":[{"en":"The question mentions eating food produced with toxic chemicals.","zh":"問題提到食用以有毒化學品生產的食物。"},{"en":"Eating food produced with something means consuming food grown or made using that substance.","zh":"「eating food produced with」某物，意思是食用使用該物種植或製造的食物。"},{"en":"Some shoppers worry about eating food produced with heavy chemical sprays.","zh":"一些購物者擔心食用以大量化學噴劑生產的食物。"},{"en":"If food is produced with toxic chemicals, consumers may ask about residues and safety.","zh":"如果食物以有毒化學品生產，消費者可能詢問殘留和安全。"},{"en":"The phrase links food consumption with production methods.","zh":"這個短語把食用食物與生產方法連繫起來。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":17},{"front":"dangerous to human health","meaning":"對人體健康有危險","examples":[{"en":"Some critics say toxic chemicals are dangerous to human health.","zh":"一些批評者說有毒化學品對人體健康有危險。"},{"en":"Dangerous to human health means able to harm people’s bodies or wellbeing.","zh":"「dangerous to human health」意思是能傷害人體或健康狀況。"},{"en":"Dirty drinking water is dangerous to human health because it can spread disease.","zh":"骯髒飲用水對人體健康有危險，因為它可以傳播疾病。"},{"en":"If farm chemicals remain on food, critics may argue they are dangerous to human health.","zh":"如果農場化學品殘留在食物上，批評者可能認為它們對人體健康有危險。"},{"en":"The phrase focuses on risk to people.","zh":"這個短語集中於對人的風險。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":17},{"front":"change from current methods to new ones","meaning":"從現行方法轉用新方法","examples":[{"en":"Changing from current farming methods to new ones is expensive.","zh":"從現行耕作方法轉用新方法很昂貴。"},{"en":"To change from current methods to new ones means to stop using existing practices and adopt different ones.","zh":"「change from current methods to new ones」意思是停止使用現有做法並採用不同做法。"},{"en":"A school may change from paper notices to online messages.","zh":"學校可能從紙本通告轉用網上訊息。"},{"en":"If changing methods requires equipment and training, the cost can be high.","zh":"如果轉換方法需要設備和訓練，成本可能很高。"},{"en":"The phrase describes a transition from old practice to new practice.","zh":"這個短語描述從舊做法到新做法的過渡。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":17},{"front":"current farming methods","meaning":"現行耕作方法","examples":[{"en":"Some farmers worry about the cost of changing current farming methods.","zh":"一些農民擔心改變現行耕作方法的成本。"},{"en":"Current farming methods are the methods farmers are using now.","zh":"「current farming methods」是農民現在正在使用的方法。"},{"en":"Current farming methods may include irrigation, spraying, fertilising and harvesting routines.","zh":"現行耕作方法可能包括灌溉、噴藥、施肥和收割流程。"},{"en":"If current methods are familiar and profitable, farmers may hesitate to replace them.","zh":"如果現行方法熟悉且有利可圖，農民可能猶豫是否取代它們。"},{"en":"The phrase refers to present practice, not future plans.","zh":"這個短語指現有做法，而不是未來計劃。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":17},{"front":"exceed expectations","meaning":"超出預期","examples":[{"en":"The results exceeded expectations.","zh":"結果超出預期。"},{"en":"To exceed expectations means to be better than people thought they would be.","zh":"「exceed expectations」意思是比人們原本預期更好。"},{"en":"A new employee may exceed expectations by solving problems quickly.","zh":"新員工可能透過快速解決問題而超出預期。"},{"en":"If a farming experiment exceeds expectations, growers may trust it more.","zh":"如果農業實驗超出預期，種植者可能更信任它。"},{"en":"The phrase is similar to “surpass expectations”.","zh":"這個短語與 “surpass expectations” 相近。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":17},{"front":"translate findings into practical projects","meaning":"把研究結果轉化為實際項目","examples":[{"en":"Research findings should be translated into practical projects.","zh":"研究結果應被轉化為實際項目。"},{"en":"To translate findings into practical projects means to turn research results into real actions or programmes.","zh":"「translate findings into practical projects」意思是把研究結果變成真實行動或計劃。"},{"en":"A hospital can translate findings into practical projects by changing how nurses check patients.","zh":"醫院可以透過改變護士檢查病人的方式，把研究結果轉化為實際項目。"},{"en":"If agricultural findings are translated into farm projects, growers can test them in real conditions.","zh":"如果農業發現被轉化為農場項目，種植者可以在真實條件下測試它們。"},{"en":"The phrase is about moving from knowledge to action.","zh":"這個短語關於從知識走向行動。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":17},{"front":"practical projects","meaning":"實際項目","examples":[{"en":"Useful research should lead to practical projects.","zh":"有用研究應導向實際項目。"},{"en":"Practical projects are real activities designed to solve problems or test ideas.","zh":"「practical projects」是為解決問題或測試想法而設計的真實活動。"},{"en":"A school garden can be a practical project for teaching science and responsibility.","zh":"學校花園可以是教授科學和責任感的實際項目。"},{"en":"If research does not lead to practical projects, it may not help the people who need it.","zh":"如果研究沒有導向實際項目，它可能幫不到需要它的人。"},{"en":"The phrase stresses real-world application.","zh":"這個短語強調現實應用。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":17},{"front":"best food in the world","meaning":"世界上最好的食物","examples":[{"en":"The question refers to the claim that the United States produces the best food in the world.","zh":"問題提到美國生產世界上最好的食物這一說法。"},{"en":"Best food in the world means food believed to be better than food from anywhere else.","zh":"「best food in the world」意思是被認為比任何其他地方食物都好的食物。"},{"en":"A country may claim it has the best food in the world to express pride in its farming or cuisine.","zh":"一個國家可能聲稱自己有世界上最好的食物，以表達對農業或飲食的自豪。"},{"en":"If someone claims a food supply is the best in the world, others may ask what evidence supports it.","zh":"如果有人聲稱某地食物供應是世界上最好的，其他人可能會問有什麼證據支持。"},{"en":"The phrase is a strong evaluative claim.","zh":"這個短語是一個強烈評價性說法。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":17},{"front":"consumers’ expectations","meaning":"消費者期望","examples":[{"en":"Consumers’ expectations influence agricultural products.","zh":"消費者期望影響農產品。"},{"en":"Consumers’ expectations are what buyers believe or demand about products.","zh":"「consumers’ expectations」是買家對產品的信念或要求。"},{"en":"Consumers’ expectations may include low prices, perfect appearance and safe ingredients.","zh":"消費者期望可能包括低價格、完美外觀和安全成分。"},{"en":"If consumers expect flawless fruit, growers may feel pressure to use more pest control.","zh":"如果消費者期望無瑕疵水果，種植者可能感到壓力要使用更多害蟲控制。"},{"en":"The phrase connects market demand with production choices.","zh":"這個短語把市場需求與生產選擇連繫起來。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":18},{"front":"influence agricultural products","meaning":"影響農產品","examples":[{"en":"Consumer expectations influence how agricultural products are grown.","zh":"消費者期望影響農產品如何種植。"},{"en":"To influence agricultural products means to affect how farm goods are produced, selected or sold.","zh":"「influence agricultural products」意思是影響農產品如何生產、挑選或出售。"},{"en":"Supermarket rules can influence agricultural products by requiring certain sizes or appearances.","zh":"超市規則可以透過要求特定尺寸或外觀來影響農產品。"},{"en":"If buyers demand chemical-free food, that demand may influence farming methods.","zh":"如果買家要求無化學品食物，該需求可能影響耕作方法。"},{"en":"The phrase shows how markets can shape agriculture.","zh":"這個短語顯示市場如何塑造農業。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":18},{"front":"agree with the views of the writer","meaning":"與作者觀點一致","examples":[{"en":"Students decide whether the statements agree with the views of the writer.","zh":"學生判斷陳述是否與作者觀點一致。"},{"en":"To agree with the views of the writer means to match what the writer thinks or argues.","zh":"「agree with the views of the writer」意思是符合作者的想法或論點。"},{"en":"In a reading test, students must separate the writer’s view from facts about other people.","zh":"在閱讀測驗中，學生必須把作者觀點與其他人的事實分開。"},{"en":"If a statement matches the writer’s opinion, it agrees with the writer’s views.","zh":"如果陳述符合作者意見，它就與作者觀點一致。"},{"en":"The phrase is used in opinion-based reading questions.","zh":"這個短語用於觀點型閱讀題。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":18},{"front":"contradict the views of the writer","meaning":"與作者觀點相矛盾","examples":[{"en":"A NO answer means the statement contradicts the writer’s views.","zh":"NO 答案表示該陳述與作者觀點相矛盾。"},{"en":"To contradict the views of the writer means to say the opposite of what the writer believes.","zh":"「contradict the views of the writer」意思是說出與作者相信內容相反的意思。"},{"en":"If the writer supports safer farming but the statement says the writer rejects it, the statement contradicts the writer’s views.","zh":"如果作者支持更安全農業，但陳述說作者反對它，該陳述就與作者觀點相矛盾。"},{"en":"Students should choose NO only when the conflict is clear.","zh":"學生只應在衝突清楚時選 NO。"},{"en":"The phrase tests whether readers can identify disagreement.","zh":"這個短語測試讀者能否辨認不一致。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":18},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"NOT GIVEN means it is impossible to say what the writer thinks.","zh":"NOT GIVEN 表示無法判斷作者怎樣想。"},{"en":"Impossible to say means there is not enough information to decide.","zh":"「impossible to say」意思是資料不足，無法決定。"},{"en":"If a passage never mentions price, it is impossible to say whether the writer thinks it is expensive.","zh":"如果文章從未提及價格，就無法判斷作者是否認為它昂貴。"},{"en":"Students should not guess when it is impossible to say from the text.","zh":"當文本無法判斷時，學生不應猜測。"},{"en":"The phrase is useful when evidence is missing.","zh":"這個短語適用於缺乏證據的情況。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":18},{"front":"generally regarded as","meaning":"普遍被視為","examples":[{"en":"The question asks whether IPM has generally been regarded as a national success.","zh":"問題問 IPM 是否普遍被視為全國性成功。"},{"en":"Generally regarded as means commonly considered or viewed in a particular way.","zh":"「generally regarded as」意思是普遍被認為或看作某種樣子。"},{"en":"The museum is generally regarded as one of the city’s best attractions.","zh":"該博物館普遍被視為城市中最好的景點之一。"},{"en":"If a policy is generally regarded as successful, many people accept that it works.","zh":"如果一項政策普遍被視為成功，很多人接受它有效。"},{"en":"The phrase describes common opinion, not necessarily proven fact.","zh":"這個短語描述普遍看法，不一定是已證明事實。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":18},{"front":"across the United States","meaning":"遍及美國","examples":[{"en":"The question asks about IPM across the United States.","zh":"問題問及遍及美國的 IPM 情況。"},{"en":"Across the United States means throughout the whole country.","zh":"「across the United States」意思是在整個美國範圍內。"},{"en":"Weather conditions differ greatly across the United States.","zh":"遍及美國各地的天氣條件差異很大。"},{"en":"If a farming method works across the United States, it succeeds in many different regions.","zh":"如果耕作方法遍及美國都有效，它就在許多不同地區成功。"},{"en":"The phrase gives a national geographical scope.","zh":"這個短語提供全國性地理範圍。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":18},{"front":"be cited as successful examples","meaning":"被列為成功例子","examples":[{"en":"Oregon farmers are cited as successful examples of IPM.","zh":"俄勒岡州農民被列為 IPM 的成功例子。"},{"en":"To be cited as successful examples means to be mentioned as cases that show success.","zh":"「be cited as successful examples」意思是被提及為顯示成功的案例。"},{"en":"A school may be cited as a successful example of improving reading scores.","zh":"一所學校可能被列為改善閱讀成績的成功例子。"},{"en":"If Oregon farmers are cited as examples, others may study their methods.","zh":"如果俄勒岡州農民被列為例子，其他人可能研究他們的方法。"},{"en":"The phrase shows public recognition of success.","zh":"這個短語顯示成功得到公開承認。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":18},{"front":"draw on scientists from","meaning":"借助來自……的科學家","examples":[{"en":"The question asks whether the IPPC draws on scientists from organisations worldwide.","zh":"問題問 IPPC 是否借助來自世界各地機構的科學家。"},{"en":"To draw on scientists from somewhere means to use their knowledge or help.","zh":"「draw on scientists from」某處，意思是使用他們的知識或幫助。"},{"en":"A hospital may draw on specialists from different departments for a difficult case.","zh":"醫院可能為疑難病例借助不同部門的專家。"},{"en":"If a centre draws on scientists from many organisations, it can access wider expertise.","zh":"如果中心借助來自許多機構的科學家，它可以取得更廣泛專業知識。"},{"en":"The phrase means making use of people’s knowledge.","zh":"這個短語意思是利用人們的知識。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":18},{"front":"organisations around the world","meaning":"世界各地的機構","examples":[{"en":"The option mentions organisations around the world.","zh":"該選項提到世界各地的機構。"},{"en":"Organisations around the world are groups or institutions located in many different countries.","zh":"「organisations around the world」是位於許多不同國家的團體或機構。"},{"en":"Environmental organisations around the world may share data about climate change.","zh":"世界各地的環境機構可能分享關於氣候變化的數據。"},{"en":"If researchers work with organisations around the world, ideas can spread faster.","zh":"如果研究人員與世界各地的機構合作，想法可以更快傳播。"},{"en":"The phrase suggests international scope.","zh":"這個短語暗示國際範圍。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":18},{"front":"experiments with straw mulch","meaning":"稻草覆蓋物實驗","examples":[{"en":"Experiments with straw mulch produced unexpected benefits.","zh":"稻草覆蓋物實驗產生了意想不到的好處。"},{"en":"Experiments with straw mulch are tests using straw as a soil covering.","zh":"「experiments with straw mulch」是使用稻草作泥土覆蓋物的測試。"},{"en":"Farmers may run experiments with straw mulch on one field before using it widely.","zh":"農民可能先在一塊田進行稻草覆蓋物實驗，再廣泛使用。"},{"en":"If such experiments reduce water use and help insects, the method becomes more attractive.","zh":"如果這類實驗減少用水並幫助昆蟲，該方法就更具吸引力。"},{"en":"The phrase refers to practical field testing.","zh":"這個短語指實際田間測試。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":18},{"front":"unexpected benefits","meaning":"意想不到的好處","examples":[{"en":"The straw mulch experiment produced unexpected benefits.","zh":"稻草覆蓋物實驗產生了意想不到的好處。"},{"en":"Unexpected benefits are good results that people did not predict.","zh":"「unexpected benefits」是人們沒有預測到的好結果。"},{"en":"A new bus route may bring unexpected benefits by helping students reach libraries more easily.","zh":"新巴士路線可能帶來意想不到的好處，幫助學生更容易到達圖書館。"},{"en":"If a farming trial produces unexpected benefits, researchers may study the reason carefully.","zh":"如果農業試驗產生意想不到的好處，研究人員可能仔細研究原因。"},{"en":"The phrase highlights positive surprise.","zh":"這個短語強調正面驚喜。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":19},{"front":"apple industry","meaning":"蘋果產業","examples":[{"en":"The question asks whether the apple industry faces strong competition from overseas.","zh":"問題問蘋果產業是否面對來自海外的強烈競爭。"},{"en":"The apple industry includes growers, packers, sellers and processors involved with apples.","zh":"「apple industry」包括與蘋果相關的種植者、包裝商、銷售者和加工商。"},{"en":"The apple industry depends on fruit quality, storage, transport and market prices.","zh":"蘋果產業依賴水果質素、儲存、運輸和市場價格。"},{"en":"If the apple industry faces cheaper imports, local producers may need to improve efficiency.","zh":"如果蘋果產業面對較便宜進口貨，本地生產者可能需要提高效率。"},{"en":"The phrase refers to apples as a business sector.","zh":"這個短語把蘋果視為一個商業部門。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":19},{"front":"strong competition from overseas","meaning":"來自海外的強烈競爭","examples":[{"en":"The option mentions strong competition from overseas.","zh":"該選項提到來自海外的強烈競爭。"},{"en":"Strong competition from overseas means serious pressure from producers or companies in other countries.","zh":"「strong competition from overseas」意思是來自其他國家生產者或公司的嚴重競爭壓力。"},{"en":"Local clothing shops may face strong competition from overseas online sellers.","zh":"本地服裝店可能面對來自海外網上賣家的強烈競爭。"},{"en":"If farms face strong overseas competition, they must control costs and maintain quality.","zh":"如果農場面對來自海外的強烈競爭，它們必須控制成本並維持質素。"},{"en":"The phrase describes an international business challenge.","zh":"這個短語描述國際商業挑戰。"}],"source":"129 - New Agriculture in Oregon, US.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 130":[{"front":"a sweet history","meaning":"甜蜜的歷史","examples":[{"en":"The title presents cacao as having a sweet history.","zh":"標題把可可呈現為擁有一段甜蜜的歷史。"},{"en":"A sweet history is a pleasant or interesting story about how something developed over time.","zh":"甜蜜的歷史是關於某物如何隨時間發展的愉快或有趣故事。"},{"en":"A family bakery may have a sweet history if three generations have made cakes there.","zh":"如果一間家庭麵包店已有三代人製作蛋糕，它可能有一段甜蜜的歷史。"},{"en":"Chocolate has a sweet history because it moved from ancient ceremonies to modern shops.","zh":"朱古力有一段甜蜜的歷史，因為它由古代儀式走進現代商店。"},{"en":"The phrase can be literal, about sweet food, or figurative, about a charming past.","zh":"這個短語可以是字面意思，關於甜食；也可以是比喻，關於迷人的過去。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":1},{"front":"think of…as…","meaning":"將……視為……","examples":[{"en":"Most people today think of chocolate as something sweet.","zh":"今天大多數人將朱古力視為甜的東西。"},{"en":"To think of something as something means to regard it in a particular way.","zh":"“Think of something as something” 指以某種方式看待某事物。"},{"en":"Many students think of grammar as rules, but it can also be a tool for clearer meaning.","zh":"許多學生將文法視為規則，但它也可以是令意思更清晰的工具。"},{"en":"If people think of cacao only as candy, they may miss its cultural history.","zh":"如果人們只將可可視為糖果，可能會錯過其文化歷史。"},{"en":"The phrase shows how people understand or label a person, object, or idea.","zh":"這個短語顯示人們如何理解或標籤某人、物件或想法。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":1},{"front":"something sweet to eat or drink","meaning":"可吃可喝的甜食","examples":[{"en":"Chocolate is now seen as something sweet to eat or drink.","zh":"朱古力現在被視為可吃可喝的甜食。"},{"en":"Something sweet to eat or drink is a food or beverage with a sweet taste.","zh":"可吃可喝的甜食是帶甜味的食物或飲品。"},{"en":"After dinner, children may ask for something sweet to eat or drink, such as pudding or hot chocolate.","zh":"晚飯後，孩子可能想要可吃可喝的甜食，例如布甸或熱朱古力。"},{"en":"If a product is sold as something sweet to eat or drink, people expect pleasure rather than medicine.","zh":"如果產品被作為可吃可喝的甜食出售，人們會期待享受，而不是藥物。"},{"en":"The phrase describes chocolate as a treat, not as an ancient ritual item.","zh":"這個短語把朱古力描述為享受品，而不是古代儀式用品。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":1},{"front":"easily found in stores","meaning":"在商店容易找到","examples":[{"en":"Chocolate can be easily found in stores around the world.","zh":"朱古力在世界各地的商店容易找到。"},{"en":"Easily found in stores means simple to buy because many shops sell it.","zh":"“Easily found in stores” 指因許多商店有售，所以容易買到。"},{"en":"Bottled water is easily found in stores in most busy train stations.","zh":"在大多數繁忙火車站，瓶裝水在商店容易找到。"},{"en":"When something is easily found in stores, people may forget that it was once rare or expensive.","zh":"當某物在商店容易找到，人們可能忘記它曾經稀有或昂貴。"},{"en":"The phrase shows that an item is common and accessible.","zh":"這個短語顯示某物常見且容易取得。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":1},{"front":"it might surprise you that","meaning":"你可能會驚訝於……","examples":[{"en":"It might surprise you that chocolate was once highly treasured.","zh":"你可能會驚訝於朱古力曾經非常珍貴。"},{"en":"It might surprise you that introduces a fact the listener probably does not expect.","zh":"“It might surprise you that” 用來引出聽者可能不預期的事實。"},{"en":"It might surprise you that some expensive spices were once used like money.","zh":"你可能會驚訝於一些昂貴香料曾經像貨幣一樣使用。"},{"en":"If a fact challenges common assumptions, a writer may begin with “it might surprise you that”.","zh":"如果某個事實挑戰常見假設，作者可能以 “it might surprise you that” 開始。"},{"en":"The phrase prepares readers for unexpected information.","zh":"這個短語讓讀者準備接收意想不到的資訊。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":1},{"front":"once highly treasured","meaning":"曾經非常珍貴","examples":[{"en":"Chocolate was once highly treasured.","zh":"朱古力曾經非常珍貴。"},{"en":"Once highly treasured means valued very much in the past, though it may be common now.","zh":"“Once highly treasured” 指某物過去非常受重視，雖然現在可能很常見。"},{"en":"Salt was once highly treasured because it helped preserve food.","zh":"鹽曾經非常珍貴，因為它有助保存食物。"},{"en":"If something was once highly treasured, its history may explain old trade routes and customs.","zh":"如果某物曾經非常珍貴，其歷史可能解釋舊貿易路線和習俗。"},{"en":"The phrase contrasts past value with present familiarity.","zh":"這個短語把過去價值與現在熟悉程度作對比。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":1},{"front":"the tasty secret of","meaning":"……的美味秘密","examples":[{"en":"The tasty secret of the cacao tree was discovered 2,000 years ago.","zh":"可可樹的美味秘密在二千年前被發現。"},{"en":"The tasty secret of something means the hidden food value or delicious use people discovered in it.","zh":"“The tasty secret of” 某物指人們在其中發現的隱藏食用價值或美味用途。"},{"en":"The tasty secret of tea leaves was learned when people found they could make a fragrant drink.","zh":"當人們發現茶葉可以製成香味飲品時，就知道了茶葉的美味秘密。"},{"en":"Once people discovered the tasty secret of cacao, they began turning its seeds into drinks.","zh":"人們一旦發現可可的美味秘密，便開始把其種子製成飲品。"},{"en":"The phrase makes a food discovery sound interesting and inviting.","zh":"這個短語令食物發現聽起來有趣而吸引。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":1},{"front":"cacao tree","meaning":"可可樹","examples":[{"en":"The tasty secret of the cacao tree was discovered in the Americas.","zh":"可可樹的美味秘密在美洲被發現。"},{"en":"A cacao tree is a tropical tree whose seeds are used to make chocolate.","zh":"可可樹是一種熱帶樹木，其種子用來製作朱古力。"},{"en":"Farmers grow cacao trees in warm, wet places near the equator.","zh":"農民在接近赤道的溫暖潮濕地方種植可可樹。"},{"en":"If cacao trees do not get enough shade and water, they may not produce good pods.","zh":"如果可可樹沒有足夠陰影和水分，可能無法產出良好莢果。"},{"en":"The phrase names the plant at the beginning of chocolate production.","zh":"這個短語指朱古力生產開端的植物。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":1},{"front":"tropical rainforests","meaning":"熱帶雨林","examples":[{"en":"Cacao was discovered in the tropical rainforests of the Americas.","zh":"可可在美洲的熱帶雨林中被發現。"},{"en":"Tropical rainforests are hot, wet forests near the equator with many plants and animals.","zh":"熱帶雨林是接近赤道、炎熱潮濕且有許多動植物的森林。"},{"en":"Many medicines and foods have origins in tropical rainforests.","zh":"許多藥物和食物都源自熱帶雨林。"},{"en":"If tropical rainforests are destroyed, plants like cacao may lose their natural habitat.","zh":"如果熱帶雨林被破壞，像可可這樣的植物可能失去自然棲息地。"},{"en":"The phrase describes the warm forest environment where cacao naturally grows.","zh":"這個短語描述可可自然生長的溫暖森林環境。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":1},{"front":"the Americas","meaning":"美洲","examples":[{"en":"The cacao tree was discovered in the Americas.","zh":"可可樹在美洲被發現。"},{"en":"The Americas refers to North America, Central America, South America, and nearby islands.","zh":"美洲指北美洲、中美洲、南美洲及附近島嶼。"},{"en":"Many ancient civilisations developed in the Americas before European contact.","zh":"許多古代文明在歐洲人接觸前已於美洲發展。"},{"en":"If a crop began in the Americas, trade later could spread it to Europe, Africa, and Asia.","zh":"如果一種作物源於美洲，後來貿易可以把它傳到歐洲、非洲和亞洲。"},{"en":"The phrase names a broad geographical region rather than one country.","zh":"這個短語指一個廣闊地理區域，而不是一個國家。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":1},{"front":"grow from…into…","meaning":"從……發展成……","examples":[{"en":"Chocolate grew from a local beverage into a global sweet.","zh":"朱古力從本地飲品發展成全球甜食。"},{"en":"To grow from one thing into another means to develop from an earlier form into a later form.","zh":"“Grow from one thing into another” 指由早期形式發展成後來形式。"},{"en":"A small tutoring class can grow from a weekend activity into a full education business.","zh":"小型補習班可以從週末活動發展成完整教育業務。"},{"en":"Chocolate grew from a bitter ceremonial drink into a sweet product sold worldwide.","zh":"朱古力從苦味儀式飲品發展成全球銷售的甜味產品。"},{"en":"The phrase shows change and development over time.","zh":"這個短語顯示隨時間變化和發展。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":1},{"front":"local Mesoamerican beverage","meaning":"中美洲地區的本地飲品","examples":[{"en":"Chocolate began as a local Mesoamerican beverage.","zh":"朱古力最初是中美洲地區的本地飲品。"},{"en":"A local Mesoamerican beverage is a drink used in the Mesoamerican region before becoming known worldwide.","zh":"中美洲地區的本地飲品是指在中美洲地區使用、後來才聞名世界的飲品。"},{"en":"The cacao drink was a local Mesoamerican beverage before Europeans tasted it.","zh":"可可飲品在歐洲人品嚐前，是中美洲地區的本地飲品。"},{"en":"When a local beverage spreads abroad, its taste and meaning may change.","zh":"當本地飲品傳到海外，其味道和意義可能改變。"},{"en":"The phrase places early chocolate in a specific cultural and geographical setting.","zh":"這個短語把早期朱古力放在特定文化和地理背景中。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":2},{"front":"global sweet","meaning":"全球甜食","examples":[{"en":"Chocolate became a global sweet.","zh":"朱古力成為全球甜食。"},{"en":"A global sweet is a sweet food enjoyed in many countries around the world.","zh":"全球甜食是在世界許多國家都受歡迎的甜味食物。"},{"en":"Ice cream has become a global sweet, though flavours differ by region.","zh":"雪糕已成為全球甜食，雖然口味因地區而異。"},{"en":"Once chocolate became a global sweet, factories and shops began selling it in many forms.","zh":"朱古力一旦成為全球甜食，工廠和商店便開始以多種形式出售它。"},{"en":"The phrase shows that a food has moved beyond its original culture.","zh":"這個短語顯示一種食物已超越其原本文化。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":2},{"front":"encompass many cultures and continents","meaning":"涵蓋多種文化和大洲","examples":[{"en":"The story of chocolate encompasses many cultures and continents.","zh":"朱古力的故事涵蓋多種文化和大洲。"},{"en":"To encompass many cultures and continents means to include people, places, and traditions from many parts of the world.","zh":"“Encompass many cultures and continents” 指包括世界許多地方的人、地區和傳統。"},{"en":"The history of tea encompasses many cultures and continents through trade and migration.","zh":"茶的歷史透過貿易和遷徙涵蓋多種文化和大洲。"},{"en":"Because chocolate spread worldwide, its story encompasses farming, empire, business, and taste.","zh":"因為朱古力傳遍世界，它的故事涵蓋農業、帝國、商業和味道。"},{"en":"The phrase shows that a topic is broad and international.","zh":"這個短語顯示題目廣泛而具國際性。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":2},{"front":"historians believe","meaning":"歷史學家相信","examples":[{"en":"Historians believe the Maya people first learned to farm cacao plants.","zh":"歷史學家相信瑪雅人最早學會種植可可植物。"},{"en":"Historians believe means experts who study the past think something is likely true.","zh":"“Historians believe” 指研究過去的專家認為某事很可能是真的。"},{"en":"Historians believe old trade routes helped spread spices across continents.","zh":"歷史學家相信古代貿易路線幫助香料傳遍各大洲。"},{"en":"If historians believe something, they usually base it on records, objects, or other evidence.","zh":"如果歷史學家相信某事，他們通常基於記錄、物件或其他證據。"},{"en":"The phrase presents a scholarly view rather than a personal guess.","zh":"這個短語呈現學術觀點，而不是個人猜測。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":2},{"front":"the Maya people","meaning":"瑪雅人","examples":[{"en":"The Maya people of Central America farmed cacao plants.","zh":"中美洲的瑪雅人種植可可植物。"},{"en":"The Maya people were an ancient civilisation in Mesoamerica with rich culture, writing, art, and farming.","zh":"瑪雅人是中美洲的一個古代文明，擁有豐富文化、文字、藝術和農業。"},{"en":"Students may learn about the Maya people when studying early American civilisations.","zh":"學生研究早期美洲文明時，可能會學到瑪雅人。"},{"en":"Because the Maya people used cacao in daily life and ceremonies, chocolate had cultural value.","zh":"因為瑪雅人在日常生活和儀式中使用可可，朱古力具有文化價值。"},{"en":"The phrase refers to a specific ancient people, not all people in Central America.","zh":"這個短語指一個特定古代民族，而不是中美洲所有人。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":2},{"front":"Central America","meaning":"中美洲","examples":[{"en":"The Maya people lived in Central America.","zh":"瑪雅人生活在中美洲。"},{"en":"Central America is the region between North America and South America.","zh":"中美洲是北美洲和南美洲之間的地區。"},{"en":"Countries in Central America have warm climates where crops such as cacao can grow.","zh":"中美洲國家氣候溫暖，可種植可可等作物。"},{"en":"If a crop began in Central America, trade could later carry it to Europe.","zh":"如果一種作物源於中美洲，貿易後來可以把它帶到歐洲。"},{"en":"The phrase identifies the geographical setting of early cacao farming.","zh":"這個短語指出早期可可種植的地理背景。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":2},{"front":"farm cacao plants","meaning":"種植可可植物","examples":[{"en":"The Maya people learned to farm cacao plants around two thousand years ago.","zh":"瑪雅人大約二千年前學會種植可可植物。"},{"en":"To farm cacao plants means to grow and care for cacao trees as an agricultural crop.","zh":"“Farm cacao plants” 指把可可樹作為農作物種植和照料。"},{"en":"Farmers need shade, water, and warm weather to farm cacao plants successfully.","zh":"農民需要陰影、水分和溫暖天氣，才能成功種植可可植物。"},{"en":"If people learn to farm cacao plants, they can produce cacao seeds more regularly.","zh":"如果人們學會種植可可植物，就能更穩定地生產可可豆。"},{"en":"The phrase describes organised cultivation, not simply finding wild trees.","zh":"這個短語描述有組織的栽培，而不只是尋找野生樹木。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":2},{"front":"around two thousand years ago","meaning":"大約二千年前","examples":[{"en":"The Maya learned to farm cacao plants around two thousand years ago.","zh":"瑪雅人大約二千年前學會種植可可植物。"},{"en":"Around two thousand years ago means approximately two millennia before the present or the time discussed.","zh":"“Around two thousand years ago” 指距今或距討論時間大約兩千年。"},{"en":"Around two thousand years ago, many societies were developing farming, trade, and cities.","zh":"大約二千年前，許多社會正在發展農業、貿易和城市。"},{"en":"If a tradition began around two thousand years ago, it has a very long history.","zh":"如果一項傳統大約二千年前開始，它就有非常悠久的歷史。"},{"en":"The phrase gives an approximate historical time, not an exact date.","zh":"這個短語給出大約歷史時間，而不是精確日期。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":2},{"front":"take cacao trees from","meaning":"從……取來可可樹","examples":[{"en":"The Maya took cacao trees from the rainforests.","zh":"瑪雅人從雨林取來可可樹。"},{"en":"To take cacao trees from a place means to remove or collect them from that place for use elsewhere.","zh":"“Take cacao trees from” 某地指從該地移走或收集可可樹，以便在其他地方使用。"},{"en":"Farmers may take young plants from a nursery and grow them in fields.","zh":"農民可能從苗圃取來幼苗，然後在田地種植。"},{"en":"By taking cacao trees from rainforests, the Maya could plant them closer to home.","zh":"透過從雨林取來可可樹，瑪雅人可以把它們種在離家較近的地方。"},{"en":"The phrase shows movement from wild nature into human cultivation.","zh":"這個短語顯示植物由野外進入人類栽培。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":2},{"front":"grow them in their gardens","meaning":"在自己的花園種植它們","examples":[{"en":"The Maya grew cacao trees in their gardens.","zh":"瑪雅人在自己的花園種植可可樹。"},{"en":"To grow them in their gardens means to plant and care for those trees near their homes.","zh":"“Grow them in their gardens” 指在家附近種植並照料那些樹。"},{"en":"A family may grow herbs in their garden so they can use fresh leaves for cooking.","zh":"家庭可能在花園種植香草，方便煮食時使用新鮮葉子。"},{"en":"If people grow cacao trees in their gardens, they can reach the plants more easily.","zh":"如果人們在自己的花園種植可可樹，就能更容易接觸這些植物。"},{"en":"The phrase suggests domestic cultivation rather than wild gathering.","zh":"這個短語暗示家庭式栽培，而不是野外採集。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":2},{"front":"cacao seeds","meaning":"可可豆；可可種子","examples":[{"en":"The Maya cooked cacao seeds before crushing them.","zh":"瑪雅人在壓碎可可豆前先烹煮它們。"},{"en":"Cacao seeds are the seeds inside cacao pods that are processed to make chocolate.","zh":"可可豆是可可莢果內的種子，經加工後用來製作朱古力。"},{"en":"Workers must clean and cook cacao seeds before turning them into chocolate products.","zh":"工人必須清潔和烘煮可可豆，才把它們製成朱古力產品。"},{"en":"If cacao seeds are damaged by insects, the quality of chocolate may fall.","zh":"如果可可豆被昆蟲損壞，朱古力品質可能下降。"},{"en":"The phrase names the part of the cacao plant most important for chocolate making.","zh":"這個短語指可可植物中對朱古力製作最重要的部分。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":2},{"front":"crush something into","meaning":"將……壓碎成……","examples":[{"en":"The Maya crushed cacao seeds into a soft paste.","zh":"瑪雅人將可可豆壓碎成軟糊狀物。"},{"en":"To crush something into another form means to press or grind it until it changes shape or texture.","zh":"“Crush something into” 另一種形態指壓或磨某物，直到其形狀或質地改變。"},{"en":"A cook may crush potatoes into a smooth mash.","zh":"廚師可能將薯仔壓碎成幼滑薯蓉。"},{"en":"When cacao seeds are crushed into paste, they become easier to mix with water or other ingredients.","zh":"當可可豆被壓碎成糊狀物，它們就更容易與水或其他材料混合。"},{"en":"The phrase describes changing a solid item by force.","zh":"這個短語描述用力量改變固體物品。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":3},{"front":"a soft paste","meaning":"軟糊狀物","examples":[{"en":"The cooked cacao seeds became a soft paste.","zh":"烘煮過的可可豆變成軟糊狀物。"},{"en":"A soft paste is a thick, smooth substance made by crushing or mixing ingredients.","zh":"軟糊狀物是透過壓碎或混合材料製成的濃稠幼滑物質。"},{"en":"Garlic can become a soft paste when it is crushed with salt.","zh":"大蒜與鹽一起壓碎後可以變成軟糊狀物。"},{"en":"If cacao seeds become a soft paste, they can be blended into a drink.","zh":"如果可可豆變成軟糊狀物，就可以混入飲品中。"},{"en":"The phrase describes texture: not dry, not liquid, but thick and smooth.","zh":"這個短語描述質地：不是乾的，也不是液體，而是濃稠幼滑。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":3},{"front":"mix something with","meaning":"將……與……混合","examples":[{"en":"The Maya mixed the paste with water and spices.","zh":"瑪雅人將糊狀物與水和香料混合。"},{"en":"To mix something with another thing means to combine them so they become one mixture.","zh":"“Mix something with” 另一物指把它們結合成一種混合物。"},{"en":"A child may mix flour with water to make dough.","zh":"孩子可能將麵粉與水混合來製作麵團。"},{"en":"If cacao paste is mixed with spices, the drink gains a stronger flavour.","zh":"如果可可糊與香料混合，飲品會有更濃味道。"},{"en":"The phrase is common in cooking, chemistry, and everyday preparation.","zh":"這個短語常見於烹飪、化學和日常準備。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":3},{"front":"flavourful spices","meaning":"味道濃郁的香料","examples":[{"en":"The Maya added flavourful spices to the chocolate drink.","zh":"瑪雅人在朱古力飲品中加入味道濃郁的香料。"},{"en":"Flavourful spices are spices with a strong and pleasant taste or smell.","zh":"味道濃郁的香料是味道或香氣強烈而令人愉快的香料。"},{"en":"Cinnamon and cloves are flavourful spices often used in desserts and hot drinks.","zh":"肉桂和丁香是常用於甜品和熱飲的味道濃郁的香料。"},{"en":"Adding flavourful spices can make a simple drink taste richer and more memorable.","zh":"加入味道濃郁的香料可以令簡單飲品味道更豐富、更令人難忘。"},{"en":"The phrase describes ingredients that improve taste.","zh":"這個短語描述改善味道的材料。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":3},{"front":"unsweetened chocolate drink","meaning":"無糖朱古力飲品","examples":[{"en":"The Maya made an unsweetened chocolate drink.","zh":"瑪雅人製作無糖朱古力飲品。"},{"en":"An unsweetened chocolate drink contains chocolate or cacao but no added sugar.","zh":"無糖朱古力飲品含有朱古力或可可，但沒有添加糖。"},{"en":"Some adults prefer an unsweetened chocolate drink because it tastes less sugary and more bitter.","zh":"一些成年人喜歡無糖朱古力飲品，因為它較不甜，味道更苦。"},{"en":"If a drink is unsweetened, people may add spices instead of sugar for flavour.","zh":"如果飲品無糖，人們可能加入香料而不是糖來增加味道。"},{"en":"The phrase contrasts ancient bitter cacao drinks with modern sweet chocolate.","zh":"這個短語把古代苦味可可飲品與現代甜朱古力作對比。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":3},{"front":"pour something back and forth","meaning":"來回倒……","examples":[{"en":"The Maya poured the chocolate drink back and forth between two containers.","zh":"瑪雅人在兩個容器之間來回倒朱古力飲品。"},{"en":"To pour something back and forth means to move liquid repeatedly from one container to another.","zh":"“Pour something back and forth” 指把液體反覆從一個容器倒到另一個容器。"},{"en":"A cook may pour tea back and forth to cool it and create bubbles.","zh":"廚師可能來回倒茶，以冷卻茶並產生氣泡。"},{"en":"Pouring a drink back and forth can mix it better and form foam on top.","zh":"來回倒飲品可以令它混合得更好，並在表面形成泡沫。"},{"en":"The phrase describes repeated movement between two places.","zh":"這個短語描述兩個地方之間的重複移動。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":3},{"front":"two containers","meaning":"兩個容器","examples":[{"en":"The drink was poured between two containers.","zh":"這種飲品在兩個容器之間被來回倒。"},{"en":"Two containers are two objects used to hold liquid, food, or materials.","zh":"兩個容器是兩件用來盛載液體、食物或材料的物件。"},{"en":"A child may pour water between two containers while learning about volume.","zh":"孩子學習容量時，可能在兩個容器之間倒水。"},{"en":"If a drink is moved between two containers, air can enter and create bubbles.","zh":"如果飲品在兩個容器之間移動，空氣可以進入並產生氣泡。"},{"en":"The phrase is simple but important for describing the chocolate-making action.","zh":"這個短語雖簡單，但對描述製作朱古力飲品的動作很重要。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":3},{"front":"a layer of bubbles","meaning":"一層氣泡","examples":[{"en":"The liquid formed a layer of bubbles.","zh":"液體形成一層氣泡。"},{"en":"A layer of bubbles is a thin surface of small air-filled circles on top of liquid.","zh":"一層氣泡是在液體表面上的薄薄一層充滿空氣的小圓泡。"},{"en":"Shaking a bottle of soap water can create a layer of bubbles.","zh":"搖晃一瓶肥皂水可以產生一層氣泡。"},{"en":"When a drink is poured repeatedly, air enters and a layer of bubbles may form.","zh":"當飲品被反覆倒來倒去，空氣進入後可能形成一層氣泡。"},{"en":"The phrase describes what appears on the surface of a liquid.","zh":"這個短語描述液體表面出現的東西。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":3},{"front":"foam","meaning":"泡沫","examples":[{"en":"The chocolate drink had foam on top.","zh":"朱古力飲品表面有泡沫。"},{"en":"Foam is a mass of small bubbles on the surface of a liquid.","zh":"泡沫是液體表面上的一團小氣泡。"},{"en":"Cappuccino often has milk foam on top.","zh":"卡布奇諾表面通常有牛奶泡沫。"},{"en":"If a drink is poured quickly, foam may form because air mixes with the liquid.","zh":"如果飲品快速倒出，空氣與液體混合後可能形成泡沫。"},{"en":"The word helps describe the texture and appearance of a drink.","zh":"這個詞有助描述飲品的質地和外觀。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":3},{"front":"an important part of","meaning":"……的重要部分","examples":[{"en":"Cacao and chocolate were an important part of Maya culture.","zh":"可可和朱古力是瑪雅文化的重要部分。"},{"en":"An important part of something is a key element that helps form it.","zh":"某事的重要部分是幫助形成它的關鍵元素。"},{"en":"Breakfast may be an important part of a child’s school day because it supports concentration.","zh":"早餐可能是孩子上學日的重要部分，因為它支持專注力。"},{"en":"If a food appears in ceremonies and daily life, it becomes an important part of culture.","zh":"如果一種食物出現在儀式和日常生活中，它就成為文化的重要部分。"},{"en":"The phrase shows that something has real value within a larger system.","zh":"這個短語顯示某物在較大系統中有真正價值。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":3},{"front":"Maya culture","meaning":"瑪雅文化","examples":[{"en":"Cacao and chocolate had a special place in Maya culture.","zh":"可可和朱古力在瑪雅文化中有特殊地位。"},{"en":"Maya culture includes the beliefs, rituals, art, writing, farming, and daily life of the Maya people.","zh":"瑪雅文化包括瑪雅人的信仰、儀式、藝術、文字、農業和日常生活。"},{"en":"Students can learn about Maya culture through buildings, art objects, and historical records.","zh":"學生可以透過建築、藝術品和歷史記錄了解瑪雅文化。"},{"en":"Because cacao appeared in ceremonies, Maya culture treated it as more than ordinary food.","zh":"因為可可出現在儀式中，瑪雅文化把它視為不只是普通食物。"},{"en":"The phrase refers to the cultural world of the Maya civilisation.","zh":"這個短語指瑪雅文明的文化世界。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":3},{"front":"images of","meaning":"……的圖像","examples":[{"en":"There are often images of cacao plants on Maya buildings.","zh":"瑪雅建築上常有可可植物的圖像。"},{"en":"Images of something are pictures, carvings, paintings, or visual representations of it.","zh":"某物的圖像是關於它的圖片、雕刻、繪畫或視覺呈現。"},{"en":"Museums may display images of old farming tools to show how people worked.","zh":"博物館可能展示舊農具的圖像，以顯示人們如何工作。"},{"en":"If images of cacao appear on buildings, they suggest cacao was culturally important.","zh":"如果可可的圖像出現在建築上，它們暗示可可具有文化重要性。"},{"en":"The phrase is useful for describing visual evidence.","zh":"這個短語適合描述視覺證據。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":4},{"front":"art objects","meaning":"藝術品","examples":[{"en":"Cacao plants appeared on Maya buildings and art objects.","zh":"可可植物出現在瑪雅建築和藝術品上。"},{"en":"Art objects are objects made or decorated for beauty, meaning, ceremony, or cultural expression.","zh":"藝術品是為美感、意義、儀式或文化表達而製作或裝飾的物件。"},{"en":"A museum may protect old art objects such as bowls, masks, and carvings.","zh":"博物館可能保護碗、面具和雕刻等古老藝術品。"},{"en":"If cacao appears on art objects, it may show that people valued it highly.","zh":"如果可可出現在藝術品上，可能顯示人們高度重視它。"},{"en":"The phrase refers to physical items with artistic or cultural value.","zh":"這個短語指具有藝術或文化價值的實物。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":4},{"front":"ruling families","meaning":"統治家族","examples":[{"en":"Ruling families drank chocolate at special ceremonies.","zh":"統治家族在特別儀式中飲用朱古力。"},{"en":"Ruling families are families that hold political power or govern a society.","zh":"統治家族是掌握政治權力或管治社會的家族。"},{"en":"In some ancient societies, ruling families controlled land, ceremonies, and trade.","zh":"在一些古代社會，統治家族控制土地、儀式和貿易。"},{"en":"If ruling families used chocolate in ceremonies, the drink likely carried status and meaning.","zh":"如果統治家族在儀式中使用朱古力，這種飲品很可能帶有地位和意義。"},{"en":"The phrase points to powerful social groups, not ordinary households.","zh":"這個短語指有權力的社會群體，而不是普通家庭。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":4},{"front":"special ceremonies","meaning":"特別儀式","examples":[{"en":"Chocolate was drunk at special ceremonies.","zh":"朱古力在特別儀式中被飲用。"},{"en":"Special ceremonies are important formal events connected with religion, family, power, or tradition.","zh":"特別儀式是與宗教、家庭、權力或傳統有關的重要正式活動。"},{"en":"Weddings and graduation days are special ceremonies in many communities.","zh":"婚禮和畢業日是許多社區中的特別儀式。"},{"en":"If a food is used at special ceremonies, it often has symbolic value.","zh":"如果一種食物用於特別儀式，它通常具有象徵價值。"},{"en":"The phrase shows that an event is more meaningful than ordinary daily activity.","zh":"這個短語顯示事件比普通日常活動更有意義。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":4},{"front":"poorer members of society","meaning":"社會中較貧窮的成員","examples":[{"en":"Poorer members of society could enjoy chocolate once in a while.","zh":"社會中較貧窮的成員偶爾也可以享用朱古力。"},{"en":"Poorer members of society are people with less money, lower status, or fewer resources than others.","zh":"社會中較貧窮的成員是指比其他人擁有較少金錢、較低地位或較少資源的人。"},{"en":"Public libraries help poorer members of society access books and computers.","zh":"公共圖書館幫助社會中較貧窮的成員使用書籍和電腦。"},{"en":"If chocolate was expensive, poorer members of society could not enjoy it every day.","zh":"如果朱古力昂貴，社會中較貧窮的成員便不能每天享用它。"},{"en":"The phrase compares people by economic position within a community.","zh":"這個短語按社區中的經濟位置比較人。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":4},{"front":"once in a while","meaning":"偶爾","examples":[{"en":"Even poorer people could enjoy the drink once in a while.","zh":"即使較貧窮的人也可以偶爾享用這種飲品。"},{"en":"Once in a while means sometimes, but not often.","zh":"“Once in a while” 指有時，但不是經常。"},{"en":"A busy parent may eat out once in a while when there is no time to cook.","zh":"忙碌家長沒時間煮飯時，可能偶爾外出用餐。"},{"en":"If a treat is expensive, people may buy it only once in a while.","zh":"如果一種享受品昂貴，人們可能只會偶爾購買。"},{"en":"The phrase describes something occasional rather than regular.","zh":"這個短語描述偶然發生，而不是定期發生。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":4},{"front":"marriage ceremonies","meaning":"婚禮儀式","examples":[{"en":"Cacao seeds were used in marriage ceremonies.","zh":"可可豆被用於婚禮儀式。"},{"en":"Marriage ceremonies are formal events in which two people become husband and wife or partners.","zh":"婚禮儀式是兩人成為夫妻或伴侶的正式活動。"},{"en":"Rings, vows, and family blessings may appear in marriage ceremonies.","zh":"戒指、誓言和家人祝福可能出現在婚禮儀式中。"},{"en":"If cacao seeds were used in marriage ceremonies, they symbolised something important about union.","zh":"如果可可豆被用於婚禮儀式，它們象徵關於結合的重要意義。"},{"en":"The phrase refers to weddings and related ritual events.","zh":"這個短語指婚禮及相關儀式活動。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":4},{"front":"a sign of","meaning":"……的象徵","examples":[{"en":"Cacao seeds were used as a sign of union.","zh":"可可豆被用作結合的象徵。"},{"en":"A sign of something is an object, action, or event that shows or symbolises it.","zh":"某事的象徵是顯示或代表它的物件、行動或事件。"},{"en":"A thank-you card is a sign of gratitude.","zh":"感謝卡是感激的象徵。"},{"en":"If people exchange cacao seeds at a wedding, the seeds may be a sign of unity.","zh":"如果人們在婚禮交換可可豆，這些種子可能是團結的象徵。"},{"en":"The phrase connects a visible thing with a deeper meaning.","zh":"這個短語把看得見的事物與更深層意思連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":4},{"front":"the union between","meaning":"……之間的結合","examples":[{"en":"The seeds symbolised the union between a husband and a wife.","zh":"這些種子象徵丈夫與妻子之間的結合。"},{"en":"The union between two people or groups is their joining together in a relationship, agreement, or partnership.","zh":"兩個人或群體之間的結合是他們在關係、協議或夥伴關係中的聯合。"},{"en":"A wedding celebrates the union between two families as well as two people.","zh":"婚禮慶祝兩個人之間的結合，也慶祝兩個家庭之間的結合。"},{"en":"If an object symbolises the union between partners, it represents commitment and connection.","zh":"如果一件物件象徵伴侶之間的結合，它代表承諾和連繫。"},{"en":"The phrase is often used for marriage, cooperation, or formal joining.","zh":"這個短語常用於婚姻、合作或正式聯合。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":4},{"front":"present-day Mexico","meaning":"現今的墨西哥","examples":[{"en":"The Aztec culture existed in present-day Mexico.","zh":"阿茲特克文化存在於現今的墨西哥。"},{"en":"Present-day Mexico means the area that is now the modern country of Mexico.","zh":"現今的墨西哥指現在屬於現代墨西哥國家的地區。"},{"en":"Ancient cities may have stood in places that are now part of present-day Mexico.","zh":"古代城市可能曾位於現在屬於現今墨西哥的地方。"},{"en":"If a text says “present-day Mexico,” it connects an ancient place with a modern map.","zh":"如果文本說「現今的墨西哥」，它把古代地方與現代地圖連繫起來。"},{"en":"The phrase helps readers locate history using today’s geography.","zh":"這個短語幫助讀者用今天的地理定位歷史。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":4},{"front":"prize chocolate","meaning":"珍視朱古力","examples":[{"en":"The Aztec culture also prized chocolate.","zh":"阿茲特克文化也珍視朱古力。"},{"en":"To prize chocolate means to value it highly and treat it as special.","zh":"“Prize chocolate” 指高度重視朱古力，並把它視為特別之物。"},{"en":"Some families prize old recipes because they connect them with grandparents.","zh":"一些家庭珍視舊食譜，因為它們把家庭與祖父母連繫起來。"},{"en":"If a society prizes chocolate, it may use it in ceremonies or as a luxury drink.","zh":"如果一個社會珍視朱古力，可能在儀式中使用它，或把它作為奢侈飲品。"},{"en":"The phrase shows strong appreciation, not ordinary liking.","zh":"這個短語顯示強烈欣賞，而不是普通喜歡。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":4},{"front":"could not grow in","meaning":"不能在……生長","examples":[{"en":"Cacao plants could not grow in the area where the Aztecs lived.","zh":"可可植物不能在阿茲特克人居住的地區生長。"},{"en":"Could not grow in a place means the conditions there were unsuitable for the plant to live or produce well.","zh":"“Could not grow in” 某地指該地條件不適合植物生長或良好產出。"},{"en":"Rice cannot grow well in very dry land without enough water.","zh":"沒有足夠水分時，水稻不能在非常乾燥的土地上好好生長。"},{"en":"If cacao could not grow in the Aztec area, the Aztecs needed trade to obtain it.","zh":"如果可可不能在阿茲特克地區生長，阿茲特克人就需要透過貿易取得它。"},{"en":"The phrase explains why people had to get a crop from elsewhere.","zh":"這個短語解釋為何人們必須從其他地方取得作物。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":5},{"front":"trade to get","meaning":"透過貿易取得","examples":[{"en":"The Aztecs traded to get cacao.","zh":"阿茲特克人透過貿易取得可可。"},{"en":"To trade to get something means to exchange goods, money, or services in order to obtain it.","zh":"“Trade to get” 某物指交換商品、金錢或服務以取得它。"},{"en":"A farmer may trade vegetables to get tools from a neighbour.","zh":"農民可能用蔬菜交換鄰居的工具。"},{"en":"If a region cannot grow cacao, people may trade to get cacao from warmer areas.","zh":"如果某地區不能種植可可，人們可能從較暖地區透過貿易取得可可。"},{"en":"The phrase shows exchange as a way to obtain scarce goods.","zh":"這個短語顯示交換是取得稀缺物品的方法。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":5},{"front":"as a form of money","meaning":"作為一種貨幣","examples":[{"en":"The Aztecs used cacao seeds as a form of money.","zh":"阿茲特克人把可可豆作為一種貨幣使用。"},{"en":"As a form of money means used like currency to buy, sell, or pay for things.","zh":"“As a form of money” 指像貨幣一樣用於購買、出售或付款。"},{"en":"In some places, shells were once used as a form of money.","zh":"在一些地方，貝殼曾被作為一種貨幣使用。"},{"en":"If cacao seeds were used as money, they must have been valuable and trusted.","zh":"如果可可豆被用作貨幣，它們必定有價值並被信任。"},{"en":"The phrase shows that an object had economic value, not only food value.","zh":"這個短語顯示物件具有經濟價值，而不只是食物價值。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":5},{"front":"pay taxes","meaning":"交稅","examples":[{"en":"The Aztecs used cacao seeds to pay taxes.","zh":"阿茲特克人使用可可豆交稅。"},{"en":"To pay taxes means to give money or goods to a government or ruler as required by law or authority.","zh":"“Pay taxes” 指根據法律或權威要求，把金錢或物品交給政府或統治者。"},{"en":"Workers pay taxes from their salaries to support public services.","zh":"工人從薪金中交稅，以支持公共服務。"},{"en":"If cacao seeds were used to pay taxes, rulers accepted them as valuable payment.","zh":"如果可可豆被用來交稅，統治者就接受它們作為有價值的付款。"},{"en":"The phrase describes a formal duty to the state or ruler.","zh":"這個短語描述對國家或統治者的正式義務。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":5},{"front":"play a special role in","meaning":"在……中扮演特殊角色","examples":[{"en":"Chocolate played a special role in royal and religious events.","zh":"朱古力在王室和宗教活動中扮演特殊角色。"},{"en":"To play a special role in something means to have an important or unusual function in it.","zh":"“Play a special role in” 某事指在其中具有重要或不尋常功能。"},{"en":"Music plays a special role in weddings because it creates emotion and memory.","zh":"音樂在婚禮中扮演特殊角色，因為它創造情感和回憶。"},{"en":"If chocolate played a special role in ceremonies, it was more than an everyday drink.","zh":"如果朱古力在儀式中扮演特殊角色，它就不只是日常飲品。"},{"en":"The phrase highlights importance within a particular event or system.","zh":"這個短語強調在特定事件或系統中的重要性。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":5},{"front":"royal and religious events","meaning":"王室和宗教活動","examples":[{"en":"Chocolate was important in royal and religious events.","zh":"朱古力在王室和宗教活動中很重要。"},{"en":"Royal and religious events are ceremonies connected with rulers, gods, worship, or sacred traditions.","zh":"王室和宗教活動是與統治者、神明、崇拜或神聖傳統有關的儀式。"},{"en":"Coronations and temple ceremonies are examples of royal and religious events.","zh":"加冕典禮和神廟儀式是王室和宗教活動的例子。"},{"en":"If a drink appears in royal and religious events, it likely carries power and symbolism.","zh":"如果一種飲品出現在王室和宗教活動中，它很可能帶有權力和象徵意義。"},{"en":"The phrase combines political status with spiritual meaning.","zh":"這個短語結合政治地位與精神意義。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":5},{"front":"present offerings to","meaning":"向……獻上祭品","examples":[{"en":"Priests presented cacao seeds and offerings to the gods.","zh":"祭司向神明獻上可可豆和祭品。"},{"en":"To present offerings to someone means to give gifts or ritual items as respect, worship, or thanks.","zh":"“Present offerings to” 某人或神明指為表示尊敬、崇拜或感謝而獻上禮物或儀式用品。"},{"en":"People may present flowers to ancestors during a memorial ceremony.","zh":"人們可能在紀念儀式中向祖先獻花。"},{"en":"If priests present offerings to gods, the items are part of sacred practice.","zh":"如果祭司向神明獻上祭品，這些物品就是神聖實踐的一部分。"},{"en":"The phrase is often used in religious or ceremonial contexts.","zh":"這個短語常用於宗教或儀式語境。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":5},{"front":"the gods","meaning":"神明","examples":[{"en":"Priests served chocolate drinks during ceremonies for the gods.","zh":"祭司在為神明舉行的儀式中供應朱古力飲品。"},{"en":"The gods are divine beings worshipped in a religion or belief system.","zh":"神明是在宗教或信仰系統中被崇拜的神聖存在。"},{"en":"Ancient societies often told stories about the gods to explain nature and human life.","zh":"古代社會常透過關於神明的故事來解釋自然和人類生活。"},{"en":"If food was offered to the gods, it carried religious meaning.","zh":"如果食物被獻給神明，它就帶有宗教意義。"},{"en":"The phrase refers to sacred beings rather than human rulers.","zh":"這個短語指神聖存在，而不是人類統治者。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":5},{"front":"sacred ceremonies","meaning":"神聖儀式","examples":[{"en":"Chocolate drinks were served during sacred ceremonies.","zh":"朱古力飲品在神聖儀式中供應。"},{"en":"Sacred ceremonies are religious or holy events treated with deep respect.","zh":"神聖儀式是被深切尊重的宗教或神聖活動。"},{"en":"A temple ritual may be a sacred ceremony for the local community.","zh":"神廟儀式可能是本地社區的神聖儀式。"},{"en":"If chocolate was served during sacred ceremonies, it had spiritual importance.","zh":"如果朱古力在神聖儀式中供應，它就具有精神重要性。"},{"en":"The phrase shows that an event is connected with religion or holiness.","zh":"這個短語顯示事件與宗教或神聖性有關。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":5},{"front":"the very wealthy","meaning":"極富有的人","examples":[{"en":"Only the very wealthy in Aztec society could afford chocolate.","zh":"阿茲特克社會中只有極富有的人負擔得起朱古力。"},{"en":"The very wealthy are people with much more money and resources than most others.","zh":"極富有的人是比大多數人擁有更多金錢和資源的人。"},{"en":"The very wealthy may buy rare art that ordinary people cannot afford.","zh":"極富有的人可能購買普通人負擔不起的稀有藝術品。"},{"en":"If only the very wealthy could drink chocolate, it was a luxury item.","zh":"如果只有極富有的人能喝朱古力，它就是奢侈品。"},{"en":"The phrase refers to the richest group in society.","zh":"這個短語指社會中最富有的群體。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":5},{"front":"could afford to","meaning":"負擔得起","examples":[{"en":"Only the very wealthy could afford to drink chocolate.","zh":"只有極富有的人負擔得起喝朱古力。"},{"en":"Could afford to do something means had enough money or resources to do it.","zh":"“Could afford to” 做某事指有足夠金錢或資源去做它。"},{"en":"A family may not be able to afford to move house if rent is too high.","zh":"如果租金太高，家庭可能負擔不起搬屋。"},{"en":"If only rich people could afford to buy a product, the product was not for ordinary consumers.","zh":"如果只有富人負擔得起購買某產品，該產品就不是給普通消費者的。"},{"en":"The phrase connects ability with cost.","zh":"這個短語把能力與成本連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":5},{"front":"so valuable","meaning":"如此珍貴","examples":[{"en":"Cacao was so valuable that only wealthy people could drink chocolate.","zh":"可可是如此珍貴，以致只有富人能喝朱古力。"},{"en":"So valuable means extremely valuable, often leading to a clear result.","zh":"“So valuable” 指極為珍貴，通常會帶來明顯結果。"},{"en":"The old photograph was so valuable to the family that they kept it in a safe box.","zh":"那張舊照片對家庭如此珍貴，以致他們把它放在保險盒中。"},{"en":"If cacao was so valuable, people might use it as money or offer it in ceremonies.","zh":"如果可可如此珍貴，人們可能把它用作貨幣或在儀式中獻上。"},{"en":"The phrase often appears in the pattern “so…that…”.","zh":"這個短語常出現在 “so…that…” 句式中。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":6},{"front":"the Aztec ruler","meaning":"阿茲特克統治者","examples":[{"en":"The Aztec ruler Montezuma was believed to drink many cups of chocolate.","zh":"阿茲特克統治者蒙特祖馬被認為喝了很多杯朱古力。"},{"en":"The Aztec ruler was the leader who governed the Aztec empire.","zh":"阿茲特克統治者是管治阿茲特克帝國的領袖。"},{"en":"Students may learn about the Aztec ruler when studying the Spanish conquest of Mexico.","zh":"學生研究西班牙征服墨西哥時，可能會學到阿茲特克統治者。"},{"en":"If the Aztec ruler drank chocolate often, the drink likely had high status.","zh":"如果阿茲特克統治者經常喝朱古力，這種飲品很可能具有高地位。"},{"en":"The phrase identifies a powerful historical leader in Aztec society.","zh":"這個短語指出阿茲特克社會中的有權勢歷史領袖。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":6},{"front":"be believed to","meaning":"被認為","examples":[{"en":"Montezuma was believed to drink fifty cups of chocolate every day.","zh":"蒙特祖馬被認為每天喝五十杯朱古力。"},{"en":"Be believed to do something means people think or say that someone did it, though it may not be fully proven.","zh":"“Be believed to” 做某事指人們認為或說某人做了它，雖然未必完全證實。"},{"en":"The old building is believed to be more than two hundred years old.","zh":"這座舊建築被認為有超過二百年歷史。"},{"en":"If a ruler is believed to drink chocolate daily, the story may show how valued chocolate was.","zh":"如果一名統治者被認為每天喝朱古力，這個故事可能顯示朱古力有多受重視。"},{"en":"The phrase is useful when reporting traditional claims or historical beliefs.","zh":"這個短語適合報告傳統說法或歷史看法。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":6},{"front":"the word for","meaning":"表示……的詞","examples":[{"en":"Some experts believe the word for chocolate came from an Aztec word.","zh":"一些專家相信表示朱古力的詞來自一個阿茲特克詞語。"},{"en":"The word for something means the term used to name that thing in a language.","zh":"“The word for” 某物指某種語言中用來命名該事物的詞語。"},{"en":"The word for “school” is different in English, Italian, and Japanese.","zh":"表示「學校」的詞在英語、意大利語和日語中不同。"},{"en":"If experts study the word for chocolate, they can learn about language contact and history.","zh":"如果專家研究表示朱古力的詞，就能了解語言接觸和歷史。"},{"en":"The phrase is useful when discussing vocabulary origins.","zh":"這個短語適合討論詞彙來源。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":6},{"front":"come from","meaning":"來自","examples":[{"en":"The word for chocolate may have come from the Aztec word “xocolatl.”","zh":"表示朱古力的詞可能來自阿茲特克詞語 “xocolatl”。"},{"en":"To come from something means to originate from it.","zh":"“Come from” 某事物指源自它。"},{"en":"Many English words come from French, Latin, or Greek.","zh":"許多英語詞來自法語、拉丁語或希臘語。"},{"en":"If a food name comes from an ancient language, it may carry traces of cultural history.","zh":"如果食物名稱來自古代語言，它可能帶有文化歷史痕跡。"},{"en":"The phrase is used for origins of words, people, products, and ideas.","zh":"這個短語用於詞語、人物、產品和想法的來源。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":6},{"front":"bitter water","meaning":"苦水","examples":[{"en":"The word “xocolatl” means “bitter water.”","zh":"“Xocolatl” 這個詞意思是「苦水」。"},{"en":"Bitter water refers to a drink that tastes sharp or unsweetened rather than sugary.","zh":"苦水指味道苦澀或無糖，而不是甜的飲品。"},{"en":"Unsweetened medicine can taste like bitter water to a child.","zh":"對孩子來說，無糖藥水可能嚐起來像苦水。"},{"en":"The name “bitter water” reminds us that ancient chocolate was not sweet like modern chocolate.","zh":"「苦水」這個名稱提醒我們，古代朱古力不像現代朱古力那樣甜。"},{"en":"The phrase describes taste and helps explain the original drink.","zh":"這個短語描述味道，並幫助解釋原本的飲品。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":6},{"front":"be created by","meaning":"由……創造出來","examples":[{"en":"The word “chocolate” may have been created by combining different words.","zh":"“Chocolate” 這個詞可能是由組合不同詞語創造出來的。"},{"en":"To be created by something means to be made through that method or cause.","zh":"“Be created by” 某事指透過該方法或原因被製造出來。"},{"en":"A new recipe can be created by mixing two family dishes.","zh":"新食譜可以由混合兩道家庭菜式創造出來。"},{"en":"If a word is created by combining older words, it may show contact between languages.","zh":"如果一個詞由組合較舊詞語創造出來，它可能顯示語言之間的接觸。"},{"en":"The phrase explains how something came into existence.","zh":"這個短語解釋某物如何出現。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":6},{"front":"combine words","meaning":"組合詞語","examples":[{"en":"Some experts believe “chocolate” was created by combining Mayan and Nahuatl words.","zh":"一些專家相信 “chocolate” 是透過組合瑪雅語和納瓦特爾語詞語創造出來的。"},{"en":"To combine words means to join two or more words or word parts together.","zh":"“Combine words” 指把兩個或以上詞語或詞語部分連在一起。"},{"en":"Children sometimes combine words when they invent names for games.","zh":"孩子為遊戲創作名稱時，有時會組合詞語。"},{"en":"If languages meet through trade, speakers may combine words from both sides.","zh":"如果語言透過貿易相遇，說話者可能組合雙方的詞語。"},{"en":"The phrase is useful for explaining how new vocabulary can form.","zh":"這個短語適合解釋新詞彙如何形成。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":6},{"front":"Mayan and Nahuatl words","meaning":"瑪雅語和納瓦特爾語詞語","examples":[{"en":"The word “chocolate” may combine Mayan and Nahuatl words.","zh":"“Chocolate” 這個詞可能結合了瑪雅語和納瓦特爾語詞語。"},{"en":"Mayan and Nahuatl words are words from languages connected with ancient Mesoamerican peoples.","zh":"瑪雅語和納瓦特爾語詞語是與古代中美洲民族有關的語言詞語。"},{"en":"Food names sometimes preserve Mayan and Nahuatl words in modern languages.","zh":"食物名稱有時在現代語言中保留瑪雅語和納瓦特爾語詞語。"},{"en":"If “chocolate” combines Mayan and Nahuatl words, the word itself reflects cultural contact.","zh":"如果 “chocolate” 結合了瑪雅語和納瓦特爾語詞語，這個詞本身就反映文化接觸。"},{"en":"The phrase identifies two language sources in the history of chocolate.","zh":"這個短語指出朱古力歷史中的兩個語言來源。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":6},{"front":"explorer","meaning":"探險家","examples":[{"en":"Christopher Columbus was an explorer who brought cacao seeds to Spain.","zh":"哥倫布是一名把可可豆帶到西班牙的探險家。"},{"en":"An explorer is someone who travels to unfamiliar places to learn, trade, map, or claim new lands.","zh":"探險家是前往陌生地方學習、貿易、繪圖或宣稱新土地的人。"},{"en":"An explorer may record plants, animals, and people encountered on a journey.","zh":"探險家可能記錄旅途中遇到的植物、動物和人民。"},{"en":"When explorers brought goods home, those goods could become known in new markets.","zh":"當探險家把貨品帶回本國，那些貨品可能在新市場中為人所知。"},{"en":"The word is often used in historical travel and discovery contexts.","zh":"這個詞常用於歷史旅行和發現語境。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":6},{"front":"bring something to","meaning":"將……帶到……","examples":[{"en":"Christopher Columbus brought cacao seeds to Spain.","zh":"哥倫布將可可豆帶到西班牙。"},{"en":"To bring something to a place means to carry or introduce it there.","zh":"“Bring something to” 某地指把某物帶到或引入該地。"},{"en":"A student may bring homemade snacks to school for a class party.","zh":"學生可能將自製小食帶到學校參加班會。"},{"en":"If traders bring a new food to another country, local tastes may change over time.","zh":"如果商人將新食物帶到另一個國家，本地口味可能隨時間改變。"},{"en":"The phrase describes movement of objects, ideas, or customs into a place.","zh":"這個短語描述物件、想法或習俗進入某地。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":6},{"front":"after his trip to","meaning":"在前往……的旅程後","examples":[{"en":"Columbus brought cacao seeds to Spain after his trip to Central America.","zh":"哥倫布在前往中美洲的旅程後，把可可豆帶到西班牙。"},{"en":"After his trip to a place means following his journey there.","zh":"“After his trip to” 某地指在他前往該地的旅程之後。"},{"en":"After his trip to Japan, the student became interested in Japanese food and language.","zh":"學生在前往日本的旅程後，開始對日本食物和語言感興趣。"},{"en":"If someone brings back seeds after a trip, the plants may later spread to new places.","zh":"如果某人在旅程後帶回種子，植物後來可能傳到新地方。"},{"en":"The phrase connects a journey with what happened afterwards.","zh":"這個短語把旅程與其後發生的事連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":7},{"front":"understand that","meaning":"明白","examples":[{"en":"Hernando Cortés understood that chocolate could be valuable.","zh":"Hernando Cortés 明白朱古力可能有價值。"},{"en":"To understand that something is true means to realise or recognise it.","zh":"“Understand that” 某事為真指意識到或認清它。"},{"en":"A shop owner may understand that good service brings customers back.","zh":"店主可能明白良好服務會令顧客再次光顧。"},{"en":"If Cortés understood that chocolate could be valuable, he saw its business potential.","zh":"如果 Cortés 明白朱古力可能有價值，他就看見其商業潛力。"},{"en":"The phrase shows awareness of a fact or opportunity.","zh":"這個短語顯示對事實或機會的認識。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":7},{"front":"valuable investment","meaning":"有價值的投資","examples":[{"en":"Cortés understood that chocolate could be a valuable investment.","zh":"Cortés 明白朱古力可能是一項有價值的投資。"},{"en":"A valuable investment is something worth putting money, time, or effort into because it may bring future benefit.","zh":"有價值的投資是值得投入金錢、時間或努力，因為它可能帶來未來好處的事物。"},{"en":"Good education can be a valuable investment for a young person.","zh":"良好教育可以是年輕人的有價值投資。"},{"en":"If chocolate became popular in Spain, cacao supplies would become a valuable investment.","zh":"如果朱古力在西班牙變得受歡迎，可可供應就會成為有價值的投資。"},{"en":"The phrase links present effort with future gain.","zh":"這個短語把當前投入與未來收益連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":7},{"front":"arrive in","meaning":"抵達","examples":[{"en":"Cortés arrived in present-day Mexico in 1519.","zh":"Cortés 於1519年抵達現今的墨西哥。"},{"en":"To arrive in a place means to reach that country, city, or region.","zh":"“Arrive in” 某地指到達該國家、城市或地區。"},{"en":"Tourists may arrive in a new city late at night and need clear transport signs.","zh":"遊客可能深夜抵達新城市，並需要清晰交通標誌。"},{"en":"When Europeans arrived in the Americas, many goods and customs began to move between continents.","zh":"當歐洲人抵達美洲，許多貨品和習俗開始在各大洲之間流動。"},{"en":"The phrase is used for reaching larger places such as countries and cities.","zh":"這個短語用於到達國家和城市等較大地方。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":7},{"front":"become popular with","meaning":"受……歡迎","examples":[{"en":"Cortés believed the chocolate drink would become popular with Spaniards.","zh":"Cortés 相信朱古力飲品會受西班牙人歡迎。"},{"en":"To become popular with a group means to be liked or widely used by that group.","zh":"“Become popular with” 某群體指受到該群體喜愛或廣泛使用。"},{"en":"Bubble tea became popular with teenagers because it was sweet and customisable.","zh":"珍珠奶茶因為甜且可自訂，變得受青少年歡迎。"},{"en":"If chocolate became popular with Spaniards, demand for cacao would increase.","zh":"如果朱古力受西班牙人歡迎，對可可的需求就會增加。"},{"en":"The phrase shows a change from unfamiliar to well-liked.","zh":"這個短語顯示由陌生變為受喜愛。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":7},{"front":"Spaniards","meaning":"西班牙人","examples":[{"en":"Cortés thought Spaniards would enjoy chocolate.","zh":"Cortés 認為西班牙人會喜歡朱古力。"},{"en":"Spaniards are people from Spain.","zh":"西班牙人是來自西班牙的人。"},{"en":"Spaniards brought some foods and customs from the Americas back to Europe.","zh":"西班牙人把一些來自美洲的食物和習俗帶回歐洲。"},{"en":"If Spaniards enjoyed chocolate, Spanish demand could help spread cacao trade.","zh":"如果西班牙人喜歡朱古力，西班牙需求可以幫助可可貿易擴散。"},{"en":"The word identifies nationality, not language ability alone.","zh":"這個詞指出國籍，而不只是語言能力。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":7},{"front":"Spanish soldiers","meaning":"西班牙士兵","examples":[{"en":"Spanish soldiers defeated the Aztec empire.","zh":"西班牙士兵擊敗了阿茲特克帝國。"},{"en":"Spanish soldiers were soldiers from Spain or serving Spanish power.","zh":"西班牙士兵是來自西班牙或服務於西班牙權力的士兵。"},{"en":"Spanish soldiers travelled with explorers and helped expand Spanish control.","zh":"西班牙士兵與探險家同行，並幫助擴張西班牙控制。"},{"en":"If Spanish soldiers defeated the Aztec empire, Spanish control over cacao supplies increased.","zh":"如果西班牙士兵擊敗阿茲特克帝國，西班牙對可可供應的控制就增加。"},{"en":"The phrase refers to military forces linked to Spain.","zh":"這個短語指與西班牙有關的軍事力量。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":7},{"front":"defeat the Aztec empire","meaning":"擊敗阿茲特克帝國","examples":[{"en":"The Spanish soldiers defeated the Aztec empire.","zh":"西班牙士兵擊敗阿茲特克帝國。"},{"en":"To defeat the Aztec empire means to win against and bring down the Aztec political power.","zh":"“Defeat the Aztec empire” 指戰勝並推翻阿茲特克政治權力。"},{"en":"In history lessons, students may study how armies defeat empires through war and alliances.","zh":"在歷史課中，學生可能研究軍隊如何透過戰爭和聯盟擊敗帝國。"},{"en":"After the Spanish defeated the Aztec empire, they gained access to cacao supplies.","zh":"西班牙擊敗阿茲特克帝國後，取得了可可供應。"},{"en":"The phrase describes a major historical conquest.","zh":"這個短語描述重大歷史征服。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":7},{"front":"be able to seize","meaning":"能夠奪取","examples":[{"en":"The Spanish were able to seize the supplies of cacao.","zh":"西班牙人能夠奪取可可供應。"},{"en":"To be able to seize something means to have the power or chance to take control of it, often by force.","zh":"“Be able to seize” 某物指有能力或機會控制它，通常是透過武力。"},{"en":"Police may be able to seize illegal goods during an investigation.","zh":"警方在調查期間可能能夠奪取非法物品。"},{"en":"If an army defeats a city, it may be able to seize food, weapons, and valuable goods.","zh":"如果軍隊擊敗一座城市，可能能夠奪取食物、武器和貴重物品。"},{"en":"The phrase suggests taking control, not politely receiving.","zh":"這個短語暗示取得控制，而不是禮貌收取。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":7},{"front":"supplies of cacao","meaning":"可可供應","examples":[{"en":"The Spanish seized the supplies of cacao.","zh":"西班牙人奪取了可可供應。"},{"en":"Supplies of cacao are the available amounts of cacao seeds or products.","zh":"可可供應是可用的可可豆或可可產品數量。"},{"en":"A chocolate factory needs steady supplies of cacao to keep producing bars.","zh":"朱古力工廠需要穩定可可供應，才能持續生產朱古力條。"},{"en":"If supplies of cacao are controlled by one power, prices and trade can change.","zh":"如果可可供應由某一權力控制，價格和貿易可能改變。"},{"en":"The phrase focuses on quantity available for use or trade.","zh":"這個短語強調可用於使用或貿易的數量。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":7},{"front":"send them home","meaning":"將它們送回本國","examples":[{"en":"The Spanish seized cacao supplies and sent them home.","zh":"西班牙人奪取可可供應並將它們送回本國。"},{"en":"To send them home means to send those goods back to one’s own country.","zh":"“Send them home” 指把那些貨品送回自己的國家。"},{"en":"A traveller may buy gifts abroad and send them home by post.","zh":"旅客可能在外國購買禮物，並用郵寄方式將它們送回本國。"},{"en":"When Spain sent cacao home, people in Spain could learn to make chocolate drinks.","zh":"當西班牙把可可送回本國，西班牙人便可以學習製作朱古力飲品。"},{"en":"The phrase describes moving goods back to the sender’s homeland.","zh":"這個短語描述把貨品送回發送者的祖國。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":7},{"front":"begin planting","meaning":"開始種植","examples":[{"en":"Spain later began planting cacao in its colonies.","zh":"西班牙後來開始在其殖民地種植可可。"},{"en":"To begin planting a crop means to start growing it deliberately.","zh":"“Begin planting” 某作物指開始有意識地種植它。"},{"en":"A school garden may begin planting vegetables in spring.","zh":"學校花園可能在春天開始種植蔬菜。"},{"en":"If Spain began planting cacao in colonies, it could produce more cacao for European demand.","zh":"如果西班牙開始在殖民地種植可可，就能為歐洲需求生產更多可可。"},{"en":"The phrase marks the start of organised cultivation.","zh":"這個短語標誌有組織栽培的開始。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":8},{"front":"colonies in the Americas","meaning":"在美洲的殖民地","examples":[{"en":"Spain planted cacao in its colonies in the Americas.","zh":"西班牙在美洲的殖民地種植可可。"},{"en":"Colonies in the Americas were territories in the Americas controlled by European powers.","zh":"在美洲的殖民地是由歐洲強權控制的美洲領土。"},{"en":"European countries used colonies in the Americas to produce crops, minerals, and trade goods.","zh":"歐洲國家利用在美洲的殖民地生產作物、礦物和貿易商品。"},{"en":"If cacao was planted in colonies in the Americas, colonial labour and land became part of chocolate history.","zh":"如果可可種植於美洲的殖民地，殖民勞動和土地就成為朱古力歷史的一部分。"},{"en":"The phrase connects agriculture with empire and geography.","zh":"這個短語把農業與帝國和地理連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":8},{"front":"in order to satisfy","meaning":"為了滿足","examples":[{"en":"Spain planted cacao in order to satisfy the demand for chocolate.","zh":"西班牙種植可可，為了滿足對朱古力的需求。"},{"en":"In order to satisfy something means for the purpose of meeting a need, desire, or requirement.","zh":"“In order to satisfy” 某事指為了滿足需要、願望或要求。"},{"en":"A shop may hire more staff in order to satisfy rising customer demand.","zh":"商店可能聘請更多員工，為了滿足上升的顧客需求。"},{"en":"If demand for chocolate grew, Spain needed more cacao in order to satisfy it.","zh":"如果對朱古力的需求增長，西班牙就需要更多可可來滿足它。"},{"en":"The phrase clearly shows purpose.","zh":"這個短語清楚顯示目的。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":8},{"front":"large demand for","meaning":"對……的大量需求","examples":[{"en":"There was a large demand for chocolate in Spain.","zh":"西班牙對朱古力有大量需求。"},{"en":"A large demand for something means many people want to buy or use it.","zh":"“A large demand for” 某物指很多人想購買或使用它。"},{"en":"There is often a large demand for umbrellas during the rainy season.","zh":"雨季期間，人們通常對雨傘有大量需求。"},{"en":"If there is a large demand for chocolate, farmers and traders may produce more cacao.","zh":"如果對朱古力有大量需求，農民和商人可能生產更多可可。"},{"en":"The phrase connects popularity with market need.","zh":"這個短語把受歡迎程度與市場需要連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":8},{"front":"wealthy people of Spain","meaning":"西班牙富人","examples":[{"en":"The wealthy people of Spain first enjoyed sweetened chocolate.","zh":"西班牙富人最先享用加糖朱古力。"},{"en":"The wealthy people of Spain were rich Spaniards who could afford rare or expensive goods.","zh":"西班牙富人是負擔得起稀有或昂貴商品的富有西班牙人。"},{"en":"Wealthy people often tried imported luxuries before ordinary people could buy them.","zh":"富人通常比普通人更早嘗試進口奢侈品。"},{"en":"If wealthy people of Spain enjoyed chocolate first, the drink was probably expensive and fashionable.","zh":"如果西班牙富人最先享用朱古力，這種飲品很可能昂貴且時髦。"},{"en":"The phrase identifies a rich social group in Spain.","zh":"這個短語指出西班牙的一個富裕社會群體。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":8},{"front":"sweetened version","meaning":"加糖版本","examples":[{"en":"Spanish elites enjoyed a sweetened version of the chocolate drink.","zh":"西班牙精英享用朱古力飲品的加糖版本。"},{"en":"A sweetened version is a form of something with sugar or another sweetener added.","zh":"加糖版本是加入糖或其他甜味劑的某物形式。"},{"en":"Some people prefer the sweetened version of yogurt because plain yogurt tastes sour.","zh":"一些人喜歡乳酪的加糖版本，因為原味乳酪味道酸。"},{"en":"When Europeans made a sweetened version of chocolate, its flavour became closer to modern chocolate.","zh":"當歐洲人製作朱古力的加糖版本，其味道變得更接近現代朱古力。"},{"en":"The phrase contrasts an original form with a sweeter adaptation.","zh":"這個短語把原始形式與較甜的改良形式作對比。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":8},{"front":"popularity of the drink","meaning":"這種飲品的受歡迎程度","examples":[{"en":"The popularity of the drink spread throughout Europe.","zh":"這種飲品的受歡迎程度傳遍歐洲。"},{"en":"The popularity of the drink means how widely people liked and wanted that drink.","zh":"這種飲品的受歡迎程度指人們有多廣泛喜歡和想要該飲品。"},{"en":"The popularity of bubble tea grew when young people shared photos online.","zh":"當年輕人在網上分享照片，珍珠奶茶的受歡迎程度上升。"},{"en":"If the popularity of a drink increases, shops may start selling it in more places.","zh":"如果一種飲品的受歡迎程度增加，商店可能開始在更多地方出售它。"},{"en":"The phrase focuses on how accepted and desired a drink becomes.","zh":"這個短語強調飲品變得多被接受和渴望。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":8},{"front":"spread throughout Europe","meaning":"傳遍歐洲","examples":[{"en":"The popularity of chocolate spread throughout Europe.","zh":"朱古力的受歡迎程度傳遍歐洲。"},{"en":"To spread throughout Europe means to move or become known across many European countries.","zh":"“Spread throughout Europe” 指傳到或在許多歐洲國家為人所知。"},{"en":"A fashion trend can spread throughout Europe through magazines and social media.","zh":"時尚潮流可以透過雜誌和社交媒體傳遍歐洲。"},{"en":"As chocolate spread throughout Europe, more countries began seeking cacao supplies.","zh":"隨着朱古力傳遍歐洲，更多國家開始尋求可可供應。"},{"en":"The phrase describes wide geographical expansion across Europe.","zh":"這個短語描述在歐洲的廣泛地理擴展。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":8},{"front":"plant cacao trees","meaning":"種植可可樹","examples":[{"en":"The English, Dutch and French began to plant cacao trees.","zh":"英國人、荷蘭人和法國人開始種植可可樹。"},{"en":"To plant cacao trees means to place cacao seedlings or seeds in the ground and grow them.","zh":"“Plant cacao trees” 指把可可幼苗或種子放入泥土中並種植它們。"},{"en":"Farmers plant cacao trees in warm, shaded places with suitable soil.","zh":"農民在溫暖、陰涼且土壤合適的地方種植可可樹。"},{"en":"If more countries plant cacao trees, chocolate production can increase.","zh":"如果更多國家種植可可樹，朱古力產量可以增加。"},{"en":"The phrase refers to the start of cacao farming.","zh":"這個短語指可可農業的開始。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":8},{"front":"their own colonies","meaning":"他們自己的殖民地","examples":[{"en":"European powers planted cacao trees in their own colonies.","zh":"歐洲強權在他們自己的殖民地種植可可樹。"},{"en":"Their own colonies means territories controlled by those countries themselves.","zh":"他們自己的殖民地指由那些國家自己控制的領土。"},{"en":"A European empire might use its own colonies to grow crops for export.","zh":"歐洲帝國可能利用自己的殖民地種植出口作物。"},{"en":"If countries planted cacao in their own colonies, they could reduce dependence on rivals.","zh":"如果各國在自己的殖民地種植可可，就可以減少依賴競爭對手。"},{"en":"The phrase connects national control with colonial production.","zh":"這個短語把國家控制與殖民地生產連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":8},{"front":"the eighteenth century","meaning":"18世紀","examples":[{"en":"Until the eighteenth century, chocolate remained expensive.","zh":"直到18世紀，朱古力仍然昂貴。"},{"en":"The eighteenth century means the years from 1701 to 1800.","zh":"18世紀指1701年至1800年。"},{"en":"Many new ideas about science and trade spread during the eighteenth century.","zh":"許多關於科學和貿易的新思想在18世紀傳播。"},{"en":"If chocolate remained expensive until the eighteenth century, ordinary people had limited access to it.","zh":"如果朱古力直到18世紀仍然昂貴，普通人接觸它的機會有限。"},{"en":"The phrase identifies a historical period, not a single year.","zh":"這個短語指出一段歷史時期，而不是單一年份。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":8},{"front":"remain a drink","meaning":"仍然是一種飲品","examples":[{"en":"Chocolate remained a drink for wealthy people.","zh":"朱古力仍然是富人的一種飲品。"},{"en":"To remain a drink means to continue being consumed mainly as a beverage rather than solid food.","zh":"“Remain a drink” 指繼續主要作為飲品而不是固體食物被飲用。"},{"en":"Before modern chocolate bars, chocolate remained a drink in many European homes.","zh":"在現代朱古力條之前，朱古力在許多歐洲家庭中仍然是一種飲品。"},{"en":"If chocolate remained a drink, people would serve it in cups rather than eat it as candy.","zh":"如果朱古力仍然是一種飲品，人們會用杯盛載，而不是把它作為糖果食用。"},{"en":"The phrase shows that its form had not yet changed into modern solid chocolate.","zh":"這個短語顯示其形式尚未變成現代固體朱古力。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":9},{"front":"only wealthy people could afford","meaning":"只有富人負擔得起","examples":[{"en":"Chocolate was a drink that only wealthy people could afford.","zh":"朱古力是一種只有富人負擔得起的飲品。"},{"en":"Only wealthy people could afford something means it was too expensive for ordinary people.","zh":"“Only wealthy people could afford” 某物指它對普通人來說太昂貴。"},{"en":"In the past, private cars were something only wealthy people could afford.","zh":"過去，私家車是只有富人負擔得起的東西。"},{"en":"If only wealthy people could afford chocolate, it was a luxury rather than a common snack.","zh":"如果只有富人負擔得起朱古力，它就是奢侈品，而不是普通小食。"},{"en":"The phrase highlights inequality in access.","zh":"這個短語強調取得某物的不平等。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":9},{"front":"Industrial Revolution","meaning":"工業革命","examples":[{"en":"New technologies developed during the Industrial Revolution.","zh":"新技術在工業革命期間發展。"},{"en":"The Industrial Revolution was a period when machines and factories changed production and daily life.","zh":"工業革命是機器和工廠改變生產和日常生活的時期。"},{"en":"During the Industrial Revolution, many goods became faster and cheaper to produce.","zh":"在工業革命期間，許多商品變得生產更快、成本更低。"},{"en":"New technology from the Industrial Revolution helped make chocolate less expensive.","zh":"工業革命的新技術幫助令朱古力較不昂貴。"},{"en":"The phrase refers to a major historical change in manufacturing.","zh":"這個短語指製造業中的重大歷史變化。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":9},{"front":"less costly to produce","meaning":"生產成本較低","examples":[{"en":"New technologies made chocolate less costly to produce.","zh":"新技術令朱古力生產成本較低。"},{"en":"Less costly to produce means cheaper to make.","zh":"“Less costly to produce” 指製造成本較低。"},{"en":"If machines can pack food quickly, each product may become less costly to produce.","zh":"如果機器能快速包裝食物，每件產品的生產成本可能較低。"},{"en":"When chocolate became less costly to produce, more people could afford to buy it.","zh":"當朱古力生產成本較低，更多人就負擔得起購買它。"},{"en":"The phrase connects lower production cost with wider access.","zh":"這個短語把較低生產成本與更廣泛取得連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":9},{"front":"shady areas","meaning":"陰涼地方","examples":[{"en":"Cacao trees grow in the shady areas of rainforests.","zh":"可可樹生長在雨林的陰涼地方。"},{"en":"Shady areas are places protected from direct sunlight by trees, roofs, or other cover.","zh":"陰涼地方是受樹木、屋頂或其他遮蔽物保護，避開直射陽光的地方。"},{"en":"People may sit in shady areas of a park to avoid strong sun.","zh":"人們可能坐在公園的陰涼地方避開強烈陽光。"},{"en":"If cacao trees need shady areas, too much direct sunlight may damage them.","zh":"如果可可樹需要陰涼地方，過多直射陽光可能傷害它們。"},{"en":"The phrase describes a cool, protected growing environment.","zh":"這個短語描述涼爽、受保護的生長環境。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":9},{"front":"near the Earth’s equator","meaning":"接近地球赤道","examples":[{"en":"Cacao trees grow near the Earth’s equator.","zh":"可可樹生長在接近地球赤道的地方。"},{"en":"Near the Earth’s equator means close to the imaginary line around the middle of the planet.","zh":"“Near the Earth’s equator” 指接近圍繞地球中部的想像線。"},{"en":"Countries near the Earth’s equator are often warm throughout the year.","zh":"接近地球赤道的國家通常全年溫暖。"},{"en":"Because cacao needs warmth and moisture, it grows best near the Earth’s equator.","zh":"因為可可需要溫暖和水分，它最適合在接近地球赤道的地方生長。"},{"en":"The phrase explains the climate zone suitable for cacao.","zh":"這個短語解釋適合可可的氣候帶。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":9},{"front":"difficult to grow","meaning":"難以種植","examples":[{"en":"Cacao trees can be difficult to grow.","zh":"可可樹可能難以種植。"},{"en":"Difficult to grow means not easy to cultivate because the plant needs special conditions.","zh":"“Difficult to grow” 指因植物需要特殊條件而不容易栽培。"},{"en":"Orchids can be difficult to grow if the room is too dry or too cold.","zh":"如果房間太乾或太冷，蘭花可能難以種植。"},{"en":"If cacao trees are difficult to grow, farmers face higher risks and need careful knowledge.","zh":"如果可可樹難以種植，農民就面對較高風險並需要謹慎知識。"},{"en":"The phrase explains why farming a crop may require skill and patience.","zh":"這個短語解釋為何種植作物可能需要技能和耐性。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":9},{"front":"require an exact amount of","meaning":"需要精確數量的……","examples":[{"en":"Cacao trees require an exact amount of water and warmth.","zh":"可可樹需要精確數量的水分和溫暖。"},{"en":"To require an exact amount of something means to need a specific level, not too much and not too little.","zh":"“Require an exact amount of” 某物指需要特定水平，不能太多也不能太少。"},{"en":"Baking bread may require an exact amount of yeast and water.","zh":"烤麵包可能需要精確份量的酵母和水。"},{"en":"If cacao trees receive too much or too little water, they may not grow well.","zh":"如果可可樹獲得太多或太少水分，它們可能生長不好。"},{"en":"The phrase stresses precise conditions.","zh":"這個短語強調精準條件。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":9},{"front":"water, warmth, soil and protection","meaning":"水分、溫暖、土壤和保護","examples":[{"en":"Cacao trees need water, warmth, soil and protection.","zh":"可可樹需要水分、溫暖、土壤和保護。"},{"en":"Water, warmth, soil and protection are basic conditions that help cacao trees survive and produce fruit.","zh":"水分、溫暖、土壤和保護是幫助可可樹生存並結果的基本條件。"},{"en":"A garden plant also needs water, warmth, soil and protection from strong wind or pests.","zh":"花園植物也需要水分、溫暖、土壤和免受強風或害蟲影響的保護。"},{"en":"Without these conditions, cacao trees may grow slowly or become damaged.","zh":"沒有這些條件，可可樹可能生長緩慢或受損。"},{"en":"The phrase lists the practical needs of a delicate crop.","zh":"這個短語列出嬌弱作物的實際需要。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":9},{"front":"start producing","meaning":"開始產出","examples":[{"en":"Cacao trees start producing fruit after about five years.","zh":"可可樹大約五年後開始產出果實。"},{"en":"To start producing something means to begin making or growing it.","zh":"“Start producing” 某物指開始製造或長出它。"},{"en":"An apple tree may start producing fruit only after several years.","zh":"蘋果樹可能要幾年後才開始產出果實。"},{"en":"If cacao trees start producing late, farmers must wait years before earning from them.","zh":"如果可可樹很晚才開始產出，農民必須等待多年才有收入。"},{"en":"The phrase marks the beginning of useful output.","zh":"這個短語標誌有用產出的開始。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":9},{"front":"large fruits called pods","meaning":"稱為莢果的大型果實","examples":[{"en":"Cacao trees produce large fruits called pods.","zh":"可可樹產出稱為莢果的大型果實。"},{"en":"Large fruits called pods are big seed-containing fruits that grow on cacao trees.","zh":"稱為莢果的大型果實是長在可可樹上、內含種子的巨大果實。"},{"en":"Farmers cut cacao pods open to reach the seeds inside.","zh":"農民切開可可莢果，以取得裡面的種子。"},{"en":"If the pods are damaged, the cacao seeds inside may also be harmed.","zh":"如果莢果受損，裡面的可可豆也可能受害。"},{"en":"The phrase introduces the fruit form that holds cacao seeds.","zh":"這個短語介紹盛載可可豆的果實形態。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":9},{"front":"trunk of the tree","meaning":"樹幹","examples":[{"en":"Cacao pods grow near the trunk of the tree.","zh":"可可莢果長在接近樹幹的位置。"},{"en":"The trunk of the tree is the main thick stem that supports branches and leaves.","zh":"樹幹是支撐樹枝和樹葉的主要粗大莖部。"},{"en":"Children can measure the trunk of a tree to learn how old or large it may be.","zh":"孩子可以量度樹幹，以了解樹可能有多老或多大。"},{"en":"If cacao pods grow near the trunk, workers can harvest them from the tree’s main stem.","zh":"如果可可莢果長在接近樹幹的位置，工人可以從樹的主幹採收它們。"},{"en":"The phrase identifies a central part of a tree.","zh":"這個短語指出樹的中心部分。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":10},{"front":"seeds inside the pods","meaning":"莢果內的種子","examples":[{"en":"The seeds inside the pods are harvested to make chocolate.","zh":"莢果內的種子被採收用來製作朱古力。"},{"en":"The seeds inside the pods are cacao seeds found within the large cacao fruits.","zh":"莢果內的種子是位於大型可可果實內的可可豆。"},{"en":"A farmer must open the pods carefully to collect the seeds inside.","zh":"農民必須小心打開莢果，以收集裡面的種子。"},{"en":"If the seeds inside the pods are healthy, they can be processed into chocolate.","zh":"如果莢果內的種子健康，它們就可以被加工成朱古力。"},{"en":"The phrase identifies the valuable part hidden inside the fruit.","zh":"這個短語指出果實內隱藏的有價值部分。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":10},{"front":"be harvested to","meaning":"被收割／採收用來……","examples":[{"en":"The seeds are harvested to make chocolate.","zh":"這些種子被採收用來製作朱古力。"},{"en":"To be harvested to do something means to be collected from plants for that purpose.","zh":"“Be harvested to” 做某事指從植物上收集某物作該用途。"},{"en":"Grapes are harvested to make juice, raisins, or wine.","zh":"葡萄被採收用來製作果汁、葡萄乾或葡萄酒。"},{"en":"If cacao seeds are harvested too early, the final chocolate may lose quality.","zh":"如果可可豆太早被採收，最終朱古力品質可能下降。"},{"en":"The phrase links crop collection with later production.","zh":"這個短語把作物採收與後續生產連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":10},{"front":"several kinds of","meaning":"幾種……","examples":[{"en":"There are several kinds of cacao trees.","zh":"有幾種可可樹。"},{"en":"Several kinds of something means more than two types of it.","zh":"“Several kinds of” 某物指多於兩種類型。"},{"en":"A shop may sell several kinds of rice for different dishes.","zh":"商店可能出售幾種米，用於不同菜式。"},{"en":"If there are several kinds of cacao trees, chocolate makers can choose different flavours and qualities.","zh":"如果有幾種可可樹，朱古力製造商可以選擇不同味道和品質。"},{"en":"The phrase introduces variety within one category.","zh":"這個短語引出同一類別中的多樣性。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":10},{"front":"most of the world’s chocolate","meaning":"世界上大部分朱古力","examples":[{"en":"Most of the world’s chocolate is made from forastero seeds.","zh":"世界上大部分朱古力由福拉斯特羅可可豆製成。"},{"en":"Most of the world’s chocolate means the majority of chocolate produced globally.","zh":"世界上大部分朱古力指全球生產的朱古力中的大多數。"},{"en":"Most of the world’s coffee comes from countries with warm climates.","zh":"世界上大部分咖啡來自氣候溫暖的國家。"},{"en":"If most of the world’s chocolate uses one cacao type, that type is commercially important.","zh":"如果世界上大部分朱古力使用一種可可類型，該類型就具有商業重要性。"},{"en":"The phrase gives a global proportion, not a local fact.","zh":"這個短語給出全球比例，而不是本地事實。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":10},{"front":"be made from","meaning":"由……製成","examples":[{"en":"Most chocolate is made from the seed of the forastero tree.","zh":"大多數朱古力由福拉斯特羅可可樹的種子製成。"},{"en":"Be made from something means produced using that material as the source.","zh":"“Be made from” 某物指使用該材料作為來源生產出來。"},{"en":"Paper is often made from wood pulp.","zh":"紙通常由木漿製成。"},{"en":"If chocolate is made from cacao seeds, the quality of the seeds affects the final taste.","zh":"如果朱古力由可可豆製成，可可豆品質會影響最終味道。"},{"en":"The phrase explains the raw material behind a product.","zh":"這個短語解釋產品背後的原材料。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":10},{"front":"forastero tree","meaning":"福拉斯特羅可可樹","examples":[{"en":"The forastero tree provides most of the world’s cacao seeds.","zh":"福拉斯特羅可可樹提供世界上大部分可可豆。"},{"en":"The forastero tree is a type of cacao tree widely used in chocolate production.","zh":"福拉斯特羅可可樹是一種廣泛用於朱古力生產的可可樹。"},{"en":"Farmers may grow forastero trees because they can produce many cacao seeds.","zh":"農民可能種植福拉斯特羅可可樹，因為它能產出許多可可豆。"},{"en":"If the forastero tree supplies most cacao, problems affecting it can affect the chocolate industry.","zh":"如果福拉斯特羅可可樹供應大部分可可，影響它的問題就會影響朱古力業。"},{"en":"The phrase names a commercially important cacao variety.","zh":"這個短語指一種商業上重要的可可品種。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":10},{"front":"criollo cacao plants","meaning":"克里奧羅可可植物","examples":[{"en":"Farmers can also grow criollo cacao plants.","zh":"農民也可以種植克里奧羅可可植物。"},{"en":"Criollo cacao plants are a type of cacao plant known as one variety used for chocolate.","zh":"克里奧羅可可植物是一種用於朱古力的可可植物品種。"},{"en":"A farmer may grow criollo cacao plants if buyers want a special flavour.","zh":"如果買家想要特別風味，農民可能種植克里奧羅可可植物。"},{"en":"If criollo cacao plants are harder to grow, their beans may be rarer and more expensive.","zh":"如果克里奧羅可可植物較難種植，其豆可能更稀有、更昂貴。"},{"en":"The phrase names one recognised cacao variety.","zh":"這個短語指一種公認的可可品種。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":10},{"front":"trinitario cacao plants","meaning":"特立尼塔里奧可可植物","examples":[{"en":"Farmers can also grow trinitario cacao plants.","zh":"農民也可以種植特立尼塔里奧可可植物。"},{"en":"Trinitario cacao plants are another variety of cacao plants used in chocolate production.","zh":"特立尼塔里奧可可植物是另一種用於朱古力生產的可可植物品種。"},{"en":"A chocolate maker may choose trinitario cacao plants for a different flavour profile.","zh":"朱古力製造商可能選擇特立尼塔里奧可可植物，以獲得不同風味特徵。"},{"en":"If farmers grow several cacao varieties, they can serve different chocolate markets.","zh":"如果農民種植幾種可可品種，就能服務不同朱古力市場。"},{"en":"The phrase identifies a specific cacao type, not all cacao plants.","zh":"這個短語指出一種特定可可類型，而不是所有可可植物。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":10},{"front":"farmed cacao trees","meaning":"人工種植的可可樹","examples":[{"en":"Farmed cacao trees are more vulnerable than wild trees.","zh":"人工種植的可可樹比野生樹木更脆弱。"},{"en":"Farmed cacao trees are cacao trees deliberately grown by farmers rather than growing naturally in the wild.","zh":"人工種植的可可樹是由農民有意栽培，而不是在野外自然生長的可可樹。"},{"en":"Farmed cacao trees may be planted in rows so workers can harvest them more easily.","zh":"人工種植的可可樹可能排列成行，方便工人採收。"},{"en":"If farmed cacao trees are genetically similar, diseases can spread quickly among them.","zh":"如果人工種植的可可樹基因相似，疾病可以在它們之間迅速傳播。"},{"en":"The phrase contrasts cultivated trees with wild trees.","zh":"這個短語把栽培樹木與野生樹木作對比。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":10},{"front":"be vulnerable to","meaning":"容易受到……影響","examples":[{"en":"Farmed cacao trees are vulnerable to diseases and insects.","zh":"人工種植的可可樹容易受到疾病和昆蟲影響。"},{"en":"To be vulnerable to something means to be easily harmed or damaged by it.","zh":"“Be vulnerable to” 某事指容易被它傷害或破壞。"},{"en":"Young children are vulnerable to colds when they do not get enough sleep.","zh":"年幼孩子睡眠不足時容易受到感冒影響。"},{"en":"If cacao trees are vulnerable to insects, farmers may lose part of their harvest.","zh":"如果可可樹容易受到昆蟲影響，農民可能失去部分收成。"},{"en":"The phrase warns that something is weak against a particular danger.","zh":"這個短語提醒某物面對特定危險時較脆弱。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":10},{"front":"diseases and insects","meaning":"疾病和昆蟲","examples":[{"en":"Cacao trees can be damaged by diseases and insects.","zh":"可可樹可能被疾病和昆蟲損害。"},{"en":"Diseases and insects are living threats that can weaken or destroy plants.","zh":"疾病和昆蟲是可以削弱或破壞植物的生物威脅。"},{"en":"Gardeners protect vegetables from diseases and insects by checking leaves regularly.","zh":"園丁透過定期檢查葉子，保護蔬菜免受疾病和昆蟲影響。"},{"en":"If diseases and insects attack cacao trees, farmers may earn less money.","zh":"如果疾病和昆蟲侵襲可可樹，農民可能賺得較少。"},{"en":"The phrase groups two common farming risks.","zh":"這個短語把兩種常見農業風險歸在一起。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":11},{"front":"very hard work for","meaning":"對……來說是非常辛苦的工作","examples":[{"en":"Growing cacao is very hard work for farmers.","zh":"種植可可對農民來說是非常辛苦的工作。"},{"en":"Very hard work for someone means a task requires great effort, time, and physical or mental energy from them.","zh":"“Very hard work for” 某人指任務需要他們大量努力、時間和體力或精神能量。"},{"en":"Moving house is very hard work for a family without help.","zh":"沒有幫助時，搬屋對家庭來說是非常辛苦的工作。"},{"en":"Because cacao trees need careful care, growing cacao is very hard work for farmers.","zh":"因為可可樹需要細心照料，種植可可對農民來說是非常辛苦的工作。"},{"en":"The phrase stresses the burden on the person doing the job.","zh":"這個短語強調做該工作的人承受的負擔。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":11},{"front":"sell their harvest","meaning":"出售收成","examples":[{"en":"Farmers sell their harvest on a futures market.","zh":"農民在期貨市場出售收成。"},{"en":"To sell their harvest means to sell the crops they have grown and collected.","zh":"“Sell their harvest” 指出售他們種植和採收的作物。"},{"en":"Rice farmers sell their harvest after the grain has been dried and stored.","zh":"稻農在穀物乾燥和儲存後出售收成。"},{"en":"If cacao farmers sell their harvest at a low price, their income may not cover their labour.","zh":"如果可可農以低價出售收成，收入可能不足以支付其勞動。"},{"en":"The phrase connects farming work with earning money.","zh":"這個短語把農業工作與賺取金錢連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":11},{"front":"futures market","meaning":"期貨市場","examples":[{"en":"Cacao farmers sell their harvest on a futures market.","zh":"可可農在期貨市場出售收成。"},{"en":"A futures market is a market where people buy and sell contracts for goods to be delivered later.","zh":"期貨市場是人們買賣日後交付商品合約的市場。"},{"en":"Farmers may use a futures market to agree on prices before harvest time.","zh":"農民可能使用期貨市場在收成前先約定價格。"},{"en":"If prices change on the futures market, farmers’ expected income may rise or fall.","zh":"如果期貨市場價格變化，農民預期收入可能上升或下降。"},{"en":"The phrase refers to a financial market linked to future supply.","zh":"這個短語指與未來供應有關的金融市場。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":11},{"front":"economic conditions","meaning":"經濟狀況","examples":[{"en":"Economic conditions can affect farmers’ earnings.","zh":"經濟狀況可以影響農民收入。"},{"en":"Economic conditions are the general financial situation, including prices, jobs, demand, and trade.","zh":"經濟狀況是整體財政情況，包括價格、就業、需求和貿易。"},{"en":"During poor economic conditions, families may buy fewer luxury foods.","zh":"在經濟狀況差時，家庭可能較少購買奢侈食物。"},{"en":"If economic conditions change suddenly, cacao prices may move beyond farmers’ control.","zh":"如果經濟狀況突然改變，可可價格可能超出農民控制。"},{"en":"The phrase describes the wider money environment around people and businesses.","zh":"這個短語描述圍繞人和企業的更廣泛金錢環境。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":11},{"front":"beyond their control","meaning":"超出他們控制範圍","examples":[{"en":"Farmers are affected by conditions beyond their control.","zh":"農民受到超出他們控制範圍的情況影響。"},{"en":"Beyond their control means outside their power to change or manage.","zh":"“Beyond their control” 指超出他們能改變或管理的能力範圍。"},{"en":"A student may be late because of a train delay beyond their control.","zh":"學生可能因超出其控制範圍的火車延誤而遲到。"},{"en":"If market prices fall for reasons beyond farmers’ control, their income may drop unfairly.","zh":"如果市場價格因農民控制範圍以外的原因下跌，他們的收入可能不公平地下跌。"},{"en":"The phrase shows that people may suffer from forces they cannot manage.","zh":"這個短語顯示人可能受自己無法管理的力量影響。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":11},{"front":"affect the amount of money","meaning":"影響金額","examples":[{"en":"Market conditions affect the amount of money farmers earn.","zh":"市場狀況影響農民賺取的金額。"},{"en":"To affect the amount of money means to change how much money is gained, lost, paid, or received.","zh":"“Affect the amount of money” 指改變獲得、損失、支付或收到的金額。"},{"en":"Overtime hours affect the amount of money a worker earns each month.","zh":"加班時數會影響工人每月賺取的金額。"},{"en":"If cacao prices fall, they affect the amount of money farmers take home.","zh":"如果可可價格下跌，就會影響農民帶回家的金額。"},{"en":"The phrase links a condition with income or cost.","zh":"這個短語把某種情況與收入或成本連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":11},{"front":"chocolate industry officials","meaning":"朱古力業界人士","examples":[{"en":"Chocolate industry officials are working with farmers.","zh":"朱古力業界人士正在與農民合作。"},{"en":"Chocolate industry officials are people in positions of responsibility within chocolate companies or industry organisations.","zh":"朱古力業界人士是在朱古力公司或行業組織中擔任責任職位的人。"},{"en":"Chocolate industry officials may discuss prices, farming standards, and supply problems.","zh":"朱古力業界人士可能討論價格、農業標準和供應問題。"},{"en":"If chocolate industry officials work with farmers, they may improve production and fairness.","zh":"如果朱古力業界人士與農民合作，他們可能改善生產和公平。"},{"en":"The phrase identifies decision-makers connected with the chocolate business.","zh":"這個短語指出與朱古力業務有關的決策者。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":11},{"front":"activists","meaning":"社運人士；倡議人士","examples":[{"en":"Activists are working with farmers to improve cacao production.","zh":"倡議人士正在與農民合作，以改善可可生產。"},{"en":"Activists are people who campaign for social, political, environmental, or economic change.","zh":"倡議人士是為社會、政治、環境或經濟改變而行動的人。"},{"en":"Environmental activists may ask companies to reduce waste and protect forests.","zh":"環保倡議人士可能要求公司減少浪費並保護森林。"},{"en":"If activists work with farmers, they may push for fairer pay and safer farming methods.","zh":"如果倡議人士與農民合作，他們可能推動更公平薪酬和更安全農法。"},{"en":"The word often describes people who try to change a system.","zh":"這個詞常描述試圖改變制度的人。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":11},{"front":"work with farmers","meaning":"與農民合作","examples":[{"en":"Scientists and activists are working with farmers.","zh":"科學家和倡議人士正在與農民合作。"},{"en":"To work with farmers means to cooperate with people who grow crops or raise animals.","zh":"“Work with farmers” 指與種植作物或飼養動物的人合作。"},{"en":"A university may work with farmers to test safer ways to control insects.","zh":"大學可能與農民合作，測試更安全的控蟲方法。"},{"en":"If companies work with farmers, they can understand real farming problems better.","zh":"如果公司與農民合作，就能更好理解真正農業問題。"},{"en":"The phrase highlights cooperation rather than giving orders from far away.","zh":"這個短語強調合作，而不是從遠處下命令。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":11},{"front":"make sure that","meaning":"確保","examples":[{"en":"They are trying to make sure that cacao is grown fairly.","zh":"他們正嘗試確保可可被公平種植。"},{"en":"To make sure that something happens means to check or act so it will happen correctly.","zh":"“Make sure that” 某事發生指檢查或採取行動，使它正確發生。"},{"en":"A teacher may make sure that every student understands the homework before leaving class.","zh":"老師可能在下課前確保每名學生明白功課。"},{"en":"If companies make sure that farmers are paid fairly, the supply chain becomes more ethical.","zh":"如果公司確保農民獲得公平薪酬，供應鏈會變得更合乎道德。"},{"en":"The phrase shows careful checking and responsibility.","zh":"這個短語顯示仔細檢查和責任。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":11},{"front":"grown in a way that","meaning":"以……的方式種植","examples":[{"en":"Cacao should be grown in a way that is fair and safe.","zh":"可可應以公平和安全的方式種植。"},{"en":"Grown in a way that means cultivated according to a particular method or standard.","zh":"“Grown in a way that” 指根據某種方法或標準栽培。"},{"en":"Vegetables can be grown in a way that uses less water.","zh":"蔬菜可以以較少用水的方式種植。"},{"en":"If cacao is grown in a way that protects forests, farming causes less environmental damage.","zh":"如果可可以保護森林的方式種植，農業造成的環境傷害會較少。"},{"en":"The phrase describes the manner or conditions of farming.","zh":"這個短語描述種植方式或條件。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":12},{"front":"fair to the farmers","meaning":"對農民公平","examples":[{"en":"Cacao production should be fair to the farmers.","zh":"可可生產應對農民公平。"},{"en":"Fair to the farmers means treating farmers justly, especially in pay, safety, and working conditions.","zh":"對農民公平指公平對待農民，尤其在薪酬、安全和工作條件方面。"},{"en":"A contract is fair to farmers if it pays them enough to cover labour and living costs.","zh":"如果合約支付足夠金額以覆蓋勞動和生活成本，它就對農民公平。"},{"en":"If chocolate is cheap because farmers are underpaid, the system is not fair to the farmers.","zh":"如果朱古力便宜是因為農民薪酬過低，該制度就不是對農民公平。"},{"en":"The phrase focuses on justice for the people who grow the crop.","zh":"這個短語強調對種植作物者的公義。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":12},{"front":"safe for the environment","meaning":"對環境安全","examples":[{"en":"Cacao should be grown in a way that is safe for the environment.","zh":"可可應以對環境安全的方式種植。"},{"en":"Safe for the environment means not causing serious harm to land, water, air, plants, or animals.","zh":"對環境安全指不會對土地、水、空氣、植物或動物造成嚴重傷害。"},{"en":"A cleaning product is safer for the environment if it does not pollute rivers.","zh":"如果清潔產品不污染河流，它就對環境較安全。"},{"en":"If cacao farming is safe for the environment, forests and wildlife are better protected.","zh":"如果可可種植對環境安全，森林和野生動物就更受保護。"},{"en":"The phrase connects production with ecological responsibility.","zh":"這個短語把生產與生態責任連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":12},{"front":"go through","meaning":"經歷","examples":[{"en":"Cacao seeds go through a long production process.","zh":"可可豆經歷一個漫長生產過程。"},{"en":"To go through a process means to pass through several stages or steps.","zh":"“Go through” 一個過程指通過幾個階段或步驟。"},{"en":"Students go through several drafts before finishing a good essay.","zh":"學生在完成一篇好作文前會經歷幾份草稿。"},{"en":"Cacao seeds must go through cleaning, cooking, crushing, and mixing before becoming chocolate.","zh":"可可豆必須經歷清潔、烘煮、壓碎和混合，才變成朱古力。"},{"en":"The phrase shows movement from one stage to another.","zh":"這個短語顯示由一個階段移向另一個階段。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":12},{"front":"long production process","meaning":"漫長生產過程","examples":[{"en":"Cacao seeds go through a long production process in a factory.","zh":"可可豆在工廠經歷漫長生產過程。"},{"en":"A long production process is a series of many steps needed to make a final product.","zh":"漫長生產過程是製作最終產品所需的一連串多個步驟。"},{"en":"Making cheese can involve a long production process of heating, pressing, and ageing.","zh":"製作芝士可能涉及加熱、壓製和熟成的漫長生產過程。"},{"en":"Because chocolate has a long production process, many workers and machines may be involved.","zh":"因為朱古力有漫長生產過程，可能涉及許多工人和機器。"},{"en":"The phrase explains why a simple-looking product can require complex work.","zh":"這個短語解釋為何看似簡單的產品可能需要複雜工作。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":12},{"front":"sort, clean and cook","meaning":"分類、清潔和烘煮","examples":[{"en":"Workers sort, clean and cook the cacao seeds.","zh":"工人分類、清潔和烘煮可可豆。"},{"en":"To sort, clean and cook seeds means to separate them, remove dirt, and heat them for processing.","zh":"“Sort, clean and cook” 種子指把它們分類、去除污垢並加熱加工。"},{"en":"Before making soup, a cook may sort, clean and cook beans.","zh":"煮湯前，廚師可能分類、清潔和烘煮豆類。"},{"en":"If cacao seeds are not sorted, cleaned and cooked properly, the chocolate may taste bad.","zh":"如果可可豆沒有妥善分類、清潔和烘煮，朱古力可能味道不好。"},{"en":"The phrase lists early preparation steps.","zh":"這個短語列出早期準備步驟。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":12},{"front":"remove the outer coverings","meaning":"去除外殼","examples":[{"en":"Workers remove the seeds’ outer coverings.","zh":"工人去除種子的外殼。"},{"en":"To remove the outer coverings means to take off the outside layer or shell.","zh":"“Remove the outer coverings” 指拿走外層或外殼。"},{"en":"A cook may remove the outer coverings of peanuts before making a smooth sauce.","zh":"廚師可能在製作幼滑醬汁前去除花生外殼。"},{"en":"When workers remove the outer coverings of cacao seeds, the useful inside remains.","zh":"當工人去除可可豆外殼，有用的內部就留下。"},{"en":"The phrase describes taking away an unwanted outside part.","zh":"這個短語描述移除不需要的外部部分。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":12},{"front":"outer coverings","meaning":"外殼","examples":[{"en":"The outer coverings of cacao seeds are removed.","zh":"可可豆的外殼被去除。"},{"en":"Outer coverings are the outside layers that protect the inside of something.","zh":"外殼是保護某物內部的外層。"},{"en":"The outer coverings of some nuts must be removed before eating.","zh":"一些堅果的外殼必須在食用前去除。"},{"en":"If the outer coverings remain, the texture of the final chocolate may be rough.","zh":"如果外殼仍然存在，最終朱古力的質地可能粗糙。"},{"en":"The phrase identifies the protective layer on the outside.","zh":"這個短語指出外部的保護層。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":12},{"front":"the insides remain","meaning":"內部留下","examples":[{"en":"Only the insides of the seeds remain.","zh":"只有種子的內部留下。"},{"en":"The insides remain means the inner parts are left after the outside has been removed.","zh":"“The insides remain” 指外層被移除後，內部部分留下。"},{"en":"After peeling an orange, only the juicy insides remain.","zh":"剝橙後，只有多汁的內部留下。"},{"en":"When cacao seed coverings are removed, the insides remain and can be processed further.","zh":"當可可豆外殼被去除，內部留下並可以進一步加工。"},{"en":"The phrase shows what is left after an outer layer is taken away.","zh":"這個短語顯示外層被拿走後留下甚麼。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":12},{"front":"nibs","meaning":"可可碎仁","examples":[{"en":"The insides of cacao seeds are called nibs.","zh":"可可豆的內部稱為可可碎仁。"},{"en":"Nibs are the small inner pieces of cacao seeds after their outer coverings are removed.","zh":"可可碎仁是可可豆去除外殼後的細小內部部分。"},{"en":"Chocolate makers crush nibs to make chocolate liquor.","zh":"朱古力製造商壓碎可可碎仁來製作巧克力原漿。"},{"en":"If the nibs are roasted well, the chocolate may develop a richer flavour.","zh":"如果可可碎仁烘焙得好，朱古力可能發展出更濃郁風味。"},{"en":"The word names a key ingredient in chocolate production.","zh":"這個詞指朱古力生產中的關鍵材料。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":12},{"front":"crush the nibs into","meaning":"將可可碎仁壓碎成……","examples":[{"en":"Workers crush the nibs into a soft substance.","zh":"工人將可可碎仁壓碎成軟質物質。"},{"en":"To crush the nibs into something means to grind cacao nibs until they change into that form.","zh":"“Crush the nibs into” 某物指研磨可可碎仁，直到它們變成該形態。"},{"en":"A food processor can crush nuts into a thick paste.","zh":"食物處理機可以將堅果壓碎成濃稠糊狀物。"},{"en":"When workers crush the nibs into a soft substance, the cacao begins to look more like chocolate.","zh":"當工人將可可碎仁壓碎成軟質物質，可可開始變得更像朱古力。"},{"en":"The phrase describes a mechanical step in production.","zh":"這個短語描述生產中的機械步驟。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":12},{"front":"soft substance","meaning":"軟質物質","examples":[{"en":"The nibs are crushed into a soft substance.","zh":"可可碎仁被壓碎成軟質物質。"},{"en":"A soft substance is a material that is smooth, thick, or easy to shape.","zh":"軟質物質是幼滑、濃稠或容易塑形的材料。"},{"en":"Butter becomes a soft substance when it warms slightly.","zh":"牛油稍微變暖後會變成軟質物質。"},{"en":"If cacao nibs become a soft substance, they can be mixed with sugar and fat.","zh":"如果可可碎仁變成軟質物質，就可以與糖和脂肪混合。"},{"en":"The phrase describes texture rather than taste.","zh":"這個短語描述質地，而不是味道。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":13},{"front":"chocolate liquor","meaning":"巧克力原漿；可可漿","examples":[{"en":"Crushed cacao nibs become chocolate liquor.","zh":"壓碎的可可碎仁變成巧克力原漿。"},{"en":"Chocolate liquor is a thick cacao substance made by grinding cacao nibs; it is not an alcoholic drink here.","zh":"巧克力原漿是研磨可可碎仁製成的濃稠可可物質；在此不是酒精飲品。"},{"en":"Chocolate makers use chocolate liquor as a base for different kinds of chocolate.","zh":"朱古力製造商使用巧克力原漿作為不同種類朱古力的基礎。"},{"en":"If chocolate liquor is separated, it can produce cocoa solids and cocoa butter.","zh":"如果巧克力原漿被分離，可以產生可可固體和可可脂。"},{"en":"The phrase names an important intermediate product in chocolate making.","zh":"這個短語指朱古力製作中的重要中間產品。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":13},{"front":"be separated into","meaning":"被分離成","examples":[{"en":"Chocolate liquor is separated into cocoa solids and cocoa butter.","zh":"巧克力原漿被分離成可可固體和可可脂。"},{"en":"To be separated into parts means to be divided into different components.","zh":"“Be separated into” 多個部分指被分成不同成分。"},{"en":"Milk can be separated into cream and skimmed milk.","zh":"牛奶可以被分離成忌廉和脫脂奶。"},{"en":"When chocolate liquor is separated into solids and butter, makers can control texture and flavour.","zh":"當巧克力原漿被分離成固體和脂肪，製造商就能控制質地和味道。"},{"en":"The phrase explains how one material becomes several useful parts.","zh":"這個短語解釋一種材料如何變成幾個有用部分。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":13},{"front":"cocoa solids","meaning":"可可固體","examples":[{"en":"Chocolate liquor is separated into cocoa solids.","zh":"巧克力原漿被分離出可可固體。"},{"en":"Cocoa solids are the non-fat parts of cacao that give chocolate much of its flavour and colour.","zh":"可可固體是可可中非脂肪部分，賦予朱古力許多味道和顏色。"},{"en":"Dark chocolate usually contains a higher amount of cocoa solids than milk chocolate.","zh":"黑朱古力通常比牛奶朱古力含有更多可可固體。"},{"en":"If a chocolate has more cocoa solids, it may taste stronger and less sweet.","zh":"如果朱古力有更多可可固體，味道可能更濃、更不甜。"},{"en":"The phrase names one main component of chocolate.","zh":"這個短語指朱古力的一種主要成分。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":13},{"front":"cocoa butter","meaning":"可可脂","examples":[{"en":"Chocolate liquor is separated into cocoa butter.","zh":"巧克力原漿被分離出可可脂。"},{"en":"Cocoa butter is the natural fat from cacao beans, used to make chocolate smooth.","zh":"可可脂是來自可可豆的天然脂肪，用來令朱古力幼滑。"},{"en":"Lip balms and skin creams may also use cocoa butter because it feels rich and soft.","zh":"潤唇膏和護膚霜也可能使用可可脂，因為它質感豐潤柔滑。"},{"en":"If chocolate contains enough cocoa butter, it can melt smoothly in the mouth.","zh":"如果朱古力含有足夠可可脂，它可以在口中幼滑融化。"},{"en":"The phrase names the fatty part of cacao.","zh":"這個短語指可可中的脂肪部分。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":13},{"front":"chocolate makers","meaning":"朱古力製造商","examples":[{"en":"Chocolate makers have their own special recipes.","zh":"朱古力製造商有自己的特別配方。"},{"en":"Chocolate makers are people or companies that produce chocolate from cacao ingredients.","zh":"朱古力製造商是使用可可材料生產朱古力的人或公司。"},{"en":"Chocolate makers may adjust roasting time, sugar, milk, and cocoa butter to create flavour.","zh":"朱古力製造商可能調整烘焙時間、糖、牛奶和可可脂來創造味道。"},{"en":"If chocolate makers use high-quality cacao, their products may taste richer.","zh":"如果朱古力製造商使用高品質可可，產品可能味道更濃郁。"},{"en":"The phrase refers to producers, not simply people who eat chocolate.","zh":"這個短語指生產者，而不只是吃朱古力的人。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":13},{"front":"special recipes","meaning":"特別配方","examples":[{"en":"Chocolate makers use their own special recipes.","zh":"朱古力製造商使用自己的特別配方。"},{"en":"Special recipes are particular sets of ingredients and methods that make a product distinctive.","zh":"特別配方是令產品有特色的一套特定材料和方法。"},{"en":"A family restaurant may keep special recipes secret for many years.","zh":"家庭餐廳可能多年保密其特別配方。"},{"en":"If chocolate makers change their special recipes, the taste and texture may change.","zh":"如果朱古力製造商改變特別配方，味道和質地可能改變。"},{"en":"The phrase highlights unique preparation methods.","zh":"這個短語強調獨特製作方法。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":13},{"front":"combine…with…","meaning":"將……與……混合","examples":[{"en":"Chocolate makers combine chocolate liquor with sugar, milk and cocoa fat.","zh":"朱古力製造商將巧克力原漿與糖、牛奶和可可脂混合。"},{"en":"To combine one thing with another means to join them together into one mixture or result.","zh":"“Combine one thing with another” 指把它們結合成一種混合物或結果。"},{"en":"A cook may combine flour with eggs and milk to make pancakes.","zh":"廚師可能將麵粉與雞蛋和牛奶混合來製作班戟。"},{"en":"When makers combine chocolate liquor with sugar, the bitter cacao becomes sweeter.","zh":"當製造商將巧克力原漿與糖混合，苦味可可就變得較甜。"},{"en":"The phrase is useful for explaining mixtures and partnerships.","zh":"這個短語適合解釋混合物和合作關係。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":13},{"front":"exact amounts of","meaning":"精確份量的……","examples":[{"en":"Chocolate makers use exact amounts of sugar, milk and cocoa fat.","zh":"朱古力製造商使用精確份量的糖、牛奶和可可脂。"},{"en":"Exact amounts of something are precise quantities, not rough guesses.","zh":"精確份量的某物是準確數量，而不是大概猜測。"},{"en":"Baking often needs exact amounts of flour and water.","zh":"烘焙通常需要精確份量的麵粉和水。"},{"en":"If chocolate makers use the wrong amounts, the chocolate may become too sweet or too soft.","zh":"如果朱古力製造商使用錯誤份量，朱古力可能太甜或太軟。"},{"en":"The phrase stresses precision in a recipe or process.","zh":"這個短語強調食譜或過程中的精準度。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":13},{"front":"cocoa fat","meaning":"可可脂","examples":[{"en":"Chocolate makers add cocoa fat to the mixture.","zh":"朱古力製造商向混合物中加入可可脂。"},{"en":"Cocoa fat is the fatty part of cacao that helps give chocolate a smooth texture.","zh":"可可脂是可可中的脂肪部分，有助給朱古力幼滑質地。"},{"en":"A chocolate bar with enough cocoa fat may melt evenly in the mouth.","zh":"含有足夠可可脂的朱古力條可能在口中均勻融化。"},{"en":"If cocoa fat is reduced too much, chocolate may feel dry or rough.","zh":"如果可可脂減少太多，朱古力可能感覺乾或粗糙。"},{"en":"The phrase is closely related to cocoa butter.","zh":"這個短語與 cocoa butter 意思密切相關。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":13},{"front":"finely crush","meaning":"精細研磨","examples":[{"en":"Workers finely crush the crumb mixture.","zh":"工人精細研磨粉粒混合物。"},{"en":"To finely crush something means to grind it into very small, smooth particles.","zh":"“Finely crush” 某物指把它研磨成非常細小、幼滑的粒子。"},{"en":"A cook may finely crush nuts before adding them to a cake.","zh":"廚師可能在把堅果加入蛋糕前精細研磨它們。"},{"en":"If the mixture is finely crushed, the final chocolate becomes smoother.","zh":"如果混合物被精細研磨，最終朱古力會變得更幼滑。"},{"en":"The phrase describes careful grinding, not rough breaking.","zh":"這個短語描述仔細研磨，而不是粗略弄碎。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":13},{"front":"crumb mixture","meaning":"粉粒混合物","examples":[{"en":"The crumb mixture is finely crushed to make it smooth.","zh":"粉粒混合物被精細研磨，以令它變得幼滑。"},{"en":"A crumb mixture is a mixture of small dry or grainy pieces before it becomes smooth.","zh":"粉粒混合物是在變得幼滑前，由細小乾粒或顆粒組成的混合物。"},{"en":"A biscuit base begins as a crumb mixture before butter holds it together.","zh":"餅乾底在被牛油黏合前，最初是粉粒混合物。"},{"en":"If the crumb mixture is not ground well, the chocolate may feel grainy.","zh":"如果粉粒混合物沒有研磨好，朱古力可能感覺有顆粒。"},{"en":"The phrase describes an intermediate texture in production.","zh":"這個短語描述生產過程中的中間質地。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":14},{"front":"make it smooth","meaning":"令它變得幼滑","examples":[{"en":"The mixture is crushed finely to make it smooth.","zh":"混合物被精細研磨，以令它變得幼滑。"},{"en":"To make it smooth means to remove roughness, lumps, or grainy texture.","zh":"“Make it smooth” 指去除粗糙、結塊或顆粒感。"},{"en":"A cook may blend soup to make it smooth.","zh":"廚師可能攪拌湯，令它變得幼滑。"},{"en":"If chocolate makers make the mixture smooth, the final product feels better in the mouth.","zh":"如果朱古力製造商令混合物變得幼滑，最終產品在口中感覺更好。"},{"en":"The phrase describes improving texture.","zh":"這個短語描述改善質地。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":14},{"front":"go through two more processes","meaning":"再經過兩個工序","examples":[{"en":"The mixture goes through two more processes before shaping.","zh":"混合物在成形前再經過兩個工序。"},{"en":"To go through two more processes means to pass through two additional steps.","zh":"“Go through two more processes” 指再通過兩個額外步驟。"},{"en":"A passport application may go through two more processes before approval.","zh":"護照申請在批准前可能再經過兩個程序。"},{"en":"If chocolate goes through two more processes, it is not ready immediately after mixing.","zh":"如果朱古力再經過兩個工序，它在混合後並不是立即完成。"},{"en":"The phrase shows that production continues before the final stage.","zh":"這個短語顯示生產在最後階段前仍會繼續。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":14},{"front":"be shaped in a mould","meaning":"在模具中成形","examples":[{"en":"The chocolate is shaped in a mould.","zh":"朱古力在模具中成形。"},{"en":"To be shaped in a mould means to be poured or pressed into a container that gives it a fixed form.","zh":"“Be shaped in a mould” 指被倒入或壓入容器中，由容器賦予固定形狀。"},{"en":"Jelly is shaped in a mould before it is served.","zh":"啫喱在上碟前會在模具中成形。"},{"en":"If chocolate is shaped in a mould, it can become bars, eggs, or small figures.","zh":"如果朱古力在模具中成形，它可以變成朱古力條、蛋形或小人物形狀。"},{"en":"The phrase explains how soft material becomes a set shape.","zh":"這個短語解釋軟材料如何變成固定形狀。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":14},{"front":"chocolate making","meaning":"朱古力製造","examples":[{"en":"Chocolate making is big business.","zh":"朱古力製造是龐大產業。"},{"en":"Chocolate making is the process and industry of turning cacao into chocolate products.","zh":"朱古力製造是把可可變成朱古力產品的過程和行業。"},{"en":"A factory tour can show visitors the steps in chocolate making.","zh":"工廠導覽可以向訪客展示朱古力製造的步驟。"},{"en":"Because many people buy chocolate, chocolate making supports farmers, factories, shops, and transport.","zh":"因為許多人購買朱古力，朱古力製造支援農民、工廠、商店和運輸。"},{"en":"The phrase can describe both the craft and the global industry.","zh":"這個短語可以描述工藝，也可以描述全球產業。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":14},{"front":"big business","meaning":"大生意；龐大產業","examples":[{"en":"Chocolate making is big business worldwide.","zh":"朱古力製造在全球是龐大產業。"},{"en":"Big business means an activity or industry involving a lot of money, companies, and customers.","zh":"“Big business” 指涉及大量金錢、公司和顧客的活動或行業。"},{"en":"Online shopping has become big business because millions of people buy things through apps.","zh":"網購已成為龐大產業，因為數百萬人透過應用程式購物。"},{"en":"If chocolate is big business, changes in cacao prices can affect many workers and firms.","zh":"如果朱古力是龐大產業，可可價格變化可以影響許多工人和企業。"},{"en":"The phrase stresses economic size and importance.","zh":"這個短語強調經濟規模和重要性。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":14},{"front":"market value","meaning":"市場價值","examples":[{"en":"The market value of the yearly cacao crop is very high.","zh":"每年可可收成的市場價值很高。"},{"en":"Market value is the amount of money something is worth in the market.","zh":"市場價值是某物在市場上值多少錢。"},{"en":"The market value of a house can rise if transport nearby improves.","zh":"如果附近交通改善，房屋的市場價值可以上升。"},{"en":"If the market value of cacao increases, farmers may earn more if they receive fair prices.","zh":"如果可可市場價值增加，而農民獲得公平價格，他們可能賺得更多。"},{"en":"The phrase connects price with economic worth.","zh":"這個短語把價格與經濟價值連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":14},{"front":"yearly cacao crop","meaning":"每年可可收成","examples":[{"en":"The yearly cacao crop is worth billions of dollars.","zh":"每年可可收成價值數十億美元。"},{"en":"The yearly cacao crop is the amount of cacao harvested around the world in one year.","zh":"每年可可收成是世界各地一年內採收的可可數量。"},{"en":"Bad weather can reduce the yearly cacao crop and push prices higher.","zh":"惡劣天氣可以減少每年可可收成，並推高價格。"},{"en":"If the yearly cacao crop is large, chocolate companies may have more supplies.","zh":"如果每年可可收成很大，朱古力公司可能有更多供應。"},{"en":"The phrase measures cacao production by year.","zh":"這個短語按年份衡量可可生產。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":14},{"front":"around the world","meaning":"世界各地","examples":[{"en":"The cacao crop is produced around the world.","zh":"可可收成在世界各地生產。"},{"en":"Around the world means in many countries or regions globally.","zh":"“Around the world” 指在全球許多國家或地區。"},{"en":"Chocolate is sold around the world in supermarkets, cafés, and airports.","zh":"朱古力在世界各地的超市、咖啡店和機場出售。"},{"en":"If a product is popular around the world, companies must manage many markets and languages.","zh":"如果產品在世界各地受歡迎，公司必須管理許多市場和語言。"},{"en":"The phrase shows wide global spread.","zh":"這個短語顯示廣泛全球分布。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":14},{"front":"more than five billion dollars","meaning":"超過五十億美元","examples":[{"en":"The yearly cacao crop is worth more than five billion dollars.","zh":"每年可可收成價值超過五十億美元。"},{"en":"More than five billion dollars means a value greater than 5,000,000,000 dollars.","zh":"“More than five billion dollars” 指價值超過5,000,000,000美元。"},{"en":"A large infrastructure project may cost more than five billion dollars.","zh":"大型基建項目可能耗資超過五十億美元。"},{"en":"If cacao is worth more than five billion dollars yearly, it is a major global crop.","zh":"如果可可每年價值超過五十億美元，它就是主要全球作物。"},{"en":"The phrase gives a very large economic value.","zh":"這個短語給出非常大的經濟價值。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":14},{"front":"especially popular in","meaning":"在……尤其受歡迎","examples":[{"en":"Chocolate is especially popular in Europe and the United States.","zh":"朱古力在歐洲和美國尤其受歡迎。"},{"en":"Especially popular in a place means liked or bought there more than in many other places.","zh":"“Especially popular in” 某地指在該地比許多其他地方更受喜愛或更常被購買。"},{"en":"Hot soup is especially popular in cold northern cities during winter.","zh":"熱湯在寒冷北方城市的冬天尤其受歡迎。"},{"en":"If chocolate is especially popular in Europe, shops there may offer many varieties.","zh":"如果朱古力在歐洲尤其受歡迎，那裡的商店可能提供許多品種。"},{"en":"The phrase highlights stronger popularity in a particular region.","zh":"這個短語強調在特定地區有更高受歡迎程度。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":14},{"front":"cocoa products","meaning":"可可製品","examples":[{"en":"The United States bought large amounts of cocoa products.","zh":"美國購買大量可可製品。"},{"en":"Cocoa products are foods or materials made from cacao, such as cocoa powder, cocoa butter, and chocolate.","zh":"可可製品是由可可製成的食物或材料，例如可可粉、可可脂和朱古力。"},{"en":"A bakery may use cocoa products to make cakes, drinks, and desserts.","zh":"麵包店可能使用可可製品製作蛋糕、飲品和甜品。"},{"en":"If a country buys many cocoa products, it has strong demand for chocolate-related goods.","zh":"如果一個國家購買許多可可製品，它對朱古力相關商品有強烈需求。"},{"en":"The phrase covers more than finished chocolate bars.","zh":"這個短語涵蓋的不只是製成的朱古力條。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":15},{"front":"an average of","meaning":"平均","examples":[{"en":"Americans eat an average of more than five kilograms of chocolate per person.","zh":"美國人平均每人吃超過五公斤朱古力。"},{"en":"An average of something is the typical amount found by sharing a total across a group.","zh":"“An average of” 某數量是把總數分配到一個群體後得到的典型數量。"},{"en":"Students in the class read an average of two books each month.","zh":"班上學生平均每月閱讀兩本書。"},{"en":"If people eat an average of five kilograms each, some eat more and some eat less.","zh":"如果人們平均每人吃五公斤，有些人吃得更多，有些人吃得更少。"},{"en":"The phrase gives a general figure, not every individual’s exact amount.","zh":"這個短語給出一般數字，而不是每個人的精確數量。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":15},{"front":"per person","meaning":"每人","examples":[{"en":"Americans eat more than five kilograms of chocolate per person each year.","zh":"美國人每年每人吃超過五公斤朱古力。"},{"en":"Per person means for each individual in a group.","zh":"“Per person” 指群體中每一個人。"},{"en":"The restaurant bill was twenty dollars per person.","zh":"餐廳帳單是每人二十美元。"},{"en":"If a country reports chocolate consumption per person, it divides total consumption by population.","zh":"如果一個國家報告每人朱古力消耗量，它會用總消耗量除以人口。"},{"en":"The phrase helps compare groups of different sizes fairly.","zh":"這個短語有助公平比較不同規模的群體。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":15},{"front":"speciality shops","meaning":"專門店","examples":[{"en":"Speciality shops that sell costly chocolates are popular.","zh":"售賣昂貴朱古力的專門店很受歡迎。"},{"en":"Speciality shops are shops that focus on one particular type of product or expert service.","zh":"專門店是專注於某一特定產品或專業服務的商店。"},{"en":"A tea speciality shop may sell rare teas and explain how to brew them.","zh":"茶葉專門店可能售賣稀有茶葉，並解釋如何沖泡。"},{"en":"If customers visit speciality shops, they often expect higher quality and expert advice.","zh":"如果顧客到專門店，通常期待較高品質和專業建議。"},{"en":"The phrase contrasts with ordinary general stores.","zh":"這個短語與普通雜貨店形成對比。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":15},{"front":"costly chocolates","meaning":"昂貴朱古力","examples":[{"en":"Speciality shops sell costly chocolates.","zh":"專門店售賣昂貴朱古力。"},{"en":"Costly chocolates are expensive chocolates, often made with rare cacao or careful methods.","zh":"昂貴朱古力是價格高的朱古力，通常使用稀有可可或仔細方法製作。"},{"en":"People may buy costly chocolates as gifts for birthdays or weddings.","zh":"人們可能購買昂貴朱古力作為生日或婚禮禮物。"},{"en":"If chocolates are costly, buyers may expect better flavour, packaging, and origin information.","zh":"如果朱古力昂貴，買家可能期待更好味道、包裝和產地資訊。"},{"en":"The phrase describes price and often suggests luxury.","zh":"這個短語描述價格，並常暗示奢侈。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":15},{"front":"chocolate lovers","meaning":"朱古力愛好者","examples":[{"en":"Many shops offer chocolate lovers the chance to taste rare chocolates.","zh":"許多商店給朱古力愛好者品嚐稀有朱古力的機會。"},{"en":"Chocolate lovers are people who enjoy chocolate very much.","zh":"朱古力愛好者是非常喜歡朱古力的人。"},{"en":"Chocolate lovers may visit festivals to try new flavours and learn about cacao origins.","zh":"朱古力愛好者可能參觀節日活動，試新口味並了解可可產地。"},{"en":"If shops serve chocolate lovers well, they may sell small batches at higher prices.","zh":"如果商店好好服務朱古力愛好者，可能以較高價格出售小批量產品。"},{"en":"The phrase describes enthusiastic consumers, not ordinary occasional buyers.","zh":"這個短語描述熱情消費者，而不是普通偶爾購買者。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":15},{"front":"the chance to","meaning":"……的機會","examples":[{"en":"Speciality shops offer customers the chance to taste different chocolates.","zh":"專門店給顧客品嚐不同朱古力的機會。"},{"en":"The chance to do something means an opportunity to do it.","zh":"“The chance to” 做某事指做該事的機會。"},{"en":"A school trip gives students the chance to learn outside the classroom.","zh":"學校旅行給學生在課室外學習的機會。"},{"en":"If customers get the chance to taste chocolate before buying, they may choose more confidently.","zh":"如果顧客在購買前有機會品嚐朱古力，他們可能更有信心選擇。"},{"en":"The phrase focuses on opportunity or access.","zh":"這個短語強調機會或接觸。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":15},{"front":"made from cacao grown in","meaning":"由種植於……的可可製成","examples":[{"en":"Some chocolates are made from cacao grown in different parts of the world.","zh":"一些朱古力由種植於世界不同地區的可可製成。"},{"en":"Made from cacao grown in a place means produced using cacao cultivated in that location.","zh":"“Made from cacao grown in” 某地指使用在該地栽培的可可製成。"},{"en":"A chocolate bar made from cacao grown in Ecuador may taste different from one made with Ghanaian cacao.","zh":"由種植於厄瓜多爾的可可製成的朱古力條，味道可能不同於使用加納可可製成的朱古力。"},{"en":"If chocolate is made from cacao grown in one region, its flavour may reflect local soil and climate.","zh":"如果朱古力由種植於某一地區的可可製成，其風味可能反映本地土壤和氣候。"},{"en":"The phrase links a product with the origin of its raw material.","zh":"這個短語把產品與原材料產地連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":15},{"front":"different parts of the world","meaning":"世界不同地區","examples":[{"en":"Chocolate can be made from cacao grown in different parts of the world.","zh":"朱古力可以由種植於世界不同地區的可可製成。"},{"en":"Different parts of the world means various countries or regions globally.","zh":"世界不同地區指全球不同國家或區域。"},{"en":"Students can learn about different parts of the world through maps, films, and food.","zh":"學生可以透過地圖、電影和食物了解世界不同地區。"},{"en":"If cacao grows in different parts of the world, chocolate can have many flavour profiles.","zh":"如果可可生長於世界不同地區，朱古力就可以有許多風味特徵。"},{"en":"The phrase highlights global variety.","zh":"這個短語強調全球多樣性。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":15},{"front":"contains the following information","meaning":"包含以下資料","examples":[{"en":"Students identify which chapter contains the following information.","zh":"學生識別哪一章包含以下資料。"},{"en":"Contains the following information means includes the details listed after the instruction.","zh":"“Contains the following information” 指包括指示後列出的細節。"},{"en":"In a reading test, students look for the paragraph that contains the following information.","zh":"在閱讀測驗中，學生尋找包含以下資料的段落。"},{"en":"If a chapter contains the following information, the answer should match that chapter, not a similar topic elsewhere.","zh":"如果某章包含以下資料，答案應配對該章，而不是其他相似題目。"},{"en":"The phrase is common in matching-information questions.","zh":"這個短語常見於資料配對題。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":15},{"front":"part of the cacao plant","meaning":"可可植物的一部分","examples":[{"en":"The question asks about the part of the cacao plant used to produce chocolate.","zh":"題目問用來生產朱古力的可可植物的一部分。"},{"en":"A part of the cacao plant is one section of the plant, such as its pod, seed, leaf, or trunk.","zh":"可可植物的一部分是植物的某個部分，例如莢果、種子、葉或樹幹。"},{"en":"Students should identify the seed as the part of the cacao plant used for chocolate.","zh":"學生應識別種子為用於朱古力的可可植物部分。"},{"en":"If a question asks about a plant part, do not answer with the whole tree unless the text says so.","zh":"如果題目問植物的一部分，除非文本這樣說，否則不要回答整棵樹。"},{"en":"The phrase helps focus attention on a specific plant component.","zh":"這個短語幫助把注意力集中於特定植物組成部分。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":15},{"front":"used to produce chocolate","meaning":"用來生產朱古力","examples":[{"en":"Cacao seeds are used to produce chocolate.","zh":"可可豆用來生產朱古力。"},{"en":"Used to produce chocolate means used as material for making chocolate.","zh":"“Used to produce chocolate” 指用作製作朱古力的材料。"},{"en":"Milk and sugar are used to produce some kinds of sweet chocolate.","zh":"牛奶和糖用來生產一些種類的甜朱古力。"},{"en":"If cacao seeds are used to produce chocolate, their quality affects the final product.","zh":"如果可可豆用來生產朱古力，其品質會影響最終產品。"},{"en":"The phrase connects an ingredient with the finished food.","zh":"這個短語把材料與完成品連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":16},{"front":"average annual chocolate consumption","meaning":"每年平均朱古力消耗量","examples":[{"en":"The question asks about average annual chocolate consumption.","zh":"題目問每年平均朱古力消耗量。"},{"en":"Average annual chocolate consumption means the typical amount of chocolate eaten per person or group each year.","zh":"每年平均朱古力消耗量指每人或每個群體每年通常吃多少朱古力。"},{"en":"A survey can compare average annual chocolate consumption between countries.","zh":"調查可以比較不同國家的每年平均朱古力消耗量。"},{"en":"If average annual chocolate consumption rises, chocolate companies may increase production.","zh":"如果每年平均朱古力消耗量上升，朱古力公司可能增加生產。"},{"en":"The phrase combines average amount with a yearly time period.","zh":"這個短語把平均數量與年度時間結合。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":16},{"front":"risks faced by","meaning":"……面對的風險","examples":[{"en":"The question asks about risks faced by farmers in the cacao business.","zh":"題目問可可業務中農民面對的風險。"},{"en":"Risks faced by someone are dangers or problems that person may have to deal with.","zh":"某人面對的風險是該人可能需要處理的危險或問題。"},{"en":"Risks faced by delivery workers include bad weather, traffic, and heavy parcels.","zh":"送貨員面對的風險包括惡劣天氣、交通和沉重包裹。"},{"en":"Risks faced by cacao farmers may include insects, disease, and unstable prices.","zh":"可可農民面對的風險可能包括昆蟲、疾病和不穩定價格。"},{"en":"The phrase focuses on who experiences the danger.","zh":"這個短語強調誰經歷危險。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":16},{"front":"cacao business","meaning":"可可業務","examples":[{"en":"Farmers face risks in the cacao business.","zh":"農民在可可業務中面對風險。"},{"en":"The cacao business is the industry of growing, selling, processing, and trading cacao.","zh":"可可業務是種植、銷售、加工和貿易可可的行業。"},{"en":"The cacao business includes farmers, buyers, factories, exporters, and chocolate companies.","zh":"可可業務包括農民、買家、工廠、出口商和朱古力公司。"},{"en":"If prices fall in the cacao business, farmers may earn less despite hard work.","zh":"如果可可業務中價格下跌，農民即使辛苦工作也可能賺得較少。"},{"en":"The phrase describes cacao as an economic activity, not only a plant.","zh":"這個短語把可可描述為經濟活動，而不只是植物。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":16},{"front":"first sweetened chocolate drink","meaning":"第一種加糖朱古力飲品","examples":[{"en":"The question asks where the first sweetened chocolate drink appeared.","zh":"題目問第一種加糖朱古力飲品在哪裡出現。"},{"en":"The first sweetened chocolate drink was the earliest version of cacao drink with sugar or sweetener added.","zh":"第一種加糖朱古力飲品是最早加入糖或甜味劑的可可飲品版本。"},{"en":"A food history lesson may ask who made the first sweetened chocolate drink.","zh":"食物歷史課可能問誰製作了第一種加糖朱古力飲品。"},{"en":"If the first sweetened chocolate drink appeared in Spain, it shows how Europeans changed cacao’s taste.","zh":"如果第一種加糖朱古力飲品出現在西班牙，這顯示歐洲人如何改變可可味道。"},{"en":"The phrase marks the beginning of chocolate becoming sweet.","zh":"這個短語標誌朱古力開始變甜。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":16},{"front":"ancient American civilisations","meaning":"古代美洲文明","examples":[{"en":"Ancient American civilisations used cacao in different ways.","zh":"古代美洲文明以不同方式使用可可。"},{"en":"Ancient American civilisations were societies in the Americas before modern times, such as the Maya and Aztecs.","zh":"古代美洲文明是現代以前美洲的社會，例如瑪雅和阿茲特克。"},{"en":"Students may study ancient American civilisations through temples, art, farming, and writing systems.","zh":"學生可能透過神廟、藝術、農業和文字系統研究古代美洲文明。"},{"en":"If ancient American civilisations used cacao in ceremonies, cacao had cultural and religious value.","zh":"如果古代美洲文明在儀式中使用可可，可可就有文化和宗教價值。"},{"en":"The phrase refers to old societies in the Americas, not the modern United States only.","zh":"這個短語指美洲的古代社會，而不只是現代美國。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":16},{"front":"obtain cacao","meaning":"取得可可","examples":[{"en":"The question asks how ancient civilisations obtained cacao.","zh":"題目問古代文明如何取得可可。"},{"en":"To obtain cacao means to get cacao by growing it, trading for it, or taking it from another source.","zh":"“Obtain cacao” 指透過種植、貿易或從其他來源取得可可。"},{"en":"A bakery may obtain cacao from a supplier rather than directly from farmers.","zh":"麵包店可能從供應商取得可可，而不是直接從農民取得。"},{"en":"If a civilisation could not grow cacao locally, it had to obtain cacao through trade.","zh":"如果一個文明不能在本地種植可可，就必須透過貿易取得可可。"},{"en":"The phrase focuses on how people got access to cacao.","zh":"這個短語強調人們如何接觸到可可。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":16},{"front":"agree with the information","meaning":"與資料一致","examples":[{"en":"Students decide whether the statements agree with the information in the passage.","zh":"學生判斷陳述是否與文章資料一致。"},{"en":"To agree with the information means to match what the passage says.","zh":"“Agree with the information” 指與文章所說內容相符。"},{"en":"In a reading test, an answer agrees with the information only if the text clearly supports it.","zh":"在閱讀測驗中，只有文本清楚支持答案時，答案才與資料一致。"},{"en":"If a statement changes “wealthy people” into “all people,” it may not agree with the information.","zh":"如果陳述把「富人」改成「所有人」，它可能不與資料一致。"},{"en":"The phrase is common in TRUE/FALSE/NOT GIVEN questions.","zh":"這個短語常見於 TRUE/FALSE/NOT GIVEN 題。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":16},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A statement is false if it contradicts the information.","zh":"如果陳述與資料相矛盾，它就是錯誤的。"},{"en":"To contradict the information means to say the opposite of what the passage says.","zh":"“Contradict the information” 指說出與文章內容相反的意思。"},{"en":"If the passage says cacao was expensive, a statement saying it was cheap contradicts the information.","zh":"如果文章說可可昂貴，而陳述說它便宜，便與資料相矛盾。"},{"en":"Students should mark FALSE when a sentence directly contradicts the text.","zh":"當句子直接與文本相矛盾時，學生應標記 FALSE。"},{"en":"The phrase helps learners distinguish false answers from not-given answers.","zh":"這個短語幫助學習者區分錯誤答案和沒有提及答案。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":16},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有相關資料，學生寫 NOT GIVEN。"},{"en":"No information on this means the passage does not say whether the statement is true or false.","zh":"“No information on this” 指文章沒有說明該陳述是真是假。"},{"en":"If the text discusses cacao farming but not workers’ ages, there is no information on this.","zh":"如果文本討論可可種植，但沒有提到工人年齡，就沒有相關資料。"},{"en":"Students should not use outside knowledge when there is no information on this in the passage.","zh":"當文章沒有相關資料時，學生不應使用外部知識作答。"},{"en":"The phrase identifies a NOT GIVEN situation.","zh":"這個短語指出 NOT GIVEN 的情況。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":16},{"front":"ceremonial use of","meaning":"……的儀式用途","examples":[{"en":"The question asks about the ceremonial use of cacao and chocolate.","zh":"題目問可可和朱古力的儀式用途。"},{"en":"The ceremonial use of something means using it in formal rituals or special events.","zh":"某物的儀式用途指在正式儀式或特別活動中使用它。"},{"en":"Flowers have ceremonial use in weddings, funerals, and public memorials.","zh":"鮮花在婚禮、葬禮和公共紀念活動中有儀式用途。"},{"en":"If cacao had ceremonial use, it carried symbolic meaning beyond taste.","zh":"如果可可有儀式用途，它就帶有超越味道的象徵意義。"},{"en":"The phrase connects an object with ritual practice.","zh":"這個短語把物件與儀式實踐連繫起來。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":16},{"front":"be restricted to","meaning":"限於……","examples":[{"en":"The question asks whether chocolate was restricted to Maya ruling families.","zh":"題目問朱古力是否限於瑪雅統治家族。"},{"en":"To be restricted to a group means only that group is allowed or able to use it.","zh":"“Be restricted to” 某群體指只有該群體被允許或能夠使用它。"},{"en":"Some school rooms are restricted to teachers because they contain private records.","zh":"一些學校房間限於老師使用，因為裡面有私人紀錄。"},{"en":"If chocolate was not restricted to ruling families, poorer people could sometimes enjoy it too.","zh":"如果朱古力不限於統治家族，較貧窮的人有時也可以享用。"},{"en":"The phrase shows a limit on access.","zh":"這個短語顯示接觸限制。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":17},{"front":"recognise something as","meaning":"將……視為","examples":[{"en":"Cortés recognised chocolate as a valuable investment.","zh":"Cortés 將朱古力視為有價值的投資。"},{"en":"To recognise something as something means to understand or identify it as having that quality or role.","zh":"“Recognise something as” 某事指理解或識別它具有某種特質或角色。"},{"en":"A teacher may recognise a quiet student as a strong writer after reading her essay.","zh":"老師讀完作文後，可能將一名安靜學生視為強大的寫作者。"},{"en":"If Cortés recognised chocolate as valuable, he saw that it could bring profit.","zh":"如果 Cortés 將朱古力視為有價值，他就看出它可能帶來利潤。"},{"en":"The phrase shows realisation and judgement.","zh":"這個短語顯示意識和判斷。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":17},{"front":"produce the best chocolate","meaning":"生產最好的朱古力","examples":[{"en":"The question asks whether the forastero tree produces the best chocolate.","zh":"題目問福拉斯特羅可可樹是否生產最好的朱古力。"},{"en":"To produce the best chocolate means to make chocolate of the highest quality or flavour.","zh":"“Produce the best chocolate” 指製作最高品質或最好味道的朱古力。"},{"en":"A baker may test different cocoa powders to see which one produces the best chocolate cake.","zh":"麵包師可能測試不同可可粉，看看哪一種能做出最好的朱古力蛋糕。"},{"en":"If a tree produces most chocolate, that does not automatically mean it produces the best chocolate.","zh":"如果一種樹生產最多朱古力，並不自動表示它生產最好的朱古力。"},{"en":"The phrase asks about quality, not quantity.","zh":"這個短語問的是品質，而不是數量。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":17},{"front":"parts of cacao seeds","meaning":"可可豆的部分","examples":[{"en":"Some parts of cacao seeds are removed during chocolate production.","zh":"可可豆的某些部分在朱古力生產過程中被去除。"},{"en":"Parts of cacao seeds are the different sections of the seeds, such as the outer coverings and inner nibs.","zh":"可可豆的部分是種子的不同部分，例如外殼和內部可可碎仁。"},{"en":"Workers separate parts of cacao seeds so only the useful material continues in the process.","zh":"工人分離可可豆的部分，使只有有用材料繼續加工。"},{"en":"If unwanted parts of cacao seeds remain, the chocolate may become rough or bitter in the wrong way.","zh":"如果可可豆中不需要的部分留下，朱古力可能變得粗糙或出現不合適的苦味。"},{"en":"The phrase focuses on components within the seed.","zh":"這個短語強調種子內部的組成部分。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":17},{"front":"during chocolate production","meaning":"在朱古力生產過程中","examples":[{"en":"The outer coverings are removed during chocolate production.","zh":"外殼在朱古力生產過程中被去除。"},{"en":"During chocolate production means while cacao is being processed into chocolate.","zh":"“During chocolate production” 指在可可被加工成朱古力期間。"},{"en":"During chocolate production, workers control temperature, texture, and ingredients carefully.","zh":"在朱古力生產過程中，工人仔細控制溫度、質地和材料。"},{"en":"If mistakes happen during chocolate production, the final product may taste poor.","zh":"如果在朱古力生產過程中出錯，最終產品可能味道差。"},{"en":"The phrase marks the manufacturing stage.","zh":"這個短語標示製造階段。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":17},{"front":"more popular in some regions than in others","meaning":"在某些地區比其他地區更受歡迎","examples":[{"en":"Chocolate is more popular in some regions than in others.","zh":"朱古力在某些地區比其他地區更受歡迎。"},{"en":"More popular in some regions than in others means liked or consumed more in certain places than elsewhere.","zh":"“More popular in some regions than in others” 指在某些地方比其他地方更受喜愛或消耗更多。"},{"en":"Spicy food is more popular in some regions than in others because tastes differ.","zh":"辛辣食物在某些地區比其他地區更受歡迎，因為口味不同。"},{"en":"If chocolate is more popular in Europe than elsewhere, shops there may sell more varieties.","zh":"如果朱古力在歐洲比其他地方更受歡迎，那裡的商店可能售賣更多品種。"},{"en":"The phrase compares popularity across places.","zh":"這個短語比較不同地方的受歡迎程度。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":17},{"front":"flow chart","meaning":"流程圖","examples":[{"en":"The flow chart shows the steps in chocolate making.","zh":"流程圖顯示朱古力製作步驟。"},{"en":"A flow chart is a diagram that shows stages in a process, often with arrows.","zh":"流程圖是顯示一個過程階段的圖表，通常有箭咀。"},{"en":"A teacher may use a flow chart to explain how water moves through the water cycle.","zh":"老師可能使用流程圖解釋水如何在水循環中移動。"},{"en":"If students follow a flow chart, they can see which step comes before the next one.","zh":"如果學生跟隨流程圖，就能看見哪一步在下一步之前。"},{"en":"The phrase is common in process diagrams and exam tasks.","zh":"這個短語常見於過程圖和考試任務。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":17},{"front":"steps in chocolate making","meaning":"朱古力製作步驟","examples":[{"en":"The flow chart shows the steps in chocolate making.","zh":"流程圖顯示朱古力製作步驟。"},{"en":"Steps in chocolate making are the stages used to turn cacao seeds into finished chocolate.","zh":"朱古力製作步驟是把可可豆變成完成朱古力所用的階段。"},{"en":"Sorting, cooking, crushing, mixing, and shaping are steps in chocolate making.","zh":"分類、烘煮、壓碎、混合和成形都是朱古力製作步驟。"},{"en":"If one step is missed, the taste or texture of chocolate may suffer.","zh":"如果漏掉其中一步，朱古力的味道或質地可能受影響。"},{"en":"The phrase focuses on the order of production.","zh":"這個短語強調生產順序。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":17},{"front":"complete the flow chart","meaning":"完成流程圖","examples":[{"en":"Candidates complete the flow chart using words from the passage.","zh":"考生使用文章中的詞語完成流程圖。"},{"en":"To complete the flow chart means to fill in missing stages or labels in the process diagram.","zh":"“Complete the flow chart” 指填寫過程圖中缺漏的階段或標籤。"},{"en":"Students should read the surrounding arrows before completing the flow chart.","zh":"學生在完成流程圖前，應先閱讀周圍箭咀。"},{"en":"If the flow chart shows production order, candidates must choose words that fit each step.","zh":"如果流程圖顯示生產順序，考生必須選擇符合每一步的詞語。"},{"en":"The phrase is a common reading-test instruction.","zh":"這個短語是閱讀測驗中的常見指示。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":17},{"front":"no more than three words","meaning":"不超過三個詞","examples":[{"en":"Candidates choose no more than three words from the passage.","zh":"考生從文章中選擇不超過三個詞。"},{"en":"No more than three words means the answer must contain three words or fewer.","zh":"“No more than three words” 指答案必須包含三個詞或更少。"},{"en":"If the instruction says no more than three words, “outer coverings” is acceptable but four words are not.","zh":"如果指示說不超過三個詞，“outer coverings” 可以接受，但四個詞不可以。"},{"en":"Students may lose marks if they write a correct idea using too many words.","zh":"如果學生用太多詞寫出正確意思，也可能失分。"},{"en":"The phrase gives a strict answer limit in exams.","zh":"這個短語在考試中給出嚴格答案限制。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":17},{"front":"sorting, cleaning and cooking","meaning":"分類、清潔和烘煮","examples":[{"en":"The first factory steps are sorting, cleaning and cooking.","zh":"最初的工廠步驟是分類、清潔和烘煮。"},{"en":"Sorting, cleaning and cooking are early preparation steps that organise, wash, and heat the cacao seeds.","zh":"分類、清潔和烘煮是早期準備步驟，用來整理、清洗和加熱可可豆。"},{"en":"Before cooking beans, a chef may do sorting, cleaning and soaking.","zh":"在煮豆前，廚師可能會進行分類、清潔和浸泡。"},{"en":"If sorting, cleaning and cooking are done badly, the final product may be unsafe or poor in taste.","zh":"如果分類、清潔和烘煮做得差，最終產品可能不安全或味道差。"},{"en":"The phrase lists actions that prepare raw material for later processing.","zh":"這個短語列出為後續加工準備原材料的動作。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":17},{"front":"removing outer coverings","meaning":"去除外殼","examples":[{"en":"The process includes removing the seeds’ outer coverings.","zh":"該過程包括去除種子的外殼。"},{"en":"Removing outer coverings means taking off the outside layer or shell of something.","zh":"“Removing outer coverings” 指拿走某物的外層或外殼。"},{"en":"Removing outer coverings from nuts can make them smoother for cooking.","zh":"去除堅果外殼可以令它們更適合幼滑烹調。"},{"en":"If workers skip removing outer coverings, unwanted rough parts may remain in the mixture.","zh":"如果工人跳過去除外殼，不需要的粗糙部分可能留在混合物中。"},{"en":"The phrase describes a preparation step that exposes the useful inside.","zh":"這個短語描述露出有用內部的準備步驟。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":18},{"front":"add sugar, milk and cocoa fat","meaning":"加入糖、牛奶和可可脂","examples":[{"en":"Chocolate makers add sugar, milk and cocoa fat.","zh":"朱古力製造商加入糖、牛奶和可可脂。"},{"en":"To add sugar, milk and cocoa fat means to put these ingredients into the chocolate mixture.","zh":"“Add sugar, milk and cocoa fat” 指把這些材料放入朱古力混合物中。"},{"en":"A baker may add sugar, milk and butter to make a cake softer and sweeter.","zh":"麵包師可能加入糖、牛奶和牛油，使蛋糕更柔軟、更甜。"},{"en":"When makers add sugar, milk and cocoa fat, the chocolate becomes sweeter, creamier, and smoother.","zh":"當製造商加入糖、牛奶和可可脂，朱古力會變得更甜、更幼滑、更順口。"},{"en":"The phrase describes a key flavour and texture step in chocolate making.","zh":"這個短語描述朱古力製作中關鍵的味道和質地步驟。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":18},{"front":"shape something in a mould","meaning":"將……放入模具成形","examples":[{"en":"Workers shape the chocolate in a mould.","zh":"工人將朱古力放入模具成形。"},{"en":"To shape something in a mould means to put soft material into a container so it hardens into a set form.","zh":"“Shape something in a mould” 指把軟材料放入容器中，使它硬化成固定形狀。"},{"en":"Children can shape jelly in a mould to make stars, hearts, or animals.","zh":"孩子可以將啫喱放入模具成形，製作星星、心形或動物。"},{"en":"If workers shape chocolate in a mould, each piece can have the same size and design.","zh":"如果工人將朱古力放入模具成形，每件朱古力都可以有相同大小和設計。"},{"en":"The phrase explains how a mixture becomes a final visible product.","zh":"這個短語解釋混合物如何變成最終可見產品。"}],"source":"130 - The Cacao - A Sweet history.pdf","sourcePage":18}],"ielts/reading/passage-2/Practice 131":[{"front":"conflicting climatic phenomena","meaning":"相互矛盾的氣候現象","examples":[{"en":"Conflicting climatic phenomena appear to have coexisted on early Mars.","zh":"相互矛盾的氣候現象似乎曾在早期火星上共存。"},{"en":"Conflicting climatic phenomena are climate signs that seem to disagree with each other.","zh":"相互矛盾的氣候現象是看似彼此不一致的氣候跡象。"},{"en":"A region with both drought warnings and flood damage may show conflicting climatic phenomena.","zh":"一個地區同時有乾旱警告和洪水破壞，可能顯示相互矛盾的氣候現象。"},{"en":"Conflicting climatic phenomena can confuse scientists because one sign suggests heat while another suggests cold.","zh":"相互矛盾的氣候現象會令科學家困惑，因為一個跡象顯示炎熱，另一個卻顯示寒冷。"},{"en":"This phrase is useful when evidence points in different climate directions at the same time.","zh":"當證據同時指向不同氣候方向時，這個片語很有用。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":1},{"front":"coexist on Mars","meaning":"在火星上共存","examples":[{"en":"Wet conditions and a cold climate may have coexisted on Mars.","zh":"潮濕條件和寒冷氣候可能曾在火星上共存。"},{"en":"To coexist on Mars means to exist on Mars at the same time.","zh":"coexist on Mars 指同時存在於火星上。"},{"en":"Ice and ancient river valleys may have coexisted on Mars in different regions or periods.","zh":"冰和古代河谷可能曾在火星上不同地區或時期共存。"},{"en":"If warmth and cold coexisted on Mars, scientists need a more complex climate explanation.","zh":"如果溫暖和寒冷曾在火星上共存，科學家就需要更複雜的氣候解釋。"},{"en":"This phrase shows that two things can be present together even if they seem contradictory.","zh":"這個片語顯示兩件事即使看似矛盾，也可以同時存在。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":1},{"front":"signs of wetness","meaning":"有水存在的跡象","examples":[{"en":"Signs of wetness keep pouring in from studies of Mars.","zh":"來自火星研究的有水存在跡象不斷湧現。"},{"en":"Signs of wetness are clues showing that water may be present or was present before.","zh":"signs of wetness 是顯示水現在可能存在或過去曾存在的線索。"},{"en":"Mud on shoes and water marks on the floor are signs of wetness after rain.","zh":"雨後鞋上的泥和地板上的水痕都是有水存在的跡象。"},{"en":"On Mars, river valleys and deltas are signs of wetness from the past.","zh":"在火星上，河谷和三角洲是過去有水存在的跡象。"},{"en":"This phrase does not prove an ocean by itself, but it suggests water-related conditions.","zh":"這個片語本身不證明有海洋，但它暗示與水有關的條件。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":1},{"front":"keep pouring in","meaning":"不斷湧現","examples":[{"en":"Evidence about ancient water on Mars keeps pouring in.","zh":"關於火星古代水的證據不斷湧現。"},{"en":"If information keeps pouring in, it arrives continuously and in large amounts.","zh":"如果資料 keeps pouring in，意思是它持續而大量到來。"},{"en":"After a school notice is sent, questions from parents may keep pouring in.","zh":"學校通告發出後，家長問題可能不斷湧現。"},{"en":"When new data keeps pouring in, researchers may need to update their explanation.","zh":"當新數據不斷湧現，研究人員可能需要更新解釋。"},{"en":"This phrase suggests a steady flow, not just one small piece of evidence.","zh":"這個片語暗示持續流入，而不只是單一小證據。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":1},{"front":"deeply carved river valleys","meaning":"深切的河谷","examples":[{"en":"Deeply carved river valleys suggest that water once flowed on Mars.","zh":"深切的河谷顯示水曾在火星上流動。"},{"en":"Deeply carved river valleys are deep channels cut into land by flowing water over time.","zh":"deeply carved river valleys 是流水長時間切割土地形成的深深河道。"},{"en":"On Earth, deeply carved river valleys can form when rivers wear down rock for many years.","zh":"在地球上，河流多年侵蝕岩石可以形成深切的河谷。"},{"en":"If Mars has deeply carved river valleys, scientists may infer that liquid water once moved there.","zh":"如果火星有深切的河谷，科學家可能推斷液態水曾在那裡流動。"},{"en":"This phrase describes a strong landscape clue left by ancient flow.","zh":"這個片語描述古代水流留下的強烈地貌線索。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":1},{"front":"vast deltas","meaning":"巨大的三角洲","examples":[{"en":"Vast deltas are among the signs of ancient water on Mars.","zh":"巨大的三角洲是火星古代有水跡象之一。"},{"en":"Vast deltas are very large landforms made when rivers deposit sediment where they meet standing water.","zh":"vast deltas 是河流在流入靜止水體時沉積泥沙形成的巨大地貌。"},{"en":"The Nile Delta is a famous example of a vast delta on Earth.","zh":"尼羅河三角洲是地球上一個著名的巨大三角洲。"},{"en":"If a planet has vast deltas, it may once have had rivers flowing into lakes or seas.","zh":"如果一顆行星有巨大三角洲，它可能曾有河流流入湖泊或海洋。"},{"en":"This phrase suggests both flowing water and places where water collected.","zh":"這個片語暗示既有流水，也有水聚集的地方。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":1},{"front":"widespread remnants of","meaning":"廣泛分布的……遺跡","examples":[{"en":"Scientists have found widespread remnants of evaporating seas.","zh":"科學家發現了廣泛分布的蒸發海洋遺跡。"},{"en":"Widespread remnants of something are remains found over a large area.","zh":"widespread remnants of something 是在大範圍內找到的殘留物。"},{"en":"Widespread remnants of old buildings can show that a town was once much larger.","zh":"廣泛分布的舊建築遺跡可以顯示城鎮曾經大得多。"},{"en":"If widespread remnants of seas exist, scientists may suspect that water once covered large areas.","zh":"如果存在廣泛分布的海洋遺跡，科學家可能懷疑水曾覆蓋大片地區。"},{"en":"This phrase focuses on leftover evidence spread across many places.","zh":"這個片語聚焦於分布在多處的殘留證據。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":1},{"front":"evaporating seas","meaning":"正在蒸發的海洋","examples":[{"en":"Remnants of evaporating seas suggest a wetter Martian past.","zh":"正在蒸發的海洋遺跡顯示火星過去較濕潤。"},{"en":"Evaporating seas are seas losing water as liquid changes into vapour.","zh":"evaporating seas 是因液態水變成水蒸氣而逐漸失水的海洋。"},{"en":"A lake can leave salt deposits behind if it keeps evaporating in a dry climate.","zh":"如果湖泊在乾燥氣候中持續蒸發，可能留下鹽類沉積物。"},{"en":"If Mars had evaporating seas, minerals may have been left on the surface.","zh":"如果火星曾有正在蒸發的海洋，礦物可能被留在表面。"},{"en":"This phrase points to water that once existed but gradually disappeared.","zh":"這個片語指曾經存在但逐漸消失的水。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":1},{"front":"convince many experts that","meaning":"令許多專家相信","examples":[{"en":"The evidence has convinced many experts that Mars once had liquid water.","zh":"這些證據令許多專家相信火星曾有液態水。"},{"en":"To convince many experts that something is true means to provide enough evidence for specialists to believe it.","zh":"convince many experts that something is true 指提供足夠證據，令專家相信某事是真的。"},{"en":"Clear test results can convince many doctors that a treatment is working.","zh":"清楚的測試結果可以令許多醫生相信治療正在奏效。"},{"en":"If repeated observations agree, they can convince many experts that a theory is likely correct.","zh":"如果重複觀察結果一致，它們可以令許多專家相信理論很可能正確。"},{"en":"This phrase suggests strong evidence, not just a casual opinion.","zh":"這個片語暗示有力證據，而不只是隨意意見。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":1},{"front":"liquid water","meaning":"液態水","examples":[{"en":"Liquid water may have covered large parts of Mars.","zh":"液態水可能曾覆蓋火星大部分地區。"},{"en":"Liquid water is water in flowing or fluid form, not ice or vapour.","zh":"liquid water 是流動或液體形態的水，不是冰或水蒸氣。"},{"en":"Plants, animals, and people need liquid water for basic survival.","zh":"植物、動物和人類都需要液態水來基本生存。"},{"en":"If a planet once had liquid water, scientists may ask whether it could have supported life.","zh":"如果一顆行星曾有液態水，科學家可能會問它是否曾能支持生命。"},{"en":"This phrase is important because liquid water behaves differently from frozen water.","zh":"這個片語很重要，因為液態水的行為不同於冰凍水。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":1},{"front":"large parts of","meaning":"……的大部分","examples":[{"en":"Liquid water may have covered large parts of the Red Planet.","zh":"液態水可能曾覆蓋紅色星球的大部分地區。"},{"en":"Large parts of something means a great portion of it, though not necessarily all of it.","zh":"large parts of something 指某物很大部分，但不一定是全部。"},{"en":"Heavy rain flooded large parts of the city after the storm.","zh":"暴風雨後，大雨淹浸了城市的大部分地區。"},{"en":"If disease affects large parts of a crop, farmers may lose much of the harvest.","zh":"如果疾病影響農作物的大部分，農民可能失去大部分收成。"},{"en":"This phrase describes broad coverage without claiming complete coverage.","zh":"這個片語描述廣泛覆蓋，但不聲稱完全覆蓋。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":1},{"front":"the Red Planet","meaning":"紅色星球；火星","examples":[{"en":"Mars is often called the Red Planet.","zh":"火星常被稱為紅色星球。"},{"en":"The Red Planet is a common nickname for Mars because it looks reddish from iron-rich dust.","zh":"the Red Planet 是火星的常見別名，因為含鐵塵埃令它看起來偏紅。"},{"en":"Students may hear the Red Planet mentioned in lessons about space exploration.","zh":"學生可能在太空探索課堂中聽到紅色星球。"},{"en":"When scientists discuss the Red Planet, they are usually referring to Mars.","zh":"當科學家討論紅色星球時，他們通常是在指火星。"},{"en":"This phrase is a descriptive nickname, not a separate planet.","zh":"這個片語是描述性別名，而不是另一顆行星。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":2},{"front":"for a billion years or more","meaning":"長達十億年或更久","examples":[{"en":"Water may have covered Mars for a billion years or more.","zh":"水可能曾覆蓋火星長達十億年或更久。"},{"en":"For a billion years or more means for at least one thousand million years.","zh":"for a billion years or more 指至少十億年。"},{"en":"A mountain range may change slowly over millions of years, but a billion years or more is far longer.","zh":"山脈可能在數百萬年間慢慢改變，但十億年或更久遠遠更長。"},{"en":"If a condition lasted for a billion years or more, it could shape an entire planet’s surface.","zh":"如果某種條件持續十億年或更久，它可以塑造整顆行星表面。"},{"en":"This phrase describes an extremely long period of time.","zh":"這個片語描述極長時間。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":2},{"front":"efforts to explain","meaning":"解釋……的努力","examples":[{"en":"Most efforts to explain Martian climate have come up dry.","zh":"大多數解釋火星氣候的努力都未能得出結果。"},{"en":"Efforts to explain something are attempts to understand and describe why it happened.","zh":"efforts to explain something 是嘗試理解並說明某事為何發生。"},{"en":"Teachers may make efforts to explain a difficult grammar rule with examples.","zh":"老師可能努力用例子解釋困難文法規則。"},{"en":"If efforts to explain a problem fail, researchers may need a new theory.","zh":"如果解釋問題的努力失敗，研究人員可能需要新理論。"},{"en":"This phrase focuses on attempts at understanding, not final proof.","zh":"這個片語聚焦於理解的嘗試，而不是最終證明。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":2},{"front":"Martian climate","meaning":"火星氣候","examples":[{"en":"Scientists are trying to explain the ancient Martian climate.","zh":"科學家正在嘗試解釋古代火星氣候。"},{"en":"Martian climate means the climate of Mars, including its temperature, atmosphere, and water conditions.","zh":"Martian climate 指火星的氣候，包括氣溫、大氣和水分條件。"},{"en":"Researchers study rocks and valleys to learn about Martian climate in the past.","zh":"研究人員研究岩石和河谷，以了解過去火星氣候。"},{"en":"If Martian climate was once warmer, liquid water may have existed on the surface.","zh":"如果火星氣候曾較溫暖，液態水可能曾存在於表面。"},{"en":"This phrase refers to climate on Mars, not Earth’s climate.","zh":"這個片語指火星上的氣候，而不是地球氣候。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":2},{"front":"permit such clement conditions","meaning":"允許這樣溫和的條件存在","examples":[{"en":"Scientists wonder how Martian climate permitted such clement conditions.","zh":"科學家想知道火星氣候如何允許這樣溫和的條件存在。"},{"en":"To permit such clement conditions means to allow such mild and life-friendly conditions to exist.","zh":"permit such clement conditions 指容許這樣溫和且較適合生命的條件存在。"},{"en":"A warm classroom and good lighting permit clement conditions for study.","zh":"溫暖課室和良好照明容許適合學習的溫和條件存在。"},{"en":"If a planet’s atmosphere permits clement conditions, liquid water may stay stable.","zh":"如果一顆行星的大氣容許溫和條件存在，液態水可能保持穩定。"},{"en":"This phrase asks how a harsh place could allow milder conditions.","zh":"這個片語詢問一個嚴酷地方如何能容許較溫和條件。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":2},{"front":"clement conditions","meaning":"溫和氣候條件","examples":[{"en":"Ancient Mars may once have had clement conditions.","zh":"古代火星可能曾有溫和氣候條件。"},{"en":"Clement conditions are mild, favourable, and not too harsh.","zh":"clement conditions 是溫和、有利且不太嚴酷的條件。"},{"en":"A picnic needs clement conditions, such as gentle weather and no heavy rain.","zh":"野餐需要溫和條件，例如天氣舒適且沒有大雨。"},{"en":"Clement conditions on a planet could allow water to remain liquid.","zh":"行星上的溫和條件可能容許水保持液態。"},{"en":"This phrase is more formal than simply saying nice weather.","zh":"這個片語比簡單說 nice weather 更正式。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":2},{"front":"come up dry","meaning":"未能得出結果；徒勞無功","examples":[{"en":"Most attempts to explain the warm, wet climate have come up dry.","zh":"大多數解釋溫暖濕潤氣候的嘗試都未能得出結果。"},{"en":"To come up dry means to fail to find an answer, result, or useful evidence.","zh":"come up dry 指未能找到答案、結果或有用證據。"},{"en":"A student may search an article for an answer but come up dry.","zh":"學生可能在文章中尋找答案，但最後未能找到。"},{"en":"If police interviews come up dry, investigators may need new leads.","zh":"如果警方訪問徒勞無功，調查員可能需要新線索。"},{"en":"This phrase is informal and means the attempt produced nothing useful.","zh":"這個片語較口語，意思是嘗試沒有產生有用結果。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":2},{"front":"bitterly cold and parched","meaning":"極度寒冷而乾旱","examples":[{"en":"Mars is bitterly cold and parched today.","zh":"火星今天極度寒冷而乾旱。"},{"en":"Bitterly cold and parched means extremely cold and extremely dry.","zh":"bitterly cold and parched 指極度寒冷而且極度乾燥。"},{"en":"A desert at night can feel bitterly cold and parched after a hot dry day.","zh":"沙漠在炎熱乾燥一天後，夜晚可能感覺極度寒冷而乾旱。"},{"en":"If a place is bitterly cold and parched, liquid water is unlikely to stay on the surface.","zh":"如果一個地方極度寒冷而乾旱，液態水不太可能留在表面。"},{"en":"This phrase combines temperature and dryness to describe a harsh environment.","zh":"這個片語結合溫度和乾燥程度來描述嚴酷環境。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":2},{"front":"potent greenhouse atmosphere","meaning":"強大的溫室大氣層","examples":[{"en":"Mars needed a potent greenhouse atmosphere to sustain liquid water.","zh":"火星需要強大的溫室大氣層來維持液態水。"},{"en":"A potent greenhouse atmosphere is a strong atmosphere that traps heat effectively.","zh":"potent greenhouse atmosphere 是能有效困住熱力的強大大氣層。"},{"en":"A planet with a potent greenhouse atmosphere may stay warmer than expected.","zh":"擁有強大溫室大氣層的行星可能比預期更溫暖。"},{"en":"Without a potent greenhouse atmosphere, early Mars might have been too cold for liquid water.","zh":"沒有強大的溫室大氣層，早期火星可能太冷，無法有液態水。"},{"en":"This phrase connects atmospheric gases with surface warmth.","zh":"這個片語把大氣氣體與表面溫暖連接起來。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":2},{"front":"sustain its watery past","meaning":"維持其曾經有水的過去","examples":[{"en":"A greenhouse atmosphere may have helped Mars sustain its watery past.","zh":"溫室大氣層可能幫助火星維持其曾經有水的過去。"},{"en":"To sustain its watery past means to keep water-related conditions going for a long time.","zh":"sustain its watery past 指長時間維持與水有關的條件。"},{"en":"A lake region needs steady rainfall to sustain its watery environment.","zh":"湖泊地區需要穩定降雨來維持其多水環境。"},{"en":"If Mars could sustain its watery past, rivers and lakes may have lasted long enough to shape the land.","zh":"如果火星能維持曾經有水的狀態，河流和湖泊可能存在得足夠久，以塑造地貌。"},{"en":"This phrase suggests maintaining water, not simply having it once.","zh":"這個片語暗示維持水的存在，而不只是曾經有水。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":2},{"front":"watery past","meaning":"曾經有水的過去","examples":[{"en":"Scientists are trying to explain Mars’s watery past.","zh":"科學家正在嘗試解釋火星曾經有水的過去。"},{"en":"A watery past means a past period when water was more common or important.","zh":"watery past 指過去某段時期水較常見或較重要。"},{"en":"Rocks, valleys, and minerals can reveal a planet’s watery past.","zh":"岩石、河谷和礦物可以揭示一顆行星曾經有水的過去。"},{"en":"If Mars had a watery past, it may once have had rivers, lakes, or seas.","zh":"如果火星曾經有水，它可能曾有河流、湖泊或海洋。"},{"en":"This phrase contrasts a formerly wet state with a drier present.","zh":"這個片語把昔日潮濕狀態與現今較乾燥狀態作對比。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":2},{"front":"a thick layer of","meaning":"厚厚一層……","examples":[{"en":"A thick layer of carbon dioxide may have surrounded young Mars.","zh":"厚厚一層二氧化碳可能曾包圍年輕的火星。"},{"en":"A thick layer of something is a deep or dense covering of that material.","zh":"a thick layer of something 指由某物形成的深厚或濃密覆蓋層。"},{"en":"A thick layer of snow can cover roads after a storm.","zh":"暴風雪後，厚厚一層雪可以覆蓋道路。"},{"en":"If a planet has a thick layer of gas, it may affect how heat escapes into space.","zh":"如果行星有厚厚一層氣體，它可能影響熱力如何逃逸到太空。"},{"en":"This phrase describes amount and coverage together.","zh":"這個片語同時描述數量和覆蓋。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":3},{"front":"heat-trapping carbon dioxide","meaning":"捕熱二氧化碳","examples":[{"en":"Heat-trapping carbon dioxide may have warmed early Mars.","zh":"捕熱二氧化碳可能曾使早期火星變暖。"},{"en":"Heat-trapping carbon dioxide is carbon dioxide that helps hold warmth in an atmosphere.","zh":"heat-trapping carbon dioxide 是幫助大氣留住熱力的二氧化碳。"},{"en":"On Earth, heat-trapping carbon dioxide contributes to rising temperatures.","zh":"在地球上，捕熱二氧化碳會導致氣溫上升。"},{"en":"If early Mars had enough heat-trapping carbon dioxide, its surface could have stayed warmer.","zh":"如果早期火星有足夠捕熱二氧化碳，其表面可能保持較溫暖。"},{"en":"This phrase explains the warming role of carbon dioxide.","zh":"這個片語解釋二氧化碳的增溫作用。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":3},{"front":"from volcanoes","meaning":"來自火山的","examples":[{"en":"Carbon dioxide from volcanoes probably shrouded the young planet.","zh":"來自火山的二氧化碳很可能籠罩這顆年輕行星。"},{"en":"From volcanoes means produced or released by volcanic activity.","zh":"from volcanoes 指由火山活動產生或釋放。"},{"en":"Ash from volcanoes can spread through the air after an eruption.","zh":"來自火山的火山灰可以在爆發後在空氣中擴散。"},{"en":"Gases from volcanoes can build up in a planet’s atmosphere over time.","zh":"來自火山的氣體可以隨時間在行星大氣中積聚。"},{"en":"This phrase identifies volcanoes as the source.","zh":"這個片語指出火山是來源。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":3},{"front":"shroud the young planet","meaning":"籠罩這顆年輕行星","examples":[{"en":"Volcanic gases may have shrouded the young planet.","zh":"火山氣體可能曾籠罩這顆年輕行星。"},{"en":"To shroud the young planet means to surround or cover an early planet like a blanket.","zh":"shroud the young planet 指像毯子一樣包圍或覆蓋一顆早期行星。"},{"en":"Thick fog can shroud a town and make buildings hard to see.","zh":"濃霧可以籠罩城鎮，令建築物難以看見。"},{"en":"If gases shroud a planet, they may change how much heat escapes.","zh":"如果氣體籠罩一顆行星，它們可能改變熱力逃逸的程度。"},{"en":"This phrase gives a visual image of a planet wrapped in gas.","zh":"這個片語給出行星被氣體包裹的視覺畫面。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":3},{"front":"climate models","meaning":"氣候模型","examples":[{"en":"Climate models indicate that CO2 alone was insufficient.","zh":"氣候模型顯示單靠二氧化碳並不足夠。"},{"en":"Climate models are computer-based tools used to simulate climate systems.","zh":"climate models 是用來模擬氣候系統的電腦工具。"},{"en":"Scientists use climate models to test how gases, sunlight, and clouds may affect temperature.","zh":"科學家使用氣候模型測試氣體、陽光和雲層如何影響氣溫。"},{"en":"If climate models fail to explain evidence, researchers may add new factors.","zh":"如果氣候模型不能解釋證據，研究人員可能加入新因素。"},{"en":"This phrase refers to scientific simulations, not simple guesses.","zh":"這個片語指科學模擬，而不是簡單猜測。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":3},{"front":"indicate time and again that","meaning":"一再顯示","examples":[{"en":"Climate models indicate time and again that CO2 alone could not warm Mars enough.","zh":"氣候模型一再顯示，單靠二氧化碳不能把火星加熱到足夠程度。"},{"en":"To indicate time and again that something is true means to show it repeatedly.","zh":"indicate time and again that something is true 指反覆顯示某事是真的。"},{"en":"Exam results may indicate time and again that students need more reading practice.","zh":"考試結果可能一再顯示學生需要更多閱讀練習。"},{"en":"If data indicate time and again that a policy fails, leaders should reconsider it.","zh":"如果數據一再顯示某政策失敗，領袖應重新考慮它。"},{"en":"This phrase stresses repeated evidence, not a single result.","zh":"這個片語強調重複證據，而不是單一結果。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":3},{"front":"CO2 alone","meaning":"單靠二氧化碳","examples":[{"en":"CO2 alone could not have kept the Martian surface above freezing.","zh":"單靠二氧化碳不可能使火星表面保持在冰點以上。"},{"en":"CO2 alone means carbon dioxide by itself, without help from other gases or factors.","zh":"CO2 alone 指二氧化碳本身，不包括其他氣體或因素幫助。"},{"en":"Money alone cannot make a school good if teachers are not well trained.","zh":"單靠金錢不能令學校變好，如果老師沒有良好培訓。"},{"en":"If CO2 alone was insufficient, scientists must look for another warming partner.","zh":"如果單靠二氧化碳不足，科學家必須尋找另一個增溫伙伴。"},{"en":"This phrase highlights that one factor is not enough by itself.","zh":"這個片語強調單一因素本身不足夠。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":3},{"front":"keep the surface above freezing","meaning":"使表面保持在冰點以上","examples":[{"en":"CO2 alone could not have kept the surface above freezing.","zh":"單靠二氧化碳不可能使表面保持在冰點以上。"},{"en":"To keep the surface above freezing means to keep the surface warmer than the temperature at which water freezes.","zh":"keep the surface above freezing 指使表面維持在水會結冰的溫度以上。"},{"en":"Salt on roads can help keep the surface above freezing in mild winter weather.","zh":"在不太嚴寒的冬季天氣中，道路上的鹽可以幫助表面保持在冰點以上。"},{"en":"If a planet’s surface stays above freezing, liquid water can exist more easily.","zh":"如果行星表面保持在冰點以上，液態水較容易存在。"},{"en":"This phrase connects temperature with whether water becomes ice.","zh":"這個片語把溫度與水是否結冰連接起來。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":3},{"front":"inspired by","meaning":"受……啟發","examples":[{"en":"Scientists were inspired by the discovery of sulfur minerals.","zh":"科學家受硫礦物的發現啟發。"},{"en":"Inspired by something means encouraged or given a new idea because of it.","zh":"inspired by something 指因某事而受到鼓勵或得到新想法。"},{"en":"A student may be inspired by a teacher’s story to study harder.","zh":"學生可能受老師的故事啟發而更努力學習。"},{"en":"If scientists are inspired by a discovery, they may develop a new hypothesis.","zh":"如果科學家受某項發現啟發，他們可能發展新假說。"},{"en":"This phrase shows the source of motivation or new thinking.","zh":"這個片語顯示動機或新思考的來源。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":3},{"front":"surprising discovery","meaning":"令人意外的發現","examples":[{"en":"A surprising discovery changed scientists’ ideas about Mars.","zh":"一項令人意外的發現改變了科學家對火星的想法。"},{"en":"A surprising discovery is a finding that people did not expect.","zh":"surprising discovery 是人們沒有預期到的發現。"},{"en":"A doctor may make a surprising discovery when a simple test reveals a hidden illness.","zh":"當簡單檢查揭示隱藏疾病時，醫生可能有令人意外的發現。"},{"en":"Surprising discoveries can force researchers to question old explanations.","zh":"令人意外的發現可以迫使研究人員質疑舊解釋。"},{"en":"This phrase suggests that new evidence changes what people thought before.","zh":"這個片語暗示新證據改變了人們之前的想法。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":3},{"front":"sulfur minerals","meaning":"硫礦物","examples":[{"en":"Sulfur minerals are pervasive in Martian soil.","zh":"硫礦物普遍存在於火星土壤中。"},{"en":"Sulfur minerals are minerals that contain sulfur.","zh":"sulfur minerals 是含有硫的礦物。"},{"en":"On Earth, sulfur minerals can form near volcanoes, hot springs, or evaporating water.","zh":"在地球上，硫礦物可以在火山、溫泉或蒸發水體附近形成。"},{"en":"If sulfur minerals are common on Mars, sulfur gases may have affected its ancient environment.","zh":"如果硫礦物在火星上常見，硫氣體可能曾影響其古代環境。"},{"en":"This phrase points to chemical evidence found in rocks or soil.","zh":"這個片語指在岩石或土壤中找到的化學證據。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":3},{"front":"be pervasive in","meaning":"普遍存在於……","examples":[{"en":"Sulfur minerals are pervasive in the Martian soil.","zh":"硫礦物普遍存在於火星土壤中。"},{"en":"To be pervasive in something means to be widespread throughout it.","zh":"be pervasive in something 指廣泛分布於某物之中。"},{"en":"Smartphones are pervasive in modern schools, homes, and workplaces.","zh":"智能電話普遍存在於現代學校、家庭和工作場所中。"},{"en":"If a chemical is pervasive in soil, scientists may suspect a large-scale process created it.","zh":"如果某化學物質普遍存在於土壤中，科學家可能懷疑有大規模過程造成它。"},{"en":"This phrase suggests broad presence, not a rare trace.","zh":"這個片語暗示廣泛存在，而不是罕見痕跡。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":4},{"front":"Martian soil","meaning":"火星土壤","examples":[{"en":"Scientists found sulfur minerals in Martian soil.","zh":"科學家在火星土壤中發現硫礦物。"},{"en":"Martian soil is the loose surface material found on Mars.","zh":"Martian soil 是火星表面的鬆散物質。"},{"en":"A rover can collect Martian soil to study minerals and chemical signs.","zh":"火星車可以收集火星土壤，以研究礦物和化學跡象。"},{"en":"If Martian soil contains certain minerals, scientists can infer past water or volcanic activity.","zh":"如果火星土壤含有某些礦物，科學家可以推斷過去有水或火山活動。"},{"en":"This phrase refers to soil on Mars, not garden soil on Earth.","zh":"這個片語指火星上的土壤，而不是地球花園泥土。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":4},{"front":"begin to suspect that","meaning":"開始懷疑","examples":[{"en":"Scientists are beginning to suspect that sulfur dioxide helped warm Mars.","zh":"科學家開始懷疑二氧化硫幫助火星增溫。"},{"en":"To begin to suspect that something is true means to start thinking it may be true.","zh":"begin to suspect that something is true 指開始認為某事可能是真的。"},{"en":"A teacher may begin to suspect that a student is struggling if homework quality suddenly falls.","zh":"如果功課質素突然下降，老師可能開始懷疑學生正在遇到困難。"},{"en":"Scientists begin to suspect a new explanation when old theories cannot explain the evidence.","zh":"當舊理論不能解釋證據時，科學家會開始懷疑有新解釋。"},{"en":"This phrase shows early doubt or early belief, not final certainty.","zh":"這個片語顯示初步懷疑或初步相信，而不是最終確定。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":4},{"front":"warm-up partner","meaning":"增溫伙伴","examples":[{"en":"CO2 may have had sulfur dioxide as a warm-up partner.","zh":"二氧化碳可能有二氧化硫作為增溫伙伴。"},{"en":"A warm-up partner is another factor that helps increase temperature together with the main factor.","zh":"warm-up partner 是與主要因素一起幫助升高溫度的另一因素。"},{"en":"In a cold room, sunlight may act as a warm-up partner to a small heater.","zh":"在寒冷房間中，陽光可能作為小暖爐的增溫伙伴。"},{"en":"If CO2 needed a warm-up partner, sulfur dioxide may have provided extra heat-trapping power.","zh":"如果二氧化碳需要增溫伙伴，二氧化硫可能提供額外捕熱能力。"},{"en":"This phrase is informal and describes cooperation in warming.","zh":"這個片語較口語，用來描述增溫方面的合作。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":4},{"front":"sulfur dioxide","meaning":"二氧化硫","examples":[{"en":"Sulfur dioxide may have contributed to greenhouse warming on Mars.","zh":"二氧化硫可能曾導致火星上的溫室增溫。"},{"en":"Sulfur dioxide is a gas made of sulfur and oxygen.","zh":"sulfur dioxide 是由硫和氧組成的氣體。"},{"en":"Volcanoes can release sulfur dioxide during eruptions.","zh":"火山爆發期間可以釋放二氧化硫。"},{"en":"If sulfur dioxide stays in an atmosphere, it can affect chemistry, rainfall, and temperature.","zh":"如果二氧化硫留在大氣中，它可以影響化學、降雨和溫度。"},{"en":"This phrase names a gas that may have helped explain early Martian warmth.","zh":"這個片語指一種可能幫助解釋早期火星溫暖的氣體。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":4},{"front":"common gas emitted when","meaning":"當……時排放的常見氣體","examples":[{"en":"Sulfur dioxide is a common gas emitted when volcanoes erupt.","zh":"二氧化硫是火山爆發時排放的常見氣體。"},{"en":"A common gas emitted when something happens is a gas usually released during that event.","zh":"common gas emitted when something happens 指在某事件中通常被釋放的氣體。"},{"en":"Carbon dioxide is a common gas emitted when petrol is burned in car engines.","zh":"二氧化碳是汽車引擎燃燒汽油時排放的常見氣體。"},{"en":"If volcanoes erupt often, common gases emitted during eruptions may build up in the atmosphere.","zh":"如果火山經常爆發，爆發期間排放的常見氣體可能在大氣中積聚。"},{"en":"This phrase connects a gas with the event that releases it.","zh":"這個片語把氣體與釋放它的事件連接起來。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":4},{"front":"volcanoes erupt","meaning":"火山爆發","examples":[{"en":"Sulfur dioxide is released when volcanoes erupt.","zh":"火山爆發時會釋放二氧化硫。"},{"en":"Volcanoes erupt when hot rock, ash, and gases burst out from inside Earth or another planet.","zh":"volcanoes erupt 指熱岩、火山灰和氣體從地球或另一顆行星內部噴出。"},{"en":"When volcanoes erupt near towns, people may need to leave for safety.","zh":"當火山在城鎮附近爆發，人們可能需要為安全離開。"},{"en":"If volcanoes erupt repeatedly, they can release large amounts of gas into the atmosphere.","zh":"如果火山反覆爆發，它們可以把大量氣體釋放到大氣中。"},{"en":"This phrase describes an active volcanic event, not a quiet mountain.","zh":"這個片語描述活躍的火山事件，而不是安靜的山。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":4},{"front":"a frequent occurrence","meaning":"經常發生的事","examples":[{"en":"Volcanic eruptions were a frequent occurrence on young Mars.","zh":"火山爆發在年輕火星上是經常發生的事。"},{"en":"A frequent occurrence is something that happens often.","zh":"a frequent occurrence 是經常發生的事情。"},{"en":"Traffic jams are a frequent occurrence near the tunnel during rush hour.","zh":"繁忙時間隧道附近交通擠塞是經常發生的事。"},{"en":"If volcanic eruptions were a frequent occurrence, gases would be released again and again.","zh":"如果火山爆發是經常發生的事，氣體便會一次又一次被釋放。"},{"en":"This phrase stresses repeated events, not one unusual event.","zh":"這個片語強調重複事件，而不是一次罕見事件。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":4},{"front":"early atmosphere","meaning":"早期大氣層","examples":[{"en":"A small amount of SO2 in Mars’s early atmosphere could have warmed the planet.","zh":"火星早期大氣層中的少量二氧化硫可能曾使這顆行星變暖。"},{"en":"Early atmosphere means the atmosphere of a planet during its early history.","zh":"early atmosphere 指一顆行星在早期歷史中的大氣層。"},{"en":"Scientists study Earth’s early atmosphere to understand how life became possible.","zh":"科學家研究地球早期大氣層，以理解生命如何變得可能。"},{"en":"If Mars’s early atmosphere contained special gases, its climate may have been different from today.","zh":"如果火星早期大氣層含有特殊氣體，其氣候可能與今日不同。"},{"en":"This phrase places atmospheric conditions in the distant past.","zh":"這個片語把大氣條件放在遙遠過去。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":4},{"front":"provide the extra boost","meaning":"提供額外推動","examples":[{"en":"Sulfur dioxide could have provided the extra boost of warming Mars needed.","zh":"二氧化硫可能提供了火星所需的額外增溫推動。"},{"en":"To provide the extra boost means to give additional help that makes success possible.","zh":"provide the extra boost 指提供額外幫助，使成功變得可能。"},{"en":"A short review session may provide the extra boost a student needs before an exam.","zh":"考試前一次短複習可能為學生提供所需的額外推動。"},{"en":"If CO2 was not enough, SO2 could provide the extra boost for warming.","zh":"如果二氧化碳不足，二氧化硫可以為增溫提供額外推動。"},{"en":"This phrase suggests a helpful addition, not the whole solution alone.","zh":"這個片語暗示有用的額外補充，而不是單獨的完整解決方案。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":4},{"front":"greenhouse warming","meaning":"溫室增溫","examples":[{"en":"Sulfur dioxide may have boosted greenhouse warming.","zh":"二氧化硫可能加強了溫室增溫。"},{"en":"Greenhouse warming is warming caused when gases trap heat in an atmosphere.","zh":"greenhouse warming 是氣體在大氣中困住熱力造成的增溫。"},{"en":"Greenhouse warming keeps Earth warmer than it would be without an atmosphere.","zh":"溫室增溫令地球比沒有大氣時更溫暖。"},{"en":"Too much greenhouse warming can raise temperatures and change climate patterns.","zh":"過多溫室增溫可以提高氣溫並改變氣候模式。"},{"en":"This phrase connects atmospheric gases with trapped heat.","zh":"這個片語把大氣氣體與被困住的熱力連接起來。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":4},{"front":"stay wet","meaning":"保持濕潤","examples":[{"en":"The Red Planet needed extra warming to stay wet.","zh":"紅色星球需要額外增溫來保持濕潤。"},{"en":"To stay wet means to remain in a condition where water is present.","zh":"stay wet 指保持有水存在的狀態。"},{"en":"A garden needs regular watering to stay wet during a hot summer.","zh":"花園在炎熱夏季需要定期澆水來保持濕潤。"},{"en":"If Mars could stay wet, rivers and lakes may have lasted longer.","zh":"如果火星能保持濕潤，河流和湖泊可能存在更久。"},{"en":"This phrase suggests continuing wetness, not just a brief rainfall.","zh":"這個片語暗示持續濕潤，而不只是短暫降雨。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":5},{"front":"that may not sound like much","meaning":"那聽起來可能不多","examples":[{"en":"That may not sound like much, but tiny amounts of gas can matter.","zh":"那聽起來可能不多，但極少量氣體也可能重要。"},{"en":"That may not sound like much means the amount seems small at first.","zh":"that may not sound like much 指數量起初聽起來很少。"},{"en":"Ten minutes of reading a day may not sound like much, but it adds up over a year.","zh":"每天閱讀十分鐘聽起來可能不多，但一年下來會累積很多。"},{"en":"A small gas concentration may not sound like much, but it can affect climate chemistry.","zh":"少量氣體濃度聽起來可能不多，但可以影響氣候化學。"},{"en":"This phrase prepares the reader to see why a small amount can still be important.","zh":"這個片語讓讀者準備理解為何少量仍可重要。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":5},{"front":"minuscule concentrations","meaning":"極微小濃度","examples":[{"en":"Minuscule concentrations of some gases are hard to maintain.","zh":"某些氣體的極微小濃度難以維持。"},{"en":"Minuscule concentrations are extremely tiny amounts of a substance in a mixture.","zh":"minuscule concentrations 是混合物中極少量的某種物質。"},{"en":"Doctors can detect minuscule concentrations of chemicals in a blood test.","zh":"醫生可以在血液測試中探測到化學物質的極微小濃度。"},{"en":"Even minuscule concentrations of some gases can affect atmospheric reactions.","zh":"即使是某些氣體的極微小濃度，也可以影響大氣反應。"},{"en":"This phrase stresses that the amount is very small but still measurable or important.","zh":"這個片語強調數量非常小，但仍可被量度或仍重要。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":5},{"front":"hard to maintain","meaning":"難以維持","examples":[{"en":"Even tiny concentrations of certain gases are hard to maintain.","zh":"即使某些氣體的微小濃度也難以維持。"},{"en":"If something is hard to maintain, it is difficult to keep at the same level or condition.","zh":"如果某事 hard to maintain，意思是難以保持在相同水平或狀態。"},{"en":"A regular exercise habit is hard to maintain when work becomes stressful.","zh":"當工作變得有壓力，定期運動習慣很難維持。"},{"en":"If a gas is quickly destroyed, its concentration is hard to maintain.","zh":"如果某氣體很快被破壞，其濃度就難以維持。"},{"en":"This phrase focuses on keeping something stable over time.","zh":"這個片語聚焦於長時間保持穩定。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":5},{"front":"on our home planet","meaning":"在我們的家園地球上","examples":[{"en":"On our home planet, sulfur dioxide does not provide long-term warmth.","zh":"在我們的家園地球上，二氧化硫不提供長期暖化作用。"},{"en":"On our home planet means on Earth, the planet where humans live.","zh":"on our home planet 指在地球上，即人類居住的行星上。"},{"en":"On our home planet, water exists as ice, liquid, and vapour.","zh":"在我們的家園地球上，水以冰、液態水和水蒸氣形式存在。"},{"en":"Comparing Mars with conditions on our home planet helps scientists understand differences.","zh":"把火星與我們家園地球上的條件比較，幫助科學家理解差異。"},{"en":"This phrase is a warmer way to refer to Earth.","zh":"這個片語是較親切地指地球的說法。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":5},{"front":"significant long-term warmth","meaning":"顯著的長期暖化作用","examples":[{"en":"SO2 provides no significant long-term warmth on Earth.","zh":"二氧化硫在地球上不提供顯著的長期暖化作用。"},{"en":"Significant long-term warmth means important warming that lasts for a long period.","zh":"significant long-term warmth 指重要且持續很久的增溫作用。"},{"en":"A thick blanket can provide short-term warmth, but not significant long-term warmth for a whole building.","zh":"厚被可以提供短期溫暖，但不能為整棟建築提供顯著長期暖化作用。"},{"en":"If a gas cannot provide significant long-term warmth, it may not explain a warm climate by itself.","zh":"如果某氣體不能提供顯著長期暖化作用，它可能不能單獨解釋溫暖氣候。"},{"en":"This phrase combines strength and duration of warming.","zh":"這個片語結合了增溫的強度和持續時間。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":5},{"front":"combine almost instantly with","meaning":"幾乎立即與……結合","examples":[{"en":"Sulfur dioxide combines almost instantly with oxygen.","zh":"二氧化硫幾乎立即與氧氣結合。"},{"en":"To combine almost instantly with something means to react or join with it very quickly.","zh":"combine almost instantly with something 指非常快速地與某物反應或結合。"},{"en":"Some cleaning chemicals can combine almost instantly with water and release heat.","zh":"一些清潔化學品可以幾乎立即與水結合並釋放熱力。"},{"en":"If SO2 combines almost instantly with oxygen, it cannot remain long as SO2.","zh":"如果二氧化硫幾乎立即與氧氣結合，它就不能長時間以二氧化硫形式存在。"},{"en":"This phrase describes a very fast chemical reaction.","zh":"這個片語描述非常快速的化學反應。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":5},{"front":"form sulfate","meaning":"形成硫酸鹽","examples":[{"en":"SO2 combines with oxygen to form sulfate.","zh":"二氧化硫與氧氣結合形成硫酸鹽。"},{"en":"To form sulfate means to change into or create a sulfate compound.","zh":"form sulfate 指轉化為或產生硫酸鹽化合物。"},{"en":"In the atmosphere, certain sulfur gases can react with oxygen and water to form sulfate particles.","zh":"在大氣中，某些硫氣體可以與氧氣和水反應形成硫酸鹽粒子。"},{"en":"If sulfur dioxide forms sulfate quickly, it may lose its warming role.","zh":"如果二氧化硫很快形成硫酸鹽，它可能失去增溫作用。"},{"en":"This phrase describes a chemical product created by reaction.","zh":"這個片語描述由反應形成的化學產物。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":5},{"front":"a type of salt","meaning":"一種鹽","examples":[{"en":"Sulfate is a type of salt.","zh":"硫酸鹽是一種鹽。"},{"en":"A type of salt means a chemical compound belonging to the salt family.","zh":"a type of salt 指屬於鹽類的一種化學化合物。"},{"en":"Table salt is one familiar type of salt, but many other salts exist in chemistry.","zh":"食鹽是一種熟悉的鹽，但化學中還有許多其他鹽。"},{"en":"If a gas turns into a type of salt, it may settle on rocks or soil instead of staying in the air.","zh":"如果氣體轉化成一種鹽，它可能沉積在岩石或土壤上，而不是留在空氣中。"},{"en":"This phrase helps learners connect an unfamiliar chemical term with a broader category.","zh":"這個片語幫助學習者把陌生化學詞與較大類別連接起來。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":5},{"front":"virtually free of","meaning":"幾乎沒有……","examples":[{"en":"Early Mars would have been virtually free of atmospheric oxygen.","zh":"早期火星的大氣中幾乎沒有氧氣。"},{"en":"Virtually free of something means having almost none of it.","zh":"virtually free of something 指幾乎沒有某物。"},{"en":"A quiet library is virtually free of loud conversation.","zh":"安靜的圖書館幾乎沒有大聲談話。"},{"en":"If early Mars was virtually free of oxygen, sulfur dioxide would behave differently there.","zh":"如果早期火星幾乎沒有氧氣，二氧化硫在那裡的行為會不同。"},{"en":"This phrase means nearly absent, not completely impossible.","zh":"這個片語指幾乎不存在，而不是完全不可能存在。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":5},{"front":"atmospheric oxygen","meaning":"大氣氧","examples":[{"en":"Early Mars had very little atmospheric oxygen.","zh":"早期火星的大氣氧非常少。"},{"en":"Atmospheric oxygen is oxygen gas present in a planet’s atmosphere.","zh":"atmospheric oxygen 是存在於行星大氣中的氧氣。"},{"en":"Humans breathe atmospheric oxygen on Earth.","zh":"人類在地球上呼吸大氣氧。"},{"en":"If a planet has little atmospheric oxygen, chemical reactions can differ greatly from Earth’s.","zh":"如果一顆行星大氣氧很少，化學反應可能與地球大不相同。"},{"en":"This phrase refers to oxygen in the air, not oxygen locked inside rocks.","zh":"這個片語指空氣中的氧，而不是鎖在岩石中的氧。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":5},{"front":"stick around","meaning":"停留；持續存在","examples":[{"en":"SO2 would have stuck around much longer on early Mars.","zh":"二氧化硫可能在早期火星上停留更久。"},{"en":"To stick around means to remain in a place or condition for longer.","zh":"stick around 指在某地方或狀態中停留更長時間。"},{"en":"After class, some students stick around to ask the teacher questions.","zh":"下課後，有些學生留下來問老師問題。"},{"en":"If a gas does not react quickly, it can stick around in the atmosphere.","zh":"如果氣體不快速反應，它可以在大氣中持續存在。"},{"en":"This phrase is informal and means continue to be present.","zh":"這個片語較口語，意思是繼續存在。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":6},{"front":"take away oxygen","meaning":"去除氧氣","examples":[{"en":"When you take away oxygen, the atmosphere works differently.","zh":"當你去除氧氣，大氣的運作方式會不同。"},{"en":"To take away oxygen means to remove oxygen from a system or environment.","zh":"take away oxygen 指從一個系統或環境中移除氧氣。"},{"en":"Sealed food packaging may take away oxygen to slow spoilage.","zh":"密封食品包裝可能去除氧氣，以減慢變壞。"},{"en":"If oxygen is taken away from an atmosphere, some chemical reactions stop or change.","zh":"如果大氣中的氧氣被去除，一些化學反應會停止或改變。"},{"en":"This phrase describes removing a key chemical ingredient.","zh":"這個片語描述移除一種關鍵化學成分。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":6},{"front":"a profound change","meaning":"深遠的變化","examples":[{"en":"The absence of oxygen creates a profound change in the atmosphere.","zh":"缺乏氧氣會在大氣中造成深遠的變化。"},{"en":"A profound change is a deep, important change that affects how something works.","zh":"profound change 是深層而重要、會影響某事如何運作的變化。"},{"en":"Moving from primary school to university is a profound change in how students learn.","zh":"從小學到大學，是學生學習方式上的深遠變化。"},{"en":"A profound change in atmospheric chemistry can alter which gases survive.","zh":"大氣化學中的深遠變化可以改變哪些氣體能存留。"},{"en":"This phrase is stronger than a small or surface-level change.","zh":"這個片語比小變化或表面變化更強。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":6},{"front":"work really differently","meaning":"運作方式很不同","examples":[{"en":"An oxygen-free atmosphere works really differently.","zh":"無氧大氣層的運作方式很不同。"},{"en":"To work really differently means to operate in a very different way.","zh":"work really differently 指以非常不同的方式運作。"},{"en":"A school works really differently when all lessons move online.","zh":"當所有課堂轉到網上，學校運作方式會很不同。"},{"en":"If an atmosphere lacks oxygen, sulfur chemicals may work really differently.","zh":"如果大氣缺乏氧氣，硫化學物質的運作方式可能很不同。"},{"en":"This phrase stresses a major difference in how a system functions.","zh":"這個片語強調系統功能上的重大差異。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":6},{"front":"according to","meaning":"根據","examples":[{"en":"According to Schrag, SO2 could help solve a climate puzzle.","zh":"根據 Schrag 的說法，二氧化硫可以幫助解決一個氣候謎題。"},{"en":"According to someone means based on what that person says or reports.","zh":"according to someone 指根據某人所說或所報告的內容。"},{"en":"According to the teacher, the exam will include one writing task.","zh":"根據老師所說，考試會包括一項寫作任務。"},{"en":"According to new data, the river level is rising faster than expected.","zh":"根據新數據，河流水位上升得比預期更快。"},{"en":"This phrase introduces a source of information.","zh":"這個片語引入資訊來源。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":6},{"front":"imply that","meaning":"意味着","examples":[{"en":"The oxygen-free atmosphere implies that SO2 behaved differently on Mars.","zh":"無氧大氣層意味着二氧化硫在火星上的行為不同。"},{"en":"To imply that something is true means to suggest it without saying it directly.","zh":"imply that something is true 指不直接說出但暗示某事是真的。"},{"en":"If a student keeps yawning, it may imply that they are tired.","zh":"如果學生不斷打呵欠，這可能意味着他們很疲倦。"},{"en":"If early Mars lacked oxygen, that may imply that sulfur dioxide lasted longer.","zh":"如果早期火星缺乏氧氣，這可能意味着二氧化硫存留更久。"},{"en":"This phrase is useful when evidence points to a conclusion indirectly.","zh":"當證據間接指向結論時，這個片語很有用。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":6},{"front":"play a starring role in","meaning":"在……中扮演主角","examples":[{"en":"SO2 may have played a starring role in the Martian water cycle.","zh":"二氧化硫可能在火星水循環中扮演主角。"},{"en":"To play a starring role in something means to be one of the most important factors in it.","zh":"play a starring role in something 指在某事中成為最重要因素之一。"},{"en":"A good teacher can play a starring role in a student’s confidence.","zh":"好老師可以在學生信心中扮演主角。"},{"en":"If SO2 played a starring role in Mars’s climate, it was not just a minor gas.","zh":"如果二氧化硫在火星氣候中扮演主角，它就不只是次要氣體。"},{"en":"This phrase borrows language from theatre or film to show importance.","zh":"這個片語借用劇場或電影語言來顯示重要性。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":6},{"front":"Martian water cycle","meaning":"火星水循環","examples":[{"en":"SO2 may have influenced the Martian water cycle.","zh":"二氧化硫可能影響了火星水循環。"},{"en":"The Martian water cycle means the movement and changes of water on Mars.","zh":"Martian water cycle 指火星上水的移動和變化。"},{"en":"On Earth, the water cycle includes evaporation, clouds, rain, rivers, and ice.","zh":"在地球上，水循環包括蒸發、雲、雨、河流和冰。"},{"en":"If sulfur dioxide affected the Martian water cycle, it may have changed rainfall and surface water.","zh":"如果二氧化硫影響火星水循環，它可能改變降雨和地表水。"},{"en":"This phrase refers to water processes on Mars, not Earth.","zh":"這個片語指火星上的水過程，而不是地球上的。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":6},{"front":"resolve a climate conundrum","meaning":"解決氣候難題","examples":[{"en":"The hypothesis may resolve a climate conundrum.","zh":"這項假說可能解決一個氣候難題。"},{"en":"To resolve a climate conundrum means to solve a difficult climate-related puzzle.","zh":"resolve a climate conundrum 指解決一個與氣候相關的困難謎題。"},{"en":"New rainfall data may resolve a climate conundrum about why one valley stays green.","zh":"新降雨數據可能解決為何某山谷保持翠綠的氣候難題。"},{"en":"If SO2 explains both warmth and missing rocks, it may resolve a climate conundrum on Mars.","zh":"如果二氧化硫同時解釋溫暖和缺失岩石，它可能解決火星上的氣候難題。"},{"en":"This phrase suggests solving a problem that confused scientists.","zh":"這個片語暗示解決令科學家困惑的問題。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":6},{"front":"climate conundrum","meaning":"氣候謎題","examples":[{"en":"The lack of carbonate rocks is a climate conundrum.","zh":"缺乏碳酸鹽岩是一個氣候謎題。"},{"en":"A climate conundrum is a difficult climate puzzle that does not fit simple explanations.","zh":"climate conundrum 是不符合簡單解釋的困難氣候謎題。"},{"en":"A city becoming drier despite more storms could be a climate conundrum.","zh":"一個城市雖然有更多風暴卻變得更乾，可能是一個氣候謎題。"},{"en":"On Mars, a wet past without expected carbonate rocks creates a climate conundrum.","zh":"在火星上，曾有潮濕過去但沒有預期中的碳酸鹽岩，形成氣候謎題。"},{"en":"This phrase is more formal than saying a climate mystery.","zh":"這個片語比說 climate mystery 更正式。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":6},{"front":"namely","meaning":"即；也就是","examples":[{"en":"The conundrum is, namely, a lack of certain rocks.","zh":"這個謎題即是缺少某些岩石。"},{"en":"Namely means “that is to say” and introduces the exact thing being discussed.","zh":"namely 意思是「也就是」，用來引入正在討論的確切事物。"},{"en":"The school needs two things, namely more classrooms and more teachers.","zh":"學校需要兩樣東西，即更多課室和更多老師。"},{"en":"Scientists focused on one problem, namely the missing carbonate rocks.","zh":"科學家聚焦於一個問題，也就是缺失的碳酸鹽岩。"},{"en":"This word helps make a general statement more specific.","zh":"這個詞幫助把一般說法變得更具體。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":6},{"front":"a lack of certain rocks","meaning":"缺少某些岩石","examples":[{"en":"Scientists were puzzled by a lack of certain rocks on Mars.","zh":"科學家對火星上缺少某些岩石感到困惑。"},{"en":"A lack of certain rocks means expected rock types are missing or rare.","zh":"a lack of certain rocks 指預期中的岩石類型缺失或罕見。"},{"en":"A geologist may notice a lack of certain rocks where old seas were expected.","zh":"地質學家可能在預期有古海洋的地方注意到缺少某些岩石。"},{"en":"If a planet lacks certain rocks, scientists may question the chemical history they expected.","zh":"如果行星缺少某些岩石，科學家可能質疑原本預期的化學歷史。"},{"en":"This phrase points to missing physical evidence.","zh":"這個片語指缺失的實體證據。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":7},{"front":"contend that","meaning":"主張；認為","examples":[{"en":"Schrag’s team contends that SO2 formed acid rain on early Mars.","zh":"Schrag 的團隊主張二氧化硫在早期火星形成酸雨。"},{"en":"To contend that something is true means to argue or claim it strongly.","zh":"contend that something is true 指有力地爭辯或聲稱某事是真的。"},{"en":"Some parents contend that children learn better with shorter homework tasks.","zh":"一些家長主張孩子透過較短功課學得更好。"},{"en":"Scientists may contend that a new gas explains evidence old models could not explain.","zh":"科學家可能主張一種新氣體解釋了舊模型不能解釋的證據。"},{"en":"This phrase is common when presenting a debatable argument.","zh":"這個片語常用於呈現可爭議論點。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":7},{"front":"airborne water droplets","meaning":"空氣中的水滴","examples":[{"en":"SO2 may have combined with airborne water droplets.","zh":"二氧化硫可能與空氣中的水滴結合。"},{"en":"Airborne water droplets are tiny drops of water floating in the air.","zh":"airborne water droplets 是漂浮在空氣中的細小水滴。"},{"en":"Fog is made of many airborne water droplets near the ground.","zh":"霧是由許多接近地面的空氣中水滴組成。"},{"en":"If gas combines with airborne water droplets, it can form acidic rain or particles.","zh":"如果氣體與空氣中的水滴結合，它可以形成酸雨或粒子。"},{"en":"This phrase connects water in the air with atmospheric chemistry.","zh":"這個片語把空氣中的水與大氣化學連接起來。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":7},{"front":"fall as sulfurous acid rain","meaning":"以亞硫酸酸雨形式降下","examples":[{"en":"The combined chemicals may have fallen as sulfurous acid rain.","zh":"結合後的化學物質可能以亞硫酸酸雨形式降下。"},{"en":"To fall as sulfurous acid rain means to come down from the atmosphere as rain containing sulfurous acid.","zh":"fall as sulfurous acid rain 指以含亞硫酸的雨從大氣中降下。"},{"en":"Polluted air can sometimes fall as acid rain and damage lakes or buildings.","zh":"受污染空氣有時可以以酸雨形式降下，並破壞湖泊或建築物。"},{"en":"If SO2 formed sulfurous acid rain on Mars, it could have changed surface minerals.","zh":"如果二氧化硫在火星上形成亞硫酸酸雨，它可能改變地表礦物。"},{"en":"This phrase describes the form in which chemicals returned to the surface.","zh":"這個片語描述化學物質回到表面的形式。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":7},{"front":"rather than","meaning":"而不是","examples":[{"en":"On Mars, SO2 may have formed acid rain rather than sulfate.","zh":"在火星上，二氧化硫可能形成酸雨，而不是硫酸鹽。"},{"en":"Rather than means instead of one thing, another thing happened or was chosen.","zh":"rather than 指不是某事，而是另一件事發生或被選擇。"},{"en":"A student may review mistakes rather than simply repeat the same exercise.","zh":"學生可以複習錯誤，而不是只是重複同一練習。"},{"en":"If SO2 formed acid rain rather than sulfate, Mars’s rocks would develop differently.","zh":"如果二氧化硫形成酸雨而不是硫酸鹽，火星岩石會以不同方式發展。"},{"en":"This phrase clearly contrasts two possibilities.","zh":"這個片語清楚對比兩種可能性。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":7},{"front":"transform into","meaning":"轉化為","examples":[{"en":"SO2 may not have transformed into a salt on early Mars.","zh":"二氧化硫在早期火星上可能沒有轉化為一種鹽。"},{"en":"To transform into something means to change into a different form or substance.","zh":"transform into something 指變成不同形式或物質。"},{"en":"Water can transform into ice when the temperature falls below freezing.","zh":"當氣溫降至冰點以下，水可以轉化為冰。"},{"en":"If sulfur dioxide transforms into sulfate, it no longer acts as the same gas.","zh":"如果二氧化硫轉化為硫酸鹽，它就不再以同一氣體形式作用。"},{"en":"This phrase describes a major change in form or nature.","zh":"這個片語描述形態或性質上的重大改變。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":7},{"front":"resulting acidity","meaning":"由此產生的酸性","examples":[{"en":"The resulting acidity would have inhibited limestone formation.","zh":"由此產生的酸性會抑制石灰岩形成。"},{"en":"Resulting acidity means the acidic condition caused by a previous reaction or event.","zh":"resulting acidity 指由先前反應或事件造成的酸性狀態。"},{"en":"If lemon juice is added to milk, the resulting acidity can change the milk’s texture.","zh":"如果把檸檬汁加入牛奶，由此產生的酸性可以改變牛奶質感。"},{"en":"On Mars, resulting acidity from acid rain could stop certain rocks from forming.","zh":"在火星上，酸雨由此產生的酸性可以阻止某些岩石形成。"},{"en":"This phrase points to acidity as a consequence, not as the starting cause.","zh":"這個片語指出酸性是後果，而不是起始原因。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":7},{"front":"inhibit the formation of","meaning":"抑制……的形成","examples":[{"en":"Acidity would have inhibited the formation of carbonate rocks.","zh":"酸性會抑制碳酸鹽岩的形成。"},{"en":"To inhibit the formation of something means to slow or prevent it from forming.","zh":"inhibit the formation of something 指減慢或阻止某物形成。"},{"en":"Cold temperatures can inhibit the formation of mould on food.","zh":"低溫可以抑制食物上霉菌的形成。"},{"en":"If acid rain inhibited the formation of carbonate rocks, Mars would lack expected minerals.","zh":"如果酸雨抑制碳酸鹽岩形成，火星就會缺少預期礦物。"},{"en":"This phrase describes blocking a process before the final product appears.","zh":"這個片語描述在最終產物出現前阻擋過程。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":7},{"front":"thick layers of limestone","meaning":"厚厚的石灰岩層","examples":[{"en":"Acid rain may have prevented thick layers of limestone from forming.","zh":"酸雨可能阻止厚厚的石灰岩層形成。"},{"en":"Thick layers of limestone are deep deposits of carbonate rock built up over time.","zh":"thick layers of limestone 是隨時間積聚形成的厚碳酸鹽岩沉積層。"},{"en":"On Earth, thick layers of limestone can form in warm shallow seas.","zh":"在地球上，厚厚的石灰岩層可以在溫暖淺海中形成。"},{"en":"If thick layers of limestone are missing, scientists may ask what stopped their formation.","zh":"如果厚厚的石灰岩層缺失，科學家可能會問是甚麼阻止它們形成。"},{"en":"This phrase refers to large rock deposits, not a thin surface coating.","zh":"這個片語指大量岩石沉積，而不是薄薄的表面覆蓋。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":7},{"front":"carbonate rocks","meaning":"碳酸鹽岩","examples":[{"en":"Scientists expected to find many carbonate rocks on Mars.","zh":"科學家原本預期在火星上找到許多碳酸鹽岩。"},{"en":"Carbonate rocks are rocks containing carbonate minerals, often formed with water and carbon dioxide.","zh":"carbonate rocks 是含有碳酸鹽礦物的岩石，常由水和二氧化碳參與形成。"},{"en":"Limestone is a common kind of carbonate rock on Earth.","zh":"石灰岩是地球上一種常見碳酸鹽岩。"},{"en":"If Mars once had a humid CO2-rich atmosphere, carbonate rocks might be expected.","zh":"如果火星曾有潮濕且富含二氧化碳的大氣層，便可能預期有碳酸鹽岩。"},{"en":"This phrase is important because missing carbonate rocks create a scientific puzzle.","zh":"這個片語很重要，因為缺失的碳酸鹽岩形成科學謎題。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":7},{"front":"assume","meaning":"假定；認為","examples":[{"en":"Researchers assumed Mars would contain many carbonate rocks.","zh":"研究人員假定火星會含有許多碳酸鹽岩。"},{"en":"To assume means to believe something is true without complete proof.","zh":"assume 指在沒有完整證據下相信某事是真的。"},{"en":"A teacher should not assume students understand a word just because they can pronounce it.","zh":"老師不應只因學生能讀出一個詞，就假定他們理解它。"},{"en":"If scientists assume the wrong starting condition, their model may fail.","zh":"如果科學家假定了錯誤的起始條件，模型可能失敗。"},{"en":"This word often signals an idea that may later be questioned.","zh":"這個詞常表示一個之後可能被質疑的想法。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":7},{"front":"be chock-full of","meaning":"充滿","examples":[{"en":"Researchers assumed Mars would be chock-full of carbonate rocks.","zh":"研究人員假定火星會充滿碳酸鹽岩。"},{"en":"To be chock-full of something means to be completely or very full of it.","zh":"be chock-full of something 指完全或非常充滿某物。"},{"en":"The school noticeboard was chock-full of exam reminders and club posters.","zh":"學校告示板上充滿考試提醒和社團海報。"},{"en":"If Mars had been chock-full of carbonate rocks, the climate puzzle would be easier to solve.","zh":"如果火星充滿碳酸鹽岩，這個氣候謎題會較容易解決。"},{"en":"This phrase is informal and stronger than simply saying full of.","zh":"這個片語較口語，比 simply full of 更強。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":8},{"front":"fundamental consequence","meaning":"根本結果","examples":[{"en":"Carbonate formation is a fundamental consequence of a humid CO2-rich atmosphere.","zh":"碳酸鹽形成是潮濕且富含二氧化碳的大氣層的根本結果。"},{"en":"A fundamental consequence is a basic and important result that naturally follows from something.","zh":"fundamental consequence 是由某事自然帶來的基本而重要結果。"},{"en":"Better sleep is a fundamental consequence of reducing late-night screen use.","zh":"減少深夜使用螢幕的根本結果是睡眠改善。"},{"en":"If a humid CO2-rich atmosphere exists, carbonate formation may be a fundamental consequence.","zh":"如果存在潮濕且富含二氧化碳的大氣層，碳酸鹽形成可能是根本結果。"},{"en":"This phrase suggests the result is expected, not accidental.","zh":"這個片語暗示結果是預期中的，而不是偶然的。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":8},{"front":"humid, CO2-rich atmosphere","meaning":"潮濕且富含二氧化碳的大氣層","examples":[{"en":"A humid, CO2-rich atmosphere should produce carbonate rocks.","zh":"潮濕且富含二氧化碳的大氣層應會產生碳酸鹽岩。"},{"en":"A humid, CO2-rich atmosphere is an atmosphere with much water vapour and carbon dioxide.","zh":"humid, CO2-rich atmosphere 是含有大量水蒸氣和二氧化碳的大氣層。"},{"en":"A greenhouse can feel like a humid, CO2-rich atmosphere when plants and warm air fill the space.","zh":"當植物和暖空氣充滿空間時，溫室可能感覺像潮濕且富含二氧化碳的大氣層。"},{"en":"If Mars had a humid, CO2-rich atmosphere, scientists would expect certain minerals to form.","zh":"如果火星曾有潮濕且富含二氧化碳的大氣層，科學家會預期某些礦物形成。"},{"en":"This phrase combines moisture and carbon dioxide as key climate conditions.","zh":"這個片語把濕度和二氧化碳結合作為關鍵氣候條件。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":8},{"front":"over millions of years","meaning":"經過數百萬年","examples":[{"en":"Over millions of years, carbonate formation removed CO2 from Earth’s atmosphere.","zh":"經過數百萬年，碳酸鹽形成從地球大氣中移除了二氧化碳。"},{"en":"Over millions of years means across an extremely long period of time.","zh":"over millions of years 指經過極長的時間。"},{"en":"Mountains can rise and erode over millions of years.","zh":"山脈可以經過數百萬年隆起和侵蝕。"},{"en":"Chemical processes in rocks can slowly change an atmosphere over millions of years.","zh":"岩石中的化學過程可以經過數百萬年慢慢改變大氣。"},{"en":"This phrase reminds readers that geological change is often very slow.","zh":"這個片語提醒讀者，地質變化通常非常緩慢。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":8},{"front":"rock-forming process","meaning":"岩石形成過程","examples":[{"en":"The rock-forming process can remove carbon dioxide from the atmosphere.","zh":"岩石形成過程可以從大氣中移除二氧化碳。"},{"en":"A rock-forming process is a natural process that creates or changes rocks.","zh":"rock-forming process 是創造或改變岩石的自然過程。"},{"en":"Cooling lava is one rock-forming process because it can become solid rock.","zh":"冷卻熔岩是一種岩石形成過程，因為它可以變成固體岩石。"},{"en":"If a rock-forming process traps carbon dioxide, it can affect climate over long periods.","zh":"如果岩石形成過程困住二氧化碳，它可以長期影響氣候。"},{"en":"This phrase connects geology with atmospheric chemistry.","zh":"這個片語把地質學與大氣化學連接起來。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":8},{"front":"sequester carbon dioxide","meaning":"封存二氧化碳","examples":[{"en":"Carbonate formation has sequestered large amounts of carbon dioxide on Earth.","zh":"碳酸鹽形成在地球上封存了大量二氧化碳。"},{"en":"To sequester carbon dioxide means to store carbon dioxide so it is kept out of the atmosphere.","zh":"sequester carbon dioxide 指儲存二氧化碳，使其不留在大氣中。"},{"en":"Forests can sequester carbon dioxide by storing carbon in wood and soil.","zh":"森林可以透過把碳儲存在木材和土壤中來封存二氧化碳。"},{"en":"If rocks sequester carbon dioxide, they can reduce the amount of heat-trapping gas in the air.","zh":"如果岩石封存二氧化碳，它們可以減少空氣中的捕熱氣體。"},{"en":"This phrase is common in climate science and carbon management.","zh":"這個片語常見於氣候科學和碳管理。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":8},{"front":"spewed from volcanoes","meaning":"從火山噴出的","examples":[{"en":"Carbon dioxide spewed from volcanoes can build up in the atmosphere.","zh":"從火山噴出的二氧化碳可以在大氣中積聚。"},{"en":"Spewed from volcanoes means violently released from volcanoes during eruptions.","zh":"spewed from volcanoes 指在火山爆發期間被猛烈釋放出來。"},{"en":"Ash spewed from volcanoes can cover farms and roads.","zh":"從火山噴出的火山灰可以覆蓋農田和道路。"},{"en":"If gases are spewed from volcanoes repeatedly, they may change atmospheric composition.","zh":"如果氣體反覆從火山噴出，它們可能改變大氣成分。"},{"en":"This phrase gives a forceful image of volcanic release.","zh":"這個片語給出火山猛烈釋放的畫面。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":8},{"front":"limit the buildup of","meaning":"限制……的積聚","examples":[{"en":"Carbonate formation limits the buildup of carbon dioxide in the atmosphere.","zh":"碳酸鹽形成限制大氣中二氧化碳的積聚。"},{"en":"To limit the buildup of something means to stop it from accumulating too much.","zh":"limit the buildup of something 指阻止某物積聚過多。"},{"en":"Opening windows can limit the buildup of smoke in a kitchen.","zh":"打開窗戶可以限制廚房中煙霧積聚。"},{"en":"If rocks limit the buildup of CO2, they can reduce long-term warming.","zh":"如果岩石限制二氧化碳積聚，它們可以減少長期暖化。"},{"en":"This phrase focuses on controlling gradual accumulation.","zh":"這個片語聚焦於控制逐漸累積。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":8},{"front":"stifle this step","meaning":"阻礙這一步驟","examples":[{"en":"Acid rain may have stifled this CO2-sequestration step.","zh":"酸雨可能阻礙了這個二氧化碳封存步驟。"},{"en":"To stifle this step means to block or suppress this stage of a process.","zh":"stifle this step 指阻擋或壓制某過程中的這個階段。"},{"en":"Too much criticism can stifle a student’s first step toward speaking English.","zh":"過多批評可以阻礙學生開口說英語的第一步。"},{"en":"If acidity stifles carbonate formation, carbon dioxide may stay in the atmosphere.","zh":"如果酸性阻礙碳酸鹽形成，二氧化碳可能留在大氣中。"},{"en":"This phrase suggests that an important process is being held back.","zh":"這個片語暗示重要過程被抑制。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":8},{"front":"CO2-sequestration step","meaning":"二氧化碳封存步驟","examples":[{"en":"The CO2-sequestration step removes carbon dioxide from the atmosphere.","zh":"二氧化碳封存步驟會從大氣中移除二氧化碳。"},{"en":"A CO2-sequestration step is a stage in which carbon dioxide is captured or stored.","zh":"CO2-sequestration step 是捕捉或儲存二氧化碳的階段。"},{"en":"Planting trees can be part of a CO2-sequestration step in a climate plan.","zh":"種樹可以是氣候計劃中二氧化碳封存步驟的一部分。"},{"en":"If the CO2-sequestration step stops, more carbon dioxide may remain in the air.","zh":"如果二氧化碳封存步驟停止，更多二氧化碳可能留在空氣中。"},{"en":"This phrase names the part of a process that locks away carbon dioxide.","zh":"這個片語指出把二氧化碳鎖起來的過程部分。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":8},{"front":"force more of the gas to accumulate","meaning":"迫使更多氣體積聚","examples":[{"en":"Stopping carbonate formation would force more CO2 to accumulate.","zh":"停止碳酸鹽形成會迫使更多二氧化碳積聚。"},{"en":"To force more of the gas to accumulate means to cause a larger amount of gas to build up.","zh":"force more of the gas to accumulate 指導致更多氣體逐漸積聚。"},{"en":"Closing all windows can force more smoke to accumulate in a room.","zh":"關閉所有窗戶可以迫使更多煙霧在房間中積聚。"},{"en":"If carbon dioxide is not trapped in rocks, more of the gas may accumulate in the atmosphere.","zh":"如果二氧化碳沒有被困在岩石中，更多這種氣體可能在大氣中積聚。"},{"en":"This phrase describes a result caused by blocking removal.","zh":"這個片語描述阻止移除後造成的結果。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":8},{"front":"another way","meaning":"另一種方式","examples":[{"en":"This is another way SO2 could have boosted warming.","zh":"這是二氧化硫可能加強增溫的另一種方式。"},{"en":"Another way means an additional method or route to the same result.","zh":"another way 指達到同一結果的另一種方法或路徑。"},{"en":"Walking to school is another way to exercise if students dislike sports.","zh":"如果學生不喜歡運動，步行上學是鍛煉的另一種方式。"},{"en":"If SO2 stopped CO2 from being trapped in rocks, that was another way it warmed Mars.","zh":"如果二氧化硫阻止二氧化碳被困在岩石中，那就是它使火星變暖的另一種方式。"},{"en":"This phrase introduces an extra explanation, not the only explanation.","zh":"這個片語引入額外解釋，而不是唯一解釋。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":9},{"front":"boost greenhouse warming","meaning":"加強溫室增溫","examples":[{"en":"Sulfur dioxide could have boosted greenhouse warming on Mars.","zh":"二氧化硫可能曾加強火星上的溫室增溫。"},{"en":"To boost greenhouse warming means to strengthen the warming caused by heat-trapping gases.","zh":"boost greenhouse warming 指加強由捕熱氣體造成的增溫。"},{"en":"More carbon dioxide can boost greenhouse warming in a planet’s atmosphere.","zh":"更多二氧化碳可以加強行星大氣中的溫室增溫。"},{"en":"If SO2 boosted greenhouse warming, Mars could have stayed warmer than CO2 alone allowed.","zh":"如果二氧化硫加強了溫室增溫，火星可能比單靠二氧化碳時更溫暖。"},{"en":"This phrase describes an increase in warming, not just the presence of gas.","zh":"這個片語描述增溫增加，而不只是有氣體存在。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":9},{"front":"doubt that","meaning":"懷疑","examples":[{"en":"Some scientists doubt that SO2 could perform these climatic tasks.","zh":"一些科學家懷疑二氧化硫能否完成這些氣候任務。"},{"en":"To doubt that something is true means to question whether it is true.","zh":"doubt that something is true 指質疑某事是否真實。"},{"en":"A teacher may doubt that a copied essay was written by the student.","zh":"老師可能懷疑一篇抄襲文章是否由學生自己寫成。"},{"en":"Scientists may doubt a hypothesis if the chemistry seems unstable.","zh":"如果化學性質似乎不穩定，科學家可能懷疑某假說。"},{"en":"This phrase shows uncertainty or scepticism.","zh":"這個片語顯示不確定或懷疑態度。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":9},{"front":"up to these climatic tasks","meaning":"足以完成這些氣候任務","examples":[{"en":"Some scientists doubt that SO2 was up to these climatic tasks.","zh":"一些科學家懷疑二氧化硫是否足以完成這些氣候任務。"},{"en":"To be up to these climatic tasks means to be capable of doing these climate-related jobs.","zh":"be up to these climatic tasks 指有能力完成這些與氣候相關的工作。"},{"en":"A small fan may not be up to the task of cooling a whole classroom.","zh":"小風扇可能不足以完成為整間課室降溫的任務。"},{"en":"If SO2 is destroyed too quickly, it may not be up to these climatic tasks.","zh":"如果二氧化硫太快被破壞，它可能不足以完成這些氣候任務。"},{"en":"This phrase questions whether something has enough power or ability.","zh":"這個片語質疑某物是否有足夠力量或能力。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":9},{"front":"oxygen-free atmosphere","meaning":"無氧大氣層","examples":[{"en":"Even in an oxygen-free atmosphere, sulfur dioxide is fragile.","zh":"即使在無氧大氣層中，二氧化硫也極不穩定。"},{"en":"An oxygen-free atmosphere is an atmosphere with little or no oxygen gas.","zh":"oxygen-free atmosphere 是含很少或沒有氧氣的大氣層。"},{"en":"Food packaging may create an oxygen-free atmosphere to slow chemical change.","zh":"食品包裝可能創造無氧環境，以減慢化學變化。"},{"en":"In an oxygen-free atmosphere, some gases react differently from how they do on Earth today.","zh":"在無氧大氣層中，一些氣體的反應方式不同於今日地球。"},{"en":"This phrase highlights the absence of oxygen as an important condition.","zh":"這個片語強調缺乏氧氣是一個重要條件。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":9},{"front":"extremely fragile","meaning":"極不穩定","examples":[{"en":"Sulfur dioxide is extremely fragile under ultraviolet radiation.","zh":"二氧化硫在紫外線輻射下極不穩定。"},{"en":"Extremely fragile means very easily damaged, broken, or destroyed.","zh":"extremely fragile 指非常容易受損、破裂或被破壞。"},{"en":"A thin glass cup is extremely fragile and may break if dropped.","zh":"薄玻璃杯極易碎，如果掉下可能破裂。"},{"en":"If SO2 is extremely fragile in sunlight, it may not stay long in the atmosphere.","zh":"如果二氧化硫在陽光下極不穩定，它可能不會長時間留在大氣中。"},{"en":"This phrase stresses weakness under certain conditions.","zh":"這個片語強調在特定條件下的脆弱性。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":9},{"front":"ultraviolet radiation","meaning":"紫外線輻射","examples":[{"en":"The sun’s ultraviolet radiation can split SO2 molecules apart.","zh":"太陽的紫外線輻射可以分解二氧化硫分子。"},{"en":"Ultraviolet radiation is invisible energy from the sun that can damage molecules and living tissue.","zh":"ultraviolet radiation 是來自太陽、不可見但能損害分子和生物組織的能量。"},{"en":"Sunscreen protects skin from ultraviolet radiation.","zh":"防曬霜保護皮膚免受紫外線輻射傷害。"},{"en":"If ultraviolet radiation breaks SO2 apart, the gas cannot keep warming the atmosphere.","zh":"如果紫外線輻射分解二氧化硫，這種氣體就不能繼續使大氣增溫。"},{"en":"This phrase is common in science when discussing sunlight’s chemical effects.","zh":"這個片語在討論陽光化學作用時常見於科學。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":9},{"front":"split apart","meaning":"分裂；分解","examples":[{"en":"Ultraviolet radiation splits apart SO2 molecules.","zh":"紫外線輻射會分解二氧化硫分子。"},{"en":"To split apart means to break something into separate pieces.","zh":"split apart 指把某物分裂成分開的部分。"},{"en":"A strong wave can split apart a weak wooden boat.","zh":"強浪可以把脆弱木船打裂。"},{"en":"If sunlight splits apart a molecule, the original chemical no longer remains intact.","zh":"如果陽光分解一個分子，原本化學物質就不再完整。"},{"en":"This phrase describes breaking into parts, not simply moving away.","zh":"這個片語描述分裂成部分，而不只是移開。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":9},{"front":"SO2 molecules","meaning":"二氧化硫分子","examples":[{"en":"SO2 molecules can be destroyed by sunlight.","zh":"二氧化硫分子可以被陽光破壞。"},{"en":"SO2 molecules are individual units of sulfur dioxide, each made of sulfur and oxygen atoms.","zh":"SO2 molecules 是二氧化硫的單個單位，每個由硫和氧原子組成。"},{"en":"Scientists study SO2 molecules to understand how sulfur dioxide behaves in air.","zh":"科學家研究二氧化硫分子，以理解二氧化硫在空氣中的行為。"},{"en":"If SO2 molecules break apart, sulfur dioxide cannot keep the same chemical effect.","zh":"如果二氧化硫分子分解，二氧化硫就不能保持相同化學作用。"},{"en":"This phrase refers to the tiny chemical units of the gas.","zh":"這個片語指這種氣體的微小化學單位。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":9},{"front":"quite readily","meaning":"相當容易地","examples":[{"en":"Sunlight can split apart SO2 molecules quite readily.","zh":"陽光可以相當容易地分解二氧化硫分子。"},{"en":"Quite readily means fairly easily and without much difficulty.","zh":"quite readily 指相當容易地，沒有太大困難。"},{"en":"A dry leaf can catch fire quite readily in hot weather.","zh":"乾葉在炎熱天氣中相當容易着火。"},{"en":"If SO2 breaks down quite readily, its concentration is hard to maintain.","zh":"如果二氧化硫相當容易分解，其濃度就難以維持。"},{"en":"This phrase suggests a process happens easily, not rarely.","zh":"這個片語暗示過程容易發生，而不是罕見發生。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":9},{"front":"point out","meaning":"指出","examples":[{"en":"Kasting points out that ultraviolet radiation destroys SO2.","zh":"Kasting 指出紫外線輻射會破壞二氧化硫。"},{"en":"To point out means to mention or draw attention to something important.","zh":"point out 指提及或提醒別人注意重要事情。"},{"en":"A teacher may point out a common spelling mistake before students write again.","zh":"老師可能在學生再次寫作前指出一個常見拼寫錯誤。"},{"en":"Scientists point out weaknesses in a hypothesis so it can be tested more carefully.","zh":"科學家指出假說中的弱點，以便更仔細測試。"},{"en":"This phrase is used when someone highlights a fact or problem.","zh":"這個片語用於某人強調事實或問題時。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":9},{"front":"atmospheric chemist","meaning":"大氣化學家","examples":[{"en":"James Kasting is an atmospheric chemist.","zh":"James Kasting 是一位大氣化學家。"},{"en":"An atmospheric chemist is a scientist who studies chemical reactions in the atmosphere.","zh":"atmospheric chemist 是研究大氣中化學反應的科學家。"},{"en":"Atmospheric chemists examine how gases, sunlight, and particles interact in air.","zh":"大氣化學家研究氣體、陽光和粒子如何在空氣中互相作用。"},{"en":"An atmospheric chemist may question whether SO2 can survive long enough to warm Mars.","zh":"大氣化學家可能質疑二氧化硫能否存留足夠久來令火星增溫。"},{"en":"This phrase names a scientific specialist, not a general weather reporter.","zh":"這個片語指科學專家，而不是普通天氣報導員。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":10},{"front":"computer models","meaning":"電腦模型","examples":[{"en":"Kasting used computer models of early climate.","zh":"Kasting 使用早期氣候的電腦模型。"},{"en":"Computer models are digital simulations used to test how a system may behave.","zh":"computer models 是用來測試系統可能如何運作的數碼模擬。"},{"en":"Engineers use computer models before building bridges or aircraft.","zh":"工程師在建造橋樑或飛機前使用電腦模型。"},{"en":"If computer models show SO2 breaks down quickly, scientists may doubt the hypothesis.","zh":"如果電腦模型顯示二氧化硫迅速分解，科學家可能懷疑該假說。"},{"en":"This phrase refers to calculated simulations, not physical miniatures.","zh":"這個片語指計算模擬，而不是實體小模型。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":10},{"front":"early climate","meaning":"早期氣候","examples":[{"en":"Models of Earth’s early climate are often compared with early Mars.","zh":"地球早期氣候模型常與早期火星比較。"},{"en":"Early climate means the climate of a planet during its ancient history.","zh":"early climate 指一顆行星在古代歷史中的氣候。"},{"en":"Scientists study early climate to understand how atmospheres and oceans first developed.","zh":"科學家研究早期氣候，以理解大氣和海洋最初如何發展。"},{"en":"If early climate models are wrong, explanations of ancient water may also be wrong.","zh":"如果早期氣候模型錯誤，對古代水的解釋也可能錯誤。"},{"en":"This phrase focuses on climate long before the present.","zh":"這個片語聚焦於遠早於現在的氣候。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":10},{"front":"be compared with","meaning":"與……比較","examples":[{"en":"Earth’s early climate is often compared with that of early Mars.","zh":"地球早期氣候常與早期火星的氣候比較。"},{"en":"To be compared with something means to be examined alongside it to see similarities and differences.","zh":"be compared with something 指與某物並列檢視，以看出相似和差異。"},{"en":"A student’s first essay may be compared with a later essay to show improvement.","zh":"學生第一篇文章可以與後來的文章比較，以顯示進步。"},{"en":"If Mars is compared with Earth, scientists can see which processes are shared and which are different.","zh":"如果把火星與地球比較，科學家可以看出哪些過程相同、哪些不同。"},{"en":"This phrase helps explain learning through comparison.","zh":"這個片語幫助解釋透過比較學習。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":10},{"front":"photochemical destruction","meaning":"光化學破壞","examples":[{"en":"Photochemical destruction may limit SO2 concentrations.","zh":"光化學破壞可能限制二氧化硫濃度。"},{"en":"Photochemical destruction is the breaking down of chemicals by light-driven reactions.","zh":"photochemical destruction 是由光驅動反應造成的化學物質分解。"},{"en":"Sunlight can cause photochemical destruction of some pollutants in the air.","zh":"陽光可以造成空氣中某些污染物的光化學破壞。"},{"en":"If photochemical destruction is strong, SO2 may not build up enough to warm Mars.","zh":"如果光化學破壞很強，二氧化硫可能無法積聚到足以令火星增溫。"},{"en":"This phrase combines light, chemistry, and breakdown.","zh":"這個片語結合光、化學和分解。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":10},{"front":"cap concentrations at","meaning":"將濃度限制在……","examples":[{"en":"Photochemical destruction capped SO2 concentrations at a low level.","zh":"光化學破壞將二氧化硫濃度限制在低水平。"},{"en":"To cap concentrations at a level means to limit the amount so it cannot rise above that level.","zh":"cap concentrations at a level 指限制數量，使其不能超過該水平。"},{"en":"A school may cap class size at thirty students.","zh":"學校可能把班級人數限制在三十名學生。"},{"en":"If sunlight caps SO2 concentrations at a very low level, the warming effect may be weak.","zh":"如果陽光把二氧化硫濃度限制在很低水平，增溫效果可能很弱。"},{"en":"This phrase describes setting or creating an upper limit.","zh":"這個片語描述設定或造成上限。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":10},{"front":"one thousandth as much as","meaning":"只有……的千分之一","examples":[{"en":"The model capped SO2 at one thousandth as much as Schrag suggested.","zh":"該模型把二氧化硫限制在只有 Schrag 所建議數量的千分之一。"},{"en":"One thousandth as much as means only one part out of a thousand of another amount.","zh":"one thousandth as much as 指只有另一數量的一千分之一。"},{"en":"If one classroom has one thousandth as much dust as another, it is far cleaner.","zh":"如果一間課室的灰塵只有另一間的千分之一，它就乾淨得多。"},{"en":"If SO2 is only one thousandth as much as suggested, its climate effect may be much smaller.","zh":"如果二氧化硫只有建議量的千分之一，其氣候作用可能小得多。"},{"en":"This phrase shows an extremely large difference in amount.","zh":"這個片語顯示數量上的極大差異。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":10},{"front":"make this idea work","meaning":"令這個想法行得通","examples":[{"en":"There may be ways to make this idea work.","zh":"可能有方法令這個想法行得通。"},{"en":"To make this idea work means to find conditions or methods that make the idea successful.","zh":"make this idea work 指找到條件或方法令這個想法成功。"},{"en":"A teacher may change the timing of a group activity to make the idea work.","zh":"老師可能改變小組活動的時間安排，以令這個想法行得通。"},{"en":"If scientists can protect SO2 from sunlight, they may make this idea work better.","zh":"如果科學家能保護二氧化硫免受陽光破壞，他們可能令這個想法更行得通。"},{"en":"This phrase suggests an idea is possible but needs improvement.","zh":"這個片語暗示想法可能可行，但需要改善。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":10},{"front":"detailed modeling","meaning":"詳細建模","examples":[{"en":"Detailed modeling would be needed to convince skeptics.","zh":"需要詳細建模才能說服懷疑者。"},{"en":"Detailed modeling means careful and complex simulation of how a system works.","zh":"detailed modeling 指對系統如何運作進行仔細而複雜的模擬。"},{"en":"City planners use detailed modeling before changing traffic routes.","zh":"城市規劃者在改變交通路線前使用詳細建模。"},{"en":"If a climate claim is controversial, detailed modeling can test whether it is realistic.","zh":"如果氣候主張有爭議，詳細建模可以測試它是否現實。"},{"en":"This phrase suggests deeper analysis than a simple estimate.","zh":"這個片語暗示比簡單估算更深入的分析。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":10},{"front":"convince skeptics","meaning":"說服懷疑者","examples":[{"en":"The hypothesis needs detailed modeling to convince skeptics.","zh":"這項假說需要詳細建模來說服懷疑者。"},{"en":"To convince skeptics means to persuade people who doubt an idea.","zh":"convince skeptics 指說服懷疑某想法的人。"},{"en":"A new medicine needs strong trial results to convince skeptics.","zh":"新藥需要有力試驗結果來說服懷疑者。"},{"en":"If the SO2 theory lacks data, it will be hard to convince skeptics.","zh":"如果二氧化硫理論缺乏數據，就很難說服懷疑者。"},{"en":"This phrase shows that doubtful people need stronger evidence.","zh":"這個片語顯示抱懷疑態度的人需要更強證據。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":10},{"front":"actually feasible","meaning":"實際可行","examples":[{"en":"Some scientists doubt that the SO2 hypothesis is actually feasible.","zh":"一些科學家懷疑二氧化硫假說是否實際可行。"},{"en":"Actually feasible means truly possible to do or work in practice.","zh":"actually feasible 指在實際上真的可能做到或奏效。"},{"en":"A study plan may sound good, but it is only actually feasible if the student has enough time.","zh":"學習計劃可能聽起來很好，但只有學生有足夠時間時才實際可行。"},{"en":"If a climate idea requires impossible gas levels, it may not be actually feasible.","zh":"如果氣候想法需要不可能的氣體水平，它可能並非實際可行。"},{"en":"This phrase separates attractive theory from practical possibility.","zh":"這個片語把吸引人的理論與實際可能性分開。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":10},{"front":"admit that","meaning":"承認","examples":[{"en":"Schrag admits that the details are uncertain.","zh":"Schrag 承認細節仍不確定。"},{"en":"To admit that something is true means to accept it openly, often though it weakens one’s argument.","zh":"admit that something is true 指公開接受某事為真，常常即使它削弱自己的論點。"},{"en":"A student may admit that they did not understand the instructions.","zh":"學生可能承認自己沒有理解指示。"},{"en":"A scientist may admit that evidence is incomplete while still supporting a hypothesis.","zh":"科學家可能承認證據不完整，同時仍支持某假說。"},{"en":"This phrase shows honesty about a limitation or problem.","zh":"這個片語顯示對限制或問題的誠實承認。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":11},{"front":"the details are uncertain","meaning":"細節仍不確定","examples":[{"en":"The details of the SO2 hypothesis are uncertain.","zh":"二氧化硫假說的細節仍不確定。"},{"en":"If the details are uncertain, people know the general idea but not the exact facts or process.","zh":"如果 the details are uncertain，意思是人們知道大概想法，但不知道確切事實或過程。"},{"en":"A trip may be planned in general, but the details are uncertain until tickets are booked.","zh":"旅行可能大致已計劃，但在訂票前細節仍不確定。"},{"en":"If the details of a theory are uncertain, scientists need more data and modeling.","zh":"如果理論細節仍不確定，科學家需要更多數據和建模。"},{"en":"This phrase means the broad claim is possible, but the specifics remain unclear.","zh":"這個片語表示大方向可能成立，但具體內容仍不清楚。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":11},{"front":"cite estimates by","meaning":"引用……的估算","examples":[{"en":"Schrag cites estimates by other researchers.","zh":"Schrag 引用其他研究人員的估算。"},{"en":"To cite estimates by someone means to refer to their calculated guesses or figures as support.","zh":"cite estimates by someone 指引用某人的計算推測或數字作支持。"},{"en":"A report may cite estimates by health experts to explain hospital demand.","zh":"報告可能引用健康專家的估算來解釋醫院需求。"},{"en":"If a scientist cites estimates by others, readers can see where the numbers came from.","zh":"如果科學家引用他人的估算，讀者就能知道數字來源。"},{"en":"This phrase shows that an argument uses outside calculations.","zh":"這個片語顯示論點使用外部計算。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":11},{"front":"keep pace with","meaning":"跟上；與……保持同步","examples":[{"en":"Volcanoes could have produced enough SO2 to keep pace with destruction.","zh":"火山可能產生足夠二氧化硫，以跟上破壞速度。"},{"en":"To keep pace with something means to match its speed or rate.","zh":"keep pace with something 指配合某事的速度或速率。"},{"en":"A student must review regularly to keep pace with a fast course.","zh":"學生必須定期複習，才能跟上快速課程。"},{"en":"If volcanoes produced SO2 fast enough to keep pace with destruction, gas levels could remain stable.","zh":"如果火山產生二氧化硫的速度足以跟上破壞速度，氣體水平可以保持穩定。"},{"en":"This phrase compares two rates moving at the same time.","zh":"這個片語比較兩個同時進行的速率。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":11},{"front":"destroyed photochemically","meaning":"被光化學作用破壞","examples":[{"en":"Some SO2 would have been destroyed photochemically.","zh":"一些二氧化硫會被光化學作用破壞。"},{"en":"Destroyed photochemically means broken down by chemical reactions driven by light.","zh":"destroyed photochemically 指被光驅動的化學反應分解。"},{"en":"Some pollutants are destroyed photochemically when sunlight reacts with them.","zh":"一些污染物在陽光與它們反應時會被光化學作用破壞。"},{"en":"If SO2 is destroyed photochemically, sunlight reduces the amount left in the atmosphere.","zh":"如果二氧化硫被光化學作用破壞，陽光會減少大氣中剩餘的量。"},{"en":"This phrase explains destruction caused by light-based chemistry.","zh":"這個片語解釋由光化學造成的破壞。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":11},{"front":"previous findings","meaning":"以往研究結果","examples":[{"en":"Previous findings support part of Schrag’s argument.","zh":"以往研究結果支持 Schrag 論點的一部分。"},{"en":"Previous findings are results discovered in earlier research.","zh":"previous findings 是早期研究中發現的結果。"},{"en":"A doctor may compare new test results with previous findings from the same patient.","zh":"醫生可能把新檢查結果與同一病人的以往結果比較。"},{"en":"If previous findings support a theory, the theory becomes more credible.","zh":"如果以往研究結果支持某理論，該理論會變得更可信。"},{"en":"This phrase connects current claims with earlier evidence.","zh":"這個片語把當前主張與較早證據連接起來。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":11},{"front":"thick CO2 atmosphere","meaning":"濃厚二氧化碳大氣層","examples":[{"en":"A thick CO2 atmosphere may have protected SO2 from ultraviolet radiation.","zh":"濃厚二氧化碳大氣層可能保護二氧化硫免受紫外線輻射破壞。"},{"en":"A thick CO2 atmosphere is a dense atmosphere containing a lot of carbon dioxide.","zh":"thick CO2 atmosphere 是含有大量二氧化碳的濃密大氣層。"},{"en":"A thick CO2 atmosphere could trap heat and scatter some incoming radiation.","zh":"濃厚二氧化碳大氣層可以困住熱力並散射部分進入的輻射。"},{"en":"If early Mars had a thick CO2 atmosphere, SO2 may have lasted longer than expected.","zh":"如果早期火星有濃厚二氧化碳大氣層，二氧化硫可能比預期存留更久。"},{"en":"This phrase describes both atmospheric density and chemical composition.","zh":"這個片語同時描述大氣密度和化學成分。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":11},{"front":"effectively scatter","meaning":"有效散射","examples":[{"en":"A thick atmosphere would have effectively scattered harmful radiation.","zh":"濃厚大氣層會有效散射有害輻射。"},{"en":"To effectively scatter something means to spread it in different directions in a way that works well.","zh":"effectively scatter something 指有效地把某物向不同方向散開。"},{"en":"Frosted glass can effectively scatter light so people cannot see clearly through it.","zh":"磨砂玻璃可以有效散射光線，使人不能清楚看穿。"},{"en":"If an atmosphere effectively scatters ultraviolet radiation, fewer harmful rays reach lower layers.","zh":"如果大氣有效散射紫外線輻射，較少有害光線會到達較低層。"},{"en":"This phrase describes successful spreading or deflection.","zh":"這個片語描述成功分散或偏轉。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":11},{"front":"destructive wavelengths","meaning":"具破壞力的波長","examples":[{"en":"The atmosphere scattered the most destructive wavelengths of ultraviolet radiation.","zh":"大氣散射了紫外線輻射中最具破壞力的波長。"},{"en":"Destructive wavelengths are parts of radiation that can damage molecules or materials.","zh":"destructive wavelengths 是會破壞分子或材料的輻射部分。"},{"en":"Sunscreen blocks destructive wavelengths that can harm skin.","zh":"防曬霜阻擋可能傷害皮膚的具破壞力波長。"},{"en":"If destructive wavelengths are scattered, fragile molecules such as SO2 may survive longer.","zh":"如果具破壞力的波長被散射，像二氧化硫這樣脆弱的分子可能存留更久。"},{"en":"This phrase focuses on the damaging parts of light.","zh":"這個片語聚焦於光中具有破壞力的部分。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":11},{"front":"yet another example of","meaning":"又一個……的例子","examples":[{"en":"The radiation effect is yet another example of cooperation between CO2 and SO2.","zh":"這種輻射效果又是二氧化碳與二氧化硫合作的一個例子。"},{"en":"Yet another example of something means one more example added to others already mentioned.","zh":"yet another example of something 指在已提到的例子之外再加上一個例子。"},{"en":"A late bus is yet another example of why the transport system needs improvement.","zh":"巴士遲到又是交通系統需要改善的一個例子。"},{"en":"CO2 protecting SO2 would be yet another example of the two gases helping each other.","zh":"二氧化碳保護二氧化硫，會是兩種氣體互相幫助的又一個例子。"},{"en":"This phrase suggests there are already several examples.","zh":"這個片語暗示已經有幾個例子存在。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":11},{"front":"apparently mutually beneficial partnership","meaning":"表面上互惠的伙伴關係","examples":[{"en":"CO2 and SO2 may have formed an apparently mutually beneficial partnership.","zh":"二氧化碳和二氧化硫可能形成了表面上互惠的伙伴關係。"},{"en":"An apparently mutually beneficial partnership is a relationship that seems to help both sides.","zh":"apparently mutually beneficial partnership 是似乎對雙方都有幫助的關係。"},{"en":"A school and a library may form a mutually beneficial partnership if students get books and the library gains visitors.","zh":"如果學生得到書籍而圖書館增加訪客，學校和圖書館可能形成互惠伙伴關係。"},{"en":"If CO2 warmed Mars and protected SO2, their partnership may have benefited both gases’ roles.","zh":"如果二氧化碳令火星增溫並保護二氧化硫，它們的伙伴關係可能有利於兩種氣體的作用。"},{"en":"The word apparently shows that the benefit seems likely but is not fully certain.","zh":"apparently 這個詞顯示好處似乎存在，但尚未完全確定。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":11},{"front":"on early Mars","meaning":"在早期火星上","examples":[{"en":"CO2 and SO2 may have worked together on early Mars.","zh":"二氧化碳和二氧化硫可能曾在早期火星上共同作用。"},{"en":"On early Mars means during the ancient period of Mars’s history.","zh":"on early Mars 指在火星歷史的古老時期。"},{"en":"Rivers may have flowed on early Mars if temperatures were warm enough.","zh":"如果氣溫足夠溫暖，河流可能曾在早期火星上流動。"},{"en":"If certain gases existed on early Mars, they may explain ancient wet landscapes.","zh":"如果某些氣體存在於早期火星，它們可能解釋古代潮濕地貌。"},{"en":"This phrase places events in Mars’s distant past.","zh":"這個片語把事件放在火星遙遠過去。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":12},{"front":"maintain that","meaning":"堅持認為","examples":[{"en":"Kasting maintains that SO2 could not have made Mars Earth-like.","zh":"Kasting 堅持認為二氧化硫不可能令火星像地球一樣。"},{"en":"To maintain that something is true means to continue to argue or believe it firmly.","zh":"maintain that something is true 指繼續堅定主張或相信某事是真的。"},{"en":"A doctor may maintain that rest is necessary even if the patient wants to work.","zh":"即使病人想工作，醫生可能仍堅持認為休息是必要的。"},{"en":"A scientist may maintain that a model is too weak despite new suggestions.","zh":"儘管有新建議，科學家可能仍堅持認為模型太弱。"},{"en":"This phrase shows a firm position in a debate.","zh":"這個片語顯示辯論中的堅定立場。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":12},{"front":"climate feedback","meaning":"氣候反饋","examples":[{"en":"An SO2 climate feedback may have kept early Mars partly defrosted.","zh":"二氧化硫氣候反饋可能使早期火星保持部分解凍。"},{"en":"Climate feedback is a process in which a climate change triggers effects that strengthen or weaken the original change.","zh":"climate feedback 是氣候變化引發效果，而這些效果又加強或削弱原本變化的過程。"},{"en":"Melting ice can create climate feedback because darker ground absorbs more heat.","zh":"融冰可以形成氣候反饋，因為較深色地面吸收更多熱力。"},{"en":"If SO2 created a climate feedback, warming and chemical reactions may have supported each other.","zh":"如果二氧化硫造成氣候反饋，增溫和化學反應可能互相支撐。"},{"en":"This phrase describes a loop of cause and effect in climate.","zh":"這個片語描述氣候中的因果循環。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":12},{"front":"as warm as Earth","meaning":"像地球一樣溫暖","examples":[{"en":"SO2 probably could not have made early Mars as warm as Earth.","zh":"二氧化硫很可能不能令早期火星像地球一樣溫暖。"},{"en":"As warm as Earth means having a temperature similar to Earth’s.","zh":"as warm as Earth 指溫度與地球相似。"},{"en":"A classroom near a sunny window may be almost as warm as the playground outside.","zh":"靠近陽光窗戶的課室可能幾乎像外面操場一樣溫暖。"},{"en":"Even if Mars was partly warm, it may not have been as warm as Earth.","zh":"即使火星部分溫暖，它也未必像地球一樣溫暖。"},{"en":"This phrase makes a direct temperature comparison.","zh":"這個片語作直接溫度比較。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":12},{"front":"allow for the possibility that","meaning":"承認……的可能性","examples":[{"en":"Kasting allows for the possibility that SO2 kept Mars partly defrosted.","zh":"Kasting 承認二氧化硫使火星保持部分解凍的可能性。"},{"en":"To allow for the possibility that something is true means to accept that it may be true.","zh":"allow for the possibility that something is true 指接受某事可能是真的。"},{"en":"A teacher may allow for the possibility that a student misunderstood the question.","zh":"老師可能承認學生誤解題目的可能性。"},{"en":"A scientist can reject one strong claim while allowing for a smaller possibility.","zh":"科學家可以拒絕一個強主張，同時承認較小可能性。"},{"en":"This phrase shows cautious openness rather than full agreement.","zh":"這個片語顯示謹慎開放，而不是完全同意。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":12},{"front":"remain high enough to","meaning":"維持在足以……的高度","examples":[{"en":"SO2 concentrations may have remained high enough to keep Mars partly defrosted.","zh":"二氧化硫濃度可能維持在足以令火星部分解凍的高度。"},{"en":"Remain high enough to means stay at a level sufficient to produce a result.","zh":"remain high enough to 指保持在足以產生某結果的水平。"},{"en":"A phone battery must remain high enough to last through the journey.","zh":"電話電量必須維持在足以撐完整段旅程的水平。"},{"en":"If SO2 levels remained high enough, some water on Mars may have stayed unfrozen.","zh":"如果二氧化硫水平維持足夠高，火星上一些水可能保持不結冰。"},{"en":"This phrase connects a maintained level with its effect.","zh":"這個片語把維持的水平與其效果連接起來。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":12},{"front":"partly defrosted","meaning":"部分解凍的","examples":[{"en":"SO2 may have kept the planet partly defrosted.","zh":"二氧化硫可能使這顆行星保持部分解凍。"},{"en":"Partly defrosted means not completely frozen, with some ice melted or softened.","zh":"partly defrosted 指沒有完全冰凍，部分冰已融化或變軟。"},{"en":"Frozen food is partly defrosted when the outside is soft but the centre is still hard.","zh":"冷凍食物外層變軟但中心仍硬時，就是部分解凍。"},{"en":"If Mars was partly defrosted, some surface water could flow at times.","zh":"如果火星部分解凍，一些地表水有時可能流動。"},{"en":"This phrase suggests limited melting, not a fully warm planet.","zh":"這個片語暗示有限融化，而不是完全溫暖的行星。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":12},{"front":"enough rainfall to","meaning":"足夠降雨去……","examples":[{"en":"There may have been enough rainfall to form river valleys.","zh":"可能曾有足夠降雨去形成河谷。"},{"en":"Enough rainfall to do something means sufficient rain to produce a particular result.","zh":"enough rainfall to do something 指有足夠雨量產生某特定結果。"},{"en":"There was enough rainfall to fill the school’s small pond after a week of storms.","zh":"經過一星期風暴後，降雨足以填滿學校的小池塘。"},{"en":"If Mars had enough rainfall to form river valleys, its climate must have supported liquid water at times.","zh":"如果火星曾有足夠降雨去形成河谷，其氣候必定有時支持液態水。"},{"en":"This phrase links amount of rain with its visible effect.","zh":"這個片語把雨量與可見效果連接起來。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":12},{"front":"form river valleys","meaning":"形成河谷","examples":[{"en":"Rainfall may have helped form river valleys on Mars.","zh":"降雨可能幫助火星形成河谷。"},{"en":"To form river valleys means to create valleys through flowing water cutting into land.","zh":"form river valleys 指透過流水切割土地來創造河谷。"},{"en":"Over many years, a river can form valleys by wearing away soil and rock.","zh":"經過多年，河流可以透過侵蝕泥土和岩石形成河谷。"},{"en":"If rainfall formed river valleys, water must have flowed across the surface.","zh":"如果降雨形成河谷，水必定曾在表面流動。"},{"en":"This phrase describes a landscape shaped by moving water.","zh":"這個片語描述由流動水塑造的地貌。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":12},{"front":"on that point","meaning":"在那一點上","examples":[{"en":"On that point, Schrag does not disagree.","zh":"在那一點上，Schrag 並不同意反對。"},{"en":"On that point means about that specific issue or detail.","zh":"on that point 指關於那個特定問題或細節。"},{"en":"Two teachers may disagree about homework amount, but on that point, they both support clearer feedback.","zh":"兩位老師可能不同意功課量，但在那一點上，他們都支持更清楚回饋。"},{"en":"In a debate, people may agree on one point while disagreeing on others.","zh":"在辯論中，人們可能在某一點上同意，而在其他方面不同意。"},{"en":"This phrase narrows discussion to one exact matter.","zh":"這個片語把討論收窄到一個確切事項。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":12},{"front":"not quibble","meaning":"不作爭辯；不吹毛求疵","examples":[{"en":"Schrag does not quibble over how warm Mars was.","zh":"Schrag 不爭辯火星到底有多暖。"},{"en":"To not quibble means not to argue over small details.","zh":"not quibble 指不為小細節爭論。"},{"en":"A teacher may not quibble over minor spelling if the student’s main argument is strong.","zh":"如果學生主要論點有力，老師可能不會對小拼寫錯誤吹毛求疵。"},{"en":"If scientists do not quibble over the exact temperature, they focus on the broader explanation.","zh":"如果科學家不爭論確切溫度，他們就聚焦於較大解釋。"},{"en":"This phrase suggests avoiding unnecessary small disputes.","zh":"這個片語暗示避免不必要的小爭執。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":12},{"front":"depend on whether","meaning":"取決於是否……","examples":[{"en":"The hypothesis does not depend on whether Mars had a large ocean.","zh":"這項假說並不取決於火星是否曾有大海洋。"},{"en":"Depend on whether means be decided by or require the truth of one possibility.","zh":"depend on whether 指由某個可能性是否真實來決定，或需要該可能性成立。"},{"en":"A picnic plan may depend on whether it rains tomorrow.","zh":"野餐計劃可能取決於明天是否下雨。"},{"en":"If the SO2 idea does not depend on whether Mars had an ocean, smaller water bodies may still fit it.","zh":"如果二氧化硫想法不取決於火星是否有海洋，較小水體仍可能符合。"},{"en":"This phrase links an outcome to a yes-or-no condition.","zh":"這個片語把結果與是或否的條件連接起來。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":13},{"front":"a big ocean","meaning":"一個大海洋","examples":[{"en":"The hypothesis does not require a big ocean on Mars.","zh":"這項假說不需要火星上有一個大海洋。"},{"en":"A big ocean is a very large body of salty or liquid water covering a wide area.","zh":"a big ocean 是覆蓋廣大範圍的巨大鹹水或液態水體。"},{"en":"Earth has big oceans that affect weather, transport, and life.","zh":"地球有大型海洋，影響天氣、交通和生命。"},{"en":"If Mars did not need a big ocean, a few lakes might still explain some river valleys.","zh":"如果火星不需要有大海洋，幾個湖泊仍可能解釋一些河谷。"},{"en":"This phrase contrasts a huge water body with smaller lakes or puddles.","zh":"這個片語把巨大水體與較小湖泊或水坑作對比。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":13},{"front":"a few lakes","meaning":"幾個湖泊","examples":[{"en":"Early Mars may have had a few lakes rather than a global ocean.","zh":"早期火星可能有幾個湖泊，而不是全球海洋。"},{"en":"A few lakes means several bodies of standing water, but not a huge ocean.","zh":"a few lakes 指幾個靜止水體，但不是巨大海洋。"},{"en":"A dry park may still have a few lakes that support birds and plants.","zh":"乾燥公園仍可能有幾個湖泊，支撐鳥類和植物。"},{"en":"If Mars had only a few lakes, water could still shape local landscapes.","zh":"如果火星只有幾個湖泊，水仍可以塑造本地地貌。"},{"en":"This phrase suggests limited water, not complete dryness.","zh":"這個片語暗示有限水量，而不是完全乾燥。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":13},{"front":"little puddles","meaning":"小水坑","examples":[{"en":"Even little puddles could fit the warming hypothesis.","zh":"即使小水坑也可以符合增溫假說。"},{"en":"Little puddles are small shallow pools of water.","zh":"little puddles 是細小而淺的水池。"},{"en":"After light rain, little puddles may form near the school gate.","zh":"小雨後，學校門口附近可能形成小水坑。"},{"en":"If Mars was only slightly warm, little puddles might appear without a global ocean.","zh":"如果火星只是稍微溫暖，可能出現小水坑，而不需要全球海洋。"},{"en":"This phrase shows a very small amount of surface water.","zh":"這個片語顯示非常少量的地表水。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":13},{"front":"just warm enough to","meaning":"剛好溫暖到足以……","examples":[{"en":"Mars may have been just warm enough to create river valleys.","zh":"火星可能剛好溫暖到足以形成河谷。"},{"en":"Just warm enough to means warm only to the minimum level needed for a result.","zh":"just warm enough to 指溫暖程度只達到產生某結果所需的最低水平。"},{"en":"The soup is just warm enough to eat, but not hot.","zh":"這碗湯剛好暖到可以喝，但不熱。"},{"en":"If Mars was just warm enough to create river valleys, it may still have been cold overall.","zh":"如果火星剛好溫暖到足以形成河谷，它整體上可能仍然寒冷。"},{"en":"This phrase suggests barely sufficient conditions.","zh":"這個片語暗示條件只是勉強足夠。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":13},{"front":"with SO2, it takes only a little","meaning":"有二氧化硫時，只需少量便足夠","examples":[{"en":"With SO2, it takes only a little to warm early Mars.","zh":"有二氧化硫時，只需少量便足以令早期火星變暖。"},{"en":"With SO2, it takes only a little means a small amount of sulfur dioxide may be enough to have an effect.","zh":"with SO2, it takes only a little 指少量二氧化硫可能已足以產生作用。"},{"en":"With strong spices, it takes only a little to change the taste of soup.","zh":"有強烈香料時，只需少量便能改變湯的味道。"},{"en":"If SO2 is powerful, it may take only a little to influence climate.","zh":"如果二氧化硫很有力，可能只需少量便能影響氣候。"},{"en":"This phrase highlights the strength of a small quantity.","zh":"這個片語突出小數量的力量。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":13},{"front":"as a new hypothesis suggests","meaning":"正如一項新假說所指出","examples":[{"en":"Sulfur dioxide may have warmed Mars, as a new hypothesis suggests.","zh":"二氧化硫可能曾使火星變暖，正如一項新假說所指出。"},{"en":"As a new hypothesis suggests means according to a new proposed explanation.","zh":"as a new hypothesis suggests 指根據一項新提出的解釋。"},{"en":"Students may learn better through examples, as a new teaching hypothesis suggests.","zh":"學生可能透過例子學得更好，正如一項新教學假說所指出。"},{"en":"If a new hypothesis suggests a different cause, scientists must test it with evidence.","zh":"如果新假說指出不同原因，科學家必須用證據測試它。"},{"en":"This phrase introduces an idea that is proposed but not fully proven.","zh":"這個片語引入一個已提出但尚未完全證明的想法。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":13},{"front":"sulfites","meaning":"亞硫酸鹽","examples":[{"en":"Sulfites may have formed in standing water on Mars.","zh":"亞硫酸鹽可能曾在火星的靜止水體中形成。"},{"en":"Sulfites are chemical compounds containing sulfur and oxygen.","zh":"sulfites 是含有硫和氧的化學化合物。"},{"en":"Scientists may look for sulfites in rocks to test whether certain sulfur reactions happened.","zh":"科學家可能在岩石中尋找亞硫酸鹽，以測試某些硫反應是否曾發生。"},{"en":"If sulfites are found on Mars, they could support parts of the SO2 hypothesis.","zh":"如果在火星上發現亞硫酸鹽，它們可能支持二氧化硫假說的部分內容。"},{"en":"This word refers to a mineral or chemical clue, not the gas itself.","zh":"這個詞指礦物或化學線索，而不是氣體本身。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":13},{"front":"standing water","meaning":"靜止水體；積水","examples":[{"en":"Sulfites would have formed in standing water at the surface.","zh":"亞硫酸鹽會在表面的靜止水體中形成。"},{"en":"Standing water is water that remains still in one place, such as a pond or puddle.","zh":"standing water 是停留在一處不流動的水，例如池塘或水坑。"},{"en":"Mosquitoes can breed in standing water left in buckets after rain.","zh":"雨後留在桶中的積水可以讓蚊子繁殖。"},{"en":"If chemicals sit in standing water, they may react and leave mineral deposits.","zh":"如果化學物質停留在靜止水體中，它們可能反應並留下礦物沉積。"},{"en":"This phrase contrasts still water with fast-flowing rivers.","zh":"這個片語把靜止的水與快速流動的河流作對比。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":13},{"front":"at the surface","meaning":"在表面","examples":[{"en":"Sulfites may have formed at the Martian surface.","zh":"亞硫酸鹽可能曾在火星表面形成。"},{"en":"At the surface means on or near the outermost layer of a planet, object, or liquid.","zh":"at the surface 指在行星、物體或液體的最外層或附近。"},{"en":"Oil can float at the surface of water because it is less dense.","zh":"油可以浮在水的表面，因為它密度較低。"},{"en":"If minerals formed at the surface, rovers may be able to detect them.","zh":"如果礦物在表面形成，火星車可能能探測到它們。"},{"en":"This phrase gives a location, not a deep underground process.","zh":"這個片語給出位置，而不是深地下過程。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":13},{"front":"no sulfites have yet turned up","meaning":"尚未發現亞硫酸鹽","examples":[{"en":"No sulfites have yet turned up on Mars.","zh":"火星上尚未發現亞硫酸鹽。"},{"en":"No sulfites have yet turned up means scientists have not found sulfites so far.","zh":"no sulfites have yet turned up 指到目前為止科學家尚未找到亞硫酸鹽。"},{"en":"No missing keys have yet turned up, even after the whole classroom was searched.","zh":"即使搜查了整間課室，遺失的鑰匙仍尚未出現。"},{"en":"If no sulfites have yet turned up, the hypothesis still needs more evidence.","zh":"如果尚未發現亞硫酸鹽，這項假說仍需要更多證據。"},{"en":"This phrase means absence of discovery so far, not proof that none exist.","zh":"這個片語指目前尚未發現，而不是證明完全不存在。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":13},{"front":"possibly because","meaning":"可能因為","examples":[{"en":"Sulfites may be missing possibly because no one was looking for them.","zh":"亞硫酸鹽可能未被發現，可能因為沒有人尋找它們。"},{"en":"Possibly because means maybe for this reason, though it is not certain.","zh":"possibly because 指也許是因為這個原因，但不確定。"},{"en":"The shop was empty possibly because it was raining heavily.","zh":"商店很空，可能因為雨下得很大。"},{"en":"Sulfites may not have been found possibly because earlier instruments were not designed to detect them.","zh":"亞硫酸鹽可能尚未被發現，可能因為早期儀器並非設計來探測它們。"},{"en":"This phrase introduces a cautious explanation.","zh":"這個片語引入謹慎解釋。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":14},{"front":"look for them","meaning":"尋找它們","examples":[{"en":"No one may have been looking for sulfites.","zh":"可能沒有人曾尋找亞硫酸鹽。"},{"en":"To look for them means to search for those things deliberately.","zh":"look for them 指有意識地搜尋那些東西。"},{"en":"If students lose their notes, they should look for them in their bags and lockers.","zh":"如果學生遺失筆記，他們應在書包和儲物櫃中尋找它們。"},{"en":"Scientists may fail to find minerals if they do not look for them with the right instrument.","zh":"如果科學家不用正確儀器尋找礦物，就可能找不到它們。"},{"en":"This phrase stresses active searching, not accidental discovery.","zh":"這個片語強調主動搜尋，而不是偶然發現。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":14},{"front":"next-generation rover","meaning":"新一代火星車","examples":[{"en":"The next-generation rover is well equipped for the search.","zh":"新一代火星車裝備完善，能夠進行這項搜尋。"},{"en":"A next-generation rover is a newer, more advanced vehicle designed to explore another planet.","zh":"next-generation rover 是更新、更先進、設計用來探索另一顆行星的車輛。"},{"en":"A next-generation rover may carry better cameras, drills, and laboratory instruments.","zh":"新一代火星車可能攜帶更好的相機、鑽具和實驗室儀器。"},{"en":"If a rover has advanced tools, it can search for minerals older rovers might miss.","zh":"如果火星車有先進工具，它可以搜尋舊火星車可能錯過的礦物。"},{"en":"This phrase suggests improved technology compared with earlier machines.","zh":"這個片語暗示與早期機器相比技術更進步。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":14},{"front":"Mars Science Laboratory","meaning":"火星科學實驗室","examples":[{"en":"The Mars Science Laboratory was designed to search for minerals.","zh":"火星科學實驗室被設計來搜尋礦物。"},{"en":"The Mars Science Laboratory is a Mars rover mission designed to study rocks, soil, and habitability.","zh":"Mars Science Laboratory 是一項火星車任務，設計來研究岩石、土壤和宜居性。"},{"en":"Scientists use data from the Mars Science Laboratory to understand Mars’s past environment.","zh":"科學家使用火星科學實驗室的數據來理解火星過去環境。"},{"en":"If the Mars Science Laboratory detects key minerals, it can test ideas about ancient water.","zh":"如果火星科學實驗室探測到關鍵礦物，它可以測試關於古代水的想法。"},{"en":"This phrase refers to a scientific mission, not a school laboratory on Earth.","zh":"這個片語指科學任務，而不是地球上的學校實驗室。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":14},{"front":"be well equipped for","meaning":"裝備完善，能夠……","examples":[{"en":"The rover is well equipped for the search for sulfites.","zh":"這輛火星車裝備完善，能夠搜尋亞硫酸鹽。"},{"en":"To be well equipped for something means to have the right tools, skills, or preparation for it.","zh":"be well equipped for something 指擁有適合某事的工具、技能或準備。"},{"en":"A student with notes, examples, and practice is well equipped for an exam.","zh":"擁有筆記、例子和練習的學生裝備完善，能夠應付考試。"},{"en":"If a rover is well equipped for mineral detection, it can identify more chemical clues.","zh":"如果火星車裝備完善，能夠探測礦物，它就能識別更多化學線索。"},{"en":"This phrase suggests readiness and suitable resources.","zh":"這個片語暗示準備充分和資源合適。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":14},{"front":"scheduled to launch","meaning":"預定發射","examples":[{"en":"The rover was scheduled to launch in 2009.","zh":"這輛火星車預定於2009年發射。"},{"en":"Scheduled to launch means planned to be sent into space at a particular time.","zh":"scheduled to launch 指計劃在特定時間被送入太空。"},{"en":"A new satellite may be scheduled to launch after final safety tests.","zh":"新衛星可能在最後安全測試後預定發射。"},{"en":"If a spacecraft is scheduled to launch, engineers must finish checks before the date.","zh":"如果太空船預定發射，工程師必須在日期前完成檢查。"},{"en":"This phrase describes a planned launch, not necessarily one that has already happened.","zh":"這個片語描述計劃中的發射，而不一定是已經發生。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":14},{"front":"artist’s conception","meaning":"藝術家構想圖","examples":[{"en":"The rover was shown in an artist’s conception.","zh":"這輛火星車在藝術家構想圖中被展示。"},{"en":"An artist’s conception is an illustration showing how something may look, especially before real photos exist.","zh":"artist’s conception 是顯示某物可能外觀的插圖，尤其是在真實照片出現前。"},{"en":"A new building may be shown in an artist’s conception before construction begins.","zh":"新建築在施工前可能以藝術家構想圖展示。"},{"en":"If a spacecraft is still being built, an artist’s conception helps the public imagine it.","zh":"如果太空船仍在建造，藝術家構想圖幫助公眾想像它。"},{"en":"This phrase means a visual design or impression, not a photograph.","zh":"這個片語指視覺設計或印象，而不是照片。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":14},{"front":"carry an X-ray diffractometer","meaning":"攜帶 X 射線衍射儀","examples":[{"en":"The rover would be the first to carry an X-ray diffractometer.","zh":"這輛火星車將成為首個攜帶 X 射線衍射儀的火星車。"},{"en":"To carry an X-ray diffractometer means to have this scientific instrument on board.","zh":"carry an X-ray diffractometer 指機上配備這種科學儀器。"},{"en":"A medical van may carry an X-ray machine to examine patients in remote areas.","zh":"醫療車可能攜帶 X 光機，到偏遠地區檢查病人。"},{"en":"If a rover carries an X-ray diffractometer, it can study mineral structures directly.","zh":"如果火星車攜帶 X 射線衍射儀，它可以直接研究礦物結構。"},{"en":"This phrase describes equipment included in a mission.","zh":"這個片語描述任務中包含的設備。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":14},{"front":"X-ray diffractometer","meaning":"X 射線衍射儀","examples":[{"en":"An X-ray diffractometer can identify mineral structures.","zh":"X 射線衍射儀可以識別礦物結構。"},{"en":"An X-ray diffractometer is an instrument that uses X-rays to study the arrangement of atoms in crystals.","zh":"X-ray diffractometer 是使用 X 射線研究晶體中原子排列的儀器。"},{"en":"Geologists use an X-ray diffractometer to identify minerals in rock samples.","zh":"地質學家使用 X 射線衍射儀識別岩石樣本中的礦物。"},{"en":"If a rover has an X-ray diffractometer, it can tell which minerals it encounters.","zh":"如果火星車有 X 射線衍射儀，它可以判斷遇到的是哪些礦物。"},{"en":"This phrase names a specialised scientific tool for crystal analysis.","zh":"這個片語指用於晶體分析的專門科學工具。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":14},{"front":"scan and identify","meaning":"掃描並識別","examples":[{"en":"The device can scan and identify crystal structures.","zh":"該裝置可以掃描並識別晶體結構。"},{"en":"To scan and identify something means to examine it carefully and recognise what it is.","zh":"scan and identify something 指仔細檢查某物並辨認它是甚麼。"},{"en":"Airport machines scan and identify luggage contents for safety.","zh":"機場機器會為安全掃描並識別行李內容。"},{"en":"If a rover can scan and identify minerals, scientists can study the planet without bringing samples home.","zh":"如果火星車可以掃描並識別礦物，科學家就能不把樣本帶回地球也研究行星。"},{"en":"This phrase combines examination with recognition.","zh":"這個片語結合檢查和辨認。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":14},{"front":"crystal structure","meaning":"晶體結構","examples":[{"en":"The instrument can identify the crystal structure of minerals.","zh":"該儀器可以識別礦物的晶體結構。"},{"en":"Crystal structure is the orderly arrangement of atoms inside a crystal.","zh":"crystal structure 是晶體內原子的有序排列。"},{"en":"Salt and diamond have different crystal structures, so they behave differently.","zh":"鹽和鑽石有不同晶體結構，所以它們表現不同。"},{"en":"If scientists know a mineral’s crystal structure, they can identify it more accurately.","zh":"如果科學家知道礦物的晶體結構，就能更準確識別它。"},{"en":"This phrase refers to the internal pattern of a solid material.","zh":"這個片語指固體材料的內部模式。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":14},{"front":"any mineral it encounters","meaning":"它遇到的任何礦物","examples":[{"en":"The rover can analyse any mineral it encounters.","zh":"這輛火星車可以分析它遇到的任何礦物。"},{"en":"Any mineral it encounters means any mineral the rover finds or comes across.","zh":"any mineral it encounters 指火星車找到或遇到的任何礦物。"},{"en":"A field scientist records any unusual rock she encounters during a survey.","zh":"野外科學家會記錄她在調查中遇到的任何異常岩石。"},{"en":"If the rover can analyse any mineral it encounters, it may detect unexpected evidence.","zh":"如果火星車可以分析它遇到的任何礦物，它可能探測到意想不到的證據。"},{"en":"This phrase stresses flexibility in studying whatever is found.","zh":"這個片語強調能靈活研究任何被發現的東西。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":15},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"Students must decide which paragraph contains the information.","zh":"學生必須判斷哪一段包含該資料。"},{"en":"Which paragraph contains means students must find the paragraph where specific information appears.","zh":"which paragraph contains 指學生必須找出特定資料出現在哪一段。"},{"en":"In a reading test, students may ask which paragraph contains a reason, example, or problem.","zh":"在閱讀測驗中，學生可能要判斷哪一段包含原因、例子或問題。"},{"en":"If paragraph C contains the evidence, students should match C with the question.","zh":"如果 C 段包含證據，學生應把 C 與題目配對。"},{"en":"This phrase is common in matching-information tasks.","zh":"這個片語常見於配對資料題。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":15},{"front":"the following information","meaning":"以下資料","examples":[{"en":"The questions ask students to locate the following information.","zh":"題目要求學生定位以下資料。"},{"en":"The following information means the details listed after the instruction.","zh":"the following information 指指示後列出的細節。"},{"en":"Students should read the following information before choosing paragraph letters.","zh":"學生應先閱讀以下資料，再選擇段落字母。"},{"en":"If the following information is paraphrased in the passage, students must match meaning, not wording.","zh":"如果以下資料在文章中被改寫，學生必須配對意思，而不是字面用詞。"},{"en":"This phrase tells readers to focus on the details that come next.","zh":"這個片語告訴讀者聚焦於接下來的細節。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":15},{"front":"use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"The instructions say students may use any letter more than once.","zh":"指示說學生可以重複使用任何字母。"},{"en":"Use any letter more than once means the same paragraph letter can be chosen repeatedly.","zh":"use any letter more than once 指同一段落字母可以重複選擇。"},{"en":"In a matching task, students may use any letter more than once if one paragraph contains several answers.","zh":"在配對題中，如果同一段包含幾個答案，學生可以重複使用任何字母。"},{"en":"If paragraph D gives two pieces of information, students can write D twice.","zh":"如果 D 段提供兩項資料，學生可以寫兩次 D。"},{"en":"This instruction prevents students from forcing each letter to appear only once.","zh":"這個指示防止學生強行讓每個字母只出現一次。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":15},{"front":"indirectly solved by","meaning":"由……間接解決","examples":[{"en":"The problem was indirectly solved by the proposed role of SO2.","zh":"這個問題由二氧化硫被提出的作用間接解決。"},{"en":"Indirectly solved by something means solved as a side result, not by addressing it directly.","zh":"indirectly solved by something 指作為附帶結果被解決，而不是被直接處理。"},{"en":"A school’s noise problem may be indirectly solved by shortening lunch queues, because students gather outside for less time.","zh":"學校噪音問題可能由縮短午餐排隊時間間接解決，因為學生在外聚集時間減少。"},{"en":"If SO2 explains acid rain, the missing-rock problem may be indirectly solved by the same idea.","zh":"如果二氧化硫解釋酸雨，缺失岩石問題可能由同一想法間接解決。"},{"en":"This phrase shows that one explanation can solve another problem at the same time.","zh":"這個片語顯示一個解釋可以同時解決另一個問題。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":15},{"front":"a device with an astounding ability to detect minerals","meaning":"具有驚人礦物探測能力的裝置","examples":[{"en":"The rover carries a device with an astounding ability to detect minerals.","zh":"這輛火星車攜帶一個具有驚人礦物探測能力的裝置。"},{"en":"A device with an astounding ability to detect minerals is an instrument that can identify minerals with remarkable skill.","zh":"a device with an astounding ability to detect minerals 是能以驚人能力識別礦物的儀器。"},{"en":"A hospital scanner with an astounding ability to detect tiny problems can help doctors treat patients earlier.","zh":"具有驚人能力探測微小問題的醫院掃描器，可以幫助醫生更早治療病人。"},{"en":"If a rover carries such a device, it can find mineral evidence that older tools may miss.","zh":"如果火星車攜帶這樣的裝置，它可以找到舊工具可能錯過的礦物證據。"},{"en":"This phrase highlights the impressive power of a scientific instrument.","zh":"這個片語突出科學儀器的驚人能力。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":15},{"front":"potential contributor to warming","meaning":"可能導致增溫的因素","examples":[{"en":"SO2 is a potential contributor to warming on Mars.","zh":"二氧化硫是火星上可能導致增溫的因素。"},{"en":"A potential contributor to warming is a possible factor that may help raise temperature.","zh":"potential contributor to warming 是可能幫助提高溫度的因素。"},{"en":"Dark roofs can be a potential contributor to warming in crowded cities.","zh":"深色屋頂可以是擁擠城市中可能導致增溫的因素。"},{"en":"If SO2 trapped heat or protected CO2, it could be a contributor to Martian warming.","zh":"如果二氧化硫困住熱力或保護二氧化碳，它可能是火星增溫的因素。"},{"en":"This phrase means possible cause, not proven main cause.","zh":"這個片語指可能原因，而不是已證明的主因。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":15},{"front":"interact with","meaning":"與……互相作用","examples":[{"en":"Sulfur dioxide may interact with carbon dioxide in the atmosphere.","zh":"二氧化硫可能與大氣中的二氧化碳互相作用。"},{"en":"To interact with something means to affect and be affected by it.","zh":"interact with something 指影響某物，同時也受其影響。"},{"en":"Some medicines interact with each other, so patients must tell doctors what they take.","zh":"有些藥物會互相作用，所以病人必須告訴醫生自己服用甚麼。"},{"en":"If SO2 interacts with CO2, the two gases may produce a different climate effect together.","zh":"如果二氧化硫與二氧化碳互相作用，兩種氣體一起可能產生不同氣候效果。"},{"en":"This phrase stresses mutual influence, not separate action.","zh":"這個片語強調互相影響，而不是各自獨立作用。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":15},{"front":"destructive effect of sunlight","meaning":"陽光的破壞作用","examples":[{"en":"Opponents emphasise the destructive effect of sunlight on SO2.","zh":"反對者強調陽光對二氧化硫的破壞作用。"},{"en":"The destructive effect of sunlight is sunlight’s ability to break down or damage something.","zh":"destructive effect of sunlight 是陽光分解或損害某物的能力。"},{"en":"The destructive effect of sunlight can fade posters left in a shop window.","zh":"陽光的破壞作用可以令放在店舖櫥窗的海報褪色。"},{"en":"If sunlight destroys SO2 molecules, that destructive effect weakens the warming hypothesis.","zh":"如果陽光破壞二氧化硫分子，這種破壞作用會削弱增溫假說。"},{"en":"This phrase focuses on harm caused by light.","zh":"這個片語聚焦於光造成的傷害。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":15},{"front":"proposed by opponents","meaning":"由反對者提出的","examples":[{"en":"The destructive effect of sunlight was proposed by opponents of the hypothesis.","zh":"陽光的破壞作用是由該假說的反對者提出的。"},{"en":"Proposed by opponents means suggested by people who disagree with an idea.","zh":"proposed by opponents 指由不同意某想法的人提出。"},{"en":"In a debate, a weakness may be proposed by opponents rather than supporters.","zh":"在辯論中，弱點可能由反對者而不是支持者提出。"},{"en":"If a problem is proposed by opponents, supporters must answer it with evidence.","zh":"如果問題由反對者提出，支持者必須用證據回應。"},{"en":"This phrase identifies the source of a counterargument.","zh":"這個片語指出反對論點的來源。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":15},{"front":"specific condition","meaning":"特定條件","examples":[{"en":"The lack of oxygen was a specific condition on early Mars.","zh":"缺乏氧氣是早期火星上的一個特定條件。"},{"en":"A specific condition is a particular situation or requirement that matters in a case.","zh":"specific condition 是在某個情況中重要的特定狀態或要求。"},{"en":"A plant may grow only under a specific condition, such as enough sunlight.","zh":"植物可能只在特定條件下生長，例如有足夠陽光。"},{"en":"If early Mars had a specific condition like low oxygen, sulfur chemistry could change.","zh":"如果早期火星有低氧這樣的特定條件，硫化學可能改變。"},{"en":"This phrase highlights one important feature among many.","zh":"這個片語突出眾多特徵中的一個重要特徵。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":15},{"front":"remain in the atmosphere","meaning":"留在大氣層中","examples":[{"en":"SO2 could remain in the atmosphere for a long time.","zh":"二氧化硫可以長時間留在大氣層中。"},{"en":"To remain in the atmosphere means to stay in the layer of gases around a planet.","zh":"remain in the atmosphere 指停留在行星周圍的氣體層中。"},{"en":"Smoke may remain in the atmosphere above a city when there is little wind.","zh":"當風很少時，煙霧可能留在城市上方的大氣中。"},{"en":"If sulfur dioxide remains in the atmosphere, it can continue affecting climate chemistry.","zh":"如果二氧化硫留在大氣層中，它可以繼續影響氣候化學。"},{"en":"This phrase focuses on staying in air rather than settling on the ground.","zh":"這個片語聚焦於留在空氣中，而不是沉降到地面。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":16},{"front":"for a long time","meaning":"長時間","examples":[{"en":"SO2 may have remained for a long time on early Mars.","zh":"二氧化硫可能在早期火星上長時間存在。"},{"en":"For a long time means for an extended period, not just briefly.","zh":"for a long time 指持續很久，而不是短暫地。"},{"en":"A student may remember a good teacher’s advice for a long time.","zh":"學生可能長時間記住好老師的建議。"},{"en":"If gas stays in an atmosphere for a long time, its effects can become more important.","zh":"如果氣體長時間留在大氣中，其影響可能變得更重要。"},{"en":"This phrase describes duration without giving an exact number.","zh":"這個片語描述持續時間，但不給出確切數字。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":16},{"front":"do the following statements agree","meaning":"以下陳述是否一致","examples":[{"en":"Students must decide whether the following statements agree with the passage.","zh":"學生必須判斷以下陳述是否與文章一致。"},{"en":"Do the following statements agree means students must check whether the statements match the text.","zh":"do the following statements agree 指學生必須檢查陳述是否與文本相符。"},{"en":"In reading tests, students ask whether the following statements agree before choosing TRUE or FALSE.","zh":"在閱讀測驗中，學生在選 TRUE 或 FALSE 前要問以下陳述是否一致。"},{"en":"If a statement agrees with the passage, the meaning matches even if the wording is different.","zh":"如果陳述與文章一致，即使用字不同，意思也相符。"},{"en":"This instruction tests careful comparison between question and text.","zh":"這個指示測試題目與文本之間的仔細比較。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":16},{"front":"information given","meaning":"所提供的資料","examples":[{"en":"The answers must match the information given in the passage.","zh":"答案必須符合文章所提供的資料。"},{"en":"Information given means the facts or details provided in the text.","zh":"information given 指文本中提供的事實或細節。"},{"en":"Students should answer using the information given, not their own outside knowledge.","zh":"學生應使用所提供的資料作答，而不是自己的外部知識。"},{"en":"If the information given does not mention a detail, the answer may be NOT GIVEN.","zh":"如果所提供的資料沒有提及某細節，答案可能是 NOT GIVEN。"},{"en":"This phrase reminds readers to stay close to the source.","zh":"這個片語提醒讀者緊貼來源。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":16},{"front":"concrete evidence","meaning":"具體證據","examples":[{"en":"The statement asks whether Schrag has provided concrete evidence.","zh":"該陳述問 Schrag 是否提供了具體證據。"},{"en":"Concrete evidence is clear, specific evidence that supports a claim.","zh":"concrete evidence 是支持某主張的清楚、具體證據。"},{"en":"A teacher needs concrete evidence, such as copied sentences, before accusing a student of plagiarism.","zh":"老師在指控學生抄襲前需要具體證據，例如抄襲句子。"},{"en":"Without concrete evidence, a scientific hypothesis remains uncertain.","zh":"沒有具體證據，科學假說仍不確定。"},{"en":"This phrase contrasts solid proof with speculation.","zh":"這個片語把實在證據與推測作對比。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":16},{"front":"counter sceptics","meaning":"反駁懷疑者","examples":[{"en":"Concrete evidence would help counter sceptics of the hypothesis.","zh":"具體證據會幫助反駁該假說的懷疑者。"},{"en":"To counter sceptics means to answer or challenge people who doubt an idea.","zh":"counter sceptics 指回應或挑戰懷疑某想法的人。"},{"en":"A company may use safety records to counter sceptics of a new product.","zh":"公司可能使用安全紀錄來反駁新產品的懷疑者。"},{"en":"If researchers find sulfites, that evidence may counter sceptics of the SO2 theory.","zh":"如果研究人員發現亞硫酸鹽，該證據可能反駁二氧化硫理論的懷疑者。"},{"en":"This phrase means responding to doubt with evidence or argument.","zh":"這個片語指用證據或論點回應懷疑。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":16},{"front":"increasing evidence","meaning":"越來越多證據","examples":[{"en":"The statement refers to increasing evidence about SO2.","zh":"該陳述提到關於二氧化硫的越來越多證據。"},{"en":"Increasing evidence means a growing amount of information supporting an idea.","zh":"increasing evidence 指支持某想法的資料數量正在增加。"},{"en":"Increasing evidence shows that regular sleep helps students learn better.","zh":"越來越多證據顯示規律睡眠幫助學生學得更好。"},{"en":"If increasing evidence supports SO2’s role, the hypothesis becomes more persuasive.","zh":"如果越來越多證據支持二氧化硫的作用，該假說會變得更有說服力。"},{"en":"This phrase suggests evidence is building over time.","zh":"這個片語暗示證據隨時間累積。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":16},{"front":"leading role","meaning":"主導作用","examples":[{"en":"SO2 may have played a leading role in warming Mars.","zh":"二氧化硫可能在火星增溫中發揮主導作用。"},{"en":"A leading role is a major or very important part in causing something.","zh":"leading role 是造成某事的主要或非常重要部分。"},{"en":"A supportive family can play a leading role in a child’s confidence.","zh":"支持性的家庭可以在孩子信心中發揮主導作用。"},{"en":"If SO2 played a leading role, it was central to the warming explanation.","zh":"如果二氧化硫發揮主導作用，它就是增溫解釋的核心。"},{"en":"This phrase indicates importance, not necessarily acting alone.","zh":"這個片語表示重要性，而不一定是單獨作用。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":16},{"front":"may not have been detected","meaning":"可能尚未被探測到","examples":[{"en":"Sulfites may not have been detected because no one searched for them.","zh":"亞硫酸鹽可能尚未被探測到，因為沒有人搜尋它們。"},{"en":"May not have been detected means possibly not found or noticed by instruments or people.","zh":"may not have been detected 指可能沒有被儀器或人發現或注意到。"},{"en":"A small error may not have been detected if nobody checked the final page.","zh":"如果沒有人檢查最後一頁，小錯誤可能尚未被發現。"},{"en":"If instruments were not designed for sulfites, they may not have been detected.","zh":"如果儀器不是為亞硫酸鹽設計，它們可能尚未被探測到。"},{"en":"This phrase suggests absence of discovery, not necessarily absence of the thing.","zh":"這個片語暗示尚未發現，而不一定表示該物不存在。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":16},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students must complete the summary below using words from the passage.","zh":"學生必須使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the short text that follows.","zh":"complete the summary below 指填寫下面短文中缺少的字詞。"},{"en":"In reading tests, students complete the summary below by finding exact words in the passage.","zh":"在閱讀測驗中，學生透過在文章中找出確切字詞完成以下摘要。"},{"en":"To complete the summary below correctly, students must check grammar and meaning.","zh":"要正確完成以下摘要，學生必須檢查文法和意思。"},{"en":"This instruction asks for careful reading, not personal opinion.","zh":"這個指示要求細心閱讀，而不是個人意見。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":16},{"front":"no more than three words","meaning":"不超過三個詞","examples":[{"en":"The answers must use no more than three words from the passage.","zh":"答案必須使用文章中不超過三個詞。"},{"en":"No more than three words means the answer must contain three words or fewer.","zh":"no more than three words 指答案必須包含三個或更少英文詞。"},{"en":"If the instruction says no more than three words, writing four words will lose marks.","zh":"如果指示說不超過三個詞，寫四個詞會失分。"},{"en":"Students should copy only the needed words and avoid adding extra explanation.","zh":"學生應只抄所需詞語，避免加入額外解釋。"},{"en":"This phrase sets a strict word limit for answers.","zh":"這個片語為答案設定嚴格字數限制。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":16},{"front":"formed when","meaning":"當……時形成","examples":[{"en":"Sulfurous acid rain formed when SO2 combined with water droplets.","zh":"當二氧化硫與水滴結合時，亞硫酸酸雨形成。"},{"en":"Formed when means was created at the time or under the condition that something happened.","zh":"formed when 指在某事發生時或在某條件下被創造出來。"},{"en":"Ice formed when the temperature fell below zero overnight.","zh":"當夜間氣溫降至零度以下時，冰形成了。"},{"en":"If acid rain formed when SO2 met water droplets, the atmosphere was driving chemical change.","zh":"如果酸雨在二氧化硫遇到水滴時形成，大氣正在推動化學變化。"},{"en":"This phrase explains the condition that creates something.","zh":"這個片語解釋創造某物的條件。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":17},{"front":"combine with","meaning":"與……結合","examples":[{"en":"SO2 may have combined with airborne water droplets.","zh":"二氧化硫可能與空氣中的水滴結合。"},{"en":"To combine with something means to join or react with it.","zh":"combine with something 指與某物結合或反應。"},{"en":"Flour combines with water to form dough.","zh":"麵粉與水結合形成麵團。"},{"en":"If SO2 combines with water droplets, it may produce acidic rain.","zh":"如果二氧化硫與水滴結合，它可能產生酸雨。"},{"en":"This phrase is common when describing chemical or physical mixing.","zh":"這個片語常用於描述化學或物理混合。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":17},{"front":"inhibit the buildup of","meaning":"抑制……的積聚","examples":[{"en":"Acid rain would inhibit the buildup of thick carbonate layers.","zh":"酸雨會抑制厚碳酸鹽層的積聚。"},{"en":"To inhibit the buildup of something means to slow or prevent its gradual accumulation.","zh":"inhibit the buildup of something 指減慢或阻止某物逐漸累積。"},{"en":"Regular cleaning can inhibit the buildup of dust in a classroom.","zh":"定期清潔可以抑制課室中灰塵積聚。"},{"en":"If acid rain inhibits the buildup of carbonate layers, expected rocks may be missing.","zh":"如果酸雨抑制碳酸鹽層積聚，預期中的岩石可能缺失。"},{"en":"This phrase focuses on stopping accumulation over time.","zh":"這個片語聚焦於阻止隨時間累積。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":17},{"front":"thick layers of","meaning":"厚厚的……層","examples":[{"en":"A humid atmosphere could produce thick layers of carbonate rocks.","zh":"潮濕大氣層可以產生厚厚的碳酸鹽岩層。"},{"en":"Thick layers of something are deep or heavy amounts of material built up over time.","zh":"thick layers of something 是隨時間累積形成的深厚或大量物質。"},{"en":"Thick layers of snow can block roads after a storm.","zh":"暴風雪後，厚厚的雪層可以堵塞道路。"},{"en":"If thick layers of rock do not appear where expected, scientists ask what stopped them forming.","zh":"如果預期中的厚岩層沒有出現，科學家會問是甚麼阻止它們形成。"},{"en":"This phrase describes large accumulation, not a thin surface mark.","zh":"這個片語描述大量積聚，而不是薄薄表面痕跡。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":17},{"front":"over time","meaning":"隨着時間過去","examples":[{"en":"Over time, carbon dioxide can be sequestered in rocks.","zh":"隨着時間過去，二氧化碳可以被封存在岩石中。"},{"en":"Over time means gradually as time passes.","zh":"over time 指隨時間逐漸地。"},{"en":"A student’s pronunciation improves over time with regular speaking practice.","zh":"學生透過定期口語練習，發音會隨時間改善。"},{"en":"Chemical reactions in rocks can change the atmosphere over time.","zh":"岩石中的化學反應可以隨着時間改變大氣。"},{"en":"This phrase suggests gradual change rather than instant results.","zh":"這個片語暗示逐漸變化，而不是即時結果。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":17},{"front":"accelerate greenhouse warming","meaning":"加速溫室增溫","examples":[{"en":"Stopping CO2 sequestration would allow SO2 to accelerate greenhouse warming.","zh":"停止二氧化碳封存會讓二氧化硫加速溫室增溫。"},{"en":"To accelerate greenhouse warming means to make heat-trapping warming happen faster or more strongly.","zh":"accelerate greenhouse warming 指令捕熱造成的增溫更快或更強。"},{"en":"More emissions can accelerate greenhouse warming on Earth.","zh":"更多排放可以加速地球上的溫室增溫。"},{"en":"If CO2 stays in the air instead of entering rocks, greenhouse warming may accelerate.","zh":"如果二氧化碳留在空氣中而不是進入岩石，溫室增溫可能加速。"},{"en":"This phrase describes speeding up a warming process.","zh":"這個片語描述加快增溫過程。"}],"source":"131 - Conflicting climatic phenomena co-existing on the Mars.pdf","sourcePage":17}],"ielts/reading/passage-2/Practice 132":[{"front":"war debris","meaning":"戰爭殘留物；戰爭廢料","examples":[{"en":"The passage discusses how war debris could cause cancer.","zh":"這篇文章討論戰爭殘留物如何可能引致癌症。"},{"en":"War debris means dangerous materials, weapons, fragments, or waste left behind after fighting.","zh":"War debris 指戰鬥後留下的危險材料、武器、碎片或廢料。"},{"en":"Children may find war debris in fields long after soldiers have left.","zh":"士兵離開很久後，兒童仍可能在田野中發現戰爭殘留物。"},{"en":"War debris can harm communities because toxic metals or unexploded weapons may remain in the ground.","zh":"戰爭殘留物可能傷害社區，因為有毒金屬或未爆武器可能仍留在地下。"},{"en":"Cleaning up war debris is important before people return to live, farm, or build in the area.","zh":"在人們返回居住、耕作或建設前，清理戰爭殘留物很重要。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":1},{"front":"cause cancer","meaning":"引致癌症","examples":[{"en":"Researchers are investigating whether war debris could cause cancer.","zh":"研究人員正在調查戰爭殘留物是否可能引致癌症。"},{"en":"To cause cancer means to increase the chance that cells grow abnormally and become cancerous.","zh":"To cause cancer 指增加細胞異常生長並變成癌細胞的機會。"},{"en":"Doctors warn that smoking can cause cancer because it damages cells over many years.","zh":"醫生警告吸煙可以引致癌症，因為它多年來損害細胞。"},{"en":"If a chemical can cause cancer, workers need protection when handling it.","zh":"如果某種化學物可引致癌症，工人在處理它時便需要保護。"},{"en":"This phrase describes a serious health risk, so evidence must be studied carefully.","zh":"這個片語描述嚴重健康風險，因此必須仔細研究證據。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":1},{"front":"the mystery over","meaning":"關於……的謎團","examples":[{"en":"The mystery over depleted uranium may be closer to being solved.","zh":"關於貧鈾的謎團可能更接近被解開。"},{"en":"The mystery over something is an unanswered question or unclear problem about it.","zh":"The mystery over something 指關於某事仍未解答的問題或不清楚的難題。"},{"en":"The mystery over a sudden illness may require tests, interviews, and medical records.","zh":"關於突發疾病的謎團可能需要檢測、訪問和醫療紀錄。"},{"en":"New evidence can reduce the mystery over a problem by showing a possible cause.","zh":"新證據可以透過顯示可能原因，減少關於某問題的謎團。"},{"en":"This phrase is useful when people still do not fully understand an issue.","zh":"這個片語適合用於人們仍未完全理解某議題時。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":1},{"front":"depleted uranium","meaning":"貧鈾","examples":[{"en":"Depleted uranium may cause genetic damage in people exposed to it.","zh":"貧鈾可能對接觸到它的人造成基因損傷。"},{"en":"Depleted uranium is a very dense form of uranium left after some radioactive material has been removed.","zh":"貧鈾是一種非常高密度的鈾，是部分放射性物質被移除後留下的形式。"},{"en":"The military uses depleted uranium because it can help weapons pierce heavy armour.","zh":"軍方使用貧鈾，因為它可以幫助武器穿透厚重裝甲。"},{"en":"Health concerns arise when depleted uranium dust or fragments remain in the environment.","zh":"當貧鈾塵埃或碎片殘留在環境中，便會引起健康憂慮。"},{"en":"This phrase is often discussed in debates about war, radiation, and long-term health risks.","zh":"這個詞常出現在關於戰爭、輻射和長期健康風險的爭論中。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":1},{"front":"genetic damage","meaning":"基因損傷","examples":[{"en":"Researchers are studying how depleted uranium might cause genetic damage.","zh":"研究人員正在研究貧鈾可能如何造成基因損傷。"},{"en":"Genetic damage means harm to DNA or other material that carries biological instructions in cells.","zh":"Genetic damage 指對DNA或細胞中攜帶生物指令的其他物質造成傷害。"},{"en":"Strong radiation can cause genetic damage if it breaks or changes DNA inside cells.","zh":"強輻射如果破壞或改變細胞內DNA，便可能造成基因損傷。"},{"en":"Genetic damage may increase disease risk because cells may not repair themselves properly.","zh":"基因損傷可能增加疾病風險，因為細胞可能無法正確修復自己。"},{"en":"This phrase is important in discussions of cancer, radiation, and inherited health problems.","zh":"這個片語在癌症、輻射和遺傳健康問題討論中很重要。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":1},{"front":"be closer to being solved","meaning":"更接近被解開","examples":[{"en":"The mystery may be closer to being solved.","zh":"這個謎團可能更接近被解開。"},{"en":"To be closer to being solved means that people have made progress toward finding the answer.","zh":"To be closer to being solved 指人們在尋找答案方面取得進展。"},{"en":"A school’s attendance problem is closer to being solved when teachers discover why students are absent.","zh":"當老師發現學生缺席的原因時，學校的出席問題就更接近被解決。"},{"en":"New data can make a medical mystery closer to being solved.","zh":"新數據可以令醫學謎團更接近被解開。"},{"en":"This phrase shows progress, but not final certainty.","zh":"這個片語顯示進展，但不是最終確定。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":1},{"front":"controversial claim","meaning":"有爭議的主張","examples":[{"en":"A controversial claim by two researchers may explain the problem.","zh":"兩名研究人員提出的一項有爭議的主張可能解釋這個問題。"},{"en":"A controversial claim is a statement that many people debate, doubt, or disagree with.","zh":"Controversial claim 是許多人會爭論、懷疑或不同意的說法。"},{"en":"A doctor’s controversial claim about a new treatment needs strong evidence before people accept it.","zh":"醫生對新治療提出有爭議的主張，在被接受前需要強有力證據。"},{"en":"A claim becomes controversial when it challenges official views or existing research.","zh":"當一項主張挑戰官方觀點或現有研究，它便會變得有爭議。"},{"en":"This phrase warns readers that the idea is not accepted by everyone.","zh":"這個片語提醒讀者，該想法並非人人接受。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":1},{"front":"minute quantities of","meaning":"微量的……","examples":[{"en":"Minute quantities of depleted uranium may remain lodged in the body.","zh":"微量的貧鈾可能仍留在體內。"},{"en":"Minute quantities of something are extremely small amounts of it.","zh":"Minute quantities of something 指極少量的某物。"},{"en":"Minute quantities of medicine can still affect a baby, so doctors measure doses carefully.","zh":"微量藥物仍可能影響嬰兒，所以醫生會仔細量度劑量。"},{"en":"Even minute quantities of toxic material may matter if they stay inside the body for years.","zh":"即使是微量有毒物質，如果多年留在體內，也可能重要。"},{"en":"This phrase emphasises that the amount is tiny, but not necessarily harmless.","zh":"這個片語強調數量很小，但不一定無害。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":1},{"front":"lodged in the body","meaning":"留在體內","examples":[{"en":"The material may become lodged in the body.","zh":"這種物質可能留在體內。"},{"en":"If something is lodged in the body, it is stuck inside body tissue and does not easily leave.","zh":"If something is lodged in the body，意思是它卡在身體組織內，不容易離開。"},{"en":"A tiny metal fragment may become lodged in the body after an accident.","zh":"意外後，微小金屬碎片可能留在體內。"},{"en":"Material lodged in the body can cause concern if it is toxic or radioactive.","zh":"如果留在體內的物質有毒或具放射性，便會引起憂慮。"},{"en":"This phrase describes something remaining inside the body, not simply touching the skin.","zh":"這個片語描述某物留在身體內，而不只是接觸皮膚。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":1},{"front":"kick out","meaning":"釋放；擊出","examples":[{"en":"Depleted uranium may kick out energetic electrons.","zh":"貧鈾可能釋放高能電子。"},{"en":"To kick out particles means to force them out from where they were held.","zh":"To kick out particles 指把粒子從原本所在位置迫出。"},{"en":"In physics, light can kick out electrons from a metal surface under certain conditions.","zh":"在物理學中，光在某些條件下可以從金屬表面擊出電子。"},{"en":"If radiation kicks out electrons near DNA, it may cause damage to genetic material.","zh":"如果輻射在DNA附近擊出電子，可能對遺傳物質造成損傷。"},{"en":"This phrase is informal, but it helps describe particles being ejected.","zh":"這個片語較口語，但有助描述粒子被射出。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":1},{"front":"energetic electrons","meaning":"高能電子","examples":[{"en":"The material may release energetic electrons inside the body.","zh":"這種物質可能在體內釋放高能電子。"},{"en":"Energetic electrons are electrons with enough energy to move quickly and possibly damage nearby matter.","zh":"Energetic electrons 是具有足夠能量快速移動並可能損害附近物質的電子。"},{"en":"Energetic electrons can be important in radiation effects because they may hit molecules.","zh":"高能電子在輻射效應中可能很重要，因為它們可能撞擊分子。"},{"en":"If energetic electrons are released near cells, scientists may worry about DNA damage.","zh":"如果高能電子在細胞附近被釋放，科學家可能擔心DNA損傷。"},{"en":"This phrase describes small particles with potentially strong biological effects.","zh":"這個片語描述可能具有強烈生物效應的小粒子。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":1},{"front":"mimic the effect of","meaning":"模仿……的作用","examples":[{"en":"The electrons may mimic the effect of beta radiation.","zh":"這些電子可能模仿β輻射的作用。"},{"en":"To mimic the effect of something means to act in a similar way or produce a similar result.","zh":"To mimic the effect of something 指以相似方式運作或產生相似結果。"},{"en":"A training app can mimic the effect of a real tutor by giving immediate feedback.","zh":"培訓應用程式可以透過即時回饋模仿真人導師的作用。"},{"en":"If one type of radiation mimics the effect of another, it may create similar damage.","zh":"如果一種輻射模仿另一種輻射的作用，它可能造成相似損傷。"},{"en":"This phrase compares effects, not necessarily causes.","zh":"這個片語比較作用，而不一定比較原因。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":2},{"front":"beta radiation","meaning":"β 輻射","examples":[{"en":"The researchers compare the effect to beta radiation.","zh":"研究人員把這種作用與β輻射作比較。"},{"en":"Beta radiation is radiation made of fast-moving beta particles, which can damage living tissue.","zh":"β輻射是由快速移動的β粒子組成的輻射，可能損害活體組織。"},{"en":"Scientists measure beta radiation carefully when testing contaminated materials.","zh":"科學家在測試受污染材料時會仔細量度β輻射。"},{"en":"If a process acts like beta radiation, it may raise concerns about cell damage.","zh":"如果某過程像β輻射一樣運作，便可能引起細胞損傷憂慮。"},{"en":"This phrase is used in nuclear physics, medicine, and radiation safety.","zh":"這個片語用於核物理、醫學和輻射安全。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":2},{"front":"this, they argue, could explain","meaning":"他們認為，這可以解釋","examples":[{"en":"This, they argue, could explain the increased cancer risk.","zh":"他們認為，這可以解釋癌症風險增加。"},{"en":"“This, they argue, could explain” introduces a proposed explanation that the speakers believe may be true.","zh":"“This, they argue, could explain” 用來引出說話者認為可能正確的解釋。"},{"en":"Poor sleep, doctors argue, could explain the student’s weak concentration.","zh":"醫生認為，睡眠不足可以解釋學生專注力差。"},{"en":"A hidden system problem, managers argue, could explain repeated customer complaints.","zh":"管理層認為，隱藏的制度問題可以解釋反覆出現的顧客投訴。"},{"en":"This structure makes clear that the explanation belongs to the people making the argument.","zh":"這個結構清楚顯示該解釋屬於提出論點的人。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":2},{"front":"residues of","meaning":"……的殘留物","examples":[{"en":"Residues of depleted uranium may remain in former war zones.","zh":"貧鈾的殘留物可能留在昔日戰區。"},{"en":"Residues of something are small amounts left behind after the main material is gone or used.","zh":"Residues of something 指主要物質消失或被使用後留下的小量物質。"},{"en":"Residues of cleaning chemicals may remain on plates if they are not rinsed well.","zh":"如果餐具沒有沖洗乾淨，清潔劑殘留物可能留在碟上。"},{"en":"Dangerous residues can affect health if people breathe, touch, or ingest them.","zh":"如果人們吸入、接觸或攝入危險殘留物，健康可能受影響。"},{"en":"This phrase often appears in discussions of pollution and contamination.","zh":"這個片語常出現在污染和受污染物討論中。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":2},{"front":"scattered across","meaning":"散布於","examples":[{"en":"Residues of depleted uranium may be scattered across former war zones.","zh":"貧鈾殘留物可能散布於昔日戰區。"},{"en":"Scattered across a place means spread over many parts of that area.","zh":"Scattered across a place 指分散在該地區的許多部分。"},{"en":"After a festival, rubbish may be scattered across the park.","zh":"節日後，垃圾可能散布於公園各處。"},{"en":"If toxic fragments are scattered across farmland, cleanup becomes harder.","zh":"如果有毒碎片散布於農田，清理工作會更困難。"},{"en":"This phrase suggests wide spread rather than one neat pile.","zh":"這個片語暗示廣泛分布，而不是整齊一堆。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":2},{"front":"former war zones","meaning":"昔日戰區","examples":[{"en":"Depleted uranium residues can remain in former war zones.","zh":"貧鈾殘留物可能留在昔日戰區。"},{"en":"Former war zones are places where fighting happened in the past but may now be inhabited again.","zh":"Former war zones 是過去曾發生戰鬥、但現在可能重新有人居住的地方。"},{"en":"Farmers may return to former war zones after the conflict ends.","zh":"衝突結束後，農民可能返回昔日戰區。"},{"en":"Former war zones can still be dangerous if mines, shells, or toxic dust remain.","zh":"如果地雷、炮彈或有毒塵埃仍在，昔日戰區仍可能危險。"},{"en":"This phrase reminds us that war can leave risks long after battles finish.","zh":"這個片語提醒我們，戰爭在戰鬥結束很久後仍會留下風險。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":2},{"front":"increase the risk of","meaning":"增加……的風險","examples":[{"en":"The residues may increase the risk of cancers and other problems.","zh":"這些殘留物可能增加癌症和其他問題的風險。"},{"en":"To increase the risk of something means to make it more likely to happen.","zh":"To increase the risk of something 指令某事更可能發生。"},{"en":"Poor diet and little exercise can increase the risk of heart disease.","zh":"不良飲食和少運動可以增加心臟病風險。"},{"en":"If a substance damages DNA, it may increase the risk of cancer.","zh":"如果某物質損害DNA，它可能增加癌症風險。"},{"en":"This phrase describes probability, not certainty.","zh":"這個片語描述可能性，而不是確定性。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":2},{"front":"cancers and other problems","meaning":"癌症和其他問題","examples":[{"en":"The theory may explain cancers and other health problems.","zh":"這個理論可能解釋癌症和其他健康問題。"},{"en":"Cancers and other problems means cancer plus additional illnesses or harmful effects.","zh":"Cancers and other problems 指癌症加上其他疾病或有害影響。"},{"en":"Pollution may be linked to cancers and other problems such as breathing difficulties.","zh":"污染可能與癌症和其他問題有關，例如呼吸困難。"},{"en":"Doctors investigate cancers and other problems by looking at exposure history and medical records.","zh":"醫生透過查看接觸史和醫療紀錄來調查癌症和其他問題。"},{"en":"This phrase groups cancer with wider health concerns.","zh":"這個片語把癌症與更廣泛健康憂慮放在一起。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":2},{"front":"among soldiers and local people","meaning":"在士兵和本地居民之中","examples":[{"en":"Health problems may occur among soldiers and local people.","zh":"健康問題可能出現在士兵和本地居民之中。"},{"en":"Among soldiers and local people means within both military personnel and civilians living in the area.","zh":"Among soldiers and local people 指在軍人和居住於該地區的平民之中。"},{"en":"After a conflict, illness may appear among soldiers and local people who shared the same environment.","zh":"衝突後，疾病可能出現在曾處於同一環境的士兵和本地居民之中。"},{"en":"Studying both groups can help researchers compare different kinds of exposure.","zh":"研究兩個群體可以幫助研究人員比較不同接觸方式。"},{"en":"This phrase shows that the concern is not limited to the army.","zh":"這個片語顯示憂慮並不限於軍隊。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":2},{"front":"be highly valued by","meaning":"受到……高度重視","examples":[{"en":"Depleted uranium is highly valued by the military.","zh":"貧鈾受到軍方高度重視。"},{"en":"To be highly valued by someone means they consider it very useful or important.","zh":"To be highly valued by someone 指某人認為它非常有用或重要。"},{"en":"Accurate maps are highly valued by rescue teams during emergencies.","zh":"在緊急情況中，準確地圖受到救援隊高度重視。"},{"en":"A material may be highly valued by the military if it gives weapons a practical advantage.","zh":"如果某材料能給武器實際優勢，便可能受到軍方高度重視。"},{"en":"This phrase shows importance from a particular group’s point of view.","zh":"這個片語顯示某事從特定群體角度看很重要。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":2},{"front":"the military","meaning":"軍方","examples":[{"en":"The military uses depleted uranium in armour-piercing weapons.","zh":"軍方在穿甲武器中使用貧鈾。"},{"en":"The military means the armed forces of a country, such as the army, navy, and air force.","zh":"The military 指一個國家的武裝力量，例如陸軍、海軍和空軍。"},{"en":"The military may use special materials that are not common in ordinary industry.","zh":"軍方可能使用在普通工業中不常見的特殊材料。"},{"en":"Decisions by the military can affect soldiers, civilians, and the environment.","zh":"軍方的決定可以影響士兵、平民和環境。"},{"en":"This phrase refers to defence organisations, not private security guards.","zh":"這個片語指國防組織，而不是私人保安。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":2},{"front":"tips of armour-piercing weapons","meaning":"穿甲武器的尖端","examples":[{"en":"The military uses depleted uranium in the tips of armour-piercing weapons.","zh":"軍方在穿甲武器的尖端使用貧鈾。"},{"en":"The tips of armour-piercing weapons are the pointed front parts designed to strike and enter hard targets.","zh":"Tips of armour-piercing weapons 是設計用來撞擊並穿入堅硬目標的尖銳前端部分。"},{"en":"A hard metal tip helps a weapon break through armour more effectively.","zh":"堅硬金屬尖端有助武器更有效穿透裝甲。"},{"en":"If the tip contains toxic material, fragments may create environmental concerns after impact.","zh":"如果尖端含有有毒物質，撞擊後碎片可能造成環境憂慮。"},{"en":"This phrase identifies the exact part of the weapon where the material is used.","zh":"這個片語指出材料被用於武器的確切部分。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":3},{"front":"armour-piercing weapons","meaning":"穿甲武器","examples":[{"en":"Armour-piercing weapons are designed to penetrate tanks and bunkers.","zh":"穿甲武器被設計用來穿透坦克和碉堡。"},{"en":"Armour-piercing weapons are weapons made to break through strong protective metal or concrete.","zh":"Armour-piercing weapons 是用來穿破強大金屬或混凝土保護層的武器。"},{"en":"The military may use armour-piercing weapons against heavily protected vehicles.","zh":"軍方可能使用穿甲武器攻擊受到重度保護的車輛。"},{"en":"Because these weapons hit hard targets, their fragments may scatter after impact.","zh":"因為這些武器撞擊堅硬目標，其碎片可能在撞擊後散開。"},{"en":"This phrase describes the purpose of the weapon, not simply its size.","zh":"這個片語描述武器用途，而不只是大小。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":3},{"front":"high density","meaning":"高密度","examples":[{"en":"The material’s high density helps it penetrate armour.","zh":"這種材料的高密度幫助它穿透裝甲。"},{"en":"High density means a lot of mass packed into a small volume.","zh":"High density 指大量質量集中在小體積內。"},{"en":"Lead has high density, so a small piece can feel surprisingly heavy.","zh":"鉛具有高密度，所以一小塊也會感覺出奇地重。"},{"en":"A high-density material can be useful when force must be concentrated into a small area.","zh":"當力量必須集中在小範圍時，高密度材料可能有用。"},{"en":"This phrase explains why some materials feel heavy and powerful for their size.","zh":"這個片語解釋為何某些材料相對大小而言感覺沉重而有力。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":3},{"front":"self-sharpening properties","meaning":"自銳特性；自我磨尖特性","examples":[{"en":"Depleted uranium has self-sharpening properties.","zh":"貧鈾具有自銳特性。"},{"en":"Self-sharpening properties are features that help a material keep or form a sharp point during impact.","zh":"Self-sharpening properties 是幫助材料在撞擊時保持或形成尖銳端點的特性。"},{"en":"A self-sharpening tool stays effective longer because its edge does not become blunt quickly.","zh":"自我磨尖工具的邊緣不會很快變鈍，因此能更長時間保持有效。"},{"en":"In weapons, self-sharpening properties can help the tip keep penetrating instead of flattening.","zh":"在武器中，自銳特性可以幫助尖端繼續穿透，而不是變平。"},{"en":"This phrase describes how a material behaves under stress.","zh":"這個片語描述材料在壓力下如何表現。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":3},{"front":"help it to penetrate","meaning":"幫助它穿透","examples":[{"en":"Its properties help it to penetrate enemy armour.","zh":"它的特性幫助它穿透敵方裝甲。"},{"en":"To help it to penetrate means to make it easier for the object to enter or pass through a hard surface.","zh":"To help it to penetrate 指使該物體更容易進入或穿過堅硬表面。"},{"en":"A sharp drill tip helps it to penetrate wood more quickly.","zh":"銳利鑽頭幫助它更快穿透木材。"},{"en":"High density and a sharp point can help a material penetrate protective layers.","zh":"高密度和尖銳端點可以幫助材料穿透保護層。"},{"en":"This phrase connects a feature with its practical effect.","zh":"這個片語把特徵與實際效果連接起來。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":3},{"front":"enemy tanks and bunkers","meaning":"敵方坦克和碉堡","examples":[{"en":"The material can penetrate the armour of enemy tanks and bunkers.","zh":"這種材料可以穿透敵方坦克和碉堡的裝甲。"},{"en":"Enemy tanks and bunkers are military vehicles and defensive structures used by the opposing side.","zh":"Enemy tanks and bunkers 是敵對一方使用的軍事車輛和防禦建築。"},{"en":"Tanks are protected by armour, while bunkers are often protected by thick concrete or earth.","zh":"坦克有裝甲保護，而碉堡通常由厚混凝土或泥土保護。"},{"en":"Weapons designed for enemy tanks and bunkers must break through strong protection.","zh":"針對敵方坦克和碉堡的武器必須穿破強大防護。"},{"en":"This phrase identifies hard military targets.","zh":"這個片語指出堅硬軍事目標。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":3},{"front":"its use in conflicts","meaning":"它在衝突中的使用","examples":[{"en":"Its use in conflicts has risen sharply in recent years.","zh":"它在衝突中的使用近年來急劇上升。"},{"en":"Its use in conflicts means how often it is used during wars or armed clashes.","zh":"Its use in conflicts 指它在戰爭或武裝衝突中被使用的頻率。"},{"en":"The use of drones in conflicts has changed how armies gather information.","zh":"無人機在衝突中的使用改變了軍隊收集資訊的方式。"},{"en":"When a weapon’s use in conflicts rises, health and environmental concerns may also grow.","zh":"當某武器在衝突中的使用增加，健康和環境憂慮也可能增加。"},{"en":"This phrase focuses on use during fighting, not peaceful industry.","zh":"這個片語著重戰鬥中的使用，而不是和平工業用途。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":3},{"front":"risen sharply","meaning":"急劇上升","examples":[{"en":"The use of depleted uranium has risen sharply.","zh":"貧鈾的使用已急劇上升。"},{"en":"To rise sharply means to increase quickly and by a large amount.","zh":"To rise sharply 指快速而大幅增加。"},{"en":"Food prices may rise sharply after a poor harvest.","zh":"收成差後，食物價格可能急劇上升。"},{"en":"If hospital visits rise sharply, doctors may suspect a new health problem.","zh":"如果求診人數急劇上升，醫生可能懷疑有新的健康問題。"},{"en":"This phrase describes a strong upward change.","zh":"這個片語描述強烈向上變化。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":3},{"front":"in recent years","meaning":"近年來","examples":[{"en":"The material has been used more often in recent years.","zh":"這種材料近年來被更頻繁使用。"},{"en":"In recent years means during the last few years, not a long time ago.","zh":"In recent years 指在過去幾年，而不是很久以前。"},{"en":"In recent years, many schools have used more online learning tools.","zh":"近年來，許多學校使用了更多網上學習工具。"},{"en":"If a problem has grown in recent years, researchers may ask what changed.","zh":"如果某問題近年來擴大，研究人員可能會問有甚麼改變。"},{"en":"This phrase places a trend in the near past.","zh":"這個片語把趨勢放在近過去。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":3},{"front":"the UN Environment Programme","meaning":"聯合國環境規劃署","examples":[{"en":"The UN Environment Programme estimates the amount used in the Iraq war.","zh":"聯合國環境規劃署估計伊拉克戰爭中使用的數量。"},{"en":"The UN Environment Programme is a United Nations body concerned with environmental issues.","zh":"聯合國環境規劃署是關注環境議題的聯合國機構。"},{"en":"It may study pollution, toxic waste, climate change, and damage after conflicts.","zh":"它可能研究污染、有毒廢物、氣候變化和衝突後損害。"},{"en":"International bodies can help estimate environmental risks when local data are incomplete.","zh":"當本地數據不完整，國際機構可以幫助估計環境風險。"},{"en":"This phrase names an organisation, not a research method.","zh":"這個片語命名一個組織，而不是研究方法。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":3},{"front":"estimates that","meaning":"估計","examples":[{"en":"UNEP estimates that shells containing the material were fired in Iraq.","zh":"聯合國環境規劃署估計含有該材料的炮彈曾在伊拉克被發射。"},{"en":"Estimates that means makes an informed calculation or judgement that something is true.","zh":"Estimates that 指根據資料作出有根據的計算或判斷。"},{"en":"A school estimates that 300 students will attend the event based on past numbers.","zh":"學校根據過往人數估計會有300名學生出席活動。"},{"en":"Officials estimate that cleanup will take years if contamination is widespread.","zh":"如果污染廣泛，官員估計清理工作需要多年。"},{"en":"This phrase suggests a careful approximation, not an exact count.","zh":"這個片語暗示仔細近似估算，而不是精確數字。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":3},{"front":"shells containing","meaning":"含有……的炮彈","examples":[{"en":"Shells containing depleted uranium were fired during the war.","zh":"戰爭期間發射了含有貧鈾的炮彈。"},{"en":"Shells containing something are explosive projectiles or ammunition that include that material inside or as part of them.","zh":"Shells containing something 是指內部或部件中含有該材料的爆炸性彈藥或炮彈。"},{"en":"Shells containing toxic material can leave dangerous residues after impact.","zh":"含有有毒物質的炮彈在撞擊後可能留下危險殘留物。"},{"en":"If shells containing uranium are used, investigators may test soil and dust later.","zh":"如果使用含有鈾的炮彈，調查人員之後可能測試土壤和塵埃。"},{"en":"This phrase identifies what substance is present in the ammunition.","zh":"這個片語指出彈藥中存在甚麼物質。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":4},{"front":"were fired during","meaning":"在……期間被發射","examples":[{"en":"Many shells were fired during the 2003 Iraq war.","zh":"許多炮彈在2003年伊拉克戰爭期間被發射。"},{"en":"Were fired during means were shot or launched in the period of a particular event.","zh":"Were fired during 指在某事件期間被射出或發射。"},{"en":"Fireworks were fired during the festival, so noise levels rose at night.","zh":"煙花在節日期間被發射，所以夜間噪音上升。"},{"en":"If many shells were fired during a battle, fragments may remain in the area.","zh":"如果許多炮彈在戰鬥期間被發射，碎片可能留在該地區。"},{"en":"This phrase connects an action with the time it happened.","zh":"這個片語把行動與發生時間連接起來。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":4},{"front":"the 2003 Iraq war","meaning":"2003 年伊拉克戰爭","examples":[{"en":"Large quantities of depleted uranium were used during the 2003 Iraq war.","zh":"大量貧鈾在2003年伊拉克戰爭期間被使用。"},{"en":"The 2003 Iraq war refers to the military conflict in Iraq that began in 2003.","zh":"The 2003 Iraq war 指2003年開始的伊拉克軍事衝突。"},{"en":"Researchers may study the 2003 Iraq war to understand later health and environmental concerns.","zh":"研究人員可能研究2003年伊拉克戰爭，以理解後來的健康和環境憂慮。"},{"en":"Weapons used in that war may have left residues in affected areas.","zh":"該戰爭中使用的武器可能在受影響地區留下殘留物。"},{"en":"This phrase places the discussion in a specific historical conflict.","zh":"這個片語把討論放在特定歷史衝突中。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":4},{"front":"researchers and campaigners","meaning":"研究人員和運動人士","examples":[{"en":"Some researchers and campaigners are concerned about depleted uranium.","zh":"一些研究人員和運動人士擔心貧鈾。"},{"en":"Researchers and campaigners are people who study an issue and people who publicly push for action on it.","zh":"Researchers and campaigners 是研究某議題的人，以及公開推動就該議題採取行動的人。"},{"en":"Researchers may collect data, while campaigners may ask governments to change policy.","zh":"研究人員可能收集數據，而運動人士可能要求政府改變政策。"},{"en":"When researchers and campaigners agree on a risk, public pressure may increase.","zh":"當研究人員和運動人士都同意某風險存在，公眾壓力可能增加。"},{"en":"This phrase combines scientific investigation with social activism.","zh":"這個片語結合科學調查和社會倡議。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":4},{"front":"be convinced that","meaning":"深信","examples":[{"en":"Some campaigners are convinced that depleted uranium causes illness.","zh":"一些運動人士深信貧鈾會導致疾病。"},{"en":"To be convinced that something is true means to strongly believe it.","zh":"To be convinced that something is true 指強烈相信某事是真的。"},{"en":"Parents may be convinced that a school policy is unfair after seeing several examples.","zh":"家長在看見幾個例子後，可能深信某項學校政策不公平。"},{"en":"People can be convinced by personal experience even before full scientific proof exists.","zh":"即使完整科學證據尚未存在，人們也可能被個人經驗說服。"},{"en":"This phrase describes strong belief, not necessarily final evidence.","zh":"這個片語描述強烈信念，而不一定是最終證據。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":4},{"front":"left in the environment","meaning":"殘留在環境中","examples":[{"en":"Depleted uranium left in the environment may affect human health.","zh":"殘留在環境中的貧鈾可能影響人體健康。"},{"en":"Left in the environment means remaining in soil, water, air, or buildings after use or release.","zh":"Left in the environment 指使用或釋放後仍留在土壤、水、空氣或建築物中。"},{"en":"Chemicals left in the environment can enter food or drinking water.","zh":"殘留在環境中的化學物可以進入食物或飲用水。"},{"en":"If toxic waste is left in the environment, people may be exposed without knowing it.","zh":"如果有毒廢物殘留在環境中，人們可能在不知情下接觸到它。"},{"en":"This phrase describes pollution that has not been removed.","zh":"這個片語描述尚未被清除的污染。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":4},{"front":"spent munitions","meaning":"已使用的軍火；殘餘彈藥","examples":[{"en":"Spent munitions can leave depleted uranium in the environment.","zh":"已使用的軍火可能把貧鈾留在環境中。"},{"en":"Spent munitions are ammunition or weapons that have already been fired or used.","zh":"Spent munitions 是已經發射或使用過的彈藥或武器。"},{"en":"After a battle, spent munitions may remain in fields, roads, and damaged buildings.","zh":"戰鬥後，殘餘彈藥可能留在田野、道路和受損建築中。"},{"en":"Spent munitions can create risks if fragments are toxic or explosive.","zh":"如果碎片有毒或具爆炸性，已使用的軍火可能造成風險。"},{"en":"This phrase focuses on used military materials left behind.","zh":"這個片語著重留下來的已用軍事材料。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":4},{"front":"birth defects","meaning":"先天缺陷","examples":[{"en":"Campaigners claim that depleted uranium may cause birth defects.","zh":"運動人士聲稱貧鈾可能造成先天缺陷。"},{"en":"Birth defects are physical or developmental problems present when a baby is born.","zh":"Birth defects 是嬰兒出生時已存在的身體或發育問題。"},{"en":"Doctors may investigate birth defects by studying family history, environment, and pregnancy conditions.","zh":"醫生可能透過研究家族史、環境和懷孕情況來調查先天缺陷。"},{"en":"If a toxin increases birth defects, public health officials must identify and reduce exposure.","zh":"如果毒素增加先天缺陷，公共衛生官員必須找出並減少接觸。"},{"en":"This phrase refers to serious health problems affecting newborn babies.","zh":"這個片語指影響新生兒的嚴重健康問題。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":4},{"front":"other ill effects","meaning":"其他有害影響","examples":[{"en":"Some people believe depleted uranium causes cancer and other ill effects.","zh":"有些人相信貧鈾會造成癌症和其他有害影響。"},{"en":"Other ill effects are additional harmful results besides the main problem mentioned.","zh":"Other ill effects 是除了已提及主要問題以外的其他有害結果。"},{"en":"A medicine may reduce pain but create other ill effects such as dizziness.","zh":"藥物可能減輕痛楚，但造成頭暈等其他有害影響。"},{"en":"Pollution can cause breathing problems and other ill effects over time.","zh":"污染可以隨時間造成呼吸問題和其他有害影響。"},{"en":"This phrase keeps the discussion broad when not all harms are named.","zh":"當並非所有傷害都被列出時，這個片語令討論保持廣泛。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":4},{"front":"people exposed to it","meaning":"接觸到它的人","examples":[{"en":"People exposed to depleted uranium may face health risks.","zh":"接觸到貧鈾的人可能面對健康風險。"},{"en":"People exposed to it are people who have come into contact with the substance through air, water, food, skin, or wounds.","zh":"People exposed to it 是透過空氣、水、食物、皮膚或傷口接觸到該物質的人。"},{"en":"Workers exposed to a chemical may need medical checks even if they feel healthy.","zh":"接觸到化學物的工人即使感覺健康，也可能需要醫療檢查。"},{"en":"The health risk depends on how much people were exposed to it and for how long.","zh":"健康風險取決於人們接觸到它的量和時間。"},{"en":"This phrase identifies the group that may be affected.","zh":"這個片語指出可能受影響的群體。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":4},{"front":"governments and the military","meaning":"政府和軍方","examples":[{"en":"Governments and the military disagree with some campaigners’ claims.","zh":"政府和軍方不同意一些運動人士的主張。"},{"en":"Governments and the military are state authorities and armed forces involved in policy and defence decisions.","zh":"Governments and the military 是參與政策和國防決定的國家當局和武裝力量。"},{"en":"Governments may focus on public evidence, while the military may focus on weapon effectiveness.","zh":"政府可能集中於公開證據，而軍方可能集中於武器效能。"},{"en":"If governments and the military reject a claim, campaigners may demand independent studies.","zh":"如果政府和軍方否認某項主張，運動人士可能要求獨立研究。"},{"en":"This phrase refers to official institutions with political and defence power.","zh":"這個片語指具有政治和國防權力的官方機構。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":4},{"front":"point out that","meaning":"指出","examples":[{"en":"They point out that there is no conclusive evidence.","zh":"他們指出沒有確鑿證據。"},{"en":"To point out that something is true means to draw attention to it as an important fact.","zh":"To point out that something is true 指指出某事作為重要事實，讓人注意。"},{"en":"A teacher may point out that an answer must come from the passage, not from memory.","zh":"老師可能指出答案必須來自文章，而不是記憶。"},{"en":"Officials may point out that a claim needs stronger data before policy changes.","zh":"官員可能指出，一項主張在政策改變前需要更強數據。"},{"en":"This phrase introduces a fact or argument someone wants others to notice.","zh":"這個片語引出某人希望他人注意的事實或論點。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":5},{"front":"conclusive epidemiological evidence","meaning":"確鑿的流行病學證據","examples":[{"en":"There is no conclusive epidemiological evidence for the claim.","zh":"這項主張沒有確鑿的流行病學證據。"},{"en":"Conclusive epidemiological evidence is strong population-level evidence that clearly proves a link between exposure and disease.","zh":"Conclusive epidemiological evidence 是清楚證明接觸與疾病之間關聯的強力人口層面證據。"},{"en":"Doctors need epidemiological evidence to see whether illness is more common in exposed groups.","zh":"醫生需要流行病學證據，判斷疾病是否在接觸群體中更常見。"},{"en":"Without conclusive epidemiological evidence, a health claim may remain disputed.","zh":"沒有確鑿的流行病學證據，健康主張可能仍有爭議。"},{"en":"This phrase is formal and often used in public health debates.","zh":"這個片語較正式，常用於公共衛生爭論。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":5},{"front":"acknowledge that","meaning":"承認","examples":[{"en":"Governments acknowledge that the material is weakly radioactive.","zh":"政府承認這種材料是弱放射性的。"},{"en":"To acknowledge that something is true means to admit or accept it.","zh":"To acknowledge that something is true 指承認或接受某事是真的。"},{"en":"A company may acknowledge that its service was slow after many complaints.","zh":"公司在收到許多投訴後，可能承認服務很慢。"},{"en":"Acknowledging one fact does not mean accepting every claim connected to it.","zh":"承認一個事實不代表接受與它相關的每一項主張。"},{"en":"This phrase often introduces partial agreement.","zh":"這個片語常引出部分同意。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":5},{"front":"weakly radioactive","meaning":"弱放射性的","examples":[{"en":"Depleted uranium is weakly radioactive.","zh":"貧鈾是弱放射性的。"},{"en":"Weakly radioactive means giving off radiation at a low level.","zh":"Weakly radioactive 指以低水平釋放輻射。"},{"en":"A weakly radioactive material may still require careful handling if exposure is long-term.","zh":"如果接觸是長期的，弱放射性材料仍可能需要小心處理。"},{"en":"Officials may argue that weak radioactivity alone cannot explain severe damage.","zh":"官員可能主張，單靠弱放射性不足以解釋嚴重損害。"},{"en":"This phrase describes level of radiation, not complete safety.","zh":"這個片語描述輻射水平，而不是完全安全。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":5},{"front":"too small to explain","meaning":"太小，不足以解釋","examples":[{"en":"They say the radioactive effect is too small to explain the damage.","zh":"他們說放射性作用太小，不足以解釋損害。"},{"en":"Too small to explain means not strong or large enough to account for a result.","zh":"Too small to explain 指不夠強或不夠大，無法解釋某結果。"},{"en":"A tiny price change may be too small to explain a sudden drop in sales.","zh":"微小價格變化可能太小，不足以解釋銷售突然下降。"},{"en":"If radiation is too small to explain illness, researchers must look for other mechanisms.","zh":"如果輻射太小，不足以解釋疾病，研究人員必須尋找其他機制。"},{"en":"This phrase rejects a cause as insufficient.","zh":"這個片語否定某原因足夠解釋結果。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":5},{"front":"war veterans","meaning":"退伍軍人","examples":[{"en":"Genetic damage has been reported in war veterans and civilians.","zh":"退伍軍人和平民中都有基因損傷報告。"},{"en":"War veterans are people who have served in the armed forces during a war.","zh":"War veterans 是曾在戰爭期間服役的軍人。"},{"en":"War veterans may face long-term health problems after returning home.","zh":"退伍軍人回家後可能面對長期健康問題。"},{"en":"Studying war veterans can help researchers understand possible effects of battlefield exposure.","zh":"研究退伍軍人可以幫助研究人員理解戰場接觸的可能影響。"},{"en":"This phrase refers to former soldiers, not current civilians.","zh":"這個片語指前軍人，而不是現役平民。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":5},{"front":"civilians","meaning":"平民","examples":[{"en":"The passage refers to both war veterans and civilians.","zh":"文章同時提到退伍軍人和平民。"},{"en":"Civilians are people who are not members of the military or armed forces.","zh":"Civilians 是不屬於軍隊或武裝力量的人。"},{"en":"Civilians living near a conflict zone may face risks even if they never fight.","zh":"住在衝突區附近的平民即使從未作戰，也可能面對風險。"},{"en":"When weapons leave toxic residues, civilians can be affected long after soldiers leave.","zh":"當武器留下有毒殘留物，士兵離開很久後平民仍可能受影響。"},{"en":"This word contrasts ordinary residents with soldiers.","zh":"這個詞把普通居民與士兵作對比。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":5},{"front":"call for","meaning":"呼籲","examples":[{"en":"Several organisations have called for more comprehensive studies.","zh":"幾個組織已呼籲進行更全面研究。"},{"en":"To call for something means to publicly ask or demand that it should happen.","zh":"To call for something 指公開要求或呼籲某事應該發生。"},{"en":"Parents may call for safer school crossings after a traffic accident.","zh":"交通意外後，家長可能呼籲改善學校過路安全。"},{"en":"Health concerns can lead organisations to call for further research.","zh":"健康憂慮可以促使組織呼籲進一步研究。"},{"en":"This phrase is common in public debates and policy discussions.","zh":"這個片語常見於公共爭論和政策討論。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":5},{"front":"comprehensive epidemiological studies","meaning":"全面的流行病學研究","examples":[{"en":"More comprehensive epidemiological studies are needed.","zh":"需要更多全面的流行病學研究。"},{"en":"Comprehensive epidemiological studies are broad public-health studies that examine disease patterns in populations carefully.","zh":"Comprehensive epidemiological studies 是仔細檢視人口中疾病模式的廣泛公共衛生研究。"},{"en":"Such studies may compare exposed and unexposed groups over many years.","zh":"這類研究可能多年比較接觸群體和未接觸群體。"},{"en":"Comprehensive studies can clarify whether a substance is linked to illness.","zh":"全面研究可以澄清某物質是否與疾病有關。"},{"en":"This phrase suggests research that is wide, systematic, and evidence-based.","zh":"這個片語暗示研究廣泛、有系統並以證據為基礎。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":5},{"front":"clarify the link between","meaning":"澄清……之間的關聯","examples":[{"en":"Studies are needed to clarify the link between depleted uranium and illness.","zh":"需要研究來澄清貧鈾與疾病之間的關聯。"},{"en":"To clarify the link between two things means to make their relationship clearer.","zh":"To clarify the link between two things 指令兩者之間的關係更清楚。"},{"en":"Doctors may study patients to clarify the link between diet and headaches.","zh":"醫生可能研究病人，以澄清飲食與頭痛之間的關聯。"},{"en":"Good data can clarify whether one factor really causes another.","zh":"良好數據可以澄清一個因素是否真的造成另一個因素。"},{"en":"This phrase is useful when a possible connection is still uncertain.","zh":"當可能關聯仍不確定時，這個片語很有用。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":5},{"front":"various test-tube and animal studies","meaning":"多項試管和動物研究","examples":[{"en":"Various test-tube and animal studies have suggested possible health risks.","zh":"多項試管和動物研究顯示可能存在健康風險。"},{"en":"Various test-tube and animal studies are different laboratory and animal experiments used before or alongside human studies.","zh":"Various test-tube and animal studies 是在人類研究之前或同時進行的不同實驗室和動物實驗。"},{"en":"Test-tube studies can show effects on cells, while animal studies can show effects in living bodies.","zh":"試管研究可以顯示對細胞的影響，而動物研究可以顯示對活體的影響。"},{"en":"These studies may raise concern, but they do not always prove what happens in humans.","zh":"這些研究可能引起憂慮，但不一定證明在人類身上會發生甚麼。"},{"en":"This phrase describes early scientific evidence from multiple experiment types.","zh":"這個片語描述來自多種實驗類型的早期科學證據。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":5},{"front":"test-tube studies","meaning":"試管研究","examples":[{"en":"Test-tube studies have examined the effects of depleted uranium.","zh":"試管研究檢視了貧鈾的影響。"},{"en":"Test-tube studies are laboratory experiments done on cells, chemicals, or tissues outside a living body.","zh":"Test-tube studies 是在活體外對細胞、化學物或組織進行的實驗室實驗。"},{"en":"A test-tube study may show how a substance affects DNA in controlled conditions.","zh":"試管研究可能顯示某物質在受控條件下如何影響DNA。"},{"en":"Test-tube studies are useful, but real bodies are more complex.","zh":"試管研究有用，但真實身體更複雜。"},{"en":"This phrase refers to laboratory research, not studies on whole human populations.","zh":"這個片語指實驗室研究，而不是整個人群研究。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":6},{"front":"animal studies","meaning":"動物研究","examples":[{"en":"Animal studies have suggested that depleted uranium may increase cancer risk.","zh":"動物研究顯示貧鈾可能增加癌症風險。"},{"en":"Animal studies are experiments or observations involving animals to understand possible biological effects.","zh":"Animal studies 是涉及動物的實驗或觀察，用來理解可能的生物影響。"},{"en":"Scientists may use animal studies before testing a substance in humans.","zh":"科學家可能在人類測試某物質前使用動物研究。"},{"en":"Animal studies can warn researchers about risks, but results may not perfectly match human biology.","zh":"動物研究可以提醒研究人員注意風險，但結果未必完全符合人體生物學。"},{"en":"This phrase describes research using living animals.","zh":"這個片語描述使用活體動物的研究。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":6},{"front":"suggested that","meaning":"顯示；提出","examples":[{"en":"Some studies have suggested that depleted uranium may increase cancer risk.","zh":"一些研究顯示貧鈾可能增加癌症風險。"},{"en":"Suggested that means indicated a possibility, without necessarily proving it finally.","zh":"Suggested that 指顯示某種可能性，但不一定最終證明。"},{"en":"Early results suggested that the new timetable helped students sleep more.","zh":"早期結果顯示新時間表幫助學生睡得更多。"},{"en":"When evidence only suggests a link, researchers usually ask for more study.","zh":"當證據只顯示可能關聯，研究人員通常會要求更多研究。"},{"en":"This phrase is careful because it does not claim complete certainty.","zh":"這個片語較謹慎，因為它不聲稱完全確定。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":6},{"front":"according to a review of","meaning":"根據一篇對……的綜述","examples":[{"en":"The claim appears in a review of the scientific literature.","zh":"這項主張出現在一篇對科學文獻的綜述中。"},{"en":"According to a review of something means based on a careful summary of existing studies or information.","zh":"According to a review of something 指根據對現有研究或資料的仔細總結。"},{"en":"According to a review of school data, attendance improved after breakfast was provided.","zh":"根據一篇對學校數據的綜述，提供早餐後出席率有所改善。"},{"en":"A review can show whether many studies point in the same direction.","zh":"綜述可以顯示許多研究是否指向同一方向。"},{"en":"This phrase gives the source of a claim.","zh":"這個片語提供主張的來源。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":6},{"front":"scientific literature","meaning":"科學文獻","examples":[{"en":"The scientific literature includes studies on uranium toxicity.","zh":"科學文獻包括關於鈾毒性的研究。"},{"en":"Scientific literature means published research papers, reviews, and reports in a scientific field.","zh":"Scientific literature 指某科學領域中已發表的研究論文、綜述和報告。"},{"en":"Doctors read scientific literature to learn whether a treatment has been tested properly.","zh":"醫生閱讀科學文獻，以了解某治療是否經過妥善測試。"},{"en":"When scientific literature is mixed, experts may disagree about risk.","zh":"當科學文獻結果不一致，專家可能對風險有分歧。"},{"en":"This phrase refers to formal research, not popular news articles.","zh":"這個片語指正式研究，而不是大眾新聞文章。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":6},{"front":"published in","meaning":"發表於","examples":[{"en":"The review was published in May 2008.","zh":"這篇綜述發表於2008年5月。"},{"en":"Published in means made publicly available in a book, journal, report, or other source at a particular time or place.","zh":"Published in 指在某本書、期刊、報告或其他來源中於某時間或地方公開發表。"},{"en":"A study published in a medical journal may influence doctors’ decisions.","zh":"發表於醫學期刊的研究可能影響醫生決定。"},{"en":"The date published in a report helps readers judge how current the evidence is.","zh":"報告中的發表日期幫助讀者判斷證據有多新。"},{"en":"This phrase identifies where or when information became public.","zh":"這個片語指出資訊在哪裡或何時公開。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":6},{"front":"the US National Research Council","meaning":"美國國家研究委員會","examples":[{"en":"The US National Research Council reviewed scientific literature on depleted uranium.","zh":"美國國家研究委員會綜述了關於貧鈾的科學文獻。"},{"en":"The US National Research Council is a research body that reviews scientific evidence for policy and public understanding.","zh":"美國國家研究委員會是一個為政策和公共理解而審視科學證據的研究機構。"},{"en":"Such organisations can summarise complex studies for governments and experts.","zh":"這類組織可以為政府和專家總結複雜研究。"},{"en":"A review by a national research body may carry weight because it examines many studies.","zh":"由國家研究機構進行的綜述可能有分量，因為它檢視多項研究。"},{"en":"This phrase names an institution involved in scientific assessment.","zh":"這個片語命名一個參與科學評估的機構。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":6},{"front":"argue that","meaning":"主張；認為","examples":[{"en":"The authors argue that more research is needed.","zh":"作者主張需要更多研究。"},{"en":"To argue that something is true means to present reasons for believing it.","zh":"To argue that something is true 指提出理由支持某事是真的。"},{"en":"Teachers may argue that homework should be shorter but more focused.","zh":"老師可能主張功課應該更短但更集中。"},{"en":"Scientists argue that a theory needs testing when current evidence is incomplete.","zh":"當現有證據不完整，科學家會認為理論需要測試。"},{"en":"This phrase introduces someone’s reasoned opinion.","zh":"這個片語引出某人有理由支持的觀點。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":6},{"front":"long-term and quantitative research","meaning":"長期及量化研究","examples":[{"en":"More long-term and quantitative research is needed.","zh":"需要更多長期及量化研究。"},{"en":"Long-term and quantitative research studies a question over time and uses numbers to measure results.","zh":"Long-term and quantitative research 是長時間研究一個問題，並用數字量度結果。"},{"en":"A long-term study may follow patients for many years to see whether illness appears later.","zh":"長期研究可能多年追蹤病人，以了解疾病是否後來出現。"},{"en":"Quantitative research can compare risk by counting cases and exposure levels.","zh":"量化研究可以透過計算病例和接觸水平來比較風險。"},{"en":"This phrase suggests careful evidence rather than short opinions.","zh":"這個片語暗示仔細證據，而不是短期意見。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":6},{"front":"uranium’s chemical toxicity","meaning":"鈾的化學毒性","examples":[{"en":"Scientists want to understand uranium’s chemical toxicity.","zh":"科學家想了解鈾的化學毒性。"},{"en":"Uranium’s chemical toxicity means the harm uranium can cause because of its chemical nature, not only its radiation.","zh":"Uranium’s chemical toxicity 指鈾因其化學性質造成的傷害，而不只是其輻射。"},{"en":"Lead has chemical toxicity because it can poison the body even without being radioactive.","zh":"鉛具有化學毒性，因為即使沒有放射性，它也可以毒害身體。"},{"en":"If uranium’s chemical toxicity damages cells, weak radioactivity may not be the only concern.","zh":"如果鈾的化學毒性損害細胞，弱放射性便不是唯一憂慮。"},{"en":"This phrase separates chemical harm from radioactive harm.","zh":"這個片語把化學傷害與放射性傷害分開。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":6},{"front":"support the theory that","meaning":"支持……這一理論","examples":[{"en":"The science seems to support the theory that genetic damage may occur.","zh":"科學似乎支持可能發生基因損傷這一理論。"},{"en":"To support the theory that something is true means to provide evidence that makes the theory more believable.","zh":"To support the theory that something is true 指提供證據，使該理論更可信。"},{"en":"Test results may support the theory that poor sleep affects memory.","zh":"測試結果可能支持睡眠不足影響記憶這一理論。"},{"en":"Evidence can support a theory without proving it completely.","zh":"證據可以支持一個理論，但不一定完全證明它。"},{"en":"This phrase connects scientific findings with an explanation.","zh":"這個片語把科學發現與解釋連接起來。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":6},{"front":"weak radioactivity","meaning":"弱放射性","examples":[{"en":"Uranium’s weak radioactivity may reinforce its chemical toxicity.","zh":"鈾的弱放射性可能加強其化學毒性。"},{"en":"Weak radioactivity is a low level of radiation released by a material.","zh":"Weak radioactivity 是材料釋放的低水平輻射。"},{"en":"Weak radioactivity may seem minor, but scientists still study how it interacts with other effects.","zh":"弱放射性可能看似輕微，但科學家仍研究它如何與其他作用互動。"},{"en":"If weak radioactivity reinforces chemical toxicity, the combined harm may be greater than expected.","zh":"如果弱放射性加強化學毒性，綜合傷害可能比預期更大。"},{"en":"This phrase describes radiation level, not the whole health risk.","zh":"這個片語描述輻射水平，而不是整體健康風險。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":7},{"front":"reinforce each other","meaning":"互相加強","examples":[{"en":"Chemical toxicity and weak radioactivity could reinforce each other.","zh":"化學毒性和弱放射性可能互相加強。"},{"en":"To reinforce each other means two effects make one another stronger.","zh":"To reinforce each other 指兩種作用令彼此更強。"},{"en":"Stress and poor sleep can reinforce each other, making both problems worse.","zh":"壓力和睡眠不足可以互相加強，使兩個問題都更嚴重。"},{"en":"If two harmful processes reinforce each other, the total damage may be greater than either alone.","zh":"如果兩個有害過程互相加強，總傷害可能比任何一個單獨作用更大。"},{"en":"This phrase describes mutual strengthening.","zh":"這個片語描述相互強化。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":7},{"front":"the mechanism for this","meaning":"這種作用的機制","examples":[{"en":"No one knows the mechanism for this effect.","zh":"沒有人知道這種作用的機制。"},{"en":"The mechanism for this means the process or pathway that explains how it happens.","zh":"The mechanism for this 指解釋它如何發生的過程或途徑。"},{"en":"Doctors may know a medicine works before they fully understand the mechanism for it.","zh":"醫生可能在完全了解藥物作用機制前已知道它有效。"},{"en":"Finding the mechanism helps researchers test whether a theory is realistic.","zh":"找出機制有助研究人員測試理論是否現實。"},{"en":"This phrase asks for the “how”, not just the result.","zh":"這個片語詢問「如何發生」，而不只是結果。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":7},{"front":"have a new theory","meaning":"有一個新理論","examples":[{"en":"Two researchers have a new theory about depleted uranium.","zh":"兩名研究人員對貧鈾有一個新理論。"},{"en":"To have a new theory means to propose a new explanation for something not fully understood.","zh":"To have a new theory 指對尚未完全理解的事情提出新解釋。"},{"en":"Scientists may have a new theory when old explanations fail to fit the evidence.","zh":"當舊解釋不符合證據時，科學家可能有一個新理論。"},{"en":"A new theory must be tested before it becomes widely accepted.","zh":"新理論在被廣泛接受前必須經過測試。"},{"en":"This phrase introduces a possible explanation, not a proven fact.","zh":"這個片語引出可能解釋，而不是已證明事實。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":7},{"front":"explains how","meaning":"解釋……如何","examples":[{"en":"The theory explains how depleted uranium could cause genetic damage.","zh":"這個理論解釋貧鈾如何可能造成基因損傷。"},{"en":"Explains how means shows the process by which something happens.","zh":"Explains how 指顯示某事發生的過程。"},{"en":"A diagram explains how blood moves through the heart.","zh":"圖表解釋血液如何流經心臟。"},{"en":"A good theory explains how a cause leads to a result step by step.","zh":"好理論會一步一步解釋原因如何導致結果。"},{"en":"This phrase focuses on mechanism and process.","zh":"這個片語著重機制和過程。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":7},{"front":"invokes","meaning":"援引；引用","examples":[{"en":"Their theory invokes a well-known physical process.","zh":"他們的理論援引一個眾所周知的物理過程。"},{"en":"To invoke something means to use or refer to it as part of an explanation or argument.","zh":"To invoke something 指把某事用作解釋或論證的一部分。"},{"en":"A lawyer may invoke a law to support a client’s case.","zh":"律師可能引用法律來支持客戶案件。"},{"en":"Scientists invoke known physics when they build a new explanation for a health effect.","zh":"科學家在建立健康效應的新解釋時，會援引已知物理學。"},{"en":"This word is formal and often means “appeals to” or “uses”.","zh":"這個字較正式，常指「訴諸」或「使用」。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":7},{"front":"a well-known process","meaning":"眾所周知的過程","examples":[{"en":"The theory invokes a well-known process called the photoelectric effect.","zh":"這個理論援引一個名為光電效應的眾所周知過程。"},{"en":"A well-known process is a process that many experts already recognise and understand.","zh":"Well-known process 是許多專家已認識和理解的過程。"},{"en":"Evaporation is a well-known process in which liquid turns into gas.","zh":"蒸發是一個眾所周知的過程，液體會變成氣體。"},{"en":"Using a well-known process can make a new theory easier to test.","zh":"使用眾所周知的過程可以令新理論較容易測試。"},{"en":"This phrase suggests the process itself is established, even if its application is debated.","zh":"這個片語暗示過程本身已確立，即使其應用仍有爭議。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":7},{"front":"the photoelectric effect","meaning":"光電效應","examples":[{"en":"The photoelectric effect may help explain uranium-related genetic damage.","zh":"光電效應可能有助解釋與鈾相關的基因損傷。"},{"en":"The photoelectric effect is a physical process in which a photon transfers energy to an electron and ejects it.","zh":"光電效應是一個物理過程，光子把能量轉移給電子並把它射出。"},{"en":"Solar cells use related light-energy processes to produce electricity.","zh":"太陽能電池使用相關的光能過程來發電。"},{"en":"If the photoelectric effect occurs near DNA, ejected electrons may cause damage.","zh":"如果光電效應在DNA附近發生，被射出的電子可能造成損傷。"},{"en":"This phrase names a scientific process involving light, matter, and electrons.","zh":"這個片語命名一個涉及光、物質和電子的科學過程。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":7},{"front":"the main mechanism by which","meaning":"……的主要機制","examples":[{"en":"The photoelectric effect is the main mechanism by which certain photons are blocked.","zh":"光電效應是某些光子被阻擋的主要機制。"},{"en":"The main mechanism by which something happens is the chief process that causes it.","zh":"The main mechanism by which something happens 指造成某事的主要過程。"},{"en":"Practice is the main mechanism by which students turn rules into real skill.","zh":"練習是學生把規則變成真正技能的主要機制。"},{"en":"If scientists identify the main mechanism, they can test and model the effect more clearly.","zh":"如果科學家找出主要機制，便可以更清楚測試和建模該作用。"},{"en":"This phrase focuses on the most important causal process.","zh":"這個片語著重最重要的因果過程。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":7},{"front":"gamma photons","meaning":"伽馬光子","examples":[{"en":"Gamma photons can transfer energy to electrons.","zh":"伽馬光子可以把能量轉移給電子。"},{"en":"Gamma photons are high-energy packets of electromagnetic radiation.","zh":"Gamma photons 是高能電磁輻射的能量包。"},{"en":"Doctors and scientists handle gamma photons carefully because they can affect living tissue.","zh":"醫生和科學家小心處理伽馬光子，因為它們可能影響活體組織。"},{"en":"When gamma photons interact with atoms, they may release energetic electrons.","zh":"當伽馬光子與原子互動時，可能釋放高能電子。"},{"en":"This phrase belongs to physics and radiation science.","zh":"這個片語屬於物理和輻射科學。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":7},{"front":"energies of about","meaning":"能量約為……","examples":[{"en":"The passage refers to gamma photons with energies of about 100 keV.","zh":"文章提到能量約為100 keV的伽馬光子。"},{"en":"Energies of about a value means energy levels close to that number, not exactly always the same.","zh":"Energies of about a value 指能量水平接近該數值，而不一定完全相同。"},{"en":"A machine may produce X-rays with energies of about a certain medical range.","zh":"一部機器可能產生能量約為某醫療範圍的X射線。"},{"en":"In science, “about” allows for small variation around a measurement.","zh":"在科學中，“about” 容許測量值周圍有小幅變化。"},{"en":"This phrase is useful when precise values vary slightly.","zh":"當精確數值略有不同時，這個片語很有用。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":7},{"front":"kiloelectronvolts","meaning":"千電子伏特","examples":[{"en":"Kiloelectronvolts are used to measure the energy of photons.","zh":"千電子伏特用來量度光子的能量。"},{"en":"Kiloelectronvolts are units of energy often used in atomic, nuclear, and radiation physics.","zh":"Kiloelectronvolts 是常用於原子、核能和輻射物理的能量單位。"},{"en":"Scientists may describe X-ray energy in kiloelectronvolts rather than everyday units.","zh":"科學家可能用千電子伏特而不是日常單位描述X射線能量。"},{"en":"Using kiloelectronvolts helps compare particles and photons at very small scales.","zh":"使用千電子伏特有助比較極小尺度上的粒子和光子。"},{"en":"This word is technical, but it simply names an energy unit.","zh":"這個詞較技術性，但它只是命名一個能量單位。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":8},{"front":"blocked by matter","meaning":"被物質阻擋","examples":[{"en":"Some gamma photons are blocked by matter.","zh":"一些伽馬光子被物質阻擋。"},{"en":"Blocked by matter means stopped or absorbed when passing through a material.","zh":"Blocked by matter 指在穿過材料時被阻止或吸收。"},{"en":"Thick lead can block some radiation because its atoms interact strongly with photons.","zh":"厚鉛可以阻擋一些輻射，因為其原子與光子強烈互動。"},{"en":"If radiation is blocked by matter, less of it reaches the tissue or object behind it.","zh":"如果輻射被物質阻擋，到達後方組織或物體的輻射便較少。"},{"en":"This phrase describes how materials can stop or reduce radiation.","zh":"這個片語描述材料如何停止或減少輻射。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":8},{"front":"transfers its energy to","meaning":"將其能量轉移到……","examples":[{"en":"A photon transfers its energy to an electron.","zh":"光子將其能量轉移到電子。"},{"en":"To transfer its energy to something means to pass energy from one object or particle to another.","zh":"To transfer its energy to something 指把能量從一個物體或粒子傳給另一個。"},{"en":"Sunlight transfers energy to a solar panel and helps produce electricity.","zh":"陽光將能量轉移到太陽能板，幫助發電。"},{"en":"When a photon transfers energy to an electron, the electron may be ejected.","zh":"當光子將能量轉移到電子時，電子可能被射出。"},{"en":"This phrase describes movement of energy, not movement of the whole object.","zh":"這個片語描述能量移動，而不是整個物體移動。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":8},{"front":"an electron in the atom’s electron cloud","meaning":"原子電子雲中的電子","examples":[{"en":"The photon transfers energy to an electron in the atom’s electron cloud.","zh":"光子把能量轉移到原子電子雲中的電子。"},{"en":"An electron in the atom’s electron cloud is a tiny negatively charged particle found around the nucleus.","zh":"原子電子雲中的電子是位於原子核周圍的帶負電微小粒子。"},{"en":"In simple chemistry, electrons in the electron cloud help atoms bond with other atoms.","zh":"在簡單化學中，電子雲中的電子幫助原子與其他原子成鍵。"},{"en":"If enough energy reaches an electron in the electron cloud, it may leave the atom.","zh":"如果電子雲中的電子得到足夠能量，它可能離開原子。"},{"en":"This phrase identifies where the affected electron is located.","zh":"這個片語指出受影響電子的位置。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":8},{"front":"ejected into the surroundings","meaning":"被射出至周圍","examples":[{"en":"The electron is ejected into the surroundings.","zh":"電子被射出至周圍。"},{"en":"Ejected into the surroundings means pushed or thrown out into the nearby area.","zh":"Ejected into the surroundings 指被推出或拋到附近區域。"},{"en":"When a seed pod bursts, seeds may be ejected into the surroundings.","zh":"當種子莢爆開，種子可能被射出至周圍。"},{"en":"In radiation physics, an ejected electron can travel and hit nearby molecules.","zh":"在輻射物理中，被射出的電子可以移動並撞擊附近分子。"},{"en":"This phrase describes sudden movement away from the original location.","zh":"這個片語描述突然離開原本位置的移動。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":8},{"front":"an atom’s ability to","meaning":"原子……的能力","examples":[{"en":"An atom’s ability to stop photons depends on its atomic number.","zh":"原子阻擋光子的能力取決於其原子序數。"},{"en":"An atom’s ability to do something means what that atom can do because of its structure.","zh":"An atom’s ability to do something 指原子因其結構而能做到的事情。"},{"en":"An atom’s ability to bond with other atoms depends partly on its electrons.","zh":"原子與其他原子成鍵的能力部分取決於其電子。"},{"en":"Heavy atoms may have a greater ability to interact with certain radiation.","zh":"重原子可能有更大能力與某些輻射互動。"},{"en":"This phrase links atomic structure with behaviour.","zh":"這個片語把原子結構與行為連接起來。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":8},{"front":"stop photons","meaning":"阻擋光子","examples":[{"en":"Heavy atoms are better able to stop photons.","zh":"重原子更能阻擋光子。"},{"en":"To stop photons means to absorb, block, or intercept packets of light or radiation energy.","zh":"To stop photons 指吸收、阻擋或攔截光或輻射能量包。"},{"en":"Protective shielding is designed to stop photons before they reach sensitive tissue.","zh":"防護屏蔽被設計來在光子到達敏感組織前阻擋它們。"},{"en":"If a material stops photons effectively, it may also release secondary electrons.","zh":"如果材料有效阻擋光子，它也可能釋放次級電子。"},{"en":"This phrase describes interaction between radiation and matter.","zh":"這個片語描述輻射與物質之間的互動。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":8},{"front":"depends on","meaning":"取決於","examples":[{"en":"The effect depends on the fourth power of the atomic number.","zh":"這種作用取決於原子序數的四次方。"},{"en":"Depends on means is controlled or strongly influenced by something.","zh":"Depends on 指由某事控制或受到某事強烈影響。"},{"en":"A student’s progress depends on practice, feedback, sleep, and motivation.","zh":"學生進步取決於練習、回饋、睡眠和動機。"},{"en":"If a result depends on one key factor, changing that factor can change the result greatly.","zh":"如果結果取決於一個關鍵因素，改變該因素可以大大改變結果。"},{"en":"This phrase connects an outcome with what determines it.","zh":"這個片語把結果與決定它的因素連接起來。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":8},{"front":"the fourth power of","meaning":"……的四次方","examples":[{"en":"The mechanism depends on the fourth power of the atomic number.","zh":"這個機制取決於原子序數的四次方。"},{"en":"The fourth power of a number means the number multiplied by itself four times.","zh":"The fourth power of a number 指該數字自乘四次。"},{"en":"The fourth power of 2 is 16 because 2 × 2 × 2 × 2 = 16.","zh":"2的四次方是16，因為2 × 2 × 2 × 2 = 16。"},{"en":"If an effect depends on the fourth power, small differences in the number can produce very large differences.","zh":"如果某作用取決於四次方，數字的小差異可以產生非常大的差異。"},{"en":"This phrase is mathematical and shows strong sensitivity to a value.","zh":"這個片語屬於數學用語，顯示對某數值高度敏感。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":8},{"front":"atomic number","meaning":"原子序數","examples":[{"en":"Uranium has an atomic number of 92.","zh":"鈾的原子序數是92。"},{"en":"Atomic number is the number of protons in an atom’s nucleus.","zh":"Atomic number 是原子核中質子的數量。"},{"en":"Carbon has atomic number 6 because each carbon atom has six protons.","zh":"碳的原子序數是6，因為每個碳原子有六個質子。"},{"en":"Atomic number helps determine an element’s identity and behaviour.","zh":"原子序數有助決定元素的身份和行為。"},{"en":"This phrase is basic to chemistry and nuclear science.","zh":"這個片語是化學和核科學的基礎。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":8},{"front":"the number of protons","meaning":"質子的數量","examples":[{"en":"The atomic number is the number of protons in the nucleus.","zh":"原子序數是原子核中質子的數量。"},{"en":"The number of protons tells us which chemical element an atom is.","zh":"質子的數量告訴我們一個原子是哪種化學元素。"},{"en":"An atom with one proton is hydrogen, while an atom with six protons is carbon.","zh":"有一個質子的原子是氫，而有六個質子的原子是碳。"},{"en":"Changing the number of protons changes the element itself.","zh":"改變質子的數量會改變元素本身。"},{"en":"This phrase explains the meaning of atomic number.","zh":"這個片語解釋原子序數的意思。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":8},{"front":"in its nucleus","meaning":"在其原子核中","examples":[{"en":"Protons are found in an atom’s nucleus.","zh":"質子位於原子的原子核中。"},{"en":"In its nucleus means inside the central part of an atom.","zh":"In its nucleus 指在原子的中心部分內。"},{"en":"Most of an atom’s mass is found in its nucleus.","zh":"原子的大部分質量位於其原子核中。"},{"en":"If the number of protons in its nucleus changes, the atom becomes a different element.","zh":"如果其原子核中的質子數量改變，該原子便變成另一種元素。"},{"en":"This phrase points to the atom’s centre, not the electron cloud.","zh":"這個片語指原子中心，而不是電子雲。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":9},{"front":"heavy elements","meaning":"重元素","examples":[{"en":"Heavy elements are better at intercepting gamma radiation.","zh":"重元素更擅長攔截伽馬輻射。"},{"en":"Heavy elements are elements with large atoms and high atomic numbers.","zh":"Heavy elements 是原子較大、原子序數較高的元素。"},{"en":"Lead and uranium are heavy elements often discussed in radiation shielding.","zh":"鉛和鈾是常在輻射屏蔽中討論的重元素。"},{"en":"Heavy elements interact more strongly with some kinds of radiation than light elements do.","zh":"重元素與某些輻射的互動比輕元素更強。"},{"en":"This phrase compares elements by atomic weight and structure.","zh":"這個片語按原子重量和結構比較元素。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":9},{"front":"far better at","meaning":"更擅長；遠比……有效","examples":[{"en":"Heavy elements are far better at intercepting X-rays than light elements.","zh":"重元素攔截X射線的能力遠比輕元素有效。"},{"en":"Far better at something means much more effective or skilled at doing it.","zh":"Far better at something 指做某事有效或熟練得多。"},{"en":"A trained nurse is far better at taking blood safely than an untrained person.","zh":"受過訓練的護士比未受訓的人更擅長安全抽血。"},{"en":"If one material is far better at blocking radiation, engineers may choose it for shielding.","zh":"如果一種材料遠比另一種更能阻擋輻射，工程師可能選它作屏蔽。"},{"en":"This phrase shows a large difference in ability.","zh":"這個片語顯示能力上的巨大差異。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":9},{"front":"intercepting gamma radiation","meaning":"攔截伽馬輻射","examples":[{"en":"Uranium is effective at intercepting gamma radiation.","zh":"鈾能有效攔截伽馬輻射。"},{"en":"Intercepting gamma radiation means blocking or absorbing gamma rays before they continue travelling.","zh":"Intercepting gamma radiation 指在伽馬射線繼續前進前阻擋或吸收它們。"},{"en":"Thick shielding may be used for intercepting gamma radiation in a laboratory.","zh":"實驗室可能使用厚屏蔽來攔截伽馬輻射。"},{"en":"When a material intercepts radiation, it may also produce secondary particles.","zh":"當材料攔截輻射時，也可能產生次級粒子。"},{"en":"This phrase describes a protective or physical interaction with radiation.","zh":"這個片語描述與輻射的保護性或物理互動。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":9},{"front":"X-rays","meaning":"X 射線","examples":[{"en":"Heavy elements can intercept X-rays more effectively than light elements.","zh":"重元素比輕元素更有效攔截X射線。"},{"en":"X-rays are a form of high-energy radiation that can pass through many soft materials.","zh":"X-rays 是一種高能輻射，可以穿過許多軟材料。"},{"en":"Doctors use X-rays to see bones inside the body.","zh":"醫生使用X射線查看身體內的骨骼。"},{"en":"Because X-rays can affect cells, medical staff limit unnecessary exposure.","zh":"因為X射線可能影響細胞，醫護人員會限制不必要接觸。"},{"en":"This word is common in medicine, physics, and safety discussions.","zh":"這個詞常見於醫學、物理和安全討論。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":9},{"front":"light elements","meaning":"輕元素","examples":[{"en":"Light elements are less effective at blocking low-energy gamma photons.","zh":"輕元素阻擋低能伽馬光子的效果較弱。"},{"en":"Light elements are elements with smaller atoms and lower atomic numbers.","zh":"Light elements 是原子較小、原子序數較低的元素。"},{"en":"Hydrogen, carbon, and oxygen are examples of light elements common in living tissue.","zh":"氫、碳和氧是活體組織中常見的輕元素例子。"},{"en":"Light elements may interact less strongly with certain photons than heavy elements do.","zh":"輕元素與某些光子的互動可能比重元素弱。"},{"en":"This phrase contrasts with heavy elements such as uranium.","zh":"這個片語與鈾等重元素形成對比。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":9},{"front":"especially effective at","meaning":"尤其有效於","examples":[{"en":"Uranium could be especially effective at capturing photons.","zh":"鈾可能尤其有效於捕捉光子。"},{"en":"Especially effective at something means particularly good at doing it.","zh":"Especially effective at something 指特別擅長或有效地做某事。"},{"en":"A clear diagram is especially effective at explaining a difficult process.","zh":"清晰圖表尤其有效於解釋困難過程。"},{"en":"A heavy element may be especially effective at blocking certain types of radiation.","zh":"重元素可能尤其有效於阻擋某些類型的輻射。"},{"en":"This phrase highlights a strong ability in a specific situation.","zh":"這個片語突顯某特定情況下的強大能力。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":9},{"front":"capturing photons","meaning":"捕捉光子","examples":[{"en":"Uranium may be effective at capturing photons.","zh":"鈾可能有效捕捉光子。"},{"en":"Capturing photons means absorbing or intercepting packets of light or radiation energy.","zh":"Capturing photons 指吸收或攔截光或輻射能量包。"},{"en":"Solar panels work by capturing photons from sunlight.","zh":"太陽能板透過捕捉陽光中的光子運作。"},{"en":"If uranium captures photons in tissue, it may release electrons nearby.","zh":"如果鈾在組織中捕捉光子，可能在附近釋放電子。"},{"en":"This phrase describes how matter receives energy from radiation.","zh":"這個片語描述物質如何從輻射接收能量。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":9},{"front":"damaging photoelectrons","meaning":"具破壞性的光電子","examples":[{"en":"Uranium may kick out damaging photoelectrons.","zh":"鈾可能擊出具破壞性的光電子。"},{"en":"Damaging photoelectrons are electrons released by light or radiation that may harm nearby molecules.","zh":"Damaging photoelectrons 是由光或輻射釋放、可能傷害附近分子的電子。"},{"en":"If damaging photoelectrons are produced near DNA, they may break chemical bonds.","zh":"如果具破壞性的光電子在DNA附近產生，可能打斷化學鍵。"},{"en":"The danger depends on where the photoelectrons are emitted and how much energy they carry.","zh":"危險取決於光電子在哪裡被釋放，以及帶有多少能量。"},{"en":"This phrase links a physics process with possible biological harm.","zh":"這個片語把物理過程與可能的生物傷害連接起來。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":9},{"front":"over 450 times as effectively as","meaning":"效率是……的 450 多倍","examples":[{"en":"Uranium blocks low-energy photons over 450 times as effectively as calcium.","zh":"鈾阻擋低能光子的效率是鈣的450多倍。"},{"en":"Over 450 times as effectively as means more than 450 times better at producing the same effect.","zh":"Over 450 times as effectively as 指產生同一效果的能力比另一物高450多倍。"},{"en":"If one filter cleans water 10 times as effectively as another, it removes much more dirt.","zh":"如果一個濾水器清潔水的效率是另一個的10倍，它就能去除更多污垢。"},{"en":"A difference of over 450 times suggests a very large contrast in performance.","zh":"450多倍的差異暗示表現上有非常大的對比。"},{"en":"This phrase is used for strong numerical comparison.","zh":"這個片語用於強烈數字比較。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":9},{"front":"low-energy gamma photons","meaning":"低能伽馬光子","examples":[{"en":"Uranium can block low-energy gamma photons.","zh":"鈾可以阻擋低能伽馬光子。"},{"en":"Low-energy gamma photons are gamma radiation particles with relatively lower energy than other gamma photons.","zh":"Low-energy gamma photons 是能量相對其他伽馬光子較低的伽馬輻射粒子。"},{"en":"Some materials interact more strongly with low-energy gamma photons than with higher-energy ones.","zh":"某些材料與低能伽馬光子的互動可能比與較高能光子更強。"},{"en":"If low-energy gamma photons are captured near uranium, electrons may be released nearby.","zh":"如果低能伽馬光子在鈾附近被捕捉，電子可能在附近被釋放。"},{"en":"This phrase specifies the type of radiation being discussed.","zh":"這個片語指明正在討論的輻射類型。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":9},{"front":"for instance","meaning":"例如","examples":[{"en":"Calcium is given as an example, for instance.","zh":"例如，鈣被作為例子提出。"},{"en":"For instance means for example.","zh":"For instance 意思是例如。"},{"en":"Some foods are high in calcium; milk and tofu, for instance, are common examples.","zh":"有些食物含鈣高；例如，牛奶和豆腐是常見例子。"},{"en":"Writers use “for instance” to make an idea clearer with a specific case.","zh":"作者使用 “for instance” 以具體例子令想法更清楚。"},{"en":"This phrase introduces an example that supports the point.","zh":"這個片語引出支持重點的例子。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":10},{"front":"previous risk models","meaning":"以往的風險模型","examples":[{"en":"Previous risk models may have ignored the photoelectric effect.","zh":"以往的風險模型可能忽略了光電效應。"},{"en":"Previous risk models are earlier systems or calculations used to estimate danger.","zh":"Previous risk models 是早前用來估計危險的系統或計算方法。"},{"en":"A previous risk model for flooding may ignore new building projects near a river.","zh":"以往的水浸風險模型可能忽略河流附近的新建築項目。"},{"en":"If previous risk models miss an important mechanism, they may underestimate harm.","zh":"如果以往風險模型漏掉重要機制，它們可能低估傷害。"},{"en":"This phrase compares old methods with newer explanations.","zh":"這個片語比較舊方法與較新的解釋。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":10},{"front":"ignored","meaning":"忽略了","examples":[{"en":"The researchers say earlier models ignored this physical effect.","zh":"研究人員說早期模型忽略了這種物理效應。"},{"en":"Ignored means did not notice, include, or pay attention to something.","zh":"Ignored 指沒有注意、包括或重視某事。"},{"en":"A school plan may fail if it ignores students’ travel time.","zh":"如果學校計劃忽略學生交通時間，可能會失敗。"},{"en":"If researchers ignore an important variable, their conclusion may be incomplete.","zh":"如果研究人員忽略重要變量，他們的結論可能不完整。"},{"en":"This word often suggests a missing factor.","zh":"這個詞常暗示有缺失因素。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":10},{"front":"well-established physical effect","meaning":"早已確立的物理效應","examples":[{"en":"The photoelectric effect is a well-established physical effect.","zh":"光電效應是早已確立的物理效應。"},{"en":"A well-established physical effect is a scientific effect that has been known and tested for a long time.","zh":"Well-established physical effect 是已知並經長期測試的科學效應。"},{"en":"Gravity is a well-established physical effect because it has been observed repeatedly.","zh":"重力是早已確立的物理效應，因為它被反覆觀察。"},{"en":"Using a well-established effect can strengthen a new theory, but the theory still needs testing.","zh":"使用早已確立的效應可以加強新理論，但該理論仍需要測試。"},{"en":"This phrase distinguishes known physics from speculative claims.","zh":"這個片語把已知物理與推測性主張區分開來。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":10},{"front":"vulnerable spots","meaning":"脆弱部位","examples":[{"en":"Depleted uranium may release photoelectrons in the body’s vulnerable spots.","zh":"貧鈾可能在身體的脆弱部位釋放光電子。"},{"en":"Vulnerable spots are places that are easily harmed or especially sensitive.","zh":"Vulnerable spots 是容易受傷害或特別敏感的位置。"},{"en":"In a building, weak walls and old wiring can be vulnerable spots during a storm.","zh":"在建築中，脆弱牆壁和老舊電線可能是風暴中的脆弱部位。"},{"en":"If harmful particles are released in vulnerable spots, damage may be greater.","zh":"如果有害粒子在脆弱部位被釋放，損害可能更大。"},{"en":"This phrase identifies areas where protection is weakest or risk is highest.","zh":"這個片語指出保護最弱或風險最高的地方。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":10},{"front":"dissolved uranium","meaning":"溶解了的鈾","examples":[{"en":"Dissolved uranium may attach to DNA strands.","zh":"溶解了的鈾可能附着於DNA鏈。"},{"en":"Dissolved uranium is uranium that has entered a liquid or solution rather than remaining as a solid piece.","zh":"Dissolved uranium 是進入液體或溶液中的鈾，而不是保持固體碎片。"},{"en":"Minerals dissolved in water can travel through soil and into plants.","zh":"溶解在水中的礦物可以穿過土壤並進入植物。"},{"en":"If uranium is dissolved in body fluids, it may move to sensitive tissues.","zh":"如果鈾溶解在體液中，它可能移動到敏感組織。"},{"en":"This phrase describes uranium in a form that can mix and move more easily.","zh":"這個片語描述一種更容易混合和移動的鈾形式。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":10},{"front":"ingested in food or water","meaning":"透過食物或水攝入","examples":[{"en":"Uranium may be ingested in food or water.","zh":"鈾可能透過食物或水攝入。"},{"en":"Ingested in food or water means taken into the body by eating or drinking.","zh":"Ingested in food or water 指透過進食或飲水進入身體。"},{"en":"People may ingest bacteria in food or water if hygiene is poor.","zh":"如果衛生差，人們可能透過食物或水攝入細菌。"},{"en":"If contaminants are ingested in food or water, they may reach the digestive system and bloodstream.","zh":"如果污染物透過食物或水攝入，可能到達消化系統和血液。"},{"en":"This phrase describes one route of exposure.","zh":"這個片語描述一種接觸途徑。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":10},{"front":"is liable to","meaning":"很可能會","examples":[{"en":"Dissolved uranium is liable to attach to DNA.","zh":"溶解了的鈾很可能會附着於DNA。"},{"en":"Is liable to means is likely to do something, often something unwanted.","zh":"Is liable to 指很可能做某事，通常是不想要的事。"},{"en":"A tired driver is liable to make mistakes on a long journey.","zh":"疲倦司機在長途旅程中很可能犯錯。"},{"en":"A dissolved metal may be liable to bind with molecules inside the body.","zh":"溶解了的金屬可能很容易與體內分子結合。"},{"en":"This phrase suggests a tendency or risk.","zh":"這個片語暗示傾向或風險。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":10},{"front":"attach to","meaning":"附着於","examples":[{"en":"Uranium can attach to DNA strands within cells.","zh":"鈾可以附着於細胞內的DNA鏈。"},{"en":"To attach to something means to stick, join, or bind to it.","zh":"To attach to something 指黏附、連接或結合到某物上。"},{"en":"A label can attach to a bottle if the surface is clean and dry.","zh":"如果瓶身表面乾淨乾爽，標籤可以附着於瓶子。"},{"en":"If a toxic metal attaches to DNA, it may affect genetic material directly.","zh":"如果有毒金屬附着於DNA，它可能直接影響遺傳物質。"},{"en":"This phrase describes physical or chemical connection.","zh":"這個片語描述物理或化學連接。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":10},{"front":"DNA strands","meaning":"DNA 鏈","examples":[{"en":"Dissolved uranium may attach to DNA strands.","zh":"溶解了的鈾可能附着於DNA鏈。"},{"en":"DNA strands are long chains of genetic material that carry instructions for living cells.","zh":"DNA strands 是攜帶活細胞指令的長鏈遺傳物質。"},{"en":"A cell uses DNA strands like an instruction manual for making proteins.","zh":"細胞把DNA鏈像製造蛋白質的說明書一樣使用。"},{"en":"Damage to DNA strands can affect how cells grow, repair, or divide.","zh":"DNA鏈受損可能影響細胞如何生長、修復或分裂。"},{"en":"This phrase refers to the structure that carries genetic information.","zh":"這個片語指攜帶遺傳資訊的結構。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":10},{"front":"within cells","meaning":"在細胞內","examples":[{"en":"Uranium may bind to DNA strands within cells.","zh":"鈾可能與細胞內的DNA鏈結合。"},{"en":"Within cells means inside the tiny living units that make up the body.","zh":"Within cells 指在構成身體的微小活體單位內。"},{"en":"Many important chemical reactions happen within cells every second.","zh":"每秒都有許多重要化學反應在細胞內發生。"},{"en":"If harmful substances reach within cells, they may interact with DNA or proteins.","zh":"如果有害物質進入細胞內，可能與DNA或蛋白質互動。"},{"en":"This phrase locates a process inside living cells.","zh":"這個片語把過程定位於活細胞內。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":10},{"front":"binds strongly to","meaning":"與……牢固結合","examples":[{"en":"Uranium binds strongly to DNA phosphate.","zh":"鈾與DNA磷酸基牢固結合。"},{"en":"Binds strongly to something means attaches tightly and is not easily separated.","zh":"Binds strongly to something 指緊密附着，不容易分離。"},{"en":"Some medicines bind strongly to proteins in the blood.","zh":"有些藥物會與血液中的蛋白質牢固結合。"},{"en":"If a metal binds strongly to DNA, it may remain close to genetic material.","zh":"如果金屬與DNA牢固結合，它可能保持在遺傳物質附近。"},{"en":"This phrase describes a firm chemical connection.","zh":"這個片語描述牢固化學連接。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":11},{"front":"DNA phosphate","meaning":"DNA 磷酸基","examples":[{"en":"Uranium binds strongly to DNA phosphate.","zh":"鈾與DNA磷酸基牢固結合。"},{"en":"DNA phosphate refers to phosphate groups that form part of the backbone of DNA.","zh":"DNA phosphate 指形成DNA骨架一部分的磷酸基。"},{"en":"The phosphate backbone helps hold the DNA strand together.","zh":"磷酸骨架幫助把DNA鏈連在一起。"},{"en":"If a substance binds to DNA phosphate, it may sit very close to genetic material.","zh":"如果某物質與DNA磷酸基結合，它可能非常接近遺傳物質。"},{"en":"This phrase names a chemical part of DNA.","zh":"這個片語命名DNA的一個化學部分。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":11},{"front":"are therefore likely to","meaning":"因此很可能會","examples":[{"en":"Photoelectrons are therefore likely to be emitted near genetic material.","zh":"因此，光電子很可能會在遺傳物質附近被釋放。"},{"en":"Are therefore likely to means are probably going to happen because of the reason just given.","zh":"Are therefore likely to 指因剛才提出的原因而很可能發生。"},{"en":"If roads are flooded, buses are therefore likely to be delayed.","zh":"如果道路水浸，巴士因此很可能會延誤。"},{"en":"If uranium binds near DNA, emitted electrons are therefore likely to affect genetic material.","zh":"如果鈾在DNA附近結合，被釋放的電子因此很可能影響遺傳物質。"},{"en":"This phrase connects a reason with a probable result.","zh":"這個片語把原因與可能結果連接起來。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":11},{"front":"be emitted","meaning":"被釋放","examples":[{"en":"Photoelectrons may be emitted where they cause most damage.","zh":"光電子可能在造成最大傷害的位置被釋放。"},{"en":"To be emitted means to be released or sent out.","zh":"To be emitted 指被釋放或發出。"},{"en":"Smoke may be emitted from a factory chimney.","zh":"煙霧可能從工廠煙囪被釋放。"},{"en":"If electrons are emitted near DNA, scientists may worry about cell damage.","zh":"如果電子在DNA附近被釋放，科學家可能擔心細胞損傷。"},{"en":"This phrase is common in science when energy, particles, or gases are released.","zh":"當能量、粒子或氣體被釋放時，這個片語常見於科學語境。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":11},{"front":"precisely where","meaning":"正正在……的地方","examples":[{"en":"The electrons may be emitted precisely where they can cause damage.","zh":"電子可能正正在能造成損害的地方被釋放。"},{"en":"Precisely where means exactly in the place where something happens or matters.","zh":"Precisely where 指正正在某事發生或重要的位置。"},{"en":"A leak must be repaired precisely where the pipe is cracked.","zh":"漏水必須正正在水管裂開的地方維修。"},{"en":"Damage becomes more serious if harmful particles appear precisely where DNA is exposed.","zh":"如果有害粒子正正在DNA暴露的地方出現，損害會更嚴重。"},{"en":"This phrase stresses exact location.","zh":"這個片語強調精確位置。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":11},{"front":"cause most damage to","meaning":"對……造成最大破壞","examples":[{"en":"Photoelectrons may cause most damage to genetic material.","zh":"光電子可能對遺傳物質造成最大破壞。"},{"en":"To cause most damage to something means to harm that thing more than other things.","zh":"To cause most damage to something 指對某物造成比其他物更大的傷害。"},{"en":"Floodwater may cause most damage to homes built in low-lying areas.","zh":"洪水可能對建於低窪地區的房屋造成最大破壞。"},{"en":"Radiation near DNA may cause most damage to genetic material because it can affect cell instructions.","zh":"DNA附近的輻射可能對遺傳物質造成最大破壞，因為它可以影響細胞指令。"},{"en":"This phrase identifies the main target of harm.","zh":"這個片語指出主要受害目標。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":11},{"front":"genetic material","meaning":"遺傳物質","examples":[{"en":"DNA is a form of genetic material.","zh":"DNA是一種遺傳物質。"},{"en":"Genetic material is the biological information that controls growth, repair, and inherited traits.","zh":"Genetic material 是控制生長、修復和遺傳特徵的生物資訊。"},{"en":"Cells use genetic material to make proteins and copy themselves.","zh":"細胞使用遺傳物質製造蛋白質並複製自己。"},{"en":"If genetic material is damaged, the cell may repair it, die, or divide incorrectly.","zh":"如果遺傳物質受損，細胞可能修復它、死亡或錯誤分裂。"},{"en":"This phrase includes DNA and related biological information.","zh":"這個片語包括DNA和相關生物資訊。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":11},{"front":"base their claim on","meaning":"把主張建基於","examples":[{"en":"The researchers base their claim on calculations.","zh":"研究人員把主張建基於計算。"},{"en":"To base a claim on something means to support it with that evidence or reasoning.","zh":"To base a claim on something 指用該證據或推理支持某主張。"},{"en":"A teacher should base feedback on the student’s actual writing, not personal preference.","zh":"老師應把回饋建基於學生的實際寫作，而不是個人喜好。"},{"en":"Scientists may base a claim on experiments, observations, or mathematical models.","zh":"科學家可能把主張建基於實驗、觀察或數學模型。"},{"en":"This phrase shows what supports an argument.","zh":"這個片語顯示論點由甚麼支持。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":11},{"front":"calculations of","meaning":"對……的計算","examples":[{"en":"The claim is based on calculations of photoelectrons.","zh":"這項主張建基於對光電子的計算。"},{"en":"Calculations of something are mathematical estimates or measurements about it.","zh":"Calculations of something 是關於某事的數學估算或量度。"},{"en":"Engineers use calculations of bridge weight before construction begins.","zh":"工程師在施工開始前使用對橋樑重量的計算。"},{"en":"Calculations of radiation dose help scientists judge possible risk.","zh":"對輻射劑量的計算幫助科學家判斷可能風險。"},{"en":"This phrase shows that numbers are being used to support a conclusion.","zh":"這個片語顯示數字被用來支持結論。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":11},{"front":"would be produced by","meaning":"會由……產生","examples":[{"en":"Photoelectrons would be produced by the interaction.","zh":"光電子會由這種相互作用產生。"},{"en":"Would be produced by means would be created as a result of a particular process.","zh":"Would be produced by 指會由某個特定過程造成或產生。"},{"en":"Steam would be produced by heating water in a closed system.","zh":"在封閉系統中加熱水會產生蒸汽。"},{"en":"If radiation interacts with uranium, photoelectrons would be produced by that interaction.","zh":"如果輻射與鈾互動，光電子會由該相互作用產生。"},{"en":"This phrase connects a product with the process that creates it.","zh":"這個片語把產物與產生它的過程連接起來。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":11},{"front":"the interaction between","meaning":"……之間的相互作用","examples":[{"en":"The model studies the interaction between gamma radiation and uranium.","zh":"這個模型研究伽馬輻射與鈾之間的相互作用。"},{"en":"The interaction between two things is the way they affect each other.","zh":"The interaction between two things 指兩者如何互相影響。"},{"en":"Doctors study the interaction between medicines before prescribing them together.","zh":"醫生在同時處方藥物前會研究藥物之間的相互作用。"},{"en":"The interaction between radiation and matter can create secondary particles.","zh":"輻射與物質之間的相互作用可以產生次級粒子。"},{"en":"This phrase focuses on mutual influence, not isolated action.","zh":"這個片語著重相互影響，而不是孤立行動。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":11},{"front":"normal background levels","meaning":"正常背景水平","examples":[{"en":"The calculations use normal background levels of gamma radiation.","zh":"這些計算使用正常背景水平的伽馬輻射。"},{"en":"Normal background levels are the usual low levels of something present in the environment.","zh":"Normal background levels 是環境中通常存在的某物低水平。"},{"en":"Normal background noise in a classroom may include fans, chairs, and quiet talking.","zh":"課室中的正常背景噪音可能包括風扇、椅子和輕聲說話。"},{"en":"If a harmful effect occurs even at normal background levels, scientists may take it seriously.","zh":"如果有害作用即使在正常背景水平下也發生，科學家可能會認真看待。"},{"en":"This phrase gives a baseline for comparison.","zh":"這個片語提供比較基準。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":12},{"front":"gamma radiation","meaning":"伽馬輻射","examples":[{"en":"Background gamma radiation may interact with uranium in the body.","zh":"背景伽馬輻射可能與體內鈾互動。"},{"en":"Gamma radiation is a high-energy form of radiation that can pass through many materials.","zh":"Gamma radiation 是一種高能輻射，可以穿過許多材料。"},{"en":"Scientists measure gamma radiation when checking radioactive contamination.","zh":"科學家在檢查放射性污染時會量度伽馬輻射。"},{"en":"If gamma radiation interacts with heavy atoms, electrons may be released.","zh":"如果伽馬輻射與重原子互動，電子可能被釋放。"},{"en":"This phrase is important in nuclear physics and radiation safety.","zh":"這個片語在核物理和輻射安全中很重要。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":12},{"front":"detailed calculations","meaning":"詳細計算","examples":[{"en":"Detailed calculations indicate a strong photoelectron effect.","zh":"詳細計算顯示強烈的光電子效應。"},{"en":"Detailed calculations are careful numerical workings that include important factors and steps.","zh":"Detailed calculations 是包含重要因素和步驟的仔細數字運算。"},{"en":"Engineers use detailed calculations before approving a bridge design.","zh":"工程師在批准橋樑設計前使用詳細計算。"},{"en":"Detailed calculations can reveal risks that rough estimates miss.","zh":"詳細計算可以揭示粗略估算漏掉的風險。"},{"en":"This phrase suggests careful mathematical support.","zh":"這個片語暗示仔細的數學支持。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":12},{"front":"indicate that","meaning":"顯示","examples":[{"en":"Their calculations indicate that photoelectrons may be the main effect.","zh":"他們的計算顯示光電子可能是主要作用。"},{"en":"Indicate that means show, suggest, or point toward a conclusion.","zh":"Indicate that 指顯示、暗示或指向某個結論。"},{"en":"Dark clouds indicate that rain may be coming.","zh":"烏雲顯示可能快要下雨。"},{"en":"Test results may indicate that a treatment is helping, even before doctors are fully certain.","zh":"測試結果可能顯示治療正在起作用，即使醫生尚未完全確定。"},{"en":"This phrase is careful because it suggests evidence rather than absolute proof.","zh":"這個片語較謹慎，因為它暗示證據而不是絕對證明。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":12},{"front":"phantom photoelectrons","meaning":"幻影光電子","examples":[{"en":"The researchers describe phantom photoelectrons as a major effect.","zh":"研究人員把幻影光電子描述為一項主要作用。"},{"en":"Phantom photoelectrons are proposed photoelectrons that may be important but were not fully included in earlier risk models.","zh":"Phantom photoelectrons 是被提出可能重要，但早期風險模型未充分納入的光電子。"},{"en":"A “phantom” factor is something hidden or overlooked that may still affect the result.","zh":"“Phantom” 因素是隱藏或被忽略，但仍可能影響結果的因素。"},{"en":"If phantom photoelectrons exist in the way proposed, they could change risk estimates.","zh":"如果幻影光電子按理論所說存在，它們可能改變風險估算。"},{"en":"This phrase names a debated mechanism in the theory.","zh":"這個片語命名該理論中的一個受爭議機制。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":12},{"front":"the predominant effect","meaning":"主要作用","examples":[{"en":"They claim that photoelectrons are the predominant effect.","zh":"他們聲稱光電子是主要作用。"},{"en":"The predominant effect is the strongest or most important effect among several.","zh":"Predominant effect 是多種作用中最強或最重要的一種。"},{"en":"In a noisy classroom, the predominant effect on learning may be loss of concentration.","zh":"在嘈雜課室中，對學習的主要作用可能是專注力下降。"},{"en":"If photoelectrons are the predominant effect, older models may have missed the main risk.","zh":"如果光電子是主要作用，舊模型可能漏掉主要風險。"},{"en":"This phrase identifies what matters most.","zh":"這個片語指出最重要的因素。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":12},{"front":"by far","meaning":"遠遠；明顯地","examples":[{"en":"The researchers claim that the photoelectron effect is predominant by far.","zh":"研究人員聲稱光電子效應遠遠是主要作用。"},{"en":"By far means clearly and much more than anything else.","zh":"By far 指明顯地、遠遠超過其他事物。"},{"en":"This is by far the hardest question in the test.","zh":"這明顯是測驗中最難的一題。"},{"en":"If one mechanism is by far the strongest, it should receive most attention.","zh":"如果一個機制遠遠最強，就應得到最多注意。"},{"en":"This phrase strongly emphasises a large difference.","zh":"這個片語強烈強調巨大差異。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":12},{"front":"uranium genotoxicity","meaning":"鈾的基因毒性","examples":[{"en":"The theory concerns uranium genotoxicity.","zh":"這個理論關乎鈾的基因毒性。"},{"en":"Uranium genotoxicity means the ability of uranium to damage genetic material such as DNA.","zh":"Uranium genotoxicity 指鈾損害DNA等遺傳物質的能力。"},{"en":"Scientists study genotoxicity to see whether a substance might increase cancer risk.","zh":"科學家研究基因毒性，以了解某物質是否可能增加癌症風險。"},{"en":"If uranium genotoxicity is stronger than expected, safety rules may need review.","zh":"如果鈾的基因毒性比預期更強，安全規則可能需要檢討。"},{"en":"This phrase combines uranium chemistry with genetic damage.","zh":"這個片語把鈾的化學性質與基因損傷結合起來。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":12},{"front":"as powerful an emitter of…as…","meaning":"作為……發射體的能力是……的……倍","examples":[{"en":"Uranium could be 1,500 times as powerful an emitter of photoelectrons as it is an alpha emitter.","zh":"鈾作為光電子發射體的能力，可能是其作為α粒子發射體能力的1500倍。"},{"en":"“As powerful an emitter of A as B” compares how strongly something emits two different things.","zh":"“As powerful an emitter of A as B” 用來比較某物發射兩種不同東西的強度。"},{"en":"A lamp may be twice as powerful an emitter of heat as it is of visible light.","zh":"一盞燈作為熱量發射體的能力，可能是其作為可見光發射體能力的兩倍。"},{"en":"If uranium emits photoelectrons much more strongly than alpha particles, risk models may change.","zh":"如果鈾發射光電子遠強於發射α粒子，風險模型可能改變。"},{"en":"This structure is used for precise comparison of output or effect.","zh":"這個結構用於精確比較輸出或作用。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":12},{"front":"alpha emitter","meaning":"α 粒子發射體","examples":[{"en":"Uranium is also an alpha emitter.","zh":"鈾也是α粒子發射體。"},{"en":"An alpha emitter is a radioactive material that releases alpha particles.","zh":"Alpha emitter 是會釋放α粒子的放射性材料。"},{"en":"Some alpha emitters are dangerous if inhaled or swallowed because particles are released inside the body.","zh":"有些α粒子發射體如果被吸入或吞下會很危險，因為粒子會在體內釋放。"},{"en":"If uranium acts as both an alpha emitter and a photoelectron emitter, scientists must compare both effects.","zh":"如果鈾既是α粒子發射體，又是光電子發射體，科學家必須比較兩種作用。"},{"en":"This phrase describes a type of radioactive behaviour.","zh":"這個片語描述一種放射性行為。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":12},{"front":"computer modelling results","meaning":"電腦建模結果","examples":[{"en":"The researchers’ computer modelling results are described in a paper.","zh":"研究人員的電腦建模結果描述於一篇論文中。"},{"en":"Computer modelling results are findings produced by using computer simulations or calculations.","zh":"Computer modelling results 是使用電腦模擬或計算產生的發現。"},{"en":"Weather forecasts depend on computer modelling results from huge amounts of data.","zh":"天氣預報依賴大量數據產生的電腦建模結果。"},{"en":"Computer modelling results can suggest what may happen before experiments are done.","zh":"電腦建模結果可以在實驗進行前提示可能發生甚麼。"},{"en":"This phrase refers to results from models, not direct observation alone.","zh":"這個片語指模型結果，而不只是直接觀察。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":12},{"front":"described in","meaning":"描述於","examples":[{"en":"The results are described in a peer-reviewed paper.","zh":"這些結果描述於一篇經同行評審的論文中。"},{"en":"Described in means explained or presented inside a particular document or source.","zh":"Described in 指在某份文件或來源中被解釋或呈現。"},{"en":"The school rules are described in the student handbook.","zh":"學校規則描述於學生手冊中。"},{"en":"If a method is described in a paper, other researchers can examine it.","zh":"如果方法描述於論文中，其他研究人員便可以檢視它。"},{"en":"This phrase identifies where information is explained.","zh":"這個片語指出資訊在哪裡被解釋。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":13},{"front":"peer-reviewed paper","meaning":"經同行評審的論文","examples":[{"en":"The computer modelling results appear in a peer-reviewed paper.","zh":"電腦建模結果出現在一篇經同行評審的論文中。"},{"en":"A peer-reviewed paper is a research article checked by other experts before publication.","zh":"Peer-reviewed paper 是在發表前由其他專家審查的研究文章。"},{"en":"Peer review can improve a paper by finding errors or weak arguments.","zh":"同行評審可以透過找出錯誤或薄弱論點改善論文。"},{"en":"A peer-reviewed paper is usually more reliable than an unchecked online claim.","zh":"經同行評審的論文通常比未經審查的網上主張更可靠。"},{"en":"This phrase signals formal academic evaluation.","zh":"這個片語標示正式學術評估。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":13},{"front":"to be published this month","meaning":"將於本月發表","examples":[{"en":"The paper is to be published this month.","zh":"這篇論文將於本月發表。"},{"en":"To be published this month means scheduled to become publicly available during the current month.","zh":"To be published this month 指預定在本月公開發表。"},{"en":"A report to be published this month may affect next month’s policy debate.","zh":"將於本月發表的報告可能影響下月的政策辯論。"},{"en":"If a paper is not yet published, readers may have to wait to examine the full evidence.","zh":"如果論文尚未發表，讀者可能要等待才能檢視完整證據。"},{"en":"This phrase points to a planned publication date.","zh":"這個片語指向計劃中的發表日期。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":13},{"front":"fertiliser-derived uranium","meaning":"源自化肥的鈾","examples":[{"en":"The book discusses fertiliser-derived uranium.","zh":"這本書討論源自化肥的鈾。"},{"en":"Fertiliser-derived uranium is uranium that comes from or is associated with fertilisers.","zh":"Fertiliser-derived uranium 是來自或與化肥相關的鈾。"},{"en":"Some fertilisers may contain trace metals depending on the minerals used to make them.","zh":"某些化肥可能因製造所用礦物而含有微量金屬。"},{"en":"If uranium is fertiliser-derived, it may enter soil through agricultural use.","zh":"如果鈾源自化肥，它可能透過農業使用進入土壤。"},{"en":"This phrase identifies the source of the uranium.","zh":"這個片語指出鈾的來源。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":13},{"front":"chairs the committee on","meaning":"主持……委員會","examples":[{"en":"Hans-Georg Menzel chairs a committee on radiation doses.","zh":"Hans-Georg Menzel主持一個關於輻射劑量的委員會。"},{"en":"To chair a committee on something means to lead a group that studies or manages that topic.","zh":"To chair a committee on something 指領導一個研究或管理該議題的小組。"},{"en":"A teacher may chair a committee on school safety.","zh":"老師可能主持學校安全委員會。"},{"en":"The chair guides discussion, organises meetings, and helps the group reach decisions.","zh":"主席引導討論、組織會議，並幫助小組作出決定。"},{"en":"This phrase describes leadership of a formal group.","zh":"這個片語描述正式小組的領導工作。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":13},{"front":"radiation doses","meaning":"輻射劑量","examples":[{"en":"The committee studies radiation doses.","zh":"該委員會研究輻射劑量。"},{"en":"Radiation doses are measured amounts of radiation received by a person, object, or tissue.","zh":"Radiation doses 是人、物體或組織接受到的輻射量。"},{"en":"Doctors control radiation doses during X-ray scans to reduce unnecessary exposure.","zh":"醫生在X光檢查中控制輻射劑量，以減少不必要接觸。"},{"en":"Higher radiation doses may increase health risks, depending on type and duration.","zh":"較高輻射劑量可能增加健康風險，視乎類型和時間長短。"},{"en":"This phrase is central to radiation safety.","zh":"這個片語是輻射安全的核心概念。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":13},{"front":"acknowledges that","meaning":"承認","examples":[{"en":"Menzel acknowledges that the theory should be considered.","zh":"Menzel承認該理論應被考慮。"},{"en":"Acknowledges that means admits or accepts that something may be true or important.","zh":"Acknowledges that 指承認或接受某事可能是真的或重要。"},{"en":"A manager may acknowledge that staff are under pressure even while disagreeing with their solution.","zh":"經理可能承認員工受壓，即使不同意他們的解決方案。"},{"en":"A scientist can acknowledge a theory without fully supporting it.","zh":"科學家可以承認某理論值得注意，但不完全支持它。"},{"en":"This phrase often shows cautious recognition.","zh":"這個片語常顯示謹慎承認。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":13},{"front":"should be considered","meaning":"應被考慮","examples":[{"en":"The theory should be considered, according to Menzel.","zh":"根據Menzel的說法，該理論應被考慮。"},{"en":"Should be considered means should be thought about seriously, not ignored.","zh":"Should be considered 指應被認真思考，而不是被忽略。"},{"en":"A student’s family situation should be considered before blaming them for lateness.","zh":"在責怪學生遲到前，應考慮其家庭情況。"},{"en":"If a theory could explain a risk, it should be considered even if it is not proven.","zh":"如果一個理論可能解釋風險，即使未被證明，也應被考慮。"},{"en":"This phrase calls for attention without claiming certainty.","zh":"這個片語要求關注，但不聲稱確定。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":13},{"front":"doubts that","meaning":"懷疑","examples":[{"en":"Menzel doubts that the effect will prove significant.","zh":"Menzel懷疑該作用會證明具有重要性。"},{"en":"Doubts that means does not feel sure or is sceptical that something is true.","zh":"Doubts that 指不確定或懷疑某事是真的。"},{"en":"A teacher may doubt that extra homework alone will solve weak writing.","zh":"老師可能懷疑單靠額外功課能否解決寫作薄弱。"},{"en":"Scientists may doubt a theory if calculations seem incomplete.","zh":"如果計算看似不完整，科學家可能懷疑一個理論。"},{"en":"This phrase expresses scepticism, not complete rejection.","zh":"這個片語表達懷疑，而不是完全否定。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":13},{"front":"prove significant","meaning":"證明具有重要性","examples":[{"en":"The effect may not prove significant.","zh":"這種作用可能不會證明具有重要性。"},{"en":"To prove significant means to turn out to be important after testing or investigation.","zh":"To prove significant 指經測試或調查後顯示出重要性。"},{"en":"A small difference in test scores may not prove significant after careful analysis.","zh":"仔細分析後，測驗分數的小差異可能不具重要性。"},{"en":"If an effect proves significant, researchers may change their risk assessment.","zh":"如果某作用證明具有重要性，研究人員可能改變風險評估。"},{"en":"This phrase means importance must be shown by evidence.","zh":"這個片語表示重要性必須由證據顯示。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":13},{"front":"under normal background radiation","meaning":"在正常背景輻射下","examples":[{"en":"The effect may be too weak under normal background radiation.","zh":"在正常背景輻射下，這種作用可能太弱。"},{"en":"Under normal background radiation means in ordinary low-level radiation conditions already present in the environment.","zh":"Under normal background radiation 指在環境中已存在的普通低水平輻射條件下。"},{"en":"Some effects appear in high-dose experiments but not under normal background radiation.","zh":"有些作用在高劑量實驗中出現，但在正常背景輻射下不出現。"},{"en":"If a mechanism is weak under normal background radiation, its real-world risk may be limited.","zh":"如果某機制在正常背景輻射下很弱，其現實風險可能有限。"},{"en":"This phrase specifies the radiation conditions being considered.","zh":"這個片語指明正在考慮的輻射條件。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":13},{"front":"too weak to inflict","meaning":"太弱，不足以造成","examples":[{"en":"The effect may be too weak to inflict many double hits.","zh":"這種作用可能太弱，不足以造成許多雙重撞擊。"},{"en":"Too weak to inflict something means not strong enough to cause that damage or result.","zh":"Too weak to inflict something 指不夠強，無法造成該損害或結果。"},{"en":"A light breeze is too weak to inflict serious damage on a strong building.","zh":"微風太弱，不足以對堅固建築造成嚴重損害。"},{"en":"If the radiation effect is too weak to inflict repeated hits, the health risk may be lower.","zh":"如果輻射作用太弱，不足以造成重複撞擊，健康風險可能較低。"},{"en":"This phrase rejects a cause as insufficiently powerful.","zh":"這個片語否定某原因有足夠力量。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":14},{"front":"double hits of energy","meaning":"雙重能量撞擊","examples":[{"en":"Double hits of energy are especially damaging to cells.","zh":"雙重能量撞擊對細胞特別有害。"},{"en":"Double hits of energy are two energy impacts that strike close together in space or time.","zh":"Double hits of energy 是在空間或時間上接近的兩次能量撞擊。"},{"en":"A cell may repair one small hit, but double hits can be harder to repair.","zh":"細胞可能修復一次小撞擊，但雙重撞擊可能較難修復。"},{"en":"If radiation causes double hits near DNA, genetic damage may become more likely.","zh":"如果輻射在DNA附近造成雙重撞擊，基因損傷可能更可能發生。"},{"en":"This phrase describes repeated or closely paired damage.","zh":"這個片語描述重複或緊密成對的損傷。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":14},{"front":"known to be","meaning":"已知是","examples":[{"en":"Double hits are known to be highly damaging.","zh":"雙重撞擊已知是高度有害的。"},{"en":"Known to be means generally recognised or established as having a certain quality.","zh":"Known to be 指被普遍認識或確立為具有某種特質。"},{"en":"Smoking is known to be harmful to lung health.","zh":"吸煙已知對肺部健康有害。"},{"en":"If a process is known to be dangerous, safety rules should treat it seriously.","zh":"如果某過程已知是危險的，安全規則應認真對待它。"},{"en":"This phrase shows that the point is already accepted by experts or common evidence.","zh":"這個片語顯示該重點已被專家或一般證據接受。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":14},{"front":"damaging to cells","meaning":"對細胞有害","examples":[{"en":"Closely spaced impacts may be damaging to cells.","zh":"間距很近的撞擊可能對細胞有害。"},{"en":"Damaging to cells means able to harm the structure or function of living cells.","zh":"Damaging to cells 指能傷害活細胞的結構或功能。"},{"en":"Some chemicals are damaging to cells because they interfere with DNA repair.","zh":"有些化學物對細胞有害，因為它們干擾DNA修復。"},{"en":"If something is damaging to cells, it may affect tissues and organs over time.","zh":"如果某物對細胞有害，久而久之可能影響組織和器官。"},{"en":"This phrase describes biological harm at the cellular level.","zh":"這個片語描述細胞層面的生物傷害。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":14},{"front":"very unlikely that","meaning":"非常不可能","examples":[{"en":"It is very unlikely that individual cells would receive several impacts.","zh":"個別細胞會受到多次撞擊是非常不可能的。"},{"en":"Very unlikely that means there is only a very small chance that something will happen.","zh":"Very unlikely that 指某事發生的機會非常小。"},{"en":"It is very unlikely that a student will improve without practice or feedback.","zh":"學生沒有練習或回饋而進步，是非常不可能的。"},{"en":"If an event is very unlikely, scientists may doubt whether it explains a common problem.","zh":"如果某事件非常不可能，科學家可能懷疑它是否能解釋常見問題。"},{"en":"This phrase expresses strong doubt about probability.","zh":"這個片語表達對可能性的強烈懷疑。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":14},{"front":"individual cells","meaning":"個別細胞","examples":[{"en":"Individual cells may not receive multiple photoelectron impacts.","zh":"個別細胞未必會受到多次光電子撞擊。"},{"en":"Individual cells are single living units considered one by one.","zh":"Individual cells 是逐一考慮的單個活體單位。"},{"en":"Doctors may examine individual cells under a microscope to look for abnormal changes.","zh":"醫生可能在顯微鏡下檢查個別細胞，以尋找異常變化。"},{"en":"Damage to individual cells may matter if it affects DNA and cell division.","zh":"如果對個別細胞的損傷影響DNA和細胞分裂，便可能重要。"},{"en":"This phrase focuses on single cells rather than whole tissues.","zh":"這個片語著重單個細胞，而不是整個組織。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":14},{"front":"be subject to","meaning":"受到；遭受","examples":[{"en":"Individual cells may be subject to photoelectron impacts.","zh":"個別細胞可能受到光電子撞擊。"},{"en":"To be subject to something means to experience it or be affected by it.","zh":"To be subject to something 指經歷某事或受其影響。"},{"en":"Coastal homes are subject to flooding during severe storms.","zh":"沿海房屋在嚴重風暴期間可能受到水浸影響。"},{"en":"Cells subject to repeated radiation impacts may face greater damage.","zh":"受到重複輻射撞擊的細胞可能面對更大損傷。"},{"en":"This phrase describes exposure to a condition or effect.","zh":"這個片語描述接觸某條件或作用。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":14},{"front":"closely spaced","meaning":"間距很近的","examples":[{"en":"Closely spaced photoelectron impacts are thought to be damaging.","zh":"間距很近的光電子撞擊被認為有害。"},{"en":"Closely spaced means very near to each other in distance or time.","zh":"Closely spaced 指在距離或時間上非常接近。"},{"en":"Closely spaced desks can make a classroom feel crowded.","zh":"間距很近的課桌會令課室感到擁擠。"},{"en":"Closely spaced energy hits may be harder for a cell to repair.","zh":"間距很近的能量撞擊可能令細胞更難修復。"},{"en":"This phrase emphasises nearness and concentration.","zh":"這個片語強調接近和集中。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":14},{"front":"photoelectron impacts","meaning":"光電子撞擊","examples":[{"en":"Cells may be damaged by photoelectron impacts.","zh":"細胞可能被光電子撞擊損害。"},{"en":"Photoelectron impacts are strikes caused by electrons released through the photoelectric effect.","zh":"Photoelectron impacts 是由光電效應釋放的電子造成的撞擊。"},{"en":"If photoelectron impacts occur near DNA, researchers may worry about genetic damage.","zh":"如果光電子撞擊在DNA附近發生，研究人員可能擔心基因損傷。"},{"en":"The seriousness of photoelectron impacts depends on energy, location, and frequency.","zh":"光電子撞擊的嚴重性取決於能量、位置和頻率。"},{"en":"This phrase describes the damaging contact made by released electrons.","zh":"這個片語描述被釋放電子造成的破壞性接觸。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":14},{"front":"gamma irradiation","meaning":"伽馬照射","examples":[{"en":"The effect may be weak under normal background gamma irradiation.","zh":"在正常背景伽馬照射下，這種作用可能很弱。"},{"en":"Gamma irradiation means exposure to gamma radiation.","zh":"Gamma irradiation 指接觸伽馬輻射。"},{"en":"Medical equipment may be sterilised by controlled gamma irradiation.","zh":"醫療設備可能透過受控伽馬照射進行消毒。"},{"en":"In living tissue, gamma irradiation can matter if it damages cells or DNA.","zh":"在活體組織中，如果伽馬照射損害細胞或DNA，便可能重要。"},{"en":"This phrase describes a radiation exposure process.","zh":"這個片語描述輻射接觸過程。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":14},{"front":"despite his doubts","meaning":"儘管他有疑慮","examples":[{"en":"Despite his doubts, Menzel raised the issue with his committee.","zh":"儘管他有疑慮，Menzel仍向他的委員會提出這個問題。"},{"en":"Despite his doubts means although he was not fully convinced.","zh":"Despite his doubts 指雖然他並未完全信服。"},{"en":"Despite her doubts, the teacher tried the new method for one term.","zh":"儘管她有疑慮，老師仍試用新方法一個學期。"},{"en":"A scientist may investigate an idea despite doubts because the possible risk is serious.","zh":"科學家可能儘管有疑慮仍調查某想法，因為可能風險很嚴重。"},{"en":"This phrase shows cautious action even without full belief.","zh":"這個片語顯示即使沒有完全相信，也採取謹慎行動。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":14},{"front":"raised the issue","meaning":"提出這個問題","examples":[{"en":"Menzel raised the issue with his committee.","zh":"Menzel向他的委員會提出這個問題。"},{"en":"To raise the issue means to bring a topic up for discussion.","zh":"To raise the issue 指提出某議題供討論。"},{"en":"A parent may raise the issue of school safety at a meeting.","zh":"家長可能在會議上提出學校安全問題。"},{"en":"Raising an issue can lead to more data collection and further debate.","zh":"提出問題可以導致更多數據收集和進一步討論。"},{"en":"This phrase describes starting formal discussion about a concern.","zh":"這個片語描述正式開始討論某項憂慮。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":15},{"front":"intended to collect","meaning":"打算收集","examples":[{"en":"Several colleagues intended to collect relevant data.","zh":"幾位同事打算收集相關數據。"},{"en":"Intended to collect means planned or meant to gather information or material.","zh":"Intended to collect 指計劃或打算收集資訊或材料。"},{"en":"A teacher intended to collect homework before the lesson began.","zh":"老師打算在課堂開始前收集功課。"},{"en":"Researchers intended to collect data so they could test the theory more carefully.","zh":"研究人員打算收集數據，以便更仔細測試該理論。"},{"en":"This phrase shows a planned future action.","zh":"這個片語顯示計劃中的未來行動。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":15},{"front":"relevant data","meaning":"相關數據","examples":[{"en":"Researchers need relevant data to test the theory.","zh":"研究人員需要相關數據來測試該理論。"},{"en":"Relevant data are facts or numbers directly useful for answering a question.","zh":"Relevant data 是直接有助回答問題的事實或數字。"},{"en":"A school studying lateness needs relevant data such as arrival times and transport problems.","zh":"研究遲到問題的學校需要到校時間和交通問題等相關數據。"},{"en":"Without relevant data, people may argue from opinion rather than evidence.","zh":"沒有相關數據，人們可能根據意見而不是證據爭論。"},{"en":"This phrase separates useful evidence from unrelated information.","zh":"這個片語把有用證據與無關資訊分開。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":15},{"front":"perform calculations","meaning":"進行計算","examples":[{"en":"Scientists planned to perform calculations on the effect.","zh":"科學家計劃對該作用進行計算。"},{"en":"To perform calculations means to use mathematics to work out values, risks, or relationships.","zh":"To perform calculations 指使用數學計算數值、風險或關係。"},{"en":"Engineers perform calculations before deciding whether a roof can carry solar panels.","zh":"工程師在決定屋頂能否承載太陽能板前會進行計算。"},{"en":"Scientists perform calculations to compare a theory with realistic conditions.","zh":"科學家進行計算，以比較理論與現實條件。"},{"en":"This phrase describes a formal numerical process.","zh":"這個片語描述正式數字運算過程。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":15},{"front":"check whether","meaning":"檢查是否","examples":[{"en":"They wanted to check whether there was any real effect.","zh":"他們想檢查是否有任何真實作用。"},{"en":"To check whether something is true means to examine it and find out if it is true.","zh":"To check whether something is true 指檢視某事以找出它是否真實。"},{"en":"A teacher may check whether students understand before moving to the next topic.","zh":"老師在進入下一個主題前，可能檢查學生是否理解。"},{"en":"Scientists check whether a theory works by comparing predictions with data.","zh":"科學家透過比較預測和數據，檢查理論是否有效。"},{"en":"This phrase shows careful verification.","zh":"這個片語顯示仔細驗證。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":15},{"front":"any possibility of","meaning":"……的任何可能性","examples":[{"en":"They wanted to see whether there was any possibility of a real effect.","zh":"他們想看看是否有任何真實作用的可能性。"},{"en":"Any possibility of something means even a small chance that it may happen or exist.","zh":"Any possibility of something 指某事即使有很小機會發生或存在。"},{"en":"Doctors check for any possibility of infection after surgery.","zh":"醫生在手術後檢查是否有任何感染可能性。"},{"en":"If there is any possibility of serious harm, further investigation may be needed.","zh":"如果有任何嚴重傷害的可能性，可能需要進一步調查。"},{"en":"This phrase keeps attention on even low-probability risks.","zh":"這個片語令注意力保持在即使低概率的風險上。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":15},{"front":"a real effect","meaning":"真實作用","examples":[{"en":"The committee wanted to test whether there was a real effect.","zh":"委員會想測試是否有真實作用。"},{"en":"A real effect is an actual measurable effect, not just an idea or coincidence.","zh":"Real effect 是真正可量度的作用，而不只是想法或巧合。"},{"en":"A new teaching method has a real effect only if students improve beyond normal variation.","zh":"只有當學生進步超過正常變化，新教學方法才有真實作用。"},{"en":"Experiments help decide whether a theory describes a real effect.","zh":"實驗幫助判斷理論是否描述真實作用。"},{"en":"This phrase contrasts evidence-based impact with speculation.","zh":"這個片語把有證據的影響與推測作對比。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":15},{"front":"living tissues","meaning":"活體組織","examples":[{"en":"The effect might occur in living tissues.","zh":"這種作用可能在活體組織中發生。"},{"en":"Living tissues are groups of living cells that form parts of the body, such as skin, muscle, or organs.","zh":"Living tissues 是由活細胞組成、形成身體部分的組織，例如皮膚、肌肉或器官。"},{"en":"Radiation can affect living tissues differently from simple laboratory materials.","zh":"輻射對活體組織的影響可能不同於對簡單實驗材料的影響。"},{"en":"If an effect occurs in living tissues, it may have health importance.","zh":"如果某作用在活體組織中發生，它可能具有健康重要性。"},{"en":"This phrase refers to real biological material in living organisms.","zh":"這個片語指活生物中的真實生物材料。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":15},{"front":"have no plans to","meaning":"沒有計劃去","examples":[{"en":"Some organisations have no plans to investigate the hypothesis.","zh":"一些組織沒有計劃去調查該假說。"},{"en":"To have no plans to do something means not currently intending or preparing to do it.","zh":"To have no plans to do something 指目前沒有打算或準備做某事。"},{"en":"A school may have no plans to change the timetable this year.","zh":"學校今年可能沒有計劃更改時間表。"},{"en":"If officials have no plans to investigate, campaigners may call for independent research.","zh":"如果官員沒有計劃調查，運動人士可能呼籲進行獨立研究。"},{"en":"This phrase describes absence of planned action.","zh":"這個片語描述沒有計劃中的行動。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":15},{"front":"investigate Busby’s hypothesis","meaning":"調查 Busby 的假說","examples":[{"en":"The Ministry of Defence has no plans to investigate Busby’s hypothesis.","zh":"國防部沒有計劃調查Busby的假說。"},{"en":"To investigate Busby’s hypothesis means to examine and test Busby’s proposed explanation.","zh":"To investigate Busby’s hypothesis 指檢視和測試Busby提出的解釋。"},{"en":"Scientists investigate a hypothesis by collecting data and checking whether predictions match reality.","zh":"科學家透過收集數據並檢查預測是否符合現實來調查假說。"},{"en":"If a hypothesis concerns health risk, investigation can help confirm or reject it.","zh":"如果假說關乎健康風險，調查可以幫助確認或否定它。"},{"en":"This phrase refers to testing a specific researcher’s idea.","zh":"這個片語指測試某位研究者的特定想法。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":15},{"front":"radiation biophysicist","meaning":"輻射生物物理學家","examples":[{"en":"A radiation biophysicist called Mark Hill commented on the theory.","zh":"一位名叫Mark Hill的輻射生物物理學家評論了該理論。"},{"en":"A radiation biophysicist is a scientist who studies how radiation affects living systems.","zh":"Radiation biophysicist 是研究輻射如何影響生命系統的科學家。"},{"en":"A radiation biophysicist may examine how particles damage cells or DNA.","zh":"輻射生物物理學家可能檢視粒子如何損害細胞或DNA。"},{"en":"Such experts can judge whether a proposed radiation mechanism is realistic.","zh":"這類專家可以判斷某個輻射機制是否現實。"},{"en":"This phrase combines physics, biology, and radiation science.","zh":"這個片語結合物理學、生物學和輻射科學。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":15},{"front":"would like to see","meaning":"希望看到","examples":[{"en":"Mark Hill would like to see a fuller investigation.","zh":"Mark Hill希望看到更全面的調查。"},{"en":"Would like to see means wants something to happen or be done.","zh":"Would like to see 指希望某事發生或被完成。"},{"en":"A teacher would like to see more students asking questions in class.","zh":"老師希望看到更多學生在課堂上提問。"},{"en":"Scientists may like to see fuller testing before accepting a bold claim.","zh":"科學家可能希望看到更完整測試，才接受大膽主張。"},{"en":"This phrase politely expresses a desired action or result.","zh":"這個片語禮貌地表達希望出現的行動或結果。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":16},{"front":"a fuller investigation","meaning":"更全面的調查","examples":[{"en":"Some scientists want a fuller investigation of the theory.","zh":"一些科學家希望對該理論進行更全面的調查。"},{"en":"A fuller investigation is a more complete and detailed examination of an issue.","zh":"Fuller investigation 是對某議題更完整和詳細的檢視。"},{"en":"A school may need a fuller investigation before blaming one teacher for poor results.","zh":"學校在把成績差歸咎於一位老師前，可能需要更全面的調查。"},{"en":"A fuller investigation can include more data, better models, and different viewpoints.","zh":"更全面的調查可以包括更多數據、更好模型和不同觀點。"},{"en":"This phrase suggests that the current evidence is not enough.","zh":"這個片語暗示目前證據不足夠。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":16},{"front":"might show that","meaning":"可能會顯示","examples":[{"en":"A fuller investigation might show that the effect is weaker.","zh":"更全面的調查可能會顯示該作用較弱。"},{"en":"Might show that means could reveal or demonstrate something, but the result is not certain yet.","zh":"Might show that 指可能揭示或證明某事，但結果尚未確定。"},{"en":"More tests might show that a student’s difficulty is caused by weak vocabulary.","zh":"更多測試可能會顯示學生困難源於詞彙薄弱。"},{"en":"Further research might show that a risk is smaller or larger than first believed.","zh":"進一步研究可能會顯示風險比最初相信的更小或更大。"},{"en":"This phrase expresses possible future evidence.","zh":"這個片語表達未來可能出現的證據。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":16},{"front":"not as powerful as","meaning":"不如……所聲稱般強大","examples":[{"en":"The photoelectric effect may not be as powerful as Busby claims.","zh":"光電效應可能不如Busby所聲稱般強大。"},{"en":"Not as powerful as means weaker or less effective than someone says or expects.","zh":"Not as powerful as 指比某人所說或預期更弱或更不有效。"},{"en":"A new app may not be as powerful as its advertisements claim.","zh":"新應用程式可能不如廣告所聲稱般強大。"},{"en":"If an effect is not as powerful as proposed, the theory may still be useful but less dramatic.","zh":"如果某作用不如提出時那麼強，理論仍可能有用，但不那麼戲劇化。"},{"en":"This phrase compares claimed strength with possible real strength.","zh":"這個片語比較聲稱強度與可能真實強度。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":16},{"front":"more detailed calculations","meaning":"更詳細的計算","examples":[{"en":"More detailed calculations are needed.","zh":"需要更詳細的計算。"},{"en":"More detailed calculations are more careful numerical analyses that include additional factors.","zh":"More detailed calculations 是包含更多因素的更仔細數字分析。"},{"en":"Engineers need more detailed calculations when a building design becomes complex.","zh":"當建築設計變得複雜，工程師需要更詳細的計算。"},{"en":"More detailed calculations can show whether a simple model overestimated an effect.","zh":"更詳細的計算可以顯示簡單模型是否高估了某作用。"},{"en":"This phrase asks for stronger mathematical evidence.","zh":"這個片語要求更強數學證據。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":16},{"front":"dose estimates","meaning":"劑量估算","examples":[{"en":"Scientists need dose estimates for realistic situations.","zh":"科學家需要現實情況下的劑量估算。"},{"en":"Dose estimates are calculated amounts of exposure a person or tissue may receive.","zh":"Dose estimates 是對人或組織可能接受到的接觸量所作的計算。"},{"en":"Doctors use dose estimates to limit radiation during medical scans.","zh":"醫生使用劑量估算來限制醫療掃描中的輻射。"},{"en":"Better dose estimates help researchers compare theoretical risk with real-world exposure.","zh":"更好的劑量估算幫助研究人員比較理論風險與現實接觸。"},{"en":"This phrase is important when judging health effects.","zh":"這個片語在判斷健康影響時很重要。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":16},{"front":"realistic situations","meaning":"現實情況","examples":[{"en":"More calculations are needed for realistic situations.","zh":"需要針對現實情況進行更多計算。"},{"en":"Realistic situations are conditions that are close to what actually happens in real life.","zh":"Realistic situations 是接近真實生活中實際發生情況的條件。"},{"en":"A fire drill should test realistic situations, not only perfect classroom behaviour.","zh":"火警演習應測試現實情況，而不只是完美課室行為。"},{"en":"A radiation model must include realistic situations if it is to predict real health risk.","zh":"如果輻射模型要預測真實健康風險，就必須包括現實情況。"},{"en":"This phrase contrasts real-world conditions with simplified examples.","zh":"這個片語把真實世界條件與簡化例子作對比。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":16},{"front":"with and without uranium present","meaning":"有鈾和沒有鈾存在的情況","examples":[{"en":"Researchers should compare situations with and without uranium present.","zh":"研究人員應比較有鈾和沒有鈾存在的情況。"},{"en":"With and without uranium present means comparing cases where uranium is present with cases where it is absent.","zh":"With and without uranium present 指比較有鈾存在和沒有鈾存在的情況。"},{"en":"Scientists compare plants with and without fertiliser to see whether growth changes.","zh":"科學家比較有肥料和沒有肥料的植物，以查看生長是否改變。"},{"en":"Comparing conditions with and without uranium helps isolate uranium’s effect.","zh":"比較有鈾和沒有鈾的條件，有助分離鈾的作用。"},{"en":"This phrase describes a controlled comparison.","zh":"這個片語描述受控比較。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":16},{"front":"doubts centre on","meaning":"疑慮集中於","examples":[{"en":"Hill’s doubts centre on Compton scattering.","zh":"Hill的疑慮集中於康普頓散射。"},{"en":"Doubts centre on something means the main reason for uncertainty is that issue.","zh":"Doubts centre on something 指不確定的主要原因集中在該議題。"},{"en":"Parents’ doubts about the trip centre on transport safety.","zh":"家長對旅行的疑慮集中於交通安全。"},{"en":"If scientific doubts centre on a missing factor, calculations must include that factor.","zh":"如果科學疑慮集中於缺失因素，計算便必須包括該因素。"},{"en":"This phrase identifies the focus of concern.","zh":"這個片語指出憂慮焦點。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":16},{"front":"Compton scattering","meaning":"康普頓散射","examples":[{"en":"Compton scattering may reduce the importance of the photoelectric effect.","zh":"康普頓散射可能降低光電效應的重要性。"},{"en":"Compton scattering is a physical process in which photons scatter after interacting with electrons.","zh":"Compton scattering 是光子與電子互動後散射的物理過程。"},{"en":"In radiation physics, Compton scattering can create secondary electrons in many materials.","zh":"在輻射物理中，康普頓散射可以在許多材料中產生次級電子。"},{"en":"Including Compton scattering may change calculations about how important uranium is.","zh":"納入康普頓散射可能改變關於鈾重要性的計算。"},{"en":"This phrase names another radiation interaction mechanism.","zh":"這個片語命名另一種輻射互動機制。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":16},{"front":"needs to be factored into","meaning":"需要被納入考慮","examples":[{"en":"Compton scattering needs to be factored into the calculations.","zh":"康普頓散射需要被納入計算中。"},{"en":"Needs to be factored into means must be included as an important part of the calculation or decision.","zh":"Needs to be factored into 指必須作為重要部分納入計算或決定。"},{"en":"Travel time needs to be factored into a school timetable.","zh":"交通時間需要被納入學校時間表考慮。"},{"en":"If a model ignores an important process, that process needs to be factored into later calculations.","zh":"如果模型忽略重要過程，該過程需要被納入之後計算。"},{"en":"This phrase is used when a missing factor could change the result.","zh":"這個片語用於缺失因素可能改變結果時。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":16},{"front":"any calculations","meaning":"任何計算","examples":[{"en":"Any calculations should include Compton scattering.","zh":"任何計算都應包括康普頓散射。"},{"en":"Any calculations means all relevant mathematical work, not just some of it.","zh":"Any calculations 指所有相關數學運算，而不只是其中一些。"},{"en":"Any calculations about a school trip should include transport, food, and entrance fees.","zh":"關於學校旅行的任何計算都應包括交通、食物和入場費。"},{"en":"If any calculations ignore a major variable, their result may be misleading.","zh":"如果任何計算忽略主要變量，其結果可能具誤導性。"},{"en":"This phrase stresses that no calculation should leave out the factor.","zh":"這個片語強調沒有計算應遺漏該因素。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":17},{"front":"taking it into account","meaning":"將其納入考慮","examples":[{"en":"Taking Compton scattering into account would change the result.","zh":"將康普頓散射納入考慮會改變結果。"},{"en":"Taking it into account means considering it when making a judgement or calculation.","zh":"Taking it into account 指在作判斷或計算時考慮它。"},{"en":"A teacher should take a student’s illness into account when marking late work.","zh":"老師在批改遲交功課時，應將學生生病納入考慮。"},{"en":"Taking an extra factor into account can make a model more realistic.","zh":"將額外因素納入考慮可以令模型更現實。"},{"en":"This phrase shows that a decision includes a relevant factor.","zh":"這個片語顯示決定包括相關因素。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":17},{"front":"reduce the relative importance of","meaning":"降低……的相對重要性","examples":[{"en":"Compton scattering would reduce the relative importance of uranium.","zh":"康普頓散射會降低鈾的相對重要性。"},{"en":"To reduce the relative importance of something means to make it seem less important compared with other factors.","zh":"To reduce the relative importance of something 指令某因素相對其他因素顯得較不重要。"},{"en":"If sleep and stress are included, diet may reduce in relative importance as the only cause of tiredness.","zh":"如果納入睡眠和壓力，飲食作為疲倦唯一原因的相對重要性可能下降。"},{"en":"Adding Compton scattering could make uranium less central in the calculation.","zh":"加入康普頓散射可能令鈾在計算中較不核心。"},{"en":"This phrase changes how important one factor looks compared with others.","zh":"這個片語改變一個因素相對其他因素的重要程度。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":17},{"front":"secondary electrons","meaning":"次級電子","examples":[{"en":"Uranium may act as an emitter of secondary electrons.","zh":"鈾可能作為次級電子的發射體。"},{"en":"Secondary electrons are electrons produced as a result of an earlier radiation interaction.","zh":"Secondary electrons 是由較早的輻射互動所產生的電子。"},{"en":"When radiation hits matter, secondary electrons may be released and cause further effects.","zh":"當輻射撞擊物質，次級電子可能被釋放並造成進一步影響。"},{"en":"If secondary electrons appear near DNA, they may contribute to damage.","zh":"如果次級電子出現在DNA附近，它們可能促成損傷。"},{"en":"This phrase describes particles produced indirectly.","zh":"這個片語描述間接產生的粒子。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":17},{"front":"dilute the mechanism","meaning":"削弱該機制","examples":[{"en":"Compton scattering could dilute the mechanism proposed by the researchers.","zh":"康普頓散射可能削弱研究人員提出的機制。"},{"en":"To dilute the mechanism means to weaken its importance or make it less dominant.","zh":"To dilute the mechanism 指削弱該機制的重要性或令它不那麼主導。"},{"en":"Adding other causes can dilute the explanation that one factor alone caused the problem.","zh":"加入其他原因可以削弱單一因素造成問題這種解釋。"},{"en":"If Compton scattering also produces electrons, uranium’s special role may be diluted.","zh":"如果康普頓散射也產生電子，鈾的特殊角色可能被削弱。"},{"en":"This phrase suggests a mechanism becomes less clear or less powerful.","zh":"這個片語暗示機制變得不那麼清晰或不那麼有力。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":17},{"front":"proposed by","meaning":"由……提出","examples":[{"en":"The mechanism was proposed by Busby and Schnug.","zh":"這個機制由Busby和Schnug提出。"},{"en":"Proposed by means suggested or put forward by a particular person or group.","zh":"Proposed by 指由某人或某團體建議或提出。"},{"en":"A new school rule proposed by students may receive more support from classmates.","zh":"由學生提出的新校規可能得到同學更多支持。"},{"en":"A theory proposed by researchers still needs evidence before acceptance.","zh":"由研究人員提出的理論仍需要證據才會被接受。"},{"en":"This phrase identifies who introduced an idea.","zh":"這個片語指出誰引入某個想法。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":17},{"front":"arguments over","meaning":"關於……的爭論","examples":[{"en":"The arguments over depleted uranium are likely to continue.","zh":"關於貧鈾的爭論很可能會繼續。"},{"en":"Arguments over something are disagreements or debates about it.","zh":"Arguments over something 是關於某事的分歧或辯論。"},{"en":"Arguments over school uniform may involve cost, freedom, and discipline.","zh":"關於校服的爭論可能涉及成本、自由和紀律。"},{"en":"Scientific arguments over risk continue when evidence is incomplete or disputed.","zh":"當證據不完整或有爭議，關於風險的科學爭論會繼續。"},{"en":"This phrase describes an ongoing debate.","zh":"這個片語描述持續辯論。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":17},{"front":"are likely to continue","meaning":"很可能會繼續","examples":[{"en":"The arguments are likely to continue whatever the outcome is.","zh":"無論結果如何，爭論很可能會繼續。"},{"en":"Are likely to continue means will probably keep going.","zh":"Are likely to continue 指很可能會持續下去。"},{"en":"Discussions about homework are likely to continue because parents and teachers see it differently.","zh":"關於功課的討論很可能會繼續，因為家長和老師看法不同。"},{"en":"If evidence remains mixed, the debate is likely to continue.","zh":"如果證據仍然不一致，辯論很可能會繼續。"},{"en":"This phrase predicts ongoing activity.","zh":"這個片語預測活動會持續。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":17},{"front":"whatever the outcome","meaning":"無論結果如何","examples":[{"en":"The debate may continue whatever the outcome of the experiments.","zh":"無論實驗結果如何，辯論可能會繼續。"},{"en":"Whatever the outcome means no matter what the result is.","zh":"Whatever the outcome 指不論結果是甚麼。"},{"en":"Whatever the outcome of the exam, students should review what they learned.","zh":"無論考試結果如何，學生都應檢討學到的東西。"},{"en":"A controversial issue may remain debated whatever the outcome of one study.","zh":"無論一項研究結果如何，有爭議議題可能仍會被辯論。"},{"en":"This phrase shows that the result may not end the situation.","zh":"這個片語顯示結果未必會結束情況。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":17},{"front":"holds up","meaning":"站得住腳","examples":[{"en":"It remains to be seen whether Busby’s theory holds up.","zh":"Busby的理論是否站得住腳仍有待觀察。"},{"en":"If a theory holds up, it remains convincing after testing and criticism.","zh":"If a theory holds up，意思是它在測試和批評後仍然令人信服。"},{"en":"A student’s argument holds up if evidence still supports it after questions.","zh":"如果證據在提問後仍支持學生論點，該論點便站得住腳。"},{"en":"A scientific model may not hold up when more realistic data are added.","zh":"當加入更現實數據，科學模型可能站不住腳。"},{"en":"This phrase asks whether an idea can survive examination.","zh":"這個片語問一個想法能否經受檢驗。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":17},{"front":"remains to be seen","meaning":"仍有待觀察","examples":[{"en":"Whether the theory is correct remains to be seen.","zh":"該理論是否正確仍有待觀察。"},{"en":"Remains to be seen means is not yet known and will only become clear later.","zh":"Remains to be seen 指目前尚未知曉，要到之後才會清楚。"},{"en":"Whether the new timetable improves sleep remains to be seen.","zh":"新時間表是否改善睡眠仍有待觀察。"},{"en":"If more experiments are needed, the final answer remains to be seen.","zh":"如果需要更多實驗，最終答案仍有待觀察。"},{"en":"This phrase expresses uncertainty about future evidence.","zh":"這個片語表達對未來證據的不確定。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":17},{"front":"investigate it","meaning":"調查它","examples":[{"en":"Investigating the theory can help clear up doubts.","zh":"調查該理論可以幫助釐清疑慮。"},{"en":"To investigate it means to examine it carefully to find out the truth.","zh":"To investigate it 指仔細檢視它以找出真相。"},{"en":"A school should investigate a complaint before deciding who is responsible.","zh":"學校在決定誰負責前，應調查投訴。"},{"en":"Scientists investigate a theory by testing predictions and checking data.","zh":"科學家透過測試預測和檢查數據來調查理論。"},{"en":"This phrase describes careful inquiry, not casual guessing.","zh":"這個片語描述仔細探究，而不是隨便猜測。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":18},{"front":"clear up doubts","meaning":"釐清疑慮","examples":[{"en":"Further investigation can help clear up doubts.","zh":"進一步調查可以幫助釐清疑慮。"},{"en":"To clear up doubts means to remove uncertainty by providing better information.","zh":"To clear up doubts 指透過提供更好資訊消除不確定。"},{"en":"A teacher’s explanation can clear up doubts before students start homework.","zh":"老師的解釋可以在學生開始做功課前釐清疑慮。"},{"en":"More data can clear up doubts about whether a substance is harmful.","zh":"更多數據可以釐清某物質是否有害的疑慮。"},{"en":"This phrase shows how evidence reduces confusion or suspicion.","zh":"這個片語顯示證據如何減少混亂或懷疑。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":18},{"front":"mysterious substance","meaning":"神秘物質","examples":[{"en":"Depleted uranium remains a mysterious substance in this debate.","zh":"在這場爭論中，貧鈾仍然是一種神秘物質。"},{"en":"A mysterious substance is a material whose effects, nature, or behaviour are not fully understood.","zh":"Mysterious substance 是其影響、性質或行為尚未被完全理解的材料。"},{"en":"Doctors may test a mysterious substance found in a patient’s workplace.","zh":"醫生可能測試在病人工作場所發現的神秘物質。"},{"en":"If a substance is mysterious, researchers need to identify how people are exposed to it.","zh":"如果某物質很神秘，研究人員需要確認人們如何接觸到它。"},{"en":"This phrase suggests uncertainty and unanswered questions.","zh":"這個片語暗示不確定和未解答問題。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":18},{"front":"contains the following information","meaning":"包含以下資料","examples":[{"en":"Students must decide which paragraph contains the following information.","zh":"學生必須判斷哪一段包含以下資料。"},{"en":"Contains the following information means includes the details listed after the instruction.","zh":"Contains the following information 指包括指示後列出的細節。"},{"en":"In a reading test, students scan paragraphs to find which one contains the required information.","zh":"在閱讀測驗中，學生掃讀段落，以找出哪一段包含所需資料。"},{"en":"A paragraph may contain the idea even if it uses different words from the question.","zh":"即使段落使用與題目不同的字詞，也可能包含該意思。"},{"en":"This phrase is common in paragraph-matching tasks.","zh":"這個片語常見於段落配對任務。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":18},{"front":"write the correct letter","meaning":"寫下正確字母","examples":[{"en":"Students write the correct letter in the answer boxes.","zh":"學生在答案方格中寫下正確字母。"},{"en":"Write the correct letter means put the letter that matches the right answer.","zh":"Write the correct letter 指寫下與正確答案相配的字母。"},{"en":"If the correct paragraph is B, students should write B clearly in the box.","zh":"如果正確段落是B，學生應在方格中清楚寫B。"},{"en":"Writing the correct letter matters because extra words may not be accepted.","zh":"寫下正確字母很重要，因為額外文字可能不被接受。"},{"en":"This phrase is a practical exam instruction.","zh":"這個片語是實用考試指示。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":18},{"front":"may use any letter more than once","meaning":"可以多次使用同一字母","examples":[{"en":"Students may use any letter more than once.","zh":"學生可以多次使用同一字母。"},{"en":"May use any letter more than once means the same answer option can be used for several questions.","zh":"May use any letter more than once 指同一答案選項可以用於多道題。"},{"en":"In paragraph matching, two questions may both refer to paragraph C.","zh":"在段落配對中，兩道題可能都指向C段。"},{"en":"Students should not avoid repeated letters if the evidence points to the same paragraph.","zh":"如果證據指向同一段，學生不應避免重複字母。"},{"en":"This instruction prevents the mistake of forcing every answer to be different.","zh":"這個指示防止學生錯誤地強迫每個答案都不同。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":18},{"front":"related to the new theory","meaning":"與新理論相關","examples":[{"en":"The question asks for a process related to the new theory.","zh":"問題要求找出與新理論相關的過程。"},{"en":"Related to the new theory means connected with the explanation that has recently been proposed.","zh":"Related to the new theory 指與最近提出的解釋有關。"},{"en":"A diagram related to a new theory can help students understand the mechanism.","zh":"與新理論相關的圖表可以幫助學生理解機制。"},{"en":"If a process is related to the theory, it may be part of how the theory works.","zh":"如果某過程與該理論相關，它可能是理論運作方式的一部分。"},{"en":"This phrase asks students to find a connection, not just a repeated word.","zh":"這個片語要求學生找出關聯，而不只是重複字詞。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":18},{"front":"acknowledges the theory","meaning":"承認該理論","examples":[{"en":"The question refers to a person who acknowledges the theory.","zh":"問題提到一個承認該理論的人。"},{"en":"To acknowledge the theory means to accept that it should be considered or taken seriously.","zh":"To acknowledge the theory 指接受該理論應被考慮或認真看待。"},{"en":"A teacher may acknowledge a student’s theory even if it needs more evidence.","zh":"老師可能承認學生的理論，即使它需要更多證據。"},{"en":"A scientist can acknowledge a theory while still doubting its importance.","zh":"科學家可以承認一個理論，同時仍懷疑其重要性。"},{"en":"This phrase shows recognition, not full agreement.","zh":"這個片語顯示認可，而不是完全同意。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":18},{"front":"doubts its significance","meaning":"懷疑其重要性","examples":[{"en":"The person acknowledges the theory but doubts its significance.","zh":"這個人承認該理論，但懷疑其重要性。"},{"en":"To doubt its significance means to question whether it is important enough to matter.","zh":"To doubt its significance 指質疑它是否重要到值得關注。"},{"en":"A doctor may accept that a symptom exists but doubt its significance if it is very mild.","zh":"如果症狀很輕微，醫生可能承認它存在，但懷疑其重要性。"},{"en":"Scientists may doubt a mechanism’s significance if it is too weak in realistic conditions.","zh":"如果某機制在現實條件下太弱，科學家可能懷疑其重要性。"},{"en":"This phrase separates accepting an idea from accepting its importance.","zh":"這個片語把接受一個想法與接受其重要性分開。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":18},{"front":"an explanation of damage to DNA","meaning":"對 DNA 損傷的解釋","examples":[{"en":"The paragraph gives an explanation of damage to DNA.","zh":"該段落提供對DNA損傷的解釋。"},{"en":"An explanation of damage to DNA tells how genetic material may be harmed.","zh":"An explanation of damage to DNA 說明遺傳物質可能如何受損。"},{"en":"A science lesson may give an explanation of DNA damage by showing how radiation breaks chemical bonds.","zh":"科學課可能透過展示輻射如何打斷化學鍵，提供對DNA損傷的解釋。"},{"en":"If researchers explain DNA damage clearly, they can test whether the proposed mechanism is realistic.","zh":"如果研究人員清楚解釋DNA損傷，就可以測試提出的機制是否現實。"},{"en":"This phrase focuses on cause and process.","zh":"這個片語著重原因和過程。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":18},{"front":"a brief, controversial explanation","meaning":"簡短而具爭議性的解釋","examples":[{"en":"The question asks for a brief, controversial explanation of the health problem.","zh":"問題要求找出對健康問題的簡短而具爭議性解釋。"},{"en":"A brief, controversial explanation is a short account that is debated or not widely accepted.","zh":"Brief, controversial explanation 是一種簡短說明，但會被爭論或未被廣泛接受。"},{"en":"A short claim about a disease can be controversial if it challenges official evidence.","zh":"如果關於疾病的簡短說法挑戰官方證據，就可能具爭議性。"},{"en":"Brief explanations may be useful, but controversial ones need careful testing.","zh":"簡短解釋可能有用，但具爭議性的解釋需要仔細測試。"},{"en":"This phrase suggests both simplicity and dispute.","zh":"這個片語暗示簡潔和爭議兩者。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":18},{"front":"soldiers’ health problems","meaning":"士兵的健康問題","examples":[{"en":"The theory may explain soldiers’ health problems.","zh":"這個理論可能解釋士兵的健康問題。"},{"en":"Soldiers’ health problems are illnesses or injuries experienced by military personnel.","zh":"Soldiers’ health problems 是軍事人員所經歷的疾病或傷害。"},{"en":"Soldiers’ health problems after war may include physical injuries, stress, and exposure-related illness.","zh":"戰後士兵的健康問題可能包括身體傷害、壓力和接觸相關疾病。"},{"en":"If weapons leave toxic residues, soldiers’ health problems may continue after battle.","zh":"如果武器留下有毒殘留物，士兵的健康問題可能在戰鬥後仍持續。"},{"en":"This phrase focuses on health effects among military personnel.","zh":"這個片語著重軍事人員中的健康影響。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":19},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"Students decide whether the following statements agree with the passage.","zh":"學生判斷以下陳述是否與文章一致。"},{"en":"Do the following statements agree with means students must check if each statement matches the text.","zh":"Do the following statements agree with 指學生必須檢查每項陳述是否符合文本。"},{"en":"In reading tests, a statement agrees with the passage only when the text supports it.","zh":"在閱讀測驗中，只有文本支持某陳述，它才與文章一致。"},{"en":"A statement may sound reasonable but still not agree with the passage.","zh":"一項陳述可能聽起來合理，但仍不一定與文章一致。"},{"en":"This phrase is common in TRUE/FALSE/NOT GIVEN questions.","zh":"這個片語常見於TRUE/FALSE/NOT GIVEN題型。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":19},{"front":"information given in","meaning":"……中提供的資料","examples":[{"en":"The answer must match the information given in the passage.","zh":"答案必須符合文章中提供的資料。"},{"en":"Information given in a text means facts or details actually provided there.","zh":"Information given in a text 指文本中實際提供的事實或細節。"},{"en":"Students should answer from the information given in the passage, not from outside knowledge.","zh":"學生應根據文章中提供的資料作答，而不是外部知識。"},{"en":"If no information is given in the text, the correct answer may be NOT GIVEN.","zh":"如果文本中沒有提供資料，正確答案可能是NOT GIVEN。"},{"en":"This phrase tells students to stay close to the source.","zh":"這個片語告訴學生要緊扣來源。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":19},{"front":"if the statement agrees with","meaning":"如果陳述與……一致","examples":[{"en":"Students write TRUE if the statement agrees with the information.","zh":"如果陳述與資料一致，學生寫TRUE。"},{"en":"If the statement agrees with means if the sentence matches what the text says.","zh":"If the statement agrees with 指如果該句與文本所說相符。"},{"en":"If the statement agrees with the passage, there should be clear evidence for it.","zh":"如果陳述與文章一致，應有清晰證據支持它。"},{"en":"Students should not choose TRUE just because the statement sounds possible.","zh":"學生不應只因陳述聽起來可能就選TRUE。"},{"en":"This phrase sets the condition for choosing TRUE.","zh":"這個片語設定選擇TRUE的條件。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":19},{"front":"if the statement contradicts","meaning":"如果陳述與……矛盾","examples":[{"en":"Students write FALSE if the statement contradicts the information.","zh":"如果陳述與資料矛盾，學生寫FALSE。"},{"en":"If the statement contradicts means if it says the opposite of what the text says.","zh":"If the statement contradicts 指如果它說出與文本相反的意思。"},{"en":"If the passage says the effect is uncertain, a statement saying it is proven may contradict it.","zh":"如果文章說作用不確定，而陳述說它已被證明，便可能與文章矛盾。"},{"en":"Students choose FALSE only when the text clearly opposes the statement.","zh":"只有當文本清楚反對該陳述，學生才選FALSE。"},{"en":"This phrase sets the condition for choosing FALSE.","zh":"這個片語設定選擇FALSE的條件。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":19},{"front":"no information on this","meaning":"沒有這方面的資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有這方面的資料，學生寫NOT GIVEN。"},{"en":"No information on this means the passage does not tell us enough to decide.","zh":"No information on this 指文章沒有提供足夠資料讓我們判斷。"},{"en":"If the text never mentions a scientist’s age, there is no information on this.","zh":"如果文本從未提及科學家的年齡，就沒有這方面資料。"},{"en":"Students should not use common sense to answer when there is no information in the passage.","zh":"當文章沒有資料時，學生不應用常識作答。"},{"en":"This phrase points to missing evidence, not disagreement.","zh":"這個片語指缺失證據，而不是不同意。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":19},{"front":"harmful to human health","meaning":"對人體健康有害","examples":[{"en":"The statement asks whether depleted uranium is harmful to human health.","zh":"這項陳述問貧鈾是否對人體健康有害。"},{"en":"Harmful to human health means able to damage people’s bodies or increase disease risk.","zh":"Harmful to human health 指能損害人的身體或增加疾病風險。"},{"en":"Dirty drinking water can be harmful to human health because it may carry bacteria.","zh":"骯髒飲用水可能對人體健康有害，因為它可能帶有細菌。"},{"en":"A substance may be harmful to human health if people breathe, eat, or absorb it over time.","zh":"如果人們長期吸入、攝入或吸收某物質，它可能對人體健康有害。"},{"en":"This phrase focuses on effects on people, not only animals or the environment.","zh":"這個片語著重對人的影響，而不只是對動物或環境的影響。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":19},{"front":"better at intercepting","meaning":"更善於攔截","examples":[{"en":"Heavier elements are better at intercepting X-rays and gamma radiation.","zh":"較重元素更善於攔截X射線和伽馬輻射。"},{"en":"Better at intercepting means more effective at blocking, catching, or absorbing something before it continues.","zh":"Better at intercepting 指更有效地在某物繼續前阻擋、捕捉或吸收它。"},{"en":"Thick curtains are better at intercepting sunlight than thin ones.","zh":"厚窗簾比薄窗簾更善於攔截陽光。"},{"en":"Heavy elements may be better at intercepting certain radiation because of their atomic structure.","zh":"重元素可能因其原子結構而更善於攔截某些輻射。"},{"en":"This phrase compares how effectively something stops another thing.","zh":"這個片語比較某物阻止另一物的有效程度。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":19},{"front":"main cause of","meaning":"……的主要成因","examples":[{"en":"The statement asks whether phantom photoelectrons are the main cause of uranium genotoxicity.","zh":"這項陳述問幻影光電子是否是鈾基因毒性的主要成因。"},{"en":"The main cause of something is the most important reason it happens.","zh":"Main cause of something 是某事發生的最重要原因。"},{"en":"Lack of sleep may be the main cause of a student’s poor concentration.","zh":"睡眠不足可能是學生專注力差的主要成因。"},{"en":"If phantom photoelectrons are the main cause, they should explain most of the genetic damage.","zh":"如果幻影光電子是主要成因，它們應能解釋大部分基因損傷。"},{"en":"This phrase identifies the chief explanation among possible causes.","zh":"這個片語指出多個可能原因中的主要解釋。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":19},{"front":"support someone’s opinion","meaning":"支持某人的意見","examples":[{"en":"The question asks whether most scientists support Mark Hill’s opinion.","zh":"問題問大多數科學家是否支持Mark Hill的意見。"},{"en":"To support someone’s opinion means to agree with or provide backing for that person’s view.","zh":"To support someone’s opinion 指同意或為某人的看法提供支持。"},{"en":"Students support a classmate’s opinion when they give examples that show it is reasonable.","zh":"當學生給出例子顯示同學的看法合理時，就是支持該同學的意見。"},{"en":"If most scientists support an opinion, the view may carry more weight.","zh":"如果大多數科學家支持某意見，該看法可能更有分量。"},{"en":"This phrase asks about agreement, not just awareness.","zh":"這個片語詢問是否同意，而不只是知道。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":19},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below with words from the passage.","zh":"學生用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in the missing words in the summary that follows.","zh":"Complete the summary below 指填寫下面摘要中的缺失字詞。"},{"en":"Students should read the summary first to understand its grammar and meaning.","zh":"學生應先閱讀摘要，以理解其文法和意思。"},{"en":"The correct answer must fit the sentence and match the passage.","zh":"正確答案必須符合句子，並與文章相符。"},{"en":"This phrase is a common instruction in reading tests.","zh":"這個片語是閱讀測驗中的常見指示。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":19},{"front":"no more than two words","meaning":"不多於兩個字","examples":[{"en":"Students choose no more than two words from the passage.","zh":"學生從文章中選擇不多於兩個字。"},{"en":"No more than two words means the answer must contain one or two words only.","zh":"No more than two words 指答案只能包含一個或兩個字。"},{"en":"If the answer has three words, it breaks the instruction even if the idea is right.","zh":"如果答案有三個字，即使意思正確也違反指示。"},{"en":"Students should copy only the necessary words from the passage.","zh":"學生應只從文章中抄寫必要字詞。"},{"en":"This phrase controls the maximum length of the answer.","zh":"這個片語控制答案的最長長度。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":20},{"front":"useful in warfare","meaning":"在戰爭中有用","examples":[{"en":"Depleted uranium has properties that are useful in warfare.","zh":"貧鈾具有在戰爭中有用的特性。"},{"en":"Useful in warfare means helpful for military fighting or battlefield purposes.","zh":"Useful in warfare 指對軍事作戰或戰場用途有幫助。"},{"en":"Strong armour is useful in warfare because it protects soldiers and vehicles.","zh":"堅固裝甲在戰爭中有用，因為它保護士兵和車輛。"},{"en":"A material may be useful in warfare but still raise serious environmental concerns.","zh":"一種材料可能在戰爭中有用，但仍引起嚴重環境憂慮。"},{"en":"This phrase judges usefulness from a military point of view.","zh":"這個片語從軍事角度判斷有用性。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":20},{"front":"prompt organisations to","meaning":"促使組織去","examples":[{"en":"Health concerns may prompt organisations to call for further research.","zh":"健康憂慮可能促使組織呼籲進一步研究。"},{"en":"To prompt organisations to do something means to cause or encourage them to take action.","zh":"To prompt organisations to do something 指促使或鼓勵組織採取行動。"},{"en":"A rise in accidents may prompt schools to improve road safety rules.","zh":"事故增加可能促使學校改善道路安全規則。"},{"en":"Public fear can prompt organisations to demand clearer evidence.","zh":"公眾恐懼可以促使組織要求更清晰證據。"},{"en":"This phrase connects a cause with an institutional response.","zh":"這個片語把原因與機構回應連接起來。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":20},{"front":"call for further research","meaning":"呼籲進一步研究","examples":[{"en":"Several organisations call for further research into depleted uranium.","zh":"幾個組織呼籲對貧鈾進一步研究。"},{"en":"To call for further research means to publicly ask for more study before reaching a final conclusion.","zh":"To call for further research 指公開要求進行更多研究，才得出最終結論。"},{"en":"Doctors may call for further research when early results are worrying but incomplete.","zh":"當早期結果令人擔心但不完整時，醫生可能呼籲進一步研究。"},{"en":"Further research can test whether a suspected health risk is real.","zh":"進一步研究可以測試可疑健康風險是否真實。"},{"en":"This phrase is common when evidence is uncertain or disputed.","zh":"這個片語常見於證據不確定或有爭議時。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":20},{"front":"more study is needed into","meaning":"需要對……作更多研究","examples":[{"en":"Some scientists say more study is needed into uranium’s toxicity.","zh":"一些科學家說需要對鈾的毒性作更多研究。"},{"en":"More study is needed into something means researchers need to investigate that topic further.","zh":"More study is needed into something 指研究人員需要進一步調查該主題。"},{"en":"More study is needed into why some students lose motivation after exams.","zh":"需要對為何一些學生考試後失去動機作更多研究。"},{"en":"If current evidence is unclear, more study is needed into the possible causes.","zh":"如果目前證據不清楚，就需要對可能原因作更多研究。"},{"en":"This phrase signals that knowledge is incomplete.","zh":"這個片語表示知識尚不完整。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":20},{"front":"reinforced by","meaning":"被……加強","examples":[{"en":"Chemical toxicity may be reinforced by weak radioactivity.","zh":"化學毒性可能被弱放射性加強。"},{"en":"Reinforced by means made stronger or more serious by another factor.","zh":"Reinforced by 指被另一因素變得更強或更嚴重。"},{"en":"A student’s anxiety may be reinforced by repeated criticism.","zh":"學生的焦慮可能被反覆批評加強。"},{"en":"If chemical damage is reinforced by radiation, the combined effect may be greater.","zh":"如果化學損害被輻射加強，綜合作用可能更大。"},{"en":"This phrase shows one factor strengthening another.","zh":"這個片語顯示一個因素加強另一個因素。"}],"source":"132 - How war debris could cause cancer.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 133":[{"front":"Museum Blockbuster","meaning":"博物館大型熱門展覽","examples":[{"en":"The passage discusses the rise of the museum blockbuster.","zh":"文章討論博物館大型熱門展覽的興起。"},{"en":"A museum blockbuster is a very popular exhibition that attracts large numbers of visitors.","zh":"博物館大型熱門展覽是吸引大量訪客的非常受歡迎展覽。"},{"en":"A city museum may create a museum blockbuster by showing rare dinosaur fossils.","zh":"城市博物館可能透過展出罕見恐龍化石來創造大型熱門展覽。"},{"en":"A museum blockbuster can increase ticket sales, media attention, and public interest.","zh":"博物館大型熱門展覽可以增加門票收入、媒體關注和公眾興趣。"},{"en":"An exhibition is not a museum blockbuster unless the public response is very strong.","zh":"除非公眾反應非常熱烈，否則一個展覽不能算是博物館大型熱門展覽。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":1},{"front":"since the 1980s","meaning":"自八十年代以來","examples":[{"en":"Since the 1980s, the term “blockbuster” has become fashionable.","zh":"自八十年代以來，“blockbuster” 這個詞變得流行。"},{"en":"Since the 1980s means from the 1980s until now or until the time being discussed.","zh":"since the 1980s 指從八十年代開始直到現在或所討論的時間。"},{"en":"Since the 1980s, computers have become common in schools and offices.","zh":"自八十年代以來，電腦在學校和辦公室變得普遍。"},{"en":"Since the 1980s, museums have used more marketing to attract visitors.","zh":"自八十年代以來，博物館使用更多市場推廣來吸引訪客。"},{"en":"This phrase shows a change that began in the past and continued later.","zh":"這個短語表示一個變化從過去開始，並在後來持續。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":1},{"front":"become fashionable","meaning":"變得流行","examples":[{"en":"The term “blockbuster” has become fashionable for spectacular exhibitions.","zh":"“blockbuster” 這個詞用於壯觀的大型展覽時變得流行。"},{"en":"To become fashionable means to become popular or commonly accepted.","zh":"become fashionable 指變得受歡迎或被普遍接受。"},{"en":"Online learning became fashionable when many students had to study from home.","zh":"當許多學生需要在家學習時，網上學習變得流行。"},{"en":"A word can become fashionable when newspapers and professionals use it often.","zh":"當報章和專業人士經常使用一個詞，它就可能變得流行。"},{"en":"Something fashionable is not always new, but many people begin to like or use it.","zh":"流行的事物不一定是新的，但很多人開始喜歡或使用它。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":1},{"front":"spectacular exhibitions","meaning":"壯觀的大型展覽","examples":[{"en":"Museums and galleries often stage spectacular exhibitions.","zh":"博物館和藝術館經常舉辦壯觀的大型展覽。"},{"en":"Spectacular exhibitions are impressive shows that are large, exciting, or visually powerful.","zh":"spectacular exhibitions 指大型、精彩或視覺效果強烈的震撼展覽。"},{"en":"A science centre may hold spectacular exhibitions with robots, lights, and live demonstrations.","zh":"科學中心可能舉辦有機械人、燈光和現場示範的壯觀大型展覽。"},{"en":"Spectacular exhibitions can attract families who do not usually visit museums.","zh":"壯觀的大型展覽可以吸引平時不常參觀博物館的家庭。"},{"en":"The word “spectacular” suggests that visitors expect something memorable.","zh":"spectacular 這個詞表示訪客期待一些令人難忘的東西。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":1},{"front":"art galleries","meaning":"藝術館","examples":[{"en":"Art galleries sometimes host blockbuster exhibitions.","zh":"藝術館有時會舉辦大型熱門展覽。"},{"en":"Art galleries are places where paintings, sculptures, photographs, or other artworks are shown.","zh":"藝術館是展出繪畫、雕塑、攝影或其他藝術品的地方。"},{"en":"Students may visit art galleries to learn how artists use colour and shape.","zh":"學生可能參觀藝術館，學習藝術家如何使用顏色和形狀。"},{"en":"Art galleries can attract more visitors when they show famous works from overseas.","zh":"當藝術館展出來自海外的著名作品時，可以吸引更多訪客。"},{"en":"Unlike shops, art galleries usually focus on viewing and understanding art.","zh":"與商店不同，藝術館通常著重觀賞和理解藝術。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":1},{"front":"science centres","meaning":"科學中心","examples":[{"en":"Science centres may also stage blockbuster exhibitions.","zh":"科學中心也可能舉辦大型熱門展覽。"},{"en":"Science centres are places where people learn science through displays, experiments, and activities.","zh":"科學中心是讓人透過展示、實驗和活動學習科學的地方。"},{"en":"Children may visit science centres to try hands-on experiments about electricity or space.","zh":"孩子可能參觀科學中心，嘗試關於電力或太空的互動實驗。"},{"en":"Science centres can make difficult ideas easier by letting visitors touch and test things.","zh":"科學中心讓訪客觸摸和測試事物，使困難概念變得較易理解。"},{"en":"A science centre is educational, but it may also use exciting displays to attract crowds.","zh":"科學中心具有教育性，但也可能利用精彩展示吸引人群。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":1},{"front":"have the ability to","meaning":"有能力……","examples":[{"en":"These exhibitions have the ability to attract large crowds.","zh":"這些展覽有能力吸引大量人群。"},{"en":"To have the ability to do something means to be able to do it.","zh":"have the ability to do something 指能夠做某事。"},{"en":"A clear poster has the ability to make people notice an event quickly.","zh":"清楚的海報有能力令人在短時間內注意到活動。"},{"en":"Good public transport has the ability to bring more visitors to a museum.","zh":"良好的公共交通有能力把更多訪客帶到博物館。"},{"en":"This phrase focuses on what something can successfully do.","zh":"這個短語著重某事物能成功做到甚麼。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":1},{"front":"attract large crowds","meaning":"吸引大量人群","examples":[{"en":"Blockbuster exhibitions can attract large crowds.","zh":"大型熱門展覽可以吸引大量人群。"},{"en":"To attract large crowds means to bring many people to a place or event.","zh":"attract large crowds 指吸引很多人到某個地方或活動。"},{"en":"A food festival can attract large crowds if famous restaurants take part.","zh":"如果著名餐廳參與，美食節可以吸引大量人群。"},{"en":"Large crowds can increase income but also create queues and pressure on staff.","zh":"大量人群可以增加收入，但也會造成排隊和員工壓力。"},{"en":"This phrase is often used for concerts, exhibitions, markets, and public events.","zh":"這個短語常用於音樂會、展覽、市集和公共活動。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":1},{"front":"corporate sponsors","meaning":"企業贊助商","examples":[{"en":"Large exhibitions often attract corporate sponsors.","zh":"大型展覽經常吸引企業贊助商。"},{"en":"Corporate sponsors are companies that give money or support to an event in return for publicity.","zh":"企業贊助商是提供金錢或支援給活動、以換取宣傳的公司。"},{"en":"A bank may become a corporate sponsor of a museum exhibition to improve its public image.","zh":"銀行可能成為博物館展覽的企業贊助商，以改善公眾形象。"},{"en":"Corporate sponsors can help pay high exhibition costs.","zh":"企業贊助商可以幫助支付高昂展覽成本。"},{"en":"However, museums must make sure corporate sponsors do not control the educational message.","zh":"然而，博物館必須確保企業贊助商不會控制教育訊息。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":1},{"front":"existing definition","meaning":"現有定義","examples":[{"en":"One existing definition of a blockbuster was offered by Elsen.","zh":"Elsen 提出了一個關於大型熱門展覽的現有定義。"},{"en":"An existing definition is an explanation that already exists before a new one is given.","zh":"existing definition 指在新定義出現之前已經存在的解釋。"},{"en":"A teacher may show an existing definition before asking students to write their own.","zh":"老師可能先展示現有定義，再要求學生寫出自己的定義。"},{"en":"Existing definitions can help people begin a discussion with shared meaning.","zh":"現有定義可以幫助人們以共同意思開始討論。"},{"en":"This phrase contrasts an old or available definition with a new personal definition.","zh":"這個短語把舊有或已有的定義與新的個人定義作對比。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":1},{"front":"be offered by","meaning":"由……提出","examples":[{"en":"A definition of a blockbuster was offered by Elsen.","zh":"一個關於大型熱門展覽的定義由 Elsen 提出。"},{"en":"To be offered by someone means to be given, suggested, or provided by that person.","zh":"be offered by someone 指由某人給出、建議或提供。"},{"en":"A solution may be offered by a teacher after students make the same mistake.","zh":"當學生犯同樣錯誤後，老師可能提出解決方法。"},{"en":"Advice offered by experts can help the public understand a complex issue.","zh":"由專家提出的建議可以幫助公眾理解複雜議題。"},{"en":"In academic writing, this phrase identifies who gave an idea or explanation.","zh":"在學術寫作中，這個短語指出某個想法或解釋由誰提出。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":2},{"front":"large-scale loan exhibition","meaning":"大型借展","examples":[{"en":"A blockbuster can be a large-scale loan exhibition.","zh":"大型熱門展覽可以是一個大型借展。"},{"en":"A large-scale loan exhibition is a big exhibition made from objects borrowed from other museums or collections.","zh":"large-scale loan exhibition 指由其他博物館或收藏借來物品所組成的大型展覽。"},{"en":"A museum may hold a large-scale loan exhibition by borrowing paintings from several countries.","zh":"博物館可能透過向多個國家借畫來舉辦大型借展。"},{"en":"Such exhibitions can be expensive because objects must be insured, transported, and protected.","zh":"這類展覽可能很昂貴，因為物品必須投保、運送和保護。"},{"en":"The phrase suggests both size and borrowing.","zh":"這個短語同時表示規模大和物品是借來的。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":2},{"front":"stand in line for hours","meaning":"排隊等候數小時","examples":[{"en":"People will stand in line for hours to see a blockbuster.","zh":"人們會排隊等候數小時去看大型熱門展覽。"},{"en":"To stand in line for hours means to wait in a queue for a long time.","zh":"stand in line for hours 指在隊伍中等待很長時間。"},{"en":"Fans may stand in line for hours to buy tickets for a famous singer.","zh":"粉絲可能排隊等候數小時去買著名歌手的門票。"},{"en":"If an exhibition is very popular, visitors may stand in line for hours before entering.","zh":"如果展覽非常受歡迎，訪客可能要排隊等候數小時才可入場。"},{"en":"This phrase shows strong demand and public excitement.","zh":"這個短語顯示需求強烈和公眾興奮。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":2},{"front":"describe something as","meaning":"把……描述為","examples":[{"en":"Rosenfield described a successful blockbuster as a triumph of curatorial and marketing skills.","zh":"Rosenfield 把成功的大型熱門展覽描述為策展和市場推廣技巧的勝利。"},{"en":"To describe something as a particular thing means to say it has that quality or identity.","zh":"describe something as 某物指說某事具有該特質或身份。"},{"en":"A teacher may describe a student’s essay as clear but lacking examples.","zh":"老師可能把學生的文章描述為清晰但缺乏例子。"},{"en":"Critics describe a film as powerful when it strongly affects the audience.","zh":"當電影強烈影響觀眾時，評論者會把它描述為有力量。"},{"en":"This phrase is useful when reporting someone else’s judgement.","zh":"這個短語適合用來報告別人的判斷。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":2},{"front":"successful blockbuster exhibition","meaning":"成功的大型熱門展覽","examples":[{"en":"A successful blockbuster exhibition attracts public attention and revenue.","zh":"成功的大型熱門展覽會吸引公眾注意和收入。"},{"en":"A successful blockbuster exhibition is a major show that brings in many visitors and strong results.","zh":"successful blockbuster exhibition 指帶來大量訪客和強勁成果的大型展覽。"},{"en":"A museum may call an exhibition successful if tickets sell out for many weeks.","zh":"如果門票連續多星期售罄，博物館可能稱該展覽成功。"},{"en":"A successful blockbuster exhibition can help pay for smaller educational programmes.","zh":"成功的大型熱門展覽可以幫助支付較小型教育計劃的費用。"},{"en":"Success here usually means public popularity, not only artistic quality.","zh":"這裡的成功通常指公眾受歡迎程度，而不只是藝術質素。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":2},{"front":"a triumph of","meaning":"……的勝利；成功展現","examples":[{"en":"A successful blockbuster can be a triumph of both curatorial and marketing skills.","zh":"成功的大型熱門展覽可以是策展和市場推廣技巧的成功展現。"},{"en":"A triumph of something means a great success achieved through that ability or effort.","zh":"a triumph of something 指透過某種能力或努力取得的巨大成功。"},{"en":"A well-run school concert can be a triumph of teamwork and planning.","zh":"一場辦得好的學校音樂會可以是團隊合作和計劃的成功展現。"},{"en":"A difficult rescue may be a triumph of courage, training, and quick decisions.","zh":"一次困難救援可能是勇氣、訓練和快速決定的勝利。"},{"en":"This phrase praises the skill behind a successful result.","zh":"這個短語讚揚成功結果背後的技巧。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":2},{"front":"curatorial skills","meaning":"策展技巧","examples":[{"en":"Blockbusters require curatorial skills as well as marketing skills.","zh":"大型熱門展覽需要策展技巧，也需要市場推廣技巧。"},{"en":"Curatorial skills are the abilities needed to choose, organise, explain, and protect exhibition objects.","zh":"策展技巧是選擇、組織、解釋和保護展品所需的能力。"},{"en":"A curator uses curatorial skills when deciding which paintings should appear together.","zh":"策展人決定哪些畫作應該一起展出時，就是在運用策展技巧。"},{"en":"Strong curatorial skills help visitors understand why objects matter.","zh":"強大的策展技巧幫助訪客理解展品為何重要。"},{"en":"Without curatorial skills, an exhibition may look impressive but teach very little.","zh":"沒有策展技巧，展覽可能看起來壯觀，但教不到甚麼。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":2},{"front":"marketing skills","meaning":"市場推廣技巧","examples":[{"en":"Marketing skills are important in promoting blockbuster exhibitions.","zh":"市場推廣技巧對宣傳大型熱門展覽很重要。"},{"en":"Marketing skills are abilities used to attract people’s attention and persuade them to buy or attend.","zh":"市場推廣技巧是吸引注意並說服人購買或參與的能力。"},{"en":"A small shop uses marketing skills when it writes clear posts about new products.","zh":"小店為新產品寫清楚帖文時，就是在使用市場推廣技巧。"},{"en":"Good marketing skills can turn a quiet event into one that many people notice.","zh":"良好的市場推廣技巧可以把冷清活動變成多人注意的活動。"},{"en":"For museums, marketing skills help connect exhibitions with the public.","zh":"對博物館而言，市場推廣技巧幫助把展覽與公眾連接起來。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":2},{"front":"my own definition of","meaning":"我自己對……的定義","examples":[{"en":"The writer gives his own definition of a blockbuster.","zh":"作者給出自己對大型熱門展覽的定義。"},{"en":"My own definition of something means the way I personally explain its meaning.","zh":"my own definition of something 指我個人對某事物意思的解釋。"},{"en":"A student may give her own definition of success before writing an essay.","zh":"學生寫文章前，可能先給出自己對成功的定義。"},{"en":"Giving your own definition can make an argument clearer when a word has many meanings.","zh":"當一個詞有多重意思時，給出自己的定義可以令論點更清晰。"},{"en":"This phrase shows that the explanation belongs to the speaker or writer.","zh":"這個短語表示該解釋屬於說話者或作者。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":2},{"front":"popular, high-profile exhibition","meaning":"受歡迎而高調的展覽","examples":[{"en":"A blockbuster is a popular, high-profile exhibition.","zh":"大型熱門展覽是受歡迎而高調的展覽。"},{"en":"A popular, high-profile exhibition is a well-known show that many people want to see.","zh":"popular, high-profile exhibition 指很多人想看、而且知名度高的展覽。"},{"en":"A gallery may hold a popular, high-profile exhibition of a famous painter’s work.","zh":"藝術館可能舉辦某位著名畫家作品的受歡迎而高調的展覽。"},{"en":"Media coverage can turn an exhibition into a popular, high-profile event.","zh":"媒體報道可以把一個展覽變成受歡迎而高調的活動。"},{"en":"This phrase suggests both public interest and strong visibility.","zh":"這個短語同時表示公眾興趣和高度曝光。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":2},{"front":"on display","meaning":"正在展出","examples":[{"en":"A blockbuster is on display for a limited period.","zh":"大型熱門展覽會在有限期間內展出。"},{"en":"If something is on display, it is being shown for people to see.","zh":"如果某物 is on display，即它正在展出給人觀看。"},{"en":"The winning science projects were on display in the school hall.","zh":"得獎科學作品正在學校禮堂展出。"},{"en":"Rare objects may be on display for only a few weeks to protect them.","zh":"稀有物件可能只展出數星期，以保護它們。"},{"en":"This phrase is often used for exhibitions, shop windows, and public shows.","zh":"這個短語常用於展覽、商店櫥窗和公共展示。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":3},{"front":"for a limited period","meaning":"在有限期間內","examples":[{"en":"A blockbuster is usually on display for a limited period.","zh":"大型熱門展覽通常只在有限期間內展出。"},{"en":"For a limited period means only for a short or fixed time.","zh":"for a limited period 指只在短時間或固定時間內。"},{"en":"A shop may offer a discount for a limited period to encourage quick purchases.","zh":"商店可能在有限期間內提供折扣，以鼓勵顧客盡快購買。"},{"en":"Visitors may hurry to see an exhibition if it is open for a limited period.","zh":"如果展覽只在有限期間內開放，訪客可能會趕去觀看。"},{"en":"This phrase creates a sense that people should act before time runs out.","zh":"這個短語營造一種時間快將用完、需要行動的感覺。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":3},{"front":"the general public","meaning":"普羅大眾","examples":[{"en":"Blockbuster exhibitions attract the general public.","zh":"大型熱門展覽吸引普羅大眾。"},{"en":"The general public means ordinary people, not only experts or professionals.","zh":"the general public 指普通人，而不只是專家或專業人士。"},{"en":"A health campaign must use simple language so the general public can understand it.","zh":"健康宣傳必須使用簡單語言，讓普羅大眾能理解。"},{"en":"Museums attract the general public by offering clear labels and family activities.","zh":"博物館透過清楚標籤和家庭活動來吸引普羅大眾。"},{"en":"This phrase contrasts ordinary visitors with specialist audiences.","zh":"這個短語把普通訪客與專門觀眾作對比。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":3},{"front":"be prepared to","meaning":"願意；準備好","examples":[{"en":"The public are prepared to pay a fee to see a blockbuster.","zh":"公眾願意付費觀看大型熱門展覽。"},{"en":"To be prepared to do something means to be willing or ready to do it.","zh":"be prepared to do something 指願意或準備好做某事。"},{"en":"Parents may be prepared to travel far if a school offers strong support.","zh":"如果學校提供強大支援，家長可能願意走很遠路程。"},{"en":"People are more prepared to pay when they believe the experience is special.","zh":"當人們相信體驗很特別時，會更願意付費。"},{"en":"This phrase often shows willingness after considering the effort or cost.","zh":"這個短語常表示在考慮努力或成本後的意願。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":3},{"front":"pay a fee","meaning":"付費","examples":[{"en":"Visitors are prepared to pay a fee to attend the exhibition.","zh":"訪客願意付費參觀展覽。"},{"en":"To pay a fee means to give money in order to enter, join, or use a service.","zh":"pay a fee 指為了進入、參加或使用服務而付款。"},{"en":"Students may pay a fee to take an English exam.","zh":"學生可能要付費參加英文考試。"},{"en":"If a museum charges visitors, the money can help cover staff and maintenance costs.","zh":"如果博物館向訪客收費，這筆錢可以幫助支付員工和維修成本。"},{"en":"This phrase is used when access is not free.","zh":"這個短語用於表示入場或使用並非免費。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":3},{"front":"in order to attend","meaning":"為了參觀","examples":[{"en":"People stand in line in order to attend the exhibition.","zh":"人們為了參觀展覽而排隊。"},{"en":"In order to attend means for the purpose of going to or taking part in an event.","zh":"in order to attend 指為了前往或參加某活動。"},{"en":"Students may register early in order to attend a popular workshop.","zh":"學生可能提早報名，為了參加受歡迎的工作坊。"},{"en":"People may change their schedule in order to attend an important meeting.","zh":"人們可能改變日程，為了出席重要會議。"},{"en":"This phrase clearly shows the purpose behind an action.","zh":"這個短語清楚顯示行動背後的目的。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":3},{"front":"omit in their descriptions","meaning":"在描述中遺漏","examples":[{"en":"Elsen and Rosenfield omit some details in their descriptions.","zh":"Elsen 和 Rosenfield 在描述中遺漏了一些細節。"},{"en":"To omit something in a description means to leave it out when explaining something.","zh":"omit something in a description 指在解釋某事時漏掉某些內容。"},{"en":"A student may omit key dates in a history answer and lose marks.","zh":"學生可能在歷史答案中遺漏重要日期而失分。"},{"en":"If instructions omit safety warnings, users may misunderstand the risk.","zh":"如果指示遺漏安全警告，使用者可能誤解風險。"},{"en":"This phrase suggests that the description is incomplete.","zh":"這個短語表示描述並不完整。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":3},{"front":"apply to","meaning":"適用於","examples":[{"en":"The term “blockbuster” can apply to a movie or a museum exhibition.","zh":"“blockbuster” 這個詞可以適用於電影或博物館展覽。"},{"en":"To apply to something means to be relevant or suitable for that thing.","zh":"apply to something 指與某事相關或適合用於某事。"},{"en":"A school rule may apply to both students and teachers.","zh":"學校規則可能同時適用於學生和老師。"},{"en":"The same safety advice can apply to buses, trains, and crowded streets.","zh":"同一安全建議可以適用於巴士、火車和擁擠街道。"},{"en":"This phrase helps show where a word, rule, or idea can be used.","zh":"這個短語幫助顯示一個詞、規則或概念可以用在哪裡。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":3},{"front":"just as easily","meaning":"同樣容易地","examples":[{"en":"The word can just as easily apply to a movie.","zh":"這個詞同樣容易地適用於電影。"},{"en":"Just as easily means with the same ease or in the same natural way.","zh":"just as easily 指同樣輕易或同樣自然地。"},{"en":"A phone can just as easily be used for studying as for entertainment.","zh":"手機可以同樣容易地用於學習和娛樂。"},{"en":"A clear example can just as easily teach adults as children.","zh":"清楚例子可以同樣容易地教成人和兒童。"},{"en":"This phrase shows that another use is equally possible.","zh":"這個短語表示另一種用法同樣可能。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":3},{"front":"merely naming something","meaning":"只是把……命名為","examples":[{"en":"Merely naming an exhibition a blockbuster does not make it one.","zh":"只是把展覽命名為大型熱門展覽，並不會令它成為真正的大型熱門展覽。"},{"en":"Merely naming something means only giving it a name, without proving it is true.","zh":"merely naming something 指只是給某事物一個名稱，而沒有證明它是真的。"},{"en":"Merely naming a room a library does not help if it has no books.","zh":"只是把一個房間命名為圖書館，如果沒有書也沒有用。"},{"en":"A company does not become green by merely naming itself environmentally friendly.","zh":"公司不會只是把自己命名為環保企業就變得環保。"},{"en":"This phrase warns that a label alone is not enough.","zh":"這個短語提醒我們，標籤本身並不足夠。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":3},{"front":"the item in question","meaning":"所指的項目","examples":[{"en":"The term can apply only when the item in question is highly successful.","zh":"只有當所指的項目非常成功時，這個詞才適用。"},{"en":"The item in question means the particular thing being discussed.","zh":"the item in question 指正在被討論的特定事物。"},{"en":"If a phone is damaged, the item in question should be checked before a refund is given.","zh":"如果手機損壞，所指的項目應先被檢查，才可退款。"},{"en":"In a museum debate, the item in question may be an exhibition, object, or policy.","zh":"在博物館爭議中，所指的項目可能是展覽、物件或政策。"},{"en":"This phrase helps focus attention on the exact thing being considered.","zh":"這個短語幫助把注意力集中在正在考慮的確切事物上。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":4},{"front":"overwhelmingly successful response","meaning":"壓倒性的成功反應","examples":[{"en":"A true blockbuster receives an overwhelmingly successful response from the public.","zh":"真正的大型熱門展覽會得到公眾壓倒性的成功反應。"},{"en":"An overwhelmingly successful response is a reaction that is extremely positive and much stronger than expected.","zh":"overwhelmingly successful response 指極度正面、遠超預期的反應。"},{"en":"A school concert may receive an overwhelmingly successful response if every ticket sells out.","zh":"如果學校音樂會每張票都售罄，它可能得到壓倒性的成功反應。"},{"en":"Such a response can encourage organisers to repeat or expand an event.","zh":"這種反應可以鼓勵主辦者重辦或擴大活動。"},{"en":"This phrase suggests success that is too strong to ignore.","zh":"這個短語表示成功強烈得不能忽視。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":4},{"front":"literature from","meaning":"來自……的文獻","examples":[{"en":"The term appears in literature from both the UK and the USA.","zh":"這個詞出現在來自英國和美國的文獻中。"},{"en":"Literature from a place means written sources, studies, or discussions produced there.","zh":"literature from 某地指由該地產生的書面資料、研究或討論。"},{"en":"A researcher may compare literature from Hong Kong and Singapore on education policy.","zh":"研究者可能比較來自香港和新加坡關於教育政策的文獻。"},{"en":"Literature from different countries can show how the same idea is understood differently.","zh":"來自不同國家的文獻可以顯示同一概念如何被不同理解。"},{"en":"This phrase usually refers to written academic or professional material.","zh":"這個短語通常指學術或專業書面材料。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":4},{"front":"appear in descriptions of","meaning":"出現在對……的描述中","examples":[{"en":"Several words appear in descriptions of blockbusters.","zh":"幾個詞出現在對大型熱門展覽的描述中。"},{"en":"To appear in descriptions of something means to be used when people explain or discuss it.","zh":"appear in descriptions of something 指在人們解釋或討論某事時被使用。"},{"en":"Words like “safe” and “clean” often appear in descriptions of good housing.","zh":"“安全”和“乾淨”等詞常出現在對良好住屋的描述中。"},{"en":"If the same words appear in many descriptions, they may show common attitudes.","zh":"如果相同詞語出現在許多描述中，它們可能顯示共同態度。"},{"en":"This phrase helps identify repeated language around a topic.","zh":"這個短語幫助辨認圍繞某主題的重複語言。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":4},{"front":"less scholarly","meaning":"較欠學術性的","examples":[{"en":"Some critics describe blockbusters as less scholarly.","zh":"有些批評者把大型熱門展覽描述為較欠學術性。"},{"en":"Less scholarly means less focused on serious academic study or expert knowledge.","zh":"less scholarly 指較少著重嚴肅學術研究或專家知識。"},{"en":"A museum label may seem less scholarly if it avoids technical terms for younger visitors.","zh":"如果博物館標籤為年輕訪客避免使用技術詞，可能顯得較欠學術性。"},{"en":"Making an exhibition less scholarly can attract more people but may worry experts.","zh":"令展覽較欠學術性可以吸引更多人，但可能令專家擔心。"},{"en":"This phrase often suggests a trade-off between accessibility and academic depth.","zh":"這個短語常表示易懂程度和學術深度之間的取捨。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":4},{"front":"non-elitist","meaning":"非精英化的","examples":[{"en":"Some people describe blockbusters as non-elitist.","zh":"有些人把大型熱門展覽描述為非精英化的。"},{"en":"Non-elitist means not limited to educated, wealthy, or high-status groups.","zh":"non-elitist 指不限於受過高等教育、有錢或高地位群體。"},{"en":"A non-elitist museum programme uses simple language so everyone can join.","zh":"非精英化的博物館活動使用簡單語言，讓所有人都能參與。"},{"en":"Non-elitist activities can make cultural spaces feel less intimidating.","zh":"非精英化活動可以令文化空間感覺較不嚇人。"},{"en":"This word suggests openness to ordinary people.","zh":"這個詞表示對普通人開放。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":4},{"front":"populist","meaning":"迎合大眾的","examples":[{"en":"Blockbusters are sometimes described as populist.","zh":"大型熱門展覽有時被描述為迎合大眾的。"},{"en":"Populist means designed to please or appeal to ordinary people rather than experts.","zh":"populist 指設計上迎合普通人，而不是專家。"},{"en":"A populist exhibition may use famous objects, simple stories, and dramatic displays.","zh":"迎合大眾的展覽可能使用著名物件、簡單故事和戲劇化展示。"},{"en":"Populist choices can increase visitors but may be criticised as too simple.","zh":"迎合大眾的選擇可以增加訪客，但也可能被批評過於簡單。"},{"en":"This word can be positive or negative, depending on the speaker’s attitude.","zh":"這個詞可以是正面或負面，取決於說話者態度。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":4},{"front":"detractors","meaning":"批評者","examples":[{"en":"Detractors argue that blockbusters appeal to the lowest common denominator.","zh":"批評者認為大型熱門展覽迎合最低層次的大眾口味。"},{"en":"Detractors are people who criticise something or point out its weaknesses.","zh":"detractors 指批評某事或指出其弱點的人。"},{"en":"Detractors of online learning say students may lose focus at home.","zh":"網上學習的批評者說學生在家可能會失去專注。"},{"en":"Detractors can force organisers to explain why their decisions are still valuable.","zh":"批評者可以迫使主辦者解釋為何其決定仍有價值。"},{"en":"This word usually refers to critics, not neutral observers.","zh":"這個詞通常指批評者，而不是中立觀察者。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":4},{"front":"appeal to","meaning":"吸引；迎合","examples":[{"en":"Blockbusters are designed to appeal to a broad public audience.","zh":"大型熱門展覽設計上是為了吸引廣泛公眾觀眾。"},{"en":"To appeal to people means to attract, interest, or please them.","zh":"appeal to people 指吸引、引起興趣或討好某些人。"},{"en":"A café may appeal to students by offering cheap lunch sets and free Wi-Fi.","zh":"咖啡店可能透過便宜午餐和免費 Wi-Fi 吸引學生。"},{"en":"Exhibitions appeal to families when they include clear explanations and child-friendly activities.","zh":"當展覽有清楚解釋和適合兒童的活動時，就能吸引家庭。"},{"en":"This phrase focuses on what makes people want something.","zh":"這個短語著重甚麼令 人們想要某事物。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":4},{"front":"the lowest common denominator","meaning":"最低層次的大眾口味","examples":[{"en":"Critics say blockbusters appeal to the lowest common denominator.","zh":"批評者說大型熱門展覽迎合最低層次的大眾口味。"},{"en":"The lowest common denominator means the simplest taste or interest shared by the largest number of people.","zh":"the lowest common denominator 指最多人共有的最簡單口味或興趣。"},{"en":"A TV show may aim at the lowest common denominator by using only jokes everyone can understand.","zh":"電視節目如果只使用人人都懂的笑話，可能是在迎合最低層次的大眾口味。"},{"en":"Appealing to the lowest common denominator can increase popularity but reduce depth.","zh":"迎合最低層次的大眾口味可以增加受歡迎程度，但會降低深度。"},{"en":"This phrase is often critical and suggests something has been made too simple.","zh":"這個短語通常帶批評意味，表示某事被做得過於簡單。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":4},{"front":"extol the virtues of","meaning":"頌揚……的好處","examples":[{"en":"Others extol the virtues of encouraging cooperation among scholars.","zh":"其他人頌揚鼓勵學者合作的好處。"},{"en":"To extol the virtues of something means to strongly praise its benefits.","zh":"extol the virtues of something 指高度讚揚某事的好處。"},{"en":"A doctor may extol the virtues of regular sleep and exercise.","zh":"醫生可能頌揚規律睡眠和運動的好處。"},{"en":"Supporters extol the virtues of public libraries because they give everyone access to knowledge.","zh":"支持者頌揚公共圖書館的好處，因為它們讓所有人接觸知識。"},{"en":"This phrase is more formal than simply saying “praise”.","zh":"這個短語比 simply saying “praise” 更正式。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":5},{"front":"encourage scholars to cooperate","meaning":"鼓勵學者合作","examples":[{"en":"Blockbusters may encourage scholars to cooperate on projects.","zh":"大型熱門展覽可能鼓勵學者在項目上合作。"},{"en":"To encourage scholars to cooperate means to push researchers or experts to work together.","zh":"encourage scholars to cooperate 指推動研究者或專家一起工作。"},{"en":"A university conference can encourage scholars to cooperate by bringing them into the same room.","zh":"大學會議可以透過把學者聚在同一地方來鼓勵學者合作。"},{"en":"Cooperation helps scholars share objects, research, and specialist knowledge.","zh":"合作幫助學者分享物件、研究和專門知識。"},{"en":"This phrase suggests that big projects may require teamwork across institutions.","zh":"這個短語表示大型項目可能需要跨機構團隊合作。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":5},{"front":"cooperate on projects","meaning":"在項目上合作","examples":[{"en":"Scholars may cooperate on major exhibition projects.","zh":"學者可能在大型展覽項目上合作。"},{"en":"To cooperate on projects means to work together on planned tasks or activities.","zh":"cooperate on projects 指在有計劃的任務或活動上一起工作。"},{"en":"Teachers may cooperate on projects to design better lesson materials.","zh":"老師可能在項目上合作，以設計更好的教材。"},{"en":"When people cooperate on projects, they can share skills and reduce repeated work.","zh":"當人們在項目上合作時，可以分享技能並減少重複工作。"},{"en":"This phrase is useful for teamwork in schools, companies, and research.","zh":"這個短語適用於學校、公司和研究中的團隊合作。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":5},{"front":"cater for","meaning":"迎合；照顧……需要","examples":[{"en":"Some exhibitions cater for a broad selection of the community.","zh":"有些展覽照顧社群中廣泛不同人士的需要。"},{"en":"To cater for people means to provide what they need or enjoy.","zh":"cater for people 指提供人們需要或喜歡的東西。"},{"en":"A school canteen should cater for students who cannot eat certain foods.","zh":"學校食堂應照顧不能吃某些食物的學生需要。"},{"en":"Museums cater for families by offering simple labels, lifts, and child activities.","zh":"博物館透過簡單標籤、升降機和兒童活動照顧家庭需要。"},{"en":"This phrase focuses on serving different needs.","zh":"這個短語著重服務不同需要。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":5},{"front":"a broad selection of","meaning":"廣泛不同類型的……","examples":[{"en":"Blockbusters cater for a broad selection of the community.","zh":"大型熱門展覽迎合社群中廣泛不同類型的人。"},{"en":"A broad selection of people or things means many different types of them.","zh":"a broad selection of people or things 指許多不同類型的人或物。"},{"en":"A library should offer a broad selection of books for children, adults, and language learners.","zh":"圖書館應提供廣泛不同類型的書給兒童、成人和語言學習者。"},{"en":"A broad selection of activities can make a community event more inclusive.","zh":"廣泛不同類型的活動可以令社區活動更具包容性。"},{"en":"This phrase suggests variety, not just a large number.","zh":"這個短語表示種類多，而不只是數量多。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":5},{"front":"the community","meaning":"社群；社區","examples":[{"en":"Museums try to serve a broad selection of the community.","zh":"博物館嘗試服務社群中廣泛不同的人。"},{"en":"The community means the people living in or connected to a particular place or group.","zh":"the community 指生活在或連繫於某地方或群體的人。"},{"en":"A school is part of the community because it serves local families.","zh":"學校是社區的一部分，因為它服務本地家庭。"},{"en":"When museums listen to the community, their programmes become more relevant.","zh":"當博物館聆聽社群意見，它們的活動會變得更相關。"},{"en":"This phrase often refers to ordinary local people, not only officials or experts.","zh":"這個短語常指普通本地人，而不只是官員或專家。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":5},{"front":"rather than an elite sector","meaning":"而不是精英階層","examples":[{"en":"Supporters want exhibitions for the whole community rather than an elite sector.","zh":"支持者希望展覽服務整個社群，而不是精英階層。"},{"en":"Rather than an elite sector means instead of only a small high-status group.","zh":"rather than an elite sector 指而不是只服務小部分高地位群體。"},{"en":"Public parks should serve ordinary residents rather than an elite sector.","zh":"公園應服務普通居民，而不是精英階層。"},{"en":"If museums use simple explanations, they can welcome families rather than an elite sector only.","zh":"如果博物館使用簡單解釋，就可以歡迎家庭，而不是只服務精英階層。"},{"en":"This phrase clearly contrasts broad access with exclusiveness.","zh":"這個短語清楚對比廣泛開放和排他性。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":5},{"front":"elite sector","meaning":"精英階層","examples":[{"en":"Traditional exhibitions may appeal mainly to an elite sector.","zh":"傳統展覽可能主要吸引精英階層。"},{"en":"An elite sector is a small group with high education, status, wealth, or specialist knowledge.","zh":"elite sector 指具有高教育、高地位、財富或專門知識的小群體。"},{"en":"A lecture full of technical terms may attract only an elite sector.","zh":"一場充滿技術詞的講座可能只吸引精英階層。"},{"en":"If cultural institutions serve only an elite sector, many people may feel excluded.","zh":"如果文化機構只服務精英階層，許多人可能會感到被排除。"},{"en":"This phrase is often used when discussing access and inequality.","zh":"這個短語常用於討論參與機會和不平等。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":5},{"front":"maintaining and increasing visitor levels","meaning":"維持並增加訪客人數","examples":[{"en":"Maintaining and increasing visitor levels is important in the new museology.","zh":"在新博物館學中，維持並增加訪客人數十分重要。"},{"en":"Maintaining and increasing visitor levels means keeping current visitors and attracting more.","zh":"maintaining and increasing visitor levels 指保留現有訪客並吸引更多訪客。"},{"en":"A museum may offer family days to maintain and increase visitor levels.","zh":"博物館可能舉辦家庭日，以維持並增加訪客人數。"},{"en":"If visitor levels fall, income and public support may also decline.","zh":"如果訪客人數下降，收入和公眾支持也可能下降。"},{"en":"This phrase treats visitor numbers as something museums must actively manage.","zh":"這個短語把訪客人數視為博物館需要主動管理的事。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":5},{"front":"visitor levels","meaning":"訪客人數","examples":[{"en":"Museums need to maintain visitor levels.","zh":"博物館需要維持訪客人數。"},{"en":"Visitor levels are the number of people who come to a place over a period of time.","zh":"visitor levels 指某段時間內前來某地的人數。"},{"en":"A zoo may check visitor levels every month to plan staff shifts.","zh":"動物園可能每月檢查訪客人數，以安排員工更表。"},{"en":"Low visitor levels can make it harder to pay for exhibitions and services.","zh":"低訪客人數可能令支付展覽和服務費用變得更困難。"},{"en":"This phrase is more formal than simply saying “visitor numbers”.","zh":"這個短語比直接說 “visitor numbers” 更正式。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":5},{"front":"paramount","meaning":"至為重要的","examples":[{"en":"Maintaining visitor levels is paramount in the new museology.","zh":"在新博物館學中，維持訪客人數至為重要。"},{"en":"Paramount means more important than almost everything else.","zh":"paramount 指比幾乎所有其他事情都重要。"},{"en":"In a hospital, patient safety is paramount.","zh":"在醫院中，病人安全至為重要。"},{"en":"If money is limited, schools may decide that basic teaching is paramount.","zh":"如果資金有限，學校可能認為基本教學至為重要。"},{"en":"This word shows that something is treated as the top priority.","zh":"這個詞表示某事被視為最高優先事項。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":6},{"front":"new museology","meaning":"新博物館學","examples":[{"en":"The new museology emphasises visitors, markets and public appeal.","zh":"新博物館學強調訪客、市場和公眾吸引力。"},{"en":"New museology is a way of thinking about museums that focuses more on audiences, access, and public value.","zh":"new museology 是一種更著重觀眾、開放性和公共價值的博物館思維。"},{"en":"Under new museology, museums may design exhibitions for families, tourists, and local residents.","zh":"在新博物館學下，博物館可能為家庭、遊客和本地居民設計展覽。"},{"en":"This approach can make museums more open but also more commercial.","zh":"這種取向可以令博物館更開放，但也更商業化。"},{"en":"The phrase shows a shift from object-centred museums to visitor-centred museums.","zh":"這個短語顯示博物館由以物件為中心轉向以訪客為中心。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":6},{"front":"continued product development","meaning":"持續產品開發","examples":[{"en":"Museums now require continued product development.","zh":"博物館現在需要持續產品開發。"},{"en":"Continued product development means regularly improving or creating things that audiences can experience or buy.","zh":"continued product development 指定期改進或創造觀眾可以體驗或購買的東西。"},{"en":"A museum may use continued product development to create new tours, workshops, and gift-shop items.","zh":"博物館可能透過持續產品開發創造新導賞、工作坊和禮品店商品。"},{"en":"Without continued product development, visitors may feel there is nothing new to see.","zh":"沒有持續產品開發，訪客可能覺得沒有新東西可看。"},{"en":"This business phrase treats exhibitions and services like products.","zh":"這個商業短語把展覽和服務視為產品。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":6},{"front":"creation or hiring of","meaning":"創作或租用","examples":[{"en":"Museums rely on the creation or hiring of blockbuster exhibitions.","zh":"博物館依靠創作或租用大型熱門展覽。"},{"en":"The creation or hiring of something means making it yourself or bringing it in from elsewhere.","zh":"creation or hiring of something 指自己製作某物，或從其他地方租用引入。"},{"en":"A school event may involve the creation or hiring of stage decorations.","zh":"學校活動可能涉及創作或租用舞台裝飾。"},{"en":"Museums may create their own exhibition or hire a travelling one to save preparation time.","zh":"博物館可能自行創作展覽，或租用巡迴展覽以節省準備時間。"},{"en":"This phrase shows two possible ways to obtain something.","zh":"這個短語顯示取得某物的兩種可能方法。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":6},{"front":"regular exhibition changes","meaning":"定期更換展覽","examples":[{"en":"Museums need regular exhibition changes to keep visitors interested.","zh":"博物館需要定期更換展覽，以保持訪客興趣。"},{"en":"Regular exhibition changes are repeated updates to what is shown in a museum or gallery.","zh":"regular exhibition changes 指博物館或藝術館反覆更新展出內容。"},{"en":"A small museum may change one room every season to create regular exhibition changes.","zh":"小型博物館可能每季更換一個展廳，以做到定期更換展覽。"},{"en":"Regular exhibition changes give people a reason to return.","zh":"定期更換展覽給人們再次到訪的理由。"},{"en":"Without them, visitors may think they have already seen everything.","zh":"沒有定期更換展覽，訪客可能以為所有東西都已看過。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":6},{"front":"innovations","meaning":"創新","examples":[{"en":"Regular exhibition changes and innovations are needed.","zh":"定期更換展覽和創新都是需要的。"},{"en":"Innovations are new ideas, methods, or products that improve how something works.","zh":"innovations 指改善某事運作的新想法、方法或產品。"},{"en":"A museum innovation may be an audio guide that lets visitors choose their own route.","zh":"博物館創新可能是讓訪客自行選路線的語音導覽。"},{"en":"Innovations can make old subjects feel fresh and easier to understand.","zh":"創新可以令舊題材感覺新鮮，並更容易理解。"},{"en":"This word suggests useful newness, not change for no reason.","zh":"這個詞表示有用的新意，而不是無原因的改變。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":6},{"front":"visiting public","meaning":"參觀公眾","examples":[{"en":"The visiting public have become customers rather than visitors.","zh":"參觀公眾已由訪客變成顧客。"},{"en":"The visiting public means ordinary people who come to visit a place such as a museum.","zh":"visiting public 指前來參觀博物館等地方的普通人。"},{"en":"A museum must consider the needs of the visiting public when planning signs and facilities.","zh":"博物館規劃標示和設施時，必須考慮參觀公眾的需要。"},{"en":"If the visiting public cannot understand the display, the exhibition may fail educationally.","zh":"如果參觀公眾無法理解展示，展覽在教育上可能失敗。"},{"en":"This phrase focuses on visitors as a group.","zh":"這個短語把訪客視為一個群體。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":6},{"front":"become customers rather than visitors","meaning":"由訪客變成顧客","examples":[{"en":"Museum visitors have become customers rather than visitors.","zh":"博物館訪客已由訪客變成顧客。"},{"en":"To become customers rather than visitors means to be treated as paying consumers, not just guests.","zh":"become customers rather than visitors 指被視為付費消費者，而不只是來賓。"},{"en":"When museums sell tickets, cafés, and souvenirs, visitors may become customers rather than visitors.","zh":"當博物館售賣門票、咖啡和紀念品時，訪客可能由訪客變成顧客。"},{"en":"This change can make museums focus more on satisfaction, service, and spending.","zh":"這種變化可以令博物館更注重滿意度、服務和消費。"},{"en":"The phrase contrasts cultural attendance with commercial consumption.","zh":"這個短語把文化參與與商業消費作對比。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":6},{"front":"valued in museums","meaning":"在博物館中受重視","examples":[{"en":"Different skills are now valued in museums and galleries.","zh":"不同技巧現在在博物館和藝術館中受重視。"},{"en":"Skills valued in museums are abilities that museums now consider important.","zh":"valued in museums 的技巧指博物館現在認為重要的能力。"},{"en":"Communication skills are valued in museums because staff must explain objects clearly.","zh":"溝通技巧在博物館中受重視，因為職員必須清楚解釋物件。"},{"en":"When visitor numbers matter, marketing and business skills become more valued in museums.","zh":"當訪客人數變得重要，市場推廣和商業技巧在博物館中更受重視。"},{"en":"This phrase shows changing priorities inside cultural institutions.","zh":"這個短語顯示文化機構內部優先事項正在改變。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":6},{"front":"keep customers coming through the door","meaning":"令顧客不斷上門","examples":[{"en":"Museums need new skills to keep customers coming through the door.","zh":"博物館需要新技巧，令顧客不斷上門。"},{"en":"To keep customers coming through the door means to keep attracting people to visit or buy.","zh":"keep customers coming through the door 指持續吸引人來參觀或消費。"},{"en":"A café uses friendly service and fresh food to keep customers coming through the door.","zh":"咖啡店用友善服務和新鮮食物令顧客不斷上門。"},{"en":"Museums may use new exhibitions and events to keep customers coming through the door.","zh":"博物館可能用新展覽和活動令顧客不斷上門。"},{"en":"This phrase is informal and strongly connected to business survival.","zh":"這個短語較口語，並與商業生存密切相關。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":6},{"front":"high on the list of requirements","meaning":"在要求清單上名列前茅","examples":[{"en":"Marketing skills are high on the list of requirements.","zh":"市場推廣技巧在要求清單上名列前茅。"},{"en":"If something is high on the list of requirements, it is one of the most important things needed.","zh":"high on the list of requirements 指在眾多需要中屬於最重要的一項。"},{"en":"For a nurse, patience and careful attention are high on the list of requirements.","zh":"對護士而言，耐性和細心在要求清單上名列前茅。"},{"en":"When museums compete for visitors, marketing becomes high on the list of requirements.","zh":"當博物館爭奪訪客時，市場推廣就在要求清單上名列前茅。"},{"en":"This phrase shows priority among many needs.","zh":"這個短語顯示眾多需要中的優先次序。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":7},{"front":"commercial skills","meaning":"商業技巧","examples":[{"en":"Commercial skills are now valued in museums.","zh":"商業技巧現在在博物館中受重視。"},{"en":"Commercial skills are abilities related to selling, income, customers, and financial decisions.","zh":"commercial skills 指與銷售、收入、顧客和財務決策有關的能力。"},{"en":"A theatre manager needs commercial skills to price tickets and attract audiences.","zh":"劇院經理需要商業技巧來定票價和吸引觀眾。"},{"en":"Museums use commercial skills when they plan shops, cafés, memberships, and ticket offers.","zh":"博物館規劃商店、咖啡店、會員和門票優惠時會使用商業技巧。"},{"en":"This phrase shows that cultural work can also require business thinking.","zh":"這個短語顯示文化工作也可能需要商業思維。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":7},{"front":"business skills","meaning":"商業能力","examples":[{"en":"Business skills are important for modern museum directors.","zh":"商業能力對現代博物館總監很重要。"},{"en":"Business skills are abilities used to manage money, staff, customers, and organisational growth.","zh":"business skills 指管理金錢、員工、顧客和機構發展的能力。"},{"en":"A school principal may need business skills when managing budgets and contracts.","zh":"校長管理預算和合約時，可能需要商業能力。"},{"en":"Good business skills can help museums survive when public funding is limited.","zh":"良好的商業能力可以幫助博物館在公共資金有限時生存。"},{"en":"This phrase is broader than selling; it includes management and planning.","zh":"這個短語不只關乎銷售，也包括管理和規劃。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":7},{"front":"entrepreneurial skills","meaning":"企業家精神；創業能力","examples":[{"en":"Museums increasingly value entrepreneurial skills.","zh":"博物館越來越重視企業家精神。"},{"en":"Entrepreneurial skills are abilities to spot opportunities, take risks, and create new projects.","zh":"entrepreneurial skills 指發現機會、承擔風險和創造新項目的能力。"},{"en":"A community leader uses entrepreneurial skills when turning an empty shop into a learning centre.","zh":"社區領袖把空置店舖改成學習中心時，就是在使用創業能力。"},{"en":"Museums need entrepreneurial skills to design new services and find new income.","zh":"博物館需要企業家精神來設計新服務和尋找新收入。"},{"en":"This phrase suggests initiative, creativity, and practical action.","zh":"這個短語表示主動性、創意和實際行動。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":7},{"front":"curators","meaning":"策展人","examples":[{"en":"Curators are now often expected to act as administrators.","zh":"策展人現在經常被期望擔任行政管理人員。"},{"en":"Curators are museum or gallery professionals who choose, study, organise, and explain collections.","zh":"curators 指選擇、研究、組織和解釋館藏的博物館或藝術館專業人員。"},{"en":"A curator may decide which objects should appear in an exhibition about ancient trade.","zh":"策展人可能決定哪些物件應出現在古代貿易展覽中。"},{"en":"Curators need research skills, but they may also need management and communication skills.","zh":"策展人需要研究技巧，但也可能需要管理和溝通技巧。"},{"en":"This word refers to cultural experts who shape how collections are presented.","zh":"這個詞指塑造館藏呈現方式的文化專家。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":7},{"front":"administrators","meaning":"行政管理人員","examples":[{"en":"Curators are now administrators as well as cultural experts.","zh":"策展人現在既是文化專家，也是行政管理人員。"},{"en":"Administrators are people who organise practical work, paperwork, budgets, and daily operations.","zh":"administrators 指負責組織實際工作、文件、預算和日常運作的人。"},{"en":"School administrators arrange timetables, records, meetings, and parent notices.","zh":"學校行政管理人員安排時間表、紀錄、會議和家長通告。"},{"en":"Museum administrators help exhibitions run smoothly behind the scenes.","zh":"博物館行政管理人員在幕後幫助展覽順利運作。"},{"en":"This word focuses on management work rather than specialist research.","zh":"這個詞著重管理工作，而不是專門研究。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":7},{"front":"no longer requires","meaning":"不再需要","examples":[{"en":"Being a gallery director no longer requires an arts degree.","zh":"成為藝術館總監不再需要藝術學位。"},{"en":"No longer requires means something was needed before but is not needed now.","zh":"no longer requires 指某事以前需要，但現在不需要。"},{"en":"Some jobs no longer require handwritten forms because applications are online.","zh":"有些工作不再需要手寫表格，因為申請已轉到網上。"},{"en":"If a museum values business skills, leadership may no longer require only art training.","zh":"如果博物館重視商業技巧，領導職位可能不再只需要藝術訓練。"},{"en":"This phrase shows that expectations have changed.","zh":"這個短語顯示期望已經改變。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":7},{"front":"arts degree","meaning":"藝術學位","examples":[{"en":"A director of an art gallery no longer necessarily needs an arts degree.","zh":"藝術館總監不一定再需要藝術學位。"},{"en":"An arts degree is a university qualification in subjects such as art, history, literature, or culture.","zh":"arts degree 指藝術、歷史、文學或文化等科目的大學學位。"},{"en":"A student with an arts degree may work in education, museums, writing, or cultural management.","zh":"擁有藝術學位的學生可能從事教育、博物館、寫作或文化管理工作。"},{"en":"Some museum jobs still value an arts degree because it provides cultural knowledge.","zh":"有些博物館工作仍重視藝術學位，因為它提供文化知識。"},{"en":"The passage suggests that an arts degree alone may not be enough for modern leadership.","zh":"文章表示，單靠藝術學位可能不足以應付現代領導工作。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":7},{"front":"succinctly summarised","meaning":"簡明扼要地總結","examples":[{"en":"The Economist succinctly summarised the new requirements for directors.","zh":"《經濟學人》簡明扼要地總結了總監的新要求。"},{"en":"Succinctly summarised means explained the main points briefly and clearly.","zh":"succinctly summarised 指簡短而清楚地說明重點。"},{"en":"A good student succinctly summarised a long article in five sentences.","zh":"好學生用五句話簡明扼要地總結了一篇長文章。"},{"en":"Succinct summaries help busy readers understand the key message quickly.","zh":"簡明摘要幫助忙碌讀者快速理解核心訊息。"},{"en":"This phrase praises writing that is short but not vague.","zh":"這個短語讚揚短而不含糊的寫作。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":7},{"front":"essential requirements","meaning":"必要條件","examples":[{"en":"Essential requirements for a director include business nous.","zh":"總監的必要條件包括商業頭腦。"},{"en":"Essential requirements are the things that are absolutely necessary for a role or task.","zh":"essential requirements 指某角色或任務絕對需要的條件。"},{"en":"A driving licence is an essential requirement for a bus driver.","zh":"駕駛執照是巴士司機的必要條件。"},{"en":"If essential requirements are missing, a person may not be suitable for the job.","zh":"如果缺少必要條件，一個人可能不適合該工作。"},{"en":"This phrase separates must-have qualities from optional extras.","zh":"這個短語把必須具備的質素與可有可無的額外條件分開。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":7},{"front":"business nous","meaning":"商業頭腦","examples":[{"en":"A modern museum director needs business nous.","zh":"現代博物館總監需要商業頭腦。"},{"en":"Business nous means practical business sense and the ability to make good commercial decisions.","zh":"business nous 指實際商業判斷力，以及作出良好商業決定的能力。"},{"en":"A shop owner shows business nous by choosing products customers actually want.","zh":"店主選擇顧客真正想要的產品時，就顯示商業頭腦。"},{"en":"Business nous helps museum directors balance culture, costs, and visitor demand.","zh":"商業頭腦幫助博物館總監平衡文化、成本和訪客需求。"},{"en":"This phrase is more informal than “business acumen” but has a similar meaning.","zh":"這個短語比 business acumen 較口語，但意思相近。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":8},{"front":"public-relations skills","meaning":"公關技巧","examples":[{"en":"Public-relations skills are important for staging travelling exhibitions.","zh":"公關技巧對舉辦巡迴展覽很重要。"},{"en":"Public-relations skills are abilities used to manage public image, media contact, and communication.","zh":"public-relations skills 指管理公眾形象、媒體聯絡和溝通的能力。"},{"en":"A school uses public-relations skills when explaining a new policy to parents.","zh":"學校向家長解釋新政策時，會使用公關技巧。"},{"en":"Museums need public-relations skills when attracting sponsors and handling criticism.","zh":"博物館吸引贊助商和處理批評時，需要公關技巧。"},{"en":"This phrase focuses on building trust and attention from the public.","zh":"這個短語著重建立公眾信任和關注。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":8},{"front":"along with","meaning":"連同；以及","examples":[{"en":"Directors need business nous along with public-relations skills.","zh":"總監需要商業頭腦，以及公關技巧。"},{"en":"Along with means together with or in addition to something else.","zh":"along with 指連同或加上另一事物。"},{"en":"A healthy lunch should include vegetables along with protein and rice.","zh":"健康午餐應包括蔬菜，以及蛋白質和米飯。"},{"en":"Museum leaders need cultural knowledge along with financial judgement.","zh":"博物館領導人需要文化知識，以及財務判斷力。"},{"en":"This phrase adds another important item to the same list.","zh":"這個短語把另一重要項目加入同一清單。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":8},{"front":"compete with","meaning":"與……競爭","examples":[{"en":"Museums compete with one another to stage travelling exhibitions.","zh":"博物館彼此競爭，以舉辦巡迴展覽。"},{"en":"To compete with someone means to try to do better than them or attract the same people.","zh":"compete with someone 指嘗試比對方做得更好，或吸引同一批人。"},{"en":"Small shops compete with large chains by offering personal service.","zh":"小店透過個人化服務與大型連鎖店競爭。"},{"en":"Museums compete with cinemas and theme parks for visitors’ free time.","zh":"博物館與戲院和主題公園競爭訪客的空閒時間。"},{"en":"This phrase usually suggests limited attention, money, or opportunity.","zh":"這個短語通常表示注意力、金錢或機會有限。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":8},{"front":"stage travelling exhibitions","meaning":"舉辦巡迴展覽","examples":[{"en":"Museums compete to stage travelling exhibitions.","zh":"博物館競爭舉辦巡迴展覽。"},{"en":"To stage travelling exhibitions means to host exhibitions that move from one place to another.","zh":"stage travelling exhibitions 指舉辦會從一個地方移到另一個地方的展覽。"},{"en":"A museum may stage travelling exhibitions from overseas galleries to attract new visitors.","zh":"博物館可能舉辦來自海外藝術館的巡迴展覽，以吸引新訪客。"},{"en":"Travelling exhibitions require planning because objects must be transported safely.","zh":"巡迴展覽需要規劃，因為物件必須安全運送。"},{"en":"This phrase combines organising an event with receiving a moving exhibition.","zh":"這個短語結合了舉辦活動和接收流動展覽的意思。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":8},{"front":"draw huge crowds","meaning":"吸引大量人群","examples":[{"en":"Travelling exhibitions can draw huge crowds.","zh":"巡迴展覽可以吸引大量人群。"},{"en":"To draw huge crowds means to attract very large numbers of people.","zh":"draw huge crowds 指吸引非常多的人。"},{"en":"A free concert in the city centre can draw huge crowds on a weekend.","zh":"市中心的免費音樂會可以在週末吸引大量人群。"},{"en":"When an event draws huge crowds, organisers need extra staff and crowd control.","zh":"當活動吸引大量人群，主辦者需要額外員工和人流管理。"},{"en":"This phrase emphasises the strong pulling power of an event.","zh":"這個短語強調活動的強大吸引力。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":8},{"front":"result in","meaning":"導致","examples":[{"en":"The new museology has resulted in the convergence of several industries.","zh":"新博物館學導致幾個產業的融合。"},{"en":"To result in something means to cause it to happen.","zh":"result in something 指導致某事發生。"},{"en":"Heavy rain can result in traffic delays and cancelled outdoor events.","zh":"大雨可以導致交通延誤和戶外活動取消。"},{"en":"More tourism can result in higher museum income but also larger crowds.","zh":"更多旅遊業可以導致博物館收入提高，但也帶來更多人群。"},{"en":"This phrase clearly connects a cause with a result.","zh":"這個短語清楚連接原因和結果。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":8},{"front":"convergence of","meaning":"……的融合","examples":[{"en":"The new museology has resulted in the convergence of museums, tourism and commerce.","zh":"新博物館學導致博物館、旅遊業和商業的融合。"},{"en":"The convergence of things means they come together and become closely connected.","zh":"convergence of things 指不同事物走在一起並變得密切相關。"},{"en":"The convergence of phones, cameras, and music players created the modern smartphone.","zh":"手機、相機和音樂播放器的融合創造了現代智能手機。"},{"en":"The convergence of museums and tourism can make exhibitions more commercial.","zh":"博物館和旅遊業的融合可以令展覽更商業化。"},{"en":"This phrase shows separate areas becoming linked.","zh":"這個短語顯示原本分開的領域變得連繫起來。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":8},{"front":"the heritage industry","meaning":"文化遺產產業","examples":[{"en":"Museums have converged with the heritage industry and tourism.","zh":"博物館已與文化遺產產業和旅遊業融合。"},{"en":"The heritage industry includes businesses and institutions that present history, culture, and old places to the public.","zh":"heritage industry 指向公眾呈現歷史、文化和古老地方的企業與機構。"},{"en":"Guided tours, historic houses, and cultural festivals can be part of the heritage industry.","zh":"導賞團、歷史大宅和文化節可以屬於文化遺產產業。"},{"en":"The heritage industry can protect culture, but it can also turn it into a product.","zh":"文化遺產產業可以保護文化，但也可能把文化變成產品。"},{"en":"This phrase links culture with tourism and business.","zh":"這個短語把文化與旅遊和商業連繫起來。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":8},{"front":"tourism","meaning":"旅遊業","examples":[{"en":"Museums are increasingly linked with tourism.","zh":"博物館越來越與旅遊業相關。"},{"en":"Tourism is travel for pleasure, culture, business, or visiting places of interest.","zh":"tourism 指為娛樂、文化、商務或參觀景點而進行的旅行活動。"},{"en":"A city may improve transport because tourism brings many visitors.","zh":"城市可能因旅遊業帶來很多訪客而改善交通。"},{"en":"Tourism can support museums by increasing ticket sales and local spending.","zh":"旅遊業可以透過增加門票銷售和本地消費來支持博物館。"},{"en":"However, too much tourism can put pressure on local communities.","zh":"然而，過多旅遊業可能對本地社區造成壓力。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":8},{"front":"the pursuits of profit and pleasure","meaning":"追求利潤和娛樂","examples":[{"en":"The new museology connects museums with the pursuits of profit and pleasure.","zh":"新博物館學把博物館與追求利潤和娛樂連繫起來。"},{"en":"The pursuits of profit and pleasure means efforts to make money and provide enjoyment.","zh":"the pursuits of profit and pleasure 指努力賺錢和提供娛樂享受。"},{"en":"A theme park is clearly connected with the pursuits of profit and pleasure.","zh":"主題公園明顯與追求利潤和娛樂有關。"},{"en":"When museums sell entertainment experiences, they move closer to these pursuits.","zh":"當博物館售賣娛樂體驗時，它們更接近這些追求。"},{"en":"This phrase suggests a shift from pure education to business and enjoyment.","zh":"這個短語表示由純教育轉向商業和娛樂的變化。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":9},{"front":"give rise to","meaning":"引發","examples":[{"en":"This convergence has given rise to much debate.","zh":"這種融合引發了大量爭議。"},{"en":"To give rise to something means to cause it to happen or appear.","zh":"give rise to something 指導致某事發生或出現。"},{"en":"A sudden rent increase can give rise to complaints from tenants.","zh":"突然加租可以引發租戶投訴。"},{"en":"New technology can give rise to new jobs and new worries.","zh":"新科技可以引發新工作和新擔憂。"},{"en":"This phrase is formal and often used for debates, problems, or changes.","zh":"這個短語較正式，常用於爭議、問題或變化。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":9},{"front":"much debate about","meaning":"關於……的大量爭議","examples":[{"en":"The new museology has given rise to much debate about museum priorities.","zh":"新博物館學引發了關於博物館優先事項的大量爭議。"},{"en":"Much debate about something means a lot of discussion and disagreement about it.","zh":"much debate about something 指圍繞某事有大量討論和分歧。"},{"en":"There is much debate about whether phones should be allowed in classrooms.","zh":"關於課室是否應允許使用手機，有大量爭議。"},{"en":"Much debate about museums arises when culture and commerce seem to conflict.","zh":"當文化和商業似乎衝突時，關於博物館的大量爭議就會出現。"},{"en":"This phrase suggests that people have different strong opinions.","zh":"這個短語表示人們有不同而強烈的意見。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":9},{"front":"appropriateness of","meaning":"……是否合適","examples":[{"en":"People debate the appropriateness of adapting museum activities to the marketplace.","zh":"人們爭論調整博物館活動以適應市場是否合適。"},{"en":"The appropriateness of something means whether it is suitable, acceptable, or right in a situation.","zh":"appropriateness of something 指某事在某情況下是否適合、可接受或正確。"},{"en":"Teachers may discuss the appropriateness of using cartoons in a serious lesson.","zh":"老師可能討論在嚴肅課堂中使用卡通是否合適。"},{"en":"The appropriateness of charging high museum fees depends on access and fairness.","zh":"收取高昂博物館費用是否合適，取決於參與機會和公平。"},{"en":"This phrase is useful when judging whether an action fits its purpose.","zh":"這個短語適合用於判斷行動是否符合目的。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":9},{"front":"adapt the activities of institutions","meaning":"調整機構活動","examples":[{"en":"Museums may adapt the activities of institutions to commercial priorities.","zh":"博物館可能調整機構活動，以配合商業優先事項。"},{"en":"To adapt the activities of institutions means to change what organisations do so they fit new needs.","zh":"adapt the activities of institutions 指改變機構所做的事，使其符合新需要。"},{"en":"Schools may adapt their activities when students need more online support.","zh":"當學生需要更多網上支援時，學校可能調整機構活動。"},{"en":"If museums adapt too much to business demands, education may become weaker.","zh":"如果博物館過度配合商業要求，教育功能可能變弱。"},{"en":"This phrase focuses on changing institutional behaviour.","zh":"這個短語著重改變機構行為。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":9},{"front":"more closely reflect","meaning":"更貼近反映","examples":[{"en":"Some institutions now more closely reflect the priorities of the marketplace.","zh":"有些機構現在更貼近反映市場的優先考慮。"},{"en":"To more closely reflect something means to show or match it more clearly than before.","zh":"more closely reflect something 指比以前更清楚地顯示或配合某事。"},{"en":"A school timetable may more closely reflect students’ needs after parents give feedback.","zh":"家長提供意見後，學校時間表可能更貼近反映學生需要。"},{"en":"Museum programmes more closely reflect the market when they focus on visitor spending.","zh":"當博物館活動著重訪客消費時，就更貼近反映市場。"},{"en":"This phrase suggests a stronger connection between two things.","zh":"這個短語表示兩者之間的連繫更強。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":9},{"front":"priorities of the marketplace","meaning":"市場的優先考慮","examples":[{"en":"Museums increasingly reflect the priorities of the marketplace.","zh":"博物館越來越反映市場的優先考慮。"},{"en":"Priorities of the marketplace are business concerns such as profit, demand, competition, and customer satisfaction.","zh":"priorities of the marketplace 指利潤、需求、競爭和顧客滿意度等商業考慮。"},{"en":"A shop follows the priorities of the marketplace when it sells what customers request most.","zh":"商店售賣顧客最常要求的東西時，就是跟隨市場的優先考慮。"},{"en":"If museums follow market priorities too closely, unpopular but important exhibitions may suffer.","zh":"如果博物館過度跟隨市場優先考慮，不受歡迎但重要的展覽可能受損。"},{"en":"This phrase contrasts business needs with cultural or educational needs.","zh":"這個短語把商業需要與文化或教育需要作對比。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":9},{"front":"primarily as","meaning":"主要作為","examples":[{"en":"Some people question whether museums should be seen primarily as tourist attractions.","zh":"有些人質疑博物館是否應主要被視為旅遊景點。"},{"en":"Primarily as means mainly in the role or form of something.","zh":"primarily as 指主要以某種角色或形式存在。"},{"en":"A school should be seen primarily as a place of learning, not a business.","zh":"學校應主要被視為學習場所，而不是企業。"},{"en":"If museums are seen primarily as entertainment venues, their educational role may be weakened.","zh":"如果博物館主要被視為娛樂場地，其教育角色可能被削弱。"},{"en":"This phrase identifies the main way something is understood.","zh":"這個短語指出人們主要如何理解某事物。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":9},{"front":"tourist attractions","meaning":"旅遊景點","examples":[{"en":"Some museums are now seen as tourist attractions.","zh":"有些博物館現在被視為旅遊景點。"},{"en":"Tourist attractions are places that visitors travel to see or experience.","zh":"tourist attractions 指遊客前往觀看或體驗的地方。"},{"en":"A famous temple, museum, or theme park can become a tourist attraction.","zh":"著名寺廟、博物館或主題公園都可以成為旅遊景點。"},{"en":"Tourist attractions can bring money to a city but also create crowding.","zh":"旅遊景點可以為城市帶來收入，但也會造成擠迫。"},{"en":"This phrase focuses on drawing visitors, especially from outside the local area.","zh":"這個短語著重吸引訪客，尤其是來自本地以外的訪客。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":9},{"front":"office functions","meaning":"公司活動","examples":[{"en":"Some institutions allow office functions in display areas.","zh":"有些機構允許在展覽區舉行公司活動。"},{"en":"Office functions are company events such as dinners, meetings, parties, or receptions.","zh":"office functions 指公司晚宴、會議、派對或招待會等活動。"},{"en":"A museum may rent a hall for office functions after closing time.","zh":"博物館可能在閉館後出租大廳作公司活動。"},{"en":"Office functions can bring income, but they may disturb the cultural atmosphere.","zh":"公司活動可以帶來收入，但可能影響文化氣氛。"},{"en":"This phrase shows a business use of a non-business space.","zh":"這個短語顯示非商業空間的商業用途。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":9},{"front":"display areas","meaning":"展覽區","examples":[{"en":"Office functions can be held in museum display areas.","zh":"公司活動可以在博物館展覽區舉行。"},{"en":"Display areas are parts of a museum or gallery where objects are shown to visitors.","zh":"display areas 指博物館或藝術館中向訪客展示物件的地方。"},{"en":"Visitors should not eat or drink in display areas because objects may be damaged.","zh":"訪客不應在展覽區飲食，因為物件可能受損。"},{"en":"Display areas need lighting, labels, security, and enough space for movement.","zh":"展覽區需要燈光、標籤、保安和足夠活動空間。"},{"en":"This phrase refers to exhibition spaces, not offices or storage rooms.","zh":"這個短語指展覽空間，而不是辦公室或儲物室。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":10},{"front":"dinner with the dinosaurs","meaning":"與恐龍共進晚餐","examples":[{"en":"Some museums let visitors have dinner with the dinosaurs.","zh":"有些博物館讓訪客與恐龍共進晚餐。"},{"en":"Dinner with the dinosaurs means a special event where people eat in a museum space with dinosaur displays.","zh":"dinner with the dinosaurs 指人們在有恐龍展示的博物館空間中用餐的特別活動。"},{"en":"A family may book dinner with the dinosaurs as a memorable birthday activity.","zh":"家庭可能預訂與恐龍共進晚餐，作為難忘的生日活動。"},{"en":"Such events can attract visitors who want entertainment as well as education.","zh":"這類活動可以吸引想要娛樂和教育體驗的訪客。"},{"en":"The phrase shows how museums mix learning with commercial experiences.","zh":"這個短語顯示博物館如何把學習與商業體驗結合。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":10},{"front":"whatever commentators may think","meaning":"無論評論者怎樣想","examples":[{"en":"Whatever commentators may think, museum managers are blending culture and commerce.","zh":"無論評論者怎樣想，博物館管理人員正在融合文化與商業。"},{"en":"Whatever commentators may think means regardless of what critics or observers believe.","zh":"whatever commentators may think 指不管批評者或觀察者相信甚麼。"},{"en":"Whatever commentators may think, many families still enjoy interactive museum displays.","zh":"無論評論者怎樣想，許多家庭仍喜歡互動博物館展示。"},{"en":"This phrase suggests that debate exists, but the action continues anyway.","zh":"這個短語表示爭議存在，但行動仍然繼續。"},{"en":"It is useful when reality moves forward despite disagreement.","zh":"當現實在分歧中繼續推進時，這個短語很有用。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":10},{"front":"managers of museums","meaning":"博物館管理人員","examples":[{"en":"Managers of museums are looking for ways to attract visitors.","zh":"博物館管理人員正在尋找吸引訪客的方法。"},{"en":"Managers of museums are people responsible for running museum operations and decisions.","zh":"managers of museums 指負責博物館運作和決策的人。"},{"en":"Managers of museums plan budgets, staff duties, exhibitions, and visitor services.","zh":"博物館管理人員規劃預算、員工職責、展覽和訪客服務。"},{"en":"If visitor numbers fall, managers of museums must decide what changes are needed.","zh":"如果訪客人數下降，博物館管理人員必須決定需要甚麼改變。"},{"en":"This phrase focuses on leadership and practical management inside museums.","zh":"這個短語著重博物館內部的領導和實際管理。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":10},{"front":"worldwide","meaning":"世界各地","examples":[{"en":"Museum managers worldwide are blending culture and commerce.","zh":"世界各地的博物館管理人員正在融合文化與商業。"},{"en":"Worldwide means across the world or in many countries.","zh":"worldwide 指遍及世界或在許多國家。"},{"en":"Online classes made some teaching methods available worldwide.","zh":"網上課堂令一些教學方法可以在世界各地使用。"},{"en":"A successful exhibition idea may spread worldwide through museum networks.","zh":"成功的展覽概念可能透過博物館網絡傳到世界各地。"},{"en":"This word shows that something is not limited to one country.","zh":"這個詞表示某事不限於一個國家。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":10},{"front":"artful ways","meaning":"巧妙的方法","examples":[{"en":"Museums are looking for artful ways to blend culture and commerce.","zh":"博物館正在尋找巧妙的方法來融合文化與商業。"},{"en":"Artful ways are clever and skilful methods of doing something.","zh":"artful ways 指聰明而有技巧的方法。"},{"en":"A teacher may find artful ways to explain grammar through stories and games.","zh":"老師可能找到巧妙的方法，透過故事和遊戲解釋文法。"},{"en":"Museums need artful ways to earn money without damaging their cultural mission.","zh":"博物館需要巧妙的方法賺錢，同時不損害文化使命。"},{"en":"This phrase suggests skill, balance, and careful judgement.","zh":"這個短語表示技巧、平衡和仔細判斷。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":10},{"front":"blend culture and commerce","meaning":"融合文化與商業","examples":[{"en":"Blockbusters help museums blend culture and commerce.","zh":"大型熱門展覽幫助博物館融合文化與商業。"},{"en":"To blend culture and commerce means to combine cultural aims with business activity.","zh":"blend culture and commerce 指把文化目標與商業活動結合。"},{"en":"A museum shop blends culture and commerce when it sells books related to an exhibition.","zh":"當博物館商店售賣與展覽相關的書籍時，就是在融合文化與商業。"},{"en":"If done badly, blending culture and commerce can make culture feel too commercial.","zh":"如果做得不好，融合文化與商業可能令文化感覺過於商業化。"},{"en":"This phrase is central to debates about modern museums.","zh":"這個短語是現代博物館爭議的核心。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":10},{"front":"at the top of the list","meaning":"位列首位","examples":[{"en":"Blockbuster exhibitions are at the top of the list.","zh":"大型熱門展覽位列首位。"},{"en":"At the top of the list means among the most important or preferred choices.","zh":"at the top of the list 指在最重要或最優先的選擇之中。"},{"en":"For many parents, safety is at the top of the list when choosing a school.","zh":"對許多家長而言，選學校時安全位列首位。"},{"en":"Museums may put blockbuster exhibitions at the top of the list because they draw crowds.","zh":"博物館可能把大型熱門展覽放在首位，因為它們吸引人群。"},{"en":"This phrase shows high priority.","zh":"這個短語表示高度優先。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":10},{"front":"drawing power","meaning":"吸引力","examples":[{"en":"Blockbusters have strong drawing power.","zh":"大型熱門展覽有強大吸引力。"},{"en":"Drawing power is the ability to attract people to an event, place, or product.","zh":"drawing power 指吸引人前往某活動、地方或產品的能力。"},{"en":"A famous singer has drawing power because many people will buy tickets to see her.","zh":"著名歌手有吸引力，因為很多人會買票去看她。"},{"en":"An exhibition with strong drawing power can bring visitors who rarely visit museums.","zh":"有強大吸引力的展覽可以帶來很少參觀博物館的訪客。"},{"en":"This phrase focuses on attraction and audience pull.","zh":"這個短語著重吸引和拉動觀眾的能力。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":10},{"front":"benefit from the drawing power of","meaning":"從……的吸引力中受惠","examples":[{"en":"Institutions can benefit from the drawing power of a blockbuster.","zh":"機構可以從大型熱門展覽的吸引力中受惠。"},{"en":"To benefit from the drawing power of something means to gain advantages because it attracts people.","zh":"benefit from the drawing power of something 指因某事物吸引人而得到好處。"},{"en":"Nearby restaurants may benefit from the drawing power of a popular concert.","zh":"附近餐廳可能從受歡迎音樂會的吸引力中受惠。"},{"en":"Museums benefit from the drawing power of famous objects when more people buy tickets.","zh":"當更多人買票時，博物館就從著名展品的吸引力中受惠。"},{"en":"This phrase connects popularity with practical gain.","zh":"這個短語把受歡迎程度與實際好處連繫起來。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":10},{"front":"stage a blockbuster","meaning":"舉辦大型熱門展覽","examples":[{"en":"You do not need a museum to stage a blockbuster.","zh":"你不一定需要博物館才可舉辦大型熱門展覽。"},{"en":"To stage a blockbuster means to organise and present a very popular large exhibition or event.","zh":"stage a blockbuster 指組織並呈現非常受歡迎的大型展覽或活動。"},{"en":"A science centre may stage a blockbuster about space exploration.","zh":"科學中心可能舉辦關於太空探索的大型熱門展覽。"},{"en":"Staging a blockbuster can require marketing, security, staff training, and extra space.","zh":"舉辦大型熱門展覽可能需要市場推廣、保安、員工培訓和額外空間。"},{"en":"This phrase focuses on organising the event, not just naming it.","zh":"這個短語著重組織活動，而不只是命名它。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":11},{"front":"public institutions","meaning":"公共機構","examples":[{"en":"Blockbusters are often held in public institutions.","zh":"大型熱門展覽經常在公共機構舉行。"},{"en":"Public institutions are organisations that serve the public, often supported by government or public money.","zh":"public institutions 指服務公眾、通常受政府或公共資金支持的機構。"},{"en":"Libraries, museums, schools, and hospitals can be public institutions.","zh":"圖書館、博物館、學校和醫院都可以是公共機構。"},{"en":"Public institutions must balance public service with financial pressure.","zh":"公共機構必須平衡公共服務和財務壓力。"},{"en":"This phrase refers to organisations with a public role, not private homes or clubs.","zh":"這個短語指具有公共角色的機構，而不是私人住宅或會所。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":11},{"front":"create a surplus","meaning":"產生盈餘","examples":[{"en":"Blockbusters may create a surplus to fund other activities.","zh":"大型熱門展覽可能產生盈餘，以資助其他活動。"},{"en":"To create a surplus means to produce more money than is needed to cover costs.","zh":"create a surplus 指產生超過支付成本所需的金錢。"},{"en":"A school fair can create a surplus if ticket sales are higher than expenses.","zh":"如果門票收入高於開支，學校嘉年華可以產生盈餘。"},{"en":"Museums may use a surplus from a popular exhibition to support free programmes.","zh":"博物館可能使用熱門展覽的盈餘來支持免費活動。"},{"en":"This phrase means extra money remains after costs are paid.","zh":"這個短語表示支付成本後仍有額外金錢。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":11},{"front":"fund other activities","meaning":"資助其他活動","examples":[{"en":"A museum may use a surplus to fund other activities.","zh":"博物館可能使用盈餘來資助其他活動。"},{"en":"To fund other activities means to provide money for different programmes or work.","zh":"fund other activities 指為其他計劃或工作提供金錢。"},{"en":"A charity shop may fund other activities by selling donated clothes.","zh":"慈善商店可能透過售賣捐贈衣物來資助其他活動。"},{"en":"Ticket income from a popular show can fund education workshops.","zh":"受歡迎演出的門票收入可以資助教育工作坊。"},{"en":"This phrase connects one source of money with another purpose.","zh":"這個短語把一個收入來源與另一個用途連繫起來。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":11},{"front":"the bottom line","meaning":"最終盈虧；底線","examples":[{"en":"If the bottom line is profit, blockbusters can make money.","zh":"如果底線是利潤，大型熱門展覽可以賺錢。"},{"en":"The bottom line means the final financial result or the main practical concern.","zh":"the bottom line 指最終財務結果或最主要的實際考慮。"},{"en":"For a small shop, the bottom line is whether income is higher than costs.","zh":"對小店而言，最終盈虧在於收入是否高於成本。"},{"en":"If the bottom line is education, a museum may judge success differently from profit.","zh":"如果底線是教育，博物館可能以不同於利潤的方式判斷成功。"},{"en":"This phrase can mean final profit or the most important point.","zh":"這個短語可以指最終利潤，也可以指最重要的一點。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":11},{"front":"according to","meaning":"根據","examples":[{"en":"According to accounting records, many blockbusters make money.","zh":"根據會計記錄，許多大型熱門展覽都賺錢。"},{"en":"According to means based on what a source says or shows.","zh":"according to 指根據某來源所說或所顯示的內容。"},{"en":"According to the timetable, the next train leaves at six.","zh":"根據時間表，下一班火車六點開出。"},{"en":"According to visitor surveys, families want clearer signs and more seating.","zh":"根據訪客調查，家庭希望有更清楚標示和更多座位。"},{"en":"This phrase helps show where information comes from.","zh":"這個短語幫助顯示資料來源。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":11},{"front":"accounting records","meaning":"會計記錄","examples":[{"en":"Accounting records suggest that many blockbusters make money.","zh":"會計記錄顯示，許多大型熱門展覽都賺錢。"},{"en":"Accounting records are financial documents that show income, costs, payments, and profits.","zh":"accounting records 指顯示收入、成本、付款和利潤的財務文件。"},{"en":"A business checks accounting records before deciding whether it can hire more staff.","zh":"企業決定是否可以聘請更多員工前，會檢查會計記錄。"},{"en":"Accounting records may show profit, but they may not capture every hidden cost.","zh":"會計記錄可能顯示利潤，但未必能捕捉所有隱藏成本。"},{"en":"This phrase refers to financial evidence, not personal opinion.","zh":"這個短語指財務證據，而不是個人意見。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":11},{"front":"major museums and galleries","meaning":"主要博物館和藝術館","examples":[{"en":"Many major museums and galleries use blockbusters to generate revenue.","zh":"許多主要博物館和藝術館利用大型熱門展覽創造收入。"},{"en":"Major museums and galleries are large or important cultural institutions with significant collections or influence.","zh":"major museums and galleries 指擁有重要館藏或影響力的大型或重要文化機構。"},{"en":"Major museums and galleries often attract tourists from many countries.","zh":"主要博物館和藝術館經常吸引來自許多國家的遊客。"},{"en":"Because they have strong reputations, major museums and galleries can borrow famous objects more easily.","zh":"由於聲譽強，主要博物館和藝術館較容易借到著名物件。"},{"en":"This phrase refers to leading institutions, not small local displays.","zh":"這個短語指領先機構，而不是小型本地展示。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":11},{"front":"make money","meaning":"賺錢","examples":[{"en":"Some blockbuster exhibitions do make money.","zh":"有些大型熱門展覽確實會賺錢。"},{"en":"To make money means to earn more income than the cost of doing something.","zh":"make money 指賺取的收入高於做某事的成本。"},{"en":"A café makes money when sales are higher than rent, wages, and food costs.","zh":"當咖啡店銷售額高於租金、工資和食材成本時，它就賺錢。"},{"en":"A museum may make money from tickets, shops, cafés, and memberships.","zh":"博物館可能透過門票、商店、咖啡店和會員賺錢。"},{"en":"This phrase is simple and directly connected to profit.","zh":"這個短語簡單而直接與利潤相關。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":11},{"front":"overseas","meaning":"海外","examples":[{"en":"For some museums overseas, blockbuster profits may fund repairs.","zh":"對一些海外博物館而言，大型熱門展覽的利潤可能資助維修。"},{"en":"Overseas means in or to another country across national borders.","zh":"overseas 指在或前往另一個國家。"},{"en":"Students may study overseas to experience a different education system.","zh":"學生可能到海外升學，以體驗不同教育制度。"},{"en":"Museums overseas may face different funding rules and visitor habits.","zh":"海外博物館可能面對不同資金規則和訪客習慣。"},{"en":"This word contrasts another country with the speaker’s own country.","zh":"這個詞把其他國家與說話者自己的國家作對比。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":11},{"front":"update parts of their collections","meaning":"更新部分館藏","examples":[{"en":"Some museums use blockbuster revenue to update parts of their collections.","zh":"有些博物館使用大型熱門展覽收入來更新部分館藏。"},{"en":"To update parts of their collections means to improve, restore, reorganise, or add to some museum holdings.","zh":"update parts of their collections 指改善、修復、重新整理或增加部分博物館藏品。"},{"en":"A library may update parts of its collection by buying newer books.","zh":"圖書館可能透過購買新書來更新部分館藏。"},{"en":"Museums update collections so visitors can see better displays and more accurate information.","zh":"博物館更新館藏，讓訪客看到更好的展示和更準確資料。"},{"en":"This phrase suggests gradual improvement, not replacing everything.","zh":"這個短語表示逐步改善，而不是更換所有東西。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":12},{"front":"repair buildings","meaning":"維修建築物","examples":[{"en":"Museums may use money from blockbusters to repair buildings.","zh":"博物館可能使用大型熱門展覽的金錢來維修建築物。"},{"en":"To repair buildings means to fix damaged or ageing parts of structures.","zh":"repair buildings 指修理建築物中損壞或老化的部分。"},{"en":"A school may repair buildings when roofs leak or windows break.","zh":"當屋頂漏水或窗戶破裂時，學校可能需要維修建築物。"},{"en":"Museums must repair buildings to protect visitors and collections.","zh":"博物館必須維修建築物，以保護訪客和館藏。"},{"en":"This phrase focuses on practical maintenance, not exhibition design.","zh":"這個短語著重實際保養，而不是展覽設計。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":12},{"front":"in need of attention","meaning":"需要處理；需要維修","examples":[{"en":"Some museum buildings are in need of attention.","zh":"有些博物館建築物需要維修。"},{"en":"In need of attention means requiring care, repair, or action.","zh":"in need of attention 指需要照顧、修理或採取行動。"},{"en":"A child’s homework may be in need of attention if there are many careless mistakes.","zh":"如果孩子的功課有很多粗心錯誤，就需要處理。"},{"en":"Old museum buildings in need of attention may become unsafe if repairs are delayed.","zh":"需要維修的舊博物館建築物如果延遲修理，可能變得不安全。"},{"en":"This phrase politely suggests that a problem should not be ignored.","zh":"這個短語委婉地表示問題不應被忽視。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":12},{"front":"illustrate that","meaning":"說明","examples":[{"en":"Some institutions want to illustrate that they are paying their way.","zh":"有些機構想說明它們正在自負盈虧。"},{"en":"To illustrate that something is true means to show or explain it clearly with evidence or example.","zh":"illustrate that something is true 指用證據或例子清楚顯示或解釋某事是真的。"},{"en":"A chart can illustrate that student attendance improved after breakfast was provided.","zh":"圖表可以說明提供早餐後學生出席率改善。"},{"en":"Museums may use financial reports to illustrate that exhibitions support their costs.","zh":"博物館可能使用財務報告說明展覽能支持成本。"},{"en":"This phrase is often used when proving or explaining a point.","zh":"這個短語常用於證明或解釋一個觀點。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":12},{"front":"attempt to pay their way","meaning":"嘗試自負盈虧","examples":[{"en":"Some museums try to show that they can pay their way.","zh":"有些博物館嘗試顯示自己可以自負盈虧。"},{"en":"To attempt to pay their way means to try to cover their own costs without relying fully on others.","zh":"attempt to pay their way 指嘗試自行支付成本，而不完全依賴他人。"},{"en":"A student may take a part-time job to attempt to pay his way through university.","zh":"學生可能做兼職，嘗試自行支付大學費用。"},{"en":"Museums attempt to pay their way when public funding is reduced.","zh":"當公共資金減少時，博物館會嘗試自負盈虧。"},{"en":"This phrase suggests financial independence, or at least the effort to achieve it.","zh":"這個短語表示財務獨立，或至少表示達成財務獨立的努力。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":12},{"front":"recover operating costs","meaning":"收回營運成本","examples":[{"en":"Museums may recover operating costs through blockbuster exhibitions.","zh":"博物館可能透過大型熱門展覽收回營運成本。"},{"en":"To recover operating costs means to earn enough money to cover daily running expenses.","zh":"recover operating costs 指賺取足夠金錢來支付日常運作開支。"},{"en":"A bus company raises fares when it cannot recover operating costs.","zh":"當巴士公司不能收回營運成本時，可能會加票價。"},{"en":"Ticket sales help museums recover operating costs such as electricity, staff, and cleaning.","zh":"門票銷售幫助博物館收回電力、員工和清潔等營運成本。"},{"en":"This phrase focuses on paying for normal operations, not making a huge profit.","zh":"這個短語著重支付正常運作，而不是賺取巨大利潤。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":12},{"front":"operating costs","meaning":"營運成本","examples":[{"en":"Blockbusters can help museums cover operating costs.","zh":"大型熱門展覽可以幫助博物館支付營運成本。"},{"en":"Operating costs are the regular expenses needed to run an organisation.","zh":"operating costs 指營運一個機構所需的定期開支。"},{"en":"Rent, wages, electricity, cleaning, and insurance are common operating costs.","zh":"租金、工資、電費、清潔和保險都是常見營運成本。"},{"en":"If operating costs rise, museums may need more income or public support.","zh":"如果營運成本上升，博物館可能需要更多收入或公共支持。"},{"en":"This phrase refers to ongoing costs, not one-time construction costs.","zh":"這個短語指持續成本，而不是一次性建築成本。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":12},{"front":"operating activities","meaning":"營運活動","examples":[{"en":"Blockbuster revenue may fund other operating activities.","zh":"大型熱門展覽收入可能資助其他營運活動。"},{"en":"Operating activities are the regular tasks and services an organisation carries out to function.","zh":"operating activities 指機構為了運作而定期進行的任務和服務。"},{"en":"In a museum, operating activities include exhibitions, education programmes, security, and visitor services.","zh":"在博物館中，營運活動包括展覽、教育計劃、保安和訪客服務。"},{"en":"If income falls, some operating activities may have to be reduced.","zh":"如果收入下降，有些營運活動可能要減少。"},{"en":"This phrase focuses on everyday organisational work.","zh":"這個短語著重機構的日常工作。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":12},{"front":"off-budget revenue","meaning":"預算外收入","examples":[{"en":"Museums may fund activities with off-budget revenue.","zh":"博物館可能用預算外收入資助活動。"},{"en":"Off-budget revenue is money received outside the normal official budget.","zh":"off-budget revenue 指正常官方預算以外收到的金錢。"},{"en":"A school may use off-budget revenue from a fair to buy extra sports equipment.","zh":"學校可能使用嘉年華的預算外收入購買額外運動器材。"},{"en":"Off-budget revenue can support useful projects, but it may be less predictable.","zh":"預算外收入可以支持有用項目，但可能較難預測。"},{"en":"This phrase refers to extra income beyond planned funding.","zh":"這個短語指計劃資金以外的額外收入。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":12},{"front":"economic rationalists","meaning":"經濟理性主義者","examples":[{"en":"Economic rationalists are pleased when museums recover costs.","zh":"當博物館收回成本時，經濟理性主義者會感到高興。"},{"en":"Economic rationalists are people who emphasise efficiency, cost control, and market-style decision-making.","zh":"economic rationalists 指強調效率、成本控制和市場式決策的人。"},{"en":"Economic rationalists may ask whether public services give value for money.","zh":"經濟理性主義者可能會問公共服務是否物有所值。"},{"en":"In museums, economic rationalists may support exhibitions that reduce reliance on subsidies.","zh":"在博物館中，經濟理性主義者可能支持減少依賴資助的展覽。"},{"en":"This phrase refers to a way of thinking based strongly on financial logic.","zh":"這個短語指一種高度根據財務邏輯的思維方式。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":12},{"front":"be hailed as","meaning":"被譽為","examples":[{"en":"Not all exhibitions hailed as blockbusters will make money.","zh":"並非所有被譽為大型熱門展覽的展覽都會賺錢。"},{"en":"To be hailed as something means to be publicly praised or described as that thing.","zh":"be hailed as something 指被公開讚揚或描述為某種事物。"},{"en":"A young athlete may be hailed as a future champion after winning a major race.","zh":"年輕運動員贏得大型比賽後，可能被譽為未來冠軍。"},{"en":"An exhibition hailed as successful may still lose money if costs are too high.","zh":"被譽為成功的展覽，如果成本太高，仍可能虧錢。"},{"en":"This phrase shows public praise, but the praise may not always be fully accurate.","zh":"這個短語表示公眾讚譽，但讚譽未必完全準確。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":13},{"front":"recognise the real cost of","meaning":"認清……的真正成本","examples":[{"en":"Accounting systems may not recognise the real cost of creating a blockbuster.","zh":"會計系統未必能認清創作大型熱門展覽的真正成本。"},{"en":"To recognise the real cost of something means to understand or record its full true expense.","zh":"recognise the real cost of something 指理解或記錄某事的完整真實開支。"},{"en":"A family may not recognise the real cost of owning a car until repairs and insurance are included.","zh":"家庭可能到計算維修和保險時，才認清擁有汽車的真正成本。"},{"en":"Museums must recognise real costs such as staff time, transport, and security.","zh":"博物館必須認清員工時間、運輸和保安等真正成本。"},{"en":"This phrase warns that visible costs may not be the whole cost.","zh":"這個短語提醒我們，可見成本未必是全部成本。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":13},{"front":"creating or hiring a blockbuster","meaning":"創作或租用大型熱門展覽","examples":[{"en":"The real cost of creating or hiring a blockbuster may be hard to measure.","zh":"創作或租用大型熱門展覽的真正成本可能難以量度。"},{"en":"Creating or hiring a blockbuster means either producing a major exhibition yourself or bringing one in from elsewhere.","zh":"creating or hiring a blockbuster 指自行製作大型展覽，或從其他地方引入一個大型展覽。"},{"en":"A small museum may hire a blockbuster because creating one from zero is too expensive.","zh":"小型博物館可能租用大型熱門展覽，因為從零創作太昂貴。"},{"en":"Creating or hiring a blockbuster can require money, staff, space, and marketing.","zh":"創作或租用大型熱門展覽可能需要金錢、員工、空間和市場推廣。"},{"en":"This phrase shows that both options involve serious costs.","zh":"這個短語顯示兩個選項都涉及重大成本。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":13},{"front":"require large capital expenditure","meaning":"需要大量資本開支","examples":[{"en":"Blockbusters require large capital expenditure.","zh":"大型熱門展覽需要大量資本開支。"},{"en":"To require large capital expenditure means to need a lot of money for major assets, equipment, or setup.","zh":"require large capital expenditure 指需要大量金錢購買主要資產、設備或進行設置。"},{"en":"Building a new sports hall requires large capital expenditure.","zh":"建造新體育館需要大量資本開支。"},{"en":"A blockbuster may require large capital expenditure for display cases, lighting, security, and transport.","zh":"大型熱門展覽可能需要大量資本開支，用於展示櫃、燈光、保安和運輸。"},{"en":"This phrase refers to big upfront spending.","zh":"這個短語指前期的大額支出。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":13},{"front":"capital expenditure","meaning":"資本開支","examples":[{"en":"Capital expenditure is necessary for mounting a blockbuster.","zh":"舉辦大型熱門展覽需要資本開支。"},{"en":"Capital expenditure is money spent on major long-term assets or equipment.","zh":"capital expenditure 指花在主要長期資產或設備上的金錢。"},{"en":"Buying new computers for a school is capital expenditure, while buying paper is usually not.","zh":"為學校購買新電腦是資本開支，而購買紙張通常不是。"},{"en":"Museums may face capital expenditure when they need new display systems.","zh":"當博物館需要新展示系統時，可能面對資本開支。"},{"en":"This phrase is different from daily operating costs.","zh":"這個短語不同於日常營運成本。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":13},{"front":"draw on resources","meaning":"動用資源","examples":[{"en":"Blockbusters draw on resources across all branches of an organisation.","zh":"大型熱門展覽會動用機構所有部門的資源。"},{"en":"To draw on resources means to use money, people, knowledge, or equipment that is available.","zh":"draw on resources 指使用可用的金錢、人手、知識或設備。"},{"en":"A school play may draw on resources from teachers, parents, students, and the office.","zh":"學校話劇可能動用老師、家長、學生和校務處的資源。"},{"en":"Large projects draw on many resources, so other work may slow down.","zh":"大型項目動用許多資源，因此其他工作可能放慢。"},{"en":"This phrase shows that support comes from several places.","zh":"這個短語表示支援來自多個地方。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":13},{"front":"across all branches of","meaning":"橫跨……所有部門","examples":[{"en":"A blockbuster uses resources across all branches of an organisation.","zh":"大型熱門展覽會使用橫跨機構所有部門的資源。"},{"en":"Across all branches of an organisation means throughout all departments or sections.","zh":"across all branches of an organisation 指遍及機構所有部門或部分。"},{"en":"A new school policy may require work across all branches of the school.","zh":"新學校政策可能需要橫跨學校所有部門的工作。"},{"en":"Big exhibitions affect staff across all branches of a museum, from security to education.","zh":"大型展覽會影響博物館所有部門的員工，從保安到教育部門。"},{"en":"This phrase emphasises wide internal involvement.","zh":"這個短語強調廣泛的內部參與。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":13},{"front":"the costs don’t end there","meaning":"成本並不止於此","examples":[{"en":"The financial costs do not end with capital expenditure.","zh":"財務成本並不止於資本開支。"},{"en":"The costs don’t end there means there are more costs after the first obvious one.","zh":"the costs don’t end there 指在第一個明顯成本之後仍有更多成本。"},{"en":"Buying a car is expensive, but the costs don’t end there because fuel and repairs continue.","zh":"買車很昂貴，但成本並不止於此，因為燃油和維修仍會持續。"},{"en":"A museum may pay for transport first, but the costs don’t end there because staff overtime follows.","zh":"博物館可能先支付運輸費，但成本並不止於此，因為之後還有員工加班。"},{"en":"This phrase warns people to look beyond the first expense.","zh":"這個短語提醒人們要看見第一項開支以外的成本。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":13},{"front":"human-resource management cost","meaning":"人力資源管理成本","examples":[{"en":"Blockbusters also involve a human-resource management cost.","zh":"大型熱門展覽也涉及人力資源管理成本。"},{"en":"A human-resource management cost is the staff-related cost of hiring, training, scheduling, or managing workers.","zh":"human-resource management cost 指與聘請、培訓、排班或管理員工有關的成本。"},{"en":"A large school event creates human-resource management costs when teachers work extra hours.","zh":"大型學校活動若令老師加班，就會產生人力資源管理成本。"},{"en":"Museums face these costs when staff must be moved from normal duties to exhibition work.","zh":"當博物館員工必須從正常職責調去展覽工作時，就會面對這些成本。"},{"en":"This phrase shows that people’s time is also a real cost.","zh":"這個短語顯示人的時間也是實際成本。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":13},{"front":"measurable real dollar cost","meaning":"可量度的實際金錢成本","examples":[{"en":"A blockbuster has a measurable real dollar cost.","zh":"大型熱門展覽有可量度的實際金錢成本。"},{"en":"A measurable real dollar cost is a cost that can be counted in actual money.","zh":"measurable real dollar cost 指可以用實際金錢計算的成本。"},{"en":"Extra electricity for a large event is a measurable real dollar cost.","zh":"大型活動的額外電費是可量度的實際金錢成本。"},{"en":"Staff overtime, insurance, and transport create measurable real dollar costs for exhibitions.","zh":"員工加班、保險和運輸會為展覽產生可量度的實際金錢成本。"},{"en":"This phrase separates financial costs from vague or emotional costs.","zh":"這個短語把財務成本與模糊或情感成本分開。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":13},{"front":"touring exhibition","meaning":"巡迴展覽","examples":[{"en":"Receiving a touring exhibition involves large expenditure.","zh":"接收巡迴展覽涉及大量開支。"},{"en":"A touring exhibition is an exhibition that travels from one venue to another.","zh":"touring exhibition 指從一個場地移到另一個場地的展覽。"},{"en":"A city museum may receive a touring exhibition about ancient Egypt.","zh":"城市博物館可能接收一個關於古埃及的巡迴展覽。"},{"en":"Touring exhibitions can save research time but still require transport, insurance, and setup.","zh":"巡迴展覽可以節省研究時間，但仍需要運輸、保險和設置。"},{"en":"This phrase describes a moving exhibition, not a permanent local display.","zh":"這個短語描述流動展覽，而不是永久本地展示。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":14},{"front":"involve large expenditure","meaning":"涉及大量開支","examples":[{"en":"A touring exhibition involves large expenditure.","zh":"巡迴展覽涉及大量開支。"},{"en":"To involve large expenditure means to require a lot of spending.","zh":"involve large expenditure 指需要大量花費。"},{"en":"Renovating an old school building may involve large expenditure.","zh":"翻新舊校舍可能涉及大量開支。"},{"en":"Large expenditure can make managers question whether a project is worth doing.","zh":"大量開支可能令管理人員質疑項目是否值得進行。"},{"en":"This phrase highlights the financial burden of an activity.","zh":"這個短語強調活動的財務負擔。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":14},{"front":"functional management structures","meaning":"職能管理架構","examples":[{"en":"Resources are drawn from across functional management structures.","zh":"資源從職能管理架構各處被調動。"},{"en":"Functional management structures are organisational systems divided by roles such as finance, education, marketing, and operations.","zh":"functional management structures 指按財務、教育、市場推廣和營運等職能劃分的組織系統。"},{"en":"A hospital has functional management structures for nursing, records, cleaning, and finance.","zh":"醫院有護理、紀錄、清潔和財務等職能管理架構。"},{"en":"Big exhibitions cross these structures because many departments must work together.","zh":"大型展覽會跨越這些架構，因為許多部門必須合作。"},{"en":"This phrase describes how an organisation is arranged internally.","zh":"這個短語描述機構內部如何安排。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":14},{"front":"project-management style","meaning":"項目管理方式","examples":[{"en":"Blockbusters are often handled in a project-management style.","zh":"大型熱門展覽通常以項目管理方式處理。"},{"en":"A project-management style means organising work through timelines, tasks, teams, budgets, and deadlines.","zh":"project-management style 指透過時間表、任務、團隊、預算和期限來組織工作。"},{"en":"A school renovation may use a project-management style to coordinate builders and teachers.","zh":"學校翻新可能使用項目管理方式來協調建築工人和老師。"},{"en":"Big exhibitions need this style because many tasks must happen in the right order.","zh":"大型展覽需要這種方式，因為許多任務必須按正確次序進行。"},{"en":"This phrase suggests planned coordination rather than casual organisation.","zh":"這個短語表示有計劃的協調，而不是隨意組織。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":14},{"front":"general labourers","meaning":"普通勞工","examples":[{"en":"General labourers may be required to perform additional tasks.","zh":"普通勞工可能被要求執行額外工作。"},{"en":"General labourers are workers who do practical physical jobs that do not require highly specialised training.","zh":"general labourers 指從事實際體力工作、而不需要高度專門訓練的工人。"},{"en":"General labourers may move boxes, set up barriers, or carry equipment.","zh":"普通勞工可能搬箱、設置圍欄或搬運設備。"},{"en":"During a large exhibition, general labourers may need to work extra hours.","zh":"在大型展覽期間，普通勞工可能需要加班。"},{"en":"This phrase refers to practical support staff.","zh":"這個短語指實際支援人員。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":14},{"front":"building-services staff","meaning":"建築服務職員","examples":[{"en":"Building-services staff may need to help with blockbuster exhibitions.","zh":"建築服務職員可能需要協助大型熱門展覽。"},{"en":"Building-services staff are workers who maintain a building’s practical systems and facilities.","zh":"building-services staff 指維持建築物實際系統和設施的員工。"},{"en":"They may check lighting, air conditioning, lifts, toilets, and electrical systems.","zh":"他們可能檢查燈光、空調、升降機、洗手間和電力系統。"},{"en":"Large exhibitions need building-services staff because visitor numbers and equipment use increase.","zh":"大型展覽需要建築服務職員，因為訪客人數和設備使用量增加。"},{"en":"This phrase refers to staff who keep the building working safely.","zh":"這個短語指保持建築物安全運作的員工。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":14},{"front":"front-of-house staff","meaning":"前台職員","examples":[{"en":"Front-of-house staff deal directly with visitors.","zh":"前台職員直接面對訪客。"},{"en":"Front-of-house staff are workers visitors meet first, such as reception, ticketing, and information staff.","zh":"front-of-house staff 指訪客最先遇到的員工，例如接待、售票和資訊人員。"},{"en":"In a theatre, front-of-house staff check tickets and guide people to seats.","zh":"在劇院中，前台職員檢查門票並帶領觀眾入座。"},{"en":"Museums need front-of-house staff to manage queues and answer visitor questions.","zh":"博物館需要前台職員管理隊伍和回答訪客問題。"},{"en":"This phrase contrasts public-facing staff with behind-the-scenes staff.","zh":"這個短語把面向公眾的員工與幕後員工作對比。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":14},{"front":"technicians","meaning":"技術員","examples":[{"en":"Technicians are needed to support blockbuster exhibitions.","zh":"大型熱門展覽需要技術員支援。"},{"en":"Technicians are skilled workers who install, repair, or operate technical equipment.","zh":"technicians 指安裝、維修或操作技術設備的熟練工人。"},{"en":"A school concert needs technicians to manage microphones, lights, and screens.","zh":"學校音樂會需要技術員管理咪高峰、燈光和螢幕。"},{"en":"Museum technicians help set up display cases, lighting, sound, and digital systems.","zh":"博物館技術員協助設置展示櫃、燈光、聲音和數碼系統。"},{"en":"This word focuses on practical technical expertise.","zh":"這個詞著重實際技術專長。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":14},{"front":"promotion staff","meaning":"宣傳職員","examples":[{"en":"Promotion staff help publicise blockbuster exhibitions.","zh":"宣傳職員幫助宣傳大型熱門展覽。"},{"en":"Promotion staff are workers who advertise events, products, or services to the public.","zh":"promotion staff 指向公眾宣傳活動、產品或服務的員工。"},{"en":"Promotion staff may write social media posts, posters, and press releases.","zh":"宣傳職員可能撰寫社交媒體帖文、海報和新聞稿。"},{"en":"Good promotion staff can increase ticket sales by reaching the right audience.","zh":"優秀宣傳職員可以透過接觸合適觀眾來增加門票銷售。"},{"en":"This phrase refers to people responsible for attracting attention.","zh":"這個短語指負責吸引注意的人員。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":14},{"front":"education and administration staff","meaning":"教育及行政職員","examples":[{"en":"Education and administration staff may perform additional tasks.","zh":"教育及行政職員可能需要執行額外工作。"},{"en":"Education and administration staff are workers who handle learning programmes and office organisation.","zh":"education and administration staff 指負責學習活動和辦公室組織的員工。"},{"en":"In a museum, education staff may design school workshops while administration staff handle bookings.","zh":"在博物館中，教育職員可能設計學校工作坊，而行政職員處理預約。"},{"en":"Large exhibitions can increase the workload for education and administration staff.","zh":"大型展覽可以增加教育及行政職員的工作量。"},{"en":"This phrase covers both teaching-related and office-related workers.","zh":"這個短語涵蓋與教學相關和辦公室相關的員工。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":14},{"front":"perform additional tasks","meaning":"執行額外工作","examples":[{"en":"Staff are required to perform additional tasks during blockbusters.","zh":"在大型熱門展覽期間，員工被要求執行額外工作。"},{"en":"To perform additional tasks means to do extra duties beyond normal work.","zh":"perform additional tasks 指做正常工作以外的額外職責。"},{"en":"Teachers may perform additional tasks during exam season, such as checking papers and supervising rooms.","zh":"考試季節期間，老師可能執行額外工作，例如改卷和監考。"},{"en":"Extra tasks can help an event succeed, but they may also tire staff.","zh":"額外工作可以幫助活動成功，但也可能令員工疲倦。"},{"en":"This phrase often appears when workload increases.","zh":"這個短語常在工作量增加時出現。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":15},{"front":"an increasing number of institutions","meaning":"越來越多機構","examples":[{"en":"An increasing number of institutions are staging blockbusters.","zh":"越來越多機構正在舉辦大型熱門展覽。"},{"en":"An increasing number of institutions means more and more organisations over time.","zh":"an increasing number of institutions 指隨時間有越來越多組織。"},{"en":"An increasing number of schools are using tablets in lessons.","zh":"越來越多學校在課堂中使用平板電腦。"},{"en":"When an increasing number of institutions enter the same market, competition becomes stronger.","zh":"當越來越多機構進入同一市場，競爭會變得更強。"},{"en":"This phrase shows a growing trend.","zh":"這個短語顯示增長趨勢。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":15},{"front":"try their hand at","meaning":"嘗試","examples":[{"en":"Many institutions try their hand at staging blockbuster exhibitions.","zh":"許多機構嘗試舉辦大型熱門展覽。"},{"en":"To try their hand at something means to attempt something for the first time or as a new challenge.","zh":"try their hand at something 指首次或作為新挑戰嘗試某事。"},{"en":"A student may try her hand at public speaking by joining a debate.","zh":"學生可能透過參加辯論來嘗試公開演說。"},{"en":"Small museums may try their hand at blockbusters after seeing larger museums succeed.","zh":"小型博物館看見大型博物館成功後，可能嘗試舉辦大型熱門展覽。"},{"en":"This phrase sounds informal and suggests experimentation.","zh":"這個短語較口語，表示實驗性嘗試。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":15},{"front":"memberships","meaning":"會員人數","examples":[{"en":"Blockbusters may increase visitor numbers and memberships.","zh":"大型熱門展覽可能增加訪客人數和會員人數。"},{"en":"Memberships are paid or registered relationships that give people special access or benefits.","zh":"memberships 指付費或登記後可獲特別入場或福利的會員關係。"},{"en":"A museum membership may give free entry, shop discounts, and early booking.","zh":"博物館會員資格可能提供免費入場、商店折扣和優先預訂。"},{"en":"Popular exhibitions can encourage visitors to buy memberships for future visits.","zh":"受歡迎展覽可以鼓勵訪客購買會員資格，以便日後參觀。"},{"en":"This word often connects regular visitors with long-term support.","zh":"這個詞常把固定訪客與長期支持連繫起來。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":15},{"front":"continue to provide a surplus","meaning":"繼續提供盈餘","examples":[{"en":"Blockbusters may not continue to provide a surplus.","zh":"大型熱門展覽未必能繼續提供盈餘。"},{"en":"To continue to provide a surplus means to keep producing extra money after costs are paid.","zh":"continue to provide a surplus 指在支付成本後仍持續產生額外金錢。"},{"en":"A charity event may fail to continue to provide a surplus if ticket sales fall.","zh":"如果門票銷售下降，慈善活動可能無法繼續提供盈餘。"},{"en":"As more museums hold blockbusters, each one may earn less extra money.","zh":"隨着更多博物館舉辦大型熱門展覽，每個展覽可能賺到較少額外金錢。"},{"en":"This phrase warns that past financial success may not last.","zh":"這個短語提醒我們，過去的財務成功未必能持續。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":15},{"front":"subsidise other activities","meaning":"資助其他活動","examples":[{"en":"A blockbuster surplus can subsidise other activities.","zh":"大型熱門展覽的盈餘可以資助其他活動。"},{"en":"To subsidise other activities means to use money from one source to help pay for other work.","zh":"subsidise other activities 指用一個來源的金錢幫助支付其他工作。"},{"en":"A profitable café may subsidise free community classes.","zh":"賺錢的咖啡店可能資助免費社區課程。"},{"en":"Museums may use blockbuster income to subsidise quiet but important education programmes.","zh":"博物館可能使用大型熱門展覽收入資助較冷門但重要的教育計劃。"},{"en":"This phrase shows money being used to support something that may not pay for itself.","zh":"這個短語顯示金錢被用來支持未必能自負盈虧的事。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":15},{"front":"due to","meaning":"由於","examples":[{"en":"Surpluses may fall due to the competitive nature of the market.","zh":"由於市場的競爭性，盈餘可能下降。"},{"en":"Due to means because of.","zh":"due to 指由於或因為。"},{"en":"The school picnic was cancelled due to heavy rain.","zh":"學校旅行由於大雨而取消。"},{"en":"Museum profits may fall due to higher costs and stronger competition.","zh":"博物館利潤可能由於成本上升和競爭加劇而下降。"},{"en":"This phrase introduces the reason for a result.","zh":"這個短語引出結果的原因。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":15},{"front":"competitive nature of the market","meaning":"市場的競爭性","examples":[{"en":"The competitive nature of the market may reduce blockbuster profits.","zh":"市場的競爭性可能減少大型熱門展覽的利潤。"},{"en":"The competitive nature of the market means businesses or institutions must compete for customers and money.","zh":"competitive nature of the market 指企業或機構必須爭奪顧客和金錢。"},{"en":"Restaurants face the competitive nature of the market when many similar shops open nearby.","zh":"當附近開了許多類似餐廳，餐廳就面對市場的競爭性。"},{"en":"If many museums offer blockbusters, visitors have more choices and profits may fall.","zh":"如果許多博物館都提供大型熱門展覽，訪客選擇更多，利潤可能下降。"},{"en":"This phrase explains why success becomes harder when many players compete.","zh":"這個短語解釋為何當許多參與者競爭時，成功會更困難。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":15},{"front":"consumer dollars","meaning":"消費者金錢","examples":[{"en":"There are only so many consumer dollars to go around.","zh":"可供分配的消費者金錢只有那麼多。"},{"en":"Consumer dollars means the money that customers are able or willing to spend.","zh":"consumer dollars 指顧客能夠或願意花費的金錢。"},{"en":"During a recession, restaurants compete harder for limited consumer dollars.","zh":"經濟衰退期間，餐廳更激烈地爭奪有限的消費者金錢。"},{"en":"Museums, cinemas, and concerts all compete for the same consumer dollars.","zh":"博物館、戲院和音樂會都在爭奪同一批消費者金錢。"},{"en":"This phrase reminds us that public spending is limited.","zh":"這個短語提醒我們，公眾消費是有限的。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":15},{"front":"to go around","meaning":"可供分配","examples":[{"en":"There are only so many consumer dollars to go around.","zh":"可供分配的消費者金錢只有那麼多。"},{"en":"To go around means to be available for everyone who needs or wants a share.","zh":"to go around 指足夠分給所有需要或想要一份的人。"},{"en":"If there are not enough chairs to go around, some students must stand.","zh":"如果沒有足夠椅子可供分配，有些學生就必須站著。"},{"en":"When money is limited, there may not be enough funding to go around.","zh":"當金錢有限時，可能沒有足夠資金可供分配。"},{"en":"This phrase highlights shortage or limited distribution.","zh":"這個短語強調短缺或有限分配。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":15},{"front":"choose between","meaning":"在……之間選擇","examples":[{"en":"Visitors may need to choose between different blockbuster products.","zh":"訪客可能需要在不同大型熱門展覽產品之間選擇。"},{"en":"To choose between things means to decide which one you want when there are two or more options.","zh":"choose between things 指在兩個或以上選項中決定想要哪一個。"},{"en":"A student may choose between joining the music club and the football team.","zh":"學生可能需要在音樂學會和足球隊之間選擇。"},{"en":"When many exhibitions open at the same time, visitors must choose between them.","zh":"當許多展覽同時開放時，訪客必須在它們之間選擇。"},{"en":"This phrase suggests that people cannot have or do everything.","zh":"這個短語表示人們不能擁有或做所有事情。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":16},{"front":"blockbuster products","meaning":"大型熱門展覽產品","examples":[{"en":"Visitors may choose between competing blockbuster products.","zh":"訪客可能在互相競爭的大型熱門展覽產品之間選擇。"},{"en":"Blockbuster products are major popular exhibitions or experiences treated like things sold to consumers.","zh":"blockbuster products 指被當作消費產品銷售的大型熱門展覽或體驗。"},{"en":"A museum may package an exhibition, shop items, and dining events as blockbuster products.","zh":"博物館可能把展覽、商店商品和餐飲活動包裝成大型熱門展覽產品。"},{"en":"When too many blockbuster products compete, each may attract fewer visitors.","zh":"當太多大型熱門展覽產品互相競爭，每一個可能吸引較少訪客。"},{"en":"This phrase shows the commercial side of cultural exhibitions.","zh":"這個短語顯示文化展覽的商業面。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":16},{"front":"mounting blockbuster exhibitions","meaning":"舉辦大型熱門展覽","examples":[{"en":"Mounting blockbuster exhibitions can be exhausting for staff.","zh":"舉辦大型熱門展覽可能令員工筋疲力盡。"},{"en":"Mounting blockbuster exhibitions means preparing, organising, and presenting major popular exhibitions.","zh":"mounting blockbuster exhibitions 指準備、組織並呈現大型熱門展覽。"},{"en":"A museum mounting a blockbuster exhibition must arrange loans, transport, marketing, and staff.","zh":"博物館舉辦大型熱門展覽時，必須安排借展、運輸、市場推廣和員工。"},{"en":"This work can be exhausting because many departments face extra pressure.","zh":"這項工作可能令人筋疲力盡，因為許多部門面對額外壓力。"},{"en":"The phrase focuses on the effort of putting an exhibition together.","zh":"這個短語著重把展覽組織起來所需的努力。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":16},{"front":"be hard to maintain","meaning":"難以維持","examples":[{"en":"A profit-focused objective can be hard to maintain.","zh":"以利潤為重的目標可能難以維持。"},{"en":"To be hard to maintain means to be difficult to continue over time.","zh":"be hard to maintain 指隨時間持續下去有困難。"},{"en":"A strict study schedule is hard to maintain if a student sleeps too late.","zh":"如果學生太晚睡，嚴格溫習時間表就難以維持。"},{"en":"High profits are hard to maintain when more competitors enter the market.","zh":"當更多競爭者進入市場，高利潤就難以維持。"},{"en":"This phrase shows that something may work at first but become difficult later.","zh":"這個短語顯示某事最初可能有效，但之後變得困難。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":16},{"front":"exhausting for staff","meaning":"令職員筋疲力盡","examples":[{"en":"Creating or hiring blockbusters is exhausting for staff.","zh":"創作或租用大型熱門展覽令職員筋疲力盡。"},{"en":"Exhausting for staff means making workers extremely tired because of heavy demands.","zh":"exhausting for staff 指因工作要求沉重而令員工極度疲倦。"},{"en":"A week of long queues and late closing times can be exhausting for staff.","zh":"一星期長隊和延遲閉館可能令職員筋疲力盡。"},{"en":"If extra work continues for months, it may reduce morale and service quality.","zh":"如果額外工作持續數月，可能降低士氣和服務質素。"},{"en":"This phrase focuses on the human cost of a project.","zh":"這個短語著重項目的人力代價。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":16},{"front":"throughout an institution","meaning":"遍及整個機構","examples":[{"en":"The real costs are felt throughout an institution.","zh":"真正成本會遍及整個機構被感受到。"},{"en":"Throughout an institution means across the whole organisation, not only one department.","zh":"throughout an institution 指遍及整個組織，而不只是一個部門。"},{"en":"A new computer system may cause changes throughout an institution.","zh":"新電腦系統可能在整個機構中造成改變。"},{"en":"A blockbuster affects staff throughout an institution because many teams must support it.","zh":"大型熱門展覽影響整個機構的員工，因為許多團隊都必須支援它。"},{"en":"This phrase emphasises wide internal impact.","zh":"這個短語強調廣泛的內部影響。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":16},{"front":"difficult to calculate","meaning":"難以計算","examples":[{"en":"The real costs of a blockbuster are difficult to calculate.","zh":"大型熱門展覽的真正成本難以計算。"},{"en":"Difficult to calculate means hard to measure or work out accurately.","zh":"difficult to calculate 指難以準確量度或算出。"},{"en":"The true cost of moving house is difficult to calculate because small expenses keep appearing.","zh":"搬屋的真正成本難以計算，因為小額開支不斷出現。"},{"en":"Staff time can be difficult to calculate when people help outside normal duties.","zh":"當人們在正常職責以外幫忙時，員工時間可能難以計算。"},{"en":"This phrase suggests uncertainty in numbers.","zh":"這個短語表示數字上存在不確定性。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":16},{"front":"direct aims","meaning":"直接目的","examples":[{"en":"The direct aims of a blockbuster may be financial.","zh":"大型熱門展覽的直接目的可能是財務上的。"},{"en":"Direct aims are the clear and immediate goals of an action or project.","zh":"direct aims 指某行動或項目的清楚而即時目標。"},{"en":"The direct aim of a fire drill is to practise leaving the building safely.","zh":"消防演習的直接目的是練習安全離開建築物。"},{"en":"A museum’s direct aims may include visitor numbers, income, and public attention.","zh":"博物館的直接目的可能包括訪客人數、收入和公眾關注。"},{"en":"This phrase separates immediate goals from wider side effects.","zh":"這個短語把即時目標與更廣泛的連帶效果分開。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":16},{"front":"positive spin-offs","meaning":"正面連帶效益","examples":[{"en":"Creating a blockbuster can have many positive spin-offs.","zh":"創作大型熱門展覽可以帶來許多正面連帶效益。"},{"en":"Positive spin-offs are extra good results that happen in addition to the main aim.","zh":"positive spin-offs 指主要目的以外出現的額外好結果。"},{"en":"A school sports day may have positive spin-offs, such as stronger friendships and better teamwork.","zh":"學校運動會可能有正面連帶效益，例如更強友誼和更好團隊合作。"},{"en":"A museum blockbuster may bring positive spin-offs for local shops and restaurants.","zh":"博物館大型熱門展覽可能為本地商店和餐廳帶來正面連帶效益。"},{"en":"This phrase focuses on useful side benefits.","zh":"這個短語著重有用的附帶好處。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":16},{"front":"raise one’s profile","meaning":"提升知名度","examples":[{"en":"A popular blockbuster can raise a museum’s profile.","zh":"受歡迎的大型熱門展覽可以提升博物館的知名度。"},{"en":"To raise one’s profile means to make a person or organisation more widely known and respected.","zh":"raise one’s profile 指令某人或機構更廣為人知並更受重視。"},{"en":"Winning an award can raise a teacher’s profile in the education community.","zh":"獲獎可以提升老師在教育界的知名度。"},{"en":"A successful exhibition can raise a museum’s profile before funding decisions are made.","zh":"成功展覽可以在資助決定前提升博物館知名度。"},{"en":"This phrase connects success with visibility and reputation.","zh":"這個短語把成功與曝光度和聲譽連繫起來。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":16},{"front":"be seen in a more favourable light","meaning":"被較正面地看待","examples":[{"en":"A museum may be seen in a more favourable light after a blockbuster.","zh":"博物館在大型熱門展覽後可能被較正面地看待。"},{"en":"To be seen in a more favourable light means to be judged more positively than before.","zh":"be seen in a more favourable light 指比以前得到更正面的評價。"},{"en":"A company may be seen in a more favourable light after improving customer service.","zh":"公司改善顧客服務後，可能被較正面地看待。"},{"en":"Museums may be seen more favourably when they attract visitors and support the local economy.","zh":"當博物館吸引訪客並支持本地經濟時，可能被較正面地看待。"},{"en":"This phrase focuses on improved public opinion.","zh":"這個短語著重公眾觀感改善。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":17},{"front":"at budget time","meaning":"在編制預算時","examples":[{"en":"A higher profile may help a museum at budget time.","zh":"較高知名度可能在編制預算時幫助博物館。"},{"en":"At budget time means when money is being planned, requested, or allocated.","zh":"at budget time 指規劃、申請或分配金錢的時候。"},{"en":"Schools prepare carefully at budget time because they must explain what funding they need.","zh":"學校在編制預算時會仔細準備，因為必須解釋需要甚麼資金。"},{"en":"A successful public event can help an organisation at budget time.","zh":"成功的公共活動可以在編制預算時幫助機構。"},{"en":"This phrase refers to the period when financial decisions are made.","zh":"這個短語指作出財務決定的時期。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":17},{"front":"be good for the local economy","meaning":"對本地經濟有利","examples":[{"en":"Large crowds are good for the local economy.","zh":"大量人群對本地經濟有利。"},{"en":"To be good for the local economy means to help local businesses, jobs, and spending.","zh":"be good for the local economy 指有助本地企業、就業和消費。"},{"en":"A weekend market is good for the local economy if it brings customers to nearby shops.","zh":"如果週末市集為附近商店帶來顧客，它就對本地經濟有利。"},{"en":"Museum visitors may spend money on transport, food, hotels, and souvenirs.","zh":"博物館訪客可能在交通、食物、酒店和紀念品上消費。"},{"en":"This phrase shows how one event can benefit a wider area.","zh":"這個短語顯示一個活動如何令更大地區受惠。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":17},{"front":"increased employment","meaning":"增加就業","examples":[{"en":"Blockbusters may provide increased employment for local businesses.","zh":"大型熱門展覽可能為本地企業提供增加就業的機會。"},{"en":"Increased employment means more jobs or more work opportunities.","zh":"increased employment 指更多工作或更多就業機會。"},{"en":"A new shopping centre can create increased employment for cleaners, shop assistants, and security staff.","zh":"新商場可以為清潔工、店員和保安創造增加就業。"},{"en":"A popular exhibition may lead to increased employment in cafés, hotels, and transport.","zh":"受歡迎展覽可能在咖啡店、酒店和運輸業帶來增加就業。"},{"en":"This phrase focuses on job growth.","zh":"這個短語著重工作增長。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":17},{"front":"transport industry","meaning":"運輸業","examples":[{"en":"Blockbusters can benefit the transport industry.","zh":"大型熱門展覽可以令運輸業受惠。"},{"en":"The transport industry includes businesses that move people or goods, such as buses, trains, taxis, and delivery services.","zh":"transport industry 包括運送人或貨物的企業，例如巴士、火車、的士和送貨服務。"},{"en":"A large festival can benefit the transport industry when many people need rides.","zh":"大型節日令許多人需要乘車時，可以令運輸業受惠。"},{"en":"Museum crowds may increase demand for trains, buses, taxis, and parking.","zh":"博物館人潮可能增加火車、巴士、的士和泊車需求。"},{"en":"This phrase refers to transport as an economic sector.","zh":"這個短語把運輸視為一個經濟行業。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":17},{"front":"retailers","meaning":"零售商","examples":[{"en":"Retailers may benefit from the crowds drawn by blockbusters.","zh":"零售商可能從大型熱門展覽吸引的人群中受惠。"},{"en":"Retailers are businesses that sell goods directly to customers.","zh":"retailers 指直接向顧客售賣商品的企業。"},{"en":"Bookshops, souvenir shops, clothing stores, and convenience stores are retailers.","zh":"書店、紀念品店、服裝店和便利店都是零售商。"},{"en":"When museum visitors walk through a shopping district, nearby retailers may earn more.","zh":"當博物館訪客經過購物區，附近零售商可能賺得更多。"},{"en":"This word focuses on shops selling to the public.","zh":"這個詞著重向公眾售賣商品的店舖。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":17},{"front":"expose staff to","meaning":"使職員接觸到","examples":[{"en":"Blockbusters expose staff to the pressures of the marketplace.","zh":"大型熱門展覽使職員接觸到市場壓力。"},{"en":"To expose staff to something means to make workers experience or face it.","zh":"expose staff to something 指使員工經歷或面對某事。"},{"en":"Customer complaints expose staff to pressure and require calm communication.","zh":"顧客投訴使職員接觸到壓力，並需要冷靜溝通。"},{"en":"Large exhibitions expose museum staff to deadlines, crowds, and commercial expectations.","zh":"大型展覽使博物館職員接觸到期限、人潮和商業期望。"},{"en":"This phrase can describe both useful experience and difficult pressure.","zh":"這個短語可以描述有用經驗，也可以描述困難壓力。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":17},{"front":"vagaries and pressures","meaning":"變幻莫測和壓力","examples":[{"en":"Staff face the vagaries and pressures of the marketplace.","zh":"職員面對市場的變幻莫測和壓力。"},{"en":"Vagaries and pressures are unpredictable changes and difficult demands.","zh":"vagaries and pressures 指難以預測的變化和困難要求。"},{"en":"A small restaurant faces the vagaries and pressures of changing customer tastes.","zh":"小餐廳面對顧客口味變化的變幻莫測和壓力。"},{"en":"Museums face these pressures when ticket sales depend on public interest.","zh":"當門票銷售取決於公眾興趣時，博物館會面對這些壓力。"},{"en":"This phrase suggests uncertainty plus stress.","zh":"這個短語表示不確定性加上壓力。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":17},{"front":"the marketplace","meaning":"市場","examples":[{"en":"Museum staff are increasingly exposed to the marketplace.","zh":"博物館職員越來越接觸到市場。"},{"en":"The marketplace means the world of buyers, sellers, competition, demand, and prices.","zh":"the marketplace 指買家、賣家、競爭、需求和價格構成的商業世界。"},{"en":"A company must understand the marketplace before launching a new product.","zh":"公司推出新產品前，必須理解市場。"},{"en":"Museums enter the marketplace when they compete for visitors’ time and money.","zh":"當博物館爭奪訪客時間和金錢時，它們就進入市場。"},{"en":"This phrase refers to commercial reality, not a physical market only.","zh":"這個短語指商業現實，而不只是實體市場。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":17},{"front":"lead to creative excellence","meaning":"帶來創意上的卓越表現","examples":[{"en":"Market pressure may lead to creative excellence.","zh":"市場壓力可能帶來創意上的卓越表現。"},{"en":"To lead to creative excellence means to produce very high-quality creative work as a result.","zh":"lead to creative excellence 指結果產生非常高質素的創意作品。"},{"en":"Competition can lead to creative excellence when designers try harder to impress users.","zh":"當設計師更努力打動使用者時，競爭可以帶來創意上的卓越表現。"},{"en":"Museums may produce better exhibitions when market pressure pushes them to be clearer and more engaging.","zh":"當市場壓力推動博物館更清晰、更吸引時，它們可能製作更好的展覽。"},{"en":"This phrase suggests that pressure can sometimes improve creativity.","zh":"這個短語表示壓力有時可以改善創意。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":17},{"front":"success or failure of","meaning":"……的成功或失敗","examples":[{"en":"The success or failure of a blockbuster may reveal strategic problems.","zh":"大型熱門展覽的成功或失敗可能揭示策略問題。"},{"en":"The success or failure of something means whether it achieves its goals or does not.","zh":"success or failure of something 指某事是否達成目標。"},{"en":"The success or failure of a school project may depend on planning and teamwork.","zh":"學校項目的成功或失敗可能取決於計劃和團隊合作。"},{"en":"Museums study the success or failure of exhibitions to improve future decisions.","zh":"博物館研究展覽的成功或失敗，以改善未來決策。"},{"en":"This phrase encourages evaluation after an event.","zh":"這個短語鼓勵活動後進行評估。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":18},{"front":"highlight the need for","meaning":"突顯……的需要","examples":[{"en":"A failed blockbuster may highlight the need for new strategies.","zh":"失敗的大型熱門展覽可能突顯新策略的需要。"},{"en":"To highlight the need for something means to make people clearly see that it is necessary.","zh":"highlight the need for something 指令人清楚看見某事是必要的。"},{"en":"A traffic accident may highlight the need for safer road crossings.","zh":"交通意外可能突顯更安全過路設施的需要。"},{"en":"Low visitor numbers may highlight the need for better museum marketing.","zh":"低訪客人數可能突顯改善博物館市場推廣的需要。"},{"en":"This phrase shows that a problem can reveal what must change.","zh":"這個短語顯示問題可以揭示需要改變之處。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":18},{"front":"managers and policymakers","meaning":"管理人員和政策制定者","examples":[{"en":"Managers and policymakers may need to rethink their strategies.","zh":"管理人員和政策制定者可能需要重新思考策略。"},{"en":"Managers and policymakers are people who run organisations and people who make rules or public decisions.","zh":"managers and policymakers 指管理機構的人，以及制定規則或公共決策的人。"},{"en":"School managers and policymakers may discuss how to reduce student stress.","zh":"學校管理人員和政策制定者可能討論如何減少學生壓力。"},{"en":"Museum managers and policymakers decide funding, priorities, and long-term direction.","zh":"博物館管理人員和政策制定者決定資金、優先事項和長遠方向。"},{"en":"This phrase connects practical leadership with wider policy decisions.","zh":"這個短語把實際領導與更廣泛政策決策連繫起來。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":18},{"front":"rethink their strategies","meaning":"重新思考策略","examples":[{"en":"Museum managers may need to rethink their strategies.","zh":"博物館管理人員可能需要重新思考策略。"},{"en":"To rethink their strategies means to consider plans again and possibly change them.","zh":"rethink their strategies 指重新考慮計劃，並可能作出改變。"},{"en":"A student may rethink her strategies after failing a mock exam.","zh":"學生模擬試失敗後，可能重新思考自己的策略。"},{"en":"If a blockbuster loses money, managers may rethink their strategies for future exhibitions.","zh":"如果大型熱門展覽虧錢，管理人員可能重新思考未來展覽策略。"},{"en":"This phrase suggests learning from results rather than repeating the same plan.","zh":"這個短語表示從結果中學習，而不是重複同一計劃。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":18},{"front":"apparent trend towards","meaning":"走向……的明顯趨勢","examples":[{"en":"There is an apparent trend towards blockbuster exhibitions.","zh":"有一個走向大型熱門展覽的明顯趨勢。"},{"en":"An apparent trend towards something is a visible movement in that direction.","zh":"apparent trend towards something 指清楚可見地朝某方向發展。"},{"en":"There is an apparent trend towards online shopping among busy workers.","zh":"忙碌上班族之中，有一個走向網上購物的明顯趨勢。"},{"en":"If more museums choose blockbusters, this shows an apparent trend towards commercial exhibitions.","zh":"如果更多博物館選擇大型熱門展覽，這顯示走向商業展覽的明顯趨勢。"},{"en":"Apparent means it seems clear, though it may still need evidence.","zh":"apparent 指看起來清楚，但仍可能需要證據支持。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":18},{"front":"make it likely that","meaning":"令……變得可能","examples":[{"en":"The trend makes it likely that museums will be seen as entertainment venues.","zh":"這個趨勢令博物館被視為娛樂場地變得可能。"},{"en":"To make it likely that something will happen means to increase the chance that it will happen.","zh":"make it likely that something will happen 指增加某事發生的可能性。"},{"en":"Dark clouds make it likely that the sports day will be delayed.","zh":"烏雲令運動會延遲變得可能。"},{"en":"More blockbuster exhibitions make it likely that museums will be linked with entertainment.","zh":"更多大型熱門展覽令博物館與娛樂連繫起來變得可能。"},{"en":"This phrase connects a condition with a probable result.","zh":"這個短語把條件與可能結果連繫起來。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":18},{"front":"entertainment and tourism industry","meaning":"娛樂及旅遊業","examples":[{"en":"Museums may be seen as part of the entertainment and tourism industry.","zh":"博物館可能被視為娛樂及旅遊業的一部分。"},{"en":"The entertainment and tourism industry includes businesses that provide leisure, fun, travel, and visitor experiences.","zh":"entertainment and tourism industry 包括提供休閒、娛樂、旅行和訪客體驗的企業。"},{"en":"Theme parks, tours, hotels, and shows are part of the entertainment and tourism industry.","zh":"主題公園、旅遊團、酒店和表演都屬於娛樂及旅遊業。"},{"en":"If museums join this industry too closely, their educational role may be questioned.","zh":"如果博物館太貼近這個行業，其教育角色可能受到質疑。"},{"en":"This phrase places museums in a commercial leisure context.","zh":"這個短語把博物館放在商業休閒背景中。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":18},{"front":"cultural icons","meaning":"文化標誌","examples":[{"en":"Museums may no longer be seen mainly as cultural icons.","zh":"博物館可能不再主要被視為文化標誌。"},{"en":"Cultural icons are people, places, or institutions widely seen as symbols of culture.","zh":"cultural icons 指被廣泛視為文化象徵的人、地方或機構。"},{"en":"A historic theatre can become one of a city’s cultural icons.","zh":"歷史劇院可以成為一個城市的文化標誌之一。"},{"en":"If museums become too commercial, people may stop seeing them mainly as cultural icons.","zh":"如果博物館變得太商業化，人們可能不再主要把它們視為文化標誌。"},{"en":"This phrase suggests symbolic cultural importance.","zh":"這個短語表示象徵性的文化重要性。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":18},{"front":"deserving of","meaning":"值得得到","examples":[{"en":"Cultural institutions may be deserving of government support.","zh":"文化機構可能值得得到政府支持。"},{"en":"Deserving of something means worthy of receiving it.","zh":"deserving of something 指值得獲得某事物。"},{"en":"A hardworking student may be deserving of praise after making real progress.","zh":"努力學生取得真正進步後，可能值得得到讚賞。"},{"en":"Museums may be deserving of support if they educate the public and preserve history.","zh":"如果博物館教育公眾並保存歷史，就可能值得得到支持。"},{"en":"This phrase is used when judging whether someone or something merits help or respect.","zh":"這個短語用於判斷某人或某事是否值得幫助或尊重。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":18},{"front":"government and philanthropic support","meaning":"政府及慈善支持","examples":[{"en":"Museums may depend on government and philanthropic support.","zh":"博物館可能依賴政府及慈善支持。"},{"en":"Government and philanthropic support means help from public authorities and charitable donors.","zh":"government and philanthropic support 指來自公共機關和慈善捐助者的幫助。"},{"en":"A community arts centre may survive through government and philanthropic support.","zh":"社區藝術中心可能靠政府及慈善支持生存。"},{"en":"Without such support, museums may rely more heavily on ticket sales and commercial events.","zh":"沒有這些支持，博物館可能更依賴門票銷售和商業活動。"},{"en":"This phrase refers to non-commercial funding sources.","zh":"這個短語指非商業資金來源。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":18},{"front":"best pathway to take","meaning":"最佳取向；最佳路線","examples":[{"en":"The best pathway to take may be a balance between blockbusters and regular exhibitions.","zh":"最佳取向可能是在大型熱門展覽和常規展覽之間取得平衡。"},{"en":"The best pathway to take means the most suitable course of action.","zh":"best pathway to take 指最合適的行動方向。"},{"en":"For a student who is tired, the best pathway to take may be shorter but regular study sessions.","zh":"對疲倦學生而言，最佳取向可能是較短但規律的溫習時段。"},{"en":"Museums may choose a balanced pathway to protect culture while attracting visitors.","zh":"博物館可能選擇平衡路線，以保護文化並吸引訪客。"},{"en":"This phrase is used when deciding between possible directions.","zh":"這個短語用於在不同可能方向之間作決定。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":19},{"front":"balance both","meaning":"平衡兩者","examples":[{"en":"Museums may need to balance both blockbusters and regular exhibitions.","zh":"博物館可能需要平衡大型熱門展覽和常規展覽兩者。"},{"en":"To balance both means to give proper attention to two different needs or choices.","zh":"balance both 指對兩種不同需要或選擇都給予適當注意。"},{"en":"Students must balance both study and rest to avoid burnout.","zh":"學生必須平衡學習和休息兩者，以避免過度疲勞。"},{"en":"Museums balance both income and education when planning their programmes.","zh":"博物館規劃活動時，需要平衡收入和教育兩者。"},{"en":"This phrase shows that neither side should be ignored.","zh":"這個短語表示兩方面都不應被忽視。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":19},{"front":"regular exhibitions","meaning":"常規展覽","examples":[{"en":"Regular exhibitions still need support alongside blockbusters.","zh":"常規展覽仍需要與大型熱門展覽並行得到支持。"},{"en":"Regular exhibitions are normal museum shows that are not major blockbuster events.","zh":"regular exhibitions 指不是大型熱門活動的一般博物館展覽。"},{"en":"A local history display may be a regular exhibition that serves the community all year.","zh":"本地歷史展示可能是全年服務社群的常規展覽。"},{"en":"Regular exhibitions can teach important topics even if they attract fewer visitors.","zh":"常規展覽即使吸引較少訪客，也可以教授重要題材。"},{"en":"This phrase contrasts ordinary ongoing displays with large high-profile shows.","zh":"這個短語把普通持續展示與大型高調展覽作對比。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":19},{"front":"easy middle ground","meaning":"容易的折衷方案","examples":[{"en":"The balanced approach may seem like an easy middle ground.","zh":"平衡取向可能看似一個容易的折衷方案。"},{"en":"An easy middle ground is a compromise that appears simple and acceptable to both sides.","zh":"easy middle ground 指看起來簡單且雙方可接受的妥協方案。"},{"en":"Letting students use phones only during breaks may seem like an easy middle ground.","zh":"只允許學生在小息使用手機，可能看似容易的折衷方案。"},{"en":"A middle ground may sound fair but still fail if practical conditions are missing.","zh":"折衷方案聽起來公平，但如果缺少實際條件，仍可能失敗。"},{"en":"This phrase suggests compromise, but not always a simple solution.","zh":"這個短語表示妥協，但不一定是真正簡單的解決方法。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":19},{"front":"only work if","meaning":"只有在……情況下才行得通","examples":[{"en":"This middle ground may only work if the museum has enough space.","zh":"這個折衷方案可能只有在博物館有足夠空間時才行得通。"},{"en":"Only work if means succeed only under a particular condition.","zh":"only work if 指只有在特定條件下才會成功。"},{"en":"Group study will only work if everyone prepares before the meeting.","zh":"小組溫習只有在每個人會前準備好時才行得通。"},{"en":"Running blockbusters and regular exhibitions together may only work if space and funding are available.","zh":"同時舉辦大型熱門展覽和常規展覽，可能只有在有空間和資金時才行得通。"},{"en":"This phrase sets a necessary condition for success.","zh":"這個短語設定成功的必要條件。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":19},{"front":"enough space","meaning":"足夠空間","examples":[{"en":"Museums need enough space to run both blockbusters and regular exhibitions.","zh":"博物館需要足夠空間來同時舉辦大型熱門展覽和常規展覽。"},{"en":"Enough space means sufficient room for the activity or purpose.","zh":"enough space 指有足夠地方進行某活動或用途。"},{"en":"A classroom needs enough space for students to move safely between desks.","zh":"課室需要足夠空間讓學生安全地在桌子之間走動。"},{"en":"Without enough space, museums may have to replace regular exhibitions with blockbusters.","zh":"沒有足夠空間，博物館可能要用大型熱門展覽取代常規展覽。"},{"en":"This phrase refers to a practical physical limit.","zh":"這個短語指實際的物理限制。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":19},{"front":"alternate sources of funding","meaning":"其他資金來源","examples":[{"en":"Museums need alternate sources of funding for regular exhibitions.","zh":"博物館需要其他資金來源來支持常規展覽。"},{"en":"Alternate sources of funding are other ways to get money besides the usual source.","zh":"alternate sources of funding 指正常來源以外取得金錢的其他方法。"},{"en":"A school may seek alternate sources of funding through donations or community grants.","zh":"學校可能透過捐款或社區資助尋找其他資金來源。"},{"en":"If ticket income is uncertain, museums need alternate sources of funding.","zh":"如果門票收入不穩定，博物館就需要其他資金來源。"},{"en":"This phrase shows the need for financial backup.","zh":"這個短語顯示需要財務後備。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":19},{"front":"continue to support","meaning":"繼續支持","examples":[{"en":"Museums need funding to continue to support regular exhibitions.","zh":"博物館需要資金來繼續支持常規展覽。"},{"en":"To continue to support something means to keep giving it money, time, help, or attention.","zh":"continue to support something 指持續給予某事金錢、時間、幫助或關注。"},{"en":"Parents may continue to support a child’s music lessons if progress is clear.","zh":"如果孩子進步明顯，父母可能繼續支持他的音樂課。"},{"en":"Museums must continue to support regular exhibitions even when blockbusters attract more attention.","zh":"即使大型熱門展覽吸引更多注意，博物館仍必須繼續支持常規展覽。"},{"en":"This phrase emphasises ongoing help, not one-time assistance.","zh":"這個短語強調持續幫助，而不是一次性協助。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":19},{"front":"less exciting fare","meaning":"較不刺激的常規內容","examples":[{"en":"Regular exhibitions may be seen as less exciting fare.","zh":"常規展覽可能被視為較不刺激的常規內容。"},{"en":"Less exciting fare means material or activities that seem less thrilling than other choices.","zh":"less exciting fare 指比其他選擇顯得較不刺激的材料或活動。"},{"en":"A simple lecture may look like less exciting fare compared with a live performance.","zh":"與現場表演相比，簡單講座可能看似較不刺激的內容。"},{"en":"Regular museum displays may seem less exciting fare beside a famous international show.","zh":"常規博物館展示在著名國際展覽旁邊可能顯得較不刺激。"},{"en":"This phrase can sound slightly critical or dismissive.","zh":"這個短語可能帶有輕微批評或輕視意味。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":19},{"front":"make sure that","meaning":"確保","examples":[{"en":"Museums should make sure that their regular activities are enticing.","zh":"博物館應確保其常規活動具有吸引力。"},{"en":"To make sure that something happens means to check or act so it definitely happens.","zh":"make sure that something happens 指檢查或採取行動，確保某事發生。"},{"en":"Students should make sure that their names are written on exam papers.","zh":"學生應確保自己的名字寫在試卷上。"},{"en":"Museums should make sure that visitors can understand labels and directions.","zh":"博物館應確保訪客能理解標籤和方向指示。"},{"en":"This phrase focuses on careful checking or control.","zh":"這個短語著重仔細檢查或控制。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":19},{"front":"regular activities","meaning":"常規活動","examples":[{"en":"Museums should improve their regular activities and exhibitions.","zh":"博物館應改善常規活動和展覽。"},{"en":"Regular activities are normal events or programmes that happen repeatedly or routinely.","zh":"regular activities 指反覆或按慣例進行的正常活動或計劃。"},{"en":"A school’s regular activities may include assemblies, clubs, and reading lessons.","zh":"學校的常規活動可能包括早會、學會和閱讀課。"},{"en":"Museums need regular activities to serve visitors between major exhibitions.","zh":"博物館需要常規活動，在大型展覽之間服務訪客。"},{"en":"This phrase refers to ordinary ongoing work, not special one-off events.","zh":"這個短語指普通持續工作，而不是特別一次性活動。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":20},{"front":"more enticing","meaning":"更吸引","examples":[{"en":"Regular exhibitions should be made more enticing.","zh":"常規展覽應被做得更吸引。"},{"en":"More enticing means more attractive, interesting, or tempting.","zh":"more enticing 指更有吸引力、更有趣或更令人想參與。"},{"en":"A library can make reading more enticing by creating comfortable corners and book displays.","zh":"圖書館可以透過設立舒適角落和書籍展示令閱讀更吸引。"},{"en":"Museums make exhibitions more enticing when they use stories, sound, and interactive tasks.","zh":"博物館使用故事、聲音和互動任務時，可以令展覽更吸引。"},{"en":"This phrase focuses on increasing people’s desire to take part.","zh":"這個短語著重增加人們參與的意欲。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":20},{"front":"local community","meaning":"本地社群","examples":[{"en":"Museums should find out what their local community wants.","zh":"博物館應了解本地社群想要甚麼。"},{"en":"The local community is the group of people who live near or are closely connected to a place.","zh":"local community 指住在附近或與某地方密切相關的一群人。"},{"en":"A library serves its local community by offering children’s reading groups and elderly support.","zh":"圖書館透過兒童閱讀小組和長者支援服務本地社群。"},{"en":"If museums ignore the local community, their programmes may feel irrelevant.","zh":"如果博物館忽視本地社群，其活動可能顯得不相關。"},{"en":"This phrase focuses on nearby people, not only tourists.","zh":"這個短語著重附近居民，而不只是遊客。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":20},{"front":"tour to overseas venues","meaning":"巡迴到海外場地","examples":[{"en":"Museums ask what blockbusters they can tour to overseas venues.","zh":"博物館會問哪些大型熱門展覽可以巡迴到海外場地。"},{"en":"To tour to overseas venues means to send an exhibition to places in other countries.","zh":"tour to overseas venues 指把展覽送到其他國家的場地展出。"},{"en":"A museum may tour a successful exhibition to overseas venues to earn income and build reputation.","zh":"博物館可能把成功展覽巡迴到海外場地，以賺取收入和建立聲譽。"},{"en":"Touring overseas requires transport, insurance, translation, and partner institutions.","zh":"海外巡迴需要運輸、保險、翻譯和合作機構。"},{"en":"This phrase shows exhibitions moving internationally.","zh":"這個短語顯示展覽作國際移動。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":20},{"front":"overseas venues","meaning":"海外場地","examples":[{"en":"Some blockbusters may be toured to overseas venues.","zh":"有些大型熱門展覽可能巡迴到海外場地。"},{"en":"Overseas venues are event or exhibition places located in other countries.","zh":"overseas venues 指位於其他國家的活動或展覽場地。"},{"en":"A theatre company may perform at overseas venues during an international tour.","zh":"劇團可能在國際巡演期間於海外場地演出。"},{"en":"Museums choose overseas venues that can protect objects and attract audiences.","zh":"博物館會選擇能保護物件並吸引觀眾的海外場地。"},{"en":"This phrase focuses on foreign locations for public events.","zh":"這個短語著重公共活動的外國地點。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":20},{"front":"cost-effective","meaning":"符合成本效益","examples":[{"en":"Museums need to ask whether touring a blockbuster will be cost-effective.","zh":"博物館需要問，巡迴大型熱門展覽是否符合成本效益。"},{"en":"Cost-effective means giving good results compared with the money spent.","zh":"cost-effective 指相對於花費而言能帶來良好效果。"},{"en":"Online booking can be cost-effective if it reduces staff workload and printing costs.","zh":"如果網上預約能減少員工工作量和印刷成本，它就符合成本效益。"},{"en":"An overseas exhibition is cost-effective only if income and reputation justify the expense.","zh":"只有當收入和聲譽能合理支持開支時，海外展覽才符合成本效益。"},{"en":"This phrase does not mean cheap; it means worth the cost.","zh":"這個短語不是指便宜，而是指值得成本。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":20},{"front":"contains the following information","meaning":"包含以下資料","examples":[{"en":"Students identify which paragraph contains the following information.","zh":"學生辨認哪一段包含以下資料。"},{"en":"Contains the following information means includes the details listed after the instruction.","zh":"contains the following information 指包括指示後列出的細節。"},{"en":"In a reading test, students must find the paragraph that contains the following information.","zh":"在閱讀測驗中，學生必須找出包含以下資料的段落。"},{"en":"If a paragraph contains the following information, the answer must match that paragraph.","zh":"如果某段包含以下資料，答案就必須對應該段。"},{"en":"This phrase is common in IELTS-style paragraph matching questions.","zh":"這個短語常見於 IELTS 類型的段落配對題。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":20},{"front":"use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"Students may use any letter more than once.","zh":"學生可以重複使用任何字母。"},{"en":"Use any letter more than once means the same answer letter can be chosen again.","zh":"use any letter more than once 指同一答案字母可以再次選用。"},{"en":"In a matching task, students should not avoid repeating a letter if the instructions allow it.","zh":"在配對題中，如果指示允許，學生不應避免重複使用字母。"},{"en":"This instruction matters because one paragraph may contain several pieces of information.","zh":"這個指示很重要，因為一段可能包含多項資料。"},{"en":"The phrase prevents students from assuming each letter can be used only once.","zh":"這個短語防止學生誤以為每個字母只能用一次。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":20},{"front":"a reason for changing","meaning":"改變……的原因","examples":[{"en":"The question asks for a reason for changing exhibition programs.","zh":"題目詢問改變展覽節目安排的原因。"},{"en":"A reason for changing something is the cause or purpose behind making it different.","zh":"a reason for changing something 指令某事改變的原因或目的。"},{"en":"A school may give a reason for changing the timetable, such as reducing student stress.","zh":"學校可能給出改變時間表的原因，例如減少學生壓力。"},{"en":"Museums change programmes when they need to maintain visitor interest.","zh":"當博物館需要維持訪客興趣時，就會改變節目安排。"},{"en":"This phrase asks why a change happens.","zh":"這個短語詢問改變為何發生。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":20},{"front":"exhibition programs","meaning":"展覽節目安排","examples":[{"en":"Museums change their exhibition programs to maintain visitor levels.","zh":"博物館改變展覽節目安排，以維持訪客人數。"},{"en":"Exhibition programs are planned schedules of exhibitions offered by a museum or gallery.","zh":"exhibition programs 指博物館或藝術館提供展覽的計劃時間表。"},{"en":"A gallery may publish its exhibition program for the whole year.","zh":"藝術館可能公布全年展覽節目安排。"},{"en":"Changing exhibition programs can encourage visitors to return.","zh":"改變展覽節目安排可以鼓勵訪客再次到訪。"},{"en":"This phrase refers to the organised plan of exhibitions, not one display only.","zh":"這個短語指有組織的展覽計劃，而不只是一個展示。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":20},{"front":"wait in a queue","meaning":"排隊等候","examples":[{"en":"People may wait in a queue for hours to see an exhibition.","zh":"人們可能排隊等候數小時去看展覽。"},{"en":"To wait in a queue means to stand or stay in line until it is your turn.","zh":"wait in a queue 指排隊等待輪到自己。"},{"en":"Students wait in a queue to buy lunch at the school canteen.","zh":"學生在學校食堂排隊等候買午餐。"},{"en":"Long queues can show popularity but may also make visitors tired.","zh":"長隊可以顯示受歡迎，但也可能令訪客疲倦。"},{"en":"This phrase is common in public services, shops, and events.","zh":"這個短語常見於公共服務、商店和活動。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":21},{"front":"terms used to refer to","meaning":"用來指稱……的詞語","examples":[{"en":"The question asks for terms used to refer to blockbusters.","zh":"題目詢問用來指稱大型熱門展覽的詞語。"},{"en":"Terms used to refer to something are words or phrases people use to name or describe it.","zh":"terms used to refer to something 指人們用來命名或描述某事的詞語或短語。"},{"en":"In science, different terms are used to refer to parts of the body.","zh":"在科學中，不同詞語用來指稱身體部位。"},{"en":"Identifying terms used to refer to an idea helps students understand how writers discuss it.","zh":"辨認用來指稱某概念的詞語，有助學生理解作者如何討論它。"},{"en":"This phrase focuses on vocabulary, not facts alone.","zh":"這個短語著重詞彙，而不只是事實。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":21},{"front":"controversy over","meaning":"關於……的爭議","examples":[{"en":"The passage discusses controversy over the target audience for a blockbuster.","zh":"文章討論關於大型熱門展覽目標觀眾的爭議。"},{"en":"Controversy over something means public disagreement or debate about it.","zh":"controversy over something 指圍繞某事的公眾分歧或辯論。"},{"en":"There may be controversy over whether students should use phones at school.","zh":"關於學生是否應在學校使用手機，可能會有爭議。"},{"en":"Controversy over museum blockbusters often concerns whether they serve education or entertainment.","zh":"關於博物館大型熱門展覽的爭議，常涉及它們服務教育還是娛樂。"},{"en":"This phrase signals that people hold opposing views.","zh":"這個短語表示人們持相反觀點。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":21},{"front":"target audience","meaning":"目標觀眾","examples":[{"en":"Critics debate the target audience for blockbuster exhibitions.","zh":"批評者爭論大型熱門展覽的目標觀眾。"},{"en":"A target audience is the group of people an event, product, or message is designed for.","zh":"target audience 指活動、產品或訊息設計上想接觸的一群人。"},{"en":"A children’s book has children and parents as its target audience.","zh":"兒童書的目標觀眾是兒童和家長。"},{"en":"Museums choose language, design, and activities based on the target audience.","zh":"博物館根據目標觀眾選擇語言、設計和活動。"},{"en":"This phrase helps explain who something is trying to reach.","zh":"這個短語幫助解釋某事物想接觸誰。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":21},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"To complete the summary below means to fill in missing words in the summary under the instruction.","zh":"complete the summary below 指填寫指示下方摘要中的空缺字詞。"},{"en":"Students should read the whole paragraph before completing the summary below.","zh":"學生應先閱讀整段，再完成以下摘要。"},{"en":"Grammar can help students decide which word fits the gap.","zh":"文法可以幫助學生判斷哪個字適合空格。"},{"en":"This phrase is common in reading tests with short-answer gaps.","zh":"這個短語常見於有短答案空格的閱讀測驗。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":21},{"front":"no more than three words","meaning":"不超過三個字","examples":[{"en":"Students should choose no more than three words from the passage.","zh":"學生應從文章中選擇不超過三個字。"},{"en":"No more than three words means one, two, or three words, but not four.","zh":"no more than three words 指一個、兩個或三個字，但不是四個。"},{"en":"If the limit is no more than three words, “the general public” is allowed.","zh":"如果限制是不超過三個字，“the general public” 是可以的。"},{"en":"Students may lose marks if they write more words than the instruction allows.","zh":"如果學生寫多於指示允許的字數，可能會失分。"},{"en":"This phrase is a strict answer-length rule.","zh":"這個短語是嚴格的答案字數規則。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":21},{"front":"treated simply as visitors","meaning":"只被視為訪客","examples":[{"en":"The public are no longer treated simply as visitors.","zh":"公眾不再只被視為訪客。"},{"en":"Treated simply as visitors means regarded only as people who come to look, not as customers or consumers.","zh":"treated simply as visitors 指只被看作前來觀看的人，而不是顧客或消費者。"},{"en":"A library treats people simply as visitors if it only counts how many enter.","zh":"如果圖書館只計算入場人數，它就是把人只視為訪客。"},{"en":"Museums now may treat visitors as customers whose satisfaction and spending matter.","zh":"博物館現在可能把訪客視為顧客，其滿意度和消費都很重要。"},{"en":"This phrase contrasts older public-service thinking with newer market thinking.","zh":"這個短語把較舊的公共服務思維與較新的市場思維作對比。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":21},{"front":"require museums to","meaning":"要求博物館去","examples":[{"en":"New customers require museums to create or hire blockbusters.","zh":"新顧客要求博物館創作或租用大型熱門展覽。"},{"en":"Require museums to do something means make museums need to take that action.","zh":"require museums to do something 指令博物館需要採取某行動。"},{"en":"Higher visitor expectations require museums to improve signs and services.","zh":"更高訪客期望要求博物館改善標示和服務。"},{"en":"Competition may require museums to offer new exhibitions more often.","zh":"競爭可能要求博物館更頻繁地提供新展覽。"},{"en":"This phrase shows pressure placed on museums.","zh":"這個短語顯示施加在博物館上的壓力。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":21},{"front":"make regular changes and innovations","meaning":"作出定期改變和創新","examples":[{"en":"Museums must make regular changes and innovations.","zh":"博物館必須作出定期改變和創新。"},{"en":"To make regular changes and innovations means to update things often and introduce new ideas.","zh":"make regular changes and innovations 指經常更新事物並引入新想法。"},{"en":"A school may make regular changes and innovations to keep lessons useful.","zh":"學校可能作出定期改變和創新，以保持課堂有用。"},{"en":"Museums do this so visitors have reasons to return.","zh":"博物館這樣做，是為了讓訪客有理由再次到訪。"},{"en":"This phrase combines repeated updating with creative improvement.","zh":"這個短語結合了反覆更新和創意改善。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":21},{"front":"business acumen","meaning":"商業觸覺","examples":[{"en":"Directors now need business acumen as well as cultural knowledge.","zh":"總監現在需要商業觸覺，也需要文化知識。"},{"en":"Business acumen is the ability to understand business situations and make smart financial decisions.","zh":"business acumen 指理解商業情況並作出明智財務決策的能力。"},{"en":"A manager shows business acumen by noticing when a product is no longer profitable.","zh":"管理人員注意到某產品不再有利潤時，就顯示商業觸覺。"},{"en":"Museum directors need business acumen to balance budgets, visitors, and cultural goals.","zh":"博物館總監需要商業觸覺，以平衡預算、訪客和文化目標。"},{"en":"This phrase is formal and means strong business judgement.","zh":"這個短語較正式，意思是強大的商業判斷力。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":21},{"front":"important qualities for directors","meaning":"總監的重要素質","examples":[{"en":"Business acumen and public-relations skills are important qualities for directors.","zh":"商業觸覺和公關技巧是總監的重要素質。"},{"en":"Important qualities for directors are abilities or traits needed for leadership roles.","zh":"important qualities for directors 指領導職位所需的能力或特質。"},{"en":"Clear communication is one of the important qualities for directors in schools and companies.","zh":"清楚溝通是學校和公司總監的重要素質之一。"},{"en":"Modern museum directors need qualities that combine culture, business, and public communication.","zh":"現代博物館總監需要結合文化、商業和公共溝通的素質。"},{"en":"This phrase focuses on what makes someone suitable for a senior role.","zh":"這個短語著重甚麼令某人適合高級職位。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":22},{"front":"attract large audiences","meaning":"吸引大量觀眾","examples":[{"en":"Travelling exhibitions can attract large audiences.","zh":"巡迴展覽可以吸引大量觀眾。"},{"en":"To attract large audiences means to bring in many viewers, visitors, or listeners.","zh":"attract large audiences 指吸引大量觀看者、訪客或聽眾。"},{"en":"A free outdoor film night can attract large audiences in summer.","zh":"夏天的免費戶外電影夜可以吸引大量觀眾。"},{"en":"Large audiences can bring income but also require crowd management.","zh":"大量觀眾可以帶來收入，但也需要人流管理。"},{"en":"This phrase is often used for performances, exhibitions, talks, and media.","zh":"這個短語常用於表演、展覽、講座和媒體。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":22},{"front":"contribute to the convergence of","meaning":"促成……的融合","examples":[{"en":"The new museology has contributed to the convergence of museums and tourism.","zh":"新博物館學促成了博物館與旅遊業的融合。"},{"en":"To contribute to the convergence of things means to help separate areas become more connected.","zh":"contribute to the convergence of things 指幫助原本分開的領域變得更有連繫。"},{"en":"Smartphones contributed to the convergence of communication, photography, and entertainment.","zh":"智能手機促成了通訊、攝影和娛樂的融合。"},{"en":"Blockbusters contribute to the convergence of culture and business by attracting paying visitors.","zh":"大型熱門展覽透過吸引付費訪客，促成文化與商業的融合。"},{"en":"This phrase shows one cause of different fields coming together.","zh":"這個短語顯示不同領域走在一起的其中一個原因。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":22},{"front":"pursuit of profit and pleasure","meaning":"追求利潤和娛樂","examples":[{"en":"Museums are increasingly linked to the pursuit of profit and pleasure.","zh":"博物館越來越與追求利潤和娛樂相關。"},{"en":"The pursuit of profit and pleasure means trying to make money and provide enjoyment.","zh":"pursuit of profit and pleasure 指嘗試賺錢並提供娛樂享受。"},{"en":"A theme park clearly operates around the pursuit of profit and pleasure.","zh":"主題公園明顯圍繞追求利潤和娛樂運作。"},{"en":"When museums sell dining events and entertainment packages, they join this pursuit.","zh":"當博物館售賣餐飲活動和娛樂套票時，它們就加入這種追求。"},{"en":"This phrase can sound critical when used about cultural institutions.","zh":"當這個短語用於文化機構時，可能帶有批評意味。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":22},{"front":"lead to debate over","meaning":"引發關於……的爭論","examples":[{"en":"The new museology has led to debate over the role of museums.","zh":"新博物館學引發了關於博物館角色的爭論。"},{"en":"To lead to debate over something means to cause disagreement and discussion about it.","zh":"lead to debate over something 指導致圍繞某事的分歧和討論。"},{"en":"A new exam policy may lead to debate over fairness.","zh":"新考試政策可能引發關於公平的爭論。"},{"en":"Commercial exhibitions lead to debate over whether museums should prioritise profit.","zh":"商業展覽引發關於博物館是否應優先考慮利潤的爭論。"},{"en":"This phrase connects a change with public argument.","zh":"這個短語把變化與公眾爭議連繫起來。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":22},{"front":"be regarded as","meaning":"被視為","examples":[{"en":"Museums may be regarded as tourist attractions.","zh":"博物館可能被視為旅遊景點。"},{"en":"To be regarded as something means to be considered or viewed in that way.","zh":"be regarded as something 指被認為或被看作某種事物。"},{"en":"A quiet student may be regarded as thoughtful if she gives careful answers.","zh":"如果安靜學生給出仔細答案，她可能被視為深思熟慮。"},{"en":"Museums may be regarded as educational spaces, entertainment venues, or tourist attractions.","zh":"博物館可能被視為教育空間、娛樂場地或旅遊景點。"},{"en":"This phrase focuses on how people judge or classify something.","zh":"這個短語著重人們如何判斷或分類某事物。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":22},{"front":"choose two letters","meaning":"選出兩個字母","examples":[{"en":"Students choose two letters from the options.","zh":"學生從選項中選出兩個字母。"},{"en":"Choose two letters means select exactly two answer choices marked by letters.","zh":"choose two letters 指選出正好兩個以字母標示的答案。"},{"en":"In a multiple-answer question, students must choose two letters, not one or three.","zh":"在多答案題中，學生必須選出兩個字母，而不是一個或三個。"},{"en":"Reading the instruction carefully prevents students from giving the wrong number of answers.","zh":"仔細閱讀指示可以防止學生給出錯誤數量的答案。"},{"en":"This phrase is a test instruction about answer format.","zh":"這個短語是關於答案格式的測驗指示。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":22},{"front":"advantages of a blockbuster","meaning":"大型熱門展覽的好處","examples":[{"en":"The question asks about advantages of a blockbuster.","zh":"題目詢問大型熱門展覽的好處。"},{"en":"Advantages of a blockbuster are the good results or benefits it can bring.","zh":"advantages of a blockbuster 指大型熱門展覽可以帶來的好結果或益處。"},{"en":"Advantages of a blockbuster may include more visitors, more income, and a higher public profile.","zh":"大型熱門展覽的好處可能包括更多訪客、更多收入和更高公眾知名度。"},{"en":"These advantages can help museums fund other activities.","zh":"這些好處可以幫助博物館資助其他活動。"},{"en":"This phrase asks students to identify positive effects.","zh":"這個短語要求學生辨認正面效果。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":22},{"front":"provide enough money to","meaning":"提供足夠金錢去","examples":[{"en":"A blockbuster may provide enough money to repair buildings.","zh":"大型熱門展覽可能提供足夠金錢去維修建築物。"},{"en":"To provide enough money to do something means to supply the amount of money needed for that purpose.","zh":"provide enough money to do something 指提供足以完成某目的的金錢。"},{"en":"A fundraiser may provide enough money to buy new library books.","zh":"籌款活動可能提供足夠金錢去購買新圖書館書籍。"},{"en":"If an exhibition sells many tickets, it may provide enough money to support repairs.","zh":"如果展覽售出很多門票，可能提供足夠金錢去支持維修。"},{"en":"This phrase connects income with a specific use.","zh":"這個短語把收入與特定用途連繫起來。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":22},{"front":"maintain and increase visitor numbers","meaning":"維持並增加訪客人數","examples":[{"en":"Blockbusters can help maintain and increase visitor numbers.","zh":"大型熱門展覽可以幫助維持並增加訪客人數。"},{"en":"To maintain and increase visitor numbers means to keep current attendance and bring in more visitors.","zh":"maintain and increase visitor numbers 指保持現有入場人數並吸引更多訪客。"},{"en":"A zoo may use new animal talks to maintain and increase visitor numbers.","zh":"動物園可能利用新的動物講解來維持並增加訪客人數。"},{"en":"Museums need this because fewer visitors can mean less income and public attention.","zh":"博物館需要這樣做，因為訪客減少可能意味收入和公眾關注下降。"},{"en":"This phrase combines protection of current numbers with future growth.","zh":"這個短語結合維持現有人數和未來增長。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":22},{"front":"benefit local businesses","meaning":"令本地商戶受惠","examples":[{"en":"Blockbuster crowds can benefit local businesses.","zh":"大型熱門展覽的人潮可以令本地商戶受惠。"},{"en":"To benefit local businesses means to help nearby shops, restaurants, hotels, or services earn more.","zh":"benefit local businesses 指幫助附近商店、餐廳、酒店或服務賺取更多收入。"},{"en":"A street festival can benefit local businesses by bringing more customers to the area.","zh":"街頭節日可以透過把更多顧客帶到該區，令本地商戶受惠。"},{"en":"Museum visitors may eat nearby, buy souvenirs, and use local transport.","zh":"博物館訪客可能在附近用餐、購買紀念品和使用本地交通。"},{"en":"This phrase shows economic effects beyond the museum itself.","zh":"這個短語顯示博物館本身以外的經濟效果。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":23},{"front":"disadvantages of a blockbuster","meaning":"大型熱門展覽的壞處","examples":[{"en":"The question asks about disadvantages of a blockbuster.","zh":"題目詢問大型熱門展覽的壞處。"},{"en":"Disadvantages of a blockbuster are the problems or negative results it may create.","zh":"disadvantages of a blockbuster 指大型熱門展覽可能造成的問題或負面結果。"},{"en":"Disadvantages of a blockbuster may include high costs, tired staff, and pressure on regular exhibitions.","zh":"大型熱門展覽的壞處可能包括高成本、員工疲倦和常規展覽受壓。"},{"en":"A popular event can still have disadvantages if it damages long-term work.","zh":"受歡迎活動如果損害長期工作，仍可能有壞處。"},{"en":"This phrase asks students to identify negative effects.","zh":"這個短語要求學生辨認負面效果。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":23},{"front":"be left unsure","meaning":"變得不確定","examples":[{"en":"Visitors may be left unsure which exhibition to choose.","zh":"訪客可能變得不確定該選擇哪個展覽。"},{"en":"To be left unsure means to remain uncertain after seeing the options or information.","zh":"be left unsure 指看過選項或資料後仍然不確定。"},{"en":"A customer may be left unsure if two phone plans look almost the same.","zh":"如果兩個電話計劃看起來幾乎一樣，顧客可能變得不確定。"},{"en":"Too many blockbuster choices can leave visitors unsure where to spend their money.","zh":"太多大型熱門展覽選擇可能令訪客不確定該把錢花在哪裡。"},{"en":"This phrase describes confusion after comparison.","zh":"這個短語描述比較後的困惑。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":23},{"front":"additional workload","meaning":"額外工作量","examples":[{"en":"Workers may become tired because of the additional workload.","zh":"工人可能因額外工作量而變得疲倦。"},{"en":"Additional workload means extra work added to someone’s normal duties.","zh":"additional workload 指加在某人正常職責以外的額外工作。"},{"en":"Teachers face additional workload during exam marking season.","zh":"老師在改卷季節會面對額外工作量。"},{"en":"Museum staff may face additional workload when visitor numbers suddenly rise.","zh":"當訪客人數突然上升，博物館員工可能面對額外工作量。"},{"en":"This phrase often explains stress, tiredness, or reduced performance.","zh":"這個短語常用來解釋壓力、疲倦或表現下降。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":23},{"front":"more entertaining than cultural","meaning":"娛樂性多於文化性","examples":[{"en":"Museums may become more entertaining than cultural.","zh":"博物館可能變得娛樂性多於文化性。"},{"en":"More entertaining than cultural means focused more on fun than on serious cultural value.","zh":"more entertaining than cultural 指更著重娛樂，而不是嚴肅文化價值。"},{"en":"A history show may become more entertaining than cultural if it ignores facts for drama.","zh":"如果歷史節目為了戲劇效果而忽略事實，就可能娛樂性多於文化性。"},{"en":"Museums risk this problem when they choose attractions only because they sell tickets.","zh":"當博物館只因門票好賣而選擇吸引項目，就有這種風險。"},{"en":"This phrase contrasts amusement with cultural meaning.","zh":"這個短語把娛樂和文化意義作對比。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":23},{"front":"huge amounts of capital","meaning":"巨額資本","examples":[{"en":"Blockbusters may require huge amounts of capital.","zh":"大型熱門展覽可能需要巨額資本。"},{"en":"Huge amounts of capital means very large sums of money used for investment or major spending.","zh":"huge amounts of capital 指用於投資或大型開支的非常大筆金錢。"},{"en":"Building a hospital requires huge amounts of capital.","zh":"建造醫院需要巨額資本。"},{"en":"Blockbusters require capital for transport, insurance, security, display systems, and promotion.","zh":"大型熱門展覽需要資本支付運輸、保險、保安、展示系統和宣傳。"},{"en":"This phrase emphasises the large financial commitment needed.","zh":"這個短語強調所需的巨大財務投入。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":23},{"front":"invest in specialists","meaning":"投資於專家","examples":[{"en":"The option refers to investing in specialists.","zh":"這個選項指投資於專家。"},{"en":"To invest in specialists means to spend money on people with expert skills or knowledge.","zh":"invest in specialists 指花錢聘用或培養具有專門技能或知識的人。"},{"en":"A hospital may invest in specialists to improve treatment for rare diseases.","zh":"醫院可能投資於專家，以改善罕見病治療。"},{"en":"Museums invest in specialists when they hire conservators, educators, or exhibition designers.","zh":"博物館聘請修復師、教育人員或展覽設計師時，就是投資於專家。"},{"en":"This phrase shows spending money to gain expert ability.","zh":"這個短語顯示花錢以取得專家能力。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":23},{"front":"be exposed to the vagaries","meaning":"面對……的變幻莫測","examples":[{"en":"Staff are exposed to the vagaries of the marketplace.","zh":"職員面對市場的變幻莫測。"},{"en":"To be exposed to the vagaries means to face unpredictable changes or uncertain conditions.","zh":"be exposed to the vagaries 指面對難以預測的變化或不確定情況。"},{"en":"Farmers are exposed to the vagaries of weather because rain and heat can change quickly.","zh":"農民面對天氣的變幻莫測，因為雨量和熱度可以迅速改變。"},{"en":"Museum staff are exposed to market vagaries when visitor demand rises and falls suddenly.","zh":"當訪客需求突然上升和下降時，博物館職員就面對市場的變幻莫測。"},{"en":"This phrase shows that people must deal with forces they cannot fully control.","zh":"這個短語顯示人們必須應付不能完全控制的力量。"}],"source":"133 - Museum Blockbuster.pdf","sourcePage":23}],"ielts/reading/passage-2/Practice 134":[{"front":"TV addiction","meaning":"電視成癮","examples":[{"en":"The passage discusses whether heavy television watching can be described as TV addiction.","zh":"文章討論重度看電視是否可以被描述為電視成癮。"},{"en":"TV addiction means being unable to control television watching even when it causes problems.","zh":"電視成癮指即使看電視造成問題，仍無法控制觀看行為。"},{"en":"A student may show TV addiction if he watches shows all night and misses schoolwork.","zh":"如果學生整晚看節目而不做功課，他可能表現出電視成癮。"},{"en":"TV addiction can reduce sleep, exercise, family time, and concentration.","zh":"電視成癮可以減少睡眠、運動、家庭時間和專注力。"},{"en":"The phrase is usually used when watching feels hard to stop, not when someone simply enjoys TV.","zh":"這個短語通常用於觀看行為難以停止，而不是單純喜歡電視。"}],"source":"134 - TV Addiction.pdf","sourcePage":1},{"front":"excessive cravings","meaning":"過度渴求","examples":[{"en":"Excessive cravings do not necessarily involve physical substances.","zh":"過度渴求不一定涉及實體物質。"},{"en":"Excessive cravings are very strong desires that feel difficult to control.","zh":"excessive cravings 指非常強烈、令人難以控制的慾望。"},{"en":"A person may have excessive cravings for online games, sweets, or social media.","zh":"一個人可能對網上遊戲、甜食或社交媒體有過度渴求。"},{"en":"Excessive cravings can lead people to ignore work, study, sleep, or health.","zh":"過度渴求可以令人忽視工作、學習、睡眠或健康。"},{"en":"The phrase suggests desire has become too powerful, not merely ordinary liking.","zh":"這個短語暗示慾望變得過強，而不只是普通喜歡。"}],"source":"134 - TV Addiction.pdf","sourcePage":1},{"front":"do not necessarily involve","meaning":"不一定涉及……","examples":[{"en":"Addiction does not necessarily involve physical substances.","zh":"成癮不一定涉及實體物質。"},{"en":"Do not necessarily involve means something is not always part of the situation.","zh":"do not necessarily involve 指某事不一定總是包含在情況之中。"},{"en":"Good learning does not necessarily involve expensive courses.","zh":"良好學習不一定涉及昂貴課程。"},{"en":"A serious problem does not necessarily involve loud arguments; silence can also show trouble.","zh":"嚴重問題不一定涉及大聲爭吵；沉默也可以顯示麻煩。"},{"en":"The phrase helps avoid an overgeneralisation.","zh":"這個短語有助避免過度概括。"}],"source":"134 - TV Addiction.pdf","sourcePage":1},{"front":"physical substances","meaning":"實體物質","examples":[{"en":"Some compulsive behaviours do not involve physical substances.","zh":"一些強迫性行為不涉及實體物質。"},{"en":"Physical substances are material things such as alcohol, drugs, nicotine, or chemicals.","zh":"physical substances 指酒精、藥物、尼古丁或化學品等物質。"},{"en":"A medical test may measure physical substances in blood or urine.","zh":"醫學檢查可能量度血液或尿液中的實體物質。"},{"en":"Some addictions involve physical substances, while others involve behaviours like gambling.","zh":"有些成癮涉及實體物質，另一些則涉及賭博等行為。"},{"en":"The phrase contrasts concrete materials with habits, actions, or mental desires.","zh":"這個短語把具體物質與習慣、行為或心理慾望作對比。"}],"source":"134 - TV Addiction.pdf","sourcePage":1},{"front":"become compulsive","meaning":"變得強迫性；令人難以自控","examples":[{"en":"Gambling can become compulsive.","zh":"賭博可以變得強迫性。"},{"en":"If a behaviour becomes compulsive, a person feels driven to repeat it and finds it hard to stop.","zh":"如果一種行為 becomes compulsive，意思是人感到被迫重複它，而且難以停止。"},{"en":"Checking messages can become compulsive if someone opens the phone every few minutes.","zh":"如果有人每隔幾分鐘就打開手機，查看訊息可以變得強迫性。"},{"en":"Compulsive behaviour can harm daily life because choice becomes weaker than habit.","zh":"強迫性行為可以損害日常生活，因為選擇變得弱於習慣。"},{"en":"The phrase describes loss of control, not simply doing something often.","zh":"這個短語描述失去控制，而不是單純經常做某事。"}],"source":"134 - TV Addiction.pdf","sourcePage":1},{"front":"become obsessive","meaning":"變得沉迷；變得強迫性","examples":[{"en":"Some activities can become obsessive.","zh":"有些活動可以變得沉迷。"},{"en":"If an activity becomes obsessive, a person thinks about it too much and struggles to stop.","zh":"如果一項活動 becomes obsessive，意思是人過度想着它，並難以停止。"},{"en":"A student’s worry about marks can become obsessive if it controls every evening.","zh":"如果學生對分數的擔憂控制每個晚上，這種擔憂可以變得沉迷。"},{"en":"Obsessive interest can crowd out rest, relationships, and other responsibilities.","zh":"沉迷式興趣可以擠走休息、人際關係和其他責任。"},{"en":"The phrase is stronger than being interested; it suggests unhealthy mental fixation.","zh":"這個短語比感興趣更強，暗示不健康的心理執着。"}],"source":"134 - TV Addiction.pdf","sourcePage":1},{"front":"stand out for","meaning":"因……而突出","examples":[{"en":"Television stands out for its prominence and ubiquity.","zh":"電視因其顯著性和普遍性而突出。"},{"en":"To stand out for something means to be especially noticeable because of that quality.","zh":"stand out for something 指因某種特質而特別顯眼。"},{"en":"A restaurant may stand out for its friendly service and clean kitchen.","zh":"一間餐廳可能因友善服務和乾淨廚房而突出。"},{"en":"A student can stand out for careful grammar even if the essay topic is simple.","zh":"即使作文題目簡單，學生也可以因文法仔細而突出。"},{"en":"The phrase explains the reason someone or something is remarkable.","zh":"這個短語解釋某人或某物值得注意的原因。"}],"source":"134 - TV Addiction.pdf","sourcePage":1},{"front":"prominence and ubiquity","meaning":"顯著性和普遍性","examples":[{"en":"Television stands out for its prominence and ubiquity.","zh":"電視因其顯著性和普遍性而突出。"},{"en":"Prominence and ubiquity mean something is both highly noticeable and found almost everywhere.","zh":"prominence and ubiquity 指某物既非常顯眼，又幾乎到處可見。"},{"en":"Smartphones have prominence and ubiquity because people see and use them daily.","zh":"智能手機具有顯著性和普遍性，因為人們每天看見並使用它們。"},{"en":"When a service has prominence and ubiquity, it can strongly shape public habits.","zh":"當一項服務具有顯著性和普遍性，它可以強烈塑造公眾習慣。"},{"en":"The phrase is formal and describes visibility plus widespread presence.","zh":"這個短語較正式，描述可見度加上廣泛存在。"}],"source":"134 - TV Addiction.pdf","sourcePage":1},{"front":"the world’s most popular pastime","meaning":"世界上最受歡迎的消遣","examples":[{"en":"Television is described as the world’s most popular pastime.","zh":"電視被描述為世界上最受歡迎的消遣。"},{"en":"The world’s most popular pastime means the leisure activity enjoyed by the largest number of people globally.","zh":"the world’s most popular pastime 指全球最多人喜歡的閒暇活動。"},{"en":"Watching short videos may become a popular pastime when people use phones during breaks.","zh":"當人們在休息時間使用手機，觀看短片可能成為受歡迎的消遣。"},{"en":"If an activity becomes the world’s most popular pastime, it can influence culture and daily schedules.","zh":"如果一項活動成為世界上最受歡迎的消遣，它可以影響文化和日常時間安排。"},{"en":"The phrase describes free-time activity, not paid work.","zh":"這個短語描述閒暇活動，而不是有薪工作。"}],"source":"134 - TV Addiction.pdf","sourcePage":1},{"front":"admit to having","meaning":"承認有……","examples":[{"en":"Most people admit to having a love-hate relationship with television.","zh":"大多數人承認自己與電視有又愛又恨的關係。"},{"en":"To admit to having something means to accept or confess that it is true for oneself.","zh":"admit to having something 指承認自己確實有某種情況。"},{"en":"A student may admit to having poor study habits before asking for help.","zh":"學生可能先承認自己有不良學習習慣，然後尋求幫助。"},{"en":"People often admit to having doubts only after they feel safe to speak honestly.","zh":"人們通常在感到安全可以坦白說話後，才承認自己有疑慮。"},{"en":"The phrase suggests honesty about something slightly embarrassing or uncomfortable.","zh":"這個短語暗示誠實承認有點尷尬或不舒服的事情。"}],"source":"134 - TV Addiction.pdf","sourcePage":1},{"front":"a love-hate relationship with","meaning":"對……又愛又恨的關係","examples":[{"en":"Many people have a love-hate relationship with television.","zh":"許多人與電視有又愛又恨的關係。"},{"en":"A love-hate relationship with something means liking it and feeling frustrated by it at the same time.","zh":"a love-hate relationship with something 指同時喜歡某物又對它感到煩惱。"},{"en":"Many students have a love-hate relationship with exams because exams motivate them but also cause stress.","zh":"許多學生對考試又愛又恨，因為考試推動他們，但也造成壓力。"},{"en":"A love-hate relationship can develop when something gives pleasure but also creates problems.","zh":"當某事帶來樂趣但也造成問題，就可能形成又愛又恨的關係。"},{"en":"The phrase describes mixed feelings, not simple love or dislike.","zh":"這個短語描述矛盾感受，而不是單純喜歡或不喜歡。"}],"source":"134 - TV Addiction.pdf","sourcePage":1},{"front":"the boob tube","meaning":"電視機；電視這個「傻瓜箱」","examples":[{"en":"Some people complain about the boob tube but still watch it for hours.","zh":"有些人抱怨電視這個「傻瓜箱」，但仍看上數小時。"},{"en":"The boob tube is an informal and slightly critical nickname for television.","zh":"the boob tube 是對電視的非正式、帶輕微批評的稱呼。"},{"en":"A parent may call the TV the boob tube when children sit silently in front of it all afternoon.","zh":"當孩子整個下午靜靜坐在電視前，父母可能稱電視為「傻瓜箱」。"},{"en":"Calling television the boob tube suggests it may make viewers passive or foolish.","zh":"把電視稱為 boob tube 暗示它可能令人被動或變笨。"},{"en":"The phrase is casual, so it is not suitable for formal academic writing.","zh":"這個短語較口語，不適合正式學術寫作。"}],"source":"134 - TV Addiction.pdf","sourcePage":2},{"front":"couch potatoes","meaning":"長時間坐着看電視的人","examples":[{"en":"People complain about couch potatoes but may become inactive viewers themselves.","zh":"人們抱怨長時間坐着看電視的人，但自己也可能變成不活躍的觀眾。"},{"en":"Couch potatoes are people who spend a lot of time sitting and watching television.","zh":"couch potatoes 指花很多時間坐着看電視的人。"},{"en":"A person may become a couch potato during holidays if he never leaves the sofa.","zh":"如果一個人在假期從不離開梳化，他可能變成 couch potato。"},{"en":"Being a couch potato can reduce exercise and make daily life less active.","zh":"長時間坐着看電視可以減少運動，令日常生活較不活躍。"},{"en":"The phrase is humorous but can sound critical.","zh":"這個短語帶幽默感，但也可能有批評意味。"}],"source":"134 - TV Addiction.pdf","sourcePage":2},{"front":"settle into","meaning":"舒舒服服地坐進","examples":[{"en":"Viewers settle into their sofas and grab the remote control.","zh":"觀眾舒舒服服地坐進梳化，拿起遙控器。"},{"en":"To settle into a seat means to sit down comfortably and prepare to stay for a while.","zh":"settle into a seat 指舒適地坐下，準備停留一段時間。"},{"en":"After dinner, a family may settle into the living room to watch a film.","zh":"晚飯後，一家人可能舒舒服服地坐進客廳看電影。"},{"en":"When people settle into a routine, it becomes easier to repeat the same habit daily.","zh":"當人們安定於某種日常習慣，便更容易每天重複同樣行為。"},{"en":"The phrase suggests comfort, stillness, and the start of a relaxed activity.","zh":"這個短語暗示舒適、靜止和放鬆活動的開始。"}],"source":"134 - TV Addiction.pdf","sourcePage":2},{"front":"grab the remote control","meaning":"拿起遙控器","examples":[{"en":"People often grab the remote control when they start watching TV.","zh":"人們開始看電視時常會拿起遙控器。"},{"en":"To grab the remote control means to quickly take the device used to change TV channels or settings.","zh":"grab the remote control 指快速拿起用來轉台或調校電視的裝置。"},{"en":"A child may grab the remote control to choose cartoons before anyone else can choose.","zh":"孩子可能搶先拿起遙控器選卡通片。"},{"en":"Grabbing the remote control can start a small family argument about what to watch.","zh":"拿起遙控器可能引發家人關於看甚麼的小爭執。"},{"en":"The phrase suggests a quick, familiar action before watching television.","zh":"這個短語暗示看電視前快速而熟悉的動作。"}],"source":"134 - TV Addiction.pdf","sourcePage":2},{"front":"commonly fret about","meaning":"經常為……擔心","examples":[{"en":"Parents commonly fret about their children’s viewing.","zh":"父母經常為孩子觀看電視的情況擔心。"},{"en":"To commonly fret about something means to often worry about it.","zh":"commonly fret about something 指經常為某事憂慮。"},{"en":"Parents commonly fret about exam results, screen time, and sleep schedules.","zh":"父母經常為考試成績、螢幕時間和睡眠時間表擔心。"},{"en":"People fret about an issue when they feel it may cause harm but cannot fully control it.","zh":"當人們覺得某事可能造成傷害但又不能完全控制，就會為它擔心。"},{"en":"The phrase suggests repeated nervous concern, not calm planning.","zh":"這個短語暗示反覆的緊張憂慮，而不是冷靜計劃。"}],"source":"134 - TV Addiction.pdf","sourcePage":2},{"front":"children’s viewing","meaning":"兒童觀看電視的情況","examples":[{"en":"Parents often worry about their children’s viewing.","zh":"父母常擔心兒童觀看電視的情況。"},{"en":"Children’s viewing means what children watch on television or screens, and how much they watch.","zh":"children’s viewing 指兒童觀看電視或螢幕內容，以及觀看時間。"},{"en":"A parent may limit children’s viewing before bedtime so they can sleep better.","zh":"父母可能限制孩子睡前觀看電視，好讓他們睡得更好。"},{"en":"Too much children’s viewing can reduce reading, outdoor play, and conversation.","zh":"過多兒童觀看電視可以減少閱讀、戶外遊戲和交談。"},{"en":"The phrase is usually used when adults discuss screen habits and content.","zh":"這個短語通常用於成年人討論螢幕習慣和內容時。"}],"source":"134 - TV Addiction.pdf","sourcePage":2},{"front":"study TV for a living","meaning":"以研究電視為職業","examples":[{"en":"Some researchers study TV for a living.","zh":"有些研究人員以研究電視為職業。"},{"en":"To study TV for a living means to earn one’s income by researching television.","zh":"study TV for a living 指靠研究電視賺取收入。"},{"en":"A media professor may study TV for a living by analysing programmes and audiences.","zh":"媒體教授可能透過分析節目和觀眾，以研究電視為職業。"},{"en":"People who study TV for a living may still find it hard to stop watching it.","zh":"以研究電視為職業的人，仍可能發現自己難以停止觀看電視。"},{"en":"The phrase means television research is someone’s job, not just a hobby.","zh":"這個短語表示電視研究是某人的工作，而不只是興趣。"}],"source":"134 - TV Addiction.pdf","sourcePage":2},{"front":"marvel at","meaning":"對……感到驚訝","examples":[{"en":"Researchers marvel at the medium’s hold on them personally.","zh":"研究人員對這種媒介對他們個人的吸引力感到驚訝。"},{"en":"To marvel at something means to feel surprised, impressed, or amazed by it.","zh":"marvel at something 指對某事感到驚奇、佩服或驚訝。"},{"en":"Visitors may marvel at a museum display that shows ancient tools in detail.","zh":"訪客可能對展示古代工具細節的博物館展品感到驚嘆。"},{"en":"People marvel at television’s power when they cannot ignore it during conversation.","zh":"當人們在交談中仍無法忽視電視，他們會對電視的力量感到驚訝。"},{"en":"The phrase suggests strong wonder, not just ordinary noticing.","zh":"這個短語暗示強烈驚奇，而不只是普通注意到。"}],"source":"134 - TV Addiction.pdf","sourcePage":2},{"front":"the medium’s hold on","meaning":"媒介對……的吸引力","examples":[{"en":"Even researchers feel the medium’s hold on them.","zh":"甚至研究人員也感受到這種媒介對他們的吸引力。"},{"en":"The medium’s hold on someone means the power a form of communication has to keep their attention.","zh":"the medium’s hold on someone 指某種傳播媒介留住人注意力的力量。"},{"en":"Social media’s hold on teenagers can make them check their phones during meals.","zh":"社交媒體對青少年的吸引力可以令他們吃飯時查看手機。"},{"en":"Television’s hold on viewers grows stronger when movement and sound keep pulling their eyes back.","zh":"當動作和聲音不斷把視線拉回來，電視對觀眾的吸引力會更強。"},{"en":"The phrase describes attraction that feels difficult to resist.","zh":"這個短語描述令人難以抗拒的吸引力。"}],"source":"134 - TV Addiction.pdf","sourcePage":2},{"front":"embarrassing moments","meaning":"尷尬時刻","examples":[{"en":"Percy Tannenbaum describes embarrassing moments caused by television.","zh":"Percy Tannenbaum 描述由電視造成的尷尬時刻。"},{"en":"Embarrassing moments are situations that make someone feel awkward, ashamed, or socially uncomfortable.","zh":"embarrassing moments 指令人感到尷尬、羞愧或社交上不自在的情況。"},{"en":"Looking at your phone while someone is speaking can create embarrassing moments.","zh":"當別人在說話時看手機，可以造成尷尬時刻。"},{"en":"Embarrassing moments may happen when a person cannot hide a bad habit.","zh":"當一個人無法掩飾壞習慣時，尷尬時刻可能出現。"},{"en":"The phrase describes small social discomfort, not necessarily serious harm.","zh":"這個短語描述小型社交不適，而不一定是嚴重傷害。"}],"source":"134 - TV Addiction.pdf","sourcePage":2},{"front":"countless occasions","meaning":"無數次","examples":[{"en":"There have been countless occasions when he could not ignore the TV.","zh":"有無數次他無法忽視電視。"},{"en":"Countless occasions means very many times, too many to count easily.","zh":"countless occasions 指非常多次，多到難以輕易計算。"},{"en":"A teacher may have helped students on countless occasions after class.","zh":"老師可能在課後無數次幫助學生。"},{"en":"If a problem happens on countless occasions, it is a pattern rather than an accident.","zh":"如果問題無數次發生，它就是一種模式，而不是意外。"},{"en":"The phrase emphasises frequency and repetition.","zh":"這個短語強調頻率和重複。"}],"source":"134 - TV Addiction.pdf","sourcePage":2},{"front":"be engaged in conversation","meaning":"正在交談","examples":[{"en":"He was engaged in conversation while a TV set was on.","zh":"電視開着時，他正在交談。"},{"en":"To be engaged in conversation means to be actively talking with someone.","zh":"be engaged in conversation 指正在積極與人談話。"},{"en":"Friends may be engaged in conversation over dinner and forget to check their phones.","zh":"朋友可能在晚餐時正在交談，忘記查看手機。"},{"en":"If someone keeps looking away while engaged in conversation, the other person may feel ignored.","zh":"如果某人正在交談時不停望向別處，對方可能覺得被忽視。"},{"en":"The phrase suggests active social interaction, not silent listening only.","zh":"這個短語暗示主動社交互動，而不只是沉默聆聽。"}],"source":"134 - TV Addiction.pdf","sourcePage":3},{"front":"cannot for the life of me","meaning":"怎樣也不能；無論如何也不能","examples":[{"en":"He cannot for the life of him stop glancing at the screen.","zh":"他無論如何也不能停止瞥向螢幕。"},{"en":"Cannot for the life of me means I really cannot do something, even though I try.","zh":"cannot for the life of me 指即使嘗試，也真的無法做到某事。"},{"en":"I cannot for the life of me remember where I put my keys.","zh":"我怎樣也記不起把鑰匙放在哪裡。"},{"en":"A student may say he cannot for the life of him understand a grammar rule after many attempts.","zh":"學生可能說自己嘗試很多次後，無論如何也不能理解某條文法規則。"},{"en":"The phrase is informal and adds strong frustration.","zh":"這個短語較口語，帶有強烈挫敗感。"}],"source":"134 - TV Addiction.pdf","sourcePage":3},{"front":"periodically glance over to","meaning":"不時瞥向……","examples":[{"en":"He periodically glanced over to the screen.","zh":"他不時瞥向螢幕。"},{"en":"To periodically glance over to something means to look at it briefly from time to time.","zh":"periodically glance over to something 指不時短暫看向某物。"},{"en":"A driver may periodically glance over to the mirror to check traffic behind.","zh":"司機可能不時瞥向倒後鏡，查看後方交通。"},{"en":"If a student periodically glances over to the clock, he may be worried about time.","zh":"如果學生不時瞥向時鐘，他可能擔心時間。"},{"en":"The phrase describes repeated quick looks, not continuous staring.","zh":"這個短語描述重複的快速一瞥，而不是持續盯着。"}],"source":"134 - TV Addiction.pdf","sourcePage":3},{"front":"reasonably interesting","meaning":"頗有趣的","examples":[{"en":"This happens even during reasonably interesting conversations.","zh":"即使在頗有趣的對話中，這也會發生。"},{"en":"Reasonably interesting means fairly interesting, though not extremely exciting.","zh":"reasonably interesting 指相當有趣，但不是極度刺激。"},{"en":"A reasonably interesting lesson can still lose students if phones keep distracting them.","zh":"一堂頗有趣的課，如果手機不斷令人分心，仍可能失去學生注意力。"},{"en":"If someone ignores a reasonably interesting conversation, the distraction must be strong.","zh":"如果某人忽視一段頗有趣的對話，干擾物一定很強。"},{"en":"The phrase shows moderate interest, not boredom.","zh":"這個短語表示中等程度的興趣，而不是沉悶。"}],"source":"134 - TV Addiction.pdf","sourcePage":3},{"front":"just as well","meaning":"也同樣如此","examples":[{"en":"He looks at the screen during interesting conversations just as well.","zh":"他在有趣對話中也同樣會看螢幕。"},{"en":"Just as well can mean equally or in the same way in a comparison.","zh":"just as well 在比較中可以指同樣地或以相同方式。"},{"en":"A child may ignore homework during cartoons, and during advertisements just as well.","zh":"孩子可能在卡通片期間忽視功課，在廣告期間也同樣如此。"},{"en":"If a habit appears in pleasant situations just as well as boring ones, it may be hard to control.","zh":"如果某習慣在愉快和沉悶情況中都同樣出現，它可能難以控制。"},{"en":"The phrase shows that the same result happens in another situation too.","zh":"這個短語表示同一結果在另一情況中也發生。"}],"source":"134 - TV Addiction.pdf","sourcePage":3},{"front":"the effects of television","meaning":"電視的影響","examples":[{"en":"Scientists have studied the effects of television for decades.","zh":"科學家數十年來一直研究電視的影響。"},{"en":"The effects of television are the ways television changes viewers’ behaviour, feelings, learning, or habits.","zh":"effects of television 指電視改變觀眾行為、感受、學習或習慣的方式。"},{"en":"Teachers may discuss the effects of television on children’s attention and language.","zh":"老師可能討論電視對兒童注意力和語言的影響。"},{"en":"The effects of television can be positive or negative depending on content and viewing habits.","zh":"電視的影響可以是正面或負面，視乎內容和觀看習慣。"},{"en":"The phrase focuses on consequences, not the device itself.","zh":"這個短語重點是後果，而不是電視機本身。"}],"source":"134 - TV Addiction.pdf","sourcePage":3},{"front":"for decades","meaning":"數十年來","examples":[{"en":"Researchers have studied television for decades.","zh":"研究人員數十年來一直研究電視。"},{"en":"For decades means for many periods of ten years.","zh":"for decades 指持續很多個十年。"},{"en":"Doctors have warned about smoking for decades.","zh":"醫生數十年來一直警告吸煙的危害。"},{"en":"If a problem continues for decades, quick solutions may not be enough.","zh":"如果問題持續數十年，快速解決方案可能不足夠。"},{"en":"The phrase shows a long period of repeated concern or activity.","zh":"這個短語表示長期重複的關注或活動。"}],"source":"134 - TV Addiction.pdf","sourcePage":3},{"front":"generally focusing on","meaning":"一般集中於……","examples":[{"en":"Studies have generally focused on television violence.","zh":"研究一般集中於電視暴力。"},{"en":"Generally focusing on something means usually giving most attention to that topic.","zh":"generally focusing on something 指通常把大部分注意力放在某主題上。"},{"en":"School meetings generally focus on grades, behaviour, and student safety.","zh":"學校會議一般集中於成績、行為和學生安全。"},{"en":"If research generally focuses on one issue, other important questions may be missed.","zh":"如果研究一般集中於一個議題，其他重要問題可能被忽略。"},{"en":"The phrase shows the common direction of attention, not every single case.","zh":"這個短語顯示常見關注方向，而不是每一個個案。"}],"source":"134 - TV Addiction.pdf","sourcePage":3},{"front":"correlate with","meaning":"與……相關","examples":[{"en":"Researchers ask whether watching violence correlates with violent behaviour.","zh":"研究人員問觀看暴力是否與暴力行為相關。"},{"en":"To correlate with something means to have a statistical relationship with it.","zh":"correlate with something 指與某事有統計關係。"},{"en":"Sleep time may correlate with school performance if students who sleep more score better.","zh":"如果睡眠較多的學生分數較高，睡眠時間可能與學業表現相關。"},{"en":"Correlation can suggest a link, but it does not always prove direct cause.","zh":"相關性可以暗示關連，但不一定證明直接原因。"},{"en":"The phrase is common when comparing research data.","zh":"這個短語常用於比較研究數據。"}],"source":"134 - TV Addiction.pdf","sourcePage":3},{"front":"in real life","meaning":"在現實生活中","examples":[{"en":"Some studies examine whether TV violence affects behaviour in real life.","zh":"一些研究檢視電視暴力是否影響現實生活中的行為。"},{"en":"In real life means in actual daily situations, not only in stories, tests, or imagination.","zh":"in real life 指在真實日常情況中，而不只是故事、測驗或想像中。"},{"en":"A phrase learned in class is useful only if students can use it in real life.","zh":"課堂學到的短語，只有學生能在現實生活中使用才有用。"},{"en":"Behaviour in real life may differ from what people say in surveys.","zh":"現實生活中的行為可能與人們在問卷中所說不同。"},{"en":"The phrase contrasts actual experience with artificial or fictional settings.","zh":"這個短語把真實經驗與人為或虛構環境作對比。"}],"source":"134 - TV Addiction.pdf","sourcePage":3},{"front":"less attention has been paid to","meaning":"較少關注……","examples":[{"en":"Less attention has been paid to the basic allure of television.","zh":"人們較少關注電視的基本吸引力。"},{"en":"Less attention has been paid to something means people have studied or noticed it less.","zh":"less attention has been paid to something 指人們較少研究或注意某事。"},{"en":"In schools, less attention has been paid to sleep than to exam results.","zh":"在學校，人們較少關注睡眠，而較多關注考試成績。"},{"en":"When less attention is paid to early warning signs, problems may grow unnoticed.","zh":"當早期警號受到較少關注，問題可能在未被察覺下惡化。"},{"en":"The phrase points out an overlooked area.","zh":"這個短語指出被忽略的範疇。"}],"source":"134 - TV Addiction.pdf","sourcePage":3},{"front":"the basic allure of","meaning":"……的基本吸引力","examples":[{"en":"Researchers have paid less attention to the basic allure of the small screen.","zh":"研究人員較少關注小螢幕的基本吸引力。"},{"en":"The basic allure of something is its simple but powerful attraction.","zh":"basic allure of something 指某事物簡單但強大的吸引力。"},{"en":"The basic allure of online shopping is that people can buy things without leaving home.","zh":"網上購物的基本吸引力是人們不用出門也能買東西。"},{"en":"Television’s basic allure may come from movement, sound, and constant change.","zh":"電視的基本吸引力可能來自動作、聲音和不斷變化。"},{"en":"The phrase asks why something attracts people before judging its content.","zh":"這個短語先探問某物為何吸引人，而不是評判其內容。"}],"source":"134 - TV Addiction.pdf","sourcePage":4},{"front":"the small screen","meaning":"電視螢幕；小螢幕","examples":[{"en":"The small screen has a powerful attraction.","zh":"小螢幕有強大的吸引力。"},{"en":"The small screen means television, especially as a medium rather than a cinema screen.","zh":"the small screen 指電視，尤其作為媒介而不是電影銀幕。"},{"en":"Many actors move from the cinema to the small screen when they join TV dramas.","zh":"許多演員加入電視劇時，會從電影轉到小螢幕。"},{"en":"The small screen can shape daily habits because it sits inside the home.","zh":"小螢幕可以塑造日常習慣，因為它位於家中。"},{"en":"The phrase contrasts television with the big screen of cinema.","zh":"這個短語把電視與電影的大銀幕作對比。"}],"source":"134 - TV Addiction.pdf","sourcePage":4},{"front":"the medium as opposed to the message","meaning":"媒介本身，而不是內容","examples":[{"en":"The passage focuses on the medium as opposed to the message.","zh":"文章集中於媒介本身，而不是內容。"},{"en":"The medium as opposed to the message means the form of communication rather than its content.","zh":"the medium as opposed to the message 指傳播形式，而不是其內容。"},{"en":"A teacher may study phone use as a medium, as opposed to the messages students send.","zh":"老師可能研究手機作為媒介，而不是學生傳送的訊息。"},{"en":"Television’s movement and sound may matter as much as, or more than, the programmes themselves.","zh":"電視的動作和聲音可能與節目本身一樣重要，甚至更重要。"},{"en":"The phrase clearly contrasts how information is delivered with what it says.","zh":"這個短語清楚對比資訊如何傳送與資訊說了甚麼。"}],"source":"134 - TV Addiction.pdf","sourcePage":4},{"front":"imprecise","meaning":"不精確的","examples":[{"en":"The term TV addiction is imprecise.","zh":"「電視成癮」這個術語是不精確的。"},{"en":"Imprecise means not exact, clear, or carefully defined.","zh":"imprecise 指不準確、不清楚或沒有仔細界定。"},{"en":"Saying “many students” is imprecise if the report needs an exact number.","zh":"如果報告需要確切數字，說「很多學生」就是不精確的。"},{"en":"Imprecise language can confuse readers because they do not know the exact meaning.","zh":"不精確的語言可能令讀者困惑，因為他們不知道確切意思。"},{"en":"The word criticises vagueness, not necessarily total falsehood.","zh":"這個詞批評含糊，而不一定表示完全錯誤。"}],"source":"134 - TV Addiction.pdf","sourcePage":4},{"front":"laden with value judgments","meaning":"帶有價值判斷","examples":[{"en":"The term is laden with value judgments.","zh":"這個術語帶有價值判斷。"},{"en":"Laden with value judgments means filled with opinions about what is good, bad, right, or wrong.","zh":"laden with value judgments 指充滿關於好壞、對錯的看法。"},{"en":"Calling someone lazy may be laden with value judgments if the real issue is illness or stress.","zh":"如果真正問題是疾病或壓力，稱某人懶惰可能帶有價值判斷。"},{"en":"A label laden with value judgments can make discussion emotional rather than objective.","zh":"帶有價值判斷的標籤可以令討論變得情緒化，而不是客觀。"},{"en":"The phrase warns that a word may judge people instead of describing them neutrally.","zh":"這個短語提醒我們，某個詞可能在評判人，而不是中立描述。"}],"source":"134 - TV Addiction.pdf","sourcePage":4},{"front":"capture the essence of","meaning":"捕捉……的本質","examples":[{"en":"The term captures the essence of a real phenomenon.","zh":"這個術語捕捉了一種真實現象的本質。"},{"en":"To capture the essence of something means to express its most important meaning or nature.","zh":"capture the essence of something 指表達某事最重要的意思或本質。"},{"en":"A good photo can capture the essence of a busy street in one image.","zh":"一張好照片可以用一幅圖像捕捉繁忙街道的本質。"},{"en":"A simple example can capture the essence of a difficult grammar rule.","zh":"一個簡單例子可以捕捉一條困難文法規則的本質。"},{"en":"The phrase suggests not every detail is included, but the core idea is clear.","zh":"這個短語暗示未包括每個細節，但核心想法清楚。"}],"source":"134 - TV Addiction.pdf","sourcePage":4},{"front":"a real phenomenon","meaning":"真實現象","examples":[{"en":"TV addiction describes a real phenomenon.","zh":"電視成癮描述了一種真實現象。"},{"en":"A real phenomenon is something that actually happens or exists, even if its name is debated.","zh":"real phenomenon 指實際發生或存在的事情，即使其名稱仍有爭議。"},{"en":"Phone distraction in classrooms is a real phenomenon teachers see every day.","zh":"課室中的手機分心是老師每天看見的真實現象。"},{"en":"When many people report the same experience, it may point to a real phenomenon.","zh":"當許多人報告同一經驗，它可能指向一種真實現象。"},{"en":"The phrase separates actual experience from pure imagination.","zh":"這個短語把實際經驗與純粹想像區分開來。"}],"source":"134 - TV Addiction.pdf","sourcePage":4},{"front":"psychologists and psychiatrists","meaning":"心理學家和精神科醫生","examples":[{"en":"Psychologists and psychiatrists formally define substance dependence.","zh":"心理學家和精神科醫生正式界定物質依賴。"},{"en":"Psychologists and psychiatrists are professionals who study or treat mental processes, behaviour, and mental disorders.","zh":"psychologists and psychiatrists 指研究或治療心理過程、行為和精神障礙的專業人士。"},{"en":"Psychologists may provide therapy, while psychiatrists can often prescribe medicine.","zh":"心理學家可能提供治療，而精神科醫生通常可以處方藥物。"},{"en":"These professionals use definitions so problems are described consistently.","zh":"這些專業人士使用定義，好讓問題被一致地描述。"},{"en":"The phrase refers to experts in mental health and behaviour.","zh":"這個短語指心理健康和行為方面的專家。"}],"source":"134 - TV Addiction.pdf","sourcePage":4},{"front":"formally define","meaning":"正式界定","examples":[{"en":"Psychologists formally define substance dependence as a disorder.","zh":"心理學家把物質依賴正式界定為一種障礙。"},{"en":"To formally define something means to give it an official or carefully accepted meaning.","zh":"formally define something 指給某事一個官方或仔細認可的意思。"},{"en":"A school may formally define bullying so teachers know what behaviour to report.","zh":"學校可能正式界定欺凌，讓老師知道應報告哪些行為。"},{"en":"Formal definitions help researchers compare studies using the same criteria.","zh":"正式定義幫助研究人員使用相同準則比較研究。"},{"en":"The phrase suggests precision and authority.","zh":"這個短語暗示精確性和權威性。"}],"source":"134 - TV Addiction.pdf","sourcePage":4},{"front":"substance dependence","meaning":"物質依賴","examples":[{"en":"Substance dependence is defined by several behavioural criteria.","zh":"物質依賴由幾項行為準則界定。"},{"en":"Substance dependence is a condition in which a person becomes unable to control use of a substance.","zh":"substance dependence 指一個人變得無法控制某種物質使用的狀況。"},{"en":"Alcohol or drug dependence can damage health, work, family life, and judgment.","zh":"酒精或藥物依賴可以損害健康、工作、家庭生活和判斷力。"},{"en":"A person with substance dependence may keep using even after serious negative results.","zh":"有物質依賴的人即使出現嚴重負面後果，仍可能繼續使用。"},{"en":"The phrase is clinical and stronger than simply liking something.","zh":"這個短語屬臨床用語，比單純喜歡某物更強。"}],"source":"134 - TV Addiction.pdf","sourcePage":4},{"front":"a disorder characterised by","meaning":"以……為特徵的障礙","examples":[{"en":"Substance dependence is a disorder characterised by specific criteria.","zh":"物質依賴是一種以特定準則為特徵的障礙。"},{"en":"A disorder characterised by certain signs is a condition known through those repeated features.","zh":"a disorder characterised by certain signs 指透過那些重複特徵被認識的狀況。"},{"en":"Insomnia is a disorder characterised by difficulty sleeping or staying asleep.","zh":"失眠是一種以入睡或維持睡眠困難為特徵的障礙。"},{"en":"If a disorder is characterised by loss of control, treatment may focus on rebuilding control.","zh":"如果一種障礙以失去控制為特徵，治療可能集中於重建控制。"},{"en":"The phrase is formal and often used in medical definitions.","zh":"這個短語較正式，常用於醫學定義。"}],"source":"134 - TV Addiction.pdf","sourcePage":4},{"front":"criteria that include","meaning":"包括……的準則","examples":[{"en":"The disorder is characterised by criteria that include repeated unsuccessful efforts to stop.","zh":"這種障礙以包括反覆但不成功嘗試停止的準則為特徵。"},{"en":"Criteria that include something are standards or signs that list it as one important feature.","zh":"criteria that include something 指把某事列為重要特徵之一的標準。"},{"en":"A scholarship may have criteria that include grades, interview performance, and community service.","zh":"獎學金可能有包括成績、面試表現和社區服務的準則。"},{"en":"Clear criteria help people judge cases fairly instead of relying on feelings.","zh":"清晰準則幫助人們公平判斷個案，而不是依靠感覺。"},{"en":"The phrase introduces the features used to decide whether something qualifies.","zh":"這個短語引入用來決定某事是否符合資格的特徵。"}],"source":"134 - TV Addiction.pdf","sourcePage":5},{"front":"a great deal of time","meaning":"大量時間","examples":[{"en":"Dependence may involve spending a great deal of time using a substance.","zh":"依賴可能涉及花大量時間使用某種物質。"},{"en":"A great deal of time means a large amount of time.","zh":"a great deal of time 指大量時間。"},{"en":"A student may spend a great deal of time revising before a major exam.","zh":"學生可能在大型考試前花大量時間溫習。"},{"en":"Spending a great deal of time on one habit can leave too little time for health or relationships.","zh":"在一個習慣上花大量時間，可能令健康或人際關係時間不足。"},{"en":"The phrase stresses quantity, not whether the time is well used.","zh":"這個短語強調時間數量，而不是時間是否用得好。"}],"source":"134 - TV Addiction.pdf","sourcePage":5},{"front":"more often than one intends","meaning":"比自己原本打算更頻繁","examples":[{"en":"Dependence may involve using something more often than one intends.","zh":"依賴可能涉及比自己原本打算更頻繁地使用某物。"},{"en":"More often than one intends means doing something more frequently than originally planned.","zh":"more often than one intends 指做某事的頻率高於原本計劃。"},{"en":"A person may check social media more often than he intends during study time.","zh":"一個人可能在學習時間比原本打算更頻繁地查看社交媒體。"},{"en":"If a habit happens more often than intended, control may be weakening.","zh":"如果習慣比原本打算更頻繁地發生，控制力可能正在減弱。"},{"en":"The phrase highlights the gap between plan and behaviour.","zh":"這個短語強調計劃與行為之間的差距。"}],"source":"134 - TV Addiction.pdf","sourcePage":5},{"front":"think about reducing use","meaning":"考慮減少使用","examples":[{"en":"Some dependent users think about reducing use.","zh":"一些有依賴的人會考慮減少使用。"},{"en":"To think about reducing use means to consider using something less often or in smaller amounts.","zh":"think about reducing use 指考慮更少次數或更少量地使用某物。"},{"en":"A student may think about reducing phone use after noticing weaker concentration.","zh":"學生注意到專注力下降後，可能考慮減少手機使用。"},{"en":"Thinking about reducing use is a first step, but action and support may still be needed.","zh":"考慮減少使用是第一步，但仍可能需要行動和支援。"},{"en":"The phrase suggests awareness of a problem, not successful change yet.","zh":"這個短語暗示意識到問題，但尚未成功改變。"}],"source":"134 - TV Addiction.pdf","sourcePage":5},{"front":"repeated unsuccessful efforts","meaning":"反覆但不成功的嘗試","examples":[{"en":"Dependence may involve repeated unsuccessful efforts to reduce use.","zh":"依賴可能涉及反覆但不成功地嘗試減少使用。"},{"en":"Repeated unsuccessful efforts are many attempts that fail again and again.","zh":"repeated unsuccessful efforts 指多次嘗試，但一次又一次失敗。"},{"en":"A person may make repeated unsuccessful efforts to stop eating snacks late at night.","zh":"一個人可能反覆但不成功地嘗試停止深夜吃零食。"},{"en":"Repeated unsuccessful efforts can show that a habit is stronger than willpower alone.","zh":"反覆但不成功的嘗試可以顯示習慣強於單靠意志力。"},{"en":"The phrase emphasises both trying and failing repeatedly.","zh":"這個短語同時強調嘗試和反覆失敗。"}],"source":"134 - TV Addiction.pdf","sourcePage":5},{"front":"give up important activities","meaning":"放棄重要活動","examples":[{"en":"Dependent users may give up important activities.","zh":"有依賴的人可能放棄重要活動。"},{"en":"To give up important activities means to stop doing valuable parts of life because of another habit.","zh":"give up important activities 指因另一個習慣而停止做生活中有價值的事情。"},{"en":"A teenager may give up sports practice because gaming takes all evening.","zh":"青少年可能因打機佔據整個晚上而放棄運動訓練。"},{"en":"Giving up important activities can damage friendships, health, learning, and work.","zh":"放棄重要活動可以損害友誼、健康、學習和工作。"},{"en":"The phrase shows that a habit has begun to replace meaningful life activities.","zh":"這個短語顯示某習慣已開始取代有意義的生活活動。"}],"source":"134 - TV Addiction.pdf","sourcePage":5},{"front":"social, family or occupational activities","meaning":"社交、家庭或職業活動","examples":[{"en":"Dependence can interfere with social, family or occupational activities.","zh":"依賴可以干擾社交、家庭或職業活動。"},{"en":"Social, family or occupational activities are activities involving friends, relatives, or work.","zh":"social, family or occupational activities 指涉及朋友、親人或工作的活動。"},{"en":"Dinner with parents, meeting friends, and arriving at work are all examples of these activities.","zh":"與父母吃晚飯、見朋友和上班都是這些活動的例子。"},{"en":"When an addiction interrupts these activities, daily life becomes less balanced.","zh":"當成癮干擾這些活動，日常生活會變得較不平衡。"},{"en":"The phrase covers major areas of normal adult life.","zh":"這個短語涵蓋正常成人生活的主要範疇。"}],"source":"134 - TV Addiction.pdf","sourcePage":5},{"front":"report withdrawal symptoms","meaning":"報稱有戒斷症狀","examples":[{"en":"Some people report withdrawal symptoms when they stop using a substance.","zh":"有些人在停止使用某種物質時報稱有戒斷症狀。"},{"en":"To report withdrawal symptoms means to say that unpleasant reactions appear after stopping something.","zh":"report withdrawal symptoms 指說自己停止某物後出現不適反應。"},{"en":"A patient may report withdrawal symptoms such as headaches, shaking, or anxiety.","zh":"病人可能報稱有頭痛、顫抖或焦慮等戒斷症狀。"},{"en":"Reporting withdrawal symptoms helps doctors understand how dependent the body or mind has become.","zh":"報稱有戒斷症狀幫助醫生理解身體或心理依賴程度。"},{"en":"The phrase focuses on what people say they experience.","zh":"這個短語重點是人們陳述自己經歷了甚麼。"}],"source":"134 - TV Addiction.pdf","sourcePage":5},{"front":"withdrawal symptoms","meaning":"戒斷症狀","examples":[{"en":"Withdrawal symptoms may appear when a dependent person stops using something.","zh":"當有依賴的人停止使用某物時，戒斷症狀可能出現。"},{"en":"Withdrawal symptoms are unpleasant physical or mental reactions after stopping a substance or habit.","zh":"withdrawal symptoms 指停止某種物質或習慣後出現的身體或心理不適反應。"},{"en":"Someone reducing caffeine may have withdrawal symptoms such as headaches or tiredness.","zh":"減少咖啡因的人可能有頭痛或疲倦等戒斷症狀。"},{"en":"Withdrawal symptoms can make quitting difficult because the body or mind demands the old habit.","zh":"戒斷症狀會令戒除變困難，因為身體或心理要求回到舊習慣。"},{"en":"The phrase is common in discussions of dependence and addiction.","zh":"這個短語常見於依賴和成癮討論。"}],"source":"134 - TV Addiction.pdf","sourcePage":5},{"front":"all these criteria","meaning":"所有這些準則","examples":[{"en":"All these criteria can apply to heavy television viewers.","zh":"所有這些準則都可以適用於重度電視觀眾。"},{"en":"All these criteria means every standard or sign just mentioned.","zh":"all these criteria 指剛提到的每一項標準或跡象。"},{"en":"If all these criteria are met, a school may classify the case as bullying.","zh":"如果所有這些準則都符合，學校可能把個案歸類為欺凌。"},{"en":"All these criteria help researchers judge behaviour more systematically.","zh":"所有這些準則幫助研究人員更有系統地判斷行為。"},{"en":"The phrase refers back to a full list, not one single point.","zh":"這個短語指回完整清單，而不是單一點。"}],"source":"134 - TV Addiction.pdf","sourcePage":5},{"front":"apply to","meaning":"適用於……","examples":[{"en":"The criteria can apply to people who watch a lot of television.","zh":"這些準則可以適用於大量看電視的人。"},{"en":"To apply to someone or something means to be relevant or suitable for that case.","zh":"apply to someone or something 指與某人或某情況相關或適合。"},{"en":"A discount may apply to students who show a valid card.","zh":"折扣可能適用於出示有效學生證的學生。"},{"en":"A rule should not apply to a situation if the situation is clearly different.","zh":"如果情況明顯不同，某條規則不應適用於該情況。"},{"en":"The phrase connects a rule, idea, or description with a specific case.","zh":"這個短語把規則、想法或描述與具體個案連起來。"}],"source":"134 - TV Addiction.pdf","sourcePage":5},{"front":"in itself","meaning":"本身","examples":[{"en":"Watching television, in itself, is not necessarily problematic.","zh":"看電視本身不一定有問題。"},{"en":"In itself means considered alone, without extra context or consequences.","zh":"in itself 指單獨考慮某事，不加入額外背景或後果。"},{"en":"Using a phone, in itself, is not bad; the problem may be using it during study time.","zh":"使用手機本身並不壞；問題可能是在學習時間使用。"},{"en":"A mistake in itself may be minor, but repeated mistakes can become serious.","zh":"一個錯誤本身可能很小，但重複錯誤可以變得嚴重。"},{"en":"The phrase separates the thing itself from how it is used.","zh":"這個短語把事物本身與其使用方式區分開來。"}],"source":"134 - TV Addiction.pdf","sourcePage":6},{"front":"problematic","meaning":"有問題的","examples":[{"en":"Television watching is not always problematic.","zh":"看電視並不總是有問題的。"},{"en":"Problematic means causing difficulty, concern, or possible harm.","zh":"problematic 指造成困難、憂慮或可能傷害。"},{"en":"A student’s late-night gaming becomes problematic when it affects sleep and grades.","zh":"當學生深夜打機影響睡眠和成績，它就變得有問題。"},{"en":"A behaviour is more problematic when people cannot stop it despite negative results.","zh":"當人們即使有負面後果仍無法停止某行為，該行為就更有問題。"},{"en":"The word does not mean always terrible; it means there is a real issue to consider.","zh":"這個詞不表示總是糟糕；它表示有真正問題需要考慮。"}],"source":"134 - TV Addiction.pdf","sourcePage":6},{"front":"teach and amuse","meaning":"教育並娛樂","examples":[{"en":"Television can teach and amuse.","zh":"電視可以教育並娛樂。"},{"en":"To teach and amuse means to provide learning and entertainment at the same time.","zh":"teach and amuse 指同時提供學習和娛樂。"},{"en":"A children’s science show can teach and amuse by explaining animals with funny scenes.","zh":"兒童科學節目可以透過有趣場景解釋動物，達到教育並娛樂的效果。"},{"en":"Programmes that teach and amuse may keep students interested while giving useful knowledge.","zh":"教育並娛樂的節目可以在提供有用知識時保持學生興趣。"},{"en":"The phrase shows that entertainment and education can happen together.","zh":"這個短語顯示娛樂和教育可以同時發生。"}],"source":"134 - TV Addiction.pdf","sourcePage":6},{"front":"reach aesthetic heights","meaning":"達到審美高度","examples":[{"en":"Television can reach aesthetic heights.","zh":"電視可以達到審美高度。"},{"en":"To reach aesthetic heights means to achieve a very high level of artistic beauty or quality.","zh":"reach aesthetic heights 指達到很高的藝術美感或質素。"},{"en":"A documentary can reach aesthetic heights through careful music, images, and storytelling.","zh":"紀錄片可以透過仔細的音樂、影像和敘事達到審美高度。"},{"en":"When a TV drama reaches aesthetic heights, viewers may value it as art, not just entertainment.","zh":"當電視劇達到審美高度，觀眾可能把它視為藝術，而不只是娛樂。"},{"en":"The phrase praises artistic achievement.","zh":"這個短語讚揚藝術成就。"}],"source":"134 - TV Addiction.pdf","sourcePage":6},{"front":"much-needed distraction and escape","meaning":"急需的分心和逃避","examples":[{"en":"Television can provide much-needed distraction and escape.","zh":"電視可以提供急需的分心和逃避。"},{"en":"Much-needed distraction and escape means a welcome break from stress, worry, or daily pressure.","zh":"much-needed distraction and escape 指從壓力、憂慮或日常負擔中得到受歡迎的休息。"},{"en":"After a difficult workday, a light comedy may provide much-needed distraction and escape.","zh":"艱難工作日後，一齣輕鬆喜劇可能提供急需的分心和逃避。"},{"en":"Such escape can help people rest, but too much may prevent them from solving real problems.","zh":"這種逃避可以幫助人休息，但過多可能阻止人解決真正問題。"},{"en":"The phrase describes relief that feels necessary, not just random entertainment.","zh":"這個短語描述感覺必要的舒緩，而不只是隨意娛樂。"}],"source":"134 - TV Addiction.pdf","sourcePage":6},{"front":"difficulty arises when","meaning":"困難在……時出現","examples":[{"en":"The difficulty arises when people cannot reduce their viewing.","zh":"困難在人們無法減少觀看時出現。"},{"en":"Difficulty arises when means the problem begins or becomes clear at that point.","zh":"difficulty arises when 指問題在某一刻開始或變得清楚。"},{"en":"In group work, difficulty arises when no one knows who is responsible.","zh":"在小組工作中，困難在沒有人知道誰負責時出現。"},{"en":"Difficulty arises when a harmless habit starts harming sleep, study, or relationships.","zh":"當無害習慣開始損害睡眠、學習或關係，困難就出現。"},{"en":"The phrase introduces the condition that creates trouble.","zh":"這個短語引入造成麻煩的條件。"}],"source":"134 - TV Addiction.pdf","sourcePage":6},{"front":"strongly sense that","meaning":"強烈感到","examples":[{"en":"Some viewers strongly sense that they watch too much.","zh":"有些觀眾強烈感到自己看太多電視。"},{"en":"To strongly sense that something is true means to feel clearly that it is true, even without exact proof.","zh":"strongly sense that something is true 指清楚感到某事是真的，即使沒有確切證據。"},{"en":"A student may strongly sense that she needs rest before her body completely breaks down.","zh":"學生可能在身體完全崩潰前強烈感到自己需要休息。"},{"en":"Strongly sensing a problem can lead people to seek help or change habits.","zh":"強烈感到問題存在可以令人尋求幫助或改變習慣。"},{"en":"The phrase describes a clear inner awareness.","zh":"這個短語描述清晰的內在覺察。"}],"source":"134 - TV Addiction.pdf","sourcePage":6},{"front":"ought not to","meaning":"不應該","examples":[{"en":"Heavy viewers may feel that they ought not to watch so much TV.","zh":"重度觀眾可能覺得自己不應該看那麼多電視。"},{"en":"Ought not to means should not, often because something is unwise or wrong.","zh":"ought not to 指不應該，通常因為某事不明智或不正確。"},{"en":"Students ought not to copy homework because it stops real learning.","zh":"學生不應該抄功課，因為這會阻礙真正學習。"},{"en":"A person may know they ought not to stay up late but still keep watching videos.","zh":"一個人可能知道自己不應該熬夜，但仍繼續看影片。"},{"en":"The phrase expresses moral, practical, or personal pressure.","zh":"這個短語表達道德、實際或個人壓力。"}],"source":"134 - TV Addiction.pdf","sourcePage":6},{"front":"find themselves strangely unable to","meaning":"發現自己莫名地無法……","examples":[{"en":"Some viewers find themselves strangely unable to reduce their viewing.","zh":"有些觀眾發現自己莫名地無法減少觀看時間。"},{"en":"To find themselves strangely unable to do something means to realise they cannot do it, even though they expected to.","zh":"find themselves strangely unable to do something 指發現自己做不到某事，即使原本以為可以。"},{"en":"A student may find herself strangely unable to stop checking messages while studying.","zh":"學生可能發現自己莫名地無法在學習時停止查看訊息。"},{"en":"This feeling can be worrying because the person’s behaviour no longer matches their intention.","zh":"這種感覺可能令人擔心，因為人的行為不再符合自己的意圖。"},{"en":"The phrase suggests surprise at one’s own lack of control.","zh":"這個短語暗示對自己缺乏控制感到驚訝。"}],"source":"134 - TV Addiction.pdf","sourcePage":6},{"front":"reduce their viewing","meaning":"減少觀看時間","examples":[{"en":"Heavy viewers may struggle to reduce their viewing.","zh":"重度觀眾可能難以減少觀看時間。"},{"en":"To reduce their viewing means to watch less television than before.","zh":"reduce their viewing 指比以前少看電視。"},{"en":"A family may reduce their viewing by turning off the TV during dinner.","zh":"家庭可以透過晚飯期間關掉電視來減少觀看時間。"},{"en":"Reducing viewing can create more time for sleep, reading, exercise, and conversation.","zh":"減少觀看時間可以為睡眠、閱讀、運動和交談創造更多時間。"},{"en":"The phrase focuses on cutting down screen time, not stopping completely.","zh":"這個短語重點是減少螢幕時間，而不是完全停止。"}],"source":"134 - TV Addiction.pdf","sourcePage":6},{"front":"exert its pull","meaning":"發揮其吸引力","examples":[{"en":"The medium exerts its pull on heavy viewers.","zh":"這種媒介對重度觀眾發揮其吸引力。"},{"en":"To exert its pull means to use its attraction or influence on people.","zh":"exert its pull 指對人發揮吸引或影響力量。"},{"en":"A sale sign can exert its pull on shoppers who planned not to buy anything.","zh":"減價標誌可以對原本不打算購物的顧客發揮吸引力。"},{"en":"Television exerts its pull through bright images, sound, movement, and habit.","zh":"電視透過鮮明影像、聲音、動作和習慣發揮其吸引力。"},{"en":"The phrase suggests a force that draws people in.","zh":"這個短語暗示一種把人拉進去的力量。"}],"source":"134 - TV Addiction.pdf","sourcePage":6},{"front":"heavy viewers","meaning":"重度觀眾","examples":[{"en":"Heavy viewers may need better control over their lives.","zh":"重度觀眾可能需要更好地掌控自己的生活。"},{"en":"Heavy viewers are people who watch television for a large amount of time.","zh":"heavy viewers 指花大量時間看電視的人。"},{"en":"A heavy viewer may keep the TV on for several hours every night.","zh":"重度觀眾可能每晚開着電視數小時。"},{"en":"Heavy viewers can miss sleep or exercise if watching becomes the main evening activity.","zh":"如果看電視成為晚上的主要活動，重度觀眾可能錯過睡眠或運動。"},{"en":"The phrase describes viewing amount, not body weight.","zh":"這個短語描述觀看量，而不是體重。"}],"source":"134 - TV Addiction.pdf","sourcePage":7},{"front":"gain better control over","meaning":"更好地掌控……","examples":[{"en":"Knowledge may help heavy viewers gain better control over their lives.","zh":"知識可能幫助重度觀眾更好地掌控自己的生活。"},{"en":"To gain better control over something means to manage it more successfully.","zh":"gain better control over something 指更成功地管理某事。"},{"en":"A student can gain better control over study time by turning off notifications.","zh":"學生可以透過關閉通知，更好地掌控學習時間。"},{"en":"People gain better control over habits when they understand what triggers them.","zh":"當人們理解觸發習慣的原因，就能更好地掌控習慣。"},{"en":"The phrase suggests improvement in self-management.","zh":"這個短語暗示自我管理有所改善。"}],"source":"134 - TV Addiction.pdf","sourcePage":7},{"front":"the amount of time","meaning":"……的時間量","examples":[{"en":"The amount of time people spend watching television is astonishing.","zh":"人們花在看電視上的時間量令人驚訝。"},{"en":"The amount of time means how long people spend doing something.","zh":"amount of time 指人們做某事所花的時間長度。"},{"en":"A teacher may ask students to record the amount of time they spend reading each week.","zh":"老師可能要求學生記錄每週閱讀的時間量。"},{"en":"The amount of time spent on screens can affect sleep and attention.","zh":"花在螢幕上的時間量可以影響睡眠和注意力。"},{"en":"The phrase focuses on duration, not quality.","zh":"這個短語重點是時間長度，而不是質素。"}],"source":"134 - TV Addiction.pdf","sourcePage":7},{"front":"spend watching television","meaning":"花時間看電視","examples":[{"en":"People spend a large amount of time watching television.","zh":"人們花大量時間看電視。"},{"en":"To spend time watching television means to use time to watch TV programmes or broadcasts.","zh":"spend time watching television 指使用時間觀看電視節目或播放內容。"},{"en":"Some families spend evenings watching television after dinner.","zh":"有些家庭晚飯後花晚上時間看電視。"},{"en":"Spending too much time watching television can leave less time for study or exercise.","zh":"花太多時間看電視可以令學習或運動時間減少。"},{"en":"The phrase describes time use, not money use.","zh":"這個短語描述時間使用，而不是金錢使用。"}],"source":"134 - TV Addiction.pdf","sourcePage":7},{"front":"astonishing","meaning":"令人驚訝的","examples":[{"en":"The amount of TV viewing is astonishing.","zh":"看電視的時間量令人驚訝。"},{"en":"Astonishing means very surprising or difficult to believe.","zh":"astonishing 指非常令人驚訝或難以相信。"},{"en":"It is astonishing that a short video can distract someone for an entire hour.","zh":"一段短片可以令人分心整整一小時，這令人驚訝。"},{"en":"Astonishing figures can make readers realise a problem is bigger than expected.","zh":"令人驚訝的數字可以令讀者意識到問題比預期大。"},{"en":"The word is stronger than surprising.","zh":"這個詞比 surprising 更強。"}],"source":"134 - TV Addiction.pdf","sourcePage":7},{"front":"on average","meaning":"平均而言","examples":[{"en":"On average, people in industrialised countries watch TV for three hours a day.","zh":"平均而言，工業化國家的人每天看三小時電視。"},{"en":"On average means calculated across a group, not true for every single person.","zh":"on average 指按整個群體計算，而不是每個人都如此。"},{"en":"On average, students may spend one hour travelling to school each day.","zh":"平均而言，學生每天可能花一小時上學。"},{"en":"Average numbers can hide differences between light users and heavy users.","zh":"平均數字可以掩蓋輕度使用者和重度使用者之間的差異。"},{"en":"The phrase is useful when summarising data.","zh":"這個短語適合總結數據。"}],"source":"134 - TV Addiction.pdf","sourcePage":7},{"front":"industrialized world","meaning":"工業化世界","examples":[{"en":"People in the industrialized world spend much of their leisure time watching TV.","zh":"工業化世界的人把許多閒暇時間用於看電視。"},{"en":"The industrialized world means countries with developed industries, cities, infrastructure, and economies.","zh":"industrialized world 指具有發達工業、城市、基礎設施和經濟的國家。"},{"en":"In the industrialized world, many homes have easy access to electricity, media, and screens.","zh":"在工業化世界中，許多家庭容易接觸電力、媒體和螢幕。"},{"en":"Habits in the industrialized world may differ from those in poorer rural areas.","zh":"工業化世界的習慣可能與較貧困鄉村地區不同。"},{"en":"The phrase is broad and should not be treated as meaning every person lives the same way.","zh":"這個短語很廣泛，不應理解為每個人都以同樣方式生活。"}],"source":"134 - TV Addiction.pdf","sourcePage":7},{"front":"devote time to","meaning":"把時間用於……","examples":[{"en":"Many people devote three hours a day to watching television.","zh":"許多人每天把三小時用於看電視。"},{"en":"To devote time to something means to give time regularly or seriously to it.","zh":"devote time to something 指定期或認真地把時間給予某事。"},{"en":"A student may devote twenty minutes a day to vocabulary review.","zh":"學生可能每天把二十分鐘用於詞彙複習。"},{"en":"Devoting too much time to one activity can crowd out other responsibilities.","zh":"把太多時間用於一項活動，可以擠走其他責任。"},{"en":"The phrase suggests deliberate or repeated use of time.","zh":"這個短語暗示有意或反覆地使用時間。"}],"source":"134 - TV Addiction.pdf","sourcePage":7},{"front":"the pursuit","meaning":"這項活動；這項消遣","examples":[{"en":"Television viewing takes up much time devoted to the pursuit.","zh":"看電視佔用了大量用於這項消遣的時間。"},{"en":"The pursuit means the activity being discussed or followed.","zh":"the pursuit 指正在討論或進行的活動。"},{"en":"In the pursuit of fitness, a person may run before work each morning.","zh":"在追求健身這項活動中，一個人可能每天早上上班前跑步。"},{"en":"If a pursuit takes too much time, other parts of life may suffer.","zh":"如果一項活動佔用太多時間，生活其他部分可能受影響。"},{"en":"The word is more formal than activity or hobby.","zh":"這個詞比 activity 或 hobby 更正式。"}],"source":"134 - TV Addiction.pdf","sourcePage":7},{"front":"fully half of","meaning":"足足一半的……","examples":[{"en":"Television takes up fully half of many people’s leisure time.","zh":"電視佔去許多人閒暇時間足足一半。"},{"en":"Fully half of means as much as one half, often more than expected.","zh":"fully half of 指多達一半，通常比預期多。"},{"en":"A project may take fully half of the team’s weekly working hours.","zh":"一個項目可能佔去團隊每週工作時間足足一半。"},{"en":"If TV takes fully half of leisure time, there may be little time left for other hobbies.","zh":"如果電視佔去閒暇時間足足一半，其他興趣可能只剩很少時間。"},{"en":"The phrase emphasises that the proportion is surprisingly large.","zh":"這個短語強調比例大得令人驚訝。"}],"source":"134 - TV Addiction.pdf","sourcePage":7},{"front":"leisure time","meaning":"閒暇時間","examples":[{"en":"Watching TV takes up a large share of leisure time.","zh":"看電視佔去很大部分閒暇時間。"},{"en":"Leisure time is free time when a person is not working, studying, or doing necessary duties.","zh":"leisure time 指一個人不用工作、學習或處理必要責任的自由時間。"},{"en":"People may use leisure time for reading, exercise, hobbies, or meeting friends.","zh":"人們可能把閒暇時間用於閱讀、運動、興趣或見朋友。"},{"en":"If one habit fills all leisure time, life can become narrow and repetitive.","zh":"如果一個習慣填滿所有閒暇時間，生活可能變得狹窄而重複。"},{"en":"The phrase refers to personal free time, not paid work hours.","zh":"這個短語指個人自由時間，而不是有薪工作時間。"}],"source":"134 - TV Addiction.pdf","sourcePage":7},{"front":"any single activity save","meaning":"除了……之外的任何單一活動","examples":[{"en":"People spend more time on television than on any single activity save work and sleep.","zh":"除了工作和睡眠之外，人們花在電視上的時間比任何單一活動都多。"},{"en":"Any single activity save something means any one activity except the thing named.","zh":"any single activity save something 指除了所提事物以外的任何一項活動。"},{"en":"A person may spend more time commuting than on any single activity save work and sleep.","zh":"一個人花在通勤上的時間可能比除了工作和睡眠之外的任何單一活動都多。"},{"en":"This phrase highlights how dominant one activity is compared with almost all others.","zh":"這個短語強調某活動相對於幾乎所有其他活動有多佔主導。"},{"en":"Save is formal here and means except.","zh":"這裡的 save 較正式，意思是「除了」。"}],"source":"134 - TV Addiction.pdf","sourcePage":8},{"front":"at this rate","meaning":"照這個速度；按這個情況","examples":[{"en":"At this rate, a person could spend nine years watching television.","zh":"按這個情況，一個人可能花九年看電視。"},{"en":"At this rate means if the current speed or pattern continues.","zh":"at this rate 指如果目前速度或模式持續。"},{"en":"At this rate, we will finish the project before Friday.","zh":"照這個速度，我們會在星期五前完成項目。"},{"en":"At this rate, a student who sleeps five hours nightly may soon feel exhausted.","zh":"按這個情況，每晚睡五小時的學生可能很快感到筋疲力盡。"},{"en":"The phrase uses the present trend to predict a future result.","zh":"這個短語用現在趨勢預測未來結果。"}],"source":"134 - TV Addiction.pdf","sourcePage":8},{"front":"in front of the tube","meaning":"在電視機前","examples":[{"en":"A person might spend nine years in front of the tube.","zh":"一個人可能花九年在電視機前。"},{"en":"In front of the tube means sitting before the television watching programmes.","zh":"in front of the tube 指坐在電視機前觀看節目。"},{"en":"After work, some people spend the whole evening in front of the tube.","zh":"下班後，有些人整晚待在電視機前。"},{"en":"Too much time in front of the tube can replace exercise, reading, and conversation.","zh":"在電視機前花太多時間可以取代運動、閱讀和交談。"},{"en":"The phrase is informal and slightly old-fashioned.","zh":"這個短語較口語，並帶一點舊式用法。"}],"source":"134 - TV Addiction.pdf","sourcePage":8},{"front":"commentators","meaning":"評論者","examples":[{"en":"Some commentators think people simply enjoy television.","zh":"一些評論者認為人們只是享受電視。"},{"en":"Commentators are people who give opinions, explanations, or analysis about public issues.","zh":"commentators 指對公共議題給予意見、解釋或分析的人。"},{"en":"Sports commentators explain what is happening during a match.","zh":"體育評論員會在比賽期間解釋正在發生的事情。"},{"en":"Social commentators may discuss why television remains popular.","zh":"社會評論者可能討論為何電視仍然受歡迎。"},{"en":"The word refers to people who comment publicly, not ordinary viewers only.","zh":"這個詞指公開發表評論的人，而不只是普通觀眾。"}],"source":"134 - TV Addiction.pdf","sourcePage":8},{"front":"make a conscious decision to","meaning":"有意識地決定去……","examples":[{"en":"Some commentators say people make a conscious decision to watch TV.","zh":"一些評論者說人們有意識地決定去看電視。"},{"en":"To make a conscious decision to do something means to choose it deliberately and with awareness.","zh":"make a conscious decision to do something 指有意識並刻意選擇做某事。"},{"en":"A student may make a conscious decision to study before opening social media.","zh":"學生可能有意識地決定先學習，再打開社交媒體。"},{"en":"Conscious decisions can be weakened when habits and distractions become powerful.","zh":"當習慣和干擾變得強大，有意識決定可能被削弱。"},{"en":"The phrase contrasts deliberate choice with automatic behaviour.","zh":"這個短語把刻意選擇與自動行為作對比。"}],"source":"134 - TV Addiction.pdf","sourcePage":8},{"front":"the whole story","meaning":"全部原因；完整解釋","examples":[{"en":"Enjoyment may not be the whole story.","zh":"享受未必是完整解釋。"},{"en":"The whole story means the complete explanation of a situation.","zh":"the whole story 指某情況的完整解釋。"},{"en":"A student’s poor score may not be the whole story if illness affected the exam.","zh":"如果疾病影響考試，學生低分未必是全部原因。"},{"en":"When a simple explanation is not the whole story, other causes must be considered.","zh":"當簡單解釋不是完整解釋時，必須考慮其他原因。"},{"en":"The phrase warns that one reason may be incomplete.","zh":"這個短語提醒我們，一個原因可能並不完整。"}],"source":"134 - TV Addiction.pdf","sourcePage":8},{"front":"experience misgivings about","meaning":"對……感到疑慮","examples":[{"en":"Many people experience misgivings about how much TV they watch.","zh":"許多人對自己看電視的時間感到疑慮。"},{"en":"To experience misgivings about something means to feel doubts, worry, or unease about it.","zh":"experience misgivings about something 指對某事感到懷疑、擔心或不安。"},{"en":"A parent may experience misgivings about giving a young child a smartphone.","zh":"父母可能對給年幼孩子智能手機感到疑慮。"},{"en":"Misgivings can appear when behaviour feels pleasant but also wrong or harmful.","zh":"當行為令人愉快但也感覺錯誤或有害，疑慮可能出現。"},{"en":"The phrase describes uneasy doubt, not a firm decision.","zh":"這個短語描述不安的懷疑，而不是堅定決定。"}],"source":"134 - TV Addiction.pdf","sourcePage":8},{"front":"Gallup polls","meaning":"蓋洛普民意調查","examples":[{"en":"Gallup polls asked adults and teenagers about television viewing.","zh":"蓋洛普民意調查詢問成年人和青少年有關看電視的情況。"},{"en":"Gallup polls are surveys conducted by the Gallup organisation to measure public opinion.","zh":"Gallup polls 指由蓋洛普機構進行、用來量度民意的調查。"},{"en":"Gallup polls may ask people about politics, health, habits, or social attitudes.","zh":"蓋洛普民意調查可能詢問人們政治、健康、習慣或社會態度。"},{"en":"Polls can show patterns in opinion, but answers depend on who is asked and how questions are worded.","zh":"民意調查可以顯示意見模式，但答案取決於問了誰和問題如何表述。"},{"en":"The phrase refers to organised opinion surveys.","zh":"這個短語指有組織的意見調查。"}],"source":"134 - TV Addiction.pdf","sourcePage":8},{"front":"two out of five","meaning":"五分之二","examples":[{"en":"Two out of five adult respondents said they watched too much TV.","zh":"五分之二的成年受訪者表示自己看太多電視。"},{"en":"Two out of five means two people or items in every group of five.","zh":"two out of five 指每五個人或物中有兩個。"},{"en":"If two out of five students forget homework, the teacher may change the reminder system.","zh":"如果五分之二學生忘記交功課，老師可能改變提醒系統。"},{"en":"Two out of five is the same as forty percent.","zh":"五分之二等於百分之四十。"},{"en":"The phrase expresses a proportion in simple everyday language.","zh":"這個短語用簡單日常語言表達比例。"}],"source":"134 - TV Addiction.pdf","sourcePage":8},{"front":"adult respondents","meaning":"成年受訪者","examples":[{"en":"Adult respondents reported watching too much television.","zh":"成年受訪者報稱自己看太多電視。"},{"en":"Adult respondents are grown-up people who answer questions in a survey.","zh":"adult respondents 指在調查中回答問題的成年人。"},{"en":"Adult respondents in a health survey may report exercise, diet, and sleep habits.","zh":"健康調查中的成年受訪者可能報告運動、飲食和睡眠習慣。"},{"en":"If adult respondents answer honestly, survey results become more useful.","zh":"如果成年受訪者誠實回答，調查結果會更有用。"},{"en":"The phrase is formal and common in research reports.","zh":"這個短語較正式，常見於研究報告。"}],"source":"134 - TV Addiction.pdf","sourcePage":8},{"front":"seven out of ten","meaning":"十分之七","examples":[{"en":"Seven out of ten teenagers said they watched too much television.","zh":"十分之七的青少年表示自己看太多電視。"},{"en":"Seven out of ten means seven people or items in every group of ten.","zh":"seven out of ten 指每十個人或物中有七個。"},{"en":"If seven out of ten customers prefer online booking, a shop should improve its website.","zh":"如果十分之七顧客偏好網上預約，商店應改善網站。"},{"en":"Seven out of ten is a large majority, not a small minority.","zh":"十分之七是很大多數，而不是少數。"},{"en":"The phrase makes percentages easier to understand.","zh":"這個短語令百分比更容易理解。"}],"source":"134 - TV Addiction.pdf","sourcePage":8},{"front":"consistently shown","meaning":"一直顯示","examples":[{"en":"Other surveys have consistently shown that some adults call themselves TV addicts.","zh":"其他調查一直顯示有些成年人自稱電視成癮者。"},{"en":"Consistently shown means shown repeatedly in a similar way over time or across studies.","zh":"consistently shown 指在一段時間內或多項研究中反覆以相似方式顯示。"},{"en":"Tests have consistently shown that regular sleep improves concentration.","zh":"測試一直顯示規律睡眠改善專注力。"},{"en":"When several surveys consistently show the same pattern, the finding becomes more convincing.","zh":"當多項調查一直顯示同一模式，該發現會更令人信服。"},{"en":"The phrase stresses repeated evidence, not one isolated result.","zh":"這個短語強調重複證據，而不是單一孤立結果。"}],"source":"134 - TV Addiction.pdf","sourcePage":9},{"front":"roughly 10 percent","meaning":"大約10%","examples":[{"en":"Roughly 10 percent of adults call themselves TV addicts.","zh":"大約10%的成年人自稱電視成癮者。"},{"en":"Roughly 10 percent means about ten percent, not exactly ten percent.","zh":"roughly 10 percent 指大約百分之十，而不是精確百分之十。"},{"en":"Roughly 10 percent of a class of thirty students is about three students.","zh":"三十人的班級中，大約10%就是約三名學生。"},{"en":"Researchers use roughly when the number is approximate or rounded.","zh":"當數字是估計或四捨五入時，研究人員會使用 roughly。"},{"en":"The phrase gives a useful estimate without pretending to be exact.","zh":"這個短語提供有用估算，而不假裝精確。"}],"source":"134 - TV Addiction.pdf","sourcePage":9},{"front":"call themselves","meaning":"自稱","examples":[{"en":"Some adults call themselves TV addicts.","zh":"有些成年人自稱電視成癮者。"},{"en":"To call themselves something means to describe themselves using that label.","zh":"call themselves something 指用某標籤描述自己。"},{"en":"A student may call herself a beginner even after learning English for years.","zh":"即使學英文多年，學生可能仍自稱初學者。"},{"en":"What people call themselves can reveal how they understand their own behaviour.","zh":"人們如何自稱可以揭示他們如何理解自己的行為。"},{"en":"The phrase focuses on self-description, not an official diagnosis.","zh":"這個短語重點是自我描述，而不是官方診斷。"}],"source":"134 - TV Addiction.pdf","sourcePage":9},{"front":"TV addicts","meaning":"電視成癮者","examples":[{"en":"Some adults describe themselves as TV addicts.","zh":"有些成年人把自己描述為電視成癮者。"},{"en":"TV addicts are people who feel unable to control how much television they watch.","zh":"TV addicts 指覺得自己無法控制看電視時間的人。"},{"en":"A TV addict may cancel exercise or sleep just to keep watching one more programme.","zh":"電視成癮者可能為了多看一個節目而取消運動或睡眠。"},{"en":"Calling someone a TV addict can be informal, so clinical judgment needs clearer criteria.","zh":"稱某人為電視成癮者可能較非正式，所以臨床判斷需要更清楚準則。"},{"en":"The phrase suggests heavy dependence, not ordinary enjoyment.","zh":"這個短語暗示重度依賴，而不是普通享受。"}],"source":"134 - TV Addiction.pdf","sourcePage":9},{"front":"have such a hold on","meaning":"對……有如此大的吸引力","examples":[{"en":"Television has such a hold on many viewers.","zh":"電視對許多觀眾有如此大的吸引力。"},{"en":"To have such a hold on someone means to have a very strong influence or attraction over them.","zh":"have such a hold on someone 指對某人有非常強的影響力或吸引力。"},{"en":"A phone app can have such a hold on users that they check it before getting out of bed.","zh":"手機應用程式可以對用戶有如此大的吸引力，以致他們起床前先查看它。"},{"en":"When something has such a hold on people, they may act against their own plans.","zh":"當某物對人有如此大的吸引力，他們可能違背自己的計劃行動。"},{"en":"The phrase suggests powerful control or attraction.","zh":"這個短語暗示強大的控制力或吸引力。"}],"source":"134 - TV Addiction.pdf","sourcePage":9},{"front":"in part","meaning":"部分地","examples":[{"en":"The attraction comes in part from the orienting response.","zh":"這種吸引力部分地來自定向反應。"},{"en":"In part means partly, but not completely.","zh":"in part 指部分地，但不是完全地。"},{"en":"A student’s progress is in part due to practice and in part due to confidence.","zh":"學生的進步部分地來自練習，也部分地來自信心。"},{"en":"If a problem is explained only in part, other causes still need attention.","zh":"如果問題只被部分地解釋，其他原因仍需要注意。"},{"en":"The phrase gives a careful partial explanation.","zh":"這個短語提供謹慎的部分解釋。"}],"source":"134 - TV Addiction.pdf","sourcePage":9},{"front":"spring from","meaning":"源於","examples":[{"en":"The attraction seems to spring from a biological response.","zh":"這種吸引力似乎源於一種生物反應。"},{"en":"To spring from something means to come from or be caused by it.","zh":"spring from something 指來自或由某事造成。"},{"en":"A child’s fear may spring from a bad experience with dogs.","zh":"孩子對狗的恐懼可能源於一次不好的經驗。"},{"en":"If a habit springs from stress, removing the stress may help change the habit.","zh":"如果習慣源於壓力，減少壓力可能有助改變習慣。"},{"en":"The phrase points to the origin or source of something.","zh":"這個短語指出某事的起源或來源。"}],"source":"134 - TV Addiction.pdf","sourcePage":9},{"front":"biological orienting response","meaning":"生物性定向反應","examples":[{"en":"The attraction of television may spring from the biological orienting response.","zh":"電視的吸引力可能源於生物性定向反應。"},{"en":"The biological orienting response is the body’s automatic reaction to sudden or new sights and sounds.","zh":"biological orienting response 指身體對突然或新奇視覺和聲音的自動反應。"},{"en":"People may turn their heads when a door slams because of this response.","zh":"人們聽到門砰一聲關上時轉頭，可能就是因為這種反應。"},{"en":"Television can use sudden movement and sound to trigger the biological orienting response.","zh":"電視可以利用突然動作和聲音觸發生物性定向反應。"},{"en":"The phrase explains attention as a bodily reaction, not just a choice.","zh":"這個短語把注意力解釋為身體反應，而不只是選擇。"}],"source":"134 - TV Addiction.pdf","sourcePage":9},{"front":"first described by","meaning":"首次由……描述","examples":[{"en":"The orienting response was first described by Ivan Pavlov.","zh":"定向反應首次由 Ivan Pavlov 描述。"},{"en":"First described by someone means that person was the first to explain or report it formally.","zh":"first described by someone 指某人首次正式解釋或報告某事。"},{"en":"A disease may be first described by a doctor who notices a new pattern of symptoms.","zh":"一種疾病可能首次由注意到新症狀模式的醫生描述。"},{"en":"Being first described by a scientist gives historical credit for the idea.","zh":"某概念首次由某科學家描述，就是給予其歷史功勞。"},{"en":"The phrase identifies the earliest formal description.","zh":"這個短語指出最早的正式描述。"}],"source":"134 - TV Addiction.pdf","sourcePage":9},{"front":"instinctive visual or auditory reaction","meaning":"本能的視覺或聽覺反應","examples":[{"en":"The orienting response is an instinctive visual or auditory reaction.","zh":"定向反應是一種本能的視覺或聽覺反應。"},{"en":"An instinctive visual or auditory reaction is an automatic response to something seen or heard.","zh":"instinctive visual or auditory reaction 指對所見或所聽事物的自動反應。"},{"en":"Turning toward a sudden shout is an instinctive auditory reaction.","zh":"轉向突然叫喊聲是一種本能的聽覺反應。"},{"en":"Such reactions help people notice possible danger before thinking carefully.","zh":"這類反應幫助人們在仔細思考前注意可能危險。"},{"en":"The phrase combines automatic behaviour with sight or hearing.","zh":"這個短語把自動行為與視覺或聽覺連起來。"}],"source":"134 - TV Addiction.pdf","sourcePage":9},{"front":"sudden or novel stimulus","meaning":"突然或新奇的刺激","examples":[{"en":"The orienting response reacts to any sudden or novel stimulus.","zh":"定向反應會對任何突然或新奇的刺激作出反應。"},{"en":"A sudden or novel stimulus is something unexpected or new that attracts attention.","zh":"sudden or novel stimulus 指意外或新的、能吸引注意的事物。"},{"en":"A flashing light or unfamiliar sound can be a sudden or novel stimulus.","zh":"閃光或陌生聲音可以是突然或新奇的刺激。"},{"en":"Such a stimulus can make people stop what they are doing and look toward it.","zh":"這類刺激可以令人停止正在做的事並望向它。"},{"en":"The phrase explains why new movement on a screen pulls the eyes.","zh":"這個短語解釋為何螢幕上的新動作會拉住視線。"}],"source":"134 - TV Addiction.pdf","sourcePage":9},{"front":"evolutionary heritage","meaning":"進化遺產","examples":[{"en":"The orienting response is part of our evolutionary heritage.","zh":"定向反應是我們進化遺產的一部分。"},{"en":"Evolutionary heritage means traits or reactions inherited from human development over a long history.","zh":"evolutionary heritage 指人類長期發展中承繼下來的特徵或反應。"},{"en":"Fear of sudden movement may be part of our evolutionary heritage because it helped ancestors survive.","zh":"對突然動作的害怕可能是進化遺產的一部分，因為它幫助祖先生存。"},{"en":"Evolutionary heritage can influence modern behaviour even in safe environments.","zh":"進化遺產即使在安全環境中也可以影響現代行為。"},{"en":"The phrase connects present reactions with ancient survival needs.","zh":"這個短語把現在反應與古代生存需要連起來。"}],"source":"134 - TV Addiction.pdf","sourcePage":10},{"front":"built-in sensitivity to","meaning":"對……與生俱來的敏感性","examples":[{"en":"Humans have a built-in sensitivity to movement and threats.","zh":"人類對動作和威脅有與生俱來的敏感性。"},{"en":"Built-in sensitivity to something means a natural ability to notice or react to it.","zh":"built-in sensitivity to something 指自然地注意或回應某事的能力。"},{"en":"Babies may have a built-in sensitivity to human voices.","zh":"嬰兒可能對人聲有與生俱來的敏感性。"},{"en":"A built-in sensitivity to movement helps people notice danger quickly.","zh":"對動作與生俱來的敏感性幫助人們快速注意危險。"},{"en":"The phrase suggests the reaction is natural, not learned only from school.","zh":"這個短語暗示反應是自然的，而不只是從學校學來。"}],"source":"134 - TV Addiction.pdf","sourcePage":10},{"front":"potential predatory threats","meaning":"潛在捕食者威脅","examples":[{"en":"The response helped humans notice potential predatory threats.","zh":"這種反應幫助人類注意潛在捕食者威脅。"},{"en":"Potential predatory threats are possible dangers from animals or attackers that may hunt or harm someone.","zh":"potential predatory threats 指可能來自會捕獵或傷害人的動物或攻擊者的危險。"},{"en":"A sudden movement in tall grass could once signal a potential predatory threat.","zh":"高草中的突然動作曾經可能表示潛在捕食者威脅。"},{"en":"Noticing potential predatory threats quickly helped early humans survive.","zh":"快速注意潛在捕食者威脅幫助早期人類生存。"},{"en":"The phrase refers to possible danger, not certain attack.","zh":"這個短語指可能危險，而不是肯定攻擊。"}],"source":"134 - TV Addiction.pdf","sourcePage":10},{"front":"formal features of television","meaning":"電視的形式特徵","examples":[{"en":"Researchers studied whether formal features of television activate attention.","zh":"研究人員研究電視的形式特徵是否啟動注意力。"},{"en":"Formal features of television are the technical features of how TV is made, such as cuts, zooms, and camera movement.","zh":"formal features of television 指電視製作方式的技術特徵，例如切鏡、變焦和鏡頭移動。"},{"en":"A fast camera zoom is one formal feature that can pull viewers’ eyes to the screen.","zh":"快速變焦是一種可以把觀眾視線拉向螢幕的形式特徵。"},{"en":"These features can affect attention even when the programme content is unimportant.","zh":"即使節目內容不重要，這些特徵也可以影響注意力。"},{"en":"The phrase focuses on television form, not story or message.","zh":"這個短語重點是電視形式，而不是故事或訊息。"}],"source":"134 - TV Addiction.pdf","sourcePage":10},{"front":"cuts, edits, zooms and pans","meaning":"切鏡、剪接、變焦和平移鏡頭","examples":[{"en":"Cuts, edits, zooms and pans may activate the orienting response.","zh":"切鏡、剪接、變焦和平移鏡頭可能啟動定向反應。"},{"en":"Cuts, edits, zooms and pans are screen techniques that change what viewers see.","zh":"cuts, edits, zooms and pans 是改變觀眾所見畫面的螢幕技巧。"},{"en":"A news report may use cuts and zooms to move quickly between speaker and scene.","zh":"新聞報道可能使用切鏡和變焦，在講者與場景之間快速轉換。"},{"en":"These techniques can keep attention because the screen keeps changing.","zh":"這些技巧可以保持注意力，因為螢幕不斷變化。"},{"en":"The phrase lists visual tools, not programme topics.","zh":"這個短語列出視覺工具，而不是節目主題。"}],"source":"134 - TV Addiction.pdf","sourcePage":10},{"front":"sudden noises","meaning":"突然的聲響","examples":[{"en":"Sudden noises can attract viewers’ attention.","zh":"突然的聲響可以吸引觀眾注意力。"},{"en":"Sudden noises are unexpected sounds that happen quickly and may startle people.","zh":"sudden noises 指突然出現、可能令人受驚的意外聲音。"},{"en":"A loud alarm is a sudden noise that makes everyone look up.","zh":"響亮警鐘是一種令所有人抬頭看的突然聲響。"},{"en":"Sudden noises in television can pull attention back even when viewers are tired.","zh":"電視中的突然聲響即使在觀眾疲倦時，也可以把注意力拉回來。"},{"en":"The phrase describes sound-based attention triggers.","zh":"這個短語描述以聲音觸發注意力的因素。"}],"source":"134 - TV Addiction.pdf","sourcePage":10},{"front":"activate the orienting response","meaning":"啟動定向反應","examples":[{"en":"Formal features can activate the orienting response.","zh":"形式特徵可以啟動定向反應。"},{"en":"To activate the orienting response means to trigger the body’s automatic attention to something new or sudden.","zh":"activate the orienting response 指觸發身體對新奇或突然事物的自動注意。"},{"en":"A flashing advertisement can activate the orienting response when people walk past.","zh":"人們走過時，閃動廣告可以啟動定向反應。"},{"en":"Once the orienting response is activated, viewers may look at the screen before choosing to do so.","zh":"一旦定向反應被啟動，觀眾可能在選擇之前已望向螢幕。"},{"en":"The phrase explains automatic attention, not deliberate interest.","zh":"這個短語解釋自動注意，而不是刻意興趣。"}],"source":"134 - TV Addiction.pdf","sourcePage":10},{"front":"thereby keeping attention on","meaning":"從而令注意力停留在……","examples":[{"en":"Television features activate the response, thereby keeping attention on the screen.","zh":"電視特徵啟動這種反應，從而令注意力停留在螢幕上。"},{"en":"Thereby keeping attention on means causing attention to remain on something as a result.","zh":"thereby keeping attention on 指因此令注意力持續停留在某物上。"},{"en":"A teacher may ask short questions, thereby keeping attention on the lesson.","zh":"老師可能提出簡短問題，從而令注意力停留在課堂上。"},{"en":"Frequent screen changes can pull the eyes back, thereby keeping attention on the programme.","zh":"頻繁畫面變化可以把視線拉回來，從而令注意力停留在節目上。"},{"en":"The phrase links a cause with the result of maintained attention.","zh":"這個短語把原因與維持注意力的結果連起來。"}],"source":"134 - TV Addiction.pdf","sourcePage":10},{"front":"brain waves","meaning":"腦電波","examples":[{"en":"Researchers watched how brain waves were affected by formal features.","zh":"研究人員觀察腦電波如何受形式特徵影響。"},{"en":"Brain waves are patterns of electrical activity in the brain.","zh":"brain waves 指大腦中的電活動模式。"},{"en":"Scientists can record brain waves while people sleep, watch television, or solve problems.","zh":"科學家可以在人們睡覺、看電視或解題時記錄腦電波。"},{"en":"Changes in brain waves can show how attention or relaxation changes.","zh":"腦電波變化可以顯示注意力或放鬆程度如何改變。"},{"en":"The phrase is scientific and refers to measurable brain activity.","zh":"這個短語較科學，指可量度的大腦活動。"}],"source":"134 - TV Addiction.pdf","sourcePage":10},{"front":"be affected by","meaning":"受到……影響","examples":[{"en":"Brain waves can be affected by television’s formal features.","zh":"腦電波可以受到電視形式特徵影響。"},{"en":"To be affected by something means to be changed or influenced by it.","zh":"be affected by something 指被某事改變或影響。"},{"en":"A student’s mood can be affected by sleep, noise, and exam pressure.","zh":"學生心情可以受到睡眠、噪音和考試壓力影響。"},{"en":"If attention is affected by screen movement, viewers may keep watching longer.","zh":"如果注意力受到螢幕動作影響，觀眾可能看得更久。"},{"en":"The phrase describes influence, not always harm.","zh":"這個短語描述影響，不一定是傷害。"}],"source":"134 - TV Addiction.pdf","sourcePage":10},{"front":"researchers concluded that","meaning":"研究人員總結指","examples":[{"en":"The researchers concluded that stylistic tricks trigger involuntary responses.","zh":"研究人員總結指，風格技巧會觸發非自願反應。"},{"en":"Researchers concluded that means researchers decided something after studying evidence.","zh":"researchers concluded that 指研究人員在研究證據後作出判斷。"},{"en":"Doctors concluded that sleep was affecting the patient’s concentration after several tests.","zh":"多項測試後，醫生總結指睡眠正在影響病人的專注力。"},{"en":"A conclusion becomes stronger when different pieces of evidence point to the same result.","zh":"當不同證據指向同一結果，結論會更強。"},{"en":"The phrase introduces a research-based judgment.","zh":"這個短語引入基於研究的判斷。"}],"source":"134 - TV Addiction.pdf","sourcePage":10},{"front":"stylistic tricks","meaning":"風格技巧","examples":[{"en":"Television uses stylistic tricks to attract attention.","zh":"電視使用風格技巧來吸引注意力。"},{"en":"Stylistic tricks are creative techniques used to make something more noticeable or exciting.","zh":"stylistic tricks 指用來令某物更顯眼或刺激的創意技巧。"},{"en":"A video may use fast music and sudden cuts as stylistic tricks.","zh":"影片可能使用快節奏音樂和突然切鏡作為風格技巧。"},{"en":"Stylistic tricks can hold attention, but they may not help people understand information deeply.","zh":"風格技巧可以維持注意力，但未必幫助人深入理解資訊。"},{"en":"The phrase can sound slightly critical if the techniques feel manipulative.","zh":"如果技巧感覺具操控性，這個短語可能帶輕微批評。"}],"source":"134 - TV Addiction.pdf","sourcePage":11},{"front":"indeed trigger","meaning":"確實觸發","examples":[{"en":"Stylistic tricks can indeed trigger involuntary responses.","zh":"風格技巧確實可以觸發非自願反應。"},{"en":"Indeed trigger means really or definitely cause something to start.","zh":"indeed trigger 指真的或確實引發某事開始。"},{"en":"A loud alarm can indeed trigger fear even when there is no real danger.","zh":"響亮警報即使沒有真正危險，也確實可以觸發恐懼。"},{"en":"If a screen change does indeed trigger attention, viewers may look before thinking.","zh":"如果螢幕變化確實觸發注意力，觀眾可能未經思考就望過去。"},{"en":"The phrase strengthens the claim that a cause is real.","zh":"這個短語加強某原因是真實的說法。"}],"source":"134 - TV Addiction.pdf","sourcePage":11},{"front":"involuntary responses","meaning":"非自願反應","examples":[{"en":"Television’s formal features can trigger involuntary responses.","zh":"電視的形式特徵可以觸發非自願反應。"},{"en":"Involuntary responses are reactions that happen automatically without deliberate control.","zh":"involuntary responses 指不經刻意控制而自動發生的反應。"},{"en":"Blinking when dust enters the eye is an involuntary response.","zh":"灰塵入眼時眨眼是一種非自願反應。"},{"en":"Involuntary responses can make people react before they consciously decide.","zh":"非自願反應可以令人在有意識決定前先作出反應。"},{"en":"The phrase contrasts automatic reaction with planned action.","zh":"這個短語把自動反應與有計劃行動作對比。"}],"source":"134 - TV Addiction.pdf","sourcePage":11},{"front":"derive their attentional value from","meaning":"從……取得吸引注意力的價值","examples":[{"en":"These features derive their attentional value from evolutionary mechanisms.","zh":"這些特徵從進化機制取得吸引注意力的價值。"},{"en":"To derive their attentional value from something means to get their power to attract attention from that source.","zh":"derive their attentional value from something 指從某來源取得吸引注意力的力量。"},{"en":"Bright warning signs derive their attentional value from strong colour and contrast.","zh":"鮮明警告標誌從強烈顏色和對比中取得吸引注意力的價值。"},{"en":"Television cuts may derive their attentional value from our sensitivity to sudden change.","zh":"電視切鏡可能從我們對突然變化的敏感性中取得吸引注意力的價值。"},{"en":"The phrase explains where attention-grabbing power comes from.","zh":"這個短語解釋吸引注意力的力量來自哪裡。"}],"source":"134 - TV Addiction.pdf","sourcePage":11},{"front":"attentional value","meaning":"吸引注意力的價值","examples":[{"en":"Movement on screen has attentional value.","zh":"螢幕上的動作具有吸引注意力的價值。"},{"en":"Attentional value is the ability of something to attract or hold attention.","zh":"attentional value 指某物吸引或保持注意力的能力。"},{"en":"A red emergency button has attentional value because people notice it quickly.","zh":"紅色緊急按鈕有吸引注意力的價值，因為人們很快注意到它。"},{"en":"Fast movement has attentional value because the eyes naturally follow change.","zh":"快速動作有吸引注意力的價值，因為眼睛自然會追隨變化。"},{"en":"The phrase describes attention-grabbing power.","zh":"這個短語描述吸引注意力的力量。"}],"source":"134 - TV Addiction.pdf","sourcePage":11},{"front":"evolutionary significance","meaning":"進化意義","examples":[{"en":"Detecting movement has evolutionary significance.","zh":"偵測動作具有進化意義。"},{"en":"Evolutionary significance means importance for survival or development across human history.","zh":"evolutionary significance 指在人類歷史中的生存或發展重要性。"},{"en":"Quick fear of sudden noise has evolutionary significance because it may help people avoid danger.","zh":"對突然聲音快速感到害怕具有進化意義，因為它可能幫助人避開危險。"},{"en":"A behaviour with evolutionary significance may still influence modern life in unusual ways.","zh":"具有進化意義的行為，仍可能以不尋常方式影響現代生活。"},{"en":"The phrase connects a present reaction with survival value in the past.","zh":"這個短語把現在反應與過去的生存價值連起來。"}],"source":"134 - TV Addiction.pdf","sourcePage":11},{"front":"detecting movement","meaning":"偵測動作","examples":[{"en":"Humans evolved a sensitivity to detecting movement.","zh":"人類進化出對偵測動作的敏感性。"},{"en":"Detecting movement means noticing that something is moving.","zh":"detecting movement 指注意到某物正在移動。"},{"en":"A driver must be good at detecting movement to notice pedestrians and cyclists.","zh":"司機必須善於偵測動作，才能注意行人和單車。"},{"en":"Detecting movement quickly can help people react before danger reaches them.","zh":"快速偵測動作可以幫助人在危險到達前作出反應。"},{"en":"The phrase focuses on noticing motion, not identifying every detail.","zh":"這個短語重點是注意動作，而不是辨認每個細節。"}],"source":"134 - TV Addiction.pdf","sourcePage":11},{"front":"form, not content","meaning":"形式而非內容","examples":[{"en":"The form, not content, of television is unique.","zh":"電視獨特之處在於形式而非內容。"},{"en":"Form, not content means the structure or presentation matters more than the message itself.","zh":"form, not content 指結構或呈現方式比訊息本身更重要。"},{"en":"A video may attract attention because of fast cuts, not content that is important.","zh":"一段影片可能因快速切鏡而吸引注意，而不是因內容重要。"},{"en":"If form, not content, keeps viewers watching, even boring material can feel hard to ignore.","zh":"如果形式而非內容令觀眾繼續觀看，即使沉悶材料也可能難以忽視。"},{"en":"The phrase creates a clear contrast between style and message.","zh":"這個短語在風格和訊息之間建立清楚對比。"}],"source":"134 - TV Addiction.pdf","sourcePage":11},{"front":"common viewer remarks","meaning":"觀眾常見說法","examples":[{"en":"The orienting response explains common viewer remarks.","zh":"定向反應解釋了觀眾常見說法。"},{"en":"Common viewer remarks are things viewers often say about their experience.","zh":"common viewer remarks 指觀眾經常說的關於自己經驗的話。"},{"en":"“I only meant to watch one episode” is a common viewer remark.","zh":"「我本來只想看一集」是一種觀眾常見說法。"},{"en":"Common viewer remarks can reveal patterns that researchers later study scientifically.","zh":"觀眾常見說法可以揭示研究人員後來以科學方式研究的模式。"},{"en":"The phrase refers to ordinary comments, not formal research results.","zh":"這個短語指普通評論，而不是正式研究結果。"}],"source":"134 - TV Addiction.pdf","sourcePage":11},{"front":"keep my eyes off it","meaning":"無法把視線從……移開","examples":[{"en":"Some viewers say they cannot keep their eyes off the television.","zh":"有些觀眾說他們無法把視線從電視移開。"},{"en":"To keep my eyes off something means to avoid looking at it.","zh":"keep my eyes off something 指避免看某物。"},{"en":"A bright moving advertisement may be so distracting that people cannot keep their eyes off it.","zh":"鮮明移動的廣告可能非常令人分心，令人無法把視線從它移開。"},{"en":"If someone cannot keep their eyes off a screen, the screen has strong visual pull.","zh":"如果某人無法把視線從螢幕移開，螢幕就有強烈視覺吸引力。"},{"en":"The phrase is often used with cannot to show irresistible attraction.","zh":"這個短語常與 cannot 連用，表示難以抗拒的吸引。"}],"source":"134 - TV Addiction.pdf","sourcePage":11},{"front":"I can’t help it","meaning":"我忍不住；我控制不了","examples":[{"en":"Some viewers say they do not want to watch but cannot help it.","zh":"有些觀眾說他們不想看，但控制不了。"},{"en":"I can’t help it means I cannot stop myself from doing or feeling something.","zh":"I can’t help it 指我無法阻止自己做或感受某事。"},{"en":"A student may say, “I can’t help it,” when he keeps laughing in a serious lesson.","zh":"學生在嚴肅課堂中不停笑時，可能說「我忍不住」。"},{"en":"People use this phrase when behaviour feels automatic or stronger than choice.","zh":"當行為感覺自動或強於選擇時，人們會使用這個短語。"},{"en":"The phrase can explain difficulty with self-control, but it should not excuse harmful behaviour.","zh":"這個短語可以解釋自控困難，但不應用來合理化有害行為。"}],"source":"134 - TV Addiction.pdf","sourcePage":11},{"front":"feel hypnotized","meaning":"感到被催眠","examples":[{"en":"Some viewers feel hypnotized when they watch television.","zh":"有些觀眾看電視時感到被催眠。"},{"en":"To feel hypnotized means to feel so absorbed that one watches almost without thinking.","zh":"feel hypnotized 指感到非常投入，以致幾乎不經思考地觀看。"},{"en":"A person may feel hypnotized by a screen full of fast-moving images.","zh":"一個人可能被滿是快速移動畫面的螢幕吸引得像被催眠。"},{"en":"Feeling hypnotized can make time pass unnoticed.","zh":"感到被催眠可以令人不知不覺中時間流逝。"},{"en":"The phrase is usually figurative, not always literal medical hypnosis.","zh":"這個短語通常是比喻用法，不一定是字面上的醫學催眠。"}],"source":"134 - TV Addiction.pdf","sourcePage":12},{"front":"pioneering work","meaning":"開創性研究","examples":[{"en":"Reeves and Thorson published pioneering work on television and attention.","zh":"Reeves 和 Thorson 發表了關於電視與注意力的開創性研究。"},{"en":"Pioneering work is early important research or activity that opens a new field.","zh":"pioneering work 指早期重要、開啟新領域的研究或工作。"},{"en":"A scientist’s pioneering work may help later researchers ask better questions.","zh":"科學家的開創性研究可能幫助後來研究人員提出更好的問題。"},{"en":"Pioneering work can be imperfect but still valuable because it starts new thinking.","zh":"開創性研究可以不完美，但仍有價值，因為它開啟新思考。"},{"en":"The phrase gives credit to original and influential work.","zh":"這個短語肯定原創且有影響力的工作。"}],"source":"134 - TV Addiction.pdf","sourcePage":12},{"front":"delve deeper","meaning":"更深入研究","examples":[{"en":"Later researchers delved deeper into television’s effects.","zh":"後來的研究人員更深入研究電視的影響。"},{"en":"To delve deeper means to study or examine something more carefully and in more detail.","zh":"delve deeper 指更仔細、更詳細地研究或檢視某事。"},{"en":"A teacher may delve deeper into an error to find the grammar problem behind it.","zh":"老師可能更深入研究一個錯誤，以找出背後的文法問題。"},{"en":"Researchers delve deeper when early findings raise new questions.","zh":"當早期發現帶來新問題，研究人員會更深入研究。"},{"en":"The phrase suggests going beyond surface explanation.","zh":"這個短語暗示超越表面解釋。"}],"source":"134 - TV Addiction.pdf","sourcePage":12},{"front":"heart rate decreases","meaning":"心率下降","examples":[{"en":"Heart rate decreases for several seconds after an orienting stimulus.","zh":"定向刺激後，心率會下降數秒。"},{"en":"Heart rate decreases means the heart beats more slowly.","zh":"heart rate decreases 指心臟跳動變慢。"},{"en":"A person’s heart rate may decrease during deep breathing or quiet rest.","zh":"一個人在深呼吸或安靜休息時，心率可能下降。"},{"en":"A short decrease in heart rate can show the body is paying attention to a new stimulus.","zh":"心率短暫下降可以顯示身體正在注意新刺激。"},{"en":"The phrase describes a measurable physical change.","zh":"這個短語描述可量度的身體變化。"}],"source":"134 - TV Addiction.pdf","sourcePage":12},{"front":"orienting stimulus","meaning":"定向刺激","examples":[{"en":"An orienting stimulus can cause a short decrease in heart rate.","zh":"定向刺激可以造成心率短暫下降。"},{"en":"An orienting stimulus is something sudden or new that makes the body turn attention toward it.","zh":"orienting stimulus 指突然或新奇、令身體把注意力轉向它的事物。"},{"en":"A loud knock on the door can be an orienting stimulus.","zh":"門上突然一聲大力敲擊可以是定向刺激。"},{"en":"An orienting stimulus can interrupt another activity because the body reacts automatically.","zh":"定向刺激可以打斷另一活動，因為身體會自動反應。"},{"en":"The phrase is scientific and linked to attention.","zh":"這個短語較科學，與注意力有關。"}],"source":"134 - TV Addiction.pdf","sourcePage":12},{"front":"action sequences","meaning":"動作場面","examples":[{"en":"Action sequences often use rapid formal features.","zh":"動作場面常使用快速形式特徵。"},{"en":"Action sequences are parts of films or shows filled with movement, fighting, chasing, or excitement.","zh":"action sequences 指電影或節目中充滿動作、打鬥、追逐或刺激的部分。"},{"en":"A car chase in a movie is an action sequence.","zh":"電影中的汽車追逐是一個動作場面。"},{"en":"Fast cuts in action sequences can keep viewers alert and excited.","zh":"動作場面中的快速切鏡可以令觀眾保持警覺和興奮。"},{"en":"The phrase refers to energetic scenes, not quiet dialogue.","zh":"這個短語指充滿能量的場景，而不是安靜對白。"}],"source":"134 - TV Addiction.pdf","sourcePage":12},{"front":"music videos","meaning":"音樂錄像","examples":[{"en":"Music videos frequently use quick cuts and edits.","zh":"音樂錄像經常使用快速切鏡和剪接。"},{"en":"Music videos are short films or clips made to accompany songs.","zh":"music videos 指配合歌曲製作的短片或片段。"},{"en":"A music video may show the singer, dancers, city streets, and symbolic images.","zh":"音樂錄像可能展示歌手、舞者、城市街道和象徵性影像。"},{"en":"Quick editing in music videos can match the rhythm of a song and hold attention.","zh":"音樂錄像中的快速剪接可以配合歌曲節奏並保持注意力。"},{"en":"The phrase refers to visual promotion or artistic presentation of music.","zh":"這個短語指音樂的視覺宣傳或藝術呈現。"}],"source":"134 - TV Addiction.pdf","sourcePage":12},{"front":"come at a rate of","meaning":"以……的頻率出現","examples":[{"en":"Formal features may come at a rate of one per second.","zh":"形式特徵可能以每秒一次的頻率出現。"},{"en":"To come at a rate of means to happen with a particular frequency.","zh":"come at a rate of 指以某個頻率發生。"},{"en":"Emails may come at a rate of ten per hour during a busy morning.","zh":"在繁忙早上，電郵可能以每小時十封的頻率出現。"},{"en":"If cuts come at a very fast rate, the brain may struggle to process them.","zh":"如果切鏡以很快頻率出現，大腦可能難以處理。"},{"en":"The phrase describes how often something happens.","zh":"這個短語描述某事發生得有多頻密。"}],"source":"134 - TV Addiction.pdf","sourcePage":12},{"front":"one per second","meaning":"每秒一次","examples":[{"en":"Some formal features appear at a rate of one per second.","zh":"一些形式特徵以每秒一次的頻率出現。"},{"en":"One per second means one thing happens every second.","zh":"one per second 指每一秒發生一次。"},{"en":"A flashing light that blinks one per second changes once each second.","zh":"每秒閃一次的燈，每一秒改變一次。"},{"en":"When edits happen one per second, the screen changes very quickly.","zh":"當剪接每秒一次發生，螢幕會非常快速地變化。"},{"en":"The phrase gives a precise frequency.","zh":"這個短語提供精確頻率。"}],"source":"134 - TV Addiction.pdf","sourcePage":12},{"front":"continuously activate","meaning":"持續啟動","examples":[{"en":"Rapid features continuously activate the orienting response.","zh":"快速特徵持續啟動定向反應。"},{"en":"To continuously activate something means to keep triggering it again and again.","zh":"continuously activate something 指不斷重複觸發某事。"},{"en":"Phone notifications can continuously activate attention during homework.","zh":"手機通知可以在做功課期間持續啟動注意力。"},{"en":"If a screen continuously activates the orienting response, viewers may find it hard to relax.","zh":"如果螢幕持續啟動定向反應，觀眾可能難以放鬆。"},{"en":"The phrase describes repeated stimulation without much pause.","zh":"這個短語描述幾乎沒有停頓的重複刺激。"}],"source":"134 - TV Addiction.pdf","sourcePage":12},{"front":"investigate whether","meaning":"調查是否","examples":[{"en":"Researchers investigated whether formal features affect memory.","zh":"研究人員調查形式特徵是否影響記憶。"},{"en":"To investigate whether something happens means to study carefully if it is true.","zh":"investigate whether something happens 指仔細研究某事是否屬實。"},{"en":"Doctors may investigate whether a new medicine reduces pain.","zh":"醫生可能調查新藥是否減輕痛楚。"},{"en":"Investigating whether a claim is true requires evidence, not only opinion.","zh":"調查某個聲稱是否真實需要證據，而不只是意見。"},{"en":"The phrase introduces a research question.","zh":"這個短語引入研究問題。"}],"source":"134 - TV Addiction.pdf","sourcePage":12},{"front":"affect people’s memory of","meaning":"影響人們對……的記憶","examples":[{"en":"Formal features may affect people’s memory of what they have seen.","zh":"形式特徵可能影響人們對所見內容的記憶。"},{"en":"To affect people’s memory of something means to change how well they remember it.","zh":"affect people’s memory of something 指改變人們記住某事的程度。"},{"en":"A clear diagram can affect students’ memory of a difficult science process.","zh":"清晰圖表可以影響學生對困難科學過程的記憶。"},{"en":"Too many fast images may affect people’s memory of details by overloading attention.","zh":"太多快速影像可能透過令注意力負荷過重而影響人們對細節的記憶。"},{"en":"The phrase links presentation style with later recall.","zh":"這個短語把呈現方式與後來回憶連起來。"}],"source":"134 - TV Addiction.pdf","sourcePage":13},{"front":"fill out a score sheet","meaning":"填寫評分表","examples":[{"en":"Participants watched a program and then filled out a score sheet.","zh":"參加者觀看節目後填寫評分表。"},{"en":"To fill out a score sheet means to write ratings, answers, or scores on a form.","zh":"fill out a score sheet 指在表格上寫下評分、答案或分數。"},{"en":"After a speaking test, examiners fill out a score sheet for each candidate.","zh":"口語考試後，考官會為每名考生填寫評分表。"},{"en":"Filling out a score sheet helps researchers collect responses in an organised way.","zh":"填寫評分表幫助研究人員有組織地收集反應。"},{"en":"The phrase refers to recording judgments, not writing a long report.","zh":"這個短語指記錄判斷，而不是寫長報告。"}],"source":"134 - TV Addiction.pdf","sourcePage":13},{"front":"increase the frequency of","meaning":"增加……的頻率","examples":[{"en":"Increasing the frequency of edits improved recognition.","zh":"增加剪接的頻率改善了辨認能力。"},{"en":"To increase the frequency of something means to make it happen more often.","zh":"increase the frequency of something 指令某事更頻繁發生。"},{"en":"A teacher may increase the frequency of short quizzes to encourage regular revision.","zh":"老師可能增加小測頻率，以鼓勵定期溫習。"},{"en":"Increasing the frequency of breaks can reduce tiredness during long study sessions.","zh":"增加休息頻率可以減少長時間學習時的疲倦。"},{"en":"The phrase focuses on how often something occurs.","zh":"這個短語重點是某事發生得有多頻密。"}],"source":"134 - TV Addiction.pdf","sourcePage":13},{"front":"be defined here as","meaning":"在此被定義為","examples":[{"en":"An edit is defined here as a change in camera angle.","zh":"剪接在此被定義為攝影機角度的改變。"},{"en":"Be defined here as means the writer gives a specific meaning for this context.","zh":"be defined here as 指作者在此語境中給出特定意思。"},{"en":"In this lesson, fluency is defined here as speaking smoothly, not speaking perfectly.","zh":"在這堂課中，fluency 在此被定義為流暢說話，而不是完美說話。"},{"en":"Defining a term clearly helps readers avoid misunderstanding.","zh":"清楚定義術語有助讀者避免誤解。"},{"en":"The phrase signals a local definition, not necessarily the only possible meaning.","zh":"這個短語表示語境中的定義，而不一定是唯一可能意思。"}],"source":"134 - TV Addiction.pdf","sourcePage":13},{"front":"camera angle","meaning":"攝影機角度","examples":[{"en":"An edit changes from one camera angle to another.","zh":"剪接從一個攝影機角度轉到另一個。"},{"en":"A camera angle is the position or direction from which a camera films something.","zh":"camera angle 指攝影機拍攝某物的位置或方向。"},{"en":"A low camera angle can make a character look powerful.","zh":"低攝影機角度可以令角色看起來有力量。"},{"en":"Changing camera angle can guide viewers to notice a face, object, or action.","zh":"改變攝影機角度可以引導觀眾注意面孔、物件或動作。"},{"en":"The phrase refers to how a scene is visually shown.","zh":"這個短語指場景如何以視覺方式呈現。"}],"source":"134 - TV Addiction.pdf","sourcePage":13},{"front":"visual scene","meaning":"視覺場景","examples":[{"en":"An edit occurs within the same visual scene.","zh":"剪接在同一視覺場景內發生。"},{"en":"A visual scene is what viewers can see in one setting or moment.","zh":"visual scene 指觀眾在一個場景或時刻中能看見的東西。"},{"en":"A kitchen, a classroom, or a street corner can be a visual scene in a film.","zh":"廚房、課室或街角都可以是電影中的視覺場景。"},{"en":"Changing details within a visual scene can direct attention without changing the whole location.","zh":"在視覺場景內改變細節，可以在不改變整個地點下引導注意力。"},{"en":"The phrase focuses on what is seen, not what is heard.","zh":"這個短語重點是所見內容，而不是所聽內容。"}],"source":"134 - TV Addiction.pdf","sourcePage":13},{"front":"memory recognition","meaning":"記憶辨認能力","examples":[{"en":"Increasing edits improved memory recognition.","zh":"增加剪接改善了記憶辨認能力。"},{"en":"Memory recognition is the ability to recognise something seen or learned before.","zh":"memory recognition 指辨認曾見過或學過事物的能力。"},{"en":"A student shows memory recognition when she sees a word and remembers its meaning.","zh":"學生看到一個字並記得其意思時，就是展示記憶辨認能力。"},{"en":"Clear cues can improve memory recognition by making information easier to identify later.","zh":"清晰提示可以令資訊之後較容易辨認，從而改善記憶辨認能力。"},{"en":"The phrase is different from freely recalling something without help.","zh":"這個短語不同於完全沒有提示下自由回憶。"}],"source":"134 - TV Addiction.pdf","sourcePage":13},{"front":"presumably because","meaning":"大概是因為","examples":[{"en":"Memory improved presumably because attention was focused on the screen.","zh":"記憶改善大概是因為注意力集中在螢幕上。"},{"en":"Presumably because means probably because, based on reasonable evidence or inference.","zh":"presumably because 指根據合理證據或推論，大概因為某原因。"},{"en":"The student was tired, presumably because he slept very late.","zh":"學生很疲倦，大概是因為他很晚才睡。"},{"en":"Researchers use presumably because when they think a cause is likely but not fully proven.","zh":"當研究人員認為某原因很可能但未完全證明時，會使用 presumably because。"},{"en":"The phrase signals a careful explanation rather than certainty.","zh":"這個短語表示謹慎解釋，而不是確定。"}],"source":"134 - TV Addiction.pdf","sourcePage":13},{"front":"focus attention on","meaning":"把注意力集中於……","examples":[{"en":"Edits can focus attention on the screen.","zh":"剪接可以把注意力集中於螢幕。"},{"en":"To focus attention on something means to direct mental effort or sight toward it.","zh":"focus attention on something 指把心理努力或視線引向某物。"},{"en":"A teacher may use a picture to focus students’ attention on the main idea.","zh":"老師可能使用圖片把學生注意力集中於主旨。"},{"en":"Sudden movement can focus attention on a screen even during a conversation.","zh":"突然動作即使在交談期間也可以把注意力集中於螢幕。"},{"en":"The phrase describes directing attention to one place or issue.","zh":"這個短語描述把注意力引向一個地方或議題。"}],"source":"134 - TV Addiction.pdf","sourcePage":13},{"front":"have a similar effect","meaning":"有類似效果","examples":[{"en":"Cuts had a similar effect on memory.","zh":"切鏡對記憶有類似效果。"},{"en":"To have a similar effect means to produce almost the same result.","zh":"have a similar effect 指產生幾乎相同的結果。"},{"en":"Walking and cycling can have a similar effect on improving daily fitness.","zh":"步行和踩單車可以對改善日常體能有類似效果。"},{"en":"If two teaching methods have a similar effect, teachers may choose the simpler one.","zh":"如果兩種教學方法有類似效果，老師可能選較簡單的一種。"},{"en":"The phrase compares results, not appearance.","zh":"這個短語比較結果，而不是外表。"}],"source":"134 - TV Addiction.pdf","sourcePage":13},{"front":"up to a point","meaning":"到某個限度為止","examples":[{"en":"Cuts improved recognition only up to a point.","zh":"切鏡只到某個限度為止能改善辨認能力。"},{"en":"Up to a point means only until a certain limit, after which the effect changes or stops.","zh":"up to a point 指只到某一限度，之後效果會改變或停止。"},{"en":"Practice improves performance up to a point, but rest is also needed.","zh":"練習到某個限度為止能改善表現，但休息也需要。"},{"en":"More examples help students up to a point; too many can confuse them.","zh":"更多例子到某個限度為止會幫助學生；太多反而會令人混亂。"},{"en":"The phrase warns that more is not always better.","zh":"這個短語提醒我們，更多不一定更好。"}],"source":"134 - TV Addiction.pdf","sourcePage":13},{"front":"exceed 10 in two minutes","meaning":"兩分鐘內超過10次","examples":[{"en":"Recognition dropped when cuts exceeded 10 in two minutes.","zh":"當切鏡在兩分鐘內超過10次，辨認能力下降。"},{"en":"To exceed 10 in two minutes means to go beyond ten times within a two-minute period.","zh":"exceed 10 in two minutes 指在兩分鐘內超過十次。"},{"en":"If interruptions exceed 10 in two minutes, students may lose track of the lesson.","zh":"如果干擾在兩分鐘內超過10次，學生可能跟不上課堂。"},{"en":"When edits exceed 10 in two minutes, viewers may become overloaded.","zh":"當剪接在兩分鐘內超過10次，觀眾可能負荷過重。"},{"en":"The phrase gives a numerical limit.","zh":"這個短語提供數字限度。"}],"source":"134 - TV Addiction.pdf","sourcePage":14},{"front":"drop off sharply","meaning":"急劇下降","examples":[{"en":"Recognition dropped off sharply when there were too many cuts.","zh":"當切鏡太多，辨認能力急劇下降。"},{"en":"To drop off sharply means to decrease suddenly and greatly.","zh":"drop off sharply 指突然並大幅下降。"},{"en":"Attendance may drop off sharply after a club stops offering useful activities.","zh":"如果社團停止提供有用活動，出席率可能急劇下降。"},{"en":"Memory can drop off sharply when information arrives too quickly.","zh":"當資訊來得太快，記憶表現可能急劇下降。"},{"en":"The phrase describes a steep fall, not a small decline.","zh":"這個短語描述陡降，而不是小幅下降。"}],"source":"134 - TV Addiction.pdf","sourcePage":14},{"front":"educational television","meaning":"教育電視","examples":[{"en":"Educational television can use formal features to support learning.","zh":"教育電視可以使用形式特徵來支持學習。"},{"en":"Educational television means TV programmes designed to teach knowledge or skills.","zh":"educational television 指旨在教授知識或技能的電視節目。"},{"en":"A children’s science programme is a form of educational television.","zh":"兒童科學節目是一種教育電視。"},{"en":"Educational television works better when attention-grabbing features support the lesson.","zh":"當吸引注意力的特徵支持課堂內容時，教育電視效果會更好。"},{"en":"The phrase describes television with a learning purpose.","zh":"這個短語描述以學習為目的的電視。"}],"source":"134 - TV Addiction.pdf","sourcePage":14},{"front":"help learning","meaning":"有助學習","examples":[{"en":"Formal features can help learning.","zh":"形式特徵可以有助學習。"},{"en":"To help learning means to make understanding, remembering, or practising easier.","zh":"help learning 指令理解、記憶或練習更容易。"},{"en":"Pictures can help learning when students struggle with abstract ideas.","zh":"當學生難以理解抽象概念，圖片可以有助學習。"},{"en":"Screen techniques help learning only if they guide attention toward useful information.","zh":"螢幕技巧只有在把注意力引向有用資訊時，才有助學習。"},{"en":"The phrase focuses on educational benefit.","zh":"這個短語重點是教育好處。"}],"source":"134 - TV Addiction.pdf","sourcePage":14},{"front":"rate of cuts and edits","meaning":"切鏡和剪接的頻率","examples":[{"en":"The rate of cuts and edits can eventually overload the brain.","zh":"切鏡和剪接的頻率最終可能令大腦負荷過重。"},{"en":"The rate of cuts and edits means how often the screen changes through cutting or editing.","zh":"rate of cuts and edits 指螢幕透過切鏡或剪接改變的頻密程度。"},{"en":"A slow documentary may have a low rate of cuts and edits.","zh":"慢節奏紀錄片可能有較低的切鏡和剪接頻率。"},{"en":"A very high rate of cuts and edits can make viewers tired or confused.","zh":"很高的切鏡和剪接頻率可以令觀眾疲倦或混亂。"},{"en":"The phrase measures editing frequency.","zh":"這個短語量度剪接頻率。"}],"source":"134 - TV Addiction.pdf","sourcePage":14},{"front":"overload the brain","meaning":"令大腦負荷過重","examples":[{"en":"Too many cuts and edits overload the brain.","zh":"太多切鏡和剪接令大腦負荷過重。"},{"en":"To overload the brain means to give it more information than it can process comfortably.","zh":"overload the brain 指給大腦超過它能舒適處理的資訊量。"},{"en":"Studying five new grammar points at once may overload the brain.","zh":"一次學五個新文法點可能令大腦負荷過重。"},{"en":"When the brain is overloaded, memory and understanding can become weaker.","zh":"當大腦負荷過重，記憶和理解可能變弱。"},{"en":"The phrase describes mental strain from too much input.","zh":"這個短語描述過多輸入造成的心理負荷。"}],"source":"134 - TV Addiction.pdf","sourcePage":14},{"front":"rapid intercutting","meaning":"快速交叉剪接","examples":[{"en":"Music videos and commercials often use rapid intercutting.","zh":"音樂錄像和廣告常使用快速交叉剪接。"},{"en":"Rapid intercutting is fast switching between different shots or scenes.","zh":"rapid intercutting 指在不同鏡頭或場景之間快速切換。"},{"en":"An advertisement may use rapid intercutting between a product, a smiling family, and city lights.","zh":"廣告可能在產品、微笑家庭和城市燈光之間使用快速交叉剪接。"},{"en":"Rapid intercutting can hold attention but may make details harder to remember.","zh":"快速交叉剪接可以保持注意力，但可能令細節較難記住。"},{"en":"The phrase describes a fast editing style.","zh":"這個短語描述快速剪接風格。"}],"source":"134 - TV Addiction.pdf","sourcePage":14},{"front":"unrelated scenes","meaning":"不相關的場景","examples":[{"en":"Rapid intercutting often shows unrelated scenes.","zh":"快速交叉剪接常展示不相關的場景。"},{"en":"Unrelated scenes are scenes that do not clearly connect in story, place, or meaning.","zh":"unrelated scenes 指在故事、地點或意思上沒有清楚連繫的場景。"},{"en":"A video may jump from a beach to a classroom to a concert, showing unrelated scenes.","zh":"影片可能從海灘跳到課室再跳到演唱會，展示不相關的場景。"},{"en":"Unrelated scenes can create energy, but they may confuse viewers about the message.","zh":"不相關的場景可以創造活力，但可能令觀眾對訊息感到混亂。"},{"en":"The phrase contrasts with scenes that follow a clear sequence.","zh":"這個短語與跟隨清楚次序的場景形成對比。"}],"source":"134 - TV Addiction.pdf","sourcePage":14},{"front":"be designed to hold attention","meaning":"旨在吸引注意力","examples":[{"en":"Commercials are designed to hold attention.","zh":"廣告旨在吸引注意力。"},{"en":"To be designed to hold attention means to be created to keep people watching or listening.","zh":"be designed to hold attention 指被創造出來以保持人們觀看或聆聽。"},{"en":"A lesson slide with clear images may be designed to hold attention.","zh":"有清晰圖片的課堂投影片可能旨在吸引注意力。"},{"en":"Advertisements are designed to hold attention so viewers notice the brand before looking away.","zh":"廣告旨在吸引注意力，好讓觀眾在移開視線前注意品牌。"},{"en":"The phrase explains purpose, not accidental effect.","zh":"這個短語解釋目的，而不是偶然效果。"}],"source":"134 - TV Addiction.pdf","sourcePage":14},{"front":"convey information","meaning":"傳達資料","examples":[{"en":"Some videos aim more to hold attention than to convey information.","zh":"有些影片更重視吸引注意力，多於傳達資料。"},{"en":"To convey information means to communicate facts, ideas, or messages clearly.","zh":"convey information 指清楚傳達事實、想法或訊息。"},{"en":"A good notice should convey information about time, place, and rules.","zh":"好告示應傳達時間、地點和規則等資料。"},{"en":"If a video is too flashy, it may fail to convey information that viewers remember.","zh":"如果影片太花巧，它可能無法傳達觀眾會記住的資料。"},{"en":"The phrase focuses on communication of meaning.","zh":"這個短語重點是意思的傳達。"}],"source":"134 - TV Addiction.pdf","sourcePage":14},{"front":"product or band","meaning":"產品或樂隊","examples":[{"en":"People may remember the name of the product or band.","zh":"人們可能記得產品或樂隊的名稱。"},{"en":"Product or band means the item being advertised or the music group being promoted.","zh":"product or band 指被宣傳的商品或被推廣的音樂組合。"},{"en":"A commercial may make viewers remember the product but forget the story.","zh":"廣告可能令人記得產品，但忘記故事。"},{"en":"A music video may make fans remember the band name through repeated images and sound.","zh":"音樂錄像可能透過重複影像和聲音令粉絲記得樂隊名稱。"},{"en":"The phrase points to what advertisers or promoters want remembered.","zh":"這個短語指出廣告商或宣傳者希望人們記住的東西。"}],"source":"134 - TV Addiction.pdf","sourcePage":14},{"front":"details of the ad","meaning":"廣告細節","examples":[{"en":"The details of the ad may be quickly forgotten.","zh":"廣告細節可能很快被忘記。"},{"en":"Details of the ad are the specific parts of an advertisement, such as scenes, words, or claims.","zh":"details of the ad 指廣告中的具體部分，例如場景、字句或聲稱。"},{"en":"Viewers may remember a brand but forget the details of the ad.","zh":"觀眾可能記得品牌，但忘記廣告細節。"},{"en":"When an ad changes scenes too quickly, details may not stay in memory.","zh":"當廣告場景轉換太快，細節可能留不在記憶中。"},{"en":"The phrase focuses on small pieces of information, not the general impression.","zh":"這個短語重點是小資訊，而不是整體印象。"}],"source":"134 - TV Addiction.pdf","sourcePage":15},{"front":"float in one ear and out the other","meaning":"左耳入右耳出","examples":[{"en":"The details of the ad float in one ear and out the other.","zh":"廣告細節左耳入右耳出。"},{"en":"To float in one ear and out the other means to be heard but quickly forgotten.","zh":"float in one ear and out the other 指聽到但很快忘記。"},{"en":"A student may hear exam advice but let it float in one ear and out the other.","zh":"學生可能聽到考試建議，卻讓它左耳入右耳出。"},{"en":"Information floats in one ear and out the other when attention is weak.","zh":"當注意力薄弱，資訊就會左耳入右耳出。"},{"en":"The phrase is informal and describes poor retention.","zh":"這個短語較口語，描述記不住內容。"}],"source":"134 - TV Addiction.pdf","sourcePage":15},{"front":"be overworked","meaning":"被過度使用","examples":[{"en":"The orienting response is overworked by rapid visual changes.","zh":"定向反應被快速視覺變化過度使用。"},{"en":"To be overworked means to be used too much until it becomes tired or less effective.","zh":"be overworked 指被過度使用，以致疲累或效果下降。"},{"en":"A person can feel overworked after too many tasks and too little rest.","zh":"一個人在任務太多、休息太少後可能感到過勞。"},{"en":"If the brain’s attention system is overworked, viewers may feel tired but still keep watching.","zh":"如果大腦注意力系統被過度使用，觀眾可能感到疲倦但仍繼續觀看。"},{"en":"The phrase suggests excessive demand on a person or system.","zh":"這個短語暗示對人或系統要求過多。"}],"source":"134 - TV Addiction.pdf","sourcePage":15},{"front":"attend to the screen","meaning":"留意螢幕","examples":[{"en":"Viewers still attend to the screen despite feeling tired.","zh":"觀眾即使感到疲倦，仍然留意螢幕。"},{"en":"To attend to the screen means to pay attention to what is shown on it.","zh":"attend to the screen 指注意螢幕上顯示的內容。"},{"en":"Children may attend to the screen when bright colours and sounds appear.","zh":"當鮮明顏色和聲音出現，孩子可能留意螢幕。"},{"en":"If viewers attend to the screen automatically, they may ignore people beside them.","zh":"如果觀眾自動留意螢幕，他們可能忽視身邊的人。"},{"en":"The phrase describes directing attention toward the screen.","zh":"這個短語描述把注意力引向螢幕。"}],"source":"134 - TV Addiction.pdf","sourcePage":15},{"front":"tired and worn out","meaning":"疲倦不堪","examples":[{"en":"Viewers may feel tired and worn out after watching rapid images.","zh":"觀眾觀看快速影像後可能感到疲倦不堪。"},{"en":"Tired and worn out means very tired, drained, or lacking energy.","zh":"tired and worn out 指非常疲倦、耗盡或沒有能量。"},{"en":"After a long day of meetings, a worker may feel tired and worn out.","zh":"經過一整天會議後，員工可能感到疲倦不堪。"},{"en":"Too much screen stimulation can leave viewers tired and worn out rather than refreshed.","zh":"過多螢幕刺激可以令觀眾疲倦不堪，而不是恢復精神。"},{"en":"The phrase is stronger than simply tired.","zh":"這個短語比 simply tired 更強。"}],"source":"134 - TV Addiction.pdf","sourcePage":15},{"front":"compensating psychological reward","meaning":"作為補償的心理回報","examples":[{"en":"Viewers may receive little compensating psychological reward.","zh":"觀眾可能得到很少作為補償的心理回報。"},{"en":"A compensating psychological reward is a mental benefit that makes effort or tiredness feel worthwhile.","zh":"compensating psychological reward 指令努力或疲倦感覺值得的心理好處。"},{"en":"Exercise may feel hard, but improved mood can be a compensating psychological reward.","zh":"運動可能辛苦，但心情改善可以是作為補償的心理回報。"},{"en":"If watching TV leaves people tired without reward, the experience may feel empty afterward.","zh":"如果看電視令人疲倦卻沒有回報，事後體驗可能感覺空洞。"},{"en":"The phrase describes emotional payback, not money.","zh":"這個短語描述情感回報，而不是金錢。"}],"source":"134 - TV Addiction.pdf","sourcePage":15},{"front":"ESM findings","meaning":"ESM 研究結果","examples":[{"en":"ESM findings show similar effects of television viewing.","zh":"ESM 研究結果顯示看電視有類似影響。"},{"en":"ESM findings are results from the Experience Sampling Method, which records people’s feelings during daily life.","zh":"ESM findings 指來自「經驗抽樣法」的結果，該方法記錄人們日常生活中的感受。"},{"en":"ESM findings may show whether people feel relaxed or tired while watching TV.","zh":"ESM 研究結果可能顯示人們看電視時感到放鬆還是疲倦。"},{"en":"Because ESM collects data in real time, it can reveal patterns that memory alone misses.","zh":"因為 ESM 即時收集數據，它可以揭示單靠記憶會錯過的模式。"},{"en":"The phrase refers to research results from a specific method.","zh":"這個短語指來自特定方法的研究結果。"}],"source":"134 - TV Addiction.pdf","sourcePage":15},{"front":"subtle memory","meaning":"微妙的記憶","examples":[{"en":"Sometimes the memory of the product is very subtle.","zh":"有時對產品的記憶非常微妙。"},{"en":"A subtle memory is a weak or indirect memory that affects feelings without being very clear.","zh":"subtle memory 指不太清楚、間接影響感覺的微弱記憶。"},{"en":"A shopper may have a subtle memory of a logo seen in an advertisement.","zh":"顧客可能對廣告中見過的標誌有微妙記憶。"},{"en":"Subtle memory can make a product feel familiar even when people cannot explain why.","zh":"微妙的記憶可以令產品感覺熟悉，即使人們不能解釋原因。"},{"en":"The phrase describes quiet influence rather than obvious recall.","zh":"這個短語描述安靜的影響，而不是明顯回憶。"}],"source":"134 - TV Addiction.pdf","sourcePage":15},{"front":"deliberately oblique","meaning":"刻意含蓄晦澀的","examples":[{"en":"Many ads today are deliberately oblique.","zh":"今天許多廣告都是刻意含蓄晦澀的。"},{"en":"Deliberately oblique means intentionally indirect, unclear, or not immediately obvious.","zh":"deliberately oblique 指有意地間接、不清楚或不立即明顯。"},{"en":"An ad may be deliberately oblique if it tells a strange story before showing the product.","zh":"如果廣告先講一個奇怪故事，然後才展示產品，它可能是刻意含蓄晦澀的。"},{"en":"Advertisers use oblique messages to make viewers curious and keep watching.","zh":"廣告商使用間接訊息令觀眾好奇並繼續觀看。"},{"en":"The phrase suggests indirectness is planned, not accidental.","zh":"這個短語暗示間接性是有計劃的，而不是意外。"}],"source":"134 - TV Addiction.pdf","sourcePage":15},{"front":"engaging story line","meaning":"吸引人的故事情節","examples":[{"en":"Some advertisements have an engaging story line.","zh":"有些廣告有吸引人的故事情節。"},{"en":"An engaging story line is a plot that keeps people interested.","zh":"engaging story line 指能保持人們興趣的情節。"},{"en":"A commercial about a lost dog returning home may have an engaging story line.","zh":"一個關於走失狗回家的廣告可能有吸引人的故事情節。"},{"en":"An engaging story line can hold attention even before viewers know what is being sold.","zh":"吸引人的故事情節可以在觀眾知道賣甚麼之前先抓住注意力。"},{"en":"The phrase focuses on story appeal, not product quality.","zh":"這個短語重點是故事吸引力，而不是產品質素。"}],"source":"134 - TV Addiction.pdf","sourcePage":15},{"front":"hard to tell","meaning":"難以判斷","examples":[{"en":"It is sometimes hard to tell what an ad is trying to sell.","zh":"有時難以判斷一個廣告試圖銷售甚麼。"},{"en":"Hard to tell means difficult to know, judge, or identify.","zh":"hard to tell 指難以知道、判斷或辨認。"},{"en":"It is hard to tell whether a student understands if she never asks questions.","zh":"如果學生從不提問，就難以判斷她是否明白。"},{"en":"If an advertisement is too indirect, it may be hard to tell what product is being promoted.","zh":"如果廣告太間接，可能難以判斷它正在推廣甚麼產品。"},{"en":"The phrase expresses uncertainty.","zh":"這個短語表達不確定。"}],"source":"134 - TV Addiction.pdf","sourcePage":15},{"front":"remember consciously","meaning":"有意識地記得","examples":[{"en":"You may not remember the product consciously afterward.","zh":"你之後可能不是有意識地記得該產品。"},{"en":"To remember consciously means to be clearly aware that you remember something.","zh":"remember consciously 指清楚意識到自己記得某事。"},{"en":"A person may not remember an ad consciously but still feel familiar with the brand.","zh":"一個人可能不是有意識地記得某個廣告，但仍對品牌感到熟悉。"},{"en":"Conscious memory is weaker when attention is captured by story or images instead of facts.","zh":"當注意力被故事或影像而不是事實吸引，有意識記憶會較弱。"},{"en":"The phrase contrasts clear recall with hidden or vague memory.","zh":"這個短語把清楚回憶與隱藏或模糊記憶作對比。"}],"source":"134 - TV Addiction.pdf","sourcePage":16},{"front":"gotten your attention","meaning":"吸引了你的注意","examples":[{"en":"Advertisers believe they have succeeded if they have gotten your attention.","zh":"廣告商相信，如果他們吸引了你的注意，就已經成功。"},{"en":"Gotten your attention means successfully made you notice or focus on something.","zh":"gotten your attention 指成功令你注意或集中於某事。"},{"en":"A loud sound in a video may have gotten your attention even if you disliked it.","zh":"影片中的巨大聲音即使你不喜歡，也可能已吸引了你的注意。"},{"en":"Once an ad has gotten your attention, the brand has a chance to stay in memory.","zh":"一旦廣告吸引了你的注意，品牌就有機會留在記憶中。"},{"en":"The phrase is American English; British English often uses got instead of gotten.","zh":"這個短語屬美式英語；英式英語常用 got 而不是 gotten。"}],"source":"134 - TV Addiction.pdf","sourcePage":16},{"front":"feel better or more comfortable with","meaning":"對……感覺較好或較舒服","examples":[{"en":"You may later feel better or more comfortable with a given product.","zh":"你之後可能對某一產品感覺較好或較舒服。"},{"en":"To feel better or more comfortable with something means to feel more positive or familiar toward it.","zh":"feel better or more comfortable with something 指對某物感到較正面或較熟悉。"},{"en":"A shopper may feel better about a brand after seeing it many times.","zh":"顧客多次見到某品牌後，可能對它感覺較好。"},{"en":"Familiarity can make people feel more comfortable with a product even without clear memory of the ad.","zh":"熟悉感可以令人對產品感覺較舒服，即使不清楚記得廣告。"},{"en":"The phrase describes emotional comfort, not proven product quality.","zh":"這個短語描述情感舒適，而不是產品質素已被證明。"}],"source":"134 - TV Addiction.pdf","sourcePage":16},{"front":"a given product","meaning":"某一產品","examples":[{"en":"A vague memory may make people feel comfortable with a given product.","zh":"模糊記憶可能令人對某一產品感到舒服。"},{"en":"A given product means a particular product being discussed.","zh":"given product 指正在討論的某個特定產品。"},{"en":"A survey may ask whether customers would buy a given product again.","zh":"問卷可能詢問顧客是否會再次購買某一產品。"},{"en":"If people recognise a given product, they may choose it over an unfamiliar one.","zh":"如果人們認得某一產品，他們可能選擇它而不是陌生產品。"},{"en":"The phrase is formal and means this specific product.","zh":"這個短語較正式，意思是這個特定產品。"}],"source":"134 - TV Addiction.pdf","sourcePage":16},{"front":"vague recollection","meaning":"模糊記憶","examples":[{"en":"Viewers may have a vague recollection of hearing about the product.","zh":"觀眾可能對曾聽說該產品有模糊記憶。"},{"en":"A vague recollection is an unclear or weak memory of something.","zh":"vague recollection 指對某事不清楚或微弱的記憶。"},{"en":"A student may have a vague recollection of a word but forget its exact meaning.","zh":"學生可能對某個字有模糊記憶，但忘記確切意思。"},{"en":"Vague recollection can still influence choices because familiar things feel safer.","zh":"模糊記憶仍可以影響選擇，因為熟悉事物感覺較安全。"},{"en":"The phrase describes partial memory, not full recall.","zh":"這個短語描述部分記憶，而不是完整回憶。"}],"source":"134 - TV Addiction.pdf","sourcePage":16},{"front":"having heard of","meaning":"曾聽說過","examples":[{"en":"You may feel familiar with a product because you remember having heard of it.","zh":"你可能因記得曾聽說過某產品，而對它感到熟悉。"},{"en":"Having heard of something means knowing its name or existence from before.","zh":"having heard of something 指以前知道某物的名稱或存在。"},{"en":"A student may choose a university because she remembers having heard of it.","zh":"學生可能因記得曾聽說過某大學而選擇它。"},{"en":"Having heard of a brand can make customers trust it more than a totally unknown one.","zh":"曾聽說過某品牌可以令顧客比對完全陌生品牌更信任它。"},{"en":"The phrase refers to basic familiarity, not deep knowledge.","zh":"這個短語指基本熟悉，而不是深入了解。"}],"source":"134 - TV Addiction.pdf","sourcePage":16},{"front":"agree with the claims of the writer","meaning":"與作者的主張一致","examples":[{"en":"Students decide whether the statements agree with the claims of the writer.","zh":"學生判斷陳述是否與作者的主張一致。"},{"en":"To agree with the claims of the writer means to match what the writer says or argues.","zh":"agree with the claims of the writer 指與作者所說或所主張的內容相符。"},{"en":"In reading tests, students must use the passage, not personal opinion, to check agreement.","zh":"在閱讀測驗中，學生必須使用篇章，而不是個人意見來判斷一致性。"},{"en":"A statement agrees with the writer’s claims only if the idea is clearly supported.","zh":"只有當想法有清楚支持，陳述才與作者主張一致。"},{"en":"The phrase is common in Yes, No, Not Given questions.","zh":"這個短語常見於 Yes, No, Not Given 題目。"}],"source":"134 - TV Addiction.pdf","sourcePage":16},{"front":"views of the writer","meaning":"作者觀點","examples":[{"en":"The answer depends on the views of the writer.","zh":"答案取決於作者觀點。"},{"en":"Views of the writer are the opinions, claims, or attitudes expressed by the author.","zh":"views of the writer 指作者表達的意見、主張或態度。"},{"en":"Students identify the writer’s views by looking at wording, contrast, and conclusion.","zh":"學生透過用字、對比和結論辨認作者觀點。"},{"en":"Confusing facts with the views of the writer can lead to wrong answers.","zh":"把事實與作者觀點混淆，可能導致錯誤答案。"},{"en":"The phrase focuses on author opinion, not general truth.","zh":"這個短語重點是作者意見，而不是一般真理。"}],"source":"134 - TV Addiction.pdf","sourcePage":16},{"front":"contradict the views of the writer","meaning":"與作者觀點相矛盾","examples":[{"en":"A NO answer means the statement contradicts the views of the writer.","zh":"NO 答案表示該陳述與作者觀點相矛盾。"},{"en":"To contradict the views of the writer means to say the opposite of the writer’s opinion.","zh":"contradict the views of the writer 指說出與作者意見相反的內容。"},{"en":"If the writer says TV can educate, a statement saying TV never educates contradicts the writer’s view.","zh":"如果作者說電視可以教育人，陳述說電視從不教育人就是與作者觀點相矛盾。"},{"en":"Students must find direct conflict before choosing NO.","zh":"學生必須找到直接衝突，才選 NO。"},{"en":"The phrase means disagreement with the author, not missing information.","zh":"這個短語表示與作者不同意，而不是資料缺失。"}],"source":"134 - TV Addiction.pdf","sourcePage":16},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"NOT GIVEN means it is impossible to say what the writer thinks.","zh":"NOT GIVEN 表示無法判斷作者怎樣想。"},{"en":"Impossible to say means there is not enough information to decide.","zh":"impossible to say 指資料不足，無法決定。"},{"en":"If a passage mentions screen time but not children’s exercise, it is impossible to say the writer’s view on exercise.","zh":"如果篇章提到螢幕時間但沒有提到兒童運動，就無法判斷作者對運動的看法。"},{"en":"In reading tests, impossible to say often leads to NOT GIVEN.","zh":"在閱讀測驗中，無法判斷通常導向 NOT GIVEN。"},{"en":"The phrase warns students not to guess beyond the text.","zh":"這個短語提醒學生不要超出文本猜測。"}],"source":"134 - TV Addiction.pdf","sourcePage":16},{"front":"more compelling than","meaning":"比……更有吸引力","examples":[{"en":"Researchers may find watching television more compelling than conversation.","zh":"研究人員可能發現看電視比交談更有吸引力。"},{"en":"More compelling than means more powerful, interesting, or difficult to resist than something else.","zh":"more compelling than 指比某事更有力量、更有趣或更難抗拒。"},{"en":"A moving image may be more compelling than a plain written notice.","zh":"移動畫面可能比普通文字告示更有吸引力。"},{"en":"If TV is more compelling than conversation, people may look away from others while talking.","zh":"如果電視比交談更有吸引力，人們談話時可能望向別處。"},{"en":"The phrase compares strength of attraction.","zh":"這個短語比較吸引力的強弱。"}],"source":"134 - TV Addiction.pdf","sourcePage":16},{"front":"talking to other people","meaning":"與他人交談","examples":[{"en":"The statement compares watching television with talking to other people.","zh":"該陳述把看電視與他人交談作比較。"},{"en":"Talking to other people means communicating directly with others through conversation.","zh":"talking to other people 指透過對話直接與他人溝通。"},{"en":"Families build relationships by talking to other people at meals instead of only watching screens.","zh":"家庭透過用餐時與他人交談，而不是只看螢幕，建立關係。"},{"en":"If television interrupts talking to other people, social connection may weaken.","zh":"如果電視打斷與他人交談，社交連繫可能減弱。"},{"en":"The phrase refers to human conversation, not one-way media consumption.","zh":"這個短語指人與人的對話，而不是單向媒體消費。"}],"source":"134 - TV Addiction.pdf","sourcePage":17},{"front":"information medium","meaning":"資訊媒介","examples":[{"en":"Television can be studied as an information medium.","zh":"電視可以作為資訊媒介來研究。"},{"en":"An information medium is a channel used to send news, ideas, stories, or messages.","zh":"information medium 指用來傳送新聞、想法、故事或訊息的渠道。"},{"en":"Newspapers, radio, television, and websites are information media.","zh":"報紙、電台、電視和網站都是資訊媒介。"},{"en":"Studying television as an information medium means looking at how it delivers messages to viewers.","zh":"把電視作為資訊媒介研究，意思是觀察它如何向觀眾傳送訊息。"},{"en":"The phrase focuses on communication function.","zh":"這個短語重點是傳播功能。"}],"source":"134 - TV Addiction.pdf","sourcePage":17},{"front":"scientific research","meaning":"科學研究","examples":[{"en":"Television has been the subject of scientific research for decades.","zh":"電視數十年來一直是科學研究的對象。"},{"en":"Scientific research is careful study that uses evidence, methods, and analysis.","zh":"scientific research 指使用證據、方法和分析的仔細研究。"},{"en":"Scientific research can test whether screen time affects sleep or attention.","zh":"科學研究可以測試螢幕時間是否影響睡眠或注意力。"},{"en":"Good scientific research avoids guessing by collecting data systematically.","zh":"良好科學研究透過有系統收集數據來避免猜測。"},{"en":"The phrase refers to evidence-based investigation.","zh":"這個短語指基於證據的調查。"}],"source":"134 - TV Addiction.pdf","sourcePage":17},{"front":"to some extent","meaning":"在某程度上","examples":[{"en":"The term TV addiction is, to some extent, unscientific.","zh":"「電視成癮」這個術語在某程度上是不科學的。"},{"en":"To some extent means partly or in a limited way.","zh":"to some extent 指部分地或在有限程度上。"},{"en":"Online learning can help students to some extent, but some still need face-to-face support.","zh":"網上學習在某程度上可以幫助學生，但有些人仍需要面授支援。"},{"en":"Saying to some extent makes a claim more careful and less absolute.","zh":"說 to some extent 令說法更謹慎，較不絕對。"},{"en":"The phrase allows both agreement and limitation.","zh":"這個短語同時容許同意和限制。"}],"source":"134 - TV Addiction.pdf","sourcePage":17},{"front":"unscientific","meaning":"不科學的","examples":[{"en":"The term TV addiction is somewhat unscientific.","zh":"「電視成癮」這個術語有點不科學。"},{"en":"Unscientific means not based on careful evidence, testing, or clear scientific definition.","zh":"unscientific 指不是基於仔細證據、測試或清晰科學定義。"},{"en":"A health claim is unscientific if it has no data and no proper test.","zh":"如果健康聲稱沒有數據和適當測試，它就是不科學的。"},{"en":"Calling a behaviour an addiction can be unscientific if no clear criteria are used.","zh":"如果沒有使用清晰準則，把一種行為稱為成癮可能是不科學的。"},{"en":"The word criticises weak evidence or loose reasoning.","zh":"這個詞批評證據薄弱或推理鬆散。"}],"source":"134 - TV Addiction.pdf","sourcePage":17},{"front":"exercise too little","meaning":"運動太少","examples":[{"en":"The statement asks whether children know why they exercise too little.","zh":"該陳述問兒童是否知道自己為何運動太少。"},{"en":"To exercise too little means to do less physical activity than is healthy or needed.","zh":"exercise too little 指身體活動少於健康或需要的水平。"},{"en":"Children may exercise too little if they spend most free time on screens.","zh":"如果孩子大部分空閒時間都用在螢幕上，他們可能運動太少。"},{"en":"Exercising too little can affect health, sleep, mood, and concentration.","zh":"運動太少可以影響健康、睡眠、心情和專注力。"},{"en":"The phrase describes insufficient activity, not poor sports skill.","zh":"這個短語描述活動不足，而不是運動技巧差。"}],"source":"134 - TV Addiction.pdf","sourcePage":17},{"front":"choose three letters","meaning":"選擇三個字母","examples":[{"en":"Students choose three letters from the options.","zh":"學生從選項中選擇三個字母。"},{"en":"Choose three letters means select three answer choices, usually marked A, B, C, and so on.","zh":"choose three letters 指選擇三個答案選項，通常標為 A、B、C 等。"},{"en":"If the instruction says choose three letters, giving only two answers is incomplete.","zh":"如果指示說選擇三個字母，只給兩個答案就是不完整。"},{"en":"Students should check that all three letters are supported by the passage.","zh":"學生應檢查三個字母是否都得到篇章支持。"},{"en":"The phrase is an exam instruction about answer format.","zh":"這個短語是關於答案格式的考試指示。"}],"source":"134 - TV Addiction.pdf","sourcePage":17},{"front":"benefits of watching TV","meaning":"看電視的好處","examples":[{"en":"The question asks about the benefits of watching TV.","zh":"題目問看電視的好處。"},{"en":"Benefits of watching TV are the useful or positive results that television can provide.","zh":"benefits of watching TV 指電視可以提供的有用或正面結果。"},{"en":"Benefits of watching TV may include learning, relaxation, and exposure to art or news.","zh":"看電視的好處可能包括學習、放鬆和接觸藝術或新聞。"},{"en":"These benefits depend on what people watch and how much time they spend watching.","zh":"這些好處取決於人們看甚麼以及花多少時間觀看。"},{"en":"The phrase focuses on positive effects, not addiction or harm.","zh":"這個短語重點是正面效果，而不是成癮或傷害。"}],"source":"134 - TV Addiction.pdf","sourcePage":17},{"front":"artistic inspiration","meaning":"藝術靈感","examples":[{"en":"Television may provide artistic inspiration.","zh":"電視可能提供藝術靈感。"},{"en":"Artistic inspiration is the creative influence that helps someone produce art, music, writing, or design.","zh":"artistic inspiration 指幫助人創作藝術、音樂、寫作或設計的創意影響。"},{"en":"A beautifully filmed documentary may give students artistic inspiration for a video project.","zh":"拍攝精美的紀錄片可能給學生影片項目的藝術靈感。"},{"en":"Artistic inspiration can come from images, music, stories, colours, or emotional scenes.","zh":"藝術靈感可以來自影像、音樂、故事、顏色或情感場面。"},{"en":"The phrase describes creative stimulation, not simple entertainment.","zh":"這個短語描述創意刺激，而不是單純娛樂。"}],"source":"134 - TV Addiction.pdf","sourcePage":17},{"front":"family reunions","meaning":"家庭團聚","examples":[{"en":"The option mentions family reunions as a possible benefit.","zh":"選項提到家庭團聚作為可能好處。"},{"en":"Family reunions are occasions when relatives gather after being apart.","zh":"family reunions 指親人分開後再次聚在一起的場合。"},{"en":"A holiday dinner can become a family reunion when cousins and grandparents meet again.","zh":"當表兄弟姊妹和祖父母再次見面，節日晚餐可以成為家庭團聚。"},{"en":"Television might support family time if relatives gather to watch a special programme together.","zh":"如果親人聚在一起觀看特別節目，電視可能支持家庭時間。"},{"en":"The phrase refers to people coming together, not only watching TV.","zh":"這個短語指人們聚首，而不只是看電視。"}],"source":"134 - TV Addiction.pdf","sourcePage":17},{"front":"stress relief","meaning":"減壓","examples":[{"en":"Television can provide stress relief for some viewers.","zh":"電視可以為一些觀眾提供減壓。"},{"en":"Stress relief means reducing worry, pressure, or mental tension.","zh":"stress relief 指減少憂慮、壓力或心理緊張。"},{"en":"A comedy show may give stress relief after a tiring workday.","zh":"疲累工作日後，喜劇節目可能帶來減壓效果。"},{"en":"Stress relief is helpful, but using TV to avoid every problem can become unhealthy.","zh":"減壓有幫助，但用電視逃避每個問題可能變得不健康。"},{"en":"The phrase describes emotional easing.","zh":"這個短語描述情緒舒緩。"}],"source":"134 - TV Addiction.pdf","sourcePage":17},{"front":"knowledge and education","meaning":"知識和教育","examples":[{"en":"Television can provide knowledge and education.","zh":"電視可以提供知識和教育。"},{"en":"Knowledge and education mean useful information and learning that help people understand the world.","zh":"knowledge and education 指有用資訊和學習，幫助人理解世界。"},{"en":"News programmes and documentaries can provide knowledge and education to viewers.","zh":"新聞節目和紀錄片可以為觀眾提供知識和教育。"},{"en":"Television supports education best when viewers actively think about what they watch.","zh":"當觀眾主動思考所看內容，電視最能支持教育。"},{"en":"The phrase points to learning benefits.","zh":"這個短語指出學習方面的好處。"}],"source":"134 - TV Addiction.pdf","sourcePage":18},{"front":"work efficiency","meaning":"工作效率","examples":[{"en":"The option mentions work efficiency.","zh":"選項提到工作效率。"},{"en":"Work efficiency means doing work well with less wasted time, energy, or resources.","zh":"work efficiency 指用較少浪費的時間、精力或資源把工作做好。"},{"en":"Clear instructions can improve work efficiency because workers make fewer mistakes.","zh":"清晰指示可以改善工作效率，因為員工犯錯較少。"},{"en":"Too much television may reduce work efficiency if it cuts into sleep.","zh":"如果看太多電視削減睡眠，可能降低工作效率。"},{"en":"The phrase describes productivity, not simply working fast.","zh":"這個短語描述生產力，而不只是工作速度快。"}],"source":"134 - TV Addiction.pdf","sourcePage":18},{"front":"easing communication conflicts","meaning":"紓緩溝通衝突","examples":[{"en":"The option mentions easing communication conflicts.","zh":"選項提到紓緩溝通衝突。"},{"en":"Easing communication conflicts means reducing misunderstandings, arguments, or tension in communication.","zh":"easing communication conflicts 指減少溝通中的誤解、爭吵或緊張。"},{"en":"A family meeting can help ease communication conflicts between parents and teenagers.","zh":"家庭會議可以幫助紓緩父母與青少年之間的溝通衝突。"},{"en":"Clear listening rules can ease communication conflicts in group projects.","zh":"清晰聆聽規則可以在小組項目中紓緩溝通衝突。"},{"en":"The phrase describes making communication problems less severe.","zh":"這個短語描述令溝通問題變得較不嚴重。"}],"source":"134 - TV Addiction.pdf","sourcePage":18},{"front":"list of statements","meaning":"陳述列表","examples":[{"en":"The question provides a list of statements about researchers.","zh":"題目提供關於研究人員的陳述列表。"},{"en":"A list of statements is a set of sentences that students must check, match, or evaluate.","zh":"list of statements 指學生必須檢查、配對或評估的一組句子。"},{"en":"In a reading test, a list of statements may need to be matched with people or paragraphs.","zh":"在閱讀測驗中，陳述列表可能需要與人物或段落配對。"},{"en":"A clear list of statements helps students compare options one by one.","zh":"清晰陳述列表幫助學生逐一比較選項。"},{"en":"The phrase refers to an organised set of claims.","zh":"這個短語指有組織的一組聲稱。"}],"source":"134 - TV Addiction.pdf","sourcePage":18},{"front":"match each researcher with","meaning":"將每位研究人員與……配對","examples":[{"en":"Students match each researcher with the correct statement.","zh":"學生將每位研究人員與正確陳述配對。"},{"en":"To match each researcher with something means to connect every researcher to the right answer.","zh":"match each researcher with something 指把每位研究人員連接到正確答案。"},{"en":"Students may match each scientist with the discovery described in the passage.","zh":"學生可能將每位科學家與篇章描述的發現配對。"},{"en":"Matching requires careful reading because names and ideas may be far apart in the text.","zh":"配對需要仔細閱讀，因為姓名和想法可能在文本中相距很遠。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"134 - TV Addiction.pdf","sourcePage":18},{"front":"specific formal characteristics","meaning":"具體形式特徵","examples":[{"en":"The medium’s specific formal characteristics are important.","zh":"這種媒介的具體形式特徵很重要。"},{"en":"Specific formal characteristics are particular features of form, style, or presentation.","zh":"specific formal characteristics 指形式、風格或呈現方式中的特定特徵。"},{"en":"In television, specific formal characteristics include cuts, zooms, sounds, and camera movement.","zh":"在電視中，具體形式特徵包括切鏡、變焦、聲音和鏡頭移動。"},{"en":"These characteristics matter because they can affect attention even before content is understood.","zh":"這些特徵重要，因為它們可以在內容被理解前先影響注意力。"},{"en":"The phrase points to exact features, not general impressions.","zh":"這個短語指確切特徵，而不是一般印象。"}],"source":"134 - TV Addiction.pdf","sourcePage":18},{"front":"what matter","meaning":"重要之處","examples":[{"en":"The statement says that formal characteristics are what matter.","zh":"該陳述說形式特徵才是重要之處。"},{"en":"What matter are the things that are important in a situation.","zh":"what matter 指在某情況中真正重要的東西。"},{"en":"In a safety drill, clear exits and calm instructions are what matter.","zh":"在安全演習中，清楚出口和冷靜指示才是重要之處。"},{"en":"If formal characteristics are what matter, researchers focus on editing style rather than story topic.","zh":"如果形式特徵才是重要之處，研究人員會集中於剪接風格，而不是故事主題。"},{"en":"The phrase highlights the key factor in a comparison.","zh":"這個短語突出比較中的關鍵因素。"}],"source":"134 - TV Addiction.pdf","sourcePage":18},{"front":"trigger a physical response","meaning":"觸發身體反應","examples":[{"en":"Television’s distractions can trigger a physical response.","zh":"電視的干擾可以觸發身體反應。"},{"en":"To trigger a physical response means to cause the body to react.","zh":"trigger a physical response 指引起身體作出反應。"},{"en":"A sudden alarm can trigger a physical response such as a faster heartbeat.","zh":"突然警鐘可以觸發心跳加快等身體反應。"},{"en":"Screen changes can trigger a physical response before viewers consciously decide to watch.","zh":"螢幕變化可以在觀眾有意識決定觀看前觸發身體反應。"},{"en":"The phrase links an outside stimulus with bodily reaction.","zh":"這個短語把外在刺激與身體反應連起來。"}],"source":"134 - TV Addiction.pdf","sourcePage":18},{"front":"a new or sudden stimulus","meaning":"新或突然的刺激","examples":[{"en":"The orienting response reacts to a new or sudden stimulus.","zh":"定向反應會對新或突然的刺激作出反應。"},{"en":"A new or sudden stimulus is something unfamiliar or unexpected that attracts attention.","zh":"new or sudden stimulus 指陌生或意外、會吸引注意力的事物。"},{"en":"A bright flash in a dark room is a new or sudden stimulus.","zh":"黑暗房間中的一陣強光是新或突然的刺激。"},{"en":"Such a stimulus can interrupt reading because the body turns attention toward it.","zh":"這類刺激可以打斷閱讀，因為身體把注意力轉向它。"},{"en":"The phrase explains why sudden screen changes are hard to ignore.","zh":"這個短語解釋為何突然的螢幕變化難以忽視。"}],"source":"134 - TV Addiction.pdf","sourcePage":18},{"front":"conveying information","meaning":"傳達資料","examples":[{"en":"The option says that conveying information is the most important thing.","zh":"選項說傳達資料是最重要的事情。"},{"en":"Conveying information means communicating facts, ideas, or messages to others.","zh":"conveying information 指向他人傳達事實、想法或訊息。"},{"en":"A public notice succeeds if it is good at conveying information clearly.","zh":"如果公共告示能清楚傳達資料，它就是成功的。"},{"en":"A video can be exciting but weak at conveying information if viewers forget the message.","zh":"如果觀眾忘記訊息，一段影片可以很刺激但傳達資料能力很弱。"},{"en":"The phrase focuses on passing meaning from sender to receiver.","zh":"這個短語重點是把意思從發送者傳到接收者。"}],"source":"134 - TV Addiction.pdf","sourcePage":18},{"front":"difficult to ignore","meaning":"難以忽視","examples":[{"en":"Television can be difficult to ignore.","zh":"電視可以難以忽視。"},{"en":"Difficult to ignore means hard not to notice or pay attention to.","zh":"difficult to ignore 指難以不注意或不理會。"},{"en":"A loud phone notification is difficult to ignore in a quiet classroom.","zh":"在安靜課室中，響亮手機通知難以忽視。"},{"en":"Television is difficult to ignore when movement and sound keep changing.","zh":"當動作和聲音不斷變化，電視就難以忽視。"},{"en":"The phrase describes strong attention-grabbing power.","zh":"這個短語描述強大的吸引注意力力量。"}],"source":"134 - TV Addiction.pdf","sourcePage":18},{"front":"how deeply people remember content","meaning":"人們對內容記得有多深","examples":[{"en":"Researchers study how deeply people remember content.","zh":"研究人員研究人們對內容記得有多深。"},{"en":"How deeply people remember content means how well and meaningfully they keep information in memory.","zh":"how deeply people remember content 指人們把資訊記得多好和多有意義。"},{"en":"Students remember content more deeply when they explain it in their own words.","zh":"當學生用自己的說話解釋內容，他們會記得更深。"},{"en":"Fast editing may hold attention but not always help people remember content deeply.","zh":"快速剪接可能保持注意力，但不一定幫助人深入記住內容。"},{"en":"The phrase focuses on quality of memory, not just whether something was seen.","zh":"這個短語重點是記憶質素，而不只是是否看過。"}],"source":"134 - TV Addiction.pdf","sourcePage":19},{"front":"be related to its format","meaning":"與其形式有關","examples":[{"en":"Memory of content may be related to its format.","zh":"對內容的記憶可能與其形式有關。"},{"en":"To be related to its format means to be connected with how the information is presented.","zh":"be related to its format 指與資訊呈現方式有關。"},{"en":"A student’s memory of notes may be related to their format, such as tables or paragraphs.","zh":"學生對筆記的記憶可能與其形式有關，例如表格或段落。"},{"en":"If content is presented with clear structure, format can support memory.","zh":"如果內容以清晰結構呈現，形式可以支持記憶。"},{"en":"The phrase links result with presentation style.","zh":"這個短語把結果與呈現風格連起來。"}],"source":"134 - TV Addiction.pdf","sourcePage":19},{"front":"heart rate remains stable","meaning":"心率保持穩定","examples":[{"en":"The option says that heart rate remains stable while watching television.","zh":"選項說看電視時心率保持穩定。"},{"en":"Heart rate remains stable means the speed of the heartbeat does not change much.","zh":"heart rate remains stable 指心跳速度沒有太大變化。"},{"en":"During calm reading, a person’s heart rate may remain stable.","zh":"在安靜閱讀期間，一個人的心率可能保持穩定。"},{"en":"If heart rate remains stable, there may be little sign of physical reaction.","zh":"如果心率保持穩定，可能沒有明顯身體反應。"},{"en":"The phrase describes lack of major change in heartbeat.","zh":"這個短語描述心跳沒有重大變化。"}],"source":"134 - TV Addiction.pdf","sourcePage":19},{"front":"clinical dependence on television","meaning":"對電視的臨床依賴","examples":[{"en":"Clinical dependence on television would need to meet addiction criteria.","zh":"對電視的臨床依賴需要符合成癮準則。"},{"en":"Clinical dependence on television means a medically serious reliance on TV judged by formal criteria.","zh":"clinical dependence on television 指根據正式準則判斷、醫學上嚴重的電視依賴。"},{"en":"A person might show clinical dependence if viewing repeatedly harms work, family, and health.","zh":"如果觀看電視反覆損害工作、家庭和健康，一個人可能表現出臨床依賴。"},{"en":"Clinical dependence requires more evidence than simply saying someone watches a lot.","zh":"臨床依賴需要比「某人看很多電視」更多的證據。"},{"en":"The phrase applies medical thinking to television behaviour.","zh":"這個短語把醫學思維應用於電視行為。"}],"source":"134 - TV Addiction.pdf","sourcePage":19},{"front":"meet the criteria for","meaning":"符合……準則","examples":[{"en":"A behaviour may meet the criteria for addiction.","zh":"一種行為可能符合成癮準則。"},{"en":"To meet the criteria for something means to satisfy the standards used to define it.","zh":"meet the criteria for something 指符合用來界定某事的標準。"},{"en":"A student may meet the criteria for a scholarship if grades and interview results are strong enough.","zh":"如果成績和面試結果足夠強，學生可能符合獎學金準則。"},{"en":"A habit meets addiction criteria only when several serious signs appear.","zh":"只有當多項嚴重跡象出現，習慣才符合成癮準則。"},{"en":"The phrase is used for formal judgment based on standards.","zh":"這個短語用於基於標準的正式判斷。"}],"source":"134 - TV Addiction.pdf","sourcePage":19},{"front":"complete the following summary","meaning":"完成以下摘要","examples":[{"en":"Students complete the following summary using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"To complete the following summary means to fill in missing words in the summary below.","zh":"complete the following summary 指填補下面摘要中的空缺字詞。"},{"en":"In a reading test, students complete the following summary by locating exact words in the passage.","zh":"在閱讀測驗中，學生透過在篇章中定位準確字詞來完成以下摘要。"},{"en":"Correct grammar and word limits matter when completing a summary.","zh":"完成摘要時，正確文法和字數限制很重要。"},{"en":"The phrase is an exam instruction.","zh":"這個短語是考試指示。"}],"source":"134 - TV Addiction.pdf","sourcePage":19},{"front":"using no more than two words","meaning":"使用不多於兩個詞","examples":[{"en":"Students should use no more than two words from the passage.","zh":"學生應使用文章中不多於兩個詞。"},{"en":"Using no more than two words means writing one or two words, but not three or more.","zh":"using no more than two words 指寫一個或兩個詞，但不是三個或更多。"},{"en":"If the answer is “formal features,” it uses no more than two words.","zh":"如果答案是 formal features，它就使用不多於兩個詞。"},{"en":"Students lose marks if they write too many words despite understanding the answer.","zh":"即使學生理解答案，寫太多詞也會失分。"},{"en":"The phrase gives a strict word-limit rule.","zh":"這個短語提供嚴格字數限制規則。"}],"source":"134 - TV Addiction.pdf","sourcePage":19},{"front":"become a worldwide pastime","meaning":"成為全球消遣","examples":[{"en":"Television has become a worldwide pastime.","zh":"電視已成為全球消遣。"},{"en":"To become a worldwide pastime means to become a leisure activity enjoyed in many countries.","zh":"become a worldwide pastime 指成為許多國家都喜愛的閒暇活動。"},{"en":"Online video watching has become a worldwide pastime for people with smartphones.","zh":"對有智能手機的人而言，觀看網上影片已成為全球消遣。"},{"en":"When an activity becomes a worldwide pastime, it can shape culture across borders.","zh":"當一項活動成為全球消遣，它可以跨越國界塑造文化。"},{"en":"The phrase describes global popularity in free time.","zh":"這個短語描述閒暇時間中的全球流行。"}],"source":"134 - TV Addiction.pdf","sourcePage":19},{"front":"a great deal of time","meaning":"大量時間","examples":[{"en":"Some people spend a great deal of time watching television.","zh":"有些人花大量時間看電視。"},{"en":"A great deal of time means a large amount of time.","zh":"a great deal of time 指大量時間。"},{"en":"A person may spend a great deal of time commuting if home is far from work.","zh":"如果家離工作地點很遠，一個人可能花大量時間通勤。"},{"en":"Spending a great deal of time on TV can leave little room for sleep, exercise, or conversation.","zh":"花大量時間看電視可以令睡眠、運動或交談時間所剩無幾。"},{"en":"The phrase highlights the size of the time commitment.","zh":"這個短語強調時間投入的龐大。"}],"source":"134 - TV Addiction.pdf","sourcePage":19},{"front":"according to surveys","meaning":"根據調查","examples":[{"en":"According to surveys, some adults call themselves TV addicts.","zh":"根據調查，有些成年人自稱電視成癮者。"},{"en":"According to surveys means based on the results of questionnaires or opinion studies.","zh":"according to surveys 指根據問卷或民意研究結果。"},{"en":"According to surveys, many students prefer short videos for revision.","zh":"根據調查，許多學生偏好用短片溫習。"},{"en":"Survey results can reveal patterns, but they depend on honest and representative answers.","zh":"調查結果可以揭示模式，但取決於誠實和具代表性的答案。"},{"en":"The phrase introduces evidence from collected responses.","zh":"這個短語引入來自收集回應的證據。"}],"source":"134 - TV Addiction.pdf","sourcePage":19},{"front":"describe themselves as","meaning":"自稱為","examples":[{"en":"Some people describe themselves as TV addicts.","zh":"有些人自稱為電視成癮者。"},{"en":"To describe themselves as something means to use a label or phrase for their own identity or behaviour.","zh":"describe themselves as something 指用某個標籤或短語描述自己的身份或行為。"},{"en":"A student may describe herself as nervous before speaking exams.","zh":"學生可能在口語考試前自稱為緊張的人。"},{"en":"How people describe themselves can show their self-awareness and worries.","zh":"人們如何自稱可以顯示他們的自我覺察和擔憂。"},{"en":"The phrase refers to self-description, not necessarily an official label.","zh":"這個短語指自我描述，而不一定是官方標籤。"}],"source":"134 - TV Addiction.pdf","sourcePage":19},{"front":"human instinct","meaning":"人類本能","examples":[{"en":"The attraction may arise from a human instinct.","zh":"這種吸引力可能來自人類本能。"},{"en":"Human instinct is a natural reaction or tendency that people do not need to learn consciously.","zh":"human instinct 指人不需要有意識學習的自然反應或傾向。"},{"en":"Turning toward a sudden sound can be a human instinct.","zh":"轉向突然聲音可以是人類本能。"},{"en":"Human instinct may make people notice movement before they understand what is happening.","zh":"人類本能可能令人們在理解發生甚麼之前先注意動作。"},{"en":"The phrase explains behaviour as natural and automatic.","zh":"這個短語把行為解釋為自然和自動。"}],"source":"134 - TV Addiction.pdf","sourcePage":20},{"front":"inbuilt part of","meaning":"……與生俱來的一部分","examples":[{"en":"The orienting response is an inbuilt part of our evolutionary heritage.","zh":"定向反應是我們進化遺產中與生俱來的一部分。"},{"en":"An inbuilt part of something is a natural or built-in element within it.","zh":"inbuilt part of something 指某事物內自然存在或內置的一部分。"},{"en":"Curiosity may be an inbuilt part of how children learn.","zh":"好奇心可能是兒童學習方式中與生俱來的一部分。"},{"en":"If a reaction is an inbuilt part of human attention, it can happen before conscious choice.","zh":"如果某反應是人類注意力中與生俱來的一部分，它可以在有意識選擇前發生。"},{"en":"The phrase suggests something belongs naturally inside a system.","zh":"這個短語暗示某物自然屬於一個系統之內。"}],"source":"134 - TV Addiction.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 135":[{"front":"the sense of flavour","meaning":"風味感覺；味道感知","examples":[{"en":"The passage explains how the sense of flavour depends heavily on smell.","zh":"文章解釋風味感覺如何在很大程度上依賴嗅覺。"},{"en":"The sense of flavour means the way we experience food through taste, smell, and feeling in the mouth.","zh":"風味感覺指我們透過味覺、嗅覺和口腔感覺來體驗食物的方式。"},{"en":"When you have a blocked nose, the sense of flavour becomes weaker and food may seem plain.","zh":"當你鼻塞時，風味感覺會變弱，食物可能顯得淡而無味。"},{"en":"The sense of flavour is important because it helps people enjoy food and notice whether it is fresh.","zh":"風味感覺很重要，因為它幫助人享受食物並察覺食物是否新鮮。"},{"en":"This phrase is broader than taste alone because smell creates much of what we call flavour.","zh":"這個短語比單純味覺更廣，因為嗅覺創造了我們所說的大部分味道。"}],"source":"135 - The sense of flavour.pdf","sourcePage":1},{"front":"human beings acquired","meaning":"人類獲得了","examples":[{"en":"Scientists believe that human beings acquired taste as a survival mechanism.","zh":"科學家相信人類獲得味覺是作為一種生存機制。"},{"en":"Human beings acquired something means people developed or gained it over time.","zh":"human beings acquired 某物，意思是人類隨時間發展或獲得了它。"},{"en":"Human beings acquired language gradually as groups needed better ways to communicate.","zh":"隨着群體需要更好的溝通方式，人類逐漸獲得了語言能力。"},{"en":"If human beings acquired taste to avoid poison, taste had a practical survival purpose.","zh":"如果人類獲得味覺是為了避免中毒，味覺就有實際的生存用途。"},{"en":"The phrase is often used when discussing abilities that developed through history or evolution.","zh":"這個短語常用於討論歷史或演化中發展出來的能力。"}],"source":"135 - The sense of flavour.pdf","sourcePage":1},{"front":"the sense of taste","meaning":"味覺","examples":[{"en":"The sense of taste may have developed to help people avoid poison.","zh":"味覺可能是為了幫助人避免毒物而發展出來的。"},{"en":"The sense of taste is the ability to notice flavours such as sweet, sour, bitter, and salty.","zh":"味覺是察覺甜、酸、苦、鹹等味道的能力。"},{"en":"A child uses the sense of taste when deciding whether soup is too salty.","zh":"孩子判斷湯是否太鹹時，會使用味覺。"},{"en":"If the sense of taste becomes weak during illness, meals may seem less enjoyable.","zh":"如果生病時味覺變弱，餐食可能變得較不享受。"},{"en":"The phrase refers mainly to what the tongue detects, not everything involved in flavour.","zh":"這個短語主要指舌頭偵測到的東西，而不是風味所涉及的一切。"}],"source":"135 - The sense of flavour.pdf","sourcePage":1},{"front":"as a way to","meaning":"作為……的方法","examples":[{"en":"Humans acquired taste as a way to avoid dangerous foods.","zh":"人類獲得味覺，作為避免危險食物的方法。"},{"en":"As a way to means as a method or purpose for doing something.","zh":"as a way to 指作為做某事的方法或目的。"},{"en":"Students use flashcards as a way to remember new vocabulary.","zh":"學生使用生字卡作為記住新詞彙的方法。"},{"en":"A family may cook at home as a way to save money and eat healthier meals.","zh":"家庭可能在家煮飯，作為省錢和吃得更健康的方法。"},{"en":"The phrase clearly links an action with its purpose.","zh":"這個短語清楚把行動與目的連繫起來。"}],"source":"135 - The sense of flavour.pdf","sourcePage":1},{"front":"avoid being poisoned","meaning":"避免中毒","examples":[{"en":"Taste helped early humans avoid being poisoned by harmful plants.","zh":"味覺幫助早期人類避免被有害植物毒害。"},{"en":"To avoid being poisoned means to prevent harmful substances from entering the body and causing illness or death.","zh":"avoid being poisoned 指防止有害物質進入身體並造成疾病或死亡。"},{"en":"Children are taught not to eat unknown berries to avoid being poisoned.","zh":"孩子被教導不要吃不認識的漿果，以避免中毒。"},{"en":"If food smells rotten, throwing it away can help people avoid being poisoned.","zh":"如果食物聞起來腐壞，把它丟掉可以幫助人避免中毒。"},{"en":"The phrase is used when danger comes from toxic food, chemicals, or substances.","zh":"這個短語用於危險來自有毒食物、化學品或物質時。"}],"source":"135 - The sense of flavour.pdf","sourcePage":1},{"front":"edible plants","meaning":"可食用植物","examples":[{"en":"Edible plants generally taste sweet.","zh":"可食用植物通常味道甜。"},{"en":"Edible plants are plants that people can safely eat.","zh":"edible plants 是人們可以安全食用的植物。"},{"en":"Lettuce, spinach, and many herbs are edible plants used in everyday cooking.","zh":"生菜、菠菜和許多香草都是日常烹飪中使用的可食用植物。"},{"en":"If hikers cannot identify edible plants, they should not eat wild leaves or berries.","zh":"如果行山者不能辨認可食用植物，就不應吃野外葉子或漿果。"},{"en":"The phrase focuses on whether a plant is safe and suitable for food.","zh":"這個短語重點在於植物是否安全並適合作食物。"}],"source":"135 - The sense of flavour.pdf","sourcePage":1},{"front":"deadly ones","meaning":"致命的植物","examples":[{"en":"Deadly plants often taste bitter.","zh":"致命的植物通常味道苦。"},{"en":"Deadly ones means the dangerous plants or things that can cause death.","zh":"deadly ones 指能導致死亡的危險植物或事物。"},{"en":"Some mushrooms look harmless, but deadly ones can make people seriously ill.","zh":"有些蘑菇看似無害，但致命的蘑菇可以令人重病。"},{"en":"If children learn the difference between safe berries and deadly ones, accidents may be prevented.","zh":"如果孩子學會分辨安全漿果和致命的漿果，意外可能得以避免。"},{"en":"The phrase usually refers back to a noun already mentioned.","zh":"這個短語通常指回前文已提及的名詞。"}],"source":"135 - The sense of flavour.pdf","sourcePage":1},{"front":"be supposed to","meaning":"應該；被認為會","examples":[{"en":"Taste is supposed to help us choose safe food.","zh":"味覺應該幫助我們選擇安全食物。"},{"en":"Be supposed to means be expected or intended to do something.","zh":"be supposed to 指被預期或被設計去做某事。"},{"en":"A school bell is supposed to tell students when a lesson begins or ends.","zh":"學校鐘聲應該告訴學生課堂何時開始或結束。"},{"en":"If medicine is supposed to reduce pain but makes it worse, patients should ask a doctor.","zh":"如果藥物本應減輕疼痛卻令情況更差，病人應該問醫生。"},{"en":"The phrase can show purpose, expectation, or a rule.","zh":"這個短語可以表示目的、預期或規則。"}],"source":"135 - The sense of flavour.pdf","sourcePage":1},{"front":"differentiate A from B","meaning":"區分A與B","examples":[{"en":"Taste helps us differentiate good food from bad food.","zh":"味覺幫助我們區分好食物與壞食物。"},{"en":"To differentiate A from B means to tell the difference between two things.","zh":"differentiate A from B 指分辨兩件事物之間的差異。"},{"en":"Teachers help children differentiate fact from opinion in reading lessons.","zh":"老師在閱讀課中幫助孩子區分事實與意見。"},{"en":"If shoppers cannot differentiate real products from fake ones, they may be cheated.","zh":"如果購物者不能區分真貨與假貨，可能會受騙。"},{"en":"The phrase is useful when two things look similar but are not the same.","zh":"這個短語適用於兩件事看似相似但其實不同時。"}],"source":"135 - The sense of flavour.pdf","sourcePage":1},{"front":"food that is good for us","meaning":"對我們有益的食物","examples":[{"en":"Taste helps people identify food that is good for them.","zh":"味覺幫助人們辨認對自己有益的食物。"},{"en":"Food that is good for us means food that supports health, growth, and energy.","zh":"food that is good for us 指支持健康、成長和能量的食物。"},{"en":"Fresh fruit, vegetables, and beans are examples of food that is good for us.","zh":"新鮮水果、蔬菜和豆類都是對我們有益的食物例子。"},{"en":"If children eat more food that is good for them, they may feel stronger and concentrate better.","zh":"如果孩子吃更多對他們有益的食物，他們可能更強壯並更能集中精神。"},{"en":"The phrase describes healthy food, not just food that tastes nice.","zh":"這個短語描述健康食物，而不只是味道好的食物。"}],"source":"135 - The sense of flavour.pdf","sourcePage":1},{"front":"taste buds","meaning":"味蕾","examples":[{"en":"Taste buds on the tongue detect basic tastes.","zh":"舌頭上的味蕾偵測基本味道。"},{"en":"Taste buds are tiny sense organs on the tongue that help us notice taste.","zh":"taste buds 是舌頭上幫助我們察覺味道的微小感覺器官。"},{"en":"When you eat lemon, your taste buds detect its sourness.","zh":"當你吃檸檬時，味蕾會偵測到它的酸味。"},{"en":"If taste buds are affected by illness, food may seem different from usual.","zh":"如果味蕾受疾病影響，食物可能與平時味道不同。"},{"en":"The phrase is often used when explaining how the tongue senses food.","zh":"這個短語常用於解釋舌頭如何感知食物。"}],"source":"135 - The sense of flavour.pdf","sourcePage":1},{"front":"detect the presence of","meaning":"偵測到……的存在","examples":[{"en":"The tongue can detect the presence of several basic tastes.","zh":"舌頭可以偵測到幾種基本味道的存在。"},{"en":"To detect the presence of something means to notice or identify that it is there.","zh":"detect the presence of 某物，意思是察覺或識別某物存在。"},{"en":"A smoke alarm can detect the presence of smoke before people see fire.","zh":"煙霧警報器可以在人們看見火之前偵測到煙霧的存在。"},{"en":"If a test can detect the presence of bacteria, doctors can choose treatment earlier.","zh":"如果測試能偵測到細菌的存在，醫生可以更早選擇治療。"},{"en":"The phrase is often used in science, health, and safety contexts.","zh":"這個短語常用於科學、健康和安全語境。"}],"source":"135 - The sense of flavour.pdf","sourcePage":2},{"front":"half a dozen or so","meaning":"大約六個","examples":[{"en":"The tongue can detect half a dozen or so basic tastes.","zh":"舌頭可以偵測大約六種基本味道。"},{"en":"Half a dozen or so means about six, not an exact number.","zh":"half a dozen or so 指大約六個，不是精確數字。"},{"en":"We need half a dozen or so chairs for the meeting, depending on who comes.","zh":"我們需要大約六張椅子開會，視乎誰會來。"},{"en":"If a shop sells half a dozen or so kinds of bread, customers still have some choice.","zh":"如果商店出售大約六種麵包，顧客仍有一些選擇。"},{"en":"The phrase is informal and useful when an approximate number is enough.","zh":"這個短語較口語，適用於只需大概數字時。"}],"source":"135 - The sense of flavour.pdf","sourcePage":2},{"front":"basic tastes","meaning":"基本味道","examples":[{"en":"Sweet, sour, bitter and salty are basic tastes.","zh":"甜、酸、苦和鹹是基本味道。"},{"en":"Basic tastes are the simple taste categories that the tongue can identify.","zh":"basic tastes 是舌頭可以識別的簡單味道類別。"},{"en":"In a cooking lesson, students compare basic tastes by tasting sugar, lemon, salt, and bitter tea.","zh":"在烹飪課中，學生透過品嚐糖、檸檬、鹽和苦茶來比較基本味道。"},{"en":"Understanding basic tastes helps cooks balance dishes more carefully.","zh":"理解基本味道有助廚師更小心地平衡菜式。"},{"en":"The phrase refers to simple taste types, not complex food flavours.","zh":"這個短語指簡單味道種類，而不是複雜食物風味。"}],"source":"135 - The sense of flavour.pdf","sourcePage":2},{"front":"sweet, sour, bitter and salty","meaning":"甜、酸、苦、鹹","examples":[{"en":"The tongue can detect sweet, sour, bitter and salty tastes.","zh":"舌頭可以偵測甜、酸、苦、鹹的味道。"},{"en":"Sweet, sour, bitter and salty are four common basic tastes found in many foods.","zh":"sweet, sour, bitter and salty 是許多食物中常見的四種基本味道。"},{"en":"Lemon is sour, sugar is sweet, black coffee can be bitter, and soy sauce is salty.","zh":"檸檬是酸的，糖是甜的，黑咖啡可以是苦的，豉油是鹹的。"},{"en":"If a dish is too salty or bitter, people may add sweet or sour ingredients to balance it.","zh":"如果一道菜太鹹或太苦，人們可能加入甜或酸的材料來平衡。"},{"en":"The phrase lists common taste categories that learners can easily recognise.","zh":"這個短語列出學習者容易辨認的常見味道類別。"}],"source":"135 - The sense of flavour.pdf","sourcePage":2},{"front":"umami","meaning":"鮮味","examples":[{"en":"Umami is a savoury taste identified by Japanese researchers.","zh":"鮮味是一種由日本研究人員識別出的鹹香味道。"},{"en":"Umami is a rich, savoury taste often found in meat, mushrooms, seaweed, and soy sauce.","zh":"umami 是一種濃郁的鮮味，常見於肉類、菇類、海藻和豉油。"},{"en":"A bowl of miso soup has umami because it tastes deep and savoury.","zh":"一碗味噌湯有鮮味，因為它味道深厚而鹹香。"},{"en":"If a dish lacks umami, cooks may add mushrooms or stock to make it fuller.","zh":"如果一道菜缺乏鮮味，廚師可能加入菇類或高湯令味道更飽滿。"},{"en":"The word names a taste that is different from sweet, sour, bitter, and salty.","zh":"這個字指一種不同於甜、酸、苦和鹹的味道。"}],"source":"135 - The sense of flavour.pdf","sourcePage":2},{"front":"be identified by","meaning":"由……識別出","examples":[{"en":"Umami was identified by Japanese researchers.","zh":"鮮味由日本研究人員識別出。"},{"en":"To be identified by someone means to be recognised, named, or discovered by that person or group.","zh":"be identified by 某人，意思是由該人或群體認出、命名或發現。"},{"en":"The illness was identified by doctors after several blood tests.","zh":"這種疾病經幾次驗血後由醫生識別出。"},{"en":"If a new species is identified by scientists, it may be given a scientific name.","zh":"如果新物種由科學家識別出，它可能獲得科學名稱。"},{"en":"The phrase focuses on who recognised or discovered something.","zh":"這個短語重點在於誰認出或發現某事物。"}],"source":"135 - The sense of flavour.pdf","sourcePage":2},{"front":"produce a rich, full sense of deliciousness","meaning":"產生濃郁而飽滿的美味感","examples":[{"en":"Umami produces a rich, full sense of deliciousness.","zh":"鮮味會產生濃郁而飽滿的美味感。"},{"en":"To produce a rich, full sense of deliciousness means to create a deep and satisfying taste.","zh":"produce a rich, full sense of deliciousness 指創造深厚而令人滿足的味道。"},{"en":"Slow-cooked soup can produce a rich, full sense of deliciousness after hours of boiling bones and vegetables.","zh":"慢煮湯經數小時熬煮骨頭和蔬菜後，可以產生濃郁而飽滿的美味感。"},{"en":"If a sauce produces a rich, full sense of deliciousness, people may feel the dish is more satisfying.","zh":"如果醬汁產生濃郁而飽滿的美味感，人們可能覺得菜式更令人滿足。"},{"en":"The phrase describes taste that feels deep and complete, not light or plain.","zh":"這個短語描述深厚而完整的味道，而不是清淡或平淡的味道。"}],"source":"135 - The sense of flavour.pdf","sourcePage":2},{"front":"be triggered by","meaning":"由……引發","examples":[{"en":"Umami is triggered by amino acids in certain foods.","zh":"鮮味由某些食物中的氨基酸引發。"},{"en":"To be triggered by something means to be caused or started by it.","zh":"be triggered by 某物，意思是由它造成或啟動。"},{"en":"An allergic reaction can be triggered by nuts in a dessert.","zh":"過敏反應可以由甜品中的果仁引發。"},{"en":"If stress is triggered by noise, a quieter room may help the student study.","zh":"如果壓力由噪音引發，較安靜的房間可能幫助學生學習。"},{"en":"The phrase shows the cause that starts a reaction or feeling.","zh":"這個短語顯示引起反應或感覺的原因。"}],"source":"135 - The sense of flavour.pdf","sourcePage":2},{"front":"amino acids","meaning":"氨基酸","examples":[{"en":"Amino acids in foods such as shellfish can trigger umami.","zh":"貝類等食物中的氨基酸可以引發鮮味。"},{"en":"Amino acids are small chemical units that help build proteins in living things.","zh":"amino acids 是幫助構成生物體內蛋白質的小型化學單位。"},{"en":"Beans, eggs, meat, and fish contain amino acids needed by the body.","zh":"豆類、雞蛋、肉類和魚類含有身體所需的氨基酸。"},{"en":"If a food contains certain amino acids, it may taste savoury and rich.","zh":"如果食物含有某些氨基酸，它可能有鹹香而濃郁的味道。"},{"en":"The phrase is common in biology, nutrition, and food science.","zh":"這個短語常見於生物學、營養和食品科學。"}],"source":"135 - The sense of flavour.pdf","sourcePage":2},{"front":"foods such as","meaning":"例如……的食物","examples":[{"en":"Umami is found in foods such as shellfish, mushrooms and seaweed.","zh":"鮮味存在於例如貝類、菇類和海藻的食物中。"},{"en":"Foods such as introduces examples of foods without listing every possible one.","zh":"foods such as 用來引出食物例子，而不是列出所有可能食物。"},{"en":"Foods such as rice, noodles, and bread provide energy for many people.","zh":"例如米飯、麵條和麵包的食物為許多人提供能量。"},{"en":"If children avoid foods such as vegetables and beans, they may miss useful nutrients.","zh":"如果孩子避免例如蔬菜和豆類的食物，他們可能錯過有用營養。"},{"en":"The phrase is useful when giving examples in a clear and simple way.","zh":"這個短語適合用來清楚簡單地提供例子。"}],"source":"135 - The sense of flavour.pdf","sourcePage":2},{"front":"shellfish","meaning":"貝類；甲殼類海鮮","examples":[{"en":"Shellfish can contain amino acids that trigger umami.","zh":"貝類可能含有引發鮮味的氨基酸。"},{"en":"Shellfish are sea animals with shells, such as shrimp, crab, clams, and oysters.","zh":"shellfish 是有外殼的海洋動物，例如蝦、蟹、蜆和蠔。"},{"en":"A seafood restaurant may serve shellfish with lemon and garlic.","zh":"海鮮餐廳可能供應配檸檬和蒜的貝類海鮮。"},{"en":"If someone is allergic to shellfish, they must avoid dishes containing shrimp or crab.","zh":"如果有人對貝類海鮮過敏，就必須避免含蝦或蟹的菜式。"},{"en":"The word refers to a food group from the sea, not ordinary fish.","zh":"這個字指海中的一類食物，而不是普通魚類。"}],"source":"135 - The sense of flavour.pdf","sourcePage":2},{"front":"mushrooms","meaning":"菇類","examples":[{"en":"Mushrooms are one of the foods associated with umami.","zh":"菇類是與鮮味相關的食物之一。"},{"en":"Mushrooms are fungi often used as food because they have a soft texture and savoury taste.","zh":"mushrooms 是常被用作食物的真菌，因為它們有柔軟口感和鹹香味道。"},{"en":"Adding mushrooms to soup can make the soup taste richer.","zh":"在湯中加入菇類可以令湯味更濃郁。"},{"en":"If mushrooms are not cooked properly, some types may be unsafe to eat.","zh":"如果菇類沒有妥善烹調，某些種類可能不安全。"},{"en":"The word refers to a common food, but wild mushrooms must be identified carefully.","zh":"這個字指常見食物，但野生菇類必須小心辨認。"}],"source":"135 - The sense of flavour.pdf","sourcePage":3},{"front":"seaweed","meaning":"海藻","examples":[{"en":"Seaweed can produce a rich umami taste.","zh":"海藻可以產生濃郁鮮味。"},{"en":"Seaweed is a plant-like organism that grows in the sea and is often used as food.","zh":"seaweed 是生長在海中的植物狀生物，常被用作食物。"},{"en":"Sushi, soup, and snacks may all contain seaweed.","zh":"壽司、湯和零食都可能含有海藻。"},{"en":"If seaweed is dried and added to broth, it can make the flavour deeper.","zh":"如果海藻被曬乾並加入高湯，可以令味道更深厚。"},{"en":"The word is common in food, nutrition, and marine biology contexts.","zh":"這個字常見於食物、營養和海洋生物語境。"}],"source":"135 - The sense of flavour.pdf","sourcePage":3},{"front":"offer a limited means of detection","meaning":"提供有限的偵測方式","examples":[{"en":"Taste buds offer a limited means of detection.","zh":"味蕾提供有限的偵測方式。"},{"en":"To offer a limited means of detection means to provide only a narrow or incomplete way to notice something.","zh":"offer a limited means of detection 指只提供狹窄或不完整的察覺方法。"},{"en":"Looking at food colour offers a limited means of detection because fresh-looking food may still be unsafe.","zh":"只看食物顏色提供有限的偵測方式，因為看似新鮮的食物仍可能不安全。"},{"en":"If taste buds offer a limited means of detection, smell must help create a fuller picture of flavour.","zh":"如果味蕾提供有限的偵測方式，嗅覺就必須幫助建立更完整的風味感覺。"},{"en":"The phrase suggests that one method helps, but cannot detect everything.","zh":"這個短語暗示一種方法有幫助，但不能偵測所有東西。"}],"source":"135 - The sense of flavour.pdf","sourcePage":3},{"front":"compared with","meaning":"與……相比","examples":[{"en":"Taste is limited compared with the human olfactory system.","zh":"與人類嗅覺系統相比，味覺是有限的。"},{"en":"Compared with means judged against another thing to show similarity or difference.","zh":"compared with 指與另一事物比較，以顯示相似或差異。"},{"en":"Compared with buses, trains may carry more passengers at one time.","zh":"與巴士相比，火車一次可能運載更多乘客。"},{"en":"If a small phone battery is compared with a laptop battery, its capacity may seem low.","zh":"如果小型手機電池與手提電腦電池相比，其容量可能顯得較低。"},{"en":"The phrase is useful when making a clear comparison.","zh":"這個短語適合用於作清楚比較時。"}],"source":"135 - The sense of flavour.pdf","sourcePage":3},{"front":"the human olfactory system","meaning":"人類嗅覺系統","examples":[{"en":"The human olfactory system can detect thousands of aromas.","zh":"人類嗅覺系統可以偵測數以千計的香氣。"},{"en":"The human olfactory system is the part of the body that allows people to smell.","zh":"the human olfactory system 是讓人能夠聞到氣味的身體系統。"},{"en":"The human olfactory system helps us notice smoke, perfume, food, and spoiled milk.","zh":"人類嗅覺系統幫助我們察覺煙味、香水、食物和變壞牛奶。"},{"en":"If the human olfactory system is blocked by a cold, flavour may become much weaker.","zh":"如果人類嗅覺系統因感冒而受阻，風味可能變得弱很多。"},{"en":"The phrase is a scientific way to refer to the human sense of smell.","zh":"這個短語是指人類嗅覺的科學說法。"}],"source":"135 - The sense of flavour.pdf","sourcePage":3},{"front":"perceive thousands of","meaning":"感知數以千計的……","examples":[{"en":"The nose can perceive thousands of different chemical aromas.","zh":"鼻子可以感知數以千計不同的化學氣味。"},{"en":"To perceive thousands of something means to notice or sense a very large number of them.","zh":"perceive thousands of 某物，指察覺或感受到非常大量的該物。"},{"en":"A trained musician may perceive thousands of small differences in sound.","zh":"受訓音樂人可能感知數以千計聲音上的細微差異。"},{"en":"If the nose can perceive thousands of aromas, smell can add great detail to flavour.","zh":"如果鼻子能感知數以千計的香氣，嗅覺就能為風味加入大量細節。"},{"en":"The phrase emphasises a wide range of things that can be detected.","zh":"這個短語強調可被偵測事物的範圍很廣。"}],"source":"135 - The sense of flavour.pdf","sourcePage":3},{"front":"chemical aromas","meaning":"化學氣味","examples":[{"en":"The olfactory system detects many chemical aromas.","zh":"嗅覺系統偵測許多化學氣味。"},{"en":"Chemical aromas are smells produced by chemical substances in food, flowers, smoke, or other materials.","zh":"chemical aromas 是由食物、花、煙或其他材料中的化學物質產生的氣味。"},{"en":"Fresh coffee releases chemical aromas that many people recognise immediately.","zh":"新鮮咖啡釋放出許多人立即能辨認的化學氣味。"},{"en":"If chemical aromas from cleaning products are too strong, people may open windows.","zh":"如果清潔產品的化學氣味太強，人們可能打開窗戶。"},{"en":"The phrase explains smell in a scientific way.","zh":"這個短語以科學方式解釋氣味。"}],"source":"135 - The sense of flavour.pdf","sourcePage":3},{"front":"indeed","meaning":"事實上","examples":[{"en":"Indeed, flavour is mainly created by smell.","zh":"事實上，風味主要由嗅覺創造。"},{"en":"Indeed means in fact, and it often strengthens or confirms the previous point.","zh":"indeed 指事實上，常用來加強或確認前面的意思。"},{"en":"The exam was difficult; indeed, many students could not finish it.","zh":"這次考試很難；事實上，許多學生都未能完成。"},{"en":"Smell affects flavour strongly; indeed, food tastes weaker when the nose is blocked.","zh":"嗅覺強烈影響風味；事實上，鼻塞時食物味道會變弱。"},{"en":"The word is useful when adding stronger evidence or emphasis.","zh":"這個字適合用來加入更強證據或強調。"}],"source":"135 - The sense of flavour.pdf","sourcePage":3},{"front":"primarily the smell of","meaning":"主要是……的氣味","examples":[{"en":"Flavour is primarily the smell of gases released in the mouth.","zh":"風味主要是口中釋放出的氣體的氣味。"},{"en":"Primarily the smell of something means mainly created by or based on that smell.","zh":"primarily the smell of 某物，指主要由該氣味創造或建立。"},{"en":"The appeal of fresh bread is primarily the smell of warm flour and butter.","zh":"新鮮麵包的吸引力主要是溫暖麵粉和牛油的氣味。"},{"en":"If flavour is primarily the smell of food gases, a blocked nose changes how food tastes.","zh":"如果風味主要是食物氣體的氣味，鼻塞就會改變食物味道。"},{"en":"The phrase shows the main source of an experience.","zh":"這個短語顯示某種體驗的主要來源。"}],"source":"135 - The sense of flavour.pdf","sourcePage":3},{"front":"be released by","meaning":"由……釋放出來","examples":[{"en":"Gases are released by the chemicals in food.","zh":"氣體由食物中的化學物質釋放出來。"},{"en":"To be released by something means to be given off or let out by it.","zh":"be released by 某物，意思是由它散發、排出或釋放。"},{"en":"Steam is released by hot soup when it is served.","zh":"熱湯上桌時會釋放蒸氣。"},{"en":"If strong smells are released by paint, workers should keep the room ventilated.","zh":"如果油漆釋放強烈氣味，工人應保持房間通風。"},{"en":"The phrase explains where something comes from or what sends it out.","zh":"這個短語解釋某物來自哪裏或由甚麼釋放。"}],"source":"135 - The sense of flavour.pdf","sourcePage":3},{"front":"chemicals in food","meaning":"食物中的化學物質","examples":[{"en":"Chemicals in food release gases that create flavour.","zh":"食物中的化學物質釋放出創造風味的氣體。"},{"en":"Chemicals in food are natural or added substances that affect taste, smell, colour, or nutrition.","zh":"chemicals in food 是影響味道、氣味、顏色或營養的天然或添加物質。"},{"en":"The chemicals in onions can make people’s eyes water when they are cut.","zh":"洋蔥中的化學物質在被切開時可令人流眼水。"},{"en":"If chemicals in food change during cooking, the smell and flavour may become richer.","zh":"如果食物中的化學物質在烹調時改變，氣味和風味可能變得更濃郁。"},{"en":"The phrase is scientific, but it can refer to ordinary substances found in food.","zh":"這個短語較科學，但可以指食物中常見的普通物質。"}],"source":"135 - The sense of flavour.pdf","sourcePage":3},{"front":"be responsible for","meaning":"是……的原因；對……負責","examples":[{"en":"The aroma of food can be responsible for most of its flavour.","zh":"食物香氣可以是其大部分風味的原因。"},{"en":"To be responsible for something means to be the cause of it or have control over it.","zh":"be responsible for 某事，意思是造成某事或掌管某事。"},{"en":"Poor sleep may be responsible for a student’s lack of concentration.","zh":"睡眠不足可能是學生缺乏專注力的原因。"},{"en":"If smell is responsible for much of flavour, losing smell changes eating greatly.","zh":"如果嗅覺是大部分風味的原因，失去嗅覺會大大改變進食體驗。"},{"en":"The phrase can describe cause, duty, or control depending on context.","zh":"這個短語可按語境表示原因、責任或控制。"}],"source":"135 - The sense of flavour.pdf","sourcePage":4},{"front":"as much as 90% of","meaning":"高達百分之九十的……","examples":[{"en":"Aroma can be responsible for as much as 90% of flavour.","zh":"香氣可以構成高達百分之九十的風味。"},{"en":"As much as 90% of something means up to 90%, which is a very large share.","zh":"as much as 90% of 某物，指高達百分之九十，是很大的比例。"},{"en":"In some homes, rent can take as much as 50% of monthly income.","zh":"在一些家庭中，租金可以佔每月收入高達百分之五十。"},{"en":"If smell creates as much as 90% of flavour, taste buds play a smaller role than many people think.","zh":"如果嗅覺創造高達百分之九十的風味，味蕾的角色就比許多人想像中小。"},{"en":"The phrase emphasises that the amount may be surprisingly high.","zh":"這個短語強調數量可能高得令人驚訝。"}],"source":"135 - The sense of flavour.pdf","sourcePage":4},{"front":"the act of drinking","meaning":"飲用這個動作","examples":[{"en":"The act of drinking a substance releases volatile gases.","zh":"飲用某種物質這個動作會釋放揮發性氣體。"},{"en":"The act of drinking means the physical action of taking liquid into the mouth and swallowing it.","zh":"the act of drinking 指把液體送入口中並吞下的身體動作。"},{"en":"The act of drinking hot tea can release steam and aroma into the nose.","zh":"飲用熱茶這個動作可以把蒸氣和香氣釋放到鼻子中。"},{"en":"If the act of drinking releases smell molecules, drinks can have flavour before they are swallowed.","zh":"如果飲用這個動作釋放氣味分子，飲品在吞下前已可有風味。"},{"en":"The phrase focuses on the action itself, not the drink alone.","zh":"這個短語重點在於動作本身，而不只是飲品。"}],"source":"135 - The sense of flavour.pdf","sourcePage":4},{"front":"sucking or chewing","meaning":"吸吮或咀嚼","examples":[{"en":"Sucking or chewing food releases volatile gases.","zh":"吸吮或咀嚼食物會釋放揮發性氣體。"},{"en":"Sucking or chewing means using the mouth to draw out liquid or break food into smaller pieces.","zh":"sucking or chewing 指用口吸出液體或把食物咬成較小部分。"},{"en":"A child sucking or chewing a sweet can smell its flavour more strongly.","zh":"孩子吸吮或咀嚼糖果時，可能更強烈聞到其風味。"},{"en":"When sucking or chewing releases gases, those gases can travel to smell receptors.","zh":"當吸吮或咀嚼釋放氣體，那些氣體可以到達嗅覺受體。"},{"en":"The phrase describes mouth actions that help create flavour.","zh":"這個短語描述幫助創造風味的口腔動作。"}],"source":"135 - The sense of flavour.pdf","sourcePage":4},{"front":"a substance","meaning":"物質","examples":[{"en":"Chewing a substance releases gases that reach the nose.","zh":"咀嚼某種物質會釋放到達鼻子的氣體。"},{"en":"A substance is a material or matter, especially when discussing what it is made of or how it acts.","zh":"substance 是一種材料或物質，尤其用於討論其組成或作用時。"},{"en":"Sugar is a common substance used to sweeten food and drinks.","zh":"糖是常用來令食物和飲品變甜的物質。"},{"en":"If a substance smells strange, people may avoid touching or eating it.","zh":"如果某種物質聞起來奇怪，人們可能避免觸摸或食用它。"},{"en":"The word is general and can refer to food, liquid, powder, or chemical material.","zh":"這個字很概括，可以指食物、液體、粉末或化學材料。"}],"source":"135 - The sense of flavour.pdf","sourcePage":4},{"front":"volatile gases","meaning":"揮發性氣體","examples":[{"en":"Volatile gases from food travel towards the nose.","zh":"食物中的揮發性氣體向鼻子移動。"},{"en":"Volatile gases are gases that easily escape into the air and can often be smelled.","zh":"volatile gases 是容易散發到空氣中、並常可被聞到的氣體。"},{"en":"Hot coffee releases volatile gases that carry its aroma around the room.","zh":"熱咖啡釋放帶着香氣在房間中飄散的揮發性氣體。"},{"en":"If volatile gases from food cannot reach the nose, flavour may seem weaker.","zh":"如果食物中的揮發性氣體不能到達鼻子，風味可能顯得較弱。"},{"en":"The phrase is often used in scientific explanations of smell and flavour.","zh":"這個短語常用於嗅覺和風味的科學解釋中。"}],"source":"135 - The sense of flavour.pdf","sourcePage":4},{"front":"flow out of","meaning":"從……流出","examples":[{"en":"Gases flow out of the mouth and up the nostrils.","zh":"氣體從口中流出並向上進入鼻孔。"},{"en":"To flow out of somewhere means to move out smoothly from that place.","zh":"flow out of 某處，意思是從該處順暢地流出。"},{"en":"Water flowed out of the broken pipe and covered the kitchen floor.","zh":"水從破裂水管流出，覆蓋了廚房地板。"},{"en":"If smoke flows out of a room, people may notice the fire quickly.","zh":"如果煙從房間流出，人們可能很快察覺火災。"},{"en":"The phrase describes movement from inside to outside.","zh":"這個短語描述由內向外的移動。"}],"source":"135 - The sense of flavour.pdf","sourcePage":4},{"front":"up the nostrils","meaning":"向上進入鼻孔","examples":[{"en":"The gases flow up the nostrils to reach smell receptors.","zh":"氣體向上進入鼻孔，到達嗅覺受體。"},{"en":"Up the nostrils means moving upward into the openings of the nose.","zh":"up the nostrils 指向上進入鼻子的開口。"},{"en":"The smell of hot soup travels up the nostrils before the first spoonful is swallowed.","zh":"熱湯的氣味在第一口吞下前已向上進入鼻孔。"},{"en":"If dust goes up the nostrils, a person may sneeze.","zh":"如果灰塵向上進入鼻孔，人可能會打噴嚏。"},{"en":"The phrase describes the route by which smells enter the nose.","zh":"這個短語描述氣味進入鼻子的路徑。"}],"source":"135 - The sense of flavour.pdf","sourcePage":4},{"front":"passageway at the back of the mouth","meaning":"口腔後方的通道","examples":[{"en":"Gases can also travel through the passageway at the back of the mouth.","zh":"氣體也可以通過口腔後方的通道移動。"},{"en":"The passageway at the back of the mouth is the route connecting the mouth area with the nasal area.","zh":"passageway at the back of the mouth 是連接口腔區域和鼻腔區域的通道。"},{"en":"When people chew hot food, aroma can move through the passageway at the back of the mouth.","zh":"當人們咀嚼熱食時，香氣可以經口腔後方的通道移動。"},{"en":"If this passageway is blocked, flavour may seem less clear.","zh":"如果這條通道受阻，風味可能顯得不那麼清晰。"},{"en":"The phrase explains how smells from food reach the nose from inside the mouth.","zh":"這個短語解釋食物氣味如何從口腔內部到達鼻子。"}],"source":"135 - The sense of flavour.pdf","sourcePage":4},{"front":"a thin layer of","meaning":"一層薄薄的……","examples":[{"en":"The gases reach a thin layer of nerve cells.","zh":"氣體到達一層薄薄的神經細胞。"},{"en":"A thin layer of something means a very narrow covering or sheet of that material.","zh":"a thin layer of 某物，指由該材料形成的很薄覆蓋層。"},{"en":"A thin layer of butter on toast can add flavour without making it too oily.","zh":"在多士上塗一層薄薄的牛油，可以增加味道而不會太油。"},{"en":"If a thin layer of dust covers a shelf, the room has probably not been cleaned recently.","zh":"如果一層薄薄的灰塵覆蓋架子，房間可能最近沒有清潔。"},{"en":"The phrase describes a small amount spread across a surface.","zh":"這個短語描述少量物質鋪在表面上。"}],"source":"135 - The sense of flavour.pdf","sourcePage":4},{"front":"nerve cells","meaning":"神經細胞","examples":[{"en":"The olfactory epithelium is made of nerve cells.","zh":"嗅覺上皮由神經細胞組成。"},{"en":"Nerve cells are cells that send signals through the body and to the brain.","zh":"nerve cells 是在身體和大腦之間傳送訊號的細胞。"},{"en":"Nerve cells in the skin help people feel heat, cold, and pain.","zh":"皮膚中的神經細胞幫助人感覺熱、冷和痛楚。"},{"en":"If nerve cells are damaged, the body may not send messages properly.","zh":"如果神經細胞受損，身體可能無法正常傳送訊息。"},{"en":"The phrase is common in biology and health topics.","zh":"這個短語常見於生物學和健康主題。"}],"source":"135 - The sense of flavour.pdf","sourcePage":4},{"front":"olfactory epithelium","meaning":"嗅覺上皮","examples":[{"en":"The olfactory epithelium receives smell signals.","zh":"嗅覺上皮接收氣味訊號。"},{"en":"The olfactory epithelium is a thin tissue in the nose that contains smell-sensing nerve cells.","zh":"olfactory epithelium 是鼻子內含有嗅覺神經細胞的一層薄組織。"},{"en":"Scientists study the olfactory epithelium to understand how humans detect aromas.","zh":"科學家研究嗅覺上皮，以了解人類如何偵測香氣。"},{"en":"If the olfactory epithelium is damaged, a person’s sense of smell may become weaker.","zh":"如果嗅覺上皮受損，人的嗅覺可能變弱。"},{"en":"The phrase is technical, but it simply refers to tissue involved in smelling.","zh":"這個短語較技術性，但簡單來說是與嗅覺有關的組織。"}],"source":"135 - The sense of flavour.pdf","sourcePage":5},{"front":"located at","meaning":"位於","examples":[{"en":"The olfactory epithelium is located at the base of the nose.","zh":"嗅覺上皮位於鼻子的底部。"},{"en":"Located at means found or positioned in a particular place.","zh":"located at 指位於或坐落於某個特定地方。"},{"en":"The school office is located at the main entrance.","zh":"學校辦公室位於正門入口。"},{"en":"If a bus stop is located at a busy road, passengers must be careful.","zh":"如果巴士站位於繁忙道路旁，乘客必須小心。"},{"en":"The phrase tells readers where something is.","zh":"這個短語告訴讀者某物在哪裏。"}],"source":"135 - The sense of flavour.pdf","sourcePage":5},{"front":"the base of the nose","meaning":"鼻子的底部","examples":[{"en":"The olfactory epithelium lies at the base of the nose.","zh":"嗅覺上皮位於鼻子的底部。"},{"en":"The base of the nose means the lower or inner area where the nose connects with nearby structures.","zh":"the base of the nose 指鼻子與附近結構相連的較低或內部位置。"},{"en":"A doctor may examine the base of the nose if a patient has breathing problems.","zh":"如果病人有呼吸問題，醫生可能檢查鼻子的底部。"},{"en":"If smell receptors are near the base of the nose, gases must travel there to be detected.","zh":"如果嗅覺受體在鼻子的底部附近，氣體必須到達那裏才可被偵測。"},{"en":"The phrase describes a specific part of the nose area.","zh":"這個短語描述鼻子區域的一個特定部分。"}],"source":"135 - The sense of flavour.pdf","sourcePage":5},{"front":"right between the eyes","meaning":"正正在兩眼之間","examples":[{"en":"The olfactory epithelium is located right between the eyes.","zh":"嗅覺上皮位於正正在兩眼之間的位置。"},{"en":"Right between the eyes means exactly in the area between the two eyes.","zh":"right between the eyes 指正正在兩隻眼之間的區域。"},{"en":"The child had a small scratch right between the eyes after falling in the playground.","zh":"孩子在操場跌倒後，兩眼之間正中位置有一條小刮痕。"},{"en":"If a pain is right between the eyes, it may feel like pressure near the nose and forehead.","zh":"如果疼痛位於正正在兩眼之間，可能像鼻子和額頭附近有壓力。"},{"en":"The word right adds precision and emphasis.","zh":"right 一字增加準確性和強調。"}],"source":"135 - The sense of flavour.pdf","sourcePage":5},{"front":"combine A with B","meaning":"將A與B結合","examples":[{"en":"The brain combines smell signals with taste signals.","zh":"大腦將嗅覺訊號與味覺訊號結合。"},{"en":"To combine A with B means to put two things together so they work as one.","zh":"combine A with B 指把兩樣東西放在一起，使它們共同發揮作用。"},{"en":"A teacher may combine reading practice with vocabulary games.","zh":"老師可能將閱讀練習與詞彙遊戲結合。"},{"en":"If cooks combine herbs with fresh vegetables, the dish may taste brighter.","zh":"如果廚師將香草與新鮮蔬菜結合，菜式味道可能更清新。"},{"en":"The phrase shows that two elements join to create a fuller result.","zh":"這個短語顯示兩個元素結合後創造更完整結果。"}],"source":"135 - The sense of flavour.pdf","sourcePage":5},{"front":"complex smell signals","meaning":"複雜的嗅覺訊號","examples":[{"en":"The brain receives complex smell signals from the nose.","zh":"大腦從鼻子接收複雜的嗅覺訊號。"},{"en":"Complex smell signals are detailed messages from the nose about many different aromas.","zh":"complex smell signals 是鼻子傳來、關於許多不同香氣的詳細訊息。"},{"en":"Coffee sends complex smell signals because it contains many aroma chemicals.","zh":"咖啡會傳送複雜的嗅覺訊號，因為它含有許多香氣化學物質。"},{"en":"If complex smell signals are blocked, food may taste simple or dull.","zh":"如果複雜的嗅覺訊號受阻，食物可能味道簡單或沉悶。"},{"en":"The phrase contrasts detailed smell information with simpler taste information.","zh":"這個短語把詳細的嗅覺資料與較簡單的味覺資料作對比。"}],"source":"135 - The sense of flavour.pdf","sourcePage":5},{"front":"simple taste signals","meaning":"簡單的味覺訊號","examples":[{"en":"The tongue sends simple taste signals to the brain.","zh":"舌頭向大腦傳送簡單的味覺訊號。"},{"en":"Simple taste signals are basic messages about tastes such as sweet, sour, bitter, or salty.","zh":"simple taste signals 是關於甜、酸、苦或鹹等基本味道的簡單訊息。"},{"en":"When you taste sugar, the tongue sends simple taste signals that tell the brain it is sweet.","zh":"當你嚐到糖，舌頭會傳送簡單的味覺訊號，告訴大腦它是甜的。"},{"en":"If simple taste signals are combined with smell, the brain can create a richer flavour experience.","zh":"如果簡單的味覺訊號與嗅覺結合，大腦可以創造更豐富的風味體驗。"},{"en":"The phrase shows that taste alone gives limited information.","zh":"這個短語顯示單靠味覺只提供有限資料。"}],"source":"135 - The sense of flavour.pdf","sourcePage":5},{"front":"assign a flavour to","meaning":"為……判定一種味道","examples":[{"en":"The brain assigns a flavour to what is in your mouth.","zh":"大腦為你口中的東西判定一種味道。"},{"en":"To assign a flavour to something means to decide what flavour it has.","zh":"assign a flavour to 某物，意思是判斷它有甚麼風味。"},{"en":"The brain may assign a strawberry flavour to a sweet red drink because of its smell.","zh":"大腦可能因為氣味而為一杯紅色甜飲判定草莓味。"},{"en":"If smell signals are confusing, the brain may assign the wrong flavour to food.","zh":"如果嗅覺訊號令人混淆，大腦可能為食物判定錯誤味道。"},{"en":"The phrase describes how the brain labels what we are eating.","zh":"這個短語描述大腦如何為我們正在吃的東西貼上味道標籤。"}],"source":"135 - The sense of flavour.pdf","sourcePage":5},{"front":"what is in your mouth","meaning":"口中的東西","examples":[{"en":"The brain decides what flavour belongs to what is in your mouth.","zh":"大腦判斷你口中的東西屬於甚麼風味。"},{"en":"What is in your mouth means the food, drink, or substance currently being eaten or tasted.","zh":"what is in your mouth 指當下正在吃或品嚐的食物、飲品或物質。"},{"en":"If what is in your mouth is too hot, you may spit it out quickly.","zh":"如果口中的東西太熱，你可能很快吐出來。"},{"en":"Smell helps the brain understand what is in your mouth more accurately.","zh":"嗅覺幫助大腦更準確理解口中的東西。"},{"en":"The phrase is simple and refers to the thing being tasted at that moment.","zh":"這個短語很簡單，指正在被品嚐的東西。"}],"source":"135 - The sense of flavour.pdf","sourcePage":5},{"front":"decide if","meaning":"判斷是否","examples":[{"en":"The brain decides if the food is something you want to eat.","zh":"大腦判斷食物是否是你想吃的東西。"},{"en":"Decide if means judge whether something is true, suitable, or wanted.","zh":"decide if 指判斷某事是否真實、合適或想要。"},{"en":"A student must decide if an answer is supported by the passage.","zh":"學生必須判斷答案是否受文章支持。"},{"en":"If food smells strange, people may decide if it is still safe before eating.","zh":"如果食物聞起來奇怪，人們可能在食用前判斷它是否仍然安全。"},{"en":"The phrase introduces a yes-or-no judgement.","zh":"這個短語引出是或否的判斷。"}],"source":"135 - The sense of flavour.pdf","sourcePage":5},{"front":"reject bitter ones","meaning":"拒絕苦味的東西","examples":[{"en":"Babies like sweet tastes and reject bitter ones.","zh":"嬰兒喜歡甜味，並拒絕苦味的東西。"},{"en":"To reject bitter ones means to refuse or dislike foods or tastes that are bitter.","zh":"reject bitter ones 指拒絕或不喜歡苦味食物或味道。"},{"en":"A baby may reject bitter medicine even if it is mixed with water.","zh":"嬰兒可能拒絕苦味藥物，即使它已混入水中。"},{"en":"If early humans rejected bitter ones, they may have avoided some poisonous plants.","zh":"如果早期人類拒絕苦味的東西，他們可能避開了一些有毒植物。"},{"en":"The phrase refers back to bitter tastes or bitter foods already mentioned.","zh":"這個短語指回前文已提及的苦味或苦味食物。"}],"source":"135 - The sense of flavour.pdf","sourcePage":5},{"front":"place flavours in","meaning":"把味道放進……","examples":[{"en":"Scientists placed flavours in infants’ mouths to observe reactions.","zh":"科學家把味道放進嬰兒口中，以觀察反應。"},{"en":"To place flavours in someone’s mouth means to put small amounts of tasting substances there.","zh":"place flavours in 某人口中，指把少量可品嚐物質放到那裏。"},{"en":"A researcher may place flavours in volunteers’ mouths to test how they react.","zh":"研究人員可能把味道放進志願者口中，以測試他們的反應。"},{"en":"If scientists place flavours in babies’ mouths, facial expressions can show likes and dislikes.","zh":"如果科學家把味道放進嬰兒口中，面部表情可以顯示喜好。"},{"en":"The phrase describes a controlled action in an experiment.","zh":"這個短語描述實驗中的受控制動作。"}],"source":"135 - The sense of flavour.pdf","sourcePage":6},{"front":"infants’ mouths","meaning":"嬰兒口中","examples":[{"en":"Researchers placed different flavours in infants’ mouths.","zh":"研究人員把不同味道放進嬰兒口中。"},{"en":"Infants’ mouths means the mouths of very young babies.","zh":"infants’ mouths 指非常年幼嬰兒的口中。"},{"en":"Doctors check infants’ mouths to see whether feeding is comfortable.","zh":"醫生檢查嬰兒口腔，以了解餵食是否舒適。"},{"en":"If food is placed in infants’ mouths too early, it may be unsafe.","zh":"如果太早把食物放進嬰兒口中，可能不安全。"},{"en":"The phrase is specific to babies, not older children.","zh":"這個短語特指嬰兒，而不是較年長兒童。"}],"source":"135 - The sense of flavour.pdf","sourcePage":6},{"front":"record facial reactions","meaning":"記錄面部反應","examples":[{"en":"Scientists recorded babies’ facial reactions to different tastes.","zh":"科學家記錄嬰兒對不同味道的面部反應。"},{"en":"To record facial reactions means to observe and note how someone’s face changes in response.","zh":"record facial reactions 指觀察並記下某人的面部如何因反應而改變。"},{"en":"Teachers may record facial reactions during a tasting activity to see which foods children like.","zh":"老師可能在試食活動中記錄面部反應，以了解孩子喜歡哪些食物。"},{"en":"If babies smile or frown, researchers can record facial reactions as evidence of preference.","zh":"如果嬰兒微笑或皺眉，研究人員可以把面部反應記錄為喜好的證據。"},{"en":"The phrase is useful in experiments where people cannot explain feelings in words.","zh":"這個短語適用於人們不能用語言解釋感受的實驗。"}],"source":"135 - The sense of flavour.pdf","sourcePage":6},{"front":"food preferences","meaning":"食物喜好","examples":[{"en":"A person’s food preferences are formed early in life.","zh":"一個人的食物喜好在人生早期形成。"},{"en":"Food preferences are the foods and flavours a person likes or dislikes.","zh":"food preferences 是一個人喜歡或不喜歡的食物和味道。"},{"en":"A child’s food preferences may include sweet fruit, plain rice, or spicy noodles.","zh":"孩子的食物喜好可能包括甜水果、白飯或辣麵。"},{"en":"If parents often cook vegetables, children’s food preferences may become healthier.","zh":"如果父母經常煮蔬菜，孩子的食物喜好可能變得更健康。"},{"en":"The phrase describes personal choices in eating.","zh":"這個短語描述飲食上的個人選擇。"}],"source":"135 - The sense of flavour.pdf","sourcePage":6},{"front":"like one’s personality","meaning":"就像某人的性格一樣","examples":[{"en":"A person’s food preferences, like their personality, develop over time.","zh":"一個人的食物喜好，就像其性格一樣，會隨時間發展。"},{"en":"Like one’s personality means in a similar way to a person’s character or habits.","zh":"like one’s personality 指像一個人的性格或習慣那樣。"},{"en":"Food habits, like one’s personality, can change through family, friends, and experience.","zh":"飲食習慣就像人的性格一樣，可以受家庭、朋友和經驗改變。"},{"en":"If taste develops like one’s personality, early surroundings matter a lot.","zh":"如果口味像性格一樣發展，早期環境就非常重要。"},{"en":"The phrase compares food preference development with personal development.","zh":"這個短語把食物喜好的發展與個人發展作比較。"}],"source":"135 - The sense of flavour.pdf","sourcePage":6},{"front":"be formed during","meaning":"在……期間形成","examples":[{"en":"Food preferences are formed during the first few years of life.","zh":"食物喜好在人生最初幾年期間形成。"},{"en":"To be formed during a period means to develop or take shape in that time.","zh":"be formed during 某時期，指在那段時間發展或成形。"},{"en":"Study habits are often formed during the first year of secondary school.","zh":"學習習慣常在中學第一年期間形成。"},{"en":"If healthy eating habits are formed during childhood, they may last into adulthood.","zh":"如果健康飲食習慣在童年期間形成，它們可能延續到成年。"},{"en":"The phrase connects development with a specific time period.","zh":"這個短語把發展與特定時間段連繫起來。"}],"source":"135 - The sense of flavour.pdf","sourcePage":6},{"front":"the first few years of life","meaning":"人生最初幾年","examples":[{"en":"Many food preferences develop in the first few years of life.","zh":"許多食物喜好在人生最初幾年發展出來。"},{"en":"The first few years of life means the early years after a person is born.","zh":"the first few years of life 指一個人出生後的早期幾年。"},{"en":"Language, trust, and eating habits can grow quickly in the first few years of life.","zh":"語言、信任和飲食習慣都可以在人生最初幾年快速發展。"},{"en":"If children try many healthy foods in the first few years of life, they may accept them more easily later.","zh":"如果孩子在人生最初幾年嘗試許多健康食物，他們日後可能更容易接受。"},{"en":"The phrase highlights early childhood as an important period.","zh":"這個短語強調幼兒期是一個重要階段。"}],"source":"135 - The sense of flavour.pdf","sourcePage":6},{"front":"through a process of socialisation","meaning":"透過社會化過程","examples":[{"en":"Children develop food preferences through a process of socialisation.","zh":"兒童透過社會化過程形成食物喜好。"},{"en":"Through a process of socialisation means by learning from family, friends, culture, and social habits.","zh":"through a process of socialisation 指透過家庭、朋友、文化和社會習慣學習。"},{"en":"Children learn table manners through a process of socialisation at home and school.","zh":"孩子在家庭和學校透過社會化過程學會餐桌禮儀。"},{"en":"If toddlers see adults enjoying vegetables, they may accept vegetables through a process of socialisation.","zh":"如果幼兒看見成年人享受蔬菜，他們可能透過社會化過程接受蔬菜。"},{"en":"The phrase explains learning that happens by living with other people.","zh":"這個短語解釋與他人共同生活時發生的學習。"}],"source":"135 - The sense of flavour.pdf","sourcePage":6},{"front":"toddlers","meaning":"幼兒","examples":[{"en":"Toddlers can learn to enjoy the food eaten by people around them.","zh":"幼兒可以學會享受身邊的人所吃的食物。"},{"en":"Toddlers are very young children who are learning to walk and speak.","zh":"toddlers 是正在學走路和說話的非常年幼兒童。"},{"en":"Toddlers often copy adults when they eat, talk, or play.","zh":"幼兒在吃飯、說話或玩耍時常模仿成年人。"},{"en":"If toddlers see parents eating fruit happily, they may want to try it too.","zh":"如果幼兒看見父母開心吃水果，他們也可能想嘗試。"},{"en":"The word usually refers to children around one to three years old.","zh":"這個字通常指約一至三歲的兒童。"}],"source":"135 - The sense of flavour.pdf","sourcePage":6},{"front":"learn to enjoy","meaning":"學會享受","examples":[{"en":"Children can learn to enjoy spicy food.","zh":"兒童可以學會享受辛辣食物。"},{"en":"To learn to enjoy something means to gradually begin liking it through experience or practice.","zh":"learn to enjoy 某事，意思是透過經驗或練習逐漸開始喜歡它。"},{"en":"A child may learn to enjoy reading when stories are connected to their interests.","zh":"當故事與孩子興趣相連，他可能學會享受閱讀。"},{"en":"If children try vegetables many times, they may learn to enjoy the taste.","zh":"如果孩子多次嘗試蔬菜，他們可能學會享受那種味道。"},{"en":"The phrase shows that liking something can be developed, not just born naturally.","zh":"這個短語顯示喜歡某事可以被培養，而不只是天生。"}],"source":"135 - The sense of flavour.pdf","sourcePage":6},{"front":"hot and spicy food","meaning":"辛辣食物","examples":[{"en":"Some toddlers learn to enjoy hot and spicy food.","zh":"一些幼兒學會享受辛辣食物。"},{"en":"Hot and spicy food is food that creates a burning or warming feeling because of chilli or spices.","zh":"hot and spicy food 是因辣椒或香料而在口中產生灼熱或溫熱感的食物。"},{"en":"Curry, chilli noodles, and spicy soup are examples of hot and spicy food.","zh":"咖喱、辣麵和辣湯都是辛辣食物的例子。"},{"en":"If children grow up eating hot and spicy food, they may accept strong flavours more easily.","zh":"如果孩子從小吃辛辣食物，他們可能更容易接受強烈味道。"},{"en":"The phrase describes food that feels hot in the mouth, not food temperature.","zh":"這個短語描述在口中感到辣的食物，而不是食物溫度。"}],"source":"135 - The sense of flavour.pdf","sourcePage":6},{"front":"bland health food","meaning":"味道清淡的健康食品","examples":[{"en":"Children may learn to enjoy bland health food.","zh":"兒童可能學會享受味道清淡的健康食品。"},{"en":"Bland health food is healthy food with a mild taste and little strong seasoning.","zh":"bland health food 是味道溫和、調味不重的健康食品。"},{"en":"Plain oats, steamed vegetables, and unsalted soup can seem like bland health food.","zh":"原味燕麥、蒸蔬菜和無鹽湯可能像味道清淡的健康食品。"},{"en":"If families serve bland health food often, children may accept simple flavours.","zh":"如果家庭經常提供味道清淡的健康食品，孩子可能接受簡單味道。"},{"en":"The phrase can sound slightly negative because the food is healthy but not exciting.","zh":"這個短語可帶少許負面意思，因為食物健康但不刺激。"}],"source":"135 - The sense of flavour.pdf","sourcePage":7},{"front":"fast food","meaning":"快餐","examples":[{"en":"Children’s attitudes towards fast food can be shaped by their surroundings.","zh":"兒童對快餐的態度可受周圍環境塑造。"},{"en":"Fast food is food prepared and served quickly, often by restaurants or chains.","zh":"fast food 是快速準備和供應的食物，常由餐廳或連鎖店提供。"},{"en":"Burgers, fried chicken, and chips are common examples of fast food.","zh":"漢堡、炸雞和薯條都是常見快餐例子。"},{"en":"If children eat fast food every day, they may become used to salty and fatty flavours.","zh":"如果孩子每天吃快餐，他們可能習慣鹹和油膩的味道。"},{"en":"The phrase refers to convenience food, not necessarily all cheap food.","zh":"這個短語指方便快捷的食物，不一定指所有便宜食物。"}],"source":"135 - The sense of flavour.pdf","sourcePage":7},{"front":"depending upon","meaning":"取決於","examples":[{"en":"Food preferences develop depending upon what people around children eat.","zh":"食物喜好會根據孩子身邊的人吃甚麼而發展。"},{"en":"Depending upon means being affected or decided by a particular factor.","zh":"depending upon 指受某個因素影響或由其決定。"},{"en":"A student’s travel time changes depending upon where they live.","zh":"學生的交通時間取決於他們住在哪裏。"},{"en":"If children’s tastes develop depending upon family meals, parents influence food habits strongly.","zh":"如果孩子的口味取決於家庭膳食，父母就強烈影響飲食習慣。"},{"en":"The phrase is similar to depending on.","zh":"這個短語與 depending on 相似。"}],"source":"135 - The sense of flavour.pdf","sourcePage":7},{"front":"the people around them","meaning":"他們身邊的人","examples":[{"en":"Toddlers learn eating habits from the people around them.","zh":"幼兒從他們身邊的人學習飲食習慣。"},{"en":"The people around them means the family, friends, carers, and others they often see.","zh":"the people around them 指他們經常見到的家人、朋友、照顧者和其他人。"},{"en":"Children may learn polite words from the people around them.","zh":"孩子可能從身邊的人學會禮貌用語。"},{"en":"If the people around them eat vegetables happily, toddlers may copy that behaviour.","zh":"如果他們身邊的人開心吃蔬菜，幼兒可能模仿這種行為。"},{"en":"The phrase highlights the influence of nearby social examples.","zh":"這個短語強調附近社會榜樣的影響。"}],"source":"135 - The sense of flavour.pdf","sourcePage":7},{"front":"not fully understood","meaning":"尚未被完全理解","examples":[{"en":"The human sense of smell is still not fully understood.","zh":"人類嗅覺尚未被完全理解。"},{"en":"Not fully understood means people know some things about it but do not understand everything.","zh":"not fully understood 指人們知道其中一些事情，但未理解全部。"},{"en":"Some sleep disorders are still not fully understood by doctors.","zh":"一些睡眠障礙仍未被醫生完全理解。"},{"en":"If smell is not fully understood, scientists must continue studying how the brain processes aromas.","zh":"如果嗅覺尚未被完全理解，科學家必須繼續研究大腦如何處理香氣。"},{"en":"The phrase shows that knowledge is incomplete.","zh":"這個短語顯示知識仍不完整。"}],"source":"135 - The sense of flavour.pdf","sourcePage":7},{"front":"be greatly affected by","meaning":"深受……影響","examples":[{"en":"The sense of smell is greatly affected by expectations.","zh":"嗅覺深受預期影響。"},{"en":"To be greatly affected by something means to be strongly changed or influenced by it.","zh":"be greatly affected by 某事，意思是被它強烈改變或影響。"},{"en":"A student’s confidence can be greatly affected by a teacher’s comments.","zh":"學生的信心可以深受老師評語影響。"},{"en":"If smell is greatly affected by expectations, the same aroma may feel pleasant or unpleasant in different situations.","zh":"如果嗅覺深受預期影響，同一種香氣在不同情況下可能令人覺得愉快或不愉快。"},{"en":"The phrase shows a strong influence, not a small one.","zh":"這個短語顯示強烈影響，而不是微小影響。"}],"source":"135 - The sense of flavour.pdf","sourcePage":7},{"front":"psychological factors","meaning":"心理因素","examples":[{"en":"Psychological factors can affect how people perceive smells.","zh":"心理因素可以影響人們如何感知氣味。"},{"en":"Psychological factors are mental or emotional influences such as expectations, memories, stress, or fear.","zh":"psychological factors 是心理或情緒上的影響，例如預期、記憶、壓力或恐懼。"},{"en":"Anxiety is a psychological factor that can make small problems feel larger.","zh":"焦慮是一種心理因素，可以令小問題感覺更大。"},{"en":"If psychological factors affect smell, a labelled “fresh” scent may seem more pleasant.","zh":"如果心理因素影響嗅覺，標示為「清新」的氣味可能顯得更愉快。"},{"en":"The phrase refers to the mind’s influence on experience and behaviour.","zh":"這個短語指心智對經驗和行為的影響。"}],"source":"135 - The sense of flavour.pdf","sourcePage":7},{"front":"expectations","meaning":"期望；預期","examples":[{"en":"Expectations can change how people experience smell.","zh":"預期可以改變人們如何體驗氣味。"},{"en":"Expectations are beliefs about what will happen or what something will be like.","zh":"expectations 是關於會發生甚麼或某物會如何的信念。"},{"en":"If a restaurant looks expensive, expectations may make the food seem better.","zh":"如果餐廳看起來昂貴，期望可能令食物顯得更好。"},{"en":"When expectations are high, a normal smell may seem disappointing.","zh":"當期望很高時，普通氣味可能顯得令人失望。"},{"en":"The word is important because what people expect can change what they notice.","zh":"這個字重要，因為人們預期甚麼會改變他們注意到甚麼。"}],"source":"135 - The sense of flavour.pdf","sourcePage":7},{"front":"filter out","meaning":"過濾掉","examples":[{"en":"The mind filters out most chemical aromas around us.","zh":"心智會過濾掉我們身邊大部分化學氣味。"},{"en":"To filter out something means to remove, block, or ignore it so it does not receive attention.","zh":"filter out 某物，意思是移除、阻隔或忽略它，使它不受注意。"},{"en":"Noise-cancelling headphones filter out traffic sounds during study.","zh":"降噪耳機在學習時過濾掉交通聲。"},{"en":"If the brain did not filter out familiar smells, everyday life would feel overwhelming.","zh":"如果大腦不過濾掉熟悉氣味，日常生活會令人難以承受。"},{"en":"The phrase can describe physical filtering or mental ignoring.","zh":"這個短語可描述實體過濾或心理上的忽略。"}],"source":"135 - The sense of flavour.pdf","sourcePage":7},{"front":"the overwhelming majority of","meaning":"絕大多數的……","examples":[{"en":"The mind ignores the overwhelming majority of surrounding aromas.","zh":"心智會忽略周圍絕大多數的香氣。"},{"en":"The overwhelming majority of something means almost all of it.","zh":"the overwhelming majority of 某物，指幾乎全部。"},{"en":"The overwhelming majority of students arrived on time for the exam.","zh":"絕大多數學生準時到達考試場地。"},{"en":"If the brain ignores the overwhelming majority of smells, only important aromas reach awareness.","zh":"如果大腦忽略絕大多數氣味，只有重要香氣會進入意識。"},{"en":"The phrase strongly emphasises that the number or share is very large.","zh":"這個短語強烈強調數量或比例非常大。"}],"source":"135 - The sense of flavour.pdf","sourcePage":7},{"front":"surround us","meaning":"圍繞着我們","examples":[{"en":"Many chemical aromas surround us every day.","zh":"許多化學氣味每天圍繞着我們。"},{"en":"To surround us means to be all around us on many sides.","zh":"surround us 指在我們周圍多個方向存在。"},{"en":"Traffic noise can surround us in a busy city street.","zh":"在繁忙城市街道上，交通噪音可能圍繞着我們。"},{"en":"If smells surround us constantly, the brain must choose which ones to notice.","zh":"如果氣味不斷圍繞着我們，大腦必須選擇注意哪些。"},{"en":"The phrase describes things present in our environment.","zh":"這個短語描述存在於我們環境中的事物。"}],"source":"135 - The sense of flavour.pdf","sourcePage":7},{"front":"focus intently on","meaning":"集中注意於","examples":[{"en":"The mind focuses intently on some smells and ignores others.","zh":"心智會集中注意於某些氣味並忽略其他氣味。"},{"en":"To focus intently on something means to give it strong and careful attention.","zh":"focus intently on 某事，意思是非常專注而仔細地留意它。"},{"en":"A student may focus intently on a difficult maths problem before answering.","zh":"學生可能在回答前集中注意於一道困難數學題。"},{"en":"If the mind focuses intently on smoke, it can warn us about danger quickly.","zh":"如果心智集中注意於煙味，它可以迅速警告我們危險。"},{"en":"The phrase suggests deep concentration, not casual noticing.","zh":"這個短語暗示深入專注，而不是隨便注意到。"}],"source":"135 - The sense of flavour.pdf","sourcePage":8},{"front":"ignoring others","meaning":"忽略其他","examples":[{"en":"The mind notices some aromas while ignoring others.","zh":"心智注意到某些香氣，同時忽略其他香氣。"},{"en":"Ignoring others means paying no attention to the other things or people present.","zh":"ignoring others 指不理會其他存在的事物或人。"},{"en":"A child may listen to the teacher while ignoring others who are talking.","zh":"孩子可能聽老師說話，同時忽略其他正在說話的人。"},{"en":"If the brain notices food smells while ignoring others, eating becomes easier to manage.","zh":"如果大腦注意食物氣味而忽略其他氣味，進食體驗會較易處理。"},{"en":"The phrase shows selective attention.","zh":"這個短語顯示選擇性注意。"}],"source":"135 - The sense of flavour.pdf","sourcePage":8},{"front":"grow accustomed to","meaning":"習慣於","examples":[{"en":"People can grow accustomed to bad smells.","zh":"人們可以習慣於難聞氣味。"},{"en":"To grow accustomed to something means to become used to it over time.","zh":"grow accustomed to 某事，意思是隨時間逐漸習慣它。"},{"en":"New students may grow accustomed to a long bus journey after a few weeks.","zh":"新學生幾星期後可能習慣長途巴士旅程。"},{"en":"If workers grow accustomed to a smell in a factory, they may stop noticing it.","zh":"如果工人習慣於工廠中的氣味，他們可能停止注意到它。"},{"en":"The phrase describes gradual familiarity.","zh":"這個短語描述逐漸熟悉。"}],"source":"135 - The sense of flavour.pdf","sourcePage":8},{"front":"bad smells","meaning":"難聞氣味","examples":[{"en":"People may stop noticing bad smells after a while.","zh":"人們過了一段時間後可能不再注意到難聞氣味。"},{"en":"Bad smells are unpleasant odours that people usually dislike.","zh":"bad smells 是人們通常不喜歡的難聞氣味。"},{"en":"Rubbish bins, blocked drains, and spoiled food can produce bad smells.","zh":"垃圾桶、堵塞的排水渠和變壞食物都可以產生難聞氣味。"},{"en":"If bad smells remain in a classroom, students may find it hard to concentrate.","zh":"如果難聞氣味留在課室中，學生可能難以集中精神。"},{"en":"The phrase is simple and common in daily life.","zh":"這個短語簡單，日常生活中常用。"}],"source":"135 - The sense of flavour.pdf","sourcePage":8},{"front":"good smells","meaning":"好聞氣味","examples":[{"en":"People can also grow accustomed to good smells.","zh":"人們也可以習慣於好聞氣味。"},{"en":"Good smells are pleasant odours that people usually enjoy.","zh":"good smells 是人們通常喜歡的愉快氣味。"},{"en":"Fresh bread, flowers, and clean laundry often have good smells.","zh":"新鮮麵包、花和乾淨衣物常有好聞氣味。"},{"en":"If you stay in a bakery all day, you may stop noticing its good smells.","zh":"如果你整天留在麵包店，可能停止注意到那裏的好聞氣味。"},{"en":"The phrase contrasts pleasant odours with bad smells.","zh":"這個短語把愉快氣味與難聞氣味作對比。"}],"source":"135 - The sense of flavour.pdf","sourcePage":8},{"front":"stop noticing","meaning":"停止注意到","examples":[{"en":"People stop noticing smells that once seemed strong.","zh":"人們會停止注意到曾經顯得強烈的氣味。"},{"en":"To stop noticing something means to no longer pay attention to it or be aware of it.","zh":"stop noticing 某事，意思是不再留意或察覺它。"},{"en":"People living near a busy road may stop noticing traffic noise.","zh":"住在繁忙道路旁的人可能停止注意到交通噪音。"},{"en":"If a smell is always present, the brain may stop noticing it to avoid overload.","zh":"如果一種氣味一直存在，大腦可能停止注意到它，以避免負荷過重。"},{"en":"The phrase shows that awareness can fade over time.","zh":"這個短語顯示意識會隨時間減弱。"}],"source":"135 - The sense of flavour.pdf","sourcePage":8},{"front":"seem overpowering","meaning":"顯得極其強烈；令人難以承受","examples":[{"en":"A smell that once seemed overpowering may later become unnoticeable.","zh":"曾經顯得極其強烈的氣味，後來可能變得不明顯。"},{"en":"To seem overpowering means to feel extremely strong and difficult to ignore or bear.","zh":"seem overpowering 指感覺極其強烈，難以忽視或承受。"},{"en":"The smell of fresh paint may seem overpowering in a closed room.","zh":"在密閉房間中，新油漆味可能顯得極其強烈。"},{"en":"If perfume seems overpowering, people nearby may feel uncomfortable.","zh":"如果香水令人難以承受，附近的人可能感到不舒服。"},{"en":"The phrase describes a strong sensory experience that can dominate attention.","zh":"這個短語描述強烈到主導注意力的感官經驗。"}],"source":"135 - The sense of flavour.pdf","sourcePage":8},{"front":"aroma and memory","meaning":"香氣與記憶","examples":[{"en":"Aroma and memory are closely connected.","zh":"香氣與記憶密切相關。"},{"en":"Aroma and memory means the relationship between smells and remembered experiences.","zh":"aroma and memory 指氣味與已記住經驗之間的關係。"},{"en":"The smell of a school lunch can connect aroma and memory by reminding adults of childhood.","zh":"學校午餐的氣味可以把香氣與記憶連繫起來，令成年人想起童年。"},{"en":"If a perfume brings back a person’s face, aroma and memory are working together.","zh":"如果一種香水令人想起某人的面孔，香氣與記憶就在共同作用。"},{"en":"The phrase highlights how smells can unlock past moments.","zh":"這個短語強調氣味能打開過去時刻。"}],"source":"135 - The sense of flavour.pdf","sourcePage":8},{"front":"be inextricably linked","meaning":"密不可分","examples":[{"en":"Aroma and memory are inextricably linked.","zh":"香氣與記憶密不可分。"},{"en":"To be inextricably linked means to be connected so closely that they cannot easily be separated.","zh":"be inextricably linked 指兩者緊密相連，難以分開。"},{"en":"Sleep and concentration are inextricably linked for many students.","zh":"對許多學生來說，睡眠和專注力密不可分。"},{"en":"If smell and memory are inextricably linked, a single aroma can bring back a whole scene.","zh":"如果氣味與記憶密不可分，一種香氣就能帶回整個場景。"},{"en":"The phrase describes a very strong and deep connection.","zh":"這個短語描述非常強而深的連繫。"}],"source":"135 - The sense of flavour.pdf","sourcePage":8},{"front":"evoke a long-forgotten moment","meaning":"喚起久已遺忘的時刻","examples":[{"en":"A familiar smell can evoke a long-forgotten moment.","zh":"熟悉的氣味可以喚起久已遺忘的時刻。"},{"en":"To evoke a long-forgotten moment means to bring back a memory from the distant past.","zh":"evoke a long-forgotten moment 指喚回遙遠過去的記憶。"},{"en":"The smell of old books may evoke a long-forgotten moment in a childhood library.","zh":"舊書的氣味可能喚起童年圖書館中久已遺忘的時刻。"},{"en":"If soup smells like a grandparent’s kitchen, it may evoke a long-forgotten moment of family warmth.","zh":"如果湯聞起來像祖父母的廚房，它可能喚起家庭溫暖中久已遺忘的時刻。"},{"en":"The phrase is often used when memory returns suddenly through the senses.","zh":"這個短語常用於記憶突然透過感官回來時。"}],"source":"135 - The sense of flavour.pdf","sourcePage":8},{"front":"childhood foods","meaning":"童年食物","examples":[{"en":"The flavours of childhood foods often remain powerful in adulthood.","zh":"童年食物的風味在成年後常仍然強烈。"},{"en":"Childhood foods are foods a person often ate or strongly remembers from childhood.","zh":"childhood foods 是一個人在童年常吃或深刻記得的食物。"},{"en":"A simple bowl of noodles may be one of someone’s childhood foods.","zh":"一碗簡單麵條可能是某人的童年食物之一。"},{"en":"If childhood foods are linked with family care, adults may return to them for comfort.","zh":"如果童年食物與家庭照顧相連，成年人可能重新尋求它們作安慰。"},{"en":"The phrase connects food with early memory and emotion.","zh":"這個短語把食物與早期記憶和情感連繫起來。"}],"source":"135 - The sense of flavour.pdf","sourcePage":8},{"front":"leave an indelible mark","meaning":"留下不可磨滅的印記","examples":[{"en":"Childhood flavours can leave an indelible mark.","zh":"童年味道可以留下不可磨滅的印記。"},{"en":"To leave an indelible mark means to create a strong effect or memory that cannot easily be removed.","zh":"leave an indelible mark 指造成難以消除的強烈影響或記憶。"},{"en":"A kind teacher can leave an indelible mark on a student’s confidence.","zh":"一位仁慈的老師可以在學生信心上留下不可磨滅的印記。"},{"en":"If a family meal leaves an indelible mark, the smell may feel comforting decades later.","zh":"如果一頓家庭飯留下不可磨滅的印記，幾十年後那種氣味仍可能令人安心。"},{"en":"The phrase describes a lasting emotional or mental influence.","zh":"這個短語描述持久的情感或心理影響。"}],"source":"135 - The sense of flavour.pdf","sourcePage":9},{"front":"return to them","meaning":"重新回到；再次尋求","examples":[{"en":"Adults often return to childhood foods for comfort.","zh":"成年人常為了安慰而再次尋求童年食物。"},{"en":"To return to them means to go back to those things, habits, places, or choices again.","zh":"return to them 指再次回到那些事物、習慣、地方或選擇。"},{"en":"Students may return to old notes before an important exam.","zh":"學生可能在重要考試前重新翻看舊筆記。"},{"en":"If people return to childhood foods, they may be seeking familiar comfort.","zh":"如果人們再次尋求童年食物，他們可能是在尋找熟悉的安慰。"},{"en":"The phrase refers back to something already mentioned.","zh":"這個短語指回前文已提及的事物。"}],"source":"135 - The sense of flavour.pdf","sourcePage":9},{"front":"without always knowing why","meaning":"不一定知道原因","examples":[{"en":"People may return to comfort foods without always knowing why.","zh":"人們可能再次尋求安慰食物，而不一定知道原因。"},{"en":"Without always knowing why means not necessarily understanding the reason every time.","zh":"without always knowing why 指不一定每次都明白原因。"},{"en":"A person may feel calmer near the sea without always knowing why.","zh":"一個人可能在海邊感到平靜，卻不一定知道原因。"},{"en":"If smells trigger hidden memories, people may seek certain foods without always knowing why.","zh":"如果氣味觸發隱藏記憶，人們可能尋求某些食物而不一定知道原因。"},{"en":"The phrase shows that behaviour can be influenced by reasons we do not clearly see.","zh":"這個短語顯示行為可能受我們未清楚看見的原因影響。"}],"source":"135 - The sense of flavour.pdf","sourcePage":9},{"front":"comfort foods","meaning":"令人感到安慰的食物","examples":[{"en":"Comfort foods can provide pleasure and reassurance.","zh":"安慰食物可以提供快樂和安心感。"},{"en":"Comfort foods are foods people eat because they make them feel safe, happy, or emotionally supported.","zh":"comfort foods 是令人感到安全、快樂或情感上受支持的食物。"},{"en":"After a stressful day, someone may eat soup or rice as comfort food.","zh":"壓力大的一天後，有人可能吃湯或飯作為安慰食物。"},{"en":"If a food reminds people of home, it may become one of their comfort foods.","zh":"如果一種食物令人想起家，它可能成為他們的安慰食物之一。"},{"en":"The phrase focuses on emotional comfort, not only nutrition.","zh":"這個短語重點在於情感安慰，而不只是營養。"}],"source":"135 - The sense of flavour.pdf","sourcePage":9},{"front":"a source of pleasure and reassurance","meaning":"快樂和安心感的來源","examples":[{"en":"Childhood foods may become a source of pleasure and reassurance.","zh":"童年食物可能成為快樂和安心感的來源。"},{"en":"A source of pleasure and reassurance is something that brings happiness and a feeling of safety.","zh":"a source of pleasure and reassurance 是帶來快樂和安全感的事物。"},{"en":"A familiar song can be a source of pleasure and reassurance during a difficult week.","zh":"在艱難的一星期，一首熟悉歌曲可以成為快樂和安心感的來源。"},{"en":"If a dish reminds someone of family care, it can become a source of pleasure and reassurance.","zh":"如果一道菜令人想起家庭照顧，它可以成為快樂和安心感的來源。"},{"en":"The phrase explains why people return to comforting experiences.","zh":"這個短語解釋人們為何會回到令人安慰的經驗。"}],"source":"135 - The sense of flavour.pdf","sourcePage":9},{"front":"fast-food chains","meaning":"連鎖快餐店","examples":[{"en":"Fast-food chains try to connect their products with childhood memories.","zh":"連鎖快餐店嘗試把其產品與童年記憶連繫起來。"},{"en":"Fast-food chains are restaurant businesses with many branches that sell quick meals.","zh":"fast-food chains 是擁有多間分店、出售快速餐食的餐飲企業。"},{"en":"McDonald’s and KFC are examples of fast-food chains in many cities.","zh":"麥當勞和肯德基是在許多城市可見的連鎖快餐店例子。"},{"en":"If fast-food chains build happy memories in children, those children may return as adults.","zh":"如果連鎖快餐店在兒童心中建立快樂記憶，那些兒童成年後可能再次光顧。"},{"en":"The phrase refers to companies, not just individual fast-food shops.","zh":"這個短語指公司，而不只是單一快餐店。"}],"source":"135 - The sense of flavour.pdf","sourcePage":9},{"front":"work hard to promote","meaning":"努力推廣","examples":[{"en":"Fast-food chains work hard to promote emotional connections with food.","zh":"連鎖快餐店努力推廣食物與情感之間的連繫。"},{"en":"To work hard to promote something means to make strong efforts to encourage or advertise it.","zh":"work hard to promote 某事，指努力鼓勵、宣傳或推動它。"},{"en":"Schools work hard to promote reading through book fairs and library activities.","zh":"學校透過書展和圖書館活動努力推廣閱讀。"},{"en":"If companies work hard to promote a brand image, customers may remember it more easily.","zh":"如果公司努力推廣品牌形象，顧客可能更容易記住它。"},{"en":"The phrase shows deliberate and repeated effort.","zh":"這個短語顯示有意識而反覆的努力。"}],"source":"135 - The sense of flavour.pdf","sourcePage":9},{"front":"translate into","meaning":"轉化為","examples":[{"en":"Childhood memories can translate into frequent adult visits.","zh":"童年記憶可以轉化為成年後頻繁光顧。"},{"en":"To translate into something means to become that result in practical terms.","zh":"translate into 某結果，意思是在實際上變成該結果。"},{"en":"Extra study can translate into higher exam scores if the practice is focused.","zh":"如果練習集中，額外溫習可以轉化為更高考試分數。"},{"en":"If happy memories translate into restaurant visits, emotions become business value.","zh":"如果快樂記憶轉化為餐廳光顧，情感就變成商業價值。"},{"en":"The phrase shows how one thing turns into a concrete outcome.","zh":"這個短語顯示一件事如何變成具體結果。"}],"source":"135 - The sense of flavour.pdf","sourcePage":9},{"front":"frequent adult visits","meaning":"成年後頻繁光顧","examples":[{"en":"Happy childhood memories may lead to frequent adult visits to a restaurant.","zh":"快樂童年記憶可能導致成年後頻繁光顧某餐廳。"},{"en":"Frequent adult visits means repeated visits made by grown-up customers.","zh":"frequent adult visits 指成年顧客反覆到訪。"},{"en":"A café from childhood may receive frequent adult visits from people who once went there with parents.","zh":"一間童年時去過的咖啡店，可能得到曾與父母到訪的人成年後頻繁光顧。"},{"en":"If advertising creates strong childhood memories, frequent adult visits may follow years later.","zh":"如果廣告創造強烈童年記憶，多年後可能出現成年後頻繁光顧。"},{"en":"The phrase links adult behaviour with repeated returning.","zh":"這個短語把成人行為與反覆回訪連繫起來。"}],"source":"135 - The sense of flavour.pdf","sourcePage":9},{"front":"heavy users","meaning":"高用量顧客；頻繁光顧者","examples":[{"en":"Heavy users may eat at the same fast-food chain several times a week.","zh":"頻繁光顧者可能每星期數次在同一連鎖快餐店用餐。"},{"en":"Heavy users are people who use a product or service very often.","zh":"heavy users 是非常頻繁使用某產品或服務的人。"},{"en":"Heavy users of public transport may buy monthly passes to save money.","zh":"公共交通高用量用戶可能購買月票以省錢。"},{"en":"If heavy users visit a restaurant weekly, they become especially valuable customers.","zh":"如果頻繁光顧者每星期光顧餐廳，他們會成為特別有價值的顧客。"},{"en":"The phrase describes frequency of use, not body weight.","zh":"這個短語描述使用頻率，而不是體重。"}],"source":"135 - The sense of flavour.pdf","sourcePage":9},{"front":"four or five times a week","meaning":"每星期四至五次","examples":[{"en":"Some heavy users eat at McDonald’s four or five times a week.","zh":"一些頻繁光顧者每星期四至五次在麥當勞用餐。"},{"en":"Four or five times a week means on four or five separate occasions during one week.","zh":"four or five times a week 指一星期內四或五個不同場合。"},{"en":"A student who practises speaking four or five times a week will improve faster.","zh":"每星期練習口語四至五次的學生會進步得更快。"},{"en":"If someone eats fast food four or five times a week, it becomes a regular habit.","zh":"如果有人每星期四至五次吃快餐，這就成為固定習慣。"},{"en":"The phrase shows high frequency within a short period.","zh":"這個短語顯示短時間內的高頻率。"}],"source":"135 - The sense of flavour.pdf","sourcePage":9},{"front":"craving for flavour","meaning":"對風味的渴求","examples":[{"en":"The human craving for flavour has influenced history.","zh":"人類對風味的渴求影響了歷史。"},{"en":"A craving for flavour is a strong desire for interesting, pleasant, or exciting tastes.","zh":"craving for flavour 是對有趣、愉快或刺激味道的強烈渴望。"},{"en":"A person may add chilli sauce because of a craving for stronger flavour.","zh":"一個人可能因對更強風味的渴求而加入辣椒醬。"},{"en":"If people have a craving for flavour, they may pay more for spices or special foods.","zh":"如果人們對風味有渴求，他們可能為香料或特別食物付更多錢。"},{"en":"The phrase shows that taste desire can drive choices and behaviour.","zh":"這個短語顯示味覺欲望可以推動選擇和行為。"}],"source":"135 - The sense of flavour.pdf","sourcePage":10},{"front":"unacknowledged and unexamined force","meaning":"未被承認和審視的力量","examples":[{"en":"The craving for flavour has been an unacknowledged and unexamined force in history.","zh":"對風味的渴求一直是歷史上一種未被承認和審視的力量。"},{"en":"An unacknowledged and unexamined force is an influence that has not been openly recognised or carefully studied.","zh":"unacknowledged and unexamined force 是未被公開承認或仔細研究的影響力。"},{"en":"Peer pressure can be an unacknowledged and unexamined force in students’ choices.","zh":"同儕壓力可能是學生選擇中未被承認和審視的力量。"},{"en":"If flavour shaped trade and exploration, it was more powerful than many people realised.","zh":"如果風味塑造了貿易和探索，它的力量就比許多人意識到的更大。"},{"en":"The phrase suggests a hidden influence that deserves more attention.","zh":"這個短語暗示一種值得更多關注的隱藏影響。"}],"source":"135 - The sense of flavour.pdf","sourcePage":10},{"front":"royal empires","meaning":"皇室帝國","examples":[{"en":"Royal empires were influenced by the spice trade.","zh":"皇室帝國受到香料貿易影響。"},{"en":"Royal empires are large territories ruled by kings, queens, or royal families.","zh":"royal empires 是由國王、女王或皇室統治的大型領土。"},{"en":"Royal empires often controlled trade routes, armies, and distant colonies.","zh":"皇室帝國常控制貿易路線、軍隊和遙遠殖民地。"},{"en":"If spices made rulers rich, royal empires had reasons to protect spice trade routes.","zh":"如果香料令統治者富有，皇室帝國就有理由保護香料貿易路線。"},{"en":"The phrase connects political power with monarchy and expansion.","zh":"這個短語把政治權力與君主制和擴張連繫起來。"}],"source":"135 - The sense of flavour.pdf","sourcePage":10},{"front":"unexplored lands","meaning":"未經探索的土地","examples":[{"en":"Explorers crossed unexplored lands in search of spices.","zh":"探險家穿越未經探索的土地尋找香料。"},{"en":"Unexplored lands are places that outsiders or recorded travellers have not yet mapped or studied carefully.","zh":"unexplored lands 是外來者或有紀錄的旅行者尚未仔細繪圖或研究的地方。"},{"en":"Early travellers often feared unexplored lands because they did not know the dangers there.","zh":"早期旅行者常害怕未經探索的土地，因為他們不知道那裏的危險。"},{"en":"If valuable spices were expected beyond unexplored lands, explorers might take great risks.","zh":"如果人們預期未經探索的土地之外有珍貴香料，探險家可能冒巨大風險。"},{"en":"The phrase describes unknown territories from the explorer’s viewpoint.","zh":"這個短語從探險者角度描述未知領土。"}],"source":"135 - The sense of flavour.pdf","sourcePage":10},{"front":"be traversed","meaning":"被穿越","examples":[{"en":"Unexplored lands were traversed because of the spice trade.","zh":"未經探索的土地因香料貿易而被穿越。"},{"en":"To be traversed means to be crossed or travelled across.","zh":"be traversed 指被橫越或穿越。"},{"en":"The desert was traversed by traders carrying salt and cloth.","zh":"沙漠曾被運送鹽和布的商人穿越。"},{"en":"If mountains must be traversed to reach a village, the journey may be dangerous.","zh":"如果必須穿越山脈才能到達村莊，旅程可能很危險。"},{"en":"The phrase is formal and often used for long or difficult journeys.","zh":"這個短語較正式，常用於漫長或困難旅程。"}],"source":"135 - The sense of flavour.pdf","sourcePage":10},{"front":"great religions and philosophies","meaning":"偉大的宗教和哲學","examples":[{"en":"Great religions and philosophies were changed by the spice trade.","zh":"偉大的宗教和哲學因香料貿易而改變。"},{"en":"Great religions and philosophies are major systems of belief, worship, ethics, and thought.","zh":"great religions and philosophies 是重要的信仰、崇拜、倫理和思想系統。"},{"en":"Trade routes helped great religions and philosophies spread across regions.","zh":"貿易路線幫助偉大的宗教和哲學跨地區傳播。"},{"en":"If travellers exchanged stories and ideas, great religions and philosophies could change over time.","zh":"如果旅行者交換故事和想法，偉大的宗教和哲學可能隨時間改變。"},{"en":"The phrase refers to broad systems of human belief and thinking.","zh":"這個短語指人類信仰和思想的廣泛系統。"}],"source":"135 - The sense of flavour.pdf","sourcePage":10},{"front":"forever changed by","meaning":"被……永遠改變","examples":[{"en":"Trade in spices forever changed parts of world history.","zh":"香料貿易永遠改變了世界歷史的部分面貌。"},{"en":"Forever changed by something means changed permanently because of it.","zh":"forever changed by 某事，指因它而永久改變。"},{"en":"A town may be forever changed by the arrival of a major railway.","zh":"一個城鎮可能因主要鐵路到來而被永遠改變。"},{"en":"If exploration was driven by spices, world trade was forever changed by flavour.","zh":"如果探索由香料推動，世界貿易就被風味永遠改變。"},{"en":"The phrase emphasises lasting impact.","zh":"這個短語強調持久影響。"}],"source":"135 - The sense of flavour.pdf","sourcePage":10},{"front":"the spice trade","meaning":"香料貿易","examples":[{"en":"The spice trade shaped empires and exploration.","zh":"香料貿易塑造了帝國和探索。"},{"en":"The spice trade was the buying, selling, and transport of spices across regions and continents.","zh":"the spice trade 是跨地區和跨洲買賣及運送香料的貿易。"},{"en":"Merchants in the spice trade carried pepper, cinnamon, and cloves over long distances.","zh":"香料貿易中的商人把胡椒、肉桂和丁香運送到遠方。"},{"en":"If spices were highly valuable, the spice trade could make cities and rulers rich.","zh":"如果香料極具價值，香料貿易可以令城市和統治者富有。"},{"en":"The phrase refers to an important historical trade network.","zh":"這個短語指一個重要歷史貿易網絡。"}],"source":"135 - The sense of flavour.pdf","sourcePage":10},{"front":"set sail","meaning":"啟航","examples":[{"en":"Christopher Columbus set sail to find new seasonings.","zh":"Christopher Columbus 啟航尋找新調味料。"},{"en":"To set sail means to begin a journey by ship.","zh":"set sail 指乘船開始旅程。"},{"en":"The fishermen set sail before sunrise to reach deeper waters.","zh":"漁民在日出前啟航，以到達更深水域。"},{"en":"If explorers set sail without accurate maps, they faced serious risks.","zh":"如果探險家沒有準確地圖就啟航，他們會面對嚴重風險。"},{"en":"The phrase is often used in stories of sea journeys and exploration.","zh":"這個短語常用於海上旅程和探索故事。"}],"source":"135 - The sense of flavour.pdf","sourcePage":10},{"front":"in order to try to","meaning":"為了嘗試去","examples":[{"en":"Columbus set sail in order to try to find new seasonings.","zh":"Columbus 啟航是為了嘗試尋找新調味料。"},{"en":"In order to try to means for the purpose of attempting to do something.","zh":"in order to try to 指為了嘗試做某事。"},{"en":"Students review old papers in order to try to understand exam patterns.","zh":"學生溫習舊試卷是為了嘗試了解考試模式。"},{"en":"If a company offers discounts in order to try to attract customers, sales may rise.","zh":"如果公司提供折扣是為了嘗試吸引顧客，銷售可能上升。"},{"en":"The phrase shows both purpose and uncertainty.","zh":"這個短語同時顯示目的和不確定性。"}],"source":"135 - The sense of flavour.pdf","sourcePage":10},{"front":"seasonings","meaning":"調味料","examples":[{"en":"Explorers searched for new seasonings.","zh":"探險家尋找新調味料。"},{"en":"Seasonings are ingredients added to food to improve or change its flavour.","zh":"seasonings 是加入食物以改善或改變味道的材料。"},{"en":"Salt, pepper, herbs, and spices are common seasonings.","zh":"鹽、胡椒、香草和香料都是常見調味料。"},{"en":"If a dish tastes flat, adding seasonings can make it more enjoyable.","zh":"如果一道菜味道平淡，加入調味料可以令它更可口。"},{"en":"The word refers to flavouring ingredients, not the main food itself.","zh":"這個字指調味材料，而不是食物主體。"}],"source":"135 - The sense of flavour.pdf","sourcePage":10},{"front":"make his fortune from","meaning":"靠……發財","examples":[{"en":"Columbus hoped to make his fortune from spices.","zh":"Columbus 希望靠香料發財。"},{"en":"To make one’s fortune from something means to become rich through it.","zh":"make one’s fortune from 某物，意思是透過它變得富有。"},{"en":"An inventor may make her fortune from a useful new medical device.","zh":"發明家可能靠一種有用的新醫療裝置發財。"},{"en":"If spices sold for high prices, traders could make their fortune from them.","zh":"如果香料能賣高價，商人就可以靠它們發財。"},{"en":"The phrase links wealth with a particular activity or product.","zh":"這個短語把財富與特定活動或產品連繫起來。"}],"source":"135 - The sense of flavour.pdf","sourcePage":11},{"front":"highly prized commodity","meaning":"極受珍視的商品","examples":[{"en":"Spices were a highly prized commodity.","zh":"香料是極受珍視的商品。"},{"en":"A highly prized commodity is a product that people value greatly and are willing to pay much for.","zh":"highly prized commodity 是人們非常重視並願意高價購買的產品。"},{"en":"Clean drinking water can become a highly prized commodity during a drought.","zh":"在乾旱期間，潔淨飲用水可以成為極受珍視的商品。"},{"en":"If spices were a highly prized commodity, rulers and traders would compete to control them.","zh":"如果香料是極受珍視的商品，統治者和商人就會競爭控制它們。"},{"en":"The phrase is often used for valuable trade goods.","zh":"這個短語常用於有價值的貿易商品。"}],"source":"135 - The sense of flavour.pdf","sourcePage":11},{"front":"the influence of flavour","meaning":"風味的影響力","examples":[{"en":"The influence of flavour remains powerful in the marketplace.","zh":"風味的影響力在市場中仍然強大。"},{"en":"The influence of flavour means the way taste affects choices, business, culture, or behaviour.","zh":"the influence of flavour 指味道如何影響選擇、商業、文化或行為。"},{"en":"The influence of flavour can decide whether children prefer one snack over another.","zh":"風味的影響力可以決定孩子偏好哪一種零食。"},{"en":"If the influence of flavour is strong, a delicious product may outsell a healthier but bland one.","zh":"如果風味的影響力強，美味產品可能比健康但清淡的產品賣得更好。"},{"en":"The phrase shows that taste can shape decisions beyond the dinner table.","zh":"這個短語顯示味道可以塑造餐桌以外的決定。"}],"source":"135 - The sense of flavour.pdf","sourcePage":11},{"front":"world marketplace","meaning":"世界市場","examples":[{"en":"The influence of flavour is still decisive in the world marketplace.","zh":"風味的影響力在世界市場中仍然具有決定性。"},{"en":"The world marketplace means the global system where products are bought and sold.","zh":"world marketplace 指產品在全球被買賣的系統。"},{"en":"A popular drink can succeed in the world marketplace if people in many countries enjoy it.","zh":"如果許多國家的人都喜歡，一款受歡迎飲品可以在世界市場成功。"},{"en":"If a company enters the world marketplace, it must understand different tastes and cultures.","zh":"如果公司進入世界市場，就必須了解不同口味和文化。"},{"en":"The phrase refers to international business, not a physical market.","zh":"這個短語指國際商業，而不是實體市場。"}],"source":"135 - The sense of flavour.pdf","sourcePage":11},{"front":"no less decisive","meaning":"同樣具有決定性","examples":[{"en":"Flavour is no less decisive today than it was in the past.","zh":"風味今天和過去一樣同樣具有決定性。"},{"en":"No less decisive means just as important in determining the result.","zh":"no less decisive 指在決定結果方面同樣重要。"},{"en":"Good communication is no less decisive in online classes than in face-to-face lessons.","zh":"良好溝通在網課中和面授課中同樣具有決定性。"},{"en":"If taste is no less decisive today, modern food companies still depend heavily on flavour.","zh":"如果味道今天仍同樣具有決定性，現代食品公司仍高度依賴風味。"},{"en":"The phrase compares two periods or situations and says the importance remains strong.","zh":"這個短語比較兩個時期或情況，並指出重要性仍然強。"}],"source":"135 - The sense of flavour.pdf","sourcePage":11},{"front":"the rise and fall of","meaning":"……的興衰","examples":[{"en":"Flavour can determine the rise and fall of food companies.","zh":"風味可以決定食品公司的興衰。"},{"en":"The rise and fall of something means its growth, success, decline, and possible failure.","zh":"the rise and fall of 某事，指其成長、成功、衰落和可能失敗。"},{"en":"Historians study the rise and fall of empires to understand power and weakness.","zh":"歷史學家研究帝國的興衰，以了解權力和弱點。"},{"en":"If customers reject a product’s taste, it can affect the rise and fall of a brand.","zh":"如果顧客拒絕產品味道，它可以影響品牌的興衰。"},{"en":"The phrase describes a full movement from success to decline.","zh":"這個短語描述從成功到衰落的完整變化。"}],"source":"135 - The sense of flavour.pdf","sourcePage":11},{"front":"corporate empires","meaning":"企業王國","examples":[{"en":"The taste of products can affect corporate empires.","zh":"產品味道可以影響企業王國。"},{"en":"Corporate empires are very large and powerful business groups or companies.","zh":"corporate empires 是非常大型而有權力的商業集團或公司。"},{"en":"A technology company can become a corporate empire if its products dominate many markets.","zh":"如果科技公司的產品主導多個市場，它可以成為企業王國。"},{"en":"If customers stop liking a famous drink, even corporate empires can lose power.","zh":"如果顧客不再喜歡著名飲品，即使企業王國也可能失去力量。"},{"en":"The phrase compares large companies to empires because of their size and influence.","zh":"這個短語把大型公司比作帝國，因為它們規模大且有影響力。"}],"source":"135 - The sense of flavour.pdf","sourcePage":11},{"front":"soft-drink companies","meaning":"汽水公司","examples":[{"en":"Soft-drink companies depend heavily on flavour.","zh":"汽水公司高度依賴風味。"},{"en":"Soft-drink companies are businesses that make and sell non-alcoholic drinks such as soda or flavoured beverages.","zh":"soft-drink companies 是製造和銷售汽水或調味飲品等非酒精飲品的企業。"},{"en":"Soft-drink companies test new flavours before launching them in shops.","zh":"汽水公司在商店推出新口味前會先測試。"},{"en":"If soft-drink companies choose the wrong flavour, customers may not buy the product again.","zh":"如果汽水公司選錯風味，顧客可能不再購買該產品。"},{"en":"The phrase refers to drink businesses, not all food companies.","zh":"這個短語指飲品企業，而不是所有食品公司。"}],"source":"135 - The sense of flavour.pdf","sourcePage":11},{"front":"snack-food companies","meaning":"零食公司","examples":[{"en":"Snack-food companies rise or fall according to taste.","zh":"零食公司會根據味道而興衰。"},{"en":"Snack-food companies are businesses that make foods such as crisps, biscuits, sweets, or crackers.","zh":"snack-food companies 是製造薯片、餅乾、糖果或梳打餅等食品的企業。"},{"en":"Snack-food companies often change flavours to attract young customers.","zh":"零食公司常改變口味以吸引年輕顧客。"},{"en":"If snack-food companies ignore local tastes, their products may sell poorly.","zh":"如果零食公司忽略本地口味，其產品可能賣得不好。"},{"en":"The phrase focuses on companies that sell small foods eaten between meals.","zh":"這個短語重點在出售正餐之間小食的公司。"}],"source":"135 - The sense of flavour.pdf","sourcePage":11},{"front":"be frequently determined by","meaning":"經常由……決定","examples":[{"en":"The success of food companies is frequently determined by flavour.","zh":"食品公司的成功經常由風味決定。"},{"en":"To be frequently determined by something means to often depend on that factor for the result.","zh":"be frequently determined by 某事，指結果常取決於該因素。"},{"en":"A student’s progress is frequently determined by practice, feedback, and sleep.","zh":"學生進步經常由練習、回饋和睡眠決定。"},{"en":"If product success is frequently determined by taste, companies must test flavours carefully.","zh":"如果產品成功經常由味道決定，公司就必須仔細測試風味。"},{"en":"The phrase shows a common cause or deciding factor.","zh":"這個短語顯示常見原因或決定因素。"}],"source":"135 - The sense of flavour.pdf","sourcePage":11},{"front":"how their products taste","meaning":"其產品味道如何","examples":[{"en":"Corporate success may depend on how their products taste.","zh":"企業成功可能取決於其產品味道如何。"},{"en":"How their products taste means the flavour experience customers get from a company’s products.","zh":"how their products taste 指顧客從公司產品中得到的風味體驗。"},{"en":"A bakery’s reputation depends partly on how its bread and cakes taste.","zh":"麵包店的聲譽部分取決於其麵包和蛋糕味道如何。"},{"en":"If customers dislike how their products taste, even strong advertising may not save sales.","zh":"如果顧客不喜歡其產品味道如何，即使強力廣告也未必能挽救銷售。"},{"en":"The phrase focuses on customer experience through flavour.","zh":"這個短語重點在顧客透過風味得到的體驗。"}],"source":"135 - The sense of flavour.pdf","sourcePage":11},{"front":"the flavour industry","meaning":"食用香料業；風味工業","examples":[{"en":"The flavour industry emerged as processed foods expanded.","zh":"隨着加工食品擴展，食用香料業興起。"},{"en":"The flavour industry is the business of creating, producing, and selling flavourings for food and drinks.","zh":"the flavour industry 是創造、生產和銷售食品及飲品調味物的行業。"},{"en":"The flavour industry helps companies make strawberry drinks, cheese snacks, and instant noodles taste consistent.","zh":"食用香料業幫助公司令草莓飲品、芝士零食和即食麵味道穩定。"},{"en":"If processed food grows, the flavour industry grows because companies need reliable tastes.","zh":"如果加工食品增長，食用香料業也會增長，因為公司需要可靠味道。"},{"en":"The phrase refers to a specialised part of the food business.","zh":"這個短語指食品業中一個專門部分。"}],"source":"135 - The sense of flavour.pdf","sourcePage":12},{"front":"emerge","meaning":"出現；興起","examples":[{"en":"The flavour industry emerged in the mid-1800s.","zh":"食用香料業在19世紀中葉興起。"},{"en":"To emerge means to appear, develop, or become known.","zh":"emerge 指出現、發展或變得為人所知。"},{"en":"A new problem may emerge when a city grows too quickly.","zh":"當城市成長太快，新問題可能出現。"},{"en":"If a new industry emerges, workers may need new skills and training.","zh":"如果新行業興起，工人可能需要新技能和培訓。"},{"en":"The word often describes something becoming visible or important over time.","zh":"這個字常描述某事物隨時間變得可見或重要。"}],"source":"135 - The sense of flavour.pdf","sourcePage":12},{"front":"in the mid-1800s","meaning":"在19世紀中葉","examples":[{"en":"The flavour industry began in the mid-1800s.","zh":"食用香料業在19世紀中葉開始。"},{"en":"In the mid-1800s means around the middle of the nineteenth century.","zh":"in the mid-1800s 指大約十九世紀中期。"},{"en":"Many factories expanded in the mid-1800s as industrial production grew.","zh":"隨着工業生產增長，許多工廠在19世紀中葉擴張。"},{"en":"If the flavour industry began in the mid-1800s, it developed alongside modern food manufacturing.","zh":"如果食用香料業在19世紀中葉開始，它就與現代食品製造一同發展。"},{"en":"The phrase places an event in a historical time period.","zh":"這個短語把事件放在一個歷史時期中。"}],"source":"135 - The sense of flavour.pdf","sourcePage":12},{"front":"processed foods","meaning":"加工食品","examples":[{"en":"Processed foods created a demand for flavour additives.","zh":"加工食品創造了對調味添加劑的需求。"},{"en":"Processed foods are foods changed from their natural state by cooking, preserving, packaging, or adding ingredients.","zh":"processed foods 是透過烹調、保存、包裝或加入成分而從天然狀態改變的食物。"},{"en":"Canned soup, instant noodles, and biscuits are examples of processed foods.","zh":"罐頭湯、即食麵和餅乾都是加工食品例子。"},{"en":"If processed foods lose flavour during manufacturing, companies may add flavourings.","zh":"如果加工食品在製造過程中失去風味，公司可能加入調味料。"},{"en":"The phrase covers many factory-made or prepared foods.","zh":"這個短語涵蓋許多工廠製造或預先處理的食品。"}],"source":"135 - The sense of flavour.pdf","sourcePage":12},{"front":"be manufactured on a large scale","meaning":"被大規模生產","examples":[{"en":"Processed foods began to be manufactured on a large scale.","zh":"加工食品開始被大規模生產。"},{"en":"To be manufactured on a large scale means to be produced in very large quantities in factories.","zh":"be manufactured on a large scale 指在工廠中以非常大的數量生產。"},{"en":"School uniforms may be manufactured on a large scale before the new term begins.","zh":"新學期開始前，校服可能被大規模生產。"},{"en":"If food is manufactured on a large scale, flavour must stay consistent across many batches.","zh":"如果食物被大規模生產，許多批次之間的風味必須保持一致。"},{"en":"The phrase emphasises industrial production, not small home cooking.","zh":"這個短語強調工業生產，而不是小規模家中烹調。"}],"source":"135 - The sense of flavour.pdf","sourcePage":12},{"front":"recognise the need for","meaning":"意識到對……的需要","examples":[{"en":"Food processors recognised the need for flavour additives.","zh":"食品加工商意識到對調味添加劑的需要。"},{"en":"To recognise the need for something means to realise that it is necessary.","zh":"recognise the need for 某物，意思是意識到它是必要的。"},{"en":"A school may recognise the need for more counsellors after students report stress.","zh":"當學生反映壓力後，學校可能意識到對更多輔導員的需要。"},{"en":"If factories recognise the need for better flavour, they may hire flavour specialists.","zh":"如果工廠意識到對更佳風味的需要，它們可能聘請風味專家。"},{"en":"The phrase shows awareness of a practical requirement.","zh":"這個短語顯示對實際需求的認識。"}],"source":"135 - The sense of flavour.pdf","sourcePage":12},{"front":"flavour additives","meaning":"調味添加劑","examples":[{"en":"Flavour additives were added to processed foods.","zh":"調味添加劑被加入加工食品中。"},{"en":"Flavour additives are substances put into food to create, strengthen, or restore taste and aroma.","zh":"flavour additives 是加入食物中以創造、加強或恢復味道和香氣的物質。"},{"en":"A strawberry yoghurt may contain flavour additives to make the fruit taste stronger.","zh":"草莓乳酪可能含有調味添加劑，使水果味更強。"},{"en":"If processing removes natural aroma, flavour additives can help the product taste appealing again.","zh":"如果加工過程移除天然香氣，調味添加劑可以幫助產品再次有吸引力。"},{"en":"The phrase refers to added flavour substances, not basic nutrients.","zh":"這個短語指添加的風味物質，而不是基本營養素。"}],"source":"135 - The sense of flavour.pdf","sourcePage":12},{"front":"food processors","meaning":"食品加工商","examples":[{"en":"Early food processors turned to perfume companies for help.","zh":"早期食品加工商向香水公司求助。"},{"en":"Food processors are companies or people that turn raw ingredients into food products for sale.","zh":"food processors 是把原材料變成可出售食品的人或公司。"},{"en":"Food processors may can fruit, freeze vegetables, or make sauces.","zh":"食品加工商可能把水果製成罐頭、冷凍蔬菜或製作醬汁。"},{"en":"If food processors need a stable flavour, they may work with flavour scientists.","zh":"如果食品加工商需要穩定風味，他們可能與風味科學家合作。"},{"en":"The phrase refers to the stage between farming and selling finished food.","zh":"這個短語指農業和出售成品食品之間的階段。"}],"source":"135 - The sense of flavour.pdf","sourcePage":12},{"front":"turn to","meaning":"求助於；轉向","examples":[{"en":"Food processors turned to perfume companies for expertise.","zh":"食品加工商求助於香水公司以獲得專業知識。"},{"en":"To turn to someone means to go to them for help, advice, or support.","zh":"turn to 某人，意思是向他們尋求幫助、建議或支援。"},{"en":"Students may turn to teachers when they cannot understand a difficult passage.","zh":"學生不明白困難文章時，可能求助於老師。"},{"en":"If a company lacks technical knowledge, it may turn to outside experts.","zh":"如果公司缺乏技術知識，它可能轉向外部專家。"},{"en":"The phrase shows seeking help from a particular source.","zh":"這個短語顯示向特定來源尋求幫助。"}],"source":"135 - The sense of flavour.pdf","sourcePage":12},{"front":"perfume companies","meaning":"香水公司","examples":[{"en":"Perfume companies had experience with volatile aromas.","zh":"香水公司有處理揮發性香氣的經驗。"},{"en":"Perfume companies are businesses that create and sell fragrances.","zh":"perfume companies 是創造和銷售香水的企業。"},{"en":"Perfume companies study flowers, spices, oils, and chemicals to design smells.","zh":"香水公司研究花、香料、油和化學物質來設計氣味。"},{"en":"If food companies needed aroma knowledge, perfume companies could offer useful expertise.","zh":"如果食品公司需要香氣知識，香水公司可以提供有用專業。"},{"en":"The phrase refers to fragrance businesses, not food manufacturers.","zh":"這個短語指香氛企業，而不是食品製造商。"}],"source":"135 - The sense of flavour.pdf","sourcePage":12},{"front":"years of experience working with","meaning":"多年處理……的經驗","examples":[{"en":"Perfume companies had years of experience working with essential oils.","zh":"香水公司有多年處理香精油的經驗。"},{"en":"Years of experience working with something means long practical knowledge gained by using or handling it.","zh":"years of experience working with 某物，指透過使用或處理它而累積的長期實際知識。"},{"en":"A nurse with years of experience working with elderly patients can notice small health changes.","zh":"一位有多年照顧長者經驗的護士可以察覺細微健康變化。"},{"en":"If a company has years of experience working with aromas, it may understand flavour chemicals well.","zh":"如果公司有多年處理香氣的經驗，它可能很了解風味化學物。"},{"en":"The phrase highlights skill built through long practice.","zh":"這個短語強調長期實踐建立的技能。"}],"source":"135 - The sense of flavour.pdf","sourcePage":12},{"front":"essential oils","meaning":"香精油","examples":[{"en":"Essential oils were familiar materials for perfume companies.","zh":"香精油是香水公司熟悉的材料。"},{"en":"Essential oils are concentrated fragrant oils taken from plants.","zh":"essential oils 是從植物提取的濃縮芳香油。"},{"en":"Lavender and peppermint essential oils are often used for their strong smells.","zh":"薰衣草和薄荷香精油常因其強烈氣味而被使用。"},{"en":"If essential oils are too concentrated, they should be used carefully.","zh":"如果香精油太濃，應小心使用。"},{"en":"The phrase is common in perfume, cosmetics, and aromatherapy contexts.","zh":"這個短語常見於香水、化妝品和香薰語境。"}],"source":"135 - The sense of flavour.pdf","sourcePage":13},{"front":"volatile aromas","meaning":"揮發性香氣","examples":[{"en":"Perfume makers understood volatile aromas.","zh":"香水製造商了解揮發性香氣。"},{"en":"Volatile aromas are smells from substances that easily evaporate into the air.","zh":"volatile aromas 是來自容易蒸發到空氣中的物質的氣味。"},{"en":"Hot soup gives off volatile aromas that reach the nose quickly.","zh":"熱湯散發很快到達鼻子的揮發性香氣。"},{"en":"If a product depends on volatile aromas, packaging must help keep the smell inside.","zh":"如果產品依賴揮發性香氣，包裝就必須幫助保留氣味。"},{"en":"The phrase describes aromas that travel through the air easily.","zh":"這個短語描述容易在空氣中移動的香氣。"}],"source":"135 - The sense of flavour.pdf","sourcePage":13},{"front":"perfume houses","meaning":"香水公司；香水製造商","examples":[{"en":"The great perfume houses produced early flavour compounds.","zh":"大型香水公司生產了早期風味化合物。"},{"en":"Perfume houses are established companies or workshops that design and produce fragrances.","zh":"perfume houses 是設計和生產香氣的老牌公司或工作室。"},{"en":"Famous perfume houses often keep secret recipes for their scents.","zh":"著名香水公司常保留其香氣配方為秘密。"},{"en":"If perfume houses understood aroma chemistry, they could help create food flavours.","zh":"如果香水製造商了解香氣化學，他們可以幫助創造食物風味。"},{"en":"The phrase sounds more traditional and specialised than perfume companies.","zh":"這個短語比 perfume companies 更傳統和專門。"}],"source":"135 - The sense of flavour.pdf","sourcePage":13},{"front":"flavour compounds","meaning":"風味化合物","examples":[{"en":"Perfume houses produced many of the first flavour compounds.","zh":"香水公司生產了許多最早的風味化合物。"},{"en":"Flavour compounds are chemical substances that create or contribute to flavour.","zh":"flavour compounds 是創造或構成風味的化學物質。"},{"en":"Vanilla flavour compounds can make cakes smell and taste sweeter.","zh":"雲呢拿風味化合物可以令蛋糕聞起來和吃起來更甜。"},{"en":"If scientists identify flavour compounds in fruit, they can recreate similar flavours in drinks.","zh":"如果科學家識別水果中的風味化合物，他們可以在飲品中重現相似風味。"},{"en":"The phrase is scientific and refers to the chemical basis of flavour.","zh":"這個短語較科學，指風味的化學基礎。"}],"source":"135 - The sense of flavour.pdf","sourcePage":13},{"front":"in the early part of","meaning":"在……早期","examples":[{"en":"In the early part of the 20th century, Germany led flavour production.","zh":"在20世紀早期，德國領先風味生產。"},{"en":"In the early part of a period means near the beginning of that time.","zh":"in the early part of 某時期，指接近該時期的開始。"},{"en":"In the early part of the school year, students are still learning routines.","zh":"在學年早期，學生仍在學習日常程序。"},{"en":"If a discovery happens in the early part of a century, it may influence many later developments.","zh":"如果一項發現在一個世紀早期出現，它可能影響許多後來發展。"},{"en":"The phrase places events near the start of a time period.","zh":"這個短語把事件放在某段時間的開始附近。"}],"source":"135 - The sense of flavour.pdf","sourcePage":13},{"front":"chemical industry","meaning":"化學工業","examples":[{"en":"Germany’s chemical industry became important in flavour production.","zh":"德國的化學工業在風味生產中變得重要。"},{"en":"The chemical industry is the business of producing chemicals for medicine, food, farming, cleaning, and manufacturing.","zh":"chemical industry 是為醫藥、食品、農業、清潔和製造業生產化學品的行業。"},{"en":"The chemical industry makes products such as fertilisers, plastics, and flavour ingredients.","zh":"化學工業製造肥料、塑膠和風味材料等產品。"},{"en":"If the chemical industry grows, it can support many other industries.","zh":"如果化學工業成長，它可以支援許多其他行業。"},{"en":"The phrase refers to a major manufacturing sector.","zh":"這個短語指一個主要製造業部門。"}],"source":"135 - The sense of flavour.pdf","sourcePage":13},{"front":"assume the lead in","meaning":"在……中取得領先地位","examples":[{"en":"Germany’s chemical industry assumed the lead in flavour production.","zh":"德國化學工業在風味生產中取得領先地位。"},{"en":"To assume the lead in something means to become the leader or most advanced participant in that area.","zh":"assume the lead in 某領域，意思是在該領域成為領導者或最先進參與者。"},{"en":"A school may assume the lead in digital learning if it trains teachers early.","zh":"如果學校及早培訓老師，它可能在數碼學習中取得領先地位。"},{"en":"If a country assumes the lead in green technology, other countries may follow its standards.","zh":"如果一個國家在綠色科技中取得領先地位，其他國家可能跟隨其標準。"},{"en":"The phrase describes taking a leading position.","zh":"這個短語描述取得領導位置。"}],"source":"135 - The sense of flavour.pdf","sourcePage":13},{"front":"flavour production","meaning":"食用香料生產","examples":[{"en":"Germany became a leader in flavour production.","zh":"德國成為食用香料生產的領導者。"},{"en":"Flavour production is the process of making substances that give food or drinks particular tastes and aromas.","zh":"flavour production 是製造賦予食物或飲品特定味道和香氣的物質的過程。"},{"en":"Flavour production may involve chemistry, testing, and knowledge of consumer preferences.","zh":"食用香料生產可能涉及化學、測試和對消費者喜好的了解。"},{"en":"If flavour production improves, processed foods can taste more consistent.","zh":"如果食用香料生產改善，加工食品味道可以更穩定。"},{"en":"The phrase refers to making flavourings, not cooking meals.","zh":"這個短語指製造調味物，而不是烹調餐食。"}],"source":"135 - The sense of flavour.pdf","sourcePage":13},{"front":"legend has it that","meaning":"傳說","examples":[{"en":"Legend has it that a German scientist discovered the flavour by accident.","zh":"傳說一位德國科學家偶然發現了這種風味。"},{"en":"Legend has it that means a story is commonly told, though it may not be fully proven.","zh":"legend has it that 指有一個流傳的說法，雖然未必完全證實。"},{"en":"Legend has it that the old school building is haunted.","zh":"傳說那座舊校舍鬧鬼。"},{"en":"If legend has it that a discovery happened by accident, people may repeat the story even without full evidence.","zh":"如果傳說某項發現是偶然發生，人們即使沒有完整證據也可能重複這個故事。"},{"en":"The phrase introduces a traditional or popular story.","zh":"這個短語用來引入傳統或流行故事。"}],"source":"135 - The sense of flavour.pdf","sourcePage":13},{"front":"artificial flavours","meaning":"人工香料","examples":[{"en":"Methyl anthranilate was one of the first artificial flavours.","zh":"鄰氨基苯甲酸甲酯是最早的人工香料之一。"},{"en":"Artificial flavours are man-made flavour substances used to imitate or create tastes.","zh":"artificial flavours 是用來模仿或創造味道的人造風味物質。"},{"en":"A grape sweet may contain artificial flavours even if it has no real grapes.","zh":"葡萄糖果即使沒有真正葡萄，也可能含有人工香料。"},{"en":"If natural flavour is expensive, companies may use artificial flavours instead.","zh":"如果天然風味昂貴，公司可能改用人工香料。"},{"en":"The phrase contrasts manufactured flavourings with flavours directly from natural foods.","zh":"這個短語把製造出來的調味物與直接來自天然食物的味道作對比。"}],"source":"135 - The sense of flavour.pdf","sourcePage":13},{"front":"by accident","meaning":"偶然地","examples":[{"en":"A scientist discovered methyl anthranilate by accident.","zh":"一位科學家偶然發現了鄰氨基苯甲酸甲酯。"},{"en":"By accident means without planning or intending it.","zh":"by accident 指沒有計劃或並非有意地。"},{"en":"I deleted the file by accident while cleaning my desktop.","zh":"我清理桌面時偶然刪除了那個檔案。"},{"en":"If a useful discovery happens by accident, careful observation can still turn it into progress.","zh":"如果有用發現是偶然發生，仔細觀察仍可把它變成進步。"},{"en":"The phrase contrasts with on purpose.","zh":"這個短語與 on purpose 形成對比。"}],"source":"135 - The sense of flavour.pdf","sourcePage":13},{"front":"mix chemicals","meaning":"混合化學物質","examples":[{"en":"The scientist discovered the flavour while mixing chemicals.","zh":"科學家在混合化學物質時發現了這種風味。"},{"en":"To mix chemicals means to combine chemical substances together.","zh":"mix chemicals 指把化學物質混合在一起。"},{"en":"Students should only mix chemicals in a lab when a teacher supervises them.","zh":"學生只應在老師監督下在實驗室混合化學物質。"},{"en":"If people mix chemicals carelessly, dangerous gases may be produced.","zh":"如果人們粗心混合化學物質，可能產生危險氣體。"},{"en":"The phrase describes a practical action in chemistry.","zh":"這個短語描述化學中的實際動作。"}],"source":"135 - The sense of flavour.pdf","sourcePage":14},{"front":"be filled with","meaning":"充滿","examples":[{"en":"The laboratory was filled with the sweet smell of grapes.","zh":"實驗室充滿葡萄的甜香。"},{"en":"To be filled with something means to contain a lot of it or have it throughout the space.","zh":"be filled with 某物，指含有大量該物或整個空間都有它。"},{"en":"The classroom was filled with laughter after the teacher told a joke.","zh":"老師說笑話後，課室充滿笑聲。"},{"en":"If a kitchen is filled with smoke, people should open windows quickly.","zh":"如果廚房充滿煙，人們應迅速開窗。"},{"en":"The phrase can describe physical contents, sounds, smells, or feelings.","zh":"這個短語可以描述實體內容、聲音、氣味或感受。"}],"source":"135 - The sense of flavour.pdf","sourcePage":14},{"front":"the sweet smell of grapes","meaning":"葡萄的甜香","examples":[{"en":"The chemical produced the sweet smell of grapes.","zh":"這種化學物質產生葡萄的甜香。"},{"en":"The sweet smell of grapes is the pleasant fruity aroma associated with grapes or grape-flavoured products.","zh":"the sweet smell of grapes 是與葡萄或葡萄味產品相關的愉快水果香氣。"},{"en":"A grape sweet can release the sweet smell of grapes as soon as the packet is opened.","zh":"一包葡萄糖果一打開，就可能釋放葡萄的甜香。"},{"en":"If a drink has the sweet smell of grapes, children may expect it to taste fruity.","zh":"如果飲品有葡萄的甜香，孩子可能預期它有水果味。"},{"en":"The phrase describes aroma, not necessarily real grape juice.","zh":"這個短語描述香氣，不一定是真葡萄汁。"}],"source":"135 - The sense of flavour.pdf","sourcePage":14},{"front":"chief flavouring compound","meaning":"主要調味化合物","examples":[{"en":"Methyl anthranilate became the chief flavouring compound in grape juice.","zh":"鄰氨基苯甲酸甲酯成為葡萄汁中的主要調味化合物。"},{"en":"A chief flavouring compound is the main chemical substance that gives a product its flavour.","zh":"chief flavouring compound 是賦予產品風味的主要化學物質。"},{"en":"Vanilla may be the chief flavouring compound in some ice creams.","zh":"雲呢拿可能是一些雪糕中的主要調味化合物。"},{"en":"If one chief flavouring compound is missing, the product may no longer taste right.","zh":"如果缺少一種主要調味化合物，產品味道可能不再正確。"},{"en":"The phrase identifies the main flavour chemical in a food or drink.","zh":"這個短語指出食物或飲品中的主要風味化學物。"}],"source":"135 - The sense of flavour.pdf","sourcePage":14},{"front":"manufactured grape juice","meaning":"工業生產的葡萄汁","examples":[{"en":"The compound was used in manufactured grape juice.","zh":"這種化合物被用於工業生產的葡萄汁。"},{"en":"Manufactured grape juice is grape juice made in factories rather than freshly squeezed at home.","zh":"manufactured grape juice 是在工廠製造、而不是在家新鮮榨取的葡萄汁。"},{"en":"Manufactured grape juice may need flavour control so every bottle tastes similar.","zh":"工業生產的葡萄汁可能需要風味控制，使每瓶味道相似。"},{"en":"If manufactured grape juice contains flavour compounds, it can taste more strongly of grapes.","zh":"如果工業生產的葡萄汁含有風味化合物，它可以有更強葡萄味。"},{"en":"The phrase refers to industrially produced juice.","zh":"這個短語指工業方式生產的果汁。"}],"source":"135 - The sense of flavour.pdf","sourcePage":14},{"front":"the quality that people seek most","meaning":"人們最追求的特質","examples":[{"en":"Flavour is the quality that people seek most in food.","zh":"風味是人們在食物中最追求的特質。"},{"en":"The quality that people seek most is the feature they value or want above all others.","zh":"the quality that people seek most 是人們最重視或最想要的特徵。"},{"en":"In a winter coat, warmth may be the quality that people seek most.","zh":"在冬天外套中，保暖可能是人們最追求的特質。"},{"en":"If flavour is the quality people seek most in food, companies must make products taste good.","zh":"如果風味是人們在食物中最追求的特質，公司就必須令產品好味。"},{"en":"The phrase highlights the most important desired feature.","zh":"這個短語突出最重要的理想特徵。"}],"source":"135 - The sense of flavour.pdf","sourcePage":14},{"front":"be present in","meaning":"存在於","examples":[{"en":"Flavour may be present in extremely tiny quantities.","zh":"風味可能以極微小分量存在。"},{"en":"To be present in something means to exist or be found there.","zh":"be present in 某物，意思是存在於或可在其中找到。"},{"en":"Vitamin C is present in oranges and many other fruits.","zh":"維他命C存在於橙和許多其他水果中。"},{"en":"If a chemical is present in food in tiny amounts, special equipment may be needed to detect it.","zh":"如果某化學物以極微量存在於食物中，可能需要特殊設備才能偵測。"},{"en":"The phrase tells us where something exists.","zh":"這個短語告訴我們某物存在於哪裏。"}],"source":"135 - The sense of flavour.pdf","sourcePage":14},{"front":"too infinitesimal to","meaning":"微小得不能","examples":[{"en":"The amount of flavour may be too infinitesimal to measure traditionally.","zh":"風味分量可能微小得不能用傳統方式量度。"},{"en":"Too infinitesimal to do something means too extremely small for that action to be possible.","zh":"too infinitesimal to do something 指微小到無法做到某事。"},{"en":"Some dust particles are too infinitesimal to see with the naked eye.","zh":"一些塵粒微小得不能用肉眼看見。"},{"en":"If a flavour chemical is too infinitesimal to measure with teaspoons, machines must measure it instead.","zh":"如果風味化學物微小得不能用茶匙量度，就必須由機器量度。"},{"en":"The phrase emphasises extremely tiny size or amount.","zh":"這個短語強調極微小的大小或數量。"}],"source":"135 - The sense of flavour.pdf","sourcePage":14},{"front":"be measured by","meaning":"由……量度","examples":[{"en":"The quantity is too small to be measured by traditional culinary terms.","zh":"這個數量太小，不能由傳統烹飪用語量度。"},{"en":"To be measured by something means to have its amount, size, or value checked using that method or unit.","zh":"be measured by 某物，指用某方法或單位檢查其數量、大小或價值。"},{"en":"Temperature is measured by a thermometer.","zh":"溫度由溫度計量度。"},{"en":"If flavour chemicals cannot be measured by spoons, scientists use more precise tools.","zh":"如果風味化學物不能由匙羹量度，科學家會使用更精密工具。"},{"en":"The phrase explains the method or standard used for measurement.","zh":"這個短語解釋用作量度的方法或標準。"}],"source":"135 - The sense of flavour.pdf","sourcePage":14},{"front":"traditional culinary terms","meaning":"傳統烹飪用語","examples":[{"en":"Ounces and teaspoons are traditional culinary terms.","zh":"盎司和茶匙是傳統烹飪用語。"},{"en":"Traditional culinary terms are common cooking words or measurements used in kitchens.","zh":"traditional culinary terms 是廚房中常用的烹飪詞語或量度單位。"},{"en":"Cups, tablespoons, and pinches are traditional culinary terms in many recipes.","zh":"杯、湯匙和一撮都是許多食譜中的傳統烹飪用語。"},{"en":"If chemicals are extremely tiny, traditional culinary terms may not be precise enough.","zh":"如果化學物極微小，傳統烹飪用語可能不夠精確。"},{"en":"The phrase connects language with cooking practice.","zh":"這個短語把語言與烹飪實踐連繫起來。"}],"source":"135 - The sense of flavour.pdf","sourcePage":14},{"front":"ounces or teaspoons","meaning":"盎司或茶匙","examples":[{"en":"Flavour chemicals may be too tiny to measure in ounces or teaspoons.","zh":"風味化學物可能微小得不能用盎司或茶匙量度。"},{"en":"Ounces or teaspoons are common cooking measurements for larger amounts of ingredients.","zh":"ounces or teaspoons 是用於較大量食材的常見烹飪量度。"},{"en":"A recipe may ask for two ounces of butter or three teaspoons of sugar.","zh":"食譜可能要求兩盎司牛油或三茶匙糖。"},{"en":"If flavour chemicals are measured in parts per billion, ounces or teaspoons are too rough.","zh":"如果風味化學物以十億分之一計量，盎司或茶匙就太粗略。"},{"en":"The phrase represents everyday kitchen measurement.","zh":"這個短語代表日常廚房量度方式。"}],"source":"135 - The sense of flavour.pdf","sourcePage":14},{"front":"sophisticated spectrometers","meaning":"精密光譜儀","examples":[{"en":"Sophisticated spectrometers can analyse flavour components.","zh":"精密光譜儀可以分析風味成分。"},{"en":"Sophisticated spectrometers are advanced scientific instruments that measure substances by analysing light or energy patterns.","zh":"sophisticated spectrometers 是透過分析光或能量模式來量度物質的先進科學儀器。"},{"en":"A laboratory may use sophisticated spectrometers to identify tiny chemicals in food.","zh":"實驗室可能使用精密光譜儀識別食物中的微小化學物。"},{"en":"If flavour components are too small for normal tools, sophisticated spectrometers can provide clearer data.","zh":"如果風味成分太小，普通工具無法處理，精密光譜儀可以提供更清晰數據。"},{"en":"The phrase suggests precise, high-level scientific equipment.","zh":"這個短語暗示精準而高階的科學設備。"}],"source":"135 - The sense of flavour.pdf","sourcePage":15},{"front":"gas chromatographs","meaning":"氣相色譜儀","examples":[{"en":"Gas chromatographs help analyse food aromas.","zh":"氣相色譜儀幫助分析食物香氣。"},{"en":"Gas chromatographs are scientific instruments that separate and identify chemicals in gases.","zh":"gas chromatographs 是分離並識別氣體中化學物質的科學儀器。"},{"en":"Food scientists may use gas chromatographs to study the aroma of coffee.","zh":"食品科學家可能使用氣相色譜儀研究咖啡香氣。"},{"en":"If a food smell contains many chemicals, gas chromatographs help separate them for analysis.","zh":"如果食物氣味含有許多化學物，氣相色譜儀可幫助把它們分離作分析。"},{"en":"The phrase is technical and often appears in chemistry and food science.","zh":"這個短語較技術性，常見於化學和食品科學。"}],"source":"135 - The sense of flavour.pdf","sourcePage":15},{"front":"headspace vapour analysers","meaning":"頂空蒸氣分析儀","examples":[{"en":"Headspace vapour analysers detect tiny amounts of aroma chemicals.","zh":"頂空蒸氣分析儀偵測極微量的香氣化學物。"},{"en":"Headspace vapour analysers are instruments that examine gases above a food or liquid sample.","zh":"headspace vapour analysers 是檢查食物或液體樣本上方氣體的儀器。"},{"en":"A lab may use headspace vapour analysers to study the smell released from packaged juice.","zh":"實驗室可能使用頂空蒸氣分析儀研究包裝果汁釋放出的氣味。"},{"en":"If only a tiny amount of aroma is present, headspace vapour analysers can help detect it.","zh":"如果只存在極微量香氣，頂空蒸氣分析儀可以幫助偵測。"},{"en":"The phrase describes specialised equipment for analysing smell.","zh":"這個短語描述用於分析氣味的專門設備。"}],"source":"135 - The sense of flavour.pdf","sourcePage":15},{"front":"provide a detailed map of","meaning":"提供……的詳細圖譜","examples":[{"en":"Modern machines provide a detailed map of flavour components.","zh":"現代機器提供風味成分的詳細圖譜。"},{"en":"To provide a detailed map of something means to show its parts clearly and systematically.","zh":"provide a detailed map of 某物，指清楚而有系統地展示其各部分。"},{"en":"A budget spreadsheet can provide a detailed map of a family’s spending.","zh":"預算試算表可以提供家庭開支的詳細圖譜。"},{"en":"If machines provide a detailed map of aroma chemicals, scientists can understand flavour more accurately.","zh":"如果機器提供香氣化學物的詳細圖譜，科學家可以更準確理解風味。"},{"en":"The phrase means giving a clear breakdown, not always a literal map.","zh":"這個短語指提供清楚分解，不一定是字面地圖。"}],"source":"135 - The sense of flavour.pdf","sourcePage":15},{"front":"flavour components","meaning":"風味成分","examples":[{"en":"Modern technology can identify flavour components in food.","zh":"現代科技可以識別食物中的風味成分。"},{"en":"Flavour components are the separate substances or qualities that together create a food’s flavour.","zh":"flavour components 是共同創造食物風味的不同物質或特質。"},{"en":"Coffee has many flavour components, including bitter, roasted, sweet, and smoky notes.","zh":"咖啡有許多風味成分，包括苦、烘焙、甜和煙燻味。"},{"en":"If one flavour component is too strong, the whole product may taste unbalanced.","zh":"如果某一風味成分太強，整個產品味道可能不平衡。"},{"en":"The phrase helps explain flavour as a mixture of many parts.","zh":"這個短語幫助把風味解釋為許多部分的混合。"}],"source":"135 - The sense of flavour.pdf","sourcePage":15},{"front":"detect chemical aromas","meaning":"偵測化學氣味","examples":[{"en":"Modern instruments detect chemical aromas in tiny amounts.","zh":"現代儀器能以極微量偵測化學氣味。"},{"en":"To detect chemical aromas means to notice or measure smell-producing chemicals.","zh":"detect chemical aromas 指察覺或量度產生氣味的化學物。"},{"en":"Food labs detect chemical aromas to check whether a product smells fresh.","zh":"食品實驗室偵測化學氣味，以檢查產品聞起來是否新鮮。"},{"en":"If machines detect chemical aromas at very low levels, companies can improve flavour control.","zh":"如果機器能在極低水平偵測化學氣味，公司可以改善風味控制。"},{"en":"The phrase is common in scientific testing of smells.","zh":"這個短語常見於氣味的科學測試。"}],"source":"135 - The sense of flavour.pdf","sourcePage":15},{"front":"amounts as low as","meaning":"低至……的分量","examples":[{"en":"Machines can detect aromas in amounts as low as one part per billion.","zh":"機器可以偵測低至十億分之一的香氣分量。"},{"en":"Amounts as low as means quantities that are extremely small, down to the stated level.","zh":"amounts as low as 指數量極小，低至所說的水平。"},{"en":"Some water tests can detect pollution in amounts as low as a few drops in a pool.","zh":"一些水質測試可以偵測低至泳池中幾滴的污染物。"},{"en":"If instruments detect chemicals in amounts as low as one part per billion, they are highly sensitive.","zh":"如果儀器能偵測低至十億分之一的化學物，它們就非常靈敏。"},{"en":"The phrase emphasises how tiny a detectable amount can be.","zh":"這個短語強調可偵測分量可以多麼微小。"}],"source":"135 - The sense of flavour.pdf","sourcePage":15},{"front":"one part per billion","meaning":"十億分之一","examples":[{"en":"Some machines can detect chemicals at one part per billion.","zh":"一些機器可以偵測十億分之一水平的化學物。"},{"en":"One part per billion means one unit of a substance in one billion units of mixture.","zh":"one part per billion 指十億份混合物中有一份某物質。"},{"en":"A pollutant at one part per billion is extremely tiny but may still be measurable.","zh":"十億分之一水平的污染物極微小，但仍可能被量度。"},{"en":"If a flavour chemical is detected at one part per billion, normal kitchen measures cannot describe it well.","zh":"如果風味化學物以十億分之一被偵測，普通廚房量度方式很難描述它。"},{"en":"The phrase is used for very small concentrations.","zh":"這個短語用於非常小的濃度。"}],"source":"135 - The sense of flavour.pdf","sourcePage":15},{"front":"more sensitive than","meaning":"比……更靈敏","examples":[{"en":"The human nose is more sensitive than any machine yet invented.","zh":"人類鼻子比至今發明的任何機器更靈敏。"},{"en":"More sensitive than means better able to notice very small changes or amounts.","zh":"more sensitive than 指更能察覺非常微小的變化或分量。"},{"en":"A good smoke alarm is more sensitive than a person sleeping in another room.","zh":"好的煙霧警報器比睡在另一房間的人更靈敏。"},{"en":"If the nose is more sensitive than machines, humans can detect some aromas machines may miss.","zh":"如果鼻子比機器更靈敏，人類可以偵測到一些機器可能錯過的香氣。"},{"en":"The phrase compares detection ability.","zh":"這個短語比較偵測能力。"}],"source":"135 - The sense of flavour.pdf","sourcePage":15},{"front":"any machine yet invented","meaning":"至今發明的任何機器","examples":[{"en":"The human nose is more sensitive than any machine yet invented.","zh":"人類鼻子比至今發明的任何機器更靈敏。"},{"en":"Any machine yet invented means any machine that humans have created up to now.","zh":"any machine yet invented 指人類到目前為止創造的任何機器。"},{"en":"No camera yet invented can fully copy the way human eyes and brains experience a sunset.","zh":"至今發明的任何相機都不能完全複製人眼和大腦體驗日落的方式。"},{"en":"If the nose beats any machine yet invented, biological senses remain impressively powerful.","zh":"如果鼻子勝過至今發明的任何機器，生物感官仍然非常強大。"},{"en":"The phrase sets a comparison against all existing technology.","zh":"這個短語把比較對象設定為所有現有科技。"}],"source":"135 - The sense of flavour.pdf","sourcePage":15},{"front":"a few parts per trillion","meaning":"幾萬億分之一","examples":[{"en":"The nose can detect aromas in quantities of a few parts per trillion.","zh":"鼻子可以偵測幾萬億分之一分量的香氣。"},{"en":"A few parts per trillion means only a few units of a substance in one trillion units of mixture.","zh":"a few parts per trillion 指一萬億份混合物中只有幾份某物質。"},{"en":"Detecting a few parts per trillion is like noticing a nearly invisible amount in a huge mixture.","zh":"偵測幾萬億分之一就像在巨大混合物中察覺幾乎看不見的分量。"},{"en":"If the nose can detect a few parts per trillion, it is extremely sensitive.","zh":"如果鼻子能偵測幾萬億分之一，它就極其靈敏。"},{"en":"The phrase describes an incredibly tiny concentration.","zh":"這個短語描述極其微小的濃度。"}],"source":"135 - The sense of flavour.pdf","sourcePage":15},{"front":"complex aromas","meaning":"複雜香氣","examples":[{"en":"Complex aromas may involve many different chemicals.","zh":"複雜香氣可能涉及許多不同化學物質。"},{"en":"Complex aromas are smells made from many different scent components working together.","zh":"complex aromas 是由許多不同氣味成分共同組成的氣味。"},{"en":"Freshly baked bread has complex aromas because it can smell warm, sweet, toasted, and buttery.","zh":"新鮮焗麵包有複雜香氣，因為它可以聞起來溫暖、甜、烘烤和帶牛油香。"},{"en":"If complex aromas contain many chemicals, they are difficult to recreate exactly.","zh":"如果複雜香氣含有許多化學物，它們就難以被完全重現。"},{"en":"The phrase describes rich smells with several layers.","zh":"這個短語描述有多層次的濃郁氣味。"}],"source":"135 - The sense of flavour.pdf","sourcePage":16},{"front":"roasted meat","meaning":"烤肉","examples":[{"en":"The aroma of roasted meat may contain many chemical gases.","zh":"烤肉的香氣可能含有許多化學氣體。"},{"en":"Roasted meat is meat cooked with dry heat until it becomes browned and strongly flavoured.","zh":"roasted meat 是以乾熱烹調至變啡並有濃郁味道的肉。"},{"en":"The smell of roasted meat can fill a kitchen before dinner.","zh":"晚餐前，烤肉的氣味可以充滿廚房。"},{"en":"If roasted meat is cooked slowly, its aroma may become richer.","zh":"如果烤肉慢慢烹調，其香氣可能變得更濃郁。"},{"en":"The phrase describes a cooked food and its strong savoury smell.","zh":"這個短語描述一種熟食及其強烈鹹香氣味。"}],"source":"135 - The sense of flavour.pdf","sourcePage":16},{"front":"be composed of","meaning":"由……組成","examples":[{"en":"Complex aromas may be composed of gases from many chemicals.","zh":"複雜香氣可能由許多化學物釋放的氣體組成。"},{"en":"To be composed of something means to be made up of those parts.","zh":"be composed of 某物，意思是由那些部分構成。"},{"en":"A class may be composed of students from several different countries.","zh":"一個班級可能由來自多個不同國家的學生組成。"},{"en":"If an aroma is composed of many chemicals, changing one part can change the whole smell.","zh":"如果香氣由許多化學物組成，改變其中一部分可以改變整體氣味。"},{"en":"The phrase explains what something consists of.","zh":"這個短語解釋某物由甚麼構成。"}],"source":"135 - The sense of flavour.pdf","sourcePage":16},{"front":"nearly a thousand different chemicals","meaning":"近千種不同化學物質","examples":[{"en":"Coffee aroma may involve nearly a thousand different chemicals.","zh":"咖啡香氣可能涉及近千種不同化學物質。"},{"en":"Nearly a thousand different chemicals means almost one thousand separate chemical substances.","zh":"nearly a thousand different chemicals 指接近一千種不同化學物質。"},{"en":"A complex natural smell may contain nearly a thousand different chemicals working together.","zh":"複雜的天然氣味可能含有近千種不同化學物質共同作用。"},{"en":"If coffee aroma includes nearly a thousand different chemicals, copying it exactly is difficult.","zh":"如果咖啡香氣包括近千種不同化學物質，完全複製它就很困難。"},{"en":"The phrase emphasises the extreme complexity of an aroma.","zh":"這個短語強調香氣極其複雜。"}],"source":"135 - The sense of flavour.pdf","sourcePage":16},{"front":"dominant flavour","meaning":"主要味道","examples":[{"en":"One chemical can provide the dominant flavour of bell pepper.","zh":"一種化學物可以提供甜椒的主要味道。"},{"en":"Dominant flavour is the strongest or most noticeable taste in a food.","zh":"dominant flavour 是食物中最強或最明顯的味道。"},{"en":"Garlic may be the dominant flavour in a sauce if too much is added.","zh":"如果加入太多蒜，蒜味可能成為醬汁的主要味道。"},{"en":"If one chemical creates the dominant flavour, a tiny amount can shape the whole food experience.","zh":"如果一種化學物創造主要味道，極少分量也能塑造整個食物體驗。"},{"en":"The phrase identifies the flavour that stands out most.","zh":"這個短語指出最突出的味道。"}],"source":"135 - The sense of flavour.pdf","sourcePage":16},{"front":"bell pepper","meaning":"甜椒","examples":[{"en":"The dominant flavour of bell pepper can be detected in tiny amounts.","zh":"甜椒的主要味道可以在極微量中被偵測。"},{"en":"Bell pepper is a mild, crisp vegetable that can be green, red, yellow, or orange.","zh":"bell pepper 是溫和爽脆的蔬菜，可以是綠色、紅色、黃色或橙色。"},{"en":"Bell pepper is often added to salads, stir-fries, and pizzas.","zh":"甜椒常被加入沙律、炒菜和薄餅中。"},{"en":"If bell pepper flavour is strong, even a small piece can affect a dish.","zh":"如果甜椒味強，即使一小塊也可以影響一道菜。"},{"en":"The phrase refers to sweet pepper, not hot chilli pepper.","zh":"這個短語指甜椒，而不是辣椒。"}],"source":"135 - The sense of flavour.pdf","sourcePage":16},{"front":"be tasted in amounts as low as","meaning":"以低至……的分量被嚐到","examples":[{"en":"The chemical can be tasted in amounts as low as 0.02 parts per billion.","zh":"這種化學物可以以低至十億分之0.02的分量被嚐到。"},{"en":"To be tasted in amounts as low as a level means people can notice the taste even at that tiny concentration.","zh":"be tasted in amounts as low as 某水平，指人們即使在那麼低濃度也能嚐到味道。"},{"en":"Some bitter chemicals can be tasted in amounts as low as a few parts per billion.","zh":"一些苦味化學物可以以低至幾十億分之一的分量被嚐到。"},{"en":"If a flavour can be tasted in amounts as low as this, it is extremely powerful.","zh":"如果一種風味可以以如此低的分量被嚐到，它就極其強烈。"},{"en":"The phrase describes how sensitive human taste or smell can be.","zh":"這個短語描述人類味覺或嗅覺可以多麼靈敏。"}],"source":"135 - The sense of flavour.pdf","sourcePage":16},{"front":"one drop is sufficient to","meaning":"一滴已足以","examples":[{"en":"One drop is sufficient to flavour an enormous amount of water.","zh":"一滴已足以為大量水調味。"},{"en":"One drop is sufficient to do something means only one drop is enough to produce the result.","zh":"one drop is sufficient to do something 指只需一滴就足以產生結果。"},{"en":"One drop of strong food colouring is sufficient to turn a bowl of icing pink.","zh":"一滴濃縮食用色素已足以把一碗糖霜變成粉紅色。"},{"en":"If one drop is sufficient to flavour many litres of water, the chemical is extremely concentrated.","zh":"如果一滴已足以為許多公升水調味，該化學物就極其濃縮。"},{"en":"The phrase emphasises how powerful a tiny amount can be.","zh":"這個短語強調極少分量可以多麼有力。"}],"source":"135 - The sense of flavour.pdf","sourcePage":16},{"front":"average-sized swimming pools","meaning":"一般大小的泳池","examples":[{"en":"One drop can flavour the water needed to fill five average-sized swimming pools.","zh":"一滴可以為裝滿五個一般大小泳池所需的水調味。"},{"en":"Average-sized swimming pools are swimming pools of ordinary or typical size.","zh":"average-sized swimming pools 是普通或典型大小的泳池。"},{"en":"A school may have one or two average-sized swimming pools for lessons and training.","zh":"學校可能有一兩個一般大小的泳池作課堂和訓練之用。"},{"en":"If one drop affects five average-sized swimming pools, the flavour chemical is incredibly strong.","zh":"如果一滴影響五個一般大小的泳池，該風味化學物就強得驚人。"},{"en":"The phrase helps readers imagine a very large amount of water.","zh":"這個短語幫助讀者想像非常大量的水。"}],"source":"135 - The sense of flavour.pdf","sourcePage":16},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"The task asks whether the statements agree with the information in the passage.","zh":"題目問以下陳述是否與文章中的資料一致。"},{"en":"Do the following statements agree with means students must check whether the statements match the text.","zh":"do the following statements agree with 指學生必須檢查陳述是否與文本相符。"},{"en":"In reading exams, this instruction asks students to compare each statement with the passage carefully.","zh":"在閱讀考試中，這個指示要求學生仔細把每項陳述與文章比較。"},{"en":"If a statement agrees with the passage, it should not contradict or add unsupported information.","zh":"如果陳述與文章一致，它不應與文本矛盾或加入無根據資料。"},{"en":"The phrase introduces a true, false, or not given type of task.","zh":"這個短語引入 TRUE、FALSE 或 NOT GIVEN 類型的題目。"}],"source":"135 - The sense of flavour.pdf","sourcePage":16},{"front":"information given in","meaning":"……中提供的資料","examples":[{"en":"Candidates compare each statement with the information given in the passage.","zh":"考生把每項陳述與文章中提供的資料比較。"},{"en":"Information given in a text means the facts or details actually stated there.","zh":"information given in 文本，指其中實際陳述的事實或細節。"},{"en":"Students should use only the information given in the article when answering the question.","zh":"學生回答問題時應只使用文章中提供的資料。"},{"en":"If an answer is not supported by information given in the passage, it may be wrong.","zh":"如果答案沒有文章中提供的資料支持，它可能是錯的。"},{"en":"The phrase reminds candidates to rely on the source text.","zh":"這個短語提醒考生依靠來源文本。"}],"source":"135 - The sense of flavour.pdf","sourcePage":16},{"front":"write TRUE if","meaning":"如……則寫TRUE","examples":[{"en":"Students write TRUE if the statement agrees with the information.","zh":"如果陳述與資料一致，學生則寫TRUE。"},{"en":"Write TRUE if means mark the answer TRUE when the condition is met.","zh":"write TRUE if 指當條件符合時，把答案標記為 TRUE。"},{"en":"Write TRUE if the sentence says the same thing as the passage.","zh":"如果句子與文章意思相同，則寫 TRUE。"},{"en":"If students write TRUE without checking exact meaning, they may miss a contradiction.","zh":"如果學生未檢查準確意思就寫 TRUE，可能錯過矛盾。"},{"en":"The phrase is a direct exam instruction.","zh":"這個短語是直接的考試指示。"}],"source":"135 - The sense of flavour.pdf","sourcePage":17},{"front":"contradict the information","meaning":"與資料矛盾","examples":[{"en":"A statement is false if it contradicts the information in the passage.","zh":"如果陳述與文章中的資料矛盾，它就是 false。"},{"en":"To contradict the information means to say the opposite of what the source says.","zh":"contradict the information 指說出與來源資料相反的內容。"},{"en":"If a passage says the shop opens at nine, “it opens at ten” contradicts the information.","zh":"如果文章說商店九點開門，「它十點開門」就與資料矛盾。"},{"en":"Students should choose FALSE only when the statement clearly contradicts the text.","zh":"學生只應在陳述明確與文本矛盾時選 FALSE。"},{"en":"The phrase is important for distinguishing FALSE from NOT GIVEN.","zh":"這個短語對區分 FALSE 和 NOT GIVEN 很重要。"}],"source":"135 - The sense of flavour.pdf","sourcePage":17},{"front":"there is no information on this","meaning":"文中沒有相關資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果文中沒有相關資料，學生寫 NOT GIVEN。"},{"en":"There is no information on this means the passage does not tell us about that point.","zh":"there is no information on this 指文章沒有告訴我們該點。"},{"en":"If the passage describes a school but not its fees, there is no information on this topic.","zh":"如果文章描述一間學校但沒有提及學費，文中就沒有這方面資料。"},{"en":"Students should not guess TRUE or FALSE when there is no information on this in the text.","zh":"當文本沒有相關資料時，學生不應猜 TRUE 或 FALSE。"},{"en":"The phrase signals that the source is silent about the issue.","zh":"這個短語表示來源對該議題沒有說明。"}],"source":"135 - The sense of flavour.pdf","sourcePage":17},{"front":"be aware of","meaning":"意識到；察覺到","examples":[{"en":"The brain determines which aromas we are aware of.","zh":"大腦決定我們意識到哪些香氣。"},{"en":"To be aware of something means to notice it or know that it exists.","zh":"be aware of 某事，意思是注意到它或知道它存在。"},{"en":"Drivers must be aware of cyclists before turning.","zh":"司機轉彎前必須察覺到單車。"},{"en":"If we are not aware of a smell, it may still be present around us.","zh":"如果我們沒有意識到某種氣味，它仍可能存在於周圍。"},{"en":"The phrase describes conscious notice or knowledge.","zh":"這個短語描述有意識的注意或知道。"}],"source":"135 - The sense of flavour.pdf","sourcePage":17},{"front":"as efficient as","meaning":"與……一樣有效率","examples":[{"en":"The question asks whether taste is as efficient as smell.","zh":"題目問味覺是否與嗅覺一樣有效率。"},{"en":"As efficient as means working equally well or using effort equally effectively.","zh":"as efficient as 指運作得同樣好或同樣有效使用力氣。"},{"en":"Online booking can be as efficient as phone booking if the system is clear.","zh":"如果系統清晰，網上預約可以與電話預約一樣有效率。"},{"en":"If taste is not as efficient as smell, smell gives more information about flavour.","zh":"如果味覺不如嗅覺有效率，嗅覺就提供更多風味資料。"},{"en":"The phrase compares how well two things perform.","zh":"這個短語比較兩件事的表現效率。"}],"source":"135 - The sense of flavour.pdf","sourcePage":17},{"front":"personal tastes in food","meaning":"個人口味","examples":[{"en":"Personal tastes in food are developed early in life.","zh":"個人口味在人生早期形成。"},{"en":"Personal tastes in food are individual preferences for certain foods or flavours.","zh":"personal tastes in food 是個人對某些食物或風味的喜好。"},{"en":"One person’s personal tastes in food may include spicy noodles, while another prefers plain soup.","zh":"一個人的個人口味可能包括辣麵，而另一個人偏好清湯。"},{"en":"If personal tastes in food form early, family meals can have a long-term effect.","zh":"如果個人口味早期形成，家庭膳食可以有長期影響。"},{"en":"The phrase focuses on individual likes and dislikes.","zh":"這個短語重點在個人的喜好與厭惡。"}],"source":"135 - The sense of flavour.pdf","sourcePage":17},{"front":"be developed in infancy","meaning":"在嬰兒期形成","examples":[{"en":"Some food preferences are developed in infancy.","zh":"一些食物喜好在嬰兒期形成。"},{"en":"To be developed in infancy means to begin forming when a person is a baby.","zh":"be developed in infancy 指在一個人還是嬰兒時開始形成。"},{"en":"Some emotional bonds are developed in infancy through regular care and touch.","zh":"一些情感連繫透過定期照顧和觸摸在嬰兒期形成。"},{"en":"If food preferences are developed in infancy, early feeding experiences matter.","zh":"如果食物喜好在嬰兒期形成，早期餵食經驗就很重要。"},{"en":"The phrase highlights the baby stage as an important period of development.","zh":"這個短語強調嬰兒階段是重要發展時期。"}],"source":"135 - The sense of flavour.pdf","sourcePage":17},{"front":"on one’s travels","meaning":"在某人的旅途中","examples":[{"en":"The question asks whether Columbus found spices on his travels.","zh":"題目問 Columbus 是否在旅途中找到香料。"},{"en":"On one’s travels means during the journeys that a person makes.","zh":"on one’s travels 指在某人進行的旅程期間。"},{"en":"She met many kind families on her travels through Europe.","zh":"她在歐洲旅途中遇到許多友善家庭。"},{"en":"If explorers found spices on their travels, those discoveries could change trade routes.","zh":"如果探險家在旅途中找到香料，這些發現可以改變貿易路線。"},{"en":"The phrase is often used for experiences gained while travelling.","zh":"這個短語常用於旅行期間獲得的經歷。"}],"source":"135 - The sense of flavour.pdf","sourcePage":17},{"front":"on purpose","meaning":"故意地；有意地","examples":[{"en":"The question asks whether artificial flavours were invented on purpose.","zh":"題目問人工香料是否被故意發明。"},{"en":"On purpose means deliberately or intentionally.","zh":"on purpose 指故意地或有意地。"},{"en":"The child did not break the cup on purpose; it slipped from his hand.","zh":"孩子不是故意打破杯子；杯子從他手中滑落。"},{"en":"If a scientist creates a flavour on purpose, the discovery is planned, not accidental.","zh":"如果科學家有意地創造一種風味，該發現就是計劃中的，而非偶然。"},{"en":"The phrase contrasts with by accident.","zh":"這個短語與 by accident 形成對比。"}],"source":"135 - The sense of flavour.pdf","sourcePage":17},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Candidates complete the summary below with words from the passage.","zh":"考生用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in the missing words in the short text that follows.","zh":"complete the summary below 指填寫接下來短文中的空缺字詞。"},{"en":"In reading practice, students complete the summary below by finding exact words in the article.","zh":"在閱讀練習中，學生透過在文章中找原字完成以下摘要。"},{"en":"If students choose words that do not fit grammatically, the summary may be wrong.","zh":"如果學生選擇文法上不合適的字，摘要可能錯誤。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"135 - The sense of flavour.pdf","sourcePage":17},{"front":"choose one word from","meaning":"從……選出一個字","examples":[{"en":"Candidates choose one word from the passage for each answer.","zh":"考生從文章中為每個答案選出一個字。"},{"en":"Choose one word from means select exactly one word from a given source.","zh":"choose one word from 指從指定來源中選出剛好一個字。"},{"en":"If the instruction says choose one word from the text, students should not write two words.","zh":"如果指示說從文本中選出一個字，學生不應寫兩個字。"},{"en":"Choosing one word from the passage requires careful checking of meaning and grammar.","zh":"從文章中選出一個字需要仔細檢查意思和文法。"},{"en":"The phrase sets both the source and the word limit.","zh":"這個短語同時設定來源和字數限制。"}],"source":"135 - The sense of flavour.pdf","sourcePage":17},{"front":"it is thought that","meaning":"人們認為","examples":[{"en":"It is thought that taste developed to protect people from poison.","zh":"人們認為味覺是為保護人免受毒害而發展出來的。"},{"en":"It is thought that means people generally believe or experts suggest something is true.","zh":"it is thought that 指人們普遍相信或專家提出某事為真。"},{"en":"It is thought that regular sleep helps memory become stronger.","zh":"人們認為規律睡眠有助記憶變得更強。"},{"en":"If it is thought that taste protects us, scientists may study taste as a survival tool.","zh":"如果人們認為味覺保護我們，科學家可能把味覺作為生存工具來研究。"},{"en":"The phrase presents an idea carefully without saying it is absolutely proven.","zh":"這個短語謹慎提出想法，而不是說它絕對已證實。"}],"source":"135 - The sense of flavour.pdf","sourcePage":18},{"front":"harmless from those that are","meaning":"無害的與……的","examples":[{"en":"Taste helps distinguish foods that are harmless from those that are dangerous.","zh":"味覺幫助區分無害食物和危險食物。"},{"en":"Harmless from those that are dangerous means separating safe things from dangerous ones.","zh":"harmless from those that are dangerous 指把安全的東西與危險的東西分開。"},{"en":"Children must learn to tell harmless insects from those that are poisonous.","zh":"孩子必須學會分辨無害昆蟲和有毒昆蟲。"},{"en":"If taste helps separate harmless foods from dangerous ones, it can protect health.","zh":"如果味覺幫助區分無害食物和危險食物，它就可以保護健康。"},{"en":"The phrase is part of a comparison between two groups.","zh":"這個短語是兩個群體比較的一部分。"}],"source":"135 - The sense of flavour.pdf","sourcePage":18},{"front":"the sense of smell","meaning":"嗅覺","examples":[{"en":"The sense of smell gives us most of the flavour we detect in food.","zh":"嗅覺給予我們在食物中偵測到的大部分風味。"},{"en":"The sense of smell is the ability to notice odours through the nose.","zh":"the sense of smell 是透過鼻子察覺氣味的能力。"},{"en":"The sense of smell helps people enjoy coffee, flowers, and freshly baked bread.","zh":"嗅覺幫助人享受咖啡、花和新鮮焗麵包。"},{"en":"If the sense of smell is lost, food may seem less flavourful.","zh":"如果失去嗅覺，食物可能顯得較少風味。"},{"en":"The phrase refers to smelling ability, not tasting with the tongue.","zh":"這個短語指聞氣味的能力，而不是用舌頭品嚐。"}],"source":"135 - The sense of flavour.pdf","sourcePage":18},{"front":"prompted many explorers to","meaning":"促使許多探險家去","examples":[{"en":"The craving for flavour prompted many explorers to travel.","zh":"對風味的渴求促使許多探險家去旅行。"},{"en":"Prompted many explorers to means caused or encouraged many explorers to do something.","zh":"prompted many explorers to 指造成或鼓勵許多探險家去做某事。"},{"en":"New trade opportunities prompted many merchants to cross dangerous seas.","zh":"新貿易機會促使許多商人橫越危險海洋。"},{"en":"If spices prompted many explorers to travel, flavour helped shape world history.","zh":"如果香料促使許多探險家去旅行，風味就幫助塑造世界歷史。"},{"en":"The phrase shows a cause that leads people to act.","zh":"這個短語顯示導致人們行動的原因。"}],"source":"135 - The sense of flavour.pdf","sourcePage":18},{"front":"distant lands","meaning":"遙遠土地","examples":[{"en":"Explorers travelled to distant lands in search of spices.","zh":"探險家前往遙遠土地尋找香料。"},{"en":"Distant lands are places far away from where someone lives or starts travelling.","zh":"distant lands 是遠離某人居住或出發地的地方。"},{"en":"Stories about distant lands can make children curious about geography.","zh":"關於遙遠土地的故事可以令孩子對地理好奇。"},{"en":"If traders travelled to distant lands, journeys took time, money, and courage.","zh":"如果商人前往遙遠土地，旅程需要時間、金錢和勇氣。"},{"en":"The phrase often appears in travel, history, and exploration contexts.","zh":"這個短語常出現在旅行、歷史和探索語境中。"}],"source":"135 - The sense of flavour.pdf","sourcePage":18},{"front":"bring back","meaning":"帶回","examples":[{"en":"Explorers wanted to bring back new seasonings.","zh":"探險家想帶回新調味料。"},{"en":"To bring back something means to return with it or make it available again.","zh":"bring back 某物，意思是帶着它回來或讓它再次出現。"},{"en":"Tourists often bring back snacks or gifts from another country.","zh":"遊客常從另一個國家帶回零食或禮物。"},{"en":"If explorers brought back spices, they could sell them at high prices.","zh":"如果探險家帶回香料，他們可以高價出售。"},{"en":"The phrase can mean physically returning with something or restoring something old.","zh":"這個短語可以指實際帶回某物，也可以指恢復舊事物。"}],"source":"135 - The sense of flavour.pdf","sourcePage":18},{"front":"greatly sought after","meaning":"極受追捧","examples":[{"en":"Spices were greatly sought after in Europe.","zh":"香料在歐洲極受追捧。"},{"en":"Greatly sought after means strongly wanted by many people.","zh":"greatly sought after 指被許多人強烈想要。"},{"en":"A teacher with strong exam experience may be greatly sought after by parents.","zh":"有豐富考試經驗的老師可能極受家長追捧。"},{"en":"If spices were greatly sought after, traders could charge high prices for them.","zh":"如果香料極受追捧，商人可以為它們收取高價。"},{"en":"The phrase describes high demand and strong desirability.","zh":"這個短語描述高需求和強吸引力。"}],"source":"135 - The sense of flavour.pdf","sourcePage":18},{"front":"rich and poor alike","meaning":"富人和窮人都一樣","examples":[{"en":"Spices improved dishes eaten by rich and poor alike.","zh":"香料改善了富人和窮人都吃的菜式。"},{"en":"Rich and poor alike means both wealthy people and poor people, without distinction.","zh":"rich and poor alike 指富裕人士和貧窮人士都一樣，沒有區分。"},{"en":"Public parks should serve rich and poor alike.","zh":"公園應服務富人和窮人都一樣。"},{"en":"If spices improved food for rich and poor alike, their appeal crossed social classes.","zh":"如果香料改善富人和窮人都吃的食物，它們的吸引力就跨越社會階層。"},{"en":"The phrase emphasises inclusion across different economic groups.","zh":"這個短語強調跨不同經濟群體的包容。"}],"source":"135 - The sense of flavour.pdf","sourcePage":18},{"front":"write no more than two words","meaning":"寫不多於兩個字","examples":[{"en":"Candidates must write no more than two words from the passage.","zh":"考生必須從文章中寫不多於兩個字。"},{"en":"Write no more than two words means the answer must contain one or two words only.","zh":"write no more than two words 指答案只能包含一個或兩個英文單字。"},{"en":"If the answer is “chemical aromas”, it fits no more than two words, but “many chemical aromas” does not.","zh":"如果答案是 chemical aromas，就符合不多於兩個字，但 many chemical aromas 就不符合。"},{"en":"Students may lose marks if they write more than two words, even with the right idea.","zh":"即使意思正確，學生如果寫超過兩個字也可能失分。"},{"en":"The phrase gives a strict answer-length rule.","zh":"這個短語給出嚴格答案長度規則。"}],"source":"135 - The sense of flavour.pdf","sourcePage":18},{"front":"associate certain smells with","meaning":"將某些氣味與……聯繫起來","examples":[{"en":"People associate certain smells with the past.","zh":"人們把某些氣味與過去聯繫起來。"},{"en":"To associate certain smells with something means to connect those smells in the mind with that thing.","zh":"associate certain smells with 某事，指在心中把那些氣味與該事連繫起來。"},{"en":"Some people associate the smell of chalk with old classrooms.","zh":"有些人把粉筆味與舊課室聯繫起來。"},{"en":"If children associate a restaurant smell with happy family meals, they may return there as adults.","zh":"如果孩子把某餐廳氣味與快樂家庭飯局聯繫起來，他們成年後可能再次光顧。"},{"en":"The phrase explains how smell becomes linked with memory or emotion.","zh":"這個短語解釋氣味如何與記憶或情感相連。"}],"source":"135 - The sense of flavour.pdf","sourcePage":18},{"front":"minute quantities of","meaning":"極微量的……","examples":[{"en":"Modern technology can detect minute quantities of flavour components.","zh":"現代科技可以偵測極微量的風味成分。"},{"en":"Minute quantities of something are extremely small amounts of it.","zh":"minute quantities of 某物，是指極小分量的該物。"},{"en":"A lab test can find minute quantities of medicine in blood.","zh":"實驗室測試可以在血液中找到極微量的藥物。"},{"en":"If food contains minute quantities of aroma chemicals, special machines may be needed to measure them.","zh":"如果食物含有極微量的香氣化學物，可能需要特殊機器量度。"},{"en":"The phrase emphasises that the amount is tiny but still important.","zh":"這個短語強調數量很小但仍然重要。"}],"source":"135 - The sense of flavour.pdf","sourcePage":18},{"front":"found in food","meaning":"食物中發現的","examples":[{"en":"Modern machines analyse chemicals found in food.","zh":"現代機器分析食物中發現的化學物質。"},{"en":"Found in food means present or existing inside food.","zh":"found in food 指存在於食物之中。"},{"en":"Vitamins found in food help the body grow and repair itself.","zh":"食物中發現的維他命幫助身體成長和修復。"},{"en":"If harmful chemicals are found in food, authorities may remove the product from shops.","zh":"如果食物中發現有害化學物，當局可能把產品下架。"},{"en":"The phrase identifies substances that are inside or part of food.","zh":"這個短語指出在食物內部或構成食物一部分的物質。"}],"source":"135 - The sense of flavour.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 136":[{"front":"decision-making","meaning":"決策；作決定","examples":[{"en":"Decision-making becomes harder when people face too many options.","zh":"當人們面對太多選項時，決策會變得更困難。"},{"en":"Decision-making means choosing what to do after considering different options.","zh":"決策是指在考慮不同選項後選擇要做甚麼。"},{"en":"A student uses decision-making when choosing which subject to study first.","zh":"學生選擇先溫習哪一科時，就是在作決定。"},{"en":"Too much information can slow decision-making because people fear choosing wrongly.","zh":"太多資訊會拖慢決策，因為人們害怕選錯。"},{"en":"Good decision-making often needs clear priorities, not endless choices.","zh":"良好決策通常需要清晰優次，而不是無盡選擇。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":1},{"front":"choose among","meaning":"從……之中選擇","examples":[{"en":"Americans today choose among more options than ever before.","zh":"今日美國人從比以往更多的選項之中作選擇。"},{"en":"To choose among options means to select one from several possibilities.","zh":"從多個選項之中選擇，是指在幾個可能性中挑一個。"},{"en":"At lunch, students may choose among rice, noodles and sandwiches.","zh":"午餐時，學生可能從飯、麵和三文治之中選擇。"},{"en":"When people choose among too many products, they may feel tired.","zh":"當人們從太多產品之中選擇，可能會感到疲倦。"},{"en":"This phrase is used when there are several choices in front of someone.","zh":"這個短語用於某人面前有幾個選擇時。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":1},{"front":"more parts of life","meaning":"生活中更多方面","examples":[{"en":"People now face choices in more parts of life than before.","zh":"現在人們在生活中更多方面面對選擇。"},{"en":"More parts of life means more areas of daily living, work and personal decisions.","zh":"生活中更多方面，是指日常生活、工作和個人決定中的更多範圍。"},{"en":"People now make choices about phones, diets, schools, careers and retirement plans.","zh":"人們現在要為手機、飲食、學校、職業和退休計劃作選擇。"},{"en":"When choices enter more parts of life, daily living can feel more complicated.","zh":"當選擇進入生活中更多方面，日常生活可能變得更複雜。"},{"en":"This phrase shows that choice affects not only shopping, but life generally.","zh":"這個短語顯示選擇不只影響購物，也影響整體生活。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":1},{"front":"than ever before","meaning":"比以往任何時候都……","examples":[{"en":"Americans today have more options than ever before.","zh":"今日美國人的選項比以往任何時候都多。"},{"en":"Than ever before means more than at any earlier time.","zh":"比以往任何時候都……，是指比過去任何時間都更多或更強。"},{"en":"Students today can learn online more easily than ever before.","zh":"今天學生比以往任何時候都更容易在網上學習。"},{"en":"When choices are greater than ever before, comparison becomes harder.","zh":"當選擇比以往任何時候都多時，比較會變得更困難。"},{"en":"This phrase stresses that the present situation is historically unusual.","zh":"這個短語強調現時情況在歷史上很不尋常。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":1},{"front":"to an extent","meaning":"在某程度上","examples":[{"en":"To an extent, the opportunity to choose enhances our lives.","zh":"在某程度上，選擇的機會改善了我們的生活。"},{"en":"To an extent means partly, but not completely.","zh":"在某程度上，是指部分正確，但不是完全正確。"},{"en":"To an extent, homework helps students practise, but too much can exhaust them.","zh":"在某程度上，功課幫助學生練習，但太多會令人疲憊。"},{"en":"This phrase is useful when a statement is true only within limits.","zh":"當一個說法只在有限範圍內成立時，這個短語很有用。"},{"en":"It softens an argument by admitting that there are boundaries.","zh":"它透過承認界限，令論點不那麼絕對。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":1},{"front":"the opportunity to choose","meaning":"選擇的機會","examples":[{"en":"The opportunity to choose can enhance our lives.","zh":"選擇的機會可以改善我們的生活。"},{"en":"The opportunity to choose means the chance to select what suits us.","zh":"選擇的機會，是指挑選適合自己事物的機會。"},{"en":"Students value the opportunity to choose subjects that match their interests.","zh":"學生重視選擇符合自己興趣科目的機會。"},{"en":"The opportunity to choose can increase freedom, but it can also create pressure.","zh":"選擇的機會可以增加自由，但也可能造成壓力。"},{"en":"This phrase describes choice as a privilege or benefit.","zh":"這個短語把選擇描述成一種權利或好處。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":1},{"front":"enhance our lives","meaning":"改善我們的生活","examples":[{"en":"More freedom of choice may enhance our lives.","zh":"更多選擇自由可能改善我們的生活。"},{"en":"To enhance our lives means to make life better, richer or more convenient.","zh":"改善我們的生活，是指令生活更好、更豐富或更方便。"},{"en":"Public parks enhance our lives by giving people space to rest and exercise.","zh":"公園透過提供休息和運動空間改善我們的生活。"},{"en":"Choice can enhance our lives when it helps us meet personal needs.","zh":"當選擇幫助我們滿足個人需要時，它可以改善生活。"},{"en":"However, too much choice may reduce happiness instead of improving life.","zh":"然而，太多選擇可能減少快樂，而不是改善生活。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":1},{"front":"it is only logical to think that","meaning":"這樣想是合乎邏輯的","examples":[{"en":"It is only logical to think that more choice should be better.","zh":"認為更多選擇應該更好，這樣想是合乎邏輯的。"},{"en":"It is only logical to think that means the idea seems reasonable at first.","zh":"這樣想是合乎邏輯的，意思是這個想法起初看來合理。"},{"en":"It is only logical to think that studying more should improve exam results.","zh":"認為讀得更多應該改善考試成績，這樣想是合乎邏輯的。"},{"en":"Sometimes a logical idea is still wrong because human feelings are complicated.","zh":"有時合乎邏輯的想法仍然錯，因為人的感受很複雜。"},{"en":"This phrase introduces an assumption that may later be questioned.","zh":"這個短語引入一個之後可能被質疑的假設。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":1},{"front":"infinite options","meaning":"無限選擇","examples":[{"en":"Some people care about having infinite options.","zh":"有些人重視擁有無限選擇。"},{"en":"Infinite options means an unlimited or seemingly endless number of choices.","zh":"無限選擇是指無限制或看似無窮無盡的選項。"},{"en":"Streaming platforms can feel like infinite options when viewers cannot choose a film.","zh":"當觀眾不能選出電影時，串流平台可能令人感覺有無限選擇。"},{"en":"Infinite options may sound attractive, but they can make decisions exhausting.","zh":"無限選擇聽起來吸引，但可能令人作決定時疲憊。"},{"en":"This phrase often suggests abundance that may become overwhelming.","zh":"這個短語常暗示豐富到可能令人難以承受。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":1},{"front":"benefit from","meaning":"從……中受益","examples":[{"en":"People who value many options may benefit from them.","zh":"重視多選項的人可能從中受益。"},{"en":"To benefit from something means to gain an advantage or help from it.","zh":"從某事中受益，是指從它得到好處或幫助。"},{"en":"Students benefit from clear feedback because they know how to improve.","zh":"學生從清楚回饋中受益，因為他們知道如何改善。"},{"en":"People benefit from choice when the options match real needs.","zh":"當選項符合真正需要時，人們會從選擇中受益。"},{"en":"Not everyone benefits from more choice in the same way.","zh":"不是每個人都以同樣方式從更多選擇中受益。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":1},{"front":"versions of cereal","meaning":"不同款式的穀物早餐","examples":[{"en":"Consumers may ignore the many versions of cereal they have never tried.","zh":"消費者可能忽略許多從未試過的不同款式穀物早餐。"},{"en":"Versions of cereal are different types, flavours or brands of breakfast cereal.","zh":"不同款式的穀物早餐，是指早餐穀物的不同類型、味道或品牌。"},{"en":"A supermarket shelf may offer chocolate, honey, fruit and plain versions of cereal.","zh":"超市貨架可能提供朱古力、蜂蜜、水果和原味款式的穀物早餐。"},{"en":"Too many versions of cereal can make a simple breakfast choice feel difficult.","zh":"太多不同款式的穀物早餐，會令簡單早餐選擇變得困難。"},{"en":"This phrase gives a concrete example of everyday consumer choice.","zh":"這個短語提供日常消費選擇的具體例子。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":1},{"front":"recent research","meaning":"近期研究","examples":[{"en":"Recent research suggests that too many choices can reduce happiness.","zh":"近期研究顯示太多選擇可能降低快樂。"},{"en":"Recent research means studies carried out not long ago.","zh":"近期研究是指不久前進行的研究。"},{"en":"Recent research on sleep shows that teenagers often need more rest.","zh":"關於睡眠的近期研究顯示青少年通常需要更多休息。"},{"en":"Recent research can challenge ideas that once seemed obvious.","zh":"近期研究可以挑戰曾經看似明顯的想法。"},{"en":"This phrase is often used to introduce evidence from studies.","zh":"這個短語常用來引入研究證據。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":2},{"front":"strongly suggest that","meaning":"強烈顯示","examples":[{"en":"Recent research strongly suggests that this assumption is wrong.","zh":"近期研究強烈顯示這個假設是錯誤的。"},{"en":"Strongly suggest that means the evidence points clearly toward a conclusion.","zh":"強烈顯示，是指證據清楚指向某個結論。"},{"en":"The test results strongly suggest that the machine needs repair.","zh":"測試結果強烈顯示機器需要維修。"},{"en":"Research may strongly suggest a pattern even if it does not prove every case.","zh":"研究可能強烈顯示某種模式，即使不證明每一個個案。"},{"en":"This phrase is stronger than simply saying “may suggest.”","zh":"這個短語比單純說「可能顯示」更強。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":2},{"front":"psychologically","meaning":"從心理上來說","examples":[{"en":"Psychologically, the assumption that more choice is always better may be wrong.","zh":"從心理上來說，更多選擇永遠更好的假設可能是錯的。"},{"en":"Psychologically means in terms of the mind, feelings or behaviour.","zh":"從心理上來說，是指從思想、感受或行為角度來看。"},{"en":"Psychologically, public speaking can feel threatening even when the room is safe.","zh":"從心理上來說，即使房間很安全，公開演說也可能令人感到受威脅。"},{"en":"A choice may look good financially but feel stressful psychologically.","zh":"一個選擇在財務上可能不錯，但從心理上來說很有壓力。"},{"en":"This word shifts attention from facts outside us to what happens inside the mind.","zh":"這個詞把注意力從外在事實轉向內心發生的事。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":2},{"front":"this assumption is wrong","meaning":"這個假設是錯誤的","examples":[{"en":"Research suggests that this assumption is wrong.","zh":"研究顯示這個假設是錯誤的。"},{"en":"This assumption is wrong means the belief being discussed is not true.","zh":"這個假設是錯誤的，是指正在討論的信念並不正確。"},{"en":"A student may assume harder words always mean better writing, but this assumption is wrong.","zh":"學生可能假設較深的詞一定代表較好的寫作，但這個假設是錯誤的。"},{"en":"When evidence challenges a belief, we may need to accept that the assumption is wrong.","zh":"當證據挑戰一個信念時，我們可能需要接受這個假設是錯誤的。"},{"en":"This phrase is useful for correcting a common but mistaken idea.","zh":"這個短語適合用來糾正常見但錯誤的想法。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":2},{"front":"undoubtedly better than none","meaning":"無疑比完全沒有好","examples":[{"en":"Some choices are undoubtedly better than none.","zh":"有些選擇無疑比完全沒有選擇好。"},{"en":"Undoubtedly better than none means clearly better than having no choice at all.","zh":"無疑比完全沒有好，是指明顯比毫無選擇好。"},{"en":"Having two bus routes is undoubtedly better than none if people need to reach work.","zh":"如果人們需要上班，有兩條巴士路線無疑比完全沒有好。"},{"en":"A few options can give people control without overwhelming them.","zh":"少量選項可以給人控制感，而不會令人受壓。"},{"en":"This phrase admits that choice has value, even if too much choice can hurt.","zh":"這個短語承認選擇有價值，即使太多選擇可能有害。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":2},{"front":"more is not always better than less","meaning":"多不一定比少好","examples":[{"en":"More is not always better than less when people make choices.","zh":"人們作選擇時，多不一定比少好。"},{"en":"More is not always better than less means a larger number does not always improve the situation.","zh":"多不一定比少好，是指數量較多不一定令情況改善。"},{"en":"More homework is not always better than less if students become too tired to learn.","zh":"如果學生太累而學不到東西，更多功課不一定比少功課好。"},{"en":"Too many choices can increase regret instead of satisfaction.","zh":"太多選擇可能增加後悔，而不是滿足感。"},{"en":"This phrase warns against assuming that quantity always means quality.","zh":"這個短語提醒人不要假設數量永遠等於質素。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":2},{"front":"offer insight into","meaning":"提供對……的深入理解","examples":[{"en":"Recent research offers insight into why choice can make people unhappy.","zh":"近期研究提供對選擇為何令人不快樂的深入理解。"},{"en":"To offer insight into something means to help people understand it more deeply.","zh":"提供對某事的深入理解，是指幫助人更深刻地明白它。"},{"en":"A diary can offer insight into how a student feels before exams.","zh":"日記可以提供對學生考試前感受的深入理解。"},{"en":"Research offers insight into behaviour by showing patterns people may not notice.","zh":"研究透過顯示人們未必注意到的模式，提供對行為的理解。"},{"en":"This phrase is useful when evidence explains hidden causes.","zh":"當證據解釋隱藏原因時，這個短語很有用。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":2},{"front":"end up unhappy","meaning":"最終變得不快樂","examples":[{"en":"Many people end up unhappy when their options expand.","zh":"當選項增加時，許多人最終變得不快樂。"},{"en":"To end up unhappy means to become unhappy as the final result.","zh":"最終變得不快樂，是指最後結果是變得不開心。"},{"en":"A shopper may end up unhappy after comparing twenty similar jackets.","zh":"顧客比較二十件相似外套後，可能最終變得不快樂。"},{"en":"Too many choices can make people end up unhappy because they imagine better alternatives.","zh":"太多選擇會令人最終變得不快樂，因為他們想像更好的替代選項。"},{"en":"This phrase focuses on the final emotional outcome.","zh":"這個短語聚焦最後的情緒結果。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":2},{"front":"rather than pleased","meaning":"而不是感到高興","examples":[{"en":"People may become unhappy rather than pleased when they have more options.","zh":"當人們有更多選項時，可能變得不快樂，而不是感到高興。"},{"en":"Rather than pleased means instead of feeling happy or satisfied.","zh":"而不是感到高興，是指並非感到快樂或滿意。"},{"en":"A child given too many toys may feel confused rather than pleased.","zh":"孩子得到太多玩具時，可能感到混亂，而不是高興。"},{"en":"More options can create pressure rather than pleasure.","zh":"更多選項可能造成壓力，而不是快樂。"},{"en":"This phrase clearly shows a contrast between expected happiness and actual unhappiness.","zh":"這個短語清楚顯示預期快樂與實際不快樂之間的對比。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":2},{"front":"options expand","meaning":"選項增加","examples":[{"en":"People may feel worse when their options expand.","zh":"當選項增加時，人們可能感覺更差。"},{"en":"When options expand, the number of available choices increases.","zh":"選項增加，是指可用選擇的數量上升。"},{"en":"A student’s options expand when more universities accept online applications.","zh":"當更多大學接受網上申請，學生的選項就會增加。"},{"en":"Options expanding can create freedom, but also more comparison and regret.","zh":"選項增加可以帶來自由，但也帶來更多比較和後悔。"},{"en":"This phrase describes choice becoming broader than before.","zh":"這個短語描述選擇比以前更廣。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":2},{"front":"make a distinction between","meaning":"區分","examples":[{"en":"The researchers made a distinction between maximizers and satisficers.","zh":"研究人員區分了追求最優者和滿意即止者。"},{"en":"To make a distinction between two things means to show how they are different.","zh":"區分兩件事，是指顯示它們如何不同。"},{"en":"A teacher may make a distinction between formal English and casual English.","zh":"老師可能區分正式英語和日常英語。"},{"en":"Making a distinction helps people avoid mixing up similar ideas.","zh":"作出區分幫助人避免混淆相似概念。"},{"en":"This phrase is often used when categories need to be separated clearly.","zh":"當需要清楚分開類別時，這個短語常被使用。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":2},{"front":"maximizers","meaning":"追求最優者","examples":[{"en":"Maximizers always aim to make the best possible choice.","zh":"追求最優者總是旨在作出可能之中最好的選擇。"},{"en":"Maximizers are people who keep searching until they believe they have found the best option.","zh":"追求最優者是會一直尋找，直到相信自己找到最佳選項的人。"},{"en":"A maximizer may read many phone reviews before buying one model.","zh":"追求最優者可能在買一款手機前閱讀很多評論。"},{"en":"Maximizers can become tired because every choice feels important.","zh":"追求最優者可能變得疲倦，因為每個選擇都感覺重要。"},{"en":"This word describes people who are not satisfied with merely good-enough choices.","zh":"這個詞描述不滿足於「夠好」選擇的人。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":3},{"front":"aim to","meaning":"旨在；目標是","examples":[{"en":"Maximizers aim to make the best possible choice.","zh":"追求最優者旨在作出可能之中最好的選擇。"},{"en":"To aim to do something means to have it as a goal.","zh":"旨在做某事，是指把它作為目標。"},{"en":"A student may aim to finish homework before dinner.","zh":"學生可能目標是在晚飯前完成功課。"},{"en":"People who aim to be perfect may spend too long on small decisions.","zh":"旨在完美的人可能在小決定上花太久。"},{"en":"This phrase links an action with a clear intention.","zh":"這個短語把行動與清晰意圖連接起來。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":3},{"front":"the best possible choice","meaning":"可能之中最好的選擇","examples":[{"en":"Maximizers try to make the best possible choice.","zh":"追求最優者嘗試作出可能之中最好的選擇。"},{"en":"The best possible choice means the option that seems better than all others.","zh":"可能之中最好的選擇，是指看起來比所有其他選項都好的選擇。"},{"en":"A parent may search many schools to find the best possible choice for a child.","zh":"家長可能搜尋很多學校，為孩子找出可能之中最好的選擇。"},{"en":"Trying to find the best possible choice can improve results, but also increase stress.","zh":"嘗試找出可能之中最好的選擇可以改善結果，但也會增加壓力。"},{"en":"This phrase suggests a very high standard for decision-making.","zh":"這個短語暗示作決定時有很高標準。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":3},{"front":"satisficers","meaning":"滿意即止者","examples":[{"en":"Satisficers aim for a choice that is good enough.","zh":"滿意即止者以夠好的選擇為目標。"},{"en":"Satisficers are people who stop searching when an option meets their needs.","zh":"滿意即止者是當某選項符合需要時就停止尋找的人。"},{"en":"A satisficer may buy the first comfortable pair of shoes at a fair price.","zh":"滿意即止者可能買第一雙舒適且價格合理的鞋。"},{"en":"Satisficers often save time because they do not demand perfection.","zh":"滿意即止者通常節省時間，因為他們不要求完美。"},{"en":"This word describes people who accept a satisfactory choice instead of the absolute best.","zh":"這個詞描述接受令人滿意選擇，而不是絕對最佳選擇的人。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":3},{"front":"good enough","meaning":"夠好；足夠滿意","examples":[{"en":"Satisficers stop when they find an option that is good enough.","zh":"滿意即止者找到一個夠好的選項時就停止。"},{"en":"Good enough means acceptable or satisfactory, even if not perfect.","zh":"夠好是指可以接受或令人滿意，即使不是完美。"},{"en":"A simple lunch may be good enough when you are busy at work.","zh":"工作繁忙時，一頓簡單午餐可能已經夠好。"},{"en":"Choosing something good enough can reduce stress and save time.","zh":"選擇夠好的東西可以減少壓力並節省時間。"},{"en":"This phrase lowers the pressure to find the perfect option.","zh":"這個短語降低尋找完美選項的壓力。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":3},{"front":"whether or not","meaning":"不論是否","examples":[{"en":"Satisficers accept a good option whether or not better selections exist.","zh":"滿意即止者接受好選項，不論是否存在更好的選擇。"},{"en":"Whether or not means it does not matter if something is true or false.","zh":"不論是否，是指某事是真是假都不重要。"},{"en":"I will bring an umbrella whether or not it rains.","zh":"不論是否下雨，我都會帶傘。"},{"en":"Satisficers stop searching whether or not a slightly better option exists elsewhere.","zh":"滿意即止者會停止尋找，不論其他地方是否有稍好的選項。"},{"en":"This phrase shows that the decision does not depend on that condition.","zh":"這個短語顯示決定不取決於那個條件。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":3},{"front":"better selections","meaning":"更好的選擇","examples":[{"en":"Better selections might be available elsewhere.","zh":"更好的選擇可能在其他地方有。"},{"en":"Better selections are options that may be more suitable or higher in quality.","zh":"更好的選擇，是指可能更合適或質素更高的選項。"},{"en":"A shopper may wonder if better selections are available in another store.","zh":"顧客可能想知道另一間店是否有更好的選擇。"},{"en":"Thinking about better selections can make people less satisfied with what they chose.","zh":"想着更好的選擇會令人對自己所選的東西較不滿意。"},{"en":"This phrase is often connected with comparison and regret.","zh":"這個短語常與比較和後悔有關。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":3},{"front":"be out there","meaning":"在外面存在；仍有其他選擇","examples":[{"en":"Better selections might be out there, but satisficers do not keep searching.","zh":"更好的選擇可能仍在外面存在，但滿意即止者不會繼續尋找。"},{"en":"To be out there means to exist somewhere, even if not immediately seen.","zh":"在外面存在，是指某物在某處存在，即使不是眼前可見。"},{"en":"A better job may be out there, but applying endlessly can be tiring.","zh":"更好的工作可能仍在外面存在，但不停申請會令人疲倦。"},{"en":"Believing that perfect options are out there can make people keep searching.","zh":"相信完美選項仍在外面存在，會令人繼續尋找。"},{"en":"This phrase often expresses possibility beyond what we currently know.","zh":"這個短語常表達目前所知以外的可能性。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":3},{"front":"in particular","meaning":"尤其；特別是","examples":[{"en":"In particular, the researchers created a scale to measure maximization.","zh":"特別是，研究人員建立了一個量表來衡量最大化傾向。"},{"en":"In particular means especially or more specifically.","zh":"尤其是指特別地或更具體地。"},{"en":"Many students struggle with grammar, in particular articles and prepositions.","zh":"許多學生在文法上有困難，尤其是冠詞和介詞。"},{"en":"This phrase narrows a general point to one important detail.","zh":"這個短語把一般重點收窄到一個重要細節。"},{"en":"It helps readers know which part deserves special attention.","zh":"它幫助讀者知道哪一部分特別值得注意。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":3},{"front":"compose a set of statements","meaning":"編寫一組陳述","examples":[{"en":"The researchers composed a set of statements to measure decision-making habits.","zh":"研究人員編寫一組陳述來衡量決策習慣。"},{"en":"To compose a set of statements means to write several sentences for a purpose.","zh":"編寫一組陳述，是指為某個目的寫出幾句句子。"},{"en":"A teacher may compose a set of statements for students to agree or disagree with.","zh":"老師可能編寫一組陳述，讓學生表示同意或不同意。"},{"en":"Researchers compose statements carefully so answers can reveal patterns.","zh":"研究人員仔細編寫陳述，使答案能揭示模式。"},{"en":"This phrase describes creating survey items or test questions.","zh":"這個短語描述創作問卷項目或測驗題目。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":3},{"front":"the Maximization Scale","meaning":"最大化傾向量表","examples":[{"en":"The Maximization Scale diagnoses people’s tendency to maximize.","zh":"最大化傾向量表診斷人們追求最優的傾向。"},{"en":"The Maximization Scale is a questionnaire that measures how strongly people seek the best option.","zh":"最大化傾向量表是一份問卷，用來衡量人們追求最佳選項的程度。"},{"en":"A person with a high Maximization Scale score may compare many products before buying.","zh":"在最大化傾向量表得分高的人，買東西前可能比較很多產品。"},{"en":"The scale helps researchers study decision-making differences between people.","zh":"這個量表幫助研究人員研究人與人之間的決策差異。"},{"en":"This term names the tool used to measure maximizer tendencies.","zh":"這個術語命名了用來衡量追求最優傾向的工具。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":3},{"front":"diagnose someone’s propensity to","meaning":"診斷某人……的傾向","examples":[{"en":"The scale was designed to diagnose people’s propensity to maximize.","zh":"這個量表旨在診斷人們追求最優的傾向。"},{"en":"To diagnose someone’s propensity to do something means to identify their tendency toward it.","zh":"診斷某人做某事的傾向，是指識別他們傾向於那樣做。"},{"en":"A questionnaire may diagnose a student’s propensity to avoid difficult tasks.","zh":"問卷可能診斷學生逃避困難任務的傾向。"},{"en":"Diagnosis helps researchers group people by behaviour patterns.","zh":"診斷幫助研究人員按行為模式把人分類。"},{"en":"This phrase is used when a tool measures a personal tendency.","zh":"當工具衡量個人傾向時，可以使用這個短語。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":4},{"front":"propensity to maximize","meaning":"追求最優的傾向","examples":[{"en":"The study measured each person’s propensity to maximize.","zh":"研究衡量每個人追求最優的傾向。"},{"en":"Propensity to maximize means the tendency to seek the best possible choice.","zh":"追求最優的傾向，是指尋找可能之中最佳選擇的傾向。"},{"en":"A shopper with a strong propensity to maximize may visit five stores before buying shoes.","zh":"有強烈追求最優傾向的顧客，買鞋前可能逛五間店。"},{"en":"This tendency can lead to more comparisons and more regret.","zh":"這種傾向可能導致更多比較和更多後悔。"},{"en":"The phrase describes a habit of aiming for the optimal option.","zh":"這個短語描述以最佳選項為目標的習慣。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":4},{"front":"rate themselves","meaning":"為自己評分","examples":[{"en":"Participants rated themselves from 1 to 7.","zh":"參與者為自己從 1 到 7 評分。"},{"en":"To rate themselves means to give themselves a score or level.","zh":"為自己評分，是指給自己一個分數或程度。"},{"en":"Students may rate themselves on how confident they feel before a presentation.","zh":"學生可能在演講前為自己的信心評分。"},{"en":"Self-ratings help researchers collect information about personal feelings or habits.","zh":"自我評分幫助研究人員收集關於個人感受或習慣的資料。"},{"en":"This phrase is used when people judge their own condition.","zh":"當人們評估自己的狀態時，可以使用這個短語。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":4},{"front":"completely disagree","meaning":"完全不同意","examples":[{"en":"Participants could choose “completely disagree” on the scale.","zh":"參與者可以在量表上選擇「完全不同意」。"},{"en":"Completely disagree means strongly believe a statement is not true.","zh":"完全不同意，是指強烈認為某陳述不正確。"},{"en":"A student may completely disagree with the idea that exams are the only measure of ability.","zh":"學生可能完全不同意考試是能力唯一標準的想法。"},{"en":"Choosing “completely disagree” shows strong rejection, not mild doubt.","zh":"選擇「完全不同意」表示強烈拒絕，而不是輕微懷疑。"},{"en":"This phrase is common in surveys and opinion scales.","zh":"這個短語常見於問卷和意見量表。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":4},{"front":"completely agree","meaning":"完全同意","examples":[{"en":"Participants could choose “completely agree” on the scale.","zh":"參與者可以在量表上選擇「完全同意」。"},{"en":"Completely agree means strongly believe a statement is true.","zh":"完全同意，是指強烈認為某陳述正確。"},{"en":"A parent may completely agree that children need enough sleep before exams.","zh":"家長可能完全同意孩子考試前需要足夠睡眠。"},{"en":"Choosing “completely agree” shows a clear and strong opinion.","zh":"選擇「完全同意」表示清楚而強烈的意見。"},{"en":"This phrase is often the highest agreement point on a survey scale.","zh":"這個短語通常是問卷量表中最高的同意程度。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":4},{"front":"settle for second best","meaning":"接受次佳選擇","examples":[{"en":"Some maximizers never settle for second best.","zh":"有些追求最優者從不接受次佳選擇。"},{"en":"To settle for second best means to accept something that is not the top option.","zh":"接受次佳選擇，是指接受不是最佳的東西。"},{"en":"A shopper may refuse to settle for second best when buying an expensive laptop.","zh":"顧客購買昂貴手提電腦時，可能拒絕接受次佳選擇。"},{"en":"Never settling for second best can push quality higher but also create stress.","zh":"從不接受次佳選擇可以推高質素，但也會造成壓力。"},{"en":"This phrase often suggests unwillingness to compromise.","zh":"這個短語常暗示不願妥協。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":4},{"front":"evaluate someone’s sense of satisfaction","meaning":"評估某人的滿足感","examples":[{"en":"The researchers evaluated people’s sense of satisfaction with their decisions.","zh":"研究人員評估人們對其決定的滿足感。"},{"en":"To evaluate someone’s sense of satisfaction means to measure how pleased they feel.","zh":"評估某人的滿足感，是指衡量他們感到多滿意。"},{"en":"A school may evaluate students’ satisfaction with a new timetable.","zh":"學校可能評估學生對新時間表的滿足感。"},{"en":"Evaluation can show whether a decision leaves people calm or regretful.","zh":"評估可以顯示一個決定令人平靜還是後悔。"},{"en":"This phrase is common in surveys about feelings after choices.","zh":"這個短語常見於關於選擇後感受的問卷。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":4},{"front":"sense of satisfaction","meaning":"滿足感","examples":[{"en":"The study measured people’s sense of satisfaction with their decisions.","zh":"研究衡量人們對其決定的滿足感。"},{"en":"A sense of satisfaction is the feeling that something is good enough or pleasing.","zh":"滿足感是覺得某事夠好或令人滿意的感覺。"},{"en":"A student may feel a sense of satisfaction after finishing a difficult essay.","zh":"學生完成一篇困難作文後，可能感到滿足感。"},{"en":"Too many alternatives can weaken the sense of satisfaction after choosing.","zh":"太多替代選項可能削弱選擇後的滿足感。"},{"en":"This phrase describes an inner feeling of being content.","zh":"這個短語描述內心感到滿意的感覺。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":4},{"front":"define a sharp cutoff","meaning":"設定清晰分界線","examples":[{"en":"The researchers did not define a sharp cutoff between the two groups.","zh":"研究人員沒有在兩組之間設定清晰分界線。"},{"en":"To define a sharp cutoff means to set a clear dividing point.","zh":"設定清晰分界線，是指設立明確的分隔點。"},{"en":"A school may define a sharp cutoff score for scholarship interviews.","zh":"學校可能為獎學金面試設定清晰分數分界線。"},{"en":"Without a sharp cutoff, people may fall between two categories.","zh":"沒有清晰分界線時，人們可能落在兩個類別之間。"},{"en":"This phrase is used when boundaries are exact rather than gradual.","zh":"當界限是精確而不是漸進時，可以使用這個短語。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":4},{"front":"separate something from something","meaning":"把……與……分開","examples":[{"en":"The scale did not sharply separate maximizers from satisficers.","zh":"這個量表沒有清楚把追求最優者與滿意即止者分開。"},{"en":"To separate one thing from another means to divide them into different groups.","zh":"把一物與另一物分開，是指把它們劃分成不同群組。"},{"en":"Teachers separate formal writing from casual writing to show different rules.","zh":"老師把正式寫作與日常寫作分開，以展示不同規則。"},{"en":"Clear criteria help separate similar cases from one another.","zh":"清楚標準幫助把相似個案彼此分開。"},{"en":"This phrase is useful when two categories overlap.","zh":"當兩個類別有重疊時，這個短語很有用。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":4},{"front":"in general","meaning":"一般來說","examples":[{"en":"In general, people with higher scores are treated as maximizers.","zh":"一般來說，得分較高的人被視為追求最優者。"},{"en":"In general means usually or in most cases.","zh":"一般來說，是指通常或在大多數情況下。"},{"en":"In general, students learn better when examples are clear and concrete.","zh":"一般來說，當例子清楚具體時，學生會學得更好。"},{"en":"This phrase allows for exceptions while describing a broad pattern.","zh":"這個短語在描述大致模式時容許例外。"},{"en":"It is useful when the statement is mostly true but not absolute.","zh":"當說法大多正確但不是絕對時，它很有用。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":4},{"front":"average scores","meaning":"平均分數","examples":[{"en":"Average scores above the midpoint suggest a stronger tendency to maximize.","zh":"高於中間點的平均分數顯示較強的追求最優傾向。"},{"en":"Average scores are the usual or mean results calculated from several ratings.","zh":"平均分數是從多個評分計算出的通常或平均結果。"},{"en":"A class’s average scores may rise after students practise more regularly.","zh":"學生更有規律練習後，全班平均分數可能上升。"},{"en":"Average scores help researchers compare groups without focusing on one person only.","zh":"平均分數幫助研究人員比較群組，而不是只聚焦一個人。"},{"en":"In a scale, average scores can show whether a tendency is weak or strong.","zh":"在量表中，平均分數可以顯示某種傾向是弱還是強。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":5},{"front":"the scale’s midpoint","meaning":"量表中間點","examples":[{"en":"The scale’s midpoint was used as a rough dividing line.","zh":"量表中間點被用作粗略分界線。"},{"en":"The scale’s midpoint is the middle point between the lowest and highest scores.","zh":"量表中間點是最低分與最高分之間的中間位置。"},{"en":"On a seven-point scale, four is often the midpoint.","zh":"在七分量表中，四通常是中間點。"},{"en":"A midpoint can help divide high and low scores, but it may be imperfect.","zh":"中間點可以幫助劃分高低分，但未必完美。"},{"en":"This phrase refers to the centre of a measurement scale.","zh":"這個短語指測量量表的中心位置。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":5},{"front":"score highest on the test","meaning":"在測試中得分最高","examples":[{"en":"People who score highest on the test are the greatest maximizers.","zh":"在測試中得分最高的人是最強的追求最優者。"},{"en":"To score highest on a test means to receive the top marks or ratings.","zh":"在測試中得分最高，是指得到最高分或最高評級。"},{"en":"Students who score highest on a spelling test usually make the fewest mistakes.","zh":"在串字測試中得分最高的學生通常錯誤最少。"},{"en":"In this study, high scores suggest stronger maximizing habits.","zh":"在這項研究中，高分顯示較強的追求最優習慣。"},{"en":"This phrase links test performance with a measured trait.","zh":"這個短語把測試表現與被衡量的特質連接起來。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":5},{"front":"engage in","meaning":"參與；進行","examples":[{"en":"Maximizers engage in more product comparisons than satisficers.","zh":"追求最優者比滿意即止者進行更多產品比較。"},{"en":"To engage in an activity means to take part in it or do it.","zh":"參與或進行某活動，是指加入或做該活動。"},{"en":"Students engage in group discussion when they share ideas in class.","zh":"學生在課堂分享想法時，就是參與小組討論。"},{"en":"People who engage in too much comparison may become less confident.","zh":"進行太多比較的人可能變得較不自信。"},{"en":"This phrase is a formal way to say “do” or “take part in.”","zh":"這個短語是表達「做」或「參與」的較正式說法。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":5},{"front":"product comparisons","meaning":"產品比較","examples":[{"en":"Maximizers make more product comparisons before buying something.","zh":"追求最優者在購買東西前作更多產品比較。"},{"en":"Product comparisons are checks of different products’ prices, quality and features.","zh":"產品比較是檢查不同產品的價格、質素和功能。"},{"en":"A shopper may make product comparisons before buying a washing machine.","zh":"顧客購買洗衣機前可能作產品比較。"},{"en":"Product comparisons can help people choose wisely, but too many can cause stress.","zh":"產品比較可以幫助人明智選擇，但太多會造成壓力。"},{"en":"This phrase is common in shopping and consumer decisions.","zh":"這個短語常見於購物和消費決定。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":5},{"front":"before and after","meaning":"在……前後","examples":[{"en":"Maximizers compare products both before and after they buy them.","zh":"追求最優者在購買產品前後都會比較。"},{"en":"Before and after means at two times: earlier and later than an event.","zh":"在……前後，是指在某事件之前和之後兩個時間。"},{"en":"A doctor may check a patient before and after treatment.","zh":"醫生可能在治療前後檢查病人。"},{"en":"Comparing before and after a purchase can make buyers doubt their choice.","zh":"在購買前後都比較，可能令買家懷疑自己的選擇。"},{"en":"This phrase shows that the behaviour continues across time.","zh":"這個短語顯示行為跨時間持續。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":5},{"front":"make purchasing decisions","meaning":"作出購買決定","examples":[{"en":"Maximizers take longer to make purchasing decisions.","zh":"追求最優者需要更長時間作出購買決定。"},{"en":"To make purchasing decisions means to decide what to buy.","zh":"作出購買決定，是指決定買甚麼。"},{"en":"Families make purchasing decisions when choosing a fridge, sofa or school bag.","zh":"家庭選擇雪櫃、梳化或書包時，就是作出購買決定。"},{"en":"Too many reviews can make purchasing decisions slower and more stressful.","zh":"太多評論會令購買決定更慢、更有壓力。"},{"en":"This phrase refers to decisions made as a consumer.","zh":"這個短語指作為消費者所作的決定。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":5},{"front":"take longer to decide","meaning":"需要更長時間決定","examples":[{"en":"Maximizers take longer to decide what to buy.","zh":"追求最優者需要更長時間決定買甚麼。"},{"en":"To take longer to decide means to need more time before choosing.","zh":"需要更長時間決定，是指選擇前需要更多時間。"},{"en":"A customer may take longer to decide when two phones look almost identical.","zh":"當兩部手機看起來幾乎一樣，顧客可能需要更長時間決定。"},{"en":"Taking longer to decide can help careful thinking, but it can also create fatigue.","zh":"花更長時間決定可以幫助仔細思考，但也可能造成疲勞。"},{"en":"This phrase describes delay caused by comparison or uncertainty.","zh":"這個短語描述由比較或不確定造成的延遲。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":5},{"front":"meet someone’s standards","meaning":"符合某人的標準","examples":[{"en":"Satisficers stop looking when an item meets their standards.","zh":"當一件物品符合他們的標準時，滿意即止者就停止尋找。"},{"en":"To meet someone’s standards means to be good enough for that person’s requirements.","zh":"符合某人的標準，是指足夠好，達到那人的要求。"},{"en":"A hotel meets a traveller’s standards if it is clean, safe and affordable.","zh":"如果酒店乾淨、安全且價格可負擔，就符合旅客的標準。"},{"en":"When something meets your standards, further searching may be unnecessary.","zh":"當某物符合你的標準，繼續尋找可能沒有必要。"},{"en":"This phrase focuses on personal requirements rather than perfection.","zh":"這個短語聚焦個人要求，而不是完美。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":5},{"front":"stop looking","meaning":"停止尋找","examples":[{"en":"Satisficers stop looking once they find a good-enough option.","zh":"滿意即止者一找到夠好的選項就停止尋找。"},{"en":"To stop looking means to end the search.","zh":"停止尋找，是指結束搜尋。"},{"en":"A shopper may stop looking after finding comfortable shoes within budget.","zh":"顧客找到預算內舒適鞋子後，可能停止尋找。"},{"en":"Stopping looking can save time and reduce regret.","zh":"停止尋找可以節省時間並減少後悔。"},{"en":"This phrase is central to the satisficer style of decision-making.","zh":"這個短語是滿意即止決策方式的核心。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":5},{"front":"exert enormous effort","meaning":"付出巨大努力","examples":[{"en":"Maximizers exert enormous effort when comparing products.","zh":"追求最優者在比較產品時付出巨大努力。"},{"en":"To exert enormous effort means to use a very large amount of energy or work.","zh":"付出巨大努力，是指使用非常大量的精力或工作。"},{"en":"A student may exert enormous effort to prepare for a scholarship interview.","zh":"學生可能為準備獎學金面試付出巨大努力。"},{"en":"Exerting enormous effort on small purchases can leave people mentally tired.","zh":"在小額購買上付出巨大努力，會令人精神疲倦。"},{"en":"This phrase stresses that the work is heavy and demanding.","zh":"這個短語強調工作沉重而費力。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":5},{"front":"read labels","meaning":"閱讀標籤","examples":[{"en":"Maximizers spend time reading labels before making purchases.","zh":"追求最優者在購買前花時間閱讀標籤。"},{"en":"To read labels means to check the printed information on a product.","zh":"閱讀標籤，是指查看產品上的印刷資料。"},{"en":"People with allergies read labels to avoid unsafe ingredients.","zh":"有過敏的人會閱讀標籤，以避免不安全成分。"},{"en":"Reading labels can help shoppers compare nutrition, price or safety information.","zh":"閱讀標籤可以幫助顧客比較營養、價格或安全資料。"},{"en":"This phrase describes careful consumer checking before buying.","zh":"這個短語描述購買前仔細檢查產品的行為。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":6},{"front":"check out","meaning":"查看；查閱","examples":[{"en":"Maximizers check out consumer magazines before buying products.","zh":"追求最優者在購買產品前查閱消費者雜誌。"},{"en":"To check out something means to look at it or examine it for information.","zh":"查看某物，是指為獲取資料而看或檢查它。"},{"en":"Before choosing a gym, a person may check out its reviews online.","zh":"選擇健身室前，人們可能在網上查看評論。"},{"en":"Checking out too many sources can make a decision feel endless.","zh":"查閱太多來源可能令決定感覺無止境。"},{"en":"This phrase is casual and common in everyday English.","zh":"這個短語較口語，在日常英語中很常見。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":6},{"front":"consumer magazines","meaning":"消費者雜誌","examples":[{"en":"Consumer magazines can help shoppers compare products.","zh":"消費者雜誌可以幫助購物者比較產品。"},{"en":"Consumer magazines are publications that review products and advise buyers.","zh":"消費者雜誌是評論產品並給買家建議的刊物。"},{"en":"A consumer magazine may compare washing machines by price, durability and energy use.","zh":"消費者雜誌可能按價格、耐用度和耗電量比較洗衣機。"},{"en":"Such magazines can reduce uncertainty by giving organised information.","zh":"這類雜誌透過提供有組織的資料，可以減少不確定性。"},{"en":"This phrase refers to media written for ordinary buyers.","zh":"這個短語指為普通買家而寫的媒體。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":6},{"front":"try new products","meaning":"嘗試新產品","examples":[{"en":"Maximizers often try new products in search of the best choice.","zh":"追求最優者常嘗試新產品，以尋找最佳選擇。"},{"en":"To try new products means to use unfamiliar items to see whether they are better.","zh":"嘗試新產品，是指使用不熟悉的物品，看看它們是否更好。"},{"en":"A shopper may try new skincare products after reading positive reviews.","zh":"顧客閱讀好評後，可能嘗試新的護膚產品。"},{"en":"Trying new products can help discovery, but it can also waste money.","zh":"嘗試新產品可以幫助發現好東西，但也可能浪費金錢。"},{"en":"This phrase shows active searching beyond familiar choices.","zh":"這個短語顯示超越熟悉選擇的主動搜尋。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":6},{"front":"compare something with","meaning":"把……與……比較","examples":[{"en":"Maximizers compare their purchasing decisions with those of others.","zh":"追求最優者把自己的購買決定與其他人的決定比較。"},{"en":"To compare something with another thing means to examine similarities and differences.","zh":"把某物與另一物比較，是指檢查相似和不同之處。"},{"en":"Students compare their answers with the model answer after practice.","zh":"學生練習後會把自己的答案與範文比較。"},{"en":"Comparing your choice with others’ choices can create pride or regret.","zh":"把自己的選擇與別人的選擇比較，可能產生自豪或後悔。"},{"en":"This phrase is used when judging one thing against another.","zh":"當用一物對照另一物來判斷時，可以使用這個短語。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":6},{"front":"those of others","meaning":"其他人的那些","examples":[{"en":"Maximizers compare their choices with those of others.","zh":"追求最優者把自己的選擇與其他人的那些選擇比較。"},{"en":"Those of others means the choices, results or possessions belonging to other people.","zh":"其他人的那些，是指屬於其他人的選擇、結果或物品。"},{"en":"Students should improve their essays rather than constantly compare them with those of others.","zh":"學生應改善自己的作文，而不是不斷與其他人的作文比較。"},{"en":"Comparing your salary with those of others can affect your satisfaction.","zh":"把自己的薪金與其他人的薪金比較，可能影響滿足感。"},{"en":"This phrase avoids repeating the noun already mentioned.","zh":"這個短語避免重複已提及的名詞。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":6},{"front":"the fruits of their efforts","meaning":"努力成果","examples":[{"en":"Maximizers are often unhappy with the fruits of their efforts.","zh":"追求最優者常對自己的努力成果感到不快。"},{"en":"The fruits of their efforts means the results produced by their hard work.","zh":"努力成果，是指辛勤付出所產生的結果。"},{"en":"After weeks of revision, exam results are the fruits of a student’s efforts.","zh":"經過幾星期溫習後，考試成績就是學生的努力成果。"},{"en":"People may feel disappointed if the fruits of their efforts seem smaller than expected.","zh":"如果努力成果比預期少，人們可能感到失望。"},{"en":"This phrase treats results as something grown from work.","zh":"這個短語把結果比作由工作長出來的東西。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":6},{"front":"compare themselves with others","meaning":"與別人比較","examples":[{"en":"Maximizers often compare themselves with others.","zh":"追求最優者常與別人比較。"},{"en":"To compare themselves with others means to judge their own results against other people’s results.","zh":"與別人比較，是指用其他人的結果來判斷自己的結果。"},{"en":"Students may compare themselves with classmates after receiving exam marks.","zh":"學生收到考試分數後，可能與同學比較。"},{"en":"Constant comparison can reduce confidence even when people perform well.","zh":"持續比較即使在人們表現良好時，也可能降低信心。"},{"en":"This phrase describes a habit that can create envy or dissatisfaction.","zh":"這個短語描述一種可能造成妒忌或不滿的習慣。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":6},{"front":"get little pleasure from","meaning":"從……中得到很少快樂","examples":[{"en":"They get little pleasure from discovering that they did better.","zh":"他們發現自己做得更好時，也從中得到很少快樂。"},{"en":"To get little pleasure from something means to feel only a small amount of happiness from it.","zh":"從某事中得到很少快樂，是指只從中感到少量高興。"},{"en":"A perfectionist may get little pleasure from a high score if one answer was wrong.","zh":"完美主義者如果錯了一題，即使得高分也可能得到很少快樂。"},{"en":"If people focus on comparison, success may bring little pleasure.","zh":"如果人們專注於比較，成功可能帶來很少快樂。"},{"en":"This phrase shows that achievement does not always create satisfaction.","zh":"這個短語顯示成就不一定帶來滿足。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":6},{"front":"find out that","meaning":"發現","examples":[{"en":"Maximizers may find out that someone else made a better choice.","zh":"追求最優者可能發現別人作出了更好的選擇。"},{"en":"To find out that means to discover or learn that something is true.","zh":"發現某事，是指知道或了解到某事是真的。"},{"en":"A customer may find out that the same bag is cheaper online.","zh":"顧客可能發現同一個袋在網上更便宜。"},{"en":"Finding out that another option was better can create regret.","zh":"發現另一個選項更好，可能造成後悔。"},{"en":"This phrase often introduces new information that changes feelings.","zh":"這個短語常引入會改變感受的新資訊。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":6},{"front":"substantial dissatisfaction","meaning":"強烈不滿","examples":[{"en":"Maximizers feel substantial dissatisfaction when they do worse.","zh":"當追求最優者做得較差時，會感到強烈不滿。"},{"en":"Substantial dissatisfaction means a strong feeling of unhappiness or disappointment.","zh":"強烈不滿，是指強烈的不快或失望感。"},{"en":"A tenant may feel substantial dissatisfaction if repairs are delayed for months.","zh":"如果維修拖延數月，租客可能感到強烈不滿。"},{"en":"When people compare constantly, small differences can create substantial dissatisfaction.","zh":"當人們不斷比較，細小差異也可能造成強烈不滿。"},{"en":"This phrase is stronger than simply saying “not happy.”","zh":"這個短語比單純說「不高興」更強。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":6},{"front":"be prone to","meaning":"易於；傾向於","examples":[{"en":"Maximizers are more prone to experiencing regret after a purchase.","zh":"追求最優者更易於在購買後感到後悔。"},{"en":"To be prone to something means to be likely to experience it.","zh":"易於某事，是指較可能經歷它。"},{"en":"People who sleep too little are prone to making careless mistakes.","zh":"睡得太少的人容易犯粗心錯誤。"},{"en":"Maximizers are prone to regret because they keep imagining better options.","zh":"追求最優者傾向於後悔，因為他們不斷想像更好的選項。"},{"en":"This phrase describes a tendency, not a certainty.","zh":"這個短語描述傾向，而不是必然。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":7},{"front":"experience regret","meaning":"感到後悔","examples":[{"en":"People with many options are more likely to experience regret.","zh":"有很多選項的人較可能感到後悔。"},{"en":"To experience regret means to feel sorry about a choice made earlier.","zh":"感到後悔，是指對早前作出的選擇感到懊悔。"},{"en":"A shopper may experience regret after buying shoes that soon go on sale.","zh":"顧客買鞋後很快看到減價，可能感到後悔。"},{"en":"More options can increase regret because people imagine what they gave up.","zh":"更多選項可以增加後悔，因為人們想像自己放棄了甚麼。"},{"en":"This phrase describes an emotional reaction after a decision.","zh":"這個短語描述作決定後的情緒反應。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":7},{"front":"after a purchase","meaning":"購買之後","examples":[{"en":"Some shoppers experience regret after a purchase.","zh":"有些購物者在購買之後感到後悔。"},{"en":"After a purchase means after someone has bought something.","zh":"購買之後，是指某人買了東西以後。"},{"en":"A customer may check reviews again after a purchase and start doubting the choice.","zh":"顧客可能在購買之後再次查看評論，開始懷疑自己的選擇。"},{"en":"Feelings after a purchase can affect whether people enjoy the item.","zh":"購買之後的感受會影響人們是否享受該物品。"},{"en":"This phrase focuses on the period following a buying decision.","zh":"這個短語聚焦購買決定之後的時期。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":7},{"front":"acquisition","meaning":"購入物；買到的東西","examples":[{"en":"A disappointing acquisition can affect a maximizer’s well-being.","zh":"令人失望的購入物可以影響追求最優者的幸福感。"},{"en":"An acquisition is something someone has bought or obtained.","zh":"購入物是某人購買或取得的東西。"},{"en":"A new laptop is an important acquisition for a student starting university.","zh":"新手提電腦對開始大學生活的學生來說是重要購入物。"},{"en":"If an acquisition fails to meet expectations, the buyer may feel regret.","zh":"如果購入物未能符合期望，買家可能感到後悔。"},{"en":"This word is more formal than “purchase” or “thing bought.”","zh":"這個詞比 “purchase” 或 “thing bought” 更正式。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":7},{"front":"disappoint someone","meaning":"令某人失望","examples":[{"en":"If their acquisition disappoints them, maximizers recover more slowly.","zh":"如果購入物令他們失望，追求最優者恢復得較慢。"},{"en":"To disappoint someone means to make them feel unhappy because expectations were not met.","zh":"令某人失望，是指因未能符合期望而令他們不快。"},{"en":"A restaurant may disappoint customers if the food looks better online than in real life.","zh":"如果食物在網上看起來比現實好，餐廳可能令顧客失望。"},{"en":"Disappointment is stronger when people spent much time choosing.","zh":"當人們花了很多時間選擇，失望感會更強。"},{"en":"This phrase connects unmet expectations with negative feelings.","zh":"這個短語把未達期望與負面感受連接起來。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":7},{"front":"sense of well-being","meaning":"身心健康感；幸福感","examples":[{"en":"A disappointing purchase can harm a person’s sense of well-being.","zh":"令人失望的購買可以損害一個人的幸福感。"},{"en":"A sense of well-being is the feeling of being healthy, calm and generally satisfied.","zh":"幸福感是感到健康、平靜和整體滿意的感覺。"},{"en":"Enough sleep and supportive friends can improve a student’s sense of well-being.","zh":"足夠睡眠和支持自己的朋友可以改善學生的幸福感。"},{"en":"Regret after choices can reduce well-being even when life looks comfortable.","zh":"選擇後的後悔即使在生活看似舒適時，也會降低幸福感。"},{"en":"This phrase refers to overall mental and emotional condition.","zh":"這個短語指整體心理和情緒狀態。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":7},{"front":"take longer to recover","meaning":"需要較長時間恢復","examples":[{"en":"Maximizers take longer to recover from disappointment.","zh":"追求最優者從失望中恢復需要較長時間。"},{"en":"To take longer to recover means to need more time to feel normal again.","zh":"需要較長時間恢復，是指需要更多時間才能再次感覺正常。"},{"en":"A worker may take longer to recover after a harsh criticism from a manager.","zh":"工人受到經理嚴厲批評後，可能需要較長時間恢復。"},{"en":"People recover more slowly when they keep thinking about what went wrong.","zh":"當人們不斷想着哪裡出錯，恢復會較慢。"},{"en":"This phrase describes a slower return to emotional balance.","zh":"這個短語描述較慢地回到情緒平衡。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":7},{"front":"tend to","meaning":"傾向於","examples":[{"en":"Maximizers tend to brood more than satisficers.","zh":"追求最優者比滿意即止者更傾向於悶悶不樂地反覆思量。"},{"en":"Tend to means usually or often behave in a certain way.","zh":"傾向於是指通常或經常以某種方式行事。"},{"en":"Students who sleep late tend to feel tired in morning lessons.","zh":"睡得晚的學生傾向於在早堂感到疲倦。"},{"en":"People tend to compare more when choices are public and visible.","zh":"當選擇是公開和可見的，人們傾向於比較更多。"},{"en":"This phrase describes a general pattern, not an absolute rule.","zh":"這個短語描述一般模式，而不是絕對規則。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":7},{"front":"brood","meaning":"悶悶不樂地反覆思量","examples":[{"en":"Some people brood over choices after making them.","zh":"有些人在作出選擇後，會悶悶不樂地反覆思量。"},{"en":"To brood means to think sadly or worriedly about something for too long.","zh":"悶悶不樂地反覆思量，是指過久地悲傷或憂慮地思考某事。"},{"en":"A student may brood over one wrong answer for the whole day.","zh":"學生可能因一道錯題悶悶不樂地想一整天。"},{"en":"Brooding over decisions can make regret last longer.","zh":"對決定反覆思量會令後悔持續更久。"},{"en":"This word suggests heavy, repeated and unhappy thinking.","zh":"這個詞暗示沉重、重複而不快的思考。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":7},{"front":"ruminate","meaning":"反覆思考；鑽牛角尖","examples":[{"en":"Maximizers may ruminate about whether they made the right decision.","zh":"追求最優者可能反覆思考自己是否作出了正確決定。"},{"en":"To ruminate means to think about the same worry again and again.","zh":"反覆思考是指一次又一次想着同一個憂慮。"},{"en":"After an interview, a person may ruminate about every answer they gave.","zh":"面試後，一個人可能反覆思考自己給出的每個答案。"},{"en":"Rumination can make a small doubt feel much larger.","zh":"鑽牛角尖會令小小懷疑變得大很多。"},{"en":"This word is often used for repetitive negative thinking.","zh":"這個詞常用於重複的負面思考。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":7},{"front":"does it follow that","meaning":"是否由此可推論","examples":[{"en":"Does it follow that maximizers are less happy in general?","zh":"是否由此可推論，追求最優者整體而言較不快樂？"},{"en":"Does it follow that asks whether one conclusion logically comes from another point.","zh":"是否由此可推論，是問一個結論是否合乎邏輯地由另一點得出。"},{"en":"If a student studies longer, does it follow that the student will always score higher?","zh":"如果學生溫習更久，是否由此可推論他一定得分更高？"},{"en":"This phrase is used to question an assumption or conclusion.","zh":"這個短語用來質疑假設或結論。"},{"en":"It asks readers not to jump too quickly from evidence to belief.","zh":"它要求讀者不要太快從證據跳到信念。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":7},{"front":"in general","meaning":"整體而言","examples":[{"en":"The researchers asked whether maximizers are less happy in general.","zh":"研究人員詢問追求最優者整體而言是否較不快樂。"},{"en":"In general means overall or in most situations.","zh":"整體而言，是指總體上或在大多數情況下。"},{"en":"In general, people feel calmer when they have a clear plan.","zh":"整體而言，當人們有清晰計劃時會感到較平靜。"},{"en":"A statement about people in general may not fit every individual.","zh":"關於人們整體而言的說法未必適合每個個體。"},{"en":"This phrase looks at the broad pattern rather than one special case.","zh":"這個短語看的是整體模式，而不是一個特殊個案。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":8},{"front":"fill out questionnaires","meaning":"填寫問卷","examples":[{"en":"Participants filled out questionnaires about their well-being.","zh":"參與者填寫關於其幸福感的問卷。"},{"en":"To fill out questionnaires means to answer written or online survey questions.","zh":"填寫問卷，是指回答書面或網上調查問題。"},{"en":"Students may fill out questionnaires about school lunch quality.","zh":"學生可能填寫關於學校午餐質素的問卷。"},{"en":"Questionnaires help researchers collect information from many people efficiently.","zh":"問卷幫助研究人員有效地從許多人收集資料。"},{"en":"This phrase describes the act of completing survey forms.","zh":"這個短語描述完成調查表的行為。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":8},{"front":"a variety of","meaning":"各種各樣的……","examples":[{"en":"The study used a variety of questionnaires.","zh":"這項研究使用了各種各樣的問卷。"},{"en":"A variety of means several different kinds of something.","zh":"各種各樣的，是指幾種不同類型的某物。"},{"en":"A teacher may use a variety of activities to keep students engaged.","zh":"老師可能使用各種各樣的活動來保持學生投入。"},{"en":"Using a variety of methods can give a fuller picture of a problem.","zh":"使用各種各樣的方法可以更全面地了解問題。"},{"en":"This phrase suggests diversity rather than just one type.","zh":"這個短語暗示多樣性，而不只是一種類型。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":8},{"front":"reliable indicators of","meaning":"……的可靠指標","examples":[{"en":"The questionnaires are reliable indicators of well-being.","zh":"這些問卷是幸福感的可靠指標。"},{"en":"Reliable indicators of something are signs that measure or show it accurately.","zh":"某事的可靠指標，是指能準確衡量或顯示它的跡象。"},{"en":"Attendance can be a reliable indicator of student interest in a course.","zh":"出席率可以是學生對課程興趣的可靠指標。"},{"en":"Reliable indicators help researchers avoid guessing from weak evidence.","zh":"可靠指標幫助研究人員避免根據薄弱證據猜測。"},{"en":"This phrase is used when a measure can be trusted.","zh":"當一項衡量可信時，可以使用這個短語。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":8},{"front":"as might be expected","meaning":"正如可以預期","examples":[{"en":"As might be expected, high maximization scores were linked to lower happiness.","zh":"正如可以預期，高最大化傾向分數與較低快樂程度有關。"},{"en":"As might be expected means the result is not surprising.","zh":"正如可以預期，是指結果並不令人意外。"},{"en":"As might be expected, students who practised daily improved faster.","zh":"正如可以預期，每天練習的學生進步較快。"},{"en":"This phrase introduces a finding that fits common sense or earlier evidence.","zh":"這個短語引入符合常識或早前證據的發現。"},{"en":"It helps readers see that the result follows logically.","zh":"它幫助讀者看出結果合乎邏輯。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":8},{"front":"maximization scores","meaning":"最大化傾向分數","examples":[{"en":"People with high maximization scores were less satisfied with life.","zh":"最大化傾向分數高的人對生活較不滿意。"},{"en":"Maximization scores are ratings that show how strongly someone tries to maximize choices.","zh":"最大化傾向分數是顯示某人追求最佳選擇程度的評分。"},{"en":"A high maximization score may mean a person keeps searching for better options.","zh":"高最大化傾向分數可能表示一個人不斷尋找更好的選項。"},{"en":"These scores help researchers compare decision-making styles.","zh":"這些分數幫助研究人員比較決策風格。"},{"en":"This phrase names the numerical result of the Maximization Scale.","zh":"這個短語命名最大化傾向量表的數字結果。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":8},{"front":"satisfaction with life","meaning":"對生活的滿意度","examples":[{"en":"People with high maximization scores experienced less satisfaction with life.","zh":"最大化傾向分數高的人對生活的滿意度較低。"},{"en":"Satisfaction with life means how pleased someone feels with life overall.","zh":"對生活的滿意度，是指某人對整體生活感到多滿意。"},{"en":"A person may have high satisfaction with life if work, health and relationships feel stable.","zh":"如果工作、健康和人際關係感覺穩定，一個人可能對生活有高滿意度。"},{"en":"Constant regret can lower satisfaction with life even when choices are abundant.","zh":"持續後悔即使在選擇很多時，也會降低對生活的滿意度。"},{"en":"This phrase measures broad happiness, not just one moment.","zh":"這個短語衡量廣泛的快樂，而不只是一刻感受。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":8},{"front":"less optimistic","meaning":"較不樂觀","examples":[{"en":"Maximizers were less optimistic than people with low scores.","zh":"追求最優者比低分者較不樂觀。"},{"en":"Less optimistic means having less hope or confidence about good outcomes.","zh":"較不樂觀，是指對好結果的希望或信心較少。"},{"en":"A student may feel less optimistic after failing several practice tests.","zh":"學生多次模擬測驗失敗後，可能較不樂觀。"},{"en":"People who focus on what could go wrong may become less optimistic.","zh":"專注於可能出錯之處的人可能變得較不樂觀。"},{"en":"This phrase compares levels of hope between people or groups.","zh":"這個短語比較人或群體之間的希望程度。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":8},{"front":"more depressed","meaning":"較抑鬱","examples":[{"en":"People with high maximization scores were more depressed.","zh":"最大化傾向分數高的人較抑鬱。"},{"en":"More depressed means feeling lower in mood or more emotionally distressed.","zh":"較抑鬱，是指心情較低落或情緒困擾較大。"},{"en":"A worker may feel more depressed after months of heavy pressure and little support.","zh":"工人在數月高壓且缺乏支援後，可能較抑鬱。"},{"en":"Repeated regret can make people feel more depressed over time.","zh":"反覆後悔會隨時間令人感到較抑鬱。"},{"en":"This phrase describes a stronger level of low mood.","zh":"這個短語描述較強的低落情緒。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":8},{"front":"extreme maximization ratings","meaning":"極高最大化傾向評級","examples":[{"en":"Extreme maximization ratings were linked to higher depression scores.","zh":"極高最大化傾向評級與較高抑鬱分數有關。"},{"en":"Extreme maximization ratings are very high scores showing a strong maximizing tendency.","zh":"極高最大化傾向評級，是顯示強烈追求最優傾向的很高分數。"},{"en":"A person with extreme ratings may struggle to stop comparing choices.","zh":"有極高評級的人可能難以停止比較選擇。"},{"en":"Extreme ratings can help researchers identify people most affected by choice overload.","zh":"極高評級可以幫助研究人員識別最受選擇過多影響的人。"},{"en":"This phrase points to the highest end of the maximizing scale.","zh":"這個短語指最大化傾向量表的最高端。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":8},{"front":"depression scores","meaning":"抑鬱分數","examples":[{"en":"Some maximizers had depression scores in the borderline clinical range.","zh":"有些追求最優者的抑鬱分數處於臨床邊緣範圍。"},{"en":"Depression scores are ratings that estimate the level of depressive symptoms.","zh":"抑鬱分數是估計抑鬱症狀程度的評分。"},{"en":"A questionnaire may produce depression scores based on sleep, mood and motivation.","zh":"問卷可能根據睡眠、心情和動力產生抑鬱分數。"},{"en":"Higher depression scores can signal a need for further support or assessment.","zh":"較高抑鬱分數可能表示需要進一步支援或評估。"},{"en":"This phrase refers to measured results, not casual sadness.","zh":"這個短語指測量結果，而不是日常傷心。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":8},{"front":"place someone in","meaning":"使某人處於","examples":[{"en":"Their depression scores placed them in the borderline clinical range.","zh":"他們的抑鬱分數使他們處於臨床邊緣範圍。"},{"en":"To place someone in a range means to classify them within that level or category.","zh":"使某人處於某範圍，是指把他們分類到該程度或類別中。"},{"en":"Test results may place a student in an advanced class.","zh":"測驗結果可能使學生進入高階班。"},{"en":"A score can place someone in a risk group even before a diagnosis is made.","zh":"分數可以在診斷前把某人置於風險群組中。"},{"en":"This phrase describes classification based on measurement.","zh":"這個短語描述根據測量作分類。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":9},{"front":"borderline clinical range","meaning":"臨床邊緣範圍","examples":[{"en":"Extreme maximizers had scores in the borderline clinical range.","zh":"極端追求最優者的分數處於臨床邊緣範圍。"},{"en":"The borderline clinical range is a score level close to possible clinical concern.","zh":"臨床邊緣範圍，是接近可能有臨床關注的分數水平。"},{"en":"A health screening result in the borderline range may require follow-up.","zh":"健康篩查結果處於邊緣範圍，可能需要跟進。"},{"en":"Borderline scores do not always mean illness, but they deserve attention.","zh":"邊緣分數不一定代表疾病，但值得注意。"},{"en":"This phrase indicates a serious but not necessarily confirmed level of concern.","zh":"這個短語表示嚴重但未必已確認的關注程度。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":9},{"front":"several factors explain why","meaning":"有幾個因素解釋為何","examples":[{"en":"Several factors explain why more choice is not always better.","zh":"有幾個因素解釋為何更多選擇不一定更好。"},{"en":"Several factors explain why means there is more than one reason behind a result.","zh":"有幾個因素解釋為何，是指某結果背後有多於一個原因。"},{"en":"Several factors explain why students may feel tired, including sleep, stress and workload.","zh":"有幾個因素解釋為何學生可能感到疲倦，包括睡眠、壓力和工作量。"},{"en":"Complex problems often need several explanations rather than one simple cause.","zh":"複雜問題通常需要幾個解釋，而不是一個簡單原因。"},{"en":"This phrase prepares readers for a list of reasons.","zh":"這個短語為一系列原因作準備。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":9},{"front":"high among these","meaning":"其中最重要的是","examples":[{"en":"High among these factors are opportunity costs.","zh":"其中最重要的是機會成本。"},{"en":"High among these means one of the most important items in a group.","zh":"其中最重要的是，指一組事物中最重要的項目之一。"},{"en":"High among the reasons for student stress is lack of sleep.","zh":"學生壓力的原因中，其中最重要的是睡眠不足。"},{"en":"This phrase highlights a key factor without saying it is the only one.","zh":"這個短語突出一個關鍵因素，但不表示它是唯一因素。"},{"en":"It is a formal way to point to a major cause.","zh":"它是指出主要原因的正式說法。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":9},{"front":"opportunity costs","meaning":"機會成本","examples":[{"en":"Opportunity costs help explain why more options can reduce satisfaction.","zh":"機會成本有助解釋為何更多選項會降低滿足感。"},{"en":"Opportunity costs are the benefits lost when we choose one option instead of another.","zh":"機會成本是選擇一個選項而放棄另一個選項時失去的好處。"},{"en":"If you study tonight, the opportunity cost may be missing dinner with friends.","zh":"如果你今晚溫習，機會成本可能是錯過與朋友晚餐。"},{"en":"More options create more opportunity costs because more alternatives are given up.","zh":"更多選項創造更多機會成本，因為放棄了更多替代選項。"},{"en":"This concept explains why choosing can feel like losing.","zh":"這個概念解釋為何選擇會感覺像失去。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":9},{"front":"any given option","meaning":"任何一個特定選項","examples":[{"en":"The quality of any given option depends on its alternatives.","zh":"任何一個特定選項的質素取決於其替代選項。"},{"en":"Any given option means any one particular choice being considered.","zh":"任何一個特定選項，是指正在考慮的任何一個具體選擇。"},{"en":"Any given restaurant may look good until you compare it with cheaper nearby places.","zh":"任何一間餐廳可能看起來不錯，直到你把它與附近較便宜的地方比較。"},{"en":"The value of any given option changes when better alternatives appear.","zh":"當更好的替代選項出現，任何一個特定選項的價值都會改變。"},{"en":"This phrase focuses on one choice inside a larger set.","zh":"這個短語聚焦較大選項集合中的一個選擇。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":9},{"front":"be assessed in isolation from","meaning":"與……分開評估","examples":[{"en":"An option cannot be assessed in isolation from its alternatives.","zh":"一個選項不能與其替代選項分開評估。"},{"en":"To be assessed in isolation from something means to be judged separately from it.","zh":"與某物分開評估，是指把它與該物分開來判斷。"},{"en":"A student’s score should not be assessed in isolation from the difficulty of the test.","zh":"學生分數不應與測驗難度分開評估。"},{"en":"Choices feel different when they are assessed alongside what was not chosen.","zh":"當選擇與未被選的東西一起評估時，感覺會不同。"},{"en":"This phrase stresses that context affects judgement.","zh":"這個短語強調背景會影響判斷。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":9},{"front":"alternatives","meaning":"替代選項","examples":[{"en":"The value of one choice depends on its alternatives.","zh":"一個選擇的價值取決於其替代選項。"},{"en":"Alternatives are other possible choices besides the one being considered.","zh":"替代選項是正在考慮的選擇以外的其他可能選擇。"},{"en":"If one bus is late, the alternatives may be walking, taking a taxi or waiting.","zh":"如果一班巴士遲到，替代選項可能是步行、乘的士或等待。"},{"en":"More alternatives can increase freedom but also increase comparison.","zh":"更多替代選項可以增加自由，但也增加比較。"},{"en":"This word is central to understanding choice and opportunity cost.","zh":"這個詞是理解選擇和機會成本的核心。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":9},{"front":"making a selection","meaning":"作出選擇","examples":[{"en":"One cost of making a selection is losing other opportunities.","zh":"作出選擇的一個成本是失去其他機會。"},{"en":"Making a selection means choosing one option from a group.","zh":"作出選擇，是指從一組選項中選一個。"},{"en":"A student makes a selection when choosing one elective from several courses.","zh":"學生從幾個課程中選一個選修科時，就是作出選擇。"},{"en":"Making a selection can bring relief, but it also closes other paths.","zh":"作出選擇可以帶來放鬆，但也會關閉其他道路。"},{"en":"This phrase focuses on the act of choosing.","zh":"這個短語聚焦選擇這個行動。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":9},{"front":"lose the opportunities","meaning":"失去機會","examples":[{"en":"Choosing one option means losing the opportunities offered by another.","zh":"選擇一個選項意味着失去另一個選項提供的機會。"},{"en":"To lose the opportunities means to miss possible benefits because of a choice.","zh":"失去機會，是指因某個選擇而錯過可能的好處。"},{"en":"If you work overtime, you may lose the opportunity to rest with family.","zh":"如果你加班，可能會失去與家人休息的機會。"},{"en":"People feel regret when lost opportunities seem attractive afterward.","zh":"當失去的機會事後看起來吸引，人們會感到後悔。"},{"en":"This phrase explains the painful side of choosing.","zh":"這個短語解釋選擇中令人痛苦的一面。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":9},{"front":"a different option","meaning":"另一個選項","examples":[{"en":"A different option might have offered other benefits.","zh":"另一個選項可能提供其他好處。"},{"en":"A different option means another choice that was not selected.","zh":"另一個選項，是指沒有被選中的另一個選擇。"},{"en":"A different option, such as taking the train, may be cheaper than driving.","zh":"另一個選項，例如乘火車，可能比駕車便宜。"},{"en":"Thinking about a different option can make people question their decision.","zh":"想着另一個選項可能令人質疑自己的決定。"},{"en":"This phrase is often used when comparing what was chosen with what was not.","zh":"這個短語常用於比較已選和未選的東西。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":9},{"front":"afford opportunities","meaning":"帶來機會","examples":[{"en":"A different option would have afforded different opportunities.","zh":"另一個選項本會帶來不同機會。"},{"en":"To afford opportunities means to provide chances or possibilities.","zh":"帶來機會，是指提供機會或可能性。"},{"en":"A scholarship can afford students opportunities to study abroad.","zh":"獎學金可以為學生帶來出國留學的機會。"},{"en":"Different jobs afford different opportunities for learning, income and lifestyle.","zh":"不同工作帶來不同學習、收入和生活方式機會。"},{"en":"This phrase is formal and means “give” or “provide” opportunities.","zh":"這個短語較正式，意思是「給予」或「提供」機會。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":10},{"front":"vacationing on the beach","meaning":"在海灘度假","examples":[{"en":"Vacationing on the beach may mean missing other experiences.","zh":"在海灘度假可能意味着錯過其他經歷。"},{"en":"Vacationing on the beach means spending a holiday by the sea.","zh":"在海灘度假，是指在海邊度過假期。"},{"en":"A family may enjoy vacationing on the beach because children can swim and play.","zh":"家庭可能享受在海灘度假，因為孩子可以游泳和玩耍。"},{"en":"Choosing a beach holiday may mean giving up museums, restaurants or mountain hikes.","zh":"選擇海灘假期可能意味着放棄博物館、餐廳或登山。"},{"en":"This example shows how even enjoyable choices have opportunity costs.","zh":"這個例子顯示即使愉快的選擇也有機會成本。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":10},{"front":"Cape Cod","meaning":"Cape Cod","examples":[{"en":"A vacation on the beach in Cape Cod may have opportunity costs.","zh":"在 Cape Cod 海灘度假可能有機會成本。"},{"en":"Cape Cod is used as an example of a beach holiday destination.","zh":"Cape Cod 在此用作海灘度假目的地的例子。"},{"en":"A family choosing Cape Cod may enjoy the sea but miss another type of trip.","zh":"選擇 Cape Cod 的家庭可能享受大海，但錯過另一類旅行。"},{"en":"Place names like Cape Cod make abstract opportunity costs easier to imagine.","zh":"像 Cape Cod 這樣的地名令抽象機會成本更容易想像。"},{"en":"In the passage, Cape Cod contrasts with Napa Valley as another holiday choice.","zh":"在篇章中，Cape Cod 與 Napa Valley 作為另一個假期選擇形成對比。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":10},{"front":"miss the fabulous restaurants","meaning":"錯過一流餐廳","examples":[{"en":"A beach vacation may mean missing the fabulous restaurants in Napa Valley.","zh":"海灘度假可能意味着錯過 Napa Valley 的一流餐廳。"},{"en":"To miss the fabulous restaurants means to lose the chance to enjoy excellent places to eat.","zh":"錯過一流餐廳，是指失去享受優質餐廳的機會。"},{"en":"If you choose a hiking trip, you may miss the famous restaurants in the city.","zh":"如果你選擇遠足旅行，可能會錯過城市中的著名餐廳。"},{"en":"Thinking about what you miss can reduce satisfaction with the choice you made.","zh":"想着自己錯過甚麼，可能降低對已作選擇的滿意度。"},{"en":"This phrase gives a concrete example of opportunity cost.","zh":"這個短語提供機會成本的具體例子。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":10},{"front":"Napa Valley","meaning":"Napa Valley","examples":[{"en":"Napa Valley is used as an example of an alternative holiday choice.","zh":"Napa Valley 被用作另一個假期選擇的例子。"},{"en":"Napa Valley represents a destination known here for restaurants and a different travel experience.","zh":"Napa Valley 在此代表以餐廳和不同旅遊體驗聞名的目的地。"},{"en":"A traveller choosing the beach may compare that trip with Napa Valley.","zh":"選擇海灘的旅客可能把那次旅行與 Napa Valley 比較。"},{"en":"Comparing Napa Valley with Cape Cod shows how one vacation excludes another.","zh":"比較 Napa Valley 與 Cape Cod，顯示一個假期如何排除另一個。"},{"en":"The place name makes the abstract idea of lost alternatives concrete.","zh":"這個地名令失去替代選項的抽象概念變得具體。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":10},{"front":"decision-making research","meaning":"決策研究","examples":[{"en":"Early decision-making research examined how people respond to gains and losses.","zh":"早期決策研究考察人們如何回應收益和損失。"},{"en":"Decision-making research studies how people choose, judge risk and react to outcomes.","zh":"決策研究是研究人們如何選擇、判斷風險和回應結果。"},{"en":"Researchers may use shopping, tickets or money tasks in decision-making research.","zh":"研究人員可能在決策研究中使用購物、門票或金錢任務。"},{"en":"This research helps explain why choices can feel emotional, not just logical.","zh":"這類研究幫助解釋為何選擇可以是情緒性的，而不只是邏輯性的。"},{"en":"The phrase refers to scientific study of how decisions are made.","zh":"這個短語指對人們如何作決定的科學研究。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":10},{"front":"respond strongly to","meaning":"對……反應強烈","examples":[{"en":"People respond much more strongly to losses than gains.","zh":"人們對損失的反應比對收益強烈得多。"},{"en":"To respond strongly to something means to react with intense feeling or behaviour.","zh":"對某事反應強烈，是指以強烈感受或行為回應它。"},{"en":"Children may respond strongly to unfair treatment in class.","zh":"孩子可能對課堂上的不公平對待反應強烈。"},{"en":"People often respond strongly to losses because losing feels painful.","zh":"人們常對損失反應強烈，因為失去令人痛苦。"},{"en":"This phrase describes a powerful reaction to an event or result.","zh":"這個短語描述對事件或結果的強烈反應。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":10},{"front":"losses than gains","meaning":"損失多於收益","examples":[{"en":"People react more strongly to losses than gains.","zh":"人們對損失的反應比對收益更強烈。"},{"en":"Losses than gains is used in comparisons showing losses have a stronger effect than benefits.","zh":"損失多於收益用於比較，表示損失的影響比好處更強。"},{"en":"Losing 100 dollars may hurt more than finding 100 dollars pleases us.","zh":"失去 100 元帶來的痛苦，可能大於撿到 100 元帶來的快樂。"},{"en":"This pattern helps explain why opportunity costs reduce satisfaction.","zh":"這種模式幫助解釋為何機會成本會降低滿足感。"},{"en":"The phrase points to the emotional weight of what people lose.","zh":"這個短語指出人們所失去的東西在情緒上的重量。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":10},{"front":"reduce the overall desirability of","meaning":"降低……的整體吸引力","examples":[{"en":"Opportunity costs reduce the overall desirability of a chosen option.","zh":"機會成本會降低已選選項的整體吸引力。"},{"en":"To reduce the overall desirability of something means to make it seem less attractive as a whole.","zh":"降低某物的整體吸引力，是指令它整體看來較不吸引。"},{"en":"Long travel time can reduce the overall desirability of a cheaper flat.","zh":"長通勤時間會降低較便宜單位的整體吸引力。"},{"en":"Lost alternatives can make a good choice feel less satisfying.","zh":"失去的替代選項會令好選擇感覺較不令人滿意。"},{"en":"This phrase shows how hidden costs weaken attraction.","zh":"這個短語顯示隱藏成本如何削弱吸引力。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":10},{"front":"the most preferred choice","meaning":"最受偏好的選擇","examples":[{"en":"Opportunity costs can make the most preferred choice feel less satisfying.","zh":"機會成本會令最受偏好的選擇感覺較不令人滿意。"},{"en":"The most preferred choice is the option someone likes best among the available choices.","zh":"最受偏好的選擇，是指某人在可用選項中最喜歡的選項。"},{"en":"A student’s most preferred choice may be a university that matches both interest and budget.","zh":"學生最受偏好的選擇可能是一間同時符合興趣和預算的大學。"},{"en":"Even the most preferred choice can feel worse when attractive alternatives are remembered.","zh":"即使是最受偏好的選擇，當人記起吸引的替代選項時也可能感覺較差。"},{"en":"This phrase identifies the option ranked highest by the decision-maker.","zh":"這個短語指出決策者排名最高的選項。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":10},{"front":"the more alternatives there are","meaning":"替代選項越多","examples":[{"en":"The more alternatives there are, the deeper the sense of loss may be.","zh":"替代選項越多，失落感可能越深。"},{"en":"The more alternatives there are means as the number of other choices increases.","zh":"替代選項越多，是指其他選擇的數量增加時。"},{"en":"The more restaurants there are, the harder it may be to feel sure about dinner.","zh":"餐廳越多，可能越難對晚餐選擇感到肯定。"},{"en":"More alternatives can increase the number of imagined lost benefits.","zh":"更多替代選項會增加被想像出來的失去好處數量。"},{"en":"This structure links an increase in one thing with an increase in another.","zh":"這個結構把一件事的增加與另一件事的增加連接起來。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":10},{"front":"sense of loss","meaning":"失落感","examples":[{"en":"More alternatives can deepen our sense of loss.","zh":"更多替代選項可以加深我們的失落感。"},{"en":"A sense of loss is the feeling that something valuable has been given up.","zh":"失落感是覺得自己放棄了有價值事物的感覺。"},{"en":"A student may feel a sense of loss after choosing one club and leaving another.","zh":"學生選擇一個學會而放棄另一個後，可能感到失落感。"},{"en":"The more attractive the rejected options are, the stronger the sense of loss becomes.","zh":"被拒絕的選項越吸引，失落感就越強。"},{"en":"This phrase explains why choosing can feel painful.","zh":"這個短語解釋為何選擇可以令人痛苦。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":11},{"front":"derive satisfaction from","meaning":"從……中獲得滿足感","examples":[{"en":"People may derive less satisfaction from their ultimate decision.","zh":"人們可能從最終決定中獲得較少滿足感。"},{"en":"To derive satisfaction from something means to get a feeling of pleasure or contentment from it.","zh":"從某事中獲得滿足感，是指從它得到愉快或滿意的感覺。"},{"en":"A teacher may derive satisfaction from seeing students improve.","zh":"老師可能從看見學生進步中獲得滿足感。"},{"en":"Regret can reduce the satisfaction people derive from a choice.","zh":"後悔會降低人們從選擇中獲得的滿足感。"},{"en":"This phrase describes where a positive feeling comes from.","zh":"這個短語描述正面感受從哪裡來。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":11},{"front":"ultimate decision","meaning":"最終決定","examples":[{"en":"Too many options can reduce satisfaction with the ultimate decision.","zh":"太多選項可以降低人們對最終決定的滿足感。"},{"en":"The ultimate decision is the final choice made after considering options.","zh":"最終決定是在考慮選項後作出的最後選擇。"},{"en":"After visiting several flats, the family’s ultimate decision was to rent the smallest one.","zh":"參觀幾個單位後，這個家庭的最終決定是租最小的一個。"},{"en":"Doubt about rejected options can weaken confidence in the ultimate decision.","zh":"對被拒絕選項的懷疑會削弱對最終決定的信心。"},{"en":"This phrase focuses on the final result of the decision process.","zh":"這個短語聚焦決策過程的最後結果。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":11},{"front":"less severe for","meaning":"對……來說較不嚴重","examples":[{"en":"The problem of opportunity costs is less severe for a satisficer.","zh":"機會成本問題對滿意即止者來說較不嚴重。"},{"en":"Less severe for someone means causing that person less difficulty or harm.","zh":"對某人來說較不嚴重，是指對那人造成較少困難或傷害。"},{"en":"Exam stress may be less severe for students who plan early.","zh":"對早作計劃的學生來說，考試壓力可能較不嚴重。"},{"en":"Opportunity costs are less severe for satisficers because they consider fewer alternatives.","zh":"機會成本對滿意即止者較不嚴重，因為他們考慮較少替代選項。"},{"en":"This phrase compares how strongly different people are affected.","zh":"這個短語比較不同人受影響的強度。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":11},{"front":"the latter","meaning":"後者","examples":[{"en":"The latter’s good-enough philosophy reduces the burden of choice.","zh":"後者「夠好便可」的理念減少了選擇負擔。"},{"en":"The latter means the second of two people or things just mentioned.","zh":"後者是指剛提及的兩個人或事物中的第二個。"},{"en":"If we compare buses and trains, the latter means trains.","zh":"如果我們比較巴士和火車，後者就是火車。"},{"en":"This phrase helps avoid repeating the second item in a comparison.","zh":"這個短語幫助避免重複比較中的第二項。"},{"en":"In the passage, the latter refers to satisficers, not maximizers.","zh":"在篇章中，後者指滿意即止者，而不是追求最優者。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":11},{"front":"good-enough philosophy","meaning":"夠好便可的理念","examples":[{"en":"The good-enough philosophy helps satisficers avoid excessive regret.","zh":"夠好便可的理念幫助滿意即止者避免過度後悔。"},{"en":"A good-enough philosophy is the belief that a satisfactory choice is acceptable.","zh":"夠好便可的理念，是指相信令人滿意的選擇已可接受。"},{"en":"A busy parent may use a good-enough philosophy when choosing a simple dinner.","zh":"繁忙家長選擇簡單晚餐時，可能使用夠好便可的理念。"},{"en":"This mindset reduces stress because people stop demanding perfection.","zh":"這種心態減少壓力，因為人們不再要求完美。"},{"en":"The phrase describes a practical attitude toward decision-making.","zh":"這個短語描述面對決策的實用態度。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":11},{"front":"survive thoughts about","meaning":"經得起對……的思考","examples":[{"en":"The good-enough philosophy can survive thoughts about opportunity costs.","zh":"夠好便可的理念可以經得起對機會成本的思考。"},{"en":"To survive thoughts about something means to remain strong even after considering it.","zh":"經得起對某事的思考，是指即使考慮該事後仍然站得住。"},{"en":"A decision can survive criticism if the reasons behind it are clear.","zh":"如果背後理由清楚，一個決定可以經得起批評。"},{"en":"A good-enough choice survives opportunity-cost thinking because it never promised perfection.","zh":"夠好的選擇經得起機會成本思考，因為它從不承諾完美。"},{"en":"This phrase shows that an idea can withstand doubt.","zh":"這個短語顯示一個想法能承受懷疑。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":11},{"front":"lead to","meaning":"導致；帶來","examples":[{"en":"The good-enough standard leads to much less searching.","zh":"夠好便可的標準導致搜尋大幅減少。"},{"en":"To lead to something means to cause it or result in it.","zh":"導致某事，是指造成或帶來該結果。"},{"en":"Poor sleep can lead to weak concentration in class.","zh":"睡眠不足會導致課堂專注力弱。"},{"en":"A clear standard can lead to faster decisions.","zh":"清晰標準可以帶來更快的決定。"},{"en":"This phrase connects a cause with its result.","zh":"這個短語把原因與結果連接起來。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":11},{"front":"searching and inspection of alternatives","meaning":"搜尋及檢查替代選項","examples":[{"en":"Satisficers do less searching and inspection of alternatives.","zh":"滿意即止者較少搜尋及檢查替代選項。"},{"en":"Searching and inspection of alternatives means looking for and checking other possible choices.","zh":"搜尋及檢查替代選項，是指尋找並檢查其他可能選擇。"},{"en":"A shopper may do searching and inspection of alternatives before choosing a phone plan.","zh":"顧客選擇手機計劃前，可能會搜尋及檢查替代選項。"},{"en":"Too much inspection of alternatives can make a decision feel tiring.","zh":"過多檢查替代選項會令決策感覺疲憊。"},{"en":"This phrase describes the comparison work people do before choosing.","zh":"這個短語描述人們選擇前所做的比較工作。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":11},{"front":"the best standard","meaning":"最佳標準","examples":[{"en":"The maximizer’s best standard requires more comparison.","zh":"追求最優者的最佳標準需要更多比較。"},{"en":"The best standard is the rule that only the top option is acceptable.","zh":"最佳標準是只有最高選項才可接受的規則。"},{"en":"A student using the best standard may rewrite an essay many times.","zh":"使用最佳標準的學生可能多次重寫作文。"},{"en":"This standard creates pressure because good choices may still feel insufficient.","zh":"這個標準造成壓力，因為好選擇仍可能感覺不足。"},{"en":"The phrase describes a demanding rule for judging options.","zh":"這個短語描述用來判斷選項的高要求規則。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":11},{"front":"under consideration","meaning":"正在考慮中","examples":[{"en":"With fewer choices under consideration, people face fewer opportunity costs.","zh":"正在考慮中的選擇較少，人們面對的機會成本也較少。"},{"en":"Under consideration means being thought about or examined before a decision.","zh":"正在考慮中，是指在決定前正被思考或檢查。"},{"en":"Several designs are under consideration for the new school logo.","zh":"幾個設計正在被考慮用作新校徽。"},{"en":"Fewer options under consideration can make decisions feel lighter.","zh":"正在考慮中的選項較少，可以令決定感覺較輕鬆。"},{"en":"This phrase refers to choices still being actively considered.","zh":"這個短語指仍被積極考慮的選擇。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":11},{"front":"subtract opportunity costs","meaning":"扣除機會成本","examples":[{"en":"A person with fewer options has fewer opportunity costs to subtract.","zh":"選項較少的人需要扣除的機會成本較少。"},{"en":"To subtract opportunity costs means to mentally reduce the value of a choice by considering what was lost.","zh":"扣除機會成本，是指在心理上因考慮失去的東西而降低某選擇的價值。"},{"en":"A cheap flat may feel less attractive after subtracting the cost of long travel.","zh":"扣除長途通勤成本後，便宜單位可能感覺較不吸引。"},{"en":"The more losses people subtract, the less satisfying a choice may feel.","zh":"人們扣除的損失越多，選擇可能越不令人滿意。"},{"en":"This phrase describes how alternatives reduce perceived value.","zh":"這個短語描述替代選項如何降低感知價值。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":12},{"front":"just as","meaning":"正如","examples":[{"en":"Just as people feel sorrow about lost opportunities, they may regret their final choice.","zh":"正如人們對失去的機會感到悲傷，他們也可能對最終選擇感到後悔。"},{"en":"Just as means in the same way that something else happens.","zh":"正如，是指就像另一件事發生的方式一樣。"},{"en":"Just as exercise strengthens the body, practice strengthens language skills.","zh":"正如運動強化身體，練習也強化語言能力。"},{"en":"This phrase compares two similar patterns or effects.","zh":"這個短語比較兩種相似模式或影響。"},{"en":"It helps readers see a connection between two ideas.","zh":"它幫助讀者看見兩個想法之間的連繫。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":12},{"front":"feel sorrow about","meaning":"對……感到悲傷","examples":[{"en":"People may feel sorrow about the opportunities they have forgone.","zh":"人們可能對已放棄的機會感到悲傷。"},{"en":"To feel sorrow about something means to feel sadness over it.","zh":"對某事感到悲傷，是指因它而感到難過。"},{"en":"A student may feel sorrow about missing a friend’s farewell party.","zh":"學生可能對錯過朋友的告別派對感到悲傷。"},{"en":"Feeling sorrow about lost chances can make a final choice feel weaker.","zh":"對失去機會感到悲傷，會令最終選擇感覺較弱。"},{"en":"This phrase is stronger and more serious than “feel a little sad.”","zh":"這個短語比「有點傷心」更強、更嚴肅。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":12},{"front":"forgone opportunities","meaning":"已放棄的機會","examples":[{"en":"Forgone opportunities can make people feel regret.","zh":"已放棄的機會會令人感到後悔。"},{"en":"Forgone opportunities are chances that were given up when another option was chosen.","zh":"已放棄的機會，是指選擇另一個選項時放棄了的機會。"},{"en":"Taking a weekend job may create forgone opportunities to rest or meet friends.","zh":"做週末兼職可能產生已放棄的休息或見朋友機會。"},{"en":"People notice forgone opportunities more when the rejected options looked attractive.","zh":"當被拒絕的選項看起來吸引，人們更容易注意已放棄的機會。"},{"en":"This phrase is closely connected with opportunity costs.","zh":"這個短語與機會成本密切相關。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":12},{"front":"suffer regret about","meaning":"對……感到後悔","examples":[{"en":"People may suffer regret about the option they settled on.","zh":"人們可能對自己選定的選項感到後悔。"},{"en":"To suffer regret about something means to feel painful regret because of it.","zh":"對某事感到後悔，是指因它而感到痛苦的懊悔。"},{"en":"A buyer may suffer regret about a phone after seeing a better model the next day.","zh":"買家第二天看到更好型號後，可能對手機感到後悔。"},{"en":"Regret becomes harder when people believe they could have chosen better.","zh":"當人們相信自己本可選得更好，後悔會更難受。"},{"en":"This phrase stresses that regret can be emotionally painful.","zh":"這個短語強調後悔可以帶來情緒痛苦。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":12},{"front":"settle on","meaning":"選定","examples":[{"en":"People may regret the option they finally settled on.","zh":"人們可能對自己最終選定的選項感到後悔。"},{"en":"To settle on an option means to finally choose it after thinking.","zh":"選定一個選項，是指思考後最終選擇它。"},{"en":"After comparing several cafés, we settled on the quiet one near the station.","zh":"比較幾間咖啡店後，我們選定車站附近安靜的那間。"},{"en":"People may still doubt the option they settled on if they keep comparing.","zh":"如果人們繼續比較，仍可能懷疑自己選定的選項。"},{"en":"This phrase describes the final choice after consideration.","zh":"這個短語描述考慮後的最終選擇。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":12},{"front":"devise a scale","meaning":"設計量表","examples":[{"en":"The researchers devised a scale to measure regret.","zh":"研究人員設計了一個量表來衡量後悔。"},{"en":"To devise a scale means to design a measurement tool.","zh":"設計量表，是指設計一種測量工具。"},{"en":"A teacher may devise a scale to rate students’ speaking confidence.","zh":"老師可能設計量表來評估學生的口語信心。"},{"en":"Researchers devise scales to turn feelings into measurable data.","zh":"研究人員設計量表，把感受轉化為可衡量資料。"},{"en":"This phrase describes creating a structured way to measure something.","zh":"這個短語描述創造一種有結構的測量方法。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":12},{"front":"measure proneness to","meaning":"衡量……的傾向","examples":[{"en":"The scale measures proneness to feeling regret.","zh":"這個量表衡量容易感到後悔的傾向。"},{"en":"To measure proneness to something means to assess how likely someone is to experience it.","zh":"衡量某事的傾向，是指評估某人有多可能經歷它。"},{"en":"A survey may measure proneness to stress before exams.","zh":"問卷可能衡量考試前容易感到壓力的傾向。"},{"en":"Measuring proneness helps identify people who may need support.","zh":"衡量傾向有助識別可能需要支援的人。"},{"en":"This phrase focuses on tendency, not a single event.","zh":"這個短語聚焦傾向，而不是單一事件。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":12},{"front":"proneness to feeling regret","meaning":"容易感到後悔的傾向","examples":[{"en":"Proneness to feeling regret is linked to lower happiness.","zh":"容易感到後悔的傾向與較低快樂程度有關。"},{"en":"Proneness to feeling regret means a tendency to regret decisions easily.","zh":"容易感到後悔的傾向，是指很容易對決定感到後悔。"},{"en":"A shopper with this proneness may feel bad after almost every purchase.","zh":"有這種傾向的顧客可能幾乎每次購物後都感覺不好。"},{"en":"This tendency can reduce happiness because decisions rarely feel settled.","zh":"這種傾向會降低快樂，因為決定很少感覺真正定下來。"},{"en":"The phrase describes vulnerability to regret.","zh":"這個短語描述對後悔的脆弱性。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":12},{"front":"high sensitivity to regret","meaning":"對後悔高度敏感","examples":[{"en":"People with high sensitivity to regret are less satisfied with life.","zh":"對後悔高度敏感的人對生活較不滿意。"},{"en":"High sensitivity to regret means being strongly affected by the possibility of regretting a choice.","zh":"對後悔高度敏感，是指強烈受可能後悔選擇所影響。"},{"en":"A person with high regret sensitivity may avoid choosing because every option feels risky.","zh":"對後悔高度敏感的人可能避免選擇，因為每個選項都感覺有風險。"},{"en":"This sensitivity can make even ordinary decisions emotionally heavy.","zh":"這種敏感會令普通決定也變得情緒沉重。"},{"en":"The phrase describes a strong emotional reaction to possible mistakes.","zh":"這個短語描述對可能錯誤的強烈情緒反應。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":12},{"front":"low sensitivity","meaning":"低敏感度","examples":[{"en":"People with low sensitivity to regret tend to be happier.","zh":"對後悔低敏感度的人傾向較快樂。"},{"en":"Low sensitivity means being less strongly affected by something.","zh":"低敏感度，是指較不受某事強烈影響。"},{"en":"A shopper with low sensitivity to regret may buy a suitable item and move on.","zh":"對後悔低敏感度的顧客可能買到合適物品後就放下。"},{"en":"Low regret sensitivity can make decisions feel lighter and easier.","zh":"低後悔敏感度可以令決定感覺較輕鬆容易。"},{"en":"This phrase contrasts with being highly sensitive to regret.","zh":"這個短語與對後悔高度敏感形成對比。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":12},{"front":"not surprisingly","meaning":"不出所料","examples":[{"en":"Not surprisingly, people with high regret sensitivity tend to be maximizers.","zh":"不出所料，對後悔高度敏感的人傾向是追求最優者。"},{"en":"Not surprisingly means the result is expected or easy to understand.","zh":"不出所料，是指結果是預期之內或容易理解的。"},{"en":"Not surprisingly, students who sleep well concentrate better in class.","zh":"不出所料，睡得好的學生在課堂上更能集中。"},{"en":"This phrase introduces a finding that follows logically from earlier points.","zh":"這個短語引入合乎早前論點的發現。"},{"en":"It tells readers that the result should not feel unexpected.","zh":"它告訴讀者結果不應令人意外。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":13},{"front":"regret sensitivity","meaning":"對後悔的敏感度","examples":[{"en":"Regret sensitivity is associated with maximization.","zh":"對後悔的敏感度與追求最優有關。"},{"en":"Regret sensitivity means how strongly a person reacts to possible or actual regret.","zh":"對後悔的敏感度，是指一個人對可能或實際後悔的反應強度。"},{"en":"High regret sensitivity may make someone check every review before buying.","zh":"高後悔敏感度可能令某人在購買前查看每一篇評論。"},{"en":"When regret sensitivity is strong, choosing can feel emotionally risky.","zh":"當對後悔的敏感度強，選擇會感覺有情緒風險。"},{"en":"This phrase links regret with decision-making style.","zh":"這個短語把後悔與決策風格連接起來。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":13},{"front":"worry over future regret","meaning":"對將來後悔的憂慮","examples":[{"en":"Worry over future regret may cause people to become maximizers.","zh":"對將來後悔的憂慮可能使人成為追求最優者。"},{"en":"Worry over future regret means fear that a present choice will feel wrong later.","zh":"對將來後悔的憂慮，是指害怕現在的選擇之後會感覺錯。"},{"en":"A student may worry over future regret when choosing a university major.","zh":"學生選擇大學主修時，可能有對將來後悔的憂慮。"},{"en":"This worry can make people search longer before deciding.","zh":"這種憂慮會令人在決定前搜尋更久。"},{"en":"The phrase explains why some people demand the best possible choice.","zh":"這個短語解釋為何有些人要求可能之中最好的選擇。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":13},{"front":"a major reason that","meaning":"……的主要原因","examples":[{"en":"Future regret is a major reason that some people become maximizers.","zh":"將來後悔是有些人成為追求最優者的主要原因。"},{"en":"A major reason that means an important cause explaining why something happens.","zh":"……的主要原因，是指解釋某事發生的重要原因。"},{"en":"Cost is a major reason that families choose public schools.","zh":"成本是家庭選擇公立學校的主要原因。"},{"en":"A major reason can strongly influence behaviour even if it is not the only cause.","zh":"主要原因即使不是唯一原因，也能強烈影響行為。"},{"en":"This phrase introduces one of the main explanations.","zh":"這個短語引入主要解釋之一。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":13},{"front":"be sure","meaning":"確定；肯定","examples":[{"en":"The only way to be sure is to make the best possible decision.","zh":"唯一能確定的方法是作出可能之中最好的決定。"},{"en":"To be sure means to feel certain or confident.","zh":"確定是指感到肯定或有信心。"},{"en":"A driver checks the map twice to be sure of the route.","zh":"司機查看地圖兩次，以確定路線。"},{"en":"People who need to be sure may spend longer comparing options.","zh":"需要確定的人可能花更久比較選項。"},{"en":"This phrase shows the desire to remove doubt.","zh":"這個短語顯示消除懷疑的願望。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":13},{"front":"incur opportunity costs","meaning":"承受機會成本","examples":[{"en":"More options mean people incur more opportunity costs.","zh":"更多選項意味着人們承受更多機會成本。"},{"en":"To incur opportunity costs means to experience the lost benefits of rejected choices.","zh":"承受機會成本，是指經歷拒絕其他選擇所失去的好處。"},{"en":"Choosing an evening class may incur the opportunity cost of missing family dinner.","zh":"選擇夜校課程可能承受錯過家庭晚餐的機會成本。"},{"en":"The more alternatives people reject, the more opportunity costs they incur.","zh":"人們拒絕的替代選項越多，承受的機會成本越多。"},{"en":"This phrase describes the cost created by choosing one path over another.","zh":"這個短語描述選擇一條路而不是另一條路所產生的成本。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":13},{"front":"be likely to experience","meaning":"較有可能經歷","examples":[{"en":"People with many options are more likely to experience regret.","zh":"有很多選項的人較有可能經歷後悔。"},{"en":"To be likely to experience something means to have a high chance of going through it.","zh":"較有可能經歷某事，是指有較高機會遇到它。"},{"en":"Students who do not sleep before exams are likely to experience poor concentration.","zh":"考試前不睡覺的學生較有可能經歷專注力差。"},{"en":"More choices make people more likely to experience doubt afterward.","zh":"更多選擇令人之後較有可能經歷懷疑。"},{"en":"This phrase describes probability, not certainty.","zh":"這個短語描述可能性，而不是必然。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":13},{"front":"a classic demonstration of","meaning":"……的經典展示","examples":[{"en":"The theatre-ticket study is a classic demonstration of sunk costs.","zh":"戲票研究是沉沒成本的經典展示。"},{"en":"A classic demonstration of something is a well-known example that clearly shows it.","zh":"某事的經典展示，是指清楚展示它的著名例子。"},{"en":"A falling apple is often used as a classic demonstration of gravity.","zh":"掉下的蘋果常被用作重力的經典展示。"},{"en":"A good demonstration makes an abstract idea easier to understand.","zh":"好的展示會令抽象概念更容易理解。"},{"en":"This phrase introduces an example that strongly illustrates a concept.","zh":"這個短語引入能強烈說明概念的例子。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":13},{"front":"the power of sunk costs","meaning":"沉沒成本的力量","examples":[{"en":"The study showed the power of sunk costs in decision-making.","zh":"研究顯示沉沒成本在決策中的力量。"},{"en":"The power of sunk costs means the strong influence past spending has on later choices.","zh":"沉沒成本的力量，是指過去花費對後來選擇的強大影響。"},{"en":"People may keep watching a boring film because they paid for the ticket.","zh":"人們可能因已買票而繼續看一部沉悶電影。"},{"en":"Sunk costs can push people to continue even when quitting would be wiser.","zh":"沉沒成本可以推動人們繼續，即使放棄會更明智。"},{"en":"This phrase shows that past costs can control present behaviour.","zh":"這個短語顯示過去成本可以控制現在行為。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":13},{"front":"sunk costs","meaning":"沉沒成本","examples":[{"en":"Sunk costs can influence whether people use what they have paid for.","zh":"沉沒成本會影響人們是否使用已付費的東西。"},{"en":"Sunk costs are money, time or effort already spent and impossible to recover.","zh":"沉沒成本是已花出且無法收回的金錢、時間或努力。"},{"en":"A gym membership fee becomes a sunk cost after it has been paid.","zh":"健身會籍費付款後就成為沉沒成本。"},{"en":"People may keep using something unpleasant because they do not want the sunk cost to feel wasted.","zh":"人們可能繼續使用不愉快的東西，因為不想沉沒成本感覺被浪費。"},{"en":"This concept explains why past spending affects future choices.","zh":"這個概念解釋為何過去花費會影響未來選擇。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":13},{"front":"season subscriptions","meaning":"季票訂閱","examples":[{"en":"People were offered season subscriptions to a local theatre company.","zh":"人們獲提供本地劇團的季票訂閱。"},{"en":"Season subscriptions are tickets or memberships covering a whole season of events.","zh":"季票訂閱是涵蓋整個演出季或賽季的門票或會籍。"},{"en":"A football fan may buy a season subscription to watch every home game.","zh":"足球迷可能購買季票訂閱，以觀看每場主場比賽。"},{"en":"Paying for a season subscription can make people feel they should attend more often.","zh":"支付季票訂閱費會令人覺得自己應該更常出席。"},{"en":"This phrase refers to buying access to several events in advance.","zh":"這個短語指預先購買多場活動的入場權。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":13},{"front":"local theatre company","meaning":"本地劇團","examples":[{"en":"The study involved tickets to a local theatre company.","zh":"這項研究涉及本地劇團的門票。"},{"en":"A local theatre company is a nearby group that produces stage performances.","zh":"本地劇團是在附近製作舞台演出的團體。"},{"en":"A community may support a local theatre company by buying tickets or volunteering.","zh":"社區可以透過買票或做義工支持本地劇團。"},{"en":"Local theatre companies often depend on regular audiences to survive.","zh":"本地劇團通常依靠固定觀眾維持營運。"},{"en":"This phrase gives the real setting for the sunk-cost study.","zh":"這個短語給出沉沒成本研究的真實場景。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":14},{"front":"at full price","meaning":"以正價","examples":[{"en":"Some people were offered the theatre tickets at full price.","zh":"有些人獲提供以正價購買戲票。"},{"en":"At full price means paying the normal price without any discount.","zh":"以正價，是指支付沒有任何折扣的正常價格。"},{"en":"A customer who buys a jacket before the sale pays at full price.","zh":"在減價前買外套的顧客就是以正價購買。"},{"en":"Paying full price can make people feel a stronger need to use what they bought.","zh":"以正價付款會令人更強烈覺得需要使用已買的東西。"},{"en":"This phrase contrasts with buying something at a discount.","zh":"這個短語與以折扣價購買形成對比。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":14},{"front":"at a discount","meaning":"以折扣價","examples":[{"en":"Others were offered the tickets at a discount.","zh":"其他人獲提供以折扣價購買門票。"},{"en":"At a discount means at a reduced price.","zh":"以折扣價，是指以降低了的價格。"},{"en":"Students often buy museum tickets at a discount.","zh":"學生常以折扣價購買博物館門票。"},{"en":"If people pay at a discount, they may feel less regret about not using the item.","zh":"如果人們以折扣價付款，不使用該物品時可能較少後悔。"},{"en":"This phrase describes a lower-than-normal price.","zh":"這個短語描述低於正常價格的價錢。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":14},{"front":"keep track of","meaning":"記錄；追蹤","examples":[{"en":"The researchers kept track of how often people attended the plays.","zh":"研究人員記錄人們觀看戲劇演出的頻率。"},{"en":"To keep track of something means to record or monitor it over time.","zh":"記錄或追蹤某事，是指隨時間記下或監察它。"},{"en":"A student may keep track of vocabulary learned each week.","zh":"學生可能記錄每星期學到的詞彙。"},{"en":"Keeping track of behaviour helps researchers see patterns clearly.","zh":"追蹤行為幫助研究人員清楚看見模式。"},{"en":"This phrase is useful when information is followed repeatedly.","zh":"當資料被反覆跟進時，這個短語很有用。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":14},{"front":"ticket purchasers","meaning":"購票者","examples":[{"en":"The researchers observed how often ticket purchasers used their tickets.","zh":"研究人員觀察購票者使用門票的頻率。"},{"en":"Ticket purchasers are people who buy tickets.","zh":"購票者是指買票的人。"},{"en":"Ticket purchasers may receive a confirmation email after paying online.","zh":"購票者網上付款後可能收到確認電郵。"},{"en":"Observing ticket purchasers can show whether price affects attendance.","zh":"觀察購票者可以顯示價格是否影響出席率。"},{"en":"This phrase identifies the people who bought the theatre subscriptions.","zh":"這個短語指出購買劇場季票的人。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":14},{"front":"attend the plays","meaning":"觀看戲劇演出","examples":[{"en":"Full-price payers were more likely to attend the plays.","zh":"支付正價的人較可能觀看戲劇演出。"},{"en":"To attend the plays means to go and watch the theatre performances.","zh":"觀看戲劇演出，是指去看舞台劇表演。"},{"en":"A student may attend the school play to support classmates.","zh":"學生可能觀看學校戲劇演出來支持同學。"},{"en":"People who paid more may attend the plays more often to avoid feeling wasteful.","zh":"支付較多的人可能更常觀看演出，以避免覺得浪費。"},{"en":"This phrase describes actual use of the purchased tickets.","zh":"這個短語描述已購門票的實際使用。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":14},{"front":"over the course of","meaning":"在……期間","examples":[{"en":"The researchers followed attendance over the course of the season.","zh":"研究人員在整個演出季期間跟進出席情況。"},{"en":"Over the course of means during the whole period of time.","zh":"在……期間，是指在整段時間之中。"},{"en":"Over the course of a year, a student’s writing can improve greatly.","zh":"在一年期間，學生的寫作可以大幅進步。"},{"en":"Tracking behaviour over the course of a season shows long-term patterns.","zh":"在整個季節期間追蹤行為，可以顯示長期模式。"},{"en":"This phrase is used for changes or observations across a period.","zh":"這個短語用於跨一段時間的變化或觀察。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":14},{"front":"full-price payers","meaning":"支付正價的人","examples":[{"en":"Full-price payers were more likely to show up at performances.","zh":"支付正價的人較可能出席演出。"},{"en":"Full-price payers are people who paid the normal price without a discount.","zh":"支付正價的人，是指沒有折扣、支付正常價格的人。"},{"en":"Full-price payers may feel stronger pressure to use what they bought.","zh":"支付正價的人可能更強烈覺得要使用自己買的東西。"},{"en":"In the study, full-price payers attended more because not going felt like a bigger loss.","zh":"在研究中，支付正價的人出席更多，因為不去感覺像更大損失。"},{"en":"This phrase identifies the group that paid more.","zh":"這個短語指出支付較多的一組人。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":14},{"front":"discount payers","meaning":"支付折扣價的人","examples":[{"en":"Discount payers attended fewer performances than full-price payers.","zh":"支付折扣價的人出席演出次數少於支付正價的人。"},{"en":"Discount payers are people who bought something at a reduced price.","zh":"支付折扣價的人，是指以降低價格購買東西的人。"},{"en":"Discount payers may feel less pressure to use a service because they spent less.","zh":"支付折扣價的人因花費較少，可能較少感到使用服務的壓力。"},{"en":"In the theatre study, paying less reduced the emotional cost of missing shows.","zh":"在戲劇研究中，支付較少降低了錯過演出的情緒成本。"},{"en":"This phrase identifies the lower-price group.","zh":"這個短語指出較低價格的一組人。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":14},{"front":"show up at performances","meaning":"出席演出","examples":[{"en":"Full-price payers were more likely to show up at performances.","zh":"支付正價的人較可能出席演出。"},{"en":"To show up at performances means to attend the events in person.","zh":"出席演出，是指親身到場觀看活動。"},{"en":"Parents may show up at performances to support their children.","zh":"父母可能出席演出來支持孩子。"},{"en":"People are more likely to show up when missing the event would feel wasteful.","zh":"當錯過活動會感覺浪費時，人們較可能出席。"},{"en":"This phrase focuses on actual attendance, not just buying tickets.","zh":"這個短語聚焦實際出席，而不只是買票。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":14},{"front":"the reason for this","meaning":"這樣做的原因","examples":[{"en":"The reason for this was linked to regret and loss.","zh":"這樣做的原因與後悔和損失有關。"},{"en":"The reason for this means the explanation for the situation just mentioned.","zh":"這樣做的原因，是指剛提到情況的解釋。"},{"en":"The reason for this delay may be heavy traffic near the station.","zh":"這次延誤的原因可能是車站附近交通繁忙。"},{"en":"This phrase points readers toward the cause behind a result.","zh":"這個短語把讀者引向結果背後的原因。"},{"en":"It is useful when explaining why a pattern happened.","zh":"它適合用來解釋某種模式為何出現。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":14},{"front":"investigators argued","meaning":"研究人員認為","examples":[{"en":"The investigators argued that full-price payers feared regret more.","zh":"研究人員認為支付正價的人更害怕後悔。"},{"en":"Investigators argued means researchers claimed or reasoned that something was true.","zh":"研究人員認為，是指研究者提出或推論某事為真。"},{"en":"Investigators argued that tired workers made more mistakes after long shifts.","zh":"研究人員認為，疲倦工人在長時間輪班後犯更多錯。"},{"en":"This phrase introduces an interpretation, not just a raw observation.","zh":"這個短語引入解釋，而不只是原始觀察。"},{"en":"It shows what the researchers thought the evidence meant.","zh":"它顯示研究人員認為證據代表甚麼。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":15},{"front":"experience more regret","meaning":"經歷更多後悔","examples":[{"en":"Full-price payers would experience more regret if they did not use the tickets.","zh":"如果不使用門票，支付正價的人會經歷更多後悔。"},{"en":"To experience more regret means to feel a stronger sense of wishing one had acted differently.","zh":"經歷更多後悔，是指更強烈地希望自己當初做法不同。"},{"en":"A buyer may experience more regret after wasting an expensive product than a cheap one.","zh":"買家浪費昂貴產品後，可能比浪費便宜產品經歷更多後悔。"},{"en":"The more money people spend, the more regret they may feel if they do not use the purchase.","zh":"人們花的錢越多，如果不使用所購物品，就可能感到更多後悔。"},{"en":"This phrase links cost with emotional pain.","zh":"這個短語把成本與情緒痛苦連接起來。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":15},{"front":"not using the tickets","meaning":"不使用門票","examples":[{"en":"Not using the tickets would feel like a loss.","zh":"不使用門票會感覺像損失。"},{"en":"Not using the tickets means buying tickets but failing to attend the events.","zh":"不使用門票，是指買了票但沒有出席活動。"},{"en":"A student may feel bad about not using concert tickets bought weeks earlier.","zh":"學生可能因不使用幾星期前買的演唱會門票而感到不好。"},{"en":"Not using paid tickets can feel wasteful because the money is already gone.","zh":"不使用已付費門票會感覺浪費，因為錢已經花了。"},{"en":"This phrase illustrates how sunk costs affect behaviour.","zh":"這個短語說明沉沒成本如何影響行為。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":15},{"front":"constitute a bigger loss","meaning":"構成更大損失","examples":[{"en":"Not using costly tickets would constitute a bigger loss.","zh":"不使用昂貴門票會構成更大損失。"},{"en":"To constitute a bigger loss means to count as or create a larger loss.","zh":"構成更大損失，是指算作或造成更大的損失。"},{"en":"Missing an expensive flight would constitute a bigger loss than missing a cheap bus ride.","zh":"錯過昂貴航班比錯過便宜巴士車程構成更大損失。"},{"en":"Higher past spending can make non-use feel like a bigger loss.","zh":"過去花費越高，不使用就越感覺構成更大損失。"},{"en":"This phrase explains why full-price payers attended more often.","zh":"這個短語解釋為何支付正價的人更常出席。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":15},{"front":"increase our sense of happiness","meaning":"增加我們的幸福感","examples":[{"en":"We can increase our sense of happiness by limiting options.","zh":"我們可以透過限制選項增加幸福感。"},{"en":"To increase our sense of happiness means to make us feel more satisfied and content.","zh":"增加我們的幸福感，是指令我們感到更滿意和知足。"},{"en":"Planning fewer weekend tasks can increase our sense of happiness by reducing pressure.","zh":"減少週末任務安排可以透過減少壓力增加幸福感。"},{"en":"Limiting choices can increase happiness because decisions become easier.","zh":"限制選擇可以增加快樂，因為決定變得更容易。"},{"en":"This phrase describes improving emotional well-being.","zh":"這個短語描述改善情緒幸福狀態。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":15},{"front":"restrict our options","meaning":"限制我們的選項","examples":[{"en":"People can restrict their options when a decision is not crucial.","zh":"當決定並非關鍵時，人們可以限制自己的選項。"},{"en":"To restrict our options means to deliberately limit the number of choices we consider.","zh":"限制我們的選項，是指有意限制所考慮選擇的數量。"},{"en":"A shopper may restrict options by visiting only two stores.","zh":"顧客可能透過只逛兩間店來限制選項。"},{"en":"Restricting options can prevent simple decisions from becoming exhausting.","zh":"限制選項可以防止簡單決定變得令人疲憊。"},{"en":"This phrase describes setting limits to make choosing easier.","zh":"這個短語描述設下限制以令選擇更容易。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":15},{"front":"not crucial","meaning":"並非關鍵的","examples":[{"en":"It can help to limit options when the decision is not crucial.","zh":"當決定並非關鍵時，限制選項會有幫助。"},{"en":"Not crucial means not extremely important or not likely to have serious consequences.","zh":"並非關鍵的，是指不是極重要或不太可能有嚴重後果。"},{"en":"Choosing a pen colour is usually not crucial.","zh":"選擇筆的顏色通常並非關鍵。"},{"en":"When a decision is not crucial, spending hours on it may waste energy.","zh":"當決定並非關鍵，在上面花幾小時可能浪費精力。"},{"en":"This phrase helps decide when a good-enough choice is acceptable.","zh":"這個短語幫助判斷何時「夠好」的選擇可以接受。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":15},{"front":"make a rule to","meaning":"制定規則去","examples":[{"en":"People can make a rule to visit no more than two stores.","zh":"人們可以制定規則，只逛不多於兩間店。"},{"en":"To make a rule to do something means to set a personal limit or instruction.","zh":"制定規則去做某事，是指設下個人限制或指示。"},{"en":"A student may make a rule to check social media only after homework.","zh":"學生可能制定規則，只有完成功課後才查看社交媒體。"},{"en":"Rules reduce decision fatigue because the choice has already been limited.","zh":"規則減少決策疲勞，因為選擇已被限制。"},{"en":"This phrase describes creating a simple guide for behaviour.","zh":"這個短語描述為行為創造簡單指引。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":15},{"front":"no more than","meaning":"不多於","examples":[{"en":"One rule is to visit no more than two stores.","zh":"一條規則是逛不多於兩間店。"},{"en":"No more than means not exceeding a stated number or amount.","zh":"不多於，是指不超過所述數字或數量。"},{"en":"Students should write no more than 150 words if the instruction sets that limit.","zh":"如果指示設定限制，學生應寫不多於 150 字。"},{"en":"A clear limit can stop people from comparing endlessly.","zh":"清楚限制可以阻止人們無止境地比較。"},{"en":"This phrase is useful for setting maximum boundaries.","zh":"這個短語適合用來設定最高界限。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":15},{"front":"shopping for clothing","meaning":"購買衣服","examples":[{"en":"People can limit their options when shopping for clothing.","zh":"人們購買衣服時可以限制選項。"},{"en":"Shopping for clothing means buying clothes such as shirts, trousers or jackets.","zh":"購買衣服，是指買恤衫、褲子或外套等衣物。"},{"en":"A shopper may choose only two stores when shopping for clothing.","zh":"顧客購買衣服時，可能只選兩間店。"},{"en":"Clothing choices can become tiring because colours, sizes and styles vary widely.","zh":"衣服選擇可能變得疲憊，因為顏色、尺碼和款式差異很大。"},{"en":"This phrase gives a familiar example of everyday decision-making.","zh":"這個短語提供日常決策的熟悉例子。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":15},{"front":"look at the following statements","meaning":"查看以下陳述","examples":[{"en":"Students look at the following statements before matching them with categories.","zh":"學生在把陳述與類別配對前查看以下陳述。"},{"en":"Look at the following statements means read the sentences that come next.","zh":"查看以下陳述，是指閱讀接下來的句子。"},{"en":"In a reading test, students look at the following statements to identify key words.","zh":"在閱讀測驗中，學生查看以下陳述以找出關鍵詞。"},{"en":"This instruction tells students what to examine before answering.","zh":"這項指示告訴學生答題前要檢查甚麼。"},{"en":"It is common in matching and True or False tasks.","zh":"它常見於配對題和判斷題。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":15},{"front":"list of categories","meaning":"類別列表","examples":[{"en":"The question provides a list of categories.","zh":"題目提供一個類別列表。"},{"en":"A list of categories is a set of groups used to classify information.","zh":"類別列表是一組用來分類資料的組別。"},{"en":"A worksheet may give a list of categories such as food, transport and health.","zh":"工作紙可能給出食物、交通和健康等類別列表。"},{"en":"Categories help students organise answers instead of treating all details the same.","zh":"類別幫助學生組織答案，而不是把所有細節都視為一樣。"},{"en":"This phrase is common in matching questions.","zh":"這個短語常見於配對題。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":16},{"front":"match each description with","meaning":"把每項描述與……配對","examples":[{"en":"Students match each description with the correct category.","zh":"學生把每項描述與正確類別配對。"},{"en":"To match each description with something means to connect each statement to the right option.","zh":"把每項描述與某物配對，是指把每句陳述連接到正確選項。"},{"en":"Students may match each definition with the correct vocabulary word.","zh":"學生可能把每個定義與正確詞彙配對。"},{"en":"Matching requires understanding meaning, not just finding repeated words.","zh":"配對需要理解意思，而不只是找重複字。"},{"en":"This phrase describes a common reading-test task.","zh":"這個短語描述常見閱讀測驗任務。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":16},{"front":"the correct category","meaning":"正確類別","examples":[{"en":"Each description must be matched with the correct category.","zh":"每項描述必須與正確類別配對。"},{"en":"The correct category is the group that best fits the information.","zh":"正確類別是最符合資料的組別。"},{"en":"A sentence about buses belongs in the correct category of transport.","zh":"關於巴士的句子屬於交通這個正確類別。"},{"en":"Choosing the wrong category shows misunderstanding of the description.","zh":"選錯類別顯示對描述理解錯誤。"},{"en":"This phrase stresses accuracy in classification.","zh":"這個短語強調分類的準確性。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":16},{"front":"rated on","meaning":"按……評分","examples":[{"en":"People are rated on the Maximization Scale for decision-making.","zh":"人們按決策最大化傾向量表評分。"},{"en":"To be rated on a scale means to receive a score according to that measure.","zh":"按某量表評分，是指根據該測量方法得到分數。"},{"en":"Hotels are often rated on cleanliness, service and location.","zh":"酒店常按清潔、服務和位置評分。"},{"en":"Ratings help compare people or services using the same standard.","zh":"評分幫助使用同一標準比較人或服務。"},{"en":"This phrase describes how performance or tendency is measured.","zh":"這個短語描述表現或傾向如何被衡量。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":16},{"front":"do not take much time before","meaning":"在……之前不花太多時間","examples":[{"en":"Some people do not take much time before making a decision.","zh":"有些人在作決定之前不花太多時間。"},{"en":"Do not take much time before means act quickly without a long delay.","zh":"在……之前不花太多時間，是指沒有長時間拖延就行動。"},{"en":"A satisficer may not take much time before choosing a good-enough lunch.","zh":"滿意即止者在選擇夠好的午餐之前，可能不花太多時間。"},{"en":"Taking little time can reduce stress when the decision is minor.","zh":"當決定很小時，花較少時間可以減少壓力。"},{"en":"This phrase describes quick decision-making.","zh":"這個短語描述快速決策。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":16},{"front":"be likely to regret","meaning":"很可能後悔","examples":[{"en":"Some people are likely to regret their choice in the future.","zh":"有些人將來很可能後悔自己的選擇。"},{"en":"To be likely to regret something means to have a strong chance of feeling sorry later.","zh":"很可能後悔某事，是指之後有很大機會感到懊悔。"},{"en":"A buyer may be likely to regret a rushed purchase.","zh":"買家很可能後悔倉促購買。"},{"en":"People are more likely to regret choices when they keep comparing alternatives.","zh":"當人們不斷比較替代選項時，更可能後悔選擇。"},{"en":"This phrase predicts a possible future feeling.","zh":"這個短語預測一種可能的未來感受。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":16},{"front":"in the future","meaning":"在將來","examples":[{"en":"People may regret their choice in the future.","zh":"人們可能在將來後悔自己的選擇。"},{"en":"In the future means at a later time, not now.","zh":"在將來，是指之後某個時間，而不是現在。"},{"en":"Students choose subjects now that may affect their careers in the future.","zh":"學生現在選擇科目，可能影響他們將來的職業。"},{"en":"Thinking too much about future regret can make present decisions harder.","zh":"過度想着將來後悔，會令現在的決定更困難。"},{"en":"This phrase points forward in time.","zh":"這個短語指向未來時間。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":16},{"front":"highest-priced option","meaning":"最高價的選項","examples":[{"en":"The question mentions people choosing the highest-priced option in a range.","zh":"題目提到人們在一系列選項中選擇最高價的選項。"},{"en":"The highest-priced option is the choice that costs the most among several options.","zh":"最高價的選項，是指幾個選項中價格最高的一個。"},{"en":"A traveller may avoid the highest-priced option when booking a hotel.","zh":"旅客訂酒店時可能避免最高價的選項。"},{"en":"People do not always choose the highest-priced option just because it is expensive.","zh":"人們不一定只因昂貴就選擇最高價的選項。"},{"en":"This phrase is useful when comparing prices within a set.","zh":"這個短語適合用於比較一組選項中的價格。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":16},{"front":"in a range","meaning":"在一系列選項之中","examples":[{"en":"People may choose the highest-priced option in a range.","zh":"人們可能在一系列選項之中選擇最高價的選項。"},{"en":"In a range means within a set of choices, values or prices.","zh":"在一系列選項之中，是指在一組選擇、數值或價格之內。"},{"en":"A shop may sell bags in a range from cheap to luxury.","zh":"商店可能出售一系列從便宜到奢華的袋。"},{"en":"Looking at options in a range helps people compare low, middle and high choices.","zh":"查看一系列選項有助人比較低、中、高選擇。"},{"en":"This phrase shows that something belongs inside a wider set.","zh":"這個短語顯示某物屬於較大集合之內。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":16},{"front":"agree with the information given","meaning":"與文中資料一致","examples":[{"en":"Students decide whether statements agree with the information given in the passage.","zh":"學生判斷陳述是否與文中資料一致。"},{"en":"To agree with the information given means to match what the text states.","zh":"與文中資料一致，是指符合文本所陳述的內容。"},{"en":"If the passage says choices increased, a matching statement agrees with the information given.","zh":"如果篇章說選擇增加，符合的陳述就與文中資料一致。"},{"en":"Students should not use personal opinion to answer this question type.","zh":"學生不應用個人意見回答這類題目。"},{"en":"This phrase is common in True, False and Not Given tasks.","zh":"這個短語常見於 True、False 和 Not Given 題。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":16},{"front":"contradicts the information","meaning":"與文中資料相矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與篇章中的資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the passage says.","zh":"與資料相矛盾，是指說出與篇章內容相反的意思。"},{"en":"If the text says prices fell, a statement saying prices rose contradicts the information.","zh":"如果文本說價格下跌，而陳述說價格上升，就與資料相矛盾。"},{"en":"Contradiction means the answer is false, not merely missing.","zh":"矛盾表示答案是錯，而不是單純沒有提及。"},{"en":"This phrase helps students separate False from Not Given.","zh":"這個短語幫助學生區分 False 和 Not Given。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":16},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"Students choose NOT GIVEN when there is no information on this.","zh":"當沒有相關資料時，學生選擇 NOT GIVEN。"},{"en":"No information on this means the passage does not say whether the point is true or false.","zh":"沒有相關資料，是指篇章沒有說明該點是真或假。"},{"en":"If the passage discusses shoppers but not their ages, there is no information on this detail.","zh":"如果篇章討論購物者但沒有提及年齡，這個細節就沒有相關資料。"},{"en":"Students should not guess when there is no information in the text.","zh":"當文本沒有資料時，學生不應猜測。"},{"en":"This phrase explains the meaning of NOT GIVEN.","zh":"這個短語解釋 NOT GIVEN 的意思。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":17},{"front":"in today’s world","meaning":"在現今世界","examples":[{"en":"In today’s world, people face more choices than before.","zh":"在現今世界，人們面對比以前更多的選擇。"},{"en":"In today’s world means in modern society or the present time.","zh":"在現今世界，是指在現代社會或當前時代。"},{"en":"In today’s world, many workers need digital skills.","zh":"在現今世界，許多工人需要數碼技能。"},{"en":"This phrase connects a topic with current life and modern conditions.","zh":"這個短語把主題與當前生活和現代條件連接起來。"},{"en":"It is often used to introduce broad social changes.","zh":"它常用來引入廣泛社會變化。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":17},{"front":"as society becomes wealthier","meaning":"隨着社會變得更富裕","examples":[{"en":"The statement discusses whether people become happier as society becomes wealthier.","zh":"該陳述討論隨着社會變得更富裕，人們是否變得更快樂。"},{"en":"As society becomes wealthier means while a society gains more money and resources.","zh":"隨着社會變得更富裕，是指當社會獲得更多金錢和資源時。"},{"en":"As society becomes wealthier, people may have more products and services to choose from.","zh":"隨着社會變得更富裕，人們可能有更多產品和服務可選。"},{"en":"Greater wealth can increase choices, but not always increase happiness.","zh":"更大財富可以增加選擇，但不一定增加快樂。"},{"en":"This phrase connects economic growth with changes in life.","zh":"這個短語把經濟增長與生活變化連接起來。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":17},{"front":"tend to react more to","meaning":"傾向對……反應更大","examples":[{"en":"People tend to react more to losses than to gains.","zh":"人們傾向對損失的反應大於對收益的反應。"},{"en":"Tend to react more to something means usually respond more strongly to it.","zh":"傾向對某事反應更大，是指通常對它有更強回應。"},{"en":"Children may react more to criticism than to praise.","zh":"孩子可能對批評的反應大於對稱讚的反應。"},{"en":"People react more to losses because losing feels painful and memorable.","zh":"人們對損失反應更大，因為失去令人痛苦且難忘。"},{"en":"This phrase compares emotional strength across two types of events.","zh":"這個短語比較兩類事件的情緒強度。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":17},{"front":"losses than gains","meaning":"損失多於收益","examples":[{"en":"The passage says people respond more strongly to losses than gains.","zh":"篇章說人們對損失的反應比對收益更強烈。"},{"en":"Losses than gains is used when losses are compared with benefits or positive results.","zh":"損失多於收益用於把損失與好處或正面結果比較。"},{"en":"Losing a favourite jacket may affect someone more than buying a new one pleases them.","zh":"失去最喜歡的外套，可能比買新外套帶來的快樂影響更大。"},{"en":"This comparison helps explain why rejected options feel costly.","zh":"這種比較幫助解釋為何被拒絕的選項感覺有成本。"},{"en":"The phrase points to the stronger emotional impact of loss.","zh":"這個短語指出損失更強的情緒影響。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":17},{"front":"act differently","meaning":"表現不同","examples":[{"en":"The question asks whether females and males acted differently in the study.","zh":"題目問女性和男性在研究中是否表現不同。"},{"en":"To act differently means to behave in a different way.","zh":"表現不同，是指以不同方式行動或反應。"},{"en":"Students may act differently in exams than they do in ordinary lessons.","zh":"學生在考試中的表現可能與平常課堂不同。"},{"en":"If two groups act differently, researchers may compare their results separately.","zh":"如果兩組人表現不同，研究人員可能分開比較結果。"},{"en":"This phrase focuses on observable behaviour.","zh":"這個短語聚焦可觀察的行為。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":17},{"front":"study of decision-making","meaning":"決策研究","examples":[{"en":"The question refers to a study of decision-making.","zh":"題目指一項決策研究。"},{"en":"A study of decision-making examines how people choose and respond to choices.","zh":"決策研究考察人們如何選擇和回應選擇。"},{"en":"A study of decision-making may ask participants to buy tickets or compare products.","zh":"決策研究可能要求參與者購買門票或比較產品。"},{"en":"Such studies reveal patterns that people may not notice in daily life.","zh":"這類研究揭示人們在日常生活中未必注意到的模式。"},{"en":"This phrase identifies research about the process of choosing.","zh":"這個短語指出關於選擇過程的研究。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":17},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter from the options.","zh":"學生從選項中選出正確字母。"},{"en":"To choose the correct letter means to select the letter that matches the right answer.","zh":"選出正確字母，是指選擇與正確答案相符的字母。"},{"en":"In multiple-choice questions, students may choose A, B, C or D.","zh":"在選擇題中，學生可能選 A、B、C 或 D。"},{"en":"Choosing the correct letter requires understanding the passage, not guessing quickly.","zh":"選出正確字母需要理解篇章，而不是快速猜測。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":17},{"front":"be intended to","meaning":"旨在","examples":[{"en":"The Maximization Scale is intended to measure decision-making style.","zh":"最大化傾向量表旨在衡量決策風格。"},{"en":"Be intended to means be designed or meant to do something.","zh":"旨在是指被設計或用來做某事。"},{"en":"A school notice is intended to inform parents about a change in timetable.","zh":"學校通知旨在告知家長時間表變動。"},{"en":"A tool may be intended to measure one thing, not solve every problem.","zh":"一個工具可能旨在衡量一件事，而不是解決所有問題。"},{"en":"This phrase explains purpose.","zh":"這個短語解釋目的。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":17},{"front":"measure people’s happiness","meaning":"衡量人們的快樂程度","examples":[{"en":"Some studies measure people’s happiness when they have more choices.","zh":"有些研究衡量人們在有更多選擇時的快樂程度。"},{"en":"To measure people’s happiness means to assess how happy or satisfied people feel.","zh":"衡量人們的快樂程度，是指評估人們感到多快樂或滿意。"},{"en":"Researchers may measure happiness through questionnaires about mood and life satisfaction.","zh":"研究人員可能透過關於心情和生活滿意度的問卷衡量快樂。"},{"en":"Measuring happiness helps test whether more choice really improves life.","zh":"衡量快樂有助測試更多選擇是否真的改善生活。"},{"en":"This phrase describes turning feelings into research data.","zh":"這個短語描述把感受轉化為研究資料。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":17},{"front":"approach making choices","meaning":"處理選擇的方式","examples":[{"en":"The scale measures how people are likely to approach making choices.","zh":"這個量表衡量人們可能如何處理選擇。"},{"en":"To approach making choices means to handle or think about decisions in a certain way.","zh":"處理選擇的方式，是指以某種方式應對或思考決定。"},{"en":"Some people approach making choices by comparing everything carefully.","zh":"有些人處理選擇的方式是仔細比較一切。"},{"en":"Others approach choices by setting a standard and stopping once it is met.","zh":"另一些人則設定標準，一達標就停止。"},{"en":"This phrase describes decision-making style.","zh":"這個短語描述決策風格。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":17},{"front":"make better choices","meaning":"作出更好的選擇","examples":[{"en":"Some tools may help people make better choices.","zh":"有些工具可能幫助人們作出更好的選擇。"},{"en":"To make better choices means to choose options that suit needs more successfully.","zh":"作出更好的選擇，是指選擇更成功地符合需要的選項。"},{"en":"Reading clear reviews can help shoppers make better choices.","zh":"閱讀清楚評論可以幫助購物者作出更好的選擇。"},{"en":"Better choices often come from knowing priorities, not just having more options.","zh":"更好的選擇通常來自知道優次，而不只是有更多選項。"},{"en":"This phrase focuses on improving the quality of decisions.","zh":"這個短語聚焦改善決定的質素。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":18},{"front":"reduce the time spent","meaning":"減少花在……上的時間","examples":[{"en":"The option mentions reducing the time spent making purchases.","zh":"該選項提到減少花在購買上的時間。"},{"en":"To reduce the time spent means to use less time on an activity.","zh":"減少花在某活動上的時間，是指用較少時間做該活動。"},{"en":"A shopping list can reduce the time spent in a supermarket.","zh":"購物清單可以減少在超市花的時間。"},{"en":"Reducing decision time can lower stress when choices are not important.","zh":"當選擇不重要時，減少決策時間可以降低壓力。"},{"en":"This phrase describes making an activity shorter or more efficient.","zh":"這個短語描述令活動更短或更有效率。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":18},{"front":"the result of","meaning":"……的結果","examples":[{"en":"The question asks about the result of more choices.","zh":"題目問更多選擇的結果。"},{"en":"The result of something means what happens because of it.","zh":"某事的結果，是指因它而發生的事。"},{"en":"Tiredness may be the result of sleeping too little.","zh":"疲倦可能是睡眠太少的結果。"},{"en":"The result of too many choices may be regret rather than happiness.","zh":"太多選擇的結果可能是後悔，而不是快樂。"},{"en":"This phrase connects a cause with an outcome.","zh":"這個短語把原因與結果連接起來。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":18},{"front":"make choices more easily","meaning":"更容易作出選擇","examples":[{"en":"More options do not always help people make choices more easily.","zh":"更多選項不一定幫助人們更容易作出選擇。"},{"en":"To make choices more easily means to decide with less effort, time or stress.","zh":"更容易作出選擇，是指用較少努力、時間或壓力作決定。"},{"en":"A short menu can help customers make choices more easily.","zh":"簡短餐牌可以幫助顧客更容易作出選擇。"},{"en":"Too many similar options can make choices harder, not easier.","zh":"太多相似選項會令選擇更困難，而不是更容易。"},{"en":"This phrase focuses on how difficult the decision process feels.","zh":"這個短語聚焦決策過程感覺有多難。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":18},{"front":"make wise choices","meaning":"作出明智選擇","examples":[{"en":"Satisficers may be quicker to make wise choices.","zh":"滿意即止者可能更快作出明智選擇。"},{"en":"To make wise choices means to choose sensibly and with good judgement.","zh":"作出明智選擇，是指以理性和良好判斷來選擇。"},{"en":"A student makes a wise choice by sleeping before an exam instead of studying all night.","zh":"學生考試前睡覺而不是通宵溫習，就是作出明智選擇。"},{"en":"Wise choices often balance quality, time, cost and emotional peace.","zh":"明智選擇通常平衡質素、時間、成本和情緒平靜。"},{"en":"This phrase values good judgement more than endless comparison.","zh":"這個短語重視良好判斷，而不是無盡比較。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":18},{"front":"theatre tickets","meaning":"戲票","examples":[{"en":"The example of theatre tickets illustrates the effect of sunk costs.","zh":"戲票的例子說明沉沒成本的影響。"},{"en":"Theatre tickets are tickets that allow people to attend stage performances.","zh":"戲票是讓人觀看舞台演出的門票。"},{"en":"A person who buys theatre tickets may feel they should go even when tired.","zh":"買了戲票的人即使疲倦，也可能覺得自己應該去。"},{"en":"The price of theatre tickets can affect how strongly people feel they must use them.","zh":"戲票價格會影響人們覺得必須使用它的強度。"},{"en":"This example makes sunk costs easy to understand.","zh":"這個例子令沉沒成本容易理解。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":18},{"front":"prefer to spend more money","meaning":"較喜歡花更多錢","examples":[{"en":"The option suggests that people prefer to spend more money on tickets.","zh":"該選項暗示人們較喜歡在門票上花更多錢。"},{"en":"To prefer to spend more money means to choose paying a higher amount over a lower amount.","zh":"較喜歡花更多錢，是指選擇支付較高金額而不是較低金額。"},{"en":"Some customers prefer to spend more money on safer products.","zh":"有些顧客較喜歡在較安全產品上花更多錢。"},{"en":"In the theatre study, higher attendance did not simply mean people preferred spending more.","zh":"在戲劇研究中，較高出席率不只是表示人們喜歡花更多錢。"},{"en":"This phrase describes a preference for a costlier option.","zh":"這個短語描述對較昂貴選項的偏好。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":18},{"front":"higher-priced items","meaning":"價格較高的物品","examples":[{"en":"Higher-priced items may cause more regret if they are not used.","zh":"如果沒有使用，價格較高的物品可能引起更多後悔。"},{"en":"Higher-priced items are products or services that cost more than alternatives.","zh":"價格較高的物品，是指比替代選項更昂貴的產品或服務。"},{"en":"An expensive gym membership is a higher-priced item compared with a single class.","zh":"昂貴健身會籍相對於單堂課，是價格較高的物品。"},{"en":"Not using higher-priced items can feel like wasting more money.","zh":"不使用價格較高的物品會感覺像浪費更多錢。"},{"en":"This phrase connects price level with potential regret.","zh":"這個短語把價格水平與可能後悔連接起來。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":18},{"front":"cause more regret","meaning":"引起更多後悔","examples":[{"en":"Unused expensive items can cause more regret.","zh":"未使用的昂貴物品可以引起更多後悔。"},{"en":"To cause more regret means to create a stronger feeling of wishing things were different.","zh":"引起更多後悔，是指造成更強烈希望事情不同的感覺。"},{"en":"A wasted first-class ticket may cause more regret than a cheap bus ticket.","zh":"浪費頭等票可能比浪費便宜巴士票引起更多後悔。"},{"en":"Higher cost can cause more regret because the loss feels larger.","zh":"較高成本會引起更多後悔，因為損失感更大。"},{"en":"This phrase explains an emotional consequence of spending.","zh":"這個短語解釋花費帶來的情緒後果。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":18},{"front":"genuine theatre lovers","meaning":"真正熱愛戲劇的人","examples":[{"en":"The option refers to people who are genuine theatre lovers.","zh":"該選項指真正熱愛戲劇的人。"},{"en":"Genuine theatre lovers are people who truly enjoy stage performances.","zh":"真正熱愛戲劇的人，是指真心喜歡舞台演出的人。"},{"en":"Genuine theatre lovers may attend plays because they love acting, stories and live performance.","zh":"真正熱愛戲劇的人可能因喜歡演技、故事和現場表演而看戲。"},{"en":"In the study, attendance was linked to ticket price, not only love of theatre.","zh":"在研究中，出席與票價有關，而不只是熱愛戲劇。"},{"en":"This phrase describes real interest rather than forced attendance.","zh":"這個短語描述真正興趣，而不是被迫出席。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":18},{"front":"increase their happiness","meaning":"提高他們的快樂程度","examples":[{"en":"People can increase their happiness by limiting certain choices.","zh":"人們可以透過限制某些選擇提高他們的快樂程度。"},{"en":"To increase their happiness means to make them feel more satisfied or content.","zh":"提高他們的快樂程度，是指令他們感到更滿意或知足。"},{"en":"Families may increase their happiness by keeping weekends less crowded.","zh":"家庭可以透過讓週末較不擁擠來提高快樂程度。"},{"en":"Limiting low-stakes choices can increase happiness by reducing decision fatigue.","zh":"限制低風險選擇可以透過減少決策疲勞來提高快樂。"},{"en":"This phrase describes improving emotional well-being.","zh":"這個短語描述改善情緒幸福。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":18},{"front":"when making choices","meaning":"在作選擇時","examples":[{"en":"People may feel less regret when making choices with fewer options.","zh":"當選項較少時，人們在作選擇時可能較少後悔。"},{"en":"When making choices means during the process of deciding.","zh":"在作選擇時，是指在決定的過程中。"},{"en":"When making choices about food, a short menu can help customers decide faster.","zh":"在作食物選擇時，簡短餐牌可以幫助顧客更快決定。"},{"en":"People feel calmer when making choices if their priorities are clear.","zh":"如果優次清晰，人們在作選擇時會較平靜。"},{"en":"This phrase points to the decision process itself.","zh":"這個短語指向決策過程本身。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":19},{"front":"use less time","meaning":"用較少時間","examples":[{"en":"One option suggests that people can increase happiness by using less time.","zh":"一個選項暗示人們可以透過用較少時間提高快樂。"},{"en":"To use less time means to spend fewer minutes or hours on an activity.","zh":"用較少時間，是指在某活動上花較少分鐘或小時。"},{"en":"A shopper can use less time by making a list before going out.","zh":"顧客可以透過出門前列清單來用較少時間購物。"},{"en":"Using less time on minor decisions leaves more energy for important ones.","zh":"在小決定上用較少時間，可以留下更多精力處理重要決定。"},{"en":"This phrase focuses on time as a limited resource.","zh":"這個短語聚焦時間作為有限資源。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":19},{"front":"make more comparisons","meaning":"作更多比較","examples":[{"en":"Making more comparisons may make maximizers less satisfied.","zh":"作更多比較可能令追求最優者較不滿意。"},{"en":"To make more comparisons means to examine more similarities and differences between options.","zh":"作更多比較，是指檢查更多選項之間的相似和不同之處。"},{"en":"A buyer may make more comparisons by checking five websites before buying a camera.","zh":"買家購買相機前查看五個網站，就是作更多比較。"},{"en":"More comparisons can improve information but also increase doubt.","zh":"更多比較可以改善資訊，但也會增加懷疑。"},{"en":"This phrase describes the habit that often makes choices harder.","zh":"這個短語描述常令選擇更困難的習慣。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":19},{"front":"limit the number of choices","meaning":"限制選擇數量","examples":[{"en":"People can increase happiness by limiting the number of choices.","zh":"人們可以透過限制選擇數量來提高快樂。"},{"en":"To limit the number of choices means to reduce how many options are considered.","zh":"限制選擇數量，是指減少所考慮的選項數目。"},{"en":"A restaurant may limit the number of choices on a menu to help customers decide.","zh":"餐廳可能限制餐牌上的選擇數量，幫助顧客決定。"},{"en":"Fewer choices can reduce regret and speed up decisions.","zh":"較少選擇可以減少後悔並加快決定。"},{"en":"This phrase describes a practical strategy for easier decision-making.","zh":"這個短語描述令決策更容易的實用策略。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":19},{"front":"in certain situations","meaning":"在某些情況下","examples":[{"en":"Limiting choices can help in certain situations.","zh":"在某些情況下，限制選擇會有幫助。"},{"en":"In certain situations means in some specific cases, but not all cases.","zh":"在某些情況下，是指在某些具體個案中，但不是所有個案。"},{"en":"In certain situations, a strict rule can reduce stress.","zh":"在某些情況下，嚴格規則可以減少壓力。"},{"en":"Limiting options helps most when the decision is small or not crucial.","zh":"當決定較小或不關鍵時，限制選項最有幫助。"},{"en":"This phrase avoids making an overgeneral claim.","zh":"這個短語避免作出過度概括的說法。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":19},{"front":"the best title for","meaning":"……的最佳標題","examples":[{"en":"Students choose the best title for the reading passage.","zh":"學生選出閱讀篇章的最佳標題。"},{"en":"The best title for a passage is the title that most accurately expresses its main idea.","zh":"篇章的最佳標題，是最準確表達其主旨的標題。"},{"en":"A good title should cover the whole text, not just one paragraph.","zh":"好標題應涵蓋整篇文章，而不只是一段。"},{"en":"Choosing the best title requires understanding the passage’s central message.","zh":"選出最佳標題需要理解篇章的中心訊息。"},{"en":"This phrase is common in reading-comprehension questions.","zh":"這個短語常見於閱讀理解題。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":19},{"front":"reasons for","meaning":"……的原因","examples":[{"en":"One possible title refers to reasons for worse decision-making.","zh":"一個可能標題提到較差決策的原因。"},{"en":"Reasons for something are the causes or explanations behind it.","zh":"某事的原因，是指它背後的成因或解釋。"},{"en":"Teachers may discuss reasons for poor attendance in a class.","zh":"老師可能討論班級出席率差的原因。"},{"en":"Understanding reasons for a problem helps people design better solutions.","zh":"理解問題的原因有助人設計更好的解決方法。"},{"en":"This phrase introduces causes, not just results.","zh":"這個短語引入原因，而不只是結果。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":19},{"front":"worse decision-making","meaning":"較差的決策","examples":[{"en":"Too many choices may lead to worse decision-making.","zh":"太多選擇可能導致較差的決策。"},{"en":"Worse decision-making means choosing less effectively or with poorer judgement.","zh":"較差的決策，是指選擇較低效或判斷較差。"},{"en":"A tired student may show worse decision-making when planning revision.","zh":"疲倦學生規劃溫習時，可能表現出較差的決策。"},{"en":"Too many options can create worse decision-making by increasing confusion and regret.","zh":"太多選項會透過增加混亂和後悔造成較差決策。"},{"en":"This phrase describes a decline in the quality of choices.","zh":"這個短語描述選擇質素下降。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":19},{"front":"making choices in today’s world","meaning":"在現今世界作選擇","examples":[{"en":"The passage discusses making choices in today’s world.","zh":"篇章討論在現今世界作選擇。"},{"en":"Making choices in today’s world means deciding among many modern options in daily life.","zh":"在現今世界作選擇，是指在日常生活中從許多現代選項中決定。"},{"en":"People make choices in today’s world when selecting schools, phones, jobs and insurance plans.","zh":"人們選擇學校、手機、工作和保險計劃時，就是在現今世界作選擇。"},{"en":"Modern abundance can make ordinary decisions more complex than before.","zh":"現代豐富選項可以令普通決定比以前更複雜。"},{"en":"This phrase captures the passage’s broad modern theme.","zh":"這個短語概括篇章廣泛的現代主題。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":19},{"front":"the influence of","meaning":"……的影響","examples":[{"en":"The passage examines the influence of more choices.","zh":"篇章考察更多選擇的影響。"},{"en":"The influence of something is the effect it has on people, events or results.","zh":"某事的影響，是指它對人、事件或結果產生的作用。"},{"en":"Teachers may discuss the influence of sleep on learning.","zh":"老師可能討論睡眠對學習的影響。"},{"en":"More choices influence happiness by changing how people compare and regret.","zh":"更多選擇透過改變人們比較和後悔的方式影響快樂。"},{"en":"This phrase is used when explaining impact.","zh":"這個短語用於解釋影響。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":19},{"front":"complexity in","meaning":"……中的複雜性","examples":[{"en":"The passage explores complexity in decision-making.","zh":"篇章探討決策中的複雜性。"},{"en":"Complexity in something means the difficulty created by many connected parts.","zh":"某事中的複雜性，是指由許多相連部分造成的困難。"},{"en":"There is complexity in planning a school trip because transport, cost and safety all matter.","zh":"規劃學校旅行有複雜性，因為交通、成本和安全都重要。"},{"en":"More options increase complexity in decision-making because each option must be compared.","zh":"更多選項增加決策中的複雜性，因為每個選項都要比較。"},{"en":"This phrase shows that a process is not simple.","zh":"這個短語顯示某個過程並不簡單。"}],"source":"136 - Decision making and Happiness.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 137":[{"front":"paper or computer","meaning":"紙張還是電腦","examples":[{"en":"The passage compares the usefulness of paper and computers.","zh":"文章比較紙張和電腦的用處。"},{"en":"Paper or computer refers to the choice between using physical paper and using digital devices.","zh":"paper or computer 指在使用實體紙張和使用數碼裝置之間作選擇。"},{"en":"A student may choose paper or computer when deciding how to take notes in class.","zh":"學生在決定如何在課堂記筆記時，可能要選擇紙張還是電腦。"},{"en":"Paper is useful for quick marking, while computers are useful for searching and storing files.","zh":"紙張適合快速批改，而電腦適合搜尋和儲存文件。"},{"en":"The best choice is not always paper or computer alone; different tasks may need different tools.","zh":"最佳選擇不一定只是紙張或電腦；不同任務可能需要不同工具。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":1},{"front":"computer technology","meaning":"電腦科技","examples":[{"en":"Computer technology was supposed to replace paper.","zh":"電腦科技原本預期會取代紙張。"},{"en":"Computer technology refers to digital tools, machines, and systems that process and store information.","zh":"computer technology 指處理和儲存資訊的數碼工具、機器和系統。"},{"en":"Offices use computer technology to write reports, send emails, and manage records.","zh":"辦公室使用電腦科技撰寫報告、發送電郵和管理記錄。"},{"en":"Computer technology can save time, but it does not automatically remove the need for paper.","zh":"電腦科技可以節省時間，但不會自動消除對紙張的需要。"},{"en":"This phrase is useful when discussing how digital tools change work and daily life.","zh":"討論數碼工具如何改變工作和日常生活時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":1},{"front":"be supposed to","meaning":"本應；原本預期會","examples":[{"en":"Computer technology was supposed to replace paper.","zh":"電腦科技本應取代紙張。"},{"en":"Be supposed to means something is expected, planned, or believed to happen.","zh":"be supposed to 表示某事被預期、計劃或認為會發生。"},{"en":"The meeting was supposed to start at nine, but the manager arrived late.","zh":"會議本應九點開始，但經理遲到了。"},{"en":"If a system is supposed to save time but creates more work, people may stop using it.","zh":"如果一個系統本應節省時間，卻製造更多工作，人們可能停止使用它。"},{"en":"This phrase often shows a gap between expectation and reality.","zh":"這個短語常顯示期望與現實之間的差距。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":1},{"front":"replace paper","meaning":"取代紙張","examples":[{"en":"Computer technology was expected to replace paper.","zh":"電腦科技原本被預期會取代紙張。"},{"en":"To replace paper means to use digital tools instead of physical sheets or documents.","zh":"replace paper 指使用數碼工具，而不是實體紙張或文件。"},{"en":"A school may try to replace paper by giving students tablets and online worksheets.","zh":"學校可能透過給學生平板電腦和網上工作紙來嘗試取代紙張。"},{"en":"Replacing paper can reduce storage needs, but it may make handwritten discussion harder.","zh":"取代紙張可以減少儲存需要，但可能令手寫討論更困難。"},{"en":"This phrase is often used when people discuss paperless offices or digital learning.","zh":"當人們討論無紙辦公室或數碼學習時，常用這個短語。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":1},{"front":"that hasn’t happened","meaning":"那並沒有發生","examples":[{"en":"People expected paper to disappear, but that hasn’t happened.","zh":"人們預期紙張會消失，但那並沒有發生。"},{"en":"That hasn’t happened means an expected event or change has not actually taken place.","zh":"that hasn’t happened 指預期中的事件或改變實際上沒有發生。"},{"en":"Many people thought cash would disappear quickly, but that hasn’t happened in every city.","zh":"許多人以為現金會很快消失，但在每個城市都不是這樣。"},{"en":"If a prediction fails, people may need to ask why that hasn’t happened.","zh":"如果預測失敗，人們可能需要問為甚麼那並沒有發生。"},{"en":"This phrase is useful for correcting an assumption.","zh":"這個短語適合用來修正假設。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":1},{"front":"the Western world","meaning":"西方世界","examples":[{"en":"Every country in the Western world uses more paper than before.","zh":"西方世界的每個國家都比以前使用更多紙張。"},{"en":"The Western world usually refers to Europe, North America, and societies strongly shaped by Western traditions.","zh":"the Western world 通常指歐洲、北美，以及深受西方傳統影響的社會。"},{"en":"Many offices in the Western world use both paper files and digital systems.","zh":"西方世界的許多辦公室同時使用紙本檔案和數碼系統。"},{"en":"Trends in the Western world do not always represent what happens in every country.","zh":"西方世界的趨勢不一定代表每個國家的情況。"},{"en":"This phrase is broad and should be used carefully because it covers many different societies.","zh":"這個短語很廣，應小心使用，因為它涵蓋許多不同社會。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":1},{"front":"on a per capita basis","meaning":"按人均計算","examples":[{"en":"People use more paper today on a per capita basis.","zh":"今天人們按人均計算使用更多紙張。"},{"en":"On a per capita basis means calculated for each person in a population.","zh":"on a per capita basis 指按人口中每個人計算。"},{"en":"A city may use less water overall but more water on a per capita basis if its population falls.","zh":"如果人口下降，一座城市的總用水量可能較少，但按人均計算用水量較高。"},{"en":"Per capita figures help compare places of different sizes more fairly.","zh":"人均數字有助較公平地比較不同規模的地方。"},{"en":"This phrase is useful when total numbers alone may be misleading.","zh":"當總數可能令人誤解時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":1},{"front":"paper consumption","meaning":"紙張消耗量","examples":[{"en":"Paper consumption rose in the United States between 1995 and 2000.","zh":"1995年至2000年間，美國的紙張消耗量上升。"},{"en":"Paper consumption means the amount of paper people or organisations use.","zh":"paper consumption 指個人或機構使用紙張的數量。"},{"en":"A school can reduce paper consumption by sharing notices online.","zh":"學校可以透過網上發布通告來減少紙張消耗量。"},{"en":"High paper consumption can increase costs and create more waste.","zh":"高紙張消耗量可以增加成本並製造更多廢物。"},{"en":"This phrase is often used in discussions of offices, schools, and environmental impact.","zh":"這個短語常用於討論辦公室、學校和環境影響。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":1},{"front":"uncoated free-sheet paper","meaning":"非塗布高級紙","examples":[{"en":"Uncoated free-sheet paper is the most common kind of office paper.","zh":"非塗布高級紙是最常見的一種辦公室用紙。"},{"en":"Uncoated free-sheet paper is plain printing or writing paper without a shiny coating.","zh":"uncoated free-sheet paper 指沒有光面塗層的普通印刷或書寫紙。"},{"en":"Most photocopy paper used in offices is uncoated free-sheet paper.","zh":"辦公室中大部分影印紙都是非塗布高級紙。"},{"en":"Because it is easy to print on, this paper is widely used for reports and letters.","zh":"由於它容易印刷，這種紙廣泛用於報告和信件。"},{"en":"This phrase is technical and usually appears in paper industry or office-use contexts.","zh":"這個短語較技術性，通常出現在造紙業或辦公用紙語境中。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":1},{"front":"the most common kind of","meaning":"最常見的一種……","examples":[{"en":"This is the most common kind of office paper.","zh":"這是最常見的一種辦公室用紙。"},{"en":"The most common kind of something is the type people use or see most often.","zh":"the most common kind of something 指人們最常使用或看見的類型。"},{"en":"Smartphones are now the most common kind of camera for many families.","zh":"對許多家庭而言，智能手機現在是最常見的一種相機。"},{"en":"If one type is the most common, shops usually keep more of it in stock.","zh":"如果某類型最常見，商店通常會存放更多該類貨品。"},{"en":"This phrase helps identify the usual or standard example in a category.","zh":"這個短語幫助指出一個類別中通常或標準的例子。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":1},{"front":"for instance","meaning":"例如","examples":[{"en":"Office paper, for instance, is often uncoated free-sheet paper.","zh":"例如，辦公室用紙通常是非塗布高級紙。"},{"en":"For instance means for example.","zh":"for instance 表示例如。"},{"en":"Some daily tools, for instance pens and calendars, still work well on paper.","zh":"有些日常工具，例如筆和日曆，仍然適合用紙張形式。"},{"en":"Writers use for instance to make a general point clearer with a specific example.","zh":"作者使用 for instance，以具體例子令一般觀點更清楚。"},{"en":"This phrase is useful when explaining an idea step by step.","zh":"逐步解釋想法時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":1},{"front":"rise almost fifteen per cent","meaning":"上升接近百分之十五","examples":[{"en":"The consumption of office paper rose almost fifteen per cent.","zh":"辦公室用紙的消耗量上升接近百分之十五。"},{"en":"To rise almost fifteen per cent means to increase by nearly 15%.","zh":"rise almost fifteen per cent 指增加接近15%。"},{"en":"If bus fares rise almost fifteen per cent, commuters may spend much more each month.","zh":"如果巴士票價上升接近百分之十五，通勤者每月可能多花很多錢。"},{"en":"A rise of this size can be noticeable even if it is not a complete doubling.","zh":"這種幅度的上升即使不是翻倍，也可以相當明顯。"},{"en":"This phrase is useful when describing numerical change.","zh":"描述數字變化時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":2},{"front":"generally taken as evidence of","meaning":"一般被視為……的證據","examples":[{"en":"This trend is generally taken as evidence of old habits.","zh":"這個趨勢一般被視為舊習慣的證據。"},{"en":"Generally taken as evidence of something means many people interpret it as proof or support for that idea.","zh":"generally taken as evidence of something 指許多人把某事解讀為支持某想法的證據。"},{"en":"Empty seats in a restaurant may be generally taken as evidence of poor demand.","zh":"餐廳座位空着可能一般被視為需求不足的證據。"},{"en":"A sign can be misleading if people take it as evidence without checking other causes.","zh":"如果人們沒有檢查其他原因就把某跡象當作證據，它可能會誤導人。"},{"en":"This phrase is useful when explaining how people commonly interpret a situation.","zh":"解釋人們通常如何理解某情況時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":2},{"front":"eradicate old habits","meaning":"根除舊習慣","examples":[{"en":"It is hard to eradicate old habits.","zh":"根除舊習慣很困難。"},{"en":"To eradicate old habits means to remove long-standing ways of behaving completely.","zh":"eradicate old habits 指完全除去長久以來的行為方式。"},{"en":"A student may struggle to eradicate old habits such as checking the phone while studying.","zh":"學生可能難以根除邊溫習邊看手機等舊習慣。"},{"en":"Old habits survive because they feel familiar and require less effort than new routines.","zh":"舊習慣能持續存在，因為它們感覺熟悉，而且比新習慣省力。"},{"en":"This phrase suggests complete removal, not just slight improvement.","zh":"這個短語表示完全去除，而不只是稍作改善。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":2},{"front":"wasteful habits","meaning":"浪費的習慣","examples":[{"en":"Using too much paper may seem like a wasteful habit.","zh":"使用太多紙張可能看似一種浪費的習慣。"},{"en":"Wasteful habits are repeated behaviours that use more resources than necessary.","zh":"wasteful habits 指反覆使用超出需要資源的行為。"},{"en":"Leaving lights on in an empty room is a wasteful habit.","zh":"在沒人的房間開着燈是一種浪費的習慣。"},{"en":"Wasteful habits increase costs and may harm the environment over time.","zh":"浪費的習慣會隨時間增加成本，並可能傷害環境。"},{"en":"This phrase is used when people criticise unnecessary use of time, money, energy, or materials.","zh":"當人們批評不必要地使用時間、金錢、能源或材料時，會用這個短語。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":2},{"front":"stubbornly resistant to","meaning":"頑固地抗拒……","examples":[{"en":"People may be stubbornly resistant to computerisation.","zh":"人們可能頑固地抗拒電腦化。"},{"en":"To be stubbornly resistant to something means to strongly refuse to accept or change toward it.","zh":"stubbornly resistant to something 指強烈拒絕接受某事或向某方向改變。"},{"en":"Some workers are stubbornly resistant to new software because they trust the old system.","zh":"有些員工頑固地抗拒新軟件，因為他們信任舊系統。"},{"en":"Strong resistance can slow change even when a new method is useful.","zh":"強烈抗拒會拖慢改變，即使新方法有用。"},{"en":"This phrase suggests unwillingness that is hard to change.","zh":"這個短語表示難以改變的不願意。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":2},{"front":"the efficiencies offered by","meaning":"……所帶來的效率","examples":[{"en":"Some people resist the efficiencies offered by computerisation.","zh":"有些人抗拒電腦化所帶來的效率。"},{"en":"The efficiencies offered by something are the time, cost, or effort savings it provides.","zh":"the efficiencies offered by something 指某事帶來的時間、成本或努力節省。"},{"en":"Online booking provides efficiencies by reducing queues and phone calls.","zh":"網上預約透過減少排隊和電話來帶來效率。"},{"en":"People may reject efficiencies if the new system feels confusing or impersonal.","zh":"如果新系統感覺混亂或沒有人情味，人們可能拒絕這些效率。"},{"en":"This phrase is often used when discussing technology, management, and work processes.","zh":"討論科技、管理和工作流程時，常用這個短語。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":2},{"front":"computerisation","meaning":"電腦化","examples":[{"en":"Computerisation has not eliminated the use of paper.","zh":"電腦化並沒有消除紙張的使用。"},{"en":"Computerisation is the process of replacing or supporting work with computers and digital systems.","zh":"computerisation 指用電腦和數碼系統取代或支援工作的過程。"},{"en":"A hospital may use computerisation to store patient records electronically.","zh":"醫院可能使用電腦化系統來電子儲存病人記錄。"},{"en":"Computerisation can improve speed, but workers may still need paper for discussion and planning.","zh":"電腦化可以提高速度，但員工仍可能需要紙張作討論和計劃。"},{"en":"This word is useful when describing a shift from manual to digital work.","zh":"描述從人手工作轉向數碼工作時，這個詞很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":2},{"front":"cognitive psychologists","meaning":"認知心理學家","examples":[{"en":"Cognitive psychologists argue that paper has real advantages.","zh":"認知心理學家認為紙張有真正優勢。"},{"en":"Cognitive psychologists study thinking, memory, attention, learning, and problem-solving.","zh":"cognitive psychologists 研究思考、記憶、注意力、學習和解難。"},{"en":"A cognitive psychologist may study why people remember handwritten notes better than typed notes.","zh":"認知心理學家可能研究為何人們對手寫筆記的記憶比打字筆記更好。"},{"en":"Their research can explain how tools affect the way people think.","zh":"他們的研究可以解釋工具如何影響人的思考方式。"},{"en":"This phrase refers to specialists in mental processes.","zh":"這個短語指研究心智過程的專家。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":2},{"front":"ergonomics experts","meaning":"人體工學專家","examples":[{"en":"Ergonomics experts study how people interact with tools and workplaces.","zh":"人體工學專家研究人們如何與工具和工作場所互動。"},{"en":"Ergonomics experts are specialists who design tools, furniture, and systems to fit human bodies and behaviour.","zh":"ergonomics experts 指設計工具、家具和系統，使其配合人體和行為的專家。"},{"en":"An ergonomics expert may suggest a better chair to reduce back pain at work.","zh":"人體工學專家可能建議使用更好的椅子，以減少工作時的背痛。"},{"en":"Good ergonomic design can make work safer, more comfortable, and more efficient.","zh":"良好人體工學設計可以令工作更安全、更舒適和更有效率。"},{"en":"This phrase is useful when discussing the relationship between people and their working environment.","zh":"討論人與工作環境的關係時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":2},{"front":"persist for good reasons","meaning":"因充分理由而持續存在","examples":[{"en":"Paper has persisted for very good reasons.","zh":"紙張因非常充分的理由而持續存在。"},{"en":"To persist for good reasons means to continue existing because there are strong practical causes.","zh":"persist for good reasons 指因有強而實際的原因而繼續存在。"},{"en":"Printed menus may persist for good reasons when elderly customers find QR codes difficult.","zh":"當長者顧客覺得 QR code 困難時，印刷餐牌可能因充分理由而持續存在。"},{"en":"If an old tool still solves problems well, it may persist despite new technology.","zh":"如果舊工具仍能有效解決問題，即使有新科技，它也可能持續存在。"},{"en":"This phrase suggests that survival is not just due to habit.","zh":"這個短語表示某事能保留下來不只是因為習慣。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":2},{"front":"when it comes to","meaning":"說到；涉及","examples":[{"en":"Paper is useful when it comes to certain cognitive tasks.","zh":"說到某些認知任務，紙張很有用。"},{"en":"When it comes to something means when discussing or dealing with that particular matter.","zh":"when it comes to something 指在討論或處理某個特定事情時。"},{"en":"When it comes to exam revision, some students prefer handwritten notes.","zh":"說到考試溫習，有些學生較喜歡手寫筆記。"},{"en":"A tool may be excellent for storage but weak when it comes to group discussion.","zh":"一個工具在儲存方面可能很出色，但涉及小組討論時可能較弱。"},{"en":"This phrase helps narrow a general topic to one specific area.","zh":"這個短語有助把一般主題收窄到特定範疇。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":2},{"front":"perform cognitive tasks","meaning":"執行認知任務","examples":[{"en":"Paper helps people perform certain cognitive tasks.","zh":"紙張幫助人們執行某些認知任務。"},{"en":"To perform cognitive tasks means to carry out mental activities such as reading, remembering, comparing, or planning.","zh":"perform cognitive tasks 指進行閱讀、記憶、比較或計劃等心智活動。"},{"en":"Students perform cognitive tasks when they summarise a passage or solve a maths problem.","zh":"學生概括文章或解數學題時，就是在執行認知任務。"},{"en":"The right tool can make cognitive tasks easier by reducing confusion and effort.","zh":"合適工具可以減少混亂和努力，使認知任務更容易。"},{"en":"This phrase is formal and often used in psychology or learning research.","zh":"這個短語較正式，常用於心理學或學習研究。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":3},{"front":"have advantages over","meaning":"比……有優勢","examples":[{"en":"Paper has many advantages over computers.","zh":"紙張比電腦有許多優勢。"},{"en":"To have advantages over something means to be better than it in certain ways.","zh":"have advantages over something 指在某些方面比另一事物更好。"},{"en":"Bicycles have advantages over cars for short trips in crowded streets.","zh":"在擁擠街道上的短途旅程中，單車比汽車有優勢。"},{"en":"A tool may have advantages over another tool for one task but not for every task.","zh":"一種工具在某項任務上可能比另一工具有優勢，但不是每項任務都如此。"},{"en":"This phrase is useful for making balanced comparisons.","zh":"作平衡比較時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":3},{"front":"dismay","meaning":"沮喪；不安","examples":[{"en":"Some people feel dismay at the sight of a messy desk.","zh":"有些人一看見凌亂書桌就感到不安。"},{"en":"Dismay is a feeling of worry, disappointment, or shock when something seems wrong.","zh":"dismay 指當某事似乎出錯時產生的擔憂、失望或震驚。"},{"en":"A teacher may feel dismay when students submit blank answer sheets.","zh":"當學生交白卷時，老師可能感到沮喪。"},{"en":"Dismay can lead people to judge a situation too quickly before understanding it.","zh":"不安可能令人未理解情況就太快作出判斷。"},{"en":"This word is stronger than simple dislike.","zh":"這個詞比簡單的不喜歡更強。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":3},{"front":"at the sight of","meaning":"一看見……","examples":[{"en":"People may feel dismay at the sight of a messy desk.","zh":"人們一看見凌亂書桌可能感到不安。"},{"en":"At the sight of something means immediately when someone sees it.","zh":"at the sight of something 指某人一看見某物時。"},{"en":"A child smiled at the sight of the birthday cake.","zh":"孩子一看見生日蛋糕就笑了。"},{"en":"People may react strongly at the sight of a problem before they know the reason behind it.","zh":"人們一看見問題，可能在了解背後原因前就有強烈反應。"},{"en":"This phrase connects seeing something with an emotional reaction.","zh":"這個短語把看見某物與情緒反應連接起來。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":3},{"front":"a messy desk","meaning":"凌亂的書桌","examples":[{"en":"A messy desk may actually reflect active thinking.","zh":"凌亂的書桌其實可能反映主動思考。"},{"en":"A messy desk is a desk covered with papers, books, or objects in an untidy way.","zh":"a messy desk 指以不整齊方式堆滿紙張、書本或物件的書桌。"},{"en":"A student’s messy desk may contain homework, notes, pens, and unfinished projects.","zh":"學生凌亂的書桌可能有功課、筆記、筆和未完成項目。"},{"en":"A messy desk can slow work if important documents are hard to find.","zh":"如果重要文件難以找到，凌亂的書桌可能拖慢工作。"},{"en":"However, a messy desk may also show that someone is working through many ideas.","zh":"然而，凌亂的書桌也可能顯示某人正在處理許多想法。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":3},{"front":"the spectacle of","meaning":"……的景象","examples":[{"en":"Some people are surprised by the spectacle of paper being used in high-tech workplaces.","zh":"有些人對高科技工作場所中使用紙張的景象感到驚訝。"},{"en":"The spectacle of something means the striking or surprising sight of it.","zh":"the spectacle of something 指某事令人印象深刻或驚訝的景象。"},{"en":"Visitors may stop at the spectacle of hundreds of students leaving school at once.","zh":"訪客可能會因數百名學生同時放學的景象而停下來。"},{"en":"A spectacle can make people notice a situation more strongly than a simple description would.","zh":"景象可以比簡單描述更強烈地令人注意到某情況。"},{"en":"This phrase often suggests that what is seen is dramatic, unusual, or memorable.","zh":"這個短語常表示所見之事戲劇化、不尋常或令人難忘。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":3},{"front":"air-traffic controllers","meaning":"航空交通管制員","examples":[{"en":"Air-traffic controllers may track flights through notes on paper strips.","zh":"航空交通管制員可能透過紙條上的筆記追蹤航班。"},{"en":"Air-traffic controllers are workers who guide aircraft safely in the sky and at airports.","zh":"air-traffic controllers 指在空中和機場安全引導航機的工作人員。"},{"en":"Air-traffic controllers must watch many flights and communicate clearly with pilots.","zh":"航空交通管制員必須監察許多航班，並清楚與機師溝通。"},{"en":"Mistakes by air-traffic controllers can be dangerous because many aircraft depend on their instructions.","zh":"航空交通管制員出錯可能很危險，因為許多飛機依賴他們的指示。"},{"en":"This phrase belongs to aviation and safety management.","zh":"這個短語屬於航空和安全管理語境。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":3},{"front":"track flights","meaning":"追蹤航班","examples":[{"en":"Controllers track flights through notes scribbled on paper strips.","zh":"管制員透過匆匆寫在紙條上的筆記追蹤航班。"},{"en":"To track flights means to follow aircraft positions, times, and movements.","zh":"track flights 指跟進飛機的位置、時間和移動。"},{"en":"Airport staff track flights to know whether planes are early, delayed, or landing soon.","zh":"機場職員追蹤航班，以知道飛機是提早、延誤還是即將降落。"},{"en":"Tracking flights helps prevent confusion and supports safe coordination.","zh":"追蹤航班有助防止混亂並支援安全協調。"},{"en":"This phrase focuses on monitoring movement over time.","zh":"這個短語聚焦隨時間監察移動。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":3},{"front":"notes scribbled on","meaning":"匆匆寫在……上的筆記","examples":[{"en":"The controllers use notes scribbled on paper strips.","zh":"管制員使用匆匆寫在紙條上的筆記。"},{"en":"Notes scribbled on something are quick, rough written marks made on a surface.","zh":"notes scribbled on something 指快速、粗略寫在某表面上的筆記。"},{"en":"A student may use notes scribbled on a sticky note to remember homework.","zh":"學生可能用匆匆寫在便利貼上的筆記來記住功課。"},{"en":"Scribbled notes are fast to make, but they may be hard for others to read.","zh":"匆匆寫下的筆記很快能完成，但別人可能難以閱讀。"},{"en":"This phrase suggests informal writing done quickly.","zh":"這個短語表示快速完成的非正式書寫。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":3},{"front":"paper strips","meaning":"紙條","examples":[{"en":"Paper strips can help air-traffic controllers track flights.","zh":"紙條可以幫助航空交通管制員追蹤航班。"},{"en":"Paper strips are narrow pieces of paper used to hold short notes or information.","zh":"paper strips 指用來記下短筆記或資料的窄紙片。"},{"en":"A teacher may use paper strips for vocabulary games in class.","zh":"老師可能在課堂詞彙遊戲中使用紙條。"},{"en":"Small paper strips are useful when information must be moved, sorted, or arranged physically.","zh":"當資料需要實體移動、分類或排列時，小紙條很有用。"},{"en":"This phrase refers to paper cut into thin pieces, not full sheets.","zh":"這個短語指被裁成窄條的紙，而不是整張紙。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":3},{"front":"arise from","meaning":"源於","examples":[{"en":"The dismay arises from a fundamental confusion about paper.","zh":"這種不安源於對紙張的根本誤解。"},{"en":"To arise from something means to be caused by it or come from it.","zh":"arise from something 指由某事造成或來自某事。"},{"en":"Many arguments arise from unclear instructions.","zh":"許多爭執源於指示不清。"},{"en":"If a problem arises from misunderstanding, better explanation may solve it.","zh":"如果問題源於誤解，更好的解釋可能解決它。"},{"en":"This phrase is useful when explaining the source of a feeling, issue, or event.","zh":"解釋感受、問題或事件來源時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":3},{"front":"a fundamental confusion about","meaning":"對……的根本誤解","examples":[{"en":"There is a fundamental confusion about the role of paper.","zh":"人們對紙張所扮演的角色有根本誤解。"},{"en":"A fundamental confusion about something is a deep misunderstanding of what it is or why it matters.","zh":"a fundamental confusion about something 指對某事物是甚麼或為何重要有深層誤解。"},{"en":"A fundamental confusion about exams may make students think memorising alone is enough.","zh":"對考試的根本誤解可能令學生以為單靠背誦就足夠。"},{"en":"Deep confusion can lead people to reject something useful for the wrong reason.","zh":"深層誤解可以令人因錯誤理由拒絕有用事物。"},{"en":"This phrase points to a basic problem in understanding.","zh":"這個短語指出理解上的基本問題。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":4},{"front":"the role that paper plays","meaning":"紙張所扮演的角色","examples":[{"en":"People misunderstand the role that paper plays in our lives.","zh":"人們誤解紙張在我們生活中所扮演的角色。"},{"en":"The role that paper plays means the function or purpose paper has in a situation.","zh":"the role that paper plays 指紙張在某情況中的功能或用途。"},{"en":"In meetings, the role that paper plays may be to help people see and discuss the same document.","zh":"在會議中，紙張所扮演的角色可能是幫助人們看見並討論同一份文件。"},{"en":"Understanding a tool’s role helps people decide when to keep it and when to replace it.","zh":"了解工具的角色有助人們決定何時保留它、何時取代它。"},{"en":"This phrase focuses on function, not just physical appearance.","zh":"這個短語聚焦功能，而不只是外觀。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":4},{"front":"the case for paper","meaning":"支持紙張的理據","examples":[{"en":"The case for paper is made clearly in a book by Sellen and Harper.","zh":"支持紙張的理據在 Sellen 和 Harper 的一本書中被清楚提出。"},{"en":"The case for paper means the argument supporting the continued use of paper.","zh":"the case for paper 指支持繼續使用紙張的論點。"},{"en":"A teacher may make the case for paper when explaining why handwriting helps revision.","zh":"老師解釋為何手寫有助溫習時，可能提出支持紙張的理據。"},{"en":"The case for paper becomes stronger when digital tools fail to support discussion well.","zh":"當數碼工具無法有效支援討論時，支持紙張的理據會更強。"},{"en":"This phrase is used when presenting reasons in favour of something.","zh":"提出支持某事的理由時，會使用這個短語。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":4},{"front":"be made eloquently","meaning":"被有力地闡述","examples":[{"en":"The case for paper is made eloquently by two social scientists.","zh":"支持紙張的理據由兩位社會科學家有力地闡述。"},{"en":"To be made eloquently means to be expressed clearly, strongly, and persuasively.","zh":"be made eloquently 指被清楚、有力並具說服力地表達。"},{"en":"A student’s argument may be made eloquently if it uses clear examples and careful language.","zh":"如果學生的論點使用清楚例子和謹慎語言，它可能被有力地闡述。"},{"en":"An eloquent explanation can change minds because people understand the reason behind it.","zh":"有說服力的解釋可以改變想法，因為人們明白背後原因。"},{"en":"This phrase describes effective expression, not just correct grammar.","zh":"這個短語描述有效表達，而不只是文法正確。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":4},{"front":"paperless office","meaning":"無紙辦公室","examples":[{"en":"The book challenges the myth of the paperless office.","zh":"這本書挑戰無紙辦公室的迷思。"},{"en":"A paperless office is a workplace that tries to use digital documents instead of paper.","zh":"paperless office 指嘗試用數碼文件取代紙張的工作場所。"},{"en":"A company may aim for a paperless office by using email, cloud storage, and online forms.","zh":"公司可能透過使用電郵、雲端儲存和網上表格來追求無紙辦公室。"},{"en":"A paperless office can save storage space, but some tasks may still work better on paper.","zh":"無紙辦公室可以節省儲存空間，但有些任務可能仍然較適合紙張。"},{"en":"This phrase often describes an ideal that is difficult to achieve completely.","zh":"這個短語常描述一個難以完全達成的理想。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":4},{"front":"social scientists","meaning":"社會科學家","examples":[{"en":"Two social scientists studied why paper remains useful.","zh":"兩位社會科學家研究為何紙張仍然有用。"},{"en":"Social scientists are researchers who study human behaviour, organisations, society, and relationships.","zh":"social scientists 指研究人類行為、組織、社會和關係的研究人員。"},{"en":"Social scientists may observe how office workers actually use documents during meetings.","zh":"社會科學家可能觀察辦公室職員在會議中實際如何使用文件。"},{"en":"Their research can reveal habits and needs that technology designers may miss.","zh":"他們的研究可以揭示科技設計者可能忽略的習慣和需要。"},{"en":"This phrase refers to academic researchers of social life.","zh":"這個短語指研究社會生活的學術研究人員。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":4},{"front":"begin with an account of","meaning":"以對……的描述開始","examples":[{"en":"The authors begin with an account of a study at the IMF.","zh":"作者以對國際貨幣基金組織一項研究的描述開始。"},{"en":"To begin with an account of something means to start by describing it.","zh":"begin with an account of something 指以描述某事作為開端。"},{"en":"A report may begin with an account of a real workplace problem.","zh":"報告可能以對真實工作場所問題的描述開始。"},{"en":"Beginning with a clear account helps readers understand the evidence before the argument.","zh":"以清楚描述開始，有助讀者在理解論點前先理解證據。"},{"en":"This phrase is useful when describing how a text opens.","zh":"描述文本如何開首時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":4},{"front":"conduct a study","meaning":"進行研究","examples":[{"en":"They conducted a study at the International Monetary Fund.","zh":"他們在國際貨幣基金組織進行研究。"},{"en":"To conduct a study means to carry out research in an organised way.","zh":"conduct a study 指以有組織方式進行研究。"},{"en":"A school may conduct a study to find out why students are late.","zh":"學校可能進行研究，以查明學生遲到的原因。"},{"en":"Conducting a study can reveal patterns that casual observation misses.","zh":"進行研究可以揭示隨意觀察所忽略的模式。"},{"en":"This phrase is common in academic, business, and policy contexts.","zh":"這個短語常見於學術、商業和政策語境。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":4},{"front":"International Monetary Fund","meaning":"國際貨幣基金組織","examples":[{"en":"The International Monetary Fund was the site of the study.","zh":"國際貨幣基金組織是這項研究的地點。"},{"en":"The International Monetary Fund is an international organisation connected with global financial cooperation and economic stability.","zh":"International Monetary Fund 指與全球金融合作和經濟穩定有關的國際組織。"},{"en":"Economists at the International Monetary Fund often analyse economic data and write reports.","zh":"國際貨幣基金組織的經濟學家常分析經濟數據並撰寫報告。"},{"en":"A study there can show how highly educated office workers use paper in serious professional work.","zh":"在那裡進行研究，可以顯示高學歷辦公室職員如何在嚴肅專業工作中使用紙張。"},{"en":"This phrase is often shortened to IMF.","zh":"這個名稱常縮寫為 IMF。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":4},{"front":"spend most of their time","meaning":"花大部分時間","examples":[{"en":"Economists at the IMF spend most of their time writing reports.","zh":"國際貨幣基金組織的經濟學家花大部分時間撰寫報告。"},{"en":"To spend most of one’s time doing something means to use the largest part of one’s time on that activity.","zh":"spend most of one’s time doing something 指把最大部分時間用於某活動。"},{"en":"A student preparing for exams may spend most of her time reviewing notes.","zh":"準備考試的學生可能花大部分時間溫習筆記。"},{"en":"If people spend most of their time on one task, the tools for that task become very important.","zh":"如果人們把大部分時間花在一項任務上，該任務所需工具就變得很重要。"},{"en":"This phrase shows what dominates someone’s daily routine.","zh":"這個短語顯示甚麼主導某人的日常生活。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":4},{"front":"complicated economic questions","meaning":"複雜經濟問題","examples":[{"en":"The economists write reports on complicated economic questions.","zh":"經濟學家撰寫關於複雜經濟問題的報告。"},{"en":"Complicated economic questions are difficult issues about money, trade, jobs, growth, or public finance.","zh":"complicated economic questions 指關於金錢、貿易、工作、增長或公共財政的困難問題。"},{"en":"A government may study complicated economic questions before changing tax policy.","zh":"政府在改變稅務政策前，可能研究複雜經濟問題。"},{"en":"These questions often require data, expert judgement, and careful discussion.","zh":"這些問題常需要數據、專業判斷和仔細討論。"},{"en":"This phrase suggests problems that cannot be solved with a simple answer.","zh":"這個短語表示不能用簡單答案解決的問題。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":4},{"front":"be perfectly suited to","meaning":"非常適合","examples":[{"en":"The work seems perfectly suited to computer use.","zh":"這項工作似乎非常適合使用電腦。"},{"en":"To be perfectly suited to something means to seem very appropriate or useful for it.","zh":"be perfectly suited to something 指似乎非常適合或有利於某事。"},{"en":"Online forms are perfectly suited to collecting simple contact information.","zh":"網上表格非常適合收集簡單聯絡資料。"},{"en":"A task may seem suited to computers but still require paper during discussion.","zh":"一項任務可能看似適合電腦，但在討論時仍需要紙張。"},{"en":"This phrase shows a strong match between a task and a tool or method.","zh":"這個短語顯示任務與工具或方法之間非常配合。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":5},{"front":"sit in front of a computer","meaning":"坐在電腦前","examples":[{"en":"Writing reports may seem suited to sitting in front of a computer.","zh":"撰寫報告可能看似適合坐在電腦前完成。"},{"en":"To sit in front of a computer means to work or spend time facing a computer screen.","zh":"sit in front of a computer 指面對電腦屏幕工作或花時間。"},{"en":"Office workers may sit in front of a computer for many hours each day.","zh":"辦公室職員每天可能坐在電腦前好幾小時。"},{"en":"Long hours at a computer can make people tired if they do not take breaks.","zh":"如果不休息，長時間坐在電腦前可能令人疲倦。"},{"en":"This phrase describes a common modern work posture and routine.","zh":"這個短語描述常見的現代工作姿勢和日常狀態。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":5},{"front":"nonetheless","meaning":"儘管如此","examples":[{"en":"Nonetheless, the IMF is awash in paper.","zh":"儘管如此，國際貨幣基金組織仍充滿大量紙張。"},{"en":"Nonetheless means despite what has just been said.","zh":"nonetheless 指儘管剛才所說的情況如此。"},{"en":"The software is useful; nonetheless, some teachers still prefer printed worksheets.","zh":"這個軟件很有用；儘管如此，有些老師仍較喜歡印刷工作紙。"},{"en":"This word introduces a contrast between expectation and reality.","zh":"這個詞引出期望與現實之間的對比。"},{"en":"It is more formal than but.","zh":"它比 but 更正式。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":5},{"front":"be awash in paper","meaning":"充滿大量紙張","examples":[{"en":"The IMF is awash in paper despite its use of computers.","zh":"儘管使用電腦，國際貨幣基金組織仍充滿大量紙張。"},{"en":"To be awash in paper means to contain or be covered with a very large amount of paper.","zh":"be awash in paper 指充滿或覆蓋着大量紙張。"},{"en":"During exam season, a teacher’s desk may be awash in paper.","zh":"考試季節期間，老師的書桌可能充滿大量紙張。"},{"en":"An office can be awash in paper when many people print drafts, forms, and reports.","zh":"當許多人列印草稿、表格和報告時，辦公室可能充滿大量紙張。"},{"en":"This phrase suggests an unexpectedly large amount.","zh":"這個短語表示數量大得出乎意料。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":5},{"front":"find out why","meaning":"查明原因","examples":[{"en":"The researchers wanted to find out why paper was still used.","zh":"研究人員想查明為何紙張仍被使用。"},{"en":"To find out why means to discover the reason behind something.","zh":"find out why 指發現某事背後的原因。"},{"en":"A parent may talk to a child to find out why homework is always late.","zh":"父母可能與孩子交談，以查明為何功課總是遲交。"},{"en":"Finding out why a problem happens helps people choose a better solution.","zh":"查明問題發生的原因，有助人們選擇更好的解決方法。"},{"en":"This phrase focuses on discovering causes, not just noticing facts.","zh":"這個短語聚焦發現原因，而不只是注意到事實。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":5},{"front":"the business of writing reports","meaning":"撰寫報告這件事","examples":[{"en":"The business of writing reports is highly collaborative.","zh":"撰寫報告這件事高度協作。"},{"en":"The business of writing reports means the work, process, and practical activity of producing reports.","zh":"the business of writing reports 指製作報告的工作、過程和實際活動。"},{"en":"In a company, the business of writing reports may include collecting data, drafting, reviewing, and revising.","zh":"在公司中，撰寫報告這件事可能包括收集數據、起草、審閱和修改。"},{"en":"Report writing becomes complicated when many people must approve the final version.","zh":"當許多人必須批准最終版本時，報告寫作會變得複雜。"},{"en":"This phrase treats report writing as a serious work process, not just typing words.","zh":"這個短語把報告寫作視為嚴肅工作流程，而不只是打字。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":5},{"front":"at least at","meaning":"至少在……","examples":[{"en":"The process is collaborative, at least at the IMF.","zh":"這個過程是協作性的，至少在國際貨幣基金組織如此。"},{"en":"At least at a place means the statement is true for that place, even if it may not be true everywhere.","zh":"at least at a place 指某說法在該地方成立，即使未必在所有地方都成立。"},{"en":"Students use printed notes often, at least at this school.","zh":"學生常使用印刷筆記，至少在這間學校如此。"},{"en":"This phrase limits a claim so it does not sound too broad.","zh":"這個短語限制說法，使它不會聽起來太廣泛。"},{"en":"It is useful when evidence comes from one setting only.","zh":"當證據只來自一個環境時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":5},{"front":"an intensely collaborative process","meaning":"高度協作的過程","examples":[{"en":"Writing reports is an intensely collaborative process.","zh":"撰寫報告是一個高度協作的過程。"},{"en":"An intensely collaborative process is work that requires many people to contribute, discuss, and revise together.","zh":"an intensely collaborative process 指需要許多人共同貢獻、討論和修訂的工作。"},{"en":"Making a school magazine can be an intensely collaborative process involving writers, editors, and designers.","zh":"製作校刊可以是一個高度協作的過程，涉及作者、編輯和設計師。"},{"en":"Such a process needs clear communication because one person’s change affects others.","zh":"這種過程需要清楚溝通，因為一個人的修改會影響其他人。"},{"en":"This phrase stresses deep teamwork, not occasional help.","zh":"這個短語強調深入團隊合作，而不是偶爾幫忙。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":5},{"front":"involve professional judgements","meaning":"涉及專業判斷","examples":[{"en":"The process involves professional judgements from many people.","zh":"這個過程涉及許多人的專業判斷。"},{"en":"To involve professional judgements means to require expert opinions based on training and experience.","zh":"involve professional judgements 指需要基於訓練和經驗的專家意見。"},{"en":"A hospital policy may involve professional judgements from doctors, nurses, and managers.","zh":"醫院政策可能涉及醫生、護士和管理人員的專業判斷。"},{"en":"When a decision involves professional judgements, it may need discussion rather than a simple rule.","zh":"當決定涉及專業判斷時，它可能需要討論，而不是簡單規則。"},{"en":"This phrase shows that skilled evaluation is part of the process.","zh":"這個短語顯示熟練評估是過程的一部分。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":5},{"front":"contributions of many people","meaning":"許多人的貢獻","examples":[{"en":"Report writing involves the contributions of many people.","zh":"報告寫作涉及許多人的貢獻。"},{"en":"Contributions of many people are the ideas, comments, work, or support provided by several individuals.","zh":"contributions of many people 指幾個人提供的想法、評語、工作或支援。"},{"en":"A community event depends on the contributions of many people, from planners to volunteers.","zh":"社區活動依靠許多人的貢獻，從策劃者到義工都包括在內。"},{"en":"When many people contribute, the final result may be richer but harder to coordinate.","zh":"當許多人作出貢獻，最終成果可能更豐富，但更難協調。"},{"en":"This phrase highlights shared effort.","zh":"這個短語突出共同努力。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":5},{"front":"drafts of reports","meaning":"報告草稿","examples":[{"en":"The economists bring drafts of reports to conference rooms.","zh":"經濟學家把報告草稿帶到會議室。"},{"en":"Drafts of reports are unfinished versions of reports prepared for review and revision.","zh":"drafts of reports 指準備用作審閱和修改的未完成報告版本。"},{"en":"A student may show drafts of reports to a teacher before submitting the final copy.","zh":"學生可能在提交最終版本前，把報告草稿給老師看。"},{"en":"Drafts allow people to correct mistakes and improve ideas before publication.","zh":"草稿讓人們在出版或提交前改正錯誤並改善想法。"},{"en":"This phrase refers to work in progress, not final documents.","zh":"這個短語指進行中的工作，而不是最終文件。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":5},{"front":"conference rooms","meaning":"會議室","examples":[{"en":"Economists discuss drafts in conference rooms.","zh":"經濟學家在會議室討論草稿。"},{"en":"Conference rooms are rooms used for meetings, discussions, and group decisions.","zh":"conference rooms 指用於會議、討論和小組決策的房間。"},{"en":"A team may book a conference room to review a project plan.","zh":"團隊可能預訂會議室來審閱項目計劃。"},{"en":"Conference rooms help people work together because everyone can see documents and speak directly.","zh":"會議室幫助人們合作，因為每個人都能看到文件並直接發言。"},{"en":"This phrase is common in office and organisational settings.","zh":"這個短語常見於辦公室和組織環境。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":6},{"front":"spread out the relevant pages","meaning":"攤開相關頁面","examples":[{"en":"The economists spread out the relevant pages.","zh":"經濟學家攤開相關頁面。"},{"en":"To spread out the relevant pages means to place the needed pages across a surface so people can see them.","zh":"spread out the relevant pages 指把需要的頁面放在桌面上，讓人能看見。"},{"en":"Students may spread out the relevant pages of notes before writing an essay.","zh":"學生寫文章前，可能攤開相關筆記頁面。"},{"en":"Spreading pages out helps people compare information quickly.","zh":"攤開頁面有助人們快速比較資料。"},{"en":"This phrase shows a physical way of organising documents.","zh":"這個短語顯示一種實體整理文件的方法。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":6},{"front":"relevant pages","meaning":"相關頁面","examples":[{"en":"The economists discuss the relevant pages together.","zh":"經濟學家一起討論相關頁面。"},{"en":"Relevant pages are the pages that matter for the topic or decision being discussed.","zh":"relevant pages 指與正在討論的主題或決定有關的頁面。"},{"en":"A teacher may ask students to read only the relevant pages before class.","zh":"老師可能要求學生上課前只閱讀相關頁面。"},{"en":"Identifying relevant pages saves time because people do not need to search the whole document.","zh":"找出相關頁面可以節省時間，因為人們不需要搜尋整份文件。"},{"en":"This phrase focuses on information that is directly connected to the task.","zh":"這個短語聚焦與任務直接相關的資料。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":6},{"front":"negotiate changes with","meaning":"與……商討修改","examples":[{"en":"The economists negotiate changes with one another.","zh":"經濟學家彼此商討修改。"},{"en":"To negotiate changes with someone means to discuss and agree on revisions together.","zh":"negotiate changes with someone 指與某人討論並共同同意修改。"},{"en":"A writer may negotiate changes with an editor before publishing an article.","zh":"作者可能在文章出版前與編輯商討修改。"},{"en":"Negotiating changes prevents one person from controlling the whole document unfairly.","zh":"商討修改可以防止一個人不公平地控制整份文件。"},{"en":"This phrase is useful when revision requires discussion and agreement.","zh":"當修訂需要討論和同意時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":6},{"front":"jot down comments","meaning":"匆匆寫下評語","examples":[{"en":"They jot down comments in the margin.","zh":"他們在頁邊空白處匆匆寫下評語。"},{"en":"To jot down comments means to write short notes quickly.","zh":"jot down comments 指快速寫下簡短筆記或評語。"},{"en":"A teacher may jot down comments while listening to a student presentation.","zh":"老師可能在聽學生匯報時匆匆寫下評語。"},{"en":"Quick comments help people capture ideas before they forget them.","zh":"快速評語幫助人們在忘記前記下想法。"},{"en":"This phrase suggests brief, informal writing rather than polished sentences.","zh":"這個短語表示簡短、非正式的書寫，而不是修飾好的句子。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":6},{"front":"in the margin","meaning":"在頁邊空白處","examples":[{"en":"Economists write comments in the margin of the draft.","zh":"經濟學家在草稿的頁邊空白處寫評語。"},{"en":"In the margin means in the blank space at the side of a page.","zh":"in the margin 指在頁面側邊的空白位置。"},{"en":"Students often write vocabulary notes in the margin of a reading passage.","zh":"學生常在閱讀文章的頁邊空白處寫詞彙筆記。"},{"en":"Writing in the margin allows readers to comment without rewriting the whole text.","zh":"在頁邊空白處書寫讓讀者可以加評語，而不用重寫整篇文本。"},{"en":"This phrase is useful when discussing printed pages and handwritten notes.","zh":"討論印刷頁面和手寫筆記時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":6},{"front":"take advantage of","meaning":"利用","examples":[{"en":"They take advantage of the freedom of handwritten notes.","zh":"他們利用手寫筆記的自由度。"},{"en":"To take advantage of something means to use a benefit or opportunity well.","zh":"take advantage of something 指善用某個好處或機會。"},{"en":"Students can take advantage of library hours to finish homework after school.","zh":"學生可以利用圖書館開放時間在放學後完成功課。"},{"en":"If people take advantage of a tool’s strengths, they can work more effectively.","zh":"如果人們利用工具的優勢，就能更有效工作。"},{"en":"This phrase is positive when it means making good use of something.","zh":"當意思是善用某事時，這個短語是正面的。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":6},{"front":"the informality of","meaning":"……的非正式性","examples":[{"en":"Writers enjoy the informality of handwritten notes.","zh":"作者享受手寫筆記的非正式性。"},{"en":"The informality of something is its relaxed, flexible, and unofficial quality.","zh":"the informality of something 指某事輕鬆、靈活和非官方的特質。"},{"en":"The informality of a small meeting may help shy staff speak more freely.","zh":"小型會議的非正式性可能幫助害羞員工更自由發言。"},{"en":"Informality can encourage quick ideas because people feel less pressure to be perfect.","zh":"非正式性可以鼓勵快速想法，因為人們感到較少完美壓力。"},{"en":"This phrase contrasts with formal, polished, or official communication.","zh":"這個短語與正式、修飾完善或官方溝通形成對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":6},{"front":"handwritten note","meaning":"手寫筆記","examples":[{"en":"A handwritten note allows flexible comments.","zh":"手寫筆記容許靈活評語。"},{"en":"A handwritten note is a message or comment written by hand rather than typed.","zh":"handwritten note 指用手寫而不是打字寫出的訊息或評語。"},{"en":"A teacher may leave a handwritten note on a student’s essay.","zh":"老師可能在學生文章上留下手寫筆記。"},{"en":"Handwritten notes can feel personal and can be placed exactly beside the relevant text.","zh":"手寫筆記可以感覺更個人化，並能準確放在相關文本旁邊。"},{"en":"This phrase refers to both the form and the personal style of writing.","zh":"這個短語同時指書寫形式和個人書寫風格。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":6},{"front":"annotated draft","meaning":"已加註的草稿","examples":[{"en":"The economist delivers the annotated draft to the author.","zh":"經濟學家把已加註的草稿交給作者。"},{"en":"An annotated draft is an unfinished text with notes, comments, or corrections added to it.","zh":"annotated draft 指加入筆記、評語或修改的未完成文本。"},{"en":"A teacher may return an annotated draft so a student can improve the final essay.","zh":"老師可能交回已加註的草稿，讓學生改善最終文章。"},{"en":"Annotations help writers see exactly which parts need attention.","zh":"註釋幫助作者準確看見哪些部分需要注意。"},{"en":"This phrase is common in editing, academic writing, and collaborative work.","zh":"這個短語常見於編輯、學術寫作和協作工作。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":6},{"front":"in person","meaning":"親身","examples":[{"en":"The economist gives the annotated draft to the author in person.","zh":"經濟學家親身把已加註的草稿交給作者。"},{"en":"In person means directly face to face, not by email, phone, or another person.","zh":"in person 指面對面直接進行，而不是透過電郵、電話或他人。"},{"en":"A manager may discuss a serious problem in person rather than by message.","zh":"經理可能親身討論嚴重問題，而不是用訊息。"},{"en":"Meeting in person can reduce misunderstanding because people can ask questions immediately.","zh":"親身會面可以減少誤解，因為人們可以立即提問。"},{"en":"This phrase contrasts physical presence with remote communication.","zh":"這個短語把實體在場與遙距溝通作對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":6},{"front":"page by page","meaning":"逐頁地","examples":[{"en":"The reviewer takes the author through the suggested changes page by page.","zh":"審閱者逐頁向作者講解建議修改。"},{"en":"Page by page means one page at a time in order.","zh":"page by page 指按順序一頁一頁地。"},{"en":"A teacher may review a student’s portfolio page by page.","zh":"老師可能逐頁審閱學生作品集。"},{"en":"Going page by page prevents people from missing small but important comments.","zh":"逐頁處理可以防止人們錯過細小但重要的評語。"},{"en":"This phrase suggests a careful and organised review.","zh":"這個短語表示仔細而有組織的審閱。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":7},{"front":"take someone through","meaning":"向某人逐步講解","examples":[{"en":"The reviewer takes the author through the suggested changes.","zh":"審閱者向作者逐步講解建議修改。"},{"en":"To take someone through something means to explain it step by step.","zh":"take someone through something 指一步一步向某人解釋某事。"},{"en":"A trainer may take new staff through the safety rules on their first day.","zh":"培訓員可能在新員工第一天向他們逐步講解安全規則。"},{"en":"Step-by-step explanation helps people understand not only what changed but why.","zh":"逐步解釋幫助人們理解不只是改了甚麼，還有為何修改。"},{"en":"This phrase is useful when someone guides another person through a process.","zh":"當某人引導另一人理解過程時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":7},{"front":"suggested changes","meaning":"建議修改","examples":[{"en":"The author reviews all the suggested changes.","zh":"作者審閱所有建議修改。"},{"en":"Suggested changes are revisions or improvements that someone recommends.","zh":"suggested changes 指某人建議的修訂或改善。"},{"en":"An editor may write suggested changes in the margin of a draft article.","zh":"編輯可能在文章草稿的頁邊空白處寫下建議修改。"},{"en":"Suggested changes can improve a text, but the author may still decide which ones to accept.","zh":"建議修改可以改善文本，但作者仍可決定接受哪些。"},{"en":"This phrase is common in reviewing, editing, and teamwork.","zh":"這個短語常見於審閱、編輯和團隊合作。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":7},{"front":"at the end of the process","meaning":"在過程最後","examples":[{"en":"At the end of the process, the author enters the comments on the computer.","zh":"在過程最後，作者把評語輸入電腦。"},{"en":"At the end of the process means during the final stage after earlier steps are complete.","zh":"at the end of the process 指在早前步驟完成後的最後階段。"},{"en":"At the end of the process, students submit the final version of their project.","zh":"在過程最後，學生提交項目的最終版本。"},{"en":"Final steps often turn discussion and notes into a finished product.","zh":"最後步驟常把討論和筆記變成完成品。"},{"en":"This phrase helps show sequence in a work process.","zh":"這個短語有助顯示工作流程的順序。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":7},{"front":"move the pages around","meaning":"移動頁面","examples":[{"en":"The author moves the pages around while working.","zh":"作者工作時移動頁面。"},{"en":"To move the pages around means to physically change the order or position of pages.","zh":"move the pages around 指實體改變頁面的順序或位置。"},{"en":"A student may move pages around to decide the best order for a presentation.","zh":"學生可能移動頁面，以決定匯報的最佳次序。"},{"en":"Moving pages helps writers see structure and compare sections quickly.","zh":"移動頁面幫助作者快速看見結構並比較段落。"},{"en":"This phrase shows one advantage of working with physical paper.","zh":"這個短語顯示使用實體紙張的一項優勢。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":7},{"front":"organise and reorganise","meaning":"組織並重新整理","examples":[{"en":"The author organises and reorganises the pages.","zh":"作者組織並重新整理頁面。"},{"en":"To organise and reorganise means to arrange something and then adjust the arrangement again.","zh":"organise and reorganise 指先安排某物，然後再次調整安排。"},{"en":"A teacher may organise and reorganise lesson materials before a busy term begins.","zh":"老師可能在繁忙學期開始前組織並重新整理教材。"},{"en":"Reorganising helps people improve structure when their first arrangement does not work well.","zh":"當最初安排效果不好時，重新整理可以幫助人改善結構。"},{"en":"This phrase shows repeated ordering and adjustment.","zh":"這個短語顯示反覆排序和調整。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":7},{"front":"save and discard","meaning":"保留和捨棄","examples":[{"en":"The author saves and discards comments during revision.","zh":"作者在修訂期間保留和捨棄評語。"},{"en":"To save and discard things means to keep useful items and throw away or ignore unneeded ones.","zh":"save and discard things 指保留有用項目，並丟棄或忽略不需要的項目。"},{"en":"A student may save useful examples and discard weak ones when editing an essay.","zh":"學生修改文章時，可能保留有用例子並捨棄薄弱例子。"},{"en":"Revision requires judgement because not every comment should be accepted.","zh":"修訂需要判斷，因為不是每條評語都應接受。"},{"en":"This phrase shows selection between what is kept and what is removed.","zh":"這個短語顯示在保留與移除之間作選擇。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":7},{"front":"collaborative work process","meaning":"協作工作流程","examples":[{"en":"Without paper, this collaborative work process would be harder.","zh":"沒有紙張，這個協作工作流程會更困難。"},{"en":"A collaborative work process is a way of working in which several people contribute together.","zh":"collaborative work process 指幾個人共同貢獻的工作方式。"},{"en":"Planning a school event is a collaborative work process involving teachers, students, and parents.","zh":"籌辦學校活動是一個涉及老師、學生和家長的協作工作流程。"},{"en":"Such a process becomes harder if people cannot easily see one another’s changes.","zh":"如果人們不能容易看見彼此的修改，這種流程會變得更困難。"},{"en":"This phrase highlights teamwork within an organised task.","zh":"這個短語突出有組織任務中的團隊合作。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":7},{"front":"iterative work process","meaning":"反覆修訂的工作流程","examples":[{"en":"Writing reports is an iterative work process.","zh":"撰寫報告是一個反覆修訂的工作流程。"},{"en":"An iterative work process is a process repeated in stages, with changes made after each round.","zh":"iterative work process 指分階段重複進行、每一輪後作修改的過程。"},{"en":"Designing a poster can be iterative because students draft, receive feedback, and revise.","zh":"設計海報可以是反覆修訂的，因為學生會起草、收到回饋並修改。"},{"en":"Iterative work improves quality because each version can fix earlier weaknesses.","zh":"反覆修訂的工作可以改善質素，因為每個版本都能修正早前弱點。"},{"en":"This phrase is useful when work develops through repeated attempts.","zh":"當工作透過反覆嘗試發展時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":7},{"front":"according to","meaning":"根據","examples":[{"en":"According to Sellen and Harper, paper has unique affordances.","zh":"根據 Sellen 和 Harper 的說法，紙張有獨特的可供性。"},{"en":"According to means based on what a person, text, or source says.","zh":"according to 指基於某人、文本或來源所說。"},{"en":"According to the teacher, students should submit the essay by Friday.","zh":"根據老師的說法，學生應在星期五前提交文章。"},{"en":"In reading tests, according to the passage means answers must come from the text.","zh":"在閱讀測驗中，according to the passage 表示答案必須來自文章。"},{"en":"This phrase identifies the source of information.","zh":"這個短語指出資訊來源。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":7},{"front":"a unique set of","meaning":"一套獨特的……","examples":[{"en":"Paper has a unique set of affordances.","zh":"紙張有一套獨特的可供性。"},{"en":"A unique set of something means a special group of features that is different from others.","zh":"a unique set of something 指一組與其他事物不同的特殊特徵。"},{"en":"Each school has a unique set of strengths, problems, and traditions.","zh":"每間學校都有一套獨特的優勢、問題和傳統。"},{"en":"A unique set of features can make one tool better for some tasks than another.","zh":"一套獨特特徵可以令某工具在某些任務上比另一工具更好。"},{"en":"This phrase is useful when comparing distinctive qualities.","zh":"比較獨特質素時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":7},{"front":"affordances","meaning":"可供性；使用特性","examples":[{"en":"Paper has affordances that support certain kinds of work.","zh":"紙張有支援某些工作類型的可供性。"},{"en":"Affordances are features of an object that make certain actions possible or easier.","zh":"affordances 指物件中使某些行動成為可能或更容易的特徵。"},{"en":"A handle has the affordance of being easy to pull.","zh":"把手具有容易拉動的可供性。"},{"en":"Paper’s affordances include being easy to touch, move, mark, and spread out.","zh":"紙張的可供性包括容易觸摸、移動、標記和攤開。"},{"en":"This word is often used in design, psychology, and technology studies.","zh":"這個詞常用於設計、心理學和科技研究。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":8},{"front":"that is","meaning":"也就是說","examples":[{"en":"Affordances are qualities that permit specific kinds of uses.","zh":"可供性是容許特定用途的特質。"},{"en":"That is introduces an explanation or restatement of what has just been said.","zh":"that is 用來引出對剛才內容的解釋或重述。"},{"en":"The office is going paperless; that is, most documents will be stored online.","zh":"辦公室將會無紙化；也就是說，大部分文件會儲存在網上。"},{"en":"Writers use that is when a term may be unfamiliar and needs clarification.","zh":"當某個詞可能陌生並需要澄清時，作者會使用 that is。"},{"en":"This phrase helps make an idea clearer.","zh":"這個短語有助令想法更清楚。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":8},{"front":"permit specific kinds of uses","meaning":"容許特定用途","examples":[{"en":"Paper has qualities that permit specific kinds of uses.","zh":"紙張具有容許特定用途的特質。"},{"en":"To permit specific kinds of uses means to allow certain actions or functions.","zh":"permit specific kinds of uses 指容許某些行動或功能。"},{"en":"A whiteboard permits quick group notes during a meeting.","zh":"白板容許在會議中快速寫下小組筆記。"},{"en":"A tool’s design can permit some uses while making other uses difficult.","zh":"工具的設計可以容許某些用途，同時令其他用途變得困難。"},{"en":"This phrase explains how features make particular actions possible.","zh":"這個短語解釋特徵如何使特定行動成為可能。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":8},{"front":"tangible","meaning":"有形的；可觸摸的","examples":[{"en":"Paper is tangible and easy to handle.","zh":"紙張是有形且容易處理的。"},{"en":"Tangible means physical and able to be touched.","zh":"tangible 指實體存在、可以觸摸的。"},{"en":"A printed certificate feels more tangible than an email confirmation.","zh":"印刷證書比電郵確認信感覺更有形。"},{"en":"Tangible objects can help people remember tasks because they remain visible on a desk.","zh":"有形物件可以幫助人記住任務，因為它們留在書桌上可被看見。"},{"en":"This word contrasts physical objects with digital or abstract things.","zh":"這個詞把實體物件與數碼或抽象事物作對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":8},{"front":"pick up a document","meaning":"拿起一份文件","examples":[{"en":"We can pick up a document and flip through it quickly.","zh":"我們可以拿起一份文件並快速翻閱。"},{"en":"To pick up a document means to lift a paper document with one’s hands.","zh":"pick up a document 指用手拿起一份紙本文件。"},{"en":"A manager may pick up a document during a meeting to check a figure.","zh":"經理可能在會議中拿起一份文件來檢查數字。"},{"en":"Physical documents are easy to pass, point at, and move around.","zh":"實體文件容易傳遞、指出和移動。"},{"en":"This phrase shows the hands-on nature of paper use.","zh":"這個短語顯示使用紙張時的動手特性。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":8},{"front":"flip through","meaning":"快速翻閱","examples":[{"en":"We can flip through a paper document easily.","zh":"我們可以輕易快速翻閱紙本文件。"},{"en":"To flip through something means to turn pages quickly to get a general idea or find something.","zh":"flip through something 指快速翻頁，以大概了解或尋找某物。"},{"en":"A student may flip through a textbook before deciding which chapter to revise.","zh":"學生可能快速翻閱教科書，然後決定溫習哪一章。"},{"en":"Flipping through pages helps people scan information without reading every word.","zh":"快速翻閱頁面幫助人們掃視資訊，而不用閱讀每個字。"},{"en":"This phrase is usually used with books, magazines, notebooks, or paper files.","zh":"這個短語通常用於書籍、雜誌、筆記簿或紙本檔案。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":8},{"front":"here and there","meaning":"到處；零星地","examples":[{"en":"We can read little bits of a document here and there.","zh":"我們可以零星地閱讀文件中的小部分。"},{"en":"Here and there means in different small places or at various points.","zh":"here and there 指在不同小地方或不同位置。"},{"en":"A reader may find useful comments here and there in the margin of a draft.","zh":"讀者可能在草稿頁邊空白處到處找到有用評語。"},{"en":"Looking here and there helps people form a rough impression before deep reading.","zh":"到處看一看可以幫助人在深入閱讀前形成粗略印象。"},{"en":"This phrase suggests scattered or occasional locations.","zh":"這個短語表示分散或偶爾出現的位置。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":8},{"front":"get a sense of","meaning":"大概了解","examples":[{"en":"Readers can quickly get a sense of a paper document.","zh":"讀者可以很快大概了解一份紙本文件。"},{"en":"To get a sense of something means to form a general understanding of it.","zh":"get a sense of something 指對某事形成大致理解。"},{"en":"A student may read the headings first to get a sense of an article.","zh":"學生可能先閱讀標題，以大概了解一篇文章。"},{"en":"Getting a sense of the whole document helps people decide where to focus.","zh":"大概了解整份文件，有助人們決定把注意力放在哪裡。"},{"en":"This phrase is useful when understanding is broad rather than detailed.","zh":"當理解是概括而非詳細時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":8},{"front":"spatially flexible","meaning":"空間上靈活","examples":[{"en":"Paper is spatially flexible because it can be spread out.","zh":"紙張空間上靈活，因為它可以被攤開。"},{"en":"Spatially flexible means able to be arranged in different physical positions or layouts.","zh":"spatially flexible 指能以不同實體位置或布局排列。"},{"en":"Sticky notes are spatially flexible because people can move them around a wall.","zh":"便利貼在空間上靈活，因為人們可以在牆上移動它們。"},{"en":"Spatial flexibility helps groups compare pages, sections, and ideas at the same time.","zh":"空間靈活性幫助小組同時比較頁面、段落和想法。"},{"en":"This phrase explains why physical layout can support thinking.","zh":"這個短語解釋為何實體布局可以支援思考。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":8},{"front":"spread something out","meaning":"將某物攤開","examples":[{"en":"People can spread documents out on a desk.","zh":"人們可以把文件攤開在書桌上。"},{"en":"To spread something out means to place items over a surface with space between them.","zh":"spread something out 指把物件分散放在一個表面上，彼此之間留有空間。"},{"en":"A student may spread flashcards out on the floor before grouping them by topic.","zh":"學生可能先把詞卡攤開在地上，再按主題分類。"},{"en":"Spreading things out makes it easier to see, compare, and rearrange them.","zh":"把東西攤開會令人更容易看見、比較和重新排列它們。"},{"en":"This phrase is often used with papers, maps, clothes, or objects.","zh":"這個短語常用於紙張、地圖、衣服或物件。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":8},{"front":"arrange something in the way that suits someone best","meaning":"以最適合某人的方式排列","examples":[{"en":"Paper can be arranged in the way that suits us best.","zh":"紙張可以以最適合我們的方式排列。"},{"en":"To arrange something in the way that suits someone best means to organise it according to that person’s needs or working style.","zh":"arrange something in the way that suits someone best 指根據某人的需要或工作方式整理某物。"},{"en":"A student may arrange notes in the way that suits her best before an exam.","zh":"學生可能在考試前以最適合自己的方式排列筆記。"},{"en":"Personal arrangement can make work faster because people know where things are.","zh":"個人化排列可以令工作更快，因為人們知道東西在哪裡。"},{"en":"This phrase highlights flexibility and personal control.","zh":"這個短語突出靈活性和個人控制。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":8},{"front":"tailorable","meaning":"可按需要調整的","examples":[{"en":"Paper is tailorable because it can be annotated easily.","zh":"紙張是可按需要調整的，因為它可以容易加註。"},{"en":"Tailorable means able to be adjusted or changed to fit someone’s needs.","zh":"tailorable 指能被調整或改變，以配合某人的需要。"},{"en":"A tailorable study plan lets students choose different tasks for weak and strong areas.","zh":"可按需要調整的學習計劃讓學生為強弱項選擇不同任務。"},{"en":"Tailorable tools are useful because different users do not all work in the same way.","zh":"可按需要調整的工具很有用，因為不同使用者工作方式不全相同。"},{"en":"This word describes flexibility and customisation.","zh":"這個詞描述靈活性和客製化。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":9},{"front":"annotate","meaning":"加註；作註釋","examples":[{"en":"Readers can annotate paper documents easily.","zh":"讀者可以容易地在紙本文件上加註。"},{"en":"To annotate means to add notes, comments, explanations, or marks to a text.","zh":"annotate 指在文本上加入筆記、評語、解釋或標記。"},{"en":"Students annotate a reading passage by underlining key words and writing questions beside them.","zh":"學生透過畫底線標出關鍵詞並在旁邊寫問題，來為閱讀文章作註釋。"},{"en":"Annotation helps readers remember ideas and prepare for discussion.","zh":"註釋幫助讀者記住想法並準備討論。"},{"en":"This verb is common in reading, editing, and academic work.","zh":"這個動詞常見於閱讀、編輯和學術工作。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":9},{"front":"scribble on","meaning":"在……上隨手寫","examples":[{"en":"People can scribble on paper as they read.","zh":"人們閱讀時可以在紙上隨手寫。"},{"en":"To scribble on something means to write quickly and roughly on its surface.","zh":"scribble on something 指快速而粗略地寫在某物表面上。"},{"en":"A child may scribble on a notebook while thinking of story ideas.","zh":"孩子構思故事時可能在筆記簿上隨手寫。"},{"en":"Scribbling is useful for quick thoughts, but it may look messy to others.","zh":"隨手寫對快速想法有用，但在別人眼中可能很凌亂。"},{"en":"This phrase suggests informal, fast writing.","zh":"這個短語表示非正式而快速的書寫。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":9},{"front":"without altering the original text","meaning":"不改動原文","examples":[{"en":"Readers can annotate a draft without altering the original text.","zh":"讀者可以在草稿上加註，而不改動原文。"},{"en":"Without altering the original text means adding comments while leaving the main words unchanged.","zh":"without altering the original text 指加入評語，但保持主要文字不變。"},{"en":"A teacher can mark an essay without altering the original text by writing notes in the margin.","zh":"老師可以在頁邊空白處寫筆記來批改文章，而不改動原文。"},{"en":"This helps writers see feedback without losing their own draft.","zh":"這幫助作者看到回饋，同時不失去自己的草稿。"},{"en":"This phrase is useful when separating comments from the main document.","zh":"當需要把評語與主文件分開時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":9},{"front":"digital documents","meaning":"數碼文件","examples":[{"en":"Digital documents have their own affordances.","zh":"數碼文件有其自身的可供性。"},{"en":"Digital documents are files that can be read, edited, stored, or shared on electronic devices.","zh":"digital documents 指可在電子裝置上閱讀、編輯、儲存或分享的檔案。"},{"en":"A company may store contracts as digital documents in a secure cloud folder.","zh":"公司可能把合約作為數碼文件儲存在安全的雲端資料夾中。"},{"en":"Digital documents are easy to search, but they may be harder to spread across a table.","zh":"數碼文件容易搜尋，但可能較難攤開在桌面上。"},{"en":"This phrase contrasts electronic files with physical paper documents.","zh":"這個短語把電子檔案與實體紙本文件作對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":9},{"front":"be easily searched","meaning":"容易被搜尋","examples":[{"en":"Digital documents can be easily searched.","zh":"數碼文件容易被搜尋。"},{"en":"To be easily searched means information can be found quickly using keywords or search tools.","zh":"be easily searched 指可以使用關鍵詞或搜尋工具快速找到資訊。"},{"en":"A long PDF is useful when it can be easily searched for names and dates.","zh":"如果長 PDF 可以容易搜尋姓名和日期，它就很有用。"},{"en":"Searchable documents save time because readers do not need to scan every page.","zh":"可搜尋文件節省時間，因為讀者不需要逐頁掃讀。"},{"en":"This phrase highlights one major advantage of digital files.","zh":"這個短語突出數碼檔案的一大優勢。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":9},{"front":"be easily shared","meaning":"容易被分享","examples":[{"en":"Digital documents can be easily shared.","zh":"數碼文件容易被分享。"},{"en":"To be easily shared means a file can be sent or given to others with little effort.","zh":"be easily shared 指檔案可以輕易被發送或交給他人。"},{"en":"A teacher can easily share worksheets with students through an online classroom.","zh":"老師可以透過網上課室輕易與學生分享工作紙。"},{"en":"Easy sharing helps teams work together even when members are in different places.","zh":"容易分享有助團隊合作，即使成員身處不同地方。"},{"en":"This phrase shows an advantage of digital communication.","zh":"這個短語顯示數碼溝通的一項優勢。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":9},{"front":"be easily stored","meaning":"容易被儲存","examples":[{"en":"Digital documents can be easily stored.","zh":"數碼文件容易被儲存。"},{"en":"To be easily stored means files can be kept safely without taking much physical space.","zh":"be easily stored 指檔案可以安全保存，而不佔用太多實體空間。"},{"en":"A family can store old photos digitally instead of keeping many boxes.","zh":"家庭可以以數碼方式儲存舊照片，而不是保留許多盒子。"},{"en":"Easy storage reduces clutter, but files still need clear names and backups.","zh":"容易儲存可以減少雜亂，但檔案仍需要清楚命名和備份。"},{"en":"This phrase is useful when comparing digital files with paper documents.","zh":"比較數碼檔案和紙本文件時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":9},{"front":"accessed remotely","meaning":"可遙距存取","examples":[{"en":"Digital documents can be accessed remotely.","zh":"數碼文件可遙距存取。"},{"en":"Accessed remotely means opened or used from another place through the internet or a network.","zh":"accessed remotely 指透過互聯網或網絡在另一地方打開或使用。"},{"en":"A worker can access office files remotely while working from home.","zh":"員工在家工作時可以遙距存取辦公室文件。"},{"en":"Remote access helps flexible work, but it may require strong security.","zh":"遙距存取有助彈性工作，但可能需要強大保安。"},{"en":"This phrase is common in digital work and online storage.","zh":"這個短語常見於數碼工作和網上儲存。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":9},{"front":"linked to","meaning":"與……連結","examples":[{"en":"Digital documents can be linked to other relevant material.","zh":"數碼文件可以與其他相關材料連結。"},{"en":"Linked to something means connected with it, often through a digital link or relationship.","zh":"linked to something 指與某物連接，常透過數碼連結或關係。"},{"en":"An online article may be linked to videos, charts, and source documents.","zh":"網上文章可能連結到影片、圖表和來源文件。"},{"en":"Links help readers move quickly from one piece of information to another.","zh":"連結幫助讀者快速從一項資料轉到另一項資料。"},{"en":"This phrase is useful for both digital connections and general relationships.","zh":"這個短語既可用於數碼連接，也可用於一般關係。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":9},{"front":"relevant material","meaning":"相關材料","examples":[{"en":"Digital files can be linked to relevant material.","zh":"數碼檔案可以連結到相關材料。"},{"en":"Relevant material is information, evidence, or content directly connected to the topic.","zh":"relevant material 指與主題直接有關的資料、證據或內容。"},{"en":"A student writing about pollution should collect relevant material such as data and case studies.","zh":"寫污染題目的學生應收集相關材料，例如數據和個案研究。"},{"en":"Using relevant material makes an argument clearer and more convincing.","zh":"使用相關材料可以令論點更清楚和更有說服力。"},{"en":"This phrase contrasts useful supporting information with unrelated details.","zh":"這個短語把有用的支持資料與無關細節作對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":9},{"front":"lack the affordances","meaning":"缺乏某些使用特性","examples":[{"en":"Digital documents may lack the affordances needed for group work.","zh":"數碼文件可能缺乏小組工作所需的某些使用特性。"},{"en":"To lack the affordances means not to have the features that make certain actions easy or possible.","zh":"lack the affordances 指沒有使某些行動容易或可能的特徵。"},{"en":"A small phone screen may lack the affordances needed for comparing long documents.","zh":"小手機屏幕可能缺乏比較長文件所需的使用特性。"},{"en":"If a tool lacks key affordances, people may return to an older tool.","zh":"如果工具缺乏關鍵使用特性，人們可能回到舊工具。"},{"en":"This phrase explains why a newer technology may not suit every task.","zh":"這個短語解釋為何較新科技未必適合每項任務。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":10},{"front":"really matter to","meaning":"對……真正重要","examples":[{"en":"Some paper affordances really matter to people working together.","zh":"某些紙張可供性對共同工作的人真正重要。"},{"en":"To really matter to someone means to be genuinely important to them.","zh":"really matter to someone 指對某人真正重要。"},{"en":"Clear feedback really matters to students who want to improve quickly.","zh":"清楚回饋對想快速進步的學生真正重要。"},{"en":"A feature may seem small but really matter when people use it every day.","zh":"一項功能可能看似細小，但當人們每天使用時，它會真正重要。"},{"en":"This phrase stresses practical importance.","zh":"這個短語強調實際重要性。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":10},{"front":"working together on","meaning":"共同處理……","examples":[{"en":"A group of people may work together on a report.","zh":"一群人可能共同處理一份報告。"},{"en":"Working together on something means cooperating to complete the same task or project.","zh":"working together on something 指合作完成同一任務或項目。"},{"en":"Students working together on a presentation must divide research and speaking parts.","zh":"共同處理匯報的學生必須分配研究和發言部分。"},{"en":"Working together can improve ideas, but it requires communication and trust.","zh":"共同工作可以改善想法，但需要溝通和信任。"},{"en":"This phrase focuses on shared effort toward one goal.","zh":"這個短語聚焦朝同一目標作出的共同努力。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":10},{"front":"physical embodiment of information","meaning":"資料的實體呈現","examples":[{"en":"Paper is a physical embodiment of information.","zh":"紙張是資料的實體呈現。"},{"en":"A physical embodiment of information is a real object that carries or represents information.","zh":"physical embodiment of information 指承載或代表資訊的真實物件。"},{"en":"A printed timetable is a physical embodiment of transport information.","zh":"印刷時間表是交通資訊的實體呈現。"},{"en":"Because information is embodied in paper, people can point at it, move it, and share it visibly.","zh":"因為資訊體現在紙張中，人們可以指着它、移動它並可見地分享它。"},{"en":"This phrase contrasts physical information with invisible digital data on a screen.","zh":"這個短語把實體資訊與屏幕上看不見的數碼資料作對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":10},{"front":"in relation to","meaning":"關於；就……而言","examples":[{"en":"Actions performed in relation to paper are visible to colleagues.","zh":"就紙張而言所進行的動作，對同事是可見的。"},{"en":"In relation to something means connected with or concerning that thing.","zh":"in relation to something 指與某事有關或關於某事。"},{"en":"A teacher may discuss mistakes in relation to grammar, vocabulary, and organisation.","zh":"老師可能就文法、詞彙和組織討論錯誤。"},{"en":"Looking at actions in relation to paper shows how physical objects support communication.","zh":"就紙張而言觀察行動，可以顯示實體物件如何支援溝通。"},{"en":"This phrase is formal and useful for explaining connections.","zh":"這個短語較正式，適合解釋關係。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":10},{"front":"to a large extent","meaning":"在很大程度上","examples":[{"en":"Paper-based actions are, to a large extent, visible to others.","zh":"紙本行動在很大程度上對他人可見。"},{"en":"To a large extent means mostly or in a major way.","zh":"to a large extent 指大部分或在很大程度上。"},{"en":"A student’s success depends, to a large extent, on regular practice.","zh":"學生的成功在很大程度上取決於規律練習。"},{"en":"If work is visible to a large extent, team members can coordinate more easily.","zh":"如果工作在很大程度上可見，團隊成員可以更容易協調。"},{"en":"This phrase allows a careful claim without saying something is completely true.","zh":"這個短語可以作出謹慎說法，而不是說某事完全成立。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":10},{"front":"made visible to","meaning":"讓……看得見","examples":[{"en":"Actions on paper are made visible to colleagues.","zh":"紙上的行動讓同事看得見。"},{"en":"To be made visible to someone means to be shown or made easy for them to see.","zh":"made visible to someone 指被展示或變得容易讓某人看見。"},{"en":"A project board makes tasks visible to the whole team.","zh":"項目板讓整個團隊看得見任務。"},{"en":"When work is made visible, people can notice progress, delay, and responsibility.","zh":"當工作變得可見，人們可以注意到進度、延誤和責任。"},{"en":"This phrase is useful when discussing transparency and coordination.","zh":"討論透明度和協調時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":10},{"front":"sitting around a desk","meaning":"圍坐在書桌旁","examples":[{"en":"Reviewers sitting around a desk can see one another’s actions.","zh":"圍坐在書桌旁的審閱者可以看見彼此的動作。"},{"en":"Sitting around a desk means several people are seated near the same desk or table.","zh":"sitting around a desk 指幾個人坐在同一張書桌或桌子附近。"},{"en":"Students sitting around a desk can share notes and discuss a problem together.","zh":"圍坐在書桌旁的學生可以分享筆記並一起討論問題。"},{"en":"Sitting together makes gestures, page-turning, and pointing easier to see.","zh":"坐在一起令手勢、翻頁和指示更容易看見。"},{"en":"This phrase suggests close, face-to-face group work.","zh":"這個短語暗示近距離、面對面的小組工作。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":10},{"front":"turn toward","meaning":"轉向","examples":[{"en":"A colleague may turn toward a report during discussion.","zh":"同事在討論期間可能轉向一份報告。"},{"en":"To turn toward something means to move one’s body or attention in its direction.","zh":"turn toward something 指把身體或注意力移向某物的方向。"},{"en":"A student may turn toward the board when the teacher explains a diagram.","zh":"老師解釋圖表時，學生可能轉向黑板。"},{"en":"Turning toward a document can show others what a person is focusing on.","zh":"轉向文件可以向他人顯示某人正在專注甚麼。"},{"en":"This phrase describes both physical movement and attention.","zh":"這個短語同時描述身體動作和注意力。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":10},{"front":"turn away from","meaning":"轉離","examples":[{"en":"A colleague may turn away from a report.","zh":"同事可能轉離一份報告。"},{"en":"To turn away from something means to move one’s body or attention away from it.","zh":"turn away from something 指把身體或注意力從某物移開。"},{"en":"A student may turn away from the screen when the discussion moves to printed notes.","zh":"當討論轉到印刷筆記時，學生可能從屏幕轉離。"},{"en":"Turning away can signal that someone is finished with a topic or no longer focused on it.","zh":"轉離可以表示某人已完成某主題或不再專注於它。"},{"en":"This phrase is the opposite of turn toward.","zh":"這個短語與 turn toward 相反。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":10},{"front":"flick through","meaning":"快速翻閱","examples":[{"en":"A reviewer may flick through a report quickly.","zh":"審閱者可能快速翻閱一份報告。"},{"en":"To flick through something means to turn pages quickly and lightly.","zh":"flick through something 指快速而輕地翻頁。"},{"en":"A shopper may flick through a magazine before deciding whether to buy it.","zh":"顧客可能快速翻閱一本雜誌，然後決定是否購買。"},{"en":"Flicking through a document helps people find sections without reading every page carefully.","zh":"快速翻閱文件幫助人們找到段落，而不用仔細閱讀每一頁。"},{"en":"This phrase is similar to flip through and usually refers to paper pages.","zh":"這個短語與 flip through 相似，通常指紙本頁面。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":10},{"front":"set something aside","meaning":"將某物放到一旁","examples":[{"en":"A reviewer may set a report aside.","zh":"審閱者可能把一份報告放到一旁。"},{"en":"To set something aside means to put it to one side, often for later use or to show it is not the current focus.","zh":"set something aside 指把某物放到一邊，常為了之後使用或表示它不是當前焦點。"},{"en":"A student may set aside difficult notes and return to them after revising easier topics.","zh":"學生可能把困難筆記放到一旁，先溫習較容易主題後再回來處理。"},{"en":"Setting papers aside helps people sort urgent items from less urgent ones.","zh":"把紙張放到一旁有助人們把緊急項目與較不緊急項目分開。"},{"en":"This phrase can refer to physical objects or time.","zh":"這個短語可以指實體物件，也可以指時間。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":11},{"front":"contrast this with","meaning":"將此與……作比較","examples":[{"en":"Contrast this with watching someone look at a laptop.","zh":"將此與觀看某人看手提電腦作比較。"},{"en":"Contrast this with something means compare it with something different to show a clear difference.","zh":"contrast this with something 指把這件事與另一不同事物比較，以顯示清楚差異。"},{"en":"Contrast handwritten feedback with typed feedback to see how each affects revision.","zh":"將手寫回饋與打字回饋作比較，以了解兩者如何影響修訂。"},{"en":"Contrasting two tools helps people understand their strengths and weaknesses.","zh":"比較兩種工具有助人們理解各自的優點和弱點。"},{"en":"This phrase is useful in comparison and analysis.","zh":"這個短語在比較和分析中很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":11},{"front":"across a desk","meaning":"隔着書桌","examples":[{"en":"It is harder to see what someone is doing across a desk.","zh":"隔着書桌較難看見某人在做甚麼。"},{"en":"Across a desk means on the other side of a desk from another person.","zh":"across a desk 指在書桌另一邊、與另一人相對的位置。"},{"en":"A manager sitting across a desk may not see exactly what is on an employee’s laptop screen.","zh":"隔着書桌坐着的經理，可能看不清員工手提電腦屏幕上的內容。"},{"en":"Distance across a desk can make small actions less visible.","zh":"隔着書桌的距離可能令細小動作不太可見。"},{"en":"This phrase describes physical position in a face-to-face setting.","zh":"這個短語描述面對面情境中的實體位置。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":11},{"front":"look at a document on a laptop","meaning":"在手提電腦上看文件","examples":[{"en":"It is difficult to know where someone is looking in a document on a laptop.","zh":"很難知道某人在手提電腦上的文件中看哪裡。"},{"en":"To look at a document on a laptop means to read or review a file on a laptop screen.","zh":"look at a document on a laptop 指在手提電腦屏幕上閱讀或審閱檔案。"},{"en":"During a meeting, one person may look at a document on a laptop while others cannot see the exact page.","zh":"會議期間，一個人可能在手提電腦上看文件，而其他人看不到確切頁面。"},{"en":"This can make group discussion harder because attention is less visible.","zh":"這可能令小組討論更困難，因為注意力較不明顯。"},{"en":"The phrase contrasts screen-based reading with shared paper documents.","zh":"這個短語把屏幕閱讀與共享紙本文件作對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":11},{"front":"coordinate discussions","meaning":"協調討論","examples":[{"en":"Visible actions help a group coordinate its discussions.","zh":"可見的動作幫助小組協調討論。"},{"en":"To coordinate discussions means to organise conversation so people know what is being discussed and when to speak.","zh":"coordinate discussions 指組織對話，使人們知道正在討論甚麼以及何時發言。"},{"en":"A meeting chair coordinates discussions by keeping everyone on the same topic.","zh":"會議主席透過讓大家保持在同一主題上來協調討論。"},{"en":"Clear coordination prevents people from talking about different pages or problems at the same time.","zh":"清楚協調可以防止人們同時談論不同頁面或問題。"},{"en":"This phrase is useful for teamwork and meetings.","zh":"這個短語適用於團隊合作和會議。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":11},{"front":"reach a shared understanding","meaning":"達成共同理解","examples":[{"en":"Paper helps a group reach a shared understanding.","zh":"紙張幫助小組達成共同理解。"},{"en":"To reach a shared understanding means to arrive at the same basic view of a situation or issue.","zh":"reach a shared understanding 指對某情況或問題形成相同的基本看法。"},{"en":"A project team reaches a shared understanding when everyone agrees on the deadline and main tasks.","zh":"當項目團隊人人同意截止日期和主要任務時，就達成共同理解。"},{"en":"Shared understanding reduces mistakes because people are less likely to work from different assumptions.","zh":"共同理解可以減少錯誤，因為人們較不可能基於不同假設工作。"},{"en":"This phrase is important in collaboration and communication.","zh":"這個短語在協作和溝通中很重要。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":11},{"front":"what is being discussed","meaning":"正在討論的內容","examples":[{"en":"Paper helps people understand what is being discussed.","zh":"紙張幫助人們理解正在討論的內容。"},{"en":"What is being discussed means the exact topic, page, issue, or point currently under conversation.","zh":"what is being discussed 指當前對話中的確切主題、頁面、問題或重點。"},{"en":"In a meeting, pointing at a printed chart helps everyone know what is being discussed.","zh":"在會議中，指着印刷圖表可以幫助每個人知道正在討論的內容。"},{"en":"If people are unsure what is being discussed, decisions become confused.","zh":"如果人們不確定正在討論甚麼，決策會變得混亂。"},{"en":"This phrase refers to the current focus of a conversation.","zh":"這個短語指對話中的當前焦點。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":11},{"front":"enable a certain kind of thinking","meaning":"促成某種思考方式","examples":[{"en":"Paper enables a certain kind of thinking.","zh":"紙張促成某種思考方式。"},{"en":"To enable a certain kind of thinking means to make a particular mental process easier or possible.","zh":"enable a certain kind of thinking 指使某種心智過程更容易或成為可能。"},{"en":"A mind map can enable creative thinking by showing links between ideas.","zh":"思維導圖可以透過展示想法之間的連繫來促成創意思考。"},{"en":"Paper may enable spatial thinking because pages can be spread out and rearranged.","zh":"紙張可能促成空間思考，因為頁面可以被攤開和重新排列。"},{"en":"This phrase connects a tool with the way people think.","zh":"這個短語把工具與人的思考方式連接起來。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":11},{"front":"picture the top of","meaning":"想像……的表面","examples":[{"en":"Picture the top of your desk.","zh":"想像你書桌的表面。"},{"en":"To picture the top of something means to imagine what its upper surface looks like.","zh":"picture the top of something 指想像某物上方表面的樣子。"},{"en":"Picture the top of your school bag and think about what you see first.","zh":"想像你書包的表面，想想你首先看見甚麼。"},{"en":"Imagining a surface helps readers understand the physical arrangement being described.","zh":"想像一個表面有助讀者理解被描述的實體排列。"},{"en":"This phrase invites the reader to visualise a scene.","zh":"這個短語邀請讀者在腦中形成畫面。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":11},{"front":"chances are that","meaning":"很可能","examples":[{"en":"Chances are that you have a computer screen on one side of your desk.","zh":"很可能你的書桌一邊有一個電腦屏幕。"},{"en":"Chances are that means it is likely that something is true.","zh":"chances are that 表示某事很可能是真的。"},{"en":"Chances are that students will forget details if they do not review soon.","zh":"如果學生不盡快溫習，他們很可能會忘記細節。"},{"en":"Writers use this phrase when making a reasonable guess about common experience.","zh":"作者在對常見經驗作合理推測時，會使用這個短語。"},{"en":"This phrase is less certain than definitely.","zh":"這個短語沒有 definitely 那麼肯定。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":11},{"front":"off to one side","meaning":"放在一旁","examples":[{"en":"The keyboard and computer screen may be off to one side.","zh":"鍵盤和電腦屏幕可能放在一旁。"},{"en":"Off to one side means placed away from the central area, toward the left or right.","zh":"off to one side 指放在離中央位置較遠的左邊或右邊。"},{"en":"A teacher may keep extra worksheets off to one side of the desk.","zh":"老師可能把額外工作紙放在書桌一旁。"},{"en":"Items placed off to one side are still available but not the main focus.","zh":"放在一旁的物件仍然可用，但不是主要焦點。"},{"en":"This phrase describes physical position.","zh":"這個短語描述實體位置。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":11},{"front":"a clear space","meaning":"一片清空的空間","examples":[{"en":"Most desks have a clear space in front of the chair.","zh":"大多數書桌在椅子前方都有一片清空的空間。"},{"en":"A clear space is an empty area without clutter, used for working or placing things.","zh":"a clear space 指沒有雜物、可用來工作或放置物件的空位。"},{"en":"A student may keep a clear space on the desk for writing homework.","zh":"學生可能在書桌上保留一片清空的空間來寫功課。"},{"en":"Clear space helps people focus because they have room to read, write, and sort papers.","zh":"清空的空間幫助人專注，因為他們有地方閱讀、書寫和整理紙張。"},{"en":"This phrase refers to useful empty space, not wasted space.","zh":"這個短語指有用的空位，而不是浪費空間。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":12},{"front":"roughly eighteen inches square","meaning":"大約18吋見方","examples":[{"en":"The clear space is roughly eighteen inches square.","zh":"那片清空空間大約18吋見方。"},{"en":"Roughly eighteen inches square means about eighteen inches long and eighteen inches wide.","zh":"roughly eighteen inches square 指長和闊大約都是18吋。"},{"en":"A small writing area may be roughly eighteen inches square on a crowded desk.","zh":"在擁擠書桌上，一小片書寫區可能大約18吋見方。"},{"en":"Giving an approximate size helps readers picture the space more clearly.","zh":"提供大約尺寸有助讀者更清楚想像空間。"},{"en":"This phrase describes measurement without needing exact precision.","zh":"這個短語描述尺寸，但不需要完全精確。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":12},{"front":"in front of","meaning":"在……前面","examples":[{"en":"There is usually a clear space in front of the chair.","zh":"椅子前面通常有一片清空的空間。"},{"en":"In front of means positioned before or facing the front side of something.","zh":"in front of 指位於某物前方或面向其前面的位置。"},{"en":"Students line up in front of the classroom before the lesson begins.","zh":"上課前，學生在課室前面排隊。"},{"en":"Objects placed in front of a person are easy to see and reach.","zh":"放在某人前面的物件容易看見和拿到。"},{"en":"This phrase is basic but important for describing location.","zh":"這個短語很基礎，但對描述位置很重要。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":12},{"front":"the rest of the desktop","meaning":"書桌其餘位置","examples":[{"en":"The rest of the desktop may be covered with piles.","zh":"書桌其餘位置可能被紙堆覆蓋。"},{"en":"The rest of the desktop means the remaining area on the surface of the desk.","zh":"the rest of the desktop 指書桌表面上剩下的區域。"},{"en":"A student may keep one clear corner for writing and leave the rest of the desktop for books.","zh":"學生可能保留一個清空角落寫字，並把書桌其餘位置留給書本。"},{"en":"If the rest of the desktop is crowded, only a small working area remains.","zh":"如果書桌其餘位置很擁擠，就只剩下一小片工作區。"},{"en":"This phrase divides a space into one part and everything else.","zh":"這個短語把空間分成某一部分和其他全部部分。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":12},{"front":"piles of","meaning":"一堆堆……","examples":[{"en":"The desktop may be covered with piles of papers and magazines.","zh":"書桌表面可能被一堆堆紙張和雜誌覆蓋。"},{"en":"Piles of something are stacks or groups of things placed on top of one another.","zh":"piles of something 指一疊疊或一堆堆互相重疊的東西。"},{"en":"A teacher may have piles of homework to mark after exams.","zh":"考試後，老師可能有一堆堆功課要批改。"},{"en":"Piles of paper can look messy, but they may contain a hidden order.","zh":"一堆堆紙張可能看似凌亂，但可能包含隱藏秩序。"},{"en":"This phrase usually suggests a large quantity arranged in stacks.","zh":"這個短語通常表示大量東西堆成一疊疊。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":12},{"front":"journals and magazines","meaning":"期刊和雜誌","examples":[{"en":"Piles may contain journals and magazines.","zh":"紙堆可能包含期刊和雜誌。"},{"en":"Journals and magazines are printed publications that contain articles, reports, or features.","zh":"journals and magazines 指載有文章、報告或專題內容的印刷出版物。"},{"en":"A library may keep journals and magazines for students doing research.","zh":"圖書館可能保存期刊和雜誌，供做研究的學生使用。"},{"en":"These materials can create clutter if readers keep them after they are no longer needed.","zh":"如果讀者在不再需要後仍保留它們，這些材料可能造成雜亂。"},{"en":"This phrase often refers to periodical reading materials.","zh":"這個短語常指期刊類閱讀材料。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":12},{"front":"binders","meaning":"活頁夾","examples":[{"en":"Office workers may keep binders on their desks.","zh":"辦公室職員可能在書桌上放活頁夾。"},{"en":"Binders are folders with rings or clips used to hold and organise papers.","zh":"binders 指用環或夾固定並整理紙張的文件夾。"},{"en":"A student may use binders to separate notes by subject.","zh":"學生可能用活頁夾按科目分開筆記。"},{"en":"Binders help keep documents in order, but too many binders can fill a desk quickly.","zh":"活頁夾有助保持文件有序，但太多活頁夾會很快佔滿書桌。"},{"en":"This word refers to a physical tool for organising paper.","zh":"這個詞指整理紙張的實體工具。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":12},{"front":"postcards","meaning":"明信片","examples":[{"en":"Postcards may become part of the piles on a desk.","zh":"明信片可能成為書桌上紙堆的一部分。"},{"en":"Postcards are small cards with a picture on one side, often sent by mail without an envelope.","zh":"postcards 指一面有圖像的小卡片，常不放進信封就郵寄。"},{"en":"A traveller may send postcards to friends while visiting another country.","zh":"旅客到訪另一個國家時，可能寄明信片給朋友。"},{"en":"Postcards can become reminders of people, places, events, or unfinished replies.","zh":"明信片可以成為人物、地方、事件或未回覆訊息的提醒。"},{"en":"This word refers to both a message card and a small personal object.","zh":"這個詞既指訊息卡，也指小型個人物件。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":12},{"front":"artefacts of the knowledge economy","meaning":"知識經濟的產物","examples":[{"en":"The desk is covered with artefacts of the knowledge economy.","zh":"書桌被知識經濟的產物覆蓋。"},{"en":"Artefacts of the knowledge economy are objects produced or used in work based on information, ideas, and expertise.","zh":"artefacts of the knowledge economy 指在以資訊、想法和專業知識為基礎的工作中產生或使用的物件。"},{"en":"Reports, journals, notes, and manuals can be artefacts of the knowledge economy.","zh":"報告、期刊、筆記和手冊都可以是知識經濟的產物。"},{"en":"These artefacts appear when people create, organise, and exchange knowledge for work.","zh":"當人們為工作創造、整理和交換知識時，這些產物就會出現。"},{"en":"This phrase makes ordinary office objects sound like evidence of modern knowledge work.","zh":"這個短語把普通辦公室物件說成現代知識工作的證據。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":12},{"front":"look like a mess","meaning":"看似一團糟","examples":[{"en":"The piles look like a mess, but they usually have meaning.","zh":"這些紙堆看似一團糟，但通常有其意義。"},{"en":"To look like a mess means to appear untidy, confused, or badly organised.","zh":"look like a mess 指看起來不整齊、混亂或組織不良。"},{"en":"A student’s desk may look like a mess during project week.","zh":"在項目週期間，學生的書桌可能看似一團糟。"},{"en":"Something can look messy to outsiders but still make sense to the person using it.","zh":"某物對外人來說可能看似凌亂，但對使用者仍然合理。"},{"en":"This phrase describes appearance, not always reality.","zh":"這個短語描述外觀，不一定描述現實。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":12},{"front":"piling behaviour","meaning":"堆放行為","examples":[{"en":"Researchers studied piling behaviour among office workers.","zh":"研究人員研究辦公室職員的堆放行為。"},{"en":"Piling behaviour is the habit of placing papers and materials in stacks rather than filing them away immediately.","zh":"piling behaviour 指把紙張和材料堆成一疊，而不是立即歸檔的習慣。"},{"en":"A teacher’s piling behaviour may show which assignments need urgent marking.","zh":"老師的堆放行為可能顯示哪些功課需要緊急批改。"},{"en":"Piling can help people keep active tasks visible, but it can also create clutter.","zh":"堆放可以幫助人保持現行任務可見，但也可能造成雜亂。"},{"en":"This phrase describes how people organise work physically.","zh":"這個短語描述人們如何實體地整理工作。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":12},{"front":"disorderly piles","meaning":"凌亂的紙堆","examples":[{"en":"Even disorderly piles may make sense to the person who created them.","zh":"即使凌亂的紙堆，對創造它們的人來說也可能合理。"},{"en":"Disorderly piles are stacks that look messy or not clearly arranged.","zh":"disorderly piles 指看起來凌亂或沒有清楚排列的一疊疊東西。"},{"en":"A student may have disorderly piles of notes on the floor before sorting them by subject.","zh":"學生在按科目整理前，可能在地上放着凌亂的筆記堆。"},{"en":"Disorderly piles can hide an internal logic known only to the owner.","zh":"凌亂的紙堆可能隱藏只有主人知道的內在邏輯。"},{"en":"This phrase contrasts outward mess with possible personal order.","zh":"這個短語把外在凌亂與可能存在的個人秩序作對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":13},{"front":"make perfect sense to","meaning":"對……來說完全合理","examples":[{"en":"The piles make perfect sense to the piler.","zh":"這些紙堆對堆放者來說完全合理。"},{"en":"To make perfect sense to someone means to be completely clear or logical to that person.","zh":"make perfect sense to someone 指對某人來說完全清楚或合乎邏輯。"},{"en":"A colour-coded notebook may make perfect sense to the student who designed it.","zh":"一本用顏色分類的筆記簿可能對設計它的學生來說完全合理。"},{"en":"Something may make sense to its owner even if outsiders find it confusing.","zh":"某物即使令外人困惑，對主人來說也可能合理。"},{"en":"This phrase shows personal understanding or internal logic.","zh":"這個短語顯示個人理解或內在邏輯。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":13},{"front":"office workers","meaning":"辦公室職員","examples":[{"en":"Office workers can explain the meaning of their piles.","zh":"辦公室職員可以解釋自己紙堆的意義。"},{"en":"Office workers are people who do administrative, professional, or clerical work in an office.","zh":"office workers 指在辦公室做行政、專業或文書工作的人。"},{"en":"Office workers may write emails, attend meetings, prepare documents, and manage records.","zh":"辦公室職員可能寫電郵、開會、準備文件和管理記錄。"},{"en":"Their desks often show what tasks are urgent, unfinished, or waiting for approval.","zh":"他們的書桌常顯示哪些任務緊急、未完成或等待批准。"},{"en":"This phrase refers to workers in an office environment.","zh":"這個短語指辦公室環境中的工作者。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":13},{"front":"hold forth in great detail about","meaning":"詳細滔滔不絕地談論","examples":[{"en":"Office workers can hold forth in great detail about their piles.","zh":"辦公室職員可以詳細滔滔不絕地談論自己的紙堆。"},{"en":"To hold forth in great detail about something means to speak at length and with much explanation about it.","zh":"hold forth in great detail about something 指長篇而詳細地談論某事。"},{"en":"A teacher may hold forth in great detail about why a student’s essay structure works.","zh":"老師可能詳細滔滔不絕地談論為何學生的文章結構有效。"},{"en":"People can explain their own systems in detail even when those systems look messy to others.","zh":"即使自己的系統對別人來說看似凌亂，人們仍能詳細解釋它。"},{"en":"This phrase often suggests confident, extended explanation.","zh":"這個短語常表示自信而長時間的解釋。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":13},{"front":"precise history and meaning","meaning":"精確的歷史和含義","examples":[{"en":"Workers know the precise history and meaning of their piles.","zh":"職員知道自己紙堆的精確歷史和含義。"},{"en":"Precise history and meaning means the exact origin, development, and purpose of something.","zh":"precise history and meaning 指某事物的確切來源、發展和目的。"},{"en":"A student may know the precise history and meaning of every sticky note on her desk.","zh":"學生可能知道她書桌上每張便利貼的精確歷史和含義。"},{"en":"Knowing this background helps people use messy-looking materials without confusion.","zh":"了解這些背景有助人們使用看似凌亂的材料而不感混亂。"},{"en":"This phrase stresses exact personal knowledge.","zh":"這個短語強調精確的個人知識。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":13},{"front":"the pile closest to","meaning":"最接近……的一堆","examples":[{"en":"The pile closest to the working area usually contains urgent work.","zh":"最接近工作區的一堆通常包含緊急工作。"},{"en":"The pile closest to something means the stack located nearest to that place.","zh":"the pile closest to something 指距離某位置最近的一疊東西。"},{"en":"A teacher may keep the pile closest to her chair for papers that must be marked today.","zh":"老師可能把最接近椅子的一堆留給今天必須批改的作業。"},{"en":"Nearness can signal importance because the worker can reach the pile quickly.","zh":"接近可以表示重要性，因為工作者能快速拿到那堆東西。"},{"en":"This phrase describes physical location and possible priority.","zh":"這個短語描述實體位置和可能的優先次序。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":13},{"front":"working area","meaning":"工作區","examples":[{"en":"The most urgent pile is usually closest to the working area.","zh":"最緊急的一堆通常最接近工作區。"},{"en":"A working area is the space where someone actively reads, writes, sorts, or completes tasks.","zh":"working area 指某人主動閱讀、書寫、分類或完成任務的空間。"},{"en":"A student may keep pens and current notes inside the working area of the desk.","zh":"學生可能把筆和正在使用的筆記放在書桌工作區內。"},{"en":"A clear working area helps people start tasks without first moving many objects.","zh":"清晰工作區讓人不用先移動很多物件就能開始工作。"},{"en":"This phrase refers to the active part of a workspace.","zh":"這個短語指工作空間中正在使用的部分。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":13},{"front":"urgent business","meaning":"緊急事務","examples":[{"en":"The closest pile often represents the most urgent business.","zh":"最接近的一堆通常代表最緊急的事務。"},{"en":"Urgent business means work or matters that need quick attention.","zh":"urgent business 指需要迅速處理的工作或事情。"},{"en":"A manager may handle urgent business before reading routine emails.","zh":"經理可能先處理緊急事務，然後才閱讀日常電郵。"},{"en":"If urgent business is ignored, deadlines may be missed or problems may worsen.","zh":"如果緊急事務被忽視，可能錯過截止日期或令問題惡化。"},{"en":"This phrase is formal and often used in work contexts.","zh":"這個短語較正式，常用於工作語境。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":13},{"front":"be likely to","meaning":"很可能","examples":[{"en":"The most important document is likely to be at the top.","zh":"最重要的文件很可能在頂部。"},{"en":"Be likely to means something will probably happen or be true.","zh":"be likely to 指某事很可能發生或是真的。"},{"en":"A student who studies every day is likely to improve over time.","zh":"每天學習的學生很可能隨時間進步。"},{"en":"If a paper is placed at the top of a pile, the owner is likely to need it soon.","zh":"如果一份紙放在紙堆頂部，主人很可能很快需要它。"},{"en":"This phrase shows probability, not certainty.","zh":"這個短語表示可能性，而不是確定性。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":13},{"front":"at the top","meaning":"在頂部","examples":[{"en":"The most important document is often at the top of the pile.","zh":"最重要的文件常在紙堆頂部。"},{"en":"At the top means in the highest or first position.","zh":"at the top 指在最高或第一的位置。"},{"en":"A teacher may put today’s attendance sheet at the top of the folder.","zh":"老師可能把今天的點名紙放在文件夾頂部。"},{"en":"Items at the top are easier to see and reach, so they may be more urgent.","zh":"在頂部的物件較容易看見和拿到，因此可能更緊急。"},{"en":"This phrase describes position in a stack, list, page, or ranking.","zh":"這個短語描述在堆疊、清單、頁面或排名中的位置。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":13},{"front":"living, breathing archives","meaning":"活生生的檔案庫","examples":[{"en":"Piles are living, breathing archives.","zh":"紙堆是活生生的檔案庫。"},{"en":"Living, breathing archives are collections that keep changing and actively reflect ongoing work.","zh":"living, breathing archives 指不斷改變並主動反映進行中工作的收藏。"},{"en":"A teacher’s desk can become a living, breathing archive of lesson plans, student questions, and unfinished marking.","zh":"老師的書桌可以成為由教案、學生問題和未完成批改組成的活生生檔案庫。"},{"en":"Unlike fixed storage, such archives change as priorities and ideas change.","zh":"與固定儲存不同，這類檔案庫會隨優先事項和想法改變。"},{"en":"This phrase is metaphorical and suggests active, evolving memory.","zh":"這個短語是比喻，表示主動而不斷演變的記憶。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":13},{"front":"over time","meaning":"隨着時間過去","examples":[{"en":"Over time, piles get broken down and sorted again.","zh":"隨着時間過去，紙堆會被拆開並再次分類。"},{"en":"Over time means gradually as time passes.","zh":"over time 指隨時間逐漸地。"},{"en":"Over time, students become faster at reading if they practise regularly.","zh":"隨着時間過去，如果學生定期練習，他們閱讀會變得更快。"},{"en":"Small changes can become important over time because their effects accumulate.","zh":"小改變隨時間可能變得重要，因為其影響會累積。"},{"en":"This phrase is useful for describing gradual development.","zh":"描述逐漸發展時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":14},{"front":"get broken down","meaning":"被拆開","examples":[{"en":"Piles get broken down when workers reorganise them.","zh":"當職員重新整理紙堆時，紙堆會被拆開。"},{"en":"To get broken down means to be separated into smaller parts or categories.","zh":"get broken down 指被分成較小部分或類別。"},{"en":"A large project gets broken down into weekly tasks so students can manage it.","zh":"大型項目會被拆分成每週任務，讓學生能夠處理。"},{"en":"Breaking things down can make a complicated task easier to handle.","zh":"把事情拆開可以令複雜任務較容易處理。"},{"en":"This phrase is often used for organising work, ideas, or materials.","zh":"這個短語常用於整理工作、想法或材料。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":14},{"front":"be resorted","meaning":"被重新分類","examples":[{"en":"The piles are sometimes resorted by date or theme.","zh":"這些紙堆有時會按日期或主題被重新分類。"},{"en":"To be resorted means to be sorted again into a new order or grouping.","zh":"be resorted 指被再次整理成新的順序或分組。"},{"en":"Old exam papers may be resorted by subject before revision begins.","zh":"舊試卷可能在溫習開始前按科目被重新分類。"},{"en":"Resorting materials helps people find a better structure when the old one no longer works.","zh":"重新分類材料有助人們在舊結構不再有效時找出更好結構。"},{"en":"This phrase focuses on organising something again.","zh":"這個短語聚焦再次整理某物。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":14},{"front":"chronologically","meaning":"按時間順序","examples":[{"en":"Documents may be sorted chronologically.","zh":"文件可能按時間順序排列。"},{"en":"Chronologically means in the order in which events happened over time.","zh":"chronologically 指按照事件隨時間發生的順序。"},{"en":"A student may arrange history notes chronologically from the earliest event to the latest.","zh":"學生可能把歷史筆記按時間順序從最早事件排到最新事件。"},{"en":"Chronological order helps readers see causes, changes, and development.","zh":"時間順序幫助讀者看見原因、變化和發展。"},{"en":"This word is useful when time sequence matters.","zh":"當時間先後重要時，這個詞很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":14},{"front":"thematically","meaning":"按主題","examples":[{"en":"Documents may be sorted thematically.","zh":"文件可能按主題排列。"},{"en":"Thematically means by topic, subject, or idea rather than by time.","zh":"thematically 指按題目、主題或想法分類，而不是按時間。"},{"en":"A student may organise vocabulary thematically into food, transport, school, and health.","zh":"學生可能按食物、交通、學校和健康等主題整理詞彙。"},{"en":"Sorting thematically helps people compare similar ideas from different dates or sources.","zh":"按主題分類幫助人們比較來自不同日期或來源的相似想法。"},{"en":"This word is useful when topic matters more than sequence.","zh":"當主題比先後次序更重要時，這個詞很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":14},{"front":"clues about","meaning":"關於……的線索","examples":[{"en":"Physical clues about documents may be embedded in the file.","zh":"關於文件的實體線索可能嵌入在檔案中。"},{"en":"Clues about something are small signs that help people understand or remember it.","zh":"clues about something 指幫助人理解或記住某事的小跡象。"},{"en":"A sticky note can give clues about which chapter a student should revise first.","zh":"便利貼可以提供關於學生應先溫習哪一章的線索。"},{"en":"Clues reduce confusion because they guide attention to useful information.","zh":"線索會引導注意力到有用資訊，因此減少混亂。"},{"en":"This phrase is useful when indirect signs help explain meaning.","zh":"當間接跡象有助解釋意思時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":14},{"front":"physically embedded in","meaning":"實際嵌入於……","examples":[{"en":"Clues about documents may be physically embedded in the file.","zh":"關於文件的線索可能實際嵌入於檔案中。"},{"en":"Physically embedded in something means built into or placed within its physical form.","zh":"physically embedded in something 指被放入或成為某物實體形式的一部分。"},{"en":"A coloured divider may be physically embedded in a folder to mark an important section.","zh":"彩色分隔紙可能實際嵌入於文件夾中，以標示重要部分。"},{"en":"Physical cues are easy to notice because they are part of the object itself.","zh":"實體提示容易被注意到，因為它們是物件本身的一部分。"},{"en":"This phrase contrasts physical placement with mental memory or digital tags.","zh":"這個短語把實體放置與心理記憶或數碼標籤作對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":14},{"front":"by, say","meaning":"例如","examples":[{"en":"A clue may be created by, say, placing a paper at an angle.","zh":"線索可以例如透過把一張紙斜放來創造。"},{"en":"By, say means for example, when giving one possible case.","zh":"by, say 表示例如，用來提出一個可能例子。"},{"en":"A teacher can mark urgent work by, say, using a red folder.","zh":"老師可以例如使用紅色文件夾來標示緊急工作。"},{"en":"This phrase introduces an example without claiming it is the only example.","zh":"這個短語引出例子，但不表示它是唯一例子。"},{"en":"It is slightly conversational and helps explain a general idea.","zh":"它語氣稍微口語化，有助解釋一般想法。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":14},{"front":"stack a piece of paper at an angle","meaning":"將一張紙斜放在紙堆中","examples":[{"en":"A worker may stack a piece of paper at an angle.","zh":"職員可能將一張紙斜放在紙堆中。"},{"en":"To stack a piece of paper at an angle means to place it in a pile slightly turned rather than straight.","zh":"stack a piece of paper at an angle 指把一張紙略為斜放在紙堆中，而不是整齊放直。"},{"en":"A student may stack a worksheet at an angle to remind herself to finish it first.","zh":"學生可能把一張工作紙斜放，以提醒自己先完成它。"},{"en":"The unusual position acts as a visual clue that the paper is special.","zh":"不尋常的位置會成為視覺線索，顯示該紙張特別。"},{"en":"This phrase shows how physical arrangement can carry meaning.","zh":"這個短語顯示實體排列如何承載意義。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":14},{"front":"insert dividers into","meaning":"將分隔紙插入……","examples":[{"en":"Workers may insert dividers into the stack.","zh":"職員可能將分隔紙插入紙堆中。"},{"en":"To insert dividers into something means to put separating sheets or markers inside it.","zh":"insert dividers into something 指把分隔頁或標記放進某物內。"},{"en":"A student may insert dividers into a binder to separate different subjects.","zh":"學生可能將分隔紙插入活頁夾，以分開不同科目。"},{"en":"Dividers make sections easier to find and reduce time spent searching.","zh":"分隔紙令各部分更容易找到，並減少搜尋時間。"},{"en":"This phrase is useful when talking about organising physical documents.","zh":"討論整理實體文件時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":14},{"front":"document filing","meaning":"文件歸檔","examples":[{"en":"Document filing is different from piling documents on a desk.","zh":"文件歸檔不同於把文件堆放在書桌上。"},{"en":"Document filing is the organised storage of documents in folders, cabinets, or digital systems.","zh":"document filing 指把文件有組織地儲存在文件夾、文件櫃或數碼系統中。"},{"en":"A secretary may do document filing so contracts can be found later.","zh":"秘書可能進行文件歸檔，以便日後找到合約。"},{"en":"Filing improves long-term storage, but it may hide active work from sight.","zh":"歸檔改善長期儲存，但可能令進行中的工作從視線中消失。"},{"en":"This phrase refers to formal organisation rather than temporary piles.","zh":"這個短語指正式整理，而不是臨時紙堆。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":14},{"front":"instead of","meaning":"而不是","examples":[{"en":"Some workers pile documents instead of filing them.","zh":"有些職員把文件堆起來，而不是把它們歸檔。"},{"en":"Instead of means in place of another choice or action.","zh":"instead of 指用一個選擇或行動取代另一個。"},{"en":"A student may draw a mind map instead of writing a long outline.","zh":"學生可能畫思維導圖，而不是寫長大綱。"},{"en":"Choosing one method instead of another can change how people think and work.","zh":"選擇一種方法而不是另一種，可能改變人們的思考和工作方式。"},{"en":"This phrase clearly shows contrast between two alternatives.","zh":"這個短語清楚顯示兩個選項之間的對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":15},{"front":"active, ongoing thinking","meaning":"主動而持續的思考","examples":[{"en":"Piles represent the process of active, ongoing thinking.","zh":"紙堆代表主動而持續的思考過程。"},{"en":"Active, ongoing thinking means thinking that is still developing and has not reached a final answer.","zh":"active, ongoing thinking 指仍在發展、尚未得出最終答案的思考。"},{"en":"A student’s notes may show active, ongoing thinking while she plans an essay.","zh":"學生計劃文章時，她的筆記可能顯示主動而持續的思考。"},{"en":"When ideas are unfinished, people may keep materials visible to help them continue thinking.","zh":"當想法未完成，人們可能讓材料保持可見，以幫助自己繼續思考。"},{"en":"This phrase contrasts living thought with completed organisation.","zh":"這個短語把活生生的思考與已完成的整理作對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":15},{"front":"knowledge workers","meaning":"知識工作者","examples":[{"en":"Knowledge workers often use physical space to organise ideas.","zh":"知識工作者常使用實體空間來整理想法。"},{"en":"Knowledge workers are people whose main work involves information, ideas, analysis, or expertise.","zh":"knowledge workers 指主要工作涉及資訊、想法、分析或專業知識的人。"},{"en":"Teachers, analysts, researchers, designers, and consultants can be knowledge workers.","zh":"老師、分析員、研究員、設計師和顧問都可以是知識工作者。"},{"en":"Knowledge workers need tools that help them think, compare, write, and communicate.","zh":"知識工作者需要幫助他們思考、比較、寫作和溝通的工具。"},{"en":"This phrase refers to workers who produce or manage knowledge rather than physical goods.","zh":"這個短語指生產或管理知識，而不是實體商品的工作者。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":15},{"front":"physical space of the desktop","meaning":"書桌的實體空間","examples":[{"en":"Workers use the physical space of the desktop to hold ideas.","zh":"職員使用書桌的實體空間來承載想法。"},{"en":"The physical space of the desktop means the actual surface area of a desk that can hold objects.","zh":"physical space of the desktop 指書桌表面可放置物件的實際空間。"},{"en":"A student may use the physical space of the desktop to separate notes for different subjects.","zh":"學生可能使用書桌的實體空間來分開不同科目的筆記。"},{"en":"Physical space can support thinking because location can show priority or relationship.","zh":"實體空間可以支援思考，因為位置可以顯示優先次序或關係。"},{"en":"This phrase highlights the desk as a thinking tool, not just furniture.","zh":"這個短語突出書桌是思考工具，而不只是家具。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":15},{"front":"hold ideas","meaning":"承載想法","examples":[{"en":"The desktop can hold ideas that are not yet categorised.","zh":"書桌可以承載尚未分類的想法。"},{"en":"To hold ideas means to contain, represent, or keep ideas available for later thinking.","zh":"hold ideas 指包含、代表或保留想法，以便之後思考。"},{"en":"A whiteboard can hold ideas during a brainstorming meeting.","zh":"白板可以在腦力激盪會議中承載想法。"},{"en":"Physical objects can hold ideas when they remind people of unfinished tasks or questions.","zh":"當實體物件提醒人們未完成任務或問題時，它們可以承載想法。"},{"en":"This phrase is partly metaphorical: a surface holds papers, and the papers hold thoughts.","zh":"這個短語帶有部分比喻：表面承載紙張，而紙張承載思想。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":15},{"front":"cannot yet categorise","meaning":"尚未能分類","examples":[{"en":"Workers may keep papers because they cannot yet categorise the ideas.","zh":"職員可能保留紙張，因為他們尚未能把想法分類。"},{"en":"Cannot yet categorise means not being able to decide the correct group or type for something at the moment.","zh":"cannot yet categorise 指暫時未能決定某物屬於哪個正確組別或類型。"},{"en":"A student may keep several notes together because she cannot yet categorise them by topic.","zh":"學生可能把幾張筆記放在一起，因為她尚未能按主題分類。"},{"en":"When ideas are still unclear, forcing categories too early can cause confusion.","zh":"當想法仍不清晰，太早強行分類可能造成混亂。"},{"en":"This phrase shows that organisation may need time and thinking.","zh":"這個短語顯示整理可能需要時間和思考。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":15},{"front":"decide how they might use","meaning":"決定如何使用","examples":[{"en":"Workers may not yet decide how they might use certain ideas.","zh":"職員可能尚未決定如何使用某些想法。"},{"en":"To decide how they might use something means to choose a possible way to apply it later.","zh":"decide how they might use something 指選擇日後可能如何應用某物。"},{"en":"A student may save an example before deciding how she might use it in an essay.","zh":"學生可能先保存一個例子，再決定如何在文章中使用它。"},{"en":"If people are unsure how an idea will be used, they may keep it visible instead of filing it away.","zh":"如果人們不確定某個想法將如何被使用，他們可能讓它保持可見，而不是歸檔。"},{"en":"This phrase describes planning for possible future use.","zh":"這個短語描述為可能的未來用途作計劃。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":15},{"front":"not necessarily a sign of","meaning":"不一定是……的跡象","examples":[{"en":"A messy desk is not necessarily a sign of disorganisation.","zh":"凌亂的書桌不一定是缺乏組織的跡象。"},{"en":"Not necessarily a sign of something means it does not always prove that thing is true.","zh":"not necessarily a sign of something 指某事不一定證明另一件事是真的。"},{"en":"A quiet student is not necessarily a sign of low ability.","zh":"安靜的學生不一定是能力低的跡象。"},{"en":"People may misjudge a situation if they treat one visible detail as certain proof.","zh":"如果人們把一個可見細節當成確切證明，可能會誤判情況。"},{"en":"This phrase helps make a careful and balanced statement.","zh":"這個短語有助作出謹慎而平衡的說法。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":15},{"front":"disorganisation","meaning":"混亂；缺乏組織","examples":[{"en":"A messy desk may not indicate disorganisation.","zh":"凌亂的書桌未必表示混亂或缺乏組織。"},{"en":"Disorganisation means a lack of clear order, planning, or structure.","zh":"disorganisation 指缺乏清晰秩序、計劃或結構。"},{"en":"A student may suffer from disorganisation if homework, notes, and deadlines are often lost.","zh":"如果學生常遺失功課、筆記和截止日期，他可能受缺乏組織影響。"},{"en":"Disorganisation can waste time because people must search for what they need.","zh":"缺乏組織會浪費時間，因為人們必須搜尋所需物品。"},{"en":"However, visible mess is not always the same as real disorganisation.","zh":"然而，可見的凌亂不一定等於真正缺乏組織。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":15},{"front":"a sign of complexity","meaning":"複雜性的跡象","examples":[{"en":"A messy desk may be a sign of complexity.","zh":"凌亂的書桌可能是複雜性的跡象。"},{"en":"A sign of complexity is evidence that many connected parts or unresolved issues are involved.","zh":"a sign of complexity 指顯示涉及許多相互連結部分或未解決問題的證據。"},{"en":"Many papers on a lawyer’s desk may be a sign of complexity in a difficult case.","zh":"律師書桌上的許多文件可能是一宗困難案件複雜性的跡象。"},{"en":"Complex work often creates visible materials because people must compare many details.","zh":"複雜工作常產生可見材料，因為人們必須比較許多細節。"},{"en":"This phrase offers a more positive interpretation of mess.","zh":"這個短語為凌亂提供較正面的解讀。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":15},{"front":"deal with","meaning":"處理","examples":[{"en":"Some workers deal with many unresolved ideas at once.","zh":"有些職員同時處理許多尚未解決的想法。"},{"en":"To deal with something means to handle, manage, or respond to it.","zh":"deal with something 指處理、管理或回應某事。"},{"en":"A receptionist must deal with phone calls, visitors, and forms at the same time.","zh":"接待員必須同時處理電話、訪客和表格。"},{"en":"If people deal with too many problems at once, they may feel stressed.","zh":"如果人們同時處理太多問題，可能感到壓力。"},{"en":"This phrase is very common for talking about tasks, problems, or responsibilities.","zh":"這個短語非常常用於談論任務、問題或責任。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":15},{"front":"unresolved ideas","meaning":"尚未解決的想法","examples":[{"en":"Unresolved ideas may be represented by piles of paper.","zh":"尚未解決的想法可能由紙堆代表。"},{"en":"Unresolved ideas are thoughts, questions, or plans that have not yet been decided or completed.","zh":"unresolved ideas 指尚未被決定或完成的想法、問題或計劃。"},{"en":"A student may keep notes about unresolved ideas for a future essay.","zh":"學生可能保留關於尚未解決想法的筆記，以供日後寫文章。"},{"en":"Unresolved ideas stay visible because the thinker is not ready to file them away.","zh":"尚未解決的想法保持可見，因為思考者尚未準備把它們歸檔。"},{"en":"This phrase describes thinking that is still open and unfinished.","zh":"這個短語描述仍然開放和未完成的思考。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":16},{"front":"simultaneously","meaning":"同時","examples":[{"en":"Some workers deal with many unresolved ideas simultaneously.","zh":"有些職員同時處理許多尚未解決的想法。"},{"en":"Simultaneously means at the same time.","zh":"simultaneously 指在同一時間。"},{"en":"A teacher may listen to a student and check the attendance list simultaneously.","zh":"老師可能一邊聽學生說話，一邊同時查看點名表。"},{"en":"Doing several tasks simultaneously can save time, but it can also reduce attention.","zh":"同時做幾項任務可以節省時間，但也可能降低注意力。"},{"en":"This word is more formal than at the same time.","zh":"這個詞比 at the same time 更正式。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":16},{"front":"sort and file","meaning":"分類和歸檔","examples":[{"en":"Workers cannot sort and file papers before sorting their ideas.","zh":"職員在整理腦中想法之前，不能先分類和歸檔紙張。"},{"en":"To sort and file papers means to organise them into categories and store them properly.","zh":"sort and file papers 指把紙張分類並妥善儲存。"},{"en":"An assistant may sort and file invoices by month and supplier.","zh":"助理可能按月份和供應商分類和歸檔發票。"},{"en":"Sorting and filing becomes easier when the purpose of each document is clear.","zh":"當每份文件的用途清楚時，分類和歸檔會更容易。"},{"en":"This phrase describes formal organisation of documents.","zh":"這個短語描述文件的正式整理。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":16},{"front":"in their heads","meaning":"在腦海中","examples":[{"en":"They have not yet sorted the ideas in their heads.","zh":"他們尚未在腦海中整理好這些想法。"},{"en":"In their heads means in their minds or thoughts.","zh":"in their heads 指在他們的心中或思想中。"},{"en":"Students may understand a topic in their heads but struggle to explain it clearly in writing.","zh":"學生可能在腦海中理解一個主題，但難以用文字清楚解釋。"},{"en":"Ideas often need to be sorted in the head before they can be organised on paper.","zh":"想法常需要先在腦海中整理好，才能在紙上組織。"},{"en":"This phrase contrasts mental organisation with visible organisation.","zh":"這個短語把心理整理與可見整理作對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":16},{"front":"contextual cues","meaning":"情境提示","examples":[{"en":"Papers on a desk serve as contextual cues.","zh":"書桌上的紙張充當情境提示。"},{"en":"Contextual cues are surrounding signs or details that help people remember what they were doing.","zh":"contextual cues 指周圍幫助人記起自己正在做甚麼的跡象或細節。"},{"en":"A textbook left open on a desk can be a contextual cue to continue revision.","zh":"放在書桌上打開的教科書可以是繼續溫習的情境提示。"},{"en":"Contextual cues help people restart work after interruptions.","zh":"情境提示幫助人在被打斷後重新開始工作。"},{"en":"This phrase is useful in learning, memory, and workplace organisation.","zh":"這個短語在學習、記憶和工作場所整理中很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":16},{"front":"recover a complex set of threads","meaning":"重新掌握一組複雜線索","examples":[{"en":"Papers help workers recover a complex set of threads.","zh":"紙張幫助職員重新掌握一組複雜線索。"},{"en":"To recover a complex set of threads means to regain understanding of many connected lines of thought or tasks.","zh":"recover a complex set of threads 指重新理解許多相互連結的思路或任務。"},{"en":"After a holiday, a manager may use notes to recover a complex set of threads in a project.","zh":"假期後，經理可能用筆記重新掌握項目中的一組複雜線索。"},{"en":"Physical cues help because they remind people where different ideas were left.","zh":"實體提示有幫助，因為它們提醒人不同想法停在哪裡。"},{"en":"This phrase describes returning to complicated unfinished work.","zh":"這個短語描述回到複雜而未完成的工作。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":16},{"front":"without difficulty and delay","meaning":"不費力且不延誤","examples":[{"en":"Contextual cues help workers resume work without difficulty and delay.","zh":"情境提示幫助職員不費力且不延誤地恢復工作。"},{"en":"Without difficulty and delay means smoothly and without wasting time.","zh":"without difficulty and delay 指順利而不浪費時間。"},{"en":"Clear labels help students find materials without difficulty and delay.","zh":"清楚標籤幫助學生不費力且不延誤地找到材料。"},{"en":"If information is easy to locate, people can continue work faster.","zh":"如果資訊容易找到，人們可以更快繼續工作。"},{"en":"This phrase stresses ease and speed.","zh":"這個短語強調容易和快速。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":16},{"front":"come in on a Monday morning","meaning":"星期一早上回到辦公室","examples":[{"en":"Workers use paper cues when they come in on a Monday morning.","zh":"職員星期一早上回到辦公室時會使用紙張提示。"},{"en":"To come in on a Monday morning means to arrive at work at the start of the working week.","zh":"come in on a Monday morning 指在工作週開始時回到工作場所。"},{"en":"A teacher may come in on a Monday morning and use lesson notes to remember the week’s plan.","zh":"老師可能星期一早上回到學校，並用教案記起本週計劃。"},{"en":"After a weekend, visible cues help people restart work without forgetting priorities.","zh":"週末後，可見提示幫助人們重新開始工作而不忘記優先事項。"},{"en":"This phrase gives a familiar workplace time context.","zh":"這個短語提供熟悉的工作時間背景。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":16},{"front":"be interrupted by","meaning":"被……打斷","examples":[{"en":"Work may be interrupted by a phone call.","zh":"工作可能被電話打斷。"},{"en":"To be interrupted by something means to be stopped or disturbed by it while doing another activity.","zh":"be interrupted by something 指正在做某活動時被某事停止或干擾。"},{"en":"A student’s revision may be interrupted by messages from classmates.","zh":"學生的溫習可能被同學訊息打斷。"},{"en":"Interruptions can break concentration and make it harder to remember where one stopped.","zh":"打斷會破壞專注，並令人更難記起自己停在哪裡。"},{"en":"This phrase is useful when explaining why cues and reminders matter.","zh":"解釋提示和提醒為何重要時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":16},{"front":"in a sense","meaning":"從某種意義上說","examples":[{"en":"In a sense, piles show the contents of our brains.","zh":"從某種意義上說，紙堆顯示我們腦海中的內容。"},{"en":"In a sense means in one way of looking at the matter.","zh":"in a sense 指從某個角度來看。"},{"en":"In a sense, a timetable is a map of how someone uses time.","zh":"從某種意義上說，時間表是一個人如何使用時間的地圖。"},{"en":"Writers use this phrase when a statement is partly true or metaphorical.","zh":"當一句話部分正確或帶有比喻時，作者會使用這個短語。"},{"en":"This phrase makes a claim more careful and less absolute.","zh":"這個短語使說法更謹慎、不那麼絕對。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":16},{"front":"the contents of our brains","meaning":"我們腦海中的內容","examples":[{"en":"The piles on our desks may reflect the contents of our brains.","zh":"書桌上的紙堆可能反映我們腦海中的內容。"},{"en":"The contents of our brains means the thoughts, memories, plans, and concerns in our minds.","zh":"the contents of our brains 指我們心中的想法、記憶、計劃和關注。"},{"en":"A notebook can reveal the contents of a student’s brain during revision.","zh":"筆記簿可以揭示學生溫習期間腦海中的內容。"},{"en":"Work materials may reflect what a person is thinking about, even if the desk looks messy.","zh":"工作材料可能反映一個人在想甚麼，即使書桌看起來凌亂。"},{"en":"This phrase is often used metaphorically, not literally.","zh":"這個短語常作比喻使用，而不是字面意思。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":16},{"front":"facilitate a process","meaning":"促成一個過程","examples":[{"en":"Paper facilitates a specialised cognitive and social process.","zh":"紙張促成一個專門的認知及社交過程。"},{"en":"To facilitate a process means to make that process easier or more effective.","zh":"facilitate a process 指令某個過程更容易或更有效。"},{"en":"A checklist can facilitate a process by helping staff remember each step.","zh":"清單可以透過幫助員工記住每一步來促成一個過程。"},{"en":"Good tools facilitate work because they reduce confusion and unnecessary effort.","zh":"好工具能促進工作，因為它們減少混亂和不必要努力。"},{"en":"This phrase is formal and useful for explaining how something helps.","zh":"這個短語較正式，適合解釋某物如何有幫助。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":17},{"front":"highly specialised","meaning":"高度專門化的","examples":[{"en":"Paper supports a highly specialised kind of work.","zh":"紙張支援一種高度專門化的工作。"},{"en":"Highly specialised means designed for or connected with a very specific skill, task, or field.","zh":"highly specialised 指為非常特定的技能、任務或領域而設計或與之相關。"},{"en":"A hospital lab uses highly specialised equipment to test blood samples.","zh":"醫院實驗室使用高度專門化的設備檢測血液樣本。"},{"en":"Specialised tools can be very useful for one task but less useful for general work.","zh":"專門化工具對某一任務可能非常有用，但對一般工作較不實用。"},{"en":"This phrase stresses narrow but expert use.","zh":"這個短語強調範圍狹窄但專業的用途。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":17},{"front":"cognitive and social process","meaning":"認知及社交過程","examples":[{"en":"Paper facilitates a cognitive and social process.","zh":"紙張促成一個認知及社交過程。"},{"en":"A cognitive and social process involves both thinking and interaction with other people.","zh":"cognitive and social process 指同時涉及思考和與他人互動的過程。"},{"en":"Group essay planning is a cognitive and social process because students think and discuss together.","zh":"小組文章規劃是一個認知及社交過程，因為學生一起思考和討論。"},{"en":"Paper can support this process by making ideas visible and shareable.","zh":"紙張可以透過令想法可見和可分享來支援這個過程。"},{"en":"This phrase links mental work with teamwork.","zh":"這個短語把心智工作與團隊合作連接起來。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":17},{"front":"a far cry from","meaning":"與……大相逕庭","examples":[{"en":"This idea is a far cry from older views of paper.","zh":"這個想法與較舊的紙張觀點大相逕庭。"},{"en":"A far cry from something means very different from it.","zh":"a far cry from something 指與某事非常不同。"},{"en":"A modern library with digital databases is a far cry from a small room of dusty books.","zh":"擁有數碼資料庫的現代圖書館，與只有滿是灰塵書本的小房間大相逕庭。"},{"en":"When two ideas are a far cry from each other, they show a major change in thinking.","zh":"當兩個想法大相逕庭時，它們顯示思維上的重大改變。"},{"en":"This phrase emphasises strong contrast.","zh":"這個短語強調強烈對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":17},{"front":"historically think about","meaning":"歷來如此看待","examples":[{"en":"People have historically thought about paper in a different way.","zh":"人們歷來以不同方式看待紙張。"},{"en":"To historically think about something means to have viewed it in a certain way in the past.","zh":"historically think about something 指過去一直以某種方式看待某事。"},{"en":"People historically thought about offices as places for records and control.","zh":"人們歷來把辦公室看作記錄和控制的地方。"},{"en":"Past views may differ from modern views because work and technology change.","zh":"過去觀點可能與現代觀點不同，因為工作和科技會改變。"},{"en":"This phrase connects present discussion with earlier thinking.","zh":"這個短語把現在的討論與早期思維連接起來。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":17},{"front":"proliferate in the workplace","meaning":"在工作場所大量增加","examples":[{"en":"Paper began to proliferate in the workplace in the late nineteenth century.","zh":"紙張在19世紀末開始在工作場所大量增加。"},{"en":"To proliferate in the workplace means to increase rapidly and become common at work.","zh":"proliferate in the workplace 指在工作場所迅速增加並變得常見。"},{"en":"Email began to proliferate in the workplace when internet access became normal.","zh":"當互聯網接入變得普遍，電郵開始在工作場所大量增加。"},{"en":"When a tool proliferates, it can change routines, communication, and management.","zh":"當一種工具大量普及，它可以改變日常流程、溝通和管理。"},{"en":"This phrase describes rapid spread in offices or work settings.","zh":"這個短語描述辦公室或工作環境中的迅速傳播。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":17},{"front":"the late nineteenth century","meaning":"19世紀末","examples":[{"en":"Paper became common in offices in the late nineteenth century.","zh":"紙張在19世紀末於辦公室變得常見。"},{"en":"The late nineteenth century means the later years of the 1800s.","zh":"the late nineteenth century 指1800年代後期。"},{"en":"Many offices changed in the late nineteenth century as businesses became larger.","zh":"19世紀末，隨着企業變得更大，許多辦公室發生改變。"},{"en":"This period matters because new management methods and office technologies expanded.","zh":"這個時期很重要，因為新管理方法和辦公科技擴展。"},{"en":"This phrase gives a historical time frame.","zh":"這個短語提供歷史時間範圍。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":17},{"front":"the move toward","meaning":"走向……的趨勢","examples":[{"en":"Paper spread as part of the move toward systematic management.","zh":"紙張的普及是走向系統化管理趨勢的一部分。"},{"en":"The move toward something means a gradual change in that direction.","zh":"the move toward something 指朝某方向的逐漸改變。"},{"en":"Many schools are part of the move toward digital learning.","zh":"許多學校正處於走向數碼學習的趨勢中。"},{"en":"A move toward a new system often changes tools, habits, and expectations.","zh":"走向新制度的趨勢常改變工具、習慣和期望。"},{"en":"This phrase describes a wider trend rather than one sudden action.","zh":"這個短語描述較大的趨勢，而不是一次突然行動。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":17},{"front":"systematic management","meaning":"系統化管理","examples":[{"en":"Paper supported the rise of systematic management.","zh":"紙張支援系統化管理的興起。"},{"en":"Systematic management is organised control of work through rules, records, reports, and procedures.","zh":"systematic management 指透過規則、記錄、報告和程序有組織地控制工作。"},{"en":"A company uses systematic management when every department follows the same reporting rules.","zh":"當每個部門都遵守同一套匯報規則時，公司就在使用系統化管理。"},{"en":"Systematic management can improve coordination, but it may also increase paperwork.","zh":"系統化管理可以改善協調，但也可能增加文書工作。"},{"en":"This phrase belongs to business and organisational history.","zh":"這個短語屬於商業和組織歷史語境。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":17},{"front":"cope with the complexity of","meaning":"應付……的複雜性","examples":[{"en":"Managers used paper to cope with the complexity of the industrial economy.","zh":"管理者使用紙張來應付工業經濟的複雜性。"},{"en":"To cope with the complexity of something means to manage a difficult situation with many connected parts.","zh":"cope with the complexity of something 指處理包含許多相互連結部分的困難情況。"},{"en":"Schools use timetables to cope with the complexity of rooms, teachers, and classes.","zh":"學校使用時間表來應付課室、老師和班級的複雜性。"},{"en":"When complexity increases, people need systems that help them record and coordinate information.","zh":"當複雜性增加，人們需要幫助記錄和協調資訊的系統。"},{"en":"This phrase shows how people respond to complicated conditions.","zh":"這個短語顯示人們如何回應複雜情況。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":17},{"front":"the industrial economy","meaning":"工業經濟","examples":[{"en":"The industrial economy required more reports and records.","zh":"工業經濟需要更多報告和記錄。"},{"en":"The industrial economy is an economy based heavily on factories, machines, large companies, and mass production.","zh":"the industrial economy 指高度依賴工廠、機器、大企業和大規模生產的經濟。"},{"en":"In the industrial economy, managers needed records to control workers, materials, and sales.","zh":"在工業經濟中，管理者需要記錄來控制工人、材料和銷售。"},{"en":"Large-scale production created more information that had to be tracked.","zh":"大規模生產創造更多必須追蹤的資訊。"},{"en":"This phrase refers to a historical stage of economic organisation.","zh":"這個短語指經濟組織的一個歷史階段。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":17},{"front":"institute company-wide policies","meaning":"制定全公司政策","examples":[{"en":"Managers were instituting company-wide policies.","zh":"管理者正在制定全公司政策。"},{"en":"To institute company-wide policies means to introduce rules that apply across the whole company.","zh":"institute company-wide policies 指引入適用於整間公司的規則。"},{"en":"A business may institute company-wide policies on safety, leave, and data protection.","zh":"企業可能制定關於安全、假期和資料保護的全公司政策。"},{"en":"Company-wide policies create consistency, but they require clear communication and records.","zh":"全公司政策創造一致性，但需要清楚溝通和記錄。"},{"en":"This phrase is formal and often used in management contexts.","zh":"這個短語較正式，常用於管理語境。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":18},{"front":"company-wide policies","meaning":"全公司政策","examples":[{"en":"Paper helped managers implement company-wide policies.","zh":"紙張幫助管理者執行全公司政策。"},{"en":"Company-wide policies are rules or procedures that apply to every department or employee in a company.","zh":"company-wide policies 指適用於公司每個部門或員工的規則或程序。"},{"en":"A company-wide policy may require all staff to report expenses in the same format.","zh":"全公司政策可能要求所有員工以同一格式匯報開支。"},{"en":"Such policies help large organisations act consistently.","zh":"這類政策幫助大型組織保持一致行動。"},{"en":"This phrase stresses that the rule is not limited to one small team.","zh":"這個短語強調規則不限於一個小團隊。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":18},{"front":"demand updates from","meaning":"向……要求匯報","examples":[{"en":"Managers demanded regular updates from subordinates.","zh":"管理者向下屬要求定期匯報。"},{"en":"To demand updates from someone means to require them to provide new information regularly.","zh":"demand updates from someone 指要求某人定期提供新資料。"},{"en":"A project leader may demand updates from team members before a deadline.","zh":"項目負責人可能在截止日期前向團隊成員要求匯報。"},{"en":"Regular updates help managers monitor progress and notice delays early.","zh":"定期匯報幫助管理者監察進度並早點發現延誤。"},{"en":"This phrase suggests authority and formal reporting.","zh":"這個短語帶有權威和正式匯報意味。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":18},{"front":"monthly, weekly, or daily updates","meaning":"每月、每星期或每日匯報","examples":[{"en":"Managers demanded monthly, weekly, or daily updates.","zh":"管理者要求每月、每星期或每日匯報。"},{"en":"Monthly, weekly, or daily updates are reports given every month, week, or day.","zh":"monthly, weekly, or daily updates 指每月、每星期或每日提供的報告。"},{"en":"A sales team may send weekly updates to show progress toward targets.","zh":"銷售團隊可能發送每星期匯報，以顯示目標進度。"},{"en":"More frequent updates give managers more control but may create more paperwork.","zh":"更頻密匯報給管理者更多控制，但可能製造更多文書工作。"},{"en":"This phrase describes different reporting intervals.","zh":"這個短語描述不同匯報間隔。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":18},{"front":"subordinates","meaning":"下屬","examples":[{"en":"Managers required reports from their subordinates.","zh":"管理者要求下屬提交報告。"},{"en":"Subordinates are people who work under someone with higher authority.","zh":"subordinates 指在較高權力者之下工作的人。"},{"en":"A department head may ask subordinates to submit progress reports every Friday.","zh":"部門主管可能要求下屬每星期五提交進度報告。"},{"en":"Clear instructions help subordinates understand what their managers expect.","zh":"清楚指示幫助下屬理解管理者的期望。"},{"en":"This word is formal and can sound hierarchical.","zh":"這個詞較正式，可能帶有階級意味。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":18},{"front":"thus was born","meaning":"……由此誕生","examples":[{"en":"Thus was born the monthly sales report.","zh":"每月銷售報告由此誕生。"},{"en":"Thus was born means this is how something began or was created.","zh":"thus was born 指某事就是這樣開始或被創造出來。"},{"en":"A school needed better communication; thus was born the weekly parent newsletter.","zh":"學校需要更好的溝通；每週家長通訊由此誕生。"},{"en":"This phrase links a cause with the creation of a new practice or object.","zh":"這個短語把原因與新做法或事物的創造連接起來。"},{"en":"It is more dramatic and formal than saying so this started.","zh":"它比 so this started 更有戲劇感和正式感。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":18},{"front":"monthly sales report","meaning":"每月銷售報告","examples":[{"en":"The monthly sales report became part of office life.","zh":"每月銷售報告成為辦公室生活的一部分。"},{"en":"A monthly sales report is a document showing sales results for one month.","zh":"monthly sales report 指顯示一個月銷售結果的文件。"},{"en":"A manager may read the monthly sales report to see which products sold best.","zh":"經理可能閱讀每月銷售報告，以了解哪些產品賣得最好。"},{"en":"Monthly reports help companies compare performance over time.","zh":"每月報告幫助公司比較不同時間的表現。"},{"en":"This phrase belongs to business reporting and management.","zh":"這個短語屬於商業匯報和管理語境。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":18},{"front":"office manual","meaning":"辦公室手冊","examples":[{"en":"The office manual was another paper-based management tool.","zh":"辦公室手冊是另一種紙本管理工具。"},{"en":"An office manual is a guidebook that explains workplace rules, procedures, and responsibilities.","zh":"office manual 指解釋工作場所規則、程序和責任的指南。"},{"en":"New staff may read the office manual to learn how to request leave or file documents.","zh":"新員工可能閱讀辦公室手冊，以學習如何申請假期或歸檔文件。"},{"en":"Manuals reduce confusion because workers can check procedures without asking every time.","zh":"手冊減少混亂，因為員工可以查看程序，而不用每次都提問。"},{"en":"This phrase refers to written guidance inside an organisation.","zh":"這個短語指組織內部的書面指引。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":18},{"front":"internal company newsletter","meaning":"公司內部通訊","examples":[{"en":"The internal company newsletter helped circulate information.","zh":"公司內部通訊幫助傳遞資訊。"},{"en":"An internal company newsletter is a regular publication shared within a company for employees.","zh":"internal company newsletter 指在公司內部定期分享給員工的出版物。"},{"en":"It may announce staff changes, sales results, new rules, and upcoming events.","zh":"它可能宣布人事變動、銷售結果、新規則和即將舉行的活動。"},{"en":"Newsletters help large organisations keep employees informed.","zh":"內部通訊幫助大型組織讓員工掌握資訊。"},{"en":"This phrase refers to communication inside a company, not public advertising.","zh":"這個短語指公司內部溝通，而不是公開廣告。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":18},{"front":"take off","meaning":"開始流行；迅速普及","examples":[{"en":"The typewriter took off in the 1880s.","zh":"打字機在1880年代開始流行。"},{"en":"To take off means to become popular or successful quickly.","zh":"take off 指迅速變得受歡迎或成功。"},{"en":"Online food delivery took off when many people began using smartphones.","zh":"當許多人開始使用智能手機時，網上外賣服務迅速普及。"},{"en":"When a tool takes off, it can change habits across a whole industry.","zh":"當一種工具迅速普及，它可以改變整個行業的習慣。"},{"en":"This phrase is informal and often describes rapid growth.","zh":"這個短語較非正式，常描述快速增長。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":18},{"front":"make it possible to","meaning":"使……成為可能","examples":[{"en":"The typewriter made it possible to create documents quickly.","zh":"打字機使快速製作文件成為可能。"},{"en":"To make it possible to do something means to create the conditions that allow it to happen.","zh":"make it possible to do something 指創造條件，使某事能夠發生。"},{"en":"Online lessons make it possible to study from home during bad weather.","zh":"網上課堂使惡劣天氣期間在家學習成為可能。"},{"en":"New tools can make old tasks faster, cheaper, or more widely available.","zh":"新工具可以使舊任務更快、更便宜或更普及。"},{"en":"This phrase shows how one development enables another action.","zh":"這個短語顯示一種發展如何使另一行動成為可能。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":18},{"front":"in a fraction of the time","meaning":"只需原本時間的一小部分","examples":[{"en":"Typewriters created documents in a fraction of the time previously needed.","zh":"打字機只需原本所需時間的一小部分就能製作文件。"},{"en":"In a fraction of the time means using much less time than before.","zh":"in a fraction of the time 指使用比以前少得多的時間。"},{"en":"A photocopier can copy pages in a fraction of the time needed for handwriting them.","zh":"影印機可以只需手抄所需時間的一小部分就複印頁面。"},{"en":"Saving time can change office routines because workers can produce more documents.","zh":"節省時間可以改變辦公室流程，因為員工可以製作更多文件。"},{"en":"This phrase emphasises a large reduction in time.","zh":"這個短語強調時間大幅減少。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":19},{"front":"the advent of","meaning":"……的出現","examples":[{"en":"The advent of carbon paper allowed typists to make copies.","zh":"複寫紙的出現讓打字員能製作副本。"},{"en":"The advent of something means the arrival or beginning of an important new thing.","zh":"the advent of something 指重要新事物的到來或開始。"},{"en":"The advent of email changed how offices communicated.","zh":"電郵的出現改變了辦公室溝通方式。"},{"en":"When a new technology arrives, it may create new habits and expectations.","zh":"當新科技出現，它可能創造新習慣和新期望。"},{"en":"This phrase is formal and often used in historical writing.","zh":"這個短語較正式，常用於歷史寫作。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":19},{"front":"carbon paper","meaning":"複寫紙","examples":[{"en":"Carbon paper allowed a typist to create several copies at once.","zh":"複寫紙讓打字員一次製作幾份副本。"},{"en":"Carbon paper is thin paper coated with ink or carbon used to make copies while typing or writing.","zh":"carbon paper 指塗有墨或碳的薄紙，用於打字或書寫時製作副本。"},{"en":"Before photocopiers were common, offices used carbon paper to duplicate forms.","zh":"在影印機普及前，辦公室使用複寫紙複製表格。"},{"en":"Carbon paper saved time because one typing action could produce several copies.","zh":"複寫紙節省時間，因為一次打字動作可以產生幾份副本。"},{"en":"This phrase refers to an older paper-based copying technology.","zh":"這個短語指較舊的紙本複製技術。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":19},{"front":"typist","meaning":"打字員","examples":[{"en":"A typist could create ten copies simultaneously.","zh":"打字員可以同時製作十份副本。"},{"en":"A typist is a person whose job is to type documents.","zh":"typist 指以打字文件為工作的職員。"},{"en":"Before personal computers, a typist might prepare letters, reports, and forms for an office.","zh":"在個人電腦出現前，打字員可能為辦公室準備信件、報告和表格。"},{"en":"Typists helped companies produce documents quickly and neatly.","zh":"打字員幫助公司快速而整齊地製作文件。"},{"en":"This word is connected with older office work and typewriter use.","zh":"這個詞與較舊的辦公工作和打字機使用有關。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":19},{"front":"create copies simultaneously","meaning":"同時製作副本","examples":[{"en":"Carbon paper allowed a typist to create copies simultaneously.","zh":"複寫紙讓打字員能同時製作副本。"},{"en":"To create copies simultaneously means to produce several copies at the same time.","zh":"create copies simultaneously 指在同一時間製作幾份副本。"},{"en":"A printer can create copies simultaneously if it is connected to several output trays.","zh":"如果打印機連接多個輸出紙盤，它可以同時製作副本。"},{"en":"Making copies at the same time saves effort and supports wider distribution.","zh":"同時製作副本節省努力並支援更廣泛分發。"},{"en":"This phrase combines copying with speed and efficiency.","zh":"這個短語結合複製、速度和效率。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":19},{"front":"facilitate creative collaboration","meaning":"促進創意協作","examples":[{"en":"Paper was not originally important to facilitate creative collaboration.","zh":"紙張最初並不是為了促進創意協作而重要。"},{"en":"To facilitate creative collaboration means to make it easier for people to work together on new ideas.","zh":"facilitate creative collaboration 指令多人共同發展新想法變得更容易。"},{"en":"A shared whiteboard can facilitate creative collaboration during a design meeting.","zh":"共享白板可以在設計會議中促進創意協作。"},{"en":"Creative collaboration improves when people can see, move, and change ideas together.","zh":"當人們能一起看見、移動和改變想法時，創意協作會改善。"},{"en":"This phrase focuses on teamwork in idea development.","zh":"這個短語聚焦想法發展中的團隊合作。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":19},{"front":"instrument of control","meaning":"控制工具","examples":[{"en":"Paper was used as an instrument of control.","zh":"紙張被用作控制工具。"},{"en":"An instrument of control is a tool used to monitor, direct, or manage people and activities.","zh":"instrument of control 指用來監察、指揮或管理人和活動的工具。"},{"en":"Attendance records can become an instrument of control in a strict workplace.","zh":"在嚴格工作場所中，出勤記錄可以成為控制工具。"},{"en":"Reports give managers information, which can increase their control over workers.","zh":"報告向管理者提供資訊，從而增加他們對員工的控制。"},{"en":"This phrase suggests that a tool is used for authority, not just communication.","zh":"這個短語表示工具被用於權威，而不只是溝通。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":19},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Students choose the correct heading for each paragraph.","zh":"學生為每段選出正確標題。"},{"en":"To choose the correct heading means to select the title that best summarises a paragraph.","zh":"choose the correct heading 指選出最能概括段落的標題。"},{"en":"In reading exams, students should read the whole paragraph before choosing the heading.","zh":"在閱讀考試中，學生應先讀完整段，再選標題。"},{"en":"A wrong heading often focuses on a detail instead of the main idea.","zh":"錯誤標題常聚焦細節，而不是主旨。"},{"en":"This phrase is common in IELTS-style reading tasks.","zh":"這個短語常見於 IELTS 類閱讀題。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":19},{"front":"from the list below","meaning":"從以下列表中","examples":[{"en":"The headings are chosen from the list below.","zh":"標題是從以下列表中選出的。"},{"en":"From the list below means using only the options printed underneath the instruction.","zh":"from the list below 指只使用指示下方列出的選項。"},{"en":"Students should choose answers from the list below, not invent their own headings.","zh":"學生應從以下列表中選答案，而不是自己創作標題。"},{"en":"Using the list helps limit the possible answers and makes comparison easier.","zh":"使用列表有助限制可能答案，並令比較更容易。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":19},{"front":"write the correct number","meaning":"寫上正確號碼","examples":[{"en":"Students write the correct number on the answer sheet.","zh":"學生在答題紙上寫上正確號碼。"},{"en":"To write the correct number means to record the number that matches the right answer.","zh":"write the correct number 指寫下與正確答案相配的號碼。"},{"en":"In a heading task, students may write iii or iv instead of copying the whole heading.","zh":"在標題配對題中，學生可能寫 iii 或 iv，而不是抄整個標題。"},{"en":"Writing the wrong number can lose marks even if the student understands the paragraph.","zh":"即使學生理解段落，寫錯號碼也可能失分。"},{"en":"This phrase reminds students to follow the answer format exactly.","zh":"這個短語提醒學生嚴格按照答案格式作答。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":19},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生在答題紙上寫下答案。"},{"en":"On your answer sheet means in the official place where exam answers must be recorded.","zh":"on your answer sheet 指在考試答案必須填寫的正式位置。"},{"en":"A correct answer in the question booklet may not count if it is not on your answer sheet.","zh":"如果答案只寫在題目冊上，而沒有寫在答題紙上，可能不會計分。"},{"en":"Students should check that the question number matches the answer box.","zh":"學生應檢查題號是否與答案格相符。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":19},{"front":"remain essential for","meaning":"對……仍然必不可少","examples":[{"en":"Paper remains essential for sharing and management.","zh":"紙張對分享和管理仍然必不可少。"},{"en":"To remain essential for something means to continue being necessary or very important for it.","zh":"remain essential for something 指對某事繼續必要或非常重要。"},{"en":"Clear communication remains essential for teamwork even when technology improves.","zh":"即使科技進步，清楚溝通對團隊合作仍然必不可少。"},{"en":"A tool may remain essential because it solves problems newer tools do not solve well.","zh":"一種工具可能仍然必不可少，因為它解決新工具不能很好解決的問題。"},{"en":"This phrase shows continued importance.","zh":"這個短語顯示持續的重要性。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":20},{"front":"sharing and management","meaning":"分享和管理","examples":[{"en":"Paper can support sharing and management in offices.","zh":"紙張可以支援辦公室中的分享和管理。"},{"en":"Sharing and management refer to distributing information and organising work or people.","zh":"sharing and management 指分發資訊，以及組織工作或人員。"},{"en":"A shared notice board can help with sharing and management in a school office.","zh":"共享告示板可以幫助學校辦公室的分享和管理。"},{"en":"Good sharing and management reduce confusion because everyone knows what is happening.","zh":"良好的分享和管理能減少混亂，因為人人知道正在發生甚麼。"},{"en":"This phrase connects communication with control and organisation.","zh":"這個短語把溝通與控制和組織連接起來。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":20},{"front":"inspire rather than indicate","meaning":"啟發而非顯示……","examples":[{"en":"Piles can inspire rather than indicate disorganisation.","zh":"紙堆可以啟發思考，而非顯示缺乏組織。"},{"en":"Inspire rather than indicate means something may encourage thought instead of simply showing a problem.","zh":"inspire rather than indicate 指某事可能激發思考，而不是單純顯示問題。"},{"en":"A messy sketchbook may inspire creativity rather than indicate laziness.","zh":"凌亂的速寫簿可能啟發創意，而非顯示懶惰。"},{"en":"This phrase contrasts a positive function with a negative interpretation.","zh":"這個短語把正面功能與負面解讀作對比。"},{"en":"It helps readers avoid judging appearance too quickly.","zh":"它幫助讀者避免太快按外觀判斷。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":20},{"front":"a favourable situation","meaning":"有利情況","examples":[{"en":"The passage describes a favourable situation in which economists used paper.","zh":"文章描述一個經濟學家使用紙張的有利情況。"},{"en":"A favourable situation is a condition that is helpful, suitable, or positive for something.","zh":"a favourable situation 指對某事有幫助、合適或正面的情況。"},{"en":"A quiet library is a favourable situation for deep reading.","zh":"安靜的圖書館是深入閱讀的有利情況。"},{"en":"When the situation is favourable, people can work more effectively and make better decisions.","zh":"當情況有利，人們可以更有效工作並作出更好決定。"},{"en":"This phrase describes conditions that support success.","zh":"這個短語描述支持成功的條件。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":20},{"front":"unexpected situation","meaning":"意料之外的情況","examples":[{"en":"The survival of paper is an unexpected situation.","zh":"紙張繼續存在是一個意料之外的情況。"},{"en":"An unexpected situation is a condition or event that people did not predict.","zh":"unexpected situation 指人們沒有預測到的情況或事件。"},{"en":"A school may face an unexpected situation when the internet stops working during an online exam.","zh":"當網上考試期間互聯網停止運作，學校可能面對意料之外的情況。"},{"en":"Unexpected situations force people to question their assumptions and adjust plans.","zh":"意料之外的情況迫使人們質疑假設並調整計劃。"},{"en":"This phrase describes surprise in real circumstances.","zh":"這個短語描述真實情境中的意外。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":20},{"front":"paper survives","meaning":"紙張繼續存在","examples":[{"en":"The passage gives an overview of why paper survives.","zh":"文章概述紙張為何繼續存在。"},{"en":"Paper survives means paper continues to be used despite alternatives such as computers.","zh":"paper survives 指儘管有電腦等替代品，紙張仍繼續被使用。"},{"en":"Paper survives in classrooms because students still write, draw, and mark texts by hand.","zh":"紙張在課室中繼續存在，因為學生仍會手寫、繪畫和標記文本。"},{"en":"A tool survives when it continues to solve problems well.","zh":"當一種工具仍能有效解決問題，它就會繼續存在。"},{"en":"This phrase focuses on continued usefulness, not biological survival.","zh":"這個短語聚焦持續有用，而不是生物學上的生存。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":20},{"front":"a comparison between","meaning":"……之間的比較","examples":[{"en":"The passage includes a comparison between paper and computers.","zh":"文章包括紙張和電腦之間的比較。"},{"en":"A comparison between two things examines their similarities and differences.","zh":"a comparison between two things 指檢視兩者的相似和不同之處。"},{"en":"A teacher may ask for a comparison between online learning and classroom learning.","zh":"老師可能要求學生比較網上學習和課室學習。"},{"en":"Comparisons help people decide which tool is better for a particular purpose.","zh":"比較幫助人們決定哪種工具更適合特定目的。"},{"en":"This phrase is useful for analytical writing.","zh":"這個短語適用於分析性寫作。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":20},{"front":"the efficiency of","meaning":"……的效率","examples":[{"en":"The heading refers to the efficiency of paper and computers.","zh":"這個標題提到紙張和電腦的效率。"},{"en":"The efficiency of something means how well it saves time, effort, money, or resources.","zh":"the efficiency of something 指某事在節省時間、努力、金錢或資源方面的表現。"},{"en":"A manager may compare the efficiency of email and printed notices.","zh":"經理可能比較電郵和印刷通告的效率。"},{"en":"A tool can be efficient for storage but inefficient for face-to-face discussion.","zh":"一種工具在儲存方面可能有效率，但在面對面討論方面效率較低。"},{"en":"This phrase helps evaluate how well something works.","zh":"這個短語幫助評估某物運作得如何。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":20},{"front":"appear to waste paper","meaning":"看似浪費紙張","examples":[{"en":"The IMF’s office may appear to waste paper.","zh":"國際貨幣基金組織的辦公室可能看似浪費紙張。"},{"en":"To appear to waste paper means to look as if paper is being used unnecessarily.","zh":"appear to waste paper 指看起來好像在不必要地使用紙張。"},{"en":"A teacher’s desk may appear to waste paper if many drafts are lying around.","zh":"如果老師書桌上放着許多草稿，可能看似浪費紙張。"},{"en":"What looks wasteful may have a hidden purpose in review, memory, or collaboration.","zh":"看似浪費的東西可能在審閱、記憶或協作中有隱藏用途。"},{"en":"This phrase separates appearance from actual function.","zh":"這個短語把外觀與實際功能分開。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":20},{"front":"a failed attempt to avoid","meaning":"避免……的失敗嘗試","examples":[{"en":"The heading describes a failed attempt to avoid paper records.","zh":"這個標題描述一次避免紙本記錄的失敗嘗試。"},{"en":"A failed attempt to avoid something is an effort to stop using or doing it that does not succeed.","zh":"a failed attempt to avoid something 指嘗試停止使用或做某事但未成功。"},{"en":"A school may make a failed attempt to avoid printed notices if parents still ask for paper copies.","zh":"如果家長仍要求紙本副本，學校避免印刷通告的嘗試可能失敗。"},{"en":"Failed attempts show that a problem may be more complicated than expected.","zh":"失敗嘗試顯示問題可能比預期更複雜。"},{"en":"This phrase describes an unsuccessful effort to prevent or remove something.","zh":"這個短語描述未能成功防止或移除某事的努力。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":20},{"front":"paper records","meaning":"紙本記錄","examples":[{"en":"Some offices have tried to avoid paper records.","zh":"有些辦公室曾嘗試避免紙本記錄。"},{"en":"Paper records are written or printed documents kept as evidence or information.","zh":"paper records 指作為證據或資料保存的手寫或印刷文件。"},{"en":"Hospitals used paper records before electronic patient systems became common.","zh":"在電子病人系統普及前，醫院使用紙本記錄。"},{"en":"Paper records can be easy to read physically but hard to search quickly.","zh":"紙本記錄可以容易實體閱讀，但難以快速搜尋。"},{"en":"This phrase contrasts physical records with electronic records.","zh":"這個短語把實體記錄與電子記錄作對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":20},{"front":"advantages of using paper","meaning":"使用紙張的好處","examples":[{"en":"The passage discusses the advantages of using paper in offices.","zh":"文章討論在辦公室使用紙張的好處。"},{"en":"Advantages of using paper are the benefits paper provides for reading, marking, sorting, or discussion.","zh":"advantages of using paper 指紙張在閱讀、標記、分類或討論方面提供的好處。"},{"en":"One advantage of using paper is that several pages can be spread out at once.","zh":"使用紙張的一個好處是可以一次攤開幾頁。"},{"en":"These advantages explain why paper may remain useful even with computers.","zh":"這些好處解釋為何即使有電腦，紙張仍可能有用。"},{"en":"This phrase is useful in compare-and-contrast writing.","zh":"這個短語適用於比較和對比寫作。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":21},{"front":"reflect characteristics of","meaning":"反映……的特點","examples":[{"en":"Piles may reflect characteristics of people’s thoughts.","zh":"紙堆可能反映人們想法的特點。"},{"en":"To reflect characteristics of something means to show its features or qualities.","zh":"reflect characteristics of something 指顯示某事物的特徵或質素。"},{"en":"A student’s notes may reflect characteristics of her learning style.","zh":"學生的筆記可能反映她學習風格的特點。"},{"en":"Physical arrangements can reveal patterns in how people think and work.","zh":"實體排列可以揭示人們思考和工作的模式。"},{"en":"This phrase is useful when visible things show hidden qualities.","zh":"當可見事物顯示隱藏特質時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":21},{"front":"people’s thoughts","meaning":"人們的想法","examples":[{"en":"Piles can reflect people’s thoughts.","zh":"紙堆可以反映人們的想法。"},{"en":"People’s thoughts are the ideas, concerns, plans, and questions in their minds.","zh":"people’s thoughts 指人們心中的想法、關注、計劃和問題。"},{"en":"A writer’s notebook may show people’s thoughts more clearly than a finished article.","zh":"作家的筆記簿可能比完成的文章更清楚顯示人的想法。"},{"en":"When thoughts are unfinished, people may keep reminders around them.","zh":"當想法未完成，人們可能在身邊保留提醒物。"},{"en":"This phrase refers to mental content rather than spoken words only.","zh":"這個短語指心理內容，而不只是說出口的話。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":21},{"front":"the benefit of having","meaning":"擁有……的好處","examples":[{"en":"The heading mentions the benefit of having a clear space.","zh":"這個標題提到擁有一片清空空間的好處。"},{"en":"The benefit of having something is the advantage gained from possessing or using it.","zh":"the benefit of having something 指擁有或使用某物所帶來的優點。"},{"en":"The benefit of having a quiet study corner is that students can focus more easily.","zh":"擁有安靜學習角落的好處是學生可以更容易專注。"},{"en":"A clear benefit makes people more willing to keep a habit or tool.","zh":"清楚的好處會令人更願意保持某個習慣或工具。"},{"en":"This phrase introduces a positive effect.","zh":"這個短語引出正面效果。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":21},{"front":"complete the summary","meaning":"完成摘要","examples":[{"en":"Students complete the summary using words from the reading passage.","zh":"學生使用閱讀文章中的詞語完成摘要。"},{"en":"To complete the summary means to fill in missing words so the summary becomes whole.","zh":"complete the summary 指填入缺失詞語，使摘要完整。"},{"en":"In a reading test, students complete the summary by locating matching information in the text.","zh":"在閱讀測驗中，學生透過在文本中定位相配資料來完成摘要。"},{"en":"This task checks whether students understand main ideas and key details.","zh":"這項任務檢查學生是否理解主旨和重點細節。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":21},{"front":"no more than three words","meaning":"不超過三個字","examples":[{"en":"Students should use no more than three words for each answer.","zh":"學生每個答案應使用不超過三個字。"},{"en":"No more than three words means one, two, or three words, but not four or more.","zh":"no more than three words 指一個、兩個或三個字，但不是四個或更多。"},{"en":"If the answer is paper documents, it follows the rule of no more than three words.","zh":"如果答案是 paper documents，就符合不超過三個字的規則。"},{"en":"Students lose marks if they write too many words even when the idea is correct.","zh":"即使意思正確，學生寫太多字也會失分。"},{"en":"This phrase controls answer length in reading tests.","zh":"這個短語控制閱讀測驗中的答案長度。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":21},{"front":"from the reading passage","meaning":"從閱讀文章中","examples":[{"en":"The answers must come from the reading passage.","zh":"答案必須來自閱讀文章中。"},{"en":"From the reading passage means taken directly from the text provided in the exam.","zh":"from the reading passage 指直接取自考試提供的文本。"},{"en":"Students should not use outside knowledge when the answer must come from the reading passage.","zh":"當答案必須來自閱讀文章時，學生不應使用外部知識。"},{"en":"This rule keeps answers based on evidence rather than guessing.","zh":"這條規則確保答案基於證據，而不是猜測。"},{"en":"This phrase is common in reading-comprehension instructions.","zh":"這個短語常見於閱讀理解指示。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":21},{"front":"compared with","meaning":"與……相比","examples":[{"en":"Compared with digital documents, paper has several advantages.","zh":"與數碼文件相比，紙張有幾項優點。"},{"en":"Compared with means looked at beside another thing to show similarities or differences.","zh":"compared with 指把某事與另一事物放在一起看，以顯示相似或差異。"},{"en":"Compared with buses, trains may be faster for long-distance travel.","zh":"與巴士相比，火車在長途旅行中可能更快。"},{"en":"A comparison can show that one tool is better for one task but worse for another.","zh":"比較可以顯示某工具在某項任務上較好，但在另一任務上較差。"},{"en":"This phrase is useful for balanced analysis.","zh":"這個短語適合平衡分析。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":21},{"front":"several advantages","meaning":"幾項優點","examples":[{"en":"Paper has several advantages over digital documents.","zh":"紙張相對於數碼文件有幾項優點。"},{"en":"Several advantages means more than one useful quality or benefit.","zh":"several advantages 指多於一項有用特質或好處。"},{"en":"Studying in a library has several advantages, such as quiet space and easy access to books.","zh":"在圖書館學習有幾項優點，例如安靜空間和容易取得書本。"},{"en":"When something has several advantages, people may keep using it even if it has weaknesses.","zh":"當某物有幾項優點，即使它有弱點，人們仍可能繼續使用。"},{"en":"This phrase introduces multiple positive points.","zh":"這個短語引出多個正面要點。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":21},{"front":"work in a collaborative way","meaning":"以協作方式工作","examples":[{"en":"Paper allows staff to work in a collaborative way.","zh":"紙張讓員工以協作方式工作。"},{"en":"To work in a collaborative way means to work together by sharing ideas, tasks, and decisions.","zh":"work in a collaborative way 指透過分享想法、任務和決定一起工作。"},{"en":"Students work in a collaborative way when they plan a project on the same table.","zh":"學生在同一張桌上計劃項目時，就是以協作方式工作。"},{"en":"Collaboration becomes easier when everyone can see the same materials.","zh":"當每個人都能看見同一份材料時，協作會更容易。"},{"en":"This phrase focuses on teamwork rather than individual work.","zh":"這個短語聚焦團隊合作，而不是個人工作。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":21},{"front":"unlike virtual digital versions","meaning":"不像虛擬數碼版本","examples":[{"en":"Unlike virtual digital versions, paper is tangible.","zh":"不像虛擬數碼版本，紙張是有形的。"},{"en":"Unlike virtual digital versions means different from electronic versions that exist on screens or devices.","zh":"unlike virtual digital versions 指不同於存在於屏幕或裝置上的電子版本。"},{"en":"Unlike virtual digital versions, printed tickets can be held, folded, and handed to someone.","zh":"不像虛擬數碼版本，印刷門票可以被拿住、摺起和交給別人。"},{"en":"This contrast explains why physical documents may feel easier to manage in some tasks.","zh":"這種對比解釋為何實體文件在某些任務中可能感覺更易管理。"},{"en":"This phrase compares physical and digital forms.","zh":"這個短語比較實體和數碼形式。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":21},{"front":"virtual digital versions","meaning":"虛擬數碼版本","examples":[{"en":"Virtual digital versions may lack the physical flexibility of paper.","zh":"虛擬數碼版本可能缺乏紙張的實體靈活性。"},{"en":"Virtual digital versions are electronic forms of documents or objects that exist on screens rather than physically.","zh":"virtual digital versions 指存在於屏幕上而非實體存在的文件或物件電子形式。"},{"en":"A digital textbook is a virtual digital version of a printed book.","zh":"數碼教科書是印刷書的虛擬數碼版本。"},{"en":"Digital versions are easy to store and search, but they cannot always be handled like paper.","zh":"數碼版本容易儲存和搜尋，但不一定能像紙張一樣被處理。"},{"en":"This phrase contrasts screen-based forms with physical copies.","zh":"這個短語把屏幕形式與實體副本作對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":22},{"front":"notes or comments","meaning":"筆記或評語","examples":[{"en":"Notes or comments can be added easily to paper.","zh":"筆記或評語可以容易加到紙上。"},{"en":"Notes or comments are short written ideas, explanations, questions, or feedback.","zh":"notes or comments 指簡短寫下的想法、解釋、問題或回饋。"},{"en":"A teacher may add notes or comments to a student’s essay draft.","zh":"老師可能在學生文章草稿上加入筆記或評語。"},{"en":"Comments help writers understand what to keep, change, or explain more clearly.","zh":"評語幫助作者理解應保留、修改或解釋得更清楚的地方。"},{"en":"This phrase is useful when discussing reviewing and annotation.","zh":"討論審閱和加註時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":22},{"front":"be added easily","meaning":"容易被加上","examples":[{"en":"Comments can be added easily to a paper document.","zh":"評語可以容易被加到紙本文件上。"},{"en":"To be added easily means something can be put in without much time or effort.","zh":"be added easily 指某物可以不費太多時間或努力地加入。"},{"en":"A note can be added easily to a printed draft with a pen.","zh":"一條筆記可以用筆容易加到印刷草稿上。"},{"en":"Easy addition of comments makes review faster and more flexible.","zh":"評語容易加入，令審閱更快速和更靈活。"},{"en":"This phrase describes convenience in changing or marking something.","zh":"這個短語描述修改或標記某物時的便利。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":22},{"front":"shortcoming","meaning":"缺點","examples":[{"en":"Digital documents have advantages, but paper also has a shortcoming.","zh":"數碼文件有優點，但紙張也有缺點。"},{"en":"A shortcoming is a weakness, limitation, or disadvantage.","zh":"shortcoming 指弱點、限制或不利之處。"},{"en":"A paper notebook’s shortcoming is that it cannot be searched with keywords.","zh":"紙本筆記簿的一個缺點是不能用關鍵詞搜尋。"},{"en":"Recognising shortcomings helps people choose the right tool for each task.","zh":"承認缺點有助人們為每項任務選擇合適工具。"},{"en":"This word is useful in balanced evaluation.","zh":"這個詞適用於平衡評估。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":22},{"front":"a lack of convenience","meaning":"缺乏便利性","examples":[{"en":"Paper may have a lack of convenience for certain digital tasks.","zh":"對於某些數碼任務，紙張可能缺乏便利性。"},{"en":"A lack of convenience means something is not easy, quick, or practical to use.","zh":"a lack of convenience 指某物使用起來不容易、不快捷或不實用。"},{"en":"Paper maps may have a lack of convenience when a driver needs live traffic updates.","zh":"當司機需要即時交通更新時，紙本地圖可能缺乏便利性。"},{"en":"If a tool lacks convenience, people may avoid it even when it has other strengths.","zh":"如果工具缺乏便利性，即使有其他優點，人們也可能避免使用。"},{"en":"This phrase describes a practical weakness.","zh":"這個短語描述實際弱點。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":22},{"front":"a task involving","meaning":"涉及……的任務","examples":[{"en":"Paper is less convenient for a task involving remote access.","zh":"對於涉及遙距存取的任務，紙張較不方便。"},{"en":"A task involving something is an activity that includes or requires that thing.","zh":"a task involving something 指包含或需要某事的活動。"},{"en":"A task involving group discussion may be easier with printed pages on a table.","zh":"涉及小組討論的任務，可能用桌上的印刷頁面更容易。"},{"en":"If a task involves remote workers, digital tools may be more practical than paper.","zh":"如果任務涉及遙距員工，數碼工具可能比紙張更實用。"},{"en":"This phrase helps define what a task includes.","zh":"這個短語幫助界定任務包含甚麼。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":22},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter from the options.","zh":"學生從選項中選出正確字母。"},{"en":"To choose the correct letter means to select the letter that matches the right answer.","zh":"choose the correct letter 指選出與正確答案相配的字母。"},{"en":"In multiple-choice questions, students may choose A, B, C, or D.","zh":"在選擇題中，學生可能選 A、B、C 或 D。"},{"en":"Students should check evidence in the passage before choosing the letter.","zh":"學生在選字母前應先檢查文章證據。"},{"en":"This phrase is common in reading and listening tests.","zh":"這個短語常見於閱讀和聆聽測驗。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":22},{"front":"what is implied by","meaning":"……暗示了甚麼","examples":[{"en":"The question asks what is implied by the piles mentioned in the passage.","zh":"題目問文章提到的紙堆暗示了甚麼。"},{"en":"What is implied by something means what is suggested indirectly rather than stated directly.","zh":"what is implied by something 指某事間接暗示甚麼，而不是直接說出甚麼。"},{"en":"A teacher may ask what is implied by a character’s silence in a story.","zh":"老師可能問故事中角色的沉默暗示了甚麼。"},{"en":"Understanding implication requires reading beyond the exact words.","zh":"理解暗示需要讀出字面以外的意思。"},{"en":"This phrase is common in inference questions.","zh":"這個短語常見於推論題。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":22},{"front":"the piles mentioned in the passage","meaning":"文章提到的紙堆","examples":[{"en":"The piles mentioned in the passage may have an underlying order.","zh":"文章提到的紙堆可能有潛在秩序。"},{"en":"The piles mentioned in the passage are the stacks of papers described by the writer.","zh":"the piles mentioned in the passage 指作者描述的一疊疊紙張。"},{"en":"These piles may look messy but still help workers remember tasks and ideas.","zh":"這些紙堆可能看似凌亂，但仍幫助職員記住任務和想法。"},{"en":"Mentioning the piles helps the passage explain how paper supports thinking.","zh":"提到紙堆有助文章解釋紙張如何支援思考。"},{"en":"This phrase points back to a specific detail in the reading text.","zh":"這個短語指回閱讀文本中的特定細節。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":22},{"front":"an underlying order","meaning":"潛在秩序","examples":[{"en":"The piles have an underlying order even if they look messy.","zh":"即使這些紙堆看似凌亂，它們也有潛在秩序。"},{"en":"An underlying order is a hidden structure or logic beneath something that appears disorganised.","zh":"an underlying order 指隱藏在看似無組織事物之下的結構或邏輯。"},{"en":"A student’s notes may have an underlying order based on exam urgency.","zh":"學生的筆記可能有基於考試緊急程度的潛在秩序。"},{"en":"Understanding the hidden order can prevent unfair judgement of someone’s workspace.","zh":"理解隱藏秩序可以避免不公平地判斷某人的工作空間。"},{"en":"This phrase contrasts surface mess with deeper organisation.","zh":"這個短語把表面凌亂與深層組織作對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":22},{"front":"necessarily a mess","meaning":"必然是一團糟","examples":[{"en":"The piles are not necessarily a mess.","zh":"這些紙堆不一定必然是一團糟。"},{"en":"Not necessarily a mess means something may look untidy but is not always truly disorganised.","zh":"not necessarily a mess 指某物可能看起來不整齊，但不一定真正無組織。"},{"en":"A desk covered with papers is not necessarily a mess if each pile has a purpose.","zh":"如果每一堆都有目的，堆滿紙張的書桌不一定是一團糟。"},{"en":"People should ask how a system works before judging it by appearance.","zh":"人們在按外觀判斷前，應先了解系統如何運作。"},{"en":"This phrase helps correct a quick assumption.","zh":"這個短語有助糾正倉促假設。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":22},{"front":"be arranged chronologically","meaning":"按時間順序排列","examples":[{"en":"Some documents may be arranged chronologically.","zh":"有些文件可能按時間順序排列。"},{"en":"To be arranged chronologically means to be placed in time order from earlier to later or later to earlier.","zh":"be arranged chronologically 指按時間先後排列，可以由早到晚或由晚到早。"},{"en":"A history folder may be arranged chronologically by year.","zh":"歷史文件夾可能按年份以時間順序排列。"},{"en":"Chronological arrangement helps people follow development over time.","zh":"按時間順序排列幫助人們跟隨事情隨時間的發展。"},{"en":"This phrase is useful when time sequence matters.","zh":"當時間順序重要時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":23},{"front":"be arranged alphabetically","meaning":"按字母順序排列","examples":[{"en":"Documents are not necessarily arranged alphabetically.","zh":"文件不一定按字母順序排列。"},{"en":"To be arranged alphabetically means to be organised according to the order of letters in the alphabet.","zh":"be arranged alphabetically 指根據字母表順序整理。"},{"en":"A class list may be arranged alphabetically by students’ surnames.","zh":"班級名單可能按學生姓氏以字母順序排列。"},{"en":"Alphabetical order helps people find names quickly, but it may not show importance or urgency.","zh":"字母順序幫助人們快速找到姓名，但未必顯示重要性或緊急程度。"},{"en":"This phrase describes one common system of organisation.","zh":"這個短語描述一種常見整理系統。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":23},{"front":"management tool","meaning":"管理工具","examples":[{"en":"Managers believed that paper records could be used as a management tool.","zh":"管理者相信紙本記錄可以被用作管理工具。"},{"en":"A management tool is something used to organise, monitor, or control work.","zh":"management tool 指用來組織、監察或控制工作的事物。"},{"en":"A shared task list can be a management tool for a small team.","zh":"共享任務清單可以是小團隊的管理工具。"},{"en":"Management tools help leaders see progress, assign responsibility, and make decisions.","zh":"管理工具幫助領導者看見進度、分配責任和作決定。"},{"en":"This phrase focuses on practical control and organisation.","zh":"這個短語聚焦實際控制和組織。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":23},{"front":"be compulsory","meaning":"強制性的","examples":[{"en":"Carbon paper was useful, but it was not necessarily compulsory.","zh":"複寫紙很有用，但不一定是強制性的。"},{"en":"To be compulsory means to be required by rule or law.","zh":"be compulsory 指根據規則或法律必須做。"},{"en":"School attendance is compulsory for children in many places.","zh":"在許多地方，兒童上學是強制性的。"},{"en":"If something is compulsory, people cannot simply choose to ignore it.","zh":"如果某事是強制性的，人們不能隨意選擇忽略它。"},{"en":"This word contrasts required action with optional action.","zh":"這個詞把必須行動與可選行動作對比。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":23},{"front":"the most important consideration","meaning":"最重要的考慮因素","examples":[{"en":"Teamwork was not the only important consideration in early paper use.","zh":"團隊合作不是早期使用紙張時唯一重要的考慮因素。"},{"en":"The most important consideration is the main factor people think about before deciding.","zh":"the most important consideration 指人們決定前思考的主要因素。"},{"en":"When choosing a school, safety may be the most important consideration for parents.","zh":"選擇學校時，安全可能是家長最重要的考慮因素。"},{"en":"If people focus on the wrong consideration, they may choose the wrong solution.","zh":"如果人們聚焦錯誤考慮因素，可能選錯解決方案。"},{"en":"This phrase is useful for discussing priorities.","zh":"討論優先事項時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":23},{"front":"the best approach","meaning":"最佳方法","examples":[{"en":"Monthly reports were one approach to management.","zh":"每月報告是管理的一種方法。"},{"en":"The best approach is the most suitable method for dealing with a task or problem.","zh":"the best approach 指處理任務或問題的最合適方法。"},{"en":"For a shy student, the best approach may be gradual speaking practice rather than sudden presentations.","zh":"對害羞學生而言，最佳方法可能是逐步說話練習，而不是突然做匯報。"},{"en":"The best approach depends on the goal, context, and people involved.","zh":"最佳方法取決於目標、情境和相關人士。"},{"en":"This phrase is useful when comparing possible methods.","zh":"比較可能方法時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":23},{"front":"according to the passage","meaning":"根據文章","examples":[{"en":"According to the passage, paper has not been replaced for practical reasons.","zh":"根據文章，紙張因實際原因未被取代。"},{"en":"According to the passage means based only on what the reading text says.","zh":"according to the passage 指只根據閱讀文本所說。"},{"en":"Students should answer according to the passage, not according to personal opinion.","zh":"學生應根據文章作答，而不是根據個人意見。"},{"en":"This instruction prevents learners from using outside knowledge when evidence is required.","zh":"這個指示防止學習者在需要證據時使用外部知識。"},{"en":"This phrase is common in reading-comprehension questions.","zh":"這個短語常見於閱讀理解題。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":23},{"front":"be replaced by electronic documents","meaning":"被電子文件取代","examples":[{"en":"Paper has not been fully replaced by electronic documents.","zh":"紙張尚未完全被電子文件取代。"},{"en":"To be replaced by electronic documents means to be substituted with digital files.","zh":"be replaced by electronic documents 指被數碼檔案取代。"},{"en":"Some schools have replaced paper forms by electronic documents for applications.","zh":"有些學校已用電子文件取代紙本申請表。"},{"en":"Paper may not be fully replaced when physical marking or shared discussion is still useful.","zh":"當實體標記或共同討論仍有用時，紙張未必會被完全取代。"},{"en":"This phrase describes a shift from physical to digital records.","zh":"這個短語描述從實體記錄轉向數碼記錄。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":23},{"front":"electronic documents","meaning":"電子文件","examples":[{"en":"Electronic documents are useful but cannot fully replace paper.","zh":"電子文件很有用，但不能完全取代紙張。"},{"en":"Electronic documents are digital files such as PDFs, word-processing files, or online forms.","zh":"electronic documents 指 PDF、文字處理檔案或網上表格等數碼檔案。"},{"en":"A company may store electronic documents in a shared drive.","zh":"公司可能把電子文件儲存在共享雲端硬碟中。"},{"en":"Electronic documents are easy to search and send, but they may not support every kind of group work.","zh":"電子文件容易搜尋和發送，但未必支援每一種小組工作。"},{"en":"This phrase is similar to digital documents.","zh":"這個短語與 digital documents 意思相近。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":23},{"front":"be inexpensive to buy","meaning":"購買成本低廉","examples":[{"en":"Paper may be inexpensive to buy, but that is not the main argument.","zh":"紙張購買成本可能低廉，但這不是主要論點。"},{"en":"To be inexpensive to buy means to cost little money to purchase.","zh":"be inexpensive to buy 指購買時花費很少金錢。"},{"en":"Basic notebooks are inexpensive to buy, so students can replace them easily.","zh":"基本筆記簿購買成本低廉，所以學生可以容易替換。"},{"en":"Low price can be an advantage, but it may not explain why a tool remains useful.","zh":"低價格可以是一項優點，但未必能解釋為何工具仍有用。"},{"en":"This phrase focuses on purchase cost.","zh":"這個短語聚焦購買成本。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":23},{"front":"contribute to management theories","meaning":"對管理理論作出貢獻","examples":[{"en":"Paper contributed to management practices in industrial offices.","zh":"紙張對工業辦公室的管理實踐作出貢獻。"},{"en":"To contribute to management theories means to help develop ideas about how organisations should be managed.","zh":"contribute to management theories 指幫助發展關於組織應如何管理的想法。"},{"en":"Research on teamwork can contribute to management theories about cooperation.","zh":"關於團隊合作的研究可以對協作管理理論作出貢獻。"},{"en":"Practical tools can influence theories because they change what managers can measure and control.","zh":"實用工具可以影響理論，因為它們改變管理者能衡量和控制的東西。"},{"en":"This phrase connects real workplace practice with broader ideas about management.","zh":"這個短語把真實工作場所實踐與更廣泛管理思想連接起來。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":23},{"front":"change old habits","meaning":"改變舊習慣","examples":[{"en":"Some people think paper survives because people need time to change old habits.","zh":"有些人認為紙張繼續存在，是因為人們需要時間改變舊習慣。"},{"en":"To change old habits means to stop familiar behaviours and develop new ones.","zh":"change old habits 指停止熟悉的行為並建立新行為。"},{"en":"A student may need months to change old habits such as studying only the night before a test.","zh":"學生可能需要幾個月來改變考試前一晚才溫習等舊習慣。"},{"en":"Changing habits is difficult because familiar actions feel easier than new routines.","zh":"改變習慣很困難，因為熟悉行動比新習慣感覺更容易。"},{"en":"This phrase is useful when discussing behaviour change.","zh":"討論行為改變時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":24},{"front":"facilitate collaboration","meaning":"促進協作","examples":[{"en":"Paper can facilitate collaboration among colleagues.","zh":"紙張可以促進同事之間的協作。"},{"en":"To facilitate collaboration means to make it easier for people to work together.","zh":"facilitate collaboration 指令人們更容易一起工作。"},{"en":"A shared table of printed drafts can facilitate collaboration during editing.","zh":"一張放滿印刷草稿的共享桌面可以在編輯期間促進協作。"},{"en":"Collaboration improves when people can see the same information and discuss it directly.","zh":"當人們可以看見同一資訊並直接討論時，協作會改善。"},{"en":"This phrase is useful for explaining how tools support teamwork.","zh":"解釋工具如何支援團隊合作時，這個短語很有用。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":24},{"front":"be useful for implementing tasks","meaning":"有助執行任務","examples":[{"en":"Paper is useful for implementing and managing tasks.","zh":"紙張有助執行和管理任務。"},{"en":"To be useful for implementing tasks means to help people put plans or decisions into action.","zh":"be useful for implementing tasks 指幫助人們把計劃或決定付諸行動。"},{"en":"A printed checklist is useful for implementing tasks during an event.","zh":"印刷清單有助在活動期間執行任務。"},{"en":"Paper reminders can help workers move from discussion to actual action.","zh":"紙本提醒可以幫助職員從討論轉向實際行動。"},{"en":"This phrase focuses on carrying out work, not just planning it.","zh":"這個短語聚焦執行工作，而不只是計劃工作。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":24},{"front":"managing tasks","meaning":"管理任務","examples":[{"en":"Paper can help people organise and manage tasks.","zh":"紙張可以幫助人們組織和管理任務。"},{"en":"Managing tasks means planning, tracking, prioritising, and completing work that needs to be done.","zh":"managing tasks 指計劃、追蹤、排序和完成需要做的工作。"},{"en":"A student manages tasks by writing homework deadlines in a planner.","zh":"學生透過在計劃簿中寫下功課截止日期來管理任務。"},{"en":"Good task management prevents people from forgetting urgent work.","zh":"良好任務管理可以防止人們忘記緊急工作。"},{"en":"This phrase is useful in school, office, and personal organisation.","zh":"這個短語適用於學校、辦公室和個人整理。"}],"source":"137 - Paper or Computer?.pdf","sourcePage":24}],"ielts/reading/passage-2/Practice 138":[{"front":"Have Teenagers Always Existed?","meaning":"青少年是否一直存在？","examples":[{"en":"The passage asks whether teenagers have always existed.","zh":"文章問青少年是否一直存在。"},{"en":"“Have teenagers always existed?” asks whether the teenage stage has been part of human life since ancient times.","zh":"「青少年是否一直存在？」是在問青少年階段是否自古以來就是人類生活的一部分。"},{"en":"A teacher may ask “Have teenagers always existed?” to make students think about history, biology, and society.","zh":"老師可能問「青少年是否一直存在？」以令學生思考歷史、生物學和社會。"},{"en":"This question matters because modern adolescence may have evolved at a particular point in human development.","zh":"這個問題很重要，因為現代青春期可能是在某個人類發展階段演化出來的。"},{"en":"Asking whether teenagers have always existed helps us see adolescence as something that may have a history, not just a natural fact.","zh":"問青少年是否一直存在，有助我們把青春期看成可能有歷史的事物，而不只是自然事實。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":1},{"front":"our ancestor","meaning":"我們的祖先","examples":[{"en":"Our ancestor, Homo erectus, may not have had culture or language.","zh":"我們的祖先直立人可能沒有文化或語言。"},{"en":"Our ancestor means an earlier human or animal from whom later humans or species developed.","zh":"我們的祖先是指較早期的人類或動物，後來的人類或物種由其發展而來。"},{"en":"In science class, students learn that our ancestors lived very differently from us.","zh":"在科學課中，學生學到我們的祖先生活方式與我們非常不同。"},{"en":"Studying our ancestors helps researchers understand how modern humans changed over time.","zh":"研究我們的祖先有助研究人員理解現代人類如何隨時間改變。"},{"en":"When we say “our ancestor,” we are looking back at earlier members of the human family.","zh":"當我們說「我們的祖先」時，就是回望人類家族中較早期的成員。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":1},{"front":"Homo erectus","meaning":"直立人","examples":[{"en":"Homo erectus may not have had culture or even language.","zh":"直立人可能沒有文化，甚至沒有語言。"},{"en":"Homo erectus was an early human species that lived long before modern humans.","zh":"直立人是一種早期人類物種，生活在現代人類之前很久。"},{"en":"Students may study Homo erectus to understand early human walking, tools, and survival.","zh":"學生可能研究直立人，以理解早期人類行走、工具和生存方式。"},{"en":"Fossils of Homo erectus help scientists compare ancient and modern human development.","zh":"直立人化石幫助科學家比較古代和現代人類發展。"},{"en":"Homo erectus is important because it may show when some human-like features first appeared.","zh":"直立人很重要，因為它可能顯示某些類似人類的特徵何時首次出現。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":1},{"front":"may not have had","meaning":"可能沒有","examples":[{"en":"Homo erectus may not have had culture or even language.","zh":"直立人可能沒有文化，甚至沒有語言。"},{"en":"May not have had means it is possible that someone or something did not possess or experience something in the past.","zh":"may not have had 是指某人或某物在過去可能沒有擁有或經歷某事。"},{"en":"The old village may not have had electricity when my grandparents were young.","zh":"我祖父母年輕時，那條舊村可能沒有電力。"},{"en":"A child who failed the test may not have had enough time to revise.","zh":"測驗不合格的孩子可能沒有足夠時間溫習。"},{"en":"This phrase is useful when we are unsure about the past and only have limited evidence.","zh":"當我們對過去不確定，而且只有有限證據時，這個短語很有用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":1},{"front":"culture or even language","meaning":"文化甚至語言","examples":[{"en":"Some researchers ask whether Homo erectus had culture or even language.","zh":"有些研究人員問直立人是否有文化甚至語言。"},{"en":"Culture or even language refers to shared customs, ideas, communication, and possibly spoken systems.","zh":"文化甚至語言是指共同習俗、思想、溝通，甚至可能包括口語系統。"},{"en":"A society without writing may still have culture or even language through stories and daily habits.","zh":"沒有文字的社會仍可能透過故事和日常習慣擁有文化甚至語言。"},{"en":"If ancient humans had culture or even language, they may have shared knowledge more effectively.","zh":"如果古人類有文化甚至語言，他們可能能更有效地分享知識。"},{"en":"The phrase “or even language” suggests language is an especially advanced possibility.","zh":"「甚至語言」這個說法暗示語言是一種尤其進階的可能性。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":1},{"front":"be contested","meaning":"受到爭議","examples":[{"en":"The question has been contested in the past few years.","zh":"這個問題在過去幾年受到爭議。"},{"en":"If an idea is contested, people disagree about it and argue over whether it is true.","zh":"如果一個想法受到爭議，即是人們對它是否真實有分歧和爭論。"},{"en":"The school rule was contested by parents who thought it was unfair.","zh":"這條校規受到家長爭議，因為他們認為它不公平。"},{"en":"Scientific claims are often contested when evidence is limited or interpreted differently.","zh":"當證據有限或有不同解讀時，科學說法常受到爭議。"},{"en":"A contested question needs careful evidence rather than quick assumptions.","zh":"受到爭議的問題需要仔細證據，而不是倉促假設。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":1},{"front":"in the past few years","meaning":"在過去幾年","examples":[{"en":"The issue has been contested in the past few years.","zh":"這個議題在過去幾年受到爭議。"},{"en":"In the past few years means during the recent period of several years before now.","zh":"在過去幾年是指現在之前最近幾年的期間。"},{"en":"In the past few years, many schools have used more online learning tools.","zh":"在過去幾年，許多學校使用了更多網上學習工具。"},{"en":"A topic may become more important in the past few years because new evidence appears.","zh":"一個題目可能因新證據出現而在過去幾年變得更重要。"},{"en":"This phrase is useful when describing recent changes or debates.","zh":"描述近期變化或爭論時，這個短語很有用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":1},{"front":"anthropologists","meaning":"人類學家","examples":[{"en":"Some anthropologists claim evidence of an adolescent phase.","zh":"有些人類學家聲稱有青春期階段的證據。"},{"en":"Anthropologists are scholars who study humans, human societies, culture, and evolution.","zh":"人類學家是研究人類、人類社會、文化和演化的學者。"},{"en":"Anthropologists may study ancient bones, tools, languages, or family customs.","zh":"人類學家可能研究古代骨骼、工具、語言或家庭習俗。"},{"en":"When anthropologists examine fossils, they try to understand how earlier humans lived.","zh":"當人類學家檢查化石時，他們嘗試理解早期人類如何生活。"},{"en":"Anthropologists help connect biology with culture when studying human development.","zh":"人類學家研究人類發展時，幫助把生物學與文化連繫起來。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":1},{"front":"claim evidence of","meaning":"聲稱有……的證據","examples":[{"en":"Some anthropologists claim evidence of adolescence in human fossils.","zh":"有些人類學家聲稱在人類化石中有青春期的證據。"},{"en":"To claim evidence of something means to say that proof or signs of it have been found.","zh":"聲稱有某事的證據，是指說已找到其證明或跡象。"},{"en":"Scientists may claim evidence of water on another planet after studying rock samples.","zh":"科學家研究岩石樣本後，可能聲稱有另一顆行星存在水的證據。"},{"en":"A teacher should ask students to support their claim with evidence from the text.","zh":"老師應要求學生用文本證據支持自己的說法。"},{"en":"When researchers claim evidence of an idea, other experts may check whether the evidence is strong enough.","zh":"當研究人員聲稱有某個想法的證據時，其他專家可能會檢查證據是否足夠有力。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":1},{"front":"adolescent phase","meaning":"青春期階段","examples":[{"en":"Researchers have looked for an adolescent phase in human fossils.","zh":"研究人員在人類化石中尋找青春期階段。"},{"en":"An adolescent phase is the period between childhood and adulthood when the body and behaviour change.","zh":"青春期階段是童年與成年之間，身體和行為發生變化的時期。"},{"en":"In modern humans, the adolescent phase often includes rapid growth and growing independence.","zh":"在現代人類中，青春期階段通常包括快速生長和逐漸獨立。"},{"en":"If ancient fossils show an adolescent phase, it may mean early humans developed more like us than expected.","zh":"如果古代化石顯示青春期階段，可能意味著早期人類的發育比預期更像我們。"},{"en":"Studying the adolescent phase helps scientists understand how humans reach maturity.","zh":"研究青春期階段幫助科學家理解人類如何達到成熟。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":1},{"front":"human fossils","meaning":"人類化石","examples":[{"en":"Evidence of adolescence may be found in human fossils.","zh":"青春期的證據可能在人類化石中被發現。"},{"en":"Human fossils are preserved remains or traces of ancient humans.","zh":"人類化石是古代人類保存下來的遺骸或痕跡。"},{"en":"Human fossils can include bones, teeth, skulls, or footprints.","zh":"人類化石可以包括骨骼、牙齒、頭骨或足跡。"},{"en":"Human fossils are rare, so each discovery can change scientific understanding.","zh":"人類化石很稀少，所以每項發現都可能改變科學理解。"},{"en":"Scientists study human fossils to learn about growth, movement, diet, and survival.","zh":"科學家研究人類化石，以了解生長、移動、飲食和生存。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":1},{"front":"not merely","meaning":"不僅僅是","examples":[{"en":"This is not merely an academic debate.","zh":"這不僅僅是一場學術爭論。"},{"en":"Not merely means not only or not just one simple thing.","zh":"not merely 是指不只是或不僅是一件簡單的事。"},{"en":"Learning English is not merely memorising words; it also involves using them in real situations.","zh":"學英文不僅僅是背單字；它也涉及在真實情境中使用它們。"},{"en":"A hospital is not merely a building because it also provides care, safety, and trust.","zh":"醫院不僅僅是一座建築，因為它也提供照顧、安全和信任。"},{"en":"This phrase is useful when you want to show that something has wider importance.","zh":"當你想顯示某事有更廣泛重要性時，這個短語很有用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":2},{"front":"academic debate","meaning":"學術爭論","examples":[{"en":"The origin of adolescence is not merely an academic debate.","zh":"青春期的起源不僅僅是一場學術爭論。"},{"en":"An academic debate is a serious discussion among scholars about evidence, ideas, or theories.","zh":"學術爭論是學者之間關於證據、思想或理論的嚴肅討論。"},{"en":"University students may join an academic debate about whether exams measure real ability.","zh":"大學生可能參與關於考試是否量度真實能力的學術爭論。"},{"en":"An academic debate can affect real life when it changes education, medicine, or public policy.","zh":"當學術爭論改變教育、醫學或公共政策時，它可以影響現實生活。"},{"en":"Calling something an academic debate suggests it involves research, argument, and evidence.","zh":"稱某事為學術爭論，暗示它涉及研究、論辯和證據。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":2},{"front":"the only animals on Earth to","meaning":"地球上唯一會……的動物","examples":[{"en":"Humans are the only animals on Earth to have a teenage phase.","zh":"人類是地球上唯一有青少年階段的動物。"},{"en":"The only animals on Earth to do something means no other known animals do that same thing.","zh":"地球上唯一會做某事的動物，是指沒有其他已知動物做同一件事。"},{"en":"Humans are not the only animals on Earth to use tools, because some birds and apes also do so.","zh":"人類不是地球上唯一會使用工具的動物，因為有些鳥類和猿類也會使用工具。"},{"en":"Saying humans are the only animals on Earth to have teenagers makes adolescence sound unusual.","zh":"說人類是地球上唯一有青少年的動物，令青春期顯得不尋常。"},{"en":"This phrase compares one species with all other animals on the planet.","zh":"這個短語把一個物種與地球上所有其他動物作比較。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":2},{"front":"teenage phase","meaning":"青少年階段","examples":[{"en":"Humans today are the only animals with a teenage phase.","zh":"今天的人類是唯一有青少年階段的動物。"},{"en":"A teenage phase is the stage between childhood and adulthood, usually involving growth and social change.","zh":"青少年階段是童年與成年之間的階段，通常涉及生長和社會變化。"},{"en":"During the teenage phase, young people often become more independent from their parents.","zh":"在青少年階段，年輕人通常變得更獨立於父母。"},{"en":"A teenage phase may allow humans more time to learn skills before full adulthood.","zh":"青少年階段可能讓人類在完全成年前有更多時間學習技能。"},{"en":"The passage asks why humans have such a clear teenage phase when other animals do not.","zh":"文章問為何人類有如此清晰的青少年階段，而其他動物沒有。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":2},{"front":"have very little idea why","meaning":"幾乎不知道原因","examples":[{"en":"We have very little idea why humans have a teenage phase.","zh":"我們幾乎不知道人類為何有青少年階段。"},{"en":"To have very little idea why means to know almost nothing about the reason.","zh":"have very little idea why 是指幾乎不知道原因。"},{"en":"Doctors may have very little idea why a rare symptom appears until more tests are done.","zh":"在進行更多檢查前，醫生可能幾乎不知道罕見症狀出現的原因。"},{"en":"Students may have very little idea why they made mistakes if feedback is unclear.","zh":"如果回饋不清楚，學生可能幾乎不知道自己犯錯的原因。"},{"en":"This phrase shows uncertainty and the need for more investigation.","zh":"這個短語顯示不確定性和進一步調查的需要。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":2},{"front":"establish exactly when","meaning":"確切確定何時","examples":[{"en":"Researchers want to establish exactly when adolescence first evolved.","zh":"研究人員想確切確定青春期何時首次演化出來。"},{"en":"To establish exactly when something happened means to determine the precise time or period.","zh":"確切確定某事何時發生，是指判斷其精確時間或時期。"},{"en":"Historians try to establish exactly when an old building was constructed.","zh":"歷史學家嘗試確切確定一座古建築何時建成。"},{"en":"Scientists need strong evidence to establish exactly when a species first appeared.","zh":"科學家需要有力證據來確切確定某物種何時首次出現。"},{"en":"This phrase is used when timing matters and a rough guess is not enough.","zh":"當時間點很重要，而粗略猜測不足夠時，這個短語很有用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":2},{"front":"adolescence first evolved","meaning":"青春期首次演化出來","examples":[{"en":"Scientists are trying to find out when adolescence first evolved.","zh":"科學家正嘗試找出青春期何時首次演化出來。"},{"en":"Adolescence first evolved means the teenage stage first appeared in human evolutionary history.","zh":"青春期首次演化出來，是指青少年階段在人類演化史中首次出現。"},{"en":"If adolescence first evolved with modern humans, it may be linked to large brains and long learning.","zh":"如果青春期與現代人類一起首次演化出來，它可能與大型大腦和長期學習有關。"},{"en":"If adolescence first evolved earlier, scientists must rethink older theories of human development.","zh":"如果青春期更早首次演化出來，科學家就必須重新思考舊有人類發展理論。"},{"en":"The question of when adolescence first evolved connects fossils with modern human behaviour.","zh":"青春期何時首次演化出來這個問題，把化石與現代人類行為連繫起來。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":2},{"front":"find out","meaning":"找出","examples":[{"en":"Researchers want to find out what changes were linked to adolescence.","zh":"研究人員想找出哪些變化與青春期有關。"},{"en":"To find out means to discover information by asking, checking, or researching.","zh":"find out 是指透過詢問、檢查或研究來發現資訊。"},{"en":"A student may read the timetable to find out when the exam starts.","zh":"學生可能閱讀時間表，以找出考試何時開始。"},{"en":"Doctors run tests to find out what is causing a patient’s pain.","zh":"醫生進行檢查，以找出病人疼痛的原因。"},{"en":"Researchers find out new facts by comparing evidence from many sources.","zh":"研究人員透過比較多個來源的證據來找出新事實。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":2},{"front":"what sorts of changes","meaning":"哪些種類的變化","examples":[{"en":"They want to know what sorts of changes adolescence was associated with.","zh":"他們想知道青春期與哪些種類的變化有關。"},{"en":"What sorts of changes means what kinds or types of changes.","zh":"what sorts of changes 是指哪些種類或類型的變化。"},{"en":"A doctor may ask what sorts of changes a patient noticed after taking medicine.","zh":"醫生可能問病人服藥後注意到哪些種類的變化。"},{"en":"Teachers ask what sorts of changes help students learn better.","zh":"老師會問哪些種類的變化有助學生學得更好。"},{"en":"This phrase is useful when the exact changes are not yet known.","zh":"當確切變化尚未知道時，這個短語很有用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":2},{"front":"be associated with","meaning":"與……有關","examples":[{"en":"Adolescence may be associated with changes in bodies and lifestyles.","zh":"青春期可能與身體和生活方式的變化有關。"},{"en":"To be associated with something means to be connected or linked with it.","zh":"be associated with 是指與某事有連繫或關聯。"},{"en":"Poor sleep is often associated with weak concentration in class.","zh":"睡眠不足常與課堂專注力差有關。"},{"en":"A festival may be associated with certain foods, clothes, and songs.","zh":"節日可能與某些食物、服飾和歌曲有關。"},{"en":"In science, being associated with something does not always prove direct cause.","zh":"在科學中，與某事有關不一定證明直接因果關係。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":2},{"front":"bodies and lifestyles","meaning":"身體和生活方式","examples":[{"en":"Adolescence may be linked to changes in bodies and lifestyles.","zh":"青春期可能與身體和生活方式的變化有關。"},{"en":"Bodies and lifestyles refer to physical development and the ways people live, work, eat, and behave.","zh":"身體和生活方式是指身體發展，以及人們生活、工作、飲食和行為的方式。"},{"en":"Teenagers experience changes in bodies and lifestyles when they grow taller and take on more independence.","zh":"青少年長高並承擔更多獨立性時，會經歷身體和生活方式的變化。"},{"en":"Urbanisation can change people’s bodies and lifestyles through diet, exercise, and stress.","zh":"城市化可以透過飲食、運動和壓力改變人的身體和生活方式。"},{"en":"Studying bodies and lifestyles helps researchers understand both biology and daily life.","zh":"研究身體和生活方式幫助研究人員理解生物學和日常生活。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":2},{"front":"help us understand","meaning":"幫助我們理解","examples":[{"en":"Studying adolescence could help us understand its purpose.","zh":"研究青春期可以幫助我們理解其目的。"},{"en":"To help us understand something means to make it clearer or easier to explain.","zh":"help us understand 是指令某事更清楚或更容易解釋。"},{"en":"A diagram can help us understand how blood moves through the heart.","zh":"圖表可以幫助我們理解血液如何流經心臟。"},{"en":"Real examples help us understand difficult grammar more quickly.","zh":"真實例子幫助我們更快理解困難文法。"},{"en":"Fossils help us understand human development by showing evidence from the past.","zh":"化石透過展示過去證據，幫助我們理解人類發展。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":3},{"front":"uniquely","meaning":"獨有地","examples":[{"en":"Why do we, uniquely, have a growth spurt so late in life?","zh":"為何我們獨有地在生命中如此晚的階段有急速生長期？"},{"en":"Uniquely means in a way that is special to one person, group, or species and not shared by others.","zh":"uniquely 是指以某人、群體或物種特有，而其他人或物種沒有的方式。"},{"en":"Humans uniquely use complex language to discuss the distant past and future.","zh":"人類獨有地使用複雜語言討論遙遠過去和未來。"},{"en":"A school may be uniquely strong in music because it has special teachers and facilities.","zh":"一間學校可能因有特殊老師和設施，而在音樂方面獨有地強。"},{"en":"The word uniquely highlights that human adolescence seems different from what other animals experience.","zh":"uniquely 這個詞強調人類青春期似乎不同於其他動物的經歷。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":3},{"front":"growth spurt","meaning":"急速生長期","examples":[{"en":"Humans have a growth spurt late in life.","zh":"人類在生命較晚階段有急速生長期。"},{"en":"A growth spurt is a short period when the body grows much faster than usual.","zh":"急速生長期是身體比平常快很多地生長的一段短時期。"},{"en":"Parents may notice a teenager’s growth spurt when shoes and clothes suddenly become too small.","zh":"當鞋和衣服突然變小時，父母可能注意到青少年的急速生長期。"},{"en":"A growth spurt can require more food, sleep, and energy.","zh":"急速生長期可能需要更多食物、睡眠和能量。"},{"en":"In humans, the adolescent growth spurt is unusual because it involves much of the body.","zh":"在人類中，青春期急速生長很不尋常，因為它涉及身體大部分部分。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":3},{"front":"so late in life","meaning":"在生命中如此晚的階段","examples":[{"en":"Humans have a growth spurt so late in life.","zh":"人類在生命中如此晚的階段有急速生長期。"},{"en":"So late in life means at a surprisingly late stage of development or age.","zh":"so late in life 是指在發育或年齡中令人驚訝地晚的階段。"},{"en":"It is unusual for a person to start a new career so late in life, but it can still be successful.","zh":"一個人在生命中如此晚的階段開始新事業很不尋常，但仍可以成功。"},{"en":"Humans grow rapidly so late in life compared with many other animals.","zh":"與許多其他動物相比，人類在生命中如此晚的階段快速生長。"},{"en":"This phrase stresses that the timing is unexpected.","zh":"這個短語強調時間點出乎意料。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":3},{"front":"until recently","meaning":"直到最近","examples":[{"en":"Until recently, the dominant explanation focused on brain growth.","zh":"直到最近，主流解釋集中於大腦生長。"},{"en":"Until recently means up to a short time ago.","zh":"until recently 是指直到不久之前。"},{"en":"Until recently, many students used paper dictionaries more often than apps.","zh":"直到最近，許多學生使用紙本字典比應用程式更頻繁。"},{"en":"A theory may be accepted until recently, when new evidence challenges it.","zh":"一個理論可能直到最近都被接受，直到新證據挑戰它。"},{"en":"This phrase signals that an older idea has begun to change.","zh":"這個短語表示舊想法已開始改變。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":3},{"front":"dominant explanation","meaning":"主流解釋","examples":[{"en":"The dominant explanation linked delayed growth to large brains.","zh":"主流解釋把延遲生長與大型大腦聯繫起來。"},{"en":"A dominant explanation is the main or most widely accepted explanation.","zh":"主流解釋是主要或最廣泛被接受的解釋。"},{"en":"For many years, the dominant explanation for poor exam results was lack of effort.","zh":"多年來，考試成績差的主流解釋是缺乏努力。"},{"en":"A dominant explanation can change when new research gives a better answer.","zh":"當新研究提供更好答案時，主流解釋可以改變。"},{"en":"In science, even a dominant explanation must be tested against evidence.","zh":"在科學中，即使是主流解釋，也必須用證據檢驗。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":3},{"front":"physical growth","meaning":"身體生長","examples":[{"en":"Physical growth may be delayed by the need to grow large brains.","zh":"身體生長可能因需要發育出大型大腦而延遲。"},{"en":"Physical growth means the body’s increase in size, height, strength, or maturity.","zh":"身體生長是指身體在大小、身高、力量或成熟度上的增加。"},{"en":"Doctors measure children’s physical growth by checking height and weight.","zh":"醫生透過檢查身高和體重來量度兒童身體生長。"},{"en":"Poor nutrition can slow physical growth and delay development.","zh":"營養不良會減慢身體生長並延遲發育。"},{"en":"Human physical growth may follow a different pattern from other animals.","zh":"人類身體生長可能遵循與其他動物不同的模式。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":3},{"front":"be delayed by","meaning":"因……而延遲","examples":[{"en":"Physical growth is delayed by our need to grow large brains.","zh":"身體生長因我們需要發育出大型大腦而延遲。"},{"en":"To be delayed by something means to happen later because of that cause.","zh":"be delayed by 是指因某原因而較遲發生。"},{"en":"The bus was delayed by heavy traffic.","zh":"巴士因交通繁忙而延誤。"},{"en":"A project may be delayed by missing documents or unclear instructions.","zh":"項目可能因文件缺失或指示不清而延遲。"},{"en":"In the theory, body growth is delayed by the energy demands of brain development.","zh":"在這個理論中，身體生長因大腦發育的能量需求而延遲。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":3},{"front":"grow large brains","meaning":"發育出大型大腦","examples":[{"en":"Humans need time to grow large brains.","zh":"人類需要時間發育出大型大腦。"},{"en":"To grow large brains means to develop bigger and more complex brains during childhood.","zh":"發育出大型大腦是指在童年期間發展出更大和更複雜的大腦。"},{"en":"Babies need food, care, and time to grow large brains and learn basic skills.","zh":"嬰兒需要食物、照顧和時間來發育出大型大腦並學習基本技能。"},{"en":"Growing large brains may require energy that could otherwise support faster body growth.","zh":"發育出大型大腦可能需要本可支持更快身體生長的能量。"},{"en":"This idea helps explain why human children depend on adults for many years.","zh":"這個想法有助解釋為何人類兒童多年來依賴成年人。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":3},{"front":"behaviour patterns","meaning":"行為模式","examples":[{"en":"Children need time to learn behaviour patterns associated with humanity.","zh":"兒童需要時間學習與人類特性有關的行為模式。"},{"en":"Behaviour patterns are repeated ways of acting, reacting, speaking, or interacting.","zh":"行為模式是反覆出現的行動、反應、說話或互動方式。"},{"en":"Children learn behaviour patterns such as greeting people, sharing, and waiting for their turn.","zh":"兒童學習打招呼、分享和輪候等行為模式。"},{"en":"Behaviour patterns can be shaped by family, school, culture, and daily routine.","zh":"行為模式可以由家庭、學校、文化和日常習慣塑造。"},{"en":"Human behaviour patterns are complex, so young people need time to learn them.","zh":"人類行為模式很複雜，所以年輕人需要時間學習。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":3},{"front":"associated with humanity","meaning":"與人類特性有關","examples":[{"en":"Speech and social interaction are behaviour patterns associated with humanity.","zh":"說話和社交互動是與人類特性有關的行為模式。"},{"en":"Associated with humanity means connected with qualities or behaviours typical of human beings.","zh":"與人類特性有關，是指與人類典型品質或行為相連。"},{"en":"Storytelling is often associated with humanity because people use stories to share memory and values.","zh":"說故事常與人類特性有關，因為人們用故事分享記憶和價值。"},{"en":"Cooperation and language are strongly associated with humanity’s social life.","zh":"合作和語言與人類社會生活密切相關。"},{"en":"This phrase points to features that make human life different from that of many other animals.","zh":"這個短語指向令人類生活不同於許多其他動物的特徵。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":3},{"front":"social interaction","meaning":"社交互動","examples":[{"en":"Humans need to learn speaking and social interaction.","zh":"人類需要學習說話和社交互動。"},{"en":"Social interaction means communication and behaviour between people.","zh":"社交互動是指人與人之間的溝通和行為。"},{"en":"Children practise social interaction when they play, argue, apologise, and share.","zh":"兒童在玩耍、爭論、道歉和分享時練習社交互動。"},{"en":"Poor social interaction can make teamwork difficult in school or work.","zh":"差劣社交互動會令學校或工作中的團隊合作困難。"},{"en":"Learning social interaction takes time because people must understand rules, emotions, and relationships.","zh":"學習社交互動需要時間，因為人們必須理解規則、情緒和關係。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":4},{"front":"and so on","meaning":"等等","examples":[{"en":"Children learn speaking, social interaction and so on.","zh":"兒童學習說話、社交互動等等。"},{"en":"And so on means and other similar things.","zh":"and so on 是指以及其他類似事物。"},{"en":"Students need pens, notebooks, textbooks and so on for class.","zh":"學生上課需要筆、筆記簿、課本等等。"},{"en":"A healthy routine includes sleep, exercise, balanced meals and so on.","zh":"健康習慣包括睡眠、運動、均衡飲食等等。"},{"en":"This phrase is useful when the reader can easily guess the remaining examples.","zh":"當讀者能輕易猜到其餘例子時，這個短語很有用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":4},{"front":"fend for themselves","meaning":"照顧自己；自力更生","examples":[{"en":"Young humans cannot easily fend for themselves.","zh":"年幼人類不能輕易照顧自己。"},{"en":"To fend for themselves means to take care of themselves without help from others.","zh":"fend for themselves 是指在沒有他人幫助下照顧自己。"},{"en":"Young children cannot fend for themselves because they need food, safety, and guidance.","zh":"年幼兒童不能自力更生，因為他們需要食物、安全和指導。"},{"en":"A student living abroad learns to fend for herself by cooking, budgeting, and solving daily problems.","zh":"在海外生活的學生透過煮食、做預算和解決日常問題，學會自力更生。"},{"en":"Human children depend on adults for a long time before they can fend for themselves.","zh":"人類兒童在能照顧自己之前，會長時間依賴成年人。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":4},{"front":"stay small and look youthful","meaning":"保持細小和年輕外表","examples":[{"en":"It may be useful for children to stay small and look youthful.","zh":"兒童保持細小和年輕外表可能有用。"},{"en":"To stay small and look youthful means to remain physically young-looking and not fully adult in appearance.","zh":"保持細小和年輕外表，是指外貌上維持年幼狀態，未完全像成人。"},{"en":"A young animal that stays small and looks youthful may attract more care from adults.","zh":"保持細小和年輕外表的幼小動物，可能吸引成年個體更多照顧。"},{"en":"Children who look youthful may encourage parents to continue protecting and feeding them.","zh":"外表年輕的兒童可能鼓勵父母繼續保護和餵養他們。"},{"en":"In the theory, staying small and looking youthful helps young humans receive support for longer.","zh":"在這個理論中，保持細小和年輕外表幫助年幼人類更長時間獲得支援。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":4},{"front":"be motivated to","meaning":"有動力去","examples":[{"en":"Parents are motivated to continue looking after young children.","zh":"父母有動力繼續照顧年幼兒童。"},{"en":"To be motivated to do something means to have a reason or desire to do it.","zh":"be motivated to 是指有理由或願望去做某事。"},{"en":"Students are motivated to revise when they see clear progress.","zh":"當學生看見清晰進步時，他們會有動力溫習。"},{"en":"Workers may be motivated to stay when they feel respected and fairly paid.","zh":"當員工感到受尊重並獲公平薪酬時，可能有動力留下。"},{"en":"In this theory, adults are motivated to care for children because they still look young and dependent.","zh":"在這個理論中，成年人有動力照顧兒童，因為他們看起來仍年幼且依賴人。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":4},{"front":"continue looking after","meaning":"繼續照顧","examples":[{"en":"Adults continue looking after children who still look youthful.","zh":"成年人繼續照顧仍然看起來年幼的兒童。"},{"en":"To continue looking after someone means to keep caring for and protecting that person.","zh":"continue looking after 是指持續照顧和保護某人。"},{"en":"Parents continue looking after a sick child until the child recovers.","zh":"父母繼續照顧生病的孩子，直到孩子康復。"},{"en":"A community may continue looking after elderly residents by delivering meals and medicine.","zh":"社區可以透過送飯和藥物，繼續照顧年長居民。"},{"en":"Children who cannot survive alone need adults to continue looking after them.","zh":"不能獨自生存的兒童需要成年人繼續照顧。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":4},{"front":"what’s more","meaning":"此外","examples":[{"en":"What’s more, studies of mammals show a link between brain size and development.","zh":"此外，哺乳動物研究顯示大腦大小與發育之間有關係。"},{"en":"What’s more means in addition, especially when adding another important point.","zh":"what’s more 是指此外，尤其用於加入另一個重要重點。"},{"en":"The course is useful; what’s more, it is free.","zh":"這門課很有用；此外，它是免費的。"},{"en":"The restaurant is close to the station; what’s more, the food is affordable.","zh":"這間餐廳靠近車站；此外，食物價格可負擔。"},{"en":"This phrase helps writers add support to an argument.","zh":"這個短語幫助作者為論點加入支持。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":4},{"front":"studies of mammals","meaning":"哺乳動物研究","examples":[{"en":"Studies of mammals show a relationship between brain size and development.","zh":"哺乳動物研究顯示大腦大小與發育之間有關係。"},{"en":"Studies of mammals are scientific investigations of warm-blooded animals that feed their young with milk.","zh":"哺乳動物研究是對以乳汁餵養幼兒的溫血動物所作的科學調查。"},{"en":"Studies of mammals may compare humans, apes, dolphins, and mice.","zh":"哺乳動物研究可能比較人類、猿類、海豚和老鼠。"},{"en":"Studies of mammals help scientists understand growth patterns across related animals.","zh":"哺乳動物研究幫助科學家理解相關動物之間的生長模式。"},{"en":"Because humans are mammals, studies of mammals can provide clues about human development.","zh":"因為人類是哺乳動物，哺乳動物研究可以提供人類發展的線索。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":4},{"front":"a strong relationship between","meaning":"……之間的強烈關係","examples":[{"en":"There is a strong relationship between brain size and development rate.","zh":"大腦大小與發育速度之間有強烈關係。"},{"en":"A strong relationship between two things means they are closely connected.","zh":"兩件事之間的強烈關係，是指它們密切相連。"},{"en":"There is a strong relationship between daily practice and language improvement.","zh":"每日練習與語言進步之間有強烈關係。"},{"en":"A strong relationship between poor sleep and weak concentration can affect school performance.","zh":"睡眠不足與專注力差之間的強烈關係可能影響學校表現。"},{"en":"Scientists look for strong relationships between variables before building explanations.","zh":"科學家在建立解釋前，會尋找變量之間的強烈關係。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":4},{"front":"brain size","meaning":"大腦大小","examples":[{"en":"Brain size is linked to the rate of development.","zh":"大腦大小與發育速度有關。"},{"en":"Brain size means the physical size or volume of the brain.","zh":"大腦大小是指大腦的實際大小或體積。"},{"en":"Scientists compare brain size across mammals to understand development and behaviour.","zh":"科學家比較不同哺乳動物的大腦大小，以理解發育和行為。"},{"en":"Larger brain size may require longer childhood because the brain takes time and energy to grow.","zh":"較大的大腦大小可能需要較長童年，因為大腦需要時間和能量生長。"},{"en":"Brain size alone does not explain intelligence, but it can be important in evolutionary studies.","zh":"大腦大小本身不能解釋智力，但在演化研究中可以很重要。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":4},{"front":"rate of development","meaning":"發育速度","examples":[{"en":"Larger-brained animals have a slower rate of development.","zh":"大腦較大的動物發育速度較慢。"},{"en":"Rate of development means how quickly an organism grows and becomes mature.","zh":"發育速度是指生物生長並變成熟的快慢。"},{"en":"Doctors check a child’s rate of development by looking at speech, movement, and growth.","zh":"醫生透過觀察語言、活動能力和生長來檢查兒童發育速度。"},{"en":"A slow rate of development may mean a longer childhood and more learning time.","zh":"較慢的發育速度可能意味著較長童年和更多學習時間。"},{"en":"Comparing the rate of development across animals helps scientists understand life history.","zh":"比較不同動物的發育速度幫助科學家理解生命史。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":4},{"front":"larger-brained animals","meaning":"大腦較大的動物","examples":[{"en":"Larger-brained animals take longer to reach adulthood.","zh":"大腦較大的動物需要更長時間達到成年。"},{"en":"Larger-brained animals are animals with bigger brains relative to many others.","zh":"大腦較大的動物是指相對許多其他動物而言大腦較大的動物。"},{"en":"Elephants and dolphins are examples of larger-brained animals with complex social behaviour.","zh":"大象和海豚是有複雜社會行為的大腦較大的動物例子。"},{"en":"Larger-brained animals may need longer periods of learning before independence.","zh":"大腦較大的動物可能需要較長學習期才能獨立。"},{"en":"Studying larger-brained animals helps scientists understand why humans mature slowly.","zh":"研究大腦較大的動物幫助科學家理解為何人類成熟緩慢。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":5},{"front":"take longer to","meaning":"需要更長時間去","examples":[{"en":"Larger-brained animals take longer to reach adulthood.","zh":"大腦較大的動物需要更長時間去達到成年。"},{"en":"To take longer to do something means to need more time to complete it.","zh":"take longer to 是指需要更多時間完成某事。"},{"en":"A child may take longer to learn swimming if they are afraid of water.","zh":"如果孩子怕水，可能需要更長時間去學游泳。"},{"en":"Large projects take longer to finish when many people must approve each step.","zh":"當大型項目每一步都需要多人批准時，需要更長時間完成。"},{"en":"In biology, some animals take longer to mature because their development is more complex.","zh":"在生物學中，有些動物需要更長時間成熟，因為其發育更複雜。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":5},{"front":"reach adulthood","meaning":"達到成年","examples":[{"en":"Humans take a long time to reach adulthood.","zh":"人類需要很長時間達到成年。"},{"en":"To reach adulthood means to become physically or socially mature as an adult.","zh":"達到成年是指在身體或社會上成熟為成年人。"},{"en":"Young people reach adulthood legally at different ages in different countries.","zh":"年輕人在不同國家以不同年齡合法達到成年。"},{"en":"Animals that reach adulthood slowly may need more parental care.","zh":"達到成年較慢的動物可能需要更多父母照顧。"},{"en":"Human beings take many years to reach adulthood because learning and development are complex.","zh":"人類需要多年才能達到成年，因為學習和發展很複雜。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":5},{"front":"at the far end of this spectrum","meaning":"位於這個範圍的極端","examples":[{"en":"Humans are at the far end of this spectrum.","zh":"人類位於這個範圍的極端。"},{"en":"At the far end of this spectrum means at the most extreme point of a range.","zh":"at the far end of this spectrum 是指位於某個範圍中最極端的一端。"},{"en":"In a class, one student may be at the far end of the spectrum for reading speed.","zh":"在班上，一名學生可能在閱讀速度範圍的極端。"},{"en":"Humans are at the far end of the development spectrum because they mature very slowly.","zh":"人類位於發育範圍的極端，因為他們成熟非常緩慢。"},{"en":"This phrase helps compare many cases along one scale.","zh":"這個短語幫助沿著一個尺度比較許多情況。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":5},{"front":"account for","meaning":"解釋；說明……的原因","examples":[{"en":"The development of large brains may account for the teenage growth spurt.","zh":"大型大腦的發展可能解釋青少年急速生長期。"},{"en":"To account for something means to explain the reason for it.","zh":"account for 是指解釋某事的原因。"},{"en":"Heavy rain may account for the delay in the train service.","zh":"大雨可能解釋火車服務延誤的原因。"},{"en":"Lack of sleep can account for a student’s poor concentration.","zh":"睡眠不足可以解釋學生專注力差的原因。"},{"en":"A theory must account for the evidence, not ignore difficult facts.","zh":"理論必須解釋證據，而不是忽略困難事實。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":5},{"front":"the origin of adolescence","meaning":"青春期的起源","examples":[{"en":"The theory places the origin of adolescence with Homo sapiens and Neanderthals.","zh":"該理論把青春期的起源放在智人和尼安德特人身上。"},{"en":"The origin of adolescence means the point in evolutionary history when the teenage phase first appeared.","zh":"青春期的起源是指青少年階段在演化史中首次出現的時間點。"},{"en":"Scientists study fossils to investigate the origin of adolescence.","zh":"科學家研究化石，以探究青春期的起源。"},{"en":"If the origin of adolescence is recent, it may be linked to modern human brain development.","zh":"如果青春期的起源較近，它可能與現代人類大腦發展有關。"},{"en":"Understanding the origin of adolescence may explain why humans grow up so slowly.","zh":"理解青春期的起源可能解釋為何人類成長如此緩慢。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":5},{"front":"Homo sapiens","meaning":"智人","examples":[{"en":"The origin of adolescence may be linked to Homo sapiens.","zh":"青春期的起源可能與智人有關。"},{"en":"Homo sapiens is the scientific name for modern humans.","zh":"Homo sapiens 是現代人類的學名。"},{"en":"Fossils of Homo sapiens help scientists study the development of modern bodies and behaviour.","zh":"智人化石幫助科學家研究現代身體和行為的發展。"},{"en":"Homo sapiens differs from earlier humans in brain structure, culture, and technology.","zh":"智人在大腦結構、文化和技術方面不同於較早期人類。"},{"en":"In this passage, Homo sapiens may be important because modern adolescence could have begun with them.","zh":"在本文中，智人可能很重要，因為現代青春期可能由他們開始。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":5},{"front":"Neanderthals","meaning":"尼安德特人","examples":[{"en":"The theory links adolescence to Homo sapiens and Neanderthals.","zh":"該理論把青春期與智人和尼安德特人聯繫起來。"},{"en":"Neanderthals were an extinct human group that lived in Europe and parts of Asia.","zh":"尼安德特人是一個已滅絕的人類群體，曾生活於歐洲和亞洲部分地區。"},{"en":"Scientists study Neanderthals through bones, tools, and DNA.","zh":"科學家透過骨骼、工具和DNA研究尼安德特人。"},{"en":"Neanderthals may have developed differently from modern humans because they faced harsh environments.","zh":"尼安德特人可能因面對嚴酷環境而與現代人類有不同發育方式。"},{"en":"Comparing Neanderthals with Homo sapiens helps researchers understand human growth and survival.","zh":"比較尼安德特人與智人，幫助研究人員理解人類生長和生存。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":5},{"front":"starting almost 200,000 years ago","meaning":"大約二十萬年前開始","examples":[{"en":"The theory suggests adolescence began almost 200,000 years ago.","zh":"該理論認為青春期大約二十萬年前開始。"},{"en":"Starting almost 200,000 years ago means beginning roughly two hundred thousand years before the present.","zh":"大約二十萬年前開始，是指大約在距今二十萬年前開始。"},{"en":"A human trait starting almost 200,000 years ago would be very ancient but still linked to modern humans.","zh":"大約二十萬年前開始的人類特徵會非常古老，但仍與現代人類有關。"},{"en":"Fossil evidence is needed to support claims about events starting almost 200,000 years ago.","zh":"關於大約二十萬年前開始的事件，需要化石證據支持。"},{"en":"This phrase gives a broad evolutionary time frame rather than an exact date.","zh":"這個短語提供大概的演化時間框架，而不是精確日期。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":5},{"front":"the trouble is","meaning":"問題是","examples":[{"en":"The trouble is that some fossil evidence tells a different story.","zh":"問題是，有些化石證據顯示不同情況。"},{"en":"The trouble is introduces a problem or difficulty with an idea.","zh":"the trouble is 用來引入某個想法中的問題或困難。"},{"en":"The plan sounds simple; the trouble is that nobody has enough time to do it.","zh":"這個計劃聽起來簡單；問題是沒有人有足夠時間做。"},{"en":"The theory is attractive, but the trouble is that the evidence is incomplete.","zh":"這個理論很吸引，但問題是證據不完整。"},{"en":"This phrase is useful when you want to challenge a previous explanation.","zh":"當你想挑戰前面的解釋時，這個短語很有用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":5},{"front":"fossil evidence","meaning":"化石證據","examples":[{"en":"Some fossil evidence seems to tell a different story.","zh":"有些化石證據似乎顯示不同情況。"},{"en":"Fossil evidence is information from preserved bones, teeth, footprints, or other ancient remains.","zh":"化石證據是來自保存下來的骨骼、牙齒、足跡或其他古代遺骸的資訊。"},{"en":"Fossil evidence can help scientists estimate how old a species is.","zh":"化石證據可以幫助科學家估算一個物種有多古老。"},{"en":"New fossil evidence may challenge a theory that seemed correct before.","zh":"新化石證據可能挑戰以前看似正確的理論。"},{"en":"Fossil evidence is valuable, but it can be difficult to interpret when remains are incomplete.","zh":"化石證據很有價值，但當遺骸不完整時，可能難以解讀。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":5},{"front":"tell a different story","meaning":"顯示不同情況","examples":[{"en":"The fossil evidence seems to tell a different story.","zh":"化石證據似乎顯示不同情況。"},{"en":"To tell a different story means to suggest a different explanation from the one expected.","zh":"tell a different story 是指暗示一個與預期不同的解釋。"},{"en":"The company said sales were strong, but the empty shop told a different story.","zh":"公司說銷售強勁，但空蕩蕩的店舖顯示不同情況。"},{"en":"A student’s test score may tell a different story from their confident words.","zh":"學生的測驗分數可能與其自信說話顯示不同情況。"},{"en":"Fossils can tell a different story when they do not match the dominant theory.","zh":"當化石不符合主流理論時，它們可以顯示不同情況。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":6},{"front":"fossil record","meaning":"化石記錄","examples":[{"en":"The human fossil record is extremely sparse.","zh":"人類化石記錄極為稀少。"},{"en":"The fossil record is the collection of fossils that shows evidence of past life.","zh":"化石記錄是顯示過去生命證據的化石集合。"},{"en":"The fossil record helps scientists study species that no longer exist.","zh":"化石記錄幫助科學家研究已不存在的物種。"},{"en":"A sparse fossil record makes it harder to draw confident conclusions.","zh":"稀少的化石記錄令作出有信心的結論更困難。"},{"en":"The human fossil record is incomplete, so researchers must interpret it carefully.","zh":"人類化石記錄並不完整，所以研究人員必須小心解讀。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":6},{"front":"extremely sparse","meaning":"極為稀少","examples":[{"en":"The human fossil record is extremely sparse.","zh":"人類化石記錄極為稀少。"},{"en":"Extremely sparse means very limited, scattered, or rare.","zh":"極為稀少是指非常有限、分散或罕見。"},{"en":"Information about the old village is extremely sparse because few records survived.","zh":"關於舊村莊的資料極為稀少，因為少數記錄保存下來。"},{"en":"If evidence is extremely sparse, researchers must avoid overconfident conclusions.","zh":"如果證據極為稀少，研究人員必須避免過度自信的結論。"},{"en":"Fossilised children are extremely sparse, making studies of ancient adolescence difficult.","zh":"兒童化石極為稀少，令古代青春期研究變得困難。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":6},{"front":"fossilised children","meaning":"兒童化石","examples":[{"en":"The number of fossilised children is minuscule.","zh":"兒童化石的數量極少。"},{"en":"Fossilised children are preserved remains of children from the ancient past.","zh":"兒童化石是古代兒童保存下來的遺骸。"},{"en":"Fossilised children can give scientists rare clues about growth and development.","zh":"兒童化石可以給科學家關於生長和發育的罕見線索。"},{"en":"Because fossilised children are rare, each discovery may be very important.","zh":"因為兒童化石很罕見，每項發現都可能非常重要。"},{"en":"Studying fossilised children helps researchers ask whether ancient humans had childhood or adolescence like ours.","zh":"研究兒童化石幫助研究人員詢問古代人類是否有像我們一樣的童年或青春期。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":6},{"front":"minuscule","meaning":"極少的","examples":[{"en":"The number of fossilised children is minuscule.","zh":"兒童化石的數量極少。"},{"en":"Minuscule means extremely small in size, number, or amount.","zh":"minuscule 是指大小、數量或程度極小。"},{"en":"The chance of finding a lost ring in the sea is minuscule.","zh":"在海中找到失去戒指的機會極少。"},{"en":"A minuscule mistake in a form can still delay an application.","zh":"表格上一個極小錯誤仍可能延誤申請。"},{"en":"When evidence is minuscule, scientists need to be especially careful.","zh":"當證據極少時，科學家需要特別小心。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":6},{"front":"nevertheless","meaning":"然而","examples":[{"en":"Nevertheless, anthropologists have begun to study young fossils.","zh":"然而，人類學家已開始研究年輕化石。"},{"en":"Nevertheless means despite what was just said, the following point is still true.","zh":"nevertheless 是指儘管剛才所說的情況，接下來的重點仍然成立。"},{"en":"The exam was hard; nevertheless, many students finished on time.","zh":"考試很難；然而，許多學生準時完成。"},{"en":"Evidence is limited; nevertheless, researchers continue to investigate.","zh":"證據有限；然而，研究人員繼續調查。"},{"en":"This word is useful when showing contrast between difficulty and action.","zh":"這個詞在顯示困難與行動之間的對比時很有用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":6},{"front":"begin to look at","meaning":"開始研究","examples":[{"en":"Anthropologists have begun to look at the lives of ancient youngsters.","zh":"人類學家已開始研究古代年輕人的生活。"},{"en":"To begin to look at something means to start studying or considering it seriously.","zh":"begin to look at 是指開始認真研究或考慮某事。"},{"en":"The school has begun to look at why students feel stressed before exams.","zh":"學校已開始研究為何學生在考試前感到壓力。"},{"en":"Doctors may begin to look at family history when symptoms are unclear.","zh":"當症狀不清楚時，醫生可能開始研究家族病史。"},{"en":"Researchers begin to look at a new topic when old explanations seem incomplete.","zh":"當舊解釋似乎不完整時，研究人員會開始研究新題目。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":6},{"front":"what can be learned of","meaning":"可以從……了解到甚麼","examples":[{"en":"Researchers ask what can be learned of our ancestors from young fossils.","zh":"研究人員問可以從年輕化石了解到我們祖先的甚麼。"},{"en":"What can be learned of something means what information or understanding can be gained about it.","zh":"what can be learned of 是指可以關於某事獲得甚麼資訊或理解。"},{"en":"Historians ask what can be learned of daily life from old letters.","zh":"歷史學家問可以從舊信件了解到日常生活的甚麼。"},{"en":"Doctors ask what can be learned of a patient’s condition from test results.","zh":"醫生問可以從檢查結果了解到病人情況的甚麼。"},{"en":"This phrase is useful when evidence is limited but still informative.","zh":"當證據有限但仍有資訊價值時，這個短語很有用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":6},{"front":"the lives of our ancestors","meaning":"我們祖先的生活","examples":[{"en":"Fossilised children can reveal the lives of our ancestors.","zh":"兒童化石可以揭示我們祖先的生活。"},{"en":"The lives of our ancestors means how earlier humans lived, grew, worked, ate, and survived.","zh":"我們祖先的生活是指早期人類如何生活、成長、工作、飲食和生存。"},{"en":"Tools and bones can show parts of the lives of our ancestors.","zh":"工具和骨骼可以顯示我們祖先生活的部分面貌。"},{"en":"Studying the lives of our ancestors helps us understand where modern human habits came from.","zh":"研究我們祖先的生活幫助我們理解現代人類習慣從何而來。"},{"en":"Young fossils may reveal the lives of our ancestors during childhood, not only adulthood.","zh":"年輕化石可能揭示我們祖先在童年時期的生活，而不只是成年生活。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":6},{"front":"youngsters","meaning":"年輕人；兒童","examples":[{"en":"These youngsters provide evidence about ancient human development.","zh":"這些年輕人提供關於古代人類發展的證據。"},{"en":"Youngsters are children or young people.","zh":"youngsters 是指兒童或年輕人。"},{"en":"Teachers often need different methods for youngsters because they learn through play and examples.","zh":"老師常需要為兒童使用不同方法，因為他們透過玩耍和例子學習。"},{"en":"Fossilised youngsters are important because they show how ancient humans grew.","zh":"兒童化石很重要，因為它們顯示古代人類如何成長。"},{"en":"The word youngsters is less formal than children, but it means young people.","zh":"youngsters 這個詞比 children 較不正式，但意思是年輕人。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":6},{"front":"one of the most studied","meaning":"最常被研究的……之一","examples":[{"en":"The Turkana boy is one of the most studied fossils.","zh":"圖爾卡納男孩是最常被研究的化石之一。"},{"en":"One of the most studied means among the examples that researchers have examined most often.","zh":"one of the most studied 是指在研究人員最常檢視的例子之中。"},{"en":"Shakespeare is one of the most studied writers in English literature.","zh":"莎士比亞是英國文學中最常被研究的作家之一。"},{"en":"A disease becomes one of the most studied topics when it affects many people.","zh":"當疾病影響很多人時，它會成為最常被研究的題目之一。"},{"en":"Being one of the most studied fossils means the Turkana boy has been examined from many angles.","zh":"作為最常被研究的化石之一，意味著圖爾卡納男孩已從許多角度被檢視。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":6},{"front":"Turkana boy","meaning":"圖爾卡納男孩","examples":[{"en":"The Turkana boy is an almost complete skeleton of Homo erectus.","zh":"圖爾卡納男孩是一具幾乎完整的直立人骨骼。"},{"en":"The Turkana boy is the name given to a famous young Homo erectus fossil found near Lake Turkana.","zh":"圖爾卡納男孩是給予一具在圖爾卡納湖附近發現的著名年輕直立人化石的名稱。"},{"en":"Students study the Turkana boy because his skeleton gives rare information about early human growth.","zh":"學生研究圖爾卡納男孩，因為他的骨骼提供關於早期人類生長的罕見資訊。"},{"en":"The Turkana boy is important because young human fossils are very rare.","zh":"圖爾卡納男孩很重要，因為年輕人類化石非常稀少。"},{"en":"Researchers debate his age because his teeth, bones, and height suggest different stages.","zh":"研究人員爭論他的年齡，因為他的牙齒、骨骼和身高暗示不同發育階段。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":7},{"front":"almost complete skeleton","meaning":"幾乎完整的骨骼","examples":[{"en":"The Turkana boy is an almost complete skeleton.","zh":"圖爾卡納男孩是一具幾乎完整的骨骼。"},{"en":"An almost complete skeleton is a set of bones with most parts preserved.","zh":"幾乎完整的骨骼是指大部分部位都保存下來的一套骨骼。"},{"en":"An almost complete skeleton helps scientists study body shape more accurately.","zh":"幾乎完整的骨骼幫助科學家更準確研究身體形態。"},{"en":"If only a few bones survive, conclusions are harder than with an almost complete skeleton.","zh":"如果只保存少數骨頭，結論會比擁有幾乎完整的骨骼更難作出。"},{"en":"The Turkana boy is valuable because his almost complete skeleton allows detailed comparison.","zh":"圖爾卡納男孩很有價值，因為其幾乎完整的骨骼允許詳細比較。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":7},{"front":"from 1.6 million years ago","meaning":"來自一百六十萬年前","examples":[{"en":"The Turkana boy lived around 1.6 million years ago.","zh":"圖爾卡納男孩生活於約一百六十萬年前。"},{"en":"From 1.6 million years ago means dating back to about 1.6 million years before the present.","zh":"from 1.6 million years ago 是指可追溯至距今約一百六十萬年前。"},{"en":"A fossil from 1.6 million years ago can show what early humans were like.","zh":"來自一百六十萬年前的化石可以顯示早期人類的樣貌。"},{"en":"Evidence from 1.6 million years ago must be interpreted carefully because it is so ancient.","zh":"來自一百六十萬年前的證據必須小心解讀，因為它非常古老。"},{"en":"This phrase places the Turkana boy far before modern human history.","zh":"這個短語把圖爾卡納男孩置於遠早於現代人類歷史的時間。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":7},{"front":"found in Kenya","meaning":"在肯尼亞被發現","examples":[{"en":"The skeleton was found in Kenya in 1984.","zh":"這具骨骼於1984年在肯尼亞被發現。"},{"en":"Found in Kenya means discovered in the country of Kenya in East Africa.","zh":"found in Kenya 是指在東非國家肯尼亞被發現。"},{"en":"A fossil found in Kenya may provide evidence about early humans in Africa.","zh":"在肯尼亞被發現的化石可能提供關於非洲早期人類的證據。"},{"en":"Discoveries found in Kenya have helped scientists understand human evolution.","zh":"在肯尼亞被發現的發現物幫助科學家理解人類演化。"},{"en":"Saying where a fossil was found helps researchers connect it with environment and geography.","zh":"說明化石在哪裡被發現，有助研究人員把它與環境和地理連接起來。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":7},{"front":"accurately assessing","meaning":"準確評估","examples":[{"en":"Accurately assessing someone’s age from a skeleton is difficult.","zh":"從骨骼準確評估某人的年齡很困難。"},{"en":"Accurately assessing means judging or measuring something correctly and carefully.","zh":"準確評估是指正確而仔細地判斷或量度某事。"},{"en":"Teachers need to accurately assess students’ writing before giving useful feedback.","zh":"老師需要準確評估學生寫作，才可給予有用回饋。"},{"en":"Doctors accurately assess symptoms by asking questions and ordering tests.","zh":"醫生透過提問和安排檢查來準確評估症狀。"},{"en":"In fossil studies, accurately assessing age is hard because evidence may be incomplete.","zh":"在化石研究中，準確評估年齡很困難，因為證據可能不完整。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":7},{"front":"a tricky business","meaning":"棘手的事","examples":[{"en":"Assessing age from a skeleton is a tricky business.","zh":"從骨骼評估年齡是一件棘手的事。"},{"en":"A tricky business means a difficult task that needs care and judgement.","zh":"a tricky business 是指需要小心和判斷的困難任務。"},{"en":"Choosing a school can be a tricky business when every option has strengths and weaknesses.","zh":"當每個選項都有優點和缺點時，選擇學校可能是一件棘手的事。"},{"en":"Explaining a child’s test results is a tricky business if the data are incomplete.","zh":"如果數據不完整，解釋孩子的測驗結果是一件棘手的事。"},{"en":"This phrase is informal and suggests something is not simple or straightforward.","zh":"這個短語較口語，表示某事並不簡單直接。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":7},{"front":"make a rough estimate","meaning":"作出粗略估計","examples":[{"en":"Scientists can only make a rough estimate of age.","zh":"科學家只能作出年齡的粗略估計。"},{"en":"To make a rough estimate means to give an approximate answer rather than an exact one.","zh":"make a rough estimate 是指給出近似答案，而不是精確答案。"},{"en":"A builder may make a rough estimate of repair costs before checking every detail.","zh":"建築工人在檢查每個細節前，可能先作出維修費用的粗略估計。"},{"en":"Students can make a rough estimate first, then calculate the exact answer.","zh":"學生可以先作出粗略估計，再計算精確答案。"},{"en":"Researchers make a rough estimate when evidence is useful but incomplete.","zh":"當證據有用但不完整時，研究人員會作出粗略估計。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":7},{"front":"based on","meaning":"根據","examples":[{"en":"The estimate is based on teeth, bones and general size.","zh":"估計是根據牙齒、骨骼和整體大小作出的。"},{"en":"Based on means using something as the foundation or evidence for a judgement.","zh":"based on 是指使用某事作為判斷的基礎或證據。"},{"en":"A doctor’s advice should be based on test results and symptoms.","zh":"醫生的建議應根據檢查結果和症狀。"},{"en":"A school rule based on safety is easier to explain to students.","zh":"根據安全而制定的校規較容易向學生解釋。"},{"en":"In science, conclusions should be based on evidence rather than guesses.","zh":"在科學中，結論應根據證據，而不是猜測。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":7},{"front":"developmental stage","meaning":"發育階段","examples":[{"en":"Age can be estimated from the developmental stage of teeth and bones.","zh":"年齡可以從牙齒和骨骼的發育階段估計。"},{"en":"Developmental stage means the level of growth or maturity something has reached.","zh":"發育階段是指某事物已達到的生長或成熟程度。"},{"en":"A doctor checks a child’s developmental stage by looking at speech, movement, and height.","zh":"醫生透過觀察語言、活動和身高來檢查兒童發育階段。"},{"en":"Teeth and bones can show developmental stage because they change as a child grows.","zh":"牙齒和骨骼可以顯示發育階段，因為它們會隨兒童成長而改變。"},{"en":"Fossil age estimates often depend on matching developmental stage with known patterns.","zh":"化石年齡估計常取決於把發育階段與已知模式配對。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":7},{"front":"teeth and bones","meaning":"牙齒和骨骼","examples":[{"en":"The developmental stage of teeth and bones helps estimate age.","zh":"牙齒和骨骼的發育階段有助估計年齡。"},{"en":"Teeth and bones are hard body parts that can preserve evidence of growth.","zh":"牙齒和骨骼是可以保存生長證據的堅硬身體部分。"},{"en":"Doctors examine teeth and bones when checking whether a child is developing normally.","zh":"醫生檢查兒童是否正常發育時，會檢查牙齒和骨骼。"},{"en":"Teeth and bones may give different age estimates because they do not always develop at the same speed.","zh":"牙齒和骨骼可能給出不同年齡估計，因為它們不一定以相同速度發育。"},{"en":"In fossils, teeth and bones are often the main evidence available.","zh":"在化石中，牙齒和骨骼通常是可用的主要證據。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":7},{"front":"general size","meaning":"整體大小","examples":[{"en":"The skeleton’s general size can help estimate age.","zh":"骨骼的整體大小可以幫助估計年齡。"},{"en":"General size means the overall height, length, or body scale rather than exact details.","zh":"整體大小是指整體高度、長度或身體規模，而不是精確細節。"},{"en":"A doctor may look at a child’s general size before checking detailed measurements.","zh":"醫生可能先看兒童的整體大小，再檢查詳細量度。"},{"en":"General size can suggest age, but it may be misleading if growth patterns differ.","zh":"整體大小可以暗示年齡，但如果生長模式不同，也可能誤導。"},{"en":"Scientists use general size together with teeth and bones, not by itself.","zh":"科學家會把整體大小與牙齒和骨骼一起使用，而不是單獨使用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":7},{"front":"developmental markers","meaning":"發育標記","examples":[{"en":"Researchers need many developmental markers to estimate age.","zh":"研究人員需要許多發育標記來估計年齡。"},{"en":"Developmental markers are signs that show a stage of growth or maturity.","zh":"發育標記是顯示生長或成熟階段的跡象。"},{"en":"Losing baby teeth can be a developmental marker in children.","zh":"乳齒脫落可以是兒童的發育標記。"},{"en":"More developmental markers make an age estimate more reliable.","zh":"更多發育標記會令年齡估計更可靠。"},{"en":"In skeletons, developmental markers may include teeth, bone shape, height, and skull features.","zh":"在骨骼中，發育標記可能包括牙齒、骨骼形狀、身高和頭骨特徵。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":8},{"front":"as many…as possible","meaning":"盡可能多的……","examples":[{"en":"You need as many developmental markers as possible.","zh":"你需要盡可能多的發育標記。"},{"en":"As many…as possible means the greatest number that can reasonably be obtained.","zh":"as many…as possible 是指合理情況下能獲得的最大數量。"},{"en":"Students should collect as many useful examples as possible before writing an essay.","zh":"學生寫文章前應收集盡可能多的有用例子。"},{"en":"Doctors gather as many symptoms as possible before making a diagnosis.","zh":"醫生在診斷前會收集盡可能多的症狀。"},{"en":"Researchers use as many markers as possible because one clue may not be enough.","zh":"研究人員使用盡可能多的標記，因為一個線索可能不足夠。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":8},{"front":"get an estimate of age","meaning":"估計年齡","examples":[{"en":"Researchers use several markers to get an estimate of age.","zh":"研究人員使用幾個標記來估計年齡。"},{"en":"To get an estimate of age means to calculate an approximate age from available evidence.","zh":"get an estimate of age 是指根據可用證據計算大約年齡。"},{"en":"A vet may get an estimate of age for a rescued dog by checking its teeth.","zh":"獸醫可能透過檢查牙齒，為獲救狗隻估計年齡。"},{"en":"Archaeologists get an estimate of age by comparing bones, tools, and layers of soil.","zh":"考古學家透過比較骨骼、工具和土層來估計年齡。"},{"en":"An estimate of age is useful when exact birth records do not exist.","zh":"當沒有準確出生記錄時，估計年齡很有用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":8},{"front":"indicate that","meaning":"顯示","examples":[{"en":"The Turkana boy’s teeth indicated that he was 10 or 11 years old.","zh":"圖爾卡納男孩的牙齒顯示他是十或十一歲。"},{"en":"To indicate that means to show or suggest that something is true.","zh":"indicate that 是指顯示或暗示某事是真實的。"},{"en":"Dark clouds indicate that rain may come soon.","zh":"烏雲顯示可能快要下雨。"},{"en":"A high temperature may indicate that someone has an infection.","zh":"高燒可能顯示某人有感染。"},{"en":"In fossils, teeth may indicate age more clearly than overall height.","zh":"在化石中，牙齒可能比整體身高更清楚顯示年齡。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":8},{"front":"features of his skeleton","meaning":"他的骨骼特徵","examples":[{"en":"The features of his skeleton put him at 13.","zh":"他的骨骼特徵顯示他約為十三歲。"},{"en":"Features of his skeleton are particular details in his bones, such as shape, size, and development.","zh":"他的骨骼特徵是指其骨頭中的特定細節，例如形狀、大小和發育。"},{"en":"Doctors may look at features of a skeleton to understand injuries or growth.","zh":"醫生可能查看骨骼特徵，以理解受傷或生長情況。"},{"en":"The features of his skeleton suggested a different age from his teeth.","zh":"他的骨骼特徵暗示了一個與牙齒不同的年齡。"},{"en":"This phrase shows that bones can provide evidence, but not always the same evidence as teeth.","zh":"這個短語顯示骨骼可以提供證據，但不一定與牙齒提供相同證據。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":8},{"front":"put him at","meaning":"顯示他約為……","examples":[{"en":"The features of his skeleton put him at 13.","zh":"他的骨骼特徵顯示他約為十三歲。"},{"en":"To put someone at an age means to estimate that person’s age as that number.","zh":"put someone at 某年齡，是指估計某人的年齡為該數字。"},{"en":"The doctor’s examination put the child at about eight years old.","zh":"醫生的檢查顯示該孩子約為八歲。"},{"en":"Witnesses put the suspect at around thirty, but they were not sure.","zh":"目擊者估計疑犯約為三十歲，但他們不確定。"},{"en":"This phrase is often used when age is estimated from evidence rather than known exactly.","zh":"當年齡是根據證據估計，而不是確切知道時，這個短語常被使用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":8},{"front":"as tall as","meaning":"與……一樣高","examples":[{"en":"He was as tall as a modern 15-year-old.","zh":"他與現代十五歲少年一樣高。"},{"en":"As tall as means having the same height as someone or something else.","zh":"as tall as 是指與某人或某物有相同高度。"},{"en":"My younger brother is already as tall as our father.","zh":"我的弟弟已經與父親一樣高。"},{"en":"A child may be as tall as an older student but still be younger in development.","zh":"孩子可能與較年長學生一樣高，但發育上仍較年輕。"},{"en":"Height alone can mislead researchers because someone may be as tall as an older person.","zh":"身高本身可能誤導研究人員，因為某人可能與較年長者一樣高。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":8},{"front":"point to research by","meaning":"提到……的研究","examples":[{"en":"Susan Anton points to research by Margaret Clegg.","zh":"Susan Anton 提到 Margaret Clegg 的研究。"},{"en":"To point to research by someone means to mention that person’s study as evidence or support.","zh":"point to research by someone 是指提及某人的研究作為證據或支持。"},{"en":"A teacher may point to research by psychologists to explain memory and learning.","zh":"老師可能提到心理學家的研究來解釋記憶和學習。"},{"en":"Doctors point to research by medical teams when recommending a treatment.","zh":"醫生在建議治療時，會提到醫療團隊的研究。"},{"en":"This phrase shows that an argument is supported by another scholar’s work.","zh":"這個短語顯示某論點由另一位學者的工作支持。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":8},{"front":"18th- and 19th-century skeletons","meaning":"18及19世紀的骨骼","examples":[{"en":"Margaret Clegg studied 18th- and 19th-century skeletons.","zh":"Margaret Clegg 研究了18及19世紀的骨骼。"},{"en":"18th- and 19th-century skeletons are skeletons from the 1700s and 1800s.","zh":"18及19世紀的骨骼是來自1700年代和1800年代的骨骼。"},{"en":"Museums may keep 18th- and 19th-century skeletons with records of age, health, and burial place.","zh":"博物館可能保存附有年齡、健康和埋葬地記錄的18及19世紀骨骼。"},{"en":"Such skeletons are useful because their historical records can be checked against physical evidence.","zh":"這類骨骼很有用，因為其歷史記錄可以與實體證據核對。"},{"en":"Comparing ancient fossils with 18th- and 19th-century skeletons helps researchers test age estimates.","zh":"把古代化石與18及19世紀骨骼比較，幫助研究人員測試年齡估計。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":8},{"front":"ages at death","meaning":"死亡時年齡","examples":[{"en":"The skeletons’ ages at death were known.","zh":"這些骨骼的死亡時年齡是已知的。"},{"en":"Ages at death are the ages people were when they died.","zh":"死亡時年齡是指人去世時的年齡。"},{"en":"Hospital records may show patients’ ages at death for medical research.","zh":"醫院記錄可能顯示病人的死亡時年齡，以供醫學研究使用。"},{"en":"If ages at death are known, scientists can test whether skeleton-based estimates are accurate.","zh":"如果死亡時年齡已知，科學家可以測試根據骨骼作出的估計是否準確。"},{"en":"In Clegg’s study, known ages at death allowed comparison with dental and skeletal evidence.","zh":"在 Clegg 的研究中，已知死亡時年齡允許與牙齒和骨骼證據作比較。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":8},{"front":"without checking the records","meaning":"沒有查閱記錄","examples":[{"en":"She tried to age the skeletons without checking the records.","zh":"她嘗試在沒有查閱記錄的情況下為骨骼定年。"},{"en":"Without checking the records means without looking at official or written information first.","zh":"without checking the records 是指沒有先查看官方或書面資料。"},{"en":"A teacher should not mark attendance without checking the records carefully.","zh":"老師不應在沒有仔細查閱記錄下標記出席。"},{"en":"Estimating age without checking the records tests whether physical evidence alone is reliable.","zh":"在沒有查閱記錄下估計年齡，可以測試單靠實體證據是否可靠。"},{"en":"This phrase highlights that the researcher was trying to avoid being influenced by known answers.","zh":"這個短語強調研究人員嘗試避免受已知答案影響。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":8},{"front":"similar discrepancies","meaning":"相似的不一致","examples":[{"en":"She found similar discrepancies to those of the Turkana boy.","zh":"她發現與圖爾卡納男孩相似的不一致。"},{"en":"Similar discrepancies are similar differences or mismatches between pieces of evidence.","zh":"相似的不一致是指不同證據之間相似的差異或不吻合。"},{"en":"A teacher may notice similar discrepancies between a student’s homework and test performance.","zh":"老師可能注意到學生功課和測驗表現之間有相似的不一致。"},{"en":"Similar discrepancies can show that one method of measurement may not be fully reliable.","zh":"相似的不一致可以顯示某種量度方法未必完全可靠。"},{"en":"In age estimation, similar discrepancies between teeth, bones, and height make conclusions harder.","zh":"在年齡估計中，牙齒、骨骼和身高之間相似的不一致令結論更困難。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":9},{"front":"dental age","meaning":"牙齒年齡","examples":[{"en":"One boy had a dental age of 9.","zh":"一名男孩的牙齒年齡是九歲。"},{"en":"Dental age is an estimated age based on the development of teeth.","zh":"牙齒年齡是根據牙齒發育作出的年齡估計。"},{"en":"Dentists may use dental age to check whether a child’s teeth are developing normally.","zh":"牙醫可能使用牙齒年齡來檢查兒童牙齒是否正常發育。"},{"en":"Dental age can differ from skeletal age because teeth and bones do not always grow at the same speed.","zh":"牙齒年齡可以不同於骨骼年齡，因為牙齒和骨骼不一定以相同速度生長。"},{"en":"In fossil studies, dental age may provide a useful clue about development.","zh":"在化石研究中，牙齒年齡可以提供關於發育的有用線索。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":9},{"front":"skeletal age","meaning":"骨骼年齡","examples":[{"en":"The same boy had a skeletal age of 6.","zh":"同一名男孩的骨骼年齡是六歲。"},{"en":"Skeletal age is an estimated age based on bone development.","zh":"骨骼年齡是根據骨骼發育作出的年齡估計。"},{"en":"Doctors may compare skeletal age with actual age to check growth problems.","zh":"醫生可能把骨骼年齡與實際年齡比較，以檢查生長問題。"},{"en":"Skeletal age can appear younger or older than dental age in some children.","zh":"在某些兒童中，骨骼年齡可能比牙齒年齡顯得更年輕或更年長。"},{"en":"Fossil researchers use skeletal age, but they know it may not match other indicators exactly.","zh":"化石研究人員使用骨骼年齡，但知道它未必與其他指標完全吻合。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":9},{"front":"tall enough to be","meaning":"高度足以像是……","examples":[{"en":"The boy was tall enough to be 11.","zh":"這名男孩的高度足以像是十一歲。"},{"en":"Tall enough to be a certain age means having a height that seems typical of that age.","zh":"tall enough to be 某年齡，是指身高看起來像該年齡的典型高度。"},{"en":"A child may be tall enough to be twelve but still only nine years old.","zh":"一個孩子可能高度足以像是十二歲，但實際只有九歲。"},{"en":"Height can suggest age, but being tall enough to be older does not prove actual age.","zh":"身高可以暗示年齡，但高度足以像較年長者並不能證明實際年齡。"},{"en":"This phrase shows why general size can create confusion in age estimates.","zh":"這個短語顯示為何整體大小會在年齡估計中造成混亂。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":9},{"front":"rounded skull","meaning":"圓形頭骨","examples":[{"en":"The Turkana boy still had a rounded skull.","zh":"圖爾卡納男孩仍有圓形頭骨。"},{"en":"A rounded skull is a skull shape that is still curved or childlike rather than fully adult.","zh":"圓形頭骨是仍然呈彎曲或兒童化，而非完全成人化的頭骨形狀。"},{"en":"Doctors may examine skull shape when studying a child’s development.","zh":"醫生研究兒童發育時，可能檢查頭骨形狀。"},{"en":"A rounded skull may suggest that more growth is still needed.","zh":"圓形頭骨可能暗示仍需要更多生長。"},{"en":"In the passage, the rounded skull supports the idea that the Turkana boy had not fully matured.","zh":"在文章中，圓形頭骨支持圖爾卡納男孩尚未完全成熟的想法。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":9},{"front":"reach the adult shape","meaning":"達到成人形態","examples":[{"en":"He needed more growth to reach the adult shape.","zh":"他需要更多生長才能達到成人形態。"},{"en":"To reach the adult shape means to develop the body form typical of a mature adult.","zh":"達到成人形態是指發展出成熟成人典型的身體形狀。"},{"en":"A teenager’s face may change before it reaches the adult shape.","zh":"青少年的臉在達到成人形態之前可能會改變。"},{"en":"Bones need time to reach the adult shape during growth.","zh":"骨骼在生長期間需要時間達到成人形態。"},{"en":"If a skeleton has not reached the adult shape, the person may still have been developing.","zh":"如果骨骼尚未達到成人形態，該人可能仍在發育中。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":9},{"front":"modern human patterns of growth","meaning":"現代人類生長模式","examples":[{"en":"Homo erectus may have developed modern human patterns of growth.","zh":"直立人可能已發展出現代人類生長模式。"},{"en":"Modern human patterns of growth are the ways modern humans grow through childhood, adolescence, and adulthood.","zh":"現代人類生長模式是指現代人類經歷童年、青春期和成年時的生長方式。"},{"en":"A modern human pattern of growth includes a relatively long childhood and a late growth spurt.","zh":"現代人類生長模式包括相對漫長的童年和較晚的急速生長。"},{"en":"If Homo erectus had modern human patterns of growth, adolescence may be older than once thought.","zh":"如果直立人有現代人類生長模式，青春期可能比過去認為的更古老。"},{"en":"This phrase compares ancient human development with development seen in people today.","zh":"這個短語把古代人類發育與今天人類的發育作比較。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":9},{"front":"late adolescent spurt","meaning":"較遲的青春期急速生長","examples":[{"en":"Homo erectus may have had a late adolescent spurt.","zh":"直立人可能有較遲的青春期急速生長。"},{"en":"A late adolescent spurt is a rapid period of growth that happens during adolescence rather than earlier childhood.","zh":"較遲的青春期急速生長是指在青春期而非較早童年出現的快速生長期。"},{"en":"Parents may notice a late adolescent spurt when a teenager suddenly grows taller in a few months.","zh":"當青少年在幾個月內突然長高時，父母可能注意到較遲的青春期急速生長。"},{"en":"A late adolescent spurt could explain why a fossil looks tall but not fully adult.","zh":"較遲的青春期急速生長可以解釋為何化石看起來高，但未完全成年。"},{"en":"In the passage, this idea challenges the belief that adolescence began only with modern humans.","zh":"在文章中，這個想法挑戰青春期只始於現代人類的信念。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":9},{"front":"not quite so extreme","meaning":"未必如此極端","examples":[{"en":"The adolescent spurt may not have been quite so extreme.","zh":"青春期急速生長未必如此極端。"},{"en":"Not quite so extreme means less strong, dramatic, or intense than another example.","zh":"not quite so extreme 是指沒有另一個例子那麼強烈、劇烈或極端。"},{"en":"The storm was serious, but not quite so extreme as last year’s typhoon.","zh":"風暴很嚴重，但未必像去年的颱風那麼極端。"},{"en":"A teenager’s growth may be fast but not quite so extreme as a younger child’s sudden change.","zh":"青少年的生長可能很快，但未必像較年幼兒童的突然變化那麼極端。"},{"en":"This phrase softens a comparison by showing that the difference exists but is smaller.","zh":"這個短語透過顯示差異存在但較小，來緩和比較。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":9},{"front":"be about to enter","meaning":"即將進入","examples":[{"en":"The Turkana boy may have been about to enter adolescence.","zh":"圖爾卡納男孩可能即將進入青春期。"},{"en":"To be about to enter a stage means to be just before starting that stage.","zh":"be about to enter 某階段，是指正要開始該階段。"},{"en":"A child about to enter secondary school may feel excited and nervous.","zh":"即將進入中學的孩子可能既興奮又緊張。"},{"en":"A patient about to enter recovery still needs careful support.","zh":"即將進入康復期的病人仍需要小心支援。"},{"en":"If the Turkana boy was about to enter adolescence, he had not yet completed that growth stage.","zh":"如果圖爾卡納男孩即將進入青春期，他尚未完成該生長階段。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":9},{"front":"contradict the orthodox idea","meaning":"與正統觀點相矛盾","examples":[{"en":"Anton’s theory contradicts the orthodox idea.","zh":"Anton 的理論與正統觀點相矛盾。"},{"en":"To contradict the orthodox idea means to disagree with the traditional or widely accepted view.","zh":"contradict the orthodox idea 是指不同意傳統或廣泛接受的觀點。"},{"en":"New research can contradict the orthodox idea when old evidence is reinterpreted.","zh":"當舊證據被重新解讀時，新研究可以與正統觀點相矛盾。"},{"en":"A student may contradict the orthodox idea in an essay if they provide strong evidence.","zh":"如果學生提供有力證據，他們可以在文章中與正統觀點相矛盾。"},{"en":"In science, contradicting an orthodox idea is acceptable when the evidence supports it.","zh":"在科學中，只要證據支持，與正統觀點相矛盾是可以接受的。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":9},{"front":"orthodox idea","meaning":"正統觀點","examples":[{"en":"The orthodox idea links late growth with large brain development.","zh":"正統觀點把較遲生長與大型大腦發展聯繫起來。"},{"en":"An orthodox idea is a traditional or widely accepted belief.","zh":"正統觀點是傳統或廣泛接受的信念。"},{"en":"The orthodox idea in many schools used to be that strict discipline produced better students.","zh":"在許多學校中，過去的正統觀點是嚴格紀律能培養更好學生。"},{"en":"An orthodox idea can remain popular until new evidence challenges it.","zh":"正統觀點可以一直流行，直到新證據挑戰它。"},{"en":"In the passage, the orthodox idea connects delayed growth with brain development.","zh":"在文章中，正統觀點把延遲生長與大腦發展連接起來。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":10},{"front":"link…with…","meaning":"將……與……聯繫起來","examples":[{"en":"The orthodox idea links late growth with large brain development.","zh":"正統觀點將較遲生長與大型大腦發展聯繫起來。"},{"en":"To link one thing with another means to connect them in explanation or meaning.","zh":"link one thing with another 是指在解釋或意義上把兩者連接起來。"},{"en":"Doctors link smoking with a higher risk of lung disease.","zh":"醫生把吸煙與較高肺病風險聯繫起來。"},{"en":"Teachers may link poor writing with lack of reading practice.","zh":"老師可能把寫作差與缺乏閱讀練習聯繫起來。"},{"en":"Scientists must be careful when linking two things because connection is not always causation.","zh":"科學家在把兩件事聯繫起來時必須小心，因為關聯不一定是因果。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":10},{"front":"go further","meaning":"更進一步","examples":[{"en":"Steven Leigh goes further in challenging the old explanation.","zh":"Steven Leigh 在挑戰舊解釋方面更進一步。"},{"en":"To go further means to take an argument or idea beyond what others have said.","zh":"go further 是指把論點或想法推到比他人所說更深入的程度。"},{"en":"A student can go further by not only describing a problem but also explaining its cause.","zh":"學生不只描述問題，還解釋其原因，就是更進一步。"},{"en":"Researchers go further when they propose a new theory instead of only criticising the old one.","zh":"研究人員提出新理論，而不只是批評舊理論，就是更進一步。"},{"en":"This phrase shows that someone makes a stronger or more developed claim.","zh":"這個短語顯示某人提出更強或更完整的主張。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":10},{"front":"catch-up growth","meaning":"追趕式生長","examples":[{"en":"Leigh questions the idea of adolescence as catch-up growth.","zh":"Leigh 質疑把青春期視為追趕式生長的想法。"},{"en":"Catch-up growth is rapid growth that happens after earlier growth has been delayed or slowed.","zh":"追趕式生長是指在早期生長被延遲或減慢後出現的快速生長。"},{"en":"A child may show catch-up growth after recovering from a long illness.","zh":"孩子在長病康復後可能出現追趕式生長。"},{"en":"If adolescence is catch-up growth, the body grows fast later to make up for earlier delay.","zh":"如果青春期是追趕式生長，身體就是在後期快速生長，以彌補早期延遲。"},{"en":"Leigh questions this idea because he thinks adolescence may have another evolutionary purpose.","zh":"Leigh 質疑這個想法，因為他認為青春期可能有另一個演化目的。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":10},{"front":"growth rate","meaning":"生長速度","examples":[{"en":"He asks why the growth rate increases so dramatically.","zh":"他問為何生長速度在青春期如此大幅增加。"},{"en":"Growth rate is the speed at which someone or something grows.","zh":"生長速度是某人或某物生長的快慢。"},{"en":"Doctors track a baby’s growth rate by measuring weight and length over time.","zh":"醫生透過持續量度體重和身長來追蹤嬰兒生長速度。"},{"en":"A sudden increase in growth rate may show that a child has entered puberty.","zh":"生長速度突然增加可能顯示孩子已進入青春期。"},{"en":"Comparing growth rates helps scientists understand differences between species.","zh":"比較生長速度幫助科學家理解物種之間的差異。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":10},{"front":"increase so dramatically","meaning":"大幅增加","examples":[{"en":"The growth rate increases so dramatically during adolescence.","zh":"生長速度在青春期大幅增加。"},{"en":"To increase so dramatically means to rise very sharply or noticeably.","zh":"increase so dramatically 是指非常急劇或明顯地上升。"},{"en":"Food prices may increase so dramatically that families change what they buy.","zh":"食物價格可能大幅增加，以致家庭改變購買內容。"},{"en":"A student’s confidence can increase dramatically after receiving clear support.","zh":"學生在獲得清晰支援後，信心可以大幅增加。"},{"en":"In adolescence, body growth can increase so dramatically that clothes quickly become too small.","zh":"在青春期，身體生長可以大幅增加，以致衣服很快變得太小。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":10},{"front":"growth spurts","meaning":"急速生長期","examples":[{"en":"Many apes have growth spurts in particular body regions.","zh":"許多猿類在特定身體部位有急速生長期。"},{"en":"Growth spurts are short periods of unusually fast growth.","zh":"急速生長期是異常快速生長的短暫時期。"},{"en":"Teenagers often experience growth spurts when they suddenly become taller.","zh":"青少年突然變高時，通常正在經歷急速生長期。"},{"en":"Growth spurts require extra energy, so food supply can be important.","zh":"急速生長期需要額外能量，所以食物供應很重要。"},{"en":"In some animals, growth spurts affect only certain body parts rather than the whole body.","zh":"在某些動物中，急速生長期只影響某些身體部位，而不是全身。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":10},{"front":"particular body regions","meaning":"特定身體部位","examples":[{"en":"Some apes have growth spurts in particular body regions.","zh":"有些猿類在特定身體部位有急速生長期。"},{"en":"Particular body regions are specific parts of the body, such as arms, legs, face, or trunk.","zh":"特定身體部位是指身體的具體部分，例如手臂、腿、臉或軀幹。"},{"en":"A doctor may examine particular body regions when pain is localised.","zh":"當疼痛集中在某處時，醫生可能檢查特定身體部位。"},{"en":"Growth in particular body regions can change an animal’s movement or appearance.","zh":"特定身體部位的生長可以改變動物的移動或外貌。"},{"en":"Unlike apes, humans may involve the whole skeleton rather than only particular body regions.","zh":"與猿類不同，人類可能涉及整副骨骼，而不是只涉及特定身體部位。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":10},{"front":"be associated with reaching maturity","meaning":"與達到成熟有關","examples":[{"en":"These growth spurts are associated with reaching maturity.","zh":"這些急速生長期與達到成熟有關。"},{"en":"To be associated with reaching maturity means to be connected with becoming fully developed.","zh":"be associated with reaching maturity 是指與變得完全發育有關。"},{"en":"In many animals, changes in body size are associated with reaching maturity.","zh":"在許多動物中，身體大小變化與達到成熟有關。"},{"en":"A deeper voice may be associated with reaching maturity in boys.","zh":"對男孩而言，聲音變低可能與達到成熟有關。"},{"en":"Growth spurts matter because they often happen near the time an organism becomes adult.","zh":"急速生長期很重要，因為它們常發生在生物接近成年之時。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":10},{"front":"make sense","meaning":"合理；說得通","examples":[{"en":"This timing makes sense because food may be plentiful.","zh":"這個時間安排是合理的，因為食物可能充足。"},{"en":"To make sense means to be logical, reasonable, or easy to understand.","zh":"make sense 是指合乎邏輯、合理或容易理解。"},{"en":"It makes sense to bring an umbrella when the sky is dark.","zh":"天色陰暗時帶傘是合理的。"},{"en":"A study plan makes sense if it gives more time to difficult subjects.","zh":"如果溫習計劃給困難科目更多時間，它就說得通。"},{"en":"In biology, growth timing makes sense when it matches food availability.","zh":"在生物學中，生長時間若與食物供應配合，就是合理的。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":10},{"front":"by timing","meaning":"透過安排……的時間","examples":[{"en":"Apes reduce risk by timing maturation carefully.","zh":"猿類透過仔細安排成熟時間來降低風險。"},{"en":"By timing something means by choosing when it happens.","zh":"by timing something 是指透過選擇某事發生的時間。"},{"en":"Farmers improve harvests by timing planting with the rainy season.","zh":"農民透過把種植時間安排在雨季來改善收成。"},{"en":"Students reduce stress by timing revision before deadlines, not at the last minute.","zh":"學生透過在期限前安排溫習時間，而不是最後一刻溫習，來減少壓力。"},{"en":"Animals may survive better by timing growth for seasons when food is available.","zh":"動物透過把生長安排在食物可得的季節，可能更容易生存。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":10},{"front":"short but crucial spells","meaning":"短暫但關鍵的時期","examples":[{"en":"Short but crucial spells of maturation may coincide with food availability.","zh":"短暫但關鍵的成熟時期可能與食物供應同時發生。"},{"en":"Short but crucial spells are brief periods that are very important.","zh":"短暫但關鍵的時期是時間很短但非常重要的時段。"},{"en":"A few short but crucial spells of sleep can help a sick person recover.","zh":"幾段短暫但關鍵的睡眠可以幫助病人康復。"},{"en":"Exam revision often depends on short but crucial spells of focused study.","zh":"考試溫習常取決於幾段短暫但關鍵的專注學習時間。"},{"en":"In animal growth, short but crucial spells may need enough food to succeed.","zh":"在動物生長中，短暫但關鍵的時期可能需要足夠食物才能成功。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":11},{"front":"maturation","meaning":"成熟過程","examples":[{"en":"Some growth spurts are linked to maturation.","zh":"有些急速生長期與成熟過程有關。"},{"en":"Maturation is the process of becoming physically, mentally, or socially mature.","zh":"成熟過程是身體、心理或社會上變成熟的過程。"},{"en":"Teenagers go through maturation as their bodies and responsibilities change.","zh":"青少年在身體和責任改變時經歷成熟過程。"},{"en":"Maturation can be affected by nutrition, environment, and biological timing.","zh":"成熟過程可能受營養、環境和生物時間影響。"},{"en":"In animals, maturation often determines when they can reproduce or live independently.","zh":"在動物中，成熟過程通常決定牠們何時能繁殖或獨立生活。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":11},{"front":"coincide with","meaning":"與……同時發生","examples":[{"en":"Maturation may coincide with seasons when food is plentiful.","zh":"成熟過程可能與食物充足的季節同時發生。"},{"en":"To coincide with something means to happen at the same time as it.","zh":"coincide with 是指與某事在同一時間發生。"},{"en":"The school fair may coincide with the public holiday.","zh":"學校嘉年華可能與公眾假期同時發生。"},{"en":"A growth period can coincide with warmer weather and better food supply.","zh":"生長期可以與較暖天氣和較好食物供應同時發生。"},{"en":"When two events coincide, one may help explain why the timing is useful.","zh":"當兩件事同時發生時，其中一件可能幫助解釋時間安排為何有用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":11},{"front":"food is plentiful","meaning":"食物充足","examples":[{"en":"Growth may occur when food is plentiful.","zh":"生長可能在食物充足時發生。"},{"en":"Food is plentiful means there is a large or sufficient amount of food available.","zh":"food is plentiful 是指有大量或足夠食物可用。"},{"en":"Animals may reproduce more successfully when food is plentiful.","zh":"當食物充足時，動物可能更成功繁殖。"},{"en":"Children grow better when food is plentiful and nutritious.","zh":"當食物充足且有營養時，兒童會生長得更好。"},{"en":"If food is plentiful during a growth spurt, the body has enough energy to develop.","zh":"如果急速生長期期間食物充足，身體便有足夠能量發育。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":11},{"front":"minimise the risk of","meaning":"將……的風險降至最低","examples":[{"en":"Animals minimise the risk of lacking food while growing.","zh":"動物將生長期間缺乏食物的風險降至最低。"},{"en":"To minimise the risk of something means to reduce the chance that it will happen.","zh":"minimise the risk of 是指減低某事發生的機會。"},{"en":"Drivers wear seat belts to minimise the risk of serious injury.","zh":"司機繫安全帶以將嚴重受傷的風險降至最低。"},{"en":"Students start revision early to minimise the risk of panic before exams.","zh":"學生提早溫習，以將考試前恐慌的風險降至最低。"},{"en":"Animals may time growth carefully to minimise the risk of not having enough food.","zh":"動物可能仔細安排生長時間，以將食物不足的風險降至最低。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":11},{"front":"adequate food supplies","meaning":"足夠的食物供應","examples":[{"en":"Growing animals need adequate food supplies.","zh":"正在生長的動物需要足夠的食物供應。"},{"en":"Adequate food supplies are enough food resources to meet basic needs.","zh":"足夠的食物供應是指足以滿足基本需要的食物資源。"},{"en":"Schools need adequate food supplies when providing lunch for all students.","zh":"學校為所有學生提供午餐時，需要足夠的食物供應。"},{"en":"Without adequate food supplies, young animals may grow slowly or fail to survive.","zh":"沒有足夠的食物供應，年幼動物可能生長緩慢或無法生存。"},{"en":"During growth spurts, adequate food supplies become especially important.","zh":"在急速生長期，足夠的食物供應變得尤其重要。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":11},{"front":"what makes humans unique","meaning":"令人類獨特的是","examples":[{"en":"What makes humans unique is that the whole skeleton is involved.","zh":"令人類獨特的是整副骨骼都參與其中。"},{"en":"What makes humans unique means the feature that separates humans from other animals.","zh":"what makes humans unique 是指把人類與其他動物區分開來的特徵。"},{"en":"Language is often discussed as one thing that makes humans unique.","zh":"語言常被討論為令人類獨特的其中一點。"},{"en":"The ability to teach complex skills may be part of what makes humans unique.","zh":"教授複雜技能的能力可能是令人類獨特的一部分。"},{"en":"In this passage, the whole-body growth spurt is presented as what makes humans unique.","zh":"在本文中，全身性的急速生長被呈現為令人類獨特的地方。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":11},{"front":"the whole skeleton is involved","meaning":"整副骨骼都參與其中","examples":[{"en":"In humans, the whole skeleton is involved in the growth spurt.","zh":"在人類中，整副骨骼都參與急速生長。"},{"en":"The whole skeleton is involved means all or most bones take part in the growth change.","zh":"整副骨骼都參與其中，是指全部或大部分骨骼都參與生長變化。"},{"en":"A whole-body illness may affect many organs, just as a whole-skeleton growth spurt affects many bones.","zh":"全身性疾病可能影響許多器官，就像整副骨骼的急速生長影響許多骨頭。"},{"en":"If the whole skeleton is involved, growth is not limited to one arm, leg, or face.","zh":"如果整副骨骼都參與其中，生長就不限於一隻手臂、一條腿或臉部。"},{"en":"This idea matters because human adolescence affects the body more broadly than in many apes.","zh":"這個想法很重要，因為人類青春期比許多猿類更廣泛地影響身體。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":11},{"front":"this is the key","meaning":"這是關鍵","examples":[{"en":"For Leigh, the whole skeleton is the key.","zh":"對 Leigh 而言，整副骨骼才是關鍵。"},{"en":"This is the key means this is the most important point for understanding the issue.","zh":"this is the key 是指這是理解問題的最重要重點。"},{"en":"In essay writing, the thesis is the key because it controls the whole argument.","zh":"在文章寫作中，論點是關鍵，因為它控制整個論證。"},{"en":"A doctor may say sleep is the key when tiredness causes many other symptoms.","zh":"當疲倦造成許多其他症狀時，醫生可能說睡眠是關鍵。"},{"en":"Leigh sees the whole skeleton as the key to explaining why adolescence evolved.","zh":"Leigh 把整副骨骼視為解釋青春期為何演化的關鍵。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":11},{"front":"according to his theory","meaning":"根據他的理論","examples":[{"en":"According to his theory, adolescence evolved as part of upright walking.","zh":"根據他的理論，青春期作為直立行走的一部分演化出來。"},{"en":"According to his theory means based on the explanation he proposes.","zh":"according to his theory 是指根據他提出的解釋。"},{"en":"According to his theory, students learn better when examples connect with daily life.","zh":"根據他的理論，當例子與日常生活連接時，學生學得更好。"},{"en":"Scientists use this phrase to report an idea without saying it is definitely true.","zh":"科學家使用這個短語來報告一個想法，而不是說它一定正確。"},{"en":"In the passage, according to his theory introduces Leigh’s explanation of adolescence.","zh":"在文章中，according to his theory 引入 Leigh 對青春期的解釋。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":11},{"front":"integral part of","meaning":"……不可或缺的一部分","examples":[{"en":"Adolescence evolved as an integral part of efficient upright locomotion.","zh":"青春期作為有效率直立行走不可或缺的一部分演化出來。"},{"en":"An integral part of something is a necessary and important part of it.","zh":"integral part of 是指某事物必要且重要的一部分。"},{"en":"Practice is an integral part of learning a language.","zh":"練習是學習語言不可或缺的一部分。"},{"en":"Trust is an integral part of teamwork because people must rely on one another.","zh":"信任是團隊合作不可或缺的一部分，因為人們必須依賴彼此。"},{"en":"Leigh argues that adolescence may be an integral part of how humans walk efficiently.","zh":"Leigh 主張青春期可能是人類有效行走方式不可或缺的一部分。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":11},{"front":"efficient upright locomotion","meaning":"有效率的直立行走","examples":[{"en":"Adolescence may be linked to efficient upright locomotion.","zh":"青春期可能與有效率的直立行走有關。"},{"en":"Efficient upright locomotion means effective movement while walking on two legs.","zh":"有效率的直立行走是指用兩條腿有效移動。"},{"en":"Human walking is a form of upright locomotion because the body moves on two legs.","zh":"人類行走是一種直立行走，因為身體用兩條腿移動。"},{"en":"Efficient upright locomotion helps save energy during long-distance movement.","zh":"有效率的直立行走有助在長距離移動時節省能量。"},{"en":"Leigh’s theory connects adolescence with the body changes needed for efficient upright locomotion.","zh":"Leigh 的理論把青春期與有效率直立行走所需的身體變化連接起來。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":12},{"front":"accommodate more complex brains","meaning":"容納更複雜的大腦","examples":[{"en":"Adolescence may also help accommodate more complex brains.","zh":"青春期也可能幫助容納更複雜的大腦。"},{"en":"To accommodate more complex brains means to allow the body and development pattern to support larger or more advanced brains.","zh":"accommodate more complex brains 是指讓身體和發育模式能支持更大或更進階的大腦。"},{"en":"A school may change its timetable to accommodate students with different learning needs.","zh":"學校可能改變時間表，以容納有不同學習需要的學生。"},{"en":"Human childhood may be long partly to accommodate more complex brains and learning.","zh":"人類童年漫長，部分原因可能是為了容納更複雜的大腦和學習。"},{"en":"This phrase suggests that body development and brain development may need to fit together.","zh":"這個短語暗示身體發育和大腦發育可能需要互相配合。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":12},{"front":"walk on two legs","meaning":"用兩條腿行走","examples":[{"en":"Fossil evidence suggests that our ancestors first walked on two legs six million years ago.","zh":"化石證據顯示，我們的祖先在六百萬年前首次用兩條腿行走。"},{"en":"To walk on two legs means to move upright using the two lower limbs.","zh":"用兩條腿行走是指使用兩條下肢直立移動。"},{"en":"Humans walk on two legs, while many other mammals move on four limbs.","zh":"人類用兩條腿行走，而許多其他哺乳動物用四肢移動。"},{"en":"Walking on two legs changed the way early humans used their hands, hips, and spine.","zh":"用兩條腿行走改變了早期人類使用雙手、髖部和脊椎的方式。"},{"en":"The ability to walk on two legs is central to many theories of human evolution.","zh":"用兩條腿行走的能力是許多人類演化理論的核心。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":12},{"front":"proficient walking","meaning":"熟練行走","examples":[{"en":"Proficient walking may have been important for survival.","zh":"熟練行走可能對生存很重要。"},{"en":"Proficient walking means walking with skill, balance, and efficiency.","zh":"熟練行走是指有技巧、平衡和效率地行走。"},{"en":"A toddler develops proficient walking after many months of practice.","zh":"幼兒在多個月練習後發展出熟練行走。"},{"en":"Proficient walking helps people travel farther with less energy.","zh":"熟練行走幫助人用較少能量走更遠。"},{"en":"For early humans, proficient walking may have helped with travel, food gathering, and escape from danger.","zh":"對早期人類而言，熟練行走可能有助移動、覓食和逃離危險。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":12},{"front":"important for survival","meaning":"對生存重要","examples":[{"en":"Walking efficiently may have been important for survival.","zh":"有效率地行走可能對生存重要。"},{"en":"Important for survival means necessary or very helpful for staying alive.","zh":"important for survival 是指對維持生命必要或非常有幫助。"},{"en":"Clean water is important for survival in any community.","zh":"清潔食水對任何社區的生存都重要。"},{"en":"For animals in the wild, speed and camouflage can be important for survival.","zh":"對野外動物而言，速度和偽裝可以對生存重要。"},{"en":"Efficient walking may have been important for survival because early humans needed to travel and find food.","zh":"有效率行走可能對生存重要，因為早期人類需要移動和尋找食物。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":12},{"front":"ancient origins","meaning":"古老起源","examples":[{"en":"The teenage growth spurt may have very ancient origins.","zh":"青少年急速生長期可能有非常古老的起源。"},{"en":"Ancient origins are beginnings that go far back into the distant past.","zh":"古老起源是指可追溯至遙遠過去的開始。"},{"en":"Many festivals have ancient origins even if their modern forms have changed.","zh":"許多節日有古老起源，即使其現代形式已改變。"},{"en":"If adolescence has ancient origins, it may have begun before modern humans appeared.","zh":"如果青春期有古老起源，它可能在現代人類出現之前已開始。"},{"en":"This phrase suggests that a feature is much older than people might expect.","zh":"這個短語暗示某特徵比人們可能預期的更古老。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":12},{"front":"a step too far","meaning":"過於激進的一步","examples":[{"en":"Many anthropologists may consider Leigh’s theory a step too far.","zh":"許多人類學家可能認為 Leigh 的理論是過於激進的一步。"},{"en":"A step too far means an idea or action that goes beyond what many people find reasonable.","zh":"a step too far 是指超出許多人認為合理範圍的想法或行動。"},{"en":"Banning all phones in school may be a step too far if students need them for safety.","zh":"如果學生需要手機保障安全，學校全面禁止手機可能是過於激進的一步。"},{"en":"A scientific theory can seem a step too far when evidence is not yet strong enough.","zh":"當證據尚未足夠有力時，一個科學理論可能顯得過於激進。"},{"en":"This phrase suggests that some people think the claim is too bold.","zh":"這個短語暗示有些人認為該主張太大膽。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":12},{"front":"not the only one with","meaning":"不是唯一有……的人","examples":[{"en":"Leigh is not the only one with new ideas about teenagers.","zh":"Leigh 不是唯一有關於青少年新想法的人。"},{"en":"Not the only one with something means other people also have it.","zh":"not the only one with 是指其他人也有某事物。"},{"en":"She is not the only one with questions about the new school policy.","zh":"她不是唯一對新校政有疑問的人。"},{"en":"A researcher is not the only one with doubts when many experts challenge a theory.","zh":"當許多專家挑戰一個理論時，某研究人員不是唯一有疑問的人。"},{"en":"This phrase shows that an idea is shared or supported by more than one person.","zh":"這個短語顯示某想法由不止一個人分享或支持。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":12},{"front":"the evolution of teenagers","meaning":"青少年的演化","examples":[{"en":"Researchers have new ideas about the evolution of teenagers.","zh":"研究人員對青少年的演化有新想法。"},{"en":"The evolution of teenagers means the development of the teenage stage through human evolutionary history.","zh":"青少年的演化是指青少年階段在人類演化史中的發展。"},{"en":"Scientists study the evolution of teenagers by comparing fossils, teeth, skeletons, and modern growth patterns.","zh":"科學家透過比較化石、牙齒、骨骼和現代生長模式來研究青少年的演化。"},{"en":"If the evolution of teenagers began early, adolescence may be linked to walking as well as brain growth.","zh":"如果青少年的演化很早開始，青春期可能與行走以及大腦生長都有關。"},{"en":"This phrase treats teenagers not only as a social group but also as a biological stage.","zh":"這個短語不只把青少年視為社會群體，也視為生物階段。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":12},{"front":"another approach","meaning":"另一種方法","examples":[{"en":"Another approach relies on the analysis of tooth growth.","zh":"另一種方法依靠牙齒生長分析。"},{"en":"Another approach means a different method or way of studying a problem.","zh":"another approach 是指研究問題的另一種方法或方式。"},{"en":"If memorising vocabulary fails, another approach is to learn words through stories.","zh":"如果背誦詞彙無效，另一種方法是透過故事學詞。"},{"en":"Doctors may try another approach when the first treatment does not work.","zh":"當第一種治療無效時，醫生可能嘗試另一種方法。"},{"en":"In research, another approach can produce evidence that earlier methods missed.","zh":"在研究中，另一種方法可以產生早期方法錯過的證據。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":12},{"front":"produce a surprising result","meaning":"產生令人意外的結果","examples":[{"en":"The new approach has produced a surprising result.","zh":"這種新方法產生了令人意外的結果。"},{"en":"To produce a surprising result means to lead to an outcome that people did not expect.","zh":"produce a surprising result 是指導致人們沒有預期的結果。"},{"en":"A small change in teaching method may produce a surprising result in student confidence.","zh":"教學方法的小改變可能在學生信心方面產生令人意外的結果。"},{"en":"Scientific tests can produce a surprising result when evidence challenges old assumptions.","zh":"當證據挑戰舊假設時，科學測試可以產生令人意外的結果。"},{"en":"This phrase suggests that the method revealed something unexpected.","zh":"這個短語暗示該方法揭示了意想不到的事情。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":12},{"front":"rely on","meaning":"依靠","examples":[{"en":"The approach relies on the minute analysis of tooth growth.","zh":"這種方法依靠對牙齒生長的精細分析。"},{"en":"To rely on something means to depend on it for support, evidence, or success.","zh":"rely on 是指依賴某事物作為支持、證據或成功的基礎。"},{"en":"Students rely on clear notes when revising for exams.","zh":"學生溫習考試時依靠清晰筆記。"},{"en":"Doctors rely on test results before making difficult decisions.","zh":"醫生在作出困難決定前依靠檢查結果。"},{"en":"In this study, researchers rely on tooth growth because teeth preserve developmental clues.","zh":"在這項研究中，研究人員依靠牙齒生長，因為牙齒保存發育線索。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":13},{"front":"minute analysis","meaning":"精細分析","examples":[{"en":"The method relies on the minute analysis of tooth growth.","zh":"這種方法依靠對牙齒生長的精細分析。"},{"en":"Minute analysis is very detailed and careful examination of small features.","zh":"精細分析是對細小特徵進行非常詳細和仔細的檢查。"},{"en":"A detective may use minute analysis of fingerprints to solve a case.","zh":"偵探可能透過指紋的精細分析來破案。"},{"en":"Minute analysis takes time, but it can reveal details that ordinary observation misses.","zh":"精細分析需要時間，但可以揭示普通觀察錯過的細節。"},{"en":"Tooth growth requires minute analysis because the ridges are small and meaningful.","zh":"牙齒生長需要精細分析，因為脊狀紋細小但有意義。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":13},{"front":"tooth growth","meaning":"牙齒生長","examples":[{"en":"Tooth growth can reveal information about development.","zh":"牙齒生長可以揭示關於發育的資訊。"},{"en":"Tooth growth is the process by which teeth form, enlarge, and emerge.","zh":"牙齒生長是牙齒形成、變大和長出的過程。"},{"en":"Dentists monitor tooth growth to see whether children are developing normally.","zh":"牙醫監測牙齒生長，以了解兒童是否正常發育。"},{"en":"Tooth growth can preserve a timing record, rather like tree rings.","zh":"牙齒生長可以保存時間記錄，有點像樹輪。"},{"en":"Researchers use tooth growth because it is less affected by environment than skeleton growth.","zh":"研究人員使用牙齒生長，因為它受環境影響比骨骼生長少。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":13},{"front":"every nine days or so","meaning":"大約每九天","examples":[{"en":"Growing teeth acquire ridges every nine days or so.","zh":"正在生長的牙齒大約每九天形成脊狀紋。"},{"en":"Every nine days or so means approximately every nine days, not exactly.","zh":"every nine days or so 是指大約每九天一次，不是完全精確。"},{"en":"The plant needs watering every three days or so in hot weather.","zh":"在炎熱天氣中，這棵植物大約每三天需要澆水一次。"},{"en":"If marks form every nine days or so, scientists can use them to estimate time.","zh":"如果痕跡大約每九天形成一次，科學家可以用它們估計時間。"},{"en":"The phrase “or so” shows the number is approximate.","zh":"or so 這個說法顯示數字是近似值。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":13},{"front":"acquire ridges","meaning":"形成脊狀紋","examples":[{"en":"Growing teeth acquire ridges on their enamel surface.","zh":"正在生長的牙齒在牙釉質表面形成脊狀紋。"},{"en":"To acquire ridges means to develop raised lines or marks over time.","zh":"acquire ridges 是指隨時間形成凸起的線條或痕跡。"},{"en":"A road may acquire ridges after years of heavy traffic.","zh":"道路經過多年繁忙交通後，可能形成凸起紋路。"},{"en":"Teeth acquire ridges as they grow, creating a record of development.","zh":"牙齒在生長時形成脊狀紋，創造出發育記錄。"},{"en":"Scientists count these ridges to estimate how long a tooth took to form.","zh":"科學家計算這些脊狀紋，以估計牙齒形成所需時間。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":13},{"front":"enamel surface","meaning":"牙釉質表面","examples":[{"en":"The ridges appear on the enamel surface of teeth.","zh":"這些脊狀紋出現在牙齒的牙釉質表面。"},{"en":"The enamel surface is the hard outer layer covering a tooth.","zh":"牙釉質表面是覆蓋牙齒的堅硬外層。"},{"en":"Dentists protect the enamel surface because it helps prevent tooth decay.","zh":"牙醫保護牙釉質表面，因為它有助防止蛀牙。"},{"en":"Marks on the enamel surface can preserve evidence of how a tooth grew.","zh":"牙釉質表面上的痕跡可以保存牙齒如何生長的證據。"},{"en":"In fossil teeth, the enamel surface may still show tiny growth ridges.","zh":"在化石牙齒中，牙釉質表面可能仍顯示微小生長脊紋。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":13},{"front":"like rings in a tree trunk","meaning":"像樹幹年輪","examples":[{"en":"The ridges are like rings in a tree trunk.","zh":"這些脊狀紋像樹幹年輪。"},{"en":"Like rings in a tree trunk means forming regular marks that can be counted to show time or growth.","zh":"像樹幹年輪是指形成可被計算、顯示時間或生長的規律痕跡。"},{"en":"Teeth ridges are compared to tree rings because both preserve a growth record.","zh":"牙齒脊狀紋被比作樹輪，因為兩者都保存生長記錄。"},{"en":"A teacher may use this comparison to help students understand tooth development.","zh":"老師可能使用這個比較，幫助學生理解牙齒發育。"},{"en":"The phrase makes a difficult scientific idea easier to imagine.","zh":"這個短語令困難的科學概念更容易想像。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":13},{"front":"tree trunk","meaning":"樹幹","examples":[{"en":"Tooth ridges are compared to rings in a tree trunk.","zh":"牙齒脊狀紋被比作樹幹中的年輪。"},{"en":"A tree trunk is the main thick stem of a tree that supports branches and carries water.","zh":"樹幹是樹木主要而粗大的莖，支撐樹枝並運送水分。"},{"en":"Children can see growth rings when a tree trunk is cut across.","zh":"當樹幹被橫切時，孩子可以看見生長年輪。"},{"en":"The tree trunk preserves evidence of years of growth inside its wood.","zh":"樹幹在其木材內保存多年生長的證據。"},{"en":"Comparing teeth with a tree trunk helps explain how natural growth can record time.","zh":"把牙齒與樹幹比較，有助解釋自然生長如何記錄時間。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":13},{"front":"crown of a tooth","meaning":"牙冠","examples":[{"en":"The ridges show how long the crown of a tooth took to form.","zh":"這些脊狀紋顯示牙冠形成需時多久。"},{"en":"The crown of a tooth is the visible upper part of a tooth above the gum.","zh":"牙冠是牙齒在牙齦以上可見的上部。"},{"en":"Dentists check the crown of a tooth for decay, cracks, or damage.","zh":"牙醫檢查牙冠是否有蛀牙、裂痕或損傷。"},{"en":"Growth marks on the crown of a tooth can help scientists estimate development time.","zh":"牙冠上的生長痕跡可以幫助科學家估計發育時間。"},{"en":"In fossil teeth, the crown of a tooth may preserve useful evidence even after many years.","zh":"在化石牙齒中，即使多年後，牙冠仍可能保存有用證據。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":13},{"front":"take to form","meaning":"需要……形成","examples":[{"en":"The number of ridges shows how long the tooth took to form.","zh":"脊狀紋數量顯示牙齒需要多久形成。"},{"en":"Take to form means require a certain amount of time to develop or be created.","zh":"take to form 是指需要某段時間發展或形成。"},{"en":"A cake may take an hour to form properly in the oven.","zh":"蛋糕可能需要一小時在焗爐中完全成形。"},{"en":"A habit can take months to form if it requires daily practice.","zh":"如果習慣需要每日練習，可能需要數月形成。"},{"en":"Teeth take time to form, and their ridges can record that process.","zh":"牙齒需要時間形成，而其脊狀紋可以記錄這個過程。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":13},{"front":"across mammals","meaning":"在各種哺乳動物之中","examples":[{"en":"Across mammals, tooth development is linked to brain growth.","zh":"在各種哺乳動物之中，牙齒發育與大腦生長有關。"},{"en":"Across mammals means when comparing many different mammal species.","zh":"across mammals 是指比較許多不同哺乳動物物種時。"},{"en":"Across mammals, mothers feed their young with milk, though details differ.","zh":"在各種哺乳動物之中，母親都以乳汁餵養幼兒，雖然細節不同。"},{"en":"Scientists look across mammals to find patterns that apply beyond one species.","zh":"科學家觀察各種哺乳動物，以找出不只適用於單一物種的模式。"},{"en":"Across mammals, tooth growth can provide clues about development and maturity.","zh":"在各種哺乳動物之中，牙齒生長可以提供關於發育和成熟的線索。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":13},{"front":"rate at which","meaning":"……的速度","examples":[{"en":"The rate at which teeth develop is closely related to maturity.","zh":"牙齒發育的速度與成熟密切相關。"},{"en":"The rate at which something happens means the speed of that process.","zh":"the rate at which something happens 是指某過程發生的速度。"},{"en":"The rate at which students learn new words depends on practice and review.","zh":"學生學習新詞的速度取決於練習和複習。"},{"en":"Doctors monitor the rate at which a wound heals.","zh":"醫生監測傷口癒合的速度。"},{"en":"In this passage, the rate at which teeth develop helps reveal life history.","zh":"在本文中，牙齒發育的速度幫助揭示生命史。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":14},{"front":"closely related to","meaning":"與……密切相關","examples":[{"en":"Tooth development is closely related to brain growth.","zh":"牙齒發育與大腦生長密切相關。"},{"en":"Closely related to means strongly connected with something.","zh":"closely related to 是指與某事有強烈連繫。"},{"en":"Poor sleep is closely related to weak concentration and low mood.","zh":"睡眠不足與專注力差和情緒低落密切相關。"},{"en":"In children, nutrition is closely related to physical growth.","zh":"在兒童中，營養與身體生長密切相關。"},{"en":"Scientists say tooth development is closely related to brain growth across mammals.","zh":"科學家說，在各種哺乳動物之中，牙齒發育與大腦生長密切相關。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":14},{"front":"how fast the brain grows","meaning":"大腦生長得有多快","examples":[{"en":"Tooth development is related to how fast the brain grows.","zh":"牙齒發育與大腦生長得有多快有關。"},{"en":"How fast the brain grows means the speed at which the brain develops in size and complexity.","zh":"how fast the brain grows 是指大腦在大小和複雜程度上發展的速度。"},{"en":"Doctors study how fast the brain grows during early childhood.","zh":"醫生研究大腦在幼兒期生長得有多快。"},{"en":"If the brain grows slowly, childhood may last longer in some species.","zh":"如果大腦生長較慢，某些物種的童年可能較長。"},{"en":"Tooth evidence may help researchers estimate how fast the brain grows.","zh":"牙齒證據可能幫助研究人員估計大腦生長得有多快。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":14},{"front":"age you mature","meaning":"成熟年齡","examples":[{"en":"Tooth development is linked to the age you mature.","zh":"牙齒發育與成熟年齡有關。"},{"en":"The age you mature means the age at which you become physically or developmentally adult.","zh":"成熟年齡是指你在身體或發育上成為成人的年齡。"},{"en":"Different animals reach the age they mature at different speeds.","zh":"不同動物以不同速度達到成熟年齡。"},{"en":"Nutrition and biology can affect the age a young person matures.","zh":"營養和生物因素可以影響年輕人的成熟年齡。"},{"en":"Teeth may help scientists estimate the age an ancient individual matured.","zh":"牙齒可能幫助科學家估計古代個體的成熟年齡。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":14},{"front":"good indicators of","meaning":"……的良好指標","examples":[{"en":"Teeth are good indicators of life history.","zh":"牙齒是生命史的良好指標。"},{"en":"Good indicators of something are signs that help show or measure it reliably.","zh":"某事的良好指標是有助可靠顯示或量度它的跡象。"},{"en":"Regular attendance can be a good indicator of student commitment.","zh":"規律出席可以是學生投入程度的良好指標。"},{"en":"Blood pressure is a good indicator of certain health risks.","zh":"血壓是某些健康風險的良好指標。"},{"en":"Teeth are good indicators of development because their growth patterns are preserved clearly.","zh":"牙齒是發育的良好指標，因為其生長模式被清楚保存。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":14},{"front":"life history","meaning":"生命史；成長歷程","examples":[{"en":"Teeth are good indicators of life history.","zh":"牙齒是生命史的良好指標。"},{"en":"Life history means the pattern of growth, development, reproduction, and lifespan of an organism.","zh":"生命史是指生物的生長、發育、繁殖和壽命模式。"},{"en":"Biologists study life history to compare how fast different animals mature.","zh":"生物學家研究生命史，以比較不同動物成熟得有多快。"},{"en":"A species with a slow life history may have long childhood and late reproduction.","zh":"生命史較慢的物種可能有漫長童年和較晚繁殖。"},{"en":"Teeth can reveal life history because they record growth timing.","zh":"牙齒可以揭示生命史，因為它們記錄生長時間。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":14},{"front":"be less related to","meaning":"與……較少相關","examples":[{"en":"Tooth growth is less related to environment and nutrition than skeleton growth.","zh":"牙齒生長與環境和營養的關係比骨骼生長較少。"},{"en":"To be less related to something means to be affected by it less strongly.","zh":"be less related to 是指受某事影響較少或關聯較弱。"},{"en":"A student’s handwriting may be less related to intelligence than to practice and habit.","zh":"學生的字跡可能與智力較少相關，而與練習和習慣較多相關。"},{"en":"Tooth growth may be less related to diet than bone growth is.","zh":"牙齒生長可能比骨骼生長較少受飲食影響。"},{"en":"This phrase is useful when comparing the strength of two connections.","zh":"比較兩種關聯的強弱時，這個短語很有用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":14},{"front":"environment and nutrition","meaning":"環境和營養","examples":[{"en":"Tooth growth is less affected by environment and nutrition.","zh":"牙齒生長較少受環境和營養影響。"},{"en":"Environment and nutrition mean living conditions and the food or nutrients an organism receives.","zh":"環境和營養是指生活條件，以及生物獲得的食物或養分。"},{"en":"A child’s height can be influenced by environment and nutrition.","zh":"兒童身高可能受環境和營養影響。"},{"en":"Poor environment and nutrition can delay physical growth and weaken health.","zh":"差劣環境和營養會延遲身體生長並削弱健康。"},{"en":"Teeth are useful evidence because they may be less affected by environment and nutrition than bones.","zh":"牙齒是有用證據，因為它們可能比骨骼較少受環境和營養影響。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":14},{"front":"a more decisive piece of evidence","meaning":"更具決定性的證據","examples":[{"en":"A more decisive piece of evidence came from Neanderthal teeth.","zh":"更具決定性的證據來自尼安德特人的牙齒。"},{"en":"A more decisive piece of evidence is stronger evidence that helps settle a question more clearly.","zh":"更具決定性的證據是能更清楚幫助解決問題的更強證據。"},{"en":"A video recording may be a more decisive piece of evidence than a vague memory.","zh":"影片記錄可能比模糊記憶更具決定性。"},{"en":"In science, a more decisive piece of evidence can make one explanation seem more likely.","zh":"在科學中，更具決定性的證據可以令某個解釋顯得更可能。"},{"en":"Neanderthal teeth mattered because they provided a clearer clue about growth speed.","zh":"尼安德特人牙齒很重要，因為它們提供了關於生長速度的更清楚線索。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":14},{"front":"publish findings","meaning":"發表研究結果","examples":[{"en":"Researchers in France and Spain published their findings.","zh":"法國和西班牙的研究人員發表了研究結果。"},{"en":"To publish findings means to make research results publicly available, usually in a report or journal.","zh":"publish findings 是指公開研究結果，通常以報告或期刊形式發表。"},{"en":"Scientists publish findings so other experts can check and discuss them.","zh":"科學家發表研究結果，讓其他專家可以檢查和討論。"},{"en":"A school may publish findings from a survey about student wellbeing.","zh":"學校可能發表關於學生福祉調查的研究結果。"},{"en":"Publishing findings is important because research becomes more useful when others can read it.","zh":"發表研究結果很重要，因為當其他人可以閱讀時，研究會更有用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":14},{"front":"a study of Neanderthal teeth","meaning":"尼安德特人牙齒研究","examples":[{"en":"The evidence came from a study of Neanderthal teeth.","zh":"證據來自一項尼安德特人牙齒研究。"},{"en":"A study of Neanderthal teeth is research that examines teeth from Neanderthal fossils.","zh":"尼安德特人牙齒研究是檢查尼安德特人化石牙齒的研究。"},{"en":"Scientists conduct a study of Neanderthal teeth to understand age, growth, and development.","zh":"科學家進行尼安德特人牙齒研究，以理解年齡、生長和發育。"},{"en":"A study of Neanderthal teeth can reveal information that bones alone may not show.","zh":"尼安德特人牙齒研究可以揭示單靠骨骼未必顯示的資訊。"},{"en":"This kind of study helps compare Neanderthals with Homo erectus and modern humans.","zh":"這類研究有助比較尼安德特人、直立人和現代人類。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":14},{"front":"much faster tooth growth","meaning":"快得多的牙齒生長","examples":[{"en":"Neanderthals had much faster tooth growth than Homo erectus.","zh":"尼安德特人的牙齒生長比直立人快得多。"},{"en":"Much faster tooth growth means teeth developed at a far quicker rate.","zh":"快得多的牙齒生長是指牙齒以遠快得多的速度發育。"},{"en":"A child with faster tooth growth may get adult teeth earlier than classmates.","zh":"牙齒生長較快的孩子可能比同學更早長出恆齒。"},{"en":"Much faster tooth growth may suggest a shorter childhood or earlier maturity.","zh":"快得多的牙齒生長可能暗示較短童年或較早成熟。"},{"en":"In Neanderthals, much faster tooth growth supports the idea that they grew up quickly.","zh":"在尼安德特人中，快得多的牙齒生長支持他們快速長大的想法。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":15},{"front":"precede them","meaning":"早於他們存在","examples":[{"en":"Homo erectus preceded Neanderthals.","zh":"直立人早於尼安德特人存在。"},{"en":"To precede them means to exist or happen before them.","zh":"precede them 是指在他們之前存在或發生。"},{"en":"Primary school precedes secondary school in most education systems.","zh":"在大多數教育制度中，小學早於中學。"},{"en":"A warning sign should precede a dangerous bend on the road.","zh":"危險彎位前應有警告標誌。"},{"en":"If Homo erectus preceded Neanderthals, it lived earlier in human evolutionary history.","zh":"如果直立人早於尼安德特人存在，即是它在人類演化史中較早生活。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":15},{"front":"hence","meaning":"因此","examples":[{"en":"Neanderthals had faster tooth growth and hence a shorter childhood.","zh":"尼安德特人牙齒生長較快，因此童年較短。"},{"en":"Hence means therefore or as a result.","zh":"hence 是指因此或結果是。"},{"en":"The road was flooded; hence, the bus was delayed.","zh":"道路水浸；因此，巴士延誤。"},{"en":"The student practised daily and hence became more confident.","zh":"學生每天練習，因此變得更有信心。"},{"en":"In formal writing, hence connects a cause with its result.","zh":"在正式寫作中，hence 連接原因和結果。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":15},{"front":"shorter childhood","meaning":"較短的童年","examples":[{"en":"Neanderthals may have had a shorter childhood.","zh":"尼安德特人可能有較短的童年。"},{"en":"A shorter childhood means reaching maturity more quickly and spending fewer years as a child.","zh":"較短的童年是指更快達到成熟，作為兒童的年數較少。"},{"en":"In some animals, a shorter childhood helps young individuals reproduce earlier.","zh":"在某些動物中，較短的童年幫助年輕個體較早繁殖。"},{"en":"A harsh environment may favour a shorter childhood because survival is uncertain.","zh":"嚴酷環境可能有利於較短的童年，因為生存不確定。"},{"en":"Neanderthal tooth growth suggests they may have had a shorter childhood than modern humans.","zh":"尼安德特人的牙齒生長暗示他們可能比現代人類有較短的童年。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":15},{"front":"lead researcher","meaning":"首席研究員","examples":[{"en":"Fernando Ramirez-Rozzi was the lead researcher.","zh":"Fernando Ramirez-Rozzi 是首席研究員。"},{"en":"A lead researcher is the main scientist responsible for a study.","zh":"首席研究員是負責某項研究的主要科學家。"},{"en":"The lead researcher explains the results when a medical trial is published.","zh":"醫學試驗發表時，首席研究員會解釋結果。"},{"en":"A lead researcher coordinates the team, methods, and interpretation of evidence.","zh":"首席研究員協調團隊、方法和證據解讀。"},{"en":"Naming the lead researcher helps readers know who guided the research.","zh":"說出首席研究員的名字，有助讀者知道誰主導研究。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":15},{"front":"die young","meaning":"早逝","examples":[{"en":"Ramirez-Rozzi thinks Neanderthals died young.","zh":"Ramirez-Rozzi 認為尼安德特人早逝。"},{"en":"To die young means to die at a relatively early age.","zh":"die young 是指在相對年輕時死亡。"},{"en":"In dangerous environments, many animals die young because food and safety are uncertain.","zh":"在危險環境中，許多動物因食物和安全不穩定而早逝。"},{"en":"People may die young when disease, war, or harsh living conditions are common.","zh":"當疾病、戰爭或惡劣生活條件普遍時，人們可能早逝。"},{"en":"If Neanderthals died young, they may have evolved to grow up quickly.","zh":"如果尼安德特人早逝，他們可能演化成快速長大。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":15},{"front":"primarily because of","meaning":"主要因為","examples":[{"en":"Neanderthals may have died young primarily because of the harsh environment.","zh":"尼安德特人可能主要因為嚴酷環境而早逝。"},{"en":"Primarily because of means mainly because of one important cause.","zh":"primarily because of 是指主要由於一個重要原因。"},{"en":"The match was cancelled primarily because of heavy rain.","zh":"比賽主要因為大雨而取消。"},{"en":"A student may feel tired primarily because of poor sleep, not laziness.","zh":"學生可能主要因為睡眠不足而疲倦，不是懶惰。"},{"en":"This phrase identifies the main cause while allowing other causes to exist.","zh":"這個短語指出主要原因，同時容許其他原因存在。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":15},{"front":"cold, harsh environment","meaning":"寒冷惡劣的環境","examples":[{"en":"Neanderthals endured a cold, harsh environment.","zh":"尼安德特人忍受寒冷惡劣的環境。"},{"en":"A cold, harsh environment is a difficult place with low temperatures and severe living conditions.","zh":"寒冷惡劣的環境是低溫且生活條件嚴峻的困難地方。"},{"en":"People need strong shelter and warm clothing in a cold, harsh environment.","zh":"人們在寒冷惡劣的環境中需要堅固住所和保暖衣物。"},{"en":"A cold, harsh environment can make food scarce and survival difficult.","zh":"寒冷惡劣的環境會令食物稀少並使生存困難。"},{"en":"Neanderthals may have grown up quickly because their cold, harsh environment was dangerous.","zh":"尼安德特人可能快速長大，因為他們的寒冷惡劣環境很危險。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":15},{"front":"endure","meaning":"忍受","examples":[{"en":"Neanderthals had to endure glacial Europe.","zh":"尼安德特人必須忍受冰河時期的歐洲。"},{"en":"To endure means to suffer through a difficult situation and continue surviving.","zh":"endure 是指忍受困難情況並繼續生存。"},{"en":"Students may endure a long exam by staying calm and managing time.","zh":"學生可以透過保持冷靜和管理時間，忍受漫長考試。"},{"en":"Families endure hardship during unemployment by reducing spending and supporting one another.","zh":"家庭在失業期間透過減少開支和互相支持來忍受困境。"},{"en":"Neanderthals had to endure cold, hunger, and danger in Ice Age Europe.","zh":"尼安德特人必須在冰河時期歐洲忍受寒冷、飢餓和危險。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":15},{"front":"glacial Europe","meaning":"冰河時期的歐洲","examples":[{"en":"Neanderthals lived in glacial Europe.","zh":"尼安德特人生活在冰河時期的歐洲。"},{"en":"Glacial Europe refers to Europe during Ice Age conditions, when the climate was very cold.","zh":"glacial Europe 是指處於冰河時期條件下、氣候非常寒冷的歐洲。"},{"en":"Animals in glacial Europe needed thick fur or other cold-weather adaptations.","zh":"冰河時期歐洲的動物需要厚毛或其他寒冷天氣適應。"},{"en":"Human groups in glacial Europe had to find food and shelter in severe conditions.","zh":"冰河時期歐洲的人類群體必須在嚴酷條件中尋找食物和住所。"},{"en":"The phrase helps explain why Neanderthal life may have been short and difficult.","zh":"這個短語有助解釋為何尼安德特人的生活可能短暫而艱難。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":15},{"front":"evolve to","meaning":"演化成會……","examples":[{"en":"They evolved to grow up quicker than their immediate ancestors.","zh":"他們演化成比直接祖先更快長大。"},{"en":"To evolve to do something means to develop a feature or behaviour over many generations.","zh":"evolve to do something 是指經過許多世代發展出某種特徵或行為。"},{"en":"Desert plants evolved to save water in dry conditions.","zh":"沙漠植物演化成會在乾燥條件中保存水分。"},{"en":"Birds may evolve to have different beaks when food sources change.","zh":"當食物來源改變時，鳥類可能演化成有不同喙形。"},{"en":"Neanderthals may have evolved to mature quickly because their environment was harsh.","zh":"尼安德特人可能因環境嚴酷而演化成快速成熟。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":15},{"front":"grow up quicker","meaning":"更快長大","examples":[{"en":"Neanderthals evolved to grow up quicker.","zh":"尼安德特人演化成更快長大。"},{"en":"To grow up quicker means to reach maturity in less time.","zh":"grow up quicker 是指用較少時間達到成熟。"},{"en":"Some animals grow up quicker when their environment is dangerous and life is short.","zh":"當環境危險且壽命短時，有些動物會更快長大。"},{"en":"Children do not physically grow up quicker just because they take on adult responsibilities.","zh":"孩子不會只因承擔成人責任而在身體上更快長大。"},{"en":"Neanderthals may have grown up quicker because early adulthood improved survival chances.","zh":"尼安德特人可能更快長大，因為早些成年提高生存機會。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":16},{"front":"immediate ancestors","meaning":"直接祖先","examples":[{"en":"Neanderthals grew up quicker than their immediate ancestors.","zh":"尼安德特人比其直接祖先更快長大。"},{"en":"Immediate ancestors are the earlier relatives directly before a species or group in evolutionary history.","zh":"直接祖先是在演化史中某物種或群體之前較直接的早期親緣。"},{"en":"A family’s immediate ancestors might include parents and grandparents.","zh":"一個家庭的直接祖先可能包括父母和祖父母。"},{"en":"Scientists compare a species with its immediate ancestors to understand what changed.","zh":"科學家把一個物種與其直接祖先比較，以理解有甚麼改變。"},{"en":"If Neanderthals differed from their immediate ancestors, their environment may have shaped their development.","zh":"如果尼安德特人不同於其直接祖先，他們的環境可能塑造了其發育。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":16},{"front":"reach adulthood fairly quickly","meaning":"相當快地達到成年","examples":[{"en":"Neanderthals and Homo erectus probably had to reach adulthood fairly quickly.","zh":"尼安德特人和直立人可能必須相當快地達到成年。"},{"en":"To reach adulthood fairly quickly means to become mature in a relatively short time.","zh":"reach adulthood fairly quickly 是指在相對短時間內成熟。"},{"en":"Some animals reach adulthood fairly quickly so they can reproduce before predators kill them.","zh":"有些動物相當快地達到成年，以便在被捕食者殺死前繁殖。"},{"en":"In harsh conditions, reaching adulthood fairly quickly may improve survival.","zh":"在嚴酷條件下，相當快地達到成年可能提高生存機會。"},{"en":"The phrase suggests that long childhood may not have been useful for some ancient humans.","zh":"這個短語暗示漫長童年對某些古人類未必有用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":16},{"front":"without delaying for","meaning":"沒有因等待……而延遲","examples":[{"en":"They may have grown up without delaying for an adolescent growth spurt.","zh":"他們可能沒有因等待青春期急速生長而延遲長大。"},{"en":"Without delaying for something means without waiting longer because of that event or stage.","zh":"without delaying for 是指沒有因某事件或階段而等待更久。"},{"en":"The team finished the project without delaying for another meeting.","zh":"團隊沒有因等待另一場會議而延遲完成項目。"},{"en":"Some animals mature without delaying for a long learning period.","zh":"有些動物成熟時，沒有因等待漫長學習期而延遲。"},{"en":"If ancient humans grew up without delaying for adolescence, they may have had shorter childhoods.","zh":"如果古人類沒有因等待青春期而延遲長大，他們可能有較短童年。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":16},{"front":"it still looks as though","meaning":"看來仍然似乎是","examples":[{"en":"It still looks as though modern humans are the original teenagers.","zh":"看來仍然似乎現代人類是最早真正有青春期的人類。"},{"en":"It still looks as though means it still seems likely, based on available evidence.","zh":"it still looks as though 是指根據現有證據，某事仍似乎可能。"},{"en":"It still looks as though the picnic will happen, even though the sky is cloudy.","zh":"即使天空多雲，野餐看來仍然似乎會舉行。"},{"en":"After checking the data, it still looks as though the first theory is stronger.","zh":"檢查數據後，第一個理論看來仍然似乎較強。"},{"en":"This phrase shows cautious judgement rather than absolute certainty.","zh":"這個短語顯示謹慎判斷，而不是絕對確定。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":16},{"front":"the original teenagers","meaning":"最早真正有青春期的人類","examples":[{"en":"Modern humans may be the original teenagers.","zh":"現代人類可能是最早真正有青春期的人類。"},{"en":"The original teenagers means the first human group to have a true teenage phase.","zh":"the original teenagers 是指第一個真正有青少年階段的人類群體。"},{"en":"If modern humans were the original teenagers, earlier humans may have grown up more quickly.","zh":"如果現代人類是最早真正有青春期的人類，較早期人類可能更快長大。"},{"en":"The phrase is memorable because it describes an evolutionary idea in everyday language.","zh":"這個短語令人容易記住，因為它用日常語言描述演化思想。"},{"en":"Calling modern humans the original teenagers suggests adolescence may be one of our distinctive traits.","zh":"稱現代人類為最早真正有青春期的人類，暗示青春期可能是我們的獨特特徵之一。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":16},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Candidates choose the correct letter for each question.","zh":"考生為每題選出正確字母。"},{"en":"To choose the correct letter means to select the option label that matches the answer.","zh":"choose the correct letter 是指選擇與答案相符的選項字母。"},{"en":"In multiple-choice questions, students choose the correct letter after reading all options.","zh":"在多項選擇題中，學生閱讀所有選項後選出正確字母。"},{"en":"A careless student may know the answer but still choose the wrong letter.","zh":"粗心學生可能知道答案，但仍選錯字母。"},{"en":"This instruction tells candidates to answer with letters, not full sentences.","zh":"這個指示告訴考生用字母作答，而不是完整句子。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":16},{"front":"in the first paragraph","meaning":"在第一段","examples":[{"en":"The question asks about the writer’s meaning in the first paragraph.","zh":"題目問作者在第一段的意思。"},{"en":"In the first paragraph means in the opening section of the passage.","zh":"in the first paragraph 是指在文章開首段落中。"},{"en":"Students should look in the first paragraph when a question refers to the writer’s opening idea.","zh":"當題目提到作者開首想法時，學生應在第一段尋找。"},{"en":"The first paragraph often introduces the topic, problem, or main question.","zh":"第一段通常介紹題目、問題或主要疑問。"},{"en":"This phrase limits where students should search for evidence.","zh":"這個短語限制學生應在哪裡尋找證據。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":16},{"front":"the writer says","meaning":"作者說","examples":[{"en":"The question asks why the writer says the debate is important.","zh":"題目問為何作者說這場爭論很重要。"},{"en":"The writer says means the author states or suggests something in the passage.","zh":"the writer says 是指作者在文章中陳述或暗示某事。"},{"en":"Students should answer according to what the writer says, not their own opinion.","zh":"學生應根據作者說的內容回答，而不是根據自己的意見。"},{"en":"When the writer says a debate matters, readers should look for the reason given nearby.","zh":"當作者說某場爭論重要時，讀者應在附近尋找所給原因。"},{"en":"This phrase reminds students to focus on the text.","zh":"這個短語提醒學生集中於文本。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":16},{"front":"theories need to be backed up by","meaning":"理論需要由……支持","examples":[{"en":"Scientific theories need to be backed up by research.","zh":"科學理論需要由研究支持。"},{"en":"Theories need to be backed up by evidence means ideas require support from facts or studies.","zh":"理論需要由證據支持，是指想法需要事實或研究作支撐。"},{"en":"A student’s claim in an essay needs to be backed up by examples from the text.","zh":"學生在文章中的主張需要由文本例子支持。"},{"en":"Medical advice should be backed up by reliable research, not just personal stories.","zh":"醫療建議應由可靠研究支持，而不只是個人故事。"},{"en":"This phrase stresses that ideas alone are not enough.","zh":"這個短語強調只有想法本身是不足夠的。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":16},{"front":"practical research","meaning":"實證研究","examples":[{"en":"The option refers to practical research by anthropologists.","zh":"該選項提到人類學家的實證研究。"},{"en":"Practical research is research based on real investigation, observation, or evidence rather than theory alone.","zh":"實證研究是基於真實調查、觀察或證據的研究，而不只是理論。"},{"en":"A school may conduct practical research by testing which teaching method helps students most.","zh":"學校可能透過測試哪種教學方法最能幫助學生，進行實證研究。"},{"en":"Practical research can challenge old ideas when real evidence does not match them.","zh":"當真實證據與舊想法不符時，實證研究可以挑戰舊想法。"},{"en":"In anthropology, practical research may include fossil study, fieldwork, and measurement.","zh":"在人類學中，實證研究可能包括化石研究、田野工作和量度。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":16},{"front":"important misunderstandings","meaning":"重要誤解","examples":[{"en":"The option mentions important misunderstandings among anthropologists.","zh":"該選項提到人類學家之間的重要誤解。"},{"en":"Important misunderstandings are serious wrong ideas that can affect how people interpret a topic.","zh":"重要誤解是會影響人們如何解讀某題目的嚴重錯誤想法。"},{"en":"Important misunderstandings about health can lead people to avoid proper treatment.","zh":"關於健康的重要誤解可能令人避開適當治療。"},{"en":"In research, important misunderstandings may continue if evidence is weak or unclear.","zh":"在研究中，如果證據薄弱或不清楚，重要誤解可能持續。"},{"en":"Correcting important misunderstandings helps people make better decisions.","zh":"糾正重要誤解幫助人們作出更好決定。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":17},{"front":"attitudes towards","meaning":"對……的態度","examples":[{"en":"The option discusses attitudes towards adolescence.","zh":"該選項討論對青春期的態度。"},{"en":"Attitudes towards something are the feelings, beliefs, or opinions people have about it.","zh":"attitudes towards something 是指人們對某事的感受、信念或意見。"},{"en":"Parents’ attitudes towards homework can influence how children study.","zh":"父母對功課的態度會影響孩子如何學習。"},{"en":"Public attitudes towards mental health have changed in many places.","zh":"許多地方公眾對心理健康的態度已經改變。"},{"en":"Understanding attitudes towards adolescence helps explain how societies treat young people.","zh":"理解對青春期的態度有助解釋社會如何對待年輕人。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":17},{"front":"inform our understanding of","meaning":"加深我們對……的理解","examples":[{"en":"Anthropologists’ work could inform our understanding of modern adolescence.","zh":"人類學家的工作可以加深我們對現代青春期的理解。"},{"en":"To inform our understanding of something means to improve or shape how we understand it.","zh":"inform our understanding of 是指改善或塑造我們對某事的理解。"},{"en":"Student feedback can inform our understanding of which lessons work best.","zh":"學生回饋可以加深我們對哪些課堂最有效的理解。"},{"en":"Medical research informs our understanding of how sleep affects memory.","zh":"醫學研究加深我們對睡眠如何影響記憶的理解。"},{"en":"Fossil evidence may inform our understanding of why modern adolescence exists.","zh":"化石證據可能加深我們對現代青春期為何存在的理解。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":17},{"front":"modern adolescence","meaning":"現代青春期","examples":[{"en":"The research may help explain modern adolescence.","zh":"這項研究可能有助解釋現代青春期。"},{"en":"Modern adolescence is the teenage stage as experienced by humans today.","zh":"現代青春期是今天人類所經歷的青少年階段。"},{"en":"Modern adolescence often includes school, identity changes, physical growth, and increasing independence.","zh":"現代青春期通常包括上學、身份變化、身體生長和逐漸獨立。"},{"en":"Studying ancient development may help explain why modern adolescence lasts so long.","zh":"研究古代發育可能有助解釋為何現代青春期持續如此長。"},{"en":"Modern adolescence is both biological and social, so it can be studied from many angles.","zh":"現代青春期既是生物性的，也是社會性的，所以可以從許多角度研究。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":17},{"front":"Susan Anton’s opinion of","meaning":"Susan Anton 對……的看法","examples":[{"en":"The question asks about Susan Anton’s opinion of the Turkana boy.","zh":"題目問 Susan Anton 對圖爾卡納男孩的看法。"},{"en":"Susan Anton’s opinion of something means what she thinks or argues about it.","zh":"Susan Anton’s opinion of something 是指她對某事的想法或主張。"},{"en":"A reading question may ask for a scientist’s opinion of a fossil, not just a fact about it.","zh":"閱讀題可能問某科學家對化石的看法，而不只是關於化石的事實。"},{"en":"Susan Anton’s opinion of the Turkana boy matters because it challenges an older idea.","zh":"Susan Anton 對圖爾卡納男孩的看法很重要，因為它挑戰舊想法。"},{"en":"Students should find textual evidence before deciding what a researcher’s opinion is.","zh":"學生在判斷研究人員的看法前，應先找文本證據。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":17},{"front":"had he lived","meaning":"如果他活下去的話","examples":[{"en":"The Turkana boy may have experienced adolescence had he lived.","zh":"如果圖爾卡納男孩活下去的話，他可能會經歷青春期。"},{"en":"Had he lived means if he had continued living instead of dying.","zh":"had he lived 是指如果他繼續活著，而不是死亡。"},{"en":"Had she lived, the artist might have produced many more paintings.","zh":"如果那位藝術家活下去的話，她可能創作更多畫作。"},{"en":"Had he lived longer, the child may have entered another stage of growth.","zh":"如果他活得更久，那個孩子可能進入另一個生長階段。"},{"en":"This phrase is a formal way to discuss an unreal past possibility.","zh":"這個短語是討論過去未實現可能性的正式方式。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":17},{"front":"reached adulthood","meaning":"已達成年","examples":[{"en":"The option asks whether his skull showed that he had reached adulthood.","zh":"該選項問他的頭骨是否顯示他已達成年。"},{"en":"Reached adulthood means became fully mature as an adult.","zh":"reached adulthood 是指已完全成熟為成人。"},{"en":"A person may have reached adulthood legally but still be developing emotionally.","zh":"一個人可能在法律上已達成年，但情感上仍在發展。"},{"en":"Bones and skull shape can help researchers decide whether someone had reached adulthood.","zh":"骨骼和頭骨形狀可以幫助研究人員判斷某人是否已達成年。"},{"en":"In the passage, the skull suggests the Turkana boy had not yet reached adulthood.","zh":"在文章中，頭骨暗示圖爾卡納男孩尚未達成年。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":17},{"front":"be compared to","meaning":"與……比較","examples":[{"en":"His skeleton and teeth can be compared to modern evidence.","zh":"他的骨骼和牙齒可以與現代證據比較。"},{"en":"To be compared to something means to be examined alongside it to find similarities or differences.","zh":"be compared to 是指與某事並列檢視，以找出相似或差異。"},{"en":"A student’s essay can be compared to a model answer to see what is missing.","zh":"學生文章可以與範文比較，以看出缺少甚麼。"},{"en":"Fossils are compared to modern skeletons to estimate age and development.","zh":"化石與現代骨骼比較，以估計年齡和發育。"},{"en":"Comparing one thing to another helps researchers understand what is normal or unusual.","zh":"把一件事與另一件事比較，幫助研究人員理解甚麼是正常或不尋常。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":17},{"front":"a more modern age","meaning":"較現代的年代","examples":[{"en":"The option refers to skeletons from a more modern age.","zh":"該選項指較現代年代的骨骼。"},{"en":"A more modern age means a later historical period closer to the present.","zh":"較現代的年代是指較接近現在的後期歷史時期。"},{"en":"Skeletons from a more modern age may have written records that ancient fossils lack.","zh":"較現代年代的骨骼可能有古代化石缺乏的書面記錄。"},{"en":"Objects from a more modern age are often easier to date because documents survive.","zh":"來自較現代年代的物件通常較容易定年，因為文件仍保存。"},{"en":"Comparing fossils with skeletons from a more modern age can test scientific methods.","zh":"把化石與較現代年代的骨骼比較，可以測試科學方法。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":17},{"front":"grown much faster than","meaning":"比……長得快得多","examples":[{"en":"The option asks whether he grew much faster than others.","zh":"該選項問他是否比其他人長得快得多。"},{"en":"Grown much faster than means increased in size at a far higher speed than someone or something else.","zh":"grown much faster than 是指以遠高於其他人或事物的速度增長。"},{"en":"One child may have grown much faster than classmates during early puberty.","zh":"一個孩子可能在青春期早期比同學長得快得多。"},{"en":"A plant grown much faster than others may have received more sunlight or water.","zh":"比其他植物長得快得多的植物，可能獲得更多陽光或水分。"},{"en":"This phrase compares growth speed, not final size alone.","zh":"這個短語比較的是生長速度，而不只是最終大小。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":17},{"front":"alive at the time","meaning":"當時在世的其他人","examples":[{"en":"The option refers to others alive at the time.","zh":"該選項指當時在世的其他人。"},{"en":"Alive at the time means living during the same period being discussed.","zh":"alive at the time 是指在所討論的同一時期活著。"},{"en":"People alive at the time of the war often remembered food shortages clearly.","zh":"戰爭時期在世的人通常清楚記得食物短缺。"},{"en":"To compare growth, scientists ask whether other individuals alive at the time developed similarly.","zh":"為了比較生長，科學家會問當時在世的其他個體是否發育相似。"},{"en":"This phrase helps place people or animals in the same historical moment.","zh":"這個短語幫助把人或動物放在同一歷史時刻中。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":17},{"front":"make a point","meaning":"提出觀點","examples":[{"en":"Steven Leigh makes a point about growth and food supply.","zh":"Steven Leigh 提出關於生長和食物供應的觀點。"},{"en":"To make a point means to state an idea clearly in order to explain or argue something.","zh":"make a point 是指清楚提出一個想法，以解釋或論證某事。"},{"en":"A teacher may make a point by giving a simple example after a difficult rule.","zh":"老師可能在困難規則後給出簡單例子來提出觀點。"},{"en":"In a debate, people make points to support their side.","zh":"在辯論中，人們提出觀點來支持自己一方。"},{"en":"Leigh makes a point by questioning why human growth suddenly speeds up.","zh":"Leigh 透過質疑為何人類生長突然加速來提出觀點。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":18},{"front":"develop at different speeds","meaning":"以不同速度發育","examples":[{"en":"The option asks whether different parts of the skeleton develop at different speeds.","zh":"該選項問骨骼不同部分是否以不同速度發育。"},{"en":"To develop at different speeds means to grow or mature at unequal rates.","zh":"develop at different speeds 是指以不相同的速度生長或成熟。"},{"en":"Children may develop at different speeds in reading, speech, and physical coordination.","zh":"兒童在閱讀、說話和身體協調方面可能以不同速度發育。"},{"en":"Teeth and bones can develop at different speeds, creating different age estimates.","zh":"牙齒和骨骼可以以不同速度發育，造成不同年齡估計。"},{"en":"This phrase helps explain why one body part may suggest one age while another suggests a different age.","zh":"這個短語有助解釋為何一個身體部位暗示一個年齡，而另一個部位暗示不同年齡。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":18},{"front":"be confined to","meaning":"限於","examples":[{"en":"The growth period may be confined to times with enough food.","zh":"生長期可能限於有足夠食物的時候。"},{"en":"To be confined to something means to be limited to that place, time, or situation.","zh":"be confined to 是指被限制在某地方、時間或情況。"},{"en":"The meeting was confined to urgent safety issues.","zh":"會議限於緊急安全問題。"},{"en":"Some animals’ breeding season is confined to months when food is available.","zh":"有些動物的繁殖季節限於食物可得的月份。"},{"en":"If growth is confined to times with enough food, timing becomes important for survival.","zh":"如果生長限於有足夠食物的時候，時間安排對生存就變得重要。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":18},{"front":"enough food","meaning":"足夠食物","examples":[{"en":"Some growth periods occur when there is enough food.","zh":"有些生長期在有足夠食物時出現。"},{"en":"Enough food means sufficient food to support health, energy, and growth.","zh":"足夠食物是指足以支持健康、能量和生長的食物。"},{"en":"Children need enough food to concentrate, play, and develop normally.","zh":"兒童需要足夠食物才能專注、玩耍和正常發育。"},{"en":"If animals do not have enough food during growth, they may become weak or die.","zh":"如果動物在生長期間沒有足夠食物，牠們可能變弱或死亡。"},{"en":"Growth spurts are safer when enough food is available.","zh":"當有足夠食物可用時，急速生長期會較安全。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":18},{"front":"depending on","meaning":"取決於","examples":[{"en":"The option mentions development depending on living conditions.","zh":"該選項提到發育取決於生活條件。"},{"en":"Depending on means being affected or decided by a particular factor.","zh":"depending on 是指受某個因素影響或由其決定。"},{"en":"The travel time changes depending on traffic.","zh":"交通時間會取決於交通情況而改變。"},{"en":"A student’s progress may vary depending on practice, feedback, and rest.","zh":"學生進步可能取決於練習、回饋和休息而不同。"},{"en":"Development may differ depending on food, climate, safety, and care.","zh":"發育可能取決於食物、氣候、安全和照顧而有所不同。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":18},{"front":"living conditions","meaning":"生活條件","examples":[{"en":"Human development may be affected by living conditions.","zh":"人類發育可能受生活條件影響。"},{"en":"Living conditions are the circumstances in which people live, such as housing, food, safety, and health care.","zh":"生活條件是人們生活的環境，例如住屋、食物、安全和醫療。"},{"en":"Poor living conditions can make children more likely to become ill.","zh":"差劣生活條件會令兒童更容易生病。"},{"en":"Better living conditions may improve growth, learning, and life expectancy.","zh":"較好生活條件可能改善生長、學習和預期壽命。"},{"en":"In ancient humans, living conditions may have influenced how quickly young people matured.","zh":"在古代人類中，生活條件可能影響年輕人多快成熟。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":18},{"front":"lasts longer","meaning":"持續更久","examples":[{"en":"The option asks whether the growth phase lasts longer with more food.","zh":"該選項問如果有更多食物，生長階段是否持續更久。"},{"en":"Lasts longer means continues for a greater amount of time.","zh":"lasts longer 是指持續較長時間。"},{"en":"A phone battery lasts longer if the screen brightness is low.","zh":"如果螢幕亮度低，手機電池會持續更久。"},{"en":"A growth phase may last longer if development is slow or conditions support continued growth.","zh":"如果發育較慢或條件支持持續生長，生長階段可能持續更久。"},{"en":"This phrase focuses on duration, not speed.","zh":"這個短語集中於持續時間，而不是速度。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":18},{"front":"if more food is available","meaning":"如果有更多食物可用","examples":[{"en":"The option discusses whether growth lasts longer if more food is available.","zh":"該選項討論如果有更多食物可用，生長是否持續更久。"},{"en":"If more food is available means if there is a greater supply of food.","zh":"if more food is available 是指如果有更大量食物供應。"},{"en":"Animals may reproduce more successfully if more food is available.","zh":"如果有更多食物可用，動物可能更成功繁殖。"},{"en":"Children can grow better if more food is available and nutrition improves.","zh":"如果有更多食物可用且營養改善，兒童可以生長得更好。"},{"en":"In evolution, food availability can affect the timing and success of growth.","zh":"在演化中，食物供應可以影響生長時間和成功程度。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":18},{"front":"what can we learn from","meaning":"我們可以從……得知甚麼","examples":[{"en":"The question asks what we can learn from a mammal’s teeth.","zh":"題目問我們可以從哺乳動物的牙齒得知甚麼。"},{"en":"What can we learn from something means what information it can give us.","zh":"what can we learn from 是指某事物可以給我們甚麼資訊。"},{"en":"What can we learn from old photos about family life in the past?","zh":"我們可以從舊照片得知過去家庭生活的甚麼？"},{"en":"Scientists ask what they can learn from teeth because teeth preserve growth records.","zh":"科學家問可以從牙齒得知甚麼，因為牙齒保存生長記錄。"},{"en":"This phrase invites readers to treat an object as evidence.","zh":"這個短語引導讀者把物件視為證據。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":18},{"front":"poor diet","meaning":"不良飲食","examples":[{"en":"The option asks whether a poor diet slows tooth growth.","zh":"該選項問不良飲食是否減慢牙齒生長。"},{"en":"A poor diet is a way of eating that lacks enough nutrients for health and growth.","zh":"不良飲食是缺乏足夠健康和生長所需營養的飲食方式。"},{"en":"A poor diet may include too much sugar and too few fruits, vegetables, or proteins.","zh":"不良飲食可能包括太多糖分，以及太少水果、蔬菜或蛋白質。"},{"en":"Children with a poor diet may feel tired and grow less well.","zh":"有不良飲食的兒童可能感到疲倦且生長較差。"},{"en":"In the passage, tooth growth is said to be less affected by diet than skeleton growth.","zh":"在文章中，牙齒生長被說成比骨骼生長較少受飲食影響。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":18},{"front":"better indication of","meaning":"……的更好指標","examples":[{"en":"The option says teeth may be a better indication of lifestyle than skeletons.","zh":"該選項說牙齒可能比骨骼更能作為生活方式的指標。"},{"en":"A better indication of something is a clearer or more reliable sign of it.","zh":"better indication of something 是指某事更清楚或更可靠的跡象。"},{"en":"Daily attendance may be a better indication of effort than one test score.","zh":"每日出席可能比一次測驗分數更能作為努力程度的指標。"},{"en":"Long-term spending habits are a better indication of financial health than one shopping trip.","zh":"長期消費習慣比一次購物更能作為財務健康的指標。"},{"en":"Teeth may be a better indication of development because they are less affected by environment.","zh":"牙齒可能是發育的更好指標，因為它們較少受環境影響。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":18},{"front":"difficult to predict accurately","meaning":"難以準確預測","examples":[{"en":"The option says their growing period is difficult to predict accurately.","zh":"該選項說牠們的生長期難以準確預測。"},{"en":"Difficult to predict accurately means hard to forecast correctly or precisely.","zh":"difficult to predict accurately 是指難以正確或精確預測。"},{"en":"It is difficult to predict accurately how long traffic will take during a storm.","zh":"暴風雨期間，交通需時多久難以準確預測。"},{"en":"A child’s final height can be difficult to predict accurately from one measurement.","zh":"單靠一次量度，兒童最終身高可能難以準確預測。"},{"en":"Fossil growth can be difficult to predict accurately when evidence is incomplete.","zh":"當證據不完整時，化石生長可能難以準確預測。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":19},{"front":"speed of growth","meaning":"生長速度","examples":[{"en":"Their speed of growth is related to development.","zh":"牠們的生長速度與發育有關。"},{"en":"Speed of growth means how quickly something grows.","zh":"speed of growth 是指某事物生長得有多快。"},{"en":"Parents may worry if a child’s speed of growth suddenly becomes very slow.","zh":"如果孩子生長速度突然變得很慢，父母可能會擔心。"},{"en":"The speed of growth can depend on genes, nutrition, and environment.","zh":"生長速度可以取決於基因、營養和環境。"},{"en":"Tooth growth speed can help scientists understand how quickly an animal matured.","zh":"牙齒生長速度可以幫助科學家理解動物成熟得有多快。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":19},{"front":"directly related to","meaning":"與……直接相關","examples":[{"en":"The option says tooth growth is directly related to body development.","zh":"該選項說牙齒生長與身體發育直接相關。"},{"en":"Directly related to means clearly and closely connected with something.","zh":"directly related to 是指與某事清楚而密切相連。"},{"en":"A student’s test score may be directly related to how much they revised.","zh":"學生測驗分數可能與他們溫習多少直接相關。"},{"en":"In health, smoking is directly related to several serious diseases.","zh":"在健康方面，吸煙與幾種嚴重疾病直接相關。"},{"en":"The phrase suggests a strong connection, not a weak or indirect one.","zh":"這個短語暗示強烈關係，而不是薄弱或間接關係。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":19},{"front":"body’s speed of development","meaning":"身體發育速度","examples":[{"en":"The option refers to the body’s speed of development.","zh":"該選項提到身體發育速度。"},{"en":"The body’s speed of development means how quickly the body grows and becomes mature.","zh":"身體發育速度是指身體生長並成熟得有多快。"},{"en":"A doctor may check the body’s speed of development by measuring height, weight, and bone growth.","zh":"醫生可能透過量度身高、體重和骨骼生長來檢查身體發育速度。"},{"en":"The body’s speed of development can differ from tooth development.","zh":"身體發育速度可以不同於牙齒發育。"},{"en":"Comparing tooth growth with the body’s speed of development helps researchers judge maturity.","zh":"把牙齒生長與身體發育速度比較，幫助研究人員判斷成熟程度。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":19},{"front":"agree with the claims of","meaning":"與……的說法一致","examples":[{"en":"Students decide whether statements agree with the claims of the writer.","zh":"學生判斷陳述是否與作者的說法一致。"},{"en":"To agree with the claims of someone means to match what that person says or argues.","zh":"agree with the claims of someone 是指與某人所說或主張的內容相符。"},{"en":"In reading exams, an answer agrees with the writer’s claims only if the passage supports it.","zh":"在閱讀考試中，只有文章支持某答案，它才與作者說法一致。"},{"en":"A statement may sound true but not agree with the claims of the writer.","zh":"一句陳述可能聽起來真實，但不一定與作者說法一致。"},{"en":"Students should look for evidence before deciding whether a statement agrees with the claims.","zh":"學生在判斷陳述是否與說法一致前，應尋找證據。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":19},{"front":"contradict the views of","meaning":"與……的觀點相矛盾","examples":[{"en":"Students write NO if a statement contradicts the writer’s views.","zh":"如果陳述與作者觀點相矛盾，學生寫 NO。"},{"en":"To contradict the views of someone means to say the opposite of what that person believes or states.","zh":"contradict the views of someone 是指說出與某人相信或陳述相反的內容。"},{"en":"A student’s answer contradicts the passage if it says the reverse of the writer’s claim.","zh":"如果學生答案說的是作者主張的相反內容，就與文章相矛盾。"},{"en":"Evidence can contradict the views of experts when new facts appear.","zh":"當新事實出現時，證據可以與專家觀點相矛盾。"},{"en":"In reading tasks, contradiction is different from information that is simply not mentioned.","zh":"在閱讀題中，矛盾不同於只是沒有提及的資訊。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":19},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"Students write NOT GIVEN if it is impossible to say what the writer thinks.","zh":"如果無法判斷作者怎樣想，學生寫 NOT GIVEN。"},{"en":"Impossible to say means there is not enough information to know the answer.","zh":"impossible to say 是指沒有足夠資料知道答案。"},{"en":"It is impossible to say who left the door open without more evidence.","zh":"沒有更多證據，就無法判斷誰把門打開。"},{"en":"In reading exams, if the passage gives no clear evidence, the answer may be impossible to say.","zh":"在閱讀考試中，如果文章沒有清楚證據，答案可能無法判斷。"},{"en":"This phrase warns students not to guess beyond the text.","zh":"這個短語提醒學生不要超出文本猜測。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":19},{"front":"do research on","meaning":"對……進行研究","examples":[{"en":"It is difficult to do research on human fossils because they are rare.","zh":"對人類化石進行研究很困難，因為它們很稀少。"},{"en":"To do research on something means to study it carefully to gain knowledge.","zh":"do research on 是指仔細研究某事以獲得知識。"},{"en":"Students do research on a topic before writing a report.","zh":"學生在寫報告前對題目進行研究。"},{"en":"Scientists do research on fossils by measuring, comparing, and dating them.","zh":"科學家透過量度、比較和定年來對化石進行研究。"},{"en":"It is harder to do research on a subject when evidence is limited.","zh":"當證據有限時，對某題目進行研究會更困難。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":19},{"front":"human fossils are rare","meaning":"人類化石稀少","examples":[{"en":"Human fossils are rare, making research difficult.","zh":"人類化石稀少，令研究困難。"},{"en":"Human fossils are rare means few preserved remains of ancient humans have been found.","zh":"人類化石稀少是指被發現的古人類保存遺骸很少。"},{"en":"Because human fossils are rare, each new discovery can be scientifically important.","zh":"因為人類化石稀少，每項新發現都可能在科學上重要。"},{"en":"Research becomes difficult when human fossils are rare and incomplete.","zh":"當人類化石稀少且不完整時，研究會變得困難。"},{"en":"This idea explains why scientists cannot answer every question about ancient adolescence.","zh":"這個想法解釋了為何科學家不能回答關於古代青春期的每個問題。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":19},{"front":"modern methods","meaning":"現代方法","examples":[{"en":"The option asks whether modern methods can predict skeleton age accurately.","zh":"該選項問現代方法是否能準確預測骨骼年齡。"},{"en":"Modern methods are recent techniques or tools used to study or solve problems.","zh":"現代方法是用於研究或解決問題的近期技術或工具。"},{"en":"Hospitals use modern methods such as scans and blood tests to diagnose illness.","zh":"醫院使用掃描和血液檢查等現代方法診斷疾病。"},{"en":"Modern methods can improve research, but they do not always remove uncertainty.","zh":"現代方法可以改善研究，但不一定消除不確定性。"},{"en":"In fossil studies, modern methods still depend on the quality of the evidence.","zh":"在化石研究中，現代方法仍取決於證據質素。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":19},{"front":"predict the age of","meaning":"預測……的年齡","examples":[{"en":"Scientists try to predict the age of a skeleton.","zh":"科學家嘗試預測骨骼的年齡。"},{"en":"To predict the age of something means to estimate how old it is using evidence.","zh":"predict the age of 是指使用證據估計某物有多老。"},{"en":"A vet may predict the age of a stray cat by checking its teeth.","zh":"獸醫可能透過檢查牙齒來預測流浪貓的年齡。"},{"en":"Archaeologists predict the age of bones by comparing them with known examples.","zh":"考古學家透過把骨骼與已知例子比較來預測骨骼年齡。"},{"en":"Predicting the age of a skeleton is difficult when growth markers disagree.","zh":"當生長標記不一致時，預測骨骼年齡很困難。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":19},{"front":"conclusion about","meaning":"關於……的結論","examples":[{"en":"The question refers to Susan Anton’s conclusion about the Turkana boy.","zh":"題目指 Susan Anton 關於圖爾卡納男孩的結論。"},{"en":"A conclusion about something is the final judgement or explanation reached after considering evidence.","zh":"conclusion about something 是指考慮證據後得出的最終判斷或解釋。"},{"en":"A teacher’s conclusion about a student’s progress should be based on several pieces of work.","zh":"老師關於學生進步的結論應基於幾份作品。"},{"en":"Scientists may change a conclusion about a fossil when new evidence appears.","zh":"當新證據出現時，科學家可能改變關於化石的結論。"},{"en":"Anton’s conclusion about the Turkana boy suggests he may have been near adolescence.","zh":"Anton 關於圖爾卡納男孩的結論暗示他可能接近青春期。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":20},{"front":"reinforce an established idea","meaning":"加強既有觀點","examples":[{"en":"The option asks whether her conclusion reinforces an established idea.","zh":"該選項問她的結論是否加強既有觀點。"},{"en":"To reinforce an established idea means to strengthen a belief that is already accepted.","zh":"reinforce an established idea 是指加強一個已被接受的信念。"},{"en":"New exam results may reinforce an established idea that practice improves writing.","zh":"新考試結果可能加強練習能改善寫作這一既有觀點。"},{"en":"Evidence can reinforce an established idea, but it can also challenge it.","zh":"證據可以加強既有觀點，但也可以挑戰它。"},{"en":"In the passage, Anton’s conclusion appears to challenge rather than reinforce the older view.","zh":"在文章中，Anton 的結論似乎是挑戰而不是加強舊觀點。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":20},{"front":"be met with disbelief","meaning":"遭到質疑；令人難以置信","examples":[{"en":"Steven Leigh’s ideas may be met with disbelief.","zh":"Steven Leigh 的想法可能遭到質疑。"},{"en":"To be met with disbelief means to receive doubt or unwillingness to believe from others.","zh":"be met with disbelief 是指受到他人的懷疑或不願相信。"},{"en":"A student’s excuse may be met with disbelief if it sounds unlikely.","zh":"如果學生的藉口聽起來不太可能，可能會遭到質疑。"},{"en":"A new theory may be met with disbelief when it challenges a long-held view.","zh":"當新理論挑戰長期持有的觀點時，可能會遭到質疑。"},{"en":"Leigh’s ideas may be met with disbelief because they push the origin of adolescence very far back.","zh":"Leigh 的想法可能遭到質疑，因為它把青春期起源推到非常久遠以前。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":20},{"front":"unique method of analysing","meaning":"分析……的獨特方法","examples":[{"en":"The option asks whether researchers developed a unique method of analysing teeth.","zh":"該選項問研究人員是否發展出分析牙齒的獨特方法。"},{"en":"A unique method of analysing something is a special or unusual way of studying it.","zh":"unique method of analysing something 是指研究某事的特殊或不尋常方法。"},{"en":"Scientists may use a unique method of analysing handwriting to identify old documents.","zh":"科學家可能使用分析筆跡的獨特方法來識別舊文件。"},{"en":"A unique method of analysing teeth could reveal details ordinary methods miss.","zh":"分析牙齒的獨特方法可以揭示普通方法錯過的細節。"},{"en":"This phrase focuses on how evidence is studied, not just what evidence is found.","zh":"這個短語集中於證據如何被研究，而不只是找到甚麼證據。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":20},{"front":"comparing the brains of","meaning":"比較……的大腦","examples":[{"en":"The option refers to comparing the brains of Homo erectus and Neanderthals.","zh":"該選項提到比較直立人和尼安德特人的大腦。"},{"en":"Comparing the brains of two groups means examining their brain size, shape, or development together.","zh":"comparing the brains of two groups 是指一起檢視兩個群體的大腦大小、形狀或發育。"},{"en":"Scientists compare the brains of different animals to understand intelligence and behaviour.","zh":"科學家比較不同動物的大腦，以理解智力和行為。"},{"en":"Comparing the brains of ancient humans is difficult because soft brain tissue does not fossilise.","zh":"比較古人類的大腦很困難，因為柔軟腦組織不會化石化。"},{"en":"Researchers may use skull shape as indirect evidence when comparing ancient brains.","zh":"研究人員在比較古代大腦時，可能使用頭骨形狀作間接證據。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":20},{"front":"complete each sentence with","meaning":"用……完成每句","examples":[{"en":"Candidates complete each sentence with the correct ending.","zh":"考生用正確結尾完成每句。"},{"en":"To complete each sentence with something means to finish every sentence using the required words or option.","zh":"complete each sentence with something 是指使用所需字詞或選項完成每個句子。"},{"en":"In grammar practice, students complete each sentence with the correct verb form.","zh":"在文法練習中，學生用正確動詞形式完成每句。"},{"en":"Candidates should read the whole sentence before choosing the ending.","zh":"考生在選擇結尾前應閱讀整個句子。"},{"en":"This instruction tests whether students can match meaning and grammar.","zh":"這個指示測試學生是否能配對意思和文法。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":20},{"front":"correct ending","meaning":"正確結尾","examples":[{"en":"Each sentence must be matched with the correct ending.","zh":"每句必須與正確結尾配對。"},{"en":"A correct ending is the option that completes a sentence logically and grammatically.","zh":"正確結尾是能在邏輯和文法上完成句子的選項。"},{"en":"In a reading task, the correct ending must match the passage, not just sound natural.","zh":"在閱讀任務中，正確結尾必須符合文章，而不只是聽起來自然。"},{"en":"Students should check whether the correct ending creates a complete and accurate sentence.","zh":"學生應檢查正確結尾是否形成完整且準確的句子。"},{"en":"Choosing the correct ending requires understanding both the sentence start and the text evidence.","zh":"選擇正確結尾需要理解句子開首和文本證據。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":20},{"front":"delayed growth","meaning":"延遲生長","examples":[{"en":"Delayed growth in humans was linked to dependence on others.","zh":"人類的延遲生長與依賴他人有關。"},{"en":"Delayed growth means growth that happens later or more slowly than expected.","zh":"延遲生長是指生長比預期更遲或更慢發生。"},{"en":"A child may have delayed growth because of illness or poor nutrition.","zh":"孩子可能因疾病或營養不良而延遲生長。"},{"en":"In humans, delayed growth may allow more time for brain development and learning.","zh":"在人類中，延遲生長可能讓大腦發育和學習有更多時間。"},{"en":"The older theory explained adolescence as a result of delayed growth.","zh":"舊理論把青春期解釋為延遲生長的結果。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":20},{"front":"be due to","meaning":"由於","examples":[{"en":"Delayed growth was thought to be due to dependence and brain development.","zh":"延遲生長被認為是由於依賴和大腦發展。"},{"en":"To be due to something means to be caused by it.","zh":"be due to 是指由某事造成。"},{"en":"The delay was due to heavy rain and road closures.","zh":"延誤是由於大雨和封路。"},{"en":"A student’s tiredness may be due to lack of sleep rather than lack of effort.","zh":"學生疲倦可能是由於睡眠不足，而不是缺乏努力。"},{"en":"This phrase is useful when explaining causes.","zh":"解釋原因時，這個短語很有用。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":20},{"front":"a need to be dependent on others","meaning":"需要依賴他人","examples":[{"en":"Delayed growth was thought to reflect a need to be dependent on others.","zh":"延遲生長被認為反映需要依賴他人。"},{"en":"A need to be dependent on others means needing support, care, or protection from other people.","zh":"需要依賴他人是指需要其他人的支援、照顧或保護。"},{"en":"Young children have a need to be dependent on others because they cannot feed or protect themselves.","zh":"年幼兒童需要依賴他人，因為他們不能餵養或保護自己。"},{"en":"If a species has a long learning period, it may also have a need to be dependent on others.","zh":"如果一個物種有漫長學習期，它可能也需要依賴他人。"},{"en":"In the theory, human children stay small partly because they need adult care.","zh":"在該理論中，人類兒童保持細小，部分原因是他們需要成人照顧。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":20},{"front":"for survival","meaning":"為了生存","examples":[{"en":"Young humans depend on others for survival.","zh":"年幼人類為了生存而依賴他人。"},{"en":"For survival means in order to stay alive.","zh":"for survival 是指為了活下去。"},{"en":"Plants need water and sunlight for survival.","zh":"植物為了生存需要水和陽光。"},{"en":"In cold weather, shelter and warm clothing are important for survival.","zh":"在寒冷天氣中，住所和保暖衣物對生存很重要。"},{"en":"Human children need adults for survival because they cannot meet basic needs alone.","zh":"人類兒童為了生存需要成年人，因為他們不能獨自滿足基本需要。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":20},{"front":"discover inconsistencies","meaning":"發現不一致之處","examples":[{"en":"Margaret Clegg discovered inconsistencies between different age indicators.","zh":"Margaret Clegg 發現不同年齡指標之間的不一致之處。"},{"en":"To discover inconsistencies means to find differences or contradictions that do not fit together.","zh":"discover inconsistencies 是指發現彼此不吻合的差異或矛盾。"},{"en":"A teacher may discover inconsistencies between a student’s homework and exam answers.","zh":"老師可能發現學生功課和考試答案之間的不一致之處。"},{"en":"Accountants discover inconsistencies when numbers in two records do not match.","zh":"當兩份記錄中的數字不吻合時，會計師會發現不一致之處。"},{"en":"In fossil studies, discovering inconsistencies warns researchers not to trust one marker alone.","zh":"在化石研究中，發現不一致之處提醒研究人員不要只信任一個標記。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":21},{"front":"inconsistencies between","meaning":"……之間的不一致","examples":[{"en":"There were inconsistencies between height, skeleton and dental evidence.","zh":"身高、骨骼和牙齒證據之間存在不一致。"},{"en":"Inconsistencies between things are differences or conflicts that make them not match.","zh":"inconsistencies between things 是指事物之間使它們不吻合的差異或衝突。"},{"en":"Inconsistencies between a timetable and a notice can confuse students.","zh":"時間表和通知之間的不一致會令學生困惑。"},{"en":"Inconsistencies between witness reports may make an investigation more difficult.","zh":"目擊者報告之間的不一致可能令調查更困難。"},{"en":"Age estimates become uncertain when there are inconsistencies between different body markers.","zh":"當不同身體標記之間存在不一致時，年齡估計會變得不確定。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":21},{"front":"height, skeleton and dental evidence","meaning":"身高、骨骼和牙齒證據","examples":[{"en":"Age estimates may differ between height, skeleton and dental evidence.","zh":"年齡估計在身高、骨骼和牙齒證據之間可能不同。"},{"en":"Height, skeleton and dental evidence are three kinds of physical clues used to estimate age.","zh":"身高、骨骼和牙齒證據是用來估計年齡的三類身體線索。"},{"en":"A child may look older in height but younger in dental evidence.","zh":"一個孩子在身高上可能看似較年長，但在牙齒證據上較年輕。"},{"en":"Skeleton and dental evidence can disagree because different body parts develop at different speeds.","zh":"骨骼和牙齒證據可能不一致，因為不同身體部分以不同速度發育。"},{"en":"Researchers compare height, skeleton and dental evidence to avoid relying on one clue only.","zh":"研究人員比較身高、骨骼和牙齒證據，以避免只依賴一個線索。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":21},{"front":"the existence of adolescence","meaning":"青春期的存在","examples":[{"en":"Steven Leigh thought the existence of adolescence was linked to walking.","zh":"Steven Leigh 認為青春期的存在與行走有關。"},{"en":"The existence of adolescence means the fact that a teenage stage exists at all.","zh":"青春期的存在是指青少年階段確實存在這一事實。"},{"en":"Scientists debate the existence of adolescence in ancient humans because fossil evidence is limited.","zh":"科學家爭論古人類是否存在青春期，因為化石證據有限。"},{"en":"If the existence of adolescence is linked to walking, it may have very ancient origins.","zh":"如果青春期的存在與行走有關，它可能有非常古老的起源。"},{"en":"This phrase focuses on whether adolescence existed, not just what it was like.","zh":"這個短語集中於青春期是否存在，而不只是它是甚麼樣子。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":21},{"front":"be connected to","meaning":"與……有關","examples":[{"en":"Leigh thought adolescence was connected to walking on two legs.","zh":"Leigh 認為青春期與用兩條腿行走有關。"},{"en":"To be connected to something means to be related or linked to it.","zh":"be connected to 是指與某事相關或相連。"},{"en":"Poor concentration may be connected to lack of sleep.","zh":"專注力差可能與睡眠不足有關。"},{"en":"A festival may be connected to harvest, religion, or local history.","zh":"節日可能與收成、宗教或本地歷史有關。"},{"en":"Leigh’s theory connects adolescence to the evolution of upright walking.","zh":"Leigh 的理論把青春期與直立行走的演化連接起來。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":21},{"front":"the fact that","meaning":"……這一事實","examples":[{"en":"The theory depends on the fact that humans walk on two legs.","zh":"這個理論取決於人類用兩條腿行走這一事實。"},{"en":"The fact that introduces a true or accepted point used in an explanation.","zh":"the fact that 用來引入解釋中真實或被接受的一點。"},{"en":"The fact that the road is closed means we need another route.","zh":"道路封閉這一事實意味著我們需要另一條路線。"},{"en":"A teacher may mention the fact that students learn differently before offering choices.","zh":"老師可能在提供選擇前提到學生學習方式不同這一事實。"},{"en":"This phrase turns a statement into a reason or basis for an argument.","zh":"這個短語把一個陳述變成論點的原因或基礎。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":21},{"front":"walk on two legs","meaning":"用兩條腿行走","examples":[{"en":"Human beings walk on two legs.","zh":"人類用兩條腿行走。"},{"en":"To walk on two legs means to move upright using the two lower limbs.","zh":"walk on two legs 是指使用兩條下肢直立移動。"},{"en":"Children usually learn to walk on two legs after crawling and standing.","zh":"兒童通常在爬行和站立後學會用兩條腿行走。"},{"en":"Walking on two legs frees the hands for carrying objects and using tools.","zh":"用兩條腿行走使雙手可以拿東西和使用工具。"},{"en":"The fact that humans walk on two legs is central to Leigh’s theory of adolescence.","zh":"人類用兩條腿行走這一事實，是 Leigh 青春期理論的核心。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":21},{"front":"research on Neanderthals","meaning":"尼安德特人研究","examples":[{"en":"Research on Neanderthals suggests that they had short lives.","zh":"尼安德特人研究顯示他們壽命短暫。"},{"en":"Research on Neanderthals is scientific study of Neanderthal fossils, tools, genes, and living conditions.","zh":"尼安德特人研究是對尼安德特人化石、工具、基因和生活條件的科學研究。"},{"en":"Researchers use teeth and bones in research on Neanderthals to study growth and age.","zh":"研究人員在尼安德特人研究中使用牙齒和骨骼來研究生長和年齡。"},{"en":"Research on Neanderthals helps compare them with modern humans.","zh":"尼安德特人研究幫助比較他們與現代人類。"},{"en":"This research may explain why Neanderthals grew up faster than some earlier humans.","zh":"這項研究可能解釋為何尼安德特人比某些較早期人類更快長大。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":21},{"front":"short lives","meaning":"短暫壽命","examples":[{"en":"Research suggests that Neanderthals had short lives.","zh":"研究顯示尼安德特人壽命短暫。"},{"en":"Short lives means lives that ended relatively early.","zh":"短暫壽命是指生命相對較早結束。"},{"en":"In dangerous environments, many animals have short lives because they face hunger and predators.","zh":"在危險環境中，許多動物因面對飢餓和捕食者而壽命短暫。"},{"en":"Short lives may favour faster growth and earlier maturity.","zh":"短暫壽命可能有利於較快生長和較早成熟。"},{"en":"If Neanderthals had short lives, they may not have benefited from a long adolescent stage.","zh":"如果尼安德特人壽命短暫，他們可能不會受益於漫長青春期。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":21},{"front":"because of","meaning":"因為","examples":[{"en":"Neanderthals may have had short lives because of difficult climatic conditions.","zh":"尼安德特人可能因為惡劣氣候條件而壽命短暫。"},{"en":"Because of means for the reason of or as a result of something.","zh":"because of 是指由於某事或作為某事的結果。"},{"en":"The class was cancelled because of bad weather.","zh":"課堂因為惡劣天氣而取消。"},{"en":"A plant may die because of too little water.","zh":"植物可能因為水分太少而死亡。"},{"en":"Neanderthals may have matured quickly because of the harsh climate they faced.","zh":"尼安德特人可能因為面對嚴酷氣候而快速成熟。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":21},{"front":"difficult climatic conditions","meaning":"惡劣氣候條件","examples":[{"en":"Neanderthals endured difficult climatic conditions.","zh":"尼安德特人忍受惡劣氣候條件。"},{"en":"Difficult climatic conditions are harsh weather or climate patterns that make survival harder.","zh":"惡劣氣候條件是令生存更困難的嚴酷天氣或氣候模式。"},{"en":"Farmers struggle under difficult climatic conditions such as drought, frost, or floods.","zh":"農民在乾旱、霜凍或洪水等惡劣氣候條件下會很吃力。"},{"en":"Difficult climatic conditions can reduce food supply and increase danger.","zh":"惡劣氣候條件可以減少食物供應並增加危險。"},{"en":"For Neanderthals, difficult climatic conditions may have encouraged faster development.","zh":"對尼安德特人而言，惡劣氣候條件可能促使更快發育。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":21},{"front":"increased quantities of food","meaning":"增加的食物數量","examples":[{"en":"The option refers to increased quantities of food.","zh":"該選項提到增加的食物數量。"},{"en":"Increased quantities of food means larger amounts of food becoming available.","zh":"increased quantities of food 是指可用食物數量增加。"},{"en":"Increased quantities of food after harvest can help a village prepare for winter.","zh":"收成後增加的食物數量可以幫助村莊準備過冬。"},{"en":"Animals may grow or reproduce more successfully when increased quantities of food are available.","zh":"當有增加的食物數量可用時，動物可能更成功生長或繁殖。"},{"en":"In growth studies, increased quantities of food may affect timing, size, and survival.","zh":"在生長研究中，增加的食物數量可能影響時間、體型和生存。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":22},{"front":"much larger brains than previously","meaning":"比以前認為大得多的大腦","examples":[{"en":"The option refers to the existence of much larger brains than previously thought.","zh":"該選項提到存在比以前認為大得多的大腦。"},{"en":"Much larger brains than previously thought means brains that were far bigger than earlier researchers believed.","zh":"much larger brains than previously thought 是指大腦比早期研究人員相信的大得多。"},{"en":"New fossil measurements may show that a species had much larger brains than previously thought.","zh":"新化石量度可能顯示某物種有比以前認為大得多的大腦。"},{"en":"If ancient humans had much larger brains than previously believed, theories of development might change.","zh":"如果古人類有比以前認為大得多的大腦，發育理論可能會改變。"},{"en":"This phrase shows how new evidence can revise older scientific assumptions.","zh":"這個短語顯示新證據如何修正舊有科學假設。"}],"source":"138 - Have teenagers always existed.pdf","sourcePage":22}],"ielts/reading/passage-2/Practice 139":[{"front":"the Practical Prophet","meaning":"實幹型先知；具遠見的實幹家","examples":[{"en":"Brunel is presented as the Practical Prophet because his engineering ideas looked far ahead of his time.","zh":"布魯內爾被呈現為具遠見的實幹家，因為他的工程構想遠遠走在時代前面。"},{"en":"The Practical Prophet is a person who has bold future-looking ideas but also knows how to turn them into real projects.","zh":"實幹型先知是指有大膽遠見，同時知道如何把構想變成實際項目的人。"},{"en":"A teacher who predicts future job skills and designs useful lessons could be called a practical prophet.","zh":"一位能預見未來工作技能並設計實用課程的老師，可被稱為實幹型先知。"},{"en":"A practical prophet is valuable because vision alone is not enough; plans must also work in real life.","zh":"實幹型先知很有價值，因為單有願景並不足夠；計劃也必須在現實中可行。"},{"en":"The phrase suggests both imagination and practical ability.","zh":"這個片語暗示想像力和實踐能力並存。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":1},{"front":"frontispiece","meaning":"卷首插圖；書前頁","examples":[{"en":"The frontispiece of Peter Hay’s book includes a quotation about engineers.","zh":"Peter Hay 的書前頁包含一段關於工程師的引文。"},{"en":"A frontispiece is an illustration or page placed near the beginning of a book.","zh":"frontispiece 是放在書本開頭附近的插圖或頁面。"},{"en":"An old history book may have a frontispiece showing a portrait of the main figure.","zh":"一本舊歷史書可能有卷首插圖，展示主要人物的肖像。"},{"en":"A frontispiece can prepare readers for the theme before the main text begins.","zh":"卷首插圖可以在正文開始前，為讀者預備主題。"},{"en":"The word is usually used when discussing printed books, especially older or formal ones.","zh":"這個詞通常用於討論印刷書籍，尤其是較舊或較正式的書。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":1},{"front":"quote from","meaning":"引用自……","examples":[{"en":"Peter Hay quotes from Nicholson’s British Encyclopaedia of 1909.","zh":"Peter Hay 引用了1909年《Nicholson’s British Encyclopaedia》中的文字。"},{"en":"Quote from means repeat words taken from a book, speech, article, or other source.","zh":"quote from 指重複引用一本書、演講、文章或其他來源中的文字。"},{"en":"A student may quote from a textbook to support an essay point.","zh":"學生可能引用教科書中的文字來支持作文觀點。"},{"en":"If you quote from a source, readers should know where the words came from.","zh":"如果你引用某來源，讀者應知道那些文字來自哪裡。"},{"en":"This phrase is useful when showing evidence rather than only giving your own opinion.","zh":"這個片語在展示證據，而不只是表達個人意見時很有用。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":1},{"front":"as follows","meaning":"如下","examples":[{"en":"The quotation reads as follows.","zh":"該引文內容如下。"},{"en":"As follows means the next words or list will give the exact details.","zh":"as follows 指接下來的文字或列表會給出確切細節。"},{"en":"The rules are as follows: arrive on time, bring your ID, and switch off your phone.","zh":"規則如下：準時到達、帶身份證、關掉手機。"},{"en":"Writers use as follows before presenting information in a clear order.","zh":"作者會在有條理地呈現資料前使用 as follows。"},{"en":"The phrase is formal and often introduces a quotation, list, or explanation.","zh":"這個片語較正式，常用來引出引文、列表或解釋。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":1},{"front":"extremely necessary for","meaning":"對……極為必要","examples":[{"en":"Engineers were described as extremely necessary for these purposes.","zh":"工程師被描述為對這些目的極為必要。"},{"en":"Extremely necessary for means very important or almost essential for a particular purpose.","zh":"extremely necessary for 指對某個特定目的非常重要或幾乎不可或缺。"},{"en":"Clean water is extremely necessary for hospitals to operate safely.","zh":"清潔食水對醫院安全運作極為必要。"},{"en":"If a project involves bridges and tunnels, engineers are extremely necessary for planning and safety.","zh":"如果一個項目涉及橋樑和隧道，工程師對規劃和安全極為必要。"},{"en":"The phrase shows that something is not optional but strongly needed.","zh":"這個片語顯示某物不是可有可無，而是非常需要。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":1},{"front":"it is requisite that","meaning":"……是必要的","examples":[{"en":"The text says it is requisite that engineers should be ingenious and brave.","zh":"文中說工程師必須有創意和勇氣。"},{"en":"It is requisite that means it is necessary that something should happen or be true.","zh":"it is requisite that 指某事發生或成立是必要的。"},{"en":"It is requisite that nurses check patient records before giving medicine.","zh":"護士在給藥前檢查病人記錄是必要的。"},{"en":"If safety is at risk, it is requisite that workers follow the rules exactly.","zh":"如果安全受到威脅，工人準確遵守規則是必要的。"},{"en":"The phrase is formal and stronger than it is useful that.","zh":"這個片語較正式，比 it is useful that 語氣更強。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":1},{"front":"besides being","meaning":"除了……之外","examples":[{"en":"Besides being ingenious, engineers should also be brave.","zh":"除了有創意之外，工程師也應該勇敢。"},{"en":"Besides being means in addition to having a particular quality or role.","zh":"besides being 指除了具有某種特質或角色之外。"},{"en":"Besides being a doctor, she is also a teacher at a medical school.","zh":"除了是醫生之外，她也是醫學院老師。"},{"en":"Besides being cheap, a product must also be safe and reliable.","zh":"除了便宜之外，產品也必須安全可靠。"},{"en":"The phrase adds another important feature to one already mentioned.","zh":"這個片語在已提及的特點之外，再加入另一個重要特點。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":1},{"front":"ingenious","meaning":"有創意的；機智巧妙的","examples":[{"en":"Engineers need to be ingenious when solving practical problems.","zh":"工程師在解決實際問題時需要有創意。"},{"en":"Ingenious means clever, inventive, and able to find smart solutions.","zh":"ingenious 指聰明、有創造力，並能想出巧妙解決方法。"},{"en":"An ingenious student may fix a broken bag with a paper clip and some string.","zh":"一個機智的學生可能用萬字夾和繩子修好破袋子。"},{"en":"Ingenious ideas are useful because they solve problems with limited resources.","zh":"巧妙構想很有用，因為它們能用有限資源解決問題。"},{"en":"The word praises practical creativity, not just book knowledge.","zh":"這個詞讚揚的是實用創意，而不只是書本知識。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":1},{"front":"in proportion","meaning":"相應地；按比例地","examples":[{"en":"The quotation says engineers should be brave in proportion.","zh":"該引文說工程師也應相應地勇敢。"},{"en":"In proportion means in a suitable amount compared with something else.","zh":"in proportion 指與其他事物相比，以合適的數量或程度。"},{"en":"A small child needs food in proportion to their age and body size.","zh":"小孩需要與年齡和體型相稱的食物。"},{"en":"If risk increases, safety checks should increase in proportion.","zh":"如果風險增加，安全檢查也應相應增加。"},{"en":"The phrase suggests balance rather than too much or too little.","zh":"這個片語暗示平衡，而不是過多或過少。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":1},{"front":"famous engineer","meaning":"著名工程師","examples":[{"en":"Sir Marc Isambard Brunel was himself a famous engineer.","zh":"馬克·伊桑巴德·布魯內爾爵士本人是一位著名工程師。"},{"en":"A famous engineer is someone widely known for designing or building important structures or machines.","zh":"famous engineer 指因設計或建造重要結構或機器而廣為人知的人。"},{"en":"A famous engineer may be remembered for bridges, railways, ships, or inventions.","zh":"著名工程師可能因橋樑、鐵路、船隻或發明而被記住。"},{"en":"If an engineer solves a difficult public problem, their reputation can grow quickly.","zh":"如果工程師解決困難的公共問題，其名聲可以迅速提升。"},{"en":"The phrase focuses on professional achievement and public recognition.","zh":"這個片語集中於專業成就和公眾認可。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":1},{"front":"of French parents","meaning":"父母是法國人","examples":[{"en":"Sir Marc Isambard Brunel was of French parents.","zh":"馬克·伊桑巴德·布魯內爾爵士的父母是法國人。"},{"en":"Of French parents means someone’s parents were French.","zh":"of French parents 指某人的父母是法國人。"},{"en":"A child of French parents may grow up hearing French at home.","zh":"父母是法國人的孩子可能在家中聽法語長大。"},{"en":"If someone is of French parents but lives in Britain, they may connect with both cultures.","zh":"如果某人父母是法國人但住在英國，他可能與兩種文化都有聯繫。"},{"en":"The phrase describes family origin rather than birthplace alone.","zh":"這個片語描述家庭來源，而不只是出生地。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":2},{"front":"eventually settled in","meaning":"最終定居於……","examples":[{"en":"Sir Marc eventually settled in Britain.","zh":"馬克爵士最終定居於英國。"},{"en":"Eventually settled in means finally began living permanently or for a long time in a place.","zh":"eventually settled in 指最後開始在某地永久或長期生活。"},{"en":"After several moves, the family eventually settled in a small coastal town.","zh":"幾次搬遷後，這個家庭最終定居於一個沿海小鎮。"},{"en":"People may eventually settle in a country after finding work and building friendships.","zh":"人們找到工作並建立友誼後，可能最終定居於某個國家。"},{"en":"The phrase suggests a journey or period of change before becoming stable.","zh":"這個片語暗示在穩定下來之前曾經歷旅程或變化。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":2},{"front":"in earlier days","meaning":"在早些日子；從前","examples":[{"en":"He married an Englishwoman whom he had known in France in earlier days.","zh":"他娶了一位他從前在法國認識的英國女子。"},{"en":"In earlier days means at a previous time in the past.","zh":"in earlier days 指在過去較早的時候。"},{"en":"In earlier days, students wrote essays by hand instead of typing them.","zh":"從前，學生用手寫文章，而不是打字。"},{"en":"If two people knew each other in earlier days, they may reconnect years later.","zh":"如果兩人在早些日子已認識，他們可能多年後重新聯絡。"},{"en":"The phrase gives a gentle historical or nostalgic tone.","zh":"這個片語帶有溫和的歷史感或懷舊語氣。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":2},{"front":"at the age of","meaning":"在……歲時","examples":[{"en":"Isambard was sent to France at the age of 14.","zh":"伊桑巴德在14歲時被送往法國。"},{"en":"At the age of means when someone was a particular age.","zh":"at the age of 指某人在某個年齡時。"},{"en":"She learned to swim at the age of six.","zh":"她在六歲時學會游泳。"},{"en":"If a child studies abroad at the age of 14, they may become independent early.","zh":"如果孩子在14歲時到海外讀書，可能較早變得獨立。"},{"en":"The phrase is used to connect an event with a person’s age.","zh":"這個片語用來把事件與某人的年齡連接起來。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":2},{"front":"study mathematics and science","meaning":"學習數學和科學","examples":[{"en":"Brunel went to France to study mathematics and science.","zh":"布魯內爾前往法國學習數學和科學。"},{"en":"Study mathematics and science means learn subjects involving numbers, measurement, nature, and physical laws.","zh":"study mathematics and science 指學習涉及數字、測量、自然和物理定律的科目。"},{"en":"Students who study mathematics and science often practise problem-solving and experiments.","zh":"學習數學和科學的學生常練習解難和實驗。"},{"en":"Studying mathematics and science can prepare someone for engineering work.","zh":"學習數學和科學可以為工程工作作準備。"},{"en":"The phrase describes formal learning in technical subjects.","zh":"這個片語描述技術科目的正式學習。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":2},{"front":"return to England","meaning":"返回英格蘭","examples":[{"en":"He was 16 when he returned to England to work with his father.","zh":"他16歲時返回英格蘭，與父親一起工作。"},{"en":"Return to England means go back to England after being somewhere else.","zh":"return to England 指在身處其他地方後回到英格蘭。"},{"en":"After studying abroad, a student may return to England to find work.","zh":"留學後，學生可能返回英格蘭找工作。"},{"en":"If someone returns to England with new skills, they may use them in family business.","zh":"如果某人帶着新技能返回英格蘭，他可能把技能用於家族事業。"},{"en":"The phrase focuses on movement back to a previous country or home.","zh":"這個片語集中於回到之前的國家或家園。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":2},{"front":"work with","meaning":"與……一起工作","examples":[{"en":"Isambard returned to England to work with his father.","zh":"伊桑巴德返回英格蘭與父親一起工作。"},{"en":"Work with means do a job or project together with another person.","zh":"work with 指與另一個人一起做工作或項目。"},{"en":"A student may work with a classmate to finish a science project.","zh":"學生可能與同學一起完成科學項目。"},{"en":"Working with an experienced person can help a beginner learn faster.","zh":"與有經驗的人一起工作可以幫助初學者更快學習。"},{"en":"The phrase suggests cooperation, not working alone.","zh":"這個片語暗示合作，而不是獨自工作。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":2},{"front":"tunnel under the River Thames","meaning":"泰晤士河底隧道","examples":[{"en":"Sir Marc was building his famous tunnel under the River Thames.","zh":"馬克爵士正在建造他著名的泰晤士河底隧道。"},{"en":"A tunnel under the River Thames is an underground passage built beneath the Thames River.","zh":"tunnel under the River Thames 指建在泰晤士河下方的地下通道。"},{"en":"Engineers building a tunnel under a river must deal with water pressure and unstable ground.","zh":"在河底建隧道的工程師必須處理水壓和不穩定地層。"},{"en":"If a tunnel under the River Thames succeeds, people and goods can cross more easily.","zh":"如果泰晤士河底隧道成功，人和貨物就能更容易過河。"},{"en":"The phrase describes a difficult engineering project below a major river.","zh":"這個片語描述一項位於主要河流下方的艱難工程。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":2},{"front":"recuperate from injuries","meaning":"從傷患中康復","examples":[{"en":"Isambard was recuperating from injuries near Bristol.","zh":"伊桑巴德正在布里斯托附近從傷患中康復。"},{"en":"Recuperate from injuries means recover after being hurt.","zh":"recuperate from injuries 指受傷後恢復。"},{"en":"An athlete may recuperate from injuries by resting and doing physiotherapy.","zh":"運動員可能透過休息和物理治療從傷患中康復。"},{"en":"If someone does not recuperate from injuries properly, they may return to work too early.","zh":"如果某人沒有好好從傷患中康復，可能太早復工。"},{"en":"The phrase focuses on the healing period after an accident.","zh":"這個片語集中於意外後的康復期。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":2},{"front":"tunnel cave-in","meaning":"隧道塌方","examples":[{"en":"Brunel was injured in a tunnel cave-in.","zh":"布魯內爾在一次隧道塌方中受傷。"},{"en":"A tunnel cave-in is an accident in which part of a tunnel collapses.","zh":"tunnel cave-in 指隧道部分倒塌的事故。"},{"en":"Workers may be trapped if a tunnel cave-in happens during construction.","zh":"如果建造期間發生隧道塌方，工人可能被困。"},{"en":"Strong supports can reduce the risk of a tunnel cave-in.","zh":"堅固支撐可以降低隧道塌方風險。"},{"en":"The phrase suggests a serious and dangerous engineering accident.","zh":"這個片語暗示嚴重而危險的工程事故。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":2},{"front":"become involved with","meaning":"參與；開始涉足","examples":[{"en":"Brunel became involved with his own first major project.","zh":"布魯內爾開始參與自己的第一個重大工程項目。"},{"en":"Become involved with means start taking part in an activity, project, or situation.","zh":"become involved with 指開始參與某項活動、項目或情況。"},{"en":"A student may become involved with a charity after volunteering once.","zh":"學生可能在一次義工活動後開始參與慈善工作。"},{"en":"If an engineer becomes involved with a project early, they can shape the design.","zh":"如果工程師早期已參與項目，就能塑造設計。"},{"en":"The phrase suggests participation and responsibility.","zh":"這個片語暗示參與和責任。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":3},{"front":"major project","meaning":"重大工程項目","examples":[{"en":"The Clifton Suspension Bridge became Brunel’s first major project.","zh":"克利夫頓吊橋成為布魯內爾第一個重大工程項目。"},{"en":"A major project is a large or important piece of work requiring planning and effort.","zh":"major project 是需要規劃和努力的大型或重要工作。"},{"en":"Building a new school is a major project for a small town.","zh":"興建新學校對小鎮而言是一個重大項目。"},{"en":"If a major project is delayed, many workers and users may be affected.","zh":"如果重大項目延誤，許多工人和使用者可能受影響。"},{"en":"The phrase suggests scale, importance, and difficulty.","zh":"這個片語暗示規模、重要性和難度。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":3},{"front":"Clifton Suspension Bridge","meaning":"克利夫頓吊橋","examples":[{"en":"The Clifton Suspension Bridge crosses the Avon Gorge.","zh":"克利夫頓吊橋橫跨埃文峽谷。"},{"en":"The Clifton Suspension Bridge is a famous bridge associated with Brunel’s engineering work.","zh":"克利夫頓吊橋是一座與布魯內爾工程工作有關的著名橋樑。"},{"en":"Tourists may visit the Clifton Suspension Bridge to admire its height and design.","zh":"遊客可能到訪克利夫頓吊橋，欣賞其高度和設計。"},{"en":"Because the bridge spans a deep gorge, its design required careful engineering.","zh":"由於這座橋跨越深峽谷，其設計需要仔細工程計算。"},{"en":"The phrase names a specific historic bridge, not a general bridge type.","zh":"這個片語指一座特定歷史橋樑，而不是一般橋樑類型。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":3},{"front":"Avon Gorge","meaning":"埃文峽谷","examples":[{"en":"The Clifton Suspension Bridge was built over the Avon Gorge.","zh":"克利夫頓吊橋建於埃文峽谷之上。"},{"en":"The Avon Gorge is a deep natural gap cut by the River Avon near Bristol.","zh":"Avon Gorge 是布里斯托附近由埃文河切割形成的深峽谷。"},{"en":"A bridge over the Avon Gorge must be high enough to cross the steep sides safely.","zh":"橫跨埃文峽谷的橋必須足夠高，才能安全跨越陡峭兩側。"},{"en":"If a gorge is deep and wide, engineers face greater design challenges.","zh":"如果峽谷又深又闊，工程師會面對更大設計挑戰。"},{"en":"The phrase names the landscape that made the bridge project difficult.","zh":"這個片語指令橋樑工程變得困難的地貌。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":3},{"front":"the span of","meaning":"……的跨度","examples":[{"en":"The span of Brunel’s bridge was over 700 feet.","zh":"布魯內爾橋樑的跨度超過700英尺。"},{"en":"The span of a bridge is the distance it stretches between supports.","zh":"the span of a bridge 指橋在支撐點之間延伸的距離。"},{"en":"The span of a classroom ceiling must be supported safely by beams.","zh":"課室天花的跨度必須由橫樑安全支撐。"},{"en":"If the span of a bridge is long, engineers must control weight and movement carefully.","zh":"如果橋樑跨度很長，工程師必須小心控制重量和移動。"},{"en":"The phrase is useful when describing structural size.","zh":"這個片語在描述結構大小時很有用。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":3},{"front":"longer than any existing","meaning":"比當時任何現存的……都長","examples":[{"en":"The bridge was longer than any existing bridge when it was designed.","zh":"這座橋在設計時，比當時任何現存橋樑都長。"},{"en":"Longer than any existing means longer than all examples already present at that time.","zh":"longer than any existing 指比當時已存在的所有例子都更長。"},{"en":"The new tunnel was longer than any existing tunnel in the city.","zh":"新隧道比城中任何現存隧道都長。"},{"en":"If a design is longer than any existing structure, engineers must test it carefully.","zh":"如果一個設計比任何現存結構都長，工程師必須仔細測試。"},{"en":"The phrase highlights a record-breaking or unusually ambitious size.","zh":"這個片語強調破紀錄或非常雄心勃勃的尺寸。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":3},{"front":"height above water","meaning":"離水面高度","examples":[{"en":"The height above water was about 245 feet.","zh":"離水面高度約為245英尺。"},{"en":"Height above water means the vertical distance from the water surface to the object above it.","zh":"height above water 指從水面到上方物體的垂直距離。"},{"en":"The height above water of a pier matters when boats pass underneath.","zh":"碼頭離水面高度會影響船隻能否從下面通過。"},{"en":"If a bridge has great height above water, construction and maintenance become harder.","zh":"如果橋樑離水面高度很大，建造和維修會更困難。"},{"en":"The phrase helps describe clearance and engineering difficulty.","zh":"這個片語幫助描述淨空和工程難度。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":3},{"front":"technical challenges","meaning":"技術挑戰","examples":[{"en":"The technical challenges of the bridge project were immense.","zh":"這座橋樑項目的技術挑戰非常巨大。"},{"en":"Technical challenges are difficult practical problems involving design, materials, machines, or safety.","zh":"technical challenges 是涉及設計、材料、機器或安全的困難實際問題。"},{"en":"Installing lifts in an old building can create technical challenges.","zh":"在舊建築安裝升降機可能造成技術挑戰。"},{"en":"If technical challenges are not solved, a project may become unsafe or too expensive.","zh":"如果技術挑戰未能解決，項目可能變得不安全或太昂貴。"},{"en":"The phrase focuses on engineering difficulty rather than public opinion.","zh":"這個片語集中於工程難度，而不是公眾意見。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":3},{"front":"engineering project","meaning":"工程項目","examples":[{"en":"The bridge was a highly ambitious engineering project.","zh":"這座橋是一項極具雄心的工程項目。"},{"en":"An engineering project is planned work that uses technical design to build or improve something.","zh":"engineering project 是使用技術設計去建造或改善某物的計劃工作。"},{"en":"Building a railway station is an engineering project involving structure, transport, and safety.","zh":"興建鐵路站是一項涉及結構、交通和安全的工程項目。"},{"en":"If an engineering project is ambitious, it may require new methods and careful testing.","zh":"如果工程項目雄心勃勃，它可能需要新方法和仔細測試。"},{"en":"The phrase refers to practical construction or technical problem-solving.","zh":"這個片語指實際建造或技術解難。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":3},{"front":"be immense","meaning":"巨大的","examples":[{"en":"The technical challenges were immense.","zh":"技術挑戰是巨大的。"},{"en":"Be immense means be extremely large, great, or difficult.","zh":"be immense 指極大、極多或極困難。"},{"en":"The cost of repairing the hospital after the flood was immense.","zh":"水災後維修醫院的成本非常巨大。"},{"en":"If the pressure on a team is immense, mistakes become more likely.","zh":"如果團隊承受巨大壓力，出錯機會會增加。"},{"en":"The word gives a strong sense of scale or difficulty.","zh":"這個詞帶出強烈的規模或難度感。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":3},{"front":"deal with","meaning":"處理；應付","examples":[{"en":"Brunel dealt with the challenges with thoroughness and ingenuity.","zh":"布魯內爾以周詳和巧思處理這些挑戰。"},{"en":"Deal with means handle, manage, or solve a problem or situation.","zh":"deal with 指處理、管理或解決問題或情況。"},{"en":"A teacher must deal with late homework fairly and clearly.","zh":"老師必須公平清楚地處理遲交功課。"},{"en":"If engineers deal with risks early, the project becomes safer.","zh":"如果工程師及早處理風險，項目會更安全。"},{"en":"The phrase suggests active handling, not ignoring the problem.","zh":"這個片語暗示主動應對，而不是忽視問題。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":4},{"front":"usual thoroughness","meaning":"一貫的周詳","examples":[{"en":"Brunel dealt with the project with his usual thoroughness.","zh":"布魯內爾以他一貫的周詳處理該項目。"},{"en":"Usual thoroughness means the careful and complete way someone normally works.","zh":"usual thoroughness 指某人平常做事時仔細而全面的方式。"},{"en":"A careful accountant checks every receipt with her usual thoroughness.","zh":"一位細心會計師會以她一貫的周詳檢查每張收據。"},{"en":"Usual thoroughness helps prevent small mistakes from becoming serious problems.","zh":"一貫的周詳有助防止小錯誤變成嚴重問題。"},{"en":"The phrase suggests that careful work is part of someone’s normal character.","zh":"這個片語暗示細心工作是某人正常性格的一部分。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":4},{"front":"ingenuity","meaning":"巧思；創造力","examples":[{"en":"His ingenuity helped him solve difficult engineering problems.","zh":"他的巧思幫助他解決困難工程問題。"},{"en":"Ingenuity is clever practical creativity used to solve problems.","zh":"ingenuity 是用來解決問題的聰明實用創意。"},{"en":"A cook shows ingenuity by making dinner from only a few ingredients.","zh":"廚師只用少量食材做出晚餐，便展現巧思。"},{"en":"Ingenuity matters when money, time, or materials are limited.","zh":"當金錢、時間或材料有限時，巧思很重要。"},{"en":"The word praises smart solutions that are both creative and useful.","zh":"這個詞讚揚既有創意又實用的聰明解決方法。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":4},{"front":"another side of","meaning":"……的另一面","examples":[{"en":"The passage also considers another side of the engineering business.","zh":"文章也考慮工程行業的另一面。"},{"en":"Another side of means a different aspect of a subject that should also be considered.","zh":"another side of 指一個主題中也應考慮的另一個方面。"},{"en":"Exams show knowledge, but another side of education is confidence.","zh":"考試顯示知識，但教育的另一面是信心。"},{"en":"If we discuss tourism, another side of the issue is pressure on local residents.","zh":"如果我們討論旅遊，這個議題的另一面是對本地居民的壓力。"},{"en":"The phrase helps widen discussion beyond the most obvious point.","zh":"這個片語幫助把討論擴展到最明顯重點以外。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":4},{"front":"selling his ideas","meaning":"推銷自己的構想","examples":[{"en":"Brunel was skilled at selling his ideas to committees.","zh":"布魯內爾擅長向委員會推銷自己的構想。"},{"en":"Selling his ideas means persuading others to accept or support his plans.","zh":"selling his ideas 指說服別人接受或支持他的計劃。"},{"en":"A student leader must be good at selling ideas when proposing a new club.","zh":"學生領袖提出新學會時，必須擅長推銷構想。"},{"en":"Even a strong design may fail if the engineer cannot sell the idea clearly.","zh":"即使設計很強，如果工程師不能清楚推銷構想，也可能失敗。"},{"en":"The phrase is about persuasion, not literally selling a product.","zh":"這個片語指說服，而不是字面上出售產品。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":4},{"front":"design competitions","meaning":"設計比賽","examples":[{"en":"Two design competitions were held for the bridge.","zh":"該橋舉行了兩次設計比賽。"},{"en":"Design competitions are contests in which people submit plans and the best design is chosen.","zh":"design competitions 是人們提交方案，然後選出最佳設計的比賽。"},{"en":"A city may hold design competitions for a new park or library.","zh":"城市可能為新公園或圖書館舉行設計比賽。"},{"en":"Design competitions can produce creative choices because many people offer different solutions.","zh":"設計比賽可以產生有創意的選擇，因為許多人提出不同解決方案。"},{"en":"The phrase is common in architecture, engineering, and public projects.","zh":"這個片語常見於建築、工程和公共項目。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":4},{"front":"committee’s expert","meaning":"委員會專家","examples":[{"en":"Thomas Telford was the committee’s expert.","zh":"Thomas Telford 是委員會專家。"},{"en":"A committee’s expert is a specialist who advises a decision-making group.","zh":"committee’s expert 是向決策小組提供建議的專門人士。"},{"en":"A school board may invite a safety expert before approving a new building.","zh":"校董會可能在批准新建築前邀請安全專家。"},{"en":"If the committee’s expert disagrees with a design, approval may become harder.","zh":"如果委員會專家不同意某設計，批准可能變得更困難。"},{"en":"The phrase shows that technical advice is being used in a formal decision.","zh":"這個片語顯示正式決策中使用技術建議。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":4},{"front":"bridge designer","meaning":"橋樑設計師","examples":[{"en":"Thomas Telford was a great bridge designer.","zh":"Thomas Telford 是一位偉大的橋樑設計師。"},{"en":"A bridge designer is a person who plans the structure, shape, and safety of bridges.","zh":"bridge designer 是規劃橋樑結構、形狀和安全的人。"},{"en":"A bridge designer must consider weight, wind, traffic, and materials.","zh":"橋樑設計師必須考慮重量、風力、交通和材料。"},{"en":"If a bridge designer makes a poor calculation, the structure may become unsafe.","zh":"如果橋樑設計師計算錯誤，結構可能變得不安全。"},{"en":"The phrase refers to a specialist within engineering.","zh":"這個片語指工程中的專門人士。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":4},{"front":"present designs","meaning":"提交設計方案","examples":[{"en":"Brunel presented four designs for the bridge.","zh":"布魯內爾提交了四個橋樑設計方案。"},{"en":"Present designs means formally show plans or drawings for consideration.","zh":"present designs 指正式展示方案或圖則以供考慮。"},{"en":"An architect may present designs to a client before construction begins.","zh":"建築師可能在施工前向客戶提交設計方案。"},{"en":"If a team presents designs clearly, decision-makers can compare choices more easily.","zh":"如果團隊清楚提交設計方案，決策者就更容易比較選擇。"},{"en":"The phrase focuses on explaining plans to others.","zh":"這個片語集中於向他人解釋計劃。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":4},{"front":"go beyond technicalities","meaning":"超越技術細節","examples":[{"en":"Brunel went beyond technicalities when presenting his bridge design.","zh":"布魯內爾在展示橋樑設計時超越了技術細節。"},{"en":"Go beyond technicalities means discuss more than small technical details.","zh":"go beyond technicalities 指討論不只限於細小技術細節。"},{"en":"A teacher should go beyond technicalities and explain why a grammar rule matters.","zh":"老師應超越技術細節，解釋文法規則為何重要。"},{"en":"If a proposal goes beyond technicalities, it may persuade people emotionally as well as logically.","zh":"如果提案超越技術細節，它可能同時在情感和邏輯上說服人。"},{"en":"The phrase suggests adding broader meaning, style, or purpose.","zh":"這個片語暗示加入更廣泛意義、風格或目的。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":4},{"front":"include arguments based on","meaning":"包括基於……的論據","examples":[{"en":"He included arguments based on the grace of his tower design.","zh":"他包括了基於其塔樓設計優美的論據。"},{"en":"Include arguments based on means add reasons that depend on a particular feature or idea.","zh":"include arguments based on 指加入依據某特點或想法的理由。"},{"en":"A shop owner may include arguments based on lower prices and better service.","zh":"店主可能包括基於較低價格和更好服務的論據。"},{"en":"If a designer includes arguments based on beauty, the proposal may appeal beyond function.","zh":"如果設計師包括基於美感的論據，提案可能不只在功能上吸引人。"},{"en":"The phrase shows what evidence or reasoning supports a claim.","zh":"這個片語顯示某主張由甚麼證據或推理支持。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":5},{"front":"among other things","meaning":"除其他事項外","examples":[{"en":"Brunel’s arguments were based on, among other things, the grace of his design.","zh":"布魯內爾的論據除其他事項外，是基於其設計的優美。"},{"en":"Among other things means including this point, but not only this point.","zh":"among other things 指包括這一點，但不只包括這一點。"},{"en":"A good school needs, among other things, clear rules and caring teachers.","zh":"好學校除其他事項外，需要清晰規則和關愛學生的老師。"},{"en":"If a report mentions cost among other things, cost is only one of several issues.","zh":"如果報告除其他事項外提到成本，成本只是幾個問題之一。"},{"en":"The phrase lets writers name one example without listing everything.","zh":"這個片語讓作者說出一個例子，而不用列出全部。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":5},{"front":"the grace of","meaning":"……的優美","examples":[{"en":"Brunel emphasised the grace of his tower design.","zh":"布魯內爾強調其塔樓設計的優美。"},{"en":"The grace of something is its elegance, beauty, or pleasing form.","zh":"the grace of something 指某物的優雅、美感或令人愉悅的形態。"},{"en":"Visitors admired the grace of the old library’s curved staircase.","zh":"參觀者欣賞舊圖書館弧形樓梯的優美。"},{"en":"The grace of a design can help people accept a structure in a public space.","zh":"設計的優美可以幫助人們接受公共空間中的結構。"},{"en":"The phrase focuses on beauty and harmony, not only function.","zh":"這個片語集中於美感和和諧，而不只是功能。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":5},{"front":"tower design","meaning":"塔樓設計","examples":[{"en":"The grace of the tower design helped Brunel sell his idea.","zh":"塔樓設計的優美幫助布魯內爾推銷他的構想。"},{"en":"Tower design means the planned shape, structure, and appearance of a tower.","zh":"tower design 指塔樓的計劃形狀、結構和外觀。"},{"en":"A tower design must consider height, wind, weight, and visual style.","zh":"塔樓設計必須考慮高度、風力、重量和視覺風格。"},{"en":"If a tower design looks elegant and safe, public support may increase.","zh":"如果塔樓設計看起來優雅又安全，公眾支持可能增加。"},{"en":"The phrase links engineering structure with appearance.","zh":"這個片語把工程結構與外觀連接起來。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":5},{"front":"only got so far as to","meaning":"只做到……的地步","examples":[{"en":"Brunel only got so far as to put up the end piers in his lifetime.","zh":"布魯內爾在有生之年只做到建起兩端橋墩的地步。"},{"en":"Only got so far as to means reached only a limited stage and did not finish the whole task.","zh":"only got so far as to 指只達到有限階段，未完成整個任務。"},{"en":"I planned to clean the whole flat but only got so far as to wash the dishes.","zh":"我本來打算清潔整個單位，但只做到洗碗的地步。"},{"en":"If funding stops, a project may only get so far as the foundation stage.","zh":"如果資金停止，項目可能只做到地基階段。"},{"en":"The phrase shows incomplete progress.","zh":"這個片語顯示進展未完成。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":5},{"front":"put up the end piers","meaning":"建起兩端橋墩","examples":[{"en":"Brunel put up the end piers before he died.","zh":"布魯內爾去世前建起了兩端橋墩。"},{"en":"Put up the end piers means build the supporting structures at the two ends of a bridge.","zh":"put up the end piers 指建造橋兩端的支撐結構。"},{"en":"Workers must put up the end piers before the main bridge span can be completed.","zh":"工人必須先建起兩端橋墩，才能完成主橋跨。"},{"en":"If the end piers are weak, the whole bridge may be unsafe.","zh":"如果兩端橋墩薄弱，整座橋可能不安全。"},{"en":"The phrase describes an early but important stage of bridge construction.","zh":"這個片語描述橋樑建造中早期但重要的階段。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":5},{"front":"in his lifetime","meaning":"在他有生之年","examples":[{"en":"The bridge was not completed in Brunel’s lifetime.","zh":"這座橋沒有在布魯內爾有生之年完成。"},{"en":"In his lifetime means during the period when he was alive.","zh":"in his lifetime 指在他仍然活着的期間。"},{"en":"An artist may become famous only after her lifetime.","zh":"藝術家可能在她有生之年後才成名。"},{"en":"If a project is not finished in someone’s lifetime, others must continue it later.","zh":"如果項目沒有在某人有生之年完成，其他人日後必須繼續。"},{"en":"The phrase connects achievement with the time a person lived.","zh":"這個片語把成就與一個人的生命時期連接起來。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":5},{"front":"completed in his honour","meaning":"為紀念他而完成","examples":[{"en":"The Clifton Suspension Bridge was completed in his honour.","zh":"克利夫頓吊橋為紀念他而完成。"},{"en":"Completed in his honour means finished as a way to respect or remember him.","zh":"completed in his honour 指為了尊敬或紀念他而完成。"},{"en":"A school garden may be completed in a teacher’s honour after she retires.","zh":"一個學校花園可能在老師退休後為紀念她而完成。"},{"en":"If friends finish a project in someone’s honour, they show respect for that person’s work.","zh":"如果朋友為紀念某人而完成項目，他們就是尊重那人的工作。"},{"en":"The phrase suggests tribute, gratitude, and remembrance.","zh":"這個片語暗示致敬、感謝和紀念。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":5},{"front":"engineering friends","meaning":"工程界朋友","examples":[{"en":"Brunel’s engineering friends completed the bridge in 1864.","zh":"布魯內爾的工程界朋友於1864年完成了這座橋。"},{"en":"Engineering friends are friends or colleagues connected with the engineering profession.","zh":"engineering friends 是與工程專業有關的朋友或同事。"},{"en":"An engineer may ask engineering friends for advice on a difficult design.","zh":"工程師可能向工程界朋友請教困難設計。"},{"en":"If engineering friends continue someone’s project, professional respect becomes practical support.","zh":"如果工程界朋友延續某人的項目，專業尊重就變成實際支持。"},{"en":"The phrase shows friendship within a technical field.","zh":"這個片語顯示技術領域內的友誼。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":5},{"front":"still in use","meaning":"仍在使用","examples":[{"en":"The Clifton Suspension Bridge is still in use.","zh":"克利夫頓吊橋仍在使用。"},{"en":"Still in use means something continues to be used today.","zh":"still in use 指某物至今仍繼續被使用。"},{"en":"Some old school buildings are still in use after careful repairs.","zh":"一些舊校舍經仔細維修後仍在使用。"},{"en":"If a bridge is still in use after many years, its design and maintenance must be strong.","zh":"如果橋樑多年後仍在使用，其設計和維修必須可靠。"},{"en":"The phrase shows lasting usefulness.","zh":"這個片語顯示長久的實用性。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":5},{"front":"Great Western Railway","meaning":"大西部鐵路","examples":[{"en":"Brunel constructed the Great Western Railway.","zh":"布魯內爾建造了大西部鐵路。"},{"en":"The Great Western Railway was a major railway project associated with Brunel.","zh":"Great Western Railway 是一項與布魯內爾有關的主要鐵路工程。"},{"en":"Passengers used the Great Western Railway to travel between important towns and cities.","zh":"乘客使用大西部鐵路往來重要城鎮和城市。"},{"en":"A railway like the Great Western Railway can change trade, commuting, and urban growth.","zh":"像大西部鐵路這樣的鐵路可以改變貿易、通勤和城市增長。"},{"en":"The phrase names a specific historic railway, not railways in general.","zh":"這個片語指一條特定歷史鐵路，而不是一般鐵路。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":6},{"front":"while Brunel was still in","meaning":"當 Brunel 仍在……時","examples":[{"en":"While Brunel was still in Bristol, he became aware of the need for a railway.","zh":"當布魯內爾仍在布里斯托時，他意識到需要一條鐵路。"},{"en":"While Brunel was still in means during the time Brunel remained in a particular place.","zh":"while Brunel was still in 指在布魯內爾仍留在某地期間。"},{"en":"While a student was still in school, she started planning her future career.","zh":"當一名學生仍在學校時，她開始規劃未來事業。"},{"en":"If someone notices a problem while still in a place, they may begin solving it before leaving.","zh":"如果某人仍在某地時注意到問題，可能在離開前已開始解決。"},{"en":"The phrase connects location and timing.","zh":"這個片語把地點和時間連接起來。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":6},{"front":"going slowly","meaning":"進展緩慢","examples":[{"en":"The Avon Bridge project was stopped or going slowly.","zh":"埃文橋項目已停工或進展緩慢。"},{"en":"Going slowly means making little progress or moving forward at a low speed.","zh":"going slowly 指進展很少或以低速度前進。"},{"en":"The road repair project is going slowly because workers found old pipes underground.","zh":"道路維修項目進展緩慢，因為工人在地下發現舊水管。"},{"en":"If a project is going slowly, costs may rise and people may lose patience.","zh":"如果項目進展緩慢，成本可能上升，人們也可能失去耐性。"},{"en":"The phrase suggests delay, not complete failure.","zh":"這個片語暗示延誤，而不是完全失敗。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":6},{"front":"become aware that","meaning":"意識到","examples":[{"en":"Brunel became aware that Bristol needed a railway link to London.","zh":"布魯內爾意識到布里斯托需要通往倫敦的鐵路連接。"},{"en":"Become aware that means realise or come to understand a fact.","zh":"become aware that 指意識到或開始理解某個事實。"},{"en":"A teacher may become aware that several students are afraid to ask questions.","zh":"老師可能意識到幾名學生害怕發問。"},{"en":"Once people become aware that a bridge is unsafe, repairs become urgent.","zh":"一旦人們意識到橋樑不安全，維修就變得緊急。"},{"en":"The phrase focuses on a new understanding.","zh":"這個片語集中於新的理解。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":6},{"front":"civic authorities","meaning":"市政當局","examples":[{"en":"The civic authorities saw the need for a railway link.","zh":"市政當局看見鐵路連接的需要。"},{"en":"Civic authorities are local government officials or bodies responsible for a city or town.","zh":"civic authorities 是負責城市或城鎮的地方政府官員或機構。"},{"en":"Civic authorities may decide where to build roads, markets, and public buildings.","zh":"市政當局可能決定道路、市場和公共建築的位置。"},{"en":"If civic authorities support a transport project, approval may become easier.","zh":"如果市政當局支持交通項目，批准可能變得更容易。"},{"en":"The phrase is formal and refers to local public leadership.","zh":"這個片語較正式，指地方公共領導機構。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":6},{"front":"see the need for","meaning":"看見……的需要","examples":[{"en":"The civic authorities saw the need for a railway link to London.","zh":"市政當局看見通往倫敦的鐵路連接需要。"},{"en":"See the need for means recognise that something is necessary or useful.","zh":"see the need for 指認識到某事是必要或有用的。"},{"en":"Parents may see the need for better school buses after repeated delays.","zh":"多次延誤後，家長可能看見改善校巴的需要。"},{"en":"If a city sees the need for clean water, it may invest in new pipes.","zh":"如果城市看見清潔食水的需要，可能投資新水管。"},{"en":"The phrase shows practical recognition of a problem or opportunity.","zh":"這個片語顯示對問題或機會的實際認識。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":6},{"front":"railway link","meaning":"鐵路連接","examples":[{"en":"Bristol needed a railway link to London.","zh":"布里斯托需要通往倫敦的鐵路連接。"},{"en":"A railway link is a rail connection between two places.","zh":"railway link 是兩地之間的鐵路連接。"},{"en":"A railway link between a town and an airport can reduce travel time.","zh":"城鎮與機場之間的鐵路連接可以減少交通時間。"},{"en":"If a city lacks a railway link, trade and commuting may be harder.","zh":"如果城市缺乏鐵路連接，貿易和通勤可能更困難。"},{"en":"The phrase focuses on transport connection.","zh":"這個片語集中於交通連接。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":6},{"front":"railway location","meaning":"鐵路選址","examples":[{"en":"Railway location was controversial.","zh":"鐵路選址具爭議性。"},{"en":"Railway location means the chosen route or position of a railway line.","zh":"railway location 指鐵路線所選定的路線或位置。"},{"en":"Railway location matters because it affects homes, farms, businesses, and noise.","zh":"鐵路選址很重要，因為它影響住屋、農場、商業和噪音。"},{"en":"If railway location cuts through private land, local opposition may grow.","zh":"如果鐵路選址穿過私人土地，本地反對可能增加。"},{"en":"The phrase refers to where a railway should be built.","zh":"這個片語指鐵路應建在哪裡。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":6},{"front":"be controversial","meaning":"具爭議性","examples":[{"en":"The location of the railway was controversial.","zh":"鐵路的位置具爭議性。"},{"en":"Be controversial means cause disagreement or strong debate.","zh":"be controversial 指引起分歧或強烈辯論。"},{"en":"A plan to close a local hospital can be controversial.","zh":"關閉本地醫院的計劃可能具爭議性。"},{"en":"If a railway route affects wealthy landowners, it may become controversial quickly.","zh":"如果鐵路路線影響富有地主，它可能很快變得具爭議性。"},{"en":"The phrase shows that people do not all agree.","zh":"這個片語顯示人們並非全部同意。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":6},{"front":"private landowners","meaning":"私人地主","examples":[{"en":"Private landowners had to be dealt with before the railway could be built.","zh":"在鐵路能夠建造前，必須處理私人地主問題。"},{"en":"Private landowners are individuals or families who own land, not the government.","zh":"private landowners 是擁有土地的個人或家庭，而不是政府。"},{"en":"Road planners may need permission from private landowners before widening a street.","zh":"道路規劃者在擴闊街道前，可能需要私人地主同意。"},{"en":"If private landowners object, a construction project can be delayed.","zh":"如果私人地主反對，建設項目可能延誤。"},{"en":"The phrase highlights ownership and negotiation.","zh":"這個片語強調擁有權和協商。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":6},{"front":"have to be dealt with","meaning":"必須處理；必須應對","examples":[{"en":"Private landowners and towns had to be dealt with.","zh":"私人地主和城鎮都必須處理。"},{"en":"Have to be dealt with means must be handled, managed, or negotiated with.","zh":"have to be dealt with 指必須處理、管理或協商。"},{"en":"Complaints from residents have to be dealt with before the shop can reopen.","zh":"商店重開前，必須處理居民投訴。"},{"en":"If safety problems have to be dealt with, work may stop temporarily.","zh":"如果安全問題必須處理，工作可能暫時停止。"},{"en":"The phrase shows that something cannot be ignored.","zh":"這個片語顯示某事不能被忽視。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":7},{"front":"the landed gentry","meaning":"鄉紳地主階層","examples":[{"en":"The landed gentry did not want a noisy railway near them.","zh":"鄉紳地主階層不希望嘈吵鐵路靠近他們。"},{"en":"The landed gentry were wealthy landowning upper-class families, especially in rural areas.","zh":"the landed gentry 是富有的地主上層家庭，尤其在鄉郊地區。"},{"en":"The landed gentry often had influence over local politics and land use.","zh":"鄉紳地主階層常對本地政治和土地使用有影響力。"},{"en":"If the landed gentry opposed a railway, engineers had to persuade powerful people.","zh":"如果鄉紳地主階層反對鐵路，工程師就必須說服有權勢的人。"},{"en":"The phrase belongs to social and historical class discussion.","zh":"這個片語屬於社會階級和歷史討論。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":7},{"front":"messy, noisy railway","meaning":"雜亂嘈吵的鐵路","examples":[{"en":"The landed gentry objected to a messy, noisy railway.","zh":"鄉紳地主階層反對雜亂嘈吵的鐵路。"},{"en":"A messy, noisy railway is a railway seen as dirty, disruptive, and loud.","zh":"messy, noisy railway 指被視為骯髒、干擾大而嘈吵的鐵路。"},{"en":"Residents may object to a messy, noisy building site near their homes.","zh":"居民可能反對住家附近雜亂嘈吵的建築工地。"},{"en":"If people fear a railway will be messy and noisy, they may oppose its route.","zh":"如果人們擔心鐵路會雜亂嘈吵，就可能反對其路線。"},{"en":"The phrase reflects the objections of people affected by construction or transport.","zh":"這個片語反映受建設或交通影響者的反對。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":7},{"front":"anywhere near","meaning":"在……附近任何地方","examples":[{"en":"They did not want a railway anywhere near them.","zh":"他們不希望鐵路在他們附近任何地方。"},{"en":"Anywhere near means in any place close to someone or something.","zh":"anywhere near 指在靠近某人或某物的任何地方。"},{"en":"Parents may not want heavy traffic anywhere near a primary school.","zh":"家長可能不希望繁忙交通在小學附近任何地方出現。"},{"en":"If residents do not want noise anywhere near their homes, a project may face objections.","zh":"如果居民不希望噪音在住家附近任何地方出現，項目可能面對反對。"},{"en":"The phrase strongly rejects closeness.","zh":"這個片語強烈拒絕接近。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":7},{"front":"be against","meaning":"反對","examples":[{"en":"The Duke of Wellington was certainly against the railway.","zh":"威靈頓公爵當然反對鐵路。"},{"en":"Be against means oppose or disagree with something.","zh":"be against 指反對或不同意某事。"},{"en":"Some parents are against longer school hours because children need rest.","zh":"有些家長反對延長上課時間，因為孩子需要休息。"},{"en":"If powerful people are against a plan, approval may become harder.","zh":"如果有權勢的人反對一項計劃，批准可能變得更困難。"},{"en":"The phrase clearly shows opposition.","zh":"這個片語清楚顯示反對。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":7},{"front":"show great skill in","meaning":"在……方面表現出高超技巧","examples":[{"en":"Brunel showed great skill in presenting his arguments.","zh":"布魯內爾在提出論據方面表現出高超技巧。"},{"en":"Show great skill in means perform an activity with high ability.","zh":"show great skill in 指在某項活動中表現出高水平能力。"},{"en":"A nurse may show great skill in calming frightened patients.","zh":"護士可能在安撫受驚病人方面表現出高超技巧。"},{"en":"If an engineer shows great skill in explanation, committees may trust the design more.","zh":"如果工程師在解釋方面表現出高超技巧，委員會可能更信任設計。"},{"en":"The phrase praises ability in a specific action.","zh":"這個片語讚揚在特定行動上的能力。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":7},{"front":"present arguments to","meaning":"向……提出論據","examples":[{"en":"Brunel presented his arguments to committees and individuals.","zh":"布魯內爾向委員會和個人提出他的論據。"},{"en":"Present arguments to means explain reasons and evidence to people who must decide.","zh":"present arguments to 指向需要決策的人解釋理由和證據。"},{"en":"A student may present arguments to a teacher when asking for more time.","zh":"學生要求更多時間時，可能向老師提出論據。"},{"en":"If you present arguments clearly to a committee, your proposal has a better chance.","zh":"如果你向委員會清楚提出論據，你的提案有更大機會。"},{"en":"The phrase focuses on persuasion through reasons.","zh":"這個片語集中於透過理由說服人。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":7},{"front":"various committees","meaning":"多個委員會","examples":[{"en":"Brunel had to persuade various committees.","zh":"布魯內爾必須說服多個委員會。"},{"en":"Various committees are several different groups formed to discuss or decide matters.","zh":"various committees 是幾個不同的討論或決策小組。"},{"en":"A school project may need approval from various committees before it starts.","zh":"學校項目開始前，可能需要多個委員會批准。"},{"en":"If various committees disagree, a project can be delayed.","zh":"如果多個委員會意見不合，項目可能延誤。"},{"en":"The phrase suggests more than one formal decision-making group.","zh":"這個片語暗示不只一個正式決策小組。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":7},{"front":"win someone over","meaning":"說服某人；爭取某人支持","examples":[{"en":"Brunel won the committees and individuals over.","zh":"布魯內爾說服了委員會和個人。"},{"en":"Win someone over means persuade someone to support you or change their opinion.","zh":"win someone over 指說服某人支持你或改變意見。"},{"en":"A shy speaker can win the audience over with honest examples.","zh":"害羞的演講者可以用真誠例子爭取聽眾支持。"},{"en":"If residents oppose a plan, clear answers may win them over gradually.","zh":"如果居民反對計劃，清晰回答可能逐漸說服他們。"},{"en":"The phrase suggests persuasion that turns doubt into support.","zh":"這個片語暗示把懷疑轉化為支持的說服。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":7},{"front":"be awarded the contract","meaning":"獲批合約","examples":[{"en":"Brunel was awarded the contract to construct the railway line.","zh":"布魯內爾獲批建造鐵路線的合約。"},{"en":"Be awarded the contract means officially be chosen to do paid work under an agreement.","zh":"be awarded the contract 指正式被選中根據協議做有酬工作。"},{"en":"A building company may be awarded the contract to repair a school.","zh":"建築公司可能獲批維修學校的合約。"},{"en":"If a firm is awarded the contract, it becomes responsible for delivering the project.","zh":"如果公司獲批合約，它就負責交付項目。"},{"en":"The phrase is common in business, construction, and government work.","zh":"這個片語常見於商業、建築和政府工作。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":7},{"front":"construct the railway line","meaning":"建造鐵路線","examples":[{"en":"Brunel constructed the railway line with a broad gauge.","zh":"布魯內爾以寬軌建造鐵路線。"},{"en":"Construct the railway line means build the tracks and related railway structures.","zh":"construct the railway line 指建造鐵軌和相關鐵路結構。"},{"en":"Workers must clear land before they construct a railway line through a town.","zh":"工人穿過城鎮建造鐵路線前，必須先清理土地。"},{"en":"If engineers construct the railway line well, trains can run safely and smoothly.","zh":"如果工程師把鐵路線建造得好，火車就能安全平穩運行。"},{"en":"The phrase describes physical railway building.","zh":"這個片語描述實體鐵路建設。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":8},{"front":"broad gauge","meaning":"寬軌","examples":[{"en":"Brunel built his railway with a broad gauge.","zh":"布魯內爾用寬軌建造他的鐵路。"},{"en":"Broad gauge is a railway track width wider than the standard gauge.","zh":"broad gauge 是比標準軌距更寬的鐵路軌距。"},{"en":"A broad gauge railway can give trains more stability but may not fit other lines.","zh":"寬軌鐵路可以給火車更多穩定性，但可能不適用於其他線路。"},{"en":"If one railway uses broad gauge and another uses standard gauge, trains cannot easily share tracks.","zh":"如果一條鐵路用寬軌，另一條用標準軌距，火車就不容易共用路軌。"},{"en":"The phrase describes the distance between the two rails.","zh":"這個片語描述兩條鐵軌之間的距離。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":8},{"front":"standard gauge","meaning":"標準軌距","examples":[{"en":"The government later required new lines to use standard gauge.","zh":"政府後來規定新線路使用標準軌距。"},{"en":"Standard gauge is the commonly accepted railway track width used as a normal measure.","zh":"standard gauge 是被普遍接受、作為正常標準的鐵路軌距。"},{"en":"Standard gauge helps trains move across different railway networks without changing wheels.","zh":"標準軌距幫助火車無需更換車輪便可跨不同鐵路網絡行駛。"},{"en":"If all new lines use standard gauge, railway systems become easier to connect.","zh":"如果所有新線路都使用標準軌距，鐵路系統就更容易連接。"},{"en":"The phrase refers to an agreed technical standard.","zh":"這個片語指一項約定的技術標準。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":8},{"front":"lines already installed","meaning":"已鋪設的鐵路線","examples":[{"en":"The standard gauge had been used for lines already installed.","zh":"標準軌距已用於已鋪設的鐵路線。"},{"en":"Lines already installed are railway tracks that have already been built and put in place.","zh":"lines already installed 是已經建成並鋪設好的鐵路軌道。"},{"en":"Engineers must check lines already installed before adding new stations.","zh":"工程師在加建新車站前，必須檢查已鋪設的鐵路線。"},{"en":"If new trains do not match lines already installed, costly changes may be needed.","zh":"如果新火車不配合已鋪設的鐵路線，可能需要昂貴改動。"},{"en":"The phrase contrasts existing infrastructure with new construction.","zh":"這個片語把現有基礎設施與新建設作對比。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":8},{"front":"there is no doubt that","meaning":"毫無疑問","examples":[{"en":"There is no doubt that the broad gauge gave superior ride and stability.","zh":"毫無疑問，寬軌提供較佳乘坐感和穩定性。"},{"en":"There is no doubt that means something is certain or very strongly believed.","zh":"there is no doubt that 指某事是確定或非常有把握的。"},{"en":"There is no doubt that regular practice improves pronunciation.","zh":"毫無疑問，定期練習會改善發音。"},{"en":"If the evidence is clear, there is no doubt that safety rules saved lives.","zh":"如果證據清楚，毫無疑問安全規則救了人命。"},{"en":"The phrase strongly introduces a confident statement.","zh":"這個片語強烈引出有信心的陳述。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":8},{"front":"superior ride and stability","meaning":"較佳乘坐感和穩定性","examples":[{"en":"The broad gauge gave superior ride and stability.","zh":"寬軌提供較佳乘坐感和穩定性。"},{"en":"Superior ride and stability means a smoother, safer, and steadier travel experience.","zh":"superior ride and stability 指更順暢、更安全和更穩定的乘坐體驗。"},{"en":"A well-designed bus suspension can give passengers superior ride and stability.","zh":"設計良好的巴士懸掛系統可以給乘客較佳乘坐感和穩定性。"},{"en":"If a train has superior ride and stability, passengers may feel less shaking.","zh":"如果火車有較佳乘坐感和穩定性，乘客可能較少感到搖晃。"},{"en":"The phrase compares comfort and steadiness with a weaker alternative.","zh":"這個片語把舒適度和穩定性與較弱選擇比較。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":8},{"front":"fight an established standard","meaning":"挑戰既定標準","examples":[{"en":"Brunel’s broad gauge was fighting an established standard.","zh":"布魯內爾的寬軌正在挑戰既定標準。"},{"en":"Fight an established standard means compete against a rule or practice already widely accepted.","zh":"fight an established standard 指與已被廣泛接受的規則或做法競爭。"},{"en":"A new phone charger design must fight an established standard if most devices use another type.","zh":"如果大部分裝置使用另一種充電器，新手機充電器設計就必須挑戰既定標準。"},{"en":"If a new idea fights an established standard, even a better design may struggle to spread.","zh":"如果新構想挑戰既定標準，即使設計更好，也可能難以普及。"},{"en":"The phrase shows conflict between innovation and accepted practice.","zh":"這個片語顯示創新與既有做法之間的衝突。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":8},{"front":"be up against","meaning":"面對；與……對抗","examples":[{"en":"Brunel was up against his professional rival Robert Stephenson.","zh":"布魯內爾面對他的專業競爭對手 Robert Stephenson。"},{"en":"Be up against means face opposition, competition, or difficulty.","zh":"be up against 指面對反對、競爭或困難。"},{"en":"A small shop is up against large chains with bigger advertising budgets.","zh":"小店面對擁有更大廣告預算的大型連鎖店。"},{"en":"If a student is up against a difficult exam, careful practice becomes important.","zh":"如果學生面對困難考試，仔細練習就變得重要。"},{"en":"The phrase suggests a challenging opponent or situation.","zh":"這個片語暗示具挑戰性的對手或情況。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":8},{"front":"professional rival","meaning":"專業上的競爭對手","examples":[{"en":"Robert Stephenson was Brunel’s professional rival but personal friend.","zh":"Robert Stephenson 是布魯內爾專業上的競爭對手，但也是私人朋友。"},{"en":"A professional rival is someone who competes with you in the same field of work.","zh":"professional rival 是在同一工作領域與你競爭的人。"},{"en":"Two lawyers may be professional rivals in court but friendly outside work.","zh":"兩位律師在法庭上可能是專業競爭對手，但工作以外是朋友。"},{"en":"Professional rivals can push each other to improve through competition.","zh":"專業競爭對手可以透過競爭推動彼此進步。"},{"en":"The phrase separates work competition from personal feelings.","zh":"這個片語把工作競爭與私人感情分開。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":8},{"front":"personal friend","meaning":"私人朋友","examples":[{"en":"Robert Stephenson was Brunel’s personal friend.","zh":"Robert Stephenson 是布魯內爾的私人朋友。"},{"en":"A personal friend is someone you know and like outside formal work roles.","zh":"personal friend 是你在正式工作角色以外認識並喜歡的人。"},{"en":"A manager may be strict at work but still be a personal friend after office hours.","zh":"經理在工作上可能嚴格，但下班後仍是私人朋友。"},{"en":"If a professional rival is also a personal friend, disagreement can remain respectful.","zh":"如果專業競爭對手也是私人朋友，分歧仍可保持尊重。"},{"en":"The phrase highlights private relationship rather than job position.","zh":"這個片語強調私人關係，而不是職位。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":8},{"front":"after much argument","meaning":"經過大量爭論後","examples":[{"en":"After much argument, the government settled the matter.","zh":"經過大量爭論後，政府解決了此事。"},{"en":"After much argument means following a long period of disagreement or debate.","zh":"after much argument 指經過長時間分歧或辯論後。"},{"en":"After much argument, the family finally chose a holiday destination.","zh":"經過大量爭論後，這個家庭終於選定假期目的地。"},{"en":"If a committee decides after much argument, the issue was probably difficult.","zh":"如果委員會經過大量爭論後作決定，問題很可能很困難。"},{"en":"The phrase shows that agreement did not come easily.","zh":"這個片語顯示共識得來不易。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":9},{"front":"settle the matter","meaning":"解決此事","examples":[{"en":"The government settled the matter in 1846.","zh":"政府於1846年解決此事。"},{"en":"Settle the matter means make a final decision that ends a dispute or uncertainty.","zh":"settle the matter 指作出最終決定，結束爭議或不確定。"},{"en":"A teacher may settle the matter by checking the school rulebook.","zh":"老師可能透過查閱校規來解決此事。"},{"en":"If leaders settle the matter clearly, people know what to do next.","zh":"如果領導清楚解決此事，人們就知道下一步怎樣做。"},{"en":"The phrase suggests closure after disagreement.","zh":"這個片語暗示分歧後有了結論。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":9},{"front":"require all new lines to","meaning":"規定所有新線路要……","examples":[{"en":"The government required all new lines to use standard gauge.","zh":"政府規定所有新線路要使用標準軌距。"},{"en":"Require all new lines to means officially make every new railway line follow a rule.","zh":"require all new lines to 指正式要求每條新鐵路線遵守某規則。"},{"en":"A city may require all new buses to meet cleaner emission standards.","zh":"城市可能規定所有新巴士要符合較清潔排放標準。"},{"en":"If governments require all new lines to use the same gauge, networks become easier to connect.","zh":"如果政府規定所有新線路使用同一軌距，網絡就更容易連接。"},{"en":"The phrase shows a compulsory rule, not a suggestion.","zh":"這個片語顯示強制規則，而不是建議。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":9},{"front":"ready acceptance of","meaning":"對……樂於接受","examples":[{"en":"Brunel’s ready acceptance of new ideas sometimes caused problems.","zh":"布魯內爾對新構想樂於接受，有時造成問題。"},{"en":"Ready acceptance of means quick and willing approval of something.","zh":"ready acceptance of 指迅速而願意地接受某事。"},{"en":"A teacher’s ready acceptance of new teaching apps may make lessons more modern.","zh":"老師對新教學應用程式樂於接受，可能令課堂更現代。"},{"en":"Ready acceptance of every idea can be risky if people do not test it carefully.","zh":"如果人們不仔細測試，對每個想法都樂於接受可能有風險。"},{"en":"The phrase suggests openness, but also possible lack of caution.","zh":"這個片語暗示開放，但也可能缺乏謹慎。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":9},{"front":"new ideas","meaning":"新構想","examples":[{"en":"Brunel was often willing to accept new ideas.","zh":"布魯內爾常願意接受新構想。"},{"en":"New ideas are fresh ways of thinking, designing, or solving problems.","zh":"new ideas 是新的思考、設計或解難方法。"},{"en":"A business needs new ideas when old products stop attracting customers.","zh":"當舊產品不再吸引顧客，企業需要新構想。"},{"en":"New ideas can improve work, but they should be tested before full use.","zh":"新構想可以改善工作，但全面使用前應先測試。"},{"en":"The phrase is positive, but not every new idea is automatically good.","zh":"這個片語是正面的，但不是每個新構想都自動是好的。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":9},{"front":"overpower good engineering judgment","meaning":"壓倒良好的工程判斷","examples":[{"en":"His enthusiasm overpowered good engineering judgment.","zh":"他的熱情壓倒了良好的工程判斷。"},{"en":"Overpower good engineering judgment means emotion or excitement becomes stronger than careful technical thinking.","zh":"overpower good engineering judgment 指情緒或興奮強過仔細技術思考。"},{"en":"A designer may ignore safety tests if enthusiasm overpowers good judgment.","zh":"如果熱情壓倒良好判斷，設計師可能忽視安全測試。"},{"en":"If excitement over a new machine overpowers engineering judgment, mistakes can become expensive.","zh":"如果對新機器的興奮壓倒工程判斷，錯誤可能變得昂貴。"},{"en":"The phrase warns that enthusiasm must be balanced with professional caution.","zh":"這個片語提醒人們熱情必須與專業謹慎平衡。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":9},{"front":"in hindsight","meaning":"事後看來","examples":[{"en":"The atmospheric railway looked like a mistake in hindsight.","zh":"事後看來，大氣壓鐵路像是一個錯誤。"},{"en":"In hindsight means when looking back after events have happened.","zh":"in hindsight 指在事情發生後回頭看。"},{"en":"In hindsight, buying the cheap printer was a mistake because repairs were expensive.","zh":"事後看來，買那部便宜打印機是錯誤，因為維修很昂貴。"},{"en":"People often see risks more clearly in hindsight than at the time.","zh":"人們事後看來往往比當時更清楚看見風險。"},{"en":"The phrase is used when later knowledge changes how we judge the past.","zh":"這個片語用於後來知識改變我們對過去的判斷時。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":9},{"front":"advocate the installation of","meaning":"主張安裝……","examples":[{"en":"Brunel advocated the installation of an atmospheric railway.","zh":"布魯內爾主張安裝大氣壓鐵路。"},{"en":"Advocate the installation of means publicly support putting a system or machine in place.","zh":"advocate the installation of 指公開支持安裝某系統或機器。"},{"en":"Doctors may advocate the installation of better air filters in hospitals.","zh":"醫生可能主張在醫院安裝更好的空氣過濾器。"},{"en":"If experts advocate the installation of safety gates, authorities may approve funding.","zh":"如果專家主張安裝安全閘，當局可能批准資金。"},{"en":"The phrase suggests active support for a practical change.","zh":"這個片語暗示對實際改變的主動支持。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":9},{"front":"atmospheric railway","meaning":"大氣壓鐵路","examples":[{"en":"The atmospheric railway was installed in South Devon.","zh":"大氣壓鐵路安裝於南德文。"},{"en":"An atmospheric railway is a railway system that uses air pressure to move trains.","zh":"atmospheric railway 是利用氣壓推動火車的鐵路系統。"},{"en":"Students may find an atmospheric railway surprising because it does not rely on a normal locomotive.","zh":"學生可能覺得大氣壓鐵路令人驚訝，因為它不依靠普通火車頭。"},{"en":"If the seals fail, an atmospheric railway can become difficult and costly to maintain.","zh":"如果密封失效，大氣壓鐵路可能變得難以維修且成本高昂。"},{"en":"The phrase names an unusual historic transport technology.","zh":"這個片語指一種不尋常的歷史交通技術。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":9},{"front":"have the great attraction of","meaning":"具有……的巨大吸引力","examples":[{"en":"The system had the great attraction of doing away with the locomotive.","zh":"這個系統具有不再需要火車頭的巨大吸引力。"},{"en":"Have the great attraction of means be very appealing because of a particular advantage.","zh":"have the great attraction of 指因某個優點而非常吸引人。"},{"en":"Online classes have the great attraction of saving travel time.","zh":"網上課堂具有節省交通時間的巨大吸引力。"},{"en":"A new transport system may attract support if it has the great attraction of reducing noise.","zh":"如果新交通系統具有減少噪音的巨大吸引力，它可能獲得支持。"},{"en":"The phrase explains why an idea seems desirable.","zh":"這個片語解釋一個想法為何吸引人。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":9},{"front":"do away with","meaning":"廢除；不再需要","examples":[{"en":"The atmospheric railway could do away with the locomotive.","zh":"大氣壓鐵路可以不再需要火車頭。"},{"en":"Do away with means remove something or make it no longer necessary.","zh":"do away with 指移除某物或令它不再必要。"},{"en":"Online forms can do away with some paper documents.","zh":"網上表格可以不再需要某些紙本文件。"},{"en":"If a new system does away with long queues, customers will welcome it.","zh":"如果新系統能消除長隊，顧客會歡迎它。"},{"en":"The phrase suggests eliminating an old need or problem.","zh":"這個片語暗示消除舊需要或問題。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":10},{"front":"locomotive","meaning":"火車頭","examples":[{"en":"The atmospheric railway did not need a locomotive.","zh":"大氣壓鐵路不需要火車頭。"},{"en":"A locomotive is the engine vehicle that pulls or powers a train.","zh":"locomotive 是拉動或推動火車的機車。"},{"en":"Children often notice the locomotive first because it is at the front of the train.","zh":"孩子常先注意到火車頭，因為它在火車最前方。"},{"en":"If a locomotive breaks down, the whole train may stop.","zh":"如果火車頭故障，整列火車可能停下來。"},{"en":"The word is mainly used in railway contexts.","zh":"這個詞主要用於鐵路語境。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":10},{"front":"potentially deal with","meaning":"可能處理到……","examples":[{"en":"The system could potentially deal with steeper gradients.","zh":"這個系統可能處理到較陡的斜坡。"},{"en":"Potentially deal with means possibly handle or solve a problem, though it is not certain.","zh":"potentially deal with 指可能處理或解決某問題，但並不確定。"},{"en":"A new timetable could potentially deal with overcrowding on buses.","zh":"新時間表可能處理到巴士擠迫問題。"},{"en":"If a machine can potentially deal with heavier loads, engineers still need to test it.","zh":"如果機器可能處理更重負載，工程師仍需測試。"},{"en":"The phrase shows possibility, not guaranteed success.","zh":"這個片語顯示可能性，而不是保證成功。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":10},{"front":"steeper gradients","meaning":"較陡的斜坡","examples":[{"en":"The atmospheric railway could potentially handle steeper gradients.","zh":"大氣壓鐵路可能應付較陡的斜坡。"},{"en":"Steeper gradients are sharper slopes that rise or fall more quickly.","zh":"steeper gradients 指升降更急的坡度。"},{"en":"Cyclists find steeper gradients harder because they require more effort.","zh":"騎單車人士覺得較陡的斜坡更困難，因為需要更多力氣。"},{"en":"If a railway has steeper gradients, normal trains may struggle to climb safely.","zh":"如果鐵路有較陡的斜坡，普通火車可能難以安全爬升。"},{"en":"The phrase is common when discussing roads, railways, and hills.","zh":"這個片語常用於討論道路、鐵路和山坡。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":10},{"front":"consist of","meaning":"由……組成","examples":[{"en":"The system consisted of a pipe laid between the rails.","zh":"這個系統由一條鋪設在鐵軌之間的管道組成。"},{"en":"Consist of means be made up of particular parts.","zh":"consist of 指由某些特定部分組成。"},{"en":"A simple lunch may consist of rice, vegetables, and soup.","zh":"一份簡單午餐可能由飯、蔬菜和湯組成。"},{"en":"If a machine consists of many delicate parts, repairs may be difficult.","zh":"如果機器由許多精細零件組成，維修可能困難。"},{"en":"The phrase explains what something contains.","zh":"這個片語解釋某物包含甚麼。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":10},{"front":"15-inch-diameter pipe","meaning":"直徑15吋的管道","examples":[{"en":"The system used a 15-inch-diameter pipe between the rails.","zh":"這個系統在鐵軌之間使用直徑15吋的管道。"},{"en":"A 15-inch-diameter pipe is a pipe whose width across the centre is 15 inches.","zh":"15-inch-diameter pipe 指橫過中心寬度為15吋的管道。"},{"en":"Plumbers choose pipe diameter according to how much water or air must pass through.","zh":"水喉工會根據需要通過多少水或空氣來選擇管道直徑。"},{"en":"If a pipe diameter is too small, pressure and flow may be affected.","zh":"如果管道直徑太小，壓力和流量可能受影響。"},{"en":"The phrase gives a precise technical measurement.","zh":"這個片語給出精確技術量度。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":10},{"front":"laid between the rails","meaning":"鋪設在鐵軌之間","examples":[{"en":"The pipe was laid between the rails.","zh":"管道鋪設在鐵軌之間。"},{"en":"Laid between the rails means placed in the space between the two railway tracks.","zh":"laid between the rails 指放置在兩條鐵路軌道之間的空間。"},{"en":"Cables may be laid between tracks only if they are protected from trains.","zh":"電纜只有在受到火車保護時，才可鋪設在軌道之間。"},{"en":"If a pipe is laid between the rails, maintenance workers must access it carefully.","zh":"如果管道鋪設在鐵軌之間，維修工人必須小心接近。"},{"en":"The phrase describes exact physical placement.","zh":"這個片語描述準確的實體位置。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":10},{"front":"slit along the top","meaning":"頂部有一道裂口","examples":[{"en":"The pipe had a slit along the top.","zh":"管道頂部有一道裂口。"},{"en":"A slit along the top is a long narrow opening running across the upper side of something.","zh":"slit along the top 指沿着某物上方延伸的狹長開口。"},{"en":"A box may have a slit along the top for letters or tickets.","zh":"箱子頂部可能有一道裂口，用來放信或票。"},{"en":"If a pipe has a slit along the top, it must be sealed properly after opening.","zh":"如果管道頂部有一道裂口，打開後必須妥善密封。"},{"en":"The phrase helps readers picture the shape of the mechanism.","zh":"這個片語幫助讀者想像機械形狀。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":10},{"front":"piston fitted inside","meaning":"裝在裏面的活塞","examples":[{"en":"A piston fitted inside the pipe.","zh":"一個活塞裝在管道裏面。"},{"en":"A piston fitted inside means a moving part was placed neatly within a tube or cylinder.","zh":"piston fitted inside 指一個活動部件合適地放在管子或圓筒內。"},{"en":"In a bicycle pump, a piston fitted inside the cylinder pushes air forward.","zh":"在單車泵中，裝在圓筒內的活塞會把空氣推前。"},{"en":"If a piston does not fit inside properly, air pressure may leak.","zh":"如果活塞不能妥善裝在裏面，氣壓可能洩漏。"},{"en":"The phrase describes how one mechanical part sits within another.","zh":"這個片語描述一個機械部件如何位於另一部件內。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":10},{"front":"be connected by","meaning":"由……連接","examples":[{"en":"The piston was connected by an arm to the driving railcar above.","zh":"活塞由一條臂連接到上方的驅動車廂。"},{"en":"Be connected by means be joined through a particular object or part.","zh":"be connected by 指透過某個物件或部件連接起來。"},{"en":"Two buildings may be connected by a covered walkway.","zh":"兩座建築可能由有蓋通道連接。"},{"en":"If machine parts are connected by a weak joint, the system may fail.","zh":"如果機械部件由薄弱接合位連接，系統可能失效。"},{"en":"The phrase explains the linking part between two things.","zh":"這個片語解釋兩物之間的連接部件。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":10},{"front":"driving railcar","meaning":"驅動車廂","examples":[{"en":"The piston was connected to the driving railcar above.","zh":"活塞連接到上方的驅動車廂。"},{"en":"A driving railcar is the rail vehicle that is pulled or pushed forward by the mechanism.","zh":"driving railcar 是由機械裝置拉動或推動前進的鐵路車廂。"},{"en":"In a special railway system, the driving railcar may not need a normal engine.","zh":"在特殊鐵路系統中，驅動車廂可能不需要普通引擎。"},{"en":"If the driving railcar loses connection with the mechanism, it may stop moving.","zh":"如果驅動車廂失去與機械裝置的連接，它可能停止移動。"},{"en":"The phrase identifies the vehicle that actually moves along the track.","zh":"這個片語指出真正沿路軌移動的車輛。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":11},{"front":"pumps stationed","meaning":"設置的泵","examples":[{"en":"Pumps were stationed about two miles apart.","zh":"泵被設置在相隔約兩英里的地方。"},{"en":"Pumps stationed means pumps were placed at fixed positions along a route.","zh":"pumps stationed 指泵被放置在路線上的固定位置。"},{"en":"Fire pumps may be stationed near a building site during risky work.","zh":"在高風險工作期間，消防泵可能設置在建築工地附近。"},{"en":"If pumps are stationed too far apart, pressure may drop between them.","zh":"如果泵設置得太遠，兩者之間的壓力可能下降。"},{"en":"The phrase describes planned placement of equipment.","zh":"這個片語描述設備的計劃性放置。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":11},{"front":"about two miles apart","meaning":"相隔約兩英里","examples":[{"en":"The pumps were stationed about two miles apart.","zh":"這些泵相隔約兩英里設置。"},{"en":"About two miles apart means separated by roughly two miles.","zh":"about two miles apart 指彼此距離大約兩英里。"},{"en":"Two bus stops placed about two miles apart may be too far for older passengers.","zh":"如果兩個巴士站相隔約兩英里，對長者乘客可能太遠。"},{"en":"If pumps are about two miles apart, each one must serve a long section.","zh":"如果泵相隔約兩英里，每個泵都必須服務一段長距離。"},{"en":"The phrase gives an approximate distance, not an exact measurement.","zh":"這個片語給出大約距離，而不是精確量度。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":11},{"front":"evacuate the air from","meaning":"抽走……中的空氣","examples":[{"en":"The pumps evacuated the air from the pipe ahead of the piston.","zh":"泵抽走活塞前方管道中的空氣。"},{"en":"Evacuate the air from means remove air from a space.","zh":"evacuate the air from 指從某空間抽走空氣。"},{"en":"A vacuum machine evacuates the air from a storage bag to save space.","zh":"真空機會抽走收納袋中的空氣來節省空間。"},{"en":"If air is evacuated from a pipe, pressure differences can create movement.","zh":"如果管道中的空氣被抽走，壓力差可以產生 movement。"},{"en":"The phrase is technical and often connected with vacuum systems.","zh":"這個片語較技術性，常與真空系統有關。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":11},{"front":"ahead of","meaning":"在……前方","examples":[{"en":"The pumps removed the air ahead of the piston.","zh":"泵移除活塞前方的空氣。"},{"en":"Ahead of means in front of something or before something in position or time.","zh":"ahead of 指在某物前方，或在位置或時間上早於某事。"},{"en":"A bus ahead of us blocked the road for several minutes.","zh":"我們前方的一輛巴士堵住道路數分鐘。"},{"en":"If air is removed ahead of the piston, pressure behind it can push it forward.","zh":"如果活塞前方的空氣被移除，後方壓力可以把它向前推。"},{"en":"The phrase can describe physical position or future time.","zh":"這個片語可以描述實體位置或未來時間。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":11},{"front":"atmospheric pressure","meaning":"大氣壓力","examples":[{"en":"Atmospheric pressure drove the train forward.","zh":"大氣壓力推動火車向前。"},{"en":"Atmospheric pressure is the force created by the weight of air around us.","zh":"atmospheric pressure 是我們周圍空氣重量造成的力。"},{"en":"A straw works partly because atmospheric pressure helps push liquid upward.","zh":"吸管能運作，部分原因是大氣壓力幫助把液體向上推。"},{"en":"If atmospheric pressure is used in a machine, differences in air pressure can create movement.","zh":"如果機器使用大氣壓力，氣壓差可以產生 movement。"},{"en":"The phrase names an invisible physical force.","zh":"這個片語指一種看不見的物理力量。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":11},{"front":"drive the train","meaning":"推動火車","examples":[{"en":"Atmospheric pressure was used to drive the train.","zh":"大氣壓力被用來推動火車。"},{"en":"Drive the train means make the train move forward.","zh":"drive the train 指使火車向前移動。"},{"en":"An electric motor can drive the train without smoke from coal.","zh":"電動馬達可以推動火車，而不產生煤煙。"},{"en":"If the power system fails, it cannot drive the train safely.","zh":"如果動力系統失效，它便不能安全推動火車。"},{"en":"The phrase refers to the force or system that moves a train.","zh":"這個片語指移動火車的力量或系統。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":11},{"front":"connecting arm","meaning":"連接臂","examples":[{"en":"The connecting arm had to run along the slit.","zh":"連接臂必須沿着裂口運行。"},{"en":"A connecting arm is a mechanical part that links one moving part to another.","zh":"connecting arm 是把一個活動部件連接到另一個活動部件的機械部分。"},{"en":"In a machine, a connecting arm may transfer movement from a motor to a wheel.","zh":"在機器中，連接臂可能把馬達的動作傳到輪子。"},{"en":"If the connecting arm is weak, the mechanism may break under pressure.","zh":"如果連接臂薄弱，機械裝置可能在壓力下斷裂。"},{"en":"The phrase describes a linking piece in a machine.","zh":"這個片語描述機器中的連接部件。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":11},{"front":"run along","meaning":"沿着……運行","examples":[{"en":"The arm had to run along the slit in the pipe.","zh":"連接臂必須沿着管道裂口運行。"},{"en":"Run along means move or extend in the same direction as something.","zh":"run along 指沿着某物的同一方向移動或延伸。"},{"en":"A path may run along the river for several kilometres.","zh":"一條小徑可能沿着河流延伸數公里。"},{"en":"If a cable runs along a wall, it should be fixed safely.","zh":"如果電纜沿着牆壁走線，就應安全固定。"},{"en":"The phrase can describe movement or position beside a line.","zh":"這個片語可以描述沿一條線的移動或位置。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":11},{"front":"be opened through a flap","meaning":"透過活門打開","examples":[{"en":"The slit had to be opened through a flap as the train moved.","zh":"隨着火車移動，裂口必須透過活門打開。"},{"en":"Be opened through a flap means be opened by using a hinged or flexible cover.","zh":"be opened through a flap 指透過鉸接或柔性的蓋門打開。"},{"en":"A pet door is opened through a flap when the animal pushes it.","zh":"當動物推動寵物門時，它就是透過活門打開。"},{"en":"If a sealed slit is opened through a flap, the flap must close again tightly.","zh":"如果密封裂口透過活門打開，活門之後必須再次緊密關閉。"},{"en":"The phrase explains the mechanism that allows temporary opening.","zh":"這個片語解釋容許暫時打開的機制。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":11},{"front":"as the train progressed","meaning":"隨着火車前進","examples":[{"en":"The flap opened as the train progressed.","zh":"隨着火車前進，活門打開。"},{"en":"As the train progressed means while the train moved forward along the track.","zh":"as the train progressed 指當火車沿路軌向前移動時。"},{"en":"As the lift rose, the city view became clearer.","zh":"隨着升降機上升，城市景觀變得更清楚。"},{"en":"If a mechanism opens as the train progresses, timing must be exact.","zh":"如果機械裝置隨着火車前進而打開，時間配合必須準確。"},{"en":"The phrase connects an action with the train’s movement.","zh":"這個片語把一個動作與火車移動連接起來。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":12},{"front":"closed airtight","meaning":"密封關閉","examples":[{"en":"The flap had to close airtight behind the train.","zh":"活門必須在火車後方密封關閉。"},{"en":"Closed airtight means shut so tightly that no air can pass through.","zh":"closed airtight 指關得非常緊，使空氣不能通過。"},{"en":"Food stays fresh longer when a container is closed airtight.","zh":"容器密封關閉時，食物可保持新鮮更久。"},{"en":"If the flap was not closed airtight, the air-pressure system would lose power.","zh":"如果活門沒有密封關閉，氣壓系統會失去動力。"},{"en":"The phrase focuses on complete sealing.","zh":"這個片語集中於完全密封。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":12},{"front":"not up to it","meaning":"不足以勝任；達不到要求","examples":[{"en":"The materials were not up to it.","zh":"材料不足以勝任。"},{"en":"Not up to it means not strong, good, or capable enough for a task.","zh":"not up to it 指對某任務而言不夠強、不夠好或能力不足。"},{"en":"My old laptop is not up to it when I edit large videos.","zh":"當我剪輯大型影片時，我的舊手提電腦達不到要求。"},{"en":"If materials are not up to it, a clever design may still fail.","zh":"如果材料不足以勝任，即使設計巧妙仍可能失敗。"},{"en":"The phrase shows that ability or quality is insufficient.","zh":"這個片語顯示能力或質素不足。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":12},{"front":"troublesome and expensive","meaning":"麻煩而昂貴","examples":[{"en":"The arrangement was troublesome and expensive to keep in repair.","zh":"這套安排維修保養起來麻煩而昂貴。"},{"en":"Troublesome and expensive means causing many problems and costing a lot of money.","zh":"troublesome and expensive 指造成很多問題且花費很多金錢。"},{"en":"An old lift can be troublesome and expensive if it breaks down every month.","zh":"如果舊升降機每月故障，它可能既麻煩又昂貴。"},{"en":"If a system is troublesome and expensive, managers may abandon it.","zh":"如果系統麻煩而昂貴，管理者可能放棄它。"},{"en":"The phrase combines practical difficulty with financial burden.","zh":"這個片語結合實際困難和財政負擔。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":12},{"front":"keep in repair","meaning":"維修保養","examples":[{"en":"The atmospheric system was expensive to keep in repair.","zh":"大氣壓系統維修保養成本高昂。"},{"en":"Keep in repair means maintain something so that it continues to work properly.","zh":"keep in repair 指保養某物，使它繼續正常運作。"},{"en":"Old houses cost money to keep in repair.","zh":"舊房子需要花錢維修保養。"},{"en":"If equipment is hard to keep in repair, breakdowns become frequent.","zh":"如果設備難以維修保養，故障會變得頻繁。"},{"en":"The phrase focuses on ongoing maintenance, not one-time construction.","zh":"這個片語集中於持續維修，而不是一次性建造。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":12},{"front":"after a year of frustration","meaning":"經過一年挫折後","examples":[{"en":"After a year of frustration, the system was abandoned.","zh":"經過一年挫折後，該系統被放棄。"},{"en":"After a year of frustration means following twelve months of repeated difficulty and disappointment.","zh":"after a year of frustration 指經過十二個月反覆困難和失望後。"},{"en":"After a year of frustration, the team changed its software system.","zh":"經過一年挫折後，團隊更換了軟件系統。"},{"en":"If users complain for a year, frustration may force leaders to stop a project.","zh":"如果用戶投訴一年，挫折可能迫使領導者停止項目。"},{"en":"The phrase shows that failure built up over time.","zh":"這個片語顯示失敗是隨時間累積的。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":12},{"front":"be abandoned","meaning":"被放棄","examples":[{"en":"The atmospheric railway was abandoned after a year.","zh":"大氣壓鐵路一年後被放棄。"},{"en":"Be abandoned means be given up or stopped completely.","zh":"be abandoned 指被放棄或完全停止。"},{"en":"A plan to build a shopping centre may be abandoned if costs become too high.","zh":"如果成本變得太高，建造商場的計劃可能被放棄。"},{"en":"If a machine keeps failing, it may be abandoned despite early excitement.","zh":"如果機器不斷失效，即使早期令人興奮，也可能被放棄。"},{"en":"The phrase suggests that people stop trying to continue something.","zh":"這個片語暗示人們停止嘗試繼續某事。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":12},{"front":"admit failure","meaning":"承認失敗","examples":[{"en":"Brunel admitted his failure.","zh":"布魯內爾承認了自己的失敗。"},{"en":"Admit failure means openly accept that something did not succeed.","zh":"admit failure 指公開接受某事沒有成功。"},{"en":"A manager may admit failure when a campaign brings no customers.","zh":"當宣傳活動沒有帶來顧客，經理可能承認失敗。"},{"en":"If people admit failure honestly, they can learn and avoid repeating mistakes.","zh":"如果人們誠實承認失敗，就能學習並避免重複錯誤。"},{"en":"The phrase suggests professional honesty rather than hiding the truth.","zh":"這個片語暗示專業誠實，而不是隱瞞真相。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":12},{"front":"take responsibility","meaning":"承擔責任","examples":[{"en":"Brunel took responsibility for the failed system.","zh":"布魯內爾為失敗的系統承擔責任。"},{"en":"Take responsibility means accept that you are accountable for a decision, action, or result.","zh":"take responsibility 指承認自己要對決定、行動或結果負責。"},{"en":"A team leader should take responsibility when instructions are unclear.","zh":"當指示不清楚，團隊領袖應承擔責任。"},{"en":"If someone takes responsibility after a mistake, trust may be repaired.","zh":"如果某人在犯錯後承擔責任，信任可能得到修復。"},{"en":"The phrase shows maturity and professional integrity.","zh":"這個片語顯示成熟和專業操守。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":12},{"front":"take no fee for","meaning":"不收取……費用","examples":[{"en":"Brunel took no fee for his work on the atmospheric railway.","zh":"布魯內爾沒有為他在大氣壓鐵路上的工作收取費用。"},{"en":"Take no fee for means accept no payment for a piece of work or service.","zh":"take no fee for 指不接受某項工作或服務的付款。"},{"en":"A doctor may take no fee for treating a neighbour in an emergency.","zh":"醫生可能在緊急情況下為鄰居治療而不收費。"},{"en":"If a consultant takes no fee after a failed project, it may show responsibility.","zh":"如果顧問在失敗項目後不收費，可能顯示責任感。"},{"en":"The phrase emphasises refusing payment.","zh":"這個片語強調拒絕收取付款。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":12},{"front":"set a good professional example","meaning":"樹立良好專業榜樣","examples":[{"en":"Brunel set a good professional example by taking responsibility.","zh":"布魯內爾透過承擔責任樹立良好專業榜樣。"},{"en":"Set a good professional example means behave in a way that other workers should follow.","zh":"set a good professional example 指以值得其他工作者效法的方式行事。"},{"en":"A senior nurse sets a good professional example by staying calm during emergencies.","zh":"資深護士在緊急情況下保持冷靜，就是樹立良好專業榜樣。"},{"en":"If leaders admit mistakes, they set a good professional example for the whole team.","zh":"如果領導者承認錯誤，他們會為整個團隊樹立良好專業榜樣。"},{"en":"The phrase connects behaviour with professional standards.","zh":"這個片語把行為與專業標準連接起來。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":13},{"front":"use steam to power ships","meaning":"使用蒸汽推動船隻","examples":[{"en":"Brunel liked the idea of using steam to power ships.","zh":"布魯內爾喜歡使用蒸汽推動船隻的想法。"},{"en":"Use steam to power ships means use steam engines to move vessels through water.","zh":"use steam to power ships 指使用蒸汽引擎推動船隻在水上行駛。"},{"en":"Engineers once used steam to power ships before modern diesel engines became common.","zh":"在現代柴油引擎普及前，工程師曾使用蒸汽推動船隻。"},{"en":"If steam can power ships reliably, ocean travel can become faster than sail alone.","zh":"如果蒸汽能可靠地推動船隻，遠洋旅行可以比單靠帆更快。"},{"en":"The phrase describes a major change in transport technology.","zh":"這個片語描述交通科技的一大轉變。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":13},{"front":"cross the ocean","meaning":"橫渡海洋","examples":[{"en":"Steam-powered ships could cross the ocean.","zh":"蒸汽動力船可以橫渡海洋。"},{"en":"Cross the ocean means travel from one side of an ocean to another.","zh":"cross the ocean 指從海洋的一邊航行到另一邊。"},{"en":"Immigrants once crossed the ocean by ship to begin new lives.","zh":"移民曾乘船橫渡海洋，開始新生活。"},{"en":"If a ship can cross the ocean without stopping often, long-distance travel becomes easier.","zh":"如果船能橫渡海洋而不經常停靠，長距離旅行會更容易。"},{"en":"The phrase suggests a long sea journey.","zh":"這個片語暗示漫長海上旅程。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":13},{"front":"appeal to","meaning":"吸引","examples":[{"en":"The idea of steam-powered ocean travel appealed to Brunel.","zh":"蒸汽動力遠洋旅行的想法吸引了布魯內爾。"},{"en":"Appeal to means attract or interest someone.","zh":"appeal to 指吸引或引起某人興趣。"},{"en":"A quiet café may appeal to students who need a place to study.","zh":"安靜咖啡店可能吸引需要地方溫習的學生。"},{"en":"If a design appeals to both engineers and passengers, it has a better chance of success.","zh":"如果設計同時吸引工程師和乘客，它有更大成功機會。"},{"en":"The phrase describes what someone finds attractive.","zh":"這個片語描述某人覺得有吸引力的事物。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":13},{"front":"company directors","meaning":"公司董事","examples":[{"en":"The GWR company directors complained about the railway’s length.","zh":"大西部鐵路公司的董事抱怨鐵路長度。"},{"en":"Company directors are senior people responsible for major decisions in a company.","zh":"company directors 是負責公司重大決策的高層人士。"},{"en":"Company directors may approve budgets, contracts, and long-term plans.","zh":"公司董事可能批准預算、合約和長遠計劃。"},{"en":"If company directors complain about cost, a project may need a stronger business case.","zh":"如果公司董事抱怨成本，項目可能需要更有力的商業理據。"},{"en":"The phrase refers to business leadership.","zh":"這個片語指商業領導層。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":13},{"front":"complain about","meaning":"抱怨","examples":[{"en":"The directors complained about the great length of the railway.","zh":"董事抱怨鐵路太長。"},{"en":"Complain about means say that something is wrong, annoying, or unsatisfactory.","zh":"complain about 指說某事有問題、令人煩惱或不令人滿意。"},{"en":"Residents may complain about noisy construction work at night.","zh":"居民可能抱怨夜間建築工程嘈吵。"},{"en":"If customers complain about long waiting times, a business should improve service.","zh":"如果顧客抱怨等候時間太長，企業應改善服務。"},{"en":"The phrase shows dissatisfaction.","zh":"這個片語顯示不滿。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":13},{"front":"jokingly suggest","meaning":"開玩笑地建議","examples":[{"en":"Brunel jokingly suggested extending the link to New York.","zh":"布魯內爾開玩笑地建議把連接延伸至紐約。"},{"en":"Jokingly suggest means propose something in a humorous or not fully serious way.","zh":"jokingly suggest 指以幽默或不完全認真的方式提出建議。"},{"en":"When the queue was long, my friend jokingly suggested sleeping at the restaurant.","zh":"排隊很長時，我朋友開玩笑地建議在餐廳睡覺。"},{"en":"A joking suggestion can sometimes lead to a serious idea later.","zh":"開玩笑的建議有時日後會變成認真想法。"},{"en":"The phrase shows that the speaker is not completely serious at first.","zh":"這個片語顯示說話者起初並非完全認真。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":13},{"front":"all the way to","meaning":"一直去到……","examples":[{"en":"Brunel suggested going all the way to New York.","zh":"布魯內爾建議一直去到紐約。"},{"en":"All the way to means the full distance to a far destination.","zh":"all the way to 指完整走到遙遠目的地。"},{"en":"She travelled all the way to the airport just to return a lost passport.","zh":"她一直去到機場，只為歸還遺失護照。"},{"en":"If a railway idea extends all the way to another continent, it becomes extremely ambitious.","zh":"如果鐵路構想一直延伸到另一個大陸，它就變得極具雄心。"},{"en":"The phrase emphasises distance and completeness.","zh":"這個片語強調距離和完整性。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":13},{"front":"call the link","meaning":"將這條連接稱為……","examples":[{"en":"Brunel suggested calling the link the Great Western.","zh":"布魯內爾建議將這條連接稱為 Great Western。"},{"en":"Call the link means give a name to the transport connection or service.","zh":"call the link 指為交通連接或服務命名。"},{"en":"A city may call the new bus route the Green Line.","zh":"城市可能把新巴士路線稱為綠線。"},{"en":"If people call the link by a memorable name, it may be easier to promote.","zh":"如果人們把連接稱為一個易記名稱，它可能更容易宣傳。"},{"en":"The phrase focuses on naming a connection.","zh":"這個片語集中於為連接命名。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":13},{"front":"first steamship to engage in","meaning":"首艘從事……的蒸汽船","examples":[{"en":"The Great Western was the first steamship to engage in transatlantic service.","zh":"Great Western 是首艘從事跨大西洋航線服務的蒸汽船。"},{"en":"First steamship to engage in means the earliest steam-powered ship to take part in a particular service.","zh":"first steamship to engage in 指最早參與某項服務的蒸汽動力船。"},{"en":"A ferry may be the first electric boat to engage in regular harbour service.","zh":"一艘渡輪可能是首艘從事定期港口服務的電動船。"},{"en":"If a ship is the first of its kind to engage in a route, it sets an example for others.","zh":"如果一艘船是同類中首艘從事某航線的，它就為其他船樹立例子。"},{"en":"The phrase highlights a pioneering role.","zh":"這個片語強調開創角色。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":13},{"front":"transatlantic service","meaning":"跨大西洋航線服務","examples":[{"en":"The Great Western engaged in transatlantic service.","zh":"Great Western 從事跨大西洋航線服務。"},{"en":"Transatlantic service is regular transport or communication across the Atlantic Ocean.","zh":"transatlantic service 是跨越大西洋的定期交通或通訊服務。"},{"en":"Airlines now provide transatlantic service between Europe and North America.","zh":"航空公司現在提供歐洲與北美之間的跨大西洋服務。"},{"en":"If a ship offers transatlantic service, it must be reliable over long ocean distances.","zh":"如果船隻提供跨大西洋服務，它必須能在長距離海洋航行中保持可靠。"},{"en":"The phrase connects two sides of the Atlantic.","zh":"這個片語連接大西洋兩岸。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":14},{"front":"form a company","meaning":"成立公司","examples":[{"en":"Brunel formed the Great Western Steamship Company.","zh":"布魯內爾成立了 Great Western Steamship Company。"},{"en":"Form a company means create or establish a business organisation.","zh":"form a company 指創立或建立一個商業組織。"},{"en":"Two friends may form a company to sell online courses.","zh":"兩位朋友可能成立公司銷售網上課程。"},{"en":"If engineers form a company, they can raise money and manage projects officially.","zh":"如果工程師成立公司，他們可以正式籌集資金和管理項目。"},{"en":"The phrase describes the beginning of a business structure.","zh":"這個片語描述商業組織的開始。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":14},{"front":"construction started on","meaning":"……的建造開始","examples":[{"en":"Construction started on the ship in Bristol in 1836.","zh":"這艘船於1836年在布里斯托開始建造。"},{"en":"Construction started on means building work began on a particular project.","zh":"construction started on 指某項目的建造工程開始。"},{"en":"Construction started on the new hospital after the budget was approved.","zh":"新醫院在預算獲批後開始建造。"},{"en":"Once construction starts on a ship, delays can become expensive.","zh":"一旦船隻建造開始，延誤可能變得昂貴。"},{"en":"The phrase marks the beginning of physical building work.","zh":"這個片語標誌實體建設工作的開始。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":14},{"front":"built of wood","meaning":"由木材建成","examples":[{"en":"The Great Western was built of wood.","zh":"Great Western 由木材建成。"},{"en":"Built of wood means made mainly from wooden materials.","zh":"built of wood 指主要由木材製成。"},{"en":"An old cottage built of wood may need protection from damp and fire.","zh":"由木材建成的舊小屋可能需要防潮和防火保護。"},{"en":"If a ship is built of wood, it may differ greatly from later iron ships.","zh":"如果船隻由木材建成，它可能與後來的鐵船大不相同。"},{"en":"The phrase tells us the main construction material.","zh":"這個片語告訴我們主要建造材料。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":14},{"front":"be launched","meaning":"下水","examples":[{"en":"The Great Western was launched in 1837.","zh":"Great Western 於1837年下水。"},{"en":"Be launched means a ship is put into the water for the first time.","zh":"be launched 指船隻首次被放入水中。"},{"en":"A new ferry may be launched after years of design and construction.","zh":"新渡輪可能經多年設計和建造後下水。"},{"en":"If a ship is launched successfully, testing and service can begin.","zh":"如果船隻成功下水，測試和服務就可以開始。"},{"en":"The phrase can also mean begin a product, but here it refers to a ship.","zh":"這個片語也可指推出產品，但這裡指船下水。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":14},{"front":"powered by sail and paddlewheels","meaning":"由帆和明輪推動","examples":[{"en":"The Great Western was powered by sail and paddlewheels.","zh":"Great Western 由帆和明輪推動。"},{"en":"Powered by sail and paddlewheels means moved by both wind-filled sails and rotating side wheels.","zh":"powered by sail and paddlewheels 指由鼓風的帆和旋轉側輪共同推動。"},{"en":"A hybrid transport system uses more than one source of power.","zh":"混合交通系統使用不止一種動力來源。"},{"en":"If a ship is powered by both sail and paddlewheels, it can use wind and steam power.","zh":"如果船隻由帆和明輪推動，它可使用風力和蒸汽動力。"},{"en":"The phrase describes a combined method of propulsion.","zh":"這個片語描述混合推進方式。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":14},{"front":"first trip to","meaning":"前往……的首次航程","examples":[{"en":"The first trip to New York took just 15 days.","zh":"前往紐約的首次航程只用了15天。"},{"en":"First trip to means the first journey made to a particular destination.","zh":"first trip to 指首次前往某目的地的旅程。"},{"en":"My first trip to London made me understand the transport system better.","zh":"我第一次去倫敦的旅程令我更了解交通系統。"},{"en":"If a ship’s first trip to a city is fast, people may trust the service.","zh":"如果船隻前往某城市的首次航程很快，人們可能信任該服務。"},{"en":"The phrase connects a journey with its first destination.","zh":"這個片語把旅程與其首次目的地連接起來。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":14},{"front":"a one-way trip","meaning":"單程旅程","examples":[{"en":"A one-way trip under sail would take more than a month.","zh":"以帆船航行的單程旅程會用超過一個月。"},{"en":"A one-way trip is a journey to a place without counting the return journey.","zh":"a one-way trip 指前往某地的旅程，不計回程。"},{"en":"A one-way trip to the airport takes about forty minutes by bus.","zh":"乘巴士前往機場的單程旅程約需四十分鐘。"},{"en":"If a one-way trip takes a month, regular travel becomes slow and costly.","zh":"如果單程旅程要一個月，定期旅行會變得緩慢而昂貴。"},{"en":"The phrase focuses on travel in one direction only.","zh":"這個片語集中於單一方向的旅程。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":14},{"front":"under sail","meaning":"以帆船航行","examples":[{"en":"A trip under sail would take more than a month.","zh":"以帆船航行的旅程會用超過一個月。"},{"en":"Under sail means travelling by using sails and wind power.","zh":"under sail 指使用帆和風力航行。"},{"en":"A traditional boat under sail moves quietly compared with a motorboat.","zh":"以帆航行的傳統船相比摩托艇移動得較安靜。"},{"en":"If a ship travels under sail, bad winds can delay the journey.","zh":"如果船以帆航行，逆風可能延誤旅程。"},{"en":"The phrase contrasts sailing power with engine power.","zh":"這個片語把帆力與引擎動力作對比。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":14},{"front":"a great success","meaning":"巨大成功","examples":[{"en":"The Great Western was a great success.","zh":"Great Western 是一項巨大成功。"},{"en":"A great success is something that works very well or achieves impressive results.","zh":"a great success 指運作非常好或取得令人印象深刻成果的事物。"},{"en":"The school fair was a great success because many families attended and raised funds.","zh":"學校嘉年華因很多家庭出席並籌得款項而大獲成功。"},{"en":"If a ship saves time and attracts passengers, it may be called a great success.","zh":"如果船隻節省時間並吸引乘客，它可能被稱為巨大成功。"},{"en":"The phrase expresses strong approval of an outcome.","zh":"這個片語表達對結果的高度肯定。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":14},{"front":"make crossings to","meaning":"橫渡到……","examples":[{"en":"The Great Western made 74 crossings to New York.","zh":"Great Western 橫渡到紐約74次。"},{"en":"Make crossings to means travel across a body of water to a destination.","zh":"make crossings to 指跨越水域前往某目的地。"},{"en":"Ferries make crossings to nearby islands every morning.","zh":"渡輪每天早上橫渡到附近島嶼。"},{"en":"If a ship makes many crossings to one city, the route is probably important.","zh":"如果船隻多次橫渡到某城市，該航線可能很重要。"},{"en":"The phrase is commonly used for sea or river journeys.","zh":"這個片語常用於海上或河上旅程。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":15},{"front":"get to work on","meaning":"開始着手做……","examples":[{"en":"Brunel immediately got to work on an even bigger ship.","zh":"布魯內爾立即開始着手建造一艘更大的船。"},{"en":"Get to work on means start working on a task or project.","zh":"get to work on 指開始處理某項任務或項目。"},{"en":"After breakfast, the students got to work on their group presentation.","zh":"早餐後，學生開始着手做小組匯報。"},{"en":"If an engineer gets to work on a new design quickly, progress may begin sooner.","zh":"如果工程師迅速開始着手新設計，進展可能更早開始。"},{"en":"The phrase suggests active beginning.","zh":"這個片語暗示主動開始。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":15},{"front":"made of iron","meaning":"由鐵製成","examples":[{"en":"The Great Britain was made of iron.","zh":"Great Britain 由鐵製成。"},{"en":"Made of iron means built mainly from iron rather than wood or another material.","zh":"made of iron 指主要由鐵而不是木或其他材料建成。"},{"en":"An old gate made of iron may be heavy but strong.","zh":"由鐵製成的舊閘可能很重但堅固。"},{"en":"If a ship is made of iron, it can be stronger than a wooden ship of similar size.","zh":"如果船隻由鐵製成，它可以比相似大小的木船更堅固。"},{"en":"The phrase identifies the main material.","zh":"這個片語指出主要材料。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":15},{"front":"initial design","meaning":"最初設計","examples":[{"en":"The initial design was for the ship to be driven by paddlewheels.","zh":"最初設計是讓船由明輪推動。"},{"en":"Initial design means the first plan before later changes are made.","zh":"initial design 指作出後來修改前的第一個方案。"},{"en":"The initial design of a classroom may change after teachers suggest more storage.","zh":"課室的最初設計可能在老師建議增加儲物空間後改變。"},{"en":"If new technology appears, an initial design may be replaced.","zh":"如果新科技出現，最初設計可能被取代。"},{"en":"The phrase describes the starting version of a plan.","zh":"這個片語描述計劃的起始版本。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":15},{"front":"be driven by","meaning":"由……推動","examples":[{"en":"The ship was initially designed to be driven by paddlewheels.","zh":"這艘船最初設計為由明輪推動。"},{"en":"Be driven by means be powered or moved by a particular force or mechanism.","zh":"be driven by 指由某種力量或機械裝置提供動力或移動。"},{"en":"An electric bus is driven by batteries and motors.","zh":"電動巴士由電池和馬達推動。"},{"en":"If a machine is driven by steam, it needs heat and water to work.","zh":"如果機器由蒸汽推動，它需要熱和水才能運作。"},{"en":"The phrase explains what provides movement or motivation.","zh":"這個片語解釋甚麼提供 movement 或動力。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":15},{"front":"propeller-driven ships","meaning":"螺旋槳推動的船隻","examples":[{"en":"Brunel saw one of the first propeller-driven ships in Britain.","zh":"布魯內爾在英國看見最早期的螺旋槳推動船隻之一。"},{"en":"Propeller-driven ships are ships moved by rotating propellers rather than paddles or sails alone.","zh":"propeller-driven ships 是由旋轉螺旋槳推動，而不是只靠明輪或帆的船隻。"},{"en":"Modern boats are often propeller-driven because propellers work efficiently underwater.","zh":"現代船隻常由螺旋槳推動，因為螺旋槳在水下效率高。"},{"en":"If propeller-driven ships perform better, designers may abandon older propulsion methods.","zh":"如果螺旋槳推動船隻表現更好，設計師可能放棄舊推進方法。"},{"en":"The phrase describes a ship’s method of movement.","zh":"這個片語描述船隻的推動方式。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":15},{"front":"abandon plans for","meaning":"放棄……的計劃","examples":[{"en":"Brunel abandoned his plans for paddlewheel propulsion.","zh":"布魯內爾放棄了明輪推進的計劃。"},{"en":"Abandon plans for means give up a planned idea or method.","zh":"abandon plans for 指放棄某個已計劃的想法或方法。"},{"en":"A school may abandon plans for a trip if the weather becomes dangerous.","zh":"如果天氣變得危險，學校可能放棄旅行計劃。"},{"en":"If a better design appears, engineers may abandon plans for the older system.","zh":"如果更好的設計出現，工程師可能放棄舊系統的計劃。"},{"en":"The phrase shows a clear decision to stop following one plan.","zh":"這個片語顯示明確決定不再跟隨某計劃。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":15},{"front":"paddlewheel propulsion","meaning":"明輪推進","examples":[{"en":"Brunel replaced paddlewheel propulsion with a screw-driven system.","zh":"布魯內爾用螺旋槳推動系統取代明輪推進。"},{"en":"Paddlewheel propulsion is a method of moving a ship using large rotating wheels with paddles.","zh":"paddlewheel propulsion 是用大型帶槳旋轉輪推動船隻的方法。"},{"en":"Old riverboats often used paddlewheel propulsion in shallow waters.","zh":"舊河船常在淺水中使用明輪推進。"},{"en":"If paddlewheel propulsion is less efficient, designers may choose propellers instead.","zh":"如果明輪推進效率較低，設計師可能改用螺旋槳。"},{"en":"The phrase describes an older ship-driving method.","zh":"這個片語描述一種較舊的船隻推動方法。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":15},{"front":"screw-driven iron ship","meaning":"螺旋槳推動的鐵船","examples":[{"en":"The Great Britain was the first screw-driven iron ship to cross the Atlantic.","zh":"Great Britain 是首艘橫渡大西洋的螺旋槳推動鐵船。"},{"en":"A screw-driven iron ship is an iron ship moved by a screw propeller.","zh":"screw-driven iron ship 是由螺旋槳推動的鐵製船隻。"},{"en":"A screw-driven ship can be more efficient than one using side paddlewheels.","zh":"螺旋槳推動的船可能比使用側明輪的船更有效率。"},{"en":"If an iron ship is screw-driven, its design combines stronger material with newer propulsion.","zh":"如果鐵船由螺旋槳推動，其設計就結合了更堅固材料和更新推進方式。"},{"en":"The phrase marks an important step in ship technology.","zh":"這個片語標誌船隻技術的重要一步。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":15},{"front":"cross the Atlantic","meaning":"橫渡大西洋","examples":[{"en":"The Great Britain crossed the Atlantic.","zh":"Great Britain 橫渡了大西洋。"},{"en":"Cross the Atlantic means travel across the Atlantic Ocean.","zh":"cross the Atlantic 指橫跨大西洋航行。"},{"en":"Many migrants crossed the Atlantic by ship in the nineteenth century.","zh":"十九世紀許多移民乘船橫渡大西洋。"},{"en":"If a ship can cross the Atlantic quickly, it can change passenger travel.","zh":"如果船隻能快速橫渡大西洋，它可以改變客運旅行。"},{"en":"The phrase suggests a long journey between Europe and the Americas.","zh":"這個片語暗示歐洲與美洲之間的長途旅程。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":15},{"front":"run aground","meaning":"擱淺","examples":[{"en":"The Great Britain ran aground early in its career.","zh":"Great Britain 在服役初期擱淺。"},{"en":"Run aground means a ship becomes stuck on land, sand, or rocks in shallow water.","zh":"run aground 指船隻在淺水中卡在陸地、沙地或岩石上。"},{"en":"A fishing boat may run aground if the captain misjudges the tide.","zh":"如果船長誤判潮汐，漁船可能擱淺。"},{"en":"If a ship runs aground, repairs and rescue can be costly.","zh":"如果船隻擱淺，維修和救援可能很昂貴。"},{"en":"The phrase describes a serious navigation accident.","zh":"這個片語描述嚴重航行事故。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":16},{"front":"early in its career","meaning":"在服役初期","examples":[{"en":"The ship ran aground early in its career.","zh":"這艘船在服役初期擱淺。"},{"en":"Early in its career means near the beginning of its working life or period of service.","zh":"early in its career 指在其工作生命或服役期剛開始時。"},{"en":"A new teacher may face difficulties early in her career.","zh":"新老師可能在職業生涯初期面對困難。"},{"en":"If a ship has problems early in its career, owners may worry about its future.","zh":"如果船在服役初期出問題，船主可能擔心其未來。"},{"en":"The phrase treats a ship or object almost like a working person.","zh":"這個片語把船或物件幾乎當作工作中的人來描述。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":16},{"front":"be repaired","meaning":"被修復","examples":[{"en":"The Great Britain was repaired after running aground.","zh":"Great Britain 擱淺後被修復。"},{"en":"Be repaired means be fixed after damage or failure.","zh":"be repaired 指在受損或故障後被修好。"},{"en":"A school roof must be repaired before students return after a storm.","zh":"風暴後，校舍屋頂必須在學生回校前被修復。"},{"en":"If a ship is repaired well, it may continue working for many years.","zh":"如果船隻修復得好，它可能繼續運作多年。"},{"en":"The phrase focuses on restoring function.","zh":"這個片語集中於恢復功能。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":16},{"front":"sail for years to","meaning":"多年航行至……","examples":[{"en":"The ship sailed for years to Australia and other parts of the world.","zh":"這艘船多年航行至澳洲和世界其他地方。"},{"en":"Sail for years to means continue travelling by sea to certain places over many years.","zh":"sail for years to 指多年來持續航行前往某些地方。"},{"en":"A cargo ship may sail for years to ports across Asia.","zh":"貨船可能多年航行至亞洲各港口。"},{"en":"If a vessel sails for years to distant regions, it proves its long-term usefulness.","zh":"如果船隻多年航行至遙遠地區，就證明其長期實用性。"},{"en":"The phrase describes repeated service over a long period.","zh":"這個片語描述長期反覆服務。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":16},{"front":"set the standard for","meaning":"為……樹立標準","examples":[{"en":"The Great Britain set the standard for ocean travel.","zh":"Great Britain 為遠洋航行樹立標準。"},{"en":"Set the standard for means become the model that others try to match.","zh":"set the standard for 指成為其他人試圖達到的典範。"},{"en":"A well-run school can set the standard for student support.","zh":"管理良好的學校可以為學生支援樹立標準。"},{"en":"If a product sets the standard for quality, competitors must improve.","zh":"如果產品為品質樹立標準，競爭者就必須改進。"},{"en":"The phrase suggests leadership and influence.","zh":"這個片語暗示領先和影響力。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":16},{"front":"ocean travel","meaning":"遠洋航行","examples":[{"en":"The Great Britain set the standard for ocean travel.","zh":"Great Britain 為遠洋航行樹立標準。"},{"en":"Ocean travel means journeys across seas or oceans, especially over long distances.","zh":"ocean travel 指跨海或跨洋旅程，尤其是長距離旅程。"},{"en":"Before air travel, ocean travel was the main way to cross continents.","zh":"在航空旅行以前，遠洋航行是跨洲的主要方式。"},{"en":"If ocean travel becomes faster and safer, trade and migration can increase.","zh":"如果遠洋航行變得更快更安全，貿易和移民可以增加。"},{"en":"The phrase focuses on long-distance sea transport.","zh":"這個片語集中於長距離海上交通。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":16},{"front":"in the early 1970s","meaning":"在二十世紀七十年代初","examples":[{"en":"The old ship was rescued in the early 1970s.","zh":"這艘舊船在二十世紀七十年代初被救回。"},{"en":"In the early 1970s means during the first years of the 1970s.","zh":"in the early 1970s 指在1970年代最初幾年。"},{"en":"In the early 1970s, many families still used film cameras for holidays.","zh":"在二十世紀七十年代初，許多家庭仍用菲林相機拍旅行照片。"},{"en":"If a ship was rescued in the early 1970s, it survived long after its original service.","zh":"如果船在二十世紀七十年代初被救回，它已在原本服役期後存活很久。"},{"en":"The phrase gives an approximate historical time.","zh":"這個片語給出大約歷史時間。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":16},{"front":"be rescued from","meaning":"從……被救回","examples":[{"en":"The Great Britain was rescued from the Falklands.","zh":"Great Britain 從福克蘭群島被救回。"},{"en":"Be rescued from means be saved or brought back from a dangerous, damaged, or abandoned place.","zh":"be rescued from 指從危險、受損或被遺棄的地方被救出或帶回。"},{"en":"A dog may be rescued from a flooded house.","zh":"一隻狗可能從水浸房屋中被救出。"},{"en":"If an old ship is rescued from a remote island, restoration becomes possible.","zh":"如果舊船從偏遠島嶼被救回，修復就變得可能。"},{"en":"The phrase suggests saving something from loss.","zh":"這個片語暗示把某物從消失中拯救出來。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":16},{"front":"under restoration","meaning":"正在修復中","examples":[{"en":"The Great Britain is now under restoration in Bristol.","zh":"Great Britain 現在正在布里斯托修復中。"},{"en":"Under restoration means being repaired and returned to an earlier or better condition.","zh":"under restoration 指正在被修理，並恢復到較早或較好狀態。"},{"en":"An old theatre under restoration may be closed to visitors for months.","zh":"正在修復中的舊劇院可能對訪客關閉數月。"},{"en":"If a historic ship is under restoration, experts must protect original materials carefully.","zh":"如果歷史船隻正在修復中，專家必須小心保護原有材料。"},{"en":"The phrase describes an ongoing repair and preservation process.","zh":"這個片語描述持續中的修理和保育過程。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":16},{"front":"conventional wisdom","meaning":"傳統看法","examples":[{"en":"Conventional wisdom said steamships could not carry enough coal.","zh":"傳統看法認為蒸汽船不能攜帶足夠煤炭。"},{"en":"Conventional wisdom is what most people generally believe to be true.","zh":"conventional wisdom 是大多數人普遍認為正確的看法。"},{"en":"Conventional wisdom says children learn better when they sleep enough.","zh":"傳統看法認為孩子睡眠足夠時學得更好。"},{"en":"If an inventor challenges conventional wisdom, people may doubt the idea at first.","zh":"如果發明家挑戰傳統看法，人們起初可能懷疑該想法。"},{"en":"The phrase can suggest accepted belief, not necessarily correct belief.","zh":"這個片語可以指被接受的看法，但不一定是正確看法。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":16},{"front":"in Brunel’s day","meaning":"在 Brunel 的時代","examples":[{"en":"In Brunel’s day, many people doubted long steamship voyages.","zh":"在布魯內爾的時代，許多人懷疑長途蒸汽船航行。"},{"en":"In Brunel’s day means during the time when Brunel lived and worked.","zh":"in Brunel’s day 指在布魯內爾生活和工作的時代。"},{"en":"In my grandparents’ day, many children walked to school every morning.","zh":"在我祖父母的時代，許多孩子每天早上步行上學。"},{"en":"If something was impossible in Brunel’s day, later technology may have changed that.","zh":"如果某事在布魯內爾的時代看似不可能，後來科技可能已改變這點。"},{"en":"The phrase places an idea in its historical period.","zh":"這個片語把一個想法放在其歷史時期中。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":17},{"front":"carry enough coal","meaning":"攜帶足夠煤炭","examples":[{"en":"Steamships were thought unable to carry enough coal for long voyages.","zh":"人們認為蒸汽船無法為長途航行攜帶足夠煤炭。"},{"en":"Carry enough coal means have sufficient coal on board to power the ship for the journey.","zh":"carry enough coal 指船上有足夠煤炭為旅程提供動力。"},{"en":"A steam train must carry enough coal if it is travelling far from supply stations.","zh":"如果蒸汽火車要遠離補給站行駛，就必須攜帶足夠煤炭。"},{"en":"If a ship cannot carry enough coal, it must stop often or risk losing power.","zh":"如果船不能攜帶足夠煤炭，就必須經常停靠或冒失去動力的風險。"},{"en":"The phrase connects fuel capacity with travel distance.","zh":"這個片語把燃料容量與旅行距離連接起來。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":17},{"front":"long ocean voyages","meaning":"長途遠洋航行","examples":[{"en":"Steamships were thought unsuitable for long ocean voyages.","zh":"人們認為蒸汽船不適合長途遠洋航行。"},{"en":"Long ocean voyages are journeys across the sea that take a great distance and time.","zh":"long ocean voyages 是跨海進行、距離和時間都很長的旅程。"},{"en":"Sailors on long ocean voyages need food, water, fuel, and repair supplies.","zh":"長途遠洋航行中的船員需要食物、水、燃料和維修物資。"},{"en":"If technology improves, long ocean voyages can become safer and faster.","zh":"如果科技改善，長途遠洋航行可以變得更安全更快速。"},{"en":"The phrase suggests demanding travel far from land.","zh":"這個片語暗示遠離陸地的艱巨旅程。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":17},{"front":"figure out","meaning":"想明白；弄清楚","examples":[{"en":"Brunel correctly figured out that size mattered.","zh":"布魯內爾正確地想明白了大小很重要。"},{"en":"Figure out means understand or solve something after thinking.","zh":"figure out 指經思考後理解或解決某事。"},{"en":"A student may figure out a maths problem after drawing a diagram.","zh":"學生可能畫圖後弄清楚一道數學題。"},{"en":"If engineers figure out the real cause of a failure, they can improve the design.","zh":"如果工程師弄清楚故障真正原因，就可以改善設計。"},{"en":"The phrase suggests active thinking rather than immediate knowing.","zh":"這個片語暗示主動思考，而不是立即知道。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":17},{"front":"size mattered","meaning":"大小很重要","examples":[{"en":"Brunel realised that size mattered for long steamship voyages.","zh":"布魯內爾意識到大小對長途蒸汽船航行很重要。"},{"en":"Size mattered means size was important for success or function.","zh":"size mattered 指大小對成功或功能很重要。"},{"en":"When choosing a classroom, size matters because students need space to move.","zh":"選擇課室時，大小很重要，因為學生需要活動空間。"},{"en":"For long voyages, size mattered because a larger ship could carry more fuel.","zh":"對長途航行而言，大小很重要，因為較大船隻可攜帶更多燃料。"},{"en":"The phrase emphasises that physical scale affects what is possible.","zh":"這個片語強調實體規模會影響可能性。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":17},{"front":"set out to design","meaning":"着手設計","examples":[{"en":"Brunel set out to design the biggest ship ever.","zh":"布魯內爾着手設計有史以來最大的船。"},{"en":"Set out to design means begin with the clear aim of creating a design.","zh":"set out to design 指帶着明確目標開始創造設計。"},{"en":"An architect set out to design a school that used natural light well.","zh":"建築師着手設計一所善用自然光的學校。"},{"en":"If someone sets out to design something difficult, they need clear goals and patience.","zh":"如果某人着手設計困難事物，就需要清晰目標和耐性。"},{"en":"The phrase suggests deliberate beginning with purpose.","zh":"這個片語暗示有目的地開始。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":17},{"front":"the biggest ship ever","meaning":"有史以來最大的船","examples":[{"en":"The Great Eastern was designed as the biggest ship ever.","zh":"Great Eastern 被設計為有史以來最大的船。"},{"en":"The biggest ship ever means the largest ship built or planned up to that time.","zh":"the biggest ship ever 指截至當時建造或計劃中最大的船。"},{"en":"A museum exhibit may describe a vessel as the biggest ship ever built in its era.","zh":"博物館展覽可能把某船描述為其時代有史以來最大的船。"},{"en":"If a ship is the biggest ever, its construction requires unusual tools and planning.","zh":"如果一艘船是有史以來最大的，其建造需要不尋常工具和規劃。"},{"en":"The phrase highlights record-breaking scale.","zh":"這個片語強調破紀錄規模。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":17},{"front":"five times larger than","meaning":"比……大五倍","examples":[{"en":"The ship was five times larger than any ship built up to that time.","zh":"這艘船比截至當時建造的任何船都大五倍。"},{"en":"Five times larger than means having five times the size of something else.","zh":"five times larger than 指大小是另一物的五倍。"},{"en":"The new library is five times larger than the old reading room.","zh":"新圖書館比舊閱覽室大五倍。"},{"en":"If a ship is five times larger than earlier ships, construction risks increase greatly.","zh":"如果一艘船比早期船隻大五倍，建造風險會大幅增加。"},{"en":"The phrase gives a strong numerical comparison.","zh":"這個片語給出強烈數字比較。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":17},{"front":"built up to that time","meaning":"截至當時建造的","examples":[{"en":"No ship built up to that time was as large as the Great Eastern.","zh":"截至當時建造的船，沒有一艘像 Great Eastern 那麼大。"},{"en":"Built up to that time means constructed before that point in history.","zh":"built up to that time 指在歷史上該時間點之前建造的。"},{"en":"No school built up to that time in the town had such a large hall.","zh":"鎮上截至當時建造的學校，沒有一所有如此大的禮堂。"},{"en":"If no machine built up to that time was as powerful, the new design was groundbreaking.","zh":"如果截至當時建造的機器都沒有如此強大，新設計就是突破性的。"},{"en":"The phrase compares something with all earlier examples.","zh":"這個片語把某物與所有較早例子比較。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":17},{"front":"big enough to","meaning":"大得足以……","examples":[{"en":"The ship was big enough to carry enough fuel to Australia.","zh":"這艘船大得足以攜帶到澳洲所需的燃料。"},{"en":"Big enough to means having sufficient size to do something.","zh":"big enough to 指大小足夠做某事。"},{"en":"The room is big enough to hold thirty students.","zh":"這個房間大得足以容納三十名學生。"},{"en":"If a bag is big enough to carry books and a laptop, students may use it daily.","zh":"如果袋子大得足以裝書和手提電腦，學生可能每天使用。"},{"en":"The phrase connects size with ability.","zh":"這個片語把大小與能力連接起來。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":17},{"front":"without refuelling","meaning":"無需補充燃料","examples":[{"en":"The ship could reach Australia without refuelling.","zh":"這艘船無需補充燃料便可到達澳洲。"},{"en":"Without refuelling means without stopping to add more fuel.","zh":"without refuelling 指無需停下來添加更多燃料。"},{"en":"A car with a large tank can drive farther without refuelling.","zh":"油缸大的車可以行駛更遠而無需補充燃料。"},{"en":"If a ship can travel without refuelling, the journey may be faster and simpler.","zh":"如果船能無需補充燃料航行，旅程可能更快更簡單。"},{"en":"The phrase focuses on fuel independence during travel.","zh":"這個片語集中於旅程中的燃料獨立性。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":18},{"front":"displacement","meaning":"排水量","examples":[{"en":"The Great Eastern had a displacement of about 32,000 tons.","zh":"Great Eastern 的排水量約為32,000噸。"},{"en":"Displacement is a measure of how much water a ship pushes aside, often linked to its size.","zh":"displacement 是量度船隻排開多少水的指標，常與船隻大小有關。"},{"en":"Engineers use displacement to understand how heavy a ship is in the water.","zh":"工程師用排水量了解船在水中的重量。"},{"en":"If a ship has huge displacement, harbours and docks must be able to handle it.","zh":"如果船隻排水量巨大，港口和船塢必須能處理它。"},{"en":"The word is technical and common in naval design.","zh":"這個詞較技術性，常見於船舶設計。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":18},{"front":"naval architect","meaning":"造船工程師","examples":[{"en":"John Scott Russell was a well-established engineer and naval architect.","zh":"John Scott Russell 是一位甚具名望的工程師和造船工程師。"},{"en":"A naval architect is a specialist who designs ships and other marine vessels.","zh":"naval architect 是設計船隻和其他海上船舶的專家。"},{"en":"A naval architect must understand balance, strength, engines, and water movement.","zh":"造船工程師必須理解平衡、強度、引擎和水流。"},{"en":"If a naval architect miscalculates weight, a ship may not perform safely.","zh":"如果造船工程師錯誤計算重量，船隻可能無法安全運作。"},{"en":"The phrase refers to ship design, not building houses.","zh":"這個片語指船隻設計，而不是房屋建築。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":18},{"front":"well-established engineer","meaning":"甚具名望的工程師","examples":[{"en":"John Scott Russell was a well-established engineer.","zh":"John Scott Russell 是一位甚具名望的工程師。"},{"en":"A well-established engineer is an engineer with a strong reputation and recognised experience.","zh":"well-established engineer 是擁有良好聲譽和公認經驗的工程師。"},{"en":"A company may hire a well-established engineer for a risky bridge project.","zh":"公司可能為高風險橋樑項目聘請甚具名望的工程師。"},{"en":"If a well-established engineer makes low cost estimates, people may trust them too easily.","zh":"如果甚具名望的工程師作出過低成本估算，人們可能太容易相信。"},{"en":"The phrase suggests status and professional credibility.","zh":"這個片語暗示地位和專業可信度。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":18},{"front":"the contract did not go well","meaning":"合約執行情況不順利","examples":[{"en":"The contract for building the Great Eastern did not go well.","zh":"建造 Great Eastern 的合約執行情況不順利。"},{"en":"The contract did not go well means the agreed work had problems, delays, or disputes.","zh":"the contract did not go well 指已協定的工作出現問題、延誤或爭議。"},{"en":"The cleaning contract did not go well because staff kept missing appointments.","zh":"清潔合約執行情況不順利，因為員工經常錯過預約。"},{"en":"If a construction contract does not go well, costs and arguments can rise quickly.","zh":"如果建築合約執行情況不順利，成本和爭論可能迅速增加。"},{"en":"The phrase describes a troubled business arrangement.","zh":"這個片語描述有問題的商業安排。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":18},{"front":"very low in his estimates","meaning":"估算過低","examples":[{"en":"Scott Russell was very low in his estimates.","zh":"Scott Russell 的估算過低。"},{"en":"Very low in his estimates means he predicted costs or requirements to be much lower than they really were.","zh":"very low in his estimates 指他預測的成本或需求遠低於實際情況。"},{"en":"A builder who is very low in his estimates may later ask for more money.","zh":"估算過低的建築商日後可能要求更多款項。"},{"en":"If estimates are too low, a project can run out of funds halfway through.","zh":"如果估算過低，項目可能在中途耗盡資金。"},{"en":"The phrase warns that early calculations were unrealistic.","zh":"這個片語提醒早期計算不切實際。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":18},{"front":"money was soon a problem","meaning":"資金很快成為問題","examples":[{"en":"Money was soon a problem during construction.","zh":"建造期間資金很快成為問題。"},{"en":"Money was soon a problem means funding quickly became insufficient or difficult to manage.","zh":"money was soon a problem 指資金很快變得不足或難以管理。"},{"en":"Money was soon a problem when the family renovation cost more than expected.","zh":"家庭裝修成本高於預期時，資金很快成為問題。"},{"en":"If estimates are too low, money can soon become a problem.","zh":"如果估算過低，資金很快便會成為問題。"},{"en":"The phrase shows that financial trouble appeared early.","zh":"這個片語顯示財政困難很早出現。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":18},{"front":"come to a standstill","meaning":"停頓下來","examples":[{"en":"Construction came to a standstill in 1856.","zh":"建造工程於1856年停頓下來。"},{"en":"Come to a standstill means stop moving or making progress completely.","zh":"come to a standstill 指完全停止移動或進展。"},{"en":"Traffic came to a standstill after the accident.","zh":"意外後，交通完全停頓下來。"},{"en":"If funding disappears, a building project may come to a standstill.","zh":"如果資金消失，建築項目可能停頓下來。"},{"en":"The phrase suggests a full stop, not just slower progress.","zh":"這個片語暗示完全停止，而不只是進展變慢。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":18},{"front":"take over the work","meaning":"接手工作","examples":[{"en":"Brunel himself had to take over the work.","zh":"布魯內爾本人不得不接手工作。"},{"en":"Take over the work means assume control or responsibility for a task someone else was handling.","zh":"take over the work 指接管原本由別人負責的任務或責任。"},{"en":"A manager may take over the work when a team member becomes ill.","zh":"當團隊成員生病，經理可能接手工作。"},{"en":"If a contractor fails, the client may need someone else to take over the work.","zh":"如果承辦商失敗，客戶可能需要其他人接手工作。"},{"en":"The phrase suggests a change in responsibility.","zh":"這個片語暗示責任轉移。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":18},{"front":"nothing if not determined","meaning":"極其堅定；非常有決心","examples":[{"en":"Brunel was nothing if not determined.","zh":"布魯內爾極其堅定。"},{"en":"Nothing if not determined means extremely determined, above all else.","zh":"nothing if not determined 指最明顯就是非常有決心。"},{"en":"A student who studies every night after failing twice is nothing if not determined.","zh":"一名學生兩次失敗後仍每晚溫習，真是非常有決心。"},{"en":"If a leader is nothing if not determined, setbacks may slow but not stop them.","zh":"如果領導者極其堅定，挫折可能拖慢他們，但不能阻止他們。"},{"en":"The phrase strongly emphasises one clear quality.","zh":"這個片語強烈強調一種明確特質。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":18},{"front":"delayed and problem-ridden launch","meaning":"延誤且問題重重的下水","examples":[{"en":"The Great Eastern had a delayed and problem-ridden launch.","zh":"Great Eastern 的下水延誤且問題重重。"},{"en":"A delayed and problem-ridden launch is a launch that happens late and with many difficulties.","zh":"delayed and problem-ridden launch 指發生得遲且充滿困難的下水或推出。"},{"en":"A new app had a delayed and problem-ridden launch when users could not log in.","zh":"新應用程式在用戶無法登入時，推出就變得延誤且問題重重。"},{"en":"If a ship has a delayed and problem-ridden launch, public confidence may suffer.","zh":"如果船隻下水延誤且問題重重，公眾信心可能受損。"},{"en":"The phrase combines time delay with repeated trouble.","zh":"這個片語結合時間延誤和反覆麻煩。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":19},{"front":"ready for its maiden voyage","meaning":"準備首航","examples":[{"en":"The Great Eastern was ready for its maiden voyage in 1859.","zh":"Great Eastern 於1859年準備首航。"},{"en":"Ready for its maiden voyage means prepared for its first journey.","zh":"ready for its maiden voyage 指已準備好進行首次航程。"},{"en":"After testing and repairs, the new ferry was ready for its maiden voyage.","zh":"經測試和維修後，新渡輪準備首航。"},{"en":"If a ship is ready for its maiden voyage, builders expect it to work at sea.","zh":"如果船隻準備首航，建造者預期它能在海上運作。"},{"en":"The phrase marks an important first test in real service.","zh":"這個片語標誌真正服務中的重要首次測試。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":19},{"front":"maiden voyage","meaning":"首航","examples":[{"en":"Brunel was too sick to go on the maiden voyage.","zh":"布魯內爾病得無法參與首航。"},{"en":"A maiden voyage is a ship’s first journey after it is built.","zh":"maiden voyage 是船建成後的首次航程。"},{"en":"Passengers were excited to join the ferry’s maiden voyage across the harbour.","zh":"乘客很興奮參加渡輪橫渡海港的首航。"},{"en":"If serious problems occur on a maiden voyage, the ship’s reputation can be damaged.","zh":"如果首航出現嚴重問題，船隻聲譽可能受損。"},{"en":"The phrase is mainly used for ships and important first journeys.","zh":"這個片語主要用於船隻和重要首次旅程。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":19},{"front":"too sick to go","meaning":"病得無法前往","examples":[{"en":"Brunel was too sick to go on the ship’s maiden voyage.","zh":"布魯內爾病得無法參與該船首航。"},{"en":"Too sick to go means so ill that someone cannot attend or travel.","zh":"too sick to go 指病得無法出席或旅行。"},{"en":"A student was too sick to go to school after a high fever.","zh":"學生發高燒後病得無法上學。"},{"en":"If someone is too sick to go, another person may have to represent them.","zh":"如果某人病得無法前往，可能要由其他人代表。"},{"en":"The phrase connects illness with inability to attend.","zh":"這個片語把疾病與無法出席連接起來。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":19},{"front":"just as well","meaning":"幸好如此","examples":[{"en":"It was just as well that Brunel did not go on the voyage.","zh":"幸好布魯內爾沒有參與該航程。"},{"en":"Just as well means it was fortunate or a good thing in the end.","zh":"just as well 指最終看來是幸運或好事。"},{"en":"It was just as well we left early, because the road later closed.","zh":"幸好我們早走，因為道路後來封閉。"},{"en":"If a dangerous accident happens, it may be just as well that someone stayed home.","zh":"如果發生危險事故，某人留在家可能幸好如此。"},{"en":"The phrase shows relief after seeing what happened.","zh":"這個片語顯示在知道結果後感到慶幸。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":19},{"front":"only a few hours out","meaning":"出航僅幾小時","examples":[{"en":"Only a few hours out, there was an explosion in the engine room.","zh":"出航僅幾小時，輪機艙就發生爆炸。"},{"en":"Only a few hours out means only a few hours after leaving port or starting a journey.","zh":"only a few hours out 指離港或開始旅程後僅幾小時。"},{"en":"Only a few hours out, the bus developed engine trouble.","zh":"出發僅幾小時，巴士就出現引擎故障。"},{"en":"If a ship has an accident only a few hours out, the voyage begins badly.","zh":"如果船隻出航僅幾小時便發生事故，航程開局很差。"},{"en":"The phrase stresses how soon a problem occurred.","zh":"這個片語強調問題很快發生。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":19},{"front":"engine room","meaning":"輪機艙","examples":[{"en":"An explosion occurred in the engine room.","zh":"輪機艙發生爆炸。"},{"en":"The engine room is the part of a ship where engines and related machinery are kept.","zh":"engine room 是船上放置引擎和相關機械的部分。"},{"en":"Crew members in the engine room monitor heat, fuel, and machinery.","zh":"輪機艙船員監察熱力、燃料和機械。"},{"en":"If a fire starts in the engine room, the whole ship may be in danger.","zh":"如果輪機艙起火，整艘船可能有危險。"},{"en":"The phrase refers to the mechanical heart of a ship.","zh":"這個片語指船隻的機械核心。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":19},{"front":"a lesser ship","meaning":"較差的船；不夠堅固的船","examples":[{"en":"The explosion would have destroyed a lesser ship.","zh":"這次爆炸本會摧毀一艘較差的船。"},{"en":"A lesser ship means a weaker, smaller, or less well-built ship.","zh":"a lesser ship 指較弱、較小或建造較差的船。"},{"en":"A lesser ship might not survive heavy storms that a strong vessel can handle.","zh":"較差的船可能無法承受強壯船隻能應付的暴風雨。"},{"en":"If an accident would destroy a lesser ship, the surviving ship must be exceptionally strong.","zh":"如果事故會摧毀較差的船，而該船仍生還，它必定非常堅固。"},{"en":"The phrase compares quality and strength.","zh":"這個片語比較質素和強度。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":19},{"front":"within a week or so of","meaning":"在……後約一星期內","examples":[{"en":"Brunel died within a week or so of the accident.","zh":"布魯內爾在事故後約一星期內去世。"},{"en":"Within a week or so of means about one week after a particular event.","zh":"within a week or so of 指在某事件後大約一星期內。"},{"en":"The patient returned to work within a week or so of the operation.","zh":"病人在手術後約一星期內復工。"},{"en":"If a leader dies within a week or so of a disaster, the timing feels especially tragic.","zh":"如果領袖在災難後約一星期內去世，時間上特別令人悲傷。"},{"en":"The phrase gives an approximate short time interval.","zh":"這個片語給出大約的短時間間隔。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":19},{"front":"among other things","meaning":"除其他因素外","examples":[{"en":"Among other things, the Suez Canal affected the ship’s commercial prospects.","zh":"除其他因素外，蘇伊士運河影響了這艘船的商業前景。"},{"en":"Among other things means including this factor, but not only this factor.","zh":"among other things 指包括這個因素，但不只包括這個因素。"},{"en":"Among other things, poor lighting made the classroom hard to use.","zh":"除其他因素外，照明差令課室難以使用。"},{"en":"If a business fails because of costs, delays, and competition, competition may be mentioned among other things.","zh":"如果企業因成本、延誤和競爭而失敗，競爭可被列為其中一個因素。"},{"en":"The phrase lets writers point to one cause within a wider set.","zh":"這個片語讓作者指出更廣泛因素中的一個原因。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":19},{"front":"come along","meaning":"出現；到來","examples":[{"en":"The Suez Canal came along and reduced the ship’s usefulness.","zh":"蘇伊士運河出現後，降低了這艘船的用途。"},{"en":"Come along means appear, arrive, or develop, often changing the situation.","zh":"come along 指出現、到來或發展出來，常改變情況。"},{"en":"When online banking came along, many people visited branches less often.","zh":"當網上銀行出現後，許多人較少到分行。"},{"en":"If a better technology comes along, an older design may become less useful.","zh":"如果更好的科技出現，舊設計可能變得較不實用。"},{"en":"The phrase suggests a new arrival that affects existing plans.","zh":"這個片語暗示新事物到來並影響現有計劃。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":20},{"front":"transatlantic crossings","meaning":"跨大西洋航程","examples":[{"en":"The Great Eastern made several transatlantic crossings.","zh":"Great Eastern 進行了幾次跨大西洋航程。"},{"en":"Transatlantic crossings are journeys across the Atlantic Ocean.","zh":"transatlantic crossings 是橫跨大西洋的旅程。"},{"en":"Early steamships made transatlantic crossings faster than many sailing ships.","zh":"早期蒸汽船進行跨大西洋航程，比許多帆船更快。"},{"en":"If a ship makes repeated transatlantic crossings, it must be strong and reliable.","zh":"如果船隻反覆進行跨大西洋航程，它必須堅固可靠。"},{"en":"The phrase is used for movement between the two sides of the Atlantic.","zh":"這個片語用於大西洋兩岸之間的移動。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":20},{"front":"financial success","meaning":"財務上的成功","examples":[{"en":"The Great Eastern was not a financial success.","zh":"Great Eastern 並不是財務上的成功。"},{"en":"A financial success is something that earns enough money or gives a good return.","zh":"financial success 指賺到足夠金錢或帶來良好回報的事物。"},{"en":"A film may be popular but not a financial success if production costs are too high.","zh":"一部電影可能受歡迎，但如果製作成本太高，就未必是財務上的成功。"},{"en":"If a ship carries too few paying passengers, it may fail as a financial success.","zh":"如果船隻載客付款人數太少，就可能無法在財務上成功。"},{"en":"The phrase judges success by money, not only technical achievement.","zh":"這個片語按金錢，而不只是技術成就來判斷成功。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":20},{"front":"working life","meaning":"服役生涯","examples":[{"en":"The Great Eastern later began a different working life.","zh":"Great Eastern 後來開始了不同的服役生涯。"},{"en":"Working life means the period or role in which a person, machine, or ship is actively used.","zh":"working life 指人、機器或船隻被積極使用的時期或角色。"},{"en":"A bus may have a long working life if it is repaired regularly.","zh":"如果巴士定期維修，它可能有很長服役生涯。"},{"en":"If a ship changes from passenger service to cable-laying, its working life changes.","zh":"如果船隻從客運服務改為鋪設電纜，其服役生涯就改變。"},{"en":"The phrase treats an object’s service period like a career.","zh":"這個片語把物件的服務期像職業生涯一樣描述。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":20},{"front":"entrepreneur","meaning":"企業家","examples":[{"en":"Cyrus Field was an American entrepreneur.","zh":"Cyrus Field 是一位美國企業家。"},{"en":"An entrepreneur is a person who starts or organises business projects, often taking financial risks.","zh":"entrepreneur 是創辦或組織商業項目，並常承擔財務風險的人。"},{"en":"A café owner who opens three shops is an entrepreneur.","zh":"開設三間咖啡店的店主是一位企業家。"},{"en":"Entrepreneurs may support new technology when they see a chance for profit or change.","zh":"當企業家看見盈利或改變的機會時，可能支持新科技。"},{"en":"The word suggests initiative, risk, and business activity.","zh":"這個詞暗示主動性、風險和商業活動。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":20},{"front":"backers","meaning":"支持者；資助者","examples":[{"en":"Cyrus Field and his backers needed a large ship.","zh":"Cyrus Field 和他的支持者需要一艘大船。"},{"en":"Backers are people who support a project, often with money, influence, or public approval.","zh":"backers 是支持項目的人，常以金錢、影響力或公開認可支持。"},{"en":"A young inventor may need backers before building a prototype.","zh":"年輕發明家在建造原型前可能需要資助者。"},{"en":"If backers lose confidence, a project may lose funding.","zh":"如果資助者失去信心，項目可能失去資金。"},{"en":"The phrase highlights support behind a plan.","zh":"這個片語強調計劃背後的支持。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":20},{"front":"telegraphic cable","meaning":"電報電纜","examples":[{"en":"The Great Eastern carried thousands of tons of telegraphic cable.","zh":"Great Eastern 運載了數千噸電報電纜。"},{"en":"Telegraphic cable is cable used to send telegraph messages over long distances.","zh":"telegraphic cable 是用來長距離傳送電報訊息的電纜。"},{"en":"Before modern internet, telegraphic cable helped people send information faster across oceans.","zh":"在現代互聯網以前，電報電纜幫助人們更快跨洋傳送資訊。"},{"en":"If telegraphic cable is damaged underwater, communication can be interrupted.","zh":"如果水底電報電纜受損，通訊可能中斷。"},{"en":"The phrase belongs to the history of long-distance communication.","zh":"這個片語屬於長距離通訊歷史。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":20},{"front":"be laid on the ocean floor","meaning":"鋪設在海床上","examples":[{"en":"The cable was to be laid on the ocean floor.","zh":"電纜將被鋪設在海床上。"},{"en":"Be laid on the ocean floor means be placed along the seabed under the ocean.","zh":"be laid on the ocean floor 指沿着海洋下的海床放置。"},{"en":"Modern internet cables are laid on the ocean floor between continents.","zh":"現代互聯網電纜被鋪設在各大洲之間的海床上。"},{"en":"If a cable is laid on the ocean floor, ships and currents can make repair difficult.","zh":"如果電纜鋪設在海床上，船隻和洋流會令維修困難。"},{"en":"The phrase describes underwater installation.","zh":"這個片語描述水底安裝。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":20},{"front":"from Ireland to Newfoundland","meaning":"從愛爾蘭到紐芬蘭","examples":[{"en":"The cable was laid from Ireland to Newfoundland.","zh":"電纜從愛爾蘭鋪設到紐芬蘭。"},{"en":"From Ireland to Newfoundland means across the Atlantic between Ireland and Newfoundland.","zh":"from Ireland to Newfoundland 指橫跨大西洋，從愛爾蘭到紐芬蘭。"},{"en":"A cable from one coast to another can connect distant communities.","zh":"從一個海岸到另一個海岸的電纜，可以連接遙遠社區。"},{"en":"If a cable runs from Ireland to Newfoundland, it links Europe and North America.","zh":"如果電纜從愛爾蘭到紐芬蘭，它就連接歐洲和北美。"},{"en":"The phrase gives the two endpoints of a long route.","zh":"這個片語給出長途路線的兩個端點。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":20},{"front":"have something in mind","meaning":"心中想到……","examples":[{"en":"Brunel did not have cable-laying in mind when he designed the ship.","zh":"布魯內爾設計這艘船時，心中並沒有想到鋪設電纜。"},{"en":"Have something in mind means be thinking of a particular purpose, plan, or idea.","zh":"have something in mind 指心中想着某個特定目的、計劃或想法。"},{"en":"A teacher may have weaker students in mind when preparing extra examples.","zh":"老師準備額外例子時，心中可能想到較弱學生。"},{"en":"If designers do not have future uses in mind, a product may be less flexible.","zh":"如果設計者沒有想到未來用途，產品可能較不靈活。"},{"en":"The phrase shows the intention behind a design or decision.","zh":"這個片語顯示設計或決定背後的意圖。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":20},{"front":"an excellent vessel for","meaning":"非常適合……的船隻","examples":[{"en":"The Great Eastern was an excellent vessel for laying cable.","zh":"Great Eastern 是非常適合鋪設電纜的船隻。"},{"en":"An excellent vessel for something is a ship very suitable for a particular purpose.","zh":"an excellent vessel for something 指非常適合某特定用途的船。"},{"en":"A wide, stable boat can be an excellent vessel for scientific research.","zh":"寬闊穩定的船可以是非常適合科學研究的船隻。"},{"en":"If a vessel has huge storage space, it may be excellent for carrying heavy equipment.","zh":"如果船隻有巨大儲存空間，它可能非常適合運載重型設備。"},{"en":"The phrase judges a ship by how well it fits a task.","zh":"這個片語根據船隻是否適合任務來判斷它。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":21},{"front":"successfully completed the connection","meaning":"成功完成連接","examples":[{"en":"The ship successfully completed the transatlantic cable connection.","zh":"這艘船成功完成跨大西洋電纜連接。"},{"en":"Successfully completed the connection means finished linking two places without failing.","zh":"successfully completed the connection 指成功把兩地連接起來，沒有失敗。"},{"en":"Engineers successfully completed the connection between the old and new water pipes.","zh":"工程師成功完成新舊水管之間的連接。"},{"en":"If a cable ship successfully completes the connection, messages can travel across the ocean.","zh":"如果電纜船成功完成連接，訊息就能跨洋傳送。"},{"en":"The phrase emphasises successful completion of a link.","zh":"這個片語強調一項連接成功完成。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":21},{"front":"transatlantic communication by cable","meaning":"跨大西洋電纜通訊","examples":[{"en":"The connection began a century of transatlantic communication by cable.","zh":"這項連接開啟了一個世紀的跨大西洋電纜通訊。"},{"en":"Transatlantic communication by cable means sending messages across the Atlantic through undersea cables.","zh":"transatlantic communication by cable 指透過海底電纜跨大西洋傳送訊息。"},{"en":"Before satellites, transatlantic communication by cable was a major technological achievement.","zh":"在衛星以前，跨大西洋電纜通訊是一項重大科技成就。"},{"en":"If cable communication becomes reliable, governments and businesses can exchange information faster.","zh":"如果電纜通訊變得可靠，政府和企業可更快交換資訊。"},{"en":"The phrase links ocean engineering with communication history.","zh":"這個片語把海洋工程與通訊歷史連接起來。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":21},{"front":"continue this career","meaning":"繼續這項用途；繼續這種生涯","examples":[{"en":"The ship continued this career for several years.","zh":"這艘船繼續這項用途數年。"},{"en":"Continue this career means keep doing the same kind of work or service.","zh":"continue this career 指繼續做同一類工作或服務。"},{"en":"After years as a teacher, she continued this career in adult education.","zh":"做了多年老師後，她在成人教育中繼續這項事業。"},{"en":"If a ship continues this career, it remains useful in its new role.","zh":"如果船隻繼續這種生涯，它在新角色中仍然有用。"},{"en":"The phrase treats a ship’s role like a person’s career path.","zh":"這個片語把船的角色像人的職業道路一樣描述。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":21},{"front":"laying cables","meaning":"鋪設電纜","examples":[{"en":"The Great Eastern was used for laying cables in many parts of the world.","zh":"Great Eastern 被用於世界多地鋪設電纜。"},{"en":"Laying cables means placing long wires or communication lines along land or under water.","zh":"laying cables 指在陸地上或水底放置長電線或通訊線。"},{"en":"Workers laying cables under a street may close one lane for safety.","zh":"在街道下鋪設電纜的工人可能為安全封閉一條行車線。"},{"en":"If a ship is laying cables on the ocean floor, it must move slowly and accurately.","zh":"如果船正在海床上鋪設電纜，它必須緩慢而準確地移動。"},{"en":"The phrase describes installing communication or power lines.","zh":"這個片語描述安裝通訊線或電力線。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":21},{"front":"use the information in the passage","meaning":"使用文章中的資料","examples":[{"en":"Students must use the information in the passage to match projects with descriptions.","zh":"學生必須使用文章中的資料，把項目與描述配對。"},{"en":"Use the information in the passage means base answers only on what the reading text says.","zh":"use the information in the passage 指只根據閱讀文章所說內容作答。"},{"en":"In a reading test, students should use the information in the passage rather than outside knowledge.","zh":"在閱讀測驗中，學生應使用文章中的資料，而不是外部知識。"},{"en":"If you use the information in the passage carefully, you can avoid guessing.","zh":"如果你仔細使用文章中的資料，就可以避免猜測。"},{"en":"The phrase reminds students to rely on textual evidence.","zh":"這個片語提醒學生依賴文本證據。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":21},{"front":"match the projects with","meaning":"將項目與……配對","examples":[{"en":"The task asks students to match the projects with opinions or deeds.","zh":"題目要求學生將項目與意見或事蹟配對。"},{"en":"Match the projects with means connect each project to the correct description or answer.","zh":"match the projects with 指把每個項目連接到正確描述或答案。"},{"en":"Students may match the people with their jobs in a vocabulary exercise.","zh":"學生可能在詞彙練習中把人物與職業配對。"},{"en":"If you match projects with the wrong descriptions, the answer will be marked incorrect.","zh":"如果你把項目與錯誤描述配對，答案會被判錯。"},{"en":"The phrase describes a common reading-test task.","zh":"這個片語描述常見閱讀測驗任務。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":21},{"front":"projects Brunel worked on","meaning":"Brunel 參與過的項目","examples":[{"en":"The question lists projects Brunel worked on.","zh":"題目列出布魯內爾參與過的項目。"},{"en":"Projects Brunel worked on are engineering tasks or designs in which Brunel took part.","zh":"projects Brunel worked on 是布魯內爾參與的工程任務或設計。"},{"en":"A biography may organise chapters around projects a famous engineer worked on.","zh":"傳記可能按著名工程師參與過的項目組織章節。"},{"en":"If students know which projects Brunel worked on, they can match details more accurately.","zh":"如果學生知道布魯內爾參與過哪些項目，就能更準確配對細節。"},{"en":"The phrase focuses on his involvement, not necessarily sole responsibility.","zh":"這個片語集中於他的參與，而不一定是唯一責任。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":21},{"front":"opinions or deeds","meaning":"意見或事蹟","examples":[{"en":"The projects must be matched with opinions or deeds below.","zh":"這些項目必須與下面的意見或事蹟配對。"},{"en":"Opinions or deeds means what people thought or what people did.","zh":"opinions or deeds 指人們的想法或所做的事。"},{"en":"In history lessons, students often connect leaders with their opinions or deeds.","zh":"在歷史課中，學生常把領袖與其意見或事蹟連接起來。"},{"en":"If a question asks for opinions or deeds, students must separate beliefs from actions.","zh":"如果題目問意見或事蹟，學生必須分清信念和行動。"},{"en":"The phrase covers both views and behaviour.","zh":"這個片語同時涵蓋觀點和行為。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":21},{"front":"appropriate letters","meaning":"適當字母","examples":[{"en":"Students write the appropriate letters in the answer boxes.","zh":"學生在答案框中寫上適當字母。"},{"en":"Appropriate letters are the correct option labels that match the answers.","zh":"appropriate letters 是與答案相符的正確選項字母。"},{"en":"In a matching task, students may write appropriate letters such as A, B, or C.","zh":"在配對題中，學生可能寫上 A、B 或 C 等適當字母。"},{"en":"If students write the wrong letters, the answer may fail even if they understand the text.","zh":"如果學生寫錯字母，即使理解文章，答案也可能錯。"},{"en":"The phrase is an exam instruction about answer format.","zh":"這個片語是關於答案格式的考試指示。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":21},{"front":"construction project","meaning":"建築工程項目","examples":[{"en":"The tunnel was a construction project connected with Brunel’s early life.","zh":"這條隧道是與布魯內爾早年生活有關的建築工程項目。"},{"en":"A construction project is planned building work, such as a road, tunnel, bridge, or building.","zh":"construction project 是有計劃的建造工程，例如道路、隧道、橋樑或建築物。"},{"en":"A school extension is a construction project that affects students and neighbours.","zh":"學校擴建是一項會影響學生和鄰居的建築工程項目。"},{"en":"If a construction project is dangerous, strict safety rules are needed.","zh":"如果建築工程項目危險，就需要嚴格安全規則。"},{"en":"The phrase focuses on physical building work.","zh":"這個片語集中於實體建造工作。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":22},{"front":"be responsible for","meaning":"負責","examples":[{"en":"The question asks which construction project Brunel was not responsible for.","zh":"題目問哪個建築工程項目不是布魯內爾負責的。"},{"en":"Be responsible for means have duty, control, or accountability for something.","zh":"be responsible for 指對某事有職責、控制權或責任。"},{"en":"A class monitor may be responsible for collecting homework.","zh":"班長可能負責收功課。"},{"en":"If an engineer is responsible for a project, mistakes may affect their reputation.","zh":"如果工程師負責某項目，錯誤可能影響其聲譽。"},{"en":"The phrase shows who is in charge or accountable.","zh":"這個片語顯示誰主管或需要負責。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":22},{"front":"because of inconvenience","meaning":"因為不便","examples":[{"en":"The atmospheric railway was abandoned because of inconvenience and cost.","zh":"大氣壓鐵路因為不便和成本而被放棄。"},{"en":"Because of inconvenience means due to practical difficulty or trouble caused to users or operators.","zh":"because of inconvenience 指由於對使用者或營運者造成實際困難或麻煩。"},{"en":"A meeting may be cancelled because of inconvenience caused by transport strikes.","zh":"會議可能因交通罷工造成不便而取消。"},{"en":"If a system creates too much inconvenience, people may stop using it.","zh":"如果系統造成太多不便，人們可能停止使用。"},{"en":"The phrase gives practical difficulty as the reason.","zh":"這個片語把實際困難作為原因。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":22},{"front":"high maintenance costs","meaning":"高昂維修成本","examples":[{"en":"The system was abandoned because of high maintenance costs.","zh":"該系統因高昂維修成本而被放棄。"},{"en":"High maintenance costs are large expenses needed to keep something working properly.","zh":"high maintenance costs 是令某物正常運作所需的大額持續開支。"},{"en":"An old car may have high maintenance costs if parts often break.","zh":"如果舊車零件經常壞，它可能有高昂維修成本。"},{"en":"If high maintenance costs continue, replacing the system may be cheaper.","zh":"如果高昂維修成本持續，更換系統可能更便宜。"},{"en":"The phrase focuses on ongoing repair expense.","zh":"這個片語集中於持續維修開支。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":22},{"front":"after his death","meaning":"在他去世後","examples":[{"en":"The bridge was completed in Brunel’s honour after his death.","zh":"這座橋在布魯內爾去世後為紀念他而完成。"},{"en":"After his death means following the time when he died.","zh":"after his death 指在他去世之後。"},{"en":"An author’s final book may be published after his death.","zh":"作者的最後一本書可能在他去世後出版。"},{"en":"If a project is completed after his death, others carried on his work.","zh":"如果項目在他去世後完成，其他人延續了他的工作。"},{"en":"The phrase connects later events with a person’s passing.","zh":"這個片語把後來事件與某人的離世連接起來。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":22},{"front":"encounter budget problems","meaning":"遇到預算問題","examples":[{"en":"The Great Eastern encountered budget problems during construction.","zh":"Great Eastern 在建造期間遇到預算問題。"},{"en":"Encounter budget problems means face difficulties because available money is not enough or not well planned.","zh":"encounter budget problems 指因可用資金不足或規劃不佳而面對困難。"},{"en":"A school trip may encounter budget problems if transport prices rise suddenly.","zh":"如果交通價格突然上升，學校旅行可能遇到預算問題。"},{"en":"If a project encounters budget problems, work may slow down or stop.","zh":"如果項目遇到預算問題，工作可能放慢或停止。"},{"en":"The phrase focuses on financial difficulty during a plan.","zh":"這個片語集中於計劃中的財政困難。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":22},{"front":"despite being built by","meaning":"儘管由……建造","examples":[{"en":"The ship had problems despite being built by a famous engineer.","zh":"這艘船儘管由著名工程師建造，仍出現問題。"},{"en":"Despite being built by means even though it was made or designed by someone.","zh":"despite being built by 指即使由某人建造或設計。"},{"en":"The house leaked despite being built by an experienced contractor.","zh":"這間屋儘管由有經驗承辦商建造，仍然漏水。"},{"en":"If a project fails despite being built by experts, the problem may be unusually difficult.","zh":"如果項目儘管由專家建造仍失敗，問題可能異常困難。"},{"en":"The phrase shows contrast between expectation and reality.","zh":"這個片語顯示期望與現實的對比。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":22},{"front":"serious problem occurred","meaning":"發生嚴重問題","examples":[{"en":"A serious problem occurred during the Great Eastern’s maiden voyage.","zh":"Great Eastern 首航期間發生嚴重問題。"},{"en":"Serious problem occurred means an important and worrying difficulty happened.","zh":"serious problem occurred 指出現重要且令人擔心的困難。"},{"en":"A serious problem occurred when the school’s heating failed in winter.","zh":"學校暖氣在冬天故障時，發生了嚴重問題。"},{"en":"If a serious problem occurs on a first journey, confidence may fall.","zh":"如果首次旅程發生嚴重問題，信心可能下降。"},{"en":"The phrase signals a major issue, not a small inconvenience.","zh":"這個片語表示重大問題，而不是小不便。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":22},{"front":"after repeated delays","meaning":"在多次延誤後","examples":[{"en":"A serious problem occurred after repeated delays.","zh":"在多次延誤後，發生了嚴重問題。"},{"en":"After repeated delays means following several times when progress was postponed.","zh":"after repeated delays 指在進展多次被推遲之後。"},{"en":"After repeated delays, the new library finally opened.","zh":"在多次延誤後，新圖書館終於開幕。"},{"en":"If a problem occurs after repeated delays, people may become even more frustrated.","zh":"如果在多次延誤後又出現問題，人們可能更加沮喪。"},{"en":"The phrase shows that trouble happened after a long waiting period.","zh":"這個片語顯示麻煩發生在漫長等待之後。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":22},{"front":"first project of its kind","meaning":"同類中的首個項目","examples":[{"en":"The Great Britain was the first project of its kind to cross the Atlantic.","zh":"Great Britain 是同類中首個橫渡大西洋的項目。"},{"en":"First project of its kind means the earliest example with that special design or purpose.","zh":"first project of its kind 指具有該特殊設計或目的的最早例子。"},{"en":"A solar-powered ferry may be the first project of its kind in a harbour.","zh":"太陽能渡輪可能是港口中同類中的首個項目。"},{"en":"If a project is the first of its kind, it may face risks that others have not tested.","zh":"如果項目是同類中的首個，它可能面對其他人未測試過的風險。"},{"en":"The phrase highlights innovation and uniqueness.","zh":"這個片語強調創新和獨特性。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":22},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"Students must identify which paragraph contains the information.","zh":"學生必須辨認哪一段包含該資料。"},{"en":"Which paragraph contains means which section of the passage includes a particular detail.","zh":"which paragraph contains 指文章中哪一部分包含某個特定細節。"},{"en":"In a reading test, students scan to find which paragraph contains a date or name.","zh":"在閱讀測驗中，學生會掃讀以找出哪一段包含日期或名字。"},{"en":"If you know which paragraph contains the answer, you can avoid reading every line again.","zh":"如果你知道哪一段包含答案，就可避免重新閱讀每一行。"},{"en":"The phrase is common in paragraph-matching tasks.","zh":"這個片語常見於段落配對題。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":23},{"front":"the following information","meaning":"以下資料","examples":[{"en":"The task asks where the following information appears.","zh":"題目問以下資料出現在哪裡。"},{"en":"The following information means the details listed next in the question.","zh":"the following information 指題目接下來列出的細節。"},{"en":"Students should read the following information before searching the passage.","zh":"學生應先閱讀以下資料，然後再搜尋文章。"},{"en":"If the following information mentions a ship, look for ship names and related details.","zh":"如果以下資料提到船，就尋找船名和相關細節。"},{"en":"The phrase points forward to material that comes next.","zh":"這個片語指向接下來的材料。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":23},{"front":"use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"The instructions say students may use any letter more than once.","zh":"指示說學生可以重複使用任何字母。"},{"en":"Use any letter more than once means the same answer option can be chosen repeatedly.","zh":"use any letter more than once 指同一答案選項可以重複選用。"},{"en":"In some matching tasks, students may use any letter more than once if two answers are in the same paragraph.","zh":"在某些配對題中，如果兩個答案在同一段，學生可以重複使用任何字母。"},{"en":"If this rule is given, students should not assume each letter is used only once.","zh":"如果給出這條規則，學生不應假設每個字母只能用一次。"},{"en":"The phrase prevents a common exam mistake.","zh":"這個片語防止常見考試錯誤。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":23},{"front":"great ship","meaning":"巨型船隻","examples":[{"en":"The passage describes a great ship that set a standard for ocean travel.","zh":"文章描述一艘為遠洋航行樹立標準的巨型船隻。"},{"en":"A great ship is an impressive or important ship, often because of size, design, or achievement.","zh":"great ship 指令人印象深刻或重要的船，常因其大小、設計或成就而聞名。"},{"en":"A museum may display a model of a great ship from maritime history.","zh":"博物館可能展示海事史上一艘巨型船隻的模型。"},{"en":"If a great ship changes travel habits, it becomes historically important.","zh":"如果巨型船隻改變旅行習慣，它就具有歷史重要性。"},{"en":"The phrase praises the ship’s significance, not just its size.","zh":"這個片語讚揚船隻的重要性，而不只是大小。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":23},{"front":"set a standard for ocean travel","meaning":"為遠洋航行樹立標準","examples":[{"en":"The Great Britain set a standard for ocean travel.","zh":"Great Britain 為遠洋航行樹立標準。"},{"en":"Set a standard for ocean travel means become a model for how long-distance sea journeys should be made.","zh":"set a standard for ocean travel 指成為長距離海上旅程應如何進行的典範。"},{"en":"A safer ship design can set a standard for ocean travel across the world.","zh":"更安全的船隻設計可以為全球遠洋航行樹立標準。"},{"en":"If a vessel sets a standard for ocean travel, later ships may copy its features.","zh":"如果船隻為遠洋航行樹立標準，後來船隻可能模仿其特點。"},{"en":"The phrase connects innovation with lasting influence.","zh":"這個片語把創新與長遠影響連接起來。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":23},{"front":"ambitious project","meaning":"雄心勃勃的項目","examples":[{"en":"The Great Eastern was an ambitious project later used for another purpose.","zh":"Great Eastern 是一個雄心勃勃的項目，後來用於另一目的。"},{"en":"An ambitious project is a large, difficult project that aims to achieve something impressive.","zh":"ambitious project 是目標宏大、困難且希望達成重大成果的項目。"},{"en":"Building a new underground railway is an ambitious project for a city.","zh":"興建新地鐵對城市而言是一個雄心勃勃的項目。"},{"en":"If an ambitious project succeeds, it can change what people think is possible.","zh":"如果雄心勃勃的項目成功，它可以改變人們對可能性的想像。"},{"en":"The phrase suggests high goals and high risk.","zh":"這個片語暗示高目標和高風險。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":23},{"front":"unplanned purpose","meaning":"原先沒有計劃的用途","examples":[{"en":"The ship was later used for an unplanned purpose.","zh":"這艘船後來被用於原先沒有計劃的用途。"},{"en":"An unplanned purpose is a use that was not originally intended.","zh":"unplanned purpose 指原本沒有打算的用途。"},{"en":"A classroom may serve an unplanned purpose as a temporary clinic after a storm.","zh":"風暴後，課室可能作為臨時診所，發揮原先沒有計劃的用途。"},{"en":"If a design is flexible, it may later fit an unplanned purpose well.","zh":"如果設計具彈性，它日後可能很適合原先沒有計劃的用途。"},{"en":"The phrase shows that usefulness can appear unexpectedly.","zh":"這個片語顯示用途可以意外出現。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":23},{"front":"interpersonal skills","meaning":"人際技巧","examples":[{"en":"Brunel used interpersonal skills to win people over.","zh":"布魯內爾運用人際技巧說服人們。"},{"en":"Interpersonal skills are abilities used to communicate, persuade, cooperate, and build relationships with people.","zh":"interpersonal skills 是用來溝通、說服、合作和建立人際關係的能力。"},{"en":"A nurse needs interpersonal skills to calm patients and explain treatment.","zh":"護士需要人際技巧來安撫病人和解釋治療。"},{"en":"If an engineer has strong interpersonal skills, committees may understand and support the design.","zh":"如果工程師有強大人際技巧，委員會可能理解並支持設計。"},{"en":"The phrase focuses on dealing well with people.","zh":"這個片語集中於妥善與人相處。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":23},{"front":"secure approval for","meaning":"爭取對……的批准","examples":[{"en":"Brunel used his skills to secure approval for a railway project.","zh":"布魯內爾運用他的技巧爭取對鐵路項目的批准。"},{"en":"Secure approval for means successfully obtain permission or support for something.","zh":"secure approval for 指成功取得某事的批准或支持。"},{"en":"A teacher must secure approval for a school trip before booking buses.","zh":"老師在預訂巴士前，必須爭取學校旅行的批准。"},{"en":"If a plan affects many people, securing approval may require clear arguments.","zh":"如果計劃影響很多人，爭取批准可能需要清晰論據。"},{"en":"The phrase suggests winning official permission.","zh":"這個片語暗示取得官方許可。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":23},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students must complete the summary below using words from the passage.","zh":"學生必須使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the short text that follows.","zh":"complete the summary below 指在下方短文中填上缺失字詞。"},{"en":"In a reading test, students complete the summary below by finding exact words in the passage.","zh":"在閱讀測驗中，學生透過在文章中尋找原字來完成以下摘要。"},{"en":"If students ignore grammar, they may choose a word that does not fit the summary.","zh":"如果學生忽視文法，可能選到不適合摘要的字。"},{"en":"The phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":23},{"front":"no more than two words","meaning":"不超過兩個詞","examples":[{"en":"The answers must use no more than two words from the passage.","zh":"答案必須使用文章中不超過兩個詞。"},{"en":"No more than two words means one or two words only, not three or more.","zh":"no more than two words 指只能用一個或兩個詞，不能三個或以上。"},{"en":"If the answer is “engine room”, it follows the no more than two words rule.","zh":"如果答案是 engine room，它符合不超過兩個詞的規則。"},{"en":"If students write three words, the answer may be marked wrong even when the idea is right.","zh":"如果學生寫三個詞，即使意思正確，也可能被判錯。"},{"en":"The phrase gives a strict word limit.","zh":"這個片語給出嚴格字數限制。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":24},{"front":"on a large scale","meaning":"以大型規模","examples":[{"en":"The Great Eastern was designed on a large scale.","zh":"Great Eastern 以大型規模設計。"},{"en":"On a large scale means in a big size, amount, or level of operation.","zh":"on a large scale 指以很大的尺寸、數量或運作層級進行。"},{"en":"A city festival is organised on a large scale when roads, police, and many volunteers are needed.","zh":"當城市節日需要道路安排、警力和大量義工時，它就是以大型規模組織。"},{"en":"If a project is built on a large scale, small errors can become major problems.","zh":"如果項目以大型規模建造，小錯誤可能變成大問題。"},{"en":"The phrase emphasises size and ambition.","zh":"這個片語強調規模和雄心。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":24},{"front":"make a long voyage","meaning":"進行長途航行","examples":[{"en":"The ship was designed to make a long voyage without refuelling.","zh":"這艘船設計為無需補充燃料便可進行長途航行。"},{"en":"Make a long voyage means travel a great distance by sea.","zh":"make a long voyage 指在海上進行遠距離航行。"},{"en":"A research vessel may make a long voyage to collect ocean data.","zh":"研究船可能進行長途航行以收集海洋數據。"},{"en":"If a ship must make a long voyage, it needs enough fuel, food, and repair supplies.","zh":"如果船必須進行長途航行，就需要足夠燃料、食物和維修物資。"},{"en":"The phrase focuses on extended travel across water.","zh":"這個片語集中於跨水域的長時間旅行。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":24},{"front":"because of ill health","meaning":"因健康欠佳","examples":[{"en":"Because of ill health, Brunel could not join the maiden voyage.","zh":"因健康欠佳，布魯內爾無法參與首航。"},{"en":"Because of ill health means due to sickness or poor physical condition.","zh":"because of ill health 指由於疾病或身體狀況欠佳。"},{"en":"A teacher may take leave because of ill health.","zh":"老師可能因健康欠佳而請假。"},{"en":"If someone misses an important event because of ill health, the situation can feel disappointing.","zh":"如果某人因健康欠佳錯過重要事件，情況可能令人失望。"},{"en":"The phrase gives health as the reason for absence or difficulty.","zh":"這個片語把健康作為缺席或困難的原因。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":24},{"front":"accompany the maiden voyage","meaning":"參與首航","examples":[{"en":"Brunel could not accompany the maiden voyage of the Great Eastern.","zh":"布魯內爾無法參與 Great Eastern 的首航。"},{"en":"Accompany the maiden voyage means go along on a ship’s first journey.","zh":"accompany the maiden voyage 指隨船參加首次航程。"},{"en":"Engineers may accompany the maiden voyage to observe how the vessel performs.","zh":"工程師可能參與首航，以觀察船隻表現。"},{"en":"If the designer cannot accompany the maiden voyage, others must report any problems.","zh":"如果設計者無法參與首航，其他人必須報告任何問題。"},{"en":"The phrase connects attendance with an important first sailing.","zh":"這個片語把出席與重要首次航行連接起來。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":24},{"front":"be unprofitable","meaning":"無利可圖","examples":[{"en":"The Great Eastern was unprofitable as a passenger ship.","zh":"Great Eastern 作為客船無利可圖。"},{"en":"Be unprofitable means fail to make enough money or produce financial gain.","zh":"be unprofitable 指無法賺取足夠金錢或產生財務收益。"},{"en":"A shop may be unprofitable if rent is higher than sales income.","zh":"如果租金高於銷售收入，商店可能無利可圖。"},{"en":"If a ship is unprofitable, owners may search for a different use for it.","zh":"如果船隻無利可圖，船主可能尋找不同用途。"},{"en":"The phrase judges something by financial results.","zh":"這個片語按財務結果判斷某事。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":24},{"front":"unexpected opportunity","meaning":"意想不到的機會","examples":[{"en":"An unexpected opportunity arose when cable-layers needed a large vessel.","zh":"當鋪設電纜的人需要大型船隻時，意想不到的機會出現了。"},{"en":"An unexpected opportunity is a useful chance that appears without being planned.","zh":"unexpected opportunity 是沒有計劃卻出現的有用機會。"},{"en":"A student may get an unexpected opportunity to speak at an event when another speaker is absent.","zh":"當另一位講者缺席，學生可能獲得在活動發言的意想不到機會。"},{"en":"If a failed product finds a new use, an unexpected opportunity may appear.","zh":"如果失敗產品找到新用途，意想不到的機會可能出現。"},{"en":"The phrase suggests good possibility arising by surprise.","zh":"這個片語暗示出乎意料出現的好可能性。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":24},{"front":"vast quantity of","meaning":"大量的……","examples":[{"en":"The Great Eastern carried a vast quantity of telegraphic cable.","zh":"Great Eastern 運載大量電報電纜。"},{"en":"Vast quantity of means a very large amount of something.","zh":"vast quantity of 指非常大量的某物。"},{"en":"A warehouse may store a vast quantity of food before a festival.","zh":"倉庫可能在節日前儲存大量食物。"},{"en":"If a ship carries a vast quantity of cable, it needs huge storage space and strength.","zh":"如果船隻運載大量電纜，它需要巨大儲存空間和強度。"},{"en":"The phrase strongly emphasises amount.","zh":"這個片語強烈強調數量。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":24},{"front":"Atlantic Ocean floor","meaning":"大西洋海床","examples":[{"en":"The cable was laid on the Atlantic Ocean floor.","zh":"電纜被鋪設在大西洋海床上。"},{"en":"The Atlantic Ocean floor is the seabed beneath the Atlantic Ocean.","zh":"Atlantic Ocean floor 是大西洋下方的海床。"},{"en":"Scientists study the Atlantic Ocean floor to understand underwater mountains and trenches.","zh":"科學家研究大西洋海床，以了解水下山脈和海溝。"},{"en":"If a cable lies on the Atlantic Ocean floor, repairing it requires special ships and equipment.","zh":"如果電纜位於大西洋海床上，維修需要特殊船隻和設備。"},{"en":"The phrase identifies the deep underwater surface where the cable was placed.","zh":"這個片語指出電纜被放置的深海水底表面。"}],"source":"139 - Brunel - ‘The Practical Prophet’.pdf","sourcePage":24}],"ielts/reading/passage-2/Practice 140":[{"front":"Tattoo on Tikopia","meaning":"Tikopia 島上的紋身","examples":[{"en":"The passage discusses tattoo traditions on Tikopia.","zh":"文章討論 Tikopia 島上的紋身傳統。"},{"en":"Tattoo on Tikopia refers to the traditional tattooing practices found on the island of Tikopia.","zh":"「Tikopia 島上的紋身」指 Tikopia 島上發現的傳統紋身習俗。"},{"en":"A lesson on Tattoo on Tikopia may help students understand how body markings can carry social meaning.","zh":"關於 Tikopia 島上紋身的一課，可能幫助學生理解身體標記如何帶有社會意義。"},{"en":"Studying Tattoo on Tikopia shows that tattoos can be linked to identity, rank and ritual.","zh":"研究 Tikopia 島上的紋身顯示，紋身可以與身份、階級和儀式有關。"},{"en":"This topic is not only about decoration; it is also about culture and community life.","zh":"這個主題不只是關於裝飾；它也關於文化和社群生活。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":1},{"front":"debates about the origins of","meaning":"關於……起源的爭論","examples":[{"en":"There are still debates about the origins of Polynesian culture.","zh":"關於波利尼西亞文化起源的爭論仍然存在。"},{"en":"Debates about the origins of something are arguments about where or how it began.","zh":"「debates about the origins of」某事，指關於它從哪裡或如何開始的爭論。"},{"en":"Historians may have debates about the origins of an old festival when written records are missing.","zh":"當缺少書面記錄時，歷史學家可能對一個古老節日的起源有爭論。"},{"en":"Debates about the origins of a culture can continue when evidence is incomplete.","zh":"當證據不完整時，關於一種文化起源的爭論可以持續下去。"},{"en":"This phrase is useful when scholars do not fully agree on the beginning of something.","zh":"當學者未能完全同意某事的開始時，這個短語很有用。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":1},{"front":"Polynesian culture","meaning":"波利尼西亞文化","examples":[{"en":"Polynesian culture is not limited to a single tribe.","zh":"波利尼西亞文化不限於單一部族。"},{"en":"Polynesian culture includes the customs, languages, beliefs and social practices of Polynesian peoples.","zh":"波利尼西亞文化包括波利尼西亞人的習俗、語言、信念和社會做法。"},{"en":"Students may learn about Polynesian culture through dance, navigation, tattooing and oral history.","zh":"學生可以透過舞蹈、航海、紋身和口述歷史認識波利尼西亞文化。"},{"en":"Because Polynesia includes many islands, Polynesian culture is varied rather than uniform.","zh":"因為波利尼西亞包括許多島嶼，波利尼西亞文化是多樣的，而不是單一的。"},{"en":"The phrase refers to a broad cultural world, not one small community only.","zh":"這個短語指一個廣闊的文化世界，而不只是小社群。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":1},{"front":"one thing is certain","meaning":"有一點是肯定的","examples":[{"en":"One thing is certain: Polynesia is a complex cultural region.","zh":"有一點是肯定的：波利尼西亞是一個複雜的文化區域。"},{"en":"One thing is certain means at least one point is definitely true.","zh":"「one thing is certain」意思是至少有一點肯定是真實的。"},{"en":"We do not know who broke the window, but one thing is certain: it happened after school.","zh":"我們不知道是誰打破窗戶，但有一點是肯定的：事情是在放學後發生。"},{"en":"When many details are unclear, one thing is certain can introduce the strongest known fact.","zh":"當許多細節不清楚時，「有一點是肯定的」可以引出最可靠的事實。"},{"en":"This phrase helps separate a clear conclusion from uncertain information.","zh":"這個短語幫助把清楚結論與不確定資料分開。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":1},{"front":"a single tribe","meaning":"單一部族","examples":[{"en":"Polynesia is not a single tribe.","zh":"波利尼西亞不是單一部族。"},{"en":"A single tribe means one social or ethnic group, not many different groups.","zh":"「a single tribe」指一個社會或族群，而不是許多不同群體。"},{"en":"A country may contain many communities, so it should not be described as a single tribe.","zh":"一個國家可能包含許多社群，所以不應被描述為單一部族。"},{"en":"Treating a whole region as a single tribe can hide its diversity.","zh":"把整個地區看成單一部族，可能掩蓋其多樣性。"},{"en":"This phrase is often used to correct an oversimplified idea.","zh":"這個短語常用來糾正過分簡化的想法。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":1},{"front":"a complex cultural region","meaning":"複雜的文化區域","examples":[{"en":"Polynesia is a complex cultural region.","zh":"波利尼西亞是一個複雜的文化區域。"},{"en":"A complex cultural region is an area with many related but different traditions, languages and peoples.","zh":"「a complex cultural region」指擁有許多相關但不同傳統、語言和民族的地區。"},{"en":"Southeast Asia is a complex cultural region because its countries have many histories and religions.","zh":"東南亞是一個複雜的文化區域，因為其國家有許多歷史和宗教。"},{"en":"A complex cultural region cannot be understood through one simple label.","zh":"複雜的文化區域不能用一個簡單標籤來理解。"},{"en":"The phrase warns readers to expect variety and depth.","zh":"這個短語提醒讀者要預期多樣性和深度。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":1},{"front":"Polynesians","meaning":"波利尼西亞人","examples":[{"en":"Polynesians include Marquesans, Samoans, Tongans, Hawaiians and Māori.","zh":"波利尼西亞人包括馬克薩斯人、薩摩亞人、湯加人、夏威夷人和毛利人。"},{"en":"Polynesians are peoples whose cultures are connected with the islands of Polynesia.","zh":"「Polynesians」指文化與波利尼西亞群島相連的人群。"},{"en":"Polynesians developed important skills in ocean travel, navigation and island life.","zh":"波利尼西亞人在遠洋航行、導航和島嶼生活方面發展出重要技能。"},{"en":"Because Polynesians live across many islands, their traditions can be related but not identical.","zh":"因為波利尼西亞人分布於許多島嶼，他們的傳統可以相關但不完全相同。"},{"en":"The word names a broad group of peoples, not one single nation.","zh":"這個詞指廣泛的人群，而不是單一國家。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":1},{"front":"Marquesans, Samoans and Māori","meaning":"馬克薩斯人、薩摩亞人和毛利人","examples":[{"en":"Marquesans, Samoans and Māori are among the peoples of Polynesia.","zh":"馬克薩斯人、薩摩亞人和毛利人是波利尼西亞民族之一。"},{"en":"Marquesans, Samoans and Māori are different Polynesian peoples with their own traditions.","zh":"馬克薩斯人、薩摩亞人和毛利人是不同的波利尼西亞民族，各有自己的傳統。"},{"en":"A teacher may mention Marquesans, Samoans and Māori to show that Polynesia is culturally varied.","zh":"老師可能提到馬克薩斯人、薩摩亞人和毛利人，以顯示波利尼西亞文化多樣。"},{"en":"Listing these groups helps students avoid thinking of Polynesia as one identical culture.","zh":"列出這些群體有助學生避免把波利尼西亞想成完全相同的一種文化。"},{"en":"The phrase gives concrete examples of Polynesian peoples.","zh":"這個短語提供波利尼西亞民族的具體例子。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":1},{"front":"genetically linked to","meaning":"在基因上與……有關聯","examples":[{"en":"Polynesians are genetically linked to indigenous peoples in Southeast Asia.","zh":"波利尼西亞人在基因上與東南亞原住民族有關聯。"},{"en":"Genetically linked to means related through inherited biological ancestry.","zh":"「genetically linked to」意思是透過遺傳血統有關。"},{"en":"Two populations may be genetically linked to each other if their ancestors came from related groups.","zh":"如果兩個族群的祖先來自相關群體，它們可能在基因上彼此有關聯。"},{"en":"Genetic links can support historical theories about migration and settlement.","zh":"基因關聯可以支持關於遷徙和定居的歷史理論。"},{"en":"This phrase refers to biological ancestry, not simply cultural similarity.","zh":"這個短語指生物血統，而不只是文化相似。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":1},{"front":"indigenous peoples","meaning":"原住民族","examples":[{"en":"Polynesians are linked to indigenous peoples in parts of Southeast Asia.","zh":"波利尼西亞人與東南亞部分地區的原住民族有關聯。"},{"en":"Indigenous peoples are the original or earliest known peoples of a place.","zh":"「indigenous peoples」指某地最早或最早已知的民族。"},{"en":"Schools may teach students about indigenous peoples to show respect for local history.","zh":"學校可能教授學生認識原住民族，以尊重本地歷史。"},{"en":"Indigenous peoples often preserve languages, land knowledge and cultural practices.","zh":"原住民族常保存語言、土地知識和文化習俗。"},{"en":"The term should be used respectfully because it refers to real communities and histories.","zh":"這個詞應被尊重地使用，因為它指真實社群和歷史。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":1},{"front":"parts of Southeast Asia","meaning":"東南亞部分地區","examples":[{"en":"Some Polynesian groups are genetically linked to peoples in parts of Southeast Asia.","zh":"一些波利尼西亞群體在基因上與東南亞部分地區的人群有關。"},{"en":"Parts of Southeast Asia means some areas of the region, not the whole region.","zh":"「parts of Southeast Asia」意思是該地區中的一些地方，而不是整個地區。"},{"en":"Heavy rain affects parts of Southeast Asia during the monsoon season.","zh":"季風季節期間，大雨會影響東南亞部分地區。"},{"en":"Saying parts of Southeast Asia is more accurate than treating the whole region as identical.","zh":"說東南亞部分地區，比把整個地區視為完全相同更準確。"},{"en":"This phrase leaves room for regional differences.","zh":"這個短語保留了地區差異的空間。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":1},{"front":"a subregion of Oceania","meaning":"大洋洲的一個分區","examples":[{"en":"Polynesia is a subregion of Oceania.","zh":"波利尼西亞是大洋洲的一個分區。"},{"en":"A subregion of Oceania is a smaller geographical area within the wider Oceania region.","zh":"「a subregion of Oceania」指大洋洲這個較大地區內的一個較小地理區域。"},{"en":"A geography lesson may describe Polynesia, Melanesia and Micronesia as subregions of Oceania.","zh":"地理課可能把波利尼西亞、美拉尼西亞和密克羅尼西亞描述為大洋洲的分區。"},{"en":"Calling Polynesia a subregion helps locate it within a larger map.","zh":"稱波利尼西亞為一個分區，有助在較大地圖中定位它。"},{"en":"The phrase explains classification, not political control.","zh":"這個短語解釋分類，而不是政治控制。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":2},{"front":"comprising more than","meaning":"包括超過……","examples":[{"en":"Polynesia is a subregion comprising more than 1,000 islands.","zh":"波利尼西亞是一個包括超過一千個島嶼的分區。"},{"en":"Comprising more than means including a number greater than the one stated.","zh":"「comprising more than」意思是包括多於所述數目的東西。"},{"en":"A library comprising more than 50,000 books needs a good cataloguing system.","zh":"一間包括超過五萬本書的圖書館需要良好的目錄系統。"},{"en":"If a course comprises more than ten units, students should plan their revision early.","zh":"如果一門課程包括超過十個單元，學生應提早規劃溫習。"},{"en":"This phrase is formal and often used to describe what a group contains.","zh":"這個短語較正式，常用來描述一個群體包含什麼。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":2},{"front":"islands scattered across","meaning":"散布於……的島嶼","examples":[{"en":"Polynesia comprises islands scattered across the Pacific Ocean.","zh":"波利尼西亞包括散布於太平洋的島嶼。"},{"en":"Islands scattered across an area are islands spread widely rather than grouped closely together.","zh":"「islands scattered across」某地，指島嶼廣泛分散，而不是緊密聚集。"},{"en":"Small villages scattered across a mountain region can be hard to reach by bus.","zh":"散布於山區的小村莊可能很難乘巴士到達。"},{"en":"When islands are scattered across a large ocean, travel and communication become difficult.","zh":"當島嶼散布於大片海洋，交通和溝通會變得困難。"},{"en":"The phrase helps readers imagine wide geographical spread.","zh":"這個短語幫助讀者想像廣闊的地理分布。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":2},{"front":"the central and southern Pacific Ocean","meaning":"太平洋中部和南部","examples":[{"en":"Polynesian islands are scattered across the central and southern Pacific Ocean.","zh":"波利尼西亞島嶼散布於太平洋中部和南部。"},{"en":"The central and southern Pacific Ocean refers to the middle and southern areas of the Pacific.","zh":"「the central and southern Pacific Ocean」指太平洋的中部和南部海域。"},{"en":"Many island communities in the central and southern Pacific Ocean depend on the sea for food and travel.","zh":"太平洋中部和南部許多島嶼社群依賴海洋獲得食物和交通。"},{"en":"Because the area is wide, cultures there can be connected yet locally different.","zh":"因為該地區廣闊，那裡的文化可以相連但有本地差異。"},{"en":"The phrase gives a geographical frame for Polynesia.","zh":"這個短語為波利尼西亞提供地理框架。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":2},{"front":"within a triangle","meaning":"在一個三角形範圍內","examples":[{"en":"The islands lie within a triangle whose corners are New Zealand, Hawaii and Easter Island.","zh":"這些島嶼位於一個以新西蘭、夏威夷和復活節島為角落的三角形範圍內。"},{"en":"Within a triangle means inside an area shaped or imagined as a triangle.","zh":"「within a triangle」意思是在一個三角形或想像成三角形的範圍內。"},{"en":"A teacher may draw points on a map and say that the towns lie within a triangle.","zh":"老師可能在地圖上畫出幾點，然後說這些城鎮位於一個三角形範圍內。"},{"en":"Using a triangle helps learners remember the outer limits of a region.","zh":"使用三角形有助學習者記住一個地區的外圍界線。"},{"en":"This phrase describes location by using three corner points.","zh":"這個短語透過三個角點描述位置。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":2},{"front":"whose corners are","meaning":"其角落是……","examples":[{"en":"Polynesia lies within a triangle whose corners are New Zealand, Hawaii and Easter Island.","zh":"波利尼西亞位於一個三角形範圍內，其角落是新西蘭、夏威夷和復活節島。"},{"en":"Whose corners are introduces the points that form the corners of a shape or area.","zh":"「whose corners are」用來引出形成一個形狀或範圍角落的點。"},{"en":"The park lies inside a square whose corners are four old gates.","zh":"該公園位於一個正方形內，其角落是四座舊閘門。"},{"en":"If a map area has corners, naming them helps people locate the region clearly.","zh":"如果地圖範圍有角落，說出它們可幫助人清楚定位該地區。"},{"en":"This phrase is useful for explaining geographical boundaries.","zh":"這個短語適合解釋地理邊界。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":2},{"front":"Easter Island","meaning":"復活節島","examples":[{"en":"Easter Island forms one corner of the Polynesian triangle.","zh":"復活節島形成波利尼西亞三角的一個角落。"},{"en":"Easter Island is an island in the southeastern Pacific Ocean known for its large stone statues.","zh":"復活節島是位於東南太平洋的島嶼，以大型石像聞名。"},{"en":"A geography class may use Easter Island to mark the eastern edge of Polynesia.","zh":"地理課可能用復活節島來標示波利尼西亞的東部邊界。"},{"en":"Because Easter Island is far from many other islands, it shows how widely Polynesia extends.","zh":"因為復活節島距離許多其他島嶼很遠，它顯示波利尼西亞延伸範圍之廣。"},{"en":"The name often appears in discussions of Polynesian history and migration.","zh":"這個名稱常出現在波利尼西亞歷史和遷徙討論中。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":2},{"front":"Polynesian history","meaning":"波利尼西亞歷史","examples":[{"en":"Polynesian history has fascinated the Western world for centuries.","zh":"波利尼西亞歷史數百年來令西方世界着迷。"},{"en":"Polynesian history is the study of the past of Polynesian peoples and islands.","zh":"「Polynesian history」是研究波利尼西亞民族和島嶼過去的學問。"},{"en":"Polynesian history includes migration, navigation, settlement, family systems and ritual life.","zh":"波利尼西亞歷史包括遷徙、航海、定居、家庭制度和儀式生活。"},{"en":"Because much history was passed down orally, objects and traditions are also important evidence.","zh":"因為許多歷史透過口述傳承，物件和傳統也是重要證據。"},{"en":"The phrase points to a long and varied past across many islands.","zh":"這個短語指向許多島嶼上悠長而多樣的過去。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":2},{"front":"has fascinated","meaning":"令……着迷","examples":[{"en":"Polynesian history has fascinated many scholars and travellers.","zh":"波利尼西亞歷史令許多學者和旅客着迷。"},{"en":"Has fascinated means has strongly attracted people’s interest or curiosity.","zh":"「has fascinated」意思是強烈吸引人們的興趣或好奇心。"},{"en":"Space travel has fascinated children and adults for many generations.","zh":"太空旅行多年來令兒童和成人着迷。"},{"en":"A mystery can fascinate researchers when each answer leads to another question.","zh":"當一個謎團每個答案都引出另一個問題，它可以令研究人員着迷。"},{"en":"The phrase suggests long-lasting interest, not just brief attention.","zh":"這個短語暗示持久興趣，而不只是短暫注意。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":2},{"front":"the Western world","meaning":"西方世界","examples":[{"en":"Polynesian history has fascinated the Western world.","zh":"波利尼西亞歷史令西方世界着迷。"},{"en":"The Western world usually refers to Europe, North America and societies culturally linked to them.","zh":"「the Western world」通常指歐洲、北美以及文化上與它們相連的社會。"},{"en":"Ideas from the Western world reached many regions through trade, travel and empire.","zh":"西方世界的思想透過貿易、旅行和帝國傳到許多地區。"},{"en":"When writers mention the Western world, they often contrast it with non-Western societies.","zh":"當作者提到西方世界時，常把它與非西方社會作對比。"},{"en":"The phrase describes a broad cultural and historical grouping.","zh":"這個短語描述廣泛的文化和歷史群體。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":2},{"front":"European explorers","meaning":"歐洲探險家","examples":[{"en":"European explorers first encountered Pacific cultures in the eighteenth century.","zh":"歐洲探險家在十八世紀首次接觸太平洋文化。"},{"en":"European explorers were travellers from Europe who searched, mapped or wrote about other regions.","zh":"「European explorers」是來自歐洲、尋找、繪製或撰寫其他地區的人。"},{"en":"European explorers often recorded what they saw, but their views could be limited or biased.","zh":"歐洲探險家常記錄所見，但他們的觀點可能有限或有偏見。"},{"en":"When European explorers reached Pacific islands, their reports shaped Western ideas about those cultures.","zh":"當歐洲探險家到達太平洋島嶼，他們的報告塑造了西方對那些文化的看法。"},{"en":"The phrase places the passage in a history of travel and contact.","zh":"這個短語把文章置於旅行和接觸的歷史中。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":2},{"front":"first encountered","meaning":"首次接觸；首次遇見","examples":[{"en":"European explorers first encountered Pacific cultures in the late eighteenth century.","zh":"歐洲探險家在十八世紀末首次接觸太平洋文化。"},{"en":"First encountered means met, saw or came into contact with something for the first time.","zh":"「first encountered」意思是第一次遇見、看見或接觸某事物。"},{"en":"A student first encountered Shakespeare in secondary school.","zh":"一名學生在中學首次接觸莎士比亞。"},{"en":"When travellers first encounter a new custom, they may misunderstand it without explanation.","zh":"當旅客首次接觸新習俗時，如果沒有解釋，他們可能會誤解。"},{"en":"The phrase marks the beginning of contact or awareness.","zh":"這個短語標誌接觸或認識的開始。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":3},{"front":"Pacific cultures","meaning":"太平洋文化","examples":[{"en":"European explorers wrote about Pacific cultures.","zh":"歐洲探險家撰寫關於太平洋文化的文章。"},{"en":"Pacific cultures are the traditions, languages and social practices of peoples living in Pacific island regions.","zh":"「Pacific cultures」指生活在太平洋島嶼地區的人群的傳統、語言和社會做法。"},{"en":"Pacific cultures can include navigation knowledge, oral history, dance, tattooing and rituals.","zh":"太平洋文化可以包括航海知識、口述歷史、舞蹈、紋身和儀式。"},{"en":"Because Pacific cultures are diverse, one island should not be used to represent all of them.","zh":"因為太平洋文化多樣，不應用一個島嶼代表所有文化。"},{"en":"The phrase refers to many communities, not one single culture.","zh":"這個短語指許多社群，而不是一種單一文化。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":3},{"front":"the late eighteenth century","meaning":"十八世紀末","examples":[{"en":"European explorers encountered Pacific cultures in the late eighteenth century.","zh":"歐洲探險家在十八世紀末接觸太平洋文化。"},{"en":"The late eighteenth century means the later years of the 1700s.","zh":"「the late eighteenth century」意思是1700年代較後期。"},{"en":"A building from the late eighteenth century may show styles from around the 1770s to 1790s.","zh":"一座來自十八世紀末的建築可能顯示約1770至1790年代的風格。"},{"en":"Placing an event in the late eighteenth century helps readers understand its historical setting.","zh":"把事件放在十八世紀末，有助讀者理解其歷史背景。"},{"en":"The phrase gives an approximate period, not one exact year.","zh":"這個短語提供大約時期，而不是一個準確年份。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":3},{"front":"Solomon Islanders","meaning":"所羅門群島居民","examples":[{"en":"Even many Solomon Islanders regard Tikopia as very remote.","zh":"即使許多所羅門群島居民也認為 Tikopia 非常偏遠。"},{"en":"Solomon Islanders are people from the Solomon Islands in the Pacific.","zh":"「Solomon Islanders」是來自太平洋所羅門群島的人。"},{"en":"If even Solomon Islanders see Tikopia as remote, the island must feel far from main centres.","zh":"如果即使所羅門群島居民也認為 Tikopia 偏遠，該島必定感覺遠離主要中心。"},{"en":"A place can be remote even to people who already live in a region of many islands.","zh":"即使對已生活在多島地區的人來說，一個地方仍可以很偏遠。"},{"en":"The phrase helps show Tikopia’s isolation.","zh":"這個短語幫助顯示 Tikopia 的孤立。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":3},{"front":"so remote that","meaning":"偏遠得……","examples":[{"en":"Tikopia is so remote that it seems like a mythical land.","zh":"Tikopia 偏遠得像一個神話般的地方。"},{"en":"So remote that means so far away or isolated that a particular result follows.","zh":"「so remote that」意思是如此遙遠或孤立，以致產生某個結果。"},{"en":"The village is so remote that the nearest hospital is several hours away.","zh":"那條村偏遠得最近的醫院也要幾小時才到。"},{"en":"A school may be so remote that online lessons are difficult without strong internet.","zh":"一所學校可能偏遠得如果沒有穩定網絡，網上課堂會很困難。"},{"en":"This structure links extreme distance with its effect.","zh":"這個結構把極度偏遠與其影響連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":3},{"front":"a mythical land","meaning":"神話般的地方","examples":[{"en":"For many people, Tikopia seems like a mythical land.","zh":"對許多人來說，Tikopia 像一個神話般的地方。"},{"en":"A mythical land is a place that seems magical, legendary or almost unreal.","zh":"「a mythical land」是看起來神奇、傳奇或幾乎不真實的地方。"},{"en":"A mountain village hidden by clouds may feel like a mythical land to visitors.","zh":"被雲霧遮住的山村，對遊客來說可能像神話般的地方。"},{"en":"Calling a place a mythical land can show how mysterious or distant it feels.","zh":"把某地稱為神話般的地方，可以顯示它感覺多麼神秘或遙遠。"},{"en":"The phrase is imaginative, not a literal claim that the place is unreal.","zh":"這個短語富有想像力，不是字面上說該地不真實。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":3},{"front":"such as","meaning":"例如","examples":[{"en":"Tikopia seems like a mythical land, such as Narnia.","zh":"Tikopia 像一個神話般的地方，例如納尼亞。"},{"en":"Such as introduces examples of the thing just mentioned.","zh":"「such as」用來引出剛提及事物的例子。"},{"en":"Students need basic supplies such as pens, notebooks and a calculator.","zh":"學生需要基本用品，例如筆、筆記簿和計算機。"},{"en":"Using such as helps readers understand a general idea through concrete examples.","zh":"使用 such as 幫助讀者透過具體例子理解一般概念。"},{"en":"The phrase does not usually introduce a complete list.","zh":"這個短語通常不是引出完整清單。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":3},{"front":"The Chronicles of Narnia","meaning":"《納尼亞傳奇》","examples":[{"en":"Narnia appears in C. S. Lewis’s classic The Chronicles of Narnia.","zh":"納尼亞出現在 C. S. Lewis 的經典作品《納尼亞傳奇》中。"},{"en":"The Chronicles of Narnia is a famous fantasy book series by C. S. Lewis.","zh":"《納尼亞傳奇》是 C. S. Lewis 著名的奇幻系列作品。"},{"en":"A writer may mention The Chronicles of Narnia to suggest a magical or distant world.","zh":"作者可能提到《納尼亞傳奇》，以暗示一個神奇或遙遠的世界。"},{"en":"Referring to Narnia helps readers imagine Tikopia as remote and almost legendary.","zh":"提到納尼亞幫助讀者想像 Tikopia 偏遠得近乎傳奇。"},{"en":"The title is used as a cultural comparison, not as historical evidence.","zh":"這個書名被用作文化比較，而不是歷史證據。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":3},{"front":"perhaps because of this","meaning":"也許正因如此","examples":[{"en":"Perhaps because of this, Tikopia has long fascinated scholars.","zh":"也許正因如此，Tikopia 長久以來令學者着迷。"},{"en":"Perhaps because of this means maybe for the reason just mentioned.","zh":"「perhaps because of this」意思是也許由於剛才提到的原因。"},{"en":"The island is hard to reach; perhaps because of this, few tourists visit it.","zh":"這個島很難到達；也許正因如此，很少遊客到訪。"},{"en":"When a writer uses perhaps, the cause is possible but not completely certain.","zh":"當作者使用 perhaps，原因是可能的，但不是完全確定。"},{"en":"This phrase links one idea to a possible explanation.","zh":"這個短語把一個想法與可能的解釋連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":3},{"front":"has long fascinated","meaning":"長久以來令……着迷","examples":[{"en":"Tikopia has long fascinated scholars, travellers and observers.","zh":"Tikopia 長久以來令學者、旅客和觀察者着迷。"},{"en":"Has long fascinated means has attracted people’s interest for a long time.","zh":"「has long fascinated」意思是長時間吸引人們的興趣。"},{"en":"Ancient Egypt has long fascinated students because of its pyramids and writing system.","zh":"古埃及因金字塔和書寫系統，長久以來令學生着迷。"},{"en":"A remote island can long fascinate researchers when its culture seems unusual or rich.","zh":"當一個偏遠島嶼的文化看似獨特或豐富，它可以長久以來令研究人員着迷。"},{"en":"The phrase suggests deep, continuing curiosity.","zh":"這個短語暗示深刻而持續的好奇心。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":3},{"front":"scholars, travellers and casual observers","meaning":"學者、旅客和普通觀察者","examples":[{"en":"Tikopia has attracted scholars, travellers and casual observers.","zh":"Tikopia 吸引了學者、旅客和普通觀察者。"},{"en":"Scholars, travellers and casual observers are different groups of people interested in a place for different reasons.","zh":"「scholars, travellers and casual observers」是因不同原因對某地感興趣的不同人群。"},{"en":"A historic market may attract scholars, travellers and casual observers at the same time.","zh":"一個歷史街市可能同時吸引學者、旅客和普通觀察者。"},{"en":"Listing these groups shows that Tikopia interested both experts and ordinary visitors.","zh":"列出這些群體顯示 Tikopia 令專家和普通訪客都感興趣。"},{"en":"The phrase covers serious researchers as well as people simply watching or visiting.","zh":"這個短語涵蓋嚴肅研究者，也涵蓋只是觀看或到訪的人。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":3},{"front":"pioneers","meaning":"先驅","examples":[{"en":"Pioneers such as Peter Dillon wrote about Tikopia.","zh":"Peter Dillon 等先驅撰寫過關於 Tikopia 的文章。"},{"en":"Pioneers are early people who explore, study or begin work in a field before many others.","zh":"「pioneers」是在許多人之前探索、研究或開創某領域的人。"},{"en":"Early doctors who tested new treatments can be pioneers in medicine.","zh":"測試新療法的早期醫生可以是醫學先驅。"},{"en":"Pioneers often make later research possible by recording first observations.","zh":"先驅常透過記錄最初觀察，使後來研究成為可能。"},{"en":"The word suggests early effort and importance, not just travel.","zh":"這個詞暗示早期努力和重要性，而不只是旅行。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":4},{"front":"visited and wrote about","meaning":"到訪並撰寫關於……的文章","examples":[{"en":"Several pioneers visited and wrote about the island.","zh":"幾位先驅到訪並撰寫關於該島的文章。"},{"en":"Visited and wrote about means went to a place and recorded observations or experiences in writing.","zh":"「visited and wrote about」意思是到過某地，並以文字記錄觀察或經歷。"},{"en":"A travel writer visited and wrote about small villages along the coast.","zh":"一名旅遊作家到訪並撰寫關於沿岸小村莊的文章。"},{"en":"When early visitors wrote about a place, they shaped how others imagined it.","zh":"當早期訪客撰寫關於某地的文章，他們塑造了其他人如何想像該地。"},{"en":"The phrase links direct experience with written record.","zh":"這個短語把親身經驗與文字記錄連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":4},{"front":"in the nineteenth century","meaning":"在十九世紀","examples":[{"en":"Several travellers wrote about Tikopia in the nineteenth century.","zh":"幾位旅客在十九世紀撰寫過關於 Tikopia 的文章。"},{"en":"In the nineteenth century means during the years from 1801 to 1900.","zh":"「in the nineteenth century」意思是在1801年至1900年間。"},{"en":"Many railways were built in the nineteenth century.","zh":"許多鐵路在十九世紀建成。"},{"en":"Placing an event in the nineteenth century helps readers understand its historical context.","zh":"把事件放在十九世紀，有助讀者理解其歷史背景。"},{"en":"The phrase gives a broad time period rather than an exact date.","zh":"這個短語提供一個大概時期，而不是準確日期。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":4},{"front":"was captivated by","meaning":"被……深深吸引","examples":[{"en":"Raymond Firth was captivated by Tikopia’s allure.","zh":"Raymond Firth 被 Tikopia 的魅力深深吸引。"},{"en":"Was captivated by means was strongly attracted, interested or charmed by something.","zh":"「was captivated by」意思是被某事物強烈吸引、感興趣或迷住。"},{"en":"Visitors were captivated by the old town’s narrow streets and quiet temples.","zh":"遊客被舊城狹窄街道和寧靜寺廟深深吸引。"},{"en":"A researcher may be captivated by a topic and spend years studying it.","zh":"研究人員可能被某主題深深吸引，並花多年研究它。"},{"en":"The phrase suggests deep interest, not ordinary attention.","zh":"這個短語暗示深厚興趣，而不是普通注意。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":4},{"front":"Tikopia’s allure","meaning":"Tikopia 的魅力","examples":[{"en":"Raymond Firth was captivated by Tikopia’s allure.","zh":"Raymond Firth 被 Tikopia 的魅力深深吸引。"},{"en":"Tikopia’s allure means the special attraction or charm of Tikopia.","zh":"「Tikopia’s allure」指 Tikopia 特別的吸引力或魅力。"},{"en":"A quiet island may have allure because it feels distant from modern city life.","zh":"一個寧靜島嶼可能因感覺遠離現代城市生活而有魅力。"},{"en":"Tikopia’s allure drew researchers who wanted to understand its society and traditions.","zh":"Tikopia 的魅力吸引了想了解其社會和傳統的研究人員。"},{"en":"The word allure suggests a pull that is emotional as well as intellectual.","zh":"allure 這個詞暗示一種情感和知識上的吸引力。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":4},{"front":"made several trips to","meaning":"多次前往","examples":[{"en":"Firth made several trips to the island.","zh":"Firth 多次前往該島。"},{"en":"Made several trips to means visited a place more than once.","zh":"「made several trips to」意思是多於一次到訪某地。"},{"en":"A doctor made several trips to the village to check patients after the storm.","zh":"風暴後，醫生多次前往村莊檢查病人。"},{"en":"Researchers may make several trips to collect enough data over time.","zh":"研究人員可能多次前往，以隨時間收集足夠數據。"},{"en":"The phrase suggests repeated visits, not a single journey.","zh":"這個短語暗示重複到訪，而不是單次旅程。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":4},{"front":"from the 1920s onwards","meaning":"從一九二零年代起","examples":[{"en":"Firth visited Tikopia from the 1920s onwards.","zh":"Firth 從一九二零年代起到訪 Tikopia。"},{"en":"From the 1920s onwards means starting in the 1920s and continuing after that time.","zh":"「from the 1920s onwards」意思是從一九二零年代開始，並在之後延續。"},{"en":"From the 1990s onwards, many homes began using the internet.","zh":"從一九九零年代起，許多家庭開始使用互聯網。"},{"en":"If a researcher visited from the 1920s onwards, his observations may cover many years.","zh":"如果研究人員從一九二零年代起到訪，他的觀察可能涵蓋多年。"},{"en":"This phrase marks a starting period and continuation.","zh":"這個短語標示開始時期和延續。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":4},{"front":"recorded his experiences","meaning":"記錄他的經歷","examples":[{"en":"Firth recorded his experiences on Tikopia.","zh":"Firth 記錄了他在 Tikopia 的經歷。"},{"en":"Recorded his experiences means wrote down, filmed or otherwise preserved what he saw and did.","zh":"「recorded his experiences」意思是寫下、拍攝或以其他方式保存他所見所做。"},{"en":"A traveller recorded his experiences in a diary during a long journey.","zh":"一名旅客在長途旅程中用日記記錄他的經歷。"},{"en":"Recording experiences helps later readers understand what happened at the time.","zh":"記錄經歷幫助後來讀者理解當時發生的事。"},{"en":"The phrase shows that personal observation became evidence.","zh":"這個短語顯示個人觀察變成了證據。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":4},{"front":"observations and reflections","meaning":"觀察和反思","examples":[{"en":"Firth recorded his observations and reflections on Tikopia.","zh":"Firth 記錄了他對 Tikopia 的觀察和反思。"},{"en":"Observations and reflections are what someone notices and then thinks about carefully.","zh":"「observations and reflections」是某人注意到的事情，以及之後仔細思考的內容。"},{"en":"A student may write observations and reflections after visiting a museum.","zh":"學生參觀博物館後，可能寫下觀察和反思。"},{"en":"Observations give facts, while reflections explain what those facts may mean.","zh":"觀察提供事實，而反思解釋這些事實可能代表什麼。"},{"en":"The phrase combines seeing with thoughtful interpretation.","zh":"這個短語結合觀看和深思詮釋。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":4},{"front":"changes that occurred","meaning":"發生的變化","examples":[{"en":"Firth wrote about the changes that occurred on Tikopia.","zh":"Firth 撰寫了 Tikopia 發生的變化。"},{"en":"Changes that occurred are changes that happened over time.","zh":"「changes that occurred」指隨時間實際發生的變化。"},{"en":"A report may describe changes that occurred after a new school policy began.","zh":"報告可能描述新學校政策開始後發生的變化。"},{"en":"Recording changes that occurred helps researchers compare past and present life.","zh":"記錄發生的變化幫助研究人員比較過去和現在的生活。"},{"en":"The phrase focuses on actual developments, not planned changes only.","zh":"這個短語集中於實際發展，而不只是計劃中的變化。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":4},{"front":"while studying","meaning":"在研究……期間","examples":[{"en":"While studying Tikopia, Firth made observations about tattooing.","zh":"在研究 Tikopia 期間，Firth 對紋身作出觀察。"},{"en":"While studying means during the time someone is researching or learning about something.","zh":"「while studying」意思是在某人研究或學習某事物期間。"},{"en":"While studying history, students may notice links between trade and culture.","zh":"在研究歷史期間，學生可能注意到貿易與文化之間的聯繫。"},{"en":"Researchers often find unexpected details while studying a larger topic.","zh":"研究人員在研究較大主題期間，常發現意想不到的細節。"},{"en":"The phrase shows that one action happened during another activity.","zh":"這個短語顯示一個行動在另一活動期間發生。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":4},{"front":"kinship and religious life","meaning":"親屬關係和宗教生活","examples":[{"en":"Firth studied the kinship and religious life of the people of Tikopia.","zh":"Firth 研究 Tikopia 人的親屬關係和宗教生活。"},{"en":"Kinship and religious life means family relationships and practices connected with belief or worship.","zh":"「kinship and religious life」指家庭親屬關係以及與信仰或崇拜相關的做法。"},{"en":"Anthropologists may study kinship and religious life to understand how a community is organised.","zh":"人類學家可能研究親屬關係和宗教生活，以理解社群如何組織。"},{"en":"Changes in kinship and religious life can affect marriage, inheritance and rituals.","zh":"親屬關係和宗教生活的變化可以影響婚姻、繼承和儀式。"},{"en":"The phrase joins social relationships with spiritual practice.","zh":"這個短語把社會關係與精神實踐連在一起。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":5},{"front":"made a few observations about","meaning":"對……作出一些觀察","examples":[{"en":"Firth made a few observations about Tikopian tattooing.","zh":"Firth 對 Tikopia 的紋身作出一些觀察。"},{"en":"Made a few observations about means noticed and recorded some points about a topic.","zh":"「made a few observations about」意思是注意並記錄關於某主題的一些要點。"},{"en":"A teacher made a few observations about students’ common grammar mistakes.","zh":"老師對學生常犯的文法錯誤作出一些觀察。"},{"en":"Even a few observations can be useful when little information exists.","zh":"當資料很少時，即使一些觀察也可能有用。"},{"en":"The phrase suggests limited but meaningful notes.","zh":"這個短語暗示有限但有意義的筆記。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":5},{"front":"tattooing","meaning":"紋身；紋身習俗","examples":[{"en":"Firth recorded observations about tattooing in Tikopia.","zh":"Firth 記錄了關於 Tikopia 紋身習俗的觀察。"},{"en":"Tattooing is the practice of making permanent marks or designs on the skin.","zh":"「tattooing」是在皮膚上製作永久標記或圖案的做法。"},{"en":"In some cultures, tattooing can show identity, status or personal history.","zh":"在一些文化中，紋身可以顯示身份、地位或個人歷史。"},{"en":"Because tattooing can be painful, it may also show courage or endurance.","zh":"因為紋身可能痛楚，它也可以顯示勇氣或忍耐力。"},{"en":"The word can refer to both the act and the cultural practice.","zh":"這個詞可以指紋身動作，也可以指文化習俗。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":5},{"front":"brief though these notes are","meaning":"雖然這些筆記簡短","examples":[{"en":"Brief though these notes are, they are worth recording.","zh":"雖然這些筆記簡短，它們仍值得記錄。"},{"en":"Brief though these notes are means although the notes are short.","zh":"「brief though these notes are」意思是雖然這些筆記很短。"},{"en":"Brief though the report is, it gives useful information about the accident.","zh":"雖然這份報告簡短，它仍提供關於意外的有用資料。"},{"en":"Even short notes can matter if they record rare details.","zh":"如果短筆記記錄了罕見細節，它們仍可能重要。"},{"en":"This structure contrasts small size with real value.","zh":"這個結構把篇幅短與實際價值作對比。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":5},{"front":"worth recording","meaning":"值得記錄","examples":[{"en":"Firth’s notes are worth recording.","zh":"Firth 的筆記值得記錄。"},{"en":"Worth recording means important or useful enough to be written down and preserved.","zh":"「worth recording」意思是重要或有用到值得寫下並保存。"},{"en":"A patient’s unusual symptom is worth recording because it may help diagnosis later.","zh":"病人的異常症狀值得記錄，因為它日後可能幫助診斷。"},{"en":"Small cultural details are worth recording before they disappear from daily practice.","zh":"小型文化細節在從日常做法中消失前值得記錄。"},{"en":"The phrase shows that information should not be ignored.","zh":"這個短語顯示資料不應被忽視。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":5},{"front":"an indication of","meaning":"……的顯示；……的跡象","examples":[{"en":"The notes give an indication of the sociological setting of tattooing.","zh":"這些筆記顯示了紋身的社會學背景。"},{"en":"An indication of something is a sign or clue that helps show it.","zh":"「an indication of」某事，是有助顯示它的跡象或線索。"},{"en":"Empty shelves may be an indication of high demand.","zh":"空貨架可能是需求高的跡象。"},{"en":"A student’s questions can be an indication of real interest.","zh":"學生的問題可以是真正有興趣的顯示。"},{"en":"The phrase suggests evidence, but not always complete proof.","zh":"這個短語暗示證據，但不一定是完整證明。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":5},{"front":"sociological setting","meaning":"社會學背景","examples":[{"en":"The notes show the sociological setting of tattooing.","zh":"這些筆記顯示了紋身的社會學背景。"},{"en":"Sociological setting means the social conditions, relationships and roles surrounding a practice.","zh":"「sociological setting」指圍繞某種做法的社會條件、關係和角色。"},{"en":"To understand a wedding ritual, we need its sociological setting, not just the ceremony itself.","zh":"要理解婚禮儀式，我們需要其社會學背景，而不只是儀式本身。"},{"en":"The sociological setting of tattooing includes rank, gender, family and community expectations.","zh":"紋身的社會學背景包括階級、性別、家庭和社群期望。"},{"en":"This phrase asks how a practice fits into society.","zh":"這個短語關注一種做法如何融入社會。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":5},{"front":"the practice","meaning":"這種習俗；這種做法","examples":[{"en":"The practice of tattooing had social meaning in Tikopia.","zh":"紋身這種習俗在 Tikopia 具有社會意義。"},{"en":"The practice means a repeated custom, method or activity.","zh":"「the practice」指一種重複出現的習俗、方法或活動。"},{"en":"The practice of greeting elders politely teaches children respect.","zh":"向長者禮貌打招呼這種做法教孩子尊重。"},{"en":"A practice can become meaningful when a community connects it with identity or status.","zh":"當社群把一種做法與身份或地位連繫起來，它就可以變得有意義。"},{"en":"The phrase refers to what people actually do, not only what they believe.","zh":"這個短語指人們實際做的事，而不只是他們相信的事。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":5},{"front":"traditional Polynesian community","meaning":"傳統波利尼西亞社群","examples":[{"en":"Tattooing took place in a traditional Polynesian community.","zh":"紋身在一個傳統波利尼西亞社群中進行。"},{"en":"A traditional Polynesian community is a Polynesian society organised around inherited customs and social roles.","zh":"「traditional Polynesian community」指圍繞傳承習俗和社會角色組織的波利尼西亞社會。"},{"en":"In a traditional Polynesian community, rituals may guide important life stages.","zh":"在傳統波利尼西亞社群中，儀式可能引導重要人生階段。"},{"en":"Studying such a community helps researchers understand how customs worked in daily life.","zh":"研究這類社群有助研究人員理解習俗如何在日常生活中運作。"},{"en":"The phrase places tattooing inside a living social system.","zh":"這個短語把紋身放在一個活的社會系統之中。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":5},{"front":"comes from","meaning":"來自；源自","examples":[{"en":"The English word “tattoo” comes from the Tikopian word “tatau”.","zh":"英文單詞 “tattoo” 來自 Tikopia 語詞 “tatau”。"},{"en":"Comes from means has its origin in a particular place, language or source.","zh":"「comes from」意思是源自某個地方、語言或來源。"},{"en":"The word “tea” comes from languages connected with Chinese trade.","zh":"“tea” 這個詞來自與中國貿易有關的語言。"},{"en":"Knowing where a word comes from can reveal cultural contact.","zh":"知道一個詞來自哪裡，可以揭示文化接觸。"},{"en":"This phrase explains origin rather than present location.","zh":"這個短語解釋起源，而不是現在的位置。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":5},{"front":"the Tikopian word","meaning":"Tikopia 當地語詞","examples":[{"en":"The English word “tattoo” comes from a Tikopian word.","zh":"英文單詞 “tattoo” 來自一個 Tikopia 當地語詞。"},{"en":"The Tikopian word means a word from the local language of Tikopia.","zh":"「the Tikopian word」指來自 Tikopia 當地語言的詞。"},{"en":"A Tikopian word may carry cultural meanings that are difficult to translate fully.","zh":"Tikopia 當地語詞可能帶有難以完全翻譯的文化意義。"},{"en":"When English borrows a Tikopian word, it shows contact between languages.","zh":"當英文借用 Tikopia 當地語詞，這顯示語言之間有接觸。"},{"en":"This phrase identifies the language source of a term.","zh":"這個短語指出某詞的語言來源。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":5},{"front":"the general word for","meaning":"……的一般用語","examples":[{"en":"The general word for tattoo marks is “tau”.","zh":"紋身圖案的一般用語是 “tau”。"},{"en":"The general word for something is the common term used to name that type of thing.","zh":"「the general word for」某物，指用來稱呼那類事物的常用詞。"},{"en":"“Vehicle” is the general word for cars, buses and trucks.","zh":"“Vehicle” 是汽車、巴士和貨車的一般用語。"},{"en":"A general word helps people name a broad category before discussing details.","zh":"一般用語幫助人們先命名大類，再討論細節。"},{"en":"The phrase is useful when explaining vocabulary within a culture.","zh":"這個短語適合用來解釋一種文化中的詞彙。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":6},{"front":"tattoo marks","meaning":"紋身圖案；紋身痕跡","examples":[{"en":"The general word for tattoo marks is “tau”.","zh":"紋身圖案的一般用語是 “tau”。"},{"en":"Tattoo marks are the visible designs or signs made on the skin through tattooing.","zh":"「tattoo marks」是透過紋身在皮膚上形成的可見圖案或標記。"},{"en":"Tattoo marks may show family background, rank or personal experience.","zh":"紋身圖案可能顯示家庭背景、階級或個人經歷。"},{"en":"Because tattoo marks are permanent, they can carry long-term social meaning.","zh":"因為紋身痕跡是永久的，它們可以承載長期社會意義。"},{"en":"The phrase focuses on the marks themselves, not the process of making them.","zh":"這個短語集中於標記本身，而不是製作過程。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":6},{"front":"the operation of tattooing","meaning":"紋身過程；紋身操作","examples":[{"en":"The operation of tattooing is known as “ta tau”.","zh":"紋身過程被稱為 “ta tau”。"},{"en":"The operation of tattooing means the physical process of making tattoos on the skin.","zh":"「the operation of tattooing」指在皮膚上製作紋身的實際過程。"},{"en":"The operation of tattooing may involve tools, ink, pain and careful technique.","zh":"紋身過程可能涉及工具、墨水、痛楚和細緻技術。"},{"en":"If the operation of tattooing is unsafe, infection can result.","zh":"如果紋身操作不安全，可能導致感染。"},{"en":"The phrase describes the procedure, not just the final design.","zh":"這個短語描述程序，而不只是最終圖案。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":6},{"front":"is known as","meaning":"被稱為","examples":[{"en":"The operation of tattooing is known as “ta tau”.","zh":"紋身過程被稱為 “ta tau”。"},{"en":"Is known as means is called by a particular name.","zh":"「is known as」意思是被某個特定名稱稱呼。"},{"en":"Hong Kong is known as a busy international city.","zh":"香港被稱為繁忙的國際城市。"},{"en":"If a practice is known as something locally, that name may reveal cultural meaning.","zh":"如果一種習俗在本地被稱為某個名稱，那個名稱可能揭示文化意義。"},{"en":"This phrase introduces a name, title or common label.","zh":"這個短語引出名稱、稱號或常用標籤。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":6},{"front":"generic term for","meaning":"……的通稱","examples":[{"en":"“Ta” is the generic term for the act of striking.","zh":"“Ta” 是敲擊動作的通稱。"},{"en":"A generic term for something is a broad word used for a whole category.","zh":"「generic term for」某物，指用來稱呼整個類別的廣義詞。"},{"en":"“Fruit” is a generic term for apples, oranges and bananas.","zh":"“Fruit” 是蘋果、橙和香蕉的通稱。"},{"en":"A generic term helps learners understand a general idea before learning specific examples.","zh":"通稱幫助學習者先理解一般概念，再學具體例子。"},{"en":"The phrase is often used in vocabulary explanation.","zh":"這個短語常用於詞彙解釋。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":6},{"front":"the act of striking","meaning":"敲擊動作","examples":[{"en":"The word “ta” refers to the act of striking.","zh":"“ta” 這個詞指敲擊動作。"},{"en":"The act of striking means the action of hitting something with force.","zh":"「the act of striking」意思是用力量敲打某物的動作。"},{"en":"The act of striking a drum produces sound through repeated blows.","zh":"敲擊鼓的動作透過反覆擊打產生聲音。"},{"en":"In traditional tattooing, the act of striking helped push pigment into the skin.","zh":"在傳統紋身中，敲擊動作幫助把顏料推入皮膚。"},{"en":"The phrase focuses on the physical action, not the final result.","zh":"這個短語集中於實際動作，而不是最終結果。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":6},{"front":"tattooing techniques","meaning":"紋身技術","examples":[{"en":"Tattooing techniques were similar throughout Polynesia.","zh":"紋身技術在整個波利尼西亞都相似。"},{"en":"Tattooing techniques are the methods and tools used to make tattoos.","zh":"「tattooing techniques」是製作紋身所用的方法和工具。"},{"en":"A tattooing technique may involve needles, tapping, ink and careful skin preparation.","zh":"紋身技術可能涉及針、敲擊、墨水和細心準備皮膚。"},{"en":"Similar techniques across islands can suggest shared cultural knowledge.","zh":"各島相似的技術可以顯示共享的文化知識。"},{"en":"The phrase refers to how tattoos are made.","zh":"這個短語指紋身如何製作。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":6},{"front":"similar throughout","meaning":"在整個……都相似","examples":[{"en":"Tattooing techniques were similar throughout Polynesia.","zh":"紋身技術在整個波利尼西亞都相似。"},{"en":"Similar throughout a place means almost the same across the whole area.","zh":"「similar throughout」某地，意思是在整個地區都幾乎相同。"},{"en":"School uniforms may be similar throughout one education system.","zh":"校服在一個教育系統中可能都相似。"},{"en":"If customs are similar throughout a region, people may share a common tradition.","zh":"如果習俗在整個地區都相似，人們可能共享共同傳統。"},{"en":"The phrase highlights consistency across many places.","zh":"這個短語強調多個地方之間的一致性。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":6},{"front":"traditional tattoo artists","meaning":"傳統紋身師","examples":[{"en":"Traditional tattoo artists created indelible tattoos.","zh":"傳統紋身師製作不可消除的紋身。"},{"en":"Traditional tattoo artists are skilled people who make tattoos using inherited methods and tools.","zh":"「traditional tattoo artists」是使用傳承方法和工具製作紋身的熟練人士。"},{"en":"Traditional tattoo artists may learn their craft from elders or experienced masters.","zh":"傳統紋身師可能從長者或有經驗的師傅學習技藝。"},{"en":"Their work can preserve cultural patterns, symbols and techniques.","zh":"他們的工作可以保存文化圖案、象徵和技術。"},{"en":"The phrase highlights both artistic skill and cultural knowledge.","zh":"這個短語強調藝術技能和文化知識。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":6},{"front":"indelible tattoos","meaning":"不可消除的紋身","examples":[{"en":"Traditional tattoo artists created indelible tattoos.","zh":"傳統紋身師製作不可消除的紋身。"},{"en":"Indelible tattoos are tattoos that cannot easily be removed or erased.","zh":"「indelible tattoos」是不能輕易移除或抹去的紋身。"},{"en":"A permanent mark on official records can be described as indelible in a figurative sense.","zh":"官方記錄上的永久標記，也可以比喻地被描述為 indelible。"},{"en":"Because indelible tattoos remain for life, they can carry serious social meaning.","zh":"因為不可消除的紋身會留存一生，它們可以承載嚴肅社會意義。"},{"en":"The word indelible emphasises permanence.","zh":"indelible 這個詞強調永久性。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":6},{"front":"pigment made from","meaning":"由……製成的顏料","examples":[{"en":"The artists used pigment made from the candlenut.","zh":"紋身師使用由石栗製成的顏料。"},{"en":"Pigment made from something is colouring material produced from that source.","zh":"「pigment made from」某物，指由該來源製成的着色材料。"},{"en":"Paint can use pigment made from minerals, plants or charcoal.","zh":"顏料可以使用由礦物、植物或木炭製成的色料。"},{"en":"If pigment is made from burnt material, it may produce a dark colour.","zh":"如果顏料由燃燒過的材料製成，它可能產生深色。"},{"en":"The phrase explains the material origin of the colour.","zh":"這個短語解釋顏色材料的來源。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":6},{"front":"candlenut","meaning":"石栗","examples":[{"en":"Traditional tattoo pigment was made from the candlenut.","zh":"傳統紋身顏料由石栗製成。"},{"en":"Candlenut is a type of nut whose oil or burned soot can be used in traditional practices.","zh":"「candlenut」是一種堅果，其油或燃燒後的煙灰可用於傳統做法。"},{"en":"A traditional craft may use candlenut soot to make dark pigment.","zh":"傳統工藝可能使用石栗煙灰製作深色顏料。"},{"en":"Because candlenut can produce useful soot, it was suitable for tattoo pigment.","zh":"因為石栗可以產生有用煙灰，所以適合用作紋身顏料。"},{"en":"The word names the plant source of the pigment.","zh":"這個詞指出顏料的植物來源。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":7},{"front":"kukui nut","meaning":"kukui 果；石栗","examples":[{"en":"The candlenut is also known as the kukui nut.","zh":"石栗也被稱為 kukui 果。"},{"en":"Kukui nut is another name for the candlenut.","zh":"「kukui nut」是 candlenut 的另一個名稱。"},{"en":"A plant may have different names in different languages or regions.","zh":"一種植物在不同語言或地區可能有不同名稱。"},{"en":"Knowing that kukui nut and candlenut refer to the same thing prevents confusion.","zh":"知道 kukui nut 和 candlenut 指同一事物，可以避免混淆。"},{"en":"The phrase introduces an alternative name.","zh":"這個短語引入另一個名稱。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":7},{"front":"coconut shell","meaning":"椰殼","examples":[{"en":"The nut was burned in a bowl made from a coconut shell.","zh":"這種果仁在由椰殼製成的碗中燃燒。"},{"en":"A coconut shell is the hard outer covering of a coconut.","zh":"「coconut shell」是椰子的堅硬外殼。"},{"en":"Coconut shells can be used as bowls, cups or fuel in island communities.","zh":"在島嶼社群中，椰殼可以用作碗、杯或燃料。"},{"en":"Using a coconut shell shows how people made practical tools from local materials.","zh":"使用椰殼顯示人們如何用本地材料製作實用工具。"},{"en":"The phrase names the natural container used in the process.","zh":"這個短語指出過程中使用的天然容器。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":7},{"front":"scraped out the soot","meaning":"刮出煙灰","examples":[{"en":"The artists scraped out the soot after burning the nut.","zh":"紋身師在燃燒果仁後刮出煙灰。"},{"en":"Scraped out the soot means removed the black powder left after burning something.","zh":"「scraped out the soot」意思是刮出燃燒後留下的黑色粉末。"},{"en":"A cook may scrape out burnt bits from a pan before washing it.","zh":"廚師可能在清洗鍋之前刮出燒焦碎屑。"},{"en":"Scraping out soot allowed tattoo artists to collect material for pigment.","zh":"刮出煙灰讓紋身師收集製作顏料的材料。"},{"en":"The phrase describes a careful removal action.","zh":"這個短語描述一個仔細移除的動作。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":7},{"front":"used a pestle to","meaning":"用杵去……","examples":[{"en":"They used a pestle to mix the soot with liquid.","zh":"他們用杵把煙灰與液體混合。"},{"en":"Used a pestle to means used a heavy grinding tool to crush or mix something.","zh":"「used a pestle to」意思是使用一種沉重的研磨工具來壓碎或混合某物。"},{"en":"A cook used a pestle to crush garlic in a mortar.","zh":"廚師用杵在臼中壓碎蒜頭。"},{"en":"Using a pestle can turn dry material into a smoother mixture.","zh":"使用杵可以把乾材料變成更順滑的混合物。"},{"en":"The phrase explains the tool used to prepare the substance.","zh":"這個短語解釋準備物質時使用的工具。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":7},{"front":"mix it with liquid","meaning":"把它與液體混合","examples":[{"en":"The soot was mixed with liquid to make pigment.","zh":"煙灰與液體混合以製成顏料。"},{"en":"To mix it with liquid means to combine a substance with a fluid.","zh":"「mix it with liquid」意思是把某種物質與液體結合。"},{"en":"A student may mix powder with liquid to make paint for an art project.","zh":"學生可能把粉末與液體混合，為藝術項目製作顏料。"},{"en":"Mixing soot with liquid changes it into a usable pigment.","zh":"把煙灰與液體混合，會把它變成可使用的顏料。"},{"en":"The phrase describes turning a dry material into a workable mixture.","zh":"這個短語描述把乾材料變成可操作混合物的過程。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":7},{"front":"bluing","meaning":"藍色劑","examples":[{"en":"Bluing was sometimes added to the pigment.","zh":"藍色劑有時會加入顏料中。"},{"en":"Bluing is a blue colouring substance used to adjust or correct colour.","zh":"「bluing」是一種藍色着色物質，用來調整或修正顏色。"},{"en":"A small amount of bluing can make a colour look cooler or darker.","zh":"少量藍色劑可以令顏色看起來較冷或較深。"},{"en":"Adding bluing to pigment can change how a design appears on skin or cloth.","zh":"在顏料中加入藍色劑，可以改變圖案在皮膚或布料上的效果。"},{"en":"The word names an added colouring material.","zh":"這個詞指一種加入的着色材料。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":7},{"front":"added to counteract","meaning":"加入以抵銷……","examples":[{"en":"Bluing was added to counteract the reddish hue.","zh":"藍色劑被加入以抵銷泛紅色調。"},{"en":"Added to counteract means put in to reduce or balance an unwanted effect.","zh":"「added to counteract」意思是加入某物，以減少或平衡不想要的效果。"},{"en":"Lemon may be added to counteract the sweetness of a dessert.","zh":"檸檬可以加入甜品中，以抵銷甜味。"},{"en":"If one colour is too warm, another colour can be added to counteract it.","zh":"如果一種顏色太暖，可以加入另一種顏色來抵銷。"},{"en":"The phrase shows purpose: something is added to correct a problem.","zh":"這個短語顯示目的：加入某物是為了修正問題。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":7},{"front":"reddish hue","meaning":"泛紅色調","examples":[{"en":"Bluing helped counteract the reddish hue of the pigment.","zh":"藍色劑幫助抵銷顏料的泛紅色調。"},{"en":"A reddish hue is a slight red colour or tint.","zh":"「reddish hue」是略帶紅色的色調。"},{"en":"The sky had a reddish hue just before sunset.","zh":"日落前，天空帶有泛紅色調。"},{"en":"If a pigment has a reddish hue, adding another colour may make it look darker or more neutral.","zh":"如果顏料有泛紅色調，加入另一種顏色可能令它看起來更深或更中性。"},{"en":"Hue refers to colour, not brightness alone.","zh":"hue 指顏色，而不只是亮度。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":7},{"front":"carbon-based pigment","meaning":"碳基顏料","examples":[{"en":"The pigment was carbon-based.","zh":"這種顏料是碳基顏料。"},{"en":"Carbon-based pigment is colouring material made mainly from carbon-rich substances such as soot or charcoal.","zh":"「carbon-based pigment」是主要由煙灰或木炭等富含碳的物質製成的着色材料。"},{"en":"Artists have used carbon-based pigment to make black marks for thousands of years.","zh":"藝術家數千年來使用碳基顏料製作黑色標記。"},{"en":"Because carbon-based pigment is dark, it can create clear outlines.","zh":"因為碳基顏料顏色深，它可以形成清晰輪廓。"},{"en":"The phrase explains the chemical nature of the colour material.","zh":"這個短語解釋色料的化學性質。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":7},{"front":"made the outlines bolder","meaning":"令輪廓線更粗更明顯","examples":[{"en":"Bluing made the outlines of the designs bolder.","zh":"藍色劑令圖案的輪廓線更粗更明顯。"},{"en":"Made the outlines bolder means made the edges or lines look thicker, darker or clearer.","zh":"「made the outlines bolder」意思是令邊緣或線條看起來更粗、更深或更清楚。"},{"en":"A teacher may make the outlines bolder on a diagram so students can see them easily.","zh":"老師可能把圖表的輪廓線加粗，讓學生容易看見。"},{"en":"Darker ink can make outlines bolder and help a design stand out.","zh":"較深墨水可以令輪廓線更明顯，幫助圖案突出。"},{"en":"The phrase describes a visual improvement in clarity.","zh":"這個短語描述視覺清晰度的改善。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":7},{"front":"inscribed designs","meaning":"刻畫的圖案","examples":[{"en":"The outlines of the inscribed designs became bolder.","zh":"刻畫圖案的輪廓線變得更粗更明顯。"},{"en":"Inscribed designs are patterns cut, marked or written onto a surface.","zh":"「inscribed designs」是在表面上刻下、標記或寫上的圖案。"},{"en":"Inscribed designs on stone may remain visible for many years.","zh":"石頭上的刻畫圖案可能多年後仍然可見。"},{"en":"If inscribed designs are too faint, researchers may need special lighting to read them.","zh":"如果刻畫的圖案太淡，研究人員可能需要特殊燈光來辨認。"},{"en":"The phrase focuses on designs physically marked into a material.","zh":"這個短語集中於實際標記在材料上的圖案。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":8},{"front":"subjects’ dark skin","meaning":"受紋身者的深色皮膚","examples":[{"en":"The designs stood out on the subjects’ dark skin.","zh":"這些圖案在受紋身者的深色皮膚上顯得突出。"},{"en":"Subjects’ dark skin means the dark skin of the people receiving the tattoos.","zh":"「subjects’ dark skin」指接受紋身的人那深色的皮膚。"},{"en":"A colour that stands out on dark skin can make a design easier to see.","zh":"在深色皮膚上突出的顏色，可以令圖案較容易看見。"},{"en":"Tattoo artists may choose pigment carefully so it appears clearly on the subject’s skin.","zh":"紋身師可能仔細選擇顏料，使它在受紋身者皮膚上清楚呈現。"},{"en":"The phrase identifies the people being tattooed as the subjects of the work.","zh":"這個短語把接受紋身的人標示為作品的對象。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":8},{"front":"tattooing specialists","meaning":"紋身專家","examples":[{"en":"Tattooing specialists used chisels made from bone.","zh":"紋身專家使用由骨頭製成的鑿子。"},{"en":"Tattooing specialists are people with special skill and knowledge in making tattoos.","zh":"「tattooing specialists」是具備製作紋身專門技能和知識的人。"},{"en":"A tattooing specialist may know which tools create different lines or patterns.","zh":"紋身專家可能知道哪些工具能製作不同線條或圖案。"},{"en":"Because the process was difficult and painful, specialists were needed to do it properly.","zh":"因為過程困難而痛楚，所以需要專家妥善完成。"},{"en":"The phrase emphasises expertise rather than casual practice.","zh":"這個短語強調專業知識，而不是隨意做法。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":8},{"front":"a range of chisels","meaning":"一系列鑿子","examples":[{"en":"Tattooing specialists used a range of chisels.","zh":"紋身專家使用一系列鑿子。"},{"en":"A range of chisels means several different chisels used for different purposes.","zh":"「a range of chisels」指用於不同目的的幾種不同鑿子。"},{"en":"A carpenter keeps a range of chisels for cutting lines of different sizes.","zh":"木匠會保留一系列鑿子，以切割不同大小的線條。"},{"en":"Using a range of chisels allows an artist to create both fine and broad marks.","zh":"使用一系列鑿子讓藝術家能製作細線和粗線。"},{"en":"The phrase suggests variety in tools.","zh":"這個短語暗示工具種類多樣。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":8},{"front":"albatross wing bone","meaning":"信天翁翼骨","examples":[{"en":"The chisels were made from albatross wing bone.","zh":"這些鑿子由信天翁翼骨製成。"},{"en":"Albatross wing bone is bone from the wing of an albatross bird.","zh":"「albatross wing bone」是信天翁翅膀中的骨頭。"},{"en":"Traditional tools were often made from local animal bones, wood or shells.","zh":"傳統工具常由本地動物骨頭、木材或貝殼製成。"},{"en":"If a chisel was made from wing bone, it had to be shaped carefully before use.","zh":"如果鑿子由翼骨製成，使用前必須仔細塑形。"},{"en":"The phrase identifies the material used to make the tattooing tool.","zh":"這個短語指出製作紋身工具的材料。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":8},{"front":"hafted onto a handle","meaning":"裝上手柄","examples":[{"en":"The chisels were hafted onto a handle.","zh":"這些鑿子被裝上手柄。"},{"en":"Hafted onto a handle means attached firmly to a handle so the tool can be held and used.","zh":"「hafted onto a handle」意思是牢固地裝到手柄上，使工具可以被握住和使用。"},{"en":"A stone blade can be hafted onto a wooden handle to make a knife.","zh":"石刀片可以裝到木柄上，製成刀。"},{"en":"If a tool is not hafted securely, it may slip during use.","zh":"如果工具沒有牢固裝上手柄，使用時可能滑落。"},{"en":"The phrase describes how a tool head is joined to its handle.","zh":"這個短語描述工具頭如何接到手柄上。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":8},{"front":"heartwood of a bush","meaning":"灌木的心材","examples":[{"en":"The handle was made from the heartwood of a bush.","zh":"手柄由灌木的心材製成。"},{"en":"Heartwood of a bush is the dense inner wood from a woody plant.","zh":"「heartwood of a bush」是灌木這類木本植物較密實的內層木材。"},{"en":"Craftspeople may choose heartwood because it is stronger than softer outer wood.","zh":"工匠可能選擇心材，因為它比較軟的外層木更堅硬。"},{"en":"A handle made from heartwood can be more durable during repeated striking.","zh":"由心材製成的手柄在反覆敲擊時可以更耐用。"},{"en":"The phrase identifies a specific natural material used in tool-making.","zh":"這個短語指出製作工具時使用的特定天然材料。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":8},{"front":"struck with a mallet","meaning":"用木槌敲打","examples":[{"en":"The chisel was struck with a mallet.","zh":"鑿子用木槌敲打。"},{"en":"Struck with a mallet means hit with a wooden or heavy hammer-like tool.","zh":"「struck with a mallet」意思是用木製或重型錘狀工具敲打。"},{"en":"A sculptor may strike a chisel with a mallet to shape stone.","zh":"雕刻家可能用木槌敲打鑿子來塑造石頭。"},{"en":"In tattooing, striking the chisel helped push pigment into the skin.","zh":"在紋身中，敲打鑿子幫助把顏料推入皮膚。"},{"en":"The phrase describes controlled hitting, not random violence.","zh":"這個短語描述受控敲擊，而不是隨意暴力。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":8},{"front":"began by sketching","meaning":"先畫出草圖","examples":[{"en":"The tattooer began by sketching a design in charcoal.","zh":"紋身師先用木炭畫出圖案草圖。"},{"en":"Began by sketching means started the process by drawing a rough outline.","zh":"「began by sketching」意思是以畫出粗略輪廓作為過程的開始。"},{"en":"An artist may begin by sketching the main shapes before painting.","zh":"藝術家可能在繪畫前先畫出主要形狀草圖。"},{"en":"Sketching first helps prevent mistakes when the final mark is permanent.","zh":"先畫草圖有助避免錯誤，尤其當最終標記是永久的。"},{"en":"The phrase shows the first step in a careful process.","zh":"這個短語顯示仔細過程的第一步。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":8},{"front":"a design in charcoal","meaning":"用木炭畫出的圖案","examples":[{"en":"The tattooer sketched a design in charcoal.","zh":"紋身師用木炭畫出圖案。"},{"en":"A design in charcoal is a drawing made using black charcoal.","zh":"「a design in charcoal」是用黑色木炭畫出的圖案。"},{"en":"Art students often make a design in charcoal before using paint.","zh":"藝術學生常在上色前用木炭畫出圖案。"},{"en":"A charcoal design can be adjusted before the permanent work begins.","zh":"木炭圖案可以在永久工作開始前作出調整。"},{"en":"The phrase describes both the drawing and the material used.","zh":"這個短語同時描述圖案和使用的材料。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":8},{"front":"supine subject","meaning":"仰臥的受紋身者","examples":[{"en":"The tattooer worked on a supine subject.","zh":"紋身師在仰臥的受紋身者身上工作。"},{"en":"A supine subject is a person lying face upward while receiving treatment or work.","zh":"「supine subject」是接受治療或處理時面朝上躺着的人。"},{"en":"A patient may be supine during a medical examination.","zh":"病人在醫學檢查期間可能仰臥。"},{"en":"A supine position can help the worker reach the skin more steadily.","zh":"仰臥姿勢可以幫助操作者更穩定地接觸皮膚。"},{"en":"The phrase describes the body position of the person being worked on.","zh":"這個短語描述接受處理者的身體姿勢。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":8},{"front":"stretched taut","meaning":"拉緊","examples":[{"en":"The subject’s skin was stretched taut by apprentices.","zh":"受紋身者的皮膚由學徒拉緊。"},{"en":"Stretched taut means pulled tight so that there is little looseness.","zh":"「stretched taut」意思是拉得緊，使其幾乎沒有鬆弛。"},{"en":"A drum skin must be stretched taut to produce a clear sound.","zh":"鼓皮必須拉緊，才能發出清晰聲音。"},{"en":"Skin stretched taut is easier to mark evenly during tattooing.","zh":"拉緊的皮膚在紋身時較容易被均勻標記。"},{"en":"The phrase describes controlled tension on a surface.","zh":"這個短語描述表面受到控制的張力。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":9},{"front":"one or more apprentices","meaning":"一名或多名學徒","examples":[{"en":"One or more apprentices helped the tattooer.","zh":"一名或多名學徒協助紋身師。"},{"en":"One or more apprentices means at least one trainee, and possibly several, assisted the expert.","zh":"「one or more apprentices」意思是至少一名受訓者，也可能有幾名，協助專家。"},{"en":"A chef may have one or more apprentices helping prepare ingredients.","zh":"廚師可能有一名或多名學徒協助準備食材。"},{"en":"Apprentices can learn by assisting skilled workers during real tasks.","zh":"學徒可以透過在真實工作中協助熟練工人來學習。"},{"en":"The phrase shows that the work involved support and training.","zh":"這個短語顯示工作涉及支援和訓練。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":9},{"front":"dipped the appropriate points into","meaning":"把合適尖端蘸入……","examples":[{"en":"The tattooer dipped the appropriate points into the ink.","zh":"紋身師把合適尖端蘸入墨水。"},{"en":"Dipped the appropriate points into means put the correct tips briefly into a liquid.","zh":"「dipped the appropriate points into」意思是把正確的尖端短暫放入液體中。"},{"en":"A painter dipped the brush tip into blue paint before drawing the sky.","zh":"畫家把畫筆尖端蘸入藍色顏料，再畫天空。"},{"en":"Choosing the appropriate points helped the tattooer make the right line or pattern.","zh":"選擇合適尖端幫助紋身師製作正確線條或圖案。"},{"en":"The phrase describes careful tool preparation before use.","zh":"這個短語描述使用前仔細準備工具。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":9},{"front":"a single point","meaning":"單一尖端","examples":[{"en":"The tattooer could use either a single point or a whole comb.","zh":"紋身師可以使用單一尖端或整排梳狀針。"},{"en":"A single point means one sharp tip rather than several points together.","zh":"「a single point」指一個尖銳尖端，而不是幾個尖端合在一起。"},{"en":"A pen uses a single point to make a thin controlled line.","zh":"筆使用單一尖端來畫出細而受控的線條。"},{"en":"In tattooing, a single point may be useful for fine details.","zh":"在紋身中，單一尖端可能適合細節。"},{"en":"The phrase contrasts one tip with a multi-point tool.","zh":"這個短語把一個尖端與多尖端工具作對比。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":9},{"front":"a whole comb","meaning":"整排梳狀針","examples":[{"en":"The tattooer sometimes used a whole comb.","zh":"紋身師有時使用整排梳狀針。"},{"en":"A whole comb means a complete row of points used together.","zh":"「a whole comb」指一整排一起使用的尖端。"},{"en":"A whole comb can create repeated marks more quickly than a single point.","zh":"整排梳狀針可以比單一尖端更快製作重複標記。"},{"en":"If a pattern needs parallel lines, a whole comb may save time.","zh":"如果圖案需要平行線，整排梳狀針可能節省時間。"},{"en":"The phrase describes a multi-point tattooing tool.","zh":"這個短語描述一種多尖端紋身工具。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":9},{"front":"held in a coconut-shell cup","meaning":"盛於椰殼杯中","examples":[{"en":"The ink was usually held in a coconut-shell cup.","zh":"墨水通常盛於椰殼杯中。"},{"en":"Held in a coconut-shell cup means kept inside a cup made from a coconut shell.","zh":"「held in a coconut-shell cup」意思是保存在由椰殼製成的杯中。"},{"en":"A small amount of dye can be held in a bowl while an artist works.","zh":"藝術家工作時，少量染料可以盛在碗中。"},{"en":"Using a coconut-shell cup shows how local materials served practical needs.","zh":"使用椰殼杯顯示本地材料如何滿足實際需要。"},{"en":"The phrase describes the container for the ink.","zh":"這個短語描述墨水的容器。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":9},{"front":"tapped them into","meaning":"把它們敲入……","examples":[{"en":"The tattooer tapped the points into the subject’s skin.","zh":"紋身師把尖端敲入受紋身者的皮膚。"},{"en":"Tapped them into means hit them lightly and repeatedly so they enter a surface.","zh":"「tapped them into」意思是輕而反覆地敲打，使它們進入表面。"},{"en":"A worker tapped small nails into the wooden frame.","zh":"工人把小釘子敲入木框。"},{"en":"In traditional tattooing, points were tapped into the skin to place pigment below the surface.","zh":"在傳統紋身中，尖端被敲入皮膚，把顏料置於表面以下。"},{"en":"The phrase describes repeated controlled striking.","zh":"這個短語描述反覆而受控的敲擊。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":9},{"front":"blood trickling from","meaning":"從……滲出的血","examples":[{"en":"Blood trickling from the punctures was wiped away.","zh":"從刺孔滲出的血被抹去。"},{"en":"Blood trickling from somewhere means blood flowing slowly from that place.","zh":"「blood trickling from」某處，意思是血從那裡慢慢流出。"},{"en":"Blood trickling from a small cut should be cleaned with care.","zh":"從小傷口滲出的血應小心清理。"},{"en":"If blood trickles from punctures during tattooing, the worker may wipe it away to see clearly.","zh":"如果紋身時血從刺孔滲出，操作者可能會把它抹去以看清楚。"},{"en":"Trickling suggests a slow flow, not a sudden burst.","zh":"trickling 暗示慢慢流動，而不是突然大量湧出。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":9},{"front":"punctures","meaning":"刺孔","examples":[{"en":"Blood came from the punctures in the skin.","zh":"血從皮膚上的刺孔流出。"},{"en":"Punctures are small holes made by a sharp object.","zh":"「punctures」是由尖銳物件造成的小孔。"},{"en":"A tyre may lose air if it has several punctures.","zh":"如果輪胎有幾個刺孔，它可能漏氣。"},{"en":"In tattooing, punctures allow pigment to enter the skin.","zh":"在紋身中，刺孔讓顏料進入皮膚。"},{"en":"The word focuses on the small holes, not the tool itself.","zh":"這個詞集中於小孔，而不是工具本身。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":9},{"front":"wiped away","meaning":"抹去","examples":[{"en":"The blood was wiped away by the tattooer or an apprentice.","zh":"血由紋身師或學徒抹去。"},{"en":"Wiped away means removed by rubbing with a cloth, hand or tool.","zh":"「wiped away」意思是用布、手或工具擦走。"},{"en":"A nurse wiped away sweat from the patient’s forehead.","zh":"護士抹去病人額頭上的汗。"},{"en":"Wiping away blood helped the tattooer keep the design visible.","zh":"抹去血液幫助紋身師保持圖案清晰可見。"},{"en":"The phrase describes cleaning a surface after something appears there.","zh":"這個短語描述某物出現在表面後把它清理走。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":9},{"front":"restrained","meaning":"按住；制止","examples":[{"en":"The apprentice restrained the subject from moving.","zh":"學徒按住受紋身者，防止他移動。"},{"en":"Restrained means held back or prevented from moving freely.","zh":"「restrained」意思是按住或阻止自由移動。"},{"en":"A nurse may restrain a patient gently if sudden movement could cause injury.","zh":"如果突然移動可能造成受傷，護士可能輕輕按住病人。"},{"en":"During a painful procedure, restraint may be used to keep the work accurate.","zh":"在痛楚程序中，按住身體可能用來保持工作準確。"},{"en":"The word can describe physical control or emotional self-control.","zh":"這個詞可以描述身體控制，也可以描述情緒克制。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":9},{"front":"pain-wracked subject","meaning":"因痛楚而受折磨的人","examples":[{"en":"The apprentice restrained the pain-wracked subject.","zh":"學徒按住那名因痛楚而受折磨的受紋身者。"},{"en":"A pain-wracked subject is a person suffering intense pain during a process.","zh":"「pain-wracked subject」是指在某個過程中承受強烈痛楚的人。"},{"en":"A patient with a broken leg may be pain-wracked before receiving treatment.","zh":"腿骨骨折的病人在接受治療前可能因痛楚而受折磨。"},{"en":"If the subject is pain-wracked, helpers may need to prevent sudden movement.","zh":"如果受紋身者因痛楚而受折磨，助手可能需要防止他突然移動。"},{"en":"The phrase strongly emphasises physical suffering.","zh":"這個短語強烈強調身體痛苦。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":10},{"front":"inevitably painful","meaning":"必然痛苦的","examples":[{"en":"The operation was inevitably painful.","zh":"這個過程必然痛苦。"},{"en":"Inevitably painful means certain to cause pain and difficult to avoid.","zh":"「inevitably painful」意思是一定會造成痛楚，而且難以避免。"},{"en":"A dental operation without enough anaesthetic would be inevitably painful.","zh":"如果牙科手術沒有足夠麻醉，便會必然痛苦。"},{"en":"Traditional tattooing was inevitably painful because sharp points entered the skin repeatedly.","zh":"傳統紋身必然痛苦，因為尖端反覆進入皮膚。"},{"en":"The word inevitably shows that pain was expected, not accidental.","zh":"inevitably 這個詞顯示痛楚是預期中的，而不是意外。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":10},{"front":"a test of fortitude","meaning":"意志力的考驗","examples":[{"en":"Tattooing was a test of fortitude.","zh":"紋身是意志力的考驗。"},{"en":"A test of fortitude is a difficult experience that shows a person’s courage and endurance.","zh":"「a test of fortitude」是顯示一個人勇氣和忍耐力的艱難經歷。"},{"en":"Finishing a marathon in bad weather can be a test of fortitude.","zh":"在惡劣天氣中完成馬拉松，可以是意志力的考驗。"},{"en":"Painful tattooing tested whether a person could endure suffering without giving up.","zh":"痛楚的紋身過程考驗一個人能否忍受痛苦而不放棄。"},{"en":"The phrase connects hardship with inner strength.","zh":"這個短語把艱辛與內在力量連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":10},{"front":"sought to shorten","meaning":"試圖縮短","examples":[{"en":"Tattooers sought to shorten the painful operation.","zh":"紋身師試圖縮短痛苦的過程。"},{"en":"Sought to shorten means tried to make something take less time.","zh":"「sought to shorten」意思是試圖令某事花較少時間。"},{"en":"The school sought to shorten waiting time at lunch by opening more counters.","zh":"學校透過開更多櫃位，試圖縮短午餐輪候時間。"},{"en":"If a process is painful, workers may seek to shorten it for the person receiving it.","zh":"如果一個過程很痛苦，操作者可能試圖為接受者縮短它。"},{"en":"The phrase shows intention and effort.","zh":"這個短語顯示意圖和努力。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":10},{"front":"working as quickly as possible","meaning":"盡快工作","examples":[{"en":"Tattooers worked as quickly as possible.","zh":"紋身師盡快工作。"},{"en":"Working as quickly as possible means doing a task at the fastest safe or practical speed.","zh":"「working as quickly as possible」意思是以最快而安全或實際可行的速度完成任務。"},{"en":"Nurses worked as quickly as possible when many patients arrived at once.","zh":"當許多病人同時到達，護士盡快工作。"},{"en":"If a task causes pain, working quickly can reduce the time someone suffers.","zh":"如果一項任務造成痛楚，快速工作可以減少別人受苦的時間。"},{"en":"The phrase suggests urgency but not necessarily carelessness.","zh":"這個短語暗示緊迫，但不一定是粗心。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":10},{"front":"nearly always festered","meaning":"幾乎總會化膿","examples":[{"en":"Tattoos nearly always festered after the operation.","zh":"紋身在過程後幾乎總會化膿。"},{"en":"Nearly always festered means almost always became infected or filled with pus.","zh":"「nearly always festered」意思是幾乎總是感染或充滿膿液。"},{"en":"A dirty wound may fester if it is not cleaned properly.","zh":"如果骯髒傷口沒有妥善清潔，可能會化膿。"},{"en":"If tattoos nearly always festered, sickness would be a common risk.","zh":"如果紋身幾乎總會化膿，疾病便會是常見風險。"},{"en":"The phrase shows that infection was expected in most cases.","zh":"這個短語顯示感染在大多數情況下是可預期的。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":10},{"front":"led to sickness","meaning":"導致疾病","examples":[{"en":"Tattoos often led to sickness.","zh":"紋身常導致疾病。"},{"en":"Led to sickness means caused illness or made people become unwell.","zh":"「led to sickness」意思是造成疾病或令人不適。"},{"en":"Dirty drinking water can lead to sickness in a whole village.","zh":"骯髒飲用水可以導致整條村的人生病。"},{"en":"If a wound becomes infected, it may lead to sickness.","zh":"如果傷口受感染，它可能導致疾病。"},{"en":"The phrase shows a cause-and-effect relationship.","zh":"這個短語顯示因果關係。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":10},{"front":"in some cases","meaning":"在某些情況下","examples":[{"en":"In some cases, tattooing led to death.","zh":"在某些情況下，紋身導致死亡。"},{"en":"In some cases means in certain situations, but not all situations.","zh":"「in some cases」意思是在某些情況中，但不是所有情況。"},{"en":"In some cases, a headache is caused by lack of sleep.","zh":"在某些情況下，頭痛是由睡眠不足造成的。"},{"en":"Using in some cases prevents a statement from sounding too absolute.","zh":"使用 in some cases 可以避免陳述聽起來過於絕對。"},{"en":"The phrase introduces an exception or limited example.","zh":"這個短語引出例外或有限例子。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":10},{"front":"ancient Polynesian society","meaning":"古代波利尼西亞社會","examples":[{"en":"In ancient Polynesian society, nearly everyone was tattooed.","zh":"在古代波利尼西亞社會中，幾乎每個人都有紋身。"},{"en":"Ancient Polynesian society means Polynesian communities and social life in the distant past.","zh":"「ancient Polynesian society」指遙遠過去的波利尼西亞社群和社會生活。"},{"en":"Ancient Polynesian society included family ranks, rituals, oral traditions and island economies.","zh":"古代波利尼西亞社會包括家庭階級、儀式、口述傳統和島嶼經濟。"},{"en":"Studying ancient Polynesian society helps explain why tattooing had social importance.","zh":"研究古代波利尼西亞社會有助解釋為何紋身具有社會重要性。"},{"en":"The phrase places the practice in a historical community.","zh":"這個短語把這種習俗放在歷史社群之中。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":10},{"front":"nearly everyone was tattooed","meaning":"幾乎每個人都有紋身","examples":[{"en":"In ancient Polynesian society, nearly everyone was tattooed.","zh":"在古代波利尼西亞社會中，幾乎每個人都有紋身。"},{"en":"Nearly everyone was tattooed means almost all people had tattoos.","zh":"「nearly everyone was tattooed」意思是幾乎所有人都有紋身。"},{"en":"If nearly everyone in a group follows a custom, that custom is probably socially important.","zh":"如果一個群體中幾乎每個人都遵循某習俗，該習俗很可能有社會重要性。"},{"en":"In a school where nearly everyone wears uniform, clothing becomes part of group identity.","zh":"在幾乎每個人都穿校服的學校中，服裝成為群體身份的一部分。"},{"en":"The phrase shows that tattooing was common, not rare.","zh":"這個短語顯示紋身很常見，而不是罕見。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":10},{"front":"an integral part of","meaning":"……不可或缺的一部分","examples":[{"en":"Tattooing was an integral part of the culture.","zh":"紋身是該文化不可或缺的一部分。"},{"en":"An integral part of something is an essential part that helps make it complete.","zh":"「an integral part of」某事，是使其完整的重要必要部分。"},{"en":"Homework is an integral part of learning because it gives students practice.","zh":"功課是學習不可或缺的一部分，因為它給學生練習。"},{"en":"If a ritual is an integral part of a culture, removing it may change social meaning.","zh":"如果一種儀式是某文化不可或缺的一部分，移除它可能改變社會意義。"},{"en":"The phrase means necessary and deeply connected, not simply added on.","zh":"這個短語意思是必要且深度相連，而不只是附加。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":10},{"front":"much more than","meaning":"遠不止是……","examples":[{"en":"Tattooing was much more than bodily ornamentation.","zh":"紋身遠不止是身體裝飾。"},{"en":"Much more than means far beyond or more important than the thing mentioned.","zh":"「much more than」意思是遠超過或比所提事物更重要。"},{"en":"A school is much more than a building; it is a community for learning.","zh":"學校遠不止是一座建築；它是學習社群。"},{"en":"When something is much more than decoration, it may carry identity or status.","zh":"當某物遠不止是裝飾，它可能承載身份或地位。"},{"en":"The phrase corrects a narrow understanding.","zh":"這個短語糾正狹窄理解。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":11},{"front":"bodily ornamentation","meaning":"身體裝飾","examples":[{"en":"Tattooing was more than bodily ornamentation.","zh":"紋身不只是身體裝飾。"},{"en":"Bodily ornamentation means decorating the body with marks, jewellery, paint or other forms.","zh":"「bodily ornamentation」指用標記、首飾、顏料或其他形式裝飾身體。"},{"en":"Earrings and ceremonial face paint can be forms of bodily ornamentation.","zh":"耳環和儀式面部彩繪可以是身體裝飾的形式。"},{"en":"In some cultures, bodily ornamentation also shows age, rank or group identity.","zh":"在一些文化中，身體裝飾也顯示年齡、階級或群體身份。"},{"en":"The phrase focuses on appearance, but the passage says tattooing had deeper meaning.","zh":"這個短語集中於外觀，但文章指出紋身有更深意義。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":11},{"front":"indicated genealogy and rank","meaning":"顯示家系和階級","examples":[{"en":"Tattooing indicated a person’s genealogy and rank.","zh":"紋身顯示一個人的家系和階級。"},{"en":"Indicated genealogy and rank means showed family ancestry and social position.","zh":"「indicated genealogy and rank」意思是顯示家族血統和社會地位。"},{"en":"A family name can sometimes indicate genealogy, but tattoos made it visible on the body.","zh":"姓氏有時可以顯示家系，但紋身把它直接顯示在身體上。"},{"en":"If a tattoo indicated rank, others could understand a person’s status quickly.","zh":"如果紋身顯示階級，其他人可以快速理解一個人的地位。"},{"en":"The phrase shows that tattoos communicated social information.","zh":"這個短語顯示紋身傳達社會資料。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":11},{"front":"genealogy","meaning":"家系；族譜","examples":[{"en":"A person’s genealogy could be shown through tattoos.","zh":"一個人的家系可以透過紋身顯示。"},{"en":"Genealogy is the history of a person’s family line and ancestors.","zh":"「genealogy」是一個人的家族線和祖先歷史。"},{"en":"Some families keep genealogy records to remember grandparents and earlier generations.","zh":"有些家庭保存族譜記錄，以記住祖父母和更早世代。"},{"en":"Genealogy can affect identity when people define themselves through ancestors.","zh":"當人們透過祖先定義自己，家系可以影響身份。"},{"en":"The word focuses on family descent over time.","zh":"這個詞集中於隨時間延續的家族血統。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":11},{"front":"rank in society","meaning":"社會地位","examples":[{"en":"Tattoos showed a person’s rank in society.","zh":"紋身顯示一個人的社會地位。"},{"en":"Rank in society means a person’s position or level in the social order.","zh":"「rank in society」指一個人在社會秩序中的位置或層級。"},{"en":"A uniform may show a soldier’s rank in society or in the army.","zh":"制服可能顯示士兵在社會或軍隊中的地位。"},{"en":"If tattoos showed rank, they helped people know how to behave toward one another.","zh":"如果紋身顯示階級，它們幫助人們知道如何互相對待。"},{"en":"The phrase is about social position, not personal character only.","zh":"這個短語關於社會位置，而不只是個人性格。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":11},{"front":"a sign of","meaning":"……的象徵","examples":[{"en":"Tattooing was a sign of wealth, strength and endurance.","zh":"紋身是財富、力量和忍耐力的象徵。"},{"en":"A sign of something is evidence or a symbol that shows it.","zh":"「a sign of」某事，是顯示它的證據或象徵。"},{"en":"A long queue can be a sign of a popular restaurant.","zh":"長長的隊伍可以是餐廳受歡迎的跡象。"},{"en":"In some cultures, special clothing is a sign of authority.","zh":"在一些文化中，特殊服裝是權威的象徵。"},{"en":"The phrase links something visible with a meaning behind it.","zh":"這個短語把可見事物與背後意義連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":11},{"front":"ability to endure pain","meaning":"忍受痛楚的能力","examples":[{"en":"Tattoos showed a person’s ability to endure pain.","zh":"紋身顯示一個人忍受痛楚的能力。"},{"en":"Ability to endure pain means the capacity to suffer pain without giving up.","zh":"「ability to endure pain」意思是承受痛楚而不放棄的能力。"},{"en":"Athletes need some ability to endure pain during hard training.","zh":"運動員在艱苦訓練中需要一定忍受痛楚的能力。"},{"en":"A painful ritual may become proof of endurance in a community.","zh":"痛苦儀式可能在社群中成為忍耐力的證明。"},{"en":"The phrase highlights mental strength as well as physical suffering.","zh":"這個短語強調精神力量和身體痛苦。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":11},{"front":"were regarded as","meaning":"被視為","examples":[{"en":"People without tattoos were regarded as lower in status.","zh":"沒有紋身的人被視為地位較低。"},{"en":"Were regarded as means were considered or seen in a particular way.","zh":"「were regarded as」意思是被認為或被看作某種樣子。"},{"en":"Good exam results were regarded as proof of hard work by many parents.","zh":"許多家長把好考試成績視為努力的證明。"},{"en":"If a custom is important, people who reject it may be regarded as different.","zh":"如果某習俗很重要，拒絕它的人可能被視為不同。"},{"en":"The phrase describes social judgement or opinion.","zh":"這個短語描述社會判斷或看法。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":11},{"front":"lower social status","meaning":"較低社會地位","examples":[{"en":"Those without tattoos had lower social status.","zh":"沒有紋身的人有較低社會地位。"},{"en":"Lower social status means a less respected or less powerful position in society.","zh":"「lower social status」指在社會中較不受尊重或權力較低的位置。"},{"en":"In some workplaces, temporary workers may have lower social status than managers.","zh":"在一些工作場所，臨時工可能比經理有較低社會地位。"},{"en":"If a visible mark shows lower social status, people may be treated differently.","zh":"如果可見標記顯示較低社會地位，人們可能受到不同對待。"},{"en":"The phrase describes position in a social hierarchy.","zh":"這個短語描述社會等級中的位置。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":11},{"front":"chiefs and warriors","meaning":"酋長和戰士","examples":[{"en":"Chiefs and warriors generally had the most elaborate tattoos.","zh":"酋長和戰士通常擁有最精細繁複的紋身。"},{"en":"Chiefs and warriors are leaders and fighters in a traditional society.","zh":"「chiefs and warriors」是傳統社會中的領袖和戰鬥者。"},{"en":"Chiefs may hold authority, while warriors may gain respect through bravery.","zh":"酋長可能掌握權威，而戰士可能透過勇敢獲得尊重。"},{"en":"If chiefs and warriors had the most elaborate tattoos, tattoos helped display power.","zh":"如果酋長和戰士擁有最精細繁複的紋身，紋身便幫助展示權力。"},{"en":"The phrase identifies high-status male figures in many traditional contexts.","zh":"這個短語指出許多傳統語境中的高地位男性角色。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":11},{"front":"elaborate tattoos","meaning":"精細繁複的紋身","examples":[{"en":"Chiefs and warriors had elaborate tattoos.","zh":"酋長和戰士擁有精細繁複的紋身。"},{"en":"Elaborate tattoos are detailed, complicated and carefully designed tattoos.","zh":"「elaborate tattoos」是細節多、複雜且經仔細設計的紋身。"},{"en":"An elaborate tattoo may take many sessions because it has many lines and symbols.","zh":"精細繁複的紋身可能需要多次完成，因為它有許多線條和符號。"},{"en":"Elaborate tattoos can signal wealth or status if they require time and skilled work.","zh":"如果精細繁複的紋身需要時間和熟練工作，它可以表示財富或地位。"},{"en":"The word elaborate suggests complexity and careful decoration.","zh":"elaborate 這個詞暗示複雜和精心裝飾。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":11},{"front":"began in adolescence","meaning":"在青春期開始","examples":[{"en":"Tattooing usually began in adolescence.","zh":"紋身通常在青春期開始。"},{"en":"Began in adolescence means started during the years between childhood and adulthood.","zh":"「began in adolescence」意思是在童年與成年之間的時期開始。"},{"en":"Many identity changes begin in adolescence as young people become more independent.","zh":"許多身份變化在青春期開始，因為年輕人變得更獨立。"},{"en":"If a ritual begins in adolescence, it may mark growing social responsibility.","zh":"如果儀式在青春期開始，它可能標誌社會責任增加。"},{"en":"The phrase connects a practice with a life stage.","zh":"這個短語把一種做法與人生階段連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":12},{"front":"took several years to complete","meaning":"需數年完成","examples":[{"en":"Some tattoos took several years to complete.","zh":"有些紋身需數年完成。"},{"en":"Took several years to complete means needed a number of years before being finished.","zh":"「took several years to complete」意思是需要幾年才完成。"},{"en":"A large building project may take several years to complete.","zh":"大型建築項目可能需數年完成。"},{"en":"If a tattoo took years to complete, it showed long-term commitment and endurance.","zh":"如果一個紋身需多年完成，它顯示長期承諾和忍耐力。"},{"en":"The phrase stresses that the process was slow and extended.","zh":"這個短語強調過程緩慢而持久。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":12},{"front":"receiving tattoos","meaning":"接受紋身","examples":[{"en":"Receiving tattoos marked an important milestone.","zh":"接受紋身標誌着一個重要里程碑。"},{"en":"Receiving tattoos means being given tattoos by a tattoo artist or specialist.","zh":"「receiving tattoos」意思是由紋身師或專家為自己紋身。"},{"en":"Receiving a certificate can mark the end of a course, just as receiving tattoos marked a stage of life.","zh":"接受證書可以標誌課程結束，就像接受紋身標誌人生階段。"},{"en":"In some cultures, receiving tattoos may change how others see a person socially.","zh":"在一些文化中，接受紋身可能改變他人在社會上如何看待一個人。"},{"en":"The phrase focuses on the person undergoing the tattooing process.","zh":"這個短語集中於經歷紋身過程的人。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":12},{"front":"marked an important milestone","meaning":"標誌着重要里程碑","examples":[{"en":"Receiving tattoos marked an important milestone between childhood and adulthood.","zh":"接受紋身標誌着童年與成年之間的重要里程碑。"},{"en":"Marked an important milestone means showed that a major stage or achievement had been reached.","zh":"「marked an important milestone」意思是顯示已到達一個重要階段或成就。"},{"en":"Graduating from school marked an important milestone in her life.","zh":"從學校畢業標誌着她人生中的重要里程碑。"},{"en":"A coming-of-age ritual can mark an important milestone in a young person’s social identity.","zh":"成年禮可以標誌年輕人社會身份中的重要里程碑。"},{"en":"The phrase connects an event with a meaningful turning point.","zh":"這個短語把事件與有意義的轉捩點連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":12},{"front":"between childhood and adulthood","meaning":"在童年與成年之間","examples":[{"en":"Tattooing marked the transition between childhood and adulthood.","zh":"紋身標誌童年與成年之間的轉變。"},{"en":"Between childhood and adulthood means in the stage separating being a child from being an adult.","zh":"「between childhood and adulthood」意思是在兒童身份與成人身份之間的階段。"},{"en":"Adolescence is the period between childhood and adulthood.","zh":"青春期就是童年與成年之間的時期。"},{"en":"Rituals between childhood and adulthood can teach young people new responsibilities.","zh":"童年與成年之間的儀式可以教年輕人新的責任。"},{"en":"The phrase highlights a life transition.","zh":"這個短語強調人生過渡。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":12},{"front":"accompanied by","meaning":"伴隨","examples":[{"en":"Tattooing was accompanied by many rites and rituals.","zh":"紋身伴隨許多儀式和禮俗。"},{"en":"Accompanied by means happened together with or was joined by something else.","zh":"「accompanied by」意思是與其他事物一起發生或相伴。"},{"en":"A school ceremony may be accompanied by music and speeches.","zh":"學校典禮可能伴隨音樂和演講。"},{"en":"If tattooing was accompanied by rituals, it was more than a private body decoration.","zh":"如果紋身伴隨儀式，它就不只是私人身體裝飾。"},{"en":"The phrase shows that two things occur together.","zh":"這個短語顯示兩件事一起出現。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":12},{"front":"rites and rituals","meaning":"儀式和禮俗","examples":[{"en":"Tattooing was accompanied by rites and rituals.","zh":"紋身伴隨儀式和禮俗。"},{"en":"Rites and rituals are formal actions performed for cultural, religious or social reasons.","zh":"「rites and rituals」是出於文化、宗教或社會原因而進行的正式行動。"},{"en":"Weddings, funerals and coming-of-age ceremonies often include rites and rituals.","zh":"婚禮、葬禮和成年禮常包括儀式和禮俗。"},{"en":"Rites and rituals give important life events public meaning.","zh":"儀式和禮俗賦予重要人生事件公共意義。"},{"en":"The phrase suggests repeated symbolic actions, not casual behaviour.","zh":"這個短語暗示重複的象徵性行動，而不是隨意行為。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":12},{"front":"besides signalling","meaning":"除了顯示……之外","examples":[{"en":"Besides signalling status, tattooing was meant to increase attractiveness.","zh":"除了顯示身份之外，紋身也旨在增加吸引力。"},{"en":"Besides signalling means in addition to showing or communicating something.","zh":"「besides signalling」意思是除了顯示或傳達某事之外。"},{"en":"Besides signalling danger, a red light tells drivers to stop.","zh":"紅燈除了顯示危險之外，也告訴司機停下。"},{"en":"Besides signalling rank, clothing may also show taste or wealth.","zh":"服裝除了顯示階級之外，也可能顯示品味或財富。"},{"en":"The phrase adds another function to the one already mentioned.","zh":"這個短語在已提功能之外加入另一功能。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":12},{"front":"status and rank","meaning":"身份和階級","examples":[{"en":"Tattoos signalled status and rank.","zh":"紋身顯示身份和階級。"},{"en":"Status and rank mean a person’s social importance and level within a group.","zh":"「status and rank」指一個人在群體中的社會重要性和層級。"},{"en":"In an organisation, titles can signal status and rank.","zh":"在組織中，職銜可以顯示身份和階級。"},{"en":"When tattoos show status and rank, the body becomes a social document.","zh":"當紋身顯示身份和階級，身體就成為一份社會文件。"},{"en":"The phrase refers to position in society, not just wealth.","zh":"這個短語指社會位置，而不只是財富。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":12},{"front":"intended to make","meaning":"旨在令……","examples":[{"en":"Tattooing was intended to make a person more attractive.","zh":"紋身旨在令一個人更有吸引力。"},{"en":"Intended to make means designed or meant to produce a particular result.","zh":"「intended to make」意思是設計或意圖產生某個結果。"},{"en":"The new timetable was intended to make buses more reliable.","zh":"新時間表旨在令巴士更可靠。"},{"en":"If a ritual is intended to make someone respected, its social meaning is important.","zh":"如果一種儀式旨在令人受尊重，它的社會意義就很重要。"},{"en":"The phrase explains purpose.","zh":"這個短語解釋目的。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":12},{"front":"more attractive to","meaning":"對……更有吸引力","examples":[{"en":"Tattooing was intended to make a person more attractive to the opposite sex.","zh":"紋身旨在令一個人對異性更有吸引力。"},{"en":"More attractive to someone means more pleasing, interesting or appealing to that person or group.","zh":"「more attractive to」某人，意思是對那個人或群體更吸引、更討好或更有魅力。"},{"en":"A shop may make its window display more attractive to young customers.","zh":"商店可能令櫥窗展示對年輕顧客更有吸引力。"},{"en":"If tattoos were more attractive to potential partners, they had social and personal value.","zh":"如果紋身對潛在伴侶更有吸引力，它就有社會和個人價值。"},{"en":"The phrase describes appeal from another person’s point of view.","zh":"這個短語從另一人的角度描述吸引力。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":12},{"front":"the opposite sex","meaning":"異性","examples":[{"en":"Tattooing could make a person more attractive to the opposite sex.","zh":"紋身可以令一個人對異性更有吸引力。"},{"en":"The opposite sex means people of the other biological sex in a traditional male-female contrast.","zh":"「the opposite sex」在傳統男女二分中指另一生理性別的人。"},{"en":"In older texts, writers often mention attraction to the opposite sex when discussing marriage.","zh":"在較舊文本中，作者討論婚姻時常提到對異性的吸引。"},{"en":"The phrase may sound traditional today, but it appears in many historical descriptions.","zh":"這個短語今天可能聽起來較傳統，但常出現在許多歷史描述中。"},{"en":"In this context, it refers to attraction between men and women.","zh":"在這個語境中，它指男女之間的吸引。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":13},{"front":"male facial tattoo","meaning":"男性面部紋身","examples":[{"en":"The male facial tattoo is generally divided into eight sections.","zh":"男性面部紋身一般分為八個部分。"},{"en":"A male facial tattoo is a tattoo design placed on a man’s face.","zh":"「male facial tattoo」是紋在男性面部的紋身圖案。"},{"en":"Male facial tattoos can carry information about rank, family and personal history.","zh":"男性面部紋身可以承載關於階級、家族和個人歷史的資料。"},{"en":"Dividing the tattoo into sections allowed different parts of the face to show different meanings.","zh":"把紋身分成不同部分，讓面部不同位置顯示不同意義。"},{"en":"The phrase refers to both body location and gendered cultural meaning.","zh":"這個短語同時指身體位置和性別化文化意義。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":13},{"front":"divided into eight sections","meaning":"分為八個部分","examples":[{"en":"The male facial tattoo is divided into eight sections.","zh":"男性面部紋身分為八個部分。"},{"en":"Divided into eight sections means separated into eight parts.","zh":"「divided into eight sections」意思是分成八個部分。"},{"en":"A worksheet divided into eight sections helps students organise different ideas.","zh":"分為八個部分的工作紙幫助學生整理不同想法。"},{"en":"When a design is divided into sections, each part can carry a separate meaning.","zh":"當圖案分成不同部分，每部分都可以承載獨立意義。"},{"en":"The phrase describes structure and organisation.","zh":"這個短語描述結構和組織。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":13},{"front":"the centre of the forehead","meaning":"額頭中央","examples":[{"en":"The centre of the forehead indicated a person’s general rank.","zh":"額頭中央顯示一個人的一般階級。"},{"en":"The centre of the forehead is the middle area above the eyes and below the hairline.","zh":"「the centre of the forehead」是眼睛上方、髮線下方的中間位置。"},{"en":"A mark at the centre of the forehead is highly visible when people meet face to face.","zh":"額頭中央的標記在人們面對面時非常顯眼。"},{"en":"If this area indicated rank, social information could be read quickly.","zh":"如果這個位置顯示階級，社會資料便可快速被讀出。"},{"en":"The phrase names a precise facial location.","zh":"這個短語指出精確的面部位置。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":13},{"front":"general rank","meaning":"一般階級","examples":[{"en":"The centre of the forehead indicated general rank.","zh":"額頭中央顯示一般階級。"},{"en":"General rank means a person’s broad social level or status.","zh":"「general rank」指一個人大致的社會層級或地位。"},{"en":"A job title can show someone’s general rank in an office.","zh":"職銜可以顯示某人在辦公室中的一般階級。"},{"en":"If a tattoo shows general rank, people can understand social position at a glance.","zh":"如果紋身顯示一般階級，人們一眼就能理解社會位置。"},{"en":"The phrase gives an overall level, not every detail of status.","zh":"這個短語給出整體層級，而不是地位的每個細節。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":13},{"front":"area around the brows","meaning":"眉毛周圍位置","examples":[{"en":"The area around the brows indicated a person’s position.","zh":"眉毛周圍位置顯示一個人的地位。"},{"en":"The area around the brows means the part of the face near the eyebrows.","zh":"「area around the brows」指面部靠近眉毛的部分。"},{"en":"Expressions around the brows can show anger, worry or surprise.","zh":"眉毛周圍的表情可以顯示憤怒、擔心或驚訝。"},{"en":"In the tattoo system, this facial area carried information about position.","zh":"在紋身系統中，這個面部位置承載關於地位的資料。"},{"en":"The phrase identifies a specific part of the face.","zh":"這個短語指出面部的特定部分。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":13},{"front":"indicated his position","meaning":"顯示其地位","examples":[{"en":"The area around the brows indicated his position.","zh":"眉毛周圍位置顯示其地位。"},{"en":"Indicated his position means showed his social place, role or standing.","zh":"「indicated his position」意思是顯示他的社會位置、角色或身份。"},{"en":"A badge on a uniform may indicate a worker’s position in a company.","zh":"制服上的徽章可能顯示員工在公司中的職位。"},{"en":"If a tattoo indicated his position, others could recognise his role without asking.","zh":"如果紋身顯示其地位，其他人不必詢問便可認出他的角色。"},{"en":"The phrase links a visible sign with social information.","zh":"這個短語把可見標記與社會資料連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":13},{"front":"area around the eyes and nose","meaning":"眼睛和鼻子周圍位置","examples":[{"en":"The area around the eyes and nose indicated a man’s hapu.","zh":"眼睛和鼻子周圍位置顯示一名男子的 hapu。"},{"en":"The area around the eyes and nose means the central facial region around those features.","zh":"「area around the eyes and nose」指面部圍繞眼睛和鼻子的中央區域。"},{"en":"Marks around the eyes and nose are very noticeable in face-to-face contact.","zh":"眼睛和鼻子周圍的標記在人與人面對面時很顯眼。"},{"en":"In this tattoo system, the area carried information about group membership.","zh":"在這個紋身系統中，該位置承載關於群體身份的資料。"},{"en":"The phrase names a facial location used for social meaning.","zh":"這個短語指出用於社會意義的面部位置。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":13},{"front":"hapu","meaning":"hapu；支族","examples":[{"en":"A person’s hapu was shown around the eyes and nose.","zh":"一個人的 hapu 會顯示在眼睛和鼻子周圍。"},{"en":"Hapu means a subtribe or smaller kinship group in Māori and related Polynesian contexts.","zh":"「hapu」在毛利及相關波利尼西亞語境中指支族或較小親屬群體。"},{"en":"Knowing someone’s hapu could help others understand family and group connections.","zh":"知道某人的 hapu 可以幫助他人理解家庭和群體聯繫。"},{"en":"If a tattoo showed hapu, it made group identity visible on the face.","zh":"如果紋身顯示 hapu，它就把群體身份顯示在面上。"},{"en":"The word refers to social belonging, not just a place.","zh":"這個詞指社會歸屬，而不只是地方。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":13},{"front":"subtribe","meaning":"支族","examples":[{"en":"A hapu is a subtribe.","zh":"hapu 是一個支族。"},{"en":"A subtribe is a smaller group within a larger tribe.","zh":"「subtribe」是較大部族內的較小群體。"},{"en":"A subtribe may share ancestors, land, rituals or leadership.","zh":"支族可能共享祖先、土地、儀式或領導。"},{"en":"Knowing a person’s subtribe can explain their place within a wider community.","zh":"知道一個人的支族可以解釋他在更大社群中的位置。"},{"en":"The word shows a smaller level of social organisation.","zh":"這個詞顯示較小層級的社會組織。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":13},{"front":"area around the temples","meaning":"太陽穴周圍位置","examples":[{"en":"The area around the temples detailed his marital status.","zh":"太陽穴周圍位置詳列其婚姻狀況。"},{"en":"The area around the temples means the sides of the head near the eyes and forehead.","zh":"「area around the temples」指靠近眼睛和額頭兩側的頭部位置。"},{"en":"Pain around the temples can feel like pressure on both sides of the head.","zh":"太陽穴周圍疼痛可能感覺像頭部兩側受壓。"},{"en":"In the tattoo system, this area was used to show marriage information.","zh":"在紋身系統中，這個位置用來顯示婚姻資料。"},{"en":"The phrase identifies another specific part of the face.","zh":"這個短語指出面部另一個特定部位。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":13},{"front":"detailed his marital status","meaning":"詳列其婚姻狀況","examples":[{"en":"The area around the temples detailed his marital status.","zh":"太陽穴周圍位置詳列其婚姻狀況。"},{"en":"Detailed his marital status means gave information about whether or how he was married.","zh":"「detailed his marital status」意思是提供關於他是否結婚或婚姻情況的資料。"},{"en":"An official form may detail a person’s marital status as single, married or divorced.","zh":"官方表格可能詳列一個人的婚姻狀況，如未婚、已婚或離婚。"},{"en":"If tattoos detailed marital status, personal life became publicly readable.","zh":"如果紋身詳列婚姻狀況，私人生活就變得公開可讀。"},{"en":"The phrase shows that the mark gave specific social information.","zh":"這個短語顯示標記提供具體社會資料。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":14},{"front":"number of marriages","meaning":"婚姻次數","examples":[{"en":"The tattoo could show the number of marriages.","zh":"紋身可以顯示婚姻次數。"},{"en":"Number of marriages means how many times a person has been married.","zh":"「number of marriages」指一個人結婚的次數。"},{"en":"A family record may list the number of marriages in a person’s life.","zh":"家族記錄可能列出一個人一生中的婚姻次數。"},{"en":"If a tattoo showed the number of marriages, it recorded personal history visibly.","zh":"如果紋身顯示婚姻次數，它就把個人歷史可見地記錄下來。"},{"en":"The phrase gives a count, not just a general marital status.","zh":"這個短語提供數量，而不只是一般婚姻狀況。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":14},{"front":"beneath the nose","meaning":"鼻下","examples":[{"en":"The area beneath the nose displayed his signature.","zh":"鼻下位置顯示其簽名。"},{"en":"Beneath the nose means directly under the nose.","zh":"「beneath the nose」意思是在鼻子正下方。"},{"en":"A moustache grows beneath the nose and above the upper lip.","zh":"鬍鬚長在鼻下、上唇之上。"},{"en":"A mark beneath the nose would be visible whenever a person spoke or faced others.","zh":"鼻下的標記在人說話或面向他人時會很顯眼。"},{"en":"The phrase gives a precise facial location.","zh":"這個短語提供精確的面部位置。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":14},{"front":"displayed his signature","meaning":"顯示其簽名","examples":[{"en":"The area beneath the nose displayed his signature.","zh":"鼻下位置顯示其簽名。"},{"en":"Displayed his signature means showed a personal mark used to identify him.","zh":"「displayed his signature」意思是顯示用來識別他的個人標記。"},{"en":"A handwritten signature on a contract proves who approved it.","zh":"合約上的手寫簽名證明是誰批准了它。"},{"en":"If a tattoo displayed his signature, identity could be recognised without paper documents.","zh":"如果紋身顯示其簽名，不用紙本文書也可識別身份。"},{"en":"The phrase connects a visible mark with personal identification.","zh":"這個短語把可見標記與個人識別連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":14},{"front":"tribal chiefs","meaning":"部族酋長","examples":[{"en":"Tribal chiefs memorised these signatures.","zh":"部族酋長記住這些簽名。"},{"en":"Tribal chiefs are leaders of tribes or traditional communities.","zh":"「tribal chiefs」是部族或傳統社群的領袖。"},{"en":"Tribal chiefs may settle disputes, lead ceremonies or approve agreements.","zh":"部族酋長可能解決爭端、主持儀式或批准協議。"},{"en":"If chiefs memorised signatures, they could recognise people’s identity and authority.","zh":"如果酋長記住簽名，他們便能辨認人們的身份和權威。"},{"en":"The phrase refers to leadership within a tribal social system.","zh":"這個短語指部族社會系統中的領導。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":14},{"front":"memorised these signatures","meaning":"記住這些簽名","examples":[{"en":"Tribal chiefs memorised these signatures.","zh":"部族酋長記住這些簽名。"},{"en":"Memorised these signatures means learned and remembered these identifying marks.","zh":"「memorised these signatures」意思是學會並記住這些識別標記。"},{"en":"A bank worker may memorise common security features on documents.","zh":"銀行職員可能記住文件上常見的保安特徵。"},{"en":"If chiefs memorised signatures, they could verify agreements without written databases.","zh":"如果酋長記住簽名，他們不用書面數據庫也可核實協議。"},{"en":"The phrase shows memory being used for social and legal recognition.","zh":"這個短語顯示記憶被用於社會和法律識別。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":14},{"front":"buying property","meaning":"購買物業","examples":[{"en":"Chiefs used the signatures when buying property.","zh":"酋長在購買物業時使用這些簽名。"},{"en":"Buying property means purchasing land, a house or another form of real estate.","zh":"「buying property」意思是購買土地、房屋或其他房地產。"},{"en":"A family buying property must usually sign legal documents.","zh":"家庭購買物業時通常必須簽署法律文件。"},{"en":"If signatures were used when buying property, tattoos could support formal transactions.","zh":"如果購買物業時使用簽名，紋身便可以支援正式交易。"},{"en":"The phrase connects personal identification with ownership.","zh":"這個短語把個人識別與所有權連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":14},{"front":"signing deeds","meaning":"簽署契據","examples":[{"en":"Chiefs used the signatures when signing deeds.","zh":"酋長在簽署契據時使用這些簽名。"},{"en":"Signing deeds means formally signing legal documents, often about land or property.","zh":"「signing deeds」意思是正式簽署法律文件，通常與土地或物業有關。"},{"en":"A buyer and seller may both be present when signing deeds.","zh":"買方和賣方可能在簽署契據時都在場。"},{"en":"If a signature was memorised, chiefs could confirm who was signing deeds.","zh":"如果簽名已被記住，酋長便能確認誰在簽署契據。"},{"en":"The phrase belongs to legal and property contexts.","zh":"這個短語屬於法律和物業語境。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":14},{"front":"officiating orders","meaning":"正式處理命令","examples":[{"en":"Chiefs used the signatures when officiating orders.","zh":"酋長在正式處理命令時使用這些簽名。"},{"en":"Officiating orders means formally approving, issuing or carrying out official instructions.","zh":"「officiating orders」意思是正式批准、發出或執行官方命令。"},{"en":"A manager may officiate orders by signing them and making them valid.","zh":"經理可能透過簽署命令來正式處理它們，使其有效。"},{"en":"If chiefs used signatures when officiating orders, identity and authority mattered.","zh":"如果酋長在正式處理命令時使用簽名，身份和權威便很重要。"},{"en":"The phrase suggests formal action by someone in power.","zh":"這個短語暗示由有權力的人進行正式行動。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":14},{"front":"cheek area","meaning":"面頰位置","examples":[{"en":"The cheek area indicated the nature of a person’s work.","zh":"面頰位置顯示一個人的工作性質。"},{"en":"The cheek area means the part of the face on either side of the mouth and nose.","zh":"「cheek area」指嘴和鼻兩側的面部部分。"},{"en":"A mark on the cheek area is easy to see during conversation.","zh":"面頰位置上的標記在交談時容易看見。"},{"en":"If the cheek area showed work, occupations could be recognised from facial tattoos.","zh":"如果面頰位置顯示工作，人們便可從面部紋身辨認職業。"},{"en":"The phrase names a visible part of the face.","zh":"這個短語指出面部一個可見部分。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":14},{"front":"the nature of a person’s work","meaning":"一個人的工作性質","examples":[{"en":"The cheek area showed the nature of a person’s work.","zh":"面頰位置顯示一個人的工作性質。"},{"en":"The nature of a person’s work means the kind, role or character of the work they do.","zh":"「the nature of a person’s work」指一個人所做工作的種類、角色或特點。"},{"en":"A uniform can show the nature of a person’s work, such as nurse, police officer or chef.","zh":"制服可以顯示一個人的工作性質，例如護士、警員或廚師。"},{"en":"If tattoos showed work nature, they acted like visible social records.","zh":"如果紋身顯示工作性質，它們就像可見的社會記錄。"},{"en":"The phrase asks what type of work is involved.","zh":"這個短語問的是涉及什麼類型的工作。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":14},{"front":"chin area","meaning":"下巴位置","examples":[{"en":"The chin area showed his mana.","zh":"下巴位置顯示他的 mana。"},{"en":"The chin area means the lower front part of the face below the mouth.","zh":"「chin area」指嘴巴下方面部前方較低的位置。"},{"en":"A beard often grows around the chin area.","zh":"鬍鬚常長在下巴位置。"},{"en":"In this tattoo system, the chin area carried information about spiritual power or status.","zh":"在這個紋身系統中，下巴位置承載關於靈力或地位的資料。"},{"en":"The phrase identifies one part of the lower face.","zh":"這個短語指出下半面部的一個部分。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":15},{"front":"mana","meaning":"mana；靈力；威望","examples":[{"en":"A person’s mana was shown by the chin area.","zh":"一個人的 mana 由下巴位置顯示。"},{"en":"Mana can mean spiritual power, authority, prestige or life force in Polynesian contexts.","zh":"「mana」在波利尼西亞語境中可以指靈性力量、權威、威望或生命力。"},{"en":"A respected leader may be described as having strong mana.","zh":"受尊敬的領袖可能被描述為擁有強大的 mana。"},{"en":"If tattoos displayed mana, they made invisible power visible on the body.","zh":"如果紋身展示 mana，它們就把不可見力量顯示在身體上。"},{"en":"The word carries cultural meaning and should not be reduced to one simple English word.","zh":"這個詞帶有文化意義，不應簡化為單一英文詞。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":15},{"front":"jaw area","meaning":"下顎位置","examples":[{"en":"The jaw area indicated his birth status.","zh":"下顎位置顯示他的出生地位。"},{"en":"The jaw area means the lower side parts of the face where the jawbone is.","zh":"「jaw area」指面部較低兩側、下顎骨所在的位置。"},{"en":"A strong line around the jaw area can change how a face appears.","zh":"下顎位置清晰的線條可以改變面部外觀。"},{"en":"In this tattoo system, the jaw area carried information about birth status.","zh":"在這個紋身系統中，下顎位置承載出生地位的資料。"},{"en":"The phrase names a specific lower-face location.","zh":"這個短語指出下半面部的特定位置。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":15},{"front":"birth status","meaning":"出生地位","examples":[{"en":"The jaw area indicated a person’s birth status.","zh":"下顎位置顯示一個人的出生地位。"},{"en":"Birth status means the social position someone has because of family background at birth.","zh":"「birth status」指某人因出生時的家庭背景而擁有的社會位置。"},{"en":"In some societies, birth status affects marriage, leadership or inheritance.","zh":"在一些社會中，出生地位會影響婚姻、領導權或繼承。"},{"en":"If tattoos showed birth status, ancestry became visible in social life.","zh":"如果紋身顯示出生地位，祖先背景就會在社會生活中變得可見。"},{"en":"The phrase focuses on status inherited from birth, not later achievement.","zh":"這個短語集中於出生時繼承的地位，而不是後天成就。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":15},{"front":"ancestry","meaning":"祖先；血統","examples":[{"en":"A person’s ancestry was indicated on each side of the face.","zh":"一個人的祖先血統顯示於面部每一側。"},{"en":"Ancestry means the family line or ancestors a person comes from.","zh":"「ancestry」指一個人來自的家族線或祖先。"},{"en":"People may research ancestry to learn where their grandparents and earlier relatives lived.","zh":"人們可能研究祖先血統，以了解祖父母和更早親屬住在哪裡。"},{"en":"In some communities, ancestry affects identity, rights and social duties.","zh":"在一些社群中，祖先血統影響身份、權利和社會責任。"},{"en":"The word is close to genealogy but often used more generally.","zh":"這個詞接近 genealogy，但用法通常較廣。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":15},{"front":"indicated on each side of","meaning":"顯示於……每一側","examples":[{"en":"Ancestry was indicated on each side of the face.","zh":"祖先血統顯示於面部每一側。"},{"en":"Indicated on each side of means shown separately on both left and right sides.","zh":"「indicated on each side of」意思是分別顯示於左右兩側。"},{"en":"A diagram may show different labels on each side of a machine.","zh":"圖表可能在機器每一側顯示不同標籤。"},{"en":"If ancestry is indicated on each side of the face, each side may carry different family information.","zh":"如果祖先血統顯示於面部每一側，每一側可能承載不同家族資料。"},{"en":"The phrase describes location and division of meaning.","zh":"這個短語描述位置和意義分配。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":15},{"front":"represented the father’s ancestry","meaning":"代表父系血統","examples":[{"en":"The left side generally represented the father’s ancestry.","zh":"左側通常代表父系血統。"},{"en":"Represented the father’s ancestry means stood for the family line from the father’s side.","zh":"「represented the father’s ancestry」意思是代表來自父親一方的家族血統。"},{"en":"A family tree may use one colour to represent the father’s ancestry.","zh":"族譜可能用一種顏色代表父系血統。"},{"en":"If the left side represented paternal ancestry, people could read family background from facial tattoos.","zh":"如果左側代表父系血統，人們便能從面部紋身讀出家族背景。"},{"en":"The phrase connects a visible side with a family line.","zh":"這個短語把可見的一側與家族線連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":15},{"front":"the mother’s ancestry","meaning":"母系血統","examples":[{"en":"The right side generally represented the mother’s ancestry.","zh":"右側通常代表母系血統。"},{"en":"The mother’s ancestry means the family line from a person’s mother’s side.","zh":"「the mother’s ancestry」指來自母親一方的家族血統。"},{"en":"A child may learn about the mother’s ancestry through stories from grandparents.","zh":"孩子可能透過祖父母的故事了解母系血統。"},{"en":"Showing the mother’s ancestry separately suggests both family lines mattered.","zh":"分開顯示母系血統，暗示兩邊家族線都重要。"},{"en":"The phrase refers to maternal family background.","zh":"這個短語指母方家族背景。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":15},{"front":"manutahi design","meaning":"manutahi 圖案","examples":[{"en":"The manutahi design was tattooed on a man’s back.","zh":"manutahi 圖案紋在男性背上。"},{"en":"The manutahi design was a specific tattoo pattern used in this cultural context.","zh":"「manutahi design」是在這個文化語境中使用的特定紋身圖案。"},{"en":"A named design can carry a meaning that ordinary decoration does not.","zh":"有名稱的圖案可以承載普通裝飾沒有的意義。"},{"en":"If a man had the manutahi design, others could recognise a particular message about him.","zh":"如果一名男子有 manutahi 圖案，其他人便可認出關於他的特定訊息。"},{"en":"The phrase names a culturally specific tattoo design.","zh":"這個短語指出具有文化特定性的紋身圖案。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":15},{"front":"tattooed on a man’s back","meaning":"紋在男性背上","examples":[{"en":"The manutahi design was tattooed on a man’s back.","zh":"manutahi 圖案紋在男性背上。"},{"en":"Tattooed on a man’s back means permanently marked on the back of a male body.","zh":"「tattooed on a man’s back」意思是永久標記在男性背部。"},{"en":"A large design may be tattooed on someone’s back because there is more space.","zh":"大型圖案可能紋在某人背上，因為那裡空間較大。"},{"en":"If a pattern is tattooed on the back, it may be shown during public gatherings or rituals.","zh":"如果圖案紋在背上，它可能在公共聚會或儀式中展示。"},{"en":"The phrase gives both body location and gender.","zh":"這個短語同時給出身體位置和性別。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":15},{"front":"consisted of","meaning":"由……組成","examples":[{"en":"The design consisted of two vertical lines.","zh":"這個圖案由兩條垂直線組成。"},{"en":"Consisted of means was made up of particular parts.","zh":"「consisted of」意思是由特定部分組成。"},{"en":"The lunch consisted of rice, fish and vegetables.","zh":"午餐由米飯、魚和蔬菜組成。"},{"en":"If a design consisted of simple lines, its meaning could still be culturally rich.","zh":"即使一個圖案由簡單線條組成，它的文化意義仍可以很豐富。"},{"en":"The phrase explains what something contains.","zh":"這個短語解釋某物包含什麼。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":15},{"front":"vertical lines","meaning":"垂直線","examples":[{"en":"The manutahi design consisted of vertical lines down the spine.","zh":"manutahi 圖案由沿脊柱向下的垂直線組成。"},{"en":"Vertical lines are straight lines that go up and down rather than side to side.","zh":"「vertical lines」是上下走向而不是左右走向的直線。"},{"en":"A teacher may draw vertical lines on the board to divide a table into columns.","zh":"老師可能在白板上畫垂直線，把表格分成欄。"},{"en":"Vertical lines down the spine would follow the body’s central back line.","zh":"沿脊柱向下的垂直線會跟隨背部中央線。"},{"en":"The phrase describes direction and shape.","zh":"這個短語描述方向和形狀。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":16},{"front":"down the spine","meaning":"沿脊柱向下","examples":[{"en":"The lines went down the spine.","zh":"這些線沿脊柱向下。"},{"en":"Down the spine means along the backbone from higher to lower on the back.","zh":"「down the spine」意思是沿着背部脊骨由上向下。"},{"en":"A doctor may check pain running down the spine.","zh":"醫生可能檢查沿脊柱向下延伸的疼痛。"},{"en":"A tattoo down the spine follows a clear central line on the body.","zh":"沿脊柱向下的紋身跟隨身體清晰的中央線。"},{"en":"The phrase gives a vertical body location.","zh":"這個短語提供垂直的身體位置。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":16},{"front":"took pride in himself","meaning":"以自己為榮","examples":[{"en":"A man with the manutahi took pride in himself.","zh":"有 manutahi 紋身的男子以自己為榮。"},{"en":"Took pride in himself means felt proud of his identity, achievement or appearance.","zh":"「took pride in himself」意思是為自己的身份、成就或外表感到自豪。"},{"en":"A student who improves through hard work may take pride in himself.","zh":"透過努力而進步的學生可能以自己為榮。"},{"en":"If a tattoo symbolised courage, wearing it could help a man take pride in himself.","zh":"如果紋身象徵勇氣，擁有它可以幫助男子以自己為榮。"},{"en":"The phrase describes self-respect and confidence.","zh":"這個短語描述自尊和信心。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":16},{"front":"stand proudly","meaning":"自豪地站立","examples":[{"en":"He could stand proudly at community gatherings.","zh":"他可以在社群聚會中自豪地站立。"},{"en":"Stand proudly means stand with confidence and self-respect.","zh":"「stand proudly」意思是帶着信心和自尊站立。"},{"en":"A student may stand proudly on stage after receiving an award.","zh":"學生領獎後可能自豪地站在台上。"},{"en":"If a person’s tattoo carries honour, he may stand proudly when others see it.","zh":"如果一個人的紋身承載榮譽，當他人看見它時，他可能自豪地站立。"},{"en":"The phrase describes body posture and inner confidence.","zh":"這個短語描述身體姿態和內在信心。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":16},{"front":"community gatherings","meaning":"社群聚會","examples":[{"en":"A man could describe his tattoos at community gatherings.","zh":"男子可以在社群聚會中描述自己的紋身。"},{"en":"Community gatherings are events where members of a community meet together.","zh":"「community gatherings」是社群成員聚在一起的活動。"},{"en":"Festivals, meetings and village ceremonies can be community gatherings.","zh":"節日、會議和村莊儀式都可以是社群聚會。"},{"en":"At community gatherings, public display of tattoos could reinforce status and identity.","zh":"在社群聚會中，公開展示紋身可以加強地位和身份。"},{"en":"The phrase suggests a social setting, not a private moment.","zh":"這個短語暗示社會場合，而不是私人時刻。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":16},{"front":"describe his tattoo designs in songs","meaning":"以歌曲描述自己的紋身圖案","examples":[{"en":"He could describe his tattoo designs in songs.","zh":"他可以以歌曲描述自己的紋身圖案。"},{"en":"To describe his tattoo designs in songs means to sing about the patterns and their meanings.","zh":"「describe his tattoo designs in songs」意思是唱出圖案及其意義。"},{"en":"A performer may describe family history in songs so others remember it easily.","zh":"表演者可能以歌曲描述家族歷史，讓其他人容易記住。"},{"en":"Singing about tattoos could turn body markings into public stories.","zh":"歌唱紋身可以把身體標記變成公開故事。"},{"en":"The phrase connects visual design with oral tradition.","zh":"這個短語把視覺圖案與口述傳統連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":16},{"front":"rows of triangles","meaning":"一排排三角形","examples":[{"en":"Rows of triangles on a man’s chest indicated bravery.","zh":"男性胸口上一排排三角形顯示勇敢。"},{"en":"Rows of triangles are repeated lines of triangular shapes.","zh":"「rows of triangles」是重複排列成行的三角形。"},{"en":"A fabric pattern may use rows of triangles to create a bold design.","zh":"布料圖案可能使用一排排三角形來形成鮮明設計。"},{"en":"In tattooing, repeated geometric shapes can carry symbolic meaning.","zh":"在紋身中，重複的幾何形狀可以承載象徵意義。"},{"en":"The phrase describes both arrangement and shape.","zh":"這個短語同時描述排列和形狀。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":16},{"front":"on a man’s chest","meaning":"在男性胸口上","examples":[{"en":"Rows of triangles appeared on a man’s chest.","zh":"一排排三角形出現在男性胸口上。"},{"en":"On a man’s chest means located on the front upper part of a male body.","zh":"「on a man’s chest」意思是位於男性身體前方上半部。"},{"en":"A medal may be worn on a man’s chest during a ceremony.","zh":"在典禮中，獎章可能佩戴在男性胸口上。"},{"en":"A tattoo on the chest can be shown or covered depending on clothing and occasion.","zh":"胸口上的紋身可按衣着和場合展示或遮蓋。"},{"en":"The phrase gives a clear body location.","zh":"這個短語提供清楚的身體位置。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":16},{"front":"indicated his bravery","meaning":"顯示其勇敢","examples":[{"en":"The triangles indicated his bravery.","zh":"這些三角形顯示其勇敢。"},{"en":"Indicated his bravery means showed that he was considered courageous.","zh":"「indicated his bravery」意思是顯示他被認為勇敢。"},{"en":"A medal can indicate a soldier’s bravery in battle.","zh":"獎章可以顯示士兵在戰鬥中的勇敢。"},{"en":"If a tattoo indicated bravery, it publicly recognised a valued personal quality.","zh":"如果紋身顯示勇敢，它就公開承認一種受重視的個人品質。"},{"en":"The phrase links a visible symbol with courage.","zh":"這個短語把可見象徵與勇氣連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":16},{"front":"conveyed information about","meaning":"傳達關於……的資料","examples":[{"en":"A tattoo conveyed information about its owner.","zh":"紋身傳達關於其擁有者的資料。"},{"en":"Conveyed information about means communicated details or meaning about someone or something.","zh":"「conveyed information about」意思是傳達關於某人或某物的細節或意義。"},{"en":"A school badge can convey information about a student’s school or team.","zh":"校徽可以傳達關於學生學校或隊伍的資料。"},{"en":"If tattoos conveyed information about owners, people could read identity from the body.","zh":"如果紋身傳達關於擁有者的資料，人們便能從身體讀出身份。"},{"en":"The phrase shows that something visible can act like a message.","zh":"這個短語顯示可見事物可以像訊息一樣運作。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":16},{"front":"its owner","meaning":"其擁有者","examples":[{"en":"A tattoo conveyed information about its owner.","zh":"紋身傳達關於其擁有者的資料。"},{"en":"Its owner means the person who possesses or carries the thing being discussed.","zh":"「its owner」指擁有或承載正在討論的事物的人。"},{"en":"A phone case can reveal something about its owner’s taste.","zh":"手機殼可以揭示其擁有者的品味。"},{"en":"If a tattoo gives information about its owner, the body becomes a form of record.","zh":"如果紋身提供關於其擁有者的資料，身體便成為一種記錄。"},{"en":"The phrase connects an object or mark to the person it belongs to.","zh":"這個短語把物件或標記與所屬的人連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":16},{"front":"a traditional means of","meaning":"……的傳統方法","examples":[{"en":"A tattoo was a traditional means of acquiring spiritual power.","zh":"紋身是獲得靈性力量的傳統方法。"},{"en":"A traditional means of doing something is an old accepted way to achieve it.","zh":"「a traditional means of」做某事，指達成它的古老且被接受的方法。"},{"en":"Storytelling is a traditional means of teaching children community values.","zh":"說故事是教孩子社群價值的傳統方法。"},{"en":"If tattoos were a traditional means of gaining power, they had ritual importance.","zh":"如果紋身是獲得力量的傳統方法，它們便有儀式重要性。"},{"en":"The phrase describes a culturally accepted method.","zh":"這個短語描述文化上被接受的方法。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":17},{"front":"acquiring spiritual power","meaning":"獲得靈性力量","examples":[{"en":"Tattoos were a way of acquiring spiritual power.","zh":"紋身是獲得靈性力量的一種方式。"},{"en":"Acquiring spiritual power means gaining sacred, invisible or religious strength.","zh":"「acquiring spiritual power」意思是獲得神聖、不可見或宗教性的力量。"},{"en":"Some rituals are believed to help people acquire spiritual power or protection.","zh":"有些儀式被認為能幫助人獲得靈性力量或保護。"},{"en":"If tattoos were linked to acquiring spiritual power, they were not only decorative.","zh":"如果紋身與獲得靈性力量有關，它們就不只是裝飾。"},{"en":"The phrase belongs to belief systems and ritual practice.","zh":"這個短語屬於信仰系統和儀式實踐。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":17},{"front":"protection and strength","meaning":"保護和力量","examples":[{"en":"Tattoos were connected with protection and strength.","zh":"紋身與保護和力量有關。"},{"en":"Protection and strength mean safety from harm and the power to endure or act.","zh":"「protection and strength」指免受傷害的安全，以及忍受或行動的力量。"},{"en":"A charm may be worn for protection and strength in a difficult journey.","zh":"人們可能在艱難旅程中佩戴護身符，以求保護和力量。"},{"en":"If tattoos symbolised protection and strength, people may have valued them for spiritual reasons.","zh":"如果紋身象徵保護和力量，人們可能因靈性原因重視它們。"},{"en":"The phrase joins defensive power with inner or physical force.","zh":"這個短語把防護力量與內在或身體力量結合起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":17},{"front":"indicate character","meaning":"顯示性格","examples":[{"en":"Polynesians used tattoos to indicate character.","zh":"波利尼西亞人用紋身顯示性格。"},{"en":"Indicate character means show a person’s qualities, nature or moral traits.","zh":"「indicate character」意思是顯示一個人的品質、本性或道德特徵。"},{"en":"A person’s actions often indicate character more clearly than their words.","zh":"一個人的行動常比言語更清楚顯示性格。"},{"en":"If tattoos indicated character, they communicated ideas about courage, identity or worth.","zh":"如果紋身顯示性格，它們傳達關於勇氣、身份或價值的想法。"},{"en":"The phrase links outward signs with inner qualities.","zh":"這個短語把外在標記與內在品質連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":17},{"front":"position and level within a hierarchy","meaning":"在等級制度中的位置和層級","examples":[{"en":"Tattoos indicated a person’s position and level within a hierarchy.","zh":"紋身顯示一個人在等級制度中的位置和層級。"},{"en":"Position and level within a hierarchy means where someone stands in an ordered social system.","zh":"「position and level within a hierarchy」指某人在有秩序的社會系統中的位置。"},{"en":"In a company, job titles show position and level within a hierarchy.","zh":"在公司中，職銜顯示一個人在等級制度中的位置和層級。"},{"en":"If tattoos showed hierarchy, people could recognise authority and social distance.","zh":"如果紋身顯示等級制度，人們便能認出權威和社會距離。"},{"en":"The phrase is about structured ranking.","zh":"這個短語關於有結構的排名。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":17},{"front":"hierarchy","meaning":"等級制度","examples":[{"en":"Tattoos showed a person’s level within a hierarchy.","zh":"紋身顯示一個人在等級制度中的層級。"},{"en":"A hierarchy is a system in which people or things are ranked at different levels.","zh":"「hierarchy」是人或事物被排列在不同層級的系統。"},{"en":"A school has a hierarchy of students, teachers, department heads and principals.","zh":"學校有學生、老師、科主任和校長組成的等級制度。"},{"en":"In a hierarchy, higher levels usually have more authority or respect.","zh":"在等級制度中，較高層級通常有更多權威或尊重。"},{"en":"The word helps explain organised social ranking.","zh":"這個詞幫助解釋有組織的社會排名。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":17},{"front":"life force","meaning":"生命力","examples":[{"en":"Mana can mean spiritual power or life force.","zh":"mana 可以指靈性力量或生命力。"},{"en":"Life force means the energy or power believed to make living beings alive and strong.","zh":"「life force」指被認為使生命存在並強大的能量或力量。"},{"en":"Some traditions believe that rituals can protect a person’s life force.","zh":"有些傳統相信儀式可以保護一個人的生命力。"},{"en":"If mana means life force, tattoos may be linked to deep spiritual ideas.","zh":"如果 mana 指生命力，紋身可能與深層靈性觀念有關。"},{"en":"The phrase is spiritual and symbolic rather than a simple medical term.","zh":"這個短語是靈性和象徵性的，而不是簡單醫學術語。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":17},{"front":"displayed through","meaning":"透過……展示","examples":[{"en":"A person’s mana was displayed through their tattoo.","zh":"一個人的 mana 透過其紋身展示。"},{"en":"Displayed through means shown by means of something.","zh":"「displayed through」意思是透過某事物顯示出來。"},{"en":"A school’s values may be displayed through how teachers treat students.","zh":"學校的價值觀可以透過老師如何對待學生展示出來。"},{"en":"If spiritual power was displayed through tattoos, the body carried invisible meaning visibly.","zh":"如果靈性力量透過紋身展示，身體便把不可見意義可見化。"},{"en":"The phrase connects an inner quality with an outward form.","zh":"這個短語把內在品質與外在形式連繫起來。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":17},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"Students decide whether the following statements agree with the passage.","zh":"學生判斷以下陳述是否與文章一致。"},{"en":"Do the following statements agree with asks whether the statements match the information in the text.","zh":"「do the following statements agree with」是問這些陳述是否符合文本資料。"},{"en":"In a reading test, students compare each statement with the passage before choosing an answer.","zh":"在閱讀測驗中，學生先把每句陳述與文章比較，再選答案。"},{"en":"If a statement adds a claim not found in the text, it may not agree with the passage.","zh":"如果陳述加入文本沒有的說法，它可能不與文章一致。"},{"en":"This instruction tests careful evidence checking.","zh":"這條指示測試仔細核對證據的能力。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":17},{"front":"information given in","meaning":"……中提供的資料","examples":[{"en":"The answers must match the information given in the passage.","zh":"答案必須符合文章中提供的資料。"},{"en":"Information given in means facts or details directly provided in a text, chart or source.","zh":"「information given in」指文本、圖表或來源中直接提供的事實或細節。"},{"en":"Students should use the information given in the table, not outside knowledge.","zh":"學生應使用表格中提供的資料，而不是外部知識。"},{"en":"If the information given in the passage is limited, the answer may be Not Given.","zh":"如果文章中提供的資料有限，答案可能是 Not Given。"},{"en":"The phrase reminds learners to base answers on evidence.","zh":"這個短語提醒學習者根據證據作答。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":17},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生把答案寫在答題紙上。"},{"en":"An answer sheet is the paper or form where students record test answers.","zh":"「answer sheet」是學生記錄測驗答案的紙張或表格。"},{"en":"In an exam, writing on the wrong page may mean the answer sheet is incomplete.","zh":"在考試中，如果寫錯頁面，答題紙可能不完整。"},{"en":"Students should check the answer sheet before time ends.","zh":"學生應在時間結束前檢查答題紙。"},{"en":"The phrase refers to the official place for answers.","zh":"這個短語指正式填寫答案的地方。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":17},{"front":"if the statement agrees with","meaning":"如果陳述與……一致","examples":[{"en":"Students write YES if the statement agrees with the information.","zh":"如果陳述與資料一致，學生寫 YES。"},{"en":"If the statement agrees with means if it matches what the text says.","zh":"「if the statement agrees with」意思是如果陳述符合文本所說。"},{"en":"Students choose YES only when the statement and passage say the same thing.","zh":"只有當陳述和文章說同一件事時，學生才選 YES。"},{"en":"If the statement agrees with only half the evidence, students should read again carefully.","zh":"如果陳述只符合一半證據，學生應再次仔細閱讀。"},{"en":"The phrase is common in Yes, No, Not Given questions.","zh":"這個短語常見於 Yes, No, Not Given 題型。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":18},{"front":"if the statement contradicts","meaning":"如果陳述與……矛盾","examples":[{"en":"Students write NO if the statement contradicts the information.","zh":"如果陳述與資料矛盾，學生寫 NO。"},{"en":"If the statement contradicts means if it says the opposite of the information.","zh":"「if the statement contradicts」意思是如果陳述說出與資料相反的內容。"},{"en":"If the passage says a custom was common but the statement says it was rare, the statement contradicts it.","zh":"如果文章說某習俗很常見，但陳述說它很罕見，該陳述便與文章矛盾。"},{"en":"Students should choose NO only when there is a clear conflict.","zh":"學生只應在有清楚衝突時選 NO。"},{"en":"The phrase tests whether learners can identify disagreement with the text.","zh":"這個短語測試學習者能否辨認與文本不一致的地方。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":18},{"front":"no information on this","meaning":"沒有這方面的資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有這方面的資料，學生寫 NOT GIVEN。"},{"en":"No information on this means the text does not provide clear evidence about the point.","zh":"「no information on this」意思是文本沒有提供關於該點的清楚證據。"},{"en":"If the passage never says whether Firth was the first scholar, there is no information on this.","zh":"如果文章從未說 Firth 是否首位學者，便沒有這方面的資料。"},{"en":"A statement may sound likely, but without textual support it can still be Not Given.","zh":"某陳述可能聽起來合理，但沒有文本支持時仍可能是 Not Given。"},{"en":"The phrase helps students avoid guessing.","zh":"這個短語幫助學生避免猜測。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":18},{"front":"interested in researching","meaning":"有興趣研究","examples":[{"en":"Scientists are interested in researching Tikopia.","zh":"科學家有興趣研究 Tikopia。"},{"en":"Interested in researching means wanting to study something carefully and systematically.","zh":"「interested in researching」意思是想仔細而有系統地研究某事。"},{"en":"Doctors may be interested in researching why a disease affects one group more than another.","zh":"醫生可能有興趣研究為何某疾病對一個群體影響較大。"},{"en":"Scholars may be interested in researching a remote island because it preserves unusual traditions.","zh":"學者可能有興趣研究偏遠島嶼，因為它保存獨特傳統。"},{"en":"The phrase shows research curiosity, not casual interest only.","zh":"這個短語顯示研究上的好奇，而不只是普通興趣。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":18},{"front":"because of the island’s remoteness","meaning":"因為該島偏遠","examples":[{"en":"The statement asks whether scholars study Tikopia because of the island’s remoteness.","zh":"該陳述問學者是否因為該島偏遠而研究 Tikopia。"},{"en":"Because of the island’s remoteness means due to the fact that the island is far away and isolated.","zh":"「because of the island’s remoteness」意思是由於該島遙遠而孤立。"},{"en":"Researchers may visit a place because of its remoteness if isolation has preserved local customs.","zh":"如果孤立保存了本地習俗，研究人員可能因為某地偏遠而到訪。"},{"en":"Remoteness can attract scholars, but it can also make fieldwork difficult.","zh":"偏遠可以吸引學者，但也會令田野工作困難。"},{"en":"The phrase gives a possible reason for interest.","zh":"這個短語提供一個可能的興趣原因。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":18},{"front":"the first scholar to study","meaning":"首位研究……的學者","examples":[{"en":"The question asks whether Firth was the first scholar to study Tikopia.","zh":"問題問 Firth 是否首位研究 Tikopia 的學者。"},{"en":"The first scholar to study something is the earliest academic researcher known to examine it.","zh":"「the first scholar to study」某事，指最早已知研究該事的學術研究者。"},{"en":"Students should not call someone the first scholar to study a topic unless the text clearly says so.","zh":"除非文本清楚說明，學生不應稱某人為首位研究某主題的學者。"},{"en":"If earlier writers visited the island, Firth may not have been the first scholar to study it.","zh":"如果早期作者曾到訪該島，Firth 可能不是首位研究它的學者。"},{"en":"The phrase asks about historical priority.","zh":"這個短語問的是歷史先後。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":18},{"front":"cultural differences","meaning":"文化差異","examples":[{"en":"The question refers to cultural differences on Tikopia and other islands.","zh":"問題指 Tikopia 與其他島嶼上的文化差異。"},{"en":"Cultural differences are differences in customs, values, language, beliefs or social behaviour.","zh":"「cultural differences」是習俗、價值觀、語言、信念或社會行為上的差異。"},{"en":"Travellers may notice cultural differences in greetings, meals and family roles.","zh":"旅客可能在問候、用餐和家庭角色中注意到文化差異。"},{"en":"Cultural differences can lead to misunderstanding if people judge too quickly.","zh":"如果人們太快判斷，文化差異可能導致誤解。"},{"en":"The phrase helps compare how communities live and think.","zh":"這個短語幫助比較社群如何生活和思考。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":18},{"front":"as well as","meaning":"以及","examples":[{"en":"The statement mentions Tikopia as well as other Pacific islands.","zh":"該陳述提到 Tikopia 以及其他太平洋島嶼。"},{"en":"As well as means in addition to or together with.","zh":"「as well as」意思是此外、以及或連同。"},{"en":"The course teaches speaking as well as writing.","zh":"這門課教授口語以及寫作。"},{"en":"If an article discusses Tikopia as well as other islands, students must compare more than one place.","zh":"如果文章討論 Tikopia 以及其他島嶼，學生必須比較不止一個地方。"},{"en":"The phrase adds another item without replacing the first one.","zh":"這個短語加入另一項，而不是取代第一項。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":18},{"front":"other Pacific islands","meaning":"其他太平洋島嶼","examples":[{"en":"The question refers to other Pacific islands.","zh":"問題指其他太平洋島嶼。"},{"en":"Other Pacific islands means islands in the Pacific apart from the one already mentioned.","zh":"「other Pacific islands」意思是已提到的島嶼以外的太平洋島嶼。"},{"en":"A researcher may compare Tikopia with other Pacific islands to find similarities and differences.","zh":"研究人員可能把 Tikopia 與其他太平洋島嶼比較，以找出相似和差異。"},{"en":"Looking at other Pacific islands prevents students from treating one island as typical of all.","zh":"觀察其他太平洋島嶼，可以避免學生把一個島視為所有島嶼的典型。"},{"en":"The phrase widens the comparison beyond Tikopia.","zh":"這個短語把比較擴展到 Tikopia 以外。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":18},{"front":"evolved from","meaning":"由……演變而來","examples":[{"en":"The English word “tattoo” evolved from the island’s local language.","zh":"英文單詞 “tattoo” 由該島的當地語言演變而來。"},{"en":"Evolved from means developed gradually from an earlier form or source.","zh":"「evolved from」意思是從較早形式或來源逐漸發展而來。"},{"en":"Many English words evolved from Latin, French or other languages.","zh":"許多英文詞由拉丁文、法文或其他語言演變而來。"},{"en":"If a word evolved from a local language, it shows cultural contact over time.","zh":"如果一個詞由當地語言演變而來，它顯示長時間的文化接觸。"},{"en":"The phrase describes gradual development, not sudden invention.","zh":"這個短語描述逐漸發展，而不是突然發明。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":18},{"front":"local language","meaning":"當地語言","examples":[{"en":"The word “tattoo” comes from a local language.","zh":"“tattoo” 這個詞來自當地語言。"},{"en":"Local language means the language spoken by people in a particular place or community.","zh":"「local language」指特定地方或社群的人所說的語言。"},{"en":"Learning a local language can help visitors understand customs more respectfully.","zh":"學習當地語言可以幫助訪客更尊重地理解習俗。"},{"en":"When a word enters English from a local language, it may carry cultural meaning.","zh":"當一個詞從當地語言進入英文，它可能帶有文化意義。"},{"en":"The phrase highlights language rooted in a specific community.","zh":"這個短語強調植根於特定社群的語言。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":18},{"front":"label the diagram below","meaning":"為下圖加上標籤","examples":[{"en":"Students label the diagram below using words from the passage.","zh":"學生使用文章中的詞語為下圖加上標籤。"},{"en":"Label the diagram below means write correct names or terms on the picture underneath.","zh":"「label the diagram below」意思是在下方圖片上寫上正確名稱或詞語。"},{"en":"In a biology test, students may label the diagram below with parts of a flower.","zh":"在生物測驗中，學生可能為下圖加上花朵各部分的標籤。"},{"en":"To label a diagram correctly, students must match words with exact locations.","zh":"要正確標示圖表，學生必須把詞語與準確位置配對。"},{"en":"The phrase gives an instruction for a visual question.","zh":"這個短語是視覺題的指示。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":19},{"front":"choose no more than two words","meaning":"選擇不多於兩個字","examples":[{"en":"Students choose no more than two words from the passage.","zh":"學生從文章中選擇不多於兩個字。"},{"en":"Choose no more than two words means select one or two words only.","zh":"「choose no more than two words」意思是只選一個或兩個字。"},{"en":"If the instruction says no more than two words, a three-word answer is wrong.","zh":"如果指示說不多於兩個字，三個字的答案就是錯的。"},{"en":"Students must copy words carefully and count them before writing the answer.","zh":"學生必須仔細抄寫詞語，並在作答前數清字數。"},{"en":"The phrase sets a strict word limit.","zh":"這個短語設定嚴格字數限制。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":19},{"front":"complete the notes below","meaning":"完成以下筆記","examples":[{"en":"Students complete the notes below using words from the passage.","zh":"學生使用文章中的詞語完成以下筆記。"},{"en":"Complete the notes below means fill missing information into the notes underneath.","zh":"「complete the notes below」意思是在下方筆記中填上缺漏資料。"},{"en":"In a listening test, students complete the notes below while hearing a talk.","zh":"在聆聽測驗中，學生邊聽講座邊完成以下筆記。"},{"en":"To complete notes correctly, students must identify key words, not copy whole sentences.","zh":"要正確完成筆記，學生必須辨認關鍵詞，而不是抄整句。"},{"en":"The phrase gives an instruction for note-completion questions.","zh":"這個短語是筆記填充題的指示。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":19},{"front":"location on the body","meaning":"身體部位","examples":[{"en":"The table asks for the location on the body.","zh":"表格要求填寫身體部位。"},{"en":"Location on the body means the exact body part where something appears.","zh":"「location on the body」指某物出現的準確身體部位。"},{"en":"In a medical form, patients may mark the location on the body where pain occurs.","zh":"在醫療表格中，病人可能標出疼痛發生的身體部位。"},{"en":"For tattoos, location on the body can change the meaning of the design.","zh":"對紋身而言，身體部位可以改變圖案的意義。"},{"en":"The phrase asks where something is placed physically.","zh":"這個短語問某物實際放在哪裡。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":19},{"front":"significance","meaning":"意義；象徵意義","examples":[{"en":"The tattoo’s significance depended on its location.","zh":"紋身的意義取決於其位置。"},{"en":"Significance means importance, meaning or symbolic value.","zh":"「significance」意思是重要性、含義或象徵價值。"},{"en":"A ring can have significance if it represents marriage or family memory.","zh":"如果戒指代表婚姻或家庭記憶，它就可以有意義。"},{"en":"The significance of a tattoo may change depending on where it appears.","zh":"紋身的象徵意義可能因出現位置而改變。"},{"en":"The word asks why something matters.","zh":"這個詞問的是某事為何重要。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":19},{"front":"geometric pattern","meaning":"幾何圖案","examples":[{"en":"The notes include the geometric pattern of some tattoos.","zh":"筆記包括一些紋身的幾何圖案。"},{"en":"A geometric pattern is a design made from shapes such as lines, circles, squares or triangles.","zh":"「geometric pattern」是由線條、圓形、正方形或三角形等形狀組成的圖案。"},{"en":"Floor tiles often use geometric patterns to create repeated designs.","zh":"地磚常使用幾何圖案來形成重複設計。"},{"en":"In tattooing, a geometric pattern can be simple in shape but rich in meaning.","zh":"在紋身中，幾何圖案形狀可以簡單，但意義豐富。"},{"en":"The phrase describes the visual form of a design.","zh":"這個短語描述圖案的視覺形式。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":19},{"front":"of the male face","meaning":"男性面部的……","examples":[{"en":"The table refers to different areas of the male face.","zh":"表格指男性面部的不同位置。"},{"en":"Of the male face means belonging to or located on a man’s face.","zh":"「of the male face」意思是屬於或位於男性面部。"},{"en":"A diagram of the male face may label the forehead, cheeks, chin and jaw.","zh":"男性面部圖表可能標示額頭、面頰、下巴和下顎。"},{"en":"If tattoo meanings differ across areas of the male face, exact location matters.","zh":"如果男性面部不同位置的紋身意義不同，準確位置就很重要。"},{"en":"The phrase narrows the body part being discussed.","zh":"這個短語收窄正在討論的身體部位。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":19},{"front":"prestige","meaning":"威望；聲望","examples":[{"en":"Some tattoos could indicate prestige or high status.","zh":"有些紋身可以顯示威望或高地位。"},{"en":"Prestige means respect, honour or admiration given to someone because of rank or achievement.","zh":"「prestige」指因階級或成就而獲得的尊重、榮譽或仰慕。"},{"en":"A famous university may have prestige because people respect its history and standards.","zh":"著名大學可能因其歷史和標準受尊重而有聲望。"},{"en":"If tattoos indicated prestige, they helped others recognise social importance.","zh":"如果紋身顯示威望，它們幫助他人認出社會重要性。"},{"en":"The word refers to honour and reputation, not money only.","zh":"這個詞指榮譽和名聲，而不只是金錢。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":19},{"front":"right side of a woman’s face","meaning":"女性面部右側","examples":[{"en":"The question mentions the right side of a woman’s face.","zh":"問題提到女性面部右側。"},{"en":"The right side of a woman’s face means the side of her face on her right-hand side.","zh":"「right side of a woman’s face」指她右手邊的面部一側。"},{"en":"A diagram may label the right side of a woman’s face differently from the left side.","zh":"圖表可能把女性面部右側與左側作不同標示。"},{"en":"If each side carries different ancestry, the right side can have a specific meaning.","zh":"如果每一側承載不同血統，右側就可以有特定意義。"},{"en":"The phrase gives a precise side and body location.","zh":"這個短語提供準確側面和身體位置。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":19},{"front":"male back","meaning":"男性背部","examples":[{"en":"The manutahi design was placed on the male back.","zh":"manutahi 圖案位於男性背部。"},{"en":"Male back means the back part of a man’s body.","zh":"「male back」指男性身體的背部。"},{"en":"A large tattoo design may be placed on the male back because it offers space.","zh":"大型紋身圖案可能置於男性背部，因為那裡空間較大。"},{"en":"If a design on the male back is shown at gatherings, it can express pride publicly.","zh":"如果男性背部的圖案在聚會中展示，它可以公開表達自豪。"},{"en":"The phrase names both gender and body location.","zh":"這個短語同時指出性別和身體位置。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":19},{"front":"sense of pride","meaning":"自豪感","examples":[{"en":"The manutahi design was linked with a sense of pride.","zh":"manutahi 圖案與自豪感有關。"},{"en":"A sense of pride is a feeling of self-respect and satisfaction about who one is or what one has done.","zh":"「sense of pride」是對自己身份或成就感到自尊和滿足的感覺。"},{"en":"A student may feel a sense of pride after improving through hard work.","zh":"學生透過努力取得進步後，可能感到自豪感。"},{"en":"If a tattoo creates a sense of pride, it supports identity and confidence.","zh":"如果紋身帶來自豪感，它便支持身份和信心。"},{"en":"The phrase describes an inner feeling, not just outward display.","zh":"這個短語描述內在感受，而不只是外在展示。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":19},{"front":"male chest","meaning":"男性胸口","examples":[{"en":"Rows of triangles appeared on the male chest.","zh":"一排排三角形出現在男性胸口。"},{"en":"Male chest means the front upper part of a man’s body.","zh":"「male chest」指男性身體前方上半部。"},{"en":"A medal, badge or tattoo on the male chest can be very visible in public.","zh":"男性胸口上的獎章、徽章或紋身在公共場合可以很顯眼。"},{"en":"If a pattern on the male chest indicated bravery, it carried a public message.","zh":"如果男性胸口上的圖案顯示勇敢，它就承載公開訊息。"},{"en":"The phrase gives a clear body location and gender.","zh":"這個短語提供清楚的身體位置和性別。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":20},{"front":"bravery","meaning":"勇敢","examples":[{"en":"The pattern on the chest indicated bravery.","zh":"胸口上的圖案顯示勇敢。"},{"en":"Bravery means courage, especially when facing danger, pain or fear.","zh":"「bravery」意思是勇氣，尤其是在面對危險、痛楚或恐懼時。"},{"en":"A firefighter shows bravery when entering a burning building to save others.","zh":"消防員進入燃燒中的建築物救人時，展現勇敢。"},{"en":"In a painful tattooing ritual, bravery could be shown by enduring the process.","zh":"在痛楚的紋身儀式中，忍受過程可以顯示勇敢。"},{"en":"The word refers to courage in action, not just confidence in words.","zh":"這個詞指行動中的勇氣，而不只是口頭上的信心。"}],"source":"140 - Tattoo on Tikopia.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 141":[{"front":"language strategy","meaning":"語言策略","examples":[{"en":"The passage evaluates language strategy in a multinational company.","zh":"文章評估一家跨國公司的語言策略。"},{"en":"A language strategy is a plan for managing communication across different languages.","zh":"語言策略是管理不同語言之間溝通的計劃。"},{"en":"A hotel may need a language strategy if many guests speak different languages.","zh":"如果酒店有很多說不同語言的客人，它可能需要語言策略。"},{"en":"Without a clear language strategy, staff may misunderstand customers and lose business.","zh":"沒有清晰語言策略，員工可能誤解顧客並失去生意。"},{"en":"A good language strategy decides when to use translation, training, or a common company language.","zh":"良好的語言策略會決定何時使用翻譯、培訓或公司共同語言。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":1},{"front":"multinational company","meaning":"跨國公司","examples":[{"en":"A multinational company must manage communication across different languages.","zh":"跨國公司必須管理不同語言之間的溝通。"},{"en":"A multinational company is a business that operates in more than one country.","zh":"跨國公司是在多於一個國家營運的企業。"},{"en":"A multinational company may have offices in Hong Kong, Germany, Brazil, and Japan.","zh":"跨國公司可能在香港、德國、巴西和日本都有辦公室。"},{"en":"If a multinational company cannot communicate clearly, projects across countries may slow down.","zh":"如果跨國公司不能清楚溝通，跨國項目可能放慢。"},{"en":"The phrase focuses on business activity across national borders.","zh":"這個短語強調跨越國界的商業活動。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":1},{"front":"language management","meaning":"語言管理","examples":[{"en":"The importance of language management in multinational companies has never been greater.","zh":"跨國公司中語言管理的重要性從未如此大。"},{"en":"Language management means organising how people use, translate, learn, and share languages at work.","zh":"語言管理指組織人們在工作中如何使用、翻譯、學習和分享語言。"},{"en":"A school with many non-local students needs language management for notices and parent meetings.","zh":"有很多非本地學生的學校需要語言管理來處理通告和家長會。"},{"en":"Poor language management can cause mistakes in contracts, emails, and customer service.","zh":"糟糕的語言管理可以導致合約、電郵和顧客服務出錯。"},{"en":"The phrase is useful when communication depends on more than one language.","zh":"當溝通依賴多於一種語言時，這個短語很有用。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":1},{"front":"has never been greater","meaning":"從未如此重要","examples":[{"en":"The importance of language management has never been greater.","zh":"語言管理的重要性從未如此重要。"},{"en":"Has never been greater means something is more important, serious, or strong now than ever before.","zh":"“Has never been greater” 指某事現在比以往任何時候都更重要、更嚴重或更強烈。"},{"en":"With more online shopping, the need for fast delivery has never been greater.","zh":"隨着網購增加，快速送貨的需要從未如此重要。"},{"en":"If students face more distractions, the value of concentration has never been greater.","zh":"如果學生面對更多分心事物，專注力的價值從未如此重要。"},{"en":"The phrase strongly emphasises the present level of importance.","zh":"這個短語強烈強調目前的重要程度。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":1},{"front":"be increasingly conscious of","meaning":"越來越意識到","examples":[{"en":"Multinationals are increasingly conscious of global coordination.","zh":"跨國公司越來越意識到全球協調。"},{"en":"To be increasingly conscious of something means to become more aware of its importance over time.","zh":"“Be increasingly conscious of” 某事指隨時間越來越意識到其重要性。"},{"en":"Parents are increasingly conscious of children’s screen time.","zh":"家長越來越意識到孩子使用螢幕的時間。"},{"en":"Companies become increasingly conscious of customer complaints when sales begin to fall.","zh":"當銷售開始下跌，公司會越來越意識到顧客投訴。"},{"en":"The phrase shows growing awareness, not sudden discovery.","zh":"這個短語顯示意識逐漸增加，而不是突然發現。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":1},{"front":"global coordination","meaning":"全球協調","examples":[{"en":"Global coordination can be a source of competitive advantage.","zh":"全球協調可以是競爭優勢的來源。"},{"en":"Global coordination means organising people, offices, and decisions across different countries.","zh":"全球協調指組織不同國家的人員、辦公室和決策。"},{"en":"An airline needs global coordination to manage flights, luggage, and customer support worldwide.","zh":"航空公司需要全球協調來管理全球航班、行李和顧客服務。"},{"en":"Poor global coordination can cause duplicated work and inconsistent service.","zh":"糟糕的全球協調可以造成工作重複和服務不一致。"},{"en":"The phrase is often used when a company wants different countries to work as one system.","zh":"當公司希望不同國家像一個系統般合作時，常使用這個短語。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":1},{"front":"a source of competitive advantage","meaning":"競爭優勢的來源","examples":[{"en":"Global coordination is a source of competitive advantage.","zh":"全球協調是競爭優勢的來源。"},{"en":"A source of competitive advantage is something that helps a company perform better than rivals.","zh":"競爭優勢的來源是幫助公司比競爭對手表現更好的事物。"},{"en":"Fast delivery can be a source of competitive advantage for an online shop.","zh":"快速送貨可以是網店競爭優勢的來源。"},{"en":"If language skills help a firm win overseas clients, they become a source of competitive advantage.","zh":"如果語言能力幫助公司贏得海外客戶，它就成為競爭優勢的來源。"},{"en":"The phrase explains where business strength comes from.","zh":"這個短語解釋商業優勢從何而來。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":1},{"front":"competitive advantage","meaning":"競爭優勢","examples":[{"en":"Effective language management can create competitive advantage.","zh":"有效語言管理可以創造競爭優勢。"},{"en":"Competitive advantage is an edge that helps a business succeed against competitors.","zh":"競爭優勢是幫助企業勝過競爭對手的優勢。"},{"en":"A café may gain competitive advantage through better service and clearer menus.","zh":"咖啡店可能透過更好服務和更清晰餐牌獲得競爭優勢。"},{"en":"If customers can get help in their own language, the company may gain competitive advantage.","zh":"如果顧客能以自己的語言獲得協助，公司可能獲得競爭優勢。"},{"en":"The phrase is common in business strategy and marketing.","zh":"這個短語常見於商業策略和市場營銷。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":1},{"front":"the ultimate barrier to","meaning":"……的最大障礙","examples":[{"en":"Language remains the ultimate barrier to international harmonisation.","zh":"語言仍然是國際協調一致的最大障礙。"},{"en":"The ultimate barrier to something is the greatest or most difficult obstacle blocking it.","zh":"“The ultimate barrier to” 某事指阻礙它的最大或最困難障礙。"},{"en":"Fear may be the ultimate barrier to speaking English confidently.","zh":"恐懼可能是自信說英語的最大障礙。"},{"en":"If two teams cannot understand each other’s language, communication becomes the ultimate barrier to cooperation.","zh":"如果兩隊人不能理解彼此語言，溝通就成為合作的最大障礙。"},{"en":"The phrase stresses that one problem is more serious than others.","zh":"這個短語強調某個問題比其他問題更嚴重。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":1},{"front":"international harmonisation","meaning":"國際協調一致","examples":[{"en":"Language remains a barrier to international harmonisation.","zh":"語言仍然是國際協調一致的障礙。"},{"en":"International harmonisation means making systems, rules, or practices more consistent across countries.","zh":"國際協調一致指令不同國家的制度、規則或做法更一致。"},{"en":"Banks need international harmonisation when they follow common rules for payments.","zh":"銀行遵守共同付款規則時，需要國際協調一致。"},{"en":"Without international harmonisation, branches in different countries may work in conflicting ways.","zh":"沒有國際協調一致，不同國家的分公司可能以互相衝突的方式工作。"},{"en":"The phrase is often used for global business, law, and regulation.","zh":"這個短語常用於全球商業、法律和規管。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":1},{"front":"before considering","meaning":"在考慮……之前","examples":[{"en":"Companies must evaluate the language barrier before considering strategies.","zh":"公司在考慮策略之前，必須評估語言障礙。"},{"en":"Before considering something means before thinking seriously about that option or decision.","zh":"“Before considering” 某事指在認真思考該選項或決定之前。"},{"en":"Students should understand the question before considering possible answers.","zh":"學生在考慮可能答案之前，應先理解題目。"},{"en":"A family should check its budget before considering a new car.","zh":"家庭在考慮新車之前，應先檢查預算。"},{"en":"The phrase shows that one step should happen before another.","zh":"這個短語顯示一個步驟應先於另一個步驟發生。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":1},{"front":"language-management strategies","meaning":"語言管理策略","examples":[{"en":"Companies need language-management strategies to operate internationally.","zh":"公司需要語言管理策略才能在國際上營運。"},{"en":"Language-management strategies are plans for dealing with language problems in communication and business.","zh":"語言管理策略是處理溝通和商業中語言問題的計劃。"},{"en":"A company may use translators, bilingual staff, and training as language-management strategies.","zh":"公司可能使用筆譯員、雙語員工和培訓作為語言管理策略。"},{"en":"Without language-management strategies, overseas customers may feel ignored or misunderstood.","zh":"沒有語言管理策略，海外顧客可能感到被忽視或被誤解。"},{"en":"The phrase focuses on practical methods for handling multilingual work.","zh":"這個短語強調處理多語工作環境的實際方法。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":2},{"front":"evaluate the magnitude of","meaning":"評估……的程度","examples":[{"en":"Companies must evaluate the magnitude of the language barrier.","zh":"公司必須評估語言障礙的程度。"},{"en":"To evaluate the magnitude of something means to judge how large, serious, or difficult it is.","zh":"“Evaluate the magnitude of” 某事指判斷它有多大、多嚴重或多困難。"},{"en":"A hospital must evaluate the magnitude of staff shortages before hiring temporary nurses.","zh":"醫院在聘請臨時護士前，必須評估人手短缺的程度。"},{"en":"If a business underestimates the magnitude of a problem, its solution may be too weak.","zh":"如果企業低估問題的程度，其解決方案可能太弱。"},{"en":"The phrase is useful when measuring the scale of a challenge.","zh":"這個短語適合用於衡量挑戰的規模。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":2},{"front":"language barrier","meaning":"語言障礙","examples":[{"en":"The language barrier can prevent international communication.","zh":"語言障礙可以阻礙國際溝通。"},{"en":"A language barrier is a communication problem caused by people not sharing the same language.","zh":"語言障礙是由人們不使用同一語言造成的溝通問題。"},{"en":"A tourist may face a language barrier when asking for directions abroad.","zh":"遊客在外國問路時可能面對語言障礙。"},{"en":"Language barriers can cause delays, mistakes, and frustration in customer service.","zh":"語言障礙可以在顧客服務中造成延誤、錯誤和挫折。"},{"en":"The phrase is common when people cannot understand one another clearly.","zh":"當人們不能清楚理解彼此時，常使用這個短語。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":2},{"front":"confront someone","meaning":"擺在某人面前；使某人面對","examples":[{"en":"Companies must evaluate the language barrier confronting them.","zh":"公司必須評估擺在它們面前的語言障礙。"},{"en":"If a problem confronts someone, it stands in front of them and must be dealt with.","zh":"如果一個問題 confronts 某人，它就是擺在他面前並必須處理的問題。"},{"en":"New students may be confronted by unfamiliar rules on their first school day.","zh":"新學生在開學第一天可能面對陌生規則。"},{"en":"When rising costs confront a family, they may need to change their spending habits.","zh":"當上升成本擺在家庭面前，他們可能需要改變消費習慣。"},{"en":"The phrase makes a problem sound direct and unavoidable.","zh":"這個短語令問題聽起來直接而無法避免。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":2},{"front":"examine three dimensions","meaning":"審視三個層面","examples":[{"en":"Companies need to examine three dimensions of the language problem.","zh":"公司需要審視語言問題的三個層面。"},{"en":"To examine three dimensions means to look carefully at three different aspects of a problem.","zh":"“Examine three dimensions” 指仔細查看問題的三個不同方面。"},{"en":"A teacher may examine three dimensions of poor writing: grammar, ideas, and organisation.","zh":"老師可能審視寫作差的三個層面：文法、想法和組織。"},{"en":"If a company examines only one dimension, it may miss other important risks.","zh":"如果公司只審視一個層面，可能錯過其他重要風險。"},{"en":"The phrase helps divide a complex issue into clearer parts.","zh":"這個短語有助把複雜問題分成較清晰部分。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":2},{"front":"language diversity","meaning":"語言多樣性","examples":[{"en":"Language diversity is one dimension of the language barrier.","zh":"語言多樣性是語言障礙的一個層面。"},{"en":"Language diversity means the presence of many different languages in one place or situation.","zh":"語言多樣性指在一個地方或情況中存在許多不同語言。"},{"en":"A hospital with patients from many countries faces language diversity every day.","zh":"有來自許多國家病人的醫院每天都面對語言多樣性。"},{"en":"Language diversity can enrich a workplace, but it also requires careful communication support.","zh":"語言多樣性可以豐富工作場所，但也需要謹慎的溝通支援。"},{"en":"The phrase focuses on the number and variety of languages involved.","zh":"這個短語強調涉及語言的數量和種類。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":2},{"front":"language penetration","meaning":"語言普及程度","examples":[{"en":"Companies must consider language penetration when forming a strategy.","zh":"公司制定策略時必須考慮語言普及程度。"},{"en":"Language penetration means how widely a language is understood or used in a market or group.","zh":"語言普及程度指某種語言在市場或群體中被理解或使用得有多廣泛。"},{"en":"If English penetration is low in a country, English-only advertising may fail.","zh":"如果某國英語普及程度低，只用英語宣傳可能失敗。"},{"en":"High language penetration makes communication easier because more people understand the language.","zh":"高語言普及程度令溝通更容易，因為更多人理解該語言。"},{"en":"The phrase helps companies judge whether one language can reach enough people.","zh":"這個短語幫助公司判斷一種語言能否接觸足夠多人。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":2},{"front":"language sophistication","meaning":"語言複雜程度","examples":[{"en":"Language sophistication affects how difficult communication becomes.","zh":"語言複雜程度影響溝通會變得多困難。"},{"en":"Language sophistication means how complex, technical, or advanced the language needed is.","zh":"語言複雜程度指所需語言有多複雜、專門或高階。"},{"en":"Daily greetings require little language sophistication, but legal contracts require much more.","zh":"日常問候需要很少語言複雜程度，但法律合約需要多得多。"},{"en":"If language sophistication is high, simple translation may not be enough.","zh":"如果語言複雜程度高，簡單翻譯可能不足夠。"},{"en":"The phrase helps explain why some communication tasks are harder than others.","zh":"這個短語幫助解釋為何某些溝通任務更困難。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":2},{"front":"how best to manage","meaning":"如何最有效地管理","examples":[{"en":"Companies must decide how best to manage language.","zh":"公司必須決定如何最有效地管理語言。"},{"en":"How best to manage something means the most effective way to handle it.","zh":"“How best to manage” 某事指處理它的最有效方法。"},{"en":"A teacher must decide how best to manage a noisy class.","zh":"老師必須決定如何最有效地管理嘈吵班級。"},{"en":"If a company knows the risks, it can decide how best to manage communication.","zh":"如果公司知道風險，就能決定如何最有效地管理溝通。"},{"en":"The phrase is useful when comparing possible solutions.","zh":"這個短語適合比較可能解決方案時使用。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":2},{"front":"a range of options","meaning":"一系列選項","examples":[{"en":"Companies can choose from a range of options.","zh":"公司可以從一系列選項中選擇。"},{"en":"A range of options means several possible choices.","zh":"“A range of options” 指幾個可能選擇。"},{"en":"Students should consider a range of options before choosing a university course.","zh":"學生選擇大學課程前應考慮一系列選項。"},{"en":"Having a range of options allows a company to match the solution to the problem.","zh":"擁有一系列選項讓公司可以把解決方案配對問題。"},{"en":"The phrase suggests flexibility rather than one fixed answer.","zh":"這個短語暗示靈活性，而不是一個固定答案。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":2},{"front":"formulate a strategy","meaning":"制定策略","examples":[{"en":"Companies must consider many factors when formulating their strategy.","zh":"公司在制定策略時必須考慮許多因素。"},{"en":"To formulate a strategy means to design a clear plan for reaching a goal.","zh":"“Formulate a strategy” 指設計達成目標的清晰計劃。"},{"en":"A school may formulate a strategy to help weak readers improve within one year.","zh":"學校可能制定策略，幫助閱讀能力較弱的學生在一年內進步。"},{"en":"If leaders formulate a strategy without data, the plan may miss real problems.","zh":"如果領袖沒有數據就制定策略，計劃可能錯過真正問題。"},{"en":"The phrase is more formal than simply saying “make a plan”.","zh":"這個短語比簡單說 “make a plan” 更正式。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":2},{"front":"lingua franca","meaning":"通用語；共同語言","examples":[{"en":"English is often used as a lingua franca in international business.","zh":"英語在國際商業中常被用作通用語。"},{"en":"A lingua franca is a common language used by people who do not share the same mother tongue.","zh":"通用語是沒有共同母語的人用來溝通的共同語言。"},{"en":"At an international conference, English may become the lingua franca for speakers from many countries.","zh":"在國際會議上，英語可能成為來自多國講者的通用語。"},{"en":"A lingua franca can help communication, but it may not solve every cultural misunderstanding.","zh":"通用語可以幫助溝通，但未必解決每個文化誤解。"},{"en":"The phrase is often used in global business, travel, and education.","zh":"這個短語常用於全球商業、旅遊和教育。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":3},{"front":"the simplest answer","meaning":"最簡單的答案","examples":[{"en":"The simplest answer is to rely on one’s native tongue.","zh":"最簡單的答案是依賴自己的母語。"},{"en":"The simplest answer means the easiest solution to think of first.","zh":"“The simplest answer” 指最容易首先想到的解決方法。"},{"en":"When a phone freezes, the simplest answer may be to restart it.","zh":"當手機當機，最簡單的答案可能是重新啟動它。"},{"en":"The simplest answer is not always the best answer when the problem is complex.","zh":"當問題複雜時，最簡單的答案不一定是最佳答案。"},{"en":"The phrase often introduces a solution before showing its limits.","zh":"這個短語常先提出一個解決方法，再展示其限制。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":3},{"front":"realistic only for","meaning":"只對……而言實際可行","examples":[{"en":"Relying on one language is realistic only for English-speaking companies.","zh":"依賴一種語言只對以英語為主要語言的公司而言實際可行。"},{"en":"Realistic only for a group means practical or possible only for that group, not for everyone.","zh":"“Realistic only for” 某群體指只對該群體實際或可行，不適用於所有人。"},{"en":"Buying a large office is realistic only for companies with stable income.","zh":"購買大型辦公室只對收入穩定的公司而言實際可行。"},{"en":"If a solution is realistic only for rich schools, poorer schools need another plan.","zh":"如果某方案只對富裕學校而言實際可行，較貧窮學校便需要另一個計劃。"},{"en":"The phrase limits where an idea can work.","zh":"這個短語限制一個想法可行的地方。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":3},{"front":"English-speaking companies","meaning":"以英語為主要語言的公司","examples":[{"en":"English-speaking companies may be tempted to rely only on English.","zh":"以英語為主要語言的公司可能傾向只依賴英語。"},{"en":"English-speaking companies are companies whose main working language is English.","zh":"以英語為主要語言的公司是主要工作語言為英語的公司。"},{"en":"English-speaking companies may find overseas communication easier in some markets but harder in others.","zh":"以英語為主要語言的公司在某些市場可能較容易海外溝通，但在其他市場較困難。"},{"en":"If English-speaking companies ignore local languages, customers may feel excluded.","zh":"如果以英語為主要語言的公司忽視本地語言，顧客可能感到被排除。"},{"en":"The phrase describes companies by their main language, not only by their country.","zh":"這個短語按主要語言描述公司，而不只是按國家描述。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":3},{"front":"native tongue","meaning":"母語","examples":[{"en":"Some companies rely on their native tongue when trading abroad.","zh":"一些公司在海外貿易時依賴自己的母語。"},{"en":"A native tongue is the first language a person or group learns and uses naturally.","zh":"母語是一個人或群體最先學會並自然使用的語言。"},{"en":"Children usually express feelings most easily in their native tongue.","zh":"孩子通常最容易用母語表達感受。"},{"en":"Relying only on a native tongue may limit communication with overseas clients.","zh":"只依賴母語可能限制與海外客戶的溝通。"},{"en":"The phrase is similar to “mother tongue”.","zh":"這個短語與 “mother tongue” 意思相近。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":3},{"front":"as recently as","meaning":"近至……","examples":[{"en":"As recently as 1991, many British exporters used only English.","zh":"近至1991年，許多英國出口商仍只使用英語。"},{"en":"As recently as a time means surprisingly close to the present or to the period being discussed.","zh":"“As recently as” 某時間指該時間出乎意料地接近現在或正在討論的時期。"},{"en":"As recently as last year, the school still used paper forms for every application.","zh":"近至去年，學校仍為每項申請使用紙本表格。"},{"en":"If a company used old methods as recently as 2020, change may be slower than expected.","zh":"如果一家公司近至2020年仍使用舊方法，改變可能比預期慢。"},{"en":"The phrase highlights that something happened not very long ago.","zh":"這個短語強調某事發生在不久之前。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":3},{"front":"a survey of","meaning":"一項關於……的調查","examples":[{"en":"A survey of British exporting companies revealed a reliance on English.","zh":"一項關於英國出口公司的調查顯示它們依賴英語。"},{"en":"A survey of a group is a study that asks or examines members of that group.","zh":"“A survey of” 某群體是詢問或研究該群體成員的一項調查。"},{"en":"A survey of students may show how many hours they spend on homework.","zh":"一項關於學生的調查可能顯示他們花多少小時做功課。"},{"en":"If a survey of customers reveals confusion, the company may rewrite its instructions.","zh":"如果一項關於顧客的調查顯示他們感到困惑，公司可能重寫指示。"},{"en":"The phrase introduces research based on collected responses or data.","zh":"這個短語引出基於收集回應或數據的研究。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":3},{"front":"British exporting companies","meaning":"英國出口公司","examples":[{"en":"British exporting companies often used English with foreign customers.","zh":"英國出口公司經常與外國客戶使用英語。"},{"en":"British exporting companies are UK-based firms that sell goods or services to other countries.","zh":"英國出口公司是設於英國、向其他國家出售商品或服務的企業。"},{"en":"British exporting companies may sell food, machines, software, or education services overseas.","zh":"英國出口公司可能向海外出售食物、機器、軟件或教育服務。"},{"en":"If British exporting companies cannot speak clients’ languages, they may lose sales.","zh":"如果英國出口公司不能說客戶的語言，它們可能失去銷售。"},{"en":"The phrase identifies both the country and the international business activity.","zh":"這個短語同時指出國家和國際商業活動。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":3},{"front":"more than one-third","meaning":"超過三分之一","examples":[{"en":"More than one-third of the companies used English exclusively.","zh":"超過三分之一的公司只使用英語。"},{"en":"More than one-third means a quantity greater than one out of every three.","zh":"“More than one-third” 指數量多於每三個中的一個。"},{"en":"More than one-third of the class arrived early for the revision lesson.","zh":"超過三分之一的學生提早到達溫習課。"},{"en":"If more than one-third of customers complain, the problem is serious.","zh":"如果超過三分之一顧客投訴，問題便很嚴重。"},{"en":"The phrase gives an approximate proportion above 33%.","zh":"這個短語給出高於33%的大約比例。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":3},{"front":"use English exclusively","meaning":"只使用英語","examples":[{"en":"Some companies used English exclusively in dealings with foreign customers.","zh":"一些公司在與外國客戶往來時只使用英語。"},{"en":"To use English exclusively means to use only English and no other language.","zh":"“Use English exclusively” 指只使用英語，不使用其他語言。"},{"en":"A website uses English exclusively if it has no Chinese, Spanish, or French pages.","zh":"如果網站沒有中文、西班牙文或法文頁面，它就是只使用英語。"},{"en":"If a company uses English exclusively, non-English-speaking clients may not understand key information.","zh":"如果公司只使用英語，非英語客戶可能不理解重要資料。"},{"en":"The phrase stresses complete reliance on English.","zh":"這個短語強調完全依賴英語。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":3},{"front":"in dealings with","meaning":"在與……往來時","examples":[{"en":"The companies used English in dealings with foreign customers.","zh":"這些公司在與外國客戶往來時使用英語。"},{"en":"In dealings with someone means when doing business, communicating, or making arrangements with them.","zh":"“In dealings with” 某人指在與他們做生意、溝通或作安排時。"},{"en":"A bank must be careful in dealings with elderly customers.","zh":"銀行在與長者顧客往來時必須小心。"},{"en":"If staff are rude in dealings with clients, the company’s reputation may suffer.","zh":"如果員工在與客戶往來時無禮，公司聲譽可能受損。"},{"en":"The phrase is formal and often used in business contexts.","zh":"這個短語較正式，常用於商業語境。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":3},{"front":"foreign customers","meaning":"外國客戶","examples":[{"en":"Exporting companies often communicate with foreign customers.","zh":"出口公司經常與外國客戶溝通。"},{"en":"Foreign customers are buyers or clients from other countries.","zh":"外國客戶是來自其他國家的買家或客戶。"},{"en":"A local shop may gain foreign customers through an online store.","zh":"本地商店可能透過網店獲得外國客戶。"},{"en":"If foreign customers cannot read the product details, they may choose another seller.","zh":"如果外國客戶不能閱讀產品詳情，他們可能選擇另一個賣家。"},{"en":"The phrase is common in export, tourism, and international business.","zh":"這個短語常見於出口、旅遊和國際商業。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":4},{"front":"one language fits all","meaning":"一種語言適用於所有情況","examples":[{"en":"The attitude that “one language fits all” has continued into the Internet age.","zh":"「一種語言適用於所有情況」的態度延續至互聯網時代。"},{"en":"One language fits all means one language is wrongly assumed to work for every person and situation.","zh":"“One language fits all” 指錯誤地假設一種語言適合每個人和每種情況。"},{"en":"A school cannot use a “one language fits all” approach if many parents need translated notices.","zh":"如果很多家長需要翻譯通告，學校不能使用「一種語言適用於所有情況」的方法。"},{"en":"This attitude can make customers feel that their language and culture do not matter.","zh":"這種態度可以令顧客覺得自己的語言和文化不重要。"},{"en":"The phrase criticises an over-simple solution to multilingual communication.","zh":"這個短語批評對多語溝通過分簡化的解決方法。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":4},{"front":"continue into","meaning":"延續至","examples":[{"en":"The attitude continued into the Internet age.","zh":"這種態度延續至互聯網時代。"},{"en":"To continue into a period means to last and still exist during that later time.","zh":"“Continue into” 某時期指持續並在後來時期仍然存在。"},{"en":"Old habits may continue into university if students never learn better study methods.","zh":"如果學生從未學會更好學習方法，舊習慣可能延續至大學。"},{"en":"If paper-based work continues into the digital age, efficiency may suffer.","zh":"如果紙本工作延續至數碼時代，效率可能受損。"},{"en":"The phrase shows that something survives beyond its original period.","zh":"這個短語顯示某事超越原本時期而存續。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":4},{"front":"the Internet age","meaning":"互聯網時代","examples":[{"en":"The “one language fits all” attitude continued into the Internet age.","zh":"「一種語言適用於所有情況」的態度延續至互聯網時代。"},{"en":"The Internet age is the period when online communication, websites, and digital services shape daily life.","zh":"互聯網時代是網上溝通、網站和數碼服務塑造日常生活的時期。"},{"en":"In the Internet age, customers expect fast answers and multilingual information.","zh":"在互聯網時代，顧客期望快速回覆和多語資訊。"},{"en":"If a company ignores the Internet age, it may lose younger or overseas customers.","zh":"如果公司忽視互聯網時代，它可能失去年輕或海外顧客。"},{"en":"The phrase connects modern life with digital communication.","zh":"這個短語把現代生活與數碼溝通連繫起來。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":4},{"front":"leading American companies","meaning":"美國龍頭公司","examples":[{"en":"A survey examined the websites of leading American companies.","zh":"一項調查審視了美國龍頭公司的網站。"},{"en":"Leading American companies are major US firms that are important or influential in their industries.","zh":"美國龍頭公司是在其行業中重要或有影響力的主要美國企業。"},{"en":"Leading American companies often set trends in technology, retail, and advertising.","zh":"美國龍頭公司常在科技、零售和廣告方面帶動趨勢。"},{"en":"If leading American companies ignore foreign languages, smaller firms may copy the same mistake.","zh":"如果美國龍頭公司忽視外語，較小公司可能模仿同一錯誤。"},{"en":"The phrase points to well-known companies with market influence.","zh":"這個短語指有市場影響力的知名公司。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":4},{"front":"make no provision for","meaning":"沒有為……作出安排","examples":[{"en":"Many companies made no provision for access in foreign languages.","zh":"許多公司沒有為外語瀏覽渠道作出安排。"},{"en":"To make no provision for something means to make no plan or arrangement for it.","zh":"“Make no provision for” 某事指沒有為它制定計劃或安排。"},{"en":"A school makes no provision for disabled students if it has no ramps or support staff.","zh":"如果學校沒有斜道或支援人員，就是沒有為殘疾學生作出安排。"},{"en":"If a company makes no provision for foreign-language customers, those customers may leave.","zh":"如果公司沒有為外語客戶作出安排，這些客戶可能離開。"},{"en":"The phrase criticises a lack of preparation.","zh":"這個短語批評缺乏準備。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":4},{"front":"access in foreign languages","meaning":"外語瀏覽渠道","examples":[{"en":"Many websites offered no access in foreign languages.","zh":"許多網站沒有提供外語瀏覽渠道。"},{"en":"Access in foreign languages means the ability to use information or services in languages other than the main one.","zh":"外語瀏覽渠道指能以主要語言以外的語言使用資訊或服務。"},{"en":"A hospital website should provide access in foreign languages for patients who cannot read the local language.","zh":"醫院網站應為不能閱讀本地語言的病人提供外語瀏覽渠道。"},{"en":"Without access in foreign languages, overseas buyers may not complete an online purchase.","zh":"沒有外語瀏覽渠道，海外買家可能無法完成網上購買。"},{"en":"The phrase is common when discussing websites, services, and public information.","zh":"這個短語常用於討論網站、服務和公共資訊。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":4},{"front":"respond adequately to","meaning":"對……作出充分回應","examples":[{"en":"Few companies could respond adequately to foreign-language emails.","zh":"很少公司能對外語電郵作出充分回應。"},{"en":"To respond adequately to something means to answer or deal with it well enough.","zh":"“Respond adequately to” 某事指以足夠好的方式回答或處理它。"},{"en":"A teacher must respond adequately to bullying reports, not just tell students to ignore them.","zh":"老師必須對欺凌報告作出充分回應，而不是只叫學生忽視。"},{"en":"If a company cannot respond adequately to complaints, customer trust may fall.","zh":"如果公司不能對投訴作出充分回應，顧客信任可能下降。"},{"en":"The phrase suggests that a weak or incomplete response is not enough.","zh":"這個短語暗示薄弱或不完整的回應不足夠。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":4},{"front":"emails written in","meaning":"以……寫成的電郵","examples":[{"en":"Some companies struggled with emails written in foreign languages.","zh":"一些公司難以處理以外語寫成的電郵。"},{"en":"Emails written in a language are messages composed using that language.","zh":"以某語言寫成的電郵是使用該語言撰寫的信息。"},{"en":"A receptionist may forward emails written in Japanese to a bilingual colleague.","zh":"接待員可能把以日文寫成的電郵轉交給雙語同事。"},{"en":"If emails written in another language are ignored, business opportunities may be lost.","zh":"如果以另一種語言寫成的電郵被忽視，商機可能流失。"},{"en":"The phrase identifies the language used in written communication.","zh":"這個短語指出書面溝通使用的語言。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":4},{"front":"a language other than","meaning":"……以外的語言","examples":[{"en":"Few companies could answer emails written in a language other than their own.","zh":"很少公司能回覆以自己語言以外的語言寫成的電郵。"},{"en":"A language other than one’s own means a different language from the person’s or company’s main language.","zh":"“A language other than one’s own” 指不同於某人或公司主要語言的另一種語言。"},{"en":"A student may read books in a language other than Chinese to improve vocabulary.","zh":"學生可能閱讀中文以外的語言的書，以提升詞彙。"},{"en":"If customers write in a language other than English, English-only staff may struggle.","zh":"如果顧客用英語以外的語言寫信，只懂英語的員工可能會吃力。"},{"en":"The phrase clearly contrasts one language with another.","zh":"這個短語清楚對比一種語言與另一種語言。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":4},{"front":"reliance on","meaning":"對……的依賴","examples":[{"en":"Reliance on a single language is a flawed strategy.","zh":"對單一語言的依賴是一種有缺陷的策略。"},{"en":"Reliance on something means depending heavily on it.","zh":"“Reliance on” 某事指高度依靠它。"},{"en":"Reliance on parents for every decision can slow a teenager’s independence.","zh":"對父母作每個決定的依賴會拖慢青少年的獨立。"},{"en":"If a business has too much reliance on one supplier, delays can stop production.","zh":"如果企業過度依賴一個供應商，延誤可以令生產停止。"},{"en":"The phrase often warns that dependence may create risk.","zh":"這個短語常提醒依賴可能造成風險。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":4},{"front":"a single language","meaning":"單一語言","examples":[{"en":"Reliance on a single language can create business risks.","zh":"對單一語言的依賴可以造成商業風險。"},{"en":"A single language means one language only.","zh":"單一語言指只用一種語言。"},{"en":"A school notice written in a single language may not reach all parents.","zh":"以單一語言寫成的學校通告可能無法傳達給所有家長。"},{"en":"Using a single language can be efficient, but it can exclude people who do not understand it.","zh":"使用單一語言可以有效率，但可能排除不理解它的人。"},{"en":"The phrase stresses lack of language variety.","zh":"這個短語強調缺乏語言多樣性。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":5},{"front":"fatally flawed strategy","meaning":"有致命缺陷的策略","examples":[{"en":"Reliance on a single language is a fatally flawed strategy.","zh":"依賴單一語言是一種有致命缺陷的策略。"},{"en":"A fatally flawed strategy has such serious weaknesses that it is likely to fail.","zh":"有致命缺陷的策略有非常嚴重弱點，因此很可能失敗。"},{"en":"A delivery plan with no drivers is a fatally flawed strategy.","zh":"沒有司機的送貨計劃是有致命缺陷的策略。"},{"en":"If a company ignores customers’ languages, its international plan may be fatally flawed.","zh":"如果公司忽視顧客語言，其國際計劃可能有致命缺陷。"},{"en":"The phrase is stronger than simply saying “not ideal”.","zh":"這個短語比單純說「不理想」更強烈。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":5},{"front":"make no allowance for","meaning":"沒有考慮到","examples":[{"en":"This strategy makes no allowance for growing linguistic nationalism.","zh":"這種策略沒有考慮到日益增長的語言民族主義。"},{"en":"To make no allowance for something means to fail to consider it when planning.","zh":"“Make no allowance for” 某事指在規劃時未有考慮它。"},{"en":"A timetable makes no allowance for traffic if it gives drivers only five minutes between stops.","zh":"如果時間表只給司機五分鐘往返站點，就是沒有考慮到交通情況。"},{"en":"If a budget makes no allowance for emergencies, a small problem can become serious.","zh":"如果預算沒有考慮到緊急情況，小問題可以變得嚴重。"},{"en":"The phrase criticises planning that ignores a real factor.","zh":"這個短語批評忽視真實因素的規劃。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":5},{"front":"linguistic nationalism","meaning":"語言民族主義","examples":[{"en":"Linguistic nationalism may make customers demand their own language.","zh":"語言民族主義可能令顧客要求使用自己的語言。"},{"en":"Linguistic nationalism is pride in one’s language and the desire to protect or promote it.","zh":"語言民族主義是對自己語言的自豪，以及保護或推廣它的願望。"},{"en":"Parents may support linguistic nationalism by asking schools to teach in the local language.","zh":"家長可能透過要求學校以本地語言教學來支持語言民族主義。"},{"en":"If linguistic nationalism grows, companies may face pressure to serve customers in their own language.","zh":"如果語言民族主義增長，公司可能面對以顧客自身語言服務他們的壓力。"},{"en":"The phrase connects language with identity and political feeling.","zh":"這個短語把語言與身份和政治情感連繫起來。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":5},{"front":"assert one’s right to","meaning":"主張自己有權……","examples":[{"en":"Buyers may assert their right to work in their own language.","zh":"買家可能主張自己有權以自己的語言工作。"},{"en":"To assert one’s right to do something means to state firmly that one should be allowed to do it.","zh":"“Assert one’s right to” 做某事指堅定表示自己應被允許做該事。"},{"en":"Workers may assert their right to safe conditions after repeated accidents.","zh":"在多次意外後，工人可能主張自己有權享有安全工作環境。"},{"en":"If customers assert their right to clear information, companies must communicate more carefully.","zh":"如果顧客主張自己有權獲得清晰資訊，公司必須更謹慎溝通。"},{"en":"The phrase shows a firm claim, not a polite suggestion.","zh":"這個短語表示堅定主張，而不是禮貌建議。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":5},{"front":"work in the language of the customer","meaning":"以客戶的語言工作","examples":[{"en":"Many buyers expect companies to work in the language of the customer.","zh":"許多買家期望公司以客戶的語言工作。"},{"en":"To work in the language of the customer means to communicate, sell, and support clients using their own language.","zh":"“Work in the language of the customer” 指使用客戶自己的語言溝通、銷售和提供支援。"},{"en":"A bank may work in the language of the customer by offering forms in several languages.","zh":"銀行可能透過提供多語表格來以客戶的語言工作。"},{"en":"If a company works in the customer’s language, trust and clarity may improve.","zh":"如果公司以客戶的語言工作，信任和清晰度可能提升。"},{"en":"The phrase focuses on adapting communication to the buyer, not the seller.","zh":"這個短語強調根據買方而不是賣方調整溝通。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":5},{"front":"increasing vitality of","meaning":"……日益增強的活力","examples":[{"en":"The strategy ignores the increasing vitality of Spanish, Arabic and Chinese.","zh":"這種策略忽視西班牙語、阿拉伯語和中文日益增強的活力。"},{"en":"The increasing vitality of a language means its growing strength, use, and influence.","zh":"某語言日益增強的活力指其使用、力量和影響力逐漸增加。"},{"en":"The increasing vitality of Korean can be seen in music, films, and language classes.","zh":"韓語日益增強的活力可從音樂、電影和語言課中看見。"},{"en":"If a company ignores the increasing vitality of a language, it may miss new markets.","zh":"如果公司忽視某語言日益增強的活力，可能錯過新市場。"},{"en":"The phrase describes a language becoming more active and important.","zh":"這個短語描述一種語言變得更活躍和重要。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":5},{"front":"challenge English’s dominance","meaning":"挑戰英語的主導地位","examples":[{"en":"Spanish, Arabic and Chinese may challenge English’s dominance.","zh":"西班牙語、阿拉伯語和中文可能挑戰英語的主導地位。"},{"en":"To challenge English’s dominance means to reduce or question English’s leading position.","zh":"“Challenge English’s dominance” 指削弱或質疑英語的領先地位。"},{"en":"A popular local app may challenge English’s dominance by offering excellent services in another language.","zh":"受歡迎的本地應用程式可能透過以另一種語言提供優秀服務來挑戰英語的主導地位。"},{"en":"If more customers demand Chinese or Arabic, they may challenge English’s dominance in business.","zh":"如果更多顧客要求中文或阿拉伯語，他們可能挑戰英語在商業中的主導地位。"},{"en":"The phrase shows competition against English’s powerful role.","zh":"這個短語顯示對英語強大角色的競爭。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":5},{"front":"dominance as a lingua franca","meaning":"作為通用語的主導地位","examples":[{"en":"English’s dominance as a lingua franca may be challenged.","zh":"英語作為通用語的主導地位可能受到挑戰。"},{"en":"Dominance as a lingua franca means being the most widely used common language between different language groups.","zh":"作為通用語的主導地位指在不同語言群體之間作為最廣泛使用共同語言的地位。"},{"en":"English has dominance as a lingua franca in many international conferences.","zh":"英語在許多國際會議中擁有作為通用語的主導地位。"},{"en":"If another language becomes widely used in trade, English’s dominance as a lingua franca may weaken.","zh":"如果另一種語言在貿易中被廣泛使用，英語作為通用語的主導地位可能削弱。"},{"en":"The phrase focuses on the leading role of a shared communication language.","zh":"這個短語強調共享溝通語言的領先角色。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":5},{"front":"in information technology","meaning":"在資訊科技方面","examples":[{"en":"In information technology, English is declining as a share of online communication.","zh":"在資訊科技方面，英語在網上溝通所佔比例正在下降。"},{"en":"In information technology means in the field of computers, software, networks, and digital systems.","zh":"“In information technology” 指在電腦、軟件、網絡和數碼系統領域中。"},{"en":"In information technology, clear English can help programmers read documentation.","zh":"在資訊科技方面，清晰英語可以幫助程式員閱讀文件。"},{"en":"If more languages are used online, English may become less dominant in information technology.","zh":"如果網上使用更多語言，英語在資訊科技方面可能變得不那麼主導。"},{"en":"The phrase identifies the technological area being discussed.","zh":"這個短語指出正在討論的科技範疇。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":5},{"front":"disregard","meaning":"忽視","examples":[{"en":"The strategy disregards the Internet’s rapid globalisation.","zh":"這種策略忽視互聯網的迅速全球化。"},{"en":"To disregard something means to ignore it or treat it as unimportant.","zh":"“Disregard” 某事指忽視它或把它視為不重要。"},{"en":"A driver who disregards traffic lights puts others in danger.","zh":"無視交通燈的司機會令他人陷入危險。"},{"en":"If a company disregards customer feedback, small complaints may become major problems.","zh":"如果公司忽視顧客回饋，小投訴可能變成大問題。"},{"en":"The word is stronger than simply “forget”.","zh":"這個詞比單純說「忘記」更強烈。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":5},{"front":"rapid globalisation","meaning":"迅速全球化","examples":[{"en":"The Internet’s rapid globalisation has reduced the dominance of English.","zh":"互聯網的迅速全球化減弱了英語的主導地位。"},{"en":"Rapid globalisation means fast worldwide spread and connection.","zh":"迅速全球化指快速的全球擴散和連接。"},{"en":"Rapid globalisation allows a small online shop to sell products abroad.","zh":"迅速全球化讓小型網店能向海外銷售產品。"},{"en":"If rapid globalisation brings more languages online, companies must adapt their communication.","zh":"如果迅速全球化把更多語言帶到網上，公司必須調整溝通。"},{"en":"The phrase describes quick movement from local to global activity.","zh":"這個短語描述活動由本地快速走向全球。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":6},{"front":"e-commerce transactions","meaning":"電子商貿交易","examples":[{"en":"English-language e-commerce transactions are declining as a proportion of the total.","zh":"英語電子商貿交易佔總量的比例正在下降。"},{"en":"E-commerce transactions are buying and selling activities completed online.","zh":"電子商貿交易是在網上完成的買賣活動。"},{"en":"Ordering clothes through a website is one kind of e-commerce transaction.","zh":"透過網站訂購衣服是一種電子商貿交易。"},{"en":"If e-commerce transactions happen in many languages, English-only websites may lose customers.","zh":"如果電子商貿交易以多種語言進行，只用英語的網站可能失去顧客。"},{"en":"The phrase is common in online business and digital trade.","zh":"這個短語常見於網上商業和數碼貿易。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":6},{"front":"as a proportion of the total","meaning":"佔總量的比例","examples":[{"en":"English-language websites are declining as a proportion of the total.","zh":"英語網站佔總量的比例正在下降。"},{"en":"As a proportion of the total means as a share or percentage of the whole amount.","zh":"“As a proportion of the total” 指作為整體數量中的份額或百分比。"},{"en":"Online sales rose as a proportion of the total during the holiday season.","zh":"在假期期間，網上銷售佔總量的比例上升。"},{"en":"If one product falls as a proportion of the total, other products may be growing faster.","zh":"如果某產品佔總量的比例下降，其他產品可能增長更快。"},{"en":"The phrase helps compare one part with the whole.","zh":"這個短語有助比較部分與整體。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":6},{"front":"put someone at risk","meaning":"令某人面臨風險","examples":[{"en":"Total reliance on English puts English speakers at risk.","zh":"完全依賴英語令英語使用者面臨風險。"},{"en":"To put someone at risk means to place them in a situation where harm or loss is possible.","zh":"“Put someone at risk” 指令某人處於可能受害或損失的情況。"},{"en":"Driving too fast puts passengers at risk.","zh":"開車太快令乘客面臨風險。"},{"en":"If staff cannot read local contracts, the company may be put at risk during negotiations.","zh":"如果員工不能閱讀本地合約，公司可能在談判期間面臨風險。"},{"en":"The phrase warns that a situation may be dangerous or costly.","zh":"這個短語提醒某情況可能危險或代價高昂。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":6},{"front":"during negotiations","meaning":"在談判期間","examples":[{"en":"Companies may be vulnerable during negotiations if they lack local-language skills.","zh":"如果公司缺乏本地語言能力，在談判期間可能容易受損。"},{"en":"During negotiations means while two or more sides are discussing an agreement.","zh":"“During negotiations” 指兩方或多方討論協議期間。"},{"en":"During negotiations, both sides may discuss price, delivery time, and responsibilities.","zh":"在談判期間，雙方可能討論價格、交貨時間和責任。"},{"en":"If a company misunderstands key words during negotiations, it may accept unfair terms.","zh":"如果公司在談判期間誤解關鍵詞，可能接受不公平條款。"},{"en":"The phrase is common in business, law, and diplomacy.","zh":"這個短語常見於商業、法律和外交。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":6},{"front":"contracts, rules and legislation","meaning":"合約、規則和法例","examples":[{"en":"Contracts, rules and legislation are usually written in the local language.","zh":"合約、規則和法例通常以本地語言寫成。"},{"en":"Contracts, rules and legislation are formal documents and laws that control business behaviour.","zh":"合約、規則和法例是控制商業行為的正式文件和法律。"},{"en":"A company must understand contracts, rules and legislation before opening a branch abroad.","zh":"公司在海外開設分公司前，必須理解合約、規則和法例。"},{"en":"If contracts, rules and legislation are misunderstood, legal and financial problems may follow.","zh":"如果合約、規則和法例被誤解，法律和財務問題可能隨之出現。"},{"en":"The phrase groups together important written requirements.","zh":"這個短語把重要書面要求歸在一起。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":6},{"front":"invariably written in","meaning":"一律以……寫成","examples":[{"en":"Contracts are invariably written in the local language.","zh":"合約一律以本地語言寫成。"},{"en":"Invariably written in a language means almost always written in that language.","zh":"“Invariably written in” 某語言指幾乎總是以該語言寫成。"},{"en":"School reports are invariably written in a formal style.","zh":"學校報告一律以正式風格寫成。"},{"en":"If legal documents are invariably written in the local language, foreign firms need expert help.","zh":"如果法律文件一律以本地語言寫成，外國公司便需要專家協助。"},{"en":"The phrase emphasises that something happens consistently.","zh":"這個短語強調某事一貫發生。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":6},{"front":"local language","meaning":"本地語言","examples":[{"en":"Companies must understand the local language during negotiations.","zh":"公司在談判期間必須理解本地語言。"},{"en":"The local language is the language commonly used in a particular country, region, or community.","zh":"本地語言是在特定國家、地區或社區中常用的語言。"},{"en":"Tourists who learn a few words of the local language may receive warmer help.","zh":"學會幾個本地語言詞語的遊客可能獲得更友善的幫助。"},{"en":"If staff understand the local language, they can read signs, forms, and customer messages more accurately.","zh":"如果員工理解本地語言，就能更準確閱讀標誌、表格和顧客信息。"},{"en":"The phrase focuses on the language used by people in that place.","zh":"這個短語強調該地人們使用的語言。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":6},{"front":"unable to operate in","meaning":"無法以……運作","examples":[{"en":"A company unable to operate in the local language is vulnerable.","zh":"無法以本地語言運作的公司是脆弱的。"},{"en":"Unable to operate in a language means unable to work, communicate, or make decisions using that language.","zh":"“Unable to operate in” 某語言指無法使用該語言工作、溝通或作決定。"},{"en":"A clinic unable to operate in patients’ languages may give unclear instructions.","zh":"無法以病人語言運作的診所可能給出不清晰指示。"},{"en":"If a firm is unable to operate in Spanish, it may struggle in Spanish-speaking markets.","zh":"如果公司無法以西班牙語運作，它可能在西班牙語市場吃力。"},{"en":"The phrase shows a practical communication limitation.","zh":"這個短語顯示實際溝通限制。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":6},{"front":"vulnerable","meaning":"脆弱的；容易受損的","examples":[{"en":"A company that lacks local-language ability may be vulnerable.","zh":"缺乏本地語言能力的公司可能容易受損。"},{"en":"Vulnerable means easily harmed, damaged, exploited, or put at a disadvantage.","zh":"“Vulnerable” 指容易受傷害、受損、被利用或處於劣勢。"},{"en":"Elderly people may be vulnerable during extreme heat if they live alone.","zh":"如果長者獨居，在酷熱天氣中可能很脆弱。"},{"en":"If a business cannot read local rules, it is vulnerable to mistakes and unfair terms.","zh":"如果企業不能閱讀本地規則，就容易因錯誤和不公平條款而受損。"},{"en":"The word often describes weakness in a risky situation.","zh":"這個詞常描述在風險情況中的弱點。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":6},{"front":"functional multilingualism","meaning":"功能性多語溝通","examples":[{"en":"Functional multilingualism is an improvised approach to communication.","zh":"功能性多語溝通是一種臨時拼湊式的溝通方法。"},{"en":"Functional multilingualism means using several languages in a practical but imperfect way to communicate.","zh":"功能性多語溝通指以實用但不完美的方式使用多種語言來溝通。"},{"en":"Travellers may use functional multilingualism by mixing English, local words, and gestures.","zh":"旅客可能透過混合英語、本地詞語和手勢來使用功能性多語溝通。"},{"en":"Functional multilingualism can help people survive daily situations, but it may fail in legal negotiations.","zh":"功能性多語溝通可以幫助人們應付日常情況，但在法律談判中可能失敗。"},{"en":"The phrase describes makeshift multilingual communication rather than fluent language ability.","zh":"這個短語描述臨時拼湊的多語溝通，而不是流利語言能力。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":6},{"front":"improvised approach","meaning":"臨時拼湊式方法","examples":[{"en":"Functional multilingualism is an improvised approach to language barriers.","zh":"功能性多語溝通是處理語言障礙的臨時拼湊式方法。"},{"en":"An improvised approach is a method created quickly using whatever is available.","zh":"臨時拼湊式方法是快速使用手上資源創造出來的方法。"},{"en":"When the projector breaks, a teacher may use an improvised approach and draw on the board.","zh":"當投影機壞掉，老師可能使用臨時拼湊式方法，在白板上畫圖。"},{"en":"An improvised approach can solve small problems, but it may be unreliable for serious tasks.","zh":"臨時拼湊式方法可以解決小問題，但對嚴肅任務可能不可靠。"},{"en":"The phrase suggests flexibility but also lack of formal planning.","zh":"這個短語暗示靈活性，但也暗示缺乏正式規劃。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":7},{"front":"what has been called","meaning":"所謂的……","examples":[{"en":"Another approach is what has been called functional multilingualism.","zh":"另一種方法是所謂的功能性多語溝通。"},{"en":"What has been called introduces a name or label that people use for something.","zh":"“What has been called” 用來引出人們給某事使用的名稱或標籤。"},{"en":"This behaviour is what has been called active listening.","zh":"這種行為就是所謂的積極聆聽。"},{"en":"If a method is new, writers may introduce it as what has been called a certain term.","zh":"如果一種方法較新，作者可能把它介紹為所謂的某個術語。"},{"en":"The phrase is useful when naming an idea formally.","zh":"這個短語適合正式命名一個想法。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":7},{"front":"essentially","meaning":"基本上","examples":[{"en":"Essentially, functional multilingualism means muddling through.","zh":"基本上，功能性多語溝通就是勉強應付。"},{"en":"Essentially means basically or in the most important sense.","zh":"“Essentially” 指基本上或從最重要意義上來說。"},{"en":"Essentially, the problem is not laziness but poor planning.","zh":"基本上，問題不是懶惰，而是規劃差。"},{"en":"If a rule is too complex, students may miss what it essentially means.","zh":"如果規則太複雜，學生可能錯過其基本意思。"},{"en":"The word helps simplify a point to its core meaning.","zh":"這個詞有助把重點簡化至核心意思。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":7},{"front":"muddle through","meaning":"勉強應付","examples":[{"en":"Some companies muddle through by using a mixture of languages.","zh":"一些公司透過混合使用多種語言來勉強應付。"},{"en":"To muddle through means to manage a difficult situation in an imperfect but workable way.","zh":"“Muddle through” 指以不完美但可行的方式處理困難情況。"},{"en":"A student who forgets notes may muddle through a presentation using memory and simple examples.","zh":"忘記筆記的學生可能憑記憶和簡單例子勉強完成匯報。"},{"en":"Muddling through can work in emergencies, but it is not a strong long-term plan.","zh":"勉強應付可以在緊急情況中有效，但不是強而有力的長期計劃。"},{"en":"The phrase suggests survival rather than smooth success.","zh":"這個短語暗示生存下來，而不是順利成功。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":7},{"front":"rely on a mixture of","meaning":"依賴……的混合","examples":[{"en":"Functional multilingualism relies on a mixture of languages, pidgins and gestures.","zh":"功能性多語溝通依賴語言、洋涇濱語和手勢的混合。"},{"en":"To rely on a mixture of things means to depend on several different things together.","zh":"“Rely on a mixture of” 某些事物指同時依靠幾種不同事物。"},{"en":"A small shop may rely on a mixture of walk-in customers, online orders, and delivery apps.","zh":"小店可能依賴堂食顧客、網上訂單和外賣應用程式的混合。"},{"en":"If people rely on a mixture of languages and gestures, meaning may become unclear.","zh":"如果人們依賴語言和手勢的混合，意思可能變得不清晰。"},{"en":"The phrase shows that no single method is being used alone.","zh":"這個短語顯示沒有單獨使用一種方法。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":7},{"front":"pidgins","meaning":"洋涇濱語；混合語","examples":[{"en":"Pidgins may be used when people do not share a common language.","zh":"當人們沒有共同語言時，可能會使用洋涇濱語。"},{"en":"Pidgins are simplified mixed languages used for basic communication between groups.","zh":"洋涇濱語是不同群體之間用於基本溝通的簡化混合語。"},{"en":"Traders may use pidgins when they need to buy and sell without a shared full language.","zh":"商人在需要買賣但沒有完整共同語言時，可能使用洋涇濱語。"},{"en":"Pidgins can help basic communication, but they may not express complex legal ideas well.","zh":"洋涇濱語可以幫助基本溝通，但未必能好好表達複雜法律概念。"},{"en":"The word refers to practical mixed language systems, not polished formal languages.","zh":"這個詞指實用的混合語系統，而不是精緻正式語言。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":7},{"front":"gestures","meaning":"手勢","examples":[{"en":"People may rely on gestures when they lack a shared language.","zh":"當人們缺乏共同語言時，可能依賴手勢。"},{"en":"Gestures are movements of the hands, face, or body used to communicate meaning.","zh":"手勢是用來傳達意思的手部、面部或身體動作。"},{"en":"Pointing at a map is a gesture that can help a tourist ask for directions.","zh":"指着地圖是一種可以幫助遊客問路的手勢。"},{"en":"Gestures can help communication, but they may be misunderstood across cultures.","zh":"手勢可以幫助溝通，但在不同文化中可能被誤解。"},{"en":"The phrase is useful when spoken language is limited.","zh":"當口語有限時，這個短語很有用。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":7},{"front":"have at one’s disposal","meaning":"可供某人使用","examples":[{"en":"The parties use whatever means they have at their disposal.","zh":"各方使用任何可供他們使用的方法。"},{"en":"To have something at one’s disposal means to have it available for use.","zh":"“Have something at one’s disposal” 指有某物可供使用。"},{"en":"A teacher with a projector, whiteboard, and worksheets has several tools at her disposal.","zh":"有投影機、白板和工作紙的老師有幾種工具可供使用。"},{"en":"If a company has few language resources at its disposal, communication may be rough.","zh":"如果公司可供使用的語言資源很少，溝通可能粗糙。"},{"en":"The phrase focuses on resources that can be used when needed.","zh":"這個短語強調有需要時可以使用的資源。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":7},{"front":"social setting","meaning":"社交場合","examples":[{"en":"Functional multilingualism may work better in a social setting.","zh":"功能性多語溝通在社交場合可能更有效。"},{"en":"A social setting is a situation where people meet, talk, and build relationships informally.","zh":"社交場合是人們非正式見面、交談和建立關係的情況。"},{"en":"A birthday party is a social setting where small mistakes in language may not matter much.","zh":"生日派對是社交場合，語言小錯誤可能不太重要。"},{"en":"In a social setting, humour and patience can help people understand one another.","zh":"在社交場合，幽默和耐性可以幫助人們理解彼此。"},{"en":"The phrase contrasts with formal settings such as courtrooms or business negotiations.","zh":"這個短語與法庭或商業談判等正式場合形成對比。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":7},{"front":"shared effort","meaning":"共同努力","examples":[{"en":"The shared effort to understand one another may aid bonding.","zh":"互相理解的共同努力可能有助建立關係。"},{"en":"A shared effort is work or trying done together by two or more people.","zh":"共同努力是由兩人或以上一起進行的工作或嘗試。"},{"en":"A shared effort to clean the classroom can make students feel more responsible.","zh":"共同努力清潔課室可以令學生更有責任感。"},{"en":"When people make a shared effort to communicate, they may become more patient with each other.","zh":"當人們共同努力溝通，他們可能對彼此更有耐性。"},{"en":"The phrase emphasises cooperation, not individual action.","zh":"這個短語強調合作，而不是個人行動。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":7},{"front":"aid bonding","meaning":"有助建立關係","examples":[{"en":"Trying to communicate across languages may aid bonding.","zh":"嘗試跨語言溝通可能有助建立關係。"},{"en":"To aid bonding means to help people build a closer relationship.","zh":"“Aid bonding” 指幫助人們建立更親密的關係。"},{"en":"Team games can aid bonding among new classmates.","zh":"團隊遊戲可以有助新同學建立關係。"},{"en":"Shared difficulties may aid bonding because people feel they have solved something together.","zh":"共同困難可能有助建立關係，因為人們覺得一起解決了某事。"},{"en":"The phrase is often used when an experience brings people closer.","zh":"當經歷令彼此更親近時，常使用這個短語。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":7},{"front":"frustrations of communication","meaning":"溝通上的挫折","examples":[{"en":"The frustrations of communication may be mixed with humour.","zh":"溝通上的挫折可能與幽默混在一起。"},{"en":"Frustrations of communication are the annoying difficulties people feel when they cannot express or understand ideas clearly.","zh":"溝通上的挫折是人們不能清楚表達或理解想法時感到的惱人困難。"},{"en":"A foreign student may experience frustrations of communication when ordering food in a new language.","zh":"外國學生用新語言點餐時，可能經歷溝通上的挫折。"},{"en":"If frustrations of communication build up, people may become impatient or stop trying.","zh":"如果溝通上的挫折累積，人們可能變得不耐煩或停止嘗試。"},{"en":"The phrase describes emotional difficulty caused by unclear communication.","zh":"這個短語描述由不清晰溝通造成的情緒困難。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":8},{"front":"be punctuated by","meaning":"夾雜着","examples":[{"en":"The communication is regularly punctuated by moments of humour.","zh":"這種溝通常常夾雜着幽默時刻。"},{"en":"To be punctuated by something means to be interrupted or marked at intervals by it.","zh":"“Be punctuated by” 某事指被它不時打斷或作為標誌。"},{"en":"A long meeting may be punctuated by short jokes to keep people awake.","zh":"漫長會議可能夾雜着短笑話，讓人保持清醒。"},{"en":"If a difficult conversation is punctuated by laughter, it may feel less tense.","zh":"如果困難對話夾雜着笑聲，氣氛可能較不緊張。"},{"en":"The phrase describes repeated moments appearing within a longer event.","zh":"這個短語描述較長事件中反覆出現的時刻。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":8},{"front":"moments of absurdity and humour","meaning":"荒謬和幽默的時刻","examples":[{"en":"Miscommunication may create moments of absurdity and humour.","zh":"誤解可能造成荒謬和幽默的時刻。"},{"en":"Moments of absurdity and humour are short situations that feel silly, strange, and funny.","zh":"荒謬和幽默的時刻是短暫、愚蠢、奇怪而有趣的情況。"},{"en":"A wrong translation on a menu can create moments of absurdity and humour for travellers.","zh":"餐牌上的錯誤翻譯可以為旅客造成荒謬和幽默的時刻。"},{"en":"These moments may reduce tension, but they can also show that communication is not accurate.","zh":"這些時刻可能減少緊張，但也可以顯示溝通不準確。"},{"en":"The phrase combines confusion with comedy.","zh":"這個短語把混亂與喜劇結合起來。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":8},{"front":"as a basis for","meaning":"作為……的基礎","examples":[{"en":"Functional multilingualism is risky as a basis for business negotiations.","zh":"功能性多語溝通作為商業談判的基礎是有風險的。"},{"en":"As a basis for something means as the foundation on which something depends.","zh":"“As a basis for” 某事指作為某事依靠的基礎。"},{"en":"A rumour should not be used as a basis for punishing a student.","zh":"謠言不應作為懲罰學生的基礎。"},{"en":"If unclear language is used as a basis for a contract, arguments may follow.","zh":"如果不清晰語言被用作合約的基礎，爭議可能隨之出現。"},{"en":"The phrase focuses on whether the foundation is strong enough.","zh":"這個短語強調基礎是否足夠穩固。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":8},{"front":"business negotiations","meaning":"商業談判","examples":[{"en":"Language problems can seriously affect business negotiations.","zh":"語言問題可以嚴重影響商業談判。"},{"en":"Business negotiations are discussions between companies or clients about deals, prices, terms, and responsibilities.","zh":"商業談判是公司或客戶之間關於交易、價格、條款和責任的討論。"},{"en":"Business negotiations may include delivery dates, payment methods, and service standards.","zh":"商業談判可能包括交貨日期、付款方式和服務標準。"},{"en":"If one side misunderstands the language in business negotiations, the final agreement may be unfair.","zh":"如果一方在商業談判中誤解語言，最終協議可能不公平。"},{"en":"The phrase is common in international trade and corporate work.","zh":"這個短語常見於國際貿易和企業工作。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":8},{"front":"decidedly hit-and-miss","meaning":"成效非常參差；很靠運氣","examples":[{"en":"Functional multilingualism is decidedly hit-and-miss in business negotiations.","zh":"功能性多語溝通在商業談判中成效非常參差。"},{"en":"Decidedly hit-and-miss means clearly unreliable, with results that sometimes work and sometimes fail.","zh":"“Decidedly hit-and-miss” 指明顯不可靠，結果有時成功、有時失敗。"},{"en":"Learning vocabulary only from random videos can be decidedly hit-and-miss.","zh":"只從隨機影片學詞彙可能成效非常參差。"},{"en":"If communication is hit-and-miss, important details may be understood one day and missed the next.","zh":"如果溝通很靠運氣，重要細節可能今天被理解、明天被錯過。"},{"en":"The phrase strongly criticises inconsistency.","zh":"這個短語強烈批評不一致。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":8},{"front":"nevertheless","meaning":"然而","examples":[{"en":"Nevertheless, some international transactions use a mixture of languages.","zh":"然而，一些國際交易使用多種語言的混合。"},{"en":"Nevertheless means despite what was just said, the following point is still true.","zh":"“Nevertheless” 指儘管剛才那樣說，接下來的一點仍然成立。"},{"en":"The course is difficult; nevertheless, many students enjoy the challenge.","zh":"這個課程很難；然而，許多學生享受挑戰。"},{"en":"Translation can be imperfect; nevertheless, it is often necessary.","zh":"翻譯可能不完美；然而，它常常是必要的。"},{"en":"The word introduces contrast while continuing the argument.","zh":"這個詞在延續論點時引出對比。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":8},{"front":"international business transactions","meaning":"國際商業交易","examples":[{"en":"Some international business transactions are conducted using mixed languages.","zh":"一些國際商業交易使用混合語言進行。"},{"en":"International business transactions are buying, selling, or agreement-making activities between parties in different countries.","zh":"國際商業交易是不同國家各方之間的買賣或協議活動。"},{"en":"An export order from Germany to Japan is an international business transaction.","zh":"從德國到日本的出口訂單是一項國際商業交易。"},{"en":"If international business transactions involve unclear language, mistakes can become expensive.","zh":"如果國際商業交易涉及不清晰語言，錯誤可能變得昂貴。"},{"en":"The phrase describes formal cross-border commercial activity.","zh":"這個短語描述正式跨境商業活動。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":8},{"front":"be conducted using","meaning":"使用……進行","examples":[{"en":"Some transactions are conducted using a cocktail of languages.","zh":"一些交易使用多種語言混合進行。"},{"en":"To be conducted using something means to be carried out with that method or tool.","zh":"“Be conducted using” 某物指用該方法或工具進行。"},{"en":"A survey may be conducted using online forms.","zh":"調查可以使用網上表格進行。"},{"en":"If a meeting is conducted using three languages, interpretation may be needed.","zh":"如果會議使用三種語言進行，可能需要傳譯。"},{"en":"The phrase explains how an activity is done.","zh":"這個短語解釋活動如何進行。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":8},{"front":"a cocktail of languages","meaning":"多種語言混合","examples":[{"en":"Some business transactions use a cocktail of languages.","zh":"一些商業交易使用多種語言混合。"},{"en":"A cocktail of languages means a mixture of several languages used together.","zh":"“A cocktail of languages” 指幾種語言混合使用。"},{"en":"In a tourist market, sellers and buyers may use a cocktail of languages to bargain.","zh":"在旅遊市場中，賣家和買家可能使用多種語言混合來議價。"},{"en":"A cocktail of languages can help basic understanding but may confuse exact details.","zh":"多種語言混合可以幫助基本理解，但可能混淆精確細節。"},{"en":"The phrase is informal and suggests a mixed, improvised style.","zh":"這個短語較非正式，暗示混合而臨時拼湊的風格。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":8},{"front":"share the defects of","meaning":"有……的同樣缺陷","examples":[{"en":"Functional multilingualism shares the defects of relying on one lingua franca.","zh":"功能性多語溝通有依賴一種通用語的同樣缺陷。"},{"en":"To share the defects of something means to have the same weaknesses as it.","zh":"“Share the defects of” 某事指具有與它相同的弱點。"},{"en":"Online lessons may share the defects of recorded videos if students cannot ask questions.","zh":"如果學生不能提問，網課可能有錄影課的同樣缺陷。"},{"en":"If two plans share the same defects, changing the name will not solve the problem.","zh":"如果兩個計劃有同樣缺陷，改名並不能解決問題。"},{"en":"The phrase compares weaknesses between two methods.","zh":"這個短語比較兩種方法之間的弱點。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":8},{"front":"increase the probability of","meaning":"增加……的可能性","examples":[{"en":"This approach increases the probability of cognitive divergence.","zh":"這種方法增加認知分歧的可能性。"},{"en":"To increase the probability of something means to make it more likely to happen.","zh":"“Increase the probability of” 某事指令它更可能發生。"},{"en":"Poor sleep increases the probability of mistakes in exams.","zh":"睡眠不足增加考試出錯的可能性。"},{"en":"If messages pass through several languages, the probability of misunderstanding may increase.","zh":"如果信息經過幾種語言傳遞，誤解的可能性可能增加。"},{"en":"The phrase is formal and common in risk analysis.","zh":"這個短語較正式，常見於風險分析。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":9},{"front":"cognitive divergence","meaning":"認知分歧","examples":[{"en":"Mixed-language communication may cause cognitive divergence between parties.","zh":"混合語言溝通可能導致各方之間出現認知分歧。"},{"en":"Cognitive divergence means people understand, interpret, or think about the same message differently.","zh":"認知分歧指人們對同一信息有不同理解、詮釋或思考方式。"},{"en":"In a group project, cognitive divergence may occur when members define success in different ways.","zh":"在小組項目中，當成員以不同方式定義成功時，可能出現認知分歧。"},{"en":"If translation creates cognitive divergence, both sides may believe they agreed while thinking different things.","zh":"如果翻譯造成認知分歧，雙方可能以為已達成共識，但其實想法不同。"},{"en":"The phrase describes differences in understanding, not just differences in words.","zh":"這個短語描述理解上的差異，而不只是字詞上的差異。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":9},{"front":"external language resources","meaning":"外部語言資源","examples":[{"en":"External language resources include translators and interpreters.","zh":"外部語言資源包括筆譯員和傳譯員。"},{"en":"External language resources are language services or experts hired from outside the company.","zh":"外部語言資源是從公司外部聘用的語言服務或專家。"},{"en":"A small firm may use external language resources to translate a contract quickly.","zh":"小公司可能使用外部語言資源快速翻譯合約。"},{"en":"If internal staff lack language skills, external language resources can fill the gap.","zh":"如果內部員工缺乏語言技能，外部語言資源可以填補缺口。"},{"en":"The phrase refers to outside help rather than in-house employees.","zh":"這個短語指外部協助，而不是內部員工。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":9},{"front":"rational and obvious response","meaning":"理性而明顯的應對方法","examples":[{"en":"Hiring translators is a rational and obvious response to the language barrier.","zh":"聘用筆譯員是對語言障礙的理性而明顯的應對方法。"},{"en":"A rational and obvious response is a sensible solution that most people would think of quickly.","zh":"理性而明顯的應對方法是大多數人很快想到的合理解決方案。"},{"en":"Calling a plumber is a rational and obvious response to a leaking pipe.","zh":"水管漏水時，打電話給水喉匠是理性而明顯的應對方法。"},{"en":"If customers cannot understand the website, translation is a rational and obvious response.","zh":"如果顧客不能理解網站，翻譯就是理性而明顯的應對方法。"},{"en":"The phrase suggests the solution makes sense, even if it is not perfect.","zh":"這個短語暗示解決方案合理，即使並不完美。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":9},{"front":"employ external translators and interpreters","meaning":"聘用外部筆譯員和傳譯員","examples":[{"en":"Companies may employ external translators and interpreters.","zh":"公司可能聘用外部筆譯員和傳譯員。"},{"en":"To employ external translators and interpreters means to hire outside language professionals to translate written or spoken messages.","zh":"“Employ external translators and interpreters” 指聘請外部語言專業人士翻譯書面或口頭信息。"},{"en":"A law firm may employ external translators and interpreters for an overseas client meeting.","zh":"律師行可能為海外客戶會議聘用外部筆譯員和傳譯員。"},{"en":"If staff cannot handle technical language, employing specialists may reduce mistakes.","zh":"如果員工不能處理專門語言，聘用專家可能減少錯誤。"},{"en":"The phrase describes paying outside experts for language support.","zh":"這個短語描述付費聘請外部專家提供語言支援。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":9},{"front":"translators and interpreters","meaning":"筆譯員和傳譯員","examples":[{"en":"Translators and interpreters can help companies communicate across languages.","zh":"筆譯員和傳譯員可以幫助公司跨語言溝通。"},{"en":"Translators usually work with written text, while interpreters usually work with spoken language.","zh":"筆譯員通常處理書面文字，而傳譯員通常處理口語。"},{"en":"A hospital may need translators and interpreters for patients who speak different languages.","zh":"醫院可能需要筆譯員和傳譯員協助說不同語言的病人。"},{"en":"If translators and interpreters are not briefed, important meaning may still be lost.","zh":"如果筆譯員和傳譯員沒有得到簡報，重要意思仍可能流失。"},{"en":"The phrase groups together two professional language roles.","zh":"這個短語把兩種專業語言角色歸在一起。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":9},{"front":"specialise in","meaning":"專門從事","examples":[{"en":"Many excellent companies specialise in translation and interpreting.","zh":"許多優秀公司專門從事筆譯和傳譯。"},{"en":"To specialise in something means to focus on one particular skill, service, or area of knowledge.","zh":"“Specialise in” 某事指專注於某一特定技能、服務或知識範疇。"},{"en":"A doctor may specialise in children’s health.","zh":"醫生可能專門從事兒童健康。"},{"en":"Companies that specialise in legal translation may understand contracts better than general translators.","zh":"專門從事法律翻譯的公司可能比一般譯者更理解合約。"},{"en":"The phrase suggests deep focus and professional expertise.","zh":"這個短語暗示深入專注和專業知識。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":9},{"front":"eliminate the barrier","meaning":"消除障礙","examples":[{"en":"Using interpreters does not eliminate the language barrier.","zh":"使用傳譯員並不能消除語言障礙。"},{"en":"To eliminate the barrier means to remove the obstacle completely.","zh":"“Eliminate the barrier” 指完全移除障礙。"},{"en":"Adding subtitles can reduce a language problem, but it may not eliminate the barrier fully.","zh":"加入字幕可以減少語言問題，但未必完全消除障礙。"},{"en":"If customers still misunderstand key terms, the barrier has not been eliminated.","zh":"如果顧客仍誤解關鍵詞，障礙便未被消除。"},{"en":"The phrase is stronger than “reduce the problem”.","zh":"這個短語比「減少問題」更強。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":9},{"front":"simultaneous interpreter","meaning":"同聲傳譯員","examples":[{"en":"A leading simultaneous interpreter may charge very high daily rates.","zh":"頂尖同聲傳譯員可能收取非常高的每日費用。"},{"en":"A simultaneous interpreter translates speech almost at the same time as the speaker talks.","zh":"同聲傳譯員幾乎在講者說話的同時翻譯演說。"},{"en":"International conferences often use simultaneous interpreters so listeners can follow immediately.","zh":"國際會議常使用同聲傳譯員，讓聽眾可以即時跟上。"},{"en":"If a simultaneous interpreter misses context, the listener may receive a weaker message.","zh":"如果同聲傳譯員錯過背景，聽眾可能收到較弱的信息。"},{"en":"The phrase refers to a highly skilled real-time interpreting role.","zh":"這個短語指高度熟練的即時傳譯角色。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":9},{"front":"command daily rates","meaning":"收取每日高額費用","examples":[{"en":"A leading interpreter can command high daily rates.","zh":"頂尖傳譯員可以收取每日高額費用。"},{"en":"To command daily rates means to be able to charge a certain amount of money per day.","zh":"“Command daily rates” 指能夠按日收取某個金額。"},{"en":"An experienced consultant may command high daily rates because of specialist knowledge.","zh":"有經驗的顧問可能因專門知識而收取每日高額費用。"},{"en":"If a skill is rare, professionals with that skill can command higher rates.","zh":"如果某技能罕有，擁有該技能的專業人士可以收取更高費用。"},{"en":"The phrase is often used for expensive expert services.","zh":"這個短語常用於昂貴專家服務。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":9},{"front":"as high as those of","meaning":"與……同樣高","examples":[{"en":"An interpreter’s daily rates may be as high as those of a consultant.","zh":"傳譯員的每日費用可能與顧問的費用同樣高。"},{"en":"As high as those of someone means equal to that person’s high level or amount.","zh":"“As high as those of” 某人指與該人的高水平或高金額相同。"},{"en":"A private tutor’s fees may be as high as those of a professional coach.","zh":"私人補習老師的費用可能與專業教練的費用同樣高。"},{"en":"If interpreter fees are as high as those of consultants, companies must budget carefully.","zh":"如果傳譯費與顧問費同樣高，公司必須謹慎預算。"},{"en":"The phrase compares one cost or level with another.","zh":"這個短語比較一項成本或水平與另一項。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":9},{"front":"consulting firm","meaning":"顧問公司","examples":[{"en":"An international consulting firm may charge high professional fees.","zh":"國際顧問公司可能收取高昂專業費用。"},{"en":"A consulting firm is a company that gives expert advice to other organisations.","zh":"顧問公司是向其他機構提供專家建議的公司。"},{"en":"A consulting firm may help a hospital improve management or reduce waiting times.","zh":"顧問公司可能幫助醫院改善管理或減少等候時間。"},{"en":"If a consulting firm charges high fees, clients expect specialist knowledge and clear results.","zh":"如果顧問公司收取高昂費用，客戶會期望專門知識和清晰成果。"},{"en":"The phrase is common in business and professional services.","zh":"這個短語常見於商業和專業服務。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":10},{"front":"insist that","meaning":"堅持認為","examples":[{"en":"A good interpreter will insist that context is necessary.","zh":"優秀傳譯員會堅持認為背景是必要的。"},{"en":"To insist that something is true means to state it firmly and not easily change one’s view.","zh":"“Insist that” 某事為真指堅定陳述它，並不輕易改變看法。"},{"en":"A doctor may insist that a patient rests after surgery.","zh":"醫生可能堅持認為病人手術後需要休息。"},{"en":"If an interpreter insists that briefing is needed, the client should take the request seriously.","zh":"如果傳譯員堅持認為需要簡報，客戶應認真看待該要求。"},{"en":"The phrase shows strong belief or requirement.","zh":"這個短語顯示強烈信念或要求。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":10},{"front":"to be fully effective","meaning":"要完全有效","examples":[{"en":"To be fully effective, an interpreter must understand the context.","zh":"要完全有效，傳譯員必須理解背景。"},{"en":"To be fully effective means to work as well as possible and achieve the intended result.","zh":"“To be fully effective” 指盡可能有效運作並達到預期結果。"},{"en":"To be fully effective, a lesson must match students’ level and needs.","zh":"要完全有效，一堂課必須配合學生程度和需要。"},{"en":"A translation tool may not be fully effective if it cannot understand humour or culture.","zh":"如果翻譯工具不能理解幽默或文化，它可能無法完全有效。"},{"en":"The phrase explains what is needed for success.","zh":"這個短語解釋成功需要甚麼。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":10},{"front":"understand the context","meaning":"理解背景","examples":[{"en":"A translator must understand the context of the subject matter.","zh":"筆譯員必須理解主題內容的背景。"},{"en":"To understand the context means to know the background, purpose, and situation around a message.","zh":"“Understand the context” 指知道信息背後的背景、目的和情況。"},{"en":"A student must understand the context before choosing the meaning of an unfamiliar word.","zh":"學生在選擇陌生詞意思前，必須理解背景。"},{"en":"If an interpreter does not understand the context, the translation may be technically correct but misleading.","zh":"如果傳譯員不理解背景，翻譯可能技術上正確但具誤導性。"},{"en":"The phrase stresses that words depend on surrounding information.","zh":"這個短語強調字詞依賴周圍資訊。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":10},{"front":"subject matter","meaning":"主題內容","examples":[{"en":"The complexity of the subject matter may make translation difficult.","zh":"主題內容的複雜性可能令翻譯困難。"},{"en":"Subject matter is the topic or content being discussed, written about, or taught.","zh":"主題內容是正在討論、書寫或教授的題目或內容。"},{"en":"A science article has different subject matter from a travel blog.","zh":"科學文章的主題內容不同於旅遊網誌。"},{"en":"If the subject matter is legal or medical, translators need specialist knowledge.","zh":"如果主題內容是法律或醫療，譯者需要專門知識。"},{"en":"The phrase focuses on what the communication is about.","zh":"這個短語強調溝通內容關於甚麼。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":10},{"front":"the complexity of","meaning":"……的複雜性","examples":[{"en":"The complexity of the topic may prevent full understanding.","zh":"該題目的複雜性可能妨礙完全理解。"},{"en":"The complexity of something means how difficult, detailed, or complicated it is.","zh":"“The complexity of” 某事指它有多困難、仔細或複雜。"},{"en":"The complexity of tax rules can confuse small business owners.","zh":"稅務規則的複雜性可以令小企業主困惑。"},{"en":"If people underestimate the complexity of translation, they may expect impossible speed.","zh":"如果人們低估翻譯的複雜性，可能期待不可能的速度。"},{"en":"The phrase helps explain why a task is hard.","zh":"這個短語有助解釋任務為何困難。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":10},{"front":"specialisation of the topic","meaning":"題目的專門性","examples":[{"en":"The specialisation of the topic may make interpreting harder.","zh":"題目的專門性可能令傳譯更困難。"},{"en":"The specialisation of the topic means how technical or expert-focused the subject is.","zh":"題目的專門性指主題有多技術性或多專家導向。"},{"en":"The specialisation of a medical talk makes it difficult for ordinary listeners.","zh":"醫學講座的專門性令普通聽眾難以理解。"},{"en":"If the topic is highly specialised, interpreters need preparation and background knowledge.","zh":"如果題目高度專門，傳譯員需要準備和背景知識。"},{"en":"The phrase explains why general language ability may not be enough.","zh":"這個短語解釋為何一般語言能力可能不足夠。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":10},{"front":"preparation time","meaning":"準備時間","examples":[{"en":"Sometimes there is too little preparation time for interpreters.","zh":"有時傳譯員的準備時間太少。"},{"en":"Preparation time is the time available before a task to study, plan, or get ready.","zh":"準備時間是在任務前可用於學習、計劃或準備的時間。"},{"en":"Students need preparation time before giving a formal presentation.","zh":"學生在正式匯報前需要準備時間。"},{"en":"If interpreters have little preparation time, they may miss technical terms.","zh":"如果傳譯員準備時間很少，可能錯過專門術語。"},{"en":"The phrase shows why good performance often depends on advance work.","zh":"這個短語顯示良好表現往往依賴事前工作。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":10},{"front":"the obstacle is","meaning":"障礙是","examples":[{"en":"Most often, the obstacle is the parties’ reluctance to brief an outsider.","zh":"最常見的是，障礙是各方不願意向外人作簡報。"},{"en":"The obstacle is means the main difficulty or barrier is being identified.","zh":"“The obstacle is” 指正在指出主要困難或障礙。"},{"en":"In many study plans, the obstacle is not ability but lack of routine.","zh":"在許多學習計劃中，障礙不是能力，而是缺乏習慣。"},{"en":"If the obstacle is cost, a cheaper solution may be needed.","zh":"如果障礙是成本，就可能需要較便宜的解決方案。"},{"en":"The phrase points directly to what is blocking progress.","zh":"這個短語直接指出阻礙進展的是甚麼。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":10},{"front":"reluctance to","meaning":"不願意……","examples":[{"en":"The parties’ reluctance to explain the wider context can cause problems.","zh":"各方不願意解釋更廣闊背景可能造成問題。"},{"en":"Reluctance to do something means unwillingness or hesitation to do it.","zh":"“Reluctance to” 做某事指不願意或猶豫去做它。"},{"en":"A child’s reluctance to ask questions may hide real confusion.","zh":"孩子不願意提問可能掩蓋真正困惑。"},{"en":"If managers show reluctance to share information, staff may make poor decisions.","zh":"如果經理不願意分享資訊，員工可能作出差劣決定。"},{"en":"The phrase suggests resistance rather than inability.","zh":"這個短語暗示抗拒，而不是沒有能力。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":10},{"front":"wider context","meaning":"更廣闊背景","examples":[{"en":"Clients may be reluctant to explain the wider context to an outsider.","zh":"客戶可能不願意向外人解釋更廣闊背景。"},{"en":"The wider context is the broader background that helps people understand a specific message or decision.","zh":"更廣闊背景是幫助人理解特定信息或決定的較大背景。"},{"en":"A single sentence may sound rude until the wider context is explained.","zh":"單一句子在解釋更廣闊背景前可能聽起來無禮。"},{"en":"If translators lack the wider context, they may choose words that miss the real intention.","zh":"如果譯者缺乏更廣闊背景，可能選擇錯過真正意圖的字詞。"},{"en":"The phrase reminds us that meaning often depends on background.","zh":"這個短語提醒我們，意思往往依賴背景。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":10},{"front":"outsider","meaning":"外人","examples":[{"en":"Companies may not want to explain sensitive details to an outsider.","zh":"公司可能不想向外人解釋敏感細節。"},{"en":"An outsider is someone who is not part of a group, organisation, or situation.","zh":"外人是不屬於某群體、機構或情況的人。"},{"en":"A family may not want to discuss private problems with an outsider.","zh":"家庭可能不想與外人討論私人問題。"},{"en":"If an interpreter is treated as an outsider, they may not receive enough information.","zh":"如果傳譯員被視為外人，他們可能得不到足夠資訊。"},{"en":"The phrase can suggest distance, lack of trust, or lack of inside knowledge.","zh":"這個短語可以暗示距離、缺乏信任或缺乏內部知識。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":11},{"front":"extensively briefed","meaning":"得到充分簡報","examples":[{"en":"Interpreters and clients need to be extensively briefed.","zh":"傳譯員和客戶需要得到充分簡報。"},{"en":"To be extensively briefed means to receive detailed information before doing a task.","zh":"“Be extensively briefed” 指在做任務前得到詳細資訊。"},{"en":"A substitute teacher should be extensively briefed before taking over a difficult class.","zh":"代課老師接手困難班級前應得到充分簡報。"},{"en":"If interpreters are extensively briefed, they can understand purpose, tone, and technical terms better.","zh":"如果傳譯員得到充分簡報，他們可以更好理解目的、語氣和專門術語。"},{"en":"The phrase shows careful preparation through detailed explanation.","zh":"這個短語顯示透過詳細解釋作謹慎準備。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":11},{"front":"ambiguity","meaning":"歧義；含糊之處","examples":[{"en":"Ambiguity may remain in the source messages.","zh":"原始信息中可能仍有歧義。"},{"en":"Ambiguity means unclear meaning that can be understood in more than one way.","zh":"歧義指意思不清楚，可以用多於一種方式理解。"},{"en":"The sentence “I saw her duck” has ambiguity because “duck” can mean an animal or an action.","zh":"“I saw her duck” 這句有歧義，因為 “duck” 可以指動物，也可以指動作。"},{"en":"If a contract contains ambiguity, both sides may interpret it differently.","zh":"如果合約包含歧義，雙方可能以不同方式詮釋它。"},{"en":"The word is important in language, law, and translation.","zh":"這個詞在語言、法律和翻譯中很重要。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":11},{"front":"cultural overtones","meaning":"文化含意","examples":[{"en":"Cultural overtones may remain in the original message.","zh":"原始信息中可能仍有文化含意。"},{"en":"Cultural overtones are hidden or indirect meanings connected with culture, values, or social expectations.","zh":"文化含意是與文化、價值觀或社會期望有關的隱藏或間接意思。"},{"en":"A joke may have cultural overtones that foreign listeners do not notice.","zh":"笑話可能有外國聽眾注意不到的文化含意。"},{"en":"If cultural overtones are lost in translation, the message may feel flat or strange.","zh":"如果文化含意在翻譯中流失，信息可能顯得平淡或奇怪。"},{"en":"The phrase refers to meaning beyond the literal words.","zh":"這個短語指超越字面文字的意思。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":11},{"front":"source messages","meaning":"原始信息","examples":[{"en":"Ambiguity may remain in the source messages.","zh":"原始信息中可能仍有歧義。"},{"en":"Source messages are the original spoken or written messages before translation.","zh":"原始信息是翻譯前的原本口頭或書面信息。"},{"en":"Translators must understand source messages before producing the target version.","zh":"譯者必須理解原始信息，才能產生目標語版本。"},{"en":"If source messages are unclear, even a skilled translator may struggle.","zh":"如果原始信息不清楚，即使熟練譯者也可能吃力。"},{"en":"The phrase is common in translation and communication studies.","zh":"這個短語常見於翻譯和傳播研究。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":11},{"front":"endeavour to","meaning":"盡力去","examples":[{"en":"The interpreter will endeavour to provide a faithful translation.","zh":"傳譯員會盡力提供忠實翻譯。"},{"en":"To endeavour to do something means to try hard to do it, especially in a formal or difficult situation.","zh":"“Endeavour to” 做某事指努力去做，尤其在正式或困難情況中。"},{"en":"A school may endeavour to support every student, even with limited resources.","zh":"即使資源有限，學校也可能盡力支援每個學生。"},{"en":"If an interpreter endeavours to be accurate, preparation still matters.","zh":"如果傳譯員盡力做到準確，準備仍然重要。"},{"en":"The phrase is more formal than “try to”.","zh":"這個短語比 “try to” 更正式。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":11},{"front":"high-fidelity translation","meaning":"高度忠實的翻譯","examples":[{"en":"The interpreter tries to provide a high-fidelity translation.","zh":"傳譯員嘗試提供高度忠實的翻譯。"},{"en":"A high-fidelity translation is a translation that stays very close to the original meaning, tone, and intention.","zh":"高度忠實的翻譯是非常貼近原文意思、語氣和意圖的翻譯。"},{"en":"Legal documents need high-fidelity translation because small differences can change obligations.","zh":"法律文件需要高度忠實的翻譯，因為細小差異可以改變責任。"},{"en":"If cultural humour is involved, high-fidelity translation becomes harder.","zh":"如果涉及文化幽默，高度忠實的翻譯會變得更困難。"},{"en":"The phrase stresses accuracy and faithfulness.","zh":"這個短語強調準確和忠實。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":11},{"front":"in such circumstances","meaning":"在這種情況下","examples":[{"en":"In such circumstances, the interpreter must use initiative and guesswork.","zh":"在這種情況下，傳譯員必須使用主動判斷和猜測。"},{"en":"In such circumstances means in a situation like the one just described.","zh":"“In such circumstances” 指在剛才描述的那種情況下。"},{"en":"The train is cancelled; in such circumstances, students should use the emergency bus route.","zh":"火車取消；在這種情況下，學生應使用緊急巴士路線。"},{"en":"If there is no preparation time, in such circumstances the interpreter may have to make quick decisions.","zh":"如果沒有準備時間，在這種情況下傳譯員可能必須迅速作決定。"},{"en":"The phrase links a response to a specific situation.","zh":"這個短語把回應與特定情況連繫起來。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":11},{"front":"initiative and guesswork","meaning":"主動判斷和猜測","examples":[{"en":"An unprepared interpreter may have to rely on initiative and guesswork.","zh":"沒有充分準備的傳譯員可能必須依賴主動判斷和猜測。"},{"en":"Initiative and guesswork mean independent judgement plus educated guessing when full information is missing.","zh":"主動判斷和猜測指在缺乏完整資訊時，運用獨立判斷和有根據的猜想。"},{"en":"A new employee may use initiative and guesswork when the manager is unavailable.","zh":"當經理不在，新員工可能使用主動判斷和猜測。"},{"en":"If too much depends on guesswork, mistakes become more likely.","zh":"如果太多事情依賴猜測，錯誤會更可能出現。"},{"en":"The phrase suggests resourcefulness but also uncertainty.","zh":"這個短語暗示機智，但也暗示不確定性。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":11},{"front":"potential source of misunderstanding","meaning":"潛在誤解來源","examples":[{"en":"Guesswork introduces a potential source of misunderstanding.","zh":"猜測引入了潛在誤解來源。"},{"en":"A potential source of misunderstanding is something that may cause people to understand a message wrongly.","zh":"潛在誤解來源是可能令人錯誤理解信息的事物。"},{"en":"Ambiguous instructions are a potential source of misunderstanding in exams.","zh":"含糊指示是考試中的潛在誤解來源。"},{"en":"If an interpreter guesses technical terms, that guesswork may become a potential source of misunderstanding.","zh":"如果傳譯員猜測專門術語，這種猜測可能成為潛在誤解來源。"},{"en":"The phrase warns where confusion may come from.","zh":"這個短語提醒混亂可能從哪裡來。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":11},{"front":"convey both the meaning and spirit of","meaning":"傳達……的意思和神髓","examples":[{"en":"A good interpreter tries to convey both the meaning and spirit of a message.","zh":"優秀傳譯員嘗試傳達信息的意思和神髓。"},{"en":"To convey both the meaning and spirit of something means to communicate both the literal idea and the feeling or intention behind it.","zh":"“Convey both the meaning and spirit of” 某事指同時傳達字面意思和背後感覺或意圖。"},{"en":"A good translator conveys both the meaning and spirit of a poem, not just the dictionary meaning.","zh":"好譯者會傳達一首詩的意思和神髓，而不只是字典意思。"},{"en":"If humour is translated too literally, the meaning may remain but the spirit may be lost.","zh":"如果幽默被翻譯得太字面，意思可能仍在，但神髓可能流失。"},{"en":"The phrase stresses complete communication beyond words alone.","zh":"這個短語強調超越字詞本身的完整溝通。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":11},{"front":"rhetorical power","meaning":"修辭力量；說服力","examples":[{"en":"Rhetorical power is often lost through interpretation.","zh":"修辭力量常在傳譯過程中流失。"},{"en":"Rhetorical power is the persuasive force or emotional impact of spoken or written language.","zh":"修辭力量是口語或書面語言的說服力或情感影響力。"},{"en":"A speech has rhetorical power when it moves listeners and changes how they think.","zh":"當演講打動聽眾並改變他們的想法時，它就有修辭力量。"},{"en":"If a joke, rhythm, or strong image is translated poorly, rhetorical power may disappear.","zh":"如果笑話、節奏或強烈意象被翻譯得不好，修辭力量可能消失。"},{"en":"The phrase focuses on how language affects people, not just what it says.","zh":"這個短語強調語言如何影響人，而不只是語言說了甚麼。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":12},{"front":"inevitably lost","meaning":"無可避免地流失","examples":[{"en":"Some rhetorical power is inevitably lost through a third party.","zh":"一些修辭力量經第三方傳遞時無可避免地流失。"},{"en":"Inevitably lost means unavoidably lost, even with effort.","zh":"“Inevitably lost” 指即使用力避免，也無法避免地失去。"},{"en":"Some tone may be inevitably lost when a handwritten letter becomes a short text message.","zh":"當手寫信變成短訊，一些語氣可能無可避免地流失。"},{"en":"If a speech passes through interpretation, some humour may be inevitably lost.","zh":"如果演講經過傳譯，一些幽默可能無可避免地流失。"},{"en":"The phrase accepts that some loss cannot be completely prevented.","zh":"這個短語承認某些損失不能完全避免。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":12},{"front":"pass through a third party","meaning":"經第三方傳遞","examples":[{"en":"Communication changes when it passes through a third party.","zh":"溝通經第三方傳遞時會改變。"},{"en":"To pass through a third party means to be delivered through another person or organisation instead of directly.","zh":"“Pass through a third party” 指透過另一個人或機構傳達，而不是直接傳達。"},{"en":"A complaint may pass through a third party if a mediator speaks for both sides.","zh":"如果調解員代表雙方發言，投訴可能經第三方傳遞。"},{"en":"When a message passes through a third party, tone and emphasis may change.","zh":"當信息經第三方傳遞時，語氣和重點可能改變。"},{"en":"The phrase highlights the risk of indirect communication.","zh":"這個短語強調間接溝通的風險。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":12},{"front":"requiring negotiation","meaning":"需要談判的","examples":[{"en":"Some situations requiring negotiation need direct communication.","zh":"一些需要談判的情況需要直接溝通。"},{"en":"Requiring negotiation means needing discussion between sides to reach an agreement.","zh":"“Requiring negotiation” 指需要各方討論以達成協議。"},{"en":"A rent increase is a situation requiring negotiation between tenant and landlord.","zh":"加租是租客和業主之間需要談判的情況。"},{"en":"If a deal requires negotiation, unclear language can slow or damage the process.","zh":"如果交易需要談判，不清晰語言可以拖慢或破壞過程。"},{"en":"The phrase describes situations where agreement cannot simply be assumed.","zh":"這個短語描述不能簡單假定已有共識的情況。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":12},{"front":"persuasion or humour","meaning":"說服或幽默","examples":[{"en":"An interpreter may struggle to convey persuasion or humour fully.","zh":"傳譯員可能難以完整傳達說服或幽默。"},{"en":"Persuasion or humour means language used to convince people or make them laugh.","zh":"說服或幽默指用來令人相信或發笑的語言。"},{"en":"A sales pitch depends on persuasion, while a joke depends on humour.","zh":"銷售演示依賴說服，而笑話依賴幽默。"},{"en":"If persuasion or humour is translated badly, the speaker may sound weak or strange.","zh":"如果說服或幽默被翻譯得差，講者可能聽起來薄弱或奇怪。"},{"en":"The phrase groups two language effects that are hard to transfer.","zh":"這個短語把兩種難以轉移的語言效果歸在一起。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":12},{"front":"a poor substitute for","meaning":"……的不理想替代品","examples":[{"en":"An interpreter can be a poor substitute for direct communication.","zh":"傳譯員可能是直接溝通的不理想替代品。"},{"en":"A poor substitute for something is a replacement that does not work as well as the original.","zh":"某事的不理想替代品是效果不如原本事物的替代物。"},{"en":"Watching exercise videos is a poor substitute for real movement if you never practise.","zh":"如果你從不練習，看運動影片就是實際活動的不理想替代品。"},{"en":"If emotional tone matters, written notes may be a poor substitute for face-to-face conversation.","zh":"如果情感語氣很重要，書面便條可能是面對面對話的不理想替代品。"},{"en":"The phrase compares a weaker replacement with a better original.","zh":"這個短語比較較弱替代品與較好的原本事物。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":12},{"front":"direct communication","meaning":"直接溝通","examples":[{"en":"Negotiations are often easier with direct communication.","zh":"有直接溝通時，談判通常更容易。"},{"en":"Direct communication means speaking or writing to someone without another person in between.","zh":"直接溝通指不經第三者，直接與某人說話或寫信。"},{"en":"A manager can avoid confusion through direct communication with staff.","zh":"經理可以透過與員工直接溝通來避免混亂。"},{"en":"Direct communication helps people ask questions immediately and correct misunderstandings quickly.","zh":"直接溝通幫助人們即時提問並快速糾正誤解。"},{"en":"The phrase contrasts with messages passed through translators or intermediaries.","zh":"這個短語與經譯者或中間人傳遞的信息形成對比。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":12},{"front":"training","meaning":"培訓","examples":[{"en":"Training is one response to a shortage of language skills.","zh":"培訓是應對語言技能短缺的一種方法。"},{"en":"Training is organised teaching or practice designed to improve ability.","zh":"培訓是有組織的教學或練習，旨在提升能力。"},{"en":"New staff may receive training before handling customers alone.","zh":"新員工可能在獨自處理顧客前接受培訓。"},{"en":"Language training can improve communication, but it needs time and regular practice.","zh":"語言培訓可以改善溝通，但需要時間和定期練習。"},{"en":"The word is common in education, work, and professional development.","zh":"這個詞常見於教育、工作和專業發展。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":12},{"front":"understandable first response","meaning":"可理解的第一反應","examples":[{"en":"An understandable first response to a skills shortage is personnel development.","zh":"對技能短缺的可理解第一反應是人員培訓。"},{"en":"An understandable first response is the first reaction that seems reasonable in a situation.","zh":"可理解的第一反應是在某情況下看起來合理的最初反應。"},{"en":"If students fail a test, extra practice is an understandable first response.","zh":"如果學生考試不合格，額外練習是可理解的第一反應。"},{"en":"Training is understandable when skills are missing, but it may not solve everything quickly.","zh":"當技能缺失時，培訓是可理解的，但未必能迅速解決一切。"},{"en":"The phrase suggests a response is sensible, though not necessarily complete.","zh":"這個短語暗示反應合理，但不一定完整。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":12},{"front":"skills shortage","meaning":"技能短缺","examples":[{"en":"A skills shortage may lead companies to invest in training.","zh":"技能短缺可能令公司投資培訓。"},{"en":"A skills shortage happens when there are not enough people with the abilities needed for a job.","zh":"技能短缺是指擁有工作所需能力的人不足。"},{"en":"A hospital may face a skills shortage if there are too few trained nurses.","zh":"如果受訓護士太少，醫院可能面對技能短缺。"},{"en":"Skills shortages can delay projects and increase hiring costs.","zh":"技能短缺可以延誤項目並增加招聘成本。"},{"en":"The phrase is often used in employment and workforce planning.","zh":"這個短語常用於就業和人力規劃。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":12},{"front":"personnel development","meaning":"人員培訓；員工發展","examples":[{"en":"Personnel development is a common response to a skills shortage.","zh":"人員培訓是對技能短缺的常見應對方法。"},{"en":"Personnel development means improving employees’ skills, knowledge, and performance through training and support.","zh":"人員培訓指透過培訓和支援提升員工技能、知識和表現。"},{"en":"A company may use personnel development to prepare junior staff for management roles.","zh":"公司可能使用人員培訓，讓初級員工準備擔任管理職位。"},{"en":"If personnel development stops during difficult times, skills may decline.","zh":"如果人員培訓在困難時期停止，技能可能下降。"},{"en":"The phrase is formal and common in human resources.","zh":"這個短語較正式，常見於人力資源。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":12},{"front":"language-training industry","meaning":"語言培訓行業","examples":[{"en":"The language-training industry is well established.","zh":"語言培訓行業已發展成熟。"},{"en":"The language-training industry consists of schools, tutors, platforms, and companies that teach languages.","zh":"語言培訓行業由教授語言的學校、導師、平台和公司組成。"},{"en":"Online platforms are now an important part of the language-training industry.","zh":"網上平台現在是語言培訓行業的重要部分。"},{"en":"If demand for English rises, the language-training industry may expand.","zh":"如果英語需求上升，語言培訓行業可能擴展。"},{"en":"The phrase treats language teaching as a professional business sector.","zh":"這個短語把語言教學視為專業商業界別。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":13},{"front":"well established","meaning":"發展成熟的","examples":[{"en":"The language-training industry is well established.","zh":"語言培訓行業已發展成熟。"},{"en":"Well established means existing for a long time and widely recognised or accepted.","zh":"“Well established” 指存在已久，並被廣泛認可或接受。"},{"en":"This clinic is well established and has served the community for thirty years.","zh":"這間診所發展成熟，已服務社區三十年。"},{"en":"If a training provider is well established, customers may trust it more easily.","zh":"如果培訓機構發展成熟，顧客可能更容易信任它。"},{"en":"The phrase suggests stability, experience, and recognition.","zh":"這個短語暗示穩定、經驗和認可。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":13},{"front":"at almost every level","meaning":"幾乎涵蓋所有程度","examples":[{"en":"Language programmes are available at almost every level.","zh":"語言課程幾乎涵蓋所有程度。"},{"en":"At almost every level means for nearly all stages of ability or difficulty.","zh":"“At almost every level” 指幾乎適用於所有能力或難度階段。"},{"en":"A sports club may offer classes at almost every level, from beginners to advanced players.","zh":"運動俱樂部可能提供幾乎涵蓋所有程度的課程，由初學者到高階選手。"},{"en":"If language courses exist at almost every level, more learners can find a suitable class.","zh":"如果語言課程幾乎涵蓋所有程度，更多學習者可以找到合適課堂。"},{"en":"The phrase emphasises wide coverage.","zh":"這個短語強調覆蓋範圍廣。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":13},{"front":"in numerous languages","meaning":"以眾多語言","examples":[{"en":"Training programmes are offered in numerous languages.","zh":"培訓課程以眾多語言提供。"},{"en":"In numerous languages means in many different languages.","zh":"“In numerous languages” 指以許多不同語言。"},{"en":"A tourist website may provide information in numerous languages.","zh":"旅遊網站可能以眾多語言提供資訊。"},{"en":"If support is offered in numerous languages, more customers can understand it.","zh":"如果支援以眾多語言提供，更多顧客可以理解它。"},{"en":"The phrase highlights language variety and broad accessibility.","zh":"這個短語強調語言多樣性和廣泛可用性。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":13},{"front":"without doubting the value of","meaning":"並非懷疑……的價值","examples":[{"en":"Without doubting the value of training, companies should not rely on it alone.","zh":"並非懷疑培訓的價值，但公司不應只依賴它。"},{"en":"Without doubting the value of something means accepting that it is useful while still pointing out its limits.","zh":"“Without doubting the value of” 某事指承認它有用，同時指出其限制。"},{"en":"Without doubting the value of exercise, doctors may still say diet also matters.","zh":"並非懷疑運動的價值，但醫生仍可能說飲食也重要。"},{"en":"Without doubting the value of translation, companies should still develop internal language skills.","zh":"並非懷疑翻譯的價值，但公司仍應發展內部語言技能。"},{"en":"The phrase is useful for balanced criticism.","zh":"這個短語適合用於平衡批評。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":13},{"front":"guarantees success","meaning":"保證成功","examples":[{"en":"No company should assume that training guarantees success.","zh":"沒有公司應假設培訓保證成功。"},{"en":"If something guarantees success, it ensures that success will definitely happen.","zh":"如果某事保證成功，它就確保成功一定會發生。"},{"en":"Buying expensive books does not guarantee success if students never practise.","zh":"如果學生從不練習，購買昂貴書籍並不保證成功。"},{"en":"Training may improve ability, but it does not guarantee success without commitment.","zh":"培訓可能提升能力，但沒有投入並不保證成功。"},{"en":"The phrase is often used to warn against overconfidence.","zh":"這個短語常用來提醒人避免過度自信。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":13},{"front":"follow the economic cycle","meaning":"跟隨經濟周期","examples":[{"en":"Training in most companies follows the economic cycle.","zh":"大多數公司的培訓跟隨經濟周期。"},{"en":"To follow the economic cycle means to rise and fall with periods of growth and difficulty in the economy.","zh":"“Follow the economic cycle” 指隨着經濟增長和困難時期而上升和下降。"},{"en":"Hiring often follows the economic cycle, increasing in good times and slowing in recessions.","zh":"招聘常跟隨經濟周期，在景氣好時增加，在衰退時放慢。"},{"en":"If training follows the economic cycle, it may be cut exactly when workers need new skills.","zh":"如果培訓跟隨經濟周期，它可能正正在員工需要新技能時被削減。"},{"en":"The phrase links company behaviour to wider economic conditions.","zh":"這個短語把公司行為與更廣泛經濟狀況連繫起來。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":13},{"front":"when times are good","meaning":"當景氣好時","examples":[{"en":"When times are good, companies invest in training.","zh":"當景氣好時，公司投資培訓。"},{"en":"When times are good means during periods when business or the economy is doing well.","zh":"“When times are good” 指商業或經濟表現良好的時期。"},{"en":"When times are good, families may spend more on travel and restaurants.","zh":"當景氣好時，家庭可能在旅遊和餐廳花更多錢。"},{"en":"Companies often hire more staff when times are good.","zh":"當景氣好時，公司通常聘請更多員工。"},{"en":"The phrase contrasts prosperous periods with difficult periods.","zh":"這個短語把繁榮時期與困難時期作對比。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":13},{"front":"invest money","meaning":"投放資金","examples":[{"en":"Companies invest money in training during good times.","zh":"公司在景氣好時投放資金於培訓。"},{"en":"To invest money means to spend money now in the hope of future benefit.","zh":"“Invest money” 指現在花錢，希望將來獲得好處。"},{"en":"Parents may invest money in their child’s education.","zh":"家長可能投放資金於孩子教育。"},{"en":"If a company invests money in language training, staff may communicate better with clients later.","zh":"如果公司投放資金於語言培訓，員工日後可能與客戶溝通得更好。"},{"en":"The phrase suggests spending for growth, not just ordinary expense.","zh":"這個短語暗示為增長而花錢，而不只是普通開支。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":13},{"front":"when belts tighten","meaning":"當財政緊縮時","examples":[{"en":"When belts tighten, training is often cut.","zh":"當財政緊縮時，培訓常被削減。"},{"en":"When belts tighten means when people or organisations have less money and must reduce spending.","zh":"“When belts tighten” 指人們或機構金錢較少，必須減少開支。"},{"en":"When belts tighten, families may eat out less often.","zh":"當財政緊縮時，家庭可能較少外出用餐。"},{"en":"If belts tighten during a recession, companies may reduce travel, hiring, and training.","zh":"如果經濟衰退期間財政緊縮，公司可能減少差旅、招聘和培訓。"},{"en":"The phrase is informal and linked to financial pressure.","zh":"這個短語較口語，與財政壓力有關。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":13},{"front":"one of the first luxuries to be cut","meaning":"最先被削減的奢侈項目之一","examples":[{"en":"Training is one of the first luxuries to be cut during difficult times.","zh":"在困難時期，培訓是最先被削減的奢侈項目之一。"},{"en":"One of the first luxuries to be cut means one of the non-essential expenses removed early when money is tight.","zh":"“One of the first luxuries to be cut” 指在金錢緊張時最早被移除的非必要開支之一。"},{"en":"Family holidays may be one of the first luxuries to be cut after a job loss.","zh":"失業後，家庭旅行可能是最先被削減的奢侈項目之一。"},{"en":"If training is treated as a luxury, companies may cut it before realising its long-term value.","zh":"如果培訓被視為奢侈品，公司可能在意識到其長期價值前削減它。"},{"en":"The phrase suggests something useful may still be seen as optional.","zh":"這個短語暗示某事有用，但仍可能被視為可有可無。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":13},{"front":"conduct a study across","meaning":"在……進行研究","examples":[{"en":"Researchers conducted a study across four European countries.","zh":"研究人員在四個歐洲國家進行研究。"},{"en":"To conduct a study across places means to carry out research in several locations or groups.","zh":"“Conduct a study across” 多個地方指在幾個地點或群體中進行研究。"},{"en":"A university may conduct a study across five schools to compare learning habits.","zh":"大學可能在五間學校進行研究，以比較學習習慣。"},{"en":"If researchers conduct a study across countries, they can compare different markets.","zh":"如果研究人員在多國進行研究，他們可以比較不同市場。"},{"en":"The phrase is useful for describing broad research coverage.","zh":"這個短語適合描述研究覆蓋範圍廣。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":14},{"front":"nearly twice as many","meaning":"接近兩倍數量的","examples":[{"en":"Nearly twice as many companies said they would need language training.","zh":"接近兩倍數量的公司表示它們將需要語言培訓。"},{"en":"Nearly twice as many means almost double the number.","zh":"“Nearly twice as many” 指數量接近兩倍。"},{"en":"Nearly twice as many students joined the revision class this year.","zh":"今年接近兩倍數量的學生參加溫習班。"},{"en":"If nearly twice as many customers ask for online support, the company needs more staff.","zh":"如果接近兩倍數量的顧客要求網上支援，公司便需要更多員工。"},{"en":"The phrase compares two quantities and shows a large increase.","zh":"這個短語比較兩個數量並顯示大幅增加。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":14},{"front":"in the coming years","meaning":"在未來數年","examples":[{"en":"More companies expected to need language training in the coming years.","zh":"更多公司預期在未來數年需要語言培訓。"},{"en":"In the coming years means during the next few years in the future.","zh":"“In the coming years” 指未來幾年期間。"},{"en":"In the coming years, more schools may use digital textbooks.","zh":"在未來數年，更多學校可能使用電子教科書。"},{"en":"If demand grows in the coming years, companies should prepare early.","zh":"如果需求在未來數年增長，公司應及早準備。"},{"en":"The phrase looks forward from the present or from the time being discussed.","zh":"這個短語從現在或討論時間向未來看。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":14},{"front":"in previous years","meaning":"在過往數年","examples":[{"en":"Fewer companies had provided language training in previous years.","zh":"較少公司在過往數年提供語言培訓。"},{"en":"In previous years means during the years before the time being discussed.","zh":"“In previous years” 指在正在討論時間之前的那些年份。"},{"en":"In previous years, the school held exams in May instead of June.","zh":"在過往數年，學校在五月而不是六月舉行考試。"},{"en":"If fewer people attended in previous years, this year’s crowd may surprise organisers.","zh":"如果過往數年出席人數較少，今年的人潮可能令主辦方驚訝。"},{"en":"The phrase refers back to an earlier period.","zh":"這個短語回指較早時期。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":14},{"front":"disparity between","meaning":"……之間的差距","examples":[{"en":"The disparity between good intentions and actual delivery is significant.","zh":"良好意願與實際執行之間的差距很明顯。"},{"en":"A disparity between two things is a noticeable gap or difference between them.","zh":"“Disparity between” 兩件事指它們之間明顯的差距或差異。"},{"en":"There may be a disparity between what students plan to revise and what they actually finish.","zh":"學生計劃溫習的內容與實際完成的內容之間可能有差距。"},{"en":"If there is a disparity between promise and action, trust may decline.","zh":"如果承諾與行動之間有差距，信任可能下降。"},{"en":"The phrase is useful when comparing expectations with reality.","zh":"這個短語適合比較期望與現實。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":14},{"front":"good intentions","meaning":"良好意願","examples":[{"en":"Many companies have good intentions about language training.","zh":"許多公司對語言培訓有良好意願。"},{"en":"Good intentions are sincere wishes to do the right or helpful thing.","zh":"良好意願是真誠希望做正確或有幫助事情的心意。"},{"en":"A teacher may have good intentions when giving extra homework, but students may feel overloaded.","zh":"老師給額外功課可能有良好意願，但學生可能感到負擔過重。"},{"en":"Good intentions do not solve problems unless they lead to practical action.","zh":"良好意願如果沒有帶來實際行動，就不能解決問題。"},{"en":"The phrase often contrasts kind aims with weak results.","zh":"這個短語常把善意目標與薄弱結果作對比。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":14},{"front":"actual delivery","meaning":"實際執行","examples":[{"en":"Actual delivery often falls short of good intentions.","zh":"實際執行常常未達良好意願。"},{"en":"Actual delivery means what is really done or provided, not just what was promised.","zh":"實際執行指真正完成或提供的事情，而不只是承諾。"},{"en":"A school may promise support, but actual delivery depends on teachers, time, and resources.","zh":"學校可能承諾支援，但實際執行取決於老師、時間和資源。"},{"en":"If actual delivery is weak, customers may ignore future promises.","zh":"如果實際執行薄弱，顧客可能不再相信未來承諾。"},{"en":"The phrase separates real action from planned action.","zh":"這個短語把真實行動與計劃行動分開。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":14},{"front":"underline the problems of","meaning":"突顯……的問題","examples":[{"en":"The disparity underlines the problems of relying on training.","zh":"這個差距突顯依賴培訓的問題。"},{"en":"To underline the problems of something means to emphasise or make its weaknesses clear.","zh":"“Underline the problems of” 某事指強調或清楚顯示其弱點。"},{"en":"Long waiting times underline the problems of understaffed hospitals.","zh":"漫長等候時間突顯醫院人手不足的問題。"},{"en":"If promised training never happens, it underlines the problems of relying on plans alone.","zh":"如果承諾的培訓從未發生，它便突顯只依賴計劃的問題。"},{"en":"The phrase shows that evidence makes a problem more visible.","zh":"這個短語顯示證據令問題更明顯。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":14},{"front":"rely on training for","meaning":"依賴培訓來獲得……","examples":[{"en":"Companies should not rely only on training for language skills.","zh":"公司不應只依賴培訓來獲得語言技能。"},{"en":"To rely on training for something means to depend on training to provide that ability or result.","zh":"“Rely on training for” 某事指依靠培訓來提供該能力或結果。"},{"en":"A school should not rely only on training for better teaching if teachers have no preparation time.","zh":"如果老師沒有備課時間，學校不應只依賴培訓來改善教學。"},{"en":"If companies rely on training for language skills, they must fund it consistently.","zh":"如果公司依賴培訓來獲得語言技能，就必須持續提供資金。"},{"en":"The phrase warns that training may need support from other methods.","zh":"這個短語提醒培訓可能需要其他方法支援。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":14},{"front":"language skills","meaning":"語言技能","examples":[{"en":"Language skills require sustained investment.","zh":"語言技能需要持續投資。"},{"en":"Language skills are abilities in speaking, listening, reading, writing, or translating a language.","zh":"語言技能是說、聽、讀、寫或翻譯某語言的能力。"},{"en":"Receptionists need language skills when helping tourists from different countries.","zh":"接待員幫助來自不同國家的遊客時需要語言技能。"},{"en":"If language skills are weak, even simple business tasks may become slow.","zh":"如果語言技能薄弱，即使簡單商業任務也可能變慢。"},{"en":"The phrase covers practical ability, not just grammar knowledge.","zh":"這個短語涵蓋實際能力，而不只是文法知識。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":14},{"front":"fully committed to","meaning":"全心投入於","examples":[{"en":"A company must be fully committed to sustaining the strategy.","zh":"公司必須全心投入於維持該策略。"},{"en":"To be fully committed to something means to support it seriously with time, money, and effort.","zh":"“Be fully committed to” 某事指以時間、金錢和努力認真支持它。"},{"en":"A student fully committed to improving pronunciation practises a little every day.","zh":"全心投入改善發音的學生每天練習一點。"},{"en":"If managers are not fully committed to training, the programme may disappear when money is tight.","zh":"如果管理層不是全心投入於培訓，該計劃可能在資金緊張時消失。"},{"en":"The phrase shows strong, long-term dedication.","zh":"這個短語顯示強烈而長期的投入。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":14},{"front":"sustain the strategy","meaning":"維持策略","examples":[{"en":"Training will fail unless the company can sustain the strategy.","zh":"除非公司能維持策略，否則培訓會失敗。"},{"en":"To sustain the strategy means to keep supporting and continuing the plan over time.","zh":"“Sustain the strategy” 指隨時間持續支持和延續該計劃。"},{"en":"A school must sustain its reading strategy for several years to see results.","zh":"學校必須維持閱讀策略數年才會看到成果。"},{"en":"If a company cannot sustain the strategy through hard times, early progress may be wasted.","zh":"如果公司不能在艱難時期維持策略，早期進展可能被浪費。"},{"en":"The phrase focuses on long-term continuation, not just starting well.","zh":"這個短語強調長期延續，而不只是開始得好。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":15},{"front":"through difficult times","meaning":"在艱難時期","examples":[{"en":"Companies must sustain training through difficult times.","zh":"公司必須在艱難時期維持培訓。"},{"en":"Through difficult times means during periods of trouble, pressure, or financial hardship.","zh":"“Through difficult times” 指在麻煩、壓力或財政困難時期。"},{"en":"Friends who support each other through difficult times often become closer.","zh":"在艱難時期互相支持的朋友通常會變得更親近。"},{"en":"If training continues through difficult times, employees may feel the company truly values development.","zh":"如果培訓在艱難時期仍然繼續，員工可能覺得公司真正重視發展。"},{"en":"The phrase stresses endurance when conditions are not easy.","zh":"這個短語強調在情況不容易時堅持下去。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":15},{"front":"notable and committed leader","meaning":"顯著而投入的領導者","examples":[{"en":"Volkswagen is a notable and committed leader in language training.","zh":"大眾汽車是語言培訓方面顯著而投入的領導者。"},{"en":"A notable and committed leader is an organisation or person that stands out and shows serious long-term effort.","zh":"顯著而投入的領導者是表現突出並展現認真長期努力的機構或人士。"},{"en":"A school may be a notable and committed leader in supporting special-needs students.","zh":"學校可能成為支援特殊教育需要學生方面顯著而投入的領導者。"},{"en":"If a company invests for many years, it may become a notable and committed leader in staff development.","zh":"如果公司多年投資，它可能成為員工發展方面顯著而投入的領導者。"},{"en":"The phrase praises both visibility and dedication.","zh":"這個短語同時稱讚可見成就和投入程度。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":15},{"front":"the Volkswagen Group","meaning":"大眾汽車集團","examples":[{"en":"The Volkswagen Group has developed a long-term language strategy.","zh":"大眾汽車集團制定了長期語言策略。"},{"en":"The Volkswagen Group is a large international car company group used here as an example of language management.","zh":"大眾汽車集團是一個大型國際汽車公司集團，在此用作語言管理例子。"},{"en":"The Volkswagen Group may need staff to communicate across factories, offices, and markets.","zh":"大眾汽車集團可能需要員工在工廠、辦公室和市場之間溝通。"},{"en":"If a company like the Volkswagen Group trains staff for years, language ability can become part of strategy.","zh":"如果像大眾汽車集團這樣的公司多年培訓員工，語言能力可以成為策略的一部分。"},{"en":"The phrase names a specific multinational company group.","zh":"這個短語指一個特定跨國公司集團。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":15},{"front":"develop a language strategy","meaning":"制定語言策略","examples":[{"en":"Volkswagen has developed a language strategy over many years.","zh":"大眾汽車經過多年制定語言策略。"},{"en":"To develop a language strategy means to build a planned approach to language use and training.","zh":"“Develop a language strategy” 指建立有計劃的語言使用和培訓方法。"},{"en":"A university may develop a language strategy for international students and staff.","zh":"大學可能為國際學生和員工制定語言策略。"},{"en":"If a company develops a language strategy slowly and carefully, it can match real business needs.","zh":"如果公司緩慢而謹慎地制定語言策略，就能配合真實商業需要。"},{"en":"The phrase suggests planning, testing, and improving over time.","zh":"這個短語暗示隨時間規劃、測試和改善。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":15},{"front":"over many years","meaning":"經過多年","examples":[{"en":"The company developed its language strategy over many years.","zh":"該公司經過多年制定其語言策略。"},{"en":"Over many years means during a long period of time.","zh":"“Over many years” 指在很長一段時間內。"},{"en":"A musician improves over many years through practice and performance.","zh":"音樂家經過多年練習和演出而進步。"},{"en":"If language ability is built over many years, it is usually stronger than a short course result.","zh":"如果語言能力經過多年建立，通常比短期課程成果更穩固。"},{"en":"The phrase stresses gradual long-term development.","zh":"這個短語強調逐步長期發展。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":15},{"front":"in many respects","meaning":"在許多方面","examples":[{"en":"In many respects, Volkswagen provides a model of language management.","zh":"在許多方面，大眾汽車提供了語言管理的典範。"},{"en":"In many respects means in many ways or from many points of view.","zh":"“In many respects” 指在許多方式或許多角度上。"},{"en":"In many respects, online learning is convenient, but it still needs discipline.","zh":"在許多方面，網上學習很方便，但仍需要自律。"},{"en":"A school may be successful in many respects while still needing better facilities.","zh":"一間學校可能在許多方面成功，但仍需要更好設施。"},{"en":"The phrase allows a balanced statement without saying something is perfect.","zh":"這個短語讓人作出平衡陳述，而不是說某事完美。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":15},{"front":"provide a model of","meaning":"提供……的典範","examples":[{"en":"Volkswagen provides a model of professional language management.","zh":"大眾汽車提供了專業語言管理的典範。"},{"en":"To provide a model of something means to offer an example that others can learn from.","zh":"“Provide a model of” 某事指提供一個其他人可以學習的例子。"},{"en":"A well-run clinic can provide a model of patient care for other hospitals.","zh":"營運良好的診所可以為其他醫院提供病人護理的典範。"},{"en":"If a company provides a model of language training, other firms may copy its system.","zh":"如果公司提供語言培訓的典範，其他企業可能模仿其制度。"},{"en":"The phrase highlights an example worth following.","zh":"這個短語強調值得仿效的例子。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":15},{"front":"professional language management","meaning":"專業語言管理","examples":[{"en":"Volkswagen provides a model of professional language management.","zh":"大眾汽車提供了專業語言管理的典範。"},{"en":"Professional language management is organised, planned, and expert handling of multilingual communication.","zh":"專業語言管理是有組織、有計劃並具專業性的多語溝通處理。"},{"en":"Professional language management may include training, testing, translators, and clear company rules.","zh":"專業語言管理可能包括培訓、測驗、筆譯員和清晰公司規則。"},{"en":"If language management is professional, staff know what support to use in different situations.","zh":"如果語言管理專業，員工知道在不同情況下使用甚麼支援。"},{"en":"The phrase contrasts with casual or improvised communication.","zh":"這個短語與隨意或臨時拼湊的溝通形成對比。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":15},{"front":"emphasise that","meaning":"強調","examples":[{"en":"The Volkswagen approach emphasises that training must be strategic.","zh":"大眾汽車的方法強調培訓必須具戰略性。"},{"en":"To emphasise that something is true means to stress it as important.","zh":"“Emphasise that” 某事為真指強調它很重要。"},{"en":"A doctor may emphasise that sleep is necessary for recovery.","zh":"醫生可能強調睡眠對康復是必要的。"},{"en":"If managers emphasise that training is long-term, employees may expect gradual progress.","zh":"如果經理強調培訓是長期的，員工可能預期逐步進步。"},{"en":"The phrase introduces a point the speaker wants readers to notice.","zh":"這個短語引出說話者希望讀者注意的重點。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":15},{"front":"strategic rather than tactical","meaning":"戰略性而非戰術性","examples":[{"en":"Language training should be a strategic rather than tactical solution.","zh":"語言培訓應是戰略性而非戰術性的解決方案。"},{"en":"Strategic rather than tactical means focused on long-term goals instead of short-term fixes.","zh":"“Strategic rather than tactical” 指集中於長期目標，而不是短期修補。"},{"en":"Saving money every month is strategic rather than tactical if the goal is buying a home.","zh":"如果目標是買樓，每月儲蓄就是戰略性而非戰術性的做法。"},{"en":"If language training is strategic rather than tactical, the company keeps supporting it for years.","zh":"如果語言培訓是戰略性而非戰術性的，公司會多年持續支持它。"},{"en":"The phrase clearly contrasts long-term planning with quick response.","zh":"這個短語清楚對比長期規劃與快速反應。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":15},{"front":"tactical solution","meaning":"戰術性方案","examples":[{"en":"Volkswagen does not see language training as merely a tactical solution.","zh":"大眾汽車不把語言培訓視為純粹戰術性方案。"},{"en":"A tactical solution is a short-term or immediate fix for a specific problem.","zh":"戰術性方案是針對特定問題的短期或即時修補方法。"},{"en":"Hiring a temporary receptionist may be a tactical solution to sudden staff absence.","zh":"聘請臨時接待員可能是應對突發缺勤的戰術性方案。"},{"en":"A tactical solution may help today but fail if the same problem returns next year.","zh":"戰術性方案可能今天有幫助，但如果同一問題明年再出現就會失敗。"},{"en":"The phrase contrasts with strategic long-term planning.","zh":"這個短語與戰略性長期規劃形成對比。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":16},{"front":"require completion of","meaning":"要求完成","examples":[{"en":"The system requires completion of six language stages.","zh":"該制度要求完成六個語言階段。"},{"en":"To require completion of something means to make finishing it necessary.","zh":"“Require completion of” 某事指規定必須完成它。"},{"en":"A university course may require completion of several core modules.","zh":"大學課程可能要求完成幾個核心單元。"},{"en":"If promotion requires completion of training, staff have a clear goal.","zh":"如果晉升要求完成培訓，員工就有清晰目標。"},{"en":"The phrase is formal and common in rules, courses, and programmes.","zh":"這個短語較正式，常見於規則、課程和計劃。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":16},{"front":"language stages","meaning":"語言學習階段","examples":[{"en":"Volkswagen’s system includes six language stages.","zh":"大眾汽車的制度包括六個語言學習階段。"},{"en":"Language stages are levels of language learning that move from easier to more advanced skills.","zh":"語言學習階段是由較容易技能進展至較高階技能的語言學習級別。"},{"en":"A beginner stage may teach greetings, while a higher stage may teach meetings and reports.","zh":"初級階段可能教授問候，而較高階階段可能教授會議和報告。"},{"en":"Clear language stages help learners know what they have achieved and what comes next.","zh":"清晰語言學習階段幫助學習者知道自己已達成甚麼，以及下一步是甚麼。"},{"en":"The phrase organises language progress into steps.","zh":"這個短語把語言進步組織成步驟。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":16},{"front":"progress from basics to","meaning":"由基礎進展至","examples":[{"en":"Learners progress from basics to communication competence.","zh":"學習者由基礎進展至溝通能力。"},{"en":"To progress from basics to something means to move from simple foundation skills to a higher ability.","zh":"“Progress from basics to” 某能力指由簡單基礎技能進展至較高能力。"},{"en":"Piano students progress from basics to full songs through regular practice.","zh":"鋼琴學生透過定期練習由基礎進展至完整歌曲。"},{"en":"If learners progress from basics to real conversation, training becomes more useful.","zh":"如果學習者由基礎進展至真實對話，培訓會更有用。"},{"en":"The phrase shows step-by-step improvement.","zh":"這個短語顯示逐步改善。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":16},{"front":"communication competence","meaning":"溝通能力","examples":[{"en":"The aim is to develop communication competence.","zh":"目標是培養溝通能力。"},{"en":"Communication competence is the ability to express, understand, and respond effectively in real situations.","zh":"溝通能力是在真實情況中有效表達、理解和回應的能力。"},{"en":"A receptionist needs communication competence to handle questions politely and clearly.","zh":"接待員需要溝通能力來禮貌而清楚地處理問題。"},{"en":"If language training builds communication competence, staff can use the language at work, not just pass tests.","zh":"如果語言培訓建立溝通能力，員工就能在工作中使用該語言，而不只是通過測驗。"},{"en":"The phrase focuses on practical communication ability.","zh":"這個短語強調實際溝通能力。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":16},{"front":"demand approximately","meaning":"要求大約","examples":[{"en":"Each stage demands approximately 90 hours of instruction.","zh":"每個階段要求大約90小時教學。"},{"en":"To demand approximately an amount means to require about that amount.","zh":"“Demand approximately” 某數量指要求大約該數量。"},{"en":"A driving course may demand approximately twenty hours of practice before the test.","zh":"駕駛課程可能在考試前要求大約二十小時練習。"},{"en":"If each stage demands approximately 90 hours, companies must plan time and staffing carefully.","zh":"如果每個階段要求大約90小時，公司必須謹慎規劃時間和人手。"},{"en":"The phrase combines requirement with an estimated number.","zh":"這個短語把要求與估算數字結合。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":16},{"front":"refresher instruction","meaning":"複習式教學","examples":[{"en":"Each stage demands approximately 90 hours of refresher instruction.","zh":"每個階段要求大約90小時複習式教學。"},{"en":"Refresher instruction is teaching that helps learners review and strengthen knowledge they already learned.","zh":"複習式教學是幫助學習者重溫和鞏固已學知識的教學。"},{"en":"Nurses may attend refresher instruction to update safety procedures.","zh":"護士可能參加複習式教學，以更新安全程序。"},{"en":"If employees forget a language after years of disuse, refresher instruction can rebuild confidence.","zh":"如果員工多年不用某語言而忘記，複習式教學可以重建信心。"},{"en":"The phrase focuses on review rather than completely new learning.","zh":"這個短語強調重溫，而不是完全新學習。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":16},{"front":"be supported by","meaning":"由……支援","examples":[{"en":"Formal instruction is supported by many hours of self-study.","zh":"正式教學由多小時自學支援。"},{"en":"To be supported by something means to receive help, backing, or reinforcement from it.","zh":"“Be supported by” 某事指得到它的幫助、支持或加強。"},{"en":"A school project can be supported by library research and teacher feedback.","zh":"學校項目可以由圖書館研究和老師回饋支援。"},{"en":"If classroom lessons are supported by self-study, learning may become stronger.","zh":"如果課堂學習由自學支援，學習可能更穩固。"},{"en":"The phrase shows that one activity strengthens another.","zh":"這個短語顯示一項活動加強另一項活動。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":16},{"front":"self-study","meaning":"自學","examples":[{"en":"Self-study is an important part of Volkswagen’s language programme.","zh":"自學是大眾汽車語言計劃的重要部分。"},{"en":"Self-study means learning by oneself outside formal lessons.","zh":"自學指在正式課堂以外自己學習。"},{"en":"A student can use self-study to review vocabulary on the bus.","zh":"學生可以在巴士上透過自學重溫詞彙。"},{"en":"Without self-study, language learners may forget what they learned in class.","zh":"沒有自學，語言學習者可能忘記課堂所學。"},{"en":"The phrase highlights personal responsibility in learning.","zh":"這個短語強調學習中的個人責任。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":16},{"front":"over six to nine months","meaning":"在六至九個月內","examples":[{"en":"Each stage takes place over six to nine months.","zh":"每個階段在六至九個月內進行。"},{"en":"Over six to nine months means during a period lasting between six and nine months.","zh":"“Over six to nine months” 指在持續六至九個月的時期內。"},{"en":"A fitness plan may show results over six to nine months if followed regularly.","zh":"如果定期跟隨，健身計劃可能在六至九個月內見到成果。"},{"en":"If a course takes place over six to nine months, learners need patience and routine.","zh":"如果課程在六至九個月內進行，學習者需要耐性和習慣。"},{"en":"The phrase describes a medium-length time frame.","zh":"這個短語描述中等長度的時間範圍。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":16},{"front":"be marked by","meaning":"以……作為標誌","examples":[{"en":"Completion of each stage is marked by an achievement test.","zh":"每個階段的完成以成績測驗作為標誌。"},{"en":"To be marked by something means to be shown, recognised, or characterised by it.","zh":"“Be marked by” 某事指由它顯示、確認或作為特徵。"},{"en":"The end of the school year is marked by a graduation ceremony.","zh":"學年結束以畢業典禮作為標誌。"},{"en":"If each stage is marked by a test, learners know when they have completed it.","zh":"如果每個階段以測驗作為標誌，學習者就知道自己何時完成。"},{"en":"The phrase shows how a point or event is identified.","zh":"這個短語顯示一個階段或事件如何被識別。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":16},{"front":"achievement test","meaning":"成績測驗","examples":[{"en":"An achievement test is required at the end of each stage.","zh":"每個階段結束時都需要成績測驗。"},{"en":"An achievement test measures what learners have successfully learned or mastered.","zh":"成績測驗衡量學習者已成功學會或掌握甚麼。"},{"en":"A music student may take an achievement test after finishing a level.","zh":"音樂學生完成一個級別後可能參加成績測驗。"},{"en":"If an achievement test is too easy, it may not show real ability.","zh":"如果成績測驗太容易，它可能不能顯示真正能力。"},{"en":"The phrase is common in structured learning programmes.","zh":"這個短語常見於結構化學習計劃。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":17},{"front":"prerequisite for","meaning":"……的先決條件","examples":[{"en":"Passing the test is a prerequisite for further training.","zh":"通過測驗是進一步培訓的先決條件。"},{"en":"A prerequisite for something is a condition that must be completed before it can happen.","zh":"某事的先決條件是在它發生前必須完成的條件。"},{"en":"Basic swimming ability is a prerequisite for joining the diving course.","zh":"基本游泳能力是參加潛水課程的先決條件。"},{"en":"If passing Stage One is a prerequisite for Stage Two, learners cannot skip the basics.","zh":"如果通過第一階段是第二階段的先決條件，學習者就不能跳過基礎。"},{"en":"The phrase shows a required step before the next stage.","zh":"這個短語顯示下一階段之前所需的步驟。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":17},{"front":"further training","meaning":"進一步培訓","examples":[{"en":"An achievement test is required before further training.","zh":"進一步培訓前需要成績測驗。"},{"en":"Further training means additional training after an earlier stage has been completed.","zh":"進一步培訓指完成較早階段後的額外培訓。"},{"en":"New teachers may receive further training after their first term.","zh":"新老師可能在第一學期後接受進一步培訓。"},{"en":"If staff fail the test, they may need review before further training.","zh":"如果員工未能通過測驗，他們可能需要重溫後才接受進一步培訓。"},{"en":"The phrase shows learning continuing beyond the first level.","zh":"這個短語顯示學習延續至第一級以後。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":17},{"front":"professionally managed programme","meaning":"專業管理的計劃","examples":[{"en":"The Volkswagen programme is a professionally managed programme.","zh":"大眾汽車計劃是一個專業管理的計劃。"},{"en":"A professionally managed programme is organised, monitored, and improved by people with proper expertise.","zh":"專業管理的計劃由具備適當專業知識的人組織、監察和改善。"},{"en":"A professionally managed programme has clear goals, records, teachers, and assessment.","zh":"專業管理的計劃有清晰目標、紀錄、教師和評估。"},{"en":"If a language course is professionally managed, learners are less likely to drift without progress.","zh":"如果語言課程是專業管理的，學習者較不可能沒有進展地漂流。"},{"en":"The phrase contrasts with casual or poorly organised training.","zh":"這個短語與隨意或組織欠佳的培訓形成對比。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":17},{"front":"expect a minimum of","meaning":"預期至少","examples":[{"en":"The programme expects a minimum of three years of intensive study.","zh":"該計劃預期至少三年的密集學習。"},{"en":"To expect a minimum of something means to require at least that amount.","zh":"“Expect a minimum of” 某數量指要求至少該數量。"},{"en":"A university may expect a minimum of two references from each applicant.","zh":"大學可能要求每名申請人至少提供兩封推薦信。"},{"en":"If a programme expects a minimum of three years, learners should not expect quick fluency.","zh":"如果計劃預期至少三年，學習者不應期待快速流利。"},{"en":"The phrase sets the lowest acceptable amount.","zh":"這個短語設定最低可接受數量。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":17},{"front":"fairly intensive study","meaning":"相當密集的學習","examples":[{"en":"Professionals need fairly intensive study to work in a foreign language.","zh":"專業人士需要相當密集的學習，才能以外語工作。"},{"en":"Fairly intensive study means study that is quite demanding and requires regular effort.","zh":"相當密集的學習指要求頗高並需要定期努力的學習。"},{"en":"Preparing for a language exam may require fairly intensive study for several months.","zh":"準備語言考試可能需要數月相當密集的學習。"},{"en":"If workers need to use a language professionally, casual practice may not replace intensive study.","zh":"如果員工需要專業地使用一種語言，隨意練習可能不能取代密集學習。"},{"en":"The phrase suggests serious but not extreme learning effort.","zh":"這個短語暗示認真但非極端的學習努力。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":17},{"front":"capable of working effectively","meaning":"能夠有效工作","examples":[{"en":"The aim is to produce staff capable of working effectively in a foreign language.","zh":"目標是培養能夠以外語有效工作的員工。"},{"en":"Capable of working effectively means able to perform tasks well and reliably.","zh":"“Capable of working effectively” 指能夠良好而可靠地完成任務。"},{"en":"A nurse capable of working effectively under pressure can still make calm decisions.","zh":"能夠在壓力下有效工作的護士仍可以冷靜作決定。"},{"en":"If staff are capable of working effectively in another language, they can handle meetings and documents.","zh":"如果員工能夠以另一種語言有效工作，他們就能處理會議和文件。"},{"en":"The phrase focuses on real work performance, not only classroom knowledge.","zh":"這個短語強調真實工作表現，而不只是課堂知識。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":17},{"front":"in a foreign language","meaning":"以外語","examples":[{"en":"Employees need years of training to work effectively in a foreign language.","zh":"員工需要多年培訓才能以外語有效工作。"},{"en":"In a foreign language means using a language that is not one’s native or main language.","zh":"“In a foreign language” 指使用非自己母語或主要語言的語言。"},{"en":"Giving a presentation in a foreign language can feel stressful at first.","zh":"以外語作匯報起初可能令人感到壓力。"},{"en":"If staff must negotiate in a foreign language, they need more than basic vocabulary.","zh":"如果員工必須以外語談判，他們需要的不只是基本詞彙。"},{"en":"The phrase is used for speaking, writing, studying, or working in another language.","zh":"這個短語用於以另一種語言說話、寫作、學習或工作。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":17},{"front":"pursuing this route","meaning":"採取這條路線","examples":[{"en":"Companies pursuing this route need realistic expectations.","zh":"採取這條路線的公司需要現實的期望。"},{"en":"Pursuing this route means choosing and following this method or plan.","zh":"“Pursuing this route” 指選擇並跟隨這種方法或計劃。"},{"en":"Students pursuing this route should expect several years of steady practice.","zh":"採取這條路線的學生應預期數年穩定練習。"},{"en":"If a company pursues the training route, it must provide time, money, and assessment.","zh":"如果公司採取培訓路線，就必須提供時間、金錢和評估。"},{"en":"The phrase describes commitment to a chosen path.","zh":"這個短語描述對所選道路的投入。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":17},{"front":"realistic expectations","meaning":"現實的期望","examples":[{"en":"Companies need realistic expectations about language training.","zh":"公司需要對語言培訓有現實的期望。"},{"en":"Realistic expectations are hopes or plans based on what is actually possible.","zh":"現實的期望是基於實際可能性的希望或計劃。"},{"en":"A beginner needs realistic expectations and should not expect fluency in one week.","zh":"初學者需要現實的期望，不應期待一星期內流利。"},{"en":"If managers have unrealistic expectations, they may cancel training too early.","zh":"如果經理有不現實的期望，他們可能太早取消培訓。"},{"en":"The phrase encourages honest planning rather than wishful thinking.","zh":"這個短語鼓勵誠實規劃，而不是一廂情願。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":17},{"front":"intention to sustain","meaning":"持續推行……的意願","examples":[{"en":"Companies need an intention to sustain the programme for many years.","zh":"公司需要有多年持續推行該計劃的意願。"},{"en":"An intention to sustain something means a serious plan to keep it going over time.","zh":"“An intention to sustain” 某事指有認真計劃讓它長期持續。"},{"en":"A school needs an intention to sustain reading support, not just launch it once.","zh":"學校需要有持續推行閱讀支援的意願，而不是只推出一次。"},{"en":"If there is no intention to sustain training, early investment may be wasted.","zh":"如果沒有持續推行培訓的意願，早期投資可能被浪費。"},{"en":"The phrase stresses long-term commitment from the beginning.","zh":"這個短語強調從一開始就有長期承諾。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":17},{"front":"for many years","meaning":"多年來","examples":[{"en":"A language programme must often be sustained for many years.","zh":"語言計劃通常必須多年來持續推行。"},{"en":"For many years means over a long period lasting several years.","zh":"“For many years” 指持續多年的長時間。"},{"en":"A community garden can serve local families for many years if people maintain it.","zh":"如果人們維護它，社區花園可以多年來服務本地家庭。"},{"en":"If language training continues for many years, learners can reach higher professional levels.","zh":"如果語言培訓持續多年，學習者可以達到更高專業水平。"},{"en":"The phrase stresses long duration.","zh":"這個短語強調時間長。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":18},{"front":"brush-up courses","meaning":"進修課程；重溫課程","examples":[{"en":"Brush-up courses may help people who were previously fluent.","zh":"進修課程可能幫助以前已能流利使用的人。"},{"en":"Brush-up courses are short courses that refresh skills people already learned before.","zh":"進修課程是重溫人們以前已學技能的短期課程。"},{"en":"A former French speaker may take brush-up courses before moving to Paris again.","zh":"以前會說法語的人在再次搬到巴黎前，可能參加進修課程。"},{"en":"Brush-up courses help when knowledge is rusty, but they cannot replace full training for beginners.","zh":"當知識生疏時，進修課程有幫助，但不能取代給初學者的完整培訓。"},{"en":"The phrase focuses on review and reactivation.","zh":"這個短語強調重溫和重新啟動能力。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":18},{"front":"previously fluent","meaning":"以前已能流利使用的","examples":[{"en":"Brush-up courses are useful for people who were previously fluent.","zh":"進修課程對以前已能流利使用的人有用。"},{"en":"Previously fluent means able to use a language smoothly in the past, even if ability has weakened now.","zh":"“Previously fluent” 指過去能流暢使用某語言，即使現在能力已減弱。"},{"en":"Someone who was previously fluent in Japanese may forget words after years without practice.","zh":"以前已能流利使用日語的人，可能多年沒練習後忘記詞語。"},{"en":"If employees were previously fluent, a short course may help them recover confidence.","zh":"如果員工以前已能流利使用，短期課程可能幫助他們恢復信心。"},{"en":"The phrase contrasts past ability with current condition.","zh":"這個短語對比過去能力與現在狀態。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":18},{"front":"quick fix","meaning":"快速解決方法","examples":[{"en":"Language training is not a quick fix.","zh":"語言培訓不是快速解決方法。"},{"en":"A quick fix is a fast solution that may solve a problem only temporarily or superficially.","zh":"快速解決方法是可能只暫時或表面解決問題的快速方案。"},{"en":"Drinking coffee is a quick fix for tiredness, but it does not replace sleep.","zh":"喝咖啡是疲倦的快速解決方法，但不能取代睡眠。"},{"en":"If a company wants real language ability, a weekend course is not a quick fix.","zh":"如果公司想要真正語言能力，週末課程不是快速解決方法。"},{"en":"The phrase warns against expecting instant solutions.","zh":"這個短語提醒人不要期待即時解決方案。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":18},{"front":"must also be considered","meaning":"也必須被考慮","examples":[{"en":"Other methods must also be considered.","zh":"其他方法也必須被考慮。"},{"en":"Must also be considered means should not be ignored when making a decision.","zh":"“Must also be considered” 指作決定時不應被忽視。"},{"en":"When choosing a school, travel time must also be considered.","zh":"選擇學校時，交通時間也必須被考慮。"},{"en":"If training alone is too slow, translation and recruitment must also be considered.","zh":"如果單靠培訓太慢，翻譯和招聘也必須被考慮。"},{"en":"The phrase adds another necessary factor or option.","zh":"這個短語加入另一個必要因素或選項。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":18},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using the words in the box.","zh":"學生使用方框中的詞語完成以下摘要。"},{"en":"Complete the summary below means fill in the missing parts of a short summary under the question.","zh":"“Complete the summary below” 指填寫題目下方短摘要中的缺漏部分。"},{"en":"Students should read the whole sentence before they complete the summary below.","zh":"學生在完成以下摘要前，應閱讀整句。"},{"en":"If the chosen word does not fit the grammar, the summary will be wrong.","zh":"如果所選詞語不符合文法，摘要就會錯。"},{"en":"The phrase is a common instruction in reading tests.","zh":"這個短語是閱讀測驗中的常見指示。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":18},{"front":"encounter language barriers","meaning":"遇到語言障礙","examples":[{"en":"Multinational companies often encounter language barriers.","zh":"跨國公司經常遇到語言障礙。"},{"en":"To encounter language barriers means to face communication problems caused by different languages.","zh":"“Encounter language barriers” 指面對由不同語言造成的溝通問題。"},{"en":"Tourists may encounter language barriers when they cannot read local signs.","zh":"遊客看不懂本地標誌時，可能遇到語言障礙。"},{"en":"If companies encounter language barriers, orders and contracts may be misunderstood.","zh":"如果公司遇到語言障礙，訂單和合約可能被誤解。"},{"en":"The phrase describes meeting a difficulty in real communication.","zh":"這個短語描述在真實溝通中遇到困難。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":18},{"front":"approaches to address","meaning":"應對……的方法","examples":[{"en":"Companies use several approaches to address language barriers.","zh":"公司使用幾種方法應對語言障礙。"},{"en":"Approaches to address a problem are methods used to deal with or reduce it.","zh":"應對問題的方法是用來處理或減少問題的方法。"},{"en":"Schools use different approaches to address bullying, such as counselling and clear rules.","zh":"學校使用不同方法應對欺凌，例如輔導和清晰規則。"},{"en":"If one approach fails to address the problem, another method may be needed.","zh":"如果一種方法未能應對問題，可能需要另一種方法。"},{"en":"The phrase focuses on practical ways to respond to an issue.","zh":"這個短語強調回應問題的實際方式。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":18},{"front":"problems arise when","meaning":"當……時問題出現","examples":[{"en":"Problems arise when companies deal with overseas clients.","zh":"當公司與海外客戶打交道時，問題出現。"},{"en":"Problems arise when something happens means difficulties appear in that situation.","zh":"“Problems arise when” 某事發生指困難在該情況中出現。"},{"en":"Problems arise when students leave homework until the last night.","zh":"當學生把功課拖到最後一晚時，問題會出現。"},{"en":"If problems arise when customers use a website, the design may need improvement.","zh":"如果顧客使用網站時問題出現，設計可能需要改善。"},{"en":"The phrase links a situation with the difficulties it creates.","zh":"這個短語把情況與其造成的困難連繫起來。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":18},{"front":"deal with overseas clients","meaning":"與海外客戶打交道","examples":[{"en":"Companies need language skills when they deal with overseas clients.","zh":"公司與海外客戶打交道時需要語言技能。"},{"en":"To deal with overseas clients means to communicate or do business with customers from other countries.","zh":"“Deal with overseas clients” 指與來自其他國家的客戶溝通或做生意。"},{"en":"A logistics company may deal with overseas clients every day by email and video calls.","zh":"物流公司可能每天透過電郵和視像會議與海外客戶打交道。"},{"en":"If staff deal with overseas clients without language support, misunderstandings may increase.","zh":"如果員工在沒有語言支援下與海外客戶打交道，誤解可能增加。"},{"en":"The phrase is common in international service and sales work.","zh":"這個短語常見於國際服務和銷售工作。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":18},{"front":"overseas clients","meaning":"海外客戶","examples":[{"en":"Overseas clients may expect communication in their own language.","zh":"海外客戶可能期望以自己的語言溝通。"},{"en":"Overseas clients are customers or business partners located in other countries.","zh":"海外客戶是位於其他國家的顧客或商業夥伴。"},{"en":"A design studio may have overseas clients who need meetings at different time zones.","zh":"設計工作室可能有海外客戶，需要在不同時區開會。"},{"en":"If overseas clients receive clear translated documents, they may trust the company more.","zh":"如果海外客戶收到清晰翻譯文件，他們可能更信任公司。"},{"en":"The phrase focuses on clients beyond the home country.","zh":"這個短語強調本國以外的客戶。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":18},{"front":"translating key documents","meaning":"翻譯重要文件","examples":[{"en":"Translating key documents can create differences in interpretation.","zh":"翻譯重要文件可以造成詮釋上的差異。"},{"en":"Translating key documents means converting important written materials into another language.","zh":"翻譯重要文件指把重要書面材料轉換成另一種語言。"},{"en":"A company may need translating key documents before signing a foreign contract.","zh":"公司在簽署外國合約前，可能需要翻譯重要文件。"},{"en":"If key documents are translated poorly, both sides may disagree about their meaning.","zh":"如果重要文件翻譯得差，雙方可能對其意思有分歧。"},{"en":"The phrase is important in legal, business, and official communication.","zh":"這個短語在法律、商業和官方溝通中很重要。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":19},{"front":"key documents","meaning":"重要文件","examples":[{"en":"Contracts and rules are key documents in business negotiations.","zh":"合約和規則是商業談判中的重要文件。"},{"en":"Key documents are the most important written materials needed for a task or decision.","zh":"重要文件是任務或決策所需的最重要書面材料。"},{"en":"A passport and visa are key documents for international travel.","zh":"護照和簽證是國際旅行的重要文件。"},{"en":"If key documents are missing, a business deal may be delayed.","zh":"如果重要文件遺失，商業交易可能延誤。"},{"en":"The phrase helps identify documents that must be read carefully.","zh":"這個短語有助辨認必須仔細閱讀的文件。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":19},{"front":"inevitably creates differences","meaning":"無可避免地造成差異","examples":[{"en":"Translation inevitably creates differences because national rules vary.","zh":"翻譯無可避免地造成差異，因為各國規則有所不同。"},{"en":"Inevitably creates differences means unavoidably produces differences, even when people try to be accurate.","zh":"“Inevitably creates differences” 指即使人們嘗試準確，也無法避免地產生差異。"},{"en":"Translating humour inevitably creates differences because jokes depend on culture.","zh":"翻譯幽默無可避免地造成差異，因為笑話依賴文化。"},{"en":"If legal systems differ, translating legal terms may inevitably create differences.","zh":"如果法律制度不同，翻譯法律術語可能無可避免地造成差異。"},{"en":"The phrase explains that some variation cannot be fully avoided.","zh":"這個短語解釋某些變化不能完全避免。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":19},{"front":"national rules vary","meaning":"各國規則有所不同","examples":[{"en":"National rules vary from country to country.","zh":"各國規則因國而異。"},{"en":"National rules vary means different countries have different laws, regulations, or official practices.","zh":"“National rules vary” 指不同國家有不同法律、規例或官方做法。"},{"en":"National rules vary on driving age, taxes, and employment rights.","zh":"各國規則在駕駛年齡、稅項和僱傭權利方面有所不同。"},{"en":"If national rules vary, companies cannot use the same contract everywhere without checking it.","zh":"如果各國規則有所不同，公司不能不經檢查就在各地使用同一合約。"},{"en":"The phrase explains why international business needs local knowledge.","zh":"這個短語解釋為何國際商業需要本地知識。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":19},{"front":"spoken language and gestures","meaning":"口語和手勢","examples":[{"en":"Some companies rely on spoken language and gestures.","zh":"一些公司依賴口語和手勢。"},{"en":"Spoken language and gestures are speech and body movements used together to communicate.","zh":"口語和手勢是一起用來溝通的說話和身體動作。"},{"en":"A tourist may use spoken language and gestures to buy food in a market.","zh":"遊客可能使用口語和手勢在市場買食物。"},{"en":"Spoken language and gestures can help simple communication, but they may fail with technical details.","zh":"口語和手勢可以幫助簡單溝通，但在技術細節上可能失效。"},{"en":"The phrase combines verbal and physical communication.","zh":"這個短語結合語言和身體溝通。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":19},{"front":"body language","meaning":"身體語言","examples":[{"en":"Body language may help communication when people do not share a language.","zh":"當人們沒有共同語言時，身體語言可能幫助溝通。"},{"en":"Body language means communication through posture, facial expression, hand movement, and eye contact.","zh":"身體語言指透過姿勢、面部表情、手部動作和眼神接觸進行溝通。"},{"en":"A smile is simple body language that can make a customer feel welcome.","zh":"微笑是一種簡單身體語言，可以令顧客感到受歡迎。"},{"en":"If body language conflicts with spoken words, listeners may feel confused.","zh":"如果身體語言與口頭說話衝突，聽者可能感到困惑。"},{"en":"The phrase describes non-verbal communication.","zh":"這個短語描述非語言溝通。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":19},{"front":"more than one-tenth of","meaning":"超過十分之一","examples":[{"en":"More than one-tenth of business transactions use mixed languages.","zh":"超過十分之一的商業交易使用混合語言。"},{"en":"More than one-tenth of something means more than 10% of it.","zh":"“More than one-tenth of” 某事指超過10%。"},{"en":"More than one-tenth of students arrived late after the bus delay.","zh":"巴士延誤後，超過十分之一學生遲到。"},{"en":"If more than one-tenth of orders contain errors, the company should review its process.","zh":"如果超過十分之一訂單有錯，公司應檢討流程。"},{"en":"The phrase gives a proportion slightly above one part in ten.","zh":"這個短語給出略高於十分之一的比例。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":19},{"front":"business transactions","meaning":"商業交易","examples":[{"en":"Business transactions may be affected by language barriers.","zh":"商業交易可能受語言障礙影響。"},{"en":"Business transactions are actions in which goods, services, money, or agreements are exchanged.","zh":"商業交易是商品、服務、金錢或協議被交換的行動。"},{"en":"Buying office furniture is a simple business transaction.","zh":"購買辦公室家具是一項簡單商業交易。"},{"en":"If business transactions cross borders, language and legal details become more important.","zh":"如果商業交易跨越國界，語言和法律細節會變得更重要。"},{"en":"The phrase is common in commerce, accounting, and trade.","zh":"這個短語常見於商業、會計和貿易。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":19},{"front":"a mixture of languages","meaning":"多種語言的混合","examples":[{"en":"Some transactions are conducted using a mixture of languages.","zh":"一些交易使用多種語言的混合進行。"},{"en":"A mixture of languages means two or more languages used together in one conversation or activity.","zh":"多種語言的混合指在一次對話或活動中一起使用兩種或以上語言。"},{"en":"Friends from different countries may use a mixture of languages when chatting.","zh":"來自不同國家的朋友聊天時可能使用多種語言的混合。"},{"en":"A mixture of languages can be friendly in casual talk but risky in contracts.","zh":"多種語言的混合在閒談中可以很友善，但在合約中有風險。"},{"en":"The phrase shows that communication is not happening in one language only.","zh":"這個短語顯示溝通不是只用一種語言。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":19},{"front":"hire translators","meaning":"聘請筆譯員","examples":[{"en":"Companies may hire translators to overcome language barriers.","zh":"公司可能聘請筆譯員來克服語言障礙。"},{"en":"To hire translators means to pay language professionals to translate written material.","zh":"“Hire translators” 指付費聘請語言專業人士翻譯書面材料。"},{"en":"A shop may hire translators to create product pages in Japanese and Spanish.","zh":"商店可能聘請筆譯員製作日文和西班牙文產品頁面。"},{"en":"If companies hire translators too late, important documents may delay the deal.","zh":"如果公司太遲聘請筆譯員，重要文件可能延誤交易。"},{"en":"The phrase focuses on written language support.","zh":"這個短語強調書面語言支援。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":19},{"front":"be costly","meaning":"昂貴的；成本高的","examples":[{"en":"Hiring professional interpreters can be costly.","zh":"聘請專業傳譯員可能成本高昂。"},{"en":"To be costly means to require a lot of money, time, effort, or resources.","zh":"“Be costly” 指需要大量金錢、時間、努力或資源。"},{"en":"Repairing an old lift can be costly for a small building.","zh":"維修舊升降機對小型大廈來說可能很昂貴。"},{"en":"If mistakes in translation lead to legal trouble, the error can be very costly.","zh":"如果翻譯錯誤導致法律麻煩，該錯誤可能代價高昂。"},{"en":"The phrase can refer to financial cost or serious consequences.","zh":"這個短語可以指財務成本或嚴重後果。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":19},{"front":"not well prepared","meaning":"沒有充分準備","examples":[{"en":"If interpreters are not well prepared, they may rely on guesswork.","zh":"如果傳譯員沒有充分準備，他們可能依賴猜測。"},{"en":"Not well prepared means lacking enough information, practice, or planning before a task.","zh":"“Not well prepared” 指任務前缺乏足夠資訊、練習或規劃。"},{"en":"A student who is not well prepared may panic during a presentation.","zh":"沒有充分準備的學生在匯報期間可能慌張。"},{"en":"If an interpreter is not well prepared for technical terms, accuracy may suffer.","zh":"如果傳譯員沒有為專門術語充分準備，準確度可能受影響。"},{"en":"The phrase explains why performance may become weak.","zh":"這個短語解釋表現為何可能變弱。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":20},{"front":"rely on guesswork","meaning":"依賴猜測","examples":[{"en":"Unprepared interpreters may rely on guesswork.","zh":"沒有準備的傳譯員可能依賴猜測。"},{"en":"To rely on guesswork means to depend on guesses instead of clear knowledge or evidence.","zh":"“Rely on guesswork” 指依靠猜想，而不是清晰知識或證據。"},{"en":"A student who has not studied may rely on guesswork in a multiple-choice test.","zh":"沒有溫習的學生可能在選擇題中依賴猜測。"},{"en":"If a doctor relied on guesswork instead of tests, patients would be at risk.","zh":"如果醫生依賴猜測而不是檢查，病人會面臨風險。"},{"en":"The phrase usually warns that the method is unreliable.","zh":"這個短語通常提醒該方法不可靠。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":20},{"front":"answer the questions below","meaning":"回答以下問題","examples":[{"en":"Students answer the questions below using words from the passage.","zh":"學生使用文章中的詞語回答以下問題。"},{"en":"Answer the questions below means respond to the questions written under the instruction.","zh":"“Answer the questions below” 指回答指示下方列出的問題。"},{"en":"In a reading test, students should answer the questions below with information from the text.","zh":"在閱讀測驗中，學生應用文本資料回答以下問題。"},{"en":"If students ignore the word limit, their answers may be marked wrong.","zh":"如果學生忽略字數限制，答案可能被判錯。"},{"en":"The phrase is a standard exam instruction.","zh":"這個短語是標準考試指示。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":20},{"front":"no more than three words and/or a number","meaning":"不超過三個字及／或一個數字","examples":[{"en":"Students should choose no more than three words and/or a number.","zh":"學生應選擇不超過三個字及／或一個數字。"},{"en":"No more than three words and/or a number means the answer must stay within that exact word and number limit.","zh":"“No more than three words and/or a number” 指答案必須符合該準確字數和數字限制。"},{"en":"If the answer is “six language stages”, it uses three words and fits the limit.","zh":"如果答案是 “six language stages”，它用了三個字，符合限制。"},{"en":"Students lose marks if they write four words when only three are allowed.","zh":"如果只允許三個字而學生寫四個字，就會失分。"},{"en":"The phrase tells candidates the maximum answer length.","zh":"這個短語告訴考生答案的最長長度。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":20},{"front":"describe something as","meaning":"把……描述為","examples":[{"en":"The author describes personnel development as an understandable response.","zh":"作者把人員培訓描述為可理解的應對方法。"},{"en":"To describe something as something means to say it has a certain quality or identity.","zh":"“Describe something as” 某物指說它具有某種特質或身份。"},{"en":"A teacher may describe an essay as clear but underdeveloped.","zh":"老師可能把作文描述為清晰但發展不足。"},{"en":"If the writer describes training as understandable, he accepts why companies choose it.","zh":"如果作者把培訓描述為可理解，他就接受公司為何選擇它。"},{"en":"The phrase is useful for reporting someone’s judgement or wording.","zh":"這個短語適合報告某人的判斷或措辭。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":20},{"front":"economic downturn","meaning":"經濟低迷","examples":[{"en":"Training is often cut during an economic downturn.","zh":"在經濟低迷期間，培訓常被削減。"},{"en":"An economic downturn is a period when business activity, income, or employment becomes weaker.","zh":"經濟低迷是商業活動、收入或就業變弱的時期。"},{"en":"During an economic downturn, families may spend less on restaurants and holidays.","zh":"在經濟低迷期間，家庭可能減少餐廳和旅行開支。"},{"en":"If an economic downturn reduces profits, companies may cut training and hiring.","zh":"如果經濟低迷減少利潤，公司可能削減培訓和招聘。"},{"en":"The phrase describes a difficult period in the economy.","zh":"這個短語描述經濟中的困難時期。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":20},{"front":"what term does the writer use","meaning":"作者使用甚麼詞語","examples":[{"en":"The question asks what term the writer uses for training cuts.","zh":"題目問作者使用甚麼詞語形容培訓削減。"},{"en":"What term does the writer use asks for the exact word or phrase chosen by the author.","zh":"“What term does the writer use” 要求找出作者選用的準確詞語或短語。"},{"en":"In reading exams, this question type requires students to locate the writer’s wording, not invent their own.","zh":"在閱讀考試中，這類題目要求學生定位作者措辭，而不是自創答案。"},{"en":"If students paraphrase instead of giving the term, they may lose marks.","zh":"如果學生改寫而不是給出該詞語，可能會失分。"},{"en":"The phrase is common in short-answer reading questions.","zh":"這個短語常見於短答閱讀題。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":20},{"front":"provide a model","meaning":"提供典範","examples":[{"en":"The Volkswagen Group provides a model of language management.","zh":"大眾汽車集團提供語言管理的典範。"},{"en":"To provide a model means to offer a good example that others can follow or learn from.","zh":"“Provide a model” 指提供其他人可以仿效或學習的良好例子。"},{"en":"A successful recycling programme can provide a model for other districts.","zh":"成功的回收計劃可以為其他地區提供典範。"},{"en":"If one company provides a model, others may adapt its methods to their own needs.","zh":"如果一家公司提供典範，其他公司可能把其方法調整至自身需要。"},{"en":"The phrase highlights an example with practical value.","zh":"這個短語強調具有實用價值的例子。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":20},{"front":"regard language training as","meaning":"把語言培訓視為","examples":[{"en":"Volkswagen regards language training as a strategic solution.","zh":"大眾汽車把語言培訓視為戰略性方案。"},{"en":"To regard language training as something means to see or treat it in that way.","zh":"“Regard language training as” 某事指以那種方式看待或處理語言培訓。"},{"en":"A school may regard reading practice as a daily habit, not a punishment.","zh":"學校可能把閱讀練習視為日常習慣，而不是懲罰。"},{"en":"If managers regard language training as strategic, they are more likely to fund it long term.","zh":"如果管理層把語言培訓視為戰略性，他們更可能長期提供資金。"},{"en":"The phrase reports how someone views an activity.","zh":"這個短語報告某人如何看待一項活動。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":20},{"front":"basic to advanced level","meaning":"由基礎至高級水平","examples":[{"en":"The system helps staff progress from a basic to an advanced level.","zh":"該制度幫助員工由基礎至高級水平進步。"},{"en":"Basic to advanced level means from beginner-level knowledge to high-level ability.","zh":"“Basic to advanced level” 指由初學知識到高階能力。"},{"en":"A cooking course may take students from basic to advanced level over several months.","zh":"烹飪課程可能在數月內帶學生由基礎至高級水平。"},{"en":"If language training moves staff from basic to advanced level, it needs clear stages.","zh":"如果語言培訓令員工由基礎至高級水平進步，它需要清晰階段。"},{"en":"The phrase describes gradual improvement across levels.","zh":"這個短語描述跨級別的逐步改善。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":20},{"front":"approximately how many hours","meaning":"大約多少小時","examples":[{"en":"The question asks approximately how many hours each stage requires.","zh":"題目問每個階段大約需要多少小時。"},{"en":"Approximately how many hours asks for an estimated number of hours, not necessarily an exact figure.","zh":"“Approximately how many hours” 詢問估算的小時數，不一定是精確數字。"},{"en":"A student may ask approximately how many hours are needed to finish the project.","zh":"學生可能問完成項目大約需要多少小時。"},{"en":"If a course requires approximately 90 hours, learners can plan their schedule better.","zh":"如果課程需要大約90小時，學習者可以更好規劃時間表。"},{"en":"The phrase is used when the answer is a rough time amount.","zh":"這個短語用於答案是大約時間數量時。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":20},{"front":"minimum time","meaning":"最短時間","examples":[{"en":"The question asks for the minimum time needed to become proficient.","zh":"題目問達到熟練所需的最短時間。"},{"en":"Minimum time means the shortest amount of time required.","zh":"最短時間指所需的最少時間量。"},{"en":"The minimum time for boiling an egg depends on how firm you want it.","zh":"煮蛋的最短時間取決於你想要多熟。"},{"en":"If the minimum time for fluency is three years, a one-month course cannot promise mastery.","zh":"如果流利所需最短時間是三年，一個月課程就不能承諾精通。"},{"en":"The phrase sets the lowest time requirement.","zh":"這個短語設定最低時間要求。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":21},{"front":"become proficient in","meaning":"熟練掌握","examples":[{"en":"Professionals need years of study to become proficient in a foreign language.","zh":"專業人士需要多年學習才能熟練掌握一種外語。"},{"en":"To become proficient in something means to become skilled and able to use it well.","zh":"“Become proficient in” 某事指變得熟練，並能好好使用它。"},{"en":"A student may need years to become proficient in academic writing.","zh":"學生可能需要多年才能熟練掌握學術寫作。"},{"en":"If employees become proficient in a client’s language, negotiations become smoother.","zh":"如果員工熟練掌握客戶的語言，談判會更順暢。"},{"en":"The phrase suggests strong practical ability, not just basic knowledge.","zh":"這個短語暗示強大的實際能力，而不只是基本知識。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":21},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter for the main-purpose question.","zh":"學生為文章主要目的題選出正確字母。"},{"en":"Choose the correct letter means select the answer option marked by the right letter.","zh":"“Choose the correct letter” 指選出由正確字母標示的答案選項。"},{"en":"In multiple-choice questions, students must choose the correct letter, not copy the whole sentence.","zh":"在選擇題中，學生必須選出正確字母，而不是抄整句。"},{"en":"If students choose the correct letter without understanding why, they may repeat mistakes later.","zh":"如果學生沒有理解原因就選出正確字母，之後可能重複錯誤。"},{"en":"The phrase is a common instruction in exam questions.","zh":"這個短語是考試題中的常見指示。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":21},{"front":"main purpose of the passage","meaning":"文章的主要目的","examples":[{"en":"The main purpose of the passage is to evaluate language-management options.","zh":"文章的主要目的是評估語言管理選項。"},{"en":"The main purpose of the passage is the writer’s central reason for writing it.","zh":"文章的主要目的是作者寫作的核心原因。"},{"en":"In a reading test, students should identify the main purpose before focusing on small details.","zh":"在閱讀測驗中，學生應先識別文章的主要目的，再集中細節。"},{"en":"If students confuse examples with the main purpose, they may choose the wrong answer.","zh":"如果學生把例子與文章主要目的混淆，可能選錯答案。"},{"en":"The phrase asks what the whole text is mainly trying to do.","zh":"這個短語詢問整篇文章主要想做甚麼。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":21},{"front":"identify every type of","meaning":"識別每一類……","examples":[{"en":"The option asks whether the passage identifies every type of language problem.","zh":"該選項問文章是否識別每一類語言問題。"},{"en":"To identify every type of something means to name or recognise all categories of it.","zh":"“Identify every type of” 某事指命名或辨認其所有類別。"},{"en":"A teacher cannot identify every type of grammar mistake in one short lesson.","zh":"老師不能在一堂短課中識別每一類文法錯誤。"},{"en":"If a report claims to identify every type of risk, readers should check whether it is complete.","zh":"如果報告聲稱識別每一類風險，讀者應檢查它是否完整。"},{"en":"The phrase suggests full classification, not just giving examples.","zh":"這個短語暗示完整分類，而不只是給例子。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":21},{"front":"language problem","meaning":"語言問題","examples":[{"en":"A multinational company may encounter many kinds of language problems.","zh":"跨國公司可能遇到許多種類的語言問題。"},{"en":"A language problem is a difficulty caused by speaking, writing, translating, or understanding a language.","zh":"語言問題是由說、寫、翻譯或理解語言造成的困難。"},{"en":"A customer service team faces a language problem when callers cannot explain their issue clearly.","zh":"當來電者不能清楚解釋問題時，顧客服務團隊便面對語言問題。"},{"en":"Language problems can lead to delays, confusion, and damaged relationships.","zh":"語言問題可以導致延誤、混亂和關係受損。"},{"en":"The phrase covers both simple misunderstandings and complex translation issues.","zh":"這個短語涵蓋簡單誤解和複雜翻譯問題。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":21},{"front":"well-known cases involving","meaning":"涉及……的著名個案","examples":[{"en":"The option refers to well-known cases involving language difficulties.","zh":"該選項提到涉及語言困難的著名個案。"},{"en":"Well-known cases involving something are famous examples connected with that issue.","zh":"涉及某事的著名個案是與該問題有關的知名例子。"},{"en":"A history lesson may discuss well-known cases involving failed communication between leaders.","zh":"歷史課可能討論涉及領袖溝通失敗的著名個案。"},{"en":"If an essay gives well-known cases involving language mistakes, readers may understand the risk more easily.","zh":"如果作文提供涉及語言錯誤的著名個案，讀者可能更容易理解風險。"},{"en":"The phrase points to recognised examples, not private incidents.","zh":"這個短語指公認例子，而不是私人事件。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":21},{"front":"language difficulties","meaning":"語言困難","examples":[{"en":"The passage discusses several language difficulties in business.","zh":"文章討論商業中的幾種語言困難。"},{"en":"Language difficulties are problems people face when using or understanding a language.","zh":"語言困難是人們使用或理解語言時面對的問題。"},{"en":"New immigrants may face language difficulties when visiting a government office.","zh":"新移民到政府辦公室時可能面對語言困難。"},{"en":"If language difficulties are ignored, people may avoid asking for help.","zh":"如果語言困難被忽視，人們可能避免求助。"},{"en":"The phrase is broader than “grammar mistakes” because it includes communication and understanding.","zh":"這個短語比「文法錯誤」更廣，因為它包括溝通和理解。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":21},{"front":"evaluate various ways","meaning":"評估各種方法","examples":[{"en":"The passage evaluates various ways to overcome language barriers.","zh":"文章評估克服語言障礙的各種方法。"},{"en":"To evaluate various ways means to judge several different methods and consider their strengths and weaknesses.","zh":"“Evaluate various ways” 指判斷幾種不同方法，並考慮其優點和缺點。"},{"en":"A school may evaluate various ways to reduce homework stress.","zh":"學校可能評估各種方法來減少功課壓力。"},{"en":"If a company evaluates various ways carefully, it is less likely to choose a weak solution.","zh":"如果公司仔細評估各種方法，就較不可能選擇薄弱方案。"},{"en":"The phrase shows comparison, not just description.","zh":"這個短語顯示比較，而不只是描述。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":21},{"front":"overcome language barriers","meaning":"克服語言障礙","examples":[{"en":"Companies need strategies to overcome language barriers.","zh":"公司需要策略來克服語言障礙。"},{"en":"To overcome language barriers means to reduce or solve communication problems caused by different languages.","zh":"“Overcome language barriers” 指減少或解決由不同語言造成的溝通問題。"},{"en":"Hospitals may overcome language barriers by using interpreters and translated forms.","zh":"醫院可能透過使用傳譯員和翻譯表格來克服語言障礙。"},{"en":"If a business overcomes language barriers, overseas customers may feel more confident.","zh":"如果企業克服語言障礙，海外顧客可能更有信心。"},{"en":"The phrase focuses on solving multilingual communication problems.","zh":"這個短語強調解決多語溝通問題。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":21},{"front":"demonstrate that","meaning":"證明","examples":[{"en":"The option asks whether the passage demonstrates that training is the only solution.","zh":"該選項問文章是否證明培訓是唯一解決方案。"},{"en":"To demonstrate that something is true means to show it clearly with evidence or explanation.","zh":"“Demonstrate that” 某事為真指用證據或解釋清楚顯示它。"},{"en":"A teacher may demonstrate that planning improves writing by comparing two essays.","zh":"老師可能透過比較兩篇作文，證明規劃能改善寫作。"},{"en":"If data demonstrate that customers prefer local languages, companies should adjust their service.","zh":"如果數據證明顧客較喜歡本地語言，公司應調整服務。"},{"en":"The phrase is formal and stronger than simply “say”.","zh":"這個短語較正式，比單純說 “say” 更強。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":21},{"front":"only feasible way","meaning":"唯一可行的方法","examples":[{"en":"Training is not the only feasible way to solve language problems.","zh":"培訓不是解決語言問題的唯一可行方法。"},{"en":"The only feasible way means the single practical method that can realistically work.","zh":"“The only feasible way” 指唯一實際可行、現實中能運作的方法。"},{"en":"Online lessons are not the only feasible way to learn English; conversation practice also helps.","zh":"網課不是學英文的唯一可行方法；對話練習也有幫助。"},{"en":"If hiring translators is expensive, training may be feasible, but it is not always the only feasible way.","zh":"如果聘請筆譯員很昂貴，培訓可能可行，但不一定是唯一可行方法。"},{"en":"The phrase is useful when discussing whether alternatives exist.","zh":"這個短語適合討論是否存在其他選擇。"}],"source":"141 - Language Strategy in Multinational Company.pdf","sourcePage":22}],"ielts/reading/passage-2/Practice 142":[{"front":"Global Warming","meaning":"全球暖化","examples":[{"en":"The passage discusses possible ways to limit global warming.","zh":"文章討論了限制全球暖化的可能方法。"},{"en":"Global warming is the long-term rise in Earth’s average temperature.","zh":"全球暖化是地球平均氣溫長期上升。"},{"en":"People notice global warming when summers become hotter and heatwaves last longer.","zh":"當夏天變得更熱、熱浪持續更久時，人們會注意到全球暖化。"},{"en":"Global warming can cause sea levels to rise because ice melts and oceans expand.","zh":"全球暖化可以導致海平面上升，因為冰融化，海洋也會膨脹。"},{"en":"Reducing pollution can help slow global warming, but it requires action from many countries.","zh":"減少污染可以幫助減慢全球暖化，但需要許多國家採取行動。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":1},{"front":"prevent the poles from melting","meaning":"防止兩極融化","examples":[{"en":"Some geoengineering schemes aim to prevent the poles from melting.","zh":"一些地球工程方案旨在防止兩極融化。"},{"en":"To prevent the poles from melting means to stop ice in the Arctic and Antarctic from disappearing.","zh":"prevent the poles from melting 指阻止北極和南極的冰消失。"},{"en":"Scientists may study reflective surfaces to prevent the poles from melting too quickly.","zh":"科學家可能研究反光表面，以防止兩極太快融化。"},{"en":"If we fail to prevent the poles from melting, sea levels may rise and coastal cities may suffer.","zh":"如果我們未能防止兩極融化，海平面可能上升，沿海城市可能受害。"},{"en":"This phrase focuses on protecting polar ice, not simply cooling one local area.","zh":"這個片語聚焦於保護極地冰層，而不只是令某個本地地區降溫。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":1},{"front":"such is our dependence on","meaning":"我們對……的依賴如此之大","examples":[{"en":"Such is our dependence on fossil fuels that significant warming now seems inevitable.","zh":"我們對化石燃料的依賴如此之大，以致顯著暖化現在似乎無可避免。"},{"en":"Such is our dependence on something means we rely on it so heavily that serious results follow.","zh":"such is our dependence on something 指我們如此嚴重依賴某物，以致產生嚴重結果。"},{"en":"Such is our dependence on smartphones that many people feel lost without them.","zh":"我們對智能電話的依賴如此之大，以致許多人沒有手機便感到迷失。"},{"en":"Such is our dependence on imported food that supply delays can quickly raise prices.","zh":"我們對進口食物的依賴如此之大，以致供應延誤可以很快推高價格。"},{"en":"This structure is formal and emphasises how great the dependence is.","zh":"這個結構較正式，強調依賴程度很大。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":1},{"front":"fossil fuels","meaning":"化石燃料","examples":[{"en":"Modern society depends heavily on fossil fuels.","zh":"現代社會嚴重依賴化石燃料。"},{"en":"Fossil fuels are fuels such as coal, oil, and natural gas formed from ancient living matter.","zh":"化石燃料是煤、石油和天然氣等由古代生物物質形成的燃料。"},{"en":"Cars, planes, factories, and power stations often use fossil fuels for energy.","zh":"汽車、飛機、工廠和發電廠常使用化石燃料作能源。"},{"en":"Burning fossil fuels releases gases that contribute to climate change.","zh":"燃燒化石燃料會釋放導致氣候變化的氣體。"},{"en":"Moving away from fossil fuels usually requires cleaner energy sources such as wind or solar power.","zh":"擺脫化石燃料通常需要風能或太陽能等較潔淨能源。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":1},{"front":"such is the volume of","meaning":"……的數量如此之大","examples":[{"en":"Such is the volume of carbon dioxide already released that warming is difficult to avoid.","zh":"已釋放的二氧化碳數量如此之大，以致暖化難以避免。"},{"en":"Such is the volume of something means the amount is so large that it creates a strong effect.","zh":"such is the volume of something 指某物數量如此之大，以致造成強烈影響。"},{"en":"Such is the volume of homework that students cannot finish it without planning carefully.","zh":"功課數量如此之大，以致學生若不仔細計劃便無法完成。"},{"en":"Such is the volume of traffic that buses are delayed every morning.","zh":"交通流量如此之大，以致巴士每天早上都延誤。"},{"en":"This phrase stresses that the quantity itself has become a problem.","zh":"這個片語強調數量本身已成為問題。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":1},{"front":"carbon dioxide","meaning":"二氧化碳","examples":[{"en":"Carbon dioxide released into the atmosphere contributes to global warming.","zh":"釋放到大氣中的二氧化碳會導致全球暖化。"},{"en":"Carbon dioxide is a gas produced when people breathe and when fuels such as coal, oil, or gas are burned.","zh":"二氧化碳是一種氣體，人呼吸時會產生，煤、石油或天然氣等燃料燃燒時也會產生。"},{"en":"Factories and cars release carbon dioxide when they use fossil fuels.","zh":"工廠和汽車使用化石燃料時會釋放二氧化碳。"},{"en":"Too much carbon dioxide in the atmosphere traps heat and warms the planet.","zh":"大氣中過多二氧化碳會困住熱力，使地球變暖。"},{"en":"Cutting carbon dioxide emissions is one way to slow climate change.","zh":"削減二氧化碳排放是減慢氣候變化的方法之一。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":1},{"front":"release into the atmosphere","meaning":"釋放到大氣中","examples":[{"en":"Humans have released large amounts of carbon dioxide into the atmosphere.","zh":"人類已把大量二氧化碳釋放到大氣中。"},{"en":"To release something into the atmosphere means to send a gas or substance into the air around Earth.","zh":"release something into the atmosphere 指把氣體或物質排放到地球周圍的空氣中。"},{"en":"A factory may release smoke into the atmosphere if its filters are poor.","zh":"如果過濾系統差，工廠可能把煙釋放到大氣中。"},{"en":"When cars burn petrol, they release gases into the atmosphere.","zh":"汽車燃燒汽油時，會把氣體釋放到大氣中。"},{"en":"Substances released into the atmosphere can spread far beyond the place where they began.","zh":"釋放到大氣中的物質可以擴散到遠離源頭的地方。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":1},{"front":"climate scientists","meaning":"氣候科學家","examples":[{"en":"Most climate scientists agree that significant global warming is now inevitable.","zh":"大多數氣候科學家同意顯著全球暖化現在已無可避免。"},{"en":"Climate scientists are researchers who study Earth’s climate, weather patterns, and long-term environmental change.","zh":"氣候科學家是研究地球氣候、天氣模式和長期環境變化的研究人員。"},{"en":"Climate scientists use data from ice, oceans, satellites, and temperature records.","zh":"氣候科學家使用來自冰層、海洋、衛星和氣溫紀錄的數據。"},{"en":"When climate scientists warn about rising temperatures, governments may need to prepare stronger policies.","zh":"當氣候科學家警告氣溫上升時，政府可能需要準備更強政策。"},{"en":"Their work helps people understand how human activity affects the planet.","zh":"他們的工作幫助人們理解人類活動如何影響地球。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":1},{"front":"significant global warming","meaning":"顯著的全球暖化","examples":[{"en":"Significant global warming is now considered inevitable by many scientists.","zh":"許多科學家現在認為顯著的全球暖化已無可避免。"},{"en":"Significant global warming means a serious and noticeable rise in Earth’s average temperature.","zh":"significant global warming 指地球平均氣溫嚴重而明顯上升。"},{"en":"Farmers may notice significant global warming when growing seasons change.","zh":"當生長季節改變，農民可能注意到顯著的全球暖化。"},{"en":"Significant global warming can increase droughts, heatwaves, and pressure on water supplies.","zh":"顯著的全球暖化可以增加乾旱、熱浪和供水壓力。"},{"en":"This phrase is stronger than a small or temporary change in weather.","zh":"這個片語比小型或暫時的天氣變化更強。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":1},{"front":"be now inevitable","meaning":"現在已無可避免","examples":[{"en":"Some level of global warming is now inevitable.","zh":"某種程度的全球暖化現在已無可避免。"},{"en":"If something is now inevitable, it can no longer be avoided under present conditions.","zh":"如果某事 is now inevitable，意思是在目前情況下已不能避免。"},{"en":"After weeks without rain, some water restrictions are now inevitable.","zh":"經過數星期無雨後，某些限水措施現在已無可避免。"},{"en":"If a student never studies before the exam, a poor result may be now inevitable.","zh":"如果學生考試前從不溫習，差劣成績可能現在已無可避免。"},{"en":"This phrase often sounds serious because it suggests the chance to prevent something has passed.","zh":"這個片語通常語氣嚴重，因為它暗示防止某事的機會已經過去。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":1},{"front":"the best we can hope to do","meaning":"我們最多只能希望做到的是","examples":[{"en":"The best we can hope to do is keep warming at a reasonable level.","zh":"我們最多只能希望做到的是把暖化維持在合理水平。"},{"en":"The best we can hope to do means the most realistic goal left in a difficult situation.","zh":"the best we can hope to do 指在困難情況下剩下的最現實目標。"},{"en":"If the train is already late, the best we can hope to do is arrive before the meeting starts.","zh":"如果火車已經遲到，我們最多只能希望做到的是在會議開始前到達。"},{"en":"During a serious illness, the best doctors can hope to do may be to reduce pain and slow the disease.","zh":"在嚴重疾病中，醫生最多只能希望做到的可能是減輕痛楚和減慢病情。"},{"en":"This phrase suggests limited options, not complete success.","zh":"這個片語暗示選項有限，而不是完全成功。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":1},{"front":"keep something at a reasonable level","meaning":"把……維持在合理水平","examples":[{"en":"The goal is to keep global warming at a reasonable level.","zh":"目標是把全球暖化維持在合理水平。"},{"en":"To keep something at a reasonable level means to control it so it does not become too high or dangerous.","zh":"keep something at a reasonable level 指控制某事，使它不會變得太高或危險。"},{"en":"A family tries to keep spending at a reasonable level by planning a monthly budget.","zh":"家庭透過制定每月預算，嘗試把開支維持在合理水平。"},{"en":"Schools keep noise at a reasonable level so students can study.","zh":"學校把噪音維持在合理水平，讓學生能學習。"},{"en":"This phrase suggests management and control rather than complete removal.","zh":"這個片語暗示管理和控制，而不是完全消除。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":2},{"front":"an uphill task","meaning":"艱巨任務","examples":[{"en":"Reducing global warming will be an uphill task.","zh":"減少全球暖化將是一項艱巨任務。"},{"en":"An uphill task is a very difficult job that requires great effort.","zh":"an uphill task 是非常困難、需要巨大努力的工作。"},{"en":"Learning a new language in three months is an uphill task for most beginners.","zh":"對大多數初學者來說，三個月內學會新語言是一項艱巨任務。"},{"en":"Repairing a company’s reputation after a scandal can be an uphill task.","zh":"醜聞後修復公司聲譽可能是一項艱巨任務。"},{"en":"This phrase suggests a struggle, like walking up a steep hill.","zh":"這個片語暗示像走上陡斜山坡一樣困難。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":2},{"front":"at present","meaning":"目前","examples":[{"en":"At present, cutting carbon emissions is the only serious option.","zh":"目前，削減碳排放是唯一認真的可行選項。"},{"en":"At present means at this time or under current conditions.","zh":"at present 指在此刻或目前情況下。"},{"en":"At present, the library is closed for repairs.","zh":"目前，圖書館因維修而關閉。"},{"en":"A student may be weak in grammar at present but improve with regular practice.","zh":"學生目前可能文法薄弱，但可透過定期練習進步。"},{"en":"This phrase focuses on the current situation, not the past or future.","zh":"這個片語聚焦於當前情況，而不是過去或未來。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":2},{"front":"the only serious option on the table","meaning":"目前唯一認真的可行選項","examples":[{"en":"The only serious option on the table is to reduce emissions.","zh":"目前唯一認真的可行選項是減少排放。"},{"en":"The only serious option on the table means the only practical choice currently being considered.","zh":"the only serious option on the table 指目前正在考慮的唯一實際選擇。"},{"en":"If the school roof is leaking badly, repairs may be the only serious option on the table.","zh":"如果學校屋頂嚴重漏水，維修可能是目前唯一認真的可行選項。"},{"en":"When a business is losing money every month, cost control may become the only serious option on the table.","zh":"當企業每月虧損，控制成本可能成為目前唯一認真的可行選項。"},{"en":"This phrase suggests that other ideas are not realistic enough right now.","zh":"這個片語暗示其他想法目前不夠現實。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":2},{"front":"cut back","meaning":"削減；減少","examples":[{"en":"Countries need to cut back their carbon emissions.","zh":"各國需要削減碳排放。"},{"en":"To cut back means to reduce the amount of something.","zh":"cut back 指減少某物的數量。"},{"en":"A family may cut back on eating out to save money.","zh":"家庭可能減少外出用餐來省錢。"},{"en":"If a company cuts back too quickly, workers may lose jobs.","zh":"如果公司削減得太快，員工可能失業。"},{"en":"This phrase is common when discussing spending, consumption, pollution, or habits.","zh":"這個片語常用於討論開支、消耗、污染或習慣。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":2},{"front":"carbon emissions","meaning":"碳排放","examples":[{"en":"Many governments are trying to reduce carbon emissions.","zh":"許多政府正嘗試減少碳排放。"},{"en":"Carbon emissions are releases of carbon-based gases, especially carbon dioxide, into the air.","zh":"carbon emissions 是含碳氣體，尤其是二氧化碳，排放到空氣中。"},{"en":"Driving petrol cars and burning coal for electricity create carbon emissions.","zh":"駕駛汽油車和燃煤發電會產生碳排放。"},{"en":"High carbon emissions can make climate change worse.","zh":"高碳排放可以令氣候變化惡化。"},{"en":"Businesses can reduce carbon emissions by using cleaner energy and wasting less fuel.","zh":"企業可以透過使用較潔淨能源和減少浪費燃料來減少碳排放。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":2},{"front":"make major strides","meaning":"取得重大進展","examples":[{"en":"A few countries are making major strides in reducing emissions.","zh":"少數國家在減少排放方面正取得重大進展。"},{"en":"To make major strides means to make important and noticeable progress.","zh":"make major strides 指取得重要而明顯的進步。"},{"en":"A student can make major strides in speaking English by practising daily with feedback.","zh":"學生透過每日練習並獲得回饋，可以在英語口語上取得重大進展。"},{"en":"Hospitals may make major strides in patient care after introducing better training.","zh":"醫院引入更好培訓後，可能在病人護理方面取得重大進展。"},{"en":"This phrase suggests strong improvement, not just a small change.","zh":"這個片語暗示強大改善，而不只是小變化。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":2},{"front":"have great difficulty doing something","meaning":"在做某事方面有很大困難","examples":[{"en":"Many countries have great difficulty stemming the increase in emissions.","zh":"許多國家在遏止排放增加方面有很大困難。"},{"en":"To have great difficulty doing something means to find it very hard to do.","zh":"have great difficulty doing something 指覺得做某事非常困難。"},{"en":"Beginners may have great difficulty understanding fast natural English.","zh":"初學者可能在理解快速自然英語方面有很大困難。"},{"en":"A small shop may have great difficulty paying rent when customer numbers fall.","zh":"當顧客數量下降，小店可能在支付租金方面有很大困難。"},{"en":"This phrase shows that effort is being made, but success is hard.","zh":"這個片語顯示有人正在努力，但成功很困難。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":2},{"front":"stem the rate of increase","meaning":"遏止增長速度","examples":[{"en":"Most countries struggle to stem the rate of increase in carbon emissions.","zh":"大多數國家難以遏止碳排放的增長速度。"},{"en":"To stem the rate of increase means to slow or stop how quickly something is rising.","zh":"stem the rate of increase 指減慢或阻止某事上升的速度。"},{"en":"A school may try to stem the rate of increase in student absences by contacting parents early.","zh":"學校可能透過及早聯絡家長，嘗試遏止學生缺席的增長速度。"},{"en":"Higher interest rates can stem the rate of increase in borrowing.","zh":"較高利率可以遏止借貸的增長速度。"},{"en":"This phrase does not always mean reducing the total amount; it may only mean slowing growth.","zh":"這個片語不一定指減少總量；它可能只是指減慢增長。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":2},{"front":"let alone","meaning":"更不用說","examples":[{"en":"Many countries cannot stem emissions growth, let alone reverse it.","zh":"許多國家不能遏止排放增長，更不用說逆轉它。"},{"en":"Let alone introduces something even more difficult, unlikely, or extreme than what was just mentioned.","zh":"let alone 用來引入比剛提及的事情更困難、更不可能或更極端的事。"},{"en":"The child cannot read a short story yet, let alone write an essay.","zh":"這個孩子還不能讀短故事，更不用說寫文章。"},{"en":"A small shop cannot afford new furniture, let alone a full renovation.","zh":"小店連新家具也負擔不起，更不用說全面裝修。"},{"en":"This phrase creates a strong contrast between a hard task and an even harder one.","zh":"這個片語在一件困難事情和更困難事情之間製造強烈對比。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":2},{"front":"reverse it","meaning":"逆轉它","examples":[{"en":"Countries find it difficult to reverse the rise in emissions.","zh":"各國發現很難逆轉排放上升。"},{"en":"To reverse it means to change a trend or process so it moves in the opposite direction.","zh":"reverse it 指改變某個趨勢或過程，使它朝相反方向發展。"},{"en":"If a student’s grades are falling, regular revision may help reverse it.","zh":"如果學生分數下降，定期溫習可能幫助逆轉它。"},{"en":"A city may try to reverse traffic congestion by improving public transport.","zh":"城市可能透過改善公共交通嘗試逆轉交通擠塞。"},{"en":"This phrase is stronger than slowing a problem because it means turning it around.","zh":"這個片語比減慢問題更強，因為它指把情況扭轉。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":2},{"front":"consequently","meaning":"因此","examples":[{"en":"Consequently, more scientists are exploring alternatives.","zh":"因此，更多科學家正在探索替代方案。"},{"en":"Consequently means as a result or therefore.","zh":"consequently 指結果是、因此。"},{"en":"The road was closed; consequently, many workers arrived late.","zh":"道路封閉；因此，許多工人遲到。"},{"en":"The school added more classes; consequently, students had more choices.","zh":"學校增加更多課堂；因此，學生有更多選擇。"},{"en":"This word connects a cause with its result in a formal way.","zh":"這個詞以較正式方式連接原因和結果。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":3},{"front":"explore alternatives","meaning":"探索替代方案","examples":[{"en":"Scientists are exploring alternatives to simply cutting emissions.","zh":"科學家正在探索除了單純削減排放以外的替代方案。"},{"en":"To explore alternatives means to study other possible choices or solutions.","zh":"explore alternatives 指研究其他可能選擇或解決方法。"},{"en":"If medicine does not work, a doctor may explore alternatives with the patient.","zh":"如果藥物無效，醫生可能與病人探索替代方案。"},{"en":"A business may explore alternatives when its usual supplier becomes too expensive.","zh":"當平常供應商變得太貴，企業可能探索替代方案。"},{"en":"This phrase suggests careful investigation before making a decision.","zh":"這個片語暗示在作決定前仔細研究。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":3},{"front":"fall under the banner of","meaning":"歸入……名下；屬於……範疇","examples":[{"en":"These ideas fall under the banner of geoengineering.","zh":"這些想法屬於地球工程的範疇。"},{"en":"To fall under the banner of something means to belong to a larger category or movement.","zh":"fall under the banner of something 指屬於一個較大的類別或運動。"},{"en":"Recycling, composting, and reducing waste all fall under the banner of environmental protection.","zh":"回收、堆肥和減少廢物都屬於環境保護的範疇。"},{"en":"Yoga, running, and balanced eating can fall under the banner of healthy living.","zh":"瑜伽、跑步和平衡飲食可以歸入健康生活名下。"},{"en":"This phrase groups different ideas under one broad name.","zh":"這個片語把不同想法歸在一個廣泛名稱之下。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":3},{"front":"geoengineering","meaning":"地球工程","examples":[{"en":"Geoengineering involves large-scale manipulation of the environment.","zh":"地球工程涉及對環境的大規模操控。"},{"en":"Geoengineering means using large technological methods to deliberately change Earth’s climate or environment.","zh":"geoengineering 指使用大型技術方法，有意改變地球氣候或環境。"},{"en":"Spraying particles into the sky to reflect sunlight would be a form of geoengineering.","zh":"把粒子噴入天空以反射陽光會是一種地球工程。"},{"en":"Geoengineering may reduce warming, but it could also create unexpected side effects.","zh":"地球工程可能減少暖化，但也可能造成意想不到的副作用。"},{"en":"This word is often used when ordinary climate policies seem too slow or uncertain.","zh":"當普通氣候政策似乎太慢或不確定時，常會使用這個詞。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":3},{"front":"be generally defined as","meaning":"一般被定義為","examples":[{"en":"Geoengineering is generally defined as intentional environmental manipulation.","zh":"地球工程一般被定義為有意識的環境操控。"},{"en":"Be generally defined as means most people or experts describe something in this way.","zh":"be generally defined as 指大多數人或專家以這種方式描述某事。"},{"en":"Bullying is generally defined as repeated behaviour intended to hurt or control another person.","zh":"欺凌一般被定義為有意傷害或控制他人的重複行為。"},{"en":"A care home is generally defined as a place where people live and receive support.","zh":"護理院一般被定義為人們居住並接受支援的地方。"},{"en":"This phrase gives a common definition, not necessarily every possible meaning.","zh":"這個片語給出常見定義，而不一定包括所有可能意思。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":3},{"front":"intentional manipulation","meaning":"有意識的操控","examples":[{"en":"Geoengineering involves intentional manipulation of the environment.","zh":"地球工程涉及對環境的有意識操控。"},{"en":"Intentional manipulation means deliberate control or change of something for a chosen purpose.","zh":"intentional manipulation 指為了特定目的而有意控制或改變某事。"},{"en":"A teacher’s seating plan may involve intentional manipulation of the classroom to reduce noise.","zh":"老師安排座位可能涉及對課室的有意識操控，以減少噪音。"},{"en":"Intentional manipulation of data is dishonest if it hides the truth.","zh":"如果有意操控數據是為了隱藏真相，便是不誠實。"},{"en":"This phrase can be neutral or negative depending on the context.","zh":"這個片語可以是中性或負面，視乎語境。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":3},{"front":"large-scale manipulation of","meaning":"對……的大規模操控","examples":[{"en":"Geoengineering means large-scale manipulation of the environment.","zh":"地球工程指對環境的大規模操控。"},{"en":"Large-scale manipulation of something means changing it across a very wide area or system.","zh":"large-scale manipulation of something 指在很大範圍或系統上改變某事。"},{"en":"Building dams on several rivers may involve large-scale manipulation of water flow.","zh":"在數條河流上建水壩可能涉及對水流的大規模操控。"},{"en":"Large-scale manipulation of a city’s transport system can affect millions of commuters.","zh":"對城市交通系統的大規模操控可以影響數百萬通勤者。"},{"en":"This phrase suggests major intervention, not small local adjustment.","zh":"這個片語暗示重大干預，而不是小型本地調整。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":3},{"front":"geoengineering has been shown to work","meaning":"地球工程已被證明可行","examples":[{"en":"Geoengineering has been shown to work on a small scale.","zh":"地球工程已被證明在小規模上可行。"},{"en":"Geoengineering has been shown to work means evidence suggests some methods can achieve their intended effect.","zh":"geoengineering has been shown to work 指證據顯示某些方法能達到預期效果。"},{"en":"A teaching method has been shown to work if students improve after using it repeatedly.","zh":"如果學生反覆使用某教學方法後進步，該方法便已被證明可行。"},{"en":"Even if a method has been shown to work locally, it may fail on a larger scale.","zh":"即使某方法在本地已被證明可行，在更大規模上也可能失敗。"},{"en":"This phrase points to evidence, but it does not prove that every version is safe.","zh":"這個片語指向證據，但不證明每個版本都安全。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":3},{"front":"at least","meaning":"至少","examples":[{"en":"Geoengineering has worked, at least on a small and localised scale.","zh":"地球工程已經奏效，至少在小型和局部規模上是如此。"},{"en":"At least means not less than, or used to limit a claim to what is definitely true.","zh":"at least 指不少於，或用來把說法限制在肯定為真的範圍內。"},{"en":"The train is late, but at least we have seats while we wait.","zh":"火車遲到，但至少我們等待時有座位。"},{"en":"The plan may not solve everything, but at least it reduces the most urgent risk.","zh":"這個計劃未必解決一切，但至少減少最緊急風險。"},{"en":"This phrase can soften a claim by showing its limit.","zh":"這個片語可以透過顯示限制來減弱說法。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":3},{"front":"localised scale","meaning":"局部規模","examples":[{"en":"Cloud-dispersal techniques have worked on a localised scale.","zh":"驅散雲層技術已在局部規模上奏效。"},{"en":"Localised scale means within a small or specific area rather than across a whole region or planet.","zh":"localised scale 指在小型或特定地區內，而不是整個地區或全球範圍。"},{"en":"A traffic rule may work on a localised scale in one busy street.","zh":"一條交通規則可能在某條繁忙街道的局部規模上有效。"},{"en":"A localised scale trial can show whether an idea is worth testing more widely.","zh":"局部規模試驗可以顯示某想法是否值得更廣泛測試。"},{"en":"This phrase warns that success in one small area may not prove global success.","zh":"這個片語提醒我們，小範圍成功未必證明全球成功。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":3},{"front":"for decades","meaning":"數十年來","examples":[{"en":"Small-scale geoengineering has been used for decades.","zh":"小規模地球工程已被使用數十年。"},{"en":"For decades means for many periods of ten years.","zh":"for decades 指經過許多個十年。"},{"en":"This family shop has served the neighbourhood for decades.","zh":"這間家庭小店已服務社區數十年。"},{"en":"If a problem continues for decades, it may become part of normal life.","zh":"如果一個問題持續數十年，它可能變成日常生活的一部分。"},{"en":"This phrase shows that something has lasted a long time.","zh":"這個片語顯示某事已持續很久。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":3},{"front":"May Day parades","meaning":"五一勞動節巡遊","examples":[{"en":"May Day parades in Moscow were held under clear skies after cloud dispersal.","zh":"莫斯科的五一勞動節巡遊在驅散雲層後於晴空下舉行。"},{"en":"May Day parades are public marches or celebrations held around 1 May, often connected with workers.","zh":"May Day parades 是大約在5月1日舉行的公共遊行或慶祝活動，常與工人相關。"},{"en":"A city may organise May Day parades with music, banners, and speeches.","zh":"城市可能舉辦有音樂、橫額和演講的五一勞動節巡遊。"},{"en":"Weather can affect May Day parades because crowds need safe outdoor conditions.","zh":"天氣可以影響五一勞動節巡遊，因為群眾需要安全戶外環境。"},{"en":"This phrase refers to organised public events, not ordinary walks.","zh":"這個片語指有組織的公共活動，而不是普通散步。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":4},{"front":"take place under clear blue skies","meaning":"在晴朗藍天下舉行","examples":[{"en":"The parades took place under clear blue skies.","zh":"巡遊在晴朗藍天下舉行。"},{"en":"To take place under clear blue skies means to happen outdoors when the weather is bright and cloudless.","zh":"take place under clear blue skies 指在明亮無雲的戶外天氣中發生。"},{"en":"The school sports day took place under clear blue skies, so no events were cancelled.","zh":"學校運動會在晴朗藍天下舉行，所以沒有項目被取消。"},{"en":"Outdoor weddings are easier when they take place under clear blue skies.","zh":"戶外婚禮在晴朗藍天下舉行時會較容易安排。"},{"en":"This phrase creates a picture of good weather during an event.","zh":"這個片語營造出活動期間天氣良好的畫面。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":4},{"front":"deposit dry ice","meaning":"投放乾冰","examples":[{"en":"Aircraft deposited dry ice to disperse clouds.","zh":"飛機投放乾冰以驅散雲層。"},{"en":"To deposit dry ice means to drop or place frozen carbon dioxide onto or into a target area.","zh":"deposit dry ice 指把冷凍二氧化碳投下或放入目標區域。"},{"en":"Scientists may deposit dry ice into clouds during a weather-modification experiment.","zh":"科學家可能在天氣改造實驗中向雲層投放乾冰。"},{"en":"If aircraft deposit dry ice in the wrong place, the result may be weak or unpredictable.","zh":"如果飛機在錯誤位置投放乾冰，結果可能很弱或不可預測。"},{"en":"This phrase describes a deliberate technical action, not ordinary storage.","zh":"這個片語描述有意識的技術行動，而不是普通儲存。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":4},{"front":"silver iodide","meaning":"碘化銀","examples":[{"en":"Silver iodide has been used to disperse clouds.","zh":"碘化銀曾被用來驅散雲層。"},{"en":"Silver iodide is a chemical sometimes used in cloud seeding or weather modification.","zh":"silver iodide 是一種有時用於人工增雨或天氣改造的化學物質。"},{"en":"Aircraft may release silver iodide into clouds to encourage changes in moisture.","zh":"飛機可能把碘化銀釋放到雲層中，以促使水分變化。"},{"en":"Because silver iodide affects cloud particles, it must be used carefully.","zh":"因為碘化銀會影響雲粒子，所以必須小心使用。"},{"en":"This term belongs to scientific and environmental discussions.","zh":"這個術語屬於科學和環境討論。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":4},{"front":"cement powder","meaning":"水泥粉","examples":[{"en":"Aircraft used cement powder as part of cloud dispersal.","zh":"飛機使用水泥粉作為驅散雲層的一部分。"},{"en":"Cement powder is a fine dry material used to make cement or concrete.","zh":"cement powder 是用來製造水泥或混凝土的幼細乾燥材料。"},{"en":"Workers wear masks around cement powder because it can irritate the lungs.","zh":"工人在水泥粉附近會戴口罩，因為它可能刺激肺部。"},{"en":"In the passage, cement powder is mentioned as a substance used in weather modification.","zh":"在文章中，水泥粉被提及為天氣改造中使用的物質。"},{"en":"This phrase refers to a physical powder, not finished concrete.","zh":"這個片語指實體粉末，而不是完成的混凝土。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":4},{"front":"disperse clouds","meaning":"驅散雲層","examples":[{"en":"Chemicals were deposited to disperse clouds.","zh":"化學物質被投放以驅散雲層。"},{"en":"To disperse clouds means to make clouds spread out, break up, or disappear.","zh":"disperse clouds 指使雲層分散、破開或消失。"},{"en":"Weather-control experiments may try to disperse clouds before a major outdoor ceremony.","zh":"天氣控制實驗可能在大型戶外典禮前嘗試驅散雲層。"},{"en":"If clouds are dispersed successfully, sunlight may reach the ground more easily.","zh":"如果雲層成功被驅散，陽光可能更容易到達地面。"},{"en":"This phrase describes changing cloud cover, not simply predicting weather.","zh":"這個片語描述改變雲量，而不只是預測天氣。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":4},{"front":"seek to do the opposite","meaning":"試圖做相反的事","examples":[{"en":"Many proposed schemes seek to do the opposite and reduce sunlight.","zh":"許多被提出的方案試圖做相反的事，減少陽光。"},{"en":"To seek to do the opposite means to try to achieve the reverse effect.","zh":"seek to do the opposite 指嘗試達到相反效果。"},{"en":"If one diet increases calories, another plan may seek to do the opposite and reduce them.","zh":"如果一種飲食增加卡路里，另一個計劃可能試圖做相反的事並減少卡路里。"},{"en":"A noisy café may seek to do the opposite of fast-food restaurants by creating a quiet atmosphere.","zh":"嘈雜咖啡店可能試圖做與快餐店相反的事，營造安靜氣氛。"},{"en":"This phrase highlights contrast between two aims.","zh":"這個片語突出兩個目標之間的對比。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":4},{"front":"reduce the amount of sunlight","meaning":"減少陽光量","examples":[{"en":"Some schemes aim to reduce the amount of sunlight reaching Earth.","zh":"一些方案旨在減少到達地球的陽光量。"},{"en":"To reduce the amount of sunlight means to make less sunlight arrive at a place.","zh":"reduce the amount of sunlight 指令到達某地的陽光變少。"},{"en":"Curtains reduce the amount of sunlight entering a bedroom in the morning.","zh":"窗簾可以減少早上進入睡房的陽光量。"},{"en":"If less sunlight reaches Earth, temperatures may fall in some areas.","zh":"如果較少陽光到達地球，一些地區的氣溫可能下降。"},{"en":"This phrase focuses on lowering incoming light, not removing the sun itself.","zh":"這個片語聚焦於降低進入的光量，而不是移除太陽本身。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":4},{"front":"reaching the planet","meaning":"到達地球","examples":[{"en":"Geoengineering may reduce sunlight reaching the planet.","zh":"地球工程可能減少到達地球的陽光。"},{"en":"Reaching the planet means arriving at Earth from space or the atmosphere.","zh":"reaching the planet 指從太空或大氣到達地球。"},{"en":"Clouds can reduce the sunlight reaching the planet’s surface.","zh":"雲層可以減少到達地球表面的陽光。"},{"en":"If less heat is reaching the planet, climate patterns may change.","zh":"如果較少熱量到達地球，氣候模式可能改變。"},{"en":"This phrase describes movement toward Earth.","zh":"這個片語描述朝地球移動。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":4},{"front":"aim to cool the Earth generally","meaning":"旨在令地球整體降溫","examples":[{"en":"One scheme aims to cool the Earth generally.","zh":"一個方案旨在令地球整體降溫。"},{"en":"To aim to cool the Earth generally means to try to lower global temperatures overall.","zh":"aim to cool the Earth generally 指嘗試降低全球整體氣溫。"},{"en":"A policy may aim to cool the Earth generally by reducing heat-trapping gases.","zh":"政策可能透過減少困住熱力的氣體，旨在令地球整體降溫。"},{"en":"If a method cools the Earth generally, it may affect weather in many regions.","zh":"如果某方法令地球整體降溫，它可能影響許多地區的天氣。"},{"en":"This phrase refers to a broad global goal, not a small local effect.","zh":"這個片語指廣泛全球目標，而不是小型本地效果。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":4},{"front":"release aerosol sprays into","meaning":"將氣溶膠噴霧釋放到……","examples":[{"en":"The scheme would release aerosol sprays into the stratosphere.","zh":"該方案會將氣溶膠噴霧釋放到平流層。"},{"en":"To release aerosol sprays into a place means to send tiny particles or droplets into that area.","zh":"release aerosol sprays into a place 指把微小粒子或液滴送入某區域。"},{"en":"A factory should not release aerosol sprays into the air without safety controls.","zh":"工廠不應在沒有安全控制下將氣溶膠噴霧釋放到空氣中。"},{"en":"Releasing aerosol sprays into the upper atmosphere could change how sunlight is reflected.","zh":"將氣溶膠噴霧釋放到高層大氣可能改變陽光如何被反射。"},{"en":"This phrase describes a technical action that may have wide effects.","zh":"這個片語描述可能有廣泛影響的技術行動。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":4},{"front":"aerosol sprays","meaning":"氣溶膠噴霧","examples":[{"en":"Aerosol sprays could be released above the Arctic.","zh":"氣溶膠噴霧可以被釋放到北極上空。"},{"en":"Aerosol sprays are tiny particles or droplets suspended in the air.","zh":"aerosol sprays 是懸浮在空氣中的微小粒子或液滴。"},{"en":"Some household products release aerosol sprays when pressed from a can.","zh":"一些家用產品從罐中按壓時會釋放氣溶膠噴霧。"},{"en":"In climate proposals, aerosol sprays may be used to reflect sunlight.","zh":"在氣候方案中，氣溶膠噴霧可能被用來反射陽光。"},{"en":"Because aerosol sprays can spread through air, their effects may be hard to control.","zh":"因為氣溶膠噴霧能在空氣中擴散，其影響可能難以控制。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":5},{"front":"the stratosphere","meaning":"平流層","examples":[{"en":"Aerosols could be released into the stratosphere above the Arctic.","zh":"氣溶膠可以被釋放到北極上空的平流層。"},{"en":"The stratosphere is a high layer of Earth’s atmosphere above the weather layer.","zh":"the stratosphere 是地球大氣中位於天氣層之上的高層。"},{"en":"Aircraft or balloons may be needed to reach the stratosphere.","zh":"可能需要飛機或氣球才能到達平流層。"},{"en":"Particles in the stratosphere can stay high above the ground and affect sunlight.","zh":"平流層中的粒子可以停留在高空並影響陽光。"},{"en":"This word refers to a specific atmospheric layer, not ordinary ground-level air.","zh":"這個詞指特定大氣層，而不是普通地面空氣。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":5},{"front":"above the Arctic","meaning":"在北極上空","examples":[{"en":"The sprays would be released above the Arctic.","zh":"噴霧會被釋放到北極上空。"},{"en":"Above the Arctic means in the sky or atmosphere over the Arctic region.","zh":"above the Arctic 指在北極地區上方的天空或大氣中。"},{"en":"Satellites can observe clouds above the Arctic during polar research.","zh":"衛星可以在極地研究期間觀察北極上空的雲層。"},{"en":"If particles are released above the Arctic, they may affect ice and sunlight in that region.","zh":"如果粒子被釋放到北極上空，它們可能影響該區的冰和陽光。"},{"en":"This phrase gives a location in the high northern polar area.","zh":"這個片語給出高北極地區的位置。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":5},{"front":"clouds of sulphur dioxide","meaning":"二氧化硫雲","examples":[{"en":"The aerosols would create clouds of sulphur dioxide.","zh":"氣溶膠會形成二氧化硫雲。"},{"en":"Clouds of sulphur dioxide are masses of sulphur dioxide gas or particles in the air.","zh":"clouds of sulphur dioxide 是空氣中的二氧化硫氣體或粒子團。"},{"en":"Volcanic eruptions can create clouds of sulphur dioxide high in the atmosphere.","zh":"火山爆發可以在高層大氣形成二氧化硫雲。"},{"en":"Such clouds may reflect sunlight but can also raise environmental concerns.","zh":"這些雲可能反射陽光，但也會引起環境憂慮。"},{"en":"This phrase describes a chemical cloud, not a normal water cloud.","zh":"這個片語描述化學雲，而不是普通水雲。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":5},{"front":"cause global dimming","meaning":"導致全球變暗","examples":[{"en":"Sulphur dioxide clouds could cause global dimming.","zh":"二氧化硫雲可能導致全球變暗。"},{"en":"To cause global dimming means to reduce the amount of sunlight reaching Earth worldwide.","zh":"cause global dimming 指減少全球到達地球的陽光量。"},{"en":"Large volcanic eruptions can cause global dimming for a short period.","zh":"大型火山爆發可以在短時間內導致全球變暗。"},{"en":"Global dimming may cool temperatures, but it can also affect rainfall and farming.","zh":"全球變暗可能降低氣溫，但也可能影響降雨和農業。"},{"en":"This phrase describes a planet-wide reduction in sunlight.","zh":"這個片語描述全球範圍的陽光減少。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":5},{"front":"global dimming","meaning":"全球變暗","examples":[{"en":"Global dimming could reduce the sunlight reaching Earth.","zh":"全球變暗可能減少到達地球的陽光。"},{"en":"Global dimming is a reduction in the amount of sunlight that reaches Earth’s surface.","zh":"global dimming 是到達地球表面的陽光量減少。"},{"en":"Pollution particles in the air can contribute to global dimming by reflecting sunlight away.","zh":"空氣中的污染粒子可以透過反射陽光，導致全球變暗。"},{"en":"If global dimming changes rainfall, farmers may face unexpected problems.","zh":"如果全球變暗改變降雨，農民可能面對意想不到的問題。"},{"en":"This term describes less sunlight, not simply darker nights.","zh":"這個術語描述陽光減少，而不只是夜晚更黑。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":5},{"front":"be modelled on","meaning":"以……為模型","examples":[{"en":"The idea is modelled on historical volcanic eruptions.","zh":"這個想法以歷史上的火山爆發為模型。"},{"en":"To be modelled on something means to be designed by copying or learning from it.","zh":"be modelled on something 指透過模仿或借鑑某物來設計。"},{"en":"A new school timetable may be modelled on one used successfully in another school.","zh":"新學校時間表可能以另一間學校成功使用的時間表為模型。"},{"en":"If a policy is modelled on a foreign system, it still needs local adjustment.","zh":"如果政策以外國制度為模型，它仍需要本地調整。"},{"en":"This phrase shows that one idea uses another as a pattern.","zh":"這個片語顯示一個想法以另一個作為模式。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":5},{"front":"historical volcanic eruptions","meaning":"歷史上的火山爆發","examples":[{"en":"The scheme is based on historical volcanic eruptions.","zh":"這個方案基於歷史上的火山爆發。"},{"en":"Historical volcanic eruptions are past events when volcanoes released ash, gas, and heat.","zh":"historical volcanic eruptions 是過去火山釋放火山灰、氣體和熱力的事件。"},{"en":"Scientists study historical volcanic eruptions to understand how they affected climate.","zh":"科學家研究歷史上的火山爆發，以理解它們如何影響氣候。"},{"en":"A major eruption can cool the planet temporarily if particles block sunlight.","zh":"如果粒子阻擋陽光，大型火山爆發可以暫時令地球降溫。"},{"en":"This phrase uses past natural events as evidence or comparison.","zh":"這個片語使用過去自然事件作為證據或比較。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":5},{"front":"Mount Pinatubo","meaning":"皮納圖博火山","examples":[{"en":"Mount Pinatubo erupted in the Philippines in 1991.","zh":"皮納圖博火山於1991年在菲律賓爆發。"},{"en":"Mount Pinatubo is a volcano in the Philippines known for a major eruption.","zh":"Mount Pinatubo 是菲律賓一座以大型爆發聞名的火山。"},{"en":"Scientists often mention Mount Pinatubo when discussing how volcanic particles affect climate.","zh":"科學家討論火山粒子如何影響氣候時，常提到皮納圖博火山。"},{"en":"The eruption of Mount Pinatubo showed that natural events can temporarily cool global temperatures.","zh":"皮納圖博火山爆發顯示自然事件可以暫時令全球氣溫下降。"},{"en":"This name is used as a real-world example in climate discussions.","zh":"這個名稱在氣候討論中用作真實例子。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":5},{"front":"short-term drop","meaning":"短期下降","examples":[{"en":"The eruption produced a short-term drop in global temperatures.","zh":"這次爆發導致全球氣溫短期下降。"},{"en":"A short-term drop is a decrease that lasts for a limited period.","zh":"short-term drop 指持續有限時間的下降。"},{"en":"A shop may see a short-term drop in sales during bad weather.","zh":"商店在惡劣天氣期間可能看到銷售短期下降。"},{"en":"A short-term drop in temperature does not necessarily disprove long-term warming.","zh":"氣溫短期下降不一定推翻長期暖化。"},{"en":"This phrase describes a temporary fall, not a permanent trend.","zh":"這個片語描述暫時下跌，而不是永久趨勢。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":5},{"front":"global temperatures","meaning":"全球氣溫","examples":[{"en":"Volcanic eruptions can affect global temperatures.","zh":"火山爆發可以影響全球氣溫。"},{"en":"Global temperatures are average temperature levels measured across the whole planet.","zh":"global temperatures 是在整個地球範圍量度的平均氣溫水平。"},{"en":"Scientists track global temperatures to see whether Earth is warming over time.","zh":"科學家追蹤全球氣溫，以了解地球是否隨時間變暖。"},{"en":"Rising global temperatures can change rainfall, ice cover, and sea levels.","zh":"全球氣溫上升可以改變降雨、冰覆蓋和海平面。"},{"en":"This phrase refers to the planet as a whole, not today’s weather in one city.","zh":"這個片語指整個地球，而不是某城市今天的天氣。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":5},{"front":"high-flying aircraft","meaning":"高空飛行的飛機","examples":[{"en":"High-flying aircraft could deliver aerosols into the atmosphere.","zh":"高空飛行的飛機可以把氣溶膠釋放到大氣中。"},{"en":"High-flying aircraft are planes that can operate at very high altitudes.","zh":"high-flying aircraft 是能在很高高度運作的飛機。"},{"en":"Weather researchers may use high-flying aircraft to collect data above storms.","zh":"天氣研究人員可能使用高空飛行的飛機在風暴上方收集數據。"},{"en":"If aerosols must reach the stratosphere, high-flying aircraft may be needed.","zh":"如果氣溶膠必須到達平流層，可能需要高空飛行的飛機。"},{"en":"This phrase describes aircraft by where they fly, not by passenger comfort.","zh":"這個片語按飛行位置描述飛機，而不是按乘客舒適度。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":6},{"front":"deliver the aerosols","meaning":"釋放氣溶膠","examples":[{"en":"Aircraft, artillery or balloons could deliver the aerosols.","zh":"飛機、炮火或氣球可以釋放氣溶膠。"},{"en":"To deliver the aerosols means to transport and release tiny particles to the target area.","zh":"deliver the aerosols 指把微小粒子運送並釋放到目標區域。"},{"en":"Balloons might deliver the aerosols if aircraft are too expensive.","zh":"如果飛機太昂貴，氣球可能釋放氣溶膠。"},{"en":"If the aerosols are delivered unevenly, the cooling effect may be uneven too.","zh":"如果氣溶膠釋放不均，降溫效果也可能不均。"},{"en":"This phrase describes the method of placing particles where they are meant to work.","zh":"這個片語描述把粒子放到預定作用位置的方法。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":6},{"front":"instead of concentrating on","meaning":"不集中於……而是","examples":[{"en":"Instead of concentrating on global cooling, some schemes focus on polar melting.","zh":"一些方案不集中於全球降溫，而是聚焦於極地融化。"},{"en":"Instead of concentrating on something means choosing not to focus mainly on it.","zh":"instead of concentrating on something 指選擇不主要聚焦於某事。"},{"en":"Instead of concentrating on grammar only, a language course may also teach speaking practice.","zh":"語言課程不應只集中於文法，而也可以教授口語練習。"},{"en":"A company may improve service instead of concentrating on price cuts alone.","zh":"公司可能改善服務，而不是只集中於減價。"},{"en":"This phrase shows a clear shift from one focus to another.","zh":"這個片語顯示由一個焦點轉向另一個焦點。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":6},{"front":"global cooling","meaning":"全球降溫","examples":[{"en":"Some schemes focus on global cooling.","zh":"一些方案聚焦於全球降溫。"},{"en":"Global cooling means a reduction in average temperatures across the planet.","zh":"global cooling 指地球整體平均氣溫下降。"},{"en":"A large volcanic eruption can cause temporary global cooling by blocking sunlight.","zh":"大型火山爆發可以透過阻擋陽光造成暫時全球降溫。"},{"en":"Artificial global cooling may reduce warming but create new climate risks.","zh":"人工全球降溫可能減少暖化，但也造成新的氣候風險。"},{"en":"This phrase is the opposite of global warming in temperature direction.","zh":"這個片語在氣溫方向上與全球暖化相反。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":6},{"front":"focus on reversing","meaning":"集中於逆轉……","examples":[{"en":"Other schemes focus on reversing polar melting.","zh":"其他方案集中於逆轉極地融化。"},{"en":"To focus on reversing something means to concentrate on turning a problem back in the opposite direction.","zh":"focus on reversing something 指集中於把問題朝相反方向扭轉。"},{"en":"A school may focus on reversing falling attendance by improving support for students.","zh":"學校可能集中於透過改善學生支援來逆轉出席率下降。"},{"en":"A city may focus on reversing pollution by closing dirty factories and improving transport.","zh":"城市可能透過關閉污染工廠和改善交通，集中於逆轉污染。"},{"en":"This phrase suggests more than slowing a problem; it means trying to undo it.","zh":"這個片語暗示不只是減慢問題，而是嘗試消除其結果。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":6},{"front":"polar melting","meaning":"極地融化","examples":[{"en":"Several ideas aim to reverse polar melting.","zh":"幾個想法旨在逆轉極地融化。"},{"en":"Polar melting means the loss of ice in the Arctic and Antarctic regions.","zh":"polar melting 指北極和南極地區的冰流失。"},{"en":"Polar melting can threaten animals that depend on sea ice.","zh":"極地融化可以威脅依賴海冰的動物。"},{"en":"As polar melting increases, more water may enter the oceans and raise sea levels.","zh":"隨着極地融化增加，更多水可能流入海洋並令海平面上升。"},{"en":"This phrase focuses on ice loss near the poles.","zh":"這個片語聚焦於兩極附近的冰流失。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":6},{"front":"bolster an ice cap","meaning":"加固冰蓋","examples":[{"en":"One idea is to bolster an ice cap by spraying it with water.","zh":"一個想法是透過向冰蓋噴水來加固冰蓋。"},{"en":"To bolster an ice cap means to strengthen or thicken a large area of ice.","zh":"bolster an ice cap 指加強或增厚一大片冰。"},{"en":"Scientists might try to bolster an ice cap if it is losing mass too quickly.","zh":"如果冰蓋流失質量太快，科學家可能嘗試加固冰蓋。"},{"en":"If an ice cap is bolstered, it may reflect more sunlight and melt more slowly.","zh":"如果冰蓋被加固，它可能反射更多陽光並融化得更慢。"},{"en":"This phrase suggests supporting something that is weakening.","zh":"這個片語暗示支撐正在變弱的東西。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":6},{"front":"ice cap","meaning":"冰蓋","examples":[{"en":"An ice cap could be thickened by spraying water over it.","zh":"冰蓋可以透過向其噴水而增厚。"},{"en":"An ice cap is a large mass of ice covering land or sea in cold regions.","zh":"ice cap 是寒冷地區覆蓋陸地或海洋的大塊冰。"},{"en":"Polar bears and seals may depend on areas near ice caps for their habitat.","zh":"北極熊和海豹可能依賴冰蓋附近地區作棲息地。"},{"en":"When an ice cap melts, it can affect sea levels and local ecosystems.","zh":"當冰蓋融化，它可以影響海平面和本地生態系統。"},{"en":"This phrase refers to a broad ice cover, not a small patch of frost.","zh":"這個片語指廣闊冰層，而不是小片霜。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":6},{"front":"spray something with water","meaning":"用水噴灑……","examples":[{"en":"Scientists have suggested spraying an ice cap with water.","zh":"科學家建議用水噴灑冰蓋。"},{"en":"To spray something with water means to cover it with many small drops of water.","zh":"spray something with water 指用許多小水滴覆蓋某物。"},{"en":"Gardeners spray plants with water when the soil and leaves are too dry.","zh":"當泥土和葉子太乾時，園丁會用水噴灑植物。"},{"en":"Spraying a surface with water can cool it or clean it.","zh":"用水噴灑表面可以令它降溫或清潔它。"},{"en":"In the passage, spraying ice with water is meant to create more ice, not to wash it.","zh":"在文章中，用水噴灑冰層是為了形成更多冰，而不是清洗它。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":6},{"front":"pumps would carry","meaning":"水泵會輸送","examples":[{"en":"Pumps would carry water from beneath the sea ice.","zh":"水泵會從海冰之下輸送水。"},{"en":"Pumps would carry means machines would move liquid from one place to another.","zh":"pumps would carry 指機器會把液體從一處移到另一處。"},{"en":"In a flooded basement, pumps would carry water out of the building.","zh":"在被水淹浸的地庫中，水泵會把水輸送出建築物。"},{"en":"If pumps carry water too slowly, the system may not work effectively.","zh":"如果水泵輸送水太慢，系統可能無法有效運作。"},{"en":"This phrase describes mechanical movement of water.","zh":"這個片語描述水的機械式移動。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":6},{"front":"beneath the sea ice","meaning":"在海冰之下","examples":[{"en":"Water could be pumped from beneath the sea ice.","zh":"水可以從海冰之下被抽上來。"},{"en":"Beneath the sea ice means under the layer of frozen seawater.","zh":"beneath the sea ice 指在冰凍海水層下面。"},{"en":"Animals may swim beneath the sea ice where humans cannot easily see them.","zh":"動物可能在海冰之下游動，而人類不容易看見它們。"},{"en":"If warmer water flows beneath the sea ice, melting may increase.","zh":"如果較暖的水在海冰之下流動，融化可能增加。"},{"en":"This phrase gives a location below ocean ice.","zh":"這個片語給出位於海洋冰層下方的位置。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":6},{"front":"emerge as","meaning":"以……形式出現","examples":[{"en":"The spray would emerge as snow or ice particles.","zh":"噴霧會以雪或冰粒形式出現。"},{"en":"To emerge as something means to appear or become visible in a particular form.","zh":"emerge as something 指以某種形式出現或變得可見。"},{"en":"Water vapour can emerge as frost on a cold window.","zh":"水蒸氣可以在寒冷窗戶上以霜的形式出現。"},{"en":"A quiet student may emerge as a leader during group work.","zh":"安靜的學生可能在小組工作中以領袖身份出現。"},{"en":"This phrase can describe physical form or a new role.","zh":"這個片語可以描述實體形態或新角色。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":7},{"front":"ice particles","meaning":"冰粒","examples":[{"en":"The sprayed water would emerge as ice particles.","zh":"被噴出的水會以冰粒形式出現。"},{"en":"Ice particles are tiny pieces or crystals of frozen water.","zh":"ice particles 是冰凍水形成的細小碎片或晶體。"},{"en":"Ice particles may form in the air when water freezes quickly.","zh":"當水快速結冰，冰粒可能在空氣中形成。"},{"en":"If many ice particles settle on sea ice, the ice surface may become thicker.","zh":"如果許多冰粒落在海冰上，冰面可能變得更厚。"},{"en":"This phrase refers to small frozen pieces, not a large solid block.","zh":"這個片語指細小冰凍顆粒，而不是大型實心冰塊。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":7},{"front":"thicker sea ice","meaning":"較厚的海冰","examples":[{"en":"The method would produce thicker sea ice.","zh":"這種方法會產生較厚的海冰。"},{"en":"Thicker sea ice means frozen seawater that has greater depth or mass.","zh":"thicker sea ice 指深度或質量較大的冰凍海水。"},{"en":"Thicker sea ice is harder for waves and warm air to break down quickly.","zh":"較厚的海冰較難被海浪和暖空氣快速破壞。"},{"en":"If sea ice becomes thicker, it may last longer through warm seasons.","zh":"如果海冰變得較厚，它可能在暖季持續更久。"},{"en":"This phrase compares ice depth, not the size of the ocean area.","zh":"這個片語比較冰的厚度，而不是海洋面積大小。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":7},{"front":"a higher albedo","meaning":"較高反照率","examples":[{"en":"Thicker sea ice would have a higher albedo.","zh":"較厚的海冰會有較高反照率。"},{"en":"A higher albedo means a surface reflects a larger share of incoming sunlight.","zh":"a higher albedo 指表面反射較大比例的入射陽光。"},{"en":"White roofs have a higher albedo than black roofs because they reflect more sunlight.","zh":"白色屋頂比黑色屋頂有較高反照率，因為它們反射更多陽光。"},{"en":"If ice has a higher albedo, it absorbs less heat and may melt more slowly.","zh":"如果冰有較高反照率，它吸收較少熱力，可能融化得較慢。"},{"en":"This phrase is common in climate science when discussing reflection.","zh":"這個片語在討論反射時常見於氣候科學。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":7},{"front":"the proportion of sunlight reflected by","meaning":"由……反射的陽光比例","examples":[{"en":"Albedo is the proportion of sunlight reflected by a surface.","zh":"反照率是由表面反射的陽光比例。"},{"en":"The proportion of sunlight reflected by something means the share of sunlight that bounces back from it.","zh":"the proportion of sunlight reflected by something 指從某物反彈回去的陽光份額。"},{"en":"The proportion of sunlight reflected by snow is higher than that reflected by dark soil.","zh":"由雪反射的陽光比例高於由深色泥土反射的比例。"},{"en":"If a surface reflects more sunlight, it usually absorbs less heat.","zh":"如果一個表面反射更多陽光，它通常吸收較少熱力。"},{"en":"This phrase explains how brightness can affect temperature.","zh":"這個片語解釋亮度如何影響溫度。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":7},{"front":"reflected by a surface","meaning":"被表面反射","examples":[{"en":"Albedo measures the sunlight reflected by a surface.","zh":"反照率量度被表面反射的陽光。"},{"en":"Reflected by a surface means bounced back from the outside layer of something.","zh":"reflected by a surface 指從某物外層反彈回來。"},{"en":"Sunlight reflected by a mirror can be very bright.","zh":"被鏡面反射的陽光可以很刺眼。"},{"en":"Light reflected by snow can make people wear sunglasses even in winter.","zh":"被雪反射的光可以令人即使在冬天也戴太陽眼鏡。"},{"en":"This phrase describes light returning from a surface instead of being absorbed.","zh":"這個片語描述光從表面返回，而不是被吸收。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":7},{"front":"summer radiation","meaning":"夏季輻射","examples":[{"en":"Thicker sea ice would reflect more summer radiation.","zh":"較厚的海冰會反射更多夏季輻射。"},{"en":"Summer radiation means energy from the sun received during the summer season.","zh":"summer radiation 指夏季接收到的太陽能量。"},{"en":"White surfaces can reflect summer radiation and keep buildings cooler.","zh":"白色表面可以反射夏季輻射，使建築物較涼。"},{"en":"If ice reflects more summer radiation, it may melt more slowly.","zh":"如果冰反射更多夏季輻射，它可能融化得較慢。"},{"en":"This phrase connects sunlight energy with seasonal warming.","zh":"這個片語把陽光能量與季節性升溫連接起來。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":7},{"front":"blocking the flow of","meaning":"阻擋……的流動","examples":[{"en":"Scientists have considered blocking the flow of Greenland’s ice.","zh":"科學家曾考慮阻擋格陵蘭冰的流動。"},{"en":"Blocking the flow of something means stopping or slowing its movement.","zh":"blocking the flow of something 指停止或減慢某物的移動。"},{"en":"A fallen tree can block the flow of traffic on a narrow road.","zh":"倒下的樹可以阻擋狹窄道路上的交通流動。"},{"en":"Blocking the flow of water may reduce flooding in one place but cause problems elsewhere.","zh":"阻擋水流可能減少一處水浸，但在其他地方造成問題。"},{"en":"This phrase usually suggests putting an obstacle in the path of movement.","zh":"這個片語通常暗示在移動路徑上設置障礙。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":7},{"front":"Greenland’s ice","meaning":"格陵蘭的冰","examples":[{"en":"Some schemes try to control the movement of Greenland’s ice.","zh":"一些方案嘗試控制格陵蘭冰的移動。"},{"en":"Greenland’s ice refers to the huge ice sheets and glaciers found on Greenland.","zh":"Greenland’s ice 指格陵蘭上的巨大冰蓋和冰川。"},{"en":"Scientists monitor Greenland’s ice because melting there can affect sea levels.","zh":"科學家監測格陵蘭的冰，因為那裡融化可以影響海平面。"},{"en":"If Greenland’s ice moves faster into the ocean, more ice may be lost.","zh":"如果格陵蘭的冰更快移入海洋，可能流失更多冰。"},{"en":"This phrase focuses on ice connected with Greenland, not all Arctic ice.","zh":"這個片語聚焦於與格陵蘭相關的冰，而不是所有北極冰。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":7},{"front":"reinforced cables","meaning":"加固纜索","examples":[{"en":"Reinforced cables might be used to block ice movement.","zh":"加固纜索可能被用來阻擋冰的移動。"},{"en":"Reinforced cables are strong cables made stronger with extra material or structure.","zh":"reinforced cables 是用額外材料或結構加強的堅固纜索。"},{"en":"Engineers use reinforced cables in bridges where ordinary cables would be too weak.","zh":"工程師在普通纜索太弱的橋樑中使用加固纜索。"},{"en":"If reinforced cables face too much force, they can still break.","zh":"如果加固纜索承受太大力量，它們仍可能斷裂。"},{"en":"This phrase suggests strength, but not unlimited strength.","zh":"這個片語暗示強度，但不是無限強度。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":7},{"front":"prevent icebergs from","meaning":"防止冰山……","examples":[{"en":"The cables would prevent icebergs from moving into the sea.","zh":"纜索會防止冰山移入海中。"},{"en":"To prevent icebergs from doing something means to stop large floating ice pieces from taking that action.","zh":"prevent icebergs from doing something 指阻止大型浮冰採取某行動。"},{"en":"Barriers might prevent icebergs from drifting too close to ships.","zh":"障礙物可能防止冰山漂得太近船隻。"},{"en":"If icebergs are prevented from entering warmer water, they may melt more slowly.","zh":"如果冰山被防止進入較暖水域，它們可能融化得較慢。"},{"en":"This phrase describes an attempt to control iceberg movement.","zh":"這個片語描述控制冰山移動的嘗試。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":7},{"front":"move into the sea","meaning":"移入海中","examples":[{"en":"The scheme aims to stop icebergs moving into the sea.","zh":"這個方案旨在阻止冰山移入海中。"},{"en":"To move into the sea means to travel from land or ice sheets into ocean water.","zh":"move into the sea 指從陸地或冰蓋移動到海水中。"},{"en":"When glacier ice moves into the sea, pieces may break off as icebergs.","zh":"當冰川冰移入海中，部分可能斷裂成冰山。"},{"en":"If more ice moves into the sea, sea levels can rise over time.","zh":"如果更多冰移入海中，海平面可以隨時間上升。"},{"en":"This phrase describes movement from a frozen land area toward open water.","zh":"這個片語描述從冰凍陸地區域向開放水域移動。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":8},{"front":"be impractical","meaning":"不切實際","examples":[{"en":"Kallio says the reinforced-cable idea is impractical.","zh":"Kallio 說加固纜索的想法不切實際。"},{"en":"If an idea is impractical, it is too difficult, costly, or unrealistic to use successfully.","zh":"如果一個想法 is impractical，意思是它太困難、太昂貴或不現實，難以成功使用。"},{"en":"Asking every student to study ten hours a day is impractical.","zh":"要求每個學生每天學習十小時是不切實際的。"},{"en":"A plan may be clever but impractical if it requires equipment nobody has.","zh":"如果計劃需要沒有人擁有的設備，它可能聰明但不切實際。"},{"en":"This phrase criticises whether something can really be done.","zh":"這個片語批評某事是否真的可行。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":8},{"front":"the force of the ice","meaning":"冰的力量","examples":[{"en":"The force of the ice would eventually snap the cables.","zh":"冰的力量最終會把纜索扯斷。"},{"en":"The force of the ice means the physical pressure or power created by moving or heavy ice.","zh":"the force of the ice 指移動或沉重冰塊產生的物理壓力或力量。"},{"en":"The force of the ice can damage ships, bridges, or coastal structures.","zh":"冰的力量可以損壞船隻、橋樑或沿海結構。"},{"en":"If engineers underestimate the force of the ice, their equipment may fail.","zh":"如果工程師低估冰的力量，設備可能失效。"},{"en":"This phrase shows that ice can act like a powerful moving object.","zh":"這個片語顯示冰可以像強大的移動物體一樣作用。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":8},{"front":"eventually snap the cables","meaning":"最終把纜索扯斷","examples":[{"en":"The ice would eventually snap the cables.","zh":"冰最終會把纜索扯斷。"},{"en":"To eventually snap the cables means to break the cables after enough pressure or time.","zh":"eventually snap the cables 指經過足夠壓力或時間後把纜索弄斷。"},{"en":"Strong waves may eventually snap old ropes holding a small boat.","zh":"強浪可能最終把固定小船的舊繩索扯斷。"},{"en":"If a bridge cable is under constant pressure, it may eventually snap.","zh":"如果橋樑纜索長期受壓，它可能最終斷裂。"},{"en":"This phrase suggests failure after a gradual build-up of force.","zh":"這個片語暗示力量逐漸累積後出現故障。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":8},{"front":"rapidly release","meaning":"迅速釋放","examples":[{"en":"Snapped cables could rapidly release frozen ice into the sea.","zh":"斷裂的纜索可能把冰凍冰塊迅速釋放到海中。"},{"en":"To rapidly release something means to let it go suddenly and quickly.","zh":"rapidly release something 指突然並快速地放出某物。"},{"en":"A broken dam can rapidly release water into a valley.","zh":"破裂水壩可以把水迅速釋放到山谷中。"},{"en":"If a container bursts, it may rapidly release gas into the room.","zh":"如果容器爆裂，它可能把氣體迅速釋放到房間中。"},{"en":"This phrase often suggests danger because the release is fast and hard to control.","zh":"這個片語常暗示危險，因為釋放快速而難以控制。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":8},{"front":"a large quantity of","meaning":"大量的……","examples":[{"en":"The method could release a large quantity of ice.","zh":"這種方法可能釋放大量冰。"},{"en":"A large quantity of something means a great amount of it.","zh":"a large quantity of something 指某物的數量很多。"},{"en":"A supermarket may throw away a large quantity of food if fridges fail.","zh":"如果雪櫃故障，超級市場可能丟棄大量食物。"},{"en":"A large quantity of rain in one hour can flood roads.","zh":"一小時內大量降雨可以淹浸道路。"},{"en":"This phrase stresses amount, not quality.","zh":"這個片語強調數量，而不是質素。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":8},{"front":"frozen ice","meaning":"冰凍的冰塊","examples":[{"en":"The cables might release frozen ice into the sea.","zh":"纜索可能把冰凍的冰塊釋放到海中。"},{"en":"Frozen ice means solid ice that has formed from water and remains frozen.","zh":"frozen ice 指由水形成並保持冰凍的固態冰。"},{"en":"Frozen ice on a road can make walking dangerous.","zh":"道路上的冰凍冰塊可以令行走危險。"},{"en":"If frozen ice breaks apart, it may float away and melt in warmer water.","zh":"如果冰凍冰塊碎裂，它可能漂走並在較暖水中融化。"},{"en":"This phrase emphasises the solid frozen state of the ice.","zh":"這個片語強調冰的固態冰凍狀態。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":8},{"front":"suspension bridges","meaning":"吊橋","examples":[{"en":"Cables like those used in suspension bridges might divert ice.","zh":"像吊橋中使用的纜索可能會轉移冰。"},{"en":"Suspension bridges are bridges whose roadways are supported by strong hanging cables.","zh":"suspension bridges 是路面由強大懸掛纜索支撐的橋樑。"},{"en":"Large suspension bridges need strong cables to carry traffic safely.","zh":"大型吊橋需要堅固纜索來安全承載交通。"},{"en":"If a cable in a suspension bridge weakens, engineers must repair it quickly.","zh":"如果吊橋中的纜索變弱，工程師必須迅速維修。"},{"en":"This phrase gives an example of very strong cable technology.","zh":"這個片語提供非常強纜索技術的例子。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":8},{"front":"divert rather than halt","meaning":"轉移而非停止","examples":[{"en":"Kallio suggests cables might divert, rather than halt, the movement of ice.","zh":"Kallio 建議纜索可能轉移而非停止冰的移動。"},{"en":"To divert rather than halt something means to change its direction instead of stopping it completely.","zh":"divert rather than halt something 指改變某事方向，而不是完全停止它。"},{"en":"A road barrier may divert traffic rather than halt it during repairs.","zh":"道路屏障在維修期間可能轉移交通，而非停止交通。"},{"en":"A teacher may divert a noisy discussion rather than halt it by turning it into a useful debate.","zh":"老師可能把嘈雜討論轉成有用辯論，轉移而非停止它。"},{"en":"This phrase clearly contrasts redirection with complete stopping.","zh":"這個片語清楚對比改變方向與完全停止。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":8},{"front":"southward movement","meaning":"向南移動","examples":[{"en":"The cables might divert the southward movement of ice.","zh":"纜索可能轉移冰向南移動的方向。"},{"en":"Southward movement means movement toward the south.","zh":"southward movement 指朝南方移動。"},{"en":"Birds may begin their southward movement when winter approaches.","zh":"當冬天接近，鳥類可能開始向南移動。"},{"en":"If ice’s southward movement is diverted, it may enter colder water instead.","zh":"如果冰的向南移動被轉移，它可能進入較冷水域。"},{"en":"This phrase describes direction, not speed.","zh":"這個片語描述方向，而不是速度。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":8},{"front":"Spitsbergen","meaning":"斯匹次卑爾根","examples":[{"en":"Kallio discusses ice moving south from Spitsbergen.","zh":"Kallio 討論從斯匹次卑爾根向南移動的冰。"},{"en":"Spitsbergen is an island in the Arctic region, part of the Svalbard archipelago.","zh":"Spitsbergen 是北極地區的一個島嶼，屬於斯瓦爾巴群島。"},{"en":"Scientists may study ice near Spitsbergen because it lies in a cold northern environment.","zh":"科學家可能研究斯匹次卑爾根附近的冰，因為它位於寒冷北方環境。"},{"en":"Ice moving from Spitsbergen can be affected by winds and local currents.","zh":"從斯匹次卑爾根移動的冰可能受風和當地洋流影響。"},{"en":"This name marks a specific Arctic location in the passage.","zh":"這個名稱標示文章中的特定北極地點。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":8},{"front":"local currents","meaning":"當地洋流","examples":[{"en":"Local currents would make the ice float northwards.","zh":"當地洋流會令冰向北漂浮。"},{"en":"Local currents are water movements in a particular area of the sea or ocean.","zh":"local currents 是海洋或海中特定區域的水流。"},{"en":"Swimmers must be careful if local currents are strong near the beach.","zh":"如果海灘附近當地洋流強，游泳者必須小心。"},{"en":"Local currents can move ice, boats, or pollution in unexpected directions.","zh":"當地洋流可以把冰、船隻或污染物移向意想不到的方向。"},{"en":"This phrase focuses on nearby water flow, not global ocean circulation.","zh":"這個片語聚焦於附近水流，而不是全球海洋循環。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":9},{"front":"float northwards","meaning":"向北漂浮","examples":[{"en":"The ice could float northwards because of local currents.","zh":"由於當地洋流，冰可能向北漂浮。"},{"en":"To float northwards means to move on water toward the north.","zh":"float northwards 指在水面上向北移動。"},{"en":"A piece of driftwood may float northwards if the current pushes it that way.","zh":"如果水流把浮木推向北方，它可能向北漂浮。"},{"en":"If ice floats northwards into colder water, it may survive longer.","zh":"如果冰向北漂浮到較冷水域，它可能存留更久。"},{"en":"This phrase describes direction of movement on water.","zh":"這個片語描述水面移動的方向。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":9},{"front":"several geoengineering ideas","meaning":"幾個地球工程構想","examples":[{"en":"Several geoengineering ideas are being examined in the Russian Arctic.","zh":"幾個地球工程構想正在俄羅斯北極地區被研究。"},{"en":"Several geoengineering ideas means a number of proposed methods for deliberately changing climate or environmental conditions.","zh":"several geoengineering ideas 指多個有意改變氣候或環境條件的 proposed 方法。"},{"en":"Scientists compare several geoengineering ideas before deciding which ones deserve field tests.","zh":"科學家比較幾個地球工程構想，再決定哪些值得實地測試。"},{"en":"Some geoengineering ideas may look cheap but create serious side effects.","zh":"一些地球工程構想可能看似便宜，但造成嚴重副作用。"},{"en":"This phrase suggests multiple possible solutions, not one agreed plan.","zh":"這個片語暗示多個可能解決方法，而不是一個已同意計劃。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":9},{"front":"be examined","meaning":"被研究；被審視","examples":[{"en":"Several Arctic geoengineering ideas are being examined.","zh":"幾個北極地球工程構想正在被研究。"},{"en":"If an idea is being examined, it is being studied or considered carefully.","zh":"如果一個想法 is being examined，意思是它正在被仔細研究或考慮。"},{"en":"A doctor may examine test results before choosing treatment.","zh":"醫生可能在選擇治療前審視檢查結果。"},{"en":"A school policy should be examined before it is used on all students.","zh":"學校政策應在用於所有學生前被審視。"},{"en":"This phrase suggests careful checking, not immediate approval.","zh":"這個片語暗示仔細檢查，而不是立即批准。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":9},{"front":"the Russian Arctic","meaning":"俄羅斯北極地區","examples":[{"en":"Some geoengineering ideas are being examined in the Russian Arctic.","zh":"一些地球工程構想正在俄羅斯北極地區被研究。"},{"en":"The Russian Arctic is the Arctic region that lies within or near Russia’s northern territory.","zh":"the Russian Arctic 是位於俄羅斯北部領土內或附近的北極地區。"},{"en":"Scientists study the Russian Arctic because it contains sea ice, permafrost, and sensitive ecosystems.","zh":"科學家研究俄羅斯北極地區，因為那裡有海冰、永久凍土和敏感生態系統。"},{"en":"Changes in the Russian Arctic can affect shipping routes and global climate patterns.","zh":"俄羅斯北極地區的變化可以影響航運路線和全球氣候模式。"},{"en":"This phrase gives a specific northern geographical setting.","zh":"這個片語給出特定北方地理背景。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":9},{"front":"birch trees","meaning":"樺樹","examples":[{"en":"Planting birch trees could increase reflected sunlight.","zh":"種植樺樹可以增加反射陽光。"},{"en":"Birch trees are trees often recognised by their pale or white bark.","zh":"birch trees 是常以淡色或白色樹皮辨認的樹木。"},{"en":"A park with birch trees may look bright in winter when snow covers the ground.","zh":"當雪覆蓋地面，有樺樹的公園在冬天可能顯得明亮。"},{"en":"Because birch trees lose leaves in winter, snow beneath them may reflect more light.","zh":"因為樺樹在冬天落葉，其下方雪地可能反射更多光。"},{"en":"This phrase refers to a specific tree type used in the climate proposal.","zh":"這個片語指氣候方案中使用的特定樹種。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":9},{"front":"white bark","meaning":"白色樹皮","examples":[{"en":"The white bark of birch trees would reflect more sunlight.","zh":"樺樹的白色樹皮會反射更多陽光。"},{"en":"White bark is the pale outer covering of certain trees, especially birch trees.","zh":"white bark 是某些樹木，尤其是樺樹，淡色的外層覆蓋物。"},{"en":"White bark can make trees stand out clearly against dark soil or green leaves.","zh":"白色樹皮可以令樹木在深色泥土或綠葉中顯得突出。"},{"en":"Because white surfaces reflect more light, white bark may reduce heat absorption.","zh":"因為白色表面反射更多光，白色樹皮可能減少吸熱。"},{"en":"This phrase explains why tree colour matters in the proposal.","zh":"這個片語解釋為何樹木顏色在方案中重要。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":9},{"front":"increase the amount of reflected sunlight","meaning":"增加反射陽光量","examples":[{"en":"Birch trees could increase the amount of reflected sunlight.","zh":"樺樹可以增加反射陽光量。"},{"en":"To increase the amount of reflected sunlight means to make more sunlight bounce back from a surface.","zh":"increase the amount of reflected sunlight 指令更多陽光從表面反彈回去。"},{"en":"Painting a roof white can increase the amount of reflected sunlight.","zh":"把屋頂塗成白色可以增加反射陽光量。"},{"en":"If more sunlight is reflected, a surface may stay cooler.","zh":"如果更多陽光被反射，表面可能保持較涼。"},{"en":"This phrase is about reflection, not producing new sunlight.","zh":"這個片語關於反射，而不是產生新陽光。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":9},{"front":"loss of leaves","meaning":"落葉","examples":[{"en":"The loss of leaves in winter would allow snow to reflect radiation.","zh":"冬季落葉會讓雪反射輻射。"},{"en":"Loss of leaves means leaves fall off a plant or tree.","zh":"loss of leaves 指植物或樹木的葉子掉落。"},{"en":"The loss of leaves in autumn lets more sunlight reach the ground.","zh":"秋季落葉讓更多陽光到達地面。"},{"en":"If trees lose leaves, they shade the snow less during winter.","zh":"如果樹木落葉，它們在冬天對雪的遮蔽會較少。"},{"en":"This phrase describes a seasonal change in many trees.","zh":"這個片語描述許多樹木的季節性變化。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":9},{"front":"reflect radiation","meaning":"反射輻射","examples":[{"en":"Snow can reflect radiation when it is not shaded by leaves.","zh":"當雪沒有被樹葉遮蔽時，它可以反射輻射。"},{"en":"To reflect radiation means to send energy, especially sunlight, back from a surface.","zh":"reflect radiation 指把能量，尤其是陽光，從表面反射回去。"},{"en":"White paint can reflect radiation and keep a building cooler.","zh":"白色油漆可以反射輻射，使建築物較涼。"},{"en":"If snow reflects radiation, it absorbs less heat and may melt more slowly.","zh":"如果雪反射輻射，它吸收較少熱力，可能融化得較慢。"},{"en":"This phrase is common in discussions of heat, light, and climate.","zh":"這個片語常見於熱、光和氣候討論。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":9},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, evergreen pines tend to absorb radiation.","zh":"相比之下，常綠松樹往往吸收輻射。"},{"en":"By contrast means compared with the previous point, the next point is different.","zh":"by contrast 指與前一點相比，下一點有所不同。"},{"en":"The city centre is noisy; by contrast, the village is quiet.","zh":"市中心很嘈雜；相比之下，村莊很安靜。"},{"en":"One student learns quickly by listening; by contrast, another needs written notes.","zh":"一名學生透過聆聽學得很快；相比之下，另一名學生需要書面筆記。"},{"en":"This phrase helps show clear difference between two ideas.","zh":"這個片語幫助顯示兩個想法之間的清楚差異。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":9},{"front":"native evergreen pines","meaning":"本地常綠松樹","examples":[{"en":"Native evergreen pines can shade the snow.","zh":"本地常綠松樹可以遮蔽雪。"},{"en":"Native evergreen pines are pine trees naturally found in a region and keeping their leaves all year.","zh":"native evergreen pines 是某地自然生長、全年保持葉子的松樹。"},{"en":"Native evergreen pines may provide homes for birds and insects.","zh":"本地常綠松樹可能為鳥類和昆蟲提供棲息地。"},{"en":"Because they keep needles in winter, native evergreen pines can block sunlight from reaching snow.","zh":"因為它們冬天仍保留針葉，本地常綠松樹可以阻擋陽光照到雪上。"},{"en":"This phrase combines origin and tree type.","zh":"這個片語結合來源和樹木種類。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":10},{"front":"tend to shade","meaning":"往往遮蔽","examples":[{"en":"Evergreen pines tend to shade the snow.","zh":"常綠松樹往往遮蔽雪。"},{"en":"To tend to shade something means usually to block light from reaching it.","zh":"tend to shade something 指通常會阻擋光線到達某物。"},{"en":"Tall buildings tend to shade narrow streets in the afternoon.","zh":"高樓在下午往往遮蔽狹窄街道。"},{"en":"If trees shade snow, the snow may reflect less sunlight.","zh":"如果樹木遮蔽雪，雪可能反射較少陽光。"},{"en":"This phrase describes a common effect, not something that happens every moment.","zh":"這個片語描述常見效果，而不是每一刻都發生。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":10},{"front":"absorb radiation","meaning":"吸收輻射","examples":[{"en":"Evergreen pines absorb radiation instead of reflecting it.","zh":"常綠松樹吸收輻射，而不是反射它。"},{"en":"To absorb radiation means to take in energy such as sunlight rather than bounce it back.","zh":"absorb radiation 指吸收陽光等能量，而不是把它反彈回去。"},{"en":"Dark clothes absorb radiation and feel hotter in strong sunlight.","zh":"深色衣服會吸收輻射，在強烈陽光下感覺更熱。"},{"en":"If a surface absorbs radiation, it may warm up more quickly.","zh":"如果表面吸收輻射，它可能更快升溫。"},{"en":"This phrase is the opposite of reflecting radiation.","zh":"這個片語與反射輻射相反。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":10},{"front":"ice-breaking vessels","meaning":"破冰船","examples":[{"en":"Ice-breaking vessels could break up coastal sea ice.","zh":"破冰船可以打碎沿岸海冰。"},{"en":"Ice-breaking vessels are strong ships designed to cut or break through ice.","zh":"ice-breaking vessels 是設計用來切開或破開冰層的堅固船隻。"},{"en":"Ice-breaking vessels help open routes for other ships in frozen waters.","zh":"破冰船幫助在結冰水域為其他船隻打開航道。"},{"en":"If ice-breaking vessels scatter sea ice, wind and currents may move it elsewhere.","zh":"如果破冰船分散海冰，風和洋流可能把它移到其他地方。"},{"en":"This phrase refers to special ships, not ordinary fishing boats.","zh":"這個片語指特殊船隻，而不是普通漁船。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":10},{"front":"deliberately break up","meaning":"故意打碎","examples":[{"en":"Ships could deliberately break up coastal sea ice.","zh":"船隻可以故意打碎沿岸海冰。"},{"en":"To deliberately break up something means to intentionally split it into smaller pieces.","zh":"deliberately break up something 指有意把某物分裂成較小部分。"},{"en":"Workers may deliberately break up old concrete before rebuilding a pavement.","zh":"工人可能在重建行人路前故意打碎舊混凝土。"},{"en":"If sea ice is deliberately broken up, it may move more easily with currents.","zh":"如果海冰被故意打碎，它可能更容易隨洋流移動。"},{"en":"This phrase stresses that the action is planned, not accidental.","zh":"這個片語強調行動是有計劃的，而不是意外。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":10},{"front":"scatter coastal sea ice","meaning":"分散沿岸海冰","examples":[{"en":"Ice-breaking vessels could scatter coastal sea ice.","zh":"破冰船可以分散沿岸海冰。"},{"en":"To scatter coastal sea ice means to spread pieces of sea ice away from the coast.","zh":"scatter coastal sea ice 指把海岸附近的海冰碎片分散開。"},{"en":"Strong winds can scatter coastal sea ice across open water.","zh":"強風可以把沿岸海冰分散到開闊水面。"},{"en":"If coastal sea ice is scattered, it may freeze together again under the right conditions.","zh":"如果沿岸海冰被分散，在合適條件下可能再次凍結在一起。"},{"en":"This phrase describes spreading ice pieces over a wider area.","zh":"這個片語描述把冰塊碎片散布到更大範圍。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":10},{"front":"Arctic and Antarctic waters","meaning":"北極和南極水域","examples":[{"en":"The method could be used in Arctic and Antarctic waters.","zh":"這種方法可以用於北極和南極水域。"},{"en":"Arctic and Antarctic waters are ocean areas near the North Pole and South Pole.","zh":"Arctic and Antarctic waters 是北極和南極附近的海洋區域。"},{"en":"Ships in Arctic and Antarctic waters must deal with ice, cold, and difficult weather.","zh":"在北極和南極水域航行的船隻必須應對冰、寒冷和惡劣天氣。"},{"en":"Changes in Arctic and Antarctic waters can affect animals, shipping, and global climate.","zh":"北極和南極水域的變化可以影響動物、航運和全球氣候。"},{"en":"This phrase refers to polar seas at both ends of Earth.","zh":"這個片語指地球兩端的極地海域。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":10},{"front":"respective autumns","meaning":"各自的秋季","examples":[{"en":"The ships would work during their respective autumns.","zh":"這些船會在各自的秋季運作。"},{"en":"Respective autumns means the autumn season in each relevant place or hemisphere.","zh":"respective autumns 指每個相關地方或半球的秋季。"},{"en":"Schools in different countries start terms in their respective autumns.","zh":"不同國家的學校在各自的秋季開學。"},{"en":"Arctic and Antarctic regions have autumn at different times, so work would follow their respective autumns.","zh":"北極和南極地區在不同時間進入秋季，所以工作會跟隨各自的秋季。"},{"en":"This phrase matches each place with its own season.","zh":"這個片語把每個地方與自己的季節配對。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":10},{"front":"divert Russian rivers","meaning":"改道俄羅斯河流","examples":[{"en":"Diverting Russian rivers could increase cold-water flow.","zh":"改道俄羅斯河流可以增加冷水流量。"},{"en":"To divert Russian rivers means to change the direction of rivers in Russia.","zh":"divert Russian rivers 指改變俄羅斯河流的方向。"},{"en":"Engineers might divert rivers by building channels, dams, or barriers.","zh":"工程師可能透過建造渠道、水壩或屏障來改道河流。"},{"en":"Diverting rivers can send water to useful areas, but it may harm ecosystems elsewhere.","zh":"改道河流可以把水送到有用地區，但可能傷害其他地方的生態系統。"},{"en":"This phrase describes large-scale control of river direction.","zh":"這個片語描述對河流方向的大規模控制。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":10},{"front":"cold-water flow","meaning":"冷水流量","examples":[{"en":"Diverting rivers could increase cold-water flow into ice-forming areas.","zh":"改道河流可以增加流入結冰區域的冷水流量。"},{"en":"Cold-water flow means the movement of cold water through rivers, seas, or channels.","zh":"cold-water flow 指冷水在河流、海洋或渠道中的流動。"},{"en":"Cold-water flow can help keep some coastal areas cooler.","zh":"冷水流量可以幫助一些沿海地區保持較涼。"},{"en":"If cold-water flow increases in an ice-forming area, more ice may develop.","zh":"如果結冰區域的冷水流量增加，可能形成更多冰。"},{"en":"This phrase focuses on temperature and movement together.","zh":"這個片語同時聚焦於溫度和移動。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":10},{"front":"ice-forming areas","meaning":"結冰區域","examples":[{"en":"Cold water could be directed into ice-forming areas.","zh":"冷水可以被引導到結冰區域。"},{"en":"Ice-forming areas are places where conditions allow water to freeze into ice.","zh":"ice-forming areas 是條件容許水結成冰的地方。"},{"en":"Shallow coastal waters may become ice-forming areas during very cold weather.","zh":"在非常寒冷天氣中，淺水沿海地區可能成為結冰區域。"},{"en":"If warmer water reaches ice-forming areas, ice growth may slow down.","zh":"如果較暖的水到達結冰區域，冰層增長可能放慢。"},{"en":"This phrase describes places where new ice can develop.","zh":"這個片語描述新冰可以形成的地方。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":10},{"front":"slow warming","meaning":"減慢暖化","examples":[{"en":"Increasing cold-water flow could slow warming.","zh":"增加冷水流量可以減慢暖化。"},{"en":"To slow warming means to reduce how quickly temperatures rise.","zh":"slow warming 指減少氣溫上升的速度。"},{"en":"Planting trees in a city can help slow warming by providing shade.","zh":"在城市種樹可以透過提供遮蔭幫助減慢暖化。"},{"en":"If emissions fall, long-term warming may slow over time.","zh":"如果排放下降，長期暖化可能隨時間放慢。"},{"en":"This phrase does not mean stopping warming completely.","zh":"這個片語不表示完全停止暖化。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":11},{"front":"blow the right way","meaning":"風向正確","examples":[{"en":"The scheme would need the wind to blow the right way.","zh":"這個方案需要風向正確。"},{"en":"If the wind blows the right way, it moves in the direction needed for a plan to work.","zh":"blow the right way 指風朝計劃所需的方向吹。"},{"en":"Sailors need the wind to blow the right way to move quickly toward their destination.","zh":"水手需要風向正確，才能快速前往目的地。"},{"en":"If smoke is released, wind must blow the right way to keep it away from homes.","zh":"如果釋放煙霧，風必須吹向正確方向，使它遠離民居。"},{"en":"This phrase shows that success depends on wind direction.","zh":"這個片語顯示成功取決於風向。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":11},{"front":"in the right conditions","meaning":"在合適條件下","examples":[{"en":"In the right conditions, free-floating ice could enhance ice growth.","zh":"在合適條件下，自由漂浮的冰可以促進冰層增長。"},{"en":"In the right conditions means when the situation, weather, or environment is suitable.","zh":"in the right conditions 指情況、天氣或環境合適時。"},{"en":"Seeds grow quickly in the right conditions of water, sunlight, and soil.","zh":"在有水、陽光和泥土的合適條件下，種子會快速生長。"},{"en":"A plan may succeed in the right conditions but fail when circumstances change.","zh":"一個計劃可能在合適條件下成功，但在情況改變時失敗。"},{"en":"This phrase reminds us that success depends on context.","zh":"這個片語提醒我們成功取決於語境。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":11},{"front":"let ice float free","meaning":"讓冰自由漂浮","examples":[{"en":"Letting ice float free could enhance ice growth.","zh":"讓冰自由漂浮可以促進冰層增長。"},{"en":"To let ice float free means to allow ice to move naturally on water without being fixed in place.","zh":"let ice float free 指容許冰在水面自然移動，而不是固定在原地。"},{"en":"If ice is allowed to float free, currents may carry it to colder areas.","zh":"如果讓冰自由漂浮，洋流可能把它帶到較冷地區。"},{"en":"Letting objects float free can be risky if they drift into shipping lanes.","zh":"讓物件自由漂浮可能有風險，因為它們可能漂入航道。"},{"en":"This phrase describes allowing movement rather than controlling it tightly.","zh":"這個片語描述容許移動，而不是嚴密控制。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":11},{"front":"head north","meaning":"向北移動","examples":[{"en":"The ice could head north and help build more ice.","zh":"冰可以向北移動，並幫助形成更多冰。"},{"en":"To head north means to move or travel toward the north.","zh":"head north 指朝北方移動或旅行。"},{"en":"Families may head north during summer to find cooler weather.","zh":"家庭可能在夏天向北移動，以尋找較涼天氣。"},{"en":"If ice heads north into colder water, it may freeze together with other ice.","zh":"如果冰向北移動到較冷水域，它可能與其他冰重新結合。"},{"en":"This phrase describes direction in simple everyday English.","zh":"這個片語用簡單日常英語描述方向。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":11},{"front":"enhance ice growth","meaning":"促進冰層增長","examples":[{"en":"Letting ice move north would enhance ice growth.","zh":"讓冰向北移動會促進冰層增長。"},{"en":"To enhance ice growth means to increase or improve the formation of ice.","zh":"enhance ice growth 指增加或改善冰的形成。"},{"en":"Colder water can enhance ice growth in polar seas.","zh":"較冷的水可以促進極地海域的冰層增長。"},{"en":"If ice growth is enhanced, more sunlight may be reflected from the surface.","zh":"如果冰層增長被促進，更多陽光可能從表面反射。"},{"en":"This phrase means strengthening a natural process, not creating ice instantly.","zh":"這個片語指加強自然過程，而不是即時製造冰。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":11},{"front":"be implemented","meaning":"被實施","examples":[{"en":"It is unclear whether these geoengineering ideas will be implemented.","zh":"這些地球工程構想是否會被實施仍不清楚。"},{"en":"If a plan is implemented, it is put into action in the real world.","zh":"如果一個計劃 is implemented，意思是它在現實中被付諸實行。"},{"en":"A school rule is implemented when teachers begin using it in classrooms.","zh":"當老師開始在課室使用某校規，它就被實施。"},{"en":"A plan may look good on paper but cause problems when implemented.","zh":"一個計劃紙面上可能很好，但被實施時造成問題。"},{"en":"This phrase means moving from proposal to actual practice.","zh":"這個片語指由提案進入實際做法。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":11},{"front":"main counterarguments","meaning":"主要反對論點","examples":[{"en":"The main counterarguments concern emissions and side effects.","zh":"主要反對論點涉及排放和副作用。"},{"en":"Main counterarguments are the strongest reasons given against an idea.","zh":"main counterarguments 是反對某想法的最有力理由。"},{"en":"In a school debate, the main counterarguments should answer the other side’s key claims.","zh":"在學校辯論中，主要反對論點應回應對方的核心主張。"},{"en":"If the main counterarguments are ignored, a proposal may seem stronger than it really is.","zh":"如果主要反對論點被忽視，提案可能看起來比實際更強。"},{"en":"This phrase is useful when discussing disagreement in a balanced way.","zh":"這個片語適合用於平衡地討論分歧。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":11},{"front":"geoengineering is a cop-out","meaning":"地球工程是逃避責任的做法","examples":[{"en":"Some critics argue that geoengineering is a cop-out.","zh":"一些批評者認為地球工程是逃避責任的做法。"},{"en":"Geoengineering is a cop-out means it is seen as an easy escape from the harder responsibility of cutting emissions.","zh":"geoengineering is a cop-out 指它被視為逃避削減排放這項更艱難責任的輕鬆出路。"},{"en":"A student who copies homework instead of studying is taking a cop-out.","zh":"學生不溫習而抄功課，就是在逃避責任。"},{"en":"Critics fear geoengineering may let people avoid changing wasteful habits.","zh":"批評者擔心地球工程可能讓人避免改變浪費的習慣。"},{"en":"This phrase is informal and negative because it suggests avoiding real responsibility.","zh":"這個片語較口語且負面，因為它暗示逃避真正責任。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":11},{"front":"continue living as we do","meaning":"繼續現有生活方式","examples":[{"en":"Geoengineering may allow us to continue living as we do.","zh":"地球工程可能容許我們繼續現有生活方式。"},{"en":"To continue living as we do means to keep the same habits and lifestyle without major change.","zh":"continue living as we do 指保持相同習慣和生活方式，不作重大改變。"},{"en":"A family may continue living as they do if prices stay low and income remains stable.","zh":"如果物價維持低、收入穩定，家庭可能繼續現有生活方式。"},{"en":"If technology hides environmental damage, people may continue living as they do without reducing waste.","zh":"如果科技掩蓋環境破壞，人們可能繼續現有生活方式而不減少浪費。"},{"en":"This phrase often suggests resistance to difficult lifestyle changes.","zh":"這個片語常暗示抗拒困難的生活方式改變。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":11},{"front":"rather than reducing","meaning":"而不是減少","examples":[{"en":"Critics say geoengineering distracts us from reducing emissions.","zh":"批評者說地球工程令我們分心，而不是減少排放。"},{"en":"Rather than reducing means instead of making something smaller or lower.","zh":"rather than reducing 指不是令某物變少或降低。"},{"en":"Rather than reducing screen time, some students simply move from phones to laptops.","zh":"一些學生不是減少螢幕時間，而只是從手機轉到手提電腦。"},{"en":"A company may talk about recycling rather than reducing unnecessary packaging.","zh":"公司可能談論回收，而不是減少不必要包裝。"},{"en":"This phrase shows that the real reduction is not happening.","zh":"這個片語顯示真正的減少並沒有發生。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":11},{"front":"even if a scheme works","meaning":"即使方案奏效","examples":[{"en":"Even if a scheme works, its side effects may be serious.","zh":"即使方案奏效，其副作用也可能嚴重。"},{"en":"Even if a scheme works means although a plan achieves its main goal.","zh":"even if a scheme works 指雖然某計劃達到主要目標。"},{"en":"Even if a medicine works, patients must watch for side effects.","zh":"即使藥物奏效，病人仍必須留意副作用。"},{"en":"Even if a new timetable works for teachers, it may be difficult for parents.","zh":"即使新時間表對老師奏效，對家長也可能很困難。"},{"en":"This phrase warns that success in one area does not remove all risks.","zh":"這個片語警告，一方面成功並不消除所有風險。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":12},{"front":"side effects","meaning":"副作用","examples":[{"en":"The side effects of geoengineering may be unpredictable.","zh":"地球工程的副作用可能難以預測。"},{"en":"Side effects are unwanted results that happen in addition to the main intended effect.","zh":"side effects 是除主要預期效果外發生的不想要結果。"},{"en":"Some medicines reduce pain but have side effects such as sleepiness.","zh":"有些藥物能減痛，但有嗜睡等副作用。"},{"en":"A new road may improve traffic but create side effects like noise and pollution.","zh":"新道路可能改善交通，但產生噪音和污染等副作用。"},{"en":"This phrase is useful when a solution may also cause problems.","zh":"當解決方法也可能造成問題時，這個片語很有用。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":12},{"front":"outweigh its advantages","meaning":"大於其好處","examples":[{"en":"The side effects may outweigh the advantages.","zh":"副作用可能大於其好處。"},{"en":"To outweigh its advantages means to be more serious or important than the benefits.","zh":"outweigh its advantages 指比好處更嚴重或更重要。"},{"en":"A cheap flat is not worth renting if safety problems outweigh its advantages.","zh":"如果安全問題大於其好處，便不值得租便宜單位。"},{"en":"If a medicine’s risks outweigh its advantages, doctors may choose another treatment.","zh":"如果藥物風險大於其好處，醫生可能選擇另一種治療。"},{"en":"This phrase helps compare costs and benefits.","zh":"這個片語幫助比較成本與好處。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":12},{"front":"daunting prospect","meaning":"令人卻步的前景","examples":[{"en":"Maintaining any geoengineering scheme is a daunting prospect.","zh":"維持任何地球工程方案都是令人卻步的前景。"},{"en":"A daunting prospect is a future task or situation that feels difficult and worrying.","zh":"daunting prospect 是令人覺得困難和擔心的未來任務或情況。"},{"en":"Moving to a new country alone can be a daunting prospect.","zh":"獨自搬到新國家可以是令人卻步的前景。"},{"en":"Repairing an old building with limited money is a daunting prospect for a small school.","zh":"用有限金錢維修舊建築，對小學校來說是令人卻步的前景。"},{"en":"This phrase suggests fear because the challenge is large.","zh":"這個片語暗示因挑戰龐大而感到害怕。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":12},{"front":"maintaining and repairing","meaning":"維護和修理","examples":[{"en":"Large schemes would require maintaining and repairing.","zh":"大型方案需要維護和修理。"},{"en":"Maintaining and repairing means keeping something working and fixing it when it breaks.","zh":"maintaining and repairing 指保持某物運作，並在損壞時修復它。"},{"en":"A lift in a housing estate needs regular maintaining and repairing to stay safe.","zh":"屋苑升降機需要定期維護和修理，以保持安全。"},{"en":"If a system is not maintained and repaired, small faults can become dangerous.","zh":"如果系統沒有被維護和修理，小故障可以變得危險。"},{"en":"This phrase focuses on long-term upkeep, not just building something once.","zh":"這個片語聚焦於長期保養，而不是只建造一次。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":12},{"front":"consequences of technical failure","meaning":"技術故障的後果","examples":[{"en":"Geoengineering could have serious consequences if technical failure occurs.","zh":"如果發生技術故障，地球工程可能有嚴重後果。"},{"en":"Consequences of technical failure are the problems caused when a machine, system, or technology stops working properly.","zh":"consequences of technical failure 是機器、系統或技術停止正常運作時造成的問題。"},{"en":"The consequences of technical failure in a hospital can be life-threatening.","zh":"醫院技術故障的後果可以危及生命。"},{"en":"If a traffic-light system fails, the consequences may include accidents and delays.","zh":"如果交通燈系統故障，後果可能包括意外和延誤。"},{"en":"This phrase warns that technology-dependent plans can fail dangerously.","zh":"這個片語警告依賴技術的計劃可能危險地失效。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":12},{"front":"technical failure","meaning":"技術故障","examples":[{"en":"Technical failure could cause rapid climate changes.","zh":"技術故障可能造成快速氣候變化。"},{"en":"Technical failure means a machine, system, or technology does not work as intended.","zh":"technical failure 指機器、系統或技術沒有按預期運作。"},{"en":"A technical failure during an online exam can stop students from submitting answers.","zh":"網上考試期間的技術故障可以阻止學生提交答案。"},{"en":"If a plane has technical failure, the flight may be delayed for safety checks.","zh":"如果飛機有技術故障，航班可能因安全檢查而延誤。"},{"en":"This phrase focuses on equipment or system problems, not human disagreement.","zh":"這個片語聚焦於設備或系統問題，而不是人與人之間的分歧。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":12},{"front":"on a given day","meaning":"在某一天","examples":[{"en":"If geoengineering ended on a given day, the climate might change quickly.","zh":"如果地球工程在某一天結束，氣候可能迅速改變。"},{"en":"On a given day means on one particular day that is being considered.","zh":"on a given day 指在正在考慮的某一特定日子。"},{"en":"On a given day, a busy clinic may see hundreds of patients.","zh":"在某一天，繁忙診所可能接待數百名病人。"},{"en":"If a bridge closes on a given day, traffic nearby may become much worse.","zh":"如果橋樑在某一天關閉，附近交通可能變得差很多。"},{"en":"This phrase is useful when imagining a specific point in time.","zh":"這個片語適合用於想像某個特定時間點。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":12},{"front":"pre-engineered condition","meaning":"工程干預前的狀態","examples":[{"en":"The planet could return to its pre-engineered condition.","zh":"地球可能回到工程干預前的狀態。"},{"en":"Pre-engineered condition means the state before human engineering changed the system.","zh":"pre-engineered condition 指人類工程改變系統之前的狀態。"},{"en":"A river’s pre-engineered condition may refer to how it flowed before dams were built.","zh":"河流的工程干預前狀態可能指建水壩前它如何流動。"},{"en":"If a project stops suddenly, the environment may move back toward its pre-engineered condition.","zh":"如果項目突然停止，環境可能向工程干預前的狀態回復。"},{"en":"This phrase compares the world before and after technical intervention.","zh":"這個片語比較技術干預前後的世界。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":12},{"front":"within 10 to 20 years","meaning":"在10至20年內","examples":[{"en":"The climate might return to its former state within 10 to 20 years.","zh":"氣候可能在10至20年內回到之前狀態。"},{"en":"Within 10 to 20 years means before ten to twenty years have passed.","zh":"within 10 to 20 years 指在十至二十年過去之前。"},{"en":"A city may need a new railway within 10 to 20 years if its population grows quickly.","zh":"如果人口快速增長，城市可能在10至20年內需要新鐵路。"},{"en":"If sea levels rise, some coastal defences may need rebuilding within 10 to 20 years.","zh":"如果海平面上升，一些海岸防禦設施可能在10至20年內需要重建。"},{"en":"This phrase gives a medium-term time limit.","zh":"這個片語給出中期時間限制。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":12},{"front":"something to worry about","meaning":"值得擔心的事","examples":[{"en":"The rapid return to earlier conditions is something to worry about.","zh":"快速回到早前情況是值得擔心的事。"},{"en":"Something to worry about is a matter that may cause danger, harm, or serious concern.","zh":"something to worry about 是可能造成危險、傷害或嚴重憂慮的事情。"},{"en":"A crack in a bridge is something to worry about if it grows wider.","zh":"如果橋上的裂縫變寬，那就是值得擔心的事。"},{"en":"A child’s repeated headaches are something to worry about if they do not stop.","zh":"如果孩子反覆頭痛不停，那是值得擔心的事。"},{"en":"This phrase signals that a problem should not be ignored.","zh":"這個片語表示問題不應被忽視。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":12},{"front":"employ a strategy","meaning":"採用一種策略","examples":[{"en":"Geoengineering might be a strategy to employ during a transition.","zh":"地球工程可能是在過渡期間採用的一種策略。"},{"en":"To employ a strategy means to use a planned method to deal with a problem.","zh":"employ a strategy 指使用有計劃的方法來處理問題。"},{"en":"A student may employ a strategy of reviewing difficult words every morning.","zh":"學生可能採用每天早上複習困難詞語的策略。"},{"en":"Businesses employ different strategies when sales fall, such as discounts or better service.","zh":"當銷售下降，企業會採用不同策略，例如折扣或改善服務。"},{"en":"This phrase is more formal than simply use a plan.","zh":"這個片語比 simply use a plan 更正式。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":13},{"front":"manage the transition to","meaning":"管理向……的過渡","examples":[{"en":"Society must manage the transition to a non-fossil-fuel economy.","zh":"社會必須管理向非化石燃料經濟的過渡。"},{"en":"To manage the transition to something means to control the change from one system to another carefully.","zh":"manage the transition to something 指謹慎控制由一個系統轉向另一個系統的變化。"},{"en":"Schools must manage the transition to online learning by helping teachers and students adapt.","zh":"學校必須透過幫助老師和學生適應，管理向網上學習的過渡。"},{"en":"If a company manages the transition badly, workers and customers may become confused.","zh":"如果公司管理過渡不善，員工和顧客可能感到混亂。"},{"en":"This phrase stresses planning during change.","zh":"這個片語強調變化期間的規劃。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":13},{"front":"non-fossil-fuel economy","meaning":"非化石燃料經濟","examples":[{"en":"Geoengineering may only help during the move to a non-fossil-fuel economy.","zh":"地球工程可能只在邁向非化石燃料經濟期間有幫助。"},{"en":"A non-fossil-fuel economy is an economy that does not depend mainly on coal, oil, or gas.","zh":"non-fossil-fuel economy 是不主要依賴煤、石油或天然氣的經濟。"},{"en":"Solar power, wind energy, and electric transport can support a non-fossil-fuel economy.","zh":"太陽能、風能和電動交通可以支援非化石燃料經濟。"},{"en":"Moving to a non-fossil-fuel economy may create new jobs but also disrupt old industries.","zh":"邁向非化石燃料經濟可能創造新工作，但也衝擊舊產業。"},{"en":"This phrase describes a major change in how society produces and uses energy.","zh":"這個片語描述社會生產和使用能源方式的重大變化。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":13},{"front":"the risk with","meaning":"……的風險","examples":[{"en":"The risk with geoengineering projects is that they can overshoot.","zh":"地球工程項目的風險是它們可能矯枉過正。"},{"en":"The risk with something means the danger or possible problem connected with it.","zh":"the risk with something 指與某事相關的危險或可能問題。"},{"en":"The risk with cheap repairs is that the same fault may return soon.","zh":"便宜維修的風險是同一故障可能很快再出現。"},{"en":"The risk with online shopping is that photos may not match the real product.","zh":"網上購物的風險是照片可能與實物不符。"},{"en":"This phrase introduces the main concern about an idea or action.","zh":"這個片語引入某想法或行動的主要憂慮。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":13},{"front":"overshoot","meaning":"超出目標；矯枉過正","examples":[{"en":"Geoengineering may overshoot and cool some regions too much.","zh":"地球工程可能超出目標，令某些地區降溫過度。"},{"en":"To overshoot means to go beyond the intended target or level.","zh":"overshoot 指超過原定目標或水平。"},{"en":"A driver may overshoot the parking space and need to reverse.","zh":"司機可能駛過泊車位，需要倒車。"},{"en":"If a medicine dose overshoots the safe level, it can cause harm.","zh":"如果藥物劑量超出安全水平，可能造成傷害。"},{"en":"This word warns that doing too much can be as dangerous as doing too little.","zh":"這個詞警告做得太多可能和做得太少一樣危險。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":13},{"front":"pre-industrial levels","meaning":"工業化前水平","examples":[{"en":"Geoengineering may bring global temperatures back to pre-industrial levels.","zh":"地球工程可能把全球氣溫帶回工業化前水平。"},{"en":"Pre-industrial levels refer to conditions before large-scale industrial activity changed the climate.","zh":"pre-industrial levels 指大規模工業活動改變氣候之前的情況。"},{"en":"Scientists compare today’s temperatures with pre-industrial levels to measure warming.","zh":"科學家把今天的氣溫與工業化前水平比較，以量度暖化。"},{"en":"Returning to pre-industrial levels would not necessarily affect every region equally.","zh":"回到工業化前水平不一定會平等影響每個地區。"},{"en":"This phrase gives a historical baseline for climate discussion.","zh":"這個片語為氣候討論提供歷史基準。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":13},{"front":"the poles","meaning":"兩極","examples":[{"en":"The poles could still be warmer than they should be.","zh":"兩極仍可能比應有水平更暖。"},{"en":"The poles are the areas around the North Pole and South Pole.","zh":"the poles 是北極和南極周邊地區。"},{"en":"The poles contain large amounts of ice and influence global sea levels.","zh":"兩極含有大量冰，並影響全球海平面。"},{"en":"If the poles warm quickly, polar animals and coastal cities may be affected.","zh":"如果兩極快速變暖，極地動物和沿海城市可能受影響。"},{"en":"This phrase refers to Earth’s extreme northern and southern regions.","zh":"這個片語指地球最北和最南的地區。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":13},{"front":"the tropics","meaning":"熱帶地區","examples":[{"en":"The tropics could become cooler than before industrialisation.","zh":"熱帶地區可能變得比工業化之前更冷。"},{"en":"The tropics are the warm regions of Earth near the equator.","zh":"the tropics 是地球赤道附近的溫暖地區。"},{"en":"Many tropical countries have hot weather, heavy rainfall, and rich biodiversity.","zh":"許多熱帶國家天氣炎熱、降雨量大，並有豐富生物多樣性。"},{"en":"If the tropics become too cool or dry, farming and ecosystems may change.","zh":"如果熱帶地區變得太冷或太乾，農業和生態系統可能改變。"},{"en":"This phrase refers to a broad climate zone, not one country.","zh":"這個片語指廣闊氣候帶，而不是一個國家。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":13},{"front":"before industrialisation","meaning":"工業化之前","examples":[{"en":"Temperatures may not return evenly to conditions before industrialisation.","zh":"氣溫未必平均回到工業化之前的情況。"},{"en":"Before industrialisation means before societies widely used factories, machines, and fossil fuels.","zh":"before industrialisation 指社會廣泛使用工廠、機器和化石燃料之前。"},{"en":"Air pollution was generally lower before industrialisation in many places.","zh":"在許多地方，工業化之前空氣污染通常較低。"},{"en":"Climate comparisons often use conditions before industrialisation as a baseline.","zh":"氣候比較常使用工業化之前的情況作基準。"},{"en":"This phrase points to a period before modern industrial growth.","zh":"這個片語指現代工業增長之前的時期。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":13},{"front":"principal reason","meaning":"主要原因","examples":[{"en":"The principal reason for considering geoengineering is political uncertainty.","zh":"考慮地球工程的主要原因是政治不確定性。"},{"en":"Principal reason means the main or most important reason.","zh":"principal reason 指主要或最重要原因。"},{"en":"The principal reason for closing the road was public safety.","zh":"封路的主要原因是公共安全。"},{"en":"A student’s principal reason for choosing a course may be future career plans.","zh":"學生選擇課程的主要原因可能是未來職業計劃。"},{"en":"This phrase identifies the strongest cause among several possibilities.","zh":"這個片語指出幾個可能原因中最強的原因。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":13},{"front":"mainstream scientific community","meaning":"主流科學界","examples":[{"en":"The mainstream scientific community is willing to consider geoengineering.","zh":"主流科學界願意考慮地球工程。"},{"en":"The mainstream scientific community means the majority of recognised scientists and research institutions in a field.","zh":"mainstream scientific community 指某領域中大多數被認可的科學家和研究機構。"},{"en":"When the mainstream scientific community agrees on a risk, governments usually pay attention.","zh":"當主流科學界同意某風險存在，政府通常會注意。"},{"en":"An idea outside the mainstream scientific community may still be studied, but it needs strong evidence.","zh":"主流科學界以外的想法仍可被研究，但需要有力證據。"},{"en":"This phrase refers to established scientific opinion, not one individual scientist.","zh":"這個片語指既定科學意見，而不是單一科學家。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":13},{"front":"countenance geoengineering","meaning":"接受／考慮地球工程","examples":[{"en":"Some scientists countenance geoengineering because emissions cuts seem unlikely.","zh":"一些科學家因減排似乎不太可能而接受或考慮地球工程。"},{"en":"To countenance geoengineering means to accept, consider, or tolerate the idea of geoengineering.","zh":"countenance geoengineering 指接受、考慮或容許地球工程這個想法。"},{"en":"A school may countenance online lessons if weather makes travel unsafe.","zh":"如果天氣令出行不安全，學校可能接受網上課堂。"},{"en":"Doctors may countenance a risky treatment only when safer options have failed.","zh":"只有在較安全選項失敗時，醫生才可能考慮有風險治療。"},{"en":"This word suggests reluctant acceptance, not enthusiastic support.","zh":"這個詞暗示勉強接受，而不是熱情支持。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":14},{"front":"have little faith in","meaning":"對……缺乏信心","examples":[{"en":"Many researchers have little faith in politicians’ ability to cut emissions.","zh":"許多研究人員對政客削減排放的能力缺乏信心。"},{"en":"To have little faith in someone or something means to have low confidence in them.","zh":"have little faith in someone or something 指對某人或某事信心很低。"},{"en":"Customers may have little faith in a company after repeated service failures.","zh":"經過反覆服務失誤後，顧客可能對公司缺乏信心。"},{"en":"If students have little faith in an exam system, they may feel the results are unfair.","zh":"如果學生對考試制度缺乏信心，他們可能覺得結果不公平。"},{"en":"This phrase shows doubt about whether someone can succeed.","zh":"這個片語顯示對某人能否成功有所懷疑。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":14},{"front":"agree on","meaning":"就……達成共識","examples":[{"en":"Politicians may struggle to agree on necessary carbon cuts.","zh":"政客可能難以就必要減碳措施達成共識。"},{"en":"To agree on something means to reach the same decision or opinion about it.","zh":"agree on something 指就某事達成相同決定或意見。"},{"en":"A family must agree on a budget before planning a holiday.","zh":"家庭在計劃旅行前必須就預算達成共識。"},{"en":"If teachers cannot agree on exam standards, marking may become inconsistent.","zh":"如果老師不能就考試標準達成共識，評分可能變得不一致。"},{"en":"This phrase is used when people need a shared decision.","zh":"這個片語用於人們需要共同決定時。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":14},{"front":"introduce carbon cuts","meaning":"推出減碳措施","examples":[{"en":"Governments may fail to introduce the necessary carbon cuts.","zh":"政府可能未能推出必要減碳措施。"},{"en":"To introduce carbon cuts means to bring in policies or actions that reduce carbon emissions.","zh":"introduce carbon cuts 指引入減少碳排放的政策或行動。"},{"en":"A city may introduce carbon cuts by limiting dirty vehicles and improving public transport.","zh":"城市可能透過限制高污染車輛和改善公共交通來推出減碳措施。"},{"en":"If governments delay carbon cuts, emissions may continue to rise.","zh":"如果政府延遲減碳措施，排放可能繼續上升。"},{"en":"This phrase is about starting real reduction measures, not only discussing them.","zh":"這個片語關於開始真正減排措施，而不只是討論。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":14},{"front":"leading conservation organisations","meaning":"主要保育組織","examples":[{"en":"Even leading conservation organisations believe geoengineering is worth exploring.","zh":"甚至主要保育組織也認為地球工程值得探索。"},{"en":"Leading conservation organisations are important groups that work to protect nature, wildlife, and ecosystems.","zh":"leading conservation organisations 是致力保護自然、野生動物和生態系統的重要團體。"},{"en":"Leading conservation organisations may advise governments on forests, oceans, and endangered species.","zh":"主要保育組織可能就森林、海洋和瀕危物種向政府提供建議。"},{"en":"When leading conservation organisations support research, the topic may gain public attention.","zh":"當主要保育組織支持研究，該議題可能獲得公眾關注。"},{"en":"This phrase refers to influential environmental groups.","zh":"這個片語指有影響力的環境團體。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":14},{"front":"worth exploring","meaning":"值得探索","examples":[{"en":"The subject of geoengineering is worth exploring.","zh":"地球工程這個題目值得探索。"},{"en":"Worth exploring means deserving careful study, even if it may not finally be accepted.","zh":"worth exploring 指值得仔細研究，即使最終未必被接受。"},{"en":"A new teaching method is worth exploring if students are not improving.","zh":"如果學生沒有進步，新教學方法值得探索。"},{"en":"A business idea may be worth exploring before anyone invests money in it.","zh":"商業想法在有人投資前可能值得探索。"},{"en":"This phrase suggests open-minded investigation, not automatic approval.","zh":"這個片語暗示開放地調查，而不是自動批准。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":14},{"front":"climate-change adviser","meaning":"氣候變化顧問","examples":[{"en":"Martin Sommerkorn is a climate-change adviser.","zh":"Martin Sommerkorn 是一位氣候變化顧問。"},{"en":"A climate-change adviser is someone who gives expert guidance on climate risks and responses.","zh":"climate-change adviser 是就氣候風險和應對方法提供專業指引的人。"},{"en":"A government may hire a climate-change adviser to plan flood protection.","zh":"政府可能聘請氣候變化顧問來規劃防洪措施。"},{"en":"Companies consult climate-change advisers when they want to reduce emissions.","zh":"公司希望減少排放時，會諮詢氣候變化顧問。"},{"en":"This phrase describes a professional role connected with climate policy and science.","zh":"這個片語描述與氣候政策和科學相關的專業角色。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":14},{"front":"human-induced climate change","meaning":"人為引致的氣候變化","examples":[{"en":"Human-induced climate change has forced scientists to consider geoengineering.","zh":"人為引致的氣候變化迫使科學家考慮地球工程。"},{"en":"Human-induced climate change is climate change caused mainly by human activities.","zh":"human-induced climate change 是主要由人類活動造成的氣候變化。"},{"en":"Burning fossil fuels and cutting forests contribute to human-induced climate change.","zh":"燃燒化石燃料和砍伐森林會導致人為引致的氣候變化。"},{"en":"Human-induced climate change can increase extreme weather and pressure on food supplies.","zh":"人為引致的氣候變化可以增加極端天氣和糧食供應壓力。"},{"en":"This phrase separates human causes from natural climate variation.","zh":"這個片語把人為原因與自然氣候變化分開。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":14},{"front":"bring humanity to a point where","meaning":"使人類走到……的地步","examples":[{"en":"Climate change has brought humanity to a point where all options must be considered.","zh":"氣候變化已使人類走到必須考慮所有選項的地步。"},{"en":"To bring humanity to a point where means to make the human situation so serious that a certain response becomes necessary.","zh":"bring humanity to a point where 指令人類處境變得如此嚴重，以致某種回應變得必要。"},{"en":"A health crisis can bring society to a point where strict measures are needed.","zh":"健康危機可以使社會走到需要嚴格措施的地步。"},{"en":"Severe water shortages may bring a city to a point where rationing becomes unavoidable.","zh":"嚴重缺水可能使城市走到配給變得無可避免的地步。"},{"en":"This phrase shows that pressure has reached a critical stage.","zh":"這個片語顯示壓力已達到關鍵階段。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":14},{"front":"exclude careful consideration of","meaning":"排除對……的審慎考慮","examples":[{"en":"Scientists should not exclude careful consideration of geoengineering.","zh":"科學家不應排除對地球工程的審慎考慮。"},{"en":"To exclude careful consideration of something means to refuse to study or think about it seriously.","zh":"exclude careful consideration of something 指拒絕認真研究或思考某事。"},{"en":"A school should not exclude careful consideration of online support for sick students.","zh":"學校不應排除對病童網上支援的審慎考慮。"},{"en":"If leaders exclude careful consideration of risks, they may make poor decisions.","zh":"如果領袖排除對風險的審慎考慮，他們可能作出差劣決定。"},{"en":"This phrase argues for serious thinking, not blind acceptance.","zh":"這個片語主張認真思考，而不是盲目接受。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":14},{"front":"potential drawbacks","meaning":"潛在缺點","examples":[{"en":"Geoengineering has potential drawbacks.","zh":"地球工程有潛在缺點。"},{"en":"Potential drawbacks are possible disadvantages or problems that may appear later.","zh":"potential drawbacks 是日後可能出現的缺點或問題。"},{"en":"Online learning has potential drawbacks, such as weaker concentration and less social contact.","zh":"網上學習有潛在缺點，例如專注力較弱和社交接觸較少。"},{"en":"A cheap product may have potential drawbacks if it breaks easily.","zh":"如果便宜產品容易壞，它可能有潛在缺點。"},{"en":"This phrase helps discuss risk before a decision is made.","zh":"這個片語幫助在作決定前討論風險。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":14},{"front":"over the coming years","meaning":"在未來數年","examples":[{"en":"Over the coming years, climate research may reveal greater risks.","zh":"在未來數年，氣候研究可能揭示更大風險。"},{"en":"Over the coming years means during the next several years.","zh":"over the coming years 指在接下來幾年期間。"},{"en":"Over the coming years, many schools may use more digital tools.","zh":"在未來數年，許多學校可能使用更多數碼工具。"},{"en":"A city’s population may grow quickly over the coming years.","zh":"城市人口可能在未來數年迅速增長。"},{"en":"This phrase points to gradual future developments.","zh":"這個片語指向逐漸出現的未來發展。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":15},{"front":"climate sensitivity","meaning":"氣候敏感度","examples":[{"en":"The planet’s climate sensitivity may be greater than expected.","zh":"地球的氣候敏感度可能比預期更高。"},{"en":"Climate sensitivity means how strongly Earth’s temperature responds to changes such as rising carbon dioxide.","zh":"climate sensitivity 指地球氣溫對二氧化碳上升等變化的反應強度。"},{"en":"If climate sensitivity is high, small changes in gases may cause larger warming.","zh":"如果氣候敏感度高，氣體的小變化可能造成更大暖化。"},{"en":"Scientists study climate sensitivity to estimate future temperature rise.","zh":"科學家研究氣候敏感度，以估算未來氣溫上升。"},{"en":"This phrase is technical but central to climate predictions.","zh":"這個片語較技術性，但對氣候預測很核心。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":15},{"front":"not unrealistic","meaning":"並非不切實際","examples":[{"en":"Greater climate sensitivity is not unrealistic.","zh":"較高氣候敏感度並非不切實際。"},{"en":"Not unrealistic means possible or reasonable, even if not certain.","zh":"not unrealistic 指可能或合理，即使未必確定。"},{"en":"It is not unrealistic for a beginner to improve quickly with daily practice.","zh":"初學者透過每日練習快速進步並非不切實際。"},{"en":"A small company growing fast is not unrealistic if demand is strong.","zh":"如果需求強，小公司快速增長並非不切實際。"},{"en":"This phrase is cautious and less strong than saying something is definitely true.","zh":"這個片語語氣謹慎，比說某事絕對正確較弱。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":15},{"front":"be best served by","meaning":"最有利於……","examples":[{"en":"Humanity may be best served by thinking about geoengineering early.","zh":"及早思考地球工程可能最有利於人類。"},{"en":"To be best served by something means to benefit most from that action or approach.","zh":"be best served by something 指從某行動或方法中得到最大好處。"},{"en":"Students are best served by clear feedback rather than vague praise.","zh":"清晰回饋而不是空泛稱讚最有利於學生。"},{"en":"A patient may be best served by early treatment before the illness worsens.","zh":"病人在病情惡化前及早治療，可能最有利於他。"},{"en":"This phrase suggests the most helpful choice in a situation.","zh":"這個片語暗示某情況中最有幫助的選擇。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":15},{"front":"start from scratch","meaning":"從零開始","examples":[{"en":"Scientists may not want to start their thinking from scratch later.","zh":"科學家可能不希望日後才從零開始思考。"},{"en":"To start from scratch means to begin again from the very beginning with nothing prepared.","zh":"start from scratch 指在沒有準備的情況下從最開始重新開始。"},{"en":"If a student loses all notes, she may have to start from scratch before the exam.","zh":"如果學生遺失所有筆記，她可能要在考試前從零開始。"},{"en":"Starting from scratch takes longer than improving work that already exists.","zh":"從零開始比改善已有工作花更長時間。"},{"en":"This phrase stresses the absence of previous preparation.","zh":"這個片語強調沒有先前準備。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":15},{"front":"contains the following information","meaning":"包含以下資料","examples":[{"en":"Students identify which paragraph contains the following information.","zh":"學生識別哪一段包含以下資料。"},{"en":"Contains the following information means includes the details listed after the instruction.","zh":"contains the following information 指包括指示後列出的細節。"},{"en":"In a reading test, students look for the paragraph that contains the following information.","zh":"在閱讀測驗中，學生尋找包含以下資料的段落。"},{"en":"A paragraph may contain the following information even if it uses different words.","zh":"即使用字不同，某段仍可能包含以下資料。"},{"en":"This phrase is common in matching-information questions.","zh":"這個片語常見於配對資料題。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":15},{"front":"may use any letter more than once","meaning":"可使用任何字母多於一次","examples":[{"en":"Students may use any letter more than once.","zh":"學生可使用任何字母多於一次。"},{"en":"May use any letter more than once means the same answer choice can be selected repeatedly.","zh":"may use any letter more than once 指同一答案選項可以重複選擇。"},{"en":"In a matching task, one paragraph may answer several questions, so students may use its letter more than once.","zh":"在配對題中，一段可能回答幾條問題，所以學生可以多於一次使用其字母。"},{"en":"If B contains two pieces of information, students may write B for two answers.","zh":"如果B包含兩項資料，學生可以兩個答案都寫B。"},{"en":"This instruction prevents students from assuming each letter can be used only once.","zh":"這個指示防止學生以為每個字母只能使用一次。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":15},{"front":"distract from the real task of","meaning":"令人分心而忽略……真正任務","examples":[{"en":"Geoengineering may distract from the real task of changing lifestyles.","zh":"地球工程可能令人分心而忽略改變生活方式這項真正任務。"},{"en":"To distract from the real task of something means to take attention away from the most important job.","zh":"distract from the real task of something 指把注意力從最重要工作上移開。"},{"en":"Arguing about classroom decorations may distract from the real task of improving teaching.","zh":"爭論課室裝飾可能令人分心而忽略改善教學這項真正任務。"},{"en":"A company’s advertising can distract from the real task of fixing poor service.","zh":"公司的廣告可以令人分心而忽略修正差劣服務這項真正任務。"},{"en":"This phrase warns that an easier topic may hide the harder duty.","zh":"這個片語警告較容易的話題可能掩蓋較困難的責任。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":15},{"front":"changing the way we live","meaning":"改變我們的生活方式","examples":[{"en":"Critics say we must focus on changing the way we live.","zh":"批評者說我們必須專注於改變我們的生活方式。"},{"en":"Changing the way we live means altering our daily habits, energy use, transport, and consumption.","zh":"changing the way we live 指改變我們的日常習慣、能源使用、交通和消費。"},{"en":"Using public transport more often is one example of changing the way we live.","zh":"更常使用公共交通是改變我們生活方式的一個例子。"},{"en":"If people avoid changing the way they live, emissions may remain high.","zh":"如果人們避免改變生活方式，排放可能維持高水平。"},{"en":"This phrase points to lifestyle change, not only new technology.","zh":"這個片語指向生活方式改變，而不只是新科技。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":15},{"front":"demonstrated success","meaning":"展示成功","examples":[{"en":"Some geoengineering has demonstrated success on a small scale.","zh":"一些地球工程在小規模上展示成功。"},{"en":"Demonstrated success means proven or shown success through evidence or examples.","zh":"demonstrated success 指透過證據或例子證明或顯示成功。"},{"en":"A reading programme has demonstrated success if students’ scores improve after joining it.","zh":"如果學生參加閱讀計劃後成績改善，該計劃便展示成功。"},{"en":"Demonstrated success in one school does not always mean the same method will work everywhere.","zh":"在一間學校展示成功，不一定代表同一方法在每處都有效。"},{"en":"This phrase points to evidence, but the scale and context still matter.","zh":"這個片語指向證據，但規模和語境仍然重要。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":15},{"front":"frustrating maintenance problems","meaning":"令人挫敗的維護問題","examples":[{"en":"Geoengineering schemes may involve frustrating maintenance problems.","zh":"地球工程方案可能涉及令人挫敗的維護問題。"},{"en":"Frustrating maintenance problems are repair and upkeep issues that are difficult, repeated, and annoying.","zh":"frustrating maintenance problems 是困難、重複且令人煩惱的維修和保養問題。"},{"en":"Old lifts in a housing estate can create frustrating maintenance problems for residents.","zh":"屋苑中的舊升降機可以為居民造成令人挫敗的維護問題。"},{"en":"If a system is huge and remote, maintenance problems may become more frustrating.","zh":"如果系統巨大而遙遠，維護問題可能變得更令人挫敗。"},{"en":"This phrase stresses the practical difficulty of keeping something working.","zh":"這個片語強調保持某物運作的實際困難。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":15},{"front":"associated with","meaning":"與……相關","examples":[{"en":"Maintenance problems may be associated with geoengineering projects.","zh":"維護問題可能與地球工程項目相關。"},{"en":"Associated with means connected to or linked with something.","zh":"associated with 指與某事有關或有連繫。"},{"en":"Poor sleep is often associated with weak concentration.","zh":"睡眠不足常與專注力弱相關。"},{"en":"A restaurant associated with dirty kitchens may lose customers quickly.","zh":"與骯髒廚房相關的餐廳可能很快失去顧客。"},{"en":"This phrase shows a connection, not always a direct cause.","zh":"這個片語顯示關聯，但不一定是直接原因。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":16},{"front":"support for geoengineering","meaning":"對地球工程的支持","examples":[{"en":"Support for geoengineering partly comes from political pessimism.","zh":"對地球工程的支持部分來自政治悲觀情緒。"},{"en":"Support for geoengineering means approval of, interest in, or willingness to consider geoengineering.","zh":"support for geoengineering 指對地球工程的認可、興趣或考慮意願。"},{"en":"Support for a new school policy may grow if parents see clear benefits.","zh":"如果家長看到明確好處，對新校政的支持可能增加。"},{"en":"Support for geoengineering may increase when emissions cuts seem politically impossible.","zh":"當減排在政治上似乎不可能時，對地球工程的支持可能增加。"},{"en":"This phrase refers to backing an idea, not necessarily implementing it immediately.","zh":"這個片語指支持某個想法，而不一定是立即實施它。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":16},{"front":"arise from","meaning":"源於","examples":[{"en":"Support for geoengineering may arise from a lack of confidence in governments.","zh":"對地球工程的支持可能源於對政府缺乏信心。"},{"en":"To arise from something means to be caused by or develop from it.","zh":"arise from something 指由某事造成或發展而來。"},{"en":"Stress may arise from too much homework and too little sleep.","zh":"壓力可能源於太多功課和太少睡眠。"},{"en":"Complaints can arise from unclear rules or poor service.","zh":"投訴可以源於規則不清或服務差劣。"},{"en":"This phrase points to the source or cause of a situation.","zh":"這個片語指出某情況的來源或原因。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":16},{"front":"lack of confidence in","meaning":"對……缺乏信心","examples":[{"en":"Scientists may have a lack of confidence in governments.","zh":"科學家可能對政府缺乏信心。"},{"en":"Lack of confidence in someone means not trusting their ability, honesty, or effectiveness.","zh":"lack of confidence in someone 指不信任某人的能力、誠信或效力。"},{"en":"Customers may have a lack of confidence in a bank after repeated errors.","zh":"經過多次錯誤後，顧客可能對銀行缺乏信心。"},{"en":"A lack of confidence in public transport can make people rely more on cars.","zh":"對公共交通缺乏信心可以令人更依賴私家車。"},{"en":"This phrase describes low trust, not simple disagreement.","zh":"這個片語描述低信任，而不是簡單不同意。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":16},{"front":"greater success in fighting climate change","meaning":"在應對氣候變化方面有較大成效","examples":[{"en":"Some countries have had greater success in fighting climate change.","zh":"一些國家在應對氣候變化方面有較大成效。"},{"en":"Greater success in fighting climate change means better progress in reducing or managing climate-related problems.","zh":"greater success in fighting climate change 指在減少或管理氣候相關問題方面取得更好進展。"},{"en":"A country may have greater success in fighting climate change if it invests early in clean energy.","zh":"如果一個國家及早投資潔淨能源，它可能在應對氣候變化方面有較大成效。"},{"en":"Greater success in one country can show others which policies work.","zh":"一個國家的較大成效可以向其他國家展示哪些政策有效。"},{"en":"This phrase compares how well different places respond to climate change.","zh":"這個片語比較不同地方應對氣候變化的效果。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":16},{"front":"some parts of the world","meaning":"世界某些地區","examples":[{"en":"Some parts of the world have made more progress than others.","zh":"世界某些地區比其他地區取得更多進展。"},{"en":"Some parts of the world means certain regions or countries, but not everywhere.","zh":"some parts of the world 指某些地區或國家，但不是所有地方。"},{"en":"Some parts of the world have excellent public transport, while others depend on cars.","zh":"世界某些地區有優良公共交通，而其他地區依賴私家車。"},{"en":"Climate change affects some parts of the world more severely than others.","zh":"氣候變化對世界某些地區的影響比其他地區更嚴重。"},{"en":"This phrase is useful when a statement is true in certain places only.","zh":"當某說法只在某些地方成立時，這個片語很有用。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":16},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in the missing words in the short text that follows.","zh":"complete the summary below 指填上下面短文中缺少的字詞。"},{"en":"In reading tests, students complete the summary below by finding exact information in the passage.","zh":"在閱讀測驗中，學生透過在文章中找出準確資料來完成以下摘要。"},{"en":"To complete the summary below correctly, students must check both grammar and meaning.","zh":"要正確完成以下摘要，學生必須同時檢查文法和意思。"},{"en":"This instruction asks for careful reading, not personal opinion.","zh":"這個指示要求細心閱讀，而不是個人意見。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":16},{"front":"no more than two words","meaning":"不多於兩個詞","examples":[{"en":"Students should choose no more than two words from the passage.","zh":"學生應從文章中選擇不多於兩個詞。"},{"en":"No more than two words means the answer must contain one or two words only.","zh":"no more than two words 指答案只能包含一個或兩個詞。"},{"en":"If the instruction says no more than two words, writing three words will lose marks.","zh":"如果指示說不多於兩個詞，寫三個詞會失分。"},{"en":"Students should copy no more than two words and avoid adding unnecessary articles.","zh":"學生應只抄不多於兩個詞，並避免加入不必要冠詞。"},{"en":"This phrase sets a strict word limit for answers.","zh":"這個片語為答案設定嚴格字數限制。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":16},{"front":"a range of","meaning":"一系列","examples":[{"en":"A range of geoengineering ideas has been proposed.","zh":"一系列地球工程構想已被提出。"},{"en":"A range of means several different types or examples of something.","zh":"a range of 指某事物的幾種不同類型或例子。"},{"en":"A school offers a range of activities, such as music, sport, and drama.","zh":"學校提供一系列活動，例如音樂、運動和戲劇。"},{"en":"A range of solutions is useful when one method cannot solve every problem.","zh":"當一種方法不能解決所有問題，一系列解決方案便有用。"},{"en":"This phrase suggests variety within the same general topic.","zh":"這個片語暗示同一大主題中的多樣性。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":16},{"front":"ice caps","meaning":"冰蓋","examples":[{"en":"Some ideas aim to prevent ice caps from melting.","zh":"一些想法旨在防止冰蓋融化。"},{"en":"Ice caps are large areas of ice covering land or sea in cold regions.","zh":"ice caps 是寒冷地區覆蓋陸地或海洋的大面積冰層。"},{"en":"Ice caps reflect sunlight and help keep polar regions cool.","zh":"冰蓋反射陽光，幫助極地地區保持寒冷。"},{"en":"When ice caps melt, sea levels and animal habitats can be affected.","zh":"當冰蓋融化，海平面和動物棲息地都可能受影響。"},{"en":"This phrase refers to major ice covers, not small pieces of ice.","zh":"這個片語指大型冰覆蓋，而不是小塊冰。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":16},{"front":"stop the general rise in","meaning":"阻止……的整體上升","examples":[{"en":"Some schemes aim to stop the general rise in global temperatures.","zh":"一些方案旨在阻止全球氣溫的整體上升。"},{"en":"To stop the general rise in something means to prevent its overall upward trend from continuing.","zh":"stop the general rise in something 指防止某事整體上升趨勢繼續。"},{"en":"A school may try to stop the general rise in absenteeism by supporting stressed students.","zh":"學校可能透過支援受壓學生，嘗試阻止缺席率整體上升。"},{"en":"If rent controls stop the general rise in housing costs, families may feel less pressure.","zh":"如果租金管制阻止住房成本整體上升，家庭壓力可能較小。"},{"en":"This phrase focuses on the broad trend, not one small change.","zh":"這個片語聚焦於廣泛趨勢，而不是一個小變化。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":16},{"front":"discourage the melting of","meaning":"阻止……融化","examples":[{"en":"Planting birch trees may discourage the melting of ice and snow.","zh":"種植樺樹可能阻止冰和雪融化。"},{"en":"To discourage the melting of something means to make melting less likely or slower.","zh":"discourage the melting of something 指令融化較不可能發生或變慢。"},{"en":"Keeping food in a freezer discourages the melting of ice cream.","zh":"把食物放在冰格中可以阻止雪糕融化。"},{"en":"White surfaces can discourage the melting of snow by reflecting sunlight.","zh":"白色表面可以透過反射陽光來阻止雪融化。"},{"en":"This phrase means reducing the conditions that cause melting.","zh":"這個片語指減少導致融化的條件。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":17},{"front":"because of their colour","meaning":"因其顏色","examples":[{"en":"Birch trees may help because of their colour.","zh":"樺樹可能因其顏色而有幫助。"},{"en":"Because of their colour means the colour is the reason for the effect.","zh":"because of their colour 指顏色是造成效果的原因。"},{"en":"White shirts feel cooler in summer because of their colour.","zh":"白色恤衫因其顏色在夏天感覺較涼。"},{"en":"Dark roads absorb more heat because of their colour.","zh":"深色道路因其顏色吸收更多熱力。"},{"en":"This phrase explains cause through appearance.","zh":"這個片語透過外觀解釋原因。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":17},{"front":"encourage something to build up","meaning":"促使……積聚","examples":[{"en":"Ice could be encouraged to build up along coasts.","zh":"可以促使冰沿海岸積聚。"},{"en":"To encourage something to build up means to help it collect, grow, or increase gradually.","zh":"encourage something to build up 指幫助某物逐漸聚集、增長或增加。"},{"en":"Saving a little money each week can encourage savings to build up.","zh":"每星期儲一點錢可以促使儲蓄積聚。"},{"en":"If snow collects in the same place, it may build up into a thicker layer.","zh":"如果雪在同一地方聚集，它可能積聚成較厚一層。"},{"en":"This phrase suggests gradual accumulation, not sudden creation.","zh":"這個片語暗示逐漸累積，而不是突然創造。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":17},{"front":"disperse along the coasts","meaning":"沿海岸分散","examples":[{"en":"Sea ice could be dispersed along the coasts.","zh":"海冰可以沿海岸分散。"},{"en":"To disperse along the coasts means to spread something out near coastal areas.","zh":"disperse along the coasts 指把某物在沿岸地區分散開。"},{"en":"Floating barriers may disperse debris along the coasts after a storm.","zh":"風暴後，浮動屏障可能把碎片沿海岸分散。"},{"en":"If ice is dispersed along the coasts, it may freeze together in cold conditions.","zh":"如果冰沿海岸分散，在寒冷條件下可能再次結冰在一起。"},{"en":"This phrase describes spreading along shorelines.","zh":"這個片語描述沿海岸線擴散。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":17},{"front":"special ships","meaning":"特殊船隻","examples":[{"en":"Special ships could scatter coastal sea ice.","zh":"特殊船隻可以分散沿岸海冰。"},{"en":"Special ships are vessels designed for a particular job rather than ordinary transport.","zh":"special ships 是為特定任務而設計的船隻，而不是普通運輸船。"},{"en":"Icebreakers are special ships because they are built to move through frozen water.","zh":"破冰船是特殊船隻，因為它們被建造來穿過結冰水域。"},{"en":"Special ships may cost more because they need stronger equipment.","zh":"特殊船隻可能較昂貴，因為它們需要更強設備。"},{"en":"This phrase stresses that ordinary ships may not be suitable.","zh":"這個片語強調普通船隻未必合適。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":17},{"front":"change the direction of","meaning":"改變……的方向","examples":[{"en":"Engineers could change the direction of some rivers.","zh":"工程師可以改變一些河流的方向。"},{"en":"To change the direction of something means to make it move or point another way.","zh":"change the direction of something 指令某物移動或指向另一方向。"},{"en":"Roadworks can change the direction of traffic for several weeks.","zh":"道路工程可以在數星期內改變交通方向。"},{"en":"If engineers change the direction of a river, farms and ecosystems downstream may be affected.","zh":"如果工程師改變河流方向，下游農場和生態系統可能受影響。"},{"en":"This phrase focuses on redirecting movement.","zh":"這個片語聚焦於重新引導移動。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":17},{"front":"depend on particular weather conditions","meaning":"取決於特定天氣條件","examples":[{"en":"The river-diversion scheme depends on particular weather conditions.","zh":"河流改道方案取決於特定天氣條件。"},{"en":"To depend on particular weather conditions means to work only if the weather is suitable in specific ways.","zh":"depend on particular weather conditions 指只有在特定合適天氣下才會奏效。"},{"en":"A beach wedding depends on particular weather conditions, such as no rain and low wind.","zh":"海灘婚禮取決於特定天氣條件，例如無雨和低風。"},{"en":"If a plan depends on particular weather conditions, it may be unreliable.","zh":"如果一個計劃取決於特定天氣條件，它可能不可靠。"},{"en":"This phrase shows that weather can decide whether a plan succeeds.","zh":"這個片語顯示天氣可以決定計劃是否成功。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":17},{"front":"increasing the amount of ice","meaning":"增加冰量","examples":[{"en":"Some schemes aim at increasing the amount of ice.","zh":"一些方案旨在增加冰量。"},{"en":"Increasing the amount of ice means making more ice form or remain in an area.","zh":"increasing the amount of ice 指令某區域形成或保留更多冰。"},{"en":"Lower temperatures can help increase the amount of ice on a lake.","zh":"較低氣溫可以幫助增加湖上的冰量。"},{"en":"If the amount of ice increases, more sunlight may be reflected.","zh":"如果冰量增加，更多陽光可能被反射。"},{"en":"This phrase focuses on ice quantity, not simply ice colour.","zh":"這個片語聚焦於冰的數量，而不只是冰的顏色。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":17},{"front":"bring water to the surface","meaning":"把水帶到表面","examples":[{"en":"Pumps could bring water to the surface.","zh":"水泵可以把水帶到表面。"},{"en":"To bring water to the surface means to move water from below up to the top layer.","zh":"bring water to the surface 指把下面的水移到上層或表面。"},{"en":"A well pump brings water to the surface for households to use.","zh":"水井泵把水帶到表面供家庭使用。"},{"en":"If seawater is brought to the surface in freezing weather, it may turn into ice.","zh":"如果海水在冰凍天氣中被帶到表面，它可能結成冰。"},{"en":"This phrase describes upward movement of water.","zh":"這個片語描述水向上移動。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":17},{"front":"a scheme to stop ice moving","meaning":"阻止冰移動的方案","examples":[{"en":"A scheme to stop ice moving would use reinforced cables.","zh":"阻止冰移動的方案會使用加固纜索。"},{"en":"A scheme to stop ice moving is a plan designed to prevent ice from flowing or drifting away.","zh":"a scheme to stop ice moving 是設計來防止冰流動或漂走的計劃。"},{"en":"Engineers might design a scheme to stop ice moving if glaciers are entering the sea too quickly.","zh":"如果冰川太快進入海中，工程師可能設計阻止冰移動的方案。"},{"en":"If the ice is too powerful, a scheme to stop ice moving may fail.","zh":"如果冰的力量太大，阻止冰移動的方案可能失敗。"},{"en":"This phrase describes the aim of a plan in simple terms.","zh":"這個片語用簡單方式描述計劃目標。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":17},{"front":"stop it altogether","meaning":"完全阻止它","examples":[{"en":"The cables may not stop the ice altogether.","zh":"纜索可能不能完全阻止冰。"},{"en":"To stop it altogether means to stop it completely, not just slow or change it.","zh":"stop it altogether 指完全停止某事，而不只是減慢或改變它。"},{"en":"Medicine may reduce pain but not stop it altogether.","zh":"藥物可能減輕痛楚，但不能完全阻止它。"},{"en":"Traffic rules can reduce accidents, but they may not stop them altogether.","zh":"交通規則可以減少意外，但可能不能完全阻止它們。"},{"en":"This phrase contrasts partial control with total prevention.","zh":"這個片語對比部分控制與完全預防。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":17},{"front":"proposal for cooling","meaning":"降溫提案","examples":[{"en":"A proposal for cooling global temperatures is based on volcanic eruptions.","zh":"一項令全球氣溫降溫的提案基於火山爆發。"},{"en":"A proposal for cooling is a suggested plan to lower temperatures.","zh":"proposal for cooling 是降低氣溫的建議計劃。"},{"en":"A city may create a proposal for cooling streets by planting trees and painting roofs white.","zh":"城市可能制定透過種樹和把屋頂塗白來為街道降溫的提案。"},{"en":"A proposal for cooling must consider possible side effects, not only temperature reduction.","zh":"降溫提案必須考慮可能副作用，而不只是降低氣溫。"},{"en":"This phrase refers to an idea still being considered, not necessarily implemented.","zh":"這個片語指仍在考慮中的想法，不一定已實施。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":18},{"front":"based on what happened after","meaning":"基於……之後發生的事","examples":[{"en":"The proposal is based on what happened after past volcanic eruptions.","zh":"這項提案基於過去火山爆發之後發生的事。"},{"en":"Based on what happened after means using later results from an earlier event as evidence.","zh":"based on what happened after 指使用較早事件之後的結果作為證據。"},{"en":"A school may change its exam rules based on what happened after last year’s complaints.","zh":"學校可能基於去年投訴之後發生的事改變考試規則。"},{"en":"Doctors may adjust treatment based on what happened after previous patients used the medicine.","zh":"醫生可能基於先前病人用藥之後發生的事調整治療。"},{"en":"This phrase connects a new plan to lessons from past outcomes.","zh":"這個片語把新計劃與過去結果中的教訓連接起來。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":18},{"front":"create clouds of gas","meaning":"形成氣體雲","examples":[{"en":"The scheme would create clouds of gas in the atmosphere.","zh":"該方案會在大氣中形成氣體雲。"},{"en":"To create clouds of gas means to form large masses of gas in the air.","zh":"create clouds of gas 指在空氣中形成大量氣體團。"},{"en":"A factory leak can create clouds of gas that are dangerous to breathe.","zh":"工廠洩漏可以形成吸入有危險的氣體雲。"},{"en":"Volcanic eruptions can create clouds of gas high above Earth.","zh":"火山爆發可以在地球高空形成氣體雲。"},{"en":"This phrase describes visible or widespread gas formations, not ordinary small breaths of air.","zh":"這個片語描述可見或大範圍的氣體形成，而不是普通少量空氣。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":18},{"front":"list of opinions","meaning":"意見列表","examples":[{"en":"The question provides a list of opinions.","zh":"題目提供一個意見列表。"},{"en":"A list of opinions is a set of views or statements that people may agree or disagree with.","zh":"list of opinions 是一組人們可能同意或不同意的看法或陳述。"},{"en":"In a reading test, students may match speakers to a list of opinions.","zh":"在閱讀測驗中，學生可能把說話者與意見列表配對。"},{"en":"A list of opinions helps compare different people’s attitudes clearly.","zh":"意見列表幫助清楚比較不同人的態度。"},{"en":"This phrase refers to viewpoints, not facts alone.","zh":"這個片語指觀點，而不只是事實。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":18},{"front":"match each person with","meaning":"將每個人物與……配對","examples":[{"en":"Students match each person with the correct opinion.","zh":"學生將每個人物與正確意見配對。"},{"en":"To match each person with something means to connect every person to the correct item.","zh":"match each person with something 指把每個人連接到正確項目。"},{"en":"In a classroom game, students match each person with their favourite hobby.","zh":"在課堂遊戲中，學生把每個人物與其最喜歡的嗜好配對。"},{"en":"In reading exams, students must match each person with the view supported by the text.","zh":"在閱讀考試中，學生必須把每個人物與文本支持的看法配對。"},{"en":"This phrase is common in matching tasks.","zh":"這個片語常見於配對題。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":18},{"front":"problems associated with","meaning":"與……相關的問題","examples":[{"en":"The problems associated with geoengineering should be considered carefully.","zh":"與地球工程相關的問題應被仔細考慮。"},{"en":"Problems associated with something are difficulties or risks connected to it.","zh":"problems associated with something 是與某事相關的困難或風險。"},{"en":"Problems associated with online learning may include poor internet and weak concentration.","zh":"與網上學習相關的問題可能包括網絡差和專注力弱。"},{"en":"If problems associated with a plan are ignored, the plan may fail later.","zh":"如果與計劃相關的問題被忽視，計劃日後可能失敗。"},{"en":"This phrase shows connection between an idea and its possible difficulties.","zh":"這個片語顯示某想法與其可能困難之間的關聯。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":18},{"front":"serious consideration of","meaning":"對……的認真考慮","examples":[{"en":"The risks should not prevent serious consideration of geoengineering.","zh":"風險不應阻止對地球工程的認真考慮。"},{"en":"Serious consideration of something means careful, thoughtful attention before accepting or rejecting it.","zh":"serious consideration of something 指在接受或拒絕某事前仔細、深思熟慮地關注它。"},{"en":"A school should give serious consideration to students’ mental health before changing exam rules.","zh":"學校在改變考試規則前，應認真考慮學生心理健康。"},{"en":"Serious consideration of a plan includes studying benefits, costs, and risks.","zh":"對計劃的認真考慮包括研究好處、成本和風險。"},{"en":"This phrase suggests careful judgement, not quick dismissal.","zh":"這個片語暗示謹慎判斷，而不是快速否定。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":18},{"front":"more likely to succeed than others","meaning":"比其他方案更有可能成功","examples":[{"en":"Some geoengineering projects may be more likely to succeed than others.","zh":"一些地球工程項目可能比其他方案更有可能成功。"},{"en":"More likely to succeed than others means having a better chance of working compared with other options.","zh":"more likely to succeed than others 指相比其他選項有更大機會奏效。"},{"en":"A simple study plan is often more likely to succeed than an unrealistic one.","zh":"簡單學習計劃通常比不現實計劃更有可能成功。"},{"en":"Projects with clear funding and skilled workers are more likely to succeed than poorly planned projects.","zh":"有清晰資金和熟練工人的項目，比規劃差的項目更有可能成功。"},{"en":"This phrase compares chances of success.","zh":"這個片語比較成功機會。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":18},{"front":"short-term relief","meaning":"短期紓緩","examples":[{"en":"Geoengineering may offer only short-term relief.","zh":"地球工程可能只提供短期紓緩。"},{"en":"Short-term relief is temporary help that reduces a problem for a limited time.","zh":"short-term relief 是在有限時間內減輕問題的暫時幫助。"},{"en":"Painkillers may give short-term relief, but they may not cure the illness.","zh":"止痛藥可能提供短期紓緩，但未必治癒疾病。"},{"en":"A discount can offer short-term relief to customers facing high prices.","zh":"折扣可以為面對高物價的顧客提供短期紓緩。"},{"en":"This phrase suggests help now, but not necessarily a lasting solution.","zh":"這個片語暗示現在有幫助，但不一定是長久解決方案。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":18},{"front":"positive outcome","meaning":"正面結果","examples":[{"en":"A positive outcome of geoengineering may have negative effects elsewhere.","zh":"地球工程的一個正面結果可能在其他地方造成負面影響。"},{"en":"A positive outcome is a good or desirable result.","zh":"positive outcome 是良好或理想的結果。"},{"en":"A positive outcome of extra tutoring may be greater confidence in class.","zh":"額外補習的一個正面結果可能是在課堂上更有信心。"},{"en":"A policy can have a positive outcome for one group but create problems for another.","zh":"政策可以對一個群體有正面結果，但為另一群體造成問題。"},{"en":"This phrase focuses on the beneficial result of an action.","zh":"這個片語聚焦於行動帶來的有益結果。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":18},{"front":"negative consequence elsewhere","meaning":"在其他地方造成負面後果","examples":[{"en":"Cooling one region may create a negative consequence elsewhere.","zh":"令一個地區降溫可能在其他地方造成負面後果。"},{"en":"A negative consequence elsewhere is a harmful result that appears in another place.","zh":"negative consequence elsewhere 是出現在另一地方的有害結果。"},{"en":"Building a road may reduce traffic in one district but create a negative consequence elsewhere.","zh":"建造道路可能減少一區交通，但在其他地方造成負面後果。"},{"en":"If water is diverted to farms, a negative consequence elsewhere may be less water for wetlands.","zh":"如果水被改道到農場，其他地方的負面後果可能是濕地水量減少。"},{"en":"This phrase warns that solving one local problem can cause harm in another area.","zh":"這個片語警告，解決一個本地問題可能在另一地區造成傷害。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":18},{"front":"aims are unclear","meaning":"目標不清晰","examples":[{"en":"The option says the aims of most geoengineering projects are unclear.","zh":"這個選項說大多數地球工程項目的目標不清晰。"},{"en":"If aims are unclear, people do not know exactly what a plan is trying to achieve.","zh":"如果 aims are unclear，意思是人們不知道計劃究竟想達成甚麼。"},{"en":"A group project fails easily when its aims are unclear.","zh":"當小組項目的目標不清晰，它很容易失敗。"},{"en":"If a policy’s aims are unclear, the public may not trust it.","zh":"如果政策目標不清晰，公眾可能不信任它。"},{"en":"This phrase suggests confusion about purpose, not necessarily failure of action.","zh":"這個片語暗示目的混亂，而不一定是行動失敗。"}],"source":"142 - Global warming - Prevent poles from melting.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 143":[{"front":"star performers","meaning":"明星表現者；頂尖人才","examples":[{"en":"The article questions whether companies should rely on star performers.","zh":"這篇文章質疑公司是否應該依賴明星表現者。"},{"en":"Star performers are people who produce outstanding results compared with most others.","zh":"明星表現者是指相對大多數人能取得出色成果的人。"},{"en":"A school may praise star performers who win prizes, but it still needs good teaching for everyone.","zh":"學校可能表揚贏得獎項的頂尖學生，但仍需要為所有人提供良好教學。"},{"en":"Relying only on star performers can create jealousy and weaken teamwork.","zh":"只依賴明星表現者可能造成妒忌並削弱團隊合作。"},{"en":"Star performers can help an organisation, but they usually need a strong system around them.","zh":"明星表現者可以幫助機構，但通常需要強大的制度支援。"}],"source":"143 - We have Star performers!.pdf","sourcePage":1},{"front":"the difference between","meaning":"……之間的差別","examples":[{"en":"The writer claims that the difference between companies is people.","zh":"作者聲稱公司之間的差別在於人。"},{"en":"The difference between two things is the way they are not the same.","zh":"兩者之間的差別，就是它們不相同的地方。"},{"en":"The difference between two restaurants may be service, price, location, or food quality.","zh":"兩間餐廳之間的差別可能是服務、價格、地點或食物質素。"},{"en":"Small differences between teams can lead to very different results over time.","zh":"團隊之間的小差別，隨時間可以導致很不同的結果。"},{"en":"This phrase is useful when comparing two people, groups, ideas, or systems.","zh":"這個片語適合比較兩個人、群體、想法或制度。"}],"source":"143 - We have Star performers!.pdf","sourcePage":1},{"front":"in plentiful supply","meaning":"供應充足","examples":[{"en":"Capital and technology are now in plentiful supply.","zh":"資本和科技現在供應充足。"},{"en":"If something is in plentiful supply, there is a large amount of it available.","zh":"如果某物 is in plentiful supply，意思是有大量可用供應。"},{"en":"During harvest season, fresh fruit may be in plentiful supply at the market.","zh":"在收成季節，市場上的新鮮水果可能供應充足。"},{"en":"When skilled workers are not in plentiful supply, companies may compete harder to hire them.","zh":"當熟練工人供應不足，公司可能更激烈地招聘他們。"},{"en":"This phrase describes abundance, not shortage.","zh":"這個片語描述充足，而不是短缺。"}],"source":"143 - We have Star performers!.pdf","sourcePage":1},{"front":"critical resource","meaning":"關鍵資源","examples":[{"en":"Human talent is the critical resource in the knowledge era.","zh":"在知識時代，人才是關鍵資源。"},{"en":"A critical resource is something extremely important for success or survival.","zh":"關鍵資源是對成功或生存極其重要的東西。"},{"en":"Clean water is a critical resource for a hospital because patients and staff need it every day.","zh":"清潔食水對醫院是關鍵資源，因為病人和職員每天都需要它。"},{"en":"If a business loses a critical resource, its performance may fall quickly.","zh":"如果企業失去關鍵資源，表現可能迅速下降。"},{"en":"This phrase shows that one resource matters more than ordinary support.","zh":"這個片語顯示某項資源比普通支援更重要。"}],"source":"143 - We have Star performers!.pdf","sourcePage":1},{"front":"the knowledge era","meaning":"知識時代","examples":[{"en":"In the knowledge era, companies compete for human talent.","zh":"在知識時代，公司爭奪人才。"},{"en":"The knowledge era is a period when information, skills, and ideas are central to economic success.","zh":"知識時代是資訊、技能和想法對經濟成功極為重要的時期。"},{"en":"In the knowledge era, a small software team may create more value than a large factory.","zh":"在知識時代，一個小型軟件團隊可能比大型工廠創造更多價值。"},{"en":"Because knowledge matters so much, education and training become more important.","zh":"因為知識如此重要，教育和培訓變得更加重要。"},{"en":"This phrase contrasts modern work with older economies based mainly on land or machines.","zh":"這個片語把現代工作與主要依賴土地或機器的舊經濟作對比。"}],"source":"143 - We have Star performers!.pdf","sourcePage":1},{"front":"human talent","meaning":"人才","examples":[{"en":"Companies often regard human talent as their most important resource.","zh":"公司常把人才視為最重要的資源。"},{"en":"Human talent means people’s abilities, knowledge, creativity, judgement, and experience.","zh":"人才是指人的能力、知識、創造力、判斷力和經驗。"},{"en":"A hospital depends on human talent such as doctors, nurses, technicians, and managers.","zh":"醫院依靠醫生、護士、技術員和管理人員等人才。"},{"en":"If a company develops human talent well, ordinary employees can become strong performers.","zh":"如果公司好好培養人才，普通員工也可以成為強大表現者。"},{"en":"Human talent matters, but it works best with good systems and leadership.","zh":"人才很重要，但配合良好制度和領導時效果最好。"}],"source":"143 - We have Star performers!.pdf","sourcePage":1},{"front":"full of achievers","meaning":"充滿成功者的","examples":[{"en":"Companies full of achievers are expected to outperform weaker rivals.","zh":"充滿成功者的公司被預期會勝過較弱的競爭對手。"},{"en":"A group full of achievers contains many people who succeed and produce strong results.","zh":"充滿成功者的群體，是指有很多能成功並取得強勁成果的人。"},{"en":"A class full of achievers may motivate students, but it can also create pressure.","zh":"充滿成功者的班級可能激勵學生，但也可能製造壓力。"},{"en":"If a workplace is full of achievers but lacks teamwork, results may still suffer.","zh":"如果工作場所充滿成功者但缺乏團隊合作，結果仍可能受損。"},{"en":"This phrase praises ability, but it does not guarantee organisational success.","zh":"這個片語稱讚能力，但不保證組織成功。"}],"source":"143 - We have Star performers!.pdf","sourcePage":1},{"front":"by definition","meaning":"根據定義；必然地","examples":[{"en":"A company full of achievers will, by definition, perform better than one full of plodders.","zh":"根據定義，一間充滿成功者的公司會比一間充滿平庸員工的公司表現更好。"},{"en":"By definition means because of the exact meaning of the word or idea.","zh":"By definition 指根據某個詞或概念的準確意思。"},{"en":"A triangle, by definition, has three sides.","zh":"根據定義，三角形有三條邊。"},{"en":"If a task is unpaid, it is not a paid job by definition.","zh":"如果一項任務沒有報酬，根據定義它就不是有薪工作。"},{"en":"This phrase shows that the conclusion follows from the definition itself.","zh":"這個片語顯示結論來自定義本身。"}],"source":"143 - We have Star performers!.pdf","sourcePage":1},{"front":"outperform","meaning":"表現勝過","examples":[{"en":"Companies with strong systems may outperform companies that simply hire stars.","zh":"擁有強大制度的公司可能表現勝過只是聘用明星人才的公司。"},{"en":"To outperform someone or something means to do better than them.","zh":"To outperform someone or something 指表現比對方更好。"},{"en":"A small school can outperform a larger school if it teaches more effectively.","zh":"如果小學校教學更有效，它可以表現勝過較大的學校。"},{"en":"Teams often outperform individuals when work requires coordination and trust.","zh":"當工作需要協調和信任時，團隊常能表現勝過個人。"},{"en":"This word is useful for comparing results, profits, grades, or performance.","zh":"這個字適合比較結果、利潤、成績或表現。"}],"source":"143 - We have Star performers!.pdf","sourcePage":1},{"front":"organisations of plodders","meaning":"由平庸員工組成的機構","examples":[{"en":"The writer contrasts companies full of achievers with organisations of plodders.","zh":"作者把充滿成功者的公司與由平庸員工組成的機構作對比。"},{"en":"Organisations of plodders are groups mainly made up of slow, ordinary, or unambitious workers.","zh":"由平庸員工組成的機構，是指主要由緩慢、普通或缺乏雄心的員工組成的群體。"},{"en":"A team of plodders may finish tasks, but it may not innovate quickly.","zh":"平庸團隊可能能完成任務，但未必能快速創新。"},{"en":"If managers label people as plodders too quickly, they may ignore hidden potential.","zh":"如果管理層太快把人標籤為平庸員工，可能會忽視隱藏潛力。"},{"en":"The phrase is negative and often used to criticise a weak workforce.","zh":"這個片語帶負面意味，常用來批評弱勢員工隊伍。"}],"source":"143 - We have Star performers!.pdf","sourcePage":1},{"front":"ergo","meaning":"因此","examples":[{"en":"Ergo, many ambitious companies compete fiercely for the best people.","zh":"因此，許多有雄心的公司激烈爭奪最優秀的人才。"},{"en":"Ergo means therefore or as a result.","zh":"Ergo 意思是因此或所以。"},{"en":"The shop is losing customers; ergo, it must improve service or reduce prices.","zh":"這間店正在流失顧客；因此，它必須改善服務或減價。"},{"en":"Students remember examples better than rules alone; ergo, teachers should use more examples.","zh":"學生比起單靠規則更能記住例子；因此，老師應使用更多例子。"},{"en":"This word is formal and slightly old-fashioned, so it is less common than “therefore”.","zh":"這個詞較正式，也有點古老，所以不如 “therefore” 常見。"}],"source":"143 - We have Star performers!.pdf","sourcePage":1},{"front":"compete ferociously for","meaning":"激烈爭奪","examples":[{"en":"Some companies compete ferociously for the best people.","zh":"一些公司激烈爭奪最優秀的人才。"},{"en":"To compete ferociously for something means to fight for it with great intensity.","zh":"To compete ferociously for something 指以非常強烈的方式爭奪某物。"},{"en":"Universities may compete ferociously for famous professors and top students.","zh":"大學可能激烈爭奪著名教授和頂尖學生。"},{"en":"When skilled workers are scarce, firms may compete ferociously by offering higher pay.","zh":"當熟練工人稀缺，公司可能透過提供更高薪酬激烈爭奪。"},{"en":"The phrase suggests aggressive competition, not mild interest.","zh":"這個片語暗示激烈競爭，而不是輕微興趣。"}],"source":"143 - We have Star performers!.pdf","sourcePage":2},{"front":"the best people","meaning":"最優秀的人才","examples":[{"en":"Ambitious companies often try to hire the best people.","zh":"有雄心的公司常試圖聘用最優秀的人才。"},{"en":"The best people are those with the strongest skills, judgement, attitude, or results for a role.","zh":"最優秀的人才，是指在某個職位上具備最強技能、判斷力、態度或成果的人。"},{"en":"A clinic needs the best people not only in medicine but also in reception and management.","zh":"診所不只在醫療方面需要最優秀的人才，也需要好的接待和管理人員。"},{"en":"If every firm chases the best people, salaries can rise quickly.","zh":"如果每間公司都追逐最優秀的人才，薪酬可能迅速上升。"},{"en":"The phrase sounds simple, but “best” depends on the job and the system.","zh":"這個片語聽起來簡單，但「最優秀」取決於工作和制度。"}],"source":"143 - We have Star performers!.pdf","sourcePage":2},{"front":"poach stars","meaning":"挖角明星人才","examples":[{"en":"Companies may try to poach stars from their rivals.","zh":"公司可能試圖從競爭對手那裡挖角明星人才。"},{"en":"To poach stars means to persuade top employees to leave a competitor and join your organisation.","zh":"To poach stars 指說服頂尖員工離開競爭對手並加入自己的機構。"},{"en":"A school may poach a famous teacher from another school by offering better pay.","zh":"學校可能透過提供更好薪酬，從另一所學校挖角著名老師。"},{"en":"Poaching stars can damage relationships between firms and create salary inflation.","zh":"挖角明星人才可能損害公司之間的關係，並造成薪酬膨脹。"},{"en":"The phrase suggests aggressive recruitment from competitors.","zh":"這個片語暗示從競爭對手那裡積極招聘。"}],"source":"143 - We have Star performers!.pdf","sourcePage":2},{"front":"pamper stars","meaning":"優待明星人才","examples":[{"en":"Some firms poach and pamper stars instead of building strong systems.","zh":"一些公司挖角並優待明星人才，而不是建立強大制度。"},{"en":"To pamper stars means to treat top performers with special comfort, rewards, or privileges.","zh":"To pamper stars 指以特別舒適、獎勵或特權對待頂尖表現者。"},{"en":"A company may pamper stars with private offices, high bonuses, and flexible rules.","zh":"公司可能用私人辦公室、高額花紅和彈性規則來優待明星人才。"},{"en":"Pampering stars can make other employees feel ignored or unfairly treated.","zh":"優待明星人才可能令其他員工感到被忽視或受到不公平對待。"},{"en":"This phrase is often critical because it suggests excessive special treatment.","zh":"這個片語常帶批評意味，因為它暗示過度特殊待遇。"}],"source":"143 - We have Star performers!.pdf","sourcePage":2},{"front":"ruthlessly weed out","meaning":"無情地淘汰","examples":[{"en":"The talent mindset encourages companies to ruthlessly weed out second-raters.","zh":"人才思維鼓勵公司無情地淘汰二流人才。"},{"en":"To ruthlessly weed out people means to remove them harshly and without much sympathy.","zh":"To ruthlessly weed out people 指嚴厲而缺乏同情地移除某些人。"},{"en":"A sales team may ruthlessly weed out weak performers after several poor months.","zh":"銷售團隊可能在數月業績差後無情地淘汰弱表現者。"},{"en":"If managers weed people out too ruthlessly, fear may replace learning.","zh":"如果管理層太無情地淘汰人，恐懼可能取代學習。"},{"en":"The phrase suggests a harsh selection process.","zh":"這個片語暗示嚴酷的篩選過程。"}],"source":"143 - We have Star performers!.pdf","sourcePage":2},{"front":"second-raters","meaning":"二流人才；能力較差者","examples":[{"en":"The strategy encourages managers to remove second-raters.","zh":"這種策略鼓勵管理層移除二流人才。"},{"en":"Second-raters are people judged to be less able, less successful, or less impressive than top performers.","zh":"Second-raters 是被認為比頂尖表現者能力較低、較不成功或較不出色的人。"},{"en":"A company may call someone a second-rater if their results are average, not outstanding.","zh":"如果某人的成果只是一般而不突出，公司可能稱他為二流人才。"},{"en":"Treating people as second-raters can damage confidence and loyalty.","zh":"把人當成二流人才可能損害信心和忠誠。"},{"en":"The word is negative and should be used carefully.","zh":"這個詞帶負面意味，應謹慎使用。"}],"source":"143 - We have Star performers!.pdf","sourcePage":2},{"front":"in essence","meaning":"本質上；實質上","examples":[{"en":"In essence, this has been the recruitment strategy of many ambitious companies.","zh":"本質上，這一直是許多有雄心公司的招聘策略。"},{"en":"In essence means basically or in its most important form.","zh":"In essence 指基本上，或從最重要的形式來說。"},{"en":"In essence, the problem is not effort but poor organisation.","zh":"本質上，問題不是努力不足，而是組織不佳。"},{"en":"A long report may, in essence, say that the school needs more teachers.","zh":"一份長報告本質上可能是在說學校需要更多老師。"},{"en":"This phrase helps reduce a complex idea to its central point.","zh":"這個片語有助把複雜想法簡化成核心重點。"}],"source":"143 - We have Star performers!.pdf","sourcePage":2},{"front":"recruitment strategy","meaning":"招聘策略","examples":[{"en":"The passage criticises a recruitment strategy based on hiring stars.","zh":"這篇文章批評一種以聘用明星人才為基礎的招聘策略。"},{"en":"A recruitment strategy is a plan for finding, attracting, and hiring workers.","zh":"招聘策略是尋找、吸引和聘用員工的計劃。"},{"en":"A restaurant’s recruitment strategy may include training local students as part-time staff.","zh":"餐廳的招聘策略可能包括培訓本地學生做兼職員工。"},{"en":"A poor recruitment strategy can bring in unsuitable people and create high turnover.","zh":"差劣招聘策略可能引入不合適的人，並造成高流失率。"},{"en":"This phrase focuses on how an organisation gets employees.","zh":"這個片語著重機構如何取得員工。"}],"source":"143 - We have Star performers!.pdf","sourcePage":2},{"front":"ambitious company","meaning":"有雄心的公司","examples":[{"en":"The ambitious company of the past decade often chased star employees.","zh":"過去十年有雄心的公司常追逐明星員工。"},{"en":"An ambitious company wants to grow, win, lead, or outperform its competitors.","zh":"有雄心的公司想成長、勝出、領先或表現勝過競爭對手。"},{"en":"An ambitious company may open new branches, hire specialists, and invest in training.","zh":"有雄心的公司可能開設新分店、聘請專家並投資培訓。"},{"en":"Ambition can help a firm improve, but it can also lead to risky hiring decisions.","zh":"雄心可以幫助公司進步，但也可能導致冒險的招聘決定。"},{"en":"This phrase describes a company with strong goals, not a passive one.","zh":"這個片語描述目標強烈的公司，而不是被動公司。"}],"source":"143 - We have Star performers!.pdf","sourcePage":2},{"front":"the past decade","meaning":"過去十年","examples":[{"en":"This strategy shaped many companies during the past decade.","zh":"這種策略在過去十年塑造了許多公司。"},{"en":"The past decade means the last ten years.","zh":"The past decade 指過去十年。"},{"en":"During the past decade, online shopping has changed many small businesses.","zh":"在過去十年，網上購物改變了許多小企業。"},{"en":"Trends from the past decade can explain why some companies hire differently today.","zh":"過去十年的趨勢可以解釋為何一些公司今天以不同方式招聘。"},{"en":"This phrase is useful for describing recent but not immediate history.","zh":"這個片語適合描述近期但不是即時的歷史。"}],"source":"143 - We have Star performers!.pdf","sourcePage":2},{"front":"talent mindset","meaning":"人才思維","examples":[{"en":"The talent mindset was promoted by influential consultancy reports.","zh":"人才思維由有影響力的顧問報告推廣。"},{"en":"The talent mindset is the belief that hiring and keeping exceptional individuals is the main route to success.","zh":"人才思維是相信聘用和留住卓越個人是成功主要途徑的想法。"},{"en":"A company with a talent mindset may spend heavily to recruit famous managers.","zh":"有人才思維的公司可能花重金招聘著名經理。"},{"en":"If the talent mindset ignores systems, stars may fail in a new workplace.","zh":"如果人才思維忽視制度，明星人才在新工作場所可能失敗。"},{"en":"This phrase describes a way of thinking about people and performance.","zh":"這個片語描述一種看待人和表現的方式。"}],"source":"143 - We have Star performers!.pdf","sourcePage":2},{"front":"be given definitive form","meaning":"被賦予明確形式","examples":[{"en":"The talent mindset was given definitive form in McKinsey’s reports.","zh":"人才思維在McKinsey的報告中被賦予明確形式。"},{"en":"To be given definitive form means to be expressed clearly, formally, and influentially.","zh":"To be given definitive form 指被清楚、正式且有影響力地表達出來。"},{"en":"A school’s values are given definitive form when they are written into clear rules.","zh":"當學校價值觀被寫成清晰規則時，它們便被賦予明確形式。"},{"en":"An idea becomes powerful when a respected report gives it definitive form.","zh":"當受尊敬的報告賦予一個想法明確形式，該想法便會變得有力量。"},{"en":"The phrase shows how a vague belief becomes a clear doctrine.","zh":"這個片語顯示模糊信念如何變成清楚理論。"}],"source":"143 - We have Star performers!.pdf","sourcePage":3},{"front":"consultancy","meaning":"顧問公司","examples":[{"en":"McKinsey is described as the consultancy behind The War for Talent.","zh":"McKinsey被描述為《人才爭奪戰》背後的顧問公司。"},{"en":"A consultancy is a company that gives expert advice to other organisations.","zh":"顧問公司是向其他機構提供專家建議的公司。"},{"en":"A school may hire a consultancy to improve its admissions system.","zh":"學校可能聘請顧問公司改善收生制度。"},{"en":"Consultancies can influence business thinking through reports, research, and recommendations.","zh":"顧問公司可以透過報告、研究和建議影響商業思維。"},{"en":"This word refers to an advisory firm, not a government department.","zh":"這個詞指提供建議的公司，而不是政府部門。"}],"source":"143 - We have Star performers!.pdf","sourcePage":3},{"front":"entitled","meaning":"題為","examples":[{"en":"The reports were famously entitled The War for Talent.","zh":"這些報告著名地題為《人才爭奪戰》。"},{"en":"Entitled means given the title or name of something.","zh":"Entitled 指被給予某個標題或名稱。"},{"en":"The school report was entitled Improving Reading for All Students.","zh":"該學校報告題為《改善所有學生的閱讀》。"},{"en":"A book’s title can shape how readers understand its argument.","zh":"一本書的標題可以塑造讀者如何理解其論點。"},{"en":"In this use, “entitled” means “called”, not “having a right to something”.","zh":"在這個用法中，entitled 意思是「題為」，不是「有權得到」。"}],"source":"143 - We have Star performers!.pdf","sourcePage":3},{"front":"The War for Talent","meaning":"《人才爭奪戰》","examples":[{"en":"The War for Talent helped popularise the talent mindset.","zh":"《人才爭奪戰》幫助普及人才思維。"},{"en":"The War for Talent is the title of reports that framed hiring as a battle for top employees.","zh":"《人才爭奪戰》是一些報告的標題，將招聘描述為爭奪頂尖員工的戰役。"},{"en":"A phrase like “war for talent” makes recruitment sound urgent and competitive.","zh":"像 “war for talent” 這樣的說法令招聘聽起來迫切而競爭激烈。"},{"en":"Such reports can change how managers think about hiring and promotion.","zh":"這類報告可以改變管理者對招聘和晉升的看法。"},{"en":"The title suggests that talent is scarce and companies must fight for it.","zh":"這個標題暗示人才稀缺，公司必須為此而戰。"}],"source":"143 - We have Star performers!.pdf","sourcePage":3},{"front":"the intensity of","meaning":"……的強度","examples":[{"en":"The intensity of the talent war later subsided.","zh":"人才戰的強度後來減弱。"},{"en":"The intensity of something is how strong, extreme, or forceful it is.","zh":"The intensity of something 指某事有多強烈、極端或有力。"},{"en":"The intensity of exam pressure rises when the test date gets closer.","zh":"當考試日期接近，考試壓力的強度會上升。"},{"en":"If the intensity of competition falls, companies may stop offering huge salaries.","zh":"如果競爭強度下降，公司可能停止提供巨額薪酬。"},{"en":"This phrase measures strength, not simply existence.","zh":"這個片語衡量強烈程度，而不只是是否存在。"}],"source":"143 - We have Star performers!.pdf","sourcePage":3},{"front":"warfare","meaning":"戰爭；激烈競爭","examples":[{"en":"The article describes competition for employees as warfare.","zh":"文章把員工競爭描述為戰爭。"},{"en":"Warfare means war or intense organised conflict.","zh":"Warfare 指戰爭或激烈而有組織的衝突。"},{"en":"Price warfare between shops can lead to heavy discounts and lower profits.","zh":"商店之間的價格戰可能導致大幅折扣和較低利潤。"},{"en":"Describing hiring as warfare can make companies act aggressively.","zh":"把招聘描述為戰爭，可能令公司行動更具攻擊性。"},{"en":"This word can be literal in war, or metaphorical in business and politics.","zh":"這個詞可以指真正戰爭，也可以在商業和政治中作比喻使用。"}],"source":"143 - We have Star performers!.pdf","sourcePage":3},{"front":"subsequently subsided","meaning":"其後減弱","examples":[{"en":"The intensity of the warfare subsequently subsided.","zh":"這場競爭的強度其後減弱。"},{"en":"Subsequently subsided means later became weaker, calmer, or less serious.","zh":"Subsequently subsided 指後來變得較弱、較平靜或較不嚴重。"},{"en":"The argument was loud at first, but it subsequently subsided after both sides listened.","zh":"爭論起初很激烈，但雙方聆聽後其後減弱。"},{"en":"A labour shortage may subsequently subside when more people enter the workforce.","zh":"當更多人進入勞動市場，勞工短缺可能其後減弱。"},{"en":"This phrase shows that a strong situation became less intense over time.","zh":"這個片語顯示強烈情況隨時間變得不那麼激烈。"}],"source":"143 - We have Star performers!.pdf","sourcePage":3},{"front":"the internet bubble","meaning":"互聯網泡沫","examples":[{"en":"The talent war cooled when the internet bubble lost air.","zh":"當互聯網泡沫洩氣時，人才戰冷卻下來。"},{"en":"The internet bubble was a period when internet companies were highly overvalued before many collapsed.","zh":"互聯網泡沫是互聯網公司被高度高估、其後許多公司倒閉的時期。"},{"en":"During a business bubble, investors may believe prices will keep rising forever.","zh":"在商業泡沫期間，投資者可能相信價格會永遠上升。"},{"en":"When a bubble bursts, companies may cut jobs and stop hiring aggressively.","zh":"當泡沫爆破，公司可能裁員並停止積極招聘。"},{"en":"This phrase links exaggerated optimism with later collapse.","zh":"這個片語把過度樂觀與後來崩潰連接起來。"}],"source":"143 - We have Star performers!.pdf","sourcePage":3},{"front":"warm up again","meaning":"再次升溫","examples":[{"en":"The competition for talent has started to warm up again.","zh":"人才競爭已開始再次升溫。"},{"en":"To warm up again means to become active, intense, or competitive again after a quieter period.","zh":"To warm up again 指在較平靜一段時間後再次變得活躍、激烈或競爭性強。"},{"en":"The housing market may warm up again when interest rates fall.","zh":"當利率下降，樓市可能再次升溫。"},{"en":"If the economy improves, hiring can warm up again quickly.","zh":"如果經濟改善，招聘可以很快再次升溫。"},{"en":"The phrase suggests renewed activity, not a completely new beginning.","zh":"這個片語暗示活動重新增強，而不是全新開始。"}],"source":"143 - We have Star performers!.pdf","sourcePage":3},{"front":"the labour market tightens","meaning":"勞工市場收緊","examples":[{"en":"The talent war intensifies when the labour market tightens.","zh":"當勞工市場收緊，人才戰會加劇。"},{"en":"The labour market tightens when there are fewer available workers compared with job openings.","zh":"當可用工人相對職位空缺較少時，勞工市場便收緊。"},{"en":"If many restaurants are hiring but few people apply, the labour market tightens.","zh":"如果很多餐廳招聘但很少人申請，勞工市場便收緊。"},{"en":"A tighter labour market can push wages up and make recruitment harder.","zh":"勞工市場收緊可以推高工資並令招聘更困難。"},{"en":"This phrase describes shortage and competition for workers.","zh":"這個片語描述工人短缺和競爭。"}],"source":"143 - We have Star performers!.pdf","sourcePage":3},{"front":"labour shortages","meaning":"勞工短缺","examples":[{"en":"Labour shortages can lead governments to welcome foreign workers.","zh":"勞工短缺可以使政府歡迎外籍工人。"},{"en":"Labour shortages happen when there are not enough workers for available jobs.","zh":"勞工短缺是指可用職位多於足夠工人。"},{"en":"A hospital may face labour shortages if many nurses leave at the same time.","zh":"如果許多護士同時離職，醫院可能面對勞工短缺。"},{"en":"Labour shortages can delay services, raise wages, and increase pressure on existing staff.","zh":"勞工短缺可以延誤服務、推高工資，並增加現有員工壓力。"},{"en":"This phrase describes a workforce problem, not simply unemployment.","zh":"這個片語描述勞動力問題，而不只是失業。"}],"source":"143 - We have Star performers!.pdf","sourcePage":3},{"front":"lay out the welcome mat for","meaning":"歡迎……到來","examples":[{"en":"The government has laid out the welcome mat for immigrants.","zh":"政府已歡迎移民到來。"},{"en":"To lay out the welcome mat for someone means to actively welcome and encourage them to come.","zh":"To lay out the welcome mat for someone 指主動歡迎並鼓勵某人到來。"},{"en":"A university may lay out the welcome mat for international students with scholarships and support.","zh":"大學可能透過獎學金和支援歡迎國際學生到來。"},{"en":"When labour is scarce, a country may lay out the welcome mat for foreign workers.","zh":"當勞動力稀缺，國家可能歡迎外籍工人到來。"},{"en":"The phrase is friendly and metaphorical, like placing a mat at the door for guests.","zh":"這個片語友善而帶比喻意味，就像在門口放迎賓地氈。"}],"source":"143 - We have Star performers!.pdf","sourcePage":4},{"front":"immigrants","meaning":"移民","examples":[{"en":"Labour shortages may encourage a country to accept more immigrants.","zh":"勞工短缺可能鼓勵一個國家接受更多移民。"},{"en":"Immigrants are people who move to another country to live there, often for work, family, or safety.","zh":"移民是搬到另一個國家生活的人，常因工作、家庭或安全原因。"},{"en":"Immigrants may open shops, work in hospitals, or study in local schools.","zh":"移民可能開店、在醫院工作，或在本地學校讀書。"},{"en":"If immigrants are treated fairly, they can contribute skills and strengthen communities.","zh":"如果移民受到公平對待，他們可以貢獻技能並強化社區。"},{"en":"This word describes people who settle in a new country, not short-term tourists.","zh":"這個詞描述在新國家定居的人，而不是短期遊客。"}],"source":"143 - We have Star performers!.pdf","sourcePage":4},{"front":"the diagnosis","meaning":"診斷；問題判斷","examples":[{"en":"The diagnosis that people are important is obvious.","zh":"人很重要這個診斷是明顯的。"},{"en":"A diagnosis is a judgement about what the real problem is.","zh":"診斷是對真正問題是甚麼的判斷。"},{"en":"A doctor’s diagnosis explains why a patient feels ill.","zh":"醫生的診斷解釋病人為何感到不適。"},{"en":"In business, a wrong diagnosis can lead managers to solve the wrong problem.","zh":"在商業中，錯誤診斷可能令管理層解決錯誤問題。"},{"en":"This word can be medical, but it is also used for analysing organisations.","zh":"這個詞可以是醫學用語，也可用於分析組織。"}],"source":"143 - We have Star performers!.pdf","sourcePage":4},{"front":"evident to the point of platitude","meaning":"明顯得近乎老生常談","examples":[{"en":"The claim that people are important is evident to the point of platitude.","zh":"人很重要這個說法明顯得近乎老生常談。"},{"en":"If something is evident to the point of platitude, it is so obvious that saying it adds little value.","zh":"如果某事 evident to the point of platitude，意思是它明顯到說出來幾乎沒有價值。"},{"en":"Saying “students need practice” may be evident to the point of platitude.","zh":"說「學生需要練習」可能明顯得近乎老生常談。"},{"en":"A statement can be true but still unhelpful if it is only a platitude.","zh":"一句話可以是真的，但如果只是老生常談，仍然幫助不大。"},{"en":"This phrase criticises ideas that sound wise but are too obvious.","zh":"這個片語批評那些聽起來有智慧但過於明顯的想法。"}],"source":"143 - We have Star performers!.pdf","sourcePage":4},{"front":"platitude","meaning":"老生常談","examples":[{"en":"The importance of people in business can sound like a platitude.","zh":"人在商業中的重要性可能聽起來像老生常談。"},{"en":"A platitude is a statement that is true or familiar but too obvious to be useful.","zh":"老生常談是指真實或熟悉，但太明顯而不太有用的說法。"},{"en":"“Work hard and you will succeed” can sound like a platitude if it ignores real obstacles.","zh":"如果忽視真實障礙，「努力就會成功」可能聽起來像老生常談。"},{"en":"Platitudes can make people feel heard for a moment, but they rarely solve problems.","zh":"老生常談可能一時令人覺得被理解，但很少真正解決問題。"},{"en":"This word often criticises empty or overused advice.","zh":"這個詞常用來批評空洞或過度使用的建議。"}],"source":"143 - We have Star performers!.pdf","sourcePage":4},{"front":"logical prescription","meaning":"合乎邏輯的對策","examples":[{"en":"The apparently logical prescription is to hire the best people.","zh":"表面上合乎邏輯的對策是聘用最優秀的人。"},{"en":"A logical prescription is a solution that seems to follow sensibly from a problem.","zh":"合乎邏輯的對策，是看似合理地由問題推出的解決方法。"},{"en":"If students are failing, the logical prescription may seem to be more lessons.","zh":"如果學生不合格，表面上合乎邏輯的對策可能是更多課堂。"},{"en":"A logical prescription can still be wrong if the diagnosis is too simple.","zh":"如果診斷過於簡單，合乎邏輯的對策仍可能是錯的。"},{"en":"This phrase describes a recommended action, not medicine only.","zh":"這個片語描述建議行動，不只指藥方。"}],"source":"143 - We have Star performers!.pdf","sourcePage":4},{"front":"hire the best","meaning":"聘用最優秀的人","examples":[{"en":"The passage questions the idea that companies should simply hire the best.","zh":"文章質疑公司是否應該只是聘用最優秀的人。"},{"en":"To hire the best means to recruit people believed to have the highest ability or strongest record.","zh":"To hire the best 指招聘被認為能力最高或履歷最強的人。"},{"en":"A school may try to hire the best teachers, but it must also support them well.","zh":"學校可能試圖聘用最優秀的老師，但也必須好好支援他們。"},{"en":"Hiring the best can fail if the workplace has poor systems and weak leadership.","zh":"如果工作場所制度差、領導弱，聘用最優秀的人也可能失敗。"},{"en":"This phrase sounds attractive, but the meaning of “best” depends on context.","zh":"這個片語聽起來吸引，但「最優秀」的意思取決於語境。"}],"source":"143 - We have Star performers!.pdf","sourcePage":4},{"front":"like so much in management","meaning":"正如管理學中很多事一樣","examples":[{"en":"Like so much in management, the idea appears simple but is misleading.","zh":"正如管理學中很多事一樣，這個想法看似簡單卻具誤導性。"},{"en":"Like so much in management means similar to many other ideas in business management.","zh":"Like so much in management 指與商業管理中許多其他想法相似。"},{"en":"Like so much in management, a simple slogan may hide a complicated problem.","zh":"正如管理學中很多事一樣，一句簡單口號可能隱藏複雜問題。"},{"en":"Managers often face ideas that sound practical but fail when applied blindly.","zh":"管理者常面對聽起來實用，但盲目應用時會失敗的想法。"},{"en":"This phrase introduces a general lesson about management thinking.","zh":"這個片語引出關於管理思維的一般教訓。"}],"source":"143 - We have Star performers!.pdf","sourcePage":4},{"front":"not only not obvious","meaning":"不但並非顯而易見","examples":[{"en":"The prescription is not only not obvious but profoundly wrong.","zh":"這個對策不但並非顯而易見，而且根本錯誤。"},{"en":"Not only not obvious means something is not merely unclear; it is even less reliable than people think.","zh":"Not only not obvious 指某事不只是並不清楚，甚至比人們以為的更不可靠。"},{"en":"The answer is not only not obvious; it may require careful evidence.","zh":"答案不但並非顯而易見，還可能需要仔細證據。"},{"en":"A policy may be not only not obvious but harmful if it ignores real causes.","zh":"如果政策忽視真正原因，它可能不但並非顯而易見，而且有害。"},{"en":"This phrase strongly rejects the idea that a solution is self-evident.","zh":"這個片語強烈否定某方案是顯而易見的說法。"}],"source":"143 - We have Star performers!.pdf","sourcePage":4},{"front":"profoundly wrong","meaning":"大錯特錯；根本錯誤","examples":[{"en":"The writer argues that the star-hiring strategy is profoundly wrong.","zh":"作者認為聘用明星人才的策略大錯特錯。"},{"en":"Profoundly wrong means deeply and seriously mistaken.","zh":"Profoundly wrong 指深層而嚴重地錯誤。"},{"en":"Blaming students alone for poor results can be profoundly wrong if the school provides little support.","zh":"如果學校幾乎沒有支援，只把成績差歸咎於學生可能是大錯特錯。"},{"en":"A business theory may be profoundly wrong when it ignores how people actually work together.","zh":"當商業理論忽視人們實際如何合作時，它可能根本錯誤。"},{"en":"This phrase is much stronger than “slightly wrong”.","zh":"這個片語比「有點錯」強烈得多。"}],"source":"143 - We have Star performers!.pdf","sourcePage":4},{"front":"suspicions dawned","meaning":"疑慮開始浮現","examples":[{"en":"The first suspicions dawned after the collapse of dotcom companies.","zh":"互聯網公司倒閉後，最初的疑慮開始浮現。"},{"en":"If suspicions dawn, people slowly begin to realise that something may be wrong.","zh":"If suspicions dawn，意思是人們慢慢開始意識到某事可能有問題。"},{"en":"Suspicions dawned when the manager noticed that the same mistake kept happening.","zh":"當經理注意到同一錯誤不斷發生時，疑慮開始浮現。"},{"en":"After several failed projects, doubts may dawn about the original strategy.","zh":"幾個項目失敗後，人們可能開始懷疑原本策略。"},{"en":"The phrase suggests gradual realisation, not sudden proof.","zh":"這個片語暗示逐步意識到，而不是突然證明。"}],"source":"143 - We have Star performers!.pdf","sourcePage":4},{"front":"crash to earth","meaning":"從高處墜落；迅速崩潰","examples":[{"en":"The crash to earth of dotcom meteors exposed weaknesses in the talent myth.","zh":"互聯網新貴公司的迅速崩潰暴露了人才神話的弱點。"},{"en":"To crash to earth means to fall suddenly from high success or high expectations to failure.","zh":"To crash to earth 指從高度成功或高期望突然跌至失敗。"},{"en":"A fashionable start-up can crash to earth when it cannot make real profit.","zh":"當時髦初創企業無法真正盈利時，可能迅速崩潰。"},{"en":"When unrealistic confidence meets reality, a company may crash to earth quickly.","zh":"當不切實際的信心遇上現實，公司可能很快從高處墜落。"},{"en":"The phrase is dramatic and suggests a hard fall after excitement.","zh":"這個片語很戲劇化，暗示興奮後的沉重下跌。"}],"source":"143 - We have Star performers!.pdf","sourcePage":5},{"front":"dotcom meteors","meaning":"互聯網新貴公司","examples":[{"en":"The dotcom meteors crashed when the internet bubble burst.","zh":"當互聯網泡沫爆破時，互聯網新貴公司崩潰。"},{"en":"Dotcom meteors are fast-rising internet companies that seemed bright but disappeared quickly.","zh":"Dotcom meteors 是迅速崛起、看似耀眼但很快消失的互聯網公司。"},{"en":"A dotcom meteor may attract investors before it has a stable business model.","zh":"互聯網新貴公司可能在擁有穩定商業模式前已吸引投資者。"},{"en":"When hype fades, dotcom meteors can collapse faster than older companies.","zh":"當炒作消退，互聯網新貴公司可能比老牌公司更快倒下。"},{"en":"The metaphor compares flashy companies to meteors burning across the sky.","zh":"這個比喻把耀眼公司比作劃過天空的流星。"}],"source":"143 - We have Star performers!.pdf","sourcePage":5},{"front":"whatever the IQ of","meaning":"不論……的智商如何","examples":[{"en":"Dumb decisions remain dumb whatever the IQ of those who make them.","zh":"愚蠢決定仍然愚蠢，不論作出決定的人智商如何。"},{"en":"Whatever the IQ of someone means no matter how intelligent that person is.","zh":"Whatever the IQ of someone 指不論某人有多聰明。"},{"en":"A bad plan is still bad whatever the IQ of the person who designed it.","zh":"壞計劃仍然是壞計劃，不論設計者智商如何。"},{"en":"Intelligent people can make poor choices if the system rewards risky behaviour.","zh":"如果制度獎勵冒險行為，聰明人也可以作出差劣選擇。"},{"en":"This phrase separates intelligence from good judgement.","zh":"這個片語把智力與良好判斷分開。"}],"source":"143 - We have Star performers!.pdf","sourcePage":5},{"front":"perpetrate","meaning":"做出；犯下","examples":[{"en":"Intelligent people can still perpetrate foolish business decisions.","zh":"聰明人仍然可以犯下愚蠢的商業決定。"},{"en":"To perpetrate something means to commit or carry out something bad, harmful, or foolish.","zh":"To perpetrate something 指做出或犯下壞的、有害的或愚蠢的事。"},{"en":"A company may perpetrate a serious mistake by hiding safety problems.","zh":"公司若隱瞞安全問題，可能犯下嚴重錯誤。"},{"en":"People with high qualifications can still perpetrate errors if they ignore evidence.","zh":"即使有高學歷的人，如果忽視證據，仍可能犯錯。"},{"en":"The word is formal and usually negative.","zh":"這個字較正式，通常帶負面意味。"}],"source":"143 - We have Star performers!.pdf","sourcePage":5},{"front":"be illuminated in brilliant relief","meaning":"被清楚鮮明地揭示","examples":[{"en":"The flaw in the talent myth was illuminated in brilliant relief by Enron.","zh":"人才神話的缺陷被安然公司清楚鮮明地揭示。"},{"en":"To be illuminated in brilliant relief means to be shown very clearly and strongly.","zh":"To be illuminated in brilliant relief 指被非常清楚而強烈地顯示出來。"},{"en":"A school’s weakness may be illuminated in brilliant relief during an emergency.","zh":"學校的弱點可能在緊急情況中被清楚鮮明地揭示。"},{"en":"A crisis can reveal problems that normal success had hidden.","zh":"危機可以揭示平日成功掩蓋的問題。"},{"en":"This phrase is formal and visual, as if light makes the issue stand out.","zh":"這個片語正式而具畫面感，像光線令問題突顯出來。"}],"source":"143 - We have Star performers!.pdf","sourcePage":5},{"front":"The Talent Myth","meaning":"《人才神話》","examples":[{"en":"The Talent Myth criticised Enron’s belief in star employees.","zh":"《人才神話》批評安然公司對明星員工的信念。"},{"en":"The Talent Myth refers to the idea that individual brilliance alone can make an organisation successful.","zh":"《人才神話》指個人聰明才智本身就能令組織成功的想法。"},{"en":"A company follows the talent myth when it hires famous people but ignores teamwork and systems.","zh":"當公司聘用名人卻忽視團隊合作和制度時，就是遵循人才神話。"},{"en":"The talent myth can make managers overvalue individuals and undervalue the workplace around them.","zh":"人才神話可能令管理層高估個人，低估其身處的工作環境。"},{"en":"The phrase is critical because it calls this belief a myth, not a fact.","zh":"這個片語帶批判意味，因為它把這種信念稱為神話，而不是事實。"}],"source":"143 - We have Star performers!.pdf","sourcePage":5},{"front":"entertainingly relate","meaning":"生動有趣地講述","examples":[{"en":"A New Yorker article entertainingly related the story of Enron’s talent culture.","zh":"一篇《紐約客》文章生動有趣地講述了安然公司人才文化的故事。"},{"en":"To entertainingly relate a story means to tell it in an interesting and enjoyable way.","zh":"To entertainingly relate a story 指以有趣而令人願意聽的方式講述故事。"},{"en":"A teacher can entertainingly relate history by using vivid people and real events.","zh":"老師可以透過生動人物和真實事件，生動有趣地講述歷史。"},{"en":"If a writer relates a serious issue entertainingly, readers may stay engaged longer.","zh":"如果作者生動有趣地講述嚴肅議題，讀者可能更長時間保持投入。"},{"en":"The phrase describes style of storytelling, not whether the topic is light.","zh":"這個片語描述敘事風格，而不是主題是否輕鬆。"}],"source":"143 - We have Star performers!.pdf","sourcePage":5},{"front":"be convinced of","meaning":"深信","examples":[{"en":"Enron’s leaders were convinced of their own cleverness.","zh":"安然公司的領導者深信自己的聰明才智。"},{"en":"To be convinced of something means to strongly believe it is true.","zh":"To be convinced of something 指強烈相信某事是真的。"},{"en":"A student may be convinced of an answer until the teacher shows contrary evidence.","zh":"學生可能深信自己的答案，直到老師展示相反證據。"},{"en":"Being convinced of your own ability can help confidence, but it can also create arrogance.","zh":"深信自己的能力可以幫助自信，但也可能造成傲慢。"},{"en":"This phrase describes strong belief, not necessarily correct belief.","zh":"這個片語描述強烈信念，但不一定是正確信念。"}],"source":"143 - We have Star performers!.pdf","sourcePage":5},{"front":"one’s own cleverness","meaning":"自己的聰明才智","examples":[{"en":"Enron’s leaders trusted too much in their own cleverness.","zh":"安然公司的領導者過度相信自己的聰明才智。"},{"en":"One’s own cleverness means one’s belief in personal intelligence or smartness.","zh":"One’s own cleverness 指一個人對自己智力或聰明的信念。"},{"en":"A manager who trusts only their own cleverness may stop listening to staff.","zh":"只相信自己聰明才智的經理可能停止聆聽員工。"},{"en":"Confidence in one’s own cleverness can lead to risky decisions if no one challenges it.","zh":"如果沒有人挑戰，對自己聰明才智的信心可能導致冒險決定。"},{"en":"This phrase often warns against arrogance.","zh":"這個片語常提醒人不要傲慢。"}],"source":"143 - We have Star performers!.pdf","sourcePage":5},{"front":"never twig that","meaning":"從未意識到","examples":[{"en":"They never twigged that collective intelligence is not individual intelligence added together.","zh":"他們從未意識到集體智慧不是個人智慧相加。"},{"en":"To never twig that something is true means to never realise or understand it.","zh":"To never twig that something is true 指從未意識到或理解某事是真的。"},{"en":"A student may never twig that grammar improves through examples, not rules alone.","zh":"學生可能從未意識到文法靠例子提升，而不只是靠規則。"},{"en":"Managers may never twig that a weak system can make talented people look ordinary.","zh":"管理層可能從未意識到薄弱制度可以令有才華的人看起來普通。"},{"en":"This phrase is informal and means “never noticed the real point”.","zh":"這個片語較口語，意思是「從未察覺真正重點」。"}],"source":"143 - We have Star performers!.pdf","sourcePage":5},{"front":"collective intelligence","meaning":"集體智慧","examples":[{"en":"Collective intelligence is not simply the sum of individual intelligence.","zh":"集體智慧不只是個人智慧的總和。"},{"en":"Collective intelligence is the ability of a group to think, learn, and solve problems together.","zh":"集體智慧是群體一起思考、學習和解決問題的能力。"},{"en":"A medical team shows collective intelligence when doctors, nurses, and technicians share information well.","zh":"當醫生、護士和技術員良好分享資訊時，醫療團隊便展現集體智慧。"},{"en":"Collective intelligence improves when communication, trust, and clear roles are strong.","zh":"當溝通、信任和清晰角色強大時，集體智慧會提升。"},{"en":"This phrase focuses on group ability, not only individual talent.","zh":"這個片語著重群體能力，而不只是個人才華。"}],"source":"143 - We have Star performers!.pdf","sourcePage":5},{"front":"the sum of","meaning":"……的總和","examples":[{"en":"The intelligence of a company is not just the sum of individual talent.","zh":"一間公司的智慧不只是個人才華的總和。"},{"en":"The sum of something means the total produced by adding parts together.","zh":"The sum of something 指把各部分相加所得的總量。"},{"en":"A class result is not simply the sum of students’ scores if teamwork also matters.","zh":"如果團隊合作也重要，班級成果就不只是學生分數的總和。"},{"en":"A team can be more than the sum of its members when people cooperate well.","zh":"當人們合作良好，團隊可以大於其成員的總和。"},{"en":"This phrase is often used to compare parts with the whole.","zh":"這個片語常用來比較部分與整體。"}],"source":"143 - We have Star performers!.pdf","sourcePage":6},{"front":"in a profound sense","meaning":"從深層意義上","examples":[{"en":"In a profound sense, individual intelligence and collective intelligence may be opposites.","zh":"從深層意義上，個人智慧和集體智慧可能是相反的。"},{"en":"In a profound sense means at a deep and important level.","zh":"In a profound sense 指在深層而重要的層面上。"},{"en":"In a profound sense, a school is not just a building but a community of habits and values.","zh":"從深層意義上，學校不只是一座建築，而是習慣和價值的共同體。"},{"en":"A problem may look simple on the surface but be different in a profound sense.","zh":"一個問題表面看來簡單，但從深層意義上可能不同。"},{"en":"This phrase signals a deeper interpretation.","zh":"這個片語標示較深層的解讀。"}],"source":"143 - We have Star performers!.pdf","sourcePage":6},{"front":"believe in stars","meaning":"相信明星人才","examples":[{"en":"Enron believed in stars because it did not believe in systems.","zh":"安然相信明星人才，因為它不相信制度。"},{"en":"To believe in stars means to trust exceptional individuals as the main source of success.","zh":"To believe in stars 指把卓越個人視為成功的主要來源。"},{"en":"A football club believes in stars if it buys famous players instead of building teamwork.","zh":"如果足球會購買著名球員而不是建立團隊合作，它就是相信明星人才。"},{"en":"Believing in stars can make leaders ignore training, processes, and culture.","zh":"相信明星人才可能令領導者忽視培訓、流程和文化。"},{"en":"The phrase contrasts individual brilliance with organisational systems.","zh":"這個片語把個人光芒與組織制度作對比。"}],"source":"143 - We have Star performers!.pdf","sourcePage":6},{"front":"believe in systems","meaning":"相信制度","examples":[{"en":"Successful companies believe in systems as well as people.","zh":"成功公司不只相信人，也相信制度。"},{"en":"To believe in systems means to trust organised processes, structures, and teamwork to produce results.","zh":"To believe in systems 指相信有組織的流程、結構和團隊合作能產生成果。"},{"en":"A hospital believes in systems when it uses checklists to reduce mistakes.","zh":"醫院使用檢查清單減少錯誤時，就是相信制度。"},{"en":"Strong systems help ordinary workers perform better and help talented workers fit in.","zh":"強大制度幫助普通員工表現更好，也幫助有才華員工融入。"},{"en":"This phrase values the organisation around people, not just the people themselves.","zh":"這個片語重視人周圍的組織，而不只是人本身。"}],"source":"143 - We have Star performers!.pdf","sourcePage":6},{"front":"execute and compete","meaning":"執行並競爭","examples":[{"en":"Companies must execute and compete, not just create ideas.","zh":"公司必須執行並競爭，而不只是創造想法。"},{"en":"To execute and compete means to carry out plans well and perform strongly against rivals.","zh":"To execute and compete 指好好執行計劃，並在競爭中表現強勁。"},{"en":"A restaurant must execute and compete by serving good food quickly every day.","zh":"餐廳必須每天快速提供好食物，才能執行並競爭。"},{"en":"Good ideas fail if a company cannot execute them in the market.","zh":"如果公司無法在市場上執行好想法，好想法也會失敗。"},{"en":"This phrase stresses action and performance, not just creativity.","zh":"這個片語強調行動和表現，而不只是創意。"}],"source":"143 - We have Star performers!.pdf","sourcePage":6},{"front":"coordinate the efforts of","meaning":"協調……的努力","examples":[{"en":"Successful organisations coordinate the efforts of many people.","zh":"成功組織會協調許多人的努力。"},{"en":"To coordinate the efforts of people means to organise their work so they support one another.","zh":"To coordinate the efforts of people 指組織人們的工作，使他們互相支援。"},{"en":"A school trip requires teachers to coordinate the efforts of drivers, parents, and students.","zh":"學校旅行需要老師協調司機、家長和學生的努力。"},{"en":"Without coordination, talented people may duplicate work or block each other.","zh":"沒有協調，有才華的人可能重複工作或互相阻礙。"},{"en":"This phrase shows how group performance depends on organisation.","zh":"這個片語顯示團隊表現如何取決於組織。"}],"source":"143 - We have Star performers!.pdf","sourcePage":6},{"front":"be successful at that task","meaning":"在該任務上成功","examples":[{"en":"The best organisations are successful at coordinating people’s efforts.","zh":"最好的組織能在協調人們努力這項任務上成功。"},{"en":"To be successful at that task means to do that specific job well.","zh":"To be successful at that task 指把那項特定工作做好。"},{"en":"A hospital is successful at that task if staff share patient information clearly.","zh":"如果醫院職員清楚分享病人資訊，它就在這項任務上成功。"},{"en":"If a company is not successful at coordinating work, individual talent may be wasted.","zh":"如果公司未能成功協調工作，個人才華可能被浪費。"},{"en":"The phrase points back to a particular task already mentioned.","zh":"這個片語指回前文提到的特定任務。"}],"source":"143 - We have Star performers!.pdf","sourcePage":6},{"front":"the system is the star","meaning":"制度才是明星","examples":[{"en":"In successful organisations, the system is the star.","zh":"在成功組織中，制度才是明星。"},{"en":"The system is the star means the organisation’s processes and culture matter more than any one famous person.","zh":"The system is the star 指組織的流程和文化比任何一位名人更重要。"},{"en":"A school where every teacher follows clear support methods shows that the system is the star.","zh":"一所每位老師都遵循清晰支援方法的學校，顯示制度才是明星。"},{"en":"When the system is strong, new staff can perform well without being celebrities.","zh":"當制度強大，新員工即使不是名人也能表現良好。"},{"en":"This phrase reverses the usual focus on individual stars.","zh":"這個片語反轉了通常集中於個人明星的焦點。"}],"source":"143 - We have Star performers!.pdf","sourcePage":6},{"front":"win the talent war","meaning":"贏得人才戰","examples":[{"en":"You cannot win the talent war simply by hiring stars.","zh":"你不能單靠聘用明星人才贏得人才戰。"},{"en":"To win the talent war means to succeed in attracting, developing, and keeping valuable workers.","zh":"To win the talent war 指成功吸引、培養和留住有價值的員工。"},{"en":"A company may win the talent war by training ordinary graduates into strong managers.","zh":"公司可能透過把普通畢業生培訓成強大經理來贏得人才戰。"},{"en":"High salaries alone may not win the talent war if the workplace is unhealthy.","zh":"如果工作環境不健康，單靠高薪未必能贏得人才戰。"},{"en":"This phrase treats recruitment as competition, but the article questions that mindset.","zh":"這個片語把招聘視為競爭，但文章質疑這種思維。"}],"source":"143 - We have Star performers!.pdf","sourcePage":6},{"front":"only lose it","meaning":"只會輸掉它","examples":[{"en":"The writer argues that firms can only lose the talent war by hiring stars.","zh":"作者認為公司聘用明星人才只會輸掉人才戰。"},{"en":"Only lose it means the strategy cannot bring victory and may only create failure.","zh":"Only lose it 指某策略不能帶來勝利，只可能造成失敗。"},{"en":"A school that hires famous teachers but ignores students’ needs may only lose trust.","zh":"如果學校聘請名師卻忽視學生需要，可能只會失去信任。"},{"en":"If a team overpays stars and damages morale, it may only lose the competition for talent.","zh":"如果團隊過度支付明星並破壞士氣，它可能只會輸掉人才競爭。"},{"en":"The phrase strongly warns that the chosen method backfires.","zh":"這個片語強烈警告所選方法會適得其反。"}],"source":"143 - We have Star performers!.pdf","sourcePage":6},{"front":"throw new light on","meaning":"使人重新理解","examples":[{"en":"A study throws new light on why hiring stars may fail.","zh":"一項研究使人重新理解為何聘用明星人才可能失敗。"},{"en":"To throw new light on something means to help people understand it in a new or clearer way.","zh":"To throw new light on something 指幫助人以新的或更清晰的方式理解某事。"},{"en":"A student survey can throw new light on why many pupils dislike homework.","zh":"學生問卷可以使人重新理解為何許多學生不喜歡功課。"},{"en":"New evidence may throw new light on an old business problem.","zh":"新證據可能使人重新理解舊商業問題。"},{"en":"This phrase is useful when research changes understanding.","zh":"這個片語適合描述研究改變理解。"}],"source":"143 - We have Star performers!.pdf","sourcePage":6},{"front":"an analysis of","meaning":"對……的分析","examples":[{"en":"An analysis of star behaviour appeared in Harvard Business Review.","zh":"一篇對明星人才行為的分析刊登於《哈佛商業評論》。"},{"en":"An analysis of something is a careful study of its parts, causes, patterns, or effects.","zh":"An analysis of something 是對某事的部分、原因、模式或影響作仔細研究。"},{"en":"An analysis of exam mistakes can show which grammar points students need to practise.","zh":"對考試錯誤的分析可以顯示學生需要練習哪些文法點。"},{"en":"Good analysis can reveal patterns that are not obvious from one example.","zh":"良好分析可以揭示單一例子看不出的模式。"},{"en":"This phrase describes careful examination, not a quick opinion.","zh":"這個片語描述仔細檢視，而不是快速意見。"}],"source":"143 - We have Star performers!.pdf","sourcePage":7},{"front":"star behaviour","meaning":"明星人才行為","examples":[{"en":"The study examined star behaviour after employees changed firms.","zh":"該研究檢視員工轉換公司後的明星人才行為。"},{"en":"Star behaviour means how top performers act, adapt, and perform in different situations.","zh":"Star behaviour 指頂尖表現者在不同情況下如何行動、適應和表現。"},{"en":"A manager may study star behaviour to see whether top employees help or hurt team morale.","zh":"經理可能研究明星人才行為，以了解頂尖員工是提升還是損害團隊士氣。"},{"en":"If star behaviour becomes arrogant, colleagues may stop offering support.","zh":"如果明星人才行為變得傲慢，同事可能停止提供支援。"},{"en":"This phrase focuses on what star performers actually do, not just their reputation.","zh":"這個片語著重明星表現者實際做甚麼，而不只是他們的名聲。"}],"source":"143 - We have Star performers!.pdf","sourcePage":7},{"front":"stock analysts","meaning":"股票分析師","examples":[{"en":"The researchers studied the careers of 1,000 star stock analysts.","zh":"研究人員研究了一千名明星股票分析師的職業生涯。"},{"en":"Stock analysts are professionals who study companies and financial markets to advise investors.","zh":"股票分析師是研究公司和金融市場，並向投資者提供建議的專業人士。"},{"en":"A stock analyst may examine profits, risks, and industry trends before recommending a share.","zh":"股票分析師可能在推薦股票前檢視利潤、風險和行業趨勢。"},{"en":"If stock analysts move firms, their performance may change because their support system changes.","zh":"如果股票分析師轉換公司，他們的表現可能因支援系統改變而改變。"},{"en":"This phrase refers to finance professionals, not ordinary stock buyers.","zh":"這個片語指金融專業人士，而不是普通股票買家。"}],"source":"143 - We have Star performers!.pdf","sourcePage":7},{"front":"recruit a star performer","meaning":"招聘明星員工","examples":[{"en":"When a company recruited a star performer, several negative effects followed.","zh":"當公司招聘明星員工時，隨後出現了幾個負面影響。"},{"en":"To recruit a star performer means to hire someone known for outstanding results.","zh":"To recruit a star performer 指聘用以出色成果聞名的人。"},{"en":"A school may recruit a star performer to lead its debate team.","zh":"學校可能招聘明星老師帶領辯論隊。"},{"en":"Recruiting a star performer can raise expectations, but it can also disturb an existing team.","zh":"招聘明星員工可以提高期望，但也可能擾亂現有團隊。"},{"en":"This phrase focuses on hiring a high-status person from outside.","zh":"這個片語著重從外部聘用高地位人物。"}],"source":"143 - We have Star performers!.pdf","sourcePage":7},{"front":"stardom","meaning":"明星地位；頂尖表現","examples":[{"en":"Stardom does not easily transfer from one organisation to another.","zh":"明星地位並不容易從一個機構轉移到另一個機構。"},{"en":"Stardom means the status of being seen as a star or outstanding performer.","zh":"Stardom 指被視為明星或頂尖表現者的地位。"},{"en":"A chef’s stardom may depend on the kitchen team, ingredients, and restaurant brand.","zh":"廚師的明星地位可能取決於廚房團隊、食材和餐廳品牌。"},{"en":"When someone changes workplace, their stardom may fade if the support system disappears.","zh":"當某人轉換工作場所，如果支援系統消失，其明星地位可能淡化。"},{"en":"This word describes reputation and exceptional status.","zh":"這個詞描述名聲和卓越地位。"}],"source":"143 - We have Star performers!.pdf","sourcePage":7},{"front":"transfer from one organisation to another","meaning":"從一個機構轉移到另一個機構","examples":[{"en":"Success may not transfer from one organisation to another.","zh":"成功未必能從一個機構轉移到另一個機構。"},{"en":"To transfer from one organisation to another means to move or carry something across workplaces or institutions.","zh":"To transfer from one organisation to another 指從一個工作場所或機構移到另一個。"},{"en":"A teaching method may not transfer from one school to another if students’ needs are different.","zh":"如果學生需要不同，一種教學方法未必能從一所學校轉移到另一所學校。"},{"en":"Skills transfer more easily than local relationships, habits, and support systems.","zh":"技能比本地關係、習慣和支援系統更容易轉移。"},{"en":"This phrase warns that success in one place may depend on that place.","zh":"這個片語提醒人，一地的成功可能取決於該地本身。"}],"source":"143 - We have Star performers!.pdf","sourcePage":7},{"front":"in many cases","meaning":"在許多情況下","examples":[{"en":"In many cases, performance dropped after stars changed employers.","zh":"在許多情況下，明星員工轉換僱主後表現下降。"},{"en":"In many cases means in a large number of situations, though not all.","zh":"In many cases 指在大量情況中，但不是全部情況。"},{"en":"In many cases, students improve when feedback is specific and kind.","zh":"在許多情況下，當回饋具體而友善，學生會進步。"},{"en":"In many cases, a star employee needs time to adjust to a new team.","zh":"在許多情況下，明星員工需要時間適應新團隊。"},{"en":"This phrase shows a common pattern without claiming it always happens.","zh":"這個片語顯示常見模式，但不聲稱永遠如此。"}],"source":"143 - We have Star performers!.pdf","sourcePage":7},{"front":"drop sharply","meaning":"急劇下降","examples":[{"en":"Performance often dropped sharply after high performers switched firms.","zh":"高績效員工轉換公司後，表現常急劇下降。"},{"en":"To drop sharply means to fall quickly and by a large amount.","zh":"To drop sharply 指快速而大幅下降。"},{"en":"A student’s grades may drop sharply if they stop sleeping properly.","zh":"如果學生停止正常睡眠，成績可能急劇下降。"},{"en":"Sales can drop sharply after customers lose trust in a brand.","zh":"當顧客失去對品牌的信任，銷售可能急劇下降。"},{"en":"This phrase describes a sudden and serious decline.","zh":"這個片語描述突然而嚴重的下跌。"}],"source":"143 - We have Star performers!.pdf","sourcePage":7},{"front":"high performers","meaning":"高績效員工","examples":[{"en":"High performers may struggle after moving to a new company.","zh":"高績效員工轉到新公司後可能會吃力。"},{"en":"High performers are people who consistently produce strong results.","zh":"高績效員工是能持續產生強勁成果的人。"},{"en":"A high performer in one sales team may depend on good data, support, and loyal customers.","zh":"某銷售團隊中的高績效員工可能依賴良好數據、支援和忠誠客戶。"},{"en":"If high performers lose familiar tools, their results may fall.","zh":"如果高績效員工失去熟悉工具，他們的成果可能下降。"},{"en":"This phrase describes strong past performance, not guaranteed future success.","zh":"這個片語描述強勁過往表現，而不是保證未來成功。"}],"source":"143 - We have Star performers!.pdf","sourcePage":7},{"front":"switch employers","meaning":"轉換僱主","examples":[{"en":"Some star analysts performed worse after they switched employers.","zh":"一些明星分析師轉換僱主後表現較差。"},{"en":"To switch employers means to leave one company or organisation and work for another.","zh":"To switch employers 指離開一間公司或機構，轉到另一間工作。"},{"en":"A nurse may switch employers for better hours or higher pay.","zh":"護士可能為了更好工時或更高薪酬而轉換僱主。"},{"en":"Switching employers can bring new opportunities, but it also means learning a new system.","zh":"轉換僱主可以帶來新機會，但也意味着要學習新制度。"},{"en":"This phrase focuses on changing the organisation that employs you.","zh":"這個片語著重改變僱用你的機構。"}],"source":"143 - We have Star performers!.pdf","sourcePage":7},{"front":"in some instances","meaning":"在某些情況下","examples":[{"en":"In some instances, performance never recovered.","zh":"在某些情況下，表現從未恢復。"},{"en":"In some instances means in some particular cases or examples.","zh":"In some instances 指在某些特定情況或例子中。"},{"en":"In some instances, students learn faster online than in a crowded classroom.","zh":"在某些情況下，學生網上學習比在擁擠課室中學得更快。"},{"en":"In some instances, a famous hire may damage rather than improve team performance.","zh":"在某些情況下，聘用名人可能損害而不是改善團隊表現。"},{"en":"This phrase is narrower than “in many cases”.","zh":"這個片語比 “in many cases” 範圍較窄。"}],"source":"143 - We have Star performers!.pdf","sourcePage":7},{"front":"never recover","meaning":"從未恢復","examples":[{"en":"Some stars’ performance never recovered after they moved.","zh":"一些明星人才轉職後表現從未恢復。"},{"en":"To never recover means to fail to return to the earlier good condition or level.","zh":"To never recover 指未能回到早前良好狀態或水平。"},{"en":"A shop’s reputation may never recover after a serious safety scandal.","zh":"一間店經歷嚴重安全醜聞後，聲譽可能從未恢復。"},{"en":"If a worker loses confidence in a bad system, their performance may never recover there.","zh":"如果員工在差劣制度中失去信心，其表現可能在那裡從未恢復。"},{"en":"The phrase describes lasting damage, not a temporary dip.","zh":"這個片語描述持久損害，而不是暫時下跌。"}],"source":"143 - We have Star performers!.pdf","sourcePage":8},{"front":"more than is commonly supposed","meaning":"比一般所想的更多","examples":[{"en":"More of their success than is commonly supposed depends on the workplace.","zh":"他們的成功比一般所想的更多依賴工作場所。"},{"en":"More than is commonly supposed means more than most people usually think.","zh":"More than is commonly supposed 指比大多數人通常認為的更多。"},{"en":"More learning than is commonly supposed happens through feedback, not just lectures.","zh":"學習比一般所想的更多來自回饋，而不只是講課。"},{"en":"More of a manager’s success than people suppose may depend on the team and tools around them.","zh":"經理的成功可能比人們所想的更多依賴其身邊團隊和工具。"},{"en":"This phrase corrects an overly simple popular belief.","zh":"這個片語修正過於簡單的普遍看法。"}],"source":"143 - We have Star performers!.pdf","sourcePage":8},{"front":"be due to","meaning":"由於；歸因於","examples":[{"en":"Much of a star’s success is due to the working environment.","zh":"明星人才很大部分成功歸因於工作環境。"},{"en":"To be due to something means to be caused by or explained by it.","zh":"To be due to something 指由某事造成或由某事解釋。"},{"en":"A student’s improvement may be due to regular practice and clear feedback.","zh":"學生的進步可能歸因於定期練習和清晰回饋。"},{"en":"Poor service may be due to staff shortages rather than laziness.","zh":"服務差可能由於人手短缺，而不是懶惰。"},{"en":"This phrase connects a result with its cause.","zh":"這個片語把結果與原因連接起來。"}],"source":"143 - We have Star performers!.pdf","sourcePage":8},{"front":"working environment","meaning":"工作環境","examples":[{"en":"The working environment helps explain the success of star employees.","zh":"工作環境有助解釋明星員工的成功。"},{"en":"A working environment is the physical, social, and organisational setting in which people do their jobs.","zh":"工作環境是人們工作的實體、社交和組織環境。"},{"en":"A quiet office, helpful colleagues, and clear rules create a good working environment.","zh":"安靜辦公室、樂於助人的同事和清晰規則能創造良好工作環境。"},{"en":"A poor working environment can make even talented staff perform badly.","zh":"差劣工作環境可以令有才華員工也表現差。"},{"en":"This phrase includes more than the building; it also includes people and systems.","zh":"這個片語不只包括建築，也包括人和制度。"}],"source":"143 - We have Star performers!.pdf","sourcePage":8},{"front":"systems, processes and leadership","meaning":"制度、流程和領導","examples":[{"en":"Systems, processes and leadership often support individual performance.","zh":"制度、流程和領導常支援個人表現。"},{"en":"Systems, processes and leadership are the structures, routines, and guidance that help people work well.","zh":"制度、流程和領導是幫助人們好好工作的結構、常規和指導。"},{"en":"A hospital needs systems, processes and leadership to avoid dangerous mistakes.","zh":"醫院需要制度、流程和領導來避免危險錯誤。"},{"en":"Without these supports, talented employees may waste time solving basic organisational problems.","zh":"沒有這些支援，有才華員工可能浪費時間解決基本組織問題。"},{"en":"This phrase explains why performance belongs partly to the organisation.","zh":"這個片語解釋為何表現部分屬於組織。"}],"source":"143 - We have Star performers!.pdf","sourcePage":8},{"front":"accumulated embedded learning","meaning":"累積並內嵌於組織的學習","examples":[{"en":"A star’s success may depend on accumulated embedded learning in the firm.","zh":"明星人才的成功可能取決於公司內累積並內嵌於組織的學習。"},{"en":"Accumulated embedded learning is knowledge built up over time and built into a company’s routines.","zh":"Accumulated embedded learning 是隨時間建立並融入公司日常流程的知識。"},{"en":"A restaurant’s kitchen may have accumulated embedded learning about timing, suppliers, and customer tastes.","zh":"餐廳廚房可能累積了關於時間安排、供應商和顧客口味的內嵌學習。"},{"en":"When a worker leaves, this hidden learning may not travel with them.","zh":"當員工離開時，這種隱藏學習未必跟着他走。"},{"en":"This phrase explains why success is often rooted in a specific workplace.","zh":"這個片語解釋為何成功常扎根於特定工作場所。"}],"source":"143 - We have Star performers!.pdf","sourcePage":8},{"front":"be absent from","meaning":"在……中不存在","examples":[{"en":"The old support system is absent from the new firm.","zh":"舊支援系統在新公司中不存在。"},{"en":"To be absent from somewhere means to not be present or available there.","zh":"To be absent from somewhere 指某物在該地方不存在或不可用。"},{"en":"Clear guidance may be absent from a badly managed workplace.","zh":"在管理差劣的工作場所中，清晰指引可能不存在。"},{"en":"If trust is absent from a team, people may hide mistakes instead of fixing them.","zh":"如果團隊中沒有信任，人們可能隱瞞錯誤而不是修正錯誤。"},{"en":"This phrase describes something missing from a place or situation.","zh":"這個片語描述某物在某地方或情況中缺失。"}],"source":"143 - We have Star performers!.pdf","sourcePage":8},{"front":"cannot be transported to","meaning":"不能被帶到……","examples":[{"en":"Embedded learning cannot be transported to the new firm.","zh":"內嵌學習不能被帶到新公司。"},{"en":"Cannot be transported to means cannot simply be carried or moved to another place.","zh":"Cannot be transported to 指不能簡單地被攜帶或轉移到另一地方。"},{"en":"A teacher’s relationship with one class cannot be transported to another class overnight.","zh":"老師與一個班級的關係不能一夜之間被帶到另一個班。"},{"en":"Company culture cannot be transported to a new office by copying rules alone.","zh":"公司文化不能單靠複製規則就被帶到新辦公室。"},{"en":"This phrase shows that some support is tied to its original context.","zh":"這個片語顯示某些支援與原本語境綁在一起。"}],"source":"143 - We have Star performers!.pdf","sourcePage":8},{"front":"precisely because of","meaning":"正正因為","examples":[{"en":"Stars may resist learning precisely because of their past success.","zh":"明星人才可能正正因為過往成功而抗拒學習。"},{"en":"Precisely because of means exactly for that reason, often when the reason is surprising.","zh":"Precisely because of 指正正由於那個原因，常用於原因令人意外時。"},{"en":"A strong student may avoid feedback precisely because of past praise.","zh":"成績好的學生可能正正因為過去被讚賞而避開回饋。"},{"en":"A company may become careless precisely because of earlier success.","zh":"公司可能正正因為早前成功而變得粗心。"},{"en":"This phrase highlights the exact cause of a problem or result.","zh":"這個片語突顯問題或結果的準確原因。"}],"source":"143 - We have Star performers!.pdf","sourcePage":8},{"front":"past stellar performance","meaning":"過往卓越表現","examples":[{"en":"Stars may be overconfident because of their past stellar performance.","zh":"明星人才可能因過往卓越表現而過度自信。"},{"en":"Past stellar performance means earlier outstanding results or achievements.","zh":"Past stellar performance 指早前出色的成果或成就。"},{"en":"An athlete with past stellar performance may still need training after joining a new team.","zh":"擁有過往卓越表現的運動員加入新隊後仍可能需要訓練。"},{"en":"Past stellar performance can impress employers, but it does not guarantee future success.","zh":"過往卓越表現可以令僱主印象深刻，但不保證未來成功。"},{"en":"This phrase praises previous excellence while leaving room for later decline.","zh":"這個片語讚揚過去優秀，同時容許後來下滑。"}],"source":"143 - We have Star performers!.pdf","sourcePage":8},{"front":"be unwilling to","meaning":"不願意","examples":[{"en":"Some stars were unwilling to learn new tricks.","zh":"一些明星人才不願意學習新方法。"},{"en":"To be unwilling to do something means to not want to do it.","zh":"To be unwilling to do something 指不想做某事。"},{"en":"A student may be unwilling to ask questions because they fear looking weak.","zh":"學生可能因害怕顯得弱而不願意提問。"},{"en":"If a new employee is unwilling to learn, colleagues may stop helping.","zh":"如果新員工不願意學習，同事可能停止幫助。"},{"en":"This phrase describes resistance or lack of readiness.","zh":"這個片語描述抗拒或未準備好。"}],"source":"143 - We have Star performers!.pdf","sourcePage":8},{"front":"learn new tricks","meaning":"學習新方法","examples":[{"en":"Star employees may need to learn new tricks in a different workplace.","zh":"明星員工在不同工作場所可能需要學習新方法。"},{"en":"To learn new tricks means to learn new methods, habits, or skills.","zh":"To learn new tricks 指學習新的方法、習慣或技能。"},{"en":"A teacher moving to online classes must learn new tricks for keeping students engaged.","zh":"轉到網上課堂的老師必須學習新方法來保持學生投入。"},{"en":"Workers who refuse to learn new tricks may struggle when technology changes.","zh":"拒絕學習新方法的員工在科技改變時可能吃力。"},{"en":"The phrase is informal and often contrasts old success with new demands.","zh":"這個片語較口語，常對比舊成功和新要求。"}],"source":"143 - We have Star performers!.pdf","sourcePage":9},{"front":"antagonise","meaning":"激怒；引起……反感","examples":[{"en":"Some star recruits antagonised colleagues who could have helped them.","zh":"一些明星新員工激怒了本可以幫助他們的同事。"},{"en":"To antagonise someone means to annoy them or make them hostile.","zh":"To antagonise someone 指惹怒某人或令某人產生敵意。"},{"en":"A new manager may antagonise staff by criticising everything on the first day.","zh":"新經理如果第一天就批評所有事情，可能引起員工反感。"},{"en":"If a star recruit antagonises colleagues, they may lose the support they need.","zh":"如果明星新員工激怒同事，可能失去自己需要的支援。"},{"en":"This word describes behaviour that turns potential helpers into opponents.","zh":"這個詞描述把潛在幫助者變成反對者的行為。"}],"source":"143 - We have Star performers!.pdf","sourcePage":9},{"front":"unwittingly depend on","meaning":"不自覺地依賴","examples":[{"en":"New recruits unwittingly depended on colleagues who understood the system.","zh":"新入職員工不自覺地依賴了解制度的同事。"},{"en":"To unwittingly depend on someone means to rely on them without realising it.","zh":"To unwittingly depend on someone 指在沒有意識到的情況下依賴某人。"},{"en":"A student may unwittingly depend on a friend who always explains homework instructions.","zh":"學生可能不自覺地依賴總是解釋功課指示的朋友。"},{"en":"A new employee may fail when they do not notice how much they depend on local knowledge.","zh":"新員工如果沒有注意到自己多麼依賴本地知識，可能會失敗。"},{"en":"This phrase reveals hidden reliance.","zh":"這個片語揭示隱藏依賴。"}],"source":"143 - We have Star performers!.pdf","sourcePage":9},{"front":"move on","meaning":"轉職；離開","examples":[{"en":"Many recruited stars moved on within three years.","zh":"許多被招聘的明星人才在三年內轉職離開。"},{"en":"To move on means to leave a job, place, or stage and go to the next one.","zh":"To move on 指離開一份工作、地方或階段，前往下一個。"},{"en":"A teacher may move on to another school for better opportunities.","zh":"老師可能為了更好機會而轉到另一所學校。"},{"en":"If star employees move on quickly, the company may not recover its hiring costs.","zh":"如果明星員工很快離開，公司可能無法收回招聘成本。"},{"en":"This phrase can sound neutral, but in business it often means turnover.","zh":"這個片語可以聽起來中性，但在商業中常指人員流失。"}],"source":"143 - We have Star performers!.pdf","sourcePage":9},{"front":"up one’s salary","meaning":"提高薪酬","examples":[{"en":"Star analysts often upped their salary when they moved firms.","zh":"明星分析師轉換公司時常提高自己的薪酬。"},{"en":"To up one’s salary means to increase one’s pay.","zh":"To up one’s salary 指提高自己的薪金。"},{"en":"A worker may switch jobs to up their salary after gaining new skills.","zh":"工人在獲得新技能後，可能轉工以提高薪酬。"},{"en":"If many firms chase the same stars, those stars can up their salaries quickly.","zh":"如果許多公司追逐同一批明星人才，他們可以很快提高薪酬。"},{"en":"This phrase is informal and means “raise pay”.","zh":"這個片語較口語，意思是「提高工資」。"}],"source":"143 - We have Star performers!.pdf","sourcePage":9},{"front":"even for Wall Street","meaning":"即使以華爾街標準而言","examples":[{"en":"Moving within three years was fast even for Wall Street.","zh":"三年內轉職，即使以華爾街標準而言也很快。"},{"en":"Even for Wall Street means surprising even in a place known for speed, pressure, or job movement.","zh":"Even for Wall Street 指即使在以速度、壓力或轉職頻繁聞名的地方也令人驚訝。"},{"en":"A two-week promotion cycle would be fast even for a highly competitive sales team.","zh":"兩星期一次晉升，即使以高度競爭的銷售團隊而言也很快。"},{"en":"If something is unusual even for a demanding industry, it is especially striking.","zh":"如果某事在要求高的行業中也不尋常，它就特別突出。"},{"en":"This phrase emphasises that the behaviour is extreme by a tough standard.","zh":"這個片語強調某行為按嚴格標準而言也很極端。"}],"source":"143 - We have Star performers!.pdf","sourcePage":9},{"front":"group performance","meaning":"團隊表現","examples":[{"en":"Group performance suffered after star employees were hired.","zh":"聘用明星員工後，團隊表現受損。"},{"en":"Group performance is how well a team works and produces results together.","zh":"團隊表現是指一個團隊共同工作和產生成果的效果。"},{"en":"A class project depends on group performance, not only the smartest student.","zh":"小組專題取決於團隊表現，而不只是最聰明的學生。"},{"en":"Group performance can fall if one person gets special treatment and others feel ignored.","zh":"如果一個人得到特殊待遇而其他人感到被忽視，團隊表現可能下降。"},{"en":"This phrase focuses on the output of the whole team.","zh":"這個片語著重整個團隊的產出。"}],"source":"143 - We have Star performers!.pdf","sourcePage":9},{"front":"suffer as a result of","meaning":"因……而受損","examples":[{"en":"Team performance suffered as a result of tensions and resentment.","zh":"團隊表現因緊張關係和怨氣而受損。"},{"en":"To suffer as a result of something means to become worse because of it.","zh":"To suffer as a result of something 指因某事而變差。"},{"en":"A student’s health may suffer as a result of poor sleep.","zh":"學生的健康可能因睡眠不足而受損。"},{"en":"Customer service can suffer as a result of staff shortages.","zh":"客戶服務可能因人手短缺而受損。"},{"en":"This phrase connects harm with its cause.","zh":"這個片語把傷害與原因連接起來。"}],"source":"143 - We have Star performers!.pdf","sourcePage":9},{"front":"tensions and resentment","meaning":"緊張關係和怨氣","examples":[{"en":"Hiring stars can create tensions and resentment within a team.","zh":"聘用明星人才可以在團隊內造成緊張關係和怨氣。"},{"en":"Tensions and resentment are stress, conflict, and bitter feelings between people.","zh":"Tensions and resentment 是人與人之間的壓力、衝突和苦澀情緒。"},{"en":"A team may develop tensions and resentment if one member receives all the praise.","zh":"如果一名成員得到所有讚賞，團隊可能產生緊張關係和怨氣。"},{"en":"These feelings can reduce cooperation and make people less willing to share information.","zh":"這些感受可以降低合作意願，令大家較不願分享資訊。"},{"en":"This phrase describes emotional damage inside a group.","zh":"這個片語描述群體內的情緒傷害。"}],"source":"143 - We have Star performers!.pdf","sourcePage":9},{"front":"rivals within the team","meaning":"團隊內的競爭者","examples":[{"en":"Stars may face resentment from rivals within the team.","zh":"明星人才可能面對來自團隊內競爭者的怨氣。"},{"en":"Rivals within the team are colleagues who compete with one another inside the same group.","zh":"Rivals within the team 是在同一團隊內互相競爭的同事。"},{"en":"Two salespeople may become rivals within the team if both want the top bonus.","zh":"如果兩名銷售員都想得到最高花紅，他們可能成為團隊內的競爭者。"},{"en":"Internal rivalry can be healthy, but it can also damage trust.","zh":"內部競爭可以健康，但也可能損害信任。"},{"en":"This phrase shows that competition can exist inside a team, not only between companies.","zh":"這個片語顯示競爭不只存在於公司之間，也可以存在於團隊內。"}],"source":"143 - We have Star performers!.pdf","sourcePage":9},{"front":"liken A to B","meaning":"將A比作B","examples":[{"en":"One respondent likened hiring a star to an organ transplant.","zh":"一名受訪者將聘用明星人才比作器官移植。"},{"en":"To liken A to B means to compare A with B because they share an important feature.","zh":"To liken A to B 指因A和B有重要相似點而把A比作B。"},{"en":"A teacher may liken learning vocabulary to building a toolbox.","zh":"老師可能把學習詞彙比作建立工具箱。"},{"en":"Comparing hiring to an organ transplant suggests that a new part may not fit the body.","zh":"把招聘比作器官移植，暗示新部分未必適合身體。"},{"en":"This phrase is used when explaining something through analogy.","zh":"這個片語用於透過類比解釋事情。"}],"source":"143 - We have Star performers!.pdf","sourcePage":9},{"front":"organ transplant","meaning":"器官移植","examples":[{"en":"Hiring a star was compared to an organ transplant.","zh":"聘用明星人才被比作器官移植。"},{"en":"An organ transplant is a medical operation in which an organ is moved into another body.","zh":"器官移植是把器官移入另一個身體的醫療手術。"},{"en":"A transplant can save a patient, but the body may reject the new organ.","zh":"移植可以拯救病人，但身體可能排斥新器官。"},{"en":"The metaphor suggests that a star recruit may disturb a healthy team.","zh":"這個比喻暗示明星新員工可能擾亂健康團隊。"},{"en":"This phrase is medical literally, but here it explains organisational fit.","zh":"這個片語字面上是醫學用語，但在此解釋組織適配。"}],"source":"143 - We have Star performers!.pdf","sourcePage":10},{"front":"hog the blood supply","meaning":"霸佔血液供應","examples":[{"en":"A new organ can damage others by hogging the blood supply.","zh":"新器官可能因霸佔血液供應而傷害其他器官。"},{"en":"To hog the blood supply means to take too much of the shared support or resources.","zh":"To hog the blood supply 指佔用過多共同支援或資源。"},{"en":"A star employee may hog management attention, bonuses, and praise.","zh":"明星員工可能霸佔管理層注意力、花紅和讚賞。"},{"en":"If one project hogs resources, other important projects may suffer.","zh":"如果一個項目霸佔資源，其他重要項目可能受損。"},{"en":"The phrase is metaphorical and suggests selfish or harmful overuse.","zh":"這個片語是比喻，暗示自私或有害的過度佔用。"}],"source":"143 - We have Star performers!.pdf","sourcePage":10},{"front":"start aching","meaning":"開始疼痛","examples":[{"en":"Other organs can start aching after a transplant.","zh":"移植後，其他器官可能開始疼痛。"},{"en":"To start aching means to begin to hurt or feel pain.","zh":"To start aching 指開始感到疼痛。"},{"en":"Your shoulders may start aching after carrying a heavy bag for hours.","zh":"背着重袋數小時後，你的肩膀可能開始疼痛。"},{"en":"In the metaphor, team members start aching when a new star takes too many resources.","zh":"在這個比喻中，當新明星佔用太多資源，團隊成員便開始疼痛。"},{"en":"The phrase can describe physical pain or, figuratively, organisational discomfort.","zh":"這個片語可以描述身體疼痛，也可比喻組織不適。"}],"source":"143 - We have Star performers!.pdf","sourcePage":10},{"front":"threaten to stop working","meaning":"可能停止運作","examples":[{"en":"Other organs may threaten to stop working.","zh":"其他器官可能停止運作。"},{"en":"To threaten to stop working means to show signs that something may fail or refuse to function.","zh":"To threaten to stop working 指顯示某物可能失效或拒絕運作的跡象。"},{"en":"A printer may threaten to stop working if it keeps jamming before an important deadline.","zh":"如果打印機在重要期限前不斷卡紙，它可能快要停止運作。"},{"en":"In a team, ignored colleagues may threaten to stop cooperating.","zh":"在團隊中，被忽視的同事可能不再合作。"},{"en":"The phrase warns of possible breakdown.","zh":"這個片語警告可能出現崩潰。"}],"source":"143 - We have Star performers!.pdf","sourcePage":10},{"front":"reject the transplant","meaning":"排斥移植器官","examples":[{"en":"The body can reject the transplant altogether.","zh":"身體可以完全排斥移植器官。"},{"en":"To reject the transplant means the body refuses to accept the new organ.","zh":"To reject the transplant 指身體拒絕接受新器官。"},{"en":"Doctors monitor patients carefully because rejection can be dangerous after surgery.","zh":"醫生仔細監察病人，因為手術後排斥可能很危險。"},{"en":"In the business metaphor, a team may reject a star recruit by refusing to support them.","zh":"在商業比喻中，團隊可能透過拒絕支援明星新員工來排斥他。"},{"en":"This phrase describes failure of fit between the new part and the existing body.","zh":"這個片語描述新部分與原有身體不適配的失敗。"}],"source":"143 - We have Star performers!.pdf","sourcePage":10},{"front":"think carefully before","meaning":"在……之前仔細考慮","examples":[{"en":"You should think carefully before hiring a star for a healthy team.","zh":"在為健康團隊聘用明星人才之前，你應仔細考慮。"},{"en":"To think carefully before doing something means to consider risks and consequences first.","zh":"To think carefully before doing something 指先考慮風險和後果。"},{"en":"Students should think carefully before choosing subjects that affect future study.","zh":"學生在選擇影響未來學習的科目前，應仔細考慮。"},{"en":"Managers should think carefully before changing a team that already works well.","zh":"管理層在改變已運作良好的團隊之前，應仔細考慮。"},{"en":"This phrase warns against acting too quickly.","zh":"這個片語提醒人不要太快行動。"}],"source":"143 - We have Star performers!.pdf","sourcePage":10},{"front":"a healthy body","meaning":"健康的身體","examples":[{"en":"A healthy body may not need a risky transplant.","zh":"健康的身體未必需要有風險的移植。"},{"en":"A healthy body is a body whose parts work well together.","zh":"健康的身體是各部分能良好合作運作的身體。"},{"en":"A healthy team, like a healthy body, depends on balance and cooperation.","zh":"健康團隊像健康身體一樣，依靠平衡和合作。"},{"en":"Adding a powerful new part to a healthy body can still create danger if it does not fit.","zh":"即使向健康身體加入強大的新部分，如果不適配仍可能造成危險。"},{"en":"In the metaphor, the healthy body represents a well-functioning organisation.","zh":"在比喻中，健康的身體代表運作良好的組織。"}],"source":"143 - We have Star performers!.pdf","sourcePage":10},{"front":"punish the offender","meaning":"懲罰犯錯者","examples":[{"en":"Investors punished the offender by selling its stock.","zh":"投資者透過沽售其股票懲罰犯錯者。"},{"en":"To punish the offender means to take action against the person or organisation believed to have done wrong.","zh":"To punish the offender 指對被認為做錯事的人或機構採取懲罰行動。"},{"en":"Customers may punish a dishonest shop by refusing to buy from it again.","zh":"顧客可能透過不再光顧來懲罰不誠實的店舖。"},{"en":"Investors punish companies when they believe managers have made poor decisions.","zh":"當投資者認為管理層作出差劣決定，便會懲罰公司。"},{"en":"This phrase shows a negative reaction to perceived wrongdoing.","zh":"這個片語顯示對被視為錯誤行為的負面反應。"}],"source":"143 - We have Star performers!.pdf","sourcePage":10},{"front":"selling its stock","meaning":"沽售其股票","examples":[{"en":"Investors reacted to star hiring by selling the company’s stock.","zh":"投資者透過沽售該公司股票來回應明星招聘。"},{"en":"Selling its stock means investors sell shares of that company.","zh":"Selling its stock 指投資者賣出該公司的股份。"},{"en":"If shareholders lose confidence, they may start selling a company’s stock.","zh":"如果股東失去信心，他們可能開始沽售公司股票。"},{"en":"Heavy selling can push down the share price and signal market distrust.","zh":"大量沽售可以壓低股價，並顯示市場不信任。"},{"en":"This phrase describes a financial reaction to company decisions.","zh":"這個片語描述對公司決策的金融反應。"}],"source":"143 - We have Star performers!.pdf","sourcePage":10},{"front":"ironic","meaning":"諷刺的","examples":[{"en":"The reaction was ironic because the hire was meant to improve the share price.","zh":"這種反應很諷刺，因為該聘用本來是為了改善股價。"},{"en":"Ironic means strange or amusing because the result is opposite to what was expected.","zh":"Ironic 指結果與預期相反，因此顯得奇怪或帶諷刺意味。"},{"en":"It is ironic if a time-management app makes a student waste more time.","zh":"如果時間管理應用程式令學生浪費更多時間，那就很諷刺。"},{"en":"A company may hire a star to impress investors, only to make investors worried.","zh":"公司可能聘請明星來打動投資者，結果反而令投資者擔心。"},{"en":"This word highlights an unexpected contrast between intention and result.","zh":"這個詞突顯意圖與結果之間的意外對比。"}],"source":"143 - We have Star performers!.pdf","sourcePage":10},{"front":"in the first place","meaning":"起初；本來","examples":[{"en":"The motive for importing stars was often a weak share price in the first place.","zh":"引入明星人才的動機，本來常是股價疲弱。"},{"en":"In the first place means originally or at the beginning of the situation.","zh":"In the first place 指原本或情況一開始時。"},{"en":"The school bought new software because attendance records were messy in the first place.","zh":"學校購買新軟件，是因為出席紀錄本來就混亂。"},{"en":"If the original problem was weak management, hiring a star may not solve it.","zh":"如果原本問題是管理薄弱，聘用明星人才未必能解決。"},{"en":"This phrase points back to the original reason or starting condition.","zh":"這個片語指回原本原因或起始狀況。"}],"source":"143 - We have Star performers!.pdf","sourcePage":10},{"front":"share price","meaning":"股價","examples":[{"en":"A suffering share price often motivated companies to hire stars.","zh":"表現疲弱的股價常促使公司聘用明星人才。"},{"en":"Share price is the market price of one share in a company.","zh":"股價是公司一股股份在市場上的價格。"},{"en":"A company’s share price may fall when investors lose confidence.","zh":"當投資者失去信心，公司股價可能下跌。"},{"en":"Managers may make risky decisions if they focus too much on short-term share price.","zh":"如果管理層過度集中短期股價，可能作出冒險決定。"},{"en":"This phrase is central to how public companies are judged by investors.","zh":"這個片語是投資者評價上市公司的核心概念。"}],"source":"143 - We have Star performers!.pdf","sourcePage":11},{"front":"overpay","meaning":"支付過高薪酬","examples":[{"en":"Shareholders may believe that the company is overpaying for a star.","zh":"股東可能認為公司為明星人才支付過高薪酬。"},{"en":"To overpay means to pay more than something or someone is really worth.","zh":"To overpay 指支付超過某物或某人真正價值的金額。"},{"en":"A family may overpay for repairs if they do not compare prices.","zh":"如果家庭不比較價格，可能為維修支付過高費用。"},{"en":"Companies overpay when they reward a famous name more than actual future value.","zh":"當公司給名氣的報酬高於實際未來價值時，就是支付過高。"},{"en":"This word suggests poor judgement in spending.","zh":"這個詞暗示花錢判斷差。"}],"source":"143 - We have Star performers!.pdf","sourcePage":11},{"front":"hiree","meaning":"受聘者","examples":[{"en":"The hiree may be cashing in on past success.","zh":"受聘者可能正在利用過往成功賺取利益。"},{"en":"A hiree is the person who has been hired for a job.","zh":"Hiree 是被聘用做某份工作的人。"},{"en":"A new hiree may need training even if their previous record was excellent.","zh":"即使新受聘者過往紀錄優秀，也可能需要培訓。"},{"en":"If a hiree receives a huge salary, others may question whether the value is real.","zh":"如果受聘者得到巨額薪酬，其他人可能質疑其價值是否真實。"},{"en":"This word focuses on the recruited person, not the employer.","zh":"這個詞著重被招聘的人，而不是僱主。"}],"source":"143 - We have Star performers!.pdf","sourcePage":11},{"front":"cash in on","meaning":"利用……賺取利益","examples":[{"en":"A star may be cashing in on a glorious past.","zh":"明星人才可能正在利用輝煌過去賺取利益。"},{"en":"To cash in on something means to use it to gain money, advantage, or popularity.","zh":"To cash in on something 指利用某事獲得金錢、優勢或人氣。"},{"en":"A celebrity may cash in on fame by selling expensive products.","zh":"名人可能透過售賣昂貴產品來利用名氣賺取利益。"},{"en":"A worker with a famous past employer may cash in on that reputation during negotiations.","zh":"曾在著名公司工作的員工，可能在談判中利用那種聲譽。"},{"en":"This phrase often suggests taking advantage of past success.","zh":"這個片語常暗示利用過往成功。"}],"source":"143 - We have Star performers!.pdf","sourcePage":11},{"front":"glorious past","meaning":"輝煌過去","examples":[{"en":"The recruited star may be rewarded for a glorious past rather than current value.","zh":"被招聘的明星可能因輝煌過去而得到回報，而不是因當前價值。"},{"en":"A glorious past is a history of impressive success, fame, or achievement.","zh":"Glorious past 指充滿出色成功、名聲或成就的歷史。"},{"en":"An old sports club may have a glorious past but poor results today.","zh":"一間老牌體育會可能有輝煌過去，但今天成績差。"},{"en":"Paying someone for a glorious past can be risky if they no longer perform well.","zh":"如果某人已不再表現出色，為其輝煌過去付錢可能有風險。"},{"en":"This phrase contrasts past reputation with present usefulness.","zh":"這個片語對比過去名聲與當前用途。"}],"source":"143 - We have Star performers!.pdf","sourcePage":11},{"front":"glowing present","meaning":"光明的現在；亮眼的當前表現","examples":[{"en":"Investors doubt whether the star can produce a glowing present.","zh":"投資者懷疑該明星能否創造亮眼的當前表現。"},{"en":"A glowing present means strong current performance or impressive present results.","zh":"Glowing present 指強勁的當前表現或令人印象深刻的現時成果。"},{"en":"A school with a famous history still needs a glowing present to attract students today.","zh":"一所擁有著名歷史的學校，今天仍需要亮眼當前表現來吸引學生。"},{"en":"If a hire has only a glorious past but no glowing present, investors may worry.","zh":"如果受聘者只有輝煌過去而沒有亮眼現在，投資者可能擔心。"},{"en":"This phrase contrasts current achievement with past reputation.","zh":"這個片語對比當前成就與過去名聲。"}],"source":"143 - We have Star performers!.pdf","sourcePage":11},{"front":"spending spree","meaning":"瘋狂花錢","examples":[{"en":"Investors may fear that a spending spree is coming.","zh":"投資者可能擔心即將出現瘋狂花錢。"},{"en":"A spending spree is a period of buying or spending a lot of money quickly.","zh":"Spending spree 是短時間內大量購買或花費金錢的時期。"},{"en":"A family may go on a spending spree after receiving a large bonus.","zh":"一個家庭收到大額花紅後，可能開始瘋狂花錢。"},{"en":"A company spending spree can worry investors if purchases do not create value.","zh":"如果購買不能創造價值，公司瘋狂花錢會令投資者擔心。"},{"en":"This phrase often suggests uncontrolled or excessive spending.","zh":"這個片語常暗示不受控制或過度支出。"}],"source":"143 - We have Star performers!.pdf","sourcePage":11},{"front":"be in the offing","meaning":"即將發生","examples":[{"en":"A costly spending spree may be in the offing.","zh":"一場昂貴的瘋狂花錢可能即將發生。"},{"en":"If something is in the offing, it is likely to happen soon.","zh":"If something is in the offing，意思是它很可能很快發生。"},{"en":"Staff may feel that layoffs are in the offing when managers suddenly cut budgets.","zh":"當管理層突然削減預算，員工可能覺得裁員即將發生。"},{"en":"If investors think more star hires are in the offing, they may sell shares early.","zh":"如果投資者認為更多明星招聘即將發生，他們可能提早賣出股份。"},{"en":"This phrase suggests a likely future event.","zh":"這個片語暗示可能發生的未來事件。"}],"source":"143 - We have Star performers!.pdf","sourcePage":11},{"front":"mass star hirings","meaning":"大規模聘用明星人才","examples":[{"en":"Mass star hirings can damage a company’s performance.","zh":"大規模聘用明星人才可以損害公司表現。"},{"en":"Mass star hirings are large-scale recruitment of many famous or top-performing people.","zh":"Mass star hirings 指大規模招聘許多著名或頂尖表現者。"},{"en":"A bank may make mass star hirings to enter a new business area quickly.","zh":"銀行可能大規模聘用明星人才，以快速進入新業務領域。"},{"en":"Hiring many stars at once can raise costs and create cultural conflict.","zh":"一次過聘用許多明星可以提高成本並造成文化衝突。"},{"en":"This phrase describes a broad hiring strategy, not one single appointment.","zh":"這個片語描述廣泛招聘策略，而不是單一任命。"}],"source":"143 - We have Star performers!.pdf","sourcePage":11},{"front":"individual ones","meaning":"個別聘用","examples":[{"en":"Individual star hirings can also create problems.","zh":"個別明星招聘也可以造成問題。"},{"en":"Individual ones means single cases, not large groups.","zh":"Individual ones 指單一個案，而不是大群體。"},{"en":"A company may avoid mass hiring but still make risky individual ones.","zh":"公司可能避免大規模招聘，但仍作出有風險的個別聘用。"},{"en":"Even one expensive hire can disturb a team if the person does not fit.","zh":"即使只是一位昂貴受聘者，如果不適配，也可以擾亂團隊。"},{"en":"This phrase contrasts single actions with large-scale actions.","zh":"這個片語把單一行動與大規模行動作對比。"}],"source":"143 - We have Star performers!.pdf","sourcePage":11},{"front":"confirm such doubts","meaning":"證實這些疑慮","examples":[{"en":"The results of star hiring seem to confirm such doubts.","zh":"明星招聘的結果似乎證實這些疑慮。"},{"en":"To confirm such doubts means to provide evidence that earlier worries were reasonable.","zh":"To confirm such doubts 指提供證據，證明早前的擔心是合理的。"},{"en":"Poor exam results can confirm doubts about a new teaching method.","zh":"差劣考試成績可以證實人們對新教學方法的疑慮。"},{"en":"If a star hire fails, it may confirm doubts about the hiring strategy.","zh":"如果明星招聘失敗，可能證實人們對招聘策略的疑慮。"},{"en":"This phrase links evidence with suspicion or concern.","zh":"這個片語把證據與懷疑或擔憂連接起來。"}],"source":"143 - We have Star performers!.pdf","sourcePage":11},{"front":"look at","meaning":"看看；以……為例","examples":[{"en":"Look at the failures of firms that hired teams of stars.","zh":"看看那些聘用明星團隊的公司失敗例子。"},{"en":"Look at means consider or examine an example as evidence.","zh":"Look at 指把某例子作為證據來考慮或檢視。"},{"en":"Look at the school’s attendance records before blaming students.","zh":"在責怪學生之前，先看看學校的出席紀錄。"},{"en":"Managers should look at results, not just impressive résumés.","zh":"管理者應看看結果，而不只是看亮眼履歷。"},{"en":"This phrase often introduces an example that supports an argument.","zh":"這個片語常引出支持論點的例子。"}],"source":"143 - We have Star performers!.pdf","sourcePage":12},{"front":"with loud fanfare","meaning":"大張旗鼓地","examples":[{"en":"Some firms hired teams of stars with loud fanfare.","zh":"一些公司大張旗鼓地聘用明星團隊。"},{"en":"With loud fanfare means with much public attention, praise, and announcement.","zh":"With loud fanfare 指帶着大量公眾注意、讚揚和宣傳。"},{"en":"A company may launch a new product with loud fanfare to attract customers.","zh":"公司可能大張旗鼓地推出新產品以吸引顧客。"},{"en":"Public excitement can create pressure if the promised results do not appear.","zh":"如果承諾成果沒有出現，公眾興奮可能變成壓力。"},{"en":"This phrase suggests showy publicity.","zh":"這個片語暗示高調宣傳。"}],"source":"143 - We have Star performers!.pdf","sourcePage":12},{"front":"do great things","meaning":"成就大事","examples":[{"en":"The firms expected their star teams to do great things.","zh":"這些公司期望其明星團隊成就大事。"},{"en":"To do great things means to achieve impressive, important, or highly successful results.","zh":"To do great things 指取得令人印象深刻、重要或非常成功的成果。"},{"en":"Parents may hope their children will do great things, but support and patience are still needed.","zh":"父母可能希望孩子成就大事，但仍需要支援和耐性。"},{"en":"A talented team may fail to do great things if it lacks clear leadership.","zh":"有才華的團隊如果缺乏清晰領導，可能無法成就大事。"},{"en":"This phrase expresses high expectations.","zh":"這個片語表達高度期望。"}],"source":"143 - We have Star performers!.pdf","sourcePage":12},{"front":"investment banking","meaning":"投資銀行業","examples":[{"en":"Star teams were hired to succeed in investment banking.","zh":"明星團隊被聘用，以在投資銀行業取得成功。"},{"en":"Investment banking is a financial business that helps companies raise money, merge, buy other firms, or sell securities.","zh":"投資銀行業是幫助公司集資、合併、收購其他公司或出售證券的金融業務。"},{"en":"Investment banking often rewards reputation, contacts, and technical knowledge.","zh":"投資銀行業常重視聲譽、人脈和技術知識。"},{"en":"Hiring stars in investment banking can be expensive because top bankers may demand huge pay.","zh":"在投資銀行業聘用明星人才可能很昂貴，因為頂尖銀行家可能要求巨額薪酬。"},{"en":"This phrase refers to a specialised area of finance.","zh":"這個片語指金融中的專門領域。"}],"source":"143 - We have Star performers!.pdf","sourcePage":12},{"front":"fail dismally","meaning":"慘敗","examples":[{"en":"Both firms failed dismally despite hiring stars.","zh":"兩間公司儘管聘用了明星人才，仍慘敗。"},{"en":"To fail dismally means to fail very badly and obviously.","zh":"To fail dismally 指非常嚴重而明顯地失敗。"},{"en":"A new restaurant may fail dismally if food is slow, expensive, and poor.","zh":"如果新餐廳出餐慢、價錢貴且食物差，可能慘敗。"},{"en":"A star-hiring strategy can fail dismally when teamwork and systems are ignored.","zh":"當團隊合作和制度被忽視，明星招聘策略可能慘敗。"},{"en":"This phrase is stronger than simply “fail”.","zh":"這個片語比單純 “fail” 更強烈。"}],"source":"143 - We have Star performers!.pdf","sourcePage":12},{"front":"accept the cliché that","meaning":"接受……這句陳詞濫調","examples":[{"en":"Everyone accepts the cliché that people make the organisation.","zh":"人人都接受「人成就組織」這句陳詞濫調。"},{"en":"To accept the cliché that something is true means to believe a common saying that may be oversimplified.","zh":"To accept the cliché that something is true 指相信一個常見但可能過度簡化的說法。"},{"en":"Many people accept the cliché that hard work always guarantees success.","zh":"許多人接受「努力一定成功」這句陳詞濫調。"},{"en":"A cliché may contain some truth but still hide important details.","zh":"陳詞濫調可能包含部分真理，但仍隱藏重要細節。"},{"en":"This phrase questions an overused belief.","zh":"這個片語質疑過度使用的信念。"}],"source":"143 - We have Star performers!.pdf","sourcePage":12},{"front":"people make the organisation","meaning":"人成就組織","examples":[{"en":"The cliché says that people make the organisation.","zh":"這句陳詞濫調說，人成就組織。"},{"en":"People make the organisation means an organisation’s quality depends on the people inside it.","zh":"People make the organisation 指一個組織的質素取決於其中的人。"},{"en":"A school improves when teachers, students, and parents work with care.","zh":"當老師、學生和家長用心合作，學校就會改善。"},{"en":"However, people need good systems before their abilities can fully appear.","zh":"然而，人需要良好制度，其能力才能充分發揮。"},{"en":"This phrase is partly true, but the passage argues it is incomplete.","zh":"這個片語部分正確，但文章認為它並不完整。"}],"source":"143 - We have Star performers!.pdf","sourcePage":12},{"front":"the organisation makes the people","meaning":"組織成就人","examples":[{"en":"The writer argues that the organisation does even more to make the people.","zh":"作者認為，組織更大程度上成就人。"},{"en":"The organisation makes the people means the workplace shapes how people perform, learn, and behave.","zh":"The organisation makes the people 指工作場所塑造人們如何表現、學習和行動。"},{"en":"A good school system can help ordinary students become confident learners.","zh":"良好學校制度可以幫助普通學生成為自信學習者。"},{"en":"A weak organisation can make talented people look ineffective.","zh":"薄弱組織可以令有才華的人看起來無效。"},{"en":"This phrase reverses the usual belief that people alone create success.","zh":"這個片語反轉了「成功只由人創造」的常見看法。"}],"source":"143 - We have Star performers!.pdf","sourcePage":12},{"front":"study the performance of","meaning":"研究……的表現","examples":[{"en":"Researchers studied the performance of fund managers.","zh":"研究人員研究基金經理的表現。"},{"en":"To study the performance of people means to examine how well they do their work.","zh":"To study the performance of people 指檢視他們工作做得有多好。"},{"en":"A school may study the performance of students before changing its curriculum.","zh":"學校在改變課程前可能研究學生表現。"},{"en":"Researchers study performance to separate individual ability from environmental support.","zh":"研究人員研究表現，以區分個人能力和環境支援。"},{"en":"This phrase focuses on measured results, not personal impressions.","zh":"這個片語著重量度成果，而不是個人印象。"}],"source":"143 - We have Star performers!.pdf","sourcePage":12},{"front":"fund managers","meaning":"基金經理","examples":[{"en":"The study examined how fund managers performed in different firms.","zh":"該研究檢視基金經理在不同公司中的表現。"},{"en":"Fund managers are professionals who invest money for clients or investment funds.","zh":"基金經理是為客戶或投資基金投資金錢的專業人士。"},{"en":"A fund manager chooses stocks, bonds, or other assets to try to earn returns.","zh":"基金經理選擇股票、債券或其他資產，試圖賺取回報。"},{"en":"A fund manager’s results may depend on research support, company systems, and market conditions.","zh":"基金經理的成果可能取決於研究支援、公司制度和市場狀況。"},{"en":"This phrase refers to investment professionals who manage other people’s money.","zh":"這個片語指管理他人資金的投資專業人士。"}],"source":"143 - We have Star performers!.pdf","sourcePage":12},{"front":"variation in performance","meaning":"表現差異","examples":[{"en":"Most variation in fund performance came from the company setting.","zh":"基金表現的大部分差異來自公司環境。"},{"en":"Variation in performance means differences in results between people, teams, or periods.","zh":"Variation in performance 指人、團隊或時期之間的成果差別。"},{"en":"A teacher may study variation in performance between classes to find what works.","zh":"老師可能研究不同班級之間的表現差異，以找出有效方法。"},{"en":"Large variation in performance may show that environment matters more than talent alone.","zh":"大幅表現差異可能顯示環境比單靠才華更重要。"},{"en":"This phrase focuses on why results differ.","zh":"這個片語著重成果為何不同。"}],"source":"143 - We have Star performers!.pdf","sourcePage":12},{"front":"be due to the individual","meaning":"由個人造成","examples":[{"en":"Only part of the performance variation was due to the individual.","zh":"表現差異只有一部分由個人造成。"},{"en":"To be due to the individual means to be caused by that person’s own ability, choices, or effort.","zh":"To be due to the individual 指由該人的能力、選擇或努力造成。"},{"en":"A student’s success may be partly due to the individual and partly due to family support.","zh":"學生成功可能部分由個人造成，部分由家庭支援造成。"},{"en":"If only some results are due to the individual, managers should also examine systems.","zh":"如果只有部分成果由個人造成，管理層也應檢視制度。"},{"en":"This phrase separates personal contribution from environmental influence.","zh":"這個片語把個人貢獻與環境影響分開。"}],"source":"143 - We have Star performers!.pdf","sourcePage":13},{"front":"compared to","meaning":"與……相比","examples":[{"en":"Only 30 per cent was due to the individual, compared to 70 per cent to the firm.","zh":"只有30%由個人造成，與公司造成的70%相比。"},{"en":"Compared to means measured or considered beside something else.","zh":"Compared to 指與另一事物並列衡量或考慮。"},{"en":"This year’s rent is high compared to last year’s rent.","zh":"今年租金與去年租金相比很高。"},{"en":"If individual influence is small compared to system influence, hiring stars may be less useful.","zh":"如果個人影響與制度影響相比很小，聘用明星人才可能較不有用。"},{"en":"This phrase helps show relative size, importance, or difference.","zh":"這個片語有助顯示相對大小、重要性或差異。"}],"source":"143 - We have Star performers!.pdf","sourcePage":13},{"front":"company-specific setting","meaning":"公司特定環境","examples":[{"en":"Company-specific setting explained most of the performance variation.","zh":"公司特定環境解釋了大部分表現差異。"},{"en":"A company-specific setting is the particular environment, systems, culture, and support found in one company.","zh":"公司特定環境是指某一公司內特有的環境、制度、文化和支援。"},{"en":"A salesperson may succeed because of a company-specific setting such as brand reputation and customer data.","zh":"銷售員可能因品牌聲譽和客戶數據等公司特定環境而成功。"},{"en":"When someone leaves the company, that setting may no longer support them.","zh":"當某人離開公司，那個環境可能不再支援他。"},{"en":"This phrase explains why performance may not travel with the person.","zh":"這個片語解釋為何表現未必跟着人轉移。"}],"source":"143 - We have Star performers!.pdf","sourcePage":13},{"front":"familiar with","meaning":"熟悉……","examples":[{"en":"The result will not surprise those familiar with systems thinking.","zh":"這個結果不會令熟悉系統思維的人感到意外。"},{"en":"To be familiar with something means to know it well or have experience of it.","zh":"To be familiar with something 指熟知某事或對它有經驗。"},{"en":"A nurse familiar with the hospital system can find equipment quickly.","zh":"熟悉醫院系統的護士可以快速找到設備。"},{"en":"People familiar with teamwork understand that results depend on more than individual talent.","zh":"熟悉團隊合作的人明白成果不只取決於個人才華。"},{"en":"This phrase describes knowledge gained through study or experience.","zh":"這個片語描述透過學習或經驗得來的知識。"}],"source":"143 - We have Star performers!.pdf","sourcePage":13},{"front":"systems thinking","meaning":"系統思維","examples":[{"en":"Systems thinking emphasises the importance of organisational structures.","zh":"系統思維強調組織結構的重要性。"},{"en":"Systems thinking is a way of understanding problems by looking at how parts interact within a whole system.","zh":"系統思維是一種透過觀察各部分如何在整體系統中互動來理解問題的方法。"},{"en":"A school using systems thinking asks how timetable, teaching, sleep, and homework affect learning together.","zh":"使用系統思維的學校會問時間表、教學、睡眠和功課如何共同影響學習。"},{"en":"Systems thinking can prevent managers from blaming individuals for problems created by bad processes.","zh":"系統思維可以防止管理層把由差劣流程造成的問題歸咎於個人。"},{"en":"This phrase focuses on relationships and structures, not isolated people.","zh":"這個片語著重關係和結構，而不是孤立個人。"}],"source":"143 - We have Star performers!.pdf","sourcePage":13},{"front":"no point in","meaning":"做……沒有意義","examples":[{"en":"Deming argued that there was no point in blaming people alone.","zh":"Deming認為單單責怪人沒有意義。"},{"en":"There is no point in doing something means it is useless or not worth doing.","zh":"There is no point in doing something 指做某事沒有用或不值得。"},{"en":"There is no point in buying more books if students never have time to read them.","zh":"如果學生從來沒有時間閱讀，買更多書就沒有意義。"},{"en":"There is no point in blaming staff if the instructions are unclear.","zh":"如果指示不清晰，責怪員工就沒有意義。"},{"en":"This phrase shows that an action will not solve the real problem.","zh":"這個片語顯示某行動不能解決真正問題。"}],"source":"143 - We have Star performers!.pdf","sourcePage":13},{"front":"beat up on people","meaning":"苛責人；責罵人","examples":[{"en":"Deming said there was no point in beating up on people.","zh":"Deming說苛責人沒有意義。"},{"en":"To beat up on people means to criticise or blame them harshly.","zh":"To beat up on people 指嚴厲批評或責怪人。"},{"en":"A manager who beats up on staff after every mistake may create fear.","zh":"每次出錯後都責罵員工的經理可能製造恐懼。"},{"en":"Beating up on people does not fix bad training or broken processes.","zh":"苛責人不能修正差劣培訓或破裂流程。"},{"en":"This phrase is informal and critical of harsh blame.","zh":"這個片語較口語，批評嚴厲責怪。"}],"source":"143 - We have Star performers!.pdf","sourcePage":13},{"front":"be down to","meaning":"歸因於","examples":[{"en":"Most performance variation was down to the system.","zh":"大部分表現差異歸因於制度。"},{"en":"To be down to something means to be caused by or mainly explained by it.","zh":"To be down to something 指由某事造成或主要由某事解釋。"},{"en":"A student’s tiredness may be down to lack of sleep, not laziness.","zh":"學生疲倦可能歸因於睡眠不足，而不是懶惰。"},{"en":"If poor service is down to understaffing, blaming workers will not help.","zh":"如果服務差歸因於人手不足，責怪員工沒有幫助。"},{"en":"This phrase identifies the real cause.","zh":"這個片語指出真正原因。"}],"source":"143 - We have Star performers!.pdf","sourcePage":13},{"front":"within which","meaning":"在其中","examples":[{"en":"People work within a system that shapes their performance.","zh":"人們在塑造其表現的制度中工作。"},{"en":"Within which means inside which, or in the context of which.","zh":"Within which 指在其中，或在某個語境之內。"},{"en":"A classroom is a system within which students learn habits as well as facts.","zh":"課室是一個學生在其中學習習慣和知識的系統。"},{"en":"The rules within which people work can affect what they are able to achieve.","zh":"人們在其中工作的規則會影響他們能達成甚麼。"},{"en":"This phrase links people’s actions to the surrounding environment.","zh":"這個片語把人的行動與周圍環境連接起來。"}],"source":"143 - We have Star performers!.pdf","sourcePage":13},{"front":"consistent improvement","meaning":"持續改善","examples":[{"en":"Consistent improvement depends on organisational learning.","zh":"持續改善取決於組織學習。"},{"en":"Consistent improvement means steady progress over time, not one lucky success.","zh":"Consistent improvement 指隨時間穩定進步，而不是一次幸運成功。"},{"en":"A student achieves consistent improvement by practising a little every day and using feedback.","zh":"學生透過每天少量練習並使用回饋，可以取得持續改善。"},{"en":"A company needs learning systems if it wants consistent improvement across many teams.","zh":"如果公司想在多個團隊中持續改善，就需要學習制度。"},{"en":"This phrase values repeatable progress.","zh":"這個片語重視可重複的進步。"}],"source":"143 - We have Star performers!.pdf","sourcePage":13},{"front":"a matter not of A but of B","meaning":"不是A的問題，而是B的問題","examples":[{"en":"Improvement is a matter not of individual intelligence but of organisational learning.","zh":"改善不是個人智慧的問題，而是組織學習的問題。"},{"en":"A matter not of A but of B means the real issue is B, not A.","zh":"A matter not of A but of B 指真正問題是B，而不是A。"},{"en":"Good writing is a matter not of long words but of clear thinking.","zh":"好寫作不是長字的問題，而是清晰思考的問題。"},{"en":"If performance depends on systems, improvement is not a matter of hiring stars but of learning together.","zh":"如果表現取決於制度，改善就不是聘用明星的問題，而是共同學習的問題。"},{"en":"This structure is useful for correcting a mistaken focus.","zh":"這個結構適合修正錯誤焦點。"}],"source":"143 - We have Star performers!.pdf","sourcePage":13},{"front":"raising the level of","meaning":"提高……的水平","examples":[{"en":"Performance improvement is not simply about raising the level of individual intelligence.","zh":"表現改善不只是提高個人智慧水平。"},{"en":"Raising the level of something means increasing its amount, quality, or standard.","zh":"Raising the level of something 指提高某事的數量、質素或標準。"},{"en":"Extra reading can raise the level of a student’s vocabulary.","zh":"額外閱讀可以提高學生詞彙水平。"},{"en":"Raising the level of individual skill may not help if the system blocks good work.","zh":"如果制度阻礙良好工作，提高個人技能水平未必有用。"},{"en":"This phrase describes improvement in a measurable or noticeable quality.","zh":"這個片語描述可量度或可察覺特質的改善。"}],"source":"143 - We have Star performers!.pdf","sourcePage":14},{"front":"the organisation as a whole","meaning":"整個組織","examples":[{"en":"Learning must occur in the organisation as a whole.","zh":"學習必須發生在整個組織中。"},{"en":"The organisation as a whole means the entire organisation, not only one person or department.","zh":"The organisation as a whole 指整個組織，而不只是某個人或部門。"},{"en":"A school improves when the organisation as a whole learns from exam results.","zh":"當整個組織從考試結果中學習，學校便會改善。"},{"en":"If only one team learns, the organisation as a whole may still repeat the same mistakes.","zh":"如果只有一個團隊學習，整個組織仍可能重複同樣錯誤。"},{"en":"This phrase emphasises system-wide change.","zh":"這個片語強調系統層面的改變。"}],"source":"143 - We have Star performers!.pdf","sourcePage":14},{"front":"the star system","meaning":"明星制度","examples":[{"en":"The star system is glamorous for a few people.","zh":"明星制度對少數人來說很光鮮。"},{"en":"The star system is an arrangement that gives special attention, pay, and status to a small number of top performers.","zh":"明星制度是一種給少數頂尖表現者特殊關注、薪酬和地位的安排。"},{"en":"A company using the star system may celebrate a few famous employees while ignoring the wider team.","zh":"使用明星制度的公司可能表揚少數著名員工，同時忽視更廣泛團隊。"},{"en":"The star system can create resentment if rewards feel unfair.","zh":"如果獎勵感覺不公平，明星制度可能造成怨氣。"},{"en":"This phrase describes a culture built around exceptional individuals.","zh":"這個片語描述圍繞卓越個人建立的文化。"}],"source":"143 - We have Star performers!.pdf","sourcePage":14},{"front":"glamorous for the few","meaning":"對少數人來說光鮮","examples":[{"en":"The star system may be glamorous for the few but harmful to the firm.","zh":"明星制度對少數人來說可能很光鮮，但對公司有害。"},{"en":"Glamorous for the few means attractive and exciting for a small number of people only.","zh":"Glamorous for the few 指只對少數人吸引和令人興奮。"},{"en":"A bonus scheme may be glamorous for the few who win, but discouraging for everyone else.","zh":"花紅制度對少數勝出者可能很光鮮，但對其他人令人沮喪。"},{"en":"When a system benefits only a few stars, wider morale can suffer.","zh":"當制度只惠及少數明星，整體士氣可能受損。"},{"en":"This phrase contrasts visible rewards for a minority with hidden costs for the group.","zh":"這個片語對比少數人的可見獎賞和群體的隱藏成本。"}],"source":"143 - We have Star performers!.pdf","sourcePage":14},{"front":"benefit the company","meaning":"令公司受益","examples":[{"en":"The star system rarely benefits the company that uses it.","zh":"明星制度很少令使用它的公司受益。"},{"en":"To benefit the company means to help the company improve, earn more, or become stronger.","zh":"To benefit the company 指幫助公司改善、賺更多或變得更強。"},{"en":"Training junior staff can benefit the company by creating future managers.","zh":"培訓初級員工可以透過培養未來經理來令公司受益。"},{"en":"A decision may benefit one employee but still harm the company as a whole.","zh":"一個決定可能令某位員工受益，但仍損害整間公司。"},{"en":"This phrase focuses on organisational advantage.","zh":"這個片語著重組織層面的好處。"}],"source":"143 - We have Star performers!.pdf","sourcePage":14},{"front":"to one’s advantage","meaning":"對……有利","examples":[{"en":"Some firms wrongly believe they can use the star system to their advantage.","zh":"一些公司錯誤地相信可以利用明星制度使其對自己有利。"},{"en":"To one’s advantage means in a way that helps or benefits that person or group.","zh":"To one’s advantage 指以幫助或有利於某人或某群體的方式。"},{"en":"A student can use feedback to their advantage by correcting mistakes before the exam.","zh":"學生可以利用回饋對自己有利，在考試前修正錯誤。"},{"en":"A company may think high-profile hiring works to its advantage, but the costs may be hidden.","zh":"公司可能認為高調招聘對自己有利，但成本可能被隱藏。"},{"en":"This phrase describes benefit from a situation or tool.","zh":"這個片語描述從某情況或工具中得到好處。"}],"source":"143 - We have Star performers!.pdf","sourcePage":14},{"front":"knock-on consequences","meaning":"連鎖後果","examples":[{"en":"The knock-on consequences of the star system affect many employees.","zh":"明星制度的連鎖後果影響許多員工。"},{"en":"Knock-on consequences are indirect effects that happen because one event causes another.","zh":"Knock-on consequences 是一件事引發另一件事而產生的間接影響。"},{"en":"A delayed train can have knock-on consequences for work, childcare, and appointments.","zh":"火車延誤可以對工作、托兒和約會產生連鎖後果。"},{"en":"Hiring one star may have knock-on consequences for salaries, morale, and teamwork.","zh":"聘用一位明星可能對薪酬、士氣和團隊合作產生連鎖後果。"},{"en":"This phrase describes chain reactions.","zh":"這個片語描述連鎖反應。"}],"source":"143 - We have Star performers!.pdf","sourcePage":14},{"front":"indirectly affect","meaning":"間接影響","examples":[{"en":"The star system can indirectly affect everyone else.","zh":"明星制度可以間接影響其他所有人。"},{"en":"To indirectly affect someone means to influence them through another person, event, or process.","zh":"To indirectly affect someone 指透過另一個人、事件或過程影響某人。"},{"en":"A rent rise can indirectly affect students if their parents must work longer hours.","zh":"如果父母因租金上升而要工作更長時間，學生可能被間接影響。"},{"en":"A star hire indirectly affects colleagues when budgets and attention shift toward that person.","zh":"當預算和注意力轉向明星員工，明星招聘便會間接影響同事。"},{"en":"This phrase describes influence that is not immediate or direct.","zh":"這個片語描述不是即時或直接的影響。"}],"source":"143 - We have Star performers!.pdf","sourcePage":14},{"front":"corporate America","meaning":"美國企業界","examples":[{"en":"The writer refers to the wider problems of corporate America after Enron.","zh":"作者提到安然事件後美國企業界更廣泛的問題。"},{"en":"Corporate America means the world of large American companies and business culture.","zh":"Corporate America 指美國大型公司和商業文化的世界。"},{"en":"Corporate America can influence management ideas used in other countries.","zh":"美國企業界可以影響其他國家使用的管理理念。"},{"en":"Scandals in corporate America can make investors question business leadership more broadly.","zh":"美國企業界的醜聞可以令投資者更廣泛地質疑商業領導。"},{"en":"This phrase refers to a business system, not all American people.","zh":"這個片語指商業系統，而不是所有美國人。"}],"source":"143 - We have Star performers!.pdf","sourcePage":14},{"front":"be stuck with","meaning":"被迫承受；擺脫不了","examples":[{"en":"Companies may be stuck with overpaid and underachieving talent.","zh":"公司可能被迫承受薪酬過高且表現未達預期的人才。"},{"en":"To be stuck with something means to be forced to keep or deal with something unwanted.","zh":"To be stuck with something 指被迫保留或處理不想要的東西。"},{"en":"A family may be stuck with a broken appliance if repair costs are too high.","zh":"如果維修費太高，家庭可能被迫承受壞了的電器。"},{"en":"A company can be stuck with an expensive hire who does not fit the team.","zh":"公司可能擺脫不了一位昂貴但不適合團隊的受聘者。"},{"en":"This phrase suggests a difficult situation that is hard to escape.","zh":"這個片語暗示難以逃離的困境。"}],"source":"143 - We have Star performers!.pdf","sourcePage":14},{"front":"overpaid","meaning":"薪酬過高的","examples":[{"en":"Some star employees are overpaid relative to their real contribution.","zh":"一些明星員工相對其真正貢獻而言薪酬過高。"},{"en":"Overpaid means paid more money than the person’s work or value justifies.","zh":"Overpaid 指薪酬高於其工作或價值所能合理支持的水平。"},{"en":"A manager may be overpaid if their team fails but their bonus remains huge.","zh":"如果經理的團隊失敗但花紅仍巨大，他可能薪酬過高。"},{"en":"Overpaid workers can create resentment when others feel they do more for less.","zh":"當其他人覺得自己做得更多卻收得更少，薪酬過高的員工可能造成怨氣。"},{"en":"This word criticises the relationship between pay and contribution.","zh":"這個詞批評薪酬與貢獻之間的關係。"}],"source":"143 - We have Star performers!.pdf","sourcePage":14},{"front":"arrogant","meaning":"傲慢的","examples":[{"en":"The article criticises some star employees as arrogant.","zh":"文章批評一些明星員工傲慢。"},{"en":"Arrogant means believing you are better or more important than other people.","zh":"Arrogant 指相信自己比別人更好或更重要。"},{"en":"An arrogant student may ignore classmates’ ideas during group work.","zh":"傲慢的學生可能在小組工作中忽視同學想法。"},{"en":"Arrogance can stop people from learning because they think they already know enough.","zh":"傲慢會阻止人學習，因為他們以為自己已經知道足夠。"},{"en":"This word is negative and describes attitude, not ability.","zh":"這個詞是負面的，描述態度而不是能力。"}],"source":"143 - We have Star performers!.pdf","sourcePage":15},{"front":"underachieving","meaning":"表現未達預期的","examples":[{"en":"Some expensive talent becomes underachieving in a new system.","zh":"一些昂貴人才在新制度中變得表現未達預期。"},{"en":"Underachieving means performing below one’s expected ability or potential.","zh":"Underachieving 指表現低於預期能力或潛力。"},{"en":"A bright student may become underachieving if lessons are confusing and support is weak.","zh":"如果課堂混亂且支援薄弱，聰明學生可能變得表現未達預期。"},{"en":"A star employee can become underachieving when the new workplace removes their old advantages.","zh":"當新工作場所移除舊有優勢，明星員工可能變得表現未達預期。"},{"en":"This word compares actual performance with expected performance.","zh":"這個詞比較實際表現與預期表現。"}],"source":"143 - We have Star performers!.pdf","sourcePage":15},{"front":"relatively useless","meaning":"相對無用的","examples":[{"en":"The response described such talent as relatively useless.","zh":"這個回應把這類人才描述為相對無用。"},{"en":"Relatively useless means not very useful compared with what was expected or compared with alternatives.","zh":"Relatively useless 指與預期或其他選項相比不太有用。"},{"en":"An expensive app is relatively useless if staff cannot learn how to use it.","zh":"如果員工學不會使用，昂貴應用程式就相對無用。"},{"en":"A star hire may be relatively useless if the company lacks the system they need.","zh":"如果公司缺乏明星人才所需的制度，該聘用可能相對無用。"},{"en":"This phrase is harsh and comparative, not an absolute scientific measure.","zh":"這個片語語氣嚴厲且具比較性，不是絕對科學量度。"}],"source":"143 - We have Star performers!.pdf","sourcePage":15},{"front":"another illustration of","meaning":"……的另一個例子","examples":[{"en":"Football is another illustration of the star-versus-system choice.","zh":"足球是明星與制度取捨的另一個例子。"},{"en":"Another illustration of something means another example that helps explain it.","zh":"Another illustration of something 指幫助解釋某事的另一個例子。"},{"en":"A school project is another illustration of why teamwork matters more than one clever student.","zh":"學校專題是為何團隊合作比一位聰明學生更重要的另一個例子。"},{"en":"Examples from sport can illustrate business ideas in a simpler way.","zh":"體育例子可以用較簡單方式說明商業理念。"},{"en":"This phrase introduces supporting evidence from a different context.","zh":"這個片語引入來自不同語境的支持證據。"}],"source":"143 - We have Star performers!.pdf","sourcePage":15},{"front":"star-versus-system","meaning":"明星與制度之間的取捨","examples":[{"en":"The passage discusses a star-versus-system strategic choice.","zh":"文章討論明星與制度之間的策略取捨。"},{"en":"Star-versus-system means a choice between relying on exceptional individuals and relying on strong structures.","zh":"Star-versus-system 指在依賴卓越個人和依賴強大結構之間作選擇。"},{"en":"A school faces a star-versus-system choice when it hires famous teachers instead of training all teachers well.","zh":"當學校聘用名師而不是好好培訓所有老師時，就面對明星與制度之間的取捨。"},{"en":"If the system is weak, stars may not create lasting success.","zh":"如果制度薄弱，明星人才未必能創造持久成功。"},{"en":"This phrase captures the central contrast in the article.","zh":"這個片語概括文章的核心對比。"}],"source":"143 - We have Star performers!.pdf","sourcePage":15},{"front":"strategic choice","meaning":"策略選擇","examples":[{"en":"Football illustrates the strategic choice between stars and systems.","zh":"足球說明明星與制度之間的策略選擇。"},{"en":"A strategic choice is an important decision about how to achieve long-term goals.","zh":"Strategic choice 是關於如何達成長期目標的重要決定。"},{"en":"A small business makes a strategic choice when it chooses quality service over low prices.","zh":"小企業選擇優質服務而不是低價時，就是作出策略選擇。"},{"en":"Choosing stars over systems can shape costs, culture, and future performance.","zh":"選擇明星而不是制度，可以塑造成本、文化和未來表現。"},{"en":"This phrase describes a major direction, not a small daily decision.","zh":"這個片語描述重大方向，而不是日常小決定。"}],"source":"143 - We have Star performers!.pdf","sourcePage":15},{"front":"as with","meaning":"正如……一樣","examples":[{"en":"As with investment banks, football clubs can overvalue stars.","zh":"正如投資銀行一樣，足球會也可能高估明星。"},{"en":"As with means in the same way as or similar to.","zh":"As with 指正如某事一樣或與某事相似。"},{"en":"As with language learning, music practice improves through repetition and feedback.","zh":"正如語言學習一樣，音樂練習也透過重複和回饋改善。"},{"en":"As with companies, sports teams need systems as well as talented individuals.","zh":"正如公司一樣，運動隊伍不只需要有才華的人，也需要制度。"},{"en":"This phrase links two situations that share a pattern.","zh":"這個片語連接兩個具有共同模式的情況。"}],"source":"143 - We have Star performers!.pdf","sourcePage":15},{"front":"stockbrokers","meaning":"股票經紀","examples":[{"en":"The writer compares football clubs with investment banks and stockbrokers.","zh":"作者把足球會與投資銀行和股票經紀作比較。"},{"en":"Stockbrokers are professionals who buy and sell shares for clients.","zh":"股票經紀是為客戶買賣股票的專業人士。"},{"en":"A stockbroker may advise clients when to buy or sell a company’s stock.","zh":"股票經紀可能建議客戶何時買入或賣出公司股票。"},{"en":"Like other finance professionals, stockbrokers may be judged by performance and reputation.","zh":"像其他金融專業人士一樣，股票經紀可能按表現和聲譽被評價。"},{"en":"This word refers to people working in financial markets.","zh":"這個詞指在金融市場工作的人。"}],"source":"143 - We have Star performers!.pdf","sourcePage":15},{"front":"be down to money","meaning":"取決於金錢","examples":[{"en":"It seems obvious that football success should be down to money.","zh":"足球成功似乎明顯應該取決於金錢。"},{"en":"To be down to money means to be mainly caused or decided by financial resources.","zh":"To be down to money 指主要由財務資源造成或決定。"},{"en":"A school’s new facilities may be down to money from donors.","zh":"學校的新設施可能取決於捐款人的資金。"},{"en":"If success were only down to money, the richest team would always win.","zh":"如果成功只取決於金錢，最富有的隊伍就會永遠勝出。"},{"en":"This phrase identifies money as the supposed cause.","zh":"這個片語把金錢指出為假定原因。"}],"source":"143 - We have Star performers!.pdf","sourcePage":15},{"front":"scarce and expensive","meaning":"稀缺而昂貴的","examples":[{"en":"Great players are scarce and expensive.","zh":"偉大球員稀缺而昂貴。"},{"en":"Scarce and expensive means hard to find and costly to obtain.","zh":"Scarce and expensive 指難以找到且取得成本高。"},{"en":"Good childcare places can be scarce and expensive in crowded cities.","zh":"在擁擠城市，優質托兒名額可能稀缺而昂貴。"},{"en":"When skilled workers are scarce and expensive, firms may overpay to hire them.","zh":"當熟練工人稀缺而昂貴，公司可能支付過高薪酬來聘用他們。"},{"en":"This phrase explains why competition for something becomes intense.","zh":"這個片語解釋為何某物的競爭變得激烈。"}],"source":"143 - We have Star performers!.pdf","sourcePage":15},{"front":"afford more of them","meaning":"負擔得起更多這類人","examples":[{"en":"The richest club can afford more great players than others.","zh":"最富有的球會比其他球會負擔得起更多偉大球員。"},{"en":"To afford more of them means to have enough money to buy or hire a larger number of those things or people.","zh":"To afford more of them 指有足夠金錢購買或聘用更多這類東西或人。"},{"en":"A large school may afford more specialist teachers than a small school.","zh":"大型學校可能比小型學校負擔得起更多專科老師。"},{"en":"Being able to afford more stars does not guarantee better teamwork.","zh":"能負擔更多明星並不保證更好團隊合作。"},{"en":"This phrase connects financial power with purchasing ability.","zh":"這個片語把財力與購買能力連接起來。"}],"source":"143 - We have Star performers!.pdf","sourcePage":15},{"front":"prove that","meaning":"證明","examples":[{"en":"The examples of football clubs prove that success is not that simple.","zh":"足球會的例子證明成功並沒有那麼簡單。"},{"en":"To prove that something is true means to show it clearly with evidence.","zh":"To prove that something is true 指用證據清楚顯示某事是真的。"},{"en":"A student’s improved test results can prove that regular practice helped.","zh":"學生考試成績改善可以證明定期練習有幫助。"},{"en":"One expensive failure can prove that money alone is not enough.","zh":"一次昂貴失敗可以證明單靠金錢不足夠。"},{"en":"This phrase links evidence with a conclusion.","zh":"這個片語把證據與結論連接起來。"}],"source":"143 - We have Star performers!.pdf","sourcePage":16},{"front":"not as easy as that","meaning":"並沒有那麼簡單","examples":[{"en":"The success of a football club is not as easy as that.","zh":"足球會的成功並沒有那麼簡單。"},{"en":"Not as easy as that means the situation is more complicated than the simple explanation suggests.","zh":"Not as easy as that 指情況比簡單解釋所暗示的更複雜。"},{"en":"Getting fit is not as easy as buying a gym membership.","zh":"健身並沒有買健身會籍那麼簡單。"},{"en":"Building a strong team is not as easy as hiring talented people.","zh":"建立強大團隊並沒有聘用有才華的人那麼簡單。"},{"en":"This phrase warns against oversimplifying a problem.","zh":"這個片語提醒人不要過度簡化問題。"}],"source":"143 - We have Star performers!.pdf","sourcePage":16},{"front":"compulsive star collectors","meaning":"強迫式收集明星球員者","examples":[{"en":"Chelsea and Real Madrid are described as compulsive star collectors.","zh":"Chelsea和Real Madrid被描述為強迫式收集明星球員者。"},{"en":"Compulsive star collectors are teams or organisations that keep buying famous talent almost automatically.","zh":"Compulsive star collectors 是幾乎自動不斷購買著名人才的團隊或組織。"},{"en":"A company becomes a compulsive star collector if it hires every famous expert without asking whether they fit.","zh":"如果公司聘用每位著名專家卻不問是否適合，就是強迫式收集明星。"},{"en":"Collecting stars compulsively can create imbalance and waste money.","zh":"強迫式收集明星可能造成失衡並浪費金錢。"},{"en":"The phrase is critical and suggests uncontrolled behaviour.","zh":"這個片語帶批評意味，暗示行為不受控制。"}],"source":"143 - We have Star performers!.pdf","sourcePage":16},{"front":"put much more emphasis on","meaning":"更加重視","examples":[{"en":"Arsenal and Manchester United put much more emphasis on developing a system.","zh":"Arsenal和Manchester United更加重視發展制度。"},{"en":"To put much more emphasis on something means to give it far greater importance or attention.","zh":"To put much more emphasis on something 指給予某事大得多的重要性或注意力。"},{"en":"A school may put much more emphasis on reading than on memorising grammar rules.","zh":"學校可能更加重視閱讀，而不是背誦文法規則。"},{"en":"If a club puts more emphasis on systems, young players may develop better.","zh":"如果球會更加重視制度，年輕球員可能發展得更好。"},{"en":"This phrase shows priority.","zh":"這個片語顯示優先次序。"}],"source":"143 - We have Star performers!.pdf","sourcePage":16},{"front":"stars-in-the-making","meaning":"正在成長中的明星","examples":[{"en":"Strong systems allow stars-in-the-making to flourish.","zh":"強大制度讓正在成長中的明星茁壯發展。"},{"en":"Stars-in-the-making are people who are not famous yet but have the potential to become stars.","zh":"Stars-in-the-making 是尚未成名但有潛力成為明星的人。"},{"en":"A junior teacher may be a star-in-the-making if they learn quickly and receive good mentoring.","zh":"如果初級老師學得快並得到良好指導，可能是正在成長中的明星。"},{"en":"Strong systems help future stars grow instead of forcing companies to buy famous names.","zh":"強大制度幫助未來明星成長，而不是迫使公司購買名人。"},{"en":"This phrase focuses on developing potential.","zh":"這個片語著重培養潛力。"}],"source":"143 - We have Star performers!.pdf","sourcePage":16},{"front":"flourish","meaning":"茁壯成長；發揮出色","examples":[{"en":"Young players can flourish in the right system.","zh":"年輕球員可以在合適制度中茁壯成長。"},{"en":"To flourish means to grow, develop, and succeed strongly.","zh":"To flourish 指強健地成長、發展和成功。"},{"en":"Students flourish when teachers give clear goals, encouragement, and useful feedback.","zh":"當老師提供清晰目標、鼓勵和有用回饋，學生會茁壯成長。"},{"en":"Talent may not flourish if the environment is confusing or hostile.","zh":"如果環境混亂或充滿敵意，才華可能無法發揮出色。"},{"en":"This word suggests healthy growth and strong performance.","zh":"這個字暗示健康成長和強勁表現。"}],"source":"143 - We have Star performers!.pdf","sourcePage":16},{"front":"significantly","meaning":"值得注意的是","examples":[{"en":"Significantly, several Arsenal players became bigger stars after joining the club.","zh":"值得注意的是，幾名Arsenal球員加入球會後成為更大明星。"},{"en":"Significantly means importantly or in a way that deserves attention.","zh":"Significantly 指重要地，或以值得注意的方式。"},{"en":"Significantly, students improved most after feedback became more specific.","zh":"值得注意的是，學生在回饋變得更具體後進步最大。"},{"en":"A detail is significant when it changes how we understand the result.","zh":"當某細節改變我們對結果的理解，它就是重要的。"},{"en":"This word tells readers that the following point matters.","zh":"這個詞告訴讀者接下來的重點很重要。"}],"source":"143 - We have Star performers!.pdf","sourcePage":16},{"front":"in all senses","meaning":"從各方面而言","examples":[{"en":"Their value increased in all senses under the Arsenal system.","zh":"在Arsenal制度下，他們的價值從各方面而言都增加了。"},{"en":"In all senses means in every important meaning or aspect.","zh":"In all senses 指在每個重要意思或方面上。"},{"en":"A student may grow in all senses: academically, socially, and emotionally.","zh":"學生可以從各方面成長：學業、社交和情緒。"},{"en":"A player’s value can rise in all senses if skill, confidence, reputation, and market price all improve.","zh":"如果技能、信心、聲譽和市場價格都改善，球員價值便從各方面上升。"},{"en":"This phrase emphasises complete or multi-dimensional improvement.","zh":"這個片語強調全面或多層面的改善。"}],"source":"143 - We have Star performers!.pdf","sourcePage":16},{"front":"be enhanced by","meaning":"由……提升","examples":[{"en":"The players’ value was enhanced by the Arsenal system.","zh":"球員的價值由Arsenal制度提升。"},{"en":"To be enhanced by something means to be improved or made more valuable by it.","zh":"To be enhanced by something 指因某事而改善或變得更有價值。"},{"en":"A lesson is enhanced by clear examples and student practice.","zh":"清晰例子和學生練習可以提升一堂課。"},{"en":"Talent can be enhanced by coaching, structure, and supportive teammates.","zh":"才華可以由教練、結構和支持性隊友提升。"},{"en":"This phrase shows what makes something better.","zh":"這個片語顯示甚麼令某物變得更好。"}],"source":"143 - We have Star performers!.pdf","sourcePage":16},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"At Chelsea, by contrast, the context was just the stars themselves.","zh":"相比之下，在Chelsea，語境就只是明星本身。"},{"en":"By contrast introduces a difference from what has just been described.","zh":"By contrast 用來引出與剛才描述內容不同的地方。"},{"en":"Some students learn best through reading; by contrast, others need discussion.","zh":"有些學生最適合透過閱讀學習；相比之下，另一些需要討論。"},{"en":"Arsenal built a system; by contrast, Chelsea focused more on stars.","zh":"Arsenal建立制度；相比之下，Chelsea較集中於明星。"},{"en":"This phrase helps organise comparison clearly.","zh":"這個片語有助清楚組織比較。"}],"source":"143 - We have Star performers!.pdf","sourcePage":16},{"front":"come and go","meaning":"來來去去；不斷更替","examples":[{"en":"Managers with different outlooks come and go every few seasons.","zh":"不同觀點的經理每隔幾個球季來來去去。"},{"en":"To come and go means to arrive and leave repeatedly over time.","zh":"To come and go 指隨時間反覆到來和離開。"},{"en":"Temporary teachers may come and go if a school cannot keep staff.","zh":"如果學校留不住員工，臨時老師可能不斷更替。"},{"en":"When leaders come and go too often, a team may lack direction.","zh":"當領導者太頻繁更替，團隊可能缺乏方向。"},{"en":"This phrase suggests instability or repeated change.","zh":"這個片語暗示不穩定或反覆變動。"}],"source":"143 - We have Star performers!.pdf","sourcePage":16},{"front":"every couple of seasons","meaning":"每隔幾個球季","examples":[{"en":"Managers changed every couple of seasons.","zh":"經理每隔幾個球季就更換。"},{"en":"Every couple of seasons means roughly every two playing seasons.","zh":"Every couple of seasons 指大約每兩個球季。"},{"en":"A football club that changes managers every couple of seasons may struggle to build a stable style.","zh":"每隔幾個球季就更換經理的足球會，可能難以建立穩定風格。"},{"en":"Frequent change can stop players from fully learning one system.","zh":"頻繁變動會阻止球員完全學會一套制度。"},{"en":"This phrase describes repeated change over a short sporting cycle.","zh":"這個片語描述在短體育週期內反覆變動。"}],"source":"143 - We have Star performers!.pdf","sourcePage":17},{"front":"settled system","meaning":"穩定制度","examples":[{"en":"There was no settled system for the stars to blend into.","zh":"沒有穩定制度讓明星球員融入。"},{"en":"A settled system is a stable and clearly understood way of working.","zh":"Settled system 是穩定而清楚理解的工作方式。"},{"en":"A school with a settled system has clear routines for lessons, homework, and support.","zh":"有穩定制度的學校，在課堂、功課和支援方面有清晰常規。"},{"en":"Without a settled system, talented people may not know how to cooperate.","zh":"沒有穩定制度，有才華的人可能不知道如何合作。"},{"en":"This phrase stresses stability and shared understanding.","zh":"這個片語強調穩定和共同理解。"}],"source":"143 - We have Star performers!.pdf","sourcePage":17},{"front":"blend into","meaning":"融入","examples":[{"en":"Stars need a settled system to blend into.","zh":"明星人才需要穩定制度來融入。"},{"en":"To blend into something means to fit smoothly into it and become part of it.","zh":"To blend into something 指順利適應並成為其中一部分。"},{"en":"A new student blends into a class more easily when classmates include them.","zh":"當同學接納新學生，新學生更容易融入班級。"},{"en":"A star recruit may fail if they cannot blend into the team’s routines.","zh":"如果明星新員工無法融入團隊常規，可能會失敗。"},{"en":"This phrase focuses on fitting in, not standing apart.","zh":"這個片語著重融入，而不是突出自己。"}],"source":"143 - We have Star performers!.pdf","sourcePage":17},{"front":"add value","meaning":"增值；增加價值","examples":[{"en":"A strong context can add value to talented people.","zh":"強大語境可以為有才華的人增值。"},{"en":"To add value means to make something or someone more useful, effective, or valuable.","zh":"To add value 指令某物或某人更有用、更有效或更有價值。"},{"en":"A good teacher adds value by turning a textbook into clear learning.","zh":"好老師透過把教科書變成清晰學習來增加價值。"},{"en":"A strong team system can add value to a young player by helping them improve.","zh":"強大的團隊制度可以透過幫助年輕球員進步而為他增值。"},{"en":"This phrase shows how support increases performance.","zh":"這個片語顯示支援如何提升表現。"}],"source":"143 - We have Star performers!.pdf","sourcePage":17},{"front":"subtract value","meaning":"減值；削弱價值","examples":[{"en":"A weak context may subtract value from expensive talent.","zh":"薄弱語境可能削弱昂貴人才的價值。"},{"en":"To subtract value means to reduce usefulness, effectiveness, or worth.","zh":"To subtract value 指降低有用性、有效性或價值。"},{"en":"A confusing workplace can subtract value from a skilled employee.","zh":"混亂工作場所可以削弱熟練員工的價值。"},{"en":"Poor management may subtract value by making people waste time and lose confidence.","zh":"差劣管理可能透過令人浪費時間和失去信心而減值。"},{"en":"This phrase is the opposite of “add value”.","zh":"這個片語是 “add value” 的相反。"}],"source":"143 - We have Star performers!.pdf","sourcePage":17},{"front":"less than the sum of its parts","meaning":"整體小於各部分之和","examples":[{"en":"The side is less than the sum of its expensive parts.","zh":"這支球隊整體小於其昂貴部分之和。"},{"en":"Less than the sum of its parts means a group performs worse than its individual members should suggest.","zh":"Less than the sum of its parts 指團隊表現比其個別成員應有水平更差。"},{"en":"A group of clever students may be less than the sum of its parts if they argue constantly.","zh":"如果一群聰明學生不斷爭論，他們的整體可能小於各部分之和。"},{"en":"Poor coordination can make an expensive team perform below its combined talent.","zh":"差劣協調可以令昂貴團隊表現低於其合計才華。"},{"en":"This phrase criticises weak integration.","zh":"這個片語批評整合薄弱。"}],"source":"143 - We have Star performers!.pdf","sourcePage":17},{"front":"exorbitantly expensive","meaning":"昂貴得離譜的","examples":[{"en":"The team was made of exorbitantly expensive players.","zh":"這支球隊由昂貴得離譜的球員組成。"},{"en":"Exorbitantly expensive means far too costly or unreasonably expensive.","zh":"Exorbitantly expensive 指成本過高或貴得不合理。"},{"en":"A simple repair becomes exorbitantly expensive if the company adds hidden charges.","zh":"如果公司加入隱藏收費，簡單維修會變得昂貴得離譜。"},{"en":"Exorbitantly expensive players can damage a club’s budget if they do not perform together.","zh":"如果昂貴得離譜的球員不能合作，便會損害球會預算。"},{"en":"This phrase strongly criticises high cost.","zh":"這個片語強烈批評高成本。"}],"source":"143 - We have Star performers!.pdf","sourcePage":17},{"front":"galacticos","meaning":"銀河艦隊巨星球員","examples":[{"en":"Real Madrid’s galacticos were extravagantly gifted footballers.","zh":"Real Madrid的銀河艦隊巨星球員是天賦極高的足球員。"},{"en":"Galacticos are extremely famous and expensive star footballers, especially associated with Real Madrid.","zh":"Galacticos 是極著名且昂貴的明星足球員，尤其與Real Madrid相關。"},{"en":"A team of galacticos may attract attention before it wins anything.","zh":"一隊銀河艦隊巨星球員可能在贏得任何東西前已吸引注意。"},{"en":"Galacticos can raise a club’s profile, but they still need a balanced system.","zh":"銀河艦隊巨星球員可以提升球會知名度，但仍需要均衡制度。"},{"en":"This word suggests glamorous superstar players.","zh":"這個詞暗示光鮮的超級明星球員。"}],"source":"143 - We have Star performers!.pdf","sourcePage":17},{"front":"extravagantly gifted","meaning":"天賦極高的","examples":[{"en":"The galacticos were among the most extravagantly gifted players on the planet.","zh":"銀河艦隊巨星球員是地球上天賦最高的球員之一。"},{"en":"Extravagantly gifted means possessing an unusually high level of natural ability.","zh":"Extravagantly gifted 指擁有異常高水平的天生能力。"},{"en":"An extravagantly gifted musician may learn difficult pieces faster than others.","zh":"天賦極高的音樂人可能比其他人更快學會困難樂曲。"},{"en":"Great natural ability still needs discipline, coaching, and teamwork.","zh":"偉大的天生能力仍需要紀律、教練和團隊合作。"},{"en":"This phrase strongly praises talent, sometimes almost excessively.","zh":"這個片語強烈讚揚才華，有時幾乎帶誇張意味。"}],"source":"143 - We have Star performers!.pdf","sourcePage":17},{"front":"on the planet","meaning":"在地球上；全世界","examples":[{"en":"Real Madrid had some of the most gifted players on the planet.","zh":"Real Madrid擁有一些全世界最有天賦的球員。"},{"en":"On the planet means in the world or anywhere on Earth.","zh":"On the planet 指在世界上或地球任何地方。"},{"en":"A hospital may have some of the best surgeons on the planet.","zh":"醫院可能擁有全世界最好的外科醫生之一。"},{"en":"Calling someone the best on the planet strongly emphasises global excellence.","zh":"稱某人為地球上最好的人，強烈強調全球卓越。"},{"en":"This phrase is often used for dramatic emphasis.","zh":"這個片語常用於戲劇化強調。"}],"source":"143 - We have Star performers!.pdf","sourcePage":17},{"front":"be outperformed by","meaning":"表現不及","examples":[{"en":"The galacticos were outperformed by better-integrated teams.","zh":"銀河艦隊巨星球員表現不及整合得更好的隊伍。"},{"en":"To be outperformed by someone means to do worse than them.","zh":"To be outperformed by someone 指表現比對方差。"},{"en":"A rich school may be outperformed by a smaller school with better teaching systems.","zh":"富有學校可能表現不及教學制度更好的小型學校。"},{"en":"Expensive teams can be outperformed by cheaper teams that cooperate better.","zh":"昂貴隊伍可能表現不及合作更好的較便宜隊伍。"},{"en":"This phrase compares actual results, not reputation.","zh":"這個片語比較實際成果，而不是名聲。"}],"source":"143 - We have Star performers!.pdf","sourcePage":17},{"front":"better-integrated","meaning":"整合得更好的","examples":[{"en":"Less talented but better-integrated sides may perform better.","zh":"才華較少但整合得更好的隊伍可能表現更好。"},{"en":"Better-integrated means the parts fit and work together more smoothly.","zh":"Better-integrated 指各部分配合並合作得更順暢。"},{"en":"A better-integrated hospital team shares information clearly between doctors and nurses.","zh":"整合得更好的醫療團隊會在醫生和護士之間清楚分享資訊。"},{"en":"A team with fewer stars can win if its players understand their roles well.","zh":"如果球員清楚理解自己的角色，較少明星的隊伍也可以勝出。"},{"en":"This phrase values coordination over individual brilliance.","zh":"這個片語重視協調多於個人光芒。"}],"source":"143 - We have Star performers!.pdf","sourcePage":18},{"front":"stars are trumped by systems","meaning":"明星也被制度勝過","examples":[{"en":"In football, too, stars are trumped by systems.","zh":"在足球中，明星也被制度勝過。"},{"en":"Stars are trumped by systems means strong systems beat individual stars in producing results.","zh":"Stars are trumped by systems 指強大制度在產生成果上勝過個人明星。"},{"en":"In a school, famous teachers may be trumped by a clear curriculum and good feedback systems.","zh":"在學校中，名師可能被清晰課程和良好回饋制度勝過。"},{"en":"When coordination matters, stars can lose to teams with better routines.","zh":"當協調很重要，明星可能輸給有更好常規的團隊。"},{"en":"This phrase summarises the article’s main argument.","zh":"這個片語概括文章主要論點。"}],"source":"143 - We have Star performers!.pdf","sourcePage":18},{"front":"if not by","meaning":"如果不是靠……","examples":[{"en":"If not by hiring stars, companies must compete in another way.","zh":"如果不是靠聘用明星人才，公司就必須以另一種方式競爭。"},{"en":"If not by something means if that method is not the answer, another method is needed.","zh":"If not by something 指如果該方法不是答案，就需要另一方法。"},{"en":"If not by extra homework, a student may improve through better feedback.","zh":"如果不是靠額外功課，學生可能透過更好回饋進步。"},{"en":"If not by buying stars, clubs may succeed by developing young players.","zh":"如果不是靠購買明星，球會可能透過培養年輕球員成功。"},{"en":"This phrase opens the door to an alternative solution.","zh":"這個片語為替代方案打開空間。"}],"source":"143 - We have Star performers!.pdf","sourcePage":18},{"front":"compete in the war for talent","meaning":"在人才戰中競爭","examples":[{"en":"Companies need a better way to compete in the war for talent.","zh":"公司需要更好的方式在人才戰中競爭。"},{"en":"To compete in the war for talent means to try to attract, develop, and keep valuable workers against other employers.","zh":"To compete in the war for talent 指與其他僱主競爭，以吸引、培養和留住有價值員工。"},{"en":"A hospital competes in the war for talent when it offers training and safe working hours.","zh":"醫院提供培訓和安全工時，就是在人才戰中競爭。"},{"en":"Companies can compete better by growing talent internally instead of only buying it.","zh":"公司可以透過內部培養人才，而不是只購買人才，來更好地競爭。"},{"en":"This phrase describes labour-market competition for skilled people.","zh":"這個片語描述對熟練人才的勞動市場競爭。"}],"source":"143 - We have Star performers!.pdf","sourcePage":18},{"front":"grow your own","meaning":"培養自己的人才","examples":[{"en":"The writer suggests that companies should grow their own stars.","zh":"作者建議公司應培養自己的明星人才。"},{"en":"Grow your own means develop talent internally instead of buying it from outside.","zh":"Grow your own 指在內部培養人才，而不是從外部購買人才。"},{"en":"A school can grow its own leaders by mentoring junior teachers.","zh":"學校可以透過指導初級老師來培養自己的領導者。"},{"en":"Growing your own talent takes time, but it creates loyalty and system knowledge.","zh":"培養自己的人才需要時間，但能建立忠誠和制度知識。"},{"en":"This phrase is informal and uses a farming metaphor.","zh":"這個片語較口語，使用農業比喻。"}],"source":"143 - We have Star performers!.pdf","sourcePage":18},{"front":"work for","meaning":"對……有效","examples":[{"en":"This approach worked for investment analysts.","zh":"這種方法對投資分析師有效。"},{"en":"To work for someone or something means to be effective in that situation.","zh":"To work for someone or something 指在該情況下有效。"},{"en":"A study plan may work for one student but not for another.","zh":"一個學習計劃可能對一名學生有效，但對另一名無效。"},{"en":"Internal training works for companies when people stay long enough to benefit from it.","zh":"當員工留得夠久能受益，內部培訓對公司便有效。"},{"en":"This phrase means “be successful”, not “be employed by” in this context.","zh":"在此語境中，這個片語意思是「有效」，不是「受僱於」。"}],"source":"143 - We have Star performers!.pdf","sourcePage":18},{"front":"be better at creating stars","meaning":"更善於培養明星人才","examples":[{"en":"Some companies were better at creating stars than hiring them.","zh":"一些公司比起聘用明星人才，更善於培養明星人才。"},{"en":"To be better at creating stars means to develop high performers internally more successfully than recruiting them from outside.","zh":"To be better at creating stars 指比起從外部招聘，更成功地在內部培養高績效人才。"},{"en":"A football club may be better at creating stars through youth training than buying famous players.","zh":"足球會可能透過青訓比購買著名球員更善於培養明星人才。"},{"en":"Companies that create stars build skills, loyalty, and system knowledge together.","zh":"能培養明星人才的公司同時建立技能、忠誠和制度知識。"},{"en":"This phrase contrasts development with external recruitment.","zh":"這個片語對比培養與外部招聘。"}],"source":"143 - We have Star performers!.pdf","sourcePage":18},{"front":"retain them","meaning":"留住他們","examples":[{"en":"Successful firms created stars and retained them.","zh":"成功公司培養明星人才並留住他們。"},{"en":"To retain them means to keep those people in the organisation.","zh":"To retain them 指把那些人留在組織內。"},{"en":"A school can retain good teachers by giving respect, support, and fair pay.","zh":"學校可以透過尊重、支援和公平薪酬留住好老師。"},{"en":"If companies cannot retain talent, training investment may be lost.","zh":"如果公司無法留住人才，培訓投資可能流失。"},{"en":"This phrase focuses on keeping people after they have been developed or hired.","zh":"這個片語著重在培養或聘用後保留人才。"}],"source":"143 - We have Star performers!.pdf","sourcePage":18},{"front":"sophisticated view of","meaning":"對……成熟深入的看法","examples":[{"en":"These companies had a sophisticated view of talent and systems.","zh":"這些公司對人才和制度有成熟深入的看法。"},{"en":"A sophisticated view of something is a deep, balanced, and detailed understanding of it.","zh":"Sophisticated view of something 是對某事深刻、平衡而細緻的理解。"},{"en":"A teacher with a sophisticated view of learning understands both motivation and practice.","zh":"對學習有成熟深入看法的老師，理解動機和練習兩者。"},{"en":"A sophisticated view of talent recognises that people and systems support each other.","zh":"對人才成熟深入的看法會承認人和制度互相支援。"},{"en":"This phrase contrasts with simple slogans.","zh":"這個片語與簡單口號形成對比。"}],"source":"143 - We have Star performers!.pdf","sourcePage":18},{"front":"interdependent relationship","meaning":"相互依存的關係","examples":[{"en":"They understood the interdependent relationship between stars and systems.","zh":"他們理解明星人才與制度之間相互依存的關係。"},{"en":"An interdependent relationship is a relationship in which both sides rely on and affect each other.","zh":"相互依存的關係是雙方互相依賴並互相影響的關係。"},{"en":"Teachers and students have an interdependent relationship because both shape classroom learning.","zh":"老師和學生有相互依存的關係，因為雙方都塑造課堂學習。"},{"en":"Stars need systems, and systems improve when talented people use them well.","zh":"明星人才需要制度，而制度在有才華的人善用時會改善。"},{"en":"This phrase shows two-way dependence.","zh":"這個片語顯示雙向依賴。"}],"source":"143 - We have Star performers!.pdf","sourcePage":18},{"front":"resort to","meaning":"訴諸；依靠","examples":[{"en":"They kept stars without resorting to exorbitant salaries.","zh":"他們留住明星人才，而沒有訴諸高得離譜的薪酬。"},{"en":"To resort to something means to use it, especially when it is not the best or preferred option.","zh":"To resort to something 指使用某方法，尤其當它不是最好或首選方法時。"},{"en":"A teacher should not resort to shouting when clearer instructions would work better.","zh":"如果更清晰指示更有效，老師不應訴諸大聲責罵。"},{"en":"Companies may resort to high salaries if they have no better way to keep talent.","zh":"如果公司沒有更好方法留住人才，可能訴諸高薪。"},{"en":"This phrase often suggests a last or desperate method.","zh":"這個片語常暗示最後或迫不得已的方法。"}],"source":"143 - We have Star performers!.pdf","sourcePage":18},{"front":"exorbitant salaries","meaning":"高得離譜的薪酬","examples":[{"en":"Firms can retain talent without paying exorbitant salaries.","zh":"公司可以不支付高得離譜的薪酬而留住人才。"},{"en":"Exorbitant salaries are unreasonably high levels of pay.","zh":"Exorbitant salaries 是不合理地高的薪酬水平。"},{"en":"A company may offer exorbitant salaries to attract famous managers quickly.","zh":"公司可能提供高得離譜的薪酬來快速吸引著名經理。"},{"en":"Exorbitant salaries can create jealousy and damage the pay structure inside a firm.","zh":"高得離譜的薪酬可以造成妒忌並破壞公司內部薪酬結構。"},{"en":"This phrase strongly criticises excessive pay.","zh":"這個片語強烈批評過高薪酬。"}],"source":"143 - We have Star performers!.pdf","sourcePage":19},{"front":"be destructive to","meaning":"對……具破壞性","examples":[{"en":"Exorbitant salaries were destructive to rival firms.","zh":"高得離譜的薪酬對競爭公司具破壞性。"},{"en":"To be destructive to something means to damage or weaken it seriously.","zh":"To be destructive to something 指嚴重損害或削弱某物。"},{"en":"Constant criticism can be destructive to a student’s confidence.","zh":"持續批評可以對學生信心具破壞性。"},{"en":"Very high salaries can be destructive to firms that cannot afford to match them.","zh":"非常高的薪酬可以對無法配合的公司具破壞性。"},{"en":"This phrase describes serious harm, not small inconvenience.","zh":"這個片語描述嚴重傷害，而不是小麻煩。"}],"source":"143 - We have Star performers!.pdf","sourcePage":19},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"The task asks which paragraph contains specific information.","zh":"這項任務問哪一段包含特定資料。"},{"en":"Which paragraph contains means you must find the paragraph where the information appears.","zh":"Which paragraph contains 指你必須找出資料出現在哪一段。"},{"en":"In a reading test, students should scan for names, numbers, and key ideas to find which paragraph contains the answer.","zh":"在閱讀測驗中，學生應掃讀姓名、數字和關鍵概念，以找出哪一段包含答案。"},{"en":"If several paragraphs seem similar, exact evidence decides the answer.","zh":"如果幾段看似相似，精確證據決定答案。"},{"en":"This phrase is common in paragraph-matching questions.","zh":"這個片語常見於段落配對題。"}],"source":"143 - We have Star performers!.pdf","sourcePage":19},{"front":"the following information","meaning":"以下資料","examples":[{"en":"Candidates identify the paragraph containing the following information.","zh":"考生辨認包含以下資料的段落。"},{"en":"The following information means the details listed after the instruction.","zh":"The following information 指指示後列出的資料。"},{"en":"Students should read the following information before looking back at the passage.","zh":"學生應先閱讀以下資料，再回到文章尋找。"},{"en":"Key words in the following information may appear in paraphrased form in the text.","zh":"以下資料中的關鍵詞可能以改寫形式出現在文本中。"},{"en":"This phrase points the reader to what comes next.","zh":"這個片語把讀者指向接下來的內容。"}],"source":"143 - We have Star performers!.pdf","sourcePage":19},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Candidates write the correct letter on the answer sheet.","zh":"考生在答題紙上寫上正確字母。"},{"en":"Write the correct letter means put the letter that matches the right answer.","zh":"Write the correct letter 指寫出與正確答案相配的字母。"},{"en":"If the answer is paragraph C, students should write C, not the whole paragraph title.","zh":"如果答案是C段，學生應寫C，而不是整個段落標題。"},{"en":"Writing the wrong letter loses the mark even if the student understood the idea.","zh":"即使學生理解意思，寫錯字母也會失分。"},{"en":"This phrase is a practical exam instruction.","zh":"這個片語是實用考試指示。"}],"source":"143 - We have Star performers!.pdf","sourcePage":19},{"front":"may use any letter more than once","meaning":"可多次使用任何字母","examples":[{"en":"Candidates may use any letter more than once.","zh":"考生可多次使用任何字母。"},{"en":"May use any letter more than once means the same answer option can be used for multiple questions.","zh":"May use any letter more than once 指同一答案選項可以用於多道題。"},{"en":"In paragraph matching, two pieces of information may come from the same paragraph.","zh":"在段落配對中，兩項資料可能來自同一段。"},{"en":"Students should not force every answer to be different when repetition is allowed.","zh":"當允許重複時，學生不應強迫每個答案都不同。"},{"en":"This instruction prevents a common exam mistake.","zh":"這個指示防止常見考試錯誤。"}],"source":"143 - We have Star performers!.pdf","sourcePage":19},{"front":"outside business","meaning":"商業以外","examples":[{"en":"The question asks for an example outside business.","zh":"問題要求一個商業以外的例子。"},{"en":"Outside business means not from the world of companies, finance, or management.","zh":"Outside business 指不是來自公司、金融或管理世界。"},{"en":"Football is an example outside business because it comes from sport.","zh":"足球是商業以外的例子，因為它來自體育。"},{"en":"Using examples outside business can make an argument easier to understand.","zh":"使用商業以外的例子可以令論點更容易理解。"},{"en":"This phrase points to another field or context.","zh":"這個片語指向另一個領域或語境。"}],"source":"143 - We have Star performers!.pdf","sourcePage":19},{"front":"a better system","meaning":"更好的制度","examples":[{"en":"A better system can outperform bigger stars.","zh":"更好的制度可以勝過更大牌的明星。"},{"en":"A better system is a stronger set of rules, routines, support, and coordination.","zh":"更好的制度是更強大的規則、常規、支援和協調。"},{"en":"A school with a better system may help average students improve more steadily.","zh":"擁有更好制度的學校可能幫助普通學生更穩定地進步。"},{"en":"Better systems reduce dependence on one brilliant person.","zh":"更好的制度減少對一位天才人物的依賴。"},{"en":"This phrase highlights structure as a source of success.","zh":"這個片語突顯結構是成功來源。"}],"source":"143 - We have Star performers!.pdf","sourcePage":19},{"front":"bigger stars","meaning":"更大牌的明星","examples":[{"en":"The football example contrasts better systems with bigger stars.","zh":"足球例子把更好的制度與更大牌的明星作對比。"},{"en":"Bigger stars are more famous, expensive, or highly rated performers.","zh":"Bigger stars 是更有名、更昂貴或評價更高的表現者。"},{"en":"A club may buy bigger stars to attract attention and sell tickets.","zh":"球會可能購買更大牌的明星來吸引注意和售票。"},{"en":"Bigger stars may still lose if they cannot work within a clear system.","zh":"如果更大牌的明星無法在清晰制度中合作，仍可能輸。"},{"en":"This phrase compares reputation and fame, not necessarily teamwork.","zh":"這個片語比較名聲和知名度，而不一定比較團隊合作。"}],"source":"143 - We have Star performers!.pdf","sourcePage":19},{"front":"a failed company","meaning":"失敗的公司","examples":[{"en":"The question asks for a failed company that believed in stars.","zh":"問題要求一間相信明星人才的失敗公司。"},{"en":"A failed company is a business that collapsed, performed badly, or did not survive.","zh":"失敗的公司是倒閉、表現差或未能生存的企業。"},{"en":"A failed company may have had famous employees but poor systems and risky decisions.","zh":"失敗的公司可能曾有著名員工，但制度差且決定冒險。"},{"en":"Studying a failed company helps students understand what went wrong.","zh":"研究失敗的公司可以幫助學生理解問題出在哪裡。"},{"en":"This phrase focuses on business failure, not temporary difficulty.","zh":"這個片語著重商業失敗，而不是暫時困難。"}],"source":"143 - We have Star performers!.pdf","sourcePage":19},{"front":"rather than systems","meaning":"而不是制度","examples":[{"en":"Enron believed in stars rather than systems.","zh":"安然相信明星人才，而不是制度。"},{"en":"Rather than systems means instead of relying on organised processes and structures.","zh":"Rather than systems 指不是依賴有組織的流程和結構。"},{"en":"A school may rely on one famous teacher rather than systems for training all staff.","zh":"學校可能依賴一位名師，而不是培訓所有員工的制度。"},{"en":"Choosing stars rather than systems can create short-term excitement but long-term weakness.","zh":"選擇明星而不是制度可以帶來短期興奮，但造成長期弱點。"},{"en":"This phrase creates a clear contrast between two approaches.","zh":"這個片語清楚對比兩種方法。"}],"source":"143 - We have Star performers!.pdf","sourcePage":19},{"front":"author’s suggestion","meaning":"作者的建議","examples":[{"en":"The question asks for the author’s suggestion on acquiring employees.","zh":"問題問作者關於獲取員工的建議。"},{"en":"The author’s suggestion is the advice or solution the writer gives.","zh":"Author’s suggestion 是作者提出的建議或解決方案。"},{"en":"A reading question may ask for the author’s suggestion rather than a factual detail.","zh":"閱讀題可能要求找出作者的建議，而不是事實細節。"},{"en":"In this passage, the author’s suggestion is linked to developing talent internally.","zh":"在這篇文章中，作者的建議與內部培養人才相關。"},{"en":"This phrase tells students to identify opinion or recommendation.","zh":"這個片語告訴學生要辨認觀點或建議。"}],"source":"143 - We have Star performers!.pdf","sourcePage":20},{"front":"acquiring employees","meaning":"獲取員工；招聘員工","examples":[{"en":"The writer discusses better ways of acquiring employees.","zh":"作者討論獲取員工的更好方法。"},{"en":"Acquiring employees means getting workers through hiring, recruitment, or internal development.","zh":"Acquiring employees 指透過招聘、聘用或內部培養取得員工。"},{"en":"A company can acquire employees by advertising jobs or training existing staff for new roles.","zh":"公司可以透過刊登招聘廣告或培訓現有員工擔任新角色來獲取員工。"},{"en":"If acquiring employees becomes too expensive, firms may focus on retention and training.","zh":"如果獲取員工變得太昂貴，公司可能集中於留住和培訓員工。"},{"en":"This phrase is broader than simply hiring from outside.","zh":"這個片語比單純外部招聘更廣。"}],"source":"143 - We have Star performers!.pdf","sourcePage":20},{"front":"compete today","meaning":"在今天競爭","examples":[{"en":"Companies need to compete today by developing their own talent.","zh":"公司今天需要透過培養自己的人才來競爭。"},{"en":"To compete today means to succeed under current conditions and modern pressures.","zh":"To compete today 指在當前條件和現代壓力下取得成功。"},{"en":"Small shops compete today by offering personal service and online ordering.","zh":"小店今天透過提供個人化服務和網上訂購來競爭。"},{"en":"Companies that compete today must adapt to technology, labour shortages, and customer expectations.","zh":"今天競爭的公司必須適應科技、勞工短缺和顧客期望。"},{"en":"This phrase focuses on present-day competition.","zh":"這個片語著重當今競爭。"}],"source":"143 - We have Star performers!.pdf","sourcePage":20},{"front":"medical-anatomy metaphor","meaning":"醫學及解剖學比喻","examples":[{"en":"The organ-transplant comparison is a medical-anatomy metaphor.","zh":"器官移植比較是一個醫學及解剖學比喻。"},{"en":"A medical-anatomy metaphor explains an idea by comparing it with the body or medical treatment.","zh":"醫學及解剖學比喻，是透過把想法與身體或醫療處理比較來解釋事情。"},{"en":"Calling a company a body and a new hire an organ is a medical-anatomy metaphor.","zh":"把公司稱為身體，把新員工稱為器官，就是醫學及解剖學比喻。"},{"en":"Such metaphors help readers understand fit, rejection, and system balance.","zh":"這類比喻幫助讀者理解適配、排斥和系統平衡。"},{"en":"This phrase describes the type of comparison being used.","zh":"這個片語描述所使用的比較類型。"}],"source":"143 - We have Star performers!.pdf","sourcePage":20},{"front":"illustrate the problems of","meaning":"說明……的問題","examples":[{"en":"The metaphor illustrates the problems of hiring stars.","zh":"這個比喻說明聘用明星人才的問題。"},{"en":"To illustrate the problems of something means to show or explain its difficulties clearly.","zh":"To illustrate the problems of something 指清楚展示或解釋某事的困難。"},{"en":"A failed group project can illustrate the problems of poor communication.","zh":"一個失敗小組專題可以說明溝通差的問題。"},{"en":"The organ-transplant metaphor illustrates how a star may disturb an existing team.","zh":"器官移植比喻說明星人才如何擾亂現有團隊。"},{"en":"This phrase connects an example with the issue it explains.","zh":"這個片語把例子與它所解釋的問題連接起來。"}],"source":"143 - We have Star performers!.pdf","sourcePage":20},{"front":"hiring stars","meaning":"聘用明星人才","examples":[{"en":"The passage criticises the strategy of hiring stars.","zh":"文章批評聘用明星人才的策略。"},{"en":"Hiring stars means recruiting famous or outstanding performers from outside an organisation.","zh":"Hiring stars 指從組織外招聘著名或出色表現者。"},{"en":"A company may try hiring stars when it wants quick improvement.","zh":"公司想快速改善時，可能嘗試聘用明星人才。"},{"en":"Hiring stars can fail if the newcomers do not fit the system or team.","zh":"如果新人不適合制度或團隊，聘用明星人才可能失敗。"},{"en":"This phrase is central to the article’s criticism of talent obsession.","zh":"這個片語是文章批評人才迷思的核心。"}],"source":"143 - We have Star performers!.pdf","sourcePage":20},{"front":"agree with the views of","meaning":"與作者觀點一致","examples":[{"en":"Candidates decide whether the statements agree with the views of the writer.","zh":"考生判斷陳述是否與作者觀點一致。"},{"en":"To agree with the views of the writer means to match the writer’s opinion or argument.","zh":"To agree with the views of the writer 指與作者的觀點或論點相符。"},{"en":"In reading tests, a statement may be factual but still not agree with the writer’s view.","zh":"在閱讀測驗中，一項陳述可能是事實，但仍未必與作者觀點一致。"},{"en":"Students must separate the writer’s opinion from examples or other people’s claims.","zh":"學生必須把作者觀點與例子或其他人的說法分開。"},{"en":"This phrase is common in YES/NO/NOT GIVEN questions.","zh":"這個片語常見於YES/NO/NOT GIVEN題型。"}],"source":"143 - We have Star performers!.pdf","sourcePage":20},{"front":"contradict the views of","meaning":"與作者觀點矛盾","examples":[{"en":"A statement is wrong if it contradicts the views of the writer.","zh":"如果陳述與作者觀點矛盾，它就是錯的。"},{"en":"To contradict the views of the writer means to say the opposite of the writer’s opinion.","zh":"To contradict the views of the writer 指說出與作者觀點相反的意思。"},{"en":"If the writer supports systems, a statement praising star-hiring may contradict the writer’s view.","zh":"如果作者支持制度，而陳述讚揚明星招聘，便可能與作者觀點矛盾。"},{"en":"Students should look for exact opposition, not just missing information.","zh":"學生應尋找精確相反，而不只是缺失資料。"},{"en":"This phrase is important for distinguishing NO from NOT GIVEN.","zh":"這個片語對區分NO和NOT GIVEN很重要。"}],"source":"143 - We have Star performers!.pdf","sourcePage":20},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"Students write NOT GIVEN if it is impossible to say what the writer thinks.","zh":"如果無法判斷作者怎樣想，學生寫NOT GIVEN。"},{"en":"Impossible to say means the information is not clear or not provided.","zh":"Impossible to say 指資訊不清楚或沒有提供。"},{"en":"If the passage never mentions salary details, it may be impossible to say whether pay increased.","zh":"如果文章從未提及薪酬細節，就可能無法判斷薪酬是否增加。"},{"en":"Students should not guess when it is impossible to say from the text.","zh":"當無法從文本判斷時，學生不應猜測。"},{"en":"This phrase points to lack of evidence, not contradiction.","zh":"這個片語指缺乏證據，而不是矛盾。"}],"source":"143 - We have Star performers!.pdf","sourcePage":20},{"front":"have such a great influence","meaning":"有如此大的影響","examples":[{"en":"The statement asks whether the reports had such a great influence.","zh":"這項陳述問這些報告是否有如此大的影響。"},{"en":"To have such a great influence means to affect people, ideas, or actions very strongly.","zh":"To have such a great influence 指對人、想法或行動產生非常強烈的影響。"},{"en":"A popular education report may have such a great influence that schools change their teaching methods.","zh":"一份受歡迎的教育報告可能有如此大的影響，以致學校改變教學方法。"},{"en":"If a business idea has great influence, managers may copy it even without enough evidence.","zh":"如果商業理念有巨大影響，管理者即使沒有足夠證據也可能模仿。"},{"en":"This phrase focuses on strong impact.","zh":"這個片語著重強大影響力。"}],"source":"143 - We have Star performers!.pdf","sourcePage":20},{"front":"economic conditions","meaning":"經濟狀況","examples":[{"en":"Economic conditions can affect immigration and labour policy.","zh":"經濟狀況可以影響移民和勞工政策。"},{"en":"Economic conditions are the state of the economy, including jobs, wages, prices, and growth.","zh":"Economic conditions 是經濟狀態，包括工作、工資、價格和增長。"},{"en":"When economic conditions are weak, families may spend less money.","zh":"當經濟狀況疲弱，家庭可能減少支出。"},{"en":"Labour shortages are one economic condition that can change government policy.","zh":"勞工短缺是一種可以改變政府政策的經濟狀況。"},{"en":"This phrase describes the financial and employment environment around decisions.","zh":"這個片語描述決策周圍的財政和就業環境。"}],"source":"143 - We have Star performers!.pdf","sourcePage":20},{"front":"determine whether","meaning":"決定是否","examples":[{"en":"The question asks whether economic conditions determine hiring foreign workers.","zh":"問題問經濟狀況是否決定聘用外籍工人。"},{"en":"To determine whether something happens means to decide or strongly influence if it happens.","zh":"To determine whether something happens 指決定或強烈影響某事是否發生。"},{"en":"Exam results may determine whether a student enters a particular programme.","zh":"考試成績可能決定學生是否進入某個課程。"},{"en":"Labour shortages may determine whether a country welcomes more foreign workers.","zh":"勞工短缺可能決定一個國家是否歡迎更多外籍工人。"},{"en":"This phrase connects a factor with a decision or outcome.","zh":"這個片語把因素與決定或結果連接起來。"}],"source":"143 - We have Star performers!.pdf","sourcePage":21},{"front":"foreign workers","meaning":"外籍工人","examples":[{"en":"Labour shortages may lead a country to hire foreign workers.","zh":"勞工短缺可能使一個國家聘用外籍工人。"},{"en":"Foreign workers are people who work in a country that is not their own.","zh":"外籍工人是在並非自己國家的地方工作的人。"},{"en":"Farms may hire foreign workers when there are not enough local workers during harvest.","zh":"在收成期間本地工人不足時，農場可能聘用外籍工人。"},{"en":"Foreign workers can fill shortages, but they also need fair pay and safe conditions.","zh":"外籍工人可以填補短缺，但也需要公平薪酬和安全條件。"},{"en":"This phrase refers to workers’ nationality or origin, not their skill level.","zh":"這個片語指工人的國籍或來源，而不是其技能水平。"}],"source":"143 - We have Star performers!.pdf","sourcePage":21},{"front":"Enron’s collapse","meaning":"安然公司的倒閉","examples":[{"en":"Enron’s collapse is used to challenge the talent myth.","zh":"安然公司的倒閉被用來挑戰人才神話。"},{"en":"Enron’s collapse means the failure and downfall of the company Enron.","zh":"Enron’s collapse 指安然公司的失敗和倒下。"},{"en":"A company collapse can reveal weaknesses in leadership, culture, and controls.","zh":"公司倒閉可以揭示領導、文化和監控制度的弱點。"},{"en":"Enron’s collapse suggested that smart people without strong systems could still fail badly.","zh":"安然公司的倒閉顯示，沒有強大制度的聰明人仍可能嚴重失敗。"},{"en":"This phrase refers to a major business failure used as evidence in the argument.","zh":"這個片語指文章用作證據的重大商業失敗。"}],"source":"143 - We have Star performers!.pdf","sourcePage":21},{"front":"be caused entirely by","meaning":"完全由……造成","examples":[{"en":"The statement asks whether the collapse was caused entirely by an accident.","zh":"這項陳述問倒閉是否完全由一次意外造成。"},{"en":"To be caused entirely by something means to result only from that one cause.","zh":"To be caused entirely by something 指結果只由那一個原因造成。"},{"en":"A student’s poor grade is rarely caused entirely by one bad lesson.","zh":"學生成績差很少完全由一堂差課造成。"},{"en":"A company failure is usually not caused entirely by an unfortunate event if management choices also mattered.","zh":"如果管理選擇也重要，公司失敗通常不會完全由一件不幸事件造成。"},{"en":"This phrase tests whether the cause is complete and exclusive.","zh":"這個片語測試原因是否完整且排他。"}],"source":"143 - We have Star performers!.pdf","sourcePage":21},{"front":"unfortunate incident","meaning":"不幸事件","examples":[{"en":"The option refers to an unfortunate incident rather than management mistakes.","zh":"這個選項指不幸事件，而不是管理錯誤。"},{"en":"An unfortunate incident is a bad event that happens by accident or bad luck.","zh":"Unfortunate incident 是因意外或壞運氣發生的壞事。"},{"en":"A power cut during an exam is an unfortunate incident.","zh":"考試期間停電是一件不幸事件。"},{"en":"Calling a failure an unfortunate incident may hide deeper causes.","zh":"把失敗稱為不幸事件，可能隱藏更深層原因。"},{"en":"This phrase can minimise responsibility if used carelessly.","zh":"如果使用不慎，這個片語可能淡化責任。"}],"source":"143 - We have Star performers!.pdf","sourcePage":21},{"front":"management mistakes","meaning":"管理錯誤","examples":[{"en":"The writer implies that management mistakes contributed to Enron’s failure.","zh":"作者暗示管理錯誤促成安然公司的失敗。"},{"en":"Management mistakes are poor decisions or actions made by leaders or managers.","zh":"管理錯誤是領導者或管理層作出的差劣決定或行動。"},{"en":"Hiring too many expensive stars without a system can be a management mistake.","zh":"沒有制度卻聘用太多昂貴明星人才，可能是管理錯誤。"},{"en":"Management mistakes can damage staff morale, finances, and public trust.","zh":"管理錯誤可以損害員工士氣、財務和公眾信任。"},{"en":"This phrase focuses responsibility on leadership choices.","zh":"這個片語把責任集中於領導選擇。"}],"source":"143 - We have Star performers!.pdf","sourcePage":21},{"front":"develop stars within","meaning":"在……內培養明星","examples":[{"en":"Some football clubs develop stars within a strong system.","zh":"一些足球會在強大制度內培養明星。"},{"en":"To develop stars within a system means to help talented people grow inside the organisation.","zh":"To develop stars within a system 指在組織內幫助有才華的人成長。"},{"en":"A company can develop stars within by mentoring junior staff and giving them challenging work.","zh":"公司可以透過指導初級員工和給予具挑戰工作，在內部培養明星。"},{"en":"Developing stars internally creates people who understand the culture and routines.","zh":"內部培養明星能創造理解文化和常規的人才。"},{"en":"This phrase contrasts internal growth with external buying.","zh":"這個片語對比內部成長與外部購買。"}],"source":"143 - We have Star performers!.pdf","sourcePage":21},{"front":"simply collect stars","meaning":"只是收集明星","examples":[{"en":"Other clubs simply collect stars without building a system.","zh":"其他球會只是收集明星，而沒有建立制度。"},{"en":"To simply collect stars means to gather famous talent without creating structure or teamwork.","zh":"To simply collect stars 指聚集著名人才，但沒有創造結構或團隊合作。"},{"en":"A company simply collects stars if it hires impressive names but gives them no shared process.","zh":"如果公司聘用亮眼名字卻沒有共同流程，就是只是收集明星。"},{"en":"Collecting stars can look exciting but fail when people cannot work together.","zh":"收集明星看起來令人興奮，但當人們無法合作時便會失敗。"},{"en":"This phrase criticises talent acquisition without integration.","zh":"這個片語批評沒有整合的人才取得。"}],"source":"143 - We have Star performers!.pdf","sourcePage":21},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Candidates complete the summary below using words from the passage.","zh":"考生使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the summary that follows.","zh":"Complete the summary below 指填寫下面摘要中的缺失字詞。"},{"en":"Students should read the whole summary first to understand its meaning.","zh":"學生應先閱讀整個摘要，以理解其意思。"},{"en":"The correct words usually fit both the grammar and the meaning of the sentence.","zh":"正確字詞通常同時符合句子的文法和意思。"},{"en":"This phrase is a common reading-test instruction.","zh":"這個片語是常見閱讀測驗指示。"}],"source":"143 - We have Star performers!.pdf","sourcePage":21},{"front":"no more than two words","meaning":"不多於兩個字","examples":[{"en":"Candidates choose no more than two words from the passage.","zh":"考生從文章中選擇不多於兩個字。"},{"en":"No more than two words means the answer must contain one or two words only.","zh":"No more than two words 指答案只能包含一個或兩個字。"},{"en":"If the answer has three words, it breaks the instruction even if the idea is correct.","zh":"如果答案有三個字，即使意思正確也違反指示。"},{"en":"Students should copy only the exact necessary words from the passage.","zh":"學生應只從文章中抄寫準確而必要的字詞。"},{"en":"This phrase controls answer length in exams.","zh":"這個片語在考試中控制答案長度。"}],"source":"143 - We have Star performers!.pdf","sourcePage":21},{"front":"an investigation examined","meaning":"一項調查研究了","examples":[{"en":"An investigation examined the careers of 1,000 star analysts.","zh":"一項調查研究了一千名明星分析師的職業生涯。"},{"en":"An investigation examined means a study carefully looked at evidence to understand something.","zh":"An investigation examined 指一項研究仔細檢視證據，以理解某事。"},{"en":"An investigation examined why students were absent so often.","zh":"一項調查研究了學生為何經常缺席。"},{"en":"A careful investigation can reveal causes that people did not expect.","zh":"仔細調查可以揭示人們意想不到的原因。"},{"en":"This phrase introduces research-based evidence.","zh":"這個片語引入以研究為基礎的證據。"}],"source":"143 - We have Star performers!.pdf","sourcePage":21},{"front":"reported in","meaning":"發表於","examples":[{"en":"A study reported in Harvard Business Review examined star behaviour.","zh":"一項發表於《哈佛商業評論》的研究檢視明星人才行為。"},{"en":"Reported in means published or described in a particular source.","zh":"Reported in 指在某個特定來源中發表或描述。"},{"en":"A medical study reported in a journal may influence hospital policy.","zh":"發表於期刊的醫學研究可能影響醫院政策。"},{"en":"When research is reported in a respected publication, more people may notice it.","zh":"當研究發表於受尊敬的刊物，更多人可能注意到它。"},{"en":"This phrase identifies where information appeared.","zh":"這個片語指出資訊出現在哪裡。"}],"source":"143 - We have Star performers!.pdf","sourcePage":22},{"front":"negative effects","meaning":"負面影響","examples":[{"en":"The study found that hiring a star has negative effects.","zh":"研究發現聘用明星人才有負面影響。"},{"en":"Negative effects are harmful or unwanted results.","zh":"Negative effects 是有害或不想要的結果。"},{"en":"Poor sleep has negative effects on memory, mood, and concentration.","zh":"睡眠不足對記憶、心情和專注力有負面影響。"},{"en":"Hiring one star can have negative effects if it damages team trust.","zh":"如果聘用一位明星損害團隊信任，便可能有負面影響。"},{"en":"This phrase focuses on bad consequences.","zh":"這個片語著重壞後果。"}],"source":"143 - We have Star performers!.pdf","sourcePage":22},{"front":"for example","meaning":"例如","examples":[{"en":"For example, star recruits may perform worse in a new company.","zh":"例如，明星新員工在新公司中可能表現更差。"},{"en":"For example introduces a specific case that explains or supports a general point.","zh":"For example 用來引出一個解釋或支持一般重點的具體例子。"},{"en":"Many habits improve health; for example, regular sleep helps concentration.","zh":"許多習慣改善健康；例如，規律睡眠幫助專注。"},{"en":"Examples make abstract ideas easier for students to understand.","zh":"例子令抽象想法對學生更容易理解。"},{"en":"This phrase signals that a concrete illustration is coming.","zh":"這個片語標示接下來會有具體說明。"}],"source":"143 - We have Star performers!.pdf","sourcePage":22},{"front":"recruits","meaning":"新入職員工","examples":[{"en":"Recruits may perform worse after leaving their old working environment.","zh":"新入職員工離開舊工作環境後可能表現更差。"},{"en":"Recruits are people who have recently joined an organisation or team.","zh":"Recruits 是最近加入一個組織或團隊的人。"},{"en":"New recruits in a hospital need training before they understand local procedures.","zh":"醫院的新入職員工在理解本地程序前需要培訓。"},{"en":"If recruits receive little support, they may struggle even with strong experience.","zh":"如果新入職員工得到很少支援，即使經驗強也可能吃力。"},{"en":"This word focuses on newly hired or newly joined people.","zh":"這個詞著重新聘用或新加入的人。"}],"source":"143 - We have Star performers!.pdf","sourcePage":22},{"front":"considerably worse","meaning":"差得多","examples":[{"en":"Star employees may perform considerably worse after changing firms.","zh":"明星員工轉換公司後可能表現差得多。"},{"en":"Considerably worse means much worse, not just slightly worse.","zh":"Considerably worse 指差很多，而不只是差一點。"},{"en":"A student may do considerably worse if they misunderstand the exam instructions.","zh":"如果學生誤解考試指示，表現可能差得多。"},{"en":"Performance can become considerably worse when a person loses familiar tools and support.","zh":"當一個人失去熟悉工具和支援，表現可能差得多。"},{"en":"This phrase stresses a large decline.","zh":"這個片語強調大幅下降。"}],"source":"143 - We have Star performers!.pdf","sourcePage":22},{"front":"new team","meaning":"新團隊","examples":[{"en":"A star may struggle to perform in a new team.","zh":"明星人才在新團隊中可能難以表現。"},{"en":"A new team is a group of colleagues or players someone has recently joined.","zh":"New team 是某人最近加入的一組同事或球員。"},{"en":"A nurse joining a new team must learn names, routines, and communication habits.","zh":"加入新團隊的護士必須學習名字、常規和溝通習慣。"},{"en":"Even talented people need time to build trust in a new team.","zh":"即使有才華的人，也需要時間在新團隊中建立信任。"},{"en":"This phrase highlights the challenge of adjustment.","zh":"這個片語突顯適應的挑戰。"}],"source":"143 - We have Star performers!.pdf","sourcePage":22},{"front":"be accustomed to","meaning":"習慣於","examples":[{"en":"Recruits may miss the working environment to which they were accustomed.","zh":"新入職員工可能懷念他們習慣的工作環境。"},{"en":"To be accustomed to something means to be used to it because it is familiar.","zh":"To be accustomed to something 指因熟悉某事而習慣於它。"},{"en":"A student accustomed to quiet study may struggle in a noisy classroom.","zh":"習慣安靜學習的學生可能在嘈雜課室中吃力。"},{"en":"When workers lose the routines they are accustomed to, performance may fall.","zh":"當員工失去習慣的常規，表現可能下降。"},{"en":"This phrase explains how familiarity supports comfort and effectiveness.","zh":"這個片語解釋熟悉感如何支援舒適和效率。"}],"source":"143 - We have Star performers!.pdf","sourcePage":22},{"front":"move on quickly","meaning":"很快轉職","examples":[{"en":"Many star employees move on quickly after changing employers.","zh":"許多明星員工轉換僱主後很快轉職。"},{"en":"To move on quickly means to leave soon after arriving or joining.","zh":"To move on quickly 指加入或到達後很快離開。"},{"en":"A teacher may move on quickly if the new school gives little support.","zh":"如果新學校支援不足，老師可能很快轉職。"},{"en":"If star hires move on quickly, the organisation loses time, money, and stability.","zh":"如果明星新員工很快轉職，組織會失去時間、金錢和穩定性。"},{"en":"This phrase suggests fast turnover.","zh":"這個片語暗示快速流失。"}],"source":"143 - We have Star performers!.pdf","sourcePage":22},{"front":"Wall Street standards","meaning":"華爾街標準","examples":[{"en":"The movement rate was fast even by Wall Street standards.","zh":"這種轉職率即使按華爾街標準而言也很快。"},{"en":"Wall Street standards means the expectations or norms of the highly competitive finance industry.","zh":"Wall Street standards 指高度競爭金融業的期望或常態。"},{"en":"Long working hours may seem normal by Wall Street standards but extreme elsewhere.","zh":"長工時按華爾街標準可能正常，但在其他地方很極端。"},{"en":"If turnover is high even by Wall Street standards, it is unusually fast.","zh":"如果流失率即使按華爾街標準也很高，那就異常快速。"},{"en":"This phrase uses Wall Street as a demanding comparison point.","zh":"這個片語把華爾街用作嚴格比較標準。"}],"source":"143 - We have Star performers!.pdf","sourcePage":22},{"front":"increasing their salary","meaning":"提高自己的薪酬","examples":[{"en":"Stars often moved while increasing their salary.","zh":"明星人才轉職時常提高自己的薪酬。"},{"en":"Increasing their salary means getting higher pay than before.","zh":"Increasing their salary 指取得比以前更高的薪金。"},{"en":"A worker may change jobs while increasing their salary after gaining experience.","zh":"工人在累積經驗後，可能透過轉工提高自己的薪酬。"},{"en":"If stars keep increasing their salary by moving, firms may question their loyalty.","zh":"如果明星人才不斷透過轉職提高薪酬，公司可能質疑其忠誠。"},{"en":"This phrase focuses on financial gain from changing jobs.","zh":"這個片語著重轉職帶來的財務收益。"}],"source":"143 - We have Star performers!.pdf","sourcePage":22},{"front":"face resentment","meaning":"面對怨氣","examples":[{"en":"Star recruits may face resentment from colleagues.","zh":"明星新員工可能面對同事的怨氣。"},{"en":"To face resentment means to receive bitter or angry feelings from others.","zh":"To face resentment 指承受他人的苦澀或憤怒感受。"},{"en":"A new manager may face resentment if staff think they were promoted unfairly.","zh":"如果員工認為新經理晉升不公平，新經理可能面對怨氣。"},{"en":"Star recruits face resentment when colleagues feel ignored or underpaid.","zh":"當同事覺得被忽視或薪酬過低，明星新員工便會面對怨氣。"},{"en":"This phrase describes social resistance inside a group.","zh":"這個片語描述群體內部的社交阻力。"}],"source":"143 - We have Star performers!.pdf","sourcePage":22},{"front":"rejection from","meaning":"遭到……排斥","examples":[{"en":"The transplant metaphor suggests that stars may face rejection from the team.","zh":"移植比喻暗示明星人才可能遭到團隊排斥。"},{"en":"Rejection from a group means being refused acceptance or support by that group.","zh":"Rejection from a group 指被該群體拒絕接納或支援。"},{"en":"A new student may feel rejection from classmates if they are excluded from activities.","zh":"如果新學生被排除在活動之外，可能感到遭到同學排斥。"},{"en":"A star employee can face rejection from colleagues when they seem arrogant or overpaid.","zh":"當明星員工顯得傲慢或薪酬過高，可能遭到同事排斥。"},{"en":"This phrase describes being pushed away socially or organisationally.","zh":"這個片語描述在社交或組織上被推開。"}],"source":"143 - We have Star performers!.pdf","sourcePage":23},{"front":"within the team","meaning":"在團隊內部","examples":[{"en":"Tensions may arise within the team after a star is hired.","zh":"聘用明星人才後，團隊內部可能出現緊張關係。"},{"en":"Within the team means inside the group of people working together.","zh":"Within the team 指在共同工作的群體內部。"},{"en":"Problems within the team may not be visible to outside customers.","zh":"團隊內部的問題對外部顧客可能不可見。"},{"en":"If trust falls within the team, cooperation and information sharing suffer.","zh":"如果團隊內部信任下降，合作和資訊分享會受損。"},{"en":"This phrase focuses on internal group dynamics.","zh":"這個片語著重群體內部互動。"}],"source":"143 - We have Star performers!.pdf","sourcePage":23},{"front":"offending company","meaning":"犯錯的公司","examples":[{"en":"Investors may punish the offending company by selling its shares.","zh":"投資者可能透過沽售股份來懲罰犯錯的公司。"},{"en":"The offending company is the company judged to have made a bad or questionable decision.","zh":"Offending company 是被認為作出差劣或值得質疑決定的公司。"},{"en":"Customers may boycott the offending company after a safety scandal.","zh":"安全醜聞後，顧客可能抵制犯錯的公司。"},{"en":"Investors sell shares when they think the offending company is wasting money.","zh":"當投資者認為犯錯公司正在浪費金錢，便會賣出股份。"},{"en":"This phrase identifies the company being blamed.","zh":"這個片語指出被責怪的公司。"}],"source":"143 - We have Star performers!.pdf","sourcePage":23},{"front":"selling its shares","meaning":"沽售其股份","examples":[{"en":"Investors punish the company by selling its shares.","zh":"投資者透過沽售其股份來懲罰公司。"},{"en":"Selling its shares means investors sell ownership units of that company.","zh":"Selling its shares 指投資者賣出該公司的所有權單位。"},{"en":"If many investors start selling its shares, the company’s share price may fall.","zh":"如果許多投資者開始沽售其股份，公司股價可能下跌。"},{"en":"Selling shares can show that investors have lost confidence in management.","zh":"沽售股份可以顯示投資者對管理層失去信心。"},{"en":"This phrase describes a market reaction to perceived risk or poor decisions.","zh":"這個短語描述市場對感知風險或欠佳決策的反應。"}],"source":"143 - We have Star performers!.pdf","sourcePage":23}],"ielts/reading/passage-2/Practice 144":[{"front":"twin study","meaning":"雙胞胎研究","examples":[{"en":"The passage discusses how twin studies help scientists understand genes and environment.","zh":"文章討論雙胞胎研究如何幫助科學家理解基因和環境。"},{"en":"A twin study is research that compares twins to understand how much genes and environment affect people.","zh":"雙胞胎研究是比較雙胞胎，以了解基因和環境對人的影響有多大的研究。"},{"en":"Doctors may use a twin study to see whether a disease appears more often in identical twins.","zh":"醫生可能使用雙胞胎研究，看看某種疾病是否更常在同卵雙胞胎中出現。"},{"en":"Twin studies are useful because identical twins share more genes than ordinary siblings.","zh":"雙胞胎研究很有用，因為同卵雙胞胎比普通兄弟姊妹共享更多基因。"},{"en":"A twin study does not prove that genes decide everything; it helps separate genetic and environmental influences.","zh":"雙胞胎研究不是證明基因決定一切；它幫助區分遺傳和環境影響。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":1},{"front":"two of a kind","meaning":"同類的兩個；十分相似的一對","examples":[{"en":"The title “Two of a Kind” refers to twins who share many similarities.","zh":"標題 “Two of a Kind” 指有許多相似之處的雙胞胎。"},{"en":"Two of a kind means two people or things are very similar in nature, behaviour, or appearance.","zh":"two of a kind 指兩個人或事物在本質、行為或外表上非常相似。"},{"en":"Two friends who always make the same jokes may be called two of a kind.","zh":"兩個總是開同樣笑話的朋友，可以被稱為十分相似的一對。"},{"en":"If two students solve problems in exactly the same careful way, they seem two of a kind.","zh":"如果兩名學生用完全相同的細心方式解決問題，他們看起來像同類的兩個。"},{"en":"The phrase is usually friendly and suggests a close match.","zh":"這個短語通常語氣友善，暗示非常相配。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":1},{"front":"scientific study of","meaning":"對……的科學研究","examples":[{"en":"The scientific study of twins goes back to the late nineteenth century.","zh":"對雙胞胎的科學研究可追溯至十九世紀末。"},{"en":"The scientific study of something means careful research that uses evidence and method.","zh":"scientific study of something 指使用證據和方法對某事作仔細研究。"},{"en":"The scientific study of sleep helps doctors understand why rest affects memory.","zh":"對睡眠的科學研究幫助醫生理解休息為何影響記憶。"},{"en":"A scientific study of pollution can show which factories or activities cause the most harm.","zh":"對污染的科學研究可以顯示哪些工廠或活動造成最大傷害。"},{"en":"This phrase is more formal than simply saying people are interested in something.","zh":"這個短語比單純說人們對某事感興趣更正式。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":1},{"front":"go back to","meaning":"追溯至","examples":[{"en":"The scientific study of twins goes back to the late nineteenth century.","zh":"對雙胞胎的科學研究可追溯至十九世紀末。"},{"en":"If something goes back to a time, it began or existed then.","zh":"如果某事 goes back to 某個時間，意思是它在那時開始或已經存在。"},{"en":"This school tradition goes back to the 1950s.","zh":"這項學校傳統可追溯至1950年代。"},{"en":"A family recipe may go back to a grandparent who first cooked it.","zh":"一道家庭食譜可能追溯至最初烹調它的祖父母。"},{"en":"The phrase is used to show historical origin, not physical movement backwards.","zh":"這個短語用來表示歷史起源，而不是身體向後移動。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":1},{"front":"the late nineteenth century","meaning":"十九世紀末","examples":[{"en":"Twin research began in the late nineteenth century.","zh":"雙胞胎研究始於十九世紀末。"},{"en":"The late nineteenth century means the later part of the 1800s.","zh":"the late nineteenth century 指1800年代的後期。"},{"en":"Many cities grew quickly in the late nineteenth century because of industrialisation.","zh":"許多城市在十九世紀末因工業化而迅速發展。"},{"en":"Scientific ideas from the late nineteenth century influenced later medicine and biology.","zh":"十九世紀末的科學思想影響了後來的醫學和生物學。"},{"en":"The phrase gives a historical period, not an exact year.","zh":"這個短語提供歷史時期，而不是確切年份。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":1},{"front":"early geneticist","meaning":"早期遺傳學家","examples":[{"en":"Francis Galton was an early geneticist who studied twins.","zh":"Francis Galton 是研究雙胞胎的早期遺傳學家。"},{"en":"An early geneticist was one of the first scientists to study heredity and inherited traits.","zh":"early geneticist 指最早研究遺傳和遺傳特徵的科學家之一。"},{"en":"An early geneticist might compare family members to see which traits were passed down.","zh":"早期遺傳學家可能比較家庭成員，看看哪些特徵被傳承。"},{"en":"Early geneticists worked before modern DNA technology was available.","zh":"早期遺傳學家在現代 DNA 技術出現前工作。"},{"en":"The phrase places a scientist near the beginning of genetic research.","zh":"這個短語把科學家放在遺傳研究的早期階段。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":1},{"front":"come in two varieties","meaning":"分為兩類","examples":[{"en":"Francis Galton realised that twins came in two varieties.","zh":"Francis Galton 意識到雙胞胎分為兩類。"},{"en":"If something comes in two varieties, there are two main types of it.","zh":"如果某物 comes in two varieties，意思是它有兩個主要類型。"},{"en":"This phone case comes in two varieties: hard plastic and soft rubber.","zh":"這款手機殼分為兩類：硬塑膠和軟橡膠。"},{"en":"A lesson may come in two varieties, online and face-to-face, to suit different students.","zh":"課堂可以分為網上和面授兩類，以配合不同學生。"},{"en":"The phrase helps classify things simply into two groups.","zh":"這個短語幫助把事物簡單分成兩組。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":1},{"front":"identical twins","meaning":"同卵雙胞胎","examples":[{"en":"Identical twins are born from one egg.","zh":"同卵雙胞胎由一個卵子發育而成。"},{"en":"Identical twins are twins who develop from the same fertilised egg and are genetically very similar.","zh":"identical twins 指由同一個受精卵發育而成、基因非常相似的雙胞胎。"},{"en":"Identical twins may look so alike that teachers mix up their names.","zh":"同卵雙胞胎可能長得非常相似，以致老師會混淆他們的名字。"},{"en":"Because identical twins share nearly all their genes, researchers can compare them with non-identical twins.","zh":"由於同卵雙胞胎共享幾乎全部基因，研究人員可以把他們與異卵雙胞胎比較。"},{"en":"Identical twins can still have different habits, personalities, and life experiences.","zh":"同卵雙胞胎仍可以有不同習慣、性格和人生經歷。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":1},{"front":"be born from one egg","meaning":"由一個卵子發育而成","examples":[{"en":"Identical twins are born from one egg.","zh":"同卵雙胞胎由一個卵子發育而成。"},{"en":"To be born from one egg means two babies develop from a single fertilised egg.","zh":"be born from one egg 指兩個嬰兒由同一個受精卵發育而成。"},{"en":"Twins born from one egg are usually much more genetically similar than ordinary siblings.","zh":"由一個卵子發育而成的雙胞胎通常比普通兄弟姊妹在基因上更相似。"},{"en":"If twins are born from one egg, researchers classify them as identical twins.","zh":"如果雙胞胎由一個卵子發育而成，研究人員會把他們歸類為同卵雙胞胎。"},{"en":"The phrase explains biological origin, not where the babies are born.","zh":"這個短語解釋生物來源，而不是嬰兒在哪裡出生。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":1},{"front":"non-identical twins","meaning":"異卵雙胞胎","examples":[{"en":"Non-identical twins come from two eggs.","zh":"異卵雙胞胎由兩個卵子發育而成。"},{"en":"Non-identical twins are twins who develop from two different fertilised eggs.","zh":"non-identical twins 指由兩個不同受精卵發育而成的雙胞胎。"},{"en":"Non-identical twins may look no more alike than ordinary brothers and sisters.","zh":"異卵雙胞胎可能長得不比普通兄弟姊妹更相似。"},{"en":"Researchers compare non-identical twins with identical twins to estimate genetic influence.","zh":"研究人員把異卵雙胞胎與同卵雙胞胎比較，以估計遺傳影響。"},{"en":"Non-identical twins share a womb and birthday, but not exactly the same genes.","zh":"異卵雙胞胎共享子宮和生日，但不是完全相同的基因。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":1},{"front":"come from two eggs","meaning":"由兩個卵子發育而成","examples":[{"en":"Non-identical twins come from two eggs.","zh":"異卵雙胞胎由兩個卵子發育而成。"},{"en":"To come from two eggs means each twin develops from a separate fertilised egg.","zh":"come from two eggs 指每個雙胞胎由不同受精卵發育而成。"},{"en":"Twins who come from two eggs can be a boy and a girl.","zh":"由兩個卵子發育而成的雙胞胎可以是一男一女。"},{"en":"Because they come from two eggs, non-identical twins are genetically like ordinary siblings.","zh":"由於他們由兩個卵子發育而成，異卵雙胞胎在基因上像普通兄弟姊妹。"},{"en":"The phrase explains why some twins do not look almost identical.","zh":"這個短語解釋為甚麼有些雙胞胎看起來並非幾乎一模一樣。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":1},{"front":"that insight","meaning":"那個見解","examples":[{"en":"That insight turned out to be key to twin research.","zh":"那個見解結果證明是雙胞胎研究的關鍵。"},{"en":"That insight means that important understanding or realisation already mentioned.","zh":"that insight 指前文已提到的重要理解或領悟。"},{"en":"A teacher may notice that students fail because of vocabulary, and that insight changes the lesson plan.","zh":"老師可能注意到學生因詞彙而失分，而那個見解改變了教學計劃。"},{"en":"In business, one customer complaint can provide an insight that improves the whole service.","zh":"在商業中，一宗顧客投訴可以提供改善整個服務的見解。"},{"en":"The phrase points back to a useful idea that explains later progress.","zh":"這個短語指回一個有用想法，而該想法解釋後來的進展。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":2},{"front":"turn out to be key","meaning":"結果證明是關鍵","examples":[{"en":"Galton’s insight turned out to be key.","zh":"Galton 的見解結果證明是關鍵。"},{"en":"If something turns out to be key, it later proves to be very important.","zh":"如果某事 turns out to be key，意思是它後來證明非常重要。"},{"en":"A small spelling habit may turn out to be key to improving a student’s writing score.","zh":"一個小小的拼字習慣可能結果證明是提升學生寫作分數的關鍵。"},{"en":"In a police case, one short message can turn out to be key evidence.","zh":"在警方案件中，一條短訊可以結果證明是關鍵證據。"},{"en":"The phrase shows that the importance was not fully clear at first.","zh":"這個短語表示其重要性一開始未必完全清楚。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":2},{"front":"formulate","meaning":"制定；構想出","examples":[{"en":"The idea was used to formulate the twin rule of pathology.","zh":"這個想法被用來制定雙胞胎病理規則。"},{"en":"To formulate something means to create or state it carefully after thinking.","zh":"formulate something 指經思考後仔細創造或表述某事。"},{"en":"A school may formulate new rules after several safety problems occur.","zh":"學校在發生幾次安全問題後，可能制定新規則。"},{"en":"Scientists formulate a hypothesis before testing it with data.","zh":"科學家在用數據測試前會構想出一個假設。"},{"en":"The word is more formal than make and suggests careful planning.","zh":"這個詞比 make 更正式，暗示仔細計劃。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":2},{"front":"be known as","meaning":"被稱為","examples":[{"en":"The principle is known as the twin rule of pathology.","zh":"這項原則被稱為雙胞胎病理規則。"},{"en":"To be known as something means to have a name or title that people use.","zh":"be known as something 指擁有人們使用的名稱或稱號。"},{"en":"Hong Kong is known as a busy international city.","zh":"香港被稱為繁忙的國際城市。"},{"en":"A quiet student may be known as the best problem-solver in class.","zh":"一名安靜的學生可能被稱為班中最會解難的人。"},{"en":"The phrase introduces a common name, not necessarily a full explanation.","zh":"這個短語引入常用名稱，而不一定是完整解釋。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":2},{"front":"the twin rule of pathology","meaning":"雙胞胎病理規則","examples":[{"en":"The twin rule of pathology compares disease patterns in different kinds of twins.","zh":"雙胞胎病理規則比較不同類型雙胞胎的疾病模式。"},{"en":"The twin rule of pathology is a principle used to judge whether diseases may be inherited.","zh":"the twin rule of pathology 是用來判斷疾病是否可能遺傳的原則。"},{"en":"If identical twins share a disease more often than non-identical twins, the rule suggests genes may matter.","zh":"如果同卵雙胞胎比異卵雙胞胎更常共同患病，這條規則暗示基因可能重要。"},{"en":"The rule helps doctors compare illness patterns instead of guessing from one family story.","zh":"這條規則幫助醫生比較疾病模式，而不是從一個家庭故事猜測。"},{"en":"It does not mean every disease in twins is completely genetic.","zh":"它並不表示雙胞胎中的每種疾病都完全由基因決定。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":2},{"front":"twin studies really got going","meaning":"雙胞胎研究真正開始發展","examples":[{"en":"Twin studies really got going after the rule was formulated.","zh":"這條規則制定後，雙胞胎研究真正開始發展。"},{"en":"If something really gets going, it begins to develop actively and seriously.","zh":"如果某事 really gets going，意思是它開始積極而認真地發展。"},{"en":"The school debate club really got going after more students joined.","zh":"更多學生加入後，學校辯論社真正開始發展。"},{"en":"A project may really get going once funding and clear leadership are available.","zh":"一個項目在有資金和清晰領導後，可能真正開始發展。"},{"en":"The phrase suggests a slow start followed by real progress.","zh":"這個短語暗示經過緩慢開始後出現真正進展。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":2},{"front":"heritable disease","meaning":"可遺傳疾病","examples":[{"en":"A heritable disease should appear more often in both identical twins.","zh":"可遺傳疾病應更常在同卵雙胞胎雙方身上出現。"},{"en":"A heritable disease is an illness that can be influenced or passed on through genes.","zh":"heritable disease 指可以受基因影響或透過基因傳承的疾病。"},{"en":"Doctors may ask about family history when they suspect a heritable disease.","zh":"當醫生懷疑可遺傳疾病時，可能會詢問家族病史。"},{"en":"If a heritable disease is common in a family, screening may help find it early.","zh":"如果某種可遺傳疾病在家庭中常見，篩查可能有助早期發現。"},{"en":"Heritable does not always mean unavoidable, because environment and treatment may still matter.","zh":"可遺傳不一定等於無可避免，因為環境和治療仍可能重要。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":2},{"front":"be more concordant","meaning":"更一致；共同出現機會更高","examples":[{"en":"Heritable diseases are more concordant in identical twins.","zh":"可遺傳疾病在同卵雙胞胎中更一致。"},{"en":"To be more concordant means to match or appear together more often.","zh":"be more concordant 指更常相符或共同出現。"},{"en":"If two students usually give the same answers, their responses are more concordant.","zh":"如果兩名學生通常給出相同答案，他們的回答就更一致。"},{"en":"In twin research, a disease is more concordant when both twins tend to have it or both tend not to have it.","zh":"在雙胞胎研究中，如果兩人傾向同時患病或同時不患病，疾病就是更一致。"},{"en":"The phrase is formal and often used in statistics or medical research.","zh":"這個短語較正式，常用於統計或醫學研究。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":2},{"front":"jointly present or absent","meaning":"共同存在或共同不存在","examples":[{"en":"A disease may be jointly present or absent in a pair of twins.","zh":"一種疾病可能在一對雙胞胎中共同存在或共同不存在。"},{"en":"Jointly present or absent means found in both people or missing from both people.","zh":"jointly present or absent 指在兩人身上都存在，或在兩人身上都不存在。"},{"en":"If two siblings both have the same allergy, the allergy is jointly present.","zh":"如果兩名兄弟姊妹都有同一種過敏，該過敏就是共同存在。"},{"en":"If neither twin shows a symptom, that symptom is jointly absent.","zh":"如果兩名雙胞胎都沒有某症狀，該症狀就是共同不存在。"},{"en":"The phrase helps researchers compare pairs instead of looking at one person alone.","zh":"這個短語幫助研究人員比較一對人，而不是只看單一個體。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":2},{"front":"in turn","meaning":"繼而；反過來","examples":[{"en":"Non-identical twins, in turn, are more concordant than non-siblings.","zh":"異卵雙胞胎繼而比非兄弟姊妹更一致。"},{"en":"In turn means next in a sequence or as a following result.","zh":"in turn 指按順序下一步，或作為後續結果。"},{"en":"A teacher explains grammar, and students, in turn, practise it in sentences.","zh":"老師解釋文法，學生繼而在句子中練習。"},{"en":"Rising rent can raise shop prices, which in turn affects customers.","zh":"租金上升可以推高商店價格，繼而影響顧客。"},{"en":"The phrase links one comparison, step, or effect to the next.","zh":"這個短語把一個比較、步驟或影響連到下一個。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":2},{"front":"non-siblings","meaning":"非兄弟姊妹","examples":[{"en":"Non-identical twins are more similar than non-siblings.","zh":"異卵雙胞胎比非兄弟姊妹更相似。"},{"en":"Non-siblings are people who are not brothers or sisters.","zh":"non-siblings 指不是兄弟姊妹的人。"},{"en":"Two classmates may look alike, but they are non-siblings if they do not share parents.","zh":"兩名同學可能長得相似，但如果他們沒有共同父母，他們就是非兄弟姊妹。"},{"en":"Researchers compare siblings and non-siblings to estimate the role of family background.","zh":"研究人員比較兄弟姊妹和非兄弟姊妹，以估計家庭背景的作用。"},{"en":"The word is useful when family relationship matters in a comparison.","zh":"當比較中家庭關係很重要時，這個詞很有用。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":2},{"front":"early work","meaning":"早期研究","examples":[{"en":"Early work showed a correlation in skin-mole counts.","zh":"早期研究顯示皮膚痣數量之間有相關性。"},{"en":"Early work means the first research or activity done in a field.","zh":"early work 指某個領域最初進行的研究或工作。"},{"en":"Early work on online learning focused on whether students could study without a classroom.","zh":"網上學習的早期研究集中於學生能否在沒有課室下學習。"},{"en":"Early work may be simple, but it can guide later and better studies.","zh":"早期研究可能較簡單，但可以指引後來更好的研究。"},{"en":"The phrase does not mean the work was bad; it means it came near the beginning.","zh":"這個短語不是指研究差，而是指它出現在較早階段。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":3},{"front":"statistical correlation","meaning":"統計相關性","examples":[{"en":"The statistical correlation of skin-mole counts was higher in identical twins.","zh":"同卵雙胞胎皮膚痣數量的統計相關性較高。"},{"en":"Statistical correlation measures how strongly two sets of data move together.","zh":"statistical correlation 衡量兩組數據一起變動的程度。"},{"en":"A school may find a statistical correlation between attendance and exam results.","zh":"學校可能發現出席率與考試成績之間有統計相關性。"},{"en":"A strong statistical correlation can suggest a link, but it does not always prove direct cause.","zh":"強統計相關性可以暗示關聯，但不一定證明直接原因。"},{"en":"The phrase is used when researchers compare numbers, not feelings.","zh":"這個短語用於研究人員比較數字，而不是感覺。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":3},{"front":"skin-mole counts","meaning":"皮膚痣數量","examples":[{"en":"Skin-mole counts were compared between identical and non-identical twins.","zh":"研究比較了同卵和異卵雙胞胎的皮膚痣數量。"},{"en":"Skin-mole counts are the numbers of moles found on a person’s skin.","zh":"skin-mole counts 指一個人皮膚上痣的數目。"},{"en":"A doctor may record skin-mole counts to watch for changes over time.","zh":"醫生可能記錄皮膚痣數量，以觀察隨時間的變化。"},{"en":"Comparing skin-mole counts in twins can help researchers study genetic influence.","zh":"比較雙胞胎的皮膚痣數量可以幫助研究人員研究遺傳影響。"},{"en":"The phrase focuses on counted marks, not general skin colour or texture.","zh":"這個短語重點是被計算的斑點，而不是一般膚色或皮膚質感。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":3},{"front":"imply a perfect correlation","meaning":"表示完全相關","examples":[{"en":"A score of 1.0 implies a perfect correlation.","zh":"1.0 的分數表示完全相關。"},{"en":"To imply a perfect correlation means to show that two sets of data match completely.","zh":"imply a perfect correlation 指顯示兩組數據完全相符。"},{"en":"If every student’s practice score exactly matched their exam score, the data would imply a perfect correlation.","zh":"如果每名學生的練習分數都完全等同考試分數，數據就表示完全相關。"},{"en":"In real life, research data rarely imply a perfect correlation because many factors interfere.","zh":"在現實中，研究數據很少表示完全相關，因為有很多因素干擾。"},{"en":"The phrase is technical and refers to an exact statistical match.","zh":"這個短語較技術性，指精確的統計相符。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":3},{"front":"no correlation","meaning":"沒有相關性","examples":[{"en":"A score of zero implies no correlation.","zh":"零分表示沒有相關性。"},{"en":"No correlation means two things do not show a clear statistical relationship.","zh":"no correlation 指兩件事沒有顯示清晰的統計關係。"},{"en":"A shop may find no correlation between rainy days and sales of notebooks.","zh":"商店可能發現下雨天與筆記簿銷量沒有相關性。"},{"en":"If there is no correlation, one number does not help predict the other.","zh":"如果沒有相關性，一個數字就不能幫助預測另一個。"},{"en":"The phrase does not always mean no connection exists; it means the data do not show one.","zh":"這個短語不一定表示完全沒有關連；它表示數據沒有顯示關連。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":3},{"front":"suggest that","meaning":"顯示；暗示","examples":[{"en":"The result suggests that moles are heritable.","zh":"結果顯示痣是可遺傳的。"},{"en":"To suggest that something is true means to give evidence that points in that direction.","zh":"suggest that something is true 指提供指向某結論的證據。"},{"en":"Dark clouds suggest that rain may come soon.","zh":"烏雲顯示可能很快下雨。"},{"en":"If many students miss the same question, it may suggest that the explanation was unclear.","zh":"如果許多學生答錯同一道題，這可能暗示解釋不夠清楚。"},{"en":"The phrase is weaker than prove and leaves room for uncertainty.","zh":"這個短語比 prove 較弱，仍留有不確定空間。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":3},{"front":"be heritable","meaning":"可遺傳的","examples":[{"en":"The study suggests that moles are heritable.","zh":"研究顯示痣是可遺傳的。"},{"en":"To be heritable means to be influenced by genes and able to run in families.","zh":"be heritable 指受基因影響並可能在家庭中傳承。"},{"en":"Eye colour is heritable, so children may have eye colour similar to their parents.","zh":"眼睛顏色是可遺傳的，所以孩子的眼睛顏色可能與父母相似。"},{"en":"A heritable trait may still be affected by environment, health, and lifestyle.","zh":"可遺傳特質仍可能受環境、健康和生活方式影響。"},{"en":"The phrase does not mean a trait is completely fixed.","zh":"這個短語不表示某特質完全固定不變。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":3},{"front":"environmental component","meaning":"環境因素","examples":[{"en":"The development of moles also has an environmental component.","zh":"痣的形成也有環境因素。"},{"en":"An environmental component is a part of an outcome caused by surroundings or experience.","zh":"environmental component 指由周圍環境或經驗造成的某部分結果。"},{"en":"Sun exposure may be an environmental component in changes to the skin.","zh":"日曬可能是皮膚變化中的一個環境因素。"},{"en":"If a child’s reading improves after more home support, environment is one component.","zh":"如果孩子在更多家庭支援後閱讀進步，環境就是其中一個因素。"},{"en":"The phrase reminds us that genes are not the only influence.","zh":"這個短語提醒我們基因不是唯一影響。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":3},{"front":"the development of","meaning":"……的形成；發展","examples":[{"en":"Genes and environment may both affect the development of moles.","zh":"基因和環境都可能影響痣的形成。"},{"en":"The development of something means the process by which it forms, grows, or changes.","zh":"the development of something 指某事物形成、成長或改變的過程。"},{"en":"The development of a child’s language depends on hearing, practice, and interaction.","zh":"孩子語言的發展取決於聆聽、練習和互動。"},{"en":"Good sleep can support the development of memory and concentration.","zh":"良好睡眠可以支持記憶和專注力的發展。"},{"en":"The phrase focuses on process over time, not only the final result.","zh":"這個短語重點是隨時間出現的過程，而不只是最終結果。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":3},{"front":"otherwise","meaning":"否則","examples":[{"en":"Otherwise, the correlation in identical twins would be close to 1.0.","zh":"否則，同卵雙胞胎中的相關性會接近1.0。"},{"en":"Otherwise means if that were not true or if things were different.","zh":"otherwise 指如果情況並非如此，或如果事情不同。"},{"en":"Bring an umbrella; otherwise, you may get wet on the way home.","zh":"帶一把傘；否則，你回家路上可能會淋濕。"},{"en":"A rule must be explained clearly; otherwise, students may misunderstand it.","zh":"規則必須解釋清楚；否則，學生可能會誤解。"},{"en":"The word often introduces the bad or different result that would happen without action.","zh":"這個詞常引入若不採取行動會出現的壞結果或不同結果。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":3},{"front":"be close to","meaning":"接近","examples":[{"en":"If only genes mattered, the correlation would be close to 1.0.","zh":"如果只有基因重要，相關性會接近1.0。"},{"en":"To be close to a number means to be near that amount but not exactly the same.","zh":"be close to a number 指接近某個數量，但不一定完全相同。"},{"en":"If the bill is close to 500 dollars, a family may need to check the details.","zh":"如果帳單接近500元，家庭可能需要檢查細節。"},{"en":"A score close to full marks shows very strong performance.","zh":"接近滿分的分數顯示表現非常強。"},{"en":"The phrase can describe physical distance, numbers, or emotional relationship.","zh":"這個短語可以描述實際距離、數字或情感關係。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":3},{"front":"twin research","meaning":"雙胞胎研究","examples":[{"en":"Twin research has revealed how genes and environment affect behaviour.","zh":"雙胞胎研究揭示了基因和環境如何影響行為。"},{"en":"Twin research is the study of twins to understand heredity, health, personality, or behaviour.","zh":"twin research 是研究雙胞胎，以理解遺傳、健康、性格或行為。"},{"en":"Twin research may compare twins raised together and twins raised apart.","zh":"雙胞胎研究可能比較一起成長和分開成長的雙胞胎。"},{"en":"Such research can show whether a trait is shaped more by genes, environment, or both.","zh":"這類研究可以顯示某特質較受基因、環境或兩者共同塑造。"},{"en":"Twin research is powerful, but it still needs careful data and ethical rules.","zh":"雙胞胎研究很有力，但仍需要仔細數據和倫理規則。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":4},{"front":"whether or not","meaning":"是否","examples":[{"en":"Twin research studies whether or not someone takes up smoking.","zh":"雙胞胎研究研究某人是否開始吸煙。"},{"en":"Whether or not means if something happens or does not happen.","zh":"whether or not 指某事是否發生。"},{"en":"A teacher may ask whether or not students understood the homework.","zh":"老師可能詢問學生是否明白功課。"},{"en":"Parents may decide whether or not a child is ready to travel alone.","zh":"父母可能決定孩子是否準備好獨自出行。"},{"en":"The phrase clearly includes both possible answers: yes and no.","zh":"這個短語清楚包括兩種可能答案：是和否。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":4},{"front":"take up smoking","meaning":"開始吸煙","examples":[{"en":"Whether someone takes up smoking is mainly determined by the environment.","zh":"一個人是否開始吸煙主要由環境決定。"},{"en":"To take up smoking means to begin smoking as a habit.","zh":"take up smoking 指開始把吸煙變成習慣。"},{"en":"A teenager may take up smoking if many friends smoke after school.","zh":"如果許多朋友放學後吸煙，青少年可能開始吸煙。"},{"en":"Public health education tries to stop young people from taking up smoking.","zh":"公共健康教育嘗試阻止年輕人開始吸煙。"},{"en":"The phrase focuses on starting the habit, not how much a person smokes later.","zh":"這個短語重點是開始這個習慣，而不是之後吸多少。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":4},{"front":"be determined mainly by","meaning":"主要由……決定","examples":[{"en":"Smoking initiation is determined mainly by environmental factors.","zh":"開始吸煙主要由環境因素決定。"},{"en":"To be determined mainly by something means to be decided mostly by that factor.","zh":"be determined mainly by something 指主要由某因素決定。"},{"en":"A student’s travel time may be determined mainly by where they live.","zh":"學生的交通時間可能主要由居住地決定。"},{"en":"Shop rent is often determined mainly by location and customer traffic.","zh":"商店租金通常主要由地點和人流決定。"},{"en":"The phrase allows other influences, but shows one factor is the strongest.","zh":"這個短語容許其他影響，但顯示某因素最強。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":4},{"front":"environmental factors","meaning":"環境因素","examples":[{"en":"Environmental factors influence whether someone starts smoking.","zh":"環境因素影響一個人是否開始吸煙。"},{"en":"Environmental factors are outside conditions, experiences, or surroundings that affect a person.","zh":"environmental factors 指影響一個人的外在條件、經驗或周圍環境。"},{"en":"Family habits, friends, school rules, and advertising can be environmental factors.","zh":"家庭習慣、朋友、校規和廣告都可以是環境因素。"},{"en":"If a child has quiet study space at home, that is an environmental factor supporting learning.","zh":"如果孩子家中有安靜的學習空間，那就是支持學習的環境因素。"},{"en":"The phrase contrasts with genetic factors inside the body.","zh":"這個短語與身體內的遺傳因素形成對比。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":4},{"front":"once someone does so","meaning":"一旦某人這樣做","examples":[{"en":"Once someone takes up smoking, genes affect how much they smoke.","zh":"一旦某人開始吸煙，基因會影響他吸多少。"},{"en":"Once someone does so means after that person has done the action just mentioned.","zh":"once someone does so 指某人完成剛提到的行動之後。"},{"en":"A student may join a club, and once she does so, she must attend meetings.","zh":"學生可以加入社團，而一旦她這樣做，就必須出席會議。"},{"en":"A customer can cancel an order, but once he does so, the shop may not reserve the item.","zh":"顧客可以取消訂單，但一旦他這樣做，商店可能不再保留貨品。"},{"en":"The phrase avoids repeating the earlier action.","zh":"這個短語避免重複前文的行動。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":4},{"front":"be largely down to","meaning":"很大程度上取決於","examples":[{"en":"How much a smoker smokes is largely down to genes.","zh":"吸煙者吸多少煙很大程度上取決於基因。"},{"en":"To be largely down to something means to be mostly caused or explained by it.","zh":"be largely down to something 指主要由某事造成或解釋。"},{"en":"A team’s success may be largely down to good communication.","zh":"團隊成功可能很大程度上取決於良好溝通。"},{"en":"A student’s improvement is often largely down to regular practice, not luck.","zh":"學生的進步通常很大程度上取決於定期練習，而不是運氣。"},{"en":"The phrase is conversational and means one factor is especially important.","zh":"這個短語較口語，意思是某因素特別重要。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":4},{"front":"a cultural attribute","meaning":"文化屬性","examples":[{"en":"A person’s religion is clearly a cultural attribute.","zh":"一個人的宗教明顯是一種文化屬性。"},{"en":"A cultural attribute is a feature connected with a society’s beliefs, customs, or way of life.","zh":"cultural attribute 指與社會信念、習俗或生活方式有關的特徵。"},{"en":"Language, festivals, table manners, and dress can be cultural attributes.","zh":"語言、節日、餐桌禮儀和服飾都可以是文化屬性。"},{"en":"A cultural attribute may be learned from family, school, media, and community life.","zh":"文化屬性可能從家庭、學校、媒體和社區生活中學習得來。"},{"en":"The phrase describes social learning more than biology.","zh":"這個短語描述社會學習多於生物因素。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":4},{"front":"genetic component","meaning":"遺傳成分","examples":[{"en":"Religious fundamentalism has a strong genetic component.","zh":"宗教原教旨主義有很強的遺傳成分。"},{"en":"A genetic component is the part of a trait or condition influenced by genes.","zh":"genetic component 指某特質或狀況中受基因影響的部分。"},{"en":"Height has a genetic component because children often resemble their parents in height.","zh":"身高有遺傳成分，因為孩子身高常與父母相似。"},{"en":"A condition can have a genetic component while still being affected by diet or lifestyle.","zh":"一種狀況可以有遺傳成分，同時仍受飲食或生活方式影響。"},{"en":"The phrase means genes play a role, not that genes are the only cause.","zh":"這個短語表示基因有作用，而不是基因是唯一原因。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":4},{"front":"religious fundamentalism","meaning":"宗教原教旨主義","examples":[{"en":"Twin studies suggest that religious fundamentalism has a genetic component.","zh":"雙胞胎研究顯示宗教原教旨主義有遺傳成分。"},{"en":"Religious fundamentalism is a strict form of religious belief that strongly resists change or compromise.","zh":"religious fundamentalism 指一種嚴格的宗教信念形式，強烈抗拒改變或妥協。"},{"en":"Researchers may study religious fundamentalism as part of personality, culture, and social behaviour.","zh":"研究人員可能把宗教原教旨主義作為性格、文化和社會行為的一部分來研究。"},{"en":"Religious fundamentalism can affect how people view education, politics, or family rules.","zh":"宗教原教旨主義可以影響人們如何看待教育、政治或家庭規則。"},{"en":"The phrase should be used carefully because religious people can differ greatly.","zh":"這個短語應小心使用，因為宗教人士之間可以有很大差異。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":4},{"front":"unravel the heritability of","meaning":"解開……遺傳性的謎團","examples":[{"en":"Twin studies are unravelling the heritability of human personality.","zh":"雙胞胎研究正在解開人類性格遺傳性的謎團。"},{"en":"To unravel the heritability of something means to gradually understand how genes influence it.","zh":"unravel the heritability of something 指逐步理解基因如何影響某事物。"},{"en":"Scientists try to unravel the heritability of anxiety by comparing families and twins.","zh":"科學家透過比較家庭和雙胞胎，嘗試解開焦慮遺傳性的謎團。"},{"en":"Large datasets can help researchers unravel the heritability of complex traits.","zh":"大型數據集可以幫助研究人員解開複雜特質遺傳性的謎團。"},{"en":"The phrase suggests a difficult question being slowly solved.","zh":"這個短語暗示一個困難問題正被慢慢解開。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":4},{"front":"various aspects of","meaning":"……的各個方面","examples":[{"en":"Researchers study various aspects of human personality.","zh":"研究人員研究人類性格的各個方面。"},{"en":"Various aspects of something are its different parts, features, or sides.","zh":"various aspects of something 指某事物的不同部分、特徵或層面。"},{"en":"A school report may discuss various aspects of student life, such as learning, friendship, and health.","zh":"學校報告可能討論學生生活的各個方面，例如學習、友誼和健康。"},{"en":"Looking at various aspects of a problem helps people avoid a one-sided solution.","zh":"審視問題的各個方面有助人們避免片面解決方案。"},{"en":"The phrase is useful when a topic has many parts.","zh":"當一個主題有很多部分時，這個短語很有用。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":5},{"front":"human personality","meaning":"人類性格","examples":[{"en":"Twin studies investigate the genetic basis of human personality.","zh":"雙胞胎研究調查人類性格的遺傳基礎。"},{"en":"Human personality means the patterns of feeling, thinking, and behaviour that make people different.","zh":"human personality 指令人與人不同的感受、思想和行為模式。"},{"en":"A person’s human personality may include patience, curiosity, confidence, or shyness.","zh":"一個人的人類性格可能包括耐性、好奇心、自信或害羞。"},{"en":"Human personality can be shaped by genes, family life, school, and personal experiences.","zh":"人類性格可以受基因、家庭生活、學校和個人經歷塑造。"},{"en":"The phrase refers to long-term character patterns, not one temporary mood.","zh":"這個短語指長期性格模式，而不是一時心情。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":5},{"front":"traits","meaning":"特質","examples":[{"en":"Many personality traits have large genetic components.","zh":"許多性格特質有很大的遺傳成分。"},{"en":"Traits are particular qualities or features of a person, animal, or thing.","zh":"traits 指人、動物或事物的特定品質或特徵。"},{"en":"Honesty, patience, and curiosity are traits teachers may notice in students.","zh":"誠實、耐性和好奇心是老師可能在學生身上注意到的特質。"},{"en":"Some traits are easy to see, while others appear only in certain situations.","zh":"有些特質容易看見，另一些只在特定情況下出現。"},{"en":"The word is often used when describing personality, biology, or behaviour.","zh":"這個詞常用於描述性格、生物或行為。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":5},{"front":"neuroticism","meaning":"神經質傾向","examples":[{"en":"Neuroticism is one personality trait studied in twin research.","zh":"神經質傾向是雙胞胎研究中研究的一種性格特質。"},{"en":"Neuroticism is a tendency to feel worry, fear, sadness, or emotional instability more easily.","zh":"neuroticism 指較容易感到擔憂、恐懼、悲傷或情緒不穩的傾向。"},{"en":"A person high in neuroticism may feel stressed by small changes in plans.","zh":"神經質傾向較高的人可能因計劃小變動而感到壓力。"},{"en":"Neuroticism can affect work and relationships if worry becomes hard to manage.","zh":"如果擔憂變得難以管理，神經質傾向可以影響工作和人際關係。"},{"en":"The term is psychological and does not simply mean someone is weak.","zh":"這個詞是心理學用語，不是單純指某人軟弱。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":5},{"front":"anxiety","meaning":"焦慮","examples":[{"en":"Anxiety can have a large genetic component.","zh":"焦慮可以有很大的遺傳成分。"},{"en":"Anxiety is a feeling of worry, fear, or tension, especially about something uncertain.","zh":"anxiety 指擔憂、恐懼或緊張感，尤其是面對不確定事情時。"},{"en":"A student may feel anxiety before an important speaking exam.","zh":"學生可能在重要口語考試前感到焦慮。"},{"en":"Long-term anxiety can affect sleep, concentration, and daily decisions.","zh":"長期焦慮可以影響睡眠、專注力和日常決定。"},{"en":"The word describes a mental and physical state, not just ordinary carefulness.","zh":"這個詞描述心理和身體狀態，而不只是普通謹慎。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":5},{"front":"thrill-seeking","meaning":"尋求刺激","examples":[{"en":"Thrill-seeking is partly influenced by genes.","zh":"尋求刺激部分受基因影響。"},{"en":"Thrill-seeking is the desire to do exciting, risky, or intense activities.","zh":"thrill-seeking 指渴望進行刺激、有風險或強烈活動。"},{"en":"Someone who enjoys roller coasters, extreme sports, and scary films may show thrill-seeking.","zh":"喜歡過山車、極限運動和恐怖片的人可能表現出尋求刺激。"},{"en":"Thrill-seeking can lead to adventure, but it can also increase risk if judgment is poor.","zh":"尋求刺激可以帶來冒險，但如果判斷力差，也可能增加風險。"},{"en":"The phrase focuses on seeking excitement, not simply enjoying fun.","zh":"這個短語重點是追求刺激，而不只是喜歡娛樂。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":5},{"front":"novelty-seeking","meaning":"追求新奇","examples":[{"en":"Novelty-seeking is one of the traits studied in twin research.","zh":"追求新奇是雙胞胎研究中研究的特質之一。"},{"en":"Novelty-seeking is the tendency to look for new experiences, ideas, or sensations.","zh":"novelty-seeking 指尋找新經驗、新想法或新感覺的傾向。"},{"en":"A novelty-seeking student may enjoy trying unfamiliar food or learning unusual topics.","zh":"追求新奇的學生可能喜歡嘗試陌生食物或學習不尋常主題。"},{"en":"Novelty-seeking can support creativity, but too much may make routines difficult.","zh":"追求新奇可以支持創意，但過度則可能令日常規律變困難。"},{"en":"The phrase describes attraction to newness, not simply being careless.","zh":"這個短語描述對新事物的吸引，而不只是粗心。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":5},{"front":"large genetic components","meaning":"很大的遺傳成分","examples":[{"en":"Several personality traits have large genetic components.","zh":"幾種性格特質有很大的遺傳成分。"},{"en":"Large genetic components mean genes explain a big part of the difference between people.","zh":"large genetic components 指基因解釋了人與人之間差異的一大部分。"},{"en":"Height often has large genetic components because children tend to resemble their parents.","zh":"身高通常有很大的遺傳成分，因為孩子傾向與父母相似。"},{"en":"Even when traits have large genetic components, environment can still shape how they appear.","zh":"即使特質有很大的遺傳成分，環境仍可以塑造其表現方式。"},{"en":"The phrase means strong genetic influence, not total genetic control.","zh":"這個短語表示強烈遺傳影響，而不是完全由基因控制。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":5},{"front":"parenting matters","meaning":"教養很重要","examples":[{"en":"Parenting matters, but it does not completely determine personality.","zh":"教養很重要，但它不會完全決定性格。"},{"en":"Parenting matters means the way parents raise children is important.","zh":"parenting matters 指父母養育孩子的方式很重要。"},{"en":"Parenting matters when parents teach children how to handle anger and disappointment.","zh":"當父母教孩子處理憤怒和失望時，教養很重要。"},{"en":"Good parenting can give children safety, language practice, and emotional support.","zh":"良好教養可以給孩子安全感、語言練習和情感支持。"},{"en":"The phrase does not mean parents control every outcome in a child’s life.","zh":"這個短語不是指父母控制孩子人生中的每個結果。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":5},{"front":"determine personality","meaning":"決定性格","examples":[{"en":"Parenting does not determine personality in the way once imagined.","zh":"教養並不如過去想像那樣決定性格。"},{"en":"To determine personality means to decide or shape a person’s long-term character.","zh":"determine personality 指決定或塑造一個人的長期性格。"},{"en":"A strict school alone cannot determine personality, because family and genes also matter.","zh":"單靠嚴格學校不能決定性格，因為家庭和基因也重要。"},{"en":"Early praise may shape confidence, but it does not completely determine personality.","zh":"早期稱讚可能塑造自信，但不會完全決定性格。"},{"en":"The phrase is strong, so it should be used when discussing major influence.","zh":"這個短語語氣很強，因此應用於討論重大影響。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":5},{"front":"in the way that","meaning":"以……的方式","examples":[{"en":"Parenting does not shape personality in the way that some people had thought.","zh":"教養並不是以一些人曾經以為的方式塑造性格。"},{"en":"In the way that means in the manner or form that someone describes.","zh":"in the way that 指以某人所描述的方式或形式。"},{"en":"A child may not learn English in the way that adults expect.","zh":"孩子未必以成年人期望的方式學英文。"},{"en":"Technology changes work in the way that people communicate and share files.","zh":"科技以人們溝通和分享文件的方式改變工作。"},{"en":"The phrase links an action with the specific manner in which it happens.","zh":"這個短語把行動與其發生的具體方式連起來。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":5},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, twin studies are helping scientists understand diseases.","zh":"更重要的是，雙胞胎研究正幫助科學家理解疾病。"},{"en":"More importantly introduces a point that matters even more than the previous one.","zh":"more importantly 引入比前一點更重要的內容。"},{"en":"The app is cheap; more importantly, it is easy for older people to use.","zh":"這個應用程式便宜；更重要的是，長者容易使用。"},{"en":"A lesson should be interesting; more importantly, students should understand it.","zh":"課堂應該有趣；更重要的是，學生應該明白。"},{"en":"The phrase helps writers rank ideas by importance.","zh":"這個短語幫助寫作者按重要性排列想法。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":6},{"front":"help the understanding of","meaning":"幫助理解……","examples":[{"en":"Twin studies help the understanding of many diseases.","zh":"雙胞胎研究幫助理解許多疾病。"},{"en":"To help the understanding of something means to make it clearer or easier to explain.","zh":"help the understanding of something 指令某事更清楚或更容易解釋。"},{"en":"Diagrams help the understanding of difficult grammar rules.","zh":"圖表幫助理解困難文法規則。"},{"en":"Patient interviews help the understanding of how illness affects daily life.","zh":"病人訪談幫助理解疾病如何影響日常生活。"},{"en":"The phrase is formal and often used in academic or scientific writing.","zh":"這個短語較正式，常用於學術或科學寫作。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":6},{"front":"immune disorders","meaning":"免疫系統疾病","examples":[{"en":"Twin studies can help researchers understand immune disorders.","zh":"雙胞胎研究可以幫助研究人員理解免疫系統疾病。"},{"en":"Immune disorders are illnesses in which the immune system does not work normally.","zh":"immune disorders 指免疫系統不能正常運作的疾病。"},{"en":"Allergies and autoimmune diseases can be examples of immune disorders.","zh":"過敏和自身免疫疾病可以是免疫系統疾病的例子。"},{"en":"Immune disorders may cause the body to overreact or attack its own tissues.","zh":"免疫系統疾病可能令身體過度反應或攻擊自身組織。"},{"en":"The phrase is medical and refers to problems with the body’s defence system.","zh":"這個短語是醫學用語，指身體防禦系統的問題。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":6},{"front":"within ethical guidelines","meaning":"在倫理指引範圍內","examples":[{"en":"Twins can be used in medical experiments within ethical guidelines.","zh":"雙胞胎可以在倫理指引範圍內用於醫學實驗。"},{"en":"Within ethical guidelines means following rules that protect people’s rights, safety, and dignity.","zh":"within ethical guidelines 指遵守保護人權利、安全和尊嚴的規則。"},{"en":"A hospital study must stay within ethical guidelines by getting informed consent.","zh":"醫院研究必須透過取得知情同意而留在倫理指引範圍內。"},{"en":"Research outside ethical guidelines may harm participants or misuse private information.","zh":"超出倫理指引的研究可能傷害參與者或濫用私人資料。"},{"en":"The phrase stresses that science must have moral limits.","zh":"這個短語強調科學必須有道德界限。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":6},{"front":"medical experiments","meaning":"醫學實驗","examples":[{"en":"Twins can be used for medical experiments under ethical rules.","zh":"雙胞胎可以在倫理規則下用於醫學實驗。"},{"en":"Medical experiments are controlled tests designed to study health, disease, or treatment.","zh":"medical experiments 指為研究健康、疾病或治療而設計的受控測試。"},{"en":"A medical experiment may compare a new medicine with a standard treatment.","zh":"醫學實驗可能比較新藥與標準治療。"},{"en":"Medical experiments require consent because participants may face risks or discomfort.","zh":"醫學實驗需要同意，因為參與者可能面對風險或不適。"},{"en":"The phrase refers to planned scientific testing, not ordinary medical care.","zh":"這個短語指有計劃的科學測試，而不是普通醫療護理。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":6},{"front":"administer vitamin C to","meaning":"給……服用維他命 C","examples":[{"en":"Researchers administered vitamin C to one twin and a placebo to the other.","zh":"研究人員給其中一名雙胞胎服用維他命 C，另一名則服用安慰劑。"},{"en":"To administer vitamin C to someone means to give that person vitamin C in a controlled way.","zh":"administer vitamin C to someone 指以受控方式給某人服用維他命 C。"},{"en":"A nurse may administer medicine to a patient at a fixed time each day.","zh":"護士可能每天固定時間給病人服藥。"},{"en":"In a study, researchers must record exactly when they administer vitamin C to participants.","zh":"在研究中，研究人員必須準確記錄何時給參與者服用維他命 C。"},{"en":"The verb administer is formal and often used in medical settings.","zh":"administer 這個動詞較正式，常用於醫療情境。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":6},{"front":"a placebo","meaning":"安慰劑","examples":[{"en":"One twin received vitamin C and the other received a placebo.","zh":"一名雙胞胎服用維他命 C，另一名服用安慰劑。"},{"en":"A placebo is a substance with no active treatment effect, used for comparison in experiments.","zh":"placebo 指沒有主動治療效果、用於實驗比較的物質。"},{"en":"In a drug trial, one group may receive medicine while another receives a placebo.","zh":"在藥物試驗中，一組可能服藥，另一組服用安慰劑。"},{"en":"Placebos help researchers see whether improvement comes from the treatment itself.","zh":"安慰劑幫助研究人員判斷改善是否來自治療本身。"},{"en":"The phrase is common in medical research and testing.","zh":"這個短語常見於醫學研究和測試。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":6},{"front":"have no effect on","meaning":"對……沒有作用","examples":[{"en":"The study found that vitamin C had no effect on the common cold.","zh":"研究發現維他命 C 對普通感冒沒有作用。"},{"en":"To have no effect on something means not to change it in any clear way.","zh":"have no effect on something 指沒有以任何清楚方式改變某事。"},{"en":"Changing the font had no effect on the student’s essay score.","zh":"改變字體對學生作文分數沒有作用。"},{"en":"If a medicine has no effect on symptoms, doctors may try another treatment.","zh":"如果藥物對症狀沒有作用，醫生可能嘗試另一種治療。"},{"en":"The phrase means the result stays the same despite the action.","zh":"這個短語表示即使採取行動，結果仍然一樣。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":6},{"front":"the common cold","meaning":"普通感冒","examples":[{"en":"Vitamin C was tested for its effect on the common cold.","zh":"維他命 C 被測試其對普通感冒的作用。"},{"en":"The common cold is a mild illness that often causes a runny nose, sore throat, and coughing.","zh":"common cold 指常造成流鼻水、喉嚨痛和咳嗽的輕微疾病。"},{"en":"Students may miss class because the common cold spreads easily in winter.","zh":"學生可能因普通感冒在冬天容易傳播而缺課。"},{"en":"The common cold is usually not serious, but it can make people tired and uncomfortable.","zh":"普通感冒通常不嚴重，但會令人疲倦和不舒服。"},{"en":"The phrase refers to an everyday illness, not a rare disease.","zh":"這個短語指日常疾病，而不是罕見疾病。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":6},{"front":"the lesson from","meaning":"從……得出的啟示","examples":[{"en":"The lesson from twin studies is that most traits are partly genetic.","zh":"從雙胞胎研究得出的啟示是，大多數特質部分由基因影響。"},{"en":"The lesson from something is the main idea or warning people learn from it.","zh":"the lesson from something 指人們從某事中學到的主要想法或警示。"},{"en":"The lesson from a failed project may be that communication must improve.","zh":"從失敗項目得出的啟示可能是溝通必須改善。"},{"en":"The lesson from an accident can lead to safer rules.","zh":"從事故得出的啟示可以帶來更安全的規則。"},{"en":"The phrase turns an experience or study into a useful conclusion.","zh":"這個短語把經驗或研究轉化為有用結論。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":6},{"front":"human traits","meaning":"人類特質","examples":[{"en":"Most human traits are at least partially influenced by genes.","zh":"大多數人類特質至少部分受基因影響。"},{"en":"Human traits are qualities, abilities, or features found in people.","zh":"human traits 指在人身上出現的品質、能力或特徵。"},{"en":"Height, anxiety, patience, and musical ability can all be human traits.","zh":"身高、焦慮、耐性和音樂能力都可以是人類特質。"},{"en":"Human traits usually develop through both biology and experience.","zh":"人類特質通常透過生物因素和經驗共同發展。"},{"en":"The phrase is broad and can include physical, mental, and behavioural features.","zh":"這個短語很廣泛，可包括身體、心理和行為特徵。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":6},{"front":"at least partially","meaning":"至少部分地","examples":[{"en":"Most human traits are at least partially influenced by genes.","zh":"大多數人類特質至少部分地受基因影響。"},{"en":"At least partially means not completely, but to some degree or more.","zh":"at least partially 指不是完全地，但至少在某程度上。"},{"en":"A student’s success is at least partially due to regular practice.","zh":"學生的成功至少部分地歸因於定期練習。"},{"en":"Traffic problems are at least partially caused by too many private cars.","zh":"交通問題至少部分地由太多私家車造成。"},{"en":"The phrase is careful because it avoids claiming a full explanation.","zh":"這個短語較謹慎，因為它避免聲稱完整解釋。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":7},{"front":"be influenced by genes","meaning":"受基因影響","examples":[{"en":"Many traits are influenced by genes.","zh":"許多特質受基因影響。"},{"en":"To be influenced by genes means to be affected by inherited biological information.","zh":"be influenced by genes 指受遺傳下來的生物資訊影響。"},{"en":"A person’s height can be influenced by genes from both parents.","zh":"一個人的身高可以受來自父母雙方的基因影響。"},{"en":"A trait influenced by genes may still change with diet, training, or environment.","zh":"受基因影響的特質仍可能隨飲食、訓練或環境而改變。"},{"en":"The phrase shows genetic effect without saying genes control everything.","zh":"這個短語顯示基因效應，但不是說基因控制一切。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":7},{"front":"for the most part","meaning":"在大多數情況下","examples":[{"en":"For the most part, the nature-versus-nurture distinction is not very useful.","zh":"在大多數情況下，先天與後天的區分不太有用。"},{"en":"For the most part means mostly or generally, though not in every case.","zh":"for the most part 指大部分或一般而言，但並非每一情況。"},{"en":"For the most part, the new timetable works well for students.","zh":"在大多數情況下，新時間表對學生運作良好。"},{"en":"The neighbourhood is quiet for the most part, except during festival nights.","zh":"這個社區在大多數情況下很安靜，節日夜晚除外。"},{"en":"The phrase allows small exceptions while describing the general situation.","zh":"這個短語容許小例外，同時描述整體情況。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":7},{"front":"age-old dichotomy","meaning":"古老的二分法","examples":[{"en":"The age-old dichotomy between nature and nurture is not very useful.","zh":"先天與後天之間的古老二分法不太有用。"},{"en":"An age-old dichotomy is a very old division of ideas into two opposing sides.","zh":"age-old dichotomy 指把想法分成兩個對立面的非常古老區分。"},{"en":"The age-old dichotomy between work and rest can be too simple for modern life.","zh":"工作與休息之間的古老二分法對現代生活而言可能過於簡單。"},{"en":"When problems are complex, an age-old dichotomy may hide the real connections.","zh":"當問題複雜時，古老的二分法可能掩蓋真正關連。"},{"en":"The phrase often suggests an old debate that may need updating.","zh":"這個短語常暗示一場古老爭論可能需要更新。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":7},{"front":"nature and nurture","meaning":"先天與後天","examples":[{"en":"The relationship between nature and nurture is complex.","zh":"先天與後天之間的關係很複雜。"},{"en":"Nature and nurture refer to genes and biology on one side, and environment and experience on the other.","zh":"nature and nurture 一方面指基因和生物因素，另一方面指環境和經驗。"},{"en":"A child’s language ability may reflect both nature and nurture.","zh":"孩子的語言能力可能反映先天與後天兩者。"},{"en":"Twin research studies how nature and nurture work together rather than separately.","zh":"雙胞胎研究研究先天與後天如何共同作用，而不是分開作用。"},{"en":"The phrase is useful for discussing why people become different from one another.","zh":"這個短語適合討論人們為何變得彼此不同。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":7},{"front":"not very useful","meaning":"不太有用","examples":[{"en":"The old nature-nurture debate is not very useful.","zh":"舊有的先天與後天之爭不太有用。"},{"en":"Not very useful means something does not help much or does not explain enough.","zh":"not very useful 指某事幫助不大或解釋不足。"},{"en":"A grammar rule is not very useful if students cannot apply it in real sentences.","zh":"如果學生不能把文法規則用在真實句子中，它就不太有用。"},{"en":"A map is not very useful when it shows old roads that no longer exist.","zh":"如果地圖顯示已不存在的舊道路，它就不太有用。"},{"en":"The phrase is polite but clear criticism.","zh":"這個短語是禮貌但清楚的批評。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":7},{"front":"genetic programs","meaning":"基因程序","examples":[{"en":"Many genetic programs are open to input from the environment.","zh":"許多基因程序容許來自環境的影響。"},{"en":"Genetic programs are biological instructions in genes that guide development and body functions.","zh":"genetic programs 指基因中的生物指令，指引發展和身體功能。"},{"en":"Growth, repair, and some behaviours may be guided by genetic programs.","zh":"生長、修復和一些行為可能受基因程序指引。"},{"en":"Environmental signals can affect how genetic programs operate in the body.","zh":"環境訊號可以影響基因程序在身體中的運作方式。"},{"en":"The phrase makes genes sound like instructions, but they still interact with conditions around them.","zh":"這個短語令基因聽起來像指令，但它們仍會與周圍條件互動。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":7},{"front":"be open to input from","meaning":"容許來自……的影響","examples":[{"en":"Genetic programs can be open to input from the environment.","zh":"基因程序可以容許來自環境的影響。"},{"en":"To be open to input from something means to be able to receive influence or information from it.","zh":"be open to input from something 指能接受來自某事物的影響或資訊。"},{"en":"A school policy should be open to input from teachers, students, and parents.","zh":"學校政策應容許來自老師、學生和家長的意見。"},{"en":"A young child’s language development is open to input from daily conversation.","zh":"幼兒的語言發展會受日常對話的影響。"},{"en":"The phrase suggests flexibility rather than a fixed system.","zh":"這個短語暗示靈活性，而不是固定系統。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":7},{"front":"be switched on or off","meaning":"被開啟或關閉","examples":[{"en":"Genes can be switched on or off by environmental signals.","zh":"基因可以被環境訊號開啟或關閉。"},{"en":"To be switched on or off means to become active or inactive.","zh":"be switched on or off 指變成活躍或不活躍。"},{"en":"A phone can be switched on or off with one button.","zh":"手機可以用一個按鈕開啟或關閉。"},{"en":"Some biological processes may be switched on or off by stress, food, or light.","zh":"一些生物過程可能被壓力、食物或光線開啟或關閉。"},{"en":"The phrase uses a switch metaphor to describe activation and deactivation.","zh":"這個短語用開關比喻來描述啟動和停用。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":7},{"front":"environmental signals","meaning":"環境訊號","examples":[{"en":"Environmental signals can switch genes on or off.","zh":"環境訊號可以開啟或關閉基因。"},{"en":"Environmental signals are outside cues, such as food, stress, light, or experience, that affect the body.","zh":"environmental signals 指影響身體的外在提示，例如食物、壓力、光線或經驗。"},{"en":"Bright morning light can act as an environmental signal for the sleep cycle.","zh":"清晨明亮光線可以作為睡眠週期的環境訊號。"},{"en":"If environmental signals change, the body may respond by adjusting biological processes.","zh":"如果環境訊號改變，身體可能透過調整生物過程作出反應。"},{"en":"The phrase connects the outside world with internal biological responses.","zh":"這個短語把外在世界與內在生物反應連起來。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":7},{"front":"influence their environment","meaning":"影響其環境","examples":[{"en":"Genes themselves may influence their environment.","zh":"基因本身可能影響其環境。"},{"en":"To influence their environment means to affect the surroundings or experiences people choose or create.","zh":"influence their environment 指影響人們選擇或創造的周圍環境或經驗。"},{"en":"A naturally outgoing child may influence their environment by making more friends.","zh":"天生外向的孩子可能透過結交更多朋友來影響其環境。"},{"en":"If someone enjoys sport, that preference can influence their environment by leading them to sports clubs.","zh":"如果某人喜歡運動，這種偏好可以透過令他加入運動社團來影響其環境。"},{"en":"The phrase shows that people are not only shaped by surroundings; they may also shape them.","zh":"這個短語顯示人不只是被環境塑造；他們也可能塑造環境。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":7},{"front":"innate preference","meaning":"天生偏好","examples":[{"en":"Some humans have an innate preference for sports.","zh":"有些人對運動有天生偏好。"},{"en":"An innate preference is a liking that seems natural or present from birth.","zh":"innate preference 指似乎自然存在或與生俱來的喜好。"},{"en":"A child with an innate preference for music may move to rhythm before formal lessons.","zh":"對音樂有天生偏好的孩子，可能在正式上課前已會隨節奏擺動。"},{"en":"Innate preferences can guide choices, but practice and environment still matter.","zh":"天生偏好可以引導選擇，但練習和環境仍重要。"},{"en":"The phrase contrasts natural tendency with learned habit.","zh":"這個短語把自然傾向與後天習慣作對比。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":8},{"front":"participation in sports","meaning":"參與運動","examples":[{"en":"Some people have an innate preference for participation in sports.","zh":"有些人對參與運動有天生偏好。"},{"en":"Participation in sports means taking part in physical games, exercise, or athletic activities.","zh":"participation in sports 指參與體育遊戲、鍛鍊或運動活動。"},{"en":"Schools encourage participation in sports to improve health and teamwork.","zh":"學校鼓勵參與運動，以改善健康和團隊合作。"},{"en":"Participation in sports can build confidence, but injuries may occur without proper training.","zh":"參與運動可以建立信心，但如果缺乏適當訓練也可能受傷。"},{"en":"The phrase refers to active involvement, not just watching matches.","zh":"這個短語指主動參與，而不是只觀看比賽。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":8},{"front":"be drawn to","meaning":"被……吸引","examples":[{"en":"Some people are drawn to novelty.","zh":"有些人被新奇事物吸引。"},{"en":"To be drawn to something means to feel naturally attracted to it.","zh":"be drawn to something 指自然地被某事物吸引。"},{"en":"A shy student may be drawn to quiet places such as libraries.","zh":"害羞的學生可能被圖書館等安靜地方吸引。"},{"en":"People drawn to adventure may choose jobs that involve travel.","zh":"被冒險吸引的人可能選擇涉及旅行的工作。"},{"en":"The phrase describes attraction that feels strong or natural.","zh":"這個短語描述感覺強烈或自然的吸引力。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":8},{"front":"certain kinds of friends","meaning":"某些類型的朋友","examples":[{"en":"Genes may influence whether people are drawn to certain kinds of friends.","zh":"基因可能影響人們是否被某些類型的朋友吸引。"},{"en":"Certain kinds of friends means particular types of friends with shared qualities or habits.","zh":"certain kinds of friends 指具有共同品質或習慣的特定朋友類型。"},{"en":"A student may prefer certain kinds of friends who enjoy studying quietly.","zh":"學生可能偏好某些喜歡安靜學習的朋友。"},{"en":"Choosing certain kinds of friends can affect hobbies, language, and future decisions.","zh":"選擇某些類型的朋友可以影響興趣、語言和未來決定。"},{"en":"The phrase focuses on friend type, not one named person.","zh":"這個短語重點是朋友類型，而不是某一個具名人物。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":8},{"front":"types of experience","meaning":"經歷類型","examples":[{"en":"People may be drawn to certain types of experience.","zh":"人們可能被某些經歷類型吸引。"},{"en":"Types of experience are different kinds of events, activities, or situations people go through.","zh":"types of experience 指人們經歷的不同事件、活動或情況。"},{"en":"Travel, teamwork, public speaking, and competition are different types of experience.","zh":"旅行、團隊合作、公開演說和競爭都是不同經歷類型。"},{"en":"The types of experience people choose can shape their confidence and skills.","zh":"人們選擇的經歷類型可以塑造他們的信心和技能。"},{"en":"The phrase is broad and can refer to daily life, education, work, or adventure.","zh":"這個短語很廣泛，可以指日常生活、教育、工作或冒險。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":8},{"front":"in this way","meaning":"以這種方式","examples":[{"en":"In this way, genes may shape the environment people choose.","zh":"以這種方式，基因可能塑造人們選擇的環境。"},{"en":"In this way means by the method or process just described.","zh":"in this way 指透過剛剛描述的方法或過程。"},{"en":"A teacher gives examples before rules; in this way, students guess meaning first.","zh":"老師先給例子再講規則；以這種方式，學生先猜意思。"},{"en":"A city adds bike lanes and safer crossings; in this way, more people may walk or cycle.","zh":"城市增設單車徑和更安全的過路設施；以這種方式，更多人可能步行或踩單車。"},{"en":"The phrase connects a previous explanation with its result.","zh":"這個短語把前文解釋與其結果連起來。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":8},{"front":"shape the environment","meaning":"塑造環境","examples":[{"en":"A person’s genes might shape the environment they act in.","zh":"一個人的基因可能塑造他行動其中的環境。"},{"en":"To shape the environment means to influence the surroundings, choices, or situations around someone.","zh":"shape the environment 指影響某人周圍的環境、選擇或情況。"},{"en":"A friendly child can shape the classroom environment by encouraging others to talk.","zh":"友善的孩子可以透過鼓勵別人說話來塑造課室環境。"},{"en":"A love of music may shape the environment a person chooses by leading them to bands and concerts.","zh":"對音樂的喜愛可能透過令一個人加入樂隊和去音樂會而塑造其選擇的環境。"},{"en":"The phrase shows that environment is not always passively received.","zh":"這個短語顯示環境不一定只是被動接受的。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":8},{"front":"as much as","meaning":"與……同樣多；不亞於","examples":[{"en":"Genes may shape the environment as much as the environment shapes genes.","zh":"基因塑造環境的程度可能不亞於環境塑造基因的程度。"},{"en":"As much as means to the same degree or nearly the same degree.","zh":"as much as 指達到相同或接近相同程度。"},{"en":"Listening matters as much as speaking in a good conversation.","zh":"在良好對話中，聆聽與說話同樣重要。"},{"en":"In learning English, review matters as much as learning new words.","zh":"在學英文時，複習的重要性不亞於學新詞。"},{"en":"The phrase is used to show equal or similar importance.","zh":"這個短語用來表示相等或相近的重要性。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":8},{"front":"in the past","meaning":"在過去","examples":[{"en":"In the past, twin research was controversial.","zh":"在過去，雙胞胎研究具爭議性。"},{"en":"In the past means during an earlier time, not now.","zh":"in the past 指在較早時期，而不是現在。"},{"en":"In the past, many students used paper dictionaries more than phone apps.","zh":"在過去，許多學生使用紙本字典多於手機應用程式。"},{"en":"A company may change its policy because old methods worked only in the past.","zh":"公司可能改變政策，因為舊方法只在過去有效。"},{"en":"The phrase helps compare earlier situations with the present.","zh":"這個短語幫助比較早期情況與現在。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":8},{"front":"be controversial","meaning":"具爭議性","examples":[{"en":"Twin research has sometimes been controversial.","zh":"雙胞胎研究有時具爭議性。"},{"en":"To be controversial means to cause disagreement, debate, or strong opinions.","zh":"be controversial 指引起分歧、辯論或強烈意見。"},{"en":"A new school rule can be controversial if students think it is unfair.","zh":"如果學生認為新校規不公平，它可能具爭議性。"},{"en":"Research becomes controversial when people worry about ethics or misuse of results.","zh":"當人們擔心倫理或研究結果被濫用，研究就會具爭議性。"},{"en":"The phrase does not mean something is wrong; it means people argue about it.","zh":"這個短語不表示某事錯誤；它表示人們對其有爭論。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":8},{"front":"Nazi doctor","meaning":"納粹醫生","examples":[{"en":"Josef Mengele was a Nazi doctor who conducted brutal experiments.","zh":"Josef Mengele 是一名進行殘酷實驗的納粹醫生。"},{"en":"A Nazi doctor was a doctor connected with Nazi Germany and its violent ideology.","zh":"Nazi doctor 指與納粹德國及其暴力意識形態有關的醫生。"},{"en":"History lessons may discuss a Nazi doctor to explain why medical ethics are necessary.","zh":"歷史課可能討論納粹醫生，以解釋為何醫學倫理是必要的。"},{"en":"The actions of Nazi doctors show how science can become dangerous without human rights.","zh":"納粹醫生的行為顯示，沒有保障人權的科學可以變得危險。"},{"en":"The phrase carries a strongly negative historical meaning.","zh":"這個短語帶有強烈負面的歷史含義。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":8},{"front":"extermination camp","meaning":"滅絕營","examples":[{"en":"Auschwitz was an extermination camp during the Second World War.","zh":"奧斯威辛是第二次世界大戰期間的一個滅絕營。"},{"en":"An extermination camp was a camp created for mass killing under the Nazi regime.","zh":"extermination camp 指納粹政權為大規模殺戮而建立的營地。"},{"en":"Students learn about extermination camps to understand the horror of the Holocaust.","zh":"學生學習滅絕營，是為了理解大屠殺的恐怖。"},{"en":"The existence of extermination camps shows why racism and dehumanisation must be resisted.","zh":"滅絕營的存在顯示為何必須抵抗種族主義和去人性化。"},{"en":"The phrase refers to an extremely serious historical crime, not an ordinary prison.","zh":"這個短語指極其嚴重的歷史罪行，而不是普通監獄。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":9},{"front":"during the Second World War","meaning":"在第二次世界大戰期間","examples":[{"en":"Mengele worked at Auschwitz during the Second World War.","zh":"Mengele 在第二次世界大戰期間於奧斯威辛工作。"},{"en":"During the Second World War means in the years when that global war was happening.","zh":"during the Second World War 指在那場全球戰爭發生的年代。"},{"en":"Many families were separated during the Second World War.","zh":"許多家庭在第二次世界大戰期間被分開。"},{"en":"Scientific and medical ethics were deeply affected by events during the Second World War.","zh":"科學和醫學倫理深受第二次世界大戰期間的事件影響。"},{"en":"The phrase gives historical timing for an event.","zh":"這個短語提供事件的歷史時間。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":9},{"front":"be fascinated by","meaning":"對……着迷","examples":[{"en":"Mengele was fascinated by twins.","zh":"Mengele 對雙胞胎着迷。"},{"en":"To be fascinated by something means to be extremely interested in it.","zh":"be fascinated by something 指對某事物極感興趣。"},{"en":"A child may be fascinated by insects and spend hours watching them.","zh":"孩子可能對昆蟲着迷，花幾小時觀察它們。"},{"en":"Scientists can be fascinated by a question, but research must still follow ethical rules.","zh":"科學家可以對某個問題着迷，但研究仍必須遵守倫理規則。"},{"en":"The phrase can describe strong interest, whether good or dangerous.","zh":"這個短語可以描述強烈興趣，不論其好壞或危險性。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":9},{"front":"seek them out","meaning":"找出；搜尋","examples":[{"en":"He sought twins out among arrivals at the camp.","zh":"他在抵達營地的人之中找出雙胞胎。"},{"en":"To seek them out means to actively look for particular people or things.","zh":"seek them out 指主動尋找特定的人或事物。"},{"en":"A teacher may seek out quiet students who need help but do not ask.","zh":"老師可能找出需要幫助但沒有開口的安靜學生。"},{"en":"Museums seek out old photographs before community memories disappear.","zh":"博物館在社區記憶消失前搜尋舊照片。"},{"en":"The phrase suggests deliberate searching, not accidental discovery.","zh":"這個短語暗示有意識地搜尋，而不是偶然發現。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":9},{"front":"arrivals at the camp","meaning":"抵達營地的人","examples":[{"en":"Mengele looked for twins among arrivals at the camp.","zh":"Mengele 在抵達營地的人之中尋找雙胞胎。"},{"en":"Arrivals at the camp are people who have just reached or been brought to a camp.","zh":"arrivals at the camp 指剛到達或被帶到營地的人。"},{"en":"Staff at a summer camp check the names of arrivals at the camp.","zh":"夏令營職員會核對抵達營地的人的姓名。"},{"en":"In a historical context, arrivals at the camp can refer to prisoners being brought in.","zh":"在歷史語境中，arrivals at the camp 可以指被帶入營地的囚犯。"},{"en":"The phrase focuses on people entering a place, not people leaving it.","zh":"這個短語重點是進入某地的人，而不是離開的人。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":9},{"front":"preserve them from","meaning":"使他們免於……","examples":[{"en":"He preserved some twins from the gas chambers for experiments.","zh":"他使一些雙胞胎免於毒氣室，以便進行實驗。"},{"en":"To preserve someone from something means to keep them from that danger or outcome.","zh":"preserve someone from something 指使某人免於某種危險或結果。"},{"en":"A helmet can preserve a cyclist from serious head injury.","zh":"頭盔可以使騎單車者免於嚴重頭部受傷。"},{"en":"Good records can preserve families from losing important legal proof.","zh":"良好記錄可以使家庭免於失去重要法律證明。"},{"en":"The phrase means protect from something, though the context may still be morally troubling.","zh":"這個短語表示保護某人免受某事，即使語境本身可能仍涉及道德問題。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":9},{"front":"gas chambers","meaning":"毒氣室","examples":[{"en":"Twins were sometimes preserved from the gas chambers for experiments.","zh":"雙胞胎有時被保留下來免於毒氣室，以便進行實驗。"},{"en":"Gas chambers were rooms used by the Nazis for mass killing during the Holocaust.","zh":"gas chambers 指納粹在大屠殺期間用於大規模殺戮的房間。"},{"en":"History teachers mention gas chambers when explaining the crimes of extermination camps.","zh":"歷史老師解釋滅絕營罪行時會提到毒氣室。"},{"en":"The use of gas chambers shows the extreme cruelty of Nazi persecution.","zh":"毒氣室的使用顯示納粹迫害的極端殘酷。"},{"en":"The phrase should be used with seriousness and historical care.","zh":"這個短語應以嚴肅和歷史謹慎態度使用。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":9},{"front":"a series of brutal experiments","meaning":"一連串殘酷實驗","examples":[{"en":"Mengele used twins in a series of brutal experiments.","zh":"Mengele 把雙胞胎用於一連串殘酷實驗。"},{"en":"A series of brutal experiments means several cruel and harmful tests done one after another.","zh":"a series of brutal experiments 指接連進行的多項殘酷且有害的測試。"},{"en":"Medical history discusses such experiments to teach why consent is essential.","zh":"醫學史討論這類實驗，是為了教導為何同意是必要的。"},{"en":"A series of brutal experiments can permanently damage people and destroy trust in science.","zh":"一連串殘酷實驗可以永久傷害人並破壞人們對科學的信任。"},{"en":"The phrase strongly condemns research that ignores human rights.","zh":"這個短語強烈譴責無視人權的研究。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":9},{"front":"work on the heredity of intelligence","meaning":"研究智力遺傳","examples":[{"en":"Cyril Burt worked on the heredity of intelligence.","zh":"Cyril Burt 研究智力遺傳。"},{"en":"To work on the heredity of intelligence means to study how far intelligence is influenced by genes.","zh":"work on the heredity of intelligence 指研究智力在多大程度上受基因影響。"},{"en":"Psychologists may work on the heredity of intelligence by comparing relatives and twins.","zh":"心理學家可能透過比較親屬和雙胞胎來研究智力遺傳。"},{"en":"Such work can be controversial if data are weak or social effects are ignored.","zh":"如果數據薄弱或忽視社會影響，這類研究可能具爭議性。"},{"en":"The phrase describes a research topic, not a simple conclusion.","zh":"這個短語描述研究主題，而不是簡單結論。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":9},{"front":"taint twin research","meaning":"玷污雙胞胎研究","examples":[{"en":"Cyril Burt’s questionable data tainted twin research.","zh":"Cyril Burt 有問題的數據玷污了雙胞胎研究。"},{"en":"To taint twin research means to damage its reputation or trustworthiness.","zh":"taint twin research 指損害雙胞胎研究的聲譽或可信度。"},{"en":"One dishonest report can taint a whole project if people lose confidence in the data.","zh":"如果人們對數據失去信心，一份不誠實報告可以玷污整個項目。"},{"en":"Faked results taint research because later scientists cannot trust the conclusions.","zh":"造假結果會玷污研究，因為後來的科學家不能信任結論。"},{"en":"The phrase suggests lasting damage to reputation.","zh":"這個短語暗示對聲譽造成持久傷害。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":9},{"front":"in retrospect","meaning":"回想起來","examples":[{"en":"In retrospect, some of Burt’s results appeared too good to be true.","zh":"回想起來，Burt 的一些結果看起來好得不太可信。"},{"en":"In retrospect means looking back after time has passed.","zh":"in retrospect 指經過一段時間後回頭看。"},{"en":"In retrospect, the warning signs before the accident were clear.","zh":"回想起來，意外前的警告信號很清楚。"},{"en":"A student may realise in retrospect that leaving revision too late was a mistake.","zh":"學生可能回想起來才意識到太遲開始溫習是錯誤。"},{"en":"The phrase shows later understanding that was not obvious at the time.","zh":"這個短語表示當時不明顯、後來才有的理解。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":9},{"front":"rather too good","meaning":"好得不太可信","examples":[{"en":"Some of Burt’s results appeared rather too good.","zh":"Burt 的一些結果看起來好得不太可信。"},{"en":"Rather too good means surprisingly perfect or impressive in a way that may be suspicious.","zh":"rather too good 指好得令人驚訝，甚至可能可疑。"},{"en":"If every survey answer is positive, the results may look rather too good.","zh":"如果每份問卷答案都是正面，結果可能看起來好得不太可信。"},{"en":"A deal that sounds rather too good may hide extra costs.","zh":"聽起來好得不太可信的優惠可能隱藏額外費用。"},{"en":"The phrase suggests cautious doubt, not simple praise.","zh":"這個短語暗示謹慎懷疑，而不是單純讚賞。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":10},{"front":"identical twins reared apart","meaning":"分開撫養的同卵雙胞胎","examples":[{"en":"Burt studied identical twins who had been reared apart.","zh":"Burt 研究了分開撫養的同卵雙胞胎。"},{"en":"Identical twins reared apart are genetically identical twins raised in different homes or environments.","zh":"identical twins reared apart 指在不同家庭或環境中長大的同卵雙胞胎。"},{"en":"Researchers value identical twins reared apart because their shared genes can be compared with different life experiences.","zh":"研究人員重視分開撫養的同卵雙胞胎，因為可以把共同基因與不同生活經歷作比較。"},{"en":"If identical twins reared apart still show similar traits, genes may play a role.","zh":"如果分開撫養的同卵雙胞胎仍表現出相似特質，基因可能有作用。"},{"en":"The phrase is important in nature-and-nurture research.","zh":"這個短語在先天與後天研究中很重要。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":10},{"front":"be reared apart","meaning":"被分開撫養","examples":[{"en":"Some identical twins were reared apart in different environments.","zh":"一些同卵雙胞胎在不同環境中被分開撫養。"},{"en":"To be reared apart means to be raised separately, often in different families or places.","zh":"be reared apart 指被分開養大，通常在不同家庭或地方。"},{"en":"Two siblings reared apart may grow up with different accents and habits.","zh":"被分開撫養的兄弟姊妹可能長大後有不同口音和習慣。"},{"en":"If twins are reared apart, researchers can compare shared genes with different environments.","zh":"如果雙胞胎被分開撫養，研究人員可以比較共同基因與不同環境。"},{"en":"The phrase is formal; in daily speech, raised apart is more common.","zh":"這個短語較正式；日常英語中 raised apart 更常見。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":10},{"front":"probably faked","meaning":"很可能造假","examples":[{"en":"Some of Burt’s data were probably faked.","zh":"Burt 的一些數據很可能造假。"},{"en":"Probably faked means likely invented, altered, or dishonest, though not stated as completely certain.","zh":"probably faked 指很可能被編造、修改或不誠實處理，但不是說完全確定。"},{"en":"A photo may be probably faked if shadows and reflections do not match.","zh":"如果照片中的陰影和倒影不相符，它可能很可能造假。"},{"en":"If data are probably faked, researchers should not build conclusions on them.","zh":"如果數據很可能造假，研究人員不應以此建立結論。"},{"en":"The phrase expresses strong suspicion without claiming absolute proof.","zh":"這個短語表達強烈懷疑，但不聲稱有絕對證明。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":10},{"front":"in any case","meaning":"無論如何","examples":[{"en":"In any case, the social sciences were suspicious of genetic explanations.","zh":"無論如何，社會科學對遺傳解釋抱有懷疑。"},{"en":"In any case means whatever the exact situation is, the following point is still true.","zh":"in any case 指無論確切情況如何，接下來的一點仍然成立。"},{"en":"The train may be late; in any case, we should leave early.","zh":"火車可能會遲到；無論如何，我們應該早點出發。"},{"en":"The price may change, but in any case, we need a clear budget.","zh":"價格可能改變，但無論如何，我們需要清晰預算。"},{"en":"The phrase helps move to a conclusion despite uncertainty or extra details.","zh":"這個短語幫助在有不確定性或額外細節下轉向結論。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":10},{"front":"prevailing ideology","meaning":"主流意識形態","examples":[{"en":"The prevailing ideology in the social sciences was Marxist.","zh":"社會科學中的主流意識形態是馬克思主義。"},{"en":"Prevailing ideology means the set of beliefs that is most accepted or powerful at a particular time.","zh":"prevailing ideology 指在某一時期最被接受或最有影響力的一套信念。"},{"en":"In one school, the prevailing ideology may favour strict exams over creative projects.","zh":"在一所學校中，主流意識形態可能重視嚴格考試多於創意項目。"},{"en":"A prevailing ideology can shape which questions researchers ask and which answers they trust.","zh":"主流意識形態可以塑造研究人員提出哪些問題和相信哪些答案。"},{"en":"The phrase is useful for explaining intellectual or political climate.","zh":"這個短語適合解釋思想或政治氣候。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":10},{"front":"social sciences","meaning":"社會科學","examples":[{"en":"The social sciences after the war were influenced by Marxist ideas.","zh":"戰後的社會科學受馬克思主義思想影響。"},{"en":"The social sciences study human society, behaviour, institutions, and relationships.","zh":"social sciences 研究人類社會、行為、制度和關係。"},{"en":"Sociology, economics, political science, and psychology can belong to the social sciences.","zh":"社會學、經濟學、政治學和心理學可以屬於社會科學。"},{"en":"The social sciences help explain problems such as inequality, education, and family change.","zh":"社會科學幫助解釋不平等、教育和家庭變化等問題。"},{"en":"The phrase differs from natural sciences, which focus more on the physical and biological world.","zh":"這個短語不同於自然科學，後者更集中於物理和生物世界。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":10},{"front":"underlying genetic causes","meaning":"潛在遺傳成因","examples":[{"en":"Some scholars disliked suggestions of underlying genetic causes.","zh":"一些學者不喜歡有潛在遺傳成因的說法。"},{"en":"Underlying genetic causes are deeper biological reasons related to genes.","zh":"underlying genetic causes 指與基因有關的更深層生物原因。"},{"en":"Doctors may look for underlying genetic causes when many relatives have the same disease.","zh":"當許多親屬患有同一疾病，醫生可能尋找潛在遺傳成因。"},{"en":"Ignoring underlying genetic causes can make treatment or prevention less effective.","zh":"忽視潛在遺傳成因可能令治療或預防較無效。"},{"en":"The phrase refers to hidden biological causes, not obvious surface symptoms.","zh":"這個短語指隱藏的生物原因，而不是明顯表面症狀。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":10},{"front":"be viewed with suspicion","meaning":"被懷疑看待","examples":[{"en":"Twin studies were viewed with suspicion after the war.","zh":"戰後，雙胞胎研究被懷疑看待。"},{"en":"To be viewed with suspicion means to be regarded as possibly wrong, dishonest, or dangerous.","zh":"be viewed with suspicion 指被認為可能錯誤、不誠實或危險。"},{"en":"A company with unclear accounts may be viewed with suspicion by investors.","zh":"帳目不清的公司可能被投資者懷疑看待。"},{"en":"Research may be viewed with suspicion if earlier studies used fake data.","zh":"如果早期研究使用造假數據，後來的研究可能被懷疑看待。"},{"en":"The phrase describes distrust, not simple disagreement.","zh":"這個短語描述不信任，而不是單純不同意。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":10},{"front":"ideological pendulum","meaning":"意識形態鐘擺","examples":[{"en":"The ideological pendulum has swung back in favour of genetic research.","zh":"意識形態鐘擺已擺回支持遺傳研究的一方。"},{"en":"An ideological pendulum is a metaphor for beliefs moving from one side to another over time.","zh":"ideological pendulum 是比喻信念隨時間從一邊移向另一邊。"},{"en":"Education policy can follow an ideological pendulum between strict exams and creative learning.","zh":"教育政策可以在嚴格考試與創意學習之間跟隨意識形態鐘擺擺動。"},{"en":"When the ideological pendulum swings, ideas once unpopular may become accepted again.","zh":"當意識形態鐘擺擺動，曾不受歡迎的想法可能再次被接受。"},{"en":"The phrase suggests changing intellectual fashion.","zh":"這個短語暗示知識潮流的變化。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":10},{"front":"swing back","meaning":"擺回來","examples":[{"en":"The ideological pendulum has swung back.","zh":"意識形態鐘擺已經擺回來。"},{"en":"To swing back means to return toward a previous position or opinion.","zh":"swing back 指回到較早的位置或意見。"},{"en":"Public opinion may swing back after people see the costs of a new policy.","zh":"當人們看見新政策的代價後，民意可能擺回來。"},{"en":"Fashion often swings back when old styles become popular again.","zh":"當舊風格再次流行，時尚常會擺回來。"},{"en":"The phrase suggests movement away and then return.","zh":"這個短語暗示先離開、後回歸的移動。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":10},{"front":"the Human Genome Project","meaning":"人類基因組計劃","examples":[{"en":"The Human Genome Project helped change views of genes.","zh":"人類基因組計劃幫助改變人們對基因的看法。"},{"en":"The Human Genome Project was a major scientific effort to map and understand human DNA.","zh":"Human Genome Project 是一項旨在繪製和理解人類 DNA 的重大科學工作。"},{"en":"Biology students may study the Human Genome Project to understand modern genetics.","zh":"生物學生可能學習人類基因組計劃，以理解現代遺傳學。"},{"en":"The Human Genome Project made genes seem more concrete and measurable.","zh":"人類基因組計劃令基因看起來更具體和可量度。"},{"en":"The phrase names an important project in genetic science.","zh":"這個短語指遺傳科學中的重要項目。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":11},{"front":"its aftermath","meaning":"其後續影響","examples":[{"en":"The Human Genome Project and its aftermath changed genetic research.","zh":"人類基因組計劃及其後續影響改變了遺傳研究。"},{"en":"Its aftermath means the period and effects that followed an event.","zh":"its aftermath 指某事件之後的時期和影響。"},{"en":"A storm and its aftermath can affect transport for several days.","zh":"暴風雨及其後續影響可以影響交通數天。"},{"en":"A school conflict and its aftermath may lead to new rules and counselling support.","zh":"學校衝突及其後續影響可能帶來新規則和輔導支援。"},{"en":"The phrase focuses on consequences after the main event.","zh":"這個短語重點是主要事件之後的後果。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":11},{"front":"abstract concepts","meaning":"抽象概念","examples":[{"en":"Genes were once treated as abstract concepts.","zh":"基因曾被視為抽象概念。"},{"en":"Abstract concepts are ideas that are not physical objects and cannot be touched directly.","zh":"abstract concepts 指不是實體物件、不能直接觸摸的想法。"},{"en":"Freedom, fairness, and identity are abstract concepts.","zh":"自由、公平和身份都是抽象概念。"},{"en":"Students understand abstract concepts better when teachers use concrete examples.","zh":"當老師使用具體例子，學生會更容易理解抽象概念。"},{"en":"The phrase contrasts ideas with visible, material things.","zh":"這個短語把想法與可見的物質事物作對比。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":11},{"front":"real pieces of DNA","meaning":"真實的 DNA 片段","examples":[{"en":"Genes are now understood as real pieces of DNA.","zh":"基因現在被理解為真實的 DNA 片段。"},{"en":"Real pieces of DNA means actual physical sections of genetic material.","zh":"real pieces of DNA 指遺傳物質中的實際物理片段。"},{"en":"A gene is not just an idea; it is a real piece of DNA that can be studied in a lab.","zh":"基因不只是想法；它是在實驗室中可研究的真實 DNA 片段。"},{"en":"Seeing genes as real pieces of DNA helps scientists connect heredity with biology.","zh":"把基因視為真實的 DNA 片段，幫助科學家把遺傳與生物學連起來。"},{"en":"The phrase makes a scientific idea concrete.","zh":"這個短語令科學概念變得具體。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":11},{"front":"sensitive areas","meaning":"敏感範疇","examples":[{"en":"Intelligence remains one of the sensitive areas in genetics.","zh":"智力仍然是遺傳學中的敏感範疇之一。"},{"en":"Sensitive areas are topics that may cause strong emotions, disagreement, or social concern.","zh":"sensitive areas 指可能引起強烈情緒、分歧或社會關注的議題。"},{"en":"Salary is a sensitive area in many workplaces because people compare fairness.","zh":"薪酬在許多工作場所是敏感範疇，因為人們會比較公平性。"},{"en":"Research on intelligence can be a sensitive area if results are misused socially or politically.","zh":"如果結果被社會或政治上濫用，智力研究可以成為敏感範疇。"},{"en":"The phrase warns writers and speakers to handle a topic carefully.","zh":"這個短語提醒寫作者和說話者要謹慎處理議題。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":11},{"front":"be acknowledged by","meaning":"得到……承認","examples":[{"en":"The role of genes is acknowledged by almost everyone.","zh":"基因的作用幾乎得到所有人承認。"},{"en":"To be acknowledged by someone means to be accepted, recognised, or admitted by them.","zh":"be acknowledged by someone 指得到某人接受、認可或承認。"},{"en":"A student’s effort may be acknowledged by the teacher in front of the class.","zh":"學生的努力可能在全班面前得到老師承認。"},{"en":"Climate risks are acknowledged by many businesses when they plan for the future.","zh":"許多企業在規劃未來時承認氣候風險。"},{"en":"The phrase can refer to public recognition or acceptance of a fact.","zh":"這個短語可以指公開肯定或承認某事實。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":11},{"front":"all but a few","meaning":"除少數……外幾乎所有人","examples":[{"en":"The role of genes is acknowledged by all but a few die-hards.","zh":"除少數頑固派外，幾乎所有人都承認基因的作用。"},{"en":"All but a few means almost everyone, except a small number.","zh":"all but a few 指除少數人外幾乎全部。"},{"en":"All but a few students finished the assignment on time.","zh":"除少數學生外，幾乎所有學生都準時完成作業。"},{"en":"If all but a few residents support the plan, opposition is small.","zh":"如果除少數居民外幾乎所有居民都支持計劃，反對聲音就很小。"},{"en":"The phrase highlights a strong majority while allowing minor exceptions.","zh":"這個短語強調大多數，同時容許少量例外。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":11},{"front":"die-hards","meaning":"頑固派","examples":[{"en":"A few die-hards still reject the role of genes.","zh":"少數頑固派仍然拒絕基因的作用。"},{"en":"Die-hards are people who stubbornly hold an old belief even when many others change their minds.","zh":"die-hards 指即使很多人改變想法，仍頑固堅持舊信念的人。"},{"en":"A few die-hards may still prefer handwritten letters to email.","zh":"少數頑固派可能仍偏好手寫信多於電郵。"},{"en":"Die-hards can slow change if they refuse to consider new evidence.","zh":"如果頑固派拒絕考慮新證據，他們可能拖慢改變。"},{"en":"The word often has a slightly critical tone.","zh":"這個詞通常帶有輕微批評語氣。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":11},{"front":"concern how","meaning":"關乎……如何","examples":[{"en":"The interesting questions now concern how nature and nurture interact.","zh":"現在有趣的問題關乎先天與後天如何互動。"},{"en":"To concern how something happens means to be about the way or process by which it happens.","zh":"concern how something happens 指關於某事發生的方式或過程。"},{"en":"The meeting will concern how students can use the library more effectively.","zh":"會議將關乎學生如何更有效使用圖書館。"},{"en":"Modern health research often concerns how lifestyle and biology affect each other.","zh":"現代健康研究常關乎生活方式和生物因素如何互相影響。"},{"en":"The phrase points to process, not just yes-or-no answers.","zh":"這個短語指向過程，而不只是是非答案。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":11},{"front":"interact to produce","meaning":"互相作用以產生","examples":[{"en":"Nature and nurture interact to produce particular biological outcomes.","zh":"先天與後天互相作用，以產生特定生物結果。"},{"en":"To interact to produce something means two or more factors work together to create a result.","zh":"interact to produce something 指兩個或更多因素共同作用以創造結果。"},{"en":"Sleep and study habits interact to produce better memory.","zh":"睡眠和學習習慣互相作用，以產生更好的記憶。"},{"en":"Diet, exercise, and genes can interact to produce differences in health.","zh":"飲食、運動和基因可以互相作用，以產生健康差異。"},{"en":"The phrase shows combined influence rather than one single cause.","zh":"這個短語顯示共同影響，而不是單一原因。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":11},{"front":"particular bits of biology","meaning":"特定生物特徵","examples":[{"en":"Researchers study how nature and nurture produce particular bits of biology.","zh":"研究人員研究先天與後天如何產生特定生物特徵。"},{"en":"Particular bits of biology means specific biological features, processes, or outcomes.","zh":"particular bits of biology 指具體的生物特徵、過程或結果。"},{"en":"Eye colour, taste sensitivity, and disease risk can be particular bits of biology.","zh":"眼睛顏色、味覺敏感度和患病風險都可以是特定生物特徵。"},{"en":"Studying particular bits of biology helps scientists avoid vague claims about the whole person.","zh":"研究特定生物特徵有助科學家避免對整個人作含糊聲稱。"},{"en":"The phrase is informal but points to specific biological details.","zh":"這個短語較口語，但指向具體生物細節。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":11},{"front":"rather than","meaning":"而不是","examples":[{"en":"The question is how genes and environment interact rather than which is more important.","zh":"問題是基因和環境如何互動，而不是哪一方更重要。"},{"en":"Rather than means instead of, and it clearly contrasts two ideas.","zh":"rather than 指「而不是」，並清楚對比兩個想法。"},{"en":"Students should focus on understanding rather than memorising every sentence.","zh":"學生應專注理解，而不是背誦每一句。"},{"en":"A good policy solves the cause rather than only hiding the symptoms.","zh":"好政策解決原因，而不是只掩蓋症狀。"},{"en":"The phrase helps separate the better focus from the less useful one.","zh":"這個短語幫助區分較好的焦點與較不有用的焦點。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":12},{"front":"be back in fashion","meaning":"重新流行","examples":[{"en":"Twin studies are back in fashion.","zh":"雙胞胎研究重新流行。"},{"en":"To be back in fashion means to become popular or respected again after a period of being less popular.","zh":"be back in fashion 指在一段較不受歡迎時期後再次流行或受重視。"},{"en":"Old film cameras are back in fashion among some young photographers.","zh":"舊菲林相機在一些年輕攝影師之間重新流行。"},{"en":"A research method can be back in fashion when new technology makes it more useful.","zh":"當新科技令某研究方法更有用，它可以重新流行。"},{"en":"The phrase suggests a return of interest, not something completely new.","zh":"這個短語暗示興趣回歸，而不是完全新事物。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":12},{"front":"enthusiastic participants","meaning":"熱心參加者","examples":[{"en":"Many twins are enthusiastic participants in research.","zh":"許多雙胞胎是研究的熱心參加者。"},{"en":"Enthusiastic participants are people who join an activity willingly and with interest.","zh":"enthusiastic participants 指願意並有興趣參與活動的人。"},{"en":"Enthusiastic participants in a school project ask questions and complete tasks early.","zh":"學校項目的熱心參加者會提問並提早完成任務。"},{"en":"Research is easier when volunteers are enthusiastic participants rather than reluctant subjects.","zh":"當志願者是熱心參加者而不是勉強的受試者，研究會較容易進行。"},{"en":"The phrase suggests positive energy and active involvement.","zh":"這個短語暗示正面能量和主動參與。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":12},{"front":"Twinsburg festival","meaning":"Twinsburg 雙胞胎節","examples":[{"en":"Research at the Twinsburg festival began with a single stand.","zh":"Twinsburg 雙胞胎節上的研究由一個攤位開始。"},{"en":"The Twinsburg festival is an event where many twins gather, making it useful for twin research.","zh":"Twinsburg festival 是許多雙胞胎聚集的活動，因此對雙胞胎研究有用。"},{"en":"Scientists may visit the Twinsburg festival because they can meet many twin pairs in one place.","zh":"科學家可能到 Twinsburg 雙胞胎節，因為他們可以在一處見到許多對雙胞胎。"},{"en":"A festival like Twinsburg can help research grow by bringing volunteers together.","zh":"像 Twinsburg 這樣的節日可以透過聚集志願者來幫助研究發展。"},{"en":"The phrase names a specific event connected with twins.","zh":"這個短語指一個與雙胞胎有關的特定活動。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":12},{"front":"begin in a small way","meaning":"以小規模開始","examples":[{"en":"Research at the festival began in a small way.","zh":"節日上的研究以小規模開始。"},{"en":"To begin in a small way means to start with limited size, money, people, or equipment.","zh":"begin in a small way 指以有限規模、資金、人手或設備開始。"},{"en":"A business may begin in a small way with one table at a weekend market.","zh":"一盤生意可能以週末市集的一張桌子小規模開始。"},{"en":"Projects that begin in a small way can grow when people see their value.","zh":"以小規模開始的項目在別人看見其價值後可以成長。"},{"en":"The phrase suggests a modest beginning, not a failed beginning.","zh":"這個短語暗示謙遜開端，而不是失敗開端。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":12},{"front":"a single stand","meaning":"一個攤位","examples":[{"en":"The research began with a single stand in 1979.","zh":"這項研究在1979年由一個攤位開始。"},{"en":"A single stand is one small booth or stall used for display, sales, or information.","zh":"a single stand 指一個用於展示、售賣或提供資訊的小攤位。"},{"en":"A charity may start with a single stand at a community fair.","zh":"慈善機構可能由社區嘉年華的一個攤位開始。"},{"en":"A single stand can attract volunteers if the message is clear and friendly.","zh":"如果訊息清晰友善，一個攤位也可以吸引志願者。"},{"en":"The phrase emphasises a very small physical starting point.","zh":"這個短語強調非常小的實體起點。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":12},{"front":"gradually","meaning":"漸漸地","examples":[{"en":"Gradually, more scientists began turning up.","zh":"漸漸地，更多科學家開始到場。"},{"en":"Gradually means slowly over time, not suddenly.","zh":"gradually 指隨時間慢慢地，而不是突然地。"},{"en":"A student’s pronunciation improves gradually with daily practice.","zh":"學生的發音會透過每日練習漸漸地改善。"},{"en":"If prices rise gradually, people may notice the change only after several months.","zh":"如果價格漸漸地上升，人們可能幾個月後才注意到變化。"},{"en":"The word is useful for describing slow development or change.","zh":"這個詞適合描述緩慢發展或改變。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":12},{"front":"news spread","meaning":"消息傳開","examples":[{"en":"News spread and more researchers came to the festival.","zh":"消息傳開後，更多研究人員來到節日。"},{"en":"News spread means information became known by more and more people.","zh":"news spread 指資訊被越來越多人知道。"},{"en":"News spread quickly when the school announced a surprise holiday.","zh":"學校宣布驚喜假期時，消息很快傳開。"},{"en":"If good news spreads, more customers may visit a new shop.","zh":"如果好消息傳開，更多顧客可能到訪新店。"},{"en":"The phrase can describe information travelling through speech, media, or social networks.","zh":"這個短語可以描述資訊透過說話、媒體或社交網絡傳播。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":12},{"front":"turn up","meaning":"出現；到場","examples":[{"en":"More scientists began to turn up at the festival.","zh":"更多科學家開始在節日到場。"},{"en":"To turn up means to arrive or appear somewhere.","zh":"turn up 指到達或出現在某地。"},{"en":"A student may turn up late if the bus is delayed.","zh":"如果巴士延誤，學生可能遲到。"},{"en":"More volunteers turned up after the organiser shared the event online.","zh":"主辦者在網上分享活動後，更多義工到場。"},{"en":"The phrase is informal and common in everyday speech.","zh":"這個短語較口語，常見於日常英語。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":12},{"front":"half a dozen groups","meaning":"六組左右","examples":[{"en":"Half a dozen groups of researchers worked in the tent.","zh":"六組左右的研究人員在帳篷中工作。"},{"en":"Half a dozen groups means about six groups.","zh":"half a dozen groups 指大約六組。"},{"en":"Half a dozen groups of students presented their projects in the hall.","zh":"六組左右的學生在禮堂展示他們的項目。"},{"en":"If half a dozen groups join a study, researchers can collect more varied data.","zh":"如果六組左右的人參與研究，研究人員可以收集更多樣化數據。"},{"en":"The phrase is a natural way to say six without sounding overly exact.","zh":"這個短語是自然地說「六」的方法，不會聽起來過於精確。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":12},{"front":"be lodged in","meaning":"被安置在","examples":[{"en":"Researchers were lodged in a specially pitched research tent.","zh":"研究人員被安置在特別搭建的研究帳篷中。"},{"en":"To be lodged in a place means to be placed, housed, or accommodated there.","zh":"be lodged in a place 指被安置、住宿或容納在某地。"},{"en":"Visiting teachers were lodged in a school dormitory during the conference.","zh":"來訪教師在會議期間被安置在學校宿舍。"},{"en":"If many guests arrive, they may be lodged in nearby hotels.","zh":"如果很多客人到達，他們可能被安置在附近酒店。"},{"en":"The phrase is more formal than saying stayed in.","zh":"這個短語比 stayed in 更正式。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":12},{"front":"specially pitched research tent","meaning":"特別搭建的研究帳篷","examples":[{"en":"Researchers worked in a specially pitched research tent.","zh":"研究人員在特別搭建的研究帳篷中工作。"},{"en":"A specially pitched research tent is a tent put up for the specific purpose of research.","zh":"specially pitched research tent 指為研究這一特定目的而搭建的帳篷。"},{"en":"At a health fair, doctors may use a specially pitched tent to test blood pressure.","zh":"在健康展覽中，醫生可能使用特別搭建的帳篷測量血壓。"},{"en":"A research tent allows scientists to collect data near the event or field site.","zh":"研究帳篷讓科學家能在活動或實地地點附近收集數據。"},{"en":"The phrase combines temporary location with planned scientific work.","zh":"這個短語結合臨時地點和有計劃的科學工作。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":13},{"front":"watch over","meaning":"看管；監察","examples":[{"en":"Paul Breslin watched over several tables of volunteers.","zh":"Paul Breslin 監察幾桌志願者。"},{"en":"To watch over people or things means to supervise, guard, or keep an eye on them.","zh":"watch over people or things 指監督、守護或留意他們。"},{"en":"A teacher watches over students during a science experiment.","zh":"老師在科學實驗期間看管學生。"},{"en":"Nurses watch over patients after surgery to notice problems early.","zh":"護士在手術後監察病人，以及早發現問題。"},{"en":"The phrase suggests care and attention, not just looking once.","zh":"這個短語暗示照顧和注意，而不是只看一次。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":13},{"front":"sip clear liquids","meaning":"啜飲透明液體","examples":[{"en":"Twins sat sipping clear liquids from cups.","zh":"雙胞胎坐着，從杯中啜飲透明液體。"},{"en":"To sip clear liquids means to drink transparent liquids slowly in small amounts.","zh":"sip clear liquids 指慢慢小口喝透明液體。"},{"en":"A patient may sip clear liquids after an operation before eating solid food.","zh":"病人在手術後可能先啜飲透明液體，再吃固體食物。"},{"en":"In a taste test, volunteers sip clear liquids so researchers can record their reactions.","zh":"在味覺測試中，志願者啜飲透明液體，好讓研究人員記錄反應。"},{"en":"The phrase suggests careful drinking, not drinking quickly.","zh":"這個短語暗示小心飲用，而不是快速喝下。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":13},{"front":"make notes","meaning":"做筆記","examples":[{"en":"The twins made notes while tasting the liquids.","zh":"雙胞胎在品嚐液體時做筆記。"},{"en":"To make notes means to write down information, observations, or ideas.","zh":"make notes 指寫下資訊、觀察或想法。"},{"en":"Students make notes during lessons so they can review later.","zh":"學生在課堂中做筆記，以便之後溫習。"},{"en":"Researchers make notes immediately because small details can be forgotten quickly.","zh":"研究人員會立即做筆記，因為小細節可能很快被忘記。"},{"en":"The phrase refers to recording useful points, not writing a full essay.","zh":"這個短語指記錄有用要點，而不是寫完整文章。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":13},{"front":"colleagues","meaning":"同事","examples":[{"en":"Dr Breslin and his colleagues studied human perception.","zh":"Breslin 博士和他的同事研究人類感知。"},{"en":"Colleagues are people who work with you in the same organisation or field.","zh":"colleagues 指在同一機構或領域與你一起工作的人。"},{"en":"A teacher may discuss lesson plans with colleagues after school.","zh":"老師可能放學後與同事討論教案。"},{"en":"Good colleagues share information and help solve workplace problems.","zh":"好同事會分享資訊並幫助解決工作問題。"},{"en":"The word is more professional than friends, though colleagues can also become friends.","zh":"這個詞比 friends 更專業，雖然同事也可以成為朋友。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":13},{"front":"find out how","meaning":"找出……如何","examples":[{"en":"The researchers wanted to find out how genes influence perception.","zh":"研究人員想找出基因如何影響感知。"},{"en":"To find out how something happens means to discover the process or method behind it.","zh":"find out how something happens 指發現某事背後的過程或方法。"},{"en":"A student may do an experiment to find out how sunlight affects plant growth.","zh":"學生可能做實驗，找出陽光如何影響植物生長。"},{"en":"Doctors ask questions to find out how a symptom began.","zh":"醫生會提問，以找出症狀如何開始。"},{"en":"The phrase is common when the answer is not yet known.","zh":"當答案尚未知時，這個短語很常用。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":13},{"front":"human perception","meaning":"人類感知","examples":[{"en":"The study examined how genes influence human perception.","zh":"這項研究檢視基因如何影響人類感知。"},{"en":"Human perception is the way people receive and interpret information through the senses.","zh":"human perception 指人們透過感官接收和理解資訊的方式。"},{"en":"Human perception affects how we judge taste, sound, colour, pain, and temperature.","zh":"人類感知影響我們如何判斷味道、聲音、顏色、疼痛和溫度。"},{"en":"Human perception can differ because of genes, experience, attention, and culture.","zh":"人類感知可能因基因、經驗、注意力和文化而不同。"},{"en":"The phrase focuses on how people sense and understand the world.","zh":"這個短語重點是人們如何感受和理解世界。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":13},{"front":"the senses of smell and taste","meaning":"嗅覺和味覺","examples":[{"en":"The study focused on the senses of smell and taste.","zh":"這項研究集中於嗅覺和味覺。"},{"en":"The senses of smell and taste are the abilities to detect odours and flavours.","zh":"the senses of smell and taste 指偵測氣味和味道的能力。"},{"en":"A cold can weaken the senses of smell and taste, making food seem bland.","zh":"感冒可以削弱嗅覺和味覺，令食物顯得淡而無味。"},{"en":"Chefs rely on the senses of smell and taste when adjusting a recipe.","zh":"廚師調整食譜時依靠嗅覺和味覺。"},{"en":"The phrase names two closely connected senses.","zh":"這個短語指出兩種密切相關的感官。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":13},{"front":"stimulation of the skin","meaning":"皮膚刺激","examples":[{"en":"Warmth, cold, pain and itch result from stimulation of the skin.","zh":"溫暖、寒冷、疼痛和痕癢都來自皮膚刺激。"},{"en":"Stimulation of the skin means something touches or affects the skin and causes a sensation.","zh":"stimulation of the skin 指某物接觸或影響皮膚並造成感覺。"},{"en":"A mosquito bite causes stimulation of the skin that may feel itchy.","zh":"蚊叮會造成皮膚刺激，可能令人覺得痕癢。"},{"en":"Heat, pressure, and cold can all create different kinds of skin stimulation.","zh":"熱力、壓力和寒冷都可以造成不同種類的皮膚刺激。"},{"en":"The phrase is scientific and describes how the body receives outside signals.","zh":"這個短語較科學，描述身體如何接收外界訊號。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":13},{"front":"be influenced by both","meaning":"同時受……影響","examples":[{"en":"Perception is probably influenced by both genes and experience.","zh":"感知很可能同時受基因和經驗影響。"},{"en":"To be influenced by both means to be affected by two factors together.","zh":"be influenced by both 指同時受兩個因素影響。"},{"en":"A child’s accent is influenced by both family speech and school friends.","zh":"孩子的口音同時受家庭說話方式和學校朋友影響。"},{"en":"Health can be influenced by both inherited risk and daily habits.","zh":"健康可以同時受遺傳風險和日常習慣影響。"},{"en":"The phrase avoids choosing only one cause.","zh":"這個短語避免只選一個原因。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":13},{"front":"even before birth","meaning":"甚至在出生前","examples":[{"en":"Even before birth, people are exposed to certain flavours.","zh":"甚至在出生前，人們已接觸到某些味道。"},{"en":"Even before birth means before a baby is born.","zh":"even before birth 指嬰兒出生之前。"},{"en":"Babies may hear voices and sounds even before birth.","zh":"嬰兒甚至在出生前可能已聽到聲音和語音。"},{"en":"Some early influences can begin even before birth through the mother’s body.","zh":"一些早期影響可以透過母體甚至在出生前開始。"},{"en":"The phrase stresses that development starts very early.","zh":"這個短語強調發展很早就開始。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":13},{"front":"be exposed to","meaning":"接觸到","examples":[{"en":"People are exposed to flavours before birth.","zh":"人們在出生前已接觸到味道。"},{"en":"To be exposed to something means to come into contact with it or experience it.","zh":"be exposed to something 指接觸或經歷某事物。"},{"en":"Children exposed to many books may develop stronger reading habits.","zh":"接觸很多書籍的孩子可能培養更強閱讀習慣。"},{"en":"Workers exposed to loud noise need protection for their hearing.","zh":"接觸巨大噪音的工人需要保護聽力。"},{"en":"The phrase can describe helpful, neutral, or harmful contact.","zh":"這個短語可以描述有益、中性或有害的接觸。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":14},{"front":"pass intact into","meaning":"完整地進入","examples":[{"en":"Some flavours pass intact into the bloodstream.","zh":"一些味道完整地進入血液循環。"},{"en":"To pass intact into something means to enter it without being broken down or changed much.","zh":"pass intact into something 指在沒有被大幅分解或改變下進入某處。"},{"en":"Some small molecules may pass intact into the body after digestion.","zh":"一些小分子可能在消化後完整地進入身體。"},{"en":"If a substance passes intact into the bloodstream, it may affect other parts of the body.","zh":"如果某物質完整地進入血液循環，它可能影響身體其他部分。"},{"en":"The phrase is scientific and focuses on movement without major change.","zh":"這個短語較科學，重點是沒有重大改變地移動。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":14},{"front":"the bloodstream","meaning":"血液循環","examples":[{"en":"Flavours can pass into the bloodstream before reaching the fetus.","zh":"味道可以在到達胎兒前進入血液循環。"},{"en":"The bloodstream is the flow of blood moving around the body.","zh":"bloodstream 指血液在身體內流動的系統。"},{"en":"Medicine enters the bloodstream so it can reach different organs.","zh":"藥物進入血液循環後，可以到達不同器官。"},{"en":"If harmful chemicals enter the bloodstream, they can spread through the body quickly.","zh":"如果有害化學物質進入血液循環，它們可以迅速傳遍身體。"},{"en":"The phrase is medical and refers to blood circulation.","zh":"這個短語是醫學用語，指血液循環。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":14},{"front":"the fetus","meaning":"胎兒","examples":[{"en":"Flavours may reach the fetus through the bloodstream.","zh":"味道可能透過血液循環到達胎兒。"},{"en":"The fetus is an unborn baby developing inside the mother’s body.","zh":"fetus 指在母體內發育、尚未出生的嬰兒。"},{"en":"Doctors monitor the fetus during pregnancy to check growth and health.","zh":"醫生在懷孕期間監察胎兒，以檢查成長和健康。"},{"en":"Substances reaching the fetus may influence early development.","zh":"到達胎兒的物質可能影響早期發展。"},{"en":"The word is medical and used before birth.","zh":"這個詞是醫學用語，用於出生前。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":14},{"front":"prenatal exposure","meaning":"產前接觸","examples":[{"en":"Prenatal exposure may shape later food preferences.","zh":"產前接觸可能塑造日後的食物偏好。"},{"en":"Prenatal exposure means contact with something before birth.","zh":"prenatal exposure 指出生前接觸某事物。"},{"en":"Prenatal exposure to certain sounds may make them familiar to a baby later.","zh":"產前接觸某些聲音，可能令嬰兒日後覺得它們熟悉。"},{"en":"Researchers study prenatal exposure to understand early influences on development.","zh":"研究人員研究產前接觸，以理解對發展的早期影響。"},{"en":"The phrase is medical and developmental, not about experiences after birth.","zh":"這個短語屬於醫學和發展語境，不是指出生後經驗。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":14},{"front":"shape taste perception","meaning":"塑造味覺感知","examples":[{"en":"Researchers are studying whether prenatal exposure shapes taste perception.","zh":"研究人員正在研究產前接觸是否塑造味覺感知。"},{"en":"To shape taste perception means to influence how someone experiences flavours.","zh":"shape taste perception 指影響某人如何感受味道。"},{"en":"Early exposure to vegetables may shape taste perception and make bitter foods more acceptable.","zh":"早期接觸蔬菜可能塑造味覺感知，令苦味食物較易接受。"},{"en":"Culture can shape taste perception because people learn which flavours are pleasant.","zh":"文化可以塑造味覺感知，因為人們會學習哪些味道是愉快的。"},{"en":"The phrase focuses on how taste is experienced, not only what food is eaten.","zh":"這個短語重點是味覺如何被感受，而不只是吃甚麼食物。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":14},{"front":"food preferences","meaning":"食物偏好","examples":[{"en":"Prenatal exposure may shape food preferences later in life.","zh":"產前接觸可能塑造人生較後階段的食物偏好。"},{"en":"Food preferences are the foods or flavours a person tends to like or choose.","zh":"food preferences 指一個人傾向喜歡或選擇的食物或味道。"},{"en":"A child’s food preferences may include sweet fruit but not bitter vegetables.","zh":"孩子的食物偏好可能包括甜水果，但不包括苦味蔬菜。"},{"en":"Food preferences can change after travel, illness, family habits, or repeated exposure.","zh":"食物偏好可以因旅行、疾病、家庭習慣或反覆接觸而改變。"},{"en":"The phrase describes patterns of liking, not strict medical needs.","zh":"這個短語描述喜好模式，而不是嚴格醫療需要。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":14},{"front":"later in life","meaning":"日後；人生較後階段","examples":[{"en":"Early exposure may affect preferences later in life.","zh":"早期接觸可能影響日後的偏好。"},{"en":"Later in life means at a later stage of a person’s life.","zh":"later in life 指人生較後的階段。"},{"en":"Good reading habits in childhood can help learning later in life.","zh":"童年的良好閱讀習慣可以幫助日後學習。"},{"en":"Injuries in youth may cause health problems later in life.","zh":"年輕時的受傷可能在人生較後階段造成健康問題。"},{"en":"The phrase connects early experience with future results.","zh":"這個短語把早期經驗與未來結果連起來。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":14},{"front":"genetic influences at work","meaning":"遺傳影響正在發揮作用","examples":[{"en":"There are clearly genetic influences at work in taste perception.","zh":"在味覺感知中，顯然有遺傳影響正在發揮作用。"},{"en":"Genetic influences at work means genes are actively affecting the situation or result.","zh":"genetic influences at work 指基因正積極影響情況或結果。"},{"en":"If relatives share similar food dislikes, there may be genetic influences at work.","zh":"如果親屬有相似的食物厭惡，可能有遺傳影響正在發揮作用。"},{"en":"Researchers look for genetic influences at work when identical twins respond similarly.","zh":"當同卵雙胞胎反應相似，研究人員會尋找是否有遺傳影響正在發揮作用。"},{"en":"The phrase points to hidden forces operating behind an observed pattern.","zh":"這個短語指出觀察到的模式背後正在運作的隱藏力量。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":14},{"front":"the ability to taste","meaning":"品嚐……的能力","examples":[{"en":"The ability to taste quinine varies from person to person.","zh":"品嚐奎寧的能力因人而異。"},{"en":"The ability to taste something is the capacity to detect its flavour.","zh":"ability to taste something 指偵測某物味道的能力。"},{"en":"Some people have a stronger ability to taste bitterness than others.","zh":"有些人品嚐苦味的能力比其他人強。"},{"en":"Illness can reduce the ability to taste food clearly.","zh":"疾病可以降低清楚品嚐食物的能力。"},{"en":"The phrase describes sensory capacity, not personal preference alone.","zh":"這個短語描述感官能力，而不只是個人喜好。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":14},{"front":"quinine","meaning":"奎寧","examples":[{"en":"Some people experience quinine as intensely bitter.","zh":"有些人覺得奎寧極苦。"},{"en":"Quinine is a bitter-tasting chemical that can be used in medicine and tonic water.","zh":"quinine 指一種有苦味的化學物質，可用於藥物和湯力水。"},{"en":"In taste research, quinine may be used to test sensitivity to bitterness.","zh":"在味覺研究中，奎寧可能用來測試對苦味的敏感度。"},{"en":"People who taste quinine strongly may dislike drinks that contain bitter flavours.","zh":"強烈嚐到奎寧味道的人可能不喜歡含苦味的飲品。"},{"en":"The word refers to a specific substance, not bitterness in general.","zh":"這個詞指一種特定物質，而不是一般苦味。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":14},{"front":"intensely bitter","meaning":"極苦的","examples":[{"en":"Some people find quinine intensely bitter.","zh":"有些人覺得奎寧極苦。"},{"en":"Intensely bitter means extremely bitter in taste.","zh":"intensely bitter 指味道非常苦。"},{"en":"A burnt cup of coffee may taste intensely bitter.","zh":"一杯燒焦的咖啡可能嘗起來極苦。"},{"en":"If medicine is intensely bitter, children may refuse to swallow it.","zh":"如果藥物極苦，孩子可能拒絕吞下。"},{"en":"The phrase describes a very strong taste, not mild dislike.","zh":"這個短語描述非常強烈的味道，而不是輕微不喜歡。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":15},{"front":"at very low levels","meaning":"在很低濃度下","examples":[{"en":"Quinine may taste bitter even at very low levels.","zh":"奎寧即使在很低濃度下也可能嚐起來苦。"},{"en":"At very low levels means even when the amount or concentration is very small.","zh":"at very low levels 指即使數量或濃度很小。"},{"en":"Some people can smell smoke at very low levels.","zh":"有些人在很低濃度下也能聞到煙味。"},{"en":"A chemical may be harmful at very low levels if it is extremely toxic.","zh":"如果一種化學物質毒性極高，它在很低濃度下也可能有害。"},{"en":"The phrase highlights sensitivity to a small amount.","zh":"這個短語強調對小量物質的敏感度。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":15},{"front":"genetic endowment","meaning":"遺傳稟賦","examples":[{"en":"People with a different genetic endowment may be less bothered by quinine.","zh":"擁有不同遺傳稟賦的人可能較少受奎寧困擾。"},{"en":"Genetic endowment means the set of genes a person inherits.","zh":"genetic endowment 指一個人遺傳所得的一套基因。"},{"en":"A person’s genetic endowment can influence height, taste sensitivity, and disease risk.","zh":"一個人的遺傳稟賦可以影響身高、味覺敏感度和患病風險。"},{"en":"Genetic endowment is fixed at birth, but its effects can interact with environment.","zh":"遺傳稟賦在出生時已固定，但其影響可以與環境互動。"},{"en":"The phrase is formal and refers to inherited biological resources.","zh":"這個短語較正式，指遺傳得來的生物資源。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":15},{"front":"be less bothered by","meaning":"較少受……困擾","examples":[{"en":"Some people are less bothered by the bitter taste of quinine.","zh":"有些人較少受奎寧的苦味困擾。"},{"en":"To be less bothered by something means to feel less discomfort, worry, or annoyance from it.","zh":"be less bothered by something 指較少因某事感到不適、擔心或煩惱。"},{"en":"A student who practises speaking often is less bothered by small mistakes.","zh":"經常練習說話的學生較少受小錯誤困擾。"},{"en":"People used to city noise may be less bothered by traffic sounds.","zh":"習慣城市噪音的人可能較少受交通聲困擾。"},{"en":"The phrase compares reactions and suggests lower sensitivity or concern.","zh":"這個短語比較反應，暗示敏感度或關注程度較低。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":15},{"front":"make this extremely clear","meaning":"使這一點非常清楚","examples":[{"en":"Twin studies make genetic influence on taste extremely clear.","zh":"雙胞胎研究使味覺上的遺傳影響非常清楚。"},{"en":"To make this extremely clear means to show a point so strongly that it is hard to misunderstand.","zh":"make this extremely clear 指把某一點顯示得很強，令人難以誤解。"},{"en":"A simple chart can make this extremely clear when numbers are confusing.","zh":"當數字令人困惑，一個簡單圖表可以使這一點非常清楚。"},{"en":"If both identical twins react the same way, the evidence may make this extremely clear.","zh":"如果兩名同卵雙胞胎反應相同，證據可能使這一點非常清楚。"},{"en":"The phrase strengthens a conclusion by stressing clarity.","zh":"這個短語透過強調清晰度來加強結論。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":15},{"front":"within a pair of identical twins","meaning":"在一對同卵雙胞胎之中","examples":[{"en":"Within a pair of identical twins, both usually react similarly to quinine.","zh":"在一對同卵雙胞胎之中，兩人通常對奎寧反應相似。"},{"en":"Within a pair of identical twins means among the two people in one identical-twin pair.","zh":"within a pair of identical twins 指在一對同卵雙胞胎的兩個人之中。"},{"en":"Within a pair of identical twins, researchers may compare health, taste, or behaviour.","zh":"在一對同卵雙胞胎之中，研究人員可能比較健康、味覺或行為。"},{"en":"Similar results within a pair of identical twins may suggest genetic influence.","zh":"在一對同卵雙胞胎之中出現相似結果，可能暗示遺傳影響。"},{"en":"The phrase focuses on one twin pair, not all twins in general.","zh":"這個短語重點是一對雙胞胎，而不是所有雙胞胎。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":15},{"front":"hard to swallow","meaning":"難以吞嚥；令人難以接受","examples":[{"en":"Both twins may find quinine hard to swallow.","zh":"兩名雙胞胎都可能覺得奎寧難以吞嚥。"},{"en":"Hard to swallow can mean physically difficult to swallow or emotionally difficult to accept.","zh":"hard to swallow 可以指身體上難以吞下，或情感上難以接受。"},{"en":"A very bitter medicine may be hard to swallow for a child.","zh":"非常苦的藥對孩子來說可能難以吞嚥。"},{"en":"Bad news can be hard to swallow even when it is true.","zh":"壞消息即使是真的，也可能令人難以接受。"},{"en":"The phrase can be literal or metaphorical, depending on context.","zh":"這個短語可按語境作字面或比喻用法。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":15},{"front":"agree less frequently","meaning":"一致的頻率較低","examples":[{"en":"Non-identical twins agree less frequently in their reaction to quinine.","zh":"異卵雙胞胎對奎寧反應一致的頻率較低。"},{"en":"To agree less frequently means to match or give the same response less often.","zh":"agree less frequently 指較少相符或給出相同反應。"},{"en":"Two reviewers agree less frequently when they have very different tastes.","zh":"當兩名評論者口味很不同，他們一致的頻率較低。"},{"en":"If non-identical twins agree less frequently, genes may explain part of the difference.","zh":"如果異卵雙胞胎一致的頻率較低，基因可能解釋部分差異。"},{"en":"The phrase compares how often two people or groups match.","zh":"這個短語比較兩人或兩組相符的頻率。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":15},{"front":"on the other side of","meaning":"在……的另一邊","examples":[{"en":"On the other side of the tent, Dennis Drayna was studying hearing.","zh":"在帳篷的另一邊，Dennis Drayna 正在研究聽覺。"},{"en":"On the other side of something means in the area opposite or across from it.","zh":"on the other side of something 指在某物對面或另一側的區域。"},{"en":"The library is on the other side of the road from the school.","zh":"圖書館在學校馬路的另一邊。"},{"en":"At an exhibition, another activity may happen on the other side of the hall.","zh":"在展覽中，另一項活動可能在大廳的另一邊進行。"},{"en":"The phrase helps describe location clearly.","zh":"這個短語幫助清楚描述位置。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":15},{"front":"the National Institute on Deafness and Other Communication Disorders","meaning":"國家耳聾及其他溝通障礙研究所","examples":[{"en":"The National Institute on Deafness and Other Communication Disorders studies hearing and communication.","zh":"國家耳聾及其他溝通障礙研究所研究聽覺和溝通。"},{"en":"The National Institute on Deafness and Other Communication Disorders is a research body focused on hearing, speech, language, and communication problems.","zh":"National Institute on Deafness and Other Communication Disorders 是專注於聽覺、說話、語言和溝通問題的研究機構。"},{"en":"Scientists from such an institute may study how people hear sounds or process speech.","zh":"來自這類研究所的科學家可能研究人們如何聽到聲音或處理語音。"},{"en":"Research from this institute can help improve diagnosis and treatment for communication disorders.","zh":"這所研究所的研究可以幫助改善溝通障礙的診斷和治療。"},{"en":"The phrase is a formal name, so it should be kept accurate.","zh":"這個短語是正式名稱，因此應保持準確。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":15},{"front":"study hearing","meaning":"研究聽覺","examples":[{"en":"Dennis Drayna was studying hearing at the festival.","zh":"Dennis Drayna 在節日研究聽覺。"},{"en":"To study hearing means to research how people detect, process, or understand sound.","zh":"study hearing 指研究人們如何偵測、處理或理解聲音。"},{"en":"Doctors study hearing to understand why some people cannot hear certain frequencies.","zh":"醫生研究聽覺，以理解為何有些人聽不到某些頻率。"},{"en":"Scientists may study hearing by playing sounds and recording volunteers’ responses.","zh":"科學家可能透過播放聲音和記錄志願者反應來研究聽覺。"},{"en":"The phrase refers to scientific investigation of the sense of hearing.","zh":"這個短語指對聽覺這一感官的科學研究。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":15},{"front":"sounds reach the ear","meaning":"聲音到達耳朵","examples":[{"en":"He wants to know what happens after sounds reach the ear.","zh":"他想知道聲音到達耳朵後會發生甚麼。"},{"en":"When sounds reach the ear, sound waves arrive at the hearing organ.","zh":"sounds reach the ear 指聲波到達聽覺器官。"},{"en":"Music must reach the ear before the brain can recognise melody.","zh":"音樂必須先到達耳朵，大腦才能辨認旋律。"},{"en":"If sounds reach the ear but are not processed well, hearing may still be unclear.","zh":"如果聲音到達耳朵但沒有被妥善處理，聽覺仍可能不清楚。"},{"en":"The phrase describes the first stage of hearing.","zh":"這個短語描述聽覺的第一階段。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":16},{"front":"be processed into sensation","meaning":"被處理成感覺","examples":[{"en":"Sound may be processed into sensation in the ear or brain.","zh":"聲音可能在耳朵或大腦中被處理成感覺。"},{"en":"To be processed into sensation means to be changed by the body into something a person can feel or perceive.","zh":"be processed into sensation 指被身體轉化成人能感受或感知的東西。"},{"en":"Light is processed into visual sensation when the eyes and brain work together.","zh":"當眼睛和大腦一起運作，光線會被處理成視覺感覺。"},{"en":"If signals are not processed into sensation properly, perception may become unclear.","zh":"如果訊號沒有被正確處理成感覺，感知可能變得不清楚。"},{"en":"The phrase explains how physical signals become experience.","zh":"這個短語解釋物理訊號如何變成經驗。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":16},{"front":"mostly in","meaning":"主要在","examples":[{"en":"Researchers ask whether sound is processed mostly in the ear or in the brain.","zh":"研究人員問聲音主要是在耳朵還是在大腦中被處理。"},{"en":"Mostly in means mainly in one place, though not necessarily only there.","zh":"mostly in 指主要在某一地方，但不一定只在那裡。"},{"en":"A company’s customers may live mostly in nearby districts.","zh":"一間公司的顧客可能主要在附近地區。"},{"en":"If a problem happens mostly in one department, managers can focus support there.","zh":"如果問題主要在一個部門發生，管理者可以集中支援那裡。"},{"en":"The phrase shows the main location or area of something.","zh":"這個短語顯示某事的主要地點或範圍。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":16},{"front":"be involved in","meaning":"參與","examples":[{"en":"Dr Drayna had already been involved in a twin study.","zh":"Dr Drayna 已經參與過一項雙胞胎研究。"},{"en":"To be involved in something means to take part in it or have a role in it.","zh":"be involved in something 指參與某事或在其中有角色。"},{"en":"A student may be involved in a school charity project.","zh":"學生可能參與學校慈善項目。"},{"en":"Researchers involved in a study must follow its methods and ethical rules.","zh":"參與研究的研究人員必須遵守其方法和倫理規則。"},{"en":"The phrase can describe active participation or connection.","zh":"這個短語可以描述主動參與或有關連。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":16},{"front":"reveal that","meaning":"揭示","examples":[{"en":"A twin study revealed that musical pitch perception is highly heritable.","zh":"一項雙胞胎研究揭示對音高的感知高度可遺傳。"},{"en":"To reveal that something is true means to show or make it known.","zh":"reveal that something is true 指顯示或使某事為人所知。"},{"en":"Test results may reveal that a student needs more vocabulary practice.","zh":"測驗結果可能揭示學生需要更多詞彙練習。"},{"en":"A survey can reveal that many workers feel stressed but do not complain openly.","zh":"問卷可以揭示許多員工感到壓力，但沒有公開抱怨。"},{"en":"The phrase is useful when evidence uncovers a hidden fact.","zh":"這個短語適合表示證據揭開隱藏事實。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":16},{"front":"perception of musical pitch","meaning":"對音高的感知","examples":[{"en":"The perception of musical pitch is highly heritable.","zh":"對音高的感知是高度可遺傳的。"},{"en":"Perception of musical pitch is the ability to hear how high or low a sound is.","zh":"perception of musical pitch 指聽出聲音高低的能力。"},{"en":"A singer needs good perception of musical pitch to stay in tune.","zh":"歌手需要良好的音高感知才能不走音。"},{"en":"Differences in pitch perception can affect how people learn music.","zh":"音高感知差異可以影響人們如何學習音樂。"},{"en":"The phrase refers to hearing musical height, not liking music.","zh":"這個短語指聽出音樂高低，而不是喜不喜歡音樂。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":16},{"front":"highly heritable","meaning":"高度可遺傳的","examples":[{"en":"The perception of musical pitch is highly heritable.","zh":"對音高的感知是高度可遺傳的。"},{"en":"Highly heritable means strongly influenced by genes.","zh":"highly heritable 指強烈受基因影響。"},{"en":"A trait that is highly heritable often appears more similarly in identical twins.","zh":"高度可遺傳的特質通常在同卵雙胞胎中更相似。"},{"en":"Even if a skill is highly heritable, practice can still improve performance.","zh":"即使某技能高度可遺傳，練習仍可以改善表現。"},{"en":"The phrase shows strong genetic influence, not complete genetic control.","zh":"這個短語顯示強烈遺傳影響，而不是完全由基因控制。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":16},{"front":"play words into","meaning":"把字詞播放到……","examples":[{"en":"Dr Drayna played words into the ears of his volunteers.","zh":"Dr Drayna 把字詞播放到志願者耳中。"},{"en":"To play words into someone’s ears means to make them hear recorded words through headphones or speakers.","zh":"play words into someone’s ears 指透過耳機或揚聲器讓某人聽到錄音字詞。"},{"en":"A language teacher may play words into students’ ears to practise pronunciation.","zh":"語言老師可能把字詞播放到學生耳中，以練習發音。"},{"en":"In a hearing test, researchers can play words into each ear separately.","zh":"在聽覺測試中，研究人員可以把字詞分別播放到每隻耳朵。"},{"en":"The phrase describes controlled sound delivery in an experiment.","zh":"這個短語描述實驗中受控地傳送聲音。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":16},{"front":"left and right ears","meaning":"左耳和右耳","examples":[{"en":"Different sounds were played into the left and right ears.","zh":"不同聲音被播放到左耳和右耳。"},{"en":"Left and right ears means the two ears on opposite sides of the head.","zh":"left and right ears 指頭部兩側的兩隻耳朵。"},{"en":"A hearing test may check the left and right ears separately.","zh":"聽力測試可能分開檢查左耳和右耳。"},{"en":"If one ear hears better, sounds may seem stronger on that side.","zh":"如果一隻耳朵聽得較好，聲音可能在那一側顯得較強。"},{"en":"The phrase is simple but important in hearing experiments.","zh":"這個短語簡單，但在聽覺實驗中很重要。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":16},{"front":"twinned volunteers","meaning":"雙胞胎志願者","examples":[{"en":"The researchers tested twinned volunteers.","zh":"研究人員測試了雙胞胎志願者。"},{"en":"Twinned volunteers are volunteers who are twins and take part in a study.","zh":"twinned volunteers 指身為雙胞胎並參與研究的志願者。"},{"en":"A festival can provide many twinned volunteers for researchers.","zh":"節日可以為研究人員提供許多雙胞胎志願者。"},{"en":"Testing twinned volunteers helps scientists compare genetic similarity with individual experience.","zh":"測試雙胞胎志願者幫助科學家比較遺傳相似性與個人經驗。"},{"en":"The phrase is formal and specific to twin-based research.","zh":"這個短語較正式，專門用於以雙胞胎為基礎的研究。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":16},{"front":"the composite of","meaning":"……的混合結果","examples":[{"en":"The composite of the two sounds depends on how the brain processes information.","zh":"兩種聲音的混合結果取決於大腦如何處理資訊。"},{"en":"The composite of two things is the combined result made from them.","zh":"composite of two things 指由兩者組成的合併結果。"},{"en":"A smoothie is the composite of fruit, milk, and ice blended together.","zh":"奶昔是水果、牛奶和冰混合而成的結果。"},{"en":"When each ear hears a different word, the brain may report a composite of both sounds.","zh":"當每隻耳朵聽到不同字詞，大腦可能報告兩種聲音的混合結果。"},{"en":"The phrase focuses on the final mixture, not the separate parts alone.","zh":"這個短語重點是最終混合結果，而不只是各個部分。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":16},{"front":"report hearing","meaning":"報稱聽到","examples":[{"en":"Each individual reported hearing a composite of two sounds.","zh":"每個人報稱聽到兩種聲音的混合結果。"},{"en":"To report hearing something means to say what sound one believes one heard.","zh":"report hearing something 指說出自己認為聽到的聲音。"},{"en":"In a listening test, students report hearing a word by writing it down.","zh":"在聆聽測試中，學生透過寫下字詞來報稱聽到某詞。"},{"en":"Volunteers may report hearing different sounds even when the recording is the same.","zh":"即使錄音相同，志願者可能報稱聽到不同聲音。"},{"en":"The phrase focuses on a person’s stated perception.","zh":"這個短語重點是個人陳述的感知。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":17},{"front":"diverse information","meaning":"多樣化資料","examples":[{"en":"The brain must process diverse auditory information.","zh":"大腦必須處理多樣化聽覺資料。"},{"en":"Diverse information means many different kinds of information.","zh":"diverse information 指許多不同種類的資訊。"},{"en":"A teacher uses diverse information, such as test scores and class behaviour, to understand students.","zh":"老師使用測驗分數和課堂行為等多樣化資料來了解學生。"},{"en":"When information is diverse, the brain or researcher must organise it carefully.","zh":"當資料多樣化，大腦或研究人員必須仔細組織它。"},{"en":"The phrase stresses variety, not just a large amount.","zh":"這個短語強調種類多樣，而不只是數量大。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":17},{"front":"may well be influenced by","meaning":"很可能受……影響","examples":[{"en":"Sound processing may well be influenced by genetics.","zh":"聲音處理很可能受遺傳影響。"},{"en":"May well be influenced by means is quite likely to be affected by something.","zh":"may well be influenced by 指很可能受某事影響。"},{"en":"A child’s food choices may well be influenced by family meals.","zh":"孩子的食物選擇很可能受家庭膳食影響。"},{"en":"Test performance may well be influenced by sleep, not only ability.","zh":"考試表現很可能受睡眠影響，而不只是能力。"},{"en":"The phrase expresses a strong possibility without claiming certainty.","zh":"這個短語表達強烈可能性，但不聲稱確定。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":17},{"front":"elsewhere in the marquee","meaning":"在大帳篷的其他地方","examples":[{"en":"Elsewhere in the marquee, another researcher studied communication.","zh":"在大帳篷的其他地方，另一名研究人員研究溝通。"},{"en":"Elsewhere in the marquee means in another part of the large tent.","zh":"elsewhere in the marquee 指在大型帳篷的另一部分。"},{"en":"Elsewhere in the hall, students were presenting science posters.","zh":"在禮堂的其他地方，學生正在展示科學海報。"},{"en":"At a festival, different activities may happen elsewhere in the marquee at the same time.","zh":"在節日中，不同活動可能同時在大帳篷的其他地方進行。"},{"en":"The phrase helps shift attention to another location nearby.","zh":"這個短語幫助把注意力轉移到附近另一個位置。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":17},{"front":"motivation to communicate","meaning":"溝通動機","examples":[{"en":"Peter Miraldi studied people’s motivation to communicate with others.","zh":"Peter Miraldi 研究人們與他人溝通的動機。"},{"en":"Motivation to communicate is the desire or willingness to exchange ideas, feelings, or information.","zh":"motivation to communicate 指交換想法、感受或資訊的渴望或意願。"},{"en":"A shy student may have low motivation to communicate in a large class.","zh":"害羞的學生在大班中可能溝通動機較低。"},{"en":"Positive feedback can increase motivation to communicate because people feel heard.","zh":"正面回饋可以增加溝通動機，因為人們覺得自己被聽見。"},{"en":"The phrase focuses on the drive to interact, not communication skill alone.","zh":"這個短語重點是互動的動力，而不只是溝通技巧。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":17},{"front":"a number of","meaning":"多項；若干","examples":[{"en":"A number of twin studies have shown that personality is heritable.","zh":"多項雙胞胎研究顯示性格是可遺傳的。"},{"en":"A number of means several or quite a few.","zh":"a number of 指數個或相當多。"},{"en":"A number of students asked for extra grammar practice.","zh":"若干學生要求額外文法練習。"},{"en":"If a number of reports show the same problem, managers should take it seriously.","zh":"如果多份報告顯示同一問題，管理者應認真處理。"},{"en":"The phrase is more formal than some and less exact than a specific number.","zh":"這個短語比 some 更正式，但不如具體數字精確。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":17},{"front":"personality and sociability","meaning":"性格與社交能力","examples":[{"en":"Personality and sociability are partly heritable.","zh":"性格與社交能力部分可遺傳。"},{"en":"Personality and sociability mean a person’s character patterns and ability or desire to mix with others.","zh":"personality and sociability 指一個人的性格模式，以及與他人相處的能力或意願。"},{"en":"A student’s personality and sociability can affect group work.","zh":"學生的性格與社交能力可以影響小組工作。"},{"en":"Personality and sociability may be shaped by both genes and social experience.","zh":"性格與社交能力可能同時受基因和社交經驗塑造。"},{"en":"The phrase links inner character with social behaviour.","zh":"這個短語把內在性格與社交行為連起來。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":17},{"front":"sociability","meaning":"社交能力；合群性","examples":[{"en":"Sociability may be influenced by genes.","zh":"社交能力可能受基因影響。"},{"en":"Sociability is the ability or tendency to enjoy being with and talking to other people.","zh":"sociability 指喜歡與他人相處和交談的能力或傾向。"},{"en":"A sociable child may make friends quickly in a new class.","zh":"合群的孩子可能在新班級中很快交朋友。"},{"en":"Low sociability can make networking events feel tiring.","zh":"社交能力較低可能令社交活動令人感到疲倦。"},{"en":"The word describes social tendency, not whether someone is kind or unkind.","zh":"這個詞描述社交傾向，而不是某人善良與否。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":17},{"front":"fertile ground","meaning":"有研究價值的領域","examples":[{"en":"Miraldi thinks motivation to communicate is fertile ground for research.","zh":"Miraldi 認為溝通動機是有研究價值的領域。"},{"en":"Fertile ground means an area that is likely to produce useful results or ideas.","zh":"fertile ground 指很可能產生有用結果或想法的範疇。"},{"en":"A classroom with many language backgrounds is fertile ground for discussion about culture.","zh":"有多種語言背景的課室是討論文化的有價值領域。"},{"en":"New technology is fertile ground for business ideas because many problems remain unsolved.","zh":"新科技是商業想法的肥沃土壤，因為仍有許多問題未解決。"},{"en":"The phrase uses a farming image to mean rich potential.","zh":"這個短語使用農業意象，意思是有豐富潛力。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":17},{"front":"dermatologists","meaning":"皮膚科醫生","examples":[{"en":"Dermatologists studied skin disease and male-pattern baldness.","zh":"皮膚科醫生研究皮膚病和男性型脫髮。"},{"en":"Dermatologists are doctors who specialise in skin, hair, and nail problems.","zh":"dermatologists 指專門處理皮膚、頭髮和指甲問題的醫生。"},{"en":"A dermatologist may treat acne, rashes, hair loss, or unusual moles.","zh":"皮膚科醫生可能治療暗瘡、皮疹、脫髮或不尋常的痣。"},{"en":"People visit dermatologists when skin symptoms do not improve with basic care.","zh":"當皮膚症狀在基本護理後仍未改善，人們會看皮膚科醫生。"},{"en":"The word refers to medical specialists, not beauty consultants.","zh":"這個詞指醫學專科醫生，而不是美容顧問。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":17},{"front":"Case Western Reserve University","meaning":"凱斯西儲大學","examples":[{"en":"A team from Case Western Reserve University studied skin and hair conditions.","zh":"來自凱斯西儲大學的團隊研究皮膚和頭髮狀況。"},{"en":"Case Western Reserve University is the name of a university linked here with medical research.","zh":"Case Western Reserve University 是一所大學的名稱，在這裡與醫學研究有關。"},{"en":"Researchers from Case Western Reserve University may work in teams with doctors and scientists.","zh":"凱斯西儲大學的研究人員可能與醫生和科學家組成團隊工作。"},{"en":"Naming the university helps readers identify where the research team came from.","zh":"說出大學名稱有助讀者辨認研究團隊來自哪裡。"},{"en":"The phrase is a proper noun, so it should not be translated loosely.","zh":"這個短語是專有名詞，因此不應自由翻譯。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":17},{"front":"look at the development of","meaning":"研究……的發展","examples":[{"en":"The team looked at the development of skin disease.","zh":"團隊研究皮膚病的發展。"},{"en":"To look at the development of something means to study how it begins, grows, or changes.","zh":"look at the development of something 指研究某事如何開始、成長或改變。"},{"en":"Teachers may look at the development of a student’s writing over a year.","zh":"老師可能研究學生一年內寫作的發展。"},{"en":"Doctors look at the development of symptoms to decide which tests are needed.","zh":"醫生研究症狀的發展，以決定需要哪些檢查。"},{"en":"The phrase is less formal than investigate but still means examine carefully.","zh":"這個短語比 investigate 較不正式，但仍表示仔細檢視。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":18},{"front":"skin disease","meaning":"皮膚病","examples":[{"en":"Researchers studied the development of skin disease.","zh":"研究人員研究皮膚病的發展。"},{"en":"Skin disease is any illness or medical condition that affects the skin.","zh":"skin disease 指任何影響皮膚的疾病或醫療狀況。"},{"en":"Eczema, acne, and serious rashes are examples of skin disease.","zh":"濕疹、暗瘡和嚴重皮疹都是皮膚病的例子。"},{"en":"Skin disease can cause itching, pain, visible marks, or emotional stress.","zh":"皮膚病可以造成痕癢、疼痛、可見痕跡或情緒壓力。"},{"en":"The phrase is broad and should be followed by details when possible.","zh":"這個短語很廣泛，如有可能應補充細節。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":18},{"front":"male-pattern baldness","meaning":"男性型脫髮","examples":[{"en":"The team studied male-pattern baldness.","zh":"團隊研究男性型脫髮。"},{"en":"Male-pattern baldness is a common type of hair loss in men, often linked to genes and hormones.","zh":"male-pattern baldness 指男性常見的一種脫髮，通常與基因和荷爾蒙有關。"},{"en":"Male-pattern baldness usually begins with thinning hair at the hairline or crown.","zh":"男性型脫髮通常由髮線或頭頂頭髮變薄開始。"},{"en":"Researchers study male-pattern baldness to understand why some men lose hair earlier.","zh":"研究人員研究男性型脫髮，以理解為何有些男性較早脫髮。"},{"en":"The phrase describes a specific pattern of hair loss, not all baldness.","zh":"這個短語描述特定脫髮模式，而不是所有禿頭情況。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":18},{"front":"the goal of","meaning":"……的目標","examples":[{"en":"The goal of the research was to find genes linked to hair loss.","zh":"這項研究的目標是找出與脫髮有關的基因。"},{"en":"The goal of something is its main purpose or intended result.","zh":"the goal of something 指某事的主要目的或預期結果。"},{"en":"The goal of a lesson may be to help students use a grammar pattern accurately.","zh":"一堂課的目標可能是幫助學生準確使用一個文法句式。"},{"en":"Clear goals help teams decide what work matters most.","zh":"清晰目標幫助團隊決定哪些工作最重要。"},{"en":"The phrase explains why an activity is being done.","zh":"這個短語解釋為甚麼要做某項活動。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":18},{"front":"the latter piece of research","meaning":"後一項研究","examples":[{"en":"The latter piece of research focused on male-pattern baldness.","zh":"後一項研究集中於男性型脫髮。"},{"en":"The latter piece of research means the second of two studies just mentioned.","zh":"the latter piece of research 指剛提到兩項研究中的第二項。"},{"en":"If one study examined skin and another examined hair, the latter piece of research means the hair study.","zh":"如果一項研究檢視皮膚，另一項檢視頭髮，後一項研究就是頭髮研究。"},{"en":"Writers use latter to avoid repeating a long description.","zh":"寫作者使用 latter 來避免重複很長描述。"},{"en":"The phrase depends on a previous comparison between two items.","zh":"這個短語依賴前文對兩個項目的比較。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":18},{"front":"genes responsible for","meaning":"導致……的基因","examples":[{"en":"Researchers want to find the genes responsible for male-pattern baldness.","zh":"研究人員想找出導致男性型脫髮的基因。"},{"en":"Genes responsible for something are genes that help cause or influence it.","zh":"genes responsible for something 指幫助造成或影響某事的基因。"},{"en":"Scientists may search for genes responsible for a rare inherited disease.","zh":"科學家可能尋找導致罕見遺傳疾病的基因。"},{"en":"Finding genes responsible for a condition can help doctors understand risk.","zh":"找出導致某狀況的基因可以幫助醫生理解風險。"},{"en":"The phrase suggests genetic contribution, not always a single direct cause.","zh":"這個短語暗示基因貢獻，不一定是單一直接原因。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":18},{"front":"hair fall out","meaning":"頭髮脫落","examples":[{"en":"The research aims to find why men’s hair falls out.","zh":"這項研究旨在找出男性頭髮為何脫落。"},{"en":"If hair falls out, it leaves the head or body and becomes thinner or lost.","zh":"如果 hair falls out，意思是頭髮離開頭部或身體，變薄或失去。"},{"en":"Stress, illness, age, or genes can make hair fall out.","zh":"壓力、疾病、年齡或基因都可能令頭髮脫落。"},{"en":"When hair falls out quickly, a person may visit a doctor to check the cause.","zh":"當頭髮迅速脫落，一個人可能看醫生檢查原因。"},{"en":"The phrase is everyday English for hair loss.","zh":"這個短語是 hair loss 的日常英文說法。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":18},{"front":"the busiest part of","meaning":"最繁忙的部分","examples":[{"en":"The busiest part of the tent was the queue for fingerprint research.","zh":"帳篷最繁忙的部分是排隊參與指紋研究的人龍。"},{"en":"The busiest part of a place is the area with the most people, activity, or movement.","zh":"the busiest part of a place 指人最多、活動最多或流動最頻繁的區域。"},{"en":"The busiest part of a supermarket is often the checkout area after work.","zh":"超級市場最繁忙的部分通常是下班後的收銀區。"},{"en":"If the busiest part of an event becomes too crowded, organisers may need extra staff.","zh":"如果活動中最繁忙的部分變得太擠迫，主辦者可能需要額外人手。"},{"en":"The phrase helps identify where activity is most intense.","zh":"這個短語幫助指出活動最密集的位置。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":18},{"front":"the queue for","meaning":"排隊等候……的人龍","examples":[{"en":"The queue for forensic-science research was the busiest.","zh":"排隊等候法證科學研究的人龍最繁忙。"},{"en":"The queue for something is the line of people waiting for it.","zh":"the queue for something 指等候某事的人龍。"},{"en":"The queue for the school canteen is longest at lunchtime.","zh":"午餐時間排隊等候學校飯堂的人龍最長。"},{"en":"A long queue for tickets shows that many people want to attend the event.","zh":"排隊買票的人龍很長，顯示很多人想參加活動。"},{"en":"The phrase focuses on people waiting, not the service itself.","zh":"這個短語重點是正在等候的人，而不是服務本身。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":18},{"front":"forensic-science research","meaning":"法證科學研究","examples":[{"en":"The fingerprint study was part of forensic-science research.","zh":"指紋研究是法證科學研究的一部分。"},{"en":"Forensic-science research is scientific study used to help investigate crime or identify evidence.","zh":"forensic-science research 指用來協助調查罪案或鑑定證據的科學研究。"},{"en":"Forensic-science research may examine fingerprints, DNA, handwriting, or fibres.","zh":"法證科學研究可能檢查指紋、DNA、筆跡或纖維。"},{"en":"Good forensic-science research helps courts make decisions based on reliable evidence.","zh":"良好的法證科學研究幫助法庭根據可靠證據作出決定。"},{"en":"The phrase connects science with law and investigation.","zh":"這個短語把科學與法律和調查連起來。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":18},{"front":"fingerprints","meaning":"指紋","examples":[{"en":"Researchers collected fingerprints from twins.","zh":"研究人員從雙胞胎身上收集指紋。"},{"en":"Fingerprints are the unique patterns of lines on a person’s fingers.","zh":"fingerprints 指人手指上獨特的線條圖案。"},{"en":"Police may use fingerprints to identify who touched an object.","zh":"警方可能使用指紋辨認誰觸碰過物件。"},{"en":"Phones use fingerprints to unlock accounts because the patterns are hard to copy exactly.","zh":"手機使用指紋解鎖帳戶，因為圖案很難完全複製。"},{"en":"The word refers to physical marks used in identification.","zh":"這個詞指用於身份識別的身體痕跡。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":18},{"front":"origins of this study","meaning":"這項研究的起源","examples":[{"en":"The origins of this study are shrouded in mystery.","zh":"這項研究的起源被神秘感籠罩。"},{"en":"The origins of this study means how and why the study first began.","zh":"origins of this study 指這項研究最初如何和為何開始。"},{"en":"The origins of a school project may lie in one teacher’s concern about reading habits.","zh":"一個學校項目的起源可能在於一名老師對閱讀習慣的關注。"},{"en":"Knowing the origins of this study can help readers understand its purpose.","zh":"了解這項研究的起源可以幫助讀者理解其目的。"},{"en":"The phrase focuses on beginnings and background.","zh":"這個短語重點是開端和背景。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":19},{"front":"be shrouded in mystery","meaning":"被神秘感籠罩","examples":[{"en":"The origins of the fingerprint study are shrouded in mystery.","zh":"指紋研究的起源被神秘感籠罩。"},{"en":"To be shrouded in mystery means to be unclear, hidden, or surrounded by unanswered questions.","zh":"be shrouded in mystery 指不清楚、被隱藏或充滿未解問題。"},{"en":"The reason for the sudden school closure was shrouded in mystery until officials explained it.","zh":"學校突然關閉的原因一直被神秘感籠罩，直到官員解釋。"},{"en":"A project may be shrouded in mystery if no one knows who started it.","zh":"如果沒有人知道誰發起項目，該項目可能被神秘感籠罩。"},{"en":"The phrase creates a sense of uncertainty and secrecy.","zh":"這個短語營造不確定和秘密感。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":19},{"front":"festival organisers","meaning":"節日主辦者","examples":[{"en":"The festival organisers suspected that the Secret Service was behind the study.","zh":"節日主辦者懷疑美國特勤局是這項研究的幕後推動者。"},{"en":"Festival organisers are people who plan and manage a festival.","zh":"festival organisers 指策劃和管理節日活動的人。"},{"en":"Festival organisers arrange stalls, safety rules, schedules, and volunteers.","zh":"節日主辦者安排攤位、安全規則、時間表和義工。"},{"en":"If too many people arrive, festival organisers must control queues and crowd movement.","zh":"如果太多人到場，節日主辦者必須控制人龍和人流。"},{"en":"The phrase refers to those responsible for running the event.","zh":"這個短語指負責營運活動的人。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":19},{"front":"be convinced that","meaning":"深信","examples":[{"en":"The organisers were convinced that the Secret Service was behind the study.","zh":"主辦者深信美國特勤局是這項研究的幕後推動者。"},{"en":"To be convinced that something is true means to believe it strongly.","zh":"be convinced that something is true 指強烈相信某事是真的。"},{"en":"A teacher may be convinced that a student can improve with regular practice.","zh":"老師可能深信學生透過定期練習可以進步。"},{"en":"If customers are convinced that a product is safe, they are more likely to buy it.","zh":"如果顧客深信產品安全，他們較可能購買。"},{"en":"The phrase suggests firm belief, usually after reasons or evidence.","zh":"這個短語暗示通常基於理由或證據的堅定信念。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":19},{"front":"the Secret Service","meaning":"美國特勤局","examples":[{"en":"The Secret Service is responsible for the safety of the US president.","zh":"美國特勤局負責美國總統的安全。"},{"en":"The Secret Service is a government agency associated with protecting important leaders and investigating certain crimes.","zh":"Secret Service 是與保護重要領袖和調查某些罪案有關的政府機構。"},{"en":"The Secret Service may appear at major public events involving national leaders.","zh":"美國特勤局可能出現在涉及國家領袖的大型公開活動中。"},{"en":"Because of its security role, people may suspect the Secret Service in studies about identification.","zh":"由於其保安角色，人們可能懷疑美國特勤局參與身份識別研究。"},{"en":"The phrase names an official agency and should be capitalised.","zh":"這個短語是官方機構名稱，應大寫。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":19},{"front":"be behind it","meaning":"是幕後推動者","examples":[{"en":"Some organisers believed the Secret Service was behind the fingerprint study.","zh":"一些主辦者相信美國特勤局是指紋研究的幕後推動者。"},{"en":"To be behind something means to be secretly or mainly responsible for it.","zh":"be behind something 指秘密或主要負責某事。"},{"en":"Students wondered who was behind the surprise party.","zh":"學生想知道誰是驚喜派對的幕後推動者。"},{"en":"If a company is behind a campaign, it may be paying for it without being obvious.","zh":"如果一間公司是某活動的幕後推動者，它可能在不明顯的情況下出資。"},{"en":"The phrase often suggests a hidden organiser or cause.","zh":"這個短語常暗示隱藏的組織者或原因。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":19},{"front":"be responsible for","meaning":"負責；是……的原因","examples":[{"en":"The Secret Service is responsible for the safety of the president.","zh":"美國特勤局負責總統的安全。"},{"en":"To be responsible for something means to have the duty to manage it or be the cause of it.","zh":"be responsible for something 指有職責管理某事，或是某事的原因。"},{"en":"A class monitor may be responsible for collecting homework.","zh":"班長可能負責收功課。"},{"en":"Poor planning can be responsible for delays in a project.","zh":"計劃不周可以是項目延誤的原因。"},{"en":"The phrase can mean duty or cause, depending on context.","zh":"這個短語可按語境指職責或原因。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":19},{"front":"among other things","meaning":"除其他職責外；除了其他事情外","examples":[{"en":"The Secret Service is responsible for the president’s safety, among other things.","zh":"美國特勤局除其他職責外，負責總統安全。"},{"en":"Among other things means in addition to other duties, facts, or examples not fully listed.","zh":"among other things 指除了未完全列出的其他職責、事實或例子之外。"},{"en":"A teacher’s job includes planning lessons, marking work, and helping students, among other things.","zh":"老師的工作包括備課、批改作業和幫助學生，此外還有其他事情。"},{"en":"A city needs transport, housing, clean water, and public safety, among other things.","zh":"城市需要交通、住屋、清潔食水和公共安全，此外還有其他事情。"},{"en":"The phrase shows that the list is not complete.","zh":"這個短語顯示清單並不完整。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":19},{"front":"refer someone to","meaning":"把某人轉介給","examples":[{"en":"The Economist was referred to Steve Nash for more information.","zh":"《經濟學人》被轉介給 Steve Nash 以取得更多資料。"},{"en":"To refer someone to a person or place means to direct them there for help or information.","zh":"refer someone to a person or place 指把某人引導到某人或某處以取得幫助或資訊。"},{"en":"A receptionist may refer a patient to a specialist clinic.","zh":"接待員可能把病人轉介給專科診所。"},{"en":"If a teacher cannot answer a question, she may refer the student to the library staff.","zh":"如果老師不能回答問題，她可能把學生轉介給圖書館職員。"},{"en":"The phrase shows guided redirection.","zh":"這個短語表示有指引的轉介。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":19},{"front":"chairman of","meaning":"……的主席","examples":[{"en":"Steve Nash is chairman of the International Association for Identification.","zh":"Steve Nash 是國際鑑定協會的主席。"},{"en":"Chairman of an organisation means the person who leads or presides over it.","zh":"chairman of an organisation 指領導或主持該組織的人。"},{"en":"The chairman of a club may run meetings and represent members.","zh":"社團主席可能主持會議並代表會員。"},{"en":"A chairman of a committee helps organise discussion and decisions.","zh":"委員會主席幫助組織討論和決策。"},{"en":"The phrase identifies a leadership role.","zh":"這個短語指出領導角色。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":19},{"front":"scientific investigations section","meaning":"科學調查組","examples":[{"en":"Steve Nash works in the scientific investigations section of a sheriff’s office.","zh":"Steve Nash 在警長辦公室的科學調查組工作。"},{"en":"A scientific investigations section is a department that uses science to examine evidence or cases.","zh":"scientific investigations section 指使用科學檢查證據或案件的部門。"},{"en":"A police scientific investigations section may study fingerprints, photos, and physical evidence.","zh":"警方科學調查組可能研究指紋、照片和實物證據。"},{"en":"Such a section helps investigators make decisions based on reliable analysis.","zh":"這類部門幫助調查人員根據可靠分析作出決定。"},{"en":"The phrase combines science with official investigation work.","zh":"這個短語把科學與官方調查工作連起來。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":19},{"front":"Sheriff’s Office","meaning":"縣警長辦公室","examples":[{"en":"Steve Nash works for the Marin County Sheriff’s Office.","zh":"Steve Nash 在馬林縣警長辦公室工作。"},{"en":"A Sheriff’s Office is a local law-enforcement office led by a sheriff.","zh":"Sheriff’s Office 指由警長領導的本地執法辦公室。"},{"en":"A Sheriff’s Office may handle patrols, local investigations, and court-related duties.","zh":"縣警長辦公室可能負責巡邏、本地調查和與法庭有關的職責。"},{"en":"People may contact the Sheriff’s Office to report certain community safety problems.","zh":"人們可能聯絡縣警長辦公室，報告某些社區安全問題。"},{"en":"The phrase names a type of official law-enforcement workplace.","zh":"這個短語指一種官方執法工作場所。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":20},{"front":"be based in","meaning":"總部設於","examples":[{"en":"The IAI is based in Minnesota.","zh":"IAI 總部設於明尼蘇達州。"},{"en":"To be based in a place means to have the main office or regular working location there.","zh":"be based in a place 指主要辦公室或固定工作地點設於某地。"},{"en":"A technology company may be based in Singapore but serve customers worldwide.","zh":"一間科技公司可能總部設於新加坡，但服務全球顧客。"},{"en":"If a charity is based in one city, its staff may still travel to other regions.","zh":"如果慈善機構總部設於一個城市，其員工仍可能前往其他地區。"},{"en":"The phrase describes location of operations, not personal birthplace.","zh":"這個短語描述營運地點，而不是個人出生地。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":20},{"front":"forensic scientists","meaning":"法證科學家","examples":[{"en":"The IAI is an organisation of forensic scientists from around the world.","zh":"IAI 是一個由來自世界各地法證科學家組成的組織。"},{"en":"Forensic scientists use scientific methods to examine evidence for legal investigations.","zh":"forensic scientists 使用科學方法檢查法律調查中的證據。"},{"en":"Forensic scientists may analyse fingerprints, DNA, blood patterns, or digital evidence.","zh":"法證科學家可能分析指紋、DNA、血跡模式或數碼證據。"},{"en":"Their work can help courts decide whether evidence supports a case.","zh":"他們的工作可以幫助法庭判斷證據是否支持案件。"},{"en":"The phrase refers to scientists working at the boundary of science and law.","zh":"這個短語指在科學與法律交界工作的科學家。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":20},{"front":"from around the world","meaning":"來自世界各地","examples":[{"en":"The organisation includes forensic scientists from around the world.","zh":"該組織包括來自世界各地的法證科學家。"},{"en":"From around the world means from many different countries or regions.","zh":"from around the world 指來自許多不同國家或地區。"},{"en":"Students from around the world may join an online English course.","zh":"來自世界各地的學生可能參加網上英語課程。"},{"en":"A conference with experts from around the world can share many viewpoints.","zh":"有來自世界各地專家的會議可以分享許多觀點。"},{"en":"The phrase emphasises international range.","zh":"這個短語強調國際範圍。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":20},{"front":"publish a journal","meaning":"出版期刊","examples":[{"en":"The IAI publishes the Journal of Forensic Identification.","zh":"IAI 出版《法證鑑定期刊》。"},{"en":"To publish a journal means to produce and distribute a regular academic or professional publication.","zh":"publish a journal 指製作並發行定期的學術或專業刊物。"},{"en":"A university department may publish a journal for research articles.","zh":"大學學系可能出版期刊刊登研究文章。"},{"en":"Publishing a journal helps professionals share findings and methods.","zh":"出版期刊幫助專業人士分享發現和方法。"},{"en":"The phrase refers to formal publication, not casual social media posting.","zh":"這個短語指正式出版，而不是隨意在社交媒體發帖。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":20},{"front":"forensic identification","meaning":"法證鑑定","examples":[{"en":"The journal focuses on forensic identification.","zh":"該期刊集中於法證鑑定。"},{"en":"Forensic identification is the use of scientific evidence to identify people, objects, or traces in legal cases.","zh":"forensic identification 指使用科學證據在法律案件中識別人物、物件或痕跡。"},{"en":"Fingerprints and DNA can be used in forensic identification.","zh":"指紋和 DNA 可以用於法證鑑定。"},{"en":"Accurate forensic identification can connect evidence to the right person or scene.","zh":"準確的法證鑑定可以把證據連繫到正確的人或現場。"},{"en":"The phrase is technical and linked to crime investigation and law.","zh":"這個短語較技術性，與罪案調查和法律有關。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":20},{"front":"reading passage","meaning":"閱讀篇章","examples":[{"en":"Reading Passage 2 has eleven paragraphs.","zh":"閱讀篇章二有十一段。"},{"en":"A reading passage is a text used for reading practice or examination questions.","zh":"reading passage 指用於閱讀練習或考試題目的文本。"},{"en":"Students should skim a reading passage before answering detailed questions.","zh":"學生在回答細節題前應快速瀏覽閱讀篇章。"},{"en":"Understanding the structure of a reading passage can make answers easier to locate.","zh":"理解閱讀篇章的結構可以令答案較容易定位。"},{"en":"The phrase is common in IELTS and other reading tests.","zh":"這個短語常見於 IELTS 和其他閱讀測驗。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":20},{"front":"contain the following information","meaning":"包含以下資料","examples":[{"en":"Students identify which paragraph contains the following information.","zh":"學生辨認哪一段包含以下資料。"},{"en":"To contain the following information means to include the details listed after the instruction.","zh":"contain the following information 指包括指示後列出的細節。"},{"en":"A paragraph may contain the following information even if it uses different words.","zh":"即使用字不同，某一段也可能包含以下資料。"},{"en":"Students must scan the text carefully to find where it contains the following information.","zh":"學生必須仔細掃讀文本，找出哪裡包含以下資料。"},{"en":"The phrase is a reading-test instruction about locating details.","zh":"這個短語是關於定位細節的閱讀測驗指示。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":20},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Students write the correct letter in the answer box.","zh":"學生在答案框中寫上正確字母。"},{"en":"To write the correct letter means to put the chosen option letter, such as A or B, in the answer space.","zh":"write the correct letter 指在答案位置寫上所選選項字母，例如 A 或 B。"},{"en":"If paragraph C contains the answer, students should write the correct letter C.","zh":"如果 C 段包含答案，學生應寫上正確字母 C。"},{"en":"Writing the wrong letter can make an answer incorrect even if the idea is understood.","zh":"即使明白意思，寫錯字母也會令答案錯誤。"},{"en":"The phrase is about answer format, not writing a full sentence.","zh":"這個短語關於答案格式，而不是寫完整句子。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":20},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Answers should be written on the answer sheet.","zh":"答案應寫在答題紙上。"},{"en":"On your answer sheet means in the official place where exam answers must be recorded.","zh":"on your answer sheet 指在考試答案必須記錄的官方位置。"},{"en":"Students may mark ideas on the question paper but must copy final answers on their answer sheet.","zh":"學生可以在試題紙上標記想法，但必須把最終答案抄在答題紙上。"},{"en":"If an answer is not on the answer sheet, it may not be marked.","zh":"如果答案不在答題紙上，它可能不會被評分。"},{"en":"The phrase reminds test takers where the final answer belongs.","zh":"這個短語提醒考生最終答案應寫在哪裡。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":20},{"front":"may use any letter more than once","meaning":"可以多次使用任何字母","examples":[{"en":"Students may use any letter more than once.","zh":"學生可以多次使用任何字母。"},{"en":"May use any letter more than once means the same option can be chosen for multiple answers.","zh":"may use any letter more than once 指同一選項可以用於多個答案。"},{"en":"In paragraph-matching questions, students may use any letter more than once if one paragraph contains several details.","zh":"在段落配對題中，如果一段包含多個細節，學生可以多次使用任何字母。"},{"en":"This instruction prevents students from rejecting an answer just because they used that letter already.","zh":"這個指示避免學生只因已用過某字母就排除答案。"},{"en":"The phrase is important in matching tasks.","zh":"這個短語在配對題中很重要。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":20},{"front":"research conducted in","meaning":"在……進行的研究","examples":[{"en":"The question asks about research conducted in Ohio.","zh":"題目問及在俄亥俄州進行的研究。"},{"en":"Research conducted in a place means research carried out or done there.","zh":"research conducted in a place 指在某地進行或完成的研究。"},{"en":"Research conducted in schools may require permission from parents and teachers.","zh":"在學校進行的研究可能需要家長和老師批准。"},{"en":"The location of research conducted in a city can affect the type of data collected.","zh":"在某城市進行的研究地點可以影響收集到的數據類型。"},{"en":"The phrase is formal and common in academic writing.","zh":"這個短語較正式，常見於學術寫作。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":21},{"front":"medical contributions","meaning":"醫學貢獻","examples":[{"en":"The passage discusses medical contributions made by twin research.","zh":"文章討論雙胞胎研究作出的醫學貢獻。"},{"en":"Medical contributions are useful findings, methods, or benefits that help medicine or healthcare.","zh":"medical contributions 指幫助醫學或醫療的有用發現、方法或好處。"},{"en":"Vaccines are major medical contributions because they prevent serious disease.","zh":"疫苗是重大醫學貢獻，因為它們預防嚴重疾病。"},{"en":"Twin research can make medical contributions by showing how genes affect illness.","zh":"雙胞胎研究可以透過顯示基因如何影響疾病而作出醫學貢獻。"},{"en":"The phrase focuses on practical value for health.","zh":"這個短語重點是對健康的實際價值。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":21},{"front":"under life-threatening conditions","meaning":"在危及生命的情況下","examples":[{"en":"Some research was conducted under life-threatening conditions.","zh":"一些研究是在危及生命的情況下進行的。"},{"en":"Under life-threatening conditions means in situations where people may die or suffer extreme danger.","zh":"under life-threatening conditions 指在可能令人死亡或面對極端危險的情況中。"},{"en":"Rescue workers operate under life-threatening conditions during major disasters.","zh":"救援人員在重大災難期間於危及生命的情況下工作。"},{"en":"Research under life-threatening conditions raises serious ethical concerns.","zh":"在危及生命的情況下進行研究會引起嚴重倫理關注。"},{"en":"The phrase signals extreme danger, not ordinary difficulty.","zh":"這個短語表示極端危險，而不是普通困難。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":21},{"front":"similarities between identical twins","meaning":"同卵雙胞胎之間的相似之處","examples":[{"en":"The passage gives data on similarities between identical twins.","zh":"文章提供同卵雙胞胎之間相似之處的數據。"},{"en":"Similarities between identical twins are shared features, behaviours, or responses in twins from one egg.","zh":"similarities between identical twins 指由一個卵子發育而成的雙胞胎共有的特徵、行為或反應。"},{"en":"Similarities between identical twins may include appearance, taste reaction, or disease risk.","zh":"同卵雙胞胎之間的相似之處可能包括外表、味覺反應或患病風險。"},{"en":"Strong similarities between identical twins can suggest genetic influence.","zh":"同卵雙胞胎之間強烈的相似之處可以暗示遺傳影響。"},{"en":"The phrase focuses on what is alike, not what is different.","zh":"這個短語重點是相同之處，而不是不同之處。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":21},{"front":"reasons why","meaning":"……的原因","examples":[{"en":"The question asks for reasons why one study was unconvincing.","zh":"題目要求說明某項研究不能令人信服的原因。"},{"en":"Reasons why are explanations for why something happened or why people judge it in a certain way.","zh":"reasons why 指解釋某事為何發生或人們為何作出某種判斷的原因。"},{"en":"A teacher may ask for reasons why a student chose a particular answer.","zh":"老師可能要求學生說明選擇某答案的原因。"},{"en":"Giving clear reasons why a plan failed helps people improve it.","zh":"清楚說明計劃失敗的原因，有助人們改善它。"},{"en":"The phrase introduces causes or explanations.","zh":"這個短語引入原因或解釋。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":21},{"front":"be unconvincing","meaning":"不能令人信服","examples":[{"en":"Burt’s study was unconvincing because some data were probably faked.","zh":"Burt 的研究不能令人信服，因為一些數據很可能造假。"},{"en":"To be unconvincing means not to make people believe something is true or reliable.","zh":"be unconvincing 指不能令人相信某事真實或可靠。"},{"en":"An excuse is unconvincing if the details keep changing.","zh":"如果藉口的細節不斷改變，它就不能令人信服。"},{"en":"Research becomes unconvincing when evidence is weak or data are suspicious.","zh":"當證據薄弱或數據可疑，研究就不能令人信服。"},{"en":"The phrase means doubtful, not necessarily completely false.","zh":"這個短語表示可疑，而不一定完全錯誤。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":21},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"To complete the summary below means to fill missing words in a short summary.","zh":"complete the summary below 指填補一段簡短摘要中的空缺字詞。"},{"en":"In IELTS reading, students complete the summary below by choosing exact words from the text.","zh":"在 IELTS 閱讀中，學生透過從文本選擇準確字詞來完成以下摘要。"},{"en":"A wrong word form can make an answer incorrect when completing the summary below.","zh":"完成以下摘要時，錯誤詞形可能令答案錯誤。"},{"en":"The phrase is an exam instruction, not a content word from the passage.","zh":"這個短語是考試指示，而不是篇章內容詞。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":21},{"front":"no more than two words","meaning":"不多於兩個字","examples":[{"en":"The answer should use no more than two words from the passage.","zh":"答案應使用文章中不多於兩個字。"},{"en":"No more than two words means one or two words, but not three.","zh":"no more than two words 指一個或兩個詞，但不能三個。"},{"en":"If the instruction says no more than two words, “genetic factors” is allowed but three words are not.","zh":"如果指示說不多於兩個詞，genetic factors 可以，但三個詞不可以。"},{"en":"Students must count words carefully to avoid losing marks.","zh":"學生必須仔細數詞數，以免失分。"},{"en":"The phrase sets a strict limit on answer length.","zh":"這個短語設定嚴格的答案長度限制。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":21},{"front":"conduct research on","meaning":"對……進行研究","examples":[{"en":"Francis Galton conducted early research on twins.","zh":"Francis Galton 對雙胞胎進行早期研究。"},{"en":"To conduct research on something means to carry out a careful study of it.","zh":"conduct research on something 指對某事進行仔細研究。"},{"en":"A university may conduct research on student stress during exam periods.","zh":"大學可能對考試期間學生壓力進行研究。"},{"en":"Researchers conduct research on a topic by collecting data, analysing results, and writing conclusions.","zh":"研究人員透過收集數據、分析結果和撰寫結論來對某主題進行研究。"},{"en":"The phrase is formal and common in academic English.","zh":"這個短語較正式，常見於學術英語。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":21},{"front":"divide something into categories","meaning":"把……分成不同類別","examples":[{"en":"Galton divided twins into identical and non-identical categories.","zh":"Galton 把雙胞胎分成同卵和異卵類別。"},{"en":"To divide something into categories means to sort it into groups based on shared features.","zh":"divide something into categories 指根據共同特徵把某物分類。"},{"en":"A teacher may divide vocabulary into categories such as food, transport, and health.","zh":"老師可能把詞彙分成食物、交通和健康等類別。"},{"en":"Dividing data into categories helps researchers compare groups more clearly.","zh":"把數據分成不同類別，有助研究人員更清楚比較群組。"},{"en":"The phrase is useful when organising information.","zh":"這個短語在組織資訊時很有用。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":21},{"front":"be first applied in medicine","meaning":"首次應用於醫學","examples":[{"en":"Twin research was first applied in medicine through the twin rule of pathology.","zh":"雙胞胎研究透過雙胞胎病理規則首次應用於醫學。"},{"en":"To be first applied in medicine means to be used in medical study or practice before other areas.","zh":"be first applied in medicine 指先於其他領域用於醫學研究或實踐。"},{"en":"A new scanning method may be first applied in medicine before being used in sports science.","zh":"新掃描方法可能先首次應用於醫學，然後才用於運動科學。"},{"en":"When an idea is first applied in medicine, doctors test whether it helps understand disease or treatment.","zh":"當一個想法首次應用於醫學，醫生會測試它是否有助理解疾病或治療。"},{"en":"The phrase focuses on the earliest practical use in a medical context.","zh":"這個短語重點是在醫學語境中的最早實際用途。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":21},{"front":"choose three letters","meaning":"選出三個字母","examples":[{"en":"Students choose three letters from the answer options.","zh":"學生從答案選項中選出三個字母。"},{"en":"Choose three letters means select three option letters, such as A, C, and F.","zh":"choose three letters 指選擇三個選項字母，例如 A、C 和 F。"},{"en":"If the instruction says choose three letters, giving only two answers is incomplete.","zh":"如果指示說選出三個字母，只給兩個答案就是不完整。"},{"en":"Students should check whether the three letters all match information in the passage.","zh":"學生應檢查三個字母是否都符合文章資料。"},{"en":"The phrase is an exam instruction about answer format.","zh":"這個短語是關於答案格式的考試指示。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":22},{"front":"research fields","meaning":"研究領域","examples":[{"en":"The question asks which research fields were investigated.","zh":"題目問哪些研究領域被調查。"},{"en":"Research fields are areas or subjects that researchers study.","zh":"research fields 指研究人員研究的範圍或主題。"},{"en":"Medicine, psychology, education, and forensic science are research fields.","zh":"醫學、心理學、教育和法證科學都是研究領域。"},{"en":"A festival with many volunteers can attract several research fields at once.","zh":"有很多志願者的節日可以同時吸引幾個研究領域。"},{"en":"The phrase helps group studies by topic.","zh":"這個短語幫助按主題分類研究。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":22},{"front":"be investigated","meaning":"被研究；被調查","examples":[{"en":"Several research fields were investigated at the festival.","zh":"幾個研究領域在節日中被研究。"},{"en":"To be investigated means to be studied, examined, or looked into carefully.","zh":"be investigated 指被仔細研究、檢查或調查。"},{"en":"A complaint may be investigated by school staff before action is taken.","zh":"投訴在採取行動前可能由學校職員調查。"},{"en":"A disease pattern is investigated when doctors collect data from many patients.","zh":"當醫生從許多病人收集數據時，疾病模式就被研究。"},{"en":"The phrase can be used in science, police work, and administration.","zh":"這個短語可用於科學、警務和行政工作。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":22},{"front":"sensory perception","meaning":"感官感知","examples":[{"en":"Researchers investigated sensory perception in Twinsburg.","zh":"研究人員在 Twinsburg 調查感官感知。"},{"en":"Sensory perception is how people experience information through senses such as sight, hearing, taste, smell, and touch.","zh":"sensory perception 指人們透過視覺、聽覺、味覺、嗅覺和觸覺等感官體驗資訊的方式。"},{"en":"Sensory perception explains why one person finds a sound pleasant and another finds it irritating.","zh":"感官感知解釋為何一個人覺得某聲音悅耳，另一個人卻覺得刺耳。"},{"en":"Studying sensory perception can help scientists understand taste, pain, hearing, and smell.","zh":"研究感官感知可以幫助科學家理解味覺、疼痛、聽覺和嗅覺。"},{"en":"The phrase focuses on sensing and interpreting the world.","zh":"這個短語重點是感受和理解世界。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":22},{"front":"mole heredity","meaning":"痣的遺傳性","examples":[{"en":"Early twin studies examined mole heredity.","zh":"早期雙胞胎研究檢視痣的遺傳性。"},{"en":"Mole heredity means the extent to which skin moles are influenced by genes.","zh":"mole heredity 指皮膚痣在多大程度上受基因影響。"},{"en":"Researchers study mole heredity by comparing mole counts in relatives or twins.","zh":"研究人員透過比較親屬或雙胞胎的痣數量來研究痣的遺傳性。"},{"en":"If identical twins have similar mole numbers, mole heredity may be important.","zh":"如果同卵雙胞胎有相似痣數量，痣的遺傳性可能很重要。"},{"en":"The phrase combines a visible skin feature with genetic influence.","zh":"這個短語把可見皮膚特徵與遺傳影響連起來。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":22},{"front":"male baldness","meaning":"男性脫髮","examples":[{"en":"Researchers studied male baldness in relation to genes.","zh":"研究人員研究男性脫髮與基因的關係。"},{"en":"Male baldness means hair loss in men, especially on the hairline or top of the head.","zh":"male baldness 指男性脫髮，尤其是髮線或頭頂位置。"},{"en":"Male baldness may begin gradually as hair becomes thinner.","zh":"男性脫髮可能隨着頭髮變薄而逐漸開始。"},{"en":"Studying male baldness can help scientists understand genetic effects on hair growth.","zh":"研究男性脫髮可以幫助科學家理解基因對頭髮生長的影響。"},{"en":"The phrase is less technical than male-pattern baldness.","zh":"這個短語比 male-pattern baldness 較不技術性。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":22},{"front":"findings are supported by","meaning":"得到篇章支持的發現","examples":[{"en":"The question asks which findings are supported by the passage.","zh":"題目問哪些發現得到篇章支持。"},{"en":"If findings are supported by a text, the text gives evidence for them.","zh":"如果 findings are supported by a text，意思是文本提供證據支持那些發現。"},{"en":"A student should choose only answers whose findings are supported by the passage.","zh":"學生只應選擇其發現得到篇章支持的答案。"},{"en":"If a claim is not supported by evidence, it may be wrong or not given.","zh":"如果某聲稱沒有證據支持，它可能是錯誤或未提及。"},{"en":"The phrase is common in reading comprehension questions.","zh":"這個短語常見於閱讀理解題。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":22},{"front":"develop from different eggs","meaning":"由不同卵子發育而成","examples":[{"en":"Non-identical twins develop from different eggs.","zh":"異卵雙胞胎由不同卵子發育而成。"},{"en":"To develop from different eggs means each baby begins from a separate fertilised egg.","zh":"develop from different eggs 指每個嬰兒由不同受精卵開始發育。"},{"en":"Twins who develop from different eggs can look as different as ordinary siblings.","zh":"由不同卵子發育而成的雙胞胎可以像普通兄弟姊妹一樣不同。"},{"en":"Because they develop from different eggs, non-identical twins do not share all their genes.","zh":"因為他們由不同卵子發育而成，異卵雙胞胎不共享全部基因。"},{"en":"The phrase explains the biological basis of non-identical twins.","zh":"這個短語解釋異卵雙胞胎的生物基礎。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":22},{"front":"be more closely related genetically","meaning":"在遺傳上關係更接近","examples":[{"en":"Identical twins are more closely related genetically than non-identical twins.","zh":"同卵雙胞胎在遺傳上比異卵雙胞胎關係更接近。"},{"en":"To be more closely related genetically means to share more of the same genes.","zh":"be more closely related genetically 指共享更多相同基因。"},{"en":"Brothers are more closely related genetically than distant cousins.","zh":"兄弟在遺傳上比遠親關係更接近。"},{"en":"Because identical twins are more closely related genetically, their similarities can reveal genetic influence.","zh":"由於同卵雙胞胎在遺傳上關係更接近，他們的相似性可以揭示遺傳影響。"},{"en":"The phrase compares biological relatedness, not emotional closeness.","zh":"這個短語比較生物關係，而不是情感親近。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":22},{"front":"have a clear effect on","meaning":"對……有明顯作用","examples":[{"en":"The passage does not suggest that vitamin C has a clear effect on colds.","zh":"文章沒有顯示維他命 C 對感冒有明顯作用。"},{"en":"To have a clear effect on something means to change it in an obvious and measurable way.","zh":"have a clear effect on something 指以明顯且可量度的方式改變某事。"},{"en":"Regular sleep can have a clear effect on a student’s concentration.","zh":"定期睡眠可以對學生專注力有明顯作用。"},{"en":"If a medicine has a clear effect on symptoms, patients should feel noticeable improvement.","zh":"如果藥物對症狀有明顯作用，病人應感到明顯改善。"},{"en":"The phrase is stronger than may help because it suggests visible evidence.","zh":"這個短語比 may help 更強，因為它暗示有可見證據。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":22},{"front":"genetic influence on","meaning":"對……的遺傳影響","examples":[{"en":"The question refers to genetic influence on smoking behaviour.","zh":"題目提到對吸煙行為的遺傳影響。"},{"en":"Genetic influence on something means the effect genes may have on it.","zh":"genetic influence on something 指基因可能對某事產生的影響。"},{"en":"Researchers may study genetic influence on taste, height, or disease risk.","zh":"研究人員可能研究對味覺、身高或患病風險的遺傳影響。"},{"en":"Genetic influence on behaviour does not remove personal choice or environmental effects.","zh":"對行為的遺傳影響並不排除個人選擇或環境影響。"},{"en":"The phrase is useful when discussing how biology contributes to differences.","zh":"這個短語適合討論生物因素如何造成差異。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":22},{"front":"environmental influence","meaning":"環境影響","examples":[{"en":"Environmental influence affects whether someone starts smoking.","zh":"環境影響會影響某人是否開始吸煙。"},{"en":"Environmental influence is the effect of surroundings, experience, culture, or social conditions.","zh":"environmental influence 指周圍環境、經驗、文化或社會條件的影響。"},{"en":"Friends can have an environmental influence on a teenager’s study habits.","zh":"朋友可以對青少年的學習習慣產生環境影響。"},{"en":"A safe home environment can have a positive influence on a child’s development.","zh":"安全的家庭環境可以對孩子發展有正面影響。"},{"en":"The phrase contrasts with genetic influence.","zh":"這個短語與遺傳影響形成對比。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":23},{"front":"during pregnancy","meaning":"在懷孕期間","examples":[{"en":"The option mentions habits during pregnancy.","zh":"選項提到在懷孕期間的習慣。"},{"en":"During pregnancy means in the period when a woman is carrying a developing baby.","zh":"during pregnancy 指女性懷着發育中嬰兒的時期。"},{"en":"Doctors often give advice about diet and rest during pregnancy.","zh":"醫生常在懷孕期間提供飲食和休息建議。"},{"en":"Exposure to some substances during pregnancy may affect early development.","zh":"在懷孕期間接觸某些物質可能影響早期發展。"},{"en":"The phrase gives a time period before birth.","zh":"這個短語提供出生前的時間段。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":23},{"front":"lead to skin disease","meaning":"導致皮膚病","examples":[{"en":"The option claims that eating too many sweets may lead to skin disease.","zh":"選項聲稱吃太多甜食可能導致皮膚病。"},{"en":"To lead to skin disease means to cause or contribute to a medical problem affecting the skin.","zh":"lead to skin disease 指造成或促成影響皮膚的醫療問題。"},{"en":"Poor hygiene may lead to skin disease if bacteria spread easily.","zh":"如果細菌容易傳播，衛生欠佳可能導致皮膚病。"},{"en":"A claim that one food will lead to skin disease needs evidence before it is accepted.","zh":"聲稱某種食物會導致皮膚病，需要有證據才可接受。"},{"en":"The phrase shows cause and result, so it must be used carefully.","zh":"這個短語顯示原因和結果，因此必須謹慎使用。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":23},{"front":"be connected with","meaning":"與……有關","examples":[{"en":"The option asks whether hair loss is connected with a skin condition.","zh":"選項問脫髮是否與皮膚狀況有關。"},{"en":"To be connected with something means to have a relationship or link with it.","zh":"be connected with something 指與某事有關係或連繫。"},{"en":"Poor sleep can be connected with lower concentration in class.","zh":"睡眠不足可能與課堂專注力較低有關。"},{"en":"Hair loss may be connected with health, age, stress, or genetics.","zh":"脫髮可能與健康、年齡、壓力或基因有關。"},{"en":"The phrase suggests a link, but not always direct cause.","zh":"這個短語暗示有關連，但不一定是直接原因。"}],"source":"144 - Twin Study - Two of a kind.pdf","sourcePage":23}],"ielts/reading/passage-2/Practice 145":[{"front":"food for thought","meaning":"值得深思的事","examples":[{"en":"The passage gives readers food for thought about nutrition and education.","zh":"這篇文章給讀者一些關於營養與教育的值得深思的事。"},{"en":"Food for thought means an idea or issue that makes people think carefully.","zh":"food for thought 指令人仔細思考的想法或議題。"},{"en":"A teacher’s question about fairness can give students food for thought after class.","zh":"老師關於公平的問題，可以在課後給學生一些值得深思的事。"},{"en":"A documentary about poverty gives viewers food for thought because it shows problems they may ignore.","zh":"關於貧窮的紀錄片給觀眾值得深思的事，因為它展示人們可能忽視的問題。"},{"en":"The phrase is used when something is not just interesting, but worth serious reflection.","zh":"這個短語用於某事不只是有趣，而是值得認真反思時。"}],"source":"145 - Food for thought.pdf","sourcePage":1},{"front":"not enough classrooms","meaning":"課室不足","examples":[{"en":"There are not enough classrooms at Msekeni primary school.","zh":"Msekeni小學課室不足。"},{"en":"Not enough classrooms means the school has fewer teaching rooms than it needs.","zh":"not enough classrooms 指學校的教學房間少於所需數量。"},{"en":"If there are not enough classrooms, some students may have lessons in the hall or outdoors.","zh":"如果課室不足，一些學生可能要在禮堂或戶外上課。"},{"en":"A growing town may face not enough classrooms when many new families move in.","zh":"當許多新家庭搬入，一個成長中的城鎮可能面對課室不足。"},{"en":"The phrase describes a shortage of learning space, not a shortage of teachers.","zh":"這個短語描述學習空間短缺，而不是教師短缺。"}],"source":"145 - Food for thought.pdf","sourcePage":1},{"front":"take place in the shade of","meaning":"在……的樹蔭下進行","examples":[{"en":"Half the lessons take place in the shade of acacia trees.","zh":"一半課堂在金合歡樹的樹蔭下進行。"},{"en":"To take place in the shade of something means to happen under it, where it blocks direct sunlight.","zh":"take place in the shade of 某物，意思是在它下面、陽光被遮擋的地方發生。"},{"en":"The picnic took place in the shade of a large tree because the afternoon was very hot.","zh":"因為下午很熱，野餐在一棵大樹的樹蔭下進行。"},{"en":"If a meeting takes place in the shade of a building, people can avoid strong sun.","zh":"如果會議在建築物陰影下進行，人們可以避開猛烈陽光。"},{"en":"The phrase usually describes an outdoor activity protected from sunlight.","zh":"這個短語通常描述受陽光遮蔽的戶外活動。"}],"source":"145 - Food for thought.pdf","sourcePage":1},{"front":"yellow-blossomed acacia trees","meaning":"開黃花的金合歡樹","examples":[{"en":"The children study under yellow-blossomed acacia trees.","zh":"孩子們在開黃花的金合歡樹下學習。"},{"en":"Yellow-blossomed acacia trees are acacia trees with yellow flowers.","zh":"yellow-blossomed acacia trees 是開着黃色花朵的金合歡樹。"},{"en":"A village path may look beautiful when yellow-blossomed acacia trees line both sides.","zh":"當道路兩旁排列着開黃花的金合歡樹，鄉村小路可能看起來很美。"},{"en":"If children study under yellow-blossomed acacia trees, the trees provide shade as well as colour.","zh":"如果孩子在開黃花的金合歡樹下學習，樹木既提供樹蔭，也帶來色彩。"},{"en":"The phrase gives a clear visual image of the place, not just the type of tree.","zh":"這個短語提供清晰的地方畫面，而不只是說明樹的種類。"}],"source":"145 - Food for thought.pdf","sourcePage":1},{"front":"given this shortage","meaning":"鑑於這種短缺","examples":[{"en":"Given this shortage, the use of one classroom as a storeroom may seem odd.","zh":"鑑於這種短缺，把其中一間課室用作儲物室可能看起來很奇怪。"},{"en":"Given this shortage means considering that there is not enough of something.","zh":"given this shortage 指考慮到某物不足。"},{"en":"Given this shortage of nurses, closing a training school would seem unwise.","zh":"鑑於護士短缺，關閉一間訓練學校看起來並不明智。"},{"en":"Given this shortage of buses, the company should repair broken vehicles quickly.","zh":"鑑於巴士短缺，公司應該迅速維修壞車。"},{"en":"The phrase introduces a fact that makes the next situation surprising or important.","zh":"這個短語引出一個事實，使接下來的情況顯得令人意外或重要。"}],"source":"145 - Food for thought.pdf","sourcePage":1},{"front":"it might seem odd that","meaning":"……看起來可能很奇怪","examples":[{"en":"It might seem odd that a classroom has been turned into a storeroom.","zh":"一間課室被改成儲物室，這看起來可能很奇怪。"},{"en":"It might seem odd that means something may appear strange or unexpected at first.","zh":"it might seem odd that 指某事起初可能看起來奇怪或出乎意料。"},{"en":"It might seem odd that a library closes early during exam season.","zh":"圖書館在考試季節提早關門，這看起來可能很奇怪。"},{"en":"It might seem odd that a poor school uses a classroom for food, but food may keep pupils attending.","zh":"一間貧困學校用課室存放食物，這看起來可能很奇怪，但食物可能令學生繼續上學。"},{"en":"The phrase often introduces a situation that needs further explanation.","zh":"這個短語常用來引出需要進一步解釋的情況。"}],"source":"145 - Food for thought.pdf","sourcePage":1},{"front":"purpose-built classrooms","meaning":"專門建造的課室","examples":[{"en":"One of the school’s purpose-built classrooms is used for food storage.","zh":"學校其中一間專門建造的課室被用作存放食物。"},{"en":"Purpose-built classrooms are rooms specially designed and built for teaching.","zh":"purpose-built classrooms 是特別為教學而設計和建造的課室。"},{"en":"A science school may have purpose-built classrooms with sinks, benches, and safety equipment.","zh":"科學學校可能有配備水槽、實驗枱和安全設備的專門建造課室。"},{"en":"If purpose-built classrooms are used for storage, students lose space made for learning.","zh":"如果專門建造的課室被用作儲物，學生會失去原本用於學習的空間。"},{"en":"The phrase shows that the room was not originally meant for a different use.","zh":"這個短語顯示房間原本不是為其他用途而設。"}],"source":"145 - Food for thought.pdf","sourcePage":1},{"front":"be emptied of","meaning":"被清空……","examples":[{"en":"The classroom has been emptied of pupils.","zh":"課室已被清空學生。"},{"en":"To be emptied of people or things means to have them removed until none or very few remain.","zh":"be emptied of 人或物，意思是它們被移走，直到沒有或只剩很少。"},{"en":"The hall was emptied of chairs before the sports lesson began.","zh":"體育課開始前，禮堂裏的椅子被清空。"},{"en":"If a room is emptied of students, it can be used for another purpose.","zh":"如果房間被清空學生，它就可以用於其他用途。"},{"en":"The phrase focuses on what has been taken out of a place.","zh":"這個短語重點在於某個地方被移走了甚麼。"}],"source":"145 - Food for thought.pdf","sourcePage":1},{"front":"be turned into","meaning":"被改成","examples":[{"en":"The classroom has been turned into a storeroom.","zh":"課室已被改成儲物室。"},{"en":"To be turned into something means to be changed into a different form, place, or use.","zh":"be turned into 某物，意思是被改變成另一種形式、地方或用途。"},{"en":"An old factory can be turned into an art centre.","zh":"舊工廠可以被改成藝術中心。"},{"en":"If a bedroom is turned into an office, the family gains work space but loses sleeping space.","zh":"如果睡房被改成辦公室，家庭會得到工作空間，但失去睡眠空間。"},{"en":"The phrase describes a clear change from one purpose to another.","zh":"這個短語描述從一種用途到另一種用途的明顯改變。"}],"source":"145 - Food for thought.pdf","sourcePage":1},{"front":"a storeroom for","meaning":"……的儲物室","examples":[{"en":"The classroom has become a storeroom for sacks of grain.","zh":"這間課室已成為一袋袋穀物的儲物室。"},{"en":"A storeroom for something is a room used to keep that thing safely until it is needed.","zh":"a storeroom for 某物，指用來安全存放某物直至需要時使用的房間。"},{"en":"The kitchen has a small storeroom for rice, oil, and cleaning supplies.","zh":"廚房有一個小儲物室，用來存放米、油和清潔用品。"},{"en":"If a school needs a storeroom for food, it must keep the area dry and clean.","zh":"如果學校需要食物儲物室，它必須保持地方乾爽和潔淨。"},{"en":"The phrase tells us what is being stored, not just that the room is for storage.","zh":"這個短語告訴我們存放的是甚麼，而不只是說房間用來儲物。"}],"source":"145 - Food for thought.pdf","sourcePage":1},{"front":"sacks of grain","meaning":"一袋袋穀物","examples":[{"en":"The food programme stores sacks of grain in the classroom.","zh":"供餐計劃把一袋袋穀物存放在課室裏。"},{"en":"Sacks of grain are large bags filled with crops such as maize, rice, wheat, or beans.","zh":"sacks of grain 是裝滿粟米、米、小麥或豆類等農作物的大袋。"},{"en":"Farmers may carry sacks of grain to the market after harvest.","zh":"農民收成後可能把一袋袋穀物搬到市場。"},{"en":"If sacks of grain are stored badly, insects and moisture can damage the food.","zh":"如果一袋袋穀物存放不當，昆蟲和濕氣可能破壞食物。"},{"en":"The phrase suggests a large, practical supply of basic food.","zh":"這個短語暗示大量而實用的基本食物供應。"}],"source":"145 - Food for thought.pdf","sourcePage":1},{"front":"it makes sense","meaning":"這是合理的","examples":[{"en":"Using a classroom for food storage makes sense.","zh":"用課室存放食物是合理的。"},{"en":"It makes sense means it is reasonable, practical, or easy to understand.","zh":"it makes sense 指某事合理、實際或容易理解。"},{"en":"It makes sense to carry an umbrella if the sky is dark.","zh":"如果天色昏暗，帶雨傘是合理的。"},{"en":"If food keeps children in school, using space to store it makes sense.","zh":"如果食物能令孩子留在學校，用空間存放食物就是合理的。"},{"en":"The phrase is often used to explain why a strange-looking choice is actually reasonable.","zh":"這個短語常用來解釋為何看似奇怪的選擇其實合理。"}],"source":"145 - Food for thought.pdf","sourcePage":2},{"front":"food matters more than shelter","meaning":"食物比遮蔽處更重要","examples":[{"en":"At Msekeni, food matters more than shelter.","zh":"在Msekeni，食物比遮蔽處更重要。"},{"en":"Food matters more than shelter means eating is more urgent than having a protected place to sit or learn.","zh":"food matters more than shelter 指進食比有受保護的地方坐下或學習更迫切。"},{"en":"In a disaster, food may matter more than shelter during the first few hours.","zh":"在災難中，最初幾小時食物可能比遮蔽處更重要。"},{"en":"If hungry children cannot concentrate, food may matter more than a proper classroom.","zh":"如果飢餓的孩子不能集中精神，食物可能比正式課室更重要。"},{"en":"The phrase compares two needs and says one is more important in that situation.","zh":"這個短語比較兩種需要，並指出在該情況下其中一種更重要。"}],"source":"145 - Food for thought.pdf","sourcePage":2},{"front":"one of the poorer parts of","meaning":"……較貧困的地區之一","examples":[{"en":"Msekeni is in one of the poorer parts of Malawi.","zh":"Msekeni位於馬拉維較貧困的地區之一。"},{"en":"One of the poorer parts of a place means an area where people generally have less money and fewer resources.","zh":"one of the poorer parts of 某地，指當地一個人們普遍較少金錢和資源的地區。"},{"en":"A charity may open a clinic in one of the poorer parts of the city.","zh":"慈善機構可能在城市較貧困的地區之一開設診所。"},{"en":"If a school is in one of the poorer parts of a country, families may struggle to buy books.","zh":"如果學校位於國家較貧困的地區之一，家庭可能難以購買書本。"},{"en":"The phrase compares areas within the same country, city, or region.","zh":"這個短語比較同一國家、城市或地區內的不同地方。"}],"source":"145 - Food for thought.pdf","sourcePage":2},{"front":"landlocked","meaning":"內陸的","examples":[{"en":"Malawi is a landlocked southern African country.","zh":"馬拉維是一個內陸的南部非洲國家。"},{"en":"Landlocked means surrounded by land, with no direct coastline or access to the sea.","zh":"landlocked 指被陸地包圍，沒有直接海岸線或出海口。"},{"en":"A landlocked country may depend on neighbouring countries for sea trade.","zh":"內陸國家可能依賴鄰國進行海上貿易。"},{"en":"If a place is landlocked, imported goods may cost more because they travel farther by road.","zh":"如果一個地方是內陸的，進口貨品可能因為要經更長陸路運輸而更昂貴。"},{"en":"The word describes geography, not poverty or political status.","zh":"這個字描述地理位置，而不是貧窮或政治地位。"}],"source":"145 - Food for thought.pdf","sourcePage":2},{"front":"southern African country","meaning":"南部非洲國家","examples":[{"en":"Malawi is a southern African country of great poverty and beauty.","zh":"馬拉維是一個兼有極度貧困和美景的南部非洲國家。"},{"en":"A southern African country is a country located in the southern part of Africa.","zh":"southern African country 指位於非洲南部的國家。"},{"en":"Botswana is a southern African country known for wildlife and open landscapes.","zh":"博茨瓦納是一個以野生動物和開闊景觀聞名的南部非洲國家。"},{"en":"If students study a southern African country, they should look at its geography, history, and economy.","zh":"如果學生研究一個南部非洲國家，應該了解其地理、歷史和經濟。"},{"en":"The phrase identifies a country by region within Africa.","zh":"這個短語按非洲內部地區指出一個國家。"}],"source":"145 - Food for thought.pdf","sourcePage":2},{"front":"exceptional beauty","meaning":"非凡美景","examples":[{"en":"Malawi is a country of exceptional beauty and great poverty.","zh":"馬拉維是一個兼有非凡美景和極度貧困的國家。"},{"en":"Exceptional beauty means beauty that is unusually great or impressive.","zh":"exceptional beauty 指異常出眾或令人印象深刻的美。"},{"en":"A lake surrounded by mountains may have exceptional beauty at sunset.","zh":"被群山包圍的湖泊在日落時可能有非凡美景。"},{"en":"If a place has exceptional beauty, tourists may visit even when travel is difficult.","zh":"如果一個地方有非凡美景，即使交通困難，遊客也可能到訪。"},{"en":"The phrase gives strong praise and suggests the beauty is not ordinary.","zh":"這個短語帶有高度讚美，暗示美並不普通。"}],"source":"145 - Food for thought.pdf","sourcePage":2},{"front":"great poverty","meaning":"極度貧困","examples":[{"en":"Malawi is known for both exceptional beauty and great poverty.","zh":"馬拉維以非凡美景和極度貧困並存而聞名。"},{"en":"Great poverty means serious poverty, where people lack basic needs such as food, shelter, healthcare, or education.","zh":"great poverty 指嚴重貧困，人們缺乏食物、住所、醫療或教育等基本需要。"},{"en":"Great poverty can force families to choose between school fees and food.","zh":"極度貧困可以迫使家庭在學費和食物之間作選擇。"},{"en":"If a village suffers great poverty, children may work instead of attending school.","zh":"如果村莊承受極度貧困，孩子可能工作而不上學。"},{"en":"The phrase describes deep hardship, not just having little extra money.","zh":"這個短語描述深重困苦，而不只是少了額外金錢。"}],"source":"145 - Food for thought.pdf","sourcePage":2},{"front":"lay waste","meaning":"摧毀；使……荒廢","examples":[{"en":"No war lays waste Malawi.","zh":"沒有戰爭摧毀馬拉維。"},{"en":"To lay waste to a place means to destroy it severely and leave it damaged or ruined.","zh":"lay waste to 某地，意思是嚴重破壞它，使它受損或荒廢。"},{"en":"A powerful storm can lay waste to coastal villages.","zh":"強烈風暴可以摧毀沿海村莊。"},{"en":"If fighting lays waste to farms, people may lose both homes and food.","zh":"如果戰鬥摧毀農田，人們可能同時失去家園和食物。"},{"en":"The phrase is strong and usually describes large-scale destruction.","zh":"這個短語語氣強烈，通常描述大規模破壞。"}],"source":"145 - Food for thought.pdf","sourcePage":2},{"front":"unusually crowded","meaning":"異常擠迫","examples":[{"en":"The land is not unusually crowded.","zh":"這片土地並非異常擠迫。"},{"en":"Unusually crowded means more crowded than normal or expected.","zh":"unusually crowded 指比正常或預期情況更擠迫。"},{"en":"The train was unusually crowded because three earlier trains were cancelled.","zh":"因為前三班火車取消，這班火車異常擠迫。"},{"en":"If a classroom is unusually crowded, teachers may struggle to help every student.","zh":"如果課室異常擠迫，老師可能難以幫助每位學生。"},{"en":"The phrase compares the situation with what is normal.","zh":"這個短語把情況與正常狀態作比較。"}],"source":"145 - Food for thought.pdf","sourcePage":2},{"front":"infertile","meaning":"貧瘠的","examples":[{"en":"The land is not unusually infertile.","zh":"這片土地並非異常貧瘠。"},{"en":"Infertile land cannot easily grow healthy crops because the soil lacks nutrients or suitable conditions.","zh":"infertile land 指土地因缺乏養分或合適條件而難以種出健康作物。"},{"en":"Farmers may add compost to infertile soil to improve it.","zh":"農民可能向貧瘠土壤加入堆肥來改善它。"},{"en":"If land becomes infertile, families may produce less food and earn less money.","zh":"如果土地變得貧瘠，家庭可能生產較少食物並賺較少錢。"},{"en":"The word can describe land that is poor for growing plants.","zh":"這個字可以描述不利植物生長的土地。"}],"source":"145 - Food for thought.pdf","sourcePage":2},{"front":"have trouble finding enough to eat","meaning":"難以找到足夠食物","examples":[{"en":"Many Malawians have trouble finding enough to eat.","zh":"許多馬拉維人難以找到足夠食物。"},{"en":"To have trouble finding enough to eat means to struggle to get enough food for daily needs.","zh":"have trouble finding enough to eat 指難以取得足夠日常所需食物。"},{"en":"A family may have trouble finding enough to eat if food prices rise suddenly.","zh":"如果食物價格突然上升，一個家庭可能難以找到足夠食物。"},{"en":"If people have trouble finding enough to eat, children’s health and learning can suffer.","zh":"如果人們難以找到足夠食物，兒童健康和學習可能受損。"},{"en":"The phrase describes food insecurity in simple, human terms.","zh":"這個短語用簡單而貼近人的方式描述糧食不安全。"}],"source":"145 - Food for thought.pdf","sourcePage":2},{"front":"children under five","meaning":"五歲以下兒童","examples":[{"en":"Half of the children under five are underfed.","zh":"半數五歲以下兒童營養不足。"},{"en":"Children under five are children who are younger than five years old.","zh":"children under five 指未滿五歲的兒童。"},{"en":"Clinics often check the weight and height of children under five.","zh":"診所常檢查五歲以下兒童的體重和身高。"},{"en":"If children under five lack good food, their growth may be affected for life.","zh":"如果五歲以下兒童缺乏良好食物，他們的成長可能終身受影響。"},{"en":"The phrase is common in health reports because early childhood is very important.","zh":"這個短語常見於健康報告，因為幼兒期非常重要。"}],"source":"145 - Food for thought.pdf","sourcePage":3},{"front":"be underfed","meaning":"營養不足；吃不飽","examples":[{"en":"Many children in Malawi are underfed.","zh":"馬拉維許多兒童營養不足。"},{"en":"To be underfed means to receive too little food or not enough nutrients.","zh":"be underfed 指食物太少或營養不足。"},{"en":"A child may be underfed if the family has only one small meal a day.","zh":"如果家庭每天只有一頓小餐，孩子可能吃不飽。"},{"en":"If students are underfed, they may feel tired and find it hard to concentrate.","zh":"如果學生營養不足，他們可能感到疲倦並難以集中精神。"},{"en":"The word describes a serious lack of food, not simply skipping one snack.","zh":"這個字描述嚴重缺乏食物，而不只是少吃一份小食。"}],"source":"145 - Food for thought.pdf","sourcePage":3},{"front":"to the point of","meaning":"到……的程度","examples":[{"en":"Some children are underfed to the point of stunting.","zh":"一些兒童營養不足到發育遲緩的程度。"},{"en":"To the point of something means so much or so severely that a particular result happens.","zh":"to the point of 某事，指某情況嚴重到造成特定結果。"},{"en":"The room was crowded to the point of being unsafe.","zh":"房間擠迫到不安全的程度。"},{"en":"If a child is hungry to the point of dizziness, they need food quickly.","zh":"如果孩子餓到頭暈的程度，他們很快需要食物。"},{"en":"The phrase shows that a situation has reached a serious level.","zh":"這個短語顯示情況已達嚴重水平。"}],"source":"145 - Food for thought.pdf","sourcePage":3},{"front":"stunting","meaning":"發育遲緩","examples":[{"en":"Severe underfeeding can lead to stunting.","zh":"嚴重營養不足可導致發育遲緩。"},{"en":"Stunting is poor physical growth in children, often caused by long-term malnutrition.","zh":"stunting 指兒童身體成長不良，通常由長期營養不良造成。"},{"en":"Doctors measure height to check whether young children show signs of stunting.","zh":"醫生會量度身高，以檢查幼兒是否有發育遲緩跡象。"},{"en":"If stunting happens early in life, it can affect health and learning later.","zh":"如果發育遲緩在生命早期發生，它可能影響日後健康和學習。"},{"en":"The word is often used in reports about child nutrition.","zh":"這個字常用於兒童營養報告。"}],"source":"145 - Food for thought.pdf","sourcePage":3},{"front":"hunger blights","meaning":"飢餓破壞……","examples":[{"en":"Hunger blights most aspects of Malawian life.","zh":"飢餓破壞馬拉維生活的大部分方面。"},{"en":"Hunger blights something means hunger damages it seriously and makes it worse.","zh":"hunger blights 某事，意思是飢餓嚴重傷害並惡化該事。"},{"en":"Hunger can blight a child’s school day because it drains energy and attention.","zh":"飢餓可以破壞孩子的上學日，因為它耗盡能量和注意力。"},{"en":"If hunger blights a community, health, work, and education all suffer.","zh":"如果飢餓破壞一個社區，健康、工作和教育都會受損。"},{"en":"The verb blight gives hunger a strong negative effect, like a disease harming crops.","zh":"blight 這個動詞令飢餓帶有強烈負面效果，像疾病傷害農作物一樣。"}],"source":"145 - Food for thought.pdf","sourcePage":3},{"front":"most aspects of","meaning":"……的大部分方面","examples":[{"en":"Hunger affects most aspects of Malawian life.","zh":"飢餓影響馬拉維生活的大部分方面。"},{"en":"Most aspects of something means nearly all the main parts of it.","zh":"most aspects of 某事，意思是它幾乎所有主要部分。"},{"en":"Technology now affects most aspects of daily life, from shopping to transport.","zh":"科技現在影響日常生活的大部分方面，從購物到交通皆然。"},{"en":"If poverty touches most aspects of family life, children may face many problems at once.","zh":"如果貧窮觸及家庭生活的大部分方面，孩子可能同時面對許多問題。"},{"en":"The phrase is useful when a problem is wide, not limited to one area.","zh":"這個短語適用於問題範圍廣泛，而非限於一個範疇時。"}],"source":"145 - Food for thought.pdf","sourcePage":3},{"front":"as good a place as any","meaning":"是再合適不過的地方","examples":[{"en":"Malawi is as good a place as any to study nutrition and development.","zh":"馬拉維是研究營養與發展再合適不過的地方。"},{"en":"As good a place as any means a place is suitable enough, and perhaps no worse than other choices.","zh":"as good a place as any 指某地方足夠合適，甚至不比其他選擇差。"},{"en":"The library is as good a place as any to start revising because it is quiet.","zh":"圖書館是開始溫習再合適不過的地方，因為它很安靜。"},{"en":"If a town shows both poverty and strong community effort, it may be as good a place as any to study development.","zh":"如果一個城鎮同時展示貧窮和強大社區努力，它可能是研究發展再合適不過的地方。"},{"en":"The phrase can sound modest, but it means the choice is reasonable.","zh":"這個短語聽起來謙虛，但意思是這個選擇合理。"}],"source":"145 - Food for thought.pdf","sourcePage":3},{"front":"investigate how","meaning":"研究……如何","examples":[{"en":"Researchers can investigate how nutrition affects development.","zh":"研究人員可以研究營養如何影響發展。"},{"en":"To investigate how something happens means to study the process, reason, or effect carefully.","zh":"investigate how 某事發生，意思是仔細研究其過程、原因或影響。"},{"en":"Scientists investigate how sleep affects memory by comparing students’ test results.","zh":"科學家透過比較學生測驗成績，研究睡眠如何影響記憶。"},{"en":"If officials investigate how accidents happen, they can design safer roads.","zh":"如果官員研究意外如何發生，他們可以設計更安全的道路。"},{"en":"The phrase is common in research questions.","zh":"這個短語常見於研究問題。"}],"source":"145 - Food for thought.pdf","sourcePage":3},{"front":"nutrition affects development","meaning":"營養影響發展","examples":[{"en":"The passage explores how nutrition affects development.","zh":"文章探討營養如何影響發展。"},{"en":"Nutrition affects development means food quality and nutrients influence growth, learning, health, and progress.","zh":"nutrition affects development 指食物質素和營養素會影響成長、學習、健康和進步。"},{"en":"Good nutrition affects development because children need energy to grow and study.","zh":"良好營養影響發展，因為孩子需要能量成長和學習。"},{"en":"If nutrition is poor, development may slow in both the body and the brain.","zh":"如果營養差，身體和大腦的發展都可能減慢。"},{"en":"The phrase connects what people eat with what they can become.","zh":"這個短語把人們吃甚麼與他們能成為甚麼連繫起來。"}],"source":"145 - Food for thought.pdf","sourcePage":3},{"front":"and vice versa","meaning":"反之亦然","examples":[{"en":"Nutrition affects development, and vice versa.","zh":"營養影響發展，反之亦然。"},{"en":"And vice versa means the reverse is also true.","zh":"and vice versa 指反過來也成立。"},{"en":"Teachers affect students’ confidence, and vice versa, because confident students can energise teachers.","zh":"老師影響學生信心，反之亦然，因為有信心的學生也能令老師更有動力。"},{"en":"If poverty affects education, and vice versa, poor schooling can also keep people poor.","zh":"如果貧窮影響教育，反之亦然，差劣教育也可能令人民持續貧窮。"},{"en":"The phrase saves words by showing a two-way relationship.","zh":"這個短語透過顯示雙向關係來節省字句。"}],"source":"145 - Food for thought.pdf","sourcePage":3},{"front":"have strong views on","meaning":"對……有強烈看法","examples":[{"en":"The headmaster has strong views on school meals.","zh":"校長對學校膳食有強烈看法。"},{"en":"To have strong views on something means to hold clear and firm opinions about it.","zh":"have strong views on 某事，意思是對它有清晰而堅定的意見。"},{"en":"Parents may have strong views on homework because it affects family time.","zh":"家長可能對功課有強烈看法，因為功課影響家庭時間。"},{"en":"If people have strong views on school lunches, discussions can become emotional.","zh":"如果人們對學校午餐有強烈看法，討論可能變得情緒化。"},{"en":"The phrase suggests the person cares about the topic and is not neutral.","zh":"這個短語暗示該人關心題目，而不是中立。"}],"source":"145 - Food for thought.pdf","sourcePage":3},{"front":"on the subject","meaning":"關於這個題目","examples":[{"en":"Bernard Kumanda has strong views on the subject.","zh":"Bernard Kumanda關於這個題目有強烈看法。"},{"en":"On the subject means about that topic or issue.","zh":"on the subject 指關於該題目或議題。"},{"en":"The doctor answered several questions on the subject of healthy eating.","zh":"醫生回答了幾個關於健康飲食這個題目的問題。"},{"en":"If a teacher has experience on the subject, students may trust the advice more.","zh":"如果老師在這個題目上有經驗，學生可能更信任建議。"},{"en":"The phrase avoids repeating the exact topic already mentioned.","zh":"這個短語避免重複前面已提及的具體題目。"}],"source":"145 - Food for thought.pdf","sourcePage":4},{"front":"a priceless teaching aid","meaning":"極有價值的教學輔助","examples":[{"en":"He thinks food is a priceless teaching aid.","zh":"他認為食物是極有價值的教學輔助。"},{"en":"A priceless teaching aid is something extremely valuable for helping students learn.","zh":"a priceless teaching aid 指對幫助學生學習極有價值的東西。"},{"en":"Real objects in a science lesson can be a priceless teaching aid because students can see and touch them.","zh":"科學課中的實物可以是極有價值的教學輔助，因為學生可以看見和觸摸。"},{"en":"If a simple meal brings children to school, it becomes a priceless teaching aid.","zh":"如果一頓簡單餐食能令孩子上學，它就成為極有價值的教學輔助。"},{"en":"The phrase does not mean the item has no price; it means its value is very high.","zh":"這個短語不是指物件沒有價格，而是指其價值非常高。"}],"source":"145 - Food for thought.pdf","sourcePage":4},{"front":"since 1999","meaning":"自1999年以來","examples":[{"en":"Since 1999, the pupils have received free school lunches.","zh":"自1999年以來，學生一直獲得免費學校午餐。"},{"en":"Since 1999 means from the year 1999 until the present or until the time being discussed.","zh":"since 1999 指從1999年開始直到現在或直到所討論的時間。"},{"en":"The community centre has served elderly residents since 1999.","zh":"這間社區中心自1999年以來一直服務長者居民。"},{"en":"If a programme has continued since 1999, it has lasted for many years.","zh":"如果一項計劃自1999年以來一直持續，它已延續多年。"},{"en":"The phrase marks the starting point of a continuing situation.","zh":"這個短語標示一個持續情況的起點。"}],"source":"145 - Food for thought.pdf","sourcePage":4},{"front":"receive free school lunches","meaning":"獲得免費學校午餐","examples":[{"en":"The pupils receive free school lunches at Msekeni.","zh":"Msekeni的學生獲得免費學校午餐。"},{"en":"To receive free school lunches means to be given midday meals at school without paying.","zh":"receive free school lunches 指在學校免費獲得午餐。"},{"en":"Children from low-income families may receive free school lunches to support their health.","zh":"低收入家庭兒童可能獲得免費學校午餐，以支持健康。"},{"en":"If pupils receive free school lunches, parents may find it easier to keep them in school.","zh":"如果學生獲得免費學校午餐，家長可能更容易讓他們留在學校。"},{"en":"The phrase describes direct food support inside the school day.","zh":"這個短語描述上學日內的直接食物支援。"}],"source":"145 - Food for thought.pdf","sourcePage":4},{"front":"donors such as","meaning":"例如……的捐助者","examples":[{"en":"Donors such as the World Food Programme provide the food.","zh":"例如世界糧食計劃署的捐助者提供食物。"},{"en":"Donors such as introduces examples of people or organisations that give money, food, or support.","zh":"donors such as 用來引出提供金錢、食物或支援的人或組織例子。"},{"en":"Donors such as local businesses may help a school buy computers.","zh":"例如本地企業的捐助者可能幫助學校購買電腦。"},{"en":"If donors such as charities provide meals, poor families may face less pressure.","zh":"如果例如慈善機構的捐助者提供膳食，貧困家庭可能承受較少壓力。"},{"en":"The phrase gives examples without naming every donor.","zh":"這個短語提供例子，而不是列出每一位捐助者。"}],"source":"145 - Food for thought.pdf","sourcePage":4},{"front":"World Food Programme","meaning":"世界糧食計劃署","examples":[{"en":"The World Food Programme provides food for the school.","zh":"世界糧食計劃署為學校提供食物。"},{"en":"The World Food Programme is an international organisation that gives food assistance to people in need.","zh":"世界糧食計劃署是一個向有需要人士提供糧食援助的國際組織。"},{"en":"The World Food Programme may support school meals during a food crisis.","zh":"世界糧食計劃署可能在糧食危機期間支援學校膳食。"},{"en":"If the World Food Programme helps a village, children may receive more reliable meals.","zh":"如果世界糧食計劃署幫助村莊，孩子可能獲得更穩定的膳食。"},{"en":"The phrase refers to an organisation, not a general food plan.","zh":"這個短語指一個組織，而不是一般食物計劃。"}],"source":"145 - Food for thought.pdf","sourcePage":4},{"front":"provide the food","meaning":"提供食物","examples":[{"en":"Donors provide the food for the feeding programme.","zh":"捐助者為供餐計劃提供食物。"},{"en":"To provide the food means to supply the meals or ingredients needed.","zh":"provide the food 指供應所需膳食或材料。"},{"en":"Parents may provide the food for a class picnic.","zh":"家長可能為班級野餐提供食物。"},{"en":"If charities provide the food, schools can focus on cooking and distribution.","zh":"如果慈善機構提供食物，學校可以專注於烹調和分發。"},{"en":"The phrase identifies who supplies the food, not who eats it.","zh":"這個短語指出誰供應食物，而不是誰食用食物。"}],"source":"145 - Food for thought.pdf","sourcePage":4},{"front":"mixed maize and soya bean flour","meaning":"混合粟米及大豆粉","examples":[{"en":"The sacks contain mostly mixed maize and soya bean flour.","zh":"這些袋子主要裝有混合粟米及大豆粉。"},{"en":"Mixed maize and soya bean flour is flour made by combining maize and soya beans.","zh":"mixed maize and soya bean flour 是把粟米和大豆混合製成的粉。"},{"en":"A school kitchen can cook mixed maize and soya bean flour into porridge.","zh":"學校廚房可以把混合粟米及大豆粉煮成粥。"},{"en":"If flour contains both maize and soya beans, it may provide more nutrition than maize alone.","zh":"如果麵粉含有粟米和大豆，它可能比單用粟米更有營養。"},{"en":"The phrase names the main dry ingredient used in the meal.","zh":"這個短語指出餐食中使用的主要乾材料。"}],"source":"145 - Food for thought.pdf","sourcePage":4},{"front":"enriched with vitamin A","meaning":"添加了維他命A","examples":[{"en":"The flour is enriched with vitamin A.","zh":"這種粉添加了維他命A。"},{"en":"Enriched with vitamin A means vitamin A has been added to improve nutritional value.","zh":"enriched with vitamin A 指加入維他命A以提高營養價值。"},{"en":"Some milk is enriched with vitamin D to support bone health.","zh":"有些牛奶添加了維他命D，以支持骨骼健康。"},{"en":"If school flour is enriched with vitamin A, children may get nutrients missing from their usual diet.","zh":"如果學校用的粉添加了維他命A，兒童可能獲得日常飲食中缺乏的營養素。"},{"en":"The phrase is often used for food with added nutrients.","zh":"這個短語常用於添加了營養素的食物。"}],"source":"145 - Food for thought.pdf","sourcePage":4},{"front":"converted classroom","meaning":"改建後的課室","examples":[{"en":"The food is stored in a converted classroom.","zh":"食物存放在一間改建後的課室。"},{"en":"A converted classroom is a classroom changed for a new purpose.","zh":"converted classroom 是為新用途而改變的課室。"},{"en":"During exams, a converted classroom may become a quiet office for teachers.","zh":"考試期間，改建後的課室可能變成老師的安靜辦公室。"},{"en":"If a converted classroom stores food, pupils may have fewer rooms for lessons.","zh":"如果改建後的課室用來存放食物，學生可能有較少房間上課。"},{"en":"The word converted shows the original use has changed.","zh":"converted 一字顯示原本用途已經改變。"}],"source":"145 - Food for thought.pdf","sourcePage":4},{"front":"local volunteers","meaning":"本地義工","examples":[{"en":"Local volunteers do the cooking.","zh":"本地義工負責烹調。"},{"en":"Local volunteers are people from the nearby community who help without being paid.","zh":"local volunteers 是附近社區中無償幫忙的人。"},{"en":"Local volunteers may clean beaches, visit elderly people, or support school events.","zh":"本地義工可能清潔海灘、探訪長者或支援學校活動。"},{"en":"If local volunteers cook meals, a feeding programme can run with lower costs.","zh":"如果本地義工烹調膳食，供餐計劃可以以較低成本運作。"},{"en":"The phrase shows community support rather than paid employment.","zh":"這個短語顯示社區支援，而不是受薪工作。"}],"source":"145 - Food for thought.pdf","sourcePage":4},{"front":"dry ingredients","meaning":"乾材料","examples":[{"en":"The volunteers turn dry ingredients into porridge.","zh":"義工把乾材料煮成粥。"},{"en":"Dry ingredients are food materials that are not liquid, such as flour, rice, sugar, or beans.","zh":"dry ingredients 是非液體食材，例如麵粉、米、糖或豆。"},{"en":"Before baking a cake, students mix dry ingredients in one bowl.","zh":"焗蛋糕前，學生把乾材料放在一個碗裏混合。"},{"en":"If dry ingredients are stored in a damp room, they may spoil.","zh":"如果乾材料存放在潮濕房間，它們可能變壞。"},{"en":"The phrase is common in cooking instructions.","zh":"這個短語常見於烹飪指示。"}],"source":"145 - Food for thought.pdf","sourcePage":5},{"front":"turn something into","meaning":"將某物變成……","examples":[{"en":"The volunteers turn the ingredients into a nutritious meal.","zh":"義工把材料變成有營養的一餐。"},{"en":"To turn something into something else means to change it into a new form or use.","zh":"turn something into something else 指把某物改變成另一種形式或用途。"},{"en":"A good teacher can turn a mistake into a learning opportunity.","zh":"好老師可以把錯誤變成學習機會。"},{"en":"If families turn leftovers into soup, they waste less food.","zh":"如果家庭把剩菜變成湯，他們會浪費較少食物。"},{"en":"The phrase focuses on transformation from one thing to another.","zh":"這個短語重點在於從一物到另一物的轉變。"}],"source":"145 - Food for thought.pdf","sourcePage":5},{"front":"bland but nutritious","meaning":"味道清淡但有營養","examples":[{"en":"The porridge is bland but nutritious.","zh":"這種粥味道清淡但有營養。"},{"en":"Bland but nutritious means not strong in taste, but still good for the body.","zh":"bland but nutritious 指味道不濃，但仍對身體有益。"},{"en":"Plain rice and vegetables may be bland but nutritious for a sick person.","zh":"白飯和蔬菜對病人來說可能味道清淡但有營養。"},{"en":"If food is bland but nutritious, children may not love the taste, but it can still help them grow.","zh":"如果食物味道清淡但有營養，孩子可能不太喜歡味道，但它仍可幫助他們成長。"},{"en":"The phrase contrasts flavour with health value.","zh":"這個短語把味道與健康價值作對比。"}],"source":"145 - Food for thought.pdf","sourcePage":5},{"front":"slop","meaning":"稀糊狀食物","examples":[{"en":"The dry ingredients are cooked into a bland but nutritious slop.","zh":"乾材料被煮成味道清淡但有營養的稀糊狀食物。"},{"en":"Slop is soft, wet food that looks messy or watery, often not very attractive.","zh":"slop 是柔軟、濕而看起來混亂或水汪汪的食物，通常不太吸引。"},{"en":"A badly cooked bowl of oats can look like slop if too much water is added.","zh":"如果加太多水，煮得差的燕麥可能看起來像稀糊狀食物。"},{"en":"If food looks like slop, children may dislike it even when it is nutritious.","zh":"如果食物看起來像稀糊狀食物，孩子即使知道有營養也可能不喜歡。"},{"en":"The word is informal and can sound slightly negative.","zh":"這個字較口語，並可帶有少許負面意思。"}],"source":"145 - Food for thought.pdf","sourcePage":5},{"front":"spoon something out","meaning":"用匙羹分發","examples":[{"en":"The volunteers spoon the porridge out onto plastic plates.","zh":"義工用匙羹把粥分到膠碟上。"},{"en":"To spoon something out means to serve or move food using a spoon.","zh":"spoon something out 指用匙羹盛出或分發食物。"},{"en":"A parent may spoon soup out into bowls for the children.","zh":"家長可能用匙羹把湯分到孩子的碗裏。"},{"en":"If volunteers spoon food out carefully, each child can receive a fair portion.","zh":"如果義工小心用匙羹分發食物，每個孩子都可以得到公平份量。"},{"en":"The phrase describes the physical action of distributing soft or liquid food.","zh":"這個短語描述分發柔軟或液體食物的實際動作。"}],"source":"145 - Food for thought.pdf","sourcePage":5},{"front":"plastic plates","meaning":"膠碟","examples":[{"en":"The children receive the porridge on plastic plates.","zh":"孩子們用膠碟盛粥。"},{"en":"Plastic plates are plates made of plastic, often light and difficult to break.","zh":"plastic plates 是由塑膠製成的碟，通常輕便且不易破裂。"},{"en":"Schools may use plastic plates because they are cheap and easy to carry.","zh":"學校可能使用膠碟，因為它們便宜又容易搬運。"},{"en":"If plastic plates are reused, they must be washed properly to keep children safe.","zh":"如果膠碟重複使用，就必須妥善清洗，以保障孩子安全。"},{"en":"The phrase identifies the simple container used for serving food.","zh":"這個短語指出用來分發食物的簡單容器。"}],"source":"145 - Food for thought.pdf","sourcePage":5},{"front":"line up in large crowds","meaning":"大群排隊","examples":[{"en":"The children line up in large crowds for lunch.","zh":"孩子們大群排隊等候午餐。"},{"en":"To line up in large crowds means many people stand together in a queue or loose line.","zh":"line up in large crowds 指許多人一起排成隊或較鬆散的隊伍。"},{"en":"Fans line up in large crowds when a famous singer gives a free concert.","zh":"當著名歌手舉行免費演唱會，粉絲會大群排隊。"},{"en":"If children line up in large crowds, teachers may need to organise them carefully.","zh":"如果孩子們大群排隊，老師可能需要小心組織他們。"},{"en":"The phrase shows both number and order: many people waiting together.","zh":"這個短語同時顯示人數和秩序：許多人一起等候。"}],"source":"145 - Food for thought.pdf","sourcePage":5},{"front":"cheerfully singing","meaning":"開心地唱着歌","examples":[{"en":"The children line up cheerfully singing a song.","zh":"孩子們開心地唱着歌排隊。"},{"en":"Cheerfully singing means singing in a happy, bright, or lively way.","zh":"cheerfully singing 指以開心、明朗或活潑的方式唱歌。"},{"en":"Children may walk to the playground cheerfully singing after the exam ends.","zh":"考試結束後，孩子們可能開心地唱着歌走到操場。"},{"en":"If pupils are cheerfully singing before lunch, the meal may feel like a happy event.","zh":"如果學生在午餐前開心地唱着歌，那頓飯可能像一件開心事情。"},{"en":"The phrase shows mood as well as action.","zh":"這個短語同時顯示心情和動作。"}],"source":"145 - Food for thought.pdf","sourcePage":5},{"front":"a song called","meaning":"一首名為……的歌","examples":[{"en":"The children sing a song called “We are getting porridge”.","zh":"孩子們唱一首名為《我們正在領粥》的歌。"},{"en":"A song called something means a song with that title or name.","zh":"a song called 某名稱，指一首有該標題或名稱的歌。"},{"en":"The class performed a song called “Our Green School” at the ceremony.","zh":"班級在典禮上表演一首名為《我們的綠色學校》的歌。"},{"en":"If children sing a song called “Wash Your Hands”, the title tells listeners the topic.","zh":"如果孩子唱一首名為《洗手》的歌，歌名會告訴聽眾主題。"},{"en":"The phrase is used to introduce the name of a song.","zh":"這個短語用來介紹歌曲名稱。"}],"source":"145 - Food for thought.pdf","sourcePage":5},{"front":"feeding programme","meaning":"供餐計劃","examples":[{"en":"The school’s feeding programme changed attendance.","zh":"學校的供餐計劃改變了出席情況。"},{"en":"A feeding programme is an organised plan that provides regular food to people who need it.","zh":"feeding programme 是有組織地向有需要人士定期提供食物的計劃。"},{"en":"A school feeding programme may give lunch to children from poor families.","zh":"學校供餐計劃可能為貧困家庭兒童提供午餐。"},{"en":"If a feeding programme is reliable, parents may be more willing to send children to school.","zh":"如果供餐計劃可靠，家長可能更願意送孩子上學。"},{"en":"The phrase describes planned food support, not one informal meal.","zh":"這個短語描述有計劃的食物支援，而不是一頓非正式餐食。"}],"source":"145 - Food for thought.pdf","sourcePage":5},{"front":"be introduced","meaning":"被引入","examples":[{"en":"When the feeding programme was introduced, enrolment doubled.","zh":"當供餐計劃被引入時，入學人數增加一倍。"},{"en":"To be introduced means to be started, brought in, or made available for the first time.","zh":"be introduced 指被開始、引入或首次提供。"},{"en":"A new bus route was introduced after residents asked for better transport.","zh":"居民要求改善交通後，一條新巴士路線被引入。"},{"en":"If free meals are introduced, more children may attend school regularly.","zh":"如果免費膳食被引入，更多孩子可能定期上學。"},{"en":"The phrase marks the beginning of a new system, policy, or practice.","zh":"這個短語標示新制度、政策或做法的開始。"}],"source":"145 - Food for thought.pdf","sourcePage":5},{"front":"enrolment doubled","meaning":"入學人數增加一倍","examples":[{"en":"Enrolment at Msekeni doubled after the feeding programme began.","zh":"供餐計劃開始後，Msekeni的入學人數增加一倍。"},{"en":"Enrolment doubled means the number of students registered became twice as large.","zh":"enrolment doubled 指註冊學生人數變成原來的兩倍。"},{"en":"A language course’s enrolment doubled after it moved online.","zh":"一個語言課程轉到網上後，入學人數增加一倍。"},{"en":"If enrolment doubled suddenly, a school might need more teachers and classrooms.","zh":"如果入學人數突然增加一倍，學校可能需要更多老師和課室。"},{"en":"The phrase describes a large increase in student numbers.","zh":"這個短語描述學生人數大幅上升。"}],"source":"145 - Food for thought.pdf","sourcePage":6},{"front":"switch from nearby schools","meaning":"從附近學校轉來","examples":[{"en":"Some pupils switched from nearby schools.","zh":"一些學生從附近學校轉來。"},{"en":"To switch from nearby schools means to leave local schools close by and move to another school.","zh":"switch from nearby schools 指離開附近的本地學校並轉到另一間學校。"},{"en":"A child may switch from a nearby school if another school offers better support.","zh":"如果另一間學校提供更好支援，孩子可能從附近學校轉來。"},{"en":"If many pupils switch from nearby schools, those schools may lose enrolment.","zh":"如果許多學生從附近學校轉走，那些學校可能失去入學人數。"},{"en":"The phrase shows movement between schools in the same area.","zh":"這個短語顯示同一地區學校之間的轉移。"}],"source":"145 - Food for thought.pdf","sourcePage":6},{"front":"give out free porridge","meaning":"派發免費粥","examples":[{"en":"Some nearby schools did not give out free porridge.","zh":"一些附近學校沒有派發免費粥。"},{"en":"To give out free porridge means to distribute porridge without charging money.","zh":"give out free porridge 指免費分發粥。"},{"en":"Volunteers may give out free porridge on cold mornings to homeless people.","zh":"義工可能在寒冷早上向無家者派發免費粥。"},{"en":"If a school gives out free porridge, hungry pupils may come to class more often.","zh":"如果學校派發免費粥，飢餓學生可能更常來上課。"},{"en":"The phrase focuses on free distribution of simple food.","zh":"這個短語重點在於免費分發簡單食物。"}],"source":"145 - Food for thought.pdf","sourcePage":6},{"front":"previously kept them at home","meaning":"以往把他們留在家中","examples":[{"en":"Some families had previously kept their children at home to work.","zh":"一些家庭以往把孩子留在家中工作。"},{"en":"Previously kept them at home means had kept them at home before the later change happened.","zh":"previously kept them at home 指在後來改變發生前，曾經把他們留在家中。"},{"en":"Some parents previously kept their children at home because the school was too far away.","zh":"一些家長以往把孩子留在家中，因為學校太遠。"},{"en":"If free meals change family decisions, children previously kept at home may start attending school.","zh":"如果免費膳食改變家庭決定，以往被留在家中的孩子可能開始上學。"},{"en":"The word previously points to an earlier situation.","zh":"previously 一字指向較早前的情況。"}],"source":"145 - Food for thought.pdf","sourcePage":6},{"front":"keep someone at home to work","meaning":"把某人留在家中工作","examples":[{"en":"Poor families often kept children at home to work.","zh":"貧困家庭常把孩子留在家中工作。"},{"en":"To keep someone at home to work means to make them stay home so they can help with jobs instead of doing something else.","zh":"keep someone at home to work 指令某人留在家裏幫忙工作，而不是做其他事情。"},{"en":"A family may keep a teenager at home to work if they cannot afford hired help.","zh":"如果家庭負擔不起聘請幫工，可能把青少年留在家中工作。"},{"en":"If children are kept at home to work, they may miss education and future opportunities.","zh":"如果孩子被留在家中工作，他們可能錯過教育和未來機會。"},{"en":"The phrase often shows how poverty changes family choices.","zh":"這個短語常顯示貧窮如何改變家庭選擇。"}],"source":"145 - Food for thought.pdf","sourcePage":6},{"front":"long-term benefits of education","meaning":"教育的長遠好處","examples":[{"en":"The long-term benefits of education seemed unattractive to very poor families.","zh":"對非常貧困的家庭來說，教育的長遠好處看起來沒有吸引力。"},{"en":"Long-term benefits of education are advantages that appear later, such as better jobs, income, and choices.","zh":"long-term benefits of education 是日後才出現的好處，例如更好工作、收入和選擇。"},{"en":"Parents may understand the long-term benefits of education but still need children to help now.","zh":"家長可能明白教育的長遠好處，但現在仍需要孩子幫忙。"},{"en":"If families cannot meet today’s needs, long-term benefits of education may feel less urgent.","zh":"如果家庭無法滿足今天的需要，教育的長遠好處可能顯得較不迫切。"},{"en":"The phrase contrasts future rewards with immediate problems.","zh":"這個短語把未來回報與即時問題作對比。"}],"source":"145 - Food for thought.pdf","sourcePage":6},{"front":"seem unattractive","meaning":"看起來沒有吸引力","examples":[{"en":"Education seemed unattractive when compared with immediate work.","zh":"與即時工作相比，教育看起來沒有吸引力。"},{"en":"To seem unattractive means to appear not useful, pleasant, or worth choosing.","zh":"seem unattractive 指看起來不有用、不愉快或不值得選擇。"},{"en":"A long bus journey may seem unattractive if walking takes only ten minutes.","zh":"如果步行只需十分鐘，漫長巴士旅程可能看起來沒有吸引力。"},{"en":"If school brings no immediate food or income, it may seem unattractive to poor families.","zh":"如果上學沒有帶來即時食物或收入，它對貧困家庭可能看起來沒有吸引力。"},{"en":"The phrase describes how something appears, not necessarily its true value.","zh":"這個短語描述某事看起來如何，而不一定是其真正價值。"}],"source":"145 - Food for thought.pdf","sourcePage":6},{"front":"when set against","meaning":"與……相比時","examples":[{"en":"The benefits of education seemed weak when set against short-term gain.","zh":"與短期收益相比時，教育的好處顯得微弱。"},{"en":"When set against something means when compared with it.","zh":"when set against 某物，意思是與其相比時。"},{"en":"A small salary rise seems less impressive when set against rising rent.","zh":"與上升的租金相比時，小幅加薪顯得沒有那麼可觀。"},{"en":"When set against a child’s need for food today, future education benefits may seem distant.","zh":"與孩子今天對食物的需要相比時，未來教育好處可能顯得遙遠。"},{"en":"The phrase is useful for showing contrast between two values or choices.","zh":"這個短語適合顯示兩種價值或選擇之間的對比。"}],"source":"145 - Food for thought.pdf","sourcePage":6},{"front":"short-term gain","meaning":"短期收益","examples":[{"en":"Sending children to work brought short-term gain.","zh":"派孩子去工作帶來短期收益。"},{"en":"Short-term gain is an immediate benefit that may not help in the future.","zh":"short-term gain 是即時好處，但未必有助將來。"},{"en":"Selling a useful tool may bring short-term gain but make work harder later.","zh":"賣掉有用工具可能帶來短期收益，但日後令工作更困難。"},{"en":"If a family chooses short-term gain, children may earn money now but lose schooling.","zh":"如果家庭選擇短期收益，孩子現在可能賺到錢，但失去學習機會。"},{"en":"The phrase often contrasts quick benefit with long-term cost.","zh":"這個短語常把快速好處與長遠代價作對比。"}],"source":"145 - Food for thought.pdf","sourcePage":6},{"front":"send children out to","meaning":"派孩子出去……","examples":[{"en":"Some families sent children out to gather firewood.","zh":"一些家庭派孩子出去收集柴枝。"},{"en":"To send children out to do something means to make them leave home to perform a task.","zh":"send children out to do something 指叫孩子離開家去做某項任務。"},{"en":"A parent may send children out to buy bread from a nearby shop.","zh":"家長可能派孩子出去到附近商店買麵包。"},{"en":"If families send children out to work every day, school attendance may fall.","zh":"如果家庭每天派孩子出去工作，上學率可能下降。"},{"en":"The phrase describes children being directed to do an outside task.","zh":"這個短語描述孩子被指派外出完成任務。"}],"source":"145 - Food for thought.pdf","sourcePage":6},{"front":"gather firewood","meaning":"收集柴枝","examples":[{"en":"Children were sent out to gather firewood.","zh":"孩子被派出去收集柴枝。"},{"en":"To gather firewood means to collect wood that can be burned for cooking or heating.","zh":"gather firewood 指收集可用作煮食或取暖的木柴。"},{"en":"In rural areas, families may gather firewood before sunset.","zh":"在鄉村地區，家庭可能在日落前收集柴枝。"},{"en":"If children spend hours gathering firewood, they have less time for schoolwork.","zh":"如果孩子花數小時收集柴枝，他們做功課的時間會減少。"},{"en":"The phrase describes a practical household task in places without easy fuel access.","zh":"這個短語描述在不易取得燃料的地方常見的實際家務。"}],"source":"145 - Food for thought.pdf","sourcePage":6},{"front":"help in the fields","meaning":"在田裏幫忙","examples":[{"en":"Some children stayed home to help in the fields.","zh":"一些孩子留在家中，在田裏幫忙。"},{"en":"To help in the fields means to work on farmland by planting, weeding, harvesting, or carrying crops.","zh":"help in the fields 指在農田裏工作，例如種植、除草、收割或搬運農作物。"},{"en":"During harvest season, teenagers may help in the fields after school.","zh":"收成季節，青少年可能放學後在田裏幫忙。"},{"en":"If children help in the fields all day, they may miss lessons and become tired.","zh":"如果孩子整天在田裏幫忙，他們可能缺課並感到疲倦。"},{"en":"The phrase usually describes agricultural work done by family members.","zh":"這個短語通常描述家庭成員做的農務。"}],"source":"145 - Food for thought.pdf","sourcePage":7},{"front":"alter the calculation","meaning":"改變了考量","examples":[{"en":"One plate of porridge a day completely altered the calculation.","zh":"每天一碟粥完全改變了考量。"},{"en":"To alter the calculation means to change how people judge costs, benefits, or choices.","zh":"alter the calculation 指改變人們對成本、好處或選擇的判斷。"},{"en":"A free bus pass can alter the calculation for students choosing between schools.","zh":"免費巴士證可以改變學生選擇學校時的考量。"},{"en":"If school meals reduce hunger at home, they alter the calculation for poor parents.","zh":"如果學校膳食減少家中飢餓，它們就改變貧困父母的考量。"},{"en":"The phrase is often used when one new factor changes a decision.","zh":"這個短語常用於一個新因素改變決定時。"}],"source":"145 - Food for thought.pdf","sourcePage":7},{"front":"be fed at school","meaning":"在學校獲供餐","examples":[{"en":"A child fed at school will be less hungry at home.","zh":"在學校獲供餐的孩子在家會較少飢餓。"},{"en":"To be fed at school means to receive food during the school day.","zh":"be fed at school 指在上學日獲得食物。"},{"en":"Children fed at school may have more energy for afternoon lessons.","zh":"在學校獲供餐的孩子可能有更多精力上下午課。"},{"en":"If pupils are fed at school, parents may save food for younger children at home.","zh":"如果學生在學校獲供餐，家長可能可以把食物留給家中較年幼孩子。"},{"en":"The phrase describes school-based meals as direct support for children.","zh":"這個短語描述以學校膳食直接支援兒童。"}],"source":"145 - Food for thought.pdf","sourcePage":7},{"front":"howl plaintively for food","meaning":"可憐地哭叫要食物","examples":[{"en":"A child fed at school will not howl so plaintively for food at home.","zh":"在學校獲供餐的孩子在家就不會那麼可憐地哭叫要食物。"},{"en":"To howl plaintively for food means to cry loudly and sadly because of hunger.","zh":"howl plaintively for food 指因飢餓而大聲、悲傷地哭叫要食物。"},{"en":"A baby may howl plaintively for milk when feeding is late.","zh":"如果餵奶時間遲了，嬰兒可能可憐地哭叫要奶。"},{"en":"If children receive lunch at school, they may not howl plaintively for food after returning home.","zh":"如果孩子在學校獲得午餐，回家後可能不會可憐地哭叫要食物。"},{"en":"The phrase sounds emotional and shows real suffering, not ordinary complaining.","zh":"這個短語帶有情感，顯示真實痛苦，而不是普通抱怨。"}],"source":"145 - Food for thought.pdf","sourcePage":7},{"front":"be more likely than boys to","meaning":"比男孩更有可能","examples":[{"en":"Girls are more likely than boys to be kept out of school.","zh":"女孩比男孩更有可能被迫不上學。"},{"en":"To be more likely than boys to do something means girls have a higher chance of doing or experiencing it than boys.","zh":"be more likely than boys to do something 指女孩做某事或經歷某事的機會比男孩高。"},{"en":"In some places, girls are more likely than boys to help with housework after school.","zh":"在一些地方，女孩比男孩更有可能放學後幫忙做家務。"},{"en":"If girls are more likely than boys to miss lessons, special support may be needed.","zh":"如果女孩比男孩更有可能缺課，可能需要特別支援。"},{"en":"The phrase compares probability between girls and boys.","zh":"這個短語比較女孩與男孩之間的可能性。"}],"source":"145 - Food for thought.pdf","sourcePage":7},{"front":"be kept out of school","meaning":"被迫不上學","examples":[{"en":"Girls are more likely than boys to be kept out of school.","zh":"女孩比男孩更有可能被迫不上學。"},{"en":"To be kept out of school means to be prevented from attending school.","zh":"be kept out of school 指被阻止上學。"},{"en":"A child may be kept out of school because the family cannot afford uniforms.","zh":"孩子可能因家庭負擔不起校服而被迫不上學。"},{"en":"If children are kept out of school, they lose lessons, friends, and future choices.","zh":"如果孩子被迫不上學，他們會失去課堂、朋友和未來選擇。"},{"en":"The phrase often points to barriers created by poverty, distance, work, or discrimination.","zh":"這個短語常指由貧窮、距離、工作或歧視造成的障礙。"}],"source":"145 - Food for thought.pdf","sourcePage":7},{"front":"extra snacks","meaning":"額外小食","examples":[{"en":"Girls are given extra snacks to take home.","zh":"女孩獲發額外小食帶回家。"},{"en":"Extra snacks are additional small amounts of food given beyond the normal meal.","zh":"extra snacks 是正常膳食以外額外給予的小量食物。"},{"en":"A teacher may give extra snacks to students staying late for sports practice.","zh":"老師可能給留校做運動練習的學生額外小食。"},{"en":"If girls receive extra snacks, families may be more willing to let them attend school.","zh":"如果女孩收到額外小食，家庭可能更願意讓她們上學。"},{"en":"The phrase suggests added food support, not a full extra meal.","zh":"這個短語暗示額外食物支援，而不是完整額外餐食。"}],"source":"145 - Food for thought.pdf","sourcePage":7},{"front":"take home","meaning":"帶回家","examples":[{"en":"Girls receive extra snacks to take home.","zh":"女孩收到額外小食帶回家。"},{"en":"To take home something means to carry it from another place back to one’s home.","zh":"take home 某物，意思是把它從其他地方帶回自己家中。"},{"en":"Students may take home books from the school library.","zh":"學生可以從學校圖書館借書帶回家。"},{"en":"If children take home food, younger siblings may also benefit.","zh":"如果孩子把食物帶回家，年幼弟妹也可能受惠。"},{"en":"The phrase can describe both physical items and lessons learned, depending on context.","zh":"這個短語可按語境描述實體物品或學到的道理。"}],"source":"145 - Food for thought.pdf","sourcePage":7},{"front":"take in","meaning":"接收","examples":[{"en":"The school takes in many extra students from poor homes.","zh":"學校接收許多來自貧困家庭的額外學生。"},{"en":"To take in students means to accept them into a school or group.","zh":"take in students 指接收學生進入學校或群體。"},{"en":"A shelter may take in families after a flood.","zh":"洪水後，庇護中心可能接收家庭。"},{"en":"If a school takes in many new pupils, it may need more desks and teachers.","zh":"如果學校接收許多新學生，可能需要更多書枱和老師。"},{"en":"The phrase often means accepting people who need a place or service.","zh":"這個短語常指接收需要地方或服務的人。"}],"source":"145 - Food for thought.pdf","sourcePage":7},{"front":"a horde of extra students","meaning":"一大群額外學生","examples":[{"en":"The school took in a horde of extra students from poor homes.","zh":"學校接收了一大群來自貧困家庭的額外學生。"},{"en":"A horde of extra students means a very large number of additional students, often more than expected.","zh":"a horde of extra students 指非常大量的新增學生，通常超出預期。"},{"en":"A free summer course may attract a horde of extra students in the final week.","zh":"免費暑期課程可能在最後一星期吸引一大群額外學生。"},{"en":"If a horde of extra students arrives, classrooms can become crowded quickly.","zh":"如果一大群額外學生到來，課室可能很快變得擠迫。"},{"en":"The word horde is vivid and suggests a large, difficult-to-manage group.","zh":"horde 一字形象鮮明，暗示一大群較難管理的人。"}],"source":"145 - Food for thought.pdf","sourcePage":7},{"front":"the poorest homes","meaning":"最貧困家庭","examples":[{"en":"Many new students came from the poorest homes.","zh":"許多新學生來自最貧困家庭。"},{"en":"The poorest homes are households with the least money, food, and resources.","zh":"the poorest homes 是金錢、食物和資源最少的家庭。"},{"en":"A charity may target the poorest homes when distributing winter clothes.","zh":"慈善機構派發冬衣時，可能以最貧困家庭為目標。"},{"en":"Children from the poorest homes may need school meals, uniforms, and books.","zh":"來自最貧困家庭的孩子可能需要學校膳食、校服和書本。"},{"en":"The phrase identifies the families facing the greatest hardship.","zh":"這個短語指出面對最大困難的家庭。"}],"source":"145 - Food for thought.pdf","sourcePage":7},{"front":"expect standards to drop","meaning":"預期水平下降","examples":[{"en":"You would expect standards to drop when many extra students arrive.","zh":"當許多額外學生到來時，你會預期水平下降。"},{"en":"To expect standards to drop means to think quality or performance will become worse.","zh":"expect standards to drop 指認為質素或表現會變差。"},{"en":"If a restaurant suddenly serves twice as many customers, you might expect standards to drop.","zh":"如果餐廳突然服務兩倍顧客，你可能預期水平下降。"},{"en":"When class sizes grow without more teachers, people often expect standards to drop.","zh":"當班級人數增加而沒有更多老師時，人們常預期水平下降。"},{"en":"The phrase describes a reasonable prediction, not always what actually happens.","zh":"這個短語描述合理預測，不一定是實際發生的事。"}],"source":"145 - Food for thought.pdf","sourcePage":8},{"front":"anywhere in the world","meaning":"世界任何地方","examples":[{"en":"Anywhere in the world, poor children tend to face learning difficulties.","zh":"在世界任何地方，貧困兒童往往面對學習困難。"},{"en":"Anywhere in the world means in any country or place globally.","zh":"anywhere in the world 指全球任何國家或地方。"},{"en":"A child needs clean water anywhere in the world.","zh":"在世界任何地方，孩子都需要潔淨食水。"},{"en":"If education is too expensive, families anywhere in the world may struggle.","zh":"如果教育太昂貴，世界任何地方的家庭都可能掙扎。"},{"en":"The phrase makes a statement broad and international.","zh":"這個短語令陳述變得廣泛和國際化。"}],"source":"145 - Food for thought.pdf","sourcePage":8},{"front":"tend to perform worse than","meaning":"往往表現比……差","examples":[{"en":"Poor children tend to perform worse than better-off classmates.","zh":"貧困兒童往往表現比家境較好的同學差。"},{"en":"To tend to perform worse than others means to usually achieve lower results than them.","zh":"tend to perform worse than others 指通常取得比他人較低的成績或表現。"},{"en":"Students who sleep badly tend to perform worse than those who rest well.","zh":"睡眠差的學生往往表現比休息充足的學生差。"},{"en":"If children lack food and books, they may tend to perform worse than classmates with more support.","zh":"如果孩子缺乏食物和書本，他們可能往往表現比有更多支援的同學差。"},{"en":"The phrase describes a general pattern, not every individual case.","zh":"這個短語描述一般趨勢，而不是每一個個案。"}],"source":"145 - Food for thought.pdf","sourcePage":8},{"front":"better-off classmates","meaning":"家境較好的同學","examples":[{"en":"Poor children often perform worse than their better-off classmates.","zh":"貧困兒童常表現比家境較好的同學差。"},{"en":"Better-off classmates are students whose families have more money or resources.","zh":"better-off classmates 是家庭有更多金錢或資源的同學。"},{"en":"Better-off classmates may have private tutors, quiet study space, and enough food.","zh":"家境較好的同學可能有私人補習、安靜學習空間和足夠食物。"},{"en":"If poor children compare themselves with better-off classmates, they may feel discouraged.","zh":"如果貧困兒童把自己與家境較好的同學比較，他們可能感到灰心。"},{"en":"The phrase compares students by family situation, not ability.","zh":"這個短語按家庭情況而非能力比較學生。"}],"source":"145 - Food for thought.pdf","sourcePage":8},{"front":"the influx of new pupils","meaning":"大批新學生湧入","examples":[{"en":"The influx of new pupils was not matched by more teachers.","zh":"大批新學生湧入並沒有伴隨更多教師。"},{"en":"The influx of new pupils means the arrival of many new students within a short time.","zh":"the influx of new pupils 指許多新學生在短時間內到來。"},{"en":"A popular school may face an influx of new pupils after exam results improve.","zh":"考試成績改善後，受歡迎學校可能面對大批新學生湧入。"},{"en":"If the influx of new pupils is not planned for, classrooms can become overcrowded.","zh":"如果沒有為大批新學生湧入作計劃，課室可能變得過度擠迫。"},{"en":"The word influx suggests many people coming in, not just a few.","zh":"influx 一字暗示許多人進入，而不只是少數人。"}],"source":"145 - Food for thought.pdf","sourcePage":8},{"front":"be accompanied by","meaning":"伴隨着","examples":[{"en":"The influx was not accompanied by an increase in teachers.","zh":"這次學生湧入並沒有伴隨教師人數增加。"},{"en":"To be accompanied by something means to happen together with it.","zh":"be accompanied by 某事，意思是與它同時發生。"},{"en":"Heavy rain was accompanied by strong winds last night.","zh":"昨晚大雨伴隨強風。"},{"en":"If rising enrolment is not accompanied by more teachers, class quality may suffer.","zh":"如果入學人數上升沒有伴隨更多教師，課堂質素可能受損。"},{"en":"The phrase connects two things that occur at the same time.","zh":"這個短語連繫同時出現的兩件事。"}],"source":"145 - Food for thought.pdf","sourcePage":8},{"front":"an increase in the number of","meaning":"……數目的增加","examples":[{"en":"There was no increase in the number of teachers.","zh":"教師數目沒有增加。"},{"en":"An increase in the number of something means there are more of them than before.","zh":"an increase in the number of 某物，指其數量比以前多。"},{"en":"An increase in the number of buses can reduce waiting time.","zh":"巴士數目的增加可以減少等候時間。"},{"en":"If there is no increase in the number of classrooms, extra pupils must share limited space.","zh":"如果課室數目沒有增加，額外學生必須共用有限空間。"},{"en":"The phrase focuses on a change in quantity.","zh":"這個短語重點在於數量變化。"}],"source":"145 - Food for thought.pdf","sourcePage":8},{"front":"as was the case at","meaning":"正如……的情況","examples":[{"en":"No new teachers were added, as was the case at Msekeni.","zh":"沒有新增教師，正如Msekeni的情況。"},{"en":"As was the case at means the same situation also happened at that place.","zh":"as was the case at 某地，指同樣情況也在該地發生。"},{"en":"The library lacked computers, as was the case at many rural schools.","zh":"圖書館缺乏電腦，正如許多鄉村學校的情況。"},{"en":"If enrolment rose without extra staff, as was the case at Msekeni, standards might be expected to fall.","zh":"如果入學人數上升而沒有額外職員，正如Msekeni的情況，人們可能預期水平下降。"},{"en":"The phrase links one example to a wider pattern.","zh":"這個短語把一個例子與更廣泛模式連繫起來。"}],"source":"145 - Food for thought.pdf","sourcePage":8},{"front":"fall even further","meaning":"進一步下降","examples":[{"en":"Standards might have been expected to fall even further.","zh":"水平原本可能被預期會進一步下降。"},{"en":"To fall even further means to decrease more than before or more than expected.","zh":"fall even further 指比以前或比預期下降更多。"},{"en":"If a shop loses more staff, service quality may fall even further.","zh":"如果商店失去更多員工，服務質素可能進一步下降。"},{"en":"When class sizes grow and resources remain the same, results may fall even further.","zh":"當班級人數增加而資源不變，成績可能進一步下降。"},{"en":"The phrase suggests an additional decline after an already difficult situation.","zh":"這個短語暗示在已困難的情況後再額外下跌。"}],"source":"145 - Food for thought.pdf","sourcePage":8},{"front":"pass rates","meaning":"合格率","examples":[{"en":"Pass rates at Msekeni improved dramatically.","zh":"Msekeni的合格率大幅改善。"},{"en":"Pass rates are the percentages of students who pass an exam or assessment.","zh":"pass rates 是通過考試或評核的學生百分比。"},{"en":"A school may study pass rates to see whether teaching methods are working.","zh":"學校可能研究合格率，以了解教學方法是否有效。"},{"en":"If pass rates rise after a lunch programme begins, nutrition may be helping learning.","zh":"如果午餐計劃開始後合格率上升，營養可能正在幫助學習。"},{"en":"The phrase measures academic success in numbers.","zh":"這個短語以數字衡量學業成功。"}],"source":"145 - Food for thought.pdf","sourcePage":8},{"front":"improve dramatically","meaning":"大幅改善","examples":[{"en":"Pass rates improved dramatically after the feeding programme began.","zh":"供餐計劃開始後，合格率大幅改善。"},{"en":"To improve dramatically means to become much better in a clear and noticeable way.","zh":"improve dramatically 指以清楚而明顯的方式變得好很多。"},{"en":"A student’s speaking can improve dramatically after regular practice with feedback.","zh":"學生在定期練習並獲得回饋後，口語可以大幅改善。"},{"en":"If children eat properly, their attention in class may improve dramatically.","zh":"如果孩子吃得好，他們在課堂上的專注力可能大幅改善。"},{"en":"The phrase describes a big improvement, not a small change.","zh":"這個短語描述重大改善，而不是小變化。"}],"source":"145 - Food for thought.pdf","sourcePage":8},{"front":"an exceptional example","meaning":"一個特殊例子","examples":[{"en":"Msekeni was an exceptional example.","zh":"Msekeni是一個特殊例子。"},{"en":"An exceptional example is a case that is unusual or much stronger than normal.","zh":"an exceptional example 是不尋常或遠強於一般情況的個案。"},{"en":"A student who improves from failing to top marks is an exceptional example of progress.","zh":"一名學生從不及格進步到最高分，是進步的一個特殊例子。"},{"en":"If one school’s results rise far more than others, it may be an exceptional example.","zh":"如果一間學校的成績升幅遠高於其他學校，它可能是一個特殊例子。"},{"en":"The phrase warns readers not to assume every case is the same.","zh":"這個短語提醒讀者不要假設每個個案都一樣。"}],"source":"145 - Food for thought.pdf","sourcePage":9},{"front":"nationwide results","meaning":"全國性結果","examples":[{"en":"The nationwide results of school feeding programmes were still good.","zh":"學校供餐計劃的全國性結果仍然良好。"},{"en":"Nationwide results are results measured across the whole country.","zh":"nationwide results 是在整個國家範圍內量度的結果。"},{"en":"Nationwide results from an exam can show whether education is improving overall.","zh":"考試的全國性結果可以顯示教育整體是否改善。"},{"en":"If nationwide results are positive, a programme may be expanded to more regions.","zh":"如果全國性結果正面，計劃可能擴展至更多地區。"},{"en":"The phrase is broader than one school, town, or district.","zh":"這個短語比一間學校、一個城鎮或一個地區更廣。"}],"source":"145 - Food for thought.pdf","sourcePage":9},{"front":"school feeding programmes","meaning":"學校供餐計劃","examples":[{"en":"School feeding programmes improved attendance and performance.","zh":"學校供餐計劃改善了出席率和表現。"},{"en":"School feeding programmes are organised plans that provide food to pupils at school.","zh":"school feeding programmes 是在學校為學生提供食物的有組織計劃。"},{"en":"School feeding programmes may include breakfast, lunch, or snacks.","zh":"學校供餐計劃可能包括早餐、午餐或小食。"},{"en":"If school feeding programmes reduce hunger, children may attend more regularly and learn better.","zh":"如果學校供餐計劃減少飢餓，孩子可能更定期上學並學得更好。"},{"en":"The phrase connects education policy with child nutrition.","zh":"這個短語把教育政策與兒童營養連繫起來。"}],"source":"145 - Food for thought.pdf","sourcePage":9},{"front":"pretty good","meaning":"相當不錯","examples":[{"en":"The nationwide results were still pretty good.","zh":"全國性結果仍然相當不錯。"},{"en":"Pretty good means quite good, though perhaps not perfect.","zh":"pretty good 指相當好，雖然未必完美。"},{"en":"Her first speech was pretty good because she was clear and confident.","zh":"她第一次演講相當不錯，因為她清晰而有自信。"},{"en":"If a programme helps attendance but not every exam result, it may still be pretty good.","zh":"如果一項計劃改善出席率但不是每項考試結果，它仍可能相當不錯。"},{"en":"The phrase is informal and slightly modest.","zh":"這個短語較口語，語氣略帶謙虛。"}],"source":"145 - Food for thought.pdf","sourcePage":9},{"front":"on average","meaning":"平均而言","examples":[{"en":"On average, school feeding attracted more pupils.","zh":"平均而言，學校供餐吸引了更多學生。"},{"en":"On average means considering the typical result after adding many cases together.","zh":"on average 指把許多個案合起來考慮後的典型結果。"},{"en":"On average, students who read daily learn vocabulary faster.","zh":"平均而言，每天閱讀的學生學詞彙較快。"},{"en":"If schools with meals attract more pupils on average, the policy may be useful.","zh":"如果提供膳食的學校平均而言吸引更多學生，該政策可能有用。"},{"en":"The phrase describes the general pattern, not every single case.","zh":"這個短語描述一般模式，而不是每一個個案。"}],"source":"145 - Food for thought.pdf","sourcePage":9},{"front":"hand out free food","meaning":"派發免費食物","examples":[{"en":"Schools started handing out free food to pupils.","zh":"學校開始向學生派發免費食物。"},{"en":"To hand out free food means to distribute food without asking people to pay.","zh":"hand out free food 指免費分發食物。"},{"en":"Volunteers hand out free food after floods or fires.","zh":"洪水或火災後，義工會派發免費食物。"},{"en":"If schools hand out free food, hungry children may be more willing to attend.","zh":"如果學校派發免費食物，飢餓孩子可能更願意上學。"},{"en":"The phrase focuses on giving food directly to many people.","zh":"這個短語重點在於直接向許多人給予食物。"}],"source":"145 - Food for thought.pdf","sourcePage":9},{"front":"attract more girls and boys","meaning":"吸引更多男女學生","examples":[{"en":"The programme attracted more girls and boys to school.","zh":"該計劃吸引更多男女學生上學。"},{"en":"To attract more girls and boys means to encourage more children of both sexes to attend or join.","zh":"attract more girls and boys 指鼓勵更多男女兒童出席或參加。"},{"en":"A sports day can attract more girls and boys if it includes different activities.","zh":"如果運動日包括不同活動，它可以吸引更多男女學生。"},{"en":"If a school meal programme attracts more girls and boys, enrolment rises.","zh":"如果學校膳食計劃吸引更多男女學生，入學人數會上升。"},{"en":"The phrase emphasises that both female and male pupils are included.","zh":"這個短語強調男女學生都包括在內。"}],"source":"145 - Food for thought.pdf","sourcePage":9},{"front":"stay about the same","meaning":"保持大致相同","examples":[{"en":"The pass rate for boys stayed about the same.","zh":"男孩的合格率保持大致相同。"},{"en":"To stay about the same means to change very little or remain nearly unchanged.","zh":"stay about the same 指變化很少或幾乎不變。"},{"en":"The price of bread stayed about the same this month.","zh":"今個月麵包價格保持大致相同。"},{"en":"If boys’ pass rates stay about the same while girls’ rates rise, the improvement is not equal.","zh":"如果男孩合格率保持大致相同，而女孩合格率上升，改善並不平均。"},{"en":"The phrase describes stability rather than growth or decline.","zh":"這個短語描述穩定，而不是增長或下降。"}],"source":"145 - Food for thought.pdf","sourcePage":9},{"front":"improve by","meaning":"上升了……","examples":[{"en":"The pass rate for girls improved by 9.5%.","zh":"女孩的合格率上升了9.5%。"},{"en":"Improve by a number means increase or become better by that amount.","zh":"improve by 某數字，指增加或改善了該幅度。"},{"en":"Her test score improved by ten marks after extra practice.","zh":"她額外練習後，測驗分數提高了十分。"},{"en":"If attendance improves by 20%, more children are coming to school regularly.","zh":"如果出席率上升了20%，代表更多孩子定期上學。"},{"en":"The phrase is used when the size of improvement is measured.","zh":"這個短語用於改善幅度可以量度時。"}],"source":"145 - Food for thought.pdf","sourcePage":9},{"front":"better nutrition","meaning":"更佳營養","examples":[{"en":"Better nutrition makes for brighter children.","zh":"更佳營養有助培養更聰明的兒童。"},{"en":"Better nutrition means people receive more suitable food and nutrients for healthy growth and function.","zh":"better nutrition 指人們獲得更適合健康成長和身體功能的食物與營養素。"},{"en":"Better nutrition at breakfast can help students stay awake in morning lessons.","zh":"早餐有更佳營養，可以幫助學生在上午課堂保持清醒。"},{"en":"If families get better nutrition, children may grow stronger and learn more easily.","zh":"如果家庭獲得更佳營養，孩子可能成長得更強壯，並更容易學習。"},{"en":"The phrase focuses on food quality as well as food quantity.","zh":"這個短語重點在於食物質素以及食物數量。"}],"source":"145 - Food for thought.pdf","sourcePage":9},{"front":"make for","meaning":"促成；有助於","examples":[{"en":"Better nutrition makes for brighter children.","zh":"更佳營養促成更聰明的兒童。"},{"en":"To make for something means to help create or lead to that result.","zh":"make for 某結果，意思是有助創造或導致該結果。"},{"en":"Clear instructions make for fewer mistakes in group work.","zh":"清晰指示有助於小組工作中減少錯誤。"},{"en":"If children eat enough good food, it can make for better concentration.","zh":"如果孩子吃到足夠好食物，這可有助於更好專注。"},{"en":"The phrase connects a cause with a likely positive result.","zh":"這個短語把原因與可能的正面結果連繫起來。"}],"source":"145 - Food for thought.pdf","sourcePage":9},{"front":"brighter children","meaning":"更聰明的兒童","examples":[{"en":"Well-fed children may become brighter learners.","zh":"吃得飽的兒童可能成為更聰明的學習者。"},{"en":"Brighter children are children who seem more alert, able to learn, and quick to understand.","zh":"brighter children 指看起來更清醒、更能學習和更快理解的兒童。"},{"en":"A calm classroom and enough sleep can help create brighter children.","zh":"安靜課室和足夠睡眠可以幫助培養更聰明的兒童。"},{"en":"If children are hungry every day, they may not show how bright they really are.","zh":"如果孩子每天飢餓，他們可能無法展現真正的聰明。"},{"en":"The phrase refers to learning ability and alertness, not only natural intelligence.","zh":"這個短語指學習能力和清醒程度，而不只是天生智力。"}],"source":"145 - Food for thought.pdf","sourcePage":10},{"front":"most immediately","meaning":"最直接地","examples":[{"en":"Most immediately, well-fed children find it easier to concentrate.","zh":"最直接地，吃得飽的孩子覺得較容易集中精神。"},{"en":"Most immediately means the first or most direct effect is this.","zh":"most immediately 指最先或最直接的影響是這個。"},{"en":"Most immediately, closing the road will increase travel time for nearby residents.","zh":"最直接地，封路會增加附近居民的交通時間。"},{"en":"If children receive lunch, most immediately they feel less hungry in afternoon lessons.","zh":"如果孩子獲得午餐，最直接地，他們在下午課會感到較少飢餓。"},{"en":"The phrase introduces the quickest visible result before deeper effects.","zh":"這個短語在較深層影響前，引出最快看見的結果。"}],"source":"145 - Food for thought.pdf","sourcePage":10},{"front":"well-fed children","meaning":"吃得飽、營養足的兒童","examples":[{"en":"Well-fed children can concentrate more easily.","zh":"吃得飽、營養足的兒童可以更容易集中精神。"},{"en":"Well-fed children are children who receive enough food and nutrients for healthy energy.","zh":"well-fed children 是獲得足夠食物和營養以維持健康能量的兒童。"},{"en":"Well-fed children are more likely to play, learn, and stay awake in class.","zh":"吃得飽、營養足的兒童更可能玩耍、學習並在課堂保持清醒。"},{"en":"If children are well-fed, teachers may notice fewer tired faces in the morning.","zh":"如果孩子吃得飽、營養足，老師可能在早上看見較少疲倦面孔。"},{"en":"The phrase describes both quantity and quality of food.","zh":"這個短語同時描述食物數量和質素。"}],"source":"145 - Food for thought.pdf","sourcePage":10},{"front":"find it easier to","meaning":"覺得較容易","examples":[{"en":"Well-fed children find it easier to concentrate.","zh":"吃得飽的孩子覺得較容易集中精神。"},{"en":"To find it easier to do something means to feel that the action is less difficult.","zh":"find it easier to do something 指覺得做某事較不困難。"},{"en":"Students find it easier to write essays when they have clear examples.","zh":"當學生有清晰例子，他們覺得較容易寫文章。"},{"en":"If children are not hungry, they may find it easier to listen to the teacher.","zh":"如果孩子不餓，他們可能覺得較容易聽老師講課。"},{"en":"The phrase describes a task becoming more manageable.","zh":"這個短語描述一項任務變得較容易處理。"}],"source":"145 - Food for thought.pdf","sourcePage":10},{"front":"concentrate","meaning":"集中精神","examples":[{"en":"Hungry children find it hard to concentrate.","zh":"飢餓的孩子覺得難以集中精神。"},{"en":"To concentrate means to give full attention to one task or idea.","zh":"concentrate 指把全部注意力放在一項任務或一個想法上。"},{"en":"Students concentrate better when their phones are put away.","zh":"當手機被收起，學生能更好集中精神。"},{"en":"If a child is hungry or worried, it becomes harder to concentrate on lessons.","zh":"如果孩子飢餓或擔心，就更難集中精神上課。"},{"en":"The word is often used when talking about study, work, and attention.","zh":"這個字常用於討論學習、工作和注意力。"}],"source":"145 - Food for thought.pdf","sourcePage":10},{"front":"focus the mind on","meaning":"將注意力集中於","examples":[{"en":"It is hard to focus the mind on mathematics when a child is hungry.","zh":"當孩子飢餓時，很難將注意力集中於數學。"},{"en":"To focus the mind on something means to direct attention and thought toward it.","zh":"focus the mind on 某事，意思是把注意力和思想導向它。"},{"en":"Deep breathing can help students focus the mind on the exam question.","zh":"深呼吸可以幫助學生將注意力集中於考試題目。"},{"en":"If your stomach hurts, it is difficult to focus the mind on reading.","zh":"如果你胃痛，就難以將注意力集中於閱讀。"},{"en":"The phrase is stronger than just looking; it means mental attention.","zh":"這個短語比只是觀看更強，意思是精神上的注意。"}],"source":"145 - Food for thought.pdf","sourcePage":10},{"front":"long division","meaning":"長除法","examples":[{"en":"Hungry children may struggle to focus on long division.","zh":"飢餓的孩子可能難以專注於長除法。"},{"en":"Long division is a written method for dividing large numbers step by step.","zh":"long division 是一步一步把大數相除的書面方法。"},{"en":"Teachers often use the board to show long division clearly.","zh":"老師常用黑板清楚示範長除法。"},{"en":"If students are tired, long division can feel confusing because it has several steps.","zh":"如果學生疲倦，長除法可能令人困惑，因為它有幾個步驟。"},{"en":"The phrase refers to a specific school mathematics skill.","zh":"這個短語指一項具體的學校數學技能。"}],"source":"145 - Food for thought.pdf","sourcePage":10},{"front":"your stomach is screaming for food","meaning":"肚子餓得難受","examples":[{"en":"It is hard to study when your stomach is screaming for food.","zh":"當你肚子餓得難受時，很難學習。"},{"en":"Your stomach is screaming for food means you feel extremely hungry.","zh":"your stomach is screaming for food 指你感到極度飢餓。"},{"en":"During a long exam, your stomach may be screaming for food if you skipped breakfast.","zh":"在長時間考試中，如果你沒吃早餐，可能會肚子餓得難受。"},{"en":"If a child’s stomach is screaming for food, concentration becomes very difficult.","zh":"如果孩子肚子餓得難受，集中精神會變得非常困難。"},{"en":"The phrase is figurative and makes hunger sound urgent and uncomfortable.","zh":"這個短語是比喻，令飢餓聽起來迫切而不舒服。"}],"source":"145 - Food for thought.pdf","sourcePage":10},{"front":"be easy to spot","meaning":"很容易看出","examples":[{"en":"It used to be easy to spot the undernourished children.","zh":"以往很容易看出營養不足的孩子。"},{"en":"To be easy to spot means to be easy to notice or recognise.","zh":"be easy to spot 指很容易注意到或辨認出來。"},{"en":"A bright red bag is easy to spot in a crowded classroom.","zh":"在擠迫課室中，鮮紅色書包很容易看出。"},{"en":"If a child is very tired and thin, poor health may be easy to spot.","zh":"如果孩子非常疲倦和瘦弱，健康差可能很容易看出。"},{"en":"The phrase is used when something stands out clearly.","zh":"這個短語用於某事很明顯突出時。"}],"source":"145 - Food for thought.pdf","sourcePage":10},{"front":"really undernourished","meaning":"嚴重營養不足的","examples":[{"en":"The really undernourished children often stared into space.","zh":"嚴重營養不足的孩子常常發呆。"},{"en":"Really undernourished means seriously lacking enough food and nutrients.","zh":"really undernourished 指嚴重缺乏足夠食物和營養。"},{"en":"Really undernourished children may look tired, thin, and unable to focus.","zh":"嚴重營養不足的孩子可能看起來疲倦、瘦弱且無法專注。"},{"en":"If a child is really undernourished, learning can become much harder.","zh":"如果孩子嚴重營養不足，學習會變得困難得多。"},{"en":"The word really strengthens the seriousness of undernourished.","zh":"really 一字加強 undernourished 的嚴重程度。"}],"source":"145 - Food for thought.pdf","sourcePage":10},{"front":"stare into space","meaning":"發呆；望着空中出神","examples":[{"en":"Undernourished children sometimes stared into space.","zh":"營養不足的孩子有時會發呆。"},{"en":"To stare into space means to look blankly at nothing, often because one is tired, sad, or unable to focus.","zh":"stare into space 指空洞地望着某處，通常因疲倦、悲傷或無法集中。"},{"en":"After a long day, a student may stare into space instead of doing homework.","zh":"漫長一天後，學生可能發呆而不是做功課。"},{"en":"If hungry pupils stare into space, teachers may realise they are too weak to answer.","zh":"如果飢餓學生望着空中出神，老師可能意識到他們太虛弱而無法回答。"},{"en":"The phrase suggests a lack of attention or energy.","zh":"這個短語暗示缺乏注意力或能量。"}],"source":"145 - Food for thought.pdf","sourcePage":10},{"front":"respond when","meaning":"在……時回應","examples":[{"en":"Some children did not respond when the teacher asked a question.","zh":"有些孩子在老師提問時沒有回應。"},{"en":"To respond when something happens means to answer or react at that moment.","zh":"respond when 某事發生，意思是在那一刻回答或作出反應。"},{"en":"Students should respond when their names are called during attendance.","zh":"點名時，學生應在聽到自己名字時回應。"},{"en":"If a child does not respond when spoken to, the teacher may check whether they are ill or upset.","zh":"如果孩子在別人跟他說話時沒有回應，老師可能檢查他是否生病或不開心。"},{"en":"The phrase links a reaction to a specific situation.","zh":"這個短語把反應連繫到特定情況。"}],"source":"145 - Food for thought.pdf","sourcePage":11},{"front":"more crucially","meaning":"更關鍵的是","examples":[{"en":"More crucially, food helps the brain grow and develop.","zh":"更關鍵的是，食物幫助大腦成長和發展。"},{"en":"More crucially means more importantly, especially when introducing the most serious point.","zh":"more crucially 指更重要的是，尤其用於引出最嚴重的重點。"},{"en":"Exercise improves mood; more crucially, it can reduce long-term health risks.","zh":"運動改善心情；更關鍵的是，它可以減少長期健康風險。"},{"en":"Food helps children concentrate; more crucially, it supports brain development.","zh":"食物幫助孩子集中精神；更關鍵的是，它支持大腦發展。"},{"en":"The phrase tells readers that the next point matters even more.","zh":"這個短語告訴讀者下一點更加重要。"}],"source":"145 - Food for thought.pdf","sourcePage":11},{"front":"brains grow and develop","meaning":"大腦成長和發展","examples":[{"en":"More and better food helps brains grow and develop.","zh":"更多和更好的食物幫助大腦成長和發展。"},{"en":"Brains grow and develop means children’s brains physically and mentally mature over time.","zh":"brains grow and develop 指兒童大腦在身體和心理上隨時間成熟。"},{"en":"Sleep, play, language, and good food all help young brains grow and develop.","zh":"睡眠、遊戲、語言和良好食物都幫助年幼大腦成長和發展。"},{"en":"If brains do not receive enough nutrients, learning and memory may suffer.","zh":"如果大腦得不到足夠營養，學習和記憶可能受損。"},{"en":"The phrase shows that the brain, like the body, needs support to mature.","zh":"這個短語顯示大腦像身體一樣需要支援才能成熟。"}],"source":"145 - Food for thought.pdf","sourcePage":11},{"front":"like any other organ","meaning":"像任何其他器官一樣","examples":[{"en":"Like any other organ, the brain needs nutrition.","zh":"像任何其他器官一樣，大腦需要營養。"},{"en":"Like any other organ means in the same way as the heart, lungs, liver, or other body parts.","zh":"like any other organ 指像心臟、肺、肝或其他身體部位一樣。"},{"en":"Like any other organ, the eyes need blood, oxygen, and nutrients.","zh":"像任何其他器官一樣，眼睛需要血液、氧氣和營養。"},{"en":"If the brain is like any other organ, poor nutrition can harm its growth.","zh":"如果大腦像任何其他器官一樣，營養差就會傷害其成長。"},{"en":"The phrase reminds readers that the brain is a physical part of the body.","zh":"這個短語提醒讀者，大腦是身體的一個實體部分。"}],"source":"145 - Food for thought.pdf","sourcePage":11},{"front":"be starved of","meaning":"缺乏……","examples":[{"en":"The brain can be starved of necessary nutrients.","zh":"大腦可能缺乏必需營養素。"},{"en":"To be starved of something means to be badly lacking something essential.","zh":"be starved of 某物，意思是嚴重缺乏某種必需東西。"},{"en":"Plants starved of water will stop growing properly.","zh":"缺乏水分的植物會停止正常生長。"},{"en":"If children are starved of protein and calories, their bodies and brains may suffer.","zh":"如果孩子缺乏蛋白質和熱量，他們的身體和大腦可能受損。"},{"en":"The phrase can be used literally for food or figuratively for support, attention, or information.","zh":"這個短語可字面用於食物，也可比喻用於支援、注意或資訊。"}],"source":"145 - Food for thought.pdf","sourcePage":11},{"front":"necessary calories","meaning":"必需熱量","examples":[{"en":"The brain needs necessary calories to develop properly.","zh":"大腦需要必需熱量才能正常發展。"},{"en":"Necessary calories are the energy from food that the body needs to function and grow.","zh":"necessary calories 是身體運作和成長所需的食物能量。"},{"en":"A child who eats too little may not get the necessary calories for school and play.","zh":"吃得太少的孩子可能得不到上學和玩耍所需的必需熱量。"},{"en":"If necessary calories are missing for a long time, growth can slow down.","zh":"如果長期缺少必需熱量，成長可能減慢。"},{"en":"The phrase focuses on food energy, not just vitamins.","zh":"這個短語重點在於食物能量，而不只是維他命。"}],"source":"145 - Food for thought.pdf","sourcePage":11},{"front":"proteins and micronutrients","meaning":"蛋白質和微量營養素","examples":[{"en":"The brain needs proteins and micronutrients.","zh":"大腦需要蛋白質和微量營養素。"},{"en":"Proteins and micronutrients are nutrients needed for growth, repair, and healthy body functions.","zh":"proteins and micronutrients 是成長、修復和健康身體功能所需的營養素。"},{"en":"Beans, eggs, vegetables, and fortified foods can provide proteins and micronutrients.","zh":"豆類、雞蛋、蔬菜和強化食品可以提供蛋白質和微量營養素。"},{"en":"If children lack proteins and micronutrients, they may become weaker and learn less effectively.","zh":"如果孩子缺乏蛋白質和微量營養素，他們可能變得較弱並學得較差。"},{"en":"The phrase combines major building materials with small but essential nutrients.","zh":"這個短語結合主要建造材料和少量但必需的營養素。"}],"source":"145 - Food for thought.pdf","sourcePage":11},{"front":"not as severely as","meaning":"不像……那樣嚴重","examples":[{"en":"The brain may be stunted, though not as severely as a muscle.","zh":"大腦可能發育受阻，雖然不像肌肉那樣嚴重。"},{"en":"Not as severely as means less seriously than something else.","zh":"not as severely as 指不如另一事物那麼嚴重。"},{"en":"His ankle was injured, but not as severely as his knee.","zh":"他的腳踝受傷，但不像膝蓋那樣嚴重。"},{"en":"A child’s brain may be affected by malnutrition, though not as severely as visible body growth.","zh":"兒童大腦可能受營養不良影響，雖然不像可見身體成長那樣嚴重。"},{"en":"The phrase compares two levels of damage or difficulty.","zh":"這個短語比較兩種傷害或困難的嚴重程度。"}],"source":"145 - Food for thought.pdf","sourcePage":11},{"front":"nonetheless","meaning":"儘管如此","examples":[{"en":"The brain may be stunted nonetheless.","zh":"儘管如此，大腦仍可能發育受阻。"},{"en":"Nonetheless means however, despite what has just been said.","zh":"nonetheless 指然而、儘管前面所說如此。"},{"en":"The medicine is expensive; nonetheless, it may be necessary.","zh":"這種藥很昂貴；儘管如此，它可能是必要的。"},{"en":"The damage may not be visible; nonetheless, poor nutrition can affect learning.","zh":"傷害可能不可見；儘管如此，營養差仍可影響學習。"},{"en":"The word introduces a point that remains true despite a contrast.","zh":"這個字引出一個儘管有對比仍然成立的重點。"}],"source":"145 - Food for thought.pdf","sourcePage":11},{"front":"work so well","meaning":"如此有效","examples":[{"en":"Feeding children at school works so well because nutrition helps learning.","zh":"在學校為孩子供餐如此有效，因為營養有助學習。"},{"en":"To work so well means to be very effective.","zh":"work so well 指非常有效。"},{"en":"Flashcards work so well for vocabulary because they encourage repeated recall.","zh":"生字卡對詞彙如此有效，因為它們鼓勵重複回想。"},{"en":"If school meals work so well, policymakers may consider expanding them.","zh":"如果學校膳食如此有效，政策制定者可能考慮擴展它們。"},{"en":"The phrase explains why a method produces strong results.","zh":"這個短語解釋為何一種方法產生強烈效果。"}],"source":"145 - Food for thought.pdf","sourcePage":11},{"front":"more pronounced in","meaning":"在……中更明顯","examples":[{"en":"The effect of feeding was more pronounced in girls than in boys.","zh":"供餐的效果在女孩中比男孩中更明顯。"},{"en":"More pronounced in one group means clearer, stronger, or more noticeable in that group.","zh":"more pronounced in 某群體，意思是在該群體中更清楚、更強或更明顯。"},{"en":"The benefit of extra reading may be more pronounced in students who rarely read at home.","zh":"額外閱讀的好處可能在家中很少閱讀的學生中更明顯。"},{"en":"If malnutrition affects girls more, the impact of school food may be more pronounced in girls.","zh":"如果營養不良對女孩影響更大，學校食物的影響可能在女孩中更明顯。"},{"en":"The phrase compares the strength of an effect across groups.","zh":"這個短語比較不同群體中某種效果的強度。"}],"source":"145 - Food for thought.pdf","sourcePage":11},{"front":"give a clue to","meaning":"提供……的線索","examples":[{"en":"The stronger effect in girls gives a clue to who eats first at home.","zh":"女孩中更強的效果，提供了家中誰先進食的線索。"},{"en":"To give a clue to something means to provide a sign or hint that helps explain it.","zh":"give a clue to 某事，意思是提供有助解釋它的跡象或提示。"},{"en":"A child’s tired face may give a clue to poor sleep at home.","zh":"孩子疲倦的面孔可能提供家中睡眠不足的線索。"},{"en":"If girls improve more after receiving food, it may give a clue to unequal food sharing at home.","zh":"如果女孩在獲得食物後改善更多，這可能提供家中食物分配不均的線索。"},{"en":"The phrase suggests evidence that points toward an explanation.","zh":"這個短語暗示有證據指向某個解釋。"}],"source":"145 - Food for thought.pdf","sourcePage":12},{"front":"rural Malawian households","meaning":"馬拉維農村家庭","examples":[{"en":"The effect gives a clue to food distribution in rural Malawian households.","zh":"這種效果提供了馬拉維農村家庭中食物分配的線索。"},{"en":"Rural Malawian households are families living in the countryside of Malawi.","zh":"rural Malawian households 是住在馬拉維鄉村地區的家庭。"},{"en":"Rural Malawian households may depend on farming, seasonal rain, and local markets.","zh":"馬拉維農村家庭可能依賴農業、季節性降雨和本地市場。"},{"en":"If food is scarce in rural Malawian households, children may not all eat equally.","zh":"如果馬拉維農村家庭食物短缺，孩子未必都能平等進食。"},{"en":"The phrase identifies both the location and family setting being discussed.","zh":"這個短語指出所討論的地點和家庭情境。"}],"source":"145 - Food for thought.pdf","sourcePage":12},{"front":"on a global scale","meaning":"從全球層面來看","examples":[{"en":"On a global scale, people are eating better than ever before.","zh":"從全球層面來看，人們吃得比以往任何時候都好。"},{"en":"On a global scale means considering the whole world, not just one country or village.","zh":"on a global scale 指考慮全世界，而不只是一個國家或村莊。"},{"en":"On a global scale, climate change affects farming, health, and migration.","zh":"從全球層面來看，氣候變化影響農業、健康和移民。"},{"en":"If hunger is falling on a global scale, many regions are improving, though some still suffer.","zh":"如果飢餓從全球層面下降，代表許多地區正在改善，雖然一些地方仍受苦。"},{"en":"The phrase broadens the discussion to worldwide patterns.","zh":"這個短語把討論擴展到全球模式。"}],"source":"145 - Food for thought.pdf","sourcePage":12},{"front":"the good news is that","meaning":"好消息是","examples":[{"en":"The good news is that people are eating better than ever before.","zh":"好消息是，人們吃得比以往任何時候都好。"},{"en":"The good news is that introduces a positive fact after concern or difficulty.","zh":"the good news is that 用來在憂慮或困難後引出正面事實。"},{"en":"The good news is that the clinic now opens on weekends.","zh":"好消息是，診所現在週末也開放。"},{"en":"After discussing hunger, the good news is that nutrition has improved in many places.","zh":"討論飢餓後，好消息是許多地方的營養已改善。"},{"en":"The phrase helps shift the tone from problem to hope.","zh":"這個短語幫助把語氣從問題轉向希望。"}],"source":"145 - Food for thought.pdf","sourcePage":12},{"front":"eat better than ever before","meaning":"吃得比以往任何時候都好","examples":[{"en":"People around the world are eating better than ever before.","zh":"世界各地的人吃得比以往任何時候都好。"},{"en":"To eat better than ever before means to have more food, better nutrients, or healthier diets than in the past.","zh":"eat better than ever before 指比過去有更多食物、更佳營養或更健康飲食。"},{"en":"Some families eat better than ever before after clean water and farming support improve.","zh":"在潔淨食水和農業支援改善後，一些家庭吃得比以往任何時候都好。"},{"en":"If people eat better than ever before, children may grow taller and healthier.","zh":"如果人們吃得比以往任何時候都好，孩子可能長得更高和更健康。"},{"en":"The phrase compares current nutrition with all earlier periods.","zh":"這個短語把現在的營養與所有以前時期作比較。"}],"source":"145 - Food for thought.pdf","sourcePage":12},{"front":"Homo sapiens","meaning":"智人；現代人類","examples":[{"en":"Homo sapiens has grown larger since the industrial revolution.","zh":"智人自工業革命以來體型變大。"},{"en":"Homo sapiens is the scientific name for modern human beings.","zh":"Homo sapiens 是現代人類的科學名稱。"},{"en":"In biology lessons, students learn that Homo sapiens belong to the human species.","zh":"在生物課中，學生學到 Homo sapiens 屬於人類物種。"},{"en":"If Homo sapiens became taller over time, better food and health may be part of the reason.","zh":"如果智人隨時間變得更高大，更好食物和健康可能是部分原因。"},{"en":"The term is scientific and formal, unlike the everyday word humans.","zh":"這個詞較科學和正式，不同於日常用語 humans。"}],"source":"145 - Food for thought.pdf","sourcePage":12},{"front":"grow 50% bigger","meaning":"長大了百分之五十","examples":[{"en":"Homo sapiens has grown 50% bigger since the industrial revolution.","zh":"智人自工業革命以來長大了百分之五十。"},{"en":"To grow 50% bigger means to increase in size by half of the original size.","zh":"grow 50% bigger 指大小增加了原本大小的一半。"},{"en":"A school garden may grow 50% bigger if another plot of land is added.","zh":"如果加入另一塊土地，學校花園可能長大百分之五十。"},{"en":"If average body size grows 50% bigger over centuries, living conditions must have changed greatly.","zh":"如果平均體型在幾個世紀中長大百分之五十，生活條件必定有巨大改變。"},{"en":"The phrase gives a measured size increase.","zh":"這個短語提供可量度的大小增加。"}],"source":"145 - Food for thought.pdf","sourcePage":12},{"front":"since the industrial revolution","meaning":"自工業革命以來","examples":[{"en":"Humans have grown larger since the industrial revolution.","zh":"人類自工業革命以來變得更高大。"},{"en":"Since the industrial revolution means from the period when machines and factories transformed production onward.","zh":"since the industrial revolution 指從機器和工廠改變生產方式的時期開始之後。"},{"en":"Since the industrial revolution, cities have become much larger.","zh":"自工業革命以來，城市變得大得多。"},{"en":"If nutrition improved since the industrial revolution, human bodies may have changed too.","zh":"如果營養自工業革命以來改善，人類身體也可能改變。"},{"en":"The phrase marks a long historical period of social and economic change.","zh":"這個短語標示一段長期的社會和經濟變化時期。"}],"source":"145 - Food for thought.pdf","sourcePage":12},{"front":"three centuries ago","meaning":"三個世紀前","examples":[{"en":"Three centuries ago, chronic malnutrition was widespread.","zh":"三個世紀前，長期營養不良很普遍。"},{"en":"Three centuries ago means about three hundred years in the past.","zh":"three centuries ago 指約三百年前。"},{"en":"Three centuries ago, most people travelled by foot, horse, or boat.","zh":"三個世紀前，大多數人步行、騎馬或乘船出行。"},{"en":"If food was scarce three centuries ago, many children may have grown more slowly.","zh":"如果三個世紀前食物短缺，許多孩子可能成長較慢。"},{"en":"The phrase places an event in a distant historical period.","zh":"這個短語把事件放在遙遠的歷史時期。"}],"source":"145 - Food for thought.pdf","sourcePage":12},{"front":"chronic malnutrition","meaning":"長期營養不良","examples":[{"en":"Chronic malnutrition was once nearly universal.","zh":"長期營養不良曾經幾乎普遍存在。"},{"en":"Chronic malnutrition is long-term lack of enough food or essential nutrients.","zh":"chronic malnutrition 是長期缺乏足夠食物或必需營養素。"},{"en":"Children with chronic malnutrition may be short for their age and often tired.","zh":"長期營養不良的兒童可能比同齡人矮，且常感疲倦。"},{"en":"If chronic malnutrition continues for years, it can harm both body and brain development.","zh":"如果長期營養不良持續多年，它可以傷害身體和大腦發展。"},{"en":"The word chronic means lasting a long time, not temporary.","zh":"chronic 一字指長期，而不是暫時。"}],"source":"145 - Food for thought.pdf","sourcePage":12},{"front":"more or less universal","meaning":"幾乎普遍存在","examples":[{"en":"Chronic malnutrition was more or less universal.","zh":"長期營養不良幾乎普遍存在。"},{"en":"More or less universal means almost everywhere or affecting almost everyone.","zh":"more or less universal 指幾乎到處都有或幾乎影響所有人。"},{"en":"Mobile phone use is more or less universal among adults in many cities.","zh":"在許多城市，成年人使用手機幾乎普遍存在。"},{"en":"If hunger was more or less universal, very few families escaped it.","zh":"如果飢餓幾乎普遍存在，就很少家庭能避開它。"},{"en":"The phrase allows a little exception while stressing a very broad pattern.","zh":"這個短語容許少量例外，同時強調非常廣泛的模式。"}],"source":"145 - Food for thought.pdf","sourcePage":12},{"front":"extremely rare","meaning":"極為罕見","examples":[{"en":"Chronic malnutrition is now extremely rare in rich countries.","zh":"長期營養不良現在在富裕國家極為罕見。"},{"en":"Extremely rare means very uncommon and almost never seen.","zh":"extremely rare 指非常不常見，幾乎看不到。"},{"en":"Snow is extremely rare in some tropical cities.","zh":"在一些熱帶城市，下雪極為罕見。"},{"en":"If chronic malnutrition becomes extremely rare, most families have enough basic food.","zh":"如果長期營養不良變得極為罕見，代表大多數家庭有足夠基本食物。"},{"en":"The phrase strongly emphasises how unusual something is.","zh":"這個短語強烈強調某事非常少見。"}],"source":"145 - Food for thought.pdf","sourcePage":13},{"front":"rich countries","meaning":"富裕國家","examples":[{"en":"Chronic malnutrition is rare in rich countries.","zh":"長期營養不良在富裕國家很少見。"},{"en":"Rich countries are countries with high income, strong public services, and many resources.","zh":"rich countries 是收入高、公共服務強和資源多的國家。"},{"en":"Rich countries often have hospitals, schools, and food systems that reduce extreme hunger.","zh":"富裕國家通常有醫院、學校和糧食系統，能減少極端飢餓。"},{"en":"If rich countries still have poor nutrition, the problem may be inequality rather than total food shortage.","zh":"如果富裕國家仍有營養差問題，問題可能是不平等，而不是整體食物短缺。"},{"en":"The phrase compares countries by wealth and resources.","zh":"這個短語按財富和資源比較國家。"}],"source":"145 - Food for thought.pdf","sourcePage":13},{"front":"developing countries","meaning":"發展中國家","examples":[{"en":"In developing countries, food supplies have also improved.","zh":"在發展中國家，食物供應也有所改善。"},{"en":"Developing countries are countries whose economies, services, and living standards are still growing or improving.","zh":"developing countries 是經濟、服務和生活水平仍在成長或改善的國家。"},{"en":"Some developing countries have expanded schools, clinics, and farming support quickly.","zh":"一些發展中國家快速擴展學校、診所和農業支援。"},{"en":"If food supplies improve in developing countries, child health may also improve.","zh":"如果發展中國家的食物供應改善，兒童健康也可能改善。"},{"en":"The phrase is broad and should be used carefully because countries differ greatly.","zh":"這個短語範圍很廣，應小心使用，因為各國差異很大。"}],"source":"145 - Food for thought.pdf","sourcePage":13},{"front":"plates and rice bowls are fuller","meaning":"盤子和飯碗更滿","examples":[{"en":"In developing countries, plates and rice bowls are fuller than before.","zh":"在發展中國家，盤子和飯碗比以前更滿。"},{"en":"Plates and rice bowls are fuller means people have more food to eat than in the past.","zh":"plates and rice bowls are fuller 指人們比過去有更多食物可吃。"},{"en":"After a good harvest, plates and rice bowls may be fuller in farming families.","zh":"收成良好後，農民家庭的盤子和飯碗可能更滿。"},{"en":"If plates and rice bowls are fuller, children may feel less hungry and grow better.","zh":"如果盤子和飯碗更滿，孩子可能較少飢餓並成長得更好。"},{"en":"The phrase uses a simple image to show improved food supply.","zh":"這個短語用簡單畫面展示食物供應改善。"}],"source":"145 - Food for thought.pdf","sourcePage":13},{"front":"the proportion of","meaning":"……的比例","examples":[{"en":"The proportion of stunted children has fallen.","zh":"發育遲緩兒童的比例已經下降。"},{"en":"The proportion of a group means the share or percentage of that group within a larger total.","zh":"the proportion of 某群體，指該群體在較大總數中的份額或百分比。"},{"en":"The proportion of students taking science rose this year.","zh":"今年修讀科學的學生比例上升。"},{"en":"If the proportion of hungry children falls, fewer children are affected than before.","zh":"如果飢餓兒童的比例下降，受影響兒童比以前少。"},{"en":"The phrase is useful for discussing statistics.","zh":"這個短語適合討論統計數據。"}],"source":"145 - Food for thought.pdf","sourcePage":13},{"front":"malnourished to the point of stunting","meaning":"營養不良至發育遲緩","examples":[{"en":"Many children were once malnourished to the point of stunting.","zh":"許多兒童曾經營養不良至發育遲緩。"},{"en":"Malnourished to the point of stunting means lacking nutrition so badly that normal growth is damaged.","zh":"malnourished to the point of stunting 指營養缺乏嚴重到正常成長受損。"},{"en":"A child malnourished to the point of stunting may be much shorter than expected for their age.","zh":"營養不良至發育遲緩的孩子，可能比同齡預期身高矮很多。"},{"en":"If food shortages last for years, more children may become malnourished to the point of stunting.","zh":"如果食物短缺持續多年，更多兒童可能營養不良至發育遲緩。"},{"en":"The phrase shows a severe result of long-term poor nutrition.","zh":"這個短語顯示長期營養差的嚴重結果。"}],"source":"145 - Food for thought.pdf","sourcePage":13},{"front":"fall from","meaning":"從……下降","examples":[{"en":"The proportion of stunted children fell from 39% to 30%.","zh":"發育遲緩兒童比例從39%下降至30%。"},{"en":"Fall from one number to another means decrease from the first level to the second.","zh":"fall from 一個數字 to 另一個數字，指從第一個水平下降到第二個水平。"},{"en":"The class absence rate fell from 12% to 5% after the new policy.","zh":"新政策後，班級缺席率從12%下降至5%。"},{"en":"If child stunting falls from a high percentage, nutrition is probably improving.","zh":"如果兒童發育遲緩比例從高百分比下降，營養可能正在改善。"},{"en":"The phrase is used to report a numerical decrease.","zh":"這個短語用於報告數字下降。"}],"source":"145 - Food for thought.pdf","sourcePage":13},{"front":"World Health Organisation","meaning":"世界衞生組織","examples":[{"en":"The World Health Organisation reported the fall in child malnutrition.","zh":"世界衞生組織報告了兒童營養不良下降。"},{"en":"The World Health Organisation is an international body that works on public health issues.","zh":"世界衞生組織是一個處理公共健康議題的國際機構。"},{"en":"The World Health Organisation may publish reports on nutrition, disease, and healthcare.","zh":"世界衞生組織可能發布關於營養、疾病和醫療的報告。"},{"en":"If the World Health Organisation reports improvement, governments may use the data for planning.","zh":"如果世界衞生組織報告改善，政府可能使用數據作規劃。"},{"en":"The phrase names a formal global health organisation.","zh":"這個短語指一個正式全球健康組織。"}],"source":"145 - Food for thought.pdf","sourcePage":13},{"front":"the battle against hunger","meaning":"對抗飢餓的戰役","examples":[{"en":"In many places, the battle against hunger is steadily being won.","zh":"在許多地方，對抗飢餓的戰役正逐步取得勝利。"},{"en":"The battle against hunger means the long effort to reduce or end hunger.","zh":"the battle against hunger 指減少或終結飢餓的長期努力。"},{"en":"Farmers, schools, clinics, and charities can all take part in the battle against hunger.","zh":"農民、學校、診所和慈善機構都可以參與對抗飢餓的戰役。"},{"en":"If child malnutrition falls, the battle against hunger is making progress.","zh":"如果兒童營養不良下降，對抗飢餓的戰役正在取得進展。"},{"en":"The phrase uses battle as a metaphor for a difficult public problem.","zh":"這個短語用 battle 作比喻，描述一個困難的公共問題。"}],"source":"145 - Food for thought.pdf","sourcePage":13},{"front":"steadily being won","meaning":"正逐步取得勝利","examples":[{"en":"The battle against hunger is steadily being won.","zh":"對抗飢餓的戰役正逐步取得勝利。"},{"en":"Steadily being won means progress is happening gradually and consistently.","zh":"steadily being won 指進展正逐漸而穩定地出現。"},{"en":"The fight against litter is steadily being won as more residents recycle.","zh":"隨着更多居民回收，對抗垃圾問題正逐步取得勝利。"},{"en":"If fewer children are underfed each year, the struggle is steadily being won.","zh":"如果每年營養不足的孩子減少，這場努力正逐步取得勝利。"},{"en":"The phrase suggests slow but real improvement.","zh":"這個短語暗示緩慢但真實的改善。"}],"source":"145 - Food for thought.pdf","sourcePage":13},{"front":"cleverer and more energetic","meaning":"更聰明、更有活力","examples":[{"en":"Better nutrition is making people cleverer and more energetic.","zh":"更佳營養正令人民更聰明、更有活力。"},{"en":"Cleverer and more energetic means better able to think and having more physical energy.","zh":"cleverer and more energetic 指更能思考，並有更多體力。"},{"en":"Students who sleep and eat well may become cleverer and more energetic in class.","zh":"睡得好、吃得好的學生在課堂上可能變得更聰明、更有活力。"},{"en":"If children receive enough nutrients, they may become cleverer and more energetic over time.","zh":"如果孩子獲得足夠營養，他們可能隨時間變得更聰明、更有活力。"},{"en":"The phrase links mental performance with physical strength.","zh":"這個短語把智力表現與身體力量連繫起來。"}],"source":"145 - Food for thought.pdf","sourcePage":13},{"front":"grow more prosperous","meaning":"變得更富裕","examples":[{"en":"Better nutrition may help people grow more prosperous.","zh":"更佳營養可能幫助人民變得更富裕。"},{"en":"To grow more prosperous means to become richer, more successful, or more economically secure over time.","zh":"grow more prosperous 指隨時間變得更富有、更成功或經濟上更穩定。"},{"en":"A town may grow more prosperous when new jobs and better schools appear.","zh":"當新工作和更好學校出現，小鎮可能變得更富裕。"},{"en":"If healthier children learn better, they may grow more prosperous as adults.","zh":"如果更健康的孩子學得更好，他們成年後可能變得更富裕。"},{"en":"The phrase describes gradual economic improvement.","zh":"這個短語描述逐步的經濟改善。"}],"source":"145 - Food for thought.pdf","sourcePage":14},{"front":"eventually","meaning":"最終","examples":[{"en":"People may eventually join the ranks of the well off.","zh":"人們可能最終加入富裕人士的行列。"},{"en":"Eventually means after some time or at the end of a process.","zh":"eventually 指一段時間後或一個過程結束時。"},{"en":"With steady practice, a beginner may eventually speak confidently.","zh":"透過穩定練習，初學者可能最終能自信說話。"},{"en":"If nutrition, education, and jobs improve, families may eventually escape poverty.","zh":"如果營養、教育和工作改善，家庭可能最終脫離貧窮。"},{"en":"The word shows that the result is not immediate.","zh":"這個字顯示結果不是即時出現。"}],"source":"145 - Food for thought.pdf","sourcePage":14},{"front":"join the ranks of","meaning":"加入……的行列","examples":[{"en":"Better nutrition may help people join the ranks of the well off.","zh":"更佳營養可能幫助人民加入富裕人士的行列。"},{"en":"To join the ranks of a group means to become part of that group.","zh":"join the ranks of 某群體，意思是成為該群體的一部分。"},{"en":"After years of study, she joined the ranks of qualified nurses.","zh":"經過多年學習，她加入合資格護士的行列。"},{"en":"If poor children grow healthy and educated, they may join the ranks of skilled workers.","zh":"如果貧困兒童健康成長並受教育，他們可能加入技術工人的行列。"},{"en":"The phrase often describes entering a social, professional, or economic group.","zh":"這個短語常描述進入某個社會、專業或經濟群體。"}],"source":"145 - Food for thought.pdf","sourcePage":14},{"front":"the well off","meaning":"富裕人士","examples":[{"en":"People who become richer may join the ranks of the well off.","zh":"變得較富有的人可能加入富裕人士的行列。"},{"en":"The well off are people who have enough money to live comfortably.","zh":"the well off 是有足夠金錢舒適生活的人。"},{"en":"The well off can usually afford good food, healthcare, and education.","zh":"富裕人士通常負擔得起良好食物、醫療和教育。"},{"en":"If more families become well off, the country’s middle class may grow.","zh":"如果更多家庭變得富裕，國家的中產階級可能擴大。"},{"en":"The phrase is polite and general, meaning financially comfortable people.","zh":"這個短語較禮貌和概括，指經濟上舒適的人。"}],"source":"145 - Food for thought.pdf","sourcePage":14},{"front":"start fretting about","meaning":"開始為……煩惱","examples":[{"en":"Richer people may start fretting about growing too fast.","zh":"較富有的人可能開始為長得太快而煩惱。"},{"en":"To start fretting about something means to begin worrying about it, often repeatedly.","zh":"start fretting about 某事，意思是開始反覆擔心某事。"},{"en":"Parents may start fretting about exam results months before the test.","zh":"家長可能在考試前幾個月就開始為成績煩惱。"},{"en":"If children grow very quickly, some parents start fretting about health and diet.","zh":"如果孩子長得很快，一些家長會開始為健康和飲食煩惱。"},{"en":"The phrase suggests anxious concern, not calm planning.","zh":"這個短語暗示焦慮擔心，而不是冷靜計劃。"}],"source":"145 - Food for thought.pdf","sourcePage":14},{"front":"grow too fast","meaning":"長得太快","examples":[{"en":"Some well-off people worry about children growing too fast.","zh":"一些富裕人士擔心孩子長得太快。"},{"en":"To grow too fast means to increase in size, height, or development more quickly than expected or desired.","zh":"grow too fast 指體型、身高或發展增長得比預期或希望更快。"},{"en":"A child may need new shoes often if they grow too fast.","zh":"如果孩子長得太快，可能經常需要新鞋。"},{"en":"If a city grows too fast, housing, schools, and roads may not keep up.","zh":"如果城市發展太快，房屋、學校和道路可能跟不上。"},{"en":"The phrase can describe bodies, businesses, cities, or problems.","zh":"這個短語可以描述身體、企業、城市或問題。"}],"source":"145 - Food for thought.pdf","sourcePage":14},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Students choose the correct heading for each paragraph.","zh":"學生為每段選出正確標題。"},{"en":"To choose the correct heading means to select the title that best matches the main idea.","zh":"choose the correct heading 指選出最符合主旨的標題。"},{"en":"In a reading exam, students choose the correct heading after identifying the paragraph’s purpose.","zh":"在閱讀考試中，學生識別段落目的後選出正確標題。"},{"en":"If students focus only on one detail, they may fail to choose the correct heading.","zh":"如果學生只專注一個細節，可能無法選出正確標題。"},{"en":"The phrase is common in IELTS-style reading tasks.","zh":"這個短語常見於IELTS式閱讀題。"}],"source":"145 - Food for thought.pdf","sourcePage":14},{"front":"from the list below","meaning":"從以下列表中","examples":[{"en":"The headings are chosen from the list below.","zh":"標題從以下列表中選出。"},{"en":"From the list below means from the options printed underneath the instruction.","zh":"from the list below 指從指示下面列出的選項中選擇。"},{"en":"Choose one answer from the list below and write the letter clearly.","zh":"從以下列表中選擇一個答案，並清楚寫上字母。"},{"en":"If the answer must come from the list below, students should not invent their own heading.","zh":"如果答案必須從以下列表中選出，學生不應自己創作標題。"},{"en":"The phrase limits choices to the given options.","zh":"這個短語把選擇限制在已給選項內。"}],"source":"145 - Food for thought.pdf","sourcePage":14},{"front":"write the correct number","meaning":"寫上正確號碼","examples":[{"en":"Students write the correct number on the answer sheet.","zh":"學生在答題紙上寫上正確號碼。"},{"en":"To write the correct number means to record the number of the chosen option.","zh":"write the correct number 指寫下所選選項的號碼。"},{"en":"In a matching task, students write the correct number beside each paragraph letter.","zh":"在配對題中，學生在每個段落字母旁寫上正確號碼。"},{"en":"If students write the wrong number, the answer may be marked wrong even if their thinking was right.","zh":"如果學生寫錯號碼，即使想法正確，答案也可能被判錯。"},{"en":"The phrase is an exam instruction about answer format.","zh":"這個短語是關於答案格式的考試指示。"}],"source":"145 - Food for thought.pdf","sourcePage":14},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生在答題紙上寫下答案。"},{"en":"On your answer sheet means in the official place provided for recording answers.","zh":"on your answer sheet 指在官方提供用來記錄答案的地方。"},{"en":"Write your name clearly on your answer sheet before the test begins.","zh":"考試開始前，請在答題紙上清楚寫上姓名。"},{"en":"If an answer is written in the question booklet but not on your answer sheet, it may not be marked.","zh":"如果答案寫在題目簿而不是答題紙上，可能不會被評分。"},{"en":"The phrase tells students where to put their final answers.","zh":"這個短語告訴學生把最終答案放在哪裏。"}],"source":"145 - Food for thought.pdf","sourcePage":14},{"front":"why better food helps","meaning":"為何較佳食物有助……","examples":[{"en":"One heading asks why better food helps students’ learning.","zh":"其中一個標題問為何較佳食物有助學生學習。"},{"en":"Why better food helps means the reason improved nutrition produces a positive effect.","zh":"why better food helps 指改善營養產生正面效果的原因。"},{"en":"A teacher may explain why better food helps children stay awake in class.","zh":"老師可能解釋為何較佳食物有助孩子在課堂保持清醒。"},{"en":"If students understand why better food helps, they can link nutrition with learning results.","zh":"如果學生理解為何較佳食物有助，他們可以把營養與學習結果連繫起來。"},{"en":"The phrase introduces cause, not just description.","zh":"這個短語引出原因，而不只是描述。"}],"source":"145 - Food for thought.pdf","sourcePage":14},{"front":"students’ learning","meaning":"學生學習","examples":[{"en":"Better food helps students’ learning.","zh":"較佳食物有助學生學習。"},{"en":"Students’ learning means how students gain knowledge, skills, and understanding.","zh":"students’ learning 指學生如何獲得知識、技能和理解。"},{"en":"Sleep, quiet classrooms, and good feedback all support students’ learning.","zh":"睡眠、安靜課室和良好回饋都支持學生學習。"},{"en":"If hunger affects students’ learning, meals can become part of education policy.","zh":"如果飢餓影響學生學習，膳食可以成為教育政策的一部分。"},{"en":"The phrase focuses on the learning process, not only exam scores.","zh":"這個短語重點在於學習過程，而不只是考試分數。"}],"source":"145 - Food for thought.pdf","sourcePage":15},{"front":"a song for getting porridge","meaning":"領粥之歌","examples":[{"en":"The children sing a song for getting porridge.","zh":"孩子們唱一首領粥之歌。"},{"en":"A song for getting porridge is a song connected with receiving porridge.","zh":"a song for getting porridge 是與領取粥有關的歌曲。"},{"en":"Children may sing a song for getting porridge while waiting in line for lunch.","zh":"孩子等候午餐排隊時，可能唱一首領粥之歌。"},{"en":"If a meal becomes linked with music, a song for getting porridge can make the routine joyful.","zh":"如果膳食與音樂連繫起來，領粥之歌可以令日常程序變得愉快。"},{"en":"The phrase describes the purpose or occasion of the song.","zh":"這個短語描述歌曲的用途或場合。"}],"source":"145 - Food for thought.pdf","sourcePage":15},{"front":"surprising use of","meaning":"……的意外用途","examples":[{"en":"The passage describes a surprising use of school premises.","zh":"文章描述校舍的一個意外用途。"},{"en":"A surprising use of something is a use that people would not normally expect.","zh":"surprising use of 某物，指人們通常不會預期的用途。"},{"en":"Turning a car park into a weekend market is a surprising use of public space.","zh":"把停車場變成週末市集，是公共空間的一個意外用途。"},{"en":"If a classroom stores food instead of holding lessons, that is a surprising use of school space.","zh":"如果課室用來存放食物而不是上課，那就是學校空間的意外用途。"},{"en":"The phrase highlights an unusual function.","zh":"這個短語突出不尋常的功能。"}],"source":"145 - Food for thought.pdf","sourcePage":15},{"front":"school premises","meaning":"校舍；學校場地","examples":[{"en":"One classroom on the school premises is used to store food.","zh":"學校場地內其中一間課室用來存放食物。"},{"en":"School premises are the buildings and land belonging to a school.","zh":"school premises 是屬於學校的建築物和土地。"},{"en":"Visitors must sign in before entering the school premises.","zh":"訪客進入校舍前必須登記。"},{"en":"If food is stored on school premises, the area must be safe and clean.","zh":"如果食物存放在學校場地內，該地方必須安全和潔淨。"},{"en":"The phrase refers to the whole school site, not only classrooms.","zh":"這個短語指整個學校地點，而不只是課室。"}],"source":"145 - Food for thought.pdf","sourcePage":15},{"front":"global perspective","meaning":"全球角度","examples":[{"en":"The final paragraph gives a global perspective on nutrition.","zh":"最後一段從全球角度看營養。"},{"en":"A global perspective looks at an issue across the whole world rather than one place.","zh":"global perspective 指從全世界而非單一地方看一個議題。"},{"en":"A global perspective on education compares schools in rich and poor countries.","zh":"教育的全球角度會比較富裕和貧困國家的學校。"},{"en":"If a report gives a global perspective, readers can see whether a local problem is part of a wider trend.","zh":"如果報告提供全球角度，讀者可以看見本地問題是否屬於更廣泛趨勢。"},{"en":"The phrase broadens understanding beyond one community.","zh":"這個短語把理解擴展到一個社區以外。"}],"source":"145 - Food for thought.pdf","sourcePage":15},{"front":"brains can be starved","meaning":"大腦也會缺乏營養","examples":[{"en":"The passage explains that brains can be starved of nutrients.","zh":"文章解釋大腦也會缺乏營養。"},{"en":"Brains can be starved means brains can lack the nutrients they need to grow and work properly.","zh":"brains can be starved 指大腦可能缺乏成長和正常運作所需的營養。"},{"en":"Young brains can be starved if children do not receive enough calories and protein.","zh":"如果兒童得不到足夠熱量和蛋白質，年幼大腦可能缺乏營養。"},{"en":"If brains are starved for years, learning and concentration may be affected.","zh":"如果大腦多年缺乏營養，學習和專注力可能受影響。"},{"en":"The phrase treats the brain as a living organ that needs food.","zh":"這個短語把大腦視為需要食物的活器官。"}],"source":"145 - Food for thought.pdf","sourcePage":15},{"front":"a surprising academic outcome","meaning":"意想不到的學業結果","examples":[{"en":"The feeding programme produced a surprising academic outcome.","zh":"供餐計劃產生了意想不到的學業結果。"},{"en":"A surprising academic outcome is an unexpected result related to learning, exams, or school performance.","zh":"a surprising academic outcome 是與學習、考試或學校表現有關的意外結果。"},{"en":"A breakfast club may produce a surprising academic outcome if reading scores rise.","zh":"如果閱讀分數上升，早餐小組可能產生意想不到的學業結果。"},{"en":"If free meals improve pass rates, the academic outcome may surprise people who expected standards to fall.","zh":"如果免費膳食改善合格率，這個學業結果可能令預期水平下降的人驚訝。"},{"en":"The phrase links education results with an unexpected cause or situation.","zh":"這個短語把教育結果與意外原因或情況連繫起來。"}],"source":"145 - Food for thought.pdf","sourcePage":15},{"front":"special treatment","meaning":"特別待遇","examples":[{"en":"Girls receive special treatment in the programme.","zh":"女孩在計劃中獲得特別待遇。"},{"en":"Special treatment means different or extra attention, help, or benefits given to a particular group.","zh":"special treatment 指給予某個特定群體不同或額外的關注、幫助或好處。"},{"en":"A student with a broken arm may receive special treatment during an exam.","zh":"手臂骨折的學生可能在考試中獲得特別待遇。"},{"en":"If girls are more likely to miss school, special treatment may be used to encourage attendance.","zh":"如果女孩更可能缺課，特別待遇可用來鼓勵出席。"},{"en":"The phrase can be neutral, positive, or negative depending on whether the reason is fair.","zh":"這個短語可中性、正面或負面，視乎原因是否公平。"}],"source":"145 - Food for thought.pdf","sourcePage":15},{"front":"how the programme is operated","meaning":"計劃如何運作","examples":[{"en":"The passage explains how the food programme is operated.","zh":"文章解釋食物計劃如何運作。"},{"en":"How the programme is operated means the way the programme is run in practice.","zh":"how the programme is operated 指該計劃在實際上如何運行。"},{"en":"A report may describe how the programme is operated, including who cooks and who pays.","zh":"報告可能描述計劃如何運作，包括誰煮食和誰付款。"},{"en":"If people know how the programme is operated, they can judge whether it is sustainable.","zh":"如果人們知道計劃如何運作，就能判斷它是否可持續。"},{"en":"The phrase focuses on practical steps, not just the programme’s aim.","zh":"這個短語重點在於實際步驟，而不只是計劃目標。"}],"source":"145 - Food for thought.pdf","sourcePage":15},{"front":"school attendance","meaning":"上學率；出席率","examples":[{"en":"The food programme affects school attendance.","zh":"食物計劃影響上學率。"},{"en":"School attendance means how regularly students go to school.","zh":"school attendance 指學生上學的規律程度。"},{"en":"Bad weather can reduce school attendance in remote villages.","zh":"惡劣天氣可以降低偏遠村莊的上學率。"},{"en":"If free meals improve school attendance, more children receive regular lessons.","zh":"如果免費膳食改善上學率，更多孩子會接受定期課堂。"},{"en":"The phrase measures presence at school, not exam performance directly.","zh":"這個短語衡量是否到校，而不是直接衡量考試表現。"}],"source":"145 - Food for thought.pdf","sourcePage":15},{"front":"usual causes","meaning":"常見原因","examples":[{"en":"The passage says Malawi lacks some of the usual causes of famine.","zh":"文章說馬拉維缺少一些饑荒的常見原因。"},{"en":"Usual causes are the common reasons that normally lead to a problem.","zh":"usual causes 是通常導致問題的常見原因。"},{"en":"The usual causes of traffic jams include accidents, roadworks, and too many cars.","zh":"交通擠塞的常見原因包括意外、道路工程和車輛太多。"},{"en":"If hunger exists without the usual causes of famine, researchers must look deeper.","zh":"如果沒有饑荒的常見原因卻存在飢餓，研究人員必須更深入尋找原因。"},{"en":"The phrase refers to expected explanations.","zh":"這個短語指預期中的解釋。"}],"source":"145 - Food for thought.pdf","sourcePage":15},{"front":"maintain academic standards","meaning":"維持學術水平","examples":[{"en":"Schools need to maintain academic standards despite rising enrolment.","zh":"學校需要在入學人數上升下維持學術水平。"},{"en":"To maintain academic standards means to keep the quality of teaching and learning at a good level.","zh":"maintain academic standards 指保持教與學質素在良好水平。"},{"en":"A school may hire more teachers to maintain academic standards when classes grow.","zh":"當班級擴大時，學校可能聘請更多教師以維持學術水平。"},{"en":"If resources do not increase, it becomes harder to maintain academic standards.","zh":"如果資源沒有增加，維持學術水平會變得更困難。"},{"en":"The phrase focuses on protecting learning quality over time.","zh":"這個短語重點在於長期保護學習質素。"}],"source":"145 - Food for thought.pdf","sourcePage":16},{"front":"complete the sentences below","meaning":"完成以下句子","examples":[{"en":"Students complete the sentences below using words from the passage.","zh":"學生使用文章中的字詞完成以下句子。"},{"en":"Complete the sentences below means fill in the missing words in the sentences that follow.","zh":"complete the sentences below 指填寫下面句子中的空缺字詞。"},{"en":"In reading practice, students complete the sentences below by finding exact information.","zh":"在閱讀練習中，學生透過尋找準確資料完成以下句子。"},{"en":"If students ignore grammar, they may choose words that do not complete the sentences correctly.","zh":"如果學生忽略文法，可能選出不能正確完成句子的字詞。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"145 - Food for thought.pdf","sourcePage":16},{"front":"using no more than","meaning":"使用不超過……","examples":[{"en":"Students complete the answers using no more than two words.","zh":"學生使用不超過兩個字完成答案。"},{"en":"Using no more than means the answer must not exceed the stated limit.","zh":"using no more than 指答案不得超過指定限制。"},{"en":"If the instruction says using no more than three words, four words will be too many.","zh":"如果指示說使用不超過三個字，四個字就太多。"},{"en":"Students may lose marks if they break the word limit, even with the right idea.","zh":"即使意思正確，學生如果違反字數限制也可能失分。"},{"en":"The phrase sets a strict answer length.","zh":"這個短語設定嚴格答案長度。"}],"source":"145 - Food for thought.pdf","sourcePage":16},{"front":"no more than two words and/or a number","meaning":"不超過兩個字及／或一個數字","examples":[{"en":"Students should use no more than two words and/or a number.","zh":"學生應使用不超過兩個字及／或一個數字。"},{"en":"No more than two words and/or a number means the answer may contain up to two words, a number, or both.","zh":"no more than two words and/or a number 指答案可包含最多兩個英文單字、一個數字，或兩者。"},{"en":"An answer like “9.5%” may fit if the instruction allows a number.","zh":"如果指示容許數字，像 9.5% 這樣的答案可能符合要求。"},{"en":"If students write a full sentence, they may exceed no more than two words and/or a number.","zh":"如果學生寫完整句子，可能超出不超過兩個字及／或一個數字的限制。"},{"en":"The phrase tells candidates both the word limit and whether numbers are allowed.","zh":"這個短語告訴考生字數限制以及是否可用數字。"}],"source":"145 - Food for thought.pdf","sourcePage":16},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must come from the passage.","zh":"答案必須從文章中得出。"},{"en":"From the passage means the information or words should be taken from the reading text.","zh":"from the passage 指資料或字詞應取自閱讀文章。"},{"en":"In summary completion, students must choose words from the passage, not from memory.","zh":"在摘要填充題中，學生必須從文章中選字，而不是靠記憶創作。"},{"en":"If an answer is not from the passage, it may be marked wrong even if it sounds sensible.","zh":"如果答案不是從文章中得出，即使聽起來合理，也可能被判錯。"},{"en":"The phrase limits answers to source-based evidence.","zh":"這個短語把答案限制在有文本根據的資料上。"}],"source":"145 - Food for thought.pdf","sourcePage":16},{"front":"offered exclusively to","meaning":"專門提供給……","examples":[{"en":"Extra snacks are offered exclusively to girls in the programme.","zh":"額外小食在計劃中專門提供給女孩。"},{"en":"Offered exclusively to a group means given only to that group and not to others.","zh":"offered exclusively to 某群體，指只提供給該群體，而不給其他人。"},{"en":"A discount may be offered exclusively to students with valid ID cards.","zh":"折扣可能專門提供給持有效學生證的學生。"},{"en":"If snacks are offered exclusively to girls, the programme is trying to solve a specific inequality.","zh":"如果小食專門提供給女孩，該計劃正嘗試解決特定不平等。"},{"en":"The phrase stresses that access is limited to one group.","zh":"這個短語強調使用權限只限於一個群體。"}],"source":"145 - Food for thought.pdf","sourcePage":16},{"front":"instead of going to school","meaning":"而不是上學","examples":[{"en":"Some children work instead of going to school.","zh":"一些孩子工作而不是上學。"},{"en":"Instead of going to school means doing another activity in place of attending school.","zh":"instead of going to school 指做另一件事來取代上學。"},{"en":"A child may sell fruit instead of going to school if the family needs money.","zh":"如果家庭需要金錢，孩子可能賣水果而不是上學。"},{"en":"If children work instead of going to school, their future choices may become narrower.","zh":"如果孩子工作而不是上學，他們未來選擇可能變窄。"},{"en":"The phrase shows a direct contrast between work and education.","zh":"這個短語顯示工作與教育之間的直接對比。"}],"source":"145 - Food for thought.pdf","sourcePage":16},{"front":"children in poverty","meaning":"貧困兒童","examples":[{"en":"Children in poverty may be sent to work.","zh":"貧困兒童可能被派去工作。"},{"en":"Children in poverty are children living in families without enough money or resources for basic needs.","zh":"children in poverty 是生活在缺乏足夠金錢或資源滿足基本需要的家庭中的兒童。"},{"en":"Children in poverty may lack food, books, safe housing, or medical care.","zh":"貧困兒童可能缺乏食物、書本、安全住所或醫療。"},{"en":"If children in poverty must work, their schooling may suffer.","zh":"如果貧困兒童必須工作，他們的學業可能受損。"},{"en":"The phrase focuses on children affected by economic hardship.","zh":"這個短語重點在於受經濟困難影響的兒童。"}],"source":"145 - Food for thought.pdf","sourcePage":16},{"front":"collect firewood","meaning":"收集柴枝","examples":[{"en":"Some children are sent to collect firewood.","zh":"一些孩子被派去收集柴枝。"},{"en":"To collect firewood means to gather pieces of wood for cooking, heating, or light.","zh":"collect firewood 指收集木柴，用作煮食、取暖或照明。"},{"en":"Rural families may collect firewood before preparing the evening meal.","zh":"鄉村家庭可能在準備晚餐前收集柴枝。"},{"en":"If children spend the morning collecting firewood, they may arrive late to school.","zh":"如果孩子早上花時間收集柴枝，可能會遲到上學。"},{"en":"The phrase describes a common task where other fuel is limited or costly.","zh":"這個短語描述在其他燃料有限或昂貴時常見的工作。"}],"source":"145 - Food for thought.pdf","sourcePage":16},{"front":"with the help of","meaning":"在……幫助下","examples":[{"en":"The pass rate improved with the help of the feeding programme.","zh":"合格率在供餐計劃幫助下有所改善。"},{"en":"With the help of something means because something provided support or made success easier.","zh":"with the help of 某物，意思是因為它提供支援或令成功較容易。"},{"en":"With the help of a dictionary, students can understand difficult articles.","zh":"在字典幫助下，學生可以理解困難文章。"},{"en":"If pass rates rise with the help of school meals, food is supporting education.","zh":"如果合格率在學校膳食幫助下上升，食物正在支援教育。"},{"en":"The phrase shows that one factor contributed to the result.","zh":"這個短語顯示某因素對結果有貢獻。"}],"source":"145 - Food for thought.pdf","sourcePage":16},{"front":"the modern human","meaning":"現代人類","examples":[{"en":"The size of the modern human has grown since the industrial revolution.","zh":"現代人類的體型自工業革命以來已經變大。"},{"en":"The modern human means people of today or the human species in its present form.","zh":"the modern human 指今天的人，或現今形式的人類物種。"},{"en":"The modern human lives with technologies that earlier generations never saw.","zh":"現代人類與早期世代從未見過的科技一起生活。"},{"en":"If the modern human is taller than ancestors were, nutrition and medicine may be reasons.","zh":"如果現代人類比祖先高大，營養和醫學可能是原因。"},{"en":"The phrase is used when comparing present-day humans with people in the past.","zh":"這個短語用於把今天人類與過去人類作比較時。"}],"source":"145 - Food for thought.pdf","sourcePage":16},{"front":"choose two letters","meaning":"選擇兩個字母","examples":[{"en":"Students choose two letters from the list.","zh":"學生從列表中選擇兩個字母。"},{"en":"Choose two letters means select exactly two lettered options, such as A and C.","zh":"choose two letters 指選出剛好兩個以字母標示的選項，例如A和C。"},{"en":"In a multiple-answer question, students may need to choose two letters instead of one.","zh":"在多答案題中，學生可能需要選擇兩個字母，而不是一個。"},{"en":"If candidates choose three letters, the answer may not follow the instruction.","zh":"如果考生選三個字母，答案可能不符合指示。"},{"en":"The phrase tells students the exact number of options required.","zh":"這個短語告訴學生所需選項的準確數量。"}],"source":"145 - Food for thought.pdf","sourcePage":17},{"front":"the following statements","meaning":"以下陳述","examples":[{"en":"Students decide which of the following statements are true.","zh":"學生判斷以下陳述哪些正確。"},{"en":"The following statements are the sentences or claims listed after the instruction.","zh":"the following statements 是指示後列出的句子或說法。"},{"en":"Read the following statements carefully before looking back at the passage.","zh":"回看文章前，先仔細閱讀以下陳述。"},{"en":"If the following statements contain small changes in meaning, students must compare them closely with the text.","zh":"如果以下陳述包含細微意思改變，學生必須仔細與文本比較。"},{"en":"The phrase points to the information that comes next.","zh":"這個短語指向接下來的資料。"}],"source":"145 - Food for thought.pdf","sourcePage":17},{"front":"in the open air","meaning":"在戶外","examples":[{"en":"Some children are taught in the open air.","zh":"一些孩子在戶外上課。"},{"en":"In the open air means outside, not inside a building.","zh":"in the open air 指在室外，而不是建築物內。"},{"en":"A music concert in the open air may be cancelled if it rains.","zh":"戶外音樂會如果下雨可能取消。"},{"en":"If lessons happen in the open air, heat, wind, and noise can affect learning.","zh":"如果課堂在戶外進行，炎熱、風和噪音都可能影響學習。"},{"en":"The phrase describes outdoor conditions.","zh":"這個短語描述戶外環境。"}],"source":"145 - Food for thought.pdf","sourcePage":17},{"front":"have trouble feeding","meaning":"難以養活……","examples":[{"en":"Some countries have trouble feeding their people.","zh":"一些國家難以養活其人民。"},{"en":"To have trouble feeding people means to struggle to provide enough food for them.","zh":"have trouble feeding people 指難以為人們提供足夠食物。"},{"en":"A family may have trouble feeding everyone if the main income earner loses a job.","zh":"如果主要收入者失業，一個家庭可能難以養活所有人。"},{"en":"If a country has trouble feeding its people, child health and social stability may suffer.","zh":"如果國家難以養活人民，兒童健康和社會穩定可能受損。"},{"en":"The phrase describes difficulty meeting basic food needs.","zh":"這個短語描述滿足基本食物需要的困難。"}],"source":"145 - Food for thought.pdf","sourcePage":17},{"front":"large population","meaning":"大量人口","examples":[{"en":"The option refers to a large population.","zh":"該選項提到大量人口。"},{"en":"A large population means a great number of people living in an area or country.","zh":"large population 指生活在某地區或國家的大量人。"},{"en":"A city with a large population needs many schools, hospitals, and buses.","zh":"擁有大量人口的城市需要許多學校、醫院和巴士。"},{"en":"If food production does not keep up with a large population, shortages may occur.","zh":"如果食物生產跟不上大量人口，可能出現短缺。"},{"en":"The phrase describes size of population, not how rich or poor people are.","zh":"這個短語描述人口規模，而不是人民貧富。"}],"source":"145 - Food for thought.pdf","sourcePage":17},{"front":"staff members","meaning":"職員；教職員","examples":[{"en":"No new staff members were recruited when attendance rose.","zh":"出席率上升時，沒有新教職員被招聘。"},{"en":"Staff members are people who work for an organisation, school, or business.","zh":"staff members 是為組織、學校或企業工作的人。"},{"en":"A hospital needs enough staff members to care for patients safely.","zh":"醫院需要足夠職員安全照顧病人。"},{"en":"If student numbers rise but staff members do not increase, workload becomes heavier.","zh":"如果學生人數上升但教職員沒有增加，工作量會變重。"},{"en":"The phrase is a general term for employees or workers.","zh":"這個短語是員工或工作人員的一般稱呼。"}],"source":"145 - Food for thought.pdf","sourcePage":17},{"front":"be recruited","meaning":"被招聘","examples":[{"en":"No new staff members were recruited when attendance increased.","zh":"出席率增加時，沒有新教職員被招聘。"},{"en":"To be recruited means to be hired or brought into an organisation to work.","zh":"be recruited 指被聘請或被吸納進組織工作。"},{"en":"New nurses were recruited after the hospital expanded.","zh":"醫院擴建後，新護士被招聘。"},{"en":"If more teachers are not recruited, larger classes may become harder to manage.","zh":"如果沒有招聘更多教師，較大的班級可能更難管理。"},{"en":"The phrase is often used in employment and staffing contexts.","zh":"這個短語常用於僱用和人手安排語境。"}],"source":"145 - Food for thought.pdf","sourcePage":17},{"front":"attendance rose","meaning":"出席率上升","examples":[{"en":"Attendance rose after the feeding programme began.","zh":"供餐計劃開始後，出席率上升。"},{"en":"Attendance rose means more people started coming regularly.","zh":"attendance rose 指更多人開始定期出席。"},{"en":"Class attendance rose when lessons became more practical and interesting.","zh":"當課堂變得更實用和有趣，班級出席率上升。"},{"en":"If attendance rose after free meals were offered, food may have encouraged pupils to come.","zh":"如果提供免費膳食後出席率上升，食物可能鼓勵學生到校。"},{"en":"The phrase reports an increase in presence.","zh":"這個短語報告出席人數增加。"}],"source":"145 - Food for thought.pdf","sourcePage":17},{"front":"enjoy a higher status than","meaning":"享有比……更高的地位","examples":[{"en":"The question asks whether girls enjoy a higher status than boys.","zh":"題目問女孩是否享有比男孩更高的地位。"},{"en":"To enjoy a higher status than someone means to be treated as more important or respected.","zh":"enjoy a higher status than 某人，意思是被視為比某人更重要或更受尊重。"},{"en":"In some workplaces, managers enjoy a higher status than junior staff.","zh":"在一些工作場所，經理享有比初級員工更高的地位。"},{"en":"If boys eat first at home, they may enjoy a higher status than girls in that family.","zh":"如果男孩在家中先吃飯，他們在該家庭中可能享有比女孩更高的地位。"},{"en":"The phrase compares social position or respect.","zh":"這個短語比較社會位置或尊重程度。"}],"source":"145 - Food for thought.pdf","sourcePage":17},{"front":"in the family","meaning":"在家庭中","examples":[{"en":"The statement compares the status of boys and girls in the family.","zh":"該陳述比較男孩和女孩在家庭中的地位。"},{"en":"In the family means within the household or among family members.","zh":"in the family 指在家庭或家庭成員之間。"},{"en":"In the family, grandparents may make important decisions.","zh":"在家庭中，祖父母可能作出重要決定。"},{"en":"If food is shared unequally in the family, some children may suffer more.","zh":"如果食物在家庭中分配不均，一些孩子可能受苦更多。"},{"en":"The phrase limits the situation to family relationships and home life.","zh":"這個短語把情況限制在家庭關係和家居生活中。"}],"source":"145 - Food for thought.pdf","sourcePage":17},{"front":"experience the same improvement","meaning":"經歷相同改善","examples":[{"en":"Boys and girls did not experience the same improvement in pass rates.","zh":"男孩和女孩在合格率上沒有經歷相同改善。"},{"en":"To experience the same improvement means to show equal progress or benefit.","zh":"experience the same improvement 指顯示相等進步或好處。"},{"en":"Two classes may not experience the same improvement if one has more support.","zh":"如果其中一班有更多支援，兩班可能不會經歷相同改善。"},{"en":"If girls’ pass rates rise more than boys’, they do not experience the same improvement.","zh":"如果女孩合格率升幅比男孩大，他們就沒有經歷相同改善。"},{"en":"The phrase compares changes between groups.","zh":"這個短語比較群體之間的變化。"}],"source":"145 - Food for thought.pdf","sourcePage":17},{"front":"cooperate with","meaning":"與……合作","examples":[{"en":"The statement asks whether WHO cooperated with WFP.","zh":"該陳述問世界衞生組織是否與世界糧食計劃署合作。"},{"en":"To cooperate with someone means to work together with them toward a shared goal.","zh":"cooperate with 某人，意思是與其共同努力達成共同目標。"},{"en":"Schools cooperate with parents to support children’s learning.","zh":"學校與家長合作，以支援兒童學習。"},{"en":"If health organisations cooperate with food agencies, aid may reach families more effectively.","zh":"如果健康組織與糧食機構合作，援助可能更有效到達家庭。"},{"en":"The phrase shows teamwork between people or organisations.","zh":"這個短語顯示人或組織之間的團隊合作。"}],"source":"145 - Food for thought.pdf","sourcePage":18},{"front":"provide grain to","meaning":"向……提供穀物","examples":[{"en":"Donors provide grain to the school at Msekeni.","zh":"捐助者向Msekeni學校提供穀物。"},{"en":"To provide grain to someone means to supply crops such as maize, rice, wheat, or beans to them.","zh":"provide grain to 某人或某地，意思是向其供應粟米、米、小麥或豆類等農作物。"},{"en":"A relief agency may provide grain to families after a drought.","zh":"乾旱後，救援機構可能向家庭提供穀物。"},{"en":"If donors provide grain to a school, volunteers can cook meals for pupils.","zh":"如果捐助者向學校提供穀物，義工就可以為學生煮食。"},{"en":"The phrase describes giving basic food supplies to a person, group, or place.","zh":"這個短語描述向個人、群體或地方提供基本食物供應。"}],"source":"145 - Food for thought.pdf","sourcePage":18}],"ielts/reading/passage-2/Practice 146":[{"front":"When the Tulip Bubble Burst","meaning":"當鬱金香泡沫爆破時","examples":[{"en":"The passage describes what happened when the tulip bubble burst.","zh":"篇章描述了當鬱金香泡沫爆破時發生的事情。"},{"en":"When a bubble bursts, prices suddenly fall after rising far beyond real value.","zh":"當泡沫爆破時，價格在遠高於真實價值後突然下跌。"},{"en":"A housing bubble bursts when buyers stop paying extremely high prices for flats.","zh":"當買家停止以極高價格購買單位時，樓市泡沫就會爆破。"},{"en":"When the tulip bubble burst, many traders could no longer sell bulbs for huge sums.","zh":"當鬱金香泡沫爆破時，許多交易者再也不能以巨額出售球莖。"},{"en":"This phrase describes the painful moment when excitement turns into financial loss.","zh":"這個短語描述興奮變成財務損失的痛苦時刻。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":1},{"front":"spring-blooming perennials","meaning":"春季開花的多年生植物","examples":[{"en":"Tulips are spring-blooming perennials that grow from bulbs.","zh":"鬱金香是從球莖生長的春季開花多年生植物。"},{"en":"Spring-blooming perennials are plants that flower in spring and can live for more than two years.","zh":"春季開花的多年生植物，是指在春天開花並能生存超過兩年的植物。"},{"en":"A garden may include spring-blooming perennials so it has colour after winter.","zh":"花園可能種有春季開花的多年生植物，使冬天後有色彩。"},{"en":"Because they return each year, spring-blooming perennials can be easier to maintain than annual flowers.","zh":"因為它們每年再生，春季開花的多年生植物可能比一年生花卉更容易打理。"},{"en":"Tulips are called spring-blooming perennials because they bloom in spring and grow again from bulbs.","zh":"鬱金香被稱為春季開花的多年生植物，因為它們在春天開花，並從球莖重新生長。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":1},{"front":"grow from bulbs","meaning":"從球莖生長","examples":[{"en":"Tulips grow from bulbs.","zh":"鬱金香從球莖生長。"},{"en":"To grow from bulbs means to develop from underground plant structures that store food.","zh":"從球莖生長，是指從儲存養分的地下植物結構發育出來。"},{"en":"Gardeners plant bulbs in the soil before the flowering season begins.","zh":"園丁會在花季開始前把球莖種入泥土。"},{"en":"Plants that grow from bulbs can survive underground before sending up leaves and flowers.","zh":"從球莖生長的植物可以先在地下存活，再長出葉和花。"},{"en":"Tulips do not start as ordinary seeds in this description; they grow from bulbs.","zh":"在這個描述中，鬱金香不是從普通種子開始，而是從球莖生長。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":1},{"front":"depending on the species","meaning":"視乎物種而定","examples":[{"en":"Depending on the species, tulip plants can vary greatly in height.","zh":"視乎物種而定，鬱金香植株的高度可以差異很大。"},{"en":"Depending on the species means the result changes according to the type of plant or animal.","zh":"視乎物種而定，是指結果會根據植物或動物的類型而改變。"},{"en":"Depending on the species, a dog can be tiny enough for a handbag or large enough to pull a sled.","zh":"視乎物種而定，狗可以小得能放入手袋，也可以大得能拉雪橇。"},{"en":"Plant height, flower colour and growth speed can differ depending on the species.","zh":"植物高度、花色和生長速度都可能視乎物種而定而不同。"},{"en":"This phrase helps explain why not all tulips look exactly the same.","zh":"這個短語幫助解釋為何不是所有鬱金香都長得完全一樣。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":1},{"front":"as short as","meaning":"矮至","examples":[{"en":"Some tulip plants can grow as short as 4 inches.","zh":"有些鬱金香植株可以矮至 4 英寸。"},{"en":"As short as means reaching a surprisingly small height, length or time.","zh":"矮至是指高度、長度或時間短到令人注意。"},{"en":"A bus ride can be as short as five minutes if there is no traffic.","zh":"如果沒有交通擠塞，巴士車程可以短至五分鐘。"},{"en":"A plant that grows as short as 4 inches may fit easily in a small pot.","zh":"矮至 4 英寸的植物可能很容易放在小盆中。"},{"en":"This phrase highlights the lowest point in a range.","zh":"這個短語強調一個範圍中的最低點。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":1},{"front":"as high as","meaning":"高達","examples":[{"en":"Some tulip plants can grow as high as 28 inches.","zh":"有些鬱金香植株可以高達 28 英寸。"},{"en":"As high as means reaching an impressive or upper-level height, amount or figure.","zh":"高達是指高度、金額或數字達到令人注意的較高水平。"},{"en":"Ticket prices can rise as high as 1,000 dollars during a popular concert.","zh":"在熱門演唱會期間，票價可以高達 1,000 元。"},{"en":"A tulip that grows as high as 28 inches may stand above many smaller flowers.","zh":"高達 28 英寸的鬱金香可能比許多較小的花更高。"},{"en":"This phrase points to the highest possible level in a range.","zh":"這個短語指出一個範圍中的最高可能水平。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":1},{"front":"bloom on","meaning":"在……上開花","examples":[{"en":"The tulip’s large flowers usually bloom on scapes.","zh":"鬱金香的大花通常在花葶上開花。"},{"en":"To bloom on something means to produce flowers on that part of the plant.","zh":"在某物上開花，是指在植物的那個部分長出花朵。"},{"en":"Roses bloom on woody stems, while tulips bloom on softer stalks.","zh":"玫瑰在木質莖上開花，而鬱金香在較柔軟的花莖上開花。"},{"en":"Where a flower blooms on a plant affects how it looks in a garden.","zh":"花在植物哪個部分開花，會影響它在花園中的外觀。"},{"en":"In tulips, the large flower usually blooms on a scape rather than directly from the ground.","zh":"對鬱金香而言，大花通常在花葶上開花，而不是直接從地面開出。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":1},{"front":"scapes","meaning":"花葶","examples":[{"en":"Tulip flowers usually bloom on scapes.","zh":"鬱金香花通常在花葶上開花。"},{"en":"Scapes are leafless flower stalks that rise from the base of some plants.","zh":"花葶是一些植物從基部長出的無葉花莖。"},{"en":"A gardener may notice scapes first before the flower fully opens.","zh":"園丁可能在花完全開放前先注意到花葶。"},{"en":"Scapes support the flower and lift it above the leaves or ground.","zh":"花葶支撐花朵，並把它抬高到葉或地面之上。"},{"en":"In tulips, scapes help hold the showy flower upright.","zh":"在鬱金香中，花葶幫助支撐鮮艷的花朵直立。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":1},{"front":"sub-scapose stems","meaning":"近花葶狀莖","examples":[{"en":"Some tulip flowers bloom on sub-scapose stems.","zh":"有些鬱金香花在近花葶狀莖上開花。"},{"en":"Sub-scapose stems are stems that are almost like scapes but not completely scape-like.","zh":"近花葶狀莖是幾乎像花葶但不完全是花葶的莖。"},{"en":"A botany guide may use sub-scapose stems to describe plants with very short or reduced leafy stems.","zh":"植物學指南可能用近花葶狀莖來描述葉莖很短或退化的植物。"},{"en":"This term helps specialists describe small differences in plant structure.","zh":"這個術語幫助專家描述植物結構上的細微差異。"},{"en":"For learners, sub-scapose stems simply means stems that are close to flower stalks in form.","zh":"對學習者來說，近花葶狀莖簡單來說就是形態接近花莖的莖。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":1},{"front":"lack bracts","meaning":"沒有苞片","examples":[{"en":"The stems lack bracts.","zh":"這些莖沒有苞片。"},{"en":"To lack bracts means not to have small leaf-like structures near the flower.","zh":"沒有苞片，是指花朵附近沒有細小葉狀結構。"},{"en":"Some flowers have bracts that look like colourful leaves, but these stems lack bracts.","zh":"有些花有像彩色葉子的苞片，但這些莖沒有苞片。"},{"en":"A plant that lacks bracts may have a cleaner, simpler-looking flower stalk.","zh":"沒有苞片的植物，花莖外觀可能更簡潔。"},{"en":"This phrase describes what is missing from the stem structure.","zh":"這個短語描述莖部結構缺少甚麼。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":1},{"front":"produce one flower per stem","meaning":"每條莖只開一朵花","examples":[{"en":"Most tulips produce only one flower per stem.","zh":"大多數鬱金香每條莖只開一朵花。"},{"en":"To produce one flower per stem means each individual stem carries a single flower.","zh":"每條莖只開一朵花，是指每一條獨立的莖只承載一朵花。"},{"en":"A plant that produces one flower per stem may look neat and evenly spaced in a garden.","zh":"每條莖只開一朵花的植物，在花園中可能看起來整齊而分布均勻。"},{"en":"If each stem produces one flower, counting stems can help estimate the number of flowers.","zh":"如果每條莖只開一朵花，數莖可以幫助估計花朵數量。"},{"en":"This phrase contrasts with plants that carry several flowers on one stem.","zh":"這個短語與一條莖上有多朵花的植物形成對比。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":1},{"front":"bear multiple flowers","meaning":"長出多朵花","examples":[{"en":"A few species bear multiple flowers on their scapes.","zh":"少數物種在花葶上長出多朵花。"},{"en":"To bear multiple flowers means to carry or produce more than one flower.","zh":"長出多朵花，是指承載或產生多於一朵花。"},{"en":"Some garden plants bear multiple flowers on one branch, creating a fuller appearance.","zh":"有些園藝植物在一條枝上長出多朵花，形成更豐滿的外觀。"},{"en":"If a stem bears multiple flowers, it may look heavier and more crowded.","zh":"如果一條莖長出多朵花，它可能看起來更重和更密集。"},{"en":"This phrase is useful when comparing ordinary tulips with species that flower more abundantly.","zh":"這個短語適合用來比較普通鬱金香和開花更多的品種。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":2},{"front":"showy flowers","meaning":"鮮艷奪目的花","examples":[{"en":"The tulip has showy flowers.","zh":"鬱金香有鮮艷奪目的花。"},{"en":"Showy flowers are large, bright or attractive flowers that easily catch attention.","zh":"鮮艷奪目的花，是指大朵、明亮或吸引人、容易引起注意的花。"},{"en":"A hotel may plant showy flowers near the entrance to impress visitors.","zh":"酒店可能在入口附近種植鮮艷奪目的花來令訪客留下印象。"},{"en":"Showy flowers can make a garden look colourful even from far away.","zh":"鮮艷奪目的花可以令花園即使從遠處看也色彩豐富。"},{"en":"Tulips are valued partly because their showy flowers look striking and decorative.","zh":"鬱金香受重視，部分原因是它們鮮艷奪目的花看起來突出又具裝飾性。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":2},{"front":"cup-shaped","meaning":"杯狀的","examples":[{"en":"The tulip flower is generally cup-shaped.","zh":"鬱金香花通常是杯狀的。"},{"en":"Cup-shaped means having a form like a small cup, with sides rising around the centre.","zh":"杯狀的，是指形狀像小杯，兩側圍着中心向上升起。"},{"en":"A cup-shaped flower can hold its petals close together before opening fully.","zh":"杯狀的花在完全開放前，花瓣可以較緊密地包住中心。"},{"en":"Cup-shaped designs are common in bowls, lamps and flower illustrations.","zh":"杯狀設計常見於碗、燈和花卉插圖中。"},{"en":"Tulips are often described as cup-shaped because their petals curve upward around the middle.","zh":"鬱金香常被形容為杯狀，因為花瓣圍着中間向上彎曲。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":2},{"front":"star-shaped","meaning":"星形的","examples":[{"en":"Some tulip flowers are star-shaped.","zh":"有些鬱金香花是星形的。"},{"en":"Star-shaped means having points or spreading parts like a star.","zh":"星形的，是指有像星星一樣的尖角或向外伸展的部分。"},{"en":"A star-shaped decoration has arms that spread out from the centre.","zh":"星形裝飾有從中心向外伸展的角。"},{"en":"When a flower opens widely, it may look star-shaped from above.","zh":"當花朵大幅張開時，從上方看可能像星形。"},{"en":"Some tulips are star-shaped rather than cup-shaped because their petals spread outward.","zh":"有些鬱金香是星形而不是杯狀，因為花瓣向外展開。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":2},{"front":"petals and sepals","meaning":"花瓣和萼片","examples":[{"en":"The tulip flower has three petals and three sepals.","zh":"鬱金香花有三片花瓣和三片萼片。"},{"en":"Petals and sepals are flower parts; petals are usually colourful, while sepals often protect the bud.","zh":"花瓣和萼片是花的部分；花瓣通常有顏色，而萼片常保護花蕾。"},{"en":"In many flowers, students can see petals easily but may overlook the sepals.","zh":"在許多花中，學生容易看見花瓣，但可能忽略萼片。"},{"en":"Petals attract attention, while sepals often support or protect the flower before it opens.","zh":"花瓣吸引注意，而萼片通常在花開放前支撐或保護花朵。"},{"en":"In tulips, petals and sepals look so similar that they are often grouped together.","zh":"在鬱金香中，花瓣和萼片看起來非常相似，所以常被歸為一類。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":2},{"front":"be termed","meaning":"被稱為","examples":[{"en":"The petals and sepals are often termed tepals.","zh":"花瓣和萼片常被稱為花被片。"},{"en":"To be termed something means to be called or described by that name.","zh":"被稱為某物，是指被用那個名稱稱呼或描述。"},{"en":"A sudden rise in prices may be termed inflation in an economics lesson.","zh":"在經濟課中，價格突然上升可能被稱為通脹。"},{"en":"Scientists use special terms so that parts can be described more precisely.","zh":"科學家使用專門術語，使各部分能被更準確地描述。"},{"en":"In tulips, the similar petals and sepals are termed tepals for clarity.","zh":"在鬱金香中，相似的花瓣和萼片被稱為花被片，以便清楚表達。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":2},{"front":"tepals","meaning":"花被片","examples":[{"en":"The petals and sepals are often termed tepals.","zh":"花瓣和萼片常被稱為花被片。"},{"en":"Tepals are flower parts used when petals and sepals look very similar.","zh":"花被片是當花瓣和萼片看起來非常相似時使用的花部名稱。"},{"en":"In some flowers, learners cannot easily tell petals from sepals, so botanists call them tepals.","zh":"在有些花中，學習者不容易分辨花瓣和萼片，所以植物學家稱它們為花被片。"},{"en":"The word tepals helps avoid confusion when the two parts are nearly identical.","zh":"花被片這個詞有助避免兩個部分幾乎相同時造成混淆。"},{"en":"Tulip tepals form the colourful outer parts of the flower.","zh":"鬱金香的花被片形成花朵外層有色彩的部分。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":2},{"front":"nearly identical","meaning":"幾乎相同","examples":[{"en":"The petals and sepals are nearly identical.","zh":"花瓣和萼片幾乎相同。"},{"en":"Nearly identical means almost the same, with only small differences.","zh":"幾乎相同，是指差不多一樣，只有細小差異。"},{"en":"Two school uniforms may look nearly identical except for the badge.","zh":"兩套校服除了徽章外可能幾乎相同。"},{"en":"If two plant parts are nearly identical, beginners may find them hard to name.","zh":"如果兩個植物部分幾乎相同，初學者可能很難命名。"},{"en":"Tulip petals and sepals are nearly identical, so they are often called tepals.","zh":"鬱金香的花瓣和萼片幾乎相同，所以常被稱為花被片。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":2},{"front":"be marked on","meaning":"在……上有斑紋","examples":[{"en":"The tepals are often marked on the interior surface.","zh":"花被片常在內側表面上有斑紋。"},{"en":"To be marked on a surface means to have spots, lines or colours on that surface.","zh":"在某表面上有斑紋，是指該表面有斑點、線條或顏色。"},{"en":"A map may be marked on the back with useful notes.","zh":"地圖背面可能標有有用筆記。"},{"en":"If a flower is marked on the inside, its pattern may be visible only when it opens.","zh":"如果花在內側有斑紋，圖案可能只有在花開時才看見。"},{"en":"Tulip tepals may be marked on the interior surface near their bases.","zh":"鬱金香花被片可能在接近基部的內側表面有斑紋。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":2},{"front":"interior surface","meaning":"內側表面","examples":[{"en":"The tepals have markings on the interior surface.","zh":"花被片在內側表面有斑紋。"},{"en":"The interior surface is the inside surface of something.","zh":"內側表面是某物內部的一面。"},{"en":"The interior surface of a cup should be cleaned carefully because it touches drinks.","zh":"杯子的內側表面應仔細清洗，因為它接觸飲品。"},{"en":"A flower’s interior surface may have colours that attract insects.","zh":"花的內側表面可能有吸引昆蟲的顏色。"},{"en":"In tulips, markings on the interior surface can make the flower look more detailed.","zh":"在鬱金香中，內側表面的斑紋可以令花朵看起來更細緻。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":2},{"front":"near the bases","meaning":"接近基部","examples":[{"en":"The markings appear near the bases of the tepals.","zh":"斑紋出現在花被片接近基部的位置。"},{"en":"Near the bases means close to the bottom parts where something begins or joins another part.","zh":"接近基部，是指靠近某物開始或連接另一部分的底部位置。"},{"en":"Leaves may turn yellow near the bases before the tips change colour.","zh":"葉子可能先在接近基部的位置變黃，之後葉尖才變色。"},{"en":"Marks near the bases of petals are often hidden until the flower opens.","zh":"花瓣接近基部的斑紋通常在花開前被隱藏。"},{"en":"This phrase tells readers exactly where the darker markings are found.","zh":"這個短語清楚告訴讀者較深色斑紋在哪裡出現。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":2},{"front":"darker colorings","meaning":"較深色的紋理","examples":[{"en":"The tepals may have darker colorings near their bases.","zh":"花被片在接近基部的位置可能有較深色的紋理。"},{"en":"Darker colorings are deeper or stronger colours compared with the surrounding area.","zh":"較深色的紋理，是指比周圍部分更深或更強的顏色。"},{"en":"A bird may have darker colorings on its wings than on its body.","zh":"鳥的翅膀可能比身體有較深色的紋理。"},{"en":"Darker colorings can make a flower’s pattern more noticeable.","zh":"較深色的紋理可以令花朵圖案更明顯。"},{"en":"In tulips, darker colorings near the bases add contrast to the flower.","zh":"在鬱金香中，接近基部的較深色紋理為花朵增加對比。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":3},{"front":"come in a wide variety of","meaning":"有各式各樣的……","examples":[{"en":"Tulip flowers come in a wide variety of colours.","zh":"鬱金香花有各式各樣的顏色。"},{"en":"To come in a wide variety of something means to be available in many different types, colours or forms.","zh":"有各式各樣的某物，是指有許多不同類型、顏色或形式可供選擇。"},{"en":"School bags come in a wide variety of sizes and designs.","zh":"書包有各式各樣的大小和設計。"},{"en":"Products that come in a wide variety of colours can attract different customers.","zh":"有各式各樣顏色的產品可以吸引不同顧客。"},{"en":"Tulips are popular partly because they come in a wide variety of colours.","zh":"鬱金香受歡迎，部分原因是它們有各式各樣的顏色。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":3},{"front":"pure blue","meaning":"純藍色","examples":[{"en":"Tulip flowers come in many colours except pure blue.","zh":"鬱金香花有許多顏色，除了純藍色。"},{"en":"Pure blue means a clear blue colour without purple, green or grey mixed in.","zh":"純藍色是指清晰的藍色，沒有混入紫色、綠色或灰色。"},{"en":"A shirt may look pure blue online but slightly purple in real life.","zh":"一件恤衫在網上可能看似純藍色，但實物略帶紫色。"},{"en":"If a flower is described as pure blue, buyers expect a clean blue shade.","zh":"如果一朵花被描述為純藍色，買家會期待乾淨的藍色色調。"},{"en":"The passage says tulips have many colours, but not true pure blue.","zh":"篇章說鬱金香有許多顏色，但沒有真正的純藍色。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":3},{"front":"faint violet hue","meaning":"淡淡的紫羅蘭色調","examples":[{"en":"Some so-called blue tulips have a faint violet hue.","zh":"有些所謂藍色鬱金香帶有淡淡的紫羅蘭色調。"},{"en":"A faint violet hue is a very light purple shade.","zh":"淡淡的紫羅蘭色調，是指非常淺的紫色調。"},{"en":"A white wall may have a faint violet hue under coloured lighting.","zh":"白牆在彩色燈光下可能帶有淡淡的紫羅蘭色調。"},{"en":"If a flower has a faint violet hue, it may look almost blue but not truly blue.","zh":"如果一朵花帶有淡淡的紫羅蘭色調，它可能看起來近似藍色，但不是真正藍色。"},{"en":"This phrase explains why some “blue” tulips are actually slightly purple.","zh":"這個短語解釋為何有些「藍色」鬱金香其實略帶紫色。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":3},{"front":"long before","meaning":"早在……之前","examples":[{"en":"Long before anyone heard of modern high-tech stocks, there was Semper Augustus.","zh":"早在任何人聽說現代高科技股票之前，就有「永恆的奧古斯都」鬱金香。"},{"en":"Long before means much earlier than a later event or period.","zh":"早在……之前，是指比之後的事件或時期早很多。"},{"en":"Long before smartphones existed, people used paper maps to find streets.","zh":"早在智能手機出現之前，人們使用紙本地圖尋找街道。"},{"en":"This phrase helps compare an old event with a modern one.","zh":"這個短語幫助把舊事件與現代事件作比較。"},{"en":"The passage uses long before to link tulip speculation with later financial bubbles.","zh":"篇章使用早在……之前，把鬱金香投機與後來的金融泡沫連繫起來。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":3},{"front":"high-tech stocks","meaning":"高科技股票","examples":[{"en":"High-tech stocks soared during the bull market.","zh":"高科技股票在牛市期間飆升。"},{"en":"High-tech stocks are shares in companies that focus on advanced technology.","zh":"高科技股票是專注於先進科技公司的股票。"},{"en":"Investors may buy high-tech stocks when they expect new software or devices to grow quickly.","zh":"當投資者預期新軟件或設備快速增長時，可能會購買高科技股票。"},{"en":"High-tech stocks can rise fast, but they can also fall sharply if expectations are too high.","zh":"高科技股票可以迅速上升，但如果期望過高，也可能急劇下跌。"},{"en":"The passage compares excitement over tulips with excitement over high-tech stocks.","zh":"篇章把人們對鬱金香的興奮與對高科技股票的興奮作比較。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":3},{"front":"soar during","meaning":"在……期間飆升","examples":[{"en":"Some high-tech stocks soared during the bull market.","zh":"一些高科技股票在牛市期間飆升。"},{"en":"To soar during a period means to rise very quickly within that time.","zh":"在某段期間飆升，是指在那段時間內迅速上升。"},{"en":"Food prices may soar during a supply shortage.","zh":"食物價格可能在供應短缺期間飆升。"},{"en":"If demand is strong, ticket prices can soar during the holiday season.","zh":"如果需求強勁，票價可以在假期期間飆升。"},{"en":"The phrase suggests a sharp upward movement, not a slow increase.","zh":"這個短語暗示急劇上升，而不是緩慢增加。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":3},{"front":"current bull market","meaning":"當前牛市","examples":[{"en":"The passage compares tulip speculation with the current bull market.","zh":"篇章把鬱金香投機與當前牛市作比較。"},{"en":"A current bull market is a present period when share prices are generally rising.","zh":"當前牛市是指現時股票價格普遍上升的時期。"},{"en":"Investors often feel confident during a current bull market because prices keep going up.","zh":"在當前牛市中，投資者常因價格持續上升而感到有信心。"},{"en":"A current bull market can encourage risky buying if people forget that prices can fall.","zh":"如果人們忘記價格可以下跌，當前牛市可能鼓勵冒險買入。"},{"en":"The phrase links the old tulip craze to modern market excitement.","zh":"這個短語把舊時鬱金香狂熱與現代市場興奮連繫起來。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":3},{"front":"Semper Augustus","meaning":"「永恆的奧古斯都」鬱金香","examples":[{"en":"Semper Augustus was a tulip of extraordinary beauty.","zh":"「永恆的奧古斯都」是一種具有非凡美態的鬱金香。"},{"en":"Semper Augustus was the name of a rare and famous tulip in the passage.","zh":"「永恆的奧古斯都」是篇章中一種稀有而著名鬱金香的名稱。"},{"en":"Collectors valued Semper Augustus because its colours and pattern were unusual.","zh":"收藏家重視「永恆的奧古斯都」，因為它的顏色和圖案很不尋常。"},{"en":"A rare object like Semper Augustus can become expensive when many people desire it.","zh":"像「永恆的奧古斯都」這樣的稀有物品，在許多人渴望時會變得昂貴。"},{"en":"The flower represents how beauty, rarity and speculation can combine.","zh":"這種花代表美感、稀有性和投機如何結合。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":3},{"front":"more prosaic and more sublime than","meaning":"比……更平凡也更崇高","examples":[{"en":"The tulip was both more prosaic and more sublime than any stock or bond.","zh":"這種鬱金香比任何股票或債券都更平凡，也更崇高。"},{"en":"More prosaic and more sublime than means both more ordinary and more beautiful or elevated than something else.","zh":"比某物更平凡也更崇高，是指既更普通，又更美麗或更高尚。"},{"en":"A handwritten letter may be more prosaic and more sublime than an expensive gift because it is simple but deeply meaningful.","zh":"手寫信可能比昂貴禮物更平凡也更崇高，因為它簡單但意義深。"},{"en":"The tulip was prosaic because it was a plant, but sublime because people saw rare beauty in it.","zh":"鬱金香是平凡的，因為它是一種植物；但它也是崇高的，因為人們在其中看到稀有美感。"},{"en":"This contrast helps show why a flower could become a financial obsession.","zh":"這種對比幫助展示為何一朵花可以變成金融狂熱。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":3},{"front":"stock or bond","meaning":"股票或債券","examples":[{"en":"The tulip was compared with a stock or bond.","zh":"鬱金香被拿來與股票或債券比較。"},{"en":"A stock or bond is a financial asset that people may buy as an investment.","zh":"股票或債券是人們可作投資購買的金融資產。"},{"en":"A worker may invest savings in a stock or bond instead of leaving all money in cash.","zh":"工人可能把儲蓄投資於股票或債券，而不是把所有錢都放作現金。"},{"en":"Stocks and bonds can rise or fall in value depending on markets and risk.","zh":"股票和債券的價值會因市場和風險而上升或下跌。"},{"en":"Comparing a tulip with a stock or bond shows how bulbs became investment objects.","zh":"把鬱金香與股票或債券比較，顯示球莖如何變成投資物件。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":3},{"front":"extraordinary beauty","meaning":"非凡美態","examples":[{"en":"Semper Augustus was a tulip of extraordinary beauty.","zh":"「永恆的奧古斯都」是一種具有非凡美態的鬱金香。"},{"en":"Extraordinary beauty means beauty that is unusually impressive or rare.","zh":"非凡美態是指異常令人印象深刻或稀有的美。"},{"en":"A mountain view after snowfall may have extraordinary beauty.","zh":"下雪後的山景可能具有非凡美態。"},{"en":"Objects of extraordinary beauty can attract collectors and push prices higher.","zh":"具有非凡美態的物品可以吸引收藏家並推高價格。"},{"en":"In the passage, extraordinary beauty helped make Semper Augustus highly desired.","zh":"在篇章中，非凡美態令「永恆的奧古斯都」極受渴求。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":4},{"front":"midnight-blue petals","meaning":"午夜藍花瓣","examples":[{"en":"Semper Augustus had midnight-blue petals.","zh":"「永恆的奧古斯都」有午夜藍花瓣。"},{"en":"Midnight-blue petals are petals with a very dark blue colour, like the night sky.","zh":"午夜藍花瓣，是指像夜空一樣非常深藍色的花瓣。"},{"en":"A dress described as midnight blue is almost black but still has a deep blue tone.","zh":"被描述為午夜藍的裙子幾乎是黑色，但仍有深藍色調。"},{"en":"Dark petals can make white or red markings stand out more clearly.","zh":"深色花瓣可以令白色或紅色紋理更加突出。"},{"en":"The phrase helps readers imagine the dramatic colour of the rare tulip.","zh":"這個短語幫助讀者想像稀有鬱金香的戲劇性顏色。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":4},{"front":"topped by","meaning":"頂端有……","examples":[{"en":"The petals were topped by a band of pure white.","zh":"花瓣頂端有一道純白色帶。"},{"en":"Topped by means having something placed or appearing on the top part.","zh":"頂端有某物，是指某物放在或出現在上方部分。"},{"en":"A cake may be topped by fresh fruit and cream.","zh":"蛋糕頂端可能有新鮮水果和忌廉。"},{"en":"A dark building topped by a bright sign is easy to notice at night.","zh":"一幢深色建築頂端有明亮招牌，夜晚很容易看見。"},{"en":"In the tulip description, the dark petals were topped by a white band.","zh":"在鬱金香描述中，深色花瓣頂端有一道白色帶。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":4},{"front":"a band of pure white","meaning":"一道純白色帶","examples":[{"en":"The flower had a band of pure white on its petals.","zh":"這朵花的花瓣上有一道純白色帶。"},{"en":"A band of pure white is a strip or line of clean white colour.","zh":"一道純白色帶，是指一條乾淨白色的帶狀或線狀部分。"},{"en":"A school uniform may have a band of pure white around the collar.","zh":"校服領口周圍可能有一道純白色帶。"},{"en":"A band of pure white can create strong contrast on a dark surface.","zh":"一道純白色帶可以在深色表面上形成強烈對比。"},{"en":"On Semper Augustus, the band of pure white made the petals look more striking.","zh":"在「永恆的奧古斯都」上，那道純白色帶令花瓣更醒目。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":4},{"front":"accented with","meaning":"以……作點綴","examples":[{"en":"The petals were accented with crimson flares.","zh":"花瓣以深紅色火焰狀紋作點綴。"},{"en":"Accented with means decorated or highlighted by another colour or detail.","zh":"以某物作點綴，是指用另一種顏色或細節作裝飾或突出。"},{"en":"A black jacket accented with silver buttons can look more formal.","zh":"一件黑色外套以銀色鈕扣作點綴，可以看起來更正式。"},{"en":"Small red details can accent a white room and make it feel warmer.","zh":"細小紅色細節可以點綴白色房間，令它感覺更溫暖。"},{"en":"The tulip petals were accented with crimson flares that made the pattern vivid.","zh":"這種鬱金香花瓣以深紅色火焰狀紋作點綴，使圖案更鮮明。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":4},{"front":"crimson flares","meaning":"深紅色火焰狀紋","examples":[{"en":"The tulip was accented with crimson flares.","zh":"這種鬱金香以深紅色火焰狀紋作點綴。"},{"en":"Crimson flares are deep red flame-like streaks or markings.","zh":"深紅色火焰狀紋，是指深紅色、像火焰一樣的條紋或斑紋。"},{"en":"A painting may use crimson flares to create energy against a dark background.","zh":"一幅畫可能使用深紅色火焰狀紋，在深色背景上營造活力。"},{"en":"Crimson flares on petals can make a flower look dramatic and rare.","zh":"花瓣上的深紅色火焰狀紋可以令花朵看起來戲劇性而稀有。"},{"en":"The crimson flares helped make Semper Augustus especially desirable.","zh":"深紅色火焰狀紋令「永恆的奧古斯都」尤其令人渴望。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":4},{"front":"denizens of","meaning":"……的居民","examples":[{"en":"To denizens of 17th-century Holland, the tulip was highly desirable.","zh":"對 17 世紀荷蘭的居民而言，鬱金香非常令人渴望。"},{"en":"Denizens of a place are the people, animals or beings who live there.","zh":"某地的居民，是指生活在那裡的人、動物或生物。"},{"en":"The denizens of a busy city learn to live with noise and crowds.","zh":"繁忙城市的居民學會與噪音和人群共處。"},{"en":"A rare object may become famous among the denizens of a wealthy trading town.","zh":"稀有物品可能在富有貿易城市的居民之間變得有名。"},{"en":"This phrase gives a formal way to say “people living in a place.”","zh":"這個短語是表達「住在某地的人」的正式說法。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":4},{"front":"17th-century Holland","meaning":"17世紀荷蘭","examples":[{"en":"Tulips were extremely desirable in 17th-century Holland.","zh":"鬱金香在 17 世紀荷蘭極受渴求。"},{"en":"17th-century Holland means Holland during the 1600s.","zh":"17 世紀荷蘭是指 1600 年代的荷蘭。"},{"en":"A history lesson on 17th-century Holland may discuss trade, wealth and tulip mania.","zh":"關於 17 世紀荷蘭的歷史課可能討論貿易、財富和鬱金香狂熱。"},{"en":"The economic conditions of 17th-century Holland helped create demand for rare flowers.","zh":"17 世紀荷蘭的經濟條件幫助製造對稀有花卉的需求。"},{"en":"This phrase gives the time and place of the tulip bubble.","zh":"這個短語給出鬱金香泡沫的時間和地點。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":4},{"front":"little was as desirable","meaning":"很少東西像……一樣令人渴望","examples":[{"en":"To Dutch collectors, little was as desirable as Semper Augustus.","zh":"對荷蘭收藏家而言，很少東西像「永恆的奧古斯都」一樣令人渴望。"},{"en":"Little was as desirable as something means very few things were wanted as much as it.","zh":"很少東西像某物一樣令人渴望，是指很少東西被人如此想要。"},{"en":"To young fans, little was as desirable as a ticket to the final concert.","zh":"對年輕粉絲而言，很少東西像最後一場演唱會門票一樣令人渴望。"},{"en":"When little is as desirable as an object, people may pay far more than usual.","zh":"當很少東西像某物一樣令人渴望時，人們可能支付遠高於平常的價格。"},{"en":"This phrase emphasises the extreme appeal of Semper Augustus.","zh":"這個短語強調「永恆的奧古斯都」的極大吸引力。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":4},{"front":"the only dozen specimens","meaning":"僅有的十二個樣本","examples":[{"en":"The Amsterdam man owned the only dozen specimens.","zh":"那名阿姆斯特丹男子擁有僅有的十二個樣本。"},{"en":"The only dozen specimens means the only twelve known examples of something.","zh":"僅有的十二個樣本，是指某物已知只有十二個例子。"},{"en":"A museum may protect the only dozen specimens of a rare insect.","zh":"博物館可能保護某種稀有昆蟲僅有的十二個樣本。"},{"en":"If there are only a dozen specimens, scarcity can make collectors compete fiercely.","zh":"如果只有十二個樣本，稀缺性可以令收藏家激烈競爭。"},{"en":"In the passage, owning the only dozen specimens made the tulips extremely valuable.","zh":"在篇章中，擁有僅有的十二個樣本令這些鬱金香極具價值。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":4},{"front":"be offered","meaning":"獲出價","examples":[{"en":"The owner was offered 3,000 guilders for one bulb.","zh":"物主獲出價 3,000 荷蘭盾購買一個球莖。"},{"en":"To be offered an amount means someone proposes to pay that amount.","zh":"獲出價某金額，是指有人提出支付那個金額。"},{"en":"A seller may be offered a high price for an old watch if collectors want it.","zh":"如果收藏家想要一隻舊手錶，賣家可能獲出高價。"},{"en":"Being offered a large sum does not mean the owner must accept it.","zh":"獲出一大筆錢不代表物主必須接受。"},{"en":"The tulip owner was offered a fortune but still refused to sell.","zh":"鬱金香物主獲出一大筆錢，但仍拒絕出售。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":4},{"front":"3,000 guilders","meaning":"3,000荷蘭盾","examples":[{"en":"Someone offered 3,000 guilders for one tulip bulb.","zh":"有人為一個鬱金香球莖出價 3,000 荷蘭盾。"},{"en":"3,000 guilders was a very large sum of Dutch money in the passage.","zh":"3,000 荷蘭盾在篇章中是一筆非常大的荷蘭貨幣金額。"},{"en":"A price of 3,000 guilders for one bulb shows how extreme the market had become.","zh":"一個球莖售價 3,000 荷蘭盾，顯示市場已變得多麼極端。"},{"en":"When an ordinary object reaches 3,000 guilders, buyers are paying for rarity and desire.","zh":"當一件普通物品達到 3,000 荷蘭盾時，買家支付的是稀有性和渴望。"},{"en":"The figure helps readers understand the scale of tulip speculation.","zh":"這個數字幫助讀者理解鬱金香投機的規模。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":5},{"front":"one bulb","meaning":"一個球莖","examples":[{"en":"The buyer offered a large sum for one bulb.","zh":"買家為一個球莖出了一大筆錢。"},{"en":"One bulb means a single underground plant structure that can grow into a tulip.","zh":"一個球莖，是指一個能長成鬱金香的地下植物結構。"},{"en":"A gardener may plant one bulb in each hole to give flowers enough space.","zh":"園丁可能每個洞種一個球莖，讓花有足夠空間。"},{"en":"Paying a huge price for one bulb shows how rare the tulip was considered.","zh":"為一個球莖支付巨額，顯示該鬱金香被視為多麼稀有。"},{"en":"In tulip mania, even one bulb could become an object of speculation.","zh":"在鬱金香狂熱中，即使一個球莖也可以成為投機物件。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":5},{"front":"accurate way to render","meaning":"準確換算的方法","examples":[{"en":"There is no accurate way to render that amount in today’s money.","zh":"沒有準確方法把該金額換算成今天的貨幣。"},{"en":"An accurate way to render an amount means a precise method for converting or expressing it in another form.","zh":"準確換算某金額的方法，是指把它精確轉換或表達成另一種形式的方法。"},{"en":"Historians may struggle to render old wages accurately in modern currency.","zh":"歷史學家可能難以把舊時工資準確換算成現代貨幣。"},{"en":"Without an accurate way to render old prices, comparisons can only be approximate.","zh":"沒有準確換算舊價格的方法，比較只能是近似。"},{"en":"This phrase shows that translating past money into present value is difficult.","zh":"這個短語顯示把過去貨幣轉成現今價值很困難。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":5},{"front":"today’s greenbacks","meaning":"現今美元","examples":[{"en":"The old price is difficult to convert into today’s greenbacks.","zh":"舊價格很難換算成現今美元。"},{"en":"Today’s greenbacks means modern US dollars in informal language.","zh":"現今美元是口語中指現代美國美元的說法。"},{"en":"A historian may say an old salary is hard to express in today’s greenbacks.","zh":"歷史學家可能說舊時薪金很難用現今美元表達。"},{"en":"Comparing ancient coins with today’s greenbacks can be misleading without context.","zh":"沒有背景下把古代硬幣與現今美元比較，可能會令人誤解。"},{"en":"The phrase gives a casual way to refer to present-day dollars.","zh":"這個短語以較口語方式指今天的美元。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":5},{"front":"roughly equal to","meaning":"大約相等於","examples":[{"en":"The sum was roughly equal to a wealthy merchant’s annual income.","zh":"該金額大約相等於一名富有商人的年收入。"},{"en":"Roughly equal to means almost the same as, but not exactly the same.","zh":"大約相等於，是指差不多相同，但不完全精確。"},{"en":"The rent is roughly equal to half of his monthly salary.","zh":"租金大約相等於他月薪的一半。"},{"en":"If a price is roughly equal to a year’s income, it is extremely expensive.","zh":"如果價格大約相等於一年收入，那就是極其昂貴。"},{"en":"This phrase gives an approximate comparison rather than an exact calculation.","zh":"這個短語提供近似比較，而不是精確計算。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":5},{"front":"annual income","meaning":"年收入","examples":[{"en":"The price was close to the annual income of a wealthy merchant.","zh":"這個價格接近一名富有商人的年收入。"},{"en":"Annual income is the amount of money someone earns in one year.","zh":"年收入是一個人在一年內賺取的金額。"},{"en":"A bank may ask about annual income before approving a loan.","zh":"銀行在批准貸款前可能詢問年收入。"},{"en":"If a purchase costs a full annual income, most people cannot afford it easily.","zh":"如果一項購買花費整整一年收入，多數人都難以負擔。"},{"en":"The tulip price seems shocking because it approached a wealthy merchant’s annual income.","zh":"鬱金香價格令人震驚，因為它接近一名富有商人的年收入。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":5},{"front":"wealthy merchant","meaning":"富有商人","examples":[{"en":"A wealthy merchant might earn that sum in a year.","zh":"一名富有商人可能一年賺到那筆錢。"},{"en":"A wealthy merchant is a rich trader or businessperson who buys and sells goods.","zh":"富有商人是有錢的貿易商或商人，買賣貨物。"},{"en":"A wealthy merchant may own ships, warehouses or large trading accounts.","zh":"富有商人可能擁有船隻、倉庫或大型貿易帳戶。"},{"en":"If even a wealthy merchant needs a year to earn a price, the object is extremely costly.","zh":"如果連富有商人也需要一年才賺到某價格，該物件就極其昂貴。"},{"en":"The passage uses wealthy merchant to show how expensive one tulip bulb was.","zh":"篇章使用富有商人來顯示一個鬱金香球莖有多昂貴。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":5},{"front":"a few years later","meaning":"幾年後","examples":[{"en":"A few years later, Rembrandt received about half that amount.","zh":"幾年後，林布蘭收到約該金額的一半。"},{"en":"A few years later means several years after the earlier event.","zh":"幾年後，是指在較早事件之後過了數年。"},{"en":"A student may start with basic English and, a few years later, write full essays confidently.","zh":"學生可能從基礎英語開始，幾年後自信地寫完整文章。"},{"en":"This phrase helps show the order of events over time.","zh":"這個短語幫助顯示事件的時間順序。"},{"en":"The comparison a few years later makes the tulip price seem even more surprising.","zh":"幾年後的比較令鬱金香價格顯得更驚人。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":5},{"front":"about half that amount","meaning":"約該金額的一半","examples":[{"en":"Rembrandt received about half that amount for painting The Night Watch.","zh":"林布蘭為繪畫《夜巡》收到約該金額的一半。"},{"en":"About half that amount means roughly fifty percent of the sum already mentioned.","zh":"約該金額的一半，是指大約等於已提及金額的百分之五十。"},{"en":"If a phone costs 800 dollars and the case costs about half that amount, the case costs around 400 dollars.","zh":"如果手機售價 800 元，而手機殼約該金額的一半，手機殼約為 400 元。"},{"en":"This phrase gives a comparison without repeating the exact number.","zh":"這個短語不用重複確切數字也能作比較。"},{"en":"Saying Rembrandt received about half that amount highlights how high the tulip price was.","zh":"說林布蘭收到約該金額的一半，突顯鬱金香價格有多高。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":5},{"front":"The Night Watch","meaning":"《夜巡》","examples":[{"en":"Rembrandt painted The Night Watch.","zh":"林布蘭繪畫了《夜巡》。"},{"en":"The Night Watch is the title of a famous painting mentioned for comparison in the passage.","zh":"《夜巡》是篇章中用作比較的一幅著名畫作標題。"},{"en":"A teacher may mention The Night Watch when discussing Dutch art.","zh":"老師討論荷蘭藝術時可能提到《夜巡》。"},{"en":"Comparing a tulip bulb with payment for The Night Watch shows the strange scale of the mania.","zh":"把鬱金香球莖與《夜巡》的酬金比較，顯示狂熱的規模多麼奇怪。"},{"en":"The painting reference helps readers understand the historical value of money.","zh":"這個畫作參照幫助讀者理解金錢的歷史價值。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":5},{"front":"be lost to history","meaning":"已被歷史遺忘","examples":[{"en":"The bulb owner’s name is now lost to history.","zh":"球莖物主的名字如今已被歷史遺忘。"},{"en":"To be lost to history means to be forgotten because records no longer preserve the information.","zh":"已被歷史遺忘，是指因記錄不再保存資料而被遺忘。"},{"en":"The builders of many old roads are lost to history.","zh":"許多古老道路的建造者已被歷史遺忘。"},{"en":"When names are lost to history, we may know the event but not the people behind it.","zh":"當名字已被歷史遺忘時，我們可能知道事件，但不知道背後的人。"},{"en":"This phrase shows that the tulip owner became anonymous over time.","zh":"這個短語顯示鬱金香物主隨時間變得無名。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":5},{"front":"nix the offer","meaning":"拒絕該出價","examples":[{"en":"The bulb’s owner nixed the offer.","zh":"球莖物主拒絕了該出價。"},{"en":"To nix an offer means to reject or refuse it.","zh":"拒絕該出價，是指不接受該提議或金額。"},{"en":"A landlord may nix an offer if the price is too low.","zh":"如果價格太低，業主可能拒絕該出價。"},{"en":"Someone may nix an offer even if it is generous, because they value the item more.","zh":"即使出價慷慨，有人也可能拒絕，因為他們更重視該物品。"},{"en":"The tulip owner nixed the offer despite the huge amount of money.","zh":"鬱金香物主儘管金額巨大，仍拒絕該出價。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":6},{"front":"refuse to sell for","meaning":"拒絕以……出售","examples":[{"en":"The tulip lover refused to sell for a small fortune.","zh":"那位鬱金香愛好者拒絕以一大筆錢出售。"},{"en":"To refuse to sell for an amount means to reject that price and keep the item.","zh":"拒絕以某金額出售，是指拒絕該價格並保留物品。"},{"en":"A collector may refuse to sell for a high price if the object has personal meaning.","zh":"如果物品有個人意義，收藏家可能拒絕以高價出售。"},{"en":"Refusing to sell for a fortune suggests the owner believes the item is even more valuable.","zh":"拒絕以巨款出售，暗示物主相信該物品更有價值。"},{"en":"In the passage, the refusal shows how intensely people valued rare tulips.","zh":"在篇章中，這次拒絕顯示人們對稀有鬱金香的重視有多強烈。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":6},{"front":"a small fortune","meaning":"一大筆錢","examples":[{"en":"The buyer was willing to pay a small fortune for the bulb.","zh":"買家願意為球莖支付一大筆錢。"},{"en":"A small fortune means a very large amount of money.","zh":"一大筆錢，是指非常大的金額。"},{"en":"A family may spend a small fortune on medical treatment if insurance does not cover it.","zh":"如果保險不涵蓋，家庭可能在醫療上花一大筆錢。"},{"en":"If people pay a small fortune for a flower, desire has clearly become extreme.","zh":"如果人們為一朵花支付一大筆錢，渴望明顯已變得極端。"},{"en":"This phrase is informal and emphasises that the cost is surprisingly high.","zh":"這個短語較口語，強調成本高得令人驚訝。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":6},{"front":"be willing to splurge","meaning":"願意豪花金錢","examples":[{"en":"One tulip lover was willing to splurge on a rare bulb.","zh":"一位鬱金香愛好者願意豪花金錢購買稀有球莖。"},{"en":"To be willing to splurge means to be ready to spend a lot of money on something special.","zh":"願意豪花金錢，是指準備為特別的東西花很多錢。"},{"en":"A parent may be willing to splurge on a birthday meal for a child.","zh":"父母可能願意為孩子的生日餐豪花金錢。"},{"en":"People splurge when they feel the item is rare, meaningful or exciting.","zh":"當人們覺得物品稀有、有意義或令人興奮時，就會豪花金錢。"},{"en":"The tulip lover’s willingness to splurge shows the power of desire in the market.","zh":"鬱金香愛好者願意豪花金錢，顯示市場中渴望的力量。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":6},{"front":"spring to mind","meaning":"浮現在腦海","examples":[{"en":"A question springs to mind after reading the book.","zh":"讀完這本書後，一個問題浮現在腦海。"},{"en":"If something springs to mind, it appears suddenly in your thoughts.","zh":"如果某事浮現在腦海，意思是它突然出現在你的思緒中。"},{"en":"When I hear “summer,” beaches and cold drinks spring to mind.","zh":"當我聽到「夏天」，沙灘和凍飲就浮現在腦海。"},{"en":"A dramatic story can make many questions spring to mind.","zh":"戲劇性的故事可以令許多問題浮現在腦海。"},{"en":"This phrase is useful for describing an immediate thought or reaction.","zh":"這個短語適合描述即時的想法或反應。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":6},{"front":"the world’s most coveted flower","meaning":"世上最令人渴求的花","examples":[{"en":"The book calls the tulip the world’s most coveted flower.","zh":"這本書稱鬱金香為世上最令人渴求的花。"},{"en":"The world’s most coveted flower means the flower most strongly desired by people around the world or in that context.","zh":"世上最令人渴求的花，是指在全球或該背景中最被人強烈渴望的花。"},{"en":"A rare orchid might become the world’s most coveted flower among collectors.","zh":"一種稀有蘭花可能成為收藏家之間世上最令人渴求的花。"},{"en":"When something is coveted, people compete to own it.","zh":"當某物令人渴求，人們就會競爭擁有它。"},{"en":"Calling the tulip the world’s most coveted flower shows the intensity of tulip mania.","zh":"稱鬱金香為世上最令人渴求的花，顯示鬱金香狂熱的強度。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":6},{"front":"extraordinary passions","meaning":"強烈得非比尋常的熱情","examples":[{"en":"The flower aroused extraordinary passions.","zh":"這種花激起強烈得非比尋常的熱情。"},{"en":"Extraordinary passions are unusually strong feelings of desire, excitement or attachment.","zh":"強烈得非比尋常的熱情，是指異常強烈的渴望、興奮或依戀。"},{"en":"A famous singer may arouse extraordinary passions among devoted fans.","zh":"著名歌手可能在忠實粉絲中激起非比尋常的熱情。"},{"en":"Extraordinary passions can push people to spend more than they planned.","zh":"強烈得非比尋常的熱情可以推動人們花超出計劃的金錢。"},{"en":"The tulip aroused extraordinary passions because beauty and rarity made people irrational.","zh":"鬱金香激起強烈得非比尋常的熱情，因為美感和稀有性令人失去理性。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":6},{"front":"be aroused by","meaning":"由……激起","examples":[{"en":"Extraordinary passions were aroused by the tulip.","zh":"強烈得非比尋常的熱情由鬱金香激起。"},{"en":"To be aroused by something means to be stirred, awakened or strongly caused by it.","zh":"由某物激起，是指被它喚起、激發或強烈引起。"},{"en":"Public anger may be aroused by unfair rules.","zh":"不公平規則可能激起公眾憤怒。"},{"en":"Curiosity can be aroused by a mysterious story opening.","zh":"神秘的故事開頭可以激起好奇心。"},{"en":"In the passage, strong desire was aroused by the tulip’s beauty and scarcity.","zh":"在篇章中，強烈渴望由鬱金香的美感和稀缺性激起。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":6},{"front":"British journalist","meaning":"英國記者","examples":[{"en":"Mike Dash is a British journalist.","zh":"Mike Dash 是一名英國記者。"},{"en":"A British journalist is a writer or reporter from Britain who researches and reports information.","zh":"英國記者是來自英國、研究和報道資訊的作者或記者。"},{"en":"A British journalist may write for newspapers, magazines or books.","zh":"英國記者可能為報紙、雜誌或書籍寫作。"},{"en":"Journalists help readers understand events by collecting facts and shaping a clear account.","zh":"記者透過收集事實並整理成清楚記述，幫助讀者理解事件。"},{"en":"The phrase identifies Mike Dash’s nationality and profession.","zh":"這個短語指出 Mike Dash 的國籍和職業。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":6},{"front":"investors","meaning":"投資者","examples":[{"en":"Investors have often compared dot-com speculation with tulip mania.","zh":"投資者常把網科股投機與鬱金香狂熱比較。"},{"en":"Investors are people or organisations that put money into assets hoping to gain profit.","zh":"投資者是把金錢投入資產並希望獲利的人或機構。"},{"en":"Investors may buy shares, property, bonds or business projects.","zh":"投資者可能購買股票、物業、債券或商業項目。"},{"en":"If investors follow excitement without checking value, they may lose money.","zh":"如果投資者只跟隨興奮而不檢查價值，可能會虧損。"},{"en":"The passage shows how investors use tulip mania as a warning example.","zh":"篇章顯示投資者如何使用鬱金香狂熱作為警告例子。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":6},{"front":"intentionally forget","meaning":"故意忘記","examples":[{"en":"Some investors intentionally forgot basic investment lessons.","zh":"有些投資者故意忘記基本投資課。"},{"en":"To intentionally forget something means to ignore it on purpose even though one knows it.","zh":"故意忘記某事，是指明明知道卻有意忽視。"},{"en":"A student may intentionally forget a teacher’s warning because the shortcut looks easier.","zh":"學生可能因捷徑看起來較容易，而故意忘記老師的警告。"},{"en":"Investors intentionally forget risk when they want quick profit more than safety.","zh":"當投資者更想快速獲利而非安全時，就會故意忘記風險。"},{"en":"This phrase suggests the mistake was not innocent ignorance but deliberate neglect.","zh":"這個短語暗示錯誤不是單純無知，而是刻意忽略。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":6},{"front":"Investing 101","meaning":"投資入門","examples":[{"en":"Investors forgot what they learned in Investing 101.","zh":"投資者忘記了他們在投資入門中學到的東西。"},{"en":"Investing 101 means the most basic lessons or principles of investing.","zh":"投資入門是指投資中最基本的課程或原則。"},{"en":"In Investing 101, people learn not to risk all their money on one exciting idea.","zh":"在投資入門中，人們學到不要把所有錢押在一個令人興奮的想法上。"},{"en":"Forgetting Investing 101 can lead to careless buying and painful losses.","zh":"忘記投資入門可能導致粗心買入和痛苦虧損。"},{"en":"The phrase is used humorously to mean “basic investment knowledge.”","zh":"這個短語帶幽默意味，指「基本投資知識」。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":7},{"front":"in order to","meaning":"為了","examples":[{"en":"Some investors forgot the basics in order to buy risky shares.","zh":"有些投資者為了購買高風險股票而忘記基本原則。"},{"en":"In order to means for the purpose of doing something.","zh":"為了，是指以做某事為目的。"},{"en":"Students review vocabulary in order to answer reading questions faster.","zh":"學生為了更快回答閱讀題而複習詞彙。"},{"en":"People may take risks in order to gain something they desire.","zh":"人們可能為了得到渴望的東西而冒險。"},{"en":"This phrase clearly connects an action with its purpose.","zh":"這個短語清楚連接行動與目的。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":7},{"front":"load up on","meaning":"大量買入","examples":[{"en":"Investors loaded up on unproved dot-com issues.","zh":"投資者大量買入未經證實的網科股。"},{"en":"To load up on something means to buy or take a large amount of it.","zh":"大量買入某物，是指購買或取得大量該物。"},{"en":"Families may load up on bottled water before a storm.","zh":"家庭可能在暴風雨前大量買入樽裝水。"},{"en":"Investors who load up on risky shares may suffer badly if prices fall.","zh":"大量買入高風險股票的投資者，如果價格下跌可能損失慘重。"},{"en":"The phrase suggests heavy buying, often more than is sensible.","zh":"這個短語暗示大量購買，而且常常超出理性。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":7},{"front":"unproved, unprofitable","meaning":"未經證實且未能盈利的","examples":[{"en":"Many dot-com issues were unproved and unprofitable.","zh":"許多網科股未經證實且未能盈利。"},{"en":"Unproved and unprofitable means not yet shown to work and not yet making money.","zh":"未經證實且未能盈利，是指尚未證明可行，也尚未賺錢。"},{"en":"A new restaurant idea may be unproved and unprofitable in its first month.","zh":"一個新餐廳概念在第一個月可能未經證實且未能盈利。"},{"en":"Investing in an unproved, unprofitable company is risky because hopes may not become results.","zh":"投資一家未經證實且未能盈利的公司很危險，因為希望未必變成成果。"},{"en":"The phrase warns that excitement alone does not equal business success.","zh":"這個短語提醒人們，興奮本身不等於商業成功。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":7},{"front":"dot-com issues","meaning":"網科股；互聯網公司股票","examples":[{"en":"Investors bought unprofitable dot-com issues.","zh":"投資者購買未能盈利的網科股。"},{"en":"Dot-com issues are shares in internet-based companies, especially those offered to investors.","zh":"網科股是互聯網公司股票，尤其是向投資者發售的股票。"},{"en":"During a technology boom, people may rush to buy dot-com issues.","zh":"在科技熱潮期間，人們可能急於購買網科股。"},{"en":"Dot-com issues can become overpriced if investors focus only on future dreams.","zh":"如果投資者只關注未來夢想，網科股可能變得價格過高。"},{"en":"The passage compares dot-com issues with tulip bulbs as speculative objects.","zh":"篇章把網科股與鬱金香球莖作為投機物件比較。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":7},{"front":"tulip mania","meaning":"鬱金香狂熱","examples":[{"en":"Tulip mania has been invoked frequently in recent years.","zh":"鬱金香狂熱近年經常被引用。"},{"en":"Tulip mania refers to the period when tulip bulbs became wildly overpriced through speculation.","zh":"鬱金香狂熱指鬱金香球莖因投機而價格瘋狂過高的時期。"},{"en":"Teachers may use tulip mania to explain how financial bubbles form.","zh":"老師可能用鬱金香狂熱來解釋金融泡沫如何形成。"},{"en":"Tulip mania warns that crowds can push prices far beyond real value.","zh":"鬱金香狂熱警告人們，群眾可以把價格推到遠高於真實價值。"},{"en":"The phrase now often describes irrational market excitement.","zh":"這個短語如今常用來描述非理性的市場興奮。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":7},{"front":"be invoked frequently","meaning":"經常被引用","examples":[{"en":"Tulip mania has been invoked frequently as a warning.","zh":"鬱金香狂熱經常被引用作警告。"},{"en":"To be invoked frequently means to be mentioned or referred to often.","zh":"經常被引用，是指常被提及或參照。"},{"en":"A famous disaster may be invoked frequently when people discuss safety rules.","zh":"當人們討論安全規則時，著名災難可能經常被引用。"},{"en":"Tulip mania is invoked frequently because it offers a clear example of speculation.","zh":"鬱金香狂熱經常被引用，因為它提供清楚的投機例子。"},{"en":"This phrase suggests that an old event remains useful in modern discussions.","zh":"這個短語暗示舊事件在現代討論中仍然有用。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":7},{"front":"concise account","meaning":"簡明記述","examples":[{"en":"Dash wrote a concise account of tulip mania.","zh":"Dash 寫了一篇關於鬱金香狂熱的簡明記述。"},{"en":"A concise account is a clear explanation that gives important details without being too long.","zh":"簡明記述是清楚解釋重要細節而不過長的說明。"},{"en":"A teacher may give a concise account of a war before discussing its causes.","zh":"老師可能在討論戰爭原因前，先給出簡明記述。"},{"en":"A concise account helps readers understand quickly without losing the main point.","zh":"簡明記述幫助讀者快速理解而不失去重點。"},{"en":"The phrase praises writing that is brief but informative.","zh":"這個短語稱讚寫作簡潔但有資訊量。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":7},{"front":"artfully written","meaning":"寫得巧妙的","examples":[{"en":"The book is an artfully written account.","zh":"這本書是一篇寫得巧妙的記述。"},{"en":"Artfully written means written skilfully, with careful structure and style.","zh":"寫得巧妙的，是指以熟練技巧、仔細結構和風格寫成。"},{"en":"An artfully written article can explain a difficult issue without confusing readers.","zh":"寫得巧妙的文章可以解釋困難議題而不令讀者混亂。"},{"en":"When a story is artfully written, readers enjoy both the information and the language.","zh":"當故事寫得巧妙時，讀者既享受資訊，也享受文字。"},{"en":"The phrase suggests that Dash’s book is not only factual but also well crafted.","zh":"這個短語暗示 Dash 的書不只是有事實，也寫得精巧。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":7},{"front":"the real history behind","meaning":"……背後的真實歷史","examples":[{"en":"The book tells the real history behind the buzzword.","zh":"這本書講述這個熱門術語背後的真實歷史。"},{"en":"The real history behind something means the actual events that explain a famous phrase or idea.","zh":"某事背後的真實歷史，是指解釋某個著名詞語或想法的實際事件。"},{"en":"A documentary may reveal the real history behind a national holiday.","zh":"紀錄片可能揭示一個國定假日背後的真實歷史。"},{"en":"Learning the real history behind a phrase can stop people using it carelessly.","zh":"學習一個短語背後的真實歷史，可以防止人們草率使用它。"},{"en":"The book explains the real history behind the phrase “tulip mania.”","zh":"這本書解釋「鬱金香狂熱」這個詞背後的真實歷史。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":7},{"front":"buzzword","meaning":"熱門術語","examples":[{"en":"Tulip mania has become a financial buzzword.","zh":"鬱金香狂熱已成為金融熱門術語。"},{"en":"A buzzword is a popular word or phrase that many people use, sometimes too casually.","zh":"熱門術語是許多人使用的流行詞語或短語，有時用得太隨便。"},{"en":"“Innovation” can become a buzzword if companies say it without explaining real change.","zh":"如果公司只說「創新」而不解釋真正改變，它就可能變成熱門術語。"},{"en":"Buzzwords spread quickly because they sound powerful and easy to remember.","zh":"熱門術語傳播迅速，因為它們聽起來有力又易記。"},{"en":"The passage suggests that tulip mania is often used as a buzzword for market madness.","zh":"篇章暗示鬱金香狂熱常被用作市場瘋狂的熱門術語。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":7},{"front":"cautionary tale","meaning":"警世故事","examples":[{"en":"The story offers a cautionary tale for our times.","zh":"這個故事為我們這個時代提供一個警世故事。"},{"en":"A cautionary tale is a story that warns people not to repeat a mistake.","zh":"警世故事是警告人們不要重複錯誤的故事。"},{"en":"A failed business can become a cautionary tale about borrowing too much money.","zh":"失敗的企業可以成為關於借貸過多的警世故事。"},{"en":"Cautionary tales help people learn from others’ losses before making similar choices.","zh":"警世故事幫助人們在作出類似選擇前，先從別人的損失中學習。"},{"en":"Tulip mania is a cautionary tale about greed, excitement and risky speculation.","zh":"鬱金香狂熱是關於貪婪、興奮和高風險投機的警世故事。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":8},{"front":"for our times","meaning":"對我們這個時代而言","examples":[{"en":"Tulip mania is a cautionary tale for our times.","zh":"鬱金香狂熱對我們這個時代而言是一個警世故事。"},{"en":"For our times means relevant to the modern period or to people living now.","zh":"對我們這個時代而言，是指與現代時期或現今生活的人相關。"},{"en":"A story about online scams can be a warning for our times.","zh":"關於網上騙案的故事對我們這個時代而言可以是一個警告。"},{"en":"Old history becomes useful for our times when it explains present behaviour.","zh":"當舊歷史解釋當下行為時，它對我們這個時代而言就有用。"},{"en":"The phrase suggests that tulip mania still teaches modern investors something.","zh":"這個短語暗示鬱金香狂熱仍能教導現代投資者。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":8},{"front":"go gaga over","meaning":"對……迷得神魂顛倒","examples":[{"en":"The Dutch were not the first to go gaga over the tulip.","zh":"荷蘭人不是第一批對鬱金香迷得神魂顛倒的人。"},{"en":"To go gaga over something means to become extremely excited or obsessed with it.","zh":"對某物迷得神魂顛倒，是指對它變得極度興奮或沉迷。"},{"en":"Children may go gaga over a new toy that everyone at school wants.","zh":"孩子可能對學校人人都想要的新玩具迷得神魂顛倒。"},{"en":"When people go gaga over an object, demand can rise very quickly.","zh":"當人們對某物迷得神魂顛倒，需求可以迅速上升。"},{"en":"The phrase is informal and slightly humorous.","zh":"這個短語較口語，並帶少許幽默感。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":8},{"front":"bloom in Europe","meaning":"在歐洲開花","examples":[{"en":"The first tulip bloomed in Europe in Bavaria.","zh":"第一朵鬱金香在歐洲的巴伐利亞開花。"},{"en":"To bloom in Europe means to flower somewhere in Europe.","zh":"在歐洲開花，是指在歐洲某處開出花朵。"},{"en":"A plant introduced from Asia may bloom in Europe if the climate suits it.","zh":"如果氣候合適，從亞洲引入的植物可能在歐洲開花。"},{"en":"When tulips bloomed in Europe, they began attracting new admirers.","zh":"當鬱金香在歐洲開花，它們開始吸引新的欣賞者。"},{"en":"This phrase marks the plant’s arrival as a visible flower in Europe.","zh":"這個短語標記這種植物以可見花朵形式到達歐洲。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":8},{"front":"enchanted the Persians","meaning":"令波斯人着迷","examples":[{"en":"The tulip had enchanted the Persians before it reached Holland.","zh":"鬱金香在到達荷蘭前已令波斯人着迷。"},{"en":"To enchant people means to charm or delight them strongly.","zh":"令某人着迷，是指強烈吸引或使他們喜愛。"},{"en":"A beautiful song can enchant an audience and make them fall silent.","zh":"一首美麗歌曲可以令觀眾着迷，讓他們安靜下來。"},{"en":"If a flower enchants a culture, people may use it in art, gardens and poetry.","zh":"如果一種花令某文化着迷，人們可能把它用於藝術、花園和詩歌中。"},{"en":"The passage says tulips fascinated the Persians before they fascinated the Dutch.","zh":"篇章說鬱金香在令荷蘭人着迷之前，已先令波斯人着迷。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":8},{"front":"bewitch the rulers of","meaning":"迷住……的統治者","examples":[{"en":"The tulip bewitched the rulers of the Ottoman Empire.","zh":"鬱金香迷住了奧斯曼帝國的統治者。"},{"en":"To bewitch the rulers of a place means to fascinate its leaders powerfully.","zh":"迷住某地的統治者，是指強烈吸引其領袖。"},{"en":"A new palace design may bewitch the rulers of a wealthy kingdom.","zh":"新宮殿設計可能迷住富裕王國的統治者。"},{"en":"When a luxury object bewitches rulers, it can become fashionable among elites.","zh":"當奢侈物迷住統治者，它可以在精英階層中變得流行。"},{"en":"The phrase suggests the tulip had almost magical appeal.","zh":"這個短語暗示鬱金香有近乎魔法般的吸引力。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":8},{"front":"Ottoman Empire","meaning":"奧斯曼帝國","examples":[{"en":"The rulers of the Ottoman Empire admired tulips.","zh":"奧斯曼帝國的統治者欣賞鬱金香。"},{"en":"The Ottoman Empire was a major historical empire connected with parts of the Middle East, Europe and North Africa.","zh":"奧斯曼帝國是一個重要歷史帝國，與中東、歐洲和北非部分地區有關。"},{"en":"A history class may study the Ottoman Empire when discussing trade and culture.","zh":"歷史課討論貿易和文化時，可能研究奧斯曼帝國。"},{"en":"The Ottoman Empire’s interest in tulips shows that the flower was admired before reaching Holland.","zh":"奧斯曼帝國對鬱金香的興趣，顯示這種花在到達荷蘭前已受欣賞。"},{"en":"Mentioning the Ottoman Empire helps trace the tulip’s cultural journey.","zh":"提到奧斯曼帝國有助追溯鬱金香的文化旅程。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":8},{"front":"passion for","meaning":"對……的熱情","examples":[{"en":"The passion for tulips found fertile ground in Holland.","zh":"對鬱金香的熱情在荷蘭找到滋長的沃土。"},{"en":"Passion for something means a strong enthusiasm or love for it.","zh":"對某物的熱情，是指對它有強烈興趣或喜愛。"},{"en":"A student with a passion for music may practise every day after school.","zh":"對音樂有熱情的學生可能每天放學後練習。"},{"en":"Passion for a hobby can become expensive if rare items are involved.","zh":"如果涉及稀有物品，對興趣的熱情可能變得昂貴。"},{"en":"In Holland, passion for tulips grew into social and financial excitement.","zh":"在荷蘭，對鬱金香的熱情發展成社交和金融興奮。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":8},{"front":"find fertile ground","meaning":"找到滋長的沃土","examples":[{"en":"The passion for tulips found fertile ground in Holland.","zh":"對鬱金香的熱情在荷蘭找到滋長的沃土。"},{"en":"To find fertile ground means to find conditions that allow an idea, habit or trend to grow easily.","zh":"找到滋長的沃土，是指找到讓想法、習慣或潮流容易發展的條件。"},{"en":"A new tutoring method may find fertile ground in a school that welcomes innovation.","zh":"新補習方法可能在歡迎創新的學校找到滋長的沃土。"},{"en":"Speculation finds fertile ground when people have money, hope and stories of profit.","zh":"當人們有錢、有希望和暴利故事時，投機就找到滋長的沃土。"},{"en":"The phrase compares social conditions to soil where something can grow.","zh":"這個短語把社會條件比作讓某物生長的泥土。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":8},{"front":"have little to do with","meaning":"與……幾乎無關","examples":[{"en":"The Dutch craze had little to do with horticulture.","zh":"荷蘭人的狂熱與園藝幾乎無關。"},{"en":"To have little to do with something means to be only weakly connected to it.","zh":"與某事幾乎無關，是指與它只有很弱的關聯。"},{"en":"A student’s poor score may have little to do with ability and more to do with lack of sleep.","zh":"學生成績差可能與能力幾乎無關，而更多與睡眠不足有關。"},{"en":"The tulip craze had little to do with gardening because buyers focused on profit and status.","zh":"鬱金香狂熱與園藝幾乎無關，因為買家關注的是利潤和地位。"},{"en":"This phrase separates the apparent topic from the real cause.","zh":"這個短語把表面主題與真正原因分開。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":8},{"front":"horticulture","meaning":"園藝","examples":[{"en":"The passion for tulips had little to do with horticulture.","zh":"對鬱金香的熱情與園藝幾乎無關。"},{"en":"Horticulture is the study or practice of growing flowers, fruit, vegetables and ornamental plants.","zh":"園藝是研究或實踐種植花卉、水果、蔬菜和觀賞植物。"},{"en":"Someone trained in horticulture knows how to care for soil, seeds and plant health.","zh":"受過園藝訓練的人知道如何照顧泥土、種子和植物健康。"},{"en":"The tulip craze was not mainly about horticulture, but about money and status.","zh":"鬱金香狂熱主要不是關於園藝，而是關於金錢和地位。"},{"en":"This word is more specific than ordinary gardening.","zh":"這個詞比普通「種花」更具體。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":8},{"front":"embark on","meaning":"開始進入","examples":[{"en":"Holland was embarking on its Golden Age.","zh":"荷蘭正開始進入其黃金時代。"},{"en":"To embark on something means to begin an important period, journey or project.","zh":"開始進入某事，是指展開一個重要時期、旅程或計劃。"},{"en":"A company may embark on a new plan after hiring a new manager.","zh":"公司聘請新經理後，可能開始進入新計劃階段。"},{"en":"A society embarking on prosperity may have more money for trade, art and luxury.","zh":"一個開始進入繁榮的社會，可能有更多金錢用於貿易、藝術和奢侈品。"},{"en":"The phrase shows that Holland was just beginning a major historical phase.","zh":"這個短語顯示荷蘭正開始一個重要歷史階段。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":9},{"front":"Golden Age","meaning":"黃金時代","examples":[{"en":"Holland was entering its Golden Age.","zh":"荷蘭正進入其黃金時代。"},{"en":"A Golden Age is a period of great success, wealth, creativity or power.","zh":"黃金時代是指成功、財富、創造力或權力高度發展的時期。"},{"en":"People may call a period a Golden Age if art, trade and science all flourish.","zh":"如果藝術、貿易和科學都繁榮，人們可能稱該時期為黃金時代。"},{"en":"During a Golden Age, luxury goods often become more visible.","zh":"在黃金時代，奢侈品通常變得更常見。"},{"en":"Holland’s Golden Age created conditions in which tulip collecting could grow.","zh":"荷蘭的黃金時代創造了鬱金香收藏得以發展的條件。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":9},{"front":"go toward","meaning":"用於","examples":[{"en":"Resources had gone toward fighting for independence.","zh":"資源曾用於爭取獨立。"},{"en":"To go toward something means to be used for that purpose.","zh":"用於某事，是指被用作該目的。"},{"en":"Part of the school budget may go toward buying new computers.","zh":"學校部分預算可能用於購買新電腦。"},{"en":"If money goes toward war, less may remain for trade or public services.","zh":"如果金錢用於戰爭，留給貿易或公共服務的可能較少。"},{"en":"The phrase explains where resources were directed before commerce expanded.","zh":"這個短語解釋商業擴張前資源被投放到哪裡。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":9},{"front":"fight for independence from","meaning":"爭取脫離……獨立","examples":[{"en":"The Dutch had been fighting for independence from Spain.","zh":"荷蘭人一直在爭取脫離西班牙獨立。"},{"en":"To fight for independence from a power means to struggle to become politically free from it.","zh":"爭取脫離某權力獨立，是指努力從其政治控制中獲得自由。"},{"en":"A colony may fight for independence from an empire when it wants self-rule.","zh":"當殖民地想自治時，可能爭取脫離帝國獨立。"},{"en":"Fighting for independence can use large amounts of money, labour and attention.","zh":"爭取獨立可能消耗大量金錢、勞力和注意力。"},{"en":"The phrase explains why Dutch resources had previously been focused on war.","zh":"這個短語解釋為何荷蘭資源此前集中於戰爭。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":9},{"front":"flow into commerce","meaning":"流入商業","examples":[{"en":"Resources now flowed into commerce.","zh":"資源現在流入商業。"},{"en":"To flow into commerce means money, labour or attention moves into trade and business.","zh":"流入商業，是指金錢、勞力或注意力轉向貿易和生意。"},{"en":"After peace returns, investment may flow into commerce instead of defence.","zh":"和平恢復後，投資可能流入商業而不是國防。"},{"en":"When resources flow into commerce, merchants can expand shops, ships and markets.","zh":"當資源流入商業，商人可以擴展店舖、船隊和市場。"},{"en":"This phrase describes a shift from war spending to business activity.","zh":"這個短語描述從戰爭開支轉向商業活動。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":9},{"front":"Amsterdam merchants","meaning":"阿姆斯特丹商人","examples":[{"en":"Amsterdam merchants were at the centre of international trade.","zh":"阿姆斯特丹商人處於國際貿易的中心。"},{"en":"Amsterdam merchants were traders based in Amsterdam who bought and sold goods internationally.","zh":"阿姆斯特丹商人是以阿姆斯特丹為基地、進行國際買賣的商人。"},{"en":"Amsterdam merchants could become wealthy through shipping and overseas trade.","zh":"阿姆斯特丹商人可以透過航運和海外貿易致富。"},{"en":"Wealthy merchants often spent money on homes, gardens and luxury objects.","zh":"富有商人常把錢花在住宅、花園和奢侈品上。"},{"en":"Their wealth helped create a society where rare tulips could become status symbols.","zh":"他們的財富幫助形成一個稀有鬱金香可成為地位象徵的社會。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":9},{"front":"at the center of","meaning":"處於……的中心","examples":[{"en":"Amsterdam merchants were at the center of the East Indies trade.","zh":"阿姆斯特丹商人處於東印度貿易的中心。"},{"en":"At the center of something means in the most important or active position within it.","zh":"處於某事的中心，是指在其中最重要或最活躍的位置。"},{"en":"A teacher is often at the center of classroom discussion.","zh":"老師常處於課堂討論的中心。"},{"en":"Cities at the center of trade can become rich and influential.","zh":"處於貿易中心的城市可以變得富有而有影響力。"},{"en":"The phrase shows Amsterdam’s important role in overseas commerce.","zh":"這個短語顯示阿姆斯特丹在海外商業中的重要角色。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":9},{"front":"lucrative trade","meaning":"利潤豐厚的貿易","examples":[{"en":"The East Indies trade was highly lucrative.","zh":"東印度貿易利潤非常豐厚。"},{"en":"Lucrative trade is trade that brings large profits.","zh":"利潤豐厚的貿易，是指帶來大量利潤的貿易。"},{"en":"Selling rare spices overseas could be lucrative trade in earlier centuries.","zh":"在早期世紀，把稀有香料賣到海外可能是利潤豐厚的貿易。"},{"en":"Lucrative trade gives merchants money to spend on houses, art and luxury goods.","zh":"利潤豐厚的貿易給商人金錢花在房屋、藝術和奢侈品上。"},{"en":"The passage links lucrative trade with the wealth behind tulip collecting.","zh":"篇章把利潤豐厚的貿易與鬱金香收藏背後的財富連繫起來。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":9},{"front":"East Indies trade","meaning":"東印度貿易","examples":[{"en":"Amsterdam merchants profited from the East Indies trade.","zh":"阿姆斯特丹商人從東印度貿易中獲利。"},{"en":"The East Indies trade was overseas trade with Asian regions known historically as the East Indies.","zh":"東印度貿易是與歷史上稱為東印度的亞洲地區進行的海外貿易。"},{"en":"Merchants involved in the East Indies trade could import spices, textiles and other valuable goods.","zh":"參與東印度貿易的商人可以進口香料、紡織品和其他貴重貨物。"},{"en":"Profits from the East Indies trade helped make Amsterdam merchants wealthy.","zh":"東印度貿易的利潤幫助阿姆斯特丹商人致富。"},{"en":"This trade background explains why luxury spending could grow in Holland.","zh":"這種貿易背景解釋了為何荷蘭奢侈消費可以增長。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":9},{"front":"a single voyage","meaning":"單次航程","examples":[{"en":"A single voyage could yield profits of 400%.","zh":"單次航程可以產生 400% 的利潤。"},{"en":"A single voyage means one journey, especially by ship.","zh":"單次航程是指一次旅程，尤其是船隻旅程。"},{"en":"A merchant ship’s single voyage might take months but bring valuable goods home.","zh":"商船的單次航程可能需時數月，但能把貴重貨物帶回來。"},{"en":"If a single voyage yields huge profits, investors may become eager to fund more trips.","zh":"如果單次航程產生巨大利潤，投資者可能渴望資助更多旅程。"},{"en":"The phrase emphasises how profitable overseas trade could be.","zh":"這個短語強調海外貿易可以多麼有利可圖。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":9},{"front":"yield profits of","meaning":"產生……利潤","examples":[{"en":"A voyage could yield profits of 400%.","zh":"一次航程可以產生 400% 的利潤。"},{"en":"To yield profits of a certain amount means to produce that level of financial gain.","zh":"產生某水平的利潤，是指帶來該程度的財務收益。"},{"en":"A small shop may yield profits of 10% after rent and wages are paid.","zh":"小店在支付租金和工資後，可能產生 10% 的利潤。"},{"en":"High expected profits can attract more investors to a risky activity.","zh":"高預期利潤可以吸引更多投資者參與高風險活動。"},{"en":"The phrase shows the financial return from a trade or investment.","zh":"這個短語顯示貿易或投資的財務回報。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":9},{"front":"display their success","meaning":"展示他們的成功","examples":[{"en":"Merchants displayed their success by building grand estates.","zh":"商人透過建造宏偉莊園展示他們的成功。"},{"en":"To display success means to show wealth, status or achievement publicly.","zh":"展示成功，是指公開顯示財富、地位或成就。"},{"en":"A company may display its success by moving into a larger office.","zh":"公司可能透過搬入更大的辦公室展示成功。"},{"en":"People sometimes display success through houses, clothes, cars or donations.","zh":"人們有時透過房屋、衣着、汽車或捐款展示成功。"},{"en":"The merchants’ estates showed others how wealthy they had become.","zh":"商人的莊園向他人展示他們變得多麼富有。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":10},{"front":"erect grand estates","meaning":"建造宏偉莊園","examples":[{"en":"Wealthy merchants erected grand estates surrounded by gardens.","zh":"富有商人建造由花園圍繞的宏偉莊園。"},{"en":"To erect grand estates means to build large, impressive homes and grounds.","zh":"建造宏偉莊園，是指興建大型而令人印象深刻的住宅和園地。"},{"en":"A rich family may erect a grand estate outside the city to show its status.","zh":"富裕家庭可能在城外建造宏偉莊園來展示地位。"},{"en":"Grand estates require money, land and workers, so they signal wealth.","zh":"宏偉莊園需要金錢、土地和工人，因此象徵財富。"},{"en":"The phrase describes how merchants turned commercial success into visible luxury.","zh":"這個短語描述商人如何把商業成功轉化為可見的奢華。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":10},{"front":"surrounded by","meaning":"被……圍繞","examples":[{"en":"The estates were surrounded by flower gardens.","zh":"這些莊園被花園圍繞。"},{"en":"Surrounded by means having something all around it.","zh":"被某物圍繞，是指四周都有該物。"},{"en":"A school surrounded by trees feels quieter than one beside a main road.","zh":"被樹木圍繞的學校，比在大路旁的學校感覺更安靜。"},{"en":"A house surrounded by gardens can look private and wealthy.","zh":"被花園圍繞的房屋可以看起來私密而富有。"},{"en":"In the passage, gardens surrounding estates helped display merchants’ taste and success.","zh":"在篇章中，圍繞莊園的花園幫助展示商人的品味和成功。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":10},{"front":"be torn between","meaning":"在……之間左右為難","examples":[{"en":"The Dutch population seemed torn between two contradictory impulses.","zh":"荷蘭人似乎在兩種矛盾衝動之間左右為難。"},{"en":"To be torn between two things means to feel pulled in two different directions.","zh":"在兩件事之間左右為難，是指感到被兩個不同方向拉扯。"},{"en":"A student may be torn between studying abroad and staying near family.","zh":"學生可能在出國留學與留在家人附近之間左右為難。"},{"en":"People torn between caution and excitement may make inconsistent choices.","zh":"在謹慎與興奮之間左右為難的人，可能作出不一致的選擇。"},{"en":"The phrase helps explain why Dutch society could be both careful and speculative.","zh":"這個短語幫助解釋為何荷蘭社會既可以謹慎又可以投機。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":10},{"front":"contradictory impulses","meaning":"矛盾的衝動","examples":[{"en":"The Dutch had two contradictory impulses.","zh":"荷蘭人有兩種矛盾的衝動。"},{"en":"Contradictory impulses are desires or urges that pull people in opposite directions.","zh":"矛盾的衝動，是指把人拉向相反方向的願望或衝動。"},{"en":"A person may feel contradictory impulses to save money and buy something expensive.","zh":"一個人可能同時有省錢和購買昂貴物品的矛盾衝動。"},{"en":"Contradictory impulses can make behaviour look confusing or inconsistent.","zh":"矛盾的衝動可以令行為看起來混亂或不一致。"},{"en":"The Dutch impulse toward thrift conflicted with the love of risky opportunity.","zh":"荷蘭人節儉的衝動與喜歡高風險機會的衝動相衝突。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":10},{"front":"a horror of","meaning":"對……的恐懼","examples":[{"en":"Many Dutch people had a horror of living beyond their means.","zh":"許多荷蘭人對入不敷支有恐懼。"},{"en":"A horror of something means a strong fear or dislike of it.","zh":"對某事的恐懼，是指對它有強烈害怕或厭惡。"},{"en":"Some parents have a horror of debt because they grew up with financial stress.","zh":"有些父母對債務有恐懼，因為他們在財務壓力中長大。"},{"en":"A horror of waste can make people repair old items instead of replacing them.","zh":"對浪費的恐懼可以令人修理舊物而不是更換。"},{"en":"The phrase shows that many Dutch people strongly disliked overspending.","zh":"這個短語顯示許多荷蘭人強烈不喜歡過度花費。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":10},{"front":"live beyond one’s means","meaning":"入不敷支；超出負擔能力生活","examples":[{"en":"The Dutch disliked living beyond one’s means.","zh":"荷蘭人不喜歡入不敷支。"},{"en":"To live beyond one’s means means to spend more money than one can afford.","zh":"入不敷支，是指花費超過自己能負擔的金額。"},{"en":"A worker lives beyond his means if his monthly spending is higher than his salary.","zh":"如果工人的每月開支高於薪金，他就是入不敷支。"},{"en":"Living beyond one’s means can lead to debt and stress.","zh":"入不敷支可能導致債務和壓力。"},{"en":"The phrase reflects a fear of careless spending and financial irresponsibility.","zh":"這個短語反映對粗心花費和財務不負責任的恐懼。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":10},{"front":"the love of a long shot","meaning":"喜歡碰運氣的高風險機會","examples":[{"en":"The Dutch also had a love of a long shot.","zh":"荷蘭人也喜歡碰運氣的高風險機會。"},{"en":"A love of a long shot means enjoyment of risky chances that are unlikely but could bring a big reward.","zh":"喜歡碰運氣的高風險機會，是指喜歡那些機會不大但可能帶來巨大回報的冒險。"},{"en":"Buying a lottery ticket shows a love of a long shot.","zh":"買彩票顯示喜歡碰運氣的高風險機會。"},{"en":"A love of a long shot can make people ignore safer choices.","zh":"喜歡高風險機會可能令人忽略較安全的選擇。"},{"en":"This phrase helps explain why cautious people might still join tulip speculation.","zh":"這個短語幫助解釋為何謹慎的人仍可能參與鬱金香投機。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":10},{"front":"comprehend","meaning":"理解","examples":[{"en":"It is impossible to comprehend tulip mania without understanding tulips.","zh":"若不了解鬱金香，就不可能理解鬱金香狂熱。"},{"en":"To comprehend something means to understand it fully.","zh":"理解某事，是指完全明白它。"},{"en":"Students must comprehend the question before choosing an answer.","zh":"學生必須先理解題目，再選擇答案。"},{"en":"To comprehend a financial bubble, we need to understand both prices and human behaviour.","zh":"要理解金融泡沫，我們需要了解價格和人類行為。"},{"en":"The passage says readers must know the flower before they can understand the craze.","zh":"篇章說讀者必須先認識這種花，才能理解這場狂熱。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":10},{"front":"every other flower known to","meaning":"……所知的其他所有花","examples":[{"en":"Tulips were different from every other flower known to horticulturists.","zh":"鬱金香與園藝學家所知的其他所有花都不同。"},{"en":"Every other flower known to a group means all the other flowers that group was familiar with.","zh":"某群體所知的其他所有花，是指該群體熟悉的全部其他花。"},{"en":"A new plant may look different from every other flower known to local gardeners.","zh":"一種新植物可能看起來與本地園丁所知的其他所有花都不同。"},{"en":"If something differs from every other known example, experts are likely to notice it.","zh":"如果某物與所有已知例子都不同，專家很可能會注意到它。"},{"en":"This phrase emphasises how unusual tulips seemed to specialists.","zh":"這個短語強調鬱金香在專家眼中多麼不尋常。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":10},{"front":"horticulturists","meaning":"園藝學家","examples":[{"en":"Horticulturists recognised that tulips were unusual.","zh":"園藝學家認出鬱金香很不尋常。"},{"en":"Horticulturists are people who study or practise the cultivation of garden plants.","zh":"園藝學家是研究或實踐栽培園藝植物的人。"},{"en":"Horticulturists may advise parks on which flowers grow best in local soil.","zh":"園藝學家可能建議公園哪些花最適合本地泥土。"},{"en":"Because horticulturists understand plants, their interest can increase a flower’s reputation.","zh":"因為園藝學家了解植物，他們的興趣可以提升花卉名聲。"},{"en":"In the passage, horticulturists noticed tulips’ unusual colours and form.","zh":"在篇章中，園藝學家注意到鬱金香不尋常的顏色和形態。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":10},{"front":"exhibit colours","meaning":"呈現顏色","examples":[{"en":"Tulips exhibited more intense colours than ordinary plants.","zh":"鬱金香呈現比普通植物更鮮明的顏色。"},{"en":"To exhibit colours means to show or display colours visibly.","zh":"呈現顏色，是指明顯展示顏色。"},{"en":"Some butterflies exhibit bright colours to warn predators.","zh":"有些蝴蝶呈現鮮艷顏色來警告捕食者。"},{"en":"Flowers that exhibit unusual colours often attract collectors and gardeners.","zh":"呈現不尋常顏色的花常吸引收藏家和園丁。"},{"en":"Tulips exhibited colours that seemed richer than those of ordinary plants.","zh":"鬱金香呈現的顏色似乎比普通植物更濃郁。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":11},{"front":"more intense and more concentrated","meaning":"更鮮明且更濃烈","examples":[{"en":"The colours were more intense and more concentrated.","zh":"這些顏色更鮮明且更濃烈。"},{"en":"More intense and more concentrated means stronger, richer and less diluted.","zh":"更鮮明且更濃烈，是指更強、更濃郁、較不淡薄。"},{"en":"A sauce becomes more intense and more concentrated after it boils down.","zh":"醬汁煮濃後會變得更鮮明且更濃烈。"},{"en":"Strong colours can make a flower look more valuable and memorable.","zh":"強烈色彩可以令花看起來更有價值和更難忘。"},{"en":"The phrase explains why tulips looked unusually vivid to observers.","zh":"這個短語解釋為何鬱金香在觀察者眼中異常鮮艷。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":11},{"front":"ordinary plants","meaning":"普通植物","examples":[{"en":"Tulips looked different from ordinary plants.","zh":"鬱金香看起來與普通植物不同。"},{"en":"Ordinary plants are common plants that do not seem rare, unusual or especially striking.","zh":"普通植物是常見、看起來不稀有、不特殊或不特別醒目的植物。"},{"en":"Grass and simple garden shrubs may look like ordinary plants beside bright flowers.","zh":"草和簡單園藝灌木在鮮艷花卉旁可能看似普通植物。"},{"en":"When something differs from ordinary plants, collectors may become interested.","zh":"當某物與普通植物不同，收藏家可能會感興趣。"},{"en":"The phrase helps contrast tulips with more familiar garden growth.","zh":"這個短語幫助把鬱金香與更熟悉的園藝植物作對比。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":11},{"front":"despite","meaning":"儘管","examples":[{"en":"Despite high prices for rare bulbs, ordinary tulips were cheap.","zh":"儘管稀有球莖價格高，普通鬱金香仍然便宜。"},{"en":"Despite means although something is true, another contrasting fact is also true.","zh":"儘管是指雖然某事是真的，但另一個相反事實也是真的。"},{"en":"Despite heavy rain, the school picnic continued indoors.","zh":"儘管下大雨，學校野餐仍在室內繼續。"},{"en":"Despite the fame of rare tulips, common tulips remained affordable.","zh":"儘管稀有鬱金香有名，普通鬱金香仍可負擔。"},{"en":"This word helps show contrast between rare bulbs and ordinary ones.","zh":"這個詞幫助展示稀有球莖與普通球莖之間的對比。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":11},{"front":"outlandish prices","meaning":"離譜高價","examples":[{"en":"Rare bulbs commanded outlandish prices.","zh":"稀有球莖索得離譜高價。"},{"en":"Outlandish prices are extremely high prices that seem unreasonable or shocking.","zh":"離譜高價是極高、看起來不合理或令人震驚的價格。"},{"en":"A small bottle of water at an airport may have an outlandish price compared with a supermarket.","zh":"機場一小瓶水與超市相比可能有離譜高價。"},{"en":"Outlandish prices can appear when buyers believe an item is rare and must be bought quickly.","zh":"當買家相信物品稀有且必須快速買下時，離譜高價可能出現。"},{"en":"Tulip bulbs reached outlandish prices because speculation overwhelmed common sense.","zh":"鬱金香球莖達到離譜高價，因為投機壓倒常識。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":11},{"front":"command high prices","meaning":"索得高價；售價高昂","examples":[{"en":"Rare bulbs commanded high prices.","zh":"稀有球莖索得高價。"},{"en":"To command high prices means to be able to sell for large amounts of money.","zh":"索得高價，是指能以大筆金額售出。"},{"en":"A painting by a famous artist can command high prices at auction.","zh":"著名藝術家的畫作可以在拍賣中索得高價。"},{"en":"Items command high prices when they are rare, beautiful or strongly desired.","zh":"物品在稀有、美麗或極受渴望時會索得高價。"},{"en":"The phrase suggests the market was willing to pay a lot for rare bulbs.","zh":"這個短語暗示市場願意為稀有球莖支付很多錢。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":11},{"front":"rare bulbs","meaning":"稀有球莖","examples":[{"en":"Rare bulbs could command outlandish prices.","zh":"稀有球莖可以索得離譜高價。"},{"en":"Rare bulbs are uncommon tulip bulbs that collectors find difficult to obtain.","zh":"稀有球莖是不常見、收藏家難以取得的鬱金香球莖。"},{"en":"A gardener may keep rare bulbs carefully because replacing them is hard.","zh":"園丁可能小心保存稀有球莖，因為很難替換。"},{"en":"Scarcity makes rare bulbs attractive to collectors and speculators.","zh":"稀缺性令稀有球莖吸引收藏家和投機者。"},{"en":"In the passage, rare bulbs became financial assets as well as plants.","zh":"在篇章中，稀有球莖既是植物，也變成金融資產。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":11},{"front":"be sold by the pound","meaning":"按磅出售","examples":[{"en":"Ordinary tulips were sold by the pound.","zh":"普通鬱金香按磅出售。"},{"en":"To be sold by the pound means to be priced according to weight.","zh":"按磅出售，是指根據重量定價。"},{"en":"Apples and potatoes are often sold by the pound in markets.","zh":"蘋果和薯仔在市場中常按磅出售。"},{"en":"If ordinary tulips were sold by the pound, they were treated as common goods.","zh":"如果普通鬱金香按磅出售，表示它們被當作普通商品。"},{"en":"This phrase contrasts cheap ordinary bulbs with rare bulbs sold for fortunes.","zh":"這個短語把便宜普通球莖與高價稀有球莖作對比。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":11},{"front":"tulip fancier","meaning":"鬱金香愛好者","examples":[{"en":"A new type of tulip fancier appeared around 1630.","zh":"約 1630 年出現了一種新的鬱金香愛好者。"},{"en":"A tulip fancier is a person who enjoys, collects or strongly admires tulips.","zh":"鬱金香愛好者是喜歡、收藏或強烈欣賞鬱金香的人。"},{"en":"A bird fancier may keep rare birds, just as a tulip fancier may seek rare bulbs.","zh":"愛鳥者可能飼養稀有鳥類，就像鬱金香愛好者可能尋找稀有球莖。"},{"en":"When fanciers enter a market, prices can rise because they care about beauty and rarity.","zh":"當愛好者進入市場，價格可能上升，因為他們重視美感和稀有性。"},{"en":"The phrase shows that tulips attracted enthusiasts, not only professional traders.","zh":"這個短語顯示鬱金香吸引了熱衷者，而不只是專業交易商。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":11},{"front":"be lured by","meaning":"被……吸引","examples":[{"en":"Some traders were lured by tales of fat profits.","zh":"有些交易者被暴利傳聞吸引。"},{"en":"To be lured by something means to be attracted or tempted by it.","zh":"被某物吸引，是指受到它誘惑或吸引。"},{"en":"Students may be lured by a cheap course that promises quick fluency.","zh":"學生可能被承諾快速流利的便宜課程吸引。"},{"en":"People can be lured by profit stories even when the risks are serious.","zh":"即使風險嚴重，人們仍可能被利潤故事吸引。"},{"en":"The phrase suggests attraction that may lead people into danger or poor judgement.","zh":"這個短語暗示吸引力可能把人帶入危險或錯誤判斷。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":11},{"front":"tales of fat profits","meaning":"暴利傳聞","examples":[{"en":"Traders were attracted by tales of fat profits.","zh":"交易者被暴利傳聞吸引。"},{"en":"Tales of fat profits are stories about people making very large gains.","zh":"暴利傳聞是關於有人賺取巨大利潤的故事。"},{"en":"Tales of fat profits can spread quickly in workplaces, markets and online groups.","zh":"暴利傳聞可以在工作場所、市場和網上群組快速傳播。"},{"en":"When people hear tales of fat profits, they may enter a market without understanding it.","zh":"當人們聽到暴利傳聞，可能在不了解市場下就進入。"},{"en":"The phrase explains how rumours of wealth drew more traders into tulips.","zh":"這個短語解釋財富傳聞如何吸引更多交易者進入鬱金香市場。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":11},{"front":"professional tulip traders","meaning":"專業鬱金香交易商","examples":[{"en":"Professional tulip traders entered the market.","zh":"專業鬱金香交易商進入市場。"},{"en":"Professional tulip traders were people who bought and sold tulips as a business.","zh":"專業鬱金香交易商是把買賣鬱金香作為生意的人。"},{"en":"Professional traders may know more about prices, buyers and supply than casual collectors.","zh":"專業交易商可能比普通收藏者更了解價格、買家和供應。"},{"en":"When professional tulip traders entered, the market became more organised and speculative.","zh":"當專業鬱金香交易商進入，市場變得更有組織也更投機。"},{"en":"Their presence shows that tulips had moved beyond simple gardening.","zh":"他們的出現顯示鬱金香已超越簡單園藝。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":12},{"front":"seek out","meaning":"尋找","examples":[{"en":"Traders sought out flower lovers and speculators.","zh":"交易商尋找愛花人士和投機者。"},{"en":"To seek out someone means to actively look for them.","zh":"尋找某人，是指主動尋覓他們。"},{"en":"A company may seek out young designers when developing a new brand.","zh":"公司發展新品牌時，可能尋找年輕設計師。"},{"en":"Traders seek out buyers when they believe demand can be expanded.","zh":"當交易商相信需求可以擴大，就會尋找買家。"},{"en":"The phrase shows active searching, not accidental meeting.","zh":"這個短語表示主動搜尋，而不是偶然遇見。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":12},{"front":"speculators alike","meaning":"投機者也一樣","examples":[{"en":"Professional traders sought out flower lovers and speculators alike.","zh":"專業交易商尋找愛花人士，投機者也一樣。"},{"en":"Speculators alike means speculators too, along with the other group mentioned.","zh":"投機者也一樣，是指投機者也包括在內，連同已提及的另一群人。"},{"en":"A popular event may attract tourists and local residents alike.","zh":"熱門活動可能吸引遊客，本地居民也一樣。"},{"en":"Traders targeted flower lovers and speculators alike because both groups could become buyers.","zh":"交易商瞄準愛花人士，投機者也一樣，因為兩者都可能成為買家。"},{"en":"This phrase shows that different types of people were included.","zh":"這個短語顯示不同類型的人都被包括在內。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":12},{"front":"supply of buyers","meaning":"買家供應；買家數量","examples":[{"en":"The supply of tulip buyers grew quickly.","zh":"鬱金香買家數量迅速增加。"},{"en":"Supply of buyers means the number of people willing to buy something.","zh":"買家供應是指願意購買某物的人數。"},{"en":"A new shopping mall may succeed if the supply of buyers is large enough.","zh":"如果買家數量足夠大，新商場可能成功。"},{"en":"When the supply of buyers grows faster than the supply of goods, prices may rise.","zh":"當買家數量增長快過商品供應，價格可能上升。"},{"en":"The growing supply of buyers pushed tulip prices upward.","zh":"不斷增加的買家數量推高了鬱金香價格。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":12},{"front":"supply of bulbs","meaning":"球莖供應","examples":[{"en":"The supply of bulbs did not grow quickly.","zh":"球莖供應沒有迅速增加。"},{"en":"Supply of bulbs means the number of bulbs available for sale or planting.","zh":"球莖供應是指可供出售或種植的球莖數量。"},{"en":"If the supply of tickets is small, prices may rise when many fans want them.","zh":"如果門票供應少，而許多粉絲想要，價格可能上升。"},{"en":"Tulip prices rose because the supply of bulbs could not match the growing number of buyers.","zh":"鬱金香價格上升，因為球莖供應無法追上不斷增加的買家數量。"},{"en":"This phrase explains the shortage side of the market.","zh":"這個短語解釋市場中短缺的一面。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":12},{"front":"supply squeeze","meaning":"供應緊張","examples":[{"en":"The tulip itself contributed to the supply squeeze.","zh":"鬱金香本身也造成供應緊張。"},{"en":"A supply squeeze happens when available supply is too limited for demand.","zh":"供應緊張，是指可用供應相對於需求太有限。"},{"en":"A shortage of drivers can create a supply squeeze in delivery services.","zh":"司機短缺可以在送貨服務中造成供應緊張。"},{"en":"A supply squeeze often raises prices because buyers compete for few goods.","zh":"供應緊張通常會推高價格，因為買家爭奪少量貨品。"},{"en":"Tulips caused a supply squeeze because they could not reproduce quickly enough.","zh":"鬱金香造成供應緊張，因為它們繁殖速度不夠快。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":12},{"front":"grow one from seed","meaning":"從種子種出一株","examples":[{"en":"It takes seven years to grow a tulip from seed.","zh":"從種子種出一株鬱金香需要七年。"},{"en":"To grow one from seed means to produce a plant starting with a seed rather than a bulb or cutting.","zh":"從種子種出一株，是指以種子而不是球莖或插枝開始培育植物。"},{"en":"Growing a fruit tree from seed may take years before it produces fruit.","zh":"從種子種出一棵果樹可能需要多年才結果。"},{"en":"If it takes years to grow one from seed, supply cannot increase quickly.","zh":"如果從種子種出一株需要多年，供應就不能迅速增加。"},{"en":"This explains why tulip bulbs remained scarce despite high demand.","zh":"這解釋了為何儘管需求高，鬱金香球莖仍然稀缺。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":12},{"front":"clones","meaning":"無性繁殖體；複製球","examples":[{"en":"Bulbs can produce two or three clones annually.","zh":"球莖每年可以產生兩三個無性繁殖體。"},{"en":"Clones are genetically identical copies produced from the original plant.","zh":"無性繁殖體是由原植物產生、基因相同的複製個體。"},{"en":"A gardener may use clones to keep a flower’s exact colour and pattern.","zh":"園丁可能使用無性繁殖體來保留花朵的確切顏色和圖案。"},{"en":"Because clones copy the parent plant, rare tulip traits can be preserved.","zh":"因為無性繁殖體複製母株，稀有鬱金香特徵可以被保存。"},{"en":"However, producing only a few clones each year limits supply growth.","zh":"不過，每年只產生少量無性繁殖體會限制供應增長。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":12},{"front":"offsets","meaning":"側球；子球","examples":[{"en":"Tulip bulbs can produce offsets annually.","zh":"鬱金香球莖每年可以產生側球。"},{"en":"Offsets are small new bulbs that grow from the mother bulb.","zh":"側球是從母球莖長出的小型新球莖。"},{"en":"Gardeners may separate offsets and plant them to grow more flowers.","zh":"園丁可能分離側球並種植，以長出更多花。"},{"en":"Offsets help tulips reproduce, but they do not appear in unlimited numbers.","zh":"側球幫助鬱金香繁殖，但數量不是無限。"},{"en":"The slow production of offsets contributed to the tulip supply squeeze.","zh":"側球生產緩慢，造成鬱金香供應緊張。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":12},{"front":"annually","meaning":"每年","examples":[{"en":"Bulbs can produce offsets annually.","zh":"球莖每年可以產生側球。"},{"en":"Annually means once every year or each year.","zh":"每年是指一年一次或每一年。"},{"en":"A school may hold a sports day annually.","zh":"學校可能每年舉行運動會。"},{"en":"If a plant produces only a few new bulbs annually, supply rises slowly.","zh":"如果植物每年只產生少量新球莖，供應就會慢慢上升。"},{"en":"This word helps explain the yearly pace of tulip reproduction.","zh":"這個詞幫助解釋鬱金香繁殖的年度速度。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":12},{"front":"mother bulb","meaning":"母球莖","examples":[{"en":"The mother bulb only lasts a few years.","zh":"母球莖只維持幾年。"},{"en":"A mother bulb is the original bulb that produces smaller new bulbs.","zh":"母球莖是產生較小新球莖的原本球莖。"},{"en":"Gardeners may remove offsets from the mother bulb and plant them separately.","zh":"園丁可能從母球莖取下側球並分開種植。"},{"en":"If the mother bulb lasts only a few years, reproduction is limited by time.","zh":"如果母球莖只維持幾年，繁殖就受時間限制。"},{"en":"This detail helps explain why tulip supply could not expand quickly.","zh":"這個細節幫助解釋為何鬱金香供應不能迅速擴大。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":12},{"front":"bulb prices","meaning":"球莖價格","examples":[{"en":"Bulb prices rose steadily throughout the 1630s.","zh":"球莖價格在整個 1630 年代穩步上升。"},{"en":"Bulb prices are the market prices paid for tulip bulbs.","zh":"球莖價格是市場上為鬱金香球莖支付的價格。"},{"en":"Gardeners may compare bulb prices before deciding which flowers to plant.","zh":"園丁可能在決定種哪些花前比較球莖價格。"},{"en":"Rising bulb prices attracted traders who hoped to sell later for profit.","zh":"上升的球莖價格吸引希望之後賣出獲利的交易者。"},{"en":"In the passage, bulb prices became a sign of growing speculation.","zh":"在篇章中，球莖價格成為投機增長的標誌。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":13},{"front":"rise steadily","meaning":"穩步上升","examples":[{"en":"Bulb prices rose steadily throughout the 1630s.","zh":"球莖價格在整個 1630 年代穩步上升。"},{"en":"To rise steadily means to increase gradually and continuously over time.","zh":"穩步上升，是指隨時間逐漸而持續地增加。"},{"en":"Rent may rise steadily if more people move into a city.","zh":"如果更多人搬入城市，租金可能穩步上升。"},{"en":"Prices that rise steadily can make buyers believe the increase will continue forever.","zh":"穩步上升的價格可以令買家相信升勢會永遠持續。"},{"en":"This phrase describes a long upward trend before the crash.","zh":"這個短語描述崩盤前長期向上的趨勢。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":13},{"front":"ever more speculators","meaning":"越來越多投機者","examples":[{"en":"Ever more speculators entered the market.","zh":"越來越多投機者進入市場。"},{"en":"Ever more speculators means an increasing number of people buying mainly to profit from price changes.","zh":"越來越多投機者，是指越來越多人主要為從價格變動中獲利而購買。"},{"en":"Ever more investors may enter a market when they hear stories of easy money.","zh":"當人們聽到容易賺錢的故事，越來越多投資者可能進入市場。"},{"en":"As ever more speculators join, prices can rise faster than real value.","zh":"隨着越來越多投機者加入，價格可以上升得快過真實價值。"},{"en":"The phrase shows how the tulip market became crowded with profit-seekers.","zh":"這個短語顯示鬱金香市場如何充滿追求利潤的人。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":13},{"front":"enter the market","meaning":"進入市場","examples":[{"en":"Speculators entered the tulip market.","zh":"投機者進入鬱金香市場。"},{"en":"To enter the market means to begin buying, selling or competing in a market.","zh":"進入市場，是指開始在市場中購買、出售或競爭。"},{"en":"A new restaurant brand may enter the market with low prices.","zh":"新餐廳品牌可能以低價進入市場。"},{"en":"When many new buyers enter the market, demand can rise quickly.","zh":"當許多新買家進入市場，需求可以迅速上升。"},{"en":"In tulip mania, speculators entered the market because they expected profits.","zh":"在鬱金香狂熱中，投機者進入市場，因為他們預期有利可圖。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":13},{"front":"mortgage whatever they could","meaning":"把能抵押的都拿去抵押","examples":[{"en":"Weavers and farmers mortgaged whatever they could.","zh":"織工和農民把能抵押的都拿去抵押。"},{"en":"To mortgage whatever they could means to borrow money by using any available property as security.","zh":"把能抵押的都拿去抵押，是指用任何可用財產作擔保借錢。"},{"en":"A family in trouble may mortgage whatever they can to pay urgent debts.","zh":"陷入困境的家庭可能把能抵押的都拿去抵押，以支付緊急債務。"},{"en":"When people mortgage whatever they can for speculation, the risk becomes personal and dangerous.","zh":"當人們為投機把能抵押的都拿去抵押，風險就變得個人化而危險。"},{"en":"The phrase shows how ordinary people risked their homes and possessions for tulip trading.","zh":"這個短語顯示普通人如何為鬱金香交易冒着失去家園和財物的風險。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":13},{"front":"raise cash","meaning":"籌集現金","examples":[{"en":"They mortgaged property to raise cash for trading.","zh":"他們抵押財產來籌集現金進行交易。"},{"en":"To raise cash means to obtain money, often quickly, for a specific purpose.","zh":"籌集現金，是指為特定目的取得金錢，通常是迅速取得。"},{"en":"A club may hold a fair to raise cash for new sports equipment.","zh":"學會可能舉辦市集來籌集現金購買新運動器材。"},{"en":"People may sell or mortgage property to raise cash when they want to invest.","zh":"當人們想投資時，可能出售或抵押財產來籌集現金。"},{"en":"In the passage, raising cash allowed ordinary people to join tulip trading.","zh":"在篇章中，籌集現金讓普通人能參與鬱金香交易。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":13},{"front":"begin trading","meaning":"開始交易","examples":[{"en":"Many ordinary people began trading tulips.","zh":"許多普通人開始交易鬱金香。"},{"en":"To begin trading means to start buying and selling goods or assets.","zh":"開始交易，是指開始買賣貨物或資產。"},{"en":"A student may begin trading second-hand books online.","zh":"學生可能開始在網上交易二手書。"},{"en":"When ordinary people begin trading a risky item, a bubble may grow faster.","zh":"當普通人開始交易高風險物品，泡沫可能更快擴大。"},{"en":"The phrase marks the point when tulip speculation spread beyond experts and collectors.","zh":"這個短語標示鬱金香投機擴散到專家和收藏家之外的時刻。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":13},{"front":"change hands","meaning":"易手","examples":[{"en":"A farmhouse changed hands for three rare bulbs.","zh":"一座農舍以三個稀有球莖作價易手。"},{"en":"To change hands means to pass from one owner to another.","zh":"易手是指從一個物主轉到另一個物主。"},{"en":"A used car changes hands when the seller transfers it to the buyer.","zh":"當賣家把二手車轉讓給買家時，二手車就易手。"},{"en":"If a farmhouse changes hands for bulbs, the bulbs are being treated like valuable property.","zh":"如果農舍以球莖作價易手，這些球莖就被當作有價財產。"},{"en":"The phrase highlights how tulips became exchange objects in major deals.","zh":"這個短語突顯鬱金香如何成為重大交易中的交換物。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":13},{"front":"sell off","meaning":"出售；拋售","examples":[{"en":"Even poor-quality bulbs could be sold off for hundreds of guilders.","zh":"即使劣質球莖也可以以數百荷蘭盾出售。"},{"en":"To sell off something means to sell it, often quickly or in large amounts.","zh":"出售或拋售某物，是指把它賣掉，通常較快或大量出售。"},{"en":"A shop may sell off old stock before moving to a new location.","zh":"商店搬到新地點前可能出售舊庫存。"},{"en":"When even weak goods can be sold off for high prices, the market may be overheated.","zh":"當即使質素差的貨品也能高價出售，市場可能已經過熱。"},{"en":"The phrase suggests that buyers were eager enough to take almost anything.","zh":"這個短語暗示買家非常渴望，幾乎甚麼都願意買。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":13},{"front":"be considered garbage","meaning":"被視為垃圾","examples":[{"en":"Some bulbs had recently been considered garbage.","zh":"有些球莖不久前還被視為垃圾。"},{"en":"To be considered garbage means to be regarded as worthless or useless.","zh":"被視為垃圾，是指被認為沒有價值或沒有用。"},{"en":"An old broken chair may be considered garbage until someone repairs it.","zh":"一張破舊椅子可能被視為垃圾，直到有人修好它。"},{"en":"If something once considered garbage suddenly sells for a high price, market judgement has changed sharply.","zh":"如果曾被視為垃圾的東西突然高價出售，市場判斷已急劇改變。"},{"en":"This phrase shows how irrational tulip prices had become.","zh":"這個短語顯示鬱金香價格已變得多麼不理性。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":13},{"front":"futures market","meaning":"期貨市場","examples":[{"en":"A futures market for tulip bulbs existed.","zh":"曾存在鬱金香球莖期貨市場。"},{"en":"A futures market is a market where people agree now to buy or sell something later at a set price.","zh":"期貨市場是人們現在約定將來以固定價格買賣某物的市場。"},{"en":"Farmers may use a futures market to lock in prices before harvest.","zh":"農民可能利用期貨市場在收成前鎖定價格。"},{"en":"A futures market can increase speculation because people trade promises, not only goods in hand.","zh":"期貨市場可以增加投機，因為人們交易的是承諾，而不只是手上貨物。"},{"en":"Tulip trading became more complex when bulbs were bought and sold for future delivery.","zh":"當球莖被買賣作未來交付時，鬱金香交易變得更複雜。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":13},{"front":"conduct business","meaning":"做生意；進行交易","examples":[{"en":"Tulip traders conducted their business in Dutch taverns.","zh":"鬱金香交易商在荷蘭酒館進行交易。"},{"en":"To conduct business means to carry out buying, selling, negotiation or other commercial activity.","zh":"做生意或進行交易，是指進行買賣、談判或其他商業活動。"},{"en":"Small companies may conduct business online instead of renting an office.","zh":"小公司可能在網上做生意，而不是租辦公室。"},{"en":"Where people conduct business can affect trust, rules and speed of deals.","zh":"人們在哪裡做生意，會影響信任、規則和交易速度。"},{"en":"In the passage, taverns became informal places for tulip trading.","zh":"在篇章中，酒館成為鬱金香交易的非正式場所。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":14},{"front":"Dutch taverns","meaning":"荷蘭酒館","examples":[{"en":"Tulip traders met in Dutch taverns.","zh":"鬱金香交易商在荷蘭酒館見面。"},{"en":"Dutch taverns were public drinking places in Holland where people could meet and talk.","zh":"荷蘭酒館是荷蘭供人飲酒、見面和交談的公共場所。"},{"en":"Traders may choose taverns because they are social, informal and easy to access.","zh":"交易商可能選擇酒館，因為那裡社交性強、非正式又容易到達。"},{"en":"Business done in taverns may be less formal than business on an official exchange.","zh":"在酒館中進行的生意，可能比官方交易所的交易較不正式。"},{"en":"The phrase shows that tulip trading happened outside mainstream finance.","zh":"這個短語顯示鬱金香交易發生在主流金融之外。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":14},{"front":"reach its peak","meaning":"達到頂峰","examples":[{"en":"Tulip mania reached its peak during the winter of 1636–37.","zh":"鬱金香狂熱在 1636 至 1637 年冬季達到頂峰。"},{"en":"To reach its peak means to arrive at the highest or most intense point.","zh":"達到頂峰，是指到達最高或最強烈的點。"},{"en":"Tourist numbers may reach their peak during summer holidays.","zh":"遊客數量可能在暑假期間達到頂峰。"},{"en":"A bubble often reaches its peak just before confidence breaks.","zh":"泡沫通常在信心破裂前達到頂峰。"},{"en":"The phrase signals the most extreme stage of tulip mania.","zh":"這個短語標示鬱金香狂熱最極端的階段。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":14},{"front":"change hands ten times in a day","meaning":"一天內易手十次","examples":[{"en":"Some bulbs changed hands ten times in a day.","zh":"有些球莖一天內易手十次。"},{"en":"To change hands ten times in a day means to be bought and sold by different people ten times within one day.","zh":"一天內易手十次，是指在一天內由不同人買賣十次。"},{"en":"A concert ticket may change hands several times if demand is very high.","zh":"如果需求很高，演唱會門票可能數次易手。"},{"en":"When an asset changes hands many times in one day, people are likely speculating rather than using it.","zh":"當資產一天內多次易手，人們很可能是在投機，而不是使用它。"},{"en":"This phrase shows how feverish tulip trading had become.","zh":"這個短語顯示鬱金香交易已變得多麼狂熱。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":14},{"front":"the zenith came","meaning":"高峰出現在","examples":[{"en":"The zenith came early that winter.","zh":"高峰出現在那年冬季初。"},{"en":"The zenith came means the highest point or climax arrived.","zh":"高峰出現，是指最高點或高潮到來。"},{"en":"The zenith of a singer’s career came when she won an international award.","zh":"一名歌手事業的高峰出現在她贏得國際獎項時。"},{"en":"A market’s zenith often arrives when optimism is strongest.","zh":"市場高峰通常出現在樂觀情緒最強時。"},{"en":"In the passage, the zenith came just before the tulip market collapsed.","zh":"在篇章中，高峰出現在鬱金香市場崩潰之前。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":14},{"front":"auction","meaning":"拍賣","examples":[{"en":"A rare bulb was sold at an auction.","zh":"一個稀有球莖在拍賣中售出。"},{"en":"An auction is a public sale where people bid, and the highest bidder usually buys the item.","zh":"拍賣是公開銷售，人們出價，通常由最高出價者買下物品。"},{"en":"A charity auction may sell paintings to raise money for a school.","zh":"慈善拍賣可能出售畫作為學校籌款。"},{"en":"Auctions can push prices high when several buyers compete for the same rare item.","zh":"當幾名買家競爭同一件稀有物品時，拍賣可以推高價格。"},{"en":"The tulip auction showed how much buyers were willing to pay.","zh":"鬱金香拍賣顯示買家願意支付多少。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":14},{"front":"benefit seven orphans","meaning":"使七名孤兒受益","examples":[{"en":"The auction was held to benefit seven orphans.","zh":"這場拍賣是為了使七名孤兒受益。"},{"en":"To benefit seven orphans means to help seven children who had lost their parents.","zh":"使七名孤兒受益，是指幫助七名失去父母的兒童。"},{"en":"A fundraiser may be held to benefit children whose homes were damaged in a fire.","zh":"籌款活動可能為因火災失去住所的孩子帶來幫助。"},{"en":"If an auction benefits orphans, the money raised is meant to support them.","zh":"如果拍賣使孤兒受益，籌得款項就是用來支持他們。"},{"en":"This phrase explains the charitable purpose behind the sale.","zh":"這個短語解釋銷售背後的慈善目的。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":14},{"front":"only asset","meaning":"唯一資產","examples":[{"en":"The orphans’ only asset was 70 fine tulips.","zh":"這些孤兒的唯一資產是 70 朵優質鬱金香。"},{"en":"An only asset is the single valuable thing a person or group owns.","zh":"唯一資產是某人或群體擁有的唯一有價值物品。"},{"en":"A family’s only asset may be a small flat if they have no savings.","zh":"如果家庭沒有儲蓄，小單位可能是他們的唯一資產。"},{"en":"If someone’s only asset falls in value, their financial security can disappear.","zh":"如果某人的唯一資產貶值，他們的財務安全可能消失。"},{"en":"The orphans depended on the value of their tulips because they had no other asset.","zh":"這些孤兒依賴鬱金香的價值，因為他們沒有其他資產。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":14},{"front":"be about to split in two","meaning":"即將分裂成兩個","examples":[{"en":"The rare bulb was about to split in two.","zh":"這個稀有球莖即將分裂成兩個。"},{"en":"To be about to split in two means it was going to divide into two parts very soon.","zh":"即將分裂成兩個，是指很快會分成兩部分。"},{"en":"A ripe seed pod may be about to split in two when it dries.","zh":"成熟的種莢乾燥時可能即將分裂成兩個。"},{"en":"If a tulip bulb is about to split in two, it may produce more bulbs and become more valuable.","zh":"如果鬱金香球莖即將分裂成兩個，它可能產生更多球莖並變得更有價值。"},{"en":"This phrase describes a near-future biological change in the bulb.","zh":"這個短語描述球莖即將發生的生物變化。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":14},{"front":"all-time record","meaning":"歷史最高紀錄","examples":[{"en":"The bulb sold for 5,200 guilders, the all-time record.","zh":"這個球莖以 5,200 荷蘭盾售出，創下歷史最高紀錄。"},{"en":"An all-time record is the highest or best figure ever reached up to that point.","zh":"歷史最高紀錄是截至該時刻曾達到的最高或最佳數字。"},{"en":"A school may set an all-time record for the number of students admitted to university.","zh":"學校可能創下學生升讀大學人數的歷史最高紀錄。"},{"en":"When a price reaches an all-time record, excitement or competition is usually very strong.","zh":"當價格達到歷史最高紀錄，興奮或競爭通常非常強烈。"},{"en":"The tulip’s all-time record price marked the extreme height of the mania.","zh":"鬱金香的歷史最高紀錄價格標誌着狂熱的極端高峰。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":14},{"front":"all told","meaning":"總共","examples":[{"en":"All told, the flowers brought in nearly 53,000 guilders.","zh":"總共，這些花帶來近 53,000 荷蘭盾。"},{"en":"All told means when everything is counted together.","zh":"總共，是指把所有東西加起來計算。"},{"en":"All told, the school fair raised 20,000 dollars after food, games and donations were counted.","zh":"總共，學校嘉年華在計算食物、遊戲和捐款後籌得 20,000 元。"},{"en":"This phrase is useful when giving a final total after several parts.","zh":"這個短語適合在幾個部分後給出最終總額。"},{"en":"In the auction, all told shows the combined value of all the flowers.","zh":"在拍賣中，總共顯示所有花的合計價值。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":14},{"front":"bring in","meaning":"帶來；賺得","examples":[{"en":"The flowers brought in nearly 53,000 guilders.","zh":"這些花帶來近 53,000 荷蘭盾。"},{"en":"To bring in money means to earn or raise that amount.","zh":"帶來金錢，是指賺得或籌得該金額。"},{"en":"A weekend market can bring in extra income for a small bakery.","zh":"週末市集可以為小麵包店帶來額外收入。"},{"en":"When an auction brings in a large sum, the items were highly valued by buyers.","zh":"當拍賣帶來大筆金額，表示買家高度重視物品。"},{"en":"The tulips brought in so much money that the auction became a symbol of the mania.","zh":"鬱金香帶來如此多金錢，使這場拍賣成為狂熱的象徵。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":15},{"front":"crash utterly","meaning":"徹底崩潰","examples":[{"en":"The tulip market crashed utterly.","zh":"鬱金香市場徹底崩潰。"},{"en":"To crash utterly means to collapse completely and severely.","zh":"徹底崩潰，是指完全而嚴重地倒塌或失敗。"},{"en":"A small business may crash utterly if sales stop and debts remain high.","zh":"如果銷售停止而債務仍高，小企業可能徹底崩潰。"},{"en":"When confidence disappears, a speculative market can crash utterly within days.","zh":"當信心消失，投機市場可以在數日內徹底崩潰。"},{"en":"The phrase emphasises total failure, not a small decline.","zh":"這個短語強調完全失敗，而不是小幅下降。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":15},{"front":"crash spectacularly","meaning":"驚人地崩潰","examples":[{"en":"The tulip market crashed spectacularly.","zh":"鬱金香市場驚人地崩潰。"},{"en":"To crash spectacularly means to collapse in a dramatic and highly noticeable way.","zh":"驚人地崩潰，是指以戲劇性而非常明顯的方式倒塌。"},{"en":"A popular app can crash spectacularly if users leave after a major security problem.","zh":"如果重大保安問題後用戶離開，熱門應用程式可能驚人地崩潰。"},{"en":"Markets that rise too fast may crash spectacularly when buyers lose confidence.","zh":"上升太快的市場在買家失去信心時可能驚人地崩潰。"},{"en":"The word spectacularly suggests the collapse was shocking and memorable.","zh":"「驚人地」暗示崩潰令人震驚而難忘。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":15},{"front":"routine bulb auction","meaning":"例行球莖拍賣","examples":[{"en":"The crash began at a routine bulb auction.","zh":"崩潰始於一場例行球莖拍賣。"},{"en":"A routine bulb auction is an ordinary, regular sale of bulbs by bidding.","zh":"例行球莖拍賣是以競價出售球莖的普通定期銷售。"},{"en":"A routine meeting can become important if something unexpected happens there.","zh":"如果有意外事情發生，例行會議也可以變得重要。"},{"en":"A market crash beginning at a routine auction shows how quickly confidence can break.","zh":"市場崩潰始於例行拍賣，顯示信心可以多快破裂。"},{"en":"This phrase contrasts an ordinary event with a dramatic result.","zh":"這個短語把普通事件與戲劇性結果作對比。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":15},{"front":"the greater fool","meaning":"更大的傻瓜；接貨的下一個買家","examples":[{"en":"The greater fool refused to show up and pay.","zh":"更大的傻瓜拒絕出現並付款。"},{"en":"The greater fool is the next buyer expected to pay an even higher price for an overpriced asset.","zh":"更大的傻瓜，是指預期會以更高價格接手高估資產的下一個買家。"},{"en":"In a bubble, buyers may rely on a greater fool to buy from them later.","zh":"在泡沫中，買家可能依賴更大的傻瓜之後向他們購買。"},{"en":"If the greater fool does not appear, the last buyer may be left with a worthless asset.","zh":"如果更大的傻瓜沒有出現，最後一位買家可能被困在無價值資產中。"},{"en":"The phrase explains why speculative markets can collapse suddenly.","zh":"這個短語解釋投機市場為何會突然崩潰。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":15},{"front":"refuse to show up","meaning":"拒絕出現","examples":[{"en":"For the first time, the buyer refused to show up.","zh":"第一次，買家拒絕出現。"},{"en":"To refuse to show up means to deliberately not appear at the expected place or event.","zh":"拒絕出現，是指故意不去預期的地方或事件。"},{"en":"A tenant may refuse to show up for a meeting if they fear being pressured.","zh":"如果租戶害怕被施壓，可能拒絕出席會議。"},{"en":"If buyers refuse to show up, sellers may realise demand has disappeared.","zh":"如果買家拒絕出現，賣家可能意識到需求已消失。"},{"en":"In the passage, one buyer’s refusal helped trigger panic.","zh":"在篇章中，一名買家的拒絕幫助觸發恐慌。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":15},{"front":"panic spread across","meaning":"恐慌蔓延至……","examples":[{"en":"The panic spread across the country within days.","zh":"恐慌在數日內蔓延至全國。"},{"en":"Panic spreads across a place when fear moves quickly from one area or group to another.","zh":"恐慌蔓延至某地，是指恐懼迅速從一個地區或群體傳到另一個。"},{"en":"Rumours can cause panic to spread across a school before teachers explain the truth.","zh":"在老師解釋真相前，謠言可能令恐慌蔓延至整間學校。"},{"en":"In financial markets, panic can spread across a country when buyers stop trusting prices.","zh":"在金融市場中，當買家不再信任價格，恐慌可以蔓延至全國。"},{"en":"This phrase shows how quickly the tulip collapse affected many people.","zh":"這個短語顯示鬱金香崩潰多快影響許多人。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":15},{"front":"prop up demand","meaning":"支撐需求","examples":[{"en":"Traders tried to prop up demand.","zh":"交易商試圖支撐需求。"},{"en":"To prop up demand means to support or maintain people’s willingness to buy.","zh":"支撐需求，是指支持或維持人們的購買意欲。"},{"en":"A shop may cut prices to prop up demand during a quiet month.","zh":"商店可能在淡季減價來支撐需求。"},{"en":"If confidence is gone, efforts to prop up demand may fail.","zh":"如果信心已經消失，支撐需求的努力可能失敗。"},{"en":"Tulip traders tried to prop up demand because falling demand threatened the whole market.","zh":"鬱金香交易商試圖支撐需求，因為需求下跌威脅整個市場。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":15},{"front":"the market evaporated","meaning":"市場突然消失","examples":[{"en":"The market for tulips evaporated.","zh":"鬱金香市場突然消失。"},{"en":"When a market evaporates, buyers suddenly disappear and trading almost stops.","zh":"當市場突然消失，買家會突然不見，交易幾乎停止。"},{"en":"A market for a fashion item can evaporate when people decide it is no longer popular.","zh":"當人們認為某時尚物品不再流行，它的市場可能突然消失。"},{"en":"If demand evaporates, sellers may be unable to find anyone willing to pay.","zh":"如果需求消失，賣家可能找不到願意付款的人。"},{"en":"The phrase suggests demand vanished quickly, almost like water turning into vapour.","zh":"這個短語暗示需求迅速消失，就像水變成蒸氣一樣。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":15},{"front":"fetch one-hundredth that amount","meaning":"只能賣得該金額的百分之一","examples":[{"en":"Flowers that once cost 5,000 guilders fetched one-hundredth that amount.","zh":"曾價值 5,000 荷蘭盾的花只能賣得該金額的百分之一。"},{"en":"To fetch one-hundredth that amount means to sell for only one percent of the earlier price.","zh":"只能賣得該金額的百分之一，是指只以早前價格的一百分之一出售。"},{"en":"A toy once sold for 100 dollars may fetch one-hundredth that amount if nobody wants it anymore.","zh":"如果沒有人再想要，曾售 100 元的玩具可能只能賣得該金額的百分之一。"},{"en":"When an asset fetches one-hundredth of its old price, the collapse has been severe.","zh":"當資產只能賣得舊價的一百分之一，崩潰就非常嚴重。"},{"en":"This phrase shows the scale of the tulip price crash.","zh":"這個短語顯示鬱金香價格崩潰的規模。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":15},{"front":"not without flaws","meaning":"並非沒有缺點","examples":[{"en":"Tulipomania is not without flaws.","zh":"《鬱金香狂熱》並非沒有缺點。"},{"en":"Not without flaws means not perfect and containing some weaknesses.","zh":"並非沒有缺點，是指不是完美，並有一些弱點。"},{"en":"A useful textbook may still be not without flaws if some examples are outdated.","zh":"一本有用的教科書如果有些例子過時，仍可能並非沒有缺點。"},{"en":"This phrase gives criticism politely without rejecting the whole work.","zh":"這個短語能禮貌地提出批評，而不是否定整部作品。"},{"en":"The reviewer praises the book but admits it has problems.","zh":"評論者稱讚這本書，但承認它有問題。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":15},{"front":"dwell too long on","meaning":"過分着墨於……","examples":[{"en":"Dash dwells too long on the tulip’s migration from Asia to Holland.","zh":"Dash 過分着墨於鬱金香從亞洲遷移到荷蘭的過程。"},{"en":"To dwell too long on something means to spend too much time discussing it.","zh":"過分着墨於某事，是指花太多時間討論它。"},{"en":"A speaker may dwell too long on background details and lose the audience’s attention.","zh":"演講者可能過分着墨於背景細節，令觀眾失去注意力。"},{"en":"If a writer dwells too long on minor history, the main argument may slow down.","zh":"如果作者過分着墨於次要歷史，主要論點可能變慢。"},{"en":"The phrase gives a criticism about balance and pacing.","zh":"這個短語是關於平衡和節奏的批評。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":16},{"front":"migration from…to…","meaning":"從……遷移至……","examples":[{"en":"The book describes the tulip’s migration from Asia to Holland.","zh":"這本書描述鬱金香從亞洲遷移至荷蘭。"},{"en":"Migration from one place to another means movement or spread from the first place to the second.","zh":"從一地遷移至另一地，是指從第一個地方移動或傳播到第二個地方。"},{"en":"The migration from villages to cities can change jobs, housing and family life.","zh":"從鄉村遷移至城市可以改變工作、住房和家庭生活。"},{"en":"A plant’s migration from one region to another may happen through trade or travel.","zh":"植物從一個地區遷移至另一個地區，可能透過貿易或旅行發生。"},{"en":"This phrase traces the tulip’s geographical journey.","zh":"這個短語追溯鬱金香的地理旅程。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":16},{"front":"do a service","meaning":"作出有益貢獻","examples":[{"en":"Dash does a service with his account of financial folly.","zh":"Dash 以其對金融愚行的記述作出有益貢獻。"},{"en":"To do a service means to help others by providing something useful.","zh":"作出有益貢獻，是指透過提供有用東西來幫助他人。"},{"en":"A journalist does a service when she explains a complex issue clearly.","zh":"記者清楚解釋複雜議題時，就是作出有益貢獻。"},{"en":"A book can do a service by correcting a careless public misunderstanding.","zh":"一本書可以透過糾正常見誤解作出有益貢獻。"},{"en":"The phrase means Dash’s account is valuable to readers.","zh":"這個短語意思是 Dash 的記述對讀者有價值。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":16},{"front":"illuminating account","meaning":"具啟發性的記述","examples":[{"en":"The book is an illuminating account of tulip mania.","zh":"這本書是對鬱金香狂熱的具啟發性記述。"},{"en":"An illuminating account is an explanation that helps people understand something more clearly.","zh":"具啟發性的記述，是幫助人們更清楚理解某事的解釋。"},{"en":"A teacher’s story about a factory can be an illuminating account of labour conditions.","zh":"老師關於工廠的故事，可以成為勞工狀況的具啟發性記述。"},{"en":"An illuminating account does not just list facts; it makes their meaning clear.","zh":"具啟發性的記述不只是列出事實，而是清楚說明其意義。"},{"en":"The phrase praises the book for making tulip mania easier to understand.","zh":"這個短語稱讚這本書令鬱金香狂熱更容易理解。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":16},{"front":"accessible account","meaning":"容易理解的記述","examples":[{"en":"The book gives an accessible account of the events.","zh":"這本書對事件作出容易理解的記述。"},{"en":"An accessible account is an explanation that ordinary readers can understand easily.","zh":"容易理解的記述，是普通讀者也能輕易明白的解釋。"},{"en":"A doctor may give an accessible account of a disease without using too much medical language.","zh":"醫生可能不用太多醫學用語，對疾病作出容易理解的說明。"},{"en":"Accessible accounts are useful when the topic is historical, technical or unfamiliar.","zh":"當主題是歷史、技術或陌生內容時，容易理解的記述很有用。"},{"en":"The phrase suggests Dash explains tulip mania clearly for non-specialists.","zh":"這個短語暗示 Dash 為非專家清楚解釋鬱金香狂熱。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":16},{"front":"financial folly","meaning":"金融愚行","examples":[{"en":"The tulip craze was an example of incredible financial folly.","zh":"鬱金香狂熱是令人難以置信的金融愚行例子。"},{"en":"Financial folly means foolish behaviour involving money.","zh":"金融愚行是涉及金錢的愚蠢行為。"},{"en":"Borrowing heavily to buy something only because its price is rising can be financial folly.","zh":"只因某物價格正在上升就大量借錢購買，可能是金融愚行。"},{"en":"Financial folly often happens when greed or fear overpowers careful judgement.","zh":"當貪婪或恐懼壓倒謹慎判斷時，金融愚行常會發生。"},{"en":"Tulip mania is called financial folly because people paid irrational prices for bulbs.","zh":"鬱金香狂熱被稱為金融愚行，因為人們為球莖支付不理性的價格。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":16},{"front":"differ in one crucial aspect from","meaning":"在一個關鍵方面與……不同","examples":[{"en":"Tulip mania differed in one crucial aspect from the dot-com craze.","zh":"鬱金香狂熱在一個關鍵方面與網科股狂熱不同。"},{"en":"To differ in one crucial aspect from something means to be unlike it in one very important way.","zh":"在一個關鍵方面與某事不同，是指在一個非常重要的方面不一樣。"},{"en":"Two schools may look similar but differ in one crucial aspect: how much support they give weak students.","zh":"兩間學校可能看似相似，但在一個關鍵方面不同：它們給弱勢學生多少支援。"},{"en":"A comparison becomes clearer when we identify the crucial aspect that separates two cases.","zh":"當我們找出區分兩個案例的關鍵方面，比較會更清楚。"},{"en":"The passage notes that tulip mania and the dot-com craze were not exactly the same.","zh":"篇章指出鬱金香狂熱和網科股狂熱並非完全相同。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":16},{"front":"dot-com craze","meaning":"網科股狂熱","examples":[{"en":"The passage compares tulip mania with the dot-com craze.","zh":"篇章把鬱金香狂熱與網科股狂熱作比較。"},{"en":"The dot-com craze was a period of intense excitement about internet companies and their shares.","zh":"網科股狂熱是人們對互聯網公司及其股票極度興奮的時期。"},{"en":"During a dot-com craze, investors may buy companies before they make profits.","zh":"在網科股狂熱中，投資者可能在公司盈利前就買入其股票。"},{"en":"A craze can push prices up when stories of future growth become too powerful.","zh":"當未來增長故事變得太強大，狂熱可以推高價格。"},{"en":"The phrase helps connect historical tulip speculation with modern technology speculation.","zh":"這個短語幫助把歷史上的鬱金香投機與現代科技投機連繫起來。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":16},{"front":"grip our attention","meaning":"吸引我們的注意力","examples":[{"en":"The dot-com craze grips our attention today.","zh":"網科股狂熱今天吸引我們的注意力。"},{"en":"To grip our attention means to hold our interest strongly.","zh":"吸引我們的注意力，是指強烈抓住我們的興趣。"},{"en":"A breaking news story can grip our attention for hours.","zh":"突發新聞可以吸引我們的注意力數小時。"},{"en":"Events grip our attention when they feel urgent, risky or close to our own lives.","zh":"當事件感覺緊急、有風險或與自己生活接近時，就會吸引我們的注意力。"},{"en":"The phrase explains why modern readers care about comparing bubbles.","zh":"這個短語解釋為何現代讀者關心泡沫比較。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":16},{"front":"at its height","meaning":"在高峰時","examples":[{"en":"Even at its height, the stock exchange would not touch tulips.","zh":"即使在高峰時，證券交易所也不願碰鬱金香。"},{"en":"At its height means at the most intense or successful point.","zh":"在高峰時，是指在最強烈或最成功的時刻。"},{"en":"At its height, a festival may attract visitors from many countries.","zh":"在高峰時，一個節日可能吸引來自多國的訪客。"},{"en":"Even at its height, a craze may still remain outside official institutions.","zh":"即使在高峰時，某種狂熱仍可能留在官方制度之外。"},{"en":"The phrase shows that tulip mania was extreme but not fully mainstream finance.","zh":"這個短語顯示鬱金香狂熱雖然極端，但並未完全進入主流金融。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":16},{"front":"Amsterdam Stock Exchange","meaning":"阿姆斯特丹證券交易所","examples":[{"en":"The Amsterdam Stock Exchange was well established in 1630.","zh":"阿姆斯特丹證券交易所在 1630 年已穩固建立。"},{"en":"The Amsterdam Stock Exchange was an official market where financial securities were traded.","zh":"阿姆斯特丹證券交易所是一個交易金融證券的官方市場。"},{"en":"A stock exchange gives buyers and sellers a formal place to trade shares or other assets.","zh":"證券交易所為買賣雙方提供交易股票或其他資產的正式場所。"},{"en":"The Amsterdam Stock Exchange’s refusal to handle tulips shows the tulip market stayed separate.","zh":"阿姆斯特丹證券交易所拒絕處理鬱金香，顯示鬱金香市場保持分離。"},{"en":"This phrase identifies the formal financial institution in the passage.","zh":"這個短語指出篇章中的正式金融機構。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":16},{"front":"well-established","meaning":"已穩固建立的","examples":[{"en":"The Amsterdam Stock Exchange was well-established in 1630.","zh":"阿姆斯特丹證券交易所在 1630 年已穩固建立。"},{"en":"Well-established means already existing firmly and widely recognised.","zh":"已穩固建立的，是指已經牢固存在並廣受認可。"},{"en":"A well-established school has a long record and clear routines.","zh":"已穩固建立的學校有長久紀錄和清楚常規。"},{"en":"If an institution is well-established, people usually trust its rules and authority.","zh":"如果機構已穩固建立，人們通常信任其規則和權威。"},{"en":"The phrase shows that formal finance already existed, but tulips stayed outside it.","zh":"這個短語顯示正式金融已存在，但鬱金香仍在其外。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":17},{"front":"would not touch","meaning":"不願碰；不涉足","examples":[{"en":"The stock exchange would not touch tulips.","zh":"證券交易所不願碰鬱金香。"},{"en":"Would not touch something means refused to become involved with it.","zh":"不願碰某事，是指拒絕參與其中。"},{"en":"A careful bank may not touch a risky loan application.","zh":"謹慎的銀行可能不願碰高風險貸款申請。"},{"en":"If official institutions will not touch a product, they may see it as too risky or unsuitable.","zh":"如果官方機構不願碰某產品，它們可能認為它風險太高或不合適。"},{"en":"The phrase shows that tulip speculation remained outside the formal exchange.","zh":"這個短語顯示鬱金香投機仍留在正式交易所之外。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":17},{"front":"speculation in","meaning":"對……的投機","examples":[{"en":"The speculation in tulip bulbs stayed outside mainstream finance.","zh":"對鬱金香球莖的投機留在主流金融之外。"},{"en":"Speculation in something means buying or selling it mainly to profit from price changes.","zh":"對某物的投機，是指主要為從價格變動中獲利而買賣它。"},{"en":"Speculation in property can make flats unaffordable for ordinary families.","zh":"對物業的投機可以令普通家庭難以負擔單位。"},{"en":"Heavy speculation in a product can push its price far above practical value.","zh":"對某產品的大量投機可以把價格推到遠高於實用價值。"},{"en":"The phrase identifies tulip trading as profit-seeking rather than ordinary gardening.","zh":"這個短語指出鬱金香交易是追求利潤，而不是普通園藝。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":17},{"front":"exist at the margins of","meaning":"存在於……的邊緣","examples":[{"en":"Tulip speculation existed at the margins of Dutch economic life.","zh":"鬱金香投機存在於荷蘭經濟生活的邊緣。"},{"en":"To exist at the margins of something means to remain at the edge, not in the centre.","zh":"存在於某事的邊緣，是指停留在外圍，而不是中心。"},{"en":"A small informal market may exist at the margins of a city’s main economy.","zh":"小型非正式市場可能存在於城市主要經濟的邊緣。"},{"en":"Activities at the margins may still be risky even if they do not control the whole system.","zh":"邊緣活動即使不控制整個系統，仍可能有風險。"},{"en":"This phrase explains why tulip mania caused limited damage to the wider economy.","zh":"這個短語解釋為何鬱金香狂熱對更廣泛經濟造成的損害有限。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":17},{"front":"economic life","meaning":"經濟生活","examples":[{"en":"Tulip speculation was at the margins of Dutch economic life.","zh":"鬱金香投機位於荷蘭經濟生活的邊緣。"},{"en":"Economic life means the buying, selling, working and earning activities of a society.","zh":"經濟生活是指一個社會的買賣、工作和賺取收入活動。"},{"en":"Shops, wages, banks and trade are all parts of economic life.","zh":"商店、工資、銀行和貿易都是經濟生活的一部分。"},{"en":"If a risky activity is central to economic life, its collapse can hurt many people.","zh":"如果高風險活動處於經濟生活的核心，其崩潰可以傷害許多人。"},{"en":"Tulip trading affected some people but remained outside the core of Dutch economic life.","zh":"鬱金香交易影響了一些人，但仍在荷蘭經濟生活核心之外。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":17},{"front":"broker a compromise","meaning":"促成妥協","examples":[{"en":"A compromise was brokered after the market crashed.","zh":"市場崩潰後，有人促成妥協。"},{"en":"To broker a compromise means to help different sides reach an agreement.","zh":"促成妥協，是指幫助不同方面達成協議。"},{"en":"A teacher may broker a compromise between two students arguing over group work.","zh":"老師可能促成兩名因小組工作爭吵的學生妥協。"},{"en":"After a financial crash, a compromise can reduce conflict over unpaid debts.","zh":"金融崩潰後，妥協可以減少未償債務引起的衝突。"},{"en":"The phrase suggests someone helped traders settle the problem.","zh":"這個短語暗示有人幫助交易者解決問題。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":17},{"front":"settle debts","meaning":"清償債務","examples":[{"en":"Most traders were allowed to settle their debts.","zh":"大多數交易者被允許清償債務。"},{"en":"To settle debts means to pay or resolve money owed.","zh":"清償債務，是指支付或解決所欠金錢。"},{"en":"A family may sell unused furniture to settle debts after losing income.","zh":"家庭失去收入後，可能出售不用的家具來清償債務。"},{"en":"Settling debts can end legal or personal conflict between borrower and lender.","zh":"清償債務可以結束借款人與貸款人之間的法律或個人衝突。"},{"en":"In the tulip crash, traders settled debts for less than the full amount.","zh":"在鬱金香崩潰中，交易者以低於全額的金額清償債務。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":17},{"front":"a fraction of","meaning":"……的一小部分","examples":[{"en":"Traders settled their debts for a fraction of their liability.","zh":"交易者以其債務的一小部分清償債務。"},{"en":"A fraction of something means a small part of the whole amount.","zh":"某物的一小部分，是指整體金額中的小部分。"},{"en":"A second-hand phone may cost only a fraction of the price of a new one.","zh":"二手手機可能只花新手機價格的一小部分。"},{"en":"Paying only a fraction of a debt reduces the burden on the debtor.","zh":"只支付債務的一小部分可以減輕債務人的負擔。"},{"en":"The phrase shows that traders did not pay everything they legally owed.","zh":"這個短語顯示交易者並沒有支付所有法律上所欠的金額。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":17},{"front":"liability","meaning":"債務；法律責任","examples":[{"en":"Traders paid only a fraction of their liability.","zh":"交易者只支付其債務的一小部分。"},{"en":"Liability means legal or financial responsibility for a debt, loss or obligation.","zh":"債務或法律責任，是指對債務、損失或義務的法律或財務責任。"},{"en":"A company has liability if its unsafe product harms customers.","zh":"如果公司的不安全產品傷害顧客，公司就有法律責任。"},{"en":"If traders cannot meet their liability, they may need a settlement or compromise.","zh":"如果交易者無法履行債務，他們可能需要和解或妥協。"},{"en":"The word shows that tulip traders had obligations after prices collapsed.","zh":"這個詞顯示鬱金香交易者在價格崩潰後仍有義務。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":17},{"front":"overall fallout","meaning":"整體後果","examples":[{"en":"The overall fallout on the Dutch economy was negligible.","zh":"對荷蘭經濟的整體後果微不足道。"},{"en":"Overall fallout means the total negative effect after a bad event.","zh":"整體後果是指壞事件之後的總體負面影響。"},{"en":"The overall fallout from a school computer failure may include delays and lost files.","zh":"學校電腦故障的整體後果可能包括延誤和文件遺失。"},{"en":"If the overall fallout is small, the damage does not spread widely.","zh":"如果整體後果很小，損害就沒有廣泛擴散。"},{"en":"The phrase explains the broader consequences of the tulip crash.","zh":"這個短語解釋鬱金香崩潰的更廣泛影響。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":17},{"front":"negligible","meaning":"微不足道","examples":[{"en":"The fallout on the Dutch economy was negligible.","zh":"對荷蘭經濟的後果微不足道。"},{"en":"Negligible means so small that it is not very important.","zh":"微不足道，是指小到不太重要。"},{"en":"A spelling mistake in a casual message may have negligible impact.","zh":"隨意訊息中的拼寫錯誤可能影響微不足道。"},{"en":"If economic damage is negligible, most businesses and workers continue normally.","zh":"如果經濟損害微不足道，大多數企業和工人會如常繼續。"},{"en":"The passage says the tulip crash was dramatic but had negligible wider economic effect.","zh":"篇章說鬱金香崩潰雖然戲劇性，但對更廣泛經濟的影響微不足道。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":17},{"front":"Wall Street’s current obsession","meaning":"華爾街當前的狂熱","examples":[{"en":"The writer compares tulip mania with Wall Street’s current obsession.","zh":"作者把鬱金香狂熱與華爾街當前的狂熱作比較。"},{"en":"Wall Street’s current obsession means the investment idea or market trend currently exciting American finance.","zh":"華爾街當前的狂熱，是指目前令美國金融界興奮的投資想法或市場趨勢。"},{"en":"A market may become obsessed with a new technology when investors expect huge profits.","zh":"當投資者預期巨大利潤時，市場可能對新科技產生狂熱。"},{"en":"An obsession can make investors focus on excitement rather than value.","zh":"狂熱可以令投資者關注興奮而不是價值。"},{"en":"The phrase connects old tulip speculation with modern financial enthusiasm.","zh":"這個短語把舊時鬱金香投機與現代金融熱情連繫起來。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":18},{"front":"run its course","meaning":"發展到自然結束","examples":[{"en":"The writer asks what will happen when the current obsession runs its course.","zh":"作者問當前狂熱發展到自然結束時會發生甚麼。"},{"en":"To run its course means to continue until it naturally ends.","zh":"發展到自然結束，是指持續到自然完結。"},{"en":"A mild cold usually runs its course after a few days of rest.","zh":"輕微感冒通常休息幾天後會自然結束。"},{"en":"When a market craze runs its course, buyers may lose interest and prices may fall.","zh":"當市場狂熱發展到自然結束，買家可能失去興趣，價格可能下跌。"},{"en":"The phrase asks what happens after excitement has used up its energy.","zh":"這個短語詢問興奮消耗完能量後會發生甚麼。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":18},{"front":"contain the following information","meaning":"包含以下資料","examples":[{"en":"Students identify which paragraph contains the following information.","zh":"學生識別哪一段包含以下資料。"},{"en":"To contain the following information means to include the details listed after the instruction.","zh":"包含以下資料，是指包括指示後列出的細節。"},{"en":"In reading tests, students scan paragraphs to find where specific information is contained.","zh":"在閱讀測驗中，學生掃讀段落以找出具體資料在哪裡出現。"},{"en":"If a paragraph contains the information, students should match it with the correct question.","zh":"如果某段包含該資料，學生應把它與正確題目配對。"},{"en":"This phrase is common in IELTS-style paragraph matching tasks.","zh":"這個短語常見於 IELTS 式段落配對題。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":18},{"front":"a difference between","meaning":"……之間的分別","examples":[{"en":"The question asks for a difference between two financial bubbles.","zh":"題目要求指出兩個金融泡沫之間的分別。"},{"en":"A difference between two things is a way in which they are not the same.","zh":"兩件事之間的分別，是指它們不相同的一方面。"},{"en":"A teacher may ask for a difference between formal and informal writing.","zh":"老師可能要求指出正式和非正式寫作之間的分別。"},{"en":"Finding a difference between two examples helps students avoid treating them as identical.","zh":"找出兩個例子之間的分別，可以幫助學生避免把它們視為完全一樣。"},{"en":"In the passage, one key difference concerns how close each bubble was to mainstream finance.","zh":"在篇章中，一個關鍵分別涉及每個泡沫與主流金融的距離。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":18},{"front":"effects of the collapse","meaning":"崩潰的影響","examples":[{"en":"The question refers to the effects of the tulip bubble’s collapse.","zh":"題目指鬱金香泡沫崩潰的影響。"},{"en":"Effects of the collapse are the results or consequences after the market failed.","zh":"崩潰的影響，是指市場失敗後的結果或後果。"},{"en":"The effects of a bridge collapse may include injuries, traffic delays and repair costs.","zh":"橋樑倒塌的影響可能包括受傷、交通延誤和維修費。"},{"en":"Studying the effects of the collapse helps readers judge how serious the crash was.","zh":"研究崩潰的影響幫助讀者判斷崩盤有多嚴重。"},{"en":"In the passage, the wider economic effects were described as small.","zh":"在篇章中，更廣泛的經濟影響被描述為很小。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":18},{"front":"high-tech share bubble","meaning":"高科技股票泡沫","examples":[{"en":"The passage compares the tulip bubble with a high-tech share bubble.","zh":"篇章把鬱金香泡沫與高科技股票泡沫作比較。"},{"en":"A high-tech share bubble happens when technology company shares rise far beyond realistic value.","zh":"高科技股票泡沫，是指科技公司股票價格升到遠高於現實價值。"},{"en":"A high-tech share bubble can form when investors believe every new company will become successful.","zh":"當投資者相信每間新公司都會成功，高科技股票泡沫可能形成。"},{"en":"When such a bubble bursts, share prices can fall sharply.","zh":"當這種泡沫爆破，股票價格可能急劇下跌。"},{"en":"The phrase links modern technology speculation with historical tulip speculation.","zh":"這個短語把現代科技投機與歷史鬱金香投機連繫起來。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":18},{"front":"spread of tulips","meaning":"鬱金香的傳播","examples":[{"en":"The question asks about the spread of tulips before the seventeenth century.","zh":"題目問 17 世紀以前鬱金香的傳播。"},{"en":"The spread of tulips means the movement or introduction of tulips into more places.","zh":"鬱金香的傳播，是指鬱金香移動或被引入更多地方。"},{"en":"The spread of a crop can happen through trade, migration or gardening fashion.","zh":"一種作物的傳播可以透過貿易、遷移或園藝潮流發生。"},{"en":"Understanding the spread of tulips helps explain how Holland later encountered them.","zh":"理解鬱金香的傳播有助解釋荷蘭後來如何接觸它們。"},{"en":"This phrase focuses on movement before the Dutch mania began.","zh":"這個短語聚焦荷蘭狂熱開始前的移動。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":18},{"front":"before the seventeenth century","meaning":"17世紀以前","examples":[{"en":"Tulips spread before the seventeenth century.","zh":"鬱金香在 17 世紀以前已傳播。"},{"en":"Before the seventeenth century means earlier than the 1600s.","zh":"17 世紀以前，是指早於 1600 年代。"},{"en":"Many trade routes existed before the seventeenth century.","zh":"許多貿易路線在 17 世紀以前已存在。"},{"en":"If tulips spread before the seventeenth century, they were admired before the Dutch bubble.","zh":"如果鬱金香在 17 世紀以前已傳播，它們在荷蘭泡沫前已受欣賞。"},{"en":"This time phrase helps separate earlier flower history from later speculation.","zh":"這個時間短語幫助把早期花卉歷史與後來投機分開。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":18},{"front":"amount of money offered","meaning":"所出價的金額","examples":[{"en":"The question asks about the amount of money offered for a rare bulb.","zh":"題目問一個稀有球莖所出價的金額。"},{"en":"The amount of money offered is the price someone proposes to pay.","zh":"所出價的金額，是指某人提出願意支付的價格。"},{"en":"A seller may refuse if the amount of money offered is below the item’s value.","zh":"如果所出價的金額低於物品價值，賣家可能拒絕。"},{"en":"A huge amount of money offered for one bulb shows extreme demand.","zh":"為一個球莖所出價的金額巨大，顯示需求極端。"},{"en":"This phrase helps students locate a specific number in the passage.","zh":"這個短語幫助學生在篇章中定位具體數字。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":18},{"front":"rare bulb","meaning":"稀有球莖","examples":[{"en":"A rare bulb could be worth a fortune.","zh":"一個稀有球莖可能值一大筆錢。"},{"en":"A rare bulb is an uncommon plant bulb that is difficult to obtain.","zh":"稀有球莖是不常見、難以取得的植物球莖。"},{"en":"Collectors may protect a rare bulb carefully because it cannot be easily replaced.","zh":"收藏家可能小心保護稀有球莖，因為它不易替換。"},{"en":"Scarcity can make a rare bulb much more expensive than ordinary bulbs.","zh":"稀缺性可以令稀有球莖比普通球莖昂貴得多。"},{"en":"In tulip mania, a rare bulb could become a speculative asset.","zh":"在鬱金香狂熱中，稀有球莖可以成為投機資產。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":18},{"front":"treated as currency","meaning":"被當作貨幣","examples":[{"en":"The question asks whether tulips were treated as currency in Holland.","zh":"題目問鬱金香在荷蘭是否被當作貨幣。"},{"en":"Treated as currency means used like money to buy, sell or exchange things.","zh":"被當作貨幣，是指像金錢一樣用來購買、出售或交換東西。"},{"en":"In some games, points are treated as currency because players use them to buy items.","zh":"在一些遊戲中，積分被當作貨幣，因為玩家用它們購買物品。"},{"en":"If tulips were treated as currency, people would exchange them for goods or debts.","zh":"如果鬱金香被當作貨幣，人們會用它們交換貨物或清償債務。"},{"en":"This phrase asks whether bulbs functioned like money, not just flowers.","zh":"這個短語問球莖是否像金錢一樣運作，而不只是花。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":18},{"front":"comparison between…and…","meaning":"……與……之間的比較","examples":[{"en":"The question asks for a comparison between tulips and other flowers.","zh":"題目要求鬱金香與其他花之間的比較。"},{"en":"A comparison between two things shows how they are similar or different.","zh":"兩件事之間的比較，顯示它們如何相似或不同。"},{"en":"A comparison between online lessons and classroom lessons can reveal strengths and weaknesses.","zh":"網上課與課室課之間的比較可以揭示優點和弱點。"},{"en":"In reading tasks, comparisons often help locate contrast words in the passage.","zh":"在閱讀題中，比較常幫助定位篇章中的對比詞。"},{"en":"The comparison between tulips and other flowers highlights why tulips seemed special.","zh":"鬱金香與其他花之間的比較突顯鬱金香為何顯得特別。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":19},{"front":"agree with the information","meaning":"與資料一致","examples":[{"en":"Students decide whether statements agree with the information in the passage.","zh":"學生判斷陳述是否與篇章資料一致。"},{"en":"To agree with the information means to match what the text says.","zh":"與資料一致，是指配合文本所說的內容。"},{"en":"If the text says prices rose, a statement saying prices increased agrees with the information.","zh":"如果文本說價格上升，而陳述說價格增加，那就與資料一致。"},{"en":"Students should choose True only when the statement clearly agrees with the passage.","zh":"只有當陳述清楚與篇章一致時，學生才應選 True。"},{"en":"This phrase reminds learners to follow the text, not their own knowledge.","zh":"這個短語提醒學習者跟隨文本，而不是自己的知識。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":19},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A statement is false if it contradicts the information.","zh":"如果陳述與資料相矛盾，它就是錯誤的。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"與資料相矛盾，是指說出與文本相反的內容。"},{"en":"If the passage says the market crashed, a statement saying it continued rising contradicts the information.","zh":"如果篇章說市場崩潰，而陳述說它繼續上升，那就與資料相矛盾。"},{"en":"In True/False/Not Given questions, contradiction leads to False.","zh":"在 True/False/Not Given 題中，矛盾會導向 False。"},{"en":"This phrase helps students separate wrong information from missing information.","zh":"這個短語幫助學生區分錯誤資料與缺失資料。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":19},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有相關資料，學生寫 NOT GIVEN。"},{"en":"No information on this means the passage does not tell us whether the statement is true or false.","zh":"沒有相關資料，是指篇章沒有告訴我們該陳述是真或假。"},{"en":"If the passage names a trader but not his age, there is no information on this point.","zh":"如果篇章說出交易者姓名但沒有說年齡，這一點就沒有相關資料。"},{"en":"Students should not guess from outside knowledge when there is no information on this.","zh":"當沒有相關資料時，學生不應用外部知識猜測。"},{"en":"This phrase explains when to choose NOT GIVEN.","zh":"這個短語解釋何時選擇 NOT GIVEN。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":19},{"front":"entire collection of tulips","meaning":"全部鬱金香收藏","examples":[{"en":"The statement asks whether the entire collection of tulips belonged to one man.","zh":"該陳述問全部鬱金香收藏是否屬於一名男子。"},{"en":"An entire collection of tulips means all the tulips in that collection, not just some.","zh":"全部鬱金香收藏，是指該收藏中的所有鬱金香，而不只是部分。"},{"en":"A museum may buy an entire collection of paintings from one family.","zh":"博物館可能從一個家庭購買全部畫作收藏。"},{"en":"If an entire collection belongs to one person, that person controls all of it.","zh":"如果全部收藏屬於一個人，那人就控制全部。"},{"en":"This phrase focuses on ownership of the whole set.","zh":"這個短語聚焦整套收藏的所有權。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":19},{"front":"belong to","meaning":"屬於","examples":[{"en":"The statement asks whether all the tulips belonged to a man in Amsterdam.","zh":"該陳述問所有鬱金香是否屬於一名阿姆斯特丹男子。"},{"en":"To belong to someone means to be owned by that person.","zh":"屬於某人，是指由那個人擁有。"},{"en":"The notebook belongs to my sister, so I should ask before using it.","zh":"這本筆記本屬於我妹妹，所以使用前我應該先問。"},{"en":"If rare bulbs belong to one owner, buyers must negotiate with that owner.","zh":"如果稀有球莖屬於一名物主，買家必須與那名物主談判。"},{"en":"This phrase is used to discuss ownership.","zh":"這個短語用來討論所有權。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":19},{"front":"according to this passage","meaning":"根據本文","examples":[{"en":"Students judge the statement according to this passage.","zh":"學生根據本文判斷該陳述。"},{"en":"According to this passage means based only on what this text says.","zh":"根據本文，是指只基於這篇文本所說的內容。"},{"en":"According to this passage, students should not use facts from another article.","zh":"根據本文，學生不應使用另一篇文章的資料。"},{"en":"In reading exams, answers must be judged according to the passage, not personal opinion.","zh":"在閱讀考試中，答案必須根據本文判斷，而不是個人意見。"},{"en":"This phrase keeps the task tied to the given text.","zh":"這個短語使任務緊扣所給文本。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":19},{"front":"first planted in","meaning":"首次種植於","examples":[{"en":"The statement asks whether tulips were first planted in Holland.","zh":"該陳述問鬱金香是否首次種植於荷蘭。"},{"en":"First planted in a place means originally or earliest planted there.","zh":"首次種植於某地，是指最早在那裡種植。"},{"en":"A crop may be first planted in one region and later spread to others.","zh":"一種作物可能首次種植於某一地區，之後傳到其他地方。"},{"en":"If tulips were not first planted in Holland, the statement would not match the passage.","zh":"如果鬱金香並非首次種植於荷蘭，該陳述就不符合篇章。"},{"en":"This phrase asks about the earliest location, not the most famous later one.","zh":"這個短語問的是最早地點，而不是後來最有名的地點。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":19},{"front":"much higher than","meaning":"遠高於","examples":[{"en":"The statement compares tulip popularity in Holland with other countries.","zh":"該陳述比較鬱金香在荷蘭與其他國家的受歡迎程度。"},{"en":"Much higher than means far above another amount, level or degree.","zh":"遠高於，是指遠遠超過另一個數量、水平或程度。"},{"en":"Rent near the station is much higher than rent in the countryside.","zh":"車站附近租金遠高於鄉郊租金。"},{"en":"If popularity is much higher than elsewhere, demand may become unusually strong.","zh":"如果受歡迎程度遠高於其他地方，需求可能變得異常強烈。"},{"en":"This phrase signals a strong comparison, not a small difference.","zh":"這個短語表示強烈比較，而不是細小差異。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":19},{"front":"seventeenth century","meaning":"17世紀","examples":[{"en":"The passage focuses on Holland in the seventeenth century.","zh":"篇章聚焦 17 世紀的荷蘭。"},{"en":"The seventeenth century means the years from 1601 to 1700.","zh":"17 世紀是指 1601 年至 1700 年。"},{"en":"A history course may study trade and empire in the seventeenth century.","zh":"歷史課可能研究 17 世紀的貿易和帝國。"},{"en":"Understanding the seventeenth century helps readers place tulip mania in context.","zh":"理解 17 世紀有助讀者把鬱金香狂熱放入背景中。"},{"en":"This time phrase identifies the period when the Dutch tulip craze occurred.","zh":"這個時間短語指出荷蘭鬱金香狂熱發生的時期。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":19},{"front":"the wealthiest country in the world","meaning":"世界上最富有的國家","examples":[{"en":"The statement asks whether Holland was the wealthiest country in the world.","zh":"該陳述問荷蘭是否是世界上最富有的國家。"},{"en":"The wealthiest country in the world means the country with the greatest wealth compared with all others.","zh":"世界上最富有的國家，是指與所有其他國家相比財富最多的國家。"},{"en":"A country may become wealthy through trade, industry, resources or finance.","zh":"一個國家可以透過貿易、工業、資源或金融變得富有。"},{"en":"If a country is extremely wealthy, luxury goods and speculation may become more common.","zh":"如果一個國家非常富有，奢侈品和投機可能更常見。"},{"en":"This phrase asks about Holland’s economic position in the passage.","zh":"這個短語詢問篇章中荷蘭的經濟地位。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":19},{"front":"begin regulating","meaning":"開始規管","examples":[{"en":"The statement asks whether the stock exchange began regulating the tulip market.","zh":"該陳述問證券交易所是否開始規管鬱金香市場。"},{"en":"To begin regulating a market means to start making or enforcing rules for it.","zh":"開始規管市場，是指開始為它制定或執行規則。"},{"en":"A government may begin regulating food delivery apps after complaints about worker safety.","zh":"在收到關於工人安全的投訴後，政府可能開始規管外賣應用程式。"},{"en":"Regulation can reduce risk when trading becomes chaotic.","zh":"當交易變得混亂，規管可以降低風險。"},{"en":"This phrase asks whether official control of the tulip market started.","zh":"這個短語詢問鬱金香市場是否開始受到官方控制。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":20},{"front":"tulip market","meaning":"鬱金香市場","examples":[{"en":"The Amsterdam Stock Exchange did not control the tulip market.","zh":"阿姆斯特丹證券交易所沒有控制鬱金香市場。"},{"en":"The tulip market was the buying and selling system for tulip bulbs.","zh":"鬱金香市場是買賣鬱金香球莖的系統。"},{"en":"A market can exist in shops, taverns, online platforms or official exchanges.","zh":"市場可以存在於商店、酒館、網上平台或官方交易所。"},{"en":"The tulip market became risky when prices rose mainly because of speculation.","zh":"當價格主要因投機而上升，鬱金香市場變得危險。"},{"en":"The phrase refers to tulip trading as an economic activity.","zh":"這個短語指鬱金香交易作為一種經濟活動。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":20},{"front":"complete the following summary","meaning":"完成以下摘要","examples":[{"en":"Candidates complete the following summary using words from the passage.","zh":"考生使用篇章中的字詞完成以下摘要。"},{"en":"Complete the following summary means fill the gaps in the short text that comes next.","zh":"完成以下摘要，是指填寫接下來短文中的空格。"},{"en":"In reading exams, candidates complete the following summary by finding exact words in the passage.","zh":"在閱讀考試中，考生透過在篇章中找出原字完成以下摘要。"},{"en":"This task checks whether students understand the main ideas and sequence.","zh":"這項任務檢查學生是否理解主要意思和次序。"},{"en":"Students should read the grammar around each blank before choosing an answer.","zh":"學生在選答案前應閱讀每個空格周圍的文法。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":20},{"front":"no more than two words","meaning":"不超過兩個詞","examples":[{"en":"Candidates choose no more than two words from the passage.","zh":"考生從篇章中選取不超過兩個詞。"},{"en":"No more than two words means the answer can have one word or two words, but not three.","zh":"不超過兩個詞，是指答案可以有一個詞或兩個詞，但不能有三個。"},{"en":"If the answer is “Golden Age,” it fits because it has two words.","zh":"如果答案是 “Golden Age”，它符合要求，因為有兩個詞。"},{"en":"Students lose marks if they write more than the allowed number of words.","zh":"如果學生寫超過允許字數，就會失分。"},{"en":"This instruction tests both understanding and exact control of wording.","zh":"這項指示同時測試理解和對字詞的精確控制。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":20},{"front":"early seventeenth century","meaning":"17世紀初","examples":[{"en":"In the early seventeenth century, Holland was entering its Golden Age.","zh":"在 17 世紀初，荷蘭正進入其黃金時代。"},{"en":"The early seventeenth century means the beginning part of the 1600s.","zh":"17 世紀初，是指 1600 年代的開始部分。"},{"en":"In the early seventeenth century, trade and empire shaped many European economies.","zh":"在 17 世紀初，貿易和帝國塑造了許多歐洲經濟。"},{"en":"A time phrase like this helps place events in historical order.","zh":"這類時間短語幫助把事件放入歷史順序中。"},{"en":"The phrase marks the period when Holland’s wealth was beginning to grow strongly.","zh":"這個短語標示荷蘭財富開始強勁增長的時期。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":20},{"front":"focus on gaining independence","meaning":"專注於爭取獨立","examples":[{"en":"The Dutch focused on gaining independence from Spain.","zh":"荷蘭人專注於爭取脫離西班牙獨立。"},{"en":"To focus on gaining independence means to give attention, resources and effort to becoming politically free.","zh":"專注於爭取獨立，是指把注意力、資源和努力放在獲得政治自由上。"},{"en":"A colony may focus on gaining independence when it no longer accepts outside rule.","zh":"當殖民地不再接受外來統治，可能專注於爭取獨立。"},{"en":"When a country focuses on gaining independence, trade and luxury may receive less attention.","zh":"當一個國家專注於爭取獨立，貿易和奢侈品可能較少受到關注。"},{"en":"The phrase explains what Dutch resources had been used for before commerce expanded.","zh":"這個短語解釋商業擴張前荷蘭資源曾用於甚麼。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":20},{"front":"spare resources","meaning":"閒置資源；剩餘資源","examples":[{"en":"Spare resources flowed into commerce after the fighting.","zh":"戰鬥後，剩餘資源流入商業。"},{"en":"Spare resources are extra money, time, materials or labour not needed elsewhere.","zh":"閒置資源是指不再被其他地方需要的額外金錢、時間、材料或勞力。"},{"en":"A family may use spare resources to repair the home after paying basic bills.","zh":"家庭支付基本帳單後，可能用剩餘資源修理房屋。"},{"en":"When spare resources increase, people can invest in business, education or luxury goods.","zh":"當剩餘資源增加，人們可以投資於商業、教育或奢侈品。"},{"en":"In Holland, spare resources helped commerce expand after the struggle for independence.","zh":"在荷蘭，剩餘資源在獨立鬥爭後幫助商業擴張。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":20},{"front":"prosperous merchants","meaning":"富裕商人","examples":[{"en":"Prosperous merchants built grand estates.","zh":"富裕商人建造宏偉莊園。"},{"en":"Prosperous merchants are successful and wealthy traders.","zh":"富裕商人是成功而有錢的貿易商。"},{"en":"Prosperous merchants may spend money on houses, gardens, art and social status.","zh":"富裕商人可能把錢花在房屋、花園、藝術和社會地位上。"},{"en":"When merchants become prosperous, luxury markets can grow around them.","zh":"當商人變得富裕，奢侈品市場可以圍繞他們發展。"},{"en":"The phrase explains who had the wealth to display success through tulips and estates.","zh":"這個短語解釋誰有財力透過鬱金香和莊園展示成功。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":20},{"front":"demonstrate their status","meaning":"展示其地位","examples":[{"en":"Merchants demonstrated their status by building grand estates.","zh":"商人透過建造宏偉莊園展示其地位。"},{"en":"To demonstrate status means to show one’s social position or wealth clearly.","zh":"展示地位，是指清楚顯示自己的社會位置或財富。"},{"en":"Some people demonstrate their status through expensive watches or large homes.","zh":"有些人透過昂貴手錶或大房子展示其地位。"},{"en":"Status can be demonstrated through visible objects that others recognise as valuable.","zh":"地位可以透過他人認為有價值的可見物件展示。"},{"en":"In the passage, gardens and estates helped merchants show their rank in society.","zh":"在篇章中，花園和莊園幫助商人展示其社會階級。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":20},{"front":"attracted by the profits","meaning":"被利潤吸引","examples":[{"en":"Traders were attracted by the profits available from tulips.","zh":"交易商被鬱金香可帶來的利潤吸引。"},{"en":"Attracted by the profits means drawn in because of the chance to make money.","zh":"被利潤吸引，是指因賺錢機會而被拉入。"},{"en":"Many people are attracted by the profits of online sales before they understand the work involved.","zh":"許多人在了解所需工作前，就被網上銷售的利潤吸引。"},{"en":"High profits can attract new participants and make a market grow quickly.","zh":"高利潤可以吸引新參與者，令市場快速增長。"},{"en":"In the tulip market, profit stories pulled traders into speculation.","zh":"在鬱金香市場中，利潤故事把交易者拉入投機。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":20},{"front":"continue looking for","meaning":"繼續尋找","examples":[{"en":"Traders continued looking for flower lovers and speculators.","zh":"交易商繼續尋找愛花人士和投機者。"},{"en":"To continue looking for someone means to keep searching for them over time.","zh":"繼續尋找某人，是指持續搜尋他們。"},{"en":"A shop may continue looking for part-time staff after the first interview round fails.","zh":"如果第一輪面試失敗，商店可能繼續尋找兼職員工。"},{"en":"Traders continue looking for buyers when they believe more demand can be created.","zh":"當交易商相信可以創造更多需求，就會繼續尋找買家。"},{"en":"The phrase shows that professional traders actively expanded the tulip market.","zh":"這個短語顯示專業交易商主動擴大鬱金香市場。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":20},{"front":"flower lovers","meaning":"愛花人士","examples":[{"en":"Professional tulip traders sought out flower lovers.","zh":"專業鬱金香交易商尋找愛花人士。"},{"en":"Flower lovers are people who enjoy, admire or collect flowers.","zh":"愛花人士是喜歡、欣賞或收藏花卉的人。"},{"en":"Flower lovers may visit gardens, buy rare seeds or grow plants at home.","zh":"愛花人士可能參觀花園、購買稀有種子或在家種植物。"},{"en":"Because flower lovers value beauty, they may pay more for unusual flowers.","zh":"因為愛花人士重視美感，他們可能為不尋常的花支付更多。"},{"en":"In tulip mania, flower lovers became part of a larger speculative market.","zh":"在鬱金香狂熱中，愛花人士成為更大投機市場的一部分。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":21},{"front":"speculators","meaning":"投機者","examples":[{"en":"Speculators entered the tulip market in growing numbers.","zh":"投機者以越來越多的數量進入鬱金香市場。"},{"en":"Speculators are people who buy and sell mainly to profit from price changes.","zh":"投機者是主要為從價格變動中獲利而買賣的人。"},{"en":"Speculators may buy property, shares or collectibles without planning to use them.","zh":"投機者可能購買物業、股票或收藏品，而不打算使用它們。"},{"en":"When speculators enter a market in large numbers, prices may become unstable.","zh":"當大量投機者進入市場，價格可能變得不穩定。"},{"en":"The passage shows speculators helped turn tulips from flowers into financial bets.","zh":"篇章顯示投機者幫助把鬱金香從花變成金融賭注。"}],"source":"146 - When the Tulip Bubble Burst.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 147":[{"front":"video games’ unexpected benefits","meaning":"電子遊戲的意想不到好處","examples":[{"en":"The passage discusses video games’ unexpected benefits to the human brain.","zh":"文章討論電子遊戲對人腦的意想不到好處。"},{"en":"Video games’ unexpected benefits are positive effects that people may not expect from gaming.","zh":"video games’ unexpected benefits 指人們可能沒有預料到的電子遊戲正面影響。"},{"en":"A parent may notice video games’ unexpected benefits when a child becomes better at planning or reacting quickly.","zh":"當孩子變得更善於計劃或快速反應時，家長可能注意到電子遊戲的意想不到好處。"},{"en":"These benefits can challenge the idea that games are only harmful or useless.","zh":"這些好處可以挑戰「遊戲只會有害或無用」的想法。"},{"en":"The phrase is useful when a common activity has hidden advantages.","zh":"當一種常見活動有隱藏優點時，這個短語很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":1},{"front":"the human brain","meaning":"人腦","examples":[{"en":"Video games may have unexpected benefits for the human brain.","zh":"電子遊戲可能對人腦有意想不到的好處。"},{"en":"The human brain is the organ that controls thinking, memory, movement, and emotion.","zh":"the human brain 指控制思考、記憶、動作和情緒的器官。"},{"en":"Sleep, exercise, and learning all affect the human brain.","zh":"睡眠、運動和學習都會影響人腦。"},{"en":"If the human brain receives repeated practice, certain skills may become faster and stronger.","zh":"如果人腦得到反覆練習，某些技能可能變得更快、更強。"},{"en":"This phrase is useful when discussing learning, behaviour, health, or psychology.","zh":"討論學習、行為、健康或心理學時，這個短語很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":1},{"front":"professor of education","meaning":"教育學教授","examples":[{"en":"James Paul Gee is a professor of education at the University of Wisconsin-Madison.","zh":"James Paul Gee 是威斯康辛大學麥迪遜分校的教育學教授。"},{"en":"A professor of education is a university teacher and researcher who studies teaching and learning.","zh":"professor of education 指研究教與學的大學教師及研究人員。"},{"en":"A professor of education may study how children learn language, maths, or problem-solving.","zh":"教育學教授可能研究兒童如何學習語言、數學或解難。"},{"en":"Their research can influence schools, teacher training, and classroom methods.","zh":"他們的研究可以影響學校、教師培訓和課堂方法。"},{"en":"This title shows that the person speaks from an academic education background.","zh":"這個銜頭顯示該人具有教育學術背景。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":1},{"front":"play one’s first video game","meaning":"第一次玩電子遊戲","examples":[{"en":"James Paul Gee played his first video game when his son was six years old.","zh":"James Paul Gee 在兒子六歲時第一次玩電子遊戲。"},{"en":"To play one’s first video game means to experience a video game for the first time.","zh":"play one’s first video game 指第一次親身體驗電子遊戲。"},{"en":"A child may play her first video game on a family tablet at home.","zh":"孩子可能在家中的平板電腦上第一次玩電子遊戲。"},{"en":"Playing one’s first video game can make someone curious about how games teach rules and goals.","zh":"第一次玩電子遊戲可能令人好奇遊戲如何教授規則和目標。"},{"en":"This phrase focuses on the first personal experience with gaming.","zh":"這個短語重點在於個人第一次接觸電子遊戲的經驗。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":1},{"front":"six-year-old son","meaning":"六歲兒子","examples":[{"en":"Gee watched his six-year-old son play Pajama Sam.","zh":"Gee 看着他的六歲兒子玩 Pajama Sam。"},{"en":"A six-year-old son is a male child who is six years old.","zh":"six-year-old son 指六歲的男孩子。"},{"en":"A father may read instructions aloud to help his six-year-old son play a game.","zh":"父親可能朗讀指示，幫助六歲兒子玩遊戲。"},{"en":"A six-year-old son may need support because some tasks are still difficult at that age.","zh":"六歲兒子可能需要支援，因為這個年紀仍會覺得某些任務困難。"},{"en":"This phrase gives the reader a clear family and age context.","zh":"這個短語給讀者清楚的家庭和年齡背景。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":1},{"front":"support someone’s problem-solving","meaning":"支持某人解決問題","examples":[{"en":"Gee wanted to play the game so he could support Sam’s problem-solving.","zh":"Gee 想玩這個遊戲，好讓他能支持 Sam 解決問題。"},{"en":"To support someone’s problem-solving means to help them think through a problem and find a solution.","zh":"support someone’s problem-solving 指幫助某人思考問題並找出解決方法。"},{"en":"A teacher can support students’ problem-solving by asking guiding questions instead of giving answers immediately.","zh":"老師可以透過提出引導問題，而不是立即給答案，來支持學生解決問題。"},{"en":"Good support can make a learner more confident and independent.","zh":"良好支援可以令學習者更有信心和更獨立。"},{"en":"This phrase is useful when help is about thinking, not just doing the task for someone.","zh":"當幫助重點在於思考，而不是替別人完成任務時，這個短語很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":1},{"front":"educational game","meaning":"教育遊戲","examples":[{"en":"Pajama Sam is not an educational game.","zh":"Pajama Sam 不是教育遊戲。"},{"en":"An educational game is a game designed to teach knowledge or skills.","zh":"educational game 指設計來教授知識或技能的遊戲。"},{"en":"A spelling game for young children can be an educational game.","zh":"給幼兒玩的串字遊戲可以是教育遊戲。"},{"en":"Educational games work best when learning feels active rather than like a test.","zh":"當學習感覺主動，而不是像測驗時，教育遊戲效果最好。"},{"en":"Not every useful game is an educational game; some ordinary games also teach thinking skills.","zh":"並非每個有用的遊戲都是教育遊戲；有些普通遊戲也能教授思考技能。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":1},{"front":"be replete with","meaning":"充滿","examples":[{"en":"The game is replete with problems studied by psychologists.","zh":"這個遊戲充滿心理學家研究的問題。"},{"en":"To be replete with something means to be full of it.","zh":"be replete with something 指充滿某事物。"},{"en":"A good textbook is replete with examples that help students understand difficult ideas.","zh":"好教科書充滿幫助學生理解困難概念的例子。"},{"en":"If a report is replete with errors, readers may not trust it.","zh":"如果報告充滿錯誤，讀者可能不會信任它。"},{"en":"This phrase is formal and usually means something contains a large amount of something.","zh":"這個短語較正式，通常表示某物包含大量某事物。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":1},{"front":"types of problems","meaning":"各類問題","examples":[{"en":"The game contains the types of problems psychologists study.","zh":"這個遊戲包含心理學家研究的各類問題。"},{"en":"Types of problems are different categories or kinds of difficulties that people need to solve.","zh":"types of problems 指人們需要解決的不同類別或種類的困難。"},{"en":"In school, students meet different types of problems in maths, reading, and science.","zh":"在學校，學生會在數學、閱讀和科學中遇到各類問題。"},{"en":"Knowing the type of problem helps people choose the right method to solve it.","zh":"知道問題類型有助人們選擇正確方法解決它。"},{"en":"This phrase is useful when a topic includes several different problem forms.","zh":"當一個主題包含幾種不同問題形式時，這個短語很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":1},{"front":"thinking and learning","meaning":"思考與學習","examples":[{"en":"Psychologists study thinking and learning through problem-solving tasks.","zh":"心理學家透過解難任務研究思考與學習。"},{"en":"Thinking and learning refer to how people understand, remember, reason, and gain new skills.","zh":"thinking and learning 指人們如何理解、記憶、推理和獲得新技能。"},{"en":"A teacher observes students’ thinking and learning when they explain their answers.","zh":"當學生解釋答案時，老師會觀察他們的思考與學習。"},{"en":"Good feedback can improve thinking and learning because students see what to change.","zh":"良好回饋可以改善思考與學習，因為學生知道要改變甚麼。"},{"en":"This phrase connects mental processes with education.","zh":"這個短語把心智過程與教育連接起來。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":1},{"front":"hold someone’s attention","meaning":"吸引某人的注意力","examples":[{"en":"The game held Sam’s attention very well.","zh":"這個遊戲很好地吸引了 Sam 的注意力。"},{"en":"To hold someone’s attention means to keep them interested and focused.","zh":"hold someone’s attention 指令某人保持興趣和專注。"},{"en":"A clear story can hold children’s attention during a reading lesson.","zh":"清楚的故事可以在閱讀課中吸引孩子的注意力。"},{"en":"If a lesson cannot hold students’ attention, they may start talking or checking their phones.","zh":"如果課堂不能吸引學生注意力，他們可能開始聊天或看手機。"},{"en":"This phrase is useful when something keeps people mentally engaged.","zh":"當某事令人保持投入時，這個短語很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":1},{"front":"wonder what sort of beast","meaning":"想知道究竟是怎樣的東西","examples":[{"en":"Gee wondered what sort of beast a more mature video game might be.","zh":"Gee 想知道較成熟的電子遊戲究竟是怎樣的東西。"},{"en":"To wonder what sort of beast something is means to be curious about what kind of thing it really is.","zh":"wonder what sort of beast something is 指好奇某事物到底是甚麼樣的東西。"},{"en":"A new teacher may wonder what sort of beast the school exam system is before seeing it closely.","zh":"新老師在深入了解前，可能想知道學校考試制度究竟是怎樣的東西。"},{"en":"This phrase can show curiosity mixed with uncertainty or surprise.","zh":"這個短語可以表示好奇，同時帶有不確定或驚訝。"},{"en":"It is slightly informal and makes the object sound strange, complex, or unfamiliar.","zh":"它語氣稍微非正式，令對象聽起來奇怪、複雜或陌生。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":2},{"front":"a more mature video game","meaning":"較成熟的電子遊戲","examples":[{"en":"Gee became curious about what a more mature video game might be like.","zh":"Gee 開始好奇較成熟的電子遊戲會是甚麼樣子。"},{"en":"A more mature video game is a game designed for older players, with more complex ideas or tasks.","zh":"a more mature video game 指為年紀較大玩家設計、包含更複雜概念或任務的遊戲。"},{"en":"A teenager may enjoy a more mature video game because it has deeper stories and harder choices.","zh":"青少年可能喜歡較成熟的電子遊戲，因為它有更深入的故事和較困難的選擇。"},{"en":"More mature games can require planning, judgement, and patience.","zh":"較成熟的遊戲可能需要計劃、判斷和耐性。"},{"en":"This phrase contrasts simple children’s games with games for older or more experienced players.","zh":"這個短語把簡單兒童遊戲與較年長或較有經驗玩家玩的遊戲作對比。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":2},{"front":"video and computer games","meaning":"電子遊戲和電腦遊戲","examples":[{"en":"Video and computer games are often criticised by parents.","zh":"電子遊戲和電腦遊戲常被家長批評。"},{"en":"Video and computer games are digital games played on consoles, computers, phones, or other devices.","zh":"video and computer games 指在遊戲機、電腦、手機或其他裝置上玩的數碼遊戲。"},{"en":"Students may play video and computer games after school to relax.","zh":"學生放學後可能玩電子遊戲和電腦遊戲來放鬆。"},{"en":"Too much gaming can reduce sleep, but some games may also train useful skills.","zh":"過度打機可能減少睡眠，但有些遊戲也可能訓練有用技能。"},{"en":"This phrase covers many types of digital games, not just one platform.","zh":"這個短語涵蓋多種數碼遊戲，不只是單一平台。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":2},{"front":"popular, entertaining and addictive","meaning":"受歡迎、具娛樂性且令人上癮的","examples":[{"en":"Video games are popular, entertaining and addictive activities for children.","zh":"電子遊戲對兒童而言是受歡迎、具娛樂性且令人上癮的活動。"},{"en":"Popular, entertaining and addictive means liked by many people, enjoyable, and hard to stop doing.","zh":"popular, entertaining and addictive 指很多人喜歡、有趣，而且很難停止。"},{"en":"Short online videos can be popular, entertaining and addictive for teenagers.","zh":"短網上影片對青少年來說可能受歡迎、具娛樂性且令人上癮。"},{"en":"If an activity is addictive, people may keep doing it even when it affects sleep or homework.","zh":"如果一項活動令人上癮，人們即使影響睡眠或功課，也可能繼續做。"},{"en":"This phrase includes both positive appeal and possible risk.","zh":"這個短語同時包含正面吸引力和潛在風險。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":2},{"front":"be looked down upon by","meaning":"被……看不起；被……輕視","examples":[{"en":"Video games are looked down upon by many parents.","zh":"電子遊戲被許多家長看不起。"},{"en":"To be looked down upon by someone means to be disapproved of or treated as less valuable.","zh":"be looked down upon by someone 指被某人不認同或視為較低價值。"},{"en":"Practical jobs should not be looked down upon by students or parents.","zh":"實用職業不應被學生或家長看不起。"},{"en":"When a hobby is looked down upon, people may hide it even if it teaches useful skills.","zh":"當一種興趣被輕視時，人們可能會隱藏它，即使它能教授有用技能。"},{"en":"This phrase shows social judgement or disrespect.","zh":"這個短語表示社會評價或不尊重。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":2},{"front":"time-wasters","meaning":"浪費時間的東西","examples":[{"en":"Many parents dismiss video games as time-wasters.","zh":"許多家長把電子遊戲斥為浪費時間的東西。"},{"en":"Time-wasters are activities that people believe use time without producing value.","zh":"time-wasters 指人們認為花時間卻沒有價值的活動。"},{"en":"Some people see scrolling social media for hours as a time-waster.","zh":"有些人認為連續幾小時滑社交媒體是浪費時間。"},{"en":"Calling something a time-waster can be unfair if it also teaches, relaxes, or connects people.","zh":"如果某事同時能教人、放鬆人或連接人，把它稱為浪費時間可能不公平。"},{"en":"This word is often used when people judge an activity negatively.","zh":"這個詞常用於人們負面評價某活動時。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":2},{"front":"rot the brain","meaning":"損害大腦","examples":[{"en":"Some parents think video games rot the brain.","zh":"有些家長認為電子遊戲會損害大腦。"},{"en":"To rot the brain is an informal way to say something damages thinking or makes the mind weaker.","zh":"rot the brain 是非正式說法，表示某事會損害思考或令心智能力變弱。"},{"en":"A parent may say endless low-quality videos rot the brain if children watch them all day.","zh":"如果孩子整天看低質短片，家長可能說這些影片會損害大腦。"},{"en":"This phrase is usually emotional and critical, not a scientific description.","zh":"這個短語通常帶有情緒和批評，不是科學描述。"},{"en":"It suggests fear that an activity will harm intelligence or concentration.","zh":"它表示擔心某活動會傷害智力或專注力。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":2},{"front":"violent video games","meaning":"暴力電子遊戲","examples":[{"en":"Violent video games are often blamed for youth violence.","zh":"暴力電子遊戲常被歸咎為青少年暴力的原因。"},{"en":"Violent video games are games that include fighting, weapons, injury, or killing.","zh":"violent video games 指包含打鬥、武器、受傷或殺戮的遊戲。"},{"en":"Parents may worry when young children play violent video games without guidance.","zh":"當幼童在沒有指導下玩暴力電子遊戲，家長可能會擔心。"},{"en":"Public debate about violent video games often increases after serious youth crimes.","zh":"嚴重青少年罪案後，關於暴力電子遊戲的公共辯論常會增加。"},{"en":"This phrase describes game content, not every player’s behaviour.","zh":"這個短語描述遊戲內容，而不是每個玩家的行為。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":2},{"front":"be readily blamed by","meaning":"輕易被……歸咎","examples":[{"en":"Violent video games are readily blamed by the media.","zh":"暴力電子遊戲很容易被傳媒歸咎。"},{"en":"To be readily blamed by someone means to be quickly or easily treated as the cause of a problem.","zh":"be readily blamed by someone 指很快或很容易被某人視為問題原因。"},{"en":"Social media is readily blamed by adults when teenagers argue online.","zh":"當青少年在網上爭吵時，社交媒體很容易被成年人歸咎。"},{"en":"If something is readily blamed, people may ignore deeper causes.","zh":"如果某事被輕易歸咎，人們可能忽略更深層原因。"},{"en":"This phrase suggests that blame may be too quick or too simple.","zh":"這個短語表示歸咎可能太快或過於簡化。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":2},{"front":"the media and some experts","meaning":"傳媒和一些專家","examples":[{"en":"The media and some experts blame violent games for anti-social behaviour.","zh":"傳媒和一些專家把反社會行為歸咎於暴力遊戲。"},{"en":"The media and some experts means news organisations and certain specialists who give public opinions.","zh":"the media and some experts 指新聞機構和某些發表公共意見的專門人士。"},{"en":"The media and some experts may influence how parents understand a social problem.","zh":"傳媒和一些專家可能影響家長如何理解社會問題。"},{"en":"If the media and some experts repeat one explanation, the public may accept it quickly.","zh":"如果傳媒和一些專家重複同一解釋，公眾可能很快接受。"},{"en":"This phrase shows that an opinion is public, but not necessarily shared by everyone.","zh":"這個短語顯示某觀點是公開的，但不一定人人同意。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":2},{"front":"commit extreme anti-social behavior","meaning":"作出極端反社會行為","examples":[{"en":"Some people claim that video games make young people commit extreme anti-social behavior.","zh":"有些人聲稱電子遊戲令年輕人作出極端反社會行為。"},{"en":"To commit extreme anti-social behavior means to do very harmful actions against other people or society.","zh":"commit extreme anti-social behavior 指做出對他人或社會非常有害的行為。"},{"en":"Serious violence, cruelty, or repeated criminal acts may be described as extreme anti-social behavior.","zh":"嚴重暴力、殘忍行為或重複犯罪行為可能被描述為極端反社會行為。"},{"en":"Blaming one activity for such behaviour may ignore family, school, and mental health factors.","zh":"把這類行為歸咎於單一活動，可能忽略家庭、學校和心理健康因素。"},{"en":"This phrase is strong and should be used for serious behaviour, not small rudeness.","zh":"這個短語語氣強烈，應用於嚴重行為，而不是小小無禮。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":2},{"front":"content analyses","meaning":"內容分析","examples":[{"en":"Recent content analyses of video games show that many contain violence.","zh":"近期對電子遊戲的內容分析顯示，許多遊戲含有暴力。"},{"en":"Content analyses are studies that examine what appears inside media, such as images, words, or themes.","zh":"content analyses 指檢視媒體中出現的圖像、文字或主題的研究。"},{"en":"A teacher may use content analyses to compare how newspapers report the same issue.","zh":"老師可能用內容分析比較報紙如何報道同一議題。"},{"en":"Content analyses can show patterns, such as how often violence or stereotypes appear.","zh":"內容分析可以顯示模式，例如暴力或刻板印象出現的頻率。"},{"en":"This phrase is common in media research and academic writing.","zh":"這個短語常見於媒體研究和學術寫作。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":3},{"front":"as many as","meaning":"多達","examples":[{"en":"As many as 89% of games contain some violent content.","zh":"多達89%的遊戲含有某些暴力內容。"},{"en":"As many as is used before a number to show that the number is surprisingly high.","zh":"as many as 用於數字前，表示該數字高得令人注意。"},{"en":"As many as thirty students may join the class if demand is strong.","zh":"如果需求強烈，多達三十名學生可能加入這個班。"},{"en":"When as many as half the workers are absent, a company may close for the day.","zh":"當多達一半員工缺席，公司可能當天關門。"},{"en":"This phrase highlights quantity and often creates emphasis.","zh":"這個短語突出數量，常用來加強語氣。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":3},{"front":"violent content","meaning":"暴力內容","examples":[{"en":"Many video games contain some violent content.","zh":"許多電子遊戲含有某些暴力內容。"},{"en":"Violent content means material that shows fighting, injury, killing, or physical harm.","zh":"violent content 指展示打鬥、受傷、殺戮或身體傷害的內容。"},{"en":"A film with violent content may not be suitable for young children.","zh":"含有暴力內容的電影可能不適合幼童觀看。"},{"en":"If children see violent content often, adults may want to discuss what is real and what is fictional.","zh":"如果孩子經常接觸暴力內容，成年人可能需要討論甚麼是真實、甚麼是虛構。"},{"en":"This phrase describes what appears in media, not necessarily what viewers will do.","zh":"這個短語描述媒體中出現的內容，而不一定是觀眾會做的事。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":3},{"front":"aggressive content","meaning":"攻擊性內容","examples":[{"en":"Most popular games contain no other form of aggressive content.","zh":"大多數受歡迎的遊戲沒有其他形式的攻擊性內容。"},{"en":"Aggressive content means material that shows hostile, threatening, or attacking behaviour.","zh":"aggressive content 指展示敵意、威脅或攻擊行為的內容。"},{"en":"A cartoon may have aggressive content if characters insult or attack one another constantly.","zh":"如果卡通角色經常侮辱或攻擊彼此，該卡通可能含有攻擊性內容。"},{"en":"Aggressive content can affect how adults judge whether media is suitable for children.","zh":"攻擊性內容可以影響成年人判斷媒體是否適合兒童。"},{"en":"This phrase is broader than violent content because aggression may be verbal or emotional.","zh":"這個短語比 violent content 更廣，因為攻擊性可以是語言或情緒上的。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":3},{"front":"scientists and psychologists","meaning":"科學家和心理學家","examples":[{"en":"Many scientists and psychologists recognise benefits in video games.","zh":"許多科學家和心理學家承認電子遊戲有好處。"},{"en":"Scientists and psychologists are researchers who study the natural world, behaviour, thinking, and the mind.","zh":"scientists and psychologists 指研究自然世界、行為、思考和心智的研究人員。"},{"en":"Scientists and psychologists may use experiments to test whether games improve attention.","zh":"科學家和心理學家可能用實驗測試遊戲是否改善注意力。"},{"en":"Their findings can challenge simple public beliefs about technology.","zh":"他們的研究結果可以挑戰公眾對科技的簡單看法。"},{"en":"This phrase suggests evidence-based views rather than casual opinions.","zh":"這個短語表示基於證據的觀點，而不是隨意意見。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":3},{"front":"the principal one being that","meaning":"主要一點是","examples":[{"en":"Video games have many benefits, the principal one being that they make children smarter.","zh":"電子遊戲有很多好處，主要一點是它們令兒童更聰明。"},{"en":"The principal one being that introduces the main reason or most important point in a list.","zh":"the principal one being that 用來引出一系列原因或重點中最重要的一點。"},{"en":"The course has several advantages, the principal one being that students practise speaking every week.","zh":"這課程有幾個優點，主要一點是學生每週練習說話。"},{"en":"This phrase helps writers show which benefit matters most.","zh":"這個短語幫助作者顯示哪個好處最重要。"},{"en":"It is more formal than saying the main one is that.","zh":"它比 the main one is that 更正式。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":3},{"front":"make children smarter","meaning":"令兒童更聰明","examples":[{"en":"Some psychologists argue that video games make children smarter.","zh":"有些心理學家認為電子遊戲令兒童更聰明。"},{"en":"To make children smarter means to help children improve thinking, problem-solving, or learning ability.","zh":"make children smarter 指幫助兒童改善思考、解難或學習能力。"},{"en":"Reading difficult stories can make children smarter by building vocabulary and imagination.","zh":"閱讀較困難的故事可以透過建立詞彙和想像力令兒童更聰明。"},{"en":"Games may make children smarter if they require planning, attention, and flexible thinking.","zh":"如果遊戲要求計劃、注意力和靈活思考，它們可能令兒童更聰明。"},{"en":"This phrase should be understood as improving skills, not making every child a genius.","zh":"這個短語應理解為改善技能，而不是令每個孩子都成為天才。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":3},{"front":"high-level thinking skills","meaning":"高階思維能力","examples":[{"en":"Video games may teach children high-level thinking skills.","zh":"電子遊戲可能教授兒童高階思維能力。"},{"en":"High-level thinking skills are advanced mental abilities such as planning, analysing, judging, and solving problems.","zh":"high-level thinking skills 指計劃、分析、判斷和解難等較高層次的心智能力。"},{"en":"Students use high-level thinking skills when they compare two arguments in an essay.","zh":"學生在文章中比較兩個論點時，會使用高階思維能力。"},{"en":"Games can build these skills when players must choose strategies and learn from mistakes.","zh":"當玩家必須選擇策略並從錯誤中學習，遊戲可以建立這些能力。"},{"en":"This phrase refers to deeper thinking, not simple memorisation.","zh":"這個短語指較深層思考，而不是簡單背誦。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":3},{"front":"need in the future","meaning":"將來需要","examples":[{"en":"Children may need these thinking skills in the future.","zh":"兒童將來可能需要這些思維能力。"},{"en":"To need something in the future means it will be useful or necessary later in life.","zh":"need something in the future 指某事在日後生活中會有用或必要。"},{"en":"Students may need teamwork skills in the future when they enter the workplace.","zh":"學生日後進入職場時，可能將來需要團隊合作能力。"},{"en":"Learning digital skills now can help because many jobs will need them in the future.","zh":"現在學習數碼技能會有幫助，因為許多工作將來需要它們。"},{"en":"This phrase links present learning with later demands.","zh":"這個短語把現在的學習與日後需求連接起來。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":3},{"front":"change the brain","meaning":"改變大腦","examples":[{"en":"Video games can change the brain.","zh":"電子遊戲可以改變大腦。"},{"en":"To change the brain means to affect how the brain works or how its connections develop.","zh":"change the brain 指影響大腦的運作方式或連結發展。"},{"en":"Learning a language can change the brain by strengthening memory and attention.","zh":"學習語言可以透過加強記憶和注意力來改變大腦。"},{"en":"Repeated practice can change the brain because neural pathways become stronger.","zh":"反覆練習可以改變大腦，因為神經路徑會變得更強。"},{"en":"This phrase is often used when experience affects mental ability or structure.","zh":"當經驗影響心智能力或結構時，常用這個短語。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":3},{"front":"physical structure","meaning":"生理結構","examples":[{"en":"Video games can change the brain’s physical structure.","zh":"電子遊戲可以改變大腦的生理結構。"},{"en":"Physical structure means the actual shape, organisation, or material form of something.","zh":"physical structure 指某物實際的形狀、組織或物質形式。"},{"en":"Exercise can change the physical structure of muscles over time.","zh":"運動可以隨時間改變肌肉的生理結構。"},{"en":"If learning changes the brain’s physical structure, repeated practice may leave measurable effects.","zh":"如果學習改變大腦生理結構，反覆練習可能留下可測量影響。"},{"en":"This phrase focuses on real biological form, not only feelings or opinions.","zh":"這個短語聚焦真實生物形式，而不只是感受或看法。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":3},{"front":"in the same way as","meaning":"以與……相同的方式","examples":[{"en":"Video games change the brain in the same way as learning to read.","zh":"電子遊戲以與學習閱讀相同的方式改變大腦。"},{"en":"In the same way as means by a similar method or process.","zh":"in the same way as 指以相似方法或過程。"},{"en":"Practice improves speaking in the same way as regular exercise improves fitness.","zh":"練習以與定期運動改善體能相同的方式改善說話能力。"},{"en":"If two activities affect the brain in the same way, both may strengthen repeated patterns.","zh":"如果兩項活動以相同方式影響大腦，兩者都可能強化重複模式。"},{"en":"This phrase is used to compare how two things happen.","zh":"這個短語用來比較兩件事如何發生。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":4},{"front":"learning to read","meaning":"學習閱讀","examples":[{"en":"Learning to read changes the brain’s physical structure.","zh":"學習閱讀會改變大腦的生理結構。"},{"en":"Learning to read means developing the ability to understand written words and sentences.","zh":"learning to read 指發展理解書面詞語和句子的能力。"},{"en":"A child learning to read may first connect letters with sounds.","zh":"正在學習閱讀的孩子可能先把字母與聲音連結起來。"},{"en":"Learning to read can open access to stories, signs, instructions, and school subjects.","zh":"學習閱讀可以讓人接觸故事、標誌、指示和學校科目。"},{"en":"This phrase describes a major learning process, not just memorising the alphabet.","zh":"這個短語描述重要的學習過程，而不只是背誦字母。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":4},{"front":"playing the piano","meaning":"彈鋼琴","examples":[{"en":"Playing the piano can change the brain.","zh":"彈鋼琴可以改變大腦。"},{"en":"Playing the piano means using the fingers to produce music on a piano keyboard.","zh":"playing the piano 指用手指在鋼琴鍵盤上演奏音樂。"},{"en":"A child playing the piano must read notes, listen carefully, and control finger movement.","zh":"彈鋼琴的孩子必須讀樂譜、仔細聆聽並控制手指動作。"},{"en":"Regular piano practice can improve coordination, memory, and concentration.","zh":"定期鋼琴練習可以改善協調、記憶和專注力。"},{"en":"This phrase is often used as an example of skill learning through practice.","zh":"這個短語常作為透過練習學習技能的例子。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":4},{"front":"navigating using a map","meaning":"使用地圖導航","examples":[{"en":"Navigating using a map can change the brain’s structure.","zh":"使用地圖導航可以改變大腦結構。"},{"en":"Navigating using a map means finding one’s way by reading directions, symbols, and locations on a map.","zh":"navigating using a map 指透過閱讀地圖上的方向、符號和位置來找路。"},{"en":"A student navigating using a map must match streets on paper with real streets outside.","zh":"使用地圖導航的學生必須把紙上的街道與外面的真實街道配對。"},{"en":"This activity can strengthen spatial thinking because the person must judge direction and distance.","zh":"這項活動可以強化空間思維，因為人必須判斷方向和距離。"},{"en":"The phrase shows that everyday tasks can train the brain.","zh":"這個短語顯示日常任務也可以訓練大腦。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":4},{"front":"much like","meaning":"很像；正如","examples":[{"en":"Video games strengthen the brain much like exercise builds muscle.","zh":"電子遊戲強化大腦，很像運動增強肌肉。"},{"en":"Much like means in a very similar way to something else.","zh":"much like 指以非常相似的方式。"},{"en":"Learning vocabulary is much like saving money: small daily efforts build up over time.","zh":"學習詞彙很像儲錢：每天小小努力會慢慢累積。"},{"en":"A team improves much like a musician improves, through practice and feedback.","zh":"團隊進步很像音樂家進步，都是透過練習和回饋。"},{"en":"This phrase helps explain a difficult idea through a familiar comparison.","zh":"這個短語透過熟悉比較來解釋困難概念。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":4},{"front":"build muscle","meaning":"增強肌肉","examples":[{"en":"Exercise can build muscle.","zh":"運動可以增強肌肉。"},{"en":"To build muscle means to make muscles stronger and larger through repeated physical training.","zh":"build muscle 指透過反覆身體訓練令肌肉更強壯和更大。"},{"en":"Lifting weights can build muscle if a person trains safely and eats enough.","zh":"如果一個人安全訓練並攝取足夠營養，舉重可以增強肌肉。"},{"en":"Without rest, the body may struggle to build muscle properly.","zh":"如果沒有休息，身體可能難以有效增強肌肉。"},{"en":"This phrase is often used literally for the body and metaphorically for developing ability.","zh":"這個短語常用於身體，也可比喻能力的培養。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":4},{"front":"powerful combination of","meaning":"……的強大結合","examples":[{"en":"Video games involve a powerful combination of concentration and reward.","zh":"電子遊戲涉及專注力和獎賞的強大結合。"},{"en":"A powerful combination of things means two or more factors work together strongly.","zh":"a powerful combination of things 指兩個或更多因素有力地共同作用。"},{"en":"A good lesson uses a powerful combination of clear explanation and active practice.","zh":"好課堂運用清楚解釋和主動練習的強大結合。"},{"en":"When concentration and reward happen together, learners may stay engaged longer.","zh":"當專注和獎賞同時出現，學習者可能保持投入更久。"},{"en":"This phrase shows that the effect comes from factors working together.","zh":"這個短語顯示效果來自多個因素共同作用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":4},{"front":"concentration","meaning":"專注力","examples":[{"en":"Concentration helps strengthen the player’s brain.","zh":"專注力有助強化玩家的大腦。"},{"en":"Concentration is the ability to focus attention on one thing for a period of time.","zh":"concentration 指在一段時間內把注意力集中在一件事上的能力。"},{"en":"Students need concentration when solving a difficult maths problem.","zh":"學生解決困難數學題時需要專注力。"},{"en":"Noise, hunger, and phone notifications can reduce concentration.","zh":"噪音、飢餓和手機通知可以降低專注力。"},{"en":"Good concentration helps people learn because they notice details and avoid mistakes.","zh":"良好專注力有助學習，因為人能注意細節並避免錯誤。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":4},{"front":"rewarding surges of neurotransmitters","meaning":"帶來獎賞感的神經傳遞物激增","examples":[{"en":"Games can produce rewarding surges of neurotransmitters.","zh":"遊戲可以產生帶來獎賞感的神經傳遞物激增。"},{"en":"Rewarding surges of neurotransmitters are sudden increases in brain chemicals that create a feeling of reward.","zh":"rewarding surges of neurotransmitters 指腦內化學物突然增加，產生獎賞感。"},{"en":"Winning a level may create rewarding surges of neurotransmitters that make players want to continue.","zh":"通過一個關卡可能產生帶來獎賞感的神經傳遞物激增，使玩家想繼續玩。"},{"en":"These surges can strengthen learning because the brain connects effort with pleasure.","zh":"這些激增可以強化學習，因為大腦把努力與快感連接起來。"},{"en":"This phrase explains why some activities feel exciting and motivating.","zh":"這個短語解釋為何某些活動令人興奮和有動力。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":4},{"front":"dopamine","meaning":"多巴胺","examples":[{"en":"Dopamine can strengthen neural circuits.","zh":"多巴胺可以強化神經迴路。"},{"en":"Dopamine is a brain chemical linked to reward, motivation, movement, and learning.","zh":"dopamine 指與獎賞、動機、動作和學習有關的腦內化學物。"},{"en":"A small success in a game may release dopamine and make the player feel encouraged.","zh":"遊戲中的小成功可能釋放多巴胺，使玩家感到受鼓勵。"},{"en":"Dopamine can help the brain remember actions that lead to rewards.","zh":"多巴胺可以幫助大腦記住帶來獎賞的行動。"},{"en":"This word is often used when discussing motivation and habit formation.","zh":"討論動機和習慣形成時，常使用這個詞。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":4},{"front":"strengthen neural circuits","meaning":"強化神經迴路","examples":[{"en":"Dopamine strengthens neural circuits in the brain.","zh":"多巴胺會強化大腦中的神經迴路。"},{"en":"To strengthen neural circuits means to make connections between brain cells work more effectively.","zh":"strengthen neural circuits 指令腦細胞之間的連結更有效運作。"},{"en":"Repeated piano practice can strengthen neural circuits linked to finger movement and hearing.","zh":"反覆鋼琴練習可以強化與手指動作和聽覺有關的神經迴路。"},{"en":"When neural circuits are strengthened, a skill may become faster and more automatic.","zh":"當神經迴路被強化，技能可能變得更快和更自動化。"},{"en":"This phrase is useful when explaining how practice changes the brain.","zh":"解釋練習如何改變大腦時，這個短語很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":4},{"front":"strengthen the player’s brain","meaning":"強化玩家的大腦","examples":[{"en":"The combination of focus and reward can strengthen the player’s brain.","zh":"專注和獎賞的結合可以強化玩家的大腦。"},{"en":"To strengthen the player’s brain means to improve mental skills through repeated challenge and reward.","zh":"strengthen the player’s brain 指透過反覆挑戰和獎賞改善玩家的心智能力。"},{"en":"Puzzle games may strengthen the player’s brain by requiring memory, logic, and patience.","zh":"益智遊戲可能透過要求記憶、邏輯和耐性來強化玩家的大腦。"},{"en":"If a player solves harder problems over time, the brain may become better at similar tasks.","zh":"如果玩家隨時間解決更困難的問題，大腦可能更擅長類似任務。"},{"en":"This phrase suggests training, not simply entertainment.","zh":"這個短語暗示訓練，而不只是娛樂。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":5},{"front":"give someone’s brain a real workout","meaning":"令某人的大腦得到真正鍛鍊","examples":[{"en":"Video games give your child’s brain a real workout.","zh":"電子遊戲令你的孩子的大腦得到真正鍛鍊。"},{"en":"To give someone’s brain a real workout means to make them think hard and use mental effort.","zh":"give someone’s brain a real workout 指令某人努力思考並使用心智能量。"},{"en":"A difficult puzzle can give a student’s brain a real workout after school.","zh":"困難謎題可以在放學後令學生的大腦得到真正鍛鍊。"},{"en":"Brain workouts can improve skills when they involve challenge, feedback, and repeated practice.","zh":"當大腦鍛鍊包含挑戰、回饋和反覆練習時，它可以改善技能。"},{"en":"This phrase compares mental effort to physical exercise.","zh":"這個短語把心智努力比作身體運動。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":5},{"front":"skills required to win","meaning":"取勝所需的技能","examples":[{"en":"The skills required to win often involve high-level thinking.","zh":"取勝所需的技能常涉及高階思維。"},{"en":"Skills required to win are the abilities a person needs in order to succeed in a game or competition.","zh":"skills required to win 指人在遊戲或比賽中成功所需要的能力。"},{"en":"In chess, the skills required to win include planning, patience, and prediction.","zh":"在國際象棋中，取勝所需的技能包括計劃、耐性和預測。"},{"en":"If the skills required to win are difficult, players must practise instead of guessing.","zh":"如果取勝所需的技能很困難，玩家必須練習，而不是猜測。"},{"en":"This phrase focuses on what success demands.","zh":"這個短語聚焦成功需要甚麼。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":5},{"front":"abstract and high-level thinking","meaning":"抽象及高階思維","examples":[{"en":"Many video games require abstract and high-level thinking.","zh":"許多電子遊戲需要抽象及高階思維。"},{"en":"Abstract and high-level thinking means thinking about ideas, patterns, strategies, and relationships beyond simple facts.","zh":"abstract and high-level thinking 指思考概念、模式、策略和關係，而不只是簡單事實。"},{"en":"Students use abstract and high-level thinking when they explain why a historical event happened.","zh":"學生解釋歷史事件為何發生時，會使用抽象及高階思維。"},{"en":"Strategy games require this thinking because players must predict future results, not just react now.","zh":"策略遊戲需要這種思維，因為玩家必須預測未來結果，而不只是即時反應。"},{"en":"This phrase describes deeper mental work.","zh":"這個短語描述較深層的心智工作。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":5},{"front":"not even taught at school","meaning":"甚至沒有在學校教授","examples":[{"en":"Some skills developed by games are not even taught at school.","zh":"有些由遊戲培養的技能甚至沒有在學校教授。"},{"en":"Not even taught at school means something is absent from formal lessons, even though it may be useful.","zh":"not even taught at school 指某事沒有出現在正式課堂中，即使它可能有用。"},{"en":"Many students learn time management from part-time work, but it is not even taught at school directly.","zh":"許多學生從兼職工作學會時間管理，但它甚至沒有在學校直接教授。"},{"en":"If a skill is not even taught at school, children may learn it through hobbies or daily life.","zh":"如果一項技能甚至沒有在學校教授，孩子可能透過興趣或日常生活學習它。"},{"en":"This phrase can suggest surprise that an important skill is missing from education.","zh":"這個短語可以表示驚訝，因為重要技能竟然沒有在教育中出現。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":5},{"front":"mental skills","meaning":"心智能力","examples":[{"en":"Video games can develop several mental skills.","zh":"電子遊戲可以發展幾種心智能力。"},{"en":"Mental skills are abilities of the mind, such as attention, memory, planning, and reasoning.","zh":"mental skills 指心智方面的能力，例如注意力、記憶、計劃和推理。"},{"en":"Reading maps can improve mental skills related to direction and space.","zh":"閱讀地圖可以改善與方向和空間有關的心智能力。"},{"en":"Mental skills grow stronger when people practise challenging tasks repeatedly.","zh":"當人們反覆練習有挑戰性的任務，心智能力會變得更強。"},{"en":"This phrase refers to thinking abilities rather than physical strength.","zh":"這個短語指思考能力，而不是體力。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":5},{"front":"following instructions","meaning":"跟從指示","examples":[{"en":"Following instructions is one skill developed by video games.","zh":"跟從指示是電子遊戲培養的一項技能。"},{"en":"Following instructions means reading, understanding, and doing what directions tell you to do.","zh":"following instructions 指閱讀、理解並按照指示行動。"},{"en":"Students practise following instructions when they complete a science experiment safely.","zh":"學生安全完成科學實驗時，會練習跟從指示。"},{"en":"Poor instruction-following can lead to mistakes, accidents, or unfinished work.","zh":"不善於跟從指示可能導致錯誤、意外或工作未完成。"},{"en":"This skill is useful in school, work, cooking, travel, and games.","zh":"這項技能在學校、工作、煮食、旅行和遊戲中都有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":5},{"front":"problem-solving","meaning":"解難能力","examples":[{"en":"Video games often require problem-solving.","zh":"電子遊戲常需要解難能力。"},{"en":"Problem-solving is the process of finding a way to deal with a difficulty or question.","zh":"problem-solving 指找出方法處理困難或問題的過程。"},{"en":"A student uses problem-solving when a computer stops working before a presentation.","zh":"當學生在匯報前遇到電腦故障，就會使用解難能力。"},{"en":"Good problem-solving often involves testing ideas, learning from mistakes, and trying again.","zh":"良好解難常涉及測試想法、從錯誤中學習並再次嘗試。"},{"en":"This skill matters because real life rarely gives perfect instructions.","zh":"這項技能很重要，因為現實生活很少給出完美指示。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":5},{"front":"hand-eye coordination","meaning":"手眼協調","examples":[{"en":"Video games can improve hand-eye coordination.","zh":"電子遊戲可以改善手眼協調。"},{"en":"Hand-eye coordination is the ability to make hand movements match what the eyes see.","zh":"hand-eye coordination 指讓手部動作配合眼睛所見的能力。"},{"en":"Catching a ball requires hand-eye coordination.","zh":"接球需要手眼協調。"},{"en":"Games that require fast aiming may train hand-eye coordination through repeated practice.","zh":"需要快速瞄準的遊戲可能透過反覆練習訓練手眼協調。"},{"en":"This skill is useful in sports, driving, surgery, and daily tasks.","zh":"這項技能在運動、駕駛、手術和日常任務中都有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":5},{"front":"fine motor and spatial skills","meaning":"精細動作和空間技能","examples":[{"en":"Some games develop fine motor and spatial skills.","zh":"有些遊戲培養精細動作和空間技能。"},{"en":"Fine motor and spatial skills involve small precise movements and understanding space, shape, and direction.","zh":"fine motor and spatial skills 涉及細小精準動作，以及理解空間、形狀和方向。"},{"en":"Drawing, sewing, and building models can develop fine motor and spatial skills.","zh":"繪畫、縫紉和製作模型可以培養精細動作和空間技能。"},{"en":"These skills help people control tools and judge where objects are placed.","zh":"這些技能幫助人們控制工具並判斷物件位置。"},{"en":"This phrase combines body control with mental understanding of space.","zh":"這個短語結合身體控制和對空間的心智理解。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":5},{"front":"research suggests that","meaning":"研究顯示","examples":[{"en":"Research suggests that people can learn visual attention skills from games.","zh":"研究顯示，人們可以從遊戲中學習視覺注意力技能。"},{"en":"Research suggests that means studies indicate something is likely, though it may not be absolutely proven.","zh":"research suggests that 表示研究指出某事很可能成立，但未必絕對證明。"},{"en":"Research suggests that regular sleep helps students remember new words.","zh":"研究顯示，規律睡眠有助學生記住新詞。"},{"en":"Writers use this phrase when they want to sound careful and evidence-based.","zh":"作者想顯得謹慎並以證據為本時，會使用這個短語。"},{"en":"It is weaker and more cautious than research proves that.","zh":"它比 research proves that 較弱、較謹慎。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":5},{"front":"iconic, spatial, and visual attention skills","meaning":"圖像、空間及視覺注意力技能","examples":[{"en":"Video games may improve iconic, spatial, and visual attention skills.","zh":"電子遊戲可能改善圖像、空間及視覺注意力技能。"},{"en":"These skills involve noticing images, understanding space, and focusing on visual information.","zh":"這些技能涉及注意圖像、理解空間，以及集中處理視覺資訊。"},{"en":"A driver uses visual attention skills when watching signs, cars, and pedestrians at the same time.","zh":"司機同時留意路牌、車輛和行人時，會使用視覺注意力技能。"},{"en":"Games may train these skills by forcing players to track many objects quickly.","zh":"遊戲可能透過迫使玩家快速追蹤多個物件來訓練這些技能。"},{"en":"This phrase describes several related ways of processing what we see.","zh":"這個短語描述幾種相關的視覺處理方式。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":6},{"front":"experience with video games","meaning":"玩電子遊戲的經驗","examples":[{"en":"Experience with video games is related to better surgical skills.","zh":"玩電子遊戲的經驗與較佳外科技能有關。"},{"en":"Experience with video games means time spent playing and learning how games work.","zh":"experience with video games 指花時間玩遊戲並學會遊戲如何運作的經驗。"},{"en":"A teenager with experience with video games may be quick at using controllers or keyboards.","zh":"有玩電子遊戲經驗的青少年可能很快掌握控制器或鍵盤。"},{"en":"Such experience can matter when a task also requires fast reactions and hand control.","zh":"當任務同樣需要快速反應和手部控制，這類經驗可能重要。"},{"en":"This phrase focuses on previous practice, not natural talent alone.","zh":"這個短語聚焦過往練習，而不只是天賦。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":6},{"front":"be related to","meaning":"與……有關","examples":[{"en":"Video-game experience is related to better surgical skills.","zh":"電子遊戲經驗與較佳外科技能有關。"},{"en":"To be related to something means to have a connection with it.","zh":"be related to something 指與某事有連繫。"},{"en":"Poor sleep is related to weaker concentration in class.","zh":"睡眠不足與課堂專注力較弱有關。"},{"en":"If two things are related, one may influence the other, but the link still needs careful study.","zh":"如果兩件事有關，其中一件可能影響另一件，但仍需仔細研究。"},{"en":"This phrase shows connection, not always direct cause.","zh":"這個短語表示關聯，不一定表示直接原因。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":6},{"front":"surgical skills","meaning":"外科技能","examples":[{"en":"Some studies connect video gaming with better surgical skills.","zh":"有些研究把電子遊戲與較佳外科技能連繫起來。"},{"en":"Surgical skills are the abilities doctors need to perform operations safely and accurately.","zh":"surgical skills 指醫生安全而準確地進行手術所需的能力。"},{"en":"Surgical skills include steady hands, careful vision, judgement, and knowledge of the body.","zh":"外科技能包括穩定雙手、仔細視覺、判斷力和身體知識。"},{"en":"Poor surgical skills can increase the risk of mistakes during an operation.","zh":"外科技能不足可能增加手術期間出錯的風險。"},{"en":"This phrase is used in medical contexts and refers to practical operating ability.","zh":"這個短語用於醫療語境，指實際手術能力。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":6},{"front":"direct link between","meaning":"……之間的直接關聯","examples":[{"en":"Jacob Benjamin found a direct link between video-game skill and surgical skill.","zh":"Jacob Benjamin 發現電子遊戲技巧與外科技能之間有直接關聯。"},{"en":"A direct link between two things means a clear connection from one to the other.","zh":"direct link between two things 指兩件事之間有清楚連繫。"},{"en":"A doctor may find a direct link between poor diet and a patient’s stomach pain.","zh":"醫生可能發現不良飲食與病人胃痛之間有直接關聯。"},{"en":"When a direct link is found, researchers still need to explain how and why it happens.","zh":"當發現直接關聯時，研究人員仍需要解釋它如何和為何發生。"},{"en":"This phrase is stronger than saying the two things are only loosely connected.","zh":"這個短語比只說兩者鬆散相關更強。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":6},{"front":"skill at video gaming","meaning":"玩電子遊戲的技巧","examples":[{"en":"Skill at video gaming may be linked to surgical performance.","zh":"玩電子遊戲的技巧可能與手術表現有關。"},{"en":"Skill at video gaming means the ability to play video games well.","zh":"skill at video gaming 指把電子遊戲玩得好的能力。"},{"en":"A person with skill at video gaming may react quickly and control small movements accurately.","zh":"有玩電子遊戲技巧的人可能反應快速，並能準確控制細小動作。"},{"en":"This skill can develop through practice, feedback, and repeated failure.","zh":"這項技巧可以透過練習、回饋和反覆失敗培養。"},{"en":"The phrase focuses on ability, not simply time spent playing.","zh":"這個短語聚焦能力，而不只是花了多少時間玩。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":6},{"front":"keyhole surgery","meaning":"鎖孔手術","examples":[{"en":"Skill at video gaming may relate to skill at keyhole surgery.","zh":"玩電子遊戲的技巧可能與鎖孔手術技巧有關。"},{"en":"Keyhole surgery is surgery done through very small cuts using tiny instruments and a camera.","zh":"keyhole surgery 指透過很小切口，使用微型工具和攝影機進行的手術。"},{"en":"A surgeon doing keyhole surgery must control tools while watching a screen.","zh":"進行鎖孔手術的外科醫生必須一邊看屏幕，一邊控制工具。"},{"en":"Because keyhole surgery requires hand-eye coordination, some gaming skills may be relevant.","zh":"由於鎖孔手術需要手眼協調，一些遊戲技能可能相關。"},{"en":"This phrase is a common term for minimally invasive surgery.","zh":"這個短語是微創手術的常見名稱。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":6},{"front":"laparoscopic surgery","meaning":"腹腔鏡手術","examples":[{"en":"Laparoscopic surgery requires precise hand-eye coordination.","zh":"腹腔鏡手術需要精準手眼協調。"},{"en":"Laparoscopic surgery is a type of keyhole surgery using a camera and small instruments inside the body.","zh":"laparoscopic surgery 是一種鎖孔手術，使用攝影機和細小工具在體內操作。"},{"en":"During laparoscopic surgery, doctors often guide tools by watching a screen.","zh":"在腹腔鏡手術中，醫生常透過觀看屏幕引導工具。"},{"en":"Precision matters because small movements can affect delicate body tissues.","zh":"精準很重要，因為細小動作可以影響脆弱身體組織。"},{"en":"This phrase is used in medical and surgical contexts.","zh":"這個短語用於醫療和外科語境。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":6},{"front":"a reason given by experts","meaning":"專家提出的原因","examples":[{"en":"Experts give video-game experience as one reason for pilots’ skill.","zh":"專家把電子遊戲經驗列為機師技能的其中一個原因。"},{"en":"A reason given by experts is an explanation offered by people with specialist knowledge.","zh":"a reason given by experts 指具有專門知識的人提出的解釋。"},{"en":"A reason given by experts for poor sleep may be too much screen use before bed.","zh":"專家提出睡眠差的其中一個原因，可能是睡前使用屏幕太多。"},{"en":"Expert reasons can guide public understanding, but they should still be supported by evidence.","zh":"專家提出的原因可以引導公眾理解，但仍應有證據支持。"},{"en":"This phrase shows that the explanation comes from specialists, not random opinion.","zh":"這個短語顯示解釋來自專家，而不是隨機意見。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":6},{"front":"fighter pilots","meaning":"戰鬥機機師","examples":[{"en":"Some experts link modern fighter pilots’ skills to video games.","zh":"有些專家把現代戰鬥機機師的技能與電子遊戲連繫起來。"},{"en":"Fighter pilots are pilots trained to fly military aircraft in combat or defence situations.","zh":"fighter pilots 指受訓在戰鬥或防衛情境中駕駛軍用飛機的機師。"},{"en":"Fighter pilots need quick reactions, spatial awareness, and calm decision-making.","zh":"戰鬥機機師需要快速反應、空間感和冷靜決策。"},{"en":"Training fighter pilots is difficult because mistakes can be dangerous and costly.","zh":"訓練戰鬥機機師很困難，因為錯誤可能危險且昂貴。"},{"en":"This phrase belongs to military aviation.","zh":"這個短語屬於軍事航空領域。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":6},{"front":"more skillful","meaning":"技術更熟練","examples":[{"en":"Fighter pilots today may be more skillful because of early gaming experience.","zh":"今天的戰鬥機機師可能因早期遊戲經驗而技術更熟練。"},{"en":"More skillful means better trained or more able to do something well.","zh":"more skillful 指訓練更好或更有能力做好某事。"},{"en":"A cook becomes more skillful after practising knife work every day.","zh":"廚師每天練習刀工後會技術更熟練。"},{"en":"People become more skillful when they receive feedback and correct repeated mistakes.","zh":"當人們得到回饋並糾正重複錯誤，就會變得技術更熟練。"},{"en":"This phrase compares ability with an earlier level or another group.","zh":"這個短語把能力與較早水平或另一群體作比較。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":6},{"front":"be weaned on video games","meaning":"從小接觸電子遊戲","examples":[{"en":"This generation’s pilots are being weaned on video games.","zh":"這一代機師從小接觸電子遊戲。"},{"en":"To be weaned on video games means to grow up with video games from an early age.","zh":"be weaned on video games 指從很小的年紀就與電子遊戲一起成長。"},{"en":"Children weaned on tablets may feel comfortable using digital tools before school.","zh":"從小接觸平板電腦的孩子，入學前可能已熟悉數碼工具。"},{"en":"If pilots are weaned on video games, they may already be used to screens and fast controls.","zh":"如果機師從小接觸電子遊戲，他們可能已習慣屏幕和快速控制。"},{"en":"This phrase is informal and suggests early, regular exposure.","zh":"這個短語較非正式，表示早期而經常的接觸。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":7},{"front":"manage limited resources","meaning":"管理有限資源","examples":[{"en":"Players learn to manage limited resources.","zh":"玩家學會管理有限資源。"},{"en":"To manage limited resources means to use a small amount of money, time, materials, or energy wisely.","zh":"manage limited resources 指明智地使用少量金錢、時間、材料或精力。"},{"en":"A student must manage limited resources when preparing for exams with little time left.","zh":"當備考時間不多，學生必須管理有限資源。"},{"en":"Poor resource management can lead to waste, shortage, or failure.","zh":"資源管理不善可能導致浪費、短缺或失敗。"},{"en":"This phrase is useful in games, business, study, and daily life.","zh":"這個短語在遊戲、商業、學習和日常生活中都有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":7},{"front":"decide how best to","meaning":"決定如何最有效地……","examples":[{"en":"Players decide how best to use their resources.","zh":"玩家決定如何最有效地使用資源。"},{"en":"To decide how best to do something means to choose the most effective way to do it.","zh":"decide how best to do something 指選擇做某事最有效的方法。"},{"en":"A family may decide how best to spend a limited monthly budget.","zh":"家庭可能決定如何最有效地使用有限的每月預算。"},{"en":"Good decisions often require comparing costs, benefits, risks, and timing.","zh":"好決定常需要比較成本、好處、風險和時間。"},{"en":"This phrase focuses on choosing the smartest method, not just any method.","zh":"這個短語聚焦選擇最明智的方法，而不是任何方法。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":7},{"front":"just as in real life","meaning":"就像在現實生活中一樣","examples":[{"en":"Players manage limited resources just as in real life.","zh":"玩家管理有限資源，就像在現實生活中一樣。"},{"en":"Just as in real life means in the same way that something happens outside the game or story.","zh":"just as in real life 指與遊戲或故事以外的真實情況相同。"},{"en":"In a classroom project, students must share time and materials just as in real life.","zh":"在課堂項目中，學生必須共享時間和材料，就像在現實生活中一樣。"},{"en":"Games can feel meaningful when their challenges resemble choices people face in daily life.","zh":"當遊戲挑戰類似人們日常面對的選擇時，遊戲會更有意義。"},{"en":"This phrase connects a simulated situation with ordinary experience.","zh":"這個短語把模擬情境與普通經驗連接起來。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":7},{"front":"strategy games","meaning":"策略遊戲","examples":[{"en":"Strategy games require planning and resource management.","zh":"策略遊戲需要計劃和資源管理。"},{"en":"Strategy games are games where players must plan actions carefully to reach goals.","zh":"strategy games 指玩家必須仔細計劃行動以達成目標的遊戲。"},{"en":"Chess, city-building games, and war simulations can be strategy games.","zh":"國際象棋、城市建設遊戲和戰爭模擬可以是策略遊戲。"},{"en":"In strategy games, careless short-term choices can cause long-term failure.","zh":"在策略遊戲中，粗心的短期選擇可能造成長期失敗。"},{"en":"This phrase describes games that reward planning more than luck.","zh":"這個短語描述比運氣更重視計劃的遊戲。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":7},{"front":"developing a city","meaning":"發展一座城市","examples":[{"en":"In some strategy games, players are developing a city.","zh":"在某些策略遊戲中，玩家正在發展一座城市。"},{"en":"Developing a city means building and improving housing, roads, services, and the economy of a city.","zh":"developing a city 指建設和改善一座城市的住房、道路、服務和經濟。"},{"en":"A mayor developing a city must think about transport, schools, jobs, and pollution.","zh":"市長發展一座城市時，必須考慮交通、學校、工作和污染。"},{"en":"If a city develops without planning, traffic and housing problems may become serious.","zh":"如果城市發展缺乏規劃，交通和住房問題可能變得嚴重。"},{"en":"This phrase can be used in games and real urban planning.","zh":"這個短語可用於遊戲和真實城市規劃。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":7},{"front":"unexpected threat","meaning":"意想不到的威脅","examples":[{"en":"An unexpected threat may emerge during a strategy game.","zh":"策略遊戲中可能出現意想不到的威脅。"},{"en":"An unexpected threat is a danger or problem that appears suddenly and was not planned for.","zh":"unexpected threat 指突然出現、沒有預先計劃應對的危險或問題。"},{"en":"A sudden storm can be an unexpected threat during an outdoor school trip.","zh":"戶外學校旅行期間，突如其來的暴風雨可以是意想不到的威脅。"},{"en":"Unexpected threats force people to change plans quickly.","zh":"意想不到的威脅迫使人們迅速改變計劃。"},{"en":"This phrase is useful when danger appears without warning.","zh":"當危險毫無預警地出現時，這個短語很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":7},{"front":"emerge","meaning":"出現","examples":[{"en":"An enemy might emerge while the player is developing a city.","zh":"當玩家正在發展城市時，敵人可能出現。"},{"en":"To emerge means to appear, become visible, or become known.","zh":"emerge 指出現、變得可見或被人知道。"},{"en":"New problems may emerge after a school changes its timetable.","zh":"學校改變時間表後，新問題可能出現。"},{"en":"When a hidden issue emerges, people must deal with it instead of ignoring it.","zh":"當隱藏問題出現時，人們必須處理，而不是忽視它。"},{"en":"This verb is useful for things that appear gradually or suddenly.","zh":"這個動詞適用於逐漸或突然出現的事物。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":7},{"front":"force the player to","meaning":"迫使玩家去……","examples":[{"en":"An unexpected threat forces the player to change tactics.","zh":"意想不到的威脅迫使玩家改變策略。"},{"en":"To force the player to do something means to make the player do it because the situation demands it.","zh":"force the player to do something 指情況要求玩家必須做某事。"},{"en":"A low health level may force the player to retreat and find supplies.","zh":"低生命值可能迫使玩家撤退並尋找補給。"},{"en":"Pressure in games can force players to think quickly and adapt.","zh":"遊戲中的壓力可以迫使玩家快速思考和適應。"},{"en":"This phrase shows that the action is necessary, not optional.","zh":"這個短語顯示該行動是必要的，而不是可選的。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":7},{"front":"be flexible","meaning":"靈活變通","examples":[{"en":"Players have to be flexible when threats appear suddenly.","zh":"當威脅突然出現時，玩家必須靈活變通。"},{"en":"To be flexible means to be able to change plans when conditions change.","zh":"be flexible 指當情況改變時能夠改變計劃。"},{"en":"A teacher must be flexible if a lesson activity takes longer than expected.","zh":"如果課堂活動花的時間比預期長，老師必須靈活變通。"},{"en":"Flexible people handle surprises better because they do not cling to one fixed plan.","zh":"靈活的人較能處理意外，因為他們不固守單一計劃。"},{"en":"This phrase describes adaptability in thinking or action.","zh":"這個短語描述思考或行動上的適應能力。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":7},{"front":"change tactics","meaning":"改變策略","examples":[{"en":"Players must quickly change tactics during a game.","zh":"玩家在遊戲中必須迅速改變策略。"},{"en":"To change tactics means to use a different method or plan to deal with a situation.","zh":"change tactics 指使用不同方法或計劃來應對情況。"},{"en":"A football team may change tactics when the other team scores first.","zh":"當對手先入球時，足球隊可能改變策略。"},{"en":"If the old method fails, changing tactics can prevent repeated mistakes.","zh":"如果舊方法失敗，改變策略可以防止重複錯誤。"},{"en":"This phrase is useful when strategy must adjust to new conditions.","zh":"當策略必須因新情況而調整時，這個短語很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":7},{"front":"almost every second","meaning":"幾乎每一秒","examples":[{"en":"Some players make decisions almost every second.","zh":"有些玩家幾乎每一秒都在作決定。"},{"en":"Almost every second means very frequently, with hardly any pause.","zh":"almost every second 指非常頻繁，幾乎沒有停頓。"},{"en":"A busy nurse may answer questions and make small decisions almost every second.","zh":"忙碌的護士可能幾乎每一秒都在回答問題和作小決定。"},{"en":"When tasks happen almost every second, people need focus and quick judgement.","zh":"當任務幾乎每一秒都發生，人們需要專注和快速判斷。"},{"en":"This phrase emphasises speed and constant activity.","zh":"這個短語強調速度和持續活動。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":8},{"front":"led by","meaning":"由……帶領","examples":[{"en":"The research team was led by Daphne Bavelier.","zh":"研究團隊由 Daphne Bavelier 帶領。"},{"en":"Led by means guided, directed, or managed by a particular person.","zh":"led by 指由某個人引導、指揮或管理。"},{"en":"The school project was led by a senior teacher.","zh":"這個學校項目由一位資深老師帶領。"},{"en":"A team led by an experienced manager may avoid confusion and wasted effort.","zh":"由有經驗經理帶領的團隊可能避免混亂和浪費努力。"},{"en":"This phrase identifies the person in charge.","zh":"這個短語指出負責的人。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":8},{"front":"cognitive scientist","meaning":"認知科學家","examples":[{"en":"Daphne Bavelier is a cognitive scientist.","zh":"Daphne Bavelier 是一位認知科學家。"},{"en":"A cognitive scientist studies thinking, attention, memory, learning, and the mind.","zh":"cognitive scientist 指研究思考、注意力、記憶、學習和心智的人。"},{"en":"A cognitive scientist may test how people make decisions under pressure.","zh":"認知科學家可能測試人在壓力下如何作決定。"},{"en":"Cognitive science can help explain why certain games improve attention or reaction speed.","zh":"認知科學可以幫助解釋為何某些遊戲改善注意力或反應速度。"},{"en":"This title suggests research into mental processes.","zh":"這個銜頭表示研究心智過程。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":8},{"front":"simulate stressful events","meaning":"模擬壓力情境","examples":[{"en":"Some games simulate stressful events such as battles.","zh":"有些遊戲模擬戰鬥等壓力情境。"},{"en":"To simulate stressful events means to copy difficult situations in a safe or artificial setting.","zh":"simulate stressful events 指在安全或人造環境中模仿困難情境。"},{"en":"Flight training software can simulate stressful events like engine failure.","zh":"飛行訓練軟件可以模擬引擎故障等壓力情境。"},{"en":"Simulations allow people to practise decisions before facing real danger.","zh":"模擬讓人在面對真實危險前練習決策。"},{"en":"This phrase is useful when training copies pressure without using real risk.","zh":"當訓練在沒有真實風險下複製壓力時，這個短語很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":8},{"front":"battle or action games","meaning":"戰鬥或動作遊戲","examples":[{"en":"Battle or action games may train players for real-world situations.","zh":"戰鬥或動作遊戲可能訓練玩家應對現實世界情境。"},{"en":"Battle or action games are games that involve fast movement, combat, danger, or quick reactions.","zh":"battle or action games 指涉及快速移動、戰鬥、危險或快速反應的遊戲。"},{"en":"Players in battle or action games must often watch several threats at once.","zh":"戰鬥或動作遊戲中的玩家常要同時留意幾個威脅。"},{"en":"These games may train reaction speed because decisions must be made quickly.","zh":"這些遊戲可能訓練反應速度，因為玩家必須快速作決定。"},{"en":"This phrase refers to fast, intense games rather than slow puzzle games.","zh":"這個短語指快速而緊張的遊戲，而不是慢速益智遊戲。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":8},{"front":"training tool","meaning":"訓練工具","examples":[{"en":"Action video games could be a training tool.","zh":"動作電子遊戲可以是一種訓練工具。"},{"en":"A training tool is something used to help people practise and improve a skill.","zh":"training tool 指用來幫助人練習和改善技能的事物。"},{"en":"A driving simulator can be a training tool for new drivers.","zh":"駕駛模擬器可以是新司機的訓練工具。"},{"en":"Training tools are useful when real practice is expensive, dangerous, or difficult to arrange.","zh":"當真實練習昂貴、危險或難以安排時，訓練工具很有用。"},{"en":"This phrase shows that an object or activity has practical learning value.","zh":"這個短語顯示某物或活動具有實際學習價值。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":8},{"front":"real-world situations","meaning":"現實世界情境","examples":[{"en":"Games may train players for real-world situations.","zh":"遊戲可能訓練玩家應對現實世界情境。"},{"en":"Real-world situations are actual situations people face outside games, classrooms, or simulations.","zh":"real-world situations 指人們在遊戲、課室或模擬以外面對的真實情況。"},{"en":"First-aid lessons prepare students for real-world situations such as injuries or emergencies.","zh":"急救課程讓學生準備應對受傷或緊急事件等現實世界情境。"},{"en":"Training is more useful when it connects practice with real-world situations.","zh":"當訓練把練習與現實世界情境連接起來時，會更有用。"},{"en":"This phrase contrasts practice or theory with everyday reality.","zh":"這個短語把練習或理論與日常現實作對比。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":8},{"front":"prime the brain to","meaning":"使大腦準備好去……","examples":[{"en":"Action video games prime the brain to make quick decisions.","zh":"動作電子遊戲使大腦準備好作出快速決定。"},{"en":"To prime the brain to do something means to prepare it to respond in a certain way.","zh":"prime the brain to do something 指使大腦準備以某種方式反應。"},{"en":"A warm-up activity can prime the brain to focus before a lesson.","zh":"熱身活動可以在上課前使大腦準備好專注。"},{"en":"Repeated fast tasks may prime the brain to notice movement more quickly.","zh":"反覆快速任務可能使大腦準備好更快注意到動作。"},{"en":"This phrase suggests preparation before an action happens.","zh":"這個短語表示行動發生前的準備。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":8},{"front":"make quick decisions","meaning":"作出快速決定","examples":[{"en":"Action games may help players make quick decisions.","zh":"動作遊戲可能幫助玩家作出快速決定。"},{"en":"To make quick decisions means to choose what to do in a short time.","zh":"make quick decisions 指在短時間內選擇要做甚麼。"},{"en":"A bus driver must make quick decisions when a pedestrian suddenly crosses the road.","zh":"當行人突然過馬路時，巴士司機必須作出快速決定。"},{"en":"Quick decisions can be useful in emergencies, but they still need accuracy.","zh":"快速決定在緊急情況中有用，但仍需要準確。"},{"en":"This phrase stresses speed in judgement or choice.","zh":"這個短語強調判斷或選擇的速度。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":8},{"front":"be used to train","meaning":"被用來訓練","examples":[{"en":"Video games can be used to train soldiers and surgeons.","zh":"電子遊戲可以被用來訓練士兵和外科醫生。"},{"en":"To be used to train someone means to serve as a method for teaching or practice.","zh":"be used to train someone 指作為教學或練習的方法。"},{"en":"Role-play can be used to train staff in customer service.","zh":"角色扮演可以被用來訓練員工的客戶服務。"},{"en":"Tools used for training should give feedback so learners can improve.","zh":"用於訓練的工具應提供回饋，讓學習者改善。"},{"en":"This phrase focuses on practical use for skill development.","zh":"這個短語聚焦於技能發展的實際用途。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":8},{"front":"soldiers and surgeons","meaning":"士兵和外科醫生","examples":[{"en":"Video games can train soldiers and surgeons.","zh":"電子遊戲可以訓練士兵和外科醫生。"},{"en":"Soldiers and surgeons are people whose work may require quick decisions, precision, and calmness under pressure.","zh":"soldiers and surgeons 指工作可能需要快速決策、精準和壓力下冷靜的人。"},{"en":"Soldiers may train for dangerous situations, while surgeons train for delicate operations.","zh":"士兵可能為危險情境受訓，而外科醫生則為精細手術受訓。"},{"en":"Both soldiers and surgeons can benefit from practice that improves attention and hand control.","zh":"士兵和外科醫生都可能受益於改善注意力和手部控制的練習。"},{"en":"This phrase links two high-pressure professions.","zh":"這個短語連接兩種高壓職業。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":8},{"front":"deal with immediate problems","meaning":"處理眼前問題","examples":[{"en":"Gamers must deal with immediate problems.","zh":"玩家必須處理眼前問題。"},{"en":"To deal with immediate problems means to handle urgent issues that need attention now.","zh":"deal with immediate problems 指處理現在需要注意的緊急問題。"},{"en":"A teacher must deal with immediate problems when a student suddenly feels sick.","zh":"當學生突然不舒服時，老師必須處理眼前問題。"},{"en":"If immediate problems are ignored, they may quickly become more serious.","zh":"如果眼前問題被忽視，它們可能很快變得更嚴重。"},{"en":"This phrase focuses on short-term action, not distant planning.","zh":"這個短語聚焦短期行動，而不是遙遠計劃。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":9},{"front":"keep long-term goals in mind","meaning":"把長遠目標記在心中","examples":[{"en":"Gamers keep their long-term goals in mind while solving immediate problems.","zh":"玩家在解決眼前問題時，把長遠目標記在心中。"},{"en":"To keep long-term goals in mind means to remember future aims while making present choices.","zh":"keep long-term goals in mind 指在作眼前選擇時記住未來目標。"},{"en":"A student should keep long-term goals in mind when choosing daily study habits.","zh":"學生選擇每日學習習慣時，應把長遠目標記在心中。"},{"en":"People who forget long-term goals may make quick choices that hurt future success.","zh":"忘記長遠目標的人可能作出傷害未來成功的快速選擇。"},{"en":"This phrase connects short-term action with future planning.","zh":"這個短語把短期行動與未來規劃連接起來。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":9},{"front":"force oneself to","meaning":"迫使自己去……","examples":[{"en":"Young gamers force themselves to read game instructions.","zh":"年輕玩家迫使自己閱讀遊戲指示。"},{"en":"To force oneself to do something means to make oneself do it even when it feels difficult or boring.","zh":"force oneself to do something 指即使感到困難或沉悶，也讓自己去做某事。"},{"en":"A tired student may force herself to review notes before an exam.","zh":"疲倦的學生可能迫使自己在考試前溫習筆記。"},{"en":"People often force themselves to start a task because motivation may come later.","zh":"人們常迫使自己開始任務，因為動力可能之後才出現。"},{"en":"This phrase shows self-discipline under resistance.","zh":"這個短語顯示在抗拒下的自律。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":9},{"front":"get instructions","meaning":"取得指示","examples":[{"en":"Players read to get instructions from the game.","zh":"玩家閱讀以從遊戲取得指示。"},{"en":"To get instructions means to receive directions about what to do.","zh":"get instructions 指取得關於要做甚麼的指引。"},{"en":"A customer may get instructions from a staff member before using a self-service machine.","zh":"顧客在使用自助機前，可能從職員取得指示。"},{"en":"Clear instructions prevent confusion and help people complete tasks correctly.","zh":"清楚指示可以防止混亂，並幫助人正確完成任務。"},{"en":"This phrase focuses on receiving guidance.","zh":"這個短語聚焦取得指引。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":9},{"front":"follow storylines","meaning":"跟隨故事線","examples":[{"en":"Gamers read to follow storylines.","zh":"玩家閱讀以跟隨故事線。"},{"en":"To follow storylines means to understand how the events in a story develop.","zh":"follow storylines 指理解故事事件如何發展。"},{"en":"Viewers follow storylines in a drama by remembering characters and conflicts.","zh":"觀眾透過記住角色和衝突來跟隨劇集故事線。"},{"en":"If a storyline is confusing, players may not know why their next task matters.","zh":"如果故事線混亂，玩家可能不知道下一個任務為何重要。"},{"en":"This phrase connects reading or watching with understanding narrative development.","zh":"這個短語把閱讀或觀看與理解敘事發展連接起來。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":9},{"front":"game texts","meaning":"遊戲文字","examples":[{"en":"Players get information from game texts.","zh":"玩家從遊戲文字中取得資料。"},{"en":"Game texts are written words inside a game, such as instructions, dialogue, menus, and story notes.","zh":"game texts 指遊戲內的文字，例如指示、對話、選單和故事筆記。"},{"en":"A player may read game texts to learn where to go next.","zh":"玩家可能閱讀遊戲文字，以知道下一步去哪裡。"},{"en":"Clear game texts help players understand rules and avoid repeated mistakes.","zh":"清楚的遊戲文字幫助玩家理解規則並避免重複錯誤。"},{"en":"This phrase reminds us that games can involve reading.","zh":"這個短語提醒我們，遊戲也可以涉及閱讀。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":9},{"front":"similar to","meaning":"與……相似","examples":[{"en":"Playing a video game is similar to working through a science problem.","zh":"玩電子遊戲與逐步解決科學問題相似。"},{"en":"Similar to means like something else in some important ways.","zh":"similar to 指在某些重要方面像另一事物。"},{"en":"Learning to drive is similar to learning a sport because both require practice and feedback.","zh":"學習駕駛與學習運動相似，因為兩者都需要練習和回饋。"},{"en":"When two activities are similar, skills from one may help with the other.","zh":"當兩項活動相似，來自其中一項的技能可能幫助另一項。"},{"en":"This phrase is used to compare two things without saying they are exactly the same.","zh":"這個短語用來比較兩件事，但不表示它們完全一樣。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":9},{"front":"work through a science problem","meaning":"逐步解決科學問題","examples":[{"en":"Gamers work through problems like students in a science laboratory.","zh":"玩家逐步解決問題，就像實驗室裏的學生一樣。"},{"en":"To work through a science problem means to test ideas step by step until an explanation or solution is found.","zh":"work through a science problem 指一步一步測試想法，直到找到解釋或解決方法。"},{"en":"Students work through a science problem when they form a hypothesis and check it with evidence.","zh":"學生提出假設並用證據檢查時，就是逐步解決科學問題。"},{"en":"If the first answer fails, they change the method and try again.","zh":"如果第一個答案失敗，他們會改變方法並再試。"},{"en":"This phrase stresses process, testing, and correction.","zh":"這個短語強調過程、測試和修正。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":9},{"front":"students in a laboratory","meaning":"實驗室裏的學生","examples":[{"en":"Gamers behave like students in a laboratory.","zh":"玩家表現得像實驗室裏的學生。"},{"en":"Students in a laboratory learn by observing, testing, recording, and adjusting their ideas.","zh":"students in a laboratory 透過觀察、測試、記錄和調整想法來學習。"},{"en":"Students in a laboratory must follow safety rules before using equipment.","zh":"實驗室裏的學生在使用設備前必須遵守安全規則。"},{"en":"Laboratory work teaches careful thinking because results may disprove the first idea.","zh":"實驗室工作教授仔細思考，因為結果可能推翻最初想法。"},{"en":"This phrase suggests active experiment-based learning.","zh":"這個短語暗示以實驗為基礎的主動學習。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":9},{"front":"come up with a hypothesis","meaning":"提出假設","examples":[{"en":"Gamers must come up with a hypothesis.","zh":"玩家必須提出假設。"},{"en":"To come up with a hypothesis means to suggest a possible explanation or solution that can be tested.","zh":"come up with a hypothesis 指提出可被測試的可能解釋或解決方法。"},{"en":"A student may come up with a hypothesis about why a plant stopped growing.","zh":"學生可能提出假設，解釋植物為何停止生長。"},{"en":"If evidence does not support the hypothesis, the student must change it.","zh":"如果證據不支持該假設，學生必須改變它。"},{"en":"This phrase is useful when people make a testable guess.","zh":"當人們作出可測試的猜想時，這個短語很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":9},{"front":"try out combinations of","meaning":"試驗……的組合","examples":[{"en":"Players try out combinations of weapons and powers.","zh":"玩家試驗武器和能力的組合。"},{"en":"To try out combinations of things means to test different mixes to see which works best.","zh":"try out combinations of things 指測試不同配搭，看看哪一種效果最好。"},{"en":"A cook may try out combinations of spices before choosing a final recipe.","zh":"廚師可能試驗不同香料的組合，然後選定最終食譜。"},{"en":"Testing combinations helps people learn through trial, failure, and adjustment.","zh":"測試組合幫助人透過嘗試、失敗和調整來學習。"},{"en":"This phrase is useful when several choices can be mixed together.","zh":"當幾種選擇可以混合使用時，這個短語很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":9},{"front":"weapons and powers","meaning":"武器和能力","examples":[{"en":"Players test different weapons and powers to defeat enemies.","zh":"玩家測試不同武器和能力來打敗敵人。"},{"en":"Weapons and powers are tools, abilities, or special strengths used by characters in a game.","zh":"weapons and powers 指遊戲角色使用的工具、能力或特殊力量。"},{"en":"A player may choose long-range weapons and healing powers for a difficult level.","zh":"玩家可能為困難關卡選擇遠程武器和治療能力。"},{"en":"Different weapons and powers create different strategies and results.","zh":"不同武器和能力會產生不同策略和結果。"},{"en":"This phrase belongs mainly to game, fantasy, or action contexts.","zh":"這個短語主要屬於遊戲、奇幻或動作語境。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":10},{"front":"defeat an enemy","meaning":"打敗敵人","examples":[{"en":"Players change their strategy to defeat an enemy.","zh":"玩家改變策略來打敗敵人。"},{"en":"To defeat an enemy means to win against an opponent or threat.","zh":"defeat an enemy 指戰勝對手或威脅。"},{"en":"In a board game, a player may defeat an enemy by planning several moves ahead.","zh":"在桌上遊戲中，玩家可能透過提前計劃幾步來打敗敵人。"},{"en":"If one method fails to defeat an enemy, the player must try another strategy.","zh":"如果一種方法不能打敗敵人，玩家必須嘗試另一種策略。"},{"en":"This phrase can be literal in war or figurative in games and stories.","zh":"這個短語可用於真實戰爭，也可比喻用於遊戲和故事。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":10},{"front":"change their hypothesis","meaning":"改變假設","examples":[{"en":"If one strategy fails, players change their hypothesis.","zh":"如果一種策略失敗，玩家會改變假設。"},{"en":"To change their hypothesis means to replace an earlier guess with a better one after new evidence appears.","zh":"change their hypothesis 指在新證據出現後，用更好的假設取代早前猜想。"},{"en":"Students change their hypothesis when an experiment gives unexpected results.","zh":"當實驗產生意外結果時，學生會改變假設。"},{"en":"Changing a hypothesis is part of learning because mistakes reveal better explanations.","zh":"改變假設是學習的一部分，因為錯誤會揭示更好的解釋。"},{"en":"This phrase shows flexible thinking rather than stubborn guessing.","zh":"這個短語顯示靈活思考，而不是固執猜測。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":10},{"front":"goal-driven experiences","meaning":"以目標為導向的經驗","examples":[{"en":"Video games are goal-driven experiences.","zh":"電子遊戲是以目標為導向的經驗。"},{"en":"Goal-driven experiences are activities organised around clear aims that people try to reach.","zh":"goal-driven experiences 指圍繞清晰目標而組織、讓人努力達成的活動經驗。"},{"en":"A school project is a goal-driven experience when students must design a working model by Friday.","zh":"如果學生必須在星期五前設計出可運作模型，學校項目就是以目標為導向的經驗。"},{"en":"Clear goals make people focus their effort and measure progress.","zh":"清晰目標令人集中努力並衡量進展。"},{"en":"This phrase shows that activity is guided by purpose.","zh":"這個短語顯示活動受目的引導。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":10},{"front":"fundamental to learning","meaning":"對學習至關重要","examples":[{"en":"Goal-driven experiences are fundamental to learning.","zh":"以目標為導向的經驗對學習至關重要。"},{"en":"Fundamental to learning means essential or very important for learning to happen.","zh":"fundamental to learning 指對學習發生而言必不可少或非常重要。"},{"en":"Practice and feedback are fundamental to learning a musical instrument.","zh":"練習和回饋對學習樂器至關重要。"},{"en":"If curiosity is missing, deep learning may become harder because students only memorise.","zh":"如果缺乏好奇心，深入學習可能更困難，因為學生只會背誦。"},{"en":"This phrase identifies something as a basic part of the learning process.","zh":"這個短語指出某事是學習過程的基本部分。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":10},{"front":"mathematical skills","meaning":"數學技能","examples":[{"en":"Mathematical skills are important for success in many games.","zh":"數學技能對許多遊戲中的成功很重要。"},{"en":"Mathematical skills are abilities involving numbers, patterns, measurement, logic, and calculation.","zh":"mathematical skills 指涉及數字、模式、測量、邏輯和計算的能力。"},{"en":"Shopping with a budget uses mathematical skills when people compare prices.","zh":"人們按預算購物並比較價格時，會使用數學技能。"},{"en":"Games can train mathematical skills when players count resources or calculate risks.","zh":"當玩家計算資源或風險時，遊戲可以訓練數學技能。"},{"en":"This phrase is broader than school arithmetic.","zh":"這個短語比學校算術更廣。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":10},{"front":"important for success","meaning":"對成功很重要","examples":[{"en":"Resource management is important for success in many games.","zh":"資源管理對許多遊戲中的成功很重要。"},{"en":"Important for success means necessary or helpful for achieving a goal.","zh":"important for success 指對達成目標而言必要或有幫助。"},{"en":"Clear communication is important for success in group projects.","zh":"清楚溝通對小組項目的成功很重要。"},{"en":"If an ability is important for success, ignoring it may lead to failure.","zh":"如果一項能力對成功很重要，忽視它可能導致失敗。"},{"en":"This phrase links a skill or factor with achievement.","zh":"這個短語把技能或因素與成就連接起來。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":10},{"front":"involve quantitative analysis","meaning":"涉及定量分析","examples":[{"en":"Some games involve quantitative analysis.","zh":"有些遊戲涉及定量分析。"},{"en":"To involve quantitative analysis means to require thinking with numbers, amounts, and measurable data.","zh":"involve quantitative analysis 指需要用數字、數量和可測量資料來思考。"},{"en":"A shop owner uses quantitative analysis when comparing monthly sales figures.","zh":"店主比較每月銷售數字時，會使用定量分析。"},{"en":"Games involve quantitative analysis when players calculate costs, points, risks, or resources.","zh":"當玩家計算成本、分數、風險或資源時，遊戲就涉及定量分析。"},{"en":"This phrase is formal and often used in academic or business contexts.","zh":"這個短語較正式，常用於學術或商業語境。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":10},{"front":"managing resources","meaning":"管理資源","examples":[{"en":"Managing resources can require mathematical thinking.","zh":"管理資源可能需要數學思維。"},{"en":"Managing resources means controlling and using limited things such as time, money, tools, or energy wisely.","zh":"managing resources 指明智地控制和使用時間、金錢、工具或精力等有限事物。"},{"en":"A family manages resources when it plans food spending for the week.","zh":"家庭計劃一星期食物開支時，就是在管理資源。"},{"en":"Poor resource management can cause shortages before the goal is reached.","zh":"資源管理不善可能在目標達成前造成短缺。"},{"en":"This phrase is useful in games, business, home life, and public planning.","zh":"這個短語在遊戲、商業、家庭生活和公共規劃中都有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":10},{"front":"higher levels of a game","meaning":"遊戲的較高關卡","examples":[{"en":"Players often fail when they first reach higher levels of a game.","zh":"玩家第一次到達遊戲較高關卡時常會失敗。"},{"en":"Higher levels of a game are more difficult stages that players reach after earlier success.","zh":"higher levels of a game 指玩家在早前成功後到達的較困難階段。"},{"en":"In higher levels of a game, enemies may move faster and resources may be fewer.","zh":"在遊戲較高關卡中，敵人可能移動更快，資源可能更少。"},{"en":"Higher levels force players to improve because old strategies may no longer work.","zh":"較高關卡迫使玩家進步，因為舊策略可能不再有效。"},{"en":"This phrase shows increasing difficulty and progress.","zh":"這個短語顯示難度增加和進展。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":10},{"front":"first time around","meaning":"第一次嘗試時","examples":[{"en":"Players usually fail the first time around.","zh":"玩家通常第一次嘗試時會失敗。"},{"en":"First time around means on the first attempt or the first occasion.","zh":"first time around 指第一次嘗試或第一次出現時。"},{"en":"A student may not understand a grammar rule the first time around.","zh":"學生第一次接觸文法規則時可能未能理解。"},{"en":"Failure the first time around can show what needs to be changed next.","zh":"第一次嘗試時失敗可以顯示下一次需要改變甚麼。"},{"en":"This phrase makes failure sound like part of a repeated process.","zh":"這個短語把失敗呈現為重複過程的一部分。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":10},{"front":"keep on trying until","meaning":"不斷嘗試直到","examples":[{"en":"Players keep on trying until they succeed.","zh":"玩家不斷嘗試直到成功。"},{"en":"To keep on trying until something happens means to continue making attempts until the goal is reached.","zh":"keep on trying until something happens 指持續嘗試直到目標達成。"},{"en":"A child learning to ride a bicycle may keep on trying until she can balance.","zh":"學騎單車的孩子可能不斷嘗試，直到能保持平衡。"},{"en":"Repeated attempts help people learn from mistakes and build confidence.","zh":"反覆嘗試幫助人從錯誤中學習並建立信心。"},{"en":"This phrase shows persistence over time.","zh":"這個短語顯示持續不懈。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":11},{"front":"move on to","meaning":"進入；轉到","examples":[{"en":"Successful players move on to the next level.","zh":"成功的玩家會進入下一關。"},{"en":"To move on to something means to leave one stage and begin the next one.","zh":"move on to something 指離開一個階段並開始下一個階段。"},{"en":"After finishing basic vocabulary, students can move on to longer reading passages.","zh":"完成基礎詞彙後，學生可以轉到較長閱讀文章。"},{"en":"People move on to harder tasks when they have mastered easier ones.","zh":"當人們掌握較容易任務後，就會進入較困難任務。"},{"en":"This phrase shows progress from one step to another.","zh":"這個短語顯示從一步進展到另一步。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":11},{"front":"be played online","meaning":"在網上進行","examples":[{"en":"Many games are played online.","zh":"許多遊戲在網上進行。"},{"en":"To be played online means to be played through the internet, often with other people.","zh":"be played online 指透過互聯網進行遊戲，常與其他人一起玩。"},{"en":"Chess can be played online with friends in another country.","zh":"國際象棋可以在網上與另一個國家的朋友對弈。"},{"en":"Online play allows cooperation and competition even when players are far apart.","zh":"網上遊玩讓相隔很遠的玩家也能合作和競爭。"},{"en":"This phrase describes the platform or method of playing.","zh":"這個短語描述遊玩的平台或方式。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":11},{"front":"involve cooperation with","meaning":"涉及與……合作","examples":[{"en":"Online games involve cooperation with other players.","zh":"網上遊戲涉及與其他玩家合作。"},{"en":"To involve cooperation with someone means to require people to work together.","zh":"involve cooperation with someone 指需要人們一起合作。"},{"en":"A group project involves cooperation with classmates to finish the work on time.","zh":"小組項目涉及與同學合作，以準時完成工作。"},{"en":"Cooperation can help people share information, divide tasks, and solve harder problems.","zh":"合作可以幫助人分享資訊、分工並解決較難問題。"},{"en":"This phrase shows that success depends on teamwork.","zh":"這個短語顯示成功取決於團隊合作。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":11},{"front":"in order to win","meaning":"為了取勝","examples":[{"en":"Players often cooperate in order to win.","zh":"玩家常為了取勝而合作。"},{"en":"In order to win means for the purpose of achieving victory.","zh":"in order to win 指以取得勝利為目的。"},{"en":"A debate team must organise its arguments carefully in order to win.","zh":"辯論隊為了取勝，必須仔細組織論點。"},{"en":"If people want to win together, they may need to communicate and trust one another.","zh":"如果人們想一起取勝，可能需要溝通並信任彼此。"},{"en":"This phrase clearly states the purpose behind an action.","zh":"這個短語清楚說明行動背後的目的。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":11},{"front":"gain self-confidence","meaning":"建立自信","examples":[{"en":"Video games help children gain self-confidence.","zh":"電子遊戲幫助兒童建立自信。"},{"en":"To gain self-confidence means to become more willing to trust one’s own ability.","zh":"gain self-confidence 指變得更願意相信自己的能力。"},{"en":"A shy student may gain self-confidence after giving several short presentations.","zh":"害羞的學生在做過幾次短匯報後，可能建立自信。"},{"en":"Success after repeated failure can help children believe they can improve.","zh":"反覆失敗後取得成功，可以幫助孩子相信自己能進步。"},{"en":"This phrase shows growth in belief, not just improvement in skill.","zh":"這個短語顯示信念上的成長，而不只是技能提升。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":11},{"front":"be based on","meaning":"以……為基礎","examples":[{"en":"Many games are based on history, city-building and governance.","zh":"許多遊戲以歷史、城市建設和治理為基礎。"},{"en":"To be based on something means to use it as the foundation or main idea.","zh":"be based on something 指以某事作為基礎或主要想法。"},{"en":"A film may be based on a true story.","zh":"電影可能以真實故事為基礎。"},{"en":"When a game is based on history, players may learn facts indirectly while playing.","zh":"當遊戲以歷史為基礎，玩家可能在遊玩中間接學習事實。"},{"en":"This phrase shows where an idea, story, or design comes from.","zh":"這個短語顯示想法、故事或設計來自哪裡。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":11},{"front":"history, city-building and governance","meaning":"歷史、城市建設和治理","examples":[{"en":"Some games teach history, city-building and governance indirectly.","zh":"有些遊戲間接教授歷史、城市建設和治理。"},{"en":"History, city-building and governance refer to past events, urban development, and the management of society.","zh":"history, city-building and governance 指過去事件、城市發展和社會管理。"},{"en":"A game about an ancient empire may include history, city-building and governance.","zh":"關於古代帝國的遊戲可能包含歷史、城市建設和治理。"},{"en":"These topics can teach players how decisions affect people, resources, and public order.","zh":"這些主題可以教玩家決策如何影響人民、資源和公共秩序。"},{"en":"This phrase combines learning about the past with managing communities.","zh":"這個短語結合對過去的學習和社群管理。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":11},{"front":"indirectly teach","meaning":"間接教授","examples":[{"en":"Some games indirectly teach children about life on Earth.","zh":"有些遊戲間接教授兒童有關地球生活的知識。"},{"en":"To indirectly teach something means to help people learn it without teaching it openly or directly.","zh":"indirectly teach something 指不明確或直接教學，但幫助人學會某事。"},{"en":"A story about sharing can indirectly teach children kindness.","zh":"關於分享的故事可以間接教授孩子善良。"},{"en":"Games indirectly teach skills when players learn through goals, rules, and consequences.","zh":"當玩家透過目標、規則和後果學習時，遊戲就在間接教授技能。"},{"en":"This phrase shows learning that happens through experience.","zh":"這個短語顯示透過經驗發生的學習。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":11},{"front":"aspects of life on Earth","meaning":"地球生活的不同方面","examples":[{"en":"Games can teach children about different aspects of life on Earth.","zh":"遊戲可以教兒童認識地球生活的不同方面。"},{"en":"Aspects of life on Earth are different parts of human, social, natural, or cultural life.","zh":"aspects of life on Earth 指人類、社會、自然或文化生活的不同部分。"},{"en":"Documentaries teach aspects of life on Earth such as animals, weather, cities, and farming.","zh":"紀錄片教授地球生活的不同方面，例如動物、天氣、城市和農業。"},{"en":"Games may show how food, trade, housing, and government affect people’s lives.","zh":"遊戲可能展示食物、貿易、住房和政府如何影響人們生活。"},{"en":"This phrase is broad and covers many areas of real life.","zh":"這個短語很廣，涵蓋現實生活的許多範疇。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":11},{"front":"upcoming study","meaning":"即將發表的研究","examples":[{"en":"An upcoming study reports that games can speed up reactions.","zh":"一項即將發表的研究報告指遊戲可以加快反應。"},{"en":"An upcoming study is research that will be published or released soon.","zh":"upcoming study 指很快會出版或發布的研究。"},{"en":"A university may announce an upcoming study on sleep and exam performance.","zh":"大學可能公布一項關於睡眠和考試表現的即將發表研究。"},{"en":"Upcoming studies can attract attention before all details are available.","zh":"即將發表的研究可以在所有細節公開前吸引注意。"},{"en":"This phrase points to research that is expected but not yet fully public.","zh":"這個短語指預期會出現但尚未完全公開的研究。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":11},{"front":"provide a potent training regimen","meaning":"提供強效訓練方案","examples":[{"en":"Video games could provide a potent training regimen.","zh":"電子遊戲可以提供強效訓練方案。"},{"en":"To provide a potent training regimen means to offer a strong and effective programme of practice.","zh":"provide a potent training regimen 指提供強而有效的練習計劃。"},{"en":"A coach may provide a potent training regimen to improve athletes’ speed and strength.","zh":"教練可能提供強效訓練方案，以改善運動員速度和力量。"},{"en":"A training regimen works best when it is repeated, challenging, and guided by feedback.","zh":"訓練方案在重複、有挑戰和有回饋時效果最好。"},{"en":"This phrase is formal and suggests powerful structured training.","zh":"這個短語較正式，表示有力而有結構的訓練。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":12},{"front":"speed up reactions","meaning":"加快反應","examples":[{"en":"Video games may help speed up reactions.","zh":"電子遊戲可能幫助加快反應。"},{"en":"To speed up reactions means to make responses faster.","zh":"speed up reactions 指令反應變得更快。"},{"en":"Sports drills can speed up reactions when players practise responding to sudden movements.","zh":"當球員練習應對突然動作時，運動訓練可以加快反應。"},{"en":"Faster reactions can help in driving, sports, games, and emergency situations.","zh":"更快反應可以在駕駛、運動、遊戲和緊急情況中有幫助。"},{"en":"This phrase focuses on reducing the time between seeing something and responding.","zh":"這個短語聚焦縮短看到事情與作出反應之間的時間。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":12},{"front":"real-life situations","meaning":"現實生活情境","examples":[{"en":"Games may improve reactions in many types of real-life situations.","zh":"遊戲可能改善人在許多現實生活情境中的反應。"},{"en":"Real-life situations are actual events or problems people face outside practice or entertainment.","zh":"real-life situations 指人們在練習或娛樂以外面對的真實事件或問題。"},{"en":"Fire drills prepare students for real-life situations involving danger.","zh":"消防演習讓學生準備應對涉及危險的現實生活情境。"},{"en":"Skills are more valuable when they can transfer to real-life situations.","zh":"當技能能轉移到現實生活情境中，它們就更有價值。"},{"en":"This phrase contrasts real experience with games, tests, or simulations.","zh":"這個短語把真實經驗與遊戲、測驗或模擬作對比。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":12},{"front":"test dozens of","meaning":"測試數十名","examples":[{"en":"The researchers tested dozens of young adults.","zh":"研究人員測試了數十名年輕成年人。"},{"en":"To test dozens of people means to examine many people, usually more than twenty but not an exact number.","zh":"test dozens of people 指測試許多人，通常超過二十人，但不是精確數字。"},{"en":"A clinic may test dozens of patients during a health screening day.","zh":"診所可能在健康檢查日測試數十名病人。"},{"en":"Testing dozens of people can give researchers more reliable patterns than testing only one or two.","zh":"測試數十人比只測試一兩人更能給研究人員可靠模式。"},{"en":"This phrase gives a general sense of sample size.","zh":"這個短語提供樣本大小的大概感覺。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":12},{"front":"18- to 25-year-olds","meaning":"18至25歲人士","examples":[{"en":"The study tested 18- to 25-year-olds.","zh":"這項研究測試了18至25歲人士。"},{"en":"18- to 25-year-olds are people aged between eighteen and twenty-five.","zh":"18- to 25-year-olds 指年齡介乎18至25歲的人。"},{"en":"A survey of 18- to 25-year-olds may focus on university, work, or technology habits.","zh":"對18至25歲人士的調查可能聚焦大學、工作或科技習慣。"},{"en":"Researchers choose this age group when they want young adult participants.","zh":"研究人員想找年輕成年受試者時，會選擇這個年齡組別。"},{"en":"This phrase identifies the age range of the subjects.","zh":"這個短語指出受試者的年齡範圍。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":12},{"front":"not ordinarily","meaning":"平時並不","examples":[{"en":"The subjects were not ordinarily video game players.","zh":"受試者平時並不是電子遊戲玩家。"},{"en":"Not ordinarily means not usually or not in normal circumstances.","zh":"not ordinarily 指通常不是或在正常情況下不是。"},{"en":"She does not ordinarily drink coffee, but she did during exam week.","zh":"她平時並不喝咖啡，但考試週喝了。"},{"en":"If participants are not ordinarily gamers, improvements after training may be easier to measure.","zh":"如果參與者平時並不是玩家，訓練後的改善可能更容易測量。"},{"en":"This phrase describes what is normally true before an exception.","zh":"這個短語描述在例外之前通常成立的情況。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":12},{"front":"split the subjects into","meaning":"將受試者分成","examples":[{"en":"The researchers split the subjects into two groups.","zh":"研究人員將受試者分成兩組。"},{"en":"To split the subjects into groups means to divide participants into separate groups for study or comparison.","zh":"split the subjects into groups 指把參與者分成不同組別作研究或比較。"},{"en":"A teacher may split the students into groups for a classroom experiment.","zh":"老師可能把學生分成幾組，進行課堂實驗。"},{"en":"Splitting subjects into groups helps researchers compare different treatments or activities.","zh":"將受試者分組有助研究人員比較不同處理方式或活動。"},{"en":"This phrase is common in experimental research.","zh":"這個短語常見於實驗研究。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":12},{"front":"fast-paced action video games","meaning":"節奏快的動作電子遊戲","examples":[{"en":"One group played fast-paced action video games.","zh":"其中一組玩節奏快的動作電子遊戲。"},{"en":"Fast-paced action video games are games with quick movement, rapid events, and constant decisions.","zh":"fast-paced action video games 指包含快速移動、迅速事件和持續決策的遊戲。"},{"en":"A fast-paced action game may require players to dodge attacks and aim quickly.","zh":"節奏快的動作遊戲可能要求玩家閃避攻擊並快速瞄準。"},{"en":"Such games can train attention because players must respond before the situation changes.","zh":"這類遊戲可以訓練注意力，因為玩家必須在情況改變前反應。"},{"en":"This phrase contrasts with slow or relaxed games.","zh":"這個短語與緩慢或輕鬆的遊戲形成對比。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":12},{"front":"slow-moving strategy game","meaning":"節奏慢的策略遊戲","examples":[{"en":"The other group played a slow-moving strategy game.","zh":"另一組玩節奏慢的策略遊戲。"},{"en":"A slow-moving strategy game is a game that allows more time for planning and decisions.","zh":"slow-moving strategy game 指讓玩家有更多時間計劃和作決定的遊戲。"},{"en":"A slow-moving strategy game may ask players to build cities or manage resources carefully.","zh":"節奏慢的策略遊戲可能要求玩家建設城市或仔細管理資源。"},{"en":"Because the pace is slower, players may think deeply rather than react instantly.","zh":"由於節奏較慢，玩家可能深入思考，而不是即時反應。"},{"en":"This phrase contrasts with fast action games.","zh":"這個短語與快速動作遊戲形成對比。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":12},{"front":"training period","meaning":"訓練期","examples":[{"en":"After the training period, the subjects completed decision-making tasks.","zh":"訓練期後，受試者完成決策任務。"},{"en":"A training period is a set time used for practice before testing or real work.","zh":"training period 指在測試或正式工作前用於練習的一段固定時間。"},{"en":"New employees may have a training period before serving customers alone.","zh":"新員工在獨自服務顧客前，可能有一段訓練期。"},{"en":"A clear training period helps people build skills gradually.","zh":"清楚的訓練期幫助人逐步建立技能。"},{"en":"This phrase focuses on the time spent practising.","zh":"這個短語聚焦花在練習上的時間。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":12},{"front":"quick decisions","meaning":"快速決定","examples":[{"en":"The subjects were asked to make quick decisions.","zh":"受試者被要求作出快速決定。"},{"en":"Quick decisions are choices made in a short amount of time.","zh":"quick decisions 指在短時間內作出的選擇。"},{"en":"A lifeguard must make quick decisions when someone is struggling in water.","zh":"當有人在水中掙扎時，救生員必須作出快速決定。"},{"en":"Quick decisions are useful only when speed does not destroy accuracy.","zh":"快速決定只有在速度不破壞準確性時才有用。"},{"en":"This phrase is common in discussions of reaction, pressure, and judgement.","zh":"這個短語常見於關於反應、壓力和判斷的討論。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":12},{"front":"tasks designed by","meaning":"由……設計的任務","examples":[{"en":"The subjects completed tasks designed by the researchers.","zh":"受試者完成由研究人員設計的任務。"},{"en":"Tasks designed by someone are activities created or planned by that person for a purpose.","zh":"tasks designed by someone 指由某人為特定目的創造或計劃的活動。"},{"en":"Students completed tasks designed by their teacher to practise listening skills.","zh":"學生完成由老師設計的任務，以練習聆聽技能。"},{"en":"Well-designed tasks can measure a skill more accurately.","zh":"設計良好的任務可以更準確地測量技能。"},{"en":"This phrase identifies who created the activity.","zh":"這個短語指出活動由誰創造。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":13},{"front":"up to 25 percent faster","meaning":"快多達百分之二十五","examples":[{"en":"Action-game players were up to 25 percent faster at reaching conclusions.","zh":"動作遊戲玩家得出結論的速度快多達百分之二十五。"},{"en":"Up to 25 percent faster means as much as one quarter quicker, depending on the case.","zh":"up to 25 percent faster 指視乎情況，最快可快四分之一。"},{"en":"A new bus route may make the journey up to 25 percent faster.","zh":"新巴士路線可能令旅程快多達百分之二十五。"},{"en":"If a group is up to 25 percent faster, the biggest improvement reaches that level.","zh":"如果一組人快多達百分之二十五，最大改善幅度達到這個水平。"},{"en":"This phrase gives a maximum improvement, not always the average.","zh":"這個短語表示最高改善幅度，不一定是平均值。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":13},{"front":"come to a conclusion","meaning":"得出結論","examples":[{"en":"Action-game players came to a conclusion more quickly.","zh":"動作遊戲玩家更快得出結論。"},{"en":"To come to a conclusion means to decide what one believes after thinking about information.","zh":"come to a conclusion 指思考資料後決定自己的看法。"},{"en":"A doctor comes to a conclusion after checking symptoms and test results.","zh":"醫生檢查症狀和測試結果後得出結論。"},{"en":"Good conclusions should be based on evidence, not just speed.","zh":"良好結論應基於證據，而不只是速度。"},{"en":"This phrase focuses on reaching a final judgement.","zh":"這個短語聚焦達成最終判斷。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":13},{"front":"just as many questions correctly as","meaning":"正確回答的題數與……一樣多","examples":[{"en":"Action-game players answered just as many questions correctly as their peers.","zh":"動作遊戲玩家正確回答的題數與同儕一樣多。"},{"en":"Just as many questions correctly as means the number of correct answers was equal to another group’s number.","zh":"just as many questions correctly as 指正確答案數量與另一組相等。"},{"en":"A student may answer just as many questions correctly as a classmate, even if she works faster.","zh":"一名學生即使做得更快，也可能正確回答的題數與同學一樣多。"},{"en":"This phrase shows that speed did not reduce accuracy.","zh":"這個短語顯示速度沒有降低準確度。"},{"en":"It is useful when comparing performance between two groups.","zh":"比較兩組表現時，這個短語很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":13},{"front":"strategy-game-playing peers","meaning":"玩策略遊戲的同儕","examples":[{"en":"The action players were compared with their strategy-game-playing peers.","zh":"動作遊戲玩家與玩策略遊戲的同儕作比較。"},{"en":"Strategy-game-playing peers are people of a similar group who played strategy games.","zh":"strategy-game-playing peers 指同類群體中玩策略遊戲的人。"},{"en":"In a study, action-game players may be compared with strategy-game-playing peers to test differences.","zh":"在研究中，動作遊戲玩家可能與玩策略遊戲的同儕比較，以測試差異。"},{"en":"Comparing peers helps researchers reduce unfair differences between groups.","zh":"比較同儕有助研究人員減少組別之間的不公平差異。"},{"en":"This phrase identifies the comparison group.","zh":"這個短語指出比較組別。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":13},{"front":"main purpose","meaning":"主要目的","examples":[{"en":"The question asks about the main purpose of the first paragraph.","zh":"題目詢問第一段的主要目的。"},{"en":"Main purpose means the most important reason why a text, paragraph, or action exists.","zh":"main purpose 指一篇文本、段落或行動存在的最重要原因。"},{"en":"In reading tests, students identify the main purpose to understand why the writer includes a paragraph.","zh":"在閱讀測驗中，學生找出主要目的，以理解作者為何加入某段。"},{"en":"If students focus only on details, they may miss the main purpose.","zh":"如果學生只注意細節，可能會錯過主要目的。"},{"en":"This phrase is common in comprehension questions.","zh":"這個短語常見於閱讀理解問題。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":13},{"front":"introduction to","meaning":"對……的介紹","examples":[{"en":"The first paragraph gives an introduction to the background of the passage.","zh":"第一段提供對文章背景的介紹。"},{"en":"An introduction to something is an opening explanation that helps readers understand what follows.","zh":"introduction to something 指開首說明，幫助讀者理解接下來的內容。"},{"en":"A teacher may give an introduction to a new topic before students read the text.","zh":"老師可能在學生閱讀文本前，對新主題作介紹。"},{"en":"A good introduction prepares readers by giving context and direction.","zh":"好介紹透過提供背景和方向來準備讀者。"},{"en":"This phrase refers to the beginning part of an explanation.","zh":"這個短語指解釋的開首部分。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":13},{"front":"background of the passage","meaning":"文章背景","examples":[{"en":"The opening story provides the background of the passage.","zh":"開首故事提供文章背景。"},{"en":"The background of the passage is the context or situation that helps readers understand the main discussion.","zh":"background of the passage 指幫助讀者理解主要討論的上下文或情境。"},{"en":"A short story about a teacher can provide the background of a passage about education.","zh":"關於老師的短故事可以提供一篇教育文章的背景。"},{"en":"Without background, readers may not understand why the topic matters.","zh":"沒有背景，讀者可能不明白主題為何重要。"},{"en":"This phrase is useful in reading analysis.","zh":"這個短語在閱讀分析中很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":13},{"front":"wish to convey","meaning":"想傳達","examples":[{"en":"The author wishes to convey a balanced view of video games.","zh":"作者想傳達對電子遊戲的平衡看法。"},{"en":"To wish to convey something means to want to communicate an idea or message.","zh":"wish to convey something 指想傳達某個想法或訊息。"},{"en":"A speaker may wish to convey concern without sounding rude.","zh":"講者可能想傳達憂慮，但不想聽起來無禮。"},{"en":"Writers choose examples carefully because they affect the message they convey.","zh":"作者仔細選擇例子，因為例子會影響他們傳達的訊息。"},{"en":"This phrase focuses on the writer’s or speaker’s intended meaning.","zh":"這個短語聚焦作者或講者想表達的意思。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":13},{"front":"be widely considered harmful","meaning":"被廣泛視為有害","examples":[{"en":"Video games are widely considered harmful by some parents.","zh":"電子遊戲被一些家長廣泛視為有害。"},{"en":"To be widely considered harmful means many people believe something causes damage or danger.","zh":"be widely considered harmful 指許多人相信某事會造成傷害或危險。"},{"en":"Smoking is widely considered harmful because it damages health.","zh":"吸煙被廣泛視為有害，因為它損害健康。"},{"en":"If an activity is widely considered harmful, people may demand rules or restrictions.","zh":"如果一項活動被廣泛視為有害，人們可能要求規則或限制。"},{"en":"This phrase describes public belief, not necessarily final scientific proof.","zh":"這個短語描述公眾看法，不一定是最終科學證明。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":13},{"front":"direct cause of","meaning":"……的直接原因","examples":[{"en":"The option claims that video games are the direct cause of youth violence.","zh":"這個選項聲稱電子遊戲是青少年暴力的直接原因。"},{"en":"A direct cause of something is the factor that clearly produces that result.","zh":"direct cause of something 指明確產生某結果的因素。"},{"en":"A broken pipe may be the direct cause of water damage in a flat.","zh":"破裂水管可能是單位水浸損壞的直接原因。"},{"en":"Calling one factor the direct cause can be risky if many causes are involved.","zh":"如果涉及許多原因，把單一因素稱為直接原因可能有風險。"},{"en":"This phrase is stronger than saying something is related to a problem.","zh":"這個短語比說某事與問題有關更強。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":13},{"front":"juvenile delinquency","meaning":"青少年犯罪","examples":[{"en":"Some people wrongly link video games directly with juvenile delinquency.","zh":"有些人錯誤地把電子遊戲直接與青少年犯罪連繫起來。"},{"en":"Juvenile delinquency means criminal or seriously antisocial behaviour by young people.","zh":"juvenile delinquency 指年輕人的犯罪或嚴重反社會行為。"},{"en":"Truancy, theft, and vandalism can be discussed under juvenile delinquency.","zh":"逃學、偷竊和破壞公物可以放在青少年犯罪下討論。"},{"en":"Juvenile delinquency may have deeper causes such as family stress, poverty, or school failure.","zh":"青少年犯罪可能有更深層原因，例如家庭壓力、貧窮或學校失敗。"},{"en":"This phrase is formal and often used in law, education, or social policy.","zh":"這個短語較正式，常用於法律、教育或社會政策。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":14},{"front":"recognise their benefits","meaning":"承認其好處","examples":[{"en":"Scientists and psychologists recognise the benefits of video games.","zh":"科學家和心理學家承認電子遊戲的好處。"},{"en":"To recognise their benefits means to admit or understand that they have positive effects.","zh":"recognise their benefits 指承認或理解它們有正面影響。"},{"en":"Some teachers recognise the benefits of group work when shy students begin to speak more.","zh":"當害羞學生開始多說話時，有些老師會承認小組合作的好處。"},{"en":"Recognising benefits does not mean ignoring possible risks.","zh":"承認好處並不代表忽視可能風險。"},{"en":"This phrase is useful when discussing a balanced view.","zh":"討論平衡觀點時，這個短語很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":14},{"front":"intellectual abilities","meaning":"智力能力","examples":[{"en":"Video games may benefit children’s intellectual abilities.","zh":"電子遊戲可能有益於兒童的智力能力。"},{"en":"Intellectual abilities are mental abilities used for learning, reasoning, understanding, and solving problems.","zh":"intellectual abilities 指用於學習、推理、理解和解難的心智能力。"},{"en":"Reading, debate, and puzzles can develop intellectual abilities.","zh":"閱讀、辯論和謎題可以培養智力能力。"},{"en":"Children strengthen intellectual abilities when they face challenging tasks and receive feedback.","zh":"當孩子面對具挑戰任務並得到回饋，他們會強化智力能力。"},{"en":"This phrase refers to thinking power, not physical skill.","zh":"這個短語指思考能力，而不是身體技能。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":14},{"front":"regard something as","meaning":"將……視為","examples":[{"en":"Many parents regard video games as time-wasters.","zh":"許多家長將電子遊戲視為浪費時間的東西。"},{"en":"To regard something as something means to think of it in a particular way.","zh":"regard something as something 指以某種方式看待某事。"},{"en":"Some students regard mistakes as proof of failure, but teachers may see them as learning chances.","zh":"有些學生將錯誤視為失敗證明，但老師可能把它們看作學習機會。"},{"en":"How people regard an activity affects whether they allow, ban, or support it.","zh":"人們如何看待一項活動，會影響他們是允許、禁止還是支持它。"},{"en":"This phrase is useful for describing opinions or judgement.","zh":"這個短語適合描述看法或判斷。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":14},{"front":"statement is correct","meaning":"陳述是正確的","examples":[{"en":"Students must decide which statement is correct according to the passage.","zh":"學生必須根據文章判斷哪個陳述是正確的。"},{"en":"A statement is correct when it matches the information or evidence given.","zh":"statement is correct 指某陳述符合所給資料或證據。"},{"en":"In a reading test, a statement is correct only if the passage supports it.","zh":"在閱讀測驗中，只有文章支持時，陳述才是正確的。"},{"en":"Students should not choose an answer just because it sounds reasonable.","zh":"學生不應只因答案聽起來合理就選它。"},{"en":"This phrase is common in exam questions about accuracy.","zh":"這個短語常見於關於準確性的考試題目。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":14},{"front":"according to","meaning":"根據","examples":[{"en":"The correct answer should be chosen according to the fourth paragraph.","zh":"正確答案應根據第四段選出。"},{"en":"According to means based on what a source says.","zh":"according to 指基於某個來源所說。"},{"en":"According to the timetable, the train leaves at eight o’clock.","zh":"根據時間表，火車八點開出。"},{"en":"In exams, according to the passage means students must use the text, not outside knowledge.","zh":"在考試中，according to the passage 表示學生必須使用文章，而不是外部知識。"},{"en":"This phrase identifies the source of information.","zh":"這個短語指出資訊來源。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":14},{"front":"various aspects of","meaning":"……的各個方面","examples":[{"en":"Video games may improve various aspects of the brain’s abilities.","zh":"電子遊戲可能改善大腦能力的各個方面。"},{"en":"Various aspects of something are different parts or features of it.","zh":"various aspects of something 指某事物的不同部分或特徵。"},{"en":"A school report may discuss various aspects of student life, such as learning, health, and friendships.","zh":"學校報告可能討論學生生活的各個方面，例如學習、健康和友誼。"},{"en":"Looking at various aspects gives a fuller understanding than looking at only one detail.","zh":"查看各個方面比只看一個細節能提供更完整理解。"},{"en":"This phrase is useful when a topic has several sides.","zh":"當一個主題有幾個面向時，這個短語很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":14},{"front":"better skills because","meaning":"因為……而有較佳技能","examples":[{"en":"Some surgeons may have better skills because of gaming experience.","zh":"有些外科醫生可能因為遊戲經驗而有較佳技能。"},{"en":"Better skills because of something means improved ability caused or supported by a particular factor.","zh":"better skills because of something 指因某因素造成或支持能力改善。"},{"en":"A student may have better speaking skills because of regular practice with classmates.","zh":"學生可能因為經常與同學練習而有較佳說話技能。"},{"en":"If people have better skills because of training, the training may be worth continuing.","zh":"如果人們因訓練而有較佳技能，該訓練可能值得繼續。"},{"en":"This phrase connects improvement with a reason.","zh":"這個短語把改善與原因連接起來。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":14},{"front":"skillful fighter pilots","meaning":"技術熟練的戰鬥機機師","examples":[{"en":"The passage discusses why modern fighter pilots may be more skillful.","zh":"文章討論為何現代戰鬥機機師可能技術更熟練。"},{"en":"Skillful fighter pilots are military pilots with strong flying, reaction, and decision-making abilities.","zh":"skillful fighter pilots 指具備強大飛行、反應和決策能力的軍事機師。"},{"en":"Skillful fighter pilots must control aircraft while processing information quickly.","zh":"技術熟練的戰鬥機機師必須控制飛機，同時快速處理資訊。"},{"en":"Training and experience can make fighter pilots more skillful over time.","zh":"訓練和經驗可以隨時間令戰鬥機機師技術更熟練。"},{"en":"This phrase highlights ability in a high-pressure military role.","zh":"這個短語突出高壓軍事角色中的能力。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":14},{"front":"expect their experiment to show","meaning":"預期實驗會顯示","examples":[{"en":"The researchers expected their experiment to show faster reactions.","zh":"研究人員預期實驗會顯示反應更快。"},{"en":"To expect their experiment to show something means researchers believe the results will reveal it.","zh":"expect their experiment to show something 指研究人員相信結果會揭示某事。"},{"en":"Scientists may expect their experiment to show whether a new teaching method works.","zh":"科學家可能預期實驗會顯示新教學方法是否有效。"},{"en":"If results are different from what researchers expect, they must rethink their explanation.","zh":"如果結果與研究人員預期不同，他們必須重新思考解釋。"},{"en":"This phrase connects prediction with experimental evidence.","zh":"這個短語把預測與實驗證據連接起來。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":14},{"front":"make the best use of","meaning":"充分利用","examples":[{"en":"Gamers learn to make the best use of limited resources.","zh":"玩家學會充分利用有限資源。"},{"en":"To make the best use of something means to use it as effectively as possible.","zh":"make the best use of something 指盡可能有效地使用某物。"},{"en":"A student can make the best use of a short lunch break by reviewing key notes.","zh":"學生可以利用短午飯時間溫習重點筆記，充分利用時間。"},{"en":"Making the best use of resources can reduce waste and improve results.","zh":"充分利用資源可以減少浪費並改善結果。"},{"en":"This phrase is useful when resources are limited.","zh":"當資源有限時，這個短語很有用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":14},{"front":"in the end","meaning":"最終","examples":[{"en":"Players with effective strategies are more likely to win in the end.","zh":"擁有有效策略的玩家最終更有可能取勝。"},{"en":"In the end means finally, after everything has happened.","zh":"in the end 指最後，在一切發生之後。"},{"en":"A student who practises steadily may improve in the end.","zh":"穩定練習的學生最終可能進步。"},{"en":"Short-term mistakes may not matter if the final result is successful in the end.","zh":"如果最終結果成功，短期錯誤可能不重要。"},{"en":"This phrase points to the final outcome.","zh":"這個短語指向最終結果。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":15},{"front":"increase the speed of","meaning":"提高……的速度","examples":[{"en":"Video games may increase the speed of players’ reactions.","zh":"電子遊戲可能提高玩家反應的速度。"},{"en":"To increase the speed of something means to make it happen faster.","zh":"increase the speed of something 指令某事發生得更快。"},{"en":"Better software can increase the speed of online payments.","zh":"更好的軟件可以提高網上付款的速度。"},{"en":"Practice can increase the speed of reading without reducing understanding.","zh":"練習可以提高閱讀速度，而不降低理解。"},{"en":"This phrase focuses on making a process quicker.","zh":"這個短語聚焦令過程更快。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":15},{"front":"agree with the information given","meaning":"與所給資料一致","examples":[{"en":"Students decide whether statements agree with the information given.","zh":"學生判斷陳述是否與所給資料一致。"},{"en":"To agree with the information given means to match what the text says.","zh":"agree with the information given 指與文本所說內容相符。"},{"en":"In a reading test, an answer agrees with the information given only if the passage supports it.","zh":"在閱讀測驗中，只有文章支持時，答案才與所給資料一致。"},{"en":"Students should check the exact wording before deciding that a statement agrees.","zh":"學生在判斷陳述一致前，應檢查確切用字。"},{"en":"This phrase is common in True, False, Not Given questions.","zh":"這個短語常見於 True, False, Not Given 題。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":15},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與文章中的資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the source says.","zh":"contradict the information 指說出與來源內容相反的意思。"},{"en":"If a passage says games improved speed, a statement saying they slowed players down would contradict the information.","zh":"如果文章說遊戲改善速度，而陳述說遊戲令玩家變慢，便與資料相矛盾。"},{"en":"Contradiction is different from missing information; it directly conflicts with the text.","zh":"矛盾不同於缺少資料；它是直接與文本衝突。"},{"en":"This phrase helps students identify false answers.","zh":"這個短語幫助學生辨認錯誤答案。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":15},{"front":"no information on this","meaning":"沒有這方面的資料","examples":[{"en":"Write NOT GIVEN if there is no information on this.","zh":"如果沒有這方面的資料，寫 NOT GIVEN。"},{"en":"No information on this means the source does not say whether the statement is true or false.","zh":"no information on this 指來源沒有說明該陳述是真還是假。"},{"en":"If a passage discusses reaction speed but not school grades, there is no information on this grade claim.","zh":"如果文章討論反應速度，但沒有討論學校成績，就沒有這方面的成績資料。"},{"en":"Students should not guess when there is no information on this in the text.","zh":"當文本沒有這方面的資料時，學生不應猜測。"},{"en":"This phrase is important for avoiding unsupported answers.","zh":"這個短語對避免無根據答案很重要。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":15},{"front":"popular because of","meaning":"因為……而受歡迎","examples":[{"en":"The statement asks whether games are popular because of violent content.","zh":"這個陳述問遊戲是否因為暴力內容而受歡迎。"},{"en":"Popular because of something means liked by many people due to that reason.","zh":"popular because of something 指因某個原因而被很多人喜歡。"},{"en":"A café may be popular because of its cheap lunch sets.","zh":"咖啡店可能因為便宜午餐套餐而受歡迎。"},{"en":"Saying games are popular because of violence may ignore story, challenge, design, and social play.","zh":"說遊戲因暴力而受歡迎，可能忽略故事、挑戰、設計和社交玩法。"},{"en":"This phrase links popularity with a cause.","zh":"這個短語把受歡迎程度與原因連接起來。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":15},{"front":"violent content","meaning":"暴力內容","examples":[{"en":"The question refers to the violent content of many video games.","zh":"題目提到許多電子遊戲的暴力內容。"},{"en":"Violent content is material that includes fighting, injury, killing, or physical harm.","zh":"violent content 指包含打鬥、受傷、殺戮或身體傷害的內容。"},{"en":"Parents may check whether a game has violent content before buying it for a child.","zh":"家長在為孩子購買遊戲前，可能檢查該遊戲是否有暴力內容。"},{"en":"Violent content can lead to concern when audiences are very young.","zh":"當觀眾年紀很小時，暴力內容可能引起憂慮。"},{"en":"This phrase describes what is shown, not automatically what viewers will do.","zh":"這個短語描述展示出來的內容，而不自動等於觀眾會做的事。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":15},{"front":"make fewer mistakes","meaning":"犯較少錯誤","examples":[{"en":"The statement asks whether action-game players made fewer mistakes.","zh":"這個陳述問動作遊戲玩家是否犯較少錯誤。"},{"en":"To make fewer mistakes means to produce a smaller number of wrong answers or errors.","zh":"make fewer mistakes 指產生較少錯誤答案或失誤。"},{"en":"A student may make fewer mistakes after checking grammar carefully.","zh":"學生仔細檢查文法後，可能犯較少錯誤。"},{"en":"Faster work is more impressive if people do not make more mistakes.","zh":"如果人們沒有犯更多錯誤，更快完成工作才更令人印象深刻。"},{"en":"This phrase compares accuracy between attempts or groups.","zh":"這個短語比較不同嘗試或群體的準確度。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":15},{"front":"apply video games in classrooms","meaning":"在課室中應用電子遊戲","examples":[{"en":"The statement suggests that schools should apply video games in classrooms.","zh":"這個陳述建議學校應在課室中應用電子遊戲。"},{"en":"To apply video games in classrooms means to use games as part of teaching and learning.","zh":"apply video games in classrooms 指把遊戲用作教與學的一部分。"},{"en":"A teacher may apply video games in classrooms to practise problem-solving or teamwork.","zh":"老師可能在課室中應用電子遊戲，以練習解難或團隊合作。"},{"en":"Games should be used carefully so they support learning goals, not just entertainment.","zh":"遊戲應謹慎使用，確保它們支援學習目標，而不只是娛樂。"},{"en":"This phrase connects gaming with formal education.","zh":"這個短語把遊戲與正式教育連接起來。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":15},{"front":"be addicted to","meaning":"對……上癮","examples":[{"en":"Some children may be addicted to video games.","zh":"有些兒童可能對電子遊戲上癮。"},{"en":"To be addicted to something means to feel unable to stop using or doing it, even when it causes problems.","zh":"be addicted to something 指即使造成問題，也感到無法停止使用或做某事。"},{"en":"A teenager may be addicted to social media if she cannot stop checking it during homework.","zh":"如果青少年做功課時無法停止查看社交媒體，她可能對社交媒體上癮。"},{"en":"Addiction can harm sleep, study, mood, and family relationships.","zh":"上癮可以傷害睡眠、學習、情緒和家庭關係。"},{"en":"This phrase should be used carefully because it describes a serious pattern.","zh":"這個短語應謹慎使用，因為它描述嚴重模式。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":15},{"front":"lots of dopamine","meaning":"大量多巴胺","examples":[{"en":"The statement asks whether addicted players have lots of dopamine in their brains.","zh":"這個陳述問上癮玩家的大腦中是否有大量多巴胺。"},{"en":"Lots of dopamine means a large amount of the brain chemical connected with reward and motivation.","zh":"lots of dopamine 指大量與獎賞和動機有關的腦內化學物。"},{"en":"Exciting rewards may be linked with lots of dopamine activity in the brain.","zh":"令人興奮的獎賞可能與大腦中大量多巴胺活動有關。"},{"en":"Having dopamine is normal, but problems can arise when reward systems strongly drive repeated behaviour.","zh":"有多巴胺是正常的，但當獎賞系統強烈推動重複行為時，可能出現問題。"},{"en":"This phrase is informal and should be used carefully in scientific discussion.","zh":"這個短語較非正式，在科學討論中應謹慎使用。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":15},{"front":"match the people with","meaning":"將人物與……配對","examples":[{"en":"Students must match the people with opinions or deeds.","zh":"學生必須將人物與意見或行為配對。"},{"en":"To match the people with something means to connect each person to the correct item.","zh":"match the people with something 指把每個人物連接到正確項目。"},{"en":"In a reading task, students may match the people with their discoveries or views.","zh":"在閱讀任務中，學生可能要將人物與其發現或觀點配對。"},{"en":"This skill requires careful scanning for names and related information.","zh":"這項技能需要仔細掃讀姓名和相關資料。"},{"en":"This phrase is common in matching questions.","zh":"這個短語常見於配對題。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":16},{"front":"opinions or deeds","meaning":"意見或行為","examples":[{"en":"The task asks students to match people with opinions or deeds.","zh":"這項任務要求學生將人物與意見或行為配對。"},{"en":"Opinions or deeds means what people think or what they do.","zh":"opinions or deeds 指人們的想法或所做的事。"},{"en":"A history worksheet may ask students to match leaders with their opinions or deeds.","zh":"歷史工作紙可能要求學生將領袖與其意見或行為配對。"},{"en":"Confusing opinions with deeds can lead to wrong answers in reading tests.","zh":"混淆意見和行為可能導致閱讀測驗答案錯誤。"},{"en":"This phrase separates beliefs from actions.","zh":"這個短語區分信念與行動。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":16},{"front":"appropriate letters","meaning":"適當字母","examples":[{"en":"Students write the appropriate letters in the answer boxes.","zh":"學生在答案格中寫上適當字母。"},{"en":"Appropriate letters are the correct option letters that match the answers.","zh":"appropriate letters 指與答案相符的正確選項字母。"},{"en":"In a matching task, students may write A, B, or C as the appropriate letters.","zh":"在配對題中，學生可能寫 A、B 或 C 作為適當字母。"},{"en":"Writing the wrong letter can lose marks even if the student understands the idea.","zh":"即使學生理解意思，寫錯字母也可能失分。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":16},{"front":"everyday skills","meaning":"日常技能","examples":[{"en":"Reading, piano playing and navigation are everyday skills that can change the brain.","zh":"閱讀、彈鋼琴和導航是可以改變大腦的日常技能。"},{"en":"Everyday skills are useful abilities people use in normal life.","zh":"everyday skills 指人們在正常生活中使用的實用能力。"},{"en":"Cooking, reading maps, budgeting, and using public transport are everyday skills.","zh":"煮食、閱讀地圖、做預算和使用公共交通都是日常技能。"},{"en":"Everyday skills improve through practice and can affect how people think and act.","zh":"日常技能透過練習改善，並可以影響人們如何思考和行動。"},{"en":"This phrase shows that important learning is not limited to school subjects.","zh":"這個短語顯示重要學習不限於學校科目。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":16},{"front":"alter the brain’s physical structure","meaning":"改變大腦的生理結構","examples":[{"en":"Video games can alter the brain’s physical structure.","zh":"電子遊戲可以改變大腦的生理結構。"},{"en":"To alter the brain’s physical structure means to change its biological organisation or connections.","zh":"alter the brain’s physical structure 指改變大腦的生物組織或連結。"},{"en":"Learning music may alter the brain’s physical structure through repeated practice.","zh":"學習音樂可能透過反覆練習改變大腦的生理結構。"},{"en":"If an activity alters the brain, its effects may be deeper than simple entertainment.","zh":"如果一項活動改變大腦，其影響可能比簡單娛樂更深。"},{"en":"This phrase is formal and scientific.","zh":"這個短語較正式，帶有科學語氣。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":16},{"front":"rapid decisions","meaning":"快速決定","examples":[{"en":"Stressful games may prepare the brain to make rapid decisions.","zh":"高壓遊戲可能使大腦準備好作出快速決定。"},{"en":"Rapid decisions are very quick choices made under time pressure.","zh":"rapid decisions 指在時間壓力下作出的非常快速選擇。"},{"en":"A nurse may make rapid decisions when a patient’s condition suddenly worsens.","zh":"當病人情況突然惡化時，護士可能作出快速決定。"},{"en":"Rapid decisions can save time, but they must still be accurate.","zh":"快速決定可以節省時間，但仍必須準確。"},{"en":"This phrase highlights speed in serious or demanding situations.","zh":"這個短語突出嚴肅或高要求情境中的速度。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":16},{"front":"be immersed in","meaning":"沉浸於","examples":[{"en":"Players become immersed in stressful games.","zh":"玩家沉浸於高壓遊戲中。"},{"en":"To be immersed in something means to be deeply involved in it and pay strong attention to it.","zh":"be immersed in something 指深度投入某事並高度專注。"},{"en":"A reader may be immersed in a novel and forget the time.","zh":"讀者可能沉浸於小說中，忘記時間。"},{"en":"When players are immersed in a game, they may react as if the situation feels real.","zh":"當玩家沉浸於遊戲時，他們可能像情境真實一樣反應。"},{"en":"This phrase describes deep mental involvement.","zh":"這個短語描述深度心智投入。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":16},{"front":"stressful games","meaning":"高壓遊戲","examples":[{"en":"Stressful games may train the brain for quick decisions.","zh":"高壓遊戲可能訓練大腦作快速決定。"},{"en":"Stressful games are games that create pressure, urgency, danger, or difficult choices.","zh":"stressful games 指製造壓力、緊迫感、危險或困難選擇的遊戲。"},{"en":"A timed puzzle can be stressful if players must solve it before the clock runs out.","zh":"如果玩家必須在時間結束前解決限時謎題，它可能是高壓遊戲。"},{"en":"Stressful games may improve focus, but too much stress can also be tiring.","zh":"高壓遊戲可能改善專注力，但太多壓力也會令人疲倦。"},{"en":"This phrase describes the emotional pressure created by a game.","zh":"這個短語描述遊戲造成的情緒壓力。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":16},{"front":"play an essential role in","meaning":"在……中扮演重要角色","examples":[{"en":"Goal-driven experiences play an essential role in learning.","zh":"以目標為導向的經驗在學習中扮演重要角色。"},{"en":"To play an essential role in something means to be very important to how it happens.","zh":"play an essential role in something 指對某事如何發生非常重要。"},{"en":"Sleep plays an essential role in memory and health.","zh":"睡眠在記憶和健康中扮演重要角色。"},{"en":"If a factor plays an essential role, removing it may weaken the whole process.","zh":"如果某因素扮演重要角色，移除它可能削弱整個過程。"},{"en":"This phrase is useful for identifying key importance.","zh":"這個短語適合用來指出關鍵重要性。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":16},{"front":"tackle immediate problems","meaning":"處理眼前問題","examples":[{"en":"Gamers tackle immediate problems while remembering long-term goals.","zh":"玩家處理眼前問題，同時記住長遠目標。"},{"en":"To tackle immediate problems means to deal with urgent difficulties directly.","zh":"tackle immediate problems 指直接處理緊急困難。"},{"en":"A school must tackle immediate problems when a classroom loses electricity.","zh":"當課室停電時，學校必須處理眼前問題。"},{"en":"Tackling immediate problems quickly can prevent wider disruption.","zh":"迅速處理眼前問題可以防止更大混亂。"},{"en":"This phrase suggests active problem-solving, not passive waiting.","zh":"這個短語表示主動解難，而不是被動等待。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":16},{"front":"broaden their horizons","meaning":"擴闊眼界","examples":[{"en":"Video games may help children broaden their horizons.","zh":"電子遊戲可能幫助兒童擴闊眼界。"},{"en":"To broaden their horizons means to help them learn about more ideas, places, skills, or ways of thinking.","zh":"broaden their horizons 指幫助他們了解更多想法、地方、技能或思考方式。"},{"en":"Travelling can broaden students’ horizons by showing them different ways of life.","zh":"旅行可以透過展示不同生活方式來擴闊學生眼界。"},{"en":"Games based on history or cities may broaden children’s horizons beyond their daily routines.","zh":"以歷史或城市為基礎的遊戲可能把孩子的眼界擴展到日常生活以外。"},{"en":"This phrase is about expanding understanding and experience.","zh":"這個短語關乎擴展理解和經驗。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":16},{"front":"gain self-confidence","meaning":"建立自信","examples":[{"en":"Some games help children broaden their horizons and gain self-confidence.","zh":"有些遊戲幫助兒童擴闊眼界並建立自信。"},{"en":"To gain self-confidence means to become more sure of one’s own ability.","zh":"gain self-confidence 指變得更肯定自己的能力。"},{"en":"A child may gain self-confidence after finally completing a difficult level.","zh":"孩子終於完成困難關卡後，可能建立自信。"},{"en":"Success after effort can make children feel more willing to try new challenges.","zh":"努力後成功可以令孩子更願意嘗試新挑戰。"},{"en":"This phrase describes emotional growth linked to achievement.","zh":"這個短語描述與成就有關的情緒成長。"}],"source":"147 - Video Games’ Unexpected Benefit to Human Brain.pdf","sourcePage":17}],"ielts/reading/passage-2/Practice 148":[{"front":"the ancient bristlecone pine","meaning":"古老的刺果松","examples":[{"en":"The passage discusses the ancient bristlecone pine and its remarkable survival.","zh":"文章討論古老的刺果松及其非凡的生存能力。"},{"en":"The ancient bristlecone pine is a very old tree species famous for living for thousands of years.","zh":"古老的刺果松是一種非常古老的樹種，以能存活數千年而聞名。"},{"en":"A science teacher may use the ancient bristlecone pine to explain how trees can record climate history.","zh":"科學老師可能用古老的刺果松來解釋樹木如何記錄氣候歷史。"},{"en":"The ancient bristlecone pine survives because it grows slowly and adapts to harsh mountain conditions.","zh":"古老的刺果松能生存，是因為它生長緩慢並適應嚴酷山區環境。"},{"en":"Unlike many fast-growing trees, the ancient bristlecone pine is valued for its extreme age and endurance.","zh":"與許多快速生長的樹不同，古老的刺果松因極高年齡和耐力而受到重視。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":1},{"front":"understand more about","meaning":"更深入了解","examples":[{"en":"Scientists study ancient trees to understand more about Earth’s history.","zh":"科學家研究古樹，以更深入了解地球歷史。"},{"en":"To understand more about something means to gain deeper knowledge of it.","zh":"更深入了解某事，是指對它獲得更深層的知識。"},{"en":"Students read extra books to understand more about a difficult topic.","zh":"學生閱讀額外書籍，以更深入了解一個困難題目。"},{"en":"Interviews can help doctors understand more about a patient’s symptoms.","zh":"面談可以幫助醫生更深入了解病人的症狀。"},{"en":"We ask questions when we want to understand more about how something works.","zh":"當我們想更深入了解某事如何運作時，便會提出問題。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":1},{"front":"Earth’s history","meaning":"地球歷史","examples":[{"en":"Bristlecone pines provide insight into Earth’s history.","zh":"刺果松提供對地球歷史的洞察。"},{"en":"Earth’s history means the long record of changes in climate, life, land, and oceans over time.","zh":"地球歷史是指氣候、生命、陸地和海洋隨時間變化的漫長記錄。"},{"en":"Fossils help students learn about Earth’s history before humans existed.","zh":"化石幫助學生了解人類出現前的地球歷史。"},{"en":"Tree rings can reveal parts of Earth’s history by recording dry and wet years.","zh":"樹輪可以透過記錄乾旱和潮濕年份，揭示部分地球歷史。"},{"en":"Understanding Earth’s history helps scientists compare past climate changes with present ones.","zh":"理解地球歷史有助科學家比較過去和現在的氣候變化。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":1},{"front":"look to the natural environment for","meaning":"從自然環境中尋找……","examples":[{"en":"Humans have often looked to the natural environment for insight into the past.","zh":"人類常從自然環境中尋找對過去的洞察。"},{"en":"To look to the natural environment for something means to use nature as a source of information or help.","zh":"從自然環境中尋找某事，是指把大自然用作資訊或幫助的來源。"},{"en":"Farmers look to the natural environment for signs of changing weather.","zh":"農民從自然環境中尋找天氣變化的跡象。"},{"en":"Scientists look to the natural environment for evidence of pollution and climate change.","zh":"科學家從自然環境中尋找污染和氣候變化的證據。"},{"en":"Instead of relying only on written records, researchers can look to the natural environment for hidden clues.","zh":"研究人員不只依賴文字記錄，也可以從自然環境中尋找隱藏線索。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":1},{"front":"insight into the past","meaning":"對過去的洞察","examples":[{"en":"Tree rings can give researchers insight into the past.","zh":"樹輪可以給研究人員對過去的洞察。"},{"en":"Insight into the past means a clearer understanding of what happened before.","zh":"對過去的洞察是指更清楚理解以前發生的事情。"},{"en":"Old photos can give families insight into the past lives of their grandparents.","zh":"舊照片可以讓家庭對祖父母過去的生活有洞察。"},{"en":"Archaeological objects give historians insight into the past by showing how people lived.","zh":"考古物件透過展示人們如何生活，給歷史學家對過去的洞察。"},{"en":"Without records, natural evidence may still provide insight into the past.","zh":"即使沒有文字記錄，自然證據仍可能提供對過去的洞察。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":1},{"front":"bristlecone pine","meaning":"刺果松；長壽松","examples":[{"en":"The bristlecone pine has served this purpose better than any other tree species.","zh":"刺果松比任何其他樹種更好地發揮了這個作用。"},{"en":"A bristlecone pine is a long-lived pine tree that grows in harsh mountain environments.","zh":"刺果松是一種長壽松樹，生長於嚴酷的山區環境。"},{"en":"Visitors may see a bristlecone pine in high, dry areas of the western United States.","zh":"遊客可能在美國西部高而乾燥的地區看見刺果松。"},{"en":"The bristlecone pine grows slowly, and this slow growth helps it survive for a very long time.","zh":"刺果松生長緩慢，而這種緩慢生長幫助它存活很久。"},{"en":"Scientists value the bristlecone pine because its rings preserve ancient climate information.","zh":"科學家重視刺果松，因為它的年輪保存古代氣候資料。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":1},{"front":"Pinus longaeva","meaning":"長壽松；Pinus longaeva","examples":[{"en":"Pinus longaeva grows in California’s White Mountains.","zh":"Pinus longaeva 生長於加州白山山脈。"},{"en":"Pinus longaeva is the scientific name for the Great Basin bristlecone pine.","zh":"Pinus longaeva 是大盆地刺果松的學名。"},{"en":"A biology student may write Pinus longaeva when using the formal name of this tree.","zh":"生物學生使用這種樹的正式名稱時，可能會寫 Pinus longaeva。"},{"en":"Scientific names like Pinus longaeva help researchers identify species clearly across languages.","zh":"像 Pinus longaeva 這樣的學名，幫助研究人員跨語言清楚識別物種。"},{"en":"Pinus longaeva is famous because some individuals are thousands of years old.","zh":"Pinus longaeva 很有名，因為有些個體已有數千年歷史。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":1},{"front":"has served this purpose","meaning":"發揮了這個作用","examples":[{"en":"The bristlecone pine has served this purpose better than any other species.","zh":"刺果松比任何其他物種更好地發揮了這個作用。"},{"en":"If something has served this purpose, it has successfully performed a particular role.","zh":"如果某事物發揮了這個作用，即是它成功履行了某個特定角色。"},{"en":"A school library has served this purpose well if it helps students read more.","zh":"如果學校圖書館幫助學生閱讀更多，它就很好地發揮了這個作用。"},{"en":"Tree rings have served this purpose by giving scientists records of past climate.","zh":"樹輪透過給科學家過去氣候的記錄，發揮了這個作用。"},{"en":"An old tool may still be kept if it has served this purpose reliably for years.","zh":"如果舊工具多年來可靠地發揮了這個作用，它可能仍會被保留。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":1},{"front":"any other species of tree","meaning":"任何其他樹種","examples":[{"en":"This species has helped scientists more than any other species of tree.","zh":"這個物種比任何其他樹種更能幫助科學家。"},{"en":"Any other species of tree means all other kinds of trees being compared.","zh":"任何其他樹種是指被比較的所有其他種類的樹。"},{"en":"The mango tree may grow better in hot weather than any other species of tree in that garden.","zh":"在那個花園中，芒果樹可能比任何其他樹種更適合炎熱天氣。"},{"en":"Scientists compare one tree with any other species of tree to see what makes it special.","zh":"科學家把一種樹與任何其他樹種比較，以了解它有何特別。"},{"en":"Saying “more than any other species of tree” shows that one tree stands out from all the rest.","zh":"說「比任何其他樹種更……」表示某種樹在所有其他樹中突圍而出。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":1},{"front":"on the planet","meaning":"在地球上","examples":[{"en":"Bristlecone pines are among the oldest living trees on the planet.","zh":"刺果松是地球上最古老的活樹之一。"},{"en":"On the planet means in the world or on Earth.","zh":"在地球上是指在世界上或在地球之上。"},{"en":"Blue whales are among the largest animals on the planet.","zh":"藍鯨是地球上最大的動物之一。"},{"en":"When people say something is rare on the planet, they mean it is rare anywhere on Earth.","zh":"當人們說某物在地球上很稀有時，意思是它在任何地方都很罕見。"},{"en":"The phrase on the planet adds emphasis by comparing something with the whole world.","zh":"「在地球上」這個短語透過與整個世界比較來加強語氣。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":1},{"front":"conditions are brutal","meaning":"環境十分嚴酷","examples":[{"en":"Conditions in the White Mountains are brutal.","zh":"白山山脈的環境十分嚴酷。"},{"en":"If conditions are brutal, the environment is extremely harsh, difficult, or dangerous.","zh":"如果環境十分嚴酷，即是該環境極其艱難、惡劣或危險。"},{"en":"Hikers may turn back when weather conditions are brutal on a mountain trail.","zh":"當山徑上的天氣十分嚴酷時，行山者可能會折返。"},{"en":"Brutal conditions can limit plant growth because only well-adapted species survive.","zh":"嚴酷環境會限制植物生長，因為只有適應力強的物種能生存。"},{"en":"A place with freezing wind, little water, and poor soil has brutal conditions for trees.","zh":"一個有冰冷強風、缺水和貧瘠土壤的地方，對樹木而言環境十分嚴酷。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":1},{"front":"scant precipitation","meaning":"稀少降雨","examples":[{"en":"Scant precipitation makes the growing season short.","zh":"稀少降雨令生長季節短暫。"},{"en":"Scant precipitation means very little rain, snow, or other moisture falling from the sky.","zh":"稀少降雨是指雨、雪或其他從天空降下的水分很少。"},{"en":"Farmers struggle in areas with scant precipitation because crops may not get enough water.","zh":"在降雨稀少的地區，農民會遇到困難，因為農作物可能得不到足夠水分。"},{"en":"Scant precipitation can create dry soil and slow plant growth.","zh":"稀少降雨會造成乾燥土壤並減慢植物生長。"},{"en":"Desert regions often have scant precipitation throughout the year.","zh":"沙漠地區全年通常降雨稀少。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":2},{"front":"low average temperatures","meaning":"較低的平均氣溫","examples":[{"en":"Low average temperatures limit plant growth in the mountains.","zh":"較低的平均氣溫限制山區植物生長。"},{"en":"Low average temperatures mean that a place is usually cold over a long period.","zh":"較低的平均氣溫是指一個地方長期通常較寒冷。"},{"en":"Low average temperatures can make winter heating bills higher for families.","zh":"較低的平均氣溫可能令家庭冬季暖氣費更高。"},{"en":"Crops may grow slowly when low average temperatures shorten the warm season.","zh":"當較低的平均氣溫縮短溫暖季節，農作物可能生長緩慢。"},{"en":"In high mountains, low average temperatures help explain why few plants survive.","zh":"在高山地區，較低的平均氣溫有助解釋為何少數植物能生存。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":2},{"front":"a short growing season","meaning":"短暫的生長季節","examples":[{"en":"Scant precipitation and cold weather mean a short growing season.","zh":"稀少降雨和寒冷天氣意味著短暫的生長季節。"},{"en":"A short growing season is a limited period each year when plants can actively grow.","zh":"短暫的生長季節是指每年植物能活躍生長的時間有限。"},{"en":"Farmers in cold regions must choose crops that can mature during a short growing season.","zh":"寒冷地區的農民必須選擇能在短暫生長季節內成熟的農作物。"},{"en":"A short growing season can make trees grow slowly and form narrow rings.","zh":"短暫的生長季節會令樹木生長緩慢並形成狹窄年輪。"},{"en":"Plants in mountains often face a short growing season because warmth and water are limited.","zh":"山區植物常面對短暫生長季節，因為溫暖和水分有限。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":2},{"front":"intensified by","meaning":"因……而加劇","examples":[{"en":"The harsh conditions are intensified by ferocious winds.","zh":"嚴酷環境因猛烈強風而加劇。"},{"en":"If something is intensified by another factor, it becomes stronger or more severe because of that factor.","zh":"如果某事因另一因素而加劇，即是它因該因素變得更強或更嚴重。"},{"en":"Traffic noise is intensified by tall buildings that trap the sound.","zh":"交通噪音可能因高樓困住聲音而加劇。"},{"en":"A drought can be intensified by high temperatures and strong sunlight.","zh":"乾旱可能因高溫和強烈陽光而加劇。"},{"en":"Stress may be intensified by lack of sleep and too many deadlines.","zh":"壓力可能因睡眠不足和太多期限而加劇。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":2},{"front":"ferocious winds","meaning":"猛烈強風","examples":[{"en":"Ferocious winds make the environment even more difficult for trees.","zh":"猛烈強風令樹木面對的環境更加困難。"},{"en":"Ferocious winds are extremely strong and violent winds.","zh":"猛烈強風是極其強烈和猛烈的風。"},{"en":"Hikers should avoid exposed ridges during ferocious winds.","zh":"在猛烈強風期間，行山者應避免暴露的山脊。"},{"en":"Ferocious winds can break branches, dry out plants, and make temperatures feel colder.","zh":"猛烈強風可以折斷樹枝、令植物乾燥，並使氣溫感覺更冷。"},{"en":"Trees that survive ferocious winds usually have strong roots and tough wood.","zh":"能在猛烈強風中生存的樹，通常有強壯根部和堅韌木材。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":2},{"front":"nutrient-poor rocky soil","meaning":"養分貧乏的岩石土壤","examples":[{"en":"Bristlecone pines grow in nutrient-poor rocky soil.","zh":"刺果松生長於養分貧乏的岩石土壤。"},{"en":"Nutrient-poor rocky soil is stony ground with few minerals or organic materials for plants.","zh":"養分貧乏的岩石土壤是石頭多、植物所需礦物質或有機物很少的土地。"},{"en":"Garden vegetables usually grow badly in nutrient-poor rocky soil unless compost is added.","zh":"如果不加入堆肥，園中蔬菜通常在養分貧乏的岩石土壤中生長不佳。"},{"en":"Nutrient-poor rocky soil limits competition because many plants cannot survive there.","zh":"養分貧乏的岩石土壤限制競爭，因為許多植物不能在那裡生存。"},{"en":"Some tough trees adapt to nutrient-poor rocky soil by growing slowly.","zh":"有些堅韌樹木透過緩慢生長來適應養分貧乏的岩石土壤。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":2},{"front":"nevertheless","meaning":"然而；儘管如此","examples":[{"en":"Nevertheless, bristlecone pines have made these barren slopes their home.","zh":"然而，刺果松已把這些貧瘠山坡變成自己的家。"},{"en":"Nevertheless means despite what was just mentioned, the following point is still true.","zh":"nevertheless 是指儘管剛才提到某情況，接下來的重點仍然成立。"},{"en":"The exam was difficult; nevertheless, many students passed.","zh":"考試很困難；然而，許多學生通過了。"},{"en":"The shop is small; nevertheless, it attracts many loyal customers.","zh":"這間店很小；然而，它吸引了許多忠實顧客。"},{"en":"Use nevertheless when you want to show contrast between a problem and a surprising result.","zh":"當你想展示問題與意外結果之間的對比時，可以使用 nevertheless。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":2},{"front":"barren slopes","meaning":"貧瘠山坡","examples":[{"en":"Bristlecone pines have claimed these barren slopes as their permanent home.","zh":"刺果松已把這些貧瘠山坡據為永久棲身之所。"},{"en":"Barren slopes are hillsides with little vegetation or fertile soil.","zh":"貧瘠山坡是植被很少或土壤不肥沃的山坡。"},{"en":"Goats may climb barren slopes where few crops can grow.","zh":"山羊可能攀上很少農作物能生長的貧瘠山坡。"},{"en":"Barren slopes make farming difficult because water and nutrients are limited.","zh":"貧瘠山坡令耕作困難，因為水分和養分有限。"},{"en":"A tree that survives on barren slopes must be able to handle dry, poor ground.","zh":"能在貧瘠山坡生存的樹，必須能應付乾燥而貧乏的土地。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":2},{"front":"permanent home","meaning":"永久棲身之所","examples":[{"en":"The barren slopes have become the bristlecone pines’ permanent home.","zh":"這些貧瘠山坡已成為刺果松的永久棲身之所。"},{"en":"A permanent home is a place where someone or something lives or remains for a long time.","zh":"永久棲身之所是某人或某物長時間生活或停留的地方。"},{"en":"A rescued dog may finally find a permanent home with a caring family.","zh":"獲救的小狗可能終於在一個有愛心的家庭找到永久棲身之所。"},{"en":"A species needs a suitable permanent home to survive and reproduce.","zh":"物種需要合適的永久棲身之所才能生存和繁殖。"},{"en":"For bristlecone pines, harsh mountain slopes became a permanent home rather than a temporary shelter.","zh":"對刺果松而言，嚴酷山坡成為永久棲身之所，而不是臨時庇護所。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":2},{"front":"evolving in","meaning":"在……中演化","examples":[{"en":"Bristlecones evolved in a harsh mountain environment.","zh":"刺果松在嚴酷山區環境中演化。"},{"en":"Evolving in a place means gradually developing features that help survival in that environment.","zh":"在某地演化，是指逐漸發展出有助在該環境生存的特徵。"},{"en":"Fish evolving in dark caves may lose the need for strong eyesight.","zh":"在黑暗洞穴中演化的魚，可能逐漸不需要強視力。"},{"en":"Plants evolving in dry deserts often develop ways to save water.","zh":"在乾燥沙漠中演化的植物，常發展出節省水分的方法。"},{"en":"Species change over time when they are evolving in difficult conditions.","zh":"當物種在困難條件中演化時，它們會隨時間改變。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":2},{"front":"harsh environment","meaning":"嚴酷環境","examples":[{"en":"Bristlecone pines survive in a harsh environment.","zh":"刺果松在嚴酷環境中生存。"},{"en":"A harsh environment is a place with difficult conditions such as cold, dryness, wind, or poor soil.","zh":"嚴酷環境是指有寒冷、乾燥、強風或貧瘠土壤等困難條件的地方。"},{"en":"Workers in a harsh environment need strong safety equipment.","zh":"在嚴酷環境中工作的工人需要強大的安全設備。"},{"en":"A harsh environment can kill weak plants but favour well-adapted ones.","zh":"嚴酷環境可以殺死脆弱植物，但有利於適應力強的植物。"},{"en":"Mountain deserts are harsh environments because water and warmth are limited.","zh":"山區沙漠是嚴酷環境，因為水分和溫暖有限。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":2},{"front":"super-adapted","meaning":"高度適應的","examples":[{"en":"Bristlecones are super-adapted to difficult conditions.","zh":"刺果松高度適應困難條件。"},{"en":"Super-adapted means extremely well suited to a particular environment or challenge.","zh":"高度適應的是指非常適合某特定環境或挑戰。"},{"en":"Camels are super-adapted to desert life because they can manage heat and water shortage.","zh":"駱駝高度適應沙漠生活，因為牠們能應付炎熱和缺水。"},{"en":"A super-adapted plant can survive where ordinary plants fail.","zh":"高度適應的植物可以在普通植物無法生存的地方存活。"},{"en":"Bristlecone pines are super-adapted because their structure helps them live through cold, wind, and drought.","zh":"刺果松高度適應，因為其結構幫助它們經歷寒冷、強風和乾旱。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":3},{"front":"without much competition","meaning":"沒有太多競爭","examples":[{"en":"Bristlecones can survive without much competition from other plants.","zh":"刺果松可以在沒有太多其他植物競爭的情況下生存。"},{"en":"Without much competition means with few other organisms or people fighting for the same resources.","zh":"沒有太多競爭是指很少其他生物或人爭奪相同資源。"},{"en":"A small shop may grow without much competition if it is the only bakery in the area.","zh":"如果某地區只有一間麵包店，小店可能在沒有太多競爭下成長。"},{"en":"Plants grow more easily without much competition for water, light, and soil nutrients.","zh":"如果沒有太多對水、光和土壤養分的競爭，植物會較容易生長。"},{"en":"Harsh places sometimes allow one tough species to survive without much competition.","zh":"嚴酷地方有時讓一種堅韌物種在沒有太多競爭下生存。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":3},{"front":"earned their seat on","meaning":"贏得……的一席位","examples":[{"en":"Bristlecones have earned their seat on the longevity throne.","zh":"刺果松已贏得長壽王座上的一席位。"},{"en":"To earn one’s seat on something means to deserve a respected position because of achievement.","zh":"贏得某處的一席位，是指因成就而配得上一個受尊重的位置。"},{"en":"A hardworking student earned her seat on the debate team after months of practice.","zh":"一名勤奮學生經過數月練習後，贏得辯論隊的一席位。"},{"en":"A company earns its seat among trusted brands by providing reliable service for years.","zh":"公司透過多年提供可靠服務，贏得可信品牌之列的一席位。"},{"en":"Bristlecones earned their seat among the world’s oldest trees through extraordinary survival.","zh":"刺果松憑非凡生存能力，在世界最古老樹木之中贏得一席位。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":3},{"front":"the longevity throne","meaning":"長壽王座","examples":[{"en":"Bristlecone pines have earned their seat on the longevity throne.","zh":"刺果松已贏得長壽王座上的一席位。"},{"en":"The longevity throne is a figurative way to describe the highest rank among long-lived organisms.","zh":"長壽王座是一種比喻說法，用來描述長壽物種中的最高地位。"},{"en":"A turtle that lives for more than a century might be jokingly placed on the longevity throne.","zh":"一隻活過百年的龜，可能被打趣地放上長壽王座。"},{"en":"The phrase suggests respect for something that survives far longer than others.","zh":"這個短語表示對遠比其他事物活得久的生物的尊重。"},{"en":"Bristlecone pines belong on the longevity throne because some live for thousands of years.","zh":"刺果松配得上長壽王座，因為有些能活數千年。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":3},{"front":"oldest living trees","meaning":"最古老的活樹","examples":[{"en":"Bristlecone pines are the oldest living trees on the planet.","zh":"刺果松是地球上最古老的活樹。"},{"en":"Oldest living trees are trees that are still alive and older than nearly all other known trees.","zh":"最古老的活樹是指仍然存活且比幾乎所有已知樹木更古老的樹。"},{"en":"Scientists protect the oldest living trees because they contain rare biological and climate records.","zh":"科學家保護最古老的活樹，因為它們包含罕見的生物和氣候記錄。"},{"en":"The oldest living trees may grow slowly, but they can survive for extraordinary lengths of time.","zh":"最古老的活樹可能生長緩慢，但能存活極長時間。"},{"en":"Seeing the oldest living trees reminds people that some natural lives are far longer than human history.","zh":"看見最古老的活樹會提醒人們，有些自然生命遠比人類歷史長久。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":3},{"front":"extensive studies on","meaning":"關於……的廣泛研究","examples":[{"en":"Extensive studies on bristlecone pine stands have revealed important patterns.","zh":"關於刺果松林分的廣泛研究揭示了重要模式。"},{"en":"Extensive studies on something are detailed and wide-ranging investigations of it.","zh":"關於某事的廣泛研究，是指對它進行詳細而範圍廣泛的調查。"},{"en":"Extensive studies on sleep show that rest affects memory and mood.","zh":"關於睡眠的廣泛研究顯示，休息會影響記憶和情緒。"},{"en":"Extensive studies on a disease can help doctors improve treatment.","zh":"關於疾病的廣泛研究可以幫助醫生改善治療。"},{"en":"Researchers need extensive studies on rare species before making strong conclusions.","zh":"研究人員需要對稀有物種進行廣泛研究，才可作出有力結論。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":3},{"front":"bristlecone pine stands","meaning":"刺果松林分","examples":[{"en":"Researchers have studied many bristlecone pine stands.","zh":"研究人員研究了許多刺果松林分。"},{"en":"Bristlecone pine stands are groups of bristlecone pines growing together in one area.","zh":"刺果松林分是指在同一地區一起生長的一群刺果松。"},{"en":"A forest ranger may guide visitors to bristlecone pine stands in protected mountains.","zh":"森林管理員可能帶遊客前往受保護山區中的刺果松林分。"},{"en":"Bristlecone pine stands are useful for research because many trees can be compared in one place.","zh":"刺果松林分對研究有用，因為許多樹可以在同一地方比較。"},{"en":"Some bristlecone pine stands are isolated, which helps protect them from fire and competition.","zh":"有些刺果松林分相當孤立，這有助保護它們免受火災和競爭影響。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":3},{"front":"environmental limitations","meaning":"環境限制","examples":[{"en":"Environmental limitations may help bristlecones attain great age.","zh":"環境限制可能幫助刺果松達至高齡。"},{"en":"Environmental limitations are natural restrictions such as little water, cold weather, or poor soil.","zh":"環境限制是指缺水、寒冷天氣或貧瘠土壤等自然限制。"},{"en":"Environmental limitations in a garden may include shade, dry soil, and limited space.","zh":"花園中的環境限制可能包括陰影、乾燥土壤和有限空間。"},{"en":"Environmental limitations can reduce competition by preventing many species from growing.","zh":"環境限制可以阻止許多物種生長，從而減少競爭。"},{"en":"In some cases, environmental limitations make organisms grow slowly but live longer.","zh":"在某些情況下，環境限制令生物生長緩慢但更長壽。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":3},{"front":"positively associated with","meaning":"與……呈正相關","examples":[{"en":"Environmental limitations are positively associated with great age.","zh":"環境限制與高齡呈正相關。"},{"en":"If one thing is positively associated with another, they tend to increase or appear together.","zh":"如果一事物與另一事物呈正相關，它們往往一起增加或一起出現。"},{"en":"Regular practice is positively associated with better exam performance.","zh":"規律練習與更好考試表現呈正相關。"},{"en":"Good sleep is positively associated with stronger concentration during the day.","zh":"良好睡眠與日間更強專注力呈正相關。"},{"en":"In this passage, harsh conditions are positively associated with bristlecone longevity.","zh":"在本文中，嚴酷環境與刺果松長壽呈正相關。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":3},{"front":"attainment of great age","meaning":"達至高齡","examples":[{"en":"The harsh environment is linked to the attainment of great age.","zh":"嚴酷環境與達至高齡有關。"},{"en":"Attainment of great age means reaching a very old age.","zh":"達至高齡是指到達非常年老的年齡。"},{"en":"Healthy habits may support the attainment of great age in humans.","zh":"健康習慣可能支持人類達至高齡。"},{"en":"For trees, slow growth and protection from disaster can help the attainment of great age.","zh":"對樹木而言，緩慢生長和免受災害保護可以幫助達至高齡。"},{"en":"The attainment of great age is rare because many organisms die from disease, competition, or accidents.","zh":"達至高齡很罕見，因為許多生物會死於疾病、競爭或意外。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":3},{"front":"intriguing phenomenon","meaning":"耐人尋味的現象","examples":[{"en":"This intriguing phenomenon will be discussed further in the passage.","zh":"這個耐人尋味的現象將在文章後文進一步討論。"},{"en":"An intriguing phenomenon is an interesting event or pattern that makes people want to understand it.","zh":"耐人尋味的現象是令人感興趣並想理解的事件或模式。"},{"en":"A class may discuss the intriguing phenomenon of birds migrating thousands of kilometres.","zh":"課堂可能討論鳥類遷徙數千公里這一耐人尋味的現象。"},{"en":"An intriguing phenomenon often leads scientists to ask new research questions.","zh":"耐人尋味的現象常引導科學家提出新的研究問題。"},{"en":"The long life of trees in harsh places is an intriguing phenomenon because it seems surprising.","zh":"樹木在嚴酷地方長壽是一個耐人尋味的現象，因為它看起來令人驚訝。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":3},{"front":"discussed further on","meaning":"在後文進一步討論","examples":[{"en":"The phenomenon is discussed further on in the passage.","zh":"這個現象在文章後文進一步討論。"},{"en":"If something is discussed further on, it is explained in more detail later in the text.","zh":"如果某事在後文進一步討論，即是它在文本較後部分被更詳細解釋。"},{"en":"The causes of the problem are mentioned here and discussed further on in the report.","zh":"問題的原因在這裡被提及，並在報告後文進一步討論。"},{"en":"A textbook may introduce a term briefly and discuss it further on in the next chapter.","zh":"教科書可能先簡短介紹一個詞，然後在下一章進一步討論。"},{"en":"This phrase tells readers to wait because more information will appear later.","zh":"這個短語告訴讀者要等待，因為稍後會出現更多資訊。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":4},{"front":"exactly how old is old","meaning":"究竟多老才算老","examples":[{"en":"The passage asks exactly how old is old for a bristlecone pine.","zh":"文章問對刺果松來說，究竟多老才算老。"},{"en":"Exactly how old is old asks what age should truly count as very old.","zh":"究竟多老才算老，是在問甚麼年齡才真正算非常古老。"},{"en":"For a phone, exactly how old is old may mean five years; for a tree, it may mean hundreds of years.","zh":"對手機而言，究竟多老才算老可能是五年；對樹而言，可能是數百年。"},{"en":"The question helps readers compare ordinary age with extraordinary age.","zh":"這個問題幫助讀者比較普通年齡與非凡高齡。"},{"en":"When studying long-lived species, scientists must ask exactly how old is old.","zh":"研究長壽物種時，科學家必須問究竟多老才算老。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":4},{"front":"sprouted before","meaning":"在……之前發芽","examples":[{"en":"Methuselah sprouted before the invention of Egyptian hieroglyphs.","zh":"瑪土撒拉在埃及象形文字發明之前已發芽。"},{"en":"If a plant sprouted before an event, it began growing before that event happened.","zh":"如果植物在某事件之前發芽，即是它在該事件發生前已開始生長。"},{"en":"The old tree in the village may have sprouted before the school was built.","zh":"村中的老樹可能在學校建成之前已發芽。"},{"en":"Saying a tree sprouted before a famous invention shows how ancient it is.","zh":"說一棵樹在某項著名發明之前發芽，可以顯示它有多古老。"},{"en":"Methuselah sprouted before many human civilisations developed written records.","zh":"瑪土撒拉在許多人類文明發展文字記錄之前已發芽。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":4},{"front":"Egyptian hieroglyphs","meaning":"埃及象形文字","examples":[{"en":"Methuselah sprouted before the invention of Egyptian hieroglyphs.","zh":"瑪土撒拉在埃及象形文字發明之前已發芽。"},{"en":"Egyptian hieroglyphs were an ancient writing system using pictures and symbols.","zh":"埃及象形文字是一種使用圖像和符號的古代書寫系統。"},{"en":"Students may see Egyptian hieroglyphs carved on temple walls in history books.","zh":"學生可能在歷史書中看到刻在神廟牆上的埃及象形文字。"},{"en":"Mentioning Egyptian hieroglyphs helps readers imagine a very distant period of human history.","zh":"提到埃及象形文字有助讀者想像非常遙遠的人類歷史時期。"},{"en":"If a tree is older than Egyptian hieroglyphs, it has lived through an astonishing span of time.","zh":"如果一棵樹比埃及象形文字更古老，它已經活過令人驚嘆的漫長時間。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":4},{"front":"teachings of Jesus of Nazareth","meaning":"拿撒勒耶穌的教導","examples":[{"en":"Methuselah existed long before the teachings of Jesus of Nazareth.","zh":"瑪土撒拉早在拿撒勒耶穌的教導之前已存在。"},{"en":"The teachings of Jesus of Nazareth refer to the religious and moral messages associated with Jesus.","zh":"拿撒勒耶穌的教導是指與耶穌相關的宗教和道德信息。"},{"en":"History students may study the teachings of Jesus of Nazareth when learning about Christianity.","zh":"歷史學生學習基督教時，可能研究拿撒勒耶穌的教導。"},{"en":"Comparing Methuselah’s age with the teachings of Jesus of Nazareth helps show how ancient the tree is.","zh":"把瑪土撒拉的年齡與拿撒勒耶穌的教導比較，有助顯示這棵樹有多古老。"},{"en":"The phrase points to a major historical reference rather than a scientific measurement.","zh":"這個短語指向一個重要歷史參照，而不是科學量度。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":4},{"front":"Methuselah","meaning":"瑪土撒拉","examples":[{"en":"Methuselah is the oldest living bristlecone pine mentioned in the passage.","zh":"瑪土撒拉是文章中提到的現存最古老刺果松。"},{"en":"Methuselah is the name of an extremely old bristlecone pine.","zh":"瑪土撒拉是一棵極其古老的刺果松的名字。"},{"en":"Park officials protect Methuselah because visitors might damage such a rare tree.","zh":"公園人員保護瑪土撒拉，因為遊客可能損害這種稀有樹木。"},{"en":"Methuselah is famous because its age connects modern science with ancient history.","zh":"瑪土撒拉很有名，因為它的年齡把現代科學與古代歷史連接起來。"},{"en":"When people mention Methuselah, they often want to show how long a living tree can survive.","zh":"人們提到瑪土撒拉時，通常想顯示一棵活樹可以存活多久。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":4},{"front":"oldest bristlecone alive","meaning":"現存最古老的刺果松","examples":[{"en":"Methuselah is the oldest bristlecone alive.","zh":"瑪土撒拉是現存最古老的刺果松。"},{"en":"The oldest bristlecone alive is the living bristlecone pine with the greatest known age.","zh":"現存最古老的刺果松是指已知年齡最高且仍然活著的刺果松。"},{"en":"Scientists study the oldest bristlecone alive to understand long-term tree survival.","zh":"科學家研究現存最古老的刺果松，以理解樹木如何長期生存。"},{"en":"The oldest bristlecone alive must be protected because it cannot be replaced quickly.","zh":"現存最古老的刺果松必須受保護，因為它不能很快被取代。"},{"en":"Calling Methuselah the oldest bristlecone alive means it is still living, not only an ancient dead specimen.","zh":"稱瑪土撒拉為現存最古老的刺果松，意思是它仍活著，而不只是古老死亡標本。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":4},{"front":"roughly 4,700 years","meaning":"約四千七百年","examples":[{"en":"Methuselah is roughly 4,700 years old.","zh":"瑪土撒拉約四千七百歲。"},{"en":"Roughly 4,700 years means about 4,700 years, not necessarily the exact number.","zh":"約四千七百年是指大約四千七百年，不一定是完全精確的數字。"},{"en":"A building roughly 100 years old may have been built a little before or after that date.","zh":"一座約一百年的建築，可能在該日期前後不久建成。"},{"en":"We use roughly when the number is close enough for general understanding.","zh":"當數字足以讓人一般理解時，我們會使用 roughly。"},{"en":"Saying Methuselah is roughly 4,700 years old helps readers grasp its incredible age.","zh":"說瑪土撒拉約四千七百歲，有助讀者理解其驚人年齡。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":4},{"front":"specimens of this age","meaning":"這個年齡的標本","examples":[{"en":"Specimens of this age do not represent the species’ average.","zh":"這個年齡的標本並不代表該物種的平均水平。"},{"en":"Specimens of this age are individual examples that have reached such an old age.","zh":"這個年齡的標本是指達到如此高齡的個別例子。"},{"en":"A museum may keep specimens of this age in special conditions to prevent damage.","zh":"博物館可能把這個年齡的標本保存在特殊條件下，以防損壞。"},{"en":"Specimens of this age are rare, so they should not be treated as normal examples.","zh":"這個年齡的標本很罕見，所以不應被視為正常例子。"},{"en":"When scientists study specimens of this age, they must remember that most members of the species are younger.","zh":"科學家研究這個年齡的標本時，必須記住該物種大多數成員較年輕。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":4},{"front":"represent the species’ average","meaning":"代表該物種的平均水平","examples":[{"en":"Very old specimens do not represent the species’ average age.","zh":"非常古老的標本並不代表該物種的平均年齡。"},{"en":"To represent the species’ average means to show what is normal or typical for that species.","zh":"代表該物種的平均水平，是指顯示該物種正常或典型的情況。"},{"en":"One unusually tall student does not represent the class average height.","zh":"一名異常高的學生並不代表全班平均身高。"},{"en":"A very old tree may not represent the species’ average because most individuals die earlier.","zh":"一棵非常古老的樹未必代表該物種的平均水平，因為大多數個體較早死亡。"},{"en":"Researchers need many examples before deciding what represents the species’ average.","zh":"研究人員需要很多例子，才可判斷甚麼代表該物種的平均水平。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":4},{"front":"two dozen","meaning":"二十四個；兩打","examples":[{"en":"There are two dozen bristlecones over 4,000 years old.","zh":"有二十四棵刺果松超過四千歲。"},{"en":"Two dozen means twenty-four.","zh":"two dozen 的意思是二十四個。"},{"en":"A bakery may sell two dozen cookies for a class party.","zh":"麵包店可能為班級派對出售兩打曲奇。"},{"en":"If two dozen students join a club, the teacher may need a larger room.","zh":"如果二十四名學生加入社團，老師可能需要較大的房間。"},{"en":"Saying two dozen sounds more natural than saying twenty-four in some everyday contexts.","zh":"在某些日常情境中，說 two dozen 比說 twenty-four 更自然。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":4},{"front":"considering that","meaning":"考慮到","examples":[{"en":"Considering that these ages are reached in harsh conditions, the trees are remarkable.","zh":"考慮到這些年齡是在嚴酷環境中達到的，這些樹非常了不起。"},{"en":"Considering that means when you think about a particular fact or situation.","zh":"considering that 是指當你考慮某個事實或情況時。"},{"en":"Considering that she was ill, her exam result was very strong.","zh":"考慮到她病了，她的考試成績已經很出色。"},{"en":"Considering that the shop is new, it already has many customers.","zh":"考慮到這間店很新，它已經有很多顧客。"},{"en":"We use considering that to explain why something is surprising or impressive.","zh":"我們使用 considering that 來解釋某事為何令人驚訝或印象深刻。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":5},{"front":"in the face of","meaning":"面對……","examples":[{"en":"Bristlecones survive in the face of remarkable environmental adversity.","zh":"刺果松面對極大的環境逆境仍能生存。"},{"en":"In the face of means despite a difficult problem, danger, or challenge.","zh":"in the face of 是指儘管有困難問題、危險或挑戰。"},{"en":"Nurses continued working in the face of heavy pressure during the outbreak.","zh":"在疫情期間，護士面對巨大壓力仍繼續工作。"},{"en":"A student may stay calm in the face of a difficult exam.","zh":"學生面對困難考試時可能保持冷靜。"},{"en":"The phrase often shows courage, survival, or persistence despite hardship.","zh":"這個短語常顯示面對艱難時的勇氣、生存或堅持。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":5},{"front":"remarkable environmental adversity","meaning":"極大的環境逆境","examples":[{"en":"The trees reach great ages despite remarkable environmental adversity.","zh":"這些樹儘管面對極大的環境逆境，仍能達至高齡。"},{"en":"Remarkable environmental adversity means unusually severe natural difficulties in a place.","zh":"極大的環境逆境是指某地異常嚴重的自然困難。"},{"en":"Desert animals face remarkable environmental adversity because heat and water shortage are constant problems.","zh":"沙漠動物面對極大的環境逆境，因為高溫和缺水是持續問題。"},{"en":"Remarkable environmental adversity can make survival difficult but also reduce competition.","zh":"極大的環境逆境會令生存困難，但也會減少競爭。"},{"en":"Bristlecone pines are impressive because they live long under remarkable environmental adversity.","zh":"刺果松令人印象深刻，因為它們在極大的環境逆境下長壽。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":5},{"front":"the focus of","meaning":"……的焦點","examples":[{"en":"Bristlecone pines have become the focus of scientific examination.","zh":"刺果松已成為科學研究的焦點。"},{"en":"The focus of something is the main subject receiving attention.","zh":"某事的焦點是受到主要注意的主題。"},{"en":"Student wellbeing has become the focus of many school meetings.","zh":"學生福祉已成為許多學校會議的焦點。"},{"en":"When a problem becomes the focus of research, more time and money are spent on it.","zh":"當某問題成為研究焦點時，人們會投入更多時間和金錢。"},{"en":"Bristlecone pines became the focus of scientists because their rings contain rare climate records.","zh":"刺果松成為科學家的焦點，因為它們的年輪包含罕見氣候記錄。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":5},{"front":"scientific examination","meaning":"科學研究","examples":[{"en":"Bristlecone pines have attracted much scientific examination.","zh":"刺果松吸引了大量科學研究。"},{"en":"Scientific examination means careful study using observation, evidence, and research methods.","zh":"科學研究是指使用觀察、證據和研究方法進行仔細研究。"},{"en":"A new medicine must go through scientific examination before doctors use it widely.","zh":"新藥在醫生廣泛使用前，必須經過科學研究。"},{"en":"Scientific examination can reveal facts that ordinary observation may miss.","zh":"科學研究可以揭示普通觀察可能錯過的事實。"},{"en":"The bristlecone pine is important because scientific examination of its rings helps date the past.","zh":"刺果松很重要，因為對其年輪的科學研究有助為過去定年。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":5},{"front":"over the past half-century","meaning":"在過去半個世紀","examples":[{"en":"Scientists have studied bristlecone pines over the past half-century.","zh":"科學家在過去半個世紀研究刺果松。"},{"en":"Over the past half-century means during the last fifty years.","zh":"在過去半個世紀是指在過去五十年期間。"},{"en":"Over the past half-century, computers have become common in homes and schools.","zh":"在過去半個世紀，電腦已在家庭和學校中變得普遍。"},{"en":"A city may change greatly over the past half-century as transport and housing develop.","zh":"一個城市可能在過去半個世紀隨交通和房屋發展而大大改變。"},{"en":"The phrase helps readers understand that the research has continued for many decades.","zh":"這個短語幫助讀者理解研究已持續許多十年。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":5},{"front":"dendrochronologists","meaning":"樹輪年代學家","examples":[{"en":"Dendrochronologists are especially interested in bristlecone pines.","zh":"樹輪年代學家對刺果松尤其感興趣。"},{"en":"Dendrochronologists are scientists who study tree rings to date events and understand past environments.","zh":"樹輪年代學家是研究樹輪以確定事件年代和理解過去環境的科學家。"},{"en":"Dendrochronologists can compare rings from different trees to build long climate records.","zh":"樹輪年代學家可以比較不同樹木的年輪，建立長期氣候記錄。"},{"en":"Dendrochronologists need old trees because longer records reveal more history.","zh":"樹輪年代學家需要古樹，因為更長記錄能揭示更多歷史。"},{"en":"Bristlecone pines are valuable to dendrochronologists because their rings go back thousands of years.","zh":"刺果松對樹輪年代學家很有價值，因為其年輪可追溯數千年。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":5},{"front":"tree-ring daters","meaning":"樹輪定年專家","examples":[{"en":"Tree-ring daters use growth rings to study the past.","zh":"樹輪定年專家使用生長年輪研究過去。"},{"en":"Tree-ring daters are specialists who estimate age and past conditions by reading tree rings.","zh":"樹輪定年專家是透過閱讀樹輪來估算年齡和過去環境的專家。"},{"en":"Tree-ring daters may help archaeologists date wooden beams in old buildings.","zh":"樹輪定年專家可能幫助考古學家為古建築中的木樑定年。"},{"en":"Tree-ring daters compare patterns of wide and narrow rings across samples.","zh":"樹輪定年專家比較不同樣本中寬窄年輪的模式。"},{"en":"Without tree-ring daters, some ancient wooden objects would be harder to date accurately.","zh":"沒有樹輪定年專家，一些古代木製物件會更難準確定年。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":5},{"front":"with every strenuous year","meaning":"每逢艱難的一年","examples":[{"en":"With every strenuous year, each bristlecone forms a new outer layer.","zh":"每逢艱難的一年，每棵刺果松都形成新的外層。"},{"en":"With every strenuous year means during each difficult year of growth or survival.","zh":"每逢艱難的一年，是指在每個生長或生存困難的年份中。"},{"en":"With every strenuous year of training, the athlete became stronger and more disciplined.","zh":"每逢艱難的一年訓練，運動員都變得更強壯和更自律。"},{"en":"A tree records hardship with every strenuous year through narrower growth rings.","zh":"樹木透過較窄的生長年輪，記錄每逢艱難的一年。"},{"en":"This phrase suggests repeated effort over time, not one single difficult moment.","zh":"這個短語暗示長時間反覆努力，而不是單一困難時刻。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":5},{"front":"forms a new outer layer","meaning":"形成新的外層","examples":[{"en":"Each bristlecone forms a new outer layer of cambium.","zh":"每棵刺果松都形成新的形成層外層。"},{"en":"If a tree forms a new outer layer, it adds fresh growth around its outside.","zh":"如果樹木形成新的外層，即是它在外部增加新的生長部分。"},{"en":"A young branch forms a new outer layer as it thickens each year.","zh":"年輕樹枝每年變粗時，會形成新的外層。"},{"en":"Forming a new outer layer helps trees record annual growth.","zh":"形成新的外層幫助樹木記錄每年生長。"},{"en":"Scientists can study each new outer layer to learn about past growing conditions.","zh":"科學家可以研究每個新的外層，以了解過去的生長條件。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":5},{"front":"cambium","meaning":"形成層","examples":[{"en":"Cambium produces new growth in the tree.","zh":"形成層在樹木中產生新生長。"},{"en":"Cambium is a thin layer of living tissue that helps a tree grow wider.","zh":"形成層是一層薄薄的活組織，幫助樹木變粗。"},{"en":"If the cambium is damaged, the tree may struggle to transport nutrients.","zh":"如果形成層受損，樹木可能難以運送養分。"},{"en":"Gardeners must protect the cambium when cutting or grafting trees.","zh":"園丁修剪或嫁接樹木時，必須保護形成層。"},{"en":"Annual rings form because the cambium produces new wood each growing season.","zh":"年輪形成，是因為形成層在每個生長季節產生新木質。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":5},{"front":"reflects a season’s ease or hardship","meaning":"反映一季的順境或艱難","examples":[{"en":"Each growth layer reflects a season’s ease or hardship.","zh":"每個生長層都反映一季的順境或艱難。"},{"en":"If a ring reflects a season’s ease or hardship, it shows whether that season was favourable or difficult.","zh":"如果年輪反映一季的順境或艱難，即是它顯示該季節是否有利或困難。"},{"en":"A wide ring may reflect a season’s ease when water and warmth were plentiful.","zh":"當水分和溫暖充足時，寬年輪可能反映一季的順境。"},{"en":"A narrow ring may reflect a season’s hardship caused by drought or cold.","zh":"窄年輪可能反映由乾旱或寒冷造成的一季艱難。"},{"en":"Tree rings are useful because they quietly reflect each season’s ease or hardship.","zh":"樹輪有用，因為它們默默反映每一季的順境或艱難。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":6},{"front":"growing seasons may expand or shrink","meaning":"生長季節可能延長或縮短","examples":[{"en":"Growing seasons may expand or shrink depending on climate.","zh":"生長季節可能因氣候而延長或縮短。"},{"en":"If growing seasons expand or shrink, the time when plants can grow becomes longer or shorter.","zh":"如果生長季節延長或縮短，即是植物能生長的時間變長或變短。"},{"en":"Warmer springs may make growing seasons expand for some crops.","zh":"較暖的春天可能令某些農作物的生長季節延長。"},{"en":"Drought can make growing seasons shrink because plants stop growing earlier.","zh":"乾旱可能令生長季節縮短，因為植物較早停止生長。"},{"en":"Changes in growing seasons affect farmers, forests, and food supply.","zh":"生長季節的變化會影響農民、森林和糧食供應。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":6},{"front":"carry on","meaning":"繼續生長；堅持下去","examples":[{"en":"The trees carry on despite changing growing seasons.","zh":"儘管生長季節改變，這些樹仍繼續生長。"},{"en":"To carry on means to continue doing something despite difficulty.","zh":"carry on 是指儘管有困難仍繼續做某事。"},{"en":"A student may carry on studying even after failing one test.","zh":"學生即使一次測驗不合格，仍可能繼續努力學習。"},{"en":"Families carry on with daily life after a storm by repairing what they can.","zh":"風暴後，家庭透過修復能修復的東西，繼續日常生活。"},{"en":"Bristlecone pines carry on because they are adapted to long-term hardship.","zh":"刺果松能堅持下去，因為它們適應長期艱難。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":6},{"front":"growth rings","meaning":"生長年輪","examples":[{"en":"Growth rings record good and bad years.","zh":"生長年輪記錄好年份和壞年份。"},{"en":"Growth rings are circular layers in wood that show how much a tree grew each year.","zh":"生長年輪是木材中的圓形層，顯示樹木每年生長多少。"},{"en":"A wide growth ring may show a year with enough water and warmth.","zh":"寬闊的生長年輪可能顯示該年有足夠水分和溫暖。"},{"en":"Growth rings help scientists compare climate conditions across many years.","zh":"生長年輪幫助科學家比較多年來的氣候條件。"},{"en":"When you count growth rings, you can often estimate a tree’s age.","zh":"當你計算生長年輪時，通常可以估算樹木年齡。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":6},{"front":"faithfully recording","meaning":"忠實記錄","examples":[{"en":"The growth rings faithfully record the bad years alongside the good ones.","zh":"生長年輪忠實記錄壞年份和好年份。"},{"en":"Faithfully recording means keeping an accurate and reliable record without leaving out important details.","zh":"忠實記錄是指準確可靠地保存記錄，不遺漏重要細節。"},{"en":"A diary faithfully records a student’s daily practice and progress.","zh":"日記忠實記錄學生的每日練習和進步。"},{"en":"Security cameras faithfully record events, which can help explain what happened.","zh":"保安攝影機忠實記錄事件，可以幫助解釋發生了甚麼。"},{"en":"Tree rings faithfully record climate changes because each year leaves a physical mark.","zh":"樹輪忠實記錄氣候變化，因為每一年都留下實體痕跡。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":6},{"front":"alongside","meaning":"與……並列；與……一起","examples":[{"en":"The trees record bad years alongside good ones.","zh":"這些樹把壞年份與好年份一起記錄下來。"},{"en":"Alongside means together with or next to something else.","zh":"alongside 是指與另一事物一起或並列。"},{"en":"Students learn grammar alongside vocabulary in a language course.","zh":"學生在語言課中同時學習文法和詞彙。"},{"en":"A museum may display modern photos alongside old maps to show change.","zh":"博物館可能把現代照片與舊地圖並列展示，以顯示變化。"},{"en":"In tree rings, difficult years appear alongside favourable years in one continuous record.","zh":"在樹輪中，困難年份與有利年份並列出現在一個連續記錄中。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":6},{"front":"annual growth rings","meaning":"年生長輪","examples":[{"en":"Scientists examine annual growth rings to understand climate history.","zh":"科學家檢查年生長輪，以理解氣候歷史。"},{"en":"Annual growth rings are the layers a tree forms each year as it grows.","zh":"年生長輪是樹木每年生長時形成的層。"},{"en":"A forester can count annual growth rings to estimate when a tree began growing.","zh":"林務人員可以計算年生長輪，以估算樹木何時開始生長。"},{"en":"Annual growth rings may become narrow during drought years.","zh":"在乾旱年份，年生長輪可能變窄。"},{"en":"Because annual growth rings form regularly, they are useful natural records.","zh":"因為年生長輪定期形成，它們是有用的自然記錄。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":6},{"front":"living and dead specimens","meaning":"活體及死亡標本","examples":[{"en":"Researchers examine living and dead specimens.","zh":"研究人員檢查活體及死亡標本。"},{"en":"Living and dead specimens are examples of organisms that are either still alive or no longer alive.","zh":"活體及死亡標本是仍然活著或已不再存活的生物例子。"},{"en":"A museum may study living and dead specimens to compare present and past features.","zh":"博物館可能研究活體及死亡標本，以比較現在和過去的特徵。"},{"en":"Living and dead specimens together can extend a scientific record further back in time.","zh":"活體及死亡標本結合起來，可以把科學記錄延伸到更久以前。"},{"en":"Tree-ring studies use living and dead specimens because dead wood can still preserve old rings.","zh":"樹輪研究使用活體及死亡標本，因為死木仍可保存古老年輪。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":6},{"front":"core samples","meaning":"芯樣；樹芯樣本","examples":[{"en":"Scientists take core samples from bristlecone pines.","zh":"科學家從刺果松取出樹芯樣本。"},{"en":"Core samples are narrow pieces taken from inside a tree or material for study.","zh":"芯樣是從樹木或材料內部取出的狹窄樣本，用於研究。"},{"en":"Researchers take core samples carefully so the tree is not seriously damaged.","zh":"研究人員小心取得芯樣，以免嚴重損害樹木。"},{"en":"Core samples let scientists examine rings without cutting down the whole tree.","zh":"樹芯樣本讓科學家在不砍倒整棵樹的情況下檢查年輪。"},{"en":"In construction, core samples from concrete can show whether a building material is strong.","zh":"在建築中，混凝土芯樣可以顯示建材是否堅固。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":6},{"front":"cross-dating trees against","meaning":"將樹木與……交叉定年","examples":[{"en":"Scientists cross-date trees against other qualitative records.","zh":"科學家將樹木與其他定性記錄交叉定年。"},{"en":"To cross-date trees against records means to compare tree-ring patterns with other evidence to confirm dates.","zh":"將樹木與記錄交叉定年，是指比較樹輪模式與其他證據，以確認日期。"},{"en":"Researchers may cross-date trees against old flood reports to check whether a wet year matches the rings.","zh":"研究人員可能將樹木與舊洪水報告交叉定年，檢查潮濕年份是否與年輪吻合。"},{"en":"Cross-dating trees against several sources makes the final timeline more reliable.","zh":"將樹木與多個來源交叉定年，可令最終時間線更可靠。"},{"en":"This method is useful because one record can support or correct another.","zh":"這種方法有用，因為一項記錄可以支持或修正另一項記錄。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":6},{"front":"qualitative records","meaning":"定性記錄","examples":[{"en":"Researchers compare tree rings with qualitative records.","zh":"研究人員把樹輪與定性記錄比較。"},{"en":"Qualitative records are descriptive records, such as written reports, observations, or historical accounts.","zh":"定性記錄是描述性記錄，例如書面報告、觀察或歷史記述。"},{"en":"A farmer’s diary about drought is a qualitative record of climate conditions.","zh":"農民關於乾旱的日記，是氣候條件的定性記錄。"},{"en":"Qualitative records help explain numbers by adding human description and context.","zh":"定性記錄透過加入人的描述和背景，幫助解釋數字。"},{"en":"Tree rings and qualitative records together can give a fuller picture of the past.","zh":"樹輪和定性記錄結合，可以提供更完整的過去圖像。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":6},{"front":"compiled a continuous tree-ring record","meaning":"編成連續樹輪記錄","examples":[{"en":"Scientists have compiled a continuous tree-ring record.","zh":"科學家已編成連續樹輪記錄。"},{"en":"To compile a continuous tree-ring record means to build an unbroken timeline from many tree-ring samples.","zh":"編成連續樹輪記錄，是指由許多樹輪樣本建立一條不間斷時間線。"},{"en":"Researchers compile records by matching ring patterns from living and dead trees.","zh":"研究人員透過匹配活樹和死樹的年輪模式來編製記錄。"},{"en":"A continuous tree-ring record helps scientists follow climate changes across thousands of years.","zh":"連續樹輪記錄幫助科學家追蹤數千年間的氣候變化。"},{"en":"Without careful matching, it would be difficult to compile a continuous tree-ring record.","zh":"沒有仔細匹配，就很難編成連續樹輪記錄。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":7},{"front":"dates back to","meaning":"可追溯至","examples":[{"en":"The tree-ring record dates back to the last Ice Age.","zh":"這項樹輪記錄可追溯至最後一次冰河時期。"},{"en":"Dates back to means began or can be traced to a particular time in the past.","zh":"dates back to 是指始於或可追溯至過去某個特定時間。"},{"en":"This temple dates back to the eighteenth century.","zh":"這座寺廟可追溯至十八世紀。"},{"en":"A family tradition may date back to a grandparent’s childhood.","zh":"一項家庭傳統可能可追溯至祖父母的童年。"},{"en":"If a record dates back thousands of years, it can show very long-term change.","zh":"如果一項記錄可追溯數千年，它可以顯示非常長期的變化。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":7},{"front":"the last Ice Age","meaning":"最後一次冰河時期","examples":[{"en":"The continuous tree-ring record dates back to the last Ice Age.","zh":"連續樹輪記錄可追溯至最後一次冰河時期。"},{"en":"The last Ice Age was a cold period in Earth’s history when large ice sheets covered many areas.","zh":"最後一次冰河時期是地球歷史上的寒冷時期，大片冰蓋覆蓋許多地區。"},{"en":"Students learn about the last Ice Age to understand ancient climates and animal migration.","zh":"學生學習最後一次冰河時期，以理解古代氣候和動物遷徙。"},{"en":"Records dating to the last Ice Age help scientists compare ancient and modern warming.","zh":"可追溯至最後一次冰河時期的記錄，有助科學家比較古代和現代暖化。"},{"en":"A tree-ring record reaching the last Ice Age is valuable because it covers a very long period.","zh":"能延伸至最後一次冰河時期的樹輪記錄很有價值，因為它涵蓋很長時期。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":7},{"front":"linked accomplishments","meaning":"相關成果","examples":[{"en":"The record has produced several linked accomplishments.","zh":"這項記錄產生了幾項相關成果。"},{"en":"Linked accomplishments are achievements connected to one another or built from the same work.","zh":"相關成果是彼此連接或由同一工作建立的成就。"},{"en":"A school project may produce linked accomplishments, such as better research skills and stronger teamwork.","zh":"一個學校項目可能產生相關成果，例如更好的研究技能和更強團隊合作。"},{"en":"One scientific discovery can lead to linked accomplishments in dating, climate study, and archaeology.","zh":"一項科學發現可以帶來定年、氣候研究和考古方面的相關成果。"},{"en":"The bristlecone record created linked accomplishments because it improved several research methods at once.","zh":"刺果松記錄產生相關成果，因為它同時改善了幾種研究方法。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":7},{"front":"enhanced the dating process","meaning":"改善定年過程","examples":[{"en":"The tree-ring record has enhanced the dating process.","zh":"樹輪記錄改善了定年過程。"},{"en":"To enhance the dating process means to make age estimation more accurate or reliable.","zh":"改善定年過程是指令年齡估算更準確或可靠。"},{"en":"Better laboratory equipment can enhance the dating process for ancient bones.","zh":"更好的實驗室設備可以改善古骨骼的定年過程。"},{"en":"Comparing tree rings with carbon data enhanced the dating process by correcting mistakes.","zh":"把樹輪與碳數據比較，透過修正錯誤改善了定年過程。"},{"en":"Archaeologists benefit when natural records enhance the dating process.","zh":"當自然記錄改善定年過程時，考古學家會受益。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":7},{"front":"double-check and correct","meaning":"反覆核對並修正","examples":[{"en":"Tree-ring data help scientists double-check and correct radiocarbon dating.","zh":"樹輪數據幫助科學家反覆核對並修正放射性碳定年。"},{"en":"To double-check and correct means to examine something again and fix any mistakes.","zh":"反覆核對並修正是指再次檢查某事並改正錯誤。"},{"en":"Students should double-check and correct spelling before handing in an essay.","zh":"學生交文章前應反覆核對並修正串字。"},{"en":"Accountants double-check and correct figures to avoid financial errors.","zh":"會計師反覆核對並修正數字，以避免財務錯誤。"},{"en":"Scientists double-check and correct dating methods when new evidence shows a problem.","zh":"當新證據顯示問題時，科學家會反覆核對並修正定年方法。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":7},{"front":"radiocarbon-14 method","meaning":"碳十四定年法","examples":[{"en":"The tree-ring record helped correct the radiocarbon-14 method.","zh":"樹輪記錄幫助修正碳十四定年法。"},{"en":"The radiocarbon-14 method estimates the age of organic material by measuring carbon-14 decay.","zh":"碳十四定年法透過量度碳十四衰變來估算有機物質的年齡。"},{"en":"Archaeologists use the radiocarbon-14 method to date bones, wood, and cloth.","zh":"考古學家使用碳十四定年法為骨骼、木材和布料定年。"},{"en":"The radiocarbon-14 method needs calibration because carbon levels have varied over time.","zh":"碳十四定年法需要校準，因為碳含量會隨時間變化。"},{"en":"Tree rings improved the radiocarbon-14 method by giving known-year samples for comparison.","zh":"樹輪透過提供已知年份的樣本作比較，改善了碳十四定年法。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":7},{"front":"more accurately estimate","meaning":"更準確估算","examples":[{"en":"Scientists can more accurately estimate the age of organic material.","zh":"科學家可以更準確估算有機物質的年齡。"},{"en":"To more accurately estimate something means to make a closer and more reliable guess.","zh":"更準確估算某事，是指作出更接近真實且更可靠的估計。"},{"en":"A doctor can more accurately estimate recovery time after seeing test results.","zh":"醫生看到檢查結果後，可以更準確估算康復時間。"},{"en":"Weather stations help experts more accurately estimate rainfall.","zh":"氣象站幫助專家更準確估算降雨量。"},{"en":"Better evidence allows researchers to more accurately estimate dates from the past.","zh":"更好的證據讓研究人員更準確估算過去日期。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":7},{"front":"organic material","meaning":"有機物質","examples":[{"en":"Radiocarbon dating estimates the age of organic material.","zh":"放射性碳定年估算有機物質的年齡。"},{"en":"Organic material is material that comes from living things, such as wood, bone, cloth, or seeds.","zh":"有機物質是來自生物的材料，例如木材、骨骼、布料或種子。"},{"en":"Compost is made from organic material like leaves and food waste.","zh":"堆肥由樹葉和廚餘等有機物質製成。"},{"en":"Organic material can decay over time, so scientists must preserve samples carefully.","zh":"有機物質會隨時間腐爛，所以科學家必須小心保存樣本。"},{"en":"Carbon dating works on organic material because it once contained carbon from living organisms.","zh":"碳定年適用於有機物質，因為它曾含有來自生物的碳。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":7},{"front":"now more than ever","meaning":"現在比以往任何時候更","examples":[{"en":"Now more than ever, scientists realise the importance of monitoring bristlecones.","zh":"現在比以往任何時候更，科學家意識到監測刺果松的重要性。"},{"en":"Now more than ever means especially at the present time.","zh":"now more than ever 是指尤其在現在這個時候。"},{"en":"Now more than ever, students need digital skills for study and work.","zh":"現在比以往任何時候更，學生需要數碼技能來學習和工作。"},{"en":"After recent floods, the city needs better drainage now more than ever.","zh":"最近洪水之後，這座城市現在比以往任何時候更需要更好的排水系統。"},{"en":"The phrase stresses that a need has become more urgent than before.","zh":"這個短語強調某種需要比以前更迫切。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":7},{"front":"the importance of monitoring","meaning":"監測……的重要性","examples":[{"en":"The importance of monitoring the bristlecone is being realised.","zh":"監測刺果松的重要性正被認識到。"},{"en":"The importance of monitoring something means the value of watching and recording it regularly.","zh":"監測某事的重要性，是指定期觀察和記錄它的價值。"},{"en":"Doctors explain the importance of monitoring blood pressure to prevent hidden health problems.","zh":"醫生解釋監測血壓的重要性，以防止隱藏健康問題。"},{"en":"The importance of monitoring forests grows when climate change creates new risks.","zh":"當氣候變化帶來新風險時，監測森林的重要性會增加。"},{"en":"Monitoring bristlecones is important because changes in their growth may reveal climate stress.","zh":"監測刺果松很重要，因為其生長變化可能揭示氣候壓力。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":7},{"front":"is being realised","meaning":"正被認識到","examples":[{"en":"The importance of monitoring these trees is being realised.","zh":"監測這些樹的重要性正被認識到。"},{"en":"If something is being realised, people are beginning to understand or recognise it.","zh":"如果某事正被認識到，即是人們開始理解或承認它。"},{"en":"The value of mental health support is being realised in many schools.","zh":"心理健康支援的價值正被許多學校認識到。"},{"en":"The danger of plastic waste is being realised as beaches become polluted.","zh":"隨著海灘受到污染，塑膠廢物的危險正被認識到。"},{"en":"A problem is often acted on only after its seriousness is being realised.","zh":"問題的嚴重性往往在正被認識到之後，才會有人採取行動。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":8},{"front":"global climate","meaning":"全球氣候","examples":[{"en":"Global climate continues to change abruptly.","zh":"全球氣候繼續突然改變。"},{"en":"Global climate means the overall climate patterns of the whole Earth.","zh":"全球氣候是指整個地球的整體氣候模式。"},{"en":"Scientists study global climate by measuring temperature, rainfall, ice, and ocean changes.","zh":"科學家透過量度氣溫、降雨、冰層和海洋變化來研究全球氣候。"},{"en":"Changes in global climate can affect farms, forests, cities, and coastlines.","zh":"全球氣候變化會影響農田、森林、城市和海岸線。"},{"en":"Tree rings help researchers understand how global climate has shifted over time.","zh":"樹輪幫助研究人員理解全球氣候如何隨時間轉變。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":8},{"front":"undergo atmospheric change","meaning":"經歷大氣變化","examples":[{"en":"Our global climate continues to undergo atmospheric change.","zh":"全球氣候繼續經歷大氣變化。"},{"en":"To undergo atmospheric change means to experience changes in air, temperature, gases, or weather patterns.","zh":"經歷大氣變化是指經歷空氣、溫度、氣體或天氣模式的改變。"},{"en":"A region may undergo atmospheric change when pollution and warming alter local weather.","zh":"當污染和暖化改變本地天氣時，一個地區可能經歷大氣變化。"},{"en":"Forests respond when the atmosphere undergoes changes in carbon dioxide and temperature.","zh":"當大氣中的二氧化碳和溫度發生變化時，森林會作出反應。"},{"en":"Scientists monitor ancient trees to see how they react as the climate undergoes atmospheric change.","zh":"科學家監測古樹，以了解氣候經歷大氣變化時它們如何反應。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":8},{"front":"abrupt atmospheric change","meaning":"突然的大氣變化","examples":[{"en":"The trees respond to abrupt atmospheric change.","zh":"這些樹對突然的大氣變化作出反應。"},{"en":"Abrupt atmospheric change means sudden change in air or climate conditions.","zh":"突然的大氣變化是指空氣或氣候條件突然改變。"},{"en":"Abrupt atmospheric change can disturb crops if temperatures shift too quickly.","zh":"如果氣溫轉變太快，突然的大氣變化可能干擾農作物。"},{"en":"Animals may struggle when abrupt atmospheric change alters their habitat.","zh":"當突然的大氣變化改變棲息地時，動物可能難以適應。"},{"en":"Tree rings can show whether past forests experienced abrupt atmospheric change.","zh":"樹輪可以顯示過去森林是否經歷突然的大氣變化。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":8},{"front":"ancient scribes","meaning":"古老記錄者","examples":[{"en":"The passage describes bristlecones as ancient scribes.","zh":"文章把刺果松描述為古老記錄者。"},{"en":"Ancient scribes were people who recorded information long ago; here, the phrase describes trees that record the past.","zh":"古代書吏是很久以前記錄資訊的人；在這裡，這個短語描述記錄過去的樹。"},{"en":"A diary can act like a private scribe by recording daily events.","zh":"日記可以像私人記錄者一樣記下每日事件。"},{"en":"Bristlecones are called ancient scribes because their rings write a natural history of climate.","zh":"刺果松被稱為古老記錄者，因為它們的年輪寫下一部自然氣候史。"},{"en":"This metaphor helps readers see the trees as record-keepers, not just plants.","zh":"這個比喻幫助讀者把這些樹看成記錄者，而不只是植物。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":8},{"front":"continue to respond","meaning":"繼續作出反應","examples":[{"en":"These ancient trees continue to respond to climate change.","zh":"這些古樹繼續對氣候變化作出反應。"},{"en":"To continue to respond means to keep reacting to something over time.","zh":"繼續作出反應是指隨時間持續對某事作出回應。"},{"en":"A patient may continue to respond well to treatment after several weeks.","zh":"病人在數星期後可能繼續對治療有良好反應。"},{"en":"Plants continue to respond to changes in light, water, and temperature.","zh":"植物繼續對光線、水分和溫度變化作出反應。"},{"en":"Bristlecone pines continue to respond to climate even after thousands of years.","zh":"即使已存活數千年，刺果松仍繼續對氣候作出反應。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":8},{"front":"rings of wood","meaning":"木質年輪","examples":[{"en":"Rings of wood reveal the trees’ response to climate.","zh":"木質年輪顯示樹木對氣候的反應。"},{"en":"Rings of wood are circular layers formed inside a tree as it grows.","zh":"木質年輪是樹木生長時在內部形成的圓形層。"},{"en":"A cut log may show rings of wood that mark each year of growth.","zh":"被切開的木材可能顯示標記每年生長的木質年輪。"},{"en":"Rings of wood can become narrow when the tree grows under stress.","zh":"當樹木在壓力下生長時，木質年輪可能變窄。"},{"en":"Scientists read rings of wood like pages in a natural record book.","zh":"科學家像閱讀自然記錄書的頁面一樣閱讀木質年輪。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":8},{"front":"formed each year","meaning":"每年形成","examples":[{"en":"Rings of wood are formed each year.","zh":"木質年輪每年形成。"},{"en":"Formed each year means created once every year as part of a regular cycle.","zh":"每年形成是指作為規律循環的一部分，每年創造一次。"},{"en":"School records are formed each year when teachers report student progress.","zh":"老師報告學生進展時，學校記錄每年形成。"},{"en":"Tree rings formed each year allow researchers to count time from growth patterns.","zh":"每年形成的樹輪讓研究人員從生長模式計算時間。"},{"en":"Because the rings are formed each year, they can act like natural calendars.","zh":"因為年輪每年形成，它們可以像自然日曆一樣。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":8},{"front":"reveal the trees’ response to","meaning":"顯示樹木對……的反應","examples":[{"en":"Tree rings reveal the trees’ response to climatic conditions.","zh":"樹輪顯示樹木對氣候條件的反應。"},{"en":"To reveal the trees’ response to something means to show how the trees reacted to it.","zh":"顯示樹木對某事的反應，是指展示樹木如何對它作出回應。"},{"en":"Wilting leaves may reveal a plant’s response to lack of water.","zh":"枯萎葉片可能顯示植物對缺水的反應。"},{"en":"Tree rings reveal the trees’ response to drought, cold, or warmth.","zh":"樹輪顯示樹木對乾旱、寒冷或溫暖的反應。"},{"en":"Scientists study growth patterns because they reveal the trees’ response to environmental change.","zh":"科學家研究生長模式，因為它們顯示樹木對環境變化的反應。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":8},{"front":"climatic conditions","meaning":"氣候條件","examples":[{"en":"Tree rings record climatic conditions during each growing season.","zh":"樹輪記錄每個生長季節的氣候條件。"},{"en":"Climatic conditions are weather-related features such as temperature, rainfall, wind, and dryness over time.","zh":"氣候條件是指一段時間內與天氣相關的特徵，例如氣溫、降雨、風和乾燥程度。"},{"en":"Farmers choose crops according to local climatic conditions.","zh":"農民根據本地氣候條件選擇農作物。"},{"en":"Bad climatic conditions can reduce harvests and slow tree growth.","zh":"惡劣氣候條件會減少收成並減慢樹木生長。"},{"en":"Tree rings are useful because they preserve evidence of past climatic conditions.","zh":"樹輪有用，因為它們保存過去氣候條件的證據。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":8},{"front":"particular growing season","meaning":"某個特定生長季節","examples":[{"en":"Each ring reflects conditions during a particular growing season.","zh":"每個年輪反映某個特定生長季節的條件。"},{"en":"A particular growing season is one specific period in which plants grow during a year.","zh":"某個特定生長季節是指一年中植物生長的某一具體時期。"},{"en":"A farmer may remember a particular growing season because heavy rain damaged the crops.","zh":"農民可能記得某個特定生長季節，因為大雨破壞了農作物。"},{"en":"A tree ring can show whether a particular growing season was dry or favourable.","zh":"樹輪可以顯示某個特定生長季節是乾旱還是有利。"},{"en":"Studying many rings lets scientists compare one particular growing season with another.","zh":"研究許多年輪讓科學家比較不同的特定生長季節。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":8},{"front":"in their persistence","meaning":"在其長久存活中","examples":[{"en":"In their persistence, bristlecones have left us records of the past.","zh":"在其長久存活中，刺果松為我們留下過去的記錄。"},{"en":"In their persistence means through their long, continued survival or effort.","zh":"在其長久存活中，是指透過長期持續的生存或努力。"},{"en":"In their persistence, community volunteers slowly rebuilt the old library.","zh":"在社區義工的堅持中，他們慢慢重建了舊圖書館。"},{"en":"Trees show persistence when they keep growing despite wind, cold, and drought.","zh":"樹木在面對強風、寒冷和乾旱仍繼續生長時，就展現了堅持。"},{"en":"Bristlecones preserve history in their persistence because they live across many centuries.","zh":"刺果松在其長久存活中保存歷史，因為它們跨越許多世紀。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":9},{"front":"natural recordings of the past","meaning":"過去的自然記錄","examples":[{"en":"Bristlecones have left us natural recordings of the past.","zh":"刺果松為我們留下過去的自然記錄。"},{"en":"Natural recordings of the past are evidence preserved by nature rather than written by people.","zh":"過去的自然記錄是由大自然保存，而不是由人書寫的證據。"},{"en":"Ice cores, fossils, and tree rings can be natural recordings of the past.","zh":"冰芯、化石和樹輪可以是過去的自然記錄。"},{"en":"Natural recordings of the past help scientists study periods before human records existed.","zh":"過去的自然記錄幫助科學家研究人類記錄出現前的時期。"},{"en":"Bristlecone rings are natural recordings of the past because they store climate information year by year.","zh":"刺果松年輪是過去的自然記錄，因為它們逐年儲存氣候資訊。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":9},{"front":"markers of the present","meaning":"現在的標記","examples":[{"en":"The trees provide markers of the present.","zh":"這些樹提供現在的標記。"},{"en":"Markers of the present are signs that show what conditions are like now.","zh":"現在的標記是顯示目前情況的跡象。"},{"en":"Current traffic levels can be markers of the present state of a city’s transport system.","zh":"目前交通量可以是城市交通系統現況的標記。"},{"en":"Today’s tree growth can act as a marker of the present climate.","zh":"今天的樹木生長可以作為目前氣候的標記。"},{"en":"Scientists compare markers of the present with records of the past to see what has changed.","zh":"科學家把現在的標記與過去記錄比較，以了解有何改變。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":9},{"front":"clues to the future","meaning":"未來的線索","examples":[{"en":"The trees may provide clues to the future.","zh":"這些樹可能提供未來的線索。"},{"en":"Clues to the future are signs that help people guess what may happen later.","zh":"未來的線索是幫助人們推測日後可能發生甚麼的跡象。"},{"en":"Falling school enrolment may provide clues to the future need for classrooms.","zh":"學校收生下降可能提供未來課室需求的線索。"},{"en":"Changes in tree growth may provide clues to the future effects of climate change.","zh":"樹木生長變化可能提供氣候變化未來影響的線索。"},{"en":"Clues to the future are not certain predictions, but they help people prepare.","zh":"未來的線索不是確定預測，但能幫助人們準備。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":9},{"front":"species’ name originates from","meaning":"物種名稱源自","examples":[{"en":"The species’ name originates from the appearance of its cones.","zh":"該物種名稱源自其球果的外觀。"},{"en":"If a species’ name originates from something, that feature is the source of the name.","zh":"如果物種名稱源自某事，即是該特徵是名稱的來源。"},{"en":"A bird’s name may originate from the colour of its feathers.","zh":"一種鳥的名字可能源自其羽毛顏色。"},{"en":"The name of a plant may originate from its shape, smell, or place of discovery.","zh":"植物名稱可能源自其形狀、氣味或發現地點。"},{"en":"Knowing where a species’ name originates from can help students remember its features.","zh":"知道物種名稱源自何處，可以幫助學生記住其特徵。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":9},{"front":"unusual cones and needles","meaning":"不尋常的球果和針葉","examples":[{"en":"The name comes from the tree’s unusual cones and needles.","zh":"這個名稱來自該樹不尋常的球果和針葉。"},{"en":"Unusual cones and needles are distinctive seed structures and leaf-like parts that look different from ordinary pines.","zh":"不尋常的球果和針葉，是指與普通松樹不同的獨特種子結構和葉狀部分。"},{"en":"A nature guide may point out unusual cones and needles to help visitors identify a tree.","zh":"自然導賞員可能指出不尋常的球果和針葉，幫助遊客辨認樹木。"},{"en":"Unusual cones and needles can become important features for naming a species.","zh":"不尋常的球果和針葉可以成為命名物種的重要特徵。"},{"en":"Bristlecone pines are easy to recognise partly because of their unusual cones and needles.","zh":"刺果松容易辨認，部分原因是其不尋常的球果和針葉。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":9},{"front":"pale needles","meaning":"淺色針葉","examples":[{"en":"The bristlecone’s short, pale needles are trademarks of the species.","zh":"刺果松短而淺色的針葉是該物種的標誌性特徵。"},{"en":"Pale needles are light-coloured needle-like leaves on certain conifer trees.","zh":"淺色針葉是某些針葉樹上顏色較淡的針狀葉。"},{"en":"A hiker may notice pale needles when trying to identify a bristlecone pine.","zh":"行山者嘗試辨認刺果松時，可能注意到淺色針葉。"},{"en":"Pale needles can reflect adaptation to bright, dry mountain environments.","zh":"淺色針葉可以反映對明亮乾燥山區環境的適應。"},{"en":"The pale needles of bristlecone pines help make the species visually distinctive.","zh":"刺果松的淺色針葉令該物種在外觀上很有特色。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":9},{"front":"trademarks","meaning":"標誌性特徵","examples":[{"en":"The short needles are trademarks of the bristlecone pine.","zh":"短針葉是刺果松的標誌性特徵。"},{"en":"Trademarks are distinctive features that make something easily recognisable.","zh":"標誌性特徵是令某事物容易被辨認的獨特特色。"},{"en":"A restaurant’s red sign and special sauce may become its trademarks.","zh":"餐廳的紅色招牌和特製醬汁可能成為其標誌性特徵。"},{"en":"A singer’s voice can be one of their trademarks.","zh":"歌手的聲音可以是其標誌性特徵之一。"},{"en":"In nature, unusual cones and needles can be trademarks of a tree species.","zh":"在自然界中，不尋常的球果和針葉可以是樹種的標誌性特徵。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":9},{"front":"bunching together","meaning":"聚集在一起","examples":[{"en":"The needles bunch together to form foxtail-like bundles.","zh":"針葉聚集在一起，形成像狐尾般的束狀。"},{"en":"Bunching together means gathering closely in a group.","zh":"聚集在一起是指緊密地聚成一群。"},{"en":"Students may bunch together near the door before class begins.","zh":"學生可能在上課前聚集在門口。"},{"en":"Leaves bunching together can help protect a plant from losing moisture.","zh":"葉片聚集在一起可以幫助植物防止水分流失。"},{"en":"The bristlecone’s needles are distinctive because they bunch together in tight bundles.","zh":"刺果松的針葉很有特色，因為它們緊密聚集成束。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":9},{"front":"foxtail-like bundles","meaning":"像狐尾般的束狀","examples":[{"en":"The needles form foxtail-like bundles.","zh":"針葉形成像狐尾般的束狀。"},{"en":"Foxtail-like bundles are tight groups that look similar to the bushy tail of a fox.","zh":"像狐尾般的束狀，是指看起來像狐狸蓬鬆尾巴的緊密群組。"},{"en":"A child might describe a plant’s soft seed head as a foxtail-like bundle.","zh":"孩子可能把植物柔軟的種子頭描述為像狐尾般的束狀。"},{"en":"Foxtail-like bundles help students imagine the shape of the needles clearly.","zh":"像狐尾般的束狀幫助學生清楚想像針葉形狀。"},{"en":"The phrase is visual because it compares plant structure with something familiar.","zh":"這個短語很有畫面感，因為它把植物結構與熟悉事物作比較。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":9},{"front":"conifer needles","meaning":"針葉樹針葉","examples":[{"en":"Conifer needles often cluster together to reduce water loss.","zh":"針葉樹針葉常聚集成簇，以減少水分流失。"},{"en":"Conifer needles are the narrow, needle-shaped leaves of cone-bearing trees.","zh":"針葉樹針葉是結球果樹木上的狹長針狀葉。"},{"en":"Pine trees, firs, and spruces all have conifer needles.","zh":"松樹、冷杉和雲杉都有針葉樹針葉。"},{"en":"Conifer needles help many trees survive cold or dry conditions.","zh":"針葉樹針葉幫助許多樹木在寒冷或乾燥條件下生存。"},{"en":"Unlike broad leaves, conifer needles often lose less water.","zh":"與闊葉不同，針葉樹針葉通常流失較少水分。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":9},{"front":"specialized leaves","meaning":"特化葉","examples":[{"en":"Conifer needles are specialized leaves.","zh":"針葉樹針葉是特化葉。"},{"en":"Specialized leaves are leaves adapted for a particular function or environment.","zh":"特化葉是為特定功能或環境而適應的葉片。"},{"en":"Cactus spines are specialized leaves that help reduce water loss.","zh":"仙人掌刺是特化葉，有助減少水分流失。"},{"en":"Specialized leaves can protect plants from heat, insects, or dryness.","zh":"特化葉可以保護植物免受高溫、昆蟲或乾燥影響。"},{"en":"Bristlecone needles are specialized leaves because they help the tree survive harsh conditions.","zh":"刺果松針葉是特化葉，因為它們幫助樹木在嚴酷條件下生存。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":10},{"front":"cluster together","meaning":"聚集成簇","examples":[{"en":"The leaves cluster together to shelter the stomata.","zh":"葉片聚集成簇，以保護氣孔。"},{"en":"To cluster together means to gather closely in a group.","zh":"聚集成簇是指緊密地聚在一起成為一組。"},{"en":"People cluster together under a shelter when it starts raining.","zh":"開始下雨時，人們會聚集在遮蔽物下。"},{"en":"Flowers that cluster together may attract more insects for pollination.","zh":"聚集成簇的花朵可能吸引更多昆蟲授粉。"},{"en":"Needles cluster together in bristlecone pines to reduce exposure and save moisture.","zh":"刺果松針葉聚集成簇，以減少暴露並保存水分。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":10},{"front":"shelter the stomata","meaning":"保護氣孔","examples":[{"en":"The needles shelter the stomata to reduce moisture loss.","zh":"針葉保護氣孔，以減少水分流失。"},{"en":"To shelter the stomata means to protect the tiny openings on leaves from drying conditions.","zh":"保護氣孔是指保護葉片上的微小開口免受乾燥條件影響。"},{"en":"Some plants shelter the stomata by curling their leaves during hot weather.","zh":"有些植物在炎熱天氣把葉片捲起，以保護氣孔。"},{"en":"Sheltering the stomata helps plants keep water inside their tissues.","zh":"保護氣孔有助植物把水分留在組織內。"},{"en":"Bristlecone needles shelter the stomata so the tree can survive dry mountain air.","zh":"刺果松針葉保護氣孔，使樹能在乾燥山區空氣中生存。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":10},{"front":"very little moisture is lost","meaning":"幾乎不流失水分","examples":[{"en":"Very little moisture is lost through the needles.","zh":"幾乎沒有水分透過針葉流失。"},{"en":"If very little moisture is lost, only a small amount of water escapes.","zh":"如果幾乎不流失水分，即是只有很少水分逃走。"},{"en":"A sealed bottle keeps drinks fresh because very little moisture is lost.","zh":"密封瓶令飲品保持新鮮，因為幾乎不流失水分。"},{"en":"Plants survive dry weather better when very little moisture is lost from their leaves.","zh":"當葉片幾乎不流失水分時，植物較能在乾燥天氣中生存。"},{"en":"Bristlecone needles are useful because very little moisture is lost through them.","zh":"刺果松針葉有用，因為幾乎沒有水分透過它們流失。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":10},{"front":"photosynthesize","meaning":"進行光合作用","examples":[{"en":"This adaptation helps the bristlecone photosynthesize in brutal months.","zh":"這種適應幫助刺果松在嚴酷月份進行光合作用。"},{"en":"To photosynthesize means to use sunlight to make food from carbon dioxide and water.","zh":"進行光合作用是指利用陽光，把二氧化碳和水製成食物。"},{"en":"Plants photosynthesize through their leaves when they receive enough light.","zh":"植物在獲得足夠光線時，透過葉片進行光合作用。"},{"en":"If a plant cannot photosynthesize, it cannot produce enough energy to grow.","zh":"如果植物不能進行光合作用，就不能產生足夠能量生長。"},{"en":"Bristlecone pines can photosynthesize during harsh periods because their needles remain useful for many years.","zh":"刺果松能在嚴酷時期進行光合作用，因為其針葉多年來仍有用。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":10},{"front":"particularly brutal months","meaning":"特別嚴酷的月份","examples":[{"en":"Bristlecones can photosynthesize during particularly brutal months.","zh":"刺果松可以在特別嚴酷的月份進行光合作用。"},{"en":"Particularly brutal months are months with especially severe weather or living conditions.","zh":"特別嚴酷的月份是指天氣或生活條件尤其惡劣的月份。"},{"en":"Homeless people need extra support during particularly brutal months of winter.","zh":"在冬季特別嚴酷的月份，無家者需要額外支援。"},{"en":"Plants may stop growing during particularly brutal months if water and warmth disappear.","zh":"如果水分和溫暖消失，植物可能在特別嚴酷的月份停止生長。"},{"en":"Bristlecones survive particularly brutal months because their needles conserve water and energy.","zh":"刺果松能熬過特別嚴酷的月份，因為其針葉保存水分和能量。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":10},{"front":"saving the energy of","meaning":"節省……所需能量","examples":[{"en":"The adaptation saves the energy of constant needle replacement.","zh":"這種適應節省不斷更換針葉所需的能量。"},{"en":"Saving the energy of something means avoiding the effort or resources needed for that activity.","zh":"節省某事所需能量，是指避免該活動所需的努力或資源。"},{"en":"Planning meals ahead saves the energy of deciding what to cook every night.","zh":"預先計劃膳食可以節省每晚決定煮甚麼所需的能量。"},{"en":"Reusing study notes saves the energy of writing everything again.","zh":"重用溫習筆記可以節省重新書寫所有內容所需的能量。"},{"en":"Long-lasting needles save the energy of replacing leaves each year.","zh":"持久針葉節省每年更換葉片所需的能量。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":10},{"front":"constant needle replacement","meaning":"不斷更換針葉","examples":[{"en":"The tree avoids the need for constant needle replacement.","zh":"這棵樹避免了不斷更換針葉的需要。"},{"en":"Constant needle replacement means repeatedly growing new needles to replace old ones.","zh":"不斷更換針葉是指反覆長出新針葉以取代舊針葉。"},{"en":"A plant that needs constant leaf replacement uses a lot of energy.","zh":"需要不斷更換葉片的植物會使用大量能量。"},{"en":"Avoiding constant needle replacement helps bristlecones survive when nutrients are scarce.","zh":"避免不斷更換針葉幫助刺果松在養分稀少時生存。"},{"en":"Long-lived needles are useful because constant needle replacement would be costly in harsh conditions.","zh":"長壽針葉很有用，因為在嚴酷條件下不斷更換針葉成本很高。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":10},{"front":"stable supply of chlorophyll","meaning":"穩定的葉綠素供應","examples":[{"en":"The needles provide a stable supply of chlorophyll.","zh":"針葉提供穩定的葉綠素供應。"},{"en":"A stable supply of chlorophyll means a steady amount of the green substance plants use for photosynthesis.","zh":"穩定的葉綠素供應是指植物用於光合作用的綠色物質保持穩定數量。"},{"en":"Healthy leaves give a plant a stable supply of chlorophyll for making food.","zh":"健康葉片為植物提供穩定的葉綠素供應，以製造食物。"},{"en":"If leaves are damaged often, the stable supply of chlorophyll may be reduced.","zh":"如果葉片經常受損，穩定的葉綠素供應可能減少。"},{"en":"Bristlecone needles help the tree maintain a stable supply of chlorophyll over many years.","zh":"刺果松針葉幫助樹木多年維持穩定的葉綠素供應。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":10},{"front":"relatively large in size","meaning":"體積相對較大","examples":[{"en":"Bristlecone seeds are relatively large in size.","zh":"刺果松種子的體積相對較大。"},{"en":"Relatively large in size means bigger than expected when compared with similar things.","zh":"體積相對較大是指與相似事物比較時，比預期更大。"},{"en":"A seed may be relatively large in size compared with seeds from related plants.","zh":"與相關植物的種子相比，一粒種子的體積可能相對較大。"},{"en":"Relatively large seeds can give young plants more stored energy at the start.","zh":"體積相對較大的種子可以在開始時給幼苗更多儲存能量。"},{"en":"The phrase does not mean huge; it means large in comparison with a relevant group.","zh":"這個短語不代表巨大；它表示與相關群組相比較大。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":10},{"front":"first reproduce","meaning":"首次繁殖","examples":[{"en":"Bristlecones first reproduce between thirty and seventy-five years old.","zh":"刺果松在三十至七十五歲之間首次繁殖。"},{"en":"To first reproduce means to produce offspring or seeds for the first time.","zh":"首次繁殖是指第一次產生後代或種子。"},{"en":"Some animals first reproduce only after reaching full maturity.","zh":"有些動物只有在完全成熟後才首次繁殖。"},{"en":"Trees that first reproduce late may invest many years in survival before making seeds.","zh":"首次繁殖較晚的樹，可能先投入多年時間於生存，再產生種子。"},{"en":"Bristlecones first reproduce much later than many short-lived plants.","zh":"刺果松首次繁殖的時間比許多短壽植物晚得多。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":10},{"front":"germination rates","meaning":"發芽率","examples":[{"en":"Germination rates are generally high.","zh":"發芽率通常很高。"},{"en":"Germination rates show how many seeds successfully begin to grow.","zh":"發芽率顯示有多少種子成功開始生長。"},{"en":"Gardeners check germination rates to know whether their seeds are healthy.","zh":"園丁檢查發芽率，以了解種子是否健康。"},{"en":"High germination rates mean more young plants can appear after seeds are planted.","zh":"高發芽率意味著種子種下後可以出現更多幼苗。"},{"en":"Low germination rates may result from poor soil, cold weather, or old seeds.","zh":"低發芽率可能由貧瘠土壤、寒冷天氣或舊種子造成。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":11},{"front":"in part because","meaning":"部分原因是","examples":[{"en":"Germination rates are high in part because seeds require little stratification.","zh":"發芽率高，部分原因是種子幾乎不需要層積處理。"},{"en":"In part because means partly because, but not as the only reason.","zh":"in part because 是指部分原因是，但不是唯一原因。"},{"en":"Students improved in part because they practised every day.","zh":"學生進步了，部分原因是他們每天練習。"},{"en":"The shop became popular in part because it was near the station.","zh":"這間店受歡迎，部分原因是它靠近車站。"},{"en":"We use in part because when several causes may explain one result.","zh":"當幾個原因可能解釋一個結果時，我們使用 in part because。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":11},{"front":"little to no initial stratification","meaning":"幾乎不需要初始層積處理","examples":[{"en":"The seeds require little to no initial stratification.","zh":"這些種子幾乎不需要初始層積處理。"},{"en":"Little to no initial stratification means the seeds need almost no early cold or moist treatment before germinating.","zh":"幾乎不需要初始層積處理，是指種子在發芽前幾乎不需要早期低溫或濕潤處理。"},{"en":"Some garden seeds need cold treatment, but others need little to no initial stratification.","zh":"有些園藝種子需要低溫處理，但另一些幾乎不需要初始層積處理。"},{"en":"Seeds that need little to no initial stratification may begin growing more easily.","zh":"幾乎不需要初始層積處理的種子，可能較容易開始生長。"},{"en":"This feature helps explain why bristlecone seeds can have high germination rates.","zh":"這個特徵有助解釋為何刺果松種子可以有高發芽率。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":11},{"front":"physical characteristic","meaning":"身體特徵；物理特徵","examples":[{"en":"The ratio of living to deadwood is an intriguing physical characteristic.","zh":"活木與死木的比例是一個耐人尋味的物理特徵。"},{"en":"A physical characteristic is a visible or measurable feature of a body, object, or organism.","zh":"物理特徵是身體、物件或生物可見或可量度的特色。"},{"en":"Height, colour, shape, and texture are physical characteristics.","zh":"高度、顏色、形狀和質感都是物理特徵。"},{"en":"Scientists study a tree’s physical characteristics to understand how it survives.","zh":"科學家研究樹木的物理特徵，以理解它如何生存。"},{"en":"A physical characteristic can be important if it affects growth, protection, or reproduction.","zh":"如果物理特徵影響生長、保護或繁殖，它就可能很重要。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":11},{"front":"mature bristlecone","meaning":"成熟刺果松","examples":[{"en":"A mature bristlecone may have both living and deadwood.","zh":"成熟刺果松可能同時有活木和死木。"},{"en":"A mature bristlecone is a fully developed bristlecone pine.","zh":"成熟刺果松是已完全發育的刺果松。"},{"en":"A mature bristlecone may look partly dead but still continue growing.","zh":"成熟刺果松可能看起來部分死亡，但仍繼續生長。"},{"en":"Mature bristlecones are valuable for study because they show long-term survival features.","zh":"成熟刺果松對研究有價值，因為它們顯示長期生存特徵。"},{"en":"Unlike a young tree, a mature bristlecone may carry thousands of years of growth history.","zh":"與幼樹不同，成熟刺果松可能承載數千年的生長歷史。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":11},{"front":"ratio of living to deadwood","meaning":"活木與死木的比例","examples":[{"en":"The ratio of living to deadwood relates to old age.","zh":"活木與死木的比例與高齡有關。"},{"en":"The ratio of living to deadwood means the amount of living wood compared with dead wood in a tree.","zh":"活木與死木的比例是指樹中活木相對於死木的數量。"},{"en":"A tree with much deadwood but some living strips may still survive.","zh":"一棵有大量死木但仍有一些活木帶的樹，仍可能生存。"},{"en":"This ratio can show how a tree reduces living tissue while remaining alive.","zh":"這個比例可以顯示樹木如何減少活組織而仍然存活。"},{"en":"In bristlecones, the ratio of living to deadwood helps explain their unusual aging pattern.","zh":"在刺果松中，活木與死木的比例有助解釋其不尋常的老化模式。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":11},{"front":"harsh sites","meaning":"嚴酷地點","examples":[{"en":"The strip-bark trait is common on harsh sites.","zh":"條狀樹皮特徵在嚴酷地點很常見。"},{"en":"Harsh sites are places with difficult natural conditions such as poor soil, wind, cold, or drought.","zh":"嚴酷地點是有貧瘠土壤、強風、寒冷或乾旱等困難自然條件的地方。"},{"en":"Builders need special materials for harsh sites near the sea because salt and wind damage structures.","zh":"建築工人在海邊嚴酷地點需要特殊材料，因為鹽分和風會破壞結構。"},{"en":"Plants on harsh sites often grow slowly and develop protective features.","zh":"在嚴酷地點的植物常生長緩慢並發展保護特徵。"},{"en":"Bristlecones survive on harsh sites where many other trees cannot grow.","zh":"刺果松能在許多其他樹無法生長的嚴酷地點生存。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":11},{"front":"relates to old age","meaning":"與高齡有關","examples":[{"en":"The ratio of living to deadwood relates to old age.","zh":"活木與死木的比例與高齡有關。"},{"en":"If something relates to old age, it is connected with aging or long life.","zh":"如果某事與高齡有關，即是它與老化或長壽相連。"},{"en":"Joint pain often relates to old age, though young people can also have it.","zh":"關節痛常與高齡有關，雖然年輕人也可能有。"},{"en":"Slow growth may relate to old age in certain tree species.","zh":"在某些樹種中，緩慢生長可能與高齡有關。"},{"en":"Scientists study features that relate to old age to understand why some organisms live longer.","zh":"科學家研究與高齡有關的特徵，以理解為何某些生物更長壽。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":11},{"front":"strip-bark trait","meaning":"條狀樹皮特徵","examples":[{"en":"The strip-bark trait is adaptive in older trees.","zh":"條狀樹皮特徵在老樹中具有適應作用。"},{"en":"The strip-bark trait is a condition in which only narrow strips of bark remain alive on the tree.","zh":"條狀樹皮特徵是指樹上只有狹窄樹皮帶仍然存活的狀態。"},{"en":"A bristlecone with the strip-bark trait may look partly dead but still survive.","zh":"具有條狀樹皮特徵的刺果松可能看起來部分死亡，但仍能生存。"},{"en":"The strip-bark trait reduces the amount of living tissue that needs water and nutrients.","zh":"條狀樹皮特徵減少需要水分和養分的活組織數量。"},{"en":"This trait helps older bristlecones survive in dry, harsh environments.","zh":"這種特徵幫助老刺果松在乾燥嚴酷環境中生存。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":11},{"front":"adaptive","meaning":"有適應作用的","examples":[{"en":"The strip-bark trait is adaptive in harsh conditions.","zh":"條狀樹皮特徵在嚴酷條件下有適應作用。"},{"en":"Adaptive means useful for survival or adjustment in a particular environment.","zh":"有適應作用的是指對在特定環境中生存或調整有幫助。"},{"en":"Thick fur is adaptive for animals living in cold regions.","zh":"厚毛對生活在寒冷地區的動物有適應作用。"},{"en":"An adaptive habit helps people cope with new work or study demands.","zh":"有適應作用的習慣幫助人應付新的工作或學習要求。"},{"en":"In bristlecone pines, slow growth is adaptive because resources are limited.","zh":"在刺果松中，緩慢生長有適應作用，因為資源有限。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":11},{"front":"occurs as a result of","meaning":"由……引起","examples":[{"en":"This condition occurs as a result of cambium dieback.","zh":"這種狀況由形成層枯死引起。"},{"en":"Occurs as a result of means happens because of a particular cause.","zh":"由某事引起，是指因某個特定原因而發生。"},{"en":"Traffic congestion often occurs as a result of too many cars on narrow roads.","zh":"交通擠塞常由狹窄道路上車輛太多引起。"},{"en":"Tooth decay may occur as a result of poor brushing and too much sugar.","zh":"蛀牙可能由刷牙不足和糖分過多引起。"},{"en":"In trees, exposed deadwood can occur as a result of tissue damage.","zh":"在樹木中，外露死木可能由組織損傷引起。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":11},{"front":"cambium dieback","meaning":"形成層枯死","examples":[{"en":"Cambium dieback exposes areas of the bole.","zh":"形成層枯死使樹幹部分區域外露。"},{"en":"Cambium dieback is the death or retreat of the living growth layer in parts of a tree.","zh":"形成層枯死是指樹木部分活生長層死亡或後退。"},{"en":"A tree with cambium dieback may lose bark and expose deadwood.","zh":"有形成層枯死的樹可能失去樹皮並露出死木。"},{"en":"Cambium dieback can reduce the living surface that needs water.","zh":"形成層枯死可以減少需要水分的活表面。"},{"en":"In bristlecones, cambium dieback may help create the strip-bark pattern.","zh":"在刺果松中，形成層枯死可能有助形成條狀樹皮模式。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":12},{"front":"erodes and exposes","meaning":"侵蝕並露出","examples":[{"en":"Cambium dieback erodes and exposes certain areas of the bole.","zh":"形成層枯死侵蝕並露出樹幹某些區域。"},{"en":"Erodes and exposes means gradually wears away a surface and leaves what is underneath visible.","zh":"侵蝕並露出是指逐漸磨走表面，令下方部分可見。"},{"en":"Strong waves erode and expose rocks along the coast.","zh":"強浪侵蝕並露出海岸岩石。"},{"en":"Wind can erode and expose soil around plant roots.","zh":"風可以侵蝕並露出植物根部周圍的土壤。"},{"en":"When bark erodes and exposes wood, the tree’s inner structure becomes visible.","zh":"當樹皮被侵蝕並露出木材時，樹木內部結構會變得可見。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":12},{"front":"the bole","meaning":"樹幹","examples":[{"en":"The bole may be partly exposed by cambium dieback.","zh":"樹幹可能因形成層枯死而部分外露。"},{"en":"The bole is the main trunk of a tree.","zh":"樹幹是樹木的主要幹部。"},{"en":"A forester measures the bole to estimate a tree’s size and age.","zh":"林務人員量度樹幹，以估算樹木大小和年齡。"},{"en":"Damage to the bole can affect the whole tree because it supports branches and transport tissues.","zh":"樹幹受損可能影響整棵樹，因為它支撐樹枝和運輸組織。"},{"en":"In old bristlecones, parts of the bole may become exposed and weathered.","zh":"在老刺果松中，部分樹幹可能外露並受風化。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":12},{"front":"narrow bands of bark","meaning":"狹窄樹皮帶","examples":[{"en":"Only narrow bands of bark remain intact.","zh":"只有狹窄樹皮帶保持完整。"},{"en":"Narrow bands of bark are thin strips of bark left on a tree’s trunk.","zh":"狹窄樹皮帶是留在樹幹上的薄樹皮條。"},{"en":"A damaged tree may survive if narrow bands of bark still carry nutrients.","zh":"如果狹窄樹皮帶仍能運送養分，受損樹木可能存活。"},{"en":"Narrow bands of bark reduce the amount of living tissue the tree must support.","zh":"狹窄樹皮帶減少樹木必須支撐的活組織數量。"},{"en":"In bristlecones, narrow bands of bark are part of the strip-bark appearance.","zh":"在刺果松中，狹窄樹皮帶是條狀樹皮外觀的一部分。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":12},{"front":"remain intact","meaning":"保持完整","examples":[{"en":"Narrow bands of bark remain intact.","zh":"狹窄樹皮帶保持完整。"},{"en":"To remain intact means to stay whole, complete, or undamaged.","zh":"保持完整是指維持完整、完好或未受損。"},{"en":"The old vase remained intact after the move because it was packed carefully.","zh":"舊花瓶因包裝小心，在搬家後仍保持完整。"},{"en":"A bridge must remain intact during storms to keep people safe.","zh":"橋樑在風暴中必須保持完整，以保障人們安全。"},{"en":"Even when much bark dies, some strips may remain intact and keep the tree alive.","zh":"即使大部分樹皮死亡，有些樹皮帶仍可能保持完整並維持樹木生命。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":12},{"front":"cambial edge retreat","meaning":"形成層邊緣後退","examples":[{"en":"Cambial edge retreat has helped promote old age in bristlecone pines.","zh":"形成層邊緣後退有助促成刺果松長壽。"},{"en":"Cambial edge retreat means the living growth edge of the tree gradually pulls back or dies back.","zh":"形成層邊緣後退是指樹木活生長邊緣逐漸後退或枯死。"},{"en":"In old bristlecones, cambial edge retreat can leave only narrow living strips.","zh":"在老刺果松中，形成層邊緣後退可能只留下狹窄活木帶。"},{"en":"Cambial edge retreat may help trees survive by reducing the living area they must support.","zh":"形成層邊緣後退可能透過減少樹木必須支撐的活區域來幫助生存。"},{"en":"Scientists study cambial edge retreat to understand bristlecone longevity.","zh":"科學家研究形成層邊緣後退，以理解刺果松長壽。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":12},{"front":"helped promote old age","meaning":"有助促成長壽","examples":[{"en":"This technique has helped promote old age in bristlecones.","zh":"這種方式有助促成刺果松長壽。"},{"en":"Helped promote old age means helped support a long lifespan.","zh":"有助促成長壽是指幫助支持漫長壽命。"},{"en":"Regular exercise and safe housing may help promote old age in humans.","zh":"規律運動和安全住屋可能有助促成人類長壽。"},{"en":"Slow growth can help promote old age in trees by reducing stress on resources.","zh":"緩慢生長可以透過減少資源壓力，有助促成樹木長壽。"},{"en":"In bristlecones, reducing living tissue may have helped promote old age.","zh":"在刺果松中，減少活組織可能有助促成長壽。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":12},{"front":"not the only reason","meaning":"並非唯一原因","examples":[{"en":"Cambial edge retreat is not the only reason for bristlecone longevity.","zh":"形成層邊緣後退並非刺果松長壽的唯一原因。"},{"en":"Not the only reason means one factor is important, but other causes also matter.","zh":"並非唯一原因是指某因素很重要，但其他原因也有影響。"},{"en":"Practice is not the only reason a student improves; feedback and rest also help.","zh":"練習並非學生進步的唯一原因；回饋和休息也有幫助。"},{"en":"Price is not the only reason customers choose a shop; service matters too.","zh":"價格並非顧客選擇店舖的唯一原因；服務也很重要。"},{"en":"Bristlecone longevity has several causes, so cambial edge retreat is not the only reason.","zh":"刺果松長壽有幾個原因，所以形成層邊緣後退並非唯一原因。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":12},{"front":"crucial to","meaning":"對……至關重要","examples":[{"en":"Compact size is crucial to the trees’ longevity.","zh":"緊湊體型對這些樹的長壽至關重要。"},{"en":"Crucial to something means extremely important for it.","zh":"對某事至關重要，是指對它極其重要。"},{"en":"Clean water is crucial to public health.","zh":"清潔食水對公共健康至關重要。"},{"en":"Clear instructions are crucial to safe laboratory work.","zh":"清晰指示對安全實驗室工作至關重要。"},{"en":"For bristlecones, small size and slow growth are crucial to survival in harsh mountains.","zh":"對刺果松而言，小體型和緩慢生長對在嚴酷山區生存至關重要。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":12},{"front":"compact size","meaning":"緊湊體型","examples":[{"en":"Compact size helps bristlecones survive.","zh":"緊湊體型幫助刺果松生存。"},{"en":"Compact size means being small, tight, and not spread out too widely.","zh":"緊湊體型是指體積較小、結構緊密且不過度伸展。"},{"en":"A compact car is useful in a crowded city because it is easy to park.","zh":"小型車在擁擠城市中很有用，因為容易泊車。"},{"en":"Compact size helps a tree stay close to limited water and resist strong winds.","zh":"緊湊體型幫助樹木接近有限水源並抵抗強風。"},{"en":"Bristlecones benefit from compact size because they do not need to support a huge crown.","zh":"刺果松受惠於緊湊體型，因為它們不需要支撐巨大的樹冠。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":12},{"front":"slow rates of growth","meaning":"緩慢生長速度","examples":[{"en":"Slow rates of growth are crucial to bristlecone longevity.","zh":"緩慢生長速度對刺果松長壽至關重要。"},{"en":"Slow rates of growth mean that an organism increases in size only gradually.","zh":"緩慢生長速度是指生物只逐漸增加大小。"},{"en":"Some children have slow rates of growth but remain healthy with proper care.","zh":"有些孩子生長速度較慢，但在適當照顧下仍然健康。"},{"en":"Slow rates of growth can produce dense, strong wood in certain trees.","zh":"緩慢生長速度可以在某些樹木中產生密實堅固的木材。"},{"en":"Bristlecones survive long partly because slow rates of growth reduce stress on resources.","zh":"刺果松能長壽，部分原因是緩慢生長速度減少資源壓力。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":12},{"front":"remaining under ten meters tall","meaning":"保持十米以下高度","examples":[{"en":"By remaining under ten meters tall, bristlecones stay close to water.","zh":"透過保持十米以下高度，刺果松能貼近水源。"},{"en":"Remaining under ten meters tall means staying shorter than ten meters in height.","zh":"保持十米以下高度是指高度維持在十米以下。"},{"en":"A tree remaining under ten meters tall is easier to support in windy conditions.","zh":"保持十米以下高度的樹，在強風條件下較容易支撐。"},{"en":"Remaining under ten meters tall helps bristlecones use limited water more efficiently.","zh":"保持十米以下高度幫助刺果松更有效使用有限水源。"},{"en":"Instead of growing very high, bristlecones survive by remaining under ten meters tall.","zh":"刺果松不是長得很高，而是透過保持十米以下高度來生存。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":13},{"front":"limited water supply","meaning":"有限水源","examples":[{"en":"Bristlecones stay close to the limited water supply.","zh":"刺果松貼近有限水源。"},{"en":"A limited water supply means only a small amount of water is available.","zh":"有限水源是指可用水量很少。"},{"en":"Villages with a limited water supply must use water carefully during dry months.","zh":"有有限水源的村莊在乾旱月份必須小心用水。"},{"en":"A limited water supply can force plants to grow slowly and conserve moisture.","zh":"有限水源會迫使植物緩慢生長並保存水分。"},{"en":"Bristlecones survive a limited water supply by staying compact and reducing water loss.","zh":"刺果松透過保持緊湊和減少水分流失，應付有限水源。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":13},{"front":"support more branches","meaning":"支撐更多樹枝","examples":[{"en":"The trees can support more branches when they remain compact.","zh":"當這些樹保持緊湊時，便能支撐更多樹枝。"},{"en":"To support more branches means to have enough strength and resources to keep more branches alive.","zh":"支撐更多樹枝是指有足夠力量和資源讓更多樹枝存活。"},{"en":"A healthy fruit tree can support more branches if it receives enough water and nutrients.","zh":"如果健康果樹獲得足夠水分和養分，就能支撐更多樹枝。"},{"en":"A compact tree may support more branches because energy is not wasted on extreme height.","zh":"緊湊樹木可能支撐更多樹枝，因為能量沒有浪費在極端高度上。"},{"en":"More branches can help a tree capture light and continue photosynthesis.","zh":"更多樹枝可以幫助樹木吸收光線並繼續光合作用。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":13},{"front":"photosynthetic activity","meaning":"光合作用活動","examples":[{"en":"More branches can support more photosynthetic activity.","zh":"更多樹枝可以支援更多光合作用活動。"},{"en":"Photosynthetic activity is the process of using sunlight to make food in plants.","zh":"光合作用活動是植物利用陽光製造食物的過程。"},{"en":"A plant with healthy leaves usually has more photosynthetic activity.","zh":"有健康葉片的植物通常有更多光合作用活動。"},{"en":"If drought damages leaves, photosynthetic activity may decrease.","zh":"如果乾旱損害葉片，光合作用活動可能減少。"},{"en":"Bristlecones need enough photosynthetic activity to survive despite slow growth.","zh":"刺果松需要足夠光合作用活動，才能在生長緩慢下生存。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":13},{"front":"combined with","meaning":"與……結合","examples":[{"en":"Slow growth combined with harsh air produces strong rings.","zh":"緩慢生長與嚴酷空氣結合，產生堅固年輪。"},{"en":"Combined with means together with another factor.","zh":"combined with 是指與另一因素一起。"},{"en":"Good teaching combined with daily practice can improve language skills quickly.","zh":"良好教學與每日練習結合，可以快速提升語言能力。"},{"en":"Cold weather combined with strong wind can make outdoor work dangerous.","zh":"寒冷天氣與強風結合，可能令戶外工作危險。"},{"en":"In bristlecones, slow growth combined with freezing air helps create dense wood.","zh":"在刺果松中，緩慢生長與冰冷空氣結合，有助形成密實木材。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":13},{"front":"freezing mountain air","meaning":"冰冷山區空氣","examples":[{"en":"Freezing mountain air helps bristlecones develop tight rings.","zh":"冰冷山區空氣幫助刺果松形成緊密年輪。"},{"en":"Freezing mountain air is very cold air found in high mountain areas.","zh":"冰冷山區空氣是高山地區非常寒冷的空氣。"},{"en":"Hikers need warm clothing when walking through freezing mountain air.","zh":"行山者穿越冰冷山區空氣時，需要保暖衣物。"},{"en":"Freezing mountain air can slow tree growth and create dense wood.","zh":"冰冷山區空氣會減慢樹木生長並形成密實木材。"},{"en":"Bristlecones endure freezing mountain air for much of the year.","zh":"刺果松一年中大部分時間承受冰冷山區空氣。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":13},{"front":"ensures that","meaning":"確保","examples":[{"en":"Slow growth ensures that bristlecones develop strong rings.","zh":"緩慢生長確保刺果松形成堅固年輪。"},{"en":"Ensures that means makes certain that something happens.","zh":"ensures that 是指確保某事會發生。"},{"en":"Wearing a seat belt ensures that passengers have better protection in a crash.","zh":"繫安全帶確保乘客在撞車時有更好保護。"},{"en":"Clear instructions ensure that students know what to do.","zh":"清晰指示確保學生知道要做甚麼。"},{"en":"Slow growth ensures that bristlecone wood becomes dense and strong over time.","zh":"緩慢生長確保刺果松木材隨時間變得密實而堅固。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":13},{"front":"tight, fibrous rings","meaning":"緊密而纖維狀的年輪","examples":[{"en":"Bristlecones develop tight, fibrous rings.","zh":"刺果松形成緊密而纖維狀的年輪。"},{"en":"Tight, fibrous rings are dense wood layers with strong fibre structure.","zh":"緊密而纖維狀的年輪是具有強纖維結構的密實木質層。"},{"en":"Slow-growing trees often form tight, fibrous rings that resist damage.","zh":"生長緩慢的樹常形成能抵抗損害的緊密而纖維狀的年輪。"},{"en":"Tight, fibrous rings can make wood stronger and less easily broken.","zh":"緊密而纖維狀的年輪可以令木材更堅固且較不易斷裂。"},{"en":"Bristlecone wood lasts long partly because of its tight, fibrous rings.","zh":"刺果松木材長久保存，部分原因是其緊密而纖維狀的年輪。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":13},{"front":"high resin content","meaning":"高樹脂含量","examples":[{"en":"The rings have a high resin content.","zh":"這些年輪有高樹脂含量。"},{"en":"High resin content means the wood contains a large amount of sticky protective substance.","zh":"高樹脂含量是指木材含有大量黏性保護物質。"},{"en":"Pine wood with high resin content may smell strong and resist decay better.","zh":"高樹脂含量的松木可能氣味濃烈，且更能抵抗腐爛。"},{"en":"High resin content can make wood harder for insects or fungi to damage.","zh":"高樹脂含量可以令木材較難被昆蟲或真菌損害。"},{"en":"Bristlecone rings are durable partly because they have high resin content.","zh":"刺果松年輪耐久，部分原因是它們有高樹脂含量。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":13},{"front":"structural strength","meaning":"結構強度","examples":[{"en":"High resin content gives the wood structural strength.","zh":"高樹脂含量賦予木材結構強度。"},{"en":"Structural strength is the ability of a material or object to support weight and resist damage.","zh":"結構強度是材料或物件支撐重量和抵抗損害的能力。"},{"en":"Bridges need structural strength so they can carry cars safely.","zh":"橋樑需要結構強度，才能安全承載車輛。"},{"en":"Wood with good structural strength is less likely to break under pressure.","zh":"具有良好結構強度的木材較不容易在壓力下斷裂。"},{"en":"Bristlecone wood gains structural strength from dense rings and resin.","zh":"刺果松木材從密實年輪和樹脂中獲得結構強度。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":13},{"front":"absence of natural disaster","meaning":"沒有天然災害","examples":[{"en":"The absence of natural disaster has protected the trees.","zh":"沒有天然災害保護了這些樹。"},{"en":"Absence of natural disaster means natural disasters have not occurred or have been very rare.","zh":"沒有天然災害是指天然災害沒有發生或非常罕見。"},{"en":"A village may grow safely for decades because of the absence of natural disaster.","zh":"一個村莊可能因沒有天然災害而安全發展數十年。"},{"en":"The absence of natural disaster allows old trees to survive without being destroyed suddenly.","zh":"沒有天然災害讓老樹不會突然被破壞，從而存活下來。"},{"en":"Fire, floods, and landslides are dangerous, so their absence helps preserve forests.","zh":"火災、洪水和山泥傾瀉都很危險，所以沒有它們有助保存森林。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":13},{"front":"safeguarded","meaning":"保護","examples":[{"en":"The absence of natural disaster has safeguarded the tree’s lifespan.","zh":"沒有天然災害保護了這棵樹的壽命。"},{"en":"Safeguarded means protected from harm, danger, or loss.","zh":"safeguarded 是指保護某物免受傷害、危險或損失。"},{"en":"Passwords safeguard personal information online.","zh":"密碼保護網上個人資料。"},{"en":"Strong building rules safeguard residents during earthquakes.","zh":"嚴格建築規則在地震中保護居民。"},{"en":"In bristlecone forests, isolation and sparse vegetation have safeguarded old trees from fire.","zh":"在刺果松森林中，孤立和稀疏植被保護老樹免受火災影響。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":14},{"front":"lengthy lifespan","meaning":"漫長壽命","examples":[{"en":"Several factors have safeguarded the bristlecone’s lengthy lifespan.","zh":"幾個因素保護了刺果松的漫長壽命。"},{"en":"A lengthy lifespan is a very long period of life.","zh":"漫長壽命是指非常長的生命時期。"},{"en":"Some turtles have a lengthy lifespan compared with many pets.","zh":"與許多寵物相比，有些龜有漫長壽命。"},{"en":"A lengthy lifespan may depend on genetics, environment, and protection from danger.","zh":"漫長壽命可能取決於基因、環境和免受危險保護。"},{"en":"Bristlecones have a lengthy lifespan because they grow slowly and avoid many natural threats.","zh":"刺果松有漫長壽命，因為它們生長緩慢並避開許多自然威脅。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":14},{"front":"due to a lack of","meaning":"由於缺乏……","examples":[{"en":"Bristlecone stands are protected from fire due to a lack of vegetation.","zh":"刺果松林分由於缺乏植被而免受火災影響。"},{"en":"Due to a lack of means because there is not enough of something.","zh":"due to a lack of 是指因為某事物不足。"},{"en":"The meeting was cancelled due to a lack of staff.","zh":"會議由於缺乏人手而取消。"},{"en":"Crops failed due to a lack of rain during summer.","zh":"農作物由於夏季缺乏降雨而失收。"},{"en":"Fires spread less easily around bristlecones due to a lack of plants on the ground.","zh":"刺果松周圍由於地面缺乏植物，火勢較不容易蔓延。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":14},{"front":"ground cover vegetation","meaning":"地被植物","examples":[{"en":"There is little ground cover vegetation around bristlecone stands.","zh":"刺果松林分周圍幾乎沒有地被植物。"},{"en":"Ground cover vegetation is low plant growth that covers the soil surface.","zh":"地被植物是覆蓋土壤表面的低矮植物。"},{"en":"Grass, moss, and small shrubs can be ground cover vegetation in a garden.","zh":"草、苔蘚和小灌木可以是花園中的地被植物。"},{"en":"Ground cover vegetation can protect soil, but it can also help fire spread if dry.","zh":"地被植物可以保護土壤，但如果乾燥，也可能幫助火勢蔓延。"},{"en":"Around bristlecones, little ground cover vegetation means less fuel for fire.","zh":"在刺果松周圍，地被植物很少意味著火災燃料較少。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":14},{"front":"evenly spaced layout","meaning":"均勻分布的排列","examples":[{"en":"An evenly spaced layout helps protect bristlecone stands from fire.","zh":"均勻分布的排列有助保護刺果松林分免受火災影響。"},{"en":"An evenly spaced layout means objects or plants are separated by regular distances.","zh":"均勻分布的排列是指物件或植物以規律距離分開。"},{"en":"Desks in an evenly spaced layout make a classroom easier to move through.","zh":"課桌均勻分布的排列令課室較容易通行。"},{"en":"Trees in an evenly spaced layout may reduce the chance of fire jumping quickly from one to another.","zh":"均勻分布的樹木可能減少火勢快速從一棵跳到另一棵的機會。"},{"en":"Bristlecone stands benefit from an evenly spaced layout because fires spread less easily.","zh":"刺果松林分受惠於均勻分布的排列，因為火災較不容易蔓延。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":14},{"front":"practically unaffected by fire","meaning":"幾乎不受火災影響","examples":[{"en":"Bristlecone stands have been practically unaffected by fire.","zh":"刺果松林分幾乎不受火災影響。"},{"en":"Practically unaffected by fire means almost not damaged by fire.","zh":"幾乎不受火災影響是指幾乎沒有被火破壞。"},{"en":"A stone wall may be practically unaffected by fire after a small kitchen accident.","zh":"小型廚房意外後，石牆可能幾乎不受火災影響。"},{"en":"Forests with little dry vegetation may be practically unaffected by fire spread.","zh":"乾燥植被很少的森林可能幾乎不受火勢蔓延影響。"},{"en":"Bristlecone stands are practically unaffected by fire because there is little fuel around them.","zh":"刺果松林分幾乎不受火災影響，因為周圍燃料很少。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":14},{"front":"lack of vegetation","meaning":"缺乏植被","examples":[{"en":"The lack of vegetation also means a lack of competition.","zh":"缺乏植被也意味著缺乏競爭。"},{"en":"Lack of vegetation means there are few plants growing in an area.","zh":"缺乏植被是指某地區生長的植物很少。"},{"en":"A lack of vegetation on a hill can lead to soil erosion after rain.","zh":"山坡缺乏植被可能在下雨後導致土壤侵蝕。"},{"en":"In bristlecone habitats, lack of vegetation reduces fire fuel and competition for water.","zh":"在刺果松棲息地中，缺乏植被減少火災燃料和對水的競爭。"},{"en":"A place with a lack of vegetation may look empty, dry, and harsh.","zh":"缺乏植被的地方可能看起來空曠、乾燥和嚴酷。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":14},{"front":"lack of competition","meaning":"缺乏競爭","examples":[{"en":"The lack of vegetation creates a lack of competition.","zh":"缺乏植被造成缺乏競爭。"},{"en":"Lack of competition means few others are competing for the same resources or customers.","zh":"缺乏競爭是指很少其他人或生物爭奪相同資源或顧客。"},{"en":"A café may succeed because of a lack of competition in a small village.","zh":"一間咖啡店可能因小村莊缺乏競爭而成功。"},{"en":"Lack of competition for water helps bristlecones survive in dry mountains.","zh":"缺乏對水的競爭幫助刺果松在乾燥山區生存。"},{"en":"Lack of competition can be an advantage, but it often exists only in difficult environments.","zh":"缺乏競爭可以是一種優勢，但它常只存在於困難環境中。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":14},{"front":"restricted to","meaning":"局限於","examples":[{"en":"Bristlecone pines are restricted to isolated stands at higher altitudes.","zh":"刺果松局限於較高海拔的孤立林分。"},{"en":"Restricted to means limited to a particular place, group, or situation.","zh":"restricted to 是指局限於某個特定地方、群體或情況。"},{"en":"Access to the laboratory is restricted to trained staff.","zh":"實驗室進入權限局限於受訓職員。"},{"en":"Some animals are restricted to one island because they cannot survive elsewhere.","zh":"有些動物局限於一個島嶼，因為它們不能在其他地方生存。"},{"en":"Bristlecones are restricted to certain mountain areas where conditions suit them.","zh":"刺果松局限於某些適合其生存條件的山區。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":14},{"front":"isolated stands","meaning":"孤立林分","examples":[{"en":"Bristlecones grow in numerous, rather isolated stands.","zh":"刺果松生長於許多相當孤立的林分。"},{"en":"Isolated stands are groups of trees separated from other similar groups.","zh":"孤立林分是與其他相似群體分隔開的樹木群。"},{"en":"A rare tree may survive in isolated stands on distant hillsides.","zh":"稀有樹種可能在遠處山坡的孤立林分中生存。"},{"en":"Isolated stands can reduce disease spread but may make reproduction harder.","zh":"孤立林分可以減少疾病傳播，但可能令繁殖更困難。"},{"en":"Bristlecone isolated stands are important because each group may preserve valuable climate records.","zh":"刺果松孤立林分很重要，因為每一群都可能保存有價值的氣候記錄。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":14},{"front":"higher altitudes","meaning":"較高海拔","examples":[{"en":"Bristlecone pines grow at higher altitudes.","zh":"刺果松生長於較高海拔地區。"},{"en":"Higher altitudes are places located farther above sea level.","zh":"較高海拔是指位於離海平面更高的地方。"},{"en":"Travellers may feel short of breath at higher altitudes because the air is thinner.","zh":"旅客在較高海拔地區可能感到氣促，因為空氣較稀薄。"},{"en":"Plants at higher altitudes often face colder temperatures and stronger winds.","zh":"在較高海拔的植物常面對較低氣溫和更強風。"},{"en":"Bristlecones survive at higher altitudes where many competing trees cannot live.","zh":"刺果松在較高海拔生存，而許多競爭樹種無法在那裡生存。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":14},{"front":"southwestern United States","meaning":"美國西南部","examples":[{"en":"Bristlecone pines occur in the southwestern United States.","zh":"刺果松分布於美國西南部。"},{"en":"The southwestern United States refers to the southwest region of the country, including dry and mountainous areas.","zh":"美國西南部是指美國西南地區，包括乾燥和多山地帶。"},{"en":"Many deserts and high plateaus are found in the southwestern United States.","zh":"美國西南部有許多沙漠和高原。"},{"en":"Plants in the southwestern United States often adapt to heat, dryness, and poor soil.","zh":"美國西南部的植物常適應炎熱、乾燥和貧瘠土壤。"},{"en":"Bristlecone pines are part of the natural landscape of certain mountains in the southwestern United States.","zh":"刺果松是美國西南部某些山區自然景觀的一部分。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":15},{"front":"stands occur from…through…to…","meaning":"林分由……經……至……分布","examples":[{"en":"Bristlecone stands occur from the Rocky Mountains through the Colorado Plateau to the Great Basin.","zh":"刺果松林分由洛磯山脈，經科羅拉多高原，至大盆地分布。"},{"en":"Stands occur from…through…to… describes a distribution that starts in one area, passes through another, and reaches a third.","zh":"林分由……經……至……分布，是描述分布由一區開始，經過另一區，再到第三區。"},{"en":"A bus route may run from the station through the city centre to the airport.","zh":"一條巴士路線可能由車站，經市中心，至機場。"},{"en":"This pattern helps readers follow a range across several regions.","zh":"這種模式幫助讀者理解跨越幾個地區的範圍。"},{"en":"The phrase is useful when describing where a species, road, or system extends.","zh":"描述物種、道路或系統延伸到哪裡時，這個短語很有用。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":15},{"front":"Rocky Mountains","meaning":"洛磯山脈","examples":[{"en":"Bristlecone stands occur in parts of the Rocky Mountains.","zh":"刺果松林分出現在洛磯山脈部分地區。"},{"en":"The Rocky Mountains are a major mountain range in western North America.","zh":"洛磯山脈是北美西部的一條主要山脈。"},{"en":"Tourists visit the Rocky Mountains for hiking, wildlife, and snowy scenery.","zh":"遊客到洛磯山脈行山、觀賞野生動物和雪景。"},{"en":"High areas of the Rocky Mountains can have cold, dry conditions.","zh":"洛磯山脈高處可能有寒冷乾燥的環境。"},{"en":"Some bristlecone pine stands are found within the wider Rocky Mountains region.","zh":"有些刺果松林分位於較廣闊的洛磯山脈地區內。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":15},{"front":"Colorado Plateau","meaning":"科羅拉多高原","examples":[{"en":"Bristlecone stands extend through the Colorado Plateau.","zh":"刺果松林分延伸經過科羅拉多高原。"},{"en":"The Colorado Plateau is a high, dry region in the southwestern United States.","zh":"科羅拉多高原是美國西南部一個高而乾燥的地區。"},{"en":"The Colorado Plateau is known for canyons, cliffs, and desert landscapes.","zh":"科羅拉多高原以峽谷、懸崖和沙漠景觀聞名。"},{"en":"Plants on the Colorado Plateau often survive with little water.","zh":"科羅拉多高原上的植物常在少水環境中生存。"},{"en":"Bristlecone distribution through the Colorado Plateau shows the species’ link with high dry land.","zh":"刺果松分布經過科羅拉多高原，顯示該物種與高而乾燥土地的關係。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":15},{"front":"western margin","meaning":"西部邊緣","examples":[{"en":"The trees occur near the western margin of the Great Basin.","zh":"這些樹出現在大盆地的西部邊緣附近。"},{"en":"A western margin is the western edge or border of an area.","zh":"西部邊緣是某地區的西側邊界或邊緣。"},{"en":"A city may expand along the western margin of a valley.","zh":"城市可能沿山谷西部邊緣擴展。"},{"en":"Species at the western margin of their range may face different climate conditions.","zh":"位於其分布範圍西部邊緣的物種，可能面對不同氣候條件。"},{"en":"The phrase helps locate something more precisely than naming the whole region.","zh":"這個短語比只說整個地區更能精確定位。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":15},{"front":"Great Basin","meaning":"大盆地","examples":[{"en":"The Great Basin is part of the bristlecone’s natural range.","zh":"大盆地是刺果松自然分布範圍的一部分。"},{"en":"The Great Basin is a large dry region in the western United States.","zh":"大盆地是美國西部一個大型乾燥地區。"},{"en":"The Great Basin includes deserts, mountains, and isolated valleys.","zh":"大盆地包括沙漠、山脈和孤立山谷。"},{"en":"Plants in the Great Basin often need adaptations for drought and poor soil.","zh":"大盆地中的植物常需要適應乾旱和貧瘠土壤。"},{"en":"Bristlecone pines are closely linked with high-elevation areas of the Great Basin.","zh":"刺果松與大盆地的高海拔地區密切相關。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":15},{"front":"natural range","meaning":"自然分布範圍","examples":[{"en":"The oldest researched stands occur within the species’ natural range.","zh":"研究過的最古老林分出現在該物種的自然分布範圍內。"},{"en":"A natural range is the area where a species normally lives or grows without being introduced by humans.","zh":"自然分布範圍是物種在沒有人類引入下通常生活或生長的地區。"},{"en":"Pandas have a limited natural range in parts of China.","zh":"熊貓在中國部分地區有有限的自然分布範圍。"},{"en":"Protecting a species’ natural range helps preserve its habitat and genetic diversity.","zh":"保護物種的自然分布範圍有助保存其棲息地和遺傳多樣性。"},{"en":"Bristlecone pines are studied within their natural range because that is where they evolved.","zh":"科學家在刺果松的自然分布範圍內研究它們，因為那裡是它們演化的地方。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":15},{"front":"most widely researched stands","meaning":"研究最廣泛的林分","examples":[{"en":"The most widely researched stands occur in California’s White Mountains.","zh":"研究最廣泛的林分出現在加州白山山脈。"},{"en":"Most widely researched stands are the tree groups that have received the most scientific study.","zh":"研究最廣泛的林分，是指受到最多科學研究的樹木群。"},{"en":"A forest may contain the most widely researched stands because it has very old and accessible trees.","zh":"一片森林可能因有非常古老且可到達的樹，而包含研究最廣泛的林分。"},{"en":"Most widely researched stands often provide the strongest data for scientists.","zh":"研究最廣泛的林分通常為科學家提供最強數據。"},{"en":"In this passage, the White Mountains contain the most widely researched bristlecone stands.","zh":"在本文中，白山山脈包含研究最廣泛的刺果松林分。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":15},{"front":"White Mountains","meaning":"白山山脈","examples":[{"en":"The White Mountains contain some of the oldest bristlecone stands.","zh":"白山山脈包含一些最古老的刺果松林分。"},{"en":"The White Mountains are a mountain range in California known for ancient bristlecone pines.","zh":"白山山脈是加州一條以古老刺果松聞名的山脈。"},{"en":"Researchers visit the White Mountains to study high-elevation desert conditions.","zh":"研究人員到白山山脈研究高海拔沙漠環境。"},{"en":"The White Mountains are dry partly because of the rain shadow effect.","zh":"白山山脈乾燥，部分原因是雨影效應。"},{"en":"The oldest bristlecone studies often focus on trees in the White Mountains.","zh":"最古老的刺果松研究常集中於白山山脈中的樹木。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":15},{"front":"high-elevation deserts","meaning":"高海拔沙漠","examples":[{"en":"The White Mountains are home to high-elevation deserts.","zh":"白山山脈是高海拔沙漠的所在地。"},{"en":"High-elevation deserts are dry areas located far above sea level.","zh":"高海拔沙漠是位於海拔很高地方的乾燥地區。"},{"en":"High-elevation deserts can be cold as well as dry.","zh":"高海拔沙漠可以既寒冷又乾燥。"},{"en":"Plants in high-elevation deserts must survive limited water, strong sunlight, and low temperatures.","zh":"高海拔沙漠中的植物必須在有限水分、強烈陽光和低溫中生存。"},{"en":"Bristlecone pines are unusual because they can survive in high-elevation deserts.","zh":"刺果松很特別，因為它們能在高海拔沙漠中生存。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":15},{"front":"located in","meaning":"位於","examples":[{"en":"The region is located in the rain shadow of the Sierra Nevada.","zh":"該地區位於內華達山脈的雨影區。"},{"en":"Located in means situated or found in a particular place.","zh":"located in 是指位於或處於某個特定地方。"},{"en":"The school is located in a quiet residential area.","zh":"學校位於一個安靜住宅區。"},{"en":"A hospital located in the city centre is easier for patients to reach.","zh":"位於市中心的醫院較方便病人前往。"},{"en":"The White Mountains are located in a dry area shaped by nearby mountains.","zh":"白山山脈位於一個受附近山脈影響的乾燥地區。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":15},{"front":"rain shadow","meaning":"雨影區","examples":[{"en":"The White Mountains lie in the rain shadow of the Sierra Nevada.","zh":"白山山脈位於內華達山脈的雨影區。"},{"en":"A rain shadow is a dry area on one side of a mountain range because the mountains block moist air.","zh":"雨影區是山脈一側的乾燥地區，因山脈阻擋潮濕空氣而形成。"},{"en":"A valley in a rain shadow may receive little rainfall even if nearby mountains are snowy.","zh":"位於雨影區的山谷即使附近山脈積雪，也可能降雨很少。"},{"en":"Rain shadow conditions can create deserts and dry grasslands.","zh":"雨影條件可以形成沙漠和乾燥草原。"},{"en":"The White Mountains are dry partly because they are in a rain shadow.","zh":"白山山脈乾燥，部分原因是它們位於雨影區。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":16},{"front":"Sierra Nevada","meaning":"內華達山脈","examples":[{"en":"The Sierra Nevada creates a rain shadow over the White Mountains.","zh":"內華達山脈在白山山脈上形成雨影區。"},{"en":"The Sierra Nevada is a major mountain range in California and nearby areas.","zh":"內華達山脈是加州及附近地區的一條主要山脈。"},{"en":"Snow from the Sierra Nevada supplies water to many communities.","zh":"內華達山脈的積雪為許多社區提供水源。"},{"en":"The Sierra Nevada can block moist air and make nearby areas drier.","zh":"內華達山脈可以阻擋潮濕空氣，使附近地區更乾燥。"},{"en":"In this passage, the Sierra Nevada helps explain why the White Mountains receive little precipitation.","zh":"在本文中，內華達山脈有助解釋為何白山山脈降雨很少。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":16},{"front":"receives only","meaning":"只接收；只有","examples":[{"en":"The region receives only 12.54 inches of precipitation per year.","zh":"該地區每年只有12.54英寸降雨量。"},{"en":"Receives only means gets no more than a small or limited amount.","zh":"receives only 是指只得到少量或有限數量。"},{"en":"A small school receives only a few applications each year.","zh":"一間小學校每年只收到少量申請。"},{"en":"A desert town may receive only a little rain in summer.","zh":"沙漠城鎮夏季可能只有很少降雨。"},{"en":"The phrase emphasises scarcity by showing how little something gets.","zh":"這個短語透過顯示某物得到得很少來強調稀缺。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":16},{"front":"precipitation per year","meaning":"每年降雨量","examples":[{"en":"The area receives little precipitation per year.","zh":"該地區每年降雨量很少。"},{"en":"Precipitation per year means the amount of rain, snow, or other moisture that falls in one year.","zh":"每年降雨量是指一年內降下的雨、雪或其他水分總量。"},{"en":"Farmers check precipitation per year before deciding which crops to grow.","zh":"農民在決定種植哪些農作物前，會查看每年降雨量。"},{"en":"Low precipitation per year can lead to dry soil and water shortages.","zh":"每年降雨量低可能導致土壤乾燥和缺水。"},{"en":"The White Mountains have low precipitation per year, making survival difficult for plants.","zh":"白山山脈每年降雨量低，令植物生存困難。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":16},{"front":"experiences temperatures between","meaning":"經歷介乎……之間的氣溫","examples":[{"en":"The region experiences temperatures between −20°F and +50°F.","zh":"該地區經歷介乎零下20華氏度至50華氏度之間的氣溫。"},{"en":"Experiences temperatures between two numbers means has temperatures within that range.","zh":"經歷介乎兩個數字之間的氣溫，是指氣溫在該範圍內。"},{"en":"The city experiences temperatures between 10°C and 30°C during spring.","zh":"該城市春季經歷介乎攝氏10至30度之間的氣溫。"},{"en":"A plant may suffer if it experiences temperatures between extremes it cannot tolerate.","zh":"如果植物經歷介乎其無法忍受的極端氣溫之間，它可能受損。"},{"en":"This phrase is useful for describing the climate range of a place.","zh":"這個短語適合用來描述一個地方的氣候範圍。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":16},{"front":"peaks south of","meaning":"……以南的山峰","examples":[{"en":"The peaks south of the Owens Valley are higher than they appear.","zh":"歐文斯谷以南的山峰比它們看起來更高。"},{"en":"Peaks south of a place are mountain tops located to the south of that place.","zh":"某地以南的山峰，是指位於該地南面的山頂。"},{"en":"The peaks south of the village are covered with snow in winter.","zh":"村莊以南的山峰在冬天被雪覆蓋。"},{"en":"Hikers use maps to identify peaks south of the valley before planning a route.","zh":"行山者在規劃路線前，會用地圖辨認山谷以南的山峰。"},{"en":"This phrase gives location by comparing mountains with a nearby landmark.","zh":"這個短語透過把山峰與附近地標比較來說明位置。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":16},{"front":"Owens Valley","meaning":"歐文斯谷","examples":[{"en":"The peaks south of the Owens Valley are very high.","zh":"歐文斯谷以南的山峰非常高。"},{"en":"Owens Valley is a valley in eastern California near the White Mountains and Sierra Nevada.","zh":"歐文斯谷是加州東部、靠近白山山脈和內華達山脈的一個山谷。"},{"en":"Travellers may pass through Owens Valley when visiting high desert landscapes.","zh":"旅客參觀高海拔沙漠景觀時，可能經過歐文斯谷。"},{"en":"Owens Valley helps readers locate the mountains discussed in the passage.","zh":"歐文斯谷幫助讀者定位文章中討論的山脈。"},{"en":"The surrounding peaks can appear less high when viewed from Owens Valley.","zh":"從歐文斯谷看去，周圍山峰可能顯得沒有那麼高。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":16},{"front":"higher up than","meaning":"比……看起來更高","examples":[{"en":"The peaks are higher up than they might appear from a distance.","zh":"這些山峰比從遠處看起來更高。"},{"en":"Higher up than means located at a greater height than something seems or than another place.","zh":"higher up than 是指位於比表面看來或比另一地方更高的位置。"},{"en":"The apartment is higher up than I expected, so the view is excellent.","zh":"這個單位比我預期更高，所以景觀很好。"},{"en":"A mountain may look close and low, but actually be higher up than it appears.","zh":"一座山可能看似很近很低，但實際上比看起來更高。"},{"en":"This phrase helps correct a mistaken impression about height.","zh":"這個短語幫助修正對高度的錯誤印象。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":16},{"front":"from a distance","meaning":"從遠處看","examples":[{"en":"The mountains appear lower from a distance.","zh":"這些山從遠處看顯得較低。"},{"en":"From a distance means when seen or considered from far away.","zh":"從遠處看是指從很遠的地方觀看或考慮。"},{"en":"From a distance, the building looks small, but it is huge up close.","zh":"從遠處看，這座建築很小，但近看其實很巨大。"},{"en":"Problems may seem simple from a distance until you know the details.","zh":"從遠處看，問題可能顯得簡單，直到你了解細節。"},{"en":"Mountains can look lower from a distance because nearby valleys affect perspective.","zh":"山峰從遠處看可能顯得較低，因為附近山谷影響視角。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":16},{"front":"snow-capped","meaning":"積雪覆蓋的","examples":[{"en":"Snow-capped White Mountain Peak stands above sea level.","zh":"積雪覆蓋的白山峰高於海平面。"},{"en":"Snow-capped means covered with snow on the top.","zh":"積雪覆蓋的是指頂部被雪覆蓋。"},{"en":"Tourists often photograph snow-capped mountains at sunrise.","zh":"遊客常在日出時拍攝積雪覆蓋的山峰。"},{"en":"Snow-capped peaks usually suggest cold temperatures at high elevations.","zh":"積雪覆蓋的山峰通常表示高海拔處氣溫寒冷。"},{"en":"A snow-capped mountain may be dry at its base but icy near the summit.","zh":"積雪覆蓋的山在山腳可能乾燥，但接近山頂時結冰。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":16},{"front":"White Mountain Peak","meaning":"白山峰","examples":[{"en":"White Mountain Peak gives the range its name.","zh":"白山峰賦予該山脈名稱。"},{"en":"White Mountain Peak is a high mountain peak in California’s White Mountains.","zh":"白山峰是加州白山山脈中的一座高山峰。"},{"en":"Visitors may see White Mountain Peak covered with snow from far away.","zh":"遊客可能從遠處看見被雪覆蓋的白山峰。"},{"en":"White Mountain Peak is important because it helps identify the mountain range.","zh":"白山峰很重要，因為它幫助識別該山脈。"},{"en":"The name of the range comes from White Mountain Peak.","zh":"該山脈的名稱來自白山峰。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":16},{"front":"the range is named","meaning":"該山脈由……命名","examples":[{"en":"The range is named after White Mountain Peak.","zh":"該山脈由白山峰命名。"},{"en":"If a range is named after something, its name comes from that person, place, or feature.","zh":"如果某山脈由某事物命名，即是其名稱來自該人物、地方或特徵。"},{"en":"A school may be named after a respected teacher.","zh":"學校可能以一位受尊敬的老師命名。"},{"en":"A street named after a local hero keeps that person’s memory alive.","zh":"以本地英雄命名的街道，延續了那個人的記憶。"},{"en":"The White Mountains are named after White Mountain Peak because it is a defining feature.","zh":"白山山脈以白山峰命名，因為它是一個標誌性特徵。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":17},{"front":"above sea level","meaning":"海拔","examples":[{"en":"White Mountain Peak stands at 14,246 feet above sea level.","zh":"白山峰海拔14,246英尺。"},{"en":"Above sea level means higher than the average level of the ocean.","zh":"海拔是指高於海洋平均水平面的高度。"},{"en":"A city 1,000 metres above sea level may have cooler weather.","zh":"海拔一千米的城市可能天氣較涼。"},{"en":"Mountain climbers need to know how high a peak is above sea level.","zh":"登山者需要知道山峰海拔有多高。"},{"en":"Places high above sea level often have thinner air and lower temperatures.","zh":"海拔高的地方通常空氣較稀薄且氣溫較低。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":17},{"front":"that said","meaning":"話雖如此","examples":[{"en":"That said, reaching pure bristlecone stands is difficult.","zh":"話雖如此，到達純刺果松林分很困難。"},{"en":"That said means although the previous point is true, another point must also be considered.","zh":"that said 是指雖然前一點成立，但仍要考慮另一點。"},{"en":"The hotel is cheap; that said, it is far from the station.","zh":"這間酒店很便宜；話雖如此，它離車站很遠。"},{"en":"The course is useful; that said, it requires a lot of homework.","zh":"這門課很有用；話雖如此，它需要很多功課。"},{"en":"Use that said when you want to balance one idea with a contrasting detail.","zh":"當你想用一個相反細節平衡前一個想法時，可以使用 that said。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":17},{"front":"pure bristlecone stands","meaning":"純刺果松林分","examples":[{"en":"Reaching pure bristlecone stands is an arduous journey.","zh":"到達純刺果松林分是一段艱辛旅程。"},{"en":"Pure bristlecone stands are tree groups made mainly or only of bristlecone pines.","zh":"純刺果松林分是主要或只由刺果松組成的樹木群。"},{"en":"A researcher may travel far to study pure bristlecone stands without many other tree species.","zh":"研究人員可能遠行去研究沒有許多其他樹種的純刺果松林分。"},{"en":"Pure bristlecone stands can provide clearer data about the species’ growth patterns.","zh":"純刺果松林分可以提供更清楚的該物種生長模式資料。"},{"en":"Such stands are often remote because bristlecones grow best in harsh high areas.","zh":"這類林分通常偏遠，因為刺果松最適合在嚴酷高地生長。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":17},{"front":"an arduous journey","meaning":"艱辛旅程","examples":[{"en":"Reaching the stands is an arduous journey in itself.","zh":"到達這些林分本身就是一段艱辛旅程。"},{"en":"An arduous journey is a long, difficult, and tiring trip.","zh":"艱辛旅程是漫長、困難且令人疲累的旅程。"},{"en":"Climbing a snowy mountain can be an arduous journey for inexperienced hikers.","zh":"對缺乏經驗的行山者而言，攀登雪山可能是一段艱辛旅程。"},{"en":"An arduous journey may require planning, strength, and patience.","zh":"艱辛旅程可能需要計劃、體力和耐性。"},{"en":"Scientists sometimes accept an arduous journey to reach important research sites.","zh":"科學家有時會接受艱辛旅程，以到達重要研究地點。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":17},{"front":"seemingly endless areas of wonder","meaning":"似乎無窮無盡的奇妙之處","examples":[{"en":"The bristlecone pines offer seemingly endless areas of wonder and interest.","zh":"刺果松提供似乎無窮無盡的奇妙之處和興趣。"},{"en":"Seemingly endless areas of wonder are many fascinating things that appear almost unlimited.","zh":"似乎無窮無盡的奇妙之處，是指許多令人著迷、看似近乎無限的事物。"},{"en":"A museum can offer seemingly endless areas of wonder for curious children.","zh":"博物館可以為好奇孩子提供似乎無窮無盡的奇妙之處。"},{"en":"Nature often provides seemingly endless areas of wonder because every detail can lead to a new question.","zh":"大自然常提供似乎無窮無盡的奇妙之處，因為每個細節都能引出新問題。"},{"en":"Bristlecone pines interest scientists because their age, structure, and records create seemingly endless areas of wonder.","zh":"刺果松令科學家感興趣，因為其年齡、結構和記錄創造了似乎無窮無盡的奇妙之處。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":17},{"front":"subject to much research","meaning":"成為大量研究對象","examples":[{"en":"The trees have become subject to much research.","zh":"這些樹已成為大量研究對象。"},{"en":"Subject to much research means studied by many researchers or in many studies.","zh":"成為大量研究對象，是指被許多研究人員或研究項目研究。"},{"en":"Sleep has become subject to much research because it affects health and learning.","zh":"睡眠已成為大量研究對象，因為它影響健康和學習。"},{"en":"A rare disease may become subject to much research after doctors notice unusual cases.","zh":"當醫生注意到不尋常病例後，罕見疾病可能成為大量研究對象。"},{"en":"Bristlecone pines are subject to much research because they preserve long climate records.","zh":"刺果松成為大量研究對象，因為它們保存長期氣候記錄。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":17},{"front":"ancient organisms","meaning":"古老生物","examples":[{"en":"The annual growth of these ancient organisms reflects climate.","zh":"這些古老生物的年度生長反映氣候。"},{"en":"Ancient organisms are living things that have existed for a very long time or belong to old biological lineages.","zh":"古老生物是存在很久或屬於古老生物譜系的生物。"},{"en":"Some ancient organisms, such as certain trees, can live far longer than humans.","zh":"有些古老生物，例如某些樹木，可以活得遠比人類長。"},{"en":"Studying ancient organisms helps scientists understand survival over long periods.","zh":"研究古老生物幫助科學家理解長期生存。"},{"en":"Bristlecone pines are ancient organisms because some individuals have lived for thousands of years.","zh":"刺果松是古老生物，因為有些個體已存活數千年。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":17},{"front":"directly reflects","meaning":"直接反映","examples":[{"en":"The annual growth directly reflects climatic conditions.","zh":"年度生長直接反映氣候條件。"},{"en":"Directly reflects means clearly shows or corresponds to something without many extra steps.","zh":"直接反映是指清楚顯示或對應某事，中間沒有太多額外步驟。"},{"en":"A student’s attendance may directly reflect their daily routine.","zh":"學生出席率可能直接反映其日常習慣。"},{"en":"Plant growth can directly reflect water supply when water is the main limiting factor.","zh":"當水是主要限制因素時，植物生長可以直接反映水源供應。"},{"en":"Tree rings directly reflect climate because good years and bad years change ring width.","zh":"樹輪直接反映氣候，因為好年份和壞年份會改變年輪寬度。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":17},{"front":"particular time period","meaning":"某個特定時期","examples":[{"en":"Tree rings reflect the conditions of a particular time period.","zh":"樹輪反映某個特定時期的條件。"},{"en":"A particular time period is a specific span of time being discussed or studied.","zh":"某個特定時期是指正在討論或研究的一段具體時間。"},{"en":"Historians may focus on a particular time period, such as the nineteenth century.","zh":"歷史學家可能集中研究某個特定時期，例如十九世紀。"},{"en":"Climate records from a particular time period help scientists compare past and present conditions.","zh":"某個特定時期的氣候記錄幫助科學家比較過去和現在的條件。"},{"en":"Each tree ring represents conditions from one particular time period in the tree’s life.","zh":"每個樹輪代表樹木生命中某個特定時期的條件。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":17},{"front":"of greatest significance to","meaning":"對……最具重要性","examples":[{"en":"Bristlecones are of greatest significance to dendrochronologists.","zh":"刺果松對樹輪年代學家最具重要性。"},{"en":"Of greatest significance to someone means most important or valuable to that person or field.","zh":"對某人最具重要性，是指對該人或領域最重要或最有價值。"},{"en":"Clear pronunciation is of greatest significance to language learners who need spoken communication.","zh":"對需要口語溝通的語言學習者而言，清晰發音最具重要性。"},{"en":"Accurate data are of greatest significance to scientists studying climate change.","zh":"對研究氣候變化的科學家而言，準確數據最具重要性。"},{"en":"Bristlecones matter most to tree-ring specialists because they provide unusually long records.","zh":"刺果松對樹輪專家最重要，因為它們提供異常長的記錄。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":17},{"front":"tree-ring specialists","meaning":"樹輪專家","examples":[{"en":"Tree-ring specialists use bristlecone records to study climate change.","zh":"樹輪專家使用刺果松記錄研究氣候變化。"},{"en":"Tree-ring specialists are experts who analyse annual rings in wood.","zh":"樹輪專家是分析木材年輪的專家。"},{"en":"Tree-ring specialists can date old buildings by comparing wooden beams with known ring patterns.","zh":"樹輪專家可以透過把木樑與已知年輪模式比較，為古建築定年。"},{"en":"Tree-ring specialists need patience because they compare small details across many samples.","zh":"樹輪專家需要耐性，因為他們要比較許多樣本中的細微細節。"},{"en":"Bristlecone pines are valuable to tree-ring specialists because their records are so long.","zh":"刺果松對樹輪專家很有價值，因為其記錄非常長。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":18},{"front":"dated with reasonable accuracy","meaning":"以相當準確度定年","examples":[{"en":"A tree can be dated with reasonable accuracy by counting rings.","zh":"樹木可以透過計算年輪以相當準確度定年。"},{"en":"Dated with reasonable accuracy means its age can be estimated fairly reliably, though not perfectly.","zh":"以相當準確度定年，是指其年齡可以被相當可靠地估算，但未必完全精確。"},{"en":"An old house can be dated with reasonable accuracy by checking building records and materials.","zh":"舊房子可以透過查看建築記錄和材料，以相當準確度定年。"},{"en":"Tree rings allow wood to be dated with reasonable accuracy because each ring marks one year.","zh":"樹輪讓木材可以以相當準確度定年，因為每個年輪代表一年。"},{"en":"Reasonable accuracy is useful when exact dates are difficult to prove.","zh":"當確切日期難以證明時，相當準確度已很有用。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":18},{"front":"simply by counting","meaning":"只需透過計算","examples":[{"en":"A tree can be dated simply by counting its annual rings.","zh":"樹木只需透過計算其年輪就可以定年。"},{"en":"Simply by counting means using only counting as the main method.","zh":"simply by counting 是指只以計算作為主要方法。"},{"en":"A teacher can check attendance simply by counting the students in the room.","zh":"老師只需透過計算課室中的學生，就可以檢查出席。"},{"en":"You can estimate a tree’s age simply by counting its visible rings.","zh":"你可以只需透過計算可見年輪來估算樹木年齡。"},{"en":"This phrase emphasises that the method is straightforward.","zh":"這個短語強調方法很直接。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":18},{"front":"annual rings","meaning":"年輪","examples":[{"en":"Annual rings are produced by natural growth.","zh":"年輪由樹木自然生長產生。"},{"en":"Annual rings are tree-ring layers that form once each year.","zh":"年輪是每年形成一次的樹木環狀層。"},{"en":"Children can see annual rings on a cut tree stump.","zh":"孩子可以在被切開的樹樁上看見年輪。"},{"en":"Annual rings become wider or narrower depending on growing conditions.","zh":"年輪會因生長條件而變寬或變窄。"},{"en":"Scientists use annual rings to study age and past climate.","zh":"科學家使用年輪研究年齡和過去氣候。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":18},{"front":"natural growth","meaning":"自然生長","examples":[{"en":"Annual rings are produced by a tree’s natural growth.","zh":"年輪由樹木自然生長產生。"},{"en":"Natural growth is growth that happens through ordinary biological processes.","zh":"自然生長是透過普通生物過程發生的生長。"},{"en":"A child’s height increases through natural growth over many years.","zh":"孩子的身高多年來透過自然生長增加。"},{"en":"Natural growth in trees creates new layers of wood each season.","zh":"樹木自然生長在每個季節創造新的木質層。"},{"en":"Tree rings are useful because natural growth leaves regular marks.","zh":"樹輪有用，因為自然生長留下規律痕跡。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":18},{"front":"carefully compiling","meaning":"仔細編製","examples":[{"en":"Scientists have carefully compiled a nearly 10,000-year-old record.","zh":"科學家已仔細編製一項近一萬年的記錄。"},{"en":"Carefully compiling means collecting and arranging information with close attention to accuracy.","zh":"仔細編製是指以高度重視準確性的方式收集並整理資訊。"},{"en":"A teacher may carefully compile students’ mistakes to plan better lessons.","zh":"老師可能仔細編製學生錯誤，以計劃更好的課堂。"},{"en":"Researchers carefully compile data so that later conclusions are trustworthy.","zh":"研究人員仔細編製數據，使後來的結論值得信賴。"},{"en":"Building a long tree-ring record requires carefully compiling many samples.","zh":"建立長期樹輪記錄需要仔細編製許多樣本。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":18},{"front":"nearly 10,000-year-old record","meaning":"近一萬年的記錄","examples":[{"en":"The bristlecone pine record is nearly 10,000 years old.","zh":"刺果松記錄已有近一萬年。"},{"en":"A nearly 10,000-year-old record is a record that reaches back almost ten thousand years.","zh":"近一萬年的記錄是指可追溯至接近一萬年前的記錄。"},{"en":"A nearly 10,000-year-old record can show changes far beyond written history.","zh":"近一萬年的記錄可以顯示遠超文字歷史的變化。"},{"en":"Scientists value such a record because it covers many climate cycles.","zh":"科學家重視這類記錄，因為它涵蓋許多氣候循環。"},{"en":"The bristlecone record is special because few natural records are this long and precise.","zh":"刺果松記錄很特別，因為很少自然記錄如此長且精確。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":18},{"front":"accurately corrected","meaning":"準確修正","examples":[{"en":"The record has accurately corrected the carbon-14 dating method.","zh":"這項記錄準確修正了碳十四定年法。"},{"en":"Accurately corrected means fixed in a precise and reliable way.","zh":"準確修正是指以精確可靠的方式改正。"},{"en":"A teacher accurately corrected the essay by explaining each grammar mistake.","zh":"老師透過解釋每個文法錯誤，準確修正了文章。"},{"en":"Scientists accurately corrected old data after discovering better measurements.","zh":"科學家在發現更好量度方法後，準確修正舊數據。"},{"en":"Tree-ring records accurately corrected carbon dating by providing known-year comparisons.","zh":"樹輪記錄透過提供已知年份比較，準確修正碳定年。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":18},{"front":"carbon-14 dating method","meaning":"碳十四定年法","examples":[{"en":"The bristlecone record helped correct the carbon-14 dating method.","zh":"刺果松記錄幫助修正碳十四定年法。"},{"en":"The carbon-14 dating method estimates the age of organic remains by measuring radioactive carbon.","zh":"碳十四定年法透過量度放射性碳來估算有機遺物年齡。"},{"en":"Archaeologists use the carbon-14 dating method on charcoal, wood, cloth, and bone.","zh":"考古學家把碳十四定年法用於木炭、木材、布料和骨骼。"},{"en":"The carbon-14 dating method becomes more reliable when checked against tree-ring records.","zh":"當碳十四定年法與樹輪記錄核對時，會變得更可靠。"},{"en":"Bristlecone data improved the carbon-14 dating method because its ring dates were known.","zh":"刺果松數據改善了碳十四定年法，因為其年輪日期已知。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":18},{"front":"estimated the dates of","meaning":"估算……的日期","examples":[{"en":"Scientists estimated the dates of past climate changes.","zh":"科學家估算過去氣候變化的日期。"},{"en":"Estimated the dates of means made informed calculations about when events happened.","zh":"估算某事的日期，是指根據資訊計算事件何時發生。"},{"en":"Historians estimated the dates of old documents by studying handwriting and paper.","zh":"歷史學家透過研究筆跡和紙張，估算舊文件的日期。"},{"en":"Scientists estimate the dates of volcanic eruptions using ash layers and rock samples.","zh":"科學家使用火山灰層和岩石樣本估算火山爆發的日期。"},{"en":"Tree rings help estimate the dates of past climate changes more precisely.","zh":"樹輪幫助更精確估算過去氣候變化的日期。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":18},{"front":"past periods of global climate change","meaning":"過去全球氣候變化時期","examples":[{"en":"The record helps date past periods of global climate change.","zh":"這項記錄幫助為過去全球氣候變化時期定年。"},{"en":"Past periods of global climate change are earlier times when Earth’s overall climate shifted.","zh":"過去全球氣候變化時期是指地球整體氣候曾經轉變的較早時期。"},{"en":"Ice cores can show past periods of global climate change through trapped air bubbles.","zh":"冰芯可以透過被困住的氣泡顯示過去全球氣候變化時期。"},{"en":"Studying past periods of global climate change helps scientists understand current warming.","zh":"研究過去全球氣候變化時期幫助科學家理解當前暖化。"},{"en":"Tree rings provide year-by-year evidence for some past periods of global climate change.","zh":"樹輪為某些過去全球氣候變化時期提供逐年證據。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":18},{"front":"what makes this record special","meaning":"令這項記錄特別之處","examples":[{"en":"The passage explains what makes this record special.","zh":"文章解釋令這項記錄特別之處。"},{"en":"What makes this record special means the reason this record is unusual, valuable, or different.","zh":"令這項記錄特別之處，是指這項記錄不尋常、有價值或與眾不同的原因。"},{"en":"A teacher may ask what makes this essay special compared with ordinary answers.","zh":"老師可能問這篇文章與普通答案相比有何特別之處。"},{"en":"What makes this record special is its length, accuracy, and connection to climate history.","zh":"令這項記錄特別之處，是其長度、準確性和與氣候歷史的關係。"},{"en":"This phrase is used when explaining the unique value of something.","zh":"這個短語用於解釋某事物的獨特價值。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":19},{"front":"throughout time","meaning":"縱觀時間","examples":[{"en":"Nowhere throughout time is the same ring sequence exactly repeated.","zh":"縱觀時間，沒有任何地方會完全重複相同的年輪序列。"},{"en":"Throughout time means across all periods of time being considered.","zh":"縱觀時間是指跨越所有被考慮的時期。"},{"en":"Throughout time, people have used stories to explain their world.","zh":"縱觀時間，人們一直用故事解釋自己的世界。"},{"en":"Fashion changes throughout time as society and technology change.","zh":"時裝隨社會和科技改變而縱觀時間不斷變化。"},{"en":"Tree-ring patterns vary throughout time because climate conditions are never identical.","zh":"樹輪模式縱觀時間會變化，因為氣候條件從不完全相同。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":19},{"front":"precisely the same","meaning":"完全相同的","examples":[{"en":"No long-term tree-ring sequence is precisely the same.","zh":"沒有長期樹輪序列是完全相同的。"},{"en":"Precisely the same means exactly identical, with no difference.","zh":"完全相同的是指精確一致，沒有差別。"},{"en":"Two handwritten signatures are rarely precisely the same.","zh":"兩個手寫簽名很少完全相同。"},{"en":"Climate from one year to another is never precisely the same.","zh":"每年的氣候從來不會完全相同。"},{"en":"Because ring sequences are not precisely the same, scientists can match them like unique patterns.","zh":"因為年輪序列不是完全相同的，科學家可以像匹配獨特模式一樣比較它們。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":19},{"front":"long-term sequence","meaning":"長期序列","examples":[{"en":"The long-term sequence of wide and narrow rings is unique.","zh":"寬窄年輪的長期序列是獨特的。"},{"en":"A long-term sequence is a pattern or order that continues over many years or periods.","zh":"長期序列是持續多年或多個時期的模式或次序。"},{"en":"A student’s long-term sequence of grades may show steady improvement.","zh":"學生成績的長期序列可能顯示穩步進步。"},{"en":"A long-term sequence of wet and dry years affects tree growth.","zh":"乾濕年份的長期序列會影響樹木生長。"},{"en":"Tree-ring dating works because long-term sequences can be matched across samples.","zh":"樹輪定年能運作，因為長期序列可以在不同樣本之間匹配。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":19},{"front":"wide and narrow rings","meaning":"寬窄年輪","examples":[{"en":"The pattern of wide and narrow rings records climate variation.","zh":"寬窄年輪的模式記錄氣候變化。"},{"en":"Wide and narrow rings are tree rings of different thicknesses caused by different growing conditions.","zh":"寬窄年輪是由不同生長條件造成的不同厚度樹輪。"},{"en":"Wide rings often show favourable years, while narrow rings may show drought or cold.","zh":"寬年輪常顯示有利年份，而窄年輪可能顯示乾旱或寒冷。"},{"en":"Scientists compare wide and narrow rings to identify past climate patterns.","zh":"科學家比較寬窄年輪，以識別過去氣候模式。"},{"en":"The alternation of wide and narrow rings creates a unique natural timeline.","zh":"寬窄年輪交替形成一條獨特自然時間線。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":19},{"front":"year-to-year variations","meaning":"每年之間的變化","examples":[{"en":"Year-to-year variations in climate are never exactly the same.","zh":"氣候每年之間的變化從不完全相同。"},{"en":"Year-to-year variations are differences that occur from one year to the next.","zh":"每年之間的變化是指一年到下一年之間出現的差異。"},{"en":"Schools may see year-to-year variations in student numbers.","zh":"學校可能看到學生人數每年之間的變化。"},{"en":"Year-to-year variations in rainfall affect crop yields and water supply.","zh":"降雨每年之間的變化會影響農作物收成和水源供應。"},{"en":"Tree rings record year-to-year variations because each year leaves a separate mark.","zh":"樹輪記錄每年之間的變化，因為每一年都留下獨立痕跡。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":19},{"front":"never exactly the same","meaning":"從不完全相同","examples":[{"en":"Climate conditions are never exactly the same from year to year.","zh":"氣候條件每年從不完全相同。"},{"en":"Never exactly the same means always having at least small differences.","zh":"從不完全相同是指總有至少細微差異。"},{"en":"Two lessons are never exactly the same because students ask different questions.","zh":"兩堂課從不完全相同，因為學生會提出不同問題。"},{"en":"Weather is never exactly the same, even in the same season.","zh":"即使在同一季節，天氣也從不完全相同。"},{"en":"Tree rings are useful because growing conditions are never exactly the same each year.","zh":"樹輪有用，因為每年的生長條件從不完全相同。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":19},{"front":"historically","meaning":"從歷史上看","examples":[{"en":"Historically, the tree’s remote location deterred commercial extraction.","zh":"從歷史上看，該樹的偏遠位置阻止了商業開採。"},{"en":"Historically means when looking at what happened in the past.","zh":"historically 是指從過去發生的事情來看。"},{"en":"Historically, many towns grew near rivers because transport and water were easier.","zh":"從歷史上看，許多城鎮在河流附近發展，因為交通和用水較容易。"},{"en":"Historically, women had fewer educational opportunities in many societies.","zh":"從歷史上看，在許多社會中，女性教育機會較少。"},{"en":"The word historically helps connect a present situation with its past causes.","zh":"historically 這個詞幫助把現在情況與其過去原因連接起來。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":19},{"front":"remote location","meaning":"偏遠位置","examples":[{"en":"The bristlecone’s remote location protected it from logging.","zh":"刺果松的偏遠位置保護它免受伐木影響。"},{"en":"A remote location is a place far from towns, roads, or easy access.","zh":"偏遠位置是指遠離城鎮、道路或容易到達地點的地方。"},{"en":"A village in a remote location may have limited medical services.","zh":"位於偏遠位置的村莊可能醫療服務有限。"},{"en":"A remote location can protect wildlife because fewer people visit.","zh":"偏遠位置可以保護野生動物，因為較少人到訪。"},{"en":"Bristlecones survived partly because their remote location made commercial logging difficult.","zh":"刺果松得以生存，部分原因是其偏遠位置令商業伐木困難。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":19},{"front":"gnarled wood","meaning":"扭曲多節的木材","examples":[{"en":"Gnarled wood made the bristlecone less attractive for commercial use.","zh":"扭曲多節的木材令刺果松對商業用途較不吸引。"},{"en":"Gnarled wood is twisted, rough, and irregular wood.","zh":"扭曲多節的木材是彎曲、粗糙且不規則的木材。"},{"en":"An old tree with gnarled wood may look beautiful but be hard to cut into straight boards.","zh":"有扭曲多節木材的老樹可能很美，但很難切成直木板。"},{"en":"Gnarled wood can reduce commercial value because it is difficult to process.","zh":"扭曲多節的木材會降低商業價值，因為它難以加工。"},{"en":"For bristlecones, gnarled wood helped protect them from logging.","zh":"對刺果松而言，扭曲多節的木材幫助它們免受伐木。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":19},{"front":"deterred commercial extraction","meaning":"阻止商業開採","examples":[{"en":"The tree’s remote location and gnarled wood deterred commercial extraction.","zh":"該樹的偏遠位置和扭曲多節的木材阻止了商業開採。"},{"en":"Deterred commercial extraction means discouraged businesses from removing natural resources for profit.","zh":"阻止商業開採是指使企業不願為利潤移走自然資源。"},{"en":"Dangerous terrain can deter commercial extraction of timber from a forest.","zh":"危險地形可以阻止企業從森林商業開採木材。"},{"en":"If a material is hard to process, it may deter commercial extraction.","zh":"如果材料難以加工，可能會阻止商業開採。"},{"en":"Bristlecones were protected because distance and poor timber quality deterred commercial extraction.","zh":"刺果松受到保護，因為距離和木材質素差阻止了商業開採。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":19},{"front":"commercial extraction","meaning":"商業開採","examples":[{"en":"Commercial extraction has been limited by the tree’s location and wood quality.","zh":"商業開採受到該樹位置和木材質素限制。"},{"en":"Commercial extraction is the removal of natural resources for sale or profit.","zh":"商業開採是指為出售或利潤而移走自然資源。"},{"en":"Mining is a form of commercial extraction when minerals are taken from the ground.","zh":"採礦把礦物從地下取出出售時，就是一種商業開採。"},{"en":"Commercial extraction can damage habitats if it is not controlled.","zh":"如果不受控制，商業開採會破壞棲息地。"},{"en":"Bristlecones avoided much commercial extraction because they were hard to reach and poor for timber.","zh":"刺果松避開許多商業開採，因為它們難以到達且不適合作木材。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":20},{"front":"nothing on earth will go unaffected","meaning":"地球上沒有任何東西會不受影響","examples":[{"en":"Nothing on earth will go unaffected by global warming.","zh":"地球上沒有任何東西會不受全球暖化影響。"},{"en":"Nothing on earth will go unaffected means every living thing or place will be influenced in some way.","zh":"地球上沒有任何東西會不受影響，是指每種生物或地方都會以某種方式受到影響。"},{"en":"If sea levels rise, nothing on earth’s coastlines will go unaffected.","zh":"如果海平面上升，地球上海岸地區沒有任何地方會不受影響。"},{"en":"Climate change is serious because nothing on earth will go unaffected by its long-term effects.","zh":"氣候變化嚴重，因為地球上沒有任何東西會不受其長期影響。"},{"en":"The phrase emphasises that the impact is extremely wide.","zh":"這個短語強調影響範圍極其廣泛。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":20},{"front":"global warming","meaning":"全球暖化","examples":[{"en":"Global warming may threaten the bristlecone’s ideal habitat.","zh":"全球暖化可能威脅刺果松的理想棲息地。"},{"en":"Global warming is the long-term rise in Earth’s average temperature.","zh":"全球暖化是地球平均氣溫長期上升。"},{"en":"Global warming can melt ice, raise sea levels, and change rainfall patterns.","zh":"全球暖化可以融化冰層、提高海平面並改變降雨模式。"},{"en":"Forests may suffer if global warming makes their habitat too hot or dry.","zh":"如果全球暖化令棲息地過熱或過乾，森林可能受害。"},{"en":"Bristlecone pines may lose suitable habitat as global warming continues.","zh":"隨著全球暖化持續，刺果松可能失去合適棲息地。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":20},{"front":"temperatures rise by","meaning":"氣溫上升……","examples":[{"en":"If temperatures rise by only 6°F, much habitat may disappear.","zh":"如果氣溫只上升6華氏度，大量棲息地可能消失。"},{"en":"Temperatures rise by a number means they increase by that amount.","zh":"氣溫上升某個數字，是指氣溫增加該幅度。"},{"en":"If room temperatures rise by five degrees, students may feel uncomfortable.","zh":"如果室溫上升五度，學生可能感到不舒服。"},{"en":"Crop yields can fall when summer temperatures rise by even a small amount.","zh":"即使夏季氣溫只上升少量，農作物收成也可能下降。"},{"en":"The phrase helps measure how much warming is being discussed.","zh":"這個短語幫助量度所討論的暖化幅度。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":20},{"front":"likely this century","meaning":"本世紀可能發生","examples":[{"en":"Many experts say this temperature rise is likely this century.","zh":"許多專家說這種氣溫上升本世紀可能發生。"},{"en":"Likely this century means probably happening before the end of the current hundred-year period.","zh":"本世紀可能發生是指很可能在當前一百年結束前發生。"},{"en":"Some coastal cities may face more flooding likely this century.","zh":"有些沿海城市本世紀可能面對更多水浸。"},{"en":"A change likely this century is urgent because it may affect people alive today.","zh":"本世紀可能發生的變化很迫切，因為它可能影響今天活著的人。"},{"en":"The phrase connects a future risk with a time frame people can understand.","zh":"這個短語把未來風險與人們能理解的時間框架連接起來。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":20},{"front":"two-thirds of","meaning":"三分之二","examples":[{"en":"About two-thirds of the ideal habitat could be lost.","zh":"約三分之二的理想棲息地可能會失去。"},{"en":"Two-thirds of something means two out of three equal parts of it.","zh":"三分之二是指某事物三等份中的兩份。"},{"en":"If two-thirds of a class passed, most students succeeded.","zh":"如果全班三分之二學生合格，即是大多數學生成功。"},{"en":"Losing two-thirds of a forest would leave only one-third remaining.","zh":"失去森林三分之二，會只剩三分之一。"},{"en":"The phrase shows a large proportion, not just a small change.","zh":"這個短語顯示很大比例，而不只是小變化。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":20},{"front":"ideal habitat","meaning":"理想棲息地","examples":[{"en":"The tree’s ideal habitat may shrink because of climate change.","zh":"由於氣候變化，該樹的理想棲息地可能縮小。"},{"en":"An ideal habitat is the environment where a species can live and grow best.","zh":"理想棲息地是物種能最好地生活和生長的環境。"},{"en":"A panda’s ideal habitat includes bamboo forests and enough space.","zh":"熊貓的理想棲息地包括竹林和足夠空間。"},{"en":"If an ideal habitat becomes too hot or dry, a species may decline.","zh":"如果理想棲息地變得過熱或過乾，物種可能衰退。"},{"en":"Bristlecones need cold, dry, high mountain conditions as part of their ideal habitat.","zh":"刺果松需要寒冷、乾燥、高山條件作為其理想棲息地的一部分。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":20},{"front":"effectively will be gone","meaning":"實際上將會消失","examples":[{"en":"Much of the ideal habitat effectively will be gone.","zh":"大部分理想棲息地實際上將會消失。"},{"en":"Effectively will be gone means will be lost in practical terms, even if some small parts remain.","zh":"實際上將會消失，是指在實際意義上會失去，即使仍有小部分存在。"},{"en":"If a road cuts through a wetland, the habitat effectively will be gone for many animals.","zh":"如果一條道路穿過濕地，對許多動物而言該棲息地實際上將會消失。"},{"en":"A service effectively will be gone if only a few people can still access it.","zh":"如果只有很少人仍能使用某項服務，它實際上將會消失。"},{"en":"The phrase stresses real loss rather than only official disappearance.","zh":"這個短語強調實際損失，而不只是正式消失。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":20},{"front":"acres of National Forest","meaning":"多英畝國家森林","examples":[{"en":"Almost 30,000 acres of National Forest preserve the ancient bristlecone.","zh":"近三萬英畝國家森林保護古老刺果松。"},{"en":"Acres of National Forest are measured areas of protected forest land managed for public and environmental purposes.","zh":"多英畝國家森林是為公共和環境目的而管理的受保護森林土地面積。"},{"en":"A park may protect thousands of acres of National Forest from development.","zh":"公園可能保護數千英畝國家森林免受發展影響。"},{"en":"More acres of National Forest can mean more space for wildlife and old trees.","zh":"更多英畝國家森林可能意味著野生動物和老樹有更多空間。"},{"en":"Protecting acres of National Forest helps reduce human damage to fragile habitats.","zh":"保護多英畝國家森林有助減少人類對脆弱棲息地的破壞。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":20},{"front":"preserve the ancient bristlecone","meaning":"保護古老刺果松","examples":[{"en":"National Forest land helps preserve the ancient bristlecone.","zh":"國家森林土地幫助保護古老刺果松。"},{"en":"To preserve the ancient bristlecone means to protect these old trees so they can continue living.","zh":"保護古老刺果松是指保護這些老樹，使它們能繼續生存。"},{"en":"Rangers preserve ancient trees by limiting visitor access and preventing damage.","zh":"管理員透過限制遊客進入和防止破壞來保護古樹。"},{"en":"Protected land can preserve the ancient bristlecone from logging, fire, and careless tourism.","zh":"受保護土地可以保護古老刺果松免受伐木、火災和粗心旅遊影響。"},{"en":"Preserving the ancient bristlecone also protects the climate records stored in its rings.","zh":"保護古老刺果松也保護其年輪中保存的氣候記錄。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":20},{"front":"paved roads","meaning":"鋪設好的道路","examples":[{"en":"Paved roads have increased human impact on the forest.","zh":"鋪設好的道路增加了人類對森林的影響。"},{"en":"Paved roads are roads with hard surfaces such as asphalt or concrete.","zh":"鋪設好的道路是有瀝青或混凝土等硬表面的道路。"},{"en":"Paved roads make remote areas easier for visitors to reach.","zh":"鋪設好的道路令遊客更容易到達偏遠地區。"},{"en":"More paved roads can bring tourism but also noise, litter, and habitat disturbance.","zh":"更多鋪設好的道路可以帶來旅遊，但也帶來噪音、垃圾和棲息地干擾。"},{"en":"In fragile forests, paved roads may increase pressure on old trees.","zh":"在脆弱森林中，鋪設好的道路可能增加老樹所受壓力。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":20},{"front":"campsites","meaning":"營地","examples":[{"en":"Campsites have brought more visitors to the ancient forest.","zh":"營地為古老森林帶來更多遊客。"},{"en":"Campsites are places where people can stay outdoors in tents or vehicles.","zh":"營地是人們可在帳篷或車輛中戶外停留的地方。"},{"en":"Families may book campsites near a national park during summer.","zh":"家庭可能在夏季預訂國家公園附近的營地。"},{"en":"Campsites can support tourism but may increase litter, noise, and fire risk.","zh":"營地可以支持旅遊，但可能增加垃圾、噪音和火災風險。"},{"en":"Near ancient trees, campsites must be managed carefully to reduce damage.","zh":"在古樹附近，營地必須小心管理以減少破壞。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":21},{"front":"self-guided trails","meaning":"自助導賞步道","examples":[{"en":"Self-guided trails have increased human access to the area.","zh":"自助導賞步道增加了人類進入該地區的機會。"},{"en":"Self-guided trails are marked walking routes that visitors can follow without a guide.","zh":"自助導賞步道是有標示、遊客無需導遊也可跟隨的步行路線。"},{"en":"A museum garden may have self-guided trails with signs explaining plants.","zh":"博物館花園可能有自助導賞步道，並以標示解釋植物。"},{"en":"Self-guided trails make nature more accessible, but they can bring more foot traffic.","zh":"自助導賞步道令自然更容易到達，但也可能帶來更多人流。"},{"en":"In fragile habitats, self-guided trails need clear rules to protect the environment.","zh":"在脆弱棲息地中，自助導賞步道需要清晰規則以保護環境。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":21},{"front":"led only to more human impact","meaning":"只導致更多人類影響","examples":[{"en":"Roads and trails have led only to more human impact.","zh":"道路和步道只導致更多人類影響。"},{"en":"Led only to more human impact means resulted mainly in greater disturbance caused by people.","zh":"只導致更多人類影響，是指主要造成更多由人類帶來的干擾。"},{"en":"Opening a quiet beach to cars may lead only to more human impact.","zh":"把安靜海灘開放給汽車，可能只導致更多人類影響。"},{"en":"If tourism facilities are not controlled, they may lead only to more human impact on nature.","zh":"如果旅遊設施不受控制，它們可能只導致自然環境受到更多人類影響。"},{"en":"The phrase suggests disappointment because access increased damage rather than protection.","zh":"這個短語帶有失望意味，因為通道增加了破壞而非保護。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":21},{"front":"U.S. Forest Service","meaning":"美國林務局","examples":[{"en":"The U.S. Forest Service reported visitor numbers in 1966.","zh":"美國林務局在1966年報告遊客人數。"},{"en":"The U.S. Forest Service is a government agency that manages national forests in the United States.","zh":"美國林務局是管理美國國家森林的政府機構。"},{"en":"The U.S. Forest Service may maintain trails, prevent fires, and protect wildlife.","zh":"美國林務局可能維護步道、防止火災和保護野生動物。"},{"en":"Reports from the U.S. Forest Service help researchers understand changes in forest use.","zh":"美國林務局的報告幫助研究人員理解森林使用變化。"},{"en":"Visitor numbers reported by the U.S. Forest Service can show human pressure on protected areas.","zh":"美國林務局報告的遊客人數可以顯示受保護地區的人類壓力。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":21},{"front":"a figure which could exceed","meaning":"這個數字可能超過","examples":[{"en":"The number of visitors is a figure which could exceed 40,000 today.","zh":"遊客人數這個數字今天可能超過四萬。"},{"en":"A figure which could exceed a number means a total that may be higher than that amount.","zh":"這個數字可能超過某數目，是指總數可能高於該數量。"},{"en":"The school expects a figure which could exceed 500 applicants this year.","zh":"學校預計今年申請人數這個數字可能超過五百。"},{"en":"If visitor numbers exceed expectations, parks may need more staff and protection measures.","zh":"如果遊客人數超出預期，公園可能需要更多人手和保護措施。"},{"en":"This phrase is useful when the exact number is uncertain but likely high.","zh":"當確切數字不確定但可能很高時，這個短語很有用。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":21},{"front":"endured in","meaning":"在……中忍耐生存","examples":[{"en":"The trees have endured in one of Earth’s most trying environments.","zh":"這些樹在地球上最艱苦的環境之一中忍耐生存。"},{"en":"Endured in means continued to survive in a difficult place or situation.","zh":"endured in 是指在困難地方或情況中持續生存。"},{"en":"Families endured in the village despite years of poor harvests.","zh":"儘管多年收成差，家庭仍在村莊中忍耐生存。"},{"en":"A plant that endured in dry soil must have strong survival adaptations.","zh":"在乾燥土壤中忍耐生存的植物，必須有強大的生存適應。"},{"en":"Bristlecones endured in harsh mountains for thousands of years.","zh":"刺果松在嚴酷山區中忍耐生存了數千年。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":21},{"front":"most trying environments","meaning":"最艱苦的環境","examples":[{"en":"The White Mountains are among Earth’s most trying environments.","zh":"白山山脈是地球上最艱苦的環境之一。"},{"en":"Most trying environments are extremely difficult places to live or survive in.","zh":"最艱苦的環境是極難生活或生存的地方。"},{"en":"Polar deserts are among the most trying environments for humans.","zh":"極地沙漠是人類最艱苦的環境之一。"},{"en":"Plants in the most trying environments often grow slowly and develop special adaptations.","zh":"最艱苦環境中的植物常生長緩慢並發展特殊適應。"},{"en":"Bristlecones are remarkable because they live in one of the most trying environments on Earth.","zh":"刺果松很了不起，因為它們生活在地球上最艱苦的環境之一。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":21},{"front":"deserve our respect and reverence","meaning":"值得我們尊重和敬畏","examples":[{"en":"These ancient trees deserve our respect and reverence.","zh":"這些古樹值得我們尊重和敬畏。"},{"en":"To deserve our respect and reverence means to be worthy of deep admiration and careful treatment.","zh":"值得我們尊重和敬畏，是指配得上深切欣賞和小心對待。"},{"en":"Old temples deserve our respect and reverence because they carry cultural memory.","zh":"古老寺廟值得我們尊重和敬畏，因為它們承載文化記憶。"},{"en":"Ancient trees deserve our respect and reverence because they survived long before us.","zh":"古樹值得我們尊重和敬畏，因為它們早在我們之前已生存很久。"},{"en":"The phrase suggests that people should protect, not simply visit, such natural wonders.","zh":"這個短語暗示人們應保護這些自然奇觀，而不只是參觀。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":21},{"front":"alters their environment","meaning":"改變其環境","examples":[{"en":"Global climate change slowly alters their environment.","zh":"全球氣候變化正慢慢改變其環境。"},{"en":"Alters their environment means changes the conditions around them.","zh":"改變其環境是指改變它們周圍的條件。"},{"en":"A new road alters animals’ environment by bringing noise and traffic.","zh":"新道路透過帶來噪音和交通，改變動物的環境。"},{"en":"Rising temperatures alter a forest environment by changing water and growth patterns.","zh":"氣溫上升透過改變水分和生長模式，改變森林環境。"},{"en":"If climate change alters their environment too much, bristlecones may lose suitable habitat.","zh":"如果氣候變化過度改變其環境，刺果松可能失去合適棲息地。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":21},{"front":"do our part to","meaning":"盡自己一分力去","examples":[{"en":"Humans must do our part to reduce our impact.","zh":"人類必須盡自己一分力去減少我們的影響。"},{"en":"To do our part to do something means to take personal responsibility for helping with a shared goal.","zh":"盡自己一分力去做某事，是指為共同目標承擔個人責任。"},{"en":"Students do their part to keep the classroom clean by throwing away rubbish.","zh":"學生透過丟掉垃圾，盡自己一分力保持課室清潔。"},{"en":"Families can do their part to save water by fixing leaks.","zh":"家庭可以透過修理漏水，盡自己一分力節約用水。"},{"en":"We do our part to protect forests when we follow rules and reduce damage.","zh":"當我們遵守規則並減少破壞時，就是盡自己一分力保護森林。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":21},{"front":"raise awareness","meaning":"提高意識","examples":[{"en":"We should raise awareness of the threat to bristlecone pines.","zh":"我們應提高人們對刺果松威脅的意識。"},{"en":"To raise awareness means to help more people understand an issue or problem.","zh":"提高意識是指幫助更多人理解某議題或問題。"},{"en":"Schools raise awareness of recycling by holding talks and poster campaigns.","zh":"學校透過講座和海報活動提高回收意識。"},{"en":"Documentaries can raise awareness of endangered animals and their habitats.","zh":"紀錄片可以提高人們對瀕危動物及其棲息地的意識。"},{"en":"Raising awareness is often the first step before people change their behaviour.","zh":"提高意識通常是人們改變行為前的第一步。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":21},{"front":"lower our impact","meaning":"減低我們的影響","examples":[{"en":"Humans must lower our impact on fragile habitats.","zh":"人類必須減低我們對脆弱棲息地的影響。"},{"en":"To lower our impact means to reduce the harm or pressure we place on something.","zh":"減低我們的影響是指減少我們對某事物造成的傷害或壓力。"},{"en":"Tourists can lower their impact by staying on marked trails.","zh":"遊客可以透過留在標示步道上來減低影響。"},{"en":"Families lower their impact on the environment by using less energy and producing less waste.","zh":"家庭透過使用較少能源和產生較少廢物，減低對環境的影響。"},{"en":"Around ancient trees, lowering our impact means visiting carefully and leaving nothing behind.","zh":"在古樹周圍，減低我們的影響意味著小心參觀並不留下任何東西。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":22},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"Students decide which paragraph contains the information.","zh":"學生判斷哪一段包含該資料。"},{"en":"Which paragraph contains means which section of the text includes a particular detail.","zh":"哪一段包含，是指文本中哪個段落包括某個特定細節。"},{"en":"In a reading test, students must find which paragraph contains the writer’s main example.","zh":"在閱讀測驗中，學生必須找出哪一段包含作者的主要例子。"},{"en":"This question type checks scanning skills rather than general opinion.","zh":"這類題型考查掃讀能力，而不是一般意見。"},{"en":"Students should look for keywords to decide which paragraph contains the answer.","zh":"學生應尋找關鍵字，以判斷哪一段包含答案。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":22},{"front":"the following information","meaning":"以下資料","examples":[{"en":"The task asks students to locate the following information.","zh":"任務要求學生找出以下資料的位置。"},{"en":"The following information means the details listed immediately after the instruction.","zh":"以下資料是指指示後立即列出的細節。"},{"en":"Please read the following information before filling in the form.","zh":"填寫表格前，請先閱讀以下資料。"},{"en":"In exams, the following information often appears as a list of points to match with paragraphs.","zh":"在考試中，以下資料常以要與段落配對的要點列表出現。"},{"en":"Students should not answer from memory; they should find the following information in the text.","zh":"學生不應憑記憶回答；他們應在文本中找出以下資料。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":22},{"front":"write the correct letter","meaning":"寫下正確字母","examples":[{"en":"Students write the correct letter in the answer boxes.","zh":"學生在答案格中寫下正確字母。"},{"en":"To write the correct letter means to put the right option label, such as A, B, or C.","zh":"寫下正確字母是指填入正確選項標籤，例如A、B或C。"},{"en":"In matching questions, students write the correct letter beside each number.","zh":"在配對題中，學生在每個題號旁寫下正確字母。"},{"en":"If students write the wrong letter, the answer may be marked incorrect even if they understood the idea.","zh":"如果學生寫錯字母，即使理解概念，答案也可能被判錯。"},{"en":"Checking the answer sheet helps ensure the correct letter is placed in the correct box.","zh":"檢查答題紙有助確保正確字母放在正確格子中。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":22},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生把答案寫在答題紙上。"},{"en":"An answer sheet is the paper or digital form where test-takers record their answers.","zh":"答題紙是考生記錄答案的紙張或電子表格。"},{"en":"Students should check the answer sheet before time ends.","zh":"學生應在時間結束前檢查答題紙。"},{"en":"A correct answer may be lost if it is written in the wrong place on the answer sheet.","zh":"如果正確答案寫在答題紙的錯誤位置，可能會失分。"},{"en":"In public exams, neat and accurate answer sheet marking is very important.","zh":"在公開考試中，整潔且準確填寫答題紙非常重要。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":22},{"front":"human activity threatens","meaning":"人類活動威脅","examples":[{"en":"The question asks where human activity threatens bristlecone-pine habitat.","zh":"題目問哪裡提到人類活動威脅刺果松棲息地。"},{"en":"Human activity threatens something when people’s actions create danger or damage.","zh":"當人的行動造成危險或破壞時，就是人類活動威脅某事物。"},{"en":"Building roads may mean human activity threatens quiet animal habitats.","zh":"修建道路可能意味著人類活動威脅安靜的動物棲息地。"},{"en":"Tourism can become a problem when human activity threatens fragile forests.","zh":"當人類活動威脅脆弱森林時，旅遊可能成為問題。"},{"en":"The phrase focuses on damage caused by people rather than natural causes.","zh":"這個短語集中於由人造成的破壞，而不是自然原因。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":22},{"front":"bristlecone-pine habitat","meaning":"刺果松棲息地","examples":[{"en":"Human activity and climate change threaten bristlecone-pine habitat.","zh":"人類活動和氣候變化威脅刺果松棲息地。"},{"en":"Bristlecone-pine habitat is the natural environment where bristlecone pines grow and survive.","zh":"刺果松棲息地是刺果松生長和生存的自然環境。"},{"en":"Bristlecone-pine habitat usually includes cold, dry, high mountain conditions.","zh":"刺果松棲息地通常包括寒冷、乾燥、高山條件。"},{"en":"If bristlecone-pine habitat becomes warmer or busier with tourists, the trees may suffer.","zh":"如果刺果松棲息地變暖或有更多遊客，這些樹可能受害。"},{"en":"Protecting bristlecone-pine habitat means protecting both the trees and their long climate records.","zh":"保護刺果松棲息地意味著保護樹木以及其長期氣候記錄。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":22},{"front":"reliable record","meaning":"可靠記錄","examples":[{"en":"Tree rings provide a reliable record of climate conditions.","zh":"樹輪提供氣候條件的可靠記錄。"},{"en":"A reliable record is information that can be trusted because it is accurate and consistent.","zh":"可靠記錄是因準確和一致而值得信任的資訊。"},{"en":"Hospitals need reliable records of patients’ medicine and test results.","zh":"醫院需要病人藥物和檢查結果的可靠記錄。"},{"en":"A reliable record helps people make decisions based on evidence, not guesses.","zh":"可靠記錄幫助人們根據證據而不是猜測作決定。"},{"en":"Tree rings are reliable records because they form regularly and preserve yearly conditions.","zh":"樹輪是可靠記錄，因為它們定期形成並保存每年條件。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":22},{"front":"extending from the past to the present","meaning":"從過去延伸至現在","examples":[{"en":"The record extends from the past to the present.","zh":"這項記錄從過去延伸至現在。"},{"en":"Extending from the past to the present means continuing across time from earlier periods until now.","zh":"從過去延伸至現在，是指跨越時間由較早時期持續到現在。"},{"en":"A family photo album may extend from the past to the present across several generations.","zh":"家庭相簿可能跨越幾代，從過去延伸至現在。"},{"en":"Climate records extending from the past to the present help scientists see long-term change.","zh":"從過去延伸至現在的氣候記錄，幫助科學家看見長期變化。"},{"en":"Bristlecone tree rings form a natural timeline extending from the past to the present.","zh":"刺果松樹輪形成一條從過去延伸至現在的自然時間線。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":22},{"front":"hostile environment","meaning":"惡劣環境","examples":[{"en":"The passage explains survival in a hostile environment.","zh":"文章解釋在惡劣環境中的生存。"},{"en":"A hostile environment is a place where conditions are difficult, dangerous, or unfriendly to life.","zh":"惡劣環境是條件困難、危險或不利於生命的地方。"},{"en":"A desert can be a hostile environment for plants that need constant water.","zh":"對需要持續水分的植物而言，沙漠可以是惡劣環境。"},{"en":"Animals in a hostile environment need special adaptations to survive.","zh":"惡劣環境中的動物需要特殊適應才能生存。"},{"en":"Bristlecones survive in a hostile environment of cold, wind, dryness, and poor soil.","zh":"刺果松在寒冷、強風、乾燥和貧瘠土壤的惡劣環境中生存。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":22},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter for each question.","zh":"學生為每題選出正確字母。"},{"en":"To choose the correct letter means to select the option label that matches the answer.","zh":"選出正確字母是指選擇與答案相符的選項標籤。"},{"en":"In multiple-choice questions, students choose the correct letter after reading all options.","zh":"在多項選擇題中，學生閱讀所有選項後選出正確字母。"},{"en":"A careless student may know the answer but choose the wrong letter on the sheet.","zh":"粗心學生可能知道答案，但在答題紙上選錯字母。"},{"en":"This instruction tells students to answer with letters, not full sentences.","zh":"這個指示告訴學生用字母作答，而不是完整句子。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":22},{"front":"according to paragraph A","meaning":"根據 A 段","examples":[{"en":"The question asks about information according to paragraph A.","zh":"題目詢問根據A段的資料。"},{"en":"According to paragraph A means based only on what paragraph A says.","zh":"根據A段是指只以A段所說內容為基礎。"},{"en":"According to paragraph A, students should not use information from later paragraphs.","zh":"根據A段作答時，學生不應使用後面段落的資料。"},{"en":"This instruction helps test whether readers can locate evidence in a specific part of the text.","zh":"這個指示幫助測試讀者是否能在文本特定部分定位證據。"},{"en":"When answering according to paragraph A, outside knowledge should not be used.","zh":"根據A段回答時，不應使用外部知識。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":23},{"front":"aspect of bristlecone pines","meaning":"刺果松的方面","examples":[{"en":"The question asks which aspect of bristlecone pines attracts attention.","zh":"題目問刺果松的哪一方面吸引注意。"},{"en":"An aspect of bristlecone pines is one particular feature or part of these trees.","zh":"刺果松的某方面是指這些樹的一個特定特徵或部分。"},{"en":"Their age, needles, habitat, and growth rings are all aspects of bristlecone pines.","zh":"其年齡、針葉、棲息地和生長年輪都是刺果松的方面。"},{"en":"Scientists focus on different aspects of bristlecone pines depending on their research question.","zh":"科學家會根據研究問題，集中於刺果松的不同方面。"},{"en":"In the passage, the most striking aspect of bristlecone pines is their longevity.","zh":"在文章中，刺果松最突出的方面是其長壽。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":23},{"front":"attracts the author’s attention","meaning":"吸引作者注意","examples":[{"en":"Their remarkable longevity attracts the author’s attention.","zh":"它們非凡的長壽吸引作者注意。"},{"en":"Attracts the author’s attention means makes the writer notice or focus on something.","zh":"吸引作者注意是指令作者注意或集中於某事。"},{"en":"A surprising statistic may attract the author’s attention at the start of an article.","zh":"一個令人驚訝的統計數字可能在文章開首吸引作者注意。"},{"en":"The tree’s extreme age attracts the author’s attention because it is unusual and meaningful.","zh":"這棵樹極高的年齡吸引作者注意，因為它不尋常且有意義。"},{"en":"When something attracts the author’s attention, it often becomes a main topic of the passage.","zh":"當某事吸引作者注意時，它常成為文章主要話題。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":23},{"front":"brutal environment","meaning":"嚴酷環境","examples":[{"en":"The brutal environment helps explain the tree’s longevity.","zh":"嚴酷環境有助解釋這棵樹的長壽。"},{"en":"A brutal environment is an extremely harsh and difficult place to live.","zh":"嚴酷環境是極其惡劣且難以生活的地方。"},{"en":"Arctic weather can create a brutal environment for unprepared travellers.","zh":"北極天氣可能為沒有準備的旅客造成嚴酷環境。"},{"en":"A brutal environment may reduce competition because few organisms can survive there.","zh":"嚴酷環境可能減少競爭，因為少數生物能在那裡生存。"},{"en":"Bristlecones live long partly because the brutal environment slows growth and limits rivals.","zh":"刺果松長壽，部分原因是嚴酷環境減慢生長並限制競爭者。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":23},{"front":"remarkable longevity","meaning":"非凡長壽","examples":[{"en":"The author focuses on the bristlecone pine’s remarkable longevity.","zh":"作者集中於刺果松的非凡長壽。"},{"en":"Remarkable longevity means unusually long life that attracts attention.","zh":"非凡長壽是指異常漫長並吸引注意的生命。"},{"en":"A person living past 110 has remarkable longevity.","zh":"一個活過110歲的人具有非凡長壽。"},{"en":"Remarkable longevity may result from genetics, environment, and protection from danger.","zh":"非凡長壽可能來自基因、環境和免受危險保護。"},{"en":"Bristlecone pines show remarkable longevity because some live for thousands of years.","zh":"刺果松展現非凡長壽，因為有些能活數千年。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":23},{"front":"outstanding height","meaning":"突出的高度","examples":[{"en":"The option refers to the tree’s outstanding height.","zh":"該選項提到這棵樹突出的高度。"},{"en":"Outstanding height means unusually great height compared with others.","zh":"突出的高度是指與其他相比異常高。"},{"en":"A basketball player with outstanding height may have an advantage near the basket.","zh":"有突出高度的籃球員可能在籃底有優勢。"},{"en":"Outstanding height can attract attention, but bristlecones are known more for age than height.","zh":"突出的高度可以吸引注意，但刺果松更以年齡而非高度聞名。"},{"en":"In this passage, outstanding height is not the main feature of bristlecone pines.","zh":"在本文中，突出的高度不是刺果松的主要特徵。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":23},{"front":"at higher elevations","meaning":"在較高海拔地區","examples":[{"en":"Bristlecone pines at higher elevations are investigated by scientists.","zh":"較高海拔地區的刺果松受到科學家研究。"},{"en":"At higher elevations means in places farther above sea level.","zh":"在較高海拔地區是指在離海平面更高的地方。"},{"en":"Plants at higher elevations often face colder nights and stronger winds.","zh":"較高海拔地區的植物常面對更寒冷夜晚和更強風。"},{"en":"Scientists study trees at higher elevations to understand mountain climate conditions.","zh":"科學家研究較高海拔地區的樹木，以理解山區氣候條件。"},{"en":"Bristlecones at higher elevations may grow slowly because warmth and water are limited.","zh":"較高海拔地區的刺果松可能因溫暖和水分有限而生長緩慢。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":23},{"front":"investigated","meaning":"被研究","examples":[{"en":"The oldest bristlecone specimens are investigated by researchers.","zh":"最古老的刺果松標本被研究人員研究。"},{"en":"Investigated means studied carefully to find facts or explanations.","zh":"investigated 是指被仔細研究，以找出事實或解釋。"},{"en":"Police investigated the accident by interviewing witnesses.","zh":"警方透過訪問目擊者調查意外。"},{"en":"Scientists investigated the tree rings to learn about past droughts.","zh":"科學家研究樹輪，以了解過去乾旱。"},{"en":"When something unusual is investigated, researchers try to understand why it happens.","zh":"當不尋常事物被研究時，研究人員會嘗試理解其原因。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":23},{"front":"oldest researched specimens","meaning":"最古老的受研究標本","examples":[{"en":"The oldest researched specimens occur in the White Mountains.","zh":"最古老的受研究標本出現在白山山脈。"},{"en":"Oldest researched specimens are the oldest examples that scientists have studied.","zh":"最古老的受研究標本是科學家已研究過的最古老例子。"},{"en":"A museum may keep the oldest researched specimens in a protected collection.","zh":"博物館可能把最古老的受研究標本保存在受保護收藏中。"},{"en":"The oldest researched specimens can provide rare information about long-term survival.","zh":"最古老的受研究標本可以提供關於長期生存的罕見資訊。"},{"en":"In the passage, the oldest researched specimens of bristlecone pine are linked to the White Mountains.","zh":"在文章中，最古老的刺果松受研究標本與白山山脈有關。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":23},{"front":"precipitation is abundant","meaning":"降雨量充沛","examples":[{"en":"The option asks whether precipitation is abundant in the region.","zh":"該選項問該地區降雨量是否充沛。"},{"en":"If precipitation is abundant, there is a large amount of rain, snow, or moisture.","zh":"如果降雨量充沛，即是有大量雨、雪或水分。"},{"en":"Rice grows well in places where precipitation is abundant.","zh":"水稻在降雨量充沛的地方生長良好。"},{"en":"In the White Mountains, precipitation is not abundant; it is very limited.","zh":"在白山山脈，降雨量並不充沛；它非常有限。"},{"en":"This phrase describes wet conditions, which contrast with the dry bristlecone habitat.","zh":"這個短語描述潮濕條件，與乾燥刺果松棲息地形成對比。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":23},{"front":"comparatively high above sea level","meaning":"海拔相對較高","examples":[{"en":"The area lies comparatively high above sea level.","zh":"該地區海拔相對較高。"},{"en":"Comparatively high above sea level means higher than many other places when compared.","zh":"海拔相對較高是指與許多其他地方相比位置較高。"},{"en":"A mountain village may be comparatively high above sea level, so nights are cold.","zh":"山村可能海拔相對較高，所以夜晚寒冷。"},{"en":"Areas comparatively high above sea level often have thinner air and shorter growing seasons.","zh":"海拔相對較高的地區通常空氣較稀薄，生長季節較短。"},{"en":"The White Mountains are comparatively high above sea level, which helps explain their harsh climate.","zh":"白山山脈海拔相對較高，這有助解釋其嚴酷氣候。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":23},{"front":"repeated long-term patterns","meaning":"重複的長期模式","examples":[{"en":"The question asks why there are no repeated long-term patterns.","zh":"題目問為何沒有重複的長期模式。"},{"en":"Repeated long-term patterns are the same sequences appearing again over many years.","zh":"重複的長期模式是指相同序列在多年中再次出現。"},{"en":"Weather may have seasons, but exact repeated long-term patterns are rare.","zh":"天氣可能有季節，但完全重複的長期模式很少見。"},{"en":"Tree-ring records have no repeated long-term patterns because yearly climate variation is unique.","zh":"樹輪記錄沒有重複的長期模式，因為每年氣候變化都是獨特的。"},{"en":"If repeated long-term patterns existed, dating tree rings would be less precise.","zh":"如果存在重複的長期模式，樹輪定年就會較不精確。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":24},{"front":"completely random","meaning":"完全隨機","examples":[{"en":"The option suggests that tree-ring patterns are completely random.","zh":"該選項暗示樹輪模式完全隨機。"},{"en":"Completely random means happening without any order, pattern, or cause.","zh":"完全隨機是指沒有任何次序、模式或原因地發生。"},{"en":"Guessing answers without reading is completely random.","zh":"不閱讀就猜答案是完全隨機的。"},{"en":"Tree-ring patterns are not completely random because climate affects ring width.","zh":"樹輪模式不是完全隨機，因為氣候會影響年輪寬度。"},{"en":"Something can vary from year to year without being completely random.","zh":"某事可以每年不同，但不一定完全隨機。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":24},{"front":"climatic variations","meaning":"氣候變化","examples":[{"en":"Climatic variations affect the width of tree rings.","zh":"氣候變化影響樹輪寬度。"},{"en":"Climatic variations are changes in climate conditions such as temperature, rainfall, or drought.","zh":"氣候變化是指氣溫、降雨或乾旱等氣候條件的變化。"},{"en":"Farmers notice climatic variations when harvests differ greatly from year to year.","zh":"當收成每年差異很大時，農民會注意到氣候變化。"},{"en":"Climatic variations create different growth patterns in trees.","zh":"氣候變化在樹木中造成不同生長模式。"},{"en":"Tree rings are useful because they preserve evidence of climatic variations.","zh":"樹輪有用，因為它們保存氣候變化的證據。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":24},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the short text that follows.","zh":"完成以下摘要是指填補後面短文中的空缺字詞。"},{"en":"In reading exams, students complete the summary below by finding exact words in the passage.","zh":"在閱讀考試中，學生透過在文章中找出原字來完成以下摘要。"},{"en":"This task tests whether students understand the main ideas and details.","zh":"這項任務測試學生是否理解主要思想和細節。"},{"en":"Students should check grammar after they complete the summary below.","zh":"學生完成以下摘要後，應檢查文法。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":24},{"front":"no more than three words","meaning":"不多於三個字","examples":[{"en":"Students choose no more than three words from the passage.","zh":"學生從文章中選擇不多於三個字。"},{"en":"No more than three words means the answer must contain three words or fewer.","zh":"不多於三個字是指答案必須包含三個字或以下。"},{"en":"If the instruction says no more than three words, a four-word answer is wrong.","zh":"如果指示說不多於三個字，四個字的答案就是錯。"},{"en":"Students should copy carefully and avoid adding unnecessary words.","zh":"學生應小心抄寫，避免加入不必要字詞。"},{"en":"This rule tests precision as well as comprehension.","zh":"這條規則既測試準確性，也測試理解力。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":24},{"front":"special adaptations","meaning":"特殊適應","examples":[{"en":"The bristlecone’s special adaptations help it survive.","zh":"刺果松的特殊適應幫助它生存。"},{"en":"Special adaptations are features that help an organism live in a particular environment.","zh":"特殊適應是幫助生物在特定環境中生活的特徵。"},{"en":"Thick leaves are special adaptations for some plants in dry places.","zh":"厚葉是某些乾燥地區植物的特殊適應。"},{"en":"Special adaptations can reduce water loss, protect from cold, or improve reproduction.","zh":"特殊適應可以減少水分流失、抵抗寒冷或改善繁殖。"},{"en":"Bristlecones have special adaptations for surviving wind, cold, drought, and poor soil.","zh":"刺果松有特殊適應，以在強風、寒冷、乾旱和貧瘠土壤中生存。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":24},{"front":"aid photosynthesis","meaning":"幫助光合作用","examples":[{"en":"The needles aid photosynthesis during harsh months.","zh":"針葉在嚴酷月份幫助光合作用。"},{"en":"To aid photosynthesis means to help the plant make food using sunlight.","zh":"幫助光合作用是指幫助植物利用陽光製造食物。"},{"en":"Healthy leaves aid photosynthesis by capturing light efficiently.","zh":"健康葉片透過有效吸收光線來幫助光合作用。"},{"en":"If leaves are damaged, they may no longer aid photosynthesis well.","zh":"如果葉片受損，它們可能不能再很好地幫助光合作用。"},{"en":"Bristlecone needles aid photosynthesis because they stay alive and hold chlorophyll for years.","zh":"刺果松針葉幫助光合作用，因為它們多年保持存活並含有葉綠素。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":24},{"front":"conserve the energy required for","meaning":"節省……所需的能量","examples":[{"en":"The adaptation conserves the energy required for leaf replacement.","zh":"這種適應節省更換葉片所需的能量。"},{"en":"To conserve the energy required for something means to save the energy normally needed for that process.","zh":"節省某事所需的能量，是指保存該過程通常需要的能量。"},{"en":"Using a timetable can conserve the energy required for making decisions every morning.","zh":"使用時間表可以節省每天早上作決定所需的能量。"},{"en":"Evergreen needles conserve the energy required for growing new leaves every year.","zh":"常綠針葉節省每年長出新葉所需的能量。"},{"en":"Bristlecones conserve the energy required for replacement by keeping needles for a long time.","zh":"刺果松透過長時間保留針葉，節省更換所需的能量。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":24},{"front":"leaf replacement","meaning":"更換葉片","examples":[{"en":"The tree saves energy by avoiding constant leaf replacement.","zh":"這棵樹透過避免不斷更換葉片來節省能量。"},{"en":"Leaf replacement is the process of growing new leaves to replace old or lost ones.","zh":"更換葉片是長出新葉以取代舊葉或失去葉片的過程。"},{"en":"Deciduous trees go through leaf replacement after losing leaves in autumn.","zh":"落葉樹在秋天落葉後會經歷更換葉片。"},{"en":"Leaf replacement uses energy that a plant might otherwise use for growth or repair.","zh":"更換葉片使用的能量，本可被植物用於生長或修復。"},{"en":"Bristlecones reduce leaf replacement by keeping needles for many years.","zh":"刺果松透過多年保留針葉來減少更換葉片。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":24},{"front":"stable supply of chlorophyll","meaning":"穩定葉綠素供應","examples":[{"en":"The needles provide a stable supply of chlorophyll.","zh":"針葉提供穩定葉綠素供應。"},{"en":"A stable supply of chlorophyll means the tree keeps enough green pigment for photosynthesis.","zh":"穩定葉綠素供應是指樹木保持足夠用於光合作用的綠色色素。"},{"en":"Healthy leaves give plants a stable supply of chlorophyll during the growing season.","zh":"健康葉片在生長季節為植物提供穩定葉綠素供應。"},{"en":"If leaves fall too often, a stable supply of chlorophyll becomes harder to maintain.","zh":"如果葉片太頻繁脫落，穩定葉綠素供應就較難維持。"},{"en":"Bristlecone needles help maintain a stable supply of chlorophyll in harsh climates.","zh":"刺果松針葉幫助在嚴酷氣候中維持穩定葉綠素供應。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":24},{"front":"narrow bands intact","meaning":"只留下狹窄帶狀部分完整","examples":[{"en":"Cambium dieback leaves only narrow bands intact.","zh":"形成層枯死只留下狹窄帶狀部分完整。"},{"en":"Narrow bands intact means only thin strips remain whole and undamaged.","zh":"只留下狹窄帶狀部分完整，是指只有薄條狀部分仍完整未損。"},{"en":"After the storm, narrow bands of paint remained intact on the old wall.","zh":"風暴後，舊牆上只留下狹窄油漆帶完整。"},{"en":"In bristlecones, narrow bands intact can still carry life to parts of the tree.","zh":"在刺果松中，完整的狹窄帶狀部分仍可把生命輸送到樹的一些部分。"},{"en":"This phrase shows that most tissue may die while small living strips survive.","zh":"這個短語顯示大部分組織可能死亡，而小片活帶仍存活。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":24},{"front":"rich in resin","meaning":"富含樹脂","examples":[{"en":"Bristlecone rings have a tight structure rich in resin.","zh":"刺果松年輪有緊密且富含樹脂的結構。"},{"en":"Rich in resin means containing a large amount of sticky protective tree substance.","zh":"富含樹脂是指含有大量黏性的樹木保護物質。"},{"en":"Pine wood rich in resin may resist insects and decay better.","zh":"富含樹脂的松木可能更能抵抗昆蟲和腐爛。"},{"en":"Wood rich in resin can be harder, smell stronger, and last longer.","zh":"富含樹脂的木材可能更硬、氣味更濃且更耐久。"},{"en":"Bristlecone wood is durable partly because its rings are rich in resin.","zh":"刺果松木材耐久，部分原因是其年輪富含樹脂。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":25},{"front":"protected from fire","meaning":"受保護免受火災影響","examples":[{"en":"Bristlecone stands are protected from fire by sparse vegetation.","zh":"刺果松林分因稀疏植被而受保護免受火災影響。"},{"en":"Protected from fire means kept safe from being burned or damaged by fire.","zh":"受保護免受火災影響，是指免於被火燒毀或損害。"},{"en":"Firebreaks help forests stay protected from fire.","zh":"防火帶幫助森林受保護免受火災影響。"},{"en":"Buildings are protected from fire when they use alarms, sprinklers, and safe materials.","zh":"建築物使用警報、灑水系統和安全材料時，會受保護免受火災影響。"},{"en":"Bristlecone stands are protected from fire because there is little ground vegetation to burn.","zh":"刺果松林分受保護免受火災影響，因為地面可燃植被很少。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":25},{"front":"viewed from a distance","meaning":"從遠處看時","examples":[{"en":"The peaks appear lower when viewed from a distance.","zh":"這些山峰從遠處看時顯得較低。"},{"en":"Viewed from a distance means seen from far away rather than close up.","zh":"從遠處看時，是指從遠方而不是近距離觀看。"},{"en":"Viewed from a distance, the island looks small, but it is large when you arrive.","zh":"從遠處看時，這座島顯得很小，但到達後會發現它很大。"},{"en":"Problems may seem simple when viewed from a distance, but details can change your opinion.","zh":"問題從遠處看時可能顯得簡單，但細節會改變你的看法。"},{"en":"Mountain height can be misjudged when peaks are viewed from a distance.","zh":"當山峰從遠處看時，人們可能誤判其高度。"}],"source":"148 - Longaeva - Ancient Bristlecone Pine.pdf","sourcePage":25}],"ielts/reading/passage-2/Practice 149":[{"front":"Western immigration","meaning":"西部移民","examples":[{"en":"The passage discusses western immigration to Canada.","zh":"文章討論到加拿大的西部移民。"},{"en":"Western immigration means the movement of settlers or immigrants into western Canada.","zh":"西部移民指定居者或移民遷入加拿大西部。"},{"en":"A farming family might join western immigration to look for land and work.","zh":"一個農民家庭可能參與西部移民，以尋找土地和工作。"},{"en":"Western immigration can increase population and create new towns.","zh":"西部移民可以增加人口並建立新城鎮。"},{"en":"The phrase is often used when discussing Canada’s settlement history.","zh":"這個片語常用於討論加拿大定居歷史。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":1},{"front":"by the mid-1870s","meaning":"到十九世紀七十年代中期","examples":[{"en":"By the mid-1870s, Canada wanted agricultural settlers in the West.","zh":"到十九世紀七十年代中期，加拿大希望西部有農業定居者。"},{"en":"By the mid-1870s means around the middle years of the 1870s.","zh":"by the mid-1870s 指大約到1870年代中期。"},{"en":"By the mid-1870s, some towns had already begun to grow around railway routes.","zh":"到十九世紀七十年代中期，一些城鎮已開始沿鐵路路線發展。"},{"en":"If a policy existed by the mid-1870s, it was already in place before the decade ended.","zh":"如果一項政策到十九世紀七十年代中期已存在，它就在該年代結束前已實行。"},{"en":"This phrase helps place an event in a broad historical period.","zh":"這個片語幫助把事件放在較概括的歷史時期中。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":1},{"front":"immigrant population","meaning":"移民人口","examples":[{"en":"Canada wanted an immigrant population established in the West.","zh":"加拿大希望西部建立移民人口。"},{"en":"An immigrant population is a group of people who have moved from another country or region.","zh":"移民人口是從其他國家或地區遷來的一群人。"},{"en":"A city’s immigrant population may bring new languages, foods, and skills.","zh":"一個城市的移民人口可能帶來新語言、食物和技能。"},{"en":"When an immigrant population grows, schools and services may need to expand.","zh":"當移民人口增長，學校和服務可能需要擴展。"},{"en":"The phrase describes people, not just the process of moving.","zh":"這個片語描述的是人群，而不只是遷移過程。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":1},{"front":"agricultural settlers","meaning":"農業定居者","examples":[{"en":"Canada wanted agricultural settlers established in the West.","zh":"加拿大希望農業定居者在西部定居。"},{"en":"Agricultural settlers are people who move to a place mainly to farm land.","zh":"農業定居者是主要為耕種土地而遷到某地的人。"},{"en":"Agricultural settlers may build homes, clear fields, and grow crops.","zh":"農業定居者可能建屋、開墾田地和種植作物。"},{"en":"If agricultural settlers arrive in large numbers, rural communities can expand quickly.","zh":"如果農業定居者大量到來，鄉郊社區可以迅速擴張。"},{"en":"They differ from urban migrants because farming is central to their settlement.","zh":"他們不同於城市移民，因為農業是其定居的核心。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":1},{"front":"be established in","meaning":"在……定居；建立於","examples":[{"en":"A population of agricultural settlers was to be established in the West.","zh":"一批農業定居者人口將在西部定居。"},{"en":"Be established in means be set up, settled, or made stable in a place.","zh":"be established in 指在某地建立、定居或穩定下來。"},{"en":"A new clinic may be established in a growing neighbourhood.","zh":"一間新診所可能建立於一個正在增長的社區。"},{"en":"Once a school is established in a village, local children can study nearby.","zh":"一所學校在村莊建立後，本地孩子便可在附近上學。"},{"en":"The phrase suggests more than arriving; it suggests becoming settled.","zh":"這個片語不只表示到達，也表示穩定下來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":1},{"front":"urban centres","meaning":"城市中心","examples":[{"en":"No urban centres existed on the prairies in the 1870s.","zh":"1870年代，大草原地區沒有城市中心。"},{"en":"Urban centres are large towns or cities where many people, shops, and services are found.","zh":"城市中心是人口、商店和服務集中的大型城鎮或城市。"},{"en":"Hospitals and universities are often located in urban centres.","zh":"醫院和大學通常位於城市中心。"},{"en":"When urban centres grow, transport and housing demand usually increase.","zh":"當城市中心發展，交通和住房需求通常會增加。"},{"en":"The phrase contrasts with small villages or rural areas.","zh":"這個片語與小村莊或鄉郊地區形成對比。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":1},{"front":"on the prairies","meaning":"在大草原地區","examples":[{"en":"No urban centres existed on the prairies in the 1870s.","zh":"1870年代，大草原地區沒有城市中心。"},{"en":"On the prairies means in the wide flat grassland regions of central Canada.","zh":"on the prairies 指在加拿大中部廣闊平坦的草原地區。"},{"en":"Farmers on the prairies often need large areas of land for crops.","zh":"大草原地區的農民通常需要大片土地種植作物。"},{"en":"Strong winds on the prairies can make winter travel difficult.","zh":"大草原地區的強風可以令冬季出行困難。"},{"en":"The phrase points to a particular landscape, not just any countryside.","zh":"這個片語指特定地貌，而不是任何鄉郊。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":1},{"front":"rural settlement","meaning":"鄉郊定居","examples":[{"en":"Rural settlement was the focus of the federal government’s attention.","zh":"鄉郊定居是聯邦政府關注的焦點。"},{"en":"Rural settlement means people moving to and living in countryside areas.","zh":"鄉郊定居指人們遷往並居住在鄉郊地區。"},{"en":"Rural settlement may involve farms, small villages, and local roads.","zh":"鄉郊定居可能涉及農場、小村莊和本地道路。"},{"en":"If rural settlement succeeds, land can be farmed and communities can grow.","zh":"如果鄉郊定居成功，土地可被耕種，社區也可成長。"},{"en":"It is different from urban growth because it centres on countryside life.","zh":"它不同於城市發展，因為它以鄉郊生活為中心。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":1},{"front":"the focus of","meaning":"……的焦點","examples":[{"en":"Rural settlement was the focus of the government’s attention.","zh":"鄉郊定居是政府關注的焦點。"},{"en":"The focus of something is the main thing receiving attention or effort.","zh":"the focus of 指最受關注或最需要努力的主要事情。"},{"en":"Exam preparation may be the focus of a student’s weekend.","zh":"考試準備可能是一名學生週末的焦點。"},{"en":"If housing becomes the focus of policy, more money may go into building homes.","zh":"如果住房成為政策焦點，更多資金可能用於建屋。"},{"en":"The phrase helps show what matters most in a situation.","zh":"這個片語幫助顯示某情況中最重要的事情。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":1},{"front":"federal government","meaning":"聯邦政府","examples":[{"en":"The federal government focused on rural settlement in the West.","zh":"聯邦政府集中於西部的鄉郊定居。"},{"en":"A federal government is the national government of a country with shared central and regional powers.","zh":"聯邦政府是在中央和地方分享權力制度下的國家政府。"},{"en":"The federal government may create immigration laws and national transport plans.","zh":"聯邦政府可能制定移民法律和全國交通計劃。"},{"en":"If the federal government funds a railway, distant regions may become connected.","zh":"如果聯邦政府資助鐵路，遙遠地區可能被連接起來。"},{"en":"The phrase usually refers to the national level, not a town council.","zh":"這個片語通常指國家層面，而不是市鎮議會。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":1},{"front":"be desired because","meaning":"因為……而被需要","examples":[{"en":"Rural settlement in the West was desired because eastern farmland was reaching capacity.","zh":"西部鄉郊定居因東部農地快達容量上限而被需要。"},{"en":"Be desired because means be wanted for a particular reason.","zh":"be desired because 指因某個特定原因而被需要或希望得到。"},{"en":"Extra teachers may be desired because classes are too large.","zh":"因為班級太大，學校可能需要額外教師。"},{"en":"New buses are desired because old routes are overcrowded.","zh":"因為舊路線太擠迫，市民可能需要新巴士。"},{"en":"The phrase links a need with the reason behind it.","zh":"這個片語把需要與背後原因連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":2},{"front":"provide homesteads for","meaning":"為……提供宅地","examples":[{"en":"The rural West would provide homesteads for the children of eastern farmers.","zh":"鄉郊西部會為東部農民的子女提供宅地。"},{"en":"Provide homesteads for means give people land where they can live and farm.","zh":"provide homesteads for 指為人們提供可居住和耕作的土地。"},{"en":"A government may provide homesteads for families willing to settle remote areas.","zh":"政府可能為願意定居偏遠地區的家庭提供宅地。"},{"en":"If land is provided as homesteads, young families can begin independent farms.","zh":"如果土地作為宅地提供，年輕家庭可以開始獨立農場。"},{"en":"The phrase suggests land for both home and agricultural use.","zh":"這個片語暗示土地同時用於居住和農業。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":2},{"front":"homesteads","meaning":"宅地；農莊用地","examples":[{"en":"The West could provide homesteads for settlers.","zh":"西部可以為定居者提供宅地。"},{"en":"Homesteads are pieces of land where settlers build homes and often farm.","zh":"宅地是定居者建屋並通常耕作的土地。"},{"en":"A family on a homestead may grow crops and keep animals.","zh":"住在宅地上的家庭可能種植作物和飼養動物。"},{"en":"Homesteads can encourage settlement because land gives families a base.","zh":"宅地可以鼓勵定居，因為土地給家庭一個基礎。"},{"en":"The word is common in discussions of frontier farming.","zh":"這個詞常見於邊疆農業的討論。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":2},{"front":"sons and daughters of","meaning":"……的子女","examples":[{"en":"The West offered land for the sons and daughters of eastern farmers.","zh":"西部為東部農民的子女提供土地。"},{"en":"Sons and daughters of means the children of particular parents or groups.","zh":"sons and daughters of 指某些父母或群體的子女。"},{"en":"Schools often serve the sons and daughters of local workers.","zh":"學校常服務本地工人的子女。"},{"en":"If farms cannot be divided further, the sons and daughters of farmers may seek land elsewhere.","zh":"如果農場不能再分割，農民的子女可能到別處尋找土地。"},{"en":"The phrase identifies people through their family background.","zh":"這個片語透過家庭背景識別人。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":2},{"front":"eastern farmers","meaning":"東部農民","examples":[{"en":"Eastern farmers needed new agricultural land for their families.","zh":"東部農民需要新的農地給家人。"},{"en":"Eastern farmers are farmers living in the eastern part of a country or region.","zh":"東部農民是住在一個國家或地區東部的農民。"},{"en":"Eastern farmers may face land shortages if farms are already divided among many families.","zh":"如果農場已分給許多家庭，東部農民可能面對土地短缺。"},{"en":"When eastern farmers lack space, their children may move west for land.","zh":"當東部農民缺少空間，他們的子女可能向西遷移尋找土地。"},{"en":"In this passage, the phrase refers to farmers in eastern Canada.","zh":"在本文中，這個片語指加拿大東部的農民。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":2},{"front":"agricultural land","meaning":"農地","examples":[{"en":"Agricultural land in the East reached capacity.","zh":"東部的農地已達到容量上限。"},{"en":"Agricultural land is land used for growing crops or raising animals.","zh":"農地是用於種植作物或飼養動物的土地。"},{"en":"A village needs agricultural land if most families depend on farming.","zh":"如果多數家庭依賴農業，一條村需要農地。"},{"en":"If agricultural land becomes scarce, food production and family inheritance may be affected.","zh":"如果農地變得稀少，食物生產和家庭繼承可能受影響。"},{"en":"The phrase is more specific than land because it focuses on farming use.","zh":"這個片語比土地更具體，因為它集中於農業用途。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":2},{"front":"reach capacity","meaning":"達到容量上限；已用盡","examples":[{"en":"Agricultural land in the East had reached capacity.","zh":"東部農地已達到容量上限。"},{"en":"Reach capacity means become full or unable to take more use, people, or demand.","zh":"reach capacity 指變滿，或無法再承受更多使用、人數或需求。"},{"en":"A classroom reaches capacity when every seat is taken.","zh":"當每個座位都坐滿，課室就達到容量上限。"},{"en":"If a hospital reaches capacity, new patients may wait longer for care.","zh":"如果醫院達到容量上限，新病人可能要等更久。"},{"en":"The phrase suggests that expansion or extra space is needed.","zh":"這個片語暗示需要擴展或額外空間。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":2},{"front":"furthermore","meaning":"此外","examples":[{"en":"Furthermore, politicians saw western Canada as suitable for agricultural expansion.","zh":"此外，政客認為加拿大西部適合農業擴張。"},{"en":"Furthermore means in addition to what has already been said.","zh":"furthermore 指除了前面所說之外。"},{"en":"The flat is near school; furthermore, the rent is affordable.","zh":"這個單位靠近學校；此外，租金也可負擔。"},{"en":"A policy may save money; furthermore, it may improve public services.","zh":"一項政策可能節省金錢；此外，它也可能改善公共服務。"},{"en":"The word adds another supporting point to an argument.","zh":"這個詞為論點加入另一個支持點。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":2},{"front":"broad expanses of","meaning":"廣闊大片的……","examples":[{"en":"Western Canada had broad expanses of unpopulated land.","zh":"加拿大西部有廣闊大片的無人居住土地。"},{"en":"Broad expanses of means very large open areas of something.","zh":"broad expanses of 指非常廣闊開放的大面積事物。"},{"en":"Travellers may see broad expanses of desert from a train window.","zh":"旅客可能從火車窗外看見廣闊大片的沙漠。"},{"en":"Broad expanses of empty land can attract people looking for farms.","zh":"廣闊大片的空地可以吸引尋找農場的人。"},{"en":"The phrase creates an image of wide open space.","zh":"這個片語營造出寬廣開闊空間的畫面。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":2},{"front":"unpopulated land","meaning":"無人居住的土地","examples":[{"en":"Western Canada contained broad expanses of unpopulated land.","zh":"加拿大西部包含廣闊大片的無人居住土地。"},{"en":"Unpopulated land is land where few or no people live permanently.","zh":"無人居住的土地是很少或沒有人永久居住的土地。"},{"en":"A government may survey unpopulated land before planning roads or farms.","zh":"政府可能在規劃道路或農場前勘察無人居住的土地。"},{"en":"If unpopulated land is settled, new services and conflicts may appear.","zh":"如果無人居住的土地被開發定居，新服務和衝突都可能出現。"},{"en":"The phrase describes population, not whether the land is valuable.","zh":"這個片語描述人口情況，而不是土地是否有價值。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":2},{"front":"a prime location for","meaning":"……的理想地點","examples":[{"en":"Western Canada was viewed as a prime location for agricultural expansion.","zh":"加拿大西部被視為農業擴張的理想地點。"},{"en":"A prime location for something is a very suitable or valuable place for that purpose.","zh":"a prime location for 指非常適合或有價值用於某目的的地方。"},{"en":"A shop near a station is a prime location for selling breakfast.","zh":"車站附近的店舖是賣早餐的理想地點。"},{"en":"If land has good soil and water, it may be a prime location for farming.","zh":"如果土地有良好土壤和水源，它可能是農業的理想地點。"},{"en":"The phrase suggests strong suitability, not just possibility.","zh":"這個片語表示高度適合，而不只是可能。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":3},{"front":"expanding agricultural output","meaning":"擴大農業產量","examples":[{"en":"Western Canada could help expand Canada’s agricultural output.","zh":"加拿大西部可以幫助擴大加拿大的農業產量。"},{"en":"Expanding agricultural output means increasing the amount of farm products produced.","zh":"expanding agricultural output 指增加農產品的產出量。"},{"en":"A farm may expand agricultural output by planting more fields.","zh":"農場可以透過種植更多田地來擴大農業產量。"},{"en":"Better tools can expand agricultural output if farmers use them effectively.","zh":"如果農民有效使用更好的工具，就可以擴大農業產量。"},{"en":"The phrase focuses on producing more food or crops.","zh":"這個片語集中於生產更多食物或作物。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":3},{"front":"agricultural output","meaning":"農業產量","examples":[{"en":"Politicians wanted to increase Canada’s agricultural output.","zh":"政客希望增加加拿大的農業產量。"},{"en":"Agricultural output is the total amount of crops, food, or farm products produced.","zh":"農業產量是作物、食物或農產品的總產出。"},{"en":"A country’s agricultural output may rise after a good harvest.","zh":"豐收後，一個國家的農業產量可能上升。"},{"en":"Drought can reduce agricultural output and raise food prices.","zh":"乾旱可以減少農業產量並推高食物價格。"},{"en":"This phrase is common in economic and farming discussions.","zh":"這個片語常見於經濟和農業討論。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":3},{"front":"in terms of","meaning":"在……方面","examples":[{"en":"The West was important in terms of wheat production.","zh":"西部在小麥生產方面十分重要。"},{"en":"In terms of means when considering a particular aspect or measure.","zh":"in terms of 指從某一方面或標準來看。"},{"en":"In terms of cost, the bus is cheaper than a taxi.","zh":"在成本方面，巴士比的士便宜。"},{"en":"A school may be strong in terms of science but weaker in sports.","zh":"一所學校可能在科學方面強，但在體育方面較弱。"},{"en":"The phrase tells readers which angle is being used.","zh":"這個片語告訴讀者正在使用哪個角度。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":3},{"front":"wheat production","meaning":"小麥生產","examples":[{"en":"Western Canada was suitable for wheat production.","zh":"加拿大西部適合小麥生產。"},{"en":"Wheat production means growing and harvesting wheat as a crop.","zh":"小麥生產指種植和收割小麥作為農作物。"},{"en":"Wheat production needs suitable land, weather, seeds, and labour.","zh":"小麥生產需要合適土地、天氣、種子和勞動力。"},{"en":"If wheat production increases, flour and bread supplies may become more stable.","zh":"如果小麥生產增加，麵粉和麵包供應可能更穩定。"},{"en":"The phrase refers to farming wheat, not simply eating it.","zh":"這個片語指種植小麥，而不只是食用小麥。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":3},{"front":"serve the markets of","meaning":"供應……的市場","examples":[{"en":"Wheat production in the West could serve the markets of eastern Canada.","zh":"西部的小麥生產可以供應加拿大東部的市場。"},{"en":"Serve the markets of means supply goods to customers in a particular place.","zh":"serve the markets of 指向某地的顧客市場供應貨品。"},{"en":"A bakery may serve the markets of nearby schools and offices.","zh":"麵包店可能供應附近學校和辦公室的市場。"},{"en":"If farms serve the markets of large cities, transport links become important.","zh":"如果農場供應大城市的市場，交通連接就變得重要。"},{"en":"The phrase connects production with buyers.","zh":"這個片語把生產與買家連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":3},{"front":"eastern Canada","meaning":"加拿大東部","examples":[{"en":"Western wheat could serve the markets of eastern Canada.","zh":"西部小麥可以供應加拿大東部的市場。"},{"en":"Eastern Canada means the eastern part of Canada, including older settled regions.","zh":"加拿大東部指加拿大東面的地區，包括較早開發的地區。"},{"en":"Many factories and cities were located in eastern Canada.","zh":"許多工廠和城市位於加拿大東部。"},{"en":"If western farms sold food to eastern Canada, railways became necessary.","zh":"如果西部農場向加拿大東部出售食物，鐵路就變得必要。"},{"en":"The phrase contrasts with Canada’s western regions.","zh":"這個片語與加拿大西部地區形成對比。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":3},{"front":"bolster Canada’s population","meaning":"增加加拿大人口","examples":[{"en":"The government wanted to bolster Canada’s population.","zh":"政府希望增加加拿大人口。"},{"en":"Bolster Canada’s population means increase or strengthen the number of people living in Canada.","zh":"bolster Canada’s population 指增加或強化居住在加拿大的人口數量。"},{"en":"Immigration can bolster a town’s population when young people leave.","zh":"當年輕人離開時，移民可以增加一個城鎮的人口。"},{"en":"A larger population can bolster markets, labour supply, and national security.","zh":"較大人口可以強化市場、勞動力供應和國家安全。"},{"en":"The verb bolster suggests support and strengthening.","zh":"bolster 這個動詞帶有支持和加強的意思。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":3},{"front":"take steps to","meaning":"採取措施去","examples":[{"en":"The federal government took steps to secure western land.","zh":"聯邦政府採取措施去取得並保障西部土地。"},{"en":"Take steps to means begin actions to achieve a goal.","zh":"take steps to 指開始採取行動以達成目標。"},{"en":"A school may take steps to reduce bullying.","zh":"學校可能採取措施去減少欺凌。"},{"en":"If a city takes steps to improve buses, commuters may benefit.","zh":"如果城市採取措施去改善巴士，通勤者可能受惠。"},{"en":"The phrase usually suggests planned action, not just hope.","zh":"這個片語通常表示有計劃的行動，而不只是希望。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":3},{"front":"secure western land","meaning":"取得並保障西部土地","examples":[{"en":"The federal government took steps to secure western land.","zh":"聯邦政府採取措施取得並保障西部土地。"},{"en":"Secure western land means obtain, control, or protect land in the western region.","zh":"secure western land 指取得、控制或保護西部地區的土地。"},{"en":"A government may secure land before building roads or settlements.","zh":"政府可能在建設道路或定居點前取得土地。"},{"en":"If land is secured, future settlers may feel safer moving there.","zh":"如果土地得到保障，未來定居者可能更安心遷往那裡。"},{"en":"The phrase can imply both legal ownership and political protection.","zh":"這個片語可以暗示法律擁有權和政治保護。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":3},{"front":"the Dominion of Canada","meaning":"加拿大自治領","examples":[{"en":"The Dominion of Canada purchased Rupert’s Land in 1870.","zh":"加拿大自治領於1870年購買魯珀特地區。"},{"en":"The Dominion of Canada was a historical name for Canada after Confederation.","zh":"加拿大自治領是加拿大聯邦成立後的一個歷史名稱。"},{"en":"History books may use the Dominion of Canada when discussing nineteenth-century policy.","zh":"歷史書討論十九世紀政策時可能使用加拿大自治領。"},{"en":"When the Dominion of Canada bought land, its western expansion became more possible.","zh":"當加拿大自治領購買土地，其西部擴張變得更有可能。"},{"en":"The phrase belongs to Canada’s constitutional and colonial history.","zh":"這個片語屬於加拿大憲制和殖民歷史。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":4},{"front":"purchase land from","meaning":"從……購買土地","examples":[{"en":"The Dominion of Canada purchased land from the Hudson’s Bay Company.","zh":"加拿大自治領從哈德遜灣公司購買土地。"},{"en":"Purchase land from means buy land from a person, company, or government.","zh":"purchase land from 指從個人、公司或政府購買土地。"},{"en":"A developer may purchase land from a private owner to build housing.","zh":"發展商可能從私人業主購買土地來建屋。"},{"en":"If a government purchases land from a company, ownership can change legally.","zh":"如果政府從公司購買土地，擁有權可以合法轉移。"},{"en":"The phrase is more formal than buy land from.","zh":"這個片語比 buy land from 更正式。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":4},{"front":"Rupert’s Land","meaning":"魯珀特地區","examples":[{"en":"The Dominion of Canada purchased Rupert’s Land in 1870.","zh":"加拿大自治領於1870年購買魯珀特地區。"},{"en":"Rupert’s Land was a large historical territory linked to the Hudson’s Bay Company.","zh":"魯珀特地區是一片與哈德遜灣公司有關的大型歷史領土。"},{"en":"Students meet the term Rupert’s Land when studying Canada’s westward expansion.","zh":"學生研究加拿大向西擴張時會遇到魯珀特地區這個詞。"},{"en":"The purchase of Rupert’s Land helped Canada control more western territory.","zh":"購買魯珀特地區幫助加拿大控制更多西部領土。"},{"en":"The phrase names a specific historical region, not ordinary land.","zh":"這個片語指特定歷史地區，而不是普通土地。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":4},{"front":"Hudson’s Bay Company","meaning":"哈德遜灣公司","examples":[{"en":"Canada purchased Rupert’s Land from the Hudson’s Bay Company.","zh":"加拿大從哈德遜灣公司購買魯珀特地區。"},{"en":"The Hudson’s Bay Company was a major trading company connected with northern and western Canada.","zh":"哈德遜灣公司是一間與加拿大北部和西部有關的大型貿易公司。"},{"en":"History lessons often mention the Hudson’s Bay Company when discussing fur trade.","zh":"歷史課討論皮毛貿易時常提到哈德遜灣公司。"},{"en":"When Canada bought land from the Hudson’s Bay Company, political control changed.","zh":"當加拿大從哈德遜灣公司購買土地，政治控制權便改變。"},{"en":"The name refers to an institution, not only a shop or brand.","zh":"這個名稱指一個機構，而不只是商店或品牌。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":4},{"front":"enact an act","meaning":"制定法案","examples":[{"en":"The federal government enacted the Dominion Lands Act in 1872.","zh":"聯邦政府於1872年制定《自治領土地法》。"},{"en":"Enact an act means formally make a law valid.","zh":"enact an act 指正式制定並使一項法律生效。"},{"en":"A parliament may enact an act to protect workers’ rights.","zh":"議會可能制定法案來保障工人權利。"},{"en":"Once leaders enact an act, officials can enforce its rules.","zh":"一旦領導者制定法案，官員就可以執行其規則。"},{"en":"The phrase is legal and formal.","zh":"這個片語屬於法律和正式語境。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":4},{"front":"Dominion Lands Act","meaning":"《自治領土地法》","examples":[{"en":"The Dominion Lands Act enabled settlers to acquire free land.","zh":"《自治領土地法》使定居者能夠取得免費土地。"},{"en":"The Dominion Lands Act was a law that helped settlers obtain land in western Canada.","zh":"《自治領土地法》是一項幫助定居者在加拿大西部取得土地的法律。"},{"en":"A history exam may ask how the Dominion Lands Act encouraged settlement.","zh":"歷史考試可能問《自治領土地法》如何鼓勵定居。"},{"en":"Because of the Dominion Lands Act, settlers could claim land under conditions.","zh":"由於《自治領土地法》，定居者可在符合條件下申請土地。"},{"en":"The phrase names a specific Canadian law.","zh":"這個片語指一項特定加拿大法律。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":4},{"front":"enable settlers to","meaning":"使定居者能夠","examples":[{"en":"The act enabled settlers to acquire 160 acres of free land.","zh":"該法案使定居者能夠取得160英畝免費土地。"},{"en":"Enable settlers to means make it possible for settlers to do something.","zh":"enable settlers to 指使定居者能夠做某事。"},{"en":"New roads can enable settlers to reach remote farms.","zh":"新道路可以使定居者能夠到達偏遠農場。"},{"en":"If laws enable settlers to own land, migration may increase.","zh":"如果法律使定居者能夠擁有土地，移民可能增加。"},{"en":"The phrase focuses on giving ability or opportunity.","zh":"這個片語集中於給予能力或機會。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":4},{"front":"acquire free land","meaning":"取得免費土地","examples":[{"en":"Settlers could acquire free land under the Dominion Lands Act.","zh":"定居者可根據《自治領土地法》取得免費土地。"},{"en":"Acquire free land means obtain land without paying the full purchase price.","zh":"acquire free land 指取得土地而不用支付完整購買價格。"},{"en":"A family may acquire free land if a settlement programme offers it.","zh":"如果定居計劃提供土地，家庭可能取得免費土地。"},{"en":"If people can acquire free land, they may be more willing to move.","zh":"如果人們能取得免費土地，他們可能更願意遷移。"},{"en":"The phrase still may involve conditions, fees, or required work.","zh":"這個片語仍可能涉及條件、費用或指定工作。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":4},{"front":"as long as","meaning":"只要","examples":[{"en":"Settlers could acquire land as long as they met certain conditions.","zh":"只要定居者符合某些條件，就可以取得土地。"},{"en":"As long as means provided that or if a condition is satisfied.","zh":"as long as 指只要某條件得到滿足。"},{"en":"You may borrow my laptop as long as you return it tonight.","zh":"只要你今晚歸還，就可以借我的手提電腦。"},{"en":"Students can join the trip as long as they bring permission forms.","zh":"只要學生帶同意書，就可以參加旅行。"},{"en":"The phrase introduces a requirement that must be met.","zh":"這個片語引出必須符合的要求。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":4},{"front":"remain on their land","meaning":"留在自己的土地上","examples":[{"en":"Settlers had to remain on their land for three years.","zh":"定居者必須留在自己的土地上三年。"},{"en":"Remain on their land means continue living or staying on the land they received.","zh":"remain on their land 指繼續居住或停留在他們取得的土地上。"},{"en":"Farmers may remain on their land during harvest season because work is constant.","zh":"農民可能在收成季節留在自己的土地上，因為工作不斷。"},{"en":"If settlers did not remain on their land, they might lose their claim.","zh":"如果定居者不留在自己的土地上，他們可能失去申請權。"},{"en":"The phrase suggests physical presence and commitment.","zh":"這個片語暗示實際居住和承諾。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":4},{"front":"for a period of","meaning":"為期","examples":[{"en":"Settlers had to remain on the land for a period of three years.","zh":"定居者必須留在土地上，為期三年。"},{"en":"For a period of means lasting for a particular amount of time.","zh":"for a period of 指持續某一段特定時間。"},{"en":"The library closed for a period of two weeks for repairs.","zh":"圖書館因維修關閉，為期兩星期。"},{"en":"If a worker trains for a period of six months, skills may improve steadily.","zh":"如果工人接受為期六個月的訓練，技能可能穩步提升。"},{"en":"The phrase is more formal than for.","zh":"這個片語比 for 更正式。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":5},{"front":"make minor improvements to","meaning":"對……作出小規模改善","examples":[{"en":"Settlers had to make minor improvements to the land.","zh":"定居者必須對土地作出小規模改善。"},{"en":"Make minor improvements to means make small changes that make something better.","zh":"make minor improvements to 指作出小改動，使某物變得更好。"},{"en":"A tenant may make minor improvements to a room by painting the walls.","zh":"租客可能透過粉刷牆壁對房間作出小規模改善。"},{"en":"Minor improvements to a farm can make the land easier to use.","zh":"對農場作出小規模改善可以令土地更易使用。"},{"en":"The phrase suggests small repairs or upgrades, not complete rebuilding.","zh":"這個片語暗示小型修補或升級，而不是完全重建。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":5},{"front":"registration fee","meaning":"登記費","examples":[{"en":"Settlers had to pay a registration fee of ten dollars.","zh":"定居者必須支付十美元登記費。"},{"en":"A registration fee is money paid to officially sign up or record something.","zh":"登記費是為正式報名或記錄某事而支付的金錢。"},{"en":"Students may pay a registration fee before joining an exam.","zh":"學生參加考試前可能要支付登記費。"},{"en":"If a registration fee is low, more people may apply.","zh":"如果登記費較低，更多人可能會申請。"},{"en":"The fee usually covers administration, not the full cost of the service.","zh":"這項費用通常支付行政成本，而不是服務全部成本。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":5},{"front":"Mounted Police Force","meaning":"騎警部隊","examples":[{"en":"The Canadian government created a Mounted Police Force in 1873.","zh":"加拿大政府於1873年成立騎警部隊。"},{"en":"A Mounted Police Force is a police group originally associated with riding horses.","zh":"騎警部隊是原本與騎馬執勤有關的警察隊伍。"},{"en":"A mounted police unit can patrol large open areas more easily than foot officers.","zh":"騎警隊伍比步行警員更容易巡邏廣闊開放地區。"},{"en":"Creating a Mounted Police Force can help a government control distant territory.","zh":"成立騎警部隊可以幫助政府控制遙遠領土。"},{"en":"The phrase sounds historical when used in the Canadian West.","zh":"這個片語用於加拿大西部時帶有歷史意味。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":5},{"front":"the Mounties","meaning":"加拿大騎警","examples":[{"en":"The Mounties journeyed west to secure the area for settlers.","zh":"加拿大騎警向西行進，為定居者保護該地區。"},{"en":"The Mounties is an informal name for Canada’s mounted police.","zh":"the Mounties 是加拿大騎警的非正式名稱。"},{"en":"In Canadian history, the Mounties are often linked with law and order in the West.","zh":"在加拿大歷史中，加拿大騎警常與西部的法律和秩序有關。"},{"en":"If the Mounties established posts, settlers might feel the region was safer.","zh":"如果加拿大騎警建立駐地，定居者可能覺得該地區更安全。"},{"en":"The word is shorter and more familiar than Mounted Police Force.","zh":"這個詞比 Mounted Police Force 更短，也更親切。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":5},{"front":"journey west","meaning":"向西行進","examples":[{"en":"The Mounties journeyed west to secure the area.","zh":"加拿大騎警向西行進以保護該地區。"},{"en":"Journey west means travel towards the western region.","zh":"journey west 指向西部地區旅行或前進。"},{"en":"A family may journey west by train to start a new life.","zh":"一個家庭可能乘火車向西行進，開始新生活。"},{"en":"If officials journey west, they can inspect land and build posts.","zh":"如果官員向西行進，他們可以勘察土地並建立駐地。"},{"en":"The phrase suggests a long trip, not a short walk.","zh":"這個片語暗示長途旅程，而不是短距離步行。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":5},{"front":"secure the area for","meaning":"為……保護該地區","examples":[{"en":"The Mounties secured the area for future settlers.","zh":"加拿大騎警為未來定居者保護該地區。"},{"en":"Secure the area for means make a place safe or controlled for a particular group or purpose.","zh":"secure the area for 指為某群體或目的使某地安全或受控制。"},{"en":"Police may secure the area for firefighters after an accident.","zh":"意外後，警察可能為消防員保護該地區。"},{"en":"If a site is secured for construction, workers can begin safely.","zh":"如果工地為施工而得到保護，工人便可安全開始。"},{"en":"The phrase connects protection with a future use.","zh":"這個片語把保護與未來用途連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":5},{"front":"future settlers","meaning":"未來定居者","examples":[{"en":"The Mounties prepared the West for future settlers.","zh":"加拿大騎警為未來定居者準備西部。"},{"en":"Future settlers are people expected to move and live in a place later.","zh":"未來定居者是預期之後會遷往並居住在某地的人。"},{"en":"Roads and wells may be built before future settlers arrive.","zh":"道路和水井可能在未來定居者到達前建成。"},{"en":"If land is made safer, future settlers may be more willing to move there.","zh":"如果土地變得更安全，未來定居者可能更願意搬去。"},{"en":"The phrase looks forward to people who have not yet arrived.","zh":"這個片語指向尚未到達的人。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":5},{"front":"establish itself in","meaning":"在……站穩陣腳","examples":[{"en":"By 1876, the NWMP had established itself in the West.","zh":"到1876年，西北騎警已在西部站穩陣腳。"},{"en":"Establish itself in means become settled, recognised, and active in a place.","zh":"establish itself in 指在某地穩定存在、獲承認並開始運作。"},{"en":"A new company may establish itself in a city by opening offices and hiring staff.","zh":"一間新公司可能透過開設辦公室和聘請員工在城市站穩陣腳。"},{"en":"Once a school establishes itself in a community, families begin to trust it.","zh":"一所學校在社區站穩陣腳後，家庭便開始信任它。"},{"en":"The phrase suggests gaining a stable presence.","zh":"這個片語暗示取得穩定存在。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":5},{"front":"major posts","meaning":"主要駐地","examples":[{"en":"The major posts included Fort Calgary and Fort Walsh.","zh":"主要駐地包括卡加利堡和沃爾什堡。"},{"en":"Major posts are important stations, bases, or locations used by an organisation.","zh":"主要駐地是組織使用的重要站點、基地或地點。"},{"en":"A police force may create major posts along important roads.","zh":"警隊可能沿重要道路建立主要駐地。"},{"en":"If major posts are well placed, officers can respond more quickly.","zh":"如果主要駐地位置合適，警員可以更快回應。"},{"en":"The phrase often appears in military, police, or administrative contexts.","zh":"這個片語常見於軍事、警務或行政語境。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":5},{"front":"initiatives","meaning":"措施；倡議","examples":[{"en":"These initiatives attracted settlers and immigrants to Canada’s West.","zh":"這些措施吸引定居者和移民到加拿大西部。"},{"en":"Initiatives are planned actions or programmes started to achieve a goal.","zh":"initiatives 是為達成目標而開始的計劃行動或方案。"},{"en":"A school may launch initiatives to help new students feel welcome.","zh":"學校可能推出措施，幫助新生感到受歡迎。"},{"en":"Government initiatives can change behaviour if people trust them.","zh":"如果人們信任政府措施，它們可以改變行為。"},{"en":"The word suggests active effort, not passive waiting.","zh":"這個詞暗示主動努力，而不是被動等待。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":6},{"front":"attract a number of","meaning":"吸引若干……","examples":[{"en":"The initiatives attracted a number of settlers to the West.","zh":"這些措施吸引若干定居者到西部。"},{"en":"Attract a number of means bring in several or many people or things.","zh":"attract a number of 指吸引一些或許多人或事物。"},{"en":"A new park may attract a number of families on weekends.","zh":"新公園可能在週末吸引若干家庭。"},{"en":"If land is cheap, it may attract a number of young farmers.","zh":"如果土地便宜，它可能吸引若干年輕農民。"},{"en":"The phrase is useful when the exact number is not given.","zh":"當沒有給出確切數字時，這個片語很有用。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":6},{"front":"eastern-Canadian settlers","meaning":"加拿大東部定居者","examples":[{"en":"Eastern-Canadian settlers moved to the West.","zh":"加拿大東部定居者遷往西部。"},{"en":"Eastern-Canadian settlers are people from eastern Canada who move to settle elsewhere.","zh":"加拿大東部定居者是從加拿大東部遷往其他地方定居的人。"},{"en":"Eastern-Canadian settlers may bring their language, religion, and farming habits with them.","zh":"加拿大東部定居者可能帶來自己的語言、宗教和農業習慣。"},{"en":"If many eastern-Canadian settlers arrive, local culture may change.","zh":"如果許多加拿大東部定居者到來，本地文化可能改變。"},{"en":"The phrase identifies settlers by their Canadian regional origin.","zh":"這個片語以加拿大地區來源識別定居者。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":6},{"front":"European and American immigrants","meaning":"歐洲和美國移民","examples":[{"en":"European and American immigrants were attracted to Canada’s West.","zh":"歐洲和美國移民被吸引到加拿大西部。"},{"en":"European and American immigrants are people from Europe and the United States who move to another country.","zh":"歐洲和美國移民是從歐洲和美國遷往另一國的人。"},{"en":"European and American immigrants may arrive with different farming skills and expectations.","zh":"歐洲和美國移民可能帶着不同農業技能和期望到來。"},{"en":"If European and American immigrants settle together, communities may become more diverse.","zh":"如果歐洲和美國移民一起定居，社區可能變得更多元。"},{"en":"The phrase groups immigrants by broad origin.","zh":"這個片語按廣泛來源把移民歸類。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":6},{"front":"Canada’s West","meaning":"加拿大西部","examples":[{"en":"Many settlers moved to Canada’s West.","zh":"許多定居者遷往加拿大西部。"},{"en":"Canada’s West refers to the western regions of Canada.","zh":"Canada’s West 指加拿大的西部地區。"},{"en":"Canada’s West attracted farmers because land appeared more available.","zh":"加拿大西部吸引農民，因為土地似乎較容易取得。"},{"en":"Railways helped connect Canada’s West with eastern markets.","zh":"鐵路幫助把加拿大西部與東部市場連接起來。"},{"en":"The phrase is geographical but also historical in this passage.","zh":"在本文中，這個片語既有地理也有歷史意味。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":6},{"front":"particularly to","meaning":"尤其到","examples":[{"en":"Many immigrants moved particularly to the area of Manitoba.","zh":"許多移民尤其遷往曼尼托巴一帶。"},{"en":"Particularly to means especially towards one place, group, or target.","zh":"particularly to 指尤其朝向某一地方、群體或目標。"},{"en":"Students were sent particularly to classrooms that had extra space.","zh":"學生尤其被安排到有額外空間的課室。"},{"en":"If migrants move particularly to one city, that city may grow quickly.","zh":"如果移民尤其遷往一個城市，該城市可能迅速增長。"},{"en":"The phrase narrows a general movement to a specific destination.","zh":"這個片語把一般移動收窄到特定目的地。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":6},{"front":"the area of Manitoba","meaning":"曼尼托巴一帶","examples":[{"en":"Many immigrants settled in the area of Manitoba.","zh":"許多移民在曼尼托巴一帶定居。"},{"en":"The area of Manitoba means the region in and around Manitoba.","zh":"the area of Manitoba 指曼尼托巴及其周邊地區。"},{"en":"Farmers in the area of Manitoba could use prairie land for crops.","zh":"曼尼托巴一帶的農民可以使用草原土地種植作物。"},{"en":"If settlers gather in the area of Manitoba, towns and services may grow.","zh":"如果定居者聚集在曼尼托巴一帶，城鎮和服務可能增長。"},{"en":"The phrase points to a regional location rather than one exact town.","zh":"這個片語指一個地區位置，而不是某個確切城鎮。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":6},{"front":"the surest way to","meaning":"最可靠的方法去","examples":[{"en":"The surest way to protect Canadian territory was to import settlers.","zh":"保護加拿大領土最可靠的方法是引入定居者。"},{"en":"The surest way to means the most reliable method for achieving something.","zh":"the surest way to 指達成某事最可靠的方法。"},{"en":"The surest way to improve spelling is regular practice and correction.","zh":"改善串字最可靠的方法是定期練習和改正。"},{"en":"If a town wants cleaner streets, the surest way to start is better waste collection.","zh":"如果城鎮想街道更清潔，最可靠的開始方法是改善垃圾收集。"},{"en":"The phrase expresses strong confidence in one method.","zh":"這個片語表達對某一方法的強烈信心。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":6},{"front":"protect Canadian territory","meaning":"保護加拿大領土","examples":[{"en":"The government wanted to protect Canadian territory.","zh":"政府希望保護加拿大領土。"},{"en":"Protect Canadian territory means defend land claimed or controlled by Canada.","zh":"protect Canadian territory 指保衛加拿大聲稱或控制的土地。"},{"en":"A country may protect its territory by building roads, posts, and settlements.","zh":"一個國家可能透過建路、設駐地和定居來保護領土。"},{"en":"If territory is not protected, another power may try to control it.","zh":"如果領土沒有受到保護，另一個勢力可能試圖控制它。"},{"en":"The phrase links land, sovereignty, and security.","zh":"這個片語把土地、主權和安全連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":6},{"front":"secondary goal","meaning":"次要目標","examples":[{"en":"The secondary goal was to join British Columbia to the rest of the country.","zh":"次要目標是把卑詩省連接到國家其他地方。"},{"en":"A secondary goal is an important but less central aim.","zh":"secondary goal 是重要但較非核心的目標。"},{"en":"A student’s main goal may be passing the exam, with confidence as a secondary goal.","zh":"學生的主要目標可能是通過考試，而信心是次要目標。"},{"en":"If a project has a secondary goal, it may still influence planning.","zh":"如果項目有次要目標，它仍可能影響規劃。"},{"en":"The phrase contrasts with the main goal.","zh":"這個片語與主要目標形成對比。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":6},{"front":"join something to","meaning":"把……連接到","examples":[{"en":"The railway would join British Columbia to the rest of the country.","zh":"鐵路會把卑詩省連接到國家其他地方。"},{"en":"Join something to means connect one thing or place with another.","zh":"join something to 指把一物或一地與另一物或另一地連接起來。"},{"en":"A bridge can join an island to the mainland.","zh":"橋可以把島嶼連接到大陸。"},{"en":"If a railway joins two regions, people and goods can move more easily.","zh":"如果鐵路把兩個地區連接起來，人和貨物可更容易流動。"},{"en":"The phrase suggests physical or functional connection.","zh":"這個片語暗示實體或功能上的連接。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":7},{"front":"British Columbia","meaning":"卑詩省","examples":[{"en":"British Columbia needed to be connected to the rest of Canada.","zh":"卑詩省需要與加拿大其他地方連接。"},{"en":"British Columbia is a province on Canada’s western coast.","zh":"卑詩省是加拿大西岸的一個省份。"},{"en":"British Columbia’s distance from eastern Canada made transport links important.","zh":"卑詩省與加拿大東部距離遠，因此交通連接很重要。"},{"en":"If British Columbia is connected by railway, trade and travel become easier.","zh":"如果卑詩省透過鐵路連接，貿易和旅行會更容易。"},{"en":"The phrase names a specific Canadian province.","zh":"這個片語指加拿大一個特定省份。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":7},{"front":"the rest of the country","meaning":"國家其他地方","examples":[{"en":"The railway connected British Columbia to the rest of the country.","zh":"鐵路把卑詩省連接到國家其他地方。"},{"en":"The rest of the country means all other parts of the country apart from the place mentioned.","zh":"the rest of the country 指除已提及地方以外的所有國內地區。"},{"en":"A storm may cut one town off from the rest of the country.","zh":"風暴可能令一個城鎮與國家其他地方隔絕。"},{"en":"If a region is linked to the rest of the country, goods can move more easily.","zh":"如果某地區與國家其他地方連接，貨物可以更容易流動。"},{"en":"The phrase depends on which place has already been named.","zh":"這個片語取決於前面已提到哪個地方。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":7},{"front":"import large numbers of","meaning":"引入大量……","examples":[{"en":"Canada wanted to import large numbers of Eastern Canadian and British settlers.","zh":"加拿大希望引入大量加拿大東部和英國定居者。"},{"en":"Import large numbers of means bring in many people or goods from elsewhere.","zh":"import large numbers of 指從其他地方引入大量人或貨物。"},{"en":"A country may import large numbers of workers during a labour shortage.","zh":"一個國家在勞工短缺時可能引入大量工人。"},{"en":"If a city imports large numbers of materials, construction can speed up.","zh":"如果城市引入大量材料，建設可以加快。"},{"en":"With people, the phrase sounds policy-focused and historical.","zh":"用於人時，這個片語帶有政策和歷史語氣。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":7},{"front":"British settlers","meaning":"英國定居者","examples":[{"en":"British settlers were encouraged to move to western Canada.","zh":"英國定居者被鼓勵遷往加拿大西部。"},{"en":"British settlers are people from Britain who move to a new place to live permanently.","zh":"英國定居者是從英國遷往新地方永久居住的人。"},{"en":"British settlers may bring language, laws, churches, and customs with them.","zh":"英國定居者可能帶來語言、法律、教會和習俗。"},{"en":"If British settlers dominate a town, local institutions may reflect British culture.","zh":"如果英國定居者支配一個城鎮，本地制度可能反映英國文化。"},{"en":"The phrase identifies settlers by origin.","zh":"這個片語按來源識別定居者。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":7},{"front":"settling the West","meaning":"開拓西部定居","examples":[{"en":"Settling the West made a transcontinental railway necessary.","zh":"開拓西部定居令橫貫大陸鐵路變得必要。"},{"en":"Settling the West means establishing communities and farms in western regions.","zh":"settling the West 指在西部地區建立社區和農場。"},{"en":"Settling the West required transport, land laws, and protection.","zh":"開拓西部定居需要交通、土地法律和保護。"},{"en":"If many families were settling the West, supplies had to reach them.","zh":"如果許多家庭正在西部定居，物資就必須送達他們。"},{"en":"The phrase describes a long process, not one single journey.","zh":"這個片語描述長期過程，而不是一次旅程。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":7},{"front":"make something imperative","meaning":"令……變得必要","examples":[{"en":"Settling the West made the railway imperative.","zh":"開拓西部定居令鐵路變得必要。"},{"en":"Make something imperative means make it urgently necessary.","zh":"make something imperative 指令某事變得緊急必要。"},{"en":"Heavy flooding can make quick evacuation imperative.","zh":"嚴重水浸可以令迅速疏散變得必要。"},{"en":"If students are far behind, extra lessons may become imperative.","zh":"如果學生嚴重落後，額外課堂可能變得必要。"},{"en":"The phrase is stronger than make something useful.","zh":"這個片語比令某事有用更強。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":7},{"front":"transcontinental railway","meaning":"橫貫大陸鐵路","examples":[{"en":"A transcontinental railway was needed to connect West and East.","zh":"需要一條橫貫大陸鐵路來連接西部和東部。"},{"en":"A transcontinental railway is a railway that crosses a continent.","zh":"橫貫大陸鐵路是橫跨一個大陸的鐵路。"},{"en":"A transcontinental railway can carry passengers and goods across huge distances.","zh":"橫貫大陸鐵路可以運送乘客和貨物跨越巨大距離。"},{"en":"If a country builds a transcontinental railway, remote regions may develop faster.","zh":"如果一個國家興建橫貫大陸鐵路，偏遠地區可能發展更快。"},{"en":"The phrase suggests national-scale transport.","zh":"這個片語暗示全國規模的交通。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":7},{"front":"work to create","meaning":"有助創造","examples":[{"en":"The railway would work to create an east-west economy.","zh":"鐵路有助創造東西向經濟體系。"},{"en":"Work to create means help bring something into existence.","zh":"work to create 指幫助某物形成或出現。"},{"en":"Clear rules can work to create a safer classroom.","zh":"清晰規則有助創造更安全的課室。"},{"en":"If roads connect farms and cities, they work to create stronger trade.","zh":"如果道路連接農場和城市，它們有助創造更強貿易。"},{"en":"The phrase shows a practical effect over time.","zh":"這個片語顯示隨時間產生的實際效果。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":7},{"front":"east-west economy","meaning":"東西向經濟體系","examples":[{"en":"The railway helped create an east-west economy.","zh":"鐵路幫助創造東西向經濟體系。"},{"en":"An east-west economy is a system of trade linking eastern and western regions.","zh":"東西向經濟體系是連接東部和西部地區的貿易系統。"},{"en":"Farms in the west may sell grain to cities in the east in an east-west economy.","zh":"在東西向經濟體系中，西部農場可能向東部城市出售穀物。"},{"en":"Railways can strengthen an east-west economy by moving goods both ways.","zh":"鐵路可以透過雙向運貨強化東西向經濟體系。"},{"en":"The phrase highlights direction and regional connection.","zh":"這個片語強調方向和地區連接。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":7},{"front":"feed the growing population","meaning":"供養日益增長的人口","examples":[{"en":"Western Canada would feed the growing urban industrial population of the east.","zh":"加拿大西部會供養東部日益增長的城市工業人口。"},{"en":"Feed the growing population means provide food for an increasing number of people.","zh":"feed the growing population 指為不斷增加的人口提供食物。"},{"en":"Local farms help feed the growing population of a city.","zh":"本地農場幫助供養城市日益增長的人口。"},{"en":"If population rises faster than food supply, feeding the growing population becomes harder.","zh":"如果人口增長快過食物供應，供養日益增長的人口就更困難。"},{"en":"The phrase links agriculture with demographic change.","zh":"這個片語把農業與人口變化連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":8},{"front":"urban industrial population","meaning":"城市工業人口","examples":[{"en":"Eastern Canada had a growing urban industrial population.","zh":"加拿大東部有不斷增長的城市工業人口。"},{"en":"An urban industrial population is a city-based population working mainly in industry and related services.","zh":"城市工業人口是以城市為基地、主要從事工業和相關服務的人口。"},{"en":"Factory towns often have an urban industrial population.","zh":"工廠城鎮通常有城市工業人口。"},{"en":"As an urban industrial population grows, demand for food and housing rises.","zh":"當城市工業人口增長，食物和住房需求會上升。"},{"en":"The phrase combines place, work, and social change.","zh":"這個片語結合地點、工作和社會變化。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":8},{"front":"in return","meaning":"作為回報；反過來","examples":[{"en":"Western Canada would become a market for eastern goods in return.","zh":"作為回報，加拿大西部會成為東部貨品的市場。"},{"en":"In return means as something given back or exchanged.","zh":"in return 指作為回報或交換。"},{"en":"I helped my neighbour carry boxes; in return, she watered my plants.","zh":"我幫鄰居搬箱子；作為回報，她幫我澆植物。"},{"en":"If the west supplied food, the east could send goods in return.","zh":"如果西部供應食物，東部可以反過來送出貨品。"},{"en":"The phrase shows two-way benefit or exchange.","zh":"這個片語顯示雙向好處或交換。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":8},{"front":"manufactured goods","meaning":"製成品","examples":[{"en":"Western Canada became a market for eastern Canadian manufactured goods.","zh":"加拿大西部成為加拿大東部製成品的市場。"},{"en":"Manufactured goods are products made in factories or workshops.","zh":"製成品是在工廠或工場製造的產品。"},{"en":"Clothes, tools, furniture, and machines are manufactured goods.","zh":"衣服、工具、家具和機器都是製成品。"},{"en":"If farms need equipment, demand for manufactured goods may rise.","zh":"如果農場需要設備，對製成品的需求可能上升。"},{"en":"The phrase contrasts with raw materials or farm produce.","zh":"這個片語與原材料或農產品形成對比。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":8},{"front":"metropolis of the West","meaning":"西部大都市","examples":[{"en":"Winnipeg became the metropolis of the West.","zh":"溫尼伯成為西部大都市。"},{"en":"Metropolis of the West means the major city or central urban hub of the western region.","zh":"metropolis of the West 指西部地區的主要城市或城市中心。"},{"en":"A city with railways, banks, factories, and markets may become a regional metropolis.","zh":"擁有鐵路、銀行、工廠和市場的城市可能成為地區大都市。"},{"en":"If many workers and traders gather there, a town can grow into a metropolis.","zh":"如果許多工人和商人聚集，一個城鎮可以發展成大都市。"},{"en":"The phrase gives Winnipeg a leading urban role.","zh":"這個片語賦予溫尼伯領先城市角色。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":8},{"front":"during this period","meaning":"在這段期間","examples":[{"en":"Winnipeg became the metropolis of the West during this period.","zh":"溫尼伯在這段期間成為西部大都市。"},{"en":"During this period means within the time being discussed.","zh":"during this period 指在正在討論的時間內。"},{"en":"During this period, many families moved from farms to cities.","zh":"在這段期間，許多家庭從農場遷往城市。"},{"en":"If prices rose during this period, workers may have struggled more.","zh":"如果物價在這段期間上升，工人可能更吃力。"},{"en":"The phrase depends on the historical time already mentioned.","zh":"這個片語取決於前文已提及的歷史時間。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":8},{"front":"growth before 1900","meaning":"1900年前的增長","examples":[{"en":"Winnipeg’s growth before 1900 was linked to railways and land speculation.","zh":"溫尼伯1900年前的增長與鐵路和土地投機有關。"},{"en":"Growth before 1900 means development that happened earlier than the year 1900.","zh":"growth before 1900 指1900年以前發生的發展。"},{"en":"A city’s growth before 1900 may be shown by maps and census records.","zh":"城市1900年前的增長可由地圖和人口普查記錄顯示。"},{"en":"If railway jobs increased, growth before 1900 could become faster.","zh":"如果鐵路工作增加，1900年前的增長可能加快。"},{"en":"The phrase places urban expansion in a specific historical frame.","zh":"這個片語把城市擴張放在特定歷史框架中。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":8},{"front":"a combination of","meaning":"……的結合","examples":[{"en":"Winnipeg’s growth was the result of a combination of several factors.","zh":"溫尼伯的增長是幾個因素結合的結果。"},{"en":"A combination of means two or more things working together.","zh":"a combination of 指兩個或以上事物共同作用。"},{"en":"Good exam results usually come from a combination of practice, sleep, and feedback.","zh":"好考試成績通常來自練習、睡眠和回饋的結合。"},{"en":"A combination of cheap land and transport can attract settlers.","zh":"廉價土地和交通的結合可以吸引定居者。"},{"en":"The phrase suggests that one cause alone is not enough.","zh":"這個片語暗示單一原因並不足夠。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":8},{"front":"land speculation","meaning":"土地投機","examples":[{"en":"Land speculation contributed to Winnipeg’s growth.","zh":"土地投機促成溫尼伯的增長。"},{"en":"Land speculation means buying land hoping its price will rise later.","zh":"土地投機指購買土地並希望其價格日後上升。"},{"en":"Investors may engage in land speculation near a planned railway station.","zh":"投資者可能在計劃中的鐵路站附近進行土地投機。"},{"en":"If land speculation spreads, prices can rise before real development happens.","zh":"如果土地投機擴散，價格可能在真正發展前上升。"},{"en":"The phrase often suggests risk and profit-seeking.","zh":"這個片語常暗示風險和逐利。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":8},{"front":"housing starts","meaning":"新屋動工量","examples":[{"en":"The growth of housing starts helped Winnipeg expand.","zh":"新屋動工量的增長幫助溫尼伯擴展。"},{"en":"Housing starts are new housing construction projects that have begun.","zh":"新屋動工量是已開始的新住房建設項目數量。"},{"en":"A rise in housing starts can show that more people need homes.","zh":"新屋動工量上升可以顯示更多人需要住房。"},{"en":"If housing starts increase, construction jobs may also increase.","zh":"如果新屋動工量增加，建築工作也可能增加。"},{"en":"The phrase is often used in economic reports.","zh":"這個片語常用於經濟報告。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":8},{"front":"selection of","meaning":"對……的選定","examples":[{"en":"The federal government’s selection of Winnipeg as a major stop changed the city.","zh":"聯邦政府選定溫尼伯為主要站點，改變了這座城市。"},{"en":"Selection of means the act of choosing someone or something for a role.","zh":"selection of 指選擇某人或某物擔任某角色的行為。"},{"en":"The selection of a school captain may depend on leadership and trust.","zh":"對學生領袖的選定可能取決於領導力和信任。"},{"en":"If the selection of a site is poor, a project may fail.","zh":"如果對地點的選定不佳，項目可能失敗。"},{"en":"The phrase focuses on a choice and its importance.","zh":"這個片語集中於選擇及其重要性。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":9},{"front":"a major stop along","meaning":"……沿線的主要站點","examples":[{"en":"Winnipeg became a major stop along the CPR.","zh":"溫尼伯成為加拿大太平洋鐵路沿線的主要站點。"},{"en":"A major stop along a route is an important place where travellers or goods pause.","zh":"a major stop along 指某路線上乘客或貨物停留的重要地點。"},{"en":"A station near a university may become a major stop along a bus route.","zh":"大學附近的車站可能成為巴士路線沿線的主要站點。"},{"en":"If a town becomes a major stop along a railway, trade may grow.","zh":"如果城鎮成為鐵路沿線的主要站點，貿易可能增長。"},{"en":"The phrase connects a place with a transport line.","zh":"這個片語把地點與交通線連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":9},{"front":"the CPR","meaning":"加拿大太平洋鐵路","examples":[{"en":"Winnipeg became a major stop along the CPR.","zh":"溫尼伯成為加拿大太平洋鐵路沿線的主要站點。"},{"en":"The CPR refers to the Canadian Pacific Railway.","zh":"the CPR 指加拿大太平洋鐵路。"},{"en":"The CPR helped connect western and eastern Canada by rail.","zh":"加拿大太平洋鐵路幫助以鐵路連接加拿大西部和東部。"},{"en":"If a town was located along the CPR, it could attract workers and businesses.","zh":"如果城鎮位於加拿大太平洋鐵路沿線，它可能吸引工人和企業。"},{"en":"The abbreviation is important in Canadian railway history.","zh":"這個縮寫在加拿大鐵路史中很重要。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":9},{"front":"culminate in","meaning":"最終導致","examples":[{"en":"The government’s decision culminated in a land boom.","zh":"政府的決定最終導致土地熱潮。"},{"en":"Culminate in means finally result in an important event or outcome.","zh":"culminate in 指最終導致重要事件或結果。"},{"en":"Months of training can culminate in a final performance.","zh":"數月訓練可以最終導致一場最終表演。"},{"en":"If prices keep rising, speculation may culminate in a crash.","zh":"如果價格持續上升，投機可能最終導致崩盤。"},{"en":"The phrase shows the endpoint of a process.","zh":"這個片語顯示一個過程的終點。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":9},{"front":"land boom","meaning":"土地熱潮","examples":[{"en":"A land boom occurred between 1881 and 1883.","zh":"1881年至1883年間出現土地熱潮。"},{"en":"A land boom is a rapid rise in land buying, selling, and prices.","zh":"土地熱潮是土地買賣和價格迅速上升的情況。"},{"en":"A planned railway can trigger a land boom near new stations.","zh":"計劃中的鐵路可以在新車站附近引發土地熱潮。"},{"en":"During a land boom, people may buy land quickly hoping to profit.","zh":"在土地熱潮期間，人們可能迅速買地，希望獲利。"},{"en":"The phrase suggests excitement but also possible risk.","zh":"這個片語暗示興奮，也可能暗示風險。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":9},{"front":"result in the transformation of","meaning":"導致……轉變為","examples":[{"en":"The land boom resulted in the transformation of hamlets into towns.","zh":"土地熱潮導致小村落轉變為城鎮。"},{"en":"Result in the transformation of means cause something to change greatly into another form.","zh":"result in the transformation of 指造成某物大幅轉變成另一種形式。"},{"en":"New transport can result in the transformation of a village into a busy suburb.","zh":"新交通可以導致村莊轉變為繁忙郊區。"},{"en":"If tourism grows, it may result in the transformation of old streets into shopping areas.","zh":"如果旅遊業增長，它可能導致舊街道轉變為購物區。"},{"en":"The phrase highlights a major change caused by something.","zh":"這個片語強調由某事造成的重大變化。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":9},{"front":"hamlets","meaning":"小村落","examples":[{"en":"Small hamlets like Brandon grew into towns.","zh":"像布蘭登這樣的小村落成長為城鎮。"},{"en":"Hamlets are very small settlements, usually smaller than villages.","zh":"hamlets 是非常小的定居點，通常比村莊更小。"},{"en":"A hamlet may have only a few houses and no major shops.","zh":"小村落可能只有幾間房屋，沒有大型商店。"},{"en":"If a railway passes nearby, hamlets can grow into larger communities.","zh":"如果鐵路經過附近，小村落可以發展成較大社區。"},{"en":"The word suggests a small rural place.","zh":"這個詞暗示一個細小鄉郊地方。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":9},{"front":"a large increase in","meaning":"……的大幅增加","examples":[{"en":"The land boom caused a large increase in Manitoba’s population.","zh":"土地熱潮導致曼尼托巴人口大幅增加。"},{"en":"A large increase in means a big rise in amount, number, or level.","zh":"a large increase in 指數量、數目或水平的大幅上升。"},{"en":"A large increase in rent can make life difficult for families.","zh":"租金大幅增加可以令家庭生活困難。"},{"en":"If there is a large increase in students, a school may need more classrooms.","zh":"如果學生人數大幅增加，學校可能需要更多課室。"},{"en":"The phrase emphasises scale, not just growth.","zh":"這個片語強調幅度，而不只是增長。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":9},{"front":"stand at the junction of","meaning":"位於……的交匯處","examples":[{"en":"Winnipeg stood at the junction of three railway lines.","zh":"溫尼伯位於三條鐵路線的交匯處。"},{"en":"Stand at the junction of means be located where routes meet.","zh":"stand at the junction of 指位於多條路線相交的地方。"},{"en":"A shop at the junction of two busy streets can attract many customers.","zh":"位於兩條繁忙街道交匯處的商店可以吸引許多顧客。"},{"en":"If a town stands at the junction of railways, transport activity may grow.","zh":"如果城鎮位於鐵路交匯處，交通活動可能增長。"},{"en":"The phrase describes a strategic location.","zh":"這個片語描述戰略位置。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":9},{"front":"railway lines","meaning":"鐵路線","examples":[{"en":"Winnipeg stood at the junction of three transcontinental railway lines.","zh":"溫尼伯位於三條橫貫大陸鐵路線的交匯處。"},{"en":"Railway lines are tracks and routes used by trains.","zh":"鐵路線是火車使用的軌道和路線。"},{"en":"New railway lines can connect farms with ports and cities.","zh":"新鐵路線可以把農場與港口和城市連接起來。"},{"en":"If railway lines cross in one city, trade and employment may increase there.","zh":"如果鐵路線在一個城市交匯，那裡的貿易和就業可能增加。"},{"en":"The phrase refers to transport infrastructure.","zh":"這個片語指交通基礎設施。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":9},{"front":"employ thousands","meaning":"僱用數以千計的人","examples":[{"en":"The railway lines employed thousands in rail yards.","zh":"鐵路線在鐵路貨場僱用數以千計的人。"},{"en":"Employ thousands means provide jobs for many thousands of people.","zh":"employ thousands 指為數以千計的人提供工作。"},{"en":"A large hospital may employ thousands of nurses, doctors, and cleaners.","zh":"大型醫院可能僱用數以千計的護士、醫生和清潔工。"},{"en":"If a factory employs thousands, closing it can hurt the local economy.","zh":"如果工廠僱用數以千計的人，關閉它會傷害本地經濟。"},{"en":"The phrase shows the employment scale of an industry.","zh":"這個片語顯示某行業的就業規模。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":10},{"front":"rail yards","meaning":"鐵路調車場；鐵路貨場","examples":[{"en":"Thousands of workers were employed in rail yards.","zh":"數以千計的工人在鐵路調車場工作。"},{"en":"Rail yards are areas where trains are stored, repaired, loaded, or organised.","zh":"鐵路調車場是火車停放、維修、裝貨或調度的地方。"},{"en":"Workers in rail yards may move cargo and maintain train cars.","zh":"鐵路貨場的工人可能搬運貨物和維修車廂。"},{"en":"If rail yards expand, nearby neighbourhoods may gain jobs but also noise.","zh":"如果鐵路貨場擴張，附近社區可能增加工作但也有噪音。"},{"en":"The phrase refers to working spaces within a railway system.","zh":"這個片語指鐵路系統內的工作空間。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":10},{"front":"major processor of","meaning":"……的主要加工中心","examples":[{"en":"Winnipeg became the major processor of agricultural products.","zh":"溫尼伯成為農產品的主要加工中心。"},{"en":"Major processor of means the main place or organisation that prepares raw goods for use or sale.","zh":"major processor of 指準備原材料供使用或出售的主要地方或機構。"},{"en":"A city can become a major processor of wheat if many mills are built there.","zh":"如果一個城市建有許多磨坊，它可以成為小麥的主要加工中心。"},{"en":"If a region produces many crops, nearby factories may become major processors.","zh":"如果一個地區生產大量作物，附近工廠可能成為主要加工中心。"},{"en":"The phrase connects raw products with industrial activity.","zh":"這個片語把原材料與工業活動連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":10},{"front":"agricultural products","meaning":"農產品","examples":[{"en":"Winnipeg processed agricultural products from the surrounding hinterland.","zh":"溫尼伯加工來自周邊內陸地區的農產品。"},{"en":"Agricultural products are goods produced by farming, such as grain, meat, and vegetables.","zh":"農產品是由農業生產的貨品，例如穀物、肉類和蔬菜。"},{"en":"Markets sell agricultural products from nearby villages every morning.","zh":"市場每天早上出售附近村莊的農產品。"},{"en":"If transport improves, agricultural products can reach cities while still fresh.","zh":"如果交通改善，農產品可以在仍新鮮時到達城市。"},{"en":"The phrase includes more than crops; it can include animal products too.","zh":"這個片語不只包括作物，也可以包括動物產品。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":10},{"front":"surrounding hinterland","meaning":"周邊內陸地區","examples":[{"en":"Winnipeg served the surrounding hinterland.","zh":"溫尼伯服務周邊內陸地區。"},{"en":"The surrounding hinterland is the inland area around a city that supplies or depends on it.","zh":"surrounding hinterland 是城市周圍供應該城市或依賴它的內陸地區。"},{"en":"A port city may buy food from its surrounding hinterland.","zh":"港口城市可能從周邊內陸地區購買食物。"},{"en":"If roads improve, the surrounding hinterland can send goods to the city more easily.","zh":"如果道路改善，周邊內陸地區可更容易把貨物送到城市。"},{"en":"The phrase links a city with its wider rural region.","zh":"這個片語把城市與更廣闊鄉郊地區連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":10},{"front":"the majority of settlers","meaning":"大部分定居者","examples":[{"en":"The majority of settlers to Winnipeg were English-speaking Protestants.","zh":"前往溫尼伯的大部分定居者是信奉新教的英語人士。"},{"en":"The majority of settlers means more than half of the people who settled there.","zh":"the majority of settlers 指超過一半的定居者。"},{"en":"If the majority of settlers share a language, schools may use that language.","zh":"如果大部分定居者使用同一語言，學校可能使用該語言。"},{"en":"The majority of settlers can shape a town’s churches, newspapers, and politics.","zh":"大部分定居者可以塑造城鎮的教會、報紙和政治。"},{"en":"The phrase describes the largest part of a settler group.","zh":"這個片語描述定居者群體中最大的一部分。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":10},{"front":"surrounding countryside","meaning":"周邊鄉郊地區","examples":[{"en":"Settlers moved to Winnipeg and the surrounding countryside.","zh":"定居者遷往溫尼伯及其周邊鄉郊地區。"},{"en":"Surrounding countryside means the rural land around a town or city.","zh":"surrounding countryside 指城鎮或城市周圍的鄉郊土地。"},{"en":"City families may visit the surrounding countryside for fresh air.","zh":"城市家庭可能到周邊鄉郊地區呼吸新鮮空氣。"},{"en":"If a city grows, the surrounding countryside may become suburbs.","zh":"如果城市增長，周邊鄉郊地區可能變成郊區。"},{"en":"The phrase contrasts the urban centre with nearby rural areas.","zh":"這個片語把城市中心與附近鄉郊地區作對比。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":10},{"front":"early period","meaning":"早期階段","examples":[{"en":"The early period saw many settlers from Ontario and the British Isles.","zh":"早期階段有許多來自安大略和不列顛群島的定居者。"},{"en":"Early period means the first stage of a development or historical process.","zh":"early period 指某個發展或歷史過程的最初階段。"},{"en":"In the early period of a business, owners often do many jobs themselves.","zh":"在企業早期階段，老闆通常自己做很多工作。"},{"en":"If the early period is successful, later growth becomes easier.","zh":"如果早期階段成功，之後增長會較容易。"},{"en":"The phrase helps divide history into stages.","zh":"這個片語幫助把歷史分成階段。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":10},{"front":"primarily","meaning":"主要地","examples":[{"en":"The settlers were primarily Protestant English-speaking migrants.","zh":"這些定居者主要是信奉新教的英語移民。"},{"en":"Primarily means mainly or for the most part.","zh":"primarily 指主要地或大部分地。"},{"en":"This library is used primarily by students after school.","zh":"這間圖書館主要由學生放學後使用。"},{"en":"If a town is primarily agricultural, farming shapes its economy.","zh":"如果一個城鎮主要是農業型，農業會塑造其經濟。"},{"en":"The word shows the main characteristic, not the only one.","zh":"這個詞顯示主要特徵，而不是唯一特徵。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":10},{"front":"Protestant English-speaking settlers","meaning":"信奉新教的英語定居者","examples":[{"en":"Many early settlers were Protestant English-speaking settlers.","zh":"許多早期定居者是信奉新教的英語定居者。"},{"en":"Protestant English-speaking settlers are settlers who speak English and follow Protestant Christianity.","zh":"信奉新教的英語定居者是說英語並信奉新教基督教的定居者。"},{"en":"Such settlers may establish English schools and Protestant churches.","zh":"這類定居者可能建立英語學校和新教教會。"},{"en":"If Protestant English-speaking settlers dominate, public life may reflect their values.","zh":"如果信奉新教的英語定居者佔主導，公共生活可能反映其價值觀。"},{"en":"The phrase combines religion and language identity.","zh":"這個片語結合宗教和語言身份。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":10},{"front":"the British Isles","meaning":"不列顛群島","examples":[{"en":"Many settlers came from Ontario and the British Isles.","zh":"許多定居者來自安大略和不列顛群島。"},{"en":"The British Isles refers to the group of islands including Great Britain and Ireland.","zh":"不列顛群島指包括大不列顛和愛爾蘭在內的一組島嶼。"},{"en":"Migrants from the British Isles brought different regional accents and traditions.","zh":"來自不列顛群島的移民帶來不同地區口音和傳統。"},{"en":"If many settlers came from the British Isles, British culture could shape local society.","zh":"如果許多定居者來自不列顛群島，英國文化可能塑造本地社會。"},{"en":"The phrase names a geographical origin.","zh":"這個片語指出地理來源。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":11},{"front":"establish something upon","meaning":"把……建立在……之上","examples":[{"en":"Settlers established Winnipeg upon a British-Ontarian ethos.","zh":"定居者把溫尼伯建立在英國—安大略式精神之上。"},{"en":"Establish something upon means build or base something on a particular idea or foundation.","zh":"establish something upon 指把某事物建基於某種理念或基礎之上。"},{"en":"A school may establish its rules upon trust and responsibility.","zh":"學校可能把規則建立在信任和責任之上。"},{"en":"If a city is established upon one group’s values, politics may reflect those values.","zh":"如果城市建立在某群體價值之上，政治可能反映那些價值。"},{"en":"The phrase is formal and often used with abstract foundations.","zh":"這個片語較正式，常與抽象基礎連用。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":11},{"front":"British-Ontarian ethos","meaning":"英國—安大略式精神","examples":[{"en":"A British-Ontarian ethos shaped Winnipeg’s early society.","zh":"英國—安大略式精神塑造了溫尼伯早期社會。"},{"en":"British-Ontarian ethos means the values and habits linked to British and Ontario settler culture.","zh":"British-Ontarian ethos 指與英國和安大略定居者文化相關的價值和習慣。"},{"en":"This ethos could influence schools, churches, manners, and politics.","zh":"這種精神可以影響學校、教會、禮儀和政治。"},{"en":"If one ethos dominates a city, other groups may feel less represented.","zh":"如果一種精神支配城市，其他群體可能覺得代表性不足。"},{"en":"The phrase refers to a cultural spirit, not a single law.","zh":"這個片語指文化精神，而不是單一法律。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":11},{"front":"come to dominate","meaning":"逐漸支配","examples":[{"en":"This ethos came to dominate Winnipeg’s social and political life.","zh":"這種精神逐漸支配溫尼伯的社會和政治生活。"},{"en":"Come to dominate means gradually become the most powerful or influential force.","zh":"come to dominate 指逐漸成為最有權力或影響力的力量。"},{"en":"One company may come to dominate a market after years of growth.","zh":"一間公司可能經多年增長後逐漸支配市場。"},{"en":"If one language comes to dominate schools, other languages may decline.","zh":"如果一種語言逐漸支配學校，其他語言可能衰退。"},{"en":"The phrase suggests change over time.","zh":"這個片語暗示隨時間出現變化。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":11},{"front":"social, political and economic spirit","meaning":"社會、政治和經濟精神","examples":[{"en":"The British-Ontarian ethos dominated the city’s social, political and economic spirit.","zh":"英國—安大略式精神支配了該市的社會、政治和經濟精神。"},{"en":"Social, political and economic spirit means the general values shaping society, government, and business life.","zh":"社會、政治和經濟精神指塑造社會、政府和商業生活的一般價值。"},{"en":"A city’s social, political and economic spirit can be seen in its laws and public habits.","zh":"一個城市的社會、政治和經濟精神可從其法律和公共習慣看見。"},{"en":"If newcomers change this spirit, institutions may slowly change too.","zh":"如果新來者改變這種精神，制度也可能慢慢改變。"},{"en":"The phrase is broad and describes the character of public life.","zh":"這個片語範圍較廣，描述公共生活的性格。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":11},{"front":"ethnic homogeneity","meaning":"種族同質性","examples":[{"en":"British-Ontarian ethnic homogeneity did not last long.","zh":"英國—安大略式種族同質性沒有維持很久。"},{"en":"Ethnic homogeneity means a population is mostly from the same ethnic background.","zh":"ethnic homogeneity 指人口大多來自相同種族背景。"},{"en":"A small village may appear to have ethnic homogeneity if most families share ancestry.","zh":"如果多數家庭有共同祖源，小村莊可能看似具有種族同質性。"},{"en":"Immigration can reduce ethnic homogeneity by adding new groups.","zh":"移民可透過加入新群體減少種族同質性。"},{"en":"The phrase contrasts with ethnic diversity.","zh":"這個片語與種族多樣性形成對比。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":11},{"front":"not last very long","meaning":"沒有維持很久","examples":[{"en":"The city’s ethnic homogeneity did not last very long.","zh":"該市的種族同質性沒有維持很久。"},{"en":"Not last very long means continue only for a short time.","zh":"not last very long 指只持續很短時間。"},{"en":"A cheap umbrella may not last very long in heavy rain.","zh":"便宜雨傘在大雨中可能沒有維持很久。"},{"en":"If rapid immigration begins, a uniform population may not last very long.","zh":"如果快速移民開始，單一人口結構可能不會維持很久。"},{"en":"The phrase suggests change happens sooner than expected.","zh":"這個片語暗示變化比預期更早發生。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":11},{"front":"increasing numbers of","meaning":"越來越多","examples":[{"en":"Increasing numbers of foreign immigrants changed Winnipeg’s population.","zh":"越來越多外國移民改變了溫尼伯的人口。"},{"en":"Increasing numbers of means more and more over time.","zh":"increasing numbers of 指隨時間越來越多。"},{"en":"Increasing numbers of students use online lessons after school.","zh":"越來越多學生放學後使用網上課堂。"},{"en":"If increasing numbers of families move in, housing demand rises.","zh":"如果越來越多家庭搬入，住房需求會上升。"},{"en":"The phrase emphasises a growing trend.","zh":"這個片語強調增長趨勢。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":11},{"front":"foreign immigrants","meaning":"外國移民","examples":[{"en":"Foreign immigrants added new ethnic elements to the population.","zh":"外國移民為人口加入新的種族元素。"},{"en":"Foreign immigrants are people who move from other countries to live in a new country.","zh":"外國移民是從其他國家遷到新國家生活的人。"},{"en":"Foreign immigrants may bring new languages, religions, foods, and skills.","zh":"外國移民可能帶來新語言、宗教、食物和技能。"},{"en":"If many foreign immigrants arrive, schools may need language support.","zh":"如果許多外國移民到來，學校可能需要語言支援。"},{"en":"The phrase focuses on international movement.","zh":"這個片語集中於國際遷移。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":11},{"front":"Austria-Hungary","meaning":"奧匈帝國","examples":[{"en":"Many immigrants came from Austria-Hungary and Ukraine.","zh":"許多移民來自奧匈帝國和烏克蘭。"},{"en":"Austria-Hungary was a historical empire in central and eastern Europe.","zh":"奧匈帝國是中歐和東歐的一個歷史帝國。"},{"en":"Immigrants from Austria-Hungary could include people of different languages and ethnic groups.","zh":"來自奧匈帝國的移民可能包括不同語言和種族群體的人。"},{"en":"If many migrants came from Austria-Hungary, western towns became more diverse.","zh":"如果許多移民來自奧匈帝國，西部城鎮會變得更多元。"},{"en":"The name belongs to historical geography, not a present-day country.","zh":"這個名稱屬於歷史地理，而不是現今國家。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":11},{"front":"Ukraine","meaning":"烏克蘭","examples":[{"en":"Immigrants from Ukraine added a new ethnic element.","zh":"來自烏克蘭的移民加入了新的種族元素。"},{"en":"Ukraine is a country in eastern Europe and a source of migrants in this passage.","zh":"烏克蘭是東歐一個國家，也是本文中的移民來源地。"},{"en":"Ukrainian immigrants may bring language, food, church traditions, and farming knowledge.","zh":"烏克蘭移民可能帶來語言、食物、教會傳統和農業知識。"},{"en":"If Ukrainian communities grow, they may build schools, churches, and cultural clubs.","zh":"如果烏克蘭社群增長，他們可能建立學校、教會和文化會。"},{"en":"The phrase identifies a national or regional origin.","zh":"這個片語指出國家或地區來源。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":12},{"front":"ethnic element","meaning":"種族元素","examples":[{"en":"Foreign immigrants added a new ethnic element to Winnipeg.","zh":"外國移民為溫尼伯加入新的種族元素。"},{"en":"An ethnic element is a group identity based on shared ancestry, culture, language, or tradition.","zh":"ethnic element 是基於共同祖源、文化、語言或傳統的群體身份。"},{"en":"A neighbourhood may gain a new ethnic element when migrant families open shops there.","zh":"當移民家庭在社區開店，該區可能加入新的種族元素。"},{"en":"New ethnic elements can change food, festivals, languages, and community life.","zh":"新的種族元素可以改變食物、節日、語言和社區生活。"},{"en":"The phrase describes diversity within a population.","zh":"這個片語描述人口內部的多樣性。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":12},{"front":"population base","meaning":"人口基礎","examples":[{"en":"The population base included British arrivals, First Nations and Métis communities.","zh":"人口基礎包括英國移民、第一民族和梅蒂斯人社群。"},{"en":"Population base means the main groups that make up a population.","zh":"population base 指組成人口的主要群體。"},{"en":"A town’s population base may include old families, migrants, and students.","zh":"一個城鎮的人口基礎可能包括老家庭、移民和學生。"},{"en":"If the population base becomes more diverse, public services may need to adapt.","zh":"如果人口基礎變得更多元，公共服務可能需要適應。"},{"en":"The phrase explains who forms the foundation of a community.","zh":"這個片語解釋誰構成社區的基礎。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":12},{"front":"comprise","meaning":"包括；由……組成","examples":[{"en":"The population base comprised several different communities.","zh":"人口基礎包括幾個不同社群。"},{"en":"Comprise means include or be made up of particular parts.","zh":"comprise 指包括某些部分或由某些部分組成。"},{"en":"The committee comprises teachers, parents, and students.","zh":"委員會包括老師、家長和學生。"},{"en":"If a city comprises many communities, decision-making may need careful consultation.","zh":"如果城市由許多社群組成，決策可能需要小心諮詢。"},{"en":"The word is formal and useful in reports.","zh":"這個詞較正式，在報告中很有用。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":12},{"front":"recent British arrivals","meaning":"新近抵達的英國移民","examples":[{"en":"Recent British arrivals formed part of the population base.","zh":"新近抵達的英國移民構成人口基礎的一部分。"},{"en":"Recent British arrivals are people from Britain who had arrived not long before.","zh":"recent British arrivals 指不久前從英國抵達的人。"},{"en":"Recent British arrivals may still be adjusting to local weather and work.","zh":"新近抵達的英國移民可能仍在適應本地天氣和工作。"},{"en":"If recent British arrivals settle quickly, they can influence schools and churches.","zh":"如果新近抵達的英國移民快速定居，他們可影響學校和教會。"},{"en":"The phrase combines origin with arrival time.","zh":"這個片語結合來源和到達時間。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":12},{"front":"First Nations","meaning":"第一民族","examples":[{"en":"First Nations communities were part of the older population.","zh":"第一民族社群是較早人口的一部分。"},{"en":"First Nations refers to Indigenous peoples in Canada who are not Inuit or Métis.","zh":"First Nations 指加拿大原住民族中不包括因紐特人和梅蒂斯人的群體。"},{"en":"First Nations communities have their own histories, languages, and traditions.","zh":"第一民族社群有自己的歷史、語言和傳統。"},{"en":"Settlement policies affected First Nations land, rights, and daily life.","zh":"定居政策影響第一民族的土地、權利和日常生活。"},{"en":"The phrase should be used respectfully and specifically.","zh":"這個片語應以尊重和準確方式使用。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":12},{"front":"Métis communities","meaning":"梅蒂斯人社群","examples":[{"en":"Métis communities lived in the Red River area.","zh":"梅蒂斯人社群居住在紅河地區。"},{"en":"Métis communities are Indigenous communities with mixed Indigenous and European ancestry and distinct culture.","zh":"梅蒂斯人社群是具有原住民和歐洲混合祖源及獨特文化的原住民社群。"},{"en":"Métis communities may have their own language traditions, family networks, and political history.","zh":"梅蒂斯人社群可能有自己的語言傳統、家庭網絡和政治歷史。"},{"en":"When settlers arrived, Métis communities could face pressure over land and rights.","zh":"當定居者到來，梅蒂斯人社群可能在土地和權利上面對壓力。"},{"en":"The phrase refers to a specific people, not simply mixed background in general.","zh":"這個片語指一個特定民族，而不是泛指混合背景。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":12},{"front":"Selkirk settlers","meaning":"塞爾扣克定居者","examples":[{"en":"Selkirk settlers were part of the older population base.","zh":"塞爾扣克定居者是較早人口基礎的一部分。"},{"en":"Selkirk settlers were settlers connected with the Red River settlement founded under Lord Selkirk.","zh":"塞爾扣克定居者是與塞爾扣克勳爵建立的紅河定居點有關的定居者。"},{"en":"History lessons may mention Selkirk settlers when discussing early prairie settlement.","zh":"歷史課討論早期大草原定居時可能提到塞爾扣克定居者。"},{"en":"If Selkirk settlers remained in the region, they contributed to its older population.","zh":"如果塞爾扣克定居者留在該地區，他們便構成較早人口的一部分。"},{"en":"The phrase names a specific historical settler group.","zh":"這個片語指特定歷史定居者群體。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":12},{"front":"offer the advantage of","meaning":"提供……的好處","examples":[{"en":"Settling the West offered the advantage of safeguarding the border.","zh":"開拓西部定居提供了保護邊界的好處。"},{"en":"Offer the advantage of means provide a useful benefit.","zh":"offer the advantage of 指提供某種有用好處。"},{"en":"Online booking offers the advantage of saving time.","zh":"網上預約提供節省時間的好處。"},{"en":"If a school is near home, it offers the advantage of shorter travel.","zh":"如果學校靠近家，它提供較短通勤的好處。"},{"en":"The phrase highlights a positive effect of an action.","zh":"這個片語強調某行動的正面效果。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":12},{"front":"safeguard the 49th parallel","meaning":"保護北緯49度邊界","examples":[{"en":"Canada wanted to safeguard the 49th parallel from American takeover.","zh":"加拿大希望保護北緯49度邊界免受美國接管。"},{"en":"Safeguard the 49th parallel means protect the border line between Canada and the United States.","zh":"safeguard the 49th parallel 指保護加拿大與美國之間的邊界線。"},{"en":"Governments may build posts to safeguard a border.","zh":"政府可能建立駐地來保護邊界。"},{"en":"If settlers lived near the 49th parallel, Canada could strengthen its claim.","zh":"如果定居者住在北緯49度邊界附近，加拿大可強化其主張。"},{"en":"The phrase links geography with national security.","zh":"這個片語把地理與國家安全連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":12},{"front":"the threat of","meaning":"……的威脅","examples":[{"en":"The settlers helped protect Canada from the threat of American takeover.","zh":"定居者幫助保護加拿大免受美國接管的威脅。"},{"en":"The threat of means the danger or possibility of something harmful happening.","zh":"the threat of 指某種有害事情發生的危險或可能性。"},{"en":"The threat of flooding made families prepare emergency bags.","zh":"水浸的威脅令家庭準備緊急包。"},{"en":"If there is a threat of job loss, workers may feel anxious.","zh":"如果有失業威脅，工人可能感到焦慮。"},{"en":"The phrase points to risk, even before harm actually happens.","zh":"這個片語指出風險，即使傷害尚未真正發生。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":13},{"front":"American takeover","meaning":"美國接管","examples":[{"en":"Canada feared American takeover of western territory.","zh":"加拿大害怕美國接管西部領土。"},{"en":"American takeover means the United States gaining control over an area or system.","zh":"American takeover 指美國取得某地區或系統的控制權。"},{"en":"A country may settle border land to prevent foreign takeover.","zh":"一個國家可能在邊境土地定居，以防止外國接管。"},{"en":"If local authority is weak, fears of takeover may grow.","zh":"如果本地權力薄弱，對接管的恐懼可能增加。"},{"en":"In this passage, the phrase refers to control of Canadian western territory.","zh":"在本文中，這個片語指對加拿大西部領土的控制。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":13},{"front":"in particular","meaning":"尤其","examples":[{"en":"Eastern Canadians and British immigrants were important in particular.","zh":"加拿大東部人和英國移民尤其重要。"},{"en":"In particular means especially or more specifically.","zh":"in particular 指尤其或更具體地說。"},{"en":"I enjoy outdoor activities, in particular hiking.","zh":"我喜歡戶外活動，尤其是遠足。"},{"en":"If one group is important in particular, it deserves special attention.","zh":"如果某群體尤其重要，它值得特別關注。"},{"en":"The phrase narrows a general statement to a specific point.","zh":"這個片語把一般陳述收窄到具體重點。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":13},{"front":"Minnesota legislature","meaning":"明尼蘇達州議會","examples":[{"en":"The Minnesota legislature had passed a resolution about annexation.","zh":"明尼蘇達州議會曾通過一項關於吞併的決議。"},{"en":"The Minnesota legislature is the law-making body of the state of Minnesota.","zh":"Minnesota legislature 是明尼蘇達州的立法機構。"},{"en":"A state legislature can debate roads, schools, taxes, and public safety.","zh":"州議會可以辯論道路、學校、稅收和公共安全。"},{"en":"If the Minnesota legislature passed a resolution, it expressed an official position.","zh":"如果明尼蘇達州議會通過決議，它表達了官方立場。"},{"en":"The phrase refers to a political institution.","zh":"這個片語指政治機構。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":13},{"front":"pass a resolution","meaning":"通過決議","examples":[{"en":"The Minnesota legislature passed a resolution.","zh":"明尼蘇達州議會通過了一項決議。"},{"en":"Pass a resolution means officially approve a formal statement or decision.","zh":"pass a resolution 指正式批准一項正式聲明或決定。"},{"en":"A school council may pass a resolution to improve lunch facilities.","zh":"學生會可能通過決議改善午餐設施。"},{"en":"If a parliament passes a resolution, it may not be a law but still carries meaning.","zh":"如果議會通過決議，它未必是法律，但仍有意義。"},{"en":"The phrase is common in meetings and politics.","zh":"這個片語常見於會議和政治。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":13},{"front":"provide for","meaning":"規定；為……作出安排","examples":[{"en":"The resolution provided for the annexation of the Red River district.","zh":"該決議規定吞併紅河地區。"},{"en":"Provide for means make arrangements for something in a rule, plan, or law.","zh":"provide for 指在規則、計劃或法律中為某事作出安排。"},{"en":"A school policy may provide for extra help after class.","zh":"學校政策可能規定課後額外支援。"},{"en":"If a contract provides for sick leave, workers have a clear right to it.","zh":"如果合約規定病假，工人便有清晰權利。"},{"en":"The phrase is formal and often legal.","zh":"這個片語較正式，常用於法律語境。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":13},{"front":"annexation of","meaning":"對……的吞併","examples":[{"en":"The resolution supported the annexation of the Red River district.","zh":"該決議支持對紅河地區的吞併。"},{"en":"Annexation of means the act of taking control of territory and adding it to another political area.","zh":"annexation of 指控制某領土並把它加入另一政治區域的行為。"},{"en":"The annexation of land can create conflict between neighbouring governments.","zh":"對土地的吞併可以在鄰近政府之間造成衝突。"},{"en":"If residents oppose annexation, political tension may increase.","zh":"如果居民反對吞併，政治緊張可能增加。"},{"en":"The phrase is used in territorial and political discussions.","zh":"這個片語用於領土和政治討論。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":13},{"front":"Red River district","meaning":"紅河地區","examples":[{"en":"The Red River district was an important settlement on the Canadian prairies.","zh":"紅河地區是加拿大大草原上的重要定居點。"},{"en":"The Red River district was a settlement area in what became Manitoba.","zh":"紅河地區是後來成為曼尼托巴一帶的定居區。"},{"en":"The Red River district included different communities with different histories.","zh":"紅河地區包括具有不同歷史的不同社群。"},{"en":"If outsiders wanted the Red River district, Canada worried about its western control.","zh":"如果外部勢力想取得紅河地區，加拿大會擔心其西部控制權。"},{"en":"The phrase names a specific historical region.","zh":"這個片語指特定歷史地區。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":13},{"front":"Canadian prairies","meaning":"加拿大大草原","examples":[{"en":"The Red River was the most important settlement on the Canadian prairies.","zh":"紅河是加拿大大草原上最重要的定居點。"},{"en":"The Canadian prairies are Canada’s wide grassland regions, especially in the central-west.","zh":"加拿大大草原是加拿大廣闊草原地區，尤其位於中西部。"},{"en":"The Canadian prairies are strongly linked with wheat farming.","zh":"加拿大大草原與小麥農業密切相關。"},{"en":"If railways crossed the Canadian prairies, farms could reach distant markets.","zh":"如果鐵路穿越加拿大大草原，農場可接觸遙遠市場。"},{"en":"The phrase refers to both geography and settlement history.","zh":"這個片語同時涉及地理和定居歷史。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":13},{"front":"inhabitants","meaning":"居民","examples":[{"en":"The Red River contained 11,963 inhabitants.","zh":"紅河地區有11,963名居民。"},{"en":"Inhabitants are the people or animals living in a place.","zh":"inhabitants 指生活在某地方的人或動物。"},{"en":"The inhabitants of a village may share wells, roads, and schools.","zh":"一條村的居民可能共享水井、道路和學校。"},{"en":"If inhabitants increase quickly, a town may need more services.","zh":"如果居民迅速增加，城鎮可能需要更多服務。"},{"en":"The word is more formal than residents.","zh":"這個詞比 residents 更正式。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":13},{"front":"neighbouring Minnesota","meaning":"鄰近的明尼蘇達州","examples":[{"en":"Neighbouring Minnesota already had a much larger population.","zh":"鄰近的明尼蘇達州已經有大得多的人口。"},{"en":"Neighbouring Minnesota means the nearby state of Minnesota.","zh":"neighbouring Minnesota 指附近的明尼蘇達州。"},{"en":"A town may trade often with neighbouring regions across a border.","zh":"一個城鎮可能常與邊界另一邊的鄰近地區貿易。"},{"en":"If neighbouring Minnesota had more people, Canada might feel demographic pressure.","zh":"如果鄰近的明尼蘇達州人口更多，加拿大可能感到人口壓力。"},{"en":"The phrase shows geographical closeness.","zh":"這個片語顯示地理接近。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":14},{"front":"not all of","meaning":"並非所有……","examples":[{"en":"Not all of the settlers desired to remain in western Canada.","zh":"並非所有定居者都希望留在加拿大西部。"},{"en":"Not all of means some, but not every member of a group.","zh":"not all of 指某群體中有些是，但不是每一個都是。"},{"en":"Not all of the students understood the instructions the first time.","zh":"並非所有學生第一次都明白指示。"},{"en":"If not all of the workers agree, managers may need more discussion.","zh":"如果並非所有工人都同意，管理層可能需要更多討論。"},{"en":"The phrase avoids overgeneralising.","zh":"這個片語避免過度概括。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":14},{"front":"desire to remain","meaning":"希望留下","examples":[{"en":"Some settlers did not desire to remain in western Canada.","zh":"有些定居者並不希望留在加拿大西部。"},{"en":"Desire to remain means want to stay in a place or situation.","zh":"desire to remain 指希望留在某地方或情況中。"},{"en":"A student may desire to remain in the same class because friends are there.","zh":"學生可能因朋友在同班而希望留下。"},{"en":"If work is scarce, migrants may not desire to remain permanently.","zh":"如果工作稀少，移民可能不希望永久留下。"},{"en":"The phrase is more formal than want to stay.","zh":"這個片語比 want to stay 更正式。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":14},{"front":"economic depression","meaning":"經濟蕭條","examples":[{"en":"Economic depression discouraged permanent settlement in the West.","zh":"經濟蕭條阻礙了西部永久定居。"},{"en":"Economic depression is a serious and lasting downturn in business, jobs, and income.","zh":"經濟蕭條是商業、就業和收入嚴重而持久的下滑。"},{"en":"During economic depression, families may spend less and companies may hire fewer workers.","zh":"在經濟蕭條期間，家庭可能減少消費，公司可能減少招聘。"},{"en":"If economic depression reduces crop prices, farmers may delay settlement plans.","zh":"如果經濟蕭條降低農產品價格，農民可能推遲定居計劃。"},{"en":"The phrase describes a deeper crisis than a short slowdown.","zh":"這個片語描述比短期放緩更深的危機。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":14},{"front":"staple exports","meaning":"主要出口商品","examples":[{"en":"Economic depression kept the value of Canada’s staple exports low.","zh":"經濟蕭條令加拿大主要出口商品的價值保持低位。"},{"en":"Staple exports are basic goods a country regularly sells abroad in large amounts.","zh":"staple exports 是一個國家定期大量出口的基本商品。"},{"en":"Wheat, timber, and fish can be staple exports for some economies.","zh":"小麥、木材和魚類可以是某些經濟體的主要出口商品。"},{"en":"If staple exports lose value, national income may fall.","zh":"如果主要出口商品貶值，國民收入可能下降。"},{"en":"The phrase links trade with key natural or agricultural products.","zh":"這個片語把貿易與主要自然或農業產品連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":14},{"front":"discourage someone from","meaning":"阻止某人；令某人打消……念頭","examples":[{"en":"Low export values discouraged many from permanent settlement.","zh":"低出口價值令許多人打消永久定居的念頭。"},{"en":"Discourage someone from means make someone less willing to do something.","zh":"discourage someone from 指令某人較不願意做某事。"},{"en":"High rent may discourage young people from moving out.","zh":"高租金可能令年輕人打消搬出去的念頭。"},{"en":"If roads are unsafe, they can discourage tourists from visiting.","zh":"如果道路不安全，它們可以阻止遊客到訪。"},{"en":"The phrase shows that a factor reduces motivation.","zh":"這個片語顯示某因素減低動機。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":14},{"front":"permanent settlement","meaning":"永久定居","examples":[{"en":"Economic depression discouraged permanent settlement in the West.","zh":"經濟蕭條阻礙了西部永久定居。"},{"en":"Permanent settlement means living in a place for the long term, not temporarily.","zh":"permanent settlement 指長期居住在某地，而不是暫時停留。"},{"en":"A family may choose permanent settlement after finding stable work and housing.","zh":"一個家庭找到穩定工作和住房後，可能選擇永久定居。"},{"en":"If crops fail repeatedly, permanent settlement becomes less attractive.","zh":"如果作物連續失收，永久定居會變得較不吸引。"},{"en":"The phrase contrasts with temporary migration.","zh":"這個片語與臨時遷移形成對比。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":14},{"front":"compete with","meaning":"與……競爭","examples":[{"en":"Other countries competed with Canada for immigrants.","zh":"其他國家與加拿大競爭移民。"},{"en":"Compete with means try to win people, customers, resources, or success against another side.","zh":"compete with 指與另一方爭取人、顧客、資源或成功。"},{"en":"Small shops compete with supermarkets by offering personal service.","zh":"小店透過個人化服務與超市競爭。"},{"en":"If countries compete with each other for migrants, they may offer better opportunities.","zh":"如果國家之間競爭移民，它們可能提供更好機會。"},{"en":"The phrase shows rivalry or comparison.","zh":"這個片語顯示競爭或比較。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":14},{"front":"American frontier","meaning":"美國邊疆地區","examples":[{"en":"Many immigrants chose to settle on the American frontier.","zh":"許多移民選擇在美國邊疆地區定居。"},{"en":"The American frontier was the expanding settlement zone in the United States.","zh":"美國邊疆地區是美國不斷擴張的定居帶。"},{"en":"Farmers on the American frontier might seek cheap land and new opportunities.","zh":"美國邊疆地區的農民可能尋找廉價土地和新機會。"},{"en":"If the American frontier was easier to reach, migrants might choose it over Canada.","zh":"如果美國邊疆地區較容易到達，移民可能選擇它而非加拿大。"},{"en":"The phrase belongs to North American settlement history.","zh":"這個片語屬於北美定居歷史。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":14},{"front":"accessible and attractive","meaning":"容易到達而有吸引力","examples":[{"en":"The American frontier was accessible and attractive to settlers.","zh":"美國邊疆地區對定居者而言容易到達而有吸引力。"},{"en":"Accessible and attractive means easy to reach and appealing to people.","zh":"accessible and attractive 指容易到達並令人感興趣。"},{"en":"A school near a station is accessible and attractive to parents.","zh":"靠近車站的學校對家長而言容易到達而有吸引力。"},{"en":"If land is accessible and attractive, migrants may choose it quickly.","zh":"如果土地容易到達而有吸引力，移民可能很快選擇它。"},{"en":"The phrase combines practical convenience with desire.","zh":"這個片語結合實際方便和吸引力。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":14},{"front":"be called","meaning":"被稱為","examples":[{"en":"Canada before 1891 has been called a huge demographic railway station.","zh":"1891年前的加拿大被稱為一個巨大的人口流動鐵路站。"},{"en":"Be called means be described or named in a particular way.","zh":"be called 指被以某種方式描述或命名。"},{"en":"A busy market may be called the heart of a neighbourhood.","zh":"繁忙市場可能被稱為社區的心臟。"},{"en":"If a place is called a railway station metaphorically, many people pass through it.","zh":"如果一個地方被比喻為鐵路站，許多人會經過它。"},{"en":"The phrase introduces a label or description.","zh":"這個片語引出一個標籤或描述。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":15},{"front":"demographic railway station","meaning":"人口流動的鐵路站","examples":[{"en":"Canada was described as a huge demographic railway station.","zh":"加拿大被描述為一個巨大的人口流動鐵路站。"},{"en":"A demographic railway station is a metaphor for a place where many people arrive and leave.","zh":"demographic railway station 是比喻，指許多人抵達又離開的地方。"},{"en":"A port city can feel like a demographic railway station if migrants constantly pass through.","zh":"如果移民不斷經過，一個港口城市可能像人口流動的鐵路站。"},{"en":"If departures exceed arrivals, a demographic railway station does not gain much population.","zh":"如果離境人數多於抵達人數，人口流動的鐵路站不會增加太多人口。"},{"en":"The phrase describes population movement, not an actual station.","zh":"這個片語描述人口流動，而不是真正車站。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":15},{"front":"constantly going and coming","meaning":"不斷來來往往","examples":[{"en":"People were constantly going and coming through Canada.","zh":"人們不斷經過加拿大，來來往往。"},{"en":"Constantly going and coming means repeatedly arriving and leaving.","zh":"constantly going and coming 指反覆抵達和離開。"},{"en":"At a busy clinic, patients are constantly going and coming all day.","zh":"在繁忙診所，病人整天不斷來來往往。"},{"en":"If migrants are constantly going and coming, population numbers may remain unstable.","zh":"如果移民不斷來來往往，人口數字可能保持不穩定。"},{"en":"The phrase suggests continuous movement.","zh":"這個片語暗示持續流動。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":15},{"front":"departures","meaning":"離境人數","examples":[{"en":"The number of departures exceeded that of arrivals.","zh":"離境人數超過抵達人數。"},{"en":"Departures are people or vehicles leaving a place.","zh":"departures 指離開某地的人或交通工具。"},{"en":"Airport screens show departures and arrivals separately.","zh":"機場屏幕分開顯示離境和抵達。"},{"en":"If departures are higher than arrivals, a place may lose population.","zh":"如果離境人數高於抵達人數，一個地方可能流失人口。"},{"en":"The word focuses on leaving, not entering.","zh":"這個詞集中於離開，而不是進入。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":15},{"front":"invariably exceeded","meaning":"一直超過","examples":[{"en":"The number of departures invariably exceeded the number of arrivals.","zh":"離境人數一直超過抵達人數。"},{"en":"Invariably exceeded means was always greater than.","zh":"invariably exceeded 指一直多於或高於。"},{"en":"In that shop, demand invariably exceeded supply during holidays.","zh":"在那間店，假期期間需求一直超過供應。"},{"en":"If costs invariably exceed income, a business cannot survive long.","zh":"如果成本一直超過收入，企業不能長期生存。"},{"en":"The phrase suggests a repeated and consistent pattern.","zh":"這個片語暗示重複而穩定的模式。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":15},{"front":"arrivals","meaning":"抵達人數","examples":[{"en":"Arrivals did not outnumber departures before 1891.","zh":"1891年前，抵達人數沒有多於離境人數。"},{"en":"Arrivals are people or vehicles entering or reaching a place.","zh":"arrivals 指進入或到達某地的人或交通工具。"},{"en":"Airport staff check arrivals to see when passengers land.","zh":"機場職員查看抵達資料，了解乘客何時降落。"},{"en":"If arrivals increase, hotels and transport services may become busier.","zh":"如果抵達人數增加，酒店和交通服務可能更繁忙。"},{"en":"The word focuses on coming in, not leaving.","zh":"這個詞集中於進入，而不是離開。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":15},{"front":"have its share of","meaning":"有相當多的……","examples":[{"en":"Eastern Canada had its share of large urban centres and urban problems.","zh":"加拿大東部有相當多的大型城市中心和城市問題。"},{"en":"Have its share of means have a noticeable amount of something, often problems or features.","zh":"have its share of 指有相當數量的某事物，常指問題或特徵。"},{"en":"Every school has its share of noisy days and difficult moments.","zh":"每所學校都有相當多嘈雜日子和困難時刻。"},{"en":"If a city has its share of traffic problems, commuters may complain often.","zh":"如果城市有相當多交通問題，通勤者可能經常投訴。"},{"en":"The phrase suggests something is not unusual or absent.","zh":"這個片語暗示某事並不罕見或不存在。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":15},{"front":"large urban centres","meaning":"大型城市中心","examples":[{"en":"Eastern Canada had large urban centres by 1891.","zh":"到1891年，加拿大東部已有大型城市中心。"},{"en":"Large urban centres are big cities or major towns with many people and services.","zh":"大型城市中心是擁有大量人口和服務的大城市或主要城鎮。"},{"en":"Large urban centres often attract workers, shops, hospitals, and schools.","zh":"大型城市中心常吸引工人、商店、醫院和學校。"},{"en":"If large urban centres grow too quickly, housing may become crowded.","zh":"如果大型城市中心增長太快，住房可能變得擠迫。"},{"en":"The phrase contrasts with rural settlements and small towns.","zh":"這個片語與鄉郊定居點和小鎮形成對比。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":15},{"front":"problems associated with","meaning":"與……有關的問題","examples":[{"en":"Eastern Canada faced problems associated with city life.","zh":"加拿大東部面對與城市生活有關的問題。"},{"en":"Problems associated with means difficulties connected to something.","zh":"problems associated with 指與某事有關的困難。"},{"en":"Lack of sleep is one problem associated with heavy screen use.","zh":"睡眠不足是與大量使用屏幕有關的問題之一。"},{"en":"If factories expand, pollution may be a problem associated with growth.","zh":"如果工廠擴張，污染可能是與增長有關的問題。"},{"en":"The phrase links a problem with its related situation.","zh":"這個片語把問題與相關情況連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":15},{"front":"city life","meaning":"城市生活","examples":[{"en":"Social reformers contrasted city life with rural living.","zh":"社會改革者把城市生活與鄉郊生活作對比。"},{"en":"City life means the way people live in urban areas.","zh":"city life 指人們在城市地區的生活方式。"},{"en":"City life often includes crowded transport, shops, offices, and apartment buildings.","zh":"城市生活通常包括擠迫交通、商店、辦公室和公寓樓。"},{"en":"If city life becomes too expensive, families may move to smaller towns.","zh":"如果城市生活變得太昂貴，家庭可能搬到小城鎮。"},{"en":"The phrase contrasts with countryside or village living.","zh":"這個片語與鄉郊或村莊生活形成對比。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":15},{"front":"booming economic centres","meaning":"蓬勃發展的經濟中心","examples":[{"en":"Toronto and Montreal were booming economic centres.","zh":"多倫多和蒙特利爾是蓬勃發展的經濟中心。"},{"en":"Booming economic centres are cities where business, jobs, and trade are growing quickly.","zh":"蓬勃發展的經濟中心是商業、工作和貿易迅速增長的城市。"},{"en":"A port can become a booming economic centre when trade increases.","zh":"當貿易增加，港口可以成為蓬勃發展的經濟中心。"},{"en":"If a city is a booming economic centre, migrants may arrive looking for work.","zh":"如果城市是蓬勃發展的經濟中心，移民可能前來尋找工作。"},{"en":"The phrase suggests fast and visible economic growth.","zh":"這個片語暗示快速而明顯的經濟增長。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":16},{"front":"be complete with","meaning":"配備有","examples":[{"en":"Wealthy areas were complete with electricity and telephones.","zh":"富裕地區配備有電力和電話。"},{"en":"Be complete with means have particular features or equipment included.","zh":"be complete with 指包括某些特色或設備。"},{"en":"The new flat was complete with furniture and kitchen appliances.","zh":"新單位配備有家具和廚房電器。"},{"en":"If a hotel is complete with a pool and gym, guests may pay more.","zh":"如果酒店配備有泳池和健身室，客人可能支付更多。"},{"en":"The phrase highlights what a place already contains.","zh":"這個片語強調某地已經具備甚麼。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":16},{"front":"by the turn of the century","meaning":"到世紀之交","examples":[{"en":"Toronto and Montreal had modern services by the turn of the century.","zh":"到世紀之交，多倫多和蒙特利爾已有現代服務。"},{"en":"By the turn of the century means around the time one century changes into the next.","zh":"by the turn of the century 指大約一個世紀轉入下一個世紀的時候。"},{"en":"By the turn of the century, many cities had electric streetlights.","zh":"到世紀之交，許多城市已有電街燈。"},{"en":"If a technology spreads by the turn of the century, it becomes part of a new era.","zh":"如果一項科技到世紀之交已普及，它就成為新時代的一部分。"},{"en":"The phrase usually refers to years around 1900 or another century change.","zh":"這個片語通常指1900年前後或另一個世紀交替時期。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":16},{"front":"slum conditions","meaning":"貧民窟環境","examples":[{"en":"Slum conditions characterised the poorest urban areas.","zh":"貧民窟環境成為最貧困城市地區的特徵。"},{"en":"Slum conditions are very poor living conditions, often with overcrowding and bad sanitation.","zh":"貧民窟環境是非常惡劣的生活條件，通常有過度擠迫和衛生差。"},{"en":"Families in slum conditions may lack clean water, safe toilets, and enough space.","zh":"生活在貧民窟環境中的家庭可能缺乏清潔食水、安全廁所和足夠空間。"},{"en":"If slum conditions spread, disease and social problems may increase.","zh":"如果貧民窟環境擴散，疾病和社會問題可能增加。"},{"en":"The phrase describes unhealthy and neglected urban living.","zh":"這個片語描述不健康且被忽視的城市生活。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":16},{"front":"characterise","meaning":"成為……的特徵","examples":[{"en":"Slum conditions characterised the poorest districts.","zh":"貧民窟環境成為最貧困地區的特徵。"},{"en":"Characterise means be a typical feature of something.","zh":"characterise 指成為某事物的典型特徵。"},{"en":"Long queues may characterise a hospital with too few staff.","zh":"長隊可能成為人手不足醫院的特徵。"},{"en":"If trust characterises a classroom, students ask questions more freely.","zh":"如果信任成為課室特徵，學生會更自由提問。"},{"en":"The word helps describe what makes a place or situation recognisable.","zh":"這個詞幫助描述某地方或情況的辨識特徵。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":16},{"front":"the poorest areas","meaning":"最貧困地區","examples":[{"en":"Slum conditions characterised the poorest areas of Toronto.","zh":"貧民窟環境成為多倫多最貧困地區的特徵。"},{"en":"The poorest areas are parts of a city where residents have the lowest income and worst conditions.","zh":"最貧困地區是居民收入最低、環境最差的城市部分。"},{"en":"The poorest areas may need better housing, healthcare, and schools.","zh":"最貧困地區可能需要更好住房、醫療和學校。"},{"en":"If services ignore the poorest areas, inequality can become worse.","zh":"如果服務忽視最貧困地區，不平等可能惡化。"},{"en":"The phrase identifies places of serious social disadvantage.","zh":"這個片語指出有嚴重社會弱勢的地方。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":16},{"front":"district known as","meaning":"被稱為……的地區","examples":[{"en":"The Ward was a district known as a poor area in Toronto.","zh":"The Ward 是多倫多一個被稱為貧困地區的區域。"},{"en":"District known as means an area recognised by a particular name or reputation.","zh":"district known as 指因某名稱或名聲而被認識的地區。"},{"en":"This street is in a district known as the old market quarter.","zh":"這條街位於被稱為舊市場區的地區。"},{"en":"If a district is known as unsafe, visitors may avoid it.","zh":"如果一個地區被稱為不安全，遊客可能避開它。"},{"en":"The phrase links a place with a name or public image.","zh":"這個片語把地方與名稱或公眾形象連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":16},{"front":"privy buckets","meaning":"糞桶；簡陋廁所用桶","examples":[{"en":"Privy buckets spilled into backyards and lanes.","zh":"糞桶溢出到後院和小巷。"},{"en":"Privy buckets are simple toilet containers used before modern sanitation.","zh":"privy buckets 是現代衛生設備出現前使用的簡陋廁所容器。"},{"en":"In poor housing, privy buckets could create bad smells and disease risks.","zh":"在貧困住房中，糞桶可能造成惡臭和疾病風險。"},{"en":"If privy buckets overflow, waste can spread into living areas.","zh":"如果糞桶滿瀉，廢物可以擴散到生活區。"},{"en":"The phrase shows how basic sanitation could be in urban slums.","zh":"這個片語顯示城市貧民窟的衛生設施可以多麼基本。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":16},{"front":"spill into","meaning":"溢出到","examples":[{"en":"Privy buckets spilled into backyards and lanes.","zh":"糞桶溢出到後院和小巷。"},{"en":"Spill into means overflow or spread into another place.","zh":"spill into 指滿瀉或擴散到另一地方。"},{"en":"Rainwater may spill into a basement during a storm.","zh":"暴風雨期間，雨水可能溢入地下室。"},{"en":"If sewage spills into streets, public health risks increase.","zh":"如果污水溢出到街道，公共健康風險會增加。"},{"en":"The phrase often suggests unwanted movement of liquid or material.","zh":"這個片語常暗示液體或物質的不受歡迎移動。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":16},{"front":"backyards and lanes","meaning":"後院和小巷","examples":[{"en":"Waste spilled into backyards and lanes.","zh":"廢物溢出到後院和小巷。"},{"en":"Backyards and lanes are small outdoor spaces behind homes and narrow paths between buildings.","zh":"backyards and lanes 是房屋後方的小戶外空間和建築物之間的狹窄通道。"},{"en":"Children may play in backyards and lanes if the area is clean and safe.","zh":"如果地方清潔安全，孩子可能在後院和小巷玩耍。"},{"en":"If waste enters backyards and lanes, daily life becomes unhealthy.","zh":"如果廢物進入後院和小巷，日常生活會變得不衛生。"},{"en":"The phrase gives a concrete picture of crowded urban housing.","zh":"這個片語提供了擠迫城市住房的具體畫面。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":16},{"front":"create cesspools","meaning":"形成污水坑","examples":[{"en":"Waste created cesspools in urban slums.","zh":"廢物在城市貧民窟形成污水坑。"},{"en":"Create cesspools means form dirty pools of waste water or sewage.","zh":"create cesspools 指形成骯髒的污水或糞水池。"},{"en":"Poor drainage can create cesspools after heavy rain.","zh":"排水不良可以在大雨後形成污水坑。"},{"en":"If waste creates cesspools, insects and disease may spread.","zh":"如果廢物形成污水坑，昆蟲和疾病可能傳播。"},{"en":"The phrase describes a serious sanitation problem.","zh":"這個片語描述嚴重衛生問題。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":17},{"front":"urban slums","meaning":"城市貧民窟","examples":[{"en":"Cesspools formed in urban slums.","zh":"污水坑在城市貧民窟形成。"},{"en":"Urban slums are poor city areas with crowded housing and poor services.","zh":"城市貧民窟是住房擠迫、服務差的貧困城市地區。"},{"en":"Urban slums may lack clean water, waste collection, and safe streets.","zh":"城市貧民窟可能缺乏清潔食水、垃圾收集和安全街道。"},{"en":"If urban slums expand, social reformers may demand better housing laws.","zh":"如果城市貧民窟擴大，社會改革者可能要求更好的住房法律。"},{"en":"The phrase describes poverty inside cities.","zh":"這個片語描述城市內部的貧窮。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":17},{"front":"social reformers","meaning":"社會改革者","examples":[{"en":"Social reformers praised rural living as healthy and moral.","zh":"社會改革者讚揚鄉郊生活健康而道德。"},{"en":"Social reformers are people who try to improve society through changes in law, health, education, or welfare.","zh":"社會改革者是試圖透過法律、健康、教育或福利改革改善社會的人。"},{"en":"Social reformers may campaign for cleaner housing and safer workplaces.","zh":"社會改革者可能倡議更清潔住房和更安全工作場所。"},{"en":"If social reformers expose urban poverty, governments may face pressure to act.","zh":"如果社會改革者揭露城市貧窮，政府可能面對行動壓力。"},{"en":"The phrase describes people who want practical social change.","zh":"這個片語描述希望推動實際社會改變的人。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":17},{"front":"rural living","meaning":"鄉郊生活","examples":[{"en":"Rural living was seen as healthier than urban life.","zh":"鄉郊生活被視為比城市生活更健康。"},{"en":"Rural living means life in the countryside or farming communities.","zh":"rural living 指鄉村或農業社區中的生活。"},{"en":"Rural living may involve open spaces, farm work, and smaller communities.","zh":"鄉郊生活可能包括開闊空間、農務和較小社區。"},{"en":"If people value fresh air, rural living may seem attractive.","zh":"如果人們重視新鮮空氣，鄉郊生活可能顯得有吸引力。"},{"en":"The phrase contrasts with city life.","zh":"這個片語與城市生活形成對比。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":17},{"front":"in stark contrast to","meaning":"與……形成鮮明對比","examples":[{"en":"Rural living stood in stark contrast to urban life.","zh":"鄉郊生活與城市生活形成鮮明對比。"},{"en":"In stark contrast to means very different from something else in an obvious way.","zh":"in stark contrast to 指與某事物有非常明顯的巨大不同。"},{"en":"The quiet library was in stark contrast to the noisy street outside.","zh":"安靜圖書館與外面嘈雜街道形成鮮明對比。"},{"en":"If rich districts stand in stark contrast to slums, inequality becomes visible.","zh":"如果富裕地區與貧民窟形成鮮明對比，不平等就變得可見。"},{"en":"The phrase emphasises a strong difference.","zh":"這個片語強調強烈差異。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":17},{"front":"lead to","meaning":"導致；帶來","examples":[{"en":"Rural living was believed to lead to a healthy way of life.","zh":"人們相信鄉郊生活會帶來健康的生活方式。"},{"en":"Lead to means cause or result in something.","zh":"lead to 指造成或導致某結果。"},{"en":"Regular practice can lead to better pronunciation.","zh":"定期練習可以帶來更好的發音。"},{"en":"Poor drainage can lead to flooding after heavy rain.","zh":"排水不良可以在大雨後導致水浸。"},{"en":"The phrase connects cause and result.","zh":"這個片語連接原因和結果。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":17},{"front":"a healthy, moral and charitable way of life","meaning":"健康、道德而仁慈的生活方式","examples":[{"en":"Reformers believed rural living would lead to a healthy, moral and charitable way of life.","zh":"改革者相信鄉郊生活會帶來健康、道德而仁慈的生活方式。"},{"en":"A healthy, moral and charitable way of life means living with good health, good behaviour, and care for others.","zh":"a healthy, moral and charitable way of life 指有健康、良好行為和關心他人的生活方式。"},{"en":"Some people think community farming encourages a healthy, moral and charitable way of life.","zh":"有些人認為社區農業鼓勵健康、道德而仁慈的生活方式。"},{"en":"If families work together and help neighbours, this ideal may seem achievable.","zh":"如果家庭一起工作並幫助鄰居，這種理想可能看似可達成。"},{"en":"The phrase reflects a value judgement about how people should live.","zh":"這個片語反映人們對應如何生活的價值判斷。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":17},{"front":"fresh air","meaning":"新鮮空氣","examples":[{"en":"Reformers praised the benefits of fresh air.","zh":"改革者讚揚新鮮空氣的好處。"},{"en":"Fresh air is clean outdoor air, often associated with health.","zh":"新鮮空氣是清潔的戶外空氣，常與健康有關。"},{"en":"After studying indoors all day, students may feel better with fresh air.","zh":"在室內學習整天後，學生呼吸新鮮空氣可能感覺更好。"},{"en":"If housing is crowded and poorly ventilated, fresh air becomes important.","zh":"如果住房擠迫且通風差，新鮮空氣就變得重要。"},{"en":"The phrase often appears in discussions of health and countryside life.","zh":"這個片語常出現在健康和鄉郊生活討論中。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":17},{"front":"hard work","meaning":"辛勤工作","examples":[{"en":"Hard work was seen as part of a moral rural life.","zh":"辛勤工作被視為道德鄉郊生活的一部分。"},{"en":"Hard work means serious effort and steady labour.","zh":"hard work 指認真努力和持續勞動。"},{"en":"Passing a difficult exam usually requires hard work over many weeks.","zh":"通過困難考試通常需要多星期辛勤工作。"},{"en":"On farms, hard work can produce food and teach responsibility.","zh":"在農場，辛勤工作可以生產食物並教人負責任。"},{"en":"The phrase is often linked with discipline and achievement.","zh":"這個片語常與紀律和成就有關。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":17},{"front":"open spaces","meaning":"開闊空間","examples":[{"en":"Open spaces were believed to benefit immigrants.","zh":"人們相信開闊空間對移民有益。"},{"en":"Open spaces are wide areas without many buildings or crowds.","zh":"開闊空間是沒有太多建築或人群的寬廣地區。"},{"en":"Parks provide open spaces where children can run and play.","zh":"公園提供開闊空間，讓孩子奔跑和玩耍。"},{"en":"If people move from crowded slums to open spaces, they may feel healthier.","zh":"如果人們從擠迫貧民窟搬到開闊空間，他們可能感覺更健康。"},{"en":"The phrase often suggests freedom, air, and room to grow.","zh":"這個片語常暗示自由、空氣和成長空間。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":17},{"front":"Canadianise immigrants","meaning":"使移民加拿大化","examples":[{"en":"Reformers believed rural life could Canadianise immigrants.","zh":"改革者相信鄉郊生活可以使移民加拿大化。"},{"en":"Canadianise immigrants means make immigrants adopt Canadian habits, values, or identity.","zh":"Canadianise immigrants 指使移民採納加拿大習慣、價值或身份。"},{"en":"Schools may try to Canadianise immigrants by teaching national history and language.","zh":"學校可能透過教授國家歷史和語言來使移民加拿大化。"},{"en":"If immigrants are pressured to Canadianise too quickly, they may lose cultural ties.","zh":"如果移民被迫太快加拿大化，他們可能失去文化聯繫。"},{"en":"The phrase reflects an assimilation idea.","zh":"這個片語反映同化概念。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":18},{"front":"agricultural pursuits","meaning":"農業活動","examples":[{"en":"Agricultural pursuits were seen as fitting for family life.","zh":"農業活動被視為適合家庭生活。"},{"en":"Agricultural pursuits are activities connected with farming and raising animals.","zh":"agricultural pursuits 是與耕種和飼養動物有關的活動。"},{"en":"Planting crops, milking cows, and repairing fences are agricultural pursuits.","zh":"種植作物、擠牛奶和修理圍欄都是農業活動。"},{"en":"If families share agricultural pursuits, children may learn practical skills early.","zh":"如果家庭共同參與農業活動，孩子可能很早學到實用技能。"},{"en":"The phrase is more formal than farm work.","zh":"這個片語比 farm work 更正式。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":18},{"front":"be seen as especially fitting for","meaning":"被視為特別適合……","examples":[{"en":"Agriculture was seen as especially fitting for a moral way of life.","zh":"農業被視為特別適合一種道德生活方式。"},{"en":"Be seen as especially fitting for means be considered particularly suitable for something.","zh":"be seen as especially fitting for 指被認為對某事特別適合。"},{"en":"Quiet reading may be seen as especially fitting for young children before bedtime.","zh":"安靜閱讀可能被視為特別適合年幼孩子睡前進行。"},{"en":"If farming is seen as especially fitting for families, policy may favour rural settlement.","zh":"如果農業被視為特別適合家庭，政策可能偏向鄉郊定居。"},{"en":"The phrase expresses social judgement about suitability.","zh":"這個片語表達社會對合適性的判斷。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":18},{"front":"attain a way of life","meaning":"達到一種生活方式","examples":[{"en":"Agriculture helped settlers attain a family-oriented way of life.","zh":"農業幫助定居者達到以家庭為本的生活方式。"},{"en":"Attain a way of life means achieve or reach a particular pattern of living.","zh":"attain a way of life 指達成或獲得某種生活模式。"},{"en":"A person may move to a smaller town to attain a slower way of life.","zh":"一個人可能搬到小鎮，以達到較慢節奏的生活方式。"},{"en":"If work hours are too long, it is hard to attain a balanced way of life.","zh":"如果工作時間太長，就難以達到平衡的生活方式。"},{"en":"The phrase suggests effort towards a desired lifestyle.","zh":"這個片語暗示為理想生活方式作出努力。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":18},{"front":"family-oriented","meaning":"以家庭為本的","examples":[{"en":"Rural life was seen as moral and family-oriented.","zh":"鄉郊生活被視為道德且以家庭為本。"},{"en":"Family-oriented means centred on family needs, values, and relationships.","zh":"family-oriented 指以家庭需要、價值和關係為中心。"},{"en":"A family-oriented workplace allows parents to leave early for childcare.","zh":"以家庭為本的工作場所容許父母提早離開照顧孩子。"},{"en":"If a community is family-oriented, schools and safe parks may be priorities.","zh":"如果社區以家庭為本，學校和安全公園可能是優先事項。"},{"en":"The phrase suggests that family life is highly valued.","zh":"這個片語暗示家庭生活受到高度重視。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":18},{"front":"in opposition to","meaning":"與……相對","examples":[{"en":"Rural life was praised in opposition to the atmosphere of cities.","zh":"鄉郊生活被讚揚，與城市氣氛相對。"},{"en":"In opposition to means against or in contrast with something.","zh":"in opposition to 指反對某事或與某事形成對比。"},{"en":"Some parents support outdoor play in opposition to too much screen time.","zh":"有些家長支持戶外玩耍，與過多屏幕時間相對。"},{"en":"If reformers praised villages in opposition to cities, they saw cities as harmful.","zh":"如果改革者讚揚村莊而與城市相對，他們便視城市為有害。"},{"en":"The phrase shows disagreement or contrast.","zh":"這個片語顯示反對或對比。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":18},{"front":"male-dominated atmosphere","meaning":"男性主導的氣氛","examples":[{"en":"Cities were described as having a single male-dominated atmosphere.","zh":"城市被描述為具有單身男性主導的氣氛。"},{"en":"A male-dominated atmosphere is an environment where men have most power or presence.","zh":"male-dominated atmosphere 是男性擁有大部分權力或佔多數的環境。"},{"en":"A workplace may feel male-dominated if most leaders and workers are men.","zh":"如果多數領導和員工都是男性，工作場所可能感覺男性主導。"},{"en":"If a city attracts many single male workers, social reformers may worry about family life.","zh":"如果城市吸引許多單身男工，社會改革者可能擔心家庭生活。"},{"en":"The phrase describes social imbalance in a place.","zh":"這個片語描述一個地方的社會不平衡。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":18},{"front":"play an important part in","meaning":"在……中扮演重要角色","examples":[{"en":"Agriculture played an important part in the Canadian economy.","zh":"農業在加拿大經濟中扮演重要角色。"},{"en":"Play an important part in means have a significant role in something.","zh":"play an important part in 指在某事中具有重要作用。"},{"en":"Parents play an important part in children’s reading habits.","zh":"父母在孩子閱讀習慣中扮演重要角色。"},{"en":"If transport plays an important part in trade, poor roads can harm business.","zh":"如果交通在貿易中扮演重要角色，道路差會傷害商業。"},{"en":"The phrase highlights contribution and influence.","zh":"這個片語強調貢獻和影響。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":18},{"front":"workforce","meaning":"勞動人口","examples":[{"en":"One-third of the workforce worked on farms in 1891.","zh":"1891年，三分之一的勞動人口在農場工作。"},{"en":"Workforce means all the people available or employed to work in an economy or organisation.","zh":"workforce 指一個經濟體或組織中可工作或已受僱的所有人。"},{"en":"A hospital’s workforce includes doctors, nurses, cleaners, and administrators.","zh":"醫院的勞動人口包括醫生、護士、清潔工和行政人員。"},{"en":"If a large share of the workforce farms, agriculture strongly affects the economy.","zh":"如果大比例勞動人口從事農業，農業會強烈影響經濟。"},{"en":"The word focuses on workers as a group.","zh":"這個詞把工人視作一個群體。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":18},{"front":"work on farms","meaning":"在農場工作","examples":[{"en":"One-third of the workforce worked on farms.","zh":"三分之一的勞動人口在農場工作。"},{"en":"Work on farms means do labour connected with crops, animals, or farm maintenance.","zh":"work on farms 指從事與作物、動物或農場維護有關的勞動。"},{"en":"People who work on farms may plant, harvest, feed animals, or repair equipment.","zh":"在農場工作的人可能種植、收割、餵動物或維修設備。"},{"en":"If many people work on farms, weather and crop prices affect many families.","zh":"如果許多人在農場工作，天氣和作物價格會影響許多家庭。"},{"en":"The phrase refers to agricultural work, not office work.","zh":"這個片語指農業工作，而不是辦公室工作。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":18},{"front":"present attractions to","meaning":"向……展示吸引力","examples":[{"en":"The Canadian government presented Canada’s attractions to overseas migrants.","zh":"加拿大政府向海外移民展示加拿大的吸引力。"},{"en":"Present attractions to means show appealing features to a target group.","zh":"present attractions to 指向目標群體展示有吸引力的特點。"},{"en":"A university may present its attractions to international students at a fair.","zh":"大學可能在展覽中向國際學生展示其吸引力。"},{"en":"If a country presents attractions to migrants, it may highlight jobs and land.","zh":"如果一個國家向移民展示吸引力，它可能強調工作和土地。"},{"en":"The phrase is about promotion and persuasion.","zh":"這個片語與宣傳和說服有關。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":19},{"front":"potential overseas migrants","meaning":"潛在海外移民","examples":[{"en":"The government tried to attract potential overseas migrants.","zh":"政府試圖吸引潛在海外移民。"},{"en":"Potential overseas migrants are people abroad who may move to another country.","zh":"潛在海外移民是在海外、可能遷往另一國的人。"},{"en":"Potential overseas migrants may compare land, jobs, travel costs, and family safety.","zh":"潛在海外移民可能比較土地、工作、旅費和家庭安全。"},{"en":"If advertising is persuasive, potential overseas migrants may apply to move.","zh":"如果宣傳有說服力，潛在海外移民可能申請遷移。"},{"en":"The phrase refers to possible migrants, not people who have already arrived.","zh":"這個片語指可能移民的人，而不是已到達的人。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":19},{"front":"in several ways","meaning":"以幾種方式","examples":[{"en":"The government advertised Canada in several ways.","zh":"政府以幾種方式宣傳加拿大。"},{"en":"In several ways means through more than one method.","zh":"in several ways 指透過不止一種方法。"},{"en":"A teacher can explain a grammar point in several ways.","zh":"老師可以以幾種方式解釋一個文法點。"},{"en":"If a campaign works in several ways, it may reach more people.","zh":"如果宣傳活動以幾種方式運作，它可能接觸更多人。"},{"en":"The phrase prepares readers for a list of methods.","zh":"這個片語為列出方法作準備。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":19},{"front":"free or cheap land","meaning":"免費或廉價土地","examples":[{"en":"The government offered free or cheap land to potential agriculturists.","zh":"政府向潛在農業移民提供免費或廉價土地。"},{"en":"Free or cheap land means land available at no cost or low cost.","zh":"free or cheap land 指免費或低成本取得的土地。"},{"en":"Free or cheap land can attract young families who cannot buy expensive farms.","zh":"免費或廉價土地可以吸引買不起昂貴農場的年輕家庭。"},{"en":"If free or cheap land is offered, settlement may increase quickly.","zh":"如果提供免費或廉價土地，定居可能迅速增加。"},{"en":"The phrase highlights economic attraction.","zh":"這個片語強調經濟吸引力。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":19},{"front":"potential agriculturists","meaning":"潛在農業移民","examples":[{"en":"Potential agriculturists were offered land in Canada.","zh":"潛在農業移民獲提供加拿大土地。"},{"en":"Potential agriculturists are people who may become farmers or agricultural workers.","zh":"potential agriculturists 是可能成為農民或農業工作者的人。"},{"en":"Potential agriculturists may look for soil, water, tools, and markets before moving.","zh":"潛在農業移民遷移前可能尋找土壤、水源、工具和市場。"},{"en":"If potential agriculturists receive land, they may start farming communities.","zh":"如果潛在農業移民獲得土地，他們可能建立農業社區。"},{"en":"The phrase refers to possible future farmers.","zh":"這個片語指可能成為未來農民的人。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":19},{"front":"establish agents","meaning":"設立代理人","examples":[{"en":"The government established agents to attract emigrants overseas.","zh":"政府設立代理人，以吸引海外移民。"},{"en":"Establish agents means appoint or set up representatives to do a task.","zh":"establish agents 指委任或設立代表去完成任務。"},{"en":"A company may establish agents in other cities to sell its products.","zh":"公司可能在其他城市設立代理人銷售產品。"},{"en":"If a government establishes agents abroad, it can promote migration more directly.","zh":"如果政府在海外設立代理人，它可以更直接推廣移民。"},{"en":"The phrase focuses on creating a network of representatives.","zh":"這個片語集中於建立代表網絡。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":19},{"front":"agencies","meaning":"代理機構","examples":[{"en":"Agencies were established to attract emigrants overseas.","zh":"代理機構被設立以吸引海外移民。"},{"en":"Agencies are organisations or offices that provide a service or carry out work for someone.","zh":"agencies 是為他人提供服務或執行工作的組織或辦事處。"},{"en":"Travel agencies help people arrange tickets and hotels.","zh":"旅行社幫助人們安排機票和酒店。"},{"en":"If migration agencies open abroad, they can answer questions from potential migrants.","zh":"如果移民代理機構在海外開設，它們可以回答潛在移民問題。"},{"en":"The word can refer to public or private organisations.","zh":"這個詞可以指公共或私人組織。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":19},{"front":"for the purpose of","meaning":"為了……的目的","examples":[{"en":"The government used agencies for the purpose of attracting emigrants.","zh":"政府使用代理機構，為了吸引移民的目的。"},{"en":"For the purpose of means in order to achieve a particular aim.","zh":"for the purpose of 指為了達成某特定目的。"},{"en":"Students visit the museum for the purpose of learning local history.","zh":"學生參觀博物館，為了學習本地歷史的目的。"},{"en":"If land is bought for the purpose of building homes, planning rules matter.","zh":"如果購買土地是為了建屋的目的，規劃規則就很重要。"},{"en":"The phrase is formal and clearly states intention.","zh":"這個片語較正式，清楚表明意圖。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":19},{"front":"attract emigrants overseas","meaning":"吸引海外移民","examples":[{"en":"Agents were used to attract emigrants overseas.","zh":"代理人被用來吸引海外移民。"},{"en":"Attract emigrants overseas means encourage people abroad to leave their country and settle elsewhere.","zh":"attract emigrants overseas 指鼓勵海外人士離開本國並到其他地方定居。"},{"en":"Posters can attract emigrants overseas by promising land and work.","zh":"海報可以透過承諾土地和工作來吸引海外移民。"},{"en":"If letters are positive, they may attract emigrants overseas more strongly than official ads.","zh":"如果信件內容正面，它們可能比官方廣告更能吸引海外移民。"},{"en":"The phrase focuses on recruitment outside the country.","zh":"這個片語集中於在國外招徠移民。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":19},{"front":"assisted-passage schemes","meaning":"資助旅程計劃","examples":[{"en":"Assisted-passage schemes attracted some immigrants to Canada.","zh":"資助旅程計劃吸引了一些移民到加拿大。"},{"en":"Assisted-passage schemes are programmes that help migrants pay for travel.","zh":"assisted-passage schemes 是幫助移民支付旅費的計劃。"},{"en":"A poor family may move abroad if an assisted-passage scheme covers part of the fare.","zh":"如果資助旅程計劃支付部分船費，貧困家庭可能移居海外。"},{"en":"If travel costs fall, assisted-passage schemes can increase migration.","zh":"如果旅費下降，資助旅程計劃可以增加移民。"},{"en":"The phrase connects financial help with movement across distance.","zh":"這個片語把財政幫助與長距離移動連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":19},{"front":"bonuses and commissions","meaning":"獎金和佣金","examples":[{"en":"Bonuses and commissions encouraged agents and settlers.","zh":"獎金和佣金鼓勵代理人和定居者。"},{"en":"Bonuses and commissions are extra payments given as rewards for results or sales.","zh":"bonuses and commissions 是因成果或銷售而給予的額外付款。"},{"en":"Sales staff may receive bonuses and commissions when they bring in customers.","zh":"銷售人員帶來顧客時可能獲得獎金和佣金。"},{"en":"If agents earn bonuses and commissions, they may work harder to recruit migrants.","zh":"如果代理人賺取獎金和佣金，他們可能更努力招募移民。"},{"en":"The phrase suggests financial incentives.","zh":"這個片語暗示財政誘因。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":20},{"front":"pamphlets","meaning":"小冊子","examples":[{"en":"Pamphlets were used to attract immigrants to Canada.","zh":"小冊子被用來吸引移民到加拿大。"},{"en":"Pamphlets are small printed booklets that give information or advertise something.","zh":"pamphlets 是提供資料或宣傳某事的小型印刷冊子。"},{"en":"A clinic may give patients pamphlets about healthy eating.","zh":"診所可能給病人關於健康飲食的小冊子。"},{"en":"If pamphlets describe cheap land clearly, migrants may become interested.","zh":"如果小冊子清楚描述廉價土地，移民可能產生興趣。"},{"en":"The word suggests simple printed promotion.","zh":"這個詞暗示簡單的印刷宣傳。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":20},{"front":"the most influential form of","meaning":"最有影響力的形式","examples":[{"en":"Letters home were the most influential form of attracting migrants.","zh":"寫回家鄉的信是吸引移民最有影響力的形式。"},{"en":"The most influential form of means the method with the greatest effect.","zh":"the most influential form of 指效果最大的方式。"},{"en":"Personal recommendation may be the most influential form of advertising for a small restaurant.","zh":"對小餐廳而言，個人推薦可能是最有影響力的宣傳形式。"},{"en":"If migrants trust relatives, letters may become the most influential form of persuasion.","zh":"如果移民信任親戚，信件可能成為最有影響力的說服形式。"},{"en":"The phrase compares methods by their power to affect decisions.","zh":"這個片語按影響決定的力量比較方法。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":20},{"front":"letters home","meaning":"寫回家鄉的信","examples":[{"en":"Letters home encouraged others to come to Canada.","zh":"寫回家鄉的信鼓勵其他人來加拿大。"},{"en":"Letters home are letters sent by migrants to family or friends in their original home country.","zh":"letters home 是移民寄給原居地家人或朋友的信。"},{"en":"Letters home may describe work, weather, wages, and daily life.","zh":"寫回家鄉的信可能描述工作、天氣、工資和日常生活。"},{"en":"If letters home sound hopeful, relatives may decide to migrate too.","zh":"如果寫回家鄉的信聽起來充滿希望，親戚也可能決定移民。"},{"en":"The phrase shows personal communication across distance.","zh":"這個片語顯示跨距離的私人溝通。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":20},{"front":"trusted friends and relatives","meaning":"可信任的朋友和親戚","examples":[{"en":"Letters from trusted friends and relatives influenced potential migrants.","zh":"來自可信任的朋友和親戚的信影響潛在移民。"},{"en":"Trusted friends and relatives are people whose words are believed because of close personal relationships.","zh":"trusted friends and relatives 是因親密個人關係而說話可信的人。"},{"en":"A student may choose a tutor after advice from trusted friends and relatives.","zh":"學生可能因可信任的朋友和親戚建議而選擇導師。"},{"en":"If trusted friends and relatives praise a country, migration seems less risky.","zh":"如果可信任的朋友和親戚稱讚一個國家，移民看起來較少風險。"},{"en":"The phrase highlights personal trust.","zh":"這個片語強調個人信任。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":20},{"front":"contain exaggerations of","meaning":"包含對……的誇張描述","examples":[{"en":"The letters often contained exaggerations of the new world.","zh":"這些信常包含對新世界的誇張描述。"},{"en":"Contain exaggerations of means include descriptions that make something seem better, bigger, or more dramatic than it is.","zh":"contain exaggerations of 指包含令某事看起來更好、更大或更戲劇化的描述。"},{"en":"A travel blog may contain exaggerations of how easy a trip is.","zh":"旅遊網誌可能包含對旅程有多容易的誇張描述。"},{"en":"If letters contain exaggerations of success, readers may form unrealistic hopes.","zh":"如果信件包含對成功的誇張描述，讀者可能形成不切實際的希望。"},{"en":"The phrase warns that information may not be fully accurate.","zh":"這個片語提醒資料可能不完全準確。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":20},{"front":"the wonder of the new world","meaning":"新世界的奇妙之處","examples":[{"en":"Letters described the wonder of the new world.","zh":"信件描述新世界的奇妙之處。"},{"en":"The wonder of the new world means the exciting and impressive qualities of a new land.","zh":"the wonder of the new world 指新土地令人興奮和印象深刻的特質。"},{"en":"Migrants may write about the wonder of the new world when everything feels fresh.","zh":"當一切都感覺新鮮，移民可能寫下新世界的奇妙之處。"},{"en":"If stories focus only on wonder, difficulties may be hidden.","zh":"如果故事只集中於奇妙之處，困難可能被隱藏。"},{"en":"The phrase carries a hopeful and slightly romantic tone.","zh":"這個片語帶有希望和略為浪漫的語氣。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":20},{"front":"migrant workers","meaning":"移民工人","examples":[{"en":"Migrant workers wrote letters home from Canada.","zh":"移民工人從加拿大寫信回家鄉。"},{"en":"Migrant workers are people who move to another place to work, often temporarily.","zh":"migrant workers 是為工作而遷往另一地方的人，通常可能是暫時的。"},{"en":"Migrant workers may send money home to support their families.","zh":"移民工人可能寄錢回家支持家庭。"},{"en":"If migrant workers face poor conditions, labour laws become important.","zh":"如果移民工人面對惡劣環境，勞工法律就變得重要。"},{"en":"The phrase focuses on work-related movement.","zh":"這個片語集中於與工作有關的遷移。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":20},{"front":"settlers already in Canada","meaning":"已在加拿大的定居者","examples":[{"en":"Settlers already in Canada wrote letters to friends and relatives.","zh":"已在加拿大的定居者寫信給朋友和親戚。"},{"en":"Settlers already in Canada are people who had moved there before others considered coming.","zh":"settlers already in Canada 是在其他人考慮前來之前已遷到加拿大的人。"},{"en":"Settlers already in Canada could describe real wages, land, and weather.","zh":"已在加拿大的定居者可以描述真實工資、土地和天氣。"},{"en":"If settlers already in Canada sound successful, relatives may follow them.","zh":"如果已在加拿大的定居者聽起來成功，親戚可能跟隨他們。"},{"en":"The phrase contrasts earlier arrivals with potential migrants abroad.","zh":"這個片語把較早到達者與海外潛在移民作對比。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":20},{"front":"disappoint or worry","meaning":"令……失望或擔心","examples":[{"en":"Settlers did not want to disappoint or worry their families.","zh":"定居者不想令家人失望或擔心。"},{"en":"Disappoint or worry means make people feel sad, let down, or anxious.","zh":"disappoint or worry 指令人感到失落、失望或焦慮。"},{"en":"A student may hide bad marks because they do not want to disappoint or worry parents.","zh":"學生可能隱瞞差成績，因為不想令父母失望或擔心。"},{"en":"If migrants struggle abroad, they may avoid writing honestly to avoid worry.","zh":"如果移民在海外吃力，他們可能避免如實寫信以免家人擔心。"},{"en":"The phrase explains an emotional reason for hiding difficulties.","zh":"這個片語解釋隱藏困難的情感原因。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":20},{"front":"embellished tales","meaning":"經修飾誇大的故事","examples":[{"en":"Embellished tales of good fortune encouraged migration.","zh":"關於好運的經修飾誇大故事鼓勵移民。"},{"en":"Embellished tales are stories made more attractive or dramatic by adding extra details.","zh":"embellished tales 是加入額外細節而變得更吸引或戲劇化的故事。"},{"en":"A traveller may tell embellished tales about a holiday to impress friends.","zh":"旅客可能講述經修飾誇大的假期故事來打動朋友。"},{"en":"If embellished tales spread, people may make decisions based on unrealistic hopes.","zh":"如果經修飾誇大的故事傳開，人們可能基於不切實際希望作決定。"},{"en":"The phrase suggests the story is partly polished or exaggerated.","zh":"這個片語暗示故事經過美化或誇張。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":21},{"front":"good fortune","meaning":"好運；成功境遇","examples":[{"en":"Letters often told embellished tales of good fortune.","zh":"信件常講述關於好運的經修飾誇大故事。"},{"en":"Good fortune means luck, success, or favourable circumstances.","zh":"good fortune 指好運、成功或有利情況。"},{"en":"A family may celebrate good fortune after finding stable work.","zh":"家庭找到穩定工作後可能慶祝好運。"},{"en":"If letters describe only good fortune, hardships may be hidden.","zh":"如果信件只描述好運，艱難可能被隱藏。"},{"en":"The phrase has a positive and hopeful meaning.","zh":"這個片語有正面和充滿希望的意思。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":21},{"front":"succeed in encouraging","meaning":"成功鼓勵","examples":[{"en":"Letters often succeeded in encouraging others to come.","zh":"信件常成功鼓勵其他人前來。"},{"en":"Succeed in encouraging means manage to persuade or motivate people to do something.","zh":"succeed in encouraging 指成功說服或推動人們做某事。"},{"en":"A teacher may succeed in encouraging shy students to speak.","zh":"老師可能成功鼓勵害羞學生發言。"},{"en":"If stories sound hopeful, they can succeed in encouraging relatives to migrate.","zh":"如果故事聽起來有希望，它們可以成功鼓勵親戚移民。"},{"en":"The phrase shows that the encouragement actually works.","zh":"這個片語顯示鼓勵確實有效。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":21},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Students choose the correct heading for each paragraph.","zh":"學生為每段選出正確標題。"},{"en":"Choose the correct heading means select the title that best matches the paragraph’s main idea.","zh":"choose the correct heading 指選出最符合段落主旨的標題。"},{"en":"In reading tests, students should choose the correct heading after understanding the whole paragraph.","zh":"在閱讀測驗中，學生應理解整段後才選出正確標題。"},{"en":"If students focus only on one detail, they may not choose the correct heading.","zh":"如果學生只看一個細節，他們可能無法選出正確標題。"},{"en":"The phrase is common in IELTS-style reading tasks.","zh":"這個片語常見於雅思式閱讀題。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":21},{"front":"list of headings","meaning":"標題列表","examples":[{"en":"The question provides a list of headings.","zh":"題目提供一個標題列表。"},{"en":"A list of headings is a set of possible titles for paragraphs or sections.","zh":"list of headings 是一組可用作段落或部分標題的選項。"},{"en":"Students should compare each paragraph with the list of headings carefully.","zh":"學生應仔細把每段與標題列表比較。"},{"en":"If two headings look similar, the main idea decides the answer.","zh":"如果兩個標題看似相似，主旨決定答案。"},{"en":"The phrase refers to answer options in a reading task.","zh":"這個片語指閱讀題中的答案選項。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":21},{"front":"not all would stay","meaning":"並非所有人都會留下","examples":[{"en":"The heading suggests that not all settlers would stay in Canada forever.","zh":"該標題暗示並非所有定居者都會永遠留在加拿大。"},{"en":"Not all would stay means some people would leave instead of remaining.","zh":"not all would stay 指有些人會離開，而不是留下。"},{"en":"In a new job, not all would stay if the pay was low.","zh":"在新工作中，如果薪酬低，並非所有人都會留下。"},{"en":"If settlement was difficult, not all would stay permanently.","zh":"如果定居很困難，並非所有人都會永久留下。"},{"en":"The phrase warns against assuming everyone remained.","zh":"這個片語提醒不要假設人人都留下。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":21},{"front":"government safeguards","meaning":"政府保障措施","examples":[{"en":"The heading refers to government safeguards in the West.","zh":"該標題指西部的政府保障措施。"},{"en":"Government safeguards are protective measures taken by the government.","zh":"government safeguards 是政府採取的保護措施。"},{"en":"Food safety laws are government safeguards for consumers.","zh":"食物安全法是保護消費者的政府保障措施。"},{"en":"If government safeguards are weak, settlers may feel unsafe.","zh":"如果政府保障措施薄弱，定居者可能感到不安全。"},{"en":"The phrase suggests official protection against risk.","zh":"這個片語暗示針對風險的官方保護。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":21},{"front":"building new infrastructure","meaning":"建設新基礎設施","examples":[{"en":"The heading refers to building new infrastructure in western Canada.","zh":"該標題指在加拿大西部建設新基礎設施。"},{"en":"Building new infrastructure means constructing basic systems such as roads, railways, water supply, and public facilities.","zh":"building new infrastructure 指建設道路、鐵路、供水和公共設施等基本系統。"},{"en":"A town may focus on building new infrastructure before many families arrive.","zh":"城鎮可能在大量家庭到達前集中建設新基礎設施。"},{"en":"If new infrastructure is built, trade and settlement become easier.","zh":"如果新基礎設施建成，貿易和定居會更容易。"},{"en":"The phrase focuses on physical systems that support society.","zh":"這個片語集中於支持社會的實體系統。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":21},{"front":"establishment of dominance","meaning":"支配地位的建立","examples":[{"en":"The passage describes the establishment of British-Ontarian dominance.","zh":"文章描述英國—安大略式支配地位的建立。"},{"en":"Establishment of dominance means the process by which one group becomes the most powerful or influential.","zh":"establishment of dominance 指某群體成為最有權力或最有影響力的過程。"},{"en":"A large company’s establishment of dominance can push smaller shops aside.","zh":"大公司的支配地位建立可以排擠小店。"},{"en":"If one culture gains dominance, public life may reflect its values.","zh":"如果一種文化取得支配地位，公共生活可能反映其價值。"},{"en":"The phrase describes a process of gaining control.","zh":"這個片語描述取得控制的過程。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":21},{"front":"ethnic and linguistic composition","meaning":"種族和語言構成","examples":[{"en":"The question includes a heading about ethnic and linguistic composition.","zh":"題目包括一個關於種族和語言構成的標題。"},{"en":"Ethnic and linguistic composition means the mix of ethnic groups and languages in a population.","zh":"ethnic and linguistic composition 指人口中的種族群體和語言組合。"},{"en":"A school’s ethnic and linguistic composition may change after immigration increases.","zh":"移民增加後，學校的種族和語言構成可能改變。"},{"en":"If a city’s ethnic and linguistic composition changes, services may need translation support.","zh":"如果城市的種族和語言構成改變，服務可能需要翻譯支援。"},{"en":"The phrase is useful for describing population diversity.","zh":"這個片語有助描述人口多樣性。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":21},{"front":"pursuing a pure life","meaning":"追求純樸生活","examples":[{"en":"Some reformers promoted rural living as pursuing a pure life.","zh":"有些改革者把鄉郊生活推廣為追求純樸生活。"},{"en":"Pursuing a pure life means trying to live in a simple, healthy, and morally good way.","zh":"pursuing a pure life 指試圖過簡單、健康而道德良好的生活。"},{"en":"A person may move to the countryside while pursuing a pure life away from city stress.","zh":"一個人可能為了追求遠離城市壓力的純樸生活而搬到鄉郊。"},{"en":"If reformers idealise farming, they may describe it as pursuing a pure life.","zh":"如果改革者理想化農業，他們可能把它描述為追求純樸生活。"},{"en":"The phrase reflects an ideal, not always reality.","zh":"這個片語反映理想，而不一定是現實。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":22},{"front":"the demand for western immigration","meaning":"對西部移民的需求","examples":[{"en":"The passage explains the demand for western immigration.","zh":"文章解釋對西部移民的需求。"},{"en":"The demand for western immigration means the need or desire to bring settlers into the West.","zh":"the demand for western immigration 指把定居者帶到西部的需要或願望。"},{"en":"Land shortages in the East could create demand for western immigration.","zh":"東部土地短缺可能造成對西部移民的需求。"},{"en":"If politicians want more farms and border security, demand for western immigration may rise.","zh":"如果政客希望更多農場和邊界安全，對西部移民的需求可能上升。"},{"en":"The phrase explains why migration was wanted.","zh":"這個片語解釋為何移民被需要。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":22},{"front":"early major urban development","meaning":"早期主要城市發展","examples":[{"en":"Winnipeg represents early major urban development in the West.","zh":"溫尼伯代表西部早期主要城市發展。"},{"en":"Early major urban development means the first significant growth of large towns or cities.","zh":"early major urban development 指大型城鎮或城市最早的重要增長。"},{"en":"A railway town may show early major urban development when stations, houses, and factories appear.","zh":"當車站、房屋和工廠出現，鐵路城鎮可能顯示早期主要城市發展。"},{"en":"If early major urban development succeeds, a region may gain a central city.","zh":"如果早期主要城市發展成功，一個地區可能取得中心城市。"},{"en":"The phrase describes city growth at an early stage.","zh":"這個片語描述早期階段的城市增長。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":22},{"front":"attractive urban environment","meaning":"有吸引力的城市環境","examples":[{"en":"The heading refers to an attractive urban environment.","zh":"該標題指有吸引力的城市環境。"},{"en":"An attractive urban environment is a city setting that people find pleasant, convenient, or desirable.","zh":"attractive urban environment 是令人覺得舒適、方便或值得居住的城市環境。"},{"en":"Parks, clean streets, jobs, and transport can create an attractive urban environment.","zh":"公園、清潔街道、工作和交通可以創造有吸引力的城市環境。"},{"en":"If an urban environment is attractive, families and businesses may move there.","zh":"如果城市環境有吸引力，家庭和企業可能搬到那裡。"},{"en":"The phrase focuses on the appeal of city life.","zh":"這個片語集中於城市生活的吸引力。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":22},{"front":"advertising of Western Canada","meaning":"加拿大西部宣傳","examples":[{"en":"The government used several methods for advertising Western Canada.","zh":"政府使用幾種方法進行加拿大西部宣傳。"},{"en":"Advertising of Western Canada means promoting the western region to attract settlers or migrants.","zh":"advertising of Western Canada 指宣傳西部地區以吸引定居者或移民。"},{"en":"Pamphlets and agents can be used for advertising Western Canada abroad.","zh":"小冊子和代理人可用於在海外進行加拿大西部宣傳。"},{"en":"If advertising of Western Canada is positive, it may hide difficulties of settlement.","zh":"如果加拿大西部宣傳過於正面，它可能隱藏定居困難。"},{"en":"The phrase describes organised promotion of a region.","zh":"這個片語描述對一個地區的有組織宣傳。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":22},{"front":"complete the following summary","meaning":"完成以下摘要","examples":[{"en":"Students complete the following summary using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"Complete the following summary means fill missing information in a short overview.","zh":"complete the following summary 指在一段簡短概述中填上缺失資料。"},{"en":"In a reading test, students complete the following summary by locating key words.","zh":"在閱讀測驗中，學生透過定位關鍵字完成以下摘要。"},{"en":"If students misunderstand the paragraph, they may choose the wrong summary word.","zh":"如果學生誤解段落，他們可能選錯摘要字詞。"},{"en":"The phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":22},{"front":"no more than two words","meaning":"不超過兩個字","examples":[{"en":"Students should use no more than two words from the passage.","zh":"學生應使用文章中不超過兩個字。"},{"en":"No more than two words means one word or two words only, not three or more.","zh":"no more than two words 指只能用一個字或兩個字，不能三個或以上。"},{"en":"If the answer is “free land”, it follows the no more than two words rule.","zh":"如果答案是 free land，它符合不超過兩個字的規則。"},{"en":"If students write three words, the answer may be marked wrong even if the idea is correct.","zh":"如果學生寫三個字，即使意思正確，也可能被判錯。"},{"en":"The phrase is a strict word-limit instruction.","zh":"這個片語是嚴格的字數限制指示。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":22},{"front":"from the Reading Passage","meaning":"從閱讀文章中","examples":[{"en":"The answers must come from the Reading Passage.","zh":"答案必須從閱讀文章中得出。"},{"en":"From the Reading Passage means taken directly from the text given in the exam.","zh":"from the Reading Passage 指直接取自考試提供的文本。"},{"en":"Students should not use outside knowledge if answers must come from the Reading Passage.","zh":"如果答案必須從閱讀文章中得出，學生不應使用外部知識。"},{"en":"If a word is not from the Reading Passage, it may not be accepted.","zh":"如果某字不是來自閱讀文章，可能不被接受。"},{"en":"The phrase tells students where evidence and wording must come from.","zh":"這個片語告訴學生證據和用字必須來自哪裡。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":22},{"front":"as agricultural land reached capacity","meaning":"隨着農地達到容量上限","examples":[{"en":"As agricultural land reached capacity, western settlement became attractive.","zh":"隨着農地達到容量上限，西部定居變得有吸引力。"},{"en":"As agricultural land reached capacity means when farmland became fully used or unavailable.","zh":"as agricultural land reached capacity 指當農地被完全使用或不再可用時。"},{"en":"As classroom space reaches capacity, schools may need new buildings.","zh":"隨着課室空間達到容量上限，學校可能需要新建築。"},{"en":"If agricultural land reaches capacity, families may look for farms elsewhere.","zh":"如果農地達到容量上限，家庭可能到別處尋找農場。"},{"en":"The phrase explains the timing and reason for migration pressure.","zh":"這個片語解釋移民壓力出現的時間和原因。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":22},{"front":"descendants of eastern farmers","meaning":"東部農民的後代","examples":[{"en":"The West could provide land for the descendants of eastern farmers.","zh":"西部可以為東部農民的後代提供土地。"},{"en":"Descendants of eastern farmers are later generations or children of farmers from the East.","zh":"descendants of eastern farmers 指東部農民的後代或子女。"},{"en":"Descendants of eastern farmers may need land when family farms are already divided.","zh":"當家庭農場已被分割，東部農民的後代可能需要土地。"},{"en":"If descendants cannot inherit enough land, they may move west.","zh":"如果後代不能繼承足夠土地，他們可能向西遷移。"},{"en":"The phrase links family history with land pressure.","zh":"這個片語把家族歷史與土地壓力連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":22},{"front":"politicians argued that","meaning":"政客主張","examples":[{"en":"Politicians argued that the West could increase agricultural output.","zh":"政客主張西部可以增加農業產量。"},{"en":"Politicians argued that means political leaders claimed or reasoned that something was true.","zh":"politicians argued that 指政治領袖聲稱或推論某事為真。"},{"en":"Politicians argued that new roads would help rural families.","zh":"政客主張新道路會幫助鄉郊家庭。"},{"en":"If politicians argued that settlement would protect territory, they used security as a reason.","zh":"如果政客主張定居會保護領土，他們便以安全作理由。"},{"en":"The phrase introduces a political claim.","zh":"這個片語引出政治主張。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":23},{"front":"increase Canada’s output","meaning":"增加加拿大的產量","examples":[{"en":"The West could increase Canada’s agricultural output.","zh":"西部可以增加加拿大的農業產量。"},{"en":"Increase Canada’s output means raise the amount Canada produces.","zh":"increase Canada’s output 指提高加拿大的生產總量。"},{"en":"New factories can increase a country’s output of manufactured goods.","zh":"新工廠可以增加一個國家的製成品產量。"},{"en":"If western farms produce more wheat, they increase Canada’s output.","zh":"如果西部農場生產更多小麥，它們便增加加拿大的產量。"},{"en":"The phrase focuses on national production.","zh":"這個片語集中於國家生產。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":23},{"front":"production consumed in the East","meaning":"在東部消耗的生產","examples":[{"en":"Wheat production in the West served markets in the East.","zh":"西部小麥生產供應東部市場。"},{"en":"Production consumed in the East means goods made elsewhere but used or eaten in the eastern region.","zh":"production consumed in the East 指在其他地方生產但在東部使用或食用的貨品。"},{"en":"Food grown in rural areas may become production consumed in the city.","zh":"鄉郊種植的食物可能成為城市消耗的生產。"},{"en":"If western grain is sent east, it becomes production consumed in the East.","zh":"如果西部穀物送往東部，它就成為在東部消耗的生產。"},{"en":"The phrase connects place of production with place of use.","zh":"這個片語把生產地與使用地連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":23},{"front":"prepare for settlement","meaning":"為定居作準備","examples":[{"en":"The federal government began preparing for settlement.","zh":"聯邦政府開始為定居作準備。"},{"en":"Prepare for settlement means make land, laws, transport, or security ready for settlers.","zh":"prepare for settlement 指使土地、法律、交通或安全安排準備好迎接定居者。"},{"en":"A town may prepare for settlement by building wells and roads.","zh":"城鎮可能透過建水井和道路為定居作準備。"},{"en":"If officials prepare for settlement well, newcomers can arrive more safely.","zh":"如果官員妥善為定居作準備，新來者可以更安全抵達。"},{"en":"The phrase describes work done before people settle.","zh":"這個片語描述人們定居前完成的工作。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":23},{"front":"private company","meaning":"私營公司","examples":[{"en":"The government purchased land from a private company.","zh":"政府從一間私營公司購買土地。"},{"en":"A private company is a business owned by individuals or shareholders, not the state.","zh":"私營公司是由個人或股東擁有，而非國家擁有的企業。"},{"en":"A city may buy buses from a private company.","zh":"城市可能向私營公司購買巴士。"},{"en":"If a private company owns land, the government may need to purchase it legally.","zh":"如果私營公司擁有土地，政府可能需要依法購買。"},{"en":"The phrase contrasts with a government department or public agency.","zh":"這個片語與政府部門或公共機構形成對比。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":23},{"front":"legally offer plots","meaning":"依法提供地段","examples":[{"en":"The government legally offered plots to qualified settlers.","zh":"政府依法向合資格定居者提供地段。"},{"en":"Legally offer plots means provide pieces of land through official law or rules.","zh":"legally offer plots 指透過官方法律或規則提供土地地段。"},{"en":"A council may legally offer plots for community gardens.","zh":"議會可能依法提供地段作社區花園。"},{"en":"If plots are legally offered, applicants must follow official conditions.","zh":"如果地段依法提供，申請者必須遵守官方條件。"},{"en":"The phrase combines land distribution with legal authority.","zh":"這個片語結合土地分配和法律權力。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":23},{"front":"qualifying period","meaning":"合資格期限","examples":[{"en":"Settlers had to remain on the land for a qualifying period.","zh":"定居者必須留在土地上達到合資格期限。"},{"en":"A qualifying period is the time someone must complete before receiving a right or benefit.","zh":"qualifying period 是某人取得權利或福利前必須完成的時間。"},{"en":"A worker may need a qualifying period before getting full benefits.","zh":"工人可能需要完成合資格期限才取得全部福利。"},{"en":"If settlers leave before the qualifying period ends, they may lose the land.","zh":"如果定居者在合資格期限結束前離開，可能失去土地。"},{"en":"The phrase describes a required waiting or proving time.","zh":"這個片語描述必要的等待或證明時間。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":23},{"front":"secure the territory","meaning":"保護領土","examples":[{"en":"A mounted police force was created to secure the territory.","zh":"一支騎警部隊被成立以保護領土。"},{"en":"Secure the territory means protect and control an area of land.","zh":"secure the territory 指保護和控制一片土地。"},{"en":"Governments may secure territory by building posts and enforcing laws.","zh":"政府可能透過建立駐地和執行法律來保護領土。"},{"en":"If territory is secured, settlers and officials can operate more safely.","zh":"如果領土得到保護，定居者和官員可以更安全地活動。"},{"en":"The phrase is common in political and military history.","zh":"這個片語常見於政治和軍事歷史。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":23},{"front":"protect Canadian interests","meaning":"保護加拿大利益","examples":[{"en":"The railway helped protect Canadian interests in the West.","zh":"鐵路幫助保護加拿大在西部的利益。"},{"en":"Protect Canadian interests means defend Canada’s political, economic, or territorial goals.","zh":"protect Canadian interests 指保護加拿大的政治、經濟或領土目標。"},{"en":"A trade agreement may protect Canadian interests by supporting local industries.","zh":"貿易協議可以透過支持本地產業保護加拿大利益。"},{"en":"If a railway strengthens control of the West, it protects Canadian interests.","zh":"如果鐵路加強對西部的控制，它便保護加拿大利益。"},{"en":"The phrase is broad and often used in national policy.","zh":"這個片語範圍較廣，常用於國家政策。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":23},{"front":"transport migrants and goods","meaning":"運送移民和貨物","examples":[{"en":"The railway transported migrants and goods between West and East.","zh":"鐵路在西部和東部之間運送移民和貨物。"},{"en":"Transport migrants and goods means carry people who are moving and the products they need or sell.","zh":"transport migrants and goods 指運送正在遷移的人和他們需要或出售的產品。"},{"en":"Trains can transport migrants and goods across long distances.","zh":"火車可以長距離運送移民和貨物。"},{"en":"If transport improves, migrants and goods can move more cheaply and quickly.","zh":"如果交通改善，移民和貨物可以更便宜、更快速移動。"},{"en":"The phrase links settlement with trade.","zh":"這個片語把定居與貿易連接起來。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":23},{"front":"between West and East","meaning":"在西部和東部之間","examples":[{"en":"The railway connected movement between West and East.","zh":"鐵路連接西部和東部之間的流動。"},{"en":"Between West and East means linking the western and eastern regions.","zh":"between West and East 指連接西部和東部地區。"},{"en":"Trade between West and East can depend on reliable transport.","zh":"西部和東部之間的貿易可以依賴可靠交通。"},{"en":"If goods move between West and East, both regions may become economically connected.","zh":"如果貨物在西部和東部之間流動，兩個地區可能在經濟上連接。"},{"en":"The phrase highlights two-way regional movement.","zh":"這個片語強調雙向地區流動。"}],"source":"149 - Western Immigration of Canada.pdf","sourcePage":24}],"ielts/reading/passage-2/Practice 150":[{"front":"provide more questions than answers","meaning":"帶來的疑問多於答案","examples":[{"en":"The Antikythera Mechanism provides more questions than answers.","zh":"安提基特拉機械帶來的疑問多於答案。"},{"en":"If something provides more questions than answers, it creates more mysteries than clear explanations.","zh":"如果某事物帶來的疑問多於答案，意思是它造成更多謎團，而不是清楚解釋。"},{"en":"A strange result in a science experiment may provide more questions than answers.","zh":"科學實驗中的奇怪結果可能帶來的疑問多於答案。"},{"en":"When a witness gives unclear details, the police interview may provide more questions than answers.","zh":"當證人提供不清楚的細節，警方訪問可能帶來的疑問多於答案。"},{"en":"New evidence can be exciting even when it provides more questions than answers.","zh":"新證據即使帶來的疑問多於答案，也可以令人興奮。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":1},{"front":"the island of Antikythera","meaning":"安提基特拉島","examples":[{"en":"The island of Antikythera lies north of Crete.","zh":"安提基特拉島位於克里特島以北。"},{"en":"The island of Antikythera is a Greek island known for the ancient shipwreck found nearby.","zh":"安提基特拉島是一個希臘島嶼，因附近發現古代沉船而聞名。"},{"en":"Tourists may pass the island of Antikythera while travelling between Greek islands.","zh":"遊客在希臘島嶼之間旅行時，可能會經過安提基特拉島。"},{"en":"Because ships crossed waters near the island of Antikythera, ancient trade goods could end up there after a wreck.","zh":"因為船隻曾穿越安提基特拉島附近水域，古代貿易貨物可能在沉船後留在那裡。"},{"en":"The island of Antikythera became famous because of one extraordinary archaeological discovery.","zh":"安提基特拉島因一項非凡的考古發現而變得著名。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":1},{"front":"lie north of","meaning":"位於……以北","examples":[{"en":"Antikythera lies 18 miles north of Crete.","zh":"安提基特拉島位於克里特島以北十八英里。"},{"en":"To lie north of a place means to be located above it on a map.","zh":"「lie north of」某地，意思是在地圖上位於該地以北。"},{"en":"The village lies north of the main railway station.","zh":"那條村位於主要火車站以北。"},{"en":"If a school lies north of your home, you need to travel in that direction to reach it.","zh":"如果學校位於你家以北，你需要向那個方向前往。"},{"en":"This phrase is used to describe location, not movement.","zh":"這個短語用來描述位置，而不是移動。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":1},{"front":"where the Aegean Sea meets the Mediterranean","meaning":"愛琴海與地中海交匯之處","examples":[{"en":"The island lies where the Aegean Sea meets the Mediterranean.","zh":"該島位於愛琴海與地中海交匯之處。"},{"en":"This phrase describes a place where two seas come together.","zh":"這個短語描述兩個海域相接的地方。"},{"en":"A port built where two rivers meet may become important for trade.","zh":"建於兩條河流交匯之處的港口，可能成為重要貿易地點。"},{"en":"Where two bodies of water meet, currents and weather can become difficult to predict.","zh":"在兩片水域交匯之處，水流和天氣可能變得難以預測。"},{"en":"The phrase helps readers picture the island’s exact geographical setting.","zh":"這個短語幫助讀者想像該島的準確地理位置。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":1},{"front":"currents","meaning":"水流；洋流","examples":[{"en":"Currents near Antikythera can make shipping treacherous.","zh":"安提基特拉島附近的水流可能令航行變得危險。"},{"en":"Currents are movements of water in the sea, a river, or another body of water.","zh":"「currents」是海洋、河流或其他水體中的水流動。"},{"en":"Swimmers should be careful when strong currents pull water away from the beach.","zh":"當強水流把水拉離海灘時，游泳者應該小心。"},{"en":"Ocean currents can move ships, floating rubbish, and sea animals over long distances.","zh":"洋流可以把船隻、漂浮垃圾和海洋動物帶到遠方。"},{"en":"Even calm-looking water can be dangerous if currents are strong underneath.","zh":"即使水面看似平靜，如果下方水流強勁，仍可能危險。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":1},{"front":"make shipping treacherous","meaning":"令航行變得危險","examples":[{"en":"Currents there can make shipping treacherous.","zh":"那裡的水流可能令航行變得危險。"},{"en":"To make shipping treacherous means to make travel by ship dangerous and uncertain.","zh":"「make shipping treacherous」意思是令船隻航行變得危險和難以預測。"},{"en":"Thick fog can make shipping treacherous because captains cannot see clearly.","zh":"濃霧可能令航行變得危險，因為船長看不清楚。"},{"en":"Strong currents can make shipping treacherous and increase the risk of accidents.","zh":"強水流可以令航行變得危險，並增加意外風險。"},{"en":"Safe shipping depends on knowing which waters can become treacherous.","zh":"安全航行取決於知道哪些水域可能變得危險。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":1},{"front":"treacherous","meaning":"危險的；變幻莫測的","examples":[{"en":"The sea near Antikythera could be treacherous for ships.","zh":"安提基特拉島附近的海域對船隻可能是危險的。"},{"en":"Treacherous means dangerous because conditions can change suddenly or are hard to judge.","zh":"「treacherous」意思是危險的，因為情況可能突然改變或難以判斷。"},{"en":"A wet mountain path can be treacherous after heavy rain.","zh":"大雨後，濕滑山路可能很危險。"},{"en":"Treacherous roads can cause accidents when drivers cannot see ice clearly.","zh":"當司機看不清冰面時，危險道路可能造成意外。"},{"en":"Something treacherous may look safe at first but become dangerous quickly.","zh":"危險而變幻莫測的事物起初可能看似安全，但很快變得危險。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":1},{"front":"bound for","meaning":"前往……的","examples":[{"en":"One ship bound for ancient Rome never made it.","zh":"一艘前往古羅馬的船未能抵達。"},{"en":"Bound for a place means travelling toward that destination.","zh":"「bound for」某地，意思是正前往該目的地。"},{"en":"A train bound for London may stop at several towns along the way.","zh":"一列前往倫敦的火車可能沿途停靠幾個城鎮。"},{"en":"If a parcel is bound for another country, it must pass through customs.","zh":"如果包裹是前往另一個國家，它必須通過海關。"},{"en":"Bound for describes where something is going, not where it came from.","zh":"「bound for」描述某物正前往哪裡，而不是來自哪裡。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":1},{"front":"ancient Rome","meaning":"古羅馬","examples":[{"en":"The cargo vessel was bound for ancient Rome.","zh":"這艘貨船正前往古羅馬。"},{"en":"Ancient Rome refers to the Roman civilisation that existed thousands of years ago.","zh":"「ancient Rome」指數千年前存在的羅馬文明。"},{"en":"Students study ancient Rome to learn about law, roads, armies, and empire-building.","zh":"學生研究古羅馬，以學習法律、道路、軍隊和帝國擴張。"},{"en":"Goods from many places were brought to ancient Rome because it was rich and powerful.","zh":"來自多地的貨物被運往古羅馬，因為它富有而強大。"},{"en":"Ancient Rome is often discussed when studying European history and classical culture.","zh":"研究歐洲歷史和古典文化時，常會討論古羅馬。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":1},{"front":"never made it","meaning":"未能抵達；沒有成功到達","examples":[{"en":"The ship bound for ancient Rome never made it.","zh":"那艘前往古羅馬的船未能抵達。"},{"en":"Never made it means failed to arrive, succeed, or complete the journey.","zh":"「never made it」意思是未能抵達、成功或完成旅程。"},{"en":"I left early for the interview, but the train broke down and I never made it.","zh":"我很早出發去面試，但火車故障，所以我未能到達。"},{"en":"If a rescue team never made it to the village, people there had to wait longer for help.","zh":"如果救援隊未能到達村莊，當地人就要等更久才有幫助。"},{"en":"The phrase often suggests disappointment because the intended goal was not reached.","zh":"這個短語常帶有失望感，因為原本的目標沒有達成。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":1},{"front":"cargo vessel","meaning":"貨船","examples":[{"en":"The ship that sank was a giant cargo vessel.","zh":"沉沒的那艘船是一艘巨型貨船。"},{"en":"A cargo vessel is a ship used to carry goods rather than passengers.","zh":"「cargo vessel」是用來運送貨物而不是乘客的船。"},{"en":"A cargo vessel may transport food, machines, clothes, or building materials.","zh":"貨船可以運送食物、機器、衣服或建築材料。"},{"en":"If a cargo vessel sinks, the goods on board may be lost or damaged.","zh":"如果貨船沉沒，船上的貨物可能遺失或受損。"},{"en":"Modern trade depends heavily on cargo vessels moving products across oceans.","zh":"現代貿易高度依賴貨船把產品運過海洋。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":1},{"front":"measuring nearly","meaning":"長度接近……","examples":[{"en":"The cargo vessel measured nearly 500 feet long.","zh":"這艘貨船長度接近五百英尺。"},{"en":"Measuring nearly a certain size means being almost that size.","zh":"「measuring nearly」某個尺寸，意思是大小差不多達到該數字。"},{"en":"The new bridge measures nearly two kilometres from end to end.","zh":"新橋從一端到另一端長度接近兩公里。"},{"en":"A queue measuring nearly fifty metres can show that demand is very high.","zh":"一條長度接近五十米的隊伍，可以顯示需求很高。"},{"en":"Nearly tells us the number is close, but not exact.","zh":"「nearly」告訴我們數字接近，但不是完全準確。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":2},{"front":"come to rest","meaning":"停留；沉落","examples":[{"en":"The ship came to rest about 200 feet below the surface.","zh":"這艘船最後停留在水面以下約二百英尺處。"},{"en":"To come to rest means to stop moving and settle in one place.","zh":"「come to rest」意思是停止移動並停留在某處。"},{"en":"After rolling down the hill, the ball came to rest beside a tree.","zh":"球滾下山後，停在一棵樹旁。"},{"en":"A sinking boat may come to rest on the seabed after falling through the water.","zh":"沉船穿過水中下沉後，可能最後沉落在海床上。"},{"en":"The phrase often describes where something finally stops after movement.","zh":"這個短語常描述某物移動後最終停止的位置。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":2},{"front":"below the surface","meaning":"在水面以下","examples":[{"en":"The wreck stayed about 200 feet below the surface.","zh":"沉船停留在水面以下約二百英尺處。"},{"en":"Below the surface means under the top layer of water, ground, or another material.","zh":"「below the surface」意思是在水、地面或其他物質的表層以下。"},{"en":"Fish may swim just below the surface where sunlight still reaches the water.","zh":"魚可能在水面以下不深處游動，那裡仍有陽光照到。"},{"en":"Problems below the surface are not always easy to see at first.","zh":"表面以下的問題起初不一定容易看見。"},{"en":"In this passage, the phrase describes depth under the sea.","zh":"在本文中，這個短語描述海面以下的深度。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":2},{"front":"stay for more than","meaning":"停留超過……","examples":[{"en":"The ship stayed underwater for more than 2,000 years.","zh":"這艘船在水底停留超過二千年。"},{"en":"To stay for more than a period means to remain there longer than that time.","zh":"「stay for more than」某段時間，意思是停留時間長過該段時間。"},{"en":"A visitor who stays for more than three months may need a special visa.","zh":"停留超過三個月的訪客可能需要特別簽證。"},{"en":"If food stays in the fridge for more than a week, you should check whether it is safe.","zh":"如果食物在雪櫃停留超過一星期，你應檢查它是否安全。"},{"en":"The phrase emphasises that the time period is longer than expected.","zh":"這個短語強調時間比預期更長。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":2},{"front":"divers looking for sponges","meaning":"尋找海綿的潛水員","examples":[{"en":"Divers looking for sponges discovered the wreck.","zh":"尋找海綿的潛水員發現了沉船。"},{"en":"Divers looking for sponges are people who go underwater to collect natural sea sponges.","zh":"「divers looking for sponges」是指潛入水底收集天然海綿的人。"},{"en":"Divers looking for sponges may find rocks, fish, or unexpected old objects underwater.","zh":"尋找海綿的潛水員可能在水底發現岩石、魚類或意想不到的古物。"},{"en":"Because they work deep in the sea, divers looking for sponges sometimes discover things others miss.","zh":"因為他們在深海工作，尋找海綿的潛水員有時會發現其他人錯過的東西。"},{"en":"In this story, ordinary work led to an important archaeological discovery.","zh":"在這個故事中，普通工作帶來了一項重要考古發現。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":2},{"front":"discover the wreck","meaning":"發現沉船","examples":[{"en":"Divers discovered the wreck a little more than a century ago.","zh":"潛水員在一百多年前發現了沉船。"},{"en":"To discover the wreck means to find the remains of a destroyed or sunken ship.","zh":"「discover the wreck」意思是發現被毀或沉沒船隻的殘骸。"},{"en":"Fishermen may discover a wreck when their nets catch old metal or wood.","zh":"漁民的漁網勾到舊金屬或木頭時，可能發現沉船。"},{"en":"Discovering a wreck can lead archaeologists to study trade, travel, and ancient technology.","zh":"發現沉船可以令考古學家研究貿易、旅行和古代技術。"},{"en":"A wreck may stay hidden for centuries before someone discovers it.","zh":"沉船可能隱藏數百年後才被人發現。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":2},{"front":"a little more than a century ago","meaning":"一百多年前","examples":[{"en":"The wreck was discovered a little more than a century ago.","zh":"這艘沉船是一百多年前被發現的。"},{"en":"A little more than a century ago means slightly over one hundred years ago.","zh":"「a little more than a century ago」意思是略多於一百年前。"},{"en":"The old school building was built a little more than a century ago.","zh":"那座舊校舍建於一百多年前。"},{"en":"If a photograph was taken a little more than a century ago, it can show how daily life has changed.","zh":"如果一張照片拍攝於一百多年前，它可以顯示日常生活如何改變。"},{"en":"This phrase gives an approximate historical time, not an exact date.","zh":"這個短語提供大約的歷史時間，而不是準確日期。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":2},{"front":"inside the hull","meaning":"在船身內","examples":[{"en":"Inside the hull were many bronze and marble statues.","zh":"船身內有許多青銅和大理石雕像。"},{"en":"Inside the hull means inside the main body of a ship.","zh":"「inside the hull」意思是在船的主要船身內部。"},{"en":"Water can enter inside the hull if a ship is damaged.","zh":"如果船受損，水可能進入船身內。"},{"en":"Archaeologists search inside the hull because cargo may still be trapped there.","zh":"考古學家搜索船身內部，因為貨物可能仍困在那裡。"},{"en":"The hull protects the ship’s contents until it breaks or sinks.","zh":"船身會保護船內物品，直到它破裂或沉沒。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":2},{"front":"a number of","meaning":"一些；若干","examples":[{"en":"Inside the hull were a number of statues.","zh":"船身內有若干雕像。"},{"en":"A number of means several, but usually not an exact number.","zh":"「a number of」意思是一些或若干，通常不是準確數字。"},{"en":"A number of students arrived early to prepare the classroom.","zh":"一些學生提早到達準備課室。"},{"en":"If a number of workers are absent, the manager may need to change the schedule.","zh":"如果若干員工缺席，經理可能需要改變時間表。"},{"en":"This phrase is useful when the exact count is unknown or unimportant.","zh":"當準確數目未知或不重要時，這個短語很有用。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":2},{"front":"bronze and marble statues","meaning":"青銅和大理石雕像","examples":[{"en":"The ship contained bronze and marble statues.","zh":"這艘船載有青銅和大理石雕像。"},{"en":"Bronze and marble statues are carved or shaped figures made from metal or stone.","zh":"「bronze and marble statues」是由金屬或石材雕刻或塑造的人像或物像。"},{"en":"A museum may display bronze and marble statues from ancient temples.","zh":"博物館可能展出來自古代神廟的青銅和大理石雕像。"},{"en":"Because bronze and marble statues are heavy, transporting them by ship could be risky.","zh":"因為青銅和大理石雕像很重，用船運送可能有風險。"},{"en":"Such statues often show wealth, artistic taste, and social status.","zh":"這類雕像常顯示財富、藝術品味和社會地位。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":2},{"front":"from the look of things","meaning":"從外觀看來；看情況","examples":[{"en":"From the look of things, the ship was carrying luxury items.","zh":"從外觀看來，這艘船載著奢侈品。"},{"en":"From the look of things means judging by what can be seen.","zh":"「from the look of things」意思是根據看得見的情況判斷。"},{"en":"From the look of things, the restaurant is very popular because people are waiting outside.","zh":"從外觀看來，這間餐廳很受歡迎，因為外面有人等候。"},{"en":"From the look of things, the old house needs repairs before anyone can live there.","zh":"看情況，這間舊屋在人入住前需要維修。"},{"en":"This phrase signals an opinion based on visible evidence, not full proof.","zh":"這個短語表示基於可見證據的看法，而不是完整證明。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":2},{"front":"seem to be carrying","meaning":"似乎載有","examples":[{"en":"The ship seemed to be carrying luxury items.","zh":"這艘船似乎載有奢侈品。"},{"en":"Seem to be carrying means appears to have goods or objects on board.","zh":"「seem to be carrying」意思是看起來船上或車上載有貨物或物品。"},{"en":"The delivery van seemed to be carrying furniture because chairs were visible inside.","zh":"那輛送貨車似乎載有家具，因為裡面看得見椅子。"},{"en":"If a truck seems to be carrying dangerous chemicals, workers should check the labels carefully.","zh":"如果貨車似乎載有危險化學品，工人應仔細檢查標籤。"},{"en":"Seem to be suggests uncertainty because the speaker is judging from evidence.","zh":"「seem to be」表示不確定，因為說話者是根據證據判斷。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":3},{"front":"luxury items","meaning":"奢侈品","examples":[{"en":"The ship was probably carrying luxury items.","zh":"這艘船很可能載有奢侈品。"},{"en":"Luxury items are expensive goods bought for comfort, beauty, or status rather than basic need.","zh":"「luxury items」是昂貴物品，購買它們是為了舒適、美感或地位，而不是基本需要。"},{"en":"Designer watches and rare paintings are luxury items for wealthy buyers.","zh":"名牌手錶和稀有畫作是富有買家的奢侈品。"},{"en":"During hard times, people usually spend less on luxury items.","zh":"在艱難時期，人們通常較少花錢在奢侈品上。"},{"en":"Luxury items can reveal what rich people valued in a particular society.","zh":"奢侈品可以揭示某個社會中富人重視什麼。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":3},{"front":"made in various Greek islands","meaning":"在多個希臘島嶼製造","examples":[{"en":"The luxury items were probably made in various Greek islands.","zh":"這些奢侈品很可能在多個希臘島嶼製造。"},{"en":"Made in various Greek islands means produced in several different Greek islands.","zh":"「made in various Greek islands」意思是在幾個不同希臘島嶼生產。"},{"en":"Souvenirs made in various villages may show different local craft styles.","zh":"在多個村莊製造的紀念品，可能展示不同本地工藝風格。"},{"en":"If goods are made in various places, their materials and designs may differ.","zh":"如果貨物在多個地方製造，其材料和設計可能不同。"},{"en":"The phrase helps show that the ship’s cargo came from more than one location.","zh":"這個短語幫助顯示船上貨物來自不止一個地方。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":3},{"front":"wealthy patrons","meaning":"富有的贊助人；富有買主","examples":[{"en":"The goods were bound for wealthy patrons in the Roman Empire.","zh":"這些貨物是送往羅馬帝國富有買主的。"},{"en":"Wealthy patrons are rich people who buy, support, or pay for art, buildings, or services.","zh":"「wealthy patrons」是購買、支持或資助藝術、建築或服務的富人。"},{"en":"A painter may depend on wealthy patrons who pay for portraits.","zh":"畫家可能依賴付錢委託肖像畫的富有贊助人。"},{"en":"Wealthy patrons can help artists survive, but they may also influence what artists create.","zh":"富有贊助人可以幫助藝術家生存，但也可能影響藝術家創作什麼。"},{"en":"In ancient societies, wealthy patrons often used art to display status.","zh":"在古代社會，富有贊助人常用藝術展示地位。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":3},{"front":"the growing Roman Empire","meaning":"不斷擴張的羅馬帝國","examples":[{"en":"The goods were heading to the growing Roman Empire.","zh":"這些貨物正前往不斷擴張的羅馬帝國。"},{"en":"The growing Roman Empire means Rome was expanding in power, land, and influence.","zh":"「the growing Roman Empire」意思是羅馬在權力、土地和影響力上不斷擴張。"},{"en":"A growing company may buy more goods because its market is expanding.","zh":"一間不斷成長的公司可能會購買更多貨物，因為市場正在擴大。"},{"en":"As the Roman Empire grew, demand for art and luxury goods also increased.","zh":"隨著羅馬帝國擴張，對藝術和奢侈品的需求也增加。"},{"en":"The phrase connects the ship’s cargo with a larger historical change.","zh":"這個短語把船上貨物與更大的歷史變化連繫起來。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":3},{"front":"be retrieved","meaning":"被取回；被打撈出來","examples":[{"en":"The statues were retrieved from the wreck.","zh":"這些雕像從沉船中被打撈出來。"},{"en":"If something is retrieved, it is found and brought back from where it was lost or stored.","zh":"如果某物被 retrieved，意思是它從遺失或存放的地方被找到並取回。"},{"en":"A diver retrieved a dropped phone from the bottom of the pool.","zh":"潛水員從泳池底取回一部掉落的電話。"},{"en":"Retrieved objects may need cleaning and protection before they can be studied.","zh":"被取回的物件可能需要清潔和保護，才能被研究。"},{"en":"Retrieve is often used when something is recovered from a difficult place.","zh":"「retrieve」常用於從困難位置取回某物。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":3},{"front":"along with","meaning":"連同；以及","examples":[{"en":"The statues were retrieved along with many other objects.","zh":"這些雕像連同許多其他物件一起被打撈出來。"},{"en":"Along with means together with or in addition to something else.","zh":"「along with」意思是連同、以及或與其他東西一起。"},{"en":"Please bring your ID card along with the application form.","zh":"請帶同身份證以及申請表。"},{"en":"If a student submits homework along with notes, the teacher can understand the process better.","zh":"如果學生提交功課時連同筆記，老師可以更好理解過程。"},{"en":"This phrase shows that one thing is included together with others.","zh":"這個短語顯示某物與其他東西一起包括在內。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":3},{"front":"unimportant stuff","meaning":"不重要的東西","examples":[{"en":"At first, some objects were treated as unimportant stuff.","zh":"起初，有些物件被視為不重要的東西。"},{"en":"Unimportant stuff means things that seem to have little value or meaning.","zh":"「unimportant stuff」指看似沒有太大價值或意義的東西。"},{"en":"Old receipts may look like unimportant stuff until you need proof of payment.","zh":"舊收據可能看似不重要，直到你需要付款證明。"},{"en":"Archaeologists must be careful because unimportant stuff can later become valuable evidence.","zh":"考古學家必須小心，因為不重要的東西後來可能成為有價值證據。"},{"en":"What looks like unimportant stuff to one person may be important to a researcher.","zh":"對一個人看似不重要的東西，對研究人員可能很重要。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":3},{"front":"be stored","meaning":"被存放","examples":[{"en":"The objects were retrieved and stored.","zh":"這些物件被取回並存放起來。"},{"en":"If something is stored, it is kept in a place for later use or protection.","zh":"如果某物被 stored，意思是它被保存在某個地方，以供日後使用或保護。"},{"en":"Important documents should be stored in a dry and safe place.","zh":"重要文件應存放在乾燥安全的地方。"},{"en":"Museum objects are stored carefully so that light, heat, and moisture do not damage them.","zh":"博物館物件會被小心存放，以免光、熱和濕氣損壞它們。"},{"en":"Stored items can be forgotten if nobody checks them again.","zh":"存放起來的物件如果沒有人再檢查，可能會被遺忘。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":3},{"front":"enterprising archaeologist","meaning":"有進取心的考古學家","examples":[{"en":"An enterprising archaeologist examined one of the pieces of junk.","zh":"一位有進取心的考古學家檢查了其中一件廢物。"},{"en":"An enterprising archaeologist is a researcher who is energetic, curious, and willing to try useful actions.","zh":"「enterprising archaeologist」是有活力、好奇，並願意採取有用行動的研究人員。"},{"en":"An enterprising teacher may turn a broken object into a classroom activity.","zh":"有進取心的老師可能把壞掉的物件變成課堂活動。"},{"en":"Because the archaeologist was enterprising, an ignored object was studied more carefully.","zh":"因為這位考古學家有進取心，一件被忽視的物件得以被更仔細研究。"},{"en":"Enterprising people often notice opportunities that others miss.","zh":"有進取心的人常注意到別人錯過的機會。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":3},{"front":"clear off","meaning":"清除；抹去","examples":[{"en":"The archaeologist cleared off a layer of organic material.","zh":"考古學家清除了一層有機物質。"},{"en":"To clear off something means to remove it from a surface.","zh":"「clear off」某物，意思是把它從表面移走。"},{"en":"Please clear off the table before dinner is served.","zh":"晚餐上桌前，請清理桌面。"},{"en":"If dust is cleared off an old photo, the image may become visible again.","zh":"如果舊照片上的灰塵被清除，圖像可能再次可見。"},{"en":"Clearing off dirt carefully can reveal details without damaging the object.","zh":"小心清除泥土可以顯露細節，而不損壞物件。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":3},{"front":"a layer of","meaning":"一層……","examples":[{"en":"The archaeologist cleared off a layer of organic material.","zh":"考古學家清除了一層有機物質。"},{"en":"A layer of something is a thin or thick covering spread over a surface.","zh":"「a layer of」某物，指覆蓋在表面上的薄層或厚層。"},{"en":"A layer of ice formed on the road after the temperature dropped.","zh":"氣溫下降後，路面形成一層冰。"},{"en":"If a layer of dust covers a book, it has probably not been used for a long time.","zh":"如果一本書被一層灰塵覆蓋，它很可能已很久沒有被使用。"},{"en":"Removing one layer may reveal what is hidden underneath.","zh":"移除一層東西可能揭示下面隱藏的內容。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":4},{"front":"organic material","meaning":"有機物質","examples":[{"en":"Organic material covered one of the objects from the wreck.","zh":"有機物質覆蓋了沉船中的其中一件物件。"},{"en":"Organic material comes from living things, such as plants, animals, or microorganisms.","zh":"「organic material」來自生物，例如植物、動物或微生物。"},{"en":"Leaves and food waste are organic material that can become compost.","zh":"樹葉和廚餘是可以變成堆肥的有機物質。"},{"en":"Organic material on an ancient object may hide its shape and details.","zh":"古物上的有機物質可能遮蓋其形狀和細節。"},{"en":"Scientists handle organic material carefully because it can decay or contain useful evidence.","zh":"科學家小心處理有機物質，因為它可能腐爛或包含有用證據。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":4},{"front":"a piece of junk","meaning":"一件廢物","examples":[{"en":"The object first seemed to be a piece of junk.","zh":"那件物件起初似乎是一件廢物。"},{"en":"A piece of junk is something that looks useless, broken, or worthless.","zh":"「a piece of junk」是看起來無用、破爛或沒有價值的東西。"},{"en":"An old radio may look like a piece of junk until someone repairs it.","zh":"一部舊收音機在有人修理前，可能看似一件廢物。"},{"en":"A piece of junk can become valuable if it contains rare parts or historical clues.","zh":"如果一件廢物包含稀有零件或歷史線索，它可能變得有價值。"},{"en":"The phrase is informal and shows that people did not value the object at first.","zh":"這個短語較口語化，顯示人們起初不重視該物件。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":4},{"front":"look like","meaning":"看起來像","examples":[{"en":"The object looked like a gearwheel.","zh":"那件物件看起來像齒輪。"},{"en":"To look like something means to have a similar appearance.","zh":"「look like」某物，意思是外觀看起來相似。"},{"en":"The cloud looked like a dragon to the children.","zh":"孩子們覺得那朵雲看起來像龍。"},{"en":"If a plant looks like it is dying, it may need water or sunlight.","zh":"如果植物看起來像快死了，它可能需要水或陽光。"},{"en":"Look like describes appearance, not necessarily the truth.","zh":"「look like」描述外觀，不一定代表事實。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":4},{"front":"gearwheel","meaning":"齒輪","examples":[{"en":"The object looked like a gearwheel.","zh":"那件物件看起來像齒輪。"},{"en":"A gearwheel is a wheel with teeth that fits with other wheels to transfer movement.","zh":"「gearwheel」是有齒的輪，可與其他齒輪配合以傳遞運動。"},{"en":"A bicycle or clock may contain gearwheels that help parts move together.","zh":"單車或時鐘可能包含齒輪，幫助零件一起運作。"},{"en":"If one gearwheel breaks, the whole machine may stop working.","zh":"如果一個齒輪壞了，整部機器可能停止運作。"},{"en":"Gearwheels are important in machines that need controlled mechanical movement.","zh":"齒輪對需要受控機械運動的機器很重要。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":4},{"front":"inscriptions","meaning":"銘文；刻字","examples":[{"en":"The object had inscriptions in Greek characters.","zh":"那件物件上有希臘文字銘文。"},{"en":"Inscriptions are words or symbols written, carved, or engraved on a surface.","zh":"「inscriptions」是寫在、刻在或雕在表面上的文字或符號。"},{"en":"Old buildings may have inscriptions showing who built them and when.","zh":"舊建築可能有銘文，顯示由誰建造及建於何時。"},{"en":"Inscriptions can help historians understand the purpose of an ancient object.","zh":"銘文可以幫助歷史學家理解古物用途。"},{"en":"Unlike printed text, inscriptions are often part of the object itself.","zh":"與印刷文字不同，銘文通常是物件本身的一部分。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":4},{"front":"Greek characters","meaning":"希臘文字","examples":[{"en":"The inscriptions were written in Greek characters.","zh":"這些銘文是用希臘文字寫成的。"},{"en":"Greek characters are the letters used in the Greek writing system.","zh":"「Greek characters」是希臘書寫系統使用的字母。"},{"en":"Students may see Greek characters in mathematics, science, or ancient texts.","zh":"學生可能在數學、科學或古代文本中看見希臘文字。"},{"en":"If an inscription uses Greek characters, experts in Greek may be needed to read it.","zh":"如果銘文使用希臘文字，可能需要希臘文專家來閱讀。"},{"en":"The characters helped researchers connect the object with Greek culture.","zh":"這些文字幫助研究人員把該物件與希臘文化連繫起來。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":4},{"front":"have something to do with","meaning":"與……有關","examples":[{"en":"The object seemed to have something to do with astronomy.","zh":"那件物件似乎與天文學有關。"},{"en":"To have something to do with a subject means to be connected with it in some way.","zh":"「have something to do with」某主題，意思是以某種方式與它有關。"},{"en":"A timetable has something to do with planning because it shows when things happen.","zh":"時間表與規劃有關，因為它顯示事情何時發生。"},{"en":"If a machine has symbols of stars and planets, it may have something to do with astronomy.","zh":"如果一部機器有星星和行星符號，它可能與天文學有關。"},{"en":"This phrase is useful when the exact connection is not yet clear.","zh":"當準確關聯尚未清楚時，這個短語很有用。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":4},{"front":"astronomy","meaning":"天文學","examples":[{"en":"The inscriptions suggested a connection with astronomy.","zh":"這些銘文顯示它與天文學有關。"},{"en":"Astronomy is the scientific study of stars, planets, the moon, the sun, and space.","zh":"「astronomy」是研究恆星、行星、月亮、太陽和太空的科學。"},{"en":"Students learn basic astronomy when they study why the moon changes shape.","zh":"學生研究月亮為何改變形狀時，就是學習基本天文學。"},{"en":"Astronomy helps people predict eclipses and understand movements in the sky.","zh":"天文學幫助人們預測日食、月食，並理解天空中的運動。"},{"en":"Astronomy is different from astrology because it is based on scientific observation.","zh":"天文學不同於占星術，因為它基於科學觀察。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":4},{"front":"go on to become","meaning":"後來成為","examples":[{"en":"The piece of junk went on to become the most celebrated find.","zh":"那件廢物後來成為最著名的發現。"},{"en":"To go on to become something means to later become it after an earlier stage.","zh":"「go on to become」某事物，意思是在早期階段之後，後來成為它。"},{"en":"A shy student may go on to become a confident public speaker.","zh":"害羞的學生可能後來成為自信的演講者。"},{"en":"A small local shop can go on to become a national brand if it grows steadily.","zh":"如果穩定成長，一間小本地店舖可以後來成為全國品牌。"},{"en":"The phrase shows a change from one status to another over time.","zh":"這個短語顯示某物隨時間從一種身份變成另一種身份。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":4},{"front":"the most celebrated find","meaning":"最著名的發現","examples":[{"en":"The Antikythera Mechanism became the most celebrated find from the shipwreck.","zh":"安提基特拉機械成為該沉船中最著名的發現。"},{"en":"The most celebrated find is the discovery that becomes the most famous or admired.","zh":"「the most celebrated find」指最有名或最受讚賞的發現。"},{"en":"In a museum collection, one small object may become the most celebrated find.","zh":"在博物館收藏中，一件小物件可能成為最著名的發現。"},{"en":"A find becomes celebrated when it changes what people know about the past.","zh":"當一項發現改變人們對過去的認識，它就會變得著名。"},{"en":"The phrase suggests that many things were found, but one became especially important.","zh":"這個短語暗示有很多東西被發現，但其中一件特別重要。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":4},{"front":"shipwreck","meaning":"沉船；船難遺址","examples":[{"en":"The device was found in an ancient shipwreck.","zh":"這件裝置是在一個古代沉船遺址中被發現的。"},{"en":"A shipwreck is the remains of a ship that sank or was destroyed.","zh":"「shipwreck」是沉沒或被毀船隻的殘骸。"},{"en":"Divers explored the shipwreck to see what cargo was still inside.","zh":"潛水員探索沉船，查看裡面仍有什麼貨物。"},{"en":"A shipwreck can preserve objects for centuries if they are buried in mud or sand.","zh":"如果物件埋在泥或沙中，沉船可以保存它們數百年。"},{"en":"Shipwrecks help historians study trade, travel, and daily life at sea.","zh":"沉船幫助歷史學家研究貿易、旅行和海上日常生活。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":5},{"front":"be displayed at","meaning":"在……展出","examples":[{"en":"The mechanism is displayed at the National Archaeological Museum of Athens.","zh":"這件機械在雅典國家考古博物館展出。"},{"en":"If something is displayed at a place, it is shown there for people to see.","zh":"如果某物被 displayed at 某地，意思是它在那裡展示給人觀看。"},{"en":"Student artwork may be displayed at the school entrance.","zh":"學生藝術作品可能在學校入口展出。"},{"en":"Valuable objects are displayed at museums with special lighting and security.","zh":"貴重物件會在博物館以特別燈光和保安展出。"},{"en":"Displayed at tells us where the public can view the object.","zh":"「displayed at」告訴我們公眾可以在哪裡觀看該物件。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":5},{"front":"National Archaeological Museum of Athens","meaning":"雅典國家考古博物館","examples":[{"en":"The Antikythera Mechanism is displayed at the National Archaeological Museum of Athens.","zh":"安提基特拉機械在雅典國家考古博物館展出。"},{"en":"The National Archaeological Museum of Athens is a museum in Greece that holds important ancient objects.","zh":"雅典國家考古博物館是希臘一間收藏重要古物的博物館。"},{"en":"Visitors may go to the National Archaeological Museum of Athens to see Greek statues, tools, and inscriptions.","zh":"訪客可能到雅典國家考古博物館觀看希臘雕像、工具和銘文。"},{"en":"Because the mechanism is kept there, researchers and visitors can study it in a protected setting.","zh":"因為這件機械保存在那裡，研究人員和訪客可以在受保護的環境中研究它。"},{"en":"The museum’s name tells us the object is treated as part of national archaeological heritage.","zh":"博物館的名稱告訴我們，該物件被視為國家考古遺產的一部分。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":5},{"front":"research has shown that","meaning":"研究顯示","examples":[{"en":"Research has shown that the wheel was part of a sophisticated device.","zh":"研究顯示，這個輪是精密裝置的一部分。"},{"en":"Research has shown that means studies have provided evidence for a conclusion.","zh":"「research has shown that」意思是研究已提供證據支持某個結論。"},{"en":"Research has shown that sleep affects memory and concentration.","zh":"研究顯示，睡眠影響記憶和專注力。"},{"en":"When research has shown that a method works, schools may be more willing to use it.","zh":"當研究顯示某方法有效，學校可能更願意使用它。"},{"en":"This phrase is stronger than a guess because it points to evidence.","zh":"這個短語比猜測更有力，因為它指向證據。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":5},{"front":"part of a device","meaning":"裝置的一部分","examples":[{"en":"The wheel was part of a complex device.","zh":"這個輪是一件複雜裝置的一部分。"},{"en":"Part of a device means one component inside a larger machine or tool.","zh":"「part of a device」意思是一部較大機器或工具中的一個組件。"},{"en":"A battery is part of a device that needs power to operate.","zh":"電池是需要電力運作的裝置的一部分。"},{"en":"If one part of a device is missing, the whole machine may not work.","zh":"如果裝置的一部分缺失，整部機器可能不能運作。"},{"en":"Archaeologists study each part of a device to understand the whole design.","zh":"考古學家研究裝置的每一部分，以理解整體設計。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":5},{"front":"so sophisticated that","meaning":"如此精密以致……","examples":[{"en":"The device was so sophisticated that its complexity was unmatched for centuries.","zh":"這件裝置如此精密，以致其複雜程度數百年間無可匹敵。"},{"en":"So sophisticated that means so advanced or complex that a particular result follows.","zh":"「so sophisticated that」意思是如此先進或複雜，以致產生某個結果。"},{"en":"The security system was so sophisticated that ordinary thieves could not break in.","zh":"保安系統如此精密，以致普通小偷無法闖入。"},{"en":"A lesson can be so sophisticated that beginners cannot follow it.","zh":"一堂課可以如此複雜，以致初學者無法跟上。"},{"en":"This structure links a high degree of complexity with its consequence.","zh":"這個結構把高度複雜性與其後果連繫起來。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":5},{"front":"sophisticated","meaning":"精密的；複雜先進的","examples":[{"en":"The Antikythera Mechanism was a highly sophisticated device.","zh":"安提基特拉機械是一件高度精密的裝置。"},{"en":"Sophisticated means complex, advanced, and carefully designed.","zh":"「sophisticated」意思是複雜、先進且經仔細設計。"},{"en":"A sophisticated phone can perform many tasks beyond making calls.","zh":"一部精密手機可以執行許多打電話以外的任務。"},{"en":"Sophisticated machines often require expert repair because their parts work closely together.","zh":"精密機器通常需要專家維修，因為其零件緊密配合。"},{"en":"Sophisticated does not simply mean expensive; it means technically or intellectually advanced.","zh":"「sophisticated」不只是昂貴的意思；它指技術上或知識上先進。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":5},{"front":"complexity","meaning":"複雜程度","examples":[{"en":"The device’s complexity would not be matched for a thousand years.","zh":"這件裝置的複雜程度在一千年內無可匹敵。"},{"en":"Complexity means the state of having many connected parts or difficult details.","zh":"「complexity」指有許多相互連結部分或困難細節的狀態。"},{"en":"The complexity of a city’s transport system makes planning difficult.","zh":"城市交通系統的複雜程度令規劃變得困難。"},{"en":"Greater complexity can make a machine powerful, but also harder to repair.","zh":"更高的複雜程度可以令機器強大，但也令維修更困難。"},{"en":"Understanding complexity requires looking at how the parts work together.","zh":"理解複雜程度需要查看各部分如何一起運作。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":5},{"front":"not be matched for","meaning":"在……期間無可匹敵","examples":[{"en":"Its complexity would not be matched for a thousand years.","zh":"它的複雜程度在一千年內無可匹敵。"},{"en":"Not be matched for a period means no equal example appears during that time.","zh":"「not be matched for」某段時間，意思是在那段時間內沒有同等例子出現。"},{"en":"The athlete’s record was not matched for twenty years.","zh":"那名運動員的紀錄在二十年間無可匹敵。"},{"en":"If a technology is not matched for centuries, it was far ahead of its time.","zh":"如果一項技術數百年間無可匹敵，它就是遠遠超前於時代。"},{"en":"This phrase emphasises how exceptional something was.","zh":"這個短語強調某物非常卓越。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":5},{"front":"a thousand years","meaning":"一千年","examples":[{"en":"The device was more advanced than anything similar for about a thousand years.","zh":"這件裝置在約一千年內比任何類似東西都先進。"},{"en":"A thousand years means a period of one millennium.","zh":"「a thousand years」意思是一個千年的時期。"},{"en":"A building that survives a thousand years can teach us about ancient engineering.","zh":"一座能保存一千年的建築可以教我們認識古代工程。"},{"en":"If a tradition lasts a thousand years, many generations must have preserved it.","zh":"如果一項傳統延續一千年，必定有許多代人保存它。"},{"en":"The phrase often creates a strong sense of historical distance.","zh":"這個短語常產生強烈的歷史距離感。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":5},{"front":"the world’s first known analogue computer","meaning":"世界首部已知模擬電腦","examples":[{"en":"The device was the world’s first known analogue computer.","zh":"這件裝置是世界首部已知模擬電腦。"},{"en":"The world’s first known analogue computer means the earliest identified machine of this kind that used physical movement to calculate information.","zh":"「the world’s first known analogue computer」指目前已確認最早、用物理運動計算資訊的這類機器。"},{"en":"A museum label may call an object the world’s first known example when no older example has been found.","zh":"當沒有發現更早例子時，博物館標籤可能稱某物為世界首個已知例子。"},{"en":"This title matters because it changes how people understand ancient technology.","zh":"這個稱號很重要，因為它改變人們對古代技術的理解。"},{"en":"Known reminds us that an older example may exist but has not been discovered.","zh":"「known」提醒我們，可能有更早例子存在，但尚未被發現。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":5},{"front":"analogue computer","meaning":"模擬電腦","examples":[{"en":"The Antikythera Mechanism is described as an analogue computer.","zh":"安提基特拉機械被描述為一部模擬電腦。"},{"en":"An analogue computer uses physical parts or continuous movement to represent and calculate information.","zh":"「analogue computer」使用物理部件或連續運動來表示和計算資訊。"},{"en":"An old mechanical tide predictor can be a kind of analogue computer.","zh":"舊式機械潮汐預測器可以是一種模擬電腦。"},{"en":"Unlike a modern digital computer, an analogue computer may use gears, wheels, or dials.","zh":"不同於現代數碼電腦，模擬電腦可能使用齒輪、輪子或刻度盤。"},{"en":"The phrase helps explain why the mechanism was more than a simple decoration.","zh":"這個短語幫助解釋為什麼該機械不只是簡單裝飾品。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":6},{"front":"international conference","meaning":"國際會議","examples":[{"en":"An international conference in Athens focused on the mechanism.","zh":"在雅典舉行的一場國際會議集中討論這件機械。"},{"en":"An international conference is a meeting where people from different countries discuss a topic.","zh":"「international conference」是來自不同國家的人討論某主題的會議。"},{"en":"Scientists may attend an international conference to share new research.","zh":"科學家可能參加國際會議以分享新研究。"},{"en":"An international conference can create cooperation because experts meet and compare ideas.","zh":"國際會議可以促成合作，因為專家會面並比較想法。"},{"en":"The phrase suggests the subject is important beyond one country.","zh":"這個短語暗示該主題的重要性超越一個國家。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":6},{"front":"organized in Athens","meaning":"在雅典舉辦","examples":[{"en":"An international conference organized in Athens had only one subject.","zh":"一場在雅典舉辦的國際會議只有一個主題。"},{"en":"Organized in Athens means arranged and held in the city of Athens.","zh":"「organized in Athens」意思是在雅典安排和舉行。"},{"en":"A festival organized in the city centre may attract many visitors.","zh":"在市中心舉辦的節日可能吸引許多訪客。"},{"en":"If a meeting is organized in Athens, scholars may travel there from other countries.","zh":"如果會議在雅典舉辦，學者可能從其他國家前往。"},{"en":"The phrase tells us where the event was planned to take place.","zh":"這個短語告訴我們活動計劃在哪裡舉行。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":6},{"front":"a couple of weeks ago","meaning":"數星期前","examples":[{"en":"The conference was organized a couple of weeks ago.","zh":"這場會議是在數星期前舉辦的。"},{"en":"A couple of weeks ago means about two weeks ago.","zh":"「a couple of weeks ago」意思是大約兩星期前。"},{"en":"I sent the application a couple of weeks ago, so I should receive a reply soon.","zh":"我在數星期前寄出申請，所以應該很快收到回覆。"},{"en":"If a rule changed a couple of weeks ago, some people may still not know it.","zh":"如果規則在數星期前改變，有些人可能仍不知道。"},{"en":"This phrase gives an approximate recent time, not an exact date.","zh":"這個短語提供大約的近期時間，而不是準確日期。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":6},{"front":"have only one subject","meaning":"只有一個主題","examples":[{"en":"The conference had only one subject: the Antikythera Mechanism.","zh":"這場會議只有一個主題：安提基特拉機械。"},{"en":"To have only one subject means to focus on a single topic.","zh":"「have only one subject」意思是只集中於單一主題。"},{"en":"A workshop may have only one subject so participants can study it deeply.","zh":"工作坊可能只有一個主題，讓參加者深入研究。"},{"en":"If a meeting has only one subject, discussion can be more focused and detailed.","zh":"如果會議只有一個主題，討論可以更集中和詳細。"},{"en":"The phrase suggests the topic is important enough to deserve full attention.","zh":"這個短語暗示該主題重要到值得全程關注。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":6},{"front":"Antikythera Mechanism","meaning":"安提基特拉機械","examples":[{"en":"The Antikythera Mechanism has become famous among historians of science.","zh":"安提基特拉機械在科學史學家之間變得著名。"},{"en":"The Antikythera Mechanism is an ancient Greek geared device used to model astronomical movements.","zh":"安提基特拉機械是一件古希臘齒輪裝置，用來模擬天體運動。"},{"en":"Students may learn about the Antikythera Mechanism when studying early technology.","zh":"學生研究早期技術時，可能會學到安提基特拉機械。"},{"en":"The Antikythera Mechanism matters because it shows ancient engineering was more advanced than many people expected.","zh":"安提基特拉機械很重要，因為它顯示古代工程比許多人想像中更先進。"},{"en":"Its discovery changed how researchers think about Greek science and craftsmanship.","zh":"它的發現改變了研究人員對希臘科學和工藝的看法。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":6},{"front":"raise new questions","meaning":"引發新問題","examples":[{"en":"Every discovery about the device has raised new questions.","zh":"關於這件裝置的每項發現都引發新問題。"},{"en":"To raise new questions means to make people ask more things they did not ask before.","zh":"「raise new questions」意思是令人提出以前沒有問過的新疑問。"},{"en":"A surprising medical result can raise new questions about how a disease works.","zh":"令人意外的醫學結果可以引發關於疾病運作方式的新問題。"},{"en":"New evidence may answer one problem but raise new questions at the same time.","zh":"新證據可能解答一個問題，同時引發新問題。"},{"en":"In research, raising new questions is often a sign that the topic is important.","zh":"在研究中，引發新問題常是主題重要的跡象。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":6},{"front":"for what purpose","meaning":"為了甚麼目的","examples":[{"en":"Researchers ask who built the device and for what purpose.","zh":"研究人員問是誰製造了這件裝置，以及為了甚麼目的。"},{"en":"For what purpose means for what reason or intended use.","zh":"「for what purpose」意思是為了甚麼原因或用途。"},{"en":"Before buying expensive equipment, ask for what purpose it will be used.","zh":"購買昂貴設備前，要問它將為了甚麼目的使用。"},{"en":"If an ancient object has no clear function, archaeologists ask for what purpose it was made.","zh":"如果古物沒有清楚功能，考古學家會問它為了甚麼目的而製造。"},{"en":"The phrase focuses on intention, not just appearance.","zh":"這個短語集中於意圖，而不只是外觀。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":6},{"front":"the technology behind","meaning":"……背後的技術","examples":[{"en":"The technology behind the device disappeared for a thousand years.","zh":"這件裝置背後的技術消失了一千年。"},{"en":"The technology behind something means the knowledge, methods, and tools that make it work.","zh":"「the technology behind」某物，指令它運作的知識、方法和工具。"},{"en":"The technology behind a smartphone includes chips, software, batteries, and networks.","zh":"智能手機背後的技術包括晶片、軟件、電池和網絡。"},{"en":"If the technology behind a machine is lost, later people may not know how to build it again.","zh":"如果一部機器背後的技術失傳，後人可能不知道如何再次製造它。"},{"en":"This phrase looks beyond the object itself to the skills that created it.","zh":"這個短語超越物件本身，看到創造它的技能。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":6},{"front":"ancient Greek culture","meaning":"古希臘文化","examples":[{"en":"The mechanism may tell us something about ancient Greek culture.","zh":"這件機械可能告訴我們一些關於古希臘文化的事情。"},{"en":"Ancient Greek culture includes the ideas, art, science, language, and daily life of ancient Greece.","zh":"古希臘文化包括古希臘的思想、藝術、科學、語言和日常生活。"},{"en":"Students study ancient Greek culture through myths, temples, plays, and philosophy.","zh":"學生透過神話、神廟、戲劇和哲學研究古希臘文化。"},{"en":"A machine from ancient Greece can show that ancient Greek culture included practical engineering.","zh":"來自古希臘的機器可以顯示古希臘文化包括實用工程。"},{"en":"Culture is not only writing and art; it can also include technology.","zh":"文化不只是文字和藝術；它也可以包括技術。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":6},{"front":"marvelous construction","meaning":"精妙的構造","examples":[{"en":"The marvelous construction of the device impressed researchers.","zh":"這件裝置精妙的構造令研究人員印象深刻。"},{"en":"Marvelous construction means a wonderful and skilful way of building something.","zh":"「marvelous construction」意思是某物建造方式精彩而技藝高超。"},{"en":"Visitors admired the marvelous construction of the old bridge.","zh":"訪客欣賞那座舊橋精妙的構造。"},{"en":"A machine with marvelous construction can reveal the skill of its makers.","zh":"一部具有精妙構造的機器可以揭示製作者的技術。"},{"en":"This phrase praises both the design and the craftsmanship.","zh":"這個短語同時讚賞設計和工藝。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":6},{"front":"precise knowledge","meaning":"精確知識","examples":[{"en":"The device implies precise knowledge of celestial movements.","zh":"這件裝置意味著對天體運動有精確知識。"},{"en":"Precise knowledge means accurate and detailed understanding.","zh":"「precise knowledge」意思是準確而詳細的理解。"},{"en":"A doctor needs precise knowledge of the patient’s symptoms before choosing treatment.","zh":"醫生在選擇治療前，需要對病人症狀有精確知識。"},{"en":"Precise knowledge of measurements helps engineers build safe structures.","zh":"對測量的精確知識幫助工程師建造安全結構。"},{"en":"The mechanism suggests its makers understood astronomy with unusual accuracy.","zh":"這件機械顯示其製作者以異常準確度理解天文學。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":7},{"front":"the movement of the sun and moon and Earth","meaning":"太陽、月亮和地球的運動","examples":[{"en":"The device reflected knowledge of the movement of the sun and moon and Earth.","zh":"這件裝置反映了對太陽、月亮和地球運動的認識。"},{"en":"This phrase refers to how these celestial bodies appear to move in relation to one another.","zh":"這個短語指這些天體彼此之間看起來如何運動。"},{"en":"Students learn about the movement of the sun, moon, and Earth when studying days, months, and seasons.","zh":"學生研究日、月和季節時，會學到太陽、月亮和地球的運動。"},{"en":"Understanding these movements helps people explain eclipses and moon phases.","zh":"理解這些運動幫助人們解釋日月食和月相。"},{"en":"The mechanism turned astronomical knowledge into visible mechanical motion.","zh":"這件機械把天文知識變成可見的機械運動。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":7},{"front":"imply","meaning":"暗示；意味","examples":[{"en":"The device implies advanced astronomical knowledge.","zh":"這件裝置暗示了先進的天文知識。"},{"en":"To imply means to suggest something without saying it directly.","zh":"「imply」意思是暗示某事，而不是直接說出。"},{"en":"A locked door may imply that the office is closed.","zh":"一扇鎖上的門可能意味著辦公室已關閉。"},{"en":"If a student finishes difficult work quickly, it may imply strong preparation.","zh":"如果學生很快完成困難作業，這可能意味著準備充分。"},{"en":"In research, an object can imply skills or knowledge that are not written down.","zh":"在研究中，一件物件可以暗示沒有寫下來的技能或知識。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":7},{"front":"the ancients","meaning":"古人","examples":[{"en":"The device may show how the ancients thought about destiny.","zh":"這件裝置可能顯示古人如何思考命運。"},{"en":"The ancients means people who lived in ancient times.","zh":"「the ancients」意思是生活在古代的人。"},{"en":"The ancients observed the sky without modern telescopes.","zh":"古人在沒有現代望遠鏡的情況下觀察天空。"},{"en":"By studying tools and texts, we can learn how the ancients solved problems.","zh":"透過研究工具和文本，我們可以了解古人如何解決問題。"},{"en":"This phrase often refers broadly to people from early civilisations.","zh":"這個短語常概括指早期文明的人。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":7},{"front":"grapple with","meaning":"努力理解；設法處理","examples":[{"en":"The ancients grappled with ideas about determinism and destiny.","zh":"古人努力理解關於決定論和命運的思想。"},{"en":"To grapple with something means to struggle to understand or deal with a difficult issue.","zh":"「grapple with」某事，意思是努力理解或處理困難問題。"},{"en":"Students may grapple with a hard maths problem before finding the method.","zh":"學生可能在找到方法前努力解一道困難數學題。"},{"en":"A family may grapple with a difficult decision about moving home.","zh":"家庭可能努力處理是否搬家的困難決定。"},{"en":"The phrase suggests effort, confusion, and serious thinking.","zh":"這個短語暗示努力、困惑和認真思考。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":7},{"front":"determinism","meaning":"決定論","examples":[{"en":"The device raises questions about ancient ideas of determinism.","zh":"這件裝置引發關於古代決定論思想的問題。"},{"en":"Determinism is the belief that events are fixed by causes and may not be freely chosen.","zh":"「determinism」是一種信念，認為事件由原因決定，未必能自由選擇。"},{"en":"A person discussing determinism may ask whether human choices are truly free.","zh":"討論決定論的人可能會問人類選擇是否真正自由。"},{"en":"If people believe strongly in determinism, they may see the future as already shaped by forces beyond them.","zh":"如果人們強烈相信決定論，他們可能認為未來已由超出自身的力量塑造。"},{"en":"The term is abstract, so it often appears in philosophy, religion, or science discussions.","zh":"這個詞較抽象，所以常出現在哲學、宗教或科學討論中。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":7},{"front":"human destiny","meaning":"人類命運","examples":[{"en":"The mechanism may relate to ancient ideas about human destiny.","zh":"這件機械可能與古人對人類命運的想法有關。"},{"en":"Human destiny means what people believe will happen to human lives or civilisation in the future.","zh":"「human destiny」指人們相信人類生命或文明未來會發生的事情。"},{"en":"Some stories explore human destiny by asking whether people can change their future.","zh":"有些故事透過詢問人能否改變未來來探討人類命運。"},{"en":"Belief in human destiny can affect how people interpret signs, dreams, or natural events.","zh":"對人類命運的信念可以影響人們如何解讀徵兆、夢或自然事件。"},{"en":"The phrase connects personal life with larger questions about fate and history.","zh":"這個短語把個人生命與關於命運和歷史的更大問題連繫起來。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":7},{"front":"gear trains","meaning":"齒輪組","examples":[{"en":"Earlier gear trains from Baghdad used fewer gears.","zh":"來自巴格達的較早齒輪組使用較少齒輪。"},{"en":"Gear trains are sets of connected gears that pass movement from one part to another.","zh":"「gear trains」是相互連接的齒輪組，把運動從一個部分傳到另一個部分。"},{"en":"A clock uses gear trains to move its hands at different speeds.","zh":"時鐘使用齒輪組讓指針以不同速度移動。"},{"en":"If one gear in a gear train is the wrong size, the whole movement can become inaccurate.","zh":"如果齒輪組中一個齒輪尺寸錯誤，整個運動可能變得不準確。"},{"en":"Gear trains allow machines to turn simple movement into complex results.","zh":"齒輪組讓機器把簡單運動變成複雜結果。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":7},{"front":"used for simpler displays","meaning":"用於較簡單的顯示","examples":[{"en":"The Baghdad gear trains were used for simpler displays of celestial motions.","zh":"巴格達的齒輪組用於較簡單地顯示天體運動。"},{"en":"Used for simpler displays means used to show something in a less complex way.","zh":"「used for simpler displays」意思是用來以較不複雜的方式展示某事物。"},{"en":"A classroom model may be used for simpler displays of how planets move.","zh":"課堂模型可能用於較簡單地顯示行星如何運動。"},{"en":"Simpler displays help beginners understand a topic before seeing more complex details.","zh":"較簡單的顯示幫助初學者在接觸複雜細節前理解主題。"},{"en":"The phrase contrasts basic demonstration with advanced calculation.","zh":"這個短語把基本示範與進階計算作對比。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":7},{"front":"solar and lunar motions","meaning":"太陽和月亮的運動","examples":[{"en":"The gears displayed solar and lunar motions.","zh":"這些齒輪顯示太陽和月亮的運動。"},{"en":"Solar and lunar motions are the movements of the sun and moon as observed from Earth.","zh":"「solar and lunar motions」是從地球觀察到的太陽和月亮運動。"},{"en":"A calendar may use solar and lunar motions to mark years and months.","zh":"曆法可能使用太陽和月亮的運動來標記年份和月份。"},{"en":"Understanding solar and lunar motions helps people predict seasons and moon phases.","zh":"理解太陽和月亮的運動幫助人們預測季節和月相。"},{"en":"The phrase is common in astronomy because the sun and moon shape timekeeping.","zh":"這個短語常見於天文學，因為太陽和月亮塑造計時方式。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":7},{"front":"relative to one another","meaning":"相對於彼此","examples":[{"en":"The device showed solar and lunar motions relative to one another.","zh":"這件裝置顯示太陽和月亮相對於彼此的運動。"},{"en":"Relative to one another means compared with each other’s position or movement.","zh":"「relative to one another」意思是比較彼此的位置或運動。"},{"en":"In a classroom, students may sit in different places relative to one another.","zh":"在課室中，學生相對於彼此坐在不同位置。"},{"en":"The moon’s position changes relative to the sun, which creates visible phases.","zh":"月亮相對於太陽的位置會改變，形成可見月相。"},{"en":"This phrase is useful when two things must be understood together.","zh":"當兩件事必須一起理解時，這個短語很有用。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":7},{"front":"historian of science","meaning":"科學史學家","examples":[{"en":"François Charette is a historian of science.","zh":"François Charette 是一位科學史學家。"},{"en":"A historian of science studies how scientific ideas, tools, and practices developed over time.","zh":"「historian of science」研究科學思想、工具和實踐如何隨時間發展。"},{"en":"A historian of science may examine old notebooks, instruments, and university records.","zh":"科學史學家可能檢查舊筆記本、儀器和大學記錄。"},{"en":"Historians of science help explain how past discoveries shaped modern knowledge.","zh":"科學史學家幫助解釋過去發現如何塑造現代知識。"},{"en":"This role connects history with scientific understanding.","zh":"這個角色把歷史與科學理解連繫起來。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":8},{"front":"write an editorial","meaning":"撰寫社論","examples":[{"en":"Charette wrote an editorial accompanying a new study.","zh":"Charette 撰寫了一篇伴隨新研究的社論。"},{"en":"To write an editorial means to write an article expressing analysis or opinion about an issue.","zh":"「write an editorial」意思是撰寫表達分析或意見的文章。"},{"en":"A newspaper editor may write an editorial about public transport problems.","zh":"報章編輯可能撰寫一篇關於公共交通問題的社論。"},{"en":"An editorial can guide readers by explaining why a study matters.","zh":"社論可以透過解釋研究為何重要來引導讀者。"},{"en":"Unlike a simple report, an editorial often includes interpretation.","zh":"與簡單報道不同，社論通常包含詮釋。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":8},{"front":"accompanying a new study","meaning":"伴隨一項新研究的","examples":[{"en":"The editorial accompanied a new study of the mechanism.","zh":"這篇社論伴隨一項關於該機械的新研究。"},{"en":"Accompanying a new study means appearing together with it to explain or discuss it.","zh":"「accompanying a new study」意思是與新研究一起出現，以解釋或討論它。"},{"en":"A chart accompanying a new study can help readers understand the data.","zh":"伴隨新研究的圖表可以幫助讀者理解數據。"},{"en":"An article accompanying a report may explain the main findings in simpler language.","zh":"伴隨報告的文章可能用較簡單語言解釋主要發現。"},{"en":"This phrase shows that one text or item supports another.","zh":"這個短語顯示一篇文本或一件物品支援另一項內容。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":8},{"front":"the journal Nature","meaning":"《自然》期刊","examples":[{"en":"The study was published in the journal Nature.","zh":"這項研究發表於《自然》期刊。"},{"en":"The journal Nature is a major scientific publication that publishes research studies.","zh":"《自然》期刊是一份重要科學刊物，發表研究論文。"},{"en":"Scientists often read journals like Nature to learn about new discoveries.","zh":"科學家常閱讀像《自然》這類期刊，以了解新發現。"},{"en":"If a study appears in a respected journal, readers may take it seriously.","zh":"如果研究刊登在受尊重的期刊，讀者可能會認真看待它。"},{"en":"The phrase identifies where the study was officially published.","zh":"這個短語指出該研究正式發表在哪裡。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":8},{"front":"in this case","meaning":"在這個情況下","examples":[{"en":"In this case, the device had more than 30 gears.","zh":"在這個情況下，這件裝置有超過三十個齒輪。"},{"en":"In this case means in this particular example or situation.","zh":"「in this case」意思是在這個特定例子或情況下。"},{"en":"Some students need extra time; in this case, the teacher should adjust the task.","zh":"有些學生需要額外時間；在這個情況下，老師應調整任務。"},{"en":"A rule may work generally, but in this case it created an unfair result.","zh":"一條規則可能一般有效，但在這個情況下造成不公平結果。"},{"en":"The phrase narrows discussion to the specific example being considered.","zh":"這個短語把討論收窄到正在考慮的具體例子。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":8},{"front":"computer animation","meaning":"電腦動畫","examples":[{"en":"Computer animation helps researchers see how the device worked.","zh":"電腦動畫幫助研究人員看見這件裝置如何運作。"},{"en":"Computer animation uses digital images to show movement or change.","zh":"「computer animation」使用數碼圖像展示運動或變化。"},{"en":"Teachers use computer animation to explain how the heart pumps blood.","zh":"老師使用電腦動畫解釋心臟如何泵血。"},{"en":"Computer animation can make hidden machine parts easier to understand.","zh":"電腦動畫可以令隱藏的機器零件更容易理解。"},{"en":"It is useful when real objects are too fragile, small, or incomplete to move.","zh":"當真實物件太脆弱、太小或不完整而不能移動時，它很有用。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":8},{"front":"mind-boggling","meaning":"令人難以置信的；令人震驚的","examples":[{"en":"The mechanism’s complexity is mind-boggling.","zh":"這件機械的複雜程度令人難以置信。"},{"en":"Mind-boggling means extremely surprising, confusing, or hard to believe.","zh":"「mind-boggling」意思是極其令人驚訝、困惑或難以相信。"},{"en":"The amount of data produced every day is mind-boggling.","zh":"每天產生的數據量令人震驚。"},{"en":"A mind-boggling puzzle can make students feel lost at first but curious later.","zh":"一道令人難以置信的謎題起初可能令學生迷失，但之後令他們好奇。"},{"en":"The word is informal and emphasises strong amazement.","zh":"這個字較口語化，強調強烈驚訝。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":8},{"front":"there is no doubt","meaning":"毫無疑問","examples":[{"en":"There is no doubt that the mechanism was a technological masterpiece.","zh":"毫無疑問，這件機械是一件技術傑作。"},{"en":"There is no doubt means something is certain or strongly accepted.","zh":"「there is no doubt」意思是某事確定或被強烈接受。"},{"en":"There is no doubt that regular practice improves language learning.","zh":"毫無疑問，定期練習能改善語言學習。"},{"en":"When many tests give the same result, there is no doubt about the conclusion.","zh":"當多次測試得到相同結果，結論就毫無疑問。"},{"en":"This phrase shows confidence, so it should be used only when evidence is strong.","zh":"這個短語顯示信心，所以只應在證據強時使用。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":8},{"front":"technological masterpiece","meaning":"技術傑作","examples":[{"en":"The Antikythera Mechanism was a technological masterpiece.","zh":"安提基特拉機械是一件技術傑作。"},{"en":"A technological masterpiece is a brilliantly designed machine or invention.","zh":"「technological masterpiece」是設計極出色的機器或發明。"},{"en":"A bridge can be called a technological masterpiece if it solves a difficult engineering problem elegantly.","zh":"如果一座橋優雅地解決困難工程問題，它可被稱為技術傑作。"},{"en":"Technological masterpieces often combine skill, knowledge, and creativity.","zh":"技術傑作通常結合技能、知識和創意。"},{"en":"The phrase praises a work for its technical achievement.","zh":"這個短語讚揚某作品的技術成就。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":8},{"front":"be built between","meaning":"建於……之間","examples":[{"en":"The device was probably built between 100 and 140 BC.","zh":"這件裝置可能建於公元前100年至140年之間。"},{"en":"To be built between two dates means to be made sometime within that time range.","zh":"「be built between」兩個日期，意思是在該時間範圍內某時製造或建成。"},{"en":"The old theatre was built between 1900 and 1910.","zh":"那座舊劇院建於1900年至1910年之間。"},{"en":"If a temple was built between two historical periods, it may show mixed styles.","zh":"如果神廟建於兩個歷史時期之間，它可能顯示混合風格。"},{"en":"This phrase gives an estimated period when the exact year is unknown.","zh":"當準確年份未知時，這個短語提供估計時期。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":8},{"front":"the understanding of astronomy","meaning":"對天文學的理解","examples":[{"en":"The device displays an advanced understanding of astronomy.","zh":"這件裝置展示了對天文學的先進理解。"},{"en":"The understanding of astronomy means knowledge of how objects in the sky move and relate to one another.","zh":"「the understanding of astronomy」指對天空物體如何運動及彼此關聯的認識。"},{"en":"A calendar can show a society’s understanding of astronomy.","zh":"曆法可以顯示一個社會對天文學的理解。"},{"en":"Improved understanding of astronomy helped people predict seasons and eclipses.","zh":"對天文學理解的改善幫助人們預測季節和日月食。"},{"en":"The mechanism suggests that ancient experts had strong astronomical knowledge.","zh":"這件機械顯示古代專家有強大的天文知識。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":8},{"front":"be based on knowledge developed by","meaning":"基於由……發展出來的知識","examples":[{"en":"The mechanism was based on knowledge developed by the Babylonians.","zh":"這件機械基於由巴比倫人發展出來的知識。"},{"en":"To be based on knowledge developed by someone means to use ideas or discoveries that group created earlier.","zh":"「be based on knowledge developed by」某人，意思是使用該群體早前創造的思想或發現。"},{"en":"Modern medicine is often based on knowledge developed by many generations of researchers.","zh":"現代醫學常基於多代研究人員發展出來的知識。"},{"en":"If a machine is based on earlier knowledge, it shows how ideas travel across cultures.","zh":"如果一部機器基於早期知識，它顯示思想如何跨文化傳播。"},{"en":"This phrase highlights intellectual inheritance, not just invention.","zh":"這個短語強調知識傳承，而不只是發明。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":9},{"front":"the Babylonians","meaning":"巴比倫人","examples":[{"en":"The astronomical knowledge may have been developed by the Babylonians.","zh":"這些天文知識可能由巴比倫人發展出來。"},{"en":"The Babylonians were people from ancient Babylonia, known for mathematics, astronomy, and record-keeping.","zh":"「the Babylonians」是古巴比倫的人，以數學、天文學和記錄保存聞名。"},{"en":"Students may study the Babylonians when learning about early civilisations.","zh":"學生學習早期文明時，可能會研究巴比倫人。"},{"en":"Babylonian observations of the sky influenced later astronomical traditions.","zh":"巴比倫人對天空的觀察影響了後來的天文傳統。"},{"en":"Mentioning the Babylonians shows that Greek science may have drawn on older knowledge.","zh":"提到巴比倫人顯示希臘科學可能吸收了更早的知識。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":9},{"front":"professor of astrophysics","meaning":"天體物理學教授","examples":[{"en":"Mike Edmunds is a professor of astrophysics at Cardiff University.","zh":"Mike Edmunds 是卡迪夫大學的天體物理學教授。"},{"en":"A professor of astrophysics teaches and researches the physics of stars, planets, galaxies, and space.","zh":"「professor of astrophysics」教授和研究恆星、行星、星系和太空的物理學。"},{"en":"A professor of astrophysics may explain eclipses using mathematics and observation.","zh":"天體物理學教授可能用數學和觀察解釋日月食。"},{"en":"Such a professor can help study ancient devices that model the sky.","zh":"這類教授可以幫助研究模擬天空的古代裝置。"},{"en":"The title shows that Edmunds has specialist knowledge relevant to the mechanism.","zh":"這個銜頭顯示 Edmunds 擁有與該機械相關的專門知識。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":9},{"front":"Cardiff University","meaning":"卡迪夫大學","examples":[{"en":"Mike Edmunds works at Cardiff University in Britain.","zh":"Mike Edmunds 在英國卡迪夫大學工作。"},{"en":"Cardiff University is a university in the United Kingdom.","zh":"卡迪夫大學是英國的一所大學。"},{"en":"A researcher from Cardiff University may work with museums and international scholars.","zh":"來自卡迪夫大學的研究人員可能與博物館和國際學者合作。"},{"en":"Universities like Cardiff University support research by providing experts, equipment, and students.","zh":"像卡迪夫大學這樣的大學透過提供專家、設備和學生支持研究。"},{"en":"The name identifies Edmunds’s academic institution.","zh":"這個名稱指出 Edmunds 所屬的學術機構。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":9},{"front":"lead a research team","meaning":"帶領研究團隊","examples":[{"en":"Mike Edmunds led a research team studying the mechanism.","zh":"Mike Edmunds 帶領一個研究該機械的研究團隊。"},{"en":"To lead a research team means to guide and manage a group of researchers.","zh":"「lead a research team」意思是指導和管理一組研究人員。"},{"en":"A professor may lead a research team investigating climate change.","zh":"教授可能帶領研究團隊調查氣候變化。"},{"en":"Leading a research team involves organising tasks, checking evidence, and sharing results.","zh":"帶領研究團隊包括安排任務、檢查證據和分享結果。"},{"en":"The phrase shows that the work was collaborative, not done by one person alone.","zh":"這個短語顯示工作是合作完成的，而不是由一個人獨自完成。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":9},{"front":"reconstruct","meaning":"重建；復原","examples":[{"en":"The team reconstructed what the gear mechanism would have looked like.","zh":"團隊重建了齒輪機制原本可能的樣子。"},{"en":"To reconstruct something means to build or work out what it was like from evidence.","zh":"「reconstruct」某物，意思是根據證據重建或推斷它原本的樣子。"},{"en":"Police may reconstruct an accident by studying photos and witness statements.","zh":"警方可能透過研究照片和證人口供來重建意外經過。"},{"en":"Archaeologists reconstruct broken objects to understand their original shape.","zh":"考古學家復原破碎物件，以理解其原本形狀。"},{"en":"Reconstructing the past requires evidence, not imagination alone.","zh":"重建過去需要證據，而不只是想像。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":9},{"front":"gear mechanism","meaning":"齒輪機制","examples":[{"en":"The researchers reconstructed the gear mechanism.","zh":"研究人員重建了齒輪機制。"},{"en":"A gear mechanism is a system of gears that produces controlled movement or calculation.","zh":"「gear mechanism」是由齒輪組成、產生受控運動或計算的系統。"},{"en":"A clock’s gear mechanism moves the hands at the correct speed.","zh":"時鐘的齒輪機制讓指針以正確速度移動。"},{"en":"If a gear mechanism is damaged, the device may show wrong information.","zh":"如果齒輪機制受損，裝置可能顯示錯誤資訊。"},{"en":"Understanding the gear mechanism helps researchers understand the whole machine.","zh":"理解齒輪機制幫助研究人員理解整部機器。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":9},{"front":"advanced three-dimensional imaging technology","meaning":"先進三維成像技術","examples":[{"en":"The team used advanced three-dimensional imaging technology.","zh":"團隊使用了先進三維成像技術。"},{"en":"Advanced three-dimensional imaging technology creates detailed 3D images of objects, including hidden parts.","zh":"「advanced three-dimensional imaging technology」能製作物件的詳細三維圖像，包括隱藏部分。"},{"en":"Doctors use advanced three-dimensional imaging technology to examine organs without surgery.","zh":"醫生使用先進三維成像技術在不做手術的情況下檢查器官。"},{"en":"This technology can reveal inscriptions or structures that are too damaged to see clearly.","zh":"這種技術可以揭示因損壞而難以清楚看見的銘文或結構。"},{"en":"It helps researchers study fragile objects without breaking them open.","zh":"它幫助研究人員在不打開或破壞脆弱物件的情況下研究它們。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":9},{"front":"decode inscriptions","meaning":"解讀銘文","examples":[{"en":"The researchers decoded a number of the inscriptions.","zh":"研究人員解讀了若干銘文。"},{"en":"To decode inscriptions means to read and interpret carved or written text that is hard to understand.","zh":"「decode inscriptions」意思是閱讀和詮釋難以理解的刻字或文字。"},{"en":"Scholars may decode inscriptions on old stone tablets by comparing letters and symbols.","zh":"學者可能透過比較字母和符號來解讀舊石板上的銘文。"},{"en":"Decoding inscriptions can reveal names, dates, instructions, or purposes.","zh":"解讀銘文可以揭示名稱、日期、說明或用途。"},{"en":"The phrase suggests careful analysis, not simply reading modern text.","zh":"這個短語暗示仔細分析，而不是簡單閱讀現代文字。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":9},{"front":"explore the relationship between","meaning":"探究……之間的關係","examples":[{"en":"The mechanism explores the relationship between lunar months and calendar years.","zh":"這件機械探究陰曆月份與曆年之間的關係。"},{"en":"To explore the relationship between two things means to examine how they are connected.","zh":"「explore the relationship between」兩件事，意思是研究它們如何連繫。"},{"en":"A teacher may explore the relationship between sleep and exam performance.","zh":"老師可能探究睡眠與考試表現之間的關係。"},{"en":"Scientists explore the relationship between temperature and crop growth to predict harvests.","zh":"科學家探究溫度與農作物生長之間的關係，以預測收成。"},{"en":"The phrase focuses on connection, pattern, or influence.","zh":"這個短語集中於關聯、模式或影響。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":9},{"front":"lunar months","meaning":"陰曆月份；月相月份","examples":[{"en":"The mechanism shows the relationship between lunar months and calendar years.","zh":"這件機械顯示陰曆月份與曆年之間的關係。"},{"en":"Lunar months are months measured by the moon’s cycle, especially from one phase to the next.","zh":"「lunar months」是根據月亮週期計算的月份，尤其是從一個月相到下一個月相。"},{"en":"Some festivals are set according to lunar months rather than fixed solar dates.","zh":"有些節日根據陰曆月份而不是固定陽曆日期設定。"},{"en":"Because lunar months do not match calendar years exactly, calendars need adjustment.","zh":"因為陰曆月份與曆年不完全吻合，曆法需要調整。"},{"en":"The phrase is important when discussing moon-based timekeeping.","zh":"討論以月亮為基礎的計時時，這個短語很重要。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":9},{"front":"calendar years","meaning":"曆年","examples":[{"en":"The mechanism relates lunar months to calendar years.","zh":"這件機械把陰曆月份與曆年聯繫起來。"},{"en":"Calendar years are years as organised by a calendar system.","zh":"「calendar years」是由曆法系統安排的年份。"},{"en":"Schools usually plan terms according to calendar years or academic years.","zh":"學校通常根據曆年或學年安排學期。"},{"en":"Because natural cycles do not always fit calendar years perfectly, calendars need rules and corrections.","zh":"因為自然週期不總是完全符合曆年，曆法需要規則和修正。"},{"en":"Calendar years help societies organise work, festivals, taxes, and records.","zh":"曆年幫助社會安排工作、節日、稅務和記錄。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":10},{"front":"cycle through its phases","meaning":"經歷其不同月相","examples":[{"en":"The moon cycles through its phases from full moon to full moon.","zh":"月亮從一次滿月到下一次滿月，經歷其不同月相。"},{"en":"To cycle through its phases means to move repeatedly through a set of stages.","zh":"「cycle through its phases」意思是反覆經歷一組階段。"},{"en":"A traffic light cycles through its colours throughout the day.","zh":"交通燈整天反覆經歷不同燈色。"},{"en":"The moon’s changing appearance helps people see how it cycles through its phases.","zh":"月亮外觀的改變幫助人們看見它如何經歷不同月相。"},{"en":"The phrase emphasises repeated movement from one stage to another.","zh":"這個短語強調從一個階段到另一個階段的重複變化。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":10},{"front":"full moon","meaning":"滿月","examples":[{"en":"A lunar month can be measured from full moon to full moon.","zh":"陰曆月份可以從一次滿月量度到下一次滿月。"},{"en":"A full moon is the phase when the moon appears as a complete bright circle.","zh":"「full moon」是月亮看起來像完整明亮圓形的月相。"},{"en":"People may notice a full moon more easily because it lights the night sky.","zh":"人們可能更容易注意到滿月，因為它照亮夜空。"},{"en":"Some calendars and festivals are connected with the full moon.","zh":"有些曆法和節日與滿月有關。"},{"en":"Full moon is one clear point in the moon’s repeating cycle.","zh":"滿月是月亮重複週期中的一個清楚時間點。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":10},{"front":"be cut precisely","meaning":"被精確切割","examples":[{"en":"The gears had to be cut precisely.","zh":"齒輪必須被精確切割。"},{"en":"If something is cut precisely, it is shaped with exact measurements.","zh":"如果某物被精確切割，意思是它按照準確尺寸成形。"},{"en":"A tailor cuts cloth precisely so the suit fits the customer.","zh":"裁縫精確切割布料，使西裝合身。"},{"en":"If gears are not cut precisely, they may not turn smoothly.","zh":"如果齒輪沒有被精確切割，它們可能無法順暢轉動。"},{"en":"Precision matters when small errors can stop a machine from working.","zh":"當小錯誤可以令機器停止運作時，精確度很重要。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":10},{"front":"reflect a complex relationship","meaning":"反映複雜關係","examples":[{"en":"The gears were cut to reflect a complex astronomical relationship.","zh":"這些齒輪被切割成能反映複雜天文關係的形狀。"},{"en":"To reflect a complex relationship means to show a difficult connection accurately.","zh":"「reflect a complex relationship」意思是準確顯示困難的關聯。"},{"en":"A map may reflect a complex relationship between roads, rivers, and neighbourhoods.","zh":"地圖可能反映道路、河流和社區之間的複雜關係。"},{"en":"If a model reflects a complex relationship well, it helps people understand what they cannot see directly.","zh":"如果模型能很好反映複雜關係，它就能幫助人理解無法直接看見的東西。"},{"en":"The phrase suggests that design was based on careful knowledge.","zh":"這個短語暗示設計基於仔細知識。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":10},{"front":"by turning","meaning":"透過轉動","examples":[{"en":"By turning the gear mechanism, a person could check the sky on a past date.","zh":"透過轉動齒輪機制，一個人可以查看過去某日的天空。"},{"en":"By turning means through the action of rotating something.","zh":"「by turning」意思是透過旋轉某物這個動作。"},{"en":"By turning the handle, you can open the old window.","zh":"透過轉動手柄，你可以打開舊窗。"},{"en":"A user changed the display by turning a wheel rather than pressing a button.","zh":"使用者透過轉動輪子而不是按按鈕來改變顯示。"},{"en":"This phrase explains the physical action that produces a result.","zh":"這個短語解釋產生結果的實際動作。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":10},{"front":"epicyclic gears","meaning":"周轉齒輪","examples":[{"en":"The mechanism included a beautiful system of epicyclic gears.","zh":"這件機械包含一套精巧的周轉齒輪系統。"},{"en":"Epicyclic gears are gears arranged so that some gears rotate around others.","zh":"「epicyclic gears」是一些齒輪圍繞其他齒輪旋轉的齒輪安排。"},{"en":"Some automatic car transmissions use epicyclic gears to change speed smoothly.","zh":"有些自動車波箱使用周轉齒輪平順改變速度。"},{"en":"Epicyclic gears can create complex motion in a small space.","zh":"周轉齒輪可以在小空間中產生複雜運動。"},{"en":"In the mechanism, they helped model the moon’s uneven movement.","zh":"在這件機械中，它們幫助模擬月亮不均勻的運動。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":10},{"front":"factor in","meaning":"把……計算在內","examples":[{"en":"The epicyclic gears factored in the moon’s elliptical orbit.","zh":"周轉齒輪把月亮的橢圓軌道計算在內。"},{"en":"To factor in something means to include it when making a calculation or decision.","zh":"「factor in」某事，意思是在計算或決定時把它包括在內。"},{"en":"When planning a trip, you should factor in traffic and bad weather.","zh":"規劃旅程時，你應把交通和壞天氣計算在內。"},{"en":"If a budget does not factor in repair costs, it may be too low.","zh":"如果預算沒有把維修費計算在內，它可能太低。"},{"en":"This phrase shows that an extra condition has been considered.","zh":"這個短語顯示額外條件已被考慮。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":10},{"front":"elliptical orbit","meaning":"橢圓軌道","examples":[{"en":"The mechanism accounted for the elliptical orbit of the moon.","zh":"這件機械考慮了月亮的橢圓軌道。"},{"en":"An elliptical orbit is an oval-shaped path followed by an object in space.","zh":"「elliptical orbit」是太空物體沿著的橢圓形路徑。"},{"en":"Planets do not move in perfect circles; they follow elliptical orbits.","zh":"行星不是沿完美圓形移動；它們沿橢圓軌道運行。"},{"en":"Because the moon’s orbit is elliptical, its speed and distance can change.","zh":"因為月亮軌道是橢圓形，它的速度和距離會改變。"},{"en":"Understanding elliptical orbit helps explain why celestial motion is not perfectly even.","zh":"理解橢圓軌道有助解釋為何天體運動並非完全均勻。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":10},{"front":"check what the sky would have looked like","meaning":"查看天空曾經會是甚麼樣子","examples":[{"en":"A user could check what the sky would have looked like in the past.","zh":"使用者可以查看過去天空曾經會是甚麼樣子。"},{"en":"To check what the sky would have looked like means to see a model of the sky at another time.","zh":"「check what the sky would have looked like」意思是查看另一時間天空的模型。"},{"en":"Astronomy software lets students check what the sky would have looked like during an eclipse.","zh":"天文軟件讓學生查看日月食期間天空曾經會是甚麼樣子。"},{"en":"Historians may check what the sky would have looked like to understand ancient records.","zh":"歷史學家可能查看天空曾經會是甚麼樣子，以理解古代記錄。"},{"en":"The phrase refers to reconstruction, not actual time travel.","zh":"這個短語指重建，而不是真正時光旅行。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":10},{"front":"on a date in the past","meaning":"在過去某一天","examples":[{"en":"The device could show the sky on a date in the past.","zh":"這件裝置可以顯示過去某一天的天空。"},{"en":"On a date in the past means on a specific day before the present.","zh":"「on a date in the past」意思是在現在之前的某個具體日期。"},{"en":"A photo may show what a street looked like on a date in the past.","zh":"一張照片可能顯示街道在過去某一天的樣子。"},{"en":"If records exist, researchers can study weather on a date in the past.","zh":"如果有記錄，研究人員可以研究過去某一天的天氣。"},{"en":"The phrase focuses on one particular past day, not the past in general.","zh":"這個短語集中於一個特定的過去日子，而不是一般過去。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":10},{"front":"appear in the future","meaning":"在未來出現","examples":[{"en":"The mechanism could show how the sky would appear in the future.","zh":"這件機械可以顯示天空在未來會如何出現。"},{"en":"Appear in the future means look or become visible at a later time.","zh":"「appear in the future」意思是在較後時間看起來如何或變得可見。"},{"en":"A weather model can show how clouds may appear in the future.","zh":"天氣模型可以顯示雲在未來可能如何出現。"},{"en":"If astronomers know orbital patterns, they can predict how planets will appear in the future.","zh":"如果天文學家知道軌道模式，他們可以預測行星在未來會如何出現。"},{"en":"The phrase is about prediction based on patterns.","zh":"這個短語關於基於模式的預測。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":11},{"front":"be encased in","meaning":"被裝在……之中","examples":[{"en":"The mechanism was encased in a box with doors.","zh":"這件機械被裝在一個有門的盒子之中。"},{"en":"If something is encased in another object, it is enclosed or covered by it.","zh":"如果某物被 encased in 另一物中，意思是它被包圍或覆蓋在其中。"},{"en":"A phone may be encased in a protective cover to prevent damage.","zh":"手機可能被裝在保護殼中，以防損壞。"},{"en":"When a fragile object is encased in glass, visitors can see it without touching it.","zh":"當脆弱物件被裝在玻璃中，訪客可以觀看而不觸摸。"},{"en":"Encased in describes protection, containment, or presentation.","zh":"「encased in」描述保護、包裹或展示。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":11},{"front":"covered with inscriptions","meaning":"刻滿銘文","examples":[{"en":"The doors were covered with inscriptions.","zh":"這些門刻滿銘文。"},{"en":"Covered with inscriptions means having many written or carved words on the surface.","zh":"「covered with inscriptions」意思是表面有許多書寫或刻上的文字。"},{"en":"A monument covered with inscriptions may list the names of important people.","zh":"一座刻滿銘文的紀念碑可能列出重要人物的名字。"},{"en":"If a box is covered with inscriptions, it may contain instructions or explanations.","zh":"如果盒子刻滿銘文，它可能包含說明或解釋。"},{"en":"The phrase suggests the writing was spread across much of the surface.","zh":"這個短語暗示文字遍布表面大部分位置。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":11},{"front":"a sort of instruction manual","meaning":"一種使用說明","examples":[{"en":"The inscriptions formed a sort of instruction manual.","zh":"這些銘文形成一種使用說明。"},{"en":"A sort of instruction manual is something that gives guidance like a manual, even if it is not a modern booklet.","zh":"「a sort of instruction manual」是像說明書一樣提供指引的東西，即使它不是現代小冊子。"},{"en":"A recipe card is a sort of instruction manual for cooking a dish.","zh":"食譜卡是一種烹調菜式的使用說明。"},{"en":"Labels on a machine can act as a sort of instruction manual when they explain what each button does.","zh":"機器上的標籤如果解釋每個按鈕的功能，就可以充當一種使用說明。"},{"en":"The phrase suggests the inscriptions helped users operate the device.","zh":"這個短語暗示銘文幫助使用者操作裝置。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":11},{"front":"pointers indicating","meaning":"指示……的指針","examples":[{"en":"Inside the front door were pointers indicating the date and celestial positions.","zh":"前門內有指示日期和天體位置的指針。"},{"en":"Pointers indicating something are moving markers that show specific information.","zh":"「pointers indicating」某物，是顯示特定資訊的移動標記。"},{"en":"A clock has pointers indicating the hour and minute.","zh":"時鐘有指示小時和分鐘的指針。"},{"en":"If pointers indicate the wrong position, the user may read the device incorrectly.","zh":"如果指針指示錯誤位置，使用者可能讀錯裝置。"},{"en":"The phrase connects a visible marker with the information it shows.","zh":"這個短語把可見標記與它顯示的資訊連繫起來。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":11},{"front":"the position of","meaning":"……的位置","examples":[{"en":"The pointers showed the position of the sun, moon and zodiac.","zh":"指針顯示太陽、月亮和黃道十二宮的位置。"},{"en":"The position of something means where it is located in relation to other things.","zh":"「the position of」某物，意思是它相對於其他事物所在的位置。"},{"en":"A map shows the position of a school, park, and bus stop.","zh":"地圖顯示學校、公園和巴士站的位置。"},{"en":"If the position of the moon changes, its appearance from Earth also changes.","zh":"如果月亮的位置改變，從地球看到的外觀也會改變。"},{"en":"The phrase is useful for describing location in space or on a diagram.","zh":"這個短語適合描述空間中或圖表上的位置。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":11},{"front":"zodiac","meaning":"黃道十二宮","examples":[{"en":"The mechanism showed the position of the zodiac.","zh":"這件機械顯示黃道十二宮的位置。"},{"en":"The zodiac is a band of the sky divided into twelve signs used in astronomy and astrology.","zh":"「zodiac」是天空中的一條帶狀區域，分成十二個星座，用於天文學和占星術。"},{"en":"Ancient sky charts often included the zodiac to organise celestial positions.","zh":"古代星圖常包括黃道十二宮，以整理天體位置。"},{"en":"If a device shows the zodiac, it helps users locate the sun, moon, or planets against a familiar sky pattern.","zh":"如果裝置顯示黃道十二宮，它可以幫助使用者按照熟悉的天空模式定位太陽、月亮或行星。"},{"en":"The zodiac was important in ancient systems for connecting time and the heavens.","zh":"黃道十二宮在古代把時間與天空連繫起來的系統中很重要。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":11},{"front":"reveal the relationship between","meaning":"顯示……之間的關係","examples":[{"en":"Opening the back door revealed the relationship between years and lunar months.","zh":"打開後門顯示年份與陰曆月份之間的關係。"},{"en":"To reveal the relationship between two things means to show how they are connected.","zh":"「reveal the relationship between」兩件事，意思是顯示它們如何相連。"},{"en":"A chart can reveal the relationship between exercise and heart health.","zh":"圖表可以顯示運動與心臟健康之間的關係。"},{"en":"If data reveals a relationship between sleep and grades, students may change their habits.","zh":"如果數據顯示睡眠與成績之間的關係，學生可能改變習慣。"},{"en":"The phrase suggests that the connection was hidden or not obvious before.","zh":"這個短語暗示關聯之前是隱藏或不明顯的。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":11},{"front":"predict eclipses","meaning":"預測日食或月食","examples":[{"en":"The mechanism could predict eclipses.","zh":"這件機械能夠預測日食或月食。"},{"en":"To predict eclipses means to calculate when the sun or moon will be blocked from view.","zh":"「predict eclipses」意思是計算太陽或月亮何時會被遮擋。"},{"en":"Ancient astronomers tried to predict eclipses because such events seemed powerful and unusual.","zh":"古代天文學家試圖預測日月食，因為這類事件看似強大而不尋常。"},{"en":"Accurate eclipse prediction requires knowledge of the sun, moon, and Earth’s positions.","zh":"準確預測日月食需要知道太陽、月亮和地球的位置。"},{"en":"The ability to predict eclipses shows advanced astronomical calculation.","zh":"能夠預測日月食顯示先進的天文計算。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":11},{"front":"occur","meaning":"發生","examples":[{"en":"The mechanism helped show when eclipses would occur.","zh":"這件機械幫助顯示日月食何時會發生。"},{"en":"To occur means to happen or take place.","zh":"「occur」意思是發生或出現。"},{"en":"Accidents may occur when drivers are tired or distracted.","zh":"當司機疲倦或分心時，意外可能發生。"},{"en":"If heavy rain occurs during rush hour, traffic can become much slower.","zh":"如果大雨在繁忙時間發生，交通可能變得慢很多。"},{"en":"Occur is more formal than happen and is common in academic writing.","zh":"「occur」比 happen 較正式，常見於學術寫作。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":11},{"front":"the rising and setting of stars","meaning":"星星的升起與落下","examples":[{"en":"Eclipses were related to the rising and setting of stars.","zh":"日月食與星星的升起與落下有關。"},{"en":"The rising and setting of stars means stars appearing above and disappearing below the horizon.","zh":"「the rising and setting of stars」指星星出現在地平線上方及消失在地平線下方。"},{"en":"Ancient farmers watched the rising and setting of stars to mark seasons.","zh":"古代農民觀察星星的升起與落下來標記季節。"},{"en":"If people know the rising and setting of stars, they can use the sky as a calendar.","zh":"如果人們知道星星的升起與落下，就可以把天空當作曆法使用。"},{"en":"This phrase links everyday observation with astronomical timekeeping.","zh":"這個短語把日常觀察與天文計時連繫起來。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":11},{"front":"religious experiences","meaning":"宗教體驗","examples":[{"en":"Dates and celestial events could be linked to religious experiences.","zh":"日期和天體事件可能與宗教體驗相連。"},{"en":"Religious experiences are events or feelings connected with faith, worship, or the sacred.","zh":"「religious experiences」是與信仰、崇拜或神聖事物相關的事件或感受。"},{"en":"A festival, prayer, or eclipse may become part of religious experiences for a community.","zh":"節日、祈禱或日月食可能成為一個社區的宗教體驗一部分。"},{"en":"If people link sky events with religion, astronomy can influence ceremonies and beliefs.","zh":"如果人們把天空事件與宗教連繫起來，天文學可以影響儀式和信仰。"},{"en":"The phrase shows that celestial events had social and spiritual meaning.","zh":"這個短語顯示天體事件具有社會和精神意義。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":12},{"front":"directly help","meaning":"直接有幫助","examples":[{"en":"The mechanism would directly help with astronomical calculations.","zh":"這件機械會對天文計算直接有幫助。"},{"en":"To directly help means to assist in a clear and immediate way.","zh":"「directly help」意思是以清楚而即時的方式提供幫助。"},{"en":"A calculator can directly help students check arithmetic.","zh":"計算機可以直接幫助學生核對算術。"},{"en":"A map directly helps travellers find the correct route.","zh":"地圖直接幫助旅客找到正確路線。"},{"en":"The phrase suggests the help is practical, not only symbolic.","zh":"這個短語暗示幫助是實際的，而不只是象徵性的。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":12},{"front":"mechanical computer","meaning":"機械電腦","examples":[{"en":"Yanis Bitsakis described the device as a mechanical computer.","zh":"Yanis Bitsakis 把這件裝置描述為機械電腦。"},{"en":"A mechanical computer is a machine that uses physical parts to calculate or display information.","zh":"「mechanical computer」是使用物理部件計算或顯示資訊的機器。"},{"en":"Old adding machines can be examples of mechanical computers.","zh":"舊式加數機可以是機械電腦的例子。"},{"en":"A mechanical computer does not need electronic circuits to perform calculations.","zh":"機械電腦不需要電子電路也能進行計算。"},{"en":"Calling the device a mechanical computer shows that it processed information through gears.","zh":"把該裝置稱為機械電腦，顯示它透過齒輪處理資訊。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":12},{"front":"turn the handle","meaning":"轉動手柄","examples":[{"en":"A user could turn the handle and see a date on the front.","zh":"使用者可以轉動手柄，並在正面看見日期。"},{"en":"To turn the handle means to rotate a handle by hand.","zh":"「turn the handle」意思是用手旋轉手柄。"},{"en":"You may turn the handle of an old door to open it.","zh":"你可能轉動舊門的手柄來開門。"},{"en":"When a user turns the handle, connected gears may begin to move.","zh":"當使用者轉動手柄，相連的齒輪可能開始移動。"},{"en":"The phrase describes a simple physical action that controls a device.","zh":"這個短語描述控制裝置的簡單實際動作。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":12},{"front":"require collaboration among","meaning":"需要……之間合作","examples":[{"en":"Building the device required collaboration among different experts.","zh":"製造這件裝置需要不同專家之間合作。"},{"en":"To require collaboration among people means to need them to work together.","zh":"「require collaboration among」某些人，意思是需要他們一起工作。"},{"en":"Building a hospital requires collaboration among doctors, architects, engineers, and managers.","zh":"建造醫院需要醫生、建築師、工程師和管理者之間合作。"},{"en":"If a project requires collaboration among specialists, one person cannot complete it alone.","zh":"如果一個項目需要專家之間合作，一個人無法獨自完成。"},{"en":"The phrase highlights teamwork across different skills.","zh":"這個短語強調不同技能之間的團隊合作。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":12},{"front":"astronomers","meaning":"天文學家","examples":[{"en":"Astronomers may have helped build the mechanism.","zh":"天文學家可能曾協助製造這件機械。"},{"en":"Astronomers are scientists who study the sun, moon, stars, planets, and space.","zh":"「astronomers」是研究太陽、月亮、恆星、行星和太空的科學家。"},{"en":"Astronomers use observations and calculations to predict celestial events.","zh":"天文學家使用觀察和計算來預測天體事件。"},{"en":"If engineers build a sky model, astronomers can provide the necessary data.","zh":"如果工程師製造天空模型，天文學家可以提供所需數據。"},{"en":"In this passage, astronomers represent the knowledge side of the project.","zh":"在本文中，天文學家代表該項目的知識一方。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":12},{"front":"engineers","meaning":"工程師","examples":[{"en":"Engineers may have helped design the mechanism.","zh":"工程師可能曾協助設計這件機械。"},{"en":"Engineers design and build machines, structures, systems, or tools.","zh":"「engineers」設計和建造機器、結構、系統或工具。"},{"en":"Engineers make sure bridges, lifts, and machines work safely.","zh":"工程師確保橋樑、升降機和機器安全運作。"},{"en":"A complex device needs engineers because its parts must fit and move correctly.","zh":"複雜裝置需要工程師，因為其零件必須正確配合和移動。"},{"en":"Engineers turn ideas and calculations into practical objects.","zh":"工程師把想法和計算變成實際物件。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":12},{"front":"intellectuals","meaning":"知識分子","examples":[{"en":"Intellectuals may have contributed to the device.","zh":"知識分子可能對這件裝置作出貢獻。"},{"en":"Intellectuals are people who think deeply about ideas, knowledge, culture, or society.","zh":"「intellectuals」是深入思考思想、知識、文化或社會的人。"},{"en":"Intellectuals may write books, teach students, or discuss difficult questions.","zh":"知識分子可能寫書、教學生或討論困難問題。"},{"en":"A project may need intellectuals when it connects science, philosophy, and design.","zh":"當項目連接科學、哲學和設計時，可能需要知識分子。"},{"en":"The word suggests mental contribution rather than only manual work.","zh":"這個詞暗示智力上的貢獻，而不只是體力工作。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":12},{"front":"craftspeople","meaning":"工匠","examples":[{"en":"Craftspeople may have helped build the mechanism.","zh":"工匠可能曾協助製造這件機械。"},{"en":"Craftspeople are skilled workers who make things carefully by hand or with tools.","zh":"「craftspeople」是用手或工具仔細製作物件的熟練工人。"},{"en":"Craftspeople may work with metal, wood, stone, glass, or cloth.","zh":"工匠可能處理金屬、木材、石材、玻璃或布料。"},{"en":"A delicate machine needs craftspeople who can shape small parts accurately.","zh":"精細機器需要能準確製作小零件的工匠。"},{"en":"The term respects practical skill, not only academic knowledge.","zh":"這個詞尊重實用技能，而不只是學術知識。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":12},{"front":"overturn conventional ideas","meaning":"推翻傳統觀念","examples":[{"en":"The device overturned conventional ideas about the ancient Greeks.","zh":"這件裝置推翻了關於古希臘人的傳統觀念。"},{"en":"To overturn conventional ideas means to challenge and change commonly accepted beliefs.","zh":"「overturn conventional ideas」意思是挑戰並改變普遍接受的信念。"},{"en":"A new discovery can overturn conventional ideas about how people lived in the past.","zh":"新發現可以推翻關於過去人們如何生活的傳統觀念。"},{"en":"If evidence overturns conventional ideas, textbooks may need to be rewritten.","zh":"如果證據推翻傳統觀念，教科書可能需要重寫。"},{"en":"The phrase shows that the finding was not merely interesting but transformative.","zh":"這個短語顯示該發現不只是有趣，而是具轉化性。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":12},{"front":"conventional ideas","meaning":"傳統觀念","examples":[{"en":"Conventional ideas about ancient Greek science may be incomplete.","zh":"關於古希臘科學的傳統觀念可能並不完整。"},{"en":"Conventional ideas are common beliefs that many people accept without questioning deeply.","zh":"「conventional ideas」是許多人接受、但未必深入質疑的普遍信念。"},{"en":"Conventional ideas about success often focus too much on money and status.","zh":"關於成功的傳統觀念常過度集中於金錢和地位。"},{"en":"New evidence can show that conventional ideas are too simple.","zh":"新證據可以顯示傳統觀念過於簡單。"},{"en":"This phrase often appears when a writer wants to challenge old assumptions.","zh":"當作者想挑戰舊假設時，常會使用這個短語。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":12},{"front":"primarily ivory tower thinkers","meaning":"主要是象牙塔思想家","examples":[{"en":"The ancient Greeks were often seen as primarily ivory tower thinkers.","zh":"古希臘人常被視為主要是象牙塔思想家。"},{"en":"Primarily ivory tower thinkers means mostly people who think abstractly and stay away from practical work.","zh":"「primarily ivory tower thinkers」意思是主要從事抽象思考、遠離實際工作的人。"},{"en":"A professor may be unfairly called an ivory tower thinker if people think their ideas ignore real life.","zh":"如果人們認為某教授的想法忽略現實，他可能被不公平地稱為象牙塔思想家。"},{"en":"The mechanism challenges the view that Greeks were only ivory tower thinkers.","zh":"這件機械挑戰了希臘人只是象牙塔思想家的看法。"},{"en":"The phrase creates a contrast between theory and hands-on skill.","zh":"這個短語製造理論與親手技能之間的對比。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":13},{"front":"deign to","meaning":"屈尊去……","examples":[{"en":"Some thinkers did not deign to work with technical objects.","zh":"有些思想家不屈尊去處理技術性物件。"},{"en":"To deign to do something means to do something reluctantly because one feels too important for it.","zh":"「deign to」做某事，意思是因覺得自己太重要而不情願地屈尊去做。"},{"en":"A rude manager may not deign to answer basic questions from new staff.","zh":"無禮的經理可能不屈尊回答新員工的基本問題。"},{"en":"If scholars do not deign to examine practical tools, they may miss important history.","zh":"如果學者不屈尊檢查實用工具，他們可能錯過重要歷史。"},{"en":"The phrase often carries criticism of arrogance.","zh":"這個短語常帶有對傲慢的批評。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":13},{"front":"muddy their hands","meaning":"親自做實際工作；弄髒雙手","examples":[{"en":"The phrase muddy their hands means to do practical technical work.","zh":"「muddy their hands」這個短語意思是親自做實際技術工作。"},{"en":"To muddy their hands means to become involved in practical, physical, or messy work.","zh":"「muddy their hands」意思是參與實際、體力或麻煩的工作。"},{"en":"A manager who visits the factory floor is willing to muddy their hands.","zh":"走到工廠現場的經理願意親自做實際工作。"},{"en":"Researchers may need to muddy their hands by testing tools, not just reading texts.","zh":"研究人員可能需要親自測試工具，而不只是閱讀文本。"},{"en":"The phrase contrasts practical involvement with staying safely theoretical.","zh":"這個短語把實際參與與安全地停留在理論中作對比。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":13},{"front":"technical stuff","meaning":"技術性事物","examples":[{"en":"The device shows that ancient Greeks engaged with technical stuff.","zh":"這件裝置顯示古希臘人有接觸技術性事物。"},{"en":"Technical stuff means practical tools, machines, methods, or details connected with technology.","zh":"「technical stuff」指與技術相關的實用工具、機器、方法或細節。"},{"en":"Some students enjoy ideas but avoid technical stuff like wiring or coding.","zh":"有些學生喜歡想法，但避開接線或編程等技術性事物。"},{"en":"A project can fail if nobody understands the technical stuff behind it.","zh":"如果沒有人理解項目背後的技術性事物，項目可能失敗。"},{"en":"The phrase is informal and makes technical work sound concrete and practical.","zh":"這個短語較口語化，令技術工作聽起來具體而實際。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":13},{"front":"a reminder that","meaning":"提醒人們……","examples":[{"en":"The mechanism is a reminder that written texts show only part of history.","zh":"這件機械提醒人們，書面文本只顯示歷史的一部分。"},{"en":"A reminder that means something that makes people remember or realise an important point.","zh":"「a reminder that」意思是使人記起或意識到重要一點的事物。"},{"en":"A hospital bill is a reminder that healthcare costs can be serious.","zh":"醫療帳單提醒人們醫療費用可以很沉重。"},{"en":"A broken machine is a reminder that regular maintenance matters.","zh":"壞掉的機器提醒人們定期維修很重要。"},{"en":"This phrase introduces a lesson drawn from an example.","zh":"這個短語引出從例子中得出的教訓。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":13},{"front":"the study of history","meaning":"歷史研究","examples":[{"en":"The study of history often focuses on written texts.","zh":"歷史研究常集中於書面文本。"},{"en":"The study of history means examining past events, people, objects, and records.","zh":"「the study of history」意思是研究過去事件、人物、物件和記錄。"},{"en":"The study of history helps students understand why societies changed.","zh":"歷史研究幫助學生理解社會為何改變。"},{"en":"If the study of history ignores objects, it may miss practical parts of life.","zh":"如果歷史研究忽略物件，它可能錯過生活中的實際部分。"},{"en":"History can be studied through texts, buildings, tools, images, and memories.","zh":"歷史可以透過文本、建築、工具、圖像和記憶來研究。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":13},{"front":"written texts","meaning":"書面文本","examples":[{"en":"Written texts tell us only part of what happened.","zh":"書面文本只告訴我們當時發生事情的一部分。"},{"en":"Written texts are words recorded in books, letters, documents, inscriptions, or other written forms.","zh":"「written texts」是記錄在書籍、信件、文件、銘文或其他書寫形式中的文字。"},{"en":"Written texts can preserve laws, stories, accounts, and ideas.","zh":"書面文本可以保存法律、故事、記述和思想。"},{"en":"If historians rely only on written texts, they may miss people who did not write much.","zh":"如果歷史學家只依賴書面文本，他們可能錯過很少書寫的人。"},{"en":"Objects can sometimes reveal what written texts leave out.","zh":"物件有時可以揭示書面文本遺漏的內容。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":13},{"front":"a fraction of","meaning":"一小部分","examples":[{"en":"Written texts can tell us only a fraction of what went on.","zh":"書面文本只能告訴我們當時發生事情的一小部分。"},{"en":"A fraction of something means only a small part of the whole.","zh":"「a fraction of」某物，意思是整體中的一小部分。"},{"en":"The photo shows a fraction of the crowd, not everyone who attended.","zh":"這張照片只顯示人群的一小部分，而不是所有出席者。"},{"en":"If a report includes only a fraction of the data, the conclusion may be weak.","zh":"如果報告只包括數據的一小部分，結論可能薄弱。"},{"en":"This phrase reminds us that evidence can be incomplete.","zh":"這個短語提醒我們證據可能並不完整。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":13},{"front":"what went on","meaning":"當時發生的事","examples":[{"en":"Artefacts can reveal what went on at a particular time.","zh":"文物可以揭示某一特定時期當時發生的事。"},{"en":"What went on means what happened or what people were doing.","zh":"「what went on」意思是發生了什麼，或人們當時在做什麼。"},{"en":"A diary can show what went on inside a family during a difficult year.","zh":"日記可以顯示一個家庭在艱難年份中發生了什麼。"},{"en":"If cameras were broken, investigators may ask witnesses what went on.","zh":"如果攝影機壞了，調查人員可能詢問證人當時發生的事。"},{"en":"The phrase is informal but useful for describing past events.","zh":"這個短語較口語化，但適合描述過去事件。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":13},{"front":"at a particular time","meaning":"在某一特定時期","examples":[{"en":"Objects can show how people lived at a particular time.","zh":"物件可以顯示人們在某一特定時期如何生活。"},{"en":"At a particular time means during one specific period or moment.","zh":"「at a particular time」意思是在某個特定時期或時刻。"},{"en":"A school photo shows what students wore at a particular time.","zh":"學校照片顯示學生在某一特定時期穿什麼。"},{"en":"If prices are recorded at a particular time, they may not represent the whole year.","zh":"如果價格記錄於某一特定時期，它們未必代表全年。"},{"en":"This phrase helps limit discussion to a specific historical moment.","zh":"這個短語幫助把討論限制在特定歷史時刻。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":13},{"front":"future historian","meaning":"未來歷史學家","examples":[{"en":"A future historian might study both texts and machines from our time.","zh":"未來歷史學家可能研究我們這個時代的文本和機器。"},{"en":"A future historian is someone in the future who studies the past that is our present.","zh":"「future historian」是未來研究過去的人，而那個過去就是我們的現在。"},{"en":"A future historian may use social media posts to understand today’s daily life.","zh":"未來歷史學家可能使用社交媒體貼文來理解今天的日常生活。"},{"en":"If future historians find only official documents, they may miss ordinary people’s experiences.","zh":"如果未來歷史學家只找到官方文件，他們可能錯過普通人的經驗。"},{"en":"The phrase helps readers imagine how our own age may one day be studied.","zh":"這個短語幫助讀者想像我們的時代有一天會如何被研究。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":13},{"front":"philosophy texts","meaning":"哲學文本","examples":[{"en":"Philosophy texts would show what some scholars were thinking.","zh":"哲學文本會顯示一些學者在想什麼。"},{"en":"Philosophy texts are writings that discuss questions about knowledge, reality, ethics, and human life.","zh":"「philosophy texts」是討論知識、現實、倫理和人生問題的文字作品。"},{"en":"Students read philosophy texts to examine arguments rather than memorise facts only.","zh":"學生閱讀哲學文本以檢視論證，而不只是背誦事實。"},{"en":"Philosophy texts can reveal ideas, but not always the technology people used daily.","zh":"哲學文本可以揭示思想，但不總能顯示人們日常使用的技術。"},{"en":"The phrase contrasts abstract thinking with physical objects.","zh":"這個短語把抽象思考與實物作對比。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":14},{"front":"in our time","meaning":"在我們這個時代","examples":[{"en":"A future historian might encounter philosophy texts written in our time.","zh":"未來歷史學家可能遇到在我們這個時代寫成的哲學文本。"},{"en":"In our time means during the present age or the period in which we live.","zh":"「in our time」意思是在現在這個年代，或我們生活的時期。"},{"en":"In our time, smartphones have changed how people communicate.","zh":"在我們這個時代，智能手機改變了人們溝通的方式。"},{"en":"Objects made in our time may help future people understand our daily habits.","zh":"在我們這個時代製造的物件，可能幫助未來的人理解我們的日常習慣。"},{"en":"The phrase makes readers think about the present as future history.","zh":"這個短語令人把現在看成未來的歷史。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":14},{"front":"aircraft engine","meaning":"飛機引擎","examples":[{"en":"An aircraft engine could reveal how technology shaped everyday life.","zh":"飛機引擎可以揭示技術如何塑造日常生活。"},{"en":"An aircraft engine is the machine that provides power for an aircraft to fly.","zh":"「aircraft engine」是為飛機飛行提供動力的機器。"},{"en":"Mechanics inspect an aircraft engine carefully before long flights.","zh":"機械師在長途飛行前仔細檢查飛機引擎。"},{"en":"A damaged aircraft engine can delay passengers and create safety risks.","zh":"受損的飛機引擎可以延誤乘客並造成安全風險。"},{"en":"For historians, an aircraft engine can show the practical technology of an age.","zh":"對歷史學家來說，飛機引擎可以顯示一個時代的實用技術。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":14},{"front":"scholars","meaning":"學者","examples":[{"en":"The books would show what a few scholars were thinking.","zh":"這些書會顯示少數學者在想什麼。"},{"en":"Scholars are people who study a subject deeply, usually through research and writing.","zh":"「scholars」是透過研究和寫作深入研究某主題的人。"},{"en":"Scholars may spend years examining one historical question.","zh":"學者可能花多年研究一個歷史問題。"},{"en":"If only scholars leave records, we may know less about ordinary workers and families.","zh":"如果只有學者留下記錄，我們可能較少了解普通工人和家庭。"},{"en":"The word often refers to academic thinkers rather than practical makers.","zh":"這個詞常指學術思想家，而不是實際製作者。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":14},{"front":"a far better window into","meaning":"更能讓人了解……的窗口","examples":[{"en":"The engine would give a far better window into everyday technology.","zh":"這個引擎更能讓人了解日常技術。"},{"en":"A far better window into something means a much clearer way to understand it.","zh":"「a far better window into」某事，意思是更清楚理解它的方式。"},{"en":"Family photos can be a far better window into daily life than official reports.","zh":"家庭照片比官方報告更能讓人了解日常生活。"},{"en":"A real workplace visit gives students a far better window into a career than a brochure.","zh":"真正到工作場所參觀，比小冊子更能讓學生了解一份職業。"},{"en":"This phrase compares sources of evidence and says one is more revealing.","zh":"這個短語比較證據來源，並指出其中一個更能揭示事情。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":14},{"front":"influence our everyday lives","meaning":"影響我們的日常生活","examples":[{"en":"Technology influences our everyday lives.","zh":"技術影響我們的日常生活。"},{"en":"To influence our everyday lives means to affect how we work, travel, communicate, and make choices daily.","zh":"「influence our everyday lives」意思是影響我們每天工作、出行、溝通和作選擇的方式。"},{"en":"Public transport influences our everyday lives by shaping when we leave home.","zh":"公共交通透過塑造我們何時離家來影響日常生活。"},{"en":"If technology influences our everyday lives deeply, future historians should study it closely.","zh":"如果技術深深影響我們的日常生活，未來歷史學家應仔細研究它。"},{"en":"The phrase connects large inventions with ordinary routines.","zh":"這個短語把大型發明與普通日常規律連繫起來。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":14},{"front":"practitioners of astrology","meaning":"占星術從業者","examples":[{"en":"Charette thought the device was unlikely to be used by practitioners of astrology.","zh":"Charette 認為這件裝置不太可能由占星術從業者使用。"},{"en":"Practitioners of astrology are people who use star and planet positions to make claims about character or destiny.","zh":"「practitioners of astrology」是使用星星和行星位置來判斷性格或命運的人。"},{"en":"Practitioners of astrology may prepare charts for clients who want predictions.","zh":"占星術從業者可能為想要預測的客戶製作星盤。"},{"en":"If astrology was still developing, practitioners of astrology may not have needed such a complex machine.","zh":"如果占星術仍在發展初期，占星術從業者可能不需要如此複雜的機器。"},{"en":"The phrase identifies a possible user group, but the passage treats it as unlikely.","zh":"這個短語指出一個可能使用者群體，但文章認為這可能性不大。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":14},{"front":"still in its infancy","meaning":"仍處於初期階段","examples":[{"en":"Astrology was still in its infancy at the time.","zh":"占星術當時仍處於初期階段。"},{"en":"If something is still in its infancy, it is still at an early stage of development.","zh":"如果某事物 still in its infancy，意思是它仍處於發展早期。"},{"en":"Online education was still in its infancy when only a few schools used it.","zh":"當只有少數學校使用網上教育時，它仍處於初期階段。"},{"en":"A technology still in its infancy may be exciting but not yet reliable.","zh":"仍處於初期階段的技術可能令人興奮，但未必可靠。"},{"en":"The phrase compares a new field to a very young child.","zh":"這個短語把新領域比作非常年幼的孩子。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":14},{"front":"more likely","meaning":"更可能","examples":[{"en":"More likely, the device was bound for a rich Roman’s home.","zh":"更可能的是，這件裝置是送往一位富有羅馬人的家中。"},{"en":"More likely means a more probable explanation than another one.","zh":"「more likely」意思是比另一個解釋更有可能。"},{"en":"If a student is late on a rainy day, more likely the bus was delayed.","zh":"如果學生在雨天遲到，更可能是巴士延誤了。"},{"en":"When evidence does not support one theory, researchers choose the more likely explanation.","zh":"當證據不支持某理論，研究人員會選擇更可能的解釋。"},{"en":"This phrase signals a cautious judgement, not absolute certainty.","zh":"這個短語表示謹慎判斷，而不是絕對確定。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":14},{"front":"mantelpiece","meaning":"壁爐架","examples":[{"en":"The device may have been displayed on a mantelpiece.","zh":"這件裝置可能曾展示在壁爐架上。"},{"en":"A mantelpiece is a shelf above a fireplace where objects can be displayed.","zh":"「mantelpiece」是壁爐上方可展示物件的架子。"},{"en":"Families may place photos, clocks, or decorations on a mantelpiece.","zh":"家庭可能把照片、時鐘或裝飾品放在壁爐架上。"},{"en":"If an object is kept on a mantelpiece, it may be meant for display rather than daily work.","zh":"如果物件放在壁爐架上，它可能是用來展示，而不是日常工作使用。"},{"en":"The word suggests a private home setting, not a laboratory.","zh":"這個詞暗示私人住宅環境，而不是實驗室。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":14},{"front":"given that","meaning":"鑑於","examples":[{"en":"Given that astronomers could already make calculations, the device may have been decorative.","zh":"鑑於天文學家已經能夠進行計算，這件裝置可能是裝飾性的。"},{"en":"Given that means considering the fact that something is true.","zh":"「given that」意思是考慮到某事實。"},{"en":"Given that the train is often late, we should leave earlier.","zh":"鑑於火車常常遲到，我們應該早點出發。"},{"en":"Given that the device was very complex, it probably required expert makers.","zh":"鑑於這件裝置非常複雜，它很可能需要專家製作。"},{"en":"This phrase introduces a reason for a conclusion.","zh":"這個短語引出結論的理由。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":14},{"front":"calculate the positions of","meaning":"計算……的位置","examples":[{"en":"Astronomers could calculate the positions of the sun and moon.","zh":"天文學家能夠計算太陽和月亮的位置。"},{"en":"To calculate the positions of objects means to use information or mathematics to find where they are.","zh":"「calculate the positions of」某些物體，意思是使用資訊或數學找出它們在哪裡。"},{"en":"A navigation app calculates the position of a car using satellite signals.","zh":"導航應用程式使用衛星訊號計算汽車的位置。"},{"en":"If astronomers calculate the positions of the sun and moon, they can predict eclipses.","zh":"如果天文學家計算太陽和月亮的位置，他們就可以預測日月食。"},{"en":"The phrase links measurement with prediction.","zh":"這個短語把測量與預測連繫起來。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":15},{"front":"without the device","meaning":"不使用該裝置","examples":[{"en":"Astronomers could predict eclipses without the device.","zh":"天文學家不使用該裝置也能預測日月食。"},{"en":"Without the device means not using that machine or tool.","zh":"「without the device」意思是不使用那部機器或工具。"},{"en":"Students should be able to solve simple sums without a calculator.","zh":"學生應該能夠不使用計算機解簡單算式。"},{"en":"If experts could work without the device, it may not have been essential for professional calculation.","zh":"如果專家不使用該裝置也能工作，它可能不是專業計算所必需的。"},{"en":"This phrase helps compare what was possible with and without the object.","zh":"這個短語幫助比較使用和不使用該物件時能做到什麼。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":15},{"front":"the equivalent of","meaning":"相當於……","examples":[{"en":"The mechanism may have been the equivalent of a modern planetarium device.","zh":"這件機械可能相當於現代天文館裝置。"},{"en":"The equivalent of something means something with a similar function, value, or role.","zh":"「the equivalent of」某物，意思是功能、價值或角色相似的東西。"},{"en":"An email can be the equivalent of a formal letter in many workplaces.","zh":"在許多工作場所，電郵可以相當於正式信件。"},{"en":"A bus pass is the equivalent of daily tickets if it gives the same travel rights.","zh":"如果巴士月票提供相同乘車權利，它就相當於每日車票。"},{"en":"This phrase helps explain an old object by comparing it with a familiar modern one.","zh":"這個短語透過與熟悉的現代物件比較，幫助解釋古物。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":15},{"front":"planetarium","meaning":"天文館","examples":[{"en":"The device may have functioned like an object built for a planetarium.","zh":"這件裝置可能像為天文館製造的物件一樣運作。"},{"en":"A planetarium is a place or device that shows stars, planets, and movements in the sky.","zh":"「planetarium」是展示星星、行星和天空運動的地方或裝置。"},{"en":"Students visit a planetarium to learn about constellations and eclipses.","zh":"學生參觀天文館以學習星座和日月食。"},{"en":"A planetarium display can make astronomy easier to understand because people can see the patterns.","zh":"天文館展示可以令人更容易理解天文學，因為人們能看見模式。"},{"en":"The word suggests public learning and visual demonstration.","zh":"這個詞暗示公眾學習和視覺示範。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":15},{"front":"spur popular interest","meaning":"激發大眾興趣","examples":[{"en":"The device may have been made to spur popular interest in astronomy.","zh":"這件裝置可能是為了激發大眾對天文學的興趣而製造。"},{"en":"To spur popular interest means to encourage many ordinary people to become interested.","zh":"「spur popular interest」意思是鼓勵許多普通人產生興趣。"},{"en":"A science fair can spur popular interest in robotics.","zh":"科學展可以激發大眾對機械人的興趣。"},{"en":"Beautiful museum displays can spur popular interest in history.","zh":"美觀的博物館展示可以激發大眾對歷史的興趣。"},{"en":"The phrase suggests the goal was education or excitement, not only expert use.","zh":"這個短語暗示目標是教育或引起興奮，而不只是專家使用。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":15},{"front":"claim bragging rights","meaning":"炫耀；取得值得誇耀的資本","examples":[{"en":"The owner may have used the device to claim bragging rights.","zh":"擁有人可能用這件裝置來取得值得誇耀的資本。"},{"en":"To claim bragging rights means to gain something impressive that lets a person boast.","zh":"「claim bragging rights」意思是獲得令人印象深刻、可用來炫耀的東西。"},{"en":"A student who wins a national contest can claim bragging rights at school.","zh":"贏得全國比賽的學生可以在學校取得值得誇耀的資本。"},{"en":"Owning a rare object may give a rich person bragging rights among friends.","zh":"擁有稀有物件可能給富人在朋友之間炫耀的資本。"},{"en":"The phrase is informal and often suggests status or showing off.","zh":"這個短語較口語化，常暗示地位或炫耀。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":15},{"front":"the technology that went into","meaning":"用於……的技術","examples":[{"en":"Researchers wonder why the technology that went into the device was lost.","zh":"研究人員想知道為何用於這件裝置的技術失傳。"},{"en":"The technology that went into something means the knowledge, skill, and methods used to make it.","zh":"「the technology that went into」某物，指用來製造它的知識、技能和方法。"},{"en":"People often admire a phone without understanding the technology that went into it.","zh":"人們常欣賞手機，卻不了解用於其中的技術。"},{"en":"If the technology that went into a machine disappears, future makers may struggle to copy it.","zh":"如果用於某部機器的技術消失，未來製作者可能難以複製它。"},{"en":"This phrase focuses on the hidden work behind a finished product.","zh":"這個短語集中於成品背後隱藏的工作。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":15},{"front":"jackboot of Rome","meaning":"羅馬的鐵蹄","examples":[{"en":"Edmunds said the jackboot of Rome was coming through when the device was built.","zh":"Edmunds 說，這件裝置製造時，羅馬的鐵蹄正踏來。"},{"en":"The jackboot of Rome is a metaphor for the forceful power of the Roman Empire.","zh":"「the jackboot of Rome」是羅馬帝國強制性權力的比喻。"},{"en":"A writer may use jackboot to suggest military pressure or harsh control.","zh":"作者可能使用 jackboot 來暗示軍事壓力或嚴厲控制。"},{"en":"If Rome’s power was expanding, Greek scientific traditions may have faced political change.","zh":"如果羅馬權力正在擴張，希臘科學傳統可能面對政治變化。"},{"en":"The phrase is vivid and critical, not a literal boot.","zh":"這個短語生動而帶批判性，不是字面上的靴子。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":15},{"front":"town planning","meaning":"城市規劃","examples":[{"en":"The Romans were good at town planning.","zh":"羅馬人擅長城市規劃。"},{"en":"Town planning is the design and organisation of streets, buildings, water systems, and public spaces.","zh":"「town planning」是街道、建築、供水系統和公共空間的設計與安排。"},{"en":"Good town planning makes it easier for people to travel, work, and live safely.","zh":"良好城市規劃令市民更容易安全地出行、工作和生活。"},{"en":"Poor town planning can create traffic jams, overcrowding, and weak public services.","zh":"差劣城市規劃可以造成交通擠塞、過度擁擠和公共服務薄弱。"},{"en":"The phrase often appears when discussing how cities are organised.","zh":"這個短語常出現在討論城市如何組織時。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":15},{"front":"sanitation","meaning":"衞生設施；公共衞生","examples":[{"en":"The Romans were good at sanitation.","zh":"羅馬人擅長公共衞生和衞生設施。"},{"en":"Sanitation means systems and practices that keep waste, water, and living conditions clean.","zh":"「sanitation」指保持廢物、水和生活環境清潔的系統和做法。"},{"en":"Toilets, drains, and clean water supplies are part of sanitation.","zh":"廁所、排水渠和清潔供水都是衞生設施的一部分。"},{"en":"Poor sanitation can spread disease because waste and dirty water affect health.","zh":"差劣公共衞生會傳播疾病，因為廢物和污水影響健康。"},{"en":"Good sanitation is a basic public service in any city.","zh":"良好公共衞生是任何城市的基本公共服務。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":15},{"front":"be known for","meaning":"以……聞名","examples":[{"en":"The Romans were not known for their interest in science.","zh":"羅馬人並不以對科學的興趣聞名。"},{"en":"To be known for something means to be famous or recognised because of it.","zh":"「be known for」某事，意思是因它而有名或被認識。"},{"en":"The city is known for its street food and night markets.","zh":"這個城市以街頭美食和夜市聞名。"},{"en":"If a school is known for music, many parents may send talented children there.","zh":"如果一所學校以音樂聞名，許多家長可能把有天分的孩子送去那裡。"},{"en":"This phrase identifies a reputation, not necessarily the full truth.","zh":"這個短語指出名聲，不一定代表完整事實。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":15},{"front":"the fact that","meaning":"……這一事實","examples":[{"en":"The fact that the device was complex suggests it was not unique.","zh":"這件裝置很複雜這一事實，顯示它並非獨一無二。"},{"en":"The fact that introduces a true point used as a reason or evidence.","zh":"「the fact that」引出一個真實觀點，用作理由或證據。"},{"en":"The fact that the shop is always crowded suggests its food is popular.","zh":"這間店總是擠滿人這一事實，顯示它的食物很受歡迎。"},{"en":"The fact that many students failed may mean the exam was too difficult.","zh":"許多學生不及格這一事實，可能表示考試太難。"},{"en":"This phrase turns a statement into evidence for an argument.","zh":"這個短語把一個陳述變成論點的證據。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":16},{"front":"be shipped with","meaning":"與……一起運送","examples":[{"en":"The device was being shipped with other luxury items.","zh":"這件裝置正與其他奢侈品一起運送。"},{"en":"To be shipped with something means to be transported together with it.","zh":"「be shipped with」某物，意思是與它一起被運送。"},{"en":"A laptop may be shipped with a charger and instruction booklet.","zh":"手提電腦可能與充電器和說明書一起運送。"},{"en":"If an object is shipped with luxury goods, it may also have been valuable.","zh":"如果一件物件與奢侈品一起運送，它也可能很有價值。"},{"en":"The phrase helps identify what company an item kept during transport.","zh":"這個短語幫助指出某物在運輸中與哪些東西一起。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":16},{"front":"be very unlikely to","meaning":"很不可能","examples":[{"en":"The device is very unlikely to have been the only one ever made.","zh":"這件裝置很不可能是唯一曾被製造的一件。"},{"en":"Be very unlikely to means there is a very low chance that something is true or will happen.","zh":"「be very unlikely to」意思是某事為真或會發生的可能性很低。"},{"en":"A student who never studied is very unlikely to pass a difficult exam.","zh":"從未溫習的學生很不可能通過困難考試。"},{"en":"If a machine is extremely sophisticated, it is very unlikely to appear without earlier experiments.","zh":"如果一部機器極其精密，它很不可能在沒有早期實驗的情況下出現。"},{"en":"The phrase expresses strong doubt, but not absolute impossibility.","zh":"這個短語表達強烈懷疑，但不是絕對不可能。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":16},{"front":"its sophistication is such that","meaning":"它的精密程度如此高以致……","examples":[{"en":"Its sophistication is such that it cannot have been the only one.","zh":"它的精密程度如此高，以致它不可能是唯一一件。"},{"en":"Its sophistication is such that means it is so advanced that a particular conclusion follows.","zh":"「its sophistication is such that」意思是它如此先進，以致可得出某個結論。"},{"en":"The building’s design is such that it must have required expert architects.","zh":"該建築的設計如此精巧，以致它必定需要專家建築師。"},{"en":"The device’s sophistication is such that earlier practice and skilled makers were probably needed.","zh":"這件裝置的精密程度如此高，以致它很可能需要早期練習和熟練製作者。"},{"en":"This formal structure links high quality with a logical inference.","zh":"這個正式結構把高品質與邏輯推論連繫起來。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":16},{"front":"a tradition of making","meaning":"製作……的傳統","examples":[{"en":"There must have been a tradition of making such devices.","zh":"一定曾有製作這類裝置的傳統。"},{"en":"A tradition of making something means a repeated practice or skill passed among makers over time.","zh":"「a tradition of making」某物，意思是製作者之間長期傳承的重複做法或技能。"},{"en":"A village may have a tradition of making pottery by hand.","zh":"一條村可能有手工製作陶器的傳統。"},{"en":"If a complex object exists, there may have been a tradition of making similar objects before it.","zh":"如果一件複雜物件存在，在它之前可能已有製作類似物件的傳統。"},{"en":"The phrase suggests continuity, training, and shared craft knowledge.","zh":"這個短語暗示延續、訓練和共享的工藝知識。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":16},{"front":"be hopeful that","meaning":"希望……","examples":[{"en":"Researchers are hopeful that a better example will surface.","zh":"研究人員希望會出現一個更好的例子。"},{"en":"To be hopeful that means to believe that something good may happen.","zh":"「be hopeful that」意思是相信好事可能會發生。"},{"en":"Doctors are hopeful that the new treatment will help more patients.","zh":"醫生希望新治療能幫助更多病人。"},{"en":"Researchers may be hopeful that more evidence will appear if old collections are checked.","zh":"如果檢查舊收藏，研究人員可能希望更多證據會出現。"},{"en":"The phrase expresses optimism, not certainty.","zh":"這個短語表達樂觀，而不是確定。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":16},{"front":"surface","meaning":"出現；被發現","examples":[{"en":"A better example of the mechanism may surface one day.","zh":"更好的機械例子有一天可能會出現。"},{"en":"To surface means to appear, be found, or become known after being hidden.","zh":"「surface」意思是在隱藏後出現、被發現或為人所知。"},{"en":"New evidence may surface years after a case is closed.","zh":"新證據可能在案件結束多年後出現。"},{"en":"If an old letter surfaces in a family cupboard, it may change the family’s history.","zh":"如果一封舊信在家庭櫃中被發現，它可能改變家族歷史。"},{"en":"In this meaning, surface is about discovery, not the top layer of water.","zh":"在這個意思中，surface 指發現，而不是水面。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":16},{"front":"renewed interest in","meaning":"對……重新產生的興趣","examples":[{"en":"The study created renewed interest in the Antikythera Mechanism.","zh":"這項研究使人們對安提基特拉機械重新產生興趣。"},{"en":"Renewed interest in something means fresh attention after a period of less attention.","zh":"「renewed interest in」某事，意思是在一段較少關注的時期後重新出現的新興趣。"},{"en":"A new film can create renewed interest in an old novel.","zh":"一部新電影可以令人對一本舊小說重新產生興趣。"},{"en":"Renewed interest in a museum object may lead to more research and visitors.","zh":"對博物館物件重新產生興趣，可能帶來更多研究和訪客。"},{"en":"The phrase shows that attention has returned.","zh":"這個短語顯示注意力回來了。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":16},{"front":"prompt second looks","meaning":"促使重新檢視","examples":[{"en":"The renewed interest may prompt second looks by archaeologists.","zh":"重新產生的興趣可能促使考古學家重新檢視。"},{"en":"To prompt second looks means to cause people to examine something again more carefully.","zh":"「prompt second looks」意思是促使人們再次更仔細檢查某物。"},{"en":"A strange mark on an X-ray may prompt second looks by doctors.","zh":"X光片上的奇怪痕跡可能促使醫生重新檢視。"},{"en":"New information can prompt second looks at old evidence.","zh":"新資訊可以促使人們重新檢視舊證據。"},{"en":"The phrase suggests that something previously ignored may deserve attention.","zh":"這個短語暗示以前被忽視的東西可能值得注意。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":16},{"front":"amateurs and professionals","meaning":"業餘人士和專業人士","examples":[{"en":"Both amateurs and professionals may re-examine old objects.","zh":"業餘人士和專業人士都可能重新檢查舊物件。"},{"en":"Amateurs and professionals means both non-experts who are interested and trained experts who work in the field.","zh":"「amateurs and professionals」指有興趣的非專家和在該領域工作的受訓專家。"},{"en":"Bird counts often rely on amateurs and professionals working together.","zh":"鳥類點算常依賴業餘人士和專業人士合作。"},{"en":"When amateurs and professionals share observations, more evidence can be collected.","zh":"當業餘人士和專業人士分享觀察，便可收集更多證據。"},{"en":"The phrase includes a wide range of people, not just official specialists.","zh":"這個短語包括廣泛的人，而不只是官方專家。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":16},{"front":"archaeological world","meaning":"考古界","examples":[{"en":"The archaeological world may reconsider objects stored away.","zh":"考古界可能重新考慮被存放起來的物件。"},{"en":"The archaeological world means the community of archaeologists, museums, researchers, and people connected with archaeology.","zh":"「archaeological world」指考古學家、博物館、研究人員和與考古相關人士組成的社群。"},{"en":"A major discovery can excite the archaeological world.","zh":"重大發現可以令考古界興奮。"},{"en":"If the archaeological world rechecks old finds, forgotten objects may become important.","zh":"如果考古界重新檢查舊發現，被遺忘的物件可能變得重要。"},{"en":"The phrase refers to a professional community, not a physical world.","zh":"這個短語指專業社群，而不是實際世界。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":16},{"front":"look in their cupboards","meaning":"翻查自己的收藏櫃","examples":[{"en":"Archaeologists may look in their cupboards for overlooked objects.","zh":"考古學家可能翻查自己的收藏櫃，尋找被忽略的物件。"},{"en":"To look in their cupboards means to search through stored items that may have been forgotten.","zh":"「look in their cupboards」意思是翻查可能被遺忘的存放物品。"},{"en":"A teacher may look in their cupboards and find old materials useful for a new lesson.","zh":"老師可能翻查自己的櫃子，找到對新課堂有用的舊材料。"},{"en":"If museums look in their cupboards, they may discover objects that deserve fresh study.","zh":"如果博物館翻查收藏櫃，它們可能發現值得重新研究的物件。"},{"en":"The phrase is partly literal and partly humorous, suggesting hidden value in storage.","zh":"這個短語部分是字面意思，部分帶幽默，暗示儲物中有隱藏價值。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":17},{"front":"a bit of rusty old metal","meaning":"一小塊生鏽舊金屬","examples":[{"en":"An object may not be merely a bit of rusty old metal.","zh":"一件物件未必只是一小塊生鏽舊金屬。"},{"en":"A bit of rusty old metal means a small piece of old metal covered with rust and apparently unimportant.","zh":"「a bit of rusty old metal」指一小塊覆蓋鐵鏽、看似不重要的舊金屬。"},{"en":"A bit of rusty old metal in a drawer might actually be part of an old machine.","zh":"抽屜中的一小塊生鏽舊金屬其實可能是舊機器的一部分。"},{"en":"If researchers dismiss rusty metal too quickly, they may miss important evidence.","zh":"如果研究人員太快忽視生鏽金屬，他們可能錯過重要證據。"},{"en":"The phrase shows how valuable objects can look ordinary or damaged.","zh":"這個短語顯示有價值物件可以看起來普通或受損。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":17},{"front":"in the cupboard","meaning":"在櫃裏","examples":[{"en":"An important object might be hidden in the cupboard.","zh":"重要物件可能藏在櫃裏。"},{"en":"In the cupboard means inside a storage cabinet or enclosed shelf.","zh":"「in the cupboard」意思是在儲物櫃或封閉架子內。"},{"en":"Old family photos may be kept in the cupboard for years.","zh":"舊家庭照片可能在櫃裏保存多年。"},{"en":"If something stays in the cupboard too long, people may forget it exists.","zh":"如果某物在櫃裏放太久，人們可能忘記它存在。"},{"en":"In this context, the phrase suggests valuable things may be hidden in storage.","zh":"在這個語境中，這個短語暗示有價值的東西可能藏在儲物處。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":17},{"front":"contains the following information","meaning":"包含以下資料","examples":[{"en":"Students identify which paragraph contains the following information.","zh":"學生辨認哪一段包含以下資料。"},{"en":"Contains the following information means includes the details listed after the instruction.","zh":"「contains the following information」意思是包括指示後列出的細節。"},{"en":"A report contains the following information if it answers each listed point.","zh":"如果報告回答了每個列出的要點，它就包含以下資料。"},{"en":"In reading tests, students must find where the text contains the following information.","zh":"在閱讀測驗中，學生必須找出文本哪裡包含以下資料。"},{"en":"The phrase asks students to match details with the correct part of a passage.","zh":"這個短語要求學生把細節與文章正確部分配對。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":17},{"front":"wrecked ship","meaning":"失事船隻","examples":[{"en":"The question asks about the content inside the wrecked ship.","zh":"問題問及失事船隻內的內容。"},{"en":"A wrecked ship is a ship that has been badly damaged, destroyed, or sunk.","zh":"「wrecked ship」是嚴重受損、被毀或沉沒的船。"},{"en":"Divers may explore a wrecked ship to recover objects or study the accident.","zh":"潛水員可能探索失事船隻，以取回物件或研究事故。"},{"en":"A wrecked ship can preserve cargo if it remains buried underwater.","zh":"如果失事船隻一直埋在水底，它可以保存貨物。"},{"en":"The phrase focuses on the damaged condition of the ship.","zh":"這個短語集中於船隻受損的狀態。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":17},{"front":"ancient astronomers and craftspeople","meaning":"古代天文學家和工匠","examples":[{"en":"Ancient astronomers and craftspeople may have been involved in building the device.","zh":"古代天文學家和工匠可能曾參與製造這件裝置。"},{"en":"Ancient astronomers and craftspeople means sky experts and skilled makers from ancient times.","zh":"「ancient astronomers and craftspeople」指古代的天空專家和熟練製作者。"},{"en":"Ancient astronomers could provide calculations, while craftspeople could make the parts.","zh":"古代天文學家可以提供計算，而工匠可以製作零件。"},{"en":"A complex machine often needs both theoretical knowledge and practical skill.","zh":"複雜機器通常需要理論知識和實用技能。"},{"en":"The phrase shows that the device may have required cooperation between thinkers and makers.","zh":"這個短語顯示該裝置可能需要思想家與製作者合作。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":17},{"front":"may have been involved","meaning":"可能曾參與","examples":[{"en":"Several kinds of experts may have been involved in building the mechanism.","zh":"幾類專家可能曾參與製造這件機械。"},{"en":"May have been involved means possibly took part in something in the past.","zh":"「may have been involved」意思是過去可能參與了某事。"},{"en":"Several teachers may have been involved in planning the school event.","zh":"幾位老師可能曾參與策劃學校活動。"},{"en":"If many skills were needed, different specialists may have been involved.","zh":"如果需要許多技能，不同專家可能曾參與其中。"},{"en":"The phrase expresses possibility, not confirmed fact.","zh":"這個短語表達可能性，而不是已確認事實。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":17},{"front":"the location of","meaning":"……的位置","examples":[{"en":"The question asks for the location of the Antikythera Mechanism.","zh":"問題要求指出安提基特拉機械的位置。"},{"en":"The location of something means the place where it is found, kept, or situated.","zh":"「the location of」某物，指它被發現、保存或所在的地方。"},{"en":"A map shows the location of hospitals, schools, and stations.","zh":"地圖顯示醫院、學校和車站的位置。"},{"en":"If the location of an object is known, visitors or researchers can find it more easily.","zh":"如果知道物件的位置，訪客或研究人員就更容易找到它。"},{"en":"The phrase asks where something is, not what it is.","zh":"這個短語問的是某物在哪裡，而不是它是什麼。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":17},{"front":"details of how","meaning":"關於……如何發生的細節","examples":[{"en":"The passage gives details of how the mechanism was found.","zh":"文章提供關於這件機械如何被發現的細節。"},{"en":"Details of how something happened are specific facts explaining the process or method.","zh":"「details of how」某事發生，指解釋過程或方法的具體事實。"},{"en":"A police report gives details of how an accident happened.","zh":"警方報告提供關於意外如何發生的細節。"},{"en":"Details of how a machine works help users avoid mistakes.","zh":"關於機器如何運作的細節幫助使用者避免錯誤。"},{"en":"The phrase asks for process, not just final result.","zh":"這個短語要求過程，而不只是最終結果。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":17},{"front":"appearance and structure","meaning":"外觀和結構","examples":[{"en":"The paragraph describes the mechanism’s appearance and structure.","zh":"該段描述這件機械的外觀和結構。"},{"en":"Appearance and structure means how something looks and how its parts are arranged.","zh":"「appearance and structure」意思是某物看起來如何，以及其部分如何安排。"},{"en":"A building report may describe the appearance and structure of an old house.","zh":"建築報告可能描述一間舊屋的外觀和結構。"},{"en":"Understanding appearance and structure helps researchers reconstruct broken objects.","zh":"理解外觀和結構幫助研究人員重建破碎物件。"},{"en":"Appearance is about what can be seen; structure is about how parts fit together.","zh":"外觀關於可見樣子；結構關於各部分如何配合。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":17},{"front":"complete the following summary","meaning":"完成以下摘要","examples":[{"en":"Students complete the following summary using words from the passage.","zh":"學生使用文章中的詞語完成以下摘要。"},{"en":"Complete the following summary means fill in missing words in a short version of the text.","zh":"「complete the following summary」意思是在文本簡短版本中填上缺漏詞語。"},{"en":"In a reading test, students complete the following summary by choosing exact words from the article.","zh":"在閱讀測驗中，學生透過從文章選擇準確詞語來完成以下摘要。"},{"en":"If students misunderstand the passage, they may complete the summary with the wrong words.","zh":"如果學生誤解文章，他們可能用錯詞完成摘要。"},{"en":"This instruction tests both understanding and careful word choice.","zh":"這條指示同時測試理解和仔細選詞。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":17},{"front":"no more than two words","meaning":"不多於兩個詞","examples":[{"en":"Students should use no more than two words from the passage.","zh":"學生應使用文章中不多於兩個詞。"},{"en":"No more than two words means the answer must contain one or two words only.","zh":"「no more than two words」意思是答案只能包含一個或兩個詞。"},{"en":"If the instruction says no more than two words, three-word answers are wrong even if the idea is correct.","zh":"如果指示說不多於兩個詞，即使意思正確，三個詞的答案也是錯的。"},{"en":"Students must count words carefully to follow the limit.","zh":"學生必須小心數詞數，以遵守限制。"},{"en":"This phrase is common in reading and listening tests.","zh":"這個短語常見於閱讀和聆聽測驗。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":18},{"front":"discovered by chance","meaning":"偶然發現","examples":[{"en":"The ancient cargo vessel was discovered by chance by sponge divers.","zh":"這艘古代貨船由採海綿潛水員偶然發現。"},{"en":"Discovered by chance means found accidentally, not because someone was looking for it directly.","zh":"「discovered by chance」意思是偶然找到，而不是有人直接尋找它。"},{"en":"A child may discover an old photo by chance while cleaning a cupboard.","zh":"孩子清理櫃子時，可能偶然發現一張舊照片。"},{"en":"Many important discoveries begin by chance when someone notices something unusual.","zh":"許多重要發現始於偶然，因為有人注意到不尋常的東西。"},{"en":"The phrase highlights accident and surprise.","zh":"這個短語強調意外和驚喜。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":18},{"front":"sponge divers","meaning":"採海綿潛水員","examples":[{"en":"Sponge divers found the ancient wreck.","zh":"採海綿潛水員發現了古代沉船。"},{"en":"Sponge divers are people who dive underwater to collect natural sea sponges.","zh":"「sponge divers」是潛入水底採集天然海綿的人。"},{"en":"Sponge divers need skill because they may work in deep or dangerous water.","zh":"採海綿潛水員需要技巧，因為他們可能在深水或危險水域工作。"},{"en":"While searching for sponges, sponge divers may notice unusual objects on the seabed.","zh":"在尋找海綿時，採海綿潛水員可能注意到海床上的不尋常物件。"},{"en":"In this story, sponge divers became accidental discoverers of history.","zh":"在這個故事中，採海綿潛水員意外成為歷史發現者。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":18},{"front":"resembling a gearwheel","meaning":"類似齒輪的","examples":[{"en":"The archaeologist found an object resembling a gearwheel.","zh":"考古學家發現一件類似齒輪的物件。"},{"en":"Resembling a gearwheel means looking similar to a toothed wheel used in a machine.","zh":"「resembling a gearwheel」意思是外觀類似機器中使用的有齒輪子。"},{"en":"A broken toy part resembling a gearwheel may belong inside a clock.","zh":"一件類似齒輪的破玩具零件可能屬於時鐘內部。"},{"en":"If an object resembles a gearwheel, researchers may examine whether it was part of a mechanism.","zh":"如果物件類似齒輪，研究人員可能檢查它是否是一個機制的一部分。"},{"en":"Resembling shows appearance, not final identification.","zh":"「resembling」顯示外觀，而不是最終身份。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":18},{"front":"inscribed with","meaning":"刻有……","examples":[{"en":"The object was inscribed with Greek characters.","zh":"那件物件刻有希臘文字。"},{"en":"Inscribed with means marked with writing or symbols cut into a surface.","zh":"「inscribed with」意思是表面刻有文字或符號。"},{"en":"A medal may be inscribed with the winner’s name.","zh":"獎牌可能刻有得獎者姓名。"},{"en":"If a stone is inscribed with a date, it can help historians place it in time.","zh":"如果石頭刻有日期，它可以幫助歷史學家判定年代。"},{"en":"The phrase suggests the writing is physically part of the object.","zh":"這個短語暗示文字是物件本身的實體部分。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":18},{"front":"prove to be","meaning":"證明是","examples":[{"en":"The sophisticated device proved to be the world’s first known analogue computer.","zh":"這件精密裝置證明是世界首部已知模擬電腦。"},{"en":"Prove to be means turn out to be after evidence or later discovery.","zh":"「prove to be」意思是經證據或後來發現後證明是。"},{"en":"The old box proved to be full of family letters.","zh":"那個舊盒子後來證明是裝滿了家庭信件。"},{"en":"A small mistake may prove to be serious if it affects the whole system.","zh":"如果小錯誤影響整個系統，它可能證明是嚴重的。"},{"en":"The phrase shows that the real nature of something became clear later.","zh":"這個短語顯示某物的真正性質後來變得清楚。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":18},{"front":"use the information in","meaning":"使用……中的資料","examples":[{"en":"Students use the information in the passage to match people with opinions.","zh":"學生使用文章中的資料，把人物與意見配對。"},{"en":"Use the information in a text means base answers on what the text actually says.","zh":"「use the information in」文本，意思是根據文本實際所說來作答。"},{"en":"Students should use the information in the chart, not their own guesses.","zh":"學生應使用圖表中的資料，而不是自己的猜測。"},{"en":"If you use the information in the passage carefully, you can avoid unsupported answers.","zh":"如果你仔細使用文章中的資料，就可以避免沒有根據的答案。"},{"en":"The phrase reminds learners to rely on evidence.","zh":"這個短語提醒學習者依賴證據。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":18},{"front":"match the people with","meaning":"將人物與……配對","examples":[{"en":"Students match the people with the correct opinions or actions.","zh":"學生將人物與正確意見或行動配對。"},{"en":"Match the people with something means connect each person to the correct item.","zh":"「match the people with」某物，意思是把每個人物連到正確項目。"},{"en":"In a reading exercise, students may match the people with their discoveries.","zh":"在閱讀練習中，學生可能將人物與他們的發現配對。"},{"en":"If two people have similar opinions, matching them with the right statement can be difficult.","zh":"如果兩個人有相似意見，把他們與正確陳述配對可能很難。"},{"en":"This instruction tests whether students understand who said or did what.","zh":"這條指示測試學生是否理解誰說了什麼或做了什麼。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":18},{"front":"opinions or actions","meaning":"意見或行動","examples":[{"en":"The question asks students to match people with opinions or actions.","zh":"問題要求學生把人物與意見或行動配對。"},{"en":"Opinions or actions means what people think or what they do.","zh":"「opinions or actions」意思是人們的想法或所做的事。"},{"en":"A history exercise may ask students to match leaders with their opinions or actions.","zh":"歷史練習可能要求學生把領袖與其意見或行動配對。"},{"en":"Confusing opinions with actions can lead to wrong answers in reading tests.","zh":"在閱讀測驗中混淆意見與行動，可能導致錯誤答案。"},{"en":"The phrase covers both beliefs and behaviour.","zh":"這個短語涵蓋信念和行為。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":18},{"front":"appropriate letters","meaning":"適當字母","examples":[{"en":"Students write the appropriate letters in the answer boxes.","zh":"學生在答案框中寫上適當字母。"},{"en":"Appropriate letters are the correct option letters that match the answers.","zh":"「appropriate letters」是與答案相配的正確選項字母。"},{"en":"In a matching task, students write the appropriate letters beside each question number.","zh":"在配對題中，學生在每個題號旁寫上適當字母。"},{"en":"If students choose inappropriate letters, the answer may not match the passage.","zh":"如果學生選擇不適當字母，答案可能不符合文章。"},{"en":"Appropriate means suitable or correct for the task.","zh":"「appropriate」意思是適合或對應任務的。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":18},{"front":"may use any letter more than once","meaning":"可使用任何字母多於一次","examples":[{"en":"Students may use any letter more than once.","zh":"學生可使用任何字母多於一次。"},{"en":"May use any letter more than once means the same option can be chosen for more than one answer.","zh":"「may use any letter more than once」意思是同一選項可以用於多於一個答案。"},{"en":"In some matching questions, students may use any letter more than once if two statements match the same person.","zh":"在一些配對題中，如果兩項陳述對應同一人物，學生可使用任何字母多於一次。"},{"en":"If students think each letter can be used only once, they may make avoidable mistakes.","zh":"如果學生以為每個字母只能用一次，他們可能犯可避免的錯誤。"},{"en":"This instruction changes how students manage the answer choices.","zh":"這條指示改變學生處理答案選項的方式。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":18},{"front":"more complicated than","meaning":"比……更複雜","examples":[{"en":"The Antikythera Mechanism was more complicated than an earlier device.","zh":"安提基特拉機械比一件較早的裝置更複雜。"},{"en":"More complicated than means having more parts, details, or difficulty than something else.","zh":"「more complicated than」意思是比另一物有更多部分、細節或難度。"},{"en":"This maths problem is more complicated than the one we did yesterday.","zh":"這道數學題比我們昨天做的那道更複雜。"},{"en":"A machine with many gears is more complicated than one with only a handle.","zh":"有許多齒輪的機器比只有一個手柄的機器更複雜。"},{"en":"The phrase makes a comparison of complexity.","zh":"這個短語用來比較複雜程度。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":19},{"front":"expect more examples to be found","meaning":"預期會發現更多例子","examples":[{"en":"Researchers expect more examples of the mechanism to be found in the future.","zh":"研究人員預期未來會發現更多這種機械的例子。"},{"en":"Expect more examples to be found means believe additional similar objects will probably be discovered.","zh":"「expect more examples to be found」意思是相信很可能會發現更多類似物件。"},{"en":"After one dinosaur fossil is found, scientists may expect more examples to be found nearby.","zh":"發現一件恐龍化石後，科學家可能預期附近會發現更多例子。"},{"en":"If a device was part of a tradition, researchers may expect more examples to be found.","zh":"如果某裝置屬於一種製作傳統，研究人員可能預期會發現更多例子。"},{"en":"The phrase expresses a research hope based on reasoning.","zh":"這個短語表達基於推理的研究期望。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":19},{"front":"be related to lunar cycles","meaning":"與月亮週期有關","examples":[{"en":"The mechanism was related to lunar cycles.","zh":"這件機械與月亮週期有關。"},{"en":"Be related to lunar cycles means connected with the repeated changes of the moon.","zh":"「be related to lunar cycles」意思是與月亮反覆變化有關。"},{"en":"Some traditional festivals are related to lunar cycles.","zh":"有些傳統節日與月亮週期有關。"},{"en":"If a device tracks lunar cycles, it can help show months, phases, or eclipses.","zh":"如果裝置追蹤月亮週期，它可以幫助顯示月份、月相或日月食。"},{"en":"The phrase connects an object or event with moon-based timing.","zh":"這個短語把物件或事件與以月亮為基礎的計時連繫起來。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":19},{"front":"calculate the movement of","meaning":"計算……的運動","examples":[{"en":"The mechanism helped ancient people calculate the movement of celestial bodies.","zh":"這件機械幫助古人計算天體的運動。"},{"en":"To calculate the movement of something means to work out how it moves using rules, data, or mathematics.","zh":"「calculate the movement of」某物，意思是用規則、數據或數學推算它如何移動。"},{"en":"Engineers calculate the movement of lifts so they stop at the right floors.","zh":"工程師計算升降機的運動，使它們停在正確樓層。"},{"en":"Astronomers calculate the movement of planets to predict where they will appear.","zh":"天文學家計算行星的運動，以預測它們會出現在哪裡。"},{"en":"The phrase links mathematical work with motion.","zh":"這個短語把數學工作與運動連繫起來。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":19},{"front":"celestial bodies","meaning":"天體","examples":[{"en":"The sun, moon and stars are celestial bodies.","zh":"太陽、月亮和星星都是天體。"},{"en":"Celestial bodies are natural objects in space, such as stars, planets, moons, and comets.","zh":"「celestial bodies」是太空中的天然物體，例如恆星、行星、月亮和彗星。"},{"en":"Students learn about celestial bodies when they study the solar system.","zh":"學生研究太陽系時會學到天體。"},{"en":"Tracking celestial bodies helped ancient people measure time and predict events in the sky.","zh":"追蹤天體幫助古人量度時間和預測天空事件。"},{"en":"The phrase is formal and often used in astronomy.","zh":"這個短語較正式，常用於天文學。"}],"source":"150 - Computer Provides More Questions Than Answers.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 151":[{"front":"Health in the Wild","meaning":"野外健康","examples":[{"en":"The passage discusses health in the wild and animal self-medication.","zh":"文章討論野外健康和動物自我用藥。"},{"en":"Health in the wild refers to how animals stay healthy without human doctors or hospitals.","zh":"野外健康指動物在沒有人類醫生或醫院的情況下如何保持健康。"},{"en":"A bird may protect its health in the wild by eating clay after consuming toxic seeds.","zh":"鳥類吃下有毒種子後，可能透過吃黏土來保護野外健康。"},{"en":"Studying health in the wild can help scientists understand natural ways of treating illness.","zh":"研究野外健康可以幫助科學家理解自然治病方法。"},{"en":"The phrase connects animal behaviour, survival, and natural medicine.","zh":"這個短語連繫動物行為、生存和天然醫藥。"}],"source":"151 - Health in the Wild.pdf","sourcePage":1},{"front":"for the past decade","meaning":"在過去十年","examples":[{"en":"For the past decade, Dr Engel has studied animal self-medication.","zh":"在過去十年，Engel 博士研究動物自我用藥。"},{"en":"For the past decade means during the last ten years up to now or up to the time mentioned.","zh":"“For the past decade” 指直到現在或文中提及時間為止的過去十年。"},{"en":"For the past decade, the school has used online tools to support homework.","zh":"在過去十年，學校一直使用網上工具支援功課。"},{"en":"If rent has risen for the past decade, many families may struggle to save money.","zh":"如果租金在過去十年持續上升，許多家庭可能難以儲蓄。"},{"en":"The phrase is useful for describing a long recent period.","zh":"這個短語適合描述一段較長的近期時間。"}],"source":"151 - Health in the Wild.pdf","sourcePage":1},{"front":"lecturer in environmental sciences","meaning":"環境科學講師","examples":[{"en":"Dr Engel is a lecturer in environmental sciences at Britain’s Open University.","zh":"Engel 博士是英國公開大學的環境科學講師。"},{"en":"A lecturer in environmental sciences teaches or researches topics such as nature, pollution, animals, and ecosystems.","zh":"環境科學講師教授或研究自然、污染、動物和生態系統等題目。"},{"en":"A lecturer in environmental sciences may explain how human activity affects rivers and forests.","zh":"環境科學講師可能解釋人類活動如何影響河流和森林。"},{"en":"If students want to study climate change, a lecturer in environmental sciences can guide them.","zh":"如果學生想研究氣候變化，環境科學講師可以指導他們。"},{"en":"The phrase tells us both the person’s job and academic field.","zh":"這個短語同時告訴我們一個人的職業和學術範疇。"}],"source":"151 - Health in the Wild.pdf","sourcePage":1},{"front":"collate examples of","meaning":"整理……的例子","examples":[{"en":"Dr Engel has been collating examples of self-medicating behaviour.","zh":"Engel 博士一直在整理自我用藥行為的例子。"},{"en":"To collate examples of something means to collect and organise examples from different sources.","zh":"“Collate examples of” 某事指從不同來源收集並整理例子。"},{"en":"A teacher may collate examples of common grammar mistakes before a revision lesson.","zh":"老師可能在溫習課前整理常見文法錯誤的例子。"},{"en":"Researchers collate examples of unusual animal behaviour so patterns become easier to see.","zh":"研究人員整理異常動物行為的例子，使模式更容易看見。"},{"en":"The phrase suggests careful collection, not random listing.","zh":"這個短語暗示有系統地收集，而不是隨意列出。"}],"source":"151 - Health in the Wild.pdf","sourcePage":1},{"front":"self-medicating behaviour","meaning":"自我用藥行為","examples":[{"en":"Wild animals may show self-medicating behaviour.","zh":"野生動物可能表現出自我用藥行為。"},{"en":"Self-medicating behaviour means an animal uses plants, soil, or other natural materials to treat illness or discomfort.","zh":"自我用藥行為指動物使用植物、泥土或其他天然物質來治療疾病或不適。"},{"en":"A chimp eating a bitter plant to kill parasites may be showing self-medicating behaviour.","zh":"黑猩猩吃苦味植物來殺死寄生蟲，可能是在表現自我用藥行為。"},{"en":"If an animal repeats the same unusual eating pattern when sick, scientists may suspect self-medicating behaviour.","zh":"如果動物生病時重複同一種異常進食模式，科學家可能懷疑是自我用藥行為。"},{"en":"The phrase describes treatment chosen by the animal itself.","zh":"這個短語描述由動物自己選擇的治療方式。"}],"source":"151 - Health in the Wild.pdf","sourcePage":1},{"front":"wild animals","meaning":"野生動物","examples":[{"en":"Dr Engel studies self-medicating behaviour in wild animals.","zh":"Engel 博士研究野生動物的自我用藥行為。"},{"en":"Wild animals are animals that live naturally without being owned or controlled by humans.","zh":"野生動物是自然生活、不由人類擁有或控制的動物。"},{"en":"Lions, parrots, elephants, and chimpanzees can all be wild animals.","zh":"獅子、鸚鵡、大象和黑猩猩都可以是野生動物。"},{"en":"Wild animals must find food, shelter, and medicine without human care.","zh":"野生動物必須在沒有人類照顧下尋找食物、住所和藥物。"},{"en":"The phrase contrasts with pets, farm animals, or animals kept in zoos.","zh":"這個短語與寵物、農場動物或動物園中的動物形成對比。"}],"source":"151 - Health in the Wild.pdf","sourcePage":1},{"front":"publish a book on","meaning":"出版一本關於……的書","examples":[{"en":"She recently published a book on the subject.","zh":"她最近出版了一本關於該主題的書。"},{"en":"To publish a book on a topic means to write and release a book about that topic for readers.","zh":"“Publish a book on” 某題目指撰寫並發行一本關於該題目的書給讀者。"},{"en":"A doctor may publish a book on healthy sleep habits for busy workers.","zh":"醫生可能出版一本關於忙碌工人健康睡眠習慣的書。"},{"en":"If a researcher publishes a book on animal behaviour, more people can learn about the research.","zh":"如果研究員出版一本關於動物行為的書，更多人可以了解該研究。"},{"en":"The phrase is common when talking about academic or specialist writing.","zh":"這個短語常用於談論學術或專門寫作。"}],"source":"151 - Health in the Wild.pdf","sourcePage":1},{"front":"on the subject","meaning":"關於該主題","examples":[{"en":"She published a book on the subject of animal self-medication.","zh":"她出版了一本關於動物自我用藥這個主題的書。"},{"en":"On the subject means about that topic or matter.","zh":"“On the subject” 指關於該題目或事情。"},{"en":"The teacher gave students extra notes on the subject of essay structure.","zh":"老師給學生關於作文結構這個主題的額外筆記。"},{"en":"If a doctor speaks on the subject of diet, patients may ask many practical questions.","zh":"如果醫生談論飲食這個主題，病人可能會問很多實際問題。"},{"en":"The phrase avoids repeating the topic again.","zh":"這個短語可以避免再次重複題目。"}],"source":"151 - Health in the Wild.pdf","sourcePage":1},{"front":"Edinburgh Science Festival","meaning":"愛丁堡科學節","examples":[{"en":"Dr Engel gave a talk at the Edinburgh Science Festival.","zh":"Engel 博士在愛丁堡科學節發表演講。"},{"en":"The Edinburgh Science Festival is an event where people can hear talks and learn about scientific ideas.","zh":"愛丁堡科學節是一個人們可以聽演講並學習科學概念的活動。"},{"en":"A researcher may present new findings at the Edinburgh Science Festival.","zh":"研究人員可能在愛丁堡科學節發表新發現。"},{"en":"Public science festivals can make difficult topics easier for ordinary people to understand.","zh":"公眾科學節可以令困難題目更容易讓普通人理解。"},{"en":"The phrase names a specific event connected with public science communication.","zh":"這個短語指一個與公眾科學傳播有關的特定活動。"}],"source":"151 - Health in the Wild.pdf","sourcePage":1},{"front":"earlier this month","meaning":"本月較早時候","examples":[{"en":"She gave a talk earlier this month.","zh":"她在本月較早時候發表演講。"},{"en":"Earlier this month means at a time before now but still within the same month.","zh":"“Earlier this month” 指在本月內、但早於現在的某個時間。"},{"en":"Earlier this month, our class visited a museum.","zh":"本月較早時候，我們班參觀了一間博物館。"},{"en":"If a payment was made earlier this month, it should appear on the latest statement.","zh":"如果付款在本月較早時候已完成，它應該出現在最新結單上。"},{"en":"The phrase is useful when the exact date is not important.","zh":"當準確日期不重要時，這個短語很有用。"}],"source":"151 - Health in the Wild.pdf","sourcePage":1},{"front":"the idea that","meaning":"……這個想法","examples":[{"en":"The idea that animals can treat themselves was once doubted.","zh":"動物能自我治療這個想法曾受到懷疑。"},{"en":"The idea that something is true means the belief or suggestion that it may be true.","zh":"“The idea that” 某事為真，指某事可能為真的信念或說法。"},{"en":"The idea that children learn only from textbooks is too narrow.","zh":"孩子只從教科書學習這個想法太狹窄。"},{"en":"New evidence can change the idea that a behaviour is useless or strange.","zh":"新證據可以改變某種行為無用或奇怪這個想法。"},{"en":"The phrase introduces a belief, claim, or explanation.","zh":"這個短語用來引出信念、主張或解釋。"}],"source":"151 - Health in the Wild.pdf","sourcePage":1},{"front":"treat themselves","meaning":"自我治療","examples":[{"en":"Some animals appear able to treat themselves.","zh":"一些動物似乎能夠自我治療。"},{"en":"To treat themselves means to deal with illness or injury without direct help from a doctor or another person.","zh":"“Treat themselves” 指在沒有醫生或他人直接幫助下處理疾病或傷口。"},{"en":"A person with a small cut may treat themselves by cleaning it and covering it with a plaster.","zh":"有小傷口的人可能透過清潔傷口並貼上膠布來自我治療。"},{"en":"Animals may treat themselves by eating plants that reduce parasites or stomach problems.","zh":"動物可能透過吃能減少寄生蟲或胃部問題的植物來自我治療。"},{"en":"The phrase focuses on self-care rather than outside medical care.","zh":"這個短語強調自我照顧，而不是外來醫療照顧。"}],"source":"151 - Health in the Wild.pdf","sourcePage":2},{"front":"be regarded with scepticism","meaning":"被懷疑地看待","examples":[{"en":"The idea was regarded with scepticism by her colleagues.","zh":"這個想法被她的同事懷疑地看待。"},{"en":"To be regarded with scepticism means to be viewed with doubt instead of immediate belief.","zh":"“Be regarded with scepticism” 指被人以懷疑態度看待，而不是立即相信。"},{"en":"A miracle cure should be regarded with scepticism until strong evidence is provided.","zh":"在有力證據出現之前，奇蹟療法應被懷疑地看待。"},{"en":"If a student gives an excuse too often, the teacher may regard it with scepticism.","zh":"如果學生太常使用同一個藉口，老師可能會懷疑地看待它。"},{"en":"The phrase is common when people are not yet convinced by a claim.","zh":"這個短語常用於人們尚未被某主張說服的情況。"}],"source":"151 - Health in the Wild.pdf","sourcePage":2},{"front":"by her colleagues","meaning":"由她的同事","examples":[{"en":"Her colleagues once doubted the idea.","zh":"她的同事曾經懷疑這個想法。"},{"en":"By her colleagues means by the people who work with her in the same field or workplace.","zh":"“By her colleagues” 指由與她在同一領域或工作場所共事的人。"},{"en":"A new teaching method may be questioned by her colleagues before it is tested.","zh":"新教學方法在測試前可能由她的同事提出質疑。"},{"en":"If her research is respected by her colleagues, it may influence the whole department.","zh":"如果她的研究受到她的同事尊重，可能影響整個部門。"},{"en":"The phrase identifies who performs the action or holds the opinion.","zh":"這個短語指出由誰作出行動或持有觀點。"}],"source":"151 - Health in the Wild.pdf","sourcePage":2},{"front":"in the past","meaning":"過去","examples":[{"en":"The idea was treated with scepticism in the past.","zh":"這個想法過去被懷疑地看待。"},{"en":"In the past means during an earlier time, not now.","zh":"“In the past” 指在較早時期，而不是現在。"},{"en":"In the past, students used dictionaries more often because smartphones were less common.","zh":"過去，學生較常使用字典，因為智能電話較不普及。"},{"en":"If a method failed in the past, people may be cautious about trying it again.","zh":"如果一種方法過去失敗過，人們可能會謹慎地再次嘗試。"},{"en":"The phrase often contrasts old views with present views.","zh":"這個短語常把舊觀點與現在觀點作對比。"}],"source":"151 - Health in the Wild.pdf","sourcePage":2},{"front":"a growing number of","meaning":"越來越多的……","examples":[{"en":"A growing number of animal behaviourists now accept the idea.","zh":"越來越多動物行為學家現在接受這個想法。"},{"en":"A growing number of people means more and more people over time.","zh":"“A growing number of” 人指隨時間越來越多人。"},{"en":"A growing number of students are using videos to revise difficult topics.","zh":"越來越多學生使用影片溫習困難題目。"},{"en":"If a growing number of patients report the same symptom, doctors will investigate it carefully.","zh":"如果越來越多病人報告同一症狀，醫生會仔細調查。"},{"en":"The phrase shows an increasing trend.","zh":"這個短語顯示增長趨勢。"}],"source":"151 - Health in the Wild.pdf","sourcePage":2},{"front":"animal behaviourists","meaning":"動物行為學家","examples":[{"en":"Animal behaviourists study how animals behave.","zh":"動物行為學家研究動物如何行動。"},{"en":"Animal behaviourists are scientists who observe and explain animal actions, habits, communication, and social life.","zh":"動物行為學家是觀察和解釋動物行動、習慣、溝通和社會生活的科學家。"},{"en":"Animal behaviourists may study why birds migrate or why monkeys groom one another.","zh":"動物行為學家可能研究鳥類為何遷徙，或猴子為何互相梳理毛髮。"},{"en":"If animal behaviourists notice unusual eating habits, they may ask whether illness is involved.","zh":"如果動物行為學家注意到異常進食習慣，他們可能會問是否與疾病有關。"},{"en":"The phrase refers to experts in animal behaviour.","zh":"這個短語指研究動物行為的專家。"}],"source":"151 - Health in the Wild.pdf","sourcePage":2},{"front":"deal with","meaning":"處理","examples":[{"en":"Wild animals can deal with their own medical needs.","zh":"野生動物可以處理自己的醫療需要。"},{"en":"To deal with something means to handle, manage, or solve it.","zh":"“Deal with” 某事指處理、管理或解決它。"},{"en":"A student can deal with exam stress by planning revision early.","zh":"學生可以透過及早規劃溫習來處理考試壓力。"},{"en":"If a shop does not deal with customer complaints, people may stop returning.","zh":"如果商店不處理顧客投訴，人們可能不再光顧。"},{"en":"The phrase is very common for problems, tasks, and responsibilities.","zh":"這個短語非常常用於問題、任務和責任。"}],"source":"151 - Health in the Wild.pdf","sourcePage":2},{"front":"medical needs","meaning":"醫療需要","examples":[{"en":"Some animals can deal with their own medical needs.","zh":"一些動物可以處理自己的醫療需要。"},{"en":"Medical needs are health problems or care requirements that must be treated or managed.","zh":"醫療需要是必須治療或管理的健康問題或護理要求。"},{"en":"An elderly person may have medical needs such as medicine, check-ups, and help walking.","zh":"長者可能有醫療需要，例如藥物、檢查和步行協助。"},{"en":"If medical needs are ignored, small health problems may become serious.","zh":"如果醫療需要被忽視，小健康問題可能變得嚴重。"},{"en":"The phrase covers both illness and the care needed to handle it.","zh":"這個短語涵蓋疾病以及處理疾病所需的照顧。"}],"source":"151 - Health in the Wild.pdf","sourcePage":2},{"front":"one example of","meaning":"……的一個例子","examples":[{"en":"One example of self-medication was discovered in 1987.","zh":"自我用藥的一個例子於1987年被發現。"},{"en":"One example of something means one case that shows or explains it.","zh":"“One example of” 某事指展示或解釋它的一個案例。"},{"en":"One example of good teamwork is students sharing notes before an exam.","zh":"良好團隊合作的一個例子是學生考試前分享筆記。"},{"en":"A teacher gives one example of a grammar rule so students can understand it faster.","zh":"老師給出文法規則的一個例子，讓學生更快理解。"},{"en":"The phrase introduces a specific case from a larger idea.","zh":"這個短語引出較大概念中的具體案例。"}],"source":"151 - Health in the Wild.pdf","sourcePage":2},{"front":"be discovered in","meaning":"在……被發現","examples":[{"en":"One example of self-medication was discovered in 1987.","zh":"自我用藥的一個例子於1987年被發現。"},{"en":"To be discovered in a year or place means to be found or noticed there or then.","zh":"“Be discovered in” 某年份或地方指在該時或該地被發現或注意到。"},{"en":"A new plant species was discovered in a remote forest.","zh":"一種新植物物種在偏遠森林中被發現。"},{"en":"If a mistake is discovered in the report, it should be corrected quickly.","zh":"如果報告中發現錯誤，應該迅速改正。"},{"en":"The phrase is often used for research findings, facts, and problems.","zh":"這個短語常用於研究發現、事實和問題。"}],"source":"151 - Health in the Wild.pdf","sourcePage":2},{"front":"working in","meaning":"在……工作","examples":[{"en":"Michael Huffman and Mohamedi Seifu were working in Tanzania.","zh":"Michael Huffman 和 Mohamedi Seifu 當時在坦桑尼亞工作。"},{"en":"Working in a place means doing a job, project, or research there.","zh":"“Working in” 某地指在該地做工作、項目或研究。"},{"en":"A nurse working in a rural clinic may treat many different health problems.","zh":"在鄉村診所工作的護士可能治療許多不同健康問題。"},{"en":"Researchers working in forests must observe animals carefully and safely.","zh":"在森林工作的研究人員必須仔細而安全地觀察動物。"},{"en":"The phrase tells us where someone’s work takes place.","zh":"這個短語告訴我們某人的工作地點。"}],"source":"151 - Health in the Wild.pdf","sourcePage":2},{"front":"Mahale Mountains National Park","meaning":"馬哈萊山國家公園","examples":[{"en":"The researchers worked in the Mahale Mountains National Park.","zh":"研究人員在馬哈萊山國家公園工作。"},{"en":"Mahale Mountains National Park is the protected area where the researchers observed chimpanzees.","zh":"馬哈萊山國家公園是研究人員觀察黑猩猩的受保護地區。"},{"en":"Scientists may visit Mahale Mountains National Park to study wild chimpanzee behaviour.","zh":"科學家可能前往馬哈萊山國家公園研究野生黑猩猩行為。"},{"en":"A national park protects animals and their habitats from many forms of human disturbance.","zh":"國家公園保護動物及其棲息地免受多種人類干擾。"},{"en":"The phrase names a specific research location in Tanzania.","zh":"這個短語指坦桑尼亞一個特定研究地點。"}],"source":"151 - Health in the Wild.pdf","sourcePage":3},{"front":"local chimpanzees","meaning":"當地黑猩猩","examples":[{"en":"Local chimpanzees were observed eating a medicinal plant.","zh":"當地黑猩猩被觀察到進食一種藥用植物。"},{"en":"Local chimpanzees are chimpanzees living in the area being studied.","zh":"當地黑猩猩是指生活在研究地區的黑猩猩。"},{"en":"Local chimpanzees may know which plants are safe or useful in their own habitat.","zh":"當地黑猩猩可能知道自己棲息地中哪些植物安全或有用。"},{"en":"If local chimpanzees eat a rare plant only when sick, researchers may study it closely.","zh":"如果當地黑猩猩只在生病時吃某種罕見植物，研究人員可能會仔細研究它。"},{"en":"The phrase focuses on animals from a particular place.","zh":"這個短語強調來自特定地方的動物。"}],"source":"151 - Health in the Wild.pdf","sourcePage":3},{"front":"suffer from","meaning":"患有；受……折磨","examples":[{"en":"The chimpanzees were suffering from intestinal worms.","zh":"這些黑猩猩患有腸道寄生蟲。"},{"en":"To suffer from a disease means to experience pain, illness, or discomfort because of it.","zh":"“Suffer from” 某疾病指因它而經歷痛苦、疾病或不適。"},{"en":"A child who suffers from asthma may find it hard to breathe during exercise.","zh":"患有哮喘的孩子在運動時可能覺得呼吸困難。"},{"en":"If workers suffer from stress for months, their health and performance may decline.","zh":"如果工人長期受壓力折磨，他們的健康和表現可能下降。"},{"en":"The phrase is used for illnesses, symptoms, and long-term problems.","zh":"這個短語用於疾病、症狀和長期問題。"}],"source":"151 - Health in the Wild.pdf","sourcePage":3},{"front":"intestinal worms","meaning":"腸道寄生蟲","examples":[{"en":"Some chimpanzees suffered from intestinal worms.","zh":"一些黑猩猩患有腸道寄生蟲。"},{"en":"Intestinal worms are parasites that live inside the intestines of animals or people.","zh":"腸道寄生蟲是生活在動物或人體腸道中的寄生蟲。"},{"en":"Intestinal worms can cause stomach pain, weakness, and poor nutrition.","zh":"腸道寄生蟲可以導致腹痛、虛弱和營養不良。"},{"en":"If animals have intestinal worms, they may eat less and lose weight.","zh":"如果動物有腸道寄生蟲，牠們可能吃得較少並變瘦。"},{"en":"The phrase refers to parasites living in the digestive system.","zh":"這個短語指生活在消化系統中的寄生蟲。"}],"source":"151 - Health in the Wild.pdf","sourcePage":3},{"front":"dose themselves with","meaning":"自行服用……","examples":[{"en":"The chimpanzees dosed themselves with the pith of Vernonia.","zh":"這些黑猩猩自行服用斑鳩菊屬植物的植物髓部。"},{"en":"To dose themselves with something means to take a measured or effective amount of it as treatment.","zh":"“Dose themselves with” 某物指自行服用某種有治療作用的份量。"},{"en":"A sick animal may dose itself with a bitter plant that reduces parasites.","zh":"生病動物可能自行服用能減少寄生蟲的苦味植物。"},{"en":"If people dose themselves with medicine incorrectly, they may take too much or too little.","zh":"如果人們錯誤地自行服藥，可能服用太多或太少。"},{"en":"The phrase suggests self-treatment using a substance.","zh":"這個短語暗示使用某種物質進行自我治療。"}],"source":"151 - Health in the Wild.pdf","sourcePage":3},{"front":"pith","meaning":"植物髓部","examples":[{"en":"The chimps ate the pith of a plant called Vernonia.","zh":"黑猩猩吃一種名為斑鳩菊屬植物的植物髓部。"},{"en":"Pith is the soft inner part of a plant stem or branch.","zh":"植物髓部是植物莖或枝條中柔軟的內部部分。"},{"en":"Some animals chew plant pith because it contains water, fibre, or chemicals.","zh":"一些動物咀嚼植物髓部，因為它含有水分、纖維或化學物質。"},{"en":"If the pith contains strong chemicals, eating it may affect parasites or digestion.","zh":"如果植物髓部含有強烈化學物質，食用它可能影響寄生蟲或消化。"},{"en":"The word refers to a specific inner plant tissue, not the leaves or bark.","zh":"這個詞指特定的植物內部組織，而不是葉或樹皮。"}],"source":"151 - Health in the Wild.pdf","sourcePage":3},{"front":"a plant called","meaning":"一種名為……的植物","examples":[{"en":"The chimpanzees ate a plant called Vernonia.","zh":"黑猩猩吃一種名為斑鳩菊屬植物的植物。"},{"en":"A plant called something means a plant with that name.","zh":"“A plant called” 某名指一種擁有該名稱的植物。"},{"en":"A child may learn about a plant called mint because it is used in tea and cooking.","zh":"孩子可能學到一種名為薄荷的植物，因為它用於茶和烹飪。"},{"en":"If a plant called aloe is kept at home, people may use its gel on minor burns.","zh":"如果家中種有一種名為蘆薈的植物，人們可能用其凝膠處理輕微燙傷。"},{"en":"The phrase introduces the name of a plant simply and clearly.","zh":"這個短語簡單清楚地引出植物名稱。"}],"source":"151 - Health in the Wild.pdf","sourcePage":3},{"front":"Vernonia","meaning":"斑鳩菊屬植物","examples":[{"en":"Vernonia contains chemicals that can kill gut parasites.","zh":"斑鳩菊屬植物含有能殺死腸道寄生蟲的化學物質。"},{"en":"Vernonia is a plant whose inner pith may have medicinal effects for chimpanzees and people.","zh":"斑鳩菊屬植物是一種植物，其內部髓部可能對黑猩猩和人類有醫療作用。"},{"en":"Researchers studied Vernonia because sick chimpanzees were seen eating it.","zh":"研究人員研究斑鳩菊屬植物，因為生病黑猩猩被看見進食它。"},{"en":"If Vernonia contains useful chemicals, it may help explain animal self-medication.","zh":"如果斑鳩菊屬植物含有有用化學物質，它可能有助解釋動物自我用藥。"},{"en":"The word names a plant linked to parasite treatment in the passage.","zh":"這個詞指文章中與寄生蟲治療有關的一種植物。"}],"source":"151 - Health in the Wild.pdf","sourcePage":3},{"front":"poisonous chemicals","meaning":"有毒化學物質","examples":[{"en":"Vernonia produces poisonous chemicals called terpenes.","zh":"斑鳩菊屬植物產生名為萜烯的有毒化學物質。"},{"en":"Poisonous chemicals are substances that can harm or kill living things if the dose is high enough.","zh":"有毒化學物質是劑量足夠高時能傷害或殺死生物的物質。"},{"en":"Some cleaning products contain poisonous chemicals and must be kept away from children.","zh":"一些清潔用品含有有毒化學物質，必須遠離兒童。"},{"en":"Plants may produce poisonous chemicals to stop insects or animals from eating them.","zh":"植物可能產生有毒化學物質，以阻止昆蟲或動物吃掉它們。"},{"en":"The phrase does not always mean useless; some poisons can act as medicine in small amounts.","zh":"這個短語不一定表示無用；少量毒素有時可以成為藥物。"}],"source":"151 - Health in the Wild.pdf","sourcePage":3},{"front":"terpenes","meaning":"萜烯","examples":[{"en":"Terpenes can kill gut parasites at the right concentration.","zh":"在適當濃度下，萜烯可以殺死腸道寄生蟲。"},{"en":"Terpenes are natural chemicals found in some plants, often with strong smells or biological effects.","zh":"萜烯是一些植物中的天然化學物質，通常有強烈氣味或生物作用。"},{"en":"Some herbs contain terpenes that give them a sharp smell.","zh":"一些香草含有萜烯，使其有刺鼻氣味。"},{"en":"If terpenes are strong enough, they may affect insects, parasites, or other animals.","zh":"如果萜烯夠強，它們可能影響昆蟲、寄生蟲或其他動物。"},{"en":"The word names a group of plant chemicals.","zh":"這個詞指一組植物化學物質。"}],"source":"151 - Health in the Wild.pdf","sourcePage":3},{"front":"strong enough to","meaning":"強到足以……","examples":[{"en":"The concentration is strong enough to kill gut parasites.","zh":"這個濃度強到足以殺死腸道寄生蟲。"},{"en":"Strong enough to do something means powerful enough to produce a particular result.","zh":"“Strong enough to” 做某事指力量足以產生某個結果。"},{"en":"This disinfectant is strong enough to kill many common germs.","zh":"這種消毒劑強到足以殺死許多常見細菌。"},{"en":"If the wind is strong enough to break branches, people should stay indoors.","zh":"如果風強到足以折斷樹枝，人們應留在室內。"},{"en":"The phrase connects degree or power with an effect.","zh":"這個短語把程度或力量與效果連繫起來。"}],"source":"151 - Health in the Wild.pdf","sourcePage":3},{"front":"concentration","meaning":"濃度","examples":[{"en":"The pith contains a strong concentration of terpenes.","zh":"植物髓部含有高濃度萜烯。"},{"en":"Concentration means the amount of a substance within a mixture or solution.","zh":"濃度指混合物或溶液中某物質的含量。"},{"en":"A high concentration of salt makes soup taste too salty.","zh":"高濃度鹽會令湯太鹹。"},{"en":"If the concentration of medicine is too high, it may cause side effects.","zh":"如果藥物濃度太高，可能造成副作用。"},{"en":"The word is useful when discussing chemicals, medicine, and pollution.","zh":"這個詞常用於討論化學物質、藥物和污染。"}],"source":"151 - Health in the Wild.pdf","sourcePage":4},{"front":"gut parasites","meaning":"腸道寄生蟲","examples":[{"en":"The chemicals can kill gut parasites.","zh":"這些化學物質可以殺死腸道寄生蟲。"},{"en":"Gut parasites are organisms that live in the digestive system and take nutrients from their host.","zh":"腸道寄生蟲是生活在消化系統並從宿主身上吸取營養的生物。"},{"en":"Gut parasites can make animals weak because they steal food from the body.","zh":"腸道寄生蟲會令動物虛弱，因為牠們從身體奪取食物。"},{"en":"If gut parasites spread through dirty water, better sanitation can reduce infection.","zh":"如果腸道寄生蟲透過骯髒食水傳播，改善衛生可以減少感染。"},{"en":"The phrase is similar to intestinal parasites.","zh":"這個短語與 intestinal parasites 意思相近。"}],"source":"151 - Health in the Wild.pdf","sourcePage":4},{"front":"not so strong as to","meaning":"未至於強到……","examples":[{"en":"The concentration is not so strong as to kill chimps.","zh":"這個濃度未至於強到殺死黑猩猩。"},{"en":"Not so strong as to do something means not strong enough to cause that extreme result.","zh":"“Not so strong as to” 做某事指未強到造成那種極端結果。"},{"en":"The medicine is strong enough to reduce pain but not so strong as to make patients sleepy all day.","zh":"這種藥強到足以減痛，但未至於強到令病人整天昏睡。"},{"en":"The rain was heavy but not so strong as to close the roads.","zh":"雨很大，但未至於強到封路。"},{"en":"The phrase shows a careful limit between useful and dangerous.","zh":"這個短語顯示有用與危險之間的謹慎界線。"}],"source":"151 - Health in the Wild.pdf","sourcePage":4},{"front":"for that matter","meaning":"就此而言","examples":[{"en":"The plant does not kill chimps, nor people, for that matter.","zh":"這種植物不會殺死黑猩猩，就此而言，也不會殺死人。"},{"en":"For that matter is used to add another related point, often casually or for emphasis.","zh":"“For that matter” 用來加入另一個相關重點，常帶口語或強調意味。"},{"en":"The rule applies to students and, for that matter, teachers as well.","zh":"這條規則適用於學生；就此而言，也適用於老師。"},{"en":"If the lift is unsafe for children, it is unsafe for adults, for that matter.","zh":"如果升降機對兒童不安全，就此而言，對成年人也不安全。"},{"en":"The phrase adds “also” in a natural spoken way.","zh":"這個短語以自然口語方式加入「也一樣」的意思。"}],"source":"151 - Health in the Wild.pdf","sourcePage":4},{"front":"for the same purpose","meaning":"為同一用途","examples":[{"en":"Locals use the pith for the same purpose.","zh":"當地人為同一用途使用該植物髓部。"},{"en":"For the same purpose means for the same reason or use already mentioned.","zh":"“For the same purpose” 指為了前面已提及的同一原因或用途。"},{"en":"Students use flashcards to remember vocabulary; teachers may use quizzes for the same purpose.","zh":"學生用詞卡記單詞；老師也可能為同一用途使用小測。"},{"en":"If animals and humans use the same plant for the same purpose, scientists may study it closely.","zh":"如果動物和人類為同一用途使用同一植物，科學家可能仔細研究它。"},{"en":"The phrase avoids repeating the reason again.","zh":"這個短語避免再次重複原因。"}],"source":"151 - Health in the Wild.pdf","sourcePage":4},{"front":"given that","meaning":"鑑於","examples":[{"en":"Given that the plant is called goat-killer, it can be dangerous.","zh":"鑑於這種植物被稱為殺羊草，它可能很危險。"},{"en":"Given that means considering the fact that something is true.","zh":"“Given that” 指考慮到某事屬實。"},{"en":"Given that the exam is tomorrow, students should sleep early tonight.","zh":"鑑於考試明天舉行，學生今晚應早點睡覺。"},{"en":"Given that prices are rising, families may cut unnecessary spending.","zh":"鑑於物價上升，家庭可能削減不必要開支。"},{"en":"The phrase introduces a reason for a judgement or decision.","zh":"這個短語引出判斷或決定的理由。"}],"source":"151 - Health in the Wild.pdf","sourcePage":4},{"front":"be known locally as","meaning":"在當地被稱為","examples":[{"en":"The plant is known locally as goat-killer.","zh":"這種植物在當地被稱為殺羊草。"},{"en":"To be known locally as something means people in that area call it by that name.","zh":"“Be known locally as” 某名稱指當地人用該名稱稱呼它。"},{"en":"This small street is known locally as Food Lane because of its many restaurants.","zh":"這條小街因有很多餐廳，在當地被稱為美食巷。"},{"en":"If a plant is known locally as poison leaf, visitors should be careful.","zh":"如果一種植物在當地被稱為毒葉，訪客應該小心。"},{"en":"The phrase shows a local name rather than an official scientific name.","zh":"這個短語顯示本地名稱，而不是正式科學名稱。"}],"source":"151 - Health in the Wild.pdf","sourcePage":4},{"front":"goat-killer","meaning":"殺羊草","examples":[{"en":"Vernonia is known locally as goat-killer.","zh":"斑鳩菊屬植物在當地被稱為殺羊草。"},{"en":"Goat-killer is a local name suggesting that the plant can be dangerous to goats.","zh":"殺羊草是一個本地名稱，暗示這種植物可能對羊有危險。"},{"en":"A plant called goat-killer would make farmers cautious about where animals graze.","zh":"一種叫殺羊草的植物會令農民小心動物在哪裡吃草。"},{"en":"If goats eat too much goat-killer, they may become ill or die.","zh":"如果羊吃太多殺羊草，可能會生病或死亡。"},{"en":"The name gives a warning about the plant’s possible toxicity.","zh":"這個名稱提醒人這種植物可能有毒。"}],"source":"151 - Health in the Wild.pdf","sourcePage":4},{"front":"be as smart as","meaning":"像……一樣聰明","examples":[{"en":"Not all animals are as smart as chimps and humans.","zh":"不是所有動物都像黑猩猩和人類一樣聰明。"},{"en":"To be as smart as someone means to have a similar level of intelligence or judgement.","zh":"“Be as smart as” 某人指擁有相近程度的智力或判斷力。"},{"en":"A young child may be as smart as an adult in solving certain puzzles.","zh":"年幼孩子在解決某些謎題時可能像成年人一樣聰明。"},{"en":"If an animal is not as smart as another, it may not use dangerous plants safely.","zh":"如果一種動物不像另一種一樣聰明，它可能不能安全使用危險植物。"},{"en":"The phrase compares intelligence between people or animals.","zh":"這個短語比較人或動物之間的智力。"}],"source":"151 - Health in the Wild.pdf","sourcePage":4},{"front":"consume it indiscriminately","meaning":"不加選擇地食用它","examples":[{"en":"Some animals consume the plant indiscriminately.","zh":"一些動物不加選擇地食用這種植物。"},{"en":"To consume something indiscriminately means to eat or use it without careful choice or control.","zh":"“Consume something indiscriminately” 指沒有仔細選擇或控制地食用或使用某物。"},{"en":"Children may get sick if they consume snacks indiscriminately without checking ingredients.","zh":"如果孩子不檢查成分就不加選擇地吃零食，可能會生病。"},{"en":"If animals consume a poisonous plant indiscriminately, they may take a dangerous dose.","zh":"如果動物不加選擇地食用有毒植物，可能攝入危險劑量。"},{"en":"The phrase suggests careless or uncontrolled consumption.","zh":"這個短語暗示粗心或不受控制的攝取。"}],"source":"151 - Health in the Wild.pdf","sourcePage":4},{"front":"succumb","meaning":"死去；不敵而倒下","examples":[{"en":"Some animals consume Vernonia indiscriminately and succumb.","zh":"一些動物不加選擇地食用斑鳩菊屬植物，然後死去。"},{"en":"To succumb means to die, collapse, or be defeated by illness, poison, pressure, or danger.","zh":"“Succumb” 指因疾病、毒素、壓力或危險而死亡、倒下或被擊敗。"},{"en":"A plant may succumb to drought if it receives no water for weeks.","zh":"如果植物數星期沒有水，可能不敵乾旱而枯死。"},{"en":"If animals eat too much poison, they may succumb quickly.","zh":"如果動物吃下太多毒物，可能很快死去。"},{"en":"The word is formal and often describes failing under something harmful.","zh":"這個詞較正式，常描述在有害事物下失敗或倒下。"}],"source":"151 - Health in the Wild.pdf","sourcePage":4},{"front":"evidence has emerged","meaning":"證據逐漸出現","examples":[{"en":"More evidence has emerged about animal self-medication.","zh":"關於動物自我用藥，更多證據逐漸出現。"},{"en":"Evidence has emerged means new information has appeared and become known.","zh":"“Evidence has emerged” 指新資料出現並被人知道。"},{"en":"Evidence has emerged that some students learn better with shorter, focused lessons.","zh":"有證據逐漸出現，顯示一些學生用較短而集中的課堂學得更好。"},{"en":"If evidence has emerged about a health risk, officials should warn the public.","zh":"如果關於健康風險的證據逐漸出現，官員應提醒公眾。"},{"en":"The phrase is common in research, news, and investigations.","zh":"這個短語常見於研究、新聞和調查。"}],"source":"151 - Health in the Wild.pdf","sourcePage":5},{"front":"suggesting that","meaning":"顯示；表明","examples":[{"en":"Evidence has emerged suggesting that animals eat things for medical reasons.","zh":"證據逐漸出現，顯示動物出於醫療原因進食某些東西。"},{"en":"Suggesting that means showing or implying that something may be true.","zh":"“Suggesting that” 指顯示或暗示某事可能為真。"},{"en":"Dark clouds are forming, suggesting that rain may come soon.","zh":"烏雲正在形成，顯示可能快要下雨。"},{"en":"If many patients improve after the same treatment, this may be evidence suggesting that it works.","zh":"如果許多病人在同一治療後好轉，這可能是顯示治療有效的證據。"},{"en":"The phrase signals a possible conclusion, not always final proof.","zh":"這個短語表示可能結論，不一定是最終證明。"}],"source":"151 - Health in the Wild.pdf","sourcePage":5},{"front":"for medical rather than nutritional reasons","meaning":"出於醫療而非營養原因","examples":[{"en":"Animals may eat some things for medical rather than nutritional reasons.","zh":"動物可能出於醫療而非營養原因進食某些東西。"},{"en":"For medical rather than nutritional reasons means for treating illness, not mainly for gaining food energy or nutrients.","zh":"“For medical rather than nutritional reasons” 指為了治病，而不是主要為了獲得食物能量或營養。"},{"en":"A parrot may eat clay for medical rather than nutritional reasons after eating toxic seeds.","zh":"鸚鵡吃下有毒種子後，可能出於醫療而非營養原因吃黏土。"},{"en":"If an animal eats a bitter plant only when sick, the reason may be medical rather than nutritional.","zh":"如果動物只在生病時吃苦味植物，原因可能是醫療而非營養。"},{"en":"The phrase clearly contrasts treatment with ordinary feeding.","zh":"這個短語清楚對比治療與普通進食。"}],"source":"151 - Health in the Wild.pdf","sourcePage":5},{"front":"many species","meaning":"許多物種","examples":[{"en":"Many species consume dirt.","zh":"許多物種吃泥土。"},{"en":"Many species means many different kinds of animals, plants, or living organisms.","zh":"“Many species” 指許多不同種類的動物、植物或生物。"},{"en":"Many species of birds migrate when the weather becomes cold.","zh":"許多鳥類物種在天氣變冷時遷徙。"},{"en":"If many species disappear from a forest, the ecosystem becomes weaker.","zh":"如果許多物種從森林中消失，生態系統會變弱。"},{"en":"The phrase is useful when describing patterns across different living things.","zh":"這個短語適合描述不同生物之間的模式。"}],"source":"151 - Health in the Wild.pdf","sourcePage":5},{"front":"consume dirt","meaning":"吃泥土","examples":[{"en":"Many species consume dirt as part of their behaviour.","zh":"許多物種把吃泥土作為其行為的一部分。"},{"en":"To consume dirt means to eat soil, earth, or clay.","zh":"“Consume dirt” 指吃土壤、泥土或黏土。"},{"en":"Some parrots consume dirt after eating seeds that may contain toxins.","zh":"一些鸚鵡在吃下可能含有毒素的種子後會吃泥土。"},{"en":"If animals consume dirt regularly, scientists may ask what benefit it provides.","zh":"如果動物定期吃泥土，科學家可能會問它有甚麼好處。"},{"en":"The phrase sounds strange in daily life, but it is a real animal behaviour.","zh":"這個短語在日常生活中聽起來奇怪，但它是真實的動物行為。"}],"source":"151 - Health in the Wild.pdf","sourcePage":5},{"front":"a behaviour known as","meaning":"一種稱為……的行為","examples":[{"en":"Eating dirt is a behaviour known as geophagy.","zh":"吃泥土是一種稱為食土行為的行為。"},{"en":"A behaviour known as something means an action that has that particular name.","zh":"“A behaviour known as” 某名稱指擁有該特定名稱的一種行動。"},{"en":"Birds cleaning each other’s feathers is a behaviour known as preening.","zh":"鳥類互相清潔羽毛是一種稱為理羽的行為。"},{"en":"If scientists identify a repeated action, they may describe it as a behaviour known as a specific term.","zh":"如果科學家辨認出一種重複行動，他們可能把它描述為一種稱為某術語的行為。"},{"en":"The phrase introduces a technical name in a clear way.","zh":"這個短語清楚引入專門名稱。"}],"source":"151 - Health in the Wild.pdf","sourcePage":5},{"front":"geophagy","meaning":"食土行為","examples":[{"en":"Geophagy means consuming earth or soil.","zh":"食土行為指食用泥土或土壤。"},{"en":"Geophagy is the behaviour of eating soil, clay, or earth.","zh":"食土行為是吃土壤、黏土或泥土的行為。"},{"en":"Some birds practise geophagy when clay helps reduce the effects of plant toxins.","zh":"一些鳥類在黏土有助減少植物毒素影響時會進行食土行為。"},{"en":"If geophagy appears in many species, it may have an important biological purpose.","zh":"如果食土行為出現在許多物種中，它可能有重要生物目的。"},{"en":"The word is scientific and refers specifically to earth-eating.","zh":"這個詞較科學，專指吃泥土。"}],"source":"151 - Health in the Wild.pdf","sourcePage":5},{"front":"historically","meaning":"歷來；以往","examples":[{"en":"Historically, scientists thought animals ate soil for minerals.","zh":"歷來，科學家認為動物吃泥土是為了礦物質。"},{"en":"Historically means in the past or according to past understanding.","zh":"“Historically” 指在過去或根據以往理解。"},{"en":"Historically, many people believed the sun moved around the Earth.","zh":"以往，許多人相信太陽圍繞地球運行。"},{"en":"If a custom was historically important, people may still respect it today.","zh":"如果一項習俗歷來很重要，人們今天可能仍尊重它。"},{"en":"The word often contrasts older views with newer evidence.","zh":"這個詞常把舊觀點與新證據作對比。"}],"source":"151 - Health in the Wild.pdf","sourcePage":5},{"front":"preferred explanation","meaning":"較受接受的解釋","examples":[{"en":"The preferred explanation was that soil supplied minerals.","zh":"較受接受的解釋是泥土提供礦物質。"},{"en":"The preferred explanation is the explanation most accepted or favoured at a particular time.","zh":"“The preferred explanation” 指在某時期最被接受或偏好的解釋。"},{"en":"The preferred explanation for the delay was bad weather, not poor planning.","zh":"對延誤較受接受的解釋是惡劣天氣，而不是規劃不足。"},{"en":"If new evidence appears, the preferred explanation may change.","zh":"如果新證據出現，較受接受的解釋可能改變。"},{"en":"The phrase shows which theory people find most convincing.","zh":"這個短語顯示人們認為哪個理論最有說服力。"}],"source":"151 - Health in the Wild.pdf","sourcePage":5},{"front":"supply minerals","meaning":"提供礦物質","examples":[{"en":"Soil was thought to supply minerals such as salt.","zh":"人們曾認為泥土提供鹽等礦物質。"},{"en":"To supply minerals means to provide minerals that the body may need.","zh":"“Supply minerals” 指提供身體可能需要的礦物質。"},{"en":"Milk can supply minerals such as calcium for bones.","zh":"牛奶可以為骨骼提供鈣等礦物質。"},{"en":"If food does not supply minerals, people may need a more balanced diet.","zh":"如果食物不能提供礦物質，人們可能需要更均衡飲食。"},{"en":"The phrase connects a food or substance with useful nutrients.","zh":"這個短語把食物或物質與有用營養素連繫起來。"}],"source":"151 - Health in the Wild.pdf","sourcePage":5},{"front":"such as salt","meaning":"例如鹽","examples":[{"en":"Soil may supply minerals such as salt.","zh":"泥土可能提供例如鹽的礦物質。"},{"en":"Such as salt introduces salt as one example of a larger group.","zh":"“Such as salt” 把鹽作為較大類別中的一個例子。"},{"en":"Athletes may need minerals such as salt after heavy sweating.","zh":"運動員大量流汗後可能需要例如鹽的礦物質。"},{"en":"If a soup contains too much seasoning such as salt, it may taste unpleasant.","zh":"如果湯含有太多例如鹽的調味料，味道可能不好。"},{"en":"The phrase is used to give a simple example.","zh":"這個短語用來給出簡單例子。"}],"source":"151 - Health in the Wild.pdf","sourcePage":5},{"front":"occur in areas where","meaning":"發生在……的地區","examples":[{"en":"Geophagy occurs in areas where the earth is not mineral-rich.","zh":"食土行為發生在泥土不富含礦物質的地區。"},{"en":"To occur in areas where something is true means to happen in places with that condition.","zh":"“Occur in areas where” 某情況成立，指在具有該條件的地方發生。"},{"en":"Flooding often occurs in areas where drainage is poor.","zh":"水浸常發生在排水差的地區。"},{"en":"If a disease occurs in areas where clean water is scarce, water supply may be part of the problem.","zh":"如果疾病發生在潔淨食水稀缺的地區，供水可能是問題的一部分。"},{"en":"The phrase connects an event with the type of place where it happens.","zh":"這個短語把事件與其發生地點的類型連繫起來。"}],"source":"151 - Health in the Wild.pdf","sourcePage":6},{"front":"a useful source of","meaning":"……的有用來源","examples":[{"en":"The earth is not always a useful source of minerals.","zh":"泥土並不總是礦物質的有用來源。"},{"en":"A useful source of something provides it in a helpful or practical way.","zh":"某物的有用來源指能以有幫助或實際方式提供它的來源。"},{"en":"Milk is a useful source of calcium for many children.","zh":"牛奶對許多孩子來說是鈣的有用來源。"},{"en":"If a website is a useful source of information, students can rely on it for revision.","zh":"如果一個網站是資訊的有用來源，學生可以依靠它溫習。"},{"en":"The phrase describes where something valuable can be obtained.","zh":"這個短語描述有價值事物可以從哪裡取得。"}],"source":"151 - Health in the Wild.pdf","sourcePage":6},{"front":"be more easily obtained from","meaning":"更容易從……取得","examples":[{"en":"Minerals can sometimes be more easily obtained from plants.","zh":"礦物質有時更容易從植物取得。"},{"en":"To be more easily obtained from something means it is simpler to get from that source.","zh":"“Be more easily obtained from” 某來源指從該來源取得更簡單。"},{"en":"Vitamin C is more easily obtained from fruit than from many processed snacks.","zh":"維他命C比起許多加工零食，更容易從水果取得。"},{"en":"If information is more easily obtained from a website, students may not visit the library first.","zh":"如果資訊更容易從網站取得，學生可能不會先去圖書館。"},{"en":"The phrase compares different sources of the same thing.","zh":"這個短語比較同一事物的不同來源。"}],"source":"151 - Health in the Wild.pdf","sourcePage":6},{"front":"rich in","meaning":"富含……","examples":[{"en":"Certain plants are rich in minerals.","zh":"某些植物富含礦物質。"},{"en":"Rich in something means containing a large amount of it.","zh":"“Rich in” 某物指含有大量該物。"},{"en":"Spinach is rich in iron and other nutrients.","zh":"菠菜富含鐵和其他營養素。"},{"en":"A city rich in history may attract visitors who enjoy museums and old buildings.","zh":"一個富含歷史的城市可能吸引喜歡博物館和古建築的遊客。"},{"en":"The phrase can describe food, places, culture, or resources.","zh":"這個短語可以描述食物、地方、文化或資源。"}],"source":"151 - Health in the Wild.pdf","sourcePage":6},{"front":"get something out of","meaning":"從……中得到某些東西","examples":[{"en":"Animals must be getting something else out of eating earth.","zh":"動物一定是從吃泥土中得到某些其他東西。"},{"en":"To get something out of an activity means to gain a benefit from it.","zh":"“Get something out of” 某活動指從中得到好處。"},{"en":"Students get confidence out of practising speaking every week.","zh":"學生從每週練習口語中得到信心。"},{"en":"If animals get something out of eating clay, the behaviour may help them survive.","zh":"如果動物從吃黏土中得到某些東西，這種行為可能幫助牠們生存。"},{"en":"The phrase asks what useful result comes from an action.","zh":"這個短語詢問某行動帶來甚麼有用結果。"}],"source":"151 - Health in the Wild.pdf","sourcePage":6},{"front":"current belief","meaning":"現時看法","examples":[{"en":"The current belief is that clay helps detoxify poisons.","zh":"現時看法是黏土有助為毒素解毒。"},{"en":"The current belief is the idea most accepted at the present time.","zh":"“The current belief” 指目前最被接受的想法。"},{"en":"The current belief among teachers is that examples help students remember words better.","zh":"教師之間的現時看法是例子幫助學生更好記住詞語。"},{"en":"If new evidence appears, the current belief may change.","zh":"如果新證據出現，現時看法可能改變。"},{"en":"The phrase contrasts present understanding with older explanations.","zh":"這個短語把現在理解與舊解釋作對比。"}],"source":"151 - Health in the Wild.pdf","sourcePage":6},{"front":"particularly","meaning":"尤其","examples":[{"en":"Soil, particularly the clay in it, may help animals.","zh":"泥土，尤其是其中的黏土，可能幫助動物。"},{"en":"Particularly means especially or more than other things in the same group.","zh":"“Particularly” 指尤其，或比同一組其他事物更甚。"},{"en":"I enjoy fruit, particularly mangoes.","zh":"我喜歡水果，尤其是芒果。"},{"en":"If students are tired, long grammar lessons are particularly difficult to follow.","zh":"如果學生疲倦，長文法課尤其難以跟上。"},{"en":"The word highlights one important example or detail.","zh":"這個詞突出一個重要例子或細節。"}],"source":"151 - Health in the Wild.pdf","sourcePage":6},{"front":"clay","meaning":"黏土","examples":[{"en":"Clay may help detoxify plant poisons.","zh":"黏土可能有助為植物毒素解毒。"},{"en":"Clay is a fine, sticky type of earth that can hold water and bind with some substances.","zh":"黏土是一種細緻而帶黏性的泥土，可以保水並與某些物質結合。"},{"en":"Children may use clay to make simple shapes in art class.","zh":"孩子在美術課可能用黏土製作簡單形狀。"},{"en":"In animals, clay may help reduce the effects of toxins in food.","zh":"在動物身上，黏土可能有助減少食物中毒素的影響。"},{"en":"The word can refer to both a natural material and a material used in crafts.","zh":"這個詞可以指天然材料，也可以指手工藝材料。"}],"source":"151 - Health in the Wild.pdf","sourcePage":6},{"front":"detoxify","meaning":"解毒","examples":[{"en":"Clay helps detoxify the poisons in some plants.","zh":"黏土有助為一些植物中的毒素解毒。"},{"en":"To detoxify means to remove, reduce, or neutralise harmful substances.","zh":"“Detoxify” 指移除、減少或中和有害物質。"},{"en":"The liver helps detoxify many substances that enter the body.","zh":"肝臟有助為進入身體的許多物質解毒。"},{"en":"If clay can detoxify plant poisons, animals may eat it after toxic food.","zh":"如果黏土能為植物毒素解毒，動物可能在吃有毒食物後吃它。"},{"en":"The word is common in biology, health, and environmental science.","zh":"這個詞常見於生物、健康和環境科學。"}],"source":"151 - Health in the Wild.pdf","sourcePage":6},{"front":"defensive poisons","meaning":"防禦性毒素","examples":[{"en":"Some plants produce defensive poisons.","zh":"一些植物產生防禦性毒素。"},{"en":"Defensive poisons are toxins that protect plants or animals from being eaten or attacked.","zh":"防禦性毒素是保護植物或動物免被吃掉或攻擊的毒素。"},{"en":"A plant may use defensive poisons to stop insects from chewing its leaves.","zh":"植物可能使用防禦性毒素來阻止昆蟲咀嚼其葉子。"},{"en":"If herbivores eat plants with defensive poisons, they may need ways to detoxify them.","zh":"如果草食動物吃含有防禦性毒素的植物，牠們可能需要方法解毒。"},{"en":"The phrase shows that poison can be a form of protection.","zh":"這個短語顯示毒素可以是一種保護形式。"}],"source":"151 - Health in the Wild.pdf","sourcePage":6},{"front":"in an attempt to","meaning":"試圖","examples":[{"en":"Plants produce poisons in an attempt to avoid being eaten.","zh":"植物產生毒素，試圖避免被吃掉。"},{"en":"In an attempt to do something means trying to achieve that result.","zh":"“In an attempt to” 做某事指試圖達到該結果。"},{"en":"A student may rewrite notes in an attempt to remember them better.","zh":"學生可能重寫筆記，試圖更好記住它們。"},{"en":"The city planted more trees in an attempt to reduce summer heat.","zh":"城市種植更多樹木，試圖減少夏季高溫。"},{"en":"The phrase shows purpose, but not guaranteed success.","zh":"這個短語顯示目的，但不保證成功。"}],"source":"151 - Health in the Wild.pdf","sourcePage":6},{"front":"prevent themselves from being eaten","meaning":"防止自己被吃掉","examples":[{"en":"Some plants produce poisons to prevent themselves from being eaten.","zh":"一些植物產生毒素來防止自己被吃掉。"},{"en":"To prevent themselves from being eaten means to stop animals or insects from consuming them.","zh":"“Prevent themselves from being eaten” 指阻止動物或昆蟲食用自己。"},{"en":"Thorny plants prevent themselves from being eaten by making leaves difficult to reach.","zh":"帶刺植物透過令葉子難以接觸來防止自己被吃掉。"},{"en":"If a plant tastes bitter, it may prevent itself from being eaten by hungry animals.","zh":"如果植物味道苦，它可能防止自己被飢餓動物吃掉。"},{"en":"The phrase describes a survival strategy in plants.","zh":"這個短語描述植物的一種生存策略。"}],"source":"151 - Health in the Wild.pdf","sourcePage":7},{"front":"evidence for","meaning":"……的證據","examples":[{"en":"Evidence for the detoxifying nature of clay came from an experiment.","zh":"黏土解毒特性的證據來自一項實驗。"},{"en":"Evidence for something is information that supports or proves it.","zh":"“Evidence for” 某事是支持或證明它的資料。"},{"en":"Improved test scores can be evidence for the effectiveness of a new teaching method.","zh":"考試成績改善可以是新教學方法有效的證據。"},{"en":"If there is little evidence for a claim, people should be cautious about accepting it.","zh":"如果某主張的證據很少，人們應謹慎接受它。"},{"en":"The phrase introduces support for an idea.","zh":"這個短語引出支持某想法的資料。"}],"source":"151 - Health in the Wild.pdf","sourcePage":7},{"front":"detoxifying nature","meaning":"解毒特性","examples":[{"en":"The experiment tested the detoxifying nature of clay.","zh":"該實驗測試了黏土的解毒特性。"},{"en":"The detoxifying nature of something is its ability to reduce or neutralise poison.","zh":"某物的解毒特性是其減少或中和毒素的能力。"},{"en":"Scientists may test the detoxifying nature of a substance before using it in medicine.","zh":"科學家在把某物用於藥物前，可能會測試其解毒特性。"},{"en":"If clay has a detoxifying nature, it can explain why animals eat it after toxic food.","zh":"如果黏土有解毒特性，就能解釋為何動物在吃有毒食物後吃它。"},{"en":"The phrase describes a natural property related to removing harm.","zh":"這個短語描述與消除傷害有關的自然屬性。"}],"source":"151 - Health in the Wild.pdf","sourcePage":7},{"front":"carry out an experiment","meaning":"進行實驗","examples":[{"en":"James Gilardi and his colleagues carried out an experiment on macaws.","zh":"James Gilardi 和他的同事對金剛鸚鵡進行實驗。"},{"en":"To carry out an experiment means to perform a scientific test.","zh":"“Carry out an experiment” 指進行科學測試。"},{"en":"Students carried out an experiment to see which soil held the most water.","zh":"學生進行實驗，看看哪種土壤保水最多。"},{"en":"If researchers carry out an experiment carefully, their results are more reliable.","zh":"如果研究人員仔細進行實驗，其結果會更可靠。"},{"en":"The phrase is common in science writing.","zh":"這個短語常見於科學寫作。"}],"source":"151 - Health in the Wild.pdf","sourcePage":7},{"front":"macaws","meaning":"金剛鸚鵡","examples":[{"en":"Macaws were used in an experiment on clay eating.","zh":"金剛鸚鵡被用於關於吃黏土的實驗。"},{"en":"Macaws are large, colourful parrots found in Central and South America.","zh":"金剛鸚鵡是生活在中南美洲的大型彩色鸚鵡。"},{"en":"Macaws may use their strong beaks to crack seeds and nuts.","zh":"金剛鸚鵡可能用強壯鳥喙咬開種子和堅果。"},{"en":"If macaws eat clay after toxic seeds, scientists may study the reason.","zh":"如果金剛鸚鵡在吃有毒種子後吃黏土，科學家可能研究原因。"},{"en":"The word refers to a type of parrot, not all birds.","zh":"這個詞指一種鸚鵡，而不是所有鳥類。"}],"source":"151 - Health in the Wild.pdf","sourcePage":7},{"front":"seeds containing","meaning":"含有……的種子","examples":[{"en":"Macaws eat seeds containing alkaloids.","zh":"金剛鸚鵡吃含有生物鹼的種子。"},{"en":"Seeds containing something are seeds that have that substance inside them.","zh":"“Seeds containing” 某物指內部含有該物質的種子。"},{"en":"Seeds containing oil can be pressed to make cooking oil.","zh":"含有油分的種子可以被壓榨成食油。"},{"en":"If birds eat seeds containing toxins, they may need protection from the harmful chemicals.","zh":"如果鳥類吃含有毒素的種子，牠們可能需要免受有害化學物質影響。"},{"en":"The phrase describes what is inside the seeds.","zh":"這個短語描述種子內含有甚麼。"}],"source":"151 - Health in the Wild.pdf","sourcePage":7},{"front":"alkaloids","meaning":"生物鹼","examples":[{"en":"Alkaloids include some notoriously toxic chemicals.","zh":"生物鹼包括一些出名有毒的化學物質。"},{"en":"Alkaloids are a group of natural chemicals found in many plants, some of which can affect animals strongly.","zh":"生物鹼是一組存在於許多植物中的天然化學物質，其中一些能強烈影響動物。"},{"en":"Some alkaloids are used in medicine, while others are poisonous.","zh":"一些生物鹼用於藥物，而另一些則有毒。"},{"en":"If seeds contain alkaloids, animals may need ways to reduce their effects.","zh":"如果種子含有生物鹼，動物可能需要方法減低其影響。"},{"en":"The word is scientific and refers to a chemical group.","zh":"這個詞較科學，指一組化學物質。"}],"source":"151 - Health in the Wild.pdf","sourcePage":7},{"front":"a group of chemicals","meaning":"一組化學物質","examples":[{"en":"Alkaloids are a group of chemicals.","zh":"生物鹼是一組化學物質。"},{"en":"A group of chemicals means several related substances with similar features.","zh":"“A group of chemicals” 指幾種具有相似特徵的相關物質。"},{"en":"Vitamins are a group of chemicals that the body needs in small amounts.","zh":"維他命是一組身體少量需要的化學物質。"},{"en":"If a group of chemicals is toxic, scientists must test safe exposure levels.","zh":"如果一組化學物質有毒，科學家必須測試安全接觸水平。"},{"en":"The phrase classifies substances together.","zh":"這個短語把物質歸為同一類。"}],"source":"151 - Health in the Wild.pdf","sourcePage":7},{"front":"notoriously toxic","meaning":"出名有毒的","examples":[{"en":"Some alkaloids are notoriously toxic.","zh":"一些生物鹼出名有毒。"},{"en":"Notoriously toxic means widely known for being poisonous or dangerous.","zh":"“Notoriously toxic” 指因有毒或危險而廣為人知。"},{"en":"Some mushrooms are notoriously toxic and should never be eaten without expert knowledge.","zh":"一些蘑菇出名有毒，沒有專業知識絕不應食用。"},{"en":"If a chemical is notoriously toxic, even small mistakes in handling it can be dangerous.","zh":"如果某化學物質出名有毒，即使處理時小錯誤也可能危險。"},{"en":"The phrase strongly warns that something is famous for harm.","zh":"這個短語強烈警告某物以有害聞名。"}],"source":"151 - Health in the Wild.pdf","sourcePage":7},{"front":"strychnine","meaning":"士的寧；馬錢子鹼","examples":[{"en":"Strychnine is a notoriously toxic alkaloid.","zh":"士的寧是一種出名有毒的生物鹼。"},{"en":"Strychnine is a highly poisonous chemical that can seriously harm or kill animals and people.","zh":"士的寧是一種劇毒化學物質，可以嚴重傷害或殺死動物和人類。"},{"en":"Scientists mention strychnine as an example of a dangerous alkaloid.","zh":"科學家把士的寧作為危險生物鹼的例子。"},{"en":"If a substance contains strychnine, it must be handled with extreme care.","zh":"如果某物質含有士的寧，必須極小心處理。"},{"en":"The word names a specific toxic compound.","zh":"這個詞指一種特定有毒化合物。"}],"source":"151 - Health in the Wild.pdf","sourcePage":7},{"front":"in the wild","meaning":"在野外","examples":[{"en":"In the wild, macaws are often seen eating clay.","zh":"在野外，金剛鸚鵡常被看見吃黏土。"},{"en":"In the wild means in natural conditions, not in captivity or under human control.","zh":"“In the wild” 指在自然環境中，而不是被圈養或受人類控制。"},{"en":"In the wild, animals must find food and avoid danger by themselves.","zh":"在野外，動物必須自己尋找食物並避開危險。"},{"en":"Behaviour seen in the wild may differ from behaviour seen in a zoo.","zh":"在野外觀察到的行為可能不同於動物園中的行為。"},{"en":"The phrase is used when describing natural animal life.","zh":"這個短語用於描述動物的自然生活。"}],"source":"151 - Health in the Wild.pdf","sourcePage":7},{"front":"be perched on","meaning":"棲息在……上","examples":[{"en":"The birds are frequently seen perched on eroding riverbanks.","zh":"這些鳥常被看見棲息在受侵蝕的河岸上。"},{"en":"To be perched on something means to sit or rest on a high or narrow place.","zh":"“Be perched on” 某物指坐在或停留在高處或狹窄地方。"},{"en":"A bird may be perched on a branch outside the classroom window.","zh":"一隻鳥可能棲息在課室窗外的樹枝上。"},{"en":"If parrots are perched on a riverbank, they may be feeding or resting there.","zh":"如果鸚鵡棲息在河岸上，牠們可能正在進食或休息。"},{"en":"The phrase often describes birds sitting above the ground.","zh":"這個短語常描述鳥類坐在離地面較高的位置。"}],"source":"151 - Health in the Wild.pdf","sourcePage":8},{"front":"eroding riverbanks","meaning":"受侵蝕的河岸","examples":[{"en":"Macaws eat clay from eroding riverbanks.","zh":"金剛鸚鵡從受侵蝕的河岸吃黏土。"},{"en":"Eroding riverbanks are river edges being worn away by water, rain, or wind.","zh":"受侵蝕的河岸是被水、雨或風逐漸磨蝕的河邊。"},{"en":"After heavy rain, eroding riverbanks may collapse into the river.","zh":"大雨後，受侵蝕的河岸可能倒塌入河。"},{"en":"Eroding riverbanks can expose clay that animals can reach and eat.","zh":"受侵蝕的河岸可以露出動物能接觸和食用的黏土。"},{"en":"The phrase describes a natural process changing the shape of a river edge.","zh":"這個短語描述改變河岸形狀的自然過程。"}],"source":"151 - Health in the Wild.pdf","sourcePage":8},{"front":"feed one group","meaning":"餵一組……","examples":[{"en":"Dr Gilardi fed one group of macaws a mixture of alkaloid and clay.","zh":"Gilardi 博士餵一組金剛鸚鵡食用生物鹼和黏土的混合物。"},{"en":"To feed one group something means to give that substance or food to one selected group in an experiment.","zh":"“Feed one group” 某物指在實驗中把該物質或食物給其中一個選定組別。"},{"en":"A scientist may feed one group of mice a normal diet and another group a high-fat diet.","zh":"科學家可能餵一組老鼠普通飲食，另一組高脂飲食。"},{"en":"If researchers feed one group a treatment, they can compare results with a control group.","zh":"如果研究人員餵一組某種治療物，他們可以與對照組比較結果。"},{"en":"The phrase is common in experimental descriptions.","zh":"這個短語常見於實驗描述。"}],"source":"151 - Health in the Wild.pdf","sourcePage":8},{"front":"a mixture of","meaning":"……的混合物","examples":[{"en":"One group was fed a mixture of harmless alkaloid and clay.","zh":"其中一組被餵食無害生物鹼和黏土的混合物。"},{"en":"A mixture of things is a combination of two or more substances or elements.","zh":"“A mixture of” 某些東西指兩種或以上物質或元素的組合。"},{"en":"Soup is often a mixture of vegetables, water, salt, and meat.","zh":"湯通常是蔬菜、水、鹽和肉的混合物。"},{"en":"If a mixture of medicine and food changes absorption, scientists need to study it.","zh":"如果藥物和食物的混合物改變吸收，科學家需要研究它。"},{"en":"The phrase describes things joined together.","zh":"這個短語描述被混合在一起的東西。"}],"source":"151 - Health in the Wild.pdf","sourcePage":8},{"front":"harmless alkaloid","meaning":"無害生物鹼","examples":[{"en":"The experiment used a harmless alkaloid.","zh":"實驗使用了一種無害生物鹼。"},{"en":"A harmless alkaloid is an alkaloid that does not damage the animals at the dose used.","zh":"無害生物鹼是指在所用劑量下不會傷害動物的生物鹼。"},{"en":"Scientists may choose a harmless alkaloid so an experiment is safer.","zh":"科學家可能選擇無害生物鹼，使實驗更安全。"},{"en":"If a harmless alkaloid is absorbed less after clay is eaten, clay may be binding to it.","zh":"如果進食黏土後無害生物鹼被吸收得較少，黏土可能正在與它結合。"},{"en":"The phrase contrasts with toxic alkaloids such as strychnine.","zh":"這個短語與士的寧等有毒生物鹼形成對比。"}],"source":"151 - Health in the Wild.pdf","sourcePage":8},{"front":"several hours later","meaning":"數小時後","examples":[{"en":"Several hours later, the birds’ blood was tested.","zh":"數小時後，這些鳥的血液被檢測。"},{"en":"Several hours later means after a few hours had passed.","zh":"“Several hours later” 指幾個小時過去之後。"},{"en":"Several hours later, the medicine began to reduce the patient’s fever.","zh":"數小時後，藥物開始降低病人的發燒。"},{"en":"If students drink coffee at night, several hours later they may still feel awake.","zh":"如果學生晚上喝咖啡，數小時後可能仍然清醒。"},{"en":"The phrase shows a short time delay between action and result.","zh":"這個短語顯示行動與結果之間有短時間延遲。"}],"source":"151 - Health in the Wild.pdf","sourcePage":8},{"front":"bloodstreams","meaning":"血液循環；血流","examples":[{"en":"The macaws that had eaten clay had less alkaloid in their bloodstreams.","zh":"吃了黏土的金剛鸚鵡血液循環中有較少生物鹼。"},{"en":"Bloodstreams are the flowing blood inside the bodies of animals or people.","zh":"血液循環是動物或人體內流動的血液。"},{"en":"Medicine enters the bloodstream before it reaches different parts of the body.","zh":"藥物進入血液循環後，才到達身體不同部位。"},{"en":"If less toxin enters the bloodstream, the animal may suffer fewer harmful effects.","zh":"如果較少毒素進入血液循環，動物可能受到較少有害影響。"},{"en":"The word is often used when discussing absorption and medicine.","zh":"這個詞常用於討論吸收和藥物。"}],"source":"151 - Health in the Wild.pdf","sourcePage":8},{"front":"suggesting that","meaning":"顯示；暗示","examples":[{"en":"The result suggested that the hypothesis was correct.","zh":"結果顯示該假說是正確的。"},{"en":"Suggesting that means pointing toward a likely explanation or conclusion.","zh":"“Suggesting that” 指指向一個可能的解釋或結論。"},{"en":"A falling fever is suggesting that the medicine may be working.","zh":"退燒顯示藥物可能正在發揮作用。"},{"en":"If fewer toxins appear in the blood, the data may be suggesting that clay has a protective effect.","zh":"如果血液中出現較少毒素，數據可能顯示黏土有保護作用。"},{"en":"The phrase is cautious because it does not always mean absolute proof.","zh":"這個短語較謹慎，因為它不一定表示絕對證明。"}],"source":"151 - Health in the Wild.pdf","sourcePage":8},{"front":"hypothesis","meaning":"假說","examples":[{"en":"The experiment supported the detoxification hypothesis.","zh":"該實驗支持了解毒假說。"},{"en":"A hypothesis is an idea that scientists test to see whether it is true.","zh":"假說是科學家測試是否屬實的一個想法。"},{"en":"A student’s hypothesis might be that plants grow faster with more sunlight.","zh":"學生的假說可能是植物在更多陽光下長得更快。"},{"en":"If an experiment supports a hypothesis, scientists may study it further.","zh":"如果實驗支持一個假說，科學家可能進一步研究它。"},{"en":"The word is common in science and means a testable explanation.","zh":"這個詞常見於科學，意思是可被測試的解釋。"}],"source":"151 - Health in the Wild.pdf","sourcePage":8},{"front":"observations","meaning":"觀察結果","examples":[{"en":"Other observations also support the idea.","zh":"其他觀察結果也支持這個想法。"},{"en":"Observations are things researchers notice, record, or measure while watching carefully.","zh":"觀察結果是研究人員仔細觀看時注意、記錄或量度到的事情。"},{"en":"A teacher’s observations can show which students need extra help.","zh":"老師的觀察結果可以顯示哪些學生需要額外幫助。"},{"en":"If repeated observations show the same pattern, the evidence becomes stronger.","zh":"如果反覆觀察結果顯示同一模式，證據會變得更強。"},{"en":"The word is useful in science, education, and daily problem-solving.","zh":"這個詞適用於科學、教育和日常解難。"}],"source":"151 - Health in the Wild.pdf","sourcePage":8},{"front":"support the idea that","meaning":"支持……的想法","examples":[{"en":"Other observations support the idea that clay is detoxifying.","zh":"其他觀察結果支持黏土有解毒作用的想法。"},{"en":"To support the idea that something is true means to provide evidence for that belief.","zh":"“Support the idea that” 某事為真指為該信念提供證據。"},{"en":"Falling accident rates support the idea that safety training works.","zh":"意外率下降支持安全培訓有效的想法。"},{"en":"If many animals eat clay after toxic food, this may support the idea that clay protects them.","zh":"如果許多動物在吃有毒食物後吃黏土，這可能支持黏土保護牠們的想法。"},{"en":"The phrase connects evidence with a claim.","zh":"這個短語把證據與主張連繫起來。"}],"source":"151 - Health in the Wild.pdf","sourcePage":8},{"front":"towards the tropics","meaning":"越接近熱帶地區","examples":[{"en":"Towards the tropics, plants contain more toxic compounds.","zh":"越接近熱帶地區，植物含有更多有毒化合物。"},{"en":"Towards the tropics means closer to the warm regions near the equator.","zh":"“Towards the tropics” 指越接近赤道附近的溫暖地區。"},{"en":"Towards the tropics, weather is generally warmer and many forests are denser.","zh":"越接近熱帶地區，天氣通常越暖，許多森林更茂密。"},{"en":"If plant toxins increase towards the tropics, herbivores there may need stronger defences.","zh":"如果植物毒素越接近熱帶地區越多，那裡的草食動物可能需要更強防禦。"},{"en":"The phrase describes a geographical direction and environmental change.","zh":"這個短語描述地理方向和環境變化。"}],"source":"151 - Health in the Wild.pdf","sourcePage":9},{"front":"toxic compounds","meaning":"有毒化合物","examples":[{"en":"The amount of toxic compounds in plants increases near the tropics.","zh":"植物中的有毒化合物含量在熱帶附近增加。"},{"en":"Toxic compounds are chemical substances that can harm living things.","zh":"有毒化合物是可以傷害生物的化學物質。"},{"en":"Some mushrooms contain toxic compounds that can damage the liver.","zh":"一些蘑菇含有會傷害肝臟的有毒化合物。"},{"en":"If animals eat plants with many toxic compounds, they may need ways to neutralise them.","zh":"如果動物吃含有許多有毒化合物的植物，牠們可能需要方法中和它們。"},{"en":"The phrase is more scientific than simply saying poisons.","zh":"這個短語比簡單說「毒物」更科學。"}],"source":"151 - Health in the Wild.pdf","sourcePage":9},{"front":"increase","meaning":"增加","examples":[{"en":"The amount of earth eaten by herbivores increases near the tropics.","zh":"草食動物吃泥土的量在熱帶附近增加。"},{"en":"To increase means to become larger in number, amount, or degree.","zh":"“Increase” 指在數量、份量或程度上變大。"},{"en":"Homework pressure may increase before exams.","zh":"考試前功課壓力可能增加。"},{"en":"If food prices increase, families may spend less on entertainment.","zh":"如果食物價格增加，家庭可能減少娛樂開支。"},{"en":"The word describes upward change.","zh":"這個詞描述向上的變化。"}],"source":"151 - Health in the Wild.pdf","sourcePage":9},{"front":"herbivores","meaning":"草食動物","examples":[{"en":"Herbivores eat more earth where plants contain more toxins.","zh":"在植物含有更多毒素的地方，草食動物吃更多泥土。"},{"en":"Herbivores are animals that mainly eat plants.","zh":"草食動物是主要吃植物的動物。"},{"en":"Cows, deer, rabbits, and elephants are herbivores.","zh":"牛、鹿、兔和大象都是草食動物。"},{"en":"If plants contain defensive poisons, herbivores may develop ways to avoid or detoxify them.","zh":"如果植物含有防禦性毒素，草食動物可能發展出避開或解毒的方法。"},{"en":"The word contrasts with carnivores, which eat meat.","zh":"這個詞與吃肉的肉食動物形成對比。"}],"source":"151 - Health in the Wild.pdf","sourcePage":9},{"front":"all year round","meaning":"全年","examples":[{"en":"Elephants lick clay from mud holes all year round.","zh":"大象全年從泥坑舔食黏土。"},{"en":"All year round means during every season of the year.","zh":"“All year round” 指一年四季都如此。"},{"en":"Some supermarkets sell fresh fruit all year round.","zh":"一些超市全年售賣新鮮水果。"},{"en":"If a clinic is open all year round, patients can get help even during holidays.","zh":"如果診所全年開放，病人即使在假期也能得到幫助。"},{"en":"The phrase shows that something is not limited to one season.","zh":"這個短語顯示某事不限於一個季節。"}],"source":"151 - Health in the Wild.pdf","sourcePage":9},{"front":"mud holes","meaning":"泥坑","examples":[{"en":"Elephants lick clay from mud holes.","zh":"大象從泥坑舔食黏土。"},{"en":"Mud holes are wet, muddy depressions in the ground where water and soil collect.","zh":"泥坑是地面上積聚水和泥土的潮濕凹陷處。"},{"en":"After rain, children may see mud holes along village roads.","zh":"下雨後，孩子可能在鄉村道路旁看見泥坑。"},{"en":"Animals may visit mud holes to drink, cool down, or lick clay.","zh":"動物可能到泥坑飲水、降溫或舔食黏土。"},{"en":"The phrase describes a simple natural feature.","zh":"這個短語描述一種簡單自然地貌。"}],"source":"151 - Health in the Wild.pdf","sourcePage":9},{"front":"binge on","meaning":"狂吃；大量進食","examples":[{"en":"Elephants do not lick clay when they are bingeing on fruit.","zh":"大象狂吃水果時不會舔食黏土。"},{"en":"To binge on something means to consume a large amount of it in a short time.","zh":"“Binge on” 某物指在短時間內大量食用它。"},{"en":"A student may binge on snacks while studying late at night.","zh":"學生深夜溫習時可能狂吃零食。"},{"en":"If animals binge on fruit, they may be getting plenty of safe food and need less clay.","zh":"如果動物大量進食水果，牠們可能正在獲得大量安全食物，較不需要黏土。"},{"en":"The phrase often suggests unusually heavy consumption.","zh":"這個短語常暗示異常大量攝取。"}],"source":"151 - Health in the Wild.pdf","sourcePage":9},{"front":"evolve to be eaten","meaning":"演化成可被食用","examples":[{"en":"Fruit has evolved to be eaten.","zh":"水果已演化成可被食用。"},{"en":"To evolve to be eaten means to develop features that attract animals to eat it and spread its seeds.","zh":"“Evolve to be eaten” 指發展出吸引動物食用並散播種子的特徵。"},{"en":"Sweet fruit may evolve to be eaten by birds and mammals.","zh":"甜水果可能演化成可被鳥類和哺乳動物食用。"},{"en":"If fruit evolves to be eaten, it may contain fewer defensive poisons than leaves.","zh":"如果水果演化成可被食用，它可能比葉子含有較少防禦性毒素。"},{"en":"The phrase explains a biological relationship between plants and animals.","zh":"這個短語解釋植物與動物之間的生物關係。"}],"source":"151 - Health in the Wild.pdf","sourcePage":9},{"front":"the addition of","meaning":"加入……","examples":[{"en":"The addition of clay to cattle diets increases nutrient absorption.","zh":"在牛的飲食中加入黏土會增加營養吸收。"},{"en":"The addition of something means adding it to what is already there.","zh":"“The addition of” 某物指把它加入已有的東西中。"},{"en":"The addition of more buses can reduce waiting times for passengers.","zh":"加入更多巴士可以減少乘客等候時間。"},{"en":"If the addition of clay improves digestion, farmers may consider using it carefully.","zh":"如果加入黏土能改善消化，農民可能會謹慎考慮使用它。"},{"en":"The phrase highlights a new element added to a system or mixture.","zh":"這個短語強調加入系統或混合物中的新元素。"}],"source":"151 - Health in the Wild.pdf","sourcePage":9},{"front":"domestic cattle","meaning":"家牛","examples":[{"en":"Clay can improve nutrient absorption in domestic cattle.","zh":"黏土可以改善家牛的營養吸收。"},{"en":"Domestic cattle are cows and bulls kept by people for farming, milk, meat, or work.","zh":"家牛是人類飼養用於農業、牛奶、肉類或工作的牛。"},{"en":"Domestic cattle need regular food, water, shelter, and veterinary care.","zh":"家牛需要定期食物、水、住所和獸醫照顧。"},{"en":"If domestic cattle absorb nutrients better, farmers may see healthier animals.","zh":"如果家牛更好吸收營養，農民可能看到更健康的動物。"},{"en":"The phrase contrasts farm animals with wild cattle-like animals.","zh":"這個短語與野生牛類動物形成對比。"}],"source":"151 - Health in the Wild.pdf","sourcePage":9},{"front":"nutrients","meaning":"營養素","examples":[{"en":"Clay helps cattle absorb more nutrients from food.","zh":"黏土幫助牛從食物中吸收更多營養素。"},{"en":"Nutrients are substances in food that the body needs for energy, growth, repair, and health.","zh":"營養素是食物中身體需要用於能量、生長、修復和健康的物質。"},{"en":"Vegetables provide nutrients such as vitamins, minerals, and fibre.","zh":"蔬菜提供維他命、礦物質和纖維等營養素。"},{"en":"If children do not get enough nutrients, they may become weak or sick.","zh":"如果孩子沒有獲得足夠營養素，可能變得虛弱或生病。"},{"en":"The word is central to discussions of diet and health.","zh":"這個詞是飲食和健康討論的核心。"}],"source":"151 - Health in the Wild.pdf","sourcePage":9},{"front":"absorb from","meaning":"從……吸收","examples":[{"en":"Cattle can absorb more nutrients from their food.","zh":"牛可以從食物中吸收更多營養素。"},{"en":"To absorb something from a source means to take it into the body or material from that source.","zh":"“Absorb something from” 某來源指從該來源把某物吸收到身體或材料中。"},{"en":"Plants absorb water from the soil through their roots.","zh":"植物透過根部從土壤中吸收水分。"},{"en":"If the body absorbs less iron from food, a person may feel tired.","zh":"如果身體從食物中吸收較少鐵質，人可能感到疲倦。"},{"en":"The phrase describes movement from one source into another system.","zh":"這個短語描述某物從來源進入另一個系統。"}],"source":"151 - Health in the Wild.pdf","sourcePage":10},{"front":"a third instance of","meaning":"……的第三個例子","examples":[{"en":"A third instance of animal self-medication involves leaves.","zh":"動物自我用藥的第三個例子涉及葉子。"},{"en":"A third instance of something means the third example or case of it.","zh":"“A third instance of” 某事指它的第三個例子或案例。"},{"en":"A third instance of lateness may lead to a warning at work.","zh":"第三次遲到可能會導致工作警告。"},{"en":"If scientists find a third instance of the same behaviour, the pattern becomes more convincing.","zh":"如果科學家找到同一行為的第三個例子，該模式會更有說服力。"},{"en":"The phrase helps organise examples in order.","zh":"這個短語有助按順序組織例子。"}],"source":"151 - Health in the Wild.pdf","sourcePage":10},{"front":"mechanical scours","meaning":"機械式清除物","examples":[{"en":"Some animals use mechanical scours to remove gut parasites.","zh":"一些動物使用機械式清除物來移除腸道寄生蟲。"},{"en":"Mechanical scours are rough physical materials that clean or scrape the gut rather than acting as chemical drugs.","zh":"機械式清除物是粗糙的物理材料，透過清理或刮擦腸道而非化學藥物發揮作用。"},{"en":"A rough leaf can work like a mechanical scour if it catches worms inside the intestine.","zh":"如果粗糙葉子在腸道中鈎住寄生蟲，它就可以像機械式清除物一樣作用。"},{"en":"If a treatment is mechanical rather than chemical, it works through physical action.","zh":"如果治療是機械式而非化學式，它透過物理作用運作。"},{"en":"The phrase describes cleaning by structure and movement.","zh":"這個短語描述透過結構和移動進行清除。"}],"source":"151 - Health in the Wild.pdf","sourcePage":10},{"front":"get rid of","meaning":"擺脫；除掉","examples":[{"en":"Chimpanzees use leaves to get rid of gut parasites.","zh":"黑猩猩使用葉子來擺脫腸道寄生蟲。"},{"en":"To get rid of something means to remove it or make it disappear.","zh":"“Get rid of” 某物指移除它或令它消失。"},{"en":"A family may get rid of old clothes by donating them.","zh":"家庭可能透過捐贈舊衣服來處理掉它們。"},{"en":"If medicine helps get rid of an infection, the patient feels better.","zh":"如果藥物幫助除掉感染，病人會感覺較好。"},{"en":"The phrase is common in daily speech and problem-solving.","zh":"這個短語常見於日常說話和解難。"}],"source":"151 - Health in the Wild.pdf","sourcePage":10},{"front":"researcher","meaning":"研究員","examples":[{"en":"Richard Wrangham was a researcher at the Gombe Stream Reserve.","zh":"Richard Wrangham 是岡貝溪保護區的研究員。"},{"en":"A researcher is a person who studies a topic carefully to discover new information.","zh":"研究員是仔細研究某個題目以發現新資料的人。"},{"en":"A medical researcher may test whether a treatment is safe and useful.","zh":"醫學研究員可能測試治療方法是否安全和有用。"},{"en":"If a researcher records behaviour accurately, later scientists can check the findings.","zh":"如果研究員準確記錄行為，後來的科學家可以檢查研究結果。"},{"en":"The word refers to someone who investigates questions systematically.","zh":"這個詞指有系統地調查問題的人。"}],"source":"151 - Health in the Wild.pdf","sourcePage":10},{"front":"Gombe Stream Reserve","meaning":"岡貝溪保護區","examples":[{"en":"Richard Wrangham worked at the Gombe Stream Reserve.","zh":"Richard Wrangham 在岡貝溪保護區工作。"},{"en":"Gombe Stream Reserve is a protected area where researchers have studied chimpanzees.","zh":"岡貝溪保護區是一個研究人員研究黑猩猩的受保護地區。"},{"en":"Scientists working at Gombe Stream Reserve may observe chimpanzees in natural forest conditions.","zh":"在岡貝溪保護區工作的科學家可能在自然森林環境中觀察黑猩猩。"},{"en":"A reserve protects wildlife so animals can live with less human disturbance.","zh":"保護區保護野生動物，使動物能在較少人類干擾下生活。"},{"en":"The phrase names a specific place linked to chimpanzee research.","zh":"這個短語指與黑猩猩研究有關的特定地方。"}],"source":"151 - Health in the Wild.pdf","sourcePage":10},{"front":"choose carefully","meaning":"小心選擇","examples":[{"en":"The chimps chose the leaves carefully.","zh":"黑猩猩小心選擇葉子。"},{"en":"To choose carefully means to select with attention and judgement, not randomly.","zh":"“Choose carefully” 指有注意力和判斷地選擇，而不是隨機選擇。"},{"en":"Students should choose carefully when selecting examples for an essay.","zh":"學生為作文選例子時應小心選擇。"},{"en":"If animals choose leaves carefully, the leaves may have a specific purpose.","zh":"如果動物小心選擇葉子，這些葉子可能有特定用途。"},{"en":"The phrase suggests deliberate selection.","zh":"這個短語暗示有意識的選擇。"}],"source":"151 - Health in the Wild.pdf","sourcePage":10},{"front":"test them in their mouths","meaning":"用口測試它們","examples":[{"en":"The chimps tested the leaves in their mouths.","zh":"黑猩猩用口測試這些葉子。"},{"en":"To test something in the mouth means to taste, feel, or check it before swallowing.","zh":"“Test something in the mouth” 指在吞下前品嚐、感受或檢查它。"},{"en":"A child may test hot soup in the mouth before taking a full spoonful.","zh":"孩子可能在喝一整匙熱湯前先用口測試一下。"},{"en":"If chimps test leaves in their mouths, they may be checking texture or taste.","zh":"如果黑猩猩用口測試葉子，牠們可能正在檢查質地或味道。"},{"en":"The phrase describes a cautious physical check before eating.","zh":"這個短語描述進食前謹慎的身體檢查。"}],"source":"151 - Health in the Wild.pdf","sourcePage":10},{"front":"fold it into","meaning":"將它摺成……","examples":[{"en":"A chimp would fold a leaf into a fan.","zh":"黑猩猩會將葉子摺成扇形。"},{"en":"To fold something into a shape means to bend it so it becomes that shape.","zh":"“Fold something into” 某形狀指把它彎摺成該形狀。"},{"en":"A student may fold paper into a small envelope.","zh":"學生可能將紙摺成一個小信封。"},{"en":"If a chimp folds a leaf into a fan, it may make the leaf easier to swallow whole.","zh":"如果黑猩猩把葉子摺成扇形，可能令整片葉子更容易吞下。"},{"en":"The phrase describes changing shape by bending.","zh":"這個短語描述透過彎摺改變形狀。"}],"source":"151 - Health in the Wild.pdf","sourcePage":10},{"front":"swallow it","meaning":"吞下它","examples":[{"en":"The chimp would fold the leaf and swallow it.","zh":"黑猩猩會把葉子摺好並吞下它。"},{"en":"To swallow it means to move it from the mouth down into the stomach.","zh":"“Swallow it” 指把它從口中送入胃部。"},{"en":"A child should chew food properly before swallowing it.","zh":"孩子吞下食物前應好好咀嚼。"},{"en":"If an animal swallows a rough leaf whole, the leaf may pass through the gut unchanged.","zh":"如果動物整片吞下粗糙葉子，葉子可能不變地通過腸道。"},{"en":"The phrase describes the final action of taking something into the body.","zh":"這個短語描述把某物帶入身體的最後動作。"}],"source":"151 - Health in the Wild.pdf","sourcePage":10},{"front":"wrinkle one’s nose","meaning":"皺鼻","examples":[{"en":"Some chimps wrinkled their noses as they swallowed the leaves.","zh":"一些黑猩猩吞葉子時皺鼻。"},{"en":"To wrinkle one’s nose means to tighten the nose, often because something smells or tastes unpleasant.","zh":"“Wrinkle one’s nose” 指皺起鼻子，通常因某物聞起來或嚐起來不愉快。"},{"en":"A child may wrinkle his nose after tasting bitter medicine.","zh":"孩子嚐到苦藥後可能皺鼻。"},{"en":"If chimps wrinkle their noses while eating leaves, the leaves may taste unpleasant.","zh":"如果黑猩猩吃葉子時皺鼻，葉子可能味道不好。"},{"en":"The phrase describes a facial reaction to dislike or discomfort.","zh":"這個短語描述對厭惡或不適的面部反應。"}],"source":"151 - Health in the Wild.pdf","sourcePage":10},{"front":"suggesting the experience was unpleasant","meaning":"顯示該經歷令人不快","examples":[{"en":"Their reaction suggested that the experience was unpleasant.","zh":"牠們的反應顯示該經歷令人不快。"},{"en":"Suggesting the experience was unpleasant means showing signs that the action felt bad or uncomfortable.","zh":"“Suggesting the experience was unpleasant” 指顯示某行動感覺不好或不舒服的跡象。"},{"en":"A child’s grimace after medicine may suggest the experience was unpleasant.","zh":"孩子服藥後扮苦相，可能顯示該經歷令人不快。"},{"en":"If animals wrinkle their noses while swallowing leaves, it may suggest the experience was unpleasant.","zh":"如果動物吞葉子時皺鼻，可能顯示該經歷令人不快。"},{"en":"The phrase uses behaviour as evidence of feeling.","zh":"這個短語用行為作為感受的證據。"}],"source":"151 - Health in the Wild.pdf","sourcePage":11},{"front":"undigested leaves","meaning":"未消化的葉子","examples":[{"en":"Undigested leaves were later found on the forest floor.","zh":"後來在森林地面發現未消化的葉子。"},{"en":"Undigested leaves are leaves that pass through the body without being broken down by digestion.","zh":"未消化的葉子是通過身體但沒有被消化分解的葉子。"},{"en":"If undigested leaves appear in droppings, the animal may not have eaten them for nutrition.","zh":"如果糞便中出現未消化的葉子，動物可能不是為了營養而吃它們。"},{"en":"Undigested leaves can show researchers what happened inside the gut.","zh":"未消化的葉子可以向研究人員顯示腸道內發生了甚麼。"},{"en":"The phrase describes food that remains almost unchanged after passing through the body.","zh":"這個短語描述通過身體後幾乎保持不變的食物。"}],"source":"151 - Health in the Wild.pdf","sourcePage":11},{"front":"forest floor","meaning":"森林地面","examples":[{"en":"Researchers found undigested leaves on the forest floor.","zh":"研究人員在森林地面發現未消化的葉子。"},{"en":"The forest floor is the ground layer of a forest, covered with soil, fallen leaves, branches, and small plants.","zh":"森林地面是森林的地面層，覆蓋着泥土、落葉、樹枝和小植物。"},{"en":"Insects, fungi, and seeds often live on the forest floor.","zh":"昆蟲、真菌和種子常生活在森林地面。"},{"en":"If researchers search the forest floor, they may find clues about animal feeding.","zh":"如果研究人員搜尋森林地面，他們可能找到動物進食的線索。"},{"en":"The phrase describes the lowest natural layer of a forest.","zh":"這個短語描述森林最底層的自然層面。"}],"source":"151 - Health in the Wild.pdf","sourcePage":11},{"front":"rightly guessed that","meaning":"正確猜到","examples":[{"en":"Dr Wrangham rightly guessed that the leaves had a medicinal purpose.","zh":"Wrangham 博士正確猜到這些葉子有醫療用途。"},{"en":"To rightly guess that something is true means to make a correct guess based on clues.","zh":"“Rightly guessed that” 某事為真指根據線索作出正確猜測。"},{"en":"The teacher rightly guessed that the student was confused by the instructions.","zh":"老師正確猜到學生被指示弄糊塗了。"},{"en":"If researchers rightly guessed that the leaves were medicinal, later evidence should support the idea.","zh":"如果研究人員正確猜到葉子有醫療作用，後來的證據應支持這個想法。"},{"en":"The phrase shows that a guess turned out to be correct.","zh":"這個短語顯示一個猜測結果正確。"}],"source":"151 - Health in the Wild.pdf","sourcePage":11},{"front":"medicinal purpose","meaning":"醫療用途","examples":[{"en":"The leaves had a medicinal purpose.","zh":"這些葉子有醫療用途。"},{"en":"A medicinal purpose is a use related to treating illness, pain, or parasites.","zh":"醫療用途是與治療疾病、痛楚或寄生蟲有關的用途。"},{"en":"Ginger tea may have a medicinal purpose when people drink it for stomach discomfort.","zh":"當人們因胃部不適而喝薑茶，它可能有醫療用途。"},{"en":"If an animal eats a plant only when sick, the plant may have a medicinal purpose.","zh":"如果動物只在生病時吃某植物，該植物可能有醫療用途。"},{"en":"The phrase focuses on health use rather than ordinary food use.","zh":"這個短語強調健康用途，而不是普通食物用途。"}],"source":"151 - Health in the Wild.pdf","sourcePage":11},{"front":"interpretation of","meaning":"對……的解釋","examples":[{"en":"This was an early interpretation of behaviour as self-medication.","zh":"這是早期把行為解釋為自我用藥的說法。"},{"en":"An interpretation of something is a way of explaining what it means.","zh":"“Interpretation of” 某事指對其意義的一種解釋。"},{"en":"A teacher’s interpretation of a poem may differ from a student’s view.","zh":"老師對詩的解釋可能不同於學生的看法。"},{"en":"If new facts appear, researchers may change their interpretation of an animal behaviour.","zh":"如果新事實出現，研究人員可能改變對動物行為的解釋。"},{"en":"The phrase shows how people understand evidence or actions.","zh":"這個短語顯示人們如何理解證據或行動。"}],"source":"151 - Health in the Wild.pdf","sourcePage":11},{"front":"behaviour pattern","meaning":"行為模式","examples":[{"en":"The leaf-swallowing was interpreted as a behaviour pattern.","zh":"吞葉行為被解釋為一種行為模式。"},{"en":"A behaviour pattern is a repeated way of acting that can be observed and studied.","zh":"行為模式是可以被觀察和研究的重複行動方式。"},{"en":"A child’s behaviour pattern may change when school pressure increases.","zh":"當學業壓力增加，孩子的行為模式可能改變。"},{"en":"If many chimps swallow leaves in the same way, scientists may identify a behaviour pattern.","zh":"如果許多黑猩猩以相同方式吞葉，科學家可能辨認出一種行為模式。"},{"en":"The phrase describes repeated action, not one random event.","zh":"這個短語描述重複行動，而不是一次隨機事件。"}],"source":"151 - Health in the Wild.pdf","sourcePage":11},{"front":"however","meaning":"然而","examples":[{"en":"However, he guessed wrong about the mechanism.","zh":"然而，他猜錯了背後機制。"},{"en":"However introduces a contrast with what was just said.","zh":"“However” 用來引出與剛才內容相反或形成對比的意思。"},{"en":"The plan was cheap; however, it was difficult to carry out.","zh":"這個計劃便宜；然而，它很難執行。"},{"en":"A student may understand the topic; however, poor grammar can still lower the score.","zh":"學生可能理解題目；然而，文法差仍可能拉低分數。"},{"en":"The word helps connect two opposing ideas.","zh":"這個詞有助連接兩個相反想法。"}],"source":"151 - Health in the Wild.pdf","sourcePage":11},{"front":"mechanism","meaning":"機制","examples":[{"en":"He guessed wrong about the mechanism behind the behaviour.","zh":"他猜錯了該行為背後的機制。"},{"en":"A mechanism is the process or method by which something works.","zh":"機制是某事運作的過程或方法。"},{"en":"The mechanism of a lock explains how the key opens it.","zh":"鎖的機制解釋鑰匙如何打開它。"},{"en":"If scientists know the mechanism behind a treatment, they can explain why it works.","zh":"如果科學家知道治療背後的機制，他們就能解釋它為何有效。"},{"en":"The word is useful for asking how a result is produced.","zh":"這個詞適合用來詢問結果如何產生。"}],"source":"151 - Health in the Wild.pdf","sourcePage":11},{"front":"assumption","meaning":"假設","examples":[{"en":"The assumption was that Aspilia contained a drug.","zh":"假設是 Aspilia 含有藥物成分。"},{"en":"An assumption is something people believe is true without full proof.","zh":"假設是人們在沒有完整證據下相信為真的事情。"},{"en":"A teacher should not make the assumption that every student has internet access at home.","zh":"老師不應假設每個學生家中都有互聯網。"},{"en":"If an assumption is wrong, the research direction may also be wrong.","zh":"如果假設錯誤，研究方向也可能錯誤。"},{"en":"The word warns that a belief may need checking.","zh":"這個詞提醒我們某個信念可能需要查證。"}],"source":"151 - Health in the Wild.pdf","sourcePage":11},{"front":"contain a drug","meaning":"含有藥物成分","examples":[{"en":"Researchers assumed that Aspilia contained a drug.","zh":"研究人員假設 Aspilia 含有藥物成分。"},{"en":"To contain a drug means to have a chemical substance that can affect the body medically.","zh":"“Contain a drug” 指含有能對身體產生醫療作用的化學物質。"},{"en":"Some plants contain a drug that can reduce pain or swelling.","zh":"一些植物含有能減少痛楚或腫脹的藥物成分。"},{"en":"If a leaf contains a drug, eating it may have a chemical effect on the animal.","zh":"如果葉子含有藥物成分，吃下它可能對動物產生化學作用。"},{"en":"The phrase describes a substance inside a plant or product.","zh":"這個短語描述植物或產品內含有某種物質。"}],"source":"151 - Health in the Wild.pdf","sourcePage":11},{"front":"spark research","meaning":"引發研究","examples":[{"en":"This assumption sparked decades of research.","zh":"這個假設引發了數十年的研究。"},{"en":"To spark research means to cause researchers to begin studying a question.","zh":"“Spark research” 指促使研究人員開始研究某個問題。"},{"en":"A strange animal behaviour can spark research into its possible survival value.","zh":"奇怪的動物行為可以引發對其可能生存價值的研究。"},{"en":"If one experiment raises new questions, it may spark research for many years.","zh":"如果一項實驗提出新問題，它可能引發多年的研究。"},{"en":"The phrase suggests that one idea starts a larger investigation.","zh":"這個短語暗示一個想法啟動更大型調查。"}],"source":"151 - Health in the Wild.pdf","sourcePage":12},{"front":"more than two decades of","meaning":"超過二十年的……","examples":[{"en":"The assumption sparked more than two decades of phytochemical research.","zh":"這個假設引發了超過二十年的植物化學研究。"},{"en":"More than two decades of something means over twenty years of it.","zh":"“More than two decades of” 某事指超過二十年的某事。"},{"en":"The school has more than two decades of experience teaching adults.","zh":"這間學校有超過二十年的成人教學經驗。"},{"en":"More than two decades of research can produce many papers and debates.","zh":"超過二十年的研究可以產生許多論文和辯論。"},{"en":"The phrase highlights a long period of time.","zh":"這個短語強調一段很長時間。"}],"source":"151 - Health in the Wild.pdf","sourcePage":12},{"front":"phytochemical research","meaning":"植物化學研究","examples":[{"en":"Scientists carried out phytochemical research on Aspilia.","zh":"科學家對 Aspilia 進行植物化學研究。"},{"en":"Phytochemical research studies the chemicals found in plants.","zh":"植物化學研究是研究植物中化學物質的研究。"},{"en":"Phytochemical research may discover substances useful for medicine or agriculture.","zh":"植物化學研究可能發現對醫藥或農業有用的物質。"},{"en":"If animals eat a plant unusually, phytochemical research can test what chemicals it contains.","zh":"如果動物異常地吃某種植物，植物化學研究可以測試它含有甚麼化學物質。"},{"en":"The phrase combines plant science with chemistry.","zh":"這個短語結合植物科學和化學。"}],"source":"151 - Health in the Wild.pdf","sourcePage":12},{"front":"find out","meaning":"找出","examples":[{"en":"Researchers tried to find out what chemical the chimps wanted.","zh":"研究人員試圖找出黑猩猩想要的是哪種化學物質。"},{"en":"To find out means to discover information by checking, asking, or investigating.","zh":"“Find out” 指透過檢查、詢問或調查發現資料。"},{"en":"Students can find out the meaning of a word by looking at examples.","zh":"學生可以透過看例句找出單詞意思。"},{"en":"If doctors cannot find out the cause of pain, they may order more tests.","zh":"如果醫生無法找出痛楚原因，可能安排更多檢查。"},{"en":"The phrase is common and means to learn something unknown.","zh":"這個短語很常用，意思是了解未知事情。"}],"source":"151 - Health in the Wild.pdf","sourcePage":12},{"front":"what chemical the chimps were after","meaning":"黑猩猩想要的是哪種化學物質","examples":[{"en":"Researchers wanted to know what chemical the chimps were after.","zh":"研究人員想知道黑猩猩想要的是哪種化學物質。"},{"en":"What chemical the chimps were after means which chemical the chimpanzees seemed to be seeking.","zh":"“What chemical the chimps were after” 指黑猩猩似乎正在尋找哪種化學物質。"},{"en":"Scientists may ask what chemical bees are after when they visit certain flowers.","zh":"當蜜蜂拜訪某些花時，科學家可能會問牠們想要的是哪種化學物質。"},{"en":"If chimps keep choosing the same plant, researchers may wonder what chemical they are after.","zh":"如果黑猩猩不斷選擇同一種植物，研究人員可能想知道牠們想要的是哪種化學物質。"},{"en":"The phrase uses “be after” to mean “be seeking”.","zh":"這個短語中的 “be after” 解作「尋找」。"}],"source":"151 - Health in the Wild.pdf","sourcePage":12},{"front":"across Africa","meaning":"遍及非洲","examples":[{"en":"Chimps across Africa were seen swallowing many species of leaves.","zh":"遍及非洲的黑猩猩被看見吞下許多種葉子。"},{"en":"Across Africa means in many different parts of Africa.","zh":"“Across Africa” 指在非洲許多不同地方。"},{"en":"Researchers across Africa may study different climates, animals, and communities.","zh":"遍及非洲的研究人員可能研究不同氣候、動物和社區。"},{"en":"If the same behaviour appears across Africa, it may not be a local accident.","zh":"如果同一行為遍及非洲出現，它可能不是本地偶然事件。"},{"en":"The phrase shows wide geographical spread.","zh":"這個短語顯示廣泛地理分布。"}],"source":"151 - Health in the Wild.pdf","sourcePage":12},{"front":"in common","meaning":"共同擁有","examples":[{"en":"The leaves seemed to have few suitable chemicals in common.","zh":"這些葉子似乎共同擁有很少合適化學物質。"},{"en":"If things have something in common, they share the same feature.","zh":"如果事物 “have something in common”，它們共同擁有同一特徵。"},{"en":"Two students may have music and football in common.","zh":"兩名學生可能共同喜歡音樂和足球。"},{"en":"If many medicinal leaves have no chemicals in common, the explanation may not be chemical.","zh":"如果許多藥用葉子沒有共同化學物質，解釋可能不是化學性的。"},{"en":"The phrase is useful for comparing similarities.","zh":"這個短語適合用來比較相似之處。"}],"source":"151 - Health in the Wild.pdf","sourcePage":12},{"front":"drug hypothesis","meaning":"藥物假說","examples":[{"en":"The drug hypothesis began to look dubious.","zh":"藥物假說開始看起來可疑。"},{"en":"The drug hypothesis is the idea that the leaves worked because they contained a medicinal chemical.","zh":"藥物假說是指葉子因含有藥用化學物質而有效這個想法。"},{"en":"Scientists tested the drug hypothesis by looking for useful chemicals in the leaves.","zh":"科學家透過尋找葉子中的有用化學物質來測試藥物假說。"},{"en":"If many leaves have no common drug, the drug hypothesis becomes weaker.","zh":"如果許多葉子沒有共同藥物成分，藥物假說會變弱。"},{"en":"The phrase names a specific explanation for the behaviour.","zh":"這個短語指對該行為的一種特定解釋。"}],"source":"151 - Health in the Wild.pdf","sourcePage":12},{"front":"more and more dubious","meaning":"越來越可疑","examples":[{"en":"The drug hypothesis was looking more and more dubious.","zh":"藥物假說看起來越來越可疑。"},{"en":"More and more dubious means increasingly doubtful or less believable over time.","zh":"“More and more dubious” 指隨時間越來越令人懷疑或越不可信。"},{"en":"His excuse became more and more dubious when the details kept changing.","zh":"當細節不斷改變時，他的藉口變得越來越可疑。"},{"en":"If repeated tests fail, a scientific idea may look more and more dubious.","zh":"如果反覆測試失敗，一個科學想法可能看起來越來越可疑。"},{"en":"The phrase shows growing doubt.","zh":"這個短語顯示懷疑正在增加。"}],"source":"151 - Health in the Wild.pdf","sourcePage":12},{"front":"get to the bottom of","meaning":"查明真相","examples":[{"en":"Dr Huffman got to the bottom of the problem.","zh":"Huffman 博士查明了問題真相。"},{"en":"To get to the bottom of a problem means to discover the real cause or truth.","zh":"“Get to the bottom of” 問題指找出真正原因或真相。"},{"en":"A teacher may get to the bottom of poor homework by asking about sleep and family stress.","zh":"老師可能透過詢問睡眠和家庭壓力來查明功課差的真相。"},{"en":"If doctors get to the bottom of a symptom, they can choose better treatment.","zh":"如果醫生查明症狀真相，就能選擇更好治療。"},{"en":"The phrase means going beyond surface explanations.","zh":"這個短語指超越表面解釋。"}],"source":"151 - Health in the Wild.pdf","sourcePage":12},{"front":"do so by","meaning":"透過……做到","examples":[{"en":"He did so by watching what came out of the chimps.","zh":"他透過觀察黑猩猩排出的東西做到這一點。"},{"en":"Do so by means to achieve that result through a particular method.","zh":"“Do so by” 指透過某種方法達到該結果。"},{"en":"A student can improve writing by reading good examples and copying useful structures.","zh":"學生可以透過閱讀好例句並模仿有用結構來改善寫作。"},{"en":"Researchers may solve a mystery by changing what they observe.","zh":"研究人員可能透過改變觀察對象來解開謎團。"},{"en":"The phrase links an action with the method used to complete it.","zh":"這個短語把行動與完成它的方法連繫起來。"}],"source":"151 - Health in the Wild.pdf","sourcePage":12},{"front":"what came out of","meaning":"從……排出的東西","examples":[{"en":"He studied what came out of the chimps.","zh":"他研究從黑猩猩排出的東西。"},{"en":"What came out of an animal means what passed out of its body, often in droppings.","zh":"“What came out of” 動物指從其身體排出的東西，通常指糞便中的東西。"},{"en":"A vet may examine what came out of a sick dog to check for parasites.","zh":"獸醫可能檢查從病犬排出的東西，以查看是否有寄生蟲。"},{"en":"If leaves come out undigested, they may have worked mechanically rather than chemically.","zh":"如果葉子未消化地排出，它們可能是機械式而非化學式發揮作用。"},{"en":"The phrase is informal but clear in a biological context.","zh":"這個短語在生物語境中較口語但清楚。"}],"source":"151 - Health in the Wild.pdf","sourcePage":13},{"front":"rather than","meaning":"而不是","examples":[{"en":"He watched what came out rather than what went in.","zh":"他觀察排出的東西，而不是進入體內的東西。"},{"en":"Rather than means instead of, and it shows a clear contrast between two choices.","zh":"“Rather than” 解作「而不是」，顯示兩個選擇之間的清楚對比。"},{"en":"Students should understand examples rather than memorise words blindly.","zh":"學生應理解例句，而不是盲目背單詞。"},{"en":"If researchers study results rather than assumptions, they may find a better answer.","zh":"如果研究人員研究結果而不是假設，可能找到更好答案。"},{"en":"The phrase separates one choice from another.","zh":"這個短語把一個選擇與另一個分開。"}],"source":"151 - Health in the Wild.pdf","sourcePage":13},{"front":"concentrate on","meaning":"集中於","examples":[{"en":"He concentrated on the egested leaves.","zh":"他集中於排出的葉子。"},{"en":"To concentrate on something means to give most attention to it.","zh":"“Concentrate on” 某事指把大部分注意力放在它上面。"},{"en":"Students should concentrate on the question before choosing an answer.","zh":"學生在選答案前應集中於題目。"},{"en":"If scientists concentrate on the wrong evidence, they may miss the real mechanism.","zh":"如果科學家集中於錯誤證據，他們可能錯過真正機制。"},{"en":"The phrase is useful for study, work, and research.","zh":"這個短語適用於學習、工作和研究。"}],"source":"151 - Health in the Wild.pdf","sourcePage":13},{"front":"what went in","meaning":"進入體內的東西","examples":[{"en":"Earlier researchers concentrated on what went into the chimps.","zh":"早期研究人員集中於進入黑猩猩體內的東西。"},{"en":"What went in means what entered the body, system, or process.","zh":"“What went in” 指進入身體、系統或過程的東西。"},{"en":"A nutritionist may check what went into a patient’s diet during the week.","zh":"營養師可能檢查病人一星期飲食中進入身體的東西。"},{"en":"If researchers only study what went in, they may miss what happened after digestion.","zh":"如果研究人員只研究進入體內的東西，可能錯過消化後發生的事。"},{"en":"The phrase contrasts input with output.","zh":"這個短語把輸入與輸出作對比。"}],"source":"151 - Health in the Wild.pdf","sourcePage":13},{"front":"egested leaves","meaning":"排出的葉子","examples":[{"en":"The egested leaves were full of intestinal worms.","zh":"排出的葉子充滿腸道寄生蟲。"},{"en":"Egested leaves are leaves that have been passed out of the body after being swallowed.","zh":"排出的葉子是被吞下後從身體排出的葉子。"},{"en":"Researchers examined egested leaves to understand what happened inside the chimps.","zh":"研究人員檢查排出的葉子，以理解黑猩猩體內發生了甚麼。"},{"en":"If egested leaves carry worms, they may have removed parasites physically.","zh":"如果排出的葉子帶有寄生蟲，它們可能以物理方式移除了寄生蟲。"},{"en":"The word is scientific and means expelled from the body.","zh":"這個詞較科學，意思是從身體排出。"}],"source":"151 - Health in the Wild.pdf","sourcePage":13},{"front":"be full of","meaning":"充滿","examples":[{"en":"The egested leaves were full of intestinal worms.","zh":"排出的葉子充滿腸道寄生蟲。"},{"en":"To be full of something means to contain a large amount of it.","zh":"“Be full of” 某物指含有大量該物。"},{"en":"The classroom was full of noise before the teacher arrived.","zh":"老師到達前，課室充滿噪音。"},{"en":"If leaves are full of worms after passing through the gut, they may have caught the worms inside.","zh":"如果葉子通過腸道後充滿蟲，牠們可能在體內鈎住了蟲。"},{"en":"The phrase can describe physical contents or a general feeling.","zh":"這個短語可以描述實際內容，也可以描述整體感覺。"}],"source":"151 - Health in the Wild.pdf","sourcePage":13},{"front":"factor common to","meaning":"……共同的因素","examples":[{"en":"The factor common to all the leaves was microscopic hooks.","zh":"所有葉子共同的因素是微小鈎狀物。"},{"en":"A factor common to several things is a feature they all share.","zh":"“A factor common to” 幾件事物指它們共同擁有的特徵。"},{"en":"The factor common to successful students may be regular practice.","zh":"成功學生共同的因素可能是定期練習。"},{"en":"If the factor common to medicinal leaves is texture, the mechanism may be physical.","zh":"如果藥用葉子共同的因素是質地，機制可能是物理性的。"},{"en":"The phrase helps identify the shared cause or feature.","zh":"這個短語有助辨認共同原因或特徵。"}],"source":"151 - Health in the Wild.pdf","sourcePage":13},{"front":"microscopic hooks","meaning":"微小鈎狀物","examples":[{"en":"The leaves were covered with microscopic hooks.","zh":"這些葉子覆蓋着微小鈎狀物。"},{"en":"Microscopic hooks are tiny hook-like structures too small to see clearly without a microscope.","zh":"微小鈎狀物是太細小、沒有顯微鏡便難以清楚看見的鈎形結構。"},{"en":"A leaf with microscopic hooks may feel rough even if it looks smooth.","zh":"有微小鈎狀物的葉子即使看起來平滑，也可能摸起來粗糙。"},{"en":"If microscopic hooks catch worms, they can help remove parasites from the gut.","zh":"如果微小鈎狀物鈎住蟲，就能幫助從腸道移除寄生蟲。"},{"en":"The phrase describes very small physical structures.","zh":"這個短語描述非常細小的物理結構。"}],"source":"151 - Health in the Wild.pdf","sourcePage":13},{"front":"be covered with","meaning":"覆蓋着","examples":[{"en":"The leaves were covered with microscopic hooks.","zh":"這些葉子覆蓋着微小鈎狀物。"},{"en":"To be covered with something means to have that thing over the surface.","zh":"“Be covered with” 某物指表面有該物覆蓋。"},{"en":"After the storm, the road was covered with fallen branches.","zh":"暴風雨後，道路覆蓋着倒下的樹枝。"},{"en":"If a leaf is covered with tiny hooks, it may catch worms as it moves through the gut.","zh":"如果葉子覆蓋着微小鈎狀物，它通過腸道時可能鈎住蟲。"},{"en":"The phrase describes what is spread across a surface.","zh":"這個短語描述某物散布在表面上。"}],"source":"151 - Health in the Wild.pdf","sourcePage":13},{"front":"catch the worms","meaning":"鈎住蟲","examples":[{"en":"The hooks caught the worms.","zh":"這些鈎狀物鈎住蟲。"},{"en":"To catch the worms means to trap or hold the worms so they cannot stay where they were.","zh":"“Catch the worms” 指困住或抓住蟲，使牠們不能留在原位。"},{"en":"A rough brush can catch hair in the same way hooks catch worms.","zh":"粗糙刷子可以像鈎狀物鈎住蟲一樣鈎住頭髮。"},{"en":"If the hooks catch the worms, the worms may be carried out of the intestine.","zh":"如果鈎狀物鈎住蟲，蟲可能被帶出腸道。"},{"en":"The phrase describes a physical trapping action.","zh":"這個短語描述物理捕捉動作。"}],"source":"151 - Health in the Wild.pdf","sourcePage":13},{"front":"drag them from their lodgings","meaning":"將牠們從寄居處拖出來","examples":[{"en":"The hooks dragged the worms from their lodgings.","zh":"這些鈎狀物將蟲從寄居處拖出來。"},{"en":"To drag them from their lodgings means to pull the worms away from the places where they were attached or living.","zh":"“Drag them from their lodgings” 指把蟲從牠們附着或生活的地方拉走。"},{"en":"A comb can drag dirt from thick hair if its teeth catch the particles.","zh":"如果梳齒鈎住污垢，梳子可以把污垢從濃密頭髮中拖出來。"},{"en":"If leaf hooks drag worms from their lodgings, the worms can be expelled with the leaves.","zh":"如果葉子上的鈎狀物將蟲從寄居處拖出來，蟲就可以隨葉子排出。"},{"en":"The phrase gives a vivid picture of parasites being physically removed.","zh":"這個短語生動描繪寄生蟲被物理移除。"}],"source":"151 - Health in the Wild.pdf","sourcePage":13},{"front":"following that observation","meaning":"在該觀察之後","examples":[{"en":"Following that observation, Dr Engel became interested in livestock health.","zh":"在該觀察之後，Engel 博士開始對牲畜健康感興趣。"},{"en":"Following that observation means after seeing or learning that particular finding.","zh":"“Following that observation” 指在看見或得知該特定發現之後。"},{"en":"Following that observation, the teacher changed the lesson plan.","zh":"在該觀察之後，老師改變了課堂計劃。"},{"en":"If scientists notice an unexpected pattern, following that observation they may begin a new study.","zh":"如果科學家注意到意外模式，在該觀察之後，他們可能開始新研究。"},{"en":"The phrase connects one discovery with the next action.","zh":"這個短語把一項發現與下一步行動連繫起來。"}],"source":"151 - Health in the Wild.pdf","sourcePage":14},{"front":"be particularly excited about","meaning":"對……特別感到興奮","examples":[{"en":"Dr Engel is particularly excited about possible applications.","zh":"Engel 博士對可能的應用特別感到興奮。"},{"en":"To be particularly excited about something means to feel especially interested and hopeful about it.","zh":"“Be particularly excited about” 某事指對它特別感興趣並抱有希望。"},{"en":"Students may be particularly excited about a field trip after months of classroom lessons.","zh":"經過數月課堂學習後，學生可能對實地考察特別感到興奮。"},{"en":"If research can help real farmers, scientists may be particularly excited about it.","zh":"如果研究能幫助真正農民，科學家可能對此特別感到興奮。"},{"en":"The phrase shows stronger enthusiasm than ordinary interest.","zh":"這個短語顯示比普通興趣更強的熱情。"}],"source":"151 - Health in the Wild.pdf","sourcePage":14},{"front":"knowledge of","meaning":"關於……的知識","examples":[{"en":"Knowledge of animal self-care could help livestock.","zh":"關於動物自我照顧的知識可以幫助牲畜。"},{"en":"Knowledge of something means understanding or information about it.","zh":"“Knowledge of” 某事指關於它的理解或資料。"},{"en":"Knowledge of first aid can help people respond quickly during accidents.","zh":"關於急救的知識可以幫助人們在意外中迅速反應。"},{"en":"If farmers gain knowledge of animal self-care, they may improve livestock health.","zh":"如果農民獲得關於動物自我照顧的知識，他們可能改善牲畜健康。"},{"en":"The phrase connects understanding with practical use.","zh":"這個短語把理解與實際用途連繫起來。"}],"source":"151 - Health in the Wild.pdf","sourcePage":14},{"front":"look after themselves","meaning":"照顧自己","examples":[{"en":"Animals may know how to look after themselves.","zh":"動物可能知道如何照顧自己。"},{"en":"To look after themselves means to take care of their own health, safety, or needs.","zh":"“Look after themselves” 指照顧自己的健康、安全或需要。"},{"en":"Children gradually learn to look after themselves by eating properly and keeping clean.","zh":"孩子透過好好飲食和保持清潔，逐漸學會照顧自己。"},{"en":"If animals can look after themselves, farmers may learn from their natural choices.","zh":"如果動物能照顧自己，農民可能從牠們的自然選擇中學習。"},{"en":"The phrase means self-care in a practical sense.","zh":"這個短語指實際意義上的自我照顧。"}],"source":"151 - Health in the Wild.pdf","sourcePage":14},{"front":"be used to improve","meaning":"被用來改善","examples":[{"en":"This knowledge could be used to improve livestock health.","zh":"這些知識可以被用來改善牲畜健康。"},{"en":"To be used to improve something means to be applied in order to make it better.","zh":"“Be used to improve” 某事指被應用來使其變得更好。"},{"en":"Exam results can be used to improve teaching plans.","zh":"考試結果可以被用來改善教學計劃。"},{"en":"If animal self-medication research is used to improve farming, livestock may become healthier.","zh":"如果動物自我用藥研究被用來改善農業，牲畜可能變得更健康。"},{"en":"The phrase connects knowledge or tools with practical improvement.","zh":"這個短語把知識或工具與實際改善連繫起來。"}],"source":"151 - Health in the Wild.pdf","sourcePage":14},{"front":"livestock","meaning":"牲畜","examples":[{"en":"Animal self-medication may help improve livestock health.","zh":"動物自我用藥可能有助改善牲畜健康。"},{"en":"Livestock are farm animals kept for food, milk, wool, labour, or other products.","zh":"牲畜是為食物、牛奶、羊毛、勞力或其他產品而飼養的農場動物。"},{"en":"Cattle, sheep, goats, pigs, and chickens can be livestock.","zh":"牛、羊、山羊、豬和雞都可以是牲畜。"},{"en":"If livestock become sick, farmers may lose income and food supply may fall.","zh":"如果牲畜生病，農民可能失去收入，食物供應也可能下降。"},{"en":"The word refers to animals raised in agriculture.","zh":"這個詞指農業中飼養的動物。"}],"source":"151 - Health in the Wild.pdf","sourcePage":14},{"front":"learn a thing or two","meaning":"學到一兩件事","examples":[{"en":"People might also be able to learn a thing or two.","zh":"人類也可能學到一兩件事。"},{"en":"To learn a thing or two means to learn some useful ideas or lessons.","zh":"“Learn a thing or two” 指學到一些有用想法或教訓。"},{"en":"New teachers can learn a thing or two from experienced classroom assistants.","zh":"新老師可以向有經驗的課室助理學到一兩件事。"},{"en":"If humans study animal self-care, they may learn a thing or two about natural medicine.","zh":"如果人類研究動物自我照顧，可能學到一兩件關於天然醫藥的事。"},{"en":"The phrase is informal and modest.","zh":"這個短語較口語而謙遜。"}],"source":"151 - Health in the Wild.pdf","sourcePage":14},{"front":"may have done so","meaning":"可能其實已經這樣做","examples":[{"en":"People may, indeed, already have done so.","zh":"人類可能其實已經這樣做了。"},{"en":"May have done so means possibly already did the thing just mentioned.","zh":"“May have done so” 指可能已經做了剛才提到的事情。"},{"en":"The student may have done so if the homework file is already uploaded.","zh":"如果功課文件已上載，學生可能已經這樣做了。"},{"en":"If humans use clay as medicine, they may have done so by learning from animal behaviour.","zh":"如果人類使用黏土作藥物，他們可能其實已經透過觀察動物行為這樣做了。"},{"en":"The phrase expresses a possible past action.","zh":"這個短語表達可能已發生的過去行動。"}],"source":"151 - Health in the Wild.pdf","sourcePage":14},{"front":"many parts of the world","meaning":"世界許多地方","examples":[{"en":"Geophagy is common in many parts of the world.","zh":"食土行為在世界許多地方很常見。"},{"en":"Many parts of the world means many different regions or countries.","zh":"“Many parts of the world” 指許多不同地區或國家。"},{"en":"Rice is a basic food in many parts of the world.","zh":"米飯是世界許多地方的基本食物。"},{"en":"If a habit appears in many parts of the world, it may have an important reason.","zh":"如果某習慣出現在世界許多地方，它可能有重要原因。"},{"en":"The phrase shows that something is widely found.","zh":"這個短語顯示某事廣泛存在。"}],"source":"151 - Health in the Wild.pdf","sourcePage":14},{"front":"medical stalls","meaning":"醫療攤檔","examples":[{"en":"Medical stalls in African markets sell clay tablets.","zh":"非洲市場中的醫療攤檔出售黏土片。"},{"en":"Medical stalls are small market stands that sell health-related products or traditional remedies.","zh":"醫療攤檔是在市場中售賣健康相關產品或傳統療法的小攤位。"},{"en":"A medical stall may sell herbs, oils, tablets, or simple treatments.","zh":"醫療攤檔可能售賣草藥、油、片劑或簡單治療用品。"},{"en":"If people buy clay tablets at medical stalls, they may be using them as medicine.","zh":"如果人們在醫療攤檔購買黏土片，他們可能把它們作藥物使用。"},{"en":"The phrase describes small public places where health products are sold.","zh":"這個短語描述售賣健康產品的小型公共場所。"}],"source":"151 - Health in the Wild.pdf","sourcePage":14},{"front":"African markets","meaning":"非洲市場","examples":[{"en":"African markets may sell tablets made of clay.","zh":"非洲市場可能出售由黏土製成的片劑。"},{"en":"African markets are places in African communities where people buy and sell goods.","zh":"非洲市場是非洲社區中人們買賣貨品的地方。"},{"en":"African markets may sell food, cloth, medicine, tools, and household items.","zh":"非洲市場可能售賣食物、布料、藥物、工具和家居用品。"},{"en":"If traditional remedies are sold in African markets, they may reflect local health beliefs.","zh":"如果傳統療法在非洲市場出售，它們可能反映本地健康信念。"},{"en":"The phrase refers broadly to markets in Africa.","zh":"這個短語廣泛指非洲的市場。"}],"source":"151 - Health in the Wild.pdf","sourcePage":14},{"front":"tablets made of","meaning":"由……製成的片劑","examples":[{"en":"The stalls sell tablets made of different sorts of clays.","zh":"這些攤檔出售由不同種類黏土製成的片劑。"},{"en":"Tablets made of something are small solid pieces formed from that material.","zh":"“Tablets made of” 某物指由該材料製成的小型固體片。"},{"en":"Some medicines are tablets made of compressed powder.","zh":"一些藥物是由壓縮粉末製成的片劑。"},{"en":"If tablets are made of clay, people may swallow or dissolve them for treatment.","zh":"如果片劑由黏土製成，人們可能吞服或溶解它們作治療。"},{"en":"The phrase describes the material used to make the tablets.","zh":"這個短語描述製造片劑的材料。"}],"source":"151 - Health in the Wild.pdf","sourcePage":15},{"front":"different sorts of","meaning":"不同種類的……","examples":[{"en":"The tablets are made of different sorts of clays.","zh":"這些片劑由不同種類的黏土製成。"},{"en":"Different sorts of something means different types or kinds of it.","zh":"“Different sorts of” 某物指它的不同類型或種類。"},{"en":"A supermarket sells different sorts of rice for different dishes.","zh":"超市售賣不同種類的米，用於不同菜式。"},{"en":"If different sorts of clay treat different conditions, sellers must know which one to recommend.","zh":"如果不同種類的黏土治療不同疾病，賣家必須知道推薦哪一種。"},{"en":"The phrase is useful for everyday classification.","zh":"這個短語適合日常分類。"}],"source":"151 - Health in the Wild.pdf","sourcePage":15},{"front":"appropriate to","meaning":"適合……","examples":[{"en":"Different clays are appropriate to different medical conditions.","zh":"不同黏土適合不同健康狀況。"},{"en":"Appropriate to something means suitable for that situation, need, or purpose.","zh":"“Appropriate to” 某事指適合該情況、需要或目的。"},{"en":"Formal language is appropriate to a job application letter.","zh":"正式語言適合求職信。"},{"en":"If a clay is appropriate to one condition, it may not be suitable for another.","zh":"如果某種黏土適合一種疾病，它未必適合另一種。"},{"en":"The phrase stresses matching the right thing to the right situation.","zh":"這個短語強調把合適事物配對合適情況。"}],"source":"151 - Health in the Wild.pdf","sourcePage":15},{"front":"medical conditions","meaning":"健康狀況；疾病","examples":[{"en":"Different clay tablets are used for different medical conditions.","zh":"不同黏土片用於不同健康狀況。"},{"en":"Medical conditions are illnesses, health problems, or states of the body that may need care.","zh":"健康狀況或疾病是可能需要照顧的病症、健康問題或身體狀態。"},{"en":"Asthma, stomach pain, and high blood pressure are medical conditions.","zh":"哮喘、胃痛和高血壓都是健康狀況。"},{"en":"If people use the wrong treatment for a medical condition, the problem may continue.","zh":"如果人們為某種疾病使用錯誤治療，問題可能持續。"},{"en":"The phrase is broad and can refer to many kinds of health issues.","zh":"這個短語很廣泛，可以指許多健康問題。"}],"source":"151 - Health in the Wild.pdf","sourcePage":15},{"front":"bring to","meaning":"將……帶到","examples":[{"en":"Africans brought this tradition to the Americas.","zh":"非洲人將這個傳統帶到美洲。"},{"en":"To bring something to a place means to carry, introduce, or pass it into that place.","zh":"“Bring something to” 某地指把某物帶入、引入或傳入該地。"},{"en":"Migrants may bring food traditions to a new country.","zh":"移民可能將飲食傳統帶到新國家。"},{"en":"If people bring medical customs to another continent, the customs may continue for generations.","zh":"如果人們將醫療習俗帶到另一個大陸，這些習俗可能延續數代。"},{"en":"The phrase describes movement of objects, ideas, or traditions.","zh":"這個短語描述物件、想法或傳統的移動。"}],"source":"151 - Health in the Wild.pdf","sourcePage":15},{"front":"the Americas","meaning":"美洲","examples":[{"en":"Slaves brought geophagy traditions to the Americas.","zh":"奴隸把食土傳統帶到美洲。"},{"en":"The Americas refers to North America, Central America, South America, and nearby islands.","zh":"美洲指北美洲、中美洲、南美洲及附近島嶼。"},{"en":"Many languages and cultures developed in the Americas through migration and colonisation.","zh":"許多語言和文化透過遷徙和殖民在美洲發展。"},{"en":"If a tradition arrived in the Americas through forced migration, its history may be painful.","zh":"如果一個傳統透過被迫遷徙到達美洲，其歷史可能很痛苦。"},{"en":"The phrase names a broad geographical region.","zh":"這個短語指一個廣闊地理區域。"}],"source":"151 - Health in the Wild.pdf","sourcePage":15},{"front":"as slaves","meaning":"作為奴隸","examples":[{"en":"Africans were brought to the Americas as slaves.","zh":"非洲人作為奴隸被帶到美洲。"},{"en":"As slaves means in the condition of being enslaved and forced to work without freedom.","zh":"“As slaves” 指處於被奴役、被迫工作且沒有自由的狀態。"},{"en":"People taken as slaves were denied basic rights and control over their own lives.","zh":"被帶走作為奴隸的人被剝奪基本權利和對自己生活的控制。"},{"en":"If a tradition was carried by people brought as slaves, it is linked to a history of suffering.","zh":"如果一個傳統由作為奴隸被帶走的人攜帶，它就與苦難歷史相連。"},{"en":"The phrase describes a forced and unjust social status.","zh":"這個短語描述被迫且不公義的社會身份。"}],"source":"151 - Health in the Wild.pdf","sourcePage":15},{"front":"continue this tradition","meaning":"延續這個傳統","examples":[{"en":"Africans in the Americas continued this tradition.","zh":"美洲的非洲人延續這個傳統。"},{"en":"To continue this tradition means to keep practising a custom from the past.","zh":"“Continue this tradition” 指繼續實踐來自過去的習俗。"},{"en":"Families continue this tradition when they cook the same festival food every year.","zh":"家庭每年煮同一道節日食物時，就是在延續這個傳統。"},{"en":"If people continue a medical tradition in a new country, it may remain part of community identity.","zh":"如果人們在新國家延續醫療傳統，它可能仍是社區身份的一部分。"},{"en":"The phrase shows cultural survival over time.","zh":"這個短語顯示文化隨時間存續。"}],"source":"151 - Health in the Wild.pdf","sourcePage":15},{"front":"give someone one more excuse to","meaning":"給某人多一個藉口去……","examples":[{"en":"The tradition gave their owners one more excuse to despise them.","zh":"這個傳統給奴隸主人多一個藉口去鄙視他們。"},{"en":"To give someone one more excuse to do something means to provide another reason they can use, often unfairly, to justify their behaviour.","zh":"“Give someone one more excuse to” 做某事指提供另一個理由，常是不公平地讓對方合理化其行為。"},{"en":"A small mistake may give a harsh manager one more excuse to criticise an employee.","zh":"一個小錯誤可能給苛刻經理多一個藉口去批評員工。"},{"en":"If prejudice already exists, any unfamiliar custom can give people one more excuse to judge others.","zh":"如果偏見已存在，任何陌生習俗都可能給人多一個藉口去評判他人。"},{"en":"The phrase often suggests the excuse is not fair or reasonable.","zh":"這個短語常暗示該藉口並不公平或合理。"}],"source":"151 - Health in the Wild.pdf","sourcePage":15},{"front":"despise","meaning":"鄙視","examples":[{"en":"Slave owners used the tradition as an excuse to despise them.","zh":"奴隸主人把這個傳統作為鄙視他們的藉口。"},{"en":"To despise someone means to strongly look down on or hate them.","zh":"“Despise” 某人指強烈看不起或憎恨對方。"},{"en":"A fair person should not despise others because of poverty, accent, or background.","zh":"公平的人不應因貧窮、口音或背景而鄙視他人。"},{"en":"When people despise a group, they may treat its customs as foolish or inferior.","zh":"當人們鄙視一個群體時，可能把其習俗視為愚蠢或低等。"},{"en":"The word is stronger than dislike and carries moral judgement.","zh":"這個詞比 dislike 更強烈，帶有道德判斷。"}],"source":"151 - Health in the Wild.pdf","sourcePage":15},{"front":"point out","meaning":"指出","examples":[{"en":"Dr Engel points out that some gorillas eat clay.","zh":"Engel 博士指出一些大猩猩吃黏土。"},{"en":"To point out means to mention or draw attention to a fact.","zh":"“Point out” 指提及或提醒人注意某個事實。"},{"en":"A teacher may point out a common mistake before students write again.","zh":"老師可能在學生再次寫作前指出一個常見錯誤。"},{"en":"If researchers point out a similar behaviour in another animal, the argument becomes broader.","zh":"如果研究人員指出另一種動物有相似行為，論點會變得更廣泛。"},{"en":"The phrase is useful when adding an important observation.","zh":"這個短語適合加入重要觀察。"}],"source":"151 - Health in the Wild.pdf","sourcePage":15},{"front":"Rwandan mountain gorillas","meaning":"盧旺達山地大猩猩","examples":[{"en":"Rwandan mountain gorillas eat a type of clay.","zh":"盧旺達山地大猩猩吃一種黏土。"},{"en":"Rwandan mountain gorillas are mountain gorillas living in or associated with Rwanda.","zh":"盧旺達山地大猩猩是生活在或與盧旺達有關的山地大猩猩。"},{"en":"Rwandan mountain gorillas are carefully protected because they are rare and valuable wildlife.","zh":"盧旺達山地大猩猩受到仔細保護，因為牠們是稀有而珍貴的野生動物。"},{"en":"If Rwandan mountain gorillas eat clay, scientists may compare their behaviour with parrots and chimps.","zh":"如果盧旺達山地大猩猩吃黏土，科學家可能把牠們的行為與鸚鵡和黑猩猩比較。"},{"en":"The phrase identifies both the animal and its location.","zh":"這個短語同時指出動物和地點。"}],"source":"151 - Health in the Wild.pdf","sourcePage":16},{"front":"a type of clay","meaning":"一種黏土","examples":[{"en":"The gorillas eat a type of clay similar to kaolinite.","zh":"這些大猩猩吃一種與高嶺石相似的黏土。"},{"en":"A type of clay means one particular kind of clay with certain features.","zh":"“A type of clay” 指具有某些特徵的一種特定黏土。"},{"en":"Potters choose a type of clay depending on the shape and strength they need.","zh":"陶藝家會根據所需形狀和強度選擇一種黏土。"},{"en":"If animals choose a specific type of clay, it may have a special chemical property.","zh":"如果動物選擇一種特定黏土，它可能有特殊化學特性。"},{"en":"The phrase helps classify clay into different kinds.","zh":"這個短語有助把黏土分類成不同種類。"}],"source":"151 - Health in the Wild.pdf","sourcePage":16},{"front":"rather similar to","meaning":"與……頗相似","examples":[{"en":"The clay is rather similar to kaolinite.","zh":"這種黏土與高嶺石頗相似。"},{"en":"Rather similar to means quite like something, though not exactly the same.","zh":"“Rather similar to” 指與某物頗為相似，但不完全一樣。"},{"en":"This student’s essay is rather similar to the model answer, but the examples are different.","zh":"這名學生的作文與範文頗相似，但例子不同。"},{"en":"If an animal clay is rather similar to a medicine ingredient, scientists may find the link interesting.","zh":"如果動物吃的黏土與藥物成分頗相似，科學家可能覺得這個關聯有趣。"},{"en":"The phrase shows moderate similarity.","zh":"這個短語表示中等程度相似。"}],"source":"151 - Health in the Wild.pdf","sourcePage":16},{"front":"kaolinite","meaning":"高嶺石","examples":[{"en":"Kaolinite is the main ingredient of many digestive medicines.","zh":"高嶺石是許多消化藥物的主要成分。"},{"en":"Kaolinite is a type of clay mineral used in some medicines for stomach problems.","zh":"高嶺石是一種黏土礦物，用於一些治療胃部問題的藥物。"},{"en":"A medicine containing kaolinite may help calm digestive discomfort.","zh":"含有高嶺石的藥物可能有助舒緩消化不適。"},{"en":"If gorillas eat clay similar to kaolinite, their behaviour may resemble human medication use.","zh":"如果大猩猩吃與高嶺石相似的黏土，牠們的行為可能類似人類用藥。"},{"en":"The word names a specific clay mineral.","zh":"這個詞指一種特定黏土礦物。"}],"source":"151 - Health in the Wild.pdf","sourcePage":16},{"front":"main ingredient","meaning":"主要成分","examples":[{"en":"Kaolinite is the main ingredient in many patent medicines.","zh":"高嶺石是許多成藥的主要成分。"},{"en":"The main ingredient is the most important or largest substance in a product.","zh":"主要成分是產品中最重要或含量最大的物質。"},{"en":"Flour is the main ingredient in many kinds of bread.","zh":"麵粉是許多麵包的主要成分。"},{"en":"If the main ingredient causes side effects, the whole product must be used carefully.","zh":"如果主要成分造成副作用，整個產品都必須小心使用。"},{"en":"The phrase identifies the key part of a mixture.","zh":"這個短語指出混合物的關鍵部分。"}],"source":"151 - Health in the Wild.pdf","sourcePage":16},{"front":"patent medicines","meaning":"成藥","examples":[{"en":"Many patent medicines contain kaolinite.","zh":"許多成藥含有高嶺石。"},{"en":"Patent medicines are ready-made medicines sold under a name, often without needing a special prescription.","zh":"成藥是以特定名稱出售的現成藥物，通常不需要特別處方。"},{"en":"A pharmacy may sell patent medicines for coughs, stomach pain, or headaches.","zh":"藥房可能出售治療咳嗽、胃痛或頭痛的成藥。"},{"en":"If patent medicines are used carelessly, people may take the wrong treatment.","zh":"如果成藥被草率使用，人們可能服用錯誤治療。"},{"en":"The phrase refers to commercial medicine products.","zh":"這個短語指商業藥物產品。"}],"source":"151 - Health in the Wild.pdf","sourcePage":16},{"front":"sold over the counter","meaning":"非處方出售","examples":[{"en":"These medicines are sold over the counter in the West.","zh":"這些藥物在西方非處方出售。"},{"en":"Sold over the counter means available to buy without a doctor’s prescription.","zh":"“Sold over the counter” 指不需要醫生處方即可購買。"},{"en":"Simple painkillers are often sold over the counter in pharmacies.","zh":"簡單止痛藥通常在藥房非處方出售。"},{"en":"If a medicine is sold over the counter, people should still read the instructions carefully.","zh":"即使藥物非處方出售，人們仍應仔細閱讀說明。"},{"en":"The phrase contrasts with prescription-only medicine.","zh":"這個短語與只可憑處方購買的藥物形成對比。"}],"source":"151 - Health in the Wild.pdf","sourcePage":16},{"front":"in the West","meaning":"在西方","examples":[{"en":"These medicines are sold over the counter in the West.","zh":"這些藥物在西方非處方出售。"},{"en":"In the West usually means in Western countries such as those in Europe or North America.","zh":"“In the West” 通常指在歐洲或北美等西方國家。"},{"en":"Some health products common in the West may be unfamiliar in other regions.","zh":"一些在西方常見的健康產品，在其他地區可能較陌生。"},{"en":"If a medicine is sold in the West, its use may reflect Western medical habits.","zh":"如果一種藥物在西方出售，其使用可能反映西方醫療習慣。"},{"en":"The phrase refers broadly to a cultural or geographical region.","zh":"這個短語廣泛指一個文化或地理區域。"}],"source":"151 - Health in the Wild.pdf","sourcePage":16},{"front":"digestive complaints","meaning":"消化問題","examples":[{"en":"Some over-the-counter medicines treat digestive complaints.","zh":"一些非處方藥物治療消化問題。"},{"en":"Digestive complaints are problems related to the stomach or intestines, such as pain, diarrhoea, or indigestion.","zh":"消化問題是與胃或腸道有關的問題，例如疼痛、腹瀉或消化不良。"},{"en":"A person with digestive complaints may avoid heavy meals for a few days.","zh":"有消化問題的人可能幾天內避免吃太飽。"},{"en":"If digestive complaints continue, a doctor should check for a deeper problem.","zh":"如果消化問題持續，醫生應檢查是否有更深層問題。"},{"en":"The phrase is a polite medical way to describe stomach-related troubles.","zh":"這個短語是描述胃腸問題的較禮貌醫學說法。"}],"source":"151 - Health in the Wild.pdf","sourcePage":16},{"front":"be good for you","meaning":"對你有益","examples":[{"en":"Dirt can sometimes be good for you.","zh":"泥土有時可能對你有益。"},{"en":"If something is good for you, it benefits your health, learning, or general wellbeing.","zh":"如果某物 “is good for you”，它對你的健康、學習或整體福祉有好處。"},{"en":"Regular sleep is good for you because it improves memory and mood.","zh":"定期睡眠對你有益，因為它改善記憶和心情。"},{"en":"If clay reduces toxins, a small amount of dirt may sometimes be good for certain animals.","zh":"如果黏土能減少毒素，少量泥土有時可能對某些動物有益。"},{"en":"The phrase is simple and common in health advice.","zh":"這個短語簡單，常見於健康建議。"}],"source":"151 - Health in the Wild.pdf","sourcePage":16},{"front":"as sick as a parrot","meaning":"非常失望／非常不適","examples":[{"en":"To be “as sick as a parrot” may be desirable after all.","zh":"“As sick as a parrot” 畢竟可能是值得追求的。"},{"en":"As sick as a parrot is an idiom meaning very disappointed or very unwell, depending on context.","zh":"“As sick as a parrot” 是成語，可指非常失望或非常不適，視乎語境而定。"},{"en":"A football fan may be as sick as a parrot after his team loses the final.","zh":"如果一名足球迷的球隊輸掉決賽，他可能非常失望。"},{"en":"In this passage, the phrase is playful because parrots may use clay to protect their health.","zh":"在本文中，這個短語帶玩笑意味，因為鸚鵡可能用黏土保護健康。"},{"en":"The idiom is humorous when linked to real parrots and medicine.","zh":"當這個成語與真正的鸚鵡和藥物連繫起來時，便帶有幽默感。"}],"source":"151 - Health in the Wild.pdf","sourcePage":16},{"front":"after all","meaning":"畢竟","examples":[{"en":"Being “as sick as a parrot” may, after all, be desirable.","zh":"畢竟，像鸚鵡一樣「病」可能是值得追求的。"},{"en":"After all means despite earlier doubts or expectations, the final point may be true.","zh":"“After all” 指儘管之前有懷疑或預期，最後某點可能是真的。"},{"en":"I thought the lesson would be boring, but it was useful after all.","zh":"我原以為這堂課會沉悶，但畢竟它很有用。"},{"en":"If dirt can act like medicine, eating it may not be foolish after all.","zh":"如果泥土能像藥物一樣發揮作用，吃泥土畢竟未必愚蠢。"},{"en":"The phrase often introduces a surprising conclusion.","zh":"這個短語常引出令人意外的結論。"}],"source":"151 - Health in the Wild.pdf","sourcePage":17},{"front":"a state to be desired","meaning":"值得追求的狀態","examples":[{"en":"The passage jokes that sickness like a parrot’s may be a state to be desired.","zh":"文章開玩笑說，像鸚鵡般「生病」可能是值得追求的狀態。"},{"en":"A state to be desired is a condition that people might actually want.","zh":"“A state to be desired” 指人們可能真正想要的一種狀態。"},{"en":"Calm confidence before an exam is a state to be desired.","zh":"考試前冷靜自信是一種值得追求的狀態。"},{"en":"If “sickness” leads animals to useful self-treatment, it may jokingly be called a state to be desired.","zh":"如果「生病」令動物進行有用的自我治療，它可以被開玩笑地稱為值得追求的狀態。"},{"en":"The phrase is formal and slightly humorous in this context.","zh":"這個短語在此語境中較正式，並帶少許幽默。"}],"source":"151 - Health in the Wild.pdf","sourcePage":17},{"front":"agree with the information","meaning":"與資料一致","examples":[{"en":"Students decide whether each statement agrees with the information in the passage.","zh":"學生判斷每個陳述是否與文章資料一致。"},{"en":"To agree with the information means to match what the passage says.","zh":"“Agree with the information” 指與文章所說內容相符。"},{"en":"In a reading test, an answer agrees with the information only if the text supports it clearly.","zh":"在閱讀測驗中，只有文本清楚支持答案時，它才與資料一致。"},{"en":"If a statement changes the meaning of the passage, it does not agree with the information.","zh":"如果陳述改變文章意思，它就不與資料一致。"},{"en":"The phrase is common in TRUE/FALSE/NOT GIVEN questions.","zh":"這個短語常見於 TRUE/FALSE/NOT GIVEN 題。"}],"source":"151 - Health in the Wild.pdf","sourcePage":17},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A statement is false if it contradicts the information.","zh":"如果陳述與資料相矛盾，它就是錯誤的。"},{"en":"To contradict the information means to say the opposite of what the passage states.","zh":"“Contradict the information” 指說出與文章所述相反的內容。"},{"en":"If the passage says the animal ate clay, an answer saying it avoided clay contradicts the information.","zh":"如果文章說動物吃黏土，而答案說牠避免黏土，便與資料相矛盾。"},{"en":"Students should mark FALSE when a statement directly contradicts the information.","zh":"當陳述直接與資料相矛盾時，學生應標記 FALSE。"},{"en":"The phrase is important for checking exact meaning.","zh":"這個短語對檢查準確意思很重要。"}],"source":"151 - Health in the Wild.pdf","sourcePage":17},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有相關資料，學生寫 NOT GIVEN。"},{"en":"No information on this means the passage does not say whether the statement is true or false.","zh":"“No information on this” 指文章沒有說明該陳述是真是假。"},{"en":"If the text mentions animals eating clay but not travel distance, there is no information on this.","zh":"如果文本提到動物吃黏土，但沒有提到移動距離，就沒有相關資料。"},{"en":"Students should not guess TRUE when there is no information on this in the passage.","zh":"當文章沒有相關資料時，學生不應猜 TRUE。"},{"en":"The phrase helps identify NOT GIVEN answers.","zh":"這個短語有助辨認 NOT GIVEN 答案。"}],"source":"151 - Health in the Wild.pdf","sourcePage":17},{"front":"spend ten years studying","meaning":"花十年研究","examples":[{"en":"Dr Engel has spent ten years studying animal self-medication.","zh":"Engel 博士花十年研究動物自我用藥。"},{"en":"To spend ten years studying something means to devote ten years to learning or researching it.","zh":"“Spend ten years studying” 某事指投入十年學習或研究它。"},{"en":"A scientist may spend ten years studying one disease before finding a useful treatment.","zh":"科學家可能花十年研究一種疾病，才找到有用治療方法。"},{"en":"If someone spends ten years studying a topic, they usually develop deep expertise.","zh":"如果某人花十年研究一個題目，通常會發展出深厚專業知識。"},{"en":"The phrase highlights long-term effort.","zh":"這個短語強調長期努力。"}],"source":"151 - Health in the Wild.pdf","sourcePage":17},{"front":"need to travel long distances","meaning":"需要長途跋涉","examples":[{"en":"The statement asks whether animals need to travel long distances to find medicinal plants.","zh":"該陳述問動物是否需要長途跋涉去尋找藥用植物。"},{"en":"To need to travel long distances means to have to go far from one place to another.","zh":"“Need to travel long distances” 指必須從一地到另一地走很遠。"},{"en":"Some patients need to travel long distances because the nearest hospital is far away.","zh":"一些病人因最近的醫院很遠而需要長途跋涉。"},{"en":"If animals need to travel long distances for medicine, illness may create extra risk.","zh":"如果動物需要長途跋涉尋找藥物，疾病可能帶來額外風險。"},{"en":"The phrase focuses on the burden of distance.","zh":"這個短語強調距離帶來的負擔。"}],"source":"151 - Health in the Wild.pdf","sourcePage":17},{"front":"medicinal plants","meaning":"藥用植物","examples":[{"en":"Some animals use medicinal plants to treat themselves.","zh":"一些動物使用藥用植物來自我治療。"},{"en":"Medicinal plants are plants used to treat illness, pain, or health problems.","zh":"藥用植物是用於治療疾病、痛楚或健康問題的植物。"},{"en":"Aloe and ginger are common examples of medicinal plants in many homes.","zh":"蘆薈和薑是許多家庭中常見的藥用植物例子。"},{"en":"If animals choose medicinal plants when sick, scientists may study their effects.","zh":"如果動物生病時選擇藥用植物，科學家可能研究其作用。"},{"en":"The phrase refers to plants valued for health uses.","zh":"這個短語指因健康用途而有價值的植物。"}],"source":"151 - Health in the Wild.pdf","sourcePage":17},{"front":"form part of","meaning":"構成……的一部分","examples":[{"en":"The question asks whether clay forms part of macaws’ natural diet.","zh":"題目問黏土是否構成金剛鸚鵡天然飲食的一部分。"},{"en":"To form part of something means to be included as one element of it.","zh":"“Form part of” 某事指作為其中一個元素被包括在內。"},{"en":"Reading aloud can form part of a language lesson.","zh":"朗讀可以構成語言課的一部分。"},{"en":"If clay forms part of a bird’s natural diet, it may not be unusual for the bird to eat it.","zh":"如果黏土構成鳥類天然飲食的一部分，牠吃黏土可能並不異常。"},{"en":"The phrase shows inclusion within a larger whole.","zh":"這個短語顯示包含於較大整體之中。"}],"source":"151 - Health in the Wild.pdf","sourcePage":17},{"front":"natural diet","meaning":"天然飲食","examples":[{"en":"Clay may not simply be part of the birds’ natural diet.","zh":"黏土可能不只是鳥類天然飲食的一部分。"},{"en":"A natural diet is the food an animal normally eats in the wild.","zh":"天然飲食是動物在野外通常進食的食物。"},{"en":"A panda’s natural diet mainly includes bamboo.","zh":"熊貓的天然飲食主要包括竹。"},{"en":"If an animal eats something outside its natural diet, researchers may ask why.","zh":"如果動物吃天然飲食以外的東西，研究人員可能會問為甚麼。"},{"en":"The phrase contrasts normal feeding with unusual or medicinal eating.","zh":"這個短語把正常進食與異常或醫療性進食作對比。"}],"source":"151 - Health in the Wild.pdf","sourcePage":17},{"front":"research into","meaning":"對……的研究","examples":[{"en":"The question refers to research into animal self-medication.","zh":"題目提到對動物自我用藥的研究。"},{"en":"Research into something means careful study of that topic.","zh":"“Research into” 某事指對該題目的仔細研究。"},{"en":"Research into sleep habits can help schools design better timetables.","zh":"對睡眠習慣的研究可以幫助學校設計更好時間表。"},{"en":"If research into animal self-medication grows, farmers may learn new ways to protect livestock.","zh":"如果對動物自我用藥的研究增加，農民可能學到保護牲畜的新方法。"},{"en":"The phrase introduces the topic being studied.","zh":"這個短語引出正在被研究的題目。"}],"source":"151 - Health in the Wild.pdf","sourcePage":17},{"front":"help in the development of","meaning":"有助於……的發展","examples":[{"en":"The question asks whether the research could help in the development of new painkillers.","zh":"題目問該研究是否有助於新止痛藥的發展。"},{"en":"To help in the development of something means to support the process of creating or improving it.","zh":"“Help in the development of” 某事指支持創造或改善它的過程。"},{"en":"Patient feedback can help in the development of better hospital services.","zh":"病人回饋可以有助於更好醫院服務的發展。"},{"en":"If plant research helps in the development of medicines, it may benefit human health.","zh":"如果植物研究有助於藥物發展，它可能有利於人類健康。"},{"en":"The phrase connects research or support with future creation.","zh":"這個短語把研究或支援與未來創造連繫起來。"}],"source":"151 - Health in the Wild.pdf","sourcePage":18},{"front":"new painkillers","meaning":"新止痛藥","examples":[{"en":"The statement mentions the development of new painkillers.","zh":"該陳述提到新止痛藥的發展。"},{"en":"New painkillers are newly developed medicines used to reduce pain.","zh":"新止痛藥是新研發、用於減輕痛楚的藥物。"},{"en":"Doctors may need new painkillers when older drugs have strong side effects.","zh":"當舊藥有強烈副作用時，醫生可能需要新止痛藥。"},{"en":"If research on plants leads to new painkillers, patients may have more treatment choices.","zh":"如果植物研究帶來新止痛藥，病人可能有更多治療選擇。"},{"en":"The phrase belongs to medical development and drug research.","zh":"這個短語屬於醫療發展和藥物研究。"}],"source":"151 - Health in the Wild.pdf","sourcePage":18},{"front":"complete the notes below","meaning":"完成以下筆記","examples":[{"en":"Candidates complete the notes below using words from the passage.","zh":"考生使用文章中的詞語完成以下筆記。"},{"en":"Complete the notes below means fill in missing information in the notes under the question.","zh":"“Complete the notes below” 指填寫題目下方筆記中的缺漏資料。"},{"en":"In a reading test, students should complete the notes below with exact words from the text.","zh":"在閱讀測驗中，學生應使用文本中的準確詞語完成以下筆記。"},{"en":"If candidates ignore the word limit, they may lose marks even if the idea is correct.","zh":"如果考生忽略字數限制，即使意思正確也可能失分。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"151 - Health in the Wild.pdf","sourcePage":18},{"front":"no more than one word","meaning":"不超過一個詞","examples":[{"en":"Candidates choose no more than one word from the passage.","zh":"考生從文章中選擇不超過一個詞。"},{"en":"No more than one word means the answer must be one word or less, not two words.","zh":"“No more than one word” 指答案必須是一個詞或少於一個詞，不能是兩個詞。"},{"en":"If the answer limit is no more than one word, “clay tablets” is too long.","zh":"如果答案限制是不超過一個詞，“clay tablets” 就太長。"},{"en":"Students should check spelling carefully when only one word is allowed.","zh":"當只允許一個詞時，學生應仔細檢查拼字。"},{"en":"The phrase gives a strict exam answer limit.","zh":"這個短語給出嚴格的考試答案限制。"}],"source":"151 - Health in the Wild.pdf","sourcePage":18},{"front":"food mechanism","meaning":"食物與機制","examples":[{"en":"The notes compare the animal, food and mechanism.","zh":"筆記比較動物、食物與機制。"},{"en":"Food mechanism means the food eaten and the way it works inside the animal.","zh":"食物與機制指動物吃的食物以及它在體內如何發揮作用。"},{"en":"In the chart, leaves are the food and hooks are part of the mechanism.","zh":"在圖表中，葉子是食物，而鈎狀物是機制的一部分。"},{"en":"If students identify the food mechanism correctly, they understand both what the animal eats and why it helps.","zh":"如果學生正確辨認食物與機制，他們就理解動物吃甚麼以及為何有幫助。"},{"en":"The phrase connects diet with function.","zh":"這個短語把飲食與功能連繫起來。"}],"source":"151 - Health in the Wild.pdf","sourcePage":18},{"front":"contain chemicals named","meaning":"含有名為……的化學物質","examples":[{"en":"The plant contained chemicals named terpenes.","zh":"該植物含有名為萜烯的化學物質。"},{"en":"To contain chemicals named something means to have chemicals with that particular name.","zh":"“Contain chemicals named” 某名稱指含有具有該特定名稱的化學物質。"},{"en":"Some herbs contain chemicals named antioxidants.","zh":"一些香草含有名為抗氧化物的化學物質。"},{"en":"If a plant contains chemicals named terpenes, those chemicals may explain its effects.","zh":"如果植物含有名為萜烯的化學物質，這些化學物質可能解釋其作用。"},{"en":"The phrase introduces a named chemical group inside a substance.","zh":"這個短語引出某物內的一組具名化學物質。"}],"source":"151 - Health in the Wild.pdf","sourcePage":18},{"front":"kill parasites","meaning":"殺死寄生蟲","examples":[{"en":"Terpenes can kill parasites.","zh":"萜烯可以殺死寄生蟲。"},{"en":"To kill parasites means to destroy organisms that live on or inside a host and harm it.","zh":"“Kill parasites” 指消滅生活在宿主表面或體內並傷害宿主的生物。"},{"en":"Some medicines kill parasites in the intestines.","zh":"一些藥物可以殺死腸道中的寄生蟲。"},{"en":"If a plant can kill parasites without killing the animal, it may be medicinal.","zh":"如果植物能殺死寄生蟲而不殺死動物，它可能具有藥用價值。"},{"en":"The phrase describes a direct anti-parasite effect.","zh":"這個短語描述直接的抗寄生蟲作用。"}],"source":"151 - Health in the Wild.pdf","sourcePage":18},{"front":"tiny hooks","meaning":"微小鈎狀物","examples":[{"en":"The leaves had tiny hooks on their surface.","zh":"這些葉子表面有微小鈎狀物。"},{"en":"Tiny hooks are very small hook-shaped structures.","zh":"微小鈎狀物是非常細小的鈎形結構。"},{"en":"Some plant seeds have tiny hooks that stick to animal fur.","zh":"一些植物種子有微小鈎狀物，可以黏在動物毛皮上。"},{"en":"If leaves have tiny hooks, they may catch worms as they pass through the gut.","zh":"如果葉子有微小鈎狀物，它們通過腸道時可能鈎住蟲。"},{"en":"The phrase describes small physical structures that can attach to things.","zh":"這個短語描述可以附着物件的小型物理結構。"}],"source":"151 - Health in the Wild.pdf","sourcePage":18},{"front":"on their surface","meaning":"在其表面上","examples":[{"en":"The leaves had hooks on their surface.","zh":"這些葉子在其表面上有鈎狀物。"},{"en":"On their surface means on the outside layer of those things.","zh":"“On their surface” 指在那些東西的外層上。"},{"en":"Some fruits have tiny hairs on their surface.","zh":"一些水果在其表面上有細小毛。"},{"en":"If hooks are on the leaves’ surface, they can touch and catch worms inside the gut.","zh":"如果鈎狀物在葉子表面上，它們可以在腸道內接觸並鈎住蟲。"},{"en":"The phrase shows where a feature is located.","zh":"這個短語顯示某特徵的位置。"}],"source":"151 - Health in the Wild.pdf","sourcePage":18},{"front":"catch and expel worms","meaning":"鈎住並排出蟲","examples":[{"en":"The leaves can catch and expel worms from intestines.","zh":"這些葉子可以從腸道中鈎住並排出蟲。"},{"en":"To catch and expel worms means to trap worms and push or carry them out of the body.","zh":"“Catch and expel worms” 指困住蟲並把牠們推出或帶出身體。"},{"en":"A rough leaf may catch and expel worms as it moves through the gut.","zh":"粗糙葉子通過腸道時可能鈎住並排出蟲。"},{"en":"If worms are caught and expelled, the animal may suffer fewer parasites.","zh":"如果蟲被鈎住並排出，動物可能受較少寄生蟲影響。"},{"en":"The phrase describes a mechanical removal process.","zh":"這個短語描述機械式移除過程。"}],"source":"151 - Health in the Wild.pdf","sourcePage":18},{"front":"from intestines","meaning":"從腸道中","examples":[{"en":"The leaves help expel worms from intestines.","zh":"這些葉子幫助從腸道中排出蟲。"},{"en":"From intestines means out of the tubes in the body where food is digested and waste is formed.","zh":"“From intestines” 指從身體中消化食物並形成廢物的管道中。"},{"en":"Doctors may remove harmful bacteria from intestines with suitable treatment.","zh":"醫生可能用合適治療從腸道中清除有害細菌。"},{"en":"If worms are removed from intestines, the animal’s digestion may improve.","zh":"如果蟲從腸道中被移除，動物的消化可能改善。"},{"en":"The phrase identifies the body part where the problem is located.","zh":"這個短語指出問題所在的身體部位。"}],"source":"151 - Health in the Wild.pdf","sourcePage":18},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Candidates complete the summary below using words from the box.","zh":"考生使用方框中的詞語完成以下摘要。"},{"en":"Complete the summary below means fill in missing words in the short passage under the question.","zh":"“Complete the summary below” 指填寫題目下方短文摘要中的缺漏詞語。"},{"en":"Students should read the whole summary below before choosing answers.","zh":"學生應先閱讀整段以下摘要，再選擇答案。"},{"en":"If a word does not fit the grammar, it cannot complete the summary correctly.","zh":"如果某詞不符合文法，就不能正確完成摘要。"},{"en":"The phrase is a common instruction in reading tests.","zh":"這個短語是閱讀測驗中的常見指示。"}],"source":"151 - Health in the Wild.pdf","sourcePage":19},{"front":"though often doubted","meaning":"雖然經常受到質疑","examples":[{"en":"Though often doubted, animal self-medication is supported by evidence.","zh":"雖然經常受到質疑，動物自我用藥仍有證據支持。"},{"en":"Though often doubted means although many people have questioned or disbelieved it.","zh":"“Though often doubted” 指雖然許多人曾質疑或不相信它。"},{"en":"Though often doubted, shy students can become strong speakers with practice.","zh":"雖然經常受到質疑，害羞學生透過練習也可以成為強大的演講者。"},{"en":"If an idea is often doubted but evidence supports it, people may slowly accept it.","zh":"如果一個想法經常受到質疑但有證據支持，人們可能慢慢接受它。"},{"en":"The phrase introduces contrast between doubt and support.","zh":"這個短語引出懷疑與支持之間的對比。"}],"source":"151 - Health in the Wild.pdf","sourcePage":19},{"front":"increasing amount of evidence","meaning":"越來越多證據","examples":[{"en":"An increasing amount of evidence supports animal self-medication.","zh":"越來越多證據支持動物自我用藥。"},{"en":"An increasing amount of evidence means more and more information supporting an idea.","zh":"“An increasing amount of evidence” 指越來越多支持某想法的資料。"},{"en":"An increasing amount of evidence shows that sleep affects learning.","zh":"越來越多證據顯示睡眠影響學習。"},{"en":"If an increasing amount of evidence supports a theory, scientists become more confident.","zh":"如果越來越多證據支持一個理論，科學家會更有信心。"},{"en":"The phrase describes evidence growing over time.","zh":"這個短語描述證據隨時間增加。"}],"source":"151 - Health in the Wild.pdf","sourcePage":19},{"front":"one piece of evidence","meaning":"一項證據","examples":[{"en":"One piece of evidence deals with geophagy.","zh":"一項證據涉及食土行為。"},{"en":"One piece of evidence is one fact, observation, or result that supports an argument.","zh":"一項證據是支持論點的一個事實、觀察結果或結果。"},{"en":"A photo can be one piece of evidence in an investigation.","zh":"一張照片可以是調查中的一項證據。"},{"en":"One piece of evidence alone may not prove a theory, but it can support it.","zh":"單一項證據未必能證明理論，但可以支持它。"},{"en":"The phrase breaks a larger argument into individual supports.","zh":"這個短語把較大論點拆成個別支持。"}],"source":"151 - Health in the Wild.pdf","sourcePage":19},{"front":"particularly deals with","meaning":"特別涉及","examples":[{"en":"The summary particularly deals with geophagy.","zh":"摘要特別涉及食土行為。"},{"en":"Particularly deals with means focuses especially on one topic.","zh":"“Particularly deals with” 指特別集中於某一題目。"},{"en":"This lesson particularly deals with mistakes in verb tense.","zh":"這堂課特別涉及動詞時態錯誤。"},{"en":"If a paragraph particularly deals with clay eating, other details may be less central.","zh":"如果段落特別涉及吃黏土，其他細節可能較不核心。"},{"en":"The phrase helps identify the main focus of a section.","zh":"這個短語有助辨認某部分的主要焦點。"}],"source":"151 - Health in the Wild.pdf","sourcePage":19},{"front":"soil-consuming behaviour","meaning":"食土行為","examples":[{"en":"Geophagy is a soil-consuming behaviour.","zh":"食土行為是一種吃泥土的行為。"},{"en":"Soil-consuming behaviour means behaviour in which animals or people eat soil or earth.","zh":"食土行為指動物或人類吃土壤或泥土的行為。"},{"en":"Some birds show soil-consuming behaviour after eating toxic seeds.","zh":"一些鳥類在吃有毒種子後表現出食土行為。"},{"en":"If soil-consuming behaviour appears in many species, it may serve a medical function.","zh":"如果食土行為出現在許多物種中，它可能有醫療功能。"},{"en":"The phrase explains geophagy in simpler words.","zh":"這個短語用更簡單的詞解釋 geophagy。"}],"source":"151 - Health in the Wild.pdf","sourcePage":19},{"front":"commonly found across","meaning":"常見於各種……","examples":[{"en":"Geophagy is commonly found across animal species.","zh":"食土行為常見於各種動物物種。"},{"en":"Commonly found across something means often seen in many different examples within that group.","zh":"“Commonly found across” 某群體指常在該群體內許多不同例子中看見。"},{"en":"Smartphone use is commonly found across different age groups.","zh":"智能電話使用常見於各種年齡群體。"},{"en":"If geophagy is commonly found across species, it is unlikely to be a rare accident.","zh":"如果食土行為常見於各種物種，它不太可能是罕見偶然事件。"},{"en":"The phrase shows a pattern spread across a wide group.","zh":"這個短語顯示一種模式廣泛存在於某群體中。"}],"source":"151 - Health in the Wild.pdf","sourcePage":19},{"front":"neutralize the toxic content","meaning":"中和有毒成分","examples":[{"en":"Clay can neutralize the toxic content of animals’ diets.","zh":"黏土可以中和動物飲食中的有毒成分。"},{"en":"To neutralize the toxic content means to reduce or cancel the harmful effects of poisonous substances.","zh":"“Neutralize the toxic content” 指減少或抵消有毒物質的有害作用。"},{"en":"Water treatment can neutralize harmful chemicals before people drink the water.","zh":"食水處理可以在人們飲水前中和有害化學物質。"},{"en":"If clay neutralizes toxic content, animals can eat certain plants more safely.","zh":"如果黏土中和有毒成分，動物可以更安全地吃某些植物。"},{"en":"The phrase describes making poison less harmful.","zh":"這個短語描述令毒素較不有害。"}],"source":"151 - Health in the Wild.pdf","sourcePage":19},{"front":"content of their diet","meaning":"牠們飲食中的成分","examples":[{"en":"Clay may neutralize the toxic content of their diet.","zh":"黏土可能中和牠們飲食中的有毒成分。"},{"en":"The content of their diet means what their food contains.","zh":"“The content of their diet” 指牠們食物中含有的東西。"},{"en":"A doctor may ask about the content of a patient’s diet to check for too much sugar.","zh":"醫生可能詢問病人飲食中的成分，以檢查是否有太多糖。"},{"en":"If the content of their diet includes toxins, animals may need detoxifying materials.","zh":"如果牠們飲食中的成分包括毒素，動物可能需要解毒物質。"},{"en":"The phrase focuses on substances inside the food eaten.","zh":"這個短語強調所吃食物內的物質。"}],"source":"151 - Health in the Wild.pdf","sourcePage":19},{"front":"be found among humans","meaning":"亦見於人類之中","examples":[{"en":"Geophagy can also be found among humans.","zh":"食土行為亦見於人類之中。"},{"en":"To be found among humans means to exist or appear in human behaviour or society.","zh":"“Be found among humans” 指存在或出現於人類行為或社會中。"},{"en":"Tool use is not only found among humans; some animals use tools too.","zh":"工具使用不只見於人類之中；一些動物也使用工具。"},{"en":"If geophagy is found among humans, it may be both cultural and medical.","zh":"如果食土行為見於人類之中，它可能同時具文化和醫療意義。"},{"en":"The phrase connects an observed behaviour with people.","zh":"這個短語把觀察到的行為與人類連繫起來。"}],"source":"151 - Health in the Wild.pdf","sourcePage":19},{"front":"purchase clay tablets","meaning":"購買黏土片","examples":[{"en":"People purchase clay tablets at market stalls.","zh":"人們在市集攤檔購買黏土片。"},{"en":"To purchase clay tablets means to buy small tablets made of clay.","zh":"“Purchase clay tablets” 指購買由黏土製成的小片劑。"},{"en":"A patient may purchase clay tablets if they believe the tablets help stomach problems.","zh":"如果病人相信黏土片有助胃部問題，可能會購買黏土片。"},{"en":"If people regularly purchase clay tablets, the product may be part of local medicine.","zh":"如果人們定期購買黏土片，該產品可能是本地醫藥的一部分。"},{"en":"The phrase is a formal way to say “buy clay tablets”.","zh":"這個短語是 “buy clay tablets” 的正式說法。"}],"source":"151 - Health in the Wild.pdf","sourcePage":19},{"front":"at market stalls","meaning":"在市集攤檔","examples":[{"en":"Clay tablets are sold at market stalls.","zh":"黏土片在市集攤檔出售。"},{"en":"At market stalls means at small selling places in a market.","zh":"“At market stalls” 指在市場中的小型售賣攤位。"},{"en":"Tourists may buy fruit, snacks, and handmade goods at market stalls.","zh":"遊客可能在市集攤檔購買水果、小食和手工藝品。"},{"en":"If medicine is sold at market stalls, buyers may ask sellers how to use it.","zh":"如果藥物在市集攤檔出售，買家可能詢問賣家如何使用。"},{"en":"The phrase describes a simple public shopping location.","zh":"這個短語描述簡單的公共購物地點。"}],"source":"151 - Health in the Wild.pdf","sourcePage":20},{"front":"as a kind of medication","meaning":"作為一種藥物","examples":[{"en":"People use clay tablets as a kind of medication.","zh":"人們把黏土片作為一種藥物使用。"},{"en":"As a kind of medication means used as a treatment for a health problem.","zh":"“As a kind of medication” 指作為治療健康問題的方法使用。"},{"en":"Honey is sometimes used as a kind of medication for a sore throat.","zh":"蜂蜜有時被用作治療喉嚨痛的一種藥物。"},{"en":"If clay tablets are used as a kind of medication, people believe they have healing effects.","zh":"如果黏土片被作為一種藥物使用，人們相信它們有治療作用。"},{"en":"The phrase shows that something is treated like medicine.","zh":"這個短語顯示某物被當作藥物。"}],"source":"151 - Health in the Wild.pdf","sourcePage":20},{"front":"for their illnesses","meaning":"用於治療疾病","examples":[{"en":"People buy clay tablets for their illnesses.","zh":"人們購買黏土片用於治療疾病。"},{"en":"For their illnesses means in order to treat or relieve their health problems.","zh":"“For their illnesses” 指為了治療或紓緩他們的健康問題。"},{"en":"Patients may take medicine for their illnesses after seeing a doctor.","zh":"病人看醫生後可能服藥治療疾病。"},{"en":"If people buy traditional remedies for their illnesses, they believe those remedies can help.","zh":"如果人們購買傳統療法用於治療疾病，他們相信那些療法有幫助。"},{"en":"The phrase shows the health reason for an action.","zh":"這個短語顯示行動背後的健康原因。"}],"source":"151 - Health in the Wild.pdf","sourcePage":20},{"front":"another example of this","meaning":"另一個例子","examples":[{"en":"Another example of this is found in chimps eating leaves.","zh":"另一個例子見於黑猩猩吃葉子。"},{"en":"Another example of this means one more case showing the same idea.","zh":"“Another example of this” 指另一個展示同一想法的案例。"},{"en":"Another example of this is students learning better when examples are concrete.","zh":"另一個例子是例子具體時，學生學得更好。"},{"en":"If clay eating shows self-medication, another example of this may be leaf swallowing.","zh":"如果吃黏土顯示自我用藥，另一個例子可能是吞葉子。"},{"en":"The phrase helps add supporting evidence.","zh":"這個短語有助加入支持證據。"}],"source":"151 - Health in the Wild.pdf","sourcePage":20},{"front":"unpleasant taste","meaning":"令人不快的味道","examples":[{"en":"The leaves appear to have an unpleasant taste.","zh":"這些葉子似乎有令人不快的味道。"},{"en":"An unpleasant taste is a taste that is bitter, bad, or difficult to accept.","zh":"令人不快的味道是苦、難吃或難以接受的味道。"},{"en":"Some medicines have an unpleasant taste, so children dislike taking them.","zh":"一些藥物有令人不快的味道，所以孩子不喜歡服用。"},{"en":"If chimps wrinkle their noses, the leaves may have an unpleasant taste.","zh":"如果黑猩猩皺鼻，這些葉子可能有令人不快的味道。"},{"en":"The phrase describes taste that people or animals do not enjoy.","zh":"這個短語描述人或動物不喜歡的味道。"}],"source":"151 - Health in the Wild.pdf","sourcePage":20},{"front":"apparent medicinal value","meaning":"明顯藥用價值","examples":[{"en":"The leaves seemed to have no apparent medicinal value.","zh":"這些葉子似乎沒有明顯藥用價值。"},{"en":"Apparent medicinal value means an obvious health or treatment benefit that can be seen or identified.","zh":"明顯藥用價值指可以看見或辨認出的明顯健康或治療好處。"},{"en":"A plant may have no apparent medicinal value until scientists test it carefully.","zh":"一種植物在科學家仔細測試前，可能沒有明顯藥用價值。"},{"en":"If leaves contain no useful chemicals, they may seem to lack apparent medicinal value.","zh":"如果葉子不含有用化學物質，它們可能看起來缺乏明顯藥用價值。"},{"en":"The phrase focuses on what appears to be medically useful.","zh":"這個短語強調表面上看來有醫療用途的地方。"}],"source":"151 - Health in the Wild.pdf","sourcePage":20},{"front":"come to light","meaning":"被揭示；曝光","examples":[{"en":"The leaves’ unique structure came to light later.","zh":"這些葉子的獨特結構後來被揭示。"},{"en":"To come to light means to become known or be discovered after being hidden or unnoticed.","zh":"“Come to light” 指在隱藏或未被注意後變得為人所知或被發現。"},{"en":"New evidence came to light after the files were checked again.","zh":"文件再次檢查後，新證據被揭示。"},{"en":"If the leaf structure came to light later, earlier researchers may have missed the real mechanism.","zh":"如果葉子的結構後來才被揭示，早期研究人員可能錯過真正機制。"},{"en":"The phrase is common in research and investigations.","zh":"這個短語常見於研究和調查。"}],"source":"151 - Health in the Wild.pdf","sourcePage":20},{"front":"unique structure","meaning":"獨特結構","examples":[{"en":"The leaves’ unique structure explained their medicinal effect.","zh":"這些葉子的獨特結構解釋了其醫療作用。"},{"en":"A unique structure is a special physical form or arrangement that is different from others.","zh":"獨特結構是與其他事物不同的特殊物理形態或排列。"},{"en":"A honeycomb has a unique structure that makes it strong and light.","zh":"蜂巢有獨特結構，使它既堅固又輕。"},{"en":"If leaves have a unique structure with tiny hooks, they may remove worms mechanically.","zh":"如果葉子有帶微小鈎狀物的獨特結構，它們可能以機械方式移除蟲。"},{"en":"The phrase connects shape or design with function.","zh":"這個短語把形狀或設計與功能連繫起來。"}],"source":"151 - Health in the Wild.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 152":[{"front":"ancient storytelling","meaning":"古代說故事","examples":[{"en":"Ancient storytelling probably began with people gathered around a fire.","zh":"古代說故事很可能始於人們圍在火堆旁。"},{"en":"Ancient storytelling means the way people in early societies shared stories before modern books or screens existed.","zh":"古代說故事指早期社會的人在現代書本或螢幕出現前分享故事的方式。"},{"en":"Ancient storytelling helped families teach children about danger, courage, and community rules.","zh":"古代說故事幫助家庭教孩子認識危險、勇氣和社群規則。"},{"en":"Because few people could write, ancient storytelling preserved memories through spoken words.","zh":"因為很少人能書寫，古代說故事透過口語保存記憶。"},{"en":"Ancient storytelling shows that humans have always used stories to understand life.","zh":"古代說故事顯示人類一直用故事理解生活。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":1},{"front":"it was told","meaning":"它被講述","examples":[{"en":"The tale was told to people crouched around a fire.","zh":"這個故事被講述給蹲坐在火堆旁的人聽。"},{"en":"It was told means the story was spoken or narrated to an audience.","zh":"it was told 指故事被說出或講述給聽眾聽。"},{"en":"The bedtime story was told slowly so the child could follow every detail.","zh":"睡前故事被慢慢講述，好讓孩子跟得上每個細節。"},{"en":"If a warning story was told often, people remembered the danger more clearly.","zh":"如果警示故事經常被講述，人們會更清楚記住危險。"},{"en":"A story can change slightly each time it is told by a different person.","zh":"一個故事每次由不同人講述時，都可能稍有改變。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":1},{"front":"crouched around a fire","meaning":"蹲坐在火堆旁","examples":[{"en":"Listeners crouched around a fire to hear the story.","zh":"聽眾蹲坐在火堆旁聽故事。"},{"en":"Crouched around a fire means people bent low or squatted close to a fire for warmth or light.","zh":"crouched around a fire 指人們彎低身或蹲在火堆附近取暖或借光。"},{"en":"Campers crouched around a fire while cooking noodles on a cold night.","zh":"露營者在寒冷夜晚蹲坐在火堆旁煮麵。"},{"en":"People may crouch around a fire when they need heat, safety, and a place to gather.","zh":"當人們需要熱力、安全感和聚集地方時，可能會蹲坐在火堆旁。"},{"en":"The phrase creates an image of people listening closely in a simple outdoor setting.","zh":"這個片語營造出人們在簡單戶外環境中專心聆聽的畫面。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":1},{"front":"a tale of adventure","meaning":"冒險故事","examples":[{"en":"The first fireside story may have been a tale of adventure.","zh":"第一個爐邊故事可能是一個冒險故事。"},{"en":"A tale of adventure is a story about exciting journeys, dangers, or brave actions.","zh":"a tale of adventure 是關於刺激旅程、危險或勇敢行動的故事。"},{"en":"A child may enjoy a tale of adventure about sailors crossing a stormy sea.","zh":"孩子可能喜歡一個關於水手穿越暴風海面的冒險故事。"},{"en":"A tale of adventure keeps listeners interested because they want to know whether the hero survives.","zh":"冒險故事令聽眾保持興趣，因為他們想知道英雄能否生還。"},{"en":"This phrase is often used for stories with risk, movement, and discovery.","zh":"這個片語常用於有風險、行動和發現的故事。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":1},{"front":"most likely","meaning":"很可能","examples":[{"en":"The tale most likely related a close encounter with death.","zh":"這個故事很可能講述了一次與死亡擦身而過的經歷。"},{"en":"Most likely means probably or with the greatest chance of being true.","zh":"most likely 指大概、很可能或最有機會是真的。"},{"en":"If the sky is dark and windy, it will most likely rain soon.","zh":"如果天空又黑又大風，很可能很快下雨。"},{"en":"A student who practises every day will most likely improve faster than one who rarely studies.","zh":"每天練習的學生很可能比很少學習的學生進步更快。"},{"en":"We use most likely when we are not completely certain but the evidence points one way.","zh":"當我們不是完全肯定，但證據指向某個方向時，會使用 most likely。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":1},{"front":"relate an encounter","meaning":"講述一次遭遇","examples":[{"en":"The story related an encounter with danger.","zh":"這個故事講述了一次與危險的遭遇。"},{"en":"To relate an encounter means to describe an experience of meeting or facing someone or something.","zh":"relate an encounter 指描述一次遇見或面對某人或某事的經歷。"},{"en":"A traveller may relate an encounter with a helpful stranger at a train station.","zh":"旅客可能講述一次在火車站遇到熱心陌生人的遭遇。"},{"en":"When people relate an encounter clearly, listeners can imagine what happened.","zh":"當人們清楚講述一次遭遇，聽眾就能想像發生了甚麼。"},{"en":"This phrase is more formal than simply saying tell about a meeting.","zh":"這個片語比簡單說 tell about a meeting 更正式。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":1},{"front":"close encounter with death","meaning":"與死亡擦身而過的經歷","examples":[{"en":"The tale may have described a close encounter with death.","zh":"這個故事可能描述了一次與死亡擦身而過的經歷。"},{"en":"A close encounter with death is an experience in which someone nearly dies.","zh":"close encounter with death 是指某人幾乎死亡的經歷。"},{"en":"A cyclist may have a close encounter with death if a truck nearly hits him.","zh":"如果貨車差點撞到單車手，他可能經歷了一次與死亡擦身而過。"},{"en":"Such an experience can change a person because it shows how fragile life is.","zh":"這種經歷可以改變一個人，因為它顯示生命多麼脆弱。"},{"en":"This phrase is used for serious danger, not ordinary fear.","zh":"這個片語用於嚴重危險，而不是普通害怕。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":1},{"front":"a remarkable hunt","meaning":"一次非凡的狩獵","examples":[{"en":"The story may have told of a remarkable hunt.","zh":"這個故事可能講述了一次非凡的狩獵。"},{"en":"A remarkable hunt is an unusually impressive or memorable search for an animal or target.","zh":"a remarkable hunt 指一次異常令人印象深刻或難忘的狩獵。"},{"en":"The villagers still talk about a remarkable hunt that saved them from a dangerous animal.","zh":"村民仍談論那次救他們避開危險動物的非凡狩獵。"},{"en":"A hunt becomes remarkable when it is difficult, risky, or successful in an unexpected way.","zh":"當狩獵困難、危險或以意想不到的方式成功時，它就變得非凡。"},{"en":"This phrase suggests that the event was special enough to become a story.","zh":"這個片語暗示事件特別得足以成為故事。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":1},{"front":"escape from mortal danger","meaning":"逃離致命危險","examples":[{"en":"The tale may have described an escape from mortal danger.","zh":"這個故事可能描述了逃離致命危險的經歷。"},{"en":"An escape from mortal danger means getting away from a situation that could cause death.","zh":"escape from mortal danger 指逃離可能導致死亡的情況。"},{"en":"A family trapped in a burning building may make an escape from mortal danger through a window.","zh":"被困在着火建築物中的家庭，可能透過窗戶逃離致命危險。"},{"en":"Such an escape often becomes unforgettable because the risk is so serious.","zh":"這種逃脫往往令人難忘，因為風險非常嚴重。"},{"en":"This phrase is dramatic and suitable for life-threatening situations.","zh":"這個片語具戲劇性，適合用於危及生命的情況。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":1},{"front":"out of the ordinary","meaning":"不尋常的","examples":[{"en":"The story probably described something out of the ordinary.","zh":"這個故事很可能描述了某件不尋常的事情。"},{"en":"Out of the ordinary means unusual or different from normal daily life.","zh":"out of the ordinary 指不尋常，或與正常日常生活不同。"},{"en":"Seeing a deer in the middle of a busy street would be out of the ordinary.","zh":"在繁忙街道中央看見一隻鹿會是不尋常的事。"},{"en":"Events that are out of the ordinary are easier to remember and retell.","zh":"不尋常的事件較容易被記住和重述。"},{"en":"The phrase can describe something strange, special, surprising, or rare.","zh":"這個片語可以描述奇怪、特別、令人驚訝或罕見的事。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":1},{"front":"whatever its thread","meaning":"不論故事脈絡如何","examples":[{"en":"Whatever its thread, the story had a prime purpose.","zh":"不論故事脈絡如何，這個故事都有一個主要目的。"},{"en":"Whatever its thread means no matter what the main line or direction of the story was.","zh":"whatever its thread 指不論故事的主線或方向是甚麼。"},{"en":"Whatever its thread, a good speech should still have a clear message.","zh":"不論演講脈絡如何，一個好演講仍應有清晰訊息。"},{"en":"A conversation may wander, but whatever its thread, people usually follow one central idea.","zh":"對話可能會岔開，但不論其脈絡如何，人們通常會跟隨一個中心概念。"},{"en":"This phrase is literary and refers to the path that holds a story together.","zh":"這個片語較文學化，指把故事連繫起來的路徑。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":1},{"front":"the weaving of this story","meaning":"這個故事的編織","examples":[{"en":"The weaving of this story was done with a clear purpose.","zh":"這個故事的編織是帶着清楚目的完成的。"},{"en":"The weaving of this story means the way different details were joined together to form the story.","zh":"the weaving of this story 指不同細節如何被連接起來形成故事。"},{"en":"A teacher’s lesson can feel like the weaving of a story when examples connect smoothly.","zh":"當例子順暢連接時，老師的課堂可以像一個故事的編織。"},{"en":"If the weaving of a story is weak, the audience may not understand how events connect.","zh":"如果故事的編織薄弱，觀眾可能不明白事件如何連接。"},{"en":"This phrase compares storytelling to making cloth from many threads.","zh":"這個片語把說故事比作由許多線編織布料。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":2},{"front":"prime purpose","meaning":"主要目的","examples":[{"en":"The prime purpose of the story was to keep listeners listening.","zh":"這個故事的主要目的是令聽眾繼續聽下去。"},{"en":"Prime purpose means the main or most important reason for doing something.","zh":"prime purpose 指做某事的主要或最重要原因。"},{"en":"The prime purpose of a fire alarm is to warn people quickly.","zh":"火警鐘的主要目的是快速警告人們。"},{"en":"If a lesson has no prime purpose, students may not know what they should learn.","zh":"如果課堂沒有主要目的，學生可能不知道自己應該學甚麼。"},{"en":"This phrase is useful when one goal is more important than all others.","zh":"當一個目標比其他所有目標更重要時，這個片語很有用。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":2},{"front":"keep someone listening","meaning":"令某人繼續聽下去","examples":[{"en":"A storyteller must keep the listeners listening.","zh":"說故事的人必須令聽眾繼續聽下去。"},{"en":"To keep someone listening means to hold their attention so they continue to hear the story or message.","zh":"keep someone listening 指吸引某人的注意力，讓他繼續聽故事或訊息。"},{"en":"A teacher can keep students listening by using clear examples and short questions.","zh":"老師可以透過清楚例子和短問題令學生繼續聽下去。"},{"en":"If a speaker is too slow or confusing, it becomes hard to keep the audience listening.","zh":"如果演講者太慢或太混亂，就很難令聽眾繼續聽下去。"},{"en":"Good stories keep people listening because they create curiosity.","zh":"好故事能令人繼續聽下去，因為它們製造好奇心。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":2},{"front":"as the story went on","meaning":"隨着故事發展","examples":[{"en":"As the story went on, the audience wanted to know what happened next.","zh":"隨着故事發展，觀眾想知道接下來發生甚麼。"},{"en":"As the story went on means while the story continued and developed.","zh":"as the story went on 指故事繼續和發展的過程中。"},{"en":"As the story went on, the quiet character slowly became braver.","zh":"隨着故事發展，那個安靜的角色慢慢變得更勇敢。"},{"en":"If new problems appear as the story goes on, readers may become more interested.","zh":"如果新問題隨着故事發展而出現，讀者可能變得更感興趣。"},{"en":"This phrase shows change over the course of a story.","zh":"這個片語顯示故事過程中的變化。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":2},{"front":"be sustained by","meaning":"由……支撐着","examples":[{"en":"The audience was sustained by one question above all.","zh":"觀眾由最重要的一個問題支撐着。"},{"en":"To be sustained by something means to be kept going or supported by it.","zh":"be sustained by something 指被某事維持、推動或支撐。"},{"en":"A long project may be sustained by clear goals and regular encouragement.","zh":"一個長期項目可能由清晰目標和定期鼓勵支撐着。"},{"en":"A tired student can be sustained by the hope of passing an important exam.","zh":"疲倦的學生可以由通過重要考試的希望支撐着。"},{"en":"In storytelling, curiosity often sustains the audience’s attention.","zh":"在說故事中，好奇心常常支撐觀眾的注意力。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":2},{"front":"one question above all","meaning":"最重要的一個問題","examples":[{"en":"The audience was sustained by one question above all.","zh":"觀眾由最重要的一個問題支撐着。"},{"en":"One question above all means the single most important question among many possible questions.","zh":"one question above all 指在許多可能問題中最重要的一個問題。"},{"en":"In a mystery story, one question above all may be who committed the crime.","zh":"在推理故事中，最重要的一個問題可能是誰犯案。"},{"en":"During a job interview, one question above all is whether the person can do the work well.","zh":"在求職面試中，最重要的一個問題是那人能否做好工作。"},{"en":"This phrase highlights the central issue that matters most.","zh":"這個片語突出最重要的核心問題。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":2},{"front":"what happens next","meaning":"接下來會發生甚麼","examples":[{"en":"A good story makes the audience ask what happens next.","zh":"好故事會令觀眾問接下來會發生甚麼。"},{"en":"What happens next is the question people ask when they want to know the next event in a story.","zh":"what happens next 是人們想知道故事下一件事時提出的問題。"},{"en":"A television drama keeps viewers watching when every episode makes them wonder what happens next.","zh":"當每集都令人想知道接下來會發生甚麼，電視劇就能令觀眾繼續觀看。"},{"en":"If readers stop caring about what happens next, the story loses power.","zh":"如果讀者不再在乎接下來會發生甚麼，故事就失去力量。"},{"en":"This phrase is central to suspense and curiosity.","zh":"這個片語是懸念和好奇心的核心。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":2},{"front":"fireside stories","meaning":"爐邊故事","examples":[{"en":"The first fireside stories in human history can never be known.","zh":"人類歷史中最早的爐邊故事永遠無法得知。"},{"en":"Fireside stories are stories told near a fire, often in a close and informal setting.","zh":"fireside stories 是在火邊講述的故事，通常發生在親近而非正式的環境中。"},{"en":"Families may share fireside stories during camping trips after dinner.","zh":"家庭露營晚飯後可能分享爐邊故事。"},{"en":"Fireside stories help people feel connected because everyone listens together.","zh":"爐邊故事幫助人們感到連繫，因為大家一起聆聽。"},{"en":"The phrase suggests warmth, memory, and spoken storytelling.","zh":"這個片語暗示溫暖、記憶和口頭說故事。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":2},{"front":"in human history","meaning":"在人類歷史中","examples":[{"en":"The first fireside stories in human history were never written down.","zh":"人類歷史中最早的爐邊故事從未被寫下。"},{"en":"In human history means during the whole past experience of human beings.","zh":"in human history 指在人類整個過去經驗之中。"},{"en":"Writing is one of the most important inventions in human history.","zh":"書寫是人類歷史中最重要的發明之一。"},{"en":"Events in human history are remembered differently by different cultures.","zh":"人類歷史中的事件會被不同文化以不同方式記住。"},{"en":"This phrase gives a topic a very broad time scale.","zh":"這個片語給主題一個非常廣闊的時間尺度。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":2},{"front":"can never be known","meaning":"永遠無法得知","examples":[{"en":"The first fireside stories can never be known.","zh":"最早的爐邊故事永遠無法得知。"},{"en":"Can never be known means there is no possible way to discover the answer with certainty.","zh":"can never be known 指沒有可能確定地發現答案。"},{"en":"The exact words of the first human song can never be known.","zh":"第一首人類歌曲的確切歌詞永遠無法得知。"},{"en":"If no records were kept, some details of the past can never be known.","zh":"如果沒有保存紀錄，過去某些細節可能永遠無法得知。"},{"en":"This phrase is used when evidence has disappeared forever.","zh":"當證據永遠消失時，會使用這個片語。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":2},{"front":"be kept in the heads of","meaning":"被保存在……的腦海中","examples":[{"en":"The stories were kept in the heads of those who told them.","zh":"這些故事被保存在講述者的腦海中。"},{"en":"To be kept in the heads of people means to be remembered instead of written down.","zh":"be kept in the heads of people 指被記住，而不是被寫下。"},{"en":"Before phones, many people kept important numbers in their heads.","zh":"在電話出現前，許多人把重要號碼保存在腦海中。"},{"en":"If knowledge is kept only in the heads of workers, a company may lose it when they leave.","zh":"如果知識只保存在員工腦海中，公司可能在他們離職時失去它。"},{"en":"This phrase shows that memory can act like storage.","zh":"這個片語顯示記憶可以像儲存工具一樣運作。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":2},{"front":"method of storage","meaning":"儲存方法","examples":[{"en":"Memory was an early method of storage for stories.","zh":"記憶是故事早期的一種儲存方法。"},{"en":"A method of storage is a way of keeping information, objects, or materials for later use.","zh":"method of storage 指保存資料、物件或材料以供日後使用的方法。"},{"en":"A notebook is a simple method of storage for homework reminders.","zh":"筆記本是儲存功課提示的簡單方法。"},{"en":"If a method of storage is unreliable, important information may be lost.","zh":"如果儲存方法不可靠，重要資料可能會遺失。"},{"en":"Modern methods of storage include computers, cloud drives, and paper files.","zh":"現代儲存方法包括電腦、雲端硬碟和紙本檔案。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":3},{"front":"not necessarily inefficient","meaning":"不一定低效","examples":[{"en":"This method of storage is not necessarily inefficient.","zh":"這種儲存方法不一定低效。"},{"en":"Not necessarily inefficient means something may work better than people expect.","zh":"not necessarily inefficient 指某事物可能比人們預期更有效。"},{"en":"Writing notes by hand is not necessarily inefficient because it can help memory.","zh":"手寫筆記不一定低效，因為它可以幫助記憶。"},{"en":"A small shop is not necessarily inefficient if it serves customers quickly and personally.","zh":"如果小店能快速並親切地服務顧客，它不一定低效。"},{"en":"This phrase challenges the assumption that an old or simple method is always poor.","zh":"這個片語挑戰舊方法或簡單方法一定差的假設。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":3},{"front":"documented oral traditions","meaning":"有文獻記錄的口述傳統","examples":[{"en":"Documented oral traditions show the power of memory.","zh":"有文獻記錄的口述傳統顯示記憶的力量。"},{"en":"Documented oral traditions are spoken storytelling practices that have been recorded or studied.","zh":"documented oral traditions 是已被記錄或研究的口頭說故事做法。"},{"en":"Researchers may study documented oral traditions to understand how communities preserve history.","zh":"研究人員可能研究有文獻記錄的口述傳統，以理解社群如何保存歷史。"},{"en":"Documented oral traditions prove that spoken stories can survive for a long time.","zh":"有文獻記錄的口述傳統證明口頭故事可以保存很久。"},{"en":"This phrase connects oral memory with written evidence.","zh":"這個片語把口頭記憶與文字證據連繫起來。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":3},{"front":"oral traditions","meaning":"口述傳統","examples":[{"en":"Oral traditions preserve stories without writing.","zh":"口述傳統在沒有文字的情況下保存故事。"},{"en":"Oral traditions are customs of passing stories, songs, history, or knowledge by speech.","zh":"oral traditions 是透過說話傳遞故事、歌曲、歷史或知識的習俗。"},{"en":"Grandparents may pass family history through oral traditions at festivals or dinners.","zh":"祖父母可能在節日或晚餐中透過口述傳統傳遞家族歷史。"},{"en":"If oral traditions are not practised, important local memories may disappear.","zh":"如果口述傳統沒有被實踐，重要本地記憶可能消失。"},{"en":"Oral traditions depend on listening, repetition, and community memory.","zh":"口述傳統依賴聆聽、重複和社群記憶。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":3},{"front":"specialised storytellers","meaning":"專門說故事的人","examples":[{"en":"Specialised storytellers can recite long stories from memory.","zh":"專門說故事的人可以憑記憶背誦長故事。"},{"en":"Specialised storytellers are people trained or skilled in telling stories as a special role.","zh":"specialised storytellers 是受訓或擅長以特殊角色講故事的人。"},{"en":"A village may invite specialised storytellers to perform during festivals.","zh":"村莊可能邀請專門說故事的人在節日表演。"},{"en":"Because they practise often, specialised storytellers can remember details ordinary listeners forget.","zh":"因為他們經常練習，專門說故事的人可以記住普通聽眾忘記的細節。"},{"en":"This phrase suggests storytelling is a skill, not just casual speaking.","zh":"這個片語暗示說故事是一種技能，而不只是隨意說話。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":3},{"front":"recite from memory","meaning":"憑記憶背誦","examples":[{"en":"Poets can recite thousands of lines from memory.","zh":"詩人可以憑記憶背誦數千行。"},{"en":"To recite from memory means to speak words accurately without reading them.","zh":"recite from memory 指不閱讀文字而準確說出內容。"},{"en":"A student may recite a poem from memory during a school performance.","zh":"學生可能在學校表演中憑記憶背誦一首詩。"},{"en":"Repeated practice helps people recite from memory with fewer mistakes.","zh":"重複練習幫助人們憑記憶背誦時少犯錯。"},{"en":"This phrase is used when the words are stored in the mind.","zh":"當文字被保存在腦海中時，會使用這個片語。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":3},{"front":"literally thousands of lines","meaning":"足足數千行","examples":[{"en":"Some storytellers can recite literally thousands of lines.","zh":"有些說故事的人可以背誦足足數千行。"},{"en":"Literally thousands of lines means truly many thousands of written or spoken lines, not just a vague large number.","zh":"literally thousands of lines 指真正有數千行文字或說話，而不只是籠統表示很多。"},{"en":"An actor in a long play may need to learn literally thousands of lines.","zh":"長劇中的演員可能需要記住足足數千行台詞。"},{"en":"If someone can remember literally thousands of lines, their memory skill is impressive.","zh":"如果有人能記住足足數千行，他的記憶能力令人佩服。"},{"en":"Literally adds emphasis that the number is not only a figure of speech.","zh":"literally 強調這個數量不只是誇張說法。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":3},{"front":"in verse or prose","meaning":"以韻文或散文形式","examples":[{"en":"Stories may be recited in verse or prose.","zh":"故事可以以韻文或散文形式背誦。"},{"en":"In verse or prose means in poetic lines or in ordinary written language.","zh":"in verse or prose 指以詩歌式行文或普通散文語言表達。"},{"en":"A love story can be written in verse or prose depending on the writer’s style.","zh":"愛情故事可以根據作者風格以韻文或散文形式寫成。"},{"en":"Verse may use rhythm and rhyme, while prose usually sounds closer to normal speech.","zh":"韻文可能使用節奏和押韻，而散文通常較接近日常說話。"},{"en":"This phrase contrasts two common forms of literary expression.","zh":"這個片語對比兩種常見文學表達形式。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":3},{"front":"verbatim","meaning":"逐字逐句地","examples":[{"en":"Some oral poets can recite stories verbatim.","zh":"有些口述詩人可以逐字逐句地背誦故事。"},{"en":"Verbatim means using exactly the same words as the original.","zh":"verbatim 指使用與原文完全相同的字詞。"},{"en":"A lawyer may read a witness statement verbatim in court.","zh":"律師可能在法庭上逐字逐句讀出證人陳述。"},{"en":"If students copy an article verbatim, they may be accused of plagiarism.","zh":"如果學生逐字逐句抄寫文章，可能被指抄襲。"},{"en":"This word stresses exact wording, not just the same general meaning.","zh":"這個詞強調確切用字，而不只是相同大意。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":3},{"front":"word for word","meaning":"一字不差地","examples":[{"en":"Verbatim means word for word.","zh":"verbatim 的意思是一字不差地。"},{"en":"Word for word means exactly the same words, in the same order.","zh":"word for word 指完全相同的字詞，而且順序相同。"},{"en":"The child repeated the teacher’s instruction word for word.","zh":"孩子一字不差地重複老師的指示。"},{"en":"Translating word for word can sound strange if the two languages work differently.","zh":"如果兩種語言運作不同，逐字翻譯可能聽起來奇怪。"},{"en":"This phrase is useful when accuracy of wording is important.","zh":"當用字準確很重要時，這個片語很有用。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":3},{"front":"be rightly considered","meaning":"被合理地視為","examples":[{"en":"Memory is rightly considered an art in itself.","zh":"記憶被合理地視為本身就是一門藝術。"},{"en":"To be rightly considered something means to be fairly or correctly regarded in that way.","zh":"be rightly considered something 指被公平或正確地視為某事物。"},{"en":"Good nursing is rightly considered skilled work, not just kindness.","zh":"良好的護理被合理地視為專業工作，而不只是善良。"},{"en":"A clear public transport system is rightly considered essential in a large city.","zh":"清晰的公共交通系統在大城市中被合理地視為必要。"},{"en":"This phrase suggests the judgement is reasonable and deserved.","zh":"這個片語暗示這個判斷合理且應得。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":3},{"front":"an art in itself","meaning":"本身就是一門藝術","examples":[{"en":"Memory can be considered an art in itself.","zh":"記憶可以被視為本身就是一門藝術。"},{"en":"An art in itself means something is a skillful practice worthy of attention on its own.","zh":"an art in itself 指某事本身就是值得關注的技巧性做法。"},{"en":"Good listening is an art in itself because it requires patience and judgement.","zh":"良好聆聽本身就是一門藝術，因為它需要耐性和判斷。"},{"en":"Packing a small suitcase well can feel like an art in itself.","zh":"把小行李箱收拾得好也可以像本身就是一門藝術。"},{"en":"This phrase gives respect to a skill people may overlook.","zh":"這個片語對人們可能忽略的技能表示尊重。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":4},{"front":"primary purpose","meaning":"主要目的","examples":[{"en":"A primary purpose of symbols is to provide reminders.","zh":"符號的一個主要目的是提供提示。"},{"en":"Primary purpose means one of the main reasons for which something exists or is used.","zh":"primary purpose 指某物存在或被使用的主要原因之一。"},{"en":"The primary purpose of a timetable is to show when classes or buses happen.","zh":"時間表的主要目的是顯示課堂或巴士何時進行。"},{"en":"If a tool fails its primary purpose, people may stop using it.","zh":"如果工具未能達到其主要目的，人們可能停止使用它。"},{"en":"This phrase focuses on the most important function.","zh":"這個片語聚焦於最重要的功能。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":4},{"front":"making symbols","meaning":"製造符號","examples":[{"en":"Making symbols helps people remember information.","zh":"製造符號幫助人們記住資料。"},{"en":"Making symbols means creating marks, pictures, or signs to represent ideas.","zh":"making symbols 指創造標記、圖像或符號來代表概念。"},{"en":"A student may practise making symbols in notes to remember grammar rules.","zh":"學生可能在筆記中練習製造符號來記住文法規則。"},{"en":"Making symbols can save time because one mark can stand for a longer message.","zh":"製造符號可以節省時間，因為一個標記可以代表更長訊息。"},{"en":"Humans make symbols when they want information to be easier to recall or share.","zh":"當人類希望資料更容易回想或分享時，就會製造符號。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":4},{"front":"a system of reminders","meaning":"一套提示系統","examples":[{"en":"Symbols can work as a system of reminders.","zh":"符號可以作為一套提示系統。"},{"en":"A system of reminders is an organised set of signs or notes that helps people remember things.","zh":"a system of reminders 是一組有組織的符號或筆記，用來幫助人們記住事情。"},{"en":"A calendar with coloured marks can be a system of reminders for homework and meetings.","zh":"有彩色標記的日曆可以成為功課和會議的一套提示系統。"},{"en":"A system of reminders reduces mistakes because people do not rely only on memory.","zh":"一套提示系統可以減少錯誤，因為人們不只依賴記憶。"},{"en":"This phrase suggests that reminders work together, not separately.","zh":"這個片語暗示提示互相配合，而不是各自獨立。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":4},{"front":"mnemonic cues","meaning":"記憶提示","examples":[{"en":"Mnemonic cues help people recall information.","zh":"記憶提示幫助人們回想資料。"},{"en":"Mnemonic cues are memory aids that help people remember words, facts, or steps.","zh":"mnemonic cues 是幫助人們記住字詞、事實或步驟的記憶輔助。"},{"en":"A rhyme can be a mnemonic cue for remembering the order of planets.","zh":"押韻句可以是記住行星順序的記憶提示。"},{"en":"Mnemonic cues make learning easier because they connect new information to familiar patterns.","zh":"記憶提示令學習更容易，因為它們把新資料連接到熟悉模式。"},{"en":"This phrase is useful in education, memory training, and note-taking.","zh":"這個片語適用於教育、記憶訓練和筆記。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":4},{"front":"assist someone to","meaning":"幫助某人去……","examples":[{"en":"Signs assist us to recall information.","zh":"標誌幫助我們回想資料。"},{"en":"To assist someone to do something means to help them do it.","zh":"assist someone to do something 指幫助某人做某事。"},{"en":"A map can assist visitors to find the correct classroom.","zh":"地圖可以幫助訪客找到正確課室。"},{"en":"Clear instructions assist workers to avoid mistakes during training.","zh":"清楚指示幫助員工在培訓期間避免錯誤。"},{"en":"This phrase is more formal than help someone to.","zh":"這個片語比 help someone to 更正式。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":4},{"front":"recall certain information","meaning":"回想起某些資料","examples":[{"en":"Mnemonic cues help us recall certain information.","zh":"記憶提示幫助我們回想起某些資料。"},{"en":"To recall certain information means to remember particular facts, details, or experiences.","zh":"recall certain information 指記起特定事實、細節或經驗。"},{"en":"A password hint may help a user recall certain information without revealing the password.","zh":"密碼提示可能幫助使用者回想起某些資料，而不直接顯示密碼。"},{"en":"Students use diagrams to recall certain information before exams.","zh":"學生考試前使用圖表回想起某些資料。"},{"en":"This phrase focuses on bringing specific details back into the mind.","zh":"這個片語聚焦於把特定細節帶回腦海。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":4},{"front":"in the mind’s eye","meaning":"在腦海中","examples":[{"en":"Symbols help people recall information in the mind’s eye.","zh":"符號幫助人們在腦海中回想資料。"},{"en":"In the mind’s eye means in imagination or mental vision rather than physical sight.","zh":"in the mind’s eye 指在想像或心中畫面中，而不是用實際眼睛看見。"},{"en":"A good description lets readers see the village in the mind’s eye.","zh":"好描述能讓讀者在腦海中看見那條村莊。"},{"en":"People may picture a childhood home in the mind’s eye even after many years.","zh":"即使多年後，人們仍可能在腦海中想起童年家居。"},{"en":"This phrase describes seeing something internally through memory or imagination.","zh":"這個片語描述透過記憶或想像在內心看見某物。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":4},{"front":"Polynesian communities","meaning":"波利尼西亞社群","examples":[{"en":"Some Polynesian communities used memory sticks for storytelling.","zh":"一些波利尼西亞社群使用記憶棒來說故事。"},{"en":"Polynesian communities are groups of people from Polynesia, a region of islands in the Pacific.","zh":"Polynesian communities 是來自太平洋群島地區波利尼西亞的人群。"},{"en":"Polynesian communities often preserved knowledge through navigation, songs, stories, and family memory.","zh":"波利尼西亞社群常透過航海、歌曲、故事和家族記憶保存知識。"},{"en":"Studying Polynesian communities can show how island societies pass down culture.","zh":"研究波利尼西亞社群可以顯示島嶼社會如何傳承文化。"},{"en":"This phrase refers to particular Pacific cultures, not all island peoples.","zh":"這個片語指特定太平洋文化，而不是所有島民。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":4},{"front":"notched memory stick","meaning":"刻有缺口的記憶棒","examples":[{"en":"A notched memory stick may guide a storyteller through a recitation.","zh":"刻有缺口的記憶棒可能引導說故事的人完成吟誦。"},{"en":"A notched memory stick is a stick with cuts or marks used to help someone remember a sequence.","zh":"notched memory stick 是有刻痕或標記的木棒，用來幫助人記住順序。"},{"en":"A storyteller may touch each notch on a notched memory stick while recalling each part of a tale.","zh":"說故事的人可能在回想故事每一部分時觸摸刻有缺口的記憶棒。"},{"en":"The notches work like reminders, so the speaker does not lose the order.","zh":"這些缺口像提示一樣運作，令講者不會失去順序。"},{"en":"This object shows how physical tools can support memory.","zh":"這件物件顯示實體工具如何支援記憶。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":4},{"front":"guide someone through","meaning":"引導某人完成……","examples":[{"en":"The stick helps guide the storyteller through the story.","zh":"這支木棒幫助引導說故事的人完成故事。"},{"en":"To guide someone through something means to help them move step by step through a process.","zh":"guide someone through something 指逐步幫助某人完成一個過程。"},{"en":"A teacher can guide students through a difficult reading passage.","zh":"老師可以引導學生完成一篇困難閱讀文章。"},{"en":"Clear signs guide passengers through a large airport.","zh":"清晰標誌引導乘客穿過大型機場。"},{"en":"This phrase suggests support from beginning to end.","zh":"這個片語暗示由開始到結束都有支援。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":4},{"front":"successive stages","meaning":"連續階段","examples":[{"en":"The storyteller follows successive stages of recitation.","zh":"說故事的人跟隨吟誦的連續階段。"},{"en":"Successive stages are steps that happen one after another in order.","zh":"successive stages 指按順序一個接一個發生的步驟。"},{"en":"A science experiment has successive stages, such as planning, testing, and recording results.","zh":"科學實驗有連續階段，例如計劃、測試和記錄結果。"},{"en":"If one stage is missed, the successive stages may become confusing.","zh":"如果漏掉一個階段，後面的連續階段可能變得混亂。"},{"en":"This phrase is useful for describing organised processes.","zh":"這個片語適合描述有組織的過程。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":5},{"front":"recitation","meaning":"背誦；吟誦","examples":[{"en":"The memory stick guides the storyteller through recitation.","zh":"記憶棒引導說故事的人完成背誦。"},{"en":"Recitation is the act of saying something aloud from memory or from a prepared text.","zh":"recitation 是憑記憶或按準備好的文字朗聲說出內容的行為。"},{"en":"A student may practise recitation before performing a poem in class.","zh":"學生可能在課堂表演詩歌前練習背誦。"},{"en":"Recitation improves when the speaker knows the order, rhythm, and meaning clearly.","zh":"當講者清楚知道順序、節奏和意思，背誦會改善。"},{"en":"This word is often used for poems, religious texts, speeches, or traditional stories.","zh":"這個詞常用於詩歌、宗教文本、演講或傳統故事。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":5},{"front":"the activity of storytelling","meaning":"說故事這項活動","examples":[{"en":"The activity of storytelling contributed to the invention of writing.","zh":"說故事這項活動促成了文字的發明。"},{"en":"The activity of storytelling means the practice of creating and sharing stories with others.","zh":"the activity of storytelling 指創造並與他人分享故事的做法。"},{"en":"The activity of storytelling can happen in classrooms, homes, theatres, or films.","zh":"說故事這項活動可以發生在課室、家中、劇院或電影中。"},{"en":"Because stories need to be remembered, the activity of storytelling encouraged people to create records.","zh":"因為故事需要被記住，說故事這項活動鼓勵人們創造紀錄。"},{"en":"This phrase treats storytelling as a human practice, not just one single story.","zh":"這個片語把說故事視為人類做法，而不是單一故事。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":5},{"front":"historically resulted in","meaning":"在歷史上導致","examples":[{"en":"Storytelling historically resulted in the development of writing systems.","zh":"說故事在歷史上導致文字系統的發展。"},{"en":"Historically resulted in means caused or helped produce something over the course of history.","zh":"historically resulted in 指在歷史過程中造成或促成某事。"},{"en":"Long-distance trade historically resulted in contact between different languages.","zh":"長途貿易在歷史上導致不同語言之間的接觸。"},{"en":"The need to count goods historically resulted in better record-keeping.","zh":"計算貨物的需要在歷史上導致更好的記錄方式。"},{"en":"This phrase connects a past practice with a later historical outcome.","zh":"這個片語把過去做法與後來的歷史結果連接起來。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":5},{"front":"development of writing systems","meaning":"文字系統的發展","examples":[{"en":"Storytelling may have encouraged the development of writing systems.","zh":"說故事可能鼓勵了文字系統的發展。"},{"en":"Development of writing systems means the gradual creation and improvement of ways to record language.","zh":"development of writing systems 指記錄語言的方法逐漸被創造和改善。"},{"en":"The development of writing systems allowed laws, stories, and trade records to survive.","zh":"文字系統的發展讓法律、故事和貿易記錄得以保存。"},{"en":"When societies became larger, the development of writing systems helped people manage information.","zh":"當社會變大，文字系統的發展幫助人們管理資訊。"},{"en":"This phrase describes a major step in human communication.","zh":"這個片語描述人類溝通中的重大一步。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":5},{"front":"invention of writing systems","meaning":"文字系統的發明","examples":[{"en":"Storytelling may even have led to the invention of writing systems.","zh":"說故事甚至可能導致文字系統的發明。"},{"en":"Invention of writing systems means the creation of organised marks that represent language.","zh":"invention of writing systems 指創造有組織的標記來代表語言。"},{"en":"The invention of writing systems allowed people to store words outside human memory.","zh":"文字系統的發明讓人們把語言儲存在人類記憶之外。"},{"en":"Without the invention of writing systems, many old stories and laws might have disappeared.","zh":"如果沒有文字系統的發明，許多古老故事和法律可能已消失。"},{"en":"This phrase points to the beginning of written communication.","zh":"這個片語指向書面溝通的開始。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":5},{"front":"one theory about","meaning":"關於……的一種理論","examples":[{"en":"One theory about literacy in Greece concerns epic tales.","zh":"關於希臘文字讀寫能力的一種理論涉及史詩故事。"},{"en":"One theory about something is one possible explanation, not the only accepted answer.","zh":"one theory about something 是對某事的一種可能解釋，而不是唯一被接受的答案。"},{"en":"One theory about why students forget words is that they do not use them often enough.","zh":"關於學生為何忘記詞語的一種理論是他們使用得不夠頻繁。"},{"en":"When evidence is incomplete, researchers may offer one theory about what happened.","zh":"當證據不完整時，研究人員可能提出關於發生了甚麼的一種理論。"},{"en":"This phrase is useful when presenting an idea that may be debated.","zh":"當呈現可能有爭議的想法時，這個片語很有用。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":5},{"front":"arrival of literacy","meaning":"文字讀寫能力的出現","examples":[{"en":"The arrival of literacy in ancient Greece may be linked to storytelling.","zh":"古希臘文字讀寫能力的出現可能與說故事有關。"},{"en":"The arrival of literacy means the point when reading and writing became present or important in a society.","zh":"arrival of literacy 指閱讀和書寫在一個社會中出現或變得重要的時刻。"},{"en":"The arrival of literacy changed how people kept records, taught children, and shared laws.","zh":"文字讀寫能力的出現改變了人們保存紀錄、教育孩子和分享法律的方式。"},{"en":"When literacy arrived, stories no longer had to depend only on memory.","zh":"當文字讀寫能力出現，故事不再只依賴記憶。"},{"en":"This phrase describes a cultural change, not a physical arrival.","zh":"這個片語描述文化變化，而不是實體到達。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":5},{"front":"ancient Greece","meaning":"古希臘","examples":[{"en":"Epic stories were important in ancient Greece.","zh":"史詩故事在古希臘很重要。"},{"en":"Ancient Greece refers to the Greek-speaking world of the past, especially its early city-states and culture.","zh":"ancient Greece 指過去的希臘語世界，尤其是早期城邦和文化。"},{"en":"Students study ancient Greece to learn about philosophy, theatre, politics, and mythology.","zh":"學生研究古希臘，以學習哲學、戲劇、政治和神話。"},{"en":"Ancient Greece influenced later European ideas about art, drama, and government.","zh":"古希臘影響了後來歐洲關於藝術、戲劇和政府的思想。"},{"en":"This phrase places events in a specific historical civilisation.","zh":"這個片語把事件放在特定歷史文明中。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":5},{"front":"epic tales","meaning":"史詩故事","examples":[{"en":"The epic tales about the Trojan War were traditionally attributed to Homer.","zh":"關於特洛伊戰爭的史詩故事傳統上被歸於荷馬。"},{"en":"Epic tales are long, grand stories about heroes, journeys, wars, or the fate of a people.","zh":"epic tales 是關於英雄、旅程、戰爭或民族命運的長篇宏大故事。"},{"en":"A culture may use epic tales to teach courage, loyalty, and suffering.","zh":"一種文化可能使用史詩故事來教導勇氣、忠誠和苦難。"},{"en":"Epic tales are memorable because they combine large events with personal emotion.","zh":"史詩故事令人難忘，因為它們結合大型事件與個人情感。"},{"en":"This phrase suggests stories of great scale and importance.","zh":"這個片語暗示規模和重要性很大的故事。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":5},{"front":"the Trojan War","meaning":"特洛伊戰爭","examples":[{"en":"The epic tales told stories about the Trojan War.","zh":"這些史詩故事講述了特洛伊戰爭。"},{"en":"The Trojan War is a famous legendary war between the Greeks and the city of Troy.","zh":"the Trojan War 是希臘人與特洛伊城之間一場著名傳說戰爭。"},{"en":"Students often meet the Trojan War through stories about Achilles, Hector, and Odysseus.","zh":"學生常透過阿基里斯、赫克托耳和奧德修斯的故事認識特洛伊戰爭。"},{"en":"The Trojan War became important because poets used it to explore honour, anger, and loss.","zh":"特洛伊戰爭變得重要，因為詩人用它探索榮譽、憤怒和失去。"},{"en":"This phrase refers to a central subject of Greek epic storytelling.","zh":"這個片語指希臘史詩敘事的核心題材。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":5},{"front":"the wanderings of Odysseus","meaning":"奧德修斯的漂泊旅程","examples":[{"en":"The Greeks preserved stories about the wanderings of Odysseus.","zh":"希臘人保存了關於奧德修斯漂泊旅程的故事。"},{"en":"The wanderings of Odysseus are the long journeys and adventures of Odysseus after the Trojan War.","zh":"the wanderings of Odysseus 指奧德修斯在特洛伊戰爭後的長途旅程和冒險。"},{"en":"A teacher may use the wanderings of Odysseus to explain the idea of a difficult homeward journey.","zh":"老師可能用奧德修斯的漂泊旅程解釋艱難歸家旅程的概念。"},{"en":"These wanderings are exciting because each stop brings a new danger or test.","zh":"這些漂泊旅程令人興奮，因為每一站都帶來新的危險或考驗。"},{"en":"This phrase connects travel, hardship, and heroic storytelling.","zh":"這個片語連接旅行、困難和英雄敘事。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":6},{"front":"traditionally attributed to","meaning":"傳統上被歸於……","examples":[{"en":"The tales were traditionally attributed to Homer.","zh":"這些故事傳統上被歸於荷馬。"},{"en":"Traditionally attributed to means people have long believed that a work was created by a particular person.","zh":"traditionally attributed to 指人們長久以來相信某作品由某人創作。"},{"en":"Some old songs are traditionally attributed to unknown village singers.","zh":"一些古老歌曲傳統上被歸於不知名的村莊歌手。"},{"en":"A story may be traditionally attributed to one writer even if scholars debate the evidence.","zh":"即使學者爭論證據，一個故事仍可能傳統上被歸於某位作家。"},{"en":"This phrase is useful when authorship comes from tradition rather than certainty.","zh":"當作者身份來自傳統而非確定證據時，這個片語很有用。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":6},{"front":"enchanting to hear","meaning":"聽起來迷人","examples":[{"en":"The stories were so enchanting to hear that they had to be preserved.","zh":"這些故事聽起來如此迷人，以致必須被保存下來。"},{"en":"Enchanting to hear means very pleasant, magical, or beautiful to listen to.","zh":"enchanting to hear 指聽起來非常愉快、有魔力或美麗。"},{"en":"A grandmother’s old folk songs may be enchanting to hear on a quiet evening.","zh":"在安靜夜晚，祖母的古老民歌可能聽起來迷人。"},{"en":"If a story is enchanting to hear, people want to remember and repeat it.","zh":"如果故事聽起來迷人，人們會想記住和重複它。"},{"en":"This phrase describes the strong charm of spoken sound.","zh":"這個片語描述口頭聲音的強烈魅力。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":6},{"front":"have to be preserved","meaning":"必須被保存下來","examples":[{"en":"The epic tales had to be preserved.","zh":"這些史詩故事必須被保存下來。"},{"en":"If something has to be preserved, it must be protected from being lost, damaged, or forgotten.","zh":"如果某物 has to be preserved，意思是它必須被保護，避免遺失、損壞或被遺忘。"},{"en":"Old family photos have to be preserved if future generations are to know their history.","zh":"如果未來世代要知道家族歷史，舊家庭相片必須被保存下來。"},{"en":"Languages have to be preserved when fewer young people speak them.","zh":"當說某種語言的年輕人變少，該語言必須被保存下來。"},{"en":"This phrase shows that protection is necessary, not optional.","zh":"這個片語顯示保護是必要的，而不是可有可無。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":6},{"front":"borrow an alphabet from","meaning":"從……借用字母系統","examples":[{"en":"The Greeks borrowed an alphabet from the Phoenicians.","zh":"希臘人從腓尼基人借用了字母系統。"},{"en":"To borrow an alphabet from another people means to adopt their writing symbols and adapt them for one’s own language.","zh":"borrow an alphabet from another people 指採用對方的書寫符號，並改造給自己的語言使用。"},{"en":"A society may borrow an alphabet from neighbours when trade makes written records useful.","zh":"當貿易令書面紀錄有用時，一個社會可能從鄰族借用字母系統。"},{"en":"Borrowing an alphabet can speed up literacy because people do not need to invent every symbol from nothing.","zh":"借用字母系統可以加快文字讀寫發展，因為人們不用從零發明每個符號。"},{"en":"This phrase refers to cultural borrowing, not a temporary loan.","zh":"這個片語指文化借用，而不是暫時借走。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":6},{"front":"neighbours in the eastern Mediterranean","meaning":"東地中海一帶的鄰近民族","examples":[{"en":"The Phoenicians were neighbours in the eastern Mediterranean.","zh":"腓尼基人是東地中海一帶的鄰近民族。"},{"en":"Neighbours in the eastern Mediterranean means peoples or societies living near one another in the eastern part of the Mediterranean region.","zh":"neighbours in the eastern Mediterranean 指生活在地中海東部彼此附近的民族或社會。"},{"en":"Ancient traders met neighbours in the eastern Mediterranean through ports and sea routes.","zh":"古代商人透過港口和海路接觸東地中海一帶的鄰近民族。"},{"en":"Close contact with neighbours in the eastern Mediterranean allowed ideas and goods to spread.","zh":"與東地中海一帶的鄰近民族密切接觸，讓思想和貨物傳播。"},{"en":"This phrase gives a geographical setting for cultural exchange.","zh":"這個片語為文化交流提供地理背景。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":6},{"front":"the Phoenicians","meaning":"腓尼基人","examples":[{"en":"The Greeks borrowed an alphabet from the Phoenicians.","zh":"希臘人從腓尼基人借用了字母系統。"},{"en":"The Phoenicians were an ancient people known for trade, seafaring, and an influential alphabet.","zh":"the Phoenicians 是一個以貿易、航海和有影響力字母系統聞名的古代民族。"},{"en":"The Phoenicians travelled by sea and connected many communities around the Mediterranean.","zh":"腓尼基人透過海路旅行，連接地中海周邊許多社群。"},{"en":"Their alphabet mattered because other societies adapted it for their own languages.","zh":"他們的字母系統重要，因為其他社會把它改造給自己的語言使用。"},{"en":"This phrase refers to a historical people from the eastern Mediterranean.","zh":"這個片語指來自東地中海的歷史民族。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":6},{"front":"custom of recording stories","meaning":"記錄故事的習俗","examples":[{"en":"The custom of recording stories can be traced around the world.","zh":"記錄故事的習俗可以在世界各地追溯到。"},{"en":"The custom of recording stories means the habit of writing, carving, or marking stories so they last.","zh":"custom of recording stories 指把故事寫下、刻下或標記下來以保存的習慣。"},{"en":"A community may develop the custom of recording stories to preserve ancestors’ experiences.","zh":"社群可能發展記錄故事的習俗，以保存祖先的經歷。"},{"en":"This custom protects stories from being forgotten when storytellers die.","zh":"當說故事的人去世，這個習俗保護故事不被遺忘。"},{"en":"The phrase describes a repeated cultural practice, not one single act.","zh":"這個片語描述重複的文化做法，而不是單一行為。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":6},{"front":"parchment","meaning":"羊皮紙","examples":[{"en":"Stories were recorded on parchment and other materials.","zh":"故事被記錄在羊皮紙和其他材料上。"},{"en":"Parchment is a writing material traditionally made from prepared animal skin.","zh":"parchment 是傳統上由處理過的動物皮製成的書寫材料。"},{"en":"Before paper became common, important documents were often written on parchment.","zh":"在紙張普及前，重要文件常寫在羊皮紙上。"},{"en":"Parchment could preserve texts for a long time if kept dry and safe.","zh":"如果保持乾燥和安全，羊皮紙可以長時間保存文本。"},{"en":"This word refers to a physical surface used for writing.","zh":"這個詞指用於書寫的實體表面。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":6},{"front":"be traced in","meaning":"可在……中追溯到","examples":[{"en":"The custom can be traced in many manifestations around the world.","zh":"這種習俗可在世界各地多種表現形式中追溯到。"},{"en":"To be traced in something means to be found or followed through evidence in that thing.","zh":"be traced in something 指可以透過某物中的證據找到或追蹤。"},{"en":"The history of a family can be traced in letters, photos, and old addresses.","zh":"一個家族的歷史可以在信件、照片和舊地址中追溯到。"},{"en":"A city’s growth can be traced in maps from different periods.","zh":"城市的發展可以在不同時期的地圖中追溯到。"},{"en":"This phrase is useful when evidence shows where something appeared.","zh":"當證據顯示某事在哪裡出現時，這個片語很有用。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":6},{"front":"many manifestations","meaning":"多種表現形式","examples":[{"en":"The practice appeared in many manifestations around the world.","zh":"這種做法在世界各地以多種表現形式出現。"},{"en":"Many manifestations means many different forms or examples of the same basic idea.","zh":"many manifestations 指同一基本概念的許多不同形式或例子。"},{"en":"Kindness has many manifestations, such as helping a classmate or visiting an elderly neighbour.","zh":"善意有多種表現形式，例如幫助同學或探望年老鄰居。"},{"en":"A tradition may survive in many manifestations, including songs, food, clothing, and festivals.","zh":"一種傳統可以透過歌曲、食物、服裝和節日等多種表現形式延續。"},{"en":"This phrase is formal and stresses variety in expression.","zh":"這個片語較正式，強調表達形式的多樣性。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":6},{"front":"around the world","meaning":"世界各地","examples":[{"en":"Story-recording traditions can be found around the world.","zh":"記錄故事的傳統可以在世界各地找到。"},{"en":"Around the world means in many countries or many parts of the Earth.","zh":"around the world 指在許多國家或地球許多地方。"},{"en":"Students around the world use stories to learn about history and values.","zh":"世界各地的學生用故事學習歷史和價值觀。"},{"en":"When a practice appears around the world, it may reflect a common human need.","zh":"當一種做法出現在世界各地，它可能反映共同的人類需要。"},{"en":"This phrase makes the topic global rather than local.","zh":"這個片語令主題變成全球性的，而不是本地性的。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":7},{"front":"priestly papyrus archives","meaning":"祭司紙草文書檔案","examples":[{"en":"Ancient Egypt had priestly papyrus archives.","zh":"古埃及有祭司紙草文書檔案。"},{"en":"Priestly papyrus archives were collections of writings on papyrus kept by priests.","zh":"priestly papyrus archives 是由祭司保存、寫在紙草上的文獻收藏。"},{"en":"Such archives might contain religious stories, rituals, records, or instructions.","zh":"這些檔案可能包含宗教故事、儀式、記錄或指示。"},{"en":"Because priests controlled important knowledge, priestly papyrus archives helped preserve culture.","zh":"因為祭司掌握重要知識，祭司紙草文書檔案幫助保存文化。"},{"en":"This phrase combines religion, writing material, and record-keeping.","zh":"這個片語結合宗教、書寫材料和記錄保存。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":7},{"front":"ancient Egypt","meaning":"古埃及","examples":[{"en":"Ancient Egypt preserved stories in papyrus archives.","zh":"古埃及在紙草文書檔案中保存故事。"},{"en":"Ancient Egypt refers to the old civilisation along the Nile known for pyramids, pharaohs, temples, and writing.","zh":"ancient Egypt 指尼羅河沿岸的古老文明，以金字塔、法老、神廟和文字聞名。"},{"en":"Students study ancient Egypt to understand early government, religion, and record-keeping.","zh":"學生研究古埃及，以理解早期政府、宗教和記錄保存。"},{"en":"Ancient Egypt left written and visual records that help modern people study its culture.","zh":"古埃及留下文字和視覺紀錄，幫助現代人研究其文化。"},{"en":"This phrase places a topic in a specific historical civilisation.","zh":"這個片語把主題放在特定歷史文明中。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":7},{"front":"birch-bark scrolls","meaning":"樺樹皮卷軸","examples":[{"en":"The Ojibway Indians recorded their creation myth on birch-bark scrolls.","zh":"Ojibway 印第安人把他們的創世神話記錄在樺樹皮卷軸上。"},{"en":"Birch-bark scrolls are rolled writing or drawing materials made from the bark of birch trees.","zh":"birch-bark scrolls 是由樺樹樹皮製成的捲起書寫或繪畫材料。"},{"en":"A community may use birch-bark scrolls when paper is unavailable but trees are common.","zh":"當紙張不可得而樹木常見時，社群可能使用樺樹皮卷軸。"},{"en":"Birch-bark scrolls can preserve stories if they are protected from moisture and damage.","zh":"如果被保護免受濕氣和損壞，樺樹皮卷軸可以保存故事。"},{"en":"This phrase shows that story records can be made from natural materials.","zh":"這個片語顯示故事記錄可以由天然材料製成。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":7},{"front":"North American Ojibway Indians","meaning":"北美 Ojibway 印第安人","examples":[{"en":"The North American Ojibway Indians set down their creation myth on scrolls.","zh":"北美 Ojibway 印第安人把他們的創世神話寫在卷軸上。"},{"en":"The North American Ojibway Indians are an Indigenous people of North America with rich cultural traditions.","zh":"North American Ojibway Indians 是北美原住民族之一，擁有豐富文化傳統。"},{"en":"Their stories, signs, and records help preserve community memory.","zh":"他們的故事、符號和紀錄幫助保存社群記憶。"},{"en":"Studying the North American Ojibway Indians can show how different cultures record origins and beliefs.","zh":"研究北美 Ojibway 印第安人可以顯示不同文化如何記錄起源和信念。"},{"en":"This phrase refers to a specific Indigenous group, so it should be used carefully and respectfully.","zh":"這個片語指特定原住民族群，因此應謹慎而尊重地使用。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":7},{"front":"set down","meaning":"寫下；記錄","examples":[{"en":"The Ojibway Indians set down their creation myth on birch-bark scrolls.","zh":"Ojibway 印第安人把他們的創世神話寫在樺樹皮卷軸上。"},{"en":"To set down something means to write, record, or state it formally.","zh":"set down something 指把某事寫下、記錄或正式說明。"},{"en":"A teacher may ask students to set down the rules before starting group work.","zh":"老師可能要求學生在開始小組工作前寫下規則。"},{"en":"If a story is set down in writing, it can be shared beyond the original speaker.","zh":"如果故事被寫下來，它就能傳給原本講者以外的人。"},{"en":"This phrase is more formal than simply write down.","zh":"這個片語比簡單的 write down 更正式。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":7},{"front":"creation-myth","meaning":"創世神話","examples":[{"en":"The Ojibway Indians recorded their creation-myth on birch-bark scrolls.","zh":"Ojibway 印第安人把他們的創世神話記錄在樺樹皮卷軸上。"},{"en":"A creation-myth is a traditional story explaining how the world, people, or a community began.","zh":"creation-myth 是解釋世界、人類或社群如何開始的傳統故事。"},{"en":"Many cultures have a creation-myth that teaches values as well as origins.","zh":"許多文化都有創世神話，它既教導價值，也解釋起源。"},{"en":"A creation-myth can unite a community because it explains where people believe they come from.","zh":"創世神話可以凝聚社群，因為它解釋人們相信自己從何而來。"},{"en":"This phrase belongs to mythology, religion, and cultural history.","zh":"這個片語屬於神話、宗教和文化歷史範疇。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":7},{"front":"well-tried and universal practice","meaning":"經充分驗證且普遍存在的做法","examples":[{"en":"Recording stories is a well-tried and universal practice.","zh":"記錄故事是一種經充分驗證且普遍存在的做法。"},{"en":"A well-tried and universal practice is a method used often and widely because it works.","zh":"well-tried and universal practice 指因為有效而經常並廣泛使用的方法。"},{"en":"Teaching children through stories is a well-tried and universal practice in many families.","zh":"透過故事教孩子是許多家庭中經充分驗證且普遍存在的做法。"},{"en":"A practice becomes universal when many societies independently find it useful.","zh":"當許多社會各自發現某做法有用，它就變得普遍。"},{"en":"This phrase suggests both long experience and worldwide use.","zh":"這個片語暗示長期經驗和全球性使用。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":7},{"front":"so much so that","meaning":"到了……的程度","examples":[{"en":"The practice is universal, so much so that storytime is linked with paper.","zh":"這種做法非常普遍，到了故事時間與紙張聯繫起來的程度。"},{"en":"So much so that means to such a strong degree that a result follows.","zh":"so much so that 指程度如此強，以致出現某個結果。"},{"en":"The rain was heavy, so much so that the school cancelled outdoor activities.","zh":"雨勢很大，到了學校取消戶外活動的程度。"},{"en":"The film became popular, so much so that people quoted its lines for years.","zh":"這部電影變得很受歡迎，到了人們多年來引用其台詞的程度。"},{"en":"This phrase connects a strong situation with its clear consequence.","zh":"這個片語把強烈情況與清楚後果連接起來。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":7},{"front":"to this day","meaning":"直到今日","examples":[{"en":"To this day, storytime is often associated with words on paper.","zh":"直到今日，故事時間仍常與紙上的文字聯繫起來。"},{"en":"To this day means still now, even after a long time has passed.","zh":"to this day 指即使經過很久，直到現在仍然如此。"},{"en":"To this day, my grandmother remembers the song she learned as a child.","zh":"直到今日，我祖母仍記得她小時候學的歌。"},{"en":"A tradition may survive to this day because families continue to practise it.","zh":"一種傳統可能延續到今日，因為家庭繼續實踐它。"},{"en":"This phrase emphasises continuity from the past to the present.","zh":"這個片語強調從過去到現在的延續。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":7},{"front":"be associated with","meaning":"與……聯繫起來","examples":[{"en":"Storytime is often associated with words on paper.","zh":"故事時間常與紙上的文字聯繫起來。"},{"en":"To be associated with something means to be connected with it in people’s minds.","zh":"be associated with something 指在人們心中與某事物有連繫。"},{"en":"Red envelopes are often associated with Lunar New Year.","zh":"紅封包常與農曆新年聯繫起來。"},{"en":"If a restaurant is associated with poor hygiene, customers may avoid it.","zh":"如果餐廳與衞生差聯繫起來，顧客可能避開它。"},{"en":"This phrase describes mental connection, reputation, or cultural link.","zh":"這個片語描述心理連結、聲譽或文化聯繫。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":7},{"front":"words on paper","meaning":"紙上的文字","examples":[{"en":"Many people associate stories with words on paper.","zh":"許多人把故事與紙上的文字聯繫起來。"},{"en":"Words on paper means written language in books, letters, documents, or printed pages.","zh":"words on paper 指書本、信件、文件或印刷頁上的書面語言。"},{"en":"A promise feels clearer when it becomes words on paper in a contract.","zh":"當承諾成為合約中紙上的文字時，它感覺更清楚。"},{"en":"Stories recorded as words on paper can travel far beyond the original storyteller.","zh":"被記錄成紙上文字的故事可以傳到原本說故事的人以外很遠的地方。"},{"en":"This phrase contrasts written form with spoken words or images.","zh":"這個片語對比書面形式與口語或圖像。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":8},{"front":"formal practice","meaning":"正式做法","examples":[{"en":"The formal practice of narrating aloud seems less dominant now.","zh":"朗聲講述故事的正式做法現在似乎較不佔主導。"},{"en":"A formal practice is an established and recognised way of doing something.","zh":"formal practice 是一種既定而被認可的做事方式。"},{"en":"Wearing uniforms is a formal practice in many schools.","zh":"穿制服是許多學校的正式做法。"},{"en":"A formal practice may decline when new habits or technologies appear.","zh":"當新習慣或技術出現，正式做法可能衰落。"},{"en":"This phrase suggests a custom with structure, not casual behaviour.","zh":"這個片語暗示有結構的習俗，而不是隨意行為。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":8},{"front":"narrate a story aloud","meaning":"朗聲講述故事","examples":[{"en":"The formal practice of narrating a story aloud has not disappeared.","zh":"朗聲講述故事的正式做法並沒有消失。"},{"en":"To narrate a story aloud means to tell or read a story out loud for others to hear.","zh":"narrate a story aloud 指大聲講述或朗讀故事給別人聽。"},{"en":"A parent may narrate a story aloud before a child goes to sleep.","zh":"父母可能在孩子睡前朗聲講述故事。"},{"en":"Narrating a story aloud can make emotions clearer through voice and rhythm.","zh":"朗聲講述故事可以透過聲音和節奏令情感更清楚。"},{"en":"This phrase focuses on spoken delivery rather than silent reading.","zh":"這個片語聚焦於口頭表達，而不是默讀。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":8},{"front":"would seem to","meaning":"似乎會","examples":[{"en":"Reading aloud would seem to have given way to printed media.","zh":"朗讀似乎已讓位於印刷媒體。"},{"en":"Would seem to means appears to be true, although the writer may later question it.","zh":"would seem to 指看起來似乎是真的，雖然作者之後可能質疑它。"},{"en":"The shop would seem to be closed because the lights are off.","zh":"因為燈關了，這間店似乎已關門。"},{"en":"A plan would seem to work at first, but problems may appear later.","zh":"一個計劃起初似乎可行，但之後可能出現問題。"},{"en":"This phrase is cautious and less certain than definitely is.","zh":"這個片語語氣謹慎，比 definitely is 較不肯定。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":8},{"front":"give way to","meaning":"讓位於","examples":[{"en":"Oral storytelling seemed to give way to newspapers and novels.","zh":"口頭說故事似乎讓位於報紙和小說。"},{"en":"To give way to something means to be replaced by it or become less important than it.","zh":"give way to something 指被某物取代，或變得不如它重要。"},{"en":"Paper maps have largely given way to phone navigation apps.","zh":"紙本地圖已大多讓位於手機導航應用程式。"},{"en":"If old habits give way to new technology, daily routines can change quickly.","zh":"如果舊習慣讓位於新科技，日常生活可以迅速改變。"},{"en":"This phrase describes one thing declining as another becomes stronger.","zh":"這個片語描述一件事衰退，而另一件事變強。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":8},{"front":"newspapers, novels and comic strips","meaning":"報紙、小說和漫畫","examples":[{"en":"Written stories appear in newspapers, novels and comic strips.","zh":"書面故事出現在報紙、小說和漫畫中。"},{"en":"Newspapers, novels and comic strips are printed forms that can carry stories to readers.","zh":"newspapers, novels and comic strips 是可以把故事帶給讀者的印刷形式。"},{"en":"A student may learn about current events from newspapers, imagination from novels, and humour from comic strips.","zh":"學生可能從報紙學時事，從小說學想像，從漫畫學幽默。"},{"en":"These forms made stories easier to share because readers could access them without a live storyteller.","zh":"這些形式令故事更容易分享，因為讀者不需要現場說故事的人也能接觸故事。"},{"en":"This phrase lists examples of written or printed storytelling media.","zh":"這個片語列出書面或印刷敘事媒介的例子。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":8},{"front":"this is not the case","meaning":"情況並非如此","examples":[{"en":"The writer argues that this is not the case.","zh":"作者主張情況並非如此。"},{"en":"This is not the case means the previous idea is not true.","zh":"this is not the case 指前面的想法並不正確。"},{"en":"Some people think online learning is always easier, but this is not the case for every student.","zh":"有些人認為網上學習總是較容易，但對每個學生來說情況並非如此。"},{"en":"If evidence shows the opposite, a writer may say this is not the case.","zh":"如果證據顯示相反，作者可能會說情況並非如此。"},{"en":"This phrase is useful for correcting a misunderstanding.","zh":"這個片語適合用來糾正誤解。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":8},{"front":"statistically","meaning":"從統計上看","examples":[{"en":"Statistically, most humans may not rely on written stories.","zh":"從統計上看，大多數人類可能並不依賴書面故事。"},{"en":"Statistically means according to numbers, data, or measured patterns.","zh":"statistically 指根據數字、數據或量度出的模式。"},{"en":"Statistically, students who sleep enough tend to perform better in exams.","zh":"從統計上看，睡眠充足的學生往往考試表現更好。"},{"en":"A claim sounds stronger statistically when it is supported by clear data.","zh":"當說法有清楚數據支持時，從統計上看會更有說服力。"},{"en":"This word introduces a point based on quantity rather than personal opinion.","zh":"這個詞引入基於數量而非個人意見的觀點。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":8},{"front":"it is doubtful that","meaning":"……是值得懷疑的","examples":[{"en":"It is doubtful that most humans rely on the written word for stories.","zh":"大多數人類依賴書面文字獲取故事是值得懷疑的。"},{"en":"It is doubtful that means it is uncertain or unlikely that something is true.","zh":"it is doubtful that 指某事是否真實不確定或不大可能。"},{"en":"It is doubtful that the bus will arrive on time during a major traffic jam.","zh":"在嚴重交通擠塞中，巴士是否會準時到達是值得懷疑的。"},{"en":"If evidence is weak, it is doubtful that the claim should be accepted.","zh":"如果證據薄弱，是否應接受該說法是值得懷疑的。"},{"en":"This phrase expresses careful scepticism.","zh":"這個片語表達謹慎的懷疑。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":8},{"front":"the majority of humans","meaning":"大多數人類","examples":[{"en":"The majority of humans may not rely on written stories.","zh":"大多數人類可能不依賴書面故事。"},{"en":"The majority of humans means more than half of all people.","zh":"the majority of humans 指所有人中超過一半。"},{"en":"The majority of humans learn first through listening and speaking before reading.","zh":"大多數人類在閱讀之前先透過聆聽和說話學習。"},{"en":"If the majority of humans use phones for news, media habits have clearly changed.","zh":"如果大多數人類用手機看新聞，媒體習慣明顯已改變。"},{"en":"This phrase describes a very large human group, not a small sample.","zh":"這個片語描述非常龐大的人群，而不是小樣本。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":8},{"front":"rely upon","meaning":"依賴","examples":[{"en":"Many people do not rely upon the written word to access stories.","zh":"許多人並不依賴書面文字來接觸故事。"},{"en":"To rely upon something means to depend on it for help, information, or support.","zh":"rely upon something 指依靠某物獲得幫助、資訊或支持。"},{"en":"Students may rely upon dictionaries when learning difficult vocabulary.","zh":"學生學習困難詞彙時可能依賴字典。"},{"en":"If people rely upon one source only, they may miss other useful information.","zh":"如果人們只依賴一個來源，可能錯過其他有用資訊。"},{"en":"This phrase is slightly more formal than rely on.","zh":"這個片語比 rely on 稍正式。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":8},{"front":"the written word","meaning":"書面文字","examples":[{"en":"Not everyone relies upon the written word to get stories.","zh":"並非每個人都依賴書面文字獲取故事。"},{"en":"The written word means language recorded in writing rather than spoken aloud.","zh":"the written word 指被寫下來的語言，而不是朗聲說出的語言。"},{"en":"Contracts depend on the written word because exact wording matters.","zh":"合約依賴書面文字，因為確切用字很重要。"},{"en":"The written word can preserve stories after the original speaker is gone.","zh":"書面文字可以在原本講者離世後保存故事。"},{"en":"This phrase contrasts writing with speech, images, or performance.","zh":"這個片語對比文字與說話、圖像或表演。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":9},{"front":"get access to","meaning":"取得；接觸到","examples":[{"en":"People get access to stories through different media.","zh":"人們透過不同媒介接觸到故事。"},{"en":"To get access to something means to be able to reach, use, or experience it.","zh":"get access to something 指能夠接觸、使用或體驗某物。"},{"en":"Students get access to online lessons when they have internet and a device.","zh":"當學生有互聯網和裝置時，就能接觸到網上課堂。"},{"en":"If people cannot get access to libraries, reading opportunities become unequal.","zh":"如果人們不能取得圖書館服務，閱讀機會會變得不平等。"},{"en":"This phrase focuses on the ability to use or reach something.","zh":"這個片語聚焦於使用或接觸某物的能力。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":9},{"front":"alternative source","meaning":"替代來源","examples":[{"en":"The passage asks what the alternative source of stories is.","zh":"文章問故事的替代來源是甚麼。"},{"en":"An alternative source is another place, method, or medium from which something can be obtained.","zh":"alternative source 指可以取得某物的另一個地方、方法或媒介。"},{"en":"If the library is closed, students may use the internet as an alternative source of information.","zh":"如果圖書館關閉，學生可能使用互聯網作為資訊的替代來源。"},{"en":"Alternative sources become important when the usual source is unavailable or less popular.","zh":"當平常來源不可用或較不受歡迎時，替代來源變得重要。"},{"en":"This phrase suggests a different option from the expected one.","zh":"這個片語暗示不同於預期選項的另一種選擇。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":9},{"front":"latest offering","meaning":"最新作品","examples":[{"en":"Millions of people watch the latest offering from Hollywood and Bollywood.","zh":"數百萬人觀看荷里活和寶萊塢的最新作品。"},{"en":"Latest offering means the newest product, film, book, or performance released by a creator or company.","zh":"latest offering 指創作者或公司推出的最新產品、電影、書籍或表演。"},{"en":"Fans waited outside the cinema to see the director’s latest offering.","zh":"粉絲在戲院外等待觀看導演的最新作品。"},{"en":"A strong latest offering can attract old customers back to a brand.","zh":"一個強勁的最新作品可以吸引老顧客回到品牌。"},{"en":"This phrase is often used in media, entertainment, and business.","zh":"這個片語常用於媒體、娛樂和商業。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":9},{"front":"Hollywood, Bollywood and beyond","meaning":"荷里活、寶萊塢及其他地方","examples":[{"en":"Cinema audiences watch films from Hollywood, Bollywood and beyond.","zh":"電影院觀眾觀看來自荷里活、寶萊塢及其他地方的電影。"},{"en":"Hollywood, Bollywood and beyond means major film industries in America, India, and other places as well.","zh":"Hollywood, Bollywood and beyond 指美國、印度和其他地方的主要電影產業。"},{"en":"A film festival may show movies from Hollywood, Bollywood and beyond to attract different audiences.","zh":"電影節可能放映來自荷里活、寶萊塢及其他地方的電影，以吸引不同觀眾。"},{"en":"This phrase suggests cinema is global, not limited to two famous centres.","zh":"這個片語暗示電影是全球性的，不限於兩個著名中心。"},{"en":"The word beyond adds the idea of many other regions and traditions.","zh":"beyond 這個詞加入許多其他地區和傳統的意思。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":9},{"front":"supreme storyteller","meaning":"最主要的說故事者","examples":[{"en":"The supreme storyteller of today is cinema.","zh":"今日最主要的說故事者是電影。"},{"en":"A supreme storyteller is the most powerful or influential medium or person for telling stories.","zh":"supreme storyteller 指在說故事方面最有力量或影響力的媒介或人物。"},{"en":"For many children, television may seem like the supreme storyteller in the home.","zh":"對許多孩子來說，電視可能像家中最主要的說故事者。"},{"en":"Cinema became a supreme storyteller because it combines image, sound, acting, and music.","zh":"電影成為最主要的說故事者，因為它結合圖像、聲音、演技和音樂。"},{"en":"This phrase gives storytelling power to a medium, not only a person.","zh":"這個片語把說故事力量賦予媒介，而不只是人物。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":9},{"front":"cinema","meaning":"電影","examples":[{"en":"Cinema is presented as the supreme storyteller of today.","zh":"電影被呈現為今日最主要的說故事者。"},{"en":"Cinema means the art, industry, or experience of watching films.","zh":"cinema 指電影藝術、產業或觀看電影的體驗。"},{"en":"Many people visit the cinema to relax, learn, or feel strong emotions.","zh":"許多人去看電影是為了放鬆、學習或感受強烈情感。"},{"en":"Cinema can reach large audiences because stories are shown through moving images and sound.","zh":"電影可以接觸大量觀眾，因為故事透過動態影像和聲音呈現。"},{"en":"This word can refer to film as culture, not only the building where films are shown.","zh":"這個詞可以指作為文化的電影，而不只是放映電影的建築物。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":9},{"front":"as distinct from","meaning":"有別於","examples":[{"en":"The movies, as distinct from still photography, are a storytelling medium.","zh":"電影有別於靜態攝影，是一種說故事媒介。"},{"en":"As distinct from means different from or separate from another thing.","zh":"as distinct from 指與另一事物不同或分開。"},{"en":"Online lessons, as distinct from recorded videos, allow students to ask questions immediately.","zh":"網上直播課有別於錄影影片，讓學生可以即時提問。"},{"en":"A public hospital, as distinct from a private clinic, is mainly funded by the government.","zh":"公立醫院有別於私人診所，主要由政府資助。"},{"en":"This phrase is useful when making a clear comparison.","zh":"當作清晰比較時，這個片語很有用。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":9},{"front":"still photography","meaning":"靜態攝影","examples":[{"en":"Movies are different from still photography.","zh":"電影不同於靜態攝影。"},{"en":"Still photography is the art or practice of taking single, non-moving images.","zh":"still photography 是拍攝單一、不會移動影像的藝術或做法。"},{"en":"A family photo album is an example of still photography preserving memories.","zh":"家庭相簿是靜態攝影保存記憶的例子。"},{"en":"Still photography captures a moment, while film shows movement over time.","zh":"靜態攝影捕捉一刻，而電影展示隨時間移動的畫面。"},{"en":"This phrase contrasts photographs with moving images.","zh":"這個片語把照片與動態影像作對比。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":9},{"front":"essentially modern phenomenon","meaning":"本質上現代的現象","examples":[{"en":"Movies seem to be an essentially modern phenomenon.","zh":"電影似乎是本質上現代的現象。"},{"en":"An essentially modern phenomenon is something that appears mainly connected with the modern age.","zh":"essentially modern phenomenon 指主要與現代時代相關的事物。"},{"en":"Social media is often seen as an essentially modern phenomenon.","zh":"社交媒體常被視為本質上現代的現象。"},{"en":"Something may seem modern, but its deeper roots can be much older.","zh":"某事物可能看似現代，但其深層根源可以古老得多。"},{"en":"This phrase invites readers to think about whether a thing is truly new.","zh":"這個片語邀請讀者思考某事物是否真正新穎。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":9},{"front":"this is an illusion","meaning":"這是一種錯覺","examples":[{"en":"The idea that cinema is entirely modern is an illusion.","zh":"認為電影完全是現代事物，這是一種錯覺。"},{"en":"This is an illusion means the idea seems true but is actually misleading or false.","zh":"this is an illusion 指某想法看似真實，但其實誤導或錯誤。"},{"en":"A cheap product may look like a bargain, but this is an illusion if it breaks quickly.","zh":"便宜產品可能看似抵買，但如果很快壞掉，這是一種錯覺。"},{"en":"If success looks effortless, this is often an illusion created by hidden practice.","zh":"如果成功看起來毫不費力，這通常是隱藏練習造成的錯覺。"},{"en":"This phrase corrects an impression that is not reliable.","zh":"這個片語糾正不可靠的印象。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":9},{"front":"as we shall see","meaning":"正如我們將會看到","examples":[{"en":"As we shall see, film has very old precedents.","zh":"正如我們將會看到，電影有非常古老的先例。"},{"en":"As we shall see means the writer will explain or prove this later.","zh":"as we shall see 指作者稍後會解釋或證明這一點。"},{"en":"As we shall see, the small mistake at the beginning caused larger problems later.","zh":"正如我們將會看到，開頭的小錯誤後來造成更大問題。"},{"en":"A teacher may say as we shall see before guiding students through evidence.","zh":"老師可能在帶學生看證據前說正如我們將會看到。"},{"en":"This phrase prepares readers for an argument that will develop.","zh":"這個片語讓讀者準備好理解即將發展的論證。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":10},{"front":"the medium of film","meaning":"電影媒介","examples":[{"en":"The medium of film is indebted to old visual traditions.","zh":"電影媒介受惠於古老視覺傳統。"},{"en":"The medium of film means film as a method or form used to communicate stories and ideas.","zh":"the medium of film 指電影作為傳達故事和思想的方法或形式。"},{"en":"The medium of film can combine pictures, speech, music, silence, and movement.","zh":"電影媒介可以結合圖像、說話、音樂、沉默和動作。"},{"en":"Because it reaches both eyes and ears, the medium of film can feel powerful.","zh":"因為它同時接觸眼睛和耳朵，電影媒介可以感覺很有力量。"},{"en":"This phrase treats film as a communication form, not just entertainment.","zh":"這個片語把電影視為溝通形式，而不只是娛樂。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":10},{"front":"be indebted to","meaning":"受惠於；源自","examples":[{"en":"Film is indebted to older ways of arranging images.","zh":"電影受惠於較古老的圖像排列方式。"},{"en":"To be indebted to something means to owe an important influence or benefit to it.","zh":"be indebted to something 指受到某物重要影響或受益於某物。"},{"en":"Modern medicine is indebted to earlier scientists who tested basic ideas.","zh":"現代醫學受惠於早期測試基本概念的科學家。"},{"en":"A young musician may be indebted to a teacher who first encouraged her.","zh":"年輕音樂人可能受惠於最先鼓勵她的老師。"},{"en":"This phrase shows gratitude, influence, or historical connection.","zh":"這個片語顯示感激、影響或歷史連繫。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":10},{"front":"old precedents","meaning":"古老先例","examples":[{"en":"Film has old precedents in visual storytelling.","zh":"電影在視覺敘事中有古老先例。"},{"en":"Old precedents are earlier examples that existed before a later form or practice.","zh":"old precedents 是在較後形式或做法之前已存在的早期例子。"},{"en":"Online learning has old precedents in distance education by mail.","zh":"網上學習在郵寄遙距教育中有古老先例。"},{"en":"Finding old precedents helps us see that new ideas often have older roots.","zh":"找到古老先例幫助我們看到新想法常有更早根源。"},{"en":"This phrase connects a modern practice with examples from the past.","zh":"這個片語把現代做法與過去例子連接起來。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":10},{"front":"sequences of images","meaning":"一連串圖像","examples":[{"en":"Film arranges sequences of images to tell stories.","zh":"電影排列一連串圖像來說故事。"},{"en":"Sequences of images are groups of pictures placed one after another in order.","zh":"sequences of images 是按順序一張接一張排列的圖像組合。"},{"en":"A comic strip uses sequences of images to show action and time.","zh":"漫畫使用一連串圖像來展示動作和時間。"},{"en":"When sequences of images are shown quickly, they can create the feeling of movement.","zh":"當一連串圖像快速顯示時，它們可以創造動感。"},{"en":"This phrase is important for understanding visual storytelling.","zh":"這個片語對理解視覺敘事很重要。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":10},{"front":"visual storytelling","meaning":"視覺敘事","examples":[{"en":"Any account of visual storytelling must consider ancient traditions.","zh":"任何對視覺敘事的說明都必須考慮古代傳統。"},{"en":"Visual storytelling means telling a story mainly through pictures, symbols, movement, or images.","zh":"visual storytelling 指主要透過圖畫、符號、動作或影像講故事。"},{"en":"A photo essay is a form of visual storytelling because pictures carry the message.","zh":"攝影故事是一種視覺敘事，因為圖像承載訊息。"},{"en":"Visual storytelling can help people understand a story even without many words.","zh":"視覺敘事可以幫助人們在沒有很多文字時仍理解故事。"},{"en":"This phrase includes film, comics, paintings, diagrams, and other image-based forms.","zh":"這個片語包括電影、漫畫、繪畫、圖表和其他以圖像為主的形式。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":10},{"front":"begin with the recognition that","meaning":"先要認識到","examples":[{"en":"An account of storytelling must begin with the recognition that stories follow old patterns.","zh":"對說故事的說明先要認識到故事遵循古老模式。"},{"en":"To begin with the recognition that means to start by accepting an important fact.","zh":"begin with the recognition that 指一開始就接受一個重要事實。"},{"en":"A discussion of health should begin with the recognition that sleep affects mood and memory.","zh":"健康討論應先要認識到睡眠影響心情和記憶。"},{"en":"Good policy begins with the recognition that people have different needs.","zh":"良好政策先要認識到人們有不同需要。"},{"en":"This phrase prepares the reader for a basic idea that supports the whole argument.","zh":"這個片語讓讀者準備好理解支撐整個論點的基本概念。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":10},{"front":"beat with","meaning":"帶有；跳動着","examples":[{"en":"All storytelling beats with an ancient pulse.","zh":"所有說故事都跳動着古老的脈搏。"},{"en":"Beat with means to be filled with or driven by a repeated energy, rhythm, or feeling.","zh":"beat with 指充滿或被某種重複的能量、節奏或感覺推動。"},{"en":"A festival may beat with music, movement, and excitement.","zh":"節日可能帶有音樂、動作和興奮感。"},{"en":"A classroom beats with curiosity when students keep asking questions.","zh":"當學生不斷提問，課室會跳動着好奇心。"},{"en":"This phrase is metaphorical and gives an idea a living rhythm.","zh":"這個片語具比喻性，給概念一種活的節奏。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":10},{"front":"deeply atavistic pulse","meaning":"深層返祖式脈搏；古老本能節奏","examples":[{"en":"Storytelling beats with a deeply atavistic pulse.","zh":"說故事跳動着深層返祖式脈搏。"},{"en":"A deeply atavistic pulse is a very old instinctive rhythm or drive from humanity’s distant past.","zh":"deeply atavistic pulse 指來自人類遙遠過去的非常古老、本能性的節奏或驅動力。"},{"en":"People gathering to hear a scary story may feel a deeply atavistic pulse of fear and curiosity.","zh":"人們聚在一起聽恐怖故事時，可能感到恐懼和好奇的古老本能節奏。"},{"en":"This pulse explains why ancient story patterns can still affect modern audiences.","zh":"這種脈搏解釋為何古老故事模式仍能影響現代觀眾。"},{"en":"The phrase is literary and suggests something ancient inside human nature.","zh":"這個片語較文學化，暗示人性中某種古老東西。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":10},{"front":"rely upon","meaning":"依賴","examples":[{"en":"A good story relies upon formal patterns of plot and characterisation.","zh":"好故事依賴情節與人物塑造的固定模式。"},{"en":"To rely upon something means to depend on it for success, support, or structure.","zh":"rely upon something 指依靠某物取得成功、支持或結構。"},{"en":"A good essay relies upon clear paragraphs and strong examples.","zh":"好文章依賴清晰段落和有力例子。"},{"en":"If a film relies upon weak characters only, viewers may lose interest.","zh":"如果電影只依賴薄弱人物，觀眾可能失去興趣。"},{"en":"This phrase shows what something needs in order to work well.","zh":"這個片語顯示某事物要運作良好所需要的東西。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":10},{"front":"formal patterns","meaning":"固定模式","examples":[{"en":"Good stories rely upon formal patterns of plot and characterisation.","zh":"好故事依賴情節與人物塑造的固定模式。"},{"en":"Formal patterns are established structures or repeated arrangements used in art, writing, or behaviour.","zh":"formal patterns 是藝術、寫作或行為中既定的結構或重複安排。"},{"en":"A detective story often follows formal patterns, such as crime, clues, and solution.","zh":"偵探故事常遵循固定模式，例如罪案、線索和解答。"},{"en":"Formal patterns help audiences understand what kind of story they are watching.","zh":"固定模式幫助觀眾理解自己正在觀看哪類故事。"},{"en":"This phrase does not mean boring rules; it means recognisable structure.","zh":"這個片語不是指沉悶規則，而是指可辨認的結構。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":10},{"front":"plot and characterisation","meaning":"情節與人物塑造","examples":[{"en":"Plot and characterisation are central to good storytelling.","zh":"情節與人物塑造是良好說故事的核心。"},{"en":"Plot is what happens in a story, and characterisation is how characters are created and shown.","zh":"plot 是故事中發生的事情，而 characterisation 是人物如何被創造和呈現。"},{"en":"A film may have an exciting plot but weak characterisation if viewers do not care about the people.","zh":"如果觀眾不在乎人物，一部電影可能有刺激情節但人物塑造薄弱。"},{"en":"Strong plot and characterisation make readers want to know both what happens and why it matters.","zh":"強大的情節與人物塑造令讀者想知道發生甚麼，以及為何重要。"},{"en":"This phrase names two basic parts of narrative craft.","zh":"這個片語指出敘事技巧的兩個基本部分。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":11},{"front":"be embedded in","meaning":"深植於","examples":[{"en":"These patterns are embedded in the practice of storytelling.","zh":"這些模式深植於說故事的做法中。"},{"en":"To be embedded in something means to be deeply fixed or built into it.","zh":"be embedded in something 指深深固定或內建於某事物之中。"},{"en":"Respect for elders may be embedded in a community’s daily habits.","zh":"尊重長者可能深植於一個社群的日常習慣中。"},{"en":"If a habit is embedded in school culture, it is hard to change quickly.","zh":"如果一種習慣深植於學校文化中，就很難快速改變。"},{"en":"This phrase shows that something is not superficial or temporary.","zh":"這個片語顯示某事不是表面或暫時的。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":11},{"front":"practice of storytelling","meaning":"說故事的做法","examples":[{"en":"The practice of storytelling has developed over many generations.","zh":"說故事的做法經過許多世代發展。"},{"en":"The practice of storytelling means the repeated human habit of creating, telling, and sharing stories.","zh":"practice of storytelling 指人類創造、講述和分享故事的重複習慣。"},{"en":"The practice of storytelling appears in families, classrooms, theatres, films, and religious settings.","zh":"說故事的做法出現在家庭、課室、劇院、電影和宗教場合中。"},{"en":"Because people keep telling stories, the practice of storytelling changes but does not disappear.","zh":"因為人們持續講故事，說故事的做法會改變但不會消失。"},{"en":"This phrase focuses on storytelling as a continuing cultural activity.","zh":"這個片語聚焦於說故事作為持續文化活動。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":11},{"front":"over many generations","meaning":"經過許多世代","examples":[{"en":"Story patterns have been embedded over many generations.","zh":"故事模式經過許多世代深植下來。"},{"en":"Over many generations means across a long period as parents, children, and later descendants pass on habits or knowledge.","zh":"over many generations 指在父母、孩子和後代傳承習慣或知識的長時間中。"},{"en":"A family recipe may change slowly over many generations.","zh":"一個家庭食譜可能經過許多世代慢慢改變。"},{"en":"Traditions survive over many generations when young people continue to practise them.","zh":"當年輕人繼續實踐，傳統可以經過許多世代延續。"},{"en":"This phrase shows long-term continuity.","zh":"這個片語顯示長期延續。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":11},{"front":"scripts arrive","meaning":"劇本送達","examples":[{"en":"Thousands of scripts arrive at major film studios every week.","zh":"每週有數以千計劇本送達大型電影製片廠。"},{"en":"Scripts arrive means written screenplays or story proposals are sent to a place for review.","zh":"scripts arrive 指書面劇本或故事提案被送到某處審閱。"},{"en":"Many scripts arrive by email before a film company chooses which ones to read carefully.","zh":"在電影公司選擇仔細閱讀哪些劇本前，許多劇本會透過電郵送達。"},{"en":"When too many scripts arrive, editors must quickly decide which stories have promise.","zh":"當太多劇本送達，編輯必須快速判斷哪些故事有潛力。"},{"en":"This phrase describes the flow of written story ideas into a studio.","zh":"這個片語描述書面故事構想流入製片廠。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":11},{"front":"major film studios","meaning":"大型電影製片廠","examples":[{"en":"Major film studios receive thousands of scripts every week.","zh":"大型電影製片廠每週收到數以千計劇本。"},{"en":"Major film studios are large companies that finance, produce, and distribute films.","zh":"major film studios 是資助、製作和發行電影的大型公司。"},{"en":"A major film studio may hire writers, directors, actors, editors, and marketing teams.","zh":"大型電影製片廠可能聘請編劇、導演、演員、剪接師和市場推廣團隊。"},{"en":"Major film studios can influence what stories reach large audiences.","zh":"大型電影製片廠可以影響哪些故事接觸大量觀眾。"},{"en":"This phrase refers to powerful organisations in the film industry.","zh":"這個片語指電影業中的有力組織。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":11},{"front":"aspiring screenwriters","meaning":"有志成為編劇的人","examples":[{"en":"Aspiring screenwriters can learn from Aristotle.","zh":"有志成為編劇的人可以向 Aristotle 學習。"},{"en":"Aspiring screenwriters are people who hope to become writers of film or television scripts.","zh":"aspiring screenwriters 是希望成為電影或電視劇本作者的人。"},{"en":"Aspiring screenwriters often practise by writing short scenes and studying successful films.","zh":"有志成為編劇的人常透過寫短場景和研究成功電影來練習。"},{"en":"Feedback helps aspiring screenwriters improve dialogue, structure, and character.","zh":"回饋幫助有志成為編劇的人改善對白、結構和人物。"},{"en":"This phrase describes people with a goal, not people who have already succeeded.","zh":"這個片語描述有目標的人，而不是已經成功的人。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":11},{"front":"look no further than","meaning":"不必再看別處，只需看……","examples":[{"en":"Screenwriters need to look no further than Aristotle for advice.","zh":"編劇不必再看別處，只需看 Aristotle 就能得到建議。"},{"en":"Look no further than means the best or clearest example can already be found in one place.","zh":"look no further than 指最好或最清楚的例子已可在某處找到。"},{"en":"For simple grammar explanations, beginners may need to look no further than a good basic textbook.","zh":"對簡單文法解釋而言，初學者可能不必再看別處，只需看一本好的基礎教材。"},{"en":"If you want evidence of hard work, look no further than her daily practice record.","zh":"如果你想找努力的證據，不必再看別處，只需看她的每日練習紀錄。"},{"en":"This phrase points strongly to a suitable source or example.","zh":"這個片語強烈指出合適來源或例子。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":11},{"front":"essential advice","meaning":"必要建議","examples":[{"en":"Aristotle offers essential advice on storytelling.","zh":"Aristotle 提供關於說故事的必要建議。"},{"en":"Essential advice is guidance that is very important and useful for success.","zh":"essential advice 是對成功非常重要和有用的指引。"},{"en":"For new drivers, essential advice includes checking mirrors and keeping a safe distance.","zh":"對新司機來說，必要建議包括檢查倒後鏡和保持安全距離。"},{"en":"Essential advice prevents common mistakes because it focuses on what matters most.","zh":"必要建議能防止常見錯誤，因為它聚焦於最重要的事情。"},{"en":"This phrase suggests advice that should not be ignored.","zh":"這個片語暗示不應忽視的建議。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":11},{"front":"fourth-century BC","meaning":"公元前四世紀","examples":[{"en":"Aristotle was a fourth-century BC Greek philosopher.","zh":"Aristotle 是公元前四世紀的希臘哲學家。"},{"en":"Fourth-century BC means the period from 400 to 301 years before the common era.","zh":"fourth-century BC 指公元前400年至公元前301年這段時期。"},{"en":"A fourth-century BC text comes from a very ancient historical period.","zh":"公元前四世紀的文本來自非常古老的歷史時期。"},{"en":"Knowing that an idea is fourth-century BC helps students understand its historical distance.","zh":"知道一個思想屬於公元前四世紀，幫助學生理解其歷史距離。"},{"en":"This phrase is used to date people, texts, events, or objects.","zh":"這個片語用來為人物、文本、事件或物件標示年代。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":11},{"front":"Greek philosopher","meaning":"希臘哲學家","examples":[{"en":"Aristotle was a Greek philosopher who analysed storytelling.","zh":"Aristotle 是一位分析說故事的希臘哲學家。"},{"en":"A Greek philosopher is a thinker from ancient Greece who studied ideas such as truth, art, politics, or nature.","zh":"Greek philosopher 是古希臘思想家，研究真理、藝術、政治或自然等思想。"},{"en":"Students often learn about Greek philosophers when studying the history of Western thought.","zh":"學生研究西方思想史時常學習希臘哲學家。"},{"en":"A Greek philosopher could influence later writers because his ideas were copied and discussed.","zh":"希臘哲學家能影響後來作者，因為他的思想被抄錄和討論。"},{"en":"This phrase connects a thinker with ancient Greek intellectual culture.","zh":"這個片語把思想家與古希臘知識文化連繫起來。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":11},{"front":"incomplete lecture notes","meaning":"不完整的講義筆記","examples":[{"en":"Aristotle left incomplete lecture notes on storytelling.","zh":"Aristotle 留下關於說故事的不完整講義筆記。"},{"en":"Incomplete lecture notes are teaching notes that are unfinished or missing some parts.","zh":"incomplete lecture notes 是未完成或缺少某些部分的教學筆記。"},{"en":"Students may find incomplete lecture notes confusing if key examples are absent.","zh":"如果關鍵例子缺失，學生可能覺得不完整講義筆記很混亂。"},{"en":"Even incomplete lecture notes can be valuable if they preserve important ideas.","zh":"即使是不完整講義筆記，只要保存重要思想，也可以很有價值。"},{"en":"This phrase suggests useful material that is not fully polished.","zh":"這個片語暗示有用但未完全整理好的材料。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":12},{"front":"the art of telling stories","meaning":"說故事的藝術","examples":[{"en":"The Poetics discusses the art of telling stories.","zh":"《詩學》討論說故事的藝術。"},{"en":"The art of telling stories means the skill of shaping events, characters, and language into a meaningful narrative.","zh":"the art of telling stories 指把事件、人物和語言塑造成有意義敘事的技巧。"},{"en":"Teachers use the art of telling stories when they make history feel alive.","zh":"當老師令歷史感覺生動時，就是在使用說故事的藝術。"},{"en":"The art of telling stories improves when writers understand timing, conflict, and emotion.","zh":"當作家理解時機、衝突和情感，說故事的藝術會提升。"},{"en":"This phrase treats storytelling as a craft that can be studied.","zh":"這個片語把說故事視為可以研究的技藝。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":12},{"front":"literary and dramatic modes","meaning":"文學和戲劇模式","examples":[{"en":"Aristotle examined stories in various literary and dramatic modes.","zh":"Aristotle 研究了各種文學和戲劇模式中的故事。"},{"en":"Literary and dramatic modes are different forms of writing and performance, such as poetry, tragedy, comedy, or drama.","zh":"literary and dramatic modes 是不同寫作和表演形式，例如詩歌、悲劇、喜劇或戲劇。"},{"en":"A university course may compare literary and dramatic modes to show how stories change across forms.","zh":"大學課程可能比較文學和戲劇模式，以顯示故事如何在不同形式中改變。"},{"en":"Different modes affect audiences differently because they use different structures and voices.","zh":"不同模式以不同方式影響觀眾，因為它們使用不同結構和聲音。"},{"en":"This phrase is formal and belongs to literary analysis.","zh":"這個片語較正式，屬於文學分析。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":12},{"front":"slim volume","meaning":"薄薄一冊","examples":[{"en":"The Poetics is a slim volume of lecture notes.","zh":"《詩學》是一薄冊講義筆記。"},{"en":"A slim volume is a short or thin book.","zh":"slim volume 指一本短小或薄的書。"},{"en":"A slim volume can still contain powerful ideas if the writing is concentrated.","zh":"如果寫作濃縮，一薄冊仍可以包含強大思想。"},{"en":"Students may prefer a slim volume when they need a clear introduction to a difficult topic.","zh":"當學生需要困難主題的清楚入門時，可能偏好薄薄一冊。"},{"en":"This phrase describes physical size, not importance.","zh":"這個片語描述實體大小，而不是重要性。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":12},{"front":"known as","meaning":"被稱為","examples":[{"en":"The lecture notes are known as The Poetics.","zh":"這些講義筆記被稱為《詩學》。"},{"en":"Known as means called by a particular name.","zh":"known as 指以某個特定名稱被稱呼。"},{"en":"A famous market may be known as the best place for street food.","zh":"著名街市可能被稱為最好的街頭小食地點。"},{"en":"If a writer is known as honest, readers may trust her work more.","zh":"如果作家被稱為誠實，讀者可能更信任她的作品。"},{"en":"This phrase identifies a name, title, or reputation.","zh":"這個片語指出名稱、稱號或聲譽。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":12},{"front":"The Poetics","meaning":"《詩學》","examples":[{"en":"Aristotle’s book on storytelling is known as The Poetics.","zh":"Aristotle 關於說故事的書被稱為《詩學》。"},{"en":"The Poetics is Aristotle’s work discussing poetry, drama, plot, character, and the effects of storytelling.","zh":"The Poetics 是 Aristotle 討論詩歌、戲劇、情節、人物和說故事效果的作品。"},{"en":"Students of literature may read The Poetics to understand early ideas about tragedy.","zh":"文學學生可能閱讀《詩學》，以理解關於悲劇的早期思想。"},{"en":"The Poetics remains important because it explains story structure in a systematic way.","zh":"《詩學》仍然重要，因為它有系統地解釋故事結構。"},{"en":"This title is often mentioned in discussions of Western literary theory.","zh":"這個書名常見於西方文學理論討論。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":12},{"front":"can never have envisaged","meaning":"不可能曾預想到","examples":[{"en":"Aristotle can never have envisaged the modern multiplex cinema.","zh":"Aristotle 不可能曾預想到現代多廳戲院。"},{"en":"Can never have envisaged means could not possibly have imagined or predicted something.","zh":"can never have envisaged 指不可能想像或預測某事。"},{"en":"Early inventors can never have envisaged how smartphones would change daily life.","zh":"早期發明家不可能曾預想到智能電話如何改變日常生活。"},{"en":"A writer from centuries ago can never have envisaged modern streaming platforms.","zh":"幾個世紀前的作家不可能曾預想到現代串流平台。"},{"en":"This phrase stresses the huge gap between past imagination and later reality.","zh":"這個片語強調過去想像與後來現實之間的巨大距離。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":12},{"front":"popcorn-fuelled actuality","meaning":"充滿爆谷氣氛的現實場景","examples":[{"en":"Aristotle could not have imagined the popcorn-fuelled actuality of modern cinema.","zh":"Aristotle 不可能想像現代電影那種充滿爆谷氣氛的現實場景。"},{"en":"Popcorn-fuelled actuality means the lively real-world cinema experience associated with modern audiences eating popcorn.","zh":"popcorn-fuelled actuality 指與現代觀眾吃爆谷相關的熱鬧真實影院體驗。"},{"en":"A crowded theatre with snacks, trailers, and bright screens shows the popcorn-fuelled actuality of cinema.","zh":"充滿零食、預告片和明亮銀幕的擁擠劇院，展示了電影充滿爆谷氣氛的現實場景。"},{"en":"The phrase contrasts ancient theory with today’s noisy commercial film experience.","zh":"這個片語對比古代理論與今日喧鬧的商業電影體驗。"},{"en":"It is playful and descriptive rather than a technical term.","zh":"它是俏皮而具描述性的說法，不是技術術語。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":12},{"front":"multiplex cinema","meaning":"多廳戲院","examples":[{"en":"A multiplex cinema is a modern cultural hub for film audiences.","zh":"多廳戲院是電影觀眾的現代文化中心。"},{"en":"A multiplex cinema is a cinema building with several screens showing different films at the same time.","zh":"multiplex cinema 是有多個銀幕、可同時放映不同電影的戲院建築。"},{"en":"Families may choose a multiplex cinema because it offers many film choices in one place.","zh":"家庭可能選擇多廳戲院，因為它在同一地點提供許多電影選擇。"},{"en":"Multiplex cinemas changed filmgoing by making the cinema a larger leisure centre.","zh":"多廳戲院把戲院變成更大型休閒中心，改變了觀影方式。"},{"en":"This phrase refers to a modern cinema complex, not a single small theatre.","zh":"這個片語指現代影院綜合體，而不是單一小劇院。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":12},{"front":"almost prescient about","meaning":"對……幾乎有先見之明","examples":[{"en":"Aristotle was almost prescient about the key elements of popular storytelling.","zh":"Aristotle 對流行說故事的關鍵元素幾乎有先見之明。"},{"en":"Almost prescient about means seeming nearly able to predict future developments.","zh":"almost prescient about 指似乎幾乎能預見未來發展。"},{"en":"An old article may seem almost prescient about online shopping if it described digital markets early.","zh":"如果一篇舊文章很早就描述數碼市場，它可能對網上購物幾乎有先見之明。"},{"en":"A thinker becomes almost prescient when later events match his ideas surprisingly well.","zh":"當後來事件驚人地符合某位思想家的想法，他就顯得幾乎有先見之明。"},{"en":"This phrase suggests impressive foresight, though not literal magic.","zh":"這個片語暗示令人佩服的預見力，但不是字面上的魔法。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":12},{"front":"key elements","meaning":"關鍵元素","examples":[{"en":"Aristotle identified key elements required for successful storytelling.","zh":"Aristotle 指出了成功說故事所需的關鍵元素。"},{"en":"Key elements are the most important parts needed to make something work.","zh":"key elements 是令某事運作所需的最重要部分。"},{"en":"Clear goals, practice, and feedback are key elements of effective learning.","zh":"清晰目標、練習和回饋是有效學習的關鍵元素。"},{"en":"If key elements are missing, a plan may fail even if it looks attractive.","zh":"如果缺少關鍵元素，即使計劃看似吸引，也可能失敗。"},{"en":"This phrase helps separate essential parts from minor details.","zh":"這個片語幫助把必要部分與次要細節分開。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":12},{"front":"required to","meaning":"需要用來……","examples":[{"en":"Certain key elements are required to attract large audiences.","zh":"某些關鍵元素需要用來吸引大量觀眾。"},{"en":"Required to means needed in order to do or achieve something.","zh":"required to 指為了做成或達成某事而需要。"},{"en":"Students are required to submit homework before the deadline.","zh":"學生需要在截止日期前提交功課。"},{"en":"Good lighting is required to take clear photographs indoors.","zh":"在室內拍清晰照片需要良好光線。"},{"en":"This phrase shows necessity, not just preference.","zh":"這個片語顯示必要性，而不只是偏好。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":13},{"front":"get the crowds flocking to","meaning":"吸引群眾蜂擁而至","examples":[{"en":"Good storytelling gets the crowds flocking to the cinema.","zh":"好故事能吸引群眾蜂擁而至戲院。"},{"en":"To get the crowds flocking to a place means to attract many people there quickly and eagerly.","zh":"get the crowds flocking to a place 指快速而熱切地吸引大量人前往某地。"},{"en":"A famous singer can get the crowds flocking to a shopping mall event.","zh":"著名歌手可以吸引群眾蜂擁而至商場活動。"},{"en":"Strong reviews may get the crowds flocking to a new restaurant.","zh":"好評可能吸引群眾蜂擁而至新餐廳。"},{"en":"This phrase suggests popularity, excitement, and large numbers.","zh":"這個片語暗示受歡迎、興奮和大量人群。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":13},{"front":"cultural hub","meaning":"文化中心","examples":[{"en":"The cinema can function as a cultural hub.","zh":"戲院可以作為文化中心運作。"},{"en":"A cultural hub is a place where people gather for art, entertainment, ideas, and shared experiences.","zh":"cultural hub 是人們為藝術、娛樂、思想和共同體驗而聚集的地方。"},{"en":"A library can become a cultural hub if it hosts talks, exhibitions, and reading clubs.","zh":"如果圖書館舉辦講座、展覽和讀書會，它可以成為文化中心。"},{"en":"Cultural hubs help communities meet, learn, and feel connected.","zh":"文化中心幫助社群相遇、學習和感到連繫。"},{"en":"This phrase describes a place with social and cultural energy.","zh":"這個片語描述具有社會和文化活力的地方。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":13},{"front":"analyse the process","meaning":"分析過程","examples":[{"en":"Aristotle analysed the storytelling process with cool rationalism.","zh":"Aristotle 以冷靜理性分析說故事過程。"},{"en":"To analyse the process means to study how something works step by step.","zh":"analyse the process 指逐步研究某事如何運作。"},{"en":"A coach may analyse the process of training to find why players are improving slowly.","zh":"教練可能分析訓練過程，以找出球員進步緩慢的原因。"},{"en":"Analysing the process helps people fix problems instead of guessing.","zh":"分析過程幫助人們修正問題，而不是猜測。"},{"en":"This phrase is useful for careful, logical study of how results are produced.","zh":"這個片語適合用於仔細而合邏輯地研究結果如何產生。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":13},{"front":"cool rationalism","meaning":"冷靜理性","examples":[{"en":"Aristotle approached storytelling with cool rationalism.","zh":"Aristotle 以冷靜理性處理說故事。"},{"en":"Cool rationalism means calm, logical thinking without being carried away by emotion.","zh":"cool rationalism 指冷靜、合邏輯的思考，不被情緒帶走。"},{"en":"A doctor needs cool rationalism when deciding how to treat an emergency patient.","zh":"醫生決定如何治療急症病人時，需要冷靜理性。"},{"en":"Cool rationalism can help a team solve conflict by focusing on facts and causes.","zh":"冷靜理性可以透過聚焦事實和原因幫助團隊解決衝突。"},{"en":"This phrase suggests clear analysis rather than emotional reaction.","zh":"這個片語暗示清晰分析，而不是情緒反應。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":13},{"front":"a story enchants us","meaning":"故事迷住我們","examples":[{"en":"When a story enchants us, we forget where we are.","zh":"當故事迷住我們時，我們會忘記自己身在何處。"},{"en":"A story enchants us when it captures our imagination so strongly that we feel absorbed.","zh":"a story enchants us 指故事強烈捕捉我們的想像力，使我們投入其中。"},{"en":"A children’s book may enchant us through simple language and magical pictures.","zh":"兒童書可能透過簡單語言和魔法般圖畫迷住我們。"},{"en":"When a story enchants us, time seems to pass quickly.","zh":"當故事迷住我們時，時間似乎過得很快。"},{"en":"This phrase describes the emotional power of storytelling.","zh":"這個片語描述說故事的情感力量。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":13},{"front":"lose the sense of","meaning":"失去對……的感覺","examples":[{"en":"Audiences lose the sense of where they are.","zh":"觀眾失去對自己身在何處的感覺。"},{"en":"To lose the sense of something means to stop being aware of it clearly.","zh":"lose the sense of something 指不再清楚意識到某事。"},{"en":"A student absorbed in a novel may lose the sense of time.","zh":"沉浸於小說的學生可能失去對時間的感覺。"},{"en":"Loud music can make people lose the sense of how loudly they are speaking.","zh":"大聲音樂可以令人失去對自己說話音量的感覺。"},{"en":"This phrase shows that attention has moved away from reality.","zh":"這個片語顯示注意力已從現實移開。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":13},{"front":"be drawn into","meaning":"被吸引進入","examples":[{"en":"We are drawn into the story so thoroughly that we forget reality.","zh":"我們被徹底吸引進入故事，以致忘記現實。"},{"en":"To be drawn into something means to become strongly involved or absorbed in it.","zh":"be drawn into something 指強烈參與或沉浸於某事。"},{"en":"Viewers are drawn into a film when the characters feel real.","zh":"當人物感覺真實時，觀眾會被吸引進入電影。"},{"en":"A person may be drawn into a conversation if the topic feels personal and important.","zh":"如果話題感覺個人而重要，一個人可能被吸引進入對話。"},{"en":"This phrase suggests a strong pull of attention or emotion.","zh":"這個片語暗示注意力或情感被強烈拉進去。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":13},{"front":"so thoroughly that","meaning":"徹底到……的程度","examples":[{"en":"The audience is drawn into the story so thoroughly that it forgets the story is fictional.","zh":"觀眾被吸引進入故事徹底到忘記故事是虛構的程度。"},{"en":"So thoroughly that means to such a complete degree that a clear result happens.","zh":"so thoroughly that 指某事完成得非常徹底，以致出現清楚結果。"},{"en":"The child cleaned the room so thoroughly that even the shelves looked new.","zh":"孩子把房間清潔得徹底到連架子都像新的程度。"},{"en":"A teacher explained the topic so thoroughly that students had few questions left.","zh":"老師解釋主題徹底到學生幾乎沒有問題剩下。"},{"en":"This phrase links complete action with a consequence.","zh":"這個片語把徹底的行動與後果連接起來。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":13},{"front":"a story being told","meaning":"一個正在被講述的故事","examples":[{"en":"We forget that it is a story being told.","zh":"我們忘記那是一個正在被講述的故事。"},{"en":"A story being told is a narrative currently being spoken, shown, or presented to an audience.","zh":"a story being told 指一個正在向觀眾說出、展示或呈現的敘事。"},{"en":"During a play, the audience knows there is a story being told but may still feel it is real.","zh":"在戲劇中，觀眾知道有一個正在被講述的故事，但仍可能覺得它真實。"},{"en":"If a story being told feels artificial, listeners may stop caring.","zh":"如果一個正在被講述的故事感覺造作，聽眾可能不再在乎。"},{"en":"This phrase reminds us that storytelling is an act of presentation.","zh":"這個片語提醒我們說故事是一種呈現行為。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":13},{"front":"in Aristotle’s phrase","meaning":"用 Aristotle 的說法","examples":[{"en":"In Aristotle’s phrase, this is the suspension of disbelief.","zh":"用 Aristotle 的說法，這就是暫時停止懷疑。"},{"en":"In Aristotle’s phrase means using the expression or wording associated with Aristotle.","zh":"in Aristotle’s phrase 指使用與 Aristotle 相關的表達或措辭。"},{"en":"In the teacher’s phrase, mistakes are not failure but information.","zh":"用老師的說法，錯誤不是失敗，而是資訊。"},{"en":"Writers use this structure when they borrow a useful expression from someone else.","zh":"當作者借用別人的有用表達時，會使用這種結構。"},{"en":"This phrase gives credit to the person whose wording is being used.","zh":"這個片語把用語歸功於相關人物。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":13},{"front":"suspension of disbelief","meaning":"暫時停止懷疑；投入虛構情境","examples":[{"en":"The suspension of disbelief allows audiences to accept a fictional world.","zh":"暫時停止懷疑讓觀眾接受虛構世界。"},{"en":"Suspension of disbelief is the temporary choice to accept unreal events in a story as if they were believable.","zh":"suspension of disbelief 是暫時選擇把故事中的非真實事件當作可信來接受。"},{"en":"Viewers practise suspension of disbelief when they enjoy a film about dragons or time travel.","zh":"當觀眾享受關於龍或時間旅行的電影時，就是在暫時停止懷疑。"},{"en":"If a story breaks its own rules, suspension of disbelief may disappear.","zh":"如果故事打破自己的規則，暫時停止懷疑可能消失。"},{"en":"This phrase explains why fiction can feel emotionally real.","zh":"這個片語解釋為何虛構作品可以在情感上感覺真實。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":14},{"front":"know the feeling","meaning":"明白那種感覺","examples":[{"en":"Anyone moved by a film knows the feeling.","zh":"任何被電影感動過的人都明白那種感覺。"},{"en":"To know the feeling means to have experienced the same emotion or situation personally.","zh":"know the feeling 指親身經歷過相同情感或情況。"},{"en":"Anyone who has waited nervously for exam results knows the feeling.","zh":"任何曾緊張等待考試結果的人都明白那種感覺。"},{"en":"When people know the feeling, they can understand another person’s reaction more easily.","zh":"當人們明白那種感覺，就更容易理解別人的反應。"},{"en":"This phrase builds connection through shared experience.","zh":"這個片語透過共同經驗建立連結。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":14},{"front":"stay in our seats","meaning":"留在座位上","examples":[{"en":"Viewers may stay in their seats as the credits roll by.","zh":"當片尾字幕滾動時，觀眾可能留在座位上。"},{"en":"To stay in our seats means to remain sitting instead of leaving.","zh":"stay in our seats 指繼續坐着而不是離開。"},{"en":"Students may stay in their seats after class if they are still finishing a test.","zh":"如果學生仍在完成測驗，下課後可能留在座位上。"},{"en":"After a powerful performance, the audience may stay in their seats silently.","zh":"一場有力表演後，觀眾可能安靜地留在座位上。"},{"en":"This phrase can show attention, shock, respect, or reluctance to leave.","zh":"這個片語可以顯示專注、震撼、尊重或不願離開。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":14},{"front":"stunned with grief","meaning":"因悲痛而震撼","examples":[{"en":"Some viewers remain stunned with grief after a tragic film.","zh":"有些觀眾在悲劇電影後仍因悲痛而震撼。"},{"en":"Stunned with grief means shocked and almost unable to react because of deep sadness.","zh":"stunned with grief 指因深切悲傷而震驚到幾乎不能反應。"},{"en":"A family may be stunned with grief after sudden bad news.","zh":"家庭在突然收到壞消息後可能因悲痛而震撼。"},{"en":"A tragic scene can leave viewers stunned with grief if they deeply care about the character.","zh":"如果觀眾深深在乎人物，悲劇場景可以令他們因悲痛而震撼。"},{"en":"This phrase describes intense emotional shock, not mild sadness.","zh":"這個片語描述強烈情感震撼，而不是輕微悲傷。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":14},{"front":"credits roll by","meaning":"片尾字幕滾動","examples":[{"en":"The audience may sit silently as the credits roll by.","zh":"當片尾字幕滾動時，觀眾可能安靜坐着。"},{"en":"Credits roll by means the list of people who made a film moves across the screen at the end.","zh":"credits roll by 指電影結尾列出製作人員的名單在螢幕上移動。"},{"en":"Some viewers leave as the credits roll by, while others wait for extra scenes.","zh":"有些觀眾在片尾字幕滾動時離開，另一些則等彩蛋。"},{"en":"If a film is very moving, people may keep watching as the credits roll by.","zh":"如果電影非常感人，人們可能在片尾字幕滾動時繼續觀看。"},{"en":"This phrase belongs to the cinema experience after the story ends.","zh":"這個片語屬於故事結束後的影院體驗。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":14},{"front":"nervous for days","meaning":"緊張不安好幾天","examples":[{"en":"A horror film may leave viewers nervous for days.","zh":"恐怖電影可能令觀眾緊張不安好幾天。"},{"en":"Nervous for days means feeling worried or uneasy for several days after an experience.","zh":"nervous for days 指在一次經歷後好幾天仍感到擔心或不安。"},{"en":"A near accident can make a driver nervous for days.","zh":"差點發生意外可以令司機緊張不安好幾天。"},{"en":"If a story feels too realistic, it may leave children nervous for days.","zh":"如果故事感覺太真實，它可能令孩子緊張不安好幾天。"},{"en":"This phrase shows that an emotional effect lasts beyond the moment.","zh":"這個片語顯示情感影響超越當下。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":14},{"front":"vivid evocation of horror","meaning":"對恐怖的鮮明喚起","examples":[{"en":"A vivid evocation of horror can stay with viewers.","zh":"對恐怖的鮮明喚起可以留在觀眾心中。"},{"en":"A vivid evocation of horror is a powerful presentation that makes fear feel clear and memorable.","zh":"vivid evocation of horror 是一種有力呈現，令恐懼感清楚而難忘。"},{"en":"A dark hallway and sudden silence can create a vivid evocation of horror in a film.","zh":"黑暗走廊和突然的沉默可以在電影中創造對恐怖的鮮明喚起。"},{"en":"Such an evocation may affect viewers because the images feel easy to imagine later.","zh":"這種喚起可能影響觀眾，因為畫面之後很容易想像。"},{"en":"This phrase is formal and describes strong emotional imagery.","zh":"這個片語較正式，描述強烈情感意象。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":14},{"front":"suspend disbelief","meaning":"暫時停止懷疑","examples":[{"en":"Viewers suspend disbelief when they are absorbed by a story.","zh":"當觀眾沉浸於故事時，他們會暫時停止懷疑。"},{"en":"To suspend disbelief means to temporarily accept unreal story events as believable.","zh":"suspend disbelief 指暫時接受故事中的非真實事件為可信。"},{"en":"Children suspend disbelief when they enjoy a cartoon about talking animals.","zh":"孩子享受會說話動物的卡通時，會暫時停止懷疑。"},{"en":"If acting or plot feels false, viewers may stop suspending disbelief.","zh":"如果演技或情節感覺虛假，觀眾可能停止暫時停止懷疑。"},{"en":"This phrase explains how audiences enter fictional worlds.","zh":"這個片語解釋觀眾如何進入虛構世界。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":14},{"front":"be caught in","meaning":"被困於；陷入","examples":[{"en":"The audience is caught in the storyteller’s web.","zh":"觀眾被困於說故事者編織的網中。"},{"en":"To be caught in something means to be trapped, involved, or held by it.","zh":"be caught in something 指被某事困住、捲入或吸引住。"},{"en":"A commuter may be caught in traffic during the morning rush hour.","zh":"通勤者可能在早上繁忙時間被困於交通擠塞中。"},{"en":"A reader can be caught in a mystery and keep reading late into the night.","zh":"讀者可以陷入推理故事中，讀到深夜仍不停。"},{"en":"This phrase can be literal or metaphorical.","zh":"這個片語可以是字面意思，也可以是比喻。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":14},{"front":"be captivated by","meaning":"被……迷住","examples":[{"en":"The audience is captivated by the storyteller’s web.","zh":"觀眾被說故事者編織的網迷住。"},{"en":"To be captivated by something means to be strongly attracted and held by it.","zh":"be captivated by something 指被某事強烈吸引並留住注意力。"},{"en":"Children may be captivated by a teacher who tells history like an adventure.","zh":"如果老師把歷史講得像冒險故事，孩子可能被迷住。"},{"en":"A beautiful song can captivate listeners and make them stop talking.","zh":"美麗歌曲可以迷住聽眾，令他們停止說話。"},{"en":"This phrase describes deep attention and emotional interest.","zh":"這個片語描述深度注意和情感興趣。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":14},{"front":"storyteller’s web","meaning":"說故事者編織的網","examples":[{"en":"A powerful story catches the audience in the storyteller’s web.","zh":"有力量的故事把觀眾困在說故事者編織的網中。"},{"en":"A storyteller’s web is a metaphor for the structure of words, images, and emotions that holds the audience.","zh":"storyteller’s web 是比喻，指由文字、圖像和情感組成、抓住觀眾的結構。"},{"en":"A mystery writer builds a storyteller’s web with clues, secrets, and surprises.","zh":"推理作家用線索、秘密和驚喜建構說故事者編織的網。"},{"en":"If the storyteller’s web is strong, the audience keeps following every detail.","zh":"如果說故事者編織的網很強，觀眾會跟隨每個細節。"},{"en":"This phrase compares storytelling to a net that catches attention.","zh":"這個片語把說故事比作捕捉注意力的網。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":14},{"front":"for a while","meaning":"一段時間內","examples":[{"en":"For a while, the audience believes the story is real.","zh":"一段時間內，觀眾相信故事是真實的。"},{"en":"For a while means for a short or limited period of time.","zh":"for a while 指一段短暫或有限的時間。"},{"en":"After lunch, the baby slept for a while.","zh":"午餐後，嬰兒睡了一段時間。"},{"en":"A problem may disappear for a while but return later if the cause is not fixed.","zh":"如果原因沒有解決，問題可能消失一段時間後再回來。"},{"en":"This phrase shows temporary duration.","zh":"這個片語顯示暫時的持續時間。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":15},{"front":"witness often enough","meaning":"一定經常目睹","examples":[{"en":"Aristotle must have witnessed this reaction often enough.","zh":"Aristotle 一定經常目睹這種反應。"},{"en":"To witness often enough means to see something happen many times, enough to notice a pattern.","zh":"witness often enough 指多次看見某事發生，多到足以注意到模式。"},{"en":"A teacher who has witnessed exam stress often enough learns to recognise early signs.","zh":"經常目睹考試壓力的老師會學會辨認早期跡象。"},{"en":"If doctors witness the same symptoms often enough, they may identify a common cause.","zh":"如果醫生經常目睹相同症狀，可能會找出共同原因。"},{"en":"This phrase suggests repeated observation.","zh":"這個片語暗示重複觀察。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":15},{"front":"taught at Athens","meaning":"在雅典任教","examples":[{"en":"Aristotle taught at Athens, where theatre was important.","zh":"Aristotle 在雅典任教，而那裡戲劇很重要。"},{"en":"Taught at Athens means worked as a teacher or philosopher in the city of Athens.","zh":"taught at Athens 指在雅典這座城市擔任老師或哲學家。"},{"en":"A scholar who taught at Athens was close to an important centre of Greek culture.","zh":"在雅典任教的學者接近希臘文化的重要中心。"},{"en":"Teaching at Athens gave Aristotle access to a society where drama mattered.","zh":"在雅典任教讓 Aristotle 接觸到重視戲劇的社會。"},{"en":"This phrase links a person’s work with a historical place.","zh":"這個片語把一個人的工作與歷史地點連繫起來。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":15},{"front":"develop as","meaning":"發展成為","examples":[{"en":"Theatre developed as a primary form of civic ritual and recreation.","zh":"戲劇發展成為公民儀式和娛樂的主要形式。"},{"en":"To develop as something means to grow into that role or form over time.","zh":"develop as something 指隨時間成長為某種角色或形式。"},{"en":"A small market may develop as a community meeting place.","zh":"小市場可能發展成為社區聚會地點。"},{"en":"Online video developed as a major source of education and entertainment.","zh":"網上影片發展成為教育和娛樂的主要來源。"},{"en":"This phrase shows gradual change into a recognised function.","zh":"這個片語顯示逐漸變成被認可的功能。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":15},{"front":"primary form of","meaning":"主要形式","examples":[{"en":"Theatre became a primary form of civic ritual and recreation.","zh":"戲劇成為公民儀式和娛樂的主要形式。"},{"en":"A primary form of something is one of its main or most important forms.","zh":"primary form of something 指某事物的主要或最重要形式之一。"},{"en":"Public transport is a primary form of travel for many city workers.","zh":"公共交通是許多城市工人的主要出行形式。"},{"en":"If reading is a primary form of learning, students need good access to books.","zh":"如果閱讀是學習的主要形式，學生就需要良好的書籍取得途徑。"},{"en":"This phrase identifies a main way in which something appears or happens.","zh":"這個片語指出某事物出現或發生的主要方式。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":15},{"front":"civic ritual","meaning":"公民儀式","examples":[{"en":"Theatre was part of civic ritual in Athens.","zh":"戲劇是雅典公民儀式的一部分。"},{"en":"Civic ritual means a public ceremony or repeated practice connected with the life of a city or community.","zh":"civic ritual 指與城市或社群生活相關的公共儀式或重複做法。"},{"en":"A flag-raising ceremony can be a civic ritual in some places.","zh":"升旗禮在一些地方可以是公民儀式。"},{"en":"Civic rituals help people feel they belong to a shared public life.","zh":"公民儀式幫助人們感到自己屬於共同公共生活。"},{"en":"This phrase connects ceremony with citizenship and community identity.","zh":"這個片語把儀式與公民身份和社群身份連繫起來。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":15},{"front":"recreation","meaning":"娛樂","examples":[{"en":"Theatre also served as recreation for Athenian audiences.","zh":"戲劇也作為雅典觀眾的娛樂。"},{"en":"Recreation means activities people do for enjoyment, rest, or refreshment.","zh":"recreation 指人們為享受、休息或恢復精神而做的活動。"},{"en":"Playing basketball after school is a form of recreation.","zh":"放學後打籃球是一種娛樂。"},{"en":"Recreation matters because people need breaks from work and study.","zh":"娛樂很重要，因為人們需要從工作和學習中休息。"},{"en":"This word refers to leisure, not paid duty.","zh":"這個詞指休閒，而不是有薪職責。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":15},{"front":"theatrical types of storytelling","meaning":"戲劇式說故事類型","examples":[{"en":"Tragedy and comedy were theatrical types of storytelling.","zh":"悲劇與喜劇是戲劇式說故事類型。"},{"en":"Theatrical types of storytelling are story forms performed on stage for an audience.","zh":"theatrical types of storytelling 是在舞台上為觀眾表演的故事形式。"},{"en":"Musicals, tragedies, comedies, and historical plays are theatrical types of storytelling.","zh":"音樂劇、悲劇、喜劇和歷史劇都是戲劇式說故事類型。"},{"en":"These forms use actors, movement, dialogue, and stage design to tell stories.","zh":"這些形式使用演員、動作、對白和舞台設計來說故事。"},{"en":"This phrase focuses on performance-based storytelling.","zh":"這個片語聚焦於以表演為本的說故事。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":15},{"front":"tragedy and comedy","meaning":"悲劇與喜劇","examples":[{"en":"Tragedy and comedy affected audiences in different ways.","zh":"悲劇與喜劇以不同方式影響觀眾。"},{"en":"Tragedy and comedy are two major dramatic forms, one often serious and sad, the other often humorous.","zh":"tragedy and comedy 是兩種主要戲劇形式，一種通常嚴肅悲傷，另一種通常幽默。"},{"en":"A school play may compare tragedy and comedy to show different emotional effects.","zh":"學校劇可能比較悲劇與喜劇，以顯示不同情感效果。"},{"en":"Tragedy may make viewers reflect on suffering, while comedy may release tension through laughter.","zh":"悲劇可能令觀眾反思苦難，而喜劇可能透過笑聲釋放緊張。"},{"en":"This phrase contrasts two traditional kinds of drama.","zh":"這個片語對比兩種傳統戲劇類型。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":15},{"front":"lose themselves in","meaning":"沉浸於","examples":[{"en":"Athenian audiences lost themselves in sadness and laughter.","zh":"雅典觀眾沉浸於悲傷和笑聲之中。"},{"en":"To lose themselves in something means to become completely absorbed in it.","zh":"lose themselves in something 指完全沉浸於某事。"},{"en":"Readers may lose themselves in a novel during a long train ride.","zh":"讀者可能在長途火車旅程中沉浸於小說。"},{"en":"People lose themselves in music when they forget their worries for a moment.","zh":"當人們暫時忘記煩惱時，他們沉浸於音樂中。"},{"en":"This phrase describes deep emotional or mental involvement.","zh":"這個片語描述深度情感或心理投入。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":15},{"front":"respectively","meaning":"分別地","examples":[{"en":"Tragedy and comedy produced sadness and laughter respectively.","zh":"悲劇與喜劇分別產生悲傷和笑聲。"},{"en":"Respectively means in the same order as the items just mentioned.","zh":"respectively 指按剛提及項目的相同順序分別對應。"},{"en":"Tom and Mary scored 80 and 90 respectively, so Tom scored 80 and Mary scored 90.","zh":"Tom 和 Mary 分別得到80和90分，即 Tom 得80分，Mary 得90分。"},{"en":"The words respectively helps avoid repeating two separate sentences.","zh":"respectively 這個詞幫助避免重複寫兩句句子。"},{"en":"This word is useful when matching two lists in order.","zh":"當按順序配對兩組項目時，這個詞很有用。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":15},{"front":"particularly potent","meaning":"特別有力","examples":[{"en":"Tragedy was particularly potent in moving the audience.","zh":"悲劇在打動觀眾方面特別有力。"},{"en":"Particularly potent means especially powerful or effective.","zh":"particularly potent 指特別有力量或特別有效。"},{"en":"A personal story can be particularly potent in a speech about public health.","zh":"在公共健康演講中，個人故事可以特別有力。"},{"en":"Music is particularly potent when it matches the emotion of a scene.","zh":"當音樂配合場景情緒時，它特別有力。"},{"en":"This phrase describes strong impact, not ordinary usefulness.","zh":"這個片語描述強烈影響，而不是普通有用。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":16},{"front":"capacity to","meaning":"……的能力","examples":[{"en":"Tragedy had a strong capacity to move emotions.","zh":"悲劇有強大的能力去打動情感。"},{"en":"Capacity to do something means ability or power to do it.","zh":"capacity to do something 指做某事的能力或力量。"},{"en":"A good teacher has the capacity to make difficult ideas clear.","zh":"好老師有能力把困難概念講清楚。"},{"en":"Stories have the capacity to change how people see strangers.","zh":"故事有能力改變人們看待陌生人的方式。"},{"en":"This phrase focuses on potential or ability.","zh":"這個片語聚焦於潛能或能力。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":16},{"front":"enlist the emotions","meaning":"調動情感","examples":[{"en":"Tragedy can enlist the emotions of the audience.","zh":"悲劇可以調動觀眾的情感。"},{"en":"To enlist the emotions means to involve people’s feelings in support of a story, idea, or purpose.","zh":"enlist the emotions 指把人們的感情牽涉進故事、想法或目的之中。"},{"en":"A charity video may enlist the emotions of viewers by showing real families.","zh":"慈善影片可能透過展示真實家庭來調動觀眾情感。"},{"en":"If a speech enlists the emotions, listeners may care more deeply about the issue.","zh":"如果演講調動情感，聽眾可能更深切關心議題。"},{"en":"This phrase suggests actively bringing feelings into participation.","zh":"這個片語暗示主動讓情感參與其中。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":16},{"front":"purge the emotions","meaning":"淨化情感","examples":[{"en":"Tragedy can purge the emotions of those watching.","zh":"悲劇可以淨化觀眾的情感。"},{"en":"To purge the emotions means to release or cleanse strong feelings through an experience.","zh":"purge the emotions 指透過某種經歷釋放或清理強烈情感。"},{"en":"Crying during a sad film may help some viewers purge their emotions.","zh":"在悲傷電影中哭泣可能幫助一些觀眾淨化情感。"},{"en":"A powerful play can purge emotions by letting audiences face fear and grief safely.","zh":"有力的戲劇可以讓觀眾安全面對恐懼和悲傷，從而淨化情感。"},{"en":"This phrase is often linked to the emotional effect of tragedy.","zh":"這個片語常與悲劇的情感效果相關。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":16},{"front":"story unfold on the stage","meaning":"故事在舞台上展開","examples":[{"en":"The audience watches the story unfold on the stage.","zh":"觀眾觀看故事在舞台上展開。"},{"en":"When a story unfolds on the stage, its events gradually appear through live performance.","zh":"story unfold on the stage 指故事事件透過現場表演逐步呈現。"},{"en":"In a school play, parents watch the story unfold on the stage scene by scene.","zh":"在學校劇中，家長一幕一幕觀看故事在舞台上展開。"},{"en":"A story unfolds more clearly when actors show changes through action and dialogue.","zh":"當演員透過動作和對白展示變化時，故事會更清楚地展開。"},{"en":"This phrase describes live dramatic development before an audience.","zh":"這個片語描述在觀眾面前的現場戲劇發展。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":16},{"front":"identify factors","meaning":"識別因素","examples":[{"en":"Aristotle tried to identify factors in the storyteller’s art.","zh":"Aristotle 嘗試識別說故事者藝術中的因素。"},{"en":"To identify factors means to find the important causes, parts, or influences in a situation.","zh":"identify factors 指找出某情況中的重要原因、部分或影響。"},{"en":"A doctor tries to identify factors that make a patient’s headaches worse.","zh":"醫生嘗試識別令病人頭痛惡化的因素。"},{"en":"Identifying factors helps people understand why something succeeds or fails.","zh":"識別因素幫助人們理解某事為何成功或失敗。"},{"en":"This phrase is useful in analysis and problem-solving.","zh":"這個片語適用於分析和解決問題。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":16},{"front":"storyteller’s art","meaning":"說故事者的藝術","examples":[{"en":"Aristotle studied the storyteller’s art.","zh":"Aristotle 研究說故事者的藝術。"},{"en":"The storyteller’s art is the skill of shaping a story so that listeners or viewers care about it.","zh":"storyteller’s art 是塑造故事以令聽眾或觀眾在乎它的技巧。"},{"en":"A teacher uses the storyteller’s art when she turns a dry topic into a memorable lesson.","zh":"當老師把沉悶主題變成難忘課堂時，她就在使用說故事者的藝術。"},{"en":"The storyteller’s art depends on timing, detail, emotion, and structure.","zh":"說故事者的藝術取決於時機、細節、情感和結構。"},{"en":"This phrase treats storytelling as a skilled craft.","zh":"這個片語把說故事視為熟練技藝。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":16},{"front":"bring about engagement","meaning":"帶來投入感","examples":[{"en":"Certain techniques bring about emotional engagement.","zh":"某些技巧會帶來情感投入。"},{"en":"To bring about engagement means to cause people to become interested, involved, or emotionally connected.","zh":"bring about engagement 指令人成為感興趣、參與或有情感連結。"},{"en":"Asking students personal questions can bring about engagement in a lesson.","zh":"問學生個人相關問題可以在課堂中帶來投入感。"},{"en":"A film brings about engagement when viewers care about the characters’ choices.","zh":"當觀眾在乎人物選擇時，電影就帶來投入感。"},{"en":"This phrase focuses on creating involvement.","zh":"這個片語聚焦於創造參與。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":16},{"front":"obvious samples for analysis","meaning":"明顯的分析樣本","examples":[{"en":"Greek tragedies provided obvious samples for analysis.","zh":"希臘悲劇提供了明顯的分析樣本。"},{"en":"Obvious samples for analysis are clear examples that can be studied to understand a pattern or idea.","zh":"obvious samples for analysis 是可用來研究模式或概念的清楚例子。"},{"en":"A teacher may use common grammar mistakes as obvious samples for analysis.","zh":"老師可能使用常見文法錯誤作為明顯的分析樣本。"},{"en":"Clear samples make analysis easier because students can see the pattern directly.","zh":"清楚樣本令分析更容易，因為學生能直接看見模式。"},{"en":"This phrase is useful when examples are especially suitable for study.","zh":"當例子特別適合研究時，這個片語很有用。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":16},{"front":"fifth-century BC masterpieces","meaning":"公元前五世紀的傑作","examples":[{"en":"Aristotle analysed fifth-century BC masterpieces of Greek tragedy.","zh":"Aristotle 分析了公元前五世紀的希臘悲劇傑作。"},{"en":"Fifth-century BC masterpieces are outstanding works created between 500 and 401 BC.","zh":"fifth-century BC masterpieces 是公元前500年至公元前401年間創作的傑出作品。"},{"en":"A literature class may study fifth-century BC masterpieces to understand early drama.","zh":"文學課可能研究公元前五世紀的傑作，以理解早期戲劇。"},{"en":"Such masterpieces lasted because later generations continued to value them.","zh":"這些傑作得以留存，是因為後世繼續重視它們。"},{"en":"This phrase combines historical period with high artistic quality.","zh":"這個片語結合歷史時期與高藝術質素。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":16},{"front":"Classical Greek tragedy","meaning":"古典希臘悲劇","examples":[{"en":"Classical Greek tragedy gave Aristotle material for analysis.","zh":"古典希臘悲劇給 Aristotle 提供分析材料。"},{"en":"Classical Greek tragedy is a serious dramatic form from ancient Greece, often involving suffering, fate, and moral conflict.","zh":"Classical Greek tragedy 是來自古希臘的嚴肅戲劇形式，常涉及苦難、命運和道德衝突。"},{"en":"Students study Classical Greek tragedy to understand how ancient drama moved audiences.","zh":"學生研究古典希臘悲劇，以理解古代戲劇如何打動觀眾。"},{"en":"Classical Greek tragedy remains influential because its themes still feel human.","zh":"古典希臘悲劇仍有影響力，因為其主題仍感覺具人性。"},{"en":"This phrase refers to a specific tradition of ancient drama.","zh":"這個片語指古代戲劇的一個特定傳統。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":16},{"front":"written by","meaning":"由……所寫","examples":[{"en":"The tragedies were written by Aeschylus, Sophocles and Euripides.","zh":"這些悲劇由 Aeschylus、Sophocles 和 Euripides 所寫。"},{"en":"Written by means created or composed by a particular writer.","zh":"written by 指由某位特定作者創作或寫成。"},{"en":"A novel written by a famous author may attract readers quickly.","zh":"由著名作者所寫的小說可能很快吸引讀者。"},{"en":"Knowing who a text was written by can help students understand its style and context.","zh":"知道文本由誰所寫，可以幫助學生理解其風格和背景。"},{"en":"This phrase identifies authorship.","zh":"這個片語指出作者身份。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":17},{"front":"beyond them stood Homer","meaning":"在他們之上還有 Homer","examples":[{"en":"Beyond the tragedians stood Homer.","zh":"在這些悲劇作家之上還有 Homer。"},{"en":"Beyond them stood Homer means Homer was seen as an even greater or earlier figure behind those writers.","zh":"beyond them stood Homer 指 Homer 被視為在這些作家背後更偉大或更早的重要人物。"},{"en":"Beyond the modern directors stood older storytellers who shaped their style.","zh":"在現代導演之上，還有塑造他們風格的較古老說故事者。"},{"en":"This phrase places one figure above or behind others in importance.","zh":"這個片語把某個人物放在其他人之上或背後，顯示重要性。"},{"en":"It suggests literary influence and high status.","zh":"它暗示文學影響和崇高地位。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":17},{"front":"canonical status","meaning":"經典地位","examples":[{"en":"Homer’s stories already had canonical status.","zh":"Homer 的故事已經具有經典地位。"},{"en":"Canonical status means being accepted as a classic, authoritative, or central work in a tradition.","zh":"canonical status 指被接受為某傳統中的經典、權威或核心作品。"},{"en":"A book gains canonical status when generations of teachers and readers keep returning to it.","zh":"當一本文學作品被幾代老師和讀者不斷重讀，它便獲得經典地位。"},{"en":"Works with canonical status often influence later writers and education.","zh":"具有經典地位的作品常影響後來作家和教育。"},{"en":"This phrase is common in literature, religion, and cultural studies.","zh":"這個片語常見於文學、宗教和文化研究。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":17},{"front":"The Iliad","meaning":"《伊利亞特》","examples":[{"en":"The Iliad was considered a literary landmark.","zh":"《伊利亞特》被視為文學里程碑。"},{"en":"The Iliad is an ancient Greek epic traditionally attributed to Homer and centred on the Trojan War.","zh":"The Iliad 是一部傳統上歸於 Homer、以特洛伊戰爭為中心的古希臘史詩。"},{"en":"Students read The Iliad to study heroism, anger, honour, and war.","zh":"學生閱讀《伊利亞特》以研究英雄主義、憤怒、榮譽和戰爭。"},{"en":"The Iliad remains important because its characters feel powerful and human.","zh":"《伊利亞特》仍重要，因為其人物既有力量又具人性。"},{"en":"This title is one of the best-known works of ancient epic literature.","zh":"這個書名是古代史詩文學中最著名的作品之一。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":17},{"front":"The Odyssey","meaning":"《奧德賽》","examples":[{"en":"The Odyssey was considered a literary landmark.","zh":"《奧德賽》被視為文學里程碑。"},{"en":"The Odyssey is an ancient Greek epic about Odysseus’s long journey home after the Trojan War.","zh":"The Odyssey 是關於 Odysseus 在特洛伊戰爭後漫長歸家旅程的古希臘史詩。"},{"en":"Students read The Odyssey to study travel, temptation, loyalty, and survival.","zh":"學生閱讀《奧德賽》以研究旅行、誘惑、忠誠和生存。"},{"en":"The Odyssey is memorable because each stage of the journey brings a new test.","zh":"《奧德賽》令人難忘，因為旅程每一階段都帶來新考驗。"},{"en":"This title is often paired with The Iliad in discussions of Homer.","zh":"這個書名在討論 Homer 時常與《伊利亞特》並列。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":17},{"front":"literary landmarks","meaning":"文學里程碑","examples":[{"en":"The Iliad and The Odyssey were literary landmarks.","zh":"《伊利亞特》和《奧德賽》是文學里程碑。"},{"en":"Literary landmarks are works that mark important points in the history of literature.","zh":"literary landmarks 是標誌文學史重要階段的作品。"},{"en":"A novel becomes a literary landmark when it changes how later writers tell stories.","zh":"當小說改變後來作家說故事的方式，它便成為文學里程碑。"},{"en":"Literary landmarks are often taught because they shaped language, style, or ideas.","zh":"文學里程碑常被教授，因為它們塑造了語言、風格或思想。"},{"en":"This phrase suggests lasting importance, not just temporary popularity.","zh":"這個片語暗示持久重要性，而不只是暫時受歡迎。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":17},{"front":"be measured by","meaning":"以……衡量","examples":[{"en":"Other stories were measured by Homer’s stories.","zh":"其他故事以 Homer 的故事作衡量。"},{"en":"To be measured by something means to be judged or compared against it as a standard.","zh":"be measured by something 指以某物作標準來判斷或比較。"},{"en":"New restaurants may be measured by the best local favourite.","zh":"新餐廳可能以本地最受歡迎的餐廳作衡量。"},{"en":"If one work becomes famous, later works may be measured by it.","zh":"如果一部作品成名，後來作品可能以它作衡量。"},{"en":"This phrase shows that something acts as a benchmark.","zh":"這個片語顯示某物作為基準。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":17},{"front":"narrative art","meaning":"敘事藝術","examples":[{"en":"Aristotle wanted to understand Homer’s narrative art.","zh":"Aristotle 想理解 Homer 的敘事藝術。"},{"en":"Narrative art is the skill of shaping a story through plot, character, voice, and structure.","zh":"narrative art 是透過情節、人物、聲音和結構塑造故事的技巧。"},{"en":"A novelist’s narrative art can make ordinary family life feel meaningful.","zh":"小說家的敘事藝術可以令普通家庭生活變得有意義。"},{"en":"Narrative art matters because events alone do not automatically become a good story.","zh":"敘事藝術很重要，因為事件本身不會自動成為好故事。"},{"en":"This phrase describes storytelling as a careful artistic craft.","zh":"這個片語把說故事描述為細緻的藝術技藝。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":17},{"front":"not hard to find","meaning":"不難找到","examples":[{"en":"Homer’s secret was not hard to find.","zh":"Homer 的秘密不難找到。"},{"en":"Not hard to find means easy to discover or identify.","zh":"not hard to find 指容易發現或識別。"},{"en":"The mistake was not hard to find because it appeared in the first line.","zh":"這個錯誤不難找到，因為它出現在第一行。"},{"en":"If the clues are clear, the answer is not hard to find.","zh":"如果線索清楚，答案就不難找到。"},{"en":"This phrase suggests that the explanation is visible once people look carefully.","zh":"這個片語暗示只要仔細看，解釋就很明顯。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":17},{"front":"credible heroes","meaning":"可信的人物英雄","examples":[{"en":"Homer created credible heroes.","zh":"Homer 創造了可信的人物英雄。"},{"en":"Credible heroes are heroic characters who feel believable, not perfect or fake.","zh":"credible heroes 是感覺可信、而不是完美或虛假的英雄人物。"},{"en":"A credible hero may be brave but still afraid before a dangerous choice.","zh":"可信的英雄可能很勇敢，但在危險選擇前仍會害怕。"},{"en":"Viewers care more about credible heroes because they can recognise human feelings in them.","zh":"觀眾更在乎可信的英雄，因為他們能在英雄身上看見人類情感。"},{"en":"This phrase connects heroism with realism.","zh":"這個片語把英雄主義與真實感連接起來。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":17},{"front":"belong to the past","meaning":"屬於過去","examples":[{"en":"Homer’s heroes belonged to the past.","zh":"Homer 的英雄屬於過去。"},{"en":"To belong to the past means to come from an earlier time or to be associated with history.","zh":"belong to the past 指來自較早時期或與歷史相關。"},{"en":"Old farming tools may belong to the past, but they still teach us how people lived.","zh":"舊農具可能屬於過去，但仍教我們人們如何生活。"},{"en":"A story can belong to the past and still speak to modern readers.","zh":"一個故事可以屬於過去，同時仍對現代讀者有意義。"},{"en":"This phrase places something in history while allowing it to remain meaningful.","zh":"這個片語把某物放在歷史中，但仍容許它有意義。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":17},{"front":"mighty and magnificent","meaning":"強大而壯麗","examples":[{"en":"Homer’s heroes were mighty and magnificent.","zh":"Homer 的英雄強大而壯麗。"},{"en":"Mighty and magnificent means powerful, impressive, and grand.","zh":"mighty and magnificent 指有力量、令人印象深刻而宏偉。"},{"en":"A mountain range can look mighty and magnificent at sunrise.","zh":"日出時，山脈可能顯得強大而壯麗。"},{"en":"A hero seems mighty and magnificent when strength is matched with dignity.","zh":"當力量配合尊嚴時，英雄顯得強大而壯麗。"},{"en":"This phrase is elevated and often used for epic description.","zh":"這個片語語氣較高雅，常用於史詩式描寫。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":18},{"front":"fantasy figures","meaning":"幻想人物","examples":[{"en":"The heroes were not mere fantasy figures.","zh":"這些英雄不只是幻想人物。"},{"en":"Fantasy figures are imaginary characters who may feel unreal or disconnected from ordinary life.","zh":"fantasy figures 是想像出來的人物，可能感覺不真實或與普通生活脫節。"},{"en":"A dragon rider can be a fantasy figure, but good writing can still make him emotionally real.","zh":"龍騎士可以是幻想人物，但好寫作仍能令他在情感上真實。"},{"en":"If heroes are only fantasy figures, audiences may admire them but not care about them deeply.","zh":"如果英雄只是幻想人物，觀眾可能欣賞他們，但不會深切在乎。"},{"en":"This phrase contrasts imaginary characters with believable human characters.","zh":"這個片語把想像人物與可信的人性角色作對比。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":18},{"front":"sulk, bicker, cheat and cry","meaning":"鬧脾氣、爭吵、欺騙和哭泣","examples":[{"en":"Homer made his heroes sulk, bicker, cheat and cry.","zh":"Homer 讓他的英雄鬧脾氣、爭吵、欺騙和哭泣。"},{"en":"To sulk, bicker, cheat and cry means to show ordinary human weaknesses such as bad mood, argument, dishonesty, and sadness.","zh":"sulk, bicker, cheat and cry 指展現普通人性弱點，例如心情差、爭吵、不誠實和悲傷。"},{"en":"Children may sulk and bicker when they are tired, but they can still care about each other.","zh":"孩子疲倦時可能鬧脾氣和爭吵，但他們仍可以關心彼此。"},{"en":"Showing heroes sulk, bicker, cheat and cry makes them less perfect and more believable.","zh":"展示英雄鬧脾氣、爭吵、欺騙和哭泣，令他們不那麼完美，更可信。"},{"en":"This list reminds us that strong characters can still behave badly or emotionally.","zh":"這個列表提醒我們，強大人物仍可能行為不好或情緒化。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":18},{"front":"in short","meaning":"簡而言之","examples":[{"en":"In short, Homer’s heroes were real characters.","zh":"簡而言之，Homer 的英雄是真實人物。"},{"en":"In short means to summarise the main point briefly.","zh":"in short 指簡短總結主要重點。"},{"en":"The bus was late, the rain was heavy, and I forgot my umbrella; in short, the morning was terrible.","zh":"巴士遲到、雨很大，而且我忘了帶傘；簡而言之，那個早上很糟。"},{"en":"Writers use in short before giving a simple conclusion after details.","zh":"作者在細節後給出簡單結論前會使用 in short。"},{"en":"This phrase helps readers see the main message quickly.","zh":"這個片語幫助讀者快速看見主要訊息。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":18},{"front":"protagonists","meaning":"主角","examples":[{"en":"The protagonists were characters the audience cared about.","zh":"這些主角是觀眾關心的人物。"},{"en":"Protagonists are the main characters in a story, play, film, or novel.","zh":"protagonists 是故事、戲劇、電影或小說中的主要人物。"},{"en":"In a school story, the protagonist may be a shy student learning to speak up.","zh":"在校園故事中，主角可能是一位學習勇敢發聲的害羞學生。"},{"en":"Strong protagonists make audiences follow the story because their choices matter.","zh":"強大的主角令觀眾跟隨故事，因為他們的選擇很重要。"},{"en":"This word usually refers to central characters, not minor background figures.","zh":"這個詞通常指核心人物，而不是次要背景人物。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":18},{"front":"care about","meaning":"關心；在乎","examples":[{"en":"An audience wants protagonists it can care about.","zh":"觀眾想要他們能關心的主角。"},{"en":"To care about someone means to feel interest, concern, or emotional connection toward them.","zh":"care about someone 指對某人感到興趣、關注或情感連結。"},{"en":"Readers care about a character when they understand the character’s hopes and fears.","zh":"當讀者理解人物的希望和恐懼時，就會關心那個人物。"},{"en":"If viewers do not care about the hero, even exciting action scenes may feel empty.","zh":"如果觀眾不在乎英雄，即使刺激動作場面也可能感覺空洞。"},{"en":"This phrase explains why emotion is important in storytelling.","zh":"這個片語解釋為何情感在說故事中很重要。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":18},{"front":"show a human side","meaning":"展現人性的一面","examples":[{"en":"A strong hero should show a human side.","zh":"強大的英雄應該展現人性的一面。"},{"en":"To show a human side means to reveal ordinary feelings, doubts, mistakes, or weaknesses.","zh":"show a human side 指展示普通情感、疑惑、錯誤或弱點。"},{"en":"A strict manager shows a human side when he admits he once failed too.","zh":"嚴格經理承認自己也曾失敗時，就展現了人性的一面。"},{"en":"Heroes who show a human side feel more believable and easier to care about.","zh":"展現人性一面的英雄感覺更可信，也更容易令人關心。"},{"en":"This phrase helps make powerful people seem relatable.","zh":"這個片語幫助強大人物顯得可親。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":18},{"front":"flaw or weakness","meaning":"缺點或弱點","examples":[{"en":"Aristotle believed a dramatic hero should have a flaw or weakness.","zh":"Aristotle 認為戲劇英雄應該有缺點或弱點。"},{"en":"A flaw or weakness is an imperfect quality that can cause trouble or make a character more human.","zh":"flaw or weakness 是可能造成麻煩或令人物更有人性的缺陷特質。"},{"en":"A hero’s flaw may be pride, impatience, jealousy, or fear.","zh":"英雄的缺點可能是驕傲、急躁、嫉妒或恐懼。"},{"en":"A flaw or weakness creates drama because it can lead to mistakes and growth.","zh":"缺點或弱點創造戲劇性，因為它可以導致錯誤和成長。"},{"en":"This phrase shows why perfect characters are often less interesting.","zh":"這個片語顯示為何完美人物通常較不有趣。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":18},{"front":"mortals are prone to","meaning":"凡人容易有……","examples":[{"en":"Mortals are prone to flaws and weaknesses.","zh":"凡人容易有缺點和弱點。"},{"en":"Mortals are prone to something means ordinary humans are likely to experience it.","zh":"mortals are prone to something 指普通人類容易經歷某事。"},{"en":"Mortals are prone to mistakes when they are tired or under pressure.","zh":"凡人在疲倦或受壓時容易犯錯。"},{"en":"Because people are prone to fear, brave actions can feel meaningful.","zh":"因為人容易害怕，勇敢行動才顯得有意義。"},{"en":"This phrase reminds us that humans are imperfect and vulnerable.","zh":"這個片語提醒我們人類並不完美，而且脆弱。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":18},{"front":"intrinsically dramatic","meaning":"本質上具戲劇性","examples":[{"en":"A flawed hero is intrinsically dramatic.","zh":"有缺陷的英雄本質上具戲劇性。"},{"en":"Intrinsically dramatic means dramatic by its very nature, not because of added decoration.","zh":"intrinsically dramatic 指某事本質上就有戲劇性，而不是因外加裝飾。"},{"en":"A choice between family and duty is intrinsically dramatic because both sides matter.","zh":"家庭與責任之間的選擇本質上具戲劇性，因為兩邊都重要。"},{"en":"A character with a serious weakness is intrinsically dramatic because conflict already exists inside them.","zh":"有嚴重弱點的人物本質上具戲劇性，因為衝突已存在於其內心。"},{"en":"This phrase describes drama built into the situation itself.","zh":"這個片語描述情況本身內建的戲劇性。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":18},{"front":"contains the following information","meaning":"包含以下資料","examples":[{"en":"Students must identify which paragraph contains the following information.","zh":"學生必須識別哪一段包含以下資料。"},{"en":"Contains the following information means includes the details listed after the instruction.","zh":"contains the following information 指包括指示後列出的細節。"},{"en":"In a reading test, students look for the paragraph that contains the following information.","zh":"在閱讀測驗中，學生尋找包含以下資料的段落。"},{"en":"If a paragraph contains the following information, its wording may be different but the meaning matches.","zh":"如果某段包含以下資料，其措辭可能不同，但意思相符。"},{"en":"This phrase is common in matching-information questions.","zh":"這個片語常見於配對資料題。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":18},{"front":"a misunderstanding about","meaning":"關於……的誤解","examples":[{"en":"The question asks about a misunderstanding about a modern form of storytelling.","zh":"這條問題問及關於一種現代說故事形式的誤解。"},{"en":"A misunderstanding about something is an incorrect idea or false impression about it.","zh":"misunderstanding about something 指對某事的錯誤想法或錯誤印象。"},{"en":"There is often a misunderstanding about online learning that it is always easier.","zh":"關於網上學習常有一個誤解，就是它總是較容易。"},{"en":"A misunderstanding about a rule can cause students to answer in the wrong format.","zh":"關於規則的誤解可以導致學生用錯格式作答。"},{"en":"This phrase helps identify an idea that needs correction.","zh":"這個片語幫助指出需要糾正的想法。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":19},{"front":"modern form of storytelling","meaning":"現代說故事形式","examples":[{"en":"Cinema is a modern form of storytelling.","zh":"電影是一種現代說故事形式。"},{"en":"A modern form of storytelling is a recent or contemporary way of presenting stories.","zh":"modern form of storytelling 指較新或當代的故事呈現方式。"},{"en":"Video games can be a modern form of storytelling because players experience the story through choices.","zh":"電子遊戲可以是一種現代說故事形式，因為玩家透過選擇體驗故事。"},{"en":"Modern forms of storytelling often use screens, sound, images, and interactive media.","zh":"現代說故事形式常使用螢幕、聲音、圖像和互動媒介。"},{"en":"This phrase compares newer storytelling methods with older spoken or written forms.","zh":"這個片語把較新的說故事方法與較古老的口頭或書面形式比較。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":19},{"front":"typical forms of storytelling","meaning":"典型說故事形式","examples":[{"en":"The passage discusses typical forms of storytelling such as tragedy and comedy.","zh":"文章討論悲劇和喜劇等典型說故事形式。"},{"en":"Typical forms of storytelling are common or recognised ways stories are presented.","zh":"typical forms of storytelling 是常見或被認可的故事呈現方式。"},{"en":"Fairy tales, films, novels, and stage plays are typical forms of storytelling.","zh":"童話、電影、小說和舞台劇都是典型說故事形式。"},{"en":"Learning typical forms helps students understand what audiences expect.","zh":"學習典型形式幫助學生理解觀眾期望甚麼。"},{"en":"This phrase groups familiar story types together.","zh":"這個片語把熟悉的故事類型歸類在一起。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":19},{"front":"fundamental aim","meaning":"根本目的","examples":[{"en":"The fundamental aim of storytelling is to keep the audience listening.","zh":"說故事的根本目的是令觀眾繼續聽下去。"},{"en":"Fundamental aim means the basic and most important purpose.","zh":"fundamental aim 指基本而最重要的目的。"},{"en":"The fundamental aim of a first-aid course is to help people respond safely in emergencies.","zh":"急救課程的根本目的是幫助人們在緊急情況中安全應對。"},{"en":"If a lesson forgets its fundamental aim, students may remember details but miss the main point.","zh":"如果課堂忘記其根本目的，學生可能記住細節但錯過重點。"},{"en":"This phrase identifies the core goal beneath everything else.","zh":"這個片語指出一切之下的核心目標。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":19},{"front":"recite stories without assistance","meaning":"無輔助地背誦故事","examples":[{"en":"Some storytellers can recite stories without assistance.","zh":"有些說故事的人可以無輔助地背誦故事。"},{"en":"To recite stories without assistance means to tell long stories from memory without notes, books, or prompts.","zh":"recite stories without assistance 指不用筆記、書本或提示，憑記憶講述長故事。"},{"en":"A skilled actor may recite a speech without assistance after weeks of practice.","zh":"熟練演員在數星期練習後，可能無輔助地背誦演講。"},{"en":"Without assistance, a storyteller must rely on memory, rhythm, and structure.","zh":"在沒有輔助下，說故事的人必須依賴記憶、節奏和結構。"},{"en":"This phrase highlights independence in performance.","zh":"這個片語突出表演中的獨立性。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":19},{"front":"make story characters attractive","meaning":"令故事人物吸引","examples":[{"en":"Writers make story characters attractive by giving them human flaws.","zh":"作家透過給予人物人性缺陷來令故事人物吸引。"},{"en":"To make story characters attractive means to make them interesting, believable, or emotionally engaging.","zh":"make story characters attractive 指令人物有趣、可信或有情感吸引力。"},{"en":"A writer can make story characters attractive by giving them clear hopes and fears.","zh":"作家可以透過給人物清晰希望和恐懼來令故事人物吸引。"},{"en":"If characters have no weakness, it may be harder to make them attractive to readers.","zh":"如果人物沒有弱點，可能較難令他們對讀者吸引。"},{"en":"This phrase is about narrative appeal, not only physical beauty.","zh":"這個片語關於敘事吸引力，而不只是外表美。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":19},{"front":"classify the following information","meaning":"將以下資料分類","examples":[{"en":"Students classify the following information according to categories.","zh":"學生根據類別將以下資料分類。"},{"en":"To classify the following information means to put the listed details into correct groups.","zh":"classify the following information 指把列出的細節放入正確組別。"},{"en":"In a science lesson, students classify information about animals into mammals, birds, and reptiles.","zh":"在科學課中，學生把動物資料分類為哺乳類、鳥類和爬行類。"},{"en":"Classification helps students compare details instead of reading them as one long list.","zh":"分類幫助學生比較細節，而不是把它們當成一長串資料閱讀。"},{"en":"This phrase is common in exam instructions and academic tasks.","zh":"這個片語常見於考試指示和學術任務。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":19},{"front":"according to the categories","meaning":"根據所給類別","examples":[{"en":"The information must be classified according to the categories given.","zh":"資料必須根據所給類別分類。"},{"en":"According to the categories means based on the groups or labels provided.","zh":"according to the categories 指根據所提供的組別或標籤。"},{"en":"Students should organise examples according to the categories in the question.","zh":"學生應根據題目中的類別整理例子。"},{"en":"If answers are not placed according to the categories, correct information may still lose marks.","zh":"如果答案沒有根據所給類別放置，即使資料正確仍可能失分。"},{"en":"This phrase tells students to follow the given grouping system.","zh":"這個片語告訴學生跟隨所給分類系統。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":19},{"front":"adopt a writing system","meaning":"採用文字系統","examples":[{"en":"The Greeks adopted a writing system from another country.","zh":"希臘人從另一個國家採用文字系統。"},{"en":"To adopt a writing system means to take and use a set of symbols for recording language.","zh":"adopt a writing system 指採用一套符號來記錄語言。"},{"en":"A society may adopt a writing system to keep trade records and laws.","zh":"一個社會可能採用文字系統來保存貿易記錄和法律。"},{"en":"Adopting a writing system can change education because words can be stored outside memory.","zh":"採用文字系統可以改變教育，因為文字可以儲存在記憶之外。"},{"en":"This phrase describes cultural borrowing and practical adaptation.","zh":"這個片語描述文化借用和實際改造。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":19},{"front":"from another country","meaning":"從另一個國家","examples":[{"en":"The alphabet was adopted from another country.","zh":"這套字母系統是從另一個國家採用的。"},{"en":"From another country means coming from a nation different from one’s own.","zh":"from another country 指來自不同於自己國家的地方。"},{"en":"A school may invite a teacher from another country to share new teaching methods.","zh":"學校可能邀請來自另一個國家的老師分享新教學方法。"},{"en":"Ideas from another country can be adapted to fit local needs.","zh":"從另一個國家來的想法可以被改造以配合本地需要。"},{"en":"This phrase shows foreign origin, not necessarily foreign control.","zh":"這個片語顯示外來來源，但不一定代表外來控制。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":19},{"front":"organic materials","meaning":"有機材料","examples":[{"en":"Some cultures used organic materials to record stories.","zh":"一些文化使用有機材料記錄故事。"},{"en":"Organic materials are natural materials from living things, such as bark, leaves, wood, or animal skin.","zh":"organic materials 是來自生物的天然材料，例如樹皮、葉子、木材或動物皮。"},{"en":"Before paper was common, people wrote on organic materials available in their environment.","zh":"在紙張普及前，人們在環境中可取得的有機材料上書寫。"},{"en":"Organic materials can decay, so records made from them may be lost unless carefully preserved.","zh":"有機材料會腐爛，因此用它們製成的紀錄若不小心保存可能會遺失。"},{"en":"This phrase contrasts natural materials with metal, stone, or modern synthetic materials.","zh":"這個片語對比天然材料與金屬、石頭或現代合成材料。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":19},{"front":"record stories","meaning":"記錄故事","examples":[{"en":"Organic materials were used to record stories.","zh":"有機材料被用來記錄故事。"},{"en":"To record stories means to preserve them in writing, images, sound, or other lasting forms.","zh":"record stories 指用文字、圖像、聲音或其他持久形式保存故事。"},{"en":"A family may record stories from grandparents before those memories disappear.","zh":"家庭可能在祖父母的記憶消失前記錄他們的故事。"},{"en":"Recording stories helps later generations learn what earlier people believed and experienced.","zh":"記錄故事幫助後代學習早期人們相信和經歷過甚麼。"},{"en":"This phrase focuses on preserving stories beyond the moment of telling.","zh":"這個片語聚焦於把故事保存到講述當下以後。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":20},{"front":"use tools to help","meaning":"使用工具協助","examples":[{"en":"Some communities used tools to help tell stories.","zh":"一些社群使用工具協助講故事。"},{"en":"To use tools to help means to rely on objects or devices for support in doing a task.","zh":"use tools to help 指依靠物件或裝置支援完成任務。"},{"en":"Students use flashcards to help remember new vocabulary.","zh":"學生使用字卡協助記住新詞彙。"},{"en":"A storyteller may use tools to help keep the correct order of events.","zh":"說故事的人可能使用工具協助保持事件的正確順序。"},{"en":"This phrase shows that memory and performance can be supported by practical objects.","zh":"這個片語顯示記憶和表演可以由實用物件支援。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":20},{"front":"complete the sentences below","meaning":"完成以下句子","examples":[{"en":"Students must complete the sentences below with words from the passage.","zh":"學生必須用文章中的字詞完成以下句子。"},{"en":"Complete the sentences below means fill the blanks in the following sentences.","zh":"complete the sentences below 指填寫下面句子中的空格。"},{"en":"In reading tests, students complete the sentences below by finding exact words in the text.","zh":"在閱讀測驗中，學生透過在文本中找出準確字詞完成以下句子。"},{"en":"To complete the sentences below correctly, students must check grammar and meaning.","zh":"要正確完成以下句子，學生必須檢查文法和意思。"},{"en":"This instruction asks for careful reading rather than personal opinion.","zh":"這個指示要求細心閱讀，而不是個人意見。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":20},{"front":"one word only","meaning":"只限一個詞","examples":[{"en":"The answers must use one word only from the passage.","zh":"答案必須只使用文章中的一個詞。"},{"en":"One word only means the answer must contain exactly one word, not two or more.","zh":"one word only 指答案必須只包含一個詞，而不是兩個或更多。"},{"en":"If the instruction says one word only, writing a short phrase can lose marks.","zh":"如果指示說只限一個詞，寫短語可能會失分。"},{"en":"Students should copy one word only from the passage and avoid adding articles.","zh":"學生應只從文章中抄一個詞，並避免加入冠詞。"},{"en":"This phrase sets a strict answer limit.","zh":"這個片語設定嚴格答案限制。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":20},{"front":"art of storytelling","meaning":"說故事的藝術","examples":[{"en":"Aristotle wrote about the art of storytelling.","zh":"Aristotle 寫過關於說故事的藝術。"},{"en":"Art of storytelling means the skill of making stories interesting, meaningful, and well-structured.","zh":"art of storytelling 指令故事有趣、有意義並結構良好的技巧。"},{"en":"A teacher uses the art of storytelling when she turns facts into a memorable lesson.","zh":"當老師把事實變成難忘課堂時，她就在使用說故事的藝術。"},{"en":"The art of storytelling improves when writers learn how to build suspense and character.","zh":"當作家學會如何建立懸念和人物，說故事的藝術就會提升。"},{"en":"This phrase treats storytelling as a craft that can be learned.","zh":"這個片語把說故事視為可以學習的技藝。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":20},{"front":"powerful type of story","meaning":"有感染力的故事類型","examples":[{"en":"Aristotle saw tragedy as a powerful type of story.","zh":"Aristotle 把悲劇視為一種有感染力的故事類型。"},{"en":"A powerful type of story is a story form that strongly affects the audience’s thoughts or emotions.","zh":"powerful type of story 指能強烈影響觀眾思想或情感的故事形式。"},{"en":"A personal survival story can be a powerful type of story in a public speech.","zh":"個人生還故事在公開演講中可以是一種有感染力的故事類型。"},{"en":"Tragedy is powerful because it can make people feel fear, pity, and reflection.","zh":"悲劇有力量，因為它可以令人感到恐懼、憐憫和反思。"},{"en":"This phrase describes emotional force, not only popularity.","zh":"這個片語描述情感力量，而不只是受歡迎程度。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":20},{"front":"move an audience","meaning":"打動觀眾","examples":[{"en":"A powerful story can move an audience deeply.","zh":"有感染力的故事可以深深打動觀眾。"},{"en":"To move an audience means to affect their emotions strongly.","zh":"move an audience 指強烈影響觀眾的情感。"},{"en":"A speech about a real family can move an audience more than statistics alone.","zh":"關於真實家庭的演講可以比單靠統計更打動觀眾。"},{"en":"Films move audiences when viewers care about the characters’ suffering and choices.","zh":"當觀眾在乎人物的痛苦和選擇，電影就能打動觀眾。"},{"en":"This phrase is about emotional impact, not physical movement.","zh":"這個片語關於情感影響，而不是身體移動。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":20},{"front":"regard something as","meaning":"將……視為","examples":[{"en":"Aristotle regarded Homer’s works as important models.","zh":"Aristotle 將 Homer 的作品視為重要典範。"},{"en":"To regard something as means to consider or think of it in a particular way.","zh":"regard something as 指以某種方式看待或認為某事物。"},{"en":"Many students regard regular practice as the safest way to improve.","zh":"許多學生將定期練習視為進步的最穩妥方法。"},{"en":"A company may regard customer trust as its most valuable asset.","zh":"公司可能將顧客信任視為最有價值的資產。"},{"en":"This phrase describes judgement, opinion, or attitude.","zh":"這個片語描述判斷、意見或態度。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":20},{"front":"attractive heroes","meaning":"吸引人的英雄人物","examples":[{"en":"Attractive heroes should have some human weakness.","zh":"吸引人的英雄人物應該有某些人性弱點。"},{"en":"Attractive heroes are heroic characters who make audiences interested in them and care about them.","zh":"attractive heroes 是令觀眾對他們感興趣並在乎他們的英雄人物。"},{"en":"An attractive hero may be brave, but also lonely, proud, afraid, or unsure.","zh":"吸引人的英雄可能勇敢，但也孤獨、驕傲、害怕或不確定。"},{"en":"Human weakness makes attractive heroes more believable because they are not perfect statues.","zh":"人性弱點令吸引人的英雄人物更可信，因為他們不是完美雕像。"},{"en":"This phrase refers to narrative appeal, not only physical attractiveness.","zh":"這個片語指敘事吸引力，而不只是外表吸引。"}],"source":"152 - Ancient Storytelling.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 153":[{"front":"British architecture","meaning":"英國建築","examples":[{"en":"The passage traces the development of British architecture from Roman times to post-modernism.","zh":"這篇文章追溯英國建築從羅馬時期到後現代主義的發展。"},{"en":"British architecture refers to the buildings and building styles developed in Britain over time.","zh":"英國建築是指英國隨時間發展出來的建築物和建築風格。"},{"en":"Castles, cathedrals, country houses, and modern housing estates are all part of British architecture.","zh":"城堡、大教堂、鄉村大宅和現代住宅屋邨都是英國建築的一部分。"},{"en":"Changes in politics, technology, wealth, and society have shaped British architecture.","zh":"政治、科技、財富和社會的變化塑造了英國建築。"},{"en":"British architecture shows that buildings often reflect both practical needs and cultural values.","zh":"英國建築顯示，建築物常反映實際需要和文化價值。"}],"source":"153 - British Architecture.pdf","sourcePage":1},{"front":"architecture is about evolution, not revolution","meaning":"建築講求演變，而非革命","examples":[{"en":"Architecture is about evolution, not revolution.","zh":"建築講求演變，而非革命。"},{"en":"This means architecture usually changes gradually rather than suddenly replacing everything before it.","zh":"這句話意思是建築通常逐步改變，而不是突然完全取代之前的一切。"},{"en":"A city may keep old streets while adding new stations, showing evolution rather than revolution.","zh":"一個城市可能保留舊街道，同時加入新車站，顯示演變而非革命。"},{"en":"When architects learn from earlier styles, buildings develop step by step.","zh":"當建築師從早期風格學習，建築物便會一步一步發展。"},{"en":"The phrase reminds us that design often grows from the past instead of destroying it.","zh":"這句話提醒我們，設計常從過去生長出來，而不是摧毀過去。"}],"source":"153 - British Architecture.pdf","sourcePage":1},{"front":"used to be thought that","meaning":"過去人們認為","examples":[{"en":"It used to be thought that Roman buildings simply fell into decay.","zh":"過去人們認為羅馬建築只是逐漸衰敗。"},{"en":"“It used to be thought that” introduces an old belief that people may no longer fully accept.","zh":"“It used to be thought that” 用來引出一個舊有看法，而人們現在未必完全接受。"},{"en":"It used to be thought that children learned best only by memorising rules.","zh":"過去人們認為孩子只靠背誦規則學得最好。"},{"en":"New evidence can show that what used to be thought was too simple.","zh":"新證據可以顯示，過去人們認為的事情過於簡單。"},{"en":"This phrase is useful when comparing past opinions with newer understanding.","zh":"這個片語適合用來比較過去觀點和較新的理解。"}],"source":"153 - British Architecture.pdf","sourcePage":1},{"front":"the Romans pulled out of","meaning":"羅馬人撤出……","examples":[{"en":"The Romans pulled out of Britain in the fifth century.","zh":"羅馬人在五世紀撤出不列顛。"},{"en":"To pull out of a place means to leave it, especially after controlling or occupying it.","zh":"To pull out of a place 指離開某地，尤其是在曾控制或佔領該地之後。"},{"en":"A company may pull out of a market if it keeps losing money there.","zh":"如果公司在某市場持續虧損，可能會撤出該市場。"},{"en":"When an army pulls out of a region, local power structures may change quickly.","zh":"當軍隊撤出某地區，本地權力結構可能迅速改變。"},{"en":"The phrase often suggests an organised withdrawal rather than a casual departure.","zh":"這個片語常暗示有組織的撤離，而不是隨便離開。"}],"source":"153 - British Architecture.pdf","sourcePage":1},{"front":"in the fifth century","meaning":"在五世紀","examples":[{"en":"The Romans left Britain in the fifth century.","zh":"羅馬人在五世紀離開不列顛。"},{"en":"In the fifth century means during the years from 401 to 500.","zh":"In the fifth century 指在401年至500年之間。"},{"en":"Many historical events are dated by century when the exact year is less important.","zh":"當確切年份不太重要時，許多歷史事件會用世紀標示。"},{"en":"If a church was built in the fifth century, it is more than 1,500 years old today.","zh":"如果一座教堂建於五世紀，它今天已有超過一千五百年歷史。"},{"en":"This phrase places an event in a broad historical period.","zh":"這個片語把事件放在一個較廣闊的歷史時期中。"}],"source":"153 - British Architecture.pdf","sourcePage":1},{"front":"elegant villas","meaning":"優雅別墅","examples":[{"en":"The Romans left behind elegant villas and carefully planned towns.","zh":"羅馬人留下了優雅別墅和精心規劃的城鎮。"},{"en":"Elegant villas are large, graceful houses, often built for wealthy people.","zh":"優雅別墅是大型而美觀的住宅，通常為富有人家而建。"},{"en":"A seaside town may contain elegant villas with gardens, columns, and wide windows.","zh":"海邊小鎮可能有帶花園、柱子和寬大窗戶的優雅別墅。"},{"en":"Elegant villas can show the wealth and taste of the people who built them.","zh":"優雅別墅可以展示建造者的財富和品味。"},{"en":"The phrase suggests beauty, comfort, and social status.","zh":"這個片語暗示美感、舒適和社會地位。"}],"source":"153 - British Architecture.pdf","sourcePage":1},{"front":"carefully planned towns","meaning":"精心規劃的城鎮","examples":[{"en":"Romano-British culture included carefully planned towns.","zh":"羅馬化不列顛文化包括精心規劃的城鎮。"},{"en":"Carefully planned towns are towns designed with organised streets, buildings, and public spaces.","zh":"精心規劃的城鎮是指街道、建築和公共空間經過有組織設計的城鎮。"},{"en":"A carefully planned town may have clear roads, markets, schools, and drainage systems.","zh":"精心規劃的城鎮可能有清晰道路、市場、學校和排水系統。"},{"en":"Good planning can make towns safer, cleaner, and easier to move around in.","zh":"良好規劃可以令城鎮更安全、更清潔，也更容易通行。"},{"en":"The phrase contrasts with towns that grow randomly without much design.","zh":"這個片語與沒有太多設計、隨意發展的城鎮形成對比。"}],"source":"153 - British Architecture.pdf","sourcePage":1},{"front":"engineering marvels","meaning":"工程奇蹟","examples":[{"en":"Hadrian’s Wall was one of the engineering marvels left by the Romans.","zh":"哈德良長城是羅馬人留下的工程奇蹟之一。"},{"en":"Engineering marvels are structures that impress people because they are difficult and skilfully built.","zh":"工程奇蹟是指因建造困難而技術精湛，令人印象深刻的結構。"},{"en":"A long bridge over deep water can be an engineering marvel.","zh":"橫跨深水的長橋可以是一項工程奇蹟。"},{"en":"Engineering marvels often require careful planning, strong materials, and advanced knowledge.","zh":"工程奇蹟通常需要仔細規劃、堅固材料和先進知識。"},{"en":"The phrase praises both the design and the technical achievement.","zh":"這個片語讚揚設計和技術成就。"}],"source":"153 - British Architecture.pdf","sourcePage":1},{"front":"Hadrian’s Wall","meaning":"哈德良長城","examples":[{"en":"Hadrian’s Wall is mentioned as a Roman engineering marvel.","zh":"哈德良長城被提及為羅馬工程奇蹟。"},{"en":"Hadrian’s Wall is an ancient Roman wall built across northern Britain.","zh":"哈德良長城是一道橫跨不列顛北部的古羅馬城牆。"},{"en":"Tourists visit Hadrian’s Wall to see how Roman military power shaped the landscape.","zh":"遊客參觀哈德良長城，以了解羅馬軍事力量如何塑造景觀。"},{"en":"The wall survived because stone structures can last far longer than wooden buildings.","zh":"這道牆能保存下來，是因為石造結構比木造建築更能長久存在。"},{"en":"In British history, Hadrian’s Wall is a famous sign of Roman influence.","zh":"在英國歷史中，哈德良長城是羅馬影響的著名象徵。"}],"source":"153 - British Architecture.pdf","sourcePage":1},{"front":"fell into decay","meaning":"衰敗；失修","examples":[{"en":"Some people believed that Roman buildings fell into decay after the Roman withdrawal.","zh":"有些人相信羅馬人撤離後，羅馬建築便衰敗失修。"},{"en":"To fall into decay means to become damaged, weak, or ruined because of neglect and time.","zh":"To fall into decay 指因被忽視和時間流逝而變得破損、脆弱或荒廢。"},{"en":"An empty cinema may fall into decay if no one repairs the roof or walls.","zh":"如果沒有人維修屋頂或牆壁，一間空置戲院可能會失修。"},{"en":"Buildings fall into decay when maintenance stops for many years.","zh":"當維護多年停止，建築物便會衰敗。"},{"en":"The phrase suggests slow decline, not sudden destruction.","zh":"這個片語暗示緩慢衰落，而不是突然毀滅。"}],"source":"153 - British Architecture.pdf","sourcePage":1},{"front":"was plunged into","meaning":"被推入；陷入","examples":[{"en":"British culture was once thought to have been plunged into the Dark Ages.","zh":"英國文化曾被認為陷入黑暗時代。"},{"en":"To be plunged into something means to be suddenly forced into a difficult or negative situation.","zh":"To be plunged into something 指突然被迫進入困難或負面的情況。"},{"en":"A family may be plunged into financial trouble after losing its main income.","zh":"一個家庭失去主要收入後，可能陷入財政困難。"},{"en":"A city can be plunged into chaos after a major power failure.","zh":"大停電後，城市可能陷入混亂。"},{"en":"The phrase is dramatic and suggests a sharp fall into trouble.","zh":"這個片語語氣強烈，暗示突然跌入困境。"}],"source":"153 - British Architecture.pdf","sourcePage":1},{"front":"the Dark Ages","meaning":"黑暗時代","examples":[{"en":"Some historians once believed Britain entered the Dark Ages after the Romans left.","zh":"有些歷史學家曾相信羅馬人離開後，英國進入黑暗時代。"},{"en":"The Dark Ages usually refers to an early medieval period seen as having less learning or fewer records.","zh":"黑暗時代通常指被視為學問較少或紀錄較少的中世紀早期。"},{"en":"People use the term when they think a society has lost order, knowledge, or cultural activity.","zh":"當人們認為一個社會失去秩序、知識或文化活動時，會使用這個詞。"},{"en":"Modern historians often question simple ideas about the Dark Ages.","zh":"現代歷史學家常質疑對黑暗時代的簡單看法。"},{"en":"The phrase can be useful, but it may oversimplify a complex period.","zh":"這個片語可以有用，但可能過度簡化複雜時期。"}],"source":"153 - British Architecture.pdf","sourcePage":2},{"front":"the Norman Conquest","meaning":"諾曼征服","examples":[{"en":"The Norman Conquest of 1066 is often linked with cultural revival.","zh":"1066年的諾曼征服常與文化復興聯繫起來。"},{"en":"The Norman Conquest was the takeover of England by the Normans in 1066.","zh":"諾曼征服是指諾曼人在1066年接管英格蘭。"},{"en":"The Norman Conquest changed English politics, language, law, and architecture.","zh":"諾曼征服改變了英格蘭的政治、語言、法律和建築。"},{"en":"After conquest, new rulers often build castles and churches to show power.","zh":"征服之後，新統治者常建造城堡和教堂以展示權力。"},{"en":"This event is a major turning point in British history.","zh":"這件事是英國歷史上的重大轉折點。"}],"source":"153 - British Architecture.pdf","sourcePage":2},{"front":"bring back the light","meaning":"帶回光明；帶來復興","examples":[{"en":"Some people thought the Norman Conquest helped bring back the light.","zh":"有些人認為諾曼征服幫助帶回光明。"},{"en":"To bring back the light means to restore knowledge, culture, order, or hope after a dark period.","zh":"To bring back the light 指在黑暗時期後恢復知識、文化、秩序或希望。"},{"en":"A rebuilt library can bring back the light to a community after a disaster.","zh":"災難後重建的圖書館可以為社區帶回光明。"},{"en":"Good teachers can bring back the light for students who have lost confidence.","zh":"好老師可以為失去信心的學生帶回光明。"},{"en":"The phrase is metaphorical and suggests cultural or moral revival.","zh":"這個片語是比喻用法，暗示文化或精神復興。"}],"source":"153 - British Architecture.pdf","sourcePage":2},{"front":"Gothic cathedral builders","meaning":"哥德式大教堂建造者","examples":[{"en":"Gothic cathedral builders played an important role in medieval culture.","zh":"哥德式大教堂建造者在中世紀文化中扮演重要角色。"},{"en":"Gothic cathedral builders were people who designed and constructed large medieval churches in the Gothic style.","zh":"哥德式大教堂建造者是設計並建造哥德式大型中世紀教堂的人。"},{"en":"They used pointed arches, tall towers, and stained glass to create impressive religious spaces.","zh":"他們使用尖拱、高塔和彩色玻璃創造令人印象深刻的宗教空間。"},{"en":"Cathedral building required skilled workers, money, faith, and long-term planning.","zh":"建造大教堂需要熟練工人、金錢、信仰和長期規劃。"},{"en":"The phrase highlights the people behind some of Europe’s most famous medieval buildings.","zh":"這個片語突顯歐洲一些最著名中世紀建築背後的人。"}],"source":"153 - British Architecture.pdf","sourcePage":2},{"front":"the Middle Ages","meaning":"中世紀","examples":[{"en":"The Gothic cathedral builders of the Middle Ages helped revive British culture.","zh":"中世紀的哥德式大教堂建造者幫助復興英國文化。"},{"en":"The Middle Ages refers to the period of European history between the ancient and modern worlds.","zh":"中世紀是指歐洲歷史中古代世界和近代世界之間的時期。"},{"en":"Castles, monasteries, and cathedrals are often associated with the Middle Ages.","zh":"城堡、修道院和大教堂常與中世紀相關。"},{"en":"The Middle Ages were not simply backward; they produced major religious and architectural achievements.","zh":"中世紀並不只是落後；它也產生了重大宗教和建築成就。"},{"en":"This phrase places people and buildings in a medieval historical context.","zh":"這個片語把人物和建築放在中世紀歷史背景中。"}],"source":"153 - British Architecture.pdf","sourcePage":2},{"front":"played an important part in","meaning":"在……中扮演重要角色","examples":[{"en":"Gothic cathedral builders played an important part in the revival of British culture.","zh":"哥德式大教堂建造者在英國文化復興中扮演重要角色。"},{"en":"To play an important part in something means to help make it happen or develop.","zh":"To play an important part in something 指幫助某事發生或發展。"},{"en":"Parents play an important part in a child’s early language development.","zh":"父母在孩子早期語言發展中扮演重要角色。"},{"en":"Public transport plays an important part in reducing traffic in large cities.","zh":"公共交通在減少大城市交通擠塞中扮演重要角色。"},{"en":"The phrase shows contribution, not complete control.","zh":"這個片語表示貢獻，而不是完全控制。"}],"source":"153 - British Architecture.pdf","sourcePage":2},{"front":"the revival of","meaning":"……的復興","examples":[{"en":"The Norman Conquest is often associated with the revival of British culture.","zh":"諾曼征服常與英國文化的復興相關。"},{"en":"The revival of something means its return, recovery, or renewed popularity after decline.","zh":"The revival of something 指某事在衰落後恢復、復甦或重新流行。"},{"en":"The revival of a local market can bring people back to an old neighbourhood.","zh":"本地市場的復興可以把人帶回舊社區。"},{"en":"A revival of traditional crafts may happen when young people learn old skills again.","zh":"當年輕人重新學習舊技能，傳統工藝可能出現復興。"},{"en":"The phrase suggests something was weakened but became active again.","zh":"這個片語暗示某事曾變弱，但後來再次活躍。"}],"source":"153 - British Architecture.pdf","sourcePage":2},{"front":"the truth is not as simple as that","meaning":"事實並非那麼簡單","examples":[{"en":"The truth about British architectural history is not as simple as that.","zh":"英國建築史的事實並非那麼簡單。"},{"en":"This phrase means the real situation is more complicated than the simple explanation given.","zh":"這個片語意思是真實情況比剛才提出的簡單解釋更複雜。"},{"en":"Some people blame students for poor results, but the truth is not as simple as that.","zh":"有些人把成績差歸咎於學生，但事實並非那麼簡單。"},{"en":"A problem may involve money, family, health, and school, so it cannot be explained in one sentence.","zh":"一個問題可能涉及金錢、家庭、健康和學校，所以不能用一句話解釋。"},{"en":"The phrase warns readers not to accept an easy answer too quickly.","zh":"這個片語提醒讀者不要太快接受簡單答案。"}],"source":"153 - British Architecture.pdf","sourcePage":2},{"front":"Romano-British culture","meaning":"羅馬化不列顛文化","examples":[{"en":"Romano-British culture survived long after the Roman withdrawal.","zh":"羅馬化不列顛文化在羅馬人撤離後仍長久存在。"},{"en":"Romano-British culture refers to the mixed culture of Roman and native British life.","zh":"羅馬化不列顛文化是指羅馬生活與本土不列顛生活混合而成的文化。"},{"en":"It could include Roman-style towns, roads, religion, language, and ways of organising society.","zh":"它可以包括羅馬式城鎮、道路、宗教、語言和社會組織方式。"},{"en":"Cultures often continue even after the rulers who introduced them leave.","zh":"文化常在引入它的統治者離開後仍繼續存在。"},{"en":"The phrase shows that Roman influence in Britain did not disappear immediately.","zh":"這個片語顯示羅馬在不列顛的影響沒有立即消失。"}],"source":"153 - British Architecture.pdf","sourcePage":2},{"front":"along with","meaning":"連同；以及","examples":[{"en":"Architecture survived along with language, religion and the arts.","zh":"建築連同語言、宗教和藝術一起保存下來。"},{"en":"Along with means together with or in addition to something else.","zh":"Along with 指連同、以及或加上其他事物。"},{"en":"A student should bring a notebook along with a pen to class.","zh":"學生上課應帶筆記簿以及一支筆。"},{"en":"Good transport, along with safe streets, can improve community life.","zh":"良好交通連同安全街道，可以改善社區生活。"},{"en":"The phrase helps add related items without making a separate sentence.","zh":"這個片語有助加入相關項目，而不用另寫一句。"}],"source":"153 - British Architecture.pdf","sourcePage":2},{"front":"political organisation","meaning":"政治組織","examples":[{"en":"Romano-British culture included political organisation as well as architecture.","zh":"羅馬化不列顛文化不只包括建築，也包括政治組織。"},{"en":"Political organisation means the way power, leadership, law, and government are arranged.","zh":"政治組織是指權力、領導、法律和政府如何被安排。"},{"en":"A school council is a simple form of political organisation inside a school.","zh":"學生會是一所學校內簡單形式的政治組織。"},{"en":"Strong political organisation can help a society collect taxes, build roads, and keep order.","zh":"強大的政治組織可以幫助社會徵稅、建路和維持秩序。"},{"en":"The phrase is about how people organise authority, not just party politics.","zh":"這個片語關乎人們如何組織權威，而不只是政黨政治。"}],"source":"153 - British Architecture.pdf","sourcePage":2},{"front":"survived long after","meaning":"在……之後仍長久存在","examples":[{"en":"Romano-British culture survived long after the Roman withdrawal.","zh":"羅馬化不列顛文化在羅馬人撤離後仍長久存在。"},{"en":"To survive long after something means to continue existing for a long time after that event ends.","zh":"To survive long after something 指在某事件結束後仍長時間繼續存在。"},{"en":"A family tradition may survive long after the grandparents who began it have died.","zh":"家庭傳統可能在創立它的祖父母去世後仍長久存在。"},{"en":"Old street names can survive long after the original buildings disappear.","zh":"舊街名可以在原本建築消失後仍長久存在。"},{"en":"The phrase shows continuity beyond a major change.","zh":"這個片語顯示重大變化之後仍有延續性。"}],"source":"153 - British Architecture.pdf","sourcePage":3},{"front":"the Roman withdrawal","meaning":"羅馬人撤離","examples":[{"en":"Architecture continued to develop after the Roman withdrawal.","zh":"建築在羅馬人撤離後繼續發展。"},{"en":"The Roman withdrawal means the period when Roman forces and officials left Britain.","zh":"The Roman withdrawal 指羅馬軍隊和官員離開不列顛的時期。"},{"en":"After the Roman withdrawal, local communities had to adapt to new political conditions.","zh":"羅馬人撤離後，本地社區必須適應新的政治條件。"},{"en":"A withdrawal of a ruling power can change defence, trade, language, and building styles.","zh":"統治力量撤離可以改變防衛、貿易、語言和建築風格。"},{"en":"The phrase marks a historical turning point, but not necessarily a complete cultural break.","zh":"這個片語標誌歷史轉折，但不一定代表文化完全斷裂。"}],"source":"153 - British Architecture.pdf","sourcePage":3},{"front":"although","meaning":"雖然","examples":[{"en":"Although the Anglo-Saxons had a sophisticated building style, little survives today.","zh":"雖然盎格魯撒克遜人有精巧的建築風格，但今天留存下來的很少。"},{"en":"Although introduces a contrast between two facts.","zh":"Although 用來引出兩個事實之間的對比。"},{"en":"Although the lesson was difficult, the examples made it easier to understand.","zh":"雖然課堂很難，但例子令內容較易理解。"},{"en":"Although a shop is small, it can still serve customers well.","zh":"雖然商店很小，它仍能好好服務顧客。"},{"en":"This word helps show that one fact does not cancel the other.","zh":"這個詞有助顯示一個事實不會抵消另一個事實。"}],"source":"153 - British Architecture.pdf","sourcePage":3},{"front":"the Anglo-Saxons","meaning":"盎格魯撒克遜人","examples":[{"en":"The Anglo-Saxons had a sophisticated building style of their own.","zh":"盎格魯撒克遜人有屬於自己的精巧建築風格。"},{"en":"The Anglo-Saxons were Germanic peoples who settled in England after Roman rule weakened.","zh":"盎格魯撒克遜人是在羅馬統治削弱後定居英格蘭的日耳曼民族。"},{"en":"Their culture influenced English language, law, settlement patterns, and early medieval buildings.","zh":"他們的文化影響英語、法律、聚落模式和中世紀早期建築。"},{"en":"Because many Anglo-Saxon buildings were wooden, few survive clearly today.","zh":"因為許多盎格魯撒克遜建築是木造的，今天清楚保存下來的很少。"},{"en":"The phrase is important in early English history.","zh":"這個片語在早期英格蘭歷史中很重要。"}],"source":"153 - British Architecture.pdf","sourcePage":3},{"front":"sophisticated building style","meaning":"精巧的建築風格","examples":[{"en":"The Anglo-Saxons had a sophisticated building style.","zh":"盎格魯撒克遜人有精巧的建築風格。"},{"en":"A sophisticated building style is advanced, carefully designed, and not simple or crude.","zh":"精巧的建築風格是先進、仔細設計，而不是簡單粗糙的風格。"},{"en":"A museum with clever lighting, natural ventilation, and balanced spaces may show a sophisticated building style.","zh":"一座有巧妙照明、自然通風和均衡空間的博物館，可能展現精巧的建築風格。"},{"en":"Sophisticated design can exist even when the materials are simple.","zh":"即使用料簡單，設計也可以很精巧。"},{"en":"The phrase warns us not to judge old buildings only by what survives today.","zh":"這個片語提醒我們，不要只根據今天保存下來的東西判斷古代建築。"}],"source":"153 - British Architecture.pdf","sourcePage":3},{"front":"of their own","meaning":"屬於自己的","examples":[{"en":"The Anglo-Saxons had a building style of their own.","zh":"盎格魯撒克遜人有屬於自己的建築風格。"},{"en":"Of their own means belonging especially to them, rather than copied from others.","zh":"Of their own 指特別屬於他們自己，而不是從別人那裡複製。"},{"en":"Children need a study space of their own if the home is noisy.","zh":"如果家中嘈雜，孩子需要屬於自己的學習空間。"},{"en":"A small restaurant may develop a flavour of its own after years of practice.","zh":"小餐廳多年練習後，可能發展出屬於自己的味道。"},{"en":"The phrase emphasises identity, ownership, or independence.","zh":"這個片語強調身份、擁有或獨立性。"}],"source":"153 - British Architecture.pdf","sourcePage":3},{"front":"little survives","meaning":"留存下來的很少","examples":[{"en":"Little survives of Anglo-Saxon architecture.","zh":"盎格魯撒克遜建築留存下來的很少。"},{"en":"Little survives means only a small amount remains today.","zh":"Little survives 指今天只剩下很少部分。"},{"en":"Little survives of the old village after repeated floods and rebuilding.","zh":"經歷多次水災和重建後，舊村莊留存下來的很少。"},{"en":"If buildings are made of wood, little may survive after many centuries.","zh":"如果建築物由木材建成，幾個世紀後可能留存下來的很少。"},{"en":"The phrase is often used when discussing lost historical evidence.","zh":"這個片語常用於討論失去的歷史證據。"}],"source":"153 - British Architecture.pdf","sourcePage":3},{"front":"bear witness to","meaning":"見證","examples":[{"en":"Few buildings survive to bear witness to Anglo-Saxon achievements.","zh":"很少建築保存下來見證盎格魯撒克遜人的成就。"},{"en":"To bear witness to something means to provide evidence that it happened or existed.","zh":"To bear witness to something 指提供證據，證明某事曾發生或存在。"},{"en":"Old photographs bear witness to how a neighbourhood looked before redevelopment.","zh":"舊照片見證了一個社區重建前的面貌。"},{"en":"A war memorial bears witness to the sacrifices of earlier generations.","zh":"戰爭紀念碑見證了前人所作的犧牲。"},{"en":"The phrase is formal and often used for history, memory, and evidence.","zh":"這個片語較正式，常用於歷史、記憶和證據。"}],"source":"153 - British Architecture.pdf","sourcePage":3},{"front":"their achievements","meaning":"他們的成就","examples":[{"en":"Wooden buildings rarely survived to show the Anglo-Saxons’ achievements.","zh":"木造建築很少保存下來展示盎格魯撒克遜人的成就。"},{"en":"Their achievements means the important things they succeeded in doing or creating.","zh":"Their achievements 指他們成功完成或創造的重要事物。"},{"en":"A school exhibition can show students’ achievements through projects, art, and writing.","zh":"學校展覽可以透過項目、藝術和寫作展示學生的成就。"},{"en":"If records are lost, later generations may underestimate their achievements.","zh":"如果紀錄遺失，後代可能低估他們的成就。"},{"en":"The phrase focuses on successful results, not just effort.","zh":"這個片語著重成功結果，而不只是努力。"}],"source":"153 - British Architecture.pdf","sourcePage":3},{"front":"the vast majority of","meaning":"絕大多數","examples":[{"en":"The vast majority of Anglo-Saxon buildings were made of wood.","zh":"絕大多數盎格魯撒克遜建築都是由木材建成。"},{"en":"The vast majority of something means almost all of it.","zh":"The vast majority of something 指某物之中的幾乎全部。"},{"en":"The vast majority of students bring phones to school, even if they do not use them in class.","zh":"絕大多數學生都帶手機上學，即使他們不在課堂使用。"},{"en":"If the vast majority of buildings use one material, that material strongly shapes the town’s appearance.","zh":"如果絕大多數建築使用同一種材料，該材料會強烈塑造城鎮外觀。"},{"en":"The phrase is stronger than “many” because it suggests a very large proportion.","zh":"這個片語比 “many” 更強，因為它表示非常大的比例。"}],"source":"153 - British Architecture.pdf","sourcePage":3},{"front":"made of wood","meaning":"由木材建成","examples":[{"en":"Anglo-Saxon buildings were usually made of wood.","zh":"盎格魯撒克遜建築通常由木材建成。"},{"en":"Made of wood means built or formed from timber.","zh":"Made of wood 指由木材建造或形成。"},{"en":"A chair made of wood may feel warmer and more natural than a metal chair.","zh":"木製椅子可能比金屬椅感覺更溫暖和自然。"},{"en":"Buildings made of wood can be beautiful, but they may burn or decay more easily.","zh":"由木材建成的建築可以很美，但可能更容易燃燒或腐朽。"},{"en":"The phrase identifies the material used to make something.","zh":"這個片語指出製造某物所用的材料。"}],"source":"153 - British Architecture.pdf","sourcePage":3},{"front":"even so","meaning":"即使如此","examples":[{"en":"Even so, the medieval period marked a rare flowering of British building.","zh":"即使如此，中世紀仍標誌着英國建築罕見的繁盛。"},{"en":"Even so means despite what has just been said.","zh":"Even so 指儘管剛才所說的情況如此。"},{"en":"The exam was difficult; even so, several students achieved high marks.","zh":"考試很難；即使如此，仍有幾名學生取得高分。"},{"en":"The building is old; even so, it remains safe and useful.","zh":"這座建築很舊；即使如此，它仍然安全和實用。"},{"en":"The phrase introduces a contrast that may surprise the reader.","zh":"這個片語引出可能令讀者意外的對比。"}],"source":"153 - British Architecture.pdf","sourcePage":4},{"front":"the Norman landing","meaning":"諾曼人登陸","examples":[{"en":"The period began with the Norman landing at Pevensey in 1066.","zh":"這個時期始於1066年諾曼人在Pevensey登陸。"},{"en":"The Norman landing refers to the arrival of Norman forces in England before the conquest.","zh":"The Norman landing 指諾曼軍隊在征服前抵達英格蘭。"},{"en":"A military landing can become historically important if it begins a major political change.","zh":"如果一次軍事登陸開啟重大政治變化，它就可能具有歷史重要性。"},{"en":"The Norman landing led to battles, new rulers, and changes in land ownership.","zh":"諾曼人登陸導致戰爭、新統治者和土地所有權變化。"},{"en":"The phrase marks the physical beginning of a larger historical event.","zh":"這個片語標誌更大歷史事件的實際開始。"}],"source":"153 - British Architecture.pdf","sourcePage":4},{"front":"lost his horse and his head","meaning":"失去坐騎和性命","examples":[{"en":"Richard III lost his horse and his head at Bosworth.","zh":"理查三世在Bosworth失去坐騎和性命。"},{"en":"To lose his horse and his head means he lost both the battle and his life.","zh":"To lose his horse and his head 指他既輸掉戰役，也失去生命。"},{"en":"In historical writing, a vivid phrase can make defeat sound memorable.","zh":"在歷史寫作中，生動片語可以令失敗更令人記得。"},{"en":"A ruler who loses power and dies in battle loses far more than a political argument.","zh":"在戰場上失去權力並死亡的統治者，失去的不只是政治爭論。"},{"en":"The phrase is dramatic and should be used only for serious or historical defeat.","zh":"這個片語語氣戲劇化，應只用於嚴重或歷史性的失敗。"}],"source":"153 - British Architecture.pdf","sourcePage":4},{"front":"ushering in","meaning":"開啟；迎來","examples":[{"en":"The Battle of Bosworth ushered in the Tudors and the Early Modern period.","zh":"Bosworth戰役開啟了都鐸王朝和近代早期。"},{"en":"To usher in something means to mark the beginning of a new period, system, or change.","zh":"To usher in something 指標誌一個新時期、新制度或變化的開始。"},{"en":"The invention of smartphones ushered in a new way of communicating.","zh":"智能手機的發明開啟了新的溝通方式。"},{"en":"A new law can usher in major changes in public services.","zh":"新法律可以迎來公共服務的重大變化。"},{"en":"The phrase suggests an important transition, not a small adjustment.","zh":"這個片語暗示重要轉變，而不是小調整。"}],"source":"153 - British Architecture.pdf","sourcePage":4},{"front":"the Tudors","meaning":"都鐸王朝","examples":[{"en":"The Tudors came to power after Richard III’s defeat.","zh":"理查三世戰敗後，都鐸王朝掌權。"},{"en":"The Tudors were the English royal family that ruled after the Wars of the Roses.","zh":"都鐸王朝是在玫瑰戰爭後統治英格蘭的王室家族。"},{"en":"Tudor rule is often linked with changes in religion, government, and domestic architecture.","zh":"都鐸統治常與宗教、政府和住宅建築的變化相關。"},{"en":"Wealthy families under the Tudors built houses that showed status and comfort.","zh":"都鐸時期的富裕家庭建造展示地位和舒適的住宅。"},{"en":"The phrase refers to a dynasty, not just one ruler.","zh":"這個片語指一個王朝，而不只是單一統治者。"}],"source":"153 - British Architecture.pdf","sourcePage":4},{"front":"the Early Modern period","meaning":"近代早期","examples":[{"en":"The Tudors ushered in the Early Modern period.","zh":"都鐸王朝開啟了近代早期。"},{"en":"The Early Modern period is the historical period between the late Middle Ages and the modern age.","zh":"近代早期是中世紀晚期與現代之間的歷史時期。"},{"en":"It included changes in government, religion, trade, science, and architecture.","zh":"它包括政府、宗教、貿易、科學和建築的變化。"},{"en":"During the Early Modern period, wealthy houses became more outward-looking and decorative.","zh":"在近代早期，富裕住宅變得更向外開放和更具裝飾性。"},{"en":"The phrase helps historians separate medieval society from later modern developments.","zh":"這個片語幫助歷史學家區分中世紀社會和後來的現代發展。"}],"source":"153 - British Architecture.pdf","sourcePage":4},{"front":"marks a rare flowering of","meaning":"標誌着……罕見的繁盛","examples":[{"en":"The period marks a rare flowering of British building.","zh":"這個時期標誌着英國建築罕見的繁盛。"},{"en":"To mark a rare flowering of something means to show an unusual period of strong creative growth.","zh":"To mark a rare flowering of something 指顯示某事出現罕見而強烈的創造力增長。"},{"en":"A decade of excellent films may mark a rare flowering of local cinema.","zh":"十年間出現許多優秀電影，可能標誌着本地電影罕見的繁盛。"},{"en":"A rare flowering happens when talent, money, demand, and ideas come together.","zh":"當人才、金錢、需求和想法結合時，罕見的繁盛便可能出現。"},{"en":"The phrase praises a period as unusually rich and productive.","zh":"這個片語讚揚某時期異常豐富而高產。"}],"source":"153 - British Architecture.pdf","sourcePage":4},{"front":"British building","meaning":"英國建築發展","examples":[{"en":"The medieval period was a rare flowering of British building.","zh":"中世紀是英國建築發展罕見的繁盛時期。"},{"en":"British building means the practice, style, and development of constructing buildings in Britain.","zh":"British building 指英國建造建築物的做法、風格和發展。"},{"en":"British building includes ordinary houses as well as castles, churches, and public buildings.","zh":"英國建築發展包括普通住宅，也包括城堡、教堂和公共建築。"},{"en":"New materials and social needs can change British building over time.","zh":"新材料和社會需要可以隨時間改變英國建築發展。"},{"en":"The phrase focuses on building activity, not only architectural theory.","zh":"這個片語著重建築活動，而不只是建築理論。"}],"source":"153 - British Architecture.pdf","sourcePage":4},{"front":"all the more remarkable","meaning":"更加值得注意","examples":[{"en":"The period is all the more remarkable because medieval architecture was functional.","zh":"這個時期更加值得注意，因為中世紀建築是功能性的。"},{"en":"All the more remarkable means even more impressive because of a particular fact.","zh":"All the more remarkable 指因某個事實而更加令人印象深刻。"},{"en":"Her high exam result is all the more remarkable because she studied while working full-time.","zh":"她的高分更加值得注意，因為她是一邊全職工作一邊溫習。"},{"en":"A beautiful building is all the more remarkable if it was built with limited money.","zh":"如果一座美麗建築是在資金有限下建成，它就更加值得注意。"},{"en":"The phrase adds extra praise by explaining why something is surprising.","zh":"這個片語透過解釋為何令人意外，增加讚賞語氣。"}],"source":"153 - British Architecture.pdf","sourcePage":4},{"front":"underlying ethos","meaning":"基本精神；核心理念","examples":[{"en":"The underlying ethos of medieval architecture was fitness for purpose.","zh":"中世紀建築的核心理念是適合用途。"},{"en":"Underlying ethos means the deep guiding belief or spirit behind an action, style, or system.","zh":"Underlying ethos 指某個行動、風格或制度背後深層的指導信念或精神。"},{"en":"The underlying ethos of a good school may be respect, effort, and care.","zh":"一所好學校的核心理念可能是尊重、努力和關懷。"},{"en":"If the underlying ethos is practical service, design choices will focus on usefulness.","zh":"如果核心理念是實用服務，設計選擇便會集中於有用性。"},{"en":"The phrase explains the hidden principle behind visible decisions.","zh":"這個片語解釋可見決定背後隱藏的原則。"}],"source":"153 - British Architecture.pdf","sourcePage":4},{"front":"medieval architecture","meaning":"中世紀建築","examples":[{"en":"Medieval architecture was strongly shaped by fitness for purpose.","zh":"中世紀建築深受適合用途這一原則塑造。"},{"en":"Medieval architecture refers to buildings designed and constructed during the Middle Ages.","zh":"中世紀建築是指在中世紀設計和建造的建築物。"},{"en":"Castles, monasteries, parish churches, and cathedrals are examples of medieval architecture.","zh":"城堡、修道院、堂區教堂和大教堂都是中世紀建築的例子。"},{"en":"Defence, worship, and community life often shaped medieval architecture.","zh":"防禦、崇拜和社區生活常塑造中世紀建築。"},{"en":"The phrase connects buildings with the needs and beliefs of the medieval world.","zh":"這個片語把建築物與中世紀世界的需要和信念連接起來。"}],"source":"153 - British Architecture.pdf","sourcePage":4},{"front":"fitness for purpose","meaning":"適合用途；實用為本","examples":[{"en":"The underlying ethos of medieval architecture was fitness for purpose.","zh":"中世紀建築的核心理念是適合用途。"},{"en":"Fitness for purpose means something is designed to do its job well.","zh":"Fitness for purpose 指某物被設計成能有效完成其用途。"},{"en":"A school desk has fitness for purpose if it is strong, comfortable, and the right height.","zh":"如果課桌堅固、舒適而且高度合適，它就符合用途。"},{"en":"A castle shows fitness for purpose when its walls, towers, and gates help defence.","zh":"當城堡的城牆、塔樓和大門有助防衛時，它便體現實用為本。"},{"en":"The phrase values usefulness more than decoration alone.","zh":"這個片語重視有用性，而不只是裝飾。"}],"source":"153 - British Architecture.pdf","sourcePage":5},{"front":"parish churches","meaning":"堂區教堂","examples":[{"en":"Great cathedrals and parish churches lifted up their towers to heaven.","zh":"大教堂和堂區教堂把塔樓高高伸向天空。"},{"en":"Parish churches are local churches serving people in a particular church district.","zh":"堂區教堂是服務特定教會地區居民的本地教堂。"},{"en":"A parish church may host worship, weddings, funerals, and community meetings.","zh":"堂區教堂可能舉行崇拜、婚禮、葬禮和社區會議。"},{"en":"Parish churches were important because ordinary people used them regularly.","zh":"堂區教堂很重要，因為普通人經常使用它們。"},{"en":"The phrase refers to local religious buildings, not grand national cathedrals.","zh":"這個片語指本地宗教建築，而不是宏大的全國性大教堂。"}],"source":"153 - British Architecture.pdf","sourcePage":5},{"front":"lifted up their towers to heaven","meaning":"將塔樓高高伸向天空","examples":[{"en":"Medieval churches lifted up their towers to heaven.","zh":"中世紀教堂將塔樓高高伸向天空。"},{"en":"This phrase means the towers rose high into the sky, suggesting religious devotion.","zh":"這個片語指塔樓高聳入天，暗示宗教虔誠。"},{"en":"A tall church tower can make people look upward and think about God or eternity.","zh":"高高的教堂塔樓可以令人仰望，想到上帝或永恆。"},{"en":"Height in religious buildings often creates awe and a sense of spiritual aspiration.","zh":"宗教建築中的高度常營造敬畏感和精神追求。"},{"en":"The phrase is visual and symbolic, not just a measurement of height.","zh":"這個片語既有視覺感，也有象徵意義，不只是高度測量。"}],"source":"153 - British Architecture.pdf","sourcePage":5},{"front":"acts of devotion in stone","meaning":"以石材呈現的虔誠奉獻","examples":[{"en":"Great cathedrals were acts of devotion in stone.","zh":"大教堂是以石材呈現的虔誠奉獻。"},{"en":"Acts of devotion in stone are buildings that express religious faith through stone construction.","zh":"Acts of devotion in stone 是指透過石造建築表達宗教信仰。"},{"en":"A carved temple can be an act of devotion in stone when it is built to honour a god.","zh":"當雕刻寺廟是為了敬奉神明而建，它可以是以石材呈現的虔誠奉獻。"},{"en":"Such buildings take time and labour because faith gives people a reason to build carefully.","zh":"這類建築需要時間和勞力，因為信仰給人仔細建造的理由。"},{"en":"The phrase presents architecture as worship made visible.","zh":"這個片語把建築呈現為可見的崇拜。"}],"source":"153 - British Architecture.pdf","sourcePage":5},{"front":"fiercely functional buildings","meaning":"極具功能性的建築","examples":[{"en":"Medieval churches were also fiercely functional buildings.","zh":"中世紀教堂也是極具功能性的建築。"},{"en":"Fiercely functional buildings are buildings strongly designed for practical use.","zh":"Fiercely functional buildings 是指高度按照實際用途設計的建築物。"},{"en":"A hospital with clear signs, wide corridors, and emergency access is fiercely functional.","zh":"有清晰標示、寬闊走廊和急症通道的醫院，是極具功能性的建築。"},{"en":"When a building must serve many people daily, function becomes more important than show.","zh":"當建築每天必須服務很多人，功能便比外觀更重要。"},{"en":"The phrase suggests usefulness is intense and central, not secondary.","zh":"這個片語暗示實用性非常核心，而不是次要。"}],"source":"153 - British Architecture.pdf","sourcePage":5},{"front":"served their particular purpose","meaning":"發揮其特定用途","examples":[{"en":"Castles served their particular purpose.","zh":"城堡發揮了其特定用途。"},{"en":"To serve a particular purpose means to be useful for a specific job or need.","zh":"To serve a particular purpose 指對某個特定工作或需要有用。"},{"en":"A school hall serves its particular purpose if it can hold assemblies and exams.","zh":"如果學校禮堂能舉行集會和考試，它便發揮其特定用途。"},{"en":"A castle’s walls and towers served the purpose of defence.","zh":"城堡的城牆和塔樓發揮防禦用途。"},{"en":"The phrase asks whether design matches use.","zh":"這個片語關注設計是否配合用途。"}],"source":"153 - British Architecture.pdf","sourcePage":5},{"front":"battlements and turrets","meaning":"城垛和角塔","examples":[{"en":"Castles had battlements and turrets for practical use.","zh":"城堡有城垛和角塔作實際用途。"},{"en":"Battlements and turrets are defensive castle features on walls and towers.","zh":"城垛和角塔是城牆和塔樓上的防禦性城堡特徵。"},{"en":"Soldiers could use battlements for protection while watching or defending the castle.","zh":"士兵可以利用城垛作保護，同時觀察或防守城堡。"},{"en":"Turrets gave defenders higher positions to see danger approaching.","zh":"角塔給防守者較高位置，以看見正在接近的危險。"},{"en":"The phrase describes features that look decorative today but were originally useful.","zh":"這個片語描述今天看似裝飾、但原本有實用功能的特徵。"}],"source":"153 - British Architecture.pdf","sourcePage":5},{"front":"for use rather than ornament","meaning":"為實用而非裝飾","examples":[{"en":"Castle features were for use rather than ornament.","zh":"城堡特徵是為實用而非裝飾。"},{"en":"For use rather than ornament means something is designed to be practical, not just beautiful.","zh":"For use rather than ornament 指某物是為了實際用途而設計，不只是為了美觀。"},{"en":"A simple raincoat is for use rather than ornament because it keeps the wearer dry.","zh":"簡單雨衣是為實用而非裝飾，因為它能讓穿着者保持乾爽。"},{"en":"In a hospital, wide doors are for use rather than ornament because beds must pass through them.","zh":"在醫院中，寬門是為實用而非裝飾，因為病床要通過。"},{"en":"The phrase clearly contrasts function with decoration.","zh":"這個片語清楚對比功能和裝飾。"}],"source":"153 - British Architecture.pdf","sourcePage":5},{"front":"in a sense","meaning":"某程度上","examples":[{"en":"In a sense, sixteenth-century buildings were also governed by purpose.","zh":"某程度上，十六世紀建築也受目的支配。"},{"en":"In a sense means partly true, or true from one particular point of view.","zh":"In a sense 指在某個角度而言部分正確。"},{"en":"In a sense, homework is training because it builds habits through repetition.","zh":"某程度上，功課是一種訓練，因為它透過重複建立習慣。"},{"en":"A library is, in a sense, a community memory because it stores shared knowledge.","zh":"圖書館某程度上是社區記憶，因為它保存共同知識。"},{"en":"The phrase softens a claim and shows it is not absolute.","zh":"這個片語使說法較柔和，表示它並非絕對。"}],"source":"153 - British Architecture.pdf","sourcePage":5},{"front":"governed by","meaning":"受……支配","examples":[{"en":"The buildings of the sixteenth century were governed by a different purpose.","zh":"十六世紀建築受另一種目的支配。"},{"en":"To be governed by something means to be strongly controlled or guided by it.","zh":"To be governed by something 指受到某事強烈控制或引導。"},{"en":"School behaviour is governed by rules about safety and respect.","zh":"學校行為受安全和尊重規則支配。"},{"en":"A budget is governed by how much money is available.","zh":"預算受可用金額支配。"},{"en":"The phrase shows what principle controls decisions.","zh":"這個片語顯示甚麼原則控制決定。"}],"source":"153 - British Architecture.pdf","sourcePage":5},{"front":"domestic architecture","meaning":"住宅建築","examples":[{"en":"Domestic architecture was used to display status and wealth.","zh":"住宅建築被用來展示地位和財富。"},{"en":"Domestic architecture refers to the design and construction of homes and private residences.","zh":"Domestic architecture 是指家庭和私人住宅的設計與建造。"},{"en":"A townhouse, cottage, flat, or country house can all belong to domestic architecture.","zh":"城市住宅、村屋、公寓或鄉村大宅都可屬於住宅建築。"},{"en":"Domestic architecture changes when family life, privacy, and wealth change.","zh":"當家庭生活、私隱和財富改變，住宅建築也會改變。"},{"en":"The phrase focuses on homes rather than churches, factories, or public buildings.","zh":"這個片語著重住宅，而不是教堂、工廠或公共建築。"}],"source":"153 - British Architecture.pdf","sourcePage":5},{"front":"in particular","meaning":"尤其是","examples":[{"en":"Domestic architecture, in particular, displayed status and wealth.","zh":"尤其是住宅建築展示了地位和財富。"},{"en":"In particular means especially or more than other things mentioned.","zh":"In particular 指尤其是，或比其他提到的事物更特別。"},{"en":"Students often find grammar difficult, in particular verb tenses.","zh":"學生常覺得文法困難，尤其是動詞時態。"},{"en":"The policy helps families, in particular those with young children.","zh":"這項政策幫助家庭，尤其是有年幼子女的家庭。"},{"en":"The phrase narrows attention to one important example.","zh":"這個片語把注意力收窄到一個重要例子。"}],"source":"153 - British Architecture.pdf","sourcePage":6},{"front":"display status and wealth","meaning":"展示地位和財富","examples":[{"en":"Sixteenth-century buildings were used to display status and wealth.","zh":"十六世紀建築被用來展示地位和財富。"},{"en":"To display status and wealth means to show social rank and money through visible signs.","zh":"To display status and wealth 指透過可見標誌顯示社會地位和金錢。"},{"en":"A large house with expensive materials can display status and wealth.","zh":"一座用昂貴材料建成的大宅可以展示地位和財富。"},{"en":"People may use cars, clothing, or home decoration to display status and wealth.","zh":"人們可能用汽車、衣服或家居裝飾展示地位和財富。"},{"en":"The phrase suggests that appearance is used to send a social message.","zh":"這個片語暗示外觀被用來傳達社會訊息。"}],"source":"153 - British Architecture.pdf","sourcePage":6},{"front":"stately and curious workmanship","meaning":"宏偉而奇特的工藝","examples":[{"en":"This stately and curious workmanship showed itself in various ways.","zh":"這種宏偉而奇特的工藝以各種方式表現出來。"},{"en":"Stately and curious workmanship means grand, impressive, and unusual skill in making something.","zh":"Stately and curious workmanship 指宏偉、令人印象深刻而不尋常的製作技藝。"},{"en":"A carved wooden ceiling can show stately and curious workmanship.","zh":"雕刻木天花可以展示宏偉而奇特的工藝。"},{"en":"Such workmanship often requires time, money, and highly skilled workers.","zh":"這類工藝通常需要時間、金錢和高度熟練工人。"},{"en":"The phrase sounds old-fashioned and praises detailed craft.","zh":"這個片語帶有古雅感，並讚揚細緻工藝。"}],"source":"153 - British Architecture.pdf","sourcePage":6},{"front":"showed itself in","meaning":"表現於","examples":[{"en":"This workmanship showed itself in various architectural features.","zh":"這種工藝表現於各種建築特色之中。"},{"en":"To show itself in something means to become visible through that thing.","zh":"To show itself in something 指透過某物變得可見。"},{"en":"A school’s values show themselves in how teachers treat weaker students.","zh":"一所學校的價值觀表現於老師如何對待較弱學生。"},{"en":"Wealth may show itself in large windows, costly materials, and decorative entrances.","zh":"財富可能表現於大窗、昂貴材料和裝飾性入口。"},{"en":"The phrase links an invisible quality with visible evidence.","zh":"這個片語把看不見的特質與可見證據連接起來。"}],"source":"153 - British Architecture.pdf","sourcePage":6},{"front":"a greater sense of security","meaning":"更大的安全感","examples":[{"en":"A greater sense of security led to more outward-looking buildings.","zh":"更大的安全感促成更向外開放的建築。"},{"en":"A greater sense of security means people feel safer and less worried about attack or danger.","zh":"A greater sense of security 指人們感到更安全，較少擔心攻擊或危險。"},{"en":"When a neighbourhood feels safer, families may spend more time outdoors.","zh":"當社區感覺更安全，家庭可能花更多時間在戶外。"},{"en":"Greater security can change design because buildings no longer need to hide behind walls.","zh":"更大的安全感可以改變設計，因為建築不再需要藏在牆後。"},{"en":"The phrase explains how feelings of safety can shape behaviour and architecture.","zh":"這個片語解釋安全感如何塑造行為和建築。"}],"source":"153 - British Architecture.pdf","sourcePage":6},{"front":"led to","meaning":"導致；促成","examples":[{"en":"A greater sense of security led to new building styles.","zh":"更大的安全感促成新的建築風格。"},{"en":"Led to means caused or resulted in something.","zh":"Led to 指導致或造成某事。"},{"en":"Heavy rain led to flooding in several streets.","zh":"大雨導致幾條街道水浸。"},{"en":"Better lighting can lead to safer public spaces at night.","zh":"更好的照明可以促成夜間更安全的公共空間。"},{"en":"The phrase connects a cause with its result.","zh":"這個片語把原因與結果連接起來。"}],"source":"153 - British Architecture.pdf","sourcePage":6},{"front":"outward-looking buildings","meaning":"向外開放的建築","examples":[{"en":"Sixteenth-century houses became more outward-looking buildings.","zh":"十六世紀房屋變得更像向外開放的建築。"},{"en":"Outward-looking buildings face or open more towards the outside world.","zh":"Outward-looking buildings 指更多面向或開放至外部世界的建築。"},{"en":"A house with large front windows and gardens can feel outward-looking.","zh":"有大型前窗和花園的房屋會感覺向外開放。"},{"en":"Greater safety allowed houses to look outward instead of hiding around inner courtyards.","zh":"更大的安全感使房屋可以向外，而不是圍繞內院隱藏起來。"},{"en":"The phrase can describe both physical design and a more open attitude.","zh":"這個片語既可描述實體設計，也可描述較開放的態度。"}],"source":"153 - British Architecture.pdf","sourcePage":6},{"front":"as opposed to","meaning":"而不是；與……相對","examples":[{"en":"New houses faced outward, as opposed to the medieval arrangement.","zh":"新房屋面向外部，而不是採用中世紀佈局。"},{"en":"As opposed to means in contrast with or rather than something else.","zh":"As opposed to 指與某事相對，或而不是某事。"},{"en":"The course focuses on speaking, as opposed to only grammar drills.","zh":"這門課集中口語，而不是只做文法操練。"},{"en":"A small clinic offers personal care, as opposed to a large hospital’s faster but less personal service.","zh":"小診所提供個人化照顧，與大型醫院較快但較不個人化的服務相對。"},{"en":"The phrase clearly marks a contrast between two options.","zh":"這個片語清楚標示兩個選項之間的對比。"}],"source":"153 - British Architecture.pdf","sourcePage":6},{"front":"medieval arrangement","meaning":"中世紀佈局","examples":[{"en":"The medieval arrangement often made houses face inward.","zh":"中世紀佈局常令房屋面向內部。"},{"en":"A medieval arrangement is the way buildings or spaces were organised in the Middle Ages.","zh":"Medieval arrangement 指中世紀建築或空間的組織方式。"},{"en":"A house arranged around a courtyard reflects a medieval arrangement focused on defence.","zh":"圍繞庭院安排的房屋反映以防禦為重點的中世紀佈局。"},{"en":"Medieval arrangements often protected people by turning buildings inward.","zh":"中世紀佈局常透過令建築向內來保護人。"},{"en":"The phrase describes layout, not simply decoration.","zh":"這個片語描述平面安排，而不只是裝飾。"}],"source":"153 - British Architecture.pdf","sourcePage":6},{"front":"the need for defence","meaning":"防禦需要","examples":[{"en":"The need for defence shaped medieval houses.","zh":"防禦需要塑造了中世紀房屋。"},{"en":"The need for defence means the need to protect people and property from attack.","zh":"The need for defence 指保護人和財產免受攻擊的需要。"},{"en":"A village near danger may build walls because of the need for defence.","zh":"靠近危險的村莊可能因防禦需要而建造圍牆。"},{"en":"When the need for defence is strong, buildings may have fewer windows and stronger gates.","zh":"當防禦需要很強，建築可能有較少窗戶和更堅固大門。"},{"en":"The phrase explains why safety can control design choices.","zh":"這個片語解釋安全如何控制設計選擇。"}],"source":"153 - British Architecture.pdf","sourcePage":6},{"front":"faced inward onto","meaning":"面向內部的……","examples":[{"en":"Medieval houses often faced inward onto a courtyard.","zh":"中世紀房屋常面向內部庭院。"},{"en":"To face inward onto something means to look towards an inner space rather than the outside.","zh":"To face inward onto something 指朝向內部空間，而不是朝向外部。"},{"en":"Some apartment blocks face inward onto a shared garden.","zh":"一些公寓大樓面向內部的共享花園。"},{"en":"Houses may face inward onto a courtyard to create privacy and protection.","zh":"房屋可能面向內部庭院，以創造私隱和保護。"},{"en":"The phrase describes both direction and layout.","zh":"這個片語同時描述方向和佈局。"}],"source":"153 - British Architecture.pdf","sourcePage":6},{"front":"a courtyard","meaning":"庭院","examples":[{"en":"Medieval houses often looked inward onto a courtyard.","zh":"中世紀房屋常向內望向庭院。"},{"en":"A courtyard is an open space surrounded partly or fully by buildings or walls.","zh":"庭院是被建築物或牆壁部分或完全包圍的開放空間。"},{"en":"Students may eat lunch in a school courtyard between lessons.","zh":"學生可能在課與課之間於學校庭院吃午飯。"},{"en":"A courtyard can bring light and air into a building while keeping privacy.","zh":"庭院可以把光和空氣帶入建築，同時保持私隱。"},{"en":"The phrase often appears in descriptions of houses, schools, and historic buildings.","zh":"這個詞常出現在住宅、學校和歷史建築的描述中。"}],"source":"153 - British Architecture.pdf","sourcePage":7},{"front":"a series of courtyards","meaning":"一連串庭院","examples":[{"en":"Some medieval houses were arranged around a series of courtyards.","zh":"一些中世紀房屋圍繞一連串庭院安排。"},{"en":"A series of courtyards means several courtyards connected or placed one after another.","zh":"A series of courtyards 指幾個相連或依次排列的庭院。"},{"en":"A palace may guide visitors through a series of courtyards before they reach the main hall.","zh":"宮殿可能引導訪客穿過一連串庭院，才到達正殿。"},{"en":"Several courtyards can separate private, working, and public areas.","zh":"多個庭院可以分隔私人、工作和公共區域。"},{"en":"The phrase suggests an organised sequence of open spaces.","zh":"這個片語暗示一組有組織次序的開放空間。"}],"source":"153 - British Architecture.pdf","sourcePage":7},{"front":"allowed for","meaning":"容許；使……成為可能","examples":[{"en":"Greater security allowed for more exterior ornament.","zh":"更大的安全感使更多外部裝飾成為可能。"},{"en":"Allowed for means made something possible or left space for it to happen.","zh":"Allowed for 指使某事成為可能，或為某事留下空間。"},{"en":"A flexible timetable allows for rest between difficult lessons.","zh":"靈活時間表容許困難課堂之間有休息時間。"},{"en":"A larger budget allows for better materials and safer construction.","zh":"更大的預算使更好材料和更安全建造成為可能。"},{"en":"The phrase shows that one condition makes another thing possible.","zh":"這個片語顯示某個條件使另一件事可以發生。"}],"source":"153 - British Architecture.pdf","sourcePage":7},{"front":"much more in the way of","meaning":"更多……方面的東西","examples":[{"en":"Outward-looking buildings allowed for much more in the way of exterior ornament.","zh":"向外開放的建築容許更多外部裝飾方面的東西。"},{"en":"Much more in the way of something means a much greater amount or variety of that thing.","zh":"Much more in the way of something 指某物在數量或種類上多得多。"},{"en":"A bigger classroom gives teachers much more in the way of display space.","zh":"更大的課室給老師更多展示空間方面的東西。"},{"en":"A modern phone offers much more in the way of functions than an old basic phone.","zh":"現代手機比舊式基本手機提供更多功能方面的東西。"},{"en":"The phrase is informal but useful for describing increased variety or quantity.","zh":"這個片語較口語，但適合描述數量或種類增加。"}],"source":"153 - British Architecture.pdf","sourcePage":7},{"front":"exterior ornament","meaning":"外部裝飾","examples":[{"en":"Sixteenth-century buildings often displayed exterior ornament.","zh":"十六世紀建築常展示外部裝飾。"},{"en":"Exterior ornament means decoration on the outside of a building.","zh":"Exterior ornament 指建築外部的裝飾。"},{"en":"Carved doorways, patterned brickwork, and decorative windows can be exterior ornament.","zh":"雕刻門口、圖案磚工和裝飾窗都可以是外部裝飾。"},{"en":"Exterior ornament may show wealth because it costs money but is not always necessary for function.","zh":"外部裝飾可能展示財富，因為它花錢但不一定對功能必要。"},{"en":"The phrase contrasts outside decoration with interior design.","zh":"這個片語把外部裝飾與室內設計作對比。"}],"source":"153 - British Architecture.pdf","sourcePage":7},{"front":"tended to be","meaning":"往往是","examples":[{"en":"The rooms tended to be bigger and lighter.","zh":"房間往往更大和更明亮。"},{"en":"Tended to be means usually were, although not always.","zh":"Tended to be 指通常是這樣，但不是永遠如此。"},{"en":"Older classrooms tended to be darker because their windows were smaller.","zh":"較舊的課室往往較暗，因為窗戶較小。"},{"en":"Restaurants near offices tend to be busy at lunchtime.","zh":"辦公室附近的餐廳午餐時間往往很忙。"},{"en":"The phrase describes a general pattern, not a strict rule.","zh":"這個片語描述一般模式，而不是嚴格規則。"}],"source":"153 - British Architecture.pdf","sourcePage":7},{"front":"expensive commodity","meaning":"昂貴商品","examples":[{"en":"Glass was an expensive commodity at the time.","zh":"玻璃在當時是一種昂貴商品。"},{"en":"An expensive commodity is a useful material or product that costs a lot to buy.","zh":"昂貴商品是指有用但購買成本很高的材料或產品。"},{"en":"In some places, clean water can become an expensive commodity during drought.","zh":"在一些地方，旱災期間清潔食水可能變成昂貴商品。"},{"en":"If a material is an expensive commodity, only wealthy people may use it widely.","zh":"如果某材料是昂貴商品，可能只有富人能大量使用。"},{"en":"The phrase shows that something ordinary today may once have been a luxury.","zh":"這個片語顯示今天普通的東西，過去可能曾是奢侈品。"}],"source":"153 - British Architecture.pdf","sourcePage":7},{"front":"great expanses of glass","meaning":"大面積玻璃","examples":[{"en":"Great expanses of glass were used to show wealth.","zh":"大面積玻璃被用來展示財富。"},{"en":"Great expanses of glass means very large areas covered by glass.","zh":"Great expanses of glass 指非常大範圍的玻璃。"},{"en":"A modern office tower may have great expanses of glass on its exterior walls.","zh":"現代辦公大樓的外牆可能有大面積玻璃。"},{"en":"When glass was expensive, large glass windows showed that the owner was rich.","zh":"當玻璃昂貴時，大玻璃窗顯示屋主富有。"},{"en":"The phrase emphasises size and visual impact.","zh":"這個片語強調大小和視覺效果。"}],"source":"153 - British Architecture.pdf","sourcePage":7},{"front":"in itself","meaning":"本身就是","examples":[{"en":"The use of glass was in itself a statement of wealth.","zh":"使用玻璃本身就是財富的象徵。"},{"en":"In itself means by its own nature, without needing anything else.","zh":"In itself 指某物憑其本身性質，不需要其他東西。"},{"en":"A handwritten thank-you note can be meaningful in itself.","zh":"手寫感謝信本身就可以很有意義。"},{"en":"A large garden was, in itself, a sign that the owner had land and money.","zh":"大花園本身就是屋主擁有土地和金錢的標誌。"},{"en":"The phrase shows that the thing alone already carries meaning.","zh":"這個片語顯示某物本身已帶有意義。"}],"source":"153 - British Architecture.pdf","sourcePage":7},{"front":"a statement of wealth","meaning":"財富的象徵","examples":[{"en":"Large windows were a statement of wealth.","zh":"大窗戶是財富的象徵。"},{"en":"A statement of wealth is a visible sign that shows a person or family is rich.","zh":"A statement of wealth 是顯示個人或家庭富有的可見標誌。"},{"en":"A marble entrance can be a statement of wealth in a luxury hotel.","zh":"大理石入口可以是豪華酒店中財富的象徵。"},{"en":"People may use expensive materials to make a statement of wealth to visitors.","zh":"人們可能使用昂貴材料向訪客展示財富。"},{"en":"The phrase means the object communicates wealth without words.","zh":"這個片語表示物件不用文字也能傳達財富。"}],"source":"153 - British Architecture.pdf","sourcePage":7},{"front":"a general move towards","meaning":"普遍轉向","examples":[{"en":"There was a general move towards balanced and symmetrical exteriors.","zh":"當時普遍轉向均衡對稱的外觀。"},{"en":"A general move towards something means a broad trend in that direction.","zh":"A general move towards something 指朝某方向發展的廣泛趨勢。"},{"en":"There is a general move towards online payment in many shops.","zh":"許多商店普遍轉向網上支付。"},{"en":"A general move towards smaller homes may happen when land becomes expensive.","zh":"當土地變貴，可能出現普遍轉向較小住宅的趨勢。"},{"en":"The phrase describes a widespread pattern, not one isolated example.","zh":"這個片語描述廣泛模式，而不是單一例子。"}],"source":"153 - British Architecture.pdf","sourcePage":7},{"front":"balanced and symmetrical exteriors","meaning":"均衡對稱的外觀","examples":[{"en":"Sixteenth-century buildings often had balanced and symmetrical exteriors.","zh":"十六世紀建築常有均衡對稱的外觀。"},{"en":"Balanced and symmetrical exteriors are building fronts where parts look evenly arranged on both sides.","zh":"均衡對稱的外觀是指建築正面兩邊看起來安排平均。"},{"en":"A house with a central door and equal windows on each side has a symmetrical exterior.","zh":"一間有中央大門、兩邊窗戶數量相同的房子，有對稱外觀。"},{"en":"Symmetry can make a building look orderly, calm, and controlled.","zh":"對稱可以令建築看起來有秩序、平靜和受控制。"},{"en":"The phrase describes visual balance on the outside of a building.","zh":"這個片語描述建築外部的視覺平衡。"}],"source":"153 - British Architecture.pdf","sourcePage":8},{"front":"central entrances","meaning":"中央入口","examples":[{"en":"Many buildings had symmetrical exteriors with central entrances.","zh":"許多建築有帶中央入口的對稱外觀。"},{"en":"Central entrances are main doorways placed in the middle of a building’s front.","zh":"中央入口是設於建築正面中間位置的主要門口。"},{"en":"A central entrance can make both sides of a building look balanced.","zh":"中央入口可以令建築兩邊看起來均衡。"},{"en":"Visitors often find a building easier to understand when the entrance is central and clear.","zh":"當入口位於中央且清晰時，訪客通常較容易理解建築。"},{"en":"The phrase describes both position and visual order.","zh":"這個片語同時描述位置和視覺秩序。"}],"source":"153 - British Architecture.pdf","sourcePage":8},{"front":"with the exception of","meaning":"除……之外","examples":[{"en":"With the exception of Inigo Jones, most early seventeenth-century buildings extended Tudor styles.","zh":"除伊尼戈・瓊斯之外，大多數十七世紀初建築都延伸都鐸風格。"},{"en":"With the exception of means not including one person, thing, or case.","zh":"With the exception of 指不包括某人、某物或某個情況。"},{"en":"With the exception of Mondays, the library closes at six o’clock.","zh":"除星期一之外，圖書館六點關門。"},{"en":"All students passed the test, with the exception of two who were absent.","zh":"除兩名缺席學生外，所有學生都通過測驗。"},{"en":"The phrase introduces the one case that does not follow the general pattern.","zh":"這個片語引出不符合一般模式的例外情況。"}],"source":"153 - British Architecture.pdf","sourcePage":8},{"front":"Inigo Jones","meaning":"伊尼戈・瓊斯","examples":[{"en":"Inigo Jones was exceptional among architects of his period.","zh":"伊尼戈・瓊斯在其時代的建築師中十分特殊。"},{"en":"Inigo Jones was an important English architect known for classical design.","zh":"伊尼戈・瓊斯是一位重要英格蘭建築師，以古典設計聞名。"},{"en":"He stood out because he handled proportion and classical detail more confidently than many others.","zh":"他之所以突出，是因為他比許多人更熟練地掌握比例和古典細節。"},{"en":"One skilled architect can influence later taste by showing a new standard.","zh":"一位熟練建築師可以透過展示新標準影響後來品味。"},{"en":"The name is linked with a shift towards classical architecture in Britain.","zh":"這個名字與英國轉向古典建築有關。"}],"source":"153 - British Architecture.pdf","sourcePage":8},{"front":"confident handling of","meaning":"熟練掌握","examples":[{"en":"Inigo Jones was known for his confident handling of classical detail and proportion.","zh":"伊尼戈・瓊斯以熟練掌握古典細節和比例而聞名。"},{"en":"Confident handling of something means skilful and assured use of it.","zh":"Confident handling of something 指熟練而有把握地運用某事。"},{"en":"A good chef shows confident handling of simple ingredients by making them taste special.","zh":"好廚師能熟練掌握簡單食材，令它們味道特別。"},{"en":"A teacher’s confident handling of difficult questions can calm the class.","zh":"老師熟練處理困難問題，可以令課堂平靜。"},{"en":"The phrase suggests control, skill, and clear understanding.","zh":"這個片語暗示控制力、技巧和清晰理解。"}],"source":"153 - British Architecture.pdf","sourcePage":8},{"front":"classical detail and proportion","meaning":"古典細節和比例","examples":[{"en":"Inigo Jones handled classical detail and proportion with confidence.","zh":"伊尼戈・瓊斯熟練掌握古典細節和比例。"},{"en":"Classical detail and proportion refers to design features and balanced measurements inspired by ancient Greek and Roman architecture.","zh":"Classical detail and proportion 指受古希臘和古羅馬建築啟發的設計細節和均衡尺寸。"},{"en":"Columns, pediments, and carefully measured façades can show classical detail and proportion.","zh":"柱子、山牆和仔細量度的立面可以展示古典細節和比例。"},{"en":"Good proportion can make a building feel calm and orderly.","zh":"良好比例可以令建築感覺平靜而有秩序。"},{"en":"The phrase is about disciplined beauty, not random decoration.","zh":"這個片語關乎有紀律的美，而不是隨意裝飾。"}],"source":"153 - British Architecture.pdf","sourcePage":8},{"front":"set him apart from","meaning":"使他有別於","examples":[{"en":"His handling of classical style set him apart from other architects.","zh":"他對古典風格的掌握使他有別於其他建築師。"},{"en":"To set someone apart from others means to make them clearly different or special.","zh":"To set someone apart from others 指使某人明顯不同或特別。"},{"en":"Her calm speaking style sets her apart from other presenters.","zh":"她冷靜的演講風格使她有別於其他主持人。"},{"en":"A restaurant’s careful service can set it apart from nearby competitors.","zh":"餐廳細心服務可以使它有別於附近競爭者。"},{"en":"The phrase shows what makes a person or thing stand out.","zh":"這個片語顯示甚麼令某人或某物突出。"}],"source":"153 - British Architecture.pdf","sourcePage":8},{"front":"architects of the period","meaning":"當時的建築師","examples":[{"en":"Inigo Jones stood apart from other architects of the period.","zh":"伊尼戈・瓊斯有別於當時其他建築師。"},{"en":"Architects of the period are architects working during the same historical time.","zh":"Architects of the period 指在同一歷史時期工作的建築師。"},{"en":"Architects of the period often shared similar materials, clients, and design expectations.","zh":"當時的建築師通常使用相似材料，面對相似客戶和設計期望。"},{"en":"One architect may stand out if their work is more original than others of the period.","zh":"如果一位建築師的作品比同時期其他人更具原創性，他可能會突出。"},{"en":"The phrase helps compare people within the same historical context.","zh":"這個片語幫助在同一歷史背景中比較人物。"}],"source":"153 - British Architecture.pdf","sourcePage":8},{"front":"early seventeenth-century buildings","meaning":"十七世紀初建築","examples":[{"en":"Most early seventeenth-century buildings developed from late Tudor work.","zh":"大多數十七世紀初建築由都鐸後期作品發展而來。"},{"en":"Early seventeenth-century buildings are buildings from the early 1600s.","zh":"Early seventeenth-century buildings 是指十七世紀早期，即1600年代初的建築。"},{"en":"Such buildings may combine older Tudor energy with newer classical interests.","zh":"這類建築可能結合較舊的都鐸活力和較新的古典興趣。"},{"en":"Buildings from a transition period often show features from both old and new styles.","zh":"過渡時期的建築常同時顯示舊風格和新風格特徵。"},{"en":"The phrase places architecture in a precise historical moment.","zh":"這個片語把建築放在精確歷史時刻中。"}],"source":"153 - British Architecture.pdf","sourcePage":8},{"front":"take something one step further","meaning":"把……再推進一步","examples":[{"en":"Many buildings took the exuberance of late Tudor work one step further.","zh":"許多建築把都鐸後期作品的奔放風格再推進一步。"},{"en":"To take something one step further means to develop or intensify it beyond its earlier form.","zh":"To take something one step further 指把某事在原有基礎上進一步發展或加強。"},{"en":"A teacher can take a writing lesson one step further by adding peer feedback.","zh":"老師可以透過加入同學回饋，把寫作課再推進一步。"},{"en":"A designer may take a simple idea one step further with better materials and clearer details.","zh":"設計師可以用更好材料和更清晰細節，把簡單想法再推進一步。"},{"en":"The phrase shows continuation plus extra development.","zh":"這個片語顯示延續再加上額外發展。"}],"source":"153 - British Architecture.pdf","sourcePage":8},{"front":"innocent exuberance","meaning":"天真奔放的風格","examples":[{"en":"Early seventeenth-century buildings often showed the innocent exuberance of late Tudor work.","zh":"十七世紀初建築常展示都鐸後期作品天真奔放的風格。"},{"en":"Innocent exuberance means lively, energetic, and slightly playful richness without heavy seriousness.","zh":"Innocent exuberance 指活潑、有活力、略帶玩味而不沉重嚴肅的豐富感。"},{"en":"A colourful school mural may show innocent exuberance through bright shapes and joyful details.","zh":"色彩鮮明的學校壁畫可能透過明亮形狀和快樂細節展示天真奔放的風格。"},{"en":"In architecture, exuberance can appear in decoration, unusual forms, and bold surfaces.","zh":"在建築中，奔放可以表現於裝飾、不尋常形式和大膽表面。"},{"en":"The phrase suggests cheerful energy rather than strict discipline.","zh":"這個片語暗示愉快能量，而不是嚴格紀律。"}],"source":"153 - British Architecture.pdf","sourcePage":8},{"front":"late Tudor work","meaning":"都鐸後期作品","examples":[{"en":"Late Tudor work influenced early seventeenth-century buildings.","zh":"都鐸後期作品影響了十七世紀初建築。"},{"en":"Late Tudor work refers to buildings or designs from the later part of the Tudor period.","zh":"Late Tudor work 指都鐸時期後段的建築或設計作品。"},{"en":"It often included decorative detail, large windows, and confident domestic display.","zh":"它常包括裝飾細節、大窗和自信的住宅展示。"},{"en":"Later architects may borrow from late Tudor work when they want richness and historical character.","zh":"後來建築師想要豐富感和歷史特色時，可能借鑑都鐸後期作品。"},{"en":"The phrase links one architectural period to the next.","zh":"這個片語把一個建築時期連接到下一個時期。"}],"source":"153 - British Architecture.pdf","sourcePage":9},{"front":"the Civil War and its aftermath","meaning":"內戰及其後果","examples":[{"en":"The Civil War and its aftermath sent many nobles to the Continent.","zh":"內戰及其後果使許多貴族前往歐洲大陸。"},{"en":"The Civil War and its aftermath means the war itself and the consequences that followed it.","zh":"The Civil War and its aftermath 指內戰本身以及之後產生的後果。"},{"en":"A conflict and its aftermath can change where people live, who holds power, and what gets built.","zh":"一場衝突及其後果可以改變人們住在哪裡、誰掌權和建造甚麼。"},{"en":"Aftermath may last long after the fighting has stopped.","zh":"後果可能在戰鬥停止很久後仍持續。"},{"en":"The phrase includes both the event and its later effects.","zh":"這個片語包括事件本身和後來影響。"}],"source":"153 - British Architecture.pdf","sourcePage":9},{"front":"sent many gentlemen and nobles to","meaning":"使許多紳士和貴族前往……","examples":[{"en":"The Civil War sent many gentlemen and nobles to the Continent.","zh":"內戰使許多紳士和貴族前往歐洲大陸。"},{"en":"To send people to a place means to cause them to go there, often because of pressure or danger.","zh":"To send people to a place 指使人前往某地，常因壓力或危險。"},{"en":"Economic hardship may send young workers to bigger cities.","zh":"經濟困難可能使年輕工人前往較大城市。"},{"en":"War can send families to safer countries.","zh":"戰爭可以使家庭前往較安全的國家。"},{"en":"The phrase shows that people moved because circumstances pushed them.","zh":"這個片語顯示人們因環境推動而移動。"}],"source":"153 - British Architecture.pdf","sourcePage":9},{"front":"the Continent","meaning":"歐洲大陸","examples":[{"en":"Many royalists went to the Continent during and after the Civil War.","zh":"許多保皇派在內戰期間及之後前往歐洲大陸。"},{"en":"The Continent means mainland Europe, especially when spoken from a British perspective.","zh":"The Continent 指歐洲大陸，尤其是從英國角度來說。"},{"en":"British travellers may say they are going to the Continent when they visit France or Italy.","zh":"英國旅客前往法國或意大利時，可能說自己要去歐洲大陸。"},{"en":"Contact with the Continent can bring new ideas, fashions, and building styles.","zh":"接觸歐洲大陸可以帶來新想法、時尚和建築風格。"},{"en":"The phrase contrasts Britain with mainland Europe.","zh":"這個片語把英國與歐洲大陸作對比。"}],"source":"153 - British Architecture.pdf","sourcePage":9},{"front":"escape the fighting","meaning":"逃避戰火","examples":[{"en":"Some nobles went abroad to escape the fighting.","zh":"有些貴族出國以逃避戰火。"},{"en":"To escape the fighting means to leave a place in order to avoid war or violence.","zh":"To escape the fighting 指離開某地以避免戰爭或暴力。"},{"en":"Families may move to another town to escape the fighting near their homes.","zh":"家庭可能搬到另一個城鎮，以逃避家附近的戰火。"},{"en":"People who escape the fighting often lose property, work, and normal life.","zh":"逃避戰火的人常失去財產、工作和正常生活。"},{"en":"The phrase focuses on safety as the reason for leaving.","zh":"這個片語著重安全是離開的原因。"}],"source":"153 - British Architecture.pdf","sourcePage":9},{"front":"follow Charles II into exile","meaning":"跟隨查理二世流亡","examples":[{"en":"Some nobles followed Charles II into exile.","zh":"有些貴族跟隨查理二世流亡。"},{"en":"To follow someone into exile means to leave one’s country with that person after political defeat or danger.","zh":"To follow someone into exile 指在政治失敗或危險後，跟隨某人離開自己的國家。"},{"en":"Supporters may follow a leader into exile if they remain loyal after a revolution.","zh":"如果支持者在革命後仍忠誠，可能跟隨領袖流亡。"},{"en":"Exile can expose people to foreign cultures, languages, and styles.","zh":"流亡可以使人接觸外國文化、語言和風格。"},{"en":"The phrase shows loyalty during political loss.","zh":"這個片語顯示政治失敗中的忠誠。"}],"source":"153 - British Architecture.pdf","sourcePage":9},{"front":"came into contact with","meaning":"接觸到","examples":[{"en":"In Europe, nobles came into contact with French, Dutch and Italian architecture.","zh":"在歐洲，貴族接觸到法國、荷蘭和意大利建築。"},{"en":"To come into contact with something means to meet, see, or experience it directly.","zh":"To come into contact with something 指直接遇到、看見或體驗某事。"},{"en":"Students come into contact with different accents when they watch international videos.","zh":"學生觀看國際影片時，會接觸到不同口音。"},{"en":"Travellers may come into contact with new foods, customs, and design ideas.","zh":"旅客可能接觸到新食物、習俗和設計想法。"},{"en":"The phrase often explains how influence begins.","zh":"這個片語常解釋影響如何開始。"}],"source":"153 - British Architecture.pdf","sourcePage":9},{"front":"French, Dutch and Italian architecture","meaning":"法國、荷蘭和意大利建築","examples":[{"en":"British nobles encountered French, Dutch and Italian architecture.","zh":"英國貴族遇見了法國、荷蘭和意大利建築。"},{"en":"French, Dutch and Italian architecture refers to building styles from France, the Netherlands, and Italy.","zh":"French, Dutch and Italian architecture 指來自法國、荷蘭和意大利的建築風格。"},{"en":"Travelling nobles could compare British houses with foreign palaces, townhouses, and churches.","zh":"旅行中的貴族可以把英國房屋與外國宮殿、城市住宅和教堂比較。"},{"en":"Exposure to foreign architecture can change what clients ask architects to build at home.","zh":"接觸外國建築可以改變客戶回國後要求建築師建造的東西。"},{"en":"The phrase groups several European influences together.","zh":"這個片語把幾種歐洲影響放在一起。"}],"source":"153 - British Architecture.pdf","sourcePage":9},{"front":"Charles’s restoration","meaning":"查理二世復辟","examples":[{"en":"Charles’s restoration in 1660 triggered new building activity.","zh":"1660年查理二世復辟引發新的建築活動。"},{"en":"Charles’s restoration means the return of Charles II to the throne in 1660.","zh":"Charles’s restoration 指查理二世於1660年重返王位。"},{"en":"A restoration of monarchy can change politics, social confidence, and artistic taste.","zh":"君主制復辟可以改變政治、社會信心和藝術品味。"},{"en":"After Charles’s restoration, royalist families wanted houses that reflected new power and fashion.","zh":"查理二世復辟後，保皇派家庭想要反映新權力和時尚的住宅。"},{"en":"The phrase refers to a political return with cultural consequences.","zh":"這個片語指帶有文化後果的政治回歸。"}],"source":"153 - British Architecture.pdf","sourcePage":9},{"front":"a flurry of","meaning":"一陣；大量突如其來的","examples":[{"en":"After the restoration, there was a flurry of building activity.","zh":"復辟後出現了一陣建築活動。"},{"en":"A flurry of something means a sudden burst of many actions or events.","zh":"A flurry of something 指大量行動或事件突然集中出現。"},{"en":"A school may receive a flurry of emails before exam results are released.","zh":"考試成績公布前，學校可能收到一陣電郵。"},{"en":"Good news about funding can lead to a flurry of new projects.","zh":"關於資金的好消息可以帶來一陣新項目。"},{"en":"The phrase suggests quick, busy activity within a short time.","zh":"這個片語暗示短時間內快速而繁忙的活動。"}],"source":"153 - British Architecture.pdf","sourcePage":9},{"front":"building activity","meaning":"建築活動","examples":[{"en":"Royalists began a new wave of building activity.","zh":"保皇派開始新一波建築活動。"},{"en":"Building activity means the planning, construction, repair, or expansion of buildings.","zh":"Building activity 指建築物的規劃、建造、維修或擴展。"},{"en":"A city with many cranes and construction sites has high building activity.","zh":"一個有許多吊機和工地的城市，建築活動很活躍。"},{"en":"Building activity often increases when people have money, land, and confidence.","zh":"當人們有金錢、土地和信心時，建築活動常會增加。"},{"en":"The phrase refers to the amount of construction happening in a period.","zh":"這個片語指某段時期正在發生的建造量。"}],"source":"153 - British Architecture.pdf","sourcePage":9},{"front":"royalists","meaning":"保皇派","examples":[{"en":"Royalists reclaimed their property after Charles II returned.","zh":"查理二世回歸後，保皇派收回他們的財產。"},{"en":"Royalists are people who support a king, queen, or royal family.","zh":"Royalists 是支持國王、女王或王室的人。"},{"en":"During a civil war, royalists may fight against groups that want to limit or remove monarchy.","zh":"在內戰中，保皇派可能與想限制或廢除君主制的群體作戰。"},{"en":"When royalists regain power, their buildings may express authority and victory.","zh":"當保皇派重新掌權，他們的建築可能表達權威和勝利。"},{"en":"The phrase identifies a political side, not simply rich people.","zh":"這個詞指出一個政治陣營，而不只是富人。"}],"source":"153 - British Architecture.pdf","sourcePage":10},{"front":"reclaimed their property","meaning":"收回他們的財產","examples":[{"en":"Royalists reclaimed their property and built new houses.","zh":"保皇派收回他們的財產並建造新房屋。"},{"en":"To reclaim property means to take back land, houses, or possessions that were lost or taken away.","zh":"To reclaim property 指收回失去或被奪走的土地、房屋或財物。"},{"en":"A family may reclaim its property after a court proves ownership.","zh":"法庭證明所有權後，一個家庭可能收回其財產。"},{"en":"Reclaiming property can restore wealth and social position.","zh":"收回財產可以恢復財富和社會地位。"},{"en":"The phrase suggests a return of control after loss.","zh":"這個片語暗示失去後重新取得控制。"}],"source":"153 - British Architecture.pdf","sourcePage":10},{"front":"reflecting the latest European trends","meaning":"反映最新歐洲潮流","examples":[{"en":"Royalists built houses reflecting the latest European trends.","zh":"保皇派建造反映最新歐洲潮流的房屋。"},{"en":"Reflecting the latest European trends means showing the newest styles or ideas from Europe.","zh":"Reflecting the latest European trends 指展示歐洲最新風格或想法。"},{"en":"A hotel may use furniture reflecting the latest design trends to appear modern.","zh":"酒店可能使用反映最新設計潮流的家具，以顯得現代。"},{"en":"Wealthy clients often copy foreign trends to show taste and status.","zh":"富裕客戶常模仿外國潮流，以展示品味和地位。"},{"en":"The phrase links local buildings with international fashion.","zh":"這個片語把本地建築與國際時尚連接起來。"}],"source":"153 - British Architecture.pdf","sourcePage":10},{"front":"the British Baroque","meaning":"英國巴洛克風格","examples":[{"en":"The British Baroque expressed authority and absolutist ideology.","zh":"英國巴洛克風格表達權威和絕對主義意識形態。"},{"en":"The British Baroque was a grand architectural style in Britain influenced by Baroque ideas.","zh":"英國巴洛克風格是英國一種受巴洛克理念影響的宏偉建築風格。"},{"en":"It often used dramatic scale, rich decoration, and strong visual effects.","zh":"它常使用戲劇化尺度、豐富裝飾和強烈視覺效果。"},{"en":"Powerful patrons used the British Baroque to show order, wealth, and authority.","zh":"有權勢的委託人利用英國巴洛克風格展示秩序、財富和權威。"},{"en":"The phrase names a style that is both artistic and political.","zh":"這個片語命名一種既藝術又政治的風格。"}],"source":"153 - British Architecture.pdf","sourcePage":10},{"front":"a reassertion of authority","meaning":"權威的重新確立","examples":[{"en":"The British Baroque was a reassertion of authority.","zh":"英國巴洛克風格是權威的重新確立。"},{"en":"A reassertion of authority means showing power again after it has been challenged or weakened.","zh":"A reassertion of authority 指權力受到挑戰或削弱後重新顯示權威。"},{"en":"A headteacher may make a reassertion of authority after repeated rule-breaking.","zh":"校長可能在學生多次違規後重新確立權威。"},{"en":"After political disorder, rulers may use buildings to reassert authority.","zh":"政治混亂後，統治者可能利用建築重新確立權威。"},{"en":"The phrase suggests power being publicly restored.","zh":"這個片語暗示權力被公開恢復。"}],"source":"153 - British Architecture.pdf","sourcePage":10},{"front":"expression of absolutist ideology","meaning":"絕對主義意識形態的表達","examples":[{"en":"The style was an expression of absolutist ideology.","zh":"這種風格是絕對主義意識形態的表達。"},{"en":"An expression of absolutist ideology is a visible way of showing belief in strong, centralised royal power.","zh":"An expression of absolutist ideology 是以可見方式展示對強大中央王權的信念。"},{"en":"A palace can express absolutist ideology by making the ruler seem grand and untouchable.","zh":"宮殿可以透過令統治者顯得宏偉而不可接近，表達絕對主義意識形態。"},{"en":"Architecture can communicate political ideas even when no words are written on it.","zh":"建築即使沒有文字，也可以傳達政治理念。"},{"en":"The phrase connects artistic style with political belief.","zh":"這個片語把藝術風格與政治信念連接起來。"}],"source":"153 - British Architecture.pdf","sourcePage":10},{"front":"a world turned upside down","meaning":"顛倒混亂的世界","examples":[{"en":"The royalists remembered a world turned upside down during the Civil War.","zh":"保皇派記得內戰期間一個顛倒混亂的世界。"},{"en":"A world turned upside down means a society in which normal order has been completely disturbed.","zh":"A world turned upside down 指正常秩序被完全打亂的社會。"},{"en":"After a sudden disaster, a family may feel their world has been turned upside down.","zh":"突如其來的災難後，一個家庭可能覺得自己的世界被顛倒。"},{"en":"Civil war can turn a world upside down by changing power, law, safety, and daily life.","zh":"內戰可以透過改變權力、法律、安全和日常生活令世界顛倒混亂。"},{"en":"The phrase is emotional and suggests deep disorder.","zh":"這個片語帶有情感，暗示深層混亂。"}],"source":"153 - British Architecture.pdf","sourcePage":10},{"front":"heavy and rich","meaning":"厚重而華麗","examples":[{"en":"The British Baroque style is heavy and rich.","zh":"英國巴洛克風格厚重而華麗。"},{"en":"Heavy and rich describes a style that feels solid, grand, dense, and full of decoration.","zh":"Heavy and rich 描述一種感覺堅實、宏偉、密集且充滿裝飾的風格。"},{"en":"A theatre with dark wood, gold detail, and thick curtains may feel heavy and rich.","zh":"有深色木材、金色細節和厚窗簾的劇院，可能感覺厚重而華麗。"},{"en":"Such a style can impress viewers but may also feel overwhelming.","zh":"這種風格可以令觀者印象深刻，但也可能令人感到壓迫。"},{"en":"The phrase describes visual weight and luxury.","zh":"這個片語描述視覺重量和奢華感。"}],"source":"153 - British Architecture.pdf","sourcePage":10},{"front":"overblown and melodramatic","meaning":"過分誇張而戲劇化","examples":[{"en":"The style can seem overblown and melodramatic.","zh":"這種風格可能顯得過分誇張而戲劇化。"},{"en":"Overblown and melodramatic means exaggerated, too emotional, or too theatrical.","zh":"Overblown and melodramatic 指誇張、過度情緒化或過於戲劇化。"},{"en":"A speech with too many grand claims may sound overblown and melodramatic.","zh":"一篇充滿宏大聲稱的演講可能聽起來過分誇張而戲劇化。"},{"en":"Decoration becomes overblown when it tries too hard to impress.","zh":"當裝飾太努力想令人印象深刻時，就會變得過分誇張。"},{"en":"The phrase is critical and suggests a lack of restraint.","zh":"這個片語帶批評意味，暗示缺乏克制。"}],"source":"153 - British Architecture.pdf","sourcePage":10},{"front":"underpin","meaning":"支撐；構成基礎","examples":[{"en":"The politics which underpin the style are questionable.","zh":"支撐這種風格的政治理念值得質疑。"},{"en":"To underpin something means to support it or form its hidden foundation.","zh":"To underpin something 指支撐某事或構成其隱藏基礎。"},{"en":"Trust underpins a good friendship because people need to believe each other.","zh":"信任支撐良好友誼，因為人們需要相信彼此。"},{"en":"Clear rules underpin a fair classroom.","zh":"清晰規則支撐公平課室。"},{"en":"The phrase explains what supports something from below or behind.","zh":"這個片語解釋某事背後或底層由甚麼支持。"}],"source":"153 - British Architecture.pdf","sourcePage":10},{"front":"questionable","meaning":"值得質疑的","examples":[{"en":"The politics behind the style are questionable.","zh":"這種風格背後的政治理念值得質疑。"},{"en":"Questionable means doubtful, problematic, or open to criticism.","zh":"Questionable 指可疑、有問題或可以被批評。"},{"en":"A company’s claim is questionable if it gives no evidence.","zh":"如果公司沒有提供證據，它的聲稱便值得質疑。"},{"en":"A decision may be questionable when it benefits only powerful people.","zh":"當一個決定只惠及有權勢的人，它可能值得質疑。"},{"en":"The phrase suggests that something should not be accepted without examination.","zh":"這個詞暗示某事不應未經檢視便被接受。"}],"source":"153 - British Architecture.pdf","sourcePage":10},{"front":"breathtaking","meaning":"令人驚嘆的","examples":[{"en":"The products of British Baroque architecture are breathtaking.","zh":"英國巴洛克建築的作品令人驚嘆。"},{"en":"Breathtaking means extremely impressive, beautiful, or exciting.","zh":"Breathtaking 指極其令人印象深刻、美麗或興奮。"},{"en":"A mountain view at sunrise can be breathtaking.","zh":"日出時的山景可以令人驚嘆。"},{"en":"A building may be breathtaking when its scale and detail surprise visitors.","zh":"當建築的規模和細節令訪客驚訝，它可能令人驚嘆。"},{"en":"The word shows strong admiration and emotional impact.","zh":"這個詞顯示強烈讚賞和情感衝擊。"}],"source":"153 - British Architecture.pdf","sourcePage":11},{"front":"glass-and-iron","meaning":"玻璃和鐵製的","examples":[{"en":"The Crystal Palace was a huge glass-and-iron building.","zh":"水晶宮是一座巨大的玻璃和鐵製建築。"},{"en":"Glass-and-iron means made mainly with glass panels and iron structures.","zh":"Glass-and-iron 指主要由玻璃板和鐵結構製成。"},{"en":"A glass-and-iron railway station can feel bright, light, and industrial.","zh":"玻璃和鐵製火車站可以感覺明亮、輕巧而工業化。"},{"en":"Using glass and iron allowed builders to create large open spaces.","zh":"使用玻璃和鐵使建造者能創造大型開放空間。"},{"en":"The phrase points to industrial materials rather than traditional stone or wood.","zh":"這個片語指向工業材料，而不是傳統石材或木材。"}],"source":"153 - British Architecture.pdf","sourcePage":11},{"front":"Crystal Palace","meaning":"水晶宮","examples":[{"en":"The Crystal Palace was designed to house the Great Exhibition.","zh":"水晶宮被設計用來舉辦萬國工業博覽會。"},{"en":"The Crystal Palace was a large nineteenth-century glass-and-iron exhibition building.","zh":"水晶宮是一座十九世紀大型玻璃和鐵製展覽建築。"},{"en":"It showed how industrial materials could create a new kind of architecture.","zh":"它顯示工業材料可以創造新型建築。"},{"en":"Exhibition buildings like the Crystal Palace needed wide spaces for visitors and displays.","zh":"像水晶宮這樣的展覽建築需要寬闊空間容納訪客和展品。"},{"en":"The name is linked with Victorian confidence in industry and progress.","zh":"這個名字與維多利亞時代對工業和進步的信心相關。"}],"source":"153 - British Architecture.pdf","sourcePage":11},{"front":"designed by","meaning":"由……設計","examples":[{"en":"The Crystal Palace was designed by Joseph Paxton.","zh":"水晶宮由約瑟夫・帕克斯頓設計。"},{"en":"Designed by means planned or created by a particular person or group.","zh":"Designed by 指由某人或某團體規劃或創作。"},{"en":"A school garden designed by students may reflect their daily needs.","zh":"由學生設計的學校花園可能反映他們的日常需要。"},{"en":"Buildings are often remembered together with the architects who designed them.","zh":"建築物常與設計它們的建築師一同被記住。"},{"en":"The phrase identifies the creator of a design.","zh":"這個片語指出設計的創作者。"}],"source":"153 - British Architecture.pdf","sourcePage":11},{"front":"Joseph Paxton","meaning":"約瑟夫・帕克斯頓","examples":[{"en":"Joseph Paxton designed the Crystal Palace.","zh":"約瑟夫・帕克斯頓設計了水晶宮。"},{"en":"Joseph Paxton was the designer associated with the Crystal Palace.","zh":"約瑟夫・帕克斯頓是與水晶宮相關的設計者。"},{"en":"His design showed how glass and iron could be used on a huge scale.","zh":"他的設計顯示玻璃和鐵可以大規模使用。"},{"en":"A designer can become famous when one project changes public ideas about building.","zh":"當一個項目改變公眾對建築的想法，設計者便可能成名。"},{"en":"The name is important in discussions of nineteenth-century industrial architecture.","zh":"這個名字在討論十九世紀工業建築時很重要。"}],"source":"153 - British Architecture.pdf","sourcePage":11},{"front":"to house","meaning":"用作容納；舉辦","examples":[{"en":"The Crystal Palace was built to house the Great Exhibition.","zh":"水晶宮被建造用作舉辦萬國工業博覽會。"},{"en":"To house an event or object means to contain, hold, or provide space for it.","zh":"To house an event or object 指容納、保存或為其提供空間。"},{"en":"A museum is built to house paintings, sculptures, and historical objects.","zh":"博物館被建造用作容納繪畫、雕塑和歷史物件。"},{"en":"A sports hall may house exams when many students need a large room.","zh":"當許多學生需要大型房間時，體育館可能用作舉辦考試。"},{"en":"The phrase focuses on the purpose of providing space.","zh":"這個片語著重提供空間的目的。"}],"source":"153 - British Architecture.pdf","sourcePage":11},{"front":"the Great Exhibition","meaning":"萬國工業博覽會","examples":[{"en":"The Crystal Palace housed the Great Exhibition of 1851.","zh":"水晶宮舉辦了1851年的萬國工業博覽會。"},{"en":"The Great Exhibition was a major nineteenth-century exhibition showing industry, invention, and empire.","zh":"萬國工業博覽會是十九世紀展示工業、發明和帝國的大型展覽。"},{"en":"Visitors went to the Great Exhibition to see machines, products, and design from many places.","zh":"訪客前往萬國工業博覽會觀看來自多地的機器、產品和設計。"},{"en":"Such exhibitions helped societies celebrate progress and compare achievements.","zh":"這類展覽幫助社會慶祝進步並比較成就。"},{"en":"The phrase is closely connected with Victorian industrial confidence.","zh":"這個片語與維多利亞時代的工業信心密切相關。"}],"source":"153 - British Architecture.pdf","sourcePage":11},{"front":"another strand to","meaning":"……的另一條脈絡","examples":[{"en":"The Crystal Palace shows another strand to nineteenth-century architecture.","zh":"水晶宮顯示十九世紀建築的另一條脈絡。"},{"en":"Another strand to something means another important line, type, or aspect within it.","zh":"Another strand to something 指某事之中的另一條重要路線、類型或方面。"},{"en":"Online learning is another strand to modern education, alongside classroom teaching.","zh":"網上學習是現代教育中除課室教學外的另一條脈絡。"},{"en":"Industrial design became another strand to architecture when new materials appeared.","zh":"當新材料出現，工業設計成為建築的另一條脈絡。"},{"en":"The phrase adds complexity by showing that a topic has more than one direction.","zh":"這個片語透過顯示主題不只一個方向，增加複雜性。"}],"source":"153 - British Architecture.pdf","sourcePage":11},{"front":"nineteenth-century architecture","meaning":"十九世紀建築","examples":[{"en":"The Crystal Palace represents an industrial strand of nineteenth-century architecture.","zh":"水晶宮代表十九世紀建築中的工業脈絡。"},{"en":"Nineteenth-century architecture refers to buildings and styles from the 1800s.","zh":"Nineteenth-century architecture 指1800年代的建築物和風格。"},{"en":"It included historic revival styles as well as new industrial materials like iron and glass.","zh":"它包括歷史復興風格，也包括鐵和玻璃等新工業材料。"},{"en":"Cities changed rapidly in the nineteenth century because industry and transport expanded.","zh":"十九世紀城市迅速改變，因為工業和交通擴展。"},{"en":"The phrase connects architecture with the age of factories, railways, and exhibitions.","zh":"這個片語把建築與工廠、鐵路和展覽的時代連接起來。"}],"source":"153 - British Architecture.pdf","sourcePage":11},{"front":"embraced new industrial processes","meaning":"採納新的工業流程","examples":[{"en":"Some nineteenth-century architecture embraced new industrial processes.","zh":"一些十九世紀建築採納新的工業流程。"},{"en":"To embrace new industrial processes means to accept and use new factory-based methods and materials.","zh":"To embrace new industrial processes 指接受並使用新的工廠化方法和材料。"},{"en":"A company embraces new processes when it replaces slow handwork with efficient machines.","zh":"當公司以高效機器取代緩慢手工時，它就是採納新流程。"},{"en":"Architecture changed when iron, glass, and mass-produced parts became easier to use.","zh":"當鐵、玻璃和大規模生產的部件更容易使用時，建築便改變。"},{"en":"The phrase suggests active acceptance of modern industry.","zh":"這個片語暗示主動接受現代工業。"}],"source":"153 - British Architecture.pdf","sourcePage":11},{"front":"it wasn’t long before","meaning":"不久之後","examples":[{"en":"It wasn’t long before confidence in progress came to be regarded with suspicion.","zh":"不久之後，人們對進步的信心逐漸被懷疑地看待。"},{"en":"It wasn’t long before means something happened soon after another event or situation.","zh":"It wasn’t long before 指某事在另一事件或情況之後很快發生。"},{"en":"It wasn’t long before students became tired after a whole day of exams.","zh":"一整天考試後，不久學生便開始疲倦。"},{"en":"When rent rose sharply, it wasn’t long before small shops began closing.","zh":"當租金大幅上升，不久之後小店便開始結業。"},{"en":"The phrase shows that the second event followed quite quickly.","zh":"這個片語顯示第二件事很快跟着發生。"}],"source":"153 - British Architecture.pdf","sourcePage":11},{"front":"confidence in progress","meaning":"對進步的信心","examples":[{"en":"Confidence in progress was later viewed with suspicion.","zh":"對進步的信心後來被懷疑地看待。"},{"en":"Confidence in progress means belief that society, technology, or knowledge will keep improving life.","zh":"Confidence in progress 指相信社會、科技或知識會持續改善生活。"},{"en":"People had confidence in progress when new machines seemed to make work faster and easier.","zh":"當新機器似乎令工作更快更容易，人們便對進步有信心。"},{"en":"Industrial pollution can weaken confidence in progress because improvement may bring harm too.","zh":"工業污染可以削弱對進步的信心，因為改善也可能帶來傷害。"},{"en":"The phrase captures hope in modern development.","zh":"這個片語捕捉人們對現代發展的希望。"}],"source":"153 - British Architecture.pdf","sourcePage":12},{"front":"came to be regarded with suspicion","meaning":"逐漸被懷疑地看待","examples":[{"en":"Industrial progress came to be regarded with suspicion.","zh":"工業進步逐漸被懷疑地看待。"},{"en":"To come to be regarded with suspicion means people gradually began to distrust or question something.","zh":"To come to be regarded with suspicion 指人們逐漸開始不信任或質疑某事。"},{"en":"A new app may come to be regarded with suspicion if it collects too much personal data.","zh":"如果一個新應用程式收集太多個人資料，它可能逐漸被懷疑地看待。"},{"en":"Mass production came to be questioned when people felt it removed human skill.","zh":"當人們覺得大規模生產消除了人的技藝，它便逐漸受到質疑。"},{"en":"The phrase shows a gradual change in public attitude.","zh":"這個片語顯示公眾態度逐步改變。"}],"source":"153 - British Architecture.pdf","sourcePage":12},{"front":"mass production","meaning":"大規模生產","examples":[{"en":"Mass production changed buildings and furnishings.","zh":"大規模生產改變了建築和家具。"},{"en":"Mass production means making large numbers of identical products, usually by machines.","zh":"Mass production 指通常用機器大量製造相同產品。"},{"en":"A factory uses mass production when it makes thousands of the same chair every week.","zh":"工廠每週製造數千張相同椅子時，就是使用大規模生產。"},{"en":"Mass production can lower prices but may reduce individuality and craft.","zh":"大規模生產可以降低價格，但可能減少個性和工藝。"},{"en":"The phrase is central to industrial society.","zh":"這個片語是工業社會的核心概念。"}],"source":"153 - British Architecture.pdf","sourcePage":12},{"front":"resulted in","meaning":"導致","examples":[{"en":"Mass production resulted in buildings that seemed too perfect.","zh":"大規模生產導致建築看起來過於完美。"},{"en":"Resulted in means caused something to happen as an effect.","zh":"Resulted in 指造成某事作為結果發生。"},{"en":"Poor planning resulted in long queues outside the clinic.","zh":"規劃不善導致診所外出現長隊。"},{"en":"More buses can result in shorter waiting times for passengers.","zh":"更多巴士可以導致乘客等候時間縮短。"},{"en":"The phrase connects an action or situation with its outcome.","zh":"這個片語把行動或情況與結果連接起來。"}],"source":"153 - British Architecture.pdf","sourcePage":12},{"front":"buildings and furnishings","meaning":"建築和家具","examples":[{"en":"Mass production affected buildings and furnishings.","zh":"大規模生產影響了建築和家具。"},{"en":"Buildings and furnishings means structures and the furniture or objects placed inside them.","zh":"Buildings and furnishings 指建築物以及放在其中的家具或物件。"},{"en":"A hotel’s buildings and furnishings both affect how guests feel.","zh":"酒店的建築和家具都會影響客人的感受。"},{"en":"Industrial methods changed not only houses but also chairs, tables, curtains, and fittings.","zh":"工業方法不只改變房屋，也改變椅子、桌子、窗簾和裝置。"},{"en":"The phrase covers both architecture and interior objects.","zh":"這個片語涵蓋建築和室內物件。"}],"source":"153 - British Architecture.pdf","sourcePage":12},{"front":"too perfect","meaning":"過於完美","examples":[{"en":"Mass-produced objects were criticised as being too perfect.","zh":"大規模生產的物件被批評為過於完美。"},{"en":"Too perfect means so regular, smooth, or identical that something feels unnatural or lifeless.","zh":"Too perfect 指某物過於規整、光滑或相同，以致感覺不自然或沒有生命力。"},{"en":"A handmade bowl may feel warmer than a factory bowl that looks too perfect.","zh":"手製碗可能比看起來過於完美的工廠碗更溫暖。"},{"en":"If every shop looks exactly the same, the street may feel too perfect and boring.","zh":"如果每間店看起來完全一樣，街道可能顯得過於完美而沉悶。"},{"en":"The phrase criticises perfection when it removes human character.","zh":"這個片語批評那種消除人性特色的完美。"}],"source":"153 - British Architecture.pdf","sourcePage":12},{"front":"individual craftsman","meaning":"個別工匠","examples":[{"en":"The individual craftsman no longer had a major role in creation.","zh":"個別工匠不再在創作中擔當重要角色。"},{"en":"An individual craftsman is a skilled person who makes things by hand.","zh":"Individual craftsman 是指用手工製作物件的熟練人士。"},{"en":"A carpenter making one chair carefully is an individual craftsman.","zh":"一位細心製作一張椅子的木匠，就是個別工匠。"},{"en":"Mass production can reduce the role of the individual craftsman by replacing hand skill with machines.","zh":"大規模生產可以用機器取代手藝，從而降低個別工匠的角色。"},{"en":"The phrase emphasises personal skill and human making.","zh":"這個片語強調個人技巧和人的製作。"}],"source":"153 - British Architecture.pdf","sourcePage":12},{"front":"no longer had a major role in","meaning":"不再在……中擔當重要角色","examples":[{"en":"Craftsmen no longer had a major role in production.","zh":"工匠不再在生產中擔當重要角色。"},{"en":"No longer had a major role in means they used to be important, but are not important now.","zh":"No longer had a major role in 指他們過去重要，但現在不再重要。"},{"en":"Handwriting no longer has a major role in many offices because most documents are typed.","zh":"因為大多數文件都是打字，手寫不再在許多辦公室中擔當重要角色。"},{"en":"When machines take over, skilled workers may no longer have a major role in some tasks.","zh":"當機器接管，熟練工人在某些任務中可能不再擔當重要角色。"},{"en":"The phrase shows loss of importance over time.","zh":"這個片語顯示重要性隨時間下降。"}],"source":"153 - British Architecture.pdf","sourcePage":12},{"front":"railing against","meaning":"強烈反對","examples":[{"en":"Ruskin and Morris were railing against the dehumanising effects of industrialisation.","zh":"Ruskin和Morris強烈反對工業化的非人性化影響。"},{"en":"To rail against something means to criticise it strongly and angrily.","zh":"To rail against something 指強烈而憤怒地批評某事。"},{"en":"Residents may rail against a plan to remove their local park.","zh":"居民可能強烈反對移除本地公園的計劃。"},{"en":"Reformers rail against unfair systems when they believe ordinary people are being harmed.","zh":"當改革者認為普通人受到傷害，他們會強烈反對不公平制度。"},{"en":"The phrase is stronger than simply “disagree with”.","zh":"這個片語比單純 “disagree with” 更強烈。"}],"source":"153 - British Architecture.pdf","sourcePage":12},{"front":"dehumanising effects","meaning":"非人性化影響","examples":[{"en":"Reformers criticised the dehumanising effects of industrialisation.","zh":"改革者批評工業化的非人性化影響。"},{"en":"Dehumanising effects are results that make people feel less human, skilled, valued, or free.","zh":"Dehumanising effects 是令，人感到較不像人、較無技能、價值或自由的結果。"},{"en":"A workplace can have dehumanising effects if workers are treated like machines.","zh":"如果工人被當成機器對待，工作場所便可能有非人性化影響。"},{"en":"Mass production may have dehumanising effects when it removes creativity from work.","zh":"當大規模生產從工作中移除創造力時，可能產生非人性化影響。"},{"en":"The phrase focuses on damage to human dignity.","zh":"這個片語著重對人類尊嚴的傷害。"}],"source":"153 - British Architecture.pdf","sourcePage":12},{"front":"industrialisation","meaning":"工業化","examples":[{"en":"Industrialisation changed how buildings and furnishings were made.","zh":"工業化改變了建築和家具的製作方式。"},{"en":"Industrialisation is the process by which factories, machines, and mass production become central to an economy.","zh":"Industrialisation 是工廠、機器和大規模生產成為經濟核心的過程。"},{"en":"Industrialisation can create jobs and cheaper goods, but it can also damage craft traditions.","zh":"工業化可以創造工作和廉價商品，但也可能損害手工傳統。"},{"en":"Cities often grow quickly during industrialisation because workers move near factories.","zh":"工業化期間，城市常迅速增長，因為工人搬到工廠附近。"},{"en":"The phrase describes a major social and economic transformation.","zh":"這個片語描述重大的社會和經濟轉變。"}],"source":"153 - British Architecture.pdf","sourcePage":12},{"front":"reformers","meaning":"改革者","examples":[{"en":"Reformers such as John Ruskin and William Morris promoted hand-crafted production.","zh":"John Ruskin和William Morris等改革者推動手工製作。"},{"en":"Reformers are people who try to improve society, systems, or practices.","zh":"Reformers 是試圖改善社會、制度或做法的人。"},{"en":"Education reformers may call for fairer exams and better support for weak students.","zh":"教育改革者可能呼籲更公平的考試和更好支援弱勢學生。"},{"en":"Reformers often criticise existing problems and propose better alternatives.","zh":"改革者常批評現有問題並提出更好替代方案。"},{"en":"The phrase suggests people who want change, not simply people who complain.","zh":"這個詞暗示想帶來改變的人，而不只是抱怨的人。"}],"source":"153 - British Architecture.pdf","sourcePage":13},{"front":"made a concerted effort to","meaning":"齊心協力去","examples":[{"en":"Reformers made a concerted effort to return to pre-industrial techniques.","zh":"改革者齊心協力去回歸工業化前的技術。"},{"en":"To make a concerted effort means to work hard in an organised and serious way.","zh":"To make a concerted effort 指以有組織而認真的方式努力。"},{"en":"A school may make a concerted effort to improve reading by training teachers and buying books.","zh":"學校可能透過培訓老師和購買書籍，齊心協力去改善閱讀。"},{"en":"A community can make a concerted effort to reduce waste through recycling and education.","zh":"社區可以透過回收和教育，齊心協力去減少廢物。"},{"en":"The phrase suggests planned teamwork, not a casual attempt.","zh":"這個片語暗示有計劃的共同努力，而不是隨便嘗試。"}],"source":"153 - British Architecture.pdf","sourcePage":13},{"front":"hand-crafted","meaning":"手工製作的","examples":[{"en":"Morris valued hand-crafted furniture and textiles.","zh":"Morris重視手工製作的家具和紡織品。"},{"en":"Hand-crafted means made carefully by hand rather than mainly by machine.","zh":"Hand-crafted 指主要由人手仔細製作，而不是主要由機器製作。"},{"en":"A hand-crafted wooden table may have small differences that show human work.","zh":"手工製作的木桌可能有小差異，顯示人的工作。"},{"en":"Hand-crafted goods often cost more because they take more time and skill.","zh":"手工製作的商品通常較貴，因為它們需要更多時間和技巧。"},{"en":"The phrase suggests individuality, care, and traditional skill.","zh":"這個片語暗示個性、用心和傳統技藝。"}],"source":"153 - British Architecture.pdf","sourcePage":13},{"front":"pre-industrial manufacturing techniques","meaning":"工業化前的製造技術","examples":[{"en":"William Morris supported pre-industrial manufacturing techniques.","zh":"William Morris支持工業化前的製造技術。"},{"en":"Pre-industrial manufacturing techniques are ways of making goods used before factories and mass production became dominant.","zh":"Pre-industrial manufacturing techniques 是工廠和大規模生產成為主導前製造商品的方法。"},{"en":"Hand weaving and traditional carpentry can be pre-industrial manufacturing techniques.","zh":"手工織布和傳統木工可以是工業化前的製造技術。"},{"en":"These techniques may preserve craft skill but usually produce goods more slowly.","zh":"這些技術可以保存工藝技能，但通常生產速度較慢。"},{"en":"The phrase contrasts older hand-based methods with modern industrial production.","zh":"這個片語把較舊的手工方法與現代工業生產作對比。"}],"source":"153 - British Architecture.pdf","sourcePage":13},{"front":"Morris’s influence grew from","meaning":"Morris 的影響力由……擴展","examples":[{"en":"Morris’s influence grew from the production of furniture and textiles.","zh":"Morris的影響力由家具和紡織品製作擴展。"},{"en":"Someone’s influence grew from something means their impact began in that area and then expanded.","zh":"Someone’s influence grew from something 指某人的影響力從某個領域開始，然後擴大。"},{"en":"A teacher’s influence may grow from one popular course to a whole school programme.","zh":"老師的影響力可能由一門受歡迎課程擴展到整個學校計劃。"},{"en":"Morris’s ideas spread because people connected his products with a larger design philosophy.","zh":"Morris的想法得以傳播，因為人們把他的產品與更大的設計理念連繫起來。"},{"en":"The phrase explains the starting point of wider influence.","zh":"這個片語解釋更廣泛影響力的起點。"}],"source":"153 - British Architecture.pdf","sourcePage":13},{"front":"furniture and textiles","meaning":"家具和紡織品","examples":[{"en":"Morris’s work influenced furniture and textiles.","zh":"Morris的作品影響了家具和紡織品。"},{"en":"Furniture and textiles means movable household objects and woven or cloth materials.","zh":"Furniture and textiles 指可移動的家居物件，以及織物或布料。"},{"en":"Chairs, tables, curtains, carpets, and fabric patterns belong to furniture and textiles.","zh":"椅子、桌子、窗簾、地毯和布料圖案都屬於家具和紡織品。"},{"en":"Good design in furniture and textiles can change the feeling of a whole room.","zh":"家具和紡織品中的良好設計可以改變整個房間的感覺。"},{"en":"The phrase links interior design with everyday use.","zh":"這個片語把室內設計與日常使用連接起來。"}],"source":"153 - British Architecture.pdf","sourcePage":13},{"front":"a generation of","meaning":"一代……","examples":[{"en":"A generation of young architects followed Morris’s ideas.","zh":"一代年輕建築師追隨Morris的想法。"},{"en":"A generation of people means people born or active around the same period.","zh":"A generation of people 指在大約同一時期出生或活躍的人。"},{"en":"A generation of students grew up using smartphones in school and at home.","zh":"一代學生在學校和家中使用智能手機長大。"},{"en":"One thinker can influence a generation of young professionals.","zh":"一位思想家可以影響一代年輕專業人士。"},{"en":"The phrase shows that an idea affected many people of a similar age or period.","zh":"這個片語顯示一個想法影響了相近年齡或時期的許多人。"}],"source":"153 - British Architecture.pdf","sourcePage":13},{"front":"principled young architects","meaning":"有原則的年輕建築師","examples":[{"en":"Principled young architects followed Morris’s call for honest construction.","zh":"有原則的年輕建築師響應Morris對真誠建造方式的呼籲。"},{"en":"Principled young architects are young designers guided by strong moral or professional beliefs.","zh":"Principled young architects 是受強烈道德或專業信念引導的年輕設計師。"},{"en":"A principled architect may refuse to use cheap unsafe materials.","zh":"有原則的建築師可能拒絕使用廉價而不安全的材料。"},{"en":"Young architects with principles may care about honesty, craft, workers, and users.","zh":"有原則的年輕建築師可能重視誠實、工藝、工人和使用者。"},{"en":"The phrase praises architects for values, not only talent.","zh":"這個片語讚揚建築師的價值觀，而不只是才華。"}],"source":"153 - British Architecture.pdf","sourcePage":13},{"front":"following his call for","meaning":"響應他對……的呼籲","examples":[{"en":"Young architects were following his call for good, honest construction.","zh":"年輕建築師響應他對優良而真誠建造方式的呼籲。"},{"en":"Following someone’s call for something means responding to their request or ideal.","zh":"Following someone’s call for something 指回應某人的要求或理想。"},{"en":"Students following a teacher’s call for daily reading may improve gradually.","zh":"響應老師每日閱讀呼籲的學生可能逐步進步。"},{"en":"Citizens may follow a leader’s call for cleaner streets by joining community clean-ups.","zh":"市民可能響應領袖清潔街道的呼籲，參與社區清潔。"},{"en":"The phrase shows people acting because someone urged them to.","zh":"這個片語顯示人們因某人呼籲而行動。"}],"source":"153 - British Architecture.pdf","sourcePage":13},{"front":"good, honest construction","meaning":"優良而真誠的建造方式","examples":[{"en":"William Morris called for good, honest construction.","zh":"William Morris呼籲優良而真誠的建造方式。"},{"en":"Good, honest construction means building carefully with suitable materials and clear, truthful design.","zh":"Good, honest construction 指用合適材料和清晰真實設計仔細建造。"},{"en":"A chair shows honest construction when its joints and materials are visible and strong.","zh":"當椅子的接合位和材料清晰可見且堅固，它便展示真誠建造方式。"},{"en":"Honest construction avoids fake surfaces that pretend to be more expensive than they are.","zh":"真誠建造方式避免使用假表面假裝更昂貴。"},{"en":"The phrase values craft, truthfulness, and real usefulness.","zh":"這個片語重視工藝、真實和真正實用。"}],"source":"153 - British Architecture.pdf","sourcePage":13},{"front":"the most important trends","meaning":"最重要的趨勢","examples":[{"en":"The most important trends in early twentieth-century architecture passed Britain by.","zh":"二十世紀初建築中最重要的趨勢與英國擦身而過。"},{"en":"The most important trends are the major directions that shape a field during a period.","zh":"The most important trends 指在某一時期塑造某領域的主要方向。"},{"en":"In education, online learning and personalised feedback are important trends.","zh":"在教育中，網上學習和個人化回饋是重要趨勢。"},{"en":"If a country ignores the most important trends, it may fall behind.","zh":"如果一個國家忽視最重要的趨勢，它可能落後。"},{"en":"The phrase focuses on changes that matter most, not every small fashion.","zh":"這個片語著重最重要的變化，而不是每一個小潮流。"}],"source":"153 - British Architecture.pdf","sourcePage":13},{"front":"early twentieth-century architecture","meaning":"二十世紀初建築","examples":[{"en":"Early twentieth-century architecture changed rapidly in Europe.","zh":"二十世紀初建築在歐洲迅速改變。"},{"en":"Early twentieth-century architecture refers to buildings and design ideas from the early 1900s.","zh":"Early twentieth-century architecture 指1900年代初的建築物和設計理念。"},{"en":"It often involved new materials, simpler forms, and new ideas about modern life.","zh":"它常涉及新材料、更簡潔形式和關於現代生活的新想法。"},{"en":"Rapid social and technological change pushed architects to rethink old styles.","zh":"快速的社會和科技變化促使建築師重新思考舊風格。"},{"en":"The phrase is strongly linked with modernism and experimentation.","zh":"這個片語與現代主義和實驗密切相關。"}],"source":"153 - British Architecture.pdf","sourcePage":14},{"front":"passed Britain by","meaning":"與英國擦身而過；沒有影響英國","examples":[{"en":"The most important architectural trends simply passed Britain by.","zh":"最重要的建築趨勢簡直與英國擦身而過。"},{"en":"If something passes a place or person by, they fail to join, notice, or benefit from it.","zh":"If something passes a place or person by 指某地或某人未能參與、注意或受益於它。"},{"en":"Some workers felt that the digital economy passed them by.","zh":"有些工人覺得數碼經濟與他們擦身而過。"},{"en":"A school may fall behind if new teaching methods pass it by.","zh":"如果新教學方法沒有影響一所學校，它可能落後。"},{"en":"The phrase suggests missed opportunity.","zh":"這個片語暗示錯失機會。"}],"source":"153 - British Architecture.pdf","sourcePage":14},{"front":"whilst","meaning":"然而；同時","examples":[{"en":"Whilst European architects experimented with new materials, Britain remained conservative.","zh":"然而，當歐洲建築師試驗新材料時，英國仍保持保守。"},{"en":"Whilst means while, and it often introduces contrast between two situations.","zh":"Whilst 意思是 while，常用來引出兩種情況的對比。"},{"en":"Whilst some students prefer group work, others learn better alone.","zh":"有些學生喜歡小組工作，然而其他人獨自學習更好。"},{"en":"Whilst the city centre became modern, many villages kept older building styles.","zh":"當市中心變得現代時，許多村莊仍保留較舊建築風格。"},{"en":"The word is more formal and British than “while”.","zh":"這個詞比 “while” 更正式，也更英式。"}],"source":"153 - British Architecture.pdf","sourcePage":14},{"front":"cold, hard expanses of glass","meaning":"冷峻堅硬的大面積玻璃","examples":[{"en":"Gropius worked on cold, hard expanses of glass.","zh":"Gropius處理冷峻堅硬的大面積玻璃。"},{"en":"Cold, hard expanses of glass are large glass surfaces that feel severe, modern, and unemotional.","zh":"Cold, hard expanses of glass 指感覺嚴厲、現代而缺乏情感的大型玻璃表面。"},{"en":"A modern office block may have cold, hard expanses of glass across its front.","zh":"現代辦公大樓正面可能有冷峻堅硬的大面積玻璃。"},{"en":"Such surfaces can look efficient but may feel unfriendly to some people.","zh":"這類表面可以顯得高效，但對某些人而言可能不友善。"},{"en":"The phrase describes both material appearance and emotional impression.","zh":"這個片語同時描述材料外觀和情感印象。"}],"source":"153 - British Architecture.pdf","sourcePage":14},{"front":"reinforced concrete frames","meaning":"鋼筋混凝土框架","examples":[{"en":"Le Corbusier experimented with reinforced concrete frames.","zh":"Le Corbusier試驗鋼筋混凝土框架。"},{"en":"Reinforced concrete frames are structural systems made of concrete strengthened with steel.","zh":"Reinforced concrete frames 是由鋼筋強化混凝土製成的結構系統。"},{"en":"Many modern apartment blocks use reinforced concrete frames because they are strong.","zh":"許多現代公寓大樓使用鋼筋混凝土框架，因為它們很堅固。"},{"en":"Reinforced concrete allowed architects to create open plans and new building shapes.","zh":"鋼筋混凝土讓建築師可以創造開放平面和新的建築形狀。"},{"en":"The phrase refers to a modern construction method, not surface decoration.","zh":"這個片語指現代建造方法，而不是表面裝飾。"}],"source":"153 - British Architecture.pdf","sourcePage":14},{"front":"staid establishment architects","meaning":"古板的建制派建築師","examples":[{"en":"Britain had staid establishment architects such as Edwin Lutyens.","zh":"英國有像Edwin Lutyens這樣古板的建制派建築師。"},{"en":"Staid establishment architects are respectable but conservative architects linked with traditional authority.","zh":"Staid establishment architects 是受尊重但保守、與傳統權威相關的建築師。"},{"en":"Such architects may design safe, familiar buildings for wealthy clients.","zh":"這類建築師可能為富裕客戶設計安全而熟悉的建築。"},{"en":"When an architectural world is dominated by staid establishment figures, new ideas may struggle.","zh":"當建築界由古板建制派人物主導，新想法可能難以發展。"},{"en":"The phrase is mildly critical and suggests lack of experimentation.","zh":"這個片語帶輕微批評，暗示缺乏實驗精神。"}],"source":"153 - British Architecture.pdf","sourcePage":14},{"front":"Edwin Lutyens","meaning":"埃德溫・魯琴斯","examples":[{"en":"Edwin Lutyens designed conservative country houses.","zh":"埃德溫・魯琴斯設計保守風格的鄉村大宅。"},{"en":"Edwin Lutyens was a British architect associated with traditional and formal design.","zh":"Edwin Lutyens 是一位與傳統和正式設計相關的英國建築師。"},{"en":"In this context, he represents architects who did not fully embrace European modernism.","zh":"在這個語境中，他代表未完全接受歐洲現代主義的建築師。"},{"en":"A famous architect can become a symbol of a wider style or attitude.","zh":"著名建築師可以成為更廣泛風格或態度的象徵。"},{"en":"The name is used to show Britain’s architectural conservatism at the time.","zh":"這個名字用來顯示當時英國建築的保守性。"}],"source":"153 - British Architecture.pdf","sourcePage":14},{"front":"Neo-Georgian","meaning":"新喬治亞風格","examples":[{"en":"Some British architects produced Neo-Georgian country houses.","zh":"一些英國建築師創作新喬治亞風格鄉村大宅。"},{"en":"Neo-Georgian is a style that revives or imitates Georgian architectural features.","zh":"Neo-Georgian 是復興或模仿喬治亞建築特色的風格。"},{"en":"A Neo-Georgian house may have symmetry, brick walls, sash windows, and classical details.","zh":"新喬治亞風格房屋可能有對稱、磚牆、上下推拉窗和古典細節。"},{"en":"People choose Neo-Georgian design when they want a traditional and respectable appearance.","zh":"當人們想要傳統而體面的外觀時，可能選擇新喬治亞風格設計。"},{"en":"The phrase means “new Georgian”, not original Georgian from the eighteenth century.","zh":"這個片語意思是「新的喬治亞風格」，不是十八世紀原本的喬治亞風格。"}],"source":"153 - British Architecture.pdf","sourcePage":14},{"front":"Renaissance country houses","meaning":"文藝復興風格鄉村大宅","examples":[{"en":"Some architects produced Renaissance country houses for landowners.","zh":"一些建築師為地主設計文藝復興風格鄉村大宅。"},{"en":"Renaissance country houses are large rural homes inspired by Renaissance architectural ideas.","zh":"Renaissance country houses 是受文藝復興建築理念啟發的大型鄉村住宅。"},{"en":"They may use classical symmetry, proportion, columns, and formal layouts.","zh":"它們可能使用古典對稱、比例、柱子和正式佈局。"},{"en":"Landowners used such houses to show learning, taste, and social rank.","zh":"地主利用這類房屋展示學養、品味和社會地位。"},{"en":"The phrase connects rural wealth with historical European style.","zh":"這個片語把鄉村財富與歐洲歷史風格連接起來。"}],"source":"153 - British Architecture.pdf","sourcePage":14},{"front":"outmoded landed class","meaning":"過時的地主階級","examples":[{"en":"Conservative houses were built for an outmoded landed class.","zh":"保守風格房屋是為過時的地主階級而建。"},{"en":"An outmoded landed class is a landowning social group whose power or values seem old-fashioned.","zh":"Outmoded landed class 指擁有土地但權力或價值觀顯得過時的社會階層。"},{"en":"A landed class may lose influence when industry, cities, and corporations become more powerful.","zh":"當工業、城市和公司變得更有力量，地主階級可能失去影響力。"},{"en":"Buildings for an outmoded class can look elegant but socially outdated.","zh":"為過時階級而建的建築可能優雅，但在社會上已過時。"},{"en":"The phrase is critical and suggests a class belonging to the past.","zh":"這個片語帶批評意味，暗示該階級屬於過去。"}],"source":"153 - British Architecture.pdf","sourcePage":14},{"front":"slightly batty","meaning":"有點古怪的","examples":[{"en":"Some architect-craftsmen were described as slightly batty.","zh":"一些建築師兼工匠被形容為有點古怪。"},{"en":"Slightly batty means a little eccentric, strange, or odd in behaviour or ideas.","zh":"Slightly batty 指行為或想法有點古怪、奇特或不尋常。"},{"en":"A teacher who keeps old maps on every wall may seem slightly batty but interesting.","zh":"一位在每面牆都掛舊地圖的老師可能顯得有點古怪但有趣。"},{"en":"People may call reformers slightly batty when their ideas seem impractical or old-fashioned.","zh":"當改革者的想法顯得不實際或過時，人們可能說他們有點古怪。"},{"en":"The phrase is informal and mildly humorous.","zh":"這個片語較口語，並帶有輕微幽默感。"}],"source":"153 - British Architecture.pdf","sourcePage":14},{"front":"architect-craftsmen","meaning":"建築師兼工匠","examples":[{"en":"Some architect-craftsmen tried to revive pre-industrial methods.","zh":"一些建築師兼工匠試圖復興工業化前的方法。"},{"en":"Architect-craftsmen are designers who also value or practise hands-on craft skills.","zh":"Architect-craftsmen 是既設計建築，又重視或實踐手工技藝的人。"},{"en":"An architect-craftsman may design a house and personally understand how its woodwork is made.","zh":"建築師兼工匠可能設計房屋，並親自理解其木工如何製作。"},{"en":"Such people often care about materials, workmanship, and honest construction.","zh":"這類人常重視材料、工藝和真誠建造方式。"},{"en":"The phrase combines intellectual design with manual skill.","zh":"這個片語結合智性設計與手工技能。"}],"source":"153 - British Architecture.pdf","sourcePage":15},{"front":"heirs of William Morris","meaning":"William Morris 的繼承者","examples":[{"en":"These architect-craftsmen were heirs of William Morris.","zh":"這些建築師兼工匠是William Morris的繼承者。"},{"en":"Heirs of William Morris means people who continued Morris’s ideas, not necessarily his family.","zh":"Heirs of William Morris 指延續Morris想法的人，不一定是他的家人。"},{"en":"A modern designer who values hand craft may be an heir of Morris’s thinking.","zh":"重視手工藝的現代設計師可能是Morris思想的繼承者。"},{"en":"Intellectual heirs keep an earlier person’s values alive in new work.","zh":"思想上的繼承者在新作品中延續早前人物的價值觀。"},{"en":"The phrase refers to inheritance of ideas rather than money or property.","zh":"這個片語指思想繼承，而不是金錢或財產繼承。"}],"source":"153 - British Architecture.pdf","sourcePage":15},{"front":"turn the clock back","meaning":"讓時光倒流","examples":[{"en":"Some architects tried to turn the clock back to before the Industrial Revolution.","zh":"一些建築師試圖讓時光倒流，回到工業革命之前。"},{"en":"To turn the clock back means to return to an earlier time or older way of doing things.","zh":"To turn the clock back 指回到較早的時代或較舊的做事方式。"},{"en":"A shop that refuses online payment may seem to turn the clock back.","zh":"一間拒絕網上支付的商店可能顯得像在讓時光倒流。"},{"en":"People sometimes want to turn the clock back when modern life feels too fast.","zh":"當現代生活感覺太快，人們有時想讓時光倒流。"},{"en":"The phrase often suggests nostalgia and resistance to change.","zh":"這個片語常暗示懷舊和抗拒改變。"}],"source":"153 - British Architecture.pdf","sourcePage":15},{"front":"the Industrial Revolution","meaning":"工業革命","examples":[{"en":"Some craftsmen wanted to return to a time before the Industrial Revolution.","zh":"一些工匠想回到工業革命之前的時代。"},{"en":"The Industrial Revolution was the period when machines, factories, and industrial production transformed society.","zh":"工業革命是機器、工廠和工業生產改造社會的時期。"},{"en":"The Industrial Revolution changed work, cities, transport, manufacturing, and architecture.","zh":"工業革命改變了工作、城市、交通、製造和建築。"},{"en":"Some people admired its progress, while others feared its effect on craft and human life.","zh":"有些人欣賞其進步，另一些人則害怕它對工藝和人類生活的影響。"},{"en":"The phrase marks a major break between pre-industrial and modern society.","zh":"這個片語標誌工業化前社會與現代社會之間的重大斷裂。"}],"source":"153 - British Architecture.pdf","sourcePage":15},{"front":"spurning new technology","meaning":"拒絕新科技","examples":[{"en":"Some architects were still spurning new technology.","zh":"一些建築師仍在拒絕新科技。"},{"en":"To spurn new technology means to reject or refuse modern tools, methods, or machines.","zh":"To spurn new technology 指拒絕使用現代工具、方法或機器。"},{"en":"A teacher spurns new technology if they refuse to use any digital materials.","zh":"如果老師拒絕使用任何數碼材料，就是拒絕新科技。"},{"en":"Spurning technology can preserve tradition, but it may also limit improvement.","zh":"拒絕科技可以保存傳統，但也可能限制改善。"},{"en":"The phrase suggests deliberate rejection, not simple unfamiliarity.","zh":"這個片語暗示有意識的拒絕，而不是單純不熟悉。"}],"source":"153 - British Architecture.pdf","sourcePage":15},{"front":"only a handful of","meaning":"只有少數","examples":[{"en":"Only a handful of Modern Movement buildings were produced in Britain.","zh":"英國只產生了少數現代主義運動建築。"},{"en":"Only a handful of something means only a very small number of it.","zh":"Only a handful of something 指只有非常少量。"},{"en":"Only a handful of students stayed after class to ask questions.","zh":"只有少數學生課後留下來問問題。"},{"en":"If only a handful of buildings use a style, that style has not spread widely.","zh":"如果只有少數建築使用某風格，該風格尚未廣泛傳播。"},{"en":"The phrase emphasises scarcity.","zh":"這個片語強調稀少。"}],"source":"153 - British Architecture.pdf","sourcePage":15},{"front":"Modern Movement buildings","meaning":"現代主義運動建築","examples":[{"en":"Few Modern Movement buildings of real merit were built in Britain.","zh":"英國建成的真正有價值的現代主義運動建築很少。"},{"en":"Modern Movement buildings are buildings linked with modernist ideas such as simplicity, new materials, and functional design.","zh":"Modern Movement buildings 是與簡潔、新材料和功能設計等現代主義理念相關的建築。"},{"en":"A Modern Movement building may use flat roofs, open plans, glass, and concrete.","zh":"現代主義運動建築可能使用平屋頂、開放平面、玻璃和混凝土。"},{"en":"These buildings often rejected historical decoration and focused on modern life.","zh":"這些建築常拒絕歷史裝飾，集中於現代生活。"},{"en":"The phrase refers to a major twentieth-century architectural movement.","zh":"這個片語指二十世紀重要建築運動。"}],"source":"153 - British Architecture.pdf","sourcePage":15},{"front":"of any real merit","meaning":"真正有價值的","examples":[{"en":"Only a few Modern Movement buildings of any real merit appeared in Britain.","zh":"英國只出現了少數真正有價值的現代主義運動建築。"},{"en":"Of any real merit means having genuine value, quality, or importance.","zh":"Of any real merit 指具有真正價值、質素或重要性。"},{"en":"A report of real merit gives evidence, clear reasoning, and useful conclusions.","zh":"真正有價值的報告會提供證據、清晰推理和有用結論。"},{"en":"A building may be new without being of any real merit.","zh":"一座建築可以很新，但不一定真正有價值。"},{"en":"The phrase is evaluative and separates quality from mere existence.","zh":"這個片語帶評價意味，把質素與單純存在區分開來。"}],"source":"153 - British Architecture.pdf","sourcePage":15},{"front":"foreign architects","meaning":"外國建築師","examples":[{"en":"Many significant Modern Movement buildings were designed by foreign architects.","zh":"許多重要的現代主義運動建築由外國建築師設計。"},{"en":"Foreign architects are architects from countries other than the one being discussed.","zh":"Foreign architects 是來自所討論國家以外地方的建築師。"},{"en":"A city may invite foreign architects to bring new ideas and international experience.","zh":"城市可能邀請外國建築師帶來新想法和國際經驗。"},{"en":"Foreign architects can influence local styles when local designers are more conservative.","zh":"當本地設計師較保守，外國建築師可以影響本地風格。"},{"en":"The phrase focuses on origin, not quality.","zh":"這個片語著重來源，而不是質素。"}],"source":"153 - British Architecture.pdf","sourcePage":15},{"front":"settled in this country","meaning":"在這個國家定居","examples":[{"en":"Some foreign architects settled in Britain.","zh":"一些外國建築師在英國定居。"},{"en":"To settle in this country means to move there and live there for a long period.","zh":"To settle in this country 指搬到該國並長期居住。"},{"en":"A doctor who settles in another country may learn its language and professional rules.","zh":"在另一個國家定居的醫生可能學習當地語言和專業規則。"},{"en":"Architects who settle in a country can influence its building culture over time.","zh":"在某國定居的建築師可以隨時間影響其建築文化。"},{"en":"The phrase suggests more permanence than a short visit.","zh":"這個片語暗示比短暫訪問更持久。"}],"source":"153 - British Architecture.pdf","sourcePage":15},{"front":"after the Second World War","meaning":"第二次世界大戰後","examples":[{"en":"After the Second World War, the situation began to change.","zh":"第二次世界大戰後，情況開始改變。"},{"en":"After the Second World War means in the period following the war that ended in 1945.","zh":"After the Second World War 指1945年戰爭結束後的時期。"},{"en":"Many European cities needed rebuilding after the Second World War.","zh":"第二次世界大戰後，許多歐洲城市需要重建。"},{"en":"Housing demand became urgent after the Second World War because many buildings were damaged.","zh":"第二次世界大戰後，由於許多建築受損，住房需求變得迫切。"},{"en":"The phrase marks a major turning point in modern history.","zh":"這個片語標誌現代歷史中的重大轉折。"}],"source":"153 - British Architecture.pdf","sourcePage":15},{"front":"the situation began to change","meaning":"情況開始改變","examples":[{"en":"British architecture began to change after the war.","zh":"戰後英國建築開始改變。"},{"en":"The situation began to change means earlier conditions started becoming different.","zh":"The situation began to change 指早前情況開始變得不同。"},{"en":"The situation began to change when more students gained access to online lessons.","zh":"當更多學生能接觸網上課堂，情況開始改變。"},{"en":"In architecture, war damage and housing needs can make the situation change quickly.","zh":"在建築方面，戰爭破壞和住房需求可以令情況迅速改變。"},{"en":"The phrase signals the start of a new direction.","zh":"這個片語標誌新方向的開始。"}],"source":"153 - British Architecture.pdf","sourcePage":16},{"front":"belief in progress and the future","meaning":"對進步和未來的信念","examples":[{"en":"The Modern Movement’s belief in progress and the future appealed to post-war Britain.","zh":"現代主義運動對進步和未來的信念吸引了戰後英國。"},{"en":"Belief in progress and the future means confidence that society can improve and move forward.","zh":"Belief in progress and the future 指相信社會可以改善並向前發展。"},{"en":"After a crisis, people may need belief in progress and the future to rebuild.","zh":"危機之後，人們可能需要對進步和未來的信念來重建。"},{"en":"Modernist architecture expressed this belief through new materials and functional design.","zh":"現代主義建築透過新材料和功能設計表達這種信念。"},{"en":"The phrase is hopeful and forward-looking.","zh":"這個片語充滿希望並面向未來。"}],"source":"153 - British Architecture.pdf","sourcePage":16},{"front":"struck a chord with","meaning":"引起……共鳴","examples":[{"en":"Modernist ideas struck a chord with the mood of post-war Britain.","zh":"現代主義想法引起戰後英國氣氛的共鳴。"},{"en":"To strike a chord with people means to connect emotionally with their feelings or experience.","zh":"To strike a chord with people 指與人們的感受或經驗產生情感連結。"},{"en":"A speech about hard work may strike a chord with students preparing for exams.","zh":"關於努力的演講可能引起備考學生的共鳴。"},{"en":"Modernism struck a chord after the war because people wanted rebuilding and hope.","zh":"戰後現代主義引起共鳴，因為人們想要重建和希望。"},{"en":"The phrase suggests that an idea feels right to a particular audience.","zh":"這個片語暗示某想法對特定聽眾而言感覺合適。"}],"source":"153 - British Architecture.pdf","sourcePage":16},{"front":"the mood of post-war Britain","meaning":"戰後英國的氣氛","examples":[{"en":"The Modern Movement suited the mood of post-war Britain.","zh":"現代主義運動符合戰後英國的氣氛。"},{"en":"The mood of post-war Britain means the general feelings and attitudes in Britain after the war.","zh":"The mood of post-war Britain 指戰後英國的普遍感受和態度。"},{"en":"This mood included hardship, hope, rebuilding, and a desire for practical solutions.","zh":"這種氣氛包括困難、希望、重建和對實際方案的渴望。"},{"en":"Architecture can match a national mood when it answers people’s urgent needs.","zh":"當建築回應人們迫切需要時，它可以配合國家氣氛。"},{"en":"The phrase links buildings with public feeling after a major historical event.","zh":"這個片語把建築與重大歷史事件後的公共感受連接起來。"}],"source":"153 - British Architecture.pdf","sourcePage":16},{"front":"reconstruction began","meaning":"重建開始","examples":[{"en":"Reconstruction began under Attlee’s Labour government in 1945.","zh":"重建在1945年艾德禮工黨政府下開始。"},{"en":"Reconstruction began means rebuilding started after damage, loss, or major disruption.","zh":"Reconstruction began 指在破壞、損失或重大中斷後重建工作開始。"},{"en":"Reconstruction began after the storm when workers repaired roads and homes.","zh":"風暴後，工人修復道路和房屋，重建開始。"},{"en":"War reconstruction often includes housing, schools, hospitals, and city centres.","zh":"戰後重建常包括住房、學校、醫院和市中心。"},{"en":"The phrase marks the start of organised rebuilding.","zh":"這個片語標誌有組織重建的開始。"}],"source":"153 - British Architecture.pdf","sourcePage":16},{"front":"Attlee’s Labour government","meaning":"艾德禮工黨政府","examples":[{"en":"Reconstruction began under Attlee’s Labour government.","zh":"重建在艾德禮工黨政府下開始。"},{"en":"Attlee’s Labour government refers to the British government led by Clement Attlee after the Second World War.","zh":"Attlee’s Labour government 指第二次世界大戰後由Clement Attlee領導的英國政府。"},{"en":"Such a government is associated in this context with rebuilding and public provision.","zh":"在這個語境中，這個政府與重建和公共供應相關。"},{"en":"Government policy can strongly affect what kinds of housing and public buildings are built.","zh":"政府政策可以強烈影響建造甚麼住房和公共建築。"},{"en":"The phrase places architectural change in a political context.","zh":"這個片語把建築變化放在政治背景中。"}],"source":"153 - British Architecture.pdf","sourcePage":16},{"front":"a desperate need for","meaning":"對……有迫切需要","examples":[{"en":"There was a desperate need for cheap housing after the war.","zh":"戰後人們對廉價房屋有迫切需要。"},{"en":"A desperate need for something is an extremely urgent and serious need.","zh":"A desperate need for something 指極其迫切而嚴重的需要。"},{"en":"After a flood, families may have a desperate need for clean water and safe shelter.","zh":"水災後，家庭可能迫切需要清潔食水和安全住所。"},{"en":"A desperate need can push governments to act quickly rather than perfectly.","zh":"迫切需要可以促使政府快速行動，而不是追求完美。"},{"en":"The phrase shows that the problem cannot wait.","zh":"這個片語顯示問題不能等待。"}],"source":"153 - British Architecture.pdf","sourcePage":16},{"front":"cheap housing","meaning":"廉價房屋","examples":[{"en":"Post-war Britain needed cheap housing that could be built quickly.","zh":"戰後英國需要可以迅速建成的廉價房屋。"},{"en":"Cheap housing means homes that ordinary or low-income people can afford.","zh":"Cheap housing 指普通人或低收入人士負擔得起的住宅。"},{"en":"A city with high rent may need cheap housing for young workers and families.","zh":"租金高昂的城市可能需要廉價房屋給年輕工人和家庭。"},{"en":"Cheap housing can reduce homelessness, but it must still be safe and decent.","zh":"廉價房屋可以減少無家可歸，但仍必須安全和合宜。"},{"en":"The phrase focuses on affordability, not poor quality.","zh":"這個片語著重可負擔性，而不是低質素。"}],"source":"153 - British Architecture.pdf","sourcePage":16},{"front":"produced quickly","meaning":"迅速建成","examples":[{"en":"New housing had to be produced quickly.","zh":"新房屋必須迅速建成。"},{"en":"Produced quickly means made or built in a short time.","zh":"Produced quickly 指在短時間內製造或建成。"},{"en":"Emergency shelters must be produced quickly after a major earthquake.","zh":"大地震後，緊急住所必須迅速建成。"},{"en":"When demand is urgent, speed may become more important than decoration.","zh":"當需求迫切，速度可能比裝飾更重要。"},{"en":"The phrase explains why simple or prefabricated methods may be chosen.","zh":"這個片語解釋為何可能選擇簡單或預製方法。"}],"source":"153 - British Architecture.pdf","sourcePage":16},{"front":"prefabricated elements","meaning":"預製構件","examples":[{"en":"Prefabricated elements were adopted for post-war housing.","zh":"預製構件被採用於戰後住房。"},{"en":"Prefabricated elements are building parts made in advance, often in a factory, before being assembled on site.","zh":"Prefabricated elements 是預先製成、通常在工廠製作，然後在工地組裝的建築部件。"},{"en":"A school can be built faster if walls and roof sections are prefabricated.","zh":"如果牆壁和屋頂部分是預製的，學校可以更快建成。"},{"en":"Prefabricated elements save time because workers do not make every part from scratch on site.","zh":"預製構件節省時間，因為工人不用在工地從零開始製作每個部分。"},{"en":"The phrase is linked with speed, standardisation, and modern construction.","zh":"這個片語與速度、標準化和現代建造相關。"}],"source":"153 - British Architecture.pdf","sourcePage":16},{"front":"metal frames","meaning":"金屬框架","examples":[{"en":"Metal frames became part of post-war building methods.","zh":"金屬框架成為戰後建築方法的一部分。"},{"en":"Metal frames are structural supports made from metal, often used to hold up a building.","zh":"Metal frames 是由金屬製成的結構支撐，常用來支撐建築物。"},{"en":"A warehouse may use metal frames because they can support large open spaces.","zh":"倉庫可能使用金屬框架，因為它們能支撐大型開放空間。"},{"en":"Metal frames can make construction faster and more regular.","zh":"金屬框架可以令建造更快和更規整。"},{"en":"The phrase refers to the skeleton of a building, not its surface finish.","zh":"這個片語指建築骨架，而不是表面飾面。"}],"source":"153 - British Architecture.pdf","sourcePage":16},{"front":"concrete cladding","meaning":"混凝土外牆覆層","examples":[{"en":"Concrete cladding was used in some post-war buildings.","zh":"一些戰後建築使用混凝土外牆覆層。"},{"en":"Concrete cladding is an outer layer of concrete attached to a building’s structure.","zh":"Concrete cladding 是附加在建築結構外部的混凝土外層。"},{"en":"A tower block may use concrete cladding to cover its exterior walls.","zh":"高樓住宅可能使用混凝土外牆覆層覆蓋外牆。"},{"en":"Cladding can affect appearance, weather protection, and maintenance.","zh":"外牆覆層可以影響外觀、防風雨功能和維修。"},{"en":"The phrase describes an external building layer, not the whole structure.","zh":"這個片語描述外部建築層，而不是整個結構。"}],"source":"153 - British Architecture.pdf","sourcePage":17},{"front":"absence of decoration","meaning":"缺乏裝飾","examples":[{"en":"The absence of decoration was a feature of Modernist design.","zh":"缺乏裝飾是現代主義設計的一個特徵。"},{"en":"Absence of decoration means there is little or no added ornament.","zh":"Absence of decoration 指很少或沒有額外裝飾。"},{"en":"A plain white classroom with simple furniture shows an absence of decoration.","zh":"有簡單家具的純白課室顯示缺乏裝飾。"},{"en":"Modernists often valued clean lines and function, so decoration was reduced.","zh":"現代主義者常重視簡潔線條和功能，所以裝飾被減少。"},{"en":"The phrase can suggest simplicity, but some people may find it cold.","zh":"這個片語可以暗示簡潔，但有些人可能覺得冷淡。"}],"source":"153 - British Architecture.pdf","sourcePage":17},{"front":"embraced by Modernists abroad","meaning":"被海外現代主義者採用","examples":[{"en":"These methods had been embraced by Modernists abroad.","zh":"這些方法已被海外現代主義者採用。"},{"en":"Embraced by Modernists abroad means accepted and used by modernist architects in other countries.","zh":"Embraced by Modernists abroad 指被其他國家的現代主義建築師接受和使用。"},{"en":"A teaching method embraced abroad may later become popular at home.","zh":"一種被海外採用的教學方法後來可能在本地流行。"},{"en":"British architects were slower to accept methods already used by foreign modernists.","zh":"英國建築師較慢接受外國現代主義者已使用的方法。"},{"en":"The phrase contrasts overseas acceptance with local hesitation.","zh":"這個片語對比海外接受與本地猶豫。"}],"source":"153 - British Architecture.pdf","sourcePage":17},{"front":"viewed with suspicion","meaning":"被懷疑地看待","examples":[{"en":"Modernist methods had long been viewed with suspicion in Britain.","zh":"現代主義方法長期在英國被懷疑地看待。"},{"en":"Viewed with suspicion means treated with doubt, distrust, or caution.","zh":"Viewed with suspicion 指被以懷疑、不信任或謹慎態度對待。"},{"en":"A new exam system may be viewed with suspicion if teachers do not understand it.","zh":"如果老師不理解新的考試制度，它可能被懷疑地看待。"},{"en":"People may view unfamiliar building materials with suspicion until they see them working safely.","zh":"在人們看見陌生建築材料安全運作前，可能會懷疑地看待它們。"},{"en":"The phrase describes a cautious or negative attitude.","zh":"這個片語描述謹慎或負面的態度。"}],"source":"153 - British Architecture.pdf","sourcePage":17},{"front":"adopted to varying degrees","meaning":"不同程度地被採用","examples":[{"en":"Modernist techniques were adopted to varying degrees in Britain.","zh":"現代主義技術在英國不同程度地被採用。"},{"en":"Adopted to varying degrees means accepted or used at different levels or amounts.","zh":"Adopted to varying degrees 指以不同水平或數量被接受或使用。"},{"en":"Schools adopted online learning to varying degrees during disruptions.","zh":"學校在中斷期間不同程度地採用網上學習。"},{"en":"Some councils used modernist ideas fully, while others used only small parts.","zh":"有些市議會完全使用現代主義想法，另一些只使用小部分。"},{"en":"The phrase shows that change was uneven.","zh":"這個片語顯示改變並不平均。"}],"source":"153 - British Architecture.pdf","sourcePage":17},{"front":"housing developments","meaning":"住宅發展項目","examples":[{"en":"Prefabricated elements were used in housing developments.","zh":"預製構件被用於住宅發展項目。"},{"en":"Housing developments are groups of new homes built as part of one planned project.","zh":"Housing developments 是作為一個規劃項目建成的一組新住宅。"},{"en":"A housing development may include flats, roads, playgrounds, and shops.","zh":"住宅發展項目可能包括公寓、道路、遊樂場和商店。"},{"en":"After war damage, large housing developments can provide homes for many families quickly.","zh":"戰爭破壞後，大型住宅發展項目可以迅速為許多家庭提供住所。"},{"en":"The phrase refers to planned residential construction, not one single house.","zh":"這個片語指有規劃的住宅建設，而不是單一房屋。"}],"source":"153 - British Architecture.pdf","sourcePage":17},{"front":"local authorities","meaning":"地方政府","examples":[{"en":"Local authorities became important patrons of architecture.","zh":"地方政府成為重要的建築委託方。"},{"en":"Local authorities are local government bodies responsible for services in towns, cities, or districts.","zh":"Local authorities 是負責城鎮、城市或地區服務的地方政府機構。"},{"en":"Local authorities may manage housing, planning, roads, schools, and public buildings.","zh":"地方政府可能管理住房、規劃、道路、學校和公共建築。"},{"en":"When local authorities fund buildings, public needs shape architecture more strongly.","zh":"當地方政府資助建築，公共需要會更強烈地塑造建築。"},{"en":"The phrase refers to government at local level, not national government.","zh":"這個片語指地方層面的政府，而不是中央政府。"}],"source":"153 - British Architecture.pdf","sourcePage":17},{"front":"charged with the task of","meaning":"被賦予……任務","examples":[{"en":"Local authorities were charged with the task of rebuilding city centres.","zh":"地方政府被賦予重建市中心的任務。"},{"en":"To be charged with the task of doing something means to be officially given responsibility for it.","zh":"To be charged with the task of doing something 指被正式賦予做某事的責任。"},{"en":"A committee may be charged with the task of improving school safety.","zh":"委員會可能被賦予改善學校安全的任務。"},{"en":"When a council is charged with rebuilding, it must plan, fund, and manage the work.","zh":"當市議會被賦予重建任務，它必須規劃、資助和管理工作。"},{"en":"The phrase is formal and emphasises responsibility.","zh":"這個片語較正式，並強調責任。"}],"source":"153 - British Architecture.pdf","sourcePage":17},{"front":"rebuilding city centres","meaning":"重建市中心","examples":[{"en":"Local authorities were responsible for rebuilding city centres.","zh":"地方政府負責重建市中心。"},{"en":"Rebuilding city centres means repairing or reconstructing the main urban areas after damage or decline.","zh":"Rebuilding city centres 指在破壞或衰落後修復或重建主要城市區域。"},{"en":"After bombing, rebuilding city centres may involve roads, shops, offices, and public spaces.","zh":"轟炸後，重建市中心可能涉及道路、商店、辦公室和公共空間。"},{"en":"City-centre rebuilding changes how people work, shop, travel, and meet.","zh":"市中心重建改變人們工作、購物、出行和聚會的方式。"},{"en":"The phrase is about large-scale urban renewal.","zh":"這個片語關乎大規模城市更新。"}],"source":"153 - British Architecture.pdf","sourcePage":17},{"front":"patrons of architecture","meaning":"建築贊助者；建築委託方","examples":[{"en":"Local authorities became important patrons of architecture.","zh":"地方政府成為重要的建築贊助者。"},{"en":"Patrons of architecture are people or organisations that pay for or commission buildings.","zh":"Patrons of architecture 是出資或委託建造建築物的人或組織。"},{"en":"A university can be a patron of architecture when it hires architects to design new campuses.","zh":"大學聘請建築師設計新校園時，可以成為建築委託方。"},{"en":"Patrons influence architecture because they choose budgets, purposes, and values.","zh":"委託方會影響建築，因為他們選擇預算、用途和價值。"},{"en":"The phrase focuses on who supports and commissions building work.","zh":"這個片語著重誰支持和委託建築工作。"}],"source":"153 - British Architecture.pdf","sourcePage":17},{"front":"represented a shift away from","meaning":"代表由……轉變","examples":[{"en":"This represented a shift away from private individuals.","zh":"這代表由私人個體轉變。"},{"en":"To represent a shift away from something means to show a move from one pattern to another.","zh":"To represent a shift away from something 指顯示從一種模式轉向另一種模式。"},{"en":"Online shopping represented a shift away from traditional street markets for many consumers.","zh":"對許多消費者而言，網上購物代表由傳統街市轉變。"},{"en":"Public building programmes represented a shift away from architecture controlled by wealthy individuals.","zh":"公共建築計劃代表由富裕個人控制建築轉變。"},{"en":"The phrase helps describe historical change in direction.","zh":"這個片語有助描述歷史方向的改變。"}],"source":"153 - British Architecture.pdf","sourcePage":17},{"front":"private individuals","meaning":"私人個體","examples":[{"en":"Private individuals had dominated architecture for centuries.","zh":"私人個體數百年來主導建築。"},{"en":"Private individuals are ordinary persons acting in their own capacity, not as governments or corporations.","zh":"Private individuals 指以個人身份行事的普通個人，而不是政府或公司。"},{"en":"A private individual may commission a house for their family.","zh":"私人個體可能委託建造一間家庭住宅。"},{"en":"When private individuals dominate building, architecture often reflects personal wealth and taste.","zh":"當私人個體主導建築，建築常反映個人財富和品味。"},{"en":"The phrase contrasts individuals with public bodies or large organisations.","zh":"這個片語把個人與公共機構或大型組織作對比。"}],"source":"153 - British Architecture.pdf","sourcePage":18},{"front":"dominated the architectural scene","meaning":"主導建築界","examples":[{"en":"Private individuals had dominated the architectural scene for centuries.","zh":"私人個體數百年來主導建築界。"},{"en":"To dominate the architectural scene means to have the greatest influence over what gets built and designed.","zh":"To dominate the architectural scene 指對建造和設計甚麼擁有最大影響力。"},{"en":"In some cities, developers dominate the architectural scene more than public planners do.","zh":"在一些城市，發展商比公共規劃者更主導建築界。"},{"en":"Whoever controls money and commissions often dominates the architectural scene.","zh":"控制金錢和委託的人通常主導建築界。"},{"en":"The phrase describes power within the world of architecture.","zh":"這個片語描述建築世界中的權力。"}],"source":"153 - British Architecture.pdf","sourcePage":18},{"front":"since the war","meaning":"戰後以來","examples":[{"en":"Since the war, corporate bodies have dominated British architecture.","zh":"戰後以來，企業及機構團體主導了英國建築。"},{"en":"Since the war means from the end of the war until the present or later period being discussed.","zh":"Since the war 指從戰爭結束到現在或所討論的後來時期。"},{"en":"Since the war, many cities have rebuilt damaged neighbourhoods.","zh":"戰後以來，許多城市重建了受損社區。"},{"en":"Social needs, government planning, and corporate clients changed architecture since the war.","zh":"社會需要、政府規劃和企業客戶在戰後以來改變了建築。"},{"en":"The phrase uses the war as a historical dividing line.","zh":"這個片語把戰爭作為歷史分界線。"}],"source":"153 - British Architecture.pdf","sourcePage":18},{"front":"corporate bodies","meaning":"企業及機構團體","examples":[{"en":"Corporate bodies have dominated British architecture since the war.","zh":"戰後以來，企業及機構團體主導了英國建築。"},{"en":"Corporate bodies are organisations such as companies, institutions, or public bodies, rather than private individuals.","zh":"Corporate bodies 是公司、機構或公共團體等組織，而不是私人個體。"},{"en":"Banks, universities, councils, and multinational firms can all be corporate bodies.","zh":"銀行、大學、市議會和跨國公司都可以是企業及機構團體。"},{"en":"When corporate bodies commission buildings, architecture often becomes larger and more institutional.","zh":"當企業及機構團體委託建築，建築常變得更大型和制度化。"},{"en":"The phrase highlights organisational power.","zh":"這個片語突顯組織力量。"}],"source":"153 - British Architecture.pdf","sourcePage":18},{"front":"national and multinational companies","meaning":"全國性及跨國公司","examples":[{"en":"National and multinational companies became major architectural clients.","zh":"全國性及跨國公司成為主要建築客戶。"},{"en":"National and multinational companies are businesses operating across a whole country or across several countries.","zh":"National and multinational companies 是在全國或多個國家營運的企業。"},{"en":"Such companies may commission offices, factories, hotels, or headquarters.","zh":"這類公司可能委託建造辦公室、工廠、酒店或總部。"},{"en":"Their money and branding needs can strongly shape modern architecture.","zh":"它們的資金和品牌需要可以強烈塑造現代建築。"},{"en":"The phrase shows that large business clients replaced many private patrons.","zh":"這個片語顯示大型商業客戶取代了許多私人贊助者。"}],"source":"153 - British Architecture.pdf","sourcePage":18},{"front":"large educational institutions","meaning":"大型教育機構","examples":[{"en":"Large educational institutions have influenced British architecture.","zh":"大型教育機構影響了英國建築。"},{"en":"Large educational institutions are big schools, colleges, or universities with many students and buildings.","zh":"Large educational institutions 是擁有許多學生和建築的大型學校、學院或大學。"},{"en":"A university may commission lecture theatres, libraries, laboratories, and student housing.","zh":"大學可能委託建造演講廳、圖書館、實驗室和學生宿舍。"},{"en":"When educational institutions grow, they create demand for new campuses and public spaces.","zh":"當教育機構增長，它們會創造對新校園和公共空間的需求。"},{"en":"The phrase links education with architectural patronage.","zh":"這個片語把教育與建築委託連接起來。"}],"source":"153 - British Architecture.pdf","sourcePage":18},{"front":"by the late 1980s","meaning":"到一九八零年代末","examples":[{"en":"By the late 1980s, the Modern Movement had lost influence.","zh":"到一九八零年代末，現代主義運動已失去影響力。"},{"en":"By the late 1980s means before or around the final years of the 1980s.","zh":"By the late 1980s 指在1980年代最後幾年之前或當時左右。"},{"en":"By the late 1980s, many offices had begun using computers more widely.","zh":"到一九八零年代末，許多辦公室已開始更廣泛使用電腦。"},{"en":"The phrase shows that a change had already happened by that time.","zh":"這個片語顯示某個變化到那時已經發生。"},{"en":"It is useful for marking historical timing.","zh":"它適合用來標示歷史時間。"}],"source":"153 - British Architecture.pdf","sourcePage":18},{"front":"unfairly blamed for","meaning":"被不公平地歸咎於","examples":[{"en":"The Modern Movement was unfairly blamed for high-rise housing problems.","zh":"現代主義運動被不公平地歸咎於高層住宅問題。"},{"en":"Unfairly blamed for something means held responsible even though the blame is not fully deserved.","zh":"Unfairly blamed for something 指即使責任並不完全應由某方承擔，仍被指責。"},{"en":"Teachers may be unfairly blamed for poor results if students receive no support at home.","zh":"如果學生在家沒有支援，老師可能被不公平地歸咎於成績差。"},{"en":"A design style may be unfairly blamed when poor management is the real problem.","zh":"當真正問題是管理不善，某種設計風格可能被不公平地歸咎。"},{"en":"The phrase separates real responsibility from convenient accusation.","zh":"這個片語區分真正責任和方便的指責。"}],"source":"153 - British Architecture.pdf","sourcePage":18},{"front":"social experiments","meaning":"社會實驗","examples":[{"en":"The Modern Movement was blamed for social experiments in housing.","zh":"現代主義運動被歸咎於住房中的社會實驗。"},{"en":"Social experiments are attempts to organise society or community life in new, untested ways.","zh":"Social experiments 是嘗試以新的、未充分測試的方式組織社會或社區生活。"},{"en":"A new housing estate with shared facilities may be seen as a social experiment.","zh":"一個有共享設施的新屋邨可能被視為社會實驗。"},{"en":"Social experiments can fail if planners ignore how people actually live.","zh":"如果規劃者忽視人們實際如何生活，社會實驗可能失敗。"},{"en":"The phrase can be neutral, but here it suggests risky planning.","zh":"這個片語可以是中性的，但在此暗示有風險的規劃。"}],"source":"153 - British Architecture.pdf","sourcePage":18},{"front":"implicit in","meaning":"隱含於","examples":[{"en":"Social experiments were implicit in high-rise housing.","zh":"社會實驗隱含於高層住宅之中。"},{"en":"Implicit in something means included or suggested by it, even if not stated directly.","zh":"Implicit in something 指包含或暗示於某事之中，即使沒有直接說明。"},{"en":"Trust is implicit in lending a friend money.","zh":"借錢給朋友隱含着信任。"},{"en":"A belief in equality may be implicit in a school’s open admissions policy.","zh":"學校開放收生政策可能隱含着平等信念。"},{"en":"The phrase points to a hidden idea inside a visible action or design.","zh":"這個片語指出可見行動或設計中的隱藏想法。"}],"source":"153 - British Architecture.pdf","sourcePage":18},{"front":"high-rise housing","meaning":"高層住宅","examples":[{"en":"High-rise housing became associated with social problems.","zh":"高層住宅開始與社會問題聯繫起來。"},{"en":"High-rise housing means tall residential buildings containing many homes or flats.","zh":"High-rise housing 指包含許多住宅或公寓的高樓住宅建築。"},{"en":"High-rise housing can save land in crowded cities.","zh":"高層住宅可以在擁擠城市節省土地。"},{"en":"Poorly managed high-rise housing may suffer from isolation, maintenance problems, and safety concerns.","zh":"管理不善的高層住宅可能出現孤立、維修問題和安全憂慮。"},{"en":"The phrase describes building height and residential use.","zh":"這個片語描述建築高度和住宅用途。"}],"source":"153 - British Architecture.pdf","sourcePage":18},{"front":"lost out to","meaning":"敗給；被……取代","examples":[{"en":"The Modern Movement lost out to post-modernism.","zh":"現代主義運動敗給了後現代主義。"},{"en":"To lose out to something means to be replaced, defeated, or made less successful by it.","zh":"To lose out to something 指被某事取代、擊敗或削弱成功機會。"},{"en":"Small shops may lose out to online platforms if customers prefer delivery.","zh":"如果顧客偏好送貨，小店可能敗給網上平台。"},{"en":"A design style loses out when public taste moves toward another style.","zh":"當公眾品味轉向另一種風格，某種設計風格便會被取代。"},{"en":"The phrase suggests competition between alternatives.","zh":"這個片語暗示不同選項之間的競爭。"}],"source":"153 - British Architecture.pdf","sourcePage":19},{"front":"irony and spectacle","meaning":"反諷和視覺奇觀","examples":[{"en":"Post-modernism emphasised irony and spectacle.","zh":"後現代主義強調反諷和視覺奇觀。"},{"en":"Irony and spectacle means playful contradiction and eye-catching visual display.","zh":"Irony and spectacle 指帶玩味的矛盾和吸引眼球的視覺展示。"},{"en":"A building may use irony when it copies a classical column in a humorous or exaggerated way.","zh":"當建築以幽默或誇張方式模仿古典柱子，它可能使用反諷。"},{"en":"Spectacle attracts attention through size, colour, surprise, or drama.","zh":"視覺奇觀透過大小、色彩、驚喜或戲劇性吸引注意。"},{"en":"The phrase suggests architecture as performance, not only function.","zh":"這個片語暗示建築是一種表演，而不只是功能。"}],"source":"153 - British Architecture.pdf","sourcePage":19},{"front":"in the shape of","meaning":"以……形式","examples":[{"en":"The Modern Movement lost out to irony and spectacle in the shape of post-modernism.","zh":"現代主義運動敗給了以後現代主義形式出現的反諷和視覺奇觀。"},{"en":"In the shape of means in the form of a particular thing.","zh":"In the shape of 指以某種具體形式出現。"},{"en":"The school received support in the shape of new computers and free training.","zh":"學校以新電腦和免費培訓的形式獲得支援。"},{"en":"The city gained a new landmark in the shape of a glass museum.","zh":"城市以玻璃博物館的形式獲得新地標。"},{"en":"The phrase introduces the specific form that an idea or change takes.","zh":"這個片語引出某個想法或變化採取的具體形式。"}],"source":"153 - British Architecture.pdf","sourcePage":19},{"front":"post-modernism","meaning":"後現代主義","examples":[{"en":"Post-modernism replaced the Modern Movement in the late twentieth century.","zh":"後現代主義在二十世紀後期取代了現代主義運動。"},{"en":"Post-modernism is a style or movement that often mixes historical references, irony, and playful design.","zh":"Post-modernism 是一種常混合歷史引用、反諷和玩味設計的風格或運動。"},{"en":"A post-modern building may borrow shapes from older architecture but use them in surprising ways.","zh":"後現代建築可能借用舊建築形狀，但以令人意外的方式使用。"},{"en":"Post-modernism reacted against the seriousness and simplicity of modernism.","zh":"後現代主義是對現代主義嚴肅和簡潔的反應。"},{"en":"The phrase is linked with variety, quotation, humour, and spectacle.","zh":"這個片語與多樣性、引用、幽默和視覺奇觀相關。"}],"source":"153 - British Architecture.pdf","sourcePage":19},{"front":"cheerful borrowings from","meaning":"愉快地借用……","examples":[{"en":"Post-modernism made cheerful borrowings from many periods.","zh":"後現代主義愉快地借用許多時期的元素。"},{"en":"Cheerful borrowings from something means playful and confident use of ideas from another source.","zh":"Cheerful borrowings from something 指以玩味而自信的方式使用來自其他來源的想法。"},{"en":"A café may make cheerful borrowings from 1950s design with bright colours and old signs.","zh":"咖啡店可能用鮮艷顏色和舊招牌，愉快地借用1950年代設計。"},{"en":"Borrowing becomes cheerful when it feels light, open, and creative rather than anxious.","zh":"當借用感覺輕鬆、開放和有創意，而不是焦慮時，它便是愉快的。"},{"en":"The phrase suggests influence without strict imitation.","zh":"這個片語暗示受影響，但不是嚴格模仿。"}],"source":"153 - British Architecture.pdf","sourcePage":19},{"front":"any period","meaning":"任何時期","examples":[{"en":"Post-modernism borrowed from anywhere and any period.","zh":"後現代主義從任何地方和任何時期借用元素。"},{"en":"Any period means any historical time, without limiting the choice to one age.","zh":"Any period 指任何歷史時期，不把選擇限制於某一年代。"},{"en":"A costume designer may borrow clothes from any period if the film is playful rather than realistic.","zh":"如果電影帶玩味而不是追求寫實，服裝設計師可以從任何時期借用服裝。"},{"en":"Post-modern design can mix details from ancient, medieval, and modern periods.","zh":"後現代設計可以混合古代、中世紀和現代時期的細節。"},{"en":"The phrase emphasises freedom from strict historical rules.","zh":"這個片語強調不受嚴格歷史規則限制的自由。"}],"source":"153 - British Architecture.pdf","sourcePage":19},{"front":"showing signs of age","meaning":"顯露老態；開始過時","examples":[{"en":"Even post-modernism is showing signs of age.","zh":"甚至後現代主義也開始顯露老態。"},{"en":"Showing signs of age means beginning to look old, outdated, or less fresh.","zh":"Showing signs of age 指開始看起來老舊、過時或不再新鮮。"},{"en":"A shopping mall is showing signs of age when its tiles, lights, and signs look old-fashioned.","zh":"當商場的地磚、燈光和標誌看起來過時，它便顯露老態。"},{"en":"A style can show signs of age when younger people no longer find it exciting.","zh":"當年輕人不再覺得某風格刺激，它可能開始過時。"},{"en":"The phrase suggests slow ageing, not complete failure.","zh":"這個片語暗示慢慢老化，而不是完全失敗。"}],"source":"153 - British Architecture.pdf","sourcePage":19},{"front":"what comes next","meaning":"接下來會是甚麼","examples":[{"en":"The writer wonders what comes next after post-modernism.","zh":"作者思考後現代主義之後接下來會是甚麼。"},{"en":"What comes next means what will happen or appear after the current stage.","zh":"What comes next 指當前階段之後會發生或出現甚麼。"},{"en":"After students finish the basic course, they often ask what comes next.","zh":"學生完成基礎課程後，常會問接下來會是甚麼。"},{"en":"In architecture, each movement raises the question of what comes next.","zh":"在建築中，每一場運動都會引出接下來會是甚麼的問題。"},{"en":"The phrase looks forward to the next development.","zh":"這個片語面向下一步發展。"}],"source":"153 - British Architecture.pdf","sourcePage":19},{"front":"complete the sentences below","meaning":"完成以下句子","examples":[{"en":"Students complete the sentences below using words from the passage.","zh":"學生使用文章中的字詞完成以下句子。"},{"en":"Complete the sentences below means fill in the missing parts of the sentences printed underneath.","zh":"Complete the sentences below 指填寫下方句子中缺失的部分。"},{"en":"In a reading test, students complete the sentences below by finding exact information in the text.","zh":"在閱讀測驗中，學生透過在文章中找準確資料來完成以下句子。"},{"en":"If learners read the instruction carefully, they know how many words they may use.","zh":"如果學習者仔細閱讀指示，就會知道可以使用多少字。"},{"en":"The phrase is a common exam instruction.","zh":"這個片語是常見考試指示。"}],"source":"153 - British Architecture.pdf","sourcePage":19},{"front":"choose no more than three words","meaning":"選擇不多於三個字","examples":[{"en":"Students choose no more than three words from the passage.","zh":"學生從文章中選擇不多於三個字。"},{"en":"Choose no more than three words means the answer must contain three words or fewer.","zh":"Choose no more than three words 指答案必須包含三個字或以下。"},{"en":"If the answer has four words, it is wrong even if the idea is correct.","zh":"如果答案有四個字，即使意思正確也是錯的。"},{"en":"Students should copy only the necessary words when the limit is strict.","zh":"當字數限制嚴格，學生應只抄必要字詞。"},{"en":"The phrase teaches careful control of answer length.","zh":"這個片語教人仔細控制答案長度。"}],"source":"153 - British Architecture.pdf","sourcePage":19},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must come from the passage.","zh":"答案必須從文章中得出。"},{"en":"From the passage means taken directly from the reading text, not invented by the student.","zh":"From the passage 指直接取自閱讀文本，而不是由學生自己創造。"},{"en":"In IELTS reading, words from the passage should be copied accurately.","zh":"在IELTS閱讀中，文章中的字詞應準確抄寫。"},{"en":"If an answer is based only on common knowledge, it may not be accepted.","zh":"如果答案只基於常識，可能不被接受。"},{"en":"The phrase reminds students that evidence is in the text.","zh":"這個片語提醒學生證據在文本中。"}],"source":"153 - British Architecture.pdf","sourcePage":19},{"front":"constructed from","meaning":"由……建造","examples":[{"en":"Anglo-Saxon buildings were constructed from wood.","zh":"盎格魯撒克遜建築由木材建造。"},{"en":"Constructed from means built using a particular material.","zh":"Constructed from 指使用某種材料建造。"},{"en":"A bridge constructed from steel can carry heavy traffic.","zh":"由鋼材建造的橋樑可以承受繁忙交通。"},{"en":"Buildings constructed from weak materials may not last for centuries.","zh":"由脆弱材料建造的建築可能無法保存數百年。"},{"en":"The phrase identifies the material used in construction.","zh":"這個片語指出建造所用的材料。"}],"source":"153 - British Architecture.pdf","sourcePage":20},{"front":"unlike medieval architecture","meaning":"與中世紀建築不同","examples":[{"en":"Unlike medieval architecture, later buildings displayed wealth and status.","zh":"與中世紀建築不同，後來的建築展示財富和地位。"},{"en":"Unlike medieval architecture means different from medieval architecture.","zh":"Unlike medieval architecture 指與中世紀建築不同。"},{"en":"Unlike older classrooms, modern ones may use screens and movable desks.","zh":"與較舊課室不同，現代課室可能使用螢幕和可移動桌椅。"},{"en":"The phrase introduces contrast between two periods, styles, or examples.","zh":"這個片語引出兩個時期、風格或例子之間的對比。"},{"en":"It helps readers notice how one thing differs from another.","zh":"它幫助讀者注意一事與另一事有何不同。"}],"source":"153 - British Architecture.pdf","sourcePage":20},{"front":"intended to represent","meaning":"旨在代表","examples":[{"en":"Sixteenth-century buildings were intended to represent status and wealth.","zh":"十六世紀建築旨在代表地位和財富。"},{"en":"Intended to represent means designed or meant to show a particular idea or quality.","zh":"Intended to represent 指被設計或意圖展示某個想法或特質。"},{"en":"A school badge may be intended to represent courage, learning, and community.","zh":"校徽可能旨在代表勇氣、學習和社群。"},{"en":"A grand entrance can be intended to represent power and confidence.","zh":"宏偉入口可以旨在代表權力和信心。"},{"en":"The phrase links design with meaning.","zh":"這個片語把設計與意義連接起來。"}],"source":"153 - British Architecture.pdf","sourcePage":20},{"front":"costly glass","meaning":"昂貴玻璃","examples":[{"en":"Costly glass was used to show wealth.","zh":"昂貴玻璃被用來展示財富。"},{"en":"Costly glass means glass that is expensive to make, buy, or install.","zh":"Costly glass 指製造、購買或安裝成本高的玻璃。"},{"en":"In the past, costly glass in large windows signalled that the owner was rich.","zh":"過去，大窗中的昂貴玻璃標示屋主富有。"},{"en":"When a material is costly, using it extensively becomes a social statement.","zh":"當一種材料昂貴，大量使用它便成為社會宣示。"},{"en":"The phrase explains why glass could function as decoration and status.","zh":"這個片語解釋玻璃為何可以作為裝飾和地位象徵。"}],"source":"153 - British Architecture.pdf","sourcePage":20},{"front":"used extensively as","meaning":"被廣泛用作","examples":[{"en":"Glass was used extensively as a statement of wealth.","zh":"玻璃被廣泛用作財富的象徵。"},{"en":"Used extensively as means used widely or in large amounts for a particular purpose.","zh":"Used extensively as 指為某個目的被廣泛或大量使用。"},{"en":"Plastic is used extensively as packaging because it is light and cheap.","zh":"塑膠因輕便便宜而被廣泛用作包裝。"},{"en":"If glass is used extensively as decoration, the building may look brighter and richer.","zh":"如果玻璃被廣泛用作裝飾，建築可能顯得更明亮和富有。"},{"en":"The phrase shows both wide use and purpose.","zh":"這個片語同時顯示廣泛使用和用途。"}],"source":"153 - British Architecture.pdf","sourcePage":20},{"front":"skilled at handling","meaning":"擅長處理","examples":[{"en":"Inigo Jones was skilled at handling classical detail and proportion.","zh":"伊尼戈・瓊斯擅長處理古典細節和比例。"},{"en":"Skilled at handling something means good at managing, using, or dealing with it.","zh":"Skilled at handling something 指善於管理、使用或處理某事。"},{"en":"A nurse is skilled at handling anxious patients if she can calm them gently.","zh":"如果護士能溫和安撫焦慮病人，她便擅長處理焦慮病人。"},{"en":"An architect skilled at handling proportion can make a building feel balanced.","zh":"擅長處理比例的建築師可以令建築感覺均衡。"},{"en":"The phrase praises practical ability and judgement.","zh":"這個片語讚揚實際能力和判斷力。"}],"source":"153 - British Architecture.pdf","sourcePage":20},{"front":"favoured the production of","meaning":"支持製作","examples":[{"en":"William Morris favoured the production of hand-crafted goods.","zh":"William Morris支持製作手工製品。"},{"en":"To favour the production of something means to support making that kind of thing.","zh":"To favour the production of something 指支持製造某類東西。"},{"en":"A government may favour the production of renewable energy by offering subsidies.","zh":"政府可能透過補貼支持生產可再生能源。"},{"en":"Morris favoured hand-crafted goods because he valued human skill and honesty in making.","zh":"Morris支持手工製品，因為他重視製作中的人類技藝和真誠。"},{"en":"The phrase shows preference and support.","zh":"這個片語顯示偏好和支持。"}],"source":"153 - British Architecture.pdf","sourcePage":20},{"front":"provided landowners with","meaning":"為地主提供","examples":[{"en":"Architects such as Edwin Lutyens provided landowners with conservative houses.","zh":"Edwin Lutyens等建築師為地主提供保守風格住宅。"},{"en":"To provide someone with something means to give, supply, or create it for them.","zh":"To provide someone with something 指給予、供應或創造某物給某人。"},{"en":"A school provides students with books, lessons, and safe classrooms.","zh":"學校為學生提供書本、課堂和安全課室。"},{"en":"Architects provide clients with designs that match their taste, money, and social position.","zh":"建築師為客戶提供符合其品味、金錢和社會地位的設計。"},{"en":"The phrase connects provider, receiver, and what is supplied.","zh":"這個片語連接提供者、接收者和所供應的東西。"}],"source":"153 - British Architecture.pdf","sourcePage":20},{"front":"conservative houses","meaning":"保守風格住宅","examples":[{"en":"Some architects designed conservative houses for the landed class.","zh":"一些建築師為地主階級設計保守風格住宅。"},{"en":"Conservative houses are homes that follow traditional styles rather than new or experimental ideas.","zh":"Conservative houses 是遵循傳統風格，而不是新穎或實驗性想法的住宅。"},{"en":"A conservative house may use symmetry, familiar materials, and historical references.","zh":"保守風格住宅可能使用對稱、熟悉材料和歷史引用。"},{"en":"Conservative design can feel safe and respectable, but it may resist innovation.","zh":"保守設計可以感覺安全和體面，但可能抗拒創新。"},{"en":"The phrase describes style, not necessarily political belief.","zh":"這個片語描述風格，不一定指政治信念。"}],"source":"153 - British Architecture.pdf","sourcePage":20},{"front":"architectural commissions shifted from…to…","meaning":"建築委託由……轉向……","examples":[{"en":"After the war, architectural commissions shifted from private individuals to corporate bodies.","zh":"戰後，建築委託由私人個體轉向企業及機構團體。"},{"en":"This means the main clients who ordered buildings changed from one group to another.","zh":"這句話意思是下訂單建造建築的主要客戶由一個群體轉為另一個群體。"},{"en":"Commissions may shift from rich families to universities when public institutions expand.","zh":"當公共機構擴張，建築委託可能由富裕家庭轉向大學。"},{"en":"When commissions shift, the purpose and scale of buildings often change too.","zh":"當委託轉變，建築的目的和規模通常也會改變。"},{"en":"The phrase is useful for explaining changes in who controls architectural work.","zh":"這個片語適合解釋誰控制建築工作方面的變化。"}],"source":"153 - British Architecture.pdf","sourcePage":20},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter for each answer.","zh":"學生為每個答案選出正確字母。"},{"en":"Choose the correct letter means select the letter that matches the right option.","zh":"Choose the correct letter 指選擇與正確選項相符的字母。"},{"en":"In a multiple-choice question, students must choose the correct letter, not copy a full sentence.","zh":"在多項選擇題中，學生必須選出正確字母，而不是抄整句。"},{"en":"Reading the options carefully helps students avoid choosing a letter too quickly.","zh":"仔細閱讀選項有助學生避免太快選字母。"},{"en":"The phrase is a standard exam instruction.","zh":"這個片語是標準考試指示。"}],"source":"153 - British Architecture.pdf","sourcePage":20},{"front":"defining feature","meaning":"定義性特徵","examples":[{"en":"The defining feature of medieval architecture was its functionality.","zh":"中世紀建築的定義性特徵是其功能性。"},{"en":"A defining feature is the main characteristic that makes something what it is.","zh":"Defining feature 是令某物成為其本身的主要特徵。"},{"en":"The defining feature of a good dictionary is clear explanation, not just many words.","zh":"好字典的定義性特徵是清楚解釋，而不只是詞多。"},{"en":"If functionality is the defining feature, decoration is less central.","zh":"如果功能性是定義性特徵，裝飾便較不核心。"},{"en":"The phrase identifies the most important quality.","zh":"這個片語指出最重要的特質。"}],"source":"153 - British Architecture.pdf","sourcePage":21},{"front":"immense","meaning":"巨大的","examples":[{"en":"Some medieval buildings were immense, but size was not their defining feature.","zh":"一些中世紀建築很巨大，但大小不是它們的定義性特徵。"},{"en":"Immense means extremely large or great.","zh":"Immense 指極大或巨大。"},{"en":"An immense library can hold millions of books.","zh":"巨大的圖書館可以收藏數百萬本書。"},{"en":"An immense building may impress visitors, but size alone does not explain its purpose.","zh":"巨大建築可能令訪客印象深刻，但大小本身不能解釋其用途。"},{"en":"The word describes scale, not necessarily quality.","zh":"這個字描述規模，而不一定描述質素。"}],"source":"153 - British Architecture.pdf","sourcePage":21},{"front":"functional","meaning":"功能性的","examples":[{"en":"Medieval architecture was strongly functional.","zh":"中世紀建築非常功能性。"},{"en":"Functional means designed to be useful and to work well for a purpose.","zh":"Functional 指為有用和有效完成目的而設計。"},{"en":"A functional kitchen has enough space, storage, light, and safe equipment.","zh":"功能性的廚房有足夠空間、儲物、光線和安全設備。"},{"en":"Functional design can save time and reduce frustration.","zh":"功能性設計可以節省時間並減少挫折。"},{"en":"The word contrasts with design that is mainly decorative.","zh":"這個字與主要為裝飾的設計形成對比。"}],"source":"153 - British Architecture.pdf","sourcePage":21},{"front":"decorative","meaning":"裝飾性的","examples":[{"en":"Some later architecture became more decorative than medieval architecture.","zh":"一些後來建築比中世紀建築更具裝飾性。"},{"en":"Decorative means added mainly to make something look attractive.","zh":"Decorative 指主要為了令某物更美觀而加入。"},{"en":"Decorative tiles can make a plain wall more interesting.","zh":"裝飾性瓷磚可以令普通牆壁更有趣。"},{"en":"Decoration can show wealth, taste, or cultural identity.","zh":"裝飾可以展示財富、品味或文化身份。"},{"en":"The word focuses on appearance rather than practical use.","zh":"這個字著重外觀，而不是實際用途。"}],"source":"153 - British Architecture.pdf","sourcePage":21},{"front":"bizarre","meaning":"古怪的","examples":[{"en":"The option asks whether medieval architecture was bizarre.","zh":"這個選項問中世紀建築是否古怪。"},{"en":"Bizarre means very strange, unusual, or hard to explain.","zh":"Bizarre 指非常奇怪、不尋常或難以解釋。"},{"en":"A building shaped like a giant shoe would seem bizarre to many people.","zh":"一座形狀像巨型鞋子的建築，對許多人而言會顯得古怪。"},{"en":"Something bizarre may attract attention, but it is not always useful or beautiful.","zh":"古怪的東西可能吸引注意，但不一定有用或美麗。"},{"en":"The word is often negative or surprised in tone.","zh":"這個字語氣常帶負面或驚訝。"}],"source":"153 - British Architecture.pdf","sourcePage":21},{"front":"contributed to","meaning":"促成","examples":[{"en":"Greater security contributed to the development of outward-looking buildings.","zh":"更大的安全感促成了向外開放建築的發展。"},{"en":"To contribute to something means to help cause or support it.","zh":"To contribute to something 指幫助造成或支持某事。"},{"en":"Regular reading contributes to better vocabulary.","zh":"定期閱讀促成更好的詞彙量。"},{"en":"Better lighting can contribute to safer streets.","zh":"更好的照明可以促成更安全的街道。"},{"en":"The phrase shows one cause among several, not necessarily the only cause.","zh":"這個片語顯示眾多原因之一，不一定是唯一原因。"}],"source":"153 - British Architecture.pdf","sourcePage":21},{"front":"the development of","meaning":"……的發展","examples":[{"en":"The question asks what contributed to the development of outward-looking buildings.","zh":"問題問甚麼促成了向外開放建築的發展。"},{"en":"The development of something means the process by which it grows, changes, or becomes more advanced.","zh":"The development of something 指某事成長、改變或變得更先進的過程。"},{"en":"The development of public transport can make a city easier to live in.","zh":"公共交通的發展可以令城市更宜居。"},{"en":"The development of a building style may take many decades.","zh":"一種建築風格的發展可能需要數十年。"},{"en":"The phrase focuses on process, not just final result.","zh":"這個片語著重過程，而不只是最終結果。"}],"source":"153 - British Architecture.pdf","sourcePage":21},{"front":"monarch returned from","meaning":"君主從……返回","examples":[{"en":"Buildings in the 1660s were influenced by Europe because the monarch returned from the Continent.","zh":"1660年代的建築受歐洲影響，因為君主從歐洲大陸返回。"},{"en":"Monarch returned from means the king or queen came back from a place.","zh":"Monarch returned from 指國王或女王從某地回來。"},{"en":"When a monarch returns from exile, political supporters may regain confidence.","zh":"當君主從流亡地返回，政治支持者可能恢復信心。"},{"en":"A ruler returning from abroad may bring foreign tastes and ideas home.","zh":"從海外返回的統治者可能把外國品味和想法帶回本國。"},{"en":"The phrase connects personal return with wider cultural change.","zh":"這個片語把個人回歸與更廣泛文化變化連接起來。"}],"source":"153 - British Architecture.pdf","sourcePage":21},{"front":"latest European trends","meaning":"最新歐洲潮流","examples":[{"en":"Royalists built houses reflecting the latest European trends.","zh":"保皇派建造反映最新歐洲潮流的房屋。"},{"en":"Latest European trends are the newest styles, fashions, or ideas coming from Europe.","zh":"Latest European trends 指來自歐洲的最新風格、時尚或想法。"},{"en":"Wealthy homeowners may follow the latest European trends to appear cultured and modern.","zh":"富裕屋主可能追隨最新歐洲潮流，以顯得有文化和現代。"},{"en":"When travellers bring home new trends, local design can change quickly.","zh":"當旅客把新潮流帶回家，本地設計可以迅速改變。"},{"en":"The phrase suggests fashion and international influence.","zh":"這個片語暗示時尚和國際影響。"}],"source":"153 - British Architecture.pdf","sourcePage":21},{"front":"what kind of impression","meaning":"甚麼樣的印象","examples":[{"en":"The question asks what kind of impression the British Baroque conveyed.","zh":"問題問英國巴洛克風格傳達甚麼樣的印象。"},{"en":"What kind of impression means what feeling, image, or idea something gives to people.","zh":"What kind of impression 指某物給人甚麼感覺、形象或想法。"},{"en":"A clean classroom gives the impression that learning is valued.","zh":"乾淨課室給人學習受重視的印象。"},{"en":"A dark entrance may create an unfriendly impression before visitors go inside.","zh":"昏暗入口可能在訪客進入前造成不友善的印象。"},{"en":"The phrase asks about effect on viewers or readers.","zh":"這個片語詢問對觀者或讀者造成的效果。"}],"source":"153 - British Architecture.pdf","sourcePage":21},{"front":"convey","meaning":"傳達","examples":[{"en":"The British Baroque conveyed authority and richness.","zh":"英國巴洛克風格傳達權威和華麗感。"},{"en":"To convey something means to communicate or express it.","zh":"To convey something 指傳遞或表達某事。"},{"en":"A teacher’s calm voice can convey confidence to students.","zh":"老師冷靜的聲音可以向學生傳達信心。"},{"en":"A building can convey power through height, symmetry, and expensive materials.","zh":"建築可以透過高度、對稱和昂貴材料傳達權力。"},{"en":"The word is useful when discussing meaning without direct words.","zh":"這個字適合討論沒有直接文字的意義。"}],"source":"153 - British Architecture.pdf","sourcePage":21},{"front":"toughness","meaning":"強硬感","examples":[{"en":"The option describes the impression of toughness.","zh":"這個選項描述強硬感。"},{"en":"Toughness means strength, hardness, or ability to endure difficulty.","zh":"Toughness 指力量、堅硬或承受困難的能力。"},{"en":"A concrete bunker may give an impression of toughness.","zh":"混凝土碉堡可能給人強硬感。"},{"en":"Toughness can be useful in defence, but it may also feel harsh or unfriendly.","zh":"強硬感在防衛上可能有用，但也可能感覺嚴厲或不友善。"},{"en":"The word describes strength more than beauty.","zh":"這個字描述力量多於美感。"}],"source":"153 - British Architecture.pdf","sourcePage":22},{"front":"steadiness","meaning":"穩定感","examples":[{"en":"The option describes the impression of steadiness.","zh":"這個選項描述穩定感。"},{"en":"Steadiness means stability, calmness, or reliability.","zh":"Steadiness 指穩定、冷靜或可靠。"},{"en":"A well-built stone bridge can give an impression of steadiness.","zh":"建造良好的石橋可以給人穩定感。"},{"en":"Steadiness is valued when people want safety and trust.","zh":"當人們想要安全和信任時，穩定感很重要。"},{"en":"The word suggests control rather than drama.","zh":"這個字暗示控制感，而不是戲劇性。"}],"source":"153 - British Architecture.pdf","sourcePage":22},{"front":"mildness","meaning":"溫和感","examples":[{"en":"The option describes the impression of mildness.","zh":"這個選項描述溫和感。"},{"en":"Mildness means gentleness, softness, or lack of strong force.","zh":"Mildness 指溫柔、柔和或缺乏強烈力量。"},{"en":"A small garden café may give an impression of mildness and calm.","zh":"小型花園咖啡店可能給人溫和而平靜的感覺。"},{"en":"Mildness may suit a peaceful home but not a building meant to show power.","zh":"溫和感可能適合和平住宅，但不適合用來展示權力的建築。"},{"en":"The word contrasts with heaviness, drama, and authority.","zh":"這個字與厚重、戲劇性和權威形成對比。"}],"source":"153 - British Architecture.pdf","sourcePage":22},{"front":"conservatism","meaning":"保守主義","examples":[{"en":"The option describes the impression of conservatism.","zh":"這個選項描述保守主義的印象。"},{"en":"Conservatism means preference for tradition and caution about change.","zh":"Conservatism 指偏好傳統並對改變保持謹慎。"},{"en":"A school shows conservatism if it refuses all new teaching methods.","zh":"如果學校拒絕所有新教學方法，就顯示保守主義。"},{"en":"In architecture, conservatism may appear through old styles and familiar forms.","zh":"在建築中，保守主義可能透過舊風格和熟悉形式表現。"},{"en":"The word can describe politics, values, or design attitudes.","zh":"這個字可以描述政治、價值觀或設計態度。"}],"source":"153 - British Architecture.pdf","sourcePage":22},{"front":"individual craftsperson","meaning":"個別工匠","examples":[{"en":"The individual craftsperson lost importance after mass production.","zh":"大規模生產出現後，個別工匠失去重要性。"},{"en":"An individual craftsperson is a skilled person who makes things by hand.","zh":"Individual craftsperson 是用手工製作物件的熟練人士。"},{"en":"A potter shaping bowls one by one is an individual craftsperson.","zh":"一位逐個塑造碗的陶工就是個別工匠。"},{"en":"Mass production reduced the importance of individual craftspeople because machines made identical goods faster.","zh":"大規模生產降低了個別工匠的重要性，因為機器更快製造相同商品。"},{"en":"The phrase emphasises human skill in making.","zh":"這個片語強調製作中的人類技藝。"}],"source":"153 - British Architecture.pdf","sourcePage":22},{"front":"ceased to play","meaning":"不再扮演","examples":[{"en":"The individual craftsperson ceased to play a major role in creation.","zh":"個別工匠不再在創作中扮演重要角色。"},{"en":"Ceased to play a role means stopped having that role.","zh":"Ceased to play a role 指停止擁有某個角色。"},{"en":"Paper forms ceased to play a major role after the company moved all applications online.","zh":"公司把所有申請移到網上後，紙本表格不再扮演重要角色。"},{"en":"When machines replaced handwork, craftsmen ceased to play the same central role.","zh":"當機器取代手工，工匠不再扮演同樣核心角色。"},{"en":"The phrase shows that an earlier function came to an end.","zh":"這個片語顯示早前功能結束。"}],"source":"153 - British Architecture.pdf","sourcePage":22},{"front":"following the emergence of","meaning":"隨着……出現","examples":[{"en":"Craftsmen lost their role following the emergence of mass production.","zh":"隨着大規模生產出現，工匠失去了他們的角色。"},{"en":"Following the emergence of something means after that thing appeared or became important.","zh":"Following the emergence of something 指在某事出現或變得重要之後。"},{"en":"Following the emergence of smartphones, many people changed how they read news.","zh":"隨着智能手機出現，許多人改變了閱讀新聞的方式。"},{"en":"New jobs appeared following the emergence of online shopping.","zh":"隨着網上購物出現，新工作也出現了。"},{"en":"The phrase links a later change to an earlier development.","zh":"這個片語把後來的變化與早前發展連接起來。"}],"source":"153 - British Architecture.pdf","sourcePage":22},{"front":"industrial-scale production","meaning":"工業規模生產","examples":[{"en":"Industrial-scale production reduced the role of individual craftsmen.","zh":"工業規模生產降低了個別工匠的角色。"},{"en":"Industrial-scale production means producing goods in very large quantities using factories and machines.","zh":"Industrial-scale production 指使用工廠和機器大量生產商品。"},{"en":"Industrial-scale production can make furniture cheaper and more widely available.","zh":"工業規模生產可以令家具更便宜和更普及。"},{"en":"When production becomes industrial-scale, individual variation often decreases.","zh":"當生產變成工業規模，個別差異常會減少。"},{"en":"The phrase stresses size, machinery, and standardisation.","zh":"這個片語強調規模、機械和標準化。"}],"source":"153 - British Architecture.pdf","sourcePage":22},{"front":"building styles changed","meaning":"建築風格改變","examples":[{"en":"Building styles changed after the Second World War.","zh":"第二次世界大戰後，建築風格改變。"},{"en":"Building styles changed means the appearance, materials, and design principles of buildings became different.","zh":"Building styles changed 指建築的外觀、材料和設計原則變得不同。"},{"en":"Building styles changed when glass towers replaced many older stone offices.","zh":"當玻璃高樓取代許多舊石造辦公室時，建築風格便改變。"},{"en":"Social needs and technology can make building styles change quickly.","zh":"社會需要和科技可以令建築風格迅速改變。"},{"en":"The phrase describes visible design change over time.","zh":"這個片語描述隨時間出現的可見設計變化。"}],"source":"153 - British Architecture.pdf","sourcePage":22},{"front":"as a result of","meaning":"由於；作為……的結果","examples":[{"en":"Post-war building styles changed as a result of urgent housing needs.","zh":"戰後建築風格由於迫切住房需要而改變。"},{"en":"As a result of means because of something.","zh":"As a result of 指因為某事。"},{"en":"The road closed as a result of heavy rain.","zh":"道路由於大雨而關閉。"},{"en":"More flats were built as a result of population growth.","zh":"由於人口增長，更多公寓被建造。"},{"en":"The phrase clearly introduces a cause.","zh":"這個片語清楚引出原因。"}],"source":"153 - British Architecture.pdf","sourcePage":22},{"front":"abundant materials","meaning":"充足材料","examples":[{"en":"The option asks whether abundant materials caused post-war change.","zh":"這個選項問充足材料是否造成戰後變化。"},{"en":"Abundant materials are materials available in large quantities.","zh":"Abundant materials 指大量可取得的材料。"},{"en":"If timber is abundant, builders may use it widely in houses.","zh":"如果木材充足，建造者可能在房屋中廣泛使用它。"},{"en":"Abundant materials can make construction cheaper and faster.","zh":"充足材料可以令建造更便宜和更快速。"},{"en":"The phrase focuses on supply, not design style itself.","zh":"這個片語著重供應，而不是設計風格本身。"}],"source":"153 - British Architecture.pdf","sourcePage":22},{"front":"a shortage of cheap housing","meaning":"廉價房屋短缺","examples":[{"en":"A shortage of cheap housing encouraged the adoption of Modernist methods.","zh":"廉價房屋短缺促使現代主義方法被採用。"},{"en":"A shortage of cheap housing means there are not enough affordable homes for people who need them.","zh":"A shortage of cheap housing 指負擔得起的住宅不足以滿足人們需要。"},{"en":"A city may face a shortage of cheap housing when rent rises faster than wages.","zh":"當租金升得比工資快，城市可能面對廉價房屋短缺。"},{"en":"Such a shortage can push governments to build quickly and use standardised methods.","zh":"這種短缺可以推動政府快速建屋並使用標準化方法。"},{"en":"The phrase describes both a social problem and a pressure on architecture.","zh":"這個片語同時描述社會問題和對建築的壓力。"}],"source":"153 - British Architecture.pdf","sourcePage":23},{"front":"conservative views","meaning":"保守觀點","examples":[{"en":"The option asks whether conservative views caused post-war architectural change.","zh":"這個選項問保守觀點是否造成戰後建築變化。"},{"en":"Conservative views are opinions that favour tradition and are cautious about major change.","zh":"Conservative views 是偏好傳統並對重大改變保持謹慎的看法。"},{"en":"A person with conservative views may prefer old buildings to experimental new designs.","zh":"持保守觀點的人可能較喜歡舊建築，而不是實驗性新設計。"},{"en":"Conservative views can slow innovation when people fear unfamiliar materials or styles.","zh":"當人們害怕陌生材料或風格，保守觀點可以減慢創新。"},{"en":"The phrase describes attitudes that resist sudden change.","zh":"這個片語描述抗拒突然改變的態度。"}],"source":"153 - British Architecture.pdf","sourcePage":23}],"ielts/reading/passage-2/Practice 154":[{"front":"Blue-footed Boobies","meaning":"藍腳鰹鳥","examples":[{"en":"The passage describes the feeding, mating and breeding behaviour of blue-footed boobies.","zh":"文章描述藍腳鰹鳥的覓食、交配和繁殖行為。"},{"en":"Blue-footed boobies are seabirds known for their bright blue feet.","zh":"藍腳鰹鳥是以鮮藍色腳聞名的海鳥。"},{"en":"Tourists often notice blue-footed boobies because their feet look almost painted.","zh":"遊客常注意到藍腳鰹鳥，因為牠們的腳看起來幾乎像被塗上顏色。"},{"en":"Blue-footed boobies dive into the sea to catch fish.","zh":"藍腳鰹鳥會潛入海中捕魚。"},{"en":"Studying blue-footed boobies shows how animal behaviour supports survival.","zh":"研究藍腳鰹鳥可以顯示動物行為如何幫助生存。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":1},{"front":"a small group of seabirds","meaning":"一小類海鳥","examples":[{"en":"Boobies are a small group of seabirds native to tropical and subtropical oceans.","zh":"鰹鳥是一小類原產於熱帶及亞熱帶海洋的海鳥。"},{"en":"A small group of seabirds means a limited type of birds that live near the sea.","zh":"一小類海鳥指生活在海邊鳥類中的一個有限類別。"},{"en":"Gulls, penguins and boobies are different seabirds, but boobies are only a small group.","zh":"海鷗、企鵝和鰹鳥都是不同海鳥，但鰹鳥只是一小類。"},{"en":"A small group of seabirds may still have very special feeding habits.","zh":"一小類海鳥仍可能有很特別的覓食習性。"},{"en":"This phrase refers to classification, not the number of birds in one flock.","zh":"這個短語指分類，而不是一群鳥的數量。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":1},{"front":"seabirds","meaning":"海鳥","examples":[{"en":"Boobies are seabirds that live near tropical and subtropical oceans.","zh":"鰹鳥是生活在熱帶及亞熱帶海洋附近的海鳥。"},{"en":"Seabirds are birds that spend much of their lives near or over the sea.","zh":"海鳥是大部分時間在海邊或海面生活的鳥類。"},{"en":"Children may see seabirds flying around a harbour looking for fish.","zh":"孩子可能看見海鳥在港口附近飛翔尋找魚類。"},{"en":"Seabirds depend on healthy oceans because many of them eat fish.","zh":"海鳥依賴健康海洋，因為牠們很多都吃魚。"},{"en":"Unlike garden birds, seabirds are closely connected to marine environments.","zh":"與花園鳥類不同，海鳥與海洋環境密切相關。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":1},{"front":"be native to","meaning":"原產於；天然分佈於","examples":[{"en":"Boobies are native to tropical and subtropical oceans throughout the world.","zh":"鰹鳥原產於世界各地的熱帶及亞熱帶海洋。"},{"en":"To be native to a place means to come from there naturally.","zh":"be native to 某地指自然來自該地。"},{"en":"Pandas are native to China, so they are naturally found there.","zh":"熊貓原產於中國，所以牠們自然分佈在那裡。"},{"en":"Plants native to an area usually grow well in the local climate.","zh":"原產於某地區的植物通常適應當地氣候，生長良好。"},{"en":"A species may be native to one region but introduced to another by people.","zh":"一個物種可能原產於某地區，但被人類引入另一地區。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":1},{"front":"tropical and subtropical oceans","meaning":"熱帶及亞熱帶海洋","examples":[{"en":"Boobies are native to tropical and subtropical oceans.","zh":"鰹鳥原產於熱帶及亞熱帶海洋。"},{"en":"Tropical and subtropical oceans are warm ocean areas near or fairly near the equator.","zh":"熱帶及亞熱帶海洋是位於赤道附近或較接近赤道的溫暖海域。"},{"en":"Many colourful fish live in tropical and subtropical oceans.","zh":"許多色彩鮮艷的魚生活在熱帶及亞熱帶海洋中。"},{"en":"Birds depending on tropical and subtropical oceans may suffer if fish numbers fall.","zh":"依賴熱帶及亞熱帶海洋的鳥類，若魚類數量下降，可能會受影響。"},{"en":"These oceans are much warmer than polar seas.","zh":"這些海洋比極地海域溫暖得多。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":1},{"front":"throughout the world","meaning":"遍及世界各地","examples":[{"en":"Boobies live in warm oceans throughout the world.","zh":"鰹鳥生活在遍及世界各地的溫暖海洋中。"},{"en":"Throughout the world means in many places around the whole world.","zh":"throughout the world 指在全世界許多地方。"},{"en":"English is studied throughout the world for work and travel.","zh":"世界各地的人為了工作和旅遊而學習英語。"},{"en":"A disease can spread throughout the world if people travel before symptoms appear.","zh":"如果人們在症狀出現前旅行，疾病可能傳遍世界各地。"},{"en":"This phrase suggests wide distribution, not one small area.","zh":"這個短語表示分佈廣泛，而不是只限於一小片地區。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":1},{"front":"consist mainly of","meaning":"主要由……組成","examples":[{"en":"Their diet consists mainly of fish.","zh":"牠們的食物主要由魚類組成。"},{"en":"To consist mainly of something means to be made up mostly of that thing.","zh":"consist mainly of something 指主要由某物組成。"},{"en":"A student’s lunch may consist mainly of rice if rice is the largest part.","zh":"如果米飯是午餐最大部分，學生的午餐可能主要由米飯組成。"},{"en":"A diet that consists mainly of fast food may lack fruit and vegetables.","zh":"主要由快餐組成的飲食可能缺乏水果和蔬菜。"},{"en":"The phrase shows the main part, not every single part.","zh":"這個短語表示主要部分，而不是每一個部分。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":1},{"front":"diet","meaning":"飲食；食物","examples":[{"en":"The booby’s diet consists mainly of fish.","zh":"鰹鳥的食物主要由魚類組成。"},{"en":"Diet means the food that a person or animal usually eats.","zh":"diet 指人或動物通常吃的食物。"},{"en":"A doctor may ask about a patient’s diet to understand their health.","zh":"醫生可能詢問病人的飲食，以了解其健康狀況。"},{"en":"A poor diet can lead to tiredness and other health problems.","zh":"不良飲食可能導致疲倦和其他健康問題。"},{"en":"An animal’s diet often depends on what food is available nearby.","zh":"動物的食物通常取決於附近有甚麼食物。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":1},{"front":"specialised fish-eaters","meaning":"專門吃魚的動物","examples":[{"en":"Boobies are specialised fish-eaters.","zh":"鰹鳥是專門吃魚的動物。"},{"en":"Specialised fish-eaters are animals especially adapted to catch and eat fish.","zh":"專門吃魚的動物是特別適應捕捉和進食魚類的動物。"},{"en":"A bird with sharp vision and strong diving skills may be a specialised fish-eater.","zh":"具有敏銳視力和強大潛水能力的鳥類，可能是專門吃魚的動物。"},{"en":"Specialised fish-eaters may struggle if fish become scarce.","zh":"如果魚類變得稀少，專門吃魚的動物可能難以生存。"},{"en":"This phrase shows that fish are a main part of survival, not occasional food.","zh":"這個短語表示魚類是生存的主要食物，而不是偶爾的食物。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":1},{"front":"feed on","meaning":"以……為食","examples":[{"en":"Boobies feed on small schooling fish.","zh":"鰹鳥以小型群游魚類為食。"},{"en":"To feed on something means to eat it as regular food.","zh":"feed on something 指以某物作為常規食物。"},{"en":"Frogs feed on insects, while rabbits feed on grass and leaves.","zh":"青蛙以昆蟲為食，而兔子以草和葉為食。"},{"en":"Animals that feed on only one food may suffer when that food disappears.","zh":"只以一種食物為食的動物，當該食物消失時可能會受苦。"},{"en":"This phrase is often used to describe what animals naturally eat.","zh":"這個短語常用來描述動物自然吃甚麼。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":1},{"front":"small schooling fish","meaning":"小型群游魚類","examples":[{"en":"Boobies feed on small schooling fish such as sardines and anchovies.","zh":"鰹鳥以沙甸魚和鯷魚等小型群游魚類為食。"},{"en":"Small schooling fish are small fish that swim together in large groups.","zh":"小型群游魚類是會成大群一起游動的小魚。"},{"en":"Fishermen often look for small schooling fish because a whole group may appear at once.","zh":"漁民常尋找小型群游魚類，因為整個魚群可能一次出現。"},{"en":"When small schooling fish gather near the surface, seabirds can find food more easily.","zh":"當小型群游魚類聚集在水面附近，海鳥較容易找到食物。"},{"en":"Sardines are a clear example of small schooling fish.","zh":"沙甸魚是小型群游魚類的一個清楚例子。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":2},{"front":"sardines","meaning":"沙甸魚","examples":[{"en":"Sardines are one of the small fish eaten by boobies.","zh":"沙甸魚是鰹鳥進食的小魚之一。"},{"en":"Sardines are small oily fish that often swim in large groups.","zh":"沙甸魚是常成大群游動的小型油性魚類。"},{"en":"People may buy sardines in tins for a quick meal.","zh":"人們可能購買罐裝沙甸魚作為快捷一餐。"},{"en":"When sardines gather near the surface, birds and larger fish may hunt them.","zh":"當沙甸魚聚集在水面附近，鳥類和較大型魚類可能會捕食牠們。"},{"en":"Sardines are small, but they support many marine food chains.","zh":"沙甸魚雖小，卻支撐許多海洋食物鏈。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":2},{"front":"anchovies","meaning":"鯷魚","examples":[{"en":"Anchovies are small fish that boobies feed on.","zh":"鯷魚是鰹鳥捕食的小魚。"},{"en":"Anchovies are tiny fish often eaten by seabirds, larger fish and people.","zh":"鯷魚是常被海鳥、較大型魚類和人類食用的小魚。"},{"en":"Some restaurants use anchovies on pizza or in salty sauces.","zh":"有些餐廳會把鯷魚放在薄餅上，或用於鹹味醬汁中。"},{"en":"If anchovy numbers fall, animals that feed on them may struggle.","zh":"如果鯷魚數量下降，以牠們為食的動物可能難以覓食。"},{"en":"Anchovies are small prey that help support marine food chains.","zh":"鯷魚是支撐海洋食物鏈的小型獵物。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":2},{"front":"mackerel","meaning":"鯖魚","examples":[{"en":"Mackerel are included in the booby’s diet.","zh":"鯖魚包括在鰹鳥的食物之中。"},{"en":"Mackerel are fast-swimming sea fish eaten by humans and marine animals.","zh":"鯖魚是游得很快的海魚，會被人類和海洋動物食用。"},{"en":"A family may grill mackerel for dinner because it is rich in flavour.","zh":"家庭可能會烤鯖魚作晚餐，因為它味道濃郁。"},{"en":"Predators may follow mackerel when they move in groups.","zh":"當鯖魚成群移動時，捕食者可能會跟隨牠們。"},{"en":"Mackerel are larger than many tiny schooling fish, but they can still become prey.","zh":"鯖魚比許多小型群游魚類大，但仍可能成為獵物。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":2},{"front":"flying fish","meaning":"飛魚","examples":[{"en":"Flying fish are among the prey eaten by boobies.","zh":"飛魚是鰹鳥捕食的獵物之一。"},{"en":"Flying fish are fish that can glide above the water for a short distance.","zh":"飛魚是能夠短距離滑翔離開水面的魚類。"},{"en":"Tourists on a boat may see flying fish leap out of the sea.","zh":"船上的遊客可能會看見飛魚跳出海面。"},{"en":"Flying fish may glide to escape predators, but seabirds can still catch them.","zh":"飛魚可能透過滑翔逃避捕食者，但海鳥仍能捕捉牠們。"},{"en":"Their movement makes flying fish different from ordinary fish.","zh":"飛魚的移動方式令牠們不同於普通魚類。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":2},{"front":"prey","meaning":"獵物","examples":[{"en":"Boobies dive into the water when their prey is in sight.","zh":"當獵物在視線範圍內，鰹鳥會潛入水中。"},{"en":"Prey means an animal that is hunted and eaten by another animal.","zh":"prey 指被另一種動物捕獵和食用的動物。"},{"en":"A mouse may become prey for an owl at night.","zh":"老鼠在夜間可能成為貓頭鷹的獵物。"},{"en":"When prey becomes scarce, predators may travel farther to find food.","zh":"當獵物變得稀少，捕食者可能要走得更遠才能找到食物。"},{"en":"In this passage, fish are the prey and boobies are the hunters.","zh":"在這篇文章中，魚是獵物，而鰹鳥是獵食者。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":2},{"front":"in sight","meaning":"在視線範圍內","examples":[{"en":"When their prey is in sight, boobies fold their wings back.","zh":"當獵物在視線範圍內，鰹鳥會把翅膀向後收起。"},{"en":"In sight means visible or able to be seen.","zh":"in sight 指看得見或在視線之內。"},{"en":"A bus is in sight when you can see it coming down the road.","zh":"當你看見巴士沿路駛來，巴士就在視線範圍內。"},{"en":"When land is finally in sight, sailors know they are near safety.","zh":"當陸地終於在視線範圍內，水手知道自己接近安全。"},{"en":"If danger is not in sight, people may relax too early.","zh":"如果危險不在視線範圍內，人們可能會太早放鬆。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":2},{"front":"fold their long wings back","meaning":"把長翼向後收起","examples":[{"en":"Boobies fold their long wings back before plunging into the water.","zh":"鰹鳥在猛衝入水前會把長翼向後收起。"},{"en":"To fold their long wings back means to pull the wings close to the body before diving.","zh":"fold their long wings back 指在潛水前把翅膀拉近身體。"},{"en":"A diver keeps his arms close, just as birds fold their long wings back to reduce resistance.","zh":"跳水員會把雙臂貼近身體，就像鳥類把長翼向後收起以減少阻力。"},{"en":"Boobies fold their long wings back so they can enter the water smoothly.","zh":"鰹鳥把長翼向後收起，使自己能順暢入水。"},{"en":"This action protects the wings and makes the dive cleaner.","zh":"這個動作保護翅膀，並令潛水動作更乾淨利落。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":2},{"front":"streamlined bodies","meaning":"流線型身體","examples":[{"en":"Boobies have streamlined bodies that help them dive cleanly into the water.","zh":"鰹鳥有流線型身體，幫助牠們乾淨利落地潛入水中。"},{"en":"Streamlined bodies are smooth, narrow shapes that move easily through air or water.","zh":"流線型身體是平滑而較窄、能輕易穿過空氣或水的形狀。"},{"en":"Fast trains and racing cars often have streamlined bodies to reduce resistance.","zh":"高速列車和賽車通常有流線型車身，以減少阻力。"},{"en":"Streamlined bodies help boobies hit the water without much splash.","zh":"流線型身體幫助鰹鳥入水時不濺起太多水花。"},{"en":"This shape is useful when speed and smooth movement are important.","zh":"當速度和順暢移動很重要時，這種形狀十分有用。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":2},{"front":"plunge into","meaning":"猛衝入；扎入","examples":[{"en":"Boobies plunge into the water from high above.","zh":"鰹鳥從高空猛衝入水中。"},{"en":"To plunge into something means to fall or dive into it suddenly and with force.","zh":"plunge into something 指突然並有力地掉入或潛入某物之中。"},{"en":"A child may plunge into a swimming pool on a hot day.","zh":"小孩可能在炎熱日子猛地跳入泳池。"},{"en":"If a phone plunges into water, it may stop working.","zh":"如果手機掉入水中，可能會停止運作。"},{"en":"The phrase often shows a fast and powerful movement downward.","zh":"這個短語常表示快速而有力的向下動作。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":2},{"front":"from as high as","meaning":"從高達……的地方","examples":[{"en":"Boobies can plunge into the water from as high as 80 feet.","zh":"鰹鳥可以從高達80英尺的地方猛衝入水中。"},{"en":"From as high as means from a height that may reach that number.","zh":"from as high as 指從可能達到某一高度的地方。"},{"en":"Some divers jump from as high as ten metres in competitions.","zh":"有些跳水員在比賽中會從高達十米的地方跳下。"},{"en":"Falling from as high as a second-floor window can cause serious injury.","zh":"從高達二樓窗戶的地方跌下，可能造成嚴重受傷。"},{"en":"The phrase emphasises that the height is surprisingly great.","zh":"這個短語強調高度大得令人意外。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":3},{"front":"barely make a splash","meaning":"幾乎沒有濺起水花","examples":[{"en":"They are so streamlined that they barely make a splash.","zh":"牠們如此流線型，以致幾乎沒有濺起水花。"},{"en":"To barely make a splash means to enter water with very little water thrown up.","zh":"barely make a splash 指入水時幾乎沒有水花濺起。"},{"en":"A skilled diver may barely make a splash when entering the pool.","zh":"熟練的跳水員入池時可能幾乎沒有濺起水花。"},{"en":"If an object barely makes a splash, it usually enters the water smoothly.","zh":"如果一件物件幾乎沒有濺起水花，通常表示它順暢入水。"},{"en":"The phrase can also suggest that something happens quietly with little visible effect.","zh":"這個短語也可表示某事安靜發生，沒有太明顯效果。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":3},{"front":"travel in parties of","meaning":"以約……一組行動","examples":[{"en":"Boobies travel in parties of about 12.","zh":"鰹鳥以約12隻一組行動。"},{"en":"To travel in parties of a number means to move around in groups of that size.","zh":"travel in parties of 某數目指以該數量左右的群體一起移動。"},{"en":"Tourists may travel in parties of four to share hotel costs.","zh":"遊客可能以四人一組旅行，以分擔酒店費用。"},{"en":"Animals may travel in parties of several individuals to find food or stay safe.","zh":"動物可能以幾隻一組行動，以尋找食物或保持安全。"},{"en":"The phrase focuses on group size rather than the journey itself.","zh":"這個短語著重群體大小，而不是旅程本身。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":3},{"front":"areas of water","meaning":"水域","examples":[{"en":"They travel to areas of water with large schools of fish.","zh":"牠們會前往有大群魚的水域。"},{"en":"Areas of water are parts of the sea, lake or river.","zh":"areas of water 指海洋、湖泊或河流中的某些部分。"},{"en":"Fishermen may choose areas of water where fish are often found.","zh":"漁民可能選擇常有魚出現的水域。"},{"en":"Some areas of water are protected because rare animals live there.","zh":"有些水域受到保護，因為稀有動物在那裡生活。"},{"en":"The phrase can describe different parts of a larger body of water.","zh":"這個短語可以描述一片水體中的不同部分。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":3},{"front":"large schools of small fish","meaning":"大群小魚","examples":[{"en":"Boobies hunt in areas with large schools of small fish.","zh":"鰹鳥在有大群小魚的水域捕獵。"},{"en":"Large schools of small fish are big groups of small fish swimming together.","zh":"large schools of small fish 指一起游動的大群小魚。"},{"en":"A fisherman may notice large schools of small fish near the surface.","zh":"漁民可能注意到水面附近有大群小魚。"},{"en":"Large schools of small fish attract seabirds because they provide a rich food source.","zh":"大群小魚會吸引海鳥，因為牠們提供豐富食物來源。"},{"en":"The phrase shows both the large group and the small size of each fish.","zh":"這個短語同時顯示群體很大，而每條魚很小。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":3},{"front":"lead bird","meaning":"領頭鳥","examples":[{"en":"The lead bird signals the rest of the group when it sees fish.","zh":"領頭鳥看見魚時會向其餘同伴發出信號。"},{"en":"The lead bird is the bird at the front or the one that guides the others.","zh":"lead bird 指在前方或引導其他鳥的鳥。"},{"en":"In a flying group, the lead bird may choose the direction.","zh":"在飛行群體中，領頭鳥可能選擇方向。"},{"en":"If the lead bird finds food, the rest of the group may follow quickly.","zh":"如果領頭鳥找到食物，其餘同伴可能會迅速跟隨。"},{"en":"The lead bird helps coordinate group movement.","zh":"領頭鳥有助協調群體行動。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":3},{"front":"fish shoal","meaning":"魚群","examples":[{"en":"The lead bird sees a fish shoal in the water.","zh":"領頭鳥在水中看見魚群。"},{"en":"A fish shoal is a group of fish swimming close together.","zh":"fish shoal 指一起近距離游動的一群魚。"},{"en":"Children looking from a pier may see a fish shoal moving like a dark cloud.","zh":"孩子從碼頭望下去，可能看見魚群像一片深色雲般移動。"},{"en":"When a fish shoal stays near the surface, birds can catch fish more easily.","zh":"當魚群留在水面附近，鳥類較容易捕魚。"},{"en":"A fish shoal can protect individual fish, but it can also attract predators.","zh":"魚群可以保護個別魚，但也可能吸引捕食者。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":3},{"front":"signal the rest of the group","meaning":"向其餘同伴發出信號","examples":[{"en":"The lead bird signals the rest of the group before they dive.","zh":"領頭鳥在牠們潛水前向其餘同伴發出信號。"},{"en":"To signal the rest of the group means to give a sign so the others know what to do.","zh":"signal the rest of the group 指發出訊號，讓其他成員知道該做甚麼。"},{"en":"A teacher may raise a hand to signal the rest of the group to be quiet.","zh":"老師可能舉手向其餘同學發出安靜的信號。"},{"en":"Clear signals help the rest of the group act together.","zh":"清楚信號幫助其餘成員一起行動。"},{"en":"In the passage, the signal tells the other birds when to dive.","zh":"在文章中，這個信號告訴其他鳥何時潛水。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":3},{"front":"dive together","meaning":"一起潛入水中","examples":[{"en":"The birds dive together after the lead bird gives a signal.","zh":"領頭鳥發出信號後，鳥群一起潛入水中。"},{"en":"To dive together means to enter the water at the same time as a group.","zh":"dive together 指作為一個群體同時入水。"},{"en":"Swimmers may dive together at the start of a race.","zh":"游泳選手可能在比賽開始時一起跳入水中。"},{"en":"Birds dive together so they can attack a fish shoal at the same moment.","zh":"鳥類一起潛入水中，以便同一時間攻向魚群。"},{"en":"This phrase shows coordinated action, not random individual movement.","zh":"這個短語顯示協調行動，而不是隨機個別行動。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":3},{"front":"surprisingly","meaning":"令人意外的是","examples":[{"en":"Surprisingly, individuals do not eat with the hunting group.","zh":"令人意外的是，個別成員不會與狩獵群體一起進食。"},{"en":"Surprisingly means that something is unexpected.","zh":"surprisingly 指某事出乎意料。"},{"en":"Surprisingly, the quiet student gave the best speech in class.","zh":"令人意外的是，那位安靜的學生在班上作出最好的演講。"},{"en":"A result is surprising when it goes against what people expected.","zh":"當結果違反人們預期時，就可以說是 surprising。"},{"en":"In this passage, it is surprising because the birds hunt together but eat alone.","zh":"在文章中，令人意外之處在於牠們一起狩獵，卻獨自進食。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":3},{"front":"individuals","meaning":"個別成員；個體","examples":[{"en":"Individuals prefer to eat on their own.","zh":"個別成員較喜歡獨自進食。"},{"en":"Individuals are single members of a group, considered separately.","zh":"individuals 指群體中被分開看待的單一成員。"},{"en":"In a class, individuals may learn at different speeds.","zh":"在班上，個別學生可能以不同速度學習。"},{"en":"Looking at individuals helps us see differences hidden inside a group average.","zh":"觀察個別成員有助我們看見群體平均值中隱藏的差異。"},{"en":"The word contrasts one member with the whole group.","zh":"這個詞把單一成員與整個群體作對比。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":4},{"front":"hunting group","meaning":"狩獵群體","examples":[{"en":"Individuals do not eat with the hunting group.","zh":"個別成員不會與狩獵群體一起進食。"},{"en":"A hunting group is a group of animals that search for and catch food together.","zh":"hunting group 指一起尋找並捕捉食物的一群動物。"},{"en":"Wolves may form a hunting group to catch larger prey.","zh":"狼可能組成狩獵群體，以捕捉較大型獵物。"},{"en":"A hunting group can increase success because several animals work together.","zh":"狩獵群體能提高成功機會，因為多隻動物一起合作。"},{"en":"In the booby passage, the birds hunt as a group but feed separately.","zh":"在鰹鳥文章中，鳥類以群體狩獵，但分開進食。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":4},{"front":"prefer to","meaning":"較喜歡","examples":[{"en":"Boobies prefer to eat on their own.","zh":"鰹鳥較喜歡獨自進食。"},{"en":"To prefer to do something means to like doing it more than another choice.","zh":"prefer to do something 指比起另一個選擇更喜歡做某事。"},{"en":"Some students prefer to study in the morning rather than at night.","zh":"有些學生較喜歡在早上溫習，而不是晚上。"},{"en":"People may prefer to cook at home because it saves money.","zh":"人們可能較喜歡在家煮飯，因為可以省錢。"},{"en":"The phrase shows a choice or stronger liking.","zh":"這個短語表示選擇或較強的喜好。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":4},{"front":"on their own","meaning":"獨自；單獨","examples":[{"en":"Boobies usually eat on their own.","zh":"鰹鳥通常獨自進食。"},{"en":"On their own means alone or without help from others.","zh":"on their own 指獨自或不靠他人幫助。"},{"en":"A child may learn to tie his shoes on his own.","zh":"小孩可能學會自己綁鞋帶。"},{"en":"Working on their own can help students become more independent.","zh":"獨自完成工作可以幫助學生變得更獨立。"},{"en":"The phrase can describe doing something separately from a group.","zh":"這個短語可以描述某事與群體分開進行。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":4},{"front":"in the early morning","meaning":"在清晨","examples":[{"en":"They usually eat on their own in the early morning.","zh":"牠們通常在清晨獨自進食。"},{"en":"In the early morning means during the first part of the morning, soon after sunrise.","zh":"in the early morning 指早晨最初的時間，通常是日出後不久。"},{"en":"Many runners exercise in the early morning before the streets become busy.","zh":"許多跑步者在清晨街道變得繁忙前運動。"},{"en":"Birds may feed in the early morning because temperatures are cooler.","zh":"鳥類可能在清晨覓食，因為氣溫較涼。"},{"en":"This phrase tells us when an action usually happens.","zh":"這個短語告訴我們某個行動通常何時發生。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":4},{"front":"late afternoon","meaning":"傍晚時分","examples":[{"en":"Boobies often feed in the early morning or late afternoon.","zh":"鰹鳥常在清晨或傍晚時分覓食。"},{"en":"Late afternoon is the later part of the afternoon, before evening begins.","zh":"late afternoon 指下午較後的時間，即傍晚開始前。"},{"en":"Students may feel tired in the late afternoon after a full day of lessons.","zh":"學生上了一整天課後，可能在傍晚時分感到疲倦。"},{"en":"Some animals become active in the late afternoon when the heat is less strong.","zh":"有些動物會在傍晚時分變得活躍，因為熱力沒有那麼強。"},{"en":"The phrase is useful for describing daily routines and natural behaviour.","zh":"這個短語適合描述日常規律和自然行為。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":4},{"front":"three varieties","meaning":"三個品種","examples":[{"en":"There are three varieties of boobies on the Galapagos.","zh":"加拉帕戈斯群島上有三個鰹鳥品種。"},{"en":"Three varieties means three types within the same general group.","zh":"three varieties 指同一大類之下的三種類型。"},{"en":"A shop may sell three varieties of apples: red, green and yellow.","zh":"商店可能售賣三個蘋果品種：紅色、綠色和黃色。"},{"en":"Identifying three varieties helps students compare their differences clearly.","zh":"辨認三個品種有助學生清楚比較它們的差異。"},{"en":"The phrase suggests related types, not completely unrelated things.","zh":"這個短語表示相關類型，而不是完全無關的事物。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":4},{"front":"the Galapagos","meaning":"加拉帕戈斯群島","examples":[{"en":"Three varieties of boobies live on the Galapagos.","zh":"三個鰹鳥品種生活在加拉帕戈斯群島。"},{"en":"The Galapagos are islands in the Pacific Ocean famous for unusual wildlife.","zh":"加拉帕戈斯群島是太平洋中的島嶼，以獨特野生動物聞名。"},{"en":"Scientists study animals on the Galapagos because many species there are distinctive.","zh":"科學家研究加拉帕戈斯群島上的動物，因為那裡許多物種都很獨特。"},{"en":"Tourism on the Galapagos must be managed carefully to protect fragile ecosystems.","zh":"加拉帕戈斯群島的旅遊必須小心管理，以保護脆弱生態系統。"},{"en":"In this passage, the Galapagos provide the setting for comparing different boobies.","zh":"在這篇文章中，加拉帕戈斯群島是比較不同鰹鳥的背景。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":4},{"front":"red-footed booby","meaning":"紅腳鰹鳥","examples":[{"en":"The red-footed booby fishes farthest from shore.","zh":"紅腳鰹鳥在離岸最遠的地方捕魚。"},{"en":"The red-footed booby is a type of booby recognised by its red feet.","zh":"紅腳鰹鳥是一種可透過紅色腳辨認的鰹鳥。"},{"en":"A birdwatcher may identify a red-footed booby by looking at its feet.","zh":"觀鳥者可能透過觀察腳部來辨認紅腳鰹鳥。"},{"en":"Because the red-footed booby fishes far from shore, it uses different feeding areas.","zh":"由於紅腳鰹鳥離岸較遠捕魚，牠會使用不同的覓食區。"},{"en":"Its name works like a simple visual clue.","zh":"牠的名稱就像一個簡單的視覺提示。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":4},{"front":"masked booby","meaning":"面罩鰹鳥","examples":[{"en":"The masked booby has an annual mating cycle.","zh":"面罩鰹鳥有一年一度的交配周期。"},{"en":"The masked booby is a type of booby with dark markings around its face.","zh":"面罩鰹鳥是一種臉部周圍有深色標記的鰹鳥。"},{"en":"Students may remember the masked booby by imagining a bird wearing a mask.","zh":"學生可以想像一隻戴著面罩的鳥來記住面罩鰹鳥。"},{"en":"Its mating cycle follows a yearly pattern.","zh":"牠的交配周期跟隨一年一次的模式。"},{"en":"The masked booby shows that related animals can still behave differently.","zh":"面罩鰹鳥顯示，相關動物仍可以有不同的行為。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":4},{"front":"members of the same family","meaning":"同一科的成員","examples":[{"en":"The three varieties are members of the same family.","zh":"這三個品種是同一科的成員。"},{"en":"Members of the same family are related types that belong to the same biological group.","zh":"members of the same family 指屬於同一生物分類群的相關類型。"},{"en":"Lions and domestic cats are members of the same wider family.","zh":"獅子和家貓屬於同一較大科的成員。"},{"en":"Being members of the same family may explain why animals share some features.","zh":"屬於同一科的成員，可能解釋為何動物有一些共同特徵。"},{"en":"Members of the same family can still differ in size, colour and behaviour.","zh":"同一科的成員仍可能在大小、顏色和行為上不同。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":5},{"front":"differ not only in appearance but also in behaviour","meaning":"不但外貌不同，行為也不同","examples":[{"en":"The birds differ not only in appearance but also in behaviour.","zh":"這些鳥不但外貌不同，行為也不同。"},{"en":"This phrase means they are different in how they look and how they act.","zh":"這個短語指牠們在外觀和行動方式上都有差異。"},{"en":"Two dog breeds may differ not only in appearance but also in behaviour.","zh":"兩個狗品種可能不但外貌不同，行為也不同。"},{"en":"Scientists study both body features and habits when animals differ in these ways.","zh":"當動物有這些差異，科學家會同時研究身體特徵和習性。"},{"en":"The phrase reminds us not to judge difference only by looks.","zh":"這個短語提醒我們不要只憑外貌判斷差異。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":5},{"front":"appearance","meaning":"外貌","examples":[{"en":"The three varieties of boobies differ in appearance.","zh":"這三個鰹鳥品種在外貌上不同。"},{"en":"Appearance means the way someone or something looks.","zh":"appearance 指人或物看起來的樣子。"},{"en":"A school uniform changes a student’s appearance but not their personality.","zh":"校服會改變學生的外貌，但不會改變性格。"},{"en":"Animals may use appearance, such as colour or shape, to attract mates.","zh":"動物可能利用顏色或形狀等外貌特徵吸引伴侶。"},{"en":"Appearance is about what can be seen from the outside.","zh":"appearance 關乎從外面看得見的特徵。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":5},{"front":"behaviour","meaning":"行為","examples":[{"en":"The boobies differ in appearance and behaviour.","zh":"這些鰹鳥在外貌和行為上不同。"},{"en":"Behaviour means the way a person or animal acts.","zh":"behaviour 指人或動物的行動方式。"},{"en":"A child’s behaviour may change when they feel tired or nervous.","zh":"孩子感到疲倦或緊張時，行為可能會改變。"},{"en":"Animal behaviour helps scientists understand feeding, mating and survival.","zh":"動物行為有助科學家理解覓食、交配和生存。"},{"en":"Behaviour is about actions, not just physical features.","zh":"behaviour 關乎行動，而不只是身體特徵。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":5},{"front":"mate throughout the year","meaning":"全年交配","examples":[{"en":"Blue-footed and red-footed boobies mate throughout the year.","zh":"藍腳鰹鳥和紅腳鰹鳥全年交配。"},{"en":"To mate throughout the year means to reproduce or pair for breeding at many times during the year.","zh":"mate throughout the year 指一年中許多時間都會交配或配對繁殖。"},{"en":"Some animals mate only in spring, while others mate throughout the year.","zh":"有些動物只在春天交配，而另一些則全年交配。"},{"en":"If food is available all year, animals may be able to mate throughout the year.","zh":"如果全年都有食物，動物可能較能全年交配。"},{"en":"The phrase shows there is no single short breeding season.","zh":"這個短語表示沒有單一而短暫的繁殖季節。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":5},{"front":"annual mating cycle","meaning":"一年一度的交配周期","examples":[{"en":"The masked booby has an annual mating cycle.","zh":"面罩鰹鳥有一年一度的交配周期。"},{"en":"An annual mating cycle is a breeding pattern that happens once every year.","zh":"annual mating cycle 指每年發生一次的繁殖模式。"},{"en":"Some birds follow an annual mating cycle linked to seasons and food supply.","zh":"有些鳥類跟隨與季節和食物供應有關的一年一度交配周期。"},{"en":"An annual mating cycle helps animals lay eggs when conditions are suitable.","zh":"一年一度的交配周期有助動物在條件合適時產卵。"},{"en":"This phrase contrasts with mating throughout the year.","zh":"這個短語與全年交配形成對比。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":5},{"front":"differ from island to island","meaning":"因島嶼而異","examples":[{"en":"The masked booby’s mating cycle differs from island to island.","zh":"面罩鰹鳥的交配周期因島嶼而異。"},{"en":"To differ from island to island means to be different on each island.","zh":"differ from island to island 指在不同島嶼上有所不同。"},{"en":"Local food may differ from island to island because each place has different crops.","zh":"本地食物可能因島嶼而異，因為每個地方有不同作物。"},{"en":"If weather differs from island to island, animals may breed at different times.","zh":"如果天氣因島嶼而異，動物可能在不同時間繁殖。"},{"en":"The phrase shows that location can affect behaviour.","zh":"這個短語顯示地點可以影響行為。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":5},{"front":"catch fish in a similar manner","meaning":"以相似方式捕魚","examples":[{"en":"All three varieties catch fish in a similar manner.","zh":"三個品種都以相似方式捕魚。"},{"en":"To catch fish in a similar manner means to use almost the same method to get fish.","zh":"catch fish in a similar manner 指用差不多相同的方法捕魚。"},{"en":"Two fishermen catch fish in a similar manner if both use nets from small boats.","zh":"如果兩名漁民都從小船上使用漁網，他們就是以相似方式捕魚。"},{"en":"Animals may look different but catch fish in a similar manner because they hunt the same prey.","zh":"動物外貌可能不同，但因為捕獵相同獵物，仍會以相似方式捕魚。"},{"en":"The phrase focuses on method rather than appearance.","zh":"這個短語著重方法，而不是外貌。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":5},{"front":"close to shore","meaning":"接近岸邊","examples":[{"en":"The blue-footed booby does its fishing close to shore.","zh":"藍腳鰹鳥在接近岸邊的地方捕魚。"},{"en":"Close to shore means near the land beside the sea.","zh":"close to shore 指靠近海邊陸地。"},{"en":"Children may swim close to shore because the water is safer there.","zh":"孩子可能在接近岸邊的地方游泳，因為那裡較安全。"},{"en":"Birds that fish close to shore do not need to travel far out to sea.","zh":"在接近岸邊捕魚的鳥類不需要飛到很遠的海上。"},{"en":"The phrase contrasts with fishing far from land.","zh":"這個短語與遠離陸地捕魚形成對比。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":5},{"front":"slightly farther out","meaning":"稍為離岸較遠","examples":[{"en":"The masked booby goes slightly farther out to fish.","zh":"面罩鰹鳥會稍為離岸較遠去捕魚。"},{"en":"Slightly farther out means a little farther away from the shore or starting point.","zh":"slightly farther out 指比岸邊或起點遠一點。"},{"en":"A swimmer may move slightly farther out but still stay near the beach.","zh":"游泳者可能稍為游遠一點，但仍留在海灘附近。"},{"en":"If food is not near the coast, birds may go slightly farther out to find it.","zh":"如果食物不在海岸附近，鳥類可能稍為離岸較遠去尋找。"},{"en":"The word slightly shows the difference is small, not extreme.","zh":"slightly 表示差異很小，而不是極端。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":5},{"front":"at the farthest distances from shore","meaning":"在離岸最遠的地方","examples":[{"en":"The red-footed booby fishes at the farthest distances from shore.","zh":"紅腳鰹鳥在離岸最遠的地方捕魚。"},{"en":"At the farthest distances from shore means the greatest distance away from land beside the sea.","zh":"at the farthest distances from shore 指離海邊陸地最遠的距離。"},{"en":"Deep-sea boats travel at the farthest distances from shore compared with small boats.","zh":"與小船相比，深海船隻會航行到離岸最遠的地方。"},{"en":"Birds that feed at the farthest distances from shore may need more energy.","zh":"在離岸最遠處覓食的鳥類，可能需要更多能量。"},{"en":"This phrase marks the extreme end of a comparison.","zh":"這個短語表示比較中的最遠一端。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":6},{"front":"the origin of","meaning":"……的來源","examples":[{"en":"The origin of the name “booby” is uncertain.","zh":"「booby」這個名稱的來源並不確定。"},{"en":"The origin of something is where it began or came from.","zh":"the origin of something 指某事物開始或來自的地方。"},{"en":"The origin of a family recipe may be a grandmother’s village.","zh":"一道家庭食譜的來源可能是祖母的村莊。"},{"en":"Knowing the origin of a word can help students understand its meaning.","zh":"了解一個詞的來源可以幫助學生理解其意思。"},{"en":"This phrase is often used when explaining history, language or traditions.","zh":"這個短語常用於解釋歷史、語言或傳統。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":6},{"front":"be uncertain","meaning":"不確定","examples":[{"en":"The origin of the name “booby” is uncertain.","zh":"「booby」這個名稱的來源並不確定。"},{"en":"To be uncertain means not to be known clearly or not decided.","zh":"be uncertain 指不清楚知道或尚未決定。"},{"en":"The date of the school trip is uncertain because the weather may change.","zh":"學校旅行日期仍不確定，因為天氣可能改變。"},{"en":"When evidence is weak, the answer may remain uncertain.","zh":"當證據不足，答案可能仍然不確定。"},{"en":"This phrase shows that people do not have complete confidence about something.","zh":"這個短語表示人們對某事沒有完全把握。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":6},{"front":"come from","meaning":"來自","examples":[{"en":"Some believe the name comes from the Spanish word bobo.","zh":"有些人認為這個名稱來自西班牙語詞 bobo。"},{"en":"To come from something means to have it as a source or origin.","zh":"come from something 指以某物作為來源或起源。"},{"en":"Many English words come from Latin, French or other languages.","zh":"許多英文字來自拉丁語、法語或其他語言。"},{"en":"A smell may come from the kitchen when someone is cooking.","zh":"當有人煮飯時，氣味可能來自廚房。"},{"en":"In word history, come from explains where a term began.","zh":"在詞源歷史中，come from 解釋一個詞從哪裡開始。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":6},{"front":"Spanish word","meaning":"西班牙語詞","examples":[{"en":"The name may come from the Spanish word bobo.","zh":"這個名稱可能來自西班牙語詞 bobo。"},{"en":"A Spanish word is a word from the Spanish language.","zh":"Spanish word 指來自西班牙語的詞語。"},{"en":"The Spanish word amigo means friend.","zh":"西班牙語詞 amigo 的意思是朋友。"},{"en":"English sometimes borrows a Spanish word when people meet new foods or ideas.","zh":"當人們接觸新食物或概念時，英語有時會借用西班牙語詞。"},{"en":"Identifying a Spanish word can explain why a name sounds the way it does.","zh":"辨認西班牙語詞可以解釋一個名稱為何聽起來如此。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":6},{"front":"meaning stupid or clown","meaning":"意思是「愚蠢」或「小丑」","examples":[{"en":"The Spanish word bobo means “stupid” or “clown”.","zh":"西班牙語詞 bobo 的意思是「愚蠢」或「小丑」。"},{"en":"Meaning stupid or clown explains what the word bobo refers to in English.","zh":"meaning stupid or clown 解釋 bobo 這個詞在英語中指甚麼。"},{"en":"A nickname meaning stupid or clown may sound unkind today.","zh":"一個意思是「愚蠢」或「小丑」的綽號，今天聽起來可能不太友善。"},{"en":"If a bird looked clumsy, people might give it a name meaning stupid or clown.","zh":"如果一隻鳥看起來笨拙，人們可能會給牠一個意思是「愚蠢」或「小丑」的名稱。"},{"en":"The phrase helps explain the possible reason behind the bird’s name.","zh":"這個短語有助解釋該鳥名稱背後的可能原因。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":6},{"front":"be inspired by","meaning":"受……啟發","examples":[{"en":"The name was probably inspired by the bird’s clumsiness on land.","zh":"這個名稱很可能受這種鳥在陸地上的笨拙啟發。"},{"en":"To be inspired by something means to be influenced by it when creating a name, idea or action.","zh":"be inspired by something 指在創造名稱、想法或行動時受某事影響。"},{"en":"A painting may be inspired by a childhood memory.","zh":"一幅畫可能受童年回憶啟發。"},{"en":"A school project can be inspired by a real problem in the community.","zh":"學校專題可以受社區中的真實問題啟發。"},{"en":"In this passage, the bird’s awkward movement may have influenced its name.","zh":"在這篇文章中，這種鳥笨拙的移動方式可能影響了牠的名稱。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":6},{"front":"clumsiness on land","meaning":"在陸地上的笨拙","examples":[{"en":"The bird’s clumsiness on land may have inspired its name.","zh":"這種鳥在陸地上的笨拙可能啟發了牠的名稱。"},{"en":"Clumsiness on land means moving awkwardly or unsteadily while walking on the ground.","zh":"clumsiness on land 指在地面行走時動作笨拙或不穩。"},{"en":"A seal shows clumsiness on land but moves gracefully in water.","zh":"海豹在陸地上顯得笨拙，但在水中移動優雅。"},{"en":"Clumsiness on land can make an animal look slow or foolish to humans.","zh":"在陸地上的笨拙可能令動物在人類眼中顯得遲緩或愚笨。"},{"en":"This phrase contrasts awkward land movement with skill in another environment.","zh":"這個短語把陸地上的笨拙與另一環境中的熟練形成對比。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":6},{"front":"apparently unwarranted bravery","meaning":"看似毫無理由的勇敢","examples":[{"en":"The bird’s apparently unwarranted bravery made it easy to capture.","zh":"這種鳥看似毫無理由的勇敢令牠容易被捕捉。"},{"en":"Apparently unwarranted bravery means courage that seems unnecessary or not based on real safety.","zh":"apparently unwarranted bravery 指看起來不必要或沒有安全根據的勇敢。"},{"en":"A child shows apparently unwarranted bravery if he walks onto a busy road without fear.","zh":"如果小孩毫不害怕地走到繁忙馬路上，就是看似毫無理由的勇敢。"},{"en":"Apparently unwarranted bravery can be dangerous when it hides real risk.","zh":"當看似毫無理由的勇敢令人忽視真正風險時，就可能很危險。"},{"en":"For the booby, this lack of fear made humans able to catch it easily.","zh":"對鰹鳥而言，這種缺乏恐懼感令牠容易被人類捉住。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":6},{"front":"be extremely vulnerable to","meaning":"對……極易受傷害","examples":[{"en":"The blue-footed booby is extremely vulnerable to human visitors.","zh":"藍腳鰹鳥對人類訪客極易受傷害。"},{"en":"To be extremely vulnerable to something means to be very easily harmed by it.","zh":"be extremely vulnerable to something 指非常容易受到某事傷害。"},{"en":"Elderly people may be extremely vulnerable to extreme heat.","zh":"長者可能對極端高溫極易受傷害。"},{"en":"A small business can be extremely vulnerable to sudden rent increases.","zh":"小企業可能對突然加租極易受傷害。"},{"en":"The phrase shows serious danger, not just mild risk.","zh":"這個短語表示嚴重危險，而不只是輕微風險。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":6},{"front":"human visitors","meaning":"人類訪客","examples":[{"en":"The blue-footed booby seems unafraid of human visitors.","zh":"藍腳鰹鳥似乎不怕人類訪客。"},{"en":"Human visitors are people who come to see a place, animal or natural area.","zh":"human visitors 指前來參觀某地、動物或自然區域的人。"},{"en":"Human visitors to a nature reserve should follow rules and keep a safe distance.","zh":"到自然保護區的人類訪客應遵守規則並保持安全距離。"},{"en":"Too many human visitors can disturb animals even without meaning harm.","zh":"太多人類訪客可能會騷擾動物，即使人們沒有惡意。"},{"en":"In the passage, human visitors create danger because the birds do not fear them.","zh":"在文章中，人類訪客造成危險，因為這些鳥不害怕他們。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":7},{"front":"seem unafraid of","meaning":"似乎不怕……","examples":[{"en":"The blue-footed booby seems unafraid of people.","zh":"藍腳鰹鳥似乎不怕人。"},{"en":"To seem unafraid of something means to appear not to feel fear towards it.","zh":"seem unafraid of something 指看起來不害怕某事物。"},{"en":"A dog may seem unafraid of thunder if it keeps sleeping during a storm.","zh":"如果狗在雷雨中繼續睡覺，牠可能似乎不怕雷聲。"},{"en":"Animals that seem unafraid of humans may be easier to approach and harm.","zh":"似乎不怕人類的動物可能較容易被接近和傷害。"},{"en":"The phrase describes what appears true, even if we cannot know the animal’s feelings fully.","zh":"這個短語描述看起來是真的事情，即使我們不能完全知道動物的感受。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":7},{"front":"lack of fear","meaning":"缺乏恐懼感","examples":[{"en":"Its clumsiness and lack of fear made it easy to catch.","zh":"牠的笨拙和缺乏恐懼感令牠容易被捉住。"},{"en":"Lack of fear means not feeling or showing enough fear in a dangerous situation.","zh":"lack of fear 指在危險情況中沒有感到或表現出足夠恐懼。"},{"en":"A child’s lack of fear near deep water can worry parents.","zh":"小孩在深水附近缺乏恐懼感，可能令父母擔心。"},{"en":"Lack of fear may be useful sometimes, but dangerous when real risks exist.","zh":"缺乏恐懼感有時可能有用，但當真實風險存在時就很危險。"},{"en":"For the booby, lack of fear made it vulnerable to humans.","zh":"對鰹鳥而言，缺乏恐懼感令牠容易受到人類傷害。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":7},{"front":"make it easy for someone to","meaning":"令某人容易……","examples":[{"en":"The bird’s lack of fear made it easy for people to capture it.","zh":"這種鳥缺乏恐懼感，令人們容易捕捉牠。"},{"en":"To make it easy for someone to do something means to create conditions that help them do it.","zh":"make it easy for someone to do something 指創造條件，使某人容易做到某事。"},{"en":"Clear signs make it easy for visitors to find the museum entrance.","zh":"清楚指示牌令訪客容易找到博物館入口。"},{"en":"Online booking makes it easy for patients to choose an appointment time.","zh":"網上預約令病人容易選擇看診時間。"},{"en":"In the passage, the bird’s behaviour made it easy for humans to catch it.","zh":"在文章中，這種鳥的行為令人類容易捉住牠。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":7},{"front":"capture, kill and eat","meaning":"捕捉、殺死並食用","examples":[{"en":"Its lack of fear made it easy for people to capture, kill and eat.","zh":"牠缺乏恐懼感，令人們容易捕捉、殺死並食用牠。"},{"en":"To capture, kill and eat an animal means to catch it, end its life and use it as food.","zh":"capture, kill and eat an animal 指捉住動物、殺死牠並把牠作為食物。"},{"en":"In the past, sailors might capture, kill and eat animals on remote islands.","zh":"過去，水手可能會捕捉、殺死並食用偏遠島嶼上的動物。"},{"en":"Animals that do not flee from humans may be easier to capture, kill and eat.","zh":"不逃避人類的動物可能較容易被捕捉、殺死並食用。"},{"en":"The phrase shows a harsh result of human contact with fearless wildlife.","zh":"這個短語顯示無懼野生動物與人類接觸後的殘酷結果。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":7},{"front":"characteristic feet","meaning":"具特色的腳","examples":[{"en":"The blue-footed booby’s characteristic feet play a role in courtship.","zh":"藍腳鰹鳥具特色的腳在求偶中扮演角色。"},{"en":"Characteristic feet are feet that are special and easily recognised as a feature of the animal.","zh":"characteristic feet 指作為該動物特徵、特別且容易辨認的腳。"},{"en":"A duck’s webbed feet are characteristic feet that help it swim.","zh":"鴨子的蹼足是具特色的腳，幫助牠游泳。"},{"en":"The booby’s characteristic feet attract attention because of their bright colour.","zh":"鰹鳥具特色的腳因顏色鮮艷而引人注意。"},{"en":"This phrase links a physical feature with a biological function.","zh":"這個短語把身體特徵與生物功能連繫起來。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":7},{"front":"play a significant part in","meaning":"在……中扮演重要角色","examples":[{"en":"The bird’s feet play a significant part in its courtship ceremony.","zh":"這種鳥的腳在求偶儀式中扮演重要角色。"},{"en":"To play a significant part in something means to be important in it.","zh":"play a significant part in something 指在某事中十分重要。"},{"en":"Practice plays a significant part in improving exam performance.","zh":"練習在提升考試表現中扮演重要角色。"},{"en":"Good communication plays a significant part in preventing workplace conflict.","zh":"良好溝通在防止職場衝突中扮演重要角色。"},{"en":"The phrase shows that something has real influence.","zh":"這個短語表示某事有真實影響。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":7},{"front":"courtship ceremony","meaning":"求偶儀式","examples":[{"en":"The blue-footed booby is famous for its courtship ceremony.","zh":"藍腳鰹鳥以其求偶儀式聞名。"},{"en":"A courtship ceremony is a set of actions an animal uses to attract a mate.","zh":"courtship ceremony 指動物用來吸引伴侶的一套行為。"},{"en":"Some birds use songs, dances or colours in their courtship ceremony.","zh":"有些鳥類在求偶儀式中使用歌聲、舞蹈或顏色。"},{"en":"A courtship ceremony can help animals choose suitable partners.","zh":"求偶儀式可以幫助動物選擇合適的伴侶。"},{"en":"In the booby’s case, the ceremony includes showing off bright blue feet.","zh":"就鰹鳥而言，這個儀式包括展示鮮藍色的腳。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":7},{"front":"booby dance","meaning":"鰹鳥求偶舞","examples":[{"en":"The booby dance is part of the blue-footed booby’s courtship ceremony.","zh":"鰹鳥求偶舞是藍腳鰹鳥求偶儀式的一部分。"},{"en":"The booby dance is a display in which the bird moves and shows its feet to attract a mate.","zh":"booby dance 指這種鳥透過移動和展示腳來吸引伴侶的展示行為。"},{"en":"Tourists may remember the booby dance because it looks funny and careful at the same time.","zh":"遊客可能記得鰹鳥求偶舞，因為它看起來既有趣又謹慎。"},{"en":"The booby dance helps the male show his bright feet to the female.","zh":"鰹鳥求偶舞幫助雄鳥向雌鳥展示鮮藍色的腳。"},{"en":"This dance is part of mating behaviour, not entertainment for humans.","zh":"這種舞蹈是交配行為的一部分，而不是為人類娛樂。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":7},{"front":"walk around","meaning":"繞着……走","examples":[{"en":"The male walks around the female during the courtship dance.","zh":"雄鳥在求偶舞中繞着雌鳥走。"},{"en":"To walk around someone means to move in a circle or near them on foot.","zh":"walk around someone 指用腳步在某人周圍或附近移動。"},{"en":"A teacher may walk around the classroom to check students’ work.","zh":"老師可能在課室中走動，檢查學生的作業。"},{"en":"In a display, walking around can draw attention to the performer’s movement.","zh":"在展示行為中，繞着走可以吸引注意力到表演者的動作。"},{"en":"The phrase describes simple movement, but the purpose depends on the situation.","zh":"這個短語描述簡單移動，但目的取決於情境。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":7},{"front":"raise something straight up","meaning":"把……筆直抬起","examples":[{"en":"The male raises his bright blue feet straight up in the air.","zh":"雄鳥把鮮藍色的腳筆直抬到空中。"},{"en":"To raise something straight up means to lift it vertically, not sideways.","zh":"raise something straight up 指垂直抬起某物，而不是向側面抬。"},{"en":"A student may raise a hand straight up when asking a question.","zh":"學生提問時可能把手筆直舉起。"},{"en":"Raising something straight up makes it more visible to others.","zh":"把某物筆直抬起可以令其他人更容易看見。"},{"en":"In the dance, the male raises his feet straight up to display their colour.","zh":"在舞蹈中，雄鳥把腳筆直抬起，以展示其顏色。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":8},{"front":"bright blue feet","meaning":"鮮藍色的腳","examples":[{"en":"The male displays his bright blue feet during courtship.","zh":"雄鳥在求偶期間展示牠鮮藍色的腳。"},{"en":"Bright blue feet are feet with a strong, clear blue colour.","zh":"bright blue feet 指顏色強烈而清晰的藍色腳。"},{"en":"A child may describe the bird’s bright blue feet as looking like blue paint.","zh":"孩子可能形容這種鳥鮮藍色的腳像塗了藍色顏料。"},{"en":"Bright blue feet can attract a mate by making the bird more noticeable.","zh":"鮮藍色的腳可以令鳥更顯眼，從而吸引伴侶。"},{"en":"For the blue-footed booby, foot colour matters in courtship.","zh":"對藍腳鰹鳥而言，腳的顏色在求偶中很重要。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":8},{"front":"bring his shoulders towards the ground","meaning":"把肩部壓向地面","examples":[{"en":"The male brings his shoulders towards the ground while dancing.","zh":"雄鳥跳舞時把肩部壓向地面。"},{"en":"To bring his shoulders towards the ground means to lower the front part of his body.","zh":"bring his shoulders towards the ground 指把身體前部降低。"},{"en":"A dancer may bring his shoulders towards the ground to make a dramatic movement.","zh":"舞者可能把肩部壓向地面，以做出戲劇化動作。"},{"en":"This movement changes the bird’s posture and makes the display more noticeable.","zh":"這個動作改變鳥的姿勢，令展示更顯眼。"},{"en":"The phrase describes direction: the shoulders move downwards.","zh":"這個短語描述方向：肩部向下移動。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":8},{"front":"cross the bottom tips of his wings","meaning":"交叉翅膀末端","examples":[{"en":"The male crosses the bottom tips of his wings high above the ground.","zh":"雄鳥把翅膀末端高高離地交叉。"},{"en":"To cross the bottom tips of his wings means to place the lower ends of the wings over one another.","zh":"cross the bottom tips of his wings 指把翅膀較低的一端互相交疊。"},{"en":"A person may cross two pencils by placing one over the other.","zh":"一個人可以把兩枝鉛筆交叉，將一枝放在另一枝上。"},{"en":"Crossing the wing tips creates a special shape during the display.","zh":"交叉翅膀末端會在展示中形成特別形狀。"},{"en":"This detail shows how carefully the bird uses body posture in courtship.","zh":"這個細節顯示這種鳥在求偶中如何仔細運用身體姿勢。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":8},{"front":"high above the ground","meaning":"高高離地","examples":[{"en":"The male crosses his wing tips high above the ground.","zh":"雄鳥把翅膀末端高高離地交叉。"},{"en":"High above the ground means far above the surface of the land.","zh":"high above the ground 指離地面很高。"},{"en":"A kite flies high above the ground on a windy day.","zh":"在有風的日子，風箏高高離地飛翔。"},{"en":"Something high above the ground is easier to see from a distance.","zh":"高高離地的東西較容易從遠處看見。"},{"en":"In the courtship dance, this position makes the wing display more striking.","zh":"在求偶舞中，這個姿勢令翅膀展示更突出。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":8},{"front":"raise his bill up towards the sky","meaning":"把鳥喙朝天抬起","examples":[{"en":"The male raises his bill up towards the sky.","zh":"雄鳥把鳥喙朝天抬起。"},{"en":"To raise his bill up towards the sky means to point the bird’s beak upward.","zh":"raise his bill up towards the sky 指把鳥的喙向上指。"},{"en":"A bird may raise its bill up towards the sky while calling loudly.","zh":"鳥兒大叫時可能把鳥喙朝天抬起。"},{"en":"This upward movement can make a courtship display look more dramatic.","zh":"這個向上動作可以令求偶展示看起來更有戲劇性。"},{"en":"The phrase describes both the body part and the direction of movement.","zh":"這個短語同時描述身體部位和移動方向。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":8},{"front":"win his mate over","meaning":"贏得伴侶的歡心","examples":[{"en":"The male performs the dance to win his mate over.","zh":"雄鳥表演舞蹈，以贏得伴侶的歡心。"},{"en":"To win someone over means to persuade them to like, trust or accept you.","zh":"win someone over 指說服某人喜歡、信任或接受自己。"},{"en":"A speaker may win the audience over by giving honest examples.","zh":"演講者可能透過真誠例子贏得觀眾的支持。"},{"en":"A kind apology can win a friend over after an argument.","zh":"真誠道歉可以在爭執後贏得朋友的諒解。"},{"en":"In courtship, the male tries to win his mate over by showing attractive behaviour.","zh":"在求偶中，雄鳥透過展示具吸引力的行為來贏得伴侶的歡心。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":8},{"front":"participate in","meaning":"參與","examples":[{"en":"The female may also participate in these activities.","zh":"雌鳥也可能參與這些活動。"},{"en":"To participate in something means to take part in it.","zh":"participate in something 指參加或參與某事。"},{"en":"Students participate in class by answering questions and joining discussions.","zh":"學生透過回答問題和參與討論來參與課堂。"},{"en":"People who participate in community clean-ups help improve their neighbourhood.","zh":"參與社區清潔活動的人幫助改善自己的社區。"},{"en":"The phrase shows active involvement, not just watching.","zh":"這個短語表示主動參與，而不只是觀看。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":8},{"front":"lifting her feet","meaning":"抬起雙腳","examples":[{"en":"The female may participate by lifting her feet.","zh":"雌鳥可能透過抬起雙腳來參與。"},{"en":"Lifting her feet means raising her feet from the ground.","zh":"lifting her feet 指把腳從地面抬起。"},{"en":"A dancer may practise lifting her feet in time with the music.","zh":"舞者可能練習跟著音樂抬起雙腳。"},{"en":"In the courtship display, lifting her feet shows that the female is taking part.","zh":"在求偶展示中，抬起雙腳顯示雌鳥正在參與。"},{"en":"This movement mirrors the male’s focus on foot display.","zh":"這個動作呼應雄鳥重視腳部展示的行為。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":8},{"front":"sky-pointing","meaning":"朝天展示","examples":[{"en":"Sky-pointing is one of the activities in the courtship display.","zh":"朝天展示是求偶展示中的其中一項活動。"},{"en":"Sky-pointing is a behaviour in which a bird points its bill upward towards the sky.","zh":"sky-pointing 是鳥類把鳥喙向上指向天空的行為。"},{"en":"A birdwatcher may describe sky-pointing when a bird raises its head and beak high.","zh":"當鳥抬高頭和喙時，觀鳥者可能會描述這是朝天展示。"},{"en":"Sky-pointing can make the bird’s display more visible and dramatic.","zh":"朝天展示可以令鳥的展示更明顯和有戲劇性。"},{"en":"The name of the behaviour explains the action clearly.","zh":"這個行為的名稱清楚解釋了動作本身。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":8},{"front":"squawk at","meaning":"對……嘎嘎叫","examples":[{"en":"The female may squawk at her mate during the display.","zh":"雌鳥可能在展示期間對伴侶嘎嘎叫。"},{"en":"To squawk at someone means to make a loud, harsh bird sound towards them.","zh":"squawk at someone 指向某人發出響亮而刺耳的鳥叫聲。"},{"en":"Parrots may squawk at visitors when they feel excited or disturbed.","zh":"鸚鵡感到興奮或受干擾時，可能會對訪客嘎嘎叫。"},{"en":"A bird may squawk at another bird to communicate during a display.","zh":"鳥類可能對另一隻鳥嘎嘎叫，以在展示期間溝通。"},{"en":"The phrase describes a noisy bird call directed at someone or something.","zh":"這個短語描述朝某人或某物發出的嘈雜鳥叫聲。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":9},{"front":"after mating","meaning":"交配後","examples":[{"en":"After mating, another ritual occurs.","zh":"交配後，另一個儀式會發生。"},{"en":"After mating means after animals have paired and reproduced or attempted to reproduce.","zh":"after mating 指動物配對並繁殖或嘗試繁殖之後。"},{"en":"Some insects die soon after mating, while others care for their young.","zh":"有些昆蟲交配後很快死亡，而另一些會照顧幼體。"},{"en":"Animal behaviour after mating may include nest building, guarding eggs or feeding young.","zh":"交配後的動物行為可能包括築巢、守護鳥蛋或餵養幼體。"},{"en":"The phrase places an action later in the breeding process.","zh":"這個短語把某行動放在繁殖過程較後的位置。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":9},{"front":"ritual","meaning":"儀式","examples":[{"en":"Another ritual occurs after mating.","zh":"交配後，另一個儀式會發生。"},{"en":"A ritual is a repeated set of actions with meaning in culture, religion or animal behaviour.","zh":"ritual 指在文化、宗教或動物行為中具有意義的一套重複動作。"},{"en":"A family may have a bedtime ritual, such as reading a story before sleep.","zh":"家庭可能有睡前儀式，例如睡前讀故事。"},{"en":"Rituals create order because people or animals repeat the same actions.","zh":"儀式可以創造秩序，因為人或動物會重複相同行動。"},{"en":"In the passage, the ritual is a repeated display connected with breeding.","zh":"在文章中，這個儀式是與繁殖相關的重複展示。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":9},{"front":"nest-building display","meaning":"築巢展示","examples":[{"en":"The booby performs a nest-building display after mating.","zh":"鰹鳥在交配後進行築巢展示。"},{"en":"A nest-building display is a show of nest-building behaviour used in courtship or breeding.","zh":"nest-building display 指展示築巢行為，通常用於求偶或繁殖。"},{"en":"Some birds carry sticks as part of a nest-building display.","zh":"有些鳥會叼著樹枝，作為築巢展示的一部分。"},{"en":"A nest-building display may signal readiness to breed even if the nest is not used.","zh":"築巢展示可能表示準備繁殖，即使巢實際上不會被使用。"},{"en":"In this passage, the display is unusual because it serves no practical purpose.","zh":"在這篇文章中，這個展示不尋常，因為它沒有實際用途。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":9},{"front":"serve no practical purpose","meaning":"沒有實際用途","examples":[{"en":"The nest-building display serves no practical purpose because the nest is never used.","zh":"築巢展示沒有實際用途，因為那個巢永遠不會被使用。"},{"en":"To serve no practical purpose means to have no useful function in real action.","zh":"serve no practical purpose 指在實際行動中沒有有用功能。"},{"en":"Keeping a broken clock on the wall may serve no practical purpose if nobody repairs it.","zh":"如果沒有人修理，把壞鐘掛在牆上可能沒有實際用途。"},{"en":"A rule that nobody follows may serve no practical purpose.","zh":"一條沒有人遵守的規則可能沒有實際用途。"},{"en":"The phrase means something has no direct use, even if it may have meaning.","zh":"這個短語指某事沒有直接用途，即使它可能仍有意義。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":9},{"front":"nest on the bare ground","meaning":"在裸露地面築巢","examples":[{"en":"Boobies nest on the bare ground.","zh":"鰹鳥在裸露地面築巢。"},{"en":"To nest on the bare ground means to lay eggs directly on open ground without a raised nest.","zh":"nest on the bare ground 指直接在開闊地面產卵，而不是使用高起的巢。"},{"en":"Some birds nest on the bare ground because there are few trees in their habitat.","zh":"有些鳥在裸露地面築巢，因為牠們的棲息地少有樹木。"},{"en":"Nesting on the bare ground can expose eggs to heat, wind and predators.","zh":"在裸露地面築巢可能令鳥蛋暴露於高溫、風和捕食者之下。"},{"en":"This phrase shows where the eggs are placed.","zh":"這個短語說明鳥蛋被放在哪裡。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":9},{"front":"be ready to lay eggs","meaning":"準備產卵","examples":[{"en":"When the female is ready to lay eggs, the pair scrape the nest away.","zh":"當雌鳥準備產卵時，牠們會把巢刮走。"},{"en":"To be ready to lay eggs means that a female animal is prepared to produce eggs.","zh":"be ready to lay eggs 指雌性動物準備產下蛋。"},{"en":"A farmer may notice when a hen is ready to lay eggs by watching its behaviour.","zh":"農夫可能透過觀察母雞的行為，知道牠何時準備產卵。"},{"en":"When a bird is ready to lay eggs, it often needs a safe place.","zh":"當鳥準備產卵時，通常需要一個安全地方。"},{"en":"The phrase marks an important moment in the breeding process.","zh":"這個短語標誌繁殖過程中的重要時刻。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":9},{"front":"scrape the existing nest away","meaning":"把現有的巢刮走","examples":[{"en":"They scrape the existing nest away before laying eggs.","zh":"牠們在產卵前把現有的巢刮走。"},{"en":"To scrape the existing nest away means to remove the nest by pushing or scratching it off the ground.","zh":"scrape the existing nest away 指透過推刮或抓刮把現有的巢從地面移走。"},{"en":"A gardener may scrape old leaves away before planting new flowers.","zh":"園丁可能在種新花前把舊葉刮走。"},{"en":"If birds scrape the existing nest away, they clear the place before laying eggs.","zh":"如果鳥把現有的巢刮走，牠們就在產卵前清理地方。"},{"en":"The action is surprising because the nest-building display happened earlier.","zh":"這個動作令人意外，因為牠們之前才進行築巢展示。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":9},{"front":"exposed ground","meaning":"裸露地面","examples":[{"en":"The female nests on exposed ground.","zh":"雌鳥在裸露地面築巢。"},{"en":"Exposed ground is open ground without much cover or protection.","zh":"exposed ground 指沒有太多遮蔽或保護的開闊地面。"},{"en":"A tent on exposed ground may be hit directly by wind and sun.","zh":"搭在裸露地面上的帳篷可能直接受風吹和日曬。"},{"en":"Eggs laid on exposed ground need protection from heat and danger.","zh":"產在裸露地面的蛋需要免受高溫和危險傷害。"},{"en":"The phrase suggests that the place is not hidden or sheltered.","zh":"這個短語表示該地方沒有被隱藏或遮蔽。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":9},{"front":"sun-baked islands","meaning":"被太陽曬得炙熱的島嶼","examples":[{"en":"Sun-baked islands form the booby’s breeding grounds.","zh":"被太陽曬得炙熱的島嶼形成鰹鳥的繁殖地。"},{"en":"Sun-baked islands are islands made very hot and dry by strong sunlight.","zh":"sun-baked islands 指被強烈陽光曬得非常炎熱乾燥的島嶼。"},{"en":"Travellers on sun-baked islands need hats, water and shade.","zh":"在被太陽曬得炙熱的島嶼上旅行的人需要帽子、水和陰涼處。"},{"en":"Animals living on sun-baked islands must cope with heat and dryness.","zh":"生活在被太陽曬得炙熱的島嶼上的動物，必須應付高溫和乾燥。"},{"en":"The phrase helps readers imagine a hot, exposed breeding environment.","zh":"這個短語幫助讀者想像炎熱而暴露的繁殖環境。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":9},{"front":"breeding grounds","meaning":"繁殖地","examples":[{"en":"Sun-baked islands form the booby’s breeding grounds.","zh":"被太陽曬得炙熱的島嶼形成鰹鳥的繁殖地。"},{"en":"Breeding grounds are places where animals mate, lay eggs or raise young.","zh":"breeding grounds 指動物交配、產卵或養育幼體的地方。"},{"en":"Wetlands can be breeding grounds for many birds and insects.","zh":"濕地可以是許多鳥類和昆蟲的繁殖地。"},{"en":"If breeding grounds are damaged, animal populations may fall.","zh":"如果繁殖地受破壞，動物數量可能下降。"},{"en":"The phrase connects a place with reproduction and the next generation.","zh":"這個短語把地方與繁殖和下一代連繫起來。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":10},{"front":"lay one to three eggs","meaning":"產下一至三隻蛋","examples":[{"en":"The female blue-footed booby lays one to three eggs.","zh":"雌性藍腳鰹鳥產下一至三隻蛋。"},{"en":"To lay one to three eggs means to produce between one and three eggs.","zh":"lay one to three eggs 指產下一至三隻蛋。"},{"en":"A hen may lay one egg in a day, while some birds lay several eggs in a clutch.","zh":"母雞一天可能產下一隻蛋，而有些鳥一窩會產下幾隻蛋。"},{"en":"Laying one to three eggs gives parents more than one chance to raise a chick.","zh":"產下一至三隻蛋讓親鳥有多於一次機會養大雛鳥。"},{"en":"The phrase gives a range, not an exact number every time.","zh":"這個短語給出範圍，而不是每次都固定的準確數字。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":10},{"front":"shallow depression","meaning":"淺凹陷處","examples":[{"en":"The eggs are laid in a shallow depression on the ground.","zh":"鳥蛋被產在地面上的淺凹陷處。"},{"en":"A shallow depression is a small low area that is not deep.","zh":"shallow depression 指不深的小型低陷位置。"},{"en":"Rainwater may collect in a shallow depression on a road.","zh":"雨水可能積聚在道路上的淺凹陷處。"},{"en":"A shallow depression can stop eggs from rolling away.","zh":"淺凹陷處可以防止鳥蛋滾走。"},{"en":"The phrase describes a simple hollow rather than a built nest.","zh":"這個短語描述簡單的凹位，而不是建造出來的巢。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":10},{"front":"flat or gently sloping ground","meaning":"平坦或微斜的地面","examples":[{"en":"The eggs are laid on flat or gently sloping ground.","zh":"鳥蛋被產在平坦或微斜的地面上。"},{"en":"Flat or gently sloping ground means ground that is level or only slightly angled.","zh":"flat or gently sloping ground 指水平或只有輕微斜度的地面。"},{"en":"A wheelchair path should be on flat or gently sloping ground for safety.","zh":"輪椅通道應位於平坦或微斜的地面上，以確保安全。"},{"en":"Eggs placed on flat or gently sloping ground are less likely to roll far away.","zh":"放在平坦或微斜地面上的蛋較不容易滾遠。"},{"en":"The phrase shows that the ground is not steep.","zh":"這個短語表示地面並不陡斜。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":10},{"front":"take turns doing something","meaning":"輪流做某事","examples":[{"en":"Both male and female take turns incubating the eggs.","zh":"雄鳥和雌鳥輪流孵蛋。"},{"en":"To take turns doing something means to do it one after another, so each person shares the job.","zh":"take turns doing something 指一個接一個地做某事，讓每個人分擔工作。"},{"en":"Children take turns using the computer when there is only one at home.","zh":"家中只有一部電腦時，孩子們輪流使用。"},{"en":"Parents may take turns cooking dinner to reduce pressure on one person.","zh":"父母可能輪流煮晚餐，以減少其中一人的壓力。"},{"en":"The phrase suggests sharing or repeated switching.","zh":"這個短語表示分擔或反覆輪換。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":10},{"front":"incubate the eggs","meaning":"孵蛋","examples":[{"en":"Both parents incubate the eggs.","zh":"雙親都會孵蛋。"},{"en":"To incubate the eggs means to keep them warm so the young can develop inside.","zh":"incubate the eggs 指保持鳥蛋溫暖，讓幼體在蛋內發育。"},{"en":"A farmer may use a machine to incubate the eggs when a hen cannot sit on them.","zh":"當母雞不能坐在蛋上時，農夫可能使用機器孵蛋。"},{"en":"If birds do not incubate the eggs properly, the chicks may not survive.","zh":"如果鳥類沒有妥善孵蛋，雛鳥可能無法存活。"},{"en":"Incubating eggs is an important stage before hatching.","zh":"孵蛋是孵化前的重要階段。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":10},{"front":"unlike most birds","meaning":"與大多數鳥類不同","examples":[{"en":"Unlike most birds, the booby does not develop brood patches.","zh":"與大多數鳥類不同，鰹鳥不會長出孵卵斑。"},{"en":"Unlike most birds means different from what is common among birds.","zh":"unlike most birds 指與鳥類中常見情況不同。"},{"en":"Unlike most birds, penguins swim better than they fly.","zh":"與大多數鳥類不同，企鵝游泳比飛行更出色。"},{"en":"This phrase signals that the animal has an unusual feature.","zh":"這個短語表示該動物有不尋常特徵。"},{"en":"It helps readers compare the booby with the usual bird pattern.","zh":"它幫助讀者把鰹鳥與一般鳥類模式作比較。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":10},{"front":"develop brood patches","meaning":"長出孵卵斑","examples":[{"en":"The booby does not develop brood patches to warm the eggs.","zh":"鰹鳥不會長出孵卵斑來溫暖鳥蛋。"},{"en":"To develop brood patches means to grow bare warm skin areas used for incubating eggs.","zh":"develop brood patches 指長出用於孵蛋的裸露溫暖皮膚區域。"},{"en":"Many birds develop brood patches before they sit on their eggs.","zh":"許多鳥在坐在蛋上前會長出孵卵斑。"},{"en":"If a bird does not develop brood patches, it must warm the eggs another way.","zh":"如果鳥不會長出孵卵斑，就必須用另一種方式溫暖鳥蛋。"},{"en":"The phrase describes a physical change linked to reproduction.","zh":"這個短語描述與繁殖有關的身體變化。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":10},{"front":"brood patches","meaning":"孵卵斑","examples":[{"en":"Brood patches are areas of bare skin on a bird’s breast.","zh":"孵卵斑是鳥類胸部上的裸露皮膚區域。"},{"en":"Brood patches are warm featherless areas that help birds transfer heat to eggs.","zh":"孵卵斑是沒有羽毛的溫暖區域，幫助鳥類把熱傳給鳥蛋。"},{"en":"A biology teacher may show a diagram of brood patches when explaining incubation.","zh":"生物老師解釋孵蛋時，可能會展示孵卵斑的圖示。"},{"en":"Brood patches help eggs stay warm before hatching.","zh":"孵卵斑幫助鳥蛋在孵化前保持溫暖。"},{"en":"The booby is unusual because it lacks brood patches and uses its feet instead.","zh":"鰹鳥不尋常，因為牠沒有孵卵斑，而是使用腳。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":10},{"front":"areas of bare skin","meaning":"裸露皮膚區域","examples":[{"en":"Brood patches are areas of bare skin on the breast.","zh":"孵卵斑是胸部上的裸露皮膚區域。"},{"en":"Areas of bare skin are parts of the body without hair, feathers or covering.","zh":"areas of bare skin 指身體上沒有毛髮、羽毛或覆蓋物的部位。"},{"en":"A shaved patch on an animal before surgery becomes an area of bare skin.","zh":"動物手術前被剃毛的一塊位置會成為裸露皮膚區域。"},{"en":"Areas of bare skin can lose heat more easily than covered areas.","zh":"裸露皮膚區域比有覆蓋的部位更容易散失熱力。"},{"en":"In birds, such areas can help transfer warmth to eggs.","zh":"在鳥類身上，這些區域可以幫助把溫暖傳給鳥蛋。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":10},{"front":"warm the eggs","meaning":"溫暖鳥蛋","examples":[{"en":"Most birds use brood patches to warm the eggs during incubation.","zh":"大多數鳥類在孵蛋期間使用孵卵斑來溫暖鳥蛋。"},{"en":"To warm the eggs means to keep eggs at a suitable temperature for development.","zh":"warm the eggs 指讓鳥蛋保持適合發育的溫度。"},{"en":"A hen sits on her eggs to warm the eggs until they hatch.","zh":"母雞坐在蛋上溫暖鳥蛋，直到牠們孵化。"},{"en":"If parents fail to warm the eggs, the young inside may not develop properly.","zh":"如果雙親未能溫暖鳥蛋，蛋內幼體可能無法正常發育。"},{"en":"The phrase describes one of the main duties of incubating parents.","zh":"這個短語描述孵蛋父母的主要工作之一。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":11},{"front":"during incubation","meaning":"在孵蛋期間","examples":[{"en":"Boobies use their feet to warm the eggs during incubation.","zh":"鰹鳥在孵蛋期間用腳溫暖鳥蛋。"},{"en":"During incubation means in the period when eggs are kept warm before hatching.","zh":"during incubation 指鳥蛋在孵化前被保持溫暖的期間。"},{"en":"Farmers check temperature carefully during incubation.","zh":"農夫在孵蛋期間會仔細檢查溫度。"},{"en":"During incubation, eggs need steady warmth and protection.","zh":"在孵蛋期間，鳥蛋需要穩定溫暖和保護。"},{"en":"The phrase tells us when the warming process happens.","zh":"這個短語告訴我們保溫過程何時發生。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":11},{"front":"instead","meaning":"相反；而是","examples":[{"en":"Instead, the booby uses its broad webbed feet to warm the eggs.","zh":"相反，鰹鳥使用牠寬大的蹼足來溫暖鳥蛋。"},{"en":"Instead means in place of the first thing mentioned.","zh":"instead 指用另一件事取代前面提到的事。"},{"en":"I wanted to take the bus, but it was late, so I walked instead.","zh":"我本想乘巴士，但巴士遲了，所以我改為步行。"},{"en":"When one method does not work, people may choose another method instead.","zh":"當一種方法行不通，人們可能改用另一種方法。"},{"en":"In the passage, instead contrasts brood patches with the use of feet.","zh":"在文章中，instead 把孵卵斑和使用腳作對比。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":11},{"front":"broad webbed feet","meaning":"寬大的蹼足","examples":[{"en":"The booby uses its broad webbed feet to transmit heat.","zh":"鰹鳥使用寬大的蹼足來傳送熱力。"},{"en":"Broad webbed feet are wide feet with skin between the toes, often useful for swimming.","zh":"broad webbed feet 指寬闊、腳趾之間有皮膜的腳，通常有助游泳。"},{"en":"Ducks have broad webbed feet that help them push through water.","zh":"鴨子有寬大的蹼足，幫助牠們在水中前進。"},{"en":"Broad webbed feet can spread heat across the eggs during incubation.","zh":"寬大的蹼足可以在孵蛋期間把熱力分散到鳥蛋上。"},{"en":"In boobies, these feet help with both movement and reproduction.","zh":"在鰹鳥身上，這些腳同時幫助移動和繁殖。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":11},{"front":"prominent blood vessels","meaning":"明顯的血管","examples":[{"en":"The feet have large numbers of prominent blood vessels.","zh":"這些腳有大量明顯的血管。"},{"en":"Prominent blood vessels are blood vessels that are clear, noticeable or important.","zh":"prominent blood vessels 指清楚可見、明顯或重要的血管。"},{"en":"A nurse may see prominent blood vessels in a patient’s arm before taking blood.","zh":"護士抽血前可能會看見病人手臂上的明顯血管。"},{"en":"Prominent blood vessels in the feet can help carry warmth to the eggs.","zh":"腳上的明顯血管可以幫助把溫暖帶到鳥蛋。"},{"en":"The phrase shows that the vessels are not minor in function.","zh":"這個短語表示血管在功能上並非次要。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":11},{"front":"transmit heat","meaning":"傳送熱力","examples":[{"en":"The booby’s feet transmit heat essential for incubation.","zh":"鰹鳥的腳傳送孵蛋所必需的熱力。"},{"en":"To transmit heat means to pass warmth from one place or object to another.","zh":"transmit heat 指把熱力從一個地方或物件傳到另一個。"},{"en":"A metal spoon can transmit heat from hot soup to your hand.","zh":"金屬匙可以把熱湯的熱力傳到你的手上。"},{"en":"Blood vessels help transmit heat from the bird’s body to the eggs.","zh":"血管幫助把熱力從鳥的身體傳到鳥蛋。"},{"en":"This phrase explains how warmth moves, not just where it exists.","zh":"這個短語解釋熱力如何移動，而不只是熱力在哪裡。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":11},{"front":"essential for","meaning":"對……必不可少","examples":[{"en":"Heat is essential for incubation.","zh":"熱力對孵蛋必不可少。"},{"en":"Essential for something means absolutely necessary for it.","zh":"essential for something 指對某事絕對必要。"},{"en":"Sleep is essential for memory and concentration.","zh":"睡眠對記憶和專注力必不可少。"},{"en":"Clean water is essential for public health.","zh":"清潔食水對公共健康必不可少。"},{"en":"The phrase shows that something is not optional; it is needed.","zh":"這個短語表示某事不是可有可無，而是必需的。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":11},{"front":"thick-shelled","meaning":"厚殼的","examples":[{"en":"The eggs are thick-shelled so they can withstand pressure.","zh":"這些蛋是厚殼的，所以能承受壓力。"},{"en":"Thick-shelled eggs have strong, relatively thick outer coverings.","zh":"thick-shelled eggs 指外殼較厚而堅固的蛋。"},{"en":"A thick-shelled nut is harder to crack than a thin-shelled one.","zh":"厚殼堅果比薄殼堅果更難打開。"},{"en":"Thick-shelled eggs are less likely to break under weight.","zh":"厚殼的蛋在重量下較不容易破裂。"},{"en":"The word explains why the eggs can survive pressure from the parent bird.","zh":"這個詞解釋為何鳥蛋能承受親鳥的壓力。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":11},{"front":"withstand the full weight of","meaning":"承受……的全部重量","examples":[{"en":"The eggs can withstand the full weight of an incubating bird.","zh":"這些蛋能承受正在孵蛋的鳥的全部重量。"},{"en":"To withstand the full weight of something means to bear all of its pressure without breaking.","zh":"withstand the full weight of something 指承受某物全部壓力而不破裂。"},{"en":"A strong chair can withstand the full weight of an adult.","zh":"堅固的椅子能承受成年人的全部重量。"},{"en":"If a bridge cannot withstand the full weight of traffic, it becomes dangerous.","zh":"如果橋樑不能承受交通的全部重量，就會變得危險。"},{"en":"In the passage, the eggs are strong enough to support the parent bird’s body.","zh":"在文章中，這些蛋堅固得足以承受親鳥的身體重量。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":11},{"front":"incubating bird","meaning":"正在孵蛋的鳥","examples":[{"en":"The eggs can withstand the weight of an incubating bird.","zh":"這些蛋能承受正在孵蛋的鳥的重量。"},{"en":"An incubating bird is a bird that is keeping its eggs warm before they hatch.","zh":"incubating bird 指在鳥蛋孵化前保持它們溫暖的鳥。"},{"en":"An incubating bird may sit still for long periods.","zh":"正在孵蛋的鳥可能長時間保持不動。"},{"en":"If an incubating bird leaves the eggs too long, they may become cold.","zh":"如果正在孵蛋的鳥離開蛋太久，鳥蛋可能會變冷。"},{"en":"The phrase describes the bird’s role at that stage, not a separate species.","zh":"這個短語描述鳥在該階段的角色，而不是另一個物種。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":11},{"front":"after hatching","meaning":"孵化後","examples":[{"en":"After hatching, the male plays a major role in feeding the chicks.","zh":"孵化後，雄鳥在餵養雛鳥方面扮演主要角色。"},{"en":"After hatching means after the young animal comes out of the egg.","zh":"after hatching 指幼體從蛋中出來之後。"},{"en":"After hatching, baby turtles move towards the sea.","zh":"孵化後，小海龜會向大海移動。"},{"en":"Birds need more food after hatching because chicks must grow quickly.","zh":"鳥類在孵化後需要更多食物，因為雛鳥必須快速成長。"},{"en":"The phrase marks the stage after incubation has ended.","zh":"這個短語標誌孵蛋結束後的階段。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":12},{"front":"play a major role in","meaning":"在……中扮演主要角色","examples":[{"en":"The male plays a major role in bringing fish home.","zh":"雄鳥在帶魚回巢方面扮演主要角色。"},{"en":"To play a major role in something means to be one of the most important parts of it.","zh":"play a major role in something 指在某事中是最重要部分之一。"},{"en":"Parents play a major role in helping children build habits.","zh":"父母在幫助孩子建立習慣方面扮演主要角色。"},{"en":"Good public transport plays a major role in reducing traffic.","zh":"良好的公共交通在減少交通擠塞方面扮演主要角色。"},{"en":"The phrase shows strong importance or responsibility.","zh":"這個短語表示高度重要性或責任。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":12},{"front":"bring fish home","meaning":"帶魚回巢","examples":[{"en":"The male brings fish home for the chicks.","zh":"雄鳥為雛鳥帶魚回巢。"},{"en":"To bring fish home means to return with fish as food for the family or young.","zh":"bring fish home 指帶著魚回來作為家庭或幼體的食物。"},{"en":"A parent may bring food home after work so the family can eat dinner.","zh":"父母下班後可能帶食物回家，讓家人吃晚餐。"},{"en":"Male boobies bring fish home because the chicks need regular feeding.","zh":"雄性鰹鳥帶魚回巢，因為雛鳥需要定時餵食。"},{"en":"The phrase makes animal feeding sound like a family duty.","zh":"這個短語令動物覓食聽起來像一種家庭責任。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":12},{"front":"constant supply of","meaning":"穩定供應","examples":[{"en":"The male can bring back a constant supply of small fish.","zh":"雄鳥可以帶回穩定供應的小魚。"},{"en":"A constant supply of something is a steady amount that continues over time.","zh":"constant supply of something 指一段時間內持續穩定的某物供應。"},{"en":"A hospital needs a constant supply of clean water and electricity.","zh":"醫院需要清潔食水和電力的穩定供應。"},{"en":"Chicks grow better when parents provide a constant supply of food.","zh":"當父母提供穩定食物供應，雛鳥會長得更好。"},{"en":"The phrase stresses regular availability, not just one delivery.","zh":"這個短語強調定期可得，而不只是一次運送。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":12},{"front":"chicks","meaning":"雛鳥","examples":[{"en":"The chicks must be fed continuously.","zh":"雛鳥必須被持續餵食。"},{"en":"Chicks are young birds, especially soon after they hatch.","zh":"chicks 指幼鳥，尤其是剛孵化不久的鳥。"},{"en":"Children may see yellow chicks following a hen on a farm.","zh":"孩子在農場可能看見黃色雛鳥跟著母雞。"},{"en":"Chicks need warmth, protection and food because they are weak when young.","zh":"雛鳥需要溫暖、保護和食物，因為幼小時很脆弱。"},{"en":"In the passage, chicks depend on their parents for survival.","zh":"在文章中，雛鳥依賴父母生存。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":12},{"front":"be fed continuously","meaning":"被持續餵食","examples":[{"en":"The chicks must be fed continuously after hatching.","zh":"雛鳥孵化後必須被持續餵食。"},{"en":"To be fed continuously means to receive food again and again without long gaps.","zh":"be fed continuously 指不斷接受食物，中間沒有長時間間隔。"},{"en":"A newborn baby may need to be fed continuously throughout the day.","zh":"新生嬰兒可能需要整天被持續餵食。"},{"en":"Chicks must be fed continuously because they grow quickly and cannot find food alone.","zh":"雛鳥必須被持續餵食，因為牠們快速成長，而且不能自己找食物。"},{"en":"The phrase shows repeated care, not a single meal.","zh":"這個短語表示反覆照顧，而不是單一餐。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":12},{"front":"in relation to","meaning":"相對於","examples":[{"en":"The male has a longer tail in relation to his body size.","zh":"相對於身體大小，雄鳥有較長的尾巴。"},{"en":"In relation to means compared with or measured against something else.","zh":"in relation to 指與某事相比或以某事作為衡量標準。"},{"en":"Rent may be high in relation to a worker’s salary.","zh":"相對於工人的薪金，租金可能很高。"},{"en":"A child’s school bag may be heavy in relation to his body size.","zh":"相對於孩子的身體大小，書包可能很重。"},{"en":"The phrase helps compare one thing with a reference point.","zh":"這個短語幫助把某事與參照點比較。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":12},{"front":"body size","meaning":"身體大小","examples":[{"en":"The male’s tail is longer in relation to his body size.","zh":"相對於身體大小，雄鳥的尾巴較長。"},{"en":"Body size means how large or small an animal or person’s body is.","zh":"body size 指動物或人的身體有多大或多小。"},{"en":"A doctor may consider body size when deciding a safe medicine dose.","zh":"醫生決定安全藥物劑量時，可能會考慮身體大小。"},{"en":"Animals with different body sizes may need different amounts of food.","zh":"身體大小不同的動物可能需要不同食物量。"},{"en":"In the passage, body size is used to compare male and female features.","zh":"在文章中，身體大小用來比較雄鳥和雌鳥的特徵。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":12},{"front":"execute shallower dives","meaning":"進行較淺的潛水","examples":[{"en":"The male can execute shallower dives than the female.","zh":"雄鳥能比雌鳥進行較淺的潛水。"},{"en":"To execute shallower dives means to perform dives that do not go as deep.","zh":"execute shallower dives 指進行深度較淺的潛水動作。"},{"en":"A beginner swimmer may execute shallower dives until he feels confident.","zh":"初學游泳者可能先進行較淺的潛水，直到有信心。"},{"en":"Shallower dives allow birds to catch fish nearer the surface.","zh":"較淺的潛水讓鳥類捕捉較接近水面的魚。"},{"en":"The phrase combines action with depth.","zh":"這個短語結合了行動和深度。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":12},{"front":"feed closer to shore","meaning":"在較近岸處覓食","examples":[{"en":"The male can feed closer to shore.","zh":"雄鳥能在較近岸處覓食。"},{"en":"To feed closer to shore means to look for and eat food nearer the coast.","zh":"feed closer to shore 指在較接近海岸的地方尋找和進食食物。"},{"en":"Small fish near the beach allow some birds to feed closer to shore.","zh":"海灘附近的小魚讓有些鳥能在較近岸處覓食。"},{"en":"Feeding closer to shore may save energy because the bird travels a shorter distance.","zh":"在較近岸處覓食可能節省能量，因為鳥類飛行距離較短。"},{"en":"The phrase contrasts with feeding far out at sea.","zh":"這個短語與遠海覓食形成對比。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":12},{"front":"take on a larger role","meaning":"承擔更大角色","examples":[{"en":"The female takes on a larger role as time passes.","zh":"隨着時間過去，雌鳥承擔更大角色。"},{"en":"To take on a larger role means to accept or begin having more responsibility.","zh":"take on a larger role 指接受或開始擁有更多責任。"},{"en":"A senior student may take on a larger role in organising a school event.","zh":"高年級學生可能在籌辦學校活動中承擔更大角色。"},{"en":"Parents may take on a larger role in caring for grandparents when they become ill.","zh":"當祖父母生病時，父母可能在照顧方面承擔更大角色。"},{"en":"The phrase shows that responsibility increases over time.","zh":"這個短語表示責任隨時間增加。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":13},{"front":"as time passes","meaning":"隨着時間過去","examples":[{"en":"The female takes on a larger role as time passes.","zh":"隨着時間過去，雌鳥承擔更大角色。"},{"en":"As time passes means as days, weeks or months go by.","zh":"as time passes 指日子、星期或月份逐漸過去。"},{"en":"As time passes, students often become more confident in speaking English.","zh":"隨着時間過去，學生通常在說英語方面更有信心。"},{"en":"As time passes, young animals need more food and space.","zh":"隨着時間過去，幼小動物需要更多食物和空間。"},{"en":"The phrase shows gradual change rather than sudden change.","zh":"這個短語表示逐漸變化，而不是突然變化。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":13},{"front":"the need to","meaning":"……的需要","examples":[{"en":"As the chicks grow, the need to feed them becomes greater.","zh":"隨着雛鳥長大，餵養牠們的需要變得更大。"},{"en":"The need to do something means the importance or necessity of doing it.","zh":"the need to do something 指做某事的重要性或必要性。"},{"en":"During exams, the need to manage time becomes stronger.","zh":"在考試期間，管理時間的需要變得更強。"},{"en":"When a baby is hungry, the need to feed it cannot be ignored.","zh":"當嬰兒肚餓時，餵養他的需要不能被忽視。"},{"en":"The phrase shows that an action is necessary, not just preferred.","zh":"這個短語表示行動是必要的，而不只是較受歡迎。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":13},{"front":"protect them","meaning":"保護牠們","examples":[{"en":"At first, the parents need to protect the chicks.","zh":"起初，親鳥需要保護雛鳥。"},{"en":"To protect them means to keep them safe from harm or danger.","zh":"protect them 指使牠們免受傷害或危險。"},{"en":"Parents protect young children by holding their hands near busy roads.","zh":"父母在繁忙馬路旁牽著年幼孩子的手，以保護他們。"},{"en":"Birds protect their chicks from sun, cold and predators.","zh":"鳥類保護雛鳥免受日曬、寒冷和捕食者傷害。"},{"en":"The phrase usually refers back to people, animals or things already mentioned.","zh":"這個短語通常指回前面提到的人、動物或事物。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":13},{"front":"provide enough food","meaning":"提供足夠食物","examples":[{"en":"Both adults must fish to provide enough food.","zh":"兩隻成年鳥都必須捕魚，以提供足夠食物。"},{"en":"To provide enough food means to supply the amount of food that is needed.","zh":"provide enough food 指供應所需數量的食物。"},{"en":"A school canteen must provide enough food for all students at lunchtime.","zh":"學校食堂午餐時必須為所有學生提供足夠食物。"},{"en":"If parents cannot provide enough food, chicks may grow weak or die.","zh":"如果父母不能提供足夠食物，雛鳥可能變弱或死亡。"},{"en":"The phrase focuses on meeting a real need, not giving extra.","zh":"這個短語著重滿足真正需要，而不是提供額外東西。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":13},{"front":"when times are good","meaning":"當環境順利時","examples":[{"en":"When times are good, the parents may fledge all three chicks.","zh":"當環境順利時，親鳥可能成功養至三隻雛鳥羽翼豐滿。"},{"en":"When times are good means when conditions are favourable or resources are plentiful.","zh":"when times are good 指條件有利或資源充足的時候。"},{"en":"When times are good, a family may save more money or take a holiday.","zh":"當環境順利時，家庭可能儲更多錢或去旅行。"},{"en":"Animals can raise more young when times are good and food is easy to find.","zh":"當環境順利、食物容易找到時，動物能養大更多幼體。"},{"en":"The phrase contrasts with harder times or periods of shortage.","zh":"這個短語與艱難時期或短缺時期形成對比。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":13},{"front":"successfully fledge","meaning":"成功養至羽翼豐滿","examples":[{"en":"The parents may successfully fledge all three chicks.","zh":"親鳥可能成功養至三隻雛鳥羽翼豐滿。"},{"en":"To successfully fledge chicks means to raise them until they can fly and leave the nest.","zh":"successfully fledge chicks 指把雛鳥養到能飛行並離巢。"},{"en":"Birdwatchers may celebrate when rare birds successfully fledge young.","zh":"當稀有鳥類成功養育幼鳥至羽翼豐滿，觀鳥者可能會感到高興。"},{"en":"Parents need enough food and protection to successfully fledge chicks.","zh":"親鳥需要足夠食物和保護，才能成功養至雛鳥羽翼豐滿。"},{"en":"The phrase marks a successful early stage of bird development.","zh":"這個短語標誌鳥類早期發展階段的成功。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":13},{"front":"in harder times","meaning":"在較艱難的時期","examples":[{"en":"In harder times, the parents may raise only one chick.","zh":"在較艱難的時期，親鳥可能只養大一隻雛鳥。"},{"en":"In harder times means during more difficult periods with fewer resources or greater problems.","zh":"in harder times 指資源較少或問題較多的困難時期。"},{"en":"In harder times, families may spend less and avoid unnecessary purchases.","zh":"在較艱難的時期，家庭可能減少開支並避免不必要購物。"},{"en":"Animals may have fewer surviving young in harder times because food is scarce.","zh":"在較艱難的時期，動物存活的幼體可能較少，因為食物短缺。"},{"en":"The phrase contrasts with times when conditions are good.","zh":"這個短語與條件良好的時期形成對比。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":13},{"front":"lay as many eggs","meaning":"產下同樣多的蛋","examples":[{"en":"The parents may still lay as many eggs in harder times.","zh":"在較艱難的時期，親鳥可能仍產下同樣多的蛋。"},{"en":"To lay as many eggs means to produce the same number of eggs as before or as another case.","zh":"lay as many eggs 指產下與之前或另一情況相同數量的蛋。"},{"en":"A hen may lay as many eggs in spring as she did last year.","zh":"母雞在春天可能產下與去年同樣多的蛋。"},{"en":"Birds may lay as many eggs even when not all chicks can survive.","zh":"鳥類可能仍產下同樣多的蛋，即使並非所有雛鳥都能存活。"},{"en":"The phrase compares number, not survival success.","zh":"這個短語比較數量，而不是存活成功率。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":13},{"front":"obtain enough food to","meaning":"獲得足夠食物去","examples":[{"en":"The parents may obtain enough food to raise only one chick.","zh":"親鳥可能只獲得足夠食物去養大一隻雛鳥。"},{"en":"To obtain enough food to do something means to get the amount of food needed for that purpose.","zh":"obtain enough food to do something 指取得足以完成某目的的食物量。"},{"en":"A family must obtain enough food to prepare meals for the week.","zh":"家庭必須獲得足夠食物去準備一星期的餐膳。"},{"en":"If animals cannot obtain enough food to feed all their young, some may die.","zh":"如果動物無法獲得足夠食物去餵養所有幼體，有些幼體可能會死亡。"},{"en":"The phrase connects food supply with what can realistically be achieved.","zh":"這個短語把食物供應與實際能做到的事連繫起來。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":13},{"front":"raise one","meaning":"養大一隻","examples":[{"en":"In harder times, the parents may raise only one chick.","zh":"在較艱難的時期，親鳥可能只養大一隻雛鳥。"},{"en":"To raise one means to bring up one young animal or child until it grows stronger.","zh":"raise one 指把一個幼體或孩子照顧至成長。"},{"en":"A single parent may raise one child with help from relatives.","zh":"單親家長可能在親戚幫助下養大一個孩子。"},{"en":"Birds may raise one chick successfully when food is too limited for more.","zh":"當食物太有限，鳥類可能只成功養大一隻雛鳥。"},{"en":"The phrase focuses on successful care of one individual.","zh":"這個短語著重成功照顧一個個體。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":14},{"front":"somewhat callous-sounding system","meaning":"聽起來有點冷酷的制度","examples":[{"en":"The problem is solved by a somewhat callous-sounding system.","zh":"這個問題由一套聽起來有點冷酷的制度解決。"},{"en":"A somewhat callous-sounding system is a method that sounds rather cruel or emotionally cold.","zh":"somewhat callous-sounding system 指聽起來相當殘酷或情感冷漠的方法。"},{"en":"Choosing only the strongest seedlings may sound like a somewhat callous-sounding system.","zh":"只選擇最強壯的幼苗，可能聽起來像一套有點冷酷的制度。"},{"en":"Such a system may improve survival, even though it feels harsh.","zh":"這樣的制度可能提升存活率，雖然感覺嚴酷。"},{"en":"The phrase suggests that the method sounds cruel before we understand its purpose.","zh":"這個短語表示在理解其目的前，該方法聽起來很殘酷。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":14},{"front":"opportunistic sibling murder","meaning":"機會性手足相殘","examples":[{"en":"Opportunistic sibling murder can occur when food is scarce.","zh":"當食物短缺時，機會性手足相殘可能發生。"},{"en":"Opportunistic sibling murder means one young animal kills or causes the death of a brother or sister when conditions allow.","zh":"opportunistic sibling murder 指一隻幼小動物在條件允許時殺死或導致兄弟姊妹死亡。"},{"en":"In some nests, a stronger chick may push a weaker sibling away from food.","zh":"在某些巢中，較強壯的雛鳥可能把較弱的同巢雛鳥推離食物。"},{"en":"Opportunistic sibling murder may happen because limited food creates strong competition.","zh":"機會性手足相殘可能發生，因為有限食物造成激烈競爭。"},{"en":"The phrase sounds shocking, but it describes survival behaviour in harsh conditions.","zh":"這個短語聽起來令人震驚，但描述的是惡劣條件下的生存行為。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":14},{"front":"firstborn chick","meaning":"最先孵出的雛鳥","examples":[{"en":"The firstborn chick is larger and stronger than its nestmates.","zh":"最先孵出的雛鳥比同巢雛鳥更大更強壯。"},{"en":"The firstborn chick is the chick that hatches before the others.","zh":"firstborn chick 指比其他雛鳥先孵化出來的雛鳥。"},{"en":"In a nest, the firstborn chick may get food first because it is already bigger.","zh":"在巢中，最先孵出的雛鳥可能因已較大而先得到食物。"},{"en":"A firstborn chick may have an advantage if food is limited.","zh":"如果食物有限，最先孵出的雛鳥可能有優勢。"},{"en":"The phrase marks birth order among chicks.","zh":"這個短語標明雛鳥之間的孵化次序。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":14},{"front":"nestmates","meaning":"同巢雛鳥","examples":[{"en":"The firstborn chick is stronger than its nestmates.","zh":"最先孵出的雛鳥比同巢雛鳥更強壯。"},{"en":"Nestmates are young birds or animals that share the same nest.","zh":"nestmates 指住在同一個巢中的幼鳥或幼小動物。"},{"en":"Puppies born in the same bed can be compared to nestmates in a bird’s nest.","zh":"在同一張小床出生的小狗，可以比作鳥巢中的同巢雛鳥。"},{"en":"Nestmates may compete for food, warmth and space.","zh":"同巢雛鳥可能為食物、溫暖和空間競爭。"},{"en":"The word focuses on shared living place rather than exact family relationship.","zh":"這個詞著重共同居住的地方，而不一定是精確親屬關係。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":14},{"front":"as a result of","meaning":"由於","examples":[{"en":"The firstborn chick is stronger as a result of hatching earlier.","zh":"最先孵出的雛鳥由於較早孵化而更強壯。"},{"en":"As a result of means because of something.","zh":"as a result of 指由於某事。"},{"en":"The road was closed as a result of heavy rain.","zh":"道路由於大雨而關閉。"},{"en":"Students may improve as a result of regular practice and feedback.","zh":"學生可能由於定期練習和回饋而進步。"},{"en":"The phrase explains the cause behind a result.","zh":"這個短語解釋結果背後的原因。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":14},{"front":"hatch a few days earlier","meaning":"早幾天孵化","examples":[{"en":"The firstborn chick hatches a few days earlier than its nestmates.","zh":"最先孵出的雛鳥比同巢雛鳥早幾天孵化。"},{"en":"To hatch a few days earlier means to come out of the egg several days before others.","zh":"hatch a few days earlier 指比其他個體早數天從蛋中出來。"},{"en":"If one chick hatches a few days earlier, it may start eating and growing sooner.","zh":"如果一隻雛鳥早幾天孵化，牠可能更早開始進食和成長。"},{"en":"Hatching a few days earlier can create a size advantage.","zh":"早幾天孵化可以造成體型優勢。"},{"en":"The phrase shows that even a small time difference can matter.","zh":"這個短語顯示即使小小時間差異也可能重要。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":14},{"front":"if food is scarce","meaning":"如果食物短缺","examples":[{"en":"If food is scarce, the firstborn chick gets more food.","zh":"如果食物短缺，最先孵出的雛鳥會得到更多食物。"},{"en":"If food is scarce means if there is not enough food available.","zh":"if food is scarce 指如果可取得的食物不足。"},{"en":"If food is scarce during winter, animals may travel farther to search for it.","zh":"如果冬天食物短缺，動物可能走得更遠去尋找食物。"},{"en":"Competition becomes stronger if food is scarce.","zh":"如果食物短缺，競爭會變得更激烈。"},{"en":"The phrase introduces a difficult condition that affects survival.","zh":"這個短語引入影響生存的困難條件。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":14},{"front":"get more food than","meaning":"比……獲得更多食物","examples":[{"en":"The firstborn chick gets more food than its nestmates.","zh":"最先孵出的雛鳥比同巢雛鳥獲得更多食物。"},{"en":"To get more food than others means to receive a larger share of available food.","zh":"get more food than others 指比其他個體獲得更大份量的可用食物。"},{"en":"An older child may get more food than a younger one if portions are not shared fairly.","zh":"如果食物分配不公平，年長孩子可能比年幼孩子獲得更多食物。"},{"en":"A stronger chick may get more food than weaker chicks during feeding.","zh":"較強壯的雛鳥在餵食期間可能比較弱的雛鳥獲得更多食物。"},{"en":"The phrase compares how food is divided.","zh":"這個短語比較食物如何被分配。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":14},{"front":"outcompete them","meaning":"在競爭中勝過牠們","examples":[{"en":"The firstborn chick may outcompete its nestmates.","zh":"最先孵出的雛鳥可能在競爭中勝過同巢雛鳥。"},{"en":"To outcompete them means to beat them in competition for something limited.","zh":"outcompete them 指在爭奪有限資源時勝過牠們。"},{"en":"A large supermarket may outcompete small shops by offering lower prices.","zh":"大型超市可能透過較低價格在競爭中勝過小店。"},{"en":"Stronger chicks may outcompete weaker ones when food is scarce.","zh":"當食物短缺時，較強壯的雛鳥可能在競爭中勝過較弱的雛鳥。"},{"en":"The phrase shows that one side succeeds by competing more effectively.","zh":"這個短語表示一方因競爭能力更強而成功。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":14},{"front":"cause them to starve","meaning":"令牠們餓死","examples":[{"en":"The firstborn chick may cause its nestmates to starve.","zh":"最先孵出的雛鳥可能令同巢雛鳥餓死。"},{"en":"To cause them to starve means to make them suffer or die because they do not get enough food.","zh":"cause them to starve 指令牠們因得不到足夠食物而受苦或死亡。"},{"en":"Blocking weaker animals from food may cause them to starve.","zh":"阻止較弱動物取得食物，可能令牠們餓死。"},{"en":"If one chick takes most of the food, it may cause the others to starve.","zh":"如果一隻雛鳥拿走大部分食物，可能令其他雛鳥餓死。"},{"en":"The phrase shows a serious result of unequal food access.","zh":"這個短語顯示食物取得不平等的嚴重結果。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":15},{"front":"optimise reproductive capacity","meaning":"優化繁殖能力","examples":[{"en":"This system optimises the reproductive capacity of the blue-footed booby.","zh":"這套制度優化了藍腳鰹鳥的繁殖能力。"},{"en":"To optimise reproductive capacity means to make the animal’s ability to produce surviving young as effective as possible.","zh":"optimise reproductive capacity 指使動物產下並養活後代的能力盡可能有效。"},{"en":"Farmers may optimise reproductive capacity by giving animals safe conditions and enough food.","zh":"農夫可能透過提供安全環境和足夠食物來優化動物的繁殖能力。"},{"en":"In harsh environments, a system may optimise reproductive capacity by ensuring at least one young survives.","zh":"在惡劣環境中，一套制度可能透過確保至少一隻幼體存活來優化繁殖能力。"},{"en":"The phrase focuses on the best possible breeding result under real limits.","zh":"這個短語著重在現實限制下取得最佳繁殖結果。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":15},{"front":"reproductive capacity","meaning":"繁殖能力","examples":[{"en":"The system optimises the bird’s reproductive capacity.","zh":"這套制度優化了這種鳥的繁殖能力。"},{"en":"Reproductive capacity is the ability of an animal or plant to produce offspring.","zh":"reproductive capacity 指動物或植物產生後代的能力。"},{"en":"Healthy soil can increase the reproductive capacity of some plants.","zh":"健康土壤可以提升某些植物的繁殖能力。"},{"en":"Poor food supply may reduce an animal’s reproductive capacity.","zh":"食物供應不足可能降低動物的繁殖能力。"},{"en":"The phrase is about producing the next generation, not simply staying alive.","zh":"這個短語關乎產生下一代，而不只是存活。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":15},{"front":"unpredictable environment","meaning":"難以預測的環境","examples":[{"en":"The blue-footed booby lives in an unpredictable environment.","zh":"藍腳鰹鳥生活在難以預測的環境中。"},{"en":"An unpredictable environment is a place where conditions change in ways that are hard to know in advance.","zh":"unpredictable environment 指條件以難以預先知道的方式變化的地方。"},{"en":"Farmers face an unpredictable environment when rainfall changes from year to year.","zh":"當降雨量每年不同，農民就面對難以預測的環境。"},{"en":"Animals in an unpredictable environment need flexible survival strategies.","zh":"生活在難以預測環境中的動物需要靈活的生存策略。"},{"en":"The phrase explains why a harsh breeding system may be useful.","zh":"這個短語解釋為何嚴酷的繁殖制度可能有用。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":15},{"front":"ensure that","meaning":"確保","examples":[{"en":"The system ensures that at least one chick survives a shortage.","zh":"這套制度確保至少一隻雛鳥能捱過短缺時期。"},{"en":"To ensure that something happens means to make certain or very likely that it happens.","zh":"ensure that something happens 指確保某事發生，或令其很可能發生。"},{"en":"Wearing a seat belt helps ensure that passengers are safer in a crash.","zh":"繫安全帶有助確保乘客在撞車時較安全。"},{"en":"Good planning can ensure that a school trip runs smoothly.","zh":"良好計劃可以確保學校旅行順利進行。"},{"en":"The phrase shows a purpose: making an outcome more secure.","zh":"這個短語表示目的：令結果更有保障。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":15},{"front":"if possible","meaning":"如有可能","examples":[{"en":"If possible, at least one chick will survive.","zh":"如有可能，至少一隻雛鳥會存活。"},{"en":"If possible means if it can be done or if conditions allow it.","zh":"if possible 指如果可以做到，或如果條件允許。"},{"en":"Please arrive early if possible, so the meeting can start on time.","zh":"如有可能，請早點到達，好讓會議準時開始。"},{"en":"Animals save energy if possible when food is limited.","zh":"當食物有限，動物如有可能會節省能量。"},{"en":"The phrase leaves room for difficulty or limits.","zh":"這個短語為困難或限制留下空間。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":15},{"front":"at least one chick","meaning":"至少一隻雛鳥","examples":[{"en":"At least one chick may survive when food is scarce.","zh":"當食物短缺時，至少一隻雛鳥可能存活。"},{"en":"At least one chick means one chick or more, but not zero.","zh":"at least one chick 指一隻或以上雛鳥，而不是零隻。"},{"en":"In a difficult season, parents may hope that at least one chick lives.","zh":"在艱難季節中，親鳥可能希望至少一隻雛鳥存活。"},{"en":"Having at least one chick survive keeps the parents’ breeding effort from failing completely.","zh":"至少一隻雛鳥存活，可以避免親鳥的繁殖努力完全失敗。"},{"en":"The phrase sets a minimum number.","zh":"這個短語設定最低數量。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":15},{"front":"survive a period of shortage","meaning":"捱過一段短缺時期","examples":[{"en":"The system helps one chick survive a period of shortage.","zh":"這套制度幫助一隻雛鳥捱過一段短缺時期。"},{"en":"To survive a period of shortage means to stay alive through a time when there is not enough food or resources.","zh":"survive a period of shortage 指在食物或資源不足的時期中存活下來。"},{"en":"A family may survive a period of shortage by saving money and wasting less.","zh":"家庭可能透過儲錢和減少浪費來捱過一段短缺時期。"},{"en":"Animals survive a period of shortage by eating less, moving elsewhere or competing harder.","zh":"動物透過少吃、遷移或更激烈競爭來捱過一段短缺時期。"},{"en":"The phrase emphasises getting through a difficult temporary period.","zh":"這個短語強調渡過一段暫時的困難時期。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":15},{"front":"rather than","meaning":"而不是","examples":[{"en":"The system helps one chick survive rather than all three dying.","zh":"這套制度幫助一隻雛鳥存活，而不是三隻全部死亡。"},{"en":"Rather than means instead of, and it clearly contrasts two choices or outcomes.","zh":"rather than 指「而不是」，清楚對比兩個選擇或結果。"},{"en":"A student may ask for help rather than give up.","zh":"學生可能尋求幫助，而不是放棄。"},{"en":"Taking the bus rather than driving can reduce pollution.","zh":"乘搭巴士而不是駕車，可以減少污染。"},{"en":"The phrase points to the chosen or better option over another.","zh":"這個短語指出被選擇或較好的選項，而非另一個。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":15},{"front":"die of starvation","meaning":"餓死","examples":[{"en":"All three chicks might die of starvation under a different system.","zh":"在另一種制度下，三隻雛鳥可能全部餓死。"},{"en":"To die of starvation means to die because of not getting enough food.","zh":"die of starvation 指因得不到足夠食物而死亡。"},{"en":"In a famine, people and animals may die of starvation.","zh":"在饑荒中，人和動物可能會餓死。"},{"en":"Young chicks may die of starvation if parents cannot bring enough food.","zh":"如果親鳥不能帶來足夠食物，幼小雛鳥可能會餓死。"},{"en":"The phrase describes an extreme result of food shortage.","zh":"這個短語描述食物短缺的極端結果。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":15},{"front":"humane system","meaning":"較人道的制度","examples":[{"en":"A more humane system might lead to all three chicks dying.","zh":"較人道的制度可能導致三隻雛鳥全部死亡。"},{"en":"A humane system is a method that seems kinder and causes less suffering.","zh":"humane system 指看起來較仁慈、造成較少痛苦的方法。"},{"en":"A humane system in animal care tries to reduce pain and fear.","zh":"動物照護中的人道制度會嘗試減少痛苦和恐懼。"},{"en":"Sometimes a humane system may sound morally better but fail under harsh natural conditions.","zh":"有時較人道的制度在道德上聽起來更好，但在嚴酷自然條件下可能失敗。"},{"en":"The phrase contrasts kindness with practical survival results.","zh":"這個短語把仁慈與實際生存結果作對比。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":16},{"front":"choose the correct heading","meaning":"選出正確標題","examples":[{"en":"Students choose the correct heading for each paragraph.","zh":"學生為每一段選出正確標題。"},{"en":"To choose the correct heading means to select the title that best matches the paragraph’s main idea.","zh":"choose the correct heading 指選擇最符合段落主旨的標題。"},{"en":"In a reading test, students choose the correct heading after understanding the whole paragraph.","zh":"在閱讀測驗中，學生應理解整段後再選出正確標題。"},{"en":"Choosing the correct heading is easier when students focus on the main point.","zh":"當學生集中於主旨，選出正確標題會較容易。"},{"en":"This task tests overall understanding rather than one word only.","zh":"這種題型測試整體理解，而不只是一個詞。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":16},{"front":"from the list below","meaning":"從以下列表中","examples":[{"en":"The heading must be chosen from the list below.","zh":"標題必須從以下列表中選出。"},{"en":"From the list below means from the options printed underneath the instruction.","zh":"from the list below 指從指示下方列出的選項中。"},{"en":"Students should choose one answer from the list below, not invent their own.","zh":"學生應從以下列表中選擇一個答案，而不是自己創作答案。"},{"en":"Reading all choices from the list below helps avoid choosing too quickly.","zh":"閱讀以下列表中的所有選項，有助避免太快選擇。"},{"en":"The phrase tells students where the answer options are located.","zh":"這個短語告訴學生答案選項的位置。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":16},{"front":"write the correct number","meaning":"寫上正確編號","examples":[{"en":"Students write the correct number in the answer box.","zh":"學生在答案框中寫上正確編號。"},{"en":"To write the correct number means to put the matching numbered answer in the space provided.","zh":"write the correct number 指在指定位置填上相應的編號答案。"},{"en":"In a matching exercise, students may write the correct number beside each name.","zh":"在配對練習中，學生可能要在每個名字旁寫上正確編號。"},{"en":"Writing the wrong number can lose marks even if the idea is understood.","zh":"即使理解概念，寫錯編號也可能失分。"},{"en":"The phrase reminds students to answer using numbers, not full sentences.","zh":"這個短語提醒學生用數字作答，而不是完整句子。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":16},{"front":"list of headings","meaning":"標題列表","examples":[{"en":"The question provides a list of headings.","zh":"題目提供一個標題列表。"},{"en":"A list of headings is a set of possible titles for paragraphs or sections.","zh":"list of headings 指一組可作為段落或章節標題的選項。"},{"en":"Students compare each paragraph with the list of headings before choosing.","zh":"學生在選擇前會把每段與標題列表比較。"},{"en":"A long list of headings can confuse students if several titles look similar.","zh":"如果多個標題看起來相似，長標題列表可能令學生混淆。"},{"en":"The phrase is common in reading tests that ask for main ideas.","zh":"這個短語常見於要求找主旨的閱讀測驗。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":16},{"front":"an unusual way of incubating eggs","meaning":"孵蛋的不尋常方式","examples":[{"en":"The heading refers to the booby’s unusual way of incubating eggs.","zh":"這個標題指鰹鳥孵蛋的不尋常方式。"},{"en":"An unusual way of incubating eggs means a method of keeping eggs warm that is different from normal birds.","zh":"an unusual way of incubating eggs 指一種與一般鳥類不同的保暖孵蛋方法。"},{"en":"Using feet instead of brood patches is an unusual way of incubating eggs.","zh":"使用腳而不是孵卵斑，是孵蛋的不尋常方式。"},{"en":"An unusual way of incubating eggs may develop when an animal adapts to its environment.","zh":"當動物適應環境時，可能會發展出孵蛋的不尋常方式。"},{"en":"The phrase points to the method, not just the eggs themselves.","zh":"這個短語指方法，而不只是鳥蛋本身。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":16},{"front":"feeding habits","meaning":"進食習性","examples":[{"en":"The heading mentions the feeding habits of the red-footed booby.","zh":"這個標題提到紅腳鰹鳥的進食習性。"},{"en":"Feeding habits are the usual ways an animal finds, catches and eats food.","zh":"feeding habits 指動物尋找、捕捉和進食食物的通常方式。"},{"en":"A pet owner should understand a cat’s feeding habits before changing its diet.","zh":"寵物主人在改變貓的飲食前，應了解牠的進食習性。"},{"en":"Feeding habits may change when food becomes scarce or seasons change.","zh":"當食物變得短缺或季節改變，進食習性可能改變。"},{"en":"The phrase covers patterns of eating, not just one meal.","zh":"這個短語涵蓋進食模式，而不只是單一餐。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":16},{"front":"folding wings for a purpose","meaning":"有目的地收起翅膀","examples":[{"en":"Boobies fold their wings for a purpose before diving.","zh":"鰹鳥在潛水前有目的地收起翅膀。"},{"en":"Folding wings for a purpose means pulling the wings back in order to achieve a clear result.","zh":"folding wings for a purpose 指為了達到明確效果而把翅膀收起。"},{"en":"A bird may fold its wings for a purpose when squeezing through a narrow space.","zh":"鳥類穿過狹窄空間時，可能有目的地收起翅膀。"},{"en":"Folding wings before a dive reduces resistance and protects the wings.","zh":"潛水前收起翅膀可以減少阻力並保護翅膀。"},{"en":"The phrase shows that the movement is useful, not random.","zh":"這個短語表示該動作有用，而不是隨機。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":16},{"front":"rearing the young","meaning":"養育幼鳥","examples":[{"en":"The passage describes the parents’ role in rearing the young.","zh":"文章描述親鳥在養育幼鳥方面的角色。"},{"en":"Rearing the young means caring for young animals until they can survive more independently.","zh":"rearing the young 指照顧幼小動物，直到牠們能較獨立生存。"},{"en":"Many birds spend weeks rearing the young after eggs hatch.","zh":"許多鳥在鳥蛋孵化後花數星期養育幼鳥。"},{"en":"Rearing the young requires food, protection and time.","zh":"養育幼鳥需要食物、保護和時間。"},{"en":"The phrase focuses on parental care after birth or hatching.","zh":"這個短語著重出生或孵化後的親代照顧。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":16},{"front":"classification of boobies","meaning":"鰹鳥的分類","examples":[{"en":"The passage classifies boobies into three varieties.","zh":"文章把鰹鳥分類為三個品種。"},{"en":"Classification of boobies means organising boobies into types or groups.","zh":"classification of boobies 指把鰹鳥整理成不同類型或群組。"},{"en":"In science class, classification helps students place animals into clear categories.","zh":"在科學課上，分類幫助學生把動物放入清楚類別。"},{"en":"Classification of boobies makes it easier to compare their appearance and behaviour.","zh":"鰹鳥的分類使比較牠們的外貌和行為更容易。"},{"en":"The phrase is about grouping, not describing one bird only.","zh":"這個短語關乎分組，而不只是描述一隻鳥。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":16},{"front":"diving for food","meaning":"潛水覓食","examples":[{"en":"Boobies are skilled at diving for food.","zh":"鰹鳥擅長潛水覓食。"},{"en":"Diving for food means entering water to catch something to eat.","zh":"diving for food 指進入水中捕捉食物。"},{"en":"Penguins and some seabirds are good at diving for food.","zh":"企鵝和一些海鳥擅長潛水覓食。"},{"en":"Diving for food requires good timing, strong movement and clear vision.","zh":"潛水覓食需要良好時機、強健動作和清晰視力。"},{"en":"The phrase describes both the action and the purpose of the action.","zh":"這個短語同時描述動作和動作目的。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":17},{"front":"survival mechanism","meaning":"生存機制","examples":[{"en":"Sibling competition acts as a survival mechanism during food shortages.","zh":"在食物短缺期間，手足競爭是一種生存機制。"},{"en":"A survival mechanism is a behaviour or feature that helps an organism stay alive.","zh":"survival mechanism 指幫助生物存活的行為或特徵。"},{"en":"Sweating is a survival mechanism because it helps the body cool down.","zh":"流汗是一種生存機制，因為它幫助身體降溫。"},{"en":"In animals, a survival mechanism may look harsh but improve the chance of survival.","zh":"在動物中，生存機制可能看起來嚴酷，但能提高存活機會。"},{"en":"The phrase explains why a behaviour exists, not whether it seems kind.","zh":"這個短語解釋行為為何存在，而不是判斷它是否仁慈。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":17},{"front":"food shortages","meaning":"食物短缺","examples":[{"en":"The survival mechanism operates during food shortages.","zh":"這種生存機制在食物短缺期間運作。"},{"en":"Food shortages are periods when there is not enough food for everyone or every animal.","zh":"food shortages 指沒有足夠食物供所有人或所有動物使用的時期。"},{"en":"Food shortages can happen after droughts, storms or poor harvests.","zh":"食物短缺可能在旱災、風暴或收成差後發生。"},{"en":"During food shortages, competition for food becomes stronger.","zh":"在食物短缺期間，食物競爭會變得更激烈。"},{"en":"The phrase describes a lack of food, not simply expensive food.","zh":"這個短語描述食物不足，而不只是食物昂貴。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":17},{"front":"mating and breeding","meaning":"交配和繁殖","examples":[{"en":"The blue-footed booby’s mating and breeding behaviour is unusual.","zh":"藍腳鰹鳥的交配和繁殖行為很不尋常。"},{"en":"Mating and breeding refers to how animals find partners, reproduce and raise young.","zh":"mating and breeding 指動物如何尋找伴侶、繁殖和養育幼體。"},{"en":"A wildlife programme may explain the mating and breeding habits of frogs.","zh":"野生動物節目可能解釋青蛙的交配和繁殖習性。"},{"en":"Mating and breeding behaviour can change when food, weather or habitat changes.","zh":"當食物、天氣或棲息地改變，交配和繁殖行為可能改變。"},{"en":"The phrase covers the whole reproductive process, not just pairing.","zh":"這個短語涵蓋整個繁殖過程，而不只是配對。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":17},{"front":"the origin of the booby’s name","meaning":"鰹鳥名稱的來源","examples":[{"en":"The passage explains the possible origin of the booby’s name.","zh":"文章解釋鰹鳥名稱的可能來源。"},{"en":"The origin of the booby’s name means where the word “booby” may have come from.","zh":"the origin of the booby’s name 指 “booby” 這個詞可能來自哪裡。"},{"en":"A teacher may discuss the origin of a place name to make history more memorable.","zh":"老師可能討論地名的來源，使歷史更易記。"},{"en":"The origin of the booby’s name may be linked to how the bird looked or behaved to people.","zh":"鰹鳥名稱的來源可能與人們眼中牠的外貌或行為有關。"},{"en":"The phrase focuses on word history, not the bird’s biology alone.","zh":"這個短語著重詞語歷史，而不只是鳥類生物學。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":17},{"front":"agree with the information given in","meaning":"與文章提供的資料一致","examples":[{"en":"Students decide whether statements agree with the information given in the passage.","zh":"學生判斷陳述是否與文章提供的資料一致。"},{"en":"To agree with the information given in a passage means to match what the passage says.","zh":"agree with the information given in a passage 指與文章所說的內容相符。"},{"en":"In a reading test, an answer agrees with the information given in the text if both say the same thing.","zh":"在閱讀測驗中，如果答案與文章說法相同，它就與文章提供的資料一致。"},{"en":"Students should not use outside knowledge when checking whether a statement agrees with the information given in the passage.","zh":"學生判斷陳述是否與文章提供的資料一致時，不應使用外部知識。"},{"en":"The phrase is common in TRUE, FALSE and NOT GIVEN questions.","zh":"這個短語常見於 TRUE、FALSE 和 NOT GIVEN 題型。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":17},{"front":"if the statement agrees with","meaning":"如果陳述與……一致","examples":[{"en":"Students write TRUE if the statement agrees with the information.","zh":"如果陳述與資料一致，學生寫 TRUE。"},{"en":"If the statement agrees with the information means if the statement says the same thing as the text.","zh":"if the statement agrees with the information 指如果陳述與文本資料說法相同。"},{"en":"Students choose TRUE if the statement agrees with the information exactly.","zh":"如果陳述與資料完全一致，學生選 TRUE。"},{"en":"If the statement agrees with only part of the information, students should read again carefully.","zh":"如果陳述只與部分資料一致，學生應再次仔細閱讀。"},{"en":"The phrase tells students when TRUE is the correct answer.","zh":"這個短語告訴學生甚麼時候 TRUE 是正確答案。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":17},{"front":"contradicts the information","meaning":"與資料相矛盾","examples":[{"en":"Students write FALSE if the statement contradicts the information.","zh":"如果陳述與資料相矛盾，學生寫 FALSE。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"contradict the information 指說法與文本資料相反。"},{"en":"If a passage says a shop opens at nine, a statement saying it opens at ten contradicts the information.","zh":"如果文章說商店九時開門，而陳述說十時開門，就是與資料相矛盾。"},{"en":"Students should choose FALSE when a statement clearly contradicts the information.","zh":"當陳述明顯與資料相矛盾，學生應選 FALSE。"},{"en":"The phrase means there is conflict, not just missing detail.","zh":"這個短語表示有衝突，而不只是缺少細節。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":17},{"front":"there is no information on this","meaning":"沒有關於這方面的資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有關於這方面的資料，學生寫 NOT GIVEN。"},{"en":"There is no information on this means the text does not say anything clearly about the point.","zh":"there is no information on this 指文本沒有清楚說明該點。"},{"en":"If a passage describes a bird’s colour but not its speed, there is no information on this speed.","zh":"如果文章描述鳥的顏色，但沒有說速度，就是沒有關於這方面速度的資料。"},{"en":"Students should not guess TRUE or FALSE when there is no information on this.","zh":"當沒有關於這方面的資料時，學生不應猜 TRUE 或 FALSE。"},{"en":"The phrase is used when the answer cannot be proved from the passage.","zh":"這個短語用於答案不能從文章中證明的情況。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":17},{"front":"be frightened when","meaning":"當……時感到害怕","examples":[{"en":"The statement asks whether boobies are frightened when humans approach them.","zh":"該陳述問鰹鳥是否在人類接近牠們時感到害怕。"},{"en":"To be frightened when something happens means to feel fear at that moment.","zh":"be frightened when something happens 指在某事發生時感到恐懼。"},{"en":"A child may be frightened when a loud alarm suddenly rings.","zh":"當響亮警報突然響起，小孩可能會感到害怕。"},{"en":"Animals may be frightened when strangers come too close.","zh":"當陌生人太接近時，動物可能會感到害怕。"},{"en":"The phrase links fear with a specific event or situation.","zh":"這個短語把恐懼與特定事件或情況連繫起來。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":17},{"front":"humans approach them","meaning":"人類接近牠們","examples":[{"en":"The blue-footed booby seems unafraid when humans approach it.","zh":"當人類接近藍腳鰹鳥時，牠似乎不害怕。"},{"en":"Humans approach them means people move closer to the animals.","zh":"humans approach them 指人類向動物走近。"},{"en":"Park signs may warn visitors not to approach wild animals.","zh":"公園標示可能提醒訪客不要接近野生動物。"},{"en":"When humans approach them too closely, animals may become stressed or unsafe.","zh":"當人類太接近牠們時，動物可能變得緊張或不安全。"},{"en":"In this passage, the birds’ calm response to humans creates risk.","zh":"在這篇文章中，這些鳥對人類的平靜反應帶來風險。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":18},{"front":"at the expense of","meaning":"以犧牲……為代價","examples":[{"en":"Larger chicks are fed at the expense of their smaller nestmates’ survival.","zh":"較大的雛鳥被餵食，是以犧牲較小同巢雛鳥的生存為代價。"},{"en":"At the expense of something means by harming, sacrificing or reducing that thing.","zh":"at the expense of something 指透過傷害、犧牲或減少某事來達成。"},{"en":"A student should not improve exam results at the expense of sleep and health.","zh":"學生不應以犧牲睡眠和健康為代價來提升考試成績。"},{"en":"A company may cut costs at the expense of product quality.","zh":"公司可能以犧牲產品質素為代價來削減成本。"},{"en":"The phrase shows that one gain creates a loss elsewhere.","zh":"這個短語表示一方得到好處，另一方承受損失。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":18},{"front":"smaller nestmates’ survival","meaning":"較小同巢雛鳥的生存","examples":[{"en":"The survival of smaller nestmates may be threatened when food is scarce.","zh":"當食物短缺時，較小同巢雛鳥的生存可能受到威脅。"},{"en":"Smaller nestmates’ survival means the continued life of the younger or weaker chicks in the same nest.","zh":"smaller nestmates’ survival 指同一巢中較年幼或較弱雛鳥能否繼續存活。"},{"en":"If stronger chicks take most of the food, smaller nestmates’ survival becomes less likely.","zh":"如果較強壯的雛鳥拿走大部分食物，較小同巢雛鳥的生存機會會降低。"},{"en":"Parents may not be able to protect smaller nestmates’ survival during severe shortages.","zh":"在嚴重短缺期間，親鳥可能無法保護較小同巢雛鳥的生存。"},{"en":"The phrase focuses on whether the weaker chicks can stay alive.","zh":"這個短語著重較弱雛鳥能否活下來。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":18},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"To complete the summary below means to fill in the missing parts of the summary printed under the instruction.","zh":"complete the summary below 指填寫指示下方摘要中的空缺部分。"},{"en":"In reading tests, students complete the summary below by choosing words that match the grammar and meaning.","zh":"在閱讀測驗中，學生透過選擇符合文法和意思的字詞完成以下摘要。"},{"en":"Reading the whole paragraph first can help students complete the summary below accurately.","zh":"先閱讀整段可以幫助學生準確完成以下摘要。"},{"en":"The phrase tells students both the task and where it appears.","zh":"這個短語同時告訴學生任務和位置。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":18},{"front":"no more than two words","meaning":"不超過兩個字","examples":[{"en":"Students should choose no more than two words from the passage.","zh":"學生應從文章中選擇不超過兩個字。"},{"en":"No more than two words means one word or two words, but not three.","zh":"no more than two words 指一個字或兩個字，但不能是三個字。"},{"en":"If the answer limit is no more than two words, “blue feet” is allowed but “bright blue feet” is too long.","zh":"如果答案限制是不超過兩個字，“blue feet” 可以，但 “bright blue feet” 太長。"},{"en":"Students lose marks if they write more than the allowed number of words.","zh":"如果學生寫多於允許字數，可能會失分。"},{"en":"The phrase is an important instruction in completion tasks.","zh":"這個短語是填充題中的重要指示。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":18},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must come from the passage.","zh":"答案必須來自文章。"},{"en":"From the passage means taken directly from the reading text.","zh":"from the passage 指直接取自閱讀文本。"},{"en":"Students should copy the exact word from the passage if the instruction requires it.","zh":"如果題目要求，學生應複製文章中的準確字詞。"},{"en":"Using words from memory may be wrong if they are not from the passage.","zh":"如果使用記憶中的字詞，而它們不是來自文章，可能會錯。"},{"en":"The phrase reminds students that the text is the only source for the answer.","zh":"這個短語提醒學生，文本是答案的唯一來源。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":18},{"front":"courtship of","meaning":"……的求偶","examples":[{"en":"The courtship of the blue-footed booby includes dancing and display.","zh":"藍腳鰹鳥的求偶包括舞蹈和展示。"},{"en":"The courtship of an animal is the behaviour it uses to attract a mate.","zh":"the courtship of an animal 指動物用來吸引伴侶的行為。"},{"en":"The courtship of some birds includes singing, dancing and showing bright colours.","zh":"有些鳥類的求偶包括唱歌、跳舞和展示鮮艷顏色。"},{"en":"Studying the courtship of animals helps scientists understand how mates are chosen.","zh":"研究動物的求偶有助科學家理解伴侶如何被選擇。"},{"en":"The phrase introduces the mating behaviour of a particular species.","zh":"這個短語引入某一物種的交配行為。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":18},{"front":"consist of","meaning":"由……組成","examples":[{"en":"The courtship consists of the male flaunting his blue feet.","zh":"求偶由雄鳥炫耀牠的藍腳組成。"},{"en":"To consist of something means to be made up of particular parts.","zh":"consist of something 指由特定部分組成。"},{"en":"A simple breakfast may consist of bread, eggs and tea.","zh":"簡單早餐可能由麵包、雞蛋和茶組成。"},{"en":"A lesson can consist of explanation, practice and feedback.","zh":"一堂課可以由講解、練習和回饋組成。"},{"en":"The phrase lists the parts that form a whole.","zh":"這個短語列出構成整體的部分。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":18},{"front":"flaunt his blue feet","meaning":"炫耀牠的藍腳","examples":[{"en":"The male flaunts his blue feet to impress the female.","zh":"雄鳥炫耀牠的藍腳來吸引雌鳥。"},{"en":"To flaunt his blue feet means to show them off proudly and clearly.","zh":"flaunt his blue feet 指自豪而清楚地展示牠的藍腳。"},{"en":"A dancer may flaunt her costume by turning slowly in front of the audience.","zh":"舞者可能在觀眾面前慢慢轉身，炫耀她的服裝。"},{"en":"The male bird flaunts his blue feet because their colour helps attract a mate.","zh":"雄鳥炫耀牠的藍腳，因為腳的顏色有助吸引伴侶。"},{"en":"The phrase suggests deliberate display, not accidental showing.","zh":"這個短語表示有意展示，而不是偶然露出。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":18},{"front":"impress the female","meaning":"吸引雌鳥","examples":[{"en":"The male dances to impress the female.","zh":"雄鳥跳舞來吸引雌鳥。"},{"en":"To impress the female means to make the female notice, admire or accept him.","zh":"impress the female 指令雌性注意、欣賞或接受牠。"},{"en":"A male peacock spreads his tail to impress the female.","zh":"雄孔雀展開尾巴來吸引雌鳥。"},{"en":"Animals may use colour, sound or movement to impress the female during courtship.","zh":"動物在求偶期間可能用顏色、聲音或動作來吸引雌性。"},{"en":"The phrase explains the purpose of the display.","zh":"這個短語解釋展示行為的目的。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":18},{"front":"spread his wings","meaning":"展開翅膀","examples":[{"en":"The male spreads his wings during the courtship dance.","zh":"雄鳥在求偶舞中展開翅膀。"},{"en":"To spread his wings means to open his wings wide.","zh":"spread his wings 指把翅膀張開。"},{"en":"A bird may spread its wings to dry them in the sun.","zh":"鳥可能展開翅膀在陽光下曬乾。"},{"en":"Spreading his wings makes the male look larger and more noticeable.","zh":"展開翅膀令雄鳥看起來更大、更顯眼。"},{"en":"In a courtship display, this movement helps attract attention.","zh":"在求偶展示中，這個動作有助吸引注意。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":19},{"front":"stamp his feet","meaning":"跺腳","examples":[{"en":"The male stamps his feet on the ground.","zh":"雄鳥在地上跺腳。"},{"en":"To stamp his feet means to put his feet down hard and clearly.","zh":"stamp his feet 指用力而明顯地把腳踏下。"},{"en":"A child may stamp his feet when angry or impatient.","zh":"小孩生氣或不耐煩時可能會跺腳。"},{"en":"In a dance, stamping the feet can create rhythm and draw attention.","zh":"在舞蹈中，跺腳可以製造節奏並吸引注意。"},{"en":"For the booby, stamping his feet helps display their bright colour.","zh":"對鰹鳥而言，跺腳有助展示鮮艷的腳色。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":19},{"front":"with his bill","meaning":"牠的鳥喙……","examples":[{"en":"The male dances with his bill raised towards the sky.","zh":"雄鳥跳舞時把鳥喙朝天抬起。"},{"en":"With his bill means using or positioning the bird’s beak in a particular way.","zh":"with his bill 指用或擺放鳥喙作某種動作。"},{"en":"A bird may pick up grass with his bill when building a nest.","zh":"鳥築巢時可能用鳥喙叼起草。"},{"en":"The male’s posture with his bill raised makes the display more dramatic.","zh":"雄鳥把鳥喙抬起的姿勢令展示更有戲劇性。"},{"en":"The phrase tells us which body part is involved.","zh":"這個短語告訴我們涉及哪個身體部位。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":19},{"front":"unusual behaviour","meaning":"不尋常行為","examples":[{"en":"The booby’s unusual behaviour continues after mating.","zh":"鰹鳥的不尋常行為在交配後繼續。"},{"en":"Unusual behaviour is behaviour that is different from what people normally expect.","zh":"unusual behaviour 指與人們通常預期不同的行為。"},{"en":"A normally shy student showing unusual behaviour may make a teacher concerned.","zh":"一名平時害羞的學生出現不尋常行為，可能令老師擔心。"},{"en":"Scientists study unusual behaviour because it may reveal adaptation or stress.","zh":"科學家研究不尋常行為，因為它可能揭示適應或壓力。"},{"en":"In this passage, the nest-building ritual is an example of unusual behaviour.","zh":"在這篇文章中，築巢儀式是不尋常行為的一個例子。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":19},{"front":"serves no practical purpose","meaning":"沒有實際用途","examples":[{"en":"The nest-building ritual serves no practical purpose.","zh":"築巢儀式沒有實際用途。"},{"en":"Serves no practical purpose means has no clear useful function in reality.","zh":"serves no practical purpose 指在現實中沒有清楚有用的功能。"},{"en":"A locked doorbell serves no practical purpose if visitors cannot use it.","zh":"如果訪客不能使用，被鎖住的門鐘就沒有實際用途。"},{"en":"A long form may serve no practical purpose if nobody reads the information.","zh":"如果沒有人閱讀資料，一份很長的表格可能沒有實際用途。"},{"en":"The phrase suggests something may exist for display or tradition rather than direct use.","zh":"這個短語表示某事可能是為了展示或傳統，而不是直接用途。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":19},{"front":"beneath their feet","meaning":"在牠們的腳下","examples":[{"en":"The parents incubate the eggs beneath their feet.","zh":"親鳥在牠們的腳下孵蛋。"},{"en":"Beneath their feet means under their feet.","zh":"beneath their feet 指在牠們的腳下面。"},{"en":"Sand beneath your feet may feel hot on a sunny beach.","zh":"在陽光猛烈的海灘上，你腳下的沙可能很熱。"},{"en":"Eggs beneath their feet receive warmth from the birds’ blood vessels.","zh":"在牠們腳下的鳥蛋會從鳥類血管獲得溫暖。"},{"en":"The phrase tells us the position of one thing under another.","zh":"這個短語告訴我們一件事物位於另一事物下方。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":19},{"front":"contain blood vessels","meaning":"含有血管","examples":[{"en":"The feet contain blood vessels that transmit heat.","zh":"這些腳含有能傳送熱力的血管。"},{"en":"To contain blood vessels means to have tubes inside that carry blood.","zh":"contain blood vessels 指內部有輸送血液的管道。"},{"en":"The skin contains blood vessels that help control body temperature.","zh":"皮膚含有幫助控制體溫的血管。"},{"en":"Feet that contain many blood vessels can pass warmth to eggs.","zh":"含有許多血管的腳可以把溫暖傳給鳥蛋。"},{"en":"The phrase explains an internal feature, not just outer appearance.","zh":"這個短語解釋內部特徵，而不只是外表。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":19},{"front":"lack brood patches","meaning":"沒有孵卵斑","examples":[{"en":"Boobies lack brood patches, so they warm eggs with their feet.","zh":"鰹鳥沒有孵卵斑，所以用腳溫暖鳥蛋。"},{"en":"To lack brood patches means not to have the bare warm skin areas many birds use for incubation.","zh":"lack brood patches 指沒有許多鳥類用於孵蛋的裸露溫暖皮膚區域。"},{"en":"If a bird lacks brood patches, it needs another way to keep eggs warm.","zh":"如果鳥沒有孵卵斑，就需要另一種方法保持鳥蛋溫暖。"},{"en":"Boobies lack brood patches but their feet contain blood vessels for heat transfer.","zh":"鰹鳥沒有孵卵斑，但牠們的腳含有可傳熱的血管。"},{"en":"The phrase explains why their incubation method is unusual.","zh":"這個短語解釋為何牠們的孵蛋方式不尋常。"}],"source":"154 - Blue-footed Boobies.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 155":[{"front":"Seed Hunting","meaning":"種子採集","examples":[{"en":"The passage Seed Hunting discusses efforts to collect and preserve plant seeds.","zh":"文章《種子採集》討論收集和保存植物種子的努力。"},{"en":"Seed hunting means searching for plant seeds so they can be studied, stored, or protected.","zh":"種子採集指尋找植物種子，以便研究、儲存或保護它們。"},{"en":"A scientist may go seed hunting in a forest to collect seeds from rare trees.","zh":"科學家可能到森林採集種子，收集稀有樹木的種子。"},{"en":"Seed hunting can help protect plants before their natural habitats disappear.","zh":"種子採集可以在植物的自然棲息地消失前保護它們。"},{"en":"Unlike ordinary gardening, seed hunting often supports long-term conservation work.","zh":"與普通園藝不同，種子採集通常支持長期保育工作。"}],"source":"155 - Seed Hunting.pdf","sourcePage":1},{"front":"a quarter of","meaning":"四分之一的……","examples":[{"en":"A quarter of the world’s plants may vanish within the next 50 years.","zh":"世界上四分之一的植物可能在未來50年內消失。"},{"en":"A quarter of something means one out of four equal parts.","zh":"a quarter of something 指四等份中的一份。"},{"en":"If a class has 40 students, a quarter of the class is 10 students.","zh":"如果一班有40名學生，全班四分之一就是10名學生。"},{"en":"A quarter of the shops closed after rent became too high.","zh":"租金變得太高後，四分之一的商店結業了。"},{"en":"Saying a quarter of the area was flooded shows the damage was large but not total.","zh":"說四分之一的地區被水淹浸，表示損害很大但並非全部受損。"}],"source":"155 - Seed Hunting.pdf","sourcePage":1},{"front":"be set to vanish","meaning":"將會消失","examples":[{"en":"Many plant species are set to vanish within the next 50 years.","zh":"許多植物物種將會在未來50年內消失。"},{"en":"If something is set to vanish, it is expected to disappear soon.","zh":"如果某物 be set to vanish，意思是它預計很快會消失。"},{"en":"An old market may be set to vanish if the land is sold to developers.","zh":"如果土地賣給發展商，一個舊市場可能將會消失。"},{"en":"Small villages can be set to vanish when young people all move away.","zh":"當年輕人全都搬走，小村莊可能將會消失。"},{"en":"The phrase suggests a serious warning, not just a small change.","zh":"這個短語暗示嚴重警告，而不只是小改變。"}],"source":"155 - Seed Hunting.pdf","sourcePage":1},{"front":"within the next 50 years","meaning":"在未來50年內","examples":[{"en":"A quarter of the world’s plants may disappear within the next 50 years.","zh":"世界上四分之一的植物可能在未來50年內消失。"},{"en":"Within the next 50 years means before 50 years have passed from now.","zh":"within the next 50 years 指由現在起計50年過去之前。"},{"en":"Many coastal homes may face flooding within the next 50 years.","zh":"許多沿海房屋可能在未來50年內面對水浸。"},{"en":"New technology may change most jobs within the next 50 years.","zh":"新科技可能在未來50年內改變大部分工作。"},{"en":"The phrase is used when predicting a long-term future change.","zh":"這個短語用於預測長期的未來變化。"}],"source":"155 - Seed Hunting.pdf","sourcePage":1},{"front":"work against the clock","meaning":"分秒必爭；與時間競賽","examples":[{"en":"Scientists are working against the clock to preserve plant species.","zh":"科學家正分秒必爭地保存植物物種。"},{"en":"To work against the clock means to work quickly because time is limited.","zh":"work against the clock 指因時間有限而快速工作。"},{"en":"Doctors worked against the clock to treat patients after the accident.","zh":"意外後，醫生分秒必爭地治療病人。"},{"en":"A student may work against the clock when an essay deadline is near.","zh":"當作文限期臨近，學生可能要與時間競賽。"},{"en":"This phrase shows urgency because delay may cause serious loss.","zh":"這個短語表示迫切，因為拖延可能造成嚴重損失。"}],"source":"155 - Seed Hunting.pdf","sourcePage":1},{"front":"preserve the Earth’s botanical heritage","meaning":"保存地球的植物遺產","examples":[{"en":"Seed hunters work to preserve the Earth’s botanical heritage.","zh":"種子採集者努力保存地球的植物遺產。"},{"en":"To preserve the Earth’s botanical heritage means to protect the world’s plant life for the future.","zh":"preserve the Earth’s botanical heritage 指為未來保護世界植物生命。"},{"en":"Seed banks preserve the Earth’s botanical heritage by storing rare plant seeds safely.","zh":"種子庫透過安全儲存稀有植物種子來保存地球的植物遺產。"},{"en":"If forests are destroyed, it becomes harder to preserve the Earth’s botanical heritage.","zh":"如果森林被破壞，保存地球的植物遺產會變得更困難。"},{"en":"This phrase treats plants as a shared natural treasure, not just useful resources.","zh":"這個短語把植物視為人類共享的自然珍寶，而不只是有用資源。"}],"source":"155 - Seed Hunting.pdf","sourcePage":1},{"front":"botanical heritage","meaning":"植物遺產","examples":[{"en":"The Earth’s botanical heritage is threatened by plant extinction.","zh":"地球的植物遺產正受到植物滅絕威脅。"},{"en":"Botanical heritage means the plant life that a place or the world has inherited from nature.","zh":"botanical heritage 指一個地方或世界從自然承繼下來的植物生命。"},{"en":"Old forests, wild flowers, and rare crops are part of a country’s botanical heritage.","zh":"古老森林、野花和稀有作物都是一個國家植物遺產的一部分。"},{"en":"Losing botanical heritage can reduce food choices, medicines, and natural beauty.","zh":"失去植物遺產可能會減少食物選擇、藥物和自然美景。"},{"en":"A garden can teach children why botanical heritage should be protected.","zh":"花園可以教孩子為甚麼植物遺產應受到保護。"}],"source":"155 - Seed Hunting.pdf","sourcePage":1},{"front":"travel to the four corners of the globe","meaning":"走遍世界各地","examples":[{"en":"Seed hunters travel to the four corners of the globe.","zh":"種子採集者走遍世界各地。"},{"en":"To travel to the four corners of the globe means to travel to many distant parts of the world.","zh":"travel to the four corners of the globe 指前往世界上許多遙遠地方。"},{"en":"Journalists may travel to the four corners of the globe to report major stories.","zh":"記者可能走遍世界各地報道重大故事。"},{"en":"Scientists travel to the four corners of the globe because rare species live in different places.","zh":"科學家走遍世界各地，因為稀有物種生活在不同地方。"},{"en":"The phrase emphasises wide, difficult, and international travel.","zh":"這個短語強調廣泛、艱難和跨國的旅程。"}],"source":"155 - Seed Hunting.pdf","sourcePage":1},{"front":"scour jungles, forests and savannas","meaning":"搜遍叢林、森林和大草原","examples":[{"en":"Scientists scour jungles, forests and savannas for seeds.","zh":"科學家搜遍叢林、森林和大草原尋找種子。"},{"en":"To scour a place means to search it very carefully.","zh":"scour a place 指非常仔細地搜索某個地方。"},{"en":"Police may scour a neighbourhood when they are looking for a missing child.","zh":"警方尋找失蹤兒童時，可能會搜遍一個社區。"},{"en":"Researchers scour jungles, forests and savannas because useful seeds may be hidden there.","zh":"研究人員搜遍叢林、森林和大草原，因為有用種子可能藏在那裡。"},{"en":"This phrase suggests slow, careful searching over a large natural area.","zh":"這個短語暗示在廣闊自然區域中緩慢而仔細地搜尋。"}],"source":"155 - Seed Hunting.pdf","sourcePage":1},{"front":"ancient artefacts","meaning":"古代文物","examples":[{"en":"Seed hunters are not looking for ancient artefacts.","zh":"種子採集者不是在尋找古代文物。"},{"en":"Ancient artefacts are old objects made or used by people long ago.","zh":"ancient artefacts 是很久以前由人製造或使用的舊物件。"},{"en":"Museums display ancient artefacts such as tools, bowls, coins, and jewellery.","zh":"博物館展示工具、碗、硬幣和首飾等古代文物。"},{"en":"Archaeologists study ancient artefacts to understand past societies.","zh":"考古學家研究古代文物，以了解過去社會。"},{"en":"Unlike seeds, ancient artefacts mainly tell us about human history.","zh":"與種子不同，古代文物主要告訴我們人類歷史。"}],"source":"155 - Seed Hunting.pdf","sourcePage":1},{"front":"lost treasure","meaning":"失落寶藏","examples":[{"en":"The hunters are not searching for lost treasure.","zh":"這些採集者不是在尋找失落寶藏。"},{"en":"Lost treasure means valuable objects that have disappeared or been hidden.","zh":"lost treasure 指已消失或被藏起來的貴重物品。"},{"en":"Children may imagine finding lost treasure on a beach or in an old house.","zh":"孩子可能想像在海灘或舊屋找到失落寶藏。"},{"en":"Stories about lost treasure often involve maps, danger, and mystery.","zh":"關於失落寶藏的故事常涉及地圖、危險和神秘。"},{"en":"In this passage, seeds are important even though they are not shiny treasure.","zh":"在這篇文章中，種子很重要，即使它們不是閃亮的寶藏。"}],"source":"155 - Seed Hunting.pdf","sourcePage":1},{"front":"undiscovered tombs","meaning":"未被發現的古墓","examples":[{"en":"They are not looking for undiscovered tombs.","zh":"他們不是在尋找未被發現的古墓。"},{"en":"Undiscovered tombs are burial places that have not yet been found.","zh":"undiscovered tombs 指尚未被找到的埋葬地點。"},{"en":"Archaeologists may search for undiscovered tombs near ancient cities.","zh":"考古學家可能在古城附近尋找未被發現的古墓。"},{"en":"Finding undiscovered tombs can reveal how people lived and honoured the dead.","zh":"發現未被發現的古墓可以揭示人們如何生活和祭奠死者。"},{"en":"The phrase belongs more to archaeology than to seed conservation.","zh":"這個短語較屬於考古學，而不是種子保育。"}],"source":"155 - Seed Hunting.pdf","sourcePage":2},{"front":"pods","meaning":"豆莢；種子莢","examples":[{"en":"Seed hunters are looking for pods rather than treasure.","zh":"種子採集者尋找的是豆莢，而不是寶藏。"},{"en":"Pods are seed cases that hold seeds inside some plants.","zh":"pods 是某些植物中包着種子的種子莢。"},{"en":"Peas and beans grow inside pods before people eat them.","zh":"豌豆和豆類在人們食用前生長在豆莢內。"},{"en":"When pods dry and open, seeds may fall to the ground.","zh":"當豆莢變乾並裂開，種子可能落到地上。"},{"en":"For seed hunters, a small pod may contain valuable genetic material.","zh":"對種子採集者而言，一個小小的種子莢可能含有珍貴遺傳材料。"}],"source":"155 - Seed Hunting.pdf","sourcePage":2},{"front":"lack the romantic allure of","meaning":"缺乏……的浪漫吸引力","examples":[{"en":"Seed hunting may lack the romantic allure of archaeology.","zh":"種子採集可能缺乏考古學的浪漫吸引力。"},{"en":"To lack the romantic allure of something means to seem less exciting or glamorous than it.","zh":"lack the romantic allure of something 指看起來沒有某事物那麼刺激或迷人。"},{"en":"Office work may lack the romantic allure of travelling, but it can still be meaningful.","zh":"辦公室工作可能缺乏旅行的浪漫吸引力，但仍可以有意義。"},{"en":"Conservation work may lack the romantic allure of adventure films because it is slow and careful.","zh":"保育工作可能缺乏冒險電影的浪漫吸引力，因為它緩慢而仔細。"},{"en":"The phrase contrasts quiet importance with dramatic excitement.","zh":"這個短語對比低調的重要性與戲劇性的刺激感。"}],"source":"155 - Seed Hunting.pdf","sourcePage":2},{"front":"romantic allure","meaning":"浪漫吸引力","examples":[{"en":"Archaeology has a romantic allure that seed hunting may lack.","zh":"考古學有一種種子採集可能缺乏的浪漫吸引力。"},{"en":"Romantic allure is the attractive, exciting feeling that makes something seem special.","zh":"romantic allure 是令人覺得某事物特別的吸引、刺激感。"},{"en":"Old castles have a romantic allure because people imagine stories from the past.","zh":"古堡有浪漫吸引力，因為人們會想像過去的故事。"},{"en":"A job may have romantic allure from outside but still involve routine work.","zh":"一份工作從外面看可能有浪漫吸引力，但仍涉及日常重複工作。"},{"en":"Romantic allure can attract attention, but it does not always show real value.","zh":"浪漫吸引力可以吸引注意，但不一定顯示真正價值。"}],"source":"155 - Seed Hunting.pdf","sourcePage":2},{"front":"the whiff of danger","meaning":"一絲危險感","examples":[{"en":"Seed hunting may lack the whiff of danger associated with big-game hunting.","zh":"種子採集可能缺乏與獵捕大型獵物相關的一絲危險感。"},{"en":"The whiff of danger means a slight feeling that something may be risky.","zh":"the whiff of danger 指某事帶有一點可能危險的感覺。"},{"en":"A stormy night can give a camping trip the whiff of danger.","zh":"暴風雨的夜晚可以令露營之旅帶有一絲危險感。"},{"en":"Extreme sports often attract people because they carry the whiff of danger.","zh":"極限運動常吸引人，因為它們帶有一絲危險感。"},{"en":"The phrase suggests danger is present as an impression, not necessarily as a certainty.","zh":"這個短語暗示危險是一種感覺，而不一定是確定存在。"}],"source":"155 - Seed Hunting.pdf","sourcePage":2},{"front":"accompany going after","meaning":"伴隨追尋……","examples":[{"en":"A sense of danger often accompanies going after big game.","zh":"危險感常伴隨追尋大型獵物。"},{"en":"If one thing accompanies going after something, it happens together with that pursuit.","zh":"如果某事 accompanies going after something，意思是它與那種追尋同時出現。"},{"en":"Stress may accompany going after a difficult exam result.","zh":"壓力可能伴隨追求困難考試成績。"},{"en":"Careful planning should accompany going after an ambitious business goal.","zh":"仔細計劃應伴隨追求遠大商業目標。"},{"en":"The phrase links an action with the feeling or situation that comes with it.","zh":"這個短語把一個行動與隨之而來的感覺或情況連起來。"}],"source":"155 - Seed Hunting.pdf","sourcePage":2},{"front":"big game","meaning":"大型獵物","examples":[{"en":"Going after big game can seem dangerous and exciting.","zh":"追尋大型獵物可能看起來危險又刺激。"},{"en":"Big game means large wild animals hunted for sport or food.","zh":"big game 指為運動或食物而被獵捕的大型野生動物。"},{"en":"Elephants, lions, and buffalo are often described as big game.","zh":"大象、獅子和水牛常被描述為大型獵物。"},{"en":"Big game hunting can threaten wildlife if it is not strictly controlled.","zh":"如果不受嚴格管制，獵捕大型獵物可能威脅野生動物。"},{"en":"In the passage, big game is contrasted with quiet seed collecting.","zh":"在文章中，大型獵物與低調的種子採集形成對比。"}],"source":"155 - Seed Hunting.pdf","sourcePage":2},{"front":"an increasingly serious business","meaning":"越來越嚴肅重要的工作","examples":[{"en":"Seed hunting is an increasingly serious business.","zh":"種子採集是一項越來越嚴肅重要的工作。"},{"en":"An increasingly serious business is an activity that is becoming more important and urgent.","zh":"an increasingly serious business 指一項變得更重要和更迫切的活動。"},{"en":"Online safety has become an increasingly serious business for schools.","zh":"網上安全已成為學校越來越嚴肅重要的工作。"},{"en":"Recycling becomes an increasingly serious business when landfill space runs out.","zh":"當堆填區空間耗盡，回收會變成越來越嚴肅重要的工作。"},{"en":"The phrase shows that something once overlooked now deserves attention.","zh":"這個短語表示某件曾被忽視的事現在值得重視。"}],"source":"155 - Seed Hunting.pdf","sourcePage":2},{"front":"seek seeds for profit","meaning":"為牟利而尋找種子","examples":[{"en":"Some seed hunters seek seeds for profit.","zh":"有些種子採集者為牟利而尋找種子。"},{"en":"To seek seeds for profit means to look for seeds in order to make money.","zh":"seek seeds for profit 指為了賺錢而尋找種子。"},{"en":"A company may seek seeds for profit if a plant could become a new medicine.","zh":"如果一種植物可能成為新藥，公司可能為牟利而尋找種子。"},{"en":"Seeking seeds for profit can create conflict if local communities are not treated fairly.","zh":"如果本地社區沒有受到公平對待，為牟利而尋找種子可能造成衝突。"},{"en":"This purpose is different from collecting seeds only for conservation.","zh":"這個目的不同於純粹為保育而採集種子。"}],"source":"155 - Seed Hunting.pdf","sourcePage":2},{"front":"biotechnology firms","meaning":"生物科技公司","examples":[{"en":"Biotechnology firms may search for useful plant species.","zh":"生物科技公司可能尋找有用的植物物種。"},{"en":"Biotechnology firms are companies that use biology to develop products or technology.","zh":"biotechnology firms 是利用生物學開發產品或技術的公司。"},{"en":"Biotechnology firms may study plant genes to improve crops.","zh":"生物科技公司可能研究植物基因以改良作物。"},{"en":"Some biotechnology firms work with universities to develop medical treatments.","zh":"一些生物科技公司與大學合作開發醫療治療。"},{"en":"These firms can create benefits, but their work may also raise ethical questions.","zh":"這些公司可以創造好處，但其工作也可能引起倫理問題。"}],"source":"155 - Seed Hunting.pdf","sourcePage":2},{"front":"pharmaceutical companies","meaning":"製藥公司","examples":[{"en":"Pharmaceutical companies may look for seeds that could produce future drugs.","zh":"製藥公司可能尋找可以產出未來藥物的種子。"},{"en":"Pharmaceutical companies are businesses that develop and sell medicines.","zh":"pharmaceutical companies 是開發和銷售藥物的企業。"},{"en":"Pharmaceutical companies often test natural substances to see whether they can treat illness.","zh":"製藥公司常測試天然物質，看看它們能否治療疾病。"},{"en":"A new plant compound may interest pharmaceutical companies if it kills harmful bacteria.","zh":"如果新的植物化合物能殺死有害細菌，它可能吸引製藥公司。"},{"en":"Their research can be useful, but it should respect local knowledge and rights.","zh":"它們的研究可以有用，但應尊重本地知識和權利。"}],"source":"155 - Seed Hunting.pdf","sourcePage":2},{"front":"private corporations","meaning":"私人企業","examples":[{"en":"Private corporations may fund seed hunting for profit.","zh":"私人企業可能為了牟利而資助種子採集。"},{"en":"Private corporations are companies owned by private individuals or groups, not the government.","zh":"private corporations 是由私人個人或團體擁有，而非政府擁有的公司。"},{"en":"Private corporations may invest in research if they expect future profits.","zh":"如果預期將來有利潤，私人企業可能投資研究。"},{"en":"Public rules are needed when private corporations use natural resources.","zh":"當私人企業使用自然資源時，需要公共規則。"},{"en":"The phrase often contrasts business interests with public or conservation goals.","zh":"這個短語常把商業利益與公共或保育目標作對比。"}],"source":"155 - Seed Hunting.pdf","sourcePage":3},{"front":"on the lookout for","meaning":"留意尋找……","examples":[{"en":"Companies are on the lookout for species with commercial potential.","zh":"公司正留意尋找具有商業潛力的物種。"},{"en":"To be on the lookout for something means to watch carefully for it.","zh":"be on the lookout for something 指仔細留意並尋找某物。"},{"en":"Parents may be on the lookout for signs that a child is being bullied.","zh":"父母可能留意尋找孩子被欺凌的跡象。"},{"en":"Shops are on the lookout for fake banknotes during busy seasons.","zh":"商店在繁忙季節會留意尋找假鈔。"},{"en":"The phrase suggests active attention, not accidental discovery.","zh":"這個短語表示主動注意，而不是偶然發現。"}],"source":"155 - Seed Hunting.pdf","sourcePage":3},{"front":"yield the drugs or crops of the future","meaning":"產出未來的藥物或農作物","examples":[{"en":"Some plant species may yield the drugs or crops of the future.","zh":"一些植物物種可能產出未來的藥物或農作物。"},{"en":"To yield the drugs or crops of the future means to produce plants or substances useful later.","zh":"yield the drugs or crops of the future 指產生將來有用的植物或物質。"},{"en":"A desert plant may yield the crops of the future if it survives with little water.","zh":"如果一種沙漠植物能用很少水存活，它可能產出未來的農作物。"},{"en":"A rainforest seed may yield future drugs if it contains a useful chemical.","zh":"如果雨林種子含有有用化學物質，它可能產出未來藥物。"},{"en":"This phrase shows that ordinary plants may have unknown future value.","zh":"這個短語顯示普通植物可能有未知的未來價值。"}],"source":"155 - Seed Hunting.pdf","sourcePage":3},{"front":"collect to conserve","meaning":"為保育而採集","examples":[{"en":"Some scientists collect seeds to conserve endangered plants.","zh":"有些科學家為保育瀕危植物而採集種子。"},{"en":"To collect to conserve means to gather something in order to protect it.","zh":"collect to conserve 指為了保護某物而收集它。"},{"en":"Museums collect old photographs to conserve community history.","zh":"博物館收集舊照片，以保存社區歷史。"},{"en":"Scientists collect to conserve when a species may disappear from the wild.","zh":"當一個物種可能從野外消失，科學家會為保育而採集。"},{"en":"This purpose is protective rather than commercial.","zh":"這個目的屬於保護性，而不是商業性。"}],"source":"155 - Seed Hunting.pdf","sourcePage":3},{"front":"halt the sad slide into extinction","meaning":"阻止令人惋惜的滅絕趨勢","examples":[{"en":"Seed conservation aims to halt the sad slide into extinction.","zh":"種子保育旨在阻止令人惋惜的滅絕趨勢。"},{"en":"To halt the sad slide into extinction means to stop species from gradually disappearing forever.","zh":"halt the sad slide into extinction 指阻止物種逐步永遠消失。"},{"en":"Protecting wetlands can halt the sad slide into extinction for some birds.","zh":"保護濕地可以為一些鳥類阻止令人惋惜的滅絕趨勢。"},{"en":"Without action, habitat loss may make it harder to halt this sad slide.","zh":"如果沒有行動，棲息地喪失可能令阻止這種趨勢更困難。"},{"en":"The phrase expresses both urgency and regret.","zh":"這個短語同時表達迫切和惋惜。"}],"source":"155 - Seed Hunting.pdf","sourcePage":3},{"front":"slide into extinction","meaning":"逐步走向滅絕","examples":[{"en":"Many plant species face a sad slide into extinction.","zh":"許多植物物種面對令人惋惜的逐步走向滅絕。"},{"en":"A slide into extinction is a gradual movement towards complete disappearance.","zh":"a slide into extinction 指逐漸走向完全消失的過程。"},{"en":"A local fish may slide into extinction if rivers remain polluted.","zh":"如果河流持續污染，本地魚類可能逐步走向滅絕。"},{"en":"The slide into extinction can be slow, so people may not notice it early.","zh":"逐步走向滅絕可能很慢，所以人們未必及早察覺。"},{"en":"The phrase suggests a downward process, not a sudden single event.","zh":"這個短語暗示下降過程，而不是突然的單一事件。"}],"source":"155 - Seed Hunting.pdf","sourcePage":3},{"front":"plant species","meaning":"植物物種","examples":[{"en":"Many plant species are threatened with extinction.","zh":"許多植物物種正受到滅絕威脅。"},{"en":"Plant species are different kinds of plants with shared features.","zh":"plant species 是具有共同特徵的不同植物種類。"},{"en":"Roses, wheat, and oak trees are different plant species.","zh":"玫瑰、小麥和橡樹是不同植物物種。"},{"en":"Losing one plant species can affect insects, animals, and people.","zh":"失去一個植物物種可能影響昆蟲、動物和人類。"},{"en":"Scientists identify plant species so they can study and protect them accurately.","zh":"科學家辨認植物物種，以便準確研究和保護它們。"}],"source":"155 - Seed Hunting.pdf","sourcePage":3},{"front":"pioneers of","meaning":"……的先驅","examples":[{"en":"John Tradescant was among the pioneers of seed hunting.","zh":"John Tradescant 是種子採集的先驅之一。"},{"en":"Pioneers of an activity are the early people who helped develop it.","zh":"pioneers of an activity 指早期幫助發展某項活動的人。"},{"en":"The pioneers of online learning tested methods before most schools used them.","zh":"網上學習的先驅在大多數學校使用前已測試方法。"},{"en":"Pioneers of medicine often worked without the tools doctors have today.","zh":"醫學先驅常在沒有現今醫生工具的情況下工作。"},{"en":"The phrase gives credit to people who began something important.","zh":"這個短語表揚開創重要事物的人。"}],"source":"155 - Seed Hunting.pdf","sourcePage":3},{"front":"botanical treasure hunt","meaning":"植物尋寶","examples":[{"en":"Early plant collecting was a kind of botanical treasure hunt.","zh":"早期植物採集是一種植物尋寶。"},{"en":"A botanical treasure hunt is a search for rare or valuable plants.","zh":"botanical treasure hunt 指尋找稀有或有價值植物的活動。"},{"en":"Children can enjoy a botanical treasure hunt by finding different leaves in a park.","zh":"孩子可以在公園尋找不同葉子，享受植物尋寶。"},{"en":"Explorers treated plant collecting as a botanical treasure hunt when new species were unknown.","zh":"當新物種仍未知，探險者把植物採集視為植物尋寶。"},{"en":"The phrase makes plant searching sound adventurous and exciting.","zh":"這個短語令尋找植物聽起來有冒險感和刺激感。"}],"source":"155 - Seed Hunting.pdf","sourcePage":3},{"front":"English royal gardener","meaning":"英國皇家園丁","examples":[{"en":"John Tradescant was an English royal gardener.","zh":"John Tradescant 是一名英國皇家園丁。"},{"en":"An English royal gardener was a gardener who worked for the English royal family.","zh":"English royal gardener 指為英國王室工作的園丁。"},{"en":"A royal gardener might design gardens, choose plants, and care for rare flowers.","zh":"皇家園丁可能設計花園、選擇植物和照顧稀有花卉。"},{"en":"An English royal gardener could gain access to wealthy patrons and overseas collections.","zh":"英國皇家園丁可能接觸富有贊助者和海外收藏。"},{"en":"The phrase identifies both the person’s job and his connection to royalty.","zh":"這個短語同時指出人物的職業和他與王室的關係。"}],"source":"155 - Seed Hunting.pdf","sourcePage":3},{"front":"bring back","meaning":"帶回","examples":[{"en":"Tradescant brought back plants and seeds from his journeys abroad.","zh":"Tradescant 從海外旅程帶回植物和種子。"},{"en":"To bring back something means to return with it from another place.","zh":"bring back something 指從另一個地方返回時帶着某物。"},{"en":"Travellers often bring back gifts for family after a trip.","zh":"旅客旅行後常為家人帶回禮物。"},{"en":"Scientists may bring back samples so they can study them in a laboratory.","zh":"科學家可能帶回樣本，以便在實驗室研究。"},{"en":"This phrase focuses on taking something home after travelling.","zh":"這個短語重點是旅行後把某物帶回來。"}],"source":"155 - Seed Hunting.pdf","sourcePage":3},{"front":"journeys abroad","meaning":"海外旅程","examples":[{"en":"He collected plants and seeds during his journeys abroad.","zh":"他在海外旅程中收集植物和種子。"},{"en":"Journeys abroad are trips to foreign countries.","zh":"journeys abroad 指前往外國的旅程。"},{"en":"Students may learn independence during their journeys abroad.","zh":"學生可能在海外旅程中學會獨立。"},{"en":"Journeys abroad can expose travellers to new languages, foods, and customs.","zh":"海外旅程可以讓旅客接觸新語言、食物和習俗。"},{"en":"The phrase is more formal than simply saying trips overseas.","zh":"這個短語比簡單說 trips overseas 更正式。"}],"source":"155 - Seed Hunting.pdf","sourcePage":4},{"front":"in the early 1600s","meaning":"在17世紀初","examples":[{"en":"John Tradescant collected seeds in the early 1600s.","zh":"John Tradescant 在17世紀初收集種子。"},{"en":"In the early 1600s means during the first part of the seventeenth century.","zh":"in the early 1600s 指17世紀的早期。"},{"en":"Many European voyages expanded in the early 1600s.","zh":"許多歐洲航海旅程在17世紀初擴展。"},{"en":"A building from the early 1600s may be more than 400 years old.","zh":"來自17世紀初的建築可能已有400多年歷史。"},{"en":"The phrase gives a historical time period, not an exact year.","zh":"這個短語提供歷史時段，而不是確切年份。"}],"source":"155 - Seed Hunting.pdf","sourcePage":4},{"front":"English botanist","meaning":"英國植物學家","examples":[{"en":"Sir Joseph Banks was an English botanist.","zh":"Sir Joseph Banks 是一名英國植物學家。"},{"en":"An English botanist is a plant scientist from England.","zh":"English botanist 指來自英格蘭的植物科學家。"},{"en":"A botanist studies how plants grow, reproduce, and survive.","zh":"植物學家研究植物如何生長、繁殖和生存。"},{"en":"An English botanist in the past might travel widely to collect unknown plants.","zh":"過去的英國植物學家可能四處旅行收集未知植物。"},{"en":"The phrase tells us both the person’s nationality and scientific field.","zh":"這個短語告訴我們人物的國籍和科學領域。"}],"source":"155 - Seed Hunting.pdf","sourcePage":4},{"front":"first director of","meaning":"……的首任總監","examples":[{"en":"Sir Joseph Banks was the first director of the Royal Botanic Gardens at Kew.","zh":"Sir Joseph Banks 是邱園皇家植物園的首任總監。"},{"en":"The first director of an organisation is the first person to lead it officially.","zh":"the first director of an organisation 指第一位正式領導該機構的人。"},{"en":"The first director of a school shapes its rules, culture, and early plans.","zh":"一所學校的首任總監會塑造其規則、文化和早期計劃。"},{"en":"Being the first director of a museum can influence what it collects.","zh":"成為博物館的首任總監可能影響其收藏方向。"},{"en":"The phrase highlights a founding leadership role.","zh":"這個短語強調創始領導角色。"}],"source":"155 - Seed Hunting.pdf","sourcePage":4},{"front":"Royal Botanic Gardens at Kew","meaning":"邱園皇家植物園","examples":[{"en":"Sir Joseph Banks was linked to the Royal Botanic Gardens at Kew.","zh":"Sir Joseph Banks 與邱園皇家植物園有關。"},{"en":"The Royal Botanic Gardens at Kew is a famous British centre for plant study and conservation.","zh":"Royal Botanic Gardens at Kew 是英國著名的植物研究和保育中心。"},{"en":"Visitors can learn about rare plants at the Royal Botanic Gardens at Kew.","zh":"遊客可以在邱園皇家植物園學習稀有植物知識。"},{"en":"Researchers there help protect plant diversity through science and seed collections.","zh":"那裡的研究人員透過科學和種子收藏幫助保護植物多樣性。"},{"en":"The name often appears in discussions of botany and conservation.","zh":"這個名稱常出現在植物學和保育討論中。"}],"source":"155 - Seed Hunting.pdf","sourcePage":4},{"front":"travel with","meaning":"與……同行","examples":[{"en":"Joseph Banks travelled with Captain James Cook.","zh":"Joseph Banks 與 James Cook 船長同行。"},{"en":"To travel with someone means to go on a journey together.","zh":"travel with someone 指與某人一起踏上旅程。"},{"en":"A student may travel with classmates on a school trip.","zh":"學生可能在學校旅行中與同學同行。"},{"en":"Scientists travel with local guides when they enter unfamiliar forests.","zh":"科學家進入陌生森林時會與本地嚮導同行。"},{"en":"The phrase shows companionship during a journey.","zh":"這個短語表示旅程中的同行關係。"}],"source":"155 - Seed Hunting.pdf","sourcePage":4},{"front":"voyages","meaning":"航海旅程","examples":[{"en":"Joseph Banks travelled with Captain Cook on his voyages.","zh":"Joseph Banks 在 Cook 船長的航海旅程中與他同行。"},{"en":"Voyages are long journeys, especially by sea.","zh":"voyages 指長途旅程，尤其是海上旅程。"},{"en":"Early voyages across oceans were dangerous and slow.","zh":"早期橫越海洋的航海旅程危險而緩慢。"},{"en":"Scientific voyages allowed researchers to collect plants, animals, and maps.","zh":"科學航海旅程讓研究人員收集植物、動物和地圖。"},{"en":"The word sounds more historical and formal than trips.","zh":"這個詞比 trips 更具歷史感和正式感。"}],"source":"155 - Seed Hunting.pdf","sourcePage":4},{"front":"near the end of","meaning":"接近……末期","examples":[{"en":"Banks travelled with Cook near the end of the 18th century.","zh":"Banks 在接近18世紀末期時與 Cook 同行。"},{"en":"Near the end of a period means close to the time when that period finished.","zh":"near the end of a period 指接近某段時期結束的時間。"},{"en":"Students often feel tired near the end of an exam.","zh":"學生在接近考試末段時常感到疲倦。"},{"en":"Near the end of winter, flowers may begin to appear.","zh":"接近冬季末期時，花朵可能開始出現。"},{"en":"The phrase gives an approximate time, not an exact date.","zh":"這個短語提供大約時間，而不是確切日期。"}],"source":"155 - Seed Hunting.pdf","sourcePage":4},{"front":"be driven to","meaning":"受驅使去……","examples":[{"en":"Banks was driven to expand his collections.","zh":"Banks 受到驅使去擴充他的收藏。"},{"en":"To be driven to do something means to feel strongly motivated or forced to do it.","zh":"be driven to do something 指受到強烈動機或壓力去做某事。"},{"en":"A student may be driven to study harder after failing a test.","zh":"學生考試不合格後，可能受到驅使去更努力學習。"},{"en":"Rising costs can drive families to reduce spending.","zh":"成本上升可以驅使家庭減少開支。"},{"en":"The phrase shows a strong cause behind an action.","zh":"這個短語顯示行動背後有強烈原因。"}],"source":"155 - Seed Hunting.pdf","sourcePage":4},{"front":"expand his collections","meaning":"擴充他的收藏","examples":[{"en":"Banks wanted to expand his collections of plants and seeds.","zh":"Banks 想擴充他的植物和種子收藏。"},{"en":"To expand his collections means to add more items to what he already had.","zh":"expand his collections 指在他已有的收藏中加入更多物品。"},{"en":"A museum may expand its collections by buying old photographs.","zh":"博物館可能透過購買舊照片來擴充收藏。"},{"en":"A teacher can expand his collections of examples to help more students.","zh":"老師可以擴充他的例句收藏，以幫助更多學生。"},{"en":"The phrase suggests growth in number, range, or variety.","zh":"這個短語暗示數量、範圍或種類上的增加。"}],"source":"155 - Seed Hunting.pdf","sourcePage":4},{"front":"at his own expense","meaning":"自費","examples":[{"en":"Banks sent botanists around the world at his own expense.","zh":"Banks 自費派植物學家到世界各地。"},{"en":"At his own expense means using his own money rather than someone else’s.","zh":"at his own expense 指使用自己的金錢，而不是別人的錢。"},{"en":"A manager repaired the community printer at his own expense.","zh":"一名經理自費修理社區打印機。"},{"en":"Volunteers sometimes travel at their own expense to help after disasters.","zh":"義工有時自費前往災區幫忙。"},{"en":"The phrase often shows personal commitment or sacrifice.","zh":"這個短語常顯示個人投入或犧牲。"}],"source":"155 - Seed Hunting.pdf","sourcePage":4},{"front":"heady days of exploration and discovery","meaning":"令人興奮的探索與發現年代","examples":[{"en":"The heady days of exploration and discovery may be over.","zh":"令人興奮的探索與發現年代可能已經結束。"},{"en":"Heady days are exciting times full of energy, hope, or success.","zh":"heady days 指充滿活力、希望或成功的興奮時期。"},{"en":"The heady days of a new business can make founders work late happily.","zh":"新公司令人興奮的早期日子可以令創辦人樂意工作到很晚。"},{"en":"During the heady days of discovery, people may overlook practical risks.","zh":"在令人興奮的發現年代，人們可能忽略實際風險。"},{"en":"The phrase suggests an exciting period that may not last forever.","zh":"這個短語暗示一段令人興奮但未必永久持續的時期。"}],"source":"155 - Seed Hunting.pdf","sourcePage":5},{"front":"be replaced by","meaning":"被……取代","examples":[{"en":"Those days have been replaced by a pressing need to preserve nature.","zh":"那些日子已被保存自然的迫切需要取代。"},{"en":"If one thing is replaced by another, the second thing takes its place.","zh":"如果 one thing is replaced by another，意思是第二樣東西取代了第一樣。"},{"en":"Paper tickets have been replaced by electronic tickets in many stations.","zh":"在許多車站，紙本車票已被電子車票取代。"},{"en":"Old habits may be replaced by healthier routines after illness.","zh":"生病後，舊習慣可能被更健康的日常安排取代。"},{"en":"The phrase shows a change from one situation to another.","zh":"這個短語表示從一種情況轉變為另一種情況。"}],"source":"155 - Seed Hunting.pdf","sourcePage":5},{"front":"a pressing need to","meaning":"迫切需要去……","examples":[{"en":"There is a pressing need to preserve our natural history.","zh":"我們迫切需要保存自己的自然歷史。"},{"en":"A pressing need to do something is an urgent and important need.","zh":"a pressing need to do something 指迫切而重要的需要。"},{"en":"There is a pressing need to repair the bridge before it becomes unsafe.","zh":"在橋樑變得不安全前，迫切需要修理它。"},{"en":"A pressing need to hire nurses appears when hospitals become overcrowded.","zh":"當醫院過度擠迫，就會出現迫切需要聘請護士。"},{"en":"The phrase shows that action should not be delayed.","zh":"這個短語表示行動不應被拖延。"}],"source":"155 - Seed Hunting.pdf","sourcePage":5},{"front":"preserve our natural history","meaning":"保存我們的自然歷史","examples":[{"en":"Scientists now work to preserve our natural history for the future.","zh":"科學家現在努力為未來保存我們的自然歷史。"},{"en":"To preserve our natural history means to protect records and examples of nature’s past and present.","zh":"preserve our natural history 指保護自然過去和現在的記錄與例子。"},{"en":"Museums preserve our natural history by keeping fossils, plants, and animal specimens.","zh":"博物館透過保存化石、植物和動物標本來保存我們的自然歷史。"},{"en":"Protecting old forests helps preserve our natural history outside museums.","zh":"保護古老森林有助在博物館以外保存我們的自然歷史。"},{"en":"The phrase connects conservation with memory and learning.","zh":"這個短語把保育與記憶和學習連起來。"}],"source":"155 - Seed Hunting.pdf","sourcePage":5},{"front":"modern mission","meaning":"現代使命","examples":[{"en":"This modern mission drives today’s seed hunters.","zh":"這個現代使命推動今天的種子採集者。"},{"en":"A modern mission is a present-day purpose or task that guides people’s work.","zh":"modern mission 指引導人們工作的當代目的或任務。"},{"en":"Reducing plastic waste has become a modern mission for many schools.","zh":"減少塑膠廢物已成為許多學校的現代使命。"},{"en":"A hospital’s modern mission may include both treatment and public education.","zh":"醫院的現代使命可能包括治療和公共教育。"},{"en":"The phrase suggests a clear goal shaped by current problems.","zh":"這個短語暗示由當前問題塑造的清晰目標。"}],"source":"155 - Seed Hunting.pdf","sourcePage":5},{"front":"good-natured Dutchman","meaning":"性格和善的荷蘭人","examples":[{"en":"Dr Michiel van Slageren is described as a good-natured Dutchman.","zh":"Michiel van Slageren 博士被描述為一名性格和善的荷蘭人。"},{"en":"A good-natured Dutchman is a kind and friendly man from the Netherlands.","zh":"good-natured Dutchman 指來自荷蘭、親切友善的男子。"},{"en":"A good-natured neighbour smiles, helps others, and rarely complains.","zh":"性格和善的鄰居會微笑、幫助別人，而且很少抱怨。"},{"en":"Describing someone as good-natured makes the person seem approachable.","zh":"把某人描述為 good-natured，會令人覺得他平易近人。"},{"en":"The phrase gives both personality and nationality.","zh":"這個短語同時提供性格和國籍。"}],"source":"155 - Seed Hunting.pdf","sourcePage":5},{"front":"sport a wide-brimmed hat","meaning":"戴着寬邊帽","examples":[{"en":"He often sports a wide-brimmed hat in the field.","zh":"他在野外常戴着寬邊帽。"},{"en":"To sport a wide-brimmed hat means to wear one in a noticeable way.","zh":"sport a wide-brimmed hat 指以顯眼方式戴着寬邊帽。"},{"en":"A farmer may sport a wide-brimmed hat to protect himself from the sun.","zh":"農夫可能戴着寬邊帽保護自己免受日曬。"},{"en":"Travellers sport wide-brimmed hats when they spend long hours outdoors.","zh":"旅客長時間在戶外時會戴着寬邊帽。"},{"en":"The verb sport makes the clothing sound distinctive or easily noticed.","zh":"動詞 sport 令衣物聽起來有特色或容易被注意到。"}],"source":"155 - Seed Hunting.pdf","sourcePage":5},{"front":"in the field","meaning":"在野外；在實地","examples":[{"en":"Seed hunters often work in the field.","zh":"種子採集者常在野外工作。"},{"en":"In the field means outside a classroom, office, or laboratory, doing practical work.","zh":"in the field 指在課室、辦公室或實驗室以外做實際工作。"},{"en":"Biology students learn more in the field when they observe real plants.","zh":"生物學生在實地觀察真實植物時會學得更多。"},{"en":"Engineers test equipment in the field before using it widely.","zh":"工程師在廣泛使用設備前會在實地測試。"},{"en":"The phrase highlights real-world work rather than theory alone.","zh":"這個短語強調真實世界的工作，而不只是理論。"}],"source":"155 - Seed Hunting.pdf","sourcePage":5},{"front":"be mistaken for","meaning":"被誤認為","examples":[{"en":"He could easily be mistaken for Indiana Jones.","zh":"他很容易被誤認為是 Indiana Jones。"},{"en":"To be mistaken for someone means to be wrongly thought to be that person or type of person.","zh":"be mistaken for someone 指被錯誤地認為是某人或某類人。"},{"en":"A teacher in casual clothes may be mistaken for a student.","zh":"穿便服的老師可能被誤認為學生。"},{"en":"A harmless insect can be mistaken for a dangerous one if people panic.","zh":"如果人們驚慌，無害昆蟲可能被誤認為危險昆蟲。"},{"en":"The phrase shows incorrect identification based on appearance.","zh":"這個短語表示基於外表的錯誤辨認。"}],"source":"155 - Seed Hunting.pdf","sourcePage":5},{"front":"cinematic hero","meaning":"電影英雄","examples":[{"en":"Indiana Jones is a famous cinematic hero.","zh":"Indiana Jones 是著名的電影英雄。"},{"en":"A cinematic hero is a brave or memorable main character in films.","zh":"cinematic hero 指電影中勇敢或令人難忘的主角。"},{"en":"A cinematic hero often faces danger, solves problems, and protects others.","zh":"電影英雄常面對危險、解決問題並保護他人。"},{"en":"Children may admire a cinematic hero because the character seems courageous.","zh":"孩子可能崇拜電影英雄，因為角色看起來很勇敢。"},{"en":"The phrase belongs to the world of movies rather than real life.","zh":"這個短語屬於電影世界，而不是現實生活。"}],"source":"155 - Seed Hunting.pdf","sourcePage":5},{"front":"Millennium Seed Bank","meaning":"千禧種子庫","examples":[{"en":"The Millennium Seed Bank is an international conservation project.","zh":"千禧種子庫是一項國際保育項目。"},{"en":"The Millennium Seed Bank is a place where seeds are stored to protect plant species.","zh":"Millennium Seed Bank 是儲存種子以保護植物物種的地方。"},{"en":"Scientists send rare seeds to the Millennium Seed Bank for safe long-term storage.","zh":"科學家把稀有種子送到千禧種子庫作安全長期儲存。"},{"en":"If a wild plant disappears, seeds in the Millennium Seed Bank may help restore it.","zh":"如果一種野生植物消失，千禧種子庫中的種子可能幫助恢復它。"},{"en":"The name represents a major effort to protect plant diversity.","zh":"這個名稱代表保護植物多樣性的重大努力。"}],"source":"155 - Seed Hunting.pdf","sourcePage":5},{"front":"international conservation project","meaning":"國際保育項目","examples":[{"en":"The Millennium Seed Bank is an international conservation project.","zh":"千禧種子庫是一項國際保育項目。"},{"en":"An international conservation project protects nature through cooperation between countries.","zh":"international conservation project 指透過國家之間合作保護自然的項目。"},{"en":"Saving sea turtles can become an international conservation project when they cross borders.","zh":"當海龜跨越國界，拯救海龜可以成為國際保育項目。"},{"en":"Such a project needs scientists, funding, data sharing, and local support.","zh":"這類項目需要科學家、資金、數據分享和本地支持。"},{"en":"The phrase shows that environmental protection is not limited to one country.","zh":"這個短語顯示環境保護不限於一個國家。"}],"source":"155 - Seed Hunting.pdf","sourcePage":6},{"front":"aim to protect","meaning":"旨在保護","examples":[{"en":"The project aims to protect endangered wild plants.","zh":"這個項目旨在保護瀕危野生植物。"},{"en":"To aim to protect something means to have protection as the main goal.","zh":"aim to protect something 指以保護某物為主要目標。"},{"en":"New traffic rules aim to protect children near schools.","zh":"新交通規則旨在保護學校附近的兒童。"},{"en":"Vaccination programmes aim to protect communities from serious disease.","zh":"疫苗接種計劃旨在保護社區免受嚴重疾病影響。"},{"en":"The phrase clearly states the purpose of an action or plan.","zh":"這個短語清楚說明行動或計劃的目的。"}],"source":"155 - Seed Hunting.pdf","sourcePage":6},{"front":"endangered wild plant species","meaning":"瀕危野生植物物種","examples":[{"en":"The bank protects endangered wild plant species.","zh":"種子庫保護瀕危野生植物物種。"},{"en":"Endangered wild plant species are wild plants that may soon disappear forever.","zh":"endangered wild plant species 指可能很快永遠消失的野生植物。"},{"en":"An endangered wild plant species may grow only in one mountain valley.","zh":"一種瀕危野生植物物種可能只生長在一個山谷中。"},{"en":"Farming, roads, and pollution can put endangered wild plant species at risk.","zh":"農業、道路和污染可能令瀕危野生植物物種受威脅。"},{"en":"The phrase focuses on plants in nature, not garden varieties.","zh":"這個短語重點是自然中的植物，而不是園藝品種。"}],"source":"155 - Seed Hunting.pdf","sourcePage":6},{"front":"group’s headquarters","meaning":"團隊總部","examples":[{"en":"The group’s headquarters are at Wakehurst Place.","zh":"該團隊總部位於 Wakehurst Place。"},{"en":"A group’s headquarters is the main place where an organisation is based and managed.","zh":"group’s headquarters 指一個組織所在和管理的主要地點。"},{"en":"A charity’s headquarters may handle donations, staff, and planning.","zh":"慈善機構的總部可能處理捐款、員工和計劃。"},{"en":"Visitors often contact a group’s headquarters for official information.","zh":"訪客常聯絡團隊總部以取得官方資訊。"},{"en":"The phrase refers to the centre of operations.","zh":"這個短語指營運中心。"}],"source":"155 - Seed Hunting.pdf","sourcePage":6},{"front":"glass-and-concrete structure","meaning":"玻璃和混凝土建築","examples":[{"en":"The headquarters are in a modern glass-and-concrete structure.","zh":"總部位於一座現代玻璃和混凝土建築內。"},{"en":"A glass-and-concrete structure is a building made mainly with glass and concrete.","zh":"glass-and-concrete structure 指主要由玻璃和混凝土建成的建築。"},{"en":"Many modern offices use glass-and-concrete structures to look open and strong.","zh":"許多現代辦公室使用玻璃和混凝土建築，以顯得開放而堅固。"},{"en":"A glass-and-concrete structure may need careful design to control heat.","zh":"玻璃和混凝土建築可能需要仔細設計以控制熱力。"},{"en":"The phrase describes the materials and modern appearance of a building.","zh":"這個短語描述建築材料和現代外觀。"}],"source":"155 - Seed Hunting.pdf","sourcePage":6},{"front":"200-hectare estate","meaning":"200公頃莊園","examples":[{"en":"The building stands on a 200-hectare estate.","zh":"這座建築位於一個200公頃莊園上。"},{"en":"A 200-hectare estate is a very large piece of land measuring 200 hectares.","zh":"200-hectare estate 指面積達200公頃的一大片土地。"},{"en":"A school on a 200-hectare estate would have space for fields, gardens, and forests.","zh":"位於200公頃莊園上的學校會有空間容納田地、花園和森林。"},{"en":"Managing a 200-hectare estate requires staff, maps, and long-term planning.","zh":"管理一個200公頃莊園需要員工、地圖和長期計劃。"},{"en":"The phrase gives a clear sense of large land size.","zh":"這個短語清楚表達土地面積很大。"}],"source":"155 - Seed Hunting.pdf","sourcePage":6},{"front":"West Sussex countryside","meaning":"西薩塞克斯郊區","examples":[{"en":"The Millennium Seed Bank is located in the West Sussex countryside.","zh":"千禧種子庫位於西薩塞克斯郊區。"},{"en":"The West Sussex countryside means rural areas in the English county of West Sussex.","zh":"West Sussex countryside 指英格蘭西薩塞克斯郡的鄉郊地區。"},{"en":"The West Sussex countryside may include fields, villages, gardens, and woodland.","zh":"西薩塞克斯郊區可能包括田野、村莊、花園和林地。"},{"en":"A research centre in the West Sussex countryside can have space for plant collections.","zh":"位於西薩塞克斯郊區的研究中心可以有空間收藏植物。"},{"en":"The phrase gives both location and rural setting.","zh":"這個短語同時提供地點和鄉郊環境。"}],"source":"155 - Seed Hunting.pdf","sourcePage":6},{"front":"underground vaults","meaning":"地下儲藏庫","examples":[{"en":"The seeds are stored in underground vaults.","zh":"種子被儲存在地下儲藏庫中。"},{"en":"Underground vaults are secure storage rooms built below ground level.","zh":"underground vaults 指建於地下的安全儲存室。"},{"en":"Banks may keep valuable records in underground vaults.","zh":"銀行可能把貴重記錄保存在地下儲藏庫。"},{"en":"Underground vaults protect seeds from heat, fire, and sudden weather changes.","zh":"地下儲藏庫可保護種子免受高溫、火災和突發天氣變化影響。"},{"en":"The phrase suggests safety, coolness, and long-term storage.","zh":"這個短語暗示安全、低溫和長期儲存。"}],"source":"155 - Seed Hunting.pdf","sourcePage":6},{"front":"dried seeds","meaning":"乾燥種子","examples":[{"en":"The underground vaults contain millions of dried seeds.","zh":"地下儲藏庫中存放着數以百萬計的乾燥種子。"},{"en":"Dried seeds are seeds with much of their moisture removed.","zh":"dried seeds 指已去除大部分水分的種子。"},{"en":"Farmers may keep dried seeds for planting in the next season.","zh":"農民可能保存乾燥種子，以便下一季種植。"},{"en":"Drying seeds can help prevent mould and slow decay.","zh":"乾燥種子可以幫助防止發霉並減慢腐壞。"},{"en":"The phrase describes seeds prepared for storage, not fresh fruit seeds.","zh":"這個短語描述為儲存而處理的種子，而不是新鮮水果種子。"}],"source":"155 - Seed Hunting.pdf","sourcePage":6},{"front":"be stored at","meaning":"在……溫度下保存","examples":[{"en":"The seeds are stored at −20°C.","zh":"種子在攝氏零下20度保存。"},{"en":"To be stored at a temperature means to be kept under that temperature condition.","zh":"be stored at a temperature 指在某個溫度條件下保存。"},{"en":"Vaccines must be stored at the correct temperature to remain effective.","zh":"疫苗必須在正確溫度下保存，才能保持有效。"},{"en":"Food stored at unsafe temperatures may spoil quickly.","zh":"食物若在不安全溫度下保存，可能很快變壞。"},{"en":"The phrase is often used for scientific or careful storage.","zh":"這個短語常用於科學或謹慎的儲存。"}],"source":"155 - Seed Hunting.pdf","sourcePage":6},{"front":"survive for centuries","meaning":"存活數百年","examples":[{"en":"The seeds are stored so that they can survive for centuries.","zh":"種子以這種方式儲存，使它們可以存活數百年。"},{"en":"To survive for centuries means to remain alive or usable for hundreds of years.","zh":"survive for centuries 指保持生命或可使用狀態達數百年。"},{"en":"Some old buildings survive for centuries because they are carefully maintained.","zh":"一些古老建築因受到細心維修而存留數百年。"},{"en":"Seeds may survive for centuries if they are dried and frozen properly.","zh":"如果種子被正確乾燥和冷凍，它們可能存活數百年。"},{"en":"The phrase emphasises an extremely long period of survival.","zh":"這個短語強調極長時間的存活。"}],"source":"155 - Seed Hunting.pdf","sourcePage":6},{"front":"species represented","meaning":"被收錄的物種","examples":[{"en":"Thousands of species are represented in the collection.","zh":"收藏中有數以千計被收錄的物種。"},{"en":"If species are represented, examples of those species are included.","zh":"如果 species are represented，意思是那些物種有樣本被包括在內。"},{"en":"A library display may have many countries represented through books.","zh":"圖書館展覽可能透過書籍收錄許多國家。"},{"en":"A seed bank is stronger when more plant species are represented.","zh":"當更多植物物種被收錄，種子庫會更強大。"},{"en":"The phrase focuses on inclusion within a collection or group.","zh":"這個短語重點是在收藏或群體中的包含情況。"}],"source":"155 - Seed Hunting.pdf","sourcePage":7},{"front":"virtually all of","meaning":"幾乎全部","examples":[{"en":"The collection includes virtually all of Britain’s native seed-bearing plants.","zh":"這個收藏包括英國幾乎全部本土結籽植物。"},{"en":"Virtually all of something means almost all of it.","zh":"virtually all of something 指幾乎全部某物。"},{"en":"Virtually all of the seats were full before the concert began.","zh":"音樂會開始前，幾乎全部座位都坐滿了。"},{"en":"Virtually all of the students understood after the teacher gave examples.","zh":"老師給出例子後，幾乎全部學生都明白了。"},{"en":"The phrase allows a tiny exception while still showing near completeness.","zh":"這個短語容許有極少例外，同時表示接近完整。"}],"source":"155 - Seed Hunting.pdf","sourcePage":7},{"front":"native seed-bearing plants","meaning":"本土結籽植物","examples":[{"en":"The bank contains Britain’s native seed-bearing plants.","zh":"種子庫收錄英國本土結籽植物。"},{"en":"Native seed-bearing plants are local plants that produce seeds naturally in a place.","zh":"native seed-bearing plants 指在某地自然生長並產生種子的本地植物。"},{"en":"Oak trees and wild grasses can be native seed-bearing plants in some regions.","zh":"橡樹和野草在某些地區可以是本土結籽植物。"},{"en":"Protecting native seed-bearing plants helps preserve local ecosystems.","zh":"保護本土結籽植物有助保存本地生態系統。"},{"en":"The phrase excludes plants introduced recently from other countries.","zh":"這個短語不包括最近從其他國家引入的植物。"}],"source":"155 - Seed Hunting.pdf","sourcePage":7},{"front":"the most complete such collection","meaning":"同類收藏中最完整的一個","examples":[{"en":"It is the most complete such collection of any country’s flora.","zh":"它是任何國家植物群同類收藏中最完整的一個。"},{"en":"The most complete such collection means the fullest collection of that type.","zh":"the most complete such collection 指該類型中最齊全的收藏。"},{"en":"A museum may have the most complete such collection of local coins.","zh":"博物館可能擁有本地硬幣同類收藏中最完整的一個。"},{"en":"A collection becomes more complete when fewer important examples are missing.","zh":"當缺少的重要例子更少，收藏就更完整。"},{"en":"The phrase stresses that the collection is unusually thorough.","zh":"這個短語強調收藏異常全面。"}],"source":"155 - Seed Hunting.pdf","sourcePage":7},{"front":"country’s flora","meaning":"一個國家的植物群","examples":[{"en":"The collection represents a country’s flora.","zh":"這個收藏代表一個國家的植物群。"},{"en":"A country’s flora means all the plant life found in that country.","zh":"country’s flora 指在一個國家中找到的全部植物生命。"},{"en":"A country’s flora may include forests, wild flowers, grasses, and crops.","zh":"一個國家的植物群可能包括森林、野花、草和農作物。"},{"en":"Climate change can alter a country’s flora over time.","zh":"氣候變化可能隨時間改變一個國家的植物群。"},{"en":"The phrase focuses on plants, not animals or landscapes in general.","zh":"這個短語重點是植物，而不是動物或一般景觀。"}],"source":"155 - Seed Hunting.pdf","sourcePage":7},{"front":"overseen by","meaning":"由……監督","examples":[{"en":"The Millennium Seed Bank is overseen by the Royal Botanic Gardens.","zh":"千禧種子庫由皇家植物園監督。"},{"en":"To be overseen by someone means to be supervised or managed by them.","zh":"be overseen by someone 指由某人監督或管理。"},{"en":"A school trip is overseen by teachers to keep students safe.","zh":"學校旅行由老師監督，以保障學生安全。"},{"en":"A research project may be overseen by a senior scientist.","zh":"研究項目可能由資深科學家監督。"},{"en":"The phrase shows responsibility and official supervision.","zh":"這個短語表示責任和正式監督。"}],"source":"155 - Seed Hunting.pdf","sourcePage":7},{"front":"wild-plant depository","meaning":"野生植物儲藏庫","examples":[{"en":"The Millennium Seed Bank is the world’s largest wild-plant depository.","zh":"千禧種子庫是世界最大的野生植物儲藏庫。"},{"en":"A wild-plant depository is a place where wild plant material is stored safely.","zh":"wild-plant depository 指安全儲存野生植物材料的地方。"},{"en":"A national wild-plant depository may keep seeds from rare flowers and grasses.","zh":"國家野生植物儲藏庫可能保存稀有花卉和草類的種子。"},{"en":"Such a depository helps scientists protect species outside their natural habitats.","zh":"這類儲藏庫幫助科學家在自然棲息地以外保護物種。"},{"en":"The phrase sounds formal and refers to organised storage.","zh":"這個短語較正式，指有組織的儲存。"}],"source":"155 - Seed Hunting.pdf","sourcePage":7},{"front":"collect 24,000 species","meaning":"收集24,000個物種","examples":[{"en":"The bank aims to collect 24,000 species by 2010.","zh":"種子庫旨在2010年前收集24,000個物種。"},{"en":"To collect 24,000 species means to gather samples from 24,000 different kinds of plants.","zh":"collect 24,000 species 指收集24,000種不同植物的樣本。"},{"en":"A library may aim to collect 10,000 books for a new community centre.","zh":"圖書館可能目標是為新社區中心收集10,000本書。"},{"en":"Collecting many species helps researchers preserve wider genetic diversity.","zh":"收集許多物種有助研究人員保存更廣泛的遺傳多樣性。"},{"en":"The number shows the project’s large scale.","zh":"這個數字顯示項目規模龐大。"}],"source":"155 - Seed Hunting.pdf","sourcePage":7},{"front":"the need is clear","meaning":"需要很明確","examples":[{"en":"The need for seed conservation is clear.","zh":"種子保育的需要很明確。"},{"en":"The need is clear means the reason for action is obvious.","zh":"the need is clear 指採取行動的原因很明顯。"},{"en":"When a roof leaks during rain, the need for repair is clear.","zh":"當屋頂下雨時漏水，維修的需要很明確。"},{"en":"If many students fail, the need for better support is clear.","zh":"如果許多學生不合格，更好支援的需要很明確。"},{"en":"The phrase removes doubt and shows action is justified.","zh":"這個短語消除疑問，並顯示行動有充分理由。"}],"source":"155 - Seed Hunting.pdf","sourcePage":7},{"front":"because of human activity","meaning":"由於人類活動","examples":[{"en":"Many plants are threatened because of human activity.","zh":"許多植物由於人類活動而受到威脅。"},{"en":"Because of human activity means as a result of things people do.","zh":"because of human activity 指由人類所做的事情造成。"},{"en":"Rivers may become polluted because of human activity such as dumping waste.","zh":"河流可能由於傾倒廢物等人類活動而受污染。"},{"en":"Forests shrink because of human activity when trees are cleared for farms.","zh":"當樹木被清理作農地，森林會由於人類活動而縮小。"},{"en":"The phrase points to people as the cause of environmental change.","zh":"這個短語指出人類是環境變化的原因。"}],"source":"155 - Seed Hunting.pdf","sourcePage":7},{"front":"an estimated 25 per cent","meaning":"估計25%","examples":[{"en":"An estimated 25 per cent of the world’s plants may vanish.","zh":"估計25%的世界植物可能消失。"},{"en":"An estimated 25 per cent means about 25 per cent, based on available information.","zh":"an estimated 25 per cent 指根據現有資料估算約25%。"},{"en":"An estimated 25 per cent of students joined the online survey.","zh":"估計25%的學生參加了網上問卷。"},{"en":"Officials use an estimated figure when the exact number is not known.","zh":"當確實數字未知，官員會使用估計數字。"},{"en":"The phrase shows the number is approximate but informed.","zh":"這個短語顯示數字是近似但有根據的。"}],"source":"155 - Seed Hunting.pdf","sourcePage":7},{"front":"on the verge of extinction","meaning":"瀕臨滅絕","examples":[{"en":"Many plant species are on the verge of extinction.","zh":"許多植物物種瀕臨滅絕。"},{"en":"On the verge of extinction means very close to disappearing forever.","zh":"on the verge of extinction 指非常接近永遠消失。"},{"en":"A bird with only a few pairs left is on the verge of extinction.","zh":"如果一種鳥只剩下幾對繁殖個體，它就是瀕臨滅絕。"},{"en":"Habitat loss can push animals and plants to the verge of extinction.","zh":"棲息地喪失可以把動植物推向瀕臨滅絕。"},{"en":"The phrase signals an emergency situation for a species.","zh":"這個短語表示某物種處於緊急狀態。"}],"source":"155 - Seed Hunting.pdf","sourcePage":8},{"front":"be responsible for","meaning":"對……負有責任；是……的原因","examples":[{"en":"Humans are responsible for habitat destruction on an unprecedented scale.","zh":"人類是以前所未有規模破壞棲息地的原因。"},{"en":"To be responsible for something means to be the cause of it or have duty for it.","zh":"be responsible for something 指是某事的原因，或對某事負有責任。"},{"en":"Heavy rain was responsible for the delay in traffic.","zh":"大雨是交通延誤的原因。"},{"en":"A manager is responsible for making sure staff work safely.","zh":"經理負責確保員工安全工作。"},{"en":"The phrase can refer to blame, cause, or duty depending on context.","zh":"這個短語可按語境指責任、原因或職責。"}],"source":"155 - Seed Hunting.pdf","sourcePage":8},{"front":"habitat destruction","meaning":"棲息地破壞","examples":[{"en":"Habitat destruction threatens many plant species.","zh":"棲息地破壞威脅許多植物物種。"},{"en":"Habitat destruction means damaging or removing the natural places where organisms live.","zh":"habitat destruction 指破壞或移除生物生活的自然地方。"},{"en":"Cutting down forests causes habitat destruction for birds and insects.","zh":"砍伐森林會對鳥類和昆蟲造成棲息地破壞。"},{"en":"Habitat destruction can force animals to move or die.","zh":"棲息地破壞可能迫使動物遷移或死亡。"},{"en":"The phrase is often used in environmental protection and conservation.","zh":"這個短語常用於環境保護和保育。"}],"source":"155 - Seed Hunting.pdf","sourcePage":8},{"front":"on an unprecedented scale","meaning":"以前所未有的規模","examples":[{"en":"Habitat destruction is occurring on an unprecedented scale.","zh":"棲息地破壞正以前所未有的規模發生。"},{"en":"On an unprecedented scale means at a level never seen before.","zh":"on an unprecedented scale 指以從未見過的程度發生。"},{"en":"The city built new housing on an unprecedented scale after the population grew.","zh":"人口增長後，城市以前所未有的規模興建新房屋。"},{"en":"Online learning expanded on an unprecedented scale during school closures.","zh":"停課期間，網上學習以前所未有的規模擴展。"},{"en":"The phrase emphasises that the size or speed is historically unusual.","zh":"這個短語強調規模或速度在歷史上異常。"}],"source":"155 - Seed Hunting.pdf","sourcePage":8},{"front":"extinction rates","meaning":"滅絕率","examples":[{"en":"Plant species extinction rates have risen dramatically.","zh":"植物物種滅絕率已大幅上升。"},{"en":"Extinction rates show how quickly species are disappearing.","zh":"extinction rates 顯示物種消失的速度。"},{"en":"High extinction rates suggest that ecosystems are under serious pressure.","zh":"高滅絕率顯示生態系統承受嚴重壓力。"},{"en":"Scientists compare extinction rates from different periods to understand environmental change.","zh":"科學家比較不同時期的滅絕率，以了解環境變化。"},{"en":"The phrase focuses on speed, not only the number of lost species.","zh":"這個短語重點是速度，而不只是失去物種的數量。"}],"source":"155 - Seed Hunting.pdf","sourcePage":8},{"front":"geological record","meaning":"地質記錄","examples":[{"en":"The geological record suggests lower normal extinction rates.","zh":"地質記錄顯示正常滅絕率較低。"},{"en":"The geological record is evidence from rocks and fossils about Earth’s past.","zh":"geological record 指岩石和化石中關於地球過去的證據。"},{"en":"Fossils in the geological record show when some species lived and died out.","zh":"地質記錄中的化石顯示某些物種何時生存和滅絕。"},{"en":"Scientists use the geological record to compare past and present changes.","zh":"科學家使用地質記錄比較過去和現在的變化。"},{"en":"The phrase gives long-term evidence beyond written history.","zh":"這個短語提供超越書面歷史的長期證據。"}],"source":"155 - Seed Hunting.pdf","sourcePage":8},{"front":"indicate as being normal","meaning":"顯示為正常","examples":[{"en":"The geological record indicates certain extinction rates as being normal.","zh":"地質記錄顯示某些滅絕率為正常。"},{"en":"To indicate something as being normal means to show that it is usual or expected.","zh":"indicate something as being normal 指顯示某事屬通常或預期情況。"},{"en":"Medical charts may indicate a child’s temperature as being normal.","zh":"醫療圖表可能顯示孩子體溫為正常。"},{"en":"If past data indicate a rainfall level as being normal, it is not unusual for that region.","zh":"如果過去數據顯示某降雨量為正常，它對該地區而言並不異常。"},{"en":"The phrase is formal and often used with evidence or records.","zh":"這個短語較正式，常與證據或記錄一起使用。"}],"source":"155 - Seed Hunting.pdf","sourcePage":8},{"front":"a further one billion hectares","meaning":"額外十億公頃","examples":[{"en":"Experts predict that a further one billion hectares of wilderness will become farmland.","zh":"專家預測額外十億公頃荒野將變成農地。"},{"en":"A further one billion hectares means an additional billion hectares beyond what already exists.","zh":"a further one billion hectares 指在已有面積之外再增加十億公頃。"},{"en":"A country may protect a further one million hectares of forest after a new law.","zh":"新法律通過後，一個國家可能再保護額外一百萬公頃森林。"},{"en":"Using a further one billion hectares for farms would greatly change natural landscapes.","zh":"把額外十億公頃用作農地，將大幅改變自然景觀。"},{"en":"The phrase highlights a very large added amount.","zh":"這個短語強調非常龐大的新增數量。"}],"source":"155 - Seed Hunting.pdf","sourcePage":8},{"front":"wilderness","meaning":"荒野","examples":[{"en":"Large areas of wilderness may be converted to farmland.","zh":"大片荒野可能被轉變為農地。"},{"en":"Wilderness is natural land that has not been strongly changed by people.","zh":"wilderness 指未被人類大幅改變的自然土地。"},{"en":"Mountains, deserts, and forests can all be forms of wilderness.","zh":"高山、沙漠和森林都可以是荒野。"},{"en":"Building roads through wilderness can disturb plants and animals.","zh":"在荒野中修建道路可能干擾動植物。"},{"en":"The word suggests wild nature, not parks carefully managed by people.","zh":"這個詞暗示野生自然，而不是由人細心管理的公園。"}],"source":"155 - Seed Hunting.pdf","sourcePage":8},{"front":"be converted to farmland","meaning":"被轉變為農地","examples":[{"en":"More wilderness will be converted to farmland in developing countries.","zh":"在發展中國家，更多荒野將被轉變為農地。"},{"en":"To be converted to farmland means to be changed into land used for growing crops or raising animals.","zh":"be converted to farmland 指被改變成用於種植作物或飼養動物的土地。"},{"en":"A forest may be converted to farmland if farmers need more space.","zh":"如果農民需要更多空間，森林可能被轉變為農地。"},{"en":"When wetlands are converted to farmland, birds may lose feeding areas.","zh":"當濕地被轉變為農地，鳥類可能失去覓食地。"},{"en":"The phrase describes land-use change.","zh":"這個短語描述土地用途改變。"}],"source":"155 - Seed Hunting.pdf","sourcePage":8},{"front":"developing countries","meaning":"發展中國家","examples":[{"en":"Farmland is expected to expand in developing countries.","zh":"預計農地會在發展中國家擴張。"},{"en":"Developing countries are countries still building stronger economies, services, and infrastructure.","zh":"developing countries 指仍在建設更強經濟、服務和基礎設施的國家。"},{"en":"Developing countries may need more schools, hospitals, and transport systems.","zh":"發展中國家可能需要更多學校、醫院和交通系統。"},{"en":"Farming can expand quickly in developing countries when food demand rises.","zh":"當食物需求上升，農業可能在發展中國家迅速擴張。"},{"en":"The phrase should be used carefully because countries differ greatly.","zh":"這個短語應小心使用，因為各國差異很大。"}],"source":"155 - Seed Hunting.pdf","sourcePage":8},{"front":"the implications of this loss","meaning":"這種損失的影響","examples":[{"en":"The implications of this loss are enormous.","zh":"這種損失的影響是巨大的。"},{"en":"The implications of this loss are the possible results or effects caused by losing something.","zh":"the implications of this loss 指失去某物可能造成的結果或影響。"},{"en":"The implications of losing a local hospital include longer travel times for patients.","zh":"失去本地醫院的影響包括病人路程時間更長。"},{"en":"The implications of this loss may not be clear until years later.","zh":"這種損失的影響可能要多年後才清楚。"},{"en":"The phrase asks us to think beyond the immediate damage.","zh":"這個短語要求我們思考即時損害以外的後果。"}],"source":"155 - Seed Hunting.pdf","sourcePage":9},{"front":"enormous","meaning":"巨大的","examples":[{"en":"The loss of plant species has enormous implications.","zh":"植物物種的損失有巨大的影響。"},{"en":"Enormous means extremely large in size, amount, or importance.","zh":"enormous 指大小、數量或重要性極大。"},{"en":"A family may face enormous stress if a parent loses work suddenly.","zh":"如果父母突然失業，家庭可能面對巨大壓力。"},{"en":"Enormous crowds gathered when the festival returned after many years.","zh":"節日多年後重辦時，巨大人群聚集起來。"},{"en":"The word is stronger than big and shows something is very serious or large.","zh":"這個詞比 big 更強，表示事情非常嚴重或龐大。"}],"source":"155 - Seed Hunting.pdf","sourcePage":9},{"front":"besides providing","meaning":"除了提供……之外","examples":[{"en":"Besides providing food, plants supply medicines and materials.","zh":"除了提供食物之外，植物還供應藥物和材料。"},{"en":"Besides providing means in addition to giving or supplying something.","zh":"besides providing 指除了給予或供應某物之外。"},{"en":"Besides providing lessons, schools give students social experience.","zh":"除了提供課堂之外，學校也給學生社交經驗。"},{"en":"Besides providing jobs, small shops make neighbourhoods feel alive.","zh":"除了提供工作之外，小店令社區感覺有活力。"},{"en":"The phrase introduces another important benefit after the first one.","zh":"這個短語在第一個好處之後引入另一個重要好處。"}],"source":"155 - Seed Hunting.pdf","sourcePage":9},{"front":"staple food crops","meaning":"主糧作物","examples":[{"en":"Plants provide staple food crops.","zh":"植物提供主糧作物。"},{"en":"Staple food crops are main crops that people eat regularly for energy.","zh":"staple food crops 指人們經常食用以獲取能量的主要農作物。"},{"en":"Rice, wheat, maize, and potatoes are staple food crops in many places.","zh":"稻米、小麥、玉米和薯仔在許多地方都是主糧作物。"},{"en":"If staple food crops fail, food prices may rise quickly.","zh":"如果主糧作物歉收，食物價格可能迅速上升。"},{"en":"The phrase refers to basic foods, not luxury ingredients.","zh":"這個短語指基本食物，而不是奢侈食材。"}],"source":"155 - Seed Hunting.pdf","sourcePage":9},{"front":"a source of many medicines","meaning":"許多藥物的來源","examples":[{"en":"Plants are a source of many medicines.","zh":"植物是許多藥物的來源。"},{"en":"A source of many medicines means something from which many drugs or treatments can come.","zh":"a source of many medicines 指許多藥物或治療可以來自的來源。"},{"en":"Some trees are a source of many medicines because their bark contains useful chemicals.","zh":"一些樹木是許多藥物的來源，因為樹皮含有有用化學物質。"},{"en":"Losing plant species may remove a source of many medicines before scientists study it.","zh":"失去植物物種可能在科學家研究前就移除許多藥物的來源。"},{"en":"The phrase shows practical value beyond food.","zh":"這個短語顯示食物以外的實際價值。"}],"source":"155 - Seed Hunting.pdf","sourcePage":9},{"front":"principal supply of","meaning":"……的主要供應來源","examples":[{"en":"Plants are the principal supply of fuel and building materials in many regions.","zh":"在許多地區，植物是燃料和建築材料的主要供應來源。"},{"en":"The principal supply of something is its main source.","zh":"the principal supply of something 指某物的主要來源。"},{"en":"Rainwater may be the principal supply of water in a remote village.","zh":"雨水可能是偏遠村莊食水的主要供應來源。"},{"en":"If the principal supply of fuel disappears, families must find alternatives.","zh":"如果燃料的主要供應來源消失，家庭必須尋找替代品。"},{"en":"The phrase points to the most important provider.","zh":"這個短語指出最重要的供應者。"}],"source":"155 - Seed Hunting.pdf","sourcePage":9},{"front":"building materials","meaning":"建築材料","examples":[{"en":"Plants provide building materials in many parts of the world.","zh":"植物在世界許多地方提供建築材料。"},{"en":"Building materials are things used to construct houses, roads, or other structures.","zh":"building materials 指用來建造房屋、道路或其他結構的材料。"},{"en":"Wood, bamboo, bricks, and metal can be building materials.","zh":"木材、竹、磚和金屬都可以是建築材料。"},{"en":"If building materials become expensive, house prices may rise.","zh":"如果建築材料變得昂貴，樓價可能上升。"},{"en":"The phrase refers to practical materials, not decoration alone.","zh":"這個短語指實用材料，而不只是裝飾。"}],"source":"155 - Seed Hunting.pdf","sourcePage":9},{"front":"regulate the climate","meaning":"調節氣候","examples":[{"en":"Plants help regulate the climate.","zh":"植物幫助調節氣候。"},{"en":"To regulate the climate means to help control temperature, rainfall, and air conditions.","zh":"regulate the climate 指幫助控制溫度、降雨和空氣狀況。"},{"en":"Forests regulate the climate by absorbing carbon dioxide and releasing moisture.","zh":"森林透過吸收二氧化碳和釋放水分來調節氣候。"},{"en":"Cutting down trees can reduce nature’s ability to regulate the climate.","zh":"砍伐樹木可能削弱自然調節氣候的能力。"},{"en":"The phrase shows plants as active parts of Earth’s system.","zh":"這個短語顯示植物是地球系統中的活躍部分。"}],"source":"155 - Seed Hunting.pdf","sourcePage":9},{"front":"across the globe","meaning":"在全球各地","examples":[{"en":"Plant species are being lost across the globe.","zh":"植物物種正在全球各地消失。"},{"en":"Across the globe means in many places around the world.","zh":"across the globe 指在世界許多地方。"},{"en":"Students across the globe use the internet to learn languages.","zh":"全球各地的學生使用互聯網學習語言。"},{"en":"Heatwaves across the globe can put pressure on farms and hospitals.","zh":"全球各地的熱浪可能對農場和醫院造成壓力。"},{"en":"The phrase emphasises worldwide scale.","zh":"這個短語強調全球規模。"}],"source":"155 - Seed Hunting.pdf","sourcePage":9},{"front":"be driven to extinction","meaning":"被推向滅絕","examples":[{"en":"Plant species are being driven to extinction before their uses are known.","zh":"植物物種在其用途被了解前正被推向滅絕。"},{"en":"To be driven to extinction means to be pushed towards disappearing forever.","zh":"be driven to extinction 指被推向永遠消失。"},{"en":"Overfishing can drive a fish species to extinction.","zh":"過度捕魚可以把一種魚推向滅絕。"},{"en":"Pollution and habitat loss can drive plants to extinction before people notice.","zh":"污染和棲息地喪失可能在人們察覺前把植物推向滅絕。"},{"en":"The phrase suggests outside pressure causing disappearance.","zh":"這個短語暗示外在壓力造成消失。"}],"source":"155 - Seed Hunting.pdf","sourcePage":9},{"front":"potential benefits","meaning":"潛在好處","examples":[{"en":"Many plants disappear before their potential benefits are discovered.","zh":"許多植物在其潛在好處被發現前就消失。"},{"en":"Potential benefits are useful effects that may appear in the future.","zh":"potential benefits 指將來可能出現的有用效果。"},{"en":"A new teaching method may have potential benefits for shy students.","zh":"新教學方法可能對害羞學生有潛在好處。"},{"en":"Scientists study plants because their potential benefits may include medicines or stronger crops.","zh":"科學家研究植物，因為它們的潛在好處可能包括藥物或更強壯的作物。"},{"en":"The phrase suggests value that is possible but not yet fully proven.","zh":"這個短語暗示可能存在但尚未完全證明的價值。"}],"source":"155 - Seed Hunting.pdf","sourcePage":9},{"front":"World Conservation Union","meaning":"世界自然保護聯盟","examples":[{"en":"The World Conservation Union has listed thousands of threatened species.","zh":"世界自然保護聯盟已列出數以千計受威脅物種。"},{"en":"The World Conservation Union is an organisation connected with protecting nature and species.","zh":"World Conservation Union 是與保護自然和物種有關的組織。"},{"en":"Reports by the World Conservation Union can influence conservation policy.","zh":"世界自然保護聯盟的報告可以影響保育政策。"},{"en":"If the World Conservation Union lists a species as threatened, governments may act.","zh":"如果世界自然保護聯盟把某物種列為受威脅，政府可能採取行動。"},{"en":"The phrase names an authority in conservation discussions.","zh":"這個短語指保育討論中的權威機構。"}],"source":"155 - Seed Hunting.pdf","sourcePage":10},{"front":"threatened species","meaning":"受威脅物種","examples":[{"en":"The World Conservation Union has listed many threatened species.","zh":"世界自然保護聯盟已列出許多受威脅物種。"},{"en":"Threatened species are plants or animals at risk of becoming extinct.","zh":"threatened species 指有滅絕風險的植物或動物。"},{"en":"A threatened species may need protected habitats and careful monitoring.","zh":"受威脅物種可能需要受保護棲息地和仔細監察。"},{"en":"Illegal trade can turn rare animals into threatened species.","zh":"非法貿易可能令稀有動物變成受威脅物種。"},{"en":"The phrase is broader than endangered because the risk level can vary.","zh":"這個短語比 endangered 更廣，因為風險程度可以不同。"}],"source":"155 - Seed Hunting.pdf","sourcePage":10},{"front":"the true figure","meaning":"真實數字","examples":[{"en":"The true figure is likely to be much higher.","zh":"真實數字很可能高得多。"},{"en":"The true figure means the real number, especially when current data may be incomplete.","zh":"the true figure 指真實數字，尤其是現有數據可能不完整時。"},{"en":"The true figure for unemployment may be higher if informal workers are counted.","zh":"如果把非正式工人計算在內，失業的真實數字可能更高。"},{"en":"Scientists may not know the true figure until more surveys are done.","zh":"科學家可能要完成更多調查才知道真實數字。"},{"en":"The phrase warns that reported numbers may be too low.","zh":"這個短語提醒我們已報告數字可能太低。"}],"source":"155 - Seed Hunting.pdf","sourcePage":10},{"front":"be sure to be","meaning":"肯定會是","examples":[{"en":"The true figure is sure to be much higher.","zh":"真實數字肯定會高得多。"},{"en":"To be sure to be something means it is almost certain to have that quality.","zh":"be sure to be something 指幾乎肯定具有某種特質。"},{"en":"The road is sure to be busy during a public holiday.","zh":"公眾假期期間，道路肯定會很繁忙。"},{"en":"A popular course is sure to be full if students register late.","zh":"如果學生遲報名，熱門課程肯定會滿額。"},{"en":"The phrase expresses strong expectation.","zh":"這個短語表達強烈預期。"}],"source":"155 - Seed Hunting.pdf","sourcePage":10},{"front":"in the UK alone","meaning":"單在英國","examples":[{"en":"In the UK alone, 300 wild plant species are endangered.","zh":"單在英國，就有300種野生植物物種瀕危。"},{"en":"In the UK alone means only in the UK, without counting other places.","zh":"in the UK alone 指只計算英國，而未包括其他地方。"},{"en":"In one school alone, fifty students joined the clean-up day.","zh":"單在一所學校，就有50名學生參加清潔日。"},{"en":"In the UK alone, a problem may already be serious before global numbers are added.","zh":"單在英國，問題可能已很嚴重，更不用加上全球數字。"},{"en":"The phrase highlights that the figure is large even for one place.","zh":"這個短語強調即使只看一個地方，數字已經很大。"}],"source":"155 - Seed Hunting.pdf","sourcePage":10},{"front":"be classified as endangered","meaning":"被列為瀕危","examples":[{"en":"Many wild plant species are classified as endangered.","zh":"許多野生植物物種被列為瀕危。"},{"en":"To be classified as endangered means to be officially placed in a high-risk category.","zh":"be classified as endangered 指被正式列入高風險類別。"},{"en":"A bird may be classified as endangered if only a small population remains.","zh":"如果一種鳥只剩小量族群，可能被列為瀕危。"},{"en":"Once a species is classified as endangered, protection measures may increase.","zh":"一旦物種被列為瀕危，保護措施可能增加。"},{"en":"The phrase suggests formal scientific or official judgement.","zh":"這個短語暗示正式的科學或官方判斷。"}],"source":"155 - Seed Hunting.pdf","sourcePage":10},{"front":"ensure that","meaning":"確保","examples":[{"en":"The seed bank aims to ensure that extinct plants are not lost forever.","zh":"種子庫旨在確保已滅絕植物不會永遠消失。"},{"en":"To ensure that something happens means to make certain it happens.","zh":"ensure that something happens 指確保某事發生。"},{"en":"Teachers check attendance to ensure that every student is safe.","zh":"老師檢查出席率，以確保每名學生安全。"},{"en":"Clear labels ensure that medicines are used correctly.","zh":"清楚標籤確保藥物被正確使用。"},{"en":"The phrase shows a deliberate action to secure a result.","zh":"這個短語表示為取得結果而採取的刻意行動。"}],"source":"155 - Seed Hunting.pdf","sourcePage":10},{"front":"extinct in the wild","meaning":"在野外滅絕","examples":[{"en":"A plant may become extinct in the wild but survive in a seed bank.","zh":"一種植物可能在野外滅絕，但仍在種子庫中存活。"},{"en":"Extinct in the wild means no longer living naturally outside human care.","zh":"extinct in the wild 指不再在人工照料以外的自然環境中生存。"},{"en":"An animal extinct in the wild may still live in zoos.","zh":"在野外滅絕的動物可能仍生活在動物園。"},{"en":"Seed banks can protect plants that become extinct in the wild.","zh":"種子庫可以保護在野外滅絕的植物。"},{"en":"The phrase is different from completely extinct because some examples still survive.","zh":"這個短語不同於完全滅絕，因為仍有一些個體存活。"}],"source":"155 - Seed Hunting.pdf","sourcePage":10},{"front":"not be lost forever","meaning":"不會永遠消失","examples":[{"en":"Stored seeds mean that a species will not be lost forever.","zh":"儲存的種子意味某物種不會永遠消失。"},{"en":"To not be lost forever means to remain recoverable instead of disappearing permanently.","zh":"not be lost forever 指仍可恢復，而不是永久消失。"},{"en":"Old family photos are scanned so memories will not be lost forever.","zh":"舊家庭照片被掃描，好讓記憶不會永遠消失。"},{"en":"Saving seeds helps ensure rare plants are not lost forever.","zh":"保存種子有助確保稀有植物不會永遠消失。"},{"en":"The phrase gives a hopeful contrast to complete loss.","zh":"這個短語與完全失去形成帶希望的對比。"}],"source":"155 - Seed Hunting.pdf","sourcePage":10},{"front":"restore damaged or destroyed environments","meaning":"修復受損或被破壞的環境","examples":[{"en":"Stored seeds can help restore damaged or destroyed environments.","zh":"儲存的種子可以幫助修復受損或被破壞的環境。"},{"en":"To restore damaged or destroyed environments means to help harmed natural places recover.","zh":"restore damaged or destroyed environments 指幫助受傷害的自然地方恢復。"},{"en":"Planting native trees can restore damaged or destroyed environments after mining.","zh":"採礦後種植本土樹木可以修復受損或被破壞的環境。"},{"en":"Wetlands may be restored when pollution is removed and plants are replanted.","zh":"當污染被移除並重新種植植物，濕地可能被修復。"},{"en":"The phrase focuses on repair, not just protection.","zh":"這個短語重點是修復，而不只是保護。"}],"source":"155 - Seed Hunting.pdf","sourcePage":10},{"front":"scientific research","meaning":"科學研究","examples":[{"en":"Stored seeds can be used in scientific research.","zh":"儲存的種子可以用於科學研究。"},{"en":"Scientific research is careful study that uses evidence to answer questions.","zh":"scientific research 指使用證據回答問題的仔細研究。"},{"en":"Students do simple scientific research when they test how light affects plant growth.","zh":"學生測試光線如何影響植物生長時，就是做簡單科學研究。"},{"en":"Scientific research can lead to better medicines, crops, and environmental decisions.","zh":"科學研究可以帶來更好的藥物、作物和環境決策。"},{"en":"The phrase suggests systematic study rather than casual guessing.","zh":"這個短語暗示有系統的研究，而不是隨便猜測。"}],"source":"155 - Seed Hunting.pdf","sourcePage":10},{"front":"find new benefits for society","meaning":"為社會找出新的好處","examples":[{"en":"Researchers may find new benefits for society from stored seeds.","zh":"研究人員可能從儲存種子中為社會找出新的好處。"},{"en":"To find new benefits for society means to discover useful effects for people and communities.","zh":"find new benefits for society 指發現對人和社區有用的新效果。"},{"en":"Scientists may find new benefits for society by studying clean energy materials.","zh":"科學家研究潔淨能源材料，可能為社會找出新的好處。"},{"en":"Plant research can find new benefits for society, such as medicines or stronger crops.","zh":"植物研究可以為社會找出新的好處，例如藥物或更強壯作物。"},{"en":"The phrase connects research with practical public value.","zh":"這個短語把研究與實際公共價值連起來。"}],"source":"155 - Seed Hunting.pdf","sourcePage":11},{"front":"otherwise be lost","meaning":"否則會失去","examples":[{"en":"Some benefits would otherwise be lost.","zh":"有些好處否則會失去。"},{"en":"Otherwise be lost means be lost if no action is taken.","zh":"otherwise be lost 指如果不採取行動就會失去。"},{"en":"Old stories may otherwise be lost if grandparents do not record them.","zh":"如果祖父母不記錄舊故事，這些故事否則會失去。"},{"en":"Rare seeds would otherwise be lost when forests are cleared.","zh":"當森林被清理，稀有種子否則會失去。"},{"en":"The phrase explains why prevention or preservation matters.","zh":"這個短語解釋為何預防或保存重要。"}],"source":"155 - Seed Hunting.pdf","sourcePage":11},{"front":"insurance policy","meaning":"保障措施；保險單","examples":[{"en":"Seed banks are an insurance policy for plant heritage.","zh":"種子庫是植物遺產的保障措施。"},{"en":"An insurance policy is protection against future loss or damage.","zh":"insurance policy 指防止未來損失或損害的保護。"},{"en":"Saving money can act as an insurance policy if someone loses work.","zh":"儲蓄可以在失業時起保障措施作用。"},{"en":"Seed banks act as an insurance policy when wild plants disappear.","zh":"當野生植物消失，種子庫就起保障措施作用。"},{"en":"The phrase is often used metaphorically to mean backup protection.","zh":"這個短語常作比喻，指備用保護。"}],"source":"155 - Seed Hunting.pdf","sourcePage":11},{"front":"plant heritage","meaning":"植物遺產","examples":[{"en":"Seed banks protect the world’s plant heritage.","zh":"種子庫保護世界的植物遺產。"},{"en":"Plant heritage means valuable plant life passed down through nature and human history.","zh":"plant heritage 指透過自然和人類歷史傳承下來的珍貴植物生命。"},{"en":"Traditional crops are part of a community’s plant heritage.","zh":"傳統作物是社區植物遺產的一部分。"},{"en":"Losing plant heritage can weaken food security and cultural memory.","zh":"失去植物遺產可能削弱糧食安全和文化記憶。"},{"en":"The phrase treats plants as something inherited and worth protecting.","zh":"這個短語把植物視為被承繼並值得保護的事物。"}],"source":"155 - Seed Hunting.pdf","sourcePage":11},{"front":"seed conservation techniques","meaning":"種子保存技術","examples":[{"en":"Seed conservation techniques were originally developed by farmers.","zh":"種子保存技術最初由農民發展。"},{"en":"Seed conservation techniques are methods used to keep seeds alive and useful.","zh":"seed conservation techniques 指保持種子存活和有用的方法。"},{"en":"Drying and cool storage are common seed conservation techniques.","zh":"乾燥和低溫儲存是常見種子保存技術。"},{"en":"Good seed conservation techniques reduce the chance of mould and decay.","zh":"良好的種子保存技術降低發霉和腐壞的機會。"},{"en":"The phrase refers to practical methods, not only scientific theory.","zh":"這個短語指實際方法，而不只是科學理論。"}],"source":"155 - Seed Hunting.pdf","sourcePage":11},{"front":"originally developed by","meaning":"最初由……發展","examples":[{"en":"These techniques were originally developed by farmers.","zh":"這些技術最初由農民發展。"},{"en":"Originally developed by someone means first created or improved by that person or group.","zh":"originally developed by someone 指最初由某人或某群體創造或改良。"},{"en":"Many recipes were originally developed by families using local ingredients.","zh":"許多食譜最初由家庭使用本地食材發展出來。"},{"en":"A tool originally developed by doctors may later be used in schools.","zh":"最初由醫生發展的工具，後來可能用於學校。"},{"en":"The phrase shows the first source of an idea or method.","zh":"這個短語顯示想法或方法的最初來源。"}],"source":"155 - Seed Hunting.pdf","sourcePage":11},{"front":"storage is the basis of","meaning":"儲存是……的基礎","examples":[{"en":"Storage is the basis of seed conservation.","zh":"儲存是種子保育的基礎。"},{"en":"If storage is the basis of something, keeping things safely is the main foundation.","zh":"如果 storage is the basis of something，意思是安全保存東西是主要基礎。"},{"en":"Good record storage is the basis of efficient office work.","zh":"良好的記錄儲存是高效辦公的基礎。"},{"en":"Safe food storage is the basis of preventing illness in restaurants.","zh":"安全食物儲存是餐廳預防疾病的基礎。"},{"en":"The phrase identifies the most important starting point.","zh":"這個短語指出最重要的起點。"}],"source":"155 - Seed Hunting.pdf","sourcePage":11},{"front":"conserving seeds until","meaning":"保存種子直至……","examples":[{"en":"Seed banks conserve seeds until they can be used.","zh":"種子庫保存種子直至它們可以被使用。"},{"en":"Conserving seeds until a later time means keeping them safe for future use.","zh":"conserving seeds until a later time 指為將來使用而安全保存種子。"},{"en":"Farmers conserve seeds until the next planting season begins.","zh":"農民保存種子直至下一個種植季節開始。"},{"en":"Seed banks conserve seeds until damaged habitats can be restored.","zh":"種子庫保存種子直至受損棲息地可以被修復。"},{"en":"The phrase links present storage with future action.","zh":"這個短語把現在的儲存與未來的行動連起來。"}],"source":"155 - Seed Hunting.pdf","sourcePage":11},{"front":"just as in farming","meaning":"正如農業中一樣","examples":[{"en":"Seed banks store seeds just as in farming.","zh":"種子庫儲存種子，正如農業中一樣。"},{"en":"Just as in farming means in a way similar to what farmers do.","zh":"just as in farming 指以類似農民做法的方式。"},{"en":"Students need planning before exams, just as in farming farmers prepare before planting.","zh":"學生考試前需要計劃，正如農業中農民種植前要準備一樣。"},{"en":"Seed banks dry and store seeds just as in farming, but for conservation.","zh":"種子庫乾燥和儲存種子，正如農業中一樣，但目的在於保育。"},{"en":"The phrase creates a simple comparison with a familiar practice.","zh":"這個短語與熟悉做法作簡單比較。"}],"source":"155 - Seed Hunting.pdf","sourcePage":11},{"front":"given today’s technology","meaning":"鑑於現今科技","examples":[{"en":"No plant species should become extinct, given today’s technology.","zh":"鑑於現今科技，沒有植物物種應該滅絕。"},{"en":"Given today’s technology means considering the tools and knowledge available now.","zh":"given today’s technology 指考慮到現今已有的工具和知識。"},{"en":"Given today’s technology, many meetings can happen online instead of requiring travel.","zh":"鑑於現今科技，許多會議可以網上進行，而不必出行。"},{"en":"Given today’s technology, doctors can detect some diseases earlier than before.","zh":"鑑於現今科技，醫生可以比以前更早發現某些疾病。"},{"en":"The phrase suggests current tools should make a better outcome possible.","zh":"這個短語暗示目前工具應能帶來更好結果。"}],"source":"155 - Seed Hunting.pdf","sourcePage":11},{"front":"biggest challenge","meaning":"最大挑戰","examples":[{"en":"The biggest challenge is finding, naming and categorising plants.","zh":"最大挑戰是尋找、命名和分類植物。"},{"en":"The biggest challenge is the most difficult problem to solve.","zh":"biggest challenge 指最難解決的問題。"},{"en":"For many students, the biggest challenge in speaking is fear of mistakes.","zh":"對許多學生而言，說話方面的最大挑戰是害怕犯錯。"},{"en":"The biggest challenge in conservation may be acting before species disappear.","zh":"保育方面的最大挑戰可能是在物種消失前行動。"},{"en":"The phrase helps identify the main difficulty, not every difficulty.","zh":"這個短語幫助指出主要困難，而不是所有困難。"}],"source":"155 - Seed Hunting.pdf","sourcePage":11},{"front":"finding, naming and categorising","meaning":"尋找、命名和分類","examples":[{"en":"Scientists must focus on finding, naming and categorising plant species.","zh":"科學家必須專注於尋找、命名和分類植物物種。"},{"en":"Finding, naming and categorising means discovering things, giving them names, and sorting them into groups.","zh":"finding, naming and categorising 指發現事物、為它們命名並把它們分組。"},{"en":"Librarians use a similar process when finding, naming and categorising old documents.","zh":"圖書館員處理舊文件時，也使用類似尋找、命名和分類的過程。"},{"en":"Without finding, naming and categorising species, scientists cannot protect them properly.","zh":"如果沒有尋找、命名和分類物種，科學家不能妥善保護它們。"},{"en":"The phrase describes organised knowledge-building.","zh":"這個短語描述有組織地建立知識的過程。"}],"source":"155 - Seed Hunting.pdf","sourcePage":12},{"front":"gather these seeds","meaning":"收集這些種子","examples":[{"en":"Someone has to gather these seeds before it is too late.","zh":"必須有人在為時已晚之前收集這些種子。"},{"en":"To gather these seeds means to collect them from plants or the ground.","zh":"gather these seeds 指從植物或地面收集這些種子。"},{"en":"Farmers gather seeds from the strongest plants for the next season.","zh":"農民從最強壯的植物收集種子，留待下一季使用。"},{"en":"Scientists gather these seeds quickly when a habitat is about to be destroyed.","zh":"當棲息地即將被破壞，科學家會迅速收集這些種子。"},{"en":"The phrase suggests practical collection work.","zh":"這個短語暗示實際採集工作。"}],"source":"155 - Seed Hunting.pdf","sourcePage":12},{"front":"before it’s too late","meaning":"在為時已晚之前","examples":[{"en":"Seeds must be gathered before it’s too late.","zh":"種子必須在為時已晚之前被收集。"},{"en":"Before it’s too late means before the chance to act is gone.","zh":"before it’s too late 指在行動機會消失之前。"},{"en":"A patient should see a doctor before it’s too late.","zh":"病人應在為時已晚之前看醫生。"},{"en":"People must repair a small leak before it’s too late and the ceiling collapses.","zh":"人們必須在為時已晚、天花倒塌之前修理小漏水。"},{"en":"The phrase creates urgency and warning.","zh":"這個短語營造迫切和警告感。"}],"source":"155 - Seed Hunting.pdf","sourcePage":12},{"front":"there aren’t a lot of people out there","meaning":"外面沒有很多人在做……","examples":[{"en":"There aren’t a lot of people out there doing seed conservation work.","zh":"外面沒有很多人在做種子保育工作。"},{"en":"There aren’t a lot of people out there means not many people are available or involved.","zh":"there aren’t a lot of people out there 指沒有很多人可參與或正在參與。"},{"en":"There aren’t a lot of people out there who can repair this old machine.","zh":"外面沒有很多人能修理這部舊機器。"},{"en":"When there aren’t a lot of people out there with special knowledge, work becomes slower.","zh":"當外面沒有很多人具備專門知識，工作會變得較慢。"},{"en":"The phrase sounds conversational and stresses shortage.","zh":"這個短語語氣較口語，強調人手短缺。"}],"source":"155 - Seed Hunting.pdf","sourcePage":12},{"front":"the key is to","meaning":"關鍵是……","examples":[{"en":"The key is to know the flora from a particular area.","zh":"關鍵是熟悉某一特定地區的植物群。"},{"en":"The key is to means the most important thing is to do something.","zh":"the key is to 指最重要的是做某事。"},{"en":"The key is to practise a little every day, not only before exams.","zh":"關鍵是每天練習一點，而不是只在考試前練習。"},{"en":"In conservation, the key is to act before damage becomes permanent.","zh":"在保育中，關鍵是在損害變成永久之前行動。"},{"en":"The phrase introduces the main solution or principle.","zh":"這個短語引入主要解決方法或原則。"}],"source":"155 - Seed Hunting.pdf","sourcePage":12},{"front":"know the flora from","meaning":"熟悉來自……的植物群","examples":[{"en":"Seed hunters need to know the flora from a particular area.","zh":"種子採集者需要熟悉某一特定地區的植物群。"},{"en":"To know the flora from an area means to understand the plants that grow there.","zh":"know the flora from an area 指了解該地區生長的植物。"},{"en":"A local guide may know the flora from the mountains better than visitors do.","zh":"本地嚮導可能比遊客更熟悉山區的植物群。"},{"en":"Scientists must know the flora from a region before judging which plants are rare.","zh":"科學家判斷哪些植物稀有前，必須熟悉該地區的植物群。"},{"en":"The phrase refers to specialist plant knowledge.","zh":"這個短語指專門的植物知識。"}],"source":"155 - Seed Hunting.pdf","sourcePage":12},{"front":"a particular area","meaning":"某一特定地區","examples":[{"en":"Knowledge of the flora from a particular area takes years to acquire.","zh":"熟悉某一特定地區的植物群需要多年才能掌握。"},{"en":"A particular area means one specific place or region.","zh":"a particular area 指某一個具體地方或地區。"},{"en":"A teacher may study problems in a particular area of the school.","zh":"老師可能研究學校某一特定區域的問題。"},{"en":"Conservation plans work better when they match the needs of a particular area.","zh":"當保育計劃配合某一特定地區的需要，效果會更好。"},{"en":"The phrase narrows attention from a general place to a specific one.","zh":"這個短語把注意力從一般地方收窄到特定地方。"}],"source":"155 - Seed Hunting.pdf","sourcePage":12},{"front":"take years to acquire","meaning":"需要多年才能掌握","examples":[{"en":"Specialist knowledge takes years to acquire.","zh":"專門知識需要多年才能掌握。"},{"en":"If something takes years to acquire, it needs many years of learning or experience.","zh":"如果某事 takes years to acquire，意思是它需要多年學習或經驗。"},{"en":"A natural accent can take years to acquire in a second language.","zh":"第二語言中的自然口音可能需要多年才能掌握。"},{"en":"Knowledge of rare plants takes years to acquire because it requires field experience.","zh":"稀有植物知識需要多年才能掌握，因為它需要實地經驗。"},{"en":"The phrase stresses patience and long-term effort.","zh":"這個短語強調耐性和長期努力。"}],"source":"155 - Seed Hunting.pdf","sourcePage":12},{"front":"seed banks scattered around the globe","meaning":"分布於全球各地的種子庫","examples":[{"en":"There are about 1,470 seed banks scattered around the globe.","zh":"全球各地分布着約1,470個種子庫。"},{"en":"Seed banks scattered around the globe are seed storage centres located in many countries.","zh":"seed banks scattered around the globe 指位於許多國家的種子儲存中心。"},{"en":"Research stations scattered around the globe can share climate data.","zh":"分布於全球各地的研究站可以分享氣候數據。"},{"en":"Seed banks scattered around the globe protect different local plant species.","zh":"分布於全球各地的種子庫保護不同本地植物物種。"},{"en":"The phrase emphasises worldwide distribution rather than one central place.","zh":"這個短語強調全球分布，而不是單一中心。"}],"source":"155 - Seed Hunting.pdf","sourcePage":12},{"front":"combined total","meaning":"合計總數","examples":[{"en":"Seed banks hold a combined total of 5.4 million samples.","zh":"種子庫合計保存540萬個樣本。"},{"en":"A combined total is the number reached when separate amounts are added together.","zh":"combined total 指把不同數量相加後得到的總數。"},{"en":"The two classes raised a combined total of 3,000 dollars.","zh":"兩班學生合計籌得3,000元。"},{"en":"A combined total can look large even if each separate number is modest.","zh":"即使每個單獨數字不大，合計總數也可能看起來很大。"},{"en":"The phrase is useful when summarising data from many sources.","zh":"這個短語適合總結來自多個來源的數據。"}],"source":"155 - Seed Hunting.pdf","sourcePage":12},{"front":"samples","meaning":"樣本","examples":[{"en":"Seed banks around the world contain millions of samples.","zh":"世界各地的種子庫存放數以百萬計樣本。"},{"en":"Samples are small amounts or examples taken for study, testing, or storage.","zh":"samples 指為研究、測試或儲存而取出的小量或例子。"},{"en":"Doctors may take blood samples to check a patient’s health.","zh":"醫生可能抽取血液樣本來檢查病人健康。"},{"en":"Seed samples allow scientists to study plants without keeping whole forests.","zh":"種子樣本讓科學家不必保存整片森林也能研究植物。"},{"en":"The word often refers to part of something larger.","zh":"這個詞常指較大整體中的一部分。"}],"source":"155 - Seed Hunting.pdf","sourcePage":12},{"front":"distinct non-duplicates","meaning":"不重複的獨特樣本","examples":[{"en":"Perhaps two million samples are distinct non-duplicates.","zh":"可能有200萬個樣本是不重複的獨特樣本。"},{"en":"Distinct non-duplicates are separate items that are not repeated copies.","zh":"distinct non-duplicates 指彼此不同、不是重複複本的項目。"},{"en":"A teacher may remove duplicate answers and count only distinct non-duplicates.","zh":"老師可能移除重複答案，只計算不重複的獨特答案。"},{"en":"In a seed bank, distinct non-duplicates show how many truly different samples exist.","zh":"在種子庫中，不重複的獨特樣本顯示真正不同樣本的數量。"},{"en":"The phrase is useful when raw totals include repeated items.","zh":"當原始總數包含重複項目時，這個短語很有用。"}],"source":"155 - Seed Hunting.pdf","sourcePage":13},{"front":"preserve genetic material","meaning":"保存遺傳材料","examples":[{"en":"Most seed banks preserve genetic material for agriculture.","zh":"大多數種子庫為農業保存遺傳材料。"},{"en":"To preserve genetic material means to protect the biological information carried in living things.","zh":"preserve genetic material 指保護生物所攜帶的生物資訊。"},{"en":"Farmers preserve genetic material when they save seeds from old crop varieties.","zh":"農民保存舊作物品種的種子時，就是保存遺傳材料。"},{"en":"Preserving genetic material helps future breeders develop stronger crops.","zh":"保存遺傳材料有助未來育種者培育更強壯作物。"},{"en":"The phrase connects storage with DNA and inherited traits.","zh":"這個短語把儲存與 DNA 和遺傳特徵連起來。"}],"source":"155 - Seed Hunting.pdf","sourcePage":13},{"front":"agricultural use","meaning":"農業用途","examples":[{"en":"Many seed banks preserve material for agricultural use.","zh":"許多種子庫為農業用途保存材料。"},{"en":"Agricultural use means use in farming or food production.","zh":"agricultural use 指在農業或食物生產中的用途。"},{"en":"Land for agricultural use may grow vegetables, rice, or fruit trees.","zh":"農業用途的土地可能種植蔬菜、稻米或果樹。"},{"en":"Seeds kept for agricultural use can help farmers respond to disease or drought.","zh":"為農業用途保存的種子可以幫助農民應對疾病或乾旱。"},{"en":"The phrase focuses on practical farming purposes.","zh":"這個短語重點是實際農業目的。"}],"source":"155 - Seed Hunting.pdf","sourcePage":13},{"front":"ensure crop diversity","meaning":"確保作物多樣性","examples":[{"en":"Seed banks help ensure crop diversity.","zh":"種子庫幫助確保作物多樣性。"},{"en":"To ensure crop diversity means to make sure many kinds of crops remain available.","zh":"ensure crop diversity 指確保許多種類的作物仍可使用。"},{"en":"Farmers ensure crop diversity by growing more than one variety of rice.","zh":"農民透過種植多於一種稻米品種來確保作物多樣性。"},{"en":"Crop diversity reduces risk because one disease may not destroy every variety.","zh":"作物多樣性降低風險，因為一種疾病未必摧毀所有品種。"},{"en":"The phrase links variety with food security.","zh":"這個短語把多樣性與糧食安全連起來。"}],"source":"155 - Seed Hunting.pdf","sourcePage":13},{"front":"conserve wild species","meaning":"保育野生物種","examples":[{"en":"Some seed banks aim to conserve wild species.","zh":"一些種子庫旨在保育野生物種。"},{"en":"To conserve wild species means to protect plants or animals that live naturally in the wild.","zh":"conserve wild species 指保護自然在野外生活的植物或動物。"},{"en":"National parks conserve wild species by protecting their habitats.","zh":"國家公園透過保護棲息地來保育野生物種。"},{"en":"Seed banks conserve wild species when they store seeds from rare natural populations.","zh":"種子庫儲存來自稀有自然族群的種子時，就是保育野生物種。"},{"en":"The phrase focuses on nature, not farmed or domesticated species.","zh":"這個短語重點是自然，而不是農作或馴化物種。"}],"source":"155 - Seed Hunting.pdf","sourcePage":13},{"front":"banked plants","meaning":"入庫保存的植物","examples":[{"en":"Only 15 per cent of all banked plants are wild.","zh":"所有入庫保存的植物中，只有15%是野生植物。"},{"en":"Banked plants are plants whose seeds or material are stored in a seed bank.","zh":"banked plants 指種子或材料被儲存在種子庫中的植物。"},{"en":"A banked plant may no longer be common in the wild.","zh":"入庫保存的植物在野外可能已不再常見。"},{"en":"Increasing the number of banked plants can protect more genetic diversity.","zh":"增加入庫保存植物的數量可以保護更多遺傳多樣性。"},{"en":"The phrase uses bank as a verb meaning stored for protection.","zh":"這個短語把 bank 用作動詞，意思是為保護而儲存。"}],"source":"155 - Seed Hunting.pdf","sourcePage":13},{"front":"under threat","meaning":"受到威脅","examples":[{"en":"Many seed banks are themselves under threat.","zh":"許多種子庫本身也受到威脅。"},{"en":"Under threat means facing danger, damage, or possible loss.","zh":"under threat 指面對危險、損害或可能失去。"},{"en":"Small shops are under threat when rent rises sharply.","zh":"當租金大幅上升，小店會受到威脅。"},{"en":"A forest under threat may need legal protection.","zh":"受到威脅的森林可能需要法律保護。"},{"en":"The phrase shows that something important may not survive without help.","zh":"這個短語顯示重要事物若沒有幫助可能無法存續。"}],"source":"155 - Seed Hunting.pdf","sourcePage":13},{"front":"due to a lack of funds","meaning":"由於缺乏資金","examples":[{"en":"Many seed banks are under threat due to a lack of funds.","zh":"許多種子庫由於缺乏資金而受到威脅。"},{"en":"Due to a lack of funds means because there is not enough money.","zh":"due to a lack of funds 指因為沒有足夠金錢。"},{"en":"The school trip was cancelled due to a lack of funds.","zh":"學校旅行由於缺乏資金而取消。"},{"en":"Conservation projects may stop due to a lack of funds even when the science is strong.","zh":"即使科學理據充分，保育項目也可能由於缺乏資金而停止。"},{"en":"The phrase gives a financial reason for a problem.","zh":"這個短語提供問題的財政原因。"}],"source":"155 - Seed Hunting.pdf","sourcePage":13},{"front":"lack of funds","meaning":"缺乏資金","examples":[{"en":"A lack of funds threatens many seed banks.","zh":"缺乏資金威脅許多種子庫。"},{"en":"A lack of funds means not having enough money to do necessary work.","zh":"lack of funds 指沒有足夠金錢去做必要工作。"},{"en":"A lack of funds can stop a club from buying equipment.","zh":"缺乏資金可能令社團無法購買設備。"},{"en":"Hospitals may delay repairs because of a lack of funds.","zh":"醫院可能因缺乏資金而延遲維修。"},{"en":"The phrase often explains why useful plans cannot continue.","zh":"這個短語常解釋有用計劃為何不能繼續。"}],"source":"155 - Seed Hunting.pdf","sourcePage":13},{"front":"crop collections","meaning":"作物收藏","examples":[{"en":"Imperial College examined crop collections from 151 countries.","zh":"帝國學院檢視了來自151個國家的作物收藏。"},{"en":"Crop collections are stored samples of crop plants or their seeds.","zh":"crop collections 指被保存的作物植物或其種子樣本。"},{"en":"A crop collection may include old rice, wheat, and bean varieties.","zh":"作物收藏可能包括舊稻米、小麥和豆類品種。"},{"en":"Crop collections help farmers and scientists find useful traits for future farming.","zh":"作物收藏幫助農民和科學家尋找未來農業有用特徵。"},{"en":"The phrase refers to organised agricultural plant material.","zh":"這個短語指有組織的農業植物材料。"}],"source":"155 - Seed Hunting.pdf","sourcePage":13},{"front":"two-thirds of the countries","meaning":"三分之二的國家","examples":[{"en":"The number of samples increased in two-thirds of the countries.","zh":"三分之二的國家的樣本數量有所增加。"},{"en":"Two-thirds of the countries means two out of every three countries in a group.","zh":"two-thirds of the countries 指一組國家中每三個有兩個。"},{"en":"Two-thirds of the countries in the survey reported higher food prices.","zh":"調查中三分之二的國家報告食物價格上升。"},{"en":"If two-thirds of the countries improve, the overall trend is positive.","zh":"如果三分之二的國家有所改善，整體趨勢就是正面。"},{"en":"The phrase describes a proportion across countries.","zh":"這個短語描述跨國比例。"}],"source":"155 - Seed Hunting.pdf","sourcePage":13},{"front":"budget had been cut","meaning":"預算被削減","examples":[{"en":"The budget had been cut in a quarter of the countries.","zh":"四分之一國家的預算被削減。"},{"en":"If a budget had been cut, less money was available than before.","zh":"如果 a budget had been cut，意思是可用金錢比以前少。"},{"en":"The school budget had been cut, so some activities were cancelled.","zh":"學校預算被削減，所以一些活動被取消。"},{"en":"When a research budget has been cut, fewer staff can be hired.","zh":"當研究預算被削減，可以聘請的員工會更少。"},{"en":"The phrase explains reduced resources in the past.","zh":"這個短語解釋過去資源減少。"}],"source":"155 - Seed Hunting.pdf","sourcePage":14},{"front":"remain static","meaning":"保持不變","examples":[{"en":"The budget remained static in another 35 per cent.","zh":"另外35%的預算保持不變。"},{"en":"To remain static means to stay the same without increasing or decreasing.","zh":"remain static 指保持一樣，沒有增加或減少。"},{"en":"A student’s score may remain static if they do not change their study method.","zh":"如果學生不改變學習方法，成績可能保持不變。"},{"en":"Prices remained static for months because demand was stable.","zh":"由於需求穩定，價格數月保持不變。"},{"en":"The phrase often suggests no progress or movement.","zh":"這個短語常暗示沒有進展或變動。"}],"source":"155 - Seed Hunting.pdf","sourcePage":14},{"front":"Food and Agriculture Organization","meaning":"糧食及農業組織","examples":[{"en":"The Food and Agriculture Organization helped set up a conservation trust.","zh":"糧食及農業組織幫助成立一個保育信託。"},{"en":"The Food and Agriculture Organization is an international body concerned with food, farming, and hunger.","zh":"Food and Agriculture Organization 是關注糧食、農業和飢餓問題的國際機構。"},{"en":"Governments may use Food and Agriculture Organization reports to plan farming policy.","zh":"政府可能使用糧食及農業組織的報告來制定農業政策。"},{"en":"The organisation can support projects that protect crops and improve food security.","zh":"該組織可以支持保護作物和改善糧食安全的項目。"},{"en":"The phrase names an official international organisation.","zh":"這個短語指一個官方國際組織。"}],"source":"155 - Seed Hunting.pdf","sourcePage":14},{"front":"Consultative Group on International Agricultural Research","meaning":"國際農業研究諮詢小組","examples":[{"en":"The Consultative Group on International Agricultural Research helped establish the trust.","zh":"國際農業研究諮詢小組幫助成立該信託。"},{"en":"The Consultative Group on International Agricultural Research is a body linked to global farming research.","zh":"Consultative Group on International Agricultural Research 是與全球農業研究有關的組織。"},{"en":"Such a group may support research on crops, soil, water, and food security.","zh":"這類小組可能支持作物、土壤、水和糧食安全研究。"},{"en":"International agricultural research helps countries share knowledge about farming problems.","zh":"國際農業研究幫助各國分享農業問題知識。"},{"en":"The phrase names an organisation, so it should not be translated too freely.","zh":"這個短語是組織名稱，所以不應翻譯得太自由。"}],"source":"155 - Seed Hunting.pdf","sourcePage":14},{"front":"set up","meaning":"成立；設立","examples":[{"en":"The organisations set up the Global Conservation Trust.","zh":"這些組織成立了全球保育信託。"},{"en":"To set up something means to create, arrange, or establish it.","zh":"set up something 指創立、安排或設立某物。"},{"en":"Students set up chairs before the school concert.","zh":"學生在學校音樂會前擺設椅子。"},{"en":"A charity may be set up after a disaster to collect donations.","zh":"災難後可能成立慈善機構來收集捐款。"},{"en":"The phrase can mean physically arrange or formally establish.","zh":"這個短語可以指實際擺設，也可以指正式成立。"}],"source":"155 - Seed Hunting.pdf","sourcePage":14},{"front":"Global Conservation Trust","meaning":"全球保育信託","examples":[{"en":"The Global Conservation Trust aims to protect seed banks.","zh":"全球保育信託旨在保護種子庫。"},{"en":"The Global Conservation Trust is a fund or organisation created to support conservation work worldwide.","zh":"Global Conservation Trust 是為支持全球保育工作而成立的基金或組織。"},{"en":"A global trust can collect money from many countries for a shared purpose.","zh":"全球信託可以從多個國家籌集資金，以支持共同目的。"},{"en":"The Global Conservation Trust supports seed banks so valuable collections are not lost.","zh":"全球保育信託支持種子庫，使珍貴收藏不會失去。"},{"en":"The phrase names a conservation funding effort.","zh":"這個短語指一項保育資助工作。"}],"source":"155 - Seed Hunting.pdf","sourcePage":14},{"front":"aim to raise","meaning":"旨在籌集","examples":[{"en":"The trust aims to raise US$260 million.","zh":"該信託旨在籌集2.6億美元。"},{"en":"To aim to raise money means to plan to collect a certain amount.","zh":"aim to raise money 指計劃籌集某個金額。"},{"en":"The school aims to raise money for a new library.","zh":"學校旨在為新圖書館籌集資金。"},{"en":"A charity may aim to raise more funds after demand increases.","zh":"需求增加後，慈善機構可能旨在籌集更多資金。"},{"en":"The phrase states a fundraising goal.","zh":"這個短語說明籌款目標。"}],"source":"155 - Seed Hunting.pdf","sourcePage":14},{"front":"protect seed banks in perpetuity","meaning":"永久保護種子庫","examples":[{"en":"The trust aims to protect seed banks in perpetuity.","zh":"該信託旨在永久保護種子庫。"},{"en":"To protect seed banks in perpetuity means to support them permanently.","zh":"protect seed banks in perpetuity 指永久支持和保護種子庫。"},{"en":"A museum fund may protect historic objects in perpetuity.","zh":"博物館基金可能永久保護歷史物件。"},{"en":"Seed banks need long-term money if they are to be protected in perpetuity.","zh":"如果要永久保護種子庫，就需要長期資金。"},{"en":"The phrase stresses protection with no planned end date.","zh":"這個短語強調沒有預定結束日期的保護。"}],"source":"155 - Seed Hunting.pdf","sourcePage":14},{"front":"in perpetuity","meaning":"永久地","examples":[{"en":"The fund aims to protect seed banks in perpetuity.","zh":"該基金旨在永久地保護種子庫。"},{"en":"In perpetuity means forever or for an unlimited time.","zh":"in perpetuity 指永遠或無限期地。"},{"en":"Some land is protected in perpetuity so it cannot be developed.","zh":"一些土地被永久保護，因此不能被開發。"},{"en":"A scholarship fund may support students in perpetuity if it is managed well.","zh":"如果管理得當，獎學金基金可以永久地支持學生。"},{"en":"The phrase is formal and often used in legal or financial contexts.","zh":"這個短語較正式，常用於法律或財政語境。"}],"source":"155 - Seed Hunting.pdf","sourcePage":14},{"front":"agree with the information given","meaning":"與文中資料一致","examples":[{"en":"Students decide whether statements agree with the information given in the passage.","zh":"學生判斷句子是否與文章中給出的資料一致。"},{"en":"To agree with the information given means to match what the text says.","zh":"agree with the information given 指與文本所說內容相符。"},{"en":"If a statement says the bank stores seeds underground and the passage says the same, it agrees with the information given.","zh":"如果句子說種子庫把種子存放在地下，而文章也這樣說，它就與文中資料一致。"},{"en":"Students should not use outside knowledge when checking whether an answer agrees with the information given.","zh":"學生判斷答案是否與文中資料一致時，不應使用外部知識。"},{"en":"The phrase is common in IELTS True, False, Not Given questions.","zh":"這個短語常見於 IELTS True, False, Not Given 題目。"}],"source":"155 - Seed Hunting.pdf","sourcePage":14},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A FALSE answer means the statement contradicts the information.","zh":"FALSE 答案表示句子與資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"contradict the information 指說出與文本相反的內容。"},{"en":"If the passage says seeds are stored cold but the statement says they are heated, it contradicts the information.","zh":"如果文章說種子低溫保存，但句子說它們被加熱，這就與資料相矛盾。"},{"en":"Students must compare details carefully to see whether a statement contradicts the information.","zh":"學生必須仔細比較細節，看看句子是否與資料相矛盾。"},{"en":"The phrase means more than missing information; it means conflict with the text.","zh":"這個短語不只是資料缺失，而是與文本有衝突。"}],"source":"155 - Seed Hunting.pdf","sourcePage":14},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"NOT GIVEN means there is no information on this.","zh":"NOT GIVEN 表示文中沒有相關資料。"},{"en":"No information on this means the text does not say whether the statement is true or false.","zh":"no information on this 指文本沒有說明句子是真還是假。"},{"en":"If a passage describes a building but not its cost, there is no information on this cost.","zh":"如果文章描述一座建築但沒有提到成本，就沒有關於成本的相關資料。"},{"en":"Students should choose NOT GIVEN when there is no information on this point.","zh":"當某一點沒有相關資料時，學生應選 NOT GIVEN。"},{"en":"The phrase warns learners not to guess beyond the passage.","zh":"這個短語提醒學習者不要超出文章猜測。"}],"source":"155 - Seed Hunting.pdf","sourcePage":15},{"front":"purpose of collecting seeds","meaning":"收集種子的目的","examples":[{"en":"The purpose of collecting seeds today may differ from that in the past.","zh":"今天收集種子的目的可能與過去不同。"},{"en":"The purpose of collecting seeds means the reason why people gather seeds.","zh":"purpose of collecting seeds 指人們收集種子的原因。"},{"en":"A farmer’s purpose of collecting seeds may be to plant next year’s crop.","zh":"農民收集種子的目的可能是種植下一年的作物。"},{"en":"A scientist’s purpose of collecting seeds may be to protect rare species.","zh":"科學家收集種子的目的可能是保護稀有物種。"},{"en":"The phrase focuses on intention, not the physical act alone.","zh":"這個短語重點是意圖，而不只是實際動作。"}],"source":"155 - Seed Hunting.pdf","sourcePage":15},{"front":"differ from","meaning":"與……不同","examples":[{"en":"Modern seed hunting differs from earlier plant collecting.","zh":"現代種子採集與早期植物採集不同。"},{"en":"To differ from something means to be different from it.","zh":"differ from something 指與某物不同。"},{"en":"Spoken English may differ from written English in grammar and tone.","zh":"英語口語可能在文法和語氣上與書面英語不同。"},{"en":"A new policy differs from the old one if it changes the rules.","zh":"如果新政策改變規則，它就與舊政策不同。"},{"en":"The phrase is useful for clear comparison.","zh":"這個短語適合用於清楚比較。"}],"source":"155 - Seed Hunting.pdf","sourcePage":15},{"front":"the earliest seed bank","meaning":"最早的種子庫","examples":[{"en":"The question asks whether the Millennium Seed Bank is the earliest seed bank.","zh":"題目問千禧種子庫是否是最早的種子庫。"},{"en":"The earliest seed bank means the first seed bank created in time.","zh":"the earliest seed bank 指時間上第一個建立的種子庫。"},{"en":"To find the earliest seed bank, students must look for dates in the passage.","zh":"要找出最早的種子庫，學生必須在文章中尋找日期。"},{"en":"A claim about the earliest seed bank needs direct evidence, not guessing.","zh":"關於最早的種子庫的說法需要直接證據，而不是猜測。"},{"en":"The phrase focuses on historical order.","zh":"這個短語重點是歷史先後次序。"}],"source":"155 - Seed Hunting.pdf","sourcePage":15},{"front":"major threat to","meaning":"對……的主要威脅","examples":[{"en":"Farmland expansion is a major threat to plant species.","zh":"農地擴張是對植物物種的主要威脅。"},{"en":"A major threat to something is a serious danger to it.","zh":"major threat to something 指對某物的嚴重危險。"},{"en":"Cybercrime is a major threat to online businesses.","zh":"網絡犯罪是對網上企業的主要威脅。"},{"en":"Pollution can be a major threat to children’s health in crowded cities.","zh":"在擠迫城市中，污染可能是對兒童健康的主要威脅。"},{"en":"The phrase identifies one of the biggest risks.","zh":"這個短語指出其中一個最大風險。"}],"source":"155 - Seed Hunting.pdf","sourcePage":15},{"front":"expansion of farmland into wilderness","meaning":"農地向荒野擴張","examples":[{"en":"The expansion of farmland into wilderness threatens plant species.","zh":"農地向荒野擴張威脅植物物種。"},{"en":"Expansion of farmland into wilderness means farms spreading into natural wild land.","zh":"expansion of farmland into wilderness 指農地擴展到自然荒野之中。"},{"en":"The expansion of roads into wilderness can also disturb habitats.","zh":"道路向荒野擴張也可能干擾棲息地。"},{"en":"Expansion of farmland into wilderness may increase food production but reduce biodiversity.","zh":"農地向荒野擴張可能增加食物生產，但減少生物多樣性。"},{"en":"The phrase describes a land-use conflict between farming and nature.","zh":"這個短語描述農業與自然之間的土地用途衝突。"}],"source":"155 - Seed Hunting.pdf","sourcePage":15},{"front":"in a way similar to","meaning":"以類似……的方式","examples":[{"en":"Scientists store seeds in a way similar to farmers’ methods.","zh":"科學家以類似農民方法的方式儲存種子。"},{"en":"In a way similar to means using a method that is like another method.","zh":"in a way similar to 指使用與另一方法相似的方式。"},{"en":"Online teachers explain grammar in a way similar to classroom teachers.","zh":"網上老師以類似課室老師的方式解釋文法。"},{"en":"Seed banks dry seeds in a way similar to traditional farming practice.","zh":"種子庫以類似傳統農業做法的方式乾燥種子。"},{"en":"The phrase shows resemblance, not exact sameness.","zh":"這個短語表示相似，而不是完全一樣。"}],"source":"155 - Seed Hunting.pdf","sourcePage":15},{"front":"method used by","meaning":"由……使用的方法","examples":[{"en":"Seed banks use a method similar to the method used by farmers.","zh":"種子庫使用一種與農民使用的方法相似的方法。"},{"en":"A method used by someone is a way or technique that person or group uses.","zh":"method used by someone 指某人或某群體使用的方式或技術。"},{"en":"The method used by doctors must be safe and evidence-based.","zh":"醫生使用的方法必須安全並有證據支持。"},{"en":"The method used by farmers to store seeds inspired modern seed banks.","zh":"農民使用的種子儲存方法啟發了現代種子庫。"},{"en":"The phrase links a technique to the people who practise it.","zh":"這個短語把技術與實踐它的人連起來。"}],"source":"155 - Seed Hunting.pdf","sourcePage":15},{"front":"technological development","meaning":"科技發展","examples":[{"en":"Technological development may help save plant species.","zh":"科技發展可能有助拯救植物物種。"},{"en":"Technological development means progress in tools, machines, or scientific methods.","zh":"technological development 指工具、機器或科學方法上的進步。"},{"en":"Technological development has made online learning easier for remote students.","zh":"科技發展令偏遠學生更容易網上學習。"},{"en":"In conservation, technological development can improve storage, mapping, and data sharing.","zh":"在保育中，科技發展可以改善儲存、製圖和數據分享。"},{"en":"The phrase focuses on improvement in technology over time.","zh":"這個短語重點是科技隨時間進步。"}],"source":"155 - Seed Hunting.pdf","sourcePage":15},{"front":"the only hope for","meaning":"……的唯一希望","examples":[{"en":"The statement asks whether technology is the only hope for saving plant species.","zh":"該陳述問科技是否是拯救植物物種的唯一希望。"},{"en":"The only hope for something means the single thing that can possibly save or improve it.","zh":"the only hope for something 指唯一可能拯救或改善某事的東西。"},{"en":"A transplant may be the only hope for a patient with severe organ failure.","zh":"對嚴重器官衰竭的病人而言，移植可能是唯一希望。"},{"en":"Technology is helpful, but it may not be the only hope for conservation.","zh":"科技有幫助，但未必是保育的唯一希望。"},{"en":"The phrase is very strong because it excludes other solutions.","zh":"這個短語語氣很強，因為它排除其他解決方法。"}],"source":"155 - Seed Hunting.pdf","sourcePage":15},{"front":"saving plant species","meaning":"拯救植物物種","examples":[{"en":"Seed banks play a role in saving plant species.","zh":"種子庫在拯救植物物種方面發揮作用。"},{"en":"Saving plant species means preventing kinds of plants from disappearing forever.","zh":"saving plant species 指防止植物種類永遠消失。"},{"en":"Protecting forests is one way of saving plant species in their natural homes.","zh":"保護森林是在自然家園中拯救植物物種的一種方法。"},{"en":"Saving plant species can also protect insects, animals, and future medicines.","zh":"拯救植物物種也可以保護昆蟲、動物和未來藥物。"},{"en":"The phrase describes an urgent conservation goal.","zh":"這個短語描述迫切的保育目標。"}],"source":"155 - Seed Hunting.pdf","sourcePage":15},{"front":"seed-conservation work","meaning":"種子保育工作","examples":[{"en":"Seed-conservation work is often restricted by financial problems.","zh":"種子保育工作常受財政問題限制。"},{"en":"Seed-conservation work is the practical effort to collect, store, and protect seeds.","zh":"seed-conservation work 指收集、儲存和保護種子的實際努力。"},{"en":"Seed-conservation work may involve field trips, laboratories, and careful records.","zh":"種子保育工作可能涉及實地考察、實驗室和仔細記錄。"},{"en":"Without funding, seed-conservation work can slow down or stop.","zh":"如果沒有資金，種子保育工作可能放慢或停止。"},{"en":"The phrase refers to ongoing work, not a single action.","zh":"這個短語指持續工作，而不是單一行動。"}],"source":"155 - Seed Hunting.pdf","sourcePage":16},{"front":"be restricted by","meaning":"受……限制","examples":[{"en":"Seed banks may be restricted by financial problems.","zh":"種子庫可能受財政問題限制。"},{"en":"To be restricted by something means to be limited by it.","zh":"be restricted by something 指被某事限制。"},{"en":"A student’s subject choice may be restricted by the school timetable.","zh":"學生的科目選擇可能受學校時間表限制。"},{"en":"Small businesses are often restricted by limited space and staff.","zh":"小企業常受有限空間和員工限制。"},{"en":"The phrase shows that something cannot develop freely.","zh":"這個短語顯示某事不能自由發展。"}],"source":"155 - Seed Hunting.pdf","sourcePage":16},{"front":"financial problems","meaning":"財政問題","examples":[{"en":"Financial problems threaten many seed banks.","zh":"財政問題威脅許多種子庫。"},{"en":"Financial problems are difficulties caused by not having enough money.","zh":"financial problems 指因金錢不足而造成的困難。"},{"en":"A family may face financial problems after sudden medical bills.","zh":"家庭可能因突然的醫療費用而面對財政問題。"},{"en":"Financial problems can force organisations to cut staff or delay projects.","zh":"財政問題可能迫使組織裁員或延遲項目。"},{"en":"The phrase explains money-related obstacles.","zh":"這個短語解釋與金錢有關的障礙。"}],"source":"155 - Seed Hunting.pdf","sourcePage":16},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用文章中的字詞完成以下摘要。"},{"en":"To complete the summary below means to fill the missing parts of a short text.","zh":"complete the summary below 指填補一段短文中缺少的部分。"},{"en":"In a reading test, students complete the summary below by choosing exact words.","zh":"在閱讀測驗中，學生透過選擇準確字詞完成以下摘要。"},{"en":"A wrong grammar form can make an answer incorrect when completing the summary below.","zh":"完成以下摘要時，錯誤文法形式可能令答案錯誤。"},{"en":"The phrase is an instruction, not a vocabulary item from the passage itself.","zh":"這個短語是指示，而不是文章本身的詞彙。"}],"source":"155 - Seed Hunting.pdf","sourcePage":16},{"front":"no more than three words","meaning":"不多於三個詞","examples":[{"en":"Students should choose no more than three words from the passage.","zh":"學生應從文章中選擇不多於三個詞。"},{"en":"No more than three words means one, two, or three words, but not four.","zh":"no more than three words 指一個、兩個或三個詞，但不能四個。"},{"en":"If the answer is four words long, it breaks the rule of no more than three words.","zh":"如果答案有四個詞，就違反不多於三個詞的規則。"},{"en":"Test takers must count words carefully when the instruction says no more than three words.","zh":"當指示說不多於三個詞，考生必須仔細數詞數。"},{"en":"The phrase sets a strict answer length limit.","zh":"這個短語設定嚴格的答案長度限制。"}],"source":"155 - Seed Hunting.pdf","sourcePage":16},{"front":"for the purpose of","meaning":"為了……的目的","examples":[{"en":"Some people collect seeds for the purpose of protecting species.","zh":"有些人為了保護物種的目的而收集種子。"},{"en":"For the purpose of means in order to achieve a particular aim.","zh":"for the purpose of 指為了達成某個特定目的。"},{"en":"Students take notes for the purpose of reviewing later.","zh":"學生做筆記是為了日後溫習的目的。"},{"en":"Scientists freeze seeds for the purpose of long-term conservation.","zh":"科學家冷凍種子是為了長期保育的目的。"},{"en":"The phrase is more formal than simply saying to.","zh":"這個短語比簡單說 to 更正式。"}],"source":"155 - Seed Hunting.pdf","sourcePage":16},{"front":"protect certain species from","meaning":"保護某些物種免受……","examples":[{"en":"Seed hunters protect certain species from extinction.","zh":"種子採集者保護某些物種免受滅絕。"},{"en":"To protect certain species from something means to keep particular species safe from that danger.","zh":"protect certain species from something 指保護特定物種免受某種危險。"},{"en":"Laws protect certain species from hunting and trade.","zh":"法律保護某些物種免受捕獵和貿易。"},{"en":"Seed banks protect certain species from being lost when habitats are destroyed.","zh":"當棲息地被破壞，種子庫保護某些物種免於消失。"},{"en":"The phrase requires both the protected species and the danger.","zh":"這個短語需要指出受保護物種和危險。"}],"source":"155 - Seed Hunting.pdf","sourcePage":16},{"front":"ability to produce","meaning":"生產……的能力","examples":[{"en":"Some seeds are collected for their ability to produce drugs or crops.","zh":"有些種子因其生產藥物或農作物的能力而被收集。"},{"en":"Ability to produce means the power or potential to create something useful.","zh":"ability to produce 指創造有用事物的力量或潛力。"},{"en":"A tree’s ability to produce fruit depends on weather and soil.","zh":"一棵樹生產果實的能力取決於天氣和土壤。"},{"en":"Plants with the ability to produce useful chemicals may interest researchers.","zh":"具有生產有用化學物質能力的植物可能吸引研究人員。"},{"en":"The phrase focuses on what something can make or generate.","zh":"這個短語重點是某物能製造或產生甚麼。"}],"source":"155 - Seed Hunting.pdf","sourcePage":16},{"front":"early pioneers","meaning":"早期先驅","examples":[{"en":"Early pioneers of seed hunting included gardeners and botanists.","zh":"種子採集的早期先驅包括園丁和植物學家。"},{"en":"Early pioneers are the first people who help begin or develop a field.","zh":"early pioneers 指最早幫助開創或發展某個領域的人。"},{"en":"Early pioneers of aviation tested dangerous machines before flying became common.","zh":"航空早期先驅在飛行普及前測試危險機器。"},{"en":"Early pioneers often work without clear rules or modern equipment.","zh":"早期先驅常在沒有清晰規則或現代設備下工作。"},{"en":"The phrase gives historical credit to people who started something.","zh":"這個短語向開創某事的人給予歷史肯定。"}],"source":"155 - Seed Hunting.pdf","sourcePage":16},{"front":"financially support collectors","meaning":"以金錢資助採集者","examples":[{"en":"Joseph Banks financially supported collectors out of his own pocket.","zh":"Joseph Banks 自掏腰包以金錢資助採集者。"},{"en":"To financially support collectors means to pay money so they can do collecting work.","zh":"financially support collectors 指提供金錢，使採集者能進行採集工作。"},{"en":"A museum may financially support collectors who search for historical documents.","zh":"博物館可能以金錢資助尋找歷史文件的採集者。"},{"en":"Without financial support, collectors may not afford travel or equipment.","zh":"如果沒有金錢資助，採集者可能負擔不起旅費或設備。"},{"en":"The phrase focuses on money as practical help.","zh":"這個短語重點是以金錢作實際幫助。"}],"source":"155 - Seed Hunting.pdf","sourcePage":16},{"front":"out of his own pocket","meaning":"自掏腰包","examples":[{"en":"Banks supported seed collectors out of his own pocket.","zh":"Banks 自掏腰包支持種子採集者。"},{"en":"Out of his own pocket means using his personal money.","zh":"out of his own pocket 指使用自己的私人金錢。"},{"en":"A teacher bought extra notebooks out of his own pocket.","zh":"老師自掏腰包買額外筆記簿。"},{"en":"Volunteers sometimes pay travel costs out of their own pocket.","zh":"義工有時自掏腰包支付交通費。"},{"en":"The phrase often shows generosity or personal responsibility.","zh":"這個短語常顯示慷慨或個人承擔。"}],"source":"155 - Seed Hunting.pdf","sourcePage":16},{"front":"famous Millennium Seed Bank","meaning":"著名的千禧種子庫","examples":[{"en":"The famous Millennium Seed Bank stores seeds at a low temperature.","zh":"著名的千禧種子庫在低溫下儲存種子。"},{"en":"The famous Millennium Seed Bank is well known for storing and protecting plant seeds.","zh":"famous Millennium Seed Bank 指以儲存和保護植物種子而聞名的千禧種子庫。"},{"en":"Students may read about the famous Millennium Seed Bank in conservation lessons.","zh":"學生可能在保育課中讀到著名的千禧種子庫。"},{"en":"The famous Millennium Seed Bank shows how science can protect plants for the future.","zh":"著名的千禧種子庫顯示科學如何為未來保護植物。"},{"en":"The phrase highlights both recognition and purpose.","zh":"這個短語同時強調知名度和目的。"}],"source":"155 - Seed Hunting.pdf","sourcePage":17},{"front":"at a low temperature","meaning":"在低溫下","examples":[{"en":"The seeds are stored underground at a low temperature.","zh":"種子在地下低溫下儲存。"},{"en":"At a low temperature means in cold conditions.","zh":"at a low temperature 指在寒冷條件下。"},{"en":"Milk must be kept at a low temperature so it does not spoil quickly.","zh":"牛奶必須在低溫下保存，才不會很快變壞。"},{"en":"Seeds are stored at a low temperature to slow ageing and decay.","zh":"種子在低溫下儲存，以減慢老化和腐壞。"},{"en":"The phrase explains a storage condition.","zh":"這個短語解釋儲存條件。"}],"source":"155 - Seed Hunting.pdf","sourcePage":17},{"front":"choose two letters","meaning":"選擇兩個字母","examples":[{"en":"Students choose two letters from the options.","zh":"學生從選項中選擇兩個字母。"},{"en":"Choose two letters means select two answer choices, usually such as A, B, C, or D.","zh":"choose two letters 指選擇兩個答案選項，通常如 A、B、C 或 D。"},{"en":"In a reading question, students may choose two letters that match the passage.","zh":"在閱讀題中，學生可能選擇兩個與文章相符的字母。"},{"en":"If the instruction says choose two letters, giving only one answer is incomplete.","zh":"如果指示說選擇兩個字母，只給一個答案就是不完整。"},{"en":"The phrase is a test instruction about answer format.","zh":"這個短語是關於答案格式的考試指示。"}],"source":"155 - Seed Hunting.pdf","sourcePage":17},{"front":"provided by plants to humans","meaning":"植物為人類提供的東西","examples":[{"en":"The question asks what is provided by plants to humans.","zh":"題目問植物為人類提供了甚麼。"},{"en":"Provided by plants to humans means given or supplied by plants for people’s use.","zh":"provided by plants to humans 指植物給予或供應給人類使用的東西。"},{"en":"Food, medicine, fuel, and building materials are provided by plants to humans.","zh":"食物、藥物、燃料和建築材料都是植物為人類提供的東西。"},{"en":"If plant species disappear, some benefits provided by plants to humans may disappear too.","zh":"如果植物物種消失，植物為人類提供的一些好處也可能消失。"},{"en":"The phrase focuses on the value plants give people.","zh":"這個短語重點是植物給予人類的價值。"}],"source":"155 - Seed Hunting.pdf","sourcePage":17},{"front":"commercial products","meaning":"商業產品","examples":[{"en":"Plants can be used to produce commercial products.","zh":"植物可以用來生產商業產品。"},{"en":"Commercial products are goods made or sold for business and profit.","zh":"commercial products 指為商業和利潤而製造或銷售的商品。"},{"en":"Soap, medicine, tea, and furniture can all be commercial products made from plants.","zh":"肥皂、藥物、茶和家具都可以是由植物製成的商業產品。"},{"en":"A plant with useful oils may become valuable for commercial products.","zh":"含有有用油分的植物可能因商業產品而變得有價值。"},{"en":"The phrase focuses on market use, not personal use only.","zh":"這個短語重點是市場用途，而不只是個人用途。"}],"source":"155 - Seed Hunting.pdf","sourcePage":17}],"ielts/reading/passage-2/Practice 156":[{"front":"New Zealand’s algae biodiesel","meaning":"新西蘭的藻類生物柴油","examples":[{"en":"The passage describes New Zealand’s algae biodiesel as a possible cleaner fuel.","zh":"文章把新西蘭的藻類生物柴油描述為一種可能較潔淨的燃料。"},{"en":"New Zealand’s algae biodiesel is a fuel made from algae and developed as an alternative to ordinary diesel.","zh":"新西蘭的藻類生物柴油是一種由藻類製成、並被開發作普通柴油替代品的燃料。"},{"en":"Scientists may study New Zealand’s algae biodiesel to see whether buses can run with less pollution.","zh":"科學家可能研究新西蘭的藻類生物柴油，看看巴士能否以較少污染運行。"},{"en":"If New Zealand’s algae biodiesel becomes cheaper, more transport companies may consider using it.","zh":"如果新西蘭的藻類生物柴油變得更便宜，更多運輸公司可能會考慮使用它。"},{"en":"New Zealand’s algae biodiesel is important because it connects waste treatment with cleaner energy.","zh":"新西蘭的藻類生物柴油重要，因為它把廢物處理與較潔淨能源連繫起來。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":1},{"front":"the world’s first","meaning":"世界首個","examples":[{"en":"Aquaflow produced the world’s first wild algae biodiesel.","zh":"Aquaflow生產了世界首個野生藻類生物柴油。"},{"en":"The world’s first means something has never been done anywhere before.","zh":"世界首個指某件事以前在世界任何地方都未曾發生或完成。"},{"en":"A school may celebrate the world’s first student-built robot that can clean classrooms.","zh":"一間學校可能慶祝世界首個由學生製作、能清潔課室的機械人。"},{"en":"When a company creates the world’s first product of its kind, it can attract global attention.","zh":"當公司創造同類中的世界首個產品時，它可能吸引全球注意。"},{"en":"The phrase is used to highlight originality, not just good quality.","zh":"這個短語用來強調原創性，而不只是品質好。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":1},{"front":"wild algae biodiesel","meaning":"野生藻類生物柴油","examples":[{"en":"Wild algae biodiesel was successfully tested in Wellington.","zh":"野生藻類生物柴油在威靈頓成功接受測試。"},{"en":"Wild algae biodiesel is biodiesel made from algae that grow naturally rather than from specially planted crops.","zh":"野生藻類生物柴油是由自然生長的藻類製成的生物柴油，而不是由專門種植的農作物製成。"},{"en":"A city may study wild algae biodiesel if algae already grow in its waste ponds.","zh":"如果城市的廢水池已有藻類生長，它可能研究野生藻類生物柴油。"},{"en":"Using wild algae biodiesel could reduce the need to use farmland for fuel crops.","zh":"使用野生藻類生物柴油可以減少把農地用作種植燃料作物的需要。"},{"en":"Wild algae biodiesel is different from fuel made from farmed plants such as corn or soy.","zh":"野生藻類生物柴油不同於由粟米或大豆等農作物製成的燃料。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":1},{"front":"be produced in","meaning":"在……生產","examples":[{"en":"The biodiesel was produced in New Zealand by Aquaflow.","zh":"這種生物柴油由Aquaflow在新西蘭生產。"},{"en":"To be produced in a place means to be made or manufactured there.","zh":"be produced in某地，意思是在該地方製造或生產。"},{"en":"This bread is produced in a local bakery, so it is delivered fresh every morning.","zh":"這種麵包在本地麵包店生產，所以每天早上新鮮送達。"},{"en":"If medicine is produced in clean conditions, it is safer for patients.","zh":"如果藥物在潔淨環境中生產，對病人會更安全。"},{"en":"The phrase tells us where something is made, not where it is sold.","zh":"這個短語告訴我們某物在哪裏製造，而不是在哪裏售賣。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":1},{"front":"successfully test-driven","meaning":"成功試駕","examples":[{"en":"The algae biodiesel was successfully test-driven in Wellington.","zh":"這種藻類生物柴油在威靈頓成功試駕。"},{"en":"Successfully test-driven means a vehicle or fuel was tried in a real drive and worked as expected.","zh":"successfully test-driven指車輛或燃料在實際駕駛測試中被試用，並按預期運作。"},{"en":"The new electric bus was successfully test-driven before the school bought it.","zh":"學校購買新電動巴士前，該巴士已成功試駕。"},{"en":"If a car is successfully test-driven, engineers can feel more confident about its safety.","zh":"如果汽車成功試駕，工程師會對它的安全更有信心。"},{"en":"This phrase is often used before a product is fully introduced to the public.","zh":"這個短語常用於產品正式推出公眾前。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":1},{"front":"Minister for Energy and Climate Change Issues","meaning":"能源及氣候變化事務部長","examples":[{"en":"The Minister for Energy and Climate Change Issues took part in the test drive.","zh":"能源及氣候變化事務部長參與了試駕。"},{"en":"A Minister for Energy and Climate Change Issues is a government official responsible for energy policy and climate-related matters.","zh":"能源及氣候變化事務部長是負責能源政策和氣候相關事務的政府官員。"},{"en":"The Minister for Energy and Climate Change Issues may announce plans for cleaner electricity.","zh":"能源及氣候變化事務部長可能宣布較潔淨電力的計劃。"},{"en":"If fuel prices rise, the Minister for Energy and Climate Change Issues may need to explain the government’s response.","zh":"如果燃料價格上升，能源及氣候變化事務部長可能需要解釋政府的應對。"},{"en":"This title shows that energy use and climate protection are closely connected in public policy.","zh":"這個職銜顯示能源使用與氣候保護在公共政策中密切相關。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":1},{"front":"in front of a crowd of","meaning":"在一群……面前","examples":[{"en":"The Minister filled the vehicle in front of a crowd of guests and media.","zh":"部長在一群嘉賓和傳媒面前為車輛加油。"},{"en":"In front of a crowd of people means while many people are watching.","zh":"in front of a crowd of people指在很多人觀看的情況下。"},{"en":"A student may feel nervous speaking in front of a crowd of classmates.","zh":"學生在一群同學面前演講時可能感到緊張。"},{"en":"If a mistake happens in front of a crowd of reporters, it may quickly become news.","zh":"如果錯誤在一群記者面前發生，它可能很快成為新聞。"},{"en":"This phrase often adds pressure, publicity, or importance to an action.","zh":"這個短語常為一個動作加入壓力、公開性或重要性。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":1},{"front":"invited guests","meaning":"受邀嘉賓","examples":[{"en":"Invited guests watched the biodiesel test drive.","zh":"受邀嘉賓觀看了生物柴油試駕。"},{"en":"Invited guests are people who are specially asked to attend an event.","zh":"受邀嘉賓是被特別邀請出席活動的人。"},{"en":"Invited guests at a school ceremony may include parents, teachers, and former students.","zh":"學校典禮上的受邀嘉賓可能包括家長、老師和校友。"},{"en":"If only invited guests can enter, the event is not open to everyone.","zh":"如果只有受邀嘉賓可以入場，該活動並非向所有人開放。"},{"en":"The phrase suggests a planned occasion rather than a casual gathering.","zh":"這個短語暗示一個有安排的場合，而不是隨意聚會。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":1},{"front":"members of the public","meaning":"公眾人士","examples":[{"en":"Members of the public attended the test drive.","zh":"公眾人士出席了試駕。"},{"en":"Members of the public are ordinary people who are not part of a special organisation or official group.","zh":"公眾人士是普通市民，不屬於特定組織或官方團體。"},{"en":"Members of the public can use the library during opening hours.","zh":"公眾人士可以在開放時間使用圖書館。"},{"en":"If members of the public report a safety problem, the council should investigate it.","zh":"如果公眾人士報告安全問題，地方議會應該調查。"},{"en":"This phrase is often used when an event or service is open beyond experts or officials.","zh":"這個短語常用於活動或服務不只開放給專家或官員時。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":1},{"front":"fill up","meaning":"入滿油；加滿燃料","examples":[{"en":"The Minister filled up a diesel-powered Land Rover with biodiesel.","zh":"部長為一部柴油驅動的Land Rover加滿生物柴油。"},{"en":"To fill up a vehicle means to put fuel into it until the tank is full or nearly full.","zh":"fill up一部車，意思是把燃料加入車中，直到油缸滿或接近滿。"},{"en":"Drivers often fill up their cars before a long journey.","zh":"司機在長途旅程前常會入滿油。"},{"en":"If you forget to fill up, the car may stop before you reach the petrol station.","zh":"如果你忘記加滿燃料，汽車可能在到達油站前停下。"},{"en":"In everyday English, fill up is common when talking about fuel.","zh":"在日常英語中，fill up常用於談論燃料。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":1},{"front":"diesel-powered","meaning":"柴油驅動的","examples":[{"en":"The biodiesel was tested in a diesel-powered Land Rover.","zh":"這種生物柴油在一部柴油驅動的Land Rover中測試。"},{"en":"Diesel-powered means using a diesel engine or diesel fuel to run.","zh":"diesel-powered指使用柴油引擎或柴油燃料運行。"},{"en":"Many trucks are diesel-powered because they need strong engines for heavy loads.","zh":"許多貨車是柴油驅動的，因為它們需要強力引擎運載重物。"},{"en":"If a diesel-powered bus changes to cleaner fuel, city air may improve.","zh":"如果柴油驅動的巴士改用較潔淨燃料，城市空氣可能改善。"},{"en":"The phrase describes the type of power system a vehicle or machine uses.","zh":"這個短語描述車輛或機器使用哪種動力系統。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":1},{"front":"B5 blend biodiesel","meaning":"B5混合生物柴油","examples":[{"en":"The Land Rover used Aquaflow B5 blend biodiesel.","zh":"這部Land Rover使用Aquaflow的B5混合生物柴油。"},{"en":"B5 blend biodiesel is a mixture of biodiesel and regular diesel.","zh":"B5混合生物柴油是生物柴油與普通柴油的混合物。"},{"en":"A bus company may test B5 blend biodiesel before using stronger biodiesel mixtures.","zh":"巴士公司可能先測試B5混合生物柴油，再使用比例更高的生物柴油混合物。"},{"en":"If B5 blend biodiesel works in existing engines, drivers may not need new vehicles.","zh":"如果B5混合生物柴油能在現有引擎中運作，司機可能不需要新車。"},{"en":"The word blend shows that the fuel is mixed, not pure biodiesel.","zh":"blend一字顯示這種燃料是混合的，而不是純生物柴油。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":2},{"front":"drive around","meaning":"駕車繞行","examples":[{"en":"The Minister drove the car around the forecourt of Parliament Buildings.","zh":"部長駕車繞行國會大樓前庭。"},{"en":"To drive around means to move a vehicle through or around an area.","zh":"drive around指駕駛車輛在某個地方內或周圍行駛。"},{"en":"A driving instructor may ask a learner to drive around the car park first.","zh":"駕駛導師可能先要求學員在停車場繞行。"},{"en":"If police drive around a neighbourhood often, residents may feel safer.","zh":"如果警察經常駕車巡視社區，居民可能感到更安全。"},{"en":"This phrase usually describes short movement, not a long journey.","zh":"這個短語通常描述短距離移動，而不是長途旅程。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":2},{"front":"forecourt","meaning":"前庭；前院","examples":[{"en":"The test drive took place on the forecourt of Parliament Buildings.","zh":"試駕在國會大樓前庭進行。"},{"en":"A forecourt is an open area in front of a large building or a petrol station.","zh":"forecourt是大型建築物或油站前方的開放空間。"},{"en":"People often wait on the forecourt before entering a museum or theatre.","zh":"人們常在博物館或劇院前庭等候入場。"},{"en":"If a forecourt is crowded, cars and pedestrians must move carefully.","zh":"如果前庭很擠迫，車輛和行人都必須小心移動。"},{"en":"The word helps describe the space outside the front of a building.","zh":"這個字有助描述建築物正門外的空間。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":2},{"front":"Parliament Buildings","meaning":"國會大樓","examples":[{"en":"The vehicle was driven around Parliament Buildings in Central Wellington.","zh":"車輛在威靈頓市中心的國會大樓周圍行駛。"},{"en":"Parliament Buildings are the official buildings where lawmakers meet and government business is discussed.","zh":"國會大樓是立法者開會和討論政府事務的官方建築物。"},{"en":"Visitors may tour Parliament Buildings to learn how laws are made.","zh":"訪客可能參觀國會大樓，了解法律如何制定。"},{"en":"If a protest happens outside Parliament Buildings, it may attract political attention.","zh":"如果抗議在國會大樓外發生，可能吸引政治關注。"},{"en":"The phrase points to a place connected with national decision-making.","zh":"這個短語指一個與國家決策相關的地方。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":2},{"front":"co-leader","meaning":"共同領袖","examples":[{"en":"Green Party co-leader Jeanette Fitzsimons was also on board.","zh":"綠黨共同領袖Jeanette Fitzsimons也在車上。"},{"en":"A co-leader is one of two or more people who share leadership of a group.","zh":"共同領袖是兩個或多個共同領導某個團體的人之一。"},{"en":"The student club has two co-leaders so that one person is not responsible for everything.","zh":"學生會有兩位共同領袖，這樣一個人不用負責所有事情。"},{"en":"If co-leaders disagree publicly, members may become confused.","zh":"如果共同領袖公開意見不合，成員可能感到困惑。"},{"en":"The prefix co- shows that leadership is shared.","zh":"co-這個前綴顯示領導權是共同分享的。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":2},{"front":"on board","meaning":"在車上；在場參與","examples":[{"en":"Jeanette Fitzsimons was on board during the test drive.","zh":"Jeanette Fitzsimons在試駕期間在車上。"},{"en":"On board means inside a vehicle, ship, or aircraft, or involved in a plan.","zh":"on board可以指在車、船或飛機上，也可以指參與或支持某個計劃。"},{"en":"All passengers must be on board before the train leaves.","zh":"火車開出前，所有乘客都必須上車。"},{"en":"If the whole team is on board with a plan, it is easier to carry out.","zh":"如果整個團隊都支持一個計劃，執行起來會更容易。"},{"en":"The meaning depends on context: it can mean physically inside or actively supporting.","zh":"意思視乎語境而定：可以指身處交通工具內，也可以指積極支持。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":2},{"front":"Marlborough-based","meaning":"總部位於馬爾堡的","examples":[{"en":"Marlborough-based Aquaflow announced its breakthrough in 2006.","zh":"總部位於馬爾堡的Aquaflow在2006年宣布其突破。"},{"en":"Marlborough-based means located in or operating from Marlborough.","zh":"Marlborough-based指位於或從馬爾堡營運。"},{"en":"A London-based charity has its main office in London.","zh":"一間總部位於倫敦的慈善機構，其主要辦公室在倫敦。"},{"en":"If a company is Marlborough-based, its local environment may shape its work.","zh":"如果一間公司總部位於馬爾堡，當地環境可能塑造其工作。"},{"en":"The phrase tells us the organisation’s base, not necessarily where all its customers are.","zh":"這個短語告訴我們機構的基地，而不一定是所有顧客所在地。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":2},{"front":"announce","meaning":"宣布","examples":[{"en":"Aquaflow announced that it had produced biodiesel from wild microalgae.","zh":"Aquaflow宣布它已從野生微藻中生產出生物柴油。"},{"en":"To announce something means to tell people it officially or publicly.","zh":"announce某事，意思是正式或公開告訴人們。"},{"en":"A school may announce exam results on its website.","zh":"學校可能在網站上宣布考試結果。"},{"en":"If a company announces a new product, customers and investors may pay attention.","zh":"如果公司宣布新產品，顧客和投資者可能會留意。"},{"en":"Announce is stronger and more public than simply say.","zh":"announce比單純的say更正式、更公開。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":2},{"front":"be derived from","meaning":"源自……","examples":[{"en":"The biodiesel was derived from wild microalgae.","zh":"這種生物柴油源自野生微藻。"},{"en":"To be derived from something means to come from it or be made from it.","zh":"be derived from某物，意思是來自某物或由某物製成。"},{"en":"Some medicines are derived from plants found in forests.","zh":"有些藥物源自森林中的植物。"},{"en":"If a word is derived from Latin, its spelling may look similar to other European words.","zh":"如果一個字源自拉丁文，它的拼寫可能與其他歐洲語言的字相似。"},{"en":"The phrase shows the source or origin of something.","zh":"這個短語顯示某物的來源或起源。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":2},{"front":"wild microalgae","meaning":"野生微藻","examples":[{"en":"Aquaflow produced biodiesel derived from wild microalgae.","zh":"Aquaflow生產了源自野生微藻的生物柴油。"},{"en":"Wild microalgae are tiny algae that grow naturally in water or waste streams.","zh":"野生微藻是在水中或廢物流中自然生長的微小藻類。"},{"en":"Scientists may collect wild microalgae from ponds to study their oil content.","zh":"科學家可能從池塘收集野生微藻，以研究其含油量。"},{"en":"If wild microalgae grow too quickly, they can create environmental problems.","zh":"如果野生微藻生長得太快，可能造成環境問題。"},{"en":"The word micro- tells us the algae are extremely small.","zh":"micro-這個字首告訴我們這些藻類非常細小。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":2},{"front":"be sourced from","meaning":"來自……","examples":[{"en":"The microalgae were sourced from local sewage ponds.","zh":"這些微藻來自本地污水池。"},{"en":"To be sourced from a place means to be obtained or collected from there.","zh":"be sourced from某地，意思是從該地方取得或收集。"},{"en":"The restaurant’s vegetables are sourced from nearby farms.","zh":"這間餐廳的蔬菜來自附近農場。"},{"en":"If materials are sourced from responsible suppliers, customers may trust the company more.","zh":"如果材料來自負責任的供應商，顧客可能更信任公司。"},{"en":"The phrase focuses on where something is obtained.","zh":"這個短語重點在於某物從哪裏取得。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":2},{"front":"local sewage ponds","meaning":"本地污水池","examples":[{"en":"The wild microalgae were sourced from local sewage ponds.","zh":"這些野生微藻來自本地污水池。"},{"en":"Local sewage ponds are nearby ponds used to hold or treat wastewater.","zh":"本地污水池是附近用來儲存或處理污水的池塘。"},{"en":"A town may clean its local sewage ponds to reduce bad smells and pollution.","zh":"城鎮可能清理本地污水池，以減少臭味和污染。"},{"en":"If algae grow in local sewage ponds, they may remove nutrients from the water.","zh":"如果藻類在本地污水池中生長，它們可能從水中移除養分。"},{"en":"The phrase describes a waste-treatment place, not a natural swimming pond.","zh":"這個短語描述的是廢水處理地方，而不是天然游泳池。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":3},{"front":"test drive a car","meaning":"試駕汽車","examples":[{"en":"Aquaflow claimed to test drive a car powered by wild algae-based biodiesel.","zh":"Aquaflow聲稱試駕了一部由野生藻類生物柴油驅動的汽車。"},{"en":"To test drive a car means to drive it for a short time to check how it performs.","zh":"test drive a car指短時間駕駛汽車，以檢查其表現。"},{"en":"Buyers often test drive a car before deciding whether to buy it.","zh":"買家常在決定是否買車前試駕汽車。"},{"en":"If engineers test drive a car after repairs, they can find problems before customers use it.","zh":"如果工程師在維修後試駕汽車，他們可以在顧客使用前發現問題。"},{"en":"A test drive is practical because it shows how the car behaves on the road.","zh":"試駕很實際，因為它顯示汽車在路上的表現。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":3},{"front":"powered by","meaning":"由……驅動","examples":[{"en":"The car was powered by wild algae-based biodiesel.","zh":"這部車由野生藻類生物柴油驅動。"},{"en":"Powered by something means using that thing as the source of energy.","zh":"powered by某物，意思是以某物作為能源來源。"},{"en":"Some calculators are powered by sunlight instead of batteries.","zh":"有些計算機由陽光而不是電池驅動。"},{"en":"If a bus is powered by cleaner fuel, it may produce less pollution.","zh":"如果巴士由較潔淨燃料驅動，它可能產生較少污染。"},{"en":"The phrase tells us what makes a machine move or work.","zh":"這個短語告訴我們是甚麼令機器移動或運作。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":3},{"front":"algae-based biodiesel","meaning":"藻類生物柴油","examples":[{"en":"Algae-based biodiesel could become a cleaner fuel alternative.","zh":"藻類生物柴油可能成為一種較潔淨的替代燃料。"},{"en":"Algae-based biodiesel is biodiesel made from algae rather than from crops such as corn.","zh":"藻類生物柴油是由藻類而不是粟米等農作物製成的生物柴油。"},{"en":"A coastal city may study algae-based biodiesel because algae are easy to collect there.","zh":"沿海城市可能研究藻類生物柴油，因為當地容易收集藻類。"},{"en":"If algae-based biodiesel becomes affordable, it could reduce dependence on mineral diesel.","zh":"如果藻類生物柴油變得負擔得起，它可以減少對礦物柴油的依賴。"},{"en":"This fuel is interesting because algae can grow in places unsuitable for food crops.","zh":"這種燃料有趣，因為藻類可以在不適合食物作物的地方生長。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":3},{"front":"come as a surprise to","meaning":"令……感到驚訝","examples":[{"en":"The breakthrough came as a surprise to some biodiesel experts.","zh":"這項突破令一些生物柴油專家感到驚訝。"},{"en":"To come as a surprise to someone means to be unexpected for that person.","zh":"come as a surprise to某人，意思是某事對那個人來說出乎意料。"},{"en":"The exam result came as a surprise to the student because she thought she had failed.","zh":"考試成績令那名學生感到驚訝，因為她以為自己不及格。"},{"en":"If a small company wins a major prize, it may come as a surprise to larger competitors.","zh":"如果小公司贏得重要獎項，可能令大型競爭者感到驚訝。"},{"en":"This phrase shows that people did not expect the event to happen so soon or in that way.","zh":"這個短語顯示人們原本沒有預期事情會這麼快或以這種方式發生。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":3},{"front":"international biodiesel industry","meaning":"國際生物柴油業界","examples":[{"en":"The discovery surprised people in the international biodiesel industry.","zh":"這項發現令國際生物柴油業界的人感到驚訝。"},{"en":"The international biodiesel industry includes companies, scientists, investors, and policymakers involved in biodiesel around the world.","zh":"國際生物柴油業界包括世界各地參與生物柴油的公司、科學家、投資者和政策制定者。"},{"en":"The international biodiesel industry watches new fuel technologies closely.","zh":"國際生物柴油業界密切留意新燃料技術。"},{"en":"If one country develops cheaper biodiesel, the international biodiesel industry may change quickly.","zh":"如果某個國家開發出較便宜的生物柴油，國際生物柴油業界可能迅速改變。"},{"en":"The phrase refers to a global business and research field, not one local company.","zh":"這個短語指全球性的商業和研究領域，而不是一間本地公司。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":3},{"front":"believe that","meaning":"相信","examples":[{"en":"Some experts believed that this breakthrough was still years away.","zh":"一些專家相信這項突破仍需多年才會實現。"},{"en":"Believe that is used to introduce what someone thinks is true.","zh":"believe that用來引出某人認為真實的事情。"},{"en":"Many teachers believe that reading every day improves writing.","zh":"許多老師相信每天閱讀能改善寫作。"},{"en":"If people believe that a product is unsafe, they may refuse to buy it.","zh":"如果人們相信某產品不安全，他們可能拒絕購買。"},{"en":"The phrase reports an opinion or judgement, not always a proven fact.","zh":"這個短語報告一種看法或判斷，不一定是已證實的事實。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":3},{"front":"this breakthrough","meaning":"這項突破","examples":[{"en":"Aquaflow believed that this breakthrough created a huge opportunity.","zh":"Aquaflow相信這項突破為新西蘭創造了巨大機會。"},{"en":"This breakthrough means this important new discovery or success.","zh":"this breakthrough指這項重要的新發現或成功。"},{"en":"This breakthrough in medicine could help doctors treat the disease earlier.","zh":"醫學上的這項突破可以幫助醫生更早治療該疾病。"},{"en":"If this breakthrough lowers costs, ordinary families may benefit.","zh":"如果這項突破降低成本，普通家庭可能受惠。"},{"en":"The phrase is used when a development removes a serious barrier.","zh":"這個短語用於某項發展移除重大障礙時。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":3},{"front":"still years away","meaning":"仍需多年才會實現","examples":[{"en":"Some industry people thought the breakthrough was still years away.","zh":"一些業界人士認為這項突破仍需多年才會實現。"},{"en":"Still years away means something is not expected to happen for several more years.","zh":"still years away指某事預計還要數年才會發生。"},{"en":"Fully driverless public buses may still be years away in many cities.","zh":"在許多城市，完全無人駕駛公共巴士可能仍需多年才會實現。"},{"en":"If a cure is still years away, patients need better support now.","zh":"如果治療方法仍需多年才會出現，病人現在需要更好的支援。"},{"en":"The phrase shows that people think progress will take a long time.","zh":"這個短語顯示人們認為進展會花很長時間。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":3},{"front":"inventive Kiwis","meaning":"有創意的新西蘭人","examples":[{"en":"A group of inventive Kiwis helped develop the fuel.","zh":"一群有創意的新西蘭人協助開發了這種燃料。"},{"en":"Inventive Kiwis means creative New Zealanders who find new practical solutions.","zh":"inventive Kiwis指有創意、能找到新實際方案的新西蘭人。"},{"en":"Inventive Kiwis may turn waste materials into useful products.","zh":"有創意的新西蘭人可能把廢料變成有用產品。"},{"en":"If inventive Kiwis receive enough support, their ideas can become real businesses.","zh":"如果有創意的新西蘭人得到足夠支援，他們的想法可以變成真正企業。"},{"en":"The word inventive praises people for being original and resourceful.","zh":"inventive一字讚揚人有原創力和善用資源。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":3},{"front":"in just over a year","meaning":"在剛超過一年內","examples":[{"en":"The team developed the fuel in just over a year.","zh":"團隊在剛超過一年內開發出這種燃料。"},{"en":"In just over a year means in a little more than one year.","zh":"in just over a year指在稍微超過一年的時間內。"},{"en":"She improved her English greatly in just over a year of regular practice.","zh":"她在剛超過一年定期練習中大幅改善英語。"},{"en":"If a company grows in just over a year, its product may meet a real need.","zh":"如果一間公司在剛超過一年內成長，其產品可能滿足了真實需要。"},{"en":"The phrase often suggests that the result happened quite quickly.","zh":"這個短語常暗示結果出現得相當快。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":3},{"front":"a huge opportunity for","meaning":"對……來說的巨大機會","examples":[{"en":"The technology created a huge opportunity for New Zealand.","zh":"這項技術為新西蘭創造了巨大機會。"},{"en":"A huge opportunity for someone is a very large chance to gain, grow, or improve.","zh":"a huge opportunity for某人，指一個非常大的獲益、成長或改善機會。"},{"en":"Online learning can be a huge opportunity for students in remote areas.","zh":"網上學習對偏遠地區學生來說可以是巨大機會。"},{"en":"If a new industry appears, it may create a huge opportunity for young workers.","zh":"如果新行業出現，它可能為年輕工人創造巨大機會。"},{"en":"The phrase is positive and often used in business, education, or national development.","zh":"這個短語帶正面意思，常用於商業、教育或國家發展。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":4},{"front":"a great credit to","meaning":"……的一大功勞","examples":[{"en":"The success was a great credit to the development team.","zh":"這次成功是開發團隊的一大功勞。"},{"en":"A great credit to someone means something shows their ability, effort, or good qualities.","zh":"a great credit to某人，指某事顯示了他們的能力、努力或優點。"},{"en":"The clean classroom is a great credit to the students who looked after it.","zh":"乾淨的課室是照顧它的學生的一大功勞。"},{"en":"If a project succeeds under pressure, it is a great credit to the whole team.","zh":"如果項目在壓力下成功，這是整個團隊的一大功勞。"},{"en":"This phrase gives praise by linking success to the people behind it.","zh":"這個短語透過把成功連繫到背後的人來表達讚賞。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":4},{"front":"see the potential in","meaning":"看出……的潛力","examples":[{"en":"The team saw the potential in this technology from day one.","zh":"團隊從第一天起就看出這項技術的潛力。"},{"en":"To see the potential in something means to recognise what it could become or achieve.","zh":"see the potential in某事，意思是看出它將來可能成為甚麼或達成甚麼。"},{"en":"A teacher may see the potential in a quiet student who writes thoughtful essays.","zh":"老師可能看出一名安靜學生的潛力，因為他寫的文章很有思想。"},{"en":"If investors see the potential in a small company, they may provide funding.","zh":"如果投資者看出一間小公司的潛力，他們可能提供資金。"},{"en":"The phrase focuses on future possibility, not only present performance.","zh":"這個短語重點在於未來可能性，而不只是目前表現。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":4},{"front":"from day one","meaning":"從第一天起","examples":[{"en":"The team recognised the potential of the technology from day one.","zh":"團隊從第一天起就認識到這項技術的潛力。"},{"en":"From day one means from the very beginning.","zh":"from day one意思是從一開始。"},{"en":"From day one, the coach told the players that teamwork mattered most.","zh":"從第一天起，教練就告訴球員團隊合作最重要。"},{"en":"If rules are clear from day one, fewer arguments happen later.","zh":"如果規則從第一天起就清楚，之後會較少出現爭拗。"},{"en":"The phrase stresses that something was true or important right at the start.","zh":"這個短語強調某事從最初已經是真實或重要的。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":4},{"front":"eventually become","meaning":"最終成為","examples":[{"en":"Algae biodiesel could eventually become a sustainable fuel alternative.","zh":"藻類生物柴油可能最終成為一種可持續替代燃料。"},{"en":"Eventually become means become something after time, development, or change.","zh":"eventually become指經過時間、發展或改變後成為某物。"},{"en":"A small habit can eventually become part of a healthy lifestyle.","zh":"一個小習慣可以最終成為健康生活方式的一部分。"},{"en":"If prices fall, electric cars may eventually become normal for most families.","zh":"如果價格下降，電動車可能最終成為大多數家庭的常態。"},{"en":"The phrase shows a future result that may not happen immediately.","zh":"這個短語顯示一個將來結果，但未必即時發生。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":4},{"front":"sustainable","meaning":"可持續的","examples":[{"en":"Biodiesel based on algae could become a sustainable fuel.","zh":"以藻類為基礎的生物柴油可以成為可持續燃料。"},{"en":"Sustainable means able to continue for a long time without causing serious damage or using up resources.","zh":"sustainable指能長期延續，而不造成嚴重破壞或耗盡資源。"},{"en":"A sustainable diet uses food choices that are healthy and not too wasteful.","zh":"可持續飲食使用健康且不太浪費的食物選擇。"},{"en":"If farming is sustainable, soil and water remain useful for future generations.","zh":"如果農業是可持續的，土壤和水源會對未來世代仍然有用。"},{"en":"Sustainable solutions solve today’s problems without creating bigger problems tomorrow.","zh":"可持續方案解決今天的問題，而不為明天製造更大問題。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":4},{"front":"low-cost","meaning":"低成本的","examples":[{"en":"The fuel could become a low-cost alternative for New Zealand.","zh":"這種燃料可以成為新西蘭的低成本替代品。"},{"en":"Low-cost means not expensive to produce, buy, or use.","zh":"low-cost指生產、購買或使用時不昂貴。"},{"en":"A low-cost lunch can help students save money during the school week.","zh":"低成本午餐可以幫助學生在上學日省錢。"},{"en":"If a low-cost medicine works well, more patients can receive treatment.","zh":"如果低成本藥物有效，更多病人可以接受治療。"},{"en":"Low-cost does not always mean poor quality; it means the price is low.","zh":"low-cost不一定代表品質差；它指價格低。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":4},{"front":"cleaner-burning","meaning":"燃燒較潔淨的","examples":[{"en":"Algae biodiesel may become a cleaner-burning fuel alternative.","zh":"藻類生物柴油可能成為燃燒較潔淨的替代燃料。"},{"en":"Cleaner-burning means producing less smoke, pollution, or harmful emissions when burned.","zh":"cleaner-burning指燃燒時產生較少煙霧、污染或有害排放。"},{"en":"A cleaner-burning stove can make a kitchen safer for a family.","zh":"燃燒較潔淨的爐具可以令家庭廚房更安全。"},{"en":"If buses use cleaner-burning fuel, people near busy roads may breathe easier.","zh":"如果巴士使用燃燒較潔淨的燃料，繁忙道路附近的人可能呼吸得更舒服。"},{"en":"The phrase compares how dirty or clean different fuels are when used.","zh":"這個短語比較不同燃料使用時的污染程度。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":4},{"front":"fuel alternative","meaning":"替代燃料","examples":[{"en":"Algae biodiesel could become a fuel alternative for vehicles.","zh":"藻類生物柴油可以成為車輛的替代燃料。"},{"en":"A fuel alternative is another type of fuel that can replace or reduce the use of a common fuel.","zh":"fuel alternative是可以取代或減少使用常見燃料的另一種燃料。"},{"en":"Electricity is a fuel alternative for some cars that no longer need petrol.","zh":"對一些不再需要汽油的汽車來說，電力是一種替代燃料。"},{"en":"If a fuel alternative is cheaper and cleaner, drivers may choose it more often.","zh":"如果替代燃料更便宜、更潔淨，司機可能更常選擇它。"},{"en":"The phrase is useful when discussing energy choices.","zh":"這個短語在討論能源選擇時很有用。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":4},{"front":"power family cars","meaning":"為私家車提供動力","examples":[{"en":"The fuel could power family cars, trucks, buses and boats.","zh":"這種燃料可以為私家車、貨車、巴士和船隻提供動力。"},{"en":"To power family cars means to provide the energy that makes ordinary private cars move.","zh":"power family cars指提供能量，使普通私家車行駛。"},{"en":"Petrol and electricity can both power family cars, depending on the engine.","zh":"汽油和電力都可以為私家車提供動力，視乎引擎而定。"},{"en":"If cleaner fuels power family cars, daily travel may produce less pollution.","zh":"如果較潔淨燃料為私家車提供動力，日常交通可能產生較少污染。"},{"en":"This phrase focuses on normal household transport, not only industrial machines.","zh":"這個短語重點在於普通家庭交通，而不只是工業機器。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":4},{"front":"be used for other purposes","meaning":"用於其他用途","examples":[{"en":"Biodiesel can be used for other purposes such as heating.","zh":"生物柴油可以用於其他用途，例如供暖。"},{"en":"To be used for other purposes means to serve additional uses beyond the main one.","zh":"be used for other purposes指除了主要用途外，還可以服務其他用途。"},{"en":"A school hall can be used for other purposes, such as exams or community meetings.","zh":"學校禮堂可以用於其他用途，例如考試或社區會議。"},{"en":"If old containers are used for other purposes, less rubbish is produced.","zh":"如果舊容器被用於其他用途，垃圾會減少。"},{"en":"The phrase shows that something is flexible and not limited to one use.","zh":"這個短語顯示某物具彈性，不限於一種用途。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":4},{"front":"distributed electricity generation","meaning":"分散式發電","examples":[{"en":"Biodiesel can be used for distributed electricity generation.","zh":"生物柴油可以用於分散式發電。"},{"en":"Distributed electricity generation means producing electricity in many smaller local places rather than only in one large power station.","zh":"分散式發電指在許多較小的本地地點發電，而不是只在一座大型發電廠發電。"},{"en":"Solar panels on homes are one form of distributed electricity generation.","zh":"住宅上的太陽能板是一種分散式發電。"},{"en":"If distributed electricity generation grows, communities may depend less on distant power plants.","zh":"如果分散式發電增長，社區可能較少依賴遠方發電廠。"},{"en":"The phrase is often used in energy planning and local power supply.","zh":"這個短語常用於能源規劃和本地電力供應。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":5},{"front":"global demand for","meaning":"對……的全球需求","examples":[{"en":"There is a global demand for billions of litres of biodiesel.","zh":"全球對數十億公升生物柴油有需求。"},{"en":"Global demand for something means people or markets around the world want or need it.","zh":"global demand for某物指世界各地的人或市場想要或需要它。"},{"en":"There is global demand for clean water technology in dry regions.","zh":"乾旱地區對潔淨水技術有全球需求。"},{"en":"If global demand for batteries rises, companies may open more factories.","zh":"如果全球對電池的需求上升，公司可能開設更多工廠。"},{"en":"The phrase links a product to worldwide need, not just local interest.","zh":"這個短語把產品與全球需要連繫起來，而不只是本地興趣。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":5},{"front":"billions of litres","meaning":"數十億公升","examples":[{"en":"The world needs billions of litres of biodiesel each year.","zh":"世界每年需要數十億公升生物柴油。"},{"en":"Billions of litres means an extremely large amount of liquid.","zh":"billions of litres指極大量液體。"},{"en":"A large city may use billions of litres of water every year.","zh":"一個大城市每年可能使用數十億公升食水。"},{"en":"If an industry needs billions of litres of fuel, production must be highly organised.","zh":"如果一個行業需要數十億公升燃料，生產必須高度有組織。"},{"en":"The phrase helps readers understand the huge scale of demand.","zh":"這個短語幫助讀者理解需求規模巨大。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":5},{"front":"per year","meaning":"每年","examples":[{"en":"Global demand for biodiesel reaches billions of litres per year.","zh":"全球對生物柴油的需求每年達數十億公升。"},{"en":"Per year means each year or every year.","zh":"per year意思是每一年。"},{"en":"The library buys hundreds of new books per year.","zh":"圖書館每年購買數百本新書。"},{"en":"If a family saves a small amount per year, the total can grow over time.","zh":"如果家庭每年儲起一小筆錢，總額會隨時間增加。"},{"en":"The phrase is used to show an annual rate or amount.","zh":"這個短語用來顯示年度比率或數量。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":5},{"front":"readily available","meaning":"容易取得的","examples":[{"en":"Algae are readily available in nutrient-rich waste streams.","zh":"藻類在富含養分的廢物流中容易取得。"},{"en":"Readily available means easy to get, find, or use.","zh":"readily available指容易取得、找到或使用。"},{"en":"Drinking water should be readily available in schools and sports centres.","zh":"學校和體育中心應該容易取得飲用水。"},{"en":"If information is readily available online, students can research more quickly.","zh":"如果資料在網上容易取得，學生可以更快做資料搜集。"},{"en":"The phrase suggests convenience and accessibility.","zh":"這個短語暗示方便和易接觸。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":5},{"front":"be produced in huge volumes","meaning":"大量產生","examples":[{"en":"Algae are produced in huge volumes in waste streams.","zh":"藻類在廢物流中大量產生。"},{"en":"To be produced in huge volumes means to be made or generated in very large amounts.","zh":"be produced in huge volumes指以非常大的數量被製造或產生。"},{"en":"Plastic bottles are produced in huge volumes around the world.","zh":"塑膠樽在世界各地大量生產。"},{"en":"If a useful material is produced in huge volumes, companies may find ways to recycle it.","zh":"如果一種有用材料大量產生，公司可能尋找方法回收它。"},{"en":"The phrase emphasises scale and quantity.","zh":"這個短語強調規模和數量。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":5},{"front":"nutrient-rich waste streams","meaning":"富含養分的廢物流","examples":[{"en":"Algae grow in nutrient-rich waste streams.","zh":"藻類在富含養分的廢物流中生長。"},{"en":"Nutrient-rich waste streams are flows of waste water or material containing substances that help organisms grow.","zh":"富含養分的廢物流是含有幫助生物生長物質的廢水或廢料流。"},{"en":"Food factories may create nutrient-rich waste streams that need treatment.","zh":"食品工廠可能產生需要處理的富含養分廢物流。"},{"en":"If nutrient-rich waste streams are not managed, they can encourage too much algae growth.","zh":"如果富含養分的廢物流管理不善，可能促進過量藻類生長。"},{"en":"The phrase explains why algae can grow strongly in some waste systems.","zh":"這個短語解釋為何藻類能在某些廢物系統中大量生長。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":5},{"front":"settling ponds","meaning":"沉澱池","examples":[{"en":"Algae can be found in the settling ponds of effluent systems.","zh":"藻類可以在污水系統的沉澱池中找到。"},{"en":"Settling ponds are ponds where solids in dirty water sink to the bottom.","zh":"沉澱池是讓污水中的固體沉到底部的池塘。"},{"en":"A farm may use settling ponds before releasing treated water.","zh":"農場可能在排放處理水前使用沉澱池。"},{"en":"If settling ponds are not maintained, waste can build up and smell bad.","zh":"如果沉澱池沒有維護，廢物可能積聚並發臭。"},{"en":"The phrase is common in wastewater treatment.","zh":"這個短語常見於廢水處理。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":5},{"front":"Effluent Management Systems","meaning":"污水管理系統","examples":[{"en":"Algae grow in the settling ponds of Effluent Management Systems.","zh":"藻類在污水管理系統的沉澱池中生長。"},{"en":"Effluent Management Systems are systems that collect, treat, and manage wastewater or liquid waste.","zh":"污水管理系統是收集、處理和管理污水或液體廢物的系統。"},{"en":"A dairy farm needs Effluent Management Systems to handle dirty water safely.","zh":"乳牛農場需要污水管理系統來安全處理污水。"},{"en":"If Effluent Management Systems fail, pollution may enter rivers or soil.","zh":"如果污水管理系統失效，污染可能進入河流或泥土。"},{"en":"The phrase is technical, but it simply refers to managing liquid waste.","zh":"這個短語較技術性，但它簡單來說就是管理液體廢物。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":5},{"front":"renewable indigenous resource","meaning":"可再生本土資源","examples":[{"en":"Algae are a renewable indigenous resource for fuel production.","zh":"藻類是燃料生產的可再生本土資源。"},{"en":"A renewable indigenous resource is a local resource that can be naturally replaced or regenerated.","zh":"可再生本土資源是可自然補充或再生的本地資源。"},{"en":"Sunlight can be a renewable indigenous resource for countries with strong sunshine.","zh":"對陽光充足的國家來說，陽光可以是可再生本土資源。"},{"en":"If a country uses renewable indigenous resources, it may import less fuel.","zh":"如果一個國家使用可再生本土資源，它可能較少進口燃料。"},{"en":"The phrase highlights both local origin and long-term availability.","zh":"這個短語強調本地來源和長期可用性。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":5},{"front":"ideally suited to","meaning":"非常適合……","examples":[{"en":"Algae are ideally suited to the production of fuel.","zh":"藻類非常適合燃料生產。"},{"en":"Ideally suited to something means very suitable for a particular purpose.","zh":"ideally suited to某事，意思是非常適合某個特定用途。"},{"en":"A quiet room is ideally suited to reading and study.","zh":"安靜房間非常適合閱讀和學習。"},{"en":"If a person’s skills are ideally suited to a job, they can perform well quickly.","zh":"如果一個人的技能非常適合某份工作，他可以很快有好表現。"},{"en":"The phrase expresses a strong match between something and its use.","zh":"這個短語表達某物與其用途之間非常配合。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":5},{"front":"production of fuel","meaning":"燃料生產","examples":[{"en":"The algae are suitable for the production of fuel and by-products.","zh":"藻類適合用於燃料和副產品生產。"},{"en":"Production of fuel means the process of making energy sources such as petrol, diesel, or biofuel.","zh":"production of fuel指製造汽油、柴油或生物燃料等能源來源的過程。"},{"en":"The production of fuel from waste can reduce rubbish and create energy.","zh":"從廢物中進行燃料生產可以減少垃圾並創造能源。"},{"en":"If the production of fuel becomes cheaper, transport costs may fall.","zh":"如果燃料生產變得更便宜，交通成本可能下降。"},{"en":"The phrase focuses on making fuel, not simply using it.","zh":"這個短語重點在於製造燃料，而不只是使用燃料。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":6},{"front":"useful by-products","meaning":"有用副產品","examples":[{"en":"The process can produce fuel and other useful by-products.","zh":"這個過程可以生產燃料和其他有用副產品。"},{"en":"Useful by-products are extra materials made during a process that can still be used.","zh":"有用副產品是在某個過程中額外產生、但仍可使用的材料。"},{"en":"When making cheese, whey can be a useful by-product.","zh":"製作芝士時，乳清可以是有用副產品。"},{"en":"If a factory sells useful by-products, it wastes less material.","zh":"如果工廠出售有用副產品，它會浪費較少材料。"},{"en":"The phrase shows that something secondary can still have value.","zh":"這個短語顯示次要產物仍然可以有價值。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":6},{"front":"technology start-up","meaning":"科技初創公司","examples":[{"en":"Aquaflow was a technology start-up working on algae fuel.","zh":"Aquaflow是一間研究藻類燃料的科技初創公司。"},{"en":"A technology start-up is a new company that develops or sells technology-based products or services.","zh":"科技初創公司是開發或銷售科技產品或服務的新公司。"},{"en":"A technology start-up may create an app to help patients book appointments.","zh":"科技初創公司可能創造應用程式，幫助病人預約診症。"},{"en":"If a technology start-up grows quickly, it may need more engineers and investors.","zh":"如果科技初創公司快速成長，它可能需要更多工程師和投資者。"},{"en":"The phrase usually suggests innovation, risk, and early-stage business growth.","zh":"這個短語通常暗示創新、風險和早期商業成長。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":6},{"front":"undertake a pilot","meaning":"進行試驗項目","examples":[{"en":"Aquaflow agreed to undertake a pilot with Marlborough District Council.","zh":"Aquaflow同意與Marlborough District Council進行試驗項目。"},{"en":"To undertake a pilot means to carry out a small trial before a full project begins.","zh":"undertake a pilot指在完整項目開始前進行小規模試驗。"},{"en":"A school may undertake a pilot of a new timetable with one year group first.","zh":"學校可能先為一個年級進行新時間表試驗項目。"},{"en":"If a pilot works well, the organisation may expand the project later.","zh":"如果試驗項目效果良好，機構之後可能擴大項目。"},{"en":"The phrase is common when testing a new idea carefully.","zh":"這個短語常用於謹慎測試新想法時。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":6},{"front":"District Council","meaning":"區議會；地方議會","examples":[{"en":"Aquaflow worked with Marlborough District Council on the pilot project.","zh":"Aquaflow與Marlborough District Council合作進行試驗項目。"},{"en":"A District Council is a local government body responsible for services in a district.","zh":"區議會或地方議會是負責某地區服務的地方政府機構。"},{"en":"A District Council may manage roads, waste collection, water, and local planning.","zh":"區議會可能管理道路、垃圾收集、供水和本地規劃。"},{"en":"If residents complain about pollution, the District Council may investigate.","zh":"如果居民投訴污染，區議會可能調查。"},{"en":"The phrase refers to local government, not national government.","zh":"這個短語指地方政府，而不是中央政府。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":6},{"front":"extract algae from","meaning":"從……提取藻類","examples":[{"en":"The company extracted algae from settling ponds.","zh":"公司從沉澱池中提取藻類。"},{"en":"To extract algae from a place means to remove or collect algae from it.","zh":"extract algae from某地，意思是從該地方移除或收集藻類。"},{"en":"Scientists may extract algae from a lake to examine why the water turned green.","zh":"科學家可能從湖中提取藻類，以研究水為何變綠。"},{"en":"If a machine can extract algae from wastewater, the water may become cleaner.","zh":"如果機器能從廢水中提取藻類，水可能變得更潔淨。"},{"en":"The phrase focuses on taking algae out of a source.","zh":"這個短語重點在於把藻類從來源中取出。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":6},{"front":"based in","meaning":"位於","examples":[{"en":"The effluent system was based in Blenheim.","zh":"該污水系統位於Blenheim。"},{"en":"Based in a place means located there or operating from there.","zh":"based in某地，意思是位於該地或從該地營運。"},{"en":"The charity is based in a small office near the hospital.","zh":"該慈善機構位於醫院附近的一間小辦公室。"},{"en":"If a team is based in the city centre, members can meet clients easily.","zh":"如果團隊位於市中心，成員可以方便會見客戶。"},{"en":"The phrase tells us the main location of a person, group, or system.","zh":"這個短語告訴我們個人、團體或系統的主要位置。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":6},{"front":"remove the main contaminant","meaning":"移除主要污染物","examples":[{"en":"Aquaflow removed the main contaminant from the ponds.","zh":"Aquaflow從池塘中移除主要污染物。"},{"en":"To remove the main contaminant means to take away the substance causing the greatest pollution or problem.","zh":"remove the main contaminant指移除造成最大污染或問題的物質。"},{"en":"A water filter can remove the main contaminant before the water is used for cooking.","zh":"濾水器可以在食水用於煮食前移除主要污染物。"},{"en":"If workers remove the main contaminant early, clean-up becomes easier.","zh":"如果工人及早移除主要污染物，清理工作會更容易。"},{"en":"The phrase is often used in pollution control and safety work.","zh":"這個短語常用於污染控制和安全工作。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":6},{"front":"use as a fuel feedstock","meaning":"用作燃料原料","examples":[{"en":"The algae were removed and used as a fuel feedstock.","zh":"藻類被移除後用作燃料原料。"},{"en":"To use something as a fuel feedstock means to use it as raw material for making fuel.","zh":"use something as a fuel feedstock指把某物用作製造燃料的原材料。"},{"en":"Waste cooking oil can be used as a fuel feedstock for biodiesel.","zh":"廢食油可以用作生物柴油的燃料原料。"},{"en":"If local waste is used as a fuel feedstock, less new material is needed.","zh":"如果本地廢物用作燃料原料，就需要較少新材料。"},{"en":"The phrase connects a material with the fuel-making process.","zh":"這個短語把某種材料與製造燃料的過程連繫起來。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":6},{"front":"fuel feedstock","meaning":"燃料原料","examples":[{"en":"Algae can serve as a feedstock for biodiesel production.","zh":"藻類可以作為生物柴油生產的原料。"},{"en":"Fuel feedstock is raw material used to make fuel.","zh":"fuel feedstock是用來製造燃料的原材料。"},{"en":"Sugarcane can be a fuel feedstock for producing ethanol.","zh":"甘蔗可以是生產乙醇的燃料原料。"},{"en":"If a fuel feedstock is cheap and abundant, fuel production may become easier.","zh":"如果燃料原料便宜且充足，燃料生產可能變得更容易。"},{"en":"The phrase describes the starting material, not the finished fuel.","zh":"這個短語描述起始材料，而不是成品燃料。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":6},{"front":"clean up","meaning":"清理；淨化","examples":[{"en":"Aquaflow helped clean up the council’s water discharge.","zh":"Aquaflow幫助清理地方議會的排放水。"},{"en":"To clean up something means to remove dirt, waste, pollution, or disorder from it.","zh":"clean up某物，意思是移除其中的污垢、廢物、污染或混亂。"},{"en":"Volunteers clean up the beach after the summer holiday.","zh":"義工在暑假後清理海灘。"},{"en":"If a factory cleans up its wastewater, nearby rivers may become healthier.","zh":"如果工廠淨化其廢水，附近河流可能更健康。"},{"en":"The phrase can be used for physical mess, pollution, or even poor management.","zh":"這個短語可用於實體雜亂、污染，甚至管理不善。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":6},{"front":"water discharge","meaning":"排放水","examples":[{"en":"The process helped improve the council’s water discharge.","zh":"這個過程幫助改善地方議會的排放水。"},{"en":"Water discharge is water released from a system, factory, farm, or treatment plant.","zh":"water discharge是從系統、工廠、農場或處理廠排出的水。"},{"en":"A factory must test its water discharge before sending it into a river.","zh":"工廠在把排放水送入河流前，必須進行測試。"},{"en":"If water discharge contains pollutants, wildlife may be harmed.","zh":"如果排放水含有污染物，野生動物可能受害。"},{"en":"The phrase is common in environmental management.","zh":"這個短語常見於環境管理。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":7},{"front":"a process known as","meaning":"一個稱為……的過程","examples":[{"en":"This cleaning process is known as bio-remediation.","zh":"這個清理過程稱為生物修復。"},{"en":"A process known as something means a method that has that particular name.","zh":"a process known as某事，意思是一種有特定名稱的方法。"},{"en":"Plants make food through a process known as photosynthesis.","zh":"植物透過一個稱為光合作用的過程製造食物。"},{"en":"When a process known as recycling is used, waste materials can become new products.","zh":"當一個稱為回收的過程被使用時，廢料可以變成新產品。"},{"en":"The phrase introduces the name of a process clearly.","zh":"這個短語清楚引入某個過程的名稱。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":7},{"front":"bio-remediation","meaning":"生物修復","examples":[{"en":"Bio-remediation uses biological processes to clean pollution.","zh":"生物修復使用生物過程來清理污染。"},{"en":"Bio-remediation is the use of living organisms to remove or reduce pollution.","zh":"生物修復是利用生物移除或減少污染。"},{"en":"Certain plants can be used in bio-remediation to absorb harmful chemicals from soil.","zh":"某些植物可用於生物修復，以吸收泥土中的有害化學物。"},{"en":"If bio-remediation works well, it can clean polluted areas more naturally.","zh":"如果生物修復效果良好，它可以較自然地清理受污染地區。"},{"en":"The word bio- shows that living things are involved.","zh":"bio-這個字首顯示有生物參與其中。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":7},{"front":"dairy farmers","meaning":"乳牛農場主","examples":[{"en":"Dairy farmers can benefit from algae-harvesting technology.","zh":"乳牛農場主可以從藻類收集技術中受益。"},{"en":"Dairy farmers are farmers who keep cows or other animals mainly for milk production.","zh":"乳牛農場主是主要飼養牛或其他動物以生產牛奶的農場主。"},{"en":"Dairy farmers must manage animal waste carefully to protect water quality.","zh":"乳牛農場主必須小心管理動物排泄物，以保護水質。"},{"en":"If dairy farmers reduce pollution, their farms may become more sustainable.","zh":"如果乳牛農場主減少污染，他們的農場可能變得更可持續。"},{"en":"The phrase refers to milk-producing farms, not all types of farming.","zh":"這個短語指生產牛奶的農場，而不是所有類型的農業。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":7},{"front":"food processors","meaning":"食品加工商","examples":[{"en":"Food processors can apply the same harvesting technology.","zh":"食品加工商可以應用同樣的收集技術。"},{"en":"Food processors are companies or people who turn raw food into products for sale.","zh":"食品加工商是把原材料食物製成銷售產品的公司或人士。"},{"en":"Food processors may wash, cut, cook, freeze, or package food.","zh":"食品加工商可能清洗、切割、烹煮、冷藏或包裝食物。"},{"en":"If food processors manage waste badly, they can create pollution and bad smells.","zh":"如果食品加工商管理廢物不善，可能造成污染和臭味。"},{"en":"The phrase refers to the stage between farms and consumers.","zh":"這個短語指農場與消費者之間的階段。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":7},{"front":"benefit in similar ways","meaning":"以相似方式受益","examples":[{"en":"Dairy farmers can benefit in similar ways from the technology.","zh":"乳牛農場主可以以相似方式從這項技術中受益。"},{"en":"To benefit in similar ways means to gain comparable advantages from the same thing.","zh":"benefit in similar ways指從同一件事中獲得相近好處。"},{"en":"Small shops and cafés can benefit in similar ways from a busy new train station.","zh":"小店和咖啡店可以以相似方式從繁忙的新火車站受益。"},{"en":"If two schools use the same reading programme, both may benefit in similar ways.","zh":"如果兩間學校使用同一閱讀計劃，兩者可能以相似方式受益。"},{"en":"The phrase compares positive effects across different people or groups.","zh":"這個短語比較不同人士或群體所得的正面效果。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":7},{"front":"apply the harvesting technology to","meaning":"將收集技術應用於……","examples":[{"en":"Farmers can apply the harvesting technology to waste streams.","zh":"農場主可以將收集技術應用於廢物流。"},{"en":"To apply the harvesting technology to something means to use that collection method in that situation.","zh":"apply the harvesting technology to某物，意思是在該情況中使用那種收集方法。"},{"en":"A factory may apply the harvesting technology to wastewater that contains algae.","zh":"工廠可能將收集技術應用於含有藻類的廢水。"},{"en":"If farms apply the harvesting technology to waste ponds, they may reduce pollution.","zh":"如果農場把收集技術應用於廢水池，它們可能減少污染。"},{"en":"The phrase shows where a technology is put into practical use.","zh":"這個短語顯示技術在哪裏被實際使用。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":7},{"front":"harvesting technology","meaning":"收集技術；採集技術","examples":[{"en":"The harvesting technology removes algae from nutrient-rich waste streams.","zh":"這項收集技術從富含養分的廢物流中移除藻類。"},{"en":"Harvesting technology is equipment or a method used to collect useful biological material.","zh":"收集技術是用來收集有用生物材料的設備或方法。"},{"en":"Farmers use harvesting technology to collect crops quickly and safely.","zh":"農民使用收集技術快速而安全地收割農作物。"},{"en":"If harvesting technology becomes cheaper, small farms can also use it.","zh":"如果收集技術變得更便宜，小農場也可以使用。"},{"en":"In this passage, the phrase refers to collecting algae from waste water.","zh":"在本文中，這個短語指從廢水中收集藻類。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":7},{"front":"blended with","meaning":"與……混合","examples":[{"en":"Biodiesel can be blended with conventional mineral diesel.","zh":"生物柴油可以與傳統礦物柴油混合。"},{"en":"Blended with means mixed together with another substance.","zh":"blended with指與另一種物質混合在一起。"},{"en":"Fruit juice can be blended with yoghurt to make a smoothie.","zh":"果汁可以與乳酪混合製成沙冰。"},{"en":"If biodiesel is blended with ordinary diesel, vehicles may use it more easily.","zh":"如果生物柴油與普通柴油混合，車輛可能更容易使用它。"},{"en":"The phrase suggests combining materials rather than replacing one completely.","zh":"這個短語暗示把材料結合，而不是完全取代其中一方。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":7},{"front":"conventional mineral diesel","meaning":"傳統礦物柴油","examples":[{"en":"Biodiesel may be mixed with conventional mineral diesel.","zh":"生物柴油可以與傳統礦物柴油混合。"},{"en":"Conventional mineral diesel is the ordinary diesel fuel made from fossil sources.","zh":"傳統礦物柴油是由化石來源製成的普通柴油燃料。"},{"en":"Many old trucks still use conventional mineral diesel every day.","zh":"許多舊貨車每天仍使用傳統礦物柴油。"},{"en":"If a country wants cleaner transport, it may reduce its use of conventional mineral diesel.","zh":"如果一個國家想要較潔淨交通，它可能減少使用傳統礦物柴油。"},{"en":"The phrase contrasts traditional fossil diesel with newer alternatives.","zh":"這個短語把傳統化石柴油與較新的替代品作對比。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":7},{"front":"run vehicles","meaning":"驅動車輛","examples":[{"en":"Blended biodiesel can run vehicles without modifications.","zh":"混合生物柴油可以無須改裝便驅動車輛。"},{"en":"To run vehicles means to provide the power that allows vehicles to operate.","zh":"run vehicles指提供動力，使車輛能夠運作。"},{"en":"Petrol can run vehicles, but electricity can run some newer cars.","zh":"汽油可以驅動車輛，而電力可以驅動一些較新的汽車。"},{"en":"If a fuel can run vehicles safely, it may be accepted more quickly.","zh":"如果一種燃料能安全驅動車輛，它可能更快被接受。"},{"en":"The phrase focuses on practical use in transport.","zh":"這個短語重點在於交通中的實際使用。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":7},{"front":"without the need for","meaning":"無須","examples":[{"en":"Biodiesel can run vehicles without the need for modifications.","zh":"生物柴油可以無須改裝便驅動車輛。"},{"en":"Without the need for something means that something is not necessary.","zh":"without the need for某事，意思是不需要某事。"},{"en":"Students can submit homework online without the need for printing.","zh":"學生可以網上提交功課，無須列印。"},{"en":"If a medicine works without the need for surgery, recovery may be easier.","zh":"如果藥物有效而無須手術，康復可能較容易。"},{"en":"The phrase is useful when showing convenience or lower cost.","zh":"這個短語在顯示方便或成本較低時很有用。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":8},{"front":"vehicle modifications","meaning":"車輛改裝","examples":[{"en":"Vehicles using blended biodiesel do not need vehicle modifications.","zh":"使用混合生物柴油的車輛不需要車輛改裝。"},{"en":"Vehicle modifications are changes made to a vehicle’s parts, engine, body, or equipment.","zh":"車輛改裝是對車輛零件、引擎、車身或設備所作的改變。"},{"en":"A van may need vehicle modifications before it can carry wheelchair users safely.","zh":"客貨車可能需要車輛改裝，才能安全運載輪椅使用者。"},{"en":"If a new fuel requires vehicle modifications, adoption may become more expensive.","zh":"如果新燃料需要車輛改裝，採用成本可能變得更高。"},{"en":"The phrase refers to physical changes to the vehicle.","zh":"這個短語指對車輛作出的實體改變。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":8},{"front":"fuel derived from algae","meaning":"由藻類提煉的燃料","examples":[{"en":"Fuel derived from algae can help meet biofuel targets.","zh":"由藻類提煉的燃料可以幫助達到生物燃料目標。"},{"en":"Fuel derived from algae is fuel made from algae or substances taken from algae.","zh":"fuel derived from algae是由藻類或從藻類提取的物質製成的燃料。"},{"en":"Researchers test fuel derived from algae to see whether it can replace diesel.","zh":"研究人員測試由藻類提煉的燃料，看看它能否取代柴油。"},{"en":"If fuel derived from algae uses waste algae, it may avoid competing with food crops.","zh":"如果由藻類提煉的燃料使用廢棄藻類，它可能避免與食物作物競爭。"},{"en":"The phrase tells us the biological source of the fuel.","zh":"這個短語告訴我們燃料的生物來源。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":8},{"front":"help meet","meaning":"幫助達到","examples":[{"en":"Algae-based fuel can help meet the Government B5 target.","zh":"藻類燃料可以幫助達到政府B5目標。"},{"en":"To help meet a target means to contribute to achieving it.","zh":"help meet a target指有助達成某個目標。"},{"en":"Extra revision classes can help meet students’ learning goals.","zh":"額外溫習班可以幫助達到學生的學習目標。"},{"en":"If more people recycle, the city can help meet its waste-reduction target.","zh":"如果更多人回收，城市可以幫助達到減廢目標。"},{"en":"The phrase shows that one action supports a larger aim.","zh":"這個短語顯示某個行動支持一個更大的目標。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":8},{"front":"Government B5 target","meaning":"政府B5目標","examples":[{"en":"Biodiesel can help meet the Government B5 target.","zh":"生物柴油可以幫助達到政府B5目標。"},{"en":"The Government B5 target is an official target related to using B5 biodiesel fuel.","zh":"政府B5目標是與使用B5生物柴油燃料相關的官方目標。"},{"en":"Fuel companies may change their products to help meet the Government B5 target.","zh":"燃料公司可能改變產品，以幫助達到政府B5目標。"},{"en":"If the Government B5 target is reached, biodiesel use will become more common.","zh":"如果政府B5目標達成，生物柴油使用會變得更普遍。"},{"en":"The phrase refers to a policy goal, not a private company’s wish.","zh":"這個短語指政策目標，而不是私人公司的願望。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":8},{"front":"with the prospect of","meaning":"有……的可能性","examples":[{"en":"The fuel has the prospect of increasing its blended proportion over time.","zh":"這種燃料有隨時間提高混合比例的可能性。"},{"en":"With the prospect of something means with the possibility that it may happen in the future.","zh":"with the prospect of某事，意思是有某事將來可能發生的可能性。"},{"en":"Students may study harder with the prospect of entering a good university.","zh":"學生可能因有入讀好大學的可能性而更努力學習。"},{"en":"If a town has the prospect of new jobs, young people may decide to stay.","zh":"如果小鎮有新增工作的可能性，年輕人可能決定留下。"},{"en":"The phrase points to a future possibility, often a hopeful one.","zh":"這個短語指向未來可能性，通常帶有希望。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":8},{"front":"this proportion","meaning":"這個比例","examples":[{"en":"This proportion may increase as biofuel production grows.","zh":"隨着生物燃料生產增長，這個比例可能增加。"},{"en":"This proportion means this share, percentage, or part of a whole.","zh":"this proportion指這個份額、百分比或整體中的部分。"},{"en":"In the class, this proportion of students chose science as their favourite subject.","zh":"在班中，這個比例的學生選擇科學作為最喜歡的科目。"},{"en":"If this proportion becomes too high, the budget may be difficult to manage.","zh":"如果這個比例變得太高，預算可能難以管理。"},{"en":"The phrase refers back to a number or share already mentioned.","zh":"這個短語指回前文已提及的數字或份額。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":8},{"front":"over time","meaning":"隨着時間推移","examples":[{"en":"The proportion of biodiesel may increase over time.","zh":"生物柴油的比例可能隨着時間推移而增加。"},{"en":"Over time means gradually as days, months, or years pass.","zh":"over time指隨着日子、月份或年份過去而逐漸發生。"},{"en":"A student’s confidence can improve over time with regular speaking practice.","zh":"學生的信心可以透過定期口語練習隨着時間推移而提高。"},{"en":"If small debts are ignored, they can grow over time.","zh":"如果小額債務被忽視，它們可能隨着時間推移而增加。"},{"en":"The phrase shows slow change rather than an immediate result.","zh":"這個短語顯示緩慢改變，而不是即時結果。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":8},{"front":"biofuel production","meaning":"生物燃料生產","examples":[{"en":"Biofuel production may increase in the future.","zh":"生物燃料生產將來可能增加。"},{"en":"Biofuel production is the process of making fuel from biological materials.","zh":"biofuel production是從生物材料中製造燃料的過程。"},{"en":"Farmers may provide crops or waste materials for biofuel production.","zh":"農民可能為生物燃料生產提供農作物或廢料。"},{"en":"If biofuel production expands too quickly, land and water use must be managed carefully.","zh":"如果生物燃料生產擴張過快，土地和用水必須小心管理。"},{"en":"The phrase covers the whole process of creating biological fuel.","zh":"這個短語涵蓋創造生物燃料的整個過程。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":8},{"front":"increase capacity","meaning":"提高產能","examples":[{"en":"Aquaflow’s next step is to increase capacity.","zh":"Aquaflow的下一步是提高產能。"},{"en":"To increase capacity means to raise the amount that can be produced, stored, served, or handled.","zh":"increase capacity指提高可生產、儲存、服務或處理的數量。"},{"en":"A hospital may increase capacity by adding more beds and nurses.","zh":"醫院可能透過增加病床和護士來提高接收能力。"},{"en":"If a factory increases capacity, it can make more products each week.","zh":"如果工廠提高產能，它每星期可以製造更多產品。"},{"en":"The phrase is often used when demand is higher than current ability.","zh":"這個短語常用於需求高於目前能力時。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":8},{"front":"produce one million litres","meaning":"生產一百萬公升","examples":[{"en":"The company planned to produce one million litres of biodiesel.","zh":"公司計劃生產一百萬公升生物柴油。"},{"en":"To produce one million litres means to make that exact large amount of liquid product.","zh":"produce one million litres指生產剛好一百萬公升這個大量液體產品。"},{"en":"A drinks factory may produce one million litres of juice during a busy summer.","zh":"飲品工廠可能在繁忙夏季生產一百萬公升果汁。"},{"en":"If a company can produce one million litres, it has moved beyond a tiny experiment.","zh":"如果公司能生產一百萬公升，它已超越小型實驗階段。"},{"en":"The phrase helps show the scale of planned production.","zh":"這個短語有助顯示計劃生產的規模。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":8},{"front":"sewerage ponds","meaning":"污水處理池","examples":[{"en":"Aquaflow planned to produce biodiesel from the Marlborough sewerage ponds.","zh":"Aquaflow計劃從馬爾堡污水處理池生產生物柴油。"},{"en":"Sewerage ponds are ponds used in systems that collect and treat sewage.","zh":"sewerage ponds是用於收集和處理污水系統中的池塘。"},{"en":"A town may build sewerage ponds away from homes to reduce smell and health risks.","zh":"城鎮可能把污水處理池建在遠離民居的地方，以減少臭味和健康風險。"},{"en":"If sewerage ponds are poorly managed, they may pollute nearby water.","zh":"如果污水處理池管理不善，可能污染附近水源。"},{"en":"The phrase refers to wastewater treatment, not ordinary ponds for leisure.","zh":"這個短語指廢水處理，而不是用作休閒的普通池塘。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":9},{"front":"over the next year","meaning":"在未來一年","examples":[{"en":"The company planned to increase production over the next year.","zh":"公司計劃在未來一年提高產量。"},{"en":"Over the next year means during the coming twelve months.","zh":"over the next year指在接下來十二個月期間。"},{"en":"The school will improve its library over the next year.","zh":"學校將在未來一年改善圖書館。"},{"en":"If a business hires more staff over the next year, service may become faster.","zh":"如果企業在未來一年聘請更多員工，服務可能變快。"},{"en":"The phrase sets a future time frame for a plan or change.","zh":"這個短語為計劃或改變設定未來時間範圍。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":9},{"front":"launch a prospectus","meaning":"發布招股章程","examples":[{"en":"Aquaflow planned to launch a prospectus before Christmas.","zh":"Aquaflow計劃在聖誕節前發布招股章程。"},{"en":"To launch a prospectus means to publish a formal document giving information to possible investors.","zh":"launch a prospectus指發布一份向潛在投資者提供資料的正式文件。"},{"en":"A new company may launch a prospectus before raising money from the public.","zh":"新公司可能在向公眾集資前發布招股章程。"},{"en":"If the prospectus is clear, investors can better understand the risks and plans.","zh":"如果招股章程清楚，投資者可以更好理解風險和計劃。"},{"en":"The phrase is mainly used in business and finance contexts.","zh":"這個短語主要用於商業和金融語境。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":9},{"front":"attract considerable interest","meaning":"吸引相當大的興趣","examples":[{"en":"The company attracted considerable interest from potential investors.","zh":"公司吸引了潛在投資者相當大的興趣。"},{"en":"To attract considerable interest means to make many people pay serious attention.","zh":"attract considerable interest指令許多人認真關注。"},{"en":"A new scholarship may attract considerable interest from students.","zh":"一項新獎學金可能吸引學生相當大的興趣。"},{"en":"If a product solves a common problem, it can attract considerable interest quickly.","zh":"如果一件產品解決常見問題，它可以很快吸引相當大的興趣。"},{"en":"The phrase suggests stronger attention than simple curiosity.","zh":"這個短語暗示比普通好奇更強的注意。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":9},{"front":"potential investors","meaning":"潛在投資者","examples":[{"en":"Potential investors showed interest in Aquaflow.","zh":"潛在投資者對Aquaflow表示興趣。"},{"en":"Potential investors are people or organisations that may provide money to a business or project.","zh":"潛在投資者是可能向企業或項目提供資金的人或機構。"},{"en":"A start-up prepares a clear presentation for potential investors.","zh":"初創公司會為潛在投資者準備清楚的簡報。"},{"en":"If potential investors trust the management team, they may decide to invest.","zh":"如果潛在投資者信任管理團隊，他們可能決定投資。"},{"en":"The phrase refers to possible future investors, not confirmed ones.","zh":"這個短語指可能成為投資者的人，而不是已確定的投資者。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":9},{"front":"static engine test","meaning":"靜態引擎測試","examples":[{"en":"The biodiesel was tested successfully in a static engine test.","zh":"這種生物柴油在靜態引擎測試中成功接受測試。"},{"en":"A static engine test checks how an engine works while it stays fixed in one place.","zh":"靜態引擎測試是檢查引擎在固定位置時如何運作。"},{"en":"Engineers may run a static engine test before testing a vehicle on the road.","zh":"工程師可能先進行靜態引擎測試，再把車輛放到道路上測試。"},{"en":"If a fuel passes a static engine test, it may be safer to try in a real vehicle.","zh":"如果燃料通過靜態引擎測試，在真實車輛中試用可能更安全。"},{"en":"The word static means not moving.","zh":"static一字意思是不移動。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":9},{"front":"Wellington campus","meaning":"威靈頓校園","examples":[{"en":"The engine test took place at Massey University’s Wellington campus.","zh":"引擎測試在Massey University的威靈頓校園進行。"},{"en":"A Wellington campus is the part of a university or institution located in Wellington.","zh":"Wellington campus指大學或機構位於威靈頓的校區。"},{"en":"Students at the Wellington campus may attend lectures, use labs, and join clubs there.","zh":"威靈頓校園的學生可以在那裏上課、使用實驗室和參加學會。"},{"en":"If research equipment is based at the Wellington campus, scientists may conduct tests there.","zh":"如果研究設備位於威靈頓校園，科學家可能在那裏進行測試。"},{"en":"The phrase identifies a specific location within a wider institution.","zh":"這個短語指出大型機構中的一個特定地點。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":9},{"front":"be used by humans in many ways","meaning":"被人類以多種方式使用","examples":[{"en":"Algae are used by humans in many ways.","zh":"藻類被人類以多種方式使用。"},{"en":"To be used by humans in many ways means to have several practical uses for people.","zh":"be used by humans in many ways指對人類有多種實際用途。"},{"en":"Plants are used by humans in many ways, including food, medicine, clothing, and building materials.","zh":"植物被人類以多種方式使用，包括食物、藥物、衣物和建材。"},{"en":"If a natural resource is used by humans in many ways, careful management becomes important.","zh":"如果一種自然資源被人類以多種方式使用，謹慎管理就變得重要。"},{"en":"The phrase shows that something is versatile and useful.","zh":"這個短語顯示某物用途廣泛而有用。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":9},{"front":"fertilisers","meaning":"肥料","examples":[{"en":"Algae can be used as fertilisers.","zh":"藻類可以用作肥料。"},{"en":"Fertilisers are substances added to soil to help plants grow.","zh":"肥料是加入泥土以幫助植物生長的物質。"},{"en":"Farmers use fertilisers when crops need more nutrients.","zh":"當農作物需要更多養分時，農民會使用肥料。"},{"en":"If too much fertiliser enters rivers, it can cause pollution.","zh":"如果太多肥料進入河流，可能造成污染。"},{"en":"Fertilisers can be natural or chemical, but both must be used carefully.","zh":"肥料可以是天然或化學的，但兩者都必須小心使用。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":9},{"front":"soil conditioners","meaning":"土壤改良劑","examples":[{"en":"Algae can be used as soil conditioners.","zh":"藻類可以用作土壤改良劑。"},{"en":"Soil conditioners are materials added to soil to improve its structure, moisture, or fertility.","zh":"土壤改良劑是加入泥土以改善其結構、濕度或肥力的材料。"},{"en":"Compost is a common soil conditioner in gardens.","zh":"堆肥是花園中常見的土壤改良劑。"},{"en":"If soil conditioners improve dry soil, plants may grow better.","zh":"如果土壤改良劑改善乾燥泥土，植物可能生長得更好。"},{"en":"Unlike fertilisers, soil conditioners often focus on soil quality as a whole.","zh":"不同於肥料，土壤改良劑通常重點在於整體土壤質素。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":9},{"front":"livestock feed","meaning":"牲畜飼料","examples":[{"en":"Algae are sometimes used as livestock feed.","zh":"藻類有時用作牲畜飼料。"},{"en":"Livestock feed is food given to farm animals such as cows, sheep, pigs, or chickens.","zh":"牲畜飼料是給牛、羊、豬或雞等農場動物吃的食物。"},{"en":"Farmers choose livestock feed that keeps animals healthy and productive.","zh":"農民選擇能保持動物健康和高產的牲畜飼料。"},{"en":"If livestock feed becomes expensive, the cost of meat and milk may rise.","zh":"如果牲畜飼料變得昂貴，肉類和牛奶成本可能上升。"},{"en":"The phrase refers to animal food, not food for humans.","zh":"這個短語指動物食物，而不是人類食物。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":9},{"front":"aquatic and microscopic species","meaning":"水生及微小物種","examples":[{"en":"Aquatic and microscopic species of algae are cultured in ponds.","zh":"水生及微小的藻類物種在池塘中培養。"},{"en":"Aquatic and microscopic species are tiny living things that live in water.","zh":"水生及微小物種是生活在水中的極細小生物。"},{"en":"Scientists use microscopes to study aquatic and microscopic species in lake water.","zh":"科學家使用顯微鏡研究湖水中的水生及微小物種。"},{"en":"If aquatic and microscopic species grow too fast, the water may change colour.","zh":"如果水生及微小物種生長太快，水可能變色。"},{"en":"The phrase combines habitat, water, with size, very small.","zh":"這個短語結合了棲息環境，即水中，以及大小，即非常細小。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":10},{"front":"be cultured in","meaning":"在……中培養","examples":[{"en":"Some algae species are cultured in clear tanks or ponds.","zh":"一些藻類物種在透明水槽或池塘中培養。"},{"en":"To be cultured in a place means to be grown or kept there under controlled conditions.","zh":"be cultured in某處，意思是在受控制條件下於該處生長或保存。"},{"en":"Bacteria may be cultured in a lab dish for medical testing.","zh":"細菌可能在實驗室培養皿中培養，以作醫學測試。"},{"en":"If algae are cultured in clean tanks, researchers can control their growth more easily.","zh":"如果藻類在潔淨水槽中培養，研究人員可以更容易控制其生長。"},{"en":"The phrase is often used in science, farming, and aquaculture.","zh":"這個短語常用於科學、農業和水產養殖。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":10},{"front":"clear tanks","meaning":"透明水槽","examples":[{"en":"Microscopic algae can be cultured in clear tanks.","zh":"微小藻類可以在透明水槽中培養。"},{"en":"Clear tanks are transparent containers that allow people to see what is growing or happening inside.","zh":"透明水槽是可讓人看見內部生長或發生情況的透明容器。"},{"en":"Fish shops often keep small fish in clear tanks so customers can see them.","zh":"魚店常把小魚養在透明水槽中，讓顧客看見。"},{"en":"If algae grow in clear tanks, scientists can watch changes in colour and density.","zh":"如果藻類在透明水槽中生長，科學家可以觀察顏色和密度變化。"},{"en":"The phrase emphasises visibility through the tank walls.","zh":"這個短語強調能透過水槽壁看見內部。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":10},{"front":"be harvested","meaning":"被收集；被採集","examples":[{"en":"The algae are either harvested or used to treat effluents.","zh":"這些藻類要麼被採集，要麼用於處理污水。"},{"en":"To be harvested means to be collected after growing.","zh":"be harvested指在生長後被收集。"},{"en":"Rice is harvested when the grains are ready.","zh":"稻米在穀粒成熟時被收割。"},{"en":"If algae are harvested at the right time, more useful material can be collected.","zh":"如果藻類在適當時間被採集，可以收集到更多有用材料。"},{"en":"The phrase is used for crops, plants, algae, and other biological resources.","zh":"這個短語用於農作物、植物、藻類和其他生物資源。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":10},{"front":"treat effluents","meaning":"處理污水","examples":[{"en":"Some algae are used to treat effluents pumped through ponds.","zh":"一些藻類被用來處理被泵送通過池塘的污水。"},{"en":"To treat effluents means to clean or process wastewater before it is released or reused.","zh":"treat effluents指在污水排放或重用前對其進行清潔或處理。"},{"en":"A factory must treat effluents so harmful chemicals do not enter rivers.","zh":"工廠必須處理污水，以免有害化學物進入河流。"},{"en":"If communities treat effluents properly, public health and water quality improve.","zh":"如果社區妥善處理污水，公共健康和水質會改善。"},{"en":"The phrase is common in environmental protection and waste management.","zh":"這個短語常見於環境保護和廢物管理。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":10},{"front":"be pumped through","meaning":"被泵送通過","examples":[{"en":"Effluents are pumped through ponds for treatment.","zh":"污水被泵送通過池塘以作處理。"},{"en":"To be pumped through something means to be moved through it by a pump.","zh":"be pumped through某物，意思是被泵推動而通過某物。"},{"en":"Water is pumped through pipes to reach apartments on higher floors.","zh":"水被泵送通過水管，以到達較高樓層的單位。"},{"en":"If wastewater is pumped through filters, dirt and chemicals may be removed.","zh":"如果廢水被泵送通過過濾器，污垢和化學物可能被移除。"},{"en":"The phrase describes movement caused by a machine, not natural flow.","zh":"這個短語描述由機器造成的移動，而不是自然流動。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":10},{"front":"algaculture","meaning":"藻類養殖","examples":[{"en":"Algaculture on a large scale is an important type of aquaculture.","zh":"大規模藻類養殖是一種重要的水產養殖。"},{"en":"Algaculture is the farming or cultivation of algae.","zh":"algaculture是藻類的養殖或培育。"},{"en":"A company may use algaculture to grow algae for food, fuel, or supplements.","zh":"公司可能利用藻類養殖來培養用於食物、燃料或補充品的藻類。"},{"en":"If algaculture expands, water quality and space must be managed carefully.","zh":"如果藻類養殖擴大，水質和空間必須小心管理。"},{"en":"The word combines algae and culture, meaning cultivation.","zh":"這個字結合algae和culture，意思是培育。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":10},{"front":"on a large scale","meaning":"大規模地","examples":[{"en":"Algaculture can be practised on a large scale.","zh":"藻類養殖可以大規模進行。"},{"en":"On a large scale means involving a large area, large number, or large amount.","zh":"on a large scale指涉及大面積、大數量或大量。"},{"en":"Vaccination programmes work best on a large scale when many people join.","zh":"當很多人參與時，疫苗接種計劃大規模推行效果最好。"},{"en":"If farming is done on a large scale, machinery and planning become very important.","zh":"如果農業大規模進行，機械和規劃會變得非常重要。"},{"en":"The phrase contrasts with small experiments or limited local action.","zh":"這個短語與小型實驗或有限本地行動形成對比。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":10},{"front":"aquaculture","meaning":"水產養殖","examples":[{"en":"Algaculture is an important type of aquaculture in some places.","zh":"在一些地方，藻類養殖是一種重要的水產養殖。"},{"en":"Aquaculture is the farming of fish, shellfish, seaweed, or other aquatic organisms.","zh":"水產養殖是魚類、貝類、海藻或其他水生生物的養殖。"},{"en":"Fish farms are a common form of aquaculture.","zh":"魚場是常見的水產養殖形式。"},{"en":"If aquaculture is poorly managed, waste and disease can harm nearby waters.","zh":"如果水產養殖管理不善，廢物和疾病可能傷害附近水域。"},{"en":"The word aqua- connects the activity with water.","zh":"aqua-這個字首把活動與水連繫起來。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":10},{"front":"naturally growing seaweeds","meaning":"天然生長的海藻","examples":[{"en":"Naturally growing seaweeds are an important source of food.","zh":"天然生長的海藻是重要的食物來源。"},{"en":"Naturally growing seaweeds are sea plants that grow without being planted by people.","zh":"天然生長的海藻是不用人類種植而自然生長的海中植物。"},{"en":"Coastal communities may collect naturally growing seaweeds for cooking.","zh":"沿海社區可能收集天然生長的海藻來烹調。"},{"en":"If naturally growing seaweeds are overharvested, the local ecosystem may suffer.","zh":"如果天然生長的海藻被過度採集，本地生態系統可能受損。"},{"en":"The phrase contrasts wild growth with farmed cultivation.","zh":"這個短語把野外自然生長與人工養殖作對比。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":10},{"front":"source of food","meaning":"食物來源","examples":[{"en":"Seaweeds are an important source of food in Asia.","zh":"海藻在亞洲是重要的食物來源。"},{"en":"A source of food is something that provides food for people or animals.","zh":"source of food是為人或動物提供食物的東西。"},{"en":"Rice is a major source of food for many communities.","zh":"稻米是許多社區的主要食物來源。"},{"en":"If a river is polluted, it may stop being a safe source of food.","zh":"如果河流受污染，它可能不再是安全的食物來源。"},{"en":"The phrase tells us where food comes from.","zh":"這個短語告訴我們食物來自哪裏。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":10},{"front":"especially in Asia","meaning":"尤其在亞洲","examples":[{"en":"Seaweed is widely eaten, especially in Asia.","zh":"海藻被廣泛食用，尤其在亞洲。"},{"en":"Especially in Asia means particularly or more commonly in Asian countries or regions.","zh":"especially in Asia指尤其或更常見於亞洲國家或地區。"},{"en":"Rice is eaten daily in many places, especially in Asia.","zh":"稻米在許多地方每天被食用，尤其在亞洲。"},{"en":"If a product is popular especially in Asia, companies may design it for Asian markets first.","zh":"如果某產品尤其在亞洲受歡迎，公司可能先為亞洲市場設計它。"},{"en":"The phrase narrows a general statement to a more important region.","zh":"這個短語把一般陳述收窄到一個更重要的地區。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":11},{"front":"provide many vitamins","meaning":"提供多種維他命","examples":[{"en":"Seaweeds provide many vitamins and minerals.","zh":"海藻提供多種維他命和礦物質。"},{"en":"To provide many vitamins means to supply several nutrients that help the body stay healthy.","zh":"provide many vitamins指供應多種有助身體保持健康的營養素。"},{"en":"Fresh fruit can provide many vitamins for children.","zh":"新鮮水果可以為孩子提供多種維他命。"},{"en":"If meals provide many vitamins, people may have stronger immunity and better health.","zh":"如果餐膳提供多種維他命，人們可能有更強免疫力和更好健康。"},{"en":"The phrase is often used when explaining nutritional value.","zh":"這個短語常用於解釋營養價值。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":11},{"front":"be rich in","meaning":"富含……","examples":[{"en":"Seaweeds are rich in iodine, potassium and iron.","zh":"海藻富含碘、鉀和鐵。"},{"en":"To be rich in something means to contain a large amount of it.","zh":"be rich in某物，意思是含有大量該物。"},{"en":"Oranges are rich in vitamin C.","zh":"橙富含維他命C。"},{"en":"If a diet is rich in fibre, digestion may improve.","zh":"如果飲食富含纖維，消化可能改善。"},{"en":"The phrase can describe nutrients, resources, history, or culture.","zh":"這個短語可以描述營養、資源、歷史或文化。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":11},{"front":"iodine","meaning":"碘","examples":[{"en":"Seaweeds are rich in iodine.","zh":"海藻富含碘。"},{"en":"Iodine is a mineral the body needs, especially for healthy thyroid function.","zh":"碘是身體需要的礦物質，尤其對甲狀腺健康功能重要。"},{"en":"Some table salt contains iodine to help prevent deficiency.","zh":"有些食鹽含有碘，以幫助預防缺乏。"},{"en":"If a person lacks iodine, health problems may develop.","zh":"如果一個人缺乏碘，可能出現健康問題。"},{"en":"In food writing, iodine is often mentioned as a nutrient found in seaweed.","zh":"在食物相關寫作中，碘常被提及為海藻中的營養素。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":11},{"front":"potassium","meaning":"鉀","examples":[{"en":"Seaweeds provide potassium and other minerals.","zh":"海藻提供鉀和其他礦物質。"},{"en":"Potassium is a mineral that helps the body’s muscles and nerves work properly.","zh":"鉀是一種幫助身體肌肉和神經正常運作的礦物質。"},{"en":"Bananas are often known as a source of potassium.","zh":"香蕉常被視為鉀的來源。"},{"en":"If a diet has too little potassium, the body may not function well.","zh":"如果飲食中鉀太少，身體可能無法良好運作。"},{"en":"The word often appears in discussions of nutrition and health.","zh":"這個字常出現在營養和健康討論中。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":11},{"front":"magnesium","meaning":"鎂","examples":[{"en":"Seaweeds contain magnesium and calcium.","zh":"海藻含有鎂和鈣。"},{"en":"Magnesium is a mineral involved in many body functions, including muscle and nerve activity.","zh":"鎂是一種參與多種身體功能的礦物質，包括肌肉和神經活動。"},{"en":"Nuts and green vegetables can contain magnesium.","zh":"果仁和綠色蔬菜可能含有鎂。"},{"en":"If people do not get enough magnesium, they may feel tired or weak.","zh":"如果人們攝取不足夠的鎂，可能感到疲倦或虛弱。"},{"en":"The word is commonly used when describing minerals in food.","zh":"這個字常用於描述食物中的礦物質。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":11},{"front":"calcium","meaning":"鈣","examples":[{"en":"Seaweeds are a source of calcium.","zh":"海藻是鈣的來源。"},{"en":"Calcium is a mineral important for strong bones and teeth.","zh":"鈣是對強健骨骼和牙齒重要的礦物質。"},{"en":"Milk, tofu, and some vegetables can provide calcium.","zh":"牛奶、豆腐和一些蔬菜可以提供鈣。"},{"en":"If children do not get enough calcium, bone development may be affected.","zh":"如果兒童攝取不足夠的鈣，骨骼發展可能受影響。"},{"en":"The word is often used in health, diet, and food labels.","zh":"這個字常用於健康、飲食和食物標籤。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":11},{"front":"commercially cultivated microalgae","meaning":"商業培植的微藻","examples":[{"en":"Commercially cultivated microalgae are marketed as supplements.","zh":"商業培植的微藻被作為補充品銷售。"},{"en":"Commercially cultivated microalgae are tiny algae grown by businesses for sale or industrial use.","zh":"商業培植的微藻是由企業培養、用於銷售或工業用途的微小藻類。"},{"en":"A company may grow commercially cultivated microalgae in tanks to control quality.","zh":"公司可能在水槽中培養商業培植的微藻，以控制品質。"},{"en":"If commercially cultivated microalgae are safe and nutritious, they can become health products.","zh":"如果商業培植的微藻安全且有營養，它們可以成為健康產品。"},{"en":"The phrase contrasts business production with wild natural growth.","zh":"這個短語把商業生產與野外自然生長作對比。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":11},{"front":"cyanobacteria","meaning":"藍綠菌；藍細菌","examples":[{"en":"Some cyanobacteria are marketed as nutritional supplements.","zh":"一些藍綠菌被作為營養補充品銷售。"},{"en":"Cyanobacteria are microscopic organisms that can perform photosynthesis and are sometimes called blue-green bacteria.","zh":"藍綠菌是能進行光合作用的微小生物，有時稱為藍細菌。"},{"en":"Scientists study cyanobacteria because they can grow in water and use sunlight.","zh":"科學家研究藍綠菌，因為它們能在水中生長並利用陽光。"},{"en":"If cyanobacteria grow too much in lakes, the water may become unsafe.","zh":"如果藍綠菌在湖中過度生長，水可能變得不安全。"},{"en":"The word is scientific, so context helps learners understand it.","zh":"這個字較科學，所以語境能幫助學習者理解。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":11},{"front":"be marketed as","meaning":"作為……銷售","examples":[{"en":"Microalgae are marketed as nutritional supplements.","zh":"微藻被作為營養補充品銷售。"},{"en":"To be marketed as something means to be advertised and sold in that role or category.","zh":"be marketed as某物，意思是以該身份或類別被宣傳和銷售。"},{"en":"Some drinks are marketed as healthy even though they contain a lot of sugar.","zh":"有些飲品被作為健康飲品銷售，雖然它們含有大量糖。"},{"en":"If a product is marketed as eco-friendly, customers may expect less wasteful packaging.","zh":"如果產品被作為環保產品銷售，顧客可能期望較少浪費的包裝。"},{"en":"The phrase focuses on how a product is presented to buyers.","zh":"這個短語重點在於產品如何呈現給買家。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":11},{"front":"nutritional supplements","meaning":"營養補充品","examples":[{"en":"Spirulina and Chlorella are sold as nutritional supplements.","zh":"螺旋藻和小球藻作為營養補充品出售。"},{"en":"Nutritional supplements are products taken to add nutrients to a person’s diet.","zh":"營養補充品是用來為個人飲食增加營養的產品。"},{"en":"Some people take nutritional supplements when their meals lack certain vitamins.","zh":"有些人在膳食缺乏某些維他命時服用營養補充品。"},{"en":"If nutritional supplements are used carelessly, they may not solve poor eating habits.","zh":"如果營養補充品使用不當，它們未必能解決不良飲食習慣。"},{"en":"The phrase refers to extra nutrition, not a replacement for all food.","zh":"這個短語指額外營養，而不是所有食物的替代品。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":11},{"front":"high in","meaning":"含有大量……","examples":[{"en":"Dunaliella is high in beta-carotene.","zh":"杜氏藻含有大量β-胡蘿蔔素。"},{"en":"High in something means containing a large amount of it.","zh":"high in某物指含有大量該物。"},{"en":"Nuts are high in healthy fats.","zh":"果仁含有大量健康脂肪。"},{"en":"If a snack is high in sugar, eating too much of it can harm health.","zh":"如果零食含有大量糖，吃太多可能傷害健康。"},{"en":"The phrase is common on food labels and in nutrition advice.","zh":"這個短語常見於食物標籤和營養建議。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":12},{"front":"beta-carotene","meaning":"β-胡蘿蔔素","examples":[{"en":"Dunaliella is high in beta-carotene.","zh":"杜氏藻含有大量β-胡蘿蔔素。"},{"en":"Beta-carotene is a natural pigment and nutrient that the body can use to make vitamin A.","zh":"β-胡蘿蔔素是一種天然色素和營養素，身體可用它製造維他命A。"},{"en":"Carrots are orange partly because they contain beta-carotene.","zh":"紅蘿蔔呈橙色，部分原因是它含有β-胡蘿蔔素。"},{"en":"If a food is rich in beta-carotene, it may support eye and skin health.","zh":"如果食物富含β-胡蘿蔔素，它可能支持眼睛和皮膚健康。"},{"en":"The word often appears in discussions of colourful fruits and vegetables.","zh":"這個詞常出現在彩色水果和蔬菜的討論中。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":12},{"front":"traditional foods","meaning":"傳統食物","examples":[{"en":"Algae are traditional foods in many nations.","zh":"藻類在許多國家是傳統食物。"},{"en":"Traditional foods are foods that people have eaten for a long time as part of their culture.","zh":"傳統食物是人們長期作為文化一部分食用的食物。"},{"en":"Dumplings, rice cakes, and seaweed dishes can be traditional foods in different communities.","zh":"餃子、年糕和海藻菜式可以是不同社區的傳統食物。"},{"en":"If traditional foods disappear, younger people may lose part of their cultural memory.","zh":"如果傳統食物消失，年輕人可能失去部分文化記憶。"},{"en":"The phrase connects food with history, family, and identity.","zh":"這個短語把食物與歷史、家庭和身份連繫起來。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":12},{"front":"consume more than","meaning":"消耗超過……","examples":[{"en":"China consumes more than 70 species of algae.","zh":"中國消耗超過70種藻類。"},{"en":"To consume more than a number means to use, eat, or drink above that amount.","zh":"consume more than某數量，意思是使用、食用或飲用超過該數量。"},{"en":"Some families consume more than one bag of rice each month.","zh":"有些家庭每月消耗超過一袋米。"},{"en":"If a city consumes more than it produces, it must import goods.","zh":"如果城市消耗超過自己生產的東西，它必須進口貨物。"},{"en":"The phrase is useful for comparing amounts above a stated level.","zh":"這個短語適合用來比較高於某一水平的數量。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":12},{"front":"be considered a vegetable","meaning":"被視為蔬菜","examples":[{"en":"Fat choy is considered a vegetable.","zh":"髮菜被視為蔬菜。"},{"en":"To be considered a vegetable means people regard it as a vegetable in food or culture.","zh":"be considered a vegetable指人們在食物或文化上把它視為蔬菜。"},{"en":"In some cuisines, seaweed is considered a vegetable and served with rice.","zh":"在一些菜系中，海藻被視為蔬菜並配飯食用。"},{"en":"If a plant is considered a vegetable, people may cook it in savoury dishes.","zh":"如果一種植物被視為蔬菜，人們可能把它煮成鹹味菜式。"},{"en":"The phrase shows how people classify food, not only its biology.","zh":"這個短語顯示人們如何分類食物，而不只是其生物學分類。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":12},{"front":"natural pigments","meaning":"天然色素","examples":[{"en":"Natural pigments produced by algae can replace chemical dyes.","zh":"藻類產生的天然色素可以取代化學染料。"},{"en":"Natural pigments are colour substances that come from plants, animals, minerals, or microorganisms.","zh":"天然色素是來自植物、動物、礦物或微生物的顏色物質。"},{"en":"Beetroot contains natural pigments that can colour food.","zh":"紅菜頭含有可為食物着色的天然色素。"},{"en":"If natural pigments are safe and stable, companies may use them in food products.","zh":"如果天然色素安全且穩定，公司可能把它們用於食品。"},{"en":"The phrase contrasts colours from nature with artificial colouring chemicals.","zh":"這個短語把來自自然的顏色與人工着色化學物作對比。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":12},{"front":"chemical dyes","meaning":"化學染料","examples":[{"en":"Algal pigments can be used instead of chemical dyes.","zh":"藻類色素可以代替化學染料使用。"},{"en":"Chemical dyes are man-made substances used to colour materials or products.","zh":"化學染料是用來為材料或產品着色的人造物質。"},{"en":"Clothes factories use chemical dyes to create bright colours in fabric.","zh":"製衣廠使用化學染料為布料製造鮮艷顏色。"},{"en":"If chemical dyes enter rivers untreated, they may harm aquatic life.","zh":"如果化學染料未經處理進入河流，可能傷害水生生物。"},{"en":"The phrase is often contrasted with natural pigments.","zh":"這個短語常與天然色素作對比。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":12},{"front":"colouring agents","meaning":"着色劑","examples":[{"en":"Algae can provide an alternative to colouring agents.","zh":"藻類可以提供着色劑的替代品。"},{"en":"Colouring agents are substances added to give colour to food, cosmetics, or materials.","zh":"着色劑是加入食物、化妝品或材料中以賦予顏色的物質。"},{"en":"A sweet drink may contain colouring agents to make it look brighter.","zh":"甜飲品可能含有着色劑，使它看起來更鮮艷。"},{"en":"If colouring agents cause allergies, companies may search for safer options.","zh":"如果着色劑引起敏感，公司可能尋找更安全選擇。"},{"en":"The phrase focuses on function: making something coloured.","zh":"這個短語重點在功能：令某物有顏色。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":12},{"front":"an alternative to","meaning":"……的替代品","examples":[{"en":"Natural pigments can be used as an alternative to chemical dyes.","zh":"天然色素可以用作化學染料的替代品。"},{"en":"An alternative to something is another choice that can replace it or serve a similar purpose.","zh":"an alternative to某物是可以取代它或達到相似用途的另一個選擇。"},{"en":"Cycling can be an alternative to taking the bus for short journeys.","zh":"對短途旅程來說，踏單車可以是乘巴士的替代選擇。"},{"en":"If meat is expensive, beans can be an alternative to it in some meals.","zh":"如果肉類昂貴，豆類在某些餐膳中可以作為替代品。"},{"en":"The phrase is useful when comparing choices.","zh":"這個短語在比較選擇時很有用。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":12},{"front":"simplest plant organisms","meaning":"最簡單的植物生物","examples":[{"en":"Algae are among the simplest plant organisms.","zh":"藻類屬於最簡單的植物生物之一。"},{"en":"Simplest plant organisms are very basic plant-like living things with relatively simple structures.","zh":"simplest plant organisms是結構相對簡單的非常基本的植物類生物。"},{"en":"Children may learn about simple plant organisms before studying complex trees and flowers.","zh":"孩子可能先學習簡單植物生物，再學習複雜的樹木和花朵。"},{"en":"If an organism has a simple structure, scientists may use it to study basic life processes.","zh":"如果一種生物結構簡單，科學家可能用它研究基本生命過程。"},{"en":"The phrase helps readers understand that algae are not complex plants.","zh":"這個短語幫助讀者理解藻類不是複雜植物。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":12},{"front":"convert A into B","meaning":"將A轉化為B","examples":[{"en":"Algae convert sunlight and carbon dioxide into stored energy.","zh":"藻類將陽光和二氧化碳轉化為儲存能量。"},{"en":"To convert A into B means to change one thing into another form or use.","zh":"convert A into B指把一樣東西轉變成另一種形式或用途。"},{"en":"A solar panel converts sunlight into electricity.","zh":"太陽能板將陽光轉化為電力。"},{"en":"If a factory converts waste into useful products, less rubbish is thrown away.","zh":"如果工廠把廢物轉化為有用產品，丟棄的垃圾會減少。"},{"en":"The structure clearly shows the starting material and the final result.","zh":"這個結構清楚顯示起始材料和最終結果。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":12},{"front":"carbon dioxide","meaning":"二氧化碳","examples":[{"en":"Algae use carbon dioxide during photosynthesis.","zh":"藻類在光合作用期間使用二氧化碳。"},{"en":"Carbon dioxide is a gas produced by breathing, burning fuel, and many natural processes.","zh":"二氧化碳是一種由呼吸、燃燒燃料和許多自然過程產生的氣體。"},{"en":"Plants take in carbon dioxide and release oxygen during photosynthesis.","zh":"植物在光合作用期間吸收二氧化碳並釋放氧氣。"},{"en":"If too much carbon dioxide enters the atmosphere, it can contribute to climate change.","zh":"如果太多二氧化碳進入大氣，可能加劇氣候變化。"},{"en":"The phrase is common in science, climate, and energy topics.","zh":"這個短語常見於科學、氣候和能源主題。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":13},{"front":"stored energy","meaning":"儲存能量","examples":[{"en":"Algae convert sunlight into stored energy.","zh":"藻類將陽光轉化為儲存能量。"},{"en":"Stored energy is energy kept in a form that can be used later.","zh":"stored energy是以某種形式保存、可稍後使用的能量。"},{"en":"A battery contains stored energy for a phone or laptop.","zh":"電池含有可供手機或手提電腦使用的儲存能量。"},{"en":"If plants store energy from sunlight, animals can later get energy by eating them.","zh":"如果植物儲存來自陽光的能量，動物之後可以透過進食它們取得能量。"},{"en":"The phrase helps explain how energy can be saved rather than used immediately.","zh":"這個短語幫助解釋能量如何被保存，而不是立即使用。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":13},{"front":"through the process of","meaning":"透過……過程","examples":[{"en":"Algae store energy through the process of photosynthesis.","zh":"藻類透過光合作用過程儲存能量。"},{"en":"Through the process of something means by using that process or method.","zh":"through the process of某事，意思是透過該過程或方法。"},{"en":"Students improve their writing through the process of drafting and editing.","zh":"學生透過草擬和修改的過程改善寫作。"},{"en":"Food becomes safer through the process of proper cooking.","zh":"食物透過適當烹煮的過程變得更安全。"},{"en":"The phrase explains how something happens.","zh":"這個短語解釋某事如何發生。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":13},{"front":"photosynthesis","meaning":"光合作用","examples":[{"en":"Photosynthesis allows algae to convert sunlight into energy.","zh":"光合作用使藻類能將陽光轉化為能量。"},{"en":"Photosynthesis is the process by which plants and algae use sunlight to make food or stored energy.","zh":"光合作用是植物和藻類利用陽光製造食物或儲存能量的過程。"},{"en":"Leaves are green partly because they contain materials needed for photosynthesis.","zh":"葉子呈綠色，部分原因是它們含有光合作用所需的物質。"},{"en":"If a plant cannot get enough sunlight, photosynthesis slows down.","zh":"如果植物得不到足夠陽光，光合作用會減慢。"},{"en":"The word is central to understanding how many living things get energy.","zh":"這個詞對理解許多生物如何取得能量十分重要。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":13},{"front":"be rich in lipids","meaning":"富含脂質","examples":[{"en":"Algae are rich in lipids and combustible elements.","zh":"藻類富含脂質和可燃成分。"},{"en":"To be rich in lipids means to contain a large amount of fats or oil-like substances.","zh":"be rich in lipids指含有大量脂肪或油狀物質。"},{"en":"Some seeds are rich in lipids, so they can be pressed for oil.","zh":"有些種子富含脂質，所以可以榨油。"},{"en":"If algae are rich in lipids, they may be useful for making biodiesel.","zh":"如果藻類富含脂質，它們可能有助製造生物柴油。"},{"en":"The phrase explains why algae can be valuable as fuel material.","zh":"這個短語解釋為何藻類可成為有價值的燃料材料。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":13},{"front":"lipids","meaning":"脂質","examples":[{"en":"The lipids in algae can be extracted for biodiesel.","zh":"藻類中的脂質可以被提取用於生物柴油。"},{"en":"Lipids are fats or oil-like substances found in living things.","zh":"脂質是在生物體內找到的脂肪或油狀物質。"},{"en":"Cooking oil contains lipids that provide energy.","zh":"食油含有提供能量的脂質。"},{"en":"If algae contain many lipids, scientists can try to turn them into fuel.","zh":"如果藻類含有大量脂質，科學家可以嘗試把它們轉化為燃料。"},{"en":"The word is common in biology and nutrition.","zh":"這個詞常見於生物學和營養學。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":13},{"front":"combustible elements","meaning":"可燃成分","examples":[{"en":"Algae contain lipids and other combustible elements.","zh":"藻類含有脂質和其他可燃成分。"},{"en":"Combustible elements are parts or substances that can burn and release energy.","zh":"combustible elements是能燃燒並釋放能量的部分或物質。"},{"en":"Dry wood contains combustible elements, which is why it can be used as fuel.","zh":"乾木含有可燃成分，所以可用作燃料。"},{"en":"If a material has many combustible elements, it must be stored safely.","zh":"如果一種材料有很多可燃成分，必須安全儲存。"},{"en":"The phrase helps explain why something can be used to produce energy.","zh":"這個短語幫助解釋為何某物可用來產生能源。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":13},{"front":"allow something to be extracted","meaning":"讓……被提取","examples":[{"en":"Aquaflow is developing technology that allows useful elements to be extracted.","zh":"Aquaflow正在開發能讓有用成分被提取的技術。"},{"en":"To allow something to be extracted means to make it possible to remove or collect that thing from a material.","zh":"allow something to be extracted指使某物能從材料中被移除或收集。"},{"en":"A good filter allows clean water to be extracted from muddy water.","zh":"好的過濾器能讓清水從泥水中被提取出來。"},{"en":"If new equipment allows oil to be extracted more safely, workers face fewer risks.","zh":"如果新設備讓油更安全地被提取，工人面對的風險會較少。"},{"en":"The phrase focuses on making removal possible.","zh":"這個短語重點在於令移除成為可能。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":13},{"front":"in a cost-effective way","meaning":"以具成本效益的方式","examples":[{"en":"The company wants to extract algal elements in a cost-effective way.","zh":"公司希望以具成本效益的方式提取藻類成分。"},{"en":"In a cost-effective way means achieving a result without wasting money or resources.","zh":"in a cost-effective way指在不浪費金錢或資源的情況下達成結果。"},{"en":"Schools can teach vocabulary in a cost-effective way by using free online tools.","zh":"學校可以透過免費網上工具，以具成本效益的方式教授詞彙。"},{"en":"If a hospital buys equipment in a cost-effective way, it can treat more patients with the same budget.","zh":"如果醫院以具成本效益的方式購買設備，它可用同一預算治療更多病人。"},{"en":"The phrase does not mean cheapest; it means good value for the cost.","zh":"這個短語不是指最便宜，而是指成本帶來良好價值。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":13},{"front":"proposed process","meaning":"擬議工序","examples":[{"en":"The proposed process is the subject of a provisional patent.","zh":"該擬議工序受臨時專利涵蓋。"},{"en":"A proposed process is a method that someone has suggested or plans to use.","zh":"proposed process是某人提出或計劃使用的方法。"},{"en":"The proposed process for school lunch ordering may reduce waiting time.","zh":"學校午餐訂購的擬議工序可能減少等候時間。"},{"en":"If the proposed process is tested successfully, it may become official.","zh":"如果擬議工序成功通過測試，它可能成為正式做法。"},{"en":"The phrase shows that the method is being planned or considered.","zh":"這個短語顯示該方法正在被計劃或考慮。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":13},{"front":"be the subject of","meaning":"是……的主題；受……涵蓋","examples":[{"en":"The proposed process is the subject of a provisional patent.","zh":"該擬議工序是臨時專利的主題。"},{"en":"To be the subject of something means to be the main thing discussed, protected, studied, or affected by it.","zh":"be the subject of某事，意思是成為其主要討論、保護、研究或影響的對象。"},{"en":"The new policy is the subject of a public debate.","zh":"新政策是公開辯論的主題。"},{"en":"If an invention is the subject of a patent, its ownership may be protected.","zh":"如果一項發明受專利涵蓋，其擁有權可能得到保護。"},{"en":"The phrase links something to a document, discussion, investigation, or legal protection.","zh":"這個短語把某物與文件、討論、調查或法律保護連繫起來。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":13},{"front":"provisional patent","meaning":"臨時專利","examples":[{"en":"Aquaflow’s proposed process is protected by a provisional patent.","zh":"Aquaflow的擬議工序受臨時專利保護。"},{"en":"A provisional patent is an early form of patent protection for an invention before a full patent is completed.","zh":"臨時專利是在完整專利完成前，為發明提供的早期專利保護形式。"},{"en":"An inventor may file a provisional patent while still improving the design.","zh":"發明者可能在仍改善設計時申請臨時專利。"},{"en":"If a provisional patent is accepted, the inventor may have more time to prepare a full application.","zh":"如果臨時專利獲接納，發明者可能有更多時間準備完整申請。"},{"en":"The phrase is common in technology and invention contexts.","zh":"這個短語常見於科技和發明語境。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":14},{"front":"take nutrients out of","meaning":"從……吸收養分","examples":[{"en":"Algae are good at taking nutrients out of sewage.","zh":"藻類很擅長從污水中吸收養分。"},{"en":"To take nutrients out of something means to remove useful chemical substances from it.","zh":"take nutrients out of某物，意思是從中移除有用的化學養分。"},{"en":"Plant roots take nutrients out of soil as they grow.","zh":"植物根部在生長時從泥土中吸收養分。"},{"en":"If algae take nutrients out of wastewater, the water may become cleaner.","zh":"如果藻類從廢水中吸收養分，水可能變得更潔淨。"},{"en":"The phrase explains both feeding and cleaning in a simple way.","zh":"這個短語以簡單方式解釋吸收和清潔兩件事。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":14},{"front":"sewage","meaning":"污水","examples":[{"en":"Algae can remove nutrients from sewage.","zh":"藻類可以從污水中移除養分。"},{"en":"Sewage is dirty water and waste carried away from homes, toilets, farms, or factories.","zh":"污水是從住宅、廁所、農場或工廠排走的污水和廢物。"},{"en":"Cities need sewage systems to protect public health.","zh":"城市需要污水系統來保護公共健康。"},{"en":"If sewage enters a river untreated, it can spread disease and pollution.","zh":"如果污水未經處理進入河流，可能傳播疾病和污染。"},{"en":"The word is common in discussions of sanitation and wastewater.","zh":"這個詞常見於衛生和廢水討論。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":14},{"front":"taint the water","meaning":"污染水質；令水變壞","examples":[{"en":"Too many algae can taint the water.","zh":"過多藻類可以污染水質。"},{"en":"To taint the water means to spoil, pollute, or make the water unpleasant or unsafe.","zh":"taint the water指破壞、污染或令水變得難聞或不安全。"},{"en":"Chemicals from a factory can taint the water in a nearby stream.","zh":"工廠化學物可以污染附近溪流的水質。"},{"en":"If waste taints the water, people may no longer be able to drink it safely.","zh":"如果廢物污染水質，人們可能不再能安全飲用。"},{"en":"The verb taint suggests damage to quality or purity.","zh":"taint這個動詞暗示品質或純淨度受損。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":14},{"front":"make it smell","meaning":"令它發臭","examples":[{"en":"Excess algae can make the water smell.","zh":"過量藻類會令水發臭。"},{"en":"To make it smell means to cause something to have an unpleasant odour.","zh":"make it smell指令某物產生難聞氣味。"},{"en":"Leaving rubbish in the kitchen can make it smell by morning.","zh":"把垃圾留在廚房裏，到了早上可能令廚房發臭。"},{"en":"If wastewater is not treated, bacteria may make it smell bad.","zh":"如果廢水沒有處理，細菌可能令它發臭。"},{"en":"The phrase is simple and direct, often used for practical problems.","zh":"這個短語簡單直接，常用於實際問題。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":14},{"front":"find a way of","meaning":"找到……的方法","examples":[{"en":"Councils must find a way of cleaning up excess algae.","zh":"地方議會必須找到清理過量藻類的方法。"},{"en":"To find a way of doing something means to discover or create a method to do it.","zh":"find a way of doing something指發現或創造做某事的方法。"},{"en":"A busy student must find a way of revising without losing sleep.","zh":"忙碌的學生必須找到不犧牲睡眠也能溫習的方法。"},{"en":"If a city finds a way of reducing traffic, daily life becomes easier.","zh":"如果城市找到減少交通擠塞的方法，日常生活會更容易。"},{"en":"The phrase often appears when there is a problem needing a solution.","zh":"這個短語常出現在有問題需要解決時。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":14},{"front":"excess algae","meaning":"過量藻類","examples":[{"en":"Councils need to clean up excess algae in sewerage outflows.","zh":"地方議會需要清理污水排放口中的過量藻類。"},{"en":"Excess algae means more algae than is wanted, useful, or safe.","zh":"excess algae指超過所需、有用或安全水平的藻類。"},{"en":"Excess algae can turn a pond green and block sunlight from other plants.","zh":"過量藻類可以令池塘變綠，並阻擋其他植物獲得陽光。"},{"en":"If excess algae die and rot, the water may smell bad.","zh":"如果過量藻類死亡並腐爛，水可能發臭。"},{"en":"The phrase shows that algae can be useful in the right amount but harmful when there is too much.","zh":"這個短語顯示藻類在適量時有用，但過多時有害。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":14},{"front":"sewerage outflows","meaning":"污水排放口","examples":[{"en":"Excess algae can build up in sewerage outflows.","zh":"過量藻類可以在污水排放口積聚。"},{"en":"Sewerage outflows are places where sewage or treated wastewater flows out of a system.","zh":"sewerage outflows是污水或經處理廢水從系統流出的地方。"},{"en":"Engineers check sewerage outflows to make sure dirty water is not harming rivers.","zh":"工程師檢查污水排放口，確保污水沒有傷害河流。"},{"en":"If sewerage outflows are blocked, wastewater may back up into the system.","zh":"如果污水排放口被堵塞，廢水可能倒流回系統。"},{"en":"The phrase describes exit points in wastewater management.","zh":"這個短語描述廢水管理中的出口位置。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":14},{"front":"dispose of","meaning":"處置；棄置","examples":[{"en":"Councils must either dispose of the algae or find alternative uses for it.","zh":"地方議會必須處置藻類，或為它尋找其他用途。"},{"en":"To dispose of something means to get rid of it safely or properly.","zh":"dispose of某物，意思是安全或妥善地處理掉它。"},{"en":"Hospitals must dispose of used needles very carefully.","zh":"醫院必須非常小心地處置用過的針筒。"},{"en":"If people dispose of batteries in normal rubbish, chemicals may leak into the environment.","zh":"如果人們把電池當普通垃圾棄置，化學物可能漏入環境。"},{"en":"The phrase often suggests responsible waste handling.","zh":"這個短語常暗示負責任的廢物處理。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":14},{"front":"alternative uses","meaning":"其他用途","examples":[{"en":"Authorities may find alternative uses for excess algae.","zh":"當局可能為過量藻類尋找其他用途。"},{"en":"Alternative uses are other practical ways to use something instead of wasting it.","zh":"alternative uses是某物除了被浪費之外的其他實際用途。"},{"en":"Old jars can have alternative uses as plant pots or storage containers.","zh":"舊玻璃瓶可以有其他用途，例如作花盆或儲物容器。"},{"en":"If a city finds alternative uses for waste, landfill pressure may decrease.","zh":"如果城市為廢物找到其他用途，堆填壓力可能減少。"},{"en":"The phrase encourages people to see value in materials that seem unwanted.","zh":"這個短語鼓勵人們看見看似不要的材料中的價值。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":14},{"front":"that’s where…comes in","meaning":"這就是……派上用場的地方","examples":[{"en":"That’s where Aquaflow comes in.","zh":"這就是Aquaflow派上用場的地方。"},{"en":"That’s where something comes in means this is the point where it becomes useful or important.","zh":"that’s where something comes in指這正是某物變得有用或重要的地方。"},{"en":"Students often struggle with pronunciation; that’s where regular listening practice comes in.","zh":"學生常在發音上遇到困難；這就是定期聆聽練習派上用場的地方。"},{"en":"A community may need clean transport, and that’s where electric buses come in.","zh":"社區可能需要潔淨交通，這就是電動巴士派上用場的地方。"},{"en":"The phrase introduces a solution after explaining a problem.","zh":"這個短語在解釋問題後引出解決方案。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":14},{"front":"unlike","meaning":"不像","examples":[{"en":"Unlike some biofuels, algae-based biodiesel does not require special crops.","zh":"不像某些生物燃料，藻類生物柴油不需要特殊農作物。"},{"en":"Unlike means different from someone or something else.","zh":"unlike指與某人或某物不同。"},{"en":"Unlike his brother, Tom enjoys studying early in the morning.","zh":"不像他的哥哥，Tom喜歡清晨學習。"},{"en":"Unlike paper books, e-books can be carried in large numbers on one device.","zh":"不像紙本書，電子書可以在一部裝置中大量攜帶。"},{"en":"The word clearly sets up a contrast.","zh":"這個字清楚建立對比。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":15},{"front":"specially grown crops","meaning":"專門種植的農作物","examples":[{"en":"Some biofuels require specially grown crops.","zh":"某些生物燃料需要專門種植的農作物。"},{"en":"Specially grown crops are crops planted for a particular purpose rather than ordinary food use.","zh":"specially grown crops是為特定目的而種植、而非普通食用用途的農作物。"},{"en":"A farm may plant specially grown crops for research or fuel production.","zh":"農場可能為研究或燃料生產種植專門農作物。"},{"en":"If fuel depends on specially grown crops, it may compete with food farming.","zh":"如果燃料依賴專門種植的農作物，它可能與食物農業競爭。"},{"en":"The phrase suggests planned cultivation for a specific aim.","zh":"這個短語暗示為特定目標而有計劃地種植。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":15},{"front":"compete with","meaning":"與……競爭","examples":[{"en":"Some biofuel crops compete with food production for land.","zh":"某些生物燃料作物與食物生產爭奪土地。"},{"en":"To compete with something means to try to use the same limited resource or win against it.","zh":"compete with某物，意思是嘗試使用同一有限資源，或與其競爭勝出。"},{"en":"Small shops compete with supermarkets by offering personal service.","zh":"小店透過提供個人化服務與超級市場競爭。"},{"en":"If housing competes with farmland for space, planning becomes difficult.","zh":"如果房屋與農地爭奪空間，規劃會變得困難。"},{"en":"The phrase often shows pressure between two needs or groups.","zh":"這個短語常顯示兩種需要或群體之間的壓力。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":15},{"front":"food production","meaning":"食物生產","examples":[{"en":"Some biofuels compete with food production for land.","zh":"某些生物燃料與食物生產爭奪土地。"},{"en":"Food production is the process of growing, raising, processing, and supplying food.","zh":"food production是種植、飼養、加工和供應食物的過程。"},{"en":"Good weather is important for food production on farms.","zh":"良好天氣對農場食物生產很重要。"},{"en":"If land is used for fuel crops, food production may be reduced.","zh":"如果土地用於燃料作物，食物生產可能減少。"},{"en":"The phrase covers much more than cooking; it includes the whole food supply process.","zh":"這個短語涵蓋的不只是烹飪，而是整個食物供應過程。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":15},{"front":"scarce resources","meaning":"稀缺資源","examples":[{"en":"Some biofuel crops consume scarce resources.","zh":"某些生物燃料作物消耗稀缺資源。"},{"en":"Scarce resources are resources that are limited and not enough for every need.","zh":"scarce resources是有限、無法滿足所有需要的資源。"},{"en":"In a drought, clean water becomes a scarce resource.","zh":"在乾旱中，潔淨水會成為稀缺資源。"},{"en":"If companies waste scarce resources, poorer communities may suffer more.","zh":"如果公司浪費稀缺資源，較貧困社區可能承受更多痛苦。"},{"en":"The phrase reminds readers that not all useful things are unlimited.","zh":"這個短語提醒讀者，不是所有有用東西都是無限的。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":15},{"front":"already widely available","meaning":"已廣泛存在的","examples":[{"en":"Algae-based biodiesel uses a source that is already widely available.","zh":"藻類生物柴油使用一種已廣泛存在的來源。"},{"en":"Already widely available means something can already be found or obtained in many places.","zh":"already widely available指某物已可在許多地方找到或取得。"},{"en":"Smartphones are already widely available, so many services can move online.","zh":"智能手機已廣泛存在，所以許多服務可以轉到網上。"},{"en":"If a raw material is already widely available, production may start more easily.","zh":"如果原材料已廣泛存在，生產可能更容易開始。"},{"en":"The phrase suggests that no rare new source is needed.","zh":"這個短語暗示不需要罕有的新來源。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":15},{"front":"net energy gain","meaning":"淨能源收益","examples":[{"en":"The process produces a sustainable net energy gain.","zh":"這個過程產生可持續的淨能源收益。"},{"en":"Net energy gain means the useful energy left after subtracting the energy used to produce it.","zh":"net energy gain指扣除生產所用能源後剩下的有用能源。"},{"en":"A fuel process has little value if there is no net energy gain.","zh":"如果燃料過程沒有淨能源收益，它的價值很低。"},{"en":"If solar panels produce far more energy than is used to make and run them, they offer a net energy gain.","zh":"如果太陽能板產生的能源遠多於製造和運行它們所需的能源，它們就提供淨能源收益。"},{"en":"The word net means after costs or inputs are considered.","zh":"net一字指已考慮成本或投入之後的結果。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":15},{"front":"capture free solar energy","meaning":"捕捉免費太陽能","examples":[{"en":"Algae-based biodiesel captures free solar energy.","zh":"藻類生物柴油捕捉免費太陽能。"},{"en":"To capture free solar energy means to use sunlight, which costs nothing, and turn it into usable energy.","zh":"capture free solar energy指利用不需成本的陽光，並把它轉化為可用能源。"},{"en":"Plants capture free solar energy when they grow through photosynthesis.","zh":"植物透過光合作用生長時，會捕捉免費太陽能。"},{"en":"If technology captures free solar energy efficiently, fuel costs may fall.","zh":"如果技術有效捕捉免費太陽能，燃料成本可能下降。"},{"en":"The phrase highlights sunlight as a natural energy source.","zh":"這個短語強調陽光是一種天然能源來源。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":15},{"front":"contains seven paragraphs","meaning":"包含七段","examples":[{"en":"The reading passage contains seven paragraphs.","zh":"閱讀文章包含七段。"},{"en":"Contains seven paragraphs means has seven separate sections of text.","zh":"contains seven paragraphs指有七個分開的文字段落。"},{"en":"The essay contains seven paragraphs, so each idea has its own space.","zh":"這篇文章包含七段，所以每個想法都有自己的空間。"},{"en":"If a passage contains seven paragraphs, students can number them before answering questions.","zh":"如果文章包含七段，學生可以先為段落編號，再回答問題。"},{"en":"The phrase helps describe the structure of a text.","zh":"這個短語幫助描述文本結構。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":15},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"The task asks which paragraph contains specific information.","zh":"題目問哪一段包含特定資料。"},{"en":"Which paragraph contains asks students to identify the paragraph where certain information appears.","zh":"which paragraph contains要求學生找出某項資料出現在哪一段。"},{"en":"A reading question may ask which paragraph contains a reason for the writer’s opinion.","zh":"閱讀題可能問哪一段包含作者意見的原因。"},{"en":"If students know which paragraph contains the answer, they can check details more quickly.","zh":"如果學生知道哪一段包含答案，他們可以更快核對細節。"},{"en":"The phrase is common in paragraph-matching tasks.","zh":"這個短語常見於段落配對題。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":15},{"front":"following information","meaning":"以下資料","examples":[{"en":"Candidates match paragraphs with the following information.","zh":"考生把段落與以下資料配對。"},{"en":"Following information means the information listed after the instruction.","zh":"following information指指示之後列出的資料。"},{"en":"Read the following information before you sign the form.","zh":"簽表格前，請閱讀以下資料。"},{"en":"If students ignore the following information, they may answer the wrong question.","zh":"如果學生忽略以下資料，他們可能答錯題目。"},{"en":"The phrase directs attention to details that come next.","zh":"這個短語把注意力引向接下來的細節。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":15},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Candidates write the correct letter on the answer sheet.","zh":"考生在答題紙上寫上正確字母。"},{"en":"To write the correct letter means to choose the right option label and record it.","zh":"write the correct letter指選擇正確選項代號並寫下。"},{"en":"In a matching task, students may write the correct letter beside each question number.","zh":"在配對題中，學生可能在每個題號旁寫上正確字母。"},{"en":"If candidates write the wrong letter, the answer may be marked incorrect even if they understood the passage.","zh":"如果考生寫錯字母，即使理解文章，答案也可能被判錯。"},{"en":"The phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":16},{"front":"may use any letter more than once","meaning":"可以多次使用任何字母","examples":[{"en":"Candidates may use any letter more than once.","zh":"考生可以多次使用任何字母。"},{"en":"May use any letter more than once means the same option can be chosen for more than one answer.","zh":"may use any letter more than once指同一選項可以用於多於一個答案。"},{"en":"In paragraph matching, students may use any letter more than once if two answers are in the same paragraph.","zh":"在段落配對中，如果兩個答案在同一段，學生可以多次使用任何字母。"},{"en":"If this instruction is ignored, students may wrongly avoid repeating an answer.","zh":"如果忽略這個指示，學生可能錯誤地避免重複答案。"},{"en":"The phrase removes the rule that each letter can be used only once.","zh":"這個短語取消了每個字母只能使用一次的規則。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":16},{"front":"vehicles using biodiesel","meaning":"使用生物柴油的車輛","examples":[{"en":"Vehicles using biodiesel do not need to be modified.","zh":"使用生物柴油的車輛不需要被改裝。"},{"en":"Vehicles using biodiesel are cars, buses, trucks, or boats that run on biodiesel fuel.","zh":"vehicles using biodiesel是以生物柴油作燃料的汽車、巴士、貨車或船隻。"},{"en":"A delivery company may test vehicles using biodiesel to reduce emissions.","zh":"速遞公司可能測試使用生物柴油的車輛，以減少排放。"},{"en":"If vehicles using biodiesel perform well, more drivers may accept the fuel.","zh":"如果使用生物柴油的車輛表現良好，更多司機可能接受這種燃料。"},{"en":"The phrase focuses on vehicles powered by this alternative fuel.","zh":"這個短語重點在於由這種替代燃料驅動的車輛。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":16},{"front":"need to be modified","meaning":"需要被改裝","examples":[{"en":"The question asks whether vehicles need to be modified.","zh":"題目問車輛是否需要被改裝。"},{"en":"Need to be modified means need to be changed or adjusted before use.","zh":"need to be modified指在使用前需要被改變或調整。"},{"en":"Some old buildings need to be modified before wheelchair users can enter safely.","zh":"有些舊建築需要被改裝，輪椅使用者才能安全進入。"},{"en":"If engines need to be modified for a new fuel, costs may rise.","zh":"如果引擎需要為新燃料而改裝，成本可能上升。"},{"en":"The phrase is often used when existing things must be adapted.","zh":"這個短語常用於現有事物必須被改造時。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":16},{"front":"be regarded as","meaning":"被視為","examples":[{"en":"Some algae are regarded as edible plants.","zh":"一些藻類被視為可食用植物。"},{"en":"To be regarded as something means to be considered or seen in that way.","zh":"be regarded as某物，意思是被認為或被看作那樣。"},{"en":"A reliable teacher may be regarded as a role model by students.","zh":"可靠的老師可能被學生視為榜樣。"},{"en":"If a food is regarded as healthy, people may buy it more often.","zh":"如果一種食物被視為健康，人們可能更常購買。"},{"en":"The phrase reports how people judge or classify something.","zh":"這個短語報告人們如何判斷或分類某物。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":16},{"front":"edible plants","meaning":"可食用植物","examples":[{"en":"Some algae are regarded as edible plants.","zh":"一些藻類被視為可食用植物。"},{"en":"Edible plants are plants that people can safely eat.","zh":"edible plants是人們可以安全食用的植物。"},{"en":"Lettuce, spinach, and many herbs are edible plants.","zh":"生菜、菠菜和許多香草都是可食用植物。"},{"en":"If children learn to identify edible plants, they must also learn which plants are dangerous.","zh":"如果孩子學習辨認可食用植物，也必須學習哪些植物危險。"},{"en":"The phrase focuses on whether a plant can be eaten.","zh":"這個短語重點在於植物是否可以食用。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":16},{"front":"form part of","meaning":"成為……的一部分","examples":[{"en":"Algae could form part of a sustainable, recycled resource.","zh":"藻類可以成為可持續循環再用資源的一部分。"},{"en":"To form part of something means to be one element within a larger whole.","zh":"form part of某事，意思是成為一個較大整體中的一個元素。"},{"en":"Daily reading can form part of a student’s English-learning routine.","zh":"每天閱讀可以成為學生英語學習習慣的一部分。"},{"en":"If local shops form part of a community plan, residents may support them more.","zh":"如果本地商店成為社區計劃的一部分，居民可能更支持它們。"},{"en":"The phrase shows that something contributes to a bigger system.","zh":"這個短語顯示某物對更大系統作出貢獻。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":16},{"front":"sustainable, recycled resource","meaning":"可持續的循環再用資源","examples":[{"en":"Algae may become part of a sustainable, recycled resource.","zh":"藻類可能成為可持續循環再用資源的一部分。"},{"en":"A sustainable, recycled resource is a resource that can be reused or renewed without heavy waste.","zh":"sustainable, recycled resource是可以重用或再生、且不造成大量浪費的資源。"},{"en":"Compost made from food waste can be a sustainable, recycled resource for gardens.","zh":"由廚餘製成的堆肥可以成為花園的可持續循環再用資源。"},{"en":"If cities treat waste as a sustainable, recycled resource, less material goes to landfill.","zh":"如果城市把廢物視為可持續循環再用資源，進入堆填區的材料會減少。"},{"en":"The phrase connects environmental protection with reuse.","zh":"這個短語把環境保護與再使用連繫起來。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":16},{"front":"advantages over","meaning":"相比……的優點","examples":[{"en":"Algae biodiesel has many advantages over other biofuels.","zh":"藻類生物柴油相比其他生物燃料有許多優點。"},{"en":"Advantages over something are benefits that make one option better than another in some ways.","zh":"advantages over某物是令一個選項在某些方面比另一個更好的好處。"},{"en":"Online classes have advantages over travel-based lessons when students live far away.","zh":"當學生住得很遠時，網課相比需要出行的課堂有優點。"},{"en":"If a new material has advantages over plastic, companies may adopt it.","zh":"如果一種新材料相比塑膠有優點，公司可能採用它。"},{"en":"The phrase sets up a comparison of strengths.","zh":"這個短語建立優勢比較。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":16},{"front":"other biofuels","meaning":"其他生物燃料","examples":[{"en":"Algae-based biodiesel may be more sustainable than other biofuels.","zh":"藻類生物柴油可能比其他生物燃料更可持續。"},{"en":"Other biofuels are alternative fuels made from different biological sources.","zh":"other biofuels是由不同生物來源製成的其他替代燃料。"},{"en":"Ethanol from corn is one example of other biofuels.","zh":"由粟米製成的乙醇就是其他生物燃料的一個例子。"},{"en":"If other biofuels require farmland, algae biodiesel may seem more attractive.","zh":"如果其他生物燃料需要農地，藻類生物柴油可能看起來更吸引。"},{"en":"The phrase compares algae fuel with different biological fuel options.","zh":"這個短語把藻類燃料與不同生物燃料選項作比較。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":16},{"front":"excessive algae growth","meaning":"藻類過度生長","examples":[{"en":"Excessive algae growth can threaten the environment.","zh":"藻類過度生長可以威脅環境。"},{"en":"Excessive algae growth means algae increase too much and create problems in water systems.","zh":"excessive algae growth指藻類增加過多，並在水系統中造成問題。"},{"en":"A lake may turn green because of excessive algae growth.","zh":"湖泊可能因藻類過度生長而變綠。"},{"en":"If excessive algae growth blocks sunlight, fish and plants may suffer.","zh":"如果藻類過度生長阻擋陽光，魚類和植物可能受害。"},{"en":"The phrase shows that even natural organisms can become harmful when they grow too much.","zh":"這個短語顯示即使天然生物過度生長，也可能變得有害。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":16},{"front":"threaten the environment","meaning":"威脅環境","examples":[{"en":"Too many algae can threaten the environment by tainting water.","zh":"過多藻類可以透過污染水質威脅環境。"},{"en":"To threaten the environment means to put nature, air, water, land, or wildlife at risk.","zh":"threaten the environment指令自然、空氣、水、土地或野生動物面臨風險。"},{"en":"Plastic waste can threaten the environment when it enters the sea.","zh":"塑膠廢物進入海洋時可以威脅環境。"},{"en":"If factories release untreated chemicals, they threaten the environment around them.","zh":"如果工廠排放未經處理的化學物，它們會威脅周圍環境。"},{"en":"The phrase is used when human or natural activity may cause ecological harm.","zh":"這個短語用於人類或自然活動可能造成生態傷害時。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":17},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Candidates complete the summary below using words from the passage.","zh":"考生使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in the missing words in the short text that follows.","zh":"complete the summary below指填寫接下來短文中的空缺字詞。"},{"en":"In reading exams, students complete the summary below by choosing exact words from the article.","zh":"在閱讀考試中，學生透過從文章選擇原字完成以下摘要。"},{"en":"If students read the whole passage first, they may complete the summary below more accurately.","zh":"如果學生先讀完整篇文章，他們可能更準確地完成以下摘要。"},{"en":"The phrase is a common instruction in exam tasks.","zh":"這個短語是考試題目中的常見指示。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":17},{"front":"no more than two words","meaning":"不多於兩個字","examples":[{"en":"Candidates choose no more than two words from the passage.","zh":"考生從文章中選擇不多於兩個字。"},{"en":"No more than two words means the answer can have one or two words, but not three.","zh":"no more than two words指答案可以有一個或兩個英文單字，但不能有三個。"},{"en":"If the instruction says no more than two words, “clean fuel” is allowed but “a clean fuel” is not.","zh":"如果指示說不多於兩個字，clean fuel可以，但a clean fuel不可以。"},{"en":"Students lose marks when they write too many words despite finding the right information.","zh":"即使找到正確資料，學生若寫太多字也會失分。"},{"en":"The phrase sets a strict word limit.","zh":"這個短語設定嚴格字數限制。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":17},{"front":"become a substitute for","meaning":"成為……的替代品","examples":[{"en":"Algae-based biodiesel could become a substitute for mineral diesel.","zh":"藻類生物柴油可以成為礦物柴油的替代品。"},{"en":"To become a substitute for something means to start replacing it or serving the same purpose.","zh":"become a substitute for某物，意思是開始取代它或達到相同用途。"},{"en":"Oat milk can become a substitute for cow’s milk for people who avoid dairy.","zh":"對避免乳製品的人來說，燕麥奶可以成為牛奶的替代品。"},{"en":"If a cheaper material becomes a substitute for plastic, waste may fall.","zh":"如果較便宜材料成為塑膠的替代品，廢物可能減少。"},{"en":"The phrase shows replacement, either partly or fully.","zh":"這個短語顯示部分或完全取代。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":17},{"front":"in New Zealand","meaning":"在新西蘭","examples":[{"en":"The fuel could become a substitute in New Zealand.","zh":"這種燃料可以在新西蘭成為替代品。"},{"en":"In New Zealand means within or related to the country of New Zealand.","zh":"in New Zealand指在新西蘭這個國家內或與其相關。"},{"en":"Rugby is a popular sport in New Zealand.","zh":"欖球在新西蘭是一項受歡迎的運動。"},{"en":"If a product succeeds in New Zealand, it may later be tested in other countries.","zh":"如果產品在新西蘭成功，它之後可能在其他國家測試。"},{"en":"The phrase locates an action, event, or market in that country.","zh":"這個短語指出行動、事件或市場位於該國。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":17},{"front":"be used to power","meaning":"用作驅動","examples":[{"en":"Algae-based biodiesel could be used to power vehicles.","zh":"藻類生物柴油可以用作驅動車輛。"},{"en":"To be used to power something means to provide energy for it to work or move.","zh":"be used to power某物，意思是為某物提供能量，使其運作或移動。"},{"en":"Batteries are used to power remote controls and toys.","zh":"電池用作驅動遙控器和玩具。"},{"en":"If solar energy is used to power street lights, electricity bills may fall.","zh":"如果太陽能用作驅動街燈，電費可能下降。"},{"en":"The phrase links an energy source with the machine it operates.","zh":"這個短語把能源來源與它操作的機器連繫起來。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":17},{"front":"vehicles such as","meaning":"例如……的車輛","examples":[{"en":"The fuel could power vehicles such as cars and boats.","zh":"這種燃料可以驅動例如汽車和船隻的車輛。"},{"en":"Vehicles such as introduces examples of transport machines.","zh":"vehicles such as用來引出交通工具的例子。"},{"en":"Cities need space for vehicles such as buses, taxis, and delivery vans.","zh":"城市需要為例如巴士、的士和送貨車的車輛預留空間。"},{"en":"If fuel works in vehicles such as trucks and boats, it has wider practical value.","zh":"如果燃料能用於例如貨車和船隻的車輛，它有更廣泛的實際價值。"},{"en":"The phrase gives examples without listing every possible vehicle.","zh":"這個短語提供例子，而不是列出所有可能車輛。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":17},{"front":"be required worldwide","meaning":"全球需要","examples":[{"en":"Billions of litres of biodiesel are required worldwide each year.","zh":"全球每年需要數十億公升生物柴油。"},{"en":"To be required worldwide means to be needed in many countries around the world.","zh":"be required worldwide指在世界許多國家都需要。"},{"en":"Clean water technology is required worldwide as populations grow.","zh":"隨着人口增長，全球需要潔淨水技術。"},{"en":"If medical supplies are required worldwide, factories must produce enough for many regions.","zh":"如果全球需要醫療用品，工廠必須為許多地區生產足夠數量。"},{"en":"The phrase shows global need rather than local demand.","zh":"這個短語顯示全球需要，而不是本地需求。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":17},{"front":"be obtained from","meaning":"從……取得","examples":[{"en":"Algae can be obtained from nutrient-rich waste streams.","zh":"藻類可以從富含養分的廢物流中取得。"},{"en":"To be obtained from a source means to be got, collected, or taken from it.","zh":"be obtained from某來源，意思是從中得到、收集或取出。"},{"en":"Drinking water can be obtained from rivers, reservoirs, or wells.","zh":"飲用水可以從河流、水塘或水井中取得。"},{"en":"If useful materials are obtained from waste, fewer resources may be wasted.","zh":"如果有用材料從廢物中取得，較少資源會被浪費。"},{"en":"The phrase explains where something comes from.","zh":"這個短語解釋某物來自哪裏。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":17},{"front":"containing nutrients","meaning":"含有養分的","examples":[{"en":"Waste streams containing nutrients can produce large amounts of algae.","zh":"含有養分的廢物流可以產生大量藻類。"},{"en":"Containing nutrients means having substances that living things need to grow.","zh":"containing nutrients指含有生物生長所需的物質。"},{"en":"Soil containing nutrients helps vegetables grow more strongly.","zh":"含有養分的泥土幫助蔬菜生長得更強壯。"},{"en":"If water contains nutrients, algae may grow quickly in it.","zh":"如果水含有養分，藻類可能在其中快速生長。"},{"en":"The phrase explains why a place can support life or growth.","zh":"這個短語解釋為何某個地方能支持生命或生長。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":17},{"front":"technological breakthrough","meaning":"技術突破","examples":[{"en":"The technological breakthrough allowed algae to be extracted for fuel.","zh":"這項技術突破讓藻類可以被提取用於燃料。"},{"en":"A technological breakthrough is an important advance that solves a difficult technical problem.","zh":"technological breakthrough是解決困難技術問題的重要進展。"},{"en":"A new battery design could be a technological breakthrough for electric cars.","zh":"新電池設計可以成為電動車的技術突破。"},{"en":"If a technological breakthrough lowers costs, many more people may use the product.","zh":"如果技術突破降低成本，更多人可能使用該產品。"},{"en":"The phrase suggests a major step forward, not a small improvement.","zh":"這個短語暗示重大進展，而不是小改良。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":17},{"front":"removed from settling ponds","meaning":"從沉澱池中移除","examples":[{"en":"The main contaminant is removed from settling ponds.","zh":"主要污染物從沉澱池中被移除。"},{"en":"Removed from settling ponds means taken out of ponds where solids or waste materials settle.","zh":"removed from settling ponds指從讓固體或廢料沉澱的池中取出。"},{"en":"Sludge may be removed from settling ponds during regular maintenance.","zh":"淤泥可能在定期維護期間從沉澱池中移除。"},{"en":"If algae are removed from settling ponds, the water may become cleaner.","zh":"如果藻類從沉澱池中移除，水可能變得更潔淨。"},{"en":"The phrase describes both the action and the place where it happens.","zh":"這個短語描述動作以及動作發生的地方。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":18},{"front":"adopt the technology","meaning":"採用該技術","examples":[{"en":"Dairy farmers and food processors can adopt the harvesting technology.","zh":"乳牛農場主和食品加工商可以採用該收集技術。"},{"en":"To adopt the technology means to start using a particular technology.","zh":"adopt the technology指開始使用某項特定技術。"},{"en":"Schools may adopt the technology if it helps teachers mark work faster.","zh":"如果科技能幫助老師更快批改作業，學校可能採用該技術。"},{"en":"If small farms adopt the technology, pollution control may improve widely.","zh":"如果小農場採用該技術，污染控制可能廣泛改善。"},{"en":"The phrase focuses on acceptance and practical use.","zh":"這個短語重點在於接受和實際使用。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":18},{"front":"answer the questions below","meaning":"回答以下問題","examples":[{"en":"Candidates answer the questions below using words from the passage.","zh":"考生使用文章中的字詞回答以下問題。"},{"en":"Answer the questions below means respond to the questions that follow the instruction.","zh":"answer the questions below指回答指示後面的問題。"},{"en":"In a worksheet, students answer the questions below after reading the article.","zh":"在工作紙中，學生閱讀文章後回答以下問題。"},{"en":"If students do not read the questions below carefully, they may miss key limits.","zh":"如果學生沒有仔細閱讀以下問題，他們可能錯過關鍵限制。"},{"en":"The phrase is a simple exam or textbook instruction.","zh":"這個短語是簡單的考試或課本指示。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":18},{"front":"no more than three words","meaning":"不多於三個字","examples":[{"en":"Candidates choose no more than three words from the passage.","zh":"考生從文章中選擇不多於三個字。"},{"en":"No more than three words means the answer can contain one, two, or three words, but not four.","zh":"no more than three words指答案可包含一個、兩個或三個英文單字，但不能有四個。"},{"en":"If the instruction says no more than three words, students must count each word carefully.","zh":"如果指示說不多於三個字，學生必須小心計算每個字。"},{"en":"A correct idea may lose marks if it is written in more than three words.","zh":"即使意思正確，若寫成超過三個字，也可能失分。"},{"en":"The phrase sets the maximum length of an answer.","zh":"這個短語設定答案的最大長度。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":18},{"front":"environmental target","meaning":"環保目標","examples":[{"en":"The question asks what environmental target biodiesel can help meet.","zh":"題目問生物柴油可以幫助達到甚麼環保目標。"},{"en":"An environmental target is a goal set to reduce harm to nature or improve environmental quality.","zh":"environmental target是為減少對自然的傷害或改善環境質素而設定的目標。"},{"en":"A city may set an environmental target to cut air pollution by half.","zh":"城市可能設定把空氣污染減半的環保目標。"},{"en":"If companies help meet an environmental target, the government may support their work.","zh":"如果公司幫助達到環保目標，政府可能支持它們的工作。"},{"en":"The phrase connects policy goals with environmental protection.","zh":"這個短語把政策目標與環境保護連繫起來。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":18},{"front":"plan to do","meaning":"計劃去做","examples":[{"en":"The question asks what Aquaflow plans to do during the coming year.","zh":"題目問Aquaflow計劃在來年做甚麼。"},{"en":"To plan to do something means to intend or prepare to do it in the future.","zh":"plan to do something指打算或準備在將來做某事。"},{"en":"She plans to do more speaking practice before the exam.","zh":"她計劃在考試前做更多口語練習。"},{"en":"If a company plans to do a large project, it should prepare money and staff early.","zh":"如果公司計劃做大型項目，它應該及早準備資金和人手。"},{"en":"The phrase points to future intention, not something already completed.","zh":"這個短語指向未來意圖，而不是已完成的事情。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":18},{"front":"during the coming year","meaning":"在來年","examples":[{"en":"Aquaflow planned to increase production during the coming year.","zh":"Aquaflow計劃在來年提高產量。"},{"en":"During the coming year means at some time or throughout the next year.","zh":"during the coming year指在下一年期間的某個時間或整段時間內。"},{"en":"The school will renovate the library during the coming year.","zh":"學校將在來年翻新圖書館。"},{"en":"If sales grow during the coming year, the shop may hire more staff.","zh":"如果銷售在來年增長，商店可能聘請更多員工。"},{"en":"The phrase gives a future time period for an action or change.","zh":"這個短語為行動或改變提供未來時間段。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":18},{"front":"obtain and store energy","meaning":"獲取並儲存能量","examples":[{"en":"Algae obtain and store energy through photosynthesis.","zh":"藻類透過光合作用獲取並儲存能量。"},{"en":"To obtain and store energy means to get energy and keep it for later use.","zh":"obtain and store energy指取得能量並保存起來供日後使用。"},{"en":"Plants obtain and store energy from sunlight in their tissues.","zh":"植物從陽光中獲取並在組織中儲存能量。"},{"en":"If a battery can obtain and store energy efficiently, it becomes more useful.","zh":"如果電池能有效獲取並儲存能量，它會變得更有用。"},{"en":"The phrase explains both receiving energy and keeping it.","zh":"這個短語解釋取得能量和保存能量兩個動作。"}],"source":"156 - Aqua Product - New zealand ‘s Algae Biodiesel.pdf","sourcePage":18}],"ielts/reading/passage-2/Practice 157":[{"front":"natural pesticide","meaning":"天然農藥","examples":[{"en":"The passage explains how farmers in India used a natural pesticide instead of chemical pesticides.","zh":"篇章解釋印度農民如何使用天然農藥而不是化學農藥。"},{"en":"A natural pesticide is made from plants or other natural materials to control insects or disease.","zh":"天然農藥是由植物或其他天然材料製成，用來控制昆蟲或疾病。"},{"en":"A gardener may use garlic spray as a natural pesticide on vegetables.","zh":"園丁可能會在蔬菜上使用蒜水作為天然農藥。"},{"en":"Natural pesticides can reduce chemical exposure while still protecting crops.","zh":"天然農藥可以減少接觸化學品，同時仍然保護農作物。"},{"en":"Farmers may choose a natural pesticide when they want safer soil, water and food.","zh":"當農民想要更安全的泥土、水源和食物時，可能會選擇天然農藥。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":1},{"front":"a dramatic story about","meaning":"關於……的戲劇性故事","examples":[{"en":"A dramatic story about cotton farmers in India shows the dangers of pesticides.","zh":"關於印度棉農的戲劇性故事展示了農藥的危險。"},{"en":"A dramatic story about something is an exciting or serious account that clearly shows a problem.","zh":"關於某事的戲劇性故事，是指一個令人緊張或嚴肅的故事，清楚展示某個問題。"},{"en":"A dramatic story about a family losing its home can make a housing crisis feel real.","zh":"關於一個家庭失去住所的戲劇性故事，可以令房屋危機變得真實。"},{"en":"A dramatic story about illness may persuade people to take safety rules seriously.","zh":"關於疾病的戲劇性故事，可能說服人們認真看待安全規則。"},{"en":"Writers use a dramatic story about one person to help readers understand a larger issue.","zh":"作者會用關於一個人的戲劇性故事，幫助讀者理解更大的議題。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":1},{"front":"cotton farmers","meaning":"棉農","examples":[{"en":"Cotton farmers in India became dependent on chemical pesticides.","zh":"印度棉農變得依賴化學農藥。"},{"en":"Cotton farmers are people who grow cotton as a crop.","zh":"棉農是指種植棉花作物的人。"},{"en":"Cotton farmers may sell their harvest to textile companies.","zh":"棉農可能把收成賣給紡織公司。"},{"en":"If pests attack the fields, cotton farmers can lose much of their income.","zh":"如果害蟲侵襲田地，棉農可能失去大部分收入。"},{"en":"Cotton farmers need good advice because cotton can require careful pest control.","zh":"棉農需要良好建議，因為棉花可能需要仔細控制害蟲。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":1},{"front":"destructive pesticides","meaning":"具破壞性的農藥","examples":[{"en":"The story shows how destructive pesticides can be for people and the environment.","zh":"這個故事展示了農藥對人和環境可以有多具破壞性。"},{"en":"Destructive pesticides are chemicals that kill pests but also damage health, soil, water or wildlife.","zh":"具破壞性的農藥是殺死害蟲但同時損害健康、泥土、水源或野生動物的化學品。"},{"en":"A farm may regret using destructive pesticides if nearby fish die after heavy rain.","zh":"如果大雨後附近的魚死亡，農場可能會後悔使用具破壞性的農藥。"},{"en":"Destructive pesticides can create new problems when they kill useful insects.","zh":"具破壞性的農藥殺死有益昆蟲時，可能製造新的問題。"},{"en":"Safer farming tries to reduce destructive pesticides, not simply spray more chemicals.","zh":"較安全的農業會嘗試減少具破壞性的農藥，而不是單純噴更多化學品。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":1},{"front":"be destructive for","meaning":"對……具破壞性","examples":[{"en":"Chemical pesticides can be destructive for people and the environment.","zh":"化學農藥可能對人和環境具破壞性。"},{"en":"To be destructive for something means to cause serious harm to it.","zh":"對某事物具破壞性，是指對它造成嚴重傷害。"},{"en":"Too much screen time can be destructive for a child’s sleep and attention.","zh":"太多螢幕時間可能對孩子的睡眠和專注力具破壞性。"},{"en":"Poor waste management can be destructive for rivers and sea life.","zh":"差劣的廢物管理可能對河流和海洋生物具破壞性。"},{"en":"A policy may be destructive for small businesses if it raises costs too suddenly.","zh":"如果政策突然大幅提高成本，可能對小企業具破壞性。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":1},{"front":"the environment","meaning":"環境","examples":[{"en":"Pesticides can damage both people and the environment.","zh":"農藥可以傷害人和環境。"},{"en":"The environment means the natural world around us, including air, water, land, plants and animals.","zh":"環境指我們周圍的自然世界，包括空氣、水、土地、植物和動物。"},{"en":"Recycling helps the environment by reducing waste.","zh":"回收透過減少垃圾來幫助環境。"},{"en":"Pollution harms the environment when dirty water enters rivers.","zh":"當污水流入河流時，污染會傷害環境。"},{"en":"Protecting the environment also protects human health.","zh":"保護環境也就是保護人類健康。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":1},{"front":"be dependent on","meaning":"依賴……","examples":[{"en":"Modern agriculture is often dependent on pesticides.","zh":"現代農業常常依賴農藥。"},{"en":"To be dependent on something means to need it in order to function or succeed.","zh":"依賴某物，是指需要它才能運作或成功。"},{"en":"Many students are dependent on public transport to get to school.","zh":"許多學生依賴公共交通上學。"},{"en":"A shop may become dependent on one large customer and suffer if that customer leaves.","zh":"一間商店可能變得依賴一位大客戶，而如果該客戶離開就會受損。"},{"en":"Being too dependent on one method can make people less flexible.","zh":"過分依賴一種方法，可能令人缺乏彈性。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":1},{"front":"today’s agriculture","meaning":"現代農業","examples":[{"en":"Today’s agriculture is highly dependent on chemical pesticides.","zh":"現代農業高度依賴化學農藥。"},{"en":"Today’s agriculture means the farming methods and systems used in the modern world.","zh":"現代農業指當今世界使用的耕作方法和農業系統。"},{"en":"Today’s agriculture often uses machines, irrigation, fertilisers and market planning.","zh":"現代農業常使用機器、灌溉、肥料和市場規劃。"},{"en":"Today’s agriculture must feed many people while reducing damage to nature.","zh":"現代農業必須養活許多人，同時減少對自然的傷害。"},{"en":"Better science can help today’s agriculture become safer and more sustainable.","zh":"更好的科學可以幫助現代農業變得更安全和更可持續。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":1},{"front":"chemical pesticides","meaning":"化學農藥","examples":[{"en":"Farmers learned that it was possible to stop using chemical pesticides.","zh":"農民知道了停止使用化學農藥是可能的。"},{"en":"Chemical pesticides are manufactured substances used to kill insects, weeds or plant diseases.","zh":"化學農藥是人工製造、用來殺死昆蟲、雜草或植物疾病的物質。"},{"en":"A farmer may spray chemical pesticides when insects are eating the crop.","zh":"當昆蟲正在吃農作物時，農民可能會噴灑化學農藥。"},{"en":"Overusing chemical pesticides can harm workers and useful animals.","zh":"過度使用化學農藥可能傷害工人和有益動物。"},{"en":"Some farms replace chemical pesticides with natural pest-control methods.","zh":"有些農場用天然控蟲方法取代化學農藥。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":1},{"front":"without losing a crop to","meaning":"沒有因……而失去收成","examples":[{"en":"Farmers stopped using pesticides without losing a crop to insects.","zh":"農民停止使用農藥，卻沒有因昆蟲而失去收成。"},{"en":"Without losing a crop to something means the harvest is not destroyed by that danger.","zh":"沒有因某事而失去收成，是指收成沒有被那種危險摧毀。"},{"en":"Good storage helps farmers keep grain without losing a crop to mould.","zh":"良好的儲存方法幫助農民保住穀物，沒有因霉菌而失去收成。"},{"en":"Strong fences may protect vegetables without losing a crop to animals.","zh":"堅固的圍欄可能保護蔬菜，沒有因動物而失去收成。"},{"en":"Farmers need reliable methods so they can change practices without losing a crop to pests.","zh":"農民需要可靠方法，才能改變做法而不因害蟲失去收成。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":1},{"front":"ravaging insects","meaning":"肆虐的害蟲","examples":[{"en":"Natural methods can protect crops from ravaging insects.","zh":"天然方法可以保護農作物免受肆虐的害蟲侵害。"},{"en":"Ravaging insects are insects that attack crops badly and cause serious damage.","zh":"肆虐的害蟲是嚴重攻擊農作物並造成重大損害的昆蟲。"},{"en":"A field of vegetables may be ruined if ravaging insects arrive during the growing season.","zh":"如果肆虐的害蟲在生長季節出現，一片菜田可能被毀掉。"},{"en":"Ravaging insects can spread quickly when there are no natural predators.","zh":"當沒有天然捕食者時，肆虐的害蟲可能迅速蔓延。"},{"en":"Farmers watch their fields carefully so ravaging insects are noticed early.","zh":"農民會仔細觀察田地，以便早點發現肆虐的害蟲。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":1},{"front":"explain how to do it","meaning":"解釋如何做到","examples":[{"en":"The story explains how to stop using chemical pesticides.","zh":"這個故事解釋如何停止使用化學農藥。"},{"en":"To explain how to do it means to give clear steps for completing an action.","zh":"解釋如何做到，是指提供清楚步驟去完成一個行動。"},{"en":"A teacher can explain how to do it by showing one example first.","zh":"老師可以先示範一個例子，來解釋如何做到。"},{"en":"Instructions are useful only if they explain how to do it, not just why it matters.","zh":"指示只有在解釋如何做到時才有用，而不只是說明它為何重要。"},{"en":"A good guide explains how to do it in simple stages.","zh":"好的指南會用簡單階段解釋如何做到。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":2},{"front":"a handful of families","meaning":"少數幾個家庭","examples":[{"en":"A handful of families migrated from Guntur to Punukala.","zh":"少數幾個家庭從 Guntur 遷移到 Punukala。"},{"en":"A handful of families means a small number of families.","zh":"少數幾個家庭指數量很少的家庭。"},{"en":"A handful of families in the village still cook with wood instead of gas.","zh":"村裡少數幾個家庭仍然用木柴而不是煤氣煮食。"},{"en":"If only a handful of families join a project, it may start slowly.","zh":"如果只有少數幾個家庭加入一個項目，它可能會開始得較慢。"},{"en":"A handful of families can still influence a whole community if their idea works.","zh":"如果想法有效，少數幾個家庭仍可以影響整個社區。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":2},{"front":"migrate from","meaning":"從……遷移","examples":[{"en":"Several families migrated from the Guntur district to Punukala.","zh":"幾個家庭從 Guntur 地區遷移到 Punukala。"},{"en":"To migrate from one place means to move away from it to live or work elsewhere.","zh":"從某地遷移，是指離開那裡到其他地方生活或工作。"},{"en":"Some workers migrate from villages to cities for better jobs.","zh":"有些工人從鄉村遷移到城市尋找更好的工作。"},{"en":"Families may migrate from dry areas when farming becomes difficult.","zh":"當耕作變得困難，家庭可能會從乾旱地區遷移。"},{"en":"People who migrate from home often bring skills, habits and crops with them.","zh":"從家鄉遷移的人，常會帶着技能、習慣和農作物一起來。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":2},{"front":"Guntur district","meaning":"Guntur 地區","examples":[{"en":"The families migrated from the Guntur district of Andhra Pradesh.","zh":"這些家庭從安得拉邦的 Guntur 地區遷移而來。"},{"en":"Guntur district is the area in Andhra Pradesh from which the families came.","zh":"Guntur 地區是安得拉邦內這些家庭原本所在的地方。"},{"en":"A district is a local area within a larger state or region.","zh":"地區是一個較大邦或區域內的本地範圍。"},{"en":"People from Guntur district brought cotton-growing knowledge to another village.","zh":"來自 Guntur 地區的人把棉花種植知識帶到另一條村。"},{"en":"Naming Guntur district helps readers understand where the migration began.","zh":"說明 Guntur 地區有助讀者理解遷移從哪裡開始。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":2},{"front":"Andhra Pradesh","meaning":"安得拉邦","examples":[{"en":"Cotton production spread through Andhra Pradesh state.","zh":"棉花生產在安得拉邦傳播開來。"},{"en":"Andhra Pradesh is the Indian state where the passage’s farming story takes place.","zh":"安得拉邦是這篇農業故事發生的印度邦。"},{"en":"Farmers in Andhra Pradesh faced serious problems with pesticide use.","zh":"安得拉邦的農民面對嚴重的農藥使用問題。"},{"en":"When cotton became valuable, many areas of Andhra Pradesh adopted it.","zh":"當棉花變得有價值，安得拉邦許多地區都採用了它。"},{"en":"Mentioning Andhra Pradesh gives the story a clear geographical setting.","zh":"提到安得拉邦，令故事有清楚的地理背景。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":2},{"front":"southeast India","meaning":"印度東南部","examples":[{"en":"Andhra Pradesh is located in southeast India.","zh":"安得拉邦位於印度東南部。"},{"en":"Southeast India means the south-eastern part of the country of India.","zh":"印度東南部指印度國土的東南方部分。"},{"en":"A map can help students find southeast India more easily.","zh":"地圖可以幫助學生更容易找到印度東南部。"},{"en":"Climate and crops in southeast India may differ from those in northern India.","zh":"印度東南部的氣候和農作物可能與印度北部不同。"},{"en":"The phrase southeast India tells readers the general region before naming a smaller place.","zh":"印度東南部這個說法在說出較小地方前，先告訴讀者大致區域。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":2},{"front":"a community of around","meaning":"約有……人的社區","examples":[{"en":"Punukala was a community of around 900 people.","zh":"Punukala 是一個約有 900 人的社區。"},{"en":"A community of around a number means a place with approximately that many people.","zh":"約有某個數字的社區，是指有大約那麼多人的地方。"},{"en":"The island is a community of around 500 residents.","zh":"這個小島是一個約有 500 名居民的社區。"},{"en":"A community of around 900 people is small enough for news to spread quickly.","zh":"一個約有 900 人的社區規模不大，消息很容易迅速傳開。"},{"en":"Writers use around when the number is close but not exact.","zh":"當數字接近但不是精確時，作者會使用 around。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":2},{"front":"farming plots","meaning":"耕種小塊土地","examples":[{"en":"The villagers farmed plots of between two and 10 acres.","zh":"村民耕種介乎二至十英畝的小塊土地。"},{"en":"Farming plots are small areas of land used for growing crops.","zh":"耕種小塊土地是指用來種植農作物的小面積土地。"},{"en":"A family may grow vegetables on several farming plots near its home.","zh":"一個家庭可能在家附近幾塊小土地上種菜。"},{"en":"Small farming plots can support families but may not produce large profits.","zh":"小塊耕地可以養活家庭，但未必能帶來大量利潤。"},{"en":"Farmers must manage each plot carefully because land is limited.","zh":"農民必須仔細管理每塊小土地，因為土地有限。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":2},{"front":"between two and 10 acres","meaning":"介乎二至十英畝","examples":[{"en":"The families farmed plots of between two and 10 acres.","zh":"這些家庭耕種介乎二至十英畝的土地。"},{"en":"Between two and 10 acres means the land size was not smaller than two acres and not larger than 10 acres.","zh":"介乎二至十英畝，意思是土地面積不小於二英畝，也不大於十英畝。"},{"en":"A small farm of between two and 10 acres may be run by one family.","zh":"一個介乎二至十英畝的小農場，可能由一個家庭經營。"},{"en":"Land between two and 10 acres can grow food but still require careful planning.","zh":"介乎二至十英畝的土地可以種植食物，但仍需要仔細規劃。"},{"en":"This phrase gives readers a rough idea of the farmers’ scale.","zh":"這個短語讓讀者大概知道農民的耕作規模。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":2},{"front":"outsiders from","meaning":"來自……的外來者","examples":[{"en":"The outsiders from Guntur brought cotton cultivation with them.","zh":"來自 Guntur 的外來者把棉花種植帶了過來。"},{"en":"Outsiders from a place are people who come from another area rather than the local community.","zh":"來自某地的外來者，是指來自其他地方而非本地社區的人。"},{"en":"Outsiders from the city may bring new business ideas to a village.","zh":"來自城市的外來者可能把新商業想法帶到村莊。"},{"en":"Outsiders from another region can change local farming habits.","zh":"來自另一地區的外來者可以改變本地耕作習慣。"},{"en":"The phrase can sound neutral, but it also shows that the people were not originally local.","zh":"這個短語可以是中性的，但也顯示這些人原本不是本地人。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":2},{"front":"cotton cultivation","meaning":"棉花種植","examples":[{"en":"The outsiders introduced cotton cultivation to Punukala.","zh":"外來者把棉花種植引入 Punukala。"},{"en":"Cotton cultivation means the growing of cotton as a crop.","zh":"棉花種植指把棉花作為農作物來栽種。"},{"en":"Cotton cultivation requires land, seeds, labour and pest control.","zh":"棉花種植需要土地、種子、勞力和害蟲控制。"},{"en":"When cotton cultivation spreads, farmers may change what they grow and sell.","zh":"當棉花種植傳播開來，農民可能改變自己種植和出售的作物。"},{"en":"Cotton cultivation can bring cash income but also new farming risks.","zh":"棉花種植可以帶來現金收入，但也帶來新的農業風險。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":2},{"front":"woo farmers by promising to","meaning":"以承諾……吸引農民","examples":[{"en":"Cotton wooed farmers by promising to bring in more cash.","zh":"棉花以承諾帶來更多現金收入來吸引農民。"},{"en":"To woo farmers by promising to do something means to attract them with the hope of a benefit.","zh":"以承諾做某事吸引農民，是指用某種好處的希望來吸引他們。"},{"en":"A seed company may woo farmers by promising to increase yields.","zh":"種子公司可能以承諾提高產量來吸引農民。"},{"en":"New technology can woo customers by promising to save time.","zh":"新科技可以以承諾節省時間來吸引顧客。"},{"en":"A promise may woo people at first, but results must prove it.","zh":"承諾起初可能吸引人，但結果必須證明它。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":3},{"front":"bring in more hard cash","meaning":"帶來更多現金收入","examples":[{"en":"Cotton promised to bring in more hard cash than mixed crops.","zh":"棉花承諾比混合農作物帶來更多現金收入。"},{"en":"To bring in more hard cash means to earn more real money that can be spent.","zh":"帶來更多現金收入，是指賺到更多可以花用的實際金錢。"},{"en":"A family may open a small shop to bring in more hard cash.","zh":"一個家庭可能開一間小店來帶來更多現金收入。"},{"en":"Farmers may choose a cash crop if it can bring in more hard cash than food crops.","zh":"如果經濟作物能比糧食作物帶來更多現金收入，農民可能會選擇它。"},{"en":"A choice that brings in more hard cash may still carry hidden costs.","zh":"能帶來更多現金收入的選擇，仍可能有隱藏成本。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":3},{"front":"hard cash","meaning":"現金；實在收入","examples":[{"en":"Farmers hoped cotton would provide hard cash.","zh":"農民希望棉花會提供現金收入。"},{"en":"Hard cash means real money that people can use immediately.","zh":"現金或實在收入，是指人們可以立即使用的實際金錢。"},{"en":"A part-time job gives students hard cash for transport and meals.","zh":"兼職工作給學生用於交通和膳食的現金。"},{"en":"Families may need hard cash to pay school fees or medical bills.","zh":"家庭可能需要現金來支付學費或醫療賬單。"},{"en":"A crop grown mainly for hard cash may reduce the land used for food.","zh":"主要為現金收入而種植的作物，可能減少用來種食物的土地。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":3},{"front":"mixed crops","meaning":"混合農作物","examples":[{"en":"The farmers had already been growing mixed crops to eat and sell.","zh":"農民早已種植混合農作物作食用和出售。"},{"en":"Mixed crops are different kinds of crops grown together or on the same farm.","zh":"混合農作物是指一起種植或在同一農場種植的不同作物。"},{"en":"A farmer may grow rice, beans and vegetables as mixed crops.","zh":"農民可能種植米、豆和蔬菜作為混合農作物。"},{"en":"Mixed crops can reduce risk because one failed crop does not ruin everything.","zh":"混合農作物可以降低風險，因為一種作物失收不會毀掉一切。"},{"en":"Mixed crops often support both family food needs and market sales.","zh":"混合農作物通常同時支持家庭食物需要和市場銷售。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":3},{"front":"grow something to eat and sell","meaning":"種植……作食用和出售","examples":[{"en":"The farmers grew millet, sorghum and rice to eat and sell.","zh":"農民種植小米、高粱和稻米作食用和出售。"},{"en":"To grow something to eat and sell means to produce crops for both family food and income.","zh":"種植某物作食用和出售，是指生產農作物同時用於家庭食物和收入。"},{"en":"A family may grow vegetables to eat and sell at the local market.","zh":"一個家庭可能種植蔬菜作食用，並在本地市場出售。"},{"en":"Growing crops to eat and sell can protect families when prices change.","zh":"種植農作物作食用和出售，可以在價格變動時保護家庭。"},{"en":"Farmers often choose crops that can feed the household and bring in money.","zh":"農民常選擇既能養活家庭又能帶來收入的作物。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":3},{"front":"millet","meaning":"小米","examples":[{"en":"Millet was one of the traditional crops grown by the farmers.","zh":"小米是農民種植的傳統農作物之一。"},{"en":"Millet is a small grain crop that people can cook and eat.","zh":"小米是一種細小穀物作物，人們可以煮來吃。"},{"en":"Some families use millet to make porridge or flatbread.","zh":"有些家庭用小米煮粥或製作薄餅。"},{"en":"Millet can be useful in dry areas because it often needs less water than rice.","zh":"小米在乾旱地區可能很有用，因為它通常比稻米需要較少水。"},{"en":"In the passage, millet shows that farmers once grew food crops as well as cash crops.","zh":"在篇章中，小米顯示農民以前既種糧食作物，也種經濟作物。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":3},{"front":"sorghum","meaning":"高粱","examples":[{"en":"Sorghum was grown along with other traditional crops.","zh":"高粱與其他傳統農作物一起種植。"},{"en":"Sorghum is a grain crop often grown for food or animal feed.","zh":"高粱是一種穀物作物，常用作食物或動物飼料。"},{"en":"Farmers may grow sorghum when the climate is too dry for some other crops.","zh":"當氣候對某些其他作物來說太乾旱時，農民可能會種高粱。"},{"en":"Sorghum can support families by providing grain during difficult seasons.","zh":"高粱可以在困難季節提供穀物，支持家庭生活。"},{"en":"Listing sorghum helps show the variety of crops before cotton became dominant.","zh":"列出高粱有助顯示棉花變得主導之前，農作物種類多樣。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":3},{"front":"groundnuts","meaning":"花生","examples":[{"en":"Groundnuts were one of the mixed crops grown in Punukala.","zh":"花生是 Punukala 種植的混合農作物之一。"},{"en":"Groundnuts are peanuts grown underground and used as food or for oil.","zh":"花生是在地下生長的豆類，可作食物或榨油。"},{"en":"A farmer may sell groundnuts in the market after drying them.","zh":"農民可能在曬乾花生後把它們拿到市場出售。"},{"en":"Groundnuts can add variety to a farm’s income and diet.","zh":"花生可以為農場的收入和飲食增加多樣性。"},{"en":"Growing groundnuts with other crops can reduce dependence on one harvest.","zh":"把花生與其他作物一起種植，可以減少對單一收成的依賴。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":3},{"front":"pigeon peas","meaning":"木豆","examples":[{"en":"Pigeon peas were among the crops grown by the local farmers.","zh":"木豆是本地農民種植的作物之一。"},{"en":"Pigeon peas are small beans often used as food in warm regions.","zh":"木豆是一種小豆，常在溫暖地區用作食物。"},{"en":"Families may cook pigeon peas in soups, stews or rice dishes.","zh":"家庭可能把木豆煮入湯、燉菜或飯食中。"},{"en":"Growing pigeon peas can help farmers produce food for home use.","zh":"種植木豆可以幫助農民生產家用食物。"},{"en":"Pigeon peas show that the farmers’ earlier crops were varied and practical.","zh":"木豆顯示農民早期的作物多樣而實用。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":3},{"front":"mung beans","meaning":"綠豆","examples":[{"en":"Mung beans were part of the farmers’ traditional mixed crops.","zh":"綠豆是農民傳統混合農作物的一部分。"},{"en":"Mung beans are small green beans used in many foods.","zh":"綠豆是一種細小的綠色豆類，用於許多食物。"},{"en":"A family may cook mung beans in soup or grow them as sprouts.","zh":"一個家庭可能用綠豆煲湯，或把它們發成芽菜。"},{"en":"Mung beans can give farmers another food source besides grains.","zh":"綠豆可以給農民穀物以外的另一種食物來源。"},{"en":"Including mung beans shows that mixed farming was not based on only one crop.","zh":"包括綠豆顯示混合耕作不是只依靠一種作物。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":3},{"front":"raising cotton","meaning":"種植棉花","examples":[{"en":"Raising cotton meant using pesticides and fertilisers.","zh":"種植棉花意味着使用農藥和肥料。"},{"en":"Raising cotton means growing cotton from planting to harvest.","zh":"種植棉花指從播種到收成都栽種棉花。"},{"en":"Farmers raising cotton must watch carefully for insects.","zh":"種植棉花的農民必須仔細留意昆蟲。"},{"en":"Raising cotton can become expensive if it requires many chemical products.","zh":"如果需要許多化學產品，種植棉花可能變得昂貴。"},{"en":"A family may stop raising cotton if the costs become higher than the income.","zh":"如果成本高於收入，一個家庭可能會停止種植棉花。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":3},{"front":"mean using","meaning":"意味着要使用","examples":[{"en":"Growing cotton meant using chemical pesticides and fertilisers.","zh":"種植棉花意味着要使用化學農藥和肥料。"},{"en":"To mean using something means that an action normally requires that thing.","zh":"意味着要使用某物，是指某個行動通常需要那樣東西。"},{"en":"Moving to a new flat may mean using a delivery service.","zh":"搬到新單位可能意味着要使用送貨服務。"},{"en":"Running an online class can mean using cameras, microphones and stable internet.","zh":"開網上課可能意味着要使用攝影機、咪高峰和穩定網絡。"},{"en":"Choosing one path often means using extra time, money or effort.","zh":"選擇一條路，往往意味着要使用額外時間、金錢或努力。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":4},{"front":"fertilisers","meaning":"肥料","examples":[{"en":"Cotton production required chemical fertilisers and pesticides.","zh":"棉花生產需要化學肥料和農藥。"},{"en":"Fertilisers are substances added to soil to help plants grow better.","zh":"肥料是加入泥土中幫助植物更好生長的物質。"},{"en":"Farmers may use fertilisers when the soil lacks nutrients.","zh":"當泥土缺乏養分時，農民可能會使用肥料。"},{"en":"Too much fertiliser can pollute water after heavy rain.","zh":"過量肥料在大雨後可能污染水源。"},{"en":"Organic fertilisers can feed plants while improving soil health.","zh":"有機肥料可以為植物提供養分，同時改善泥土健康。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":4},{"front":"until then","meaning":"在那之前","examples":[{"en":"Until then, pesticides and fertilisers had been a mystery to the farmers.","zh":"在那之前，農藥和肥料對農民來說一直是謎。"},{"en":"Until then means before that time or before that event happened.","zh":"在那之前，是指在那個時間或事件發生以前。"},{"en":"I had never used a laptop until then, so the first lesson was difficult.","zh":"在那之前，我從未用過手提電腦，所以第一堂課很困難。"},{"en":"The village had no clinic until then, so people travelled far for treatment.","zh":"村莊在那之前沒有診所，所以人們要去很遠的地方求醫。"},{"en":"This phrase helps show how knowledge or conditions changed at a particular point.","zh":"這個短語有助顯示知識或情況在某一刻如何改變。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":4},{"front":"a mystery to","meaning":"對……來說是謎","examples":[{"en":"Agricultural chemicals were a mystery to the mostly illiterate farmers.","zh":"農用化學品對大多目不識丁的農民來說是謎。"},{"en":"If something is a mystery to someone, they do not understand it.","zh":"如果某事對某人來說是謎，意思是他們不理解它。"},{"en":"Online banking may be a mystery to people who have never used a computer.","zh":"網上銀行對從未用過電腦的人來說可能是謎。"},{"en":"A medical report can be a mystery to patients unless a doctor explains it clearly.","zh":"醫療報告對病人來說可能是謎，除非醫生清楚解釋。"},{"en":"When something is a mystery to people, they may rely too much on others for advice.","zh":"當某事對人們來說是謎，他們可能過分依靠別人的意見。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":4},{"front":"mostly illiterate farmers","meaning":"大多目不識丁的農民","examples":[{"en":"The chemicals were unfamiliar to the mostly illiterate farmers.","zh":"這些化學品對大多目不識丁的農民來說很陌生。"},{"en":"Mostly illiterate farmers are farmers most of whom cannot read or write well.","zh":"大多目不識丁的農民，是指大部分不能良好閱讀或書寫的農民。"},{"en":"Mostly illiterate farmers may find written instructions difficult to use.","zh":"大多目不識丁的農民可能覺得書面指示很難使用。"},{"en":"Companies can exploit mostly illiterate farmers if information is not explained clearly.","zh":"如果資料沒有清楚解釋，公司可能剝削大多目不識丁的農民。"},{"en":"Training with pictures and demonstrations can help mostly illiterate farmers learn safely.","zh":"使用圖片和示範的培訓，可以幫助大多目不識丁的農民安全學習。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":4},{"front":"cotton production","meaning":"棉花生產","examples":[{"en":"Cotton production started spreading through Andhra Pradesh.","zh":"棉花生產開始在安得拉邦傳播。"},{"en":"Cotton production means the process of growing cotton for use or sale.","zh":"棉花生產指種植棉花作使用或出售的過程。"},{"en":"Cotton production includes planting, protecting, harvesting and selling cotton.","zh":"棉花生產包括播種、保護、收成和出售棉花。"},{"en":"Cotton production can rise when market prices are high.","zh":"當市場價格高時，棉花生產可能上升。"},{"en":"Heavy dependence on cotton production can make farmers vulnerable to pests and price changes.","zh":"過度依賴棉花生產，可能令農民容易受害蟲和價格變動影響。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":4},{"front":"spread through","meaning":"在……蔓延；傳遍","examples":[{"en":"Cotton production spread through Andhra Pradesh state.","zh":"棉花生產在安得拉邦傳播開來。"},{"en":"To spread through a place means to move across it and become common in many areas.","zh":"在某地蔓延或傳遍，是指在那裡移動並在許多地方變得常見。"},{"en":"News can spread through a school within minutes.","zh":"消息可以在幾分鐘內傳遍一間學校。"},{"en":"A disease may spread through a city if people are crowded together.","zh":"如果人們擠在一起，疾病可能在城市中蔓延。"},{"en":"New farming methods spread through villages when early results look successful.","zh":"當早期成果看起來成功，新耕作方法會傳遍村莊。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":4},{"front":"the high value of","meaning":"……的高價值","examples":[{"en":"The high value of cotton made it an attractive crop.","zh":"棉花的高價值使它成為有吸引力的作物。"},{"en":"The high value of something means it can bring a good price or strong benefit.","zh":"某物的高價值，是指它能帶來好價錢或重大好處。"},{"en":"The high value of land near the station makes rent expensive.","zh":"車站附近土地的高價值令租金昂貴。"},{"en":"The high value of a skill can attract students to study it.","zh":"一項技能的高價值可以吸引學生學習它。"},{"en":"Farmers may change crops because of the high value of one product.","zh":"農民可能因某種產品的高價值而改變作物。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":4},{"front":"exceptionally attractive","meaning":"格外吸引的","examples":[{"en":"Cotton became an exceptionally attractive crop for poor farmers.","zh":"棉花對貧窮農民來說變成格外吸引的作物。"},{"en":"Exceptionally attractive means much more appealing than usual.","zh":"格外吸引的意思是比平常更有吸引力。"},{"en":"A scholarship is exceptionally attractive to students who cannot afford tuition.","zh":"獎學金對負擔不起學費的學生來說格外吸引。"},{"en":"A job with high pay and flexible hours may be exceptionally attractive.","zh":"一份高薪且工時彈性的工作可能格外吸引。"},{"en":"Something exceptionally attractive can still be risky if people ignore the hidden costs.","zh":"格外吸引的事物如果令人忽略隱藏成本，仍然可能有風險。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":4},{"front":"require chemical fertilisers and pesticides","meaning":"需要化學肥料和農藥","examples":[{"en":"Growing cotton required chemical fertilisers and pesticides.","zh":"種植棉花需要化學肥料和農藥。"},{"en":"To require chemical fertilisers and pesticides means to need these products for growth and pest control.","zh":"需要化學肥料和農藥，是指需要這些產品來幫助生長和控制害蟲。"},{"en":"Some crops require chemical fertilisers and pesticides when grown on a large scale.","zh":"有些作物在大規模種植時需要化學肥料和農藥。"},{"en":"If a crop requires chemical fertilisers and pesticides, production costs may rise.","zh":"如果一種作物需要化學肥料和農藥，生產成本可能上升。"},{"en":"Farmers may prefer crops that do not require chemical fertilisers and pesticides.","zh":"農民可能較喜歡不需要化學肥料和農藥的作物。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":4},{"front":"previous experience using","meaning":"使用……的過往經驗","examples":[{"en":"Most farmers had no previous experience using agricultural chemicals.","zh":"大多數農民沒有使用農用化學品的過往經驗。"},{"en":"Previous experience using something means having used it before.","zh":"使用某物的過往經驗，是指以前曾經使用過它。"},{"en":"A new employee may have no previous experience using the company’s software.","zh":"新員工可能沒有使用公司軟件的過往經驗。"},{"en":"Without previous experience using a machine, workers need careful training.","zh":"如果沒有使用機器的過往經驗，工人需要仔細培訓。"},{"en":"Previous experience using a tool can make people more confident and safer.","zh":"使用工具的過往經驗可以令人更有信心，也更安全。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":4},{"front":"agricultural chemicals","meaning":"農用化學品","examples":[{"en":"The farmers had little experience with agricultural chemicals.","zh":"農民幾乎沒有使用農用化學品的經驗。"},{"en":"Agricultural chemicals are chemical products used in farming, such as pesticides and fertilisers.","zh":"農用化學品是農業中使用的化學產品，例如農藥和肥料。"},{"en":"Agricultural chemicals can help crops grow but must be handled safely.","zh":"農用化學品可以幫助農作物生長，但必須安全處理。"},{"en":"Misusing agricultural chemicals can harm farmers, animals and water sources.","zh":"誤用農用化學品可能傷害農民、動物和水源。"},{"en":"Clear labels are important when farmers buy agricultural chemicals.","zh":"農民購買農用化學品時，清楚的標籤很重要。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":5},{"front":"be forced to rely on","meaning":"被迫依賴","examples":[{"en":"The farmers were forced to rely on local dealers for advice.","zh":"農民被迫依賴本地經銷商提供意見。"},{"en":"To be forced to rely on someone means to have no real choice but to depend on them.","zh":"被迫依賴某人，是指沒有真正選擇，只能依靠他們。"},{"en":"Patients may be forced to rely on one clinic if there are no hospitals nearby.","zh":"如果附近沒有醫院，病人可能被迫依賴一間診所。"},{"en":"Students without internet may be forced to rely on printed notes.","zh":"沒有互聯網的學生可能被迫依賴印刷筆記。"},{"en":"People are vulnerable when they are forced to rely on advisers who may not be qualified.","zh":"當人們被迫依賴未必合資格的顧問時，他們會很脆弱。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":5},{"front":"local, small-scale agricultural dealers","meaning":"本地小型農資經銷商","examples":[{"en":"Farmers relied on local, small-scale agricultural dealers for advice.","zh":"農民依賴本地小型農資經銷商提供意見。"},{"en":"Local, small-scale agricultural dealers are nearby small sellers of farming supplies.","zh":"本地小型農資經銷商是附近銷售農業用品的小型商戶。"},{"en":"Such dealers may sell seeds, fertilisers and pesticides to village farmers.","zh":"這些經銷商可能向村莊農民出售種子、肥料和農藥。"},{"en":"Farmers may trust local, small-scale agricultural dealers because they are easy to reach.","zh":"農民可能信任本地小型農資經銷商，因為他們容易找到。"},{"en":"Problems arise if local, small-scale agricultural dealers lack technical knowledge.","zh":"如果本地小型農資經銷商缺乏技術知識，問題就會出現。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":5},{"front":"rely on someone for advice","meaning":"依靠某人提供意見","examples":[{"en":"Poor farmers relied on dealers for advice about pesticides.","zh":"貧窮農民依靠經銷商提供關於農藥的意見。"},{"en":"To rely on someone for advice means to depend on that person’s guidance.","zh":"依靠某人提供意見，是指依賴那個人的指導。"},{"en":"New parents may rely on nurses for advice about feeding a baby.","zh":"新手父母可能依靠護士提供關於餵養嬰兒的意見。"},{"en":"If people rely on sellers for advice, the advice may be biased.","zh":"如果人們依靠賣家提供意見，意見可能有偏見。"},{"en":"It is safer to rely on trained experts for advice when health or money is at risk.","zh":"當健康或金錢有風險時，依靠受過訓練的專家提供意見會較安全。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":5},{"front":"sell something on credit","meaning":"賒帳出售……","examples":[{"en":"The dealers sold seeds, fertilisers and pesticides on credit.","zh":"經銷商賒帳出售種子、肥料和農藥。"},{"en":"To sell something on credit means to let customers take it now and pay later.","zh":"賒帳出售某物，是指讓顧客先取貨，之後才付款。"},{"en":"A shop may sell school uniforms on credit to families before term starts.","zh":"商店可能在開學前賒帳出售校服給家庭。"},{"en":"Selling goods on credit can help poor buyers but also create debt.","zh":"賒帳出售貨物可以幫助貧窮買家，但也會造成債務。"},{"en":"Farmers may accept products on credit when they lack cash before harvest.","zh":"當農民在收成前缺乏現金時，可能會接受賒帳產品。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":5},{"front":"guarantee the purchase of","meaning":"擔保收購……","examples":[{"en":"The dealers guaranteed the purchase of the farmers’ crop.","zh":"經銷商擔保收購農民的作物。"},{"en":"To guarantee the purchase of something means to promise to buy it.","zh":"擔保收購某物，是指承諾購買它。"},{"en":"A supermarket may guarantee the purchase of vegetables from local farms.","zh":"超級市場可能擔保收購本地農場的蔬菜。"},{"en":"If a buyer guarantees the purchase of a crop, farmers may feel safer planting it.","zh":"如果買家擔保收購一種作物，農民種植它時可能更安心。"},{"en":"Such promises can be helpful, but they may also make farmers dependent on one buyer.","zh":"這些承諾可以有幫助，但也可能令農民依賴單一買家。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":5},{"front":"little technical knowledge","meaning":"技術知識有限","examples":[{"en":"The dealers themselves had little technical knowledge about pesticides.","zh":"經銷商自己對農藥的技術知識也有限。"},{"en":"Little technical knowledge means not much specialist understanding of how something works.","zh":"技術知識有限，是指對某物如何運作沒有太多專門理解。"},{"en":"A driver may have little technical knowledge about repairing an engine.","zh":"司機可能對修理引擎的技術知識有限。"},{"en":"People with little technical knowledge may repeat advice without checking it.","zh":"技術知識有限的人可能沒有查證就重複建議。"},{"en":"Dangerous products should not be explained by people with little technical knowledge.","zh":"危險產品不應由技術知識有限的人解釋。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":5},{"front":"merely pass on","meaning":"只是轉述；只是傳遞","examples":[{"en":"The dealers merely passed on information from chemical companies.","zh":"經銷商只是轉述化工公司的資料。"},{"en":"To merely pass on information means to repeat it without adding expert judgement.","zh":"只是轉述資料，是指重複資料而沒有加入專業判斷。"},{"en":"A receptionist may merely pass on a message from the manager.","zh":"接待員可能只是轉達經理的訊息。"},{"en":"If teachers merely pass on answers, students may not learn how to think.","zh":"如果老師只是傳遞答案，學生可能學不到如何思考。"},{"en":"Advice is weak when someone merely passes on sales information.","zh":"當某人只是轉述銷售資料時，建議就很薄弱。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":5},{"front":"promotional information","meaning":"推廣資料","examples":[{"en":"The dealers passed on promotional information from multinational companies.","zh":"經銷商轉述來自跨國公司的推廣資料。"},{"en":"Promotional information is material designed to advertise or sell a product.","zh":"推廣資料是為宣傳或銷售產品而設計的材料。"},{"en":"A phone shop may give customers promotional information about a new model.","zh":"手機店可能向顧客提供關於新型號的推廣資料。"},{"en":"Promotional information often highlights benefits but may hide risks.","zh":"推廣資料通常強調好處，但可能隱藏風險。"},{"en":"Farmers need independent advice, not only promotional information from sellers.","zh":"農民需要獨立建議，而不只是賣家的推廣資料。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":5},{"front":"multinational chemical companies","meaning":"跨國化工公司","examples":[{"en":"Multinational chemical companies supplied pesticide products.","zh":"跨國化工公司供應農藥產品。"},{"en":"Multinational chemical companies are chemical businesses that operate in more than one country.","zh":"跨國化工公司是在多於一個國家經營的化學品企業。"},{"en":"Multinational chemical companies may sell fertilisers, pesticides or industrial chemicals.","zh":"跨國化工公司可能銷售肥料、農藥或工業化學品。"},{"en":"Their products can reach remote villages through local dealers.","zh":"它們的產品可以透過本地經銷商到達偏遠村莊。"},{"en":"Multinational chemical companies may have strong marketing power over small farmers.","zh":"跨國化工公司可能對小農有強大的營銷影響力。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":5},{"front":"supply their products","meaning":"供應其產品","examples":[{"en":"Chemical companies supplied their products to local dealers.","zh":"化工公司把其產品供應給本地經銷商。"},{"en":"To supply their products means to provide the goods they make or sell.","zh":"供應其產品，是指提供它們製造或銷售的貨品。"},{"en":"Bakeries supply their products to cafés every morning.","zh":"麵包店每天早上把其產品供應給咖啡店。"},{"en":"If companies supply their products through small shops, they can reach more customers.","zh":"如果公司透過小店供應其產品，就能接觸更多顧客。"},{"en":"Suppliers should also provide clear safety information when they supply their products.","zh":"供應商供應其產品時，也應提供清楚的安全資料。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":5},{"front":"at first","meaning":"起初","examples":[{"en":"At first, cotton yields were high and pesticide expenses were low.","zh":"起初，棉花產量高，而農藥開支低。"},{"en":"At first means in the beginning, before the situation changes.","zh":"起初指一開始，在情況改變之前。"},{"en":"At first, the new job felt easy, but later the workload increased.","zh":"起初，新工作感覺容易，但後來工作量增加。"},{"en":"A plan may look successful at first before hidden problems appear.","zh":"一個計劃起初可能看似成功，之後隱藏問題才出現。"},{"en":"This phrase often prepares readers for a later contrast.","zh":"這個短語常為之後的對比作準備。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":6},{"front":"cotton yields","meaning":"棉花產量","examples":[{"en":"Cotton yields were high before the pests arrived.","zh":"害蟲出現之前，棉花產量很高。"},{"en":"Cotton yields are the amounts of cotton harvested from the fields.","zh":"棉花產量是指從田地收成的棉花數量。"},{"en":"Good rain and healthy soil can improve cotton yields.","zh":"充足雨水和健康泥土可以提高棉花產量。"},{"en":"Cotton yields may fall sharply if insects destroy the plants.","zh":"如果昆蟲破壞植物，棉花產量可能急劇下降。"},{"en":"Farmers compare cotton yields to decide whether a method is worth using.","zh":"農民比較棉花產量，以決定某種方法是否值得使用。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":6},{"front":"expenses for pesticides","meaning":"農藥開支","examples":[{"en":"Expenses for pesticides were low at first.","zh":"起初，農藥開支很低。"},{"en":"Expenses for pesticides are the money spent on buying and using pesticide products.","zh":"農藥開支是指購買和使用農藥產品所花的錢。"},{"en":"A farmer records expenses for pesticides to know the real cost of production.","zh":"農民記錄農藥開支，以了解生產的真正成本。"},{"en":"Expenses for pesticides can rise when insects become resistant.","zh":"當昆蟲產生抗藥性時，農藥開支可能上升。"},{"en":"Reducing expenses for pesticides can leave families with more income.","zh":"減少農藥開支可以讓家庭有更多收入。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":6},{"front":"cotton pests","meaning":"棉花害蟲","examples":[{"en":"Cotton pests had not yet moved into the fields.","zh":"棉花害蟲當時還未侵入田地。"},{"en":"Cotton pests are insects or other organisms that damage cotton plants.","zh":"棉花害蟲是破壞棉花植物的昆蟲或其他生物。"},{"en":"Bollworms and aphids can become serious cotton pests.","zh":"棉鈴蟲和蚜蟲可以成為嚴重的棉花害蟲。"},{"en":"Cotton pests reduce harvests when they eat leaves, flowers or bolls.","zh":"棉花害蟲吃葉、花或棉鈴時，會減少收成。"},{"en":"Farmers must notice cotton pests early before they spread widely.","zh":"農民必須及早發現棉花害蟲，以免它們廣泛蔓延。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":6},{"front":"move in","meaning":"進駐；侵入","examples":[{"en":"Cotton pests had not yet moved in.","zh":"棉花害蟲當時還未侵入。"},{"en":"To move in means to enter a place and begin living or spreading there.","zh":"進駐或侵入，是指進入某個地方並開始在那裡生活或蔓延。"},{"en":"Ants may move in if food is left on the kitchen floor.","zh":"如果食物留在廚房地板上，螞蟻可能會侵入。"},{"en":"New shops move in when a neighbourhood becomes popular.","zh":"當社區變得受歡迎，新商店會進駐。"},{"en":"In farming, pests moving in can quickly change a good season into a crisis.","zh":"在農業中，害蟲侵入可以很快把好季節變成危機。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":6},{"front":"within a few years","meaning":"數年之內","examples":[{"en":"Within a few years, pests plagued the cotton fields.","zh":"數年之內，害蟲在棉田肆虐。"},{"en":"Within a few years means after only several years, not a very long time.","zh":"數年之內，是指只過了幾年，不是很長時間。"},{"en":"Within a few years, the small shop became a successful chain.","zh":"數年之內，這間小店變成成功的連鎖店。"},{"en":"A farming problem can become serious within a few years if no one controls it.","zh":"如果沒有人控制，農業問題可以在數年之內變得嚴重。"},{"en":"This phrase shows that the change happened fairly quickly.","zh":"這個短語顯示變化發生得相當快。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":6},{"front":"bollworms","meaning":"棉鈴蟲","examples":[{"en":"Bollworms became a serious pest in the cotton fields.","zh":"棉鈴蟲成為棉田中的嚴重害蟲。"},{"en":"Bollworms are caterpillars that damage cotton by feeding on the plant.","zh":"棉鈴蟲是會啃食棉花植物並造成損害的毛蟲。"},{"en":"Farmers fear bollworms because they can reduce cotton harvests.","zh":"農民害怕棉鈴蟲，因為它們可以減少棉花收成。"},{"en":"If bollworms survive pesticide spraying, the next generation may be harder to kill.","zh":"如果棉鈴蟲在農藥噴灑後存活，下一代可能更難殺死。"},{"en":"Controlling bollworms is important in cotton farming.","zh":"控制棉鈴蟲對棉花種植很重要。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":6},{"front":"aphids","meaning":"蚜蟲","examples":[{"en":"Aphids were one of the pests that plagued the fields.","zh":"蚜蟲是在田間肆虐的害蟲之一。"},{"en":"Aphids are small insects that feed on plant juices.","zh":"蚜蟲是吸食植物汁液的小昆蟲。"},{"en":"A gardener may find aphids on the underside of leaves.","zh":"園丁可能在葉底發現蚜蟲。"},{"en":"Aphids can weaken plants and spread quickly in warm weather.","zh":"蚜蟲可以削弱植物，並在溫暖天氣中迅速蔓延。"},{"en":"Natural predators such as ladybirds can help control aphids.","zh":"瓢蟲等天然捕食者可以幫助控制蚜蟲。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":6},{"front":"plague the fields","meaning":"在田間肆虐","examples":[{"en":"Bollworms and aphids plagued the cotton fields.","zh":"棉鈴蟲和蚜蟲在棉田肆虐。"},{"en":"To plague the fields means to attack or trouble the fields repeatedly and seriously.","zh":"在田間肆虐，是指反覆而嚴重地侵襲或困擾田地。"},{"en":"Locusts can plague the fields when they arrive in large numbers.","zh":"當蝗蟲大量出現時，牠們可以在田間肆虐。"},{"en":"If pests plague the fields, farmers may lose income and food.","zh":"如果害蟲在田間肆虐，農民可能失去收入和食物。"},{"en":"The phrase suggests a problem that is widespread, repeated and hard to stop.","zh":"這個短語暗示問題廣泛、反覆而難以阻止。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":6},{"front":"rapid insect evolution","meaning":"昆蟲快速進化","examples":[{"en":"The farmers saw how rapid insect evolution could be.","zh":"農民看見昆蟲快速進化可以有多快。"},{"en":"Rapid insect evolution means insects change quickly over generations, often becoming harder to kill.","zh":"昆蟲快速進化，是指昆蟲在幾代之間迅速改變，常變得更難殺死。"},{"en":"Repeated spraying can speed up rapid insect evolution by leaving only resistant insects alive.","zh":"反覆噴灑可能只留下有抗藥性的昆蟲存活，從而加快昆蟲快速進化。"},{"en":"Rapid insect evolution can make yesterday’s pesticide ineffective today.","zh":"昆蟲快速進化可以令昨天有效的農藥今天失效。"},{"en":"Farmers need varied methods because rapid insect evolution can defeat a single chemical.","zh":"農民需要多種方法，因為昆蟲快速進化可能擊敗單一化學品。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":6},{"front":"repeated spraying","meaning":"反覆噴灑","examples":[{"en":"Repeated spraying killed off the weaker pests.","zh":"反覆噴灑消滅了較弱的害蟲。"},{"en":"Repeated spraying means spraying a chemical many times.","zh":"反覆噴灑是指多次噴灑某種化學品。"},{"en":"Repeated spraying may happen when farmers fear losing a crop.","zh":"當農民害怕失去收成時，可能會反覆噴灑。"},{"en":"Repeated spraying can increase costs and expose workers to more chemicals.","zh":"反覆噴灑會增加成本，並令工人接觸更多化學品。"},{"en":"If repeated spraying kills useful insects, pest problems may become worse.","zh":"如果反覆噴灑殺死有益昆蟲，害蟲問題可能變得更嚴重。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":6},{"front":"kill off","meaning":"消滅；殺死","examples":[{"en":"Pesticides killed off the weaker pests.","zh":"農藥消滅了較弱的害蟲。"},{"en":"To kill off living things means to destroy them completely or in large numbers.","zh":"消滅或殺死生物，是指完全或大量破壞它們。"},{"en":"A cold winter may kill off many garden insects.","zh":"寒冷冬天可能殺死許多花園昆蟲。"},{"en":"Strong chemicals can kill off bacteria, but they may also harm healthy organisms.","zh":"強力化學品可以殺死細菌，但也可能傷害健康生物。"},{"en":"Killing off one group can disturb the balance of nature.","zh":"消滅一個群體可能打亂自然平衡。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":7},{"front":"resistant to pesticides","meaning":"對農藥有抗藥性的","examples":[{"en":"The pests most resistant to pesticides survived and multiplied.","zh":"對農藥最有抗藥性的害蟲存活並繁殖。"},{"en":"Resistant to pesticides means able to survive after pesticide treatment.","zh":"對農藥有抗藥性，是指在農藥處理後仍能存活。"},{"en":"Insects can become resistant to pesticides after repeated exposure.","zh":"昆蟲在反覆接觸農藥後可能變得對農藥有抗藥性。"},{"en":"If pests are resistant to pesticides, farmers may spray more but get poor results.","zh":"如果害蟲對農藥有抗藥性，農民可能噴更多卻效果差。"},{"en":"Natural pest control can help reduce the pressure that creates resistance.","zh":"天然控蟲可以幫助減少造成抗藥性的壓力。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":7},{"front":"multiply","meaning":"繁殖；大量增加","examples":[{"en":"The resistant pests were left to multiply.","zh":"有抗藥性的害蟲被留下來繁殖。"},{"en":"To multiply means to increase in number by reproducing.","zh":"繁殖是指透過生殖而數量增加。"},{"en":"Bacteria can multiply quickly in warm food.","zh":"細菌可以在溫暖食物中迅速繁殖。"},{"en":"If insects multiply unchecked, a small problem can become a major infestation.","zh":"如果昆蟲不受控制地繁殖，小問題可能變成重大蟲害。"},{"en":"Pest control tries to stop harmful insects before they multiply.","zh":"害蟲控制嘗試在有害昆蟲大量增加前阻止它們。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":7},{"front":"pesticide resistance","meaning":"農藥抗藥性","examples":[{"en":"Pesticide resistance mounted as farmers sprayed more chemicals.","zh":"隨着農民噴灑更多化學品，農藥抗藥性增加。"},{"en":"Pesticide resistance is the ability of pests to survive chemicals that once killed them.","zh":"農藥抗藥性是害蟲能在曾經殺死牠們的化學品下存活的能力。"},{"en":"Pesticide resistance can develop when the same chemical is used too often.","zh":"當同一種化學品使用過於頻繁，農藥抗藥性可能形成。"},{"en":"As pesticide resistance grows, farmers may spend more and harvest less.","zh":"隨着農藥抗藥性增加，農民可能花更多錢但收成更少。"},{"en":"Good pest management tries to slow pesticide resistance.","zh":"良好的害蟲管理會嘗試減慢農藥抗藥性的發展。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":7},{"front":"as resistance mounted","meaning":"隨着抗藥性增加","examples":[{"en":"As pesticide resistance mounted, farmers had to use more pesticides.","zh":"隨着農藥抗藥性增加，農民不得不使用更多農藥。"},{"en":"As resistance mounted means while resistance increased and became more serious.","zh":"隨着抗藥性增加，是指抗藥性上升並變得更嚴重。"},{"en":"As pressure mounted, the team had to make a decision quickly.","zh":"隨着壓力增加，團隊不得不迅速作決定。"},{"en":"As resistance mounted in the insects, old sprays became less useful.","zh":"隨着昆蟲抗藥性增加，舊噴劑變得較無用。"},{"en":"This phrase shows a problem growing step by step.","zh":"這個短語顯示問題一步一步變大。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":7},{"front":"apply more and more of","meaning":"施用越來越多的……","examples":[{"en":"Farmers had to apply more and more of the pesticides.","zh":"農民不得不施用越來越多的農藥。"},{"en":"To apply more and more of something means to use increasingly larger amounts of it.","zh":"施用越來越多的某物，是指使用越來越大的份量。"},{"en":"A patient should not apply more and more of a cream without medical advice.","zh":"病人不應在沒有醫療建議下塗抹越來越多的藥膏。"},{"en":"If a cleaner stops working, using more and more of it may not solve the problem.","zh":"如果清潔劑停止有效，使用越來越多未必能解決問題。"},{"en":"Farmers applied more and more pesticide because the old amount no longer worked.","zh":"農民施用越來越多農藥，因為舊份量不再有效。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":7},{"front":"get the same results","meaning":"取得相同效果","examples":[{"en":"Farmers needed more pesticides to get the same results.","zh":"農民需要更多農藥才能取得相同效果。"},{"en":"To get the same results means to achieve the same effect as before.","zh":"取得相同效果，是指達到與以前一樣的作用。"},{"en":"A student may need more practice to get the same results in a harder course.","zh":"學生在更難的課程中可能需要更多練習才能取得相同效果。"},{"en":"If a medicine becomes less effective, a doctor may adjust the dose to get the same results.","zh":"如果藥物變得較無效，醫生可能調整劑量以取得相同效果。"},{"en":"Needing more effort to get the same results often shows that something has changed.","zh":"需要更多努力才能取得相同效果，往往顯示某些事情已經改變。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":7},{"front":"at the same time","meaning":"同時","examples":[{"en":"At the same time, pesticides killed birds, wasps and beetles.","zh":"同時，農藥殺死鳥類、黃蜂和甲蟲。"},{"en":"At the same time means while another thing is also happening.","zh":"同時是指另一件事也在發生。"},{"en":"A job can pay well and, at the same time, create heavy stress.","zh":"一份工作可以薪金高，同時造成沉重壓力。"},{"en":"Public transport can reduce traffic and at the same time cut pollution.","zh":"公共交通可以減少交通擠塞，同時減少污染。"},{"en":"This phrase helps connect two effects happening together.","zh":"這個短語有助連接一起發生的兩種影響。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":7},{"front":"wasps","meaning":"黃蜂","examples":[{"en":"Wasps once helped control pest insects naturally.","zh":"黃蜂曾經幫助天然控制害蟲。"},{"en":"Wasps are flying insects, some of which hunt other insects.","zh":"黃蜂是會飛的昆蟲，其中一些會捕食其他昆蟲。"},{"en":"In a garden, wasps may help by eating caterpillars.","zh":"在花園中，黃蜂可能透過吃毛蟲來幫忙。"},{"en":"Killing wasps can remove a natural form of pest control.","zh":"殺死黃蜂可能移除一種天然控蟲方式。"},{"en":"Although wasps may sting people, some wasps are useful in farming.","zh":"雖然黃蜂可能螫人，但有些黃蜂在農業中很有用。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":7},{"front":"beetles","meaning":"甲蟲","examples":[{"en":"Beetles were among the predators killed by pesticides.","zh":"甲蟲是被農藥殺死的捕食者之一。"},{"en":"Beetles are insects with hard wing covers; some eat pests.","zh":"甲蟲是有硬翅鞘的昆蟲；其中一些會吃害蟲。"},{"en":"Farmers may welcome beetles that feed on harmful insects.","zh":"農民可能歡迎吃有害昆蟲的甲蟲。"},{"en":"If pesticides kill useful beetles, pest numbers may rise later.","zh":"如果農藥殺死有益甲蟲，害蟲數量之後可能上升。"},{"en":"Beetles are part of the small wildlife that keeps fields balanced.","zh":"甲蟲是維持田地平衡的小型野生生物之一。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":7},{"front":"predators","meaning":"捕食者","examples":[{"en":"Pesticides killed predators that had once controlled pest insects.","zh":"農藥殺死了曾經控制害蟲的捕食者。"},{"en":"Predators are animals or insects that hunt and eat other living things.","zh":"捕食者是捕獵並吃其他生物的動物或昆蟲。"},{"en":"Birds, wasps and beetles can be predators of crop pests.","zh":"鳥類、黃蜂和甲蟲可以是農作物害蟲的捕食者。"},{"en":"When predators disappear, pest insects may multiply quickly.","zh":"當捕食者消失，害蟲可能迅速繁殖。"},{"en":"Protecting predators can reduce the need for chemical pesticides.","zh":"保護捕食者可以減少對化學農藥的需要。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":7},{"front":"natural control of","meaning":"對……的自然控制","examples":[{"en":"Predators provided natural control of pest insects.","zh":"捕食者提供了對害蟲的自然控制。"},{"en":"Natural control of pests means limiting them through nature rather than chemicals.","zh":"對害蟲的自然控制，是指透過自然方式而不是化學品限制牠們。"},{"en":"Birds can provide natural control of mosquitoes near ponds.","zh":"鳥類可以對池塘附近的蚊子提供自然控制。"},{"en":"Natural control of pests may fail if pesticides kill useful animals.","zh":"如果農藥殺死有益動物，對害蟲的自然控制可能失效。"},{"en":"Farmers who protect natural control often spend less on chemicals.","zh":"保護自然控制的農民通常在化學品上花費較少。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":8},{"front":"pest insects","meaning":"害蟲","examples":[{"en":"Predators helped control pest insects in the fields.","zh":"捕食者幫助控制田間害蟲。"},{"en":"Pest insects are insects that damage crops, stored food or plants.","zh":"害蟲是破壞農作物、儲存食物或植物的昆蟲。"},{"en":"Aphids are pest insects when they weaken vegetable leaves.","zh":"當蚜蟲削弱菜葉時，它們就是害蟲。"},{"en":"Pest insects can reduce harvests if they are not controlled.","zh":"如果不加以控制，害蟲可以減少收成。"},{"en":"Not all insects are pest insects; some help farmers by eating harmful species.","zh":"並非所有昆蟲都是害蟲；有些會吃有害物種來幫助農民。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":8},{"front":"the entire crop","meaning":"整批農作物","examples":[{"en":"Without predators, pests could destroy the entire crop.","zh":"沒有捕食者，害蟲可能摧毀整批農作物。"},{"en":"The entire crop means all of the plants or harvest in a field or season.","zh":"整批農作物指田地或一個季節中的全部植物或收成。"},{"en":"A flood can destroy the entire crop in one night.","zh":"一場洪水可以在一夜之間摧毀整批農作物。"},{"en":"Farmers fear losing the entire crop because it means losing income and food.","zh":"農民害怕失去整批農作物，因為這意味着失去收入和食物。"},{"en":"Protecting the entire crop requires planning before problems spread.","zh":"保護整批農作物需要在問題蔓延前作好規劃。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":8},{"front":"eventually","meaning":"最終","examples":[{"en":"Eventually, farmers had to mix pesticides and spray very often.","zh":"最終，農民不得不混合農藥並非常頻繁地噴灑。"},{"en":"Eventually means after some time, especially after a process or series of changes.","zh":"最終是指經過一段時間後，特別是在一個過程或一連串變化之後。"},{"en":"After many failed attempts, the student eventually understood the grammar rule.","zh":"經過多次失敗嘗試後，學生最終理解了文法規則。"},{"en":"If costs keep rising, a business may eventually close.","zh":"如果成本持續上升，企業最終可能倒閉。"},{"en":"This word often shows the final result of a developing situation.","zh":"這個詞常顯示某個發展中情況的最後結果。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":8},{"front":"mix pesticides","meaning":"混合農藥","examples":[{"en":"Farmers began mixing pesticides to fight resistant insects.","zh":"農民開始混合農藥來對抗有抗藥性的昆蟲。"},{"en":"To mix pesticides means to combine different pesticide products together.","zh":"混合農藥是指把不同農藥產品混在一起。"},{"en":"Mixing pesticides without expert advice can be dangerous.","zh":"沒有專家建議而混合農藥可能很危險。"},{"en":"Farmers may mix pesticides when one product no longer works.","zh":"當一種產品不再有效，農民可能會混合農藥。"},{"en":"The need to mix pesticides can show that pest resistance has become serious.","zh":"需要混合農藥可能顯示害蟲抗藥性已變得嚴重。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":8},{"front":"as often as","meaning":"頻密至；多達","examples":[{"en":"Some farmers sprayed their cotton as often as twice a week.","zh":"有些農民頻密至每星期兩次噴灑棉花。"},{"en":"As often as means up to a surprisingly frequent number of times.","zh":"頻密至或多達，是指次數高到令人注意或驚訝。"},{"en":"Some commuters check train updates as often as five times a day.","zh":"有些通勤者多達一天五次查看火車資訊。"},{"en":"A sick child may need medicine as often as every four hours.","zh":"生病的孩子可能頻密至每四小時需要服藥一次。"},{"en":"The phrase often suggests that the frequency is high or worrying.","zh":"這個短語通常暗示頻率很高或令人擔憂。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":8},{"front":"twice a week","meaning":"每星期兩次","examples":[{"en":"Farmers sometimes sprayed their cotton twice a week.","zh":"農民有時每星期兩次噴灑棉花。"},{"en":"Twice a week means two times in one week.","zh":"每星期兩次，是指一星期內兩次。"},{"en":"I go swimming twice a week to build fitness.","zh":"我每星期兩次游泳來增強體能。"},{"en":"A tutor may meet a student twice a week before an exam.","zh":"考試前，導師可能每星期兩次與學生見面。"},{"en":"Spraying twice a week shows how dependent farmers had become on pesticides.","zh":"每星期兩次噴灑顯示農民已變得多麼依賴農藥。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":8},{"front":"be hooked","meaning":"深陷其中；依賴成癮","examples":[{"en":"The farmers were really hooked on pesticides.","zh":"農民真的深陷對農藥的依賴之中。"},{"en":"To be hooked on something means to depend on it strongly or find it hard to stop using it.","zh":"深陷某物或對某物依賴成癮，是指強烈依賴它或很難停止使用它。"},{"en":"Some people become hooked on checking their phones every few minutes.","zh":"有些人變得依賴每隔幾分鐘查看手機。"},{"en":"Farmers became hooked on pesticides when each crop seemed to require more spraying.","zh":"當每次收成都似乎需要更多噴灑時，農民就深陷對農藥的依賴。"},{"en":"Being hooked on one solution can prevent people from trying safer alternatives.","zh":"依賴單一解決方法成癮，可能阻止人們嘗試更安全的替代方案。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":8},{"front":"be hesitant","meaning":"猶豫不決","examples":[{"en":"The villagers were hesitant about trying natural methods.","zh":"村民對嘗試天然方法猶豫不決。"},{"en":"To be hesitant means to feel unsure and slow to decide.","zh":"猶豫不決是指感到不確定，並且慢於作決定。"},{"en":"A student may be hesitant to speak English in front of the class.","zh":"學生可能猶豫不決，不敢在全班面前說英語。"},{"en":"People are often hesitant when a new method could risk their income.","zh":"當新方法可能危及收入時，人們常會猶豫不決。"},{"en":"Clear evidence can help hesitant people become more willing to try.","zh":"清楚證據可以幫助猶豫不決的人更願意嘗試。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":8},{"front":"village elders","meaning":"村中長者","examples":[{"en":"One of Punukala’s village elders decided to try natural methods.","zh":"Punukala 的一位村中長者決定嘗試天然方法。"},{"en":"Village elders are respected older members of a village community.","zh":"村中長者是村莊社區中受尊重的年長成員。"},{"en":"Village elders may help settle disputes or guide important decisions.","zh":"村中長者可能幫助解決爭端或指導重要決定。"},{"en":"When village elders support a project, other villagers may trust it more.","zh":"當村中長者支持一個項目，其他村民可能更信任它。"},{"en":"In many communities, village elders carry memory, experience and authority.","zh":"在許多社區中，村中長者承載記憶、經驗和權威。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":8},{"front":"decide to risk trying","meaning":"決定冒險嘗試","examples":[{"en":"A village elder decided to risk trying natural methods instead of pesticides.","zh":"一位村中長者決定冒險嘗試天然方法而不是農藥。"},{"en":"To decide to risk trying something means to try it even though failure is possible.","zh":"決定冒險嘗試某事，是指即使可能失敗仍選擇嘗試。"},{"en":"A small shop may decide to risk trying online sales.","zh":"一間小店可能決定冒險嘗試網上銷售。"},{"en":"Farmers may decide to risk trying a new crop when old methods stop working.","zh":"當舊方法不再有效時，農民可能決定冒險嘗試新作物。"},{"en":"People often decide to risk trying change when the current situation has become dangerous.","zh":"當現況已變得危險，人們常會決定冒險嘗試改變。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":8},{"front":"natural methods","meaning":"天然方法","examples":[{"en":"Natural methods were used instead of chemical pesticides.","zh":"天然方法被用來取代化學農藥。"},{"en":"Natural methods use plants, animals or farming practices rather than synthetic chemicals.","zh":"天然方法使用植物、動物或耕作方式，而不是合成化學品。"},{"en":"A gardener may use natural methods such as removing insects by hand.","zh":"園丁可能使用天然方法，例如用手清除昆蟲。"},{"en":"Natural methods can protect health if they reduce exposure to toxic substances.","zh":"如果天然方法減少接觸有毒物質，就可以保護健康。"},{"en":"Natural methods may require more labour but can make farming safer.","zh":"天然方法可能需要更多勞力，但可以令農業更安全。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":9},{"front":"instead of","meaning":"而不是","examples":[{"en":"The farmer tried natural methods instead of pesticides.","zh":"那位農民嘗試天然方法，而不是農藥。"},{"en":"Instead of shows that one thing is chosen and another is not chosen.","zh":"而不是表示選擇了一件事，而沒有選擇另一件事。"},{"en":"I walked home instead of taking a taxi.","zh":"我步行回家，而不是乘的士。"},{"en":"A school may repair old computers instead of buying new ones.","zh":"學校可能維修舊電腦，而不是購買新電腦。"},{"en":"In the passage, farmers used neem instead of chemical pesticides.","zh":"在篇章中，農民使用印楝，而不是化學農藥。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":9},{"front":"collapse with","meaning":"因……而倒下","examples":[{"en":"The farmer’s son collapsed with acute pesticide poisoning.","zh":"那位農民的兒子因急性農藥中毒而倒下。"},{"en":"To collapse with an illness means to fall down or become unable to stand because of it.","zh":"因某種疾病而倒下，是指因它而跌倒或無法站立。"},{"en":"A runner may collapse with heat exhaustion on a very hot day.","zh":"跑步者可能在非常炎熱的日子因中暑衰竭而倒下。"},{"en":"Workers can collapse with poisoning if they breathe toxic fumes.","zh":"如果工人吸入有毒煙霧，可能因中毒而倒下。"},{"en":"This phrase shows a sudden and serious physical reaction.","zh":"這個短語顯示突然而嚴重的身體反應。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":9},{"front":"acute pesticide poisoning","meaning":"急性農藥中毒","examples":[{"en":"His son collapsed with acute pesticide poisoning.","zh":"他的兒子因急性農藥中毒而倒下。"},{"en":"Acute pesticide poisoning is sudden serious illness caused by exposure to pesticides.","zh":"急性農藥中毒是由接觸農藥引起的突發嚴重疾病。"},{"en":"Acute pesticide poisoning may cause breathing problems, dizziness or collapse.","zh":"急性農藥中毒可能造成呼吸困難、頭暈或倒下。"},{"en":"Farmers risk acute pesticide poisoning when they spray without protection.","zh":"農民沒有防護就噴灑時，會有急性農藥中毒的風險。"},{"en":"Avoiding toxic chemicals can reduce the danger of acute pesticide poisoning.","zh":"避免有毒化學品可以降低急性農藥中毒的危險。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":9},{"front":"hospital bill","meaning":"醫院賬單","examples":[{"en":"The hospital bill after the poisoning was staggering.","zh":"中毒後的醫院賬單非常驚人。"},{"en":"A hospital bill is the amount of money charged for medical care.","zh":"醫院賬單是醫療護理所收取的金額。"},{"en":"A family may struggle to pay a hospital bill after an emergency.","zh":"緊急事故後，一個家庭可能難以支付醫院賬單。"},{"en":"A high hospital bill can push poor families into debt.","zh":"高昂的醫院賬單可以令貧窮家庭陷入債務。"},{"en":"Preventing illness is often cheaper than paying a hospital bill afterwards.","zh":"預防疾病通常比事後支付醫院賬單更便宜。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":9},{"front":"staggering","meaning":"驚人的","examples":[{"en":"The hospital bill was staggering.","zh":"醫院賬單非常驚人。"},{"en":"Staggering means extremely large, shocking or difficult to believe.","zh":"驚人的意思是極大、令人震驚或難以相信。"},{"en":"The rent increase was staggering for a family with low income.","zh":"對低收入家庭來說，租金升幅非常驚人。"},{"en":"A staggering number of students applied for the scholarship.","zh":"申請獎學金的學生人數驚人。"},{"en":"This word is used when a size, cost or effect is surprisingly high.","zh":"當規模、成本或影響高得令人意外時，可以使用這個詞。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":9},{"front":"coach someone on how to","meaning":"指導某人如何","examples":[{"en":"SECURE’s staff coached the villager on how to protect his crop.","zh":"SECURE 的職員指導那位村民如何保護他的農作物。"},{"en":"To coach someone on how to do something means to train or guide them step by step.","zh":"指導某人如何做某事，是指一步一步訓練或引導他們。"},{"en":"A manager may coach new staff on how to answer customers politely.","zh":"經理可能指導新員工如何有禮貌地回答顧客。"},{"en":"Teachers coach students on how to plan an essay before writing.","zh":"老師指導學生如何在寫作前規劃文章。"},{"en":"Good coaching shows people what to do, not only tells them what is wrong.","zh":"好的指導會展示人們應怎樣做，而不只是告訴他們錯在哪裡。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":9},{"front":"protect his cotton crop","meaning":"保護他的棉花作物","examples":[{"en":"The staff taught him how to protect his cotton crop naturally.","zh":"職員教他如何天然地保護他的棉花作物。"},{"en":"To protect his cotton crop means to keep his cotton plants safe from pests or damage.","zh":"保護他的棉花作物，是指使他的棉花植物免受害蟲或損害。"},{"en":"A farmer may protect his cotton crop by checking the field every day.","zh":"農民可能透過每天檢查田地來保護他的棉花作物。"},{"en":"Natural sprays can help protect his cotton crop without harmful chemicals.","zh":"天然噴劑可以幫助保護他的棉花作物，而不用有害化學品。"},{"en":"Protecting his cotton crop was essential because the harvest supported his family.","zh":"保護他的棉花作物很重要，因為收成支持他的家庭。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":9},{"front":"a toolkit of natural methods","meaning":"一套天然方法工具","examples":[{"en":"The farmer used a toolkit of natural methods to protect cotton.","zh":"那位農民使用一套天然方法工具來保護棉花。"},{"en":"A toolkit of natural methods is a set of different non-chemical techniques used together.","zh":"一套天然方法工具，是指一起使用的不同非化學技巧。"},{"en":"A school may use a toolkit of learning methods for students with different needs.","zh":"學校可能為有不同需要的學生使用一套學習方法工具。"},{"en":"A toolkit of natural methods works better when farmers know when to use each method.","zh":"當農民知道何時使用每種方法，一套天然方法工具會更有效。"},{"en":"The word toolkit suggests practical choices, not just one single solution.","zh":"工具一詞暗示實用選擇，而不只是單一解決方案。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":9},{"front":"put together","meaning":"編製；整合","examples":[{"en":"The Center for Sustainable Agriculture put together the toolkit.","zh":"可持續農業中心編製了這套工具。"},{"en":"To put together something means to create it by collecting and organising different parts.","zh":"編製或整合某物，是指收集並組織不同部分來創造它。"},{"en":"A teacher may put together notes from several books.","zh":"老師可能把幾本書的筆記整合起來。"},{"en":"Volunteers put together food packages for families after a flood.","zh":"洪水後，義工為家庭整理食物包。"},{"en":"Putting together a toolkit takes planning, knowledge and testing.","zh":"編製一套工具需要規劃、知識和測試。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":9},{"front":"in collaboration with","meaning":"與……合作","examples":[{"en":"The toolkit was developed in collaboration with university scientists.","zh":"這套工具是與大學科學家合作開發的。"},{"en":"In collaboration with someone means working together with them.","zh":"與某人合作，是指和他們一起工作。"},{"en":"The school created a health programme in collaboration with local doctors.","zh":"學校與本地醫生合作創建健康計劃。"},{"en":"A museum may design an exhibition in collaboration with community elders.","zh":"博物館可能與社區長者合作設計展覽。"},{"en":"Projects often improve when experts work in collaboration with local people.","zh":"當專家與本地人合作時，項目通常會改善。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":9},{"front":"sustainable agriculture","meaning":"可持續農業","examples":[{"en":"The toolkit came from India’s Center for Sustainable Agriculture.","zh":"這套工具來自印度的可持續農業中心。"},{"en":"Sustainable agriculture is farming that aims to protect land, water, farmers and future production.","zh":"可持續農業是旨在保護土地、水源、農民和未來生產的耕作方式。"},{"en":"Sustainable agriculture may use compost, crop rotation and natural pest control.","zh":"可持續農業可能使用堆肥、輪作和天然控蟲。"},{"en":"It helps farmers produce food without destroying the resources they need later.","zh":"它幫助農民生產食物，而不破壞日後需要的資源。"},{"en":"Sustainable agriculture balances income, health and the environment.","zh":"可持續農業平衡收入、健康和環境。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":10},{"front":"state university","meaning":"州立大學","examples":[{"en":"The scientists worked at Andhra Pradesh’s state university.","zh":"這些科學家在安得拉邦的州立大學工作。"},{"en":"A state university is a public university supported or run by a state government.","zh":"州立大學是由邦政府支持或營運的公立大學。"},{"en":"A state university may train teachers, doctors, engineers and scientists.","zh":"州立大學可能培訓教師、醫生、工程師和科學家。"},{"en":"Farmers may trust advice more when it comes from a state university.","zh":"當建議來自州立大學，農民可能更信任它。"},{"en":"Research from a state university can help solve local problems.","zh":"州立大學的研究可以幫助解決本地問題。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":10},{"front":"Non-Pesticide Management","meaning":"非農藥管理","examples":[{"en":"The toolkit was called Non-Pesticide Management.","zh":"這套工具稱為非農藥管理。"},{"en":"Non-Pesticide Management is a farming approach that controls pests without chemical pesticides.","zh":"非農藥管理是一種不用化學農藥控制害蟲的耕作方式。"},{"en":"Non-Pesticide Management may use neem, traps and natural predators.","zh":"非農藥管理可能使用印楝、陷阱和天然捕食者。"},{"en":"Farmers use Non-Pesticide Management to protect crops while reducing chemical harm.","zh":"農民使用非農藥管理來保護作物，同時減少化學傷害。"},{"en":"The name clearly shows that pesticides are not the main tool.","zh":"這個名稱清楚顯示農藥不是主要工具。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":10},{"front":"NPM","meaning":"非農藥管理","examples":[{"en":"NPM helped farmers grow cotton without chemical pesticides.","zh":"NPM 幫助農民不用化學農藥也能種植棉花。"},{"en":"NPM stands for Non-Pesticide Management.","zh":"NPM 代表非農藥管理。"},{"en":"Farmers used NPM to control pests with natural methods.","zh":"農民使用 NPM 以天然方法控制害蟲。"},{"en":"NPM reduced spending on pesticides and improved health in the village.","zh":"NPM 減少農藥開支，並改善村莊健康。"},{"en":"In the passage, NPM became a community solution, not just a farming technique.","zh":"在篇章中，NPM 成為社區解決方案，而不只是耕作技巧。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":10},{"front":"the most important resource","meaning":"最重要資源","examples":[{"en":"The most important resource in the NPM toolkit was the neem tree.","zh":"NPM 工具中最重要資源是印楝樹。"},{"en":"The most important resource is the thing most needed for success.","zh":"最重要資源是成功最需要的東西。"},{"en":"In a school, good teachers may be the most important resource.","zh":"在學校裡，好老師可能是最重要資源。"},{"en":"For a small business, loyal customers can be the most important resource.","zh":"對小企業來說，忠誠顧客可以是最重要資源。"},{"en":"Calling neem the most important resource shows its central role in NPM.","zh":"稱印楝為最重要資源，顯示它在 NPM 中的核心角色。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":10},{"front":"neem tree","meaning":"印楝樹","examples":[{"en":"The neem tree was central to natural pest control in Punukala.","zh":"印楝樹是 Punukala 天然控蟲的核心。"},{"en":"The neem tree is a tree whose seeds and parts can be used for natural pest control.","zh":"印楝樹是一種其種子和部分可用於天然控蟲的樹。"},{"en":"Farmers may grind neem seeds to make a spray for crops.","zh":"農民可能把印楝種子磨碎，製成農作物噴劑。"},{"en":"Neem trees are useful because they can provide pesticide material locally.","zh":"印楝樹很有用，因為它們可以在本地提供農藥材料。"},{"en":"In the passage, the neem tree helped farmers escape dependence on chemicals.","zh":"在篇章中，印楝樹幫助農民擺脫對化學品的依賴。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":10},{"front":"Azadirachta indica","meaning":"印楝的學名","examples":[{"en":"Azadirachta indica is the scientific name of the neem tree.","zh":"Azadirachta indica 是印楝樹的學名。"},{"en":"Azadirachta indica is the Latin scientific name used to identify neem precisely.","zh":"Azadirachta indica 是用來準確識別印楝的拉丁學名。"},{"en":"Scientists use names like Azadirachta indica to avoid confusion between local names.","zh":"科學家使用 Azadirachta indica 這類名稱，以避免不同本地名稱造成混淆。"},{"en":"A plant may have many common names but only one scientific name.","zh":"一種植物可能有許多俗名，但只有一個學名。"},{"en":"Learning Azadirachta indica helps students connect the local neem tree with scientific classification.","zh":"學習 Azadirachta indica 幫助學生把本地印楝樹與科學分類連繫起來。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":10},{"front":"be common throughout","meaning":"在……各地很常見","examples":[{"en":"The neem tree is common throughout much of India.","zh":"印楝樹在印度大部分地區很常見。"},{"en":"To be common throughout a place means to be found in many parts of that place.","zh":"在某地各地很常見，是指在該地方許多部分都能找到。"},{"en":"Convenience stores are common throughout many large cities.","zh":"便利店在許多大城市各地都很常見。"},{"en":"If a useful tree is common throughout a region, local people can use it cheaply.","zh":"如果一種有用的樹在某地區各地很常見，本地人就能低成本使用它。"},{"en":"Neem was practical because it was common throughout much of India.","zh":"印楝很實用，因為它在印度大部分地區很常見。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":10},{"front":"broad-leaved evergreen tree","meaning":"闊葉常綠樹","examples":[{"en":"The neem tree is a broad-leaved evergreen tree.","zh":"印楝樹是一種闊葉常綠樹。"},{"en":"A broad-leaved evergreen tree has wide leaves and keeps its leaves throughout the year.","zh":"闊葉常綠樹有寬闊葉片，並全年保持葉子。"},{"en":"A garden with broad-leaved evergreen trees can stay green in every season.","zh":"有闊葉常綠樹的花園可以四季保持綠色。"},{"en":"Such trees may provide shade and plant material even outside the rainy season.","zh":"這類樹即使在雨季以外，也可能提供樹蔭和植物材料。"},{"en":"This description helps readers imagine what the neem tree looks like.","zh":"這個描述幫助讀者想像印楝樹的外觀。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":10},{"front":"be related to","meaning":"與……有親緣關係","examples":[{"en":"The neem tree is related to mahogany.","zh":"印楝樹與桃花心木有親緣關係。"},{"en":"To be related to another plant means to belong to a connected biological group.","zh":"與另一種植物有親緣關係，是指屬於相關的生物群組。"},{"en":"Wolves are related to domestic dogs.","zh":"狼與家犬有親緣關係。"},{"en":"Two languages may be related to each other if they developed from the same older language.","zh":"如果兩種語言由同一種古老語言發展而來，它們可能有親緣關係。"},{"en":"Saying neem is related to mahogany helps classify it.","zh":"說印楝與桃花心木有親緣關係，有助對它分類。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":10},{"front":"mahogany","meaning":"桃花心木","examples":[{"en":"The neem tree is related to mahogany.","zh":"印楝樹與桃花心木有親緣關係。"},{"en":"Mahogany is a type of tree known for its hard, valuable wood.","zh":"桃花心木是一種以堅硬而有價值的木材聞名的樹。"},{"en":"Furniture makers may use mahogany because it is strong and attractive.","zh":"家具製造商可能使用桃花心木，因為它堅固而美觀。"},{"en":"Mentioning mahogany helps readers connect neem with a known tree family.","zh":"提到桃花心木，幫助讀者把印楝與一個已知的樹木家族連繫起來。"},{"en":"In this passage, mahogany is used to describe neem’s biological relationship.","zh":"在這篇文章中，桃花心木用來描述印楝的生物親緣關係。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":10},{"front":"protect itself against","meaning":"保護自己免受……侵害","examples":[{"en":"The neem tree protects itself against insects.","zh":"印楝樹保護自己免受昆蟲侵害。"},{"en":"To protect itself against something means to defend itself from harm.","zh":"保護自己免受某物侵害，是指防衛自己不受傷害。"},{"en":"A cactus protects itself against animals with sharp spines.","zh":"仙人掌用尖刺保護自己免受動物侵害。"},{"en":"The body protects itself against infection through the immune system.","zh":"身體透過免疫系統保護自己免受感染。"},{"en":"Neem protects itself against insects by producing natural chemicals.","zh":"印楝透過產生天然化學物質，保護自己免受昆蟲侵害。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":11},{"front":"a multitude of","meaning":"大量；眾多","examples":[{"en":"The neem tree produces a multitude of natural pesticides.","zh":"印楝樹產生大量天然農藥。"},{"en":"A multitude of something means a very large number or variety of it.","zh":"大量或眾多，是指數量或種類非常多。"},{"en":"A city offers a multitude of transport choices.","zh":"城市提供眾多交通選擇。"},{"en":"A multitude of small problems can become overwhelming if ignored.","zh":"大量小問題如果被忽視，可能變得難以承受。"},{"en":"Neem is useful because it produces a multitude of insect-fighting substances.","zh":"印楝很有用，因為它產生大量對抗昆蟲的物質。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":11},{"front":"in a variety of ways","meaning":"以多種方式","examples":[{"en":"Neem pesticides work in a variety of ways.","zh":"印楝農藥以多種方式發揮作用。"},{"en":"In a variety of ways means in several different methods or forms.","zh":"以多種方式，是指用幾種不同方法或形式。"},{"en":"Teachers explain new vocabulary in a variety of ways, such as examples and pictures.","zh":"老師以多種方式解釋新詞，例如例句和圖片。"},{"en":"A community can save water in a variety of ways.","zh":"社區可以以多種方式節約用水。"},{"en":"Neem controls insects in a variety of ways rather than through one single effect.","zh":"印楝以多種方式控制昆蟲，而不是只有單一作用。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":11},{"front":"repel egg-laying","meaning":"阻止產卵","examples":[{"en":"Neem can repel egg-laying by insects.","zh":"印楝可以阻止昆蟲產卵。"},{"en":"To repel egg-laying means to stop or discourage insects from laying eggs there.","zh":"阻止產卵，是指阻止或令昆蟲不願在某處產卵。"},{"en":"A plant smell may repel egg-laying on young leaves.","zh":"一種植物氣味可能阻止昆蟲在嫩葉上產卵。"},{"en":"If a spray repels egg-laying, fewer larvae will appear later.","zh":"如果噴劑阻止產卵，之後出現的幼蟲就會較少。"},{"en":"Repelling egg-laying controls pests before the next generation begins.","zh":"阻止產卵是在下一代開始前控制害蟲。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":11},{"front":"interfere with insect growth","meaning":"干擾昆蟲生長","examples":[{"en":"Neem substances can interfere with insect growth.","zh":"印楝物質可以干擾昆蟲生長。"},{"en":"To interfere with insect growth means to disturb the normal development of insects.","zh":"干擾昆蟲生長，是指擾亂昆蟲的正常發育。"},{"en":"Some natural chemicals interfere with insect growth so larvae cannot mature properly.","zh":"有些天然化學物質會干擾昆蟲生長，使幼蟲不能正常成熟。"},{"en":"If insect growth is disrupted, the pest population may fall.","zh":"如果昆蟲生長被擾亂，害蟲數量可能下降。"},{"en":"Neem does not only kill insects; it can also interfere with insect growth.","zh":"印楝不只是殺死昆蟲；它也可以干擾昆蟲生長。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":11},{"front":"disrupt the ability of","meaning":"破壞……的能力","examples":[{"en":"Neem can disrupt the ability of insects to sense food.","zh":"印楝可以破壞昆蟲感知食物的能力。"},{"en":"To disrupt the ability of something means to stop it from working normally.","zh":"破壞某物的能力，是指阻止它正常運作。"},{"en":"Loud noise can disrupt the ability of students to concentrate.","zh":"嘈雜聲音可以破壞學生專注的能力。"},{"en":"A computer virus may disrupt the ability of a company to serve customers.","zh":"電腦病毒可能破壞公司服務顧客的能力。"},{"en":"Neem disrupts the ability of insects to find food, so they harm crops less.","zh":"印楝破壞昆蟲尋找食物的能力，所以牠們對農作物的傷害較少。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":11},{"front":"crop-eating insects","meaning":"食害作物的昆蟲","examples":[{"en":"Neem affects crop-eating insects.","zh":"印楝會影響食害作物的昆蟲。"},{"en":"Crop-eating insects are insects that feed on and damage crops.","zh":"食害作物的昆蟲，是指啃食並破壞農作物的昆蟲。"},{"en":"Caterpillars can become crop-eating insects when they attack vegetables.","zh":"當毛蟲攻擊蔬菜時，就可能成為食害作物的昆蟲。"},{"en":"Crop-eating insects can reduce both food supply and farmers’ income.","zh":"食害作物的昆蟲可以同時減少食物供應和農民收入。"},{"en":"Farmers need safe ways to control crop-eating insects.","zh":"農民需要安全方法來控制食害作物的昆蟲。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":11},{"front":"sense their food","meaning":"感知食物","examples":[{"en":"Some neem compounds disrupt insects’ ability to sense their food.","zh":"有些印楝化合物會破壞昆蟲感知食物的能力。"},{"en":"To sense their food means to detect or find food through smell, taste or other signals.","zh":"感知食物，是指透過氣味、味道或其他訊號偵測或尋找食物。"},{"en":"Ants sense their food by following chemical trails.","zh":"螞蟻透過跟隨化學路徑來感知食物。"},{"en":"If insects cannot sense their food, they may stop feeding on the crop.","zh":"如果昆蟲不能感知食物，牠們可能停止啃食農作物。"},{"en":"Neem can protect plants by making it harder for pests to sense their food.","zh":"印楝可以令害蟲更難感知食物，從而保護植物。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":11},{"front":"be used traditionally","meaning":"傳統上被使用","examples":[{"en":"Neem has been used traditionally in India.","zh":"印楝在印度傳統上被使用。"},{"en":"To be used traditionally means to have been used for a long time by a community.","zh":"傳統上被使用，是指長時間被某個社區使用。"},{"en":"Ginger has been used traditionally in many homes to make warming drinks.","zh":"薑在許多家庭中傳統上被用來製作暖身飲品。"},{"en":"Plants used traditionally may later be studied by scientists.","zh":"傳統上被使用的植物，之後可能被科學家研究。"},{"en":"Neem’s traditional use helped people trust it as a natural resource.","zh":"印楝的傳統使用幫助人們相信它是一種天然資源。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":11},{"front":"stored grains","meaning":"儲存的穀物","examples":[{"en":"Neem has been used to protect stored grains from insects.","zh":"印楝一直被用來保護儲存的穀物免受昆蟲侵害。"},{"en":"Stored grains are grains kept after harvest for later use or sale.","zh":"儲存的穀物是收成後留待日後使用或出售的穀物。"},{"en":"Farmers must keep stored grains dry to prevent mould.","zh":"農民必須保持儲存的穀物乾爽，以防發霉。"},{"en":"Insects can destroy stored grains if bags are not protected.","zh":"如果袋子沒有保護，昆蟲可以摧毀儲存的穀物。"},{"en":"Protecting stored grains helps families survive between harvests.","zh":"保護儲存的穀物有助家庭在收成之間維持生活。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":11},{"front":"health products","meaning":"保健產品","examples":[{"en":"Neem has been used to produce soaps, skin lotions and health products.","zh":"印楝被用來生產肥皂、潤膚露和保健產品。"},{"en":"Health products are items made to support cleanliness, care or well-being.","zh":"保健產品是為支持清潔、護理或健康而製成的物品。"},{"en":"Pharmacies sell health products such as soap, creams and basic medical supplies.","zh":"藥房出售肥皂、護膚霜和基本醫療用品等保健產品。"},{"en":"Plant-based health products may be popular when people trust natural ingredients.","zh":"當人們信任天然成分時，植物性保健產品可能受歡迎。"},{"en":"Neem’s use in health products shows it has value beyond farming.","zh":"印楝用於保健產品，顯示它的價值不只限於農業。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":11},{"front":"protect crops from insects","meaning":"保護農作物免受昆蟲侵害","examples":[{"en":"Neem can protect crops from insects.","zh":"印楝可以保護農作物免受昆蟲侵害。"},{"en":"To protect crops from insects means to stop insects from damaging plants or harvests.","zh":"保護農作物免受昆蟲侵害，是指阻止昆蟲破壞植物或收成。"},{"en":"Farmers may use nets to protect crops from insects.","zh":"農民可能用網保護農作物免受昆蟲侵害。"},{"en":"Protecting crops from insects can prevent food loss and income loss.","zh":"保護農作物免受昆蟲侵害，可以防止食物損失和收入損失。"},{"en":"Neem protects crops from insects without relying mainly on synthetic chemicals.","zh":"印楝保護農作物免受昆蟲侵害，而不主要依賴合成化學品。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":12},{"front":"be ground into a powder","meaning":"被磨成粉末","examples":[{"en":"Neem seeds are ground into a powder.","zh":"印楝種子被磨成粉末。"},{"en":"To be ground into a powder means to be crushed until the pieces become very fine.","zh":"被磨成粉末，是指被壓碎到顆粒變得非常細。"},{"en":"Coffee beans are ground into a powder before making some drinks.","zh":"咖啡豆在製作某些飲品前會被磨成粉末。"},{"en":"Spices are often ground into a powder so they mix easily with food.","zh":"香料常被磨成粉末，使它們容易與食物混合。"},{"en":"Neem seeds are ground into a powder before being soaked in water.","zh":"印楝種子在浸泡於水中之前會被磨成粉末。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":12},{"front":"soaked overnight in water","meaning":"在水中浸泡一夜","examples":[{"en":"The neem powder is soaked overnight in water.","zh":"印楝粉末在水中浸泡一夜。"},{"en":"Soaked overnight in water means left in water for the whole night.","zh":"在水中浸泡一夜，是指整晚留在水裡。"},{"en":"Beans are often soaked overnight in water before cooking.","zh":"豆類在烹煮前常會在水中浸泡一夜。"},{"en":"Soaking seeds overnight in water can help release useful substances.","zh":"種子在水中浸泡一夜，可以幫助釋放有用物質。"},{"en":"Neem powder is soaked overnight in water to create a sprayable solution.","zh":"印楝粉末在水中浸泡一夜，以製成可噴灑的溶液。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":12},{"front":"the solution","meaning":"溶液","examples":[{"en":"The solution is sprayed onto the crop.","zh":"這種溶液被噴灑到農作物上。"},{"en":"The solution is the liquid mixture made after a substance has been dissolved or soaked in water.","zh":"溶液是某種物質溶解或浸泡在水中後形成的液體混合物。"},{"en":"A cleaning solution can be sprayed onto a table before wiping it.","zh":"清潔溶液可以在擦拭前噴到桌上。"},{"en":"If the solution is too strong, it may damage delicate plants.","zh":"如果溶液太濃，可能傷害脆弱的植物。"},{"en":"In the passage, the solution contains neem substances that help control insects.","zh":"在篇章中，這種溶液含有幫助控制昆蟲的印楝物質。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":12},{"front":"sprayed onto","meaning":"噴灑到……上","examples":[{"en":"The neem solution is sprayed onto the crop.","zh":"印楝溶液被噴灑到農作物上。"},{"en":"Sprayed onto something means applied to its surface in small drops of liquid.","zh":"噴灑到某物上，是指以細小液滴施加在它的表面。"},{"en":"Water is sprayed onto dusty roads to reduce dust.","zh":"水被噴灑到多塵道路上，以減少灰塵。"},{"en":"Disinfectant may be sprayed onto tables before a restaurant opens.","zh":"餐廳開門前，消毒劑可能被噴灑到桌上。"},{"en":"A crop spray must be sprayed onto the leaves evenly to work well.","zh":"作物噴劑必須均勻噴灑到葉上，才會有效。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":12},{"front":"another preparation","meaning":"另一種配製物","examples":[{"en":"Another preparation, neem cake, can be mixed into the soil.","zh":"另一種配製物印楝餅，可以混入泥土中。"},{"en":"Another preparation means a different form or mixture made for use.","zh":"另一種配製物，是指為使用而製成的另一種形式或混合物。"},{"en":"One medicine is a tablet, while another preparation is a liquid.","zh":"一種藥物是藥片，而另一種配製物是液體。"},{"en":"Farmers may use one preparation as a spray and another preparation in the soil.","zh":"農民可能把一種配製物作噴劑，另一種配製物用於泥土。"},{"en":"The phrase shows there is more than one way to use neem.","zh":"這個短語顯示印楝有多於一種使用方法。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":12},{"front":"neem cake","meaning":"印楝餅","examples":[{"en":"Neem cake can be mixed into the soil.","zh":"印楝餅可以混入泥土中。"},{"en":"Neem cake is the remaining solid material from neem seeds, used in soil.","zh":"印楝餅是印楝種子留下的固體材料，可用於泥土。"},{"en":"Farmers may add neem cake to fields before planting.","zh":"農民可能在播種前把印楝餅加入田地。"},{"en":"Neem cake can help control soil pests and improve soil nutrients.","zh":"印楝餅可以幫助控制土中害蟲並改善泥土養分。"},{"en":"In NPM, neem cake is useful because it works below the ground.","zh":"在 NPM 中，印楝餅很有用，因為它在地下發揮作用。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":12},{"front":"be mixed into the soil","meaning":"被混入泥土中","examples":[{"en":"Neem cake is mixed into the soil to kill pests.","zh":"印楝餅被混入泥土中以殺死害蟲。"},{"en":"To be mixed into the soil means to be blended with the earth where plants grow.","zh":"被混入泥土中，是指與植物生長的泥土混合。"},{"en":"Compost is often mixed into the soil before vegetables are planted.","zh":"堆肥常在種植蔬菜前被混入泥土中。"},{"en":"A material mixed into the soil can affect roots, nutrients and pests.","zh":"被混入泥土中的材料可以影響根部、養分和害蟲。"},{"en":"Neem cake is mixed into the soil so it can act directly where soil pests live.","zh":"印楝餅被混入泥土中，使它能在土傳害蟲生活的地方直接發揮作用。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":12},{"front":"soil-borne pests","meaning":"土傳害蟲","examples":[{"en":"Neem cake can kill soil-borne pests.","zh":"印楝餅可以殺死土傳害蟲。"},{"en":"Soil-borne pests are harmful organisms that live in or come from the soil.","zh":"土傳害蟲是生活在泥土中或從泥土來的有害生物。"},{"en":"Soil-borne pests may attack plant roots before farmers see damage above ground.","zh":"土傳害蟲可能在農民看到地面上損害之前，已經攻擊植物根部。"},{"en":"Controlling soil-borne pests can improve plant survival.","zh":"控制土傳害蟲可以提高植物存活率。"},{"en":"Neem cake targets soil-borne pests by being mixed into the field.","zh":"印楝餅透過混入田地，針對土傳害蟲。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":12},{"front":"soil-borne diseases","meaning":"土傳病害","examples":[{"en":"Neem cake can help control soil-borne diseases.","zh":"印楝餅可以幫助控制土傳病害。"},{"en":"Soil-borne diseases are plant diseases that start in the soil.","zh":"土傳病害是從泥土開始的植物疾病。"},{"en":"Soil-borne diseases can make roots rot and plants weaken.","zh":"土傳病害可以令根部腐爛並使植物變弱。"},{"en":"Farmers rotate crops to reduce soil-borne diseases.","zh":"農民透過輪作減少土傳病害。"},{"en":"Healthy soil management helps prevent soil-borne diseases from returning.","zh":"健康的泥土管理有助防止土傳病害再次出現。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":12},{"front":"double as","meaning":"兼作","examples":[{"en":"Neem cake doubles as an organic fertilizer.","zh":"印楝餅兼作有機肥料。"},{"en":"To double as something means to have a second use or function.","zh":"兼作某物，是指有第二種用途或功能。"},{"en":"A sofa can double as a bed in a small flat.","zh":"在小單位中，梳化可以兼作睡床。"},{"en":"A school hall may double as a community meeting space.","zh":"學校禮堂可能兼作社區會議空間。"},{"en":"Neem cake is valuable because it controls pests and doubles as fertiliser.","zh":"印楝餅很有價值，因為它控制害蟲並兼作肥料。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":12},{"front":"organic fertilizer","meaning":"有機肥料","examples":[{"en":"Neem cake can be used as an organic fertilizer.","zh":"印楝餅可以用作有機肥料。"},{"en":"Organic fertilizer is plant or animal-based material that adds nutrients to soil.","zh":"有機肥料是由植物或動物材料製成、為泥土增加養分的物質。"},{"en":"Compost is a common organic fertilizer used in gardens.","zh":"堆肥是花園中常用的有機肥料。"},{"en":"Organic fertilizer can improve soil structure as well as feed plants.","zh":"有機肥料可以改善泥土結構，也可以為植物提供養分。"},{"en":"Farmers may prefer organic fertilizer when they want to reduce chemical use.","zh":"當農民想減少化學品使用時，可能較喜歡有機肥料。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":13},{"front":"high in nitrogen","meaning":"富含氮","examples":[{"en":"Neem cake is high in nitrogen.","zh":"印楝餅富含氮。"},{"en":"High in nitrogen means containing a large amount of nitrogen, a nutrient plants need.","zh":"富含氮，是指含有大量氮，而氮是植物需要的養分。"},{"en":"Some fertilisers are high in nitrogen to help leaves grow.","zh":"有些肥料富含氮，以幫助葉片生長。"},{"en":"Soil high in nitrogen can support strong plant growth if other nutrients are balanced.","zh":"如果其他養分平衡，富含氮的泥土可以支持植物強壯生長。"},{"en":"Neem cake helps crops partly because it is high in nitrogen.","zh":"印楝餅能幫助作物，部分原因是它富含氮。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":13},{"front":"grow locally","meaning":"在本地生長","examples":[{"en":"Neem trees grow locally, so the cost is low.","zh":"印楝樹在本地生長，所以成本很低。"},{"en":"To grow locally means to grow in the nearby area rather than being imported.","zh":"在本地生長，是指在附近地區生長，而不是從外地進口。"},{"en":"Vegetables that grow locally are often fresher and cheaper.","zh":"在本地生長的蔬菜通常更新鮮和更便宜。"},{"en":"If useful plants grow locally, farmers do not need to buy expensive materials from far away.","zh":"如果有用植物在本地生長，農民就不需要從遠方購買昂貴材料。"},{"en":"Neem was affordable because it grew locally around the farmers.","zh":"印楝價格可負擔，因為它在農民附近本地生長。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":13},{"front":"prepare something for application","meaning":"準備……以便施用","examples":[{"en":"Farmers need labour to prepare neem for application to fields.","zh":"農民需要勞力準備印楝，以便施用於田地。"},{"en":"To prepare something for application means to make it ready to be used on a surface, crop or area.","zh":"準備某物以便施用，是指使它準備好用在表面、作物或地方上。"},{"en":"Workers prepare paint for application by mixing it properly.","zh":"工人透過正確混合油漆，準備它以便施用。"},{"en":"Farmers prepare natural sprays for application before walking through the fields.","zh":"農民在走進田地前，準備天然噴劑以便施用。"},{"en":"Preparation matters because poorly prepared materials may not work well.","zh":"準備很重要，因為準備不當的材料可能效果不好。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":13},{"front":"application to fields","meaning":"施用於田地","examples":[{"en":"The only cost is the labour needed for application to fields.","zh":"唯一成本是施用於田地所需的勞力。"},{"en":"Application to fields means putting or using a substance on farmland.","zh":"施用於田地，是指把某種物質放到或用於農田。"},{"en":"Fertiliser application to fields usually happens before or during crop growth.","zh":"肥料施用於田地通常在作物生長前或期間進行。"},{"en":"Application to fields takes time when the land is large.","zh":"當土地很大時，施用於田地需要時間。"},{"en":"Neem is cheap, but application to fields still requires human work.","zh":"印楝很便宜，但施用於田地仍需要人力。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":13},{"front":"the first farmer’s trial","meaning":"第一位農民的試驗","examples":[{"en":"The first farmer’s trial with NPM was a complete success.","zh":"第一位農民使用 NPM 的試驗完全成功。"},{"en":"The first farmer’s trial means the first test carried out by one farmer.","zh":"第一位農民的試驗，是指由一位農民進行的第一次測試。"},{"en":"The first farmer’s trial helped other villagers judge whether the method was safe.","zh":"第一位農民的試驗幫助其他村民判斷這種方法是否安全。"},{"en":"If the first farmer’s trial fails, others may refuse to try the method.","zh":"如果第一位農民的試驗失敗，其他人可能拒絕嘗試這種方法。"},{"en":"A successful first trial can turn private risk into community confidence.","zh":"成功的第一次試驗可以把個人風險變成社區信心。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":13},{"front":"a complete success","meaning":"完全成功","examples":[{"en":"The trial with NPM was a complete success.","zh":"使用 NPM 的試驗完全成功。"},{"en":"A complete success means something works fully and achieves the desired result.","zh":"完全成功，是指某事完全有效並達到想要的結果。"},{"en":"The school fair was a complete success because many families joined and enough money was raised.","zh":"學校嘉年華完全成功，因為許多家庭參與並籌到足夠款項。"},{"en":"A new method becomes convincing when the first test is a complete success.","zh":"當第一次測試完全成功，新方法就會變得有說服力。"},{"en":"Calling the trial a complete success shows that it met both farming and financial needs.","zh":"稱這次試驗完全成功，顯示它同時滿足農業和財務需要。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":13},{"front":"harvest","meaning":"收成","examples":[{"en":"His harvest was as good as the harvests of pesticide users.","zh":"他的收成與使用農藥者的收成一樣好。"},{"en":"A harvest is the crop collected from the fields.","zh":"收成是從田地收集回來的農作物。"},{"en":"Farmers celebrate when the harvest is large and healthy.","zh":"當收成又多又健康時，農民會慶祝。"},{"en":"A poor harvest can make it hard for a family to repay debt.","zh":"差劣收成可能令家庭難以還債。"},{"en":"Comparing harvests helps farmers see whether a farming method works.","zh":"比較收成有助農民了解某種耕作方法是否有效。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":13},{"front":"as good as","meaning":"與……一樣好","examples":[{"en":"His harvest was as good as those of farmers using pesticides.","zh":"他的收成與使用農藥的農民一樣好。"},{"en":"As good as means equal in quality or result.","zh":"與……一樣好，是指質素或結果相等。"},{"en":"A homemade meal can be as good as restaurant food.","zh":"家常飯可以與餐廳食物一樣好。"},{"en":"If a cheaper method is as good as an expensive one, people may change their habits.","zh":"如果較便宜的方法與昂貴方法一樣好，人們可能改變習慣。"},{"en":"NPM became convincing because the harvest was as good as pesticide-based harvests.","zh":"NPM 變得有說服力，因為收成與依靠農藥的收成一樣好。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":13},{"front":"spend a single rupee on","meaning":"在……上花一盧比","examples":[{"en":"The farmer did not spend a single rupee on pesticides.","zh":"那位農民沒有在農藥上花一盧比。"},{"en":"To not spend a single rupee on something means to spend no money on it at all.","zh":"沒有在某物上花一盧比，是指完全沒有在它上面花錢。"},{"en":"She repaired the old shelf without spending a single dollar on new furniture.","zh":"她修理舊書架，沒有在新家具上花一元。"},{"en":"If farmers spend no money on pesticides, more income stays with the family.","zh":"如果農民沒有在農藥上花錢，更多收入會留在家庭中。"},{"en":"The phrase emphasises that the saving was total, not just small.","zh":"這個短語強調節省是完全的，而不只是少量。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":13},{"front":"inspired by","meaning":"受……鼓舞","examples":[{"en":"Inspired by this success, 20 farmers tried NPM the next year.","zh":"受這次成功鼓舞，20 位農民在翌年嘗試 NPM。"},{"en":"Inspired by something means encouraged or motivated because of it.","zh":"受某事鼓舞，是指因它而受到鼓勵或推動。"},{"en":"Inspired by her teacher, the student entered a writing competition.","zh":"受老師鼓舞，那名學生參加了寫作比賽。"},{"en":"People may try a new method when they are inspired by someone else’s success.","zh":"當人們受別人的成功鼓舞時，可能會嘗試新方法。"},{"en":"The farmers were inspired by real results, not only promises.","zh":"農民受真實成果鼓舞，而不只是受承諾鼓舞。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":13},{"front":"station staff in","meaning":"派駐職員到……","examples":[{"en":"SECURE stationed two well-trained staff in Punukala.","zh":"SECURE 派駐兩名訓練有素的職員到 Punukala。"},{"en":"To station staff in a place means to send workers there to stay and work.","zh":"派駐職員到某地，是指派工人到那裡留下並工作。"},{"en":"A hospital may station nurses in a village during a vaccination campaign.","zh":"醫院可能在疫苗接種活動期間派駐護士到村莊。"},{"en":"An organisation stations staff in a community when daily support is needed.","zh":"當社區需要日常支援時，組織會派駐職員到那裡。"},{"en":"Stationing staff in Punukala helped farmers receive practical guidance.","zh":"派駐職員到 Punukala 幫助農民獲得實際指導。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":14},{"front":"well-trained staff","meaning":"訓練有素的職員","examples":[{"en":"SECURE stationed two well-trained staff in the village.","zh":"SECURE 在村裡派駐兩名訓練有素的職員。"},{"en":"Well-trained staff are workers who have learned the skills needed for their job.","zh":"訓練有素的職員，是指已學會工作所需技能的員工。"},{"en":"Well-trained staff can explain safety rules clearly to new workers.","zh":"訓練有素的職員可以清楚向新工人解釋安全規則。"},{"en":"A clinic with well-trained staff can provide better care.","zh":"有訓練有素職員的診所可以提供更好的護理。"},{"en":"Farmers trusted NPM more because well-trained staff were present in the village.","zh":"因為村裡有訓練有素的職員，農民更信任 NPM。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":14},{"front":"put pressure on","meaning":"向……施壓","examples":[{"en":"The village women put pressure on their husbands to stop using chemicals.","zh":"村中婦女向丈夫施壓，要求他們停止使用化學品。"},{"en":"To put pressure on someone means to push or urge them to do something.","zh":"向某人施壓，是指推動或催促他們做某事。"},{"en":"Parents may put pressure on a school to improve safety.","zh":"家長可能向學校施壓，要求改善安全。"},{"en":"Customers can put pressure on companies to reduce plastic packaging.","zh":"顧客可以向公司施壓，要求減少塑膠包裝。"},{"en":"In the village, women put pressure on husbands because family health was at risk.","zh":"在村裡，婦女向丈夫施壓，因為家庭健康受到威脅。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":14},{"front":"stop using toxic chemicals","meaning":"停止使用有毒化學品","examples":[{"en":"The women urged their husbands to stop using toxic chemicals.","zh":"婦女敦促丈夫停止使用有毒化學品。"},{"en":"To stop using toxic chemicals means to no longer use substances that can poison or harm living things.","zh":"停止使用有毒化學品，是指不再使用可能毒害或傷害生物的物質。"},{"en":"A cleaner may stop using toxic chemicals after getting skin irritation.","zh":"清潔工在皮膚受刺激後，可能停止使用有毒化學品。"},{"en":"Farmers stop using toxic chemicals when safer methods protect the crop.","zh":"當較安全方法能保護作物，農民就會停止使用有毒化學品。"},{"en":"Stopping toxic chemicals can improve health at home and in the fields.","zh":"停止使用有毒化學品可以改善家庭和田間的健康。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":14},{"front":"expose themselves to","meaning":"使自己接觸……","examples":[{"en":"Families were no longer exposing themselves to pesticides.","zh":"家庭不再使自己接觸農藥。"},{"en":"To expose themselves to something harmful means to put themselves in contact with danger.","zh":"使自己接觸有害物，是指讓自己接觸危險。"},{"en":"Workers expose themselves to dust if they do not wear masks.","zh":"如果工人不戴口罩，就會使自己接觸灰塵。"},{"en":"Children may expose themselves to germs when they share cups.","zh":"孩子共用杯子時，可能使自己接觸細菌。"},{"en":"Avoiding pesticides helped villagers stop exposing themselves to poison.","zh":"避免農藥幫助村民停止使自己接觸毒物。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":14},{"front":"begin to feel much better","meaning":"開始感覺好得多","examples":[{"en":"Families began to feel much better after avoiding pesticides.","zh":"避免農藥後，家庭開始感覺好得多。"},{"en":"To begin to feel much better means to start feeling healthier, safer or more comfortable.","zh":"開始感覺好得多，是指開始感到更健康、更安全或更舒服。"},{"en":"After sleeping properly, the student began to feel much better.","zh":"睡眠充足後，學生開始感覺好得多。"},{"en":"Workers may begin to feel much better when dangerous fumes are removed.","zh":"當危險煙霧被移除，工人可能開始感覺好得多。"},{"en":"The phrase shows an improvement that people can notice in daily life.","zh":"這個短語顯示人們在日常生活中能感受到的改善。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":14},{"front":"rapid improvement in","meaning":"……的快速改善","examples":[{"en":"There was rapid improvement in income, health and well-being.","zh":"收入、健康和福祉出現快速改善。"},{"en":"Rapid improvement in something means it gets better quickly.","zh":"某方面的快速改善，是指它很快變得更好。"},{"en":"A student may show rapid improvement in speaking after daily practice.","zh":"學生每天練習後，口語可能出現快速改善。"},{"en":"Rapid improvement in health can occur when a harmful cause is removed.","zh":"當有害原因被移除，健康可能出現快速改善。"},{"en":"The village saw rapid improvement because costs fell and poisoning stopped.","zh":"村莊出現快速改善，因為成本下降而中毒停止。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":14},{"front":"general well-being","meaning":"整體福祉","examples":[{"en":"NPM improved income, health and general well-being.","zh":"NPM 改善了收入、健康和整體福祉。"},{"en":"General well-being means people’s overall physical, mental and social condition.","zh":"整體福祉是指人的整體身體、心理和社交狀況。"},{"en":"Good sleep, safe work and family support improve general well-being.","zh":"良好睡眠、安全工作和家庭支持會改善整體福祉。"},{"en":"Pollution can damage general well-being even if people still earn money.","zh":"污染即使在人們仍有收入時，也可以損害整體福祉。"},{"en":"The phrase goes beyond income and includes how people feel and live.","zh":"這個短語不只指收入，也包括人們的感受和生活。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":14},{"front":"sell everyone on","meaning":"令所有人相信","examples":[{"en":"The quick results sold everyone on the value of NPM.","zh":"快速成果令所有人相信 NPM 的價值。"},{"en":"To sell everyone on an idea means to persuade everyone that it is good or useful.","zh":"令所有人相信某個想法，是指說服所有人它是好的或有用的。"},{"en":"A successful trial lesson can sell parents on a new teaching method.","zh":"一堂成功的試堂可以令家長相信新的教學方法。"},{"en":"Clear savings sold the workers on the new energy plan.","zh":"清楚的節省效果令工人相信新的節能計劃。"},{"en":"Real results sell people on change more effectively than speeches.","zh":"真實成果比演說更有效令人大眾相信改變。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":14},{"front":"the value of","meaning":"……的價值","examples":[{"en":"The villagers quickly saw the value of NPM.","zh":"村民很快看見 NPM 的價值。"},{"en":"The value of something means its usefulness, importance or benefit.","zh":"某物的價值，是指它的用途、重要性或好處。"},{"en":"Students see the value of grammar when it helps them write clearly.","zh":"當文法幫助學生清楚寫作時，學生會看見文法的價值。"},{"en":"Families may see the value of insurance after a medical emergency.","zh":"醫療緊急情況後，家庭可能會看見保險的價值。"},{"en":"The value of NPM became clear when farmers saved money and stayed healthier.","zh":"當農民省錢並更健康時，NPM 的價值變得清楚。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":14},{"front":"by 2000","meaning":"到 2000 年","examples":[{"en":"By 2000, all the farmers in Punukala were using NPM.","zh":"到 2000 年，Punukala 所有農民都在使用 NPM。"},{"en":"By 2000 means at or before the year 2000.","zh":"到 2000 年，是指在 2000 年或之前。"},{"en":"By 2020, many schools had started using online learning tools.","zh":"到 2020 年，許多學校已開始使用網上學習工具。"},{"en":"If a change spreads by a certain year, it has already happened before that point.","zh":"如果一個變化到某一年已經傳播開來，意思是它在那個時間點前已經發生。"},{"en":"By 2000 shows when NPM had become normal in the village.","zh":"到 2000 年顯示 NPM 何時在村莊中變得普遍。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":14},{"front":"not only for…but for…as well","meaning":"不但用於……也用於……","examples":[{"en":"Farmers used NPM not only for cotton but for other crops as well.","zh":"農民使用 NPM 不但用於棉花，也用於其他農作物。"},{"en":"Not only for A but for B as well shows that something is used in more than one case.","zh":"不但用於 A 也用於 B，是指某物用於多於一種情況。"},{"en":"The library is useful not only for students but for parents as well.","zh":"圖書館不但對學生有用，也對家長有用。"},{"en":"Exercise helps not only for weight control but for mood as well.","zh":"運動不但有助控制體重，也有助心情。"},{"en":"This structure expands the point by adding another important use.","zh":"這個結構透過加入另一個重要用途來擴展重點。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":15},{"front":"other crops","meaning":"其他農作物","examples":[{"en":"NPM was used for cotton and other crops.","zh":"NPM 被用於棉花和其他農作物。"},{"en":"Other crops are crops besides the one already mentioned.","zh":"其他農作物是指已提及作物以外的作物。"},{"en":"A farmer may grow rice first and other crops after the rainy season.","zh":"農民可能先種稻米，雨季後再種其他農作物。"},{"en":"If a method works on other crops, more farmers may adopt it.","zh":"如果一種方法對其他農作物有效，更多農民可能採用它。"},{"en":"Using NPM on other crops showed that it was not limited to cotton.","zh":"把 NPM 用於其他農作物，顯示它不限於棉花。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":15},{"front":"suicide epidemic","meaning":"自殺潮","examples":[{"en":"The suicide epidemic came to an end.","zh":"自殺潮結束了。"},{"en":"A suicide epidemic means a serious wave of many suicides in a community or region.","zh":"自殺潮是指一個社區或地區出現許多自殺個案的嚴重浪潮。"},{"en":"A debt crisis can contribute to a suicide epidemic among desperate farmers.","zh":"債務危機可能導致絕望農民之間出現自殺潮。"},{"en":"Ending a suicide epidemic requires reducing the pressures that make life feel hopeless.","zh":"結束自殺潮需要減少令人感到絕望的壓力。"},{"en":"In the passage, stopping pesticide dependence helped the suicide epidemic end.","zh":"在篇章中，停止依賴農藥幫助自殺潮結束。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":15},{"front":"come to an end","meaning":"結束","examples":[{"en":"The suicide epidemic came to an end after pesticide use stopped.","zh":"停止使用農藥後，自殺潮結束了。"},{"en":"To come to an end means to finish or stop.","zh":"結束是指完成或停止。"},{"en":"The meeting came to an end after two hours.","zh":"會議兩小時後結束。"},{"en":"A long conflict may come to an end when both sides accept a fair agreement.","zh":"當雙方接受公平協議，長期衝突可能結束。"},{"en":"In the village, a dangerous pattern came to an end when farming changed.","zh":"在村莊中，當耕作方式改變，一種危險模式結束了。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":15},{"front":"stop poisoning themselves","meaning":"停止用農藥毒害自己","examples":[{"en":"The villagers stopped poisoning themselves with pesticides.","zh":"村民停止用農藥毒害自己。"},{"en":"To stop poisoning themselves means to stop exposing themselves to substances that harm their bodies.","zh":"停止毒害自己，是指停止使自己接觸傷害身體的物質。"},{"en":"Workers stopped poisoning themselves when the factory improved ventilation.","zh":"工廠改善通風後，工人停止毒害自己。"},{"en":"Farmers stopped poisoning themselves by replacing toxic sprays with natural methods.","zh":"農民透過用天然方法取代有毒噴劑，停止毒害自己。"},{"en":"This phrase emphasises that the danger came from their own necessary work.","zh":"這個短語強調危險來自他們自己必要的工作。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":15},{"front":"be inspired to start","meaning":"受到啟發去開始","examples":[{"en":"The villagers were inspired to start more community projects.","zh":"村民受到啟發去開始更多社區項目。"},{"en":"To be inspired to start something means to feel encouraged to begin it.","zh":"受到啟發去開始某事，是指感到被鼓勵去展開它。"},{"en":"After seeing a clean-up campaign, students were inspired to start a recycling club.","zh":"看到清潔運動後，學生受到啟發去開始回收學會。"},{"en":"Success in one project can inspire people to start another.","zh":"一個項目的成功可以啟發人們開始另一個項目。"},{"en":"The villagers were inspired to start new projects because NPM gave them confidence.","zh":"村民受到啟發去開始新項目，因為 NPM 給了他們信心。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":15},{"front":"community and business projects","meaning":"社區及商業項目","examples":[{"en":"The villagers started more community and business projects.","zh":"村民開始更多社區及商業項目。"},{"en":"Community and business projects are activities that improve village life or create income.","zh":"社區及商業項目是改善村莊生活或創造收入的活動。"},{"en":"A village market is both a community and business project.","zh":"村莊市場既是社區項目，也是商業項目。"},{"en":"Community and business projects can grow when people trust one another.","zh":"當人們彼此信任時，社區及商業項目可以發展。"},{"en":"After NPM, villagers had the confidence to organise community and business projects.","zh":"NPM 之後，村民有信心組織社區及商業項目。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":15},{"front":"create a new source of income","meaning":"創造新的收入來源","examples":[{"en":"The women created a new source of income by selling neem seeds.","zh":"婦女透過出售印楝種子創造新的收入來源。"},{"en":"To create a new source of income means to find a new way to earn money.","zh":"創造新的收入來源，是指找到新的賺錢方法。"},{"en":"A family may create a new source of income by renting out a room.","zh":"一個家庭可能透過出租房間創造新的收入來源。"},{"en":"Community projects can create a new source of income for people with few jobs.","zh":"社區項目可以為工作機會少的人創造新的收入來源。"},{"en":"Selling neem seeds created income while supporting natural farming.","zh":"出售印楝種子創造收入，同時支持天然農業。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":15},{"front":"collect, grind and sell","meaning":"收集、磨碎並出售","examples":[{"en":"The women collected, ground and sold neem seeds.","zh":"婦女收集、磨碎並出售印楝種子。"},{"en":"To collect, grind and sell something means to gather it, crush it into powder and earn money from it.","zh":"收集、磨碎並出售某物，是指收集它、把它壓成粉末，然後靠它賺錢。"},{"en":"A family may collect, dry and sell herbs at a local market.","zh":"一個家庭可能在本地市場收集、曬乾並出售草藥。"},{"en":"The women added value by grinding seeds before selling them.","zh":"婦女在出售前磨碎種子，從而增加價值。"},{"en":"These actions turned a local tree into a small business.","zh":"這些行動把一棵本地樹變成小生意。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":15},{"front":"in other villages","meaning":"在其他村莊","examples":[{"en":"The women sold neem seeds for NPM in other villages.","zh":"婦女在其他村莊出售用於 NPM 的印楝種子。"},{"en":"In other villages means in villages different from the one already mentioned.","zh":"在其他村莊，是指在已提及村莊以外的村莊。"},{"en":"A successful health campaign may later be repeated in other villages.","zh":"成功的健康宣傳活動之後可能在其他村莊重複。"},{"en":"Selling products in other villages can expand a small business.","zh":"在其他村莊出售產品可以擴大小生意。"},{"en":"NPM spread further when neem seeds were used in other villages.","zh":"當印楝種子在其他村莊使用時，NPM 進一步傳播。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":15},{"front":"rescue indentured children","meaning":"解救受契約束縛的兒童","examples":[{"en":"The villagers rescued their indentured children.","zh":"村民解救了他們受契約束縛的兒童。"},{"en":"To rescue indentured children means to free children trapped in bonded or forced labour.","zh":"解救受契約束縛的兒童，是指釋放被債役或強迫勞動困住的兒童。"},{"en":"A charity may rescue indentured children from dangerous workshops.","zh":"慈善機構可能從危險工場解救受契約束縛的兒童。"},{"en":"Rescuing indentured children allows them to return to learning and family life.","zh":"解救受契約束縛的兒童，讓他們重返學習和家庭生活。"},{"en":"The village’s new confidence helped people rescue children from unfair labour arrangements.","zh":"村莊的新信心幫助人們把兒童從不公平勞動安排中解救出來。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":15},{"front":"indentured children","meaning":"債役兒童；受契約束縛的兒童","examples":[{"en":"Indentured children were given courses to return to school.","zh":"受契約束縛的兒童接受課程以重返校園。"},{"en":"Indentured children are children bound to work, often because of debt or an agreement made by adults.","zh":"債役兒童是被束縛去工作的兒童，通常因債務或成年人訂下的協議所致。"},{"en":"Indentured children may miss school because they must work long hours.","zh":"受契約束縛的兒童可能因必須長時間工作而缺課。"},{"en":"Freeing indentured children can break a cycle of poverty.","zh":"解放受契約束縛的兒童可以打破貧窮循環。"},{"en":"The phrase shows that the children were not simply working by choice.","zh":"這個短語顯示孩子不是單純自願工作。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":16},{"front":"catch-up courses","meaning":"補課課程","examples":[{"en":"The children received six-month catch-up courses.","zh":"這些兒童接受了六個月的補課課程。"},{"en":"Catch-up courses are classes that help learners recover missed knowledge.","zh":"補課課程是幫助學習者補回錯過知識的課堂。"},{"en":"A student who was ill for two months may need catch-up courses.","zh":"生病兩個月的學生可能需要補課課程。"},{"en":"Catch-up courses can help children return to the correct school level.","zh":"補課課程可以幫助孩子回到合適的學校程度。"},{"en":"For rescued children, catch-up courses made school possible again.","zh":"對獲救兒童來說，補課課程令重返校園再次成為可能。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":16},{"front":"return to school","meaning":"重返校園","examples":[{"en":"The catch-up courses helped children return to school.","zh":"補課課程幫助兒童重返校園。"},{"en":"To return to school means to go back to formal education after leaving or missing it.","zh":"重返校園，是指離開或錯過學校教育後回到正式教育。"},{"en":"A child may return to school after recovering from illness.","zh":"孩子病癒後可能重返校園。"},{"en":"Children who work too early need support to return to school.","zh":"太早工作的兒童需要支援才能重返校園。"},{"en":"Returning to school gives children a better chance of future independence.","zh":"重返校園給孩子更好的未來獨立機會。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":16},{"front":"fight against pesticides","meaning":"對抗農藥","examples":[{"en":"The villagers fought against pesticides and won.","zh":"村民對抗農藥並取得勝利。"},{"en":"To fight against pesticides means to resist or campaign against their use.","zh":"對抗農藥，是指抵制或發起行動反對使用農藥。"},{"en":"A community may fight against pollution from a nearby factory.","zh":"社區可能對抗附近工廠造成的污染。"},{"en":"Villagers fight against pesticides when they believe the chemicals harm health and income.","zh":"當村民相信化學品傷害健康和收入時，就會對抗農藥。"},{"en":"Winning such a fight can change both farming and community confidence.","zh":"贏得這場對抗可以改變農業和社區信心。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":16},{"front":"increase village solidarity","meaning":"增強村莊團結","examples":[{"en":"Winning against pesticides increased village solidarity.","zh":"對抗農藥的勝利增強了村莊團結。"},{"en":"To increase village solidarity means to make villagers more united and supportive of one another.","zh":"增強村莊團結，是指令村民更團結並互相支持。"},{"en":"A successful clean-up campaign can increase village solidarity.","zh":"成功的清潔運動可以增強村莊團結。"},{"en":"Shared struggle increases village solidarity because people learn to trust each other.","zh":"共同奮鬥會增強村莊團結，因為人們學會彼此信任。"},{"en":"In Punukala, NPM increased village solidarity by giving everyone a common victory.","zh":"在 Punukala，NPM 透過給所有人共同勝利來增強村莊團結。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":16},{"front":"village solidarity","meaning":"村莊團結","examples":[{"en":"The NPM struggle strengthened village solidarity.","zh":"NPM 奮鬥加強了村莊團結。"},{"en":"Village solidarity is the unity and mutual support among people in a village.","zh":"村莊團結是村民之間的團結和互相支持。"},{"en":"Village solidarity grows when families work together during a crisis.","zh":"當家庭在危機中一起工作，村莊團結會增強。"},{"en":"Strong village solidarity can help people organise projects and defend their interests.","zh":"強大的村莊團結可以幫助人們組織項目並捍衛利益。"},{"en":"Without village solidarity, farmers may face dealers and companies alone.","zh":"沒有村莊團結，農民可能要獨自面對經銷商和公司。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":16},{"front":"self-confidence","meaning":"自信","examples":[{"en":"The success increased villagers’ self-confidence.","zh":"成功增加了村民的自信。"},{"en":"Self-confidence is the belief that one can do something successfully.","zh":"自信是相信自己能成功做到某事。"},{"en":"A student gains self-confidence after giving several successful presentations.","zh":"學生在幾次成功演講後會建立自信。"},{"en":"Community success can build self-confidence because people see their own power.","zh":"社區成功可以建立自信，因為人們看見自己的力量。"},{"en":"The villagers’ self-confidence grew when they solved a serious problem together.","zh":"當村民一起解決嚴重問題時，他們的自信增強。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":16},{"front":"optimism about the future","meaning":"對未來的樂觀","examples":[{"en":"The victory gave villagers optimism about the future.","zh":"這場勝利給村民對未來的樂觀。"},{"en":"Optimism about the future means hope and confidence that life will improve.","zh":"對未來的樂觀，是指相信生活會改善的希望和信心。"},{"en":"A new job can give a family optimism about the future.","zh":"一份新工作可以給一個家庭對未來的樂觀。"},{"en":"When debts fall and health improves, people gain optimism about the future.","zh":"當債務下降而健康改善，人們會獲得對未來的樂觀。"},{"en":"The villagers’ optimism about the future came from real change, not empty words.","zh":"村民對未來的樂觀來自真實改變，而不是空話。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":16},{"front":"punish NPM users by","meaning":"透過……懲罰 NPM 使用者","examples":[{"en":"Dealers tried to punish NPM users by paying less for their cotton.","zh":"經銷商試圖透過為棉花支付較低價格來懲罰 NPM 使用者。"},{"en":"To punish someone by doing something means to harm or disadvantage them as a response.","zh":"透過做某事懲罰某人，是指以傷害或使他們處於不利作為回應。"},{"en":"A shop may punish late payers by charging extra fees.","zh":"商店可能透過收取額外費用來懲罰遲付款者。"},{"en":"Dealers punished NPM users by offering lower prices, hoping they would return to pesticides.","zh":"經銷商透過開較低價格懲罰 NPM 使用者，希望他們回到農藥。"},{"en":"Such punishment can push people to organise together.","zh":"這種懲罰可以推動人們一起組織起來。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":16},{"front":"pay less for","meaning":"為……支付較低價格","examples":[{"en":"Dealers paid less for NPM cotton.","zh":"經銷商為 NPM 棉花支付較低價格。"},{"en":"To pay less for something means to offer or spend a smaller amount of money for it.","zh":"為某物支付較低價格，是指為它開出或花費較少金錢。"},{"en":"Customers pay less for fruit near closing time at the market.","zh":"顧客在市場快關門時為水果支付較低價格。"},{"en":"If buyers pay less for a farmer’s crop, the farmer’s income falls.","zh":"如果買家為農民的作物支付較低價格，農民收入會下降。"},{"en":"Dealers paid less for NPM cotton to discourage farmers from using the new method.","zh":"經銷商為 NPM 棉花支付較低價格，以阻止農民使用新方法。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":16},{"front":"unite to form","meaning":"團結起來成立","examples":[{"en":"The farmers united to form a marketing cooperative.","zh":"農民團結起來成立銷售合作社。"},{"en":"To unite to form something means to join together in order to create it.","zh":"團結起來成立某物，是指一起加入並創建它。"},{"en":"Parents united to form a school safety group.","zh":"家長團結起來成立學校安全小組。"},{"en":"Small shops may unite to form a local business association.","zh":"小店可能團結起來成立本地商業協會。"},{"en":"Farmers united to form a cooperative because they needed stronger bargaining power.","zh":"農民團結起來成立合作社，因為他們需要更強的議價能力。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":16},{"front":"marketing cooperative","meaning":"銷售合作社","examples":[{"en":"The farmers formed a marketing cooperative to find better prices.","zh":"農民成立銷售合作社來尋找更好的價格。"},{"en":"A marketing cooperative is a group that helps members sell products together.","zh":"銷售合作社是幫助成員一起出售產品的組織。"},{"en":"Farmers may use a marketing cooperative to reach larger buyers.","zh":"農民可能利用銷售合作社接觸更大型買家。"},{"en":"A marketing cooperative can give small producers more power in the market.","zh":"銷售合作社可以給小生產者在市場上更大力量。"},{"en":"The cooperative helped farmers avoid unfair prices from local dealers.","zh":"合作社幫助農民避免本地經銷商的不公平價格。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":17},{"front":"fairer prices","meaning":"較公平的價格","examples":[{"en":"The cooperative found fairer prices elsewhere.","zh":"合作社在其他地方找到較公平的價格。"},{"en":"Fairer prices are prices that treat sellers or buyers more justly.","zh":"較公平的價格，是指更公正對待賣方或買方的價格。"},{"en":"Farmers want fairer prices when their work is not properly rewarded.","zh":"當農民的工作沒有得到應有回報時，他們想要較公平的價格。"},{"en":"Fairer prices can help families pay debts and improve daily life.","zh":"較公平的價格可以幫助家庭還債並改善日常生活。"},{"en":"A cooperative can search for fairer prices by comparing different buyers.","zh":"合作社可以透過比較不同買家尋找較公平的價格。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":17},{"front":"elsewhere","meaning":"在其他地方","examples":[{"en":"The farmers found fairer prices elsewhere.","zh":"農民在其他地方找到較公平的價格。"},{"en":"Elsewhere means in another place or in other places.","zh":"在其他地方，是指在另一個地方或其他地方。"},{"en":"If one shop is closed, customers may buy food elsewhere.","zh":"如果一間店關門，顧客可能在其他地方買食物。"},{"en":"Farmers looked elsewhere when local dealers offered unfair prices.","zh":"當本地經銷商開出不公平價格，農民便在其他地方尋找。"},{"en":"This word shows that the solution was not found in the original place.","zh":"這個詞顯示解決方法不是在原來地方找到的。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":17},{"front":"leadership skills","meaning":"領導能力","examples":[{"en":"The NPM struggle helped villagers develop leadership skills.","zh":"NPM 奮鬥幫助村民發展領導能力。"},{"en":"Leadership skills are abilities that help people guide, organise and encourage others.","zh":"領導能力是幫助人引導、組織和鼓勵他人的能力。"},{"en":"A student develops leadership skills by organising a class project.","zh":"學生透過組織班級項目發展領導能力。"},{"en":"Community challenges can build leadership skills because someone must coordinate action.","zh":"社區挑戰可以建立領導能力，因為需要有人協調行動。"},{"en":"Villagers used leadership skills to solve problems beyond pesticides.","zh":"村民利用領導能力解決農藥以外的問題。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":17},{"front":"collaboration skills","meaning":"協作能力","examples":[{"en":"The villagers developed collaboration skills during the NPM struggle.","zh":"村民在 NPM 奮鬥中發展了協作能力。"},{"en":"Collaboration skills are abilities that help people work well together.","zh":"協作能力是幫助人們良好合作的能力。"},{"en":"Group projects help students practise collaboration skills.","zh":"小組項目幫助學生練習協作能力。"},{"en":"Collaboration skills improve when people share tasks and listen to different views.","zh":"當人們分工並聆聽不同意見時，協作能力會提升。"},{"en":"The villagers needed collaboration skills to form a cooperative and run projects.","zh":"村民需要協作能力來成立合作社和運作項目。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":17},{"front":"take on other challenges","meaning":"應對其他挑戰","examples":[{"en":"The villagers used their new skills to take on other challenges.","zh":"村民利用新技能應對其他挑戰。"},{"en":"To take on other challenges means to face and try to solve additional difficult problems.","zh":"應對其他挑戰，是指面對並嘗試解決額外的困難問題。"},{"en":"After improving reading, a student may take on other challenges in writing.","zh":"改善閱讀後，學生可能應對寫作中的其他挑戰。"},{"en":"A community that solves one problem may feel ready to take on other challenges.","zh":"解決一個問題的社區，可能覺得準備好應對其他挑戰。"},{"en":"The phrase shows growth from one victory to broader action.","zh":"這個短語顯示從一次勝利成長到更廣泛的行動。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":17},{"front":"water purification","meaning":"水淨化","examples":[{"en":"The villagers worked on water purification after their NPM success.","zh":"NPM 成功後，村民致力於水淨化。"},{"en":"Water purification is the process of making water clean and safe to use.","zh":"水淨化是令水變得乾淨並可安全使用的過程。"},{"en":"Boiling and filtering are simple forms of water purification.","zh":"煮沸和過濾是簡單的水淨化形式。"},{"en":"Water purification can prevent disease when wells or rivers are polluted.","zh":"當井水或河流受污染時，水淨化可以預防疾病。"},{"en":"The village moved from pesticide reform to another health-related project: water purification.","zh":"村莊從農藥改革轉向另一個與健康相關的項目：水淨化。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":17},{"front":"cotton gin","meaning":"軋棉機","examples":[{"en":"The village planned to build a cotton gin.","zh":"村莊計劃建造一部軋棉機。"},{"en":"A cotton gin is a machine that separates cotton fibres from seeds.","zh":"軋棉機是把棉花纖維與種子分離的機器。"},{"en":"Farmers can sell cotton for more if a cotton gin prepares it better.","zh":"如果軋棉機把棉花處理得更好，農民可以以更高價格出售。"},{"en":"Building a cotton gin can help a village keep more value locally.","zh":"建造軋棉機可以幫助村莊在本地保留更多價值。"},{"en":"The cotton gin project showed that farmers wanted more control over production.","zh":"軋棉機項目顯示農民希望對生產有更多控制。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":17},{"front":"add value to","meaning":"為……增值","examples":[{"en":"A cotton gin can add value to cotton before it is sold.","zh":"軋棉機可以在棉花出售前為它增值。"},{"en":"To add value to something means to make it more useful, attractive or profitable.","zh":"為某物增值，是指令它更有用、更吸引或更有利可圖。"},{"en":"Packaging fruit neatly can add value to it in the market.","zh":"把水果包裝整齊可以在市場上為它增值。"},{"en":"Training can add value to workers by improving their skills.","zh":"培訓可以透過提升技能為工人增值。"},{"en":"A cotton gin adds value to cotton by processing it before sale.","zh":"軋棉機透過在出售前處理棉花，為棉花增值。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":17},{"front":"convince someone to","meaning":"說服某人去","examples":[{"en":"The villagers tried to convince the state government to support NPM.","zh":"村民嘗試說服邦政府支持 NPM。"},{"en":"To convince someone to do something means to persuade them to do it.","zh":"說服某人去做某事，是指使他們願意做那件事。"},{"en":"A student may convince parents to allow more study time at the library.","zh":"學生可能說服父母讓自己有更多時間在圖書館學習。"},{"en":"Clear evidence can convince officials to change a policy.","zh":"清楚證據可以說服官員改變政策。"},{"en":"The villagers needed results to convince the government to support NPM.","zh":"村民需要成果來說服政府支持 NPM。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":17},{"front":"state government","meaning":"邦政府","examples":[{"en":"The villagers wanted the state government to support NPM.","zh":"村民希望邦政府支持 NPM。"},{"en":"A state government is the government of a state within a country.","zh":"邦政府是一個國家內某個邦的政府。"},{"en":"A state government may manage agriculture, education and local development.","zh":"邦政府可能管理農業、教育和本地發展。"},{"en":"Farmers often need support from the state government to expand a successful method.","zh":"農民常需要邦政府支持，才能擴大成功方法。"},{"en":"State government support can turn a village practice into a wider policy.","zh":"邦政府支持可以把村莊做法變成更廣泛的政策。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":17},{"front":"support NPM over","meaning":"支持 NPM 而非……","examples":[{"en":"The villagers convinced the government to support NPM over pesticide corporations’ objections.","zh":"村民說服政府儘管農藥企業反對，仍支持 NPM。"},{"en":"To support NPM over something else means to choose NPM instead of the competing option or pressure.","zh":"支持 NPM 而非其他東西，是指選擇 NPM，而不是競爭選項或壓力。"},{"en":"A school may support healthy meals over cheaper junk food.","zh":"學校可能支持健康膳食，而非較便宜的垃圾食物。"},{"en":"Officials supported the village method over company pressure because results were strong.","zh":"官員支持村莊方法而非公司壓力，因為成果很強。"},{"en":"This phrase shows a choice between public benefit and corporate opposition.","zh":"這個短語顯示公共利益與企業反對之間的選擇。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":18},{"front":"over the objection of","meaning":"儘管……反對","examples":[{"en":"The government was asked to support NPM over the objection of pesticide corporations.","zh":"村民要求政府儘管農藥企業反對，仍支持 NPM。"},{"en":"Over the objection of someone means despite that person or group opposing it.","zh":"儘管某人反對，是指即使那個人或群體反對仍然做。"},{"en":"The council approved the park over the objection of some shop owners.","zh":"議會儘管一些店主反對，仍批准公園計劃。"},{"en":"A school may change its timetable over the objection of a few parents.","zh":"學校可能儘管少數家長反對，仍改變時間表。"},{"en":"Supporting NPM over the objection of pesticide corporations required political courage.","zh":"儘管農藥企業反對仍支持 NPM，需要政治勇氣。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":18},{"front":"pesticide corporations","meaning":"農藥企業","examples":[{"en":"Multinational pesticide corporations objected to NPM.","zh":"跨國農藥企業反對 NPM。"},{"en":"Pesticide corporations are large companies that produce or sell pesticides.","zh":"農藥企業是生產或銷售農藥的大型公司。"},{"en":"Pesticide corporations may lose sales if farmers stop using chemicals.","zh":"如果農民停止使用化學品，農藥企業可能失去銷售額。"},{"en":"Farmers need independent information because pesticide corporations have business interests.","zh":"農民需要獨立資訊，因為農藥企業有商業利益。"},{"en":"In the passage, pesticide corporations opposed a method that reduced chemical use.","zh":"在篇章中，農藥企業反對一種減少化學品使用的方法。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":18},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"Students decide whether the following statements agree with the passage.","zh":"學生判斷以下陳述是否與篇章一致。"},{"en":"Do the following statements agree with asks whether each statement matches the text.","zh":"以下陳述是否與……一致，是問每句陳述是否配合文本內容。"},{"en":"In IELTS reading, students check whether statements agree with the writer’s information.","zh":"在 IELTS 閱讀中，學生檢查陳述是否與作者資料一致。"},{"en":"A statement agrees with the passage when it says the same thing as the text.","zh":"當陳述與文本說同一件事，它就與篇章一致。"},{"en":"This question type tests careful reading, not personal opinion.","zh":"這種題型測試仔細閱讀，而不是個人意見。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":18},{"front":"information given in","meaning":"在……中給出的資料","examples":[{"en":"The answers must agree with the information given in the passage.","zh":"答案必須與篇章中給出的資料一致。"},{"en":"Information given in a text means the facts or details stated there.","zh":"在文本中給出的資料，是指那裡陳述的事實或細節。"},{"en":"Students should answer according to the information given in the article.","zh":"學生應根據文章中給出的資料作答。"},{"en":"If information is not given in the passage, students should not guess.","zh":"如果篇章中沒有給出資料，學生不應猜測。"},{"en":"This phrase reminds learners to stay close to the source text.","zh":"這個短語提醒學習者要緊扣來源文本。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":18},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與篇章中的資料相矛盾。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"與資料相矛盾，是指說出與文本相反的內容。"},{"en":"If the article says sales rose, a statement saying sales fell contradicts the information.","zh":"如果文章說銷售上升，而陳述說銷售下降，那就與資料相矛盾。"},{"en":"Students choose False when the statement contradicts the information clearly.","zh":"當陳述清楚與資料相矛盾時，學生選 False。"},{"en":"Contradiction is different from missing information.","zh":"矛盾不同於資料缺失。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":18},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"Students choose NOT GIVEN when there is no information on this.","zh":"當沒有相關資料時，學生選擇 NOT GIVEN。"},{"en":"No information on this means the text does not say whether the point is true or false.","zh":"沒有相關資料，是指文本沒有說明該點是真或假。"},{"en":"If a passage names a farmer but not his age, there is no information on this.","zh":"如果篇章說出農民姓名但沒有說年齡，就沒有相關資料。"},{"en":"Students should not use outside knowledge when there is no information on this.","zh":"當沒有相關資料時，學生不應使用外部知識。"},{"en":"This phrase helps explain the meaning of NOT GIVEN.","zh":"這個短語有助解釋 NOT GIVEN 的意思。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":18},{"front":"bring local farmers more income","meaning":"為本地農民帶來更多收入","examples":[{"en":"Cotton could bring local farmers more income than traditional crops.","zh":"棉花可以比傳統農作物為本地農民帶來更多收入。"},{"en":"To bring local farmers more income means to help nearby farmers earn more money.","zh":"為本地農民帶來更多收入，是指幫助附近農民賺更多錢。"},{"en":"A new market may bring local farmers more income by giving them more buyers.","zh":"新市場可以透過提供更多買家，為本地農民帶來更多收入。"},{"en":"A crop that brings local farmers more income may quickly become popular.","zh":"能為本地農民帶來更多收入的作物，可能很快變得受歡迎。"},{"en":"Higher income is attractive, but it does not remove farming risks.","zh":"較高收入很吸引，但不會消除農業風險。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":18},{"front":"traditional crops","meaning":"傳統農作物","examples":[{"en":"Traditional crops included millet, sorghum, groundnuts and rice.","zh":"傳統農作物包括小米、高粱、花生和稻米。"},{"en":"Traditional crops are crops that farmers in an area have grown for a long time.","zh":"傳統農作物是某地農民長期種植的作物。"},{"en":"Traditional crops often match local food habits and climate.","zh":"傳統農作物通常配合本地飲食習慣和氣候。"},{"en":"Replacing traditional crops with one cash crop can increase risk.","zh":"用單一經濟作物取代傳統農作物可能增加風險。"},{"en":"Traditional crops may bring less cash but provide food security.","zh":"傳統農作物可能帶來較少現金，但提供糧食安全。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":18},{"front":"cotton cultivation was introduced","meaning":"棉花種植被引入","examples":[{"en":"Cotton cultivation was introduced to Punukala by outsiders.","zh":"棉花種植由外來者引入 Punukala。"},{"en":"Cotton cultivation was introduced means cotton growing was brought into a place for the first time or newly adopted there.","zh":"棉花種植被引入，是指棉花耕作首次或新近被帶入某地。"},{"en":"A new crop was introduced to the village when migrants arrived.","zh":"當移民到來時，一種新作物被引入村莊。"},{"en":"When cotton cultivation was introduced, farmers changed from mixed crops to a cash crop.","zh":"棉花種植被引入後，農民從混合農作物轉向經濟作物。"},{"en":"This phrase focuses on how a new practice entered the community.","zh":"這個短語聚焦一種新做法如何進入社區。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":18},{"front":"relatively lower than","meaning":"相對低於","examples":[{"en":"The question asks whether cotton yields were relatively lower than other crops.","zh":"題目問棉花產量是否相對低於其他作物。"},{"en":"Relatively lower than means lower when compared with something else.","zh":"相對低於，是指與其他事物比較時較低。"},{"en":"The price is relatively lower than nearby shops, so more customers visit.","zh":"價格相對低於附近商店，所以更多顧客到訪。"},{"en":"A score may be relatively lower than last year even if it is not very low.","zh":"分數可能相對低於去年，即使它本身不是很低。"},{"en":"This phrase always needs a comparison point.","zh":"這個短語總需要一個比較點。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":18},{"front":"other agricultural crops","meaning":"其他農作物","examples":[{"en":"The question compares cotton with other agricultural crops.","zh":"題目把棉花與其他農作物作比較。"},{"en":"Other agricultural crops are farm crops besides the one being discussed.","zh":"其他農作物是指正在討論的作物以外的農場作物。"},{"en":"Rice, beans and vegetables can be other agricultural crops compared with cotton.","zh":"與棉花相比，稻米、豆類和蔬菜都可以是其他農作物。"},{"en":"Farmers compare profits from cotton with other agricultural crops before deciding what to plant.","zh":"農民在決定種甚麼前，會比較棉花與其他農作物的利潤。"},{"en":"This phrase helps set up a farming comparison.","zh":"這個短語有助建立農業比較。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":19},{"front":"realise how quickly","meaning":"意識到……有多快","examples":[{"en":"The farmers did not realise how quickly pests would spread.","zh":"農民沒有意識到害蟲會蔓延得多快。"},{"en":"To realise how quickly something happens means to understand its speed.","zh":"意識到某事發生得多快，是指理解它的速度。"},{"en":"New students may not realise how quickly exam deadlines arrive.","zh":"新生可能沒有意識到考試期限來得多快。"},{"en":"Farmers realised how quickly insects could multiply only after the fields were damaged.","zh":"農民只有在田地受損後，才意識到昆蟲可以繁殖得多快。"},{"en":"This phrase often shows that people underestimated a risk.","zh":"這個短語常顯示人們低估了風險。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":19},{"front":"pests would spread","meaning":"害蟲會蔓延","examples":[{"en":"Farmers were surprised by how quickly pests would spread.","zh":"農民對害蟲會蔓延得多快感到驚訝。"},{"en":"Pests would spread means harmful insects or organisms would move and increase across an area.","zh":"害蟲會蔓延，是指有害昆蟲或生物會在某地移動並增加。"},{"en":"Without control, pests would spread from one field to the next.","zh":"如果沒有控制，害蟲會從一塊田蔓延到下一塊田。"},{"en":"Warm weather can make pests spread faster.","zh":"溫暖天氣可以令害蟲蔓延得更快。"},{"en":"Understanding how pests would spread helps farmers act early.","zh":"理解害蟲會如何蔓延，有助農民及早行動。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":19},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Students complete the summary below using words from the passage.","zh":"學生使用篇章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in missing information in the short text that follows.","zh":"完成以下摘要，是指填寫接下來短文中缺失的資料。"},{"en":"In a reading test, students complete the summary below with exact words from the article.","zh":"在閱讀測驗中，學生用文章中的原字完成以下摘要。"},{"en":"This task checks whether students understand the main process or idea.","zh":"這項任務檢查學生是否理解主要過程或想法。"},{"en":"Students should read the summary grammar carefully before choosing words.","zh":"學生在選字前應仔細閱讀摘要文法。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":19},{"front":"no more than two words","meaning":"不多於兩個字","examples":[{"en":"The answers should use no more than two words from the passage.","zh":"答案應使用篇章中不多於兩個字。"},{"en":"No more than two words means one word or two words, but not three.","zh":"不多於兩個字，是指一個字或兩個字，但不是三個字。"},{"en":"If the instruction says no more than two words, “neem seeds” is acceptable but “the neem seeds” may be too long.","zh":"如果指示寫不多於兩個字，neem seeds 可以接受，但 the neem seeds 可能太長。"},{"en":"Students lose marks when they write more words than the limit allows.","zh":"當學生寫超過字數限制，就會失分。"},{"en":"This instruction tests accuracy as well as understanding.","zh":"這項指示同時測試準確度和理解。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":19},{"front":"from the passage","meaning":"從篇章中選取","examples":[{"en":"The answers must be chosen from the passage.","zh":"答案必須從篇章中選取。"},{"en":"From the passage means taken directly from the reading text.","zh":"從篇章中選取，是指直接取自閱讀文本。"},{"en":"Students should copy the answer from the passage, not invent a synonym.","zh":"學生應從篇章中抄寫答案，而不是自己創造同義詞。"},{"en":"If the answer is from the passage, spelling must match the text.","zh":"如果答案來自篇章，拼寫必須符合文本。"},{"en":"This phrase reminds students not to use outside knowledge.","zh":"這個短語提醒學生不要使用外部知識。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":19},{"front":"making a natural pesticide","meaning":"製作天然農藥","examples":[{"en":"The summary explains the process of making a natural pesticide.","zh":"摘要解釋製作天然農藥的過程。"},{"en":"Making a natural pesticide means preparing a pest-control substance from natural materials.","zh":"製作天然農藥，是指用天然材料準備控蟲物質。"},{"en":"Farmers may begin making a natural pesticide by collecting useful seeds or leaves.","zh":"農民可能透過收集有用種子或葉子開始製作天然農藥。"},{"en":"Making a natural pesticide can reduce the need to buy chemical sprays.","zh":"製作天然農藥可以減少購買化學噴劑的需要。"},{"en":"In the passage, making a natural pesticide involves grinding neem seeds and soaking them.","zh":"在篇章中，製作天然農藥涉及磨碎印楝種子並浸泡它們。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":19},{"front":"broad-leaved neem tree","meaning":"闊葉印楝樹","examples":[{"en":"The broad-leaved neem tree produces natural pesticides.","zh":"闊葉印楝樹產生天然農藥。"},{"en":"A broad-leaved neem tree is a neem tree with wide leaves that stays green through the year.","zh":"闊葉印楝樹是有寬闊葉片並全年常綠的印楝樹。"},{"en":"Farmers value the broad-leaved neem tree because its seeds can be used for pest control.","zh":"農民重視闊葉印楝樹，因為它的種子可用於控蟲。"},{"en":"A broad-leaved neem tree can provide both shade and useful farming material.","zh":"闊葉印楝樹可以提供樹蔭，也提供有用的農業材料。"},{"en":"The phrase helps describe the plant clearly for readers.","zh":"這個短語幫助讀者清楚描述這種植物。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":19},{"front":"fast-growing tree","meaning":"生長迅速的樹","examples":[{"en":"A fast-growing tree can be useful in sustainable farming.","zh":"生長迅速的樹在可持續農業中可能很有用。"},{"en":"A fast-growing tree is a tree that reaches useful size quickly.","zh":"生長迅速的樹，是指很快長到有用大小的樹。"},{"en":"Farmers may plant a fast-growing tree for shade, fuel or soil protection.","zh":"農民可能種植生長迅速的樹，用作樹蔭、燃料或保護泥土。"},{"en":"A fast-growing tree can provide benefits sooner than a slow-growing tree.","zh":"生長迅速的樹比生長慢的樹更快提供好處。"},{"en":"Fast-growing trees are useful when communities need quick, local resources.","zh":"當社區需要快速而本地的資源時，生長迅速的樹很有用。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":19},{"front":"produce natural pesticides","meaning":"產生天然農藥","examples":[{"en":"The neem tree produces natural pesticides.","zh":"印楝樹產生天然農藥。"},{"en":"To produce natural pesticides means to make substances from nature that can control pests.","zh":"產生天然農藥，是指製造來自自然、能控制害蟲的物質。"},{"en":"Some plants produce natural pesticides to protect their leaves.","zh":"有些植物產生天然農藥來保護自己的葉子。"},{"en":"If a tree produces natural pesticides, farmers can use it as a local pest-control resource.","zh":"如果一棵樹產生天然農藥，農民就能把它用作本地控蟲資源。"},{"en":"Neem is important because it produces natural pesticides in several forms.","zh":"印楝很重要，因為它以幾種形式產生天然農藥。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":19},{"front":"act as insect repellents","meaning":"作為驅蟲劑","examples":[{"en":"Neem substances act as insect repellents.","zh":"印楝物質作為驅蟲劑。"},{"en":"To act as insect repellents means to keep insects away.","zh":"作為驅蟲劑，是指把昆蟲趕走。"},{"en":"Some plant smells act as insect repellents in kitchens and gardens.","zh":"有些植物氣味在廚房和花園中作為驅蟲劑。"},{"en":"If a spray acts as an insect repellent, insects are less likely to lay eggs there.","zh":"如果噴劑作為驅蟲劑，昆蟲就較不可能在那裡產卵。"},{"en":"Neem can protect crops because some of its chemicals act as insect repellents.","zh":"印楝可以保護農作物，因為它的一些化學物質作為驅蟲劑。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":19},{"front":"insect repellents","meaning":"驅蟲劑","examples":[{"en":"Neem can be used as an insect repellent.","zh":"印楝可以用作驅蟲劑。"},{"en":"Insect repellents are substances that keep insects away.","zh":"驅蟲劑是令昆蟲遠離的物質。"},{"en":"People may use insect repellents before walking in a mosquito-filled area.","zh":"人們在走進多蚊地區前可能使用驅蟲劑。"},{"en":"Insect repellents reduce bites or crop damage by discouraging insects from coming close.","zh":"驅蟲劑透過阻止昆蟲接近，減少叮咬或農作物損害。"},{"en":"Natural insect repellents may be made from plant oils or extracts.","zh":"天然驅蟲劑可能由植物油或提取物製成。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":20},{"front":"be crushed into","meaning":"被壓碎成","examples":[{"en":"Neem seeds are crushed into powder.","zh":"印楝種子被壓碎成粉末。"},{"en":"To be crushed into something means to be pressed or broken until it becomes that form.","zh":"被壓碎成某物，是指被擠壓或打碎直到變成該形態。"},{"en":"Biscuits can be crushed into crumbs for a dessert base.","zh":"餅乾可以被壓碎成碎屑，用作甜品底。"},{"en":"Seeds are crushed into powder so their useful substances can mix with water.","zh":"種子被壓碎成粉末，使其中有用物質能與水混合。"},{"en":"In the neem process, crushing makes the seeds easier to use.","zh":"在印楝製作過程中，壓碎使種子更容易使用。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":20},{"front":"soaked in water","meaning":"浸泡在水中","examples":[{"en":"The powder is soaked in water overnight.","zh":"粉末在水中浸泡一夜。"},{"en":"Soaked in water means left in water for a period of time.","zh":"浸泡在水中，是指在水裡放置一段時間。"},{"en":"Rice may be soaked in water before cooking.","zh":"米在烹煮前可能會浸泡在水中。"},{"en":"When powder is soaked in water, useful substances can enter the liquid.","zh":"當粉末浸泡在水中，有用物質可以進入液體。"},{"en":"Neem powder is soaked in water to prepare the natural pesticide solution.","zh":"印楝粉末浸泡在水中，以準備天然農藥溶液。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":20},{"front":"the resulting solution","meaning":"所得溶液","examples":[{"en":"The resulting solution is sprayed onto the crop.","zh":"所得溶液被噴灑到農作物上。"},{"en":"The resulting solution means the liquid produced after the previous steps.","zh":"所得溶液，是指完成前面步驟後產生的液體。"},{"en":"After salt is mixed with water, the resulting solution tastes salty.","zh":"鹽與水混合後，所得溶液有鹹味。"},{"en":"In a recipe, the resulting mixture is what you get after combining ingredients.","zh":"在食譜中，所得混合物就是把材料混合後得到的東西。"},{"en":"In the neem process, the resulting solution is the liquid used on crops.","zh":"在印楝過程中，所得溶液就是用於農作物的液體。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":20},{"front":"eliminate pests and diseases","meaning":"清除害蟲及病害","examples":[{"en":"Neem cake can eliminate pests and diseases in the soil.","zh":"印楝餅可以清除泥土中的害蟲及病害。"},{"en":"To eliminate pests and diseases means to remove or kill harmful organisms and infections.","zh":"清除害蟲及病害，是指移除或殺死有害生物和感染。"},{"en":"Farmers may rotate crops to eliminate pests and diseases over time.","zh":"農民可能透過輪作逐漸清除害蟲及病害。"},{"en":"If pests and diseases are eliminated, plants have a better chance to grow well.","zh":"如果害蟲及病害被清除，植物就有更好機會健康生長。"},{"en":"Neem cake helps eliminate pests and diseases below the soil surface.","zh":"印楝餅幫助清除泥土表面以下的害蟲及病害。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":20},{"front":"increase the level of","meaning":"提高……水平","examples":[{"en":"Neem cake increases the level of nitrogen in the soil.","zh":"印楝餅提高泥土中的氮水平。"},{"en":"To increase the level of something means to make the amount of it higher.","zh":"提高某物水平，是指令它的數量或程度上升。"},{"en":"Exercise can increase the level of energy people feel during the day.","zh":"運動可以提高人們白天感到的精力水平。"},{"en":"Fertiliser can increase the level of nutrients in poor soil.","zh":"肥料可以提高貧瘠泥土中的養分水平。"},{"en":"Neem cake improves soil partly by increasing the level of nitrogen.","zh":"印楝餅部分透過提高氮水平改善泥土。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":20},{"front":"answer the questions below","meaning":"回答以下問題","examples":[{"en":"Students answer the questions below using words from the passage.","zh":"學生使用篇章中的字詞回答以下問題。"},{"en":"Answer the questions below means write responses to the questions that follow.","zh":"回答以下問題，是指為接下來的問題寫答案。"},{"en":"In an exam, students should read the passage before they answer the questions below.","zh":"在考試中，學生應先閱讀篇章，再回答以下問題。"},{"en":"This instruction tells students where to put their attention next.","zh":"這項指示告訴學生接下來要把注意力放在哪裡。"},{"en":"Students must follow the word limit when they answer the questions below.","zh":"學生回答以下問題時，必須遵守字數限制。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":20},{"front":"no more than two words and/or a number","meaning":"不多於兩個字及／或一個數字","examples":[{"en":"The answer should use no more than two words and/or a number.","zh":"答案應使用不多於兩個字及／或一個數字。"},{"en":"No more than two words and/or a number means the answer may contain up to two words plus a number if needed.","zh":"不多於兩個字及／或一個數字，是指答案可包含最多兩個字，並在需要時加一個數字。"},{"en":"“six months” fits the rule because it has a number and one word.","zh":"“six months” 符合規則，因為它有一個數字和一個字。"},{"en":"Students should not write a full sentence when the limit is no more than two words and/or a number.","zh":"當限制是不多於兩個字及／或一個數字時，學生不應寫完整句子。"},{"en":"This instruction helps examiners check exact answers quickly.","zh":"這項指示幫助考官快速檢查準確答案。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":20},{"front":"in which year","meaning":"在哪一年","examples":[{"en":"The question asks in which year all farmers used NPM.","zh":"題目問所有農民在哪一年使用 NPM。"},{"en":"In which year asks for the specific year when something happened.","zh":"在哪一年，是詢問某事發生的具體年份。"},{"en":"In which year did the school open?","zh":"這間學校在哪一年開辦？"},{"en":"Students should answer with a year, not a long explanation.","zh":"學生應用年份作答，而不是長篇解釋。"},{"en":"In the passage, the relevant answer is found by locating the time reference.","zh":"在篇章中，相關答案要透過找出時間提示來取得。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":20},{"front":"on their crops","meaning":"在他們的農作物上","examples":[{"en":"All farmers used NPM on their crops.","zh":"所有農民都在他們的農作物上使用 NPM。"},{"en":"On their crops means applied to or used for the plants they were growing.","zh":"在他們的農作物上，是指施用或用於他們正在種植的植物。"},{"en":"Farmers sprayed the natural solution on their crops after preparing it.","zh":"農民準備好天然溶液後，把它噴灑在他們的農作物上。"},{"en":"Using a method on their crops affects both harvest and income.","zh":"在農作物上使用一種方法，會影響收成和收入。"},{"en":"This phrase tells us where the farming method was applied.","zh":"這個短語告訴我們耕作方法被施用在哪裡。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":20},{"front":"NPM-related business opportunity","meaning":"與 NPM 相關的商機","examples":[{"en":"Selling neem seeds created an NPM-related business opportunity.","zh":"出售印楝種子創造了與 NPM 相關的商機。"},{"en":"An NPM-related business opportunity is a chance to earn money from activities connected to Non-Pesticide Management.","zh":"與 NPM 相關的商機，是指從與非農藥管理有關的活動中賺錢的機會。"},{"en":"Grinding neem seeds for other farmers became an NPM-related business opportunity.","zh":"為其他農民磨碎印楝種子，成為與 NPM 相關的商機。"},{"en":"When a farming method spreads, related services can create new income.","zh":"當一種耕作方法傳播，相關服務可以創造新收入。"},{"en":"The women’s neem-seed work shows how environmental change can also create business opportunities.","zh":"婦女的印楝種子工作顯示，環境改變也可以創造商機。"}],"source":"157 - Natural pesticide in India.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 158":[{"front":"travel accounts","meaning":"旅行記錄；遊記","examples":[{"en":"Travel accounts give valuable information about foreign lands.","zh":"旅行記錄提供有關外地的寶貴資料。"},{"en":"Travel accounts are written descriptions of journeys, places, people, and cultures.","zh":"旅行記錄是對旅程、地方、人物和文化的書面描述。"},{"en":"A student may read travel accounts to understand how people lived in another country.","zh":"學生可以閱讀旅行記錄，了解另一個國家的人如何生活。"},{"en":"Travel accounts can preserve details about food, clothing, roads, and customs that official records miss.","zh":"旅行記錄可以保存官方記錄忽略的食物、衣着、道路和習俗細節。"},{"en":"Some travel accounts teach us about foreign places, but they also reveal the writer’s own views.","zh":"有些旅行記錄教我們認識外地，但也反映作者本身的看法。"}],"source":"158 - Travel Accounts.pdf","sourcePage":1},{"front":"there are many reasons why","meaning":"有很多原因解釋為甚麼","examples":[{"en":"There are many reasons why individuals have travelled beyond their own societies.","zh":"有很多原因解釋為甚麼個人會到自己所屬社會以外旅行。"},{"en":"There are many reasons why means that several different explanations are possible.","zh":"there are many reasons why 表示可能有幾個不同解釋。"},{"en":"There are many reasons why students choose different subjects, such as interest, ability, and future plans.","zh":"有很多原因解釋為甚麼學生選擇不同科目，例如興趣、能力和未來計劃。"},{"en":"There are many reasons why a shop may close early, including bad weather or staff shortages.","zh":"有很多原因解釋為甚麼商店可能提早關門，包括惡劣天氣或人手短缺。"},{"en":"This phrase is useful when one simple explanation is not enough.","zh":"當一個簡單解釋不足夠時，這個短語很有用。"}],"source":"158 - Travel Accounts.pdf","sourcePage":1},{"front":"travel beyond","meaning":"到……以外旅行","examples":[{"en":"Individuals have travelled beyond their own societies for many reasons.","zh":"個人因很多原因到自己所屬社會以外旅行。"},{"en":"To travel beyond a place means to go outside its usual area or limits.","zh":"travel beyond 某地表示到該地方的通常範圍或界限以外旅行。"},{"en":"Some students travel beyond their hometown to attend university.","zh":"有些學生到家鄉以外旅行，去上大學。"},{"en":"Better transport allows workers to travel beyond nearby districts for jobs.","zh":"更好的交通讓工人可以到附近地區以外找工作。"},{"en":"People may travel beyond familiar places to find trade, safety, education, or adventure.","zh":"人們可能到熟悉地方以外旅行，尋找貿易、安全、教育或冒險機會。"}],"source":"158 - Travel Accounts.pdf","sourcePage":1},{"front":"one’s own society","meaning":"自己所屬的社會","examples":[{"en":"Travellers often leave their own society to visit foreign lands.","zh":"旅行者常離開自己所屬的社會，到外地遊歷。"},{"en":"One’s own society means the community, country, or culture a person belongs to.","zh":"one’s own society 指一個人所屬的社群、國家或文化。"},{"en":"A student may understand one’s own society better after studying another country.","zh":"學生在研究另一個國家後，可能更了解自己所屬的社會。"},{"en":"Living abroad can make people notice problems and strengths in their own society.","zh":"在外地生活可以令人注意到自己社會中的問題和優點。"},{"en":"Travel writing often compares foreign societies with the traveller’s own society.","zh":"旅行文學常把外地社會與旅行者自己所屬的社會作比較。"}],"source":"158 - Travel Accounts.pdf","sourcePage":1},{"front":"simply desire to","meaning":"只是想要","examples":[{"en":"Some travellers simply desired to satisfy curiosity about the larger world.","zh":"有些旅行者只是想要滿足對更廣闊世界的好奇心。"},{"en":"To simply desire to do something means to want to do it for a basic, direct reason.","zh":"simply desire to do something 表示出於簡單直接的原因想做某事。"},{"en":"Some children simply desire to play after a long day at school.","zh":"有些孩子在漫長上課日後只是想要玩耍。"},{"en":"A person may simply desire to rest when work has been stressful.","zh":"工作壓力大時，一個人可能只是想要休息。"},{"en":"This phrase often suggests that the motive is plain, personal, and not complicated.","zh":"這個短語常表示動機很單純、個人化，並不複雜。"}],"source":"158 - Travel Accounts.pdf","sourcePage":1},{"front":"satisfy curiosity about","meaning":"滿足對……的好奇心","examples":[{"en":"Some travellers wanted to satisfy curiosity about the larger world.","zh":"有些旅行者想滿足對更廣闊世界的好奇心。"},{"en":"To satisfy curiosity about something means to find out more because one wants to know.","zh":"satisfy curiosity about something 表示因為想知道而去了解更多。"},{"en":"A child may read a science book to satisfy curiosity about space.","zh":"孩子可能閱讀科學書，以滿足對太空的好奇心。"},{"en":"Museums satisfy curiosity about the past by showing objects and stories.","zh":"博物館透過展示物件和故事，滿足人們對過去的好奇心。"},{"en":"Curiosity is satisfied when questions are answered with clear information or experience.","zh":"當問題透過清楚資料或經驗得到解答時，好奇心就得到滿足。"}],"source":"158 - Travel Accounts.pdf","sourcePage":1},{"front":"the larger world","meaning":"更廣闊的世界","examples":[{"en":"Travellers were curious about the larger world beyond their own societies.","zh":"旅行者對自己社會以外更廣闊的世界感到好奇。"},{"en":"The larger world means places, peoples, and events outside one’s familiar surroundings.","zh":"the larger world 指一個人熟悉環境以外的地方、人民和事件。"},{"en":"Reading news can help students understand the larger world beyond school.","zh":"閱讀新聞可以幫助學生了解校園以外更廣闊的世界。"},{"en":"Travel can show people that the larger world is more varied than they imagined.","zh":"旅行可以令人看見更廣闊的世界比想像中更多樣。"},{"en":"This phrase often contrasts familiar local life with wider global experience.","zh":"這個短語常把熟悉的本地生活與更廣泛的全球經驗作對比。"}],"source":"158 - Travel Accounts.pdf","sourcePage":1},{"front":"until recent times","meaning":"直到近代以前","examples":[{"en":"Until recent times, curiosity was not the main reason for foreign travel.","zh":"直到近代以前，好奇心並不是外地旅行的主要原因。"},{"en":"Until recent times means before the modern period or before the last few generations.","zh":"until recent times 表示在現代以前，或在最近幾代人以前。"},{"en":"Until recent times, many families cooked most meals at home.","zh":"直到近代以前，許多家庭大多在家煮飯。"},{"en":"Until recent times, long-distance travel was slow, costly, and risky.","zh":"直到近代以前，長途旅行既慢、昂貴，又有風險。"},{"en":"This phrase is useful when comparing the past with the modern world.","zh":"比較過去與現代世界時，這個短語很有用。"}],"source":"158 - Travel Accounts.pdf","sourcePage":1},{"front":"trade and business dealings","meaning":"貿易和商業往來","examples":[{"en":"Trade and business dealings were common reasons for foreign travel.","zh":"貿易和商業往來是外地旅行的常見原因。"},{"en":"Trade and business dealings are activities involving buying, selling, contracts, and commercial relationships.","zh":"trade and business dealings 指涉及買賣、合約和商業關係的活動。"},{"en":"A manager may travel abroad for trade and business dealings with suppliers.","zh":"經理可能因為與供應商進行貿易和商業往來而出國。"},{"en":"Trade and business dealings can create links between distant cities and cultures.","zh":"貿易和商業往來可以在遙遠城市和文化之間建立連繫。"},{"en":"Unlike leisure travel, trade and business dealings are mainly connected with work and profit.","zh":"與休閒旅行不同，貿易和商業往來主要與工作和利潤有關。"}],"source":"158 - Travel Accounts.pdf","sourcePage":1},{"front":"diplomacy","meaning":"外交","examples":[{"en":"Diplomacy was one common inducement to foreign travel.","zh":"外交是促使外地旅行的一個常見誘因。"},{"en":"Diplomacy is the work of managing relations between countries through discussion and negotiation.","zh":"外交是透過討論和談判處理國家之間關係的工作。"},{"en":"An ambassador uses diplomacy when solving disagreements between governments.","zh":"大使在解決政府之間的分歧時會運用外交。"},{"en":"Good diplomacy can prevent conflict by allowing leaders to talk before fighting begins.","zh":"良好的外交可以讓領袖在戰鬥開始前交談，從而防止衝突。"},{"en":"Diplomacy usually depends on patience, careful language, and respect for both sides.","zh":"外交通常依靠耐性、謹慎用語和對雙方的尊重。"}],"source":"158 - Travel Accounts.pdf","sourcePage":1},{"front":"political administration","meaning":"政治管治；政治行政","examples":[{"en":"Political administration often required people to travel abroad.","zh":"政治管治常要求人們到外地旅行。"},{"en":"Political administration means the work of governing, organising, and managing public affairs.","zh":"political administration 指治理、組織和管理公共事務的工作。"},{"en":"Officials may travel for political administration when they inspect distant provinces.","zh":"官員巡視遙遠省份時，可能因政治行政而出行。"},{"en":"Weak political administration can lead to confusion, corruption, and poor public services.","zh":"薄弱的政治管治可能導致混亂、腐敗和公共服務欠佳。"},{"en":"In large empires, political administration often depended on messengers, reports, and travelling officials.","zh":"在大型帝國中，政治管治常依靠信使、報告和出行官員。"}],"source":"158 - Travel Accounts.pdf","sourcePage":1},{"front":"military campaigns","meaning":"軍事行動；軍事戰役","examples":[{"en":"Military campaigns could lead people to foreign lands.","zh":"軍事行動可能把人們帶到外地。"},{"en":"Military campaigns are organised army operations carried out to achieve war aims.","zh":"military campaigns 是為達成戰爭目標而進行的有組織軍隊行動。"},{"en":"Soldiers may travel far from home during military campaigns.","zh":"士兵在軍事戰役期間可能遠離家鄉。"},{"en":"Military campaigns can change borders, damage towns, and force civilians to move.","zh":"軍事行動可以改變邊界、破壞城鎮，並迫使平民遷移。"},{"en":"Unlike peaceful travel, military campaigns often involve danger, control, and conflict.","zh":"與和平旅行不同，軍事行動常涉及危險、控制和衝突。"}],"source":"158 - Travel Accounts.pdf","sourcePage":2},{"front":"exile","meaning":"流亡","examples":[{"en":"Exile was one reason why some people travelled beyond their own societies.","zh":"流亡是有些人到自己社會以外旅行的原因之一。"},{"en":"Exile means being forced or pressured to live away from one’s country or home.","zh":"exile 指被迫或受壓離開自己的國家或家園生活。"},{"en":"A writer may live in exile after criticising a powerful government.","zh":"作家批評強大政府後，可能過着流亡生活。"},{"en":"Exile can separate people from family, language, and familiar customs.","zh":"流亡可以使人與家庭、語言和熟悉習俗分離。"},{"en":"Some people choose exile for safety, while others are officially sent away.","zh":"有些人為了安全選擇流亡，另一些人則被正式驅逐。"}],"source":"158 - Travel Accounts.pdf","sourcePage":2},{"front":"flight from persecution","meaning":"逃避迫害","examples":[{"en":"Flight from persecution forced many people to travel.","zh":"逃避迫害迫使許多人旅行。"},{"en":"Flight from persecution means escaping because one is being treated cruelly for beliefs, identity, or group membership.","zh":"flight from persecution 指因信仰、身份或群體歸屬而遭殘酷對待，於是逃走。"},{"en":"A family may begin flight from persecution if their religion is banned.","zh":"如果宗教被禁止，一個家庭可能開始逃避迫害。"},{"en":"Flight from persecution often creates refugees who need safety in another place.","zh":"逃避迫害常造成需要在別處尋求安全的難民。"},{"en":"This phrase describes urgent movement caused by fear, not ordinary tourism.","zh":"這個短語描述由恐懼造成的緊急遷移，而不是普通旅遊。"}],"source":"158 - Travel Accounts.pdf","sourcePage":2},{"front":"migration","meaning":"遷徙；移民","examples":[{"en":"Migration was a common reason for travel to foreign lands.","zh":"遷徙是到外地旅行的常見原因。"},{"en":"Migration is the movement of people from one place to another to live or work.","zh":"migration 指人們從一地移到另一地生活或工作。"},{"en":"Families may choose migration when jobs are scarce in their hometown.","zh":"當家鄉工作不足時，家庭可能選擇移民。"},{"en":"Migration can change cities by bringing new languages, foods, and skills.","zh":"遷徙可以帶來新語言、食物和技能，從而改變城市。"},{"en":"Migration may be voluntary, but war or poverty can also force people to move.","zh":"遷徙可以是自願的，但戰爭或貧窮也可以迫使人們遷移。"}],"source":"158 - Travel Accounts.pdf","sourcePage":2},{"front":"pilgrimage","meaning":"朝聖","examples":[{"en":"Pilgrimage was a major reason for travel in many eras.","zh":"朝聖在許多時代都是旅行的主要原因。"},{"en":"Pilgrimage is a journey to a holy place for religious reasons.","zh":"pilgrimage 指因宗教原因前往聖地的旅程。"},{"en":"A Buddhist may make a pilgrimage to a temple connected with an important teacher.","zh":"佛教徒可能到與重要老師有關的寺廟朝聖。"},{"en":"Pilgrimage can strengthen faith because travellers pray, reflect, and meet other believers.","zh":"朝聖可以透過祈禱、反思和遇見其他信徒來加強信仰。"},{"en":"Unlike sightseeing, pilgrimage is mainly about spiritual meaning.","zh":"與觀光不同，朝聖主要關乎精神意義。"}],"source":"158 - Travel Accounts.pdf","sourcePage":2},{"front":"missionary efforts","meaning":"傳教工作","examples":[{"en":"Missionary efforts took travellers to distant societies.","zh":"傳教工作把旅行者帶到遙遠社會。"},{"en":"Missionary efforts are attempts to spread a religion or teach religious beliefs.","zh":"missionary efforts 指傳播宗教或教授宗教信仰的努力。"},{"en":"Missionary efforts may bring teachers, doctors, or translators to remote communities.","zh":"傳教工作可能把教師、醫生或翻譯帶到偏遠社群。"},{"en":"Missionary efforts can create contact between cultures, but they may also cause tension.","zh":"傳教工作可以造成文化接觸，但也可能引起緊張。"},{"en":"This phrase usually describes organised religious work, not casual conversation about faith.","zh":"這個短語通常描述有組織的宗教工作，而不是隨意談論信仰。"}],"source":"158 - Travel Accounts.pdf","sourcePage":2},{"front":"the quest for","meaning":"對……的追求","examples":[{"en":"The quest for economic or educational opportunities encouraged foreign travel.","zh":"對經濟或教育機會的追求鼓勵了外地旅行。"},{"en":"The quest for something is a serious search for something important or valuable.","zh":"the quest for something 指認真尋找重要或有價值的東西。"},{"en":"A student’s quest for better training may lead them to study abroad.","zh":"學生對更好培訓的追求可能使他們出國留學。"},{"en":"The quest for clean water can push families to leave dry villages.","zh":"對潔淨食水的追求可以迫使家庭離開乾旱村莊。"},{"en":"This phrase sounds stronger than simply wanting something; it suggests effort and purpose.","zh":"這個短語比 simply wanting something 更強，表示努力和目的。"}],"source":"158 - Travel Accounts.pdf","sourcePage":2},{"front":"economic or educational opportunities","meaning":"經濟或教育機會","examples":[{"en":"Many people travelled in search of economic or educational opportunities.","zh":"許多人旅行是為了尋找經濟或教育機會。"},{"en":"Economic or educational opportunities are chances to earn, work, study, or improve one’s future.","zh":"economic or educational opportunities 指賺錢、工作、學習或改善未來的機會。"},{"en":"A young worker may move to a city for economic or educational opportunities.","zh":"年輕工人可能為了經濟或教育機會搬到城市。"},{"en":"Lack of economic or educational opportunities can make rural families migrate.","zh":"缺乏經濟或教育機會可能令農村家庭遷移。"},{"en":"These opportunities often shape where people choose to live.","zh":"這些機會常影響人們選擇在哪裡生活。"}],"source":"158 - Travel Accounts.pdf","sourcePage":2},{"front":"common inducements to","meaning":"促使……的常見誘因","examples":[{"en":"Trade and pilgrimage were common inducements to foreign travel.","zh":"貿易和朝聖是促使外地旅行的常見誘因。"},{"en":"Common inducements to an action are frequent reasons that encourage people to do it.","zh":"common inducements to an action 指促使人們做某事的常見原因。"},{"en":"Higher pay and safer housing are common inducements to taking a difficult job.","zh":"較高工資和較安全住房是促使人們接受艱苦工作的常見誘因。"},{"en":"Cheap tickets can be common inducements to visiting a museum or concert.","zh":"便宜門票可以是促使人們參觀博物館或音樂會的常見誘因。"},{"en":"This phrase focuses on what attracts or pushes people towards an action.","zh":"這個短語重點在於吸引或推動人們採取行動的原因。"}],"source":"158 - Travel Accounts.pdf","sourcePage":2},{"front":"foreign travel","meaning":"外國旅行；到外地旅行","examples":[{"en":"Foreign travel was often motivated by trade, pilgrimage or diplomacy.","zh":"外地旅行常受貿易、朝聖或外交推動。"},{"en":"Foreign travel means travelling to a country or society outside one’s own.","zh":"foreign travel 指到自己國家或社會以外的地方旅行。"},{"en":"Foreign travel can help students practise a language in real situations.","zh":"外地旅行可以幫助學生在真實情境中練習語言。"},{"en":"Expensive tickets and strict borders can reduce foreign travel.","zh":"昂貴機票和嚴格邊境可能減少外地旅行。"},{"en":"Foreign travel may be for work, study, religion, safety, or leisure.","zh":"外地旅行可以是為了工作、學習、宗教、安全或休閒。"}],"source":"158 - Travel Accounts.pdf","sourcePage":2},{"front":"mere curiosity","meaning":"純粹好奇","examples":[{"en":"Mere curiosity was not the most common reason for travel.","zh":"純粹好奇並不是旅行最常見的原因。"},{"en":"Mere curiosity means simple interest without a stronger practical reason.","zh":"mere curiosity 指單純興趣，沒有更強的實際原因。"},{"en":"A person may open an old box out of mere curiosity.","zh":"一個人可能出於純粹好奇打開舊盒子。"},{"en":"Mere curiosity can lead to learning, but it may not be enough to justify a dangerous journey.","zh":"純粹好奇可以帶來學習，但未必足以支持危險旅程。"},{"en":"In this passage, trade and religion mattered more than mere curiosity.","zh":"在這篇文章中，貿易和宗教比純粹好奇更重要。"}],"source":"158 - Travel Accounts.pdf","sourcePage":2},{"front":"give valuable information on","meaning":"提供有關……的寶貴資料","examples":[{"en":"Travellers’ accounts give valuable information on foreign lands.","zh":"旅行者的記錄提供有關外地的寶貴資料。"},{"en":"To give valuable information on something means to provide useful knowledge about it.","zh":"give valuable information on something 表示提供有關某事的有用知識。"},{"en":"A medical report can give valuable information on a patient’s condition.","zh":"醫療報告可以提供有關病人情況的寶貴資料。"},{"en":"Surveys give valuable information on what residents need from public services.","zh":"調查提供有關居民對公共服務需要的寶貴資料。"},{"en":"Information is valuable when it helps people understand, decide, or solve problems.","zh":"當資料幫助人理解、決定或解決問題時，它就是寶貴的。"}],"source":"158 - Travel Accounts.pdf","sourcePage":3},{"front":"foreign lands","meaning":"外地；異國地方","examples":[{"en":"Travellers’ accounts describe foreign lands and peoples.","zh":"旅行者的記錄描述外地和當地人民。"},{"en":"Foreign lands are countries or regions outside one’s own familiar world.","zh":"foreign lands 指自己熟悉世界以外的國家或地區。"},{"en":"Old maps often showed foreign lands with limited detail and many guesses.","zh":"古地圖常以有限細節和許多猜測描繪異國地方。"},{"en":"Stories about foreign lands can make readers curious about different climates and customs.","zh":"關於外地的故事可以令人對不同氣候和習俗感到好奇。"},{"en":"The phrase foreign lands often sounds more historical or literary than foreign countries.","zh":"foreign lands 這個短語通常比 foreign countries 更有歷史或文學色彩。"}],"source":"158 - Travel Accounts.pdf","sourcePage":3},{"front":"provide a window into","meaning":"提供了解……的窗口","examples":[{"en":"Travel accounts provide a window into local cultures and histories.","zh":"旅行記錄提供了解本地文化和歷史的窗口。"},{"en":"To provide a window into something means to help people see and understand it.","zh":"provide a window into something 表示幫助人看見並理解某事。"},{"en":"Family photographs provide a window into how people lived in the past.","zh":"家庭照片提供了解過去人們生活方式的窗口。"},{"en":"Interviews can provide a window into workers’ real experiences.","zh":"訪問可以提供了解工人真實經驗的窗口。"},{"en":"This phrase suggests indirect understanding, as if the reader can look inside a world.","zh":"這個短語表示間接理解，好像讀者能望進一個世界。"}],"source":"158 - Travel Accounts.pdf","sourcePage":3},{"front":"local cultures and histories","meaning":"本地文化和歷史","examples":[{"en":"Travel writing helps readers understand local cultures and histories.","zh":"旅行文學幫助讀者了解本地文化和歷史。"},{"en":"Local cultures and histories are the customs, stories, memories, and past events of particular communities.","zh":"local cultures and histories 指特定社群的習俗、故事、記憶和過去事件。"},{"en":"Museums teach local cultures and histories through objects and personal stories.","zh":"博物館透過物件和個人故事教授本地文化和歷史。"},{"en":"Ignoring local cultures and histories can make development projects feel disrespectful.","zh":"忽視本地文化和歷史可能令發展項目顯得不尊重。"},{"en":"Travel accounts are richer when they describe both daily life and historical background.","zh":"當旅行記錄同時描述日常生活和歷史背景時，內容會更豐富。"}],"source":"158 - Travel Accounts.pdf","sourcePage":3},{"front":"mirror the travellers themselves","meaning":"反映旅行者本身","examples":[{"en":"Travel accounts also mirror the travellers themselves.","zh":"旅行記錄也反映旅行者本身。"},{"en":"To mirror the travellers themselves means to reflect their values, fears, interests, and assumptions.","zh":"mirror the travellers themselves 指反映他們的價值觀、恐懼、興趣和假設。"},{"en":"A diary may mirror the writer themselves by showing what they notice first.","zh":"日記可以透過顯示作者首先注意甚麼來反映作者本身。"},{"en":"Travel accounts mirror the travellers themselves when they praise some customs and criticise others.","zh":"當旅行記錄讚揚某些習俗並批評另一些習俗時，它反映旅行者本身。"},{"en":"This phrase reminds us that travel writing is not completely neutral.","zh":"這個短語提醒我們，旅行文學並非完全中立。"}],"source":"158 - Travel Accounts.pdf","sourcePage":3},{"front":"understand themselves better","meaning":"更了解自己","examples":[{"en":"Travel accounts helped travellers understand themselves better.","zh":"旅行記錄幫助旅行者更了解自己。"},{"en":"To understand themselves better means to become clearer about one’s own values, habits, and identity.","zh":"understand themselves better 指更清楚自己的價值觀、習慣和身份。"},{"en":"Living with a host family can help students understand themselves better.","zh":"與寄宿家庭生活可以幫助學生更了解自己。"},{"en":"Meeting different customs can make people understand themselves better by comparison.","zh":"接觸不同習俗可以透過比較令人更了解自己。"},{"en":"Sometimes people learn who they are only after leaving familiar surroundings.","zh":"有時人們只有離開熟悉環境後，才學會自己是誰。"}],"source":"158 - Travel Accounts.pdf","sourcePage":3},{"front":"records of foreign travel","meaning":"外地旅行記錄","examples":[{"en":"Records of foreign travel appeared soon after the invention of writing.","zh":"外地旅行記錄在文字發明後不久便出現。"},{"en":"Records of foreign travel are written accounts of journeys to places outside one’s own society.","zh":"records of foreign travel 指到自己社會以外地方旅行的書面記錄。"},{"en":"Ancient records of foreign travel may describe roads, rulers, markets, and temples.","zh":"古代外地旅行記錄可能描述道路、統治者、市場和寺廟。"},{"en":"Records of foreign travel help historians study contact between distant peoples.","zh":"外地旅行記錄幫助歷史學家研究遙遠民族之間的接觸。"},{"en":"Without such records, many early journeys would be almost forgotten.","zh":"沒有這些記錄，許多早期旅程幾乎會被遺忘。"}],"source":"158 - Travel Accounts.pdf","sourcePage":3},{"front":"soon after","meaning":"在……之後不久","examples":[{"en":"Travel records appeared soon after the invention of writing.","zh":"旅行記錄在文字發明後不久便出現。"},{"en":"Soon after means a short time later.","zh":"soon after 表示在不久之後。"},{"en":"The students left soon after the final bell rang.","zh":"放學鐘聲響起後不久，學生便離開。"},{"en":"Soon after heavy rain begins, some roads may flood.","zh":"大雨開始後不久，有些道路可能水浸。"},{"en":"This phrase shows that one event follows another with little delay.","zh":"這個短語表示一件事在另一件事後很快發生。"}],"source":"158 - Travel Accounts.pdf","sourcePage":3},{"front":"the invention of writing","meaning":"文字的發明","examples":[{"en":"Travel records appeared after the invention of writing.","zh":"旅行記錄在文字發明後出現。"},{"en":"The invention of writing was the development of systems for recording language with symbols.","zh":"the invention of writing 指用符號記錄語言的系統發展。"},{"en":"The invention of writing allowed people to keep laws, stories, trade records, and letters.","zh":"文字的發明讓人們能保存法律、故事、貿易記錄和書信。"},{"en":"After the invention of writing, knowledge could travel beyond one person’s memory.","zh":"文字發明後，知識可以超越個人記憶而流傳。"},{"en":"Writing changed history because events could be recorded and passed on.","zh":"文字改變歷史，因為事件可以被記錄並傳承。"}],"source":"158 - Travel Accounts.pdf","sourcePage":3},{"front":"fragmentary travel accounts","meaning":"殘缺不全的旅行記錄","examples":[{"en":"Fragmentary travel accounts appeared in Mesopotamia and Egypt.","zh":"殘缺不全的旅行記錄出現在美索不達米亞和埃及。"},{"en":"Fragmentary travel accounts are incomplete travel records, with only parts surviving.","zh":"fragmentary travel accounts 指不完整的旅行記錄，只有部分保存下來。"},{"en":"An ancient tablet may contain fragmentary travel accounts if many lines are broken.","zh":"如果古代泥板有許多行破損，它可能包含殘缺不全的旅行記錄。"},{"en":"Fragmentary travel accounts can still help historians when they are compared with other evidence.","zh":"當殘缺不全的旅行記錄與其他證據比較時，仍可幫助歷史學家。"},{"en":"They are valuable, even though they do not tell the whole story.","zh":"它們雖然不能說出完整故事，但仍然寶貴。"}],"source":"158 - Travel Accounts.pdf","sourcePage":3},{"front":"ancient times","meaning":"古代","examples":[{"en":"Travel accounts appeared in ancient times.","zh":"旅行記錄在古代出現。"},{"en":"Ancient times refers to the very early period of human history.","zh":"ancient times 指人類歷史非常早期的時代。"},{"en":"In ancient times, messages often travelled slowly by foot, horse, or boat.","zh":"在古代，訊息常透過步行、馬匹或船隻慢慢傳遞。"},{"en":"Life in ancient times was shaped by farming, religion, war, and local trade.","zh":"古代生活受農業、宗教、戰爭和本地貿易影響。"},{"en":"This phrase is useful when speaking broadly about early civilisations.","zh":"泛指早期文明時，這個短語很有用。"}],"source":"158 - Travel Accounts.pdf","sourcePage":3},{"front":"the formation of","meaning":"……的形成","examples":[{"en":"Travel accounts became common after the formation of large imperial states.","zh":"在大型帝國國家形成後，旅行記錄變得常見。"},{"en":"The formation of something is the process by which it is created or takes shape.","zh":"the formation of something 指某事物被創造或成形的過程。"},{"en":"The formation of a student club begins when members agree on its purpose.","zh":"學生學會的形成始於成員同意其目的。"},{"en":"The formation of cities often leads to new jobs, roads, and social rules.","zh":"城市的形成常帶來新工作、道路和社會規則。"},{"en":"This phrase focuses on how something begins to exist in an organised way.","zh":"這個短語重點在於某事如何以有組織的方式開始存在。"}],"source":"158 - Travel Accounts.pdf","sourcePage":4},{"front":"large, imperial states","meaning":"大型帝國國家","examples":[{"en":"Large, imperial states helped travel accounts develop.","zh":"大型帝國國家幫助旅行記錄發展。"},{"en":"Large, imperial states are big political systems that rule many peoples or territories.","zh":"large, imperial states 指統治許多民族或領土的大型政治體系。"},{"en":"Large, imperial states needed roads, officials, and reports to control distant regions.","zh":"大型帝國國家需要道路、官員和報告來控制遙遠地區。"},{"en":"Because large, imperial states connected many lands, travellers had more places to describe.","zh":"由於大型帝國國家連接許多地方，旅行者有更多地方可以描述。"},{"en":"Such states often produced records because rulers wanted knowledge about their realms.","zh":"這類國家常產生記錄，因為統治者想了解自己的領土。"}],"source":"158 - Travel Accounts.pdf","sourcePage":4},{"front":"the classical world","meaning":"古典世界","examples":[{"en":"Travel accounts became a literary genre in the classical world.","zh":"旅行記錄在古典世界成為一種文學體裁。"},{"en":"The classical world usually refers to ancient Greek and Roman civilisation.","zh":"the classical world 通常指古希臘和古羅馬文明。"},{"en":"Students study the classical world to learn about philosophy, politics, art, and history.","zh":"學生研究古典世界，以學習哲學、政治、藝術和歷史。"},{"en":"In the classical world, writers often mixed travel description with geography and history.","zh":"在古典世界中，作家常把旅行描述與地理和歷史混合。"},{"en":"This phrase points to a specific ancient cultural tradition, not all ancient societies.","zh":"這個短語指特定的古代文化傳統，而不是所有古代社會。"}],"source":"158 - Travel Accounts.pdf","sourcePage":4},{"front":"emerge as","meaning":"作為……出現","examples":[{"en":"Travel accounts emerged as a prominent literary genre.","zh":"旅行記錄作為重要文學體裁出現。"},{"en":"To emerge as something means to gradually become recognised in that role or form.","zh":"emerge as something 指逐漸被認定為某種角色或形式。"},{"en":"A quiet student may emerge as a strong leader during a group project.","zh":"安靜的學生可能在小組項目中逐漸成為強有力的領袖。"},{"en":"Online learning emerged as an important option when schools closed.","zh":"當學校關閉時，網上學習作為重要選擇出現。"},{"en":"This phrase suggests development over time, not a sudden label.","zh":"這個短語表示隨時間發展，而不是突然被貼上標籤。"}],"source":"158 - Travel Accounts.pdf","sourcePage":4},{"front":"a prominent literary genre","meaning":"重要文學體裁","examples":[{"en":"Travel accounts became a prominent literary genre.","zh":"旅行記錄成為重要文學體裁。"},{"en":"A prominent literary genre is an important and well-known type of writing.","zh":"a prominent literary genre 指重要而知名的寫作類型。"},{"en":"Detective fiction became a prominent literary genre because many readers enjoyed mystery stories.","zh":"偵探小說因許多讀者喜愛推理故事而成為重要文學體裁。"},{"en":"A prominent literary genre often attracts publishers, critics, and regular readers.","zh":"重要文學體裁常吸引出版商、評論家和固定讀者。"},{"en":"Travel writing became prominent when readers wanted information about distant places.","zh":"當讀者想了解遙遠地方時，旅行文學變得突出。"}],"source":"158 - Travel Accounts.pdf","sourcePage":4},{"front":"hold strong appeal for","meaning":"對……有強大吸引力","examples":[{"en":"Travel accounts held strong appeal for rulers.","zh":"旅行記錄對統治者有強大吸引力。"},{"en":"To hold strong appeal for someone means to be very attractive or useful to them.","zh":"hold strong appeal for someone 指對某人非常有吸引力或有用。"},{"en":"Scholarships hold strong appeal for students from low-income families.","zh":"獎學金對低收入家庭學生有強大吸引力。"},{"en":"A safe neighbourhood may hold strong appeal for parents with young children.","zh":"安全社區可能對有幼兒的父母有強大吸引力。"},{"en":"Travel accounts appealed to rulers because they offered practical knowledge.","zh":"旅行記錄吸引統治者，因為它們提供實用知識。"}],"source":"158 - Travel Accounts.pdf","sourcePage":4},{"front":"rulers desiring","meaning":"渴望……的統治者","examples":[{"en":"Travel accounts appealed to rulers desiring useful knowledge.","zh":"旅行記錄吸引渴望實用知識的統治者。"},{"en":"Rulers desiring something are leaders who want or seek it.","zh":"rulers desiring something 指想要或尋求某事物的領袖。"},{"en":"Rulers desiring stability may collect reports from distant regions.","zh":"渴望穩定的統治者可能收集遙遠地區的報告。"},{"en":"A manager desiring better service may ask customers for honest feedback.","zh":"渴望改善服務的經理可能要求顧客提供誠實意見。"},{"en":"The phrase often introduces the motive behind a leader’s action.","zh":"這個短語常引出領袖行動背後的動機。"}],"source":"158 - Travel Accounts.pdf","sourcePage":4},{"front":"useful knowledge about","meaning":"關於……的實用知識","examples":[{"en":"Rulers wanted useful knowledge about their realms.","zh":"統治者想要關於自己領土的實用知識。"},{"en":"Useful knowledge about something is information that helps people make decisions or act effectively.","zh":"useful knowledge about something 指幫助人作決定或有效行動的資料。"},{"en":"Parents need useful knowledge about school choices before moving house.","zh":"父母在搬家前需要關於學校選擇的實用知識。"},{"en":"Useful knowledge about local roads can help emergency workers arrive faster.","zh":"關於本地道路的實用知識可以幫助救援人員更快到達。"},{"en":"In government, useful knowledge is valuable because it supports control and planning.","zh":"在政府中，實用知識很有價值，因為它支援控制和規劃。"}],"source":"158 - Travel Accounts.pdf","sourcePage":4},{"front":"their realms","meaning":"他們的領土；王國","examples":[{"en":"Rulers wanted information about their realms.","zh":"統治者想要有關他們領土的資料。"},{"en":"Their realms means the lands, peoples, and territories under rulers’ control.","zh":"their realms 指在統治者控制下的土地、人民和領域。"},{"en":"Ancient kings sent officials to inspect their realms.","zh":"古代國王派官員巡視他們的領土。"},{"en":"If rulers knew little about their realms, they could not tax or defend them well.","zh":"如果統治者對自己的領土了解很少，就難以有效徵稅或防衛。"},{"en":"This word is more historical than modern words such as country or district.","zh":"這個詞比 country 或 district 等現代詞更有歷史感。"}],"source":"158 - Travel Accounts.pdf","sourcePage":4},{"front":"report on","meaning":"報道；記述","examples":[{"en":"Herodotus reported on his travels in Egypt and Anatolia.","zh":"希羅多德記述了他在埃及和安納托利亞的旅行。"},{"en":"To report on something means to describe it and give information about it.","zh":"report on something 指描述某事並提供有關資料。"},{"en":"Journalists report on floods, elections, and public problems.","zh":"記者報道洪水、選舉和公共問題。"},{"en":"A school monitor may report on class activities during a meeting.","zh":"班長可能在會議中匯報班級活動。"},{"en":"Reporting on a place should include clear details, not only personal feelings.","zh":"記述一個地方應包括清楚細節，而不只是個人感受。"}],"source":"158 - Travel Accounts.pdf","sourcePage":4},{"front":"research the history of","meaning":"研究……的歷史","examples":[{"en":"Herodotus travelled while researching the history of the Persian wars.","zh":"希羅多德在研究波斯戰爭歷史時旅行。"},{"en":"To research the history of something means to study past events carefully using evidence.","zh":"research the history of something 指利用證據仔細研究過去事件。"},{"en":"A student may research the history of a local market for a school project.","zh":"學生可能為學校項目研究本地市場的歷史。"},{"en":"Historians research the history of a war by reading letters, records, and eyewitness accounts.","zh":"歷史學家透過閱讀書信、記錄和目擊者記述來研究戰爭歷史。"},{"en":"Good historical research asks what happened, why it happened, and how people remembered it.","zh":"良好的歷史研究會問發生了甚麼、為何發生，以及人們如何記住它。"}],"source":"158 - Travel Accounts.pdf","sourcePage":4},{"front":"the Persian wars","meaning":"波斯戰爭","examples":[{"en":"Herodotus studied the history of the Persian wars.","zh":"希羅多德研究波斯戰爭的歷史。"},{"en":"The Persian wars were conflicts between the Persian Empire and Greek city-states in ancient times.","zh":"the Persian wars 指古代波斯帝國與希臘城邦之間的衝突。"},{"en":"Students study the Persian wars to understand Greek and Persian power.","zh":"學生研究波斯戰爭，以了解希臘和波斯的力量。"},{"en":"The Persian wars became important because writers recorded their causes and consequences.","zh":"波斯戰爭變得重要，因為作家記錄了其原因和後果。"},{"en":"This term names a specific historical conflict, not wars in modern Persia or Iran.","zh":"這個詞指特定歷史衝突，而不是現代波斯或伊朗的戰爭。"}],"source":"158 - Travel Accounts.pdf","sourcePage":5},{"front":"Chinese envoy","meaning":"中國使節","examples":[{"en":"The Chinese envoy Zhang Qian described much of Central Asia.","zh":"中國使節張騫描述了中亞大部分地區。"},{"en":"A Chinese envoy is an official representative sent by a Chinese ruler or government.","zh":"Chinese envoy 指由中國統治者或政府派出的官方代表。"},{"en":"A Chinese envoy might travel to another court to deliver messages or seek allies.","zh":"中國使節可能前往另一個宮廷傳遞訊息或尋找盟友。"},{"en":"Envoys can gather information because they meet leaders, merchants, and local people.","zh":"使節能收集資料，因為他們會見領袖、商人和本地人。"},{"en":"In ancient history, envoys often combined diplomacy, travel, and intelligence-gathering.","zh":"在古代歷史中，使節常結合外交、旅行和情報收集。"}],"source":"158 - Travel Accounts.pdf","sourcePage":5},{"front":"describe much of","meaning":"描述……的大部分","examples":[{"en":"Zhang Qian described much of Central Asia.","zh":"張騫描述了中亞大部分地區。"},{"en":"To describe much of a place means to give information about a large part of it.","zh":"describe much of a place 指提供有關該地方大部分地區的資料。"},{"en":"A guidebook may describe much of a city, including transport, food, and museums.","zh":"旅遊指南可能描述一座城市的大部分內容，包括交通、食物和博物館。"},{"en":"A report can describe much of a problem without covering every small detail.","zh":"報告可以描述一個問題的大部分，而不涵蓋每個小細節。"},{"en":"This phrase suggests broad coverage, but not complete coverage.","zh":"這個短語表示涵蓋範圍廣，但不是完全涵蓋。"}],"source":"158 - Travel Accounts.pdf","sourcePage":5},{"front":"Central Asia","meaning":"中亞","examples":[{"en":"Zhang Qian travelled through Central Asia.","zh":"張騫穿越中亞旅行。"},{"en":"Central Asia is the region between East Asia, South Asia, the Middle East, and Russia.","zh":"Central Asia 指位於東亞、南亞、中東和俄羅斯之間的地區。"},{"en":"Merchants crossed Central Asia along routes that later became linked with the Silk Road.","zh":"商人沿後來與絲綢之路相關的路線穿越中亞。"},{"en":"Central Asia mattered because it connected different empires, religions, and trading peoples.","zh":"中亞很重要，因為它連接不同帝國、宗教和貿易民族。"},{"en":"Travel accounts from Central Asia often describe deserts, oases, horses, and markets.","zh":"來自中亞的旅行記錄常描述沙漠、綠洲、馬匹和市場。"}],"source":"158 - Travel Accounts.pdf","sourcePage":5},{"front":"as far west as","meaning":"向西遠至","examples":[{"en":"Zhang Qian described lands as far west as Bactria.","zh":"張騫描述的地方向西遠至巴克特里亞。"},{"en":"As far west as means reaching a western limit or distant western point.","zh":"as far west as 表示到達西面的界限或遙遠西方地點。"},{"en":"The storm moved as far west as the coastal villages.","zh":"風暴向西遠至沿海村莊。"},{"en":"A delivery company may send packages as far west as remote mountain towns.","zh":"快遞公司可能把包裹送到向西遠至偏遠山城的地方。"},{"en":"This phrase helps show how wide or distant a journey or influence was.","zh":"這個短語有助顯示旅程或影響範圍有多廣、多遠。"}],"source":"158 - Travel Accounts.pdf","sourcePage":5},{"front":"modern-day Afghanistan","meaning":"今日的阿富汗","examples":[{"en":"Bactria was located in modern-day Afghanistan.","zh":"巴克特里亞位於今日的阿富汗。"},{"en":"Modern-day Afghanistan means the country of Afghanistan as it exists today.","zh":"modern-day Afghanistan 指今天存在的阿富汗這個國家。"},{"en":"Some ancient kingdoms were located in areas of modern-day Afghanistan.","zh":"有些古代王國位於今日阿富汗的地區。"},{"en":"Using modern-day Afghanistan helps readers connect an old place name with a current map.","zh":"使用 modern-day Afghanistan 可以幫助讀者把古地名與現代地圖連繫起來。"},{"en":"This phrase is useful when ancient borders do not match present borders.","zh":"當古代邊界與現代邊界不同時，這個短語很有用。"}],"source":"158 - Travel Accounts.pdf","sourcePage":5},{"front":"on the basis of","meaning":"基於","examples":[{"en":"His account was written on the basis of travels undertaken in the first century BC.","zh":"他的記錄是基於公元前一世紀所進行的旅行而寫成。"},{"en":"On the basis of something means using it as the main support, reason, or evidence.","zh":"on the basis of something 指以某事作為主要支持、原因或證據。"},{"en":"A teacher may grade an essay on the basis of content, language, and organisation.","zh":"老師可能基於內容、語言和組織來評分一篇文章。"},{"en":"Decisions made on the basis of weak evidence may be unfair or wrong.","zh":"基於薄弱證據作出的決定可能不公平或錯誤。"},{"en":"This phrase shows what information or reason a conclusion depends on.","zh":"這個短語顯示結論依靠甚麼資料或理由。"}],"source":"158 - Travel Accounts.pdf","sourcePage":5},{"front":"travels undertaken","meaning":"所進行的旅行","examples":[{"en":"The account was based on travels undertaken in the first century BC.","zh":"這份記錄基於公元前一世紀所進行的旅行。"},{"en":"Travels undertaken are journeys that were carried out or completed.","zh":"travels undertaken 指已經進行或完成的旅程。"},{"en":"The report describes travels undertaken by researchers in remote villages.","zh":"這份報告描述研究人員在偏遠村莊所進行的旅行。"},{"en":"Travels undertaken for trade can later become important historical evidence.","zh":"為貿易所進行的旅行後來可能成為重要歷史證據。"},{"en":"This phrase sounds formal and is often used in academic writing.","zh":"這個短語語氣正式，常用於學術寫作。"}],"source":"158 - Travel Accounts.pdf","sourcePage":5},{"front":"search for allies","meaning":"尋找盟友","examples":[{"en":"Zhang Qian travelled while searching for allies for the Han dynasty.","zh":"張騫旅行時為漢朝尋找盟友。"},{"en":"To search for allies means to look for people or groups who will support you.","zh":"search for allies 指尋找會支持自己的人或群體。"},{"en":"A new student may search for allies when facing bullying.","zh":"新學生面對欺凌時可能尋找盟友。"},{"en":"Countries search for allies when they need help against a stronger enemy.","zh":"國家面對更強大的敵人時會尋找盟友。"},{"en":"Allies are useful because they provide support, protection, advice, or resources.","zh":"盟友很有用，因為他們提供支持、保護、建議或資源。"}],"source":"158 - Travel Accounts.pdf","sourcePage":5},{"front":"the Han dynasty","meaning":"漢朝","examples":[{"en":"Zhang Qian searched for allies for the Han dynasty.","zh":"張騫為漢朝尋找盟友。"},{"en":"The Han dynasty was an important Chinese dynasty that ruled for several centuries.","zh":"the Han dynasty 指統治了數個世紀的重要中國朝代。"},{"en":"Students study the Han dynasty to understand early Chinese government and expansion.","zh":"學生研究漢朝，以了解早期中國政府和擴張。"},{"en":"The Han dynasty sent envoys because it needed information and diplomatic support.","zh":"漢朝派遣使節，因為它需要資訊和外交支持。"},{"en":"This term refers to a specific period of Chinese imperial history.","zh":"這個詞指中國帝國歷史中的特定時期。"}],"source":"158 - Travel Accounts.pdf","sourcePage":5},{"front":"Hellenistic and Roman geographers","meaning":"希臘化時期及羅馬地理學家","examples":[{"en":"Hellenistic and Roman geographers compiled geographical knowledge.","zh":"希臘化時期及羅馬地理學家編纂了地理知識。"},{"en":"Hellenistic and Roman geographers were ancient scholars who studied and described the known world.","zh":"Hellenistic and Roman geographers 指研究和描述已知世界的古代學者。"},{"en":"These geographers used travel reports to map seas, mountains, cities, and trade routes.","zh":"這些地理學家利用旅行記錄繪製海洋、山脈、城市和貿易路線。"},{"en":"Their work helped later readers understand how ancient people imagined the world.","zh":"他們的作品幫助後來讀者了解古人如何想像世界。"},{"en":"They were important because they organised scattered information into clearer geographical knowledge.","zh":"他們很重要，因為他們把分散資料整理成較清晰的地理知識。"}],"source":"158 - Travel Accounts.pdf","sourcePage":5},{"front":"rely on","meaning":"依靠","examples":[{"en":"Ancient geographers relied on their own travels and other reports.","zh":"古代地理學家依靠自己的旅行和其他記錄。"},{"en":"To rely on something means to depend on it for help, support, or information.","zh":"rely on something 指依靠某物取得幫助、支持或資料。"},{"en":"Students often rely on dictionaries when learning new words.","zh":"學生學習新詞時常依靠字典。"},{"en":"If a city relies on one bridge, traffic becomes serious when it closes.","zh":"如果一座城市依靠一條橋，橋關閉時交通便會很嚴重。"},{"en":"Reliable sources matter because people make decisions based on what they rely on.","zh":"可靠來源很重要，因為人們會根據自己依靠的資料作決定。"}],"source":"158 - Travel Accounts.pdf","sourcePage":6},{"front":"the Mediterranean world","meaning":"地中海世界","examples":[{"en":"Some geographers travelled through much of the Mediterranean world.","zh":"有些地理學家遊歷了地中海世界的大部分。"},{"en":"The Mediterranean world means the lands and peoples around the Mediterranean Sea.","zh":"the Mediterranean world 指地中海周圍的土地和人民。"},{"en":"Ancient trade connected the Mediterranean world through ports, ships, and markets.","zh":"古代貿易透過港口、船隻和市場連接地中海世界。"},{"en":"The Mediterranean world mattered because many cultures met around the same sea.","zh":"地中海世界很重要，因為許多文化在同一片海周圍相遇。"},{"en":"This phrase describes a connected region, not just the sea itself.","zh":"這個短語描述一個相互連繫的地區，而不只是海本身。"}],"source":"158 - Travel Accounts.pdf","sourcePage":6},{"front":"reports by other travellers","meaning":"其他旅行者的記錄","examples":[{"en":"Geographers used reports by other travellers.","zh":"地理學家使用其他旅行者的記錄。"},{"en":"Reports by other travellers are descriptions written or spoken by people who made journeys themselves.","zh":"reports by other travellers 指親身旅行者寫下或說出的描述。"},{"en":"A historian may compare reports by other travellers before accepting a detail.","zh":"歷史學家可能比較其他旅行者的記錄，才接受某個細節。"},{"en":"Reports by other travellers can fill gaps when a writer has not visited a place personally.","zh":"當作者沒有親身到訪某地時，其他旅行者的記錄可以填補空白。"},{"en":"Such reports are helpful, but they may contain mistakes or personal bias.","zh":"這類記錄有幫助，但可能包含錯誤或個人偏見。"}],"source":"158 - Travel Accounts.pdf","sourcePage":6},{"front":"compile vast compendia of","meaning":"編纂大量……匯編","examples":[{"en":"Geographers compiled vast compendia of geographical knowledge.","zh":"地理學家編纂大量地理知識匯編。"},{"en":"To compile vast compendia of something means to collect a huge amount of information into organised collections.","zh":"compile vast compendia of something 指把大量資料收集成有組織的匯編。"},{"en":"A museum may compile vast compendia of local stories, photographs, and maps.","zh":"博物館可能編纂大量本地故事、照片和地圖的匯編。"},{"en":"Scholars compile vast compendia when information is scattered across many sources.","zh":"當資料分散在許多來源中，學者會編纂大型匯編。"},{"en":"This phrase suggests careful collection on a very large scale.","zh":"這個短語表示大規模而仔細的收集。"}],"source":"158 - Travel Accounts.pdf","sourcePage":6},{"front":"geographical knowledge","meaning":"地理知識","examples":[{"en":"Ancient geographers collected geographical knowledge.","zh":"古代地理學家收集地理知識。"},{"en":"Geographical knowledge is information about places, landforms, routes, climates, and regions.","zh":"geographical knowledge 指有關地方、地形、路線、氣候和地區的資料。"},{"en":"Drivers need geographical knowledge to choose safe and efficient routes.","zh":"司機需要地理知識來選擇安全而有效率的路線。"},{"en":"Geographical knowledge helps governments plan roads, farms, and emergency services.","zh":"地理知識幫助政府規劃道路、農業和緊急服務。"},{"en":"Travel accounts added to geographical knowledge by describing places people had not mapped well.","zh":"旅行記錄透過描述未被充分繪製的地方，增加了地理知識。"}],"source":"158 - Travel Accounts.pdf","sourcePage":6},{"front":"the postclassical era","meaning":"後古典時代","examples":[{"en":"Trade and pilgrimage were major travel incentives during the postclassical era.","zh":"在後古典時代，貿易和朝聖是主要旅行誘因。"},{"en":"The postclassical era refers to the historical period after the classical world and before the early modern age.","zh":"the postclassical era 指古典世界之後、近代早期之前的歷史時期。"},{"en":"During the postclassical era, merchants and pilgrims connected distant societies.","zh":"在後古典時代，商人和朝聖者連接遙遠社會。"},{"en":"Trade routes in the postclassical era spread goods, religions, and ideas.","zh":"後古典時代的貿易路線傳播商品、宗教和思想。"},{"en":"This phrase helps organise history into broad periods.","zh":"這個短語幫助把歷史劃分成大的時期。"}],"source":"158 - Travel Accounts.pdf","sourcePage":6},{"front":"emerge as major incentives for","meaning":"成為……的主要誘因","examples":[{"en":"Trade and pilgrimage emerged as major incentives for travel.","zh":"貿易和朝聖成為旅行的主要誘因。"},{"en":"To emerge as major incentives for something means to become important reasons encouraging it.","zh":"emerge as major incentives for something 指成為促成某事的重要原因。"},{"en":"Better salaries emerged as major incentives for nurses to work overseas.","zh":"較高薪金成為護士到海外工作的主要誘因。"},{"en":"Cheap flights emerged as major incentives for weekend travel.","zh":"便宜航班成為週末旅行的主要誘因。"},{"en":"This phrase shows that certain factors became powerful motivations over time.","zh":"這個短語顯示某些因素隨時間成為強大動機。"}],"source":"158 - Travel Accounts.pdf","sourcePage":6},{"front":"travel to foreign lands","meaning":"到外地旅行","examples":[{"en":"Trade encouraged travel to foreign lands.","zh":"貿易鼓勵人們到外地旅行。"},{"en":"Travel to foreign lands means journeys to countries or regions outside one’s own society.","zh":"travel to foreign lands 指到自己社會以外的國家或地區旅行。"},{"en":"Students may travel to foreign lands to learn languages and experience new customs.","zh":"學生可能到外地旅行，以學習語言和體驗新習俗。"},{"en":"Trade, war, religion, and education have all encouraged travel to foreign lands.","zh":"貿易、戰爭、宗教和教育都曾鼓勵人們到外地旅行。"},{"en":"This phrase is broader and more historical than simply saying tourism.","zh":"這個短語比 tourism 更廣泛，也更有歷史感。"}],"source":"158 - Travel Accounts.pdf","sourcePage":6},{"front":"Muslim merchants","meaning":"穆斯林商人","examples":[{"en":"Muslim merchants sought trading opportunities across the eastern hemisphere.","zh":"穆斯林商人在東半球各地尋找貿易機會。"},{"en":"Muslim merchants were traders who belonged to Islamic societies or followed Islam.","zh":"Muslim merchants 指屬於伊斯蘭社會或信奉伊斯蘭教的商人。"},{"en":"Muslim merchants carried goods, news, and religious ideas across long trade routes.","zh":"穆斯林商人沿長途貿易路線運送商品、消息和宗教思想。"},{"en":"Because Muslim merchants travelled widely, they often described societies others knew little about.","zh":"由於穆斯林商人廣泛旅行，他們常描述別人了解很少的社會。"},{"en":"Their accounts are important for understanding trade and cultural contact.","zh":"他們的記錄對理解貿易和文化接觸很重要。"}],"source":"158 - Travel Accounts.pdf","sourcePage":6},{"front":"seek trading opportunities","meaning":"尋找貿易機會","examples":[{"en":"Merchants sought trading opportunities in distant regions.","zh":"商人在遙遠地區尋找貿易機會。"},{"en":"To seek trading opportunities means to look for chances to buy, sell, or exchange goods profitably.","zh":"seek trading opportunities 指尋找有利可圖地買賣或交換商品的機會。"},{"en":"A company may seek trading opportunities in a growing overseas market.","zh":"公司可能在正在增長的海外市場尋找貿易機會。"},{"en":"Merchants seek trading opportunities when local demand is too small.","zh":"當本地需求太小時，商人會尋找貿易機會。"},{"en":"This phrase connects travel with business purpose.","zh":"這個短語把旅行與商業目的連繫起來。"}],"source":"158 - Travel Accounts.pdf","sourcePage":6},{"front":"throughout much of","meaning":"遍及……大部分地區","examples":[{"en":"Muslim merchants travelled throughout much of the eastern hemisphere.","zh":"穆斯林商人的旅行遍及東半球大部分地區。"},{"en":"Throughout much of a place means across a large part of it.","zh":"throughout much of a place 指遍及該地方的大部分。"},{"en":"Heavy rain spread throughout much of the city by evening.","zh":"到晚上，大雨蔓延至城市大部分地區。"},{"en":"A popular song may be heard throughout much of a country.","zh":"一首流行歌曲可能在一個國家大部分地區都聽得到。"},{"en":"This phrase suggests wide coverage, though not necessarily every single area.","zh":"這個短語表示範圍廣，但不一定包括每一處。"}],"source":"158 - Travel Accounts.pdf","sourcePage":6},{"front":"the eastern hemisphere","meaning":"東半球","examples":[{"en":"Muslim merchants travelled across the eastern hemisphere.","zh":"穆斯林商人穿越東半球旅行。"},{"en":"The eastern hemisphere is the half of the world that includes Asia, Africa, Europe, and Australia.","zh":"the eastern hemisphere 指包括亞洲、非洲、歐洲和澳洲的世界東半部分。"},{"en":"Trade routes in the eastern hemisphere connected ports, deserts, and inland markets.","zh":"東半球的貿易路線連接港口、沙漠和內陸市場。"},{"en":"The eastern hemisphere was important because many ancient civilisations interacted there.","zh":"東半球很重要，因為許多古代文明在那裡互動。"},{"en":"This phrase is geographical, but it is often used in broad historical discussion.","zh":"這個短語屬地理用語，但常用於廣泛歷史討論。"}],"source":"158 - Travel Accounts.pdf","sourcePage":7},{"front":"commercial products","meaning":"商業產品","examples":[{"en":"Merchants described the commercial products of the Indian Ocean basin.","zh":"商人描述印度洋盆地的商業產品。"},{"en":"Commercial products are goods bought, sold, or exchanged in trade.","zh":"commercial products 指在貿易中被購買、出售或交換的商品。"},{"en":"Commercial products in a market may include cloth, spices, tools, and food.","zh":"市場中的商業產品可能包括布料、香料、工具和食物。"},{"en":"Knowing local commercial products helps traders decide what to buy and sell.","zh":"了解本地商業產品幫助商人決定買賣甚麼。"},{"en":"Travel accounts often mention commercial products because merchants cared about profit.","zh":"旅行記錄常提到商業產品，因為商人關心利潤。"}],"source":"158 - Travel Accounts.pdf","sourcePage":7},{"front":"the Indian Ocean basin","meaning":"印度洋盆地","examples":[{"en":"Muslim merchants described societies around the Indian Ocean basin.","zh":"穆斯林商人描述印度洋盆地周圍的社會。"},{"en":"The Indian Ocean basin is the region of lands and seas connected by the Indian Ocean.","zh":"the Indian Ocean basin 指由印度洋連接的陸地和海域地區。"},{"en":"Ports in the Indian Ocean basin traded spices, textiles, metals, and ideas.","zh":"印度洋盆地的港口交易香料、紡織品、金屬和思想。"},{"en":"The Indian Ocean basin linked East Africa, Arabia, India, Southeast Asia, and beyond.","zh":"印度洋盆地連接東非、阿拉伯、印度、東南亞及更遠地區。"},{"en":"This phrase describes a wide connected trading world, not just the ocean water.","zh":"這個短語描述一個廣闊連繫的貿易世界，而不只是海水本身。"}],"source":"158 - Travel Accounts.pdf","sourcePage":7},{"front":"from East Africa to Indonesia","meaning":"從東非到印尼","examples":[{"en":"The accounts covered regions from East Africa to Indonesia.","zh":"這些記錄涵蓋從東非到印尼的地區。"},{"en":"From East Africa to Indonesia means across a very wide area of the Indian Ocean world.","zh":"from East Africa to Indonesia 表示跨越印度洋世界的廣闊地區。"},{"en":"Trade routes from East Africa to Indonesia carried goods, languages, and religious ideas.","zh":"從東非到印尼的貿易路線運送商品、語言和宗教思想。"},{"en":"A travel study covering places from East Africa to Indonesia would include many different cultures.","zh":"涵蓋從東非到印尼的旅行研究會包括許多不同文化。"},{"en":"This phrase shows the large geographical range of the accounts.","zh":"這個短語顯示記錄的地理範圍很大。"}],"source":"158 - Travel Accounts.pdf","sourcePage":7},{"front":"supply written accounts of","meaning":"提供……的書面記錄","examples":[{"en":"Muslim merchants supplied the first written accounts of some societies.","zh":"穆斯林商人提供了某些社會的最早書面記錄。"},{"en":"To supply written accounts of something means to provide written descriptions or reports about it.","zh":"supply written accounts of something 指提供有關某事的書面描述或報告。"},{"en":"Nurses may supply written accounts of patient care after each shift.","zh":"護士可能在每次輪班後提供病人護理的書面記錄。"},{"en":"Travellers supplied written accounts of distant markets when few maps existed.","zh":"當地圖很少時，旅行者提供了遙遠市場的書面記錄。"},{"en":"This phrase stresses that information was recorded in writing, not only spoken.","zh":"這個短語強調資料被寫下來，而不只是口頭傳達。"}],"source":"158 - Travel Accounts.pdf","sourcePage":7},{"front":"sub-Saharan West Africa","meaning":"撒哈拉以南西非","examples":[{"en":"Merchants described societies in sub-Saharan West Africa.","zh":"商人描述撒哈拉以南西非的社會。"},{"en":"Sub-Saharan West Africa means the western part of Africa lying south of the Sahara Desert.","zh":"sub-Saharan West Africa 指位於撒哈拉沙漠以南的非洲西部。"},{"en":"Trade connected sub-Saharan West Africa with North Africa and the Mediterranean world.","zh":"貿易把撒哈拉以南西非與北非和地中海世界連接起來。"},{"en":"Gold, salt, and caravan routes made sub-Saharan West Africa historically important.","zh":"黃金、鹽和商隊路線令撒哈拉以南西非在歷史上重要。"},{"en":"This phrase is geographical and helps distinguish the region from North Africa.","zh":"這個地理短語有助把該地區與北非區分開來。"}],"source":"158 - Travel Accounts.pdf","sourcePage":7},{"front":"set out in search of","meaning":"出發尋找","examples":[{"en":"Merchants set out in search of trade and profit.","zh":"商人出發尋找貿易和利潤。"},{"en":"To set out in search of something means to begin a journey or effort to find it.","zh":"set out in search of something 指開始旅程或努力去尋找某物。"},{"en":"A family may set out in search of safer housing after a flood.","zh":"洪水後，一個家庭可能出發尋找更安全的住房。"},{"en":"Researchers set out in search of evidence before writing a report.","zh":"研究人員在撰寫報告前出發尋找證據。"},{"en":"This phrase suggests purposeful movement from the beginning.","zh":"這個短語表示從一開始就有明確目的的行動。"}],"source":"158 - Travel Accounts.pdf","sourcePage":7},{"front":"trade and profit","meaning":"貿易和利潤","examples":[{"en":"Merchants travelled in search of trade and profit.","zh":"商人旅行是為了尋找貿易和利潤。"},{"en":"Trade and profit refer to commercial exchange and the money gained from it.","zh":"trade and profit 指商業交換以及從中獲得的金錢收益。"},{"en":"A shop owner may open a second branch for trade and profit.","zh":"店主可能為了貿易和利潤開設第二間分店。"},{"en":"The search for trade and profit can encourage people to take risks and travel far.","zh":"對貿易和利潤的追求可以鼓勵人們冒險並遠行。"},{"en":"This phrase shows an economic motive rather than a religious or personal one.","zh":"這個短語顯示經濟動機，而不是宗教或個人動機。"}],"source":"158 - Travel Accounts.pdf","sourcePage":7},{"front":"devout Muslims","meaning":"虔誠的穆斯林","examples":[{"en":"Devout Muslims travelled as pilgrims to Mecca.","zh":"虔誠的穆斯林以朝聖者身份前往麥加。"},{"en":"Devout Muslims are Muslims who are deeply committed to their religious faith and practice.","zh":"devout Muslims 指深切投入伊斯蘭信仰和實踐的穆斯林。"},{"en":"Devout Muslims may pray regularly, fast during Ramadan, and give to charity.","zh":"虔誠的穆斯林可能定期祈禱、在齋月禁食，並捐助慈善。"},{"en":"Devout Muslims may save money for years to make the hajj.","zh":"虔誠的穆斯林可能多年儲錢以進行朝覲。"},{"en":"The word devout shows sincere religious commitment, not only identity.","zh":"devout 一詞表示真誠的宗教投入，而不只是身份。"}],"source":"158 - Travel Accounts.pdf","sourcePage":7},{"front":"travel as pilgrims","meaning":"以朝聖者身份旅行","examples":[{"en":"Devout Muslims travelled as pilgrims to Mecca.","zh":"虔誠的穆斯林以朝聖者身份前往麥加。"},{"en":"To travel as pilgrims means to journey to a holy place for religious purposes.","zh":"travel as pilgrims 指為宗教目的前往聖地旅行。"},{"en":"Many believers travel as pilgrims to temples, churches, shrines, or sacred mountains.","zh":"許多信徒以朝聖者身份前往寺廟、教堂、神社或聖山。"},{"en":"People who travel as pilgrims often pray, reflect, and follow religious customs.","zh":"以朝聖者身份旅行的人常祈禱、反思並遵守宗教習俗。"},{"en":"This phrase describes the role of the traveller, not just the destination.","zh":"這個短語描述旅行者的身份，而不只是目的地。"}],"source":"158 - Travel Accounts.pdf","sourcePage":7},{"front":"make their hajj","meaning":"進行朝覲","examples":[{"en":"Muslims travelled to Mecca to make their hajj.","zh":"穆斯林前往麥加進行朝覲。"},{"en":"To make their hajj means to complete the Islamic pilgrimage to Mecca.","zh":"make their hajj 指完成前往麥加的伊斯蘭朝聖。"},{"en":"A family may plan for years before they can make their hajj.","zh":"一個家庭可能計劃多年，才能進行朝覲。"},{"en":"Making the hajj can be a deeply meaningful moment in a Muslim’s life.","zh":"進行朝覲可以是穆斯林生命中深具意義的時刻。"},{"en":"This phrase is specific to Islam and should not be used for every pilgrimage.","zh":"這個短語專指伊斯蘭教，不應用於所有朝聖。"}],"source":"158 - Travel Accounts.pdf","sourcePage":7},{"front":"holy sites","meaning":"聖地","examples":[{"en":"Pilgrims travelled to visit the holy sites of Islam.","zh":"朝聖者前往參觀伊斯蘭教的聖地。"},{"en":"Holy sites are places considered sacred or spiritually important by a religion.","zh":"holy sites 指被宗教視為神聖或具有精神重要性的地方。"},{"en":"Visitors should behave respectfully when entering holy sites.","zh":"訪客進入聖地時應尊重當地。"},{"en":"Holy sites can attract pilgrims, historians, tourists, and local worshippers.","zh":"聖地可以吸引朝聖者、歷史學家、遊客和本地信徒。"},{"en":"These places matter because they connect faith with memory and place.","zh":"這些地方很重要，因為它們把信仰、記憶和地方連接起來。"}],"source":"158 - Travel Accounts.pdf","sourcePage":8},{"front":"the prophet Muhammad","meaning":"先知穆罕默德","examples":[{"en":"Many Muslims followed the prophet Muhammad’s example.","zh":"許多穆斯林效法先知穆罕默德的榜樣。"},{"en":"The prophet Muhammad is the central prophet of Islam.","zh":"the prophet Muhammad 指伊斯蘭教的核心先知。"},{"en":"Muslims study the prophet Muhammad’s life to understand faith, conduct, and community.","zh":"穆斯林研究先知穆罕默德的一生，以理解信仰、行為和社群。"},{"en":"His pilgrimage became an important model for later Muslim practice.","zh":"他的朝聖成為後來穆斯林實踐的重要模式。"},{"en":"This phrase should be used respectfully because it refers to a major religious figure.","zh":"這個短語應尊重地使用，因為它指一位重要宗教人物。"}],"source":"158 - Travel Accounts.pdf","sourcePage":8},{"front":"original pilgrimage","meaning":"最初的朝聖","examples":[{"en":"Muhammad’s original pilgrimage became a model for later pilgrims.","zh":"穆罕默德最初的朝聖成為後來朝聖者的榜樣。"},{"en":"Original pilgrimage means the first or earliest pilgrimage that later people followed as an example.","zh":"original pilgrimage 指最早或最初的朝聖，後來的人以此為例。"},{"en":"A founder’s original pilgrimage may shape how later believers travel and pray.","zh":"創始人的最初朝聖可能塑造後來信徒如何旅行和祈禱。"},{"en":"Original pilgrimage stories can explain why certain routes and rituals became important.","zh":"最初朝聖的故事可以解釋為何某些路線和儀式變得重要。"},{"en":"The word original shows that later journeys were based on an earlier example.","zh":"original 一詞顯示後來的旅程基於較早的例子。"}],"source":"158 - Travel Accounts.pdf","sourcePage":8},{"front":"untold millions of","meaning":"數以百萬計；無數","examples":[{"en":"Untold millions of Muslims have followed his example.","zh":"無數穆斯林效法他的榜樣。"},{"en":"Untold millions of people means countless millions, too many to count exactly.","zh":"untold millions of people 指數以百萬計、難以準確計算的人。"},{"en":"Untold millions of viewers watched the historic event on television.","zh":"無數觀眾在電視上觀看這件歷史事件。"},{"en":"A disease may affect untold millions of people if it spreads unchecked.","zh":"如果疾病不受控制地傳播，可能影響數以百萬計的人。"},{"en":"This phrase emphasises a very large number rather than a precise statistic.","zh":"這個短語強調數量極大，而不是精確統計。"}],"source":"158 - Travel Accounts.pdf","sourcePage":8},{"front":"follow one’s example","meaning":"效法某人","examples":[{"en":"Many pilgrims followed Muhammad’s example.","zh":"許多朝聖者效法穆罕默德的榜樣。"},{"en":"To follow one’s example means to act in a similar way because that person is respected or trusted.","zh":"follow one’s example 指因尊敬或信任某人而以相似方式行動。"},{"en":"Younger students may follow a captain’s example by training seriously.","zh":"年幼學生可能效法隊長，認真訓練。"},{"en":"Children often follow their parents’ example more than their advice.","zh":"孩子常效法父母的榜樣，多於聽從父母的建議。"},{"en":"This phrase is about imitation based on influence, not simply copying without thought.","zh":"這個短語指基於影響力的仿效，而不是毫無思考地照抄。"}],"source":"158 - Travel Accounts.pdf","sourcePage":8},{"front":"hajj accounts","meaning":"朝覲記錄","examples":[{"en":"Thousands of hajj accounts have related pilgrims’ experiences.","zh":"數以千計的朝覲記錄敘述了朝聖者的經歷。"},{"en":"Hajj accounts are written or spoken records of Muslims’ pilgrimage to Mecca.","zh":"hajj accounts 指穆斯林前往麥加朝覲的書面或口頭記錄。"},{"en":"Hajj accounts may describe travel routes, prayers, crowds, hardship, and joy.","zh":"朝覲記錄可能描述旅行路線、祈禱、人群、艱辛和喜悅。"},{"en":"Hajj accounts help later readers understand the spiritual and practical sides of pilgrimage.","zh":"朝覲記錄幫助後來讀者理解朝聖的精神和實際面向。"},{"en":"They are one special type of religious travel writing.","zh":"它們是宗教旅行文學的一種特殊類型。"}],"source":"158 - Travel Accounts.pdf","sourcePage":8},{"front":"relate one’s experiences","meaning":"敘述某人的經歷","examples":[{"en":"Hajj accounts related the experiences of Muslim pilgrims.","zh":"朝覲記錄敘述了穆斯林朝聖者的經歷。"},{"en":"To relate one’s experiences means to tell or describe what one went through.","zh":"relate one’s experiences 指講述或描述自己經歷過的事情。"},{"en":"A patient may relate their experiences to help doctors understand symptoms.","zh":"病人可能敘述自己的經歷，幫助醫生了解症狀。"},{"en":"Travellers relate their experiences so others can learn from their journeys.","zh":"旅行者敘述自己的經歷，讓別人可以從旅程中學習。"},{"en":"This phrase is more formal than simply say what happened.","zh":"這個短語比 simply say what happened 更正式。"}],"source":"158 - Travel Accounts.pdf","sourcePage":8},{"front":"one of the best known","meaning":"最著名的……之一","examples":[{"en":"Ibn Battuta was one of the best known Muslim travellers.","zh":"伊本·白圖泰是最著名的穆斯林旅行者之一。"},{"en":"One of the best known means among the most famous or widely recognised.","zh":"one of the best known 表示屬於最有名或最廣為人知的一類。"},{"en":"Shakespeare is one of the best known writers in English literature.","zh":"莎士比亞是英國文學中最著名的作家之一。"},{"en":"A landmark becomes one of the best known places in a city when many visitors recognise it.","zh":"當許多訪客都認得某個地標，它便成為城市中最著名的地方之一。"},{"en":"This phrase compares someone or something with other famous examples in the same group.","zh":"這個短語把某人或某物與同類中其他著名例子作比較。"}],"source":"158 - Travel Accounts.pdf","sourcePage":8},{"front":"begin one’s travels with","meaning":"以……開始旅行","examples":[{"en":"Ibn Battuta began his travels with the hajj.","zh":"伊本·白圖泰以朝覲開始他的旅行。"},{"en":"To begin one’s travels with something means to start a journey or series of journeys by doing that thing first.","zh":"begin one’s travels with something 指先做某事來開始一段旅程或一系列旅行。"},{"en":"A tourist may begin her travels with a visit to the capital city.","zh":"遊客可能以參觀首都開始她的旅行。"},{"en":"Students often begin their travels with a short exchange programme before studying abroad longer.","zh":"學生常以短期交流計劃開始旅行，之後再長期留學。"},{"en":"This phrase shows the first stage of a wider journey.","zh":"這個短語顯示更大旅程的第一階段。"}],"source":"158 - Travel Accounts.pdf","sourcePage":8},{"front":"go on to visit","meaning":"繼續前往","examples":[{"en":"Ibn Battuta went on to visit Central Asia, India and China.","zh":"伊本·白圖泰繼續前往中亞、印度和中國。"},{"en":"To go on to visit a place means to visit it later after doing something else first.","zh":"go on to visit a place 指在先做別的事情後，之後再前往某地。"},{"en":"After seeing Paris, the family went on to visit Rome.","zh":"參觀巴黎後，這家人繼續前往羅馬。"},{"en":"A researcher may interview local officials and then go on to visit nearby villages.","zh":"研究人員可能訪問本地官員，然後繼續前往附近村莊。"},{"en":"This phrase is useful for showing the next step in a journey.","zh":"這個短語適合用來顯示旅程的下一步。"}],"source":"158 - Travel Accounts.pdf","sourcePage":8},{"front":"return finally to","meaning":"最終回到","examples":[{"en":"Ibn Battuta finally returned to his home in Morocco.","zh":"伊本·白圖泰最終回到他在摩洛哥的家。"},{"en":"To return finally to a place means to come back there at the end of a long process or journey.","zh":"return finally to a place 指在漫長過程或旅程結束時回到某地。"},{"en":"After years abroad, she returned finally to her hometown.","zh":"在海外多年後，她最終回到家鄉。"},{"en":"A long journey may return finally to its starting point.","zh":"一段長旅程可能最終回到起點。"},{"en":"This phrase gives a sense of completion after many events.","zh":"這個短語在許多事件後帶出完成感。"}],"source":"158 - Travel Accounts.pdf","sourcePage":8},{"front":"not quite so prominent as","meaning":"不及……那樣突出","examples":[{"en":"East Asian travellers were not quite so prominent as Muslims.","zh":"東亞旅行者不及穆斯林那樣突出。"},{"en":"Not quite so prominent as means less important, visible, or well-known than another group.","zh":"not quite so prominent as 表示不如另一個群體那麼重要、明顯或知名。"},{"en":"The second speaker was not quite so prominent as the keynote speaker.","zh":"第二位講者不及主題演講者那樣突出。"},{"en":"A small local festival may be not quite so prominent as a national holiday.","zh":"小型本地節日可能不及全國假期那樣突出。"},{"en":"This phrase makes a careful comparison without saying something is unimportant.","zh":"這個短語作出謹慎比較，而不是說某事不重要。"}],"source":"158 - Travel Accounts.pdf","sourcePage":9},{"front":"follow highways and sea lanes","meaning":"沿着道路和海上航線前行","examples":[{"en":"East Asian travellers followed highways and sea lanes.","zh":"東亞旅行者沿着道路和海上航線前行。"},{"en":"To follow highways and sea lanes means to travel along established land and sea routes.","zh":"follow highways and sea lanes 指沿既有陸路和海路旅行。"},{"en":"Traders followed highways and sea lanes to reach markets safely and efficiently.","zh":"商人沿着道路和海上航線前往市場，既安全又有效率。"},{"en":"Reliable highways and sea lanes can increase trade between distant regions.","zh":"可靠的道路和海上航線可以增加遙遠地區之間的貿易。"},{"en":"This phrase shows that travel often depended on existing routes.","zh":"這個短語顯示旅行常依賴既有路線。"}],"source":"158 - Travel Accounts.pdf","sourcePage":9},{"front":"sea lanes","meaning":"海上航線","examples":[{"en":"Merchants travelled along sea lanes of the eastern hemisphere.","zh":"商人沿東半球的海上航線旅行。"},{"en":"Sea lanes are regular routes used by ships across oceans or seas.","zh":"sea lanes 指船隻穿越海洋或海域時常用的固定路線。"},{"en":"Modern shipping companies depend on safe sea lanes for global trade.","zh":"現代航運公司依靠安全海上航線進行全球貿易。"},{"en":"When storms or wars block sea lanes, prices may rise because goods arrive late.","zh":"當風暴或戰爭阻塞海上航線，貨物延遲到達，價格可能上升。"},{"en":"Sea lanes are like roads on water, connecting ports and markets.","zh":"海上航線就像水上的道路，連接港口和市場。"}],"source":"158 - Travel Accounts.pdf","sourcePage":9},{"front":"frequently visited","meaning":"經常到訪","examples":[{"en":"Chinese merchants frequently visited Southeast Asia and India.","zh":"中國商人經常到訪東南亞和印度。"},{"en":"Frequently visited means went to a place often or many times.","zh":"frequently visited 表示經常或多次到某地。"},{"en":"The library is frequently visited by students before exams.","zh":"考試前，圖書館經常有學生到訪。"},{"en":"A doctor may frequently visit elderly patients who cannot travel easily.","zh":"醫生可能經常探訪不便出行的長者病人。"},{"en":"This phrase shows repeated contact, not a single trip.","zh":"這個短語表示重複接觸，而不是一次旅行。"}],"source":"158 - Travel Accounts.pdf","sourcePage":9},{"front":"Southeast Asia","meaning":"東南亞","examples":[{"en":"Chinese merchants frequently visited Southeast Asia.","zh":"中國商人經常到訪東南亞。"},{"en":"Southeast Asia is the region including countries such as Vietnam, Thailand, Malaysia, Indonesia, and the Philippines.","zh":"Southeast Asia 指包括越南、泰國、馬來西亞、印尼和菲律賓等國家的地區。"},{"en":"Southeast Asia has long been important for maritime trade.","zh":"東南亞長期對海上貿易十分重要。"},{"en":"Merchants visited Southeast Asia because its ports connected China, India, and the wider ocean world.","zh":"商人到訪東南亞，因為其港口連接中國、印度和更廣闊的海洋世界。"},{"en":"The phrase refers to a region with many different languages, religions, and cultures.","zh":"這個短語指一個擁有許多不同語言、宗教和文化的地區。"}],"source":"158 - Travel Accounts.pdf","sourcePage":9},{"front":"occasionally venturing even to","meaning":"偶爾甚至冒險前往","examples":[{"en":"Chinese merchants occasionally ventured even to East Africa.","zh":"中國商人偶爾甚至冒險前往東非。"},{"en":"Occasionally venturing even to a place means sometimes travelling as far as a surprising or distant place.","zh":"occasionally venturing even to a place 指有時甚至前往令人意外或遙遠的地方。"},{"en":"A hiking group may occasionally venture even to remote mountain villages.","zh":"遠足隊可能偶爾甚至冒險前往偏遠山村。"},{"en":"Merchants occasionally ventured even to dangerous ports when profits were high.","zh":"當利潤很高時，商人偶爾甚至冒險前往危險港口。"},{"en":"This phrase highlights that the journey was not common, but it did happen.","zh":"這個短語強調旅程並不常見，但確實發生過。"}],"source":"158 - Travel Accounts.pdf","sourcePage":9},{"front":"undertake distant pilgrimages","meaning":"進行遠途朝聖","examples":[{"en":"East Asian Buddhists undertook distant pilgrimages.","zh":"東亞佛教徒進行遠途朝聖。"},{"en":"To undertake distant pilgrimages means to make long religious journeys to sacred places.","zh":"undertake distant pilgrimages 指前往遙遠聖地進行宗教旅程。"},{"en":"Some believers undertake distant pilgrimages to learn from respected teachers.","zh":"有些信徒進行遠途朝聖，以向受尊敬的老師學習。"},{"en":"Distant pilgrimages require planning because travellers may face danger, cost, and exhaustion.","zh":"遠途朝聖需要計劃，因為旅行者可能面對危險、費用和疲憊。"},{"en":"This phrase suggests serious religious commitment and physical effort.","zh":"這個短語表示認真的宗教投入和體力付出。"}],"source":"158 - Travel Accounts.pdf","sourcePage":9},{"front":"between the 5th and 9th centuries CE","meaning":"在公元5至9世紀之間","examples":[{"en":"Many Chinese Buddhists travelled to India between the 5th and 9th centuries CE.","zh":"許多中國佛教徒在公元5至9世紀之間前往印度。"},{"en":"Between the 5th and 9th centuries CE means during the period from the 400s to the 800s in the Common Era.","zh":"between the 5th and 9th centuries CE 指公元400年代至800年代之間。"},{"en":"Many religious texts moved across Asia between the 5th and 9th centuries CE.","zh":"許多宗教典籍在公元5至9世紀之間於亞洲各地流傳。"},{"en":"This date phrase helps readers place travel in a clear historical period.","zh":"這個日期短語幫助讀者把旅行放在清楚的歷史時期中。"},{"en":"It is more precise than saying in ancient or medieval times.","zh":"它比說 ancient 或 medieval times 更精確。"}],"source":"158 - Travel Accounts.pdf","sourcePage":9},{"front":"sacred texts","meaning":"神聖典籍","examples":[{"en":"Buddhists travelled to India to collect sacred texts.","zh":"佛教徒前往印度收集神聖典籍。"},{"en":"Sacred texts are writings considered holy or spiritually important by a religion.","zh":"sacred texts 指被宗教視為神聖或具有精神重要性的著作。"},{"en":"Monks copied sacred texts carefully so teachings could be preserved.","zh":"僧侶仔細抄寫神聖典籍，使教義得以保存。"},{"en":"Sacred texts can guide belief, prayer, moral behaviour, and religious practice.","zh":"神聖典籍可以指導信仰、祈禱、道德行為和宗教實踐。"},{"en":"This phrase refers to religious writings, not ordinary books.","zh":"這個短語指宗教著作，而不是普通書籍。"}],"source":"158 - Travel Accounts.pdf","sourcePage":9},{"front":"written accounts recorded","meaning":"書面記錄記載了","examples":[{"en":"Written accounts recorded the experiences of many pilgrims.","zh":"書面記錄記載了許多朝聖者的經歷。"},{"en":"Written accounts recorded means that written reports preserved information about what happened.","zh":"written accounts recorded 表示書面報告保存了有關發生事情的資料。"},{"en":"Written accounts recorded how villagers survived the flood.","zh":"書面記錄記載了村民如何在洪水中生存。"},{"en":"Written accounts recorded by nurses can help doctors review a patient’s progress.","zh":"護士所寫的書面記錄可以幫助醫生檢視病人進展。"},{"en":"This phrase stresses that experiences were not only lived, but also documented.","zh":"這個短語強調經歷不只是被親身經歷，也被記錄下來。"}],"source":"158 - Travel Accounts.pdf","sourcePage":9},{"front":"though not as numerous as","meaning":"雖然數目不及……多","examples":[{"en":"Japanese and Korean Buddhists travelled abroad, though not as numerous as Chinese pilgrims.","zh":"日本和韓國佛教徒也到外地旅行，雖然數目不及中國朝聖者多。"},{"en":"Though not as numerous as means although there were fewer of one group than another.","zh":"though not as numerous as 表示雖然一個群體的數量少於另一群體。"},{"en":"Volunteers came from several schools, though not as numerous as last year.","zh":"志願者來自幾間學校，雖然數目不及去年多。"},{"en":"Local shops survived in the area, though not as numerous as chain stores.","zh":"本地小店仍在該區生存，雖然數目不及連鎖店多。"},{"en":"This phrase compares numbers while still acknowledging that the smaller group existed.","zh":"這個短語在比較數量時，也承認較小群體存在。"}],"source":"158 - Travel Accounts.pdf","sourcePage":9},{"front":"venture abroad","meaning":"前往外地；出國","examples":[{"en":"Buddhists from Japan and Korea also ventured abroad.","zh":"來自日本和韓國的佛教徒也前往外地。"},{"en":"To venture abroad means to travel to another country, often with some risk or uncertainty.","zh":"venture abroad 指到另一個國家旅行，常帶有某種風險或不確定性。"},{"en":"A young artist may venture abroad to study new techniques.","zh":"年輕藝術家可能出國學習新技術。"},{"en":"People venture abroad when they believe the journey may bring learning or opportunity.","zh":"當人們相信旅程可能帶來學習或機會時，他們會前往外地。"},{"en":"The word venture suggests more courage than simply travel.","zh":"venture 這個詞比 simply travel 更有勇氣意味。"}],"source":"158 - Travel Accounts.pdf","sourcePage":10},{"front":"in the interests of","meaning":"為了……的利益；出於……目的","examples":[{"en":"They ventured abroad in the interests of spiritual enlightenment.","zh":"他們為了精神啟迪而前往外地。"},{"en":"In the interests of something means for the purpose or benefit of that thing.","zh":"in the interests of something 指為了某事的目的或利益。"},{"en":"A school may change its rules in the interests of student safety.","zh":"學校可能為了學生安全而改變規則。"},{"en":"A family may save money in the interests of future stability.","zh":"家庭可能為了未來穩定而儲蓄。"},{"en":"This phrase sounds formal and often explains the reason for an action.","zh":"這個短語語氣正式，常用來解釋行動原因。"}],"source":"158 - Travel Accounts.pdf","sourcePage":10},{"front":"spiritual enlightenment","meaning":"精神啟迪；宗教覺悟","examples":[{"en":"Buddhists travelled in search of spiritual enlightenment.","zh":"佛教徒旅行以尋求精神啟迪。"},{"en":"Spiritual enlightenment is deep religious or inner understanding.","zh":"spiritual enlightenment 指深刻的宗教或內在理解。"},{"en":"A monk may meditate for years in search of spiritual enlightenment.","zh":"僧侶可能冥想多年，以尋求精神啟迪。"},{"en":"Pilgrimage can support spiritual enlightenment by removing people from ordinary distractions.","zh":"朝聖可以讓人離開日常干擾，從而支持宗教覺悟。"},{"en":"This phrase is about inner wisdom, not ordinary school knowledge.","zh":"這個短語關乎內在智慧，而不是普通學校知識。"}],"source":"158 - Travel Accounts.pdf","sourcePage":10},{"front":"medieval Europeans","meaning":"中世紀歐洲人","examples":[{"en":"Medieval Europeans travelled less than their Muslim and East Asian counterparts.","zh":"中世紀歐洲人旅行少於穆斯林和東亞同類人士。"},{"en":"Medieval Europeans were people living in Europe during the Middle Ages.","zh":"medieval Europeans 指生活在中世紀歐洲的人。"},{"en":"Medieval Europeans included farmers, monks, merchants, nobles, and townspeople.","zh":"中世紀歐洲人包括農民、僧侶、商人、貴族和城鎮居民。"},{"en":"Some medieval Europeans travelled for trade, pilgrimage, war, or diplomacy.","zh":"有些中世紀歐洲人因貿易、朝聖、戰爭或外交而旅行。"},{"en":"This phrase refers to a historical group, not modern Europeans.","zh":"這個短語指歷史群體，而不是現代歐洲人。"}],"source":"158 - Travel Accounts.pdf","sourcePage":10},{"front":"hit the roads","meaning":"上路；出行","examples":[{"en":"Medieval Europeans did not hit the roads in such large numbers.","zh":"中世紀歐洲人並沒有以那麼大的數量上路旅行。"},{"en":"To hit the roads means to start travelling, especially by land.","zh":"hit the roads 指開始旅行，尤其是陸路旅行。"},{"en":"Families hit the roads early to avoid holiday traffic.","zh":"家庭早早上路，以避開假日交通。"},{"en":"Young graduates may hit the roads to explore the country before starting work.","zh":"年輕畢業生可能在開始工作前上路探索國家。"},{"en":"This phrase is informal and suggests people setting out on a journey.","zh":"這個短語較非正式，表示人們出發踏上旅程。"}],"source":"158 - Travel Accounts.pdf","sourcePage":10},{"front":"in such large numbers as","meaning":"數量不像……那麼多","examples":[{"en":"Europeans did not travel in such large numbers as Muslim travellers.","zh":"歐洲人旅行的數量不像穆斯林旅行者那麼多。"},{"en":"In such large numbers as means in quantities as great as another group.","zh":"in such large numbers as 表示數量達到與另一群體一樣多。"},{"en":"Students did not join the club in such large numbers as last year.","zh":"學生加入學會的數量不像去年那麼多。"},{"en":"Tourists rarely visit small villages in such large numbers as famous cities.","zh":"遊客到訪小村莊的數量很少像到訪名城那麼多。"},{"en":"This phrase is used to compare the size of two groups or movements.","zh":"這個短語用來比較兩個群體或流動的規模。"}],"source":"158 - Travel Accounts.pdf","sourcePage":10},{"front":"counterparts","meaning":"對應的人；同類人士","examples":[{"en":"Muslim and East Asian travellers were the counterparts of medieval European travellers.","zh":"穆斯林和東亞旅行者是中世紀歐洲旅行者的同類人士。"},{"en":"Counterparts are people or things with similar roles in different places or groups.","zh":"counterparts 指在不同地方或群體中具有相似角色的人或事物。"},{"en":"A school principal may meet her counterparts from other schools.","zh":"校長可能與其他學校的同級校長會面。"},{"en":"Doctors in one country can learn from their counterparts abroad.","zh":"一個國家的醫生可以向海外同業學習。"},{"en":"This word helps compare similar roles across different societies.","zh":"這個詞幫助比較不同社會中的相似角色。"}],"source":"158 - Travel Accounts.pdf","sourcePage":10},{"front":"the early part of","meaning":"……的早期","examples":[{"en":"European travel was less common during the early part of the postclassical era.","zh":"在後古典時代的早期，歐洲旅行較不常見。"},{"en":"The early part of a period means its beginning section.","zh":"the early part of a period 指某段時期的開始部分。"},{"en":"The early part of the school year is often used to build routines.","zh":"學年的早期常用來建立日常規律。"},{"en":"Problems in the early part of a project can delay later work.","zh":"項目早期的問題可能拖延後期工作。"},{"en":"This phrase helps divide a long period into clearer stages.","zh":"這個短語幫助把長時期分成更清楚的階段。"}],"source":"158 - Travel Accounts.pdf","sourcePage":10},{"front":"gradually increasing crowds of","meaning":"逐漸增加的一群群……","examples":[{"en":"Gradually increasing crowds of Christian pilgrims travelled to holy sites.","zh":"逐漸增加的一群群基督徒朝聖者前往聖地。"},{"en":"Gradually increasing crowds of people means groups that become larger over time.","zh":"gradually increasing crowds of people 指隨時間變得越來越大的群體。"},{"en":"Gradually increasing crowds of commuters filled the station after six o’clock.","zh":"六點後，逐漸增加的通勤人群擠滿車站。"},{"en":"Gradually increasing crowds of visitors can put pressure on small towns.","zh":"逐漸增加的訪客人群可能對小鎮造成壓力。"},{"en":"This phrase shows slow growth in numbers, not a sudden rush.","zh":"這個短語表示數量慢慢增長，而不是突然湧現。"}],"source":"158 - Travel Accounts.pdf","sourcePage":10},{"front":"Christian pilgrims","meaning":"基督徒朝聖者","examples":[{"en":"Christian pilgrims travelled to Jerusalem, Rome and other sites.","zh":"基督徒朝聖者前往耶路撒冷、羅馬和其他地點。"},{"en":"Christian pilgrims are believers who travel to holy places connected with Christianity.","zh":"Christian pilgrims 指前往與基督教有關聖地的信徒。"},{"en":"Christian pilgrims may visit churches, shrines, or places linked to saints.","zh":"基督徒朝聖者可能參觀教堂、聖壇或與聖人有關的地方。"},{"en":"Christian pilgrims often travel for prayer, repentance, gratitude, or spiritual reflection.","zh":"基督徒朝聖者常為祈禱、懺悔、感恩或精神反思而旅行。"},{"en":"Their journeys show how religion shaped movement across medieval Europe.","zh":"他們的旅程顯示宗教如何塑造中世紀歐洲的流動。"}],"source":"158 - Travel Accounts.pdf","sourcePage":10},{"front":"flow to","meaning":"湧向","examples":[{"en":"Pilgrims flowed to Jerusalem and Rome.","zh":"朝聖者湧向耶路撒冷和羅馬。"},{"en":"To flow to a place means to move there steadily in large numbers.","zh":"flow to a place 指大量人穩定地移向某地。"},{"en":"Shoppers flowed to the new mall on its opening day.","zh":"新商場開幕當天，購物者湧向那裡。"},{"en":"If jobs are created, workers may flow to a growing city.","zh":"如果工作機會增加，工人可能湧向正在增長的城市。"},{"en":"This phrase compares people’s movement to water moving in one direction.","zh":"這個短語把人的流動比作水朝一個方向流動。"}],"source":"158 - Travel Accounts.pdf","sourcePage":10},{"front":"after the 12th century","meaning":"12世紀之後","examples":[{"en":"After the 12th century, medieval Europeans travelled widely.","zh":"12世紀之後，中世紀歐洲人廣泛旅行。"},{"en":"After the 12th century means from the period following the 1100s onward.","zh":"after the 12th century 指從1100年代之後開始的時期。"},{"en":"After the 12th century, some European trade networks became more active.","zh":"12世紀之後，一些歐洲貿易網絡變得更活躍。"},{"en":"This date phrase marks a change between an earlier and a later period.","zh":"這個日期短語標示早期與後期之間的變化。"},{"en":"It helps readers understand when travel became more common.","zh":"它幫助讀者理解旅行何時變得更常見。"}],"source":"158 - Travel Accounts.pdf","sourcePage":11},{"front":"travel widely","meaning":"廣泛旅行","examples":[{"en":"Merchants, pilgrims and missionaries from medieval Europe travelled widely.","zh":"來自中世紀歐洲的商人、朝聖者和傳教士廣泛旅行。"},{"en":"To travel widely means to visit many places or cover a large area.","zh":"travel widely 指到訪許多地方或涵蓋廣闊地區。"},{"en":"A journalist may travel widely to report on different communities.","zh":"記者可能廣泛旅行，以報道不同社區。"},{"en":"People who travel widely often compare customs, prices, food, and public services.","zh":"廣泛旅行的人常比較習俗、價格、食物和公共服務。"},{"en":"This phrase suggests broad experience rather than one short trip.","zh":"這個短語表示廣泛經驗，而不是一次短途旅行。"}],"source":"158 - Travel Accounts.pdf","sourcePage":11},{"front":"leave numerous travel accounts","meaning":"留下大量旅行記錄","examples":[{"en":"European travellers left numerous travel accounts.","zh":"歐洲旅行者留下大量旅行記錄。"},{"en":"To leave numerous travel accounts means to produce many written records of journeys.","zh":"leave numerous travel accounts 指留下許多旅程的書面記錄。"},{"en":"Explorers left numerous travel accounts describing rivers, mountains, and local peoples.","zh":"探險者留下大量旅行記錄，描述河流、山脈和本地人民。"},{"en":"Numerous travel accounts help historians compare different views of the same place.","zh":"大量旅行記錄幫助歷史學家比較同一地方的不同觀點。"},{"en":"This phrase shows that travel produced a large body of writing.","zh":"這個短語顯示旅行產生了大量寫作。"}],"source":"158 - Travel Accounts.pdf","sourcePage":11},{"front":"sojourn in","meaning":"在……逗留","examples":[{"en":"Marco Polo’s sojourn in China became famous.","zh":"馬可·波羅在中國的逗留變得著名。"},{"en":"A sojourn in a place is a temporary stay there.","zh":"sojourn in a place 指在某地的暫時停留。"},{"en":"A student’s sojourn in Italy may last one semester.","zh":"學生在意大利的逗留可能持續一個學期。"},{"en":"A sojourn in a foreign city can change a writer’s language, friendships, and ideas.","zh":"在外國城市的逗留可以改變作家的語言、友誼和思想。"},{"en":"This word sounds more formal or literary than stay.","zh":"這個詞比 stay 更正式或更有文學感。"}],"source":"158 - Travel Accounts.pdf","sourcePage":11},{"front":"the best known","meaning":"最著名的","examples":[{"en":"Marco Polo’s description of China is the best known European travel account.","zh":"馬可·波羅對中國的描述是最著名的歐洲旅行記錄。"},{"en":"The best known means the most famous or widely recognised.","zh":"the best known 指最有名或最廣為人知的。"},{"en":"The Eiffel Tower is probably the best known landmark in Paris.","zh":"埃菲爾鐵塔大概是巴黎最著名的地標。"},{"en":"A writer becomes the best known in a field when many people read and discuss their work.","zh":"當許多人閱讀並討論某位作家的作品時，該作家就成為某領域最著名的人。"},{"en":"This phrase identifies the most familiar example within a group.","zh":"這個短語指出一組例子中最熟悉的一個。"}],"source":"158 - Travel Accounts.pdf","sourcePage":11},{"front":"become familiar with","meaning":"熟悉","examples":[{"en":"Europeans became familiar with the larger world of the eastern hemisphere.","zh":"歐洲人逐漸熟悉東半球更廣闊的世界。"},{"en":"To become familiar with something means to learn enough about it that it no longer feels strange.","zh":"become familiar with something 指對某事了解足夠，使它不再陌生。"},{"en":"New students become familiar with school rules after a few weeks.","zh":"新學生幾週後會熟悉校規。"},{"en":"Travelling can help people become familiar with different foods, languages, and manners.","zh":"旅行可以幫助人熟悉不同食物、語言和禮儀。"},{"en":"Familiarity grows through repeated exposure and experience.","zh":"熟悉感透過反覆接觸和經驗而增長。"}],"source":"158 - Travel Accounts.pdf","sourcePage":11},{"front":"profitable commercial opportunities","meaning":"有利可圖的商業機會","examples":[{"en":"Asian and African markets offered profitable commercial opportunities.","zh":"亞洲和非洲市場提供有利可圖的商業機會。"},{"en":"Profitable commercial opportunities are business chances that can produce financial gain.","zh":"profitable commercial opportunities 指能帶來金錢收益的商業機會。"},{"en":"A growing city may offer profitable commercial opportunities for small restaurants.","zh":"正在發展的城市可能為小餐廳提供有利可圖的商業機會。"},{"en":"Merchants travel far when they believe profitable commercial opportunities exist elsewhere.","zh":"當商人相信其他地方存在有利可圖的商業機會時，他們會遠行。"},{"en":"This phrase focuses on business benefit, not cultural interest alone.","zh":"這個短語聚焦商業利益，而不只是文化興趣。"}],"source":"158 - Travel Accounts.pdf","sourcePage":11},{"front":"work to find","meaning":"努力尋找","examples":[{"en":"European peoples worked to find new routes to Asian markets.","zh":"歐洲人努力尋找通往亞洲市場的新路線。"},{"en":"To work to find something means to make serious efforts to discover or achieve it.","zh":"work to find something 指認真努力去發現或達成某事。"},{"en":"Scientists work to find safer treatments for serious diseases.","zh":"科學家努力尋找更安全的嚴重疾病治療方法。"},{"en":"A school may work to find better ways to support struggling students.","zh":"學校可能努力尋找更好方法支援學習困難的學生。"},{"en":"This phrase shows effort over time, not an easy discovery.","zh":"這個短語表示長時間努力，而不是輕易發現。"}],"source":"158 - Travel Accounts.pdf","sourcePage":11},{"front":"more direct routes to","meaning":"通往……的更直接路線","examples":[{"en":"Europeans searched for more direct routes to Asian and African markets.","zh":"歐洲人尋找通往亞洲和非洲市場的更直接路線。"},{"en":"More direct routes to a place are shorter or less complicated ways to reach it.","zh":"more direct routes to a place 指到達某地較短或較不複雜的路線。"},{"en":"Commuters want more direct routes to work so they spend less time travelling.","zh":"通勤者想要通往工作的更直接路線，從而減少交通時間。"},{"en":"Traders searched for more direct routes because middlemen and delays reduced profit.","zh":"商人尋找更直接路線，因為中間商和延誤會降低利潤。"},{"en":"This phrase shows a desire for speed, efficiency, and lower cost.","zh":"這個短語顯示對速度、效率和較低成本的追求。"}],"source":"158 - Travel Accounts.pdf","sourcePage":11},{"front":"Asian and African markets","meaning":"亞洲和非洲市場","examples":[{"en":"European merchants wanted access to Asian and African markets.","zh":"歐洲商人想進入亞洲和非洲市場。"},{"en":"Asian and African markets are places and trade networks in Asia and Africa where goods are bought and sold.","zh":"Asian and African markets 指亞洲和非洲買賣商品的地方和貿易網絡。"},{"en":"Asian and African markets offered spices, textiles, metals, ivory, and other goods.","zh":"亞洲和非洲市場提供香料、紡織品、金屬、象牙和其他商品。"},{"en":"Competition for Asian and African markets encouraged exploration and overseas expansion.","zh":"對亞洲和非洲市場的競爭鼓勵了探險和海外擴張。"},{"en":"This phrase refers to economic opportunity across two large regions.","zh":"這個短語指兩大地區的經濟機會。"}],"source":"158 - Travel Accounts.pdf","sourcePage":11},{"front":"efforts took them to","meaning":"他們的努力使他們到達……","examples":[{"en":"Their efforts took them to the Americas and Oceania.","zh":"他們的努力使他們到達美洲和大洋洲。"},{"en":"Efforts took them to a place means their attempts or plans caused them to reach that place.","zh":"efforts took them to a place 指他們的嘗試或計劃使他們到達某地。"},{"en":"Her research efforts took her to remote villages for interviews.","zh":"她的研究努力使她前往偏遠村莊進行訪問。"},{"en":"A company’s search for suppliers may take it to several countries.","zh":"公司尋找供應商的努力可能使它前往幾個國家。"},{"en":"This phrase links action and result: people try something, and it leads them somewhere.","zh":"這個短語把行動和結果連繫起來：人們嘗試某事，結果被帶到某地。"}],"source":"158 - Travel Accounts.pdf","sourcePage":11},{"front":"all parts of","meaning":"……的所有地方","examples":[{"en":"Europeans travelled to all parts of the eastern hemisphere.","zh":"歐洲人旅行到東半球的所有地方。"},{"en":"All parts of a place means every major area or region within it.","zh":"all parts of a place 指該地方內所有主要區域或地區。"},{"en":"Public health messages were sent to all parts of the city.","zh":"公共健康訊息被送到城市的所有地方。"},{"en":"A railway network can connect all parts of a country.","zh":"鐵路網絡可以連接一個國家的所有地方。"},{"en":"This phrase stresses wide coverage rather than a few selected places.","zh":"這個短語強調廣泛覆蓋，而不是少數選定地方。"}],"source":"158 - Travel Accounts.pdf","sourcePage":12},{"front":"the Americas and Oceania","meaning":"美洲和大洋洲","examples":[{"en":"European travel eventually extended to the Americas and Oceania.","zh":"歐洲旅行最終擴展到美洲和大洋洲。"},{"en":"The Americas and Oceania refer to the continents and island regions of the Western Hemisphere and Pacific world.","zh":"the Americas and Oceania 指西半球和太平洋世界的大陸及島嶼地區。"},{"en":"European ships reached the Americas and Oceania during long-distance exploration.","zh":"歐洲船隻在長途探險中到達美洲和大洋洲。"},{"en":"Contact with the Americas and Oceania changed trade, migration, disease, and colonisation.","zh":"與美洲和大洋洲的接觸改變了貿易、遷移、疾病和殖民。"},{"en":"This phrase names large world regions beyond Europe, Asia, and Africa.","zh":"這個短語指出歐洲、亞洲和非洲以外的大型世界地區。"}],"source":"158 - Travel Accounts.pdf","sourcePage":12},{"front":"dominate travel writing","meaning":"主導旅行文學","examples":[{"en":"Muslim and Chinese peoples dominated travel writing in postclassical times.","zh":"在後古典時期，穆斯林和中國人主導旅行文學。"},{"en":"To dominate travel writing means to be the leading or most influential producers of travel accounts.","zh":"dominate travel writing 指成為旅行記錄的主要或最有影響力創作者。"},{"en":"A language can dominate travel writing if many popular guidebooks are written in it.","zh":"如果許多流行旅遊指南都用某種語言寫成，該語言可能主導旅行文學。"},{"en":"Groups dominate travel writing when their journeys are recorded more often than others’.","zh":"當某些群體的旅程比其他群體更常被記錄時，他們便主導旅行文學。"},{"en":"This phrase shows unequal influence in a literary field.","zh":"這個短語顯示文學領域中的不平等影響力。"}],"source":"158 - Travel Accounts.pdf","sourcePage":12},{"front":"take centre stage","meaning":"成為焦點；佔據中心位置","examples":[{"en":"European explorers took centre stage during the early modern era.","zh":"歐洲探險者在近代早期成為焦點。"},{"en":"To take centre stage means to become the main focus of attention.","zh":"take centre stage 指成為注意力的主要焦點。"},{"en":"During the debate, climate policy took centre stage.","zh":"在辯論中，氣候政策成為焦點。"},{"en":"A quiet student may take centre stage when presenting a strong project.","zh":"安靜的學生展示出色項目時，可能佔據中心位置。"},{"en":"This phrase comes from theatre and suggests being placed in the spotlight.","zh":"這個短語來自劇場，表示被放在聚光燈下。"}],"source":"158 - Travel Accounts.pdf","sourcePage":12},{"front":"the early modern era","meaning":"近代早期","examples":[{"en":"European travellers took centre stage during the early modern era.","zh":"歐洲旅行者在近代早期成為焦點。"},{"en":"The early modern era is the period after the Middle Ages and before the modern industrial age.","zh":"the early modern era 指中世紀之後、現代工業時代之前的時期。"},{"en":"During the early modern era, overseas exploration and printing expanded rapidly.","zh":"在近代早期，海外探險和印刷迅速擴展。"},{"en":"The early modern era changed travel writing because more books reached more readers.","zh":"近代早期改變了旅行文學，因為更多書籍接觸到更多讀者。"},{"en":"This phrase helps place events in a broad historical timeline.","zh":"這個短語幫助把事件放在廣闊歷史時間線中。"}],"source":"158 - Travel Accounts.pdf","sourcePage":12},{"front":"by no means","meaning":"絕不","examples":[{"en":"By no means did Muslim and Chinese travel come to a halt.","zh":"穆斯林和中國人的旅行絕沒有停止。"},{"en":"By no means means definitely not or certainly not.","zh":"by no means 表示絕對不或當然不。"},{"en":"This task is difficult, but by no means impossible.","zh":"這項任務困難，但絕不是不可能。"},{"en":"A small mistake by no means proves that a student is careless.","zh":"一個小錯誤絕不證明學生粗心。"},{"en":"This phrase is emphatic and often used to reject an over-simple conclusion.","zh":"這個短語語氣強烈，常用來否定過度簡化的結論。"}],"source":"158 - Travel Accounts.pdf","sourcePage":12},{"front":"come to a halt","meaning":"停止","examples":[{"en":"Muslim and Chinese travel did not come to a halt.","zh":"穆斯林和中國人的旅行並沒有停止。"},{"en":"To come to a halt means to stop completely or nearly completely.","zh":"come to a halt 指完全或幾乎完全停止。"},{"en":"Traffic came to a halt after the accident blocked the tunnel.","zh":"意外阻塞隧道後，交通停止了。"},{"en":"Work may come to a halt if funding suddenly disappears.","zh":"如果資金突然消失，工作可能停頓。"},{"en":"This phrase is often used when movement, progress, or activity stops.","zh":"這個短語常用於流動、進展或活動停止時。"}],"source":"158 - Travel Accounts.pdf","sourcePage":12},{"front":"distant corners of the globe","meaning":"世界遙遠角落","examples":[{"en":"European peoples ventured to the distant corners of the globe.","zh":"歐洲人冒險前往世界遙遠角落。"},{"en":"Distant corners of the globe means very faraway parts of the world.","zh":"distant corners of the globe 指世界上非常遙遠的地方。"},{"en":"Scientists travel to distant corners of the globe to study rare plants and animals.","zh":"科學家前往世界遙遠角落研究罕見動植物。"},{"en":"Better transport has made distant corners of the globe easier to reach.","zh":"更好的交通令世界遙遠角落更容易到達。"},{"en":"This phrase suggests extreme distance and wide exploration.","zh":"這個短語表示極遠距離和廣泛探索。"}],"source":"158 - Travel Accounts.pdf","sourcePage":12},{"front":"printing presses","meaning":"印刷機","examples":[{"en":"European printing presses produced thousands of travel accounts.","zh":"歐洲印刷機製作了數以千計的旅行記錄。"},{"en":"Printing presses are machines used to print books, papers, and other written materials.","zh":"printing presses 指用來印製書籍、紙張和其他文字材料的機器。"},{"en":"Printing presses made it possible to produce many copies of the same text.","zh":"印刷機使大量複製同一文本成為可能。"},{"en":"When printing presses spread, information reached readers faster and more cheaply.","zh":"當印刷機普及，資料更快、更便宜地傳到讀者手中。"},{"en":"Printing presses changed travel writing by creating a larger reading public.","zh":"印刷機透過創造更大的閱讀大眾改變了旅行文學。"}],"source":"158 - Travel Accounts.pdf","sourcePage":12},{"front":"churn out","meaning":"大量製作；大量出版","examples":[{"en":"Printing presses churned out thousands of travel accounts.","zh":"印刷機大量出版數以千計的旅行記錄。"},{"en":"To churn out something means to produce a large amount quickly, often in a routine way.","zh":"churn out something 指快速大量生產某物，常帶有例行方式。"},{"en":"A factory can churn out thousands of bottles every hour.","zh":"工廠每小時可以大量製造數千個瓶子。"},{"en":"Publishers may churn out guidebooks when public demand is high.","zh":"當公眾需求很高，出版商可能大量出版旅遊指南。"},{"en":"This phrase can sound slightly critical if the quality seems less careful.","zh":"如果品質似乎不夠仔細，這個短語可能帶有輕微批評意味。"}],"source":"158 - Travel Accounts.pdf","sourcePage":12},{"front":"a reading public","meaning":"閱讀大眾","examples":[{"en":"Travel accounts were written for a reading public hungry for news.","zh":"旅行記錄是為渴望消息的閱讀大眾而寫。"},{"en":"A reading public is a group of people who regularly read books, newspapers, or printed material.","zh":"a reading public 指經常閱讀書籍、報紙或印刷材料的一群人。"},{"en":"A reading public grows when education and printing become more widespread.","zh":"當教育和印刷更普及，閱讀大眾便會增長。"},{"en":"Publishers study the reading public to decide what books to print.","zh":"出版商研究閱讀大眾，以決定印甚麼書。"},{"en":"This phrase refers to readers as a social group, not one individual reader.","zh":"這個短語指作為社會群體的讀者，而不是一位個別讀者。"}],"source":"158 - Travel Accounts.pdf","sourcePage":12},{"front":"an apparently insatiable appetite for","meaning":"對……似乎永不滿足的渴求","examples":[{"en":"The public had an apparently insatiable appetite for news about the larger world.","zh":"公眾對更廣闊世界的消息似乎有永不滿足的渴求。"},{"en":"An apparently insatiable appetite for something means a desire that seems impossible to satisfy.","zh":"an apparently insatiable appetite for something 指似乎無法滿足的渴望。"},{"en":"Many viewers have an apparently insatiable appetite for crime dramas.","zh":"許多觀眾對犯罪劇似乎有永不滿足的渴求。"},{"en":"An apparently insatiable appetite for cheap goods can increase pressure on workers and factories.","zh":"對廉價商品似乎永不滿足的渴求可能增加工人和工廠壓力。"},{"en":"This phrase strongly emphasises continuous demand.","zh":"這個短語強烈強調持續需求。"}],"source":"158 - Travel Accounts.pdf","sourcePage":13},{"front":"news about the larger world","meaning":"關於更廣闊世界的消息","examples":[{"en":"Readers wanted news about the larger world.","zh":"讀者想要關於更廣闊世界的消息。"},{"en":"News about the larger world is information about places and events beyond one’s local community.","zh":"news about the larger world 指有關本地社區以外地方和事件的資料。"},{"en":"Students follow news about the larger world to understand wars, elections, and climate events.","zh":"學生關注更廣闊世界的消息，以了解戰爭、選舉和氣候事件。"},{"en":"Travel books once provided news about the larger world before modern media existed.","zh":"在現代媒體出現前，旅行書曾提供關於更廣闊世界的消息。"},{"en":"This phrase connects curiosity with information from distant places.","zh":"這個短語把好奇心與遙遠地方的資訊連接起來。"}],"source":"158 - Travel Accounts.pdf","sourcePage":13},{"front":"the volume of travel literature","meaning":"旅行文學的數量","examples":[{"en":"The volume of travel literature was extremely great.","zh":"旅行文學的數量極大。"},{"en":"The volume of travel literature means the total amount of travel writing produced.","zh":"the volume of travel literature 指旅行寫作作品的總數量。"},{"en":"The volume of travel literature increased when printing became cheaper.","zh":"當印刷變得更便宜，旅行文學的數量增加。"},{"en":"A large volume of travel literature gives historians many sources to compare.","zh":"大量旅行文學給歷史學家許多來源作比較。"},{"en":"This phrase focuses on quantity, not necessarily quality.","zh":"這個短語聚焦數量，而不一定是質素。"}],"source":"158 - Travel Accounts.pdf","sourcePage":13},{"front":"assemble numerous travel accounts","meaning":"匯編大量旅行記錄","examples":[{"en":"Editors assembled numerous travel accounts into large collections.","zh":"編者把大量旅行記錄匯編成大型文集。"},{"en":"To assemble numerous travel accounts means to gather many travel writings together.","zh":"assemble numerous travel accounts 指把許多旅行作品收集在一起。"},{"en":"A teacher may assemble numerous student essays into a class booklet.","zh":"老師可能把大量學生文章匯編成班級小冊子。"},{"en":"Editors assemble numerous travel accounts when readers want many journeys in one book.","zh":"當讀者想在一本書中看到許多旅程時，編者會匯編大量旅行記錄。"},{"en":"This phrase highlights organisation and collection, not writing from scratch.","zh":"這個短語強調整理和收集，而不是從零開始寫作。"}],"source":"158 - Travel Accounts.pdf","sourcePage":13},{"front":"make them available","meaning":"使它們可供取得","examples":[{"en":"Editors made travel accounts available in published collections.","zh":"編者把旅行記錄製成出版文集，使它們可供取得。"},{"en":"To make something available means to allow people to get, read, use, or buy it.","zh":"make something available 指讓人能取得、閱讀、使用或購買某物。"},{"en":"Schools make online lessons available to students who are absent.","zh":"學校把網上課堂提供給缺席學生使用。"},{"en":"Libraries make old newspapers available by scanning them into digital archives.","zh":"圖書館把舊報紙掃描成數碼檔案，使它們可供查閱。"},{"en":"This phrase focuses on access.","zh":"這個短語重點在於取得途徑。"}],"source":"158 - Travel Accounts.pdf","sourcePage":13},{"front":"enormous published collections","meaning":"大型出版文集","examples":[{"en":"Travel accounts appeared in enormous published collections.","zh":"旅行記錄出現在大型出版文集中。"},{"en":"Enormous published collections are very large printed sets of writings or documents.","zh":"enormous published collections 指非常大型的印刷作品或文件集。"},{"en":"A library may hold enormous published collections of letters, maps, and diaries.","zh":"圖書館可能收藏大型出版文集，內含書信、地圖和日記。"},{"en":"Enormous published collections help readers access many sources in one place.","zh":"大型出版文集幫助讀者在一處接觸許多來源。"},{"en":"This phrase suggests both great size and formal publication.","zh":"這個短語同時表示規模巨大和正式出版。"}],"source":"158 - Travel Accounts.pdf","sourcePage":13},{"front":"make one’s way to","meaning":"前往","examples":[{"en":"European travellers made their way to the interior regions of Africa.","zh":"歐洲旅行者前往非洲內陸地區。"},{"en":"To make one’s way to a place means to travel there, often with some effort.","zh":"make one’s way to a place 指前往某地，常帶有一定努力。"},{"en":"After the storm, villagers made their way to the shelter.","zh":"風暴後，村民前往避難所。"},{"en":"A student may make her way to school through crowded streets.","zh":"學生可能穿過擁擠街道前往學校。"},{"en":"This phrase suggests movement step by step rather than instant arrival.","zh":"這個短語表示一步步移動，而不是瞬間到達。"}],"source":"158 - Travel Accounts.pdf","sourcePage":13},{"front":"interior regions","meaning":"內陸地區","examples":[{"en":"European travellers entered interior regions of Africa and the Americas.","zh":"歐洲旅行者進入非洲和美洲的內陸地區。"},{"en":"Interior regions are inland areas far from coasts or borders.","zh":"interior regions 指遠離海岸或邊界的內陸地區。"},{"en":"Farmers in interior regions may face higher transport costs than coastal cities.","zh":"內陸地區的農民可能比沿海城市面對更高運輸成本。"},{"en":"Explorers entered interior regions to find rivers, resources, and new routes.","zh":"探險者進入內陸地區尋找河流、資源和新路線。"},{"en":"This phrase contrasts inland areas with coastal or outer areas.","zh":"這個短語把內陸地區與沿海或外圍地區作對比。"}],"source":"158 - Travel Accounts.pdf","sourcePage":13},{"front":"generate a fresh round of","meaning":"產生新一輪……","examples":[{"en":"New journeys generated a fresh round of travel writing.","zh":"新旅程產生新一輪旅行寫作。"},{"en":"To generate a fresh round of something means to cause a new series of it to appear.","zh":"generate a fresh round of something 指促成新一系列某事出現。"},{"en":"A new exam policy may generate a fresh round of debate among parents.","zh":"新考試政策可能在家長之間產生新一輪辯論。"},{"en":"A major discovery can generate a fresh round of research.","zh":"重大發現可以產生新一輪研究。"},{"en":"This phrase shows that one event creates another wave of activity.","zh":"這個短語顯示一件事引發另一波活動。"}],"source":"158 - Travel Accounts.pdf","sourcePage":13},{"front":"as they did so","meaning":"在這樣做時","examples":[{"en":"Travellers generated new accounts as they did so.","zh":"旅行者在這樣做時產生新的記錄。"},{"en":"As they did so means while they were doing that action.","zh":"as they did so 指在他們做那個行動的同時。"},{"en":"The students cleaned the classroom and, as they did so, found a lost notebook.","zh":"學生打掃課室時，發現了一本遺失的筆記簿。"},{"en":"Researchers interviewed villagers and, as they did so, discovered new questions.","zh":"研究人員訪問村民時，發現了新的問題。"},{"en":"This phrase connects a main action with something that happened during it.","zh":"這個短語把主要行動與期間發生的事情連接起來。"}],"source":"158 - Travel Accounts.pdf","sourcePage":13},{"front":"meanwhile","meaning":"與此同時","examples":[{"en":"Meanwhile, colonial administrators wrote about the societies they ruled.","zh":"與此同時，殖民地行政官員寫作關於他們統治的社會。"},{"en":"Meanwhile means at the same time or during the same period.","zh":"meanwhile 表示同時或在同一時期。"},{"en":"The children studied at home; meanwhile, their parents prepared dinner.","zh":"孩子在家學習；與此同時，父母準備晚餐。"},{"en":"A city may build new roads; meanwhile, old buses still need repair.","zh":"城市可能興建新道路；與此同時，舊巴士仍需要維修。"},{"en":"This word helps show two events happening in parallel.","zh":"這個詞幫助顯示兩件事並行發生。"}],"source":"158 - Travel Accounts.pdf","sourcePage":13},{"front":"colonial administrators","meaning":"殖民地行政官員","examples":[{"en":"Colonial administrators wrote works about colonial societies.","zh":"殖民地行政官員寫作關於殖民地社會的著作。"},{"en":"Colonial administrators were officials who governed territories controlled by a foreign power.","zh":"colonial administrators 指管理受外國勢力控制領土的官員。"},{"en":"Colonial administrators collected taxes, managed laws, and reported to imperial governments.","zh":"殖民地行政官員徵稅、管理法律，並向帝國政府報告。"},{"en":"Their writings can provide information, but they may also reflect colonial bias.","zh":"他們的著作可以提供資料，但也可能反映殖民偏見。"},{"en":"This term belongs to the history of empire and colonial rule.","zh":"這個詞屬於帝國和殖民統治的歷史。"}],"source":"158 - Travel Accounts.pdf","sourcePage":14},{"front":"devote works to","meaning":"將著作專門用於……","examples":[{"en":"Colonial administrators devoted numerous works to colonial societies.","zh":"殖民地行政官員將大量著作專門用於殖民地社會。"},{"en":"To devote works to a topic means to write books, reports, or studies mainly about it.","zh":"devote works to a topic 指寫書、報告或研究，主要探討某個主題。"},{"en":"A historian may devote works to the lives of ordinary workers.","zh":"歷史學家可能將著作專門用於普通工人的生活。"},{"en":"Writers devote works to a topic when they consider it important or worth explaining.","zh":"當作家認為某主題重要或值得解釋時，便會把作品專門用於該主題。"},{"en":"This phrase shows the main focus of written work.","zh":"這個短語顯示書面作品的主要焦點。"}],"source":"158 - Travel Accounts.pdf","sourcePage":14},{"front":"colonial subjects","meaning":"殖民地臣民","examples":[{"en":"Administrators wrote about the societies of their colonial subjects.","zh":"行政官員寫作關於其殖民地臣民的社會。"},{"en":"Colonial subjects were people living under colonial rule.","zh":"colonial subjects 指生活在殖民統治下的人。"},{"en":"Colonial subjects often had fewer political rights than citizens of the ruling power.","zh":"殖民地臣民通常比統治國公民擁有較少政治權利。"},{"en":"Writings about colonial subjects may reveal both local life and colonial control.","zh":"關於殖民地臣民的著作可能同時揭示本地生活和殖民控制。"},{"en":"This phrase should be used carefully because it reflects unequal power.","zh":"這個短語應謹慎使用，因為它反映不平等權力。"}],"source":"158 - Travel Accounts.pdf","sourcePage":14},{"front":"Asian and African colonies","meaning":"亞洲及非洲殖民地","examples":[{"en":"European powers established colonies in Asia and Africa.","zh":"歐洲列強在亞洲和非洲建立殖民地。"},{"en":"Asian and African colonies were territories in Asia and Africa controlled by foreign imperial powers.","zh":"Asian and African colonies 指亞洲和非洲受外國帝國勢力控制的領土。"},{"en":"Asian and African colonies supplied raw materials, labour, taxes, and markets to empires.","zh":"亞洲及非洲殖民地向帝國提供原材料、勞力、稅收和市場。"},{"en":"Colonial rule in Asian and African colonies changed local politics, economies, and education.","zh":"亞洲及非洲殖民地的殖民統治改變了本地政治、經濟和教育。"},{"en":"This phrase refers to territories under colonial control, not independent countries.","zh":"這個短語指受殖民控制的領土，而不是獨立國家。"}],"source":"158 - Travel Accounts.pdf","sourcePage":14},{"front":"by midcentury","meaning":"到19世紀中葉","examples":[{"en":"By midcentury, attention began to flow in the other direction.","zh":"到19世紀中葉，注意力開始朝相反方向流動。"},{"en":"By midcentury means by the middle of a particular century.","zh":"by midcentury 指到某個世紀的中期。"},{"en":"By midcentury, many cities had begun to expand beyond their old walls.","zh":"到世紀中葉，許多城市已開始擴展到舊城牆之外。"},{"en":"A country may aim to cut emissions sharply by midcentury.","zh":"一個國家可能希望到本世紀中葉大幅減排。"},{"en":"This phrase needs context because the century must be clear.","zh":"這個短語需要上下文，因為必須清楚是哪個世紀。"}],"source":"158 - Travel Accounts.pdf","sourcePage":14},{"front":"flow in the other direction","meaning":"朝相反方向流動","examples":[{"en":"Attention also began to flow in the other direction.","zh":"注意力也開始朝相反方向流動。"},{"en":"To flow in the other direction means to move back the opposite way.","zh":"flow in the other direction 指朝相反方向流動或移動。"},{"en":"After years of people leaving the village, investment began to flow in the other direction.","zh":"多年來人們離開村莊後，投資開始朝相反方向流動。"},{"en":"Information can flow in the other direction when students teach teachers about new technology.","zh":"當學生教老師新科技時，資訊可以朝相反方向流動。"},{"en":"This phrase is useful when a one-way pattern becomes two-way or reversed.","zh":"當單向模式變成雙向或逆轉時，這個短語很有用。"}],"source":"158 - Travel Accounts.pdf","sourcePage":14},{"front":"painfully aware of","meaning":"深切意識到","examples":[{"en":"Asian travellers were painfully aware of European military power.","zh":"亞洲旅行者深切意識到歐洲軍事力量。"},{"en":"To be painfully aware of something means to know it clearly and often uncomfortably.","zh":"painfully aware of something 指清楚知道某事，而且常令人不安。"},{"en":"A student who failed the exam was painfully aware of his weak grammar.","zh":"考試不合格的學生深切意識到自己的文法薄弱。"},{"en":"Small shops are painfully aware of rising rent when profits fall.","zh":"當利潤下降，小店深切意識到租金上升。"},{"en":"This phrase suggests awareness mixed with worry, embarrassment, or pressure.","zh":"這個短語表示意識中帶有憂慮、尷尬或壓力。"}],"source":"158 - Travel Accounts.pdf","sourcePage":14},{"front":"military and technological prowess","meaning":"軍事及科技實力","examples":[{"en":"Asian travellers noticed the military and technological prowess of Europe.","zh":"亞洲旅行者注意到歐洲的軍事及科技實力。"},{"en":"Military and technological prowess means great skill, strength, or achievement in warfare and technology.","zh":"military and technological prowess 指在戰爭和科技方面的高超能力、力量或成就。"},{"en":"A country’s military and technological prowess may be seen in its ships, weapons, and factories.","zh":"一個國家的軍事及科技實力可能體現在船艦、武器和工廠上。"},{"en":"Military and technological prowess can give one society power over another.","zh":"軍事及科技實力可以使一個社會對另一個社會擁有力量。"},{"en":"This phrase is formal and often used in historical or political analysis.","zh":"這個短語語氣正式，常用於歷史或政治分析。"}],"source":"158 - Travel Accounts.pdf","sourcePage":14},{"front":"Euro-American societies","meaning":"歐美社會","examples":[{"en":"Asian travellers studied European and Euro-American societies.","zh":"亞洲旅行者研究歐洲及歐美社會。"},{"en":"Euro-American societies are societies shaped mainly by European and North American institutions, cultures, or power.","zh":"Euro-American societies 指主要受歐洲和北美制度、文化或力量塑造的社會。"},{"en":"Reformers studied Euro-American societies to understand industry, education, and government.","zh":"改革者研究歐美社會，以了解工業、教育和政府。"},{"en":"Observing Euro-American societies helped some Asian writers compare systems of reform.","zh":"觀察歐美社會幫助一些亞洲作家比較改革制度。"},{"en":"This phrase groups Europe and America together for historical or cultural comparison.","zh":"這個短語把歐洲和美國放在一起作歷史或文化比較。"}],"source":"158 - Travel Accounts.pdf","sourcePage":14},{"front":"in hopes of","meaning":"希望","examples":[{"en":"Asian travellers visited Europe in hopes of discovering useful principles.","zh":"亞洲旅行者到訪歐洲，希望發現有用原則。"},{"en":"In hopes of means with the aim or wish of achieving something.","zh":"in hopes of 表示以達成某事為目標或願望。"},{"en":"Students join extra classes in hopes of improving their exam results.","zh":"學生參加補習班，希望改善考試成績。"},{"en":"A family may move to a new city in hopes of finding better work.","zh":"家庭可能搬到新城市，希望找到更好的工作。"},{"en":"This phrase shows the desired result behind an action.","zh":"這個短語顯示行動背後想達成的結果。"}],"source":"158 - Travel Accounts.pdf","sourcePage":14},{"front":"discovering principles useful for","meaning":"發現對……有用的原則","examples":[{"en":"Travellers hoped to discover principles useful for social reform.","zh":"旅行者希望發現對社會改革有用的原則。"},{"en":"Discovering principles useful for something means finding ideas or rules that can help achieve it.","zh":"discovering principles useful for something 指找到有助達成某事的想法或規則。"},{"en":"Teachers may observe other schools in hopes of discovering principles useful for better classroom management.","zh":"老師可能觀察其他學校，希望發現對改善課堂管理有用的原則。"},{"en":"Reformers looked abroad to discover principles useful for stronger government and education.","zh":"改革者向外國學習，以發現對更強政府和教育有用的原則。"},{"en":"This phrase connects learning with practical improvement.","zh":"這個短語把學習與實際改善連接起來。"}],"source":"158 - Travel Accounts.pdf","sourcePage":14},{"front":"reorganisation of","meaning":"……的重組","examples":[{"en":"Asian travellers sought principles for the reorganisation of their societies.","zh":"亞洲旅行者尋求用於重組自己社會的原則。"},{"en":"Reorganisation of something means changing its structure, order, or system.","zh":"reorganisation of something 指改變某事物的結構、秩序或制度。"},{"en":"The reorganisation of a school timetable may give students longer lunch breaks.","zh":"學校時間表的重組可能給學生更長午膳時間。"},{"en":"The reorganisation of a company can reduce waste but may worry workers.","zh":"公司的重組可以減少浪費，但可能令員工擔心。"},{"en":"This phrase is often used when large systems are rearranged.","zh":"這個短語常用於大型制度被重新安排時。"}],"source":"158 - Travel Accounts.pdf","sourcePage":15},{"front":"among the most prominent","meaning":"最突出者包括","examples":[{"en":"Fukuzawa Yukichi and Sun Yat-sen were among the most prominent travellers.","zh":"福澤諭吉和孫中山是最突出的旅行者之一。"},{"en":"Among the most prominent means included in the group of the most important or well-known.","zh":"among the most prominent 表示屬於最重要或最知名的一群。"},{"en":"Several women were among the most prominent scientists in the project.","zh":"幾位女性是該項目中最突出的科學家之一。"},{"en":"A city’s mayor may be among the most prominent voices in a public debate.","zh":"一個城市的市長可能是公共辯論中最突出的聲音之一。"},{"en":"This phrase recognises importance without saying there was only one leading figure.","zh":"這個短語承認重要性，但不表示只有一位領先人物。"}],"source":"158 - Travel Accounts.pdf","sourcePage":15},{"front":"make extensive use of","meaning":"大量運用","examples":[{"en":"Some travellers made extensive use of their overseas observations.","zh":"有些旅行者大量運用他們的海外觀察。"},{"en":"To make extensive use of something means to use it a lot and in many ways.","zh":"make extensive use of something 指大量並以多種方式使用某物。"},{"en":"Teachers make extensive use of examples when explaining difficult grammar.","zh":"老師解釋困難文法時會大量運用例子。"},{"en":"A writer may make extensive use of interviews when writing a biography.","zh":"作家寫傳記時可能大量運用訪問。"},{"en":"This phrase shows that something is not used lightly or only once.","zh":"這個短語顯示某物不是被輕微或一次性使用。"}],"source":"158 - Travel Accounts.pdf","sourcePage":15},{"front":"overseas observations and experiences","meaning":"海外觀察和經歷","examples":[{"en":"Travellers used their overseas observations and experiences in writing.","zh":"旅行者在寫作中使用他們的海外觀察和經歷。"},{"en":"Overseas observations and experiences are things people notice and go through while abroad.","zh":"overseas observations and experiences 指人們在海外注意到和親身經歷的事情。"},{"en":"A student may use overseas observations and experiences in a speech about culture shock.","zh":"學生可能在關於文化衝擊的演講中使用海外觀察和經歷。"},{"en":"Overseas observations and experiences can change how reformers judge their own society.","zh":"海外觀察和經歷可以改變改革者如何評價自己的社會。"},{"en":"This phrase combines what travellers saw with what they personally lived through.","zh":"這個短語結合旅行者所看見的事和親身經歷。"}],"source":"158 - Travel Accounts.pdf","sourcePage":15},{"front":"in one’s own writing","meaning":"在自己的寫作中","examples":[{"en":"They used travel experiences in their own writing.","zh":"他們在自己的寫作中使用旅行經驗。"},{"en":"In one’s own writing means in the texts, essays, books, or articles that a person writes.","zh":"in one’s own writing 指在一個人自己寫的文本、文章、書籍或論文中。"},{"en":"Students should use clear examples in their own writing.","zh":"學生應在自己的寫作中使用清楚例子。"},{"en":"A historian may use diary evidence in her own writing about migration.","zh":"歷史學家可能在自己關於遷徙的寫作中使用日記證據。"},{"en":"This phrase focuses on how a person includes ideas in their personal written work.","zh":"這個短語重點在於一個人如何把想法放入自己的書面作品中。"}],"source":"158 - Travel Accounts.pdf","sourcePage":15},{"front":"Japanese reformer","meaning":"日本改革家","examples":[{"en":"Fukuzawa Yukichi was a Japanese reformer.","zh":"福澤諭吉是一位日本改革家。"},{"en":"A Japanese reformer is a person from Japan who works to change society, government, or education.","zh":"Japanese reformer 指來自日本、致力改變社會、政府或教育的人。"},{"en":"A Japanese reformer may study foreign systems before proposing change at home.","zh":"日本改革家可能研究外國制度，然後在國內提出改革。"},{"en":"Reformers can influence schools, laws, public debate, and national identity.","zh":"改革家可以影響學校、法律、公共辯論和國民身份。"},{"en":"This phrase identifies both nationality and role.","zh":"這個短語同時指出國籍和角色。"}],"source":"158 - Travel Accounts.pdf","sourcePage":15},{"front":"Chinese revolutionary","meaning":"中國革命家","examples":[{"en":"Sun Yat-sen was a Chinese revolutionary.","zh":"孫中山是一位中國革命家。"},{"en":"A Chinese revolutionary is a Chinese person who works to overthrow or radically change a political system.","zh":"Chinese revolutionary 指致力推翻或徹底改變政治制度的中國人。"},{"en":"A Chinese revolutionary may write, organise supporters, and seek help abroad.","zh":"中國革命家可能寫作、組織支持者，並在海外尋求幫助。"},{"en":"Revolutionary ideas can spread when people compare their society with foreign examples.","zh":"當人們把自己的社會與外國例子比較時，革命思想可以傳播。"},{"en":"This phrase identifies someone connected with major political change.","zh":"這個短語指出某人與重大政治變革有關。"}],"source":"158 - Travel Accounts.pdf","sourcePage":15},{"front":"with the development of","meaning":"隨着……的發展","examples":[{"en":"Travel changed with the development of mass transport.","zh":"隨着大眾運輸的發展，旅行發生了變化。"},{"en":"With the development of something means as that thing grows, improves, or becomes more advanced.","zh":"with the development of something 指隨着某事物成長、改善或變得更先進。"},{"en":"With the development of the internet, students can study from home.","zh":"隨着互聯網的發展，學生可以在家學習。"},{"en":"With the development of public transport, workers can live farther from their jobs.","zh":"隨着公共交通的發展，工人可以住得離工作地點更遠。"},{"en":"This phrase shows that one change happens together with another development.","zh":"這個短語顯示一種變化伴隨另一種發展而發生。"}],"source":"158 - Travel Accounts.pdf","sourcePage":15},{"front":"inexpensive and reliable means of","meaning":"廉價而可靠的……方式","examples":[{"en":"The 20th century saw inexpensive and reliable means of mass transport.","zh":"20世紀出現了廉價而可靠的大眾運輸方式。"},{"en":"Inexpensive and reliable means of something are methods that are affordable and can be trusted to work well.","zh":"inexpensive and reliable means of something 指價格可負擔且能穩定運作的方法。"},{"en":"Buses can be an inexpensive and reliable means of travelling to school.","zh":"巴士可以是前往學校的廉價而可靠方式。"},{"en":"Inexpensive and reliable means of communication help families stay in touch across countries.","zh":"廉價而可靠的通訊方式幫助跨國家庭保持聯繫。"},{"en":"This phrase stresses both low cost and dependability.","zh":"這個短語同時強調低成本和可靠性。"}],"source":"158 - Travel Accounts.pdf","sourcePage":15},{"front":"mass transport","meaning":"大眾運輸；集體運輸","examples":[{"en":"Mass transport encouraged long-distance travel.","zh":"大眾運輸鼓勵了長途旅行。"},{"en":"Mass transport means systems that move large numbers of people, such as trains, buses, ships, and planes.","zh":"mass transport 指運送大量人群的系統，例如火車、巴士、船和飛機。"},{"en":"Good mass transport helps workers reach jobs without using private cars.","zh":"良好的大眾運輸幫助工人不用私家車也能上班。"},{"en":"Mass transport can reduce travel costs and connect distant places.","zh":"大眾運輸可以降低旅行成本並連接遙遠地方。"},{"en":"When mass transport improves, tourism and migration often become easier.","zh":"當大眾運輸改善，旅遊和遷移常變得更容易。"}],"source":"158 - Travel Accounts.pdf","sourcePage":15},{"front":"witness an explosion in","meaning":"見證……激增","examples":[{"en":"The 20th century witnessed an explosion in long-distance travel.","zh":"20世紀見證了長途旅行的激增。"},{"en":"To witness an explosion in something means to experience or see a very rapid increase in it.","zh":"witness an explosion in something 指經歷或看到某事物非常迅速增加。"},{"en":"The city witnessed an explosion in online shopping during the lockdown.","zh":"封城期間，這座城市見證了網購激增。"},{"en":"Cheap smartphones caused an explosion in mobile video use.","zh":"廉價智能手機導致手機影片使用量激增。"},{"en":"This phrase is dramatic and shows very fast growth.","zh":"這個短語語氣強烈，表示非常快速的增長。"}],"source":"158 - Travel Accounts.pdf","sourcePage":15},{"front":"the frequency of","meaning":"……的頻率","examples":[{"en":"The frequency of long-distance travel increased sharply.","zh":"長途旅行的頻率急劇增加。"},{"en":"The frequency of something means how often it happens.","zh":"the frequency of something 指某事發生的次數有多密。"},{"en":"The frequency of school tests may affect students’ stress levels.","zh":"學校測驗的頻率可能影響學生壓力水平。"},{"en":"If the frequency of buses increases, passengers wait for less time.","zh":"如果巴士班次頻率增加，乘客等待時間會減少。"},{"en":"This phrase measures repeated occurrence, not size or quality.","zh":"這個短語衡量重複發生的次數，而不是大小或質素。"}],"source":"158 - Travel Accounts.pdf","sourcePage":16},{"front":"long-distance travel","meaning":"長途旅行","examples":[{"en":"Long-distance travel became much more common in the 20th century.","zh":"長途旅行在20世紀變得常見得多。"},{"en":"Long-distance travel means journeys across far places, often between regions or countries.","zh":"long-distance travel 指跨越遙遠地方的旅程，常在地區或國家之間。"},{"en":"Trains and planes made long-distance travel easier for ordinary families.","zh":"火車和飛機令普通家庭更容易進行長途旅行。"},{"en":"Long-distance travel can create tiredness, cost, and culture shock.","zh":"長途旅行可能帶來疲倦、費用和文化衝擊。"},{"en":"This phrase contrasts with short local trips.","zh":"這個短語與短途本地旅程相對。"}],"source":"158 - Travel Accounts.pdf","sourcePage":16},{"front":"as in ages past","meaning":"如同過去各時代一樣","examples":[{"en":"People still travelled for business and pilgrimage, as in ages past.","zh":"人們仍為商業和朝聖旅行，如同過去各時代一樣。"},{"en":"As in ages past means just as people did in earlier historical periods.","zh":"as in ages past 指正如人們在較早歷史時期所做的一樣。"},{"en":"Families still gather for festivals, as in ages past.","zh":"家庭仍在節日聚首，如同過去各時代一樣。"},{"en":"Farmers still depend on weather, as in ages past, even with modern tools.","zh":"即使有現代工具，農民仍依靠天氣，如同過去各時代一樣。"},{"en":"This phrase connects modern behaviour with older traditions.","zh":"這個短語把現代行為與較古老傳統連接起來。"}],"source":"158 - Travel Accounts.pdf","sourcePage":16},{"front":"increasingly effective modes of","meaning":"越來越有效的……方式","examples":[{"en":"Increasingly effective modes of mass transport changed travel.","zh":"越來越有效的大眾運輸方式改變了旅行。"},{"en":"Increasingly effective modes of something are methods that become better and more successful over time.","zh":"increasingly effective modes of something 指隨時間變得更好、更成功的方法。"},{"en":"Increasingly effective modes of online teaching can help students in remote areas.","zh":"越來越有效的網上教學方式可以幫助偏遠地區學生。"},{"en":"Increasingly effective modes of transport reduce cost, time, and discomfort.","zh":"越來越有效的交通方式減少成本、時間和不適。"},{"en":"This phrase emphasises improvement over time.","zh":"這個短語強調隨時間改善。"}],"source":"158 - Travel Accounts.pdf","sourcePage":16},{"front":"make it possible for","meaning":"使……成為可能","examples":[{"en":"Mass transport made it possible for new kinds of travel to flourish.","zh":"大眾運輸使新型旅行蓬勃發展成為可能。"},{"en":"To make it possible for something to happen means to create the conditions that allow it.","zh":"make it possible for something to happen 指創造條件，使某事能夠發生。"},{"en":"Scholarships make it possible for poorer students to attend university.","zh":"獎學金使較貧困學生上大學成為可能。"},{"en":"Better roads make it possible for doctors to reach villages quickly.","zh":"更好的道路使醫生快速到達村莊成為可能。"},{"en":"This phrase shows that one development enables another.","zh":"這個短語顯示一種發展使另一件事成為可能。"}],"source":"158 - Travel Accounts.pdf","sourcePage":16},{"front":"new kinds of travel","meaning":"新型旅行","examples":[{"en":"New kinds of travel began to flourish.","zh":"新型旅行開始蓬勃發展。"},{"en":"New kinds of travel are forms of journeying that become possible or popular in a new period.","zh":"new kinds of travel 指在新時期變得可能或流行的旅行形式。"},{"en":"Budget flights created new kinds of travel, such as short weekend trips abroad.","zh":"廉價航班創造了新型旅行，例如週末短途出國旅行。"},{"en":"New kinds of travel can appear when technology, wealth, or leisure time changes.","zh":"當科技、財富或休閒時間改變，新型旅行可能出現。"},{"en":"This phrase shows that travel is not fixed; it changes with society.","zh":"這個短語顯示旅行不是固定的，而是隨社會改變。"}],"source":"158 - Travel Accounts.pdf","sourcePage":16},{"front":"flourish","meaning":"蓬勃發展","examples":[{"en":"Mass tourism began to flourish in the 20th century.","zh":"大眾旅遊在20世紀開始蓬勃發展。"},{"en":"To flourish means to grow, develop, and become successful.","zh":"flourish 指成長、發展並變得成功。"},{"en":"Small shops can flourish when local residents support them.","zh":"當本地居民支持小店時，小店可以蓬勃發展。"},{"en":"Plants flourish when they have enough sunlight, water, and healthy soil.","zh":"植物在有足夠陽光、水分和健康土壤時會蓬勃生長。"},{"en":"This word suggests healthy and visible growth.","zh":"這個詞表示健康而明顯的增長。"}],"source":"158 - Travel Accounts.pdf","sourcePage":16},{"front":"the most distinctive of them","meaning":"其中最具特色的","examples":[{"en":"The most distinctive of these new kinds of travel was mass tourism.","zh":"這些新型旅行中最具特色的是大眾旅遊。"},{"en":"The most distinctive of them means the one that is easiest to recognise as different or special.","zh":"the most distinctive of them 指其中最容易被認出為不同或特別的一個。"},{"en":"Among the paintings, the brightest one was the most distinctive of them.","zh":"在那些畫作中，最鮮艷的一幅是其中最具特色的。"},{"en":"A school’s caring culture may be the most distinctive of its qualities.","zh":"學校的關愛文化可能是其特質中最具特色的一項。"},{"en":"This phrase singles out the clearest or most special example in a group.","zh":"這個短語在一組事物中指出最清楚或最特別的例子。"}],"source":"158 - Travel Accounts.pdf","sourcePage":16},{"front":"mass tourism","meaning":"大眾旅遊","examples":[{"en":"Mass tourism became a major form of consumption.","zh":"大眾旅遊成為主要消費形式。"},{"en":"Mass tourism is tourism involving large numbers of ordinary people travelling for leisure.","zh":"mass tourism 指大量普通人為休閒而旅行的旅遊形式。"},{"en":"Package tours and cheap flights helped mass tourism grow.","zh":"套票旅行和廉價航班幫助大眾旅遊增長。"},{"en":"Mass tourism can bring income to local communities but also crowd streets and damage heritage.","zh":"大眾旅遊可以為本地社區帶來收入，但也可能擠滿街道並破壞文化遺產。"},{"en":"This phrase focuses on tourism as a large-scale social and economic activity.","zh":"這個短語把旅遊視為大規模社會和經濟活動。"}],"source":"158 - Travel Accounts.pdf","sourcePage":16},{"front":"emerge as","meaning":"作為……出現","examples":[{"en":"Mass tourism emerged as a major form of consumption.","zh":"大眾旅遊作為主要消費形式出現。"},{"en":"To emerge as something means to gradually become recognised as that thing.","zh":"emerge as something 指逐漸被認定為某種事物。"},{"en":"Online shopping emerged as a normal habit for many families.","zh":"網購逐漸作為許多家庭的日常習慣出現。"},{"en":"A small town may emerge as a popular destination after a famous film is shot there.","zh":"一部著名電影在某小鎮拍攝後，它可能逐漸成為熱門目的地。"},{"en":"This phrase suggests development over time rather than a sudden change.","zh":"這個短語表示隨時間發展，而不是突然改變。"}],"source":"158 - Travel Accounts.pdf","sourcePage":16},{"front":"a major form of consumption","meaning":"主要消費形式","examples":[{"en":"Tourism became a major form of consumption in wealthy societies.","zh":"旅遊在富裕社會成為主要消費形式。"},{"en":"A major form of consumption is an important way people spend money to satisfy wants or enjoy life.","zh":"a major form of consumption 指人們花錢滿足需要或享受生活的重要方式。"},{"en":"Streaming entertainment has become a major form of consumption for many young people.","zh":"串流娛樂已成為許多年輕人的主要消費形式。"},{"en":"When tourism becomes a major form of consumption, hotels, airlines, and restaurants expand.","zh":"當旅遊成為主要消費形式，酒店、航空公司和餐廳便會擴張。"},{"en":"This phrase treats leisure travel as part of economic behaviour.","zh":"這個短語把休閒旅行視為經濟行為的一部分。"}],"source":"158 - Travel Accounts.pdf","sourcePage":16},{"front":"wealthy societies","meaning":"富裕社會","examples":[{"en":"Mass tourism grew among people living in wealthy societies.","zh":"大眾旅遊在富裕社會的人群中增長。"},{"en":"Wealthy societies are societies where many people have enough income for comfort and leisure.","zh":"wealthy societies 指許多人有足夠收入享受舒適和休閒的社會。"},{"en":"In wealthy societies, families may spend money on holidays, restaurants, and entertainment.","zh":"在富裕社會，家庭可能花錢在假期、餐廳和娛樂上。"},{"en":"Wealthy societies often create more demand for tourism because people have paid leave and savings.","zh":"富裕社會常創造更多旅遊需求，因為人們有有薪假期和儲蓄。"},{"en":"This phrase describes economic conditions, not moral value.","zh":"這個短語描述經濟條件，而不是道德價值。"}],"source":"158 - Travel Accounts.pdf","sourcePage":17},{"front":"enable consumers to","meaning":"使消費者能夠","examples":[{"en":"Tourism enabled consumers to get away from home.","zh":"旅遊使消費者能夠離開家去放鬆。"},{"en":"To enable consumers to do something means to make it possible for buyers or users to do it.","zh":"enable consumers to do something 指使買家或使用者能夠做某事。"},{"en":"Online booking enables consumers to compare hotel prices quickly.","zh":"網上預訂使消費者能夠快速比較酒店價格。"},{"en":"Cheap transport enables consumers to travel more often.","zh":"便宜交通使消費者能夠更頻繁旅行。"},{"en":"This phrase shows how a service gives people practical access or ability.","zh":"這個短語顯示服務如何給人實際取得途徑或能力。"}],"source":"158 - Travel Accounts.pdf","sourcePage":17},{"front":"get away from home","meaning":"離開家去放鬆；出外旅行","examples":[{"en":"Tourists wanted to get away from home and see new places.","zh":"遊客想離開家去放鬆，並看看新地方。"},{"en":"To get away from home means to leave one’s usual home environment for rest, change, or travel.","zh":"get away from home 指離開日常居家環境，以休息、轉換或旅行。"},{"en":"A tired parent may want to get away from home for a quiet weekend.","zh":"疲倦的父母可能想離開家去過一個安靜週末。"},{"en":"People get away from home when daily routines become stressful or boring.","zh":"當日常生活變得有壓力或沉悶時，人們會想出外旅行。"},{"en":"This phrase often suggests relaxation, escape, or a break from normal life.","zh":"這個短語常表示放鬆、逃離或暫停平常生活。"}],"source":"158 - Travel Accounts.pdf","sourcePage":17},{"front":"see the sights","meaning":"觀光","examples":[{"en":"Tourists travelled to Rome to see the sights.","zh":"遊客前往羅馬觀光。"},{"en":"To see the sights means to visit famous or interesting places in a city or region.","zh":"see the sights 指參觀城市或地區中著名或有趣的地方。"},{"en":"Visitors to London often see the sights by bus or on foot.","zh":"到倫敦的遊客常坐巴士或步行觀光。"},{"en":"People who see the sights may visit museums, monuments, markets, and old streets.","zh":"觀光的人可能參觀博物館、紀念碑、市場和古老街道。"},{"en":"This phrase is about sightseeing, not deep study of a place.","zh":"這個短語關乎觀光，而不是深入研究一個地方。"}],"source":"158 - Travel Accounts.pdf","sourcePage":17},{"front":"take a cruise through","meaning":"乘船遊覽","examples":[{"en":"Tourists could take a cruise through the Caribbean.","zh":"遊客可以乘船遊覽加勒比海。"},{"en":"To take a cruise through a place means to travel by ship through that area for leisure.","zh":"take a cruise through a place 指乘船穿越該地區作休閒旅行。"},{"en":"A family may take a cruise through the Mediterranean during summer.","zh":"家庭可能在夏天乘船遊覽地中海。"},{"en":"Cruises allow travellers to visit several ports without changing hotels each night.","zh":"郵輪讓旅客可以到訪幾個港口，而不用每晚更換酒店。"},{"en":"This phrase is mainly used for holiday travel by boat or ship.","zh":"這個短語主要用於乘船或郵輪度假旅行。"}],"source":"158 - Travel Accounts.pdf","sourcePage":17},{"front":"walk the Great Wall of China","meaning":"遊覽中國長城","examples":[{"en":"Tourists travelled to walk the Great Wall of China.","zh":"遊客旅行去遊覽中國長城。"},{"en":"To walk the Great Wall of China means to visit and walk along this famous historic structure.","zh":"walk the Great Wall of China 指參觀並沿着這座著名歷史建築步行。"},{"en":"Many visitors walk the Great Wall of China to experience its scale and history.","zh":"許多遊客遊覽中國長城，以體驗其規模和歷史。"},{"en":"Walking the Great Wall can be tiring because some sections are steep and uneven.","zh":"遊覽長城可能很累，因為有些路段陡斜且不平。"},{"en":"This phrase refers to a specific tourist and historical activity.","zh":"這個短語指一項特定旅遊和歷史活動。"}],"source":"158 - Travel Accounts.pdf","sourcePage":17},{"front":"visit wineries","meaning":"參觀酒莊","examples":[{"en":"Tourists visited wineries in Bordeaux.","zh":"遊客在波爾多參觀酒莊。"},{"en":"To visit wineries means to go to places where wine is produced, stored, or tasted.","zh":"visit wineries 指前往生產、儲存或品嚐葡萄酒的地方。"},{"en":"Travellers may visit wineries to learn how grapes become wine.","zh":"旅客可能參觀酒莊，以了解葡萄如何變成葡萄酒。"},{"en":"Winery visits can support local farms, restaurants, and tourism businesses.","zh":"酒莊參觀可以支持本地農場、餐廳和旅遊業務。"},{"en":"This phrase is usually connected with food, drink, agriculture, and leisure travel.","zh":"這個短語通常與食物、飲品、農業和休閒旅行有關。"}],"source":"158 - Travel Accounts.pdf","sourcePage":17},{"front":"go on safari","meaning":"參加野生動物觀賞旅行","examples":[{"en":"Tourists could go on safari in Kenya.","zh":"遊客可以在肯尼亞參加野生動物觀賞旅行。"},{"en":"To go on safari means to travel to observe wild animals, especially in Africa.","zh":"go on safari 指旅行去觀察野生動物，尤其是在非洲。"},{"en":"A family may go on safari to see elephants, lions, and giraffes in protected parks.","zh":"家庭可能參加野生動物觀賞旅行，在保護區看大象、獅子和長頸鹿。"},{"en":"Responsible safari tourism can support conservation and local jobs.","zh":"負責任的 safari 旅遊可以支持保育和本地就業。"},{"en":"This phrase is about wildlife viewing, not hunting in modern tourism contexts.","zh":"在現代旅遊語境中，這個短語指觀賞野生動物，而不是狩獵。"}],"source":"158 - Travel Accounts.pdf","sourcePage":17},{"front":"a peculiar variant of","meaning":"……的一種特殊變體","examples":[{"en":"The guidebook was a peculiar variant of the travel account.","zh":"旅遊指南是旅行記錄的一種特殊變體。"},{"en":"A peculiar variant of something is an unusual type or version of it.","zh":"a peculiar variant of something 指某事物的一種不尋常類型或版本。"},{"en":"A podcast can be a peculiar variant of traditional radio.","zh":"播客可以是傳統電台的一種特殊變體。"},{"en":"A guidebook is a peculiar variant of travel writing because it gives advice rather than only telling a story.","zh":"旅遊指南是旅行文學的特殊變體，因為它提供建議，而不只是講故事。"},{"en":"This phrase points out that something belongs to a category but differs from the usual form.","zh":"這個短語指出某物屬於一個類別，但不同於通常形式。"}],"source":"158 - Travel Accounts.pdf","sourcePage":17},{"front":"arise to meet the needs of","meaning":"出現以滿足……需要","examples":[{"en":"The guidebook arose to meet the needs of tourists.","zh":"旅遊指南出現以滿足遊客需要。"},{"en":"To arise to meet the needs of people means to appear because those people need help or service.","zh":"arise to meet the needs of people 指因為那些人需要幫助或服務而出現。"},{"en":"Online grocery delivery arose to meet the needs of busy families.","zh":"網上雜貨配送出現以滿足忙碌家庭的需要。"},{"en":"New language apps arose to meet the needs of independent learners.","zh":"新語言應用程式出現以滿足自主學習者的需要。"},{"en":"This phrase links the creation of something to a practical demand.","zh":"這個短語把某物的創造與實際需求連接起來。"}],"source":"158 - Travel Accounts.pdf","sourcePage":17},{"front":"guidebook","meaning":"旅遊指南","examples":[{"en":"A guidebook offers advice to tourists.","zh":"旅遊指南向遊客提供建議。"},{"en":"A guidebook is a book that gives visitors information about places, transport, food, lodging, and sights.","zh":"guidebook 指向訪客提供地方、交通、食物、住宿和景點資料的書。"},{"en":"A guidebook may tell travellers which museums are free on Sundays.","zh":"旅遊指南可能告訴旅客哪些博物館星期日免費。"},{"en":"Guidebooks help tourists avoid confusion when they arrive in an unfamiliar city.","zh":"旅遊指南幫助遊客到達陌生城市時避免混亂。"},{"en":"Modern guidebooks may be printed books, apps, or online travel pages.","zh":"現代旅遊指南可以是印刷書、應用程式或網上旅遊頁面。"}],"source":"158 - Travel Accounts.pdf","sourcePage":17},{"front":"offer advice on","meaning":"提供關於……的建議","examples":[{"en":"Guidebooks offer advice on food, lodging and local customs.","zh":"旅遊指南提供關於食物、住宿和本地習俗的建議。"},{"en":"To offer advice on something means to give suggestions or guidance about it.","zh":"offer advice on something 指提供有關某事的建議或指引。"},{"en":"A teacher may offer advice on how to organise an essay.","zh":"老師可能提供關於如何組織文章的建議。"},{"en":"Doctors offer advice on diet, sleep, exercise, and medicine.","zh":"醫生提供關於飲食、睡眠、運動和藥物的建議。"},{"en":"This phrase focuses on helpful guidance, not orders.","zh":"這個短語重點在於有幫助的指引，而不是命令。"}],"source":"158 - Travel Accounts.pdf","sourcePage":18},{"front":"lodging","meaning":"住宿","examples":[{"en":"Guidebooks give advice on food and lodging.","zh":"旅遊指南提供關於食物和住宿的建議。"},{"en":"Lodging means a place to stay temporarily, especially while travelling.","zh":"lodging 指暫時停留的地方，尤其是在旅行期間。"},{"en":"Students on a field trip need safe and affordable lodging.","zh":"參加實地考察的學生需要安全而可負擔的住宿。"},{"en":"Expensive lodging can make a holiday impossible for low-income families.","zh":"昂貴住宿可能令低收入家庭無法度假。"},{"en":"This word is more general than hotel because it can include inns, hostels, or rented rooms.","zh":"這個詞比 hotel 更廣泛，因為它可以包括旅館、青年旅舍或出租房間。"}],"source":"158 - Travel Accounts.pdf","sourcePage":18},{"front":"local customs","meaning":"本地習俗","examples":[{"en":"Guidebooks often explain local customs.","zh":"旅遊指南常解釋本地習俗。"},{"en":"Local customs are the usual behaviours, traditions, and social rules of a particular place.","zh":"local customs 指特定地方的慣常行為、傳統和社交規則。"},{"en":"Travellers should learn local customs before attending a wedding abroad.","zh":"旅客在海外參加婚禮前應了解本地習俗。"},{"en":"Ignoring local customs can cause embarrassment or offence.","zh":"忽視本地習俗可能造成尷尬或冒犯。"},{"en":"Local customs may involve greetings, clothing, eating, gift-giving, and festival behaviour.","zh":"本地習俗可能涉及問候、衣着、用餐、送禮和節日行為。"}],"source":"158 - Travel Accounts.pdf","sourcePage":18},{"front":"visitors should not miss seeing","meaning":"遊客不應錯過觀看","examples":[{"en":"Guidebooks list the sights visitors should not miss seeing.","zh":"旅遊指南列出遊客不應錯過觀看的景點。"},{"en":"Visitors should not miss seeing means that certain places are strongly recommended for visitors.","zh":"visitors should not miss seeing 表示某些地方強烈建議遊客觀看。"},{"en":"In Kyoto, visitors should not miss seeing historic temples and quiet gardens.","zh":"在京都，遊客不應錯過觀看歷史寺廟和寧靜庭園。"},{"en":"A museum guide may mark exhibits visitors should not miss seeing.","zh":"博物館指南可能標示遊客不應錯過觀看的展品。"},{"en":"This phrase helps tourists choose important sights when time is limited.","zh":"當時間有限時，這個短語幫助遊客選擇重要景點。"}],"source":"158 - Travel Accounts.pdf","sourcePage":18},{"front":"have a massive economic impact","meaning":"產生巨大經濟影響","examples":[{"en":"Tourism has had a massive economic impact throughout the world.","zh":"旅遊業在全球產生巨大經濟影響。"},{"en":"To have a massive economic impact means to strongly affect jobs, income, prices, and business activity.","zh":"have a massive economic impact 指強烈影響就業、收入、價格和商業活動。"},{"en":"A new airport can have a massive economic impact on a small city.","zh":"新機場可以對小城市產生巨大經濟影響。"},{"en":"Tourism can have a massive economic impact by creating hotel, transport, and restaurant jobs.","zh":"旅遊可以透過創造酒店、交通和餐飲工作產生巨大經濟影響。"},{"en":"This phrase shows that the effect is large and connected with the economy.","zh":"這個短語顯示影響很大，而且與經濟有關。"}],"source":"158 - Travel Accounts.pdf","sourcePage":18},{"front":"throughout the world","meaning":"遍及全球","examples":[{"en":"Tourism has affected economies throughout the world.","zh":"旅遊影響遍及全球的經濟。"},{"en":"Throughout the world means in many or all parts of the world.","zh":"throughout the world 指在世界許多或所有地方。"},{"en":"Smartphones are used throughout the world for communication, banking, and entertainment.","zh":"智能手機在全球各地用於通訊、銀行和娛樂。"},{"en":"A disease can spread throughout the world when travel is frequent.","zh":"當旅行頻繁時，疾病可能傳播遍及全球。"},{"en":"This phrase stresses global reach.","zh":"這個短語強調全球範圍。"}],"source":"158 - Travel Accounts.pdf","sourcePage":18},{"front":"considerable influence","meaning":"相當大的影響","examples":[{"en":"Other new forms of travel have had considerable influence.","zh":"其他新形式的旅行也有相當大的影響。"},{"en":"Considerable influence means a large or important effect on people, events, or behaviour.","zh":"considerable influence 指對人、事件或行為有很大或重要影響。"},{"en":"Teachers can have considerable influence on students’ confidence.","zh":"老師可以對學生信心有相當大的影響。"},{"en":"Social media has considerable influence on how young people receive news.","zh":"社交媒體對年輕人接收新聞的方式有相當大的影響。"},{"en":"This phrase suggests an effect that is significant, though not always total.","zh":"這個短語表示影響重要，但不一定是完全控制。"}],"source":"158 - Travel Accounts.pdf","sourcePage":18},{"front":"contemporary times","meaning":"當代","examples":[{"en":"Migration has had great influence in contemporary times.","zh":"遷徙在當代有重大影響。"},{"en":"Contemporary times means the present age or recent modern period.","zh":"contemporary times 指現今年代或近代時期。"},{"en":"In contemporary times, many people work with colleagues in other countries online.","zh":"在當代，許多人透過網上與其他國家的同事工作。"},{"en":"Migration in contemporary times is shaped by war, jobs, education, and family ties.","zh":"當代遷徙受戰爭、工作、教育和家庭聯繫影響。"},{"en":"This phrase contrasts the present or recent period with earlier history.","zh":"這個短語把現今或近代時期與較早歷史作對比。"}],"source":"158 - Travel Accounts.pdf","sourcePage":18},{"front":"unprecedented waves of","meaning":"前所未有的一波波……","examples":[{"en":"Recent times have seen unprecedented waves of migration.","zh":"近代出現了前所未有的一波波遷徙。"},{"en":"Unprecedented waves of something are repeated large movements or increases never seen before.","zh":"unprecedented waves of something 指前所未見的重複大規模流動或增加。"},{"en":"The city faced unprecedented waves of visitors after the festival became famous.","zh":"節日成名後，這座城市面對前所未有的一波波訪客。"},{"en":"Unprecedented waves of migration can pressure housing, schools, and public services.","zh":"前所未有的一波波遷徙可能對住房、學校和公共服務造成壓力。"},{"en":"This phrase stresses both scale and historical newness.","zh":"這個短語同時強調規模和歷史上的新情況。"}],"source":"158 - Travel Accounts.pdf","sourcePage":18},{"front":"seek to record","meaning":"力求記錄","examples":[{"en":"Numerous migrants have sought to record their experiences.","zh":"許多移民力求記錄自己的經歷。"},{"en":"To seek to record something means to try to write, film, or preserve it.","zh":"seek to record something 指嘗試把某事寫下、拍攝或保存。"},{"en":"Survivors may seek to record their memories so later generations understand what happened.","zh":"倖存者可能力求記錄自己的記憶，讓後代了解發生過甚麼。"},{"en":"Migrants seek to record life abroad when they feel their stories might be forgotten.","zh":"當移民覺得自己的故事可能被遺忘時，會力求記錄海外生活。"},{"en":"This phrase suggests an intentional effort to preserve experience.","zh":"這個短語表示有意識地努力保存經驗。"}],"source":"158 - Travel Accounts.pdf","sourcePage":18},{"front":"articulate their feelings about","meaning":"表達對……的感受","examples":[{"en":"Migrants have tried to articulate their feelings about life abroad.","zh":"移民嘗試表達對海外生活的感受。"},{"en":"To articulate feelings about something means to express those feelings clearly in words.","zh":"articulate feelings about something 指用語言清楚表達對某事的感受。"},{"en":"A teenager may struggle to articulate their feelings about moving school.","zh":"青少年可能難以表達對轉校的感受。"},{"en":"Writing a diary can help people articulate their feelings about loneliness.","zh":"寫日記可以幫助人表達對孤獨的感受。"},{"en":"This phrase is useful when emotions are complicated and need careful expression.","zh":"當情感複雜並需要仔細表達時，這個短語很有用。"}],"source":"158 - Travel Accounts.pdf","sourcePage":18},{"front":"life in foreign lands","meaning":"在異國的生活","examples":[{"en":"Migrants wrote about life in foreign lands.","zh":"移民寫作關於在異國的生活。"},{"en":"Life in foreign lands means daily living in countries or societies outside one’s own.","zh":"life in foreign lands 指在自己國家或社會以外地方的日常生活。"},{"en":"Life in foreign lands may involve new languages, food, laws, and social expectations.","zh":"在異國的生活可能涉及新語言、食物、法律和社交期望。"},{"en":"Migrants write about life in foreign lands to explain both opportunity and loneliness.","zh":"移民寫作在異國的生活，以解釋機會和孤獨。"},{"en":"This phrase is broader than travel because it can include long-term settlement.","zh":"這個短語比 travel 更廣，因為它可包括長期定居。"}],"source":"158 - Travel Accounts.pdf","sourcePage":19},{"front":"unprecedented development of","meaning":"……前所未有的發展","examples":[{"en":"Recent times have seen an unprecedented development of ethnic consciousness.","zh":"近代出現了族裔意識前所未有的發展。"},{"en":"Unprecedented development of something means growth or change in it that has not happened before.","zh":"unprecedented development of something 指某事物出現以前未有的增長或變化。"},{"en":"The internet led to an unprecedented development of online learning.","zh":"互聯網帶來網上學習前所未有的發展。"},{"en":"Unprecedented development of a city can create jobs but also housing pressure.","zh":"城市前所未有的發展可以創造工作，但也帶來住房壓力。"},{"en":"This phrase stresses that the change is historically new and important.","zh":"這個短語強調變化在歷史上嶄新而重要。"}],"source":"158 - Travel Accounts.pdf","sourcePage":19},{"front":"ethnic consciousness","meaning":"族裔意識","examples":[{"en":"Ethnic consciousness influenced some modern travel accounts.","zh":"族裔意識影響了一些現代旅行記錄。"},{"en":"Ethnic consciousness is awareness of one’s ethnic identity, heritage, history, and shared culture.","zh":"ethnic consciousness 指對自己族裔身份、傳承、歷史和共同文化的意識。"},{"en":"A migrant family may develop ethnic consciousness by teaching children their ancestral language.","zh":"移民家庭可能透過教孩子祖先語言來培養族裔意識。"},{"en":"Ethnic consciousness can grow when people compare life abroad with inherited traditions.","zh":"當人們把海外生活與繼承的傳統比較時，族裔意識可能增長。"},{"en":"This phrase is about identity and belonging, not just nationality.","zh":"這個短語關乎身份和歸屬，而不只是國籍。"}],"source":"158 - Travel Accounts.pdf","sourcePage":19},{"front":"intellectuals and writers","meaning":"知識分子和作家","examples":[{"en":"Many intellectuals and writers in the diaspora visited ancestral homes.","zh":"許多散居族群中的知識分子和作家到訪祖先的家鄉。"},{"en":"Intellectuals and writers are people who think, study, publish, and express ideas through writing.","zh":"intellectuals and writers 指透過思考、研究、出版和寫作表達思想的人。"},{"en":"Intellectuals and writers often help societies discuss identity, reform, and memory.","zh":"知識分子和作家常幫助社會討論身份、改革和記憶。"},{"en":"When intellectuals and writers travel, their observations may influence public debate.","zh":"當知識分子和作家旅行，他們的觀察可能影響公共辯論。"},{"en":"This phrase groups thinkers and literary figures together.","zh":"這個短語把思想家和文學人物放在一起。"}],"source":"158 - Travel Accounts.pdf","sourcePage":19},{"front":"in the diaspora","meaning":"在散居族群中","examples":[{"en":"Writers in the diaspora visited the homes of their ancestors.","zh":"散居族群中的作家到訪祖先的家鄉。"},{"en":"In the diaspora means living outside the homeland of one’s people or ancestors.","zh":"in the diaspora 指生活在自己民族或祖先 homeland 以外的地方。"},{"en":"Families in the diaspora may keep traditions through food, language, and festivals.","zh":"散居族群中的家庭可能透過食物、語言和節日保留傳統。"},{"en":"People in the diaspora may feel connected to both their current home and ancestral homeland.","zh":"散居族群中的人可能同時感到與現居地和祖籍地相連。"},{"en":"This phrase is often used to discuss migration, identity, and memory.","zh":"這個短語常用於討論遷移、身份和記憶。"}],"source":"158 - Travel Accounts.pdf","sourcePage":19},{"front":"the homes of their ancestors","meaning":"祖先的家鄉","examples":[{"en":"Writers visited the homes of their ancestors.","zh":"作家到訪祖先的家鄉。"},{"en":"The homes of their ancestors are the places where earlier family members or forebears lived.","zh":"the homes of their ancestors 指早期家庭成員或祖先生活過的地方。"},{"en":"A migrant’s child may visit the homes of their ancestors to understand family history.","zh":"移民的孩子可能到訪祖先的家鄉，以了解家族歷史。"},{"en":"Visiting the homes of their ancestors can create pride, sadness, or confusion.","zh":"到訪祖先的家鄉可以帶來自豪、悲傷或困惑。"},{"en":"This phrase connects place with memory and inherited identity.","zh":"這個短語把地方與記憶和繼承身份連繫起來。"}],"source":"158 - Travel Accounts.pdf","sourcePage":19},{"front":"forebears’ values","meaning":"祖先的價值觀","examples":[{"en":"Writers explored how much of their forebears’ values they had inherited.","zh":"作家探索自己繼承了多少祖先的價值觀。"},{"en":"Forebears’ values are the beliefs and moral ideas held by earlier generations of one’s family or people.","zh":"forebears’ values 指家族或民族較早世代所持有的信念和道德觀念。"},{"en":"A young person may ask whether they still share their forebears’ values about family duty.","zh":"年輕人可能會問自己是否仍認同祖先關於家庭責任的價值觀。"},{"en":"Migration can make people question which forebears’ values to keep or change.","zh":"遷移可以令人思考哪些祖先價值觀應保留或改變。"},{"en":"This phrase connects ancestry with moral inheritance.","zh":"這個短語把祖先與道德繼承連接起來。"}],"source":"158 - Travel Accounts.pdf","sourcePage":19},{"front":"cultural traditions","meaning":"文化傳統","examples":[{"en":"Many writers examined inherited cultural traditions.","zh":"許多作家審視繼承而來的文化傳統。"},{"en":"Cultural traditions are customs, beliefs, rituals, arts, and practices passed down in a community.","zh":"cultural traditions 指社群中代代相傳的習俗、信念、儀式、藝術和做法。"},{"en":"Cultural traditions may include festival food, wedding customs, songs, and family stories.","zh":"文化傳統可能包括節日食物、婚禮習俗、歌曲和家族故事。"},{"en":"Cultural traditions survive when people understand their meaning and practise them regularly.","zh":"當人們理解文化傳統的意義並定期實踐，它們便能延續。"},{"en":"This phrase is broader than one habit because it includes many forms of shared culture.","zh":"這個短語比單一習慣更廣，因為它包括許多共同文化形式。"}],"source":"158 - Travel Accounts.pdf","sourcePage":19},{"front":"inherit","meaning":"繼承","examples":[{"en":"Writers asked how much of their ancestors’ culture they had inherited.","zh":"作家問自己繼承了多少祖先文化。"},{"en":"To inherit something means to receive it from parents, ancestors, or earlier generations.","zh":"inherit something 指從父母、祖先或較早世代接收某物。"},{"en":"A child may inherit a family recipe from a grandparent.","zh":"孩子可能從祖父母那裡繼承家庭食譜。"},{"en":"People can inherit property, but they can also inherit language, values, and traditions.","zh":"人們可以繼承財產，也可以繼承語言、價值觀和傳統。"},{"en":"This word can refer to both material possessions and cultural influence.","zh":"這個詞可以指物質財產，也可以指文化影響。"}],"source":"158 - Travel Accounts.pdf","sourcePage":19},{"front":"particularly notable among","meaning":"在……中特別值得注意","examples":[{"en":"The memoirs of Malcolm X and Maya Angelou are particularly notable among these accounts.","zh":"馬爾科姆·X和瑪雅·安傑盧的回憶錄在這些記錄中特別值得注意。"},{"en":"Particularly notable among means especially important or worth noticing within a group.","zh":"particularly notable among 表示在一組事物中特別重要或值得注意。"},{"en":"One student’s improvement was particularly notable among the whole class.","zh":"在全班之中，一位學生的進步特別值得注意。"},{"en":"A small island may be particularly notable among tourist destinations for its wildlife.","zh":"一個小島可能因其野生動物而在旅遊目的地中特別值得注意。"},{"en":"This phrase points to examples that stand out from others.","zh":"這個短語指出從其他例子中突出的例子。"}],"source":"158 - Travel Accounts.pdf","sourcePage":19},{"front":"memoirs","meaning":"回憶錄","examples":[{"en":"Some memoirs describe visits to ancestral homelands.","zh":"有些回憶錄描述到訪祖先 homeland 的經歷。"},{"en":"Memoirs are written accounts of a person’s own memories and life experiences.","zh":"memoirs 指一個人對自己記憶和人生經歷的書面記錄。"},{"en":"A refugee’s memoirs may describe leaving home, learning a new language, and rebuilding life.","zh":"難民的回憶錄可能描述離家、學習新語言和重建生活。"},{"en":"Memoirs can help readers understand history through personal experience.","zh":"回憶錄可以幫助讀者透過個人經驗理解歷史。"},{"en":"Unlike a full biography, memoirs often focus on selected meaningful memories.","zh":"與完整傳記不同，回憶錄常聚焦於選定而有意義的記憶。"}],"source":"158 - Travel Accounts.pdf","sourcePage":19},{"front":"describe one’s visits to","meaning":"描述某人到訪……","examples":[{"en":"The memoirs describe their visits to Africa.","zh":"這些回憶錄描述他們到訪非洲的經歷。"},{"en":"To describe one’s visits to a place means to write or speak about journeys made there.","zh":"describe one’s visits to a place 指寫下或說出到某地旅行的經歷。"},{"en":"A student may describe her visits to local museums in a project.","zh":"學生可能在項目中描述她到訪本地博物館的經歷。"},{"en":"Writers describe their visits to ancestral places to explore identity and memory.","zh":"作家描述自己到訪祖先之地，以探索身份和記憶。"},{"en":"This phrase focuses on recording what was seen, felt, and understood during visits.","zh":"這個短語重點在於記錄到訪期間所見、所感和所理解的事情。"}],"source":"158 - Travel Accounts.pdf","sourcePage":20},{"front":"complete the table below","meaning":"完成以下表格","examples":[{"en":"Students complete the table below using words from the passage.","zh":"學生使用文章中的詞語完成以下表格。"},{"en":"Complete the table below means fill in the missing information in the table provided.","zh":"complete the table below 指填寫所提供表格中的缺失資料。"},{"en":"In an exam, students may complete the table below with numbers from a chart.","zh":"在考試中，學生可能用圖表中的數字完成以下表格。"},{"en":"Students lose marks if they complete the table below with words that are not in the passage.","zh":"如果學生用文章中沒有的詞語完成以下表格，可能會失分。"},{"en":"This instruction tells students exactly where to put their answers.","zh":"這個指示清楚告訴學生把答案放在哪裡。"}],"source":"158 - Travel Accounts.pdf","sourcePage":20},{"front":"no more than two words","meaning":"不超過兩個字","examples":[{"en":"Students should choose no more than two words from the passage.","zh":"學生應從文章中選擇不超過兩個字。"},{"en":"No more than two words means one or two words, but not three or more.","zh":"no more than two words 指一個或兩個字，但不是三個或更多。"},{"en":"If the answer is mass tourism, it follows the rule of no more than two words.","zh":"如果答案是 mass tourism，就符合不超過兩個字的規則。"},{"en":"Students break the rule if they write three words when no more than two words are allowed.","zh":"當題目規定不超過兩個字時，學生寫三個字便違規。"},{"en":"This instruction controls answer length in reading exams.","zh":"這個指示控制閱讀考試中的答案長度。"}],"source":"158 - Travel Accounts.pdf","sourcePage":20},{"front":"from the passage","meaning":"從文章中","examples":[{"en":"The answers must come from the passage.","zh":"答案必須來自文章中。"},{"en":"From the passage means taken directly from the reading text, not from one’s own ideas.","zh":"from the passage 指直接取自閱讀文章，而不是來自自己的想法。"},{"en":"In reading tests, students should copy answers from the passage when instructed.","zh":"在閱讀測驗中，當題目要求時，學生應從文章中抄寫答案。"},{"en":"Answers not from the passage may be wrong even if they sound logical.","zh":"不是來自文章的答案即使聽起來合理，也可能錯。"},{"en":"This phrase reminds students to use source evidence.","zh":"這個短語提醒學生使用來源證據。"}],"source":"158 - Travel Accounts.pdf","sourcePage":20},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生在答題紙上寫下答案。"},{"en":"On your answer sheet means in the official place where exam answers must be written.","zh":"on your answer sheet 指在考試答案必須填寫的正式位置。"},{"en":"A correct answer in the question booklet may not count if it is not on your answer sheet.","zh":"如果答案沒有寫在答題紙上，即使在題目冊中正確，也可能不計分。"},{"en":"Students should check that the answer number on the answer sheet matches the question number.","zh":"學生應檢查答題紙上的答案編號是否與題號相符。"},{"en":"This phrase is common in exam instructions.","zh":"這個短語常見於考試指示。"}],"source":"158 - Travel Accounts.pdf","sourcePage":20},{"front":"obtain information about","meaning":"取得有關……的資料","examples":[{"en":"Herodotus travelled to obtain information about the Persian wars.","zh":"希羅多德旅行以取得有關波斯戰爭的資料。"},{"en":"To obtain information about something means to get facts or details about it.","zh":"obtain information about something 指取得有關某事的事實或細節。"},{"en":"Patients may call a clinic to obtain information about appointment times.","zh":"病人可能致電診所，以取得有關預約時間的資料。"},{"en":"Researchers obtain information about a community by interviewing residents.","zh":"研究人員透過訪問居民取得有關社區的資料。"},{"en":"This phrase is formal and focuses on collecting useful knowledge.","zh":"這個短語語氣正式，重點在於收集有用知識。"}],"source":"158 - Travel Accounts.pdf","sourcePage":20},{"front":"seek allies","meaning":"尋找盟友","examples":[{"en":"Zhang Qian travelled to seek allies for the Han dynasty.","zh":"張騫為漢朝旅行尋找盟友。"},{"en":"To seek allies means to look for people, groups, or states willing to support you.","zh":"seek allies 指尋找願意支持自己的人、群體或國家。"},{"en":"A small club may seek allies before asking the school to change a rule.","zh":"小型學會在要求學校改變規則前，可能會尋找盟友。"},{"en":"Countries seek allies when they face military, political, or economic threats.","zh":"國家面對軍事、政治或經濟威脅時會尋找盟友。"},{"en":"This phrase shows a search for support rather than information alone.","zh":"這個短語顯示尋求支持，而不只是尋找資料。"}],"source":"158 - Travel Accounts.pdf","sourcePage":20},{"front":"gather knowledge","meaning":"收集知識","examples":[{"en":"Ancient geographers travelled to gather geographical knowledge.","zh":"古代地理學家旅行以收集地理知識。"},{"en":"To gather knowledge means to collect information through study, observation, or experience.","zh":"gather knowledge 指透過研究、觀察或經驗收集資料。"},{"en":"Students gather knowledge by reading, asking questions, and practising.","zh":"學生透過閱讀、提問和練習收集知識。"},{"en":"Doctors gather knowledge about symptoms before deciding on treatment.","zh":"醫生在決定治療前收集有關症狀的知識。"},{"en":"This phrase shows active learning, not passive guessing.","zh":"這個短語表示主動學習，而不是被動猜測。"}],"source":"158 - Travel Accounts.pdf","sourcePage":20},{"front":"for business and pilgrimage","meaning":"為了商業和朝聖","examples":[{"en":"Muslims travelled for business and pilgrimage.","zh":"穆斯林為了商業和朝聖而旅行。"},{"en":"For business and pilgrimage means for commercial work and religious journeys.","zh":"for business and pilgrimage 指為了商業工作和宗教旅程。"},{"en":"A port city may receive travellers for business and pilgrimage at the same time.","zh":"港口城市可能同時接待為了商業和朝聖而來的旅客。"},{"en":"Roads became busy when merchants and believers travelled for business and pilgrimage.","zh":"當商人和信徒為了商業和朝聖而旅行，道路變得繁忙。"},{"en":"This phrase combines economic and religious reasons for travel.","zh":"這個短語結合旅行的經濟和宗教原因。"}],"source":"158 - Travel Accounts.pdf","sourcePage":20},{"front":"study with teachers","meaning":"跟隨老師學習","examples":[{"en":"Buddhists travelled to India to study with teachers.","zh":"佛教徒前往印度跟隨老師學習。"},{"en":"To study with teachers means to learn directly from instructors or religious masters.","zh":"study with teachers 指直接向導師或宗教大師學習。"},{"en":"Music students may travel abroad to study with teachers known for a special technique.","zh":"音樂學生可能出國跟隨以特殊技巧著稱的老師學習。"},{"en":"Studying with teachers allows learners to ask questions and receive correction.","zh":"跟隨老師學習讓學習者可以提問並獲得糾正。"},{"en":"This phrase stresses personal instruction, not only reading books alone.","zh":"這個短語強調親身指導，而不只是自己看書。"}],"source":"158 - Travel Accounts.pdf","sourcePage":20},{"front":"satisfy public demand for","meaning":"滿足公眾對……的需求","examples":[{"en":"Travel books were published to satisfy public demand for news.","zh":"旅行書出版是為了滿足公眾對消息的需求。"},{"en":"To satisfy public demand for something means to provide what many people want.","zh":"satisfy public demand for something 指提供許多人想要的東西。"},{"en":"More buses were added to satisfy public demand for late-night transport.","zh":"為了滿足公眾對深夜交通的需求，政府增加了巴士。"},{"en":"Publishers print more books when they need to satisfy public demand for a popular topic.","zh":"當出版商需要滿足公眾對熱門主題的需求時，會印更多書。"},{"en":"This phrase links supply with what the public wants.","zh":"這個短語把供應與公眾想要的東西連接起來。"}],"source":"158 - Travel Accounts.pdf","sourcePage":20},{"front":"public demand","meaning":"公眾需求","examples":[{"en":"Editors responded to public demand for travel accounts.","zh":"編者回應公眾對旅行記錄的需求。"},{"en":"Public demand is the desire or need expressed by many people in society.","zh":"public demand 指社會中許多人表達出的願望或需要。"},{"en":"Public demand for cleaner parks can push a council to hire more workers.","zh":"公眾對更清潔公園的需求可以推動市議會聘請更多工人。"},{"en":"When public demand is strong, businesses often create more products or services.","zh":"當公眾需求強烈，企業常創造更多產品或服務。"},{"en":"This phrase refers to what many people want, not one person’s preference.","zh":"這個短語指許多人想要的東西，而不是一個人的偏好。"}],"source":"158 - Travel Accounts.pdf","sourcePage":21},{"front":"the wider world","meaning":"更廣闊的世界","examples":[{"en":"Readers wanted information about the wider world.","zh":"讀者想要有關更廣闊世界的資料。"},{"en":"The wider world means places, societies, and issues beyond one’s local environment.","zh":"the wider world 指本地環境以外的地方、社會和議題。"},{"en":"School exchanges help teenagers learn about the wider world.","zh":"學校交流幫助青少年了解更廣闊的世界。"},{"en":"News about the wider world can change how people understand their own country.","zh":"關於更廣闊世界的消息可以改變人們如何理解自己的國家。"},{"en":"This phrase contrasts local life with broader global experience.","zh":"這個短語把本地生活與更廣泛的全球經驗作對比。"}],"source":"158 - Travel Accounts.pdf","sourcePage":21},{"front":"provide information about","meaning":"提供關於……的資料","examples":[{"en":"Colonial administrators wrote to provide information about the societies they ruled.","zh":"殖民地行政官員寫作，以提供關於他們統治社會的資料。"},{"en":"To provide information about something means to give facts, details, or explanations about it.","zh":"provide information about something 指提供有關某事的事實、細節或解釋。"},{"en":"A school website provides information about fees, subjects, and teachers.","zh":"學校網站提供關於學費、科目和教師的資料。"},{"en":"Clear signs provide information about safety rules in a factory.","zh":"清楚標誌提供關於工廠安全規則的資料。"},{"en":"This phrase is neutral; the information may still need to be checked for bias.","zh":"這個短語本身中性；資料仍可能需要檢查是否有偏見。"}],"source":"158 - Travel Accounts.pdf","sourcePage":21},{"front":"mass-tourism destinations","meaning":"大眾旅遊目的地","examples":[{"en":"People travelled to mass-tourism destinations for leisure.","zh":"人們為休閒前往大眾旅遊目的地。"},{"en":"Mass-tourism destinations are places visited by large numbers of holiday travellers.","zh":"mass-tourism destinations 指大量度假旅客到訪的地方。"},{"en":"Famous beaches and historic cities can become mass-tourism destinations.","zh":"著名海灘和歷史城市可以成為大眾旅遊目的地。"},{"en":"Mass-tourism destinations earn money but may suffer from crowding and higher prices.","zh":"大眾旅遊目的地賺取收入，但可能受擁擠和物價上升影響。"},{"en":"This phrase describes popular places shaped by large-scale tourism.","zh":"這個短語描述受大規模旅遊塑造的熱門地方。"}],"source":"158 - Travel Accounts.pdf","sourcePage":21},{"front":"people from wealthy countries","meaning":"來自富裕國家的人","examples":[{"en":"People from wealthy countries travelled for leisure.","zh":"來自富裕國家的人為休閒而旅行。"},{"en":"People from wealthy countries are individuals from nations where incomes and living standards are generally high.","zh":"people from wealthy countries 指來自收入和生活水平普遍較高國家的人。"},{"en":"People from wealthy countries may have more paid holidays and money for overseas trips.","zh":"來自富裕國家的人可能有更多有薪假期和海外旅行金錢。"},{"en":"Tourism can grow quickly when people from wealthy countries spend money abroad.","zh":"當來自富裕國家的人在海外消費，旅遊業可以快速增長。"},{"en":"This phrase points to economic background, not personal character.","zh":"這個短語指出經濟背景，而不是個人性格。"}],"source":"158 - Travel Accounts.pdf","sourcePage":21},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter from the choices given.","zh":"學生從給定選項中選出正確字母。"},{"en":"Choose the correct letter means select the answer option marked by the right letter.","zh":"choose the correct letter 指選出以正確字母標示的答案選項。"},{"en":"In multiple-choice questions, students choose the correct letter instead of writing a full sentence.","zh":"在選擇題中，學生選出正確字母，而不是寫完整句子。"},{"en":"Students should read all options before they choose the correct letter.","zh":"學生在選出正確字母前，應閱讀所有選項。"},{"en":"This instruction is common in reading and listening tests.","zh":"這個指示常見於閱讀和聆聽測驗。"}],"source":"158 - Travel Accounts.pdf","sourcePage":21},{"front":"why did some people travel","meaning":"為甚麼有些人旅行","examples":[{"en":"The question asks why some people travelled in early times.","zh":"這條問題問為甚麼有些人在早期時代旅行。"},{"en":"Why did some people travel asks for the reasons behind their journeys.","zh":"why did some people travel 是詢問他們旅程背後的原因。"},{"en":"Students should answer why some people travelled by looking for motives in the text.","zh":"學生應透過在文章中尋找動機，回答為甚麼有些人旅行。"},{"en":"People may travel because of trade, religion, work, danger, or curiosity.","zh":"人們可能因貿易、宗教、工作、危險或好奇而旅行。"},{"en":"This question word why requires causes, not just places or dates.","zh":"why 這個疑問詞要求原因，而不只是地點或日期。"}],"source":"158 - Travel Accounts.pdf","sourcePage":21},{"front":"in early times","meaning":"在早期時代","examples":[{"en":"People travelled for many reasons in early times.","zh":"在早期時代，人們因許多原因旅行。"},{"en":"In early times means during ancient or earlier historical periods.","zh":"in early times 指在古代或較早歷史時期。"},{"en":"In early times, people often travelled by foot, animal, boat, or caravan.","zh":"在早期時代，人們常步行、騎牲畜、乘船或隨商隊旅行。"},{"en":"In early times, travel was slower and more dangerous than it is today.","zh":"在早期時代，旅行比今天更慢也更危險。"},{"en":"This phrase is broad and usually needs context from the passage.","zh":"這個短語較廣泛，通常需要文章上下文。"}],"source":"158 - Travel Accounts.pdf","sourcePage":21},{"front":"conduct research on","meaning":"對……進行研究","examples":[{"en":"Some travellers conducted research on foreign places.","zh":"有些旅行者對外地進行研究。"},{"en":"To conduct research on something means to study it carefully and systematically.","zh":"conduct research on something 指仔細而有系統地研究某事。"},{"en":"Students may conduct research on local food waste for a project.","zh":"學生可能為項目對本地廚餘進行研究。"},{"en":"Doctors conduct research on new treatments before recommending them widely.","zh":"醫生在廣泛推薦新療法前會對其進行研究。"},{"en":"This phrase is formal and suggests organised investigation.","zh":"這個短語語氣正式，表示有組織的調查。"}],"source":"158 - Travel Accounts.pdf","sourcePage":21},{"front":"gain a better understanding of","meaning":"更深入了解","examples":[{"en":"Travel can help people gain a better understanding of other societies.","zh":"旅行可以幫助人更深入了解其他社會。"},{"en":"To gain a better understanding of something means to learn about it more clearly and deeply.","zh":"gain a better understanding of something 指更清楚、更深入地了解某事。"},{"en":"Volunteering can help students gain a better understanding of poverty.","zh":"做義工可以幫助學生更深入了解貧窮。"},{"en":"Meeting local residents helps tourists gain a better understanding of a city.","zh":"與本地居民見面幫助遊客更深入了解一座城市。"},{"en":"This phrase focuses on improved knowledge, not just seeing something briefly.","zh":"這個短語聚焦更好的知識，而不是短暫看見某事。"}],"source":"158 - Travel Accounts.pdf","sourcePage":21},{"front":"other people and places","meaning":"其他人和地方","examples":[{"en":"Travel accounts describe other people and places.","zh":"旅行記錄描述其他人和地方。"},{"en":"Other people and places means communities, individuals, and locations outside one’s own familiar world.","zh":"other people and places 指自己熟悉世界以外的社群、個人和地點。"},{"en":"Books about other people and places can reduce narrow thinking.","zh":"關於其他人和地方的書可以減少狹隘思維。"},{"en":"Learning about other people and places helps students compare cultures respectfully.","zh":"了解其他人和地方幫助學生尊重地比較文化。"},{"en":"This phrase combines human society with geography.","zh":"這個短語結合人類社會與地理。"}],"source":"158 - Travel Accounts.pdf","sourcePage":21},{"front":"reflect one’s own experiences","meaning":"反映某人自己的經歷","examples":[{"en":"Travellers’ accounts reflect the writers’ own experiences.","zh":"旅行者的記錄反映作者自己的經歷。"},{"en":"To reflect one’s own experiences means to show what a person has personally seen, felt, or lived through.","zh":"reflect one’s own experiences 指顯示一個人親身看見、感受或經歷過的事。"},{"en":"A diary reflects one’s own experiences more directly than a textbook.","zh":"日記比教科書更直接反映某人自己的經歷。"},{"en":"Writers may reflect their own experiences when they describe fear, surprise, or homesickness.","zh":"作家描述恐懼、驚訝或思鄉時，可能反映自己的經歷。"},{"en":"This phrase reminds readers that writing often includes a personal viewpoint.","zh":"這個短語提醒讀者，寫作常包含個人觀點。"}],"source":"158 - Travel Accounts.pdf","sourcePage":22},{"front":"social lives","meaning":"社交生活；社會生活","examples":[{"en":"Travel accounts may reflect travellers’ social lives.","zh":"旅行記錄可能反映旅行者的社交生活。"},{"en":"Social lives are the relationships, meetings, habits, and activities people share with others.","zh":"social lives 指人們與他人共有的關係、聚會、習慣和活動。"},{"en":"Students’ social lives may include clubs, friendships, meals, and online chats.","zh":"學生的社交生活可能包括學會、友誼、聚餐和網上聊天。"},{"en":"Moving abroad can change people’s social lives because they must build new relationships.","zh":"移居海外可以改變人的社交生活，因為他們必須建立新關係。"},{"en":"This phrase focuses on how people interact, not just what they do alone.","zh":"這個短語聚焦人們如何互動，而不只是獨自做甚麼。"}],"source":"158 - Travel Accounts.pdf","sourcePage":22},{"front":"travel to holy sites","meaning":"前往聖地","examples":[{"en":"Many pilgrims travelled to holy sites.","zh":"許多朝聖者前往聖地。"},{"en":"To travel to holy sites means to journey to places considered sacred by a religion.","zh":"travel to holy sites 指前往被宗教視為神聖的地方。"},{"en":"Believers may travel to holy sites for prayer, healing, or thanksgiving.","zh":"信徒可能為祈禱、療癒或感恩而前往聖地。"},{"en":"Travel to holy sites can create routes, guesthouses, and written accounts.","zh":"前往聖地可以形成路線、客棧和書面記錄。"},{"en":"This phrase describes religious movement rather than ordinary sightseeing.","zh":"這個短語描述宗教流動，而不是普通觀光。"}],"source":"158 - Travel Accounts.pdf","sourcePage":22},{"front":"large numbers of","meaning":"大量","examples":[{"en":"Large numbers of travel books were published in the early modern era.","zh":"大量旅行書在近代早期出版。"},{"en":"Large numbers of means many people or things.","zh":"large numbers of 指許多人或事物。"},{"en":"Large numbers of students use public transport every morning.","zh":"大量學生每天早上使用公共交通。"},{"en":"Large numbers of visitors can bring money but also crowding.","zh":"大量訪客可以帶來金錢，但也帶來擁擠。"},{"en":"This phrase stresses quantity without giving an exact figure.","zh":"這個短語強調數量，而不提供精確數字。"}],"source":"158 - Travel Accounts.pdf","sourcePage":22},{"front":"provide what the public wanted","meaning":"提供公眾想要的東西","examples":[{"en":"Publishers provided what the public wanted.","zh":"出版商提供公眾想要的東西。"},{"en":"To provide what the public wanted means to supply products or information that many people desired.","zh":"provide what the public wanted 指供應許多人想要的產品或資料。"},{"en":"A radio station provides what the public wants when it plays popular programmes.","zh":"電台播放受歡迎節目時，就是提供公眾想要的東西。"},{"en":"Publishers printed travel accounts because readers wanted news about distant places.","zh":"出版商印刷旅行記錄，因為讀者想要有關遠方的消息。"},{"en":"This phrase links business decisions with public demand.","zh":"這個短語把商業決定與公眾需求連接起來。"}],"source":"158 - Travel Accounts.pdf","sourcePage":22},{"front":"encourage public feedback","meaning":"鼓勵公眾回應","examples":[{"en":"A publication may encourage public feedback.","zh":"出版物可能鼓勵公眾回應。"},{"en":"To encourage public feedback means to invite ordinary people to give opinions or responses.","zh":"encourage public feedback 指邀請普通人提供意見或回應。"},{"en":"A school survey can encourage public feedback from parents.","zh":"學校調查可以鼓勵家長給予公眾回饋。"},{"en":"Public feedback helps organisations discover mistakes, needs, and complaints.","zh":"公眾回應幫助機構發現錯誤、需要和投訴。"},{"en":"This phrase focuses on communication from the public back to the provider.","zh":"這個短語重點在於公眾向提供者作出溝通。"}],"source":"158 - Travel Accounts.pdf","sourcePage":22},{"front":"make a profit","meaning":"賺取利潤","examples":[{"en":"Some publishers aimed to make a profit.","zh":"有些出版商旨在賺取利潤。"},{"en":"To make a profit means to earn more money than the cost of producing or selling something.","zh":"make a profit 指賺到的錢多於生產或銷售成本。"},{"en":"A café must make a profit to pay rent and staff.","zh":"咖啡店必須賺取利潤，才能支付租金和員工薪金。"},{"en":"Businesses may cut waste or raise prices to make a profit.","zh":"企業可能減少浪費或提高價格來賺取利潤。"},{"en":"This phrase is about financial gain, not just receiving money.","zh":"這個短語關乎財務收益，而不只是收到金錢。"}],"source":"158 - Travel Accounts.pdf","sourcePage":22},{"front":"promote travel to","meaning":"推廣前往……旅行","examples":[{"en":"Travel books could promote travel to new regions.","zh":"旅行書可以推廣前往新地區旅行。"},{"en":"To promote travel to a place means to encourage people to visit it.","zh":"promote travel to a place 指鼓勵人們到訪某地。"},{"en":"A tourism board may promote travel to small towns through videos and festivals.","zh":"旅遊局可能透過影片和節日推廣前往小鎮旅行。"},{"en":"Cheap package tours can promote travel to places that were once difficult to reach.","zh":"便宜套票可以推廣前往曾經難以到達的地方旅行。"},{"en":"This phrase focuses on increasing interest and visits.","zh":"這個短語重點在於增加興趣和到訪量。"}],"source":"158 - Travel Accounts.pdf","sourcePage":22},{"front":"stimulate the travel market","meaning":"刺激旅遊市場","examples":[{"en":"Mass transport stimulated the travel market in the 20th century.","zh":"大眾運輸在20世紀刺激了旅遊市場。"},{"en":"To stimulate the travel market means to increase travel demand and business activity.","zh":"stimulate the travel market 指增加旅遊需求和商業活動。"},{"en":"Discount air tickets can stimulate the travel market during quiet seasons.","zh":"折扣機票可以在淡季刺激旅遊市場。"},{"en":"Better trains stimulate the travel market by making weekend trips easier.","zh":"更好的火車讓週末旅行更容易，從而刺激旅遊市場。"},{"en":"This phrase connects transport, prices, and consumer demand with tourism growth.","zh":"這個短語把交通、價格和消費者需求與旅遊增長連接起來。"}],"source":"158 - Travel Accounts.pdf","sourcePage":22}],"ielts/reading/passage-2/Practice 159":[{"front":"Development of Public Management Theory","meaning":"公共管理理論的發展","examples":[{"en":"The passage explains the development of public management theory.","zh":"文章解釋公共管理理論的發展。"},{"en":"The development of public management theory means how ideas about managing public organisations changed over time.","zh":"公共管理理論的發展是指關於管理公共組織的想法如何隨時間改變。"},{"en":"Students may study the development of public management theory to understand why governments no longer rely only on strict hierarchy.","zh":"學生可能研究公共管理理論的發展，以理解為何政府不再只依賴嚴格層級。"},{"en":"New social problems can lead to the development of public management theory because older methods may no longer work well.","zh":"新的社會問題可能推動公共管理理論的發展，因為舊方法未必仍然有效。"},{"en":"The development of public management theory shows that management ideas often change with society.","zh":"公共管理理論的發展顯示，管理思想常會隨社會改變。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":1},{"front":"bureaucratic management","meaning":"官僚式管理","examples":[{"en":"Bureaucratic management is presented as the classical model.","zh":"官僚式管理被呈現為古典模式。"},{"en":"Bureaucratic management is a system that uses clear rules, hierarchy, and fixed procedures to run an organisation.","zh":"官僚式管理是一種利用清晰規則、層級和固定程序來運作組織的制度。"},{"en":"A government office may use bureaucratic management so every application follows the same steps.","zh":"政府辦公室可能使用官僚式管理，令每份申請都跟隨相同步驟。"},{"en":"Bureaucratic management can create fairness, but it may also slow decisions when rules are too strict.","zh":"官僚式管理可以帶來公平，但當規則過於嚴格時，也可能拖慢決策。"},{"en":"Large organisations often use bureaucratic management when consistency is more important than speed.","zh":"當一致性比速度更重要時，大型組織常使用官僚式管理。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":1},{"front":"the classical model","meaning":"古典模式","examples":[{"en":"Bureaucratic management is described as the classical model.","zh":"官僚式管理被描述為古典模式。"},{"en":"The classical model means the older, standard way of understanding how something should work.","zh":"古典模式是指理解某事物應如何運作的較早期、標準方式。"},{"en":"In management lessons, students often learn the classical model before studying newer approaches.","zh":"在管理課堂中，學生通常先學古典模式，再學較新的取向。"},{"en":"The classical model can be useful because it gives clear basic rules, but it may not fit every modern workplace.","zh":"古典模式可以有用，因為它提供清晰基本規則，但未必適合每個現代工作場所。"},{"en":"When people call bureaucracy the classical model, they mean it was an early and influential management approach.","zh":"當人們稱官僚制度為古典模式時，他們是指它是一種早期且有影響力的管理取向。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":1},{"front":"bridge the gap between","meaning":"彌合……之間的差距","examples":[{"en":"Several theories bridge the gap between private- and public-sector management.","zh":"幾種理論彌合私營及公營部門管理之間的差距。"},{"en":"To bridge the gap between two areas means to connect them or reduce the difference between them.","zh":"彌合兩個範疇之間的差距，是指把它們連接起來或減少它們之間的分別。"},{"en":"Extra language classes can bridge the gap between weak students and the level needed for university.","zh":"額外語言課程可以彌合較弱學生與大學所需水平之間的差距。"},{"en":"Training programmes bridge the gap between classroom knowledge and real workplace skills.","zh":"培訓計劃彌合課堂知識與真實工作技能之間的差距。"},{"en":"Good examples can bridge the gap between abstract theory and daily life.","zh":"好例子可以彌合理論抽象概念與日常生活之間的差距。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":1},{"front":"private- and public-sector management","meaning":"私營及公營部門管理","examples":[{"en":"Some theories apply to both private- and public-sector management.","zh":"有些理論適用於私營及公營部門管理。"},{"en":"Private- and public-sector management refers to managing businesses and government or public organisations.","zh":"私營及公營部門管理是指管理企業以及政府或公共組織。"},{"en":"A hospital administrator may need ideas from both private- and public-sector management.","zh":"醫院行政人員可能需要同時運用私營及公營部門管理的概念。"},{"en":"Private-sector management often focuses on profit, while public-sector management must also consider public responsibility.","zh":"私營部門管理常重視利潤，而公營部門管理亦必須考慮公共責任。"},{"en":"Comparing private- and public-sector management helps students see why government decisions are often more complicated.","zh":"比較私營及公營部門管理，有助學生理解為何政府決策通常更複雜。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":1},{"front":"one good example is","meaning":"一個很好的例子是","examples":[{"en":"One good example is the work of Max Weber.","zh":"一個很好的例子是馬克斯・韋伯的著作。"},{"en":"One good example is used when you want to introduce a clear case that supports your point.","zh":"「一個很好的例子是」用於引入一個清楚支持你觀點的例子。"},{"en":"Many cities improved public transport; one good example is Singapore’s rail system.","zh":"許多城市改善了公共交通；一個很好的例子是新加坡的鐵路系統。"},{"en":"If you want to show how technology helps learning, one good example is online video lessons.","zh":"如果你想展示科技如何幫助學習，一個很好的例子是網上影片課程。"},{"en":"One good example is useful because it makes an abstract idea easier to understand.","zh":"一個很好的例子很有用，因為它令抽象概念更易理解。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":1},{"front":"German sociologist","meaning":"德國社會學家","examples":[{"en":"Max Weber was a German sociologist and political economist.","zh":"馬克斯・韋伯是一位德國社會學家和政治經濟學家。"},{"en":"A German sociologist is a scholar from Germany who studies society and human behaviour.","zh":"德國社會學家是來自德國、研究社會和人類行為的學者。"},{"en":"A German sociologist may study how rules, work, religion, and authority shape people’s lives.","zh":"德國社會學家可能研究規則、工作、宗教和權威如何塑造人們的生活。"},{"en":"Weber became an important German sociologist because his ideas influenced politics, economics, and management.","zh":"韋伯成為重要的德國社會學家，因為他的思想影響了政治、經濟和管理。"},{"en":"When students read a German sociologist, they often meet theories about modern society.","zh":"當學生閱讀德國社會學家的著作時，他們常會接觸關於現代社會的理論。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":1},{"front":"political economist","meaning":"政治經濟學家","examples":[{"en":"Max Weber was also a political economist.","zh":"馬克斯・韋伯也是一位政治經濟學家。"},{"en":"A political economist studies how politics, government, and the economy affect one another.","zh":"政治經濟學家研究政治、政府和經濟如何互相影響。"},{"en":"A political economist may ask how tax policy changes business behaviour.","zh":"政治經濟學家可能會問稅收政策如何改變商業行為。"},{"en":"Political economists study poverty because economic problems are often linked to government decisions.","zh":"政治經濟學家研究貧窮，因為經濟問題常與政府決策有關。"},{"en":"A political economist does not look at money alone; they also look at power and institutions.","zh":"政治經濟學家不只研究金錢；他們也研究權力和制度。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":1},{"front":"explore the ideal bureaucracy","meaning":"探討理想官僚制度","examples":[{"en":"Max Weber explored the ideal bureaucracy in his work.","zh":"馬克斯・韋伯在其著作中探討理想官僚制度。"},{"en":"To explore the ideal bureaucracy means to examine what a perfectly organised rule-based system would look like.","zh":"探討理想官僚制度是指研究一個完美組織化、以規則為基礎的制度會是甚麼樣子。"},{"en":"In class, students may explore the ideal bureaucracy by discussing clear hierarchy and fixed procedures.","zh":"在課堂上，學生可能透過討論清晰層級和固定程序來探討理想官僚制度。"},{"en":"Scholars explore the ideal bureaucracy to understand both its strengths and its dangers.","zh":"學者探討理想官僚制度，以理解它的優點和危險。"},{"en":"When we explore the ideal bureaucracy, we ask how rules can create order without making organisations too rigid.","zh":"當我們探討理想官僚制度時，我們會問規則如何創造秩序，而不令組織過於僵化。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":1},{"front":"ideal bureaucracy","meaning":"理想官僚制度","examples":[{"en":"Weber explored the idea of an ideal bureaucracy.","zh":"韋伯探討了理想官僚制度的概念。"},{"en":"An ideal bureaucracy is a perfectly organised system based on rules, roles, hierarchy, and fairness.","zh":"理想官僚制度是一個以規則、角色、層級和公平為基礎的完美組織制度。"},{"en":"A passport office may try to follow an ideal bureaucracy by treating every applicant according to the same rules.","zh":"護照辦事處可能嘗試跟隨理想官僚制度，按相同規則對待每位申請人。"},{"en":"An ideal bureaucracy can reduce personal favouritism because decisions are based on official procedures.","zh":"理想官僚制度可以減少個人偏袒，因為決定是根據官方程序作出的。"},{"en":"In reality, an ideal bureaucracy is difficult to achieve because people and situations are often complicated.","zh":"在現實中，理想官僚制度很難達到，因為人和情況往往很複雜。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":1},{"front":"The Protestant Ethic and the Spirit of Capitalism","meaning":"《新教倫理與資本主義精神》","examples":[{"en":"Weber explored bureaucracy in The Protestant Ethic and the Spirit of Capitalism.","zh":"韋伯在《新教倫理與資本主義精神》中探討官僚制度。"},{"en":"The Protestant Ethic and the Spirit of Capitalism is a famous work associated with Max Weber’s ideas about religion, work, and modern capitalism.","zh":"《新教倫理與資本主義精神》是與馬克斯・韋伯關於宗教、工作和現代資本主義思想相關的著名作品。"},{"en":"Students may read The Protestant Ethic and the Spirit of Capitalism to understand how beliefs can influence economic behaviour.","zh":"學生可能閱讀《新教倫理與資本主義精神》，以理解信念如何影響經濟行為。"},{"en":"The Protestant Ethic and the Spirit of Capitalism connects cultural values with the growth of modern economic life.","zh":"《新教倫理與資本主義精神》把文化價值與現代經濟生活的發展連繫起來。"},{"en":"This title is often mentioned when discussing Weber’s influence on sociology and management thought.","zh":"討論韋伯對社會學和管理思想的影響時，這個書名常被提及。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":1},{"front":"according to","meaning":"根據……","examples":[{"en":"According to Weber, bureaucracy is the most efficient form of organisation.","zh":"根據韋伯，官僚制度是最有效率的組織形式。"},{"en":"According to is used to show where information, an opinion, or a claim comes from.","zh":"「according to」用來表示資料、意見或說法的來源。"},{"en":"According to the timetable, the train leaves at eight o’clock.","zh":"根據時間表，火車八點開出。"},{"en":"According to the doctor, regular sleep can improve concentration.","zh":"根據醫生所說，規律睡眠可以改善專注力。"},{"en":"When writing essays, students use according to before naming a source or thinker.","zh":"寫文章時，學生會在指出來源或思想家前使用 according to。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":2},{"front":"the most efficient form of organisation","meaning":"最有效率的組織形式","examples":[{"en":"Weber saw bureaucracy as the most efficient form of organisation.","zh":"韋伯認為官僚制度是最有效率的組織形式。"},{"en":"The most efficient form of organisation means the structure that uses time, people, and resources with the least waste.","zh":"最有效率的組織形式是指最少浪費時間、人手和資源的結構。"},{"en":"A delivery company may think a centralised system is the most efficient form of organisation for handling orders.","zh":"物流公司可能認為中央化制度是處理訂單的最有效率組織形式。"},{"en":"A system becomes the most efficient form of organisation when it reduces confusion and repeated work.","zh":"當一個制度減少混亂和重複工作時，它就會成為最有效率的組織形式。"},{"en":"What counts as the most efficient form of organisation may change when the task or environment changes.","zh":"甚麼算是最有效率的組織形式，可能會隨任務或環境改變。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":2},{"front":"well-defined line of authority","meaning":"清晰界定的權力層級","examples":[{"en":"Bureaucracy has a well-defined line of authority.","zh":"官僚制度有清晰界定的權力層級。"},{"en":"A well-defined line of authority means everyone knows who has the power to give instructions and make decisions.","zh":"清晰界定的權力層級是指每個人都知道誰有權發出指示和作出決定。"},{"en":"In a school, a well-defined line of authority helps teachers know when to report problems to senior staff.","zh":"在學校，清晰界定的權力層級幫助老師知道何時向高層職員報告問題。"},{"en":"A well-defined line of authority can prevent confusion during emergencies.","zh":"清晰界定的權力層級可以在緊急情況中防止混亂。"},{"en":"Without a well-defined line of authority, workers may receive conflicting instructions.","zh":"如果沒有清晰界定的權力層級，員工可能收到互相矛盾的指示。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":2},{"front":"clear rules and regulations","meaning":"清晰規則和規例","examples":[{"en":"Bureaucracy depends on clear rules and regulations.","zh":"官僚制度依賴清晰規則和規例。"},{"en":"Clear rules and regulations are written instructions that tell people what they can and cannot do.","zh":"清晰規則和規例是告訴人們可以做甚麼和不可以做甚麼的書面指示。"},{"en":"A library needs clear rules and regulations so students know how long they can borrow books.","zh":"圖書館需要清晰規則和規例，讓學生知道可以借書多久。"},{"en":"Clear rules and regulations can reduce unfair treatment because everyone follows the same standard.","zh":"清晰規則和規例可以減少不公平對待，因為每個人都跟隨相同標準。"},{"en":"Rules and regulations should be clear, but they should not become so complicated that people cannot understand them.","zh":"規則和規例應該清晰，但不應複雜到令人無法理解。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":2},{"front":"be strictly followed","meaning":"被嚴格遵守","examples":[{"en":"The rules and regulations are strictly followed.","zh":"規則和規例被嚴格遵守。"},{"en":"If rules are strictly followed, people obey them carefully without making casual exceptions.","zh":"如果規則被嚴格遵守，人們會仔細服從，不會隨便例外處理。"},{"en":"Safety rules in a laboratory must be strictly followed to prevent accidents.","zh":"實驗室安全規則必須被嚴格遵守，以防止意外。"},{"en":"When exam rules are strictly followed, students trust that the test is fair.","zh":"當考試規則被嚴格遵守時，學生會相信考試是公平的。"},{"en":"Rules should be strictly followed when public safety is involved.","zh":"涉及公共安全時，規則應被嚴格遵守。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":2},{"front":"identify three types of","meaning":"識別出三種類型的……","examples":[{"en":"Weber identified three types of power in an organisation.","zh":"韋伯識別出組織中三種類型的權力。"},{"en":"To identify three types of something means to name and separate it into three clear categories.","zh":"識別出三種類型的某事物，是指把它命名並分成三個清晰類別。"},{"en":"A teacher may identify three types of writing mistakes: grammar, vocabulary, and organisation.","zh":"老師可能識別出三種類型的寫作錯誤：文法、詞彙和組織。"},{"en":"Researchers identify three types of customers so they can understand different needs.","zh":"研究人員識別出三種類型的顧客，以理解不同需要。"},{"en":"When you identify three types of a problem, it becomes easier to explain and solve.","zh":"當你識別出某問題的三種類型時，就更容易解釋和解決。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":2},{"front":"traditional power","meaning":"傳統權力","examples":[{"en":"Traditional power was one of Weber’s three types of power.","zh":"傳統權力是韋伯三種權力之一。"},{"en":"Traditional power comes from long-established customs, family position, or inherited authority.","zh":"傳統權力來自長久建立的習俗、家庭地位或繼承而來的權威。"},{"en":"A village elder may have traditional power because people respect old customs.","zh":"村中長者可能擁有傳統權力，因為人們尊重舊習俗。"},{"en":"Traditional power can be stable, but it may resist change when society develops.","zh":"傳統權力可以穩定，但當社會發展時，它可能抗拒改變。"},{"en":"In some families, traditional power gives older members more influence over decisions.","zh":"在一些家庭中，傳統權力令年長成員對決定有更大影響。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":2},{"front":"charismatic power","meaning":"魅力型權力","examples":[{"en":"Charismatic power depends on the personal appeal of a leader.","zh":"魅力型權力取決於領袖的個人吸引力。"},{"en":"Charismatic power is influence based on a person’s charm, confidence, or ability to inspire others.","zh":"魅力型權力是基於一個人的魅力、自信或啟發他人的能力而產生的影響力。"},{"en":"A speaker with charismatic power can make people believe in a difficult project.","zh":"擁有魅力型權力的演講者可以令人相信一個困難項目。"},{"en":"Charismatic power can motivate followers quickly, but it may depend too much on one person.","zh":"魅力型權力可以快速激勵追隨者，但可能過度依賴某一個人。"},{"en":"Leaders with charismatic power often use stories, emotion, and confidence to gain support.","zh":"擁有魅力型權力的領袖常使用故事、情感和自信來取得支持。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":2},{"front":"bureaucratic or legal power","meaning":"官僚式或法定權力","examples":[{"en":"Bureaucratic or legal power is based on formal rules.","zh":"官僚式或法定權力以正式規則為基礎。"},{"en":"Bureaucratic or legal power comes from an official position, written law, or accepted procedure.","zh":"官僚式或法定權力來自正式職位、成文法律或被接受的程序。"},{"en":"A judge has bureaucratic or legal power because the law gives them authority.","zh":"法官擁有官僚式或法定權力，因為法律賦予他們權威。"},{"en":"Bureaucratic or legal power can continue even when the person holding the role changes.","zh":"即使擔任職位的人改變，官僚式或法定權力仍可延續。"},{"en":"In an office, bureaucratic or legal power tells workers whose decisions are officially valid.","zh":"在辦公室中，官僚式或法定權力告訴員工誰的決定具有正式效力。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":2},{"front":"characteristics of","meaning":"……的特徵","examples":[{"en":"The passage describes the characteristics of bureaucratic organisations.","zh":"文章描述官僚式組織的特徵。"},{"en":"The characteristics of something are the main features that help people recognise or understand it.","zh":"某事物的特徵是幫助人們辨認或理解它的主要特色。"},{"en":"The characteristics of a good teacher include patience, clear explanation, and fairness.","zh":"好老師的特徵包括耐性、清晰解釋和公平。"},{"en":"Studying the characteristics of a disease helps doctors choose the right treatment.","zh":"研究疾病的特徵有助醫生選擇正確治療。"},{"en":"When describing an organisation, its characteristics may include size, structure, rules, and culture.","zh":"描述組織時，其特徵可能包括規模、結構、規則和文化。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":2},{"front":"bureaucratic organisations","meaning":"官僚式組織","examples":[{"en":"Bureaucratic organisations follow formal rules and hierarchy.","zh":"官僚式組織遵循正式規則和層級。"},{"en":"Bureaucratic organisations are organisations that operate through fixed roles, written rules, and clear authority.","zh":"官僚式組織是透過固定角色、書面規則和清晰權威運作的組織。"},{"en":"Government departments are often bureaucratic organisations because they must treat cases according to formal procedures.","zh":"政府部門通常是官僚式組織，因為它們必須按正式程序處理個案。"},{"en":"Bureaucratic organisations can be reliable, but they may become slow if every small decision needs approval.","zh":"官僚式組織可以可靠，但如果每個小決定都需要批准，就可能變得緩慢。"},{"en":"A university can become a bureaucratic organisation when paperwork controls many daily decisions.","zh":"當文書工作控制許多日常決定時，大學也可能變成官僚式組織。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":2},{"front":"admire something for","meaning":"因……而欣賞某事物","examples":[{"en":"Weber admired bureaucracy for its trustworthiness.","zh":"韋伯因官僚制度的可靠性而欣賞它。"},{"en":"To admire something for a quality means to respect it because it has that quality.","zh":"因某種特質而欣賞某事物，是指因它具備該特質而尊重它。"},{"en":"Many people admire nurses for their patience and courage.","zh":"許多人因護士的耐性和勇氣而欣賞他們。"},{"en":"Students may admire a teacher for explaining difficult ideas clearly.","zh":"學生可能因老師能清楚解釋困難概念而欣賞他。"},{"en":"We can admire a system for its fairness while still criticising its weaknesses.","zh":"我們可以因一個制度的公平性而欣賞它，同時仍批評其弱點。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":3},{"front":"trustworthiness","meaning":"可靠性","examples":[{"en":"Weber admired bureaucracy for its trustworthiness.","zh":"韋伯因官僚制度的可靠性而欣賞它。"},{"en":"Trustworthiness means the quality of being reliable, honest, and safe to depend on.","zh":"可靠性是指值得依靠、誠實和可靠的品質。"},{"en":"A bank needs trustworthiness because people leave their savings there.","zh":"銀行需要可靠性，因為人們把儲蓄存放在那裡。"},{"en":"Trustworthiness grows when a person keeps promises and admits mistakes.","zh":"當一個人守承諾並承認錯誤時，可靠性會提升。"},{"en":"In public service, trustworthiness is important because citizens must believe decisions are fair.","zh":"在公共服務中，可靠性很重要，因為市民必須相信決策是公平的。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":3},{"front":"be constituted by","meaning":"由……組成","examples":[{"en":"Bureaucracy was constituted by professional public officials.","zh":"官僚制度由專業公職人員組成。"},{"en":"To be constituted by something means to be made up of particular parts, people, or elements.","zh":"由某事物組成，是指由特定部分、人員或元素構成。"},{"en":"A committee may be constituted by teachers, parents, and student representatives.","zh":"委員會可能由老師、家長和學生代表組成。"},{"en":"A healthy diet is constituted by balanced portions of different food groups.","zh":"健康飲食由不同食物類別的均衡分量組成。"},{"en":"When an organisation is constituted by trained workers, it can usually operate more consistently.","zh":"當組織由受過訓練的員工組成時，它通常能更一致地運作。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":3},{"front":"professional, ethical public officials","meaning":"專業且有操守的公職人員","examples":[{"en":"Bureaucracy depended on professional, ethical public officials.","zh":"官僚制度依賴專業且有操守的公職人員。"},{"en":"Professional, ethical public officials are government workers who act skilfully, fairly, and honestly.","zh":"專業且有操守的公職人員是指有能力、公平和誠實行事的政府工作人員。"},{"en":"Citizens trust public services more when professional, ethical public officials handle their cases.","zh":"當專業且有操守的公職人員處理個案時，市民會更信任公共服務。"},{"en":"Professional, ethical public officials can prevent corruption because they follow rules and respect public duty.","zh":"專業且有操守的公職人員可以防止貪污，因為他們遵守規則並尊重公共職責。"},{"en":"A strong public system needs professional, ethical public officials, not only strict written procedures.","zh":"強大的公共制度需要專業且有操守的公職人員，而不只是嚴格的書面程序。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":3},{"front":"dedicate oneself to","meaning":"致力於","examples":[{"en":"Public officials dedicated themselves to public service.","zh":"公職人員致力於公共服務。"},{"en":"To dedicate oneself to something means to give serious time, energy, and effort to it.","zh":"致力於某事，是指認真投入時間、精力和努力。"},{"en":"A doctor may dedicate herself to helping patients in poor communities.","zh":"醫生可能致力於幫助貧困社區的病人。"},{"en":"Students who dedicate themselves to daily practice usually improve steadily.","zh":"致力於每日練習的學生通常會穩步進步。"},{"en":"Dedicating oneself to a cause often requires patience, discipline, and personal sacrifice.","zh":"致力於一項事業往往需要耐性、自律和個人犧牲。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":3},{"front":"public service","meaning":"公共服務","examples":[{"en":"Public officials dedicated themselves to public service.","zh":"公職人員致力於公共服務。"},{"en":"Public service means work done to help citizens and support the needs of society.","zh":"公共服務是指幫助市民並支持社會需要的工作。"},{"en":"Teaching in a government school is a form of public service.","zh":"在政府學校任教是一種公共服務。"},{"en":"Public service requires fairness because workers serve the public, not only private customers.","zh":"公共服務需要公平，因為工作者服務的是公眾，而不只是私人顧客。"},{"en":"Good public service makes daily life safer, cleaner, and more organised.","zh":"良好的公共服務令日常生活更安全、更清潔和更有秩序。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":3},{"front":"in return for","meaning":"作為……的回報","examples":[{"en":"Officials served the public in return for job security.","zh":"官員服務公眾，作為工作保障的回報。"},{"en":"In return for means as a payment, reward, or exchange for something given or done.","zh":"「in return for」是指作為某事物或某行動的付款、獎賞或交換。"},{"en":"A student may help clean the classroom in return for extra reading time.","zh":"學生可能幫忙清潔課室，作為額外閱讀時間的回報。"},{"en":"Workers give time and skill in return for wages and benefits.","zh":"員工付出時間和技能，作為工資和福利的回報。"},{"en":"In return for public trust, officials must act honestly and responsibly.","zh":"作為公眾信任的回報，官員必須誠實和負責任地行事。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":3},{"front":"job security","meaning":"工作保障","examples":[{"en":"Public officials received job security in return for their service.","zh":"公職人員因其服務而獲得工作保障。"},{"en":"Job security means the confidence that a person is unlikely to lose their job suddenly.","zh":"工作保障是指一個人相信自己不太可能突然失去工作的信心。"},{"en":"Many workers value job security because it helps them plan rent, family expenses, and savings.","zh":"許多員工重視工作保障，因為它有助他們計劃租金、家庭開支和儲蓄。"},{"en":"Job security can reduce stress, but it should not become an excuse for poor performance.","zh":"工作保障可以減少壓力，但不應成為表現差的藉口。"},{"en":"Public employment often attracts people who want long-term job security.","zh":"公職常吸引希望有長期工作保障的人。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":3},{"front":"public employment","meaning":"公職","examples":[{"en":"Public employment offered job security and other advantages.","zh":"公職提供工作保障和其他好處。"},{"en":"Public employment means working for the government or a public organisation.","zh":"公職是指為政府或公共組織工作。"},{"en":"Teachers, police officers, and clerks in government offices may all be in public employment.","zh":"老師、警察和政府辦公室文員都可能屬於公職。"},{"en":"Public employment can provide stable benefits because the work is supported by public institutions.","zh":"公職可以提供穩定福利，因為工作由公共機構支持。"},{"en":"People choose public employment for different reasons, including service, stability, and career development.","zh":"人們選擇公職有不同原因，包括服務、穩定和事業發展。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":3},{"front":"a high degree of","meaning":"高度的……","examples":[{"en":"Bureaucracy involves a high degree of division of labour.","zh":"官僚制度涉及高度的分工。"},{"en":"A high degree of something means a large amount or strong level of it.","zh":"高度的某事物是指大量或強烈程度的某事物。"},{"en":"Surgery requires a high degree of care because small mistakes can be serious.","zh":"手術需要高度謹慎，因為小錯誤可能很嚴重。"},{"en":"A research project needs a high degree of accuracy when collecting data.","zh":"研究項目在收集數據時需要高度準確性。"},{"en":"A high degree of teamwork is needed when many people must finish one task together.","zh":"當許多人必須一起完成一項任務時，需要高度團隊合作。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":3},{"front":"division of labour","meaning":"分工","examples":[{"en":"Bureaucracy involves division of labour and specialisation.","zh":"官僚制度涉及分工和專門化。"},{"en":"Division of labour means splitting work into different tasks so different people handle different parts.","zh":"分工是指把工作分成不同任務，由不同人負責不同部分。"},{"en":"In a restaurant, division of labour means cooks, waiters, and cashiers each have separate duties.","zh":"在餐廳中，分工是指廚師、侍應和收銀員各自有不同職責。"},{"en":"Division of labour can increase efficiency because workers become skilled at specific tasks.","zh":"分工可以提高效率，因為員工會熟練於特定任務。"},{"en":"Poor division of labour can cause confusion when nobody knows who should do which job.","zh":"分工不佳會造成混亂，因為沒有人知道哪項工作應由誰負責。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":3},{"front":"specialisation","meaning":"專門化","examples":[{"en":"Bureaucratic organisations rely on specialisation.","zh":"官僚式組織依賴專門化。"},{"en":"Specialisation means focusing on a particular type of work, skill, or knowledge.","zh":"專門化是指專注於某一類工作、技能或知識。"},{"en":"A hospital uses specialisation when different doctors treat the heart, eyes, or bones.","zh":"醫院中不同醫生治療心臟、眼睛或骨骼，就是使用專門化。"},{"en":"Specialisation can improve quality because people become experts in one area.","zh":"專門化可以提高質素，因為人們會成為某個領域的專家。"},{"en":"Too much specialisation may make workers less flexible when new tasks appear.","zh":"過度專門化可能令員工在新任務出現時較不靈活。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":4},{"front":"defined hierarchy of authority","meaning":"明確的權力層級","examples":[{"en":"Bureaucracy has a defined hierarchy of authority.","zh":"官僚制度有明確的權力層級。"},{"en":"A defined hierarchy of authority means the levels of power are clearly arranged from top to bottom.","zh":"明確的權力層級是指權力等級由上至下被清楚安排。"},{"en":"In a company, a defined hierarchy of authority shows who reports to whom.","zh":"在公司中，明確的權力層級顯示誰向誰匯報。"},{"en":"A defined hierarchy of authority can speed up reporting because workers know the correct channel.","zh":"明確的權力層級可以加快匯報，因為員工知道正確渠道。"},{"en":"However, a defined hierarchy of authority may slow action if every decision must move upward.","zh":"然而，如果每個決定都必須向上傳遞，明確的權力層級可能拖慢行動。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":4},{"front":"principles of rationality","meaning":"理性原則","examples":[{"en":"Bureaucratic rules follow the principles of rationality.","zh":"官僚規則遵循理性原則。"},{"en":"Principles of rationality are ideas based on logic, evidence, and sensible reasoning.","zh":"理性原則是基於邏輯、證據和合理推理的想法。"},{"en":"A school follows principles of rationality when it uses clear marking criteria instead of personal favour.","zh":"學校使用清晰評分準則而非個人偏好時，就是遵循理性原則。"},{"en":"Principles of rationality can make decisions more consistent and easier to explain.","zh":"理性原則可以令決定更一致，也更容易解釋。"},{"en":"Public policies should follow principles of rationality so citizens understand why decisions are made.","zh":"公共政策應遵循理性原則，讓市民理解為何作出決定。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":4},{"front":"objectivity and consistency","meaning":"客觀性和一致性","examples":[{"en":"Bureaucratic rules are based on objectivity and consistency.","zh":"官僚規則以客觀性和一致性為基礎。"},{"en":"Objectivity and consistency mean making decisions fairly and applying the same standard each time.","zh":"客觀性和一致性是指公平地作決定，並每次應用相同標準。"},{"en":"Teachers need objectivity and consistency when marking essays from different students.","zh":"老師批改不同學生的文章時需要客觀性和一致性。"},{"en":"Objectivity and consistency can reduce complaints because people see that rules are not personal.","zh":"客觀性和一致性可以減少投訴，因為人們會看到規則不是針對個人。"},{"en":"Without objectivity and consistency, public decisions may seem unfair or biased.","zh":"沒有客觀性和一致性，公共決策可能顯得不公平或有偏見。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":4},{"front":"duties and rights","meaning":"職責和權利","examples":[{"en":"The rules cover all employees’ duties and rights.","zh":"規則涵蓋所有員工的職責和權利。"},{"en":"Duties and rights are what people must do and what they are allowed or entitled to receive.","zh":"職責和權利是指人們必須做的事，以及他們被允許或有資格得到的事物。"},{"en":"A school handbook explains students’ duties and rights, such as attending class and receiving fair treatment.","zh":"學生手冊解釋學生的職責和權利，例如上課和獲得公平對待。"},{"en":"Clear duties and rights help workers know both their responsibilities and protections.","zh":"清晰的職責和權利幫助員工知道自己的責任和保障。"},{"en":"When duties and rights are unclear, conflicts between staff and managers become more likely.","zh":"當職責和權利不清晰時，員工與管理層之間更容易出現衝突。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":4},{"front":"relations among members","meaning":"成員之間的關係","examples":[{"en":"Relations among members of the organisation are impersonal.","zh":"組織成員之間的關係是非個人化的。"},{"en":"Relations among members means the way people inside a group or organisation interact with one another.","zh":"成員之間的關係是指團體或組織內部的人如何彼此互動。"},{"en":"In a sports team, relations among members affect trust, communication, and performance.","zh":"在運動隊中，成員之間的關係會影響信任、溝通和表現。"},{"en":"Good relations among members can make a workplace more cooperative.","zh":"良好的成員之間的關係可以令工作場所更合作。"},{"en":"In bureaucracy, relations among members are often based on roles rather than personal friendship.","zh":"在官僚制度中，成員之間的關係通常基於角色，而非私人友誼。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":4},{"front":"impersonal","meaning":"非個人化的","examples":[{"en":"Bureaucratic relations are impersonal.","zh":"官僚關係是非個人化的。"},{"en":"Impersonal means not based on personal feelings, friendship, or individual preference.","zh":"非個人化的意思是不基於個人感情、友誼或個人偏好。"},{"en":"A bank may use an impersonal process so every loan application is judged by the same rules.","zh":"銀行可能使用非個人化的程序，讓每宗貸款申請都按相同規則判斷。"},{"en":"Impersonal treatment can feel cold, but it may also prevent unfair favouritism.","zh":"非個人化的對待可能感覺冷淡，但也可能防止不公平偏袒。"},{"en":"In formal organisations, decisions are often impersonal because they depend on position and procedure.","zh":"在正式組織中，決定通常是非個人化的，因為它們取決於職位和程序。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":4},{"front":"be based on positions rather than personalities","meaning":"以職位而非個人性格為基礎","examples":[{"en":"Relations are based on positions rather than personalities.","zh":"關係以職位而非個人性格為基礎。"},{"en":"If relations are based on positions rather than personalities, people interact according to official roles, not personal likes or dislikes.","zh":"如果關係以職位而非個人性格為基礎，人們會按正式角色互動，而非按個人喜惡。"},{"en":"A manager approves leave based on positions rather than personalities when the same rules apply to every employee.","zh":"當同一規則適用於每位員工時，經理批准假期就是以職位而非個人性格為基礎。"},{"en":"This approach can reduce favouritism because decisions do not depend on friendship.","zh":"這種做法可以減少偏袒，因為決定不取決於友誼。"},{"en":"However, relations based on positions rather than personalities may feel distant and less human.","zh":"然而，以職位而非個人性格為基礎的關係可能感覺疏離和不夠人性化。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":4},{"front":"be very rigid","meaning":"非常僵化","examples":[{"en":"A bureaucratic organisation is very rigid.","zh":"官僚式組織非常僵化。"},{"en":"To be very rigid means to be strict, fixed, and difficult to change.","zh":"非常僵化是指嚴格、固定和難以改變。"},{"en":"A school timetable is very rigid if students cannot choose any subjects or activities.","zh":"如果學生不能選擇任何科目或活動，學校時間表就是非常僵化。"},{"en":"A very rigid system may work well in stable situations but poorly during sudden change.","zh":"非常僵化的制度在穩定情況下可能運作良好，但在突然變化時表現較差。"},{"en":"Rules become a problem when they are very rigid and leave no room for judgement.","zh":"當規則非常僵化且不留判斷空間時，它們就會成為問題。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":4},{"front":"place too much emphasis on","meaning":"過分強調","examples":[{"en":"Bureaucracy places too much emphasis on rules and regulations.","zh":"官僚制度過分強調規則和規例。"},{"en":"To place too much emphasis on something means to give it more attention or importance than it deserves.","zh":"過分強調某事，是指給予它超過應有的注意或重要性。"},{"en":"Some schools place too much emphasis on exam scores and forget creativity.","zh":"有些學校過分強調考試分數，而忘記創意。"},{"en":"A company may place too much emphasis on speed, causing workers to make mistakes.","zh":"公司可能過分強調速度，導致員工犯錯。"},{"en":"Management becomes unbalanced when it places too much emphasis on rules and ignores people.","zh":"當管理過分強調規則而忽略人時，就會變得失衡。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":4},{"front":"inflexible rules and regulations","meaning":"缺乏彈性的規則和規例","examples":[{"en":"Bureaucracy relies on inflexible rules and regulations.","zh":"官僚制度依賴缺乏彈性的規則和規例。"},{"en":"Inflexible rules and regulations are rules that cannot easily be adjusted to fit special situations.","zh":"缺乏彈性的規則和規例是指不能輕易因特殊情況而調整的規則。"},{"en":"A refund policy with inflexible rules and regulations may reject a fair request because it misses the deadline by one day.","zh":"有缺乏彈性規則和規例的退款政策，可能因申請遲了一天而拒絕一個合理要求。"},{"en":"Inflexible rules and regulations can protect fairness, but they can also create frustration.","zh":"缺乏彈性的規則和規例可以保護公平，但也可能造成挫折。"},{"en":"Public organisations need rules, but overly inflexible rules and regulations can delay useful action.","zh":"公共組織需要規則，但過度缺乏彈性的規則和規例可能延誤有用行動。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":4},{"front":"give little importance to","meaning":"不太重視","examples":[{"en":"Bureaucracy gives little importance to human relations.","zh":"官僚制度不太重視人際關係。"},{"en":"To give little importance to something means to treat it as not very important.","zh":"不太重視某事，是指把它視為不太重要。"},{"en":"A school gives little importance to mental health if it only cares about grades.","zh":"如果學校只關心成績，就是不太重視心理健康。"},{"en":"Companies that give little importance to staff feedback may lose good employees.","zh":"不太重視員工意見的公司可能失去優秀員工。"},{"en":"A system can become cold when it gives little importance to people’s feelings and relationships.","zh":"當制度不太重視人的感受和關係時，它可能變得冷漠。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":5},{"front":"human relations","meaning":"人際關係","examples":[{"en":"Bureaucracy gives little importance to human relations.","zh":"官僚制度不太重視人際關係。"},{"en":"Human relations are the personal and social relationships between people in a group or workplace.","zh":"人際關係是指團體或工作場所中人與人之間的個人和社交關係。"},{"en":"Good human relations help colleagues trust one another and solve problems calmly.","zh":"良好的人際關係幫助同事互相信任並冷靜解決問題。"},{"en":"Poor human relations can lead to conflict, low morale, and weak teamwork.","zh":"差劣的人際關係可能導致衝突、士氣低落和團隊合作薄弱。"},{"en":"Managers need to understand human relations, not just rules and procedures.","zh":"管理者需要理解人際關係，而不只是規則和程序。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":5},{"front":"informal groups","meaning":"非正式群體","examples":[{"en":"Informal groups now play an important role in business organisations.","zh":"非正式群體現在在商業組織中扮演重要角色。"},{"en":"Informal groups are unofficial groups formed through friendship, shared interests, or daily contact.","zh":"非正式群體是透過友誼、共同興趣或日常接觸形成的非官方群體。"},{"en":"Employees who eat lunch together may become an informal group that shares useful workplace news.","zh":"一起吃午餐的員工可能成為分享有用職場消息的非正式群體。"},{"en":"Informal groups can improve support, but they may also spread rumours if communication is poor.","zh":"非正式群體可以改善支援，但如果溝通欠佳，也可能散播謠言。"},{"en":"Managers should understand informal groups because not all influence comes from official positions.","zh":"管理者應理解非正式群體，因為並非所有影響力都來自正式職位。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":5},{"front":"play an important role in","meaning":"在……中扮演重要角色","examples":[{"en":"Informal groups play an important role in business organisations.","zh":"非正式群體在商業組織中扮演重要角色。"},{"en":"To play an important role in something means to have a strong influence on how it works or develops.","zh":"在某事中扮演重要角色，是指對它的運作或發展有很大影響。"},{"en":"Parents play an important role in children’s reading habits.","zh":"父母在孩子的閱讀習慣中扮演重要角色。"},{"en":"Public transport plays an important role in reducing traffic and pollution.","zh":"公共交通在減少交通擠塞和污染中扮演重要角色。"},{"en":"Clear communication plays an important role in keeping teams organised.","zh":"清晰溝通在保持團隊有組織方面扮演重要角色。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":5},{"front":"business organisations","meaning":"商業組織","examples":[{"en":"Informal groups are important in business organisations.","zh":"非正式群體在商業組織中很重要。"},{"en":"Business organisations are companies or groups that produce, sell, or provide goods and services.","zh":"商業組織是生產、銷售或提供商品和服務的公司或團體。"},{"en":"Restaurants, banks, factories, and online shops are all business organisations.","zh":"餐廳、銀行、工廠和網店都是商業組織。"},{"en":"Business organisations need good management because workers, customers, and money must be coordinated.","zh":"商業組織需要良好管理，因為員工、顧客和資金都必須協調。"},{"en":"Some business organisations are small family firms, while others are large international companies.","zh":"有些商業組織是小型家族企業，另一些則是大型國際公司。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":5},{"front":"give too much weight to","meaning":"過分重視","examples":[{"en":"Bureaucracy gives too much weight to technical qualifications.","zh":"官僚制度過分重視技術資格。"},{"en":"To give too much weight to something means to treat it as more important than other relevant factors.","zh":"過分重視某事，是指把它看得比其他相關因素更重要。"},{"en":"A university gives too much weight to test scores if it ignores interviews and portfolios.","zh":"如果大學忽視面試和作品集，就是過分重視考試分數。"},{"en":"Employers may give too much weight to degrees and miss candidates with strong practical skills.","zh":"僱主可能過分重視學位，而錯過實務能力很強的應徵者。"},{"en":"Fair decisions consider many factors instead of giving too much weight to only one.","zh":"公平決定會考慮多個因素，而不是只過分重視一項。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":5},{"front":"technical qualifications","meaning":"技術資格","examples":[{"en":"Promotion decisions may focus too much on technical qualifications.","zh":"晉升決定可能過分集中於技術資格。"},{"en":"Technical qualifications are formal certificates or skills showing that a person can do specialised work.","zh":"技術資格是顯示一個人能做專門工作的正式證書或技能。"},{"en":"An engineer may need technical qualifications before designing bridges.","zh":"工程師在設計橋樑前可能需要技術資格。"},{"en":"Technical qualifications are important, but they do not always show teamwork or commitment.","zh":"技術資格很重要，但不一定顯示團隊合作或投入。"},{"en":"When hiring nurses, hospitals consider technical qualifications as well as care and communication.","zh":"醫院聘請護士時，會考慮技術資格，也會考慮關懷和溝通能力。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":5},{"front":"promotion and transfer decisions","meaning":"晉升和調職決定","examples":[{"en":"Technical qualifications influence promotion and transfer decisions.","zh":"技術資格影響晉升和調職決定。"},{"en":"Promotion and transfer decisions are choices about moving employees to higher roles or different positions.","zh":"晉升和調職決定是關於把員工調往更高職位或不同崗位的選擇。"},{"en":"Managers make promotion and transfer decisions after reviewing performance and workplace needs.","zh":"管理者會在審視表現和工作場所需要後作出晉升和調職決定。"},{"en":"Poor promotion and transfer decisions can reduce morale if employees feel the process is unfair.","zh":"如果員工覺得過程不公平，差劣的晉升和調職決定會降低士氣。"},{"en":"Good promotion and transfer decisions should consider ability, attitude, experience, and organisational needs.","zh":"良好的晉升和調職決定應考慮能力、態度、經驗和組織需要。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":5},{"front":"dedication and commitment","meaning":"奉獻精神和投入","examples":[{"en":"Bureaucracy may ignore employees’ dedication and commitment.","zh":"官僚制度可能忽略員工的奉獻精神和投入。"},{"en":"Dedication and commitment mean serious effort, loyalty, and willingness to keep working towards a goal.","zh":"奉獻精神和投入是指認真的努力、忠誠，以及持續朝目標工作的意願。"},{"en":"A volunteer shows dedication and commitment by helping every weekend for many years.","zh":"義工多年來每個週末幫忙，就是展現奉獻精神和投入。"},{"en":"Dedication and commitment can keep a team strong during difficult periods.","zh":"奉獻精神和投入可以在困難時期令團隊保持強大。"},{"en":"Qualifications are useful, but dedication and commitment also show whether a person can be trusted.","zh":"資格很有用，但奉獻精神和投入也顯示一個人是否值得信任。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":5},{"front":"be not considered","meaning":"不被考慮","examples":[{"en":"Employees’ dedication and commitment are not considered.","zh":"員工的奉獻精神和投入不被考慮。"},{"en":"If something is not considered, it is ignored or not included when a decision is made.","zh":"如果某事不被考慮，它在作決定時被忽略或沒有被納入。"},{"en":"A student’s family situation may not be considered if a school only looks at attendance numbers.","zh":"如果學校只看出席數字，學生的家庭情況可能不被考慮。"},{"en":"When workers’ ideas are not considered, they may feel unvalued.","zh":"當員工的想法不被考慮時，他們可能覺得不受重視。"},{"en":"Important factors should not be left unconsidered in serious decisions.","zh":"在重要決定中，重要因素不應被忽略而不被考慮。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":5},{"front":"be suitable for","meaning":"適合……","examples":[{"en":"Bureaucracy is suitable for government organisations.","zh":"官僚制度適合政府機構。"},{"en":"To be suitable for something means to fit its needs, purpose, or situation.","zh":"適合某事，是指符合它的需要、目的或情況。"},{"en":"Online lessons may be suitable for students who live far from school.","zh":"網上課程可能適合住得離學校很遠的學生。"},{"en":"A quiet room is suitable for studying because it has fewer distractions.","zh":"安靜房間適合溫習，因為干擾較少。"},{"en":"A method suitable for a small team may not be suitable for a large department.","zh":"適合小團隊的方法，未必適合大型部門。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":5},{"front":"government organisations","meaning":"政府機構","examples":[{"en":"Bureaucracy is often suitable for government organisations.","zh":"官僚制度通常適合政府機構。"},{"en":"Government organisations are public bodies that carry out official duties and provide public services.","zh":"政府機構是履行官方職責和提供公共服務的公共機構。"},{"en":"Tax offices, public hospitals, and immigration departments are government organisations.","zh":"稅務局、公立醫院和入境部門都是政府機構。"},{"en":"Government organisations need clear rules because their decisions affect citizens’ rights and resources.","zh":"政府機構需要清晰規則，因為其決定影響市民的權利和資源。"},{"en":"People expect government organisations to be fair, accountable, and consistent.","zh":"人們期望政府機構公平、問責和一致。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":6},{"front":"static organisations","meaning":"靜態組織","examples":[{"en":"Bureaucracy suits static organisations in which change is slow.","zh":"官僚制度適合變化緩慢的靜態組織。"},{"en":"Static organisations are organisations that change slowly and operate in a stable environment.","zh":"靜態組織是變化緩慢並在穩定環境中運作的組織。"},{"en":"A records office may be a static organisation if its daily tasks rarely change.","zh":"如果檔案辦公室的日常任務很少改變，它可能是一個靜態組織。"},{"en":"Static organisations can benefit from fixed procedures because the same work is repeated often.","zh":"靜態組織可以受惠於固定程序，因為相同工作經常重複。"},{"en":"Bureaucracy fits static organisations better than organisations facing constant market change.","zh":"官僚制度比起面對持續市場變化的組織，更適合靜態組織。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":6},{"front":"change is very slow","meaning":"變化非常緩慢","examples":[{"en":"Bureaucracy works best where change is very slow.","zh":"在變化非常緩慢的地方，官僚制度運作得最好。"},{"en":"If change is very slow, the situation stays almost the same for a long time.","zh":"如果變化非常緩慢，情況會長時間幾乎保持不變。"},{"en":"A filing system may work well for years if change is very slow in the office.","zh":"如果辦公室變化非常緩慢，一套檔案系統可能多年都運作良好。"},{"en":"When change is very slow, fixed rules are less likely to become outdated quickly.","zh":"當變化非常緩慢時，固定規則較不容易很快過時。"},{"en":"If change is very slow, stability may matter more than creativity.","zh":"如果變化非常緩慢，穩定可能比創意更重要。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":6},{"front":"unnecessary delays","meaning":"不必要的延誤","examples":[{"en":"Formalities and rules can cause unnecessary delays.","zh":"手續和規則可能造成不必要的延誤。"},{"en":"Unnecessary delays are delays that waste time and could have been avoided.","zh":"不必要的延誤是浪費時間且本可避免的延誤。"},{"en":"A patient may suffer unnecessary delays if every hospital form must be approved by several offices.","zh":"如果每張醫院表格都必須經幾個辦公室批准，病人可能遭遇不必要的延誤。"},{"en":"Unnecessary delays can frustrate citizens and reduce trust in public services.","zh":"不必要的延誤會令市民感到挫折，並降低對公共服務的信任。"},{"en":"Clearer procedures help organisations avoid unnecessary delays.","zh":"更清晰的程序幫助組織避免不必要的延誤。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":6},{"front":"decision-making","meaning":"決策","examples":[{"en":"Formalities can delay decision-making.","zh":"手續可能延誤決策。"},{"en":"Decision-making is the process of choosing what to do after considering information and options.","zh":"決策是在考慮資料和選項後選擇要做甚麼的過程。"},{"en":"A family uses decision-making when choosing where to live or which school to attend.","zh":"家庭選擇住在哪裡或讀哪間學校時，就是在進行決策。"},{"en":"Good decision-making depends on clear information, enough time, and sensible judgement.","zh":"良好決策取決於清晰資料、足夠時間和合理判斷。"},{"en":"Too many approval steps can slow decision-making in an organisation.","zh":"太多審批步驟可能拖慢組織中的決策。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":6},{"front":"coordination and communication","meaning":"協調和溝通","examples":[{"en":"Coordination and communication can be difficult in bureaucracies.","zh":"在官僚制度中，協調和溝通可能很困難。"},{"en":"Coordination and communication mean organising people’s actions and sharing information clearly.","zh":"協調和溝通是指組織人們的行動並清楚分享資訊。"},{"en":"A school trip needs coordination and communication among teachers, parents, and bus drivers.","zh":"學校旅行需要老師、家長和巴士司機之間的協調和溝通。"},{"en":"Poor coordination and communication can cause repeated work, missed deadlines, and confusion.","zh":"差劣的協調和溝通可能導致重複工作、錯過期限和混亂。"},{"en":"Large organisations need strong coordination and communication because many departments depend on one another.","zh":"大型組織需要強大的協調和溝通，因為許多部門互相依賴。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":6},{"front":"public administrators","meaning":"公共行政學者；公共行政人員","examples":[{"en":"Simon, Barnard and Lindblom were early American public administrators.","zh":"西蒙、巴納德和林德布洛姆是早期美國公共行政學者。"},{"en":"Public administrators are people who manage public organisations, policies, or government programmes.","zh":"公共行政人員是管理公共組織、政策或政府計劃的人。"},{"en":"A public administrator may organise housing support, hospital services, or transport planning.","zh":"公共行政人員可能組織房屋支援、醫院服務或交通規劃。"},{"en":"Public administrators need evidence because their decisions affect public resources and citizens’ lives.","zh":"公共行政人員需要證據，因為他們的決定影響公共資源和市民生活。"},{"en":"Good public administrators balance rules, fairness, efficiency, and human needs.","zh":"優秀的公共行政人員會平衡規則、公平、效率和人的需要。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":6},{"front":"usher in an era","meaning":"開創一個時代","examples":[{"en":"These scholars ushered in an era of recognition for public administration.","zh":"這些學者為公共行政開創了一個獲得承認的時代。"},{"en":"To usher in an era means to help begin a new period with different ideas or conditions.","zh":"開創一個時代是指幫助開始一個有不同思想或條件的新時期。"},{"en":"The internet ushered in an era of instant communication.","zh":"互聯網開創了一個即時溝通的時代。"},{"en":"New medical discoveries can usher in an era of better treatment for patients.","zh":"新醫學發現可以開創一個讓病人得到更好治療的時代。"},{"en":"Important thinkers can usher in an era when people start viewing a subject differently.","zh":"重要思想家可以開創一個人們以不同方式看待某學科的時代。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":6},{"front":"gain recognition as","meaning":"獲承認為……","examples":[{"en":"The field gained recognition as independent and unique.","zh":"該領域獲承認為獨立而獨特。"},{"en":"To gain recognition as something means to become accepted or respected in that identity or role.","zh":"獲承認為某身分或角色，是指在該身分或角色上變得被接受或受尊重。"},{"en":"A small college may gain recognition as a serious research centre after publishing strong studies.","zh":"小型學院在發表高質研究後，可能獲承認為嚴肅的研究中心。"},{"en":"A city can gain recognition as a cultural centre when artists and visitors gather there.","zh":"當藝術家和訪客聚集於某城市時，它可以獲承認為文化中心。"},{"en":"A new subject gains recognition as important when people see its practical value.","zh":"當人們看見其實用價值時，一門新學科會獲承認為重要。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":6},{"front":"independent and unique","meaning":"獨立而獨特","examples":[{"en":"Public administration became recognised as independent and unique.","zh":"公共行政獲承認為獨立而獨特。"},{"en":"Independent and unique means separate from others and having its own special qualities.","zh":"獨立而獨特是指與其他事物分開，並有自己的特殊品質。"},{"en":"A local café can feel independent and unique if it has its own recipes and atmosphere.","zh":"如果本地咖啡店有自己的食譜和氛圍，它會感覺獨立而獨特。"},{"en":"A subject becomes independent and unique when it develops its own questions, methods, and ideas.","zh":"當一門學科發展出自己的問題、方法和思想時，它就變得獨立而獨特。"},{"en":"Public administration is independent and unique because it deals with public values, resources, and responsibility.","zh":"公共行政獨立而獨特，因為它處理公共價值、資源和責任。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":6},{"front":"multidisciplinary nature","meaning":"跨學科性質","examples":[{"en":"The field gained recognition despite its multidisciplinary nature.","zh":"儘管具有跨學科性質，該領域仍獲得承認。"},{"en":"Multidisciplinary nature means involving knowledge, methods, or ideas from several different subjects.","zh":"跨學科性質是指涉及幾個不同學科的知識、方法或思想。"},{"en":"Public health has a multidisciplinary nature because it uses medicine, sociology, economics, and education.","zh":"公共健康具有跨學科性質，因為它使用醫學、社會學、經濟學和教育學。"},{"en":"A project with a multidisciplinary nature may need experts who speak very different professional languages.","zh":"具有跨學科性質的項目可能需要使用非常不同專業語言的專家。"},{"en":"The multidisciplinary nature of public administration can make it rich, but also harder to define.","zh":"公共行政的跨學科性質可以令它內容豐富，但也更難界定。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":6},{"front":"distinguish…from…","meaning":"將……與……區分開來","examples":[{"en":"Simon distinguished decisions based on facts from those based on values.","zh":"西蒙將基於事實的決定與基於價值觀的決定區分開來。"},{"en":"To distinguish one thing from another means to show the difference between them.","zh":"將一事物與另一事物區分開來，是指顯示它們之間的差異。"},{"en":"Students must distinguish facts from opinions when reading news articles.","zh":"學生閱讀新聞文章時，必須將事實與意見區分開來。"},{"en":"Doctors distinguish a minor cold from a serious infection by checking symptoms carefully.","zh":"醫生透過仔細檢查症狀，將輕微感冒與嚴重感染區分開來。"},{"en":"Good writing distinguishes the main argument from supporting details.","zh":"好文章會將主要論點與支持細節區分開來。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":7},{"front":"based on facts","meaning":"以事實為基礎","examples":[{"en":"Some management decisions are based on facts.","zh":"有些管理決定以事實為基礎。"},{"en":"If a decision is based on facts, it uses real evidence rather than guesses or feelings.","zh":"如果一個決定以事實為基礎，它使用真實證據，而不是猜測或感覺。"},{"en":"A doctor’s advice should be based on facts from tests and symptoms.","zh":"醫生的建議應以檢查和症狀得出的事實為基礎。"},{"en":"Decisions based on facts are easier to explain because they can be supported by evidence.","zh":"以事實為基礎的決定較容易解釋，因為它們有證據支持。"},{"en":"Public spending should be based on facts, not only political pressure.","zh":"公共開支應以事實為基礎，而不只是政治壓力。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":7},{"front":"based on values","meaning":"以價值觀為基礎","examples":[{"en":"Some public decisions are based on values.","zh":"有些公共決定以價值觀為基礎。"},{"en":"If a decision is based on values, it reflects beliefs about what is right, fair, or important.","zh":"如果一個決定以價值觀為基礎，它反映關於何為正確、公平或重要的信念。"},{"en":"A school rule may be based on values such as respect, honesty, and responsibility.","zh":"學校規則可能以尊重、誠實和責任等價值觀為基礎。"},{"en":"Decisions based on values can guide society, but they should also consider facts.","zh":"以價值觀為基礎的決定可以引導社會，但也應考慮事實。"},{"en":"Public policy often combines choices based on values with evidence from research.","zh":"公共政策常把以價值觀為基礎的選擇與研究證據結合。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":7},{"front":"public resources","meaning":"公共資源","examples":[{"en":"Responsible decisions about public resources require factual support.","zh":"關於公共資源的負責任決定需要事實支持。"},{"en":"Public resources are money, land, services, or facilities that belong to or serve the public.","zh":"公共資源是屬於公眾或服務公眾的金錢、土地、服務或設施。"},{"en":"Parks, hospitals, schools, and tax revenue are examples of public resources.","zh":"公園、醫院、學校和稅收都是公共資源的例子。"},{"en":"Public resources must be managed carefully because many citizens depend on them.","zh":"公共資源必須被小心管理，因為許多市民依賴它們。"},{"en":"Wasting public resources can damage trust in government.","zh":"浪費公共資源會損害對政府的信任。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":7},{"front":"be based solely on","meaning":"純粹基於……","examples":[{"en":"Public decisions cannot be based solely on personal values.","zh":"公共決定不能純粹基於個人價值觀。"},{"en":"To be based solely on something means to depend only on that thing and nothing else.","zh":"純粹基於某事，是指只依靠該事物，而不依靠其他因素。"},{"en":"A hiring decision should not be based solely on one short interview.","zh":"招聘決定不應純粹基於一次短面試。"},{"en":"Medical treatment cannot be based solely on internet advice.","zh":"醫療治療不能純粹基於網上建議。"},{"en":"When decisions are based solely on feelings, important evidence may be ignored.","zh":"當決定純粹基於感覺時，重要證據可能被忽略。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":7},{"front":"personal values","meaning":"個人價值觀","examples":[{"en":"Administrators should not rely only on personal values.","zh":"行政人員不應只依靠個人價值觀。"},{"en":"Personal values are a person’s own beliefs about what is right, important, or acceptable.","zh":"個人價值觀是一個人自己對何為正確、重要或可接受的信念。"},{"en":"A manager’s personal values may influence how they treat workers.","zh":"經理的個人價值觀可能影響他如何對待員工。"},{"en":"Personal values can guide behaviour, but public decisions need wider evidence and fairness.","zh":"個人價值觀可以引導行為，但公共決定需要更廣泛的證據和公平性。"},{"en":"People may disagree because their personal values are different.","zh":"人們可能因個人價值觀不同而意見不合。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":7},{"front":"attempt to rely on","meaning":"嘗試依靠","examples":[{"en":"Administrators must attempt to rely on objectively determined facts.","zh":"行政人員必須嘗試依靠客觀釐定的事實。"},{"en":"To attempt to rely on something means to try to base your judgement or action on it.","zh":"嘗試依靠某事，是指試圖以它作為判斷或行動的基礎。"},{"en":"A student should attempt to rely on evidence when answering a history question.","zh":"學生回答歷史問題時應嘗試依靠證據。"},{"en":"Doctors attempt to rely on test results before choosing a treatment.","zh":"醫生在選擇治療方法前，會嘗試依靠檢查結果。"},{"en":"Public officials attempt to rely on facts so their decisions are less personal and more defensible.","zh":"公職人員嘗試依靠事實，使其決定較少個人化且更站得住腳。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":7},{"front":"objectively determined facts","meaning":"客觀釐定的事實","examples":[{"en":"Responsible decisions should rely on objectively determined facts.","zh":"負責任的決定應依靠客觀釐定的事實。"},{"en":"Objectively determined facts are facts found through evidence, measurement, or fair methods rather than personal opinion.","zh":"客觀釐定的事實是透過證據、量度或公平方法找出的事實，而非個人意見。"},{"en":"Exam results are more reliable when grades are based on objectively determined facts and clear criteria.","zh":"當成績以客觀釐定的事實和清晰準則為基礎時，考試結果更可靠。"},{"en":"Objectively determined facts can reduce arguments because people can check the evidence.","zh":"客觀釐定的事實可以減少爭論，因為人們可以檢查證據。"},{"en":"Policy decisions should use objectively determined facts whenever public money is involved.","zh":"只要涉及公共金錢，政策決定就應使用客觀釐定的事實。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":7},{"front":"economic man","meaning":"經濟人","examples":[{"en":"Simon argued that the strictly economic man is unrealistic.","zh":"西蒙主張嚴格意義上的經濟人是不切實際的。"},{"en":"Economic man is a model of a person who always makes fully rational choices to maximise personal benefit.","zh":"經濟人是一種人物模型，指總是作出完全理性選擇以最大化個人利益的人。"},{"en":"In real life, people are not always economic men because they lack time, information, or emotional control.","zh":"在現實生活中，人們不總是經濟人，因為他們缺乏時間、資訊或情緒控制。"},{"en":"The idea of economic man helps economists build models, but it simplifies human behaviour.","zh":"經濟人的概念幫助經濟學家建立模型，但它簡化了人類行為。"},{"en":"Simon criticised the economic man because real decision-makers often settle for good enough choices.","zh":"西蒙批評經濟人，因為真實決策者常接受足夠好的選擇。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":7},{"front":"maximise returns","meaning":"將回報最大化","examples":[{"en":"An economic man maximises returns with complete information.","zh":"經濟人在擁有完整資料下將回報最大化。"},{"en":"To maximise returns means to get the greatest possible benefit, profit, or result from a choice.","zh":"將回報最大化是指從選擇中取得最大可能利益、利潤或結果。"},{"en":"An investor tries to maximise returns by choosing assets carefully.","zh":"投資者透過謹慎選擇資產來嘗試將回報最大化。"},{"en":"A student may maximise returns from study time by focusing on weak areas first.","zh":"學生可以先集中處理弱項，從而將溫習時間的回報最大化。"},{"en":"In public service, maximising returns should not mean ignoring fairness or human needs.","zh":"在公共服務中，將回報最大化不應意味著忽視公平或人的需要。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":7},{"front":"complete information","meaning":"完整資料","examples":[{"en":"The economic man makes decisions with complete information.","zh":"經濟人在擁有完整資料下作決定。"},{"en":"Complete information means having all the facts needed to make a fully informed decision.","zh":"完整資料是指擁有作出充分知情決定所需的所有事實。"},{"en":"A buyer rarely has complete information about every product before choosing one.","zh":"買家在選擇產品前，很少擁有關於每件產品的完整資料。"},{"en":"Without complete information, decision-makers may choose an option that is only satisfactory.","zh":"沒有完整資料時，決策者可能只選擇一個令人滿意的選項。"},{"en":"Complete information is useful, but collecting it can take too much time and money.","zh":"完整資料很有用，但收集它可能花費太多時間和金錢。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":7},{"front":"unlimited time","meaning":"無限時間","examples":[{"en":"The economic man is assumed to have unlimited time.","zh":"經濟人被假定擁有無限時間。"},{"en":"Unlimited time means as much time as needed, without any deadline or pressure.","zh":"無限時間是指有所需的一切時間，沒有期限或壓力。"},{"en":"Students do not have unlimited time in an exam, so they must manage each question carefully.","zh":"學生在考試中沒有無限時間，所以必須小心管理每道題目。"},{"en":"Real managers rarely have unlimited time before making urgent decisions.","zh":"真實經理在作出緊急決定前，很少擁有無限時間。"},{"en":"Because people lack unlimited time, they often choose a good enough solution.","zh":"因為人們沒有無限時間，他們常選擇足夠好的解決方案。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":8},{"front":"be unrealistic","meaning":"不切實際","examples":[{"en":"Simon believed that the idea of a strictly economic man is unrealistic.","zh":"西蒙認為嚴格經濟人的概念是不切實際的。"},{"en":"To be unrealistic means not to match real life or what is actually possible.","zh":"不切實際是指不符合現實生活或實際可能性。"},{"en":"It is unrealistic to expect beginners to speak perfectly after one lesson.","zh":"期望初學者上一堂課後說得完美，是不切實際的。"},{"en":"A budget is unrealistic if it ignores rent, transport, and food costs.","zh":"如果預算忽略租金、交通和食物成本，它就是不切實際的。"},{"en":"Management theories become unrealistic when they assume people never make mistakes.","zh":"當管理理論假設人從不犯錯時，它們就變得不切實際。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":8},{"front":"use enough information","meaning":"使用足夠資料","examples":[{"en":"Public administrators use enough information to make decisions.","zh":"公共行政人員使用足夠資料來作決定。"},{"en":"To use enough information means to collect sufficient facts for a reasonable decision, even if the information is not perfect.","zh":"使用足夠資料是指收集足夠事實來作出合理決定，即使資料並不完美。"},{"en":"A doctor uses enough information from symptoms and tests before giving advice.","zh":"醫生在給予建議前，會使用來自症狀和檢查的足夠資料。"},{"en":"Managers use enough information when they compare costs, risks, and staff opinions before acting.","zh":"管理者在行動前比較成本、風險和員工意見，就是使用足夠資料。"},{"en":"People often use enough information because waiting for perfect information would take too long.","zh":"人們常使用足夠資料，因為等待完美資料會花太長時間。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":8},{"front":"satisfactory decision","meaning":"令人滿意的決定","examples":[{"en":"Administrators often make a satisfactory decision rather than an optimal one.","zh":"行政人員常作出令人滿意的決定，而不是最佳決定。"},{"en":"A satisfactory decision is good enough to meet the main need, even if it is not the best possible choice.","zh":"令人滿意的決定是指足以滿足主要需要的決定，即使它不是最佳可能選擇。"},{"en":"A family may make a satisfactory decision about dinner by choosing a nearby restaurant everyone accepts.","zh":"一家人可能選擇大家都接受的附近餐廳，作出關於晚餐的令人滿意的決定。"},{"en":"A satisfactory decision saves time when the perfect answer is too costly to find.","zh":"當尋找完美答案成本太高時，令人滿意的決定可以節省時間。"},{"en":"In public administration, a satisfactory decision may be more realistic than a perfect one.","zh":"在公共行政中，令人滿意的決定可能比完美決定更現實。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":8},{"front":"satisfice","meaning":"滿意化；作出足夠滿意的選擇","examples":[{"en":"Simon argued that administrators often satisfice rather than maximise.","zh":"西蒙主張行政人員常作出足夠滿意的選擇，而不是追求最大化。"},{"en":"To satisfice means to choose an option that is good enough instead of searching for the best possible one.","zh":"滿意化是指選擇一個足夠好的選項，而不是尋找最佳可能選項。"},{"en":"A busy shopper may satisfice by buying the first jacket that fits and is affordable.","zh":"忙碌的購物者可能買下第一件合身且負擔得起的外套，作出足夠滿意的選擇。"},{"en":"People satisfice when more searching would cost too much time or effort.","zh":"當繼續搜尋會花太多時間或精力時，人們會滿意化。"},{"en":"Satisficing is common in real decision-making because perfect information is rarely available.","zh":"滿意化在真實決策中很常見，因為完美資料很少存在。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":8},{"front":"decision-makers","meaning":"決策者","examples":[{"en":"Decision-makers face uncertainty about the future.","zh":"決策者面對關於未來的不確定性。"},{"en":"Decision-makers are people who choose what action an organisation, group, or government should take.","zh":"決策者是選擇組織、團體或政府應採取甚麼行動的人。"},{"en":"School principals are decision-makers when they decide how to use limited classroom space.","zh":"校長在決定如何使用有限課室空間時，就是決策者。"},{"en":"Decision-makers need reliable information because their choices can affect many people.","zh":"決策者需要可靠資料，因為他們的選擇可能影響許多人。"},{"en":"Good decision-makers listen to evidence, but they also understand values and consequences.","zh":"優秀決策者會聆聽證據，也理解價值觀和後果。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":8},{"front":"face uncertainty","meaning":"面對不確定性","examples":[{"en":"Decision-makers face uncertainty about the future.","zh":"決策者面對關於未來的不確定性。"},{"en":"To face uncertainty means to deal with a situation where the result is not clear or predictable.","zh":"面對不確定性是指處理結果不清楚或不可預測的情況。"},{"en":"Students face uncertainty when exam questions may cover many possible topics.","zh":"當考試題目可能涵蓋很多不同主題時，學生面對不確定性。"},{"en":"Businesses face uncertainty when customer demand changes suddenly.","zh":"當顧客需求突然改變時，企業面對不確定性。"},{"en":"People facing uncertainty often choose safer options or collect more information.","zh":"面對不確定性的人常選擇較安全的選項或收集更多資料。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":8},{"front":"acquire information","meaning":"取得資料","examples":[{"en":"Decision-makers face costs in acquiring information.","zh":"決策者在取得資料時面對成本。"},{"en":"To acquire information means to get or collect facts, data, or knowledge.","zh":"取得資料是指獲得或收集事實、數據或知識。"},{"en":"A student acquires information for a project by reading books and interviewing people.","zh":"學生透過閱讀書籍和訪問他人，為專題研習取得資料。"},{"en":"Companies spend money acquiring information about customers before launching new products.","zh":"公司在推出新產品前，會花錢取得關於顧客的資料。"},{"en":"Acquiring information can improve decisions, but it may take time and resources.","zh":"取得資料可以改善決定，但可能需要時間和資源。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":8},{"front":"in the present","meaning":"在當下","examples":[{"en":"Decision-makers face costs in acquiring information in the present.","zh":"決策者在當下取得資料時面對成本。"},{"en":"In the present means now, at the current time, rather than in the past or future.","zh":"在當下是指現在、目前，而不是過去或未來。"},{"en":"A family may save money in the present to prepare for future needs.","zh":"家庭可能在當下儲蓄，以準備未來需要。"},{"en":"Problems ignored in the present may become more serious later.","zh":"在當下被忽視的問題，日後可能變得更嚴重。"},{"en":"Decision-makers must act in the present even when future results are uncertain.","zh":"即使未來結果不確定，決策者也必須在當下行動。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":8},{"front":"limit someone’s ability to","meaning":"限制某人做……的能力","examples":[{"en":"These factors limit administrators’ ability to make fully rational decisions.","zh":"這些因素限制行政人員作出完全理性決定的能力。"},{"en":"To limit someone’s ability to do something means to reduce what they can do or how well they can do it.","zh":"限制某人做某事的能力，是指減少他們能做的事或做好的程度。"},{"en":"Lack of sleep can limit a student’s ability to concentrate.","zh":"睡眠不足會限制學生專注的能力。"},{"en":"Poor internet access limits people’s ability to study or work online.","zh":"網絡連接差會限制人們網上學習或工作的能力。"},{"en":"Incomplete information limits decision-makers’ ability to choose the best option.","zh":"資料不完整會限制決策者選擇最佳選項的能力。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":8},{"front":"fully rational decisions","meaning":"完全理性的決定","examples":[{"en":"Decision-makers cannot always make fully rational decisions.","zh":"決策者不能總是作出完全理性的決定。"},{"en":"Fully rational decisions are decisions made with complete information, clear logic, and no emotional or practical limits.","zh":"完全理性的決定是指在完整資料、清晰邏輯且沒有情緒或實際限制下作出的決定。"},{"en":"In real life, people rarely make fully rational decisions because time and information are limited.","zh":"在現實生活中，人們很少作出完全理性的決定，因為時間和資料有限。"},{"en":"A fully rational decision would compare all possible choices carefully before acting.","zh":"完全理性的決定會在行動前仔細比較所有可能選擇。"},{"en":"Simon argued that fully rational decisions are often impossible in public administration.","zh":"西蒙主張，在公共行政中，完全理性的決定往往是不可能的。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":8},{"front":"bounded rationality","meaning":"有限理性","examples":[{"en":"Public administrators possess only bounded rationality.","zh":"公共行政人員只擁有有限理性。"},{"en":"Bounded rationality means people try to make rational decisions, but their rationality is limited by time, information, and ability.","zh":"有限理性是指人們嘗試作出理性決定，但其理性受時間、資料和能力限制。"},{"en":"A shopper shows bounded rationality when they compare a few products instead of every product in the market.","zh":"購物者比較幾件產品，而不是市場上每件產品，就是表現出有限理性。"},{"en":"Bounded rationality explains why people often choose good enough solutions.","zh":"有限理解釋了為何人們常選擇足夠好的解決方案。"},{"en":"Public officials work under bounded rationality because they cannot know every future consequence.","zh":"公職人員在有限理性下工作，因為他們不可能知道每個未來後果。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":9},{"front":"choose an option","meaning":"選擇一個選項","examples":[{"en":"Administrators choose an option that is satisfactory.","zh":"行政人員選擇一個令人滿意的選項。"},{"en":"To choose an option means to select one possibility from several choices.","zh":"選擇一個選項是指從幾個選擇中選取一個可能性。"},{"en":"A student may choose an option on a multiple-choice question after eliminating wrong answers.","zh":"學生可能在刪去錯誤答案後，於多項選擇題中選擇一個選項。"},{"en":"Families choose an option for housing by comparing price, location, and space.","zh":"家庭透過比較價格、地點和空間，選擇一個住屋選項。"},{"en":"When time is limited, decision-makers may choose an option that is acceptable rather than perfect.","zh":"當時間有限時，決策者可能選擇一個可接受而非完美的選項。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":9},{"front":"may not be optimal","meaning":"未必是最佳的","examples":[{"en":"The chosen option may not be optimal.","zh":"被選擇的選項未必是最佳的。"},{"en":"If something may not be optimal, it may not be the best possible choice.","zh":"如果某事未必是最佳的，它可能不是最佳可能選擇。"},{"en":"Taking the first bus may not be optimal, but it can still get you there on time.","zh":"乘搭第一班巴士未必是最佳的，但仍可令你準時到達。"},{"en":"A cheap laptop may not be optimal for video editing, even if it is good for basic work.","zh":"便宜手提電腦未必最適合剪片，即使它適合基本工作。"},{"en":"In real decisions, people often accept solutions that may not be optimal but are good enough.","zh":"在真實決策中，人們常接受未必最佳但足夠好的解決方案。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":9},{"front":"rational behaviour","meaning":"理性行為","examples":[{"en":"In economics, rational behaviour means maximising utility.","zh":"在經濟學中，理性行為意味著將效用最大化。"},{"en":"Rational behaviour means making choices in a logical way to achieve one’s goals under limits.","zh":"理性行為是指在限制下以合乎邏輯的方式作選擇，以達成目標。"},{"en":"Saving money for rent before buying luxuries is rational behaviour.","zh":"在購買奢侈品前先為租金儲錢，是理性行為。"},{"en":"Rational behaviour can be affected by limited information, habits, and emotions.","zh":"理性行為可能受有限資料、習慣和情緒影響。"},{"en":"Economists study rational behaviour to understand how people choose between different options.","zh":"經濟學家研究理性行為，以理解人們如何在不同選項之間作選擇。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":9},{"front":"maximise utility","meaning":"將效用最大化","examples":[{"en":"Individuals maximise their utility under constraints.","zh":"個人在限制下將效用最大化。"},{"en":"To maximise utility means to get the greatest possible satisfaction or benefit from available choices.","zh":"將效用最大化是指從可用選擇中取得最大可能滿足或利益。"},{"en":"A student may maximise utility by choosing a course that is useful, interesting, and affordable.","zh":"學生可以選擇有用、有趣且負擔得起的課程，以將效用最大化。"},{"en":"Consumers try to maximise utility when they compare price, quality, and personal need.","zh":"消費者比較價格、質素和個人需要時，是在嘗試將效用最大化。"},{"en":"People cannot always maximise utility because their money, time, and information are limited.","zh":"人們不能總是將效用最大化，因為金錢、時間和資料都有限。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":9},{"front":"under the constraints they face","meaning":"在所面對的限制下","examples":[{"en":"People make choices under the constraints they face.","zh":"人們在所面對的限制下作選擇。"},{"en":"Under the constraints they face means within the limits created by their situation, such as money, time, rules, or resources.","zh":"在所面對的限制下，是指在由自身情況造成的限制之內，例如金錢、時間、規則或資源。"},{"en":"A family chooses a flat under the constraints they face, including rent and distance from work.","zh":"家庭在所面對的限制下選擇單位，包括租金和上班距離。"},{"en":"Students plan revision under the constraints they face when exams are close and time is short.","zh":"當考試臨近而時間很短，學生就在所面對的限制下計劃溫習。"},{"en":"Real decisions are made under the constraints people face, not in perfect conditions.","zh":"真實決定是在所面對的限制下作出的，而不是在完美條件下作出的。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":9},{"front":"budget constraints","meaning":"預算限制","examples":[{"en":"Budget constraints limit rational choices.","zh":"預算限制限制理性選擇。"},{"en":"Budget constraints are limits caused by the amount of money available.","zh":"預算限制是由可用金額造成的限制。"},{"en":"A family faces budget constraints when choosing between a holiday and school fees.","zh":"家庭在假期和學費之間選擇時，會面對預算限制。"},{"en":"Budget constraints may force a hospital to buy fewer machines than it needs.","zh":"預算限制可能迫使醫院購買少於所需的機器。"},{"en":"Good planning helps organisations work within budget constraints without wasting money.","zh":"良好規劃幫助組織在預算限制內工作而不浪費金錢。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":9},{"front":"limited choices","meaning":"有限選擇","examples":[{"en":"Limited choices affect decision-making.","zh":"有限選擇影響決策。"},{"en":"Limited choices means having only a small number of possible options.","zh":"有限選擇是指只有少量可能選項。"},{"en":"A student in a small town may have limited choices of schools or courses.","zh":"小鎮學生可能在學校或課程方面只有有限選擇。"},{"en":"Limited choices can make people accept an option that is not ideal.","zh":"有限選擇可能令人接受一個不理想的選項。"},{"en":"When choices are limited, the best decision may simply be the least harmful one.","zh":"當選擇有限時，最佳決定可能只是傷害最少的決定。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":9},{"front":"in pursuit of","meaning":"為追求……","examples":[{"en":"People act in pursuit of their self-interest.","zh":"人們為追求自身利益而行動。"},{"en":"In pursuit of something means trying to achieve, obtain, or follow it.","zh":"為追求某事，是指嘗試達成、獲得或跟隨它。"},{"en":"Students may study late in pursuit of better exam results.","zh":"學生可能為追求更好考試成績而讀書到很晚。"},{"en":"A company may open new branches in pursuit of higher profits.","zh":"公司可能為追求更高利潤而開設新分店。"},{"en":"In pursuit of success, people should not forget health, family, or fairness.","zh":"為追求成功，人們不應忘記健康、家庭或公平。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":9},{"front":"self-interest","meaning":"自身利益","examples":[{"en":"Rational behaviour is often linked to self-interest.","zh":"理性行為常與自身利益有關。"},{"en":"Self-interest means concern for one’s own benefit, safety, comfort, or success.","zh":"自身利益是指關心自己的利益、安全、舒適或成功。"},{"en":"A worker may change jobs out of self-interest if the new job pays better.","zh":"如果新工作薪金更好，員工可能出於自身利益而轉工。"},{"en":"Self-interest is not always selfish, because people must also protect their own needs.","zh":"自身利益不一定是自私，因為人們也必須保護自己的需要。"},{"en":"Public policy must consider self-interest because people often respond to personal incentives.","zh":"公共政策必須考慮自身利益，因為人們常對個人誘因作出反應。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":9},{"front":"watershed scholar","meaning":"具分水嶺意義的學者","examples":[{"en":"Chester Barnard was another watershed scholar.","zh":"切斯特・巴納德是另一位具分水嶺意義的學者。"},{"en":"A watershed scholar is a thinker whose work marks an important turning point in a field.","zh":"具分水嶺意義的學者，是指其著作標誌著某領域重要轉折點的思想家。"},{"en":"A watershed scholar may change how future students and researchers understand a subject.","zh":"具分水嶺意義的學者可能改變後來學生和研究者理解某學科的方式。"},{"en":"Barnard was a watershed scholar because he helped shift attention towards incentives and cooperation.","zh":"巴納德是具分水嶺意義的學者，因為他幫助把注意力轉向誘因和合作。"},{"en":"The ideas of a watershed scholar often remain important long after they are first published.","zh":"具分水嶺意義的學者的思想，常在首次出版後很久仍然重要。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":9},{"front":"The Economy of Incentives","meaning":"《誘因經濟》","examples":[{"en":"Barnard discussed incentives in The Economy of Incentives.","zh":"巴納德在《誘因經濟》中討論誘因。"},{"en":"The Economy of Incentives refers to Barnard’s discussion of how rewards and conditions influence participation in organisations.","zh":"《誘因經濟》指巴納德關於回報和條件如何影響個人參與組織的討論。"},{"en":"Students may study The Economy of Incentives to understand why employees stay in or leave organisations.","zh":"學生可能研究《誘因經濟》，以理解員工為何留在或離開組織。"},{"en":"The Economy of Incentives connects money, recognition, working conditions, and loyalty.","zh":"《誘因經濟》把金錢、認可、工作條件和忠誠連繫起來。"},{"en":"The title reminds readers that organisations depend on exchanges between individuals and the group.","zh":"這個標題提醒讀者，組織依賴個人與團體之間的交換。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":10},{"front":"attempt to explain","meaning":"嘗試解釋","examples":[{"en":"Barnard attempted to explain individual participation in organisations.","zh":"巴納德嘗試解釋個人在組織中的參與。"},{"en":"To attempt to explain something means to try to make it clear or understandable.","zh":"嘗試解釋某事，是指試圖令它變得清楚或可理解。"},{"en":"A teacher may attempt to explain grammar by using simple daily examples.","zh":"老師可能嘗試用簡單日常例子解釋文法。"},{"en":"Researchers attempt to explain social problems by studying evidence and causes.","zh":"研究人員透過研究證據和原因，嘗試解釋社會問題。"},{"en":"When an idea is complex, writers often attempt to explain it through examples and comparisons.","zh":"當概念複雜時，作者常透過例子和比較嘗試解釋它。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":10},{"front":"individual participation","meaning":"個人參與","examples":[{"en":"Barnard studied individual participation in an organisation.","zh":"巴納德研究個人在組織中的參與。"},{"en":"Individual participation means the involvement of each person in a group, activity, or organisation.","zh":"個人參與是指每個人在團體、活動或組織中的投入。"},{"en":"A club depends on individual participation because members must attend meetings and help with events.","zh":"社團依賴個人參與，因為會員必須出席會議並協助活動。"},{"en":"Individual participation increases when people feel their effort is recognised.","zh":"當人們覺得自己的努力獲得認可時，個人參與會增加。"},{"en":"Organisations need individual participation, not just formal rules, to stay active.","zh":"組織需要個人參與，而不只是正式規則，才能保持活力。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":10},{"front":"systems of exchange","meaning":"交換系統","examples":[{"en":"Barnard described organisations as systems of exchange.","zh":"巴納德把組織描述為交換系統。"},{"en":"Systems of exchange are arrangements in which people give something and receive something in return.","zh":"交換系統是指人們付出某些東西並取得回報的安排。"},{"en":"A workplace is a system of exchange because employees give labour and receive pay, support, or recognition.","zh":"工作場所是一個交換系統，因為員工付出勞動並獲得薪酬、支援或認可。"},{"en":"Systems of exchange fail when one side feels the reward is not worth the effort.","zh":"當其中一方覺得回報不值得付出時，交換系統就會失效。"},{"en":"Seeing organisations as systems of exchange helps explain why people stay loyal or leave.","zh":"把組織視為交換系統，有助解釋人們為何保持忠誠或離開。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":10},{"front":"lower-level employees","meaning":"較低層員工","examples":[{"en":"Lower-level employees must receive enough incentive to stay.","zh":"較低層員工必須獲得足夠誘因才會留下。"},{"en":"Lower-level employees are workers in less senior positions within an organisation.","zh":"較低層員工是組織中職位較低的工作人員。"},{"en":"Cashiers, junior clerks, and assistants may be lower-level employees.","zh":"收銀員、初級文員和助理可能是較低層員工。"},{"en":"Lower-level employees often understand daily problems because they deal directly with routine tasks.","zh":"較低層員工常理解日常問題，因為他們直接處理例行工作。"},{"en":"Organisations should listen to lower-level employees, not only senior managers.","zh":"組織應聆聽較低層員工，而不只是高級管理層。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":10},{"front":"receive enough incentive","meaning":"獲得足夠誘因","examples":[{"en":"Employees must receive enough incentive to remain with the organisation.","zh":"員工必須獲得足夠誘因才會留在組織內。"},{"en":"To receive enough incentive means to get sufficient rewards or reasons to continue doing something.","zh":"獲得足夠誘因是指得到足夠回報或理由去繼續做某事。"},{"en":"Students receive enough incentive to study when progress is recognised and goals feel reachable.","zh":"當進步獲得認可且目標感覺可達到時，學生會獲得足夠誘因去學習。"},{"en":"Workers may leave if they do not receive enough incentive in pay, respect, or growth.","zh":"如果員工在薪酬、尊重或成長方面沒有獲得足夠誘因，他們可能離開。"},{"en":"An organisation keeps people longer when they receive enough incentive to stay.","zh":"當人們獲得足夠誘因留下時，組織能更長久地留住他們。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":10},{"front":"remain with the organisation","meaning":"留在組織內","examples":[{"en":"Incentives help employees remain with the organisation.","zh":"誘因幫助員工留在組織內。"},{"en":"To remain with the organisation means to continue working for or belonging to the same organisation.","zh":"留在組織內是指繼續為同一組織工作或屬於同一組織。"},{"en":"Employees may remain with the organisation if they feel respected and fairly paid.","zh":"如果員工感到受尊重並獲公平薪酬，他們可能留在組織內。"},{"en":"People are less likely to remain with the organisation when promotion opportunities disappear.","zh":"當晉升機會消失時，人們較不可能留在組織內。"},{"en":"Good leadership helps talented staff remain with the organisation through difficult periods.","zh":"良好領導幫助有才能的員工在困難時期留在組織內。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":10},{"front":"labour and loyalty","meaning":"勞動力和忠誠","examples":[{"en":"Employees give their labour and loyalty to the organisation.","zh":"員工向組織付出勞動力和忠誠。"},{"en":"Labour and loyalty mean workers’ effort, time, skills, and continued support for an organisation.","zh":"勞動力和忠誠是指員工為組織付出的努力、時間、技能和持續支持。"},{"en":"A company receives labour and loyalty when staff work hard and stay through difficult months.","zh":"當員工努力工作並在困難月份留下時，公司就獲得勞動力和忠誠。"},{"en":"Labour and loyalty are stronger when employees feel fairly treated.","zh":"當員工覺得受到公平對待時，勞動力和忠誠會更強。"},{"en":"Organisations should not expect labour and loyalty without giving respect and reasonable rewards.","zh":"組織不應在不給予尊重和合理回報的情況下期待勞動力和忠誠。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":10},{"front":"higher-level employees","meaning":"較高層員工","examples":[{"en":"The organisation and higher-level employees must benefit from staff.","zh":"組織和較高層員工必須從員工身上受益。"},{"en":"Higher-level employees are staff in more senior positions with greater authority or responsibility.","zh":"較高層員工是職位較高、擁有較大權力或責任的員工。"},{"en":"Managers and directors are higher-level employees in many companies.","zh":"在許多公司中，經理和董事都是較高層員工。"},{"en":"Higher-level employees often make decisions that affect the work of junior staff.","zh":"較高層員工常作出影響初級員工工作的決定。"},{"en":"Good higher-level employees support lower-level staff rather than only giving orders.","zh":"優秀的較高層員工會支援較低層員工，而不只是發號施令。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":10},{"front":"derive sufficient benefit from","meaning":"從……獲得足夠利益","examples":[{"en":"The organisation must derive sufficient benefit from employees.","zh":"組織必須從員工身上獲得足夠利益。"},{"en":"To derive sufficient benefit from something means to gain enough value or advantage from it.","zh":"從某事物獲得足夠利益，是指從中取得足夠價值或好處。"},{"en":"A school must derive sufficient benefit from a new app before paying for it every year.","zh":"學校每年付費購買新應用程式前，必須從中獲得足夠利益。"},{"en":"Employers derive sufficient benefit from training when workers become more skilled and confident.","zh":"當員工變得更熟練和自信時，僱主就從培訓中獲得足夠利益。"},{"en":"If an organisation does not derive sufficient benefit from a programme, it may stop funding it.","zh":"如果組織沒有從某計劃中獲得足夠利益，它可能停止資助。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":10},{"front":"retain them","meaning":"挽留他們","examples":[{"en":"The organisation must benefit from employees in order to retain them.","zh":"組織必須從員工身上受益，才能挽留他們。"},{"en":"To retain them means to keep those people in the organisation instead of losing them.","zh":"挽留他們是指把那些人留在組織內，而不是失去他們。"},{"en":"A company may improve pay and training to retain talented workers.","zh":"公司可能改善薪酬和培訓，以挽留有才能的員工。"},{"en":"Schools retain good teachers when they provide support and fair workload.","zh":"學校提供支援和公平工作量時，能挽留好老師。"},{"en":"It is often cheaper to retain employees than to hire and train new ones.","zh":"挽留員工通常比招聘和培訓新人更便宜。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":10},{"front":"net attraction","meaning":"淨吸引力","examples":[{"en":"An organisation’s net attraction depends on rewards and working conditions.","zh":"組織的淨吸引力取決於回報和工作條件。"},{"en":"Net attraction means the overall pull that makes people want to join or stay after considering both benefits and costs.","zh":"淨吸引力是指在人們考慮利益和成本後，令他們想加入或留下的整體吸引力。"},{"en":"A job’s net attraction may be high if the pay is fair and the workplace is supportive.","zh":"如果薪酬公平且工作場所支援性強，一份工作的淨吸引力可能很高。"},{"en":"Long hours can reduce the net attraction of a job even when the salary is good.","zh":"即使薪金不錯，長工時也會降低工作的淨吸引力。"},{"en":"Organisations improve net attraction by offering respect, growth, and reasonable conditions.","zh":"組織透過提供尊重、成長和合理條件來提升淨吸引力。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":11},{"front":"be determined by","meaning":"由……決定","examples":[{"en":"Net attraction is determined by rewards and working conditions.","zh":"淨吸引力由回報和工作條件決定。"},{"en":"To be determined by something means to be decided or strongly influenced by it.","zh":"由某事物決定，是指由它決定或受到它強烈影響。"},{"en":"A student’s grade may be determined by exams, coursework, and participation.","zh":"學生的成績可能由考試、課業和參與度決定。"},{"en":"Travel time is often determined by traffic, distance, and transport options.","zh":"交通時間通常由交通狀況、距離和交通選項決定。"},{"en":"Job satisfaction is not determined by salary alone.","zh":"工作滿意度並非只由薪金決定。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":11},{"front":"material rewards","meaning":"物質回報","examples":[{"en":"Material rewards help attract employees to an organisation.","zh":"物質回報幫助吸引員工加入組織。"},{"en":"Material rewards are practical or financial benefits, such as money, gifts, housing, or bonuses.","zh":"物質回報是實際或金錢上的利益，例如金錢、禮物、住屋或獎金。"},{"en":"A company may offer material rewards like salary increases to keep experienced staff.","zh":"公司可能提供加薪等物質回報，以留住有經驗員工。"},{"en":"Material rewards can motivate people, but they may not satisfy emotional needs.","zh":"物質回報可以激勵人，但未必滿足情感需要。"},{"en":"Good incentive systems combine material rewards with respect and recognition.","zh":"良好的誘因制度會把物質回報與尊重和認可結合。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":11},{"front":"working conditions","meaning":"工作條件","examples":[{"en":"Working conditions affect an organisation’s attraction.","zh":"工作條件影響組織的吸引力。"},{"en":"Working conditions are the physical, social, and organisational circumstances in which people work.","zh":"工作條件是人們工作的實體、社交和組織環境。"},{"en":"Clean offices, safe equipment, fair hours, and supportive managers are good working conditions.","zh":"清潔辦公室、安全設備、公平工時和支持性經理都是良好工作條件。"},{"en":"Poor working conditions can push employees to leave even when wages are acceptable.","zh":"差劣工作條件即使在薪金可接受時，也可能推使員工離開。"},{"en":"Improving working conditions can raise morale and reduce staff turnover.","zh":"改善工作條件可以提升士氣並減少員工流失。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":11},{"front":"intangibles such as recognition","meaning":"例如認可等無形因素","examples":[{"en":"Intangibles such as recognition can motivate employees.","zh":"例如認可等無形因素可以激勵員工。"},{"en":"Intangibles such as recognition are non-material rewards that make people feel valued and respected.","zh":"例如認可等無形因素，是指令人在非物質層面感到被重視和尊重的回報。"},{"en":"A simple thank-you from a manager is an intangible such as recognition.","zh":"經理一句簡單的謝謝，就是例如認可等無形因素。"},{"en":"Intangibles such as recognition can be powerful because people want their effort to be noticed.","zh":"例如認可等無形因素可以很有力量，因為人們希望自己的努力被看見。"},{"en":"Money matters, but intangibles such as recognition often help employees feel connected to their work.","zh":"金錢很重要，但例如認可等無形因素常幫助員工感到與工作有連繫。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":11},{"front":"attach greater importance to","meaning":"更重視……","examples":[{"en":"Barnard attached greater importance to persuasion than to money.","zh":"巴納德更重視說服，而不是金錢。"},{"en":"To attach greater importance to something means to consider it more important than another thing.","zh":"更重視某事，是指認為它比另一事物更重要。"},{"en":"Some parents attach greater importance to character than to exam results.","zh":"有些父母更重視品格，而不是考試成績。"},{"en":"A company may attach greater importance to customer trust than to short-term profit.","zh":"公司可能更重視顧客信任，而不是短期利潤。"},{"en":"Barnard attached greater importance to persuasion because motivation is not only financial.","zh":"巴納德更重視說服，因為動機不只是金錢上的。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":11},{"front":"persuasion","meaning":"說服","examples":[{"en":"Barnard valued persuasion as an incentive.","zh":"巴納德重視說服作為一種誘因。"},{"en":"Persuasion is the act of encouraging someone to believe, agree, or act through reasons and communication.","zh":"說服是透過理由和溝通鼓勵某人相信、同意或行動。"},{"en":"A teacher uses persuasion when explaining why daily reading matters.","zh":"老師解釋為何每日閱讀重要時，就是在使用說服。"},{"en":"Persuasion can work better than force because people feel they have chosen freely.","zh":"說服可能比強迫更有效，因為人們覺得自己是自由選擇的。"},{"en":"In management, persuasion helps employees understand the purpose behind a decision.","zh":"在管理中，說服幫助員工理解決定背後的目的。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":11},{"front":"economic incentives","meaning":"經濟誘因","examples":[{"en":"Barnard did not rely only on economic incentives.","zh":"巴納德不只依賴經濟誘因。"},{"en":"Economic incentives are financial rewards or costs that influence people’s behaviour.","zh":"經濟誘因是影響人們行為的金錢回報或成本。"},{"en":"Bonuses and higher wages are common economic incentives at work.","zh":"獎金和較高工資是工作中常見的經濟誘因。"},{"en":"Economic incentives can encourage effort, but they may not create loyalty by themselves.","zh":"經濟誘因可以鼓勵努力，但它們本身未必創造忠誠。"},{"en":"A good policy may combine economic incentives with education and clear rules.","zh":"好政策可能把經濟誘因與教育和清晰規則結合。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":11},{"front":"general and specific incentives","meaning":"一般和特定誘因","examples":[{"en":"Barnard described both general and specific incentives.","zh":"巴納德描述了一般和特定誘因。"},{"en":"General and specific incentives are broad rewards and particular rewards that encourage people to participate.","zh":"一般和特定誘因是鼓勵人們參與的廣泛回報和特定回報。"},{"en":"A good work atmosphere is a general incentive, while a bonus for finishing a project is a specific incentive.","zh":"良好工作氣氛是一般誘因，而完成項目的獎金是特定誘因。"},{"en":"Organisations use general and specific incentives to meet different employee needs.","zh":"組織使用一般和特定誘因，以滿足不同員工需要。"},{"en":"General and specific incentives work best when they match what people actually value.","zh":"一般和特定誘因在符合人們真正重視的事物時，效果最好。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":11},{"front":"material inducements","meaning":"物質誘因","examples":[{"en":"Money can be one type of material inducement.","zh":"金錢可以是一種物質誘因。"},{"en":"Material inducements are physical or financial rewards offered to encourage action.","zh":"物質誘因是為鼓勵行動而提供的實體或金錢回報。"},{"en":"A company may use material inducements such as bonuses, travel allowances, or free meals.","zh":"公司可能使用獎金、交通津貼或免費膳食等物質誘因。"},{"en":"Material inducements can attract workers, but they may not build deep commitment alone.","zh":"物質誘因可以吸引員工，但單靠它們未必建立深層投入。"},{"en":"When wages are low, material inducements may become especially important.","zh":"當工資低時，物質誘因可能變得尤其重要。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":11},{"front":"non-material opportunities","meaning":"非物質機會","examples":[{"en":"Employees may value non-material opportunities for distinction.","zh":"員工可能重視脫穎而出的非物質機會。"},{"en":"Non-material opportunities are chances that do not involve money but give growth, respect, learning, or meaning.","zh":"非物質機會是不涉及金錢但提供成長、尊重、學習或意義的機會。"},{"en":"A worker may value non-material opportunities such as leading a project or learning a new skill.","zh":"員工可能重視領導項目或學習新技能等非物質機會。"},{"en":"Non-material opportunities can motivate employees who already earn enough to meet basic needs.","zh":"對已能滿足基本需要的員工而言，非物質機會可以激勵他們。"},{"en":"Organisations should offer non-material opportunities because people want more than pay.","zh":"組織應提供非物質機會，因為人們想要的不只是薪酬。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":11},{"front":"opportunities for distinction","meaning":"脫穎而出的機會","examples":[{"en":"Recognition can provide opportunities for distinction.","zh":"認可可以提供脫穎而出的機會。"},{"en":"Opportunities for distinction are chances to stand out, be noticed, or gain respect for good work.","zh":"脫穎而出的機會是指因良好表現而突顯自己、被注意或獲得尊重的機會。"},{"en":"A school competition gives students opportunities for distinction beyond normal homework.","zh":"學校比賽給學生在普通功課以外脫穎而出的機會。"},{"en":"Employees may work harder when they have opportunities for distinction through awards or leadership roles.","zh":"當員工透過獎項或領導角色擁有脫穎而出的機會時，他們可能更努力工作。"},{"en":"Opportunities for distinction can satisfy people’s need to feel valued.","zh":"脫穎而出的機會可以滿足人們感到被重視的需要。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":12},{"front":"desirable physical working conditions","meaning":"理想的實體工作環境","examples":[{"en":"Good workplaces offer desirable physical working conditions.","zh":"良好工作場所提供理想的實體工作環境。"},{"en":"Desirable physical working conditions are comfortable, safe, and healthy workplace surroundings.","zh":"理想的實體工作環境是舒適、安全和健康的工作場所環境。"},{"en":"Good lighting, clean air, safe tools, and enough space are desirable physical working conditions.","zh":"良好照明、清潔空氣、安全工具和足夠空間都是理想的實體工作環境。"},{"en":"Desirable physical working conditions reduce tiredness and help employees work better.","zh":"理想的實體工作環境減少疲勞，幫助員工更好地工作。"},{"en":"Poor factories may lose workers if they cannot provide desirable physical working conditions.","zh":"如果不能提供理想的實體工作環境，差劣工廠可能失去員工。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":12},{"front":"ideal benefactions","meaning":"理想性利益","examples":[{"en":"Barnard included ideal benefactions among incentives.","zh":"巴納德把理想性利益列入誘因之中。"},{"en":"Ideal benefactions are non-material benefits connected with ideals, pride, meaning, or moral satisfaction.","zh":"理想性利益是與理想、自豪、意義或道德滿足有關的非物質好處。"},{"en":"A charity worker may value ideal benefactions because the work feels meaningful.","zh":"慈善工作者可能重視理想性利益，因為工作感覺有意義。"},{"en":"Ideal benefactions can motivate people when they believe their work serves a higher purpose.","zh":"當人們相信自己的工作服務於更高目的時，理想性利益可以激勵他們。"},{"en":"Money may attract workers, but ideal benefactions can make work feel worthwhile.","zh":"金錢可能吸引員工，但理想性利益可以令工作感到值得。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":12},{"front":"pride in workmanship","meaning":"對工作成果的自豪感","examples":[{"en":"Pride in workmanship can motivate employees.","zh":"對工作成果的自豪感可以激勵員工。"},{"en":"Pride in workmanship means satisfaction from doing careful, skilled, and high-quality work.","zh":"對工作成果的自豪感是指因完成細心、有技術和高質素的工作而感到滿足。"},{"en":"A carpenter shows pride in workmanship when every corner of a table is finished neatly.","zh":"木匠把桌子的每個角都修整得整齊時，就是展現對工作成果的自豪感。"},{"en":"Pride in workmanship can make employees care about quality even when nobody is watching.","zh":"對工作成果的自豪感可以令員工即使沒有人觀看，也關心質素。"},{"en":"Organisations encourage pride in workmanship by recognising careful and honest work.","zh":"組織透過認可細心和誠實的工作，鼓勵對工作成果的自豪感。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":12},{"front":"humanist era","meaning":"人文主義時代","examples":[{"en":"The passage describes a new humanist era in management.","zh":"文章描述管理中的新人文主義時代。"},{"en":"A humanist era is a period when management begins to see workers as people with needs, emotions, and goals.","zh":"人文主義時代是管理開始把員工視為有需要、情感和目標的人之時期。"},{"en":"In a humanist era, managers care about motivation, cooperation, and personal development.","zh":"在人文主義時代，管理者關心動機、合作和個人發展。"},{"en":"The humanist era challenged older views that treated workers like machine parts.","zh":"人文主義時代挑戰了把員工視為機器部件的舊觀點。"},{"en":"A humanist era in management values both organisational results and human dignity.","zh":"管理中的人文主義時代同時重視組織成果和人的尊嚴。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":12},{"front":"rethink power and management","meaning":"重新思考權力和管理","examples":[{"en":"The humanist era involved rethinking power and management.","zh":"人文主義時代涉及重新思考權力和管理。"},{"en":"To rethink power and management means to examine old ideas about authority and leadership again.","zh":"重新思考權力和管理，是指再次審視關於權威和領導的舊觀念。"},{"en":"A company may rethink power and management after staff complain that decisions are too top-down.","zh":"當員工投訴決策過於自上而下時，公司可能重新思考權力和管理。"},{"en":"Rethinking power and management can lead to more participation and trust.","zh":"重新思考權力和管理可以帶來更多參與和信任。"},{"en":"Organisations rethink power and management when old control methods no longer motivate employees.","zh":"當舊有控制方法不再能激勵員工時，組織會重新思考權力和管理。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":12},{"front":"embrace a dynamic view of","meaning":"接納對……的動態觀點","examples":[{"en":"Humanists embrace a dynamic view of employees and management.","zh":"人文主義者接納對員工和管理的動態觀點。"},{"en":"To embrace a dynamic view of something means to accept that it changes, develops, and interacts with other factors.","zh":"接納對某事物的動態觀點，是指接受它會改變、發展並與其他因素互動。"},{"en":"Good teachers embrace a dynamic view of learning because students improve at different speeds.","zh":"好老師接納對學習的動態觀點，因為學生以不同速度進步。"},{"en":"Managers embrace a dynamic view of employees when they see them as growing people, not fixed tools.","zh":"當管理者把員工視為會成長的人，而非固定工具時，就是接納對員工的動態觀點。"},{"en":"A dynamic view of management allows organisations to adjust as needs change.","zh":"對管理的動態觀點讓組織能隨需要改變而調整。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":12},{"front":"management techniques","meaning":"管理技巧","examples":[{"en":"Humanists rethink employees and management techniques.","zh":"人文主義者重新思考員工和管理技巧。"},{"en":"Management techniques are methods used to organise, guide, motivate, and evaluate people at work.","zh":"管理技巧是用來組織、引導、激勵和評估工作中人員的方法。"},{"en":"Setting goals, giving feedback, and delegating tasks are common management techniques.","zh":"設定目標、提供回饋和委派任務都是常見管理技巧。"},{"en":"Management techniques should change when employees need more creativity and responsibility.","zh":"當員工需要更多創意和責任時，管理技巧應作改變。"},{"en":"Poor management techniques can make capable workers feel controlled and untrusted.","zh":"差劣管理技巧會令有能力的員工感到被控制和不被信任。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":12},{"front":"theoretical shift","meaning":"理論轉向","examples":[{"en":"The humanist approach requires a theoretical shift.","zh":"人文主義取向需要理論轉向。"},{"en":"A theoretical shift is a major change in the way people explain or understand a subject.","zh":"理論轉向是指人們解釋或理解某學科方式上的重大改變。"},{"en":"Moving from punishment to support in education is a theoretical shift in how teachers view students.","zh":"教育中從懲罰轉向支援，是老師看待學生方式上的理論轉向。"},{"en":"A theoretical shift often happens when old ideas cannot explain new problems.","zh":"當舊思想不能解釋新問題時，常會出現理論轉向。"},{"en":"The humanist era brought a theoretical shift from control to cooperation.","zh":"人文主義時代帶來從控制到合作的理論轉向。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":12},{"front":"shift away from","meaning":"從……轉向","examples":[{"en":"Humanists shift away from treating employees as machine parts.","zh":"人文主義者從把員工視為機器部件轉向其他看法。"},{"en":"To shift away from something means to move gradually from one idea, habit, or method to another.","zh":"從某事轉向，是指逐漸由一種思想、習慣或方法移向另一種。"},{"en":"Schools may shift away from memorisation and use more project-based learning.","zh":"學校可能從死記硬背轉向更多專題式學習。"},{"en":"Companies shift away from strict control when they want employees to be more creative.","zh":"當公司希望員工更有創意時，會從嚴格控制轉向其他管理方式。"},{"en":"A shift away from old habits can be difficult but necessary.","zh":"從舊習慣轉向可能困難，但有必要。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":12},{"front":"treat an employee as","meaning":"將員工視為……","examples":[{"en":"Old theories treated an employee as a cog in a machine.","zh":"舊理論將員工視為機器中的齒輪。"},{"en":"To treat an employee as something means to view or handle that worker in a particular way.","zh":"將員工視為某事物，是指以某種方式看待或處理該員工。"},{"en":"A bad manager may treat an employee as a replaceable tool rather than a person.","zh":"差劣經理可能將員工視為可替換工具，而不是人。"},{"en":"Good leaders treat an employee as someone with ideas, needs, and potential.","zh":"好領袖將員工視為有想法、需要和潛力的人。"},{"en":"How managers treat an employee affects motivation and loyalty.","zh":"管理者如何看待員工會影響動機和忠誠。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":12},{"front":"a cog in an industrial machine","meaning":"工業機器中的齒輪","examples":[{"en":"Humanists reject the idea of an employee as a cog in an industrial machine.","zh":"人文主義者拒絕把員工視為工業機器中的齒輪。"},{"en":"A cog in an industrial machine means a small replaceable part of a large system, with little personal value or freedom.","zh":"工業機器中的齒輪是指大型系統中可替換的小部件，幾乎沒有個人價值或自由。"},{"en":"Workers feel like cogs in an industrial machine when they repeat tasks without being heard.","zh":"當工人重複任務而沒有人聆聽時，他們會覺得自己像工業機器中的齒輪。"},{"en":"Treating people as cogs in an industrial machine can reduce creativity and morale.","zh":"把人視為工業機器中的齒輪，可能降低創意和士氣。"},{"en":"The humanist approach argues that employees are more than cogs in an industrial machine.","zh":"人文主義取向主張員工不只是工業機器中的齒輪。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":13},{"front":"unique individuals","meaning":"獨特個體","examples":[{"en":"Employees are unique individuals with their own goals.","zh":"員工是有自己目標的獨特個體。"},{"en":"Unique individuals are people with their own personalities, needs, experiences, and abilities.","zh":"獨特個體是指擁有自己性格、需要、經驗和能力的人。"},{"en":"Good teachers see students as unique individuals, not just exam scores.","zh":"好老師把學生視為獨特個體，而不只是考試分數。"},{"en":"Managers who respect employees as unique individuals can better understand what motivates them.","zh":"尊重員工為獨特個體的管理者，能更好理解甚麼能激勵他們。"},{"en":"Treating people as unique individuals helps create a more human workplace.","zh":"把人視為獨特個體有助創造更人性化的工作場所。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":13},{"front":"goals, needs and desires","meaning":"目標、需要和願望","examples":[{"en":"Employees have their own goals, needs and desires.","zh":"員工有自己的目標、需要和願望。"},{"en":"Goals, needs and desires are what people want to achieve, require, and hope for.","zh":"目標、需要和願望是人們想達成、需要和希望得到的事物。"},{"en":"A student’s goals, needs and desires may include passing exams, feeling confident, and choosing a career.","zh":"學生的目標、需要和願望可能包括通過考試、建立自信和選擇職業。"},{"en":"Managers understand workers better when they listen to their goals, needs and desires.","zh":"當管理者聆聽員工的目標、需要和願望時，會更理解他們。"},{"en":"Ignoring people’s goals, needs and desires can make an organisation feel cold and controlling.","zh":"忽略人的目標、需要和願望，可能令組織感覺冷漠和控制性強。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":13},{"front":"interpretations of power and management","meaning":"對權力和管理的新詮釋","examples":[{"en":"The humanist era brought new interpretations of power and management.","zh":"人文主義時代帶來對權力和管理的新詮釋。"},{"en":"Interpretations of power and management are ways of understanding how authority and leadership should work.","zh":"對權力和管理的新詮釋，是指理解權威和領導應如何運作的方式。"},{"en":"A strict manager may have different interpretations of power and management from a cooperative leader.","zh":"嚴格經理對權力和管理的詮釋，可能與合作型領袖不同。"},{"en":"New interpretations of power and management can change how employees are motivated and supervised.","zh":"對權力和管理的新詮釋可以改變員工被激勵和監督的方式。"},{"en":"Humanist interpretations of power and management focus more on people, trust, and participation.","zh":"人文主義對權力和管理的詮釋更重視人、信任和參與。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":13},{"front":"Theory X and Theory Y","meaning":"X理論和Y理論","examples":[{"en":"Douglas McGregor developed Theory X and Theory Y.","zh":"道格拉斯・麥格雷戈提出X理論和Y理論。"},{"en":"Theory X and Theory Y are two contrasting views of how managers think about workers’ motivation and responsibility.","zh":"X理論和Y理論是兩種對管理者如何看待員工動機和責任的相反觀點。"},{"en":"Theory X assumes workers dislike work, while Theory Y assumes they can enjoy responsibility.","zh":"X理論假設員工不喜歡工作，而Y理論假設他們可以享受責任。"},{"en":"Managers may act differently depending on whether they believe in Theory X or Theory Y.","zh":"管理者的行動可能因他們相信X理論或Y理論而不同。"},{"en":"Theory X and Theory Y help students compare controlling and cooperative management styles.","zh":"X理論和Y理論幫助學生比較控制式和合作式管理風格。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":13},{"front":"provide a framework","meaning":"提供框架","examples":[{"en":"McGregor’s work provided a framework for management approaches.","zh":"麥格雷戈的作品為管理取向提供框架。"},{"en":"To provide a framework means to give a structure that helps people organise and understand ideas.","zh":"提供框架是指給出一個幫助人們組織和理解思想的結構。"},{"en":"A writing plan provides a framework for students before they start an essay.","zh":"寫作計劃在學生開始文章前提供框架。"},{"en":"A framework helps researchers compare different cases in a clear way.","zh":"框架幫助研究人員以清晰方式比較不同個案。"},{"en":"Theory X and Theory Y provide a framework for thinking about employee motivation.","zh":"X理論和Y理論為思考員工動機提供框架。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":13},{"front":"management approaches","meaning":"管理取向","examples":[{"en":"Classical and newer management approaches can be placed on the framework.","zh":"古典和較新的管理取向可以放在該框架上。"},{"en":"Management approaches are different ways of leading, organising, and motivating people at work.","zh":"管理取向是領導、組織和激勵工作中人員的不同方式。"},{"en":"A strict management approach may use close supervision and detailed rules.","zh":"嚴格的管理取向可能使用密切監督和詳細規則。"},{"en":"A cooperative management approach may give employees more trust and responsibility.","zh":"合作式管理取向可能給員工更多信任和責任。"},{"en":"Different management approaches work better in different organisations and situations.","zh":"不同管理取向在不同組織和情況中效果較好。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":13},{"front":"commonly held by","meaning":"由……普遍持有","examples":[{"en":"Theory X was commonly held by early management theorists.","zh":"X理論由早期管理理論家普遍持有。"},{"en":"Commonly held by a group means widely believed, accepted, or supported by that group.","zh":"由某群體普遍持有，是指被該群體廣泛相信、接受或支持。"},{"en":"The belief that exams show ability is commonly held by many schools.","zh":"考試能顯示能力這種信念，受到許多學校普遍持有。"},{"en":"A view commonly held by older managers may be questioned by younger workers.","zh":"由較年長管理者普遍持有的觀點，可能受到年輕員工質疑。"},{"en":"Ideas commonly held by society can change when new evidence appears.","zh":"社會普遍持有的想法，可能在新證據出現時改變。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":13},{"front":"early management theorists","meaning":"早期管理理論家","examples":[{"en":"Early management theorists often accepted Theory X assumptions.","zh":"早期管理理論家常接受X理論的假設。"},{"en":"Early management theorists were thinkers who developed some of the first formal ideas about organising work.","zh":"早期管理理論家是提出最早一批正式工作組織思想的思想家。"},{"en":"Early management theorists often focused on efficiency, control, hierarchy, and productivity.","zh":"早期管理理論家常集中於效率、控制、層級和生產力。"},{"en":"Students study early management theorists to understand where modern management ideas came from.","zh":"學生研究早期管理理論家，以理解現代管理思想從何而來。"},{"en":"Some early management theorists underestimated workers’ emotional and social needs.","zh":"有些早期管理理論家低估了員工的情感和社交需要。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":13},{"front":"begin with the assumption that","meaning":"以……假設為起點","examples":[{"en":"Theory X begins with the assumption that people dislike work.","zh":"X理論以人們不喜歡工作這一假設為起點。"},{"en":"To begin with the assumption that something is true means to start an argument or theory by accepting that idea.","zh":"以某事為真這一假設為起點，是指在開始論點或理論時接受該想法。"},{"en":"A teacher should not begin with the assumption that quiet students are lazy.","zh":"老師不應以安靜學生懶惰這一假設為起點。"},{"en":"If managers begin with the assumption that workers cannot be trusted, they may over-control them.","zh":"如果管理者以員工不可信這一假設為起點，他們可能過度控制員工。"},{"en":"Good research avoids beginning with assumptions that have not been tested.","zh":"好研究避免以未經檢驗的假設為起點。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":13},{"front":"inherent aversion to work","meaning":"對工作天生厭惡","examples":[{"en":"Theory X assumes that people have an inherent aversion to work.","zh":"X理論假設人們對工作天生厭惡。"},{"en":"An inherent aversion to work means a natural dislike of working that is assumed to exist inside people.","zh":"對工作天生厭惡，是指假定人們內在自然不喜歡工作。"},{"en":"A manager who believes in an inherent aversion to work may think workers need constant supervision.","zh":"相信人們對工作天生厭惡的管理者，可能認為員工需要持續監督。"},{"en":"Theory Y rejects the idea that everyone has an inherent aversion to work.","zh":"Y理論拒絕人人對工作天生厭惡的想法。"},{"en":"Assuming an inherent aversion to work can make managers ignore employees’ creativity and ambition.","zh":"假設人們對工作天生厭惡，可能令管理者忽視員工的創意和抱負。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":13},{"front":"be coerced and controlled","meaning":"被強迫和控制","examples":[{"en":"Theory X says employees must be coerced and controlled.","zh":"X理論認為員工必須被強迫和控制。"},{"en":"To be coerced and controlled means to be forced and closely directed instead of being trusted to act freely.","zh":"被強迫和控制，是指被迫行事並受到密切指揮，而不是被信任能自由行動。"},{"en":"Workers feel coerced and controlled when every small task needs permission.","zh":"當每項小任務都需要批准時，員工會覺得自己被強迫和控制。"},{"en":"People who are coerced and controlled may obey rules but lose motivation.","zh":"被強迫和控制的人可能服從規則，但失去動機。"},{"en":"Humanist management argues that employees do not always need to be coerced and controlled.","zh":"人文主義管理主張員工不一定需要被強迫和控制。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":14},{"front":"expect results","meaning":"期望成果","examples":[{"en":"Management expects results from employees.","zh":"管理層期望員工交出成果。"},{"en":"To expect results means to require clear outcomes, progress, or performance from someone’s work.","zh":"期望成果是指要求某人的工作有清楚結果、進展或表現。"},{"en":"A coach expects results after players practise seriously for months.","zh":"球員認真練習數月後，教練會期望成果。"},{"en":"Managers expect results, but they should also provide support and resources.","zh":"管理者期望成果，但也應提供支援和資源。"},{"en":"Employees may feel pressure when leaders expect results without explaining the goal.","zh":"當領袖在沒有解釋目標下期望成果時，員工可能感到壓力。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":14},{"front":"supposedly lazy people","meaning":"被假定為懶惰的人","examples":[{"en":"Theory X assumes supposedly lazy people prefer close direction.","zh":"X理論假設被假定為懶惰的人偏好密切指導。"},{"en":"Supposedly lazy people are people assumed to be unwilling to work, though the assumption may be unfair or unproven.","zh":"被假定為懶惰的人，是指被認為不願工作的人，雖然這種假設可能不公平或未經證實。"},{"en":"A manager may wrongly treat quiet employees as supposedly lazy people.","zh":"經理可能錯誤地把安靜員工視為被假定為懶惰的人。"},{"en":"Calling workers supposedly lazy people can hide problems such as poor training or unclear goals.","zh":"把員工稱為被假定為懶惰的人，可能掩蓋培訓差或目標不清等問題。"},{"en":"Humanist theories warn against assuming that employees are supposedly lazy people.","zh":"人文主義理論提醒人們不要假設員工是被假定為懶惰的人。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":14},{"front":"close direction","meaning":"密切指導","examples":[{"en":"Theory X assumes employees prefer close direction.","zh":"X理論假設員工偏好密切指導。"},{"en":"Close direction means detailed supervision and frequent instructions from a manager.","zh":"密切指導是指經理由詳細監督和頻密指示來管理。"},{"en":"New workers may need close direction until they understand the job.","zh":"新員工在理解工作前可能需要密切指導。"},{"en":"Too much close direction can make experienced employees feel untrusted.","zh":"過多密切指導會令有經驗員工感到不被信任。"},{"en":"Close direction is useful for risky tasks, but creative work often needs more freedom.","zh":"密切指導對高風險任務有用，但創意工作通常需要更多自由。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":14},{"front":"micromanagement","meaning":"微觀管理；過度細節管理","examples":[{"en":"Theory X can lead to micromanagement.","zh":"X理論可能導致微觀管理。"},{"en":"Micromanagement is a management style in which a manager controls too many small details of employees’ work.","zh":"微觀管理是一種管理風格，指經理控制員工工作中太多小細節。"},{"en":"A manager shows micromanagement when they check every email before staff can send it.","zh":"當經理要求每封電郵都先給他檢查才可發出時，就是微觀管理。"},{"en":"Micromanagement can reduce confidence because employees feel they are not trusted.","zh":"微觀管理會削弱信心，因為員工覺得自己不被信任。"},{"en":"Good managers avoid micromanagement by setting clear goals and allowing responsible freedom.","zh":"好經理透過設定清晰目標並給予負責任的自由，避免微觀管理。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":14},{"front":"compatible with","meaning":"與……相容","examples":[{"en":"Theory Y is more compatible with the humanist tradition.","zh":"Y理論更與人文主義傳統相容。"},{"en":"Compatible with means able to fit, work, or exist well with something else.","zh":"與某事相容，是指能與另一事物良好配合、運作或共存。"},{"en":"This phone charger is compatible with several laptop models.","zh":"這個手機充電器與幾款手提電腦型號相容。"},{"en":"A flexible timetable is compatible with students who work part-time.","zh":"彈性時間表與兼職學生相容。"},{"en":"Theory Y is compatible with humanist ideas because both trust employees’ potential.","zh":"Y理論與人文主義思想相容，因為兩者都信任員工的潛力。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":14},{"front":"humanist tradition","meaning":"人文主義傳統","examples":[{"en":"Theory Y fits the humanist tradition.","zh":"Y理論符合人文主義傳統。"},{"en":"The humanist tradition focuses on people’s dignity, needs, growth, and ability to contribute.","zh":"人文主義傳統重視人的尊嚴、需要、成長和貢獻能力。"},{"en":"A teacher follows the humanist tradition when they treat students as whole people, not just test results.","zh":"當老師把學生視為完整的人，而不只是考試成績時，就是跟隨人文主義傳統。"},{"en":"The humanist tradition in management values trust and cooperation more than fear and control.","zh":"管理中的人文主義傳統更重視信任和合作，而非恐懼和控制。"},{"en":"Theory Y belongs to the humanist tradition because it sees employees as responsible and creative.","zh":"Y理論屬於人文主義傳統，因為它把員工視為負責任和有創意的人。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":14},{"front":"as natural as rest or play","meaning":"像休息或玩樂一樣自然","examples":[{"en":"Theory Y assumes that work is as natural as rest or play.","zh":"Y理論假設工作像休息或玩樂一樣自然。"},{"en":"As natural as rest or play means something can be a normal part of life, not something people automatically dislike.","zh":"像休息或玩樂一樣自然，是指某事可以是生活中的正常部分，而不是人們自動討厭的事。"},{"en":"For a curious child, learning can feel as natural as rest or play.","zh":"對好奇的孩子來說，學習可以感覺像休息或玩樂一樣自然。"},{"en":"Theory Y says work can be as natural as rest or play when conditions are supportive.","zh":"Y理論認為，在有支援的條件下，工作可以像休息或玩樂一樣自然。"},{"en":"If work feels meaningful, people may see it as natural as rest or play.","zh":"如果工作感覺有意義，人們可能會把它看成像休息或玩樂一樣自然。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":14},{"front":"direct and control themselves","meaning":"自我指導和自我控制","examples":[{"en":"Employees can direct and control themselves.","zh":"員工可以自我指導和自我控制。"},{"en":"To direct and control themselves means to guide their own actions and manage their own behaviour responsibly.","zh":"自我指導和自我控制，是指負責任地引導自己的行動並管理自己的行為。"},{"en":"University students must direct and control themselves when nobody checks their homework every day.","zh":"大學生在沒有人每天檢查功課時，必須自我指導和自我控制。"},{"en":"Employees can direct and control themselves better when goals are clear.","zh":"當目標清晰時，員工能更好地自我指導和自我控制。"},{"en":"Theory Y trusts workers to direct and control themselves instead of needing constant supervision.","zh":"Y理論信任員工能自我指導和自我控制，而不需要持續監督。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":14},{"front":"pursue objectives","meaning":"追求目標","examples":[{"en":"Employees direct themselves as they pursue objectives.","zh":"員工在追求目標時自我指導。"},{"en":"To pursue objectives means to work towards clear goals.","zh":"追求目標是指朝清晰目標努力。"},{"en":"A student pursues objectives when they plan steps to improve writing and speaking.","zh":"學生計劃改善寫作和口語的步驟時，就是在追求目標。"},{"en":"Teams pursue objectives more effectively when everyone understands the deadline and purpose.","zh":"當每個人理解期限和目的時，團隊能更有效追求目標。"},{"en":"Managers should help employees pursue objectives without controlling every small action.","zh":"管理者應幫助員工追求目標，而不是控制每個小行動。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":14},{"front":"seek responsibility","meaning":"尋求責任","examples":[{"en":"Theory Y assumes that people naturally seek responsibility.","zh":"Y理論假設人們自然尋求責任。"},{"en":"To seek responsibility means to want chances to make decisions, take ownership, and contribute.","zh":"尋求責任是指希望有機會作決定、承擔工作並作出貢獻。"},{"en":"A student seeks responsibility when they volunteer to lead a group project.","zh":"學生自願領導小組項目時，就是在尋求責任。"},{"en":"Employees may seek responsibility when they feel trusted and capable.","zh":"當員工感到被信任且有能力時，他們可能尋求責任。"},{"en":"Theory Y differs from Theory X because it believes many people seek responsibility, not only avoid work.","zh":"Y理論與X理論不同，因為它相信許多人會尋求責任，而不只是逃避工作。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":14},{"front":"guide employees cooperatively","meaning":"以合作方式引導員工","examples":[{"en":"Managers need only guide employees cooperatively.","zh":"管理者只需要以合作方式引導員工。"},{"en":"To guide employees cooperatively means to lead workers through support, discussion, and shared goals rather than force.","zh":"以合作方式引導員工，是指透過支援、討論和共同目標來領導員工，而不是強迫。"},{"en":"A manager guides employees cooperatively by asking for ideas before setting a new schedule.","zh":"經理在制定新時間表前詢問意見，就是以合作方式引導員工。"},{"en":"Guiding employees cooperatively can increase trust and responsibility.","zh":"以合作方式引導員工可以增加信任和責任感。"},{"en":"Theory Y suggests managers should guide employees cooperatively instead of micromanaging them.","zh":"Y理論建議管理者應以合作方式引導員工，而不是微觀管理他們。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":15},{"front":"towards goals","meaning":"朝向目標","examples":[{"en":"Managers guide employees towards organisational goals.","zh":"管理者引導員工朝向組織目標。"},{"en":"Towards goals means in the direction of aims that someone or a group wants to achieve.","zh":"朝向目標是指向著某人或團體想達成的目的前進。"},{"en":"A coach guides players towards goals by setting training plans and reviewing progress.","zh":"教練透過制定訓練計劃和檢視進展，引導球員朝向目標。"},{"en":"Small daily actions can move students towards goals such as fluency or confidence.","zh":"每日小行動可以推動學生朝向流利度或自信等目標。"},{"en":"Employees work better towards goals when the goals are clear and meaningful.","zh":"當目標清晰且有意義時，員工會更好地朝向目標工作。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":15},{"front":"serve the organisation","meaning":"服務於組織","examples":[{"en":"Goals should serve the organisation.","zh":"目標應服務於組織。"},{"en":"To serve the organisation means to support its purpose, needs, or long-term success.","zh":"服務於組織是指支持組織的目的、需要或長遠成功。"},{"en":"A training plan serves the organisation if it helps staff do their jobs better.","zh":"如果培訓計劃幫助員工更好工作，它就是服務於組織。"},{"en":"Personal goals should connect with team goals if they are to serve the organisation.","zh":"如果個人目標要服務於組織，就應與團隊目標連接。"},{"en":"Decisions that serve the organisation should also respect employees and the public.","zh":"服務於組織的決定也應尊重員工和公眾。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":15},{"front":"leave room for","meaning":"留下空間讓……","examples":[{"en":"Theory Y leaves room for employees to create and share power.","zh":"Y理論留下空間讓員工創造並分享權力。"},{"en":"To leave room for something means to allow space, time, or possibility for it to happen.","zh":"留下空間讓某事發生，是指允許它有空間、時間或可能性發生。"},{"en":"A teacher leaves room for questions by not filling the whole lesson with lecture.","zh":"老師不把整堂課都填滿講授，就是留下空間讓學生提問。"},{"en":"Flexible rules leave room for judgement in unusual cases.","zh":"彈性規則為特殊個案留下判斷空間。"},{"en":"Good management leaves room for creativity while still keeping clear goals.","zh":"良好管理在保持清晰目標的同時，留下空間讓創意出現。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":15},{"front":"create and share power","meaning":"創造並分享權力","examples":[{"en":"Theory Y allows people to create and share power.","zh":"Y理論允許人們創造並分享權力。"},{"en":"To create and share power means to build influence together and allow more people to take part in decisions.","zh":"創造並分享權力，是指共同建立影響力，並讓更多人參與決策。"},{"en":"A team creates and shares power when members take turns leading meetings.","zh":"當團隊成員輪流主持會議時，他們就是在創造並分享權力。"},{"en":"Organisations create and share power by letting employees contribute ideas and make choices.","zh":"組織透過讓員工提出想法和作選擇來創造並分享權力。"},{"en":"Creating and sharing power can make workers feel trusted and responsible.","zh":"創造並分享權力可以令員工感到被信任和有責任感。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":15},{"front":"Z organisation","meaning":"Z型組織","examples":[{"en":"The Z organisation is a complementary third element.","zh":"Z型組織是一個互補的第三元素。"},{"en":"A Z organisation is a management model influenced by Japanese organisational ideas, with shared responsibility and long-term commitment.","zh":"Z型組織是一種受日本組織思想影響的管理模式，重視共同責任和長期投入。"},{"en":"In a Z organisation, employees may be trusted to learn widely and contribute beyond one narrow role.","zh":"在Z型組織中，員工可能被信任去廣泛學習，並在狹窄角色以外作出貢獻。"},{"en":"A Z organisation encourages participation, but it also requires strong self-discipline.","zh":"Z型組織鼓勵參與，但也需要強大的自律。"},{"en":"The Z organisation adds another possibility beyond Theory X and Theory Y.","zh":"Z型組織在X理論和Y理論之外加入另一種可能性。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":15},{"front":"complementary third element","meaning":"互補的第三元素","examples":[{"en":"The Z organisation complements McGregor’s dichotomy.","zh":"Z型組織補充了麥格雷戈的二分法。"},{"en":"A complementary third element is an additional part that supports or completes two existing parts.","zh":"互補的第三元素是支持或補完整有兩個部分的額外部分。"},{"en":"If reading and writing are two skills, speaking can be a complementary third element in language learning.","zh":"如果閱讀和寫作是兩項技能，口語可以成為語言學習中的互補第三元素。"},{"en":"Theory Z acts as a complementary third element by adding another management possibility.","zh":"Z理論透過加入另一種管理可能性，成為互補的第三元素。"},{"en":"A complementary third element can make a simple contrast more complete.","zh":"互補的第三元素可以令簡單對比更完整。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":15},{"front":"dichotomy","meaning":"二分法","examples":[{"en":"Theory Z adds to McGregor’s dichotomy of Theory X and Theory Y.","zh":"Z理論補充了麥格雷戈X理論和Y理論的二分法。"},{"en":"A dichotomy is a division between two clearly different or opposite ideas.","zh":"二分法是把兩個清楚不同或相反的想法分開。"},{"en":"The dichotomy between city life and country life is common in essays.","zh":"城市生活與鄉村生活之間的二分法常見於文章。"},{"en":"A strict dichotomy can be too simple if real life has many mixed cases.","zh":"如果現實生活有許多混合情況，嚴格二分法可能過於簡單。"},{"en":"Theory Z makes McGregor’s dichotomy less complete by adding a third model.","zh":"Z理論透過加入第三種模式，令麥格雷戈的二分法不再完整。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":15},{"front":"be based on","meaning":"以……為基礎","examples":[{"en":"Theory Z is based on a Japanese organisational model.","zh":"Z理論以日本組織模式為基礎。"},{"en":"To be based on something means to be built from, supported by, or strongly influenced by it.","zh":"以某事為基礎，是指由它建立、支持或受到它強烈影響。"},{"en":"A film may be based on a true story.","zh":"一部電影可能以真實故事為基礎。"},{"en":"A good decision should be based on evidence, not only emotion.","zh":"好決定應以證據為基礎，而不只是情緒。"},{"en":"Theory Z is based on ideas about trust, participation, and long-term employment.","zh":"Z理論以關於信任、參與和長期僱用的思想為基礎。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":15},{"front":"Japanese organisational model","meaning":"日本組織模式","examples":[{"en":"Theory Z is based on a Japanese organisational model.","zh":"Z理論以日本組織模式為基礎。"},{"en":"A Japanese organisational model is a management style associated with Japanese firms, often stressing loyalty, participation, and long-term development.","zh":"日本組織模式是一種與日本企業相關的管理風格，常強調忠誠、參與和長期發展。"},{"en":"A company following a Japanese organisational model may train employees across different roles.","zh":"跟隨日本組織模式的公司，可能培訓員工擔任不同角色。"},{"en":"The Japanese organisational model can create strong company identity, but it may demand high commitment.","zh":"日本組織模式可以建立強烈公司身份，但可能要求高度投入。"},{"en":"Theory Z uses the Japanese organisational model to imagine a more participatory workplace.","zh":"Z理論使用日本組織模式來想像更具參與性的工作場所。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":15},{"front":"place considerable responsibility on","meaning":"將相當大的責任放在……身上","examples":[{"en":"Theory Z places considerable responsibility on employees.","zh":"Z理論將相當大的責任放在員工身上。"},{"en":"To place considerable responsibility on someone means to give them a large amount of duty, trust, or decision-making power.","zh":"將相當大的責任放在某人身上，是指給予他們大量職責、信任或決策權。"},{"en":"A school places considerable responsibility on student leaders when they organise a public event.","zh":"學校讓學生領袖組織公開活動時，就是將相當大的責任放在他們身上。"},{"en":"Managers place considerable responsibility on employees when they let them solve customer problems directly.","zh":"當管理者讓員工直接解決顧客問題時，就是將相當大的責任放在員工身上。"},{"en":"Placing considerable responsibility on workers can build confidence, but it also requires support.","zh":"將相當大的責任放在員工身上可以建立信心，但也需要支援。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":15},{"front":"relatively low-level employees","meaning":"相對低層的員工","examples":[{"en":"Relatively low-level employees are free to be creative.","zh":"相對低層的員工可自由發揮創意。"},{"en":"Relatively low-level employees are workers who are not senior compared with managers or executives.","zh":"相對低層的員工是與經理或高層相比職位不高的工作人員。"},{"en":"Relatively low-level employees may still know daily operations better than senior leaders.","zh":"相對低層的員工仍可能比高層領袖更了解日常運作。"},{"en":"Giving relatively low-level employees a voice can reveal practical problems quickly.","zh":"讓相對低層的員工發聲，可以快速揭示實際問題。"},{"en":"Theory Z gives relatively low-level employees more room to contribute than traditional bureaucracy does.","zh":"相比傳統官僚制度，Z理論給相對低層的員工更多貢獻空間。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":16},{"front":"be free to","meaning":"可自由去……","examples":[{"en":"Employees are free to be creative in Z organisations.","zh":"在Z型組織中，員工可自由發揮創意。"},{"en":"To be free to do something means to have permission or opportunity to do it without unnecessary control.","zh":"可自由做某事，是指有許可或機會去做，而沒有不必要的控制。"},{"en":"Students are free to choose their project topic if it fits the course aims.","zh":"如果符合課程目標，學生可自由選擇專題題目。"},{"en":"Workers are more motivated when they are free to suggest better methods.","zh":"當員工可自由提出更好方法時，他們會更有動力。"},{"en":"Being free to act does not mean ignoring shared rules or goals.","zh":"可自由行動並不代表忽略共同規則或目標。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":16},{"front":"wander around the organisation","meaning":"在組織內四處探索","examples":[{"en":"Employees may wander around the organisation to learn and contribute.","zh":"員工可能在組織內四處探索，以學習和作出貢獻。"},{"en":"To wander around the organisation means to move through different parts of a workplace and learn from different departments.","zh":"在組織內四處探索，是指在工作場所不同部分走動，並向不同部門學習。"},{"en":"A trainee may wander around the organisation to understand how sales, finance, and operations connect.","zh":"培訓生可能在組織內四處探索，以理解銷售、財務和營運如何連接。"},{"en":"Wandering around the organisation can help employees see problems beyond their own desk.","zh":"在組織內四處探索可以幫助員工看見自己座位以外的問題。"},{"en":"In Theory Z, employees wander around the organisation so they become more company-specific and flexible.","zh":"在Z理論中，員工在組織內四處探索，從而變得更具公司專屬特質和靈活。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":16},{"front":"genuinely distinctive","meaning":"真正具特色的","examples":[{"en":"Employees can become genuinely distinctive.","zh":"員工可以變得真正具特色。"},{"en":"Genuinely distinctive means truly different in a clear and meaningful way.","zh":"真正具特色是指以清楚且有意義的方式真正不同。"},{"en":"A restaurant becomes genuinely distinctive when its food, service, and atmosphere cannot easily be copied.","zh":"當一家餐廳的食物、服務和氣氛不容易被複製時，它就變得真正具特色。"},{"en":"Employees become genuinely distinctive when they understand the company deeply and offer unique value.","zh":"當員工深入理解公司並提供獨特價值時，他們會變得真正具特色。"},{"en":"Being genuinely distinctive is more than looking different; it means having real special qualities.","zh":"真正具特色不只是看起來不同；它意味著擁有真正特殊品質。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":16},{"front":"company-specific employees","meaning":"具公司專屬特質的員工","examples":[{"en":"Theory Z aims to develop company-specific employees.","zh":"Z理論旨在培養具公司專屬特質的員工。"},{"en":"Company-specific employees are workers whose knowledge, habits, and skills are closely shaped by one organisation.","zh":"具公司專屬特質的員工，是指其知識、習慣和技能受某一組織深深塑造的員工。"},{"en":"A company-specific employee may understand internal systems, culture, customers, and unwritten rules very well.","zh":"具公司專屬特質的員工可能非常了解內部系統、文化、顧客和不成文規則。"},{"en":"Training across departments can create company-specific employees who know how the whole business works.","zh":"跨部門培訓可以培養了解整個企業如何運作的具公司專屬特質的員工。"},{"en":"Company-specific employees can be valuable, but they may find it harder to move to very different workplaces.","zh":"具公司專屬特質的員工很有價值，但他們可能較難轉到非常不同的工作場所。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":16},{"front":"after agreeing on","meaning":"在同意……之後","examples":[{"en":"Employees gain freedom after agreeing on shared objectives.","zh":"員工在同意共同目標之後獲得自由。"},{"en":"After agreeing on something means after people have discussed it and accepted the same plan or idea.","zh":"在同意某事之後，是指人們討論並接受同一計劃或想法之後。"},{"en":"A team can start work after agreeing on the deadline and each person’s role.","zh":"團隊在同意期限和每個人的角色之後，便可以開始工作。"},{"en":"After agreeing on classroom rules, students are more likely to follow them.","zh":"在同意課室規則之後，學生更可能遵守它們。"},{"en":"In Theory Z, freedom comes after agreeing on common objectives and ways of working.","zh":"在Z理論中，自由是在同意共同目標和工作方式之後出現的。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":16},{"front":"central set of objectives","meaning":"核心目標組合","examples":[{"en":"Employees agree on a central set of objectives.","zh":"員工同意一組核心目標。"},{"en":"A central set of objectives is a group of main goals that guides everyone’s work.","zh":"核心目標組合是一組引導所有人工作的主要目標。"},{"en":"A school may set a central set of objectives, such as safety, learning, and student wellbeing.","zh":"學校可能設定一組核心目標，例如安全、學習和學生福祉。"},{"en":"A central set of objectives helps teams make decisions in the same direction.","zh":"核心目標組合幫助團隊朝同一方向作決定。"},{"en":"Without a central set of objectives, employees may work hard but move in different directions.","zh":"沒有核心目標組合時，員工可能努力工作，但走向不同方向。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":16},{"front":"ways of doing business","meaning":"做生意／營運的方式","examples":[{"en":"Employees agree on objectives and ways of doing business.","zh":"員工同意目標和做生意／營運的方式。"},{"en":"Ways of doing business are the usual methods, values, and practices a company uses when operating.","zh":"做生意／營運的方式是公司運作時使用的常見方法、價值和做法。"},{"en":"A shop’s ways of doing business include how it treats customers, handles complaints, and sets prices.","zh":"店舖做生意的方式包括如何對待顧客、處理投訴和定價。"},{"en":"Clear ways of doing business help employees understand what behaviour is expected.","zh":"清晰的營運方式幫助員工理解被期望的行為。"},{"en":"Different cultures may have different ways of doing business, especially in communication and negotiation.","zh":"不同文化可能有不同做生意的方式，尤其在溝通和談判方面。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":16},{"front":"democratic and participatory","meaning":"民主且參與式的","examples":[{"en":"Decision-making in Z organisations is democratic and participatory.","zh":"Z型組織中的決策是民主且參與式的。"},{"en":"Democratic and participatory means allowing people to take part in discussion and decision-making.","zh":"民主且參與式的是指允許人們參與討論和決策。"},{"en":"A class meeting is democratic and participatory when students can suggest rules and vote.","zh":"當學生可以提出規則並投票時，班會就是民主且參與式的。"},{"en":"Democratic and participatory management can increase trust because employees feel heard.","zh":"民主且參與式的管理可以增加信任，因為員工覺得被聆聽。"},{"en":"A democratic and participatory process may take longer, but it can create stronger commitment.","zh":"民主且參與式的過程可能較花時間，但可以建立更強投入。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":16},{"front":"despite its advantages","meaning":"儘管有其優點","examples":[{"en":"Despite its advantages, Theory Z has several drawbacks.","zh":"儘管有其優點，Z理論仍有幾個缺點。"},{"en":"Despite its advantages means although it has good points, there are still problems or limits.","zh":"儘管有其優點，是指雖然它有好處，但仍有問題或限制。"},{"en":"Despite its advantages, online learning may not suit students who need face-to-face support.","zh":"儘管有其優點，網上學習未必適合需要面對面支援的學生。"},{"en":"Despite its advantages, a strict budget can reduce flexibility.","zh":"儘管有其優點，嚴格預算可能降低靈活性。"},{"en":"This phrase is useful when you want to balance praise with criticism.","zh":"當你想在讚賞後作出批評時，這個短語很有用。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":16},{"front":"drawbacks","meaning":"缺點","examples":[{"en":"The model has several drawbacks.","zh":"這個模式有幾個缺點。"},{"en":"Drawbacks are disadvantages, problems, or negative points of something.","zh":"缺點是某事物的不足、問題或負面之處。"},{"en":"Working from home has benefits, but one drawback is loneliness.","zh":"在家工作有好處，但其中一個缺點是孤獨。"},{"en":"A policy’s drawbacks should be considered before it is introduced.","zh":"政策推出前，應考慮其缺點。"},{"en":"Understanding the drawbacks of a theory helps students avoid using it too simply.","zh":"理解理論的缺點，有助學生避免過於簡單地使用它。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":16},{"front":"professional distance","meaning":"專業距離","examples":[{"en":"Professional distance is reduced in Z organisations.","zh":"Z型組織中的專業距離會減少。"},{"en":"Professional distance means the formal separation between people at work that keeps relationships objective and role-based.","zh":"專業距離是工作中人與人之間保持客觀和以角色為基礎的正式分隔。"},{"en":"Doctors keep professional distance so patients receive fair and respectful treatment.","zh":"醫生保持專業距離，讓病人獲得公平和尊重的對待。"},{"en":"Too little professional distance can make workplace decisions feel personal or biased.","zh":"專業距離過少，可能令工作場所決定感覺個人化或有偏見。"},{"en":"Z organisations may reduce professional distance because relationships become closer and more personal.","zh":"Z型組織可能減少專業距離，因為關係變得更親近和個人化。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":17},{"front":"remain impersonal","meaning":"保持非個人化","examples":[{"en":"Relationships cannot remain impersonal in the Z model.","zh":"在Z模式中，關係不能保持非個人化。"},{"en":"To remain impersonal means to stay formal and not become based on personal feelings or relationships.","zh":"保持非個人化是指維持正式，不變成以個人感情或關係為基礎。"},{"en":"Customer service may remain impersonal when staff follow only scripts.","zh":"當員工只跟隨稿本時，客戶服務可能保持非個人化。"},{"en":"In small teams, relationships often cannot remain impersonal because people know one another well.","zh":"在小團隊中，關係通常不能保持非個人化，因為人們彼此熟悉。"},{"en":"Bureaucracy tries to remain impersonal, but human relationships can make this difficult.","zh":"官僚制度嘗試保持非個人化，但人際關係可能令這點變得困難。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":17},{"front":"in reality","meaning":"實際上","examples":[{"en":"In reality, many workers value wages more than job objectives.","zh":"實際上，許多員工重視金錢回報多於工作目標。"},{"en":"In reality means in real life, not just in theory or imagination.","zh":"實際上是指在真實生活中，而不只是理論或想像中。"},{"en":"In reality, learning a language takes daily practice, not only watching videos.","zh":"實際上，學習語言需要每日練習，而不只是觀看影片。"},{"en":"A plan may sound simple, but in reality it requires money, time, and cooperation.","zh":"一個計劃聽起來簡單，但實際上需要金錢、時間和合作。"},{"en":"In reality, employees may care about both meaningful work and financial return.","zh":"實際上，員工可能同時重視有意義的工作和金錢回報。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":17},{"front":"financial return","meaning":"金錢回報","examples":[{"en":"Many workers value the financial return more than the job’s objectives.","zh":"許多員工重視金錢回報多於工作的目標。"},{"en":"Financial return means the money or economic benefit a person receives from an activity or job.","zh":"金錢回報是指一個人從活動或工作中獲得的金錢或經濟利益。"},{"en":"Investors compare financial return before choosing where to put their money.","zh":"投資者在選擇把錢放在哪裡前，會比較金錢回報。"},{"en":"A job with low financial return may be hard to accept if living costs are high.","zh":"如果生活成本高，金錢回報低的工作可能難以接受。"},{"en":"People may value financial return because it affects rent, food, family, and future security.","zh":"人們可能重視金錢回報，因為它影響租金、食物、家庭和未來保障。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":17},{"front":"objectives of the job","meaning":"工作目標","examples":[{"en":"Some workers care less about the objectives of the job.","zh":"有些員工較少關心工作目標。"},{"en":"The objectives of the job are the main aims or purposes that the work is meant to achieve.","zh":"工作目標是該工作旨在達成的主要目的或宗旨。"},{"en":"A nurse’s job objectives may include patient safety, comfort, and recovery.","zh":"護士的工作目標可能包括病人安全、舒適和康復。"},{"en":"Employees understand their work better when the objectives of the job are clearly explained.","zh":"當工作目標被清楚解釋時，員工會更理解自己的工作。"},{"en":"If wages are too low, workers may focus more on pay than on the objectives of the job.","zh":"如果工資太低，員工可能比工作目標更重視薪酬。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":17},{"front":"high level of self-discipline","meaning":"高度自律","examples":[{"en":"The Z model requires a high level of self-discipline.","zh":"Z模式需要高度自律。"},{"en":"A high level of self-discipline means strong ability to control one’s own actions without constant supervision.","zh":"高度自律是指在沒有持續監督下強烈控制自己行動的能力。"},{"en":"Online learners need a high level of self-discipline because no teacher watches them all day.","zh":"網上學習者需要高度自律，因為沒有老師整天看著他們。"},{"en":"A high level of self-discipline helps employees use freedom responsibly.","zh":"高度自律幫助員工負責任地使用自由。"},{"en":"Without a high level of self-discipline, flexible work systems may become disorganised.","zh":"沒有高度自律，彈性工作制度可能變得混亂。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":17},{"front":"choose two letters","meaning":"選擇兩個字母","examples":[{"en":"Candidates choose two letters from the options.","zh":"考生從選項中選擇兩個字母。"},{"en":"To choose two letters means to select two answer choices, usually from a list marked A, B, C, and so on.","zh":"選擇兩個字母是指選出兩個答案選項，通常來自以A、B、C等標示的列表。"},{"en":"In a reading test, students may choose two letters that match the writer’s claims.","zh":"在閱讀測驗中，學生可能選擇兩個符合作者說法的字母。"},{"en":"If the question says choose two letters, choosing only one answer will be incomplete.","zh":"如果題目說選擇兩個字母，只選一個答案就是不完整。"},{"en":"Students should read all options carefully before they choose two letters.","zh":"學生在選擇兩個字母前，應仔細閱讀所有選項。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":17},{"front":"features and advantages of","meaning":"……的特徵和優點","examples":[{"en":"The question asks about the features and advantages of bureaucratic management.","zh":"題目詢問官僚式管理的特徵和優點。"},{"en":"Features and advantages of something are its main characteristics and good points.","zh":"某事物的特徵和優點是指它的主要特色和好處。"},{"en":"Students may describe the features and advantages of online learning, such as flexibility and access.","zh":"學生可能描述網上學習的特徵和優點，例如彈性和可及性。"},{"en":"Knowing the features and advantages of a system helps people decide whether it is useful.","zh":"了解一個制度的特徵和優點，有助人們判斷它是否有用。"},{"en":"Essays often discuss both the features and advantages of a theory before examining its limits.","zh":"文章常在檢視限制前，討論理論的特徵和優點。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":17},{"front":"equal opportunities","meaning":"平等機會","examples":[{"en":"The option discusses equal opportunities within bureaucratic management.","zh":"該選項討論官僚式管理中的平等機會。"},{"en":"Equal opportunities mean fair chances for people regardless of background, gender, age, or personal connections.","zh":"平等機會是指不論背景、性別、年齡或人脈，人們都有公平機會。"},{"en":"A school provides equal opportunities when all students can join activities, not only the richest ones.","zh":"當所有學生都能參加活動，而不只是最富裕的學生時，學校就是提供平等機會。"},{"en":"Equal opportunities in hiring reduce unfair favouritism and discrimination.","zh":"招聘中的平等機會減少不公平偏袒和歧視。"},{"en":"Bureaucratic rules may support equal opportunities if selection is based on clear criteria.","zh":"如果甄選以清晰準則為基礎，官僚規則可能支持平等機會。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":17},{"front":"hierarchy of authority","meaning":"權力層級","examples":[{"en":"Bureaucratic organisations have a hierarchy of authority.","zh":"官僚式組織有權力層級。"},{"en":"A hierarchy of authority is a system in which power is arranged in levels from higher to lower positions.","zh":"權力層級是一種權力由較高至較低職位分層排列的制度。"},{"en":"In a hospital, the hierarchy of authority shows who can approve treatment plans and staff duties.","zh":"在醫院中，權力層級顯示誰可以批准治療計劃和員工職責。"},{"en":"A hierarchy of authority can make responsibility clear, but it may slow communication.","zh":"權力層級可以令責任清晰，但也可能拖慢溝通。"},{"en":"Employees understand reporting lines better when the hierarchy of authority is clear.","zh":"當權力層級清晰時，員工更理解匯報線。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":17},{"front":"be based on job duties","meaning":"以工作職責為基礎","examples":[{"en":"Promotion may be fairer when based on job duties.","zh":"當晉升以工作職責為基礎時，可能更公平。"},{"en":"If a decision is based on job duties, it depends on what the role requires rather than personal favour.","zh":"如果一個決定以工作職責為基礎，它取決於該角色所要求的內容，而不是個人偏袒。"},{"en":"A manager evaluates staff based on job duties when checking whether required tasks are completed.","zh":"經理檢查所需任務是否完成時，就是以工作職責為基礎來評估員工。"},{"en":"Promotion based on job duties can reduce bias because the standard is clearer.","zh":"以工作職責為基礎的晉升可以減少偏見，因為標準更清晰。"},{"en":"A fair workplace explains how performance is based on job duties.","zh":"公平工作場所會解釋表現如何以工作職責為基礎。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":17},{"front":"personal characteristics","meaning":"個人特徵","examples":[{"en":"The option contrasts job duties with personal characteristics.","zh":"該選項把工作職責與個人特徵作對比。"},{"en":"Personal characteristics are individual qualities such as personality, appearance, age, confidence, or communication style.","zh":"個人特徵是個人品質，例如性格、外貌、年齡、自信或溝通風格。"},{"en":"Hiring should focus on ability, not irrelevant personal characteristics.","zh":"招聘應集中於能力，而不是無關的個人特徵。"},{"en":"Personal characteristics may affect teamwork, but they should not lead to unfair judgement.","zh":"個人特徵可能影響團隊合作，但不應導致不公平判斷。"},{"en":"Bureaucratic rules try to reduce decisions based only on personal characteristics.","zh":"官僚規則嘗試減少只基於個人特徵的決定。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":18},{"front":"greater freedom in","meaning":"在……方面更大自由","examples":[{"en":"The option asks whether employees enjoy greater freedom in their duties.","zh":"該選項詢問員工是否在職責方面享有更大自由。"},{"en":"Greater freedom in something means more choice, flexibility, or control within that area.","zh":"在某方面更大自由，是指在該範疇有更多選擇、彈性或控制權。"},{"en":"Students have greater freedom in project work when they can choose their own topic.","zh":"當學生可以選擇自己的題目時，他們在專題研習方面有更大自由。"},{"en":"Employees may feel more trusted when they have greater freedom in how they complete tasks.","zh":"當員工在完成任務方式方面有更大自由時，他們可能感到更受信任。"},{"en":"Greater freedom in work can improve creativity, but it also requires responsibility.","zh":"在工作方面更大自由可以提升創意，但也需要責任感。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":18},{"front":"strict rules","meaning":"嚴格規則","examples":[{"en":"Bureaucracy operates under strict rules.","zh":"官僚制度在嚴格規則下運作。"},{"en":"Strict rules are rules that must be followed carefully and allow little flexibility.","zh":"嚴格規則是必須仔細遵守且幾乎沒有彈性的規則。"},{"en":"Airports use strict rules to keep passengers safe.","zh":"機場使用嚴格規則來保障乘客安全。"},{"en":"Strict rules can prevent unfair behaviour, but they may also feel limiting.","zh":"嚴格規則可以防止不公平行為，但也可能感覺受限制。"},{"en":"Students must follow strict rules during exams to protect fairness.","zh":"學生在考試期間必須遵守嚴格規則，以保障公平。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":18},{"front":"selection and promotion","meaning":"甄選和晉升","examples":[{"en":"The option discusses selection and promotion decisions.","zh":"該選項討論甄選和晉升決定。"},{"en":"Selection and promotion mean choosing people for jobs and moving them to higher positions.","zh":"甄選和晉升是指選擇人員擔任工作，以及把他們提升到更高職位。"},{"en":"A company should make selection and promotion decisions using clear and fair criteria.","zh":"公司應使用清晰和公平的準則作出甄選和晉升決定。"},{"en":"Poor selection and promotion can create resentment among employees.","zh":"差劣的甄選和晉升可能在員工之間造成怨氣。"},{"en":"Bureaucracy aims to make selection and promotion less personal and more rule-based.","zh":"官僚制度旨在令甄選和晉升較少個人化，並更以規則為基礎。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":18},{"front":"mastery of new technology","meaning":"掌握新科技","examples":[{"en":"The option links promotion to mastery of new technology.","zh":"該選項把晉升與掌握新科技連繫起來。"},{"en":"Mastery of new technology means strong skill and confidence in using recently developed tools or systems.","zh":"掌握新科技是指有能力和信心使用新近發展的工具或系統。"},{"en":"A teacher shows mastery of new technology when they use online platforms smoothly in class.","zh":"老師在課堂中流暢使用網上平台時，就是掌握新科技。"},{"en":"Mastery of new technology can improve efficiency and open new career opportunities.","zh":"掌握新科技可以提升效率並開拓新職業機會。"},{"en":"Promotion should not depend only on mastery of new technology; attitude and judgement also matter.","zh":"晉升不應只取決於掌握新科技；態度和判斷力也很重要。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":18},{"front":"long-term job stability","meaning":"長期工作穩定","examples":[{"en":"Public service can provide long-term job stability.","zh":"公共服務可以提供長期工作穩定。"},{"en":"Long-term job stability means having secure employment over a long period.","zh":"長期工作穩定是指長時間擁有穩定就業。"},{"en":"Many parents value long-term job stability because it helps them plan family expenses.","zh":"許多父母重視長期工作穩定，因為它幫助他們計劃家庭開支。"},{"en":"Long-term job stability can reduce stress and encourage loyalty.","zh":"長期工作穩定可以減少壓力並鼓勵忠誠。"},{"en":"Some people choose government work because it often offers long-term job stability.","zh":"有些人選擇政府工作，因為它通常提供長期工作穩定。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":18},{"front":"limitations of bureaucratic management","meaning":"官僚式管理的限制","examples":[{"en":"The question asks about the limitations of bureaucratic management.","zh":"題目詢問官僚式管理的限制。"},{"en":"Limitations of bureaucratic management are the weaknesses or problems of using strict rules and hierarchy.","zh":"官僚式管理的限制是使用嚴格規則和層級所帶來的弱點或問題。"},{"en":"One limitation of bureaucratic management is that decisions may take too long.","zh":"官僚式管理其中一個限制是決策可能花太長時間。"},{"en":"Limitations of bureaucratic management appear clearly when organisations need quick change.","zh":"當組織需要快速改變時，官僚式管理的限制會清楚出現。"},{"en":"Understanding the limitations of bureaucratic management helps managers avoid using rules too rigidly.","zh":"理解官僚式管理的限制，有助管理者避免過於僵化地使用規則。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":18},{"front":"not given enough consideration","meaning":"未獲足夠考慮","examples":[{"en":"Employee commitment is not given enough consideration.","zh":"員工投入未獲足夠考慮。"},{"en":"If something is not given enough consideration, people do not think about it carefully enough before making a decision.","zh":"如果某事未獲足夠考慮，人們在作決定前沒有足夠仔細思考它。"},{"en":"Students’ mental health is not given enough consideration when schools focus only on exam results.","zh":"當學校只集中於考試成績時，學生心理健康未獲足夠考慮。"},{"en":"A plan may fail if local residents’ needs are not given enough consideration.","zh":"如果本地居民的需要未獲足夠考慮，計劃可能失敗。"},{"en":"In management, dedication should not be ignored or given too little consideration.","zh":"在管理中，奉獻精神不應被忽略或未獲足夠考慮。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":18},{"front":"make decision-making difficult","meaning":"令決策困難","examples":[{"en":"Formalities and rules can make decision-making difficult.","zh":"手續和規則可以令決策困難。"},{"en":"To make decision-making difficult means to create obstacles that stop people from choosing quickly or clearly.","zh":"令決策困難是指製造障礙，使人不能快速或清楚地作出選擇。"},{"en":"Too many forms can make decision-making difficult in a hospital.","zh":"太多表格可以令醫院中的決策困難。"},{"en":"Conflicting advice can make decision-making difficult for families choosing a school.","zh":"互相矛盾的建議可以令家庭選擇學校時決策困難。"},{"en":"A good system removes unnecessary steps that make decision-making difficult.","zh":"良好制度會移除令決策困難的不必要步驟。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":18},{"front":"formalities and rules","meaning":"手續和規則","examples":[{"en":"Formalities and rules can cause unnecessary delays.","zh":"手續和規則可能造成不必要的延誤。"},{"en":"Formalities and rules are official procedures and instructions that people must follow.","zh":"手續和規則是人們必須遵守的官方程序和指示。"},{"en":"Applying for a licence often involves formalities and rules such as forms, documents, and approvals.","zh":"申請牌照通常涉及表格、文件和批准等手續和規則。"},{"en":"Formalities and rules can protect fairness, but too many can slow action.","zh":"手續和規則可以保護公平，但太多會拖慢行動。"},{"en":"Organisations should keep necessary formalities and rules while removing pointless ones.","zh":"組織應保留必要的手續和規則，同時移除無意義的部分。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":18},{"front":"be organised casually","meaning":"被鬆散地組織","examples":[{"en":"The option says employees are organised casually.","zh":"該選項說員工被鬆散地組織。"},{"en":"To be organised casually means to be arranged in a loose, informal, or not very systematic way.","zh":"被鬆散地組織，是指以鬆散、非正式或不太系統化的方式安排。"},{"en":"A weekend picnic can be organised casually without a detailed timetable.","zh":"週末野餐可以被鬆散地組織，不需要詳細時間表。"},{"en":"A hospital should not be organised casually because safety requires clear responsibility.","zh":"醫院不應被鬆散地組織，因為安全需要清晰責任。"},{"en":"Bureaucratic organisations are usually not organised casually; they rely on formal structure.","zh":"官僚式組織通常不是被鬆散地組織；它們依賴正式結構。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":18},{"front":"enforce rules and regulations","meaning":"執行規則和規例","examples":[{"en":"The option asks whether rules and regulations are difficult to enforce.","zh":"該選項詢問規則和規例是否難以執行。"},{"en":"To enforce rules and regulations means to make sure people obey official instructions.","zh":"執行規則和規例是指確保人們遵守官方指示。"},{"en":"Schools enforce rules and regulations by checking attendance and behaviour.","zh":"學校透過檢查出席和行為來執行規則和規例。"},{"en":"Rules are difficult to enforce if nobody understands them or if punishments are unclear.","zh":"如果沒有人理解規則，或懲罰不清楚，規則就難以執行。"},{"en":"Fair enforcement of rules and regulations helps people trust the system.","zh":"公平執行規則和規例，有助人們信任制度。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":19},{"front":"be applicable to","meaning":"適用於","examples":[{"en":"Bureaucracy may not be applicable to dynamic organisations.","zh":"官僚制度未必適用於動態組織。"},{"en":"To be applicable to something means to be relevant, suitable, or able to be used in that situation.","zh":"適用於某事，是指與該情況相關、合適或可以使用。"},{"en":"A grammar rule may not be applicable to every sentence.","zh":"一條文法規則未必適用於每個句子。"},{"en":"A business strategy applicable to a large company may not work for a small shop.","zh":"適用於大公司的商業策略，未必適用於小店。"},{"en":"Bureaucracy is more applicable to stable organisations than to fast-changing ones.","zh":"官僚制度較適用於穩定組織，而不是快速變化的組織。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":19},{"front":"dynamic organisations","meaning":"動態組織","examples":[{"en":"Dynamic organisations experience rapid change.","zh":"動態組織經歷快速變化。"},{"en":"Dynamic organisations are organisations that change quickly and often need flexible decisions.","zh":"動態組織是變化快速且常需要彈性決策的組織。"},{"en":"Technology start-ups are often dynamic organisations because products and markets change fast.","zh":"科技初創企業通常是動態組織，因為產品和市場變化很快。"},{"en":"Dynamic organisations may struggle with rigid procedures because they need quick responses.","zh":"動態組織可能難以應付僵化程序，因為它們需要快速回應。"},{"en":"Managers in dynamic organisations must balance freedom, coordination, and clear goals.","zh":"動態組織中的管理者必須平衡自由、協調和清晰目標。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":19},{"front":"change is rapid","meaning":"變化迅速","examples":[{"en":"Bureaucracy is less suitable where change is rapid.","zh":"在變化迅速的地方，官僚制度較不合適。"},{"en":"If change is rapid, conditions, needs, or problems alter quickly.","zh":"如果變化迅速，條件、需要或問題會快速改變。"},{"en":"In technology markets, change is rapid because new products appear all the time.","zh":"在科技市場中，變化迅速，因為新產品不斷出現。"},{"en":"When change is rapid, slow approval systems may become a serious weakness.","zh":"當變化迅速時，緩慢審批制度可能成為嚴重弱點。"},{"en":"Organisations need flexible communication when change is rapid.","zh":"當變化迅速時，組織需要彈性的溝通。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":19},{"front":"reflect the aims of","meaning":"反映……的目標","examples":[{"en":"The question asks which statements reflect the aims of Theory Y.","zh":"題目詢問哪些陳述反映Y理論的目標。"},{"en":"To reflect the aims of something means to show or match its main purposes.","zh":"反映某事的目標，是指顯示或符合其主要目的。"},{"en":"A school rule reflects the aims of safety if it protects students from harm.","zh":"如果學校規則保護學生免受傷害，它就反映安全的目標。"},{"en":"A company policy reflects the aims of teamwork when it rewards cooperation.","zh":"當公司政策獎勵合作時，它反映團隊合作的目標。"},{"en":"Statements reflect the aims of Theory Y when they show trust, responsibility, and self-direction.","zh":"當陳述顯示信任、責任和自我指導時，它們就反映Y理論的目標。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":19},{"front":"management under Theory Y","meaning":"Y理論下的管理","examples":[{"en":"Management under Theory Y guides employees cooperatively.","zh":"Y理論下的管理以合作方式引導員工。"},{"en":"Management under Theory Y is a style that trusts employees to work responsibly and direct themselves.","zh":"Y理論下的管理是一種信任員工負責任工作和自我指導的風格。"},{"en":"A manager using management under Theory Y may discuss goals with employees instead of giving constant orders.","zh":"使用Y理論下管理的經理，可能與員工討論目標，而不是持續發出命令。"},{"en":"Management under Theory Y can increase motivation because workers feel respected.","zh":"Y理論下的管理可以增加動機，因為員工感到受尊重。"},{"en":"Management under Theory Y works best when employees have clear goals and enough support.","zh":"當員工有清晰目標和足夠支援時，Y理論下的管理最有效。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":19},{"front":"humans will not automatically seek responsibility","meaning":"人不會自然尋求責任","examples":[{"en":"The option questions whether humans automatically seek responsibility.","zh":"該選項質疑人是否會自然尋求責任。"},{"en":"Humans will not automatically seek responsibility means people may not naturally ask for duties unless conditions encourage them.","zh":"人不會自然尋求責任，是指除非條件鼓勵，否則人們未必自然要求承擔職責。"},{"en":"Some students will not automatically seek responsibility if they fear making mistakes.","zh":"如果學生害怕犯錯，有些學生不會自然尋求責任。"},{"en":"Workers may not automatically seek responsibility when they feel unsupported or punished for failure.","zh":"當員工感到缺乏支援或因失敗受懲罰時，他們未必會自然尋求責任。"},{"en":"This idea contrasts with Theory Y, which assumes people can naturally seek responsibility.","zh":"這個想法與Y理論形成對比，因為Y理論假設人可以自然尋求責任。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":19},{"front":"scope to delegate","meaning":"授權空間","examples":[{"en":"The option asks whether managers have scope to delegate power.","zh":"該選項詢問管理者是否有授權空間。"},{"en":"Scope to delegate means room or opportunity for managers to give responsibility or authority to others.","zh":"授權空間是指管理者有空間或機會把責任或權力交給他人。"},{"en":"A team leader has scope to delegate when staff are trained and trusted.","zh":"當員工受過訓練且被信任時，團隊領袖就有授權空間。"},{"en":"Managers need scope to delegate if they want employees to develop decision-making skills.","zh":"如果管理者希望員工發展決策技能，就需要授權空間。"},{"en":"Without scope to delegate, all decisions remain at the top and work becomes slower.","zh":"沒有授權空間時，所有決定都留在高層，工作會變慢。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":19},{"front":"share power","meaning":"分享權力","examples":[{"en":"Theory Y allows managers to share power.","zh":"Y理論允許管理者分享權力。"},{"en":"To share power means to let more than one person take part in influence, responsibility, or decision-making.","zh":"分享權力是指讓不只一個人參與影響、責任或決策。"},{"en":"A teacher shares power when students help design classroom rules.","zh":"老師讓學生幫忙制定課室規則時，就是分享權力。"},{"en":"Managers share power by allowing staff to choose methods and solve problems.","zh":"管理者讓員工選擇方法和解決問題，就是分享權力。"},{"en":"Sharing power can increase commitment because people feel trusted and involved.","zh":"分享權力可以增加投入，因為人們感到被信任和參與其中。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":19},{"front":"limitations of Theory Z","meaning":"Z理論的限制","examples":[{"en":"The question asks about the limitations of Theory Z.","zh":"題目詢問Z理論的限制。"},{"en":"Limitations of Theory Z are the weaknesses or problems of this participatory management model.","zh":"Z理論的限制是這種參與式管理模式的弱點或問題。"},{"en":"One limitation of Theory Z is that not every worker values company goals more than wages.","zh":"Z理論其中一個限制是並非每位員工都把公司目標看得比工資重要。"},{"en":"Limitations of Theory Z appear when employees lack self-discipline or prefer clear boundaries.","zh":"當員工缺乏自律或偏好清晰界線時，Z理論的限制會出現。"},{"en":"Understanding the limitations of Theory Z prevents managers from treating it as a perfect solution.","zh":"理解Z理論的限制，可以防止管理者把它視為完美解決方案。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":19},{"front":"inherent design flaw","meaning":"內在設計缺陷","examples":[{"en":"The option refers to an inherent design flaw in the model.","zh":"該選項提到模式中的內在設計缺陷。"},{"en":"An inherent design flaw is a weakness built into the structure of a system from the beginning.","zh":"內在設計缺陷是從一開始就存在於制度結構中的弱點。"},{"en":"A chair has an inherent design flaw if it easily falls over because of its shape.","zh":"如果椅子因形狀而容易翻倒，它就有內在設計缺陷。"},{"en":"An inherent design flaw can cause repeated problems even when people use the system correctly.","zh":"即使人們正確使用系統，內在設計缺陷也可能造成重複問題。"},{"en":"Critics may argue that a theory has an inherent design flaw if its basic assumptions are unrealistic.","zh":"如果一個理論的基本假設不切實際，批評者可能認為它有內在設計缺陷。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":19},{"front":"value the work more highly than wages","meaning":"將工作看得比工資更重要","examples":[{"en":"Not all employees value the work more highly than their wages.","zh":"並非所有員工都將工作看得比工資更重要。"},{"en":"To value the work more highly than wages means to care more about the purpose or meaning of a job than the money it pays.","zh":"將工作看得比工資更重要，是指比起薪酬，更重視工作的目的或意義。"},{"en":"Some artists may value the work more highly than wages when the project has deep personal meaning.","zh":"當項目有深刻個人意義時，有些藝術家可能將工作看得比工資更重要。"},{"en":"Many workers cannot value the work more highly than wages if they struggle to pay rent.","zh":"如果許多員工難以支付租金，他們無法將工作看得比工資更重要。"},{"en":"Theory Z may be limited because not everyone values work more highly than wages.","zh":"Z理論可能有限，因為並非所有人都將工作看得比工資更重要。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":20},{"front":"personalisation","meaning":"個人化","examples":[{"en":"Theory Z may make personalisation hard to avoid.","zh":"Z理論可能令個人化難以避免。"},{"en":"Personalisation means making something depend on personal relationships, feelings, or individual preferences.","zh":"個人化是指令某事取決於個人關係、感情或個人偏好。"},{"en":"Personalisation can improve customer service when a shop remembers regular customers’ needs.","zh":"當店舖記得常客需要時，個人化可以改善客戶服務。"},{"en":"In management, too much personalisation may make decisions seem unfair.","zh":"在管理中，過度個人化可能令決定看起來不公平。"},{"en":"Bureaucracy tries to reduce personalisation by relying on official roles and rules.","zh":"官僚制度透過依賴正式角色和規則來減少個人化。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":20},{"front":"impossible to eliminate","meaning":"無法消除","examples":[{"en":"The option says personalisation remains impossible to eliminate.","zh":"該選項說個人化仍然無法消除。"},{"en":"Impossible to eliminate means cannot be completely removed.","zh":"無法消除是指不能被完全移除。"},{"en":"Small mistakes may be impossible to eliminate in a very large project.","zh":"在非常大型的項目中，小錯誤可能無法消除。"},{"en":"Bias is hard and sometimes impossible to eliminate, so systems need checks and transparency.","zh":"偏見很難且有時無法消除，所以制度需要檢查和平透明度。"},{"en":"In close workplaces, personal feelings may be impossible to eliminate entirely.","zh":"在關係密切的工作場所中，個人感情可能無法完全消除。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":20},{"front":"use the information in","meaning":"使用……中的資料","examples":[{"en":"Candidates use the information in the passage to match people with statements.","zh":"考生使用文章中的資料將人物與陳述配對。"},{"en":"To use the information in a text means to base your answer on what the text says.","zh":"使用文本中的資料，是指以文本所說內容作為答案基礎。"},{"en":"Students should use the information in the chart instead of guessing from memory.","zh":"學生應使用圖表中的資料，而不是憑記憶猜測。"},{"en":"In reading exams, using the information in the passage prevents careless outside assumptions.","zh":"在閱讀考試中，使用文章中的資料可以防止粗心加入外部假設。"},{"en":"Good answers use the information in the source clearly and accurately.","zh":"好答案會清楚且準確地使用來源中的資料。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":20},{"front":"match people with opinions or actions","meaning":"將人物與觀點或行動配對","examples":[{"en":"Candidates match people with opinions or actions below.","zh":"考生將人物與下列觀點或行動配對。"},{"en":"To match people with opinions or actions means to connect each person to what they thought, said, or did.","zh":"將人物與觀點或行動配對，是指把每個人與其想法、說法或做法連接起來。"},{"en":"In a history lesson, students match leaders with actions such as reforms or wars.","zh":"在歷史課中，學生把領袖與改革或戰爭等行動配對。"},{"en":"Reading questions may ask students to match people with opinions or actions mentioned in the passage.","zh":"閱讀題可能要求學生將人物與文章中提及的觀點或行動配對。"},{"en":"To answer correctly, students must find evidence before they match people with opinions or actions.","zh":"要正確作答，學生在將人物與觀點或行動配對前，必須找到證據。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":20},{"front":"appropriate letter","meaning":"適當字母","examples":[{"en":"Candidates write the appropriate letter for each question.","zh":"考生為每題寫上適當字母。"},{"en":"The appropriate letter is the answer choice that correctly matches the question.","zh":"適當字母是正確配合題目的答案選項。"},{"en":"In a matching task, students write the appropriate letter beside each statement.","zh":"在配對題中，學生在每句陳述旁寫上適當字母。"},{"en":"The appropriate letter should be chosen from the options given, not invented by the candidate.","zh":"適當字母應從提供的選項中選出，而不是由考生自行創作。"},{"en":"Students should check spelling and numbering after writing the appropriate letter.","zh":"學生寫上適當字母後，應檢查串字和題號。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":20},{"front":"may match more than one statement","meaning":"可配對多於一項陳述","examples":[{"en":"Some people may match more than one statement.","zh":"有些人物可配對多於一項陳述。"},{"en":"May match more than one statement means one person can be the correct answer for several items.","zh":"可配對多於一項陳述，是指一個人可以是幾個項目的正確答案。"},{"en":"In a reading task, one researcher may match more than one statement if the passage mentions several of their ideas.","zh":"在閱讀題中，如果文章提到某研究者的幾個想法，該研究者可配對多於一項陳述。"},{"en":"Students should not assume each person is used only once when the instructions say they may match more than one statement.","zh":"當指示說可配對多於一項陳述時，學生不應假設每個人物只使用一次。"},{"en":"Careful reading is needed because a name may match more than one statement.","zh":"需要仔細閱讀，因為一個名字可配對多於一項陳述。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":20},{"front":"core set of objectives","meaning":"核心目標組合","examples":[{"en":"High effectiveness requires agreement on a core set of objectives.","zh":"高效能需要就核心目標組合達成一致。"},{"en":"A core set of objectives is a small group of main goals that everyone accepts as central.","zh":"核心目標組合是一小組被所有人接受為核心的主要目標。"},{"en":"A project team needs a core set of objectives before deciding tasks and deadlines.","zh":"項目團隊在決定任務和期限前，需要一組核心目標。"},{"en":"Agreement on a core set of objectives helps people work in the same direction.","zh":"就核心目標組合達成一致，有助人們朝同一方向工作。"},{"en":"Without a core set of objectives, freedom may turn into confusion.","zh":"沒有核心目標組合，自由可能變成混亂。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":20},{"front":"emotional needs","meaning":"情感需要","examples":[{"en":"Managers need to consider employees’ emotional needs.","zh":"管理者需要考慮員工的情感需要。"},{"en":"Emotional needs are needs for respect, belonging, recognition, support, and psychological safety.","zh":"情感需要是對尊重、歸屬感、認可、支援和心理安全的需要。"},{"en":"A student’s emotional needs include feeling safe enough to ask questions.","zh":"學生的情感需要包括感到安全，敢於提問。"},{"en":"Employees may lose motivation if their emotional needs are ignored.","zh":"如果員工的情感需要被忽略，他們可能失去動機。"},{"en":"Good management considers emotional needs as well as pay and job duties.","zh":"良好管理會考慮情感需要，也會考慮薪酬和工作職責。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":20},{"front":"in addition to","meaning":"除了……之外","examples":[{"en":"Managers should consider emotional needs in addition to material rewards.","zh":"除了物質回報之外，管理者也應考慮情感需要。"},{"en":"In addition to means as well as or besides something else.","zh":"除了……之外，是指也包括或此外還有某事。"},{"en":"In addition to homework, students need time to rest and read freely.","zh":"除了功課之外，學生需要時間休息和自由閱讀。"},{"en":"A healthy workplace provides respect in addition to fair pay.","zh":"健康的工作場所除了公平薪酬之外，也提供尊重。"},{"en":"In addition to rules, public organisations need good communication.","zh":"除了規則之外，公共組織也需要良好溝通。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":20},{"front":"incentive system","meaning":"誘因制度","examples":[{"en":"Emotional needs may be part of an incentive system.","zh":"情感需要可能是誘因制度的一部分。"},{"en":"An incentive system is a set of rewards or reasons designed to encourage people to act or stay involved.","zh":"誘因制度是一套旨在鼓勵人們行動或持續參與的回報或理由。"},{"en":"A company’s incentive system may include bonuses, training, praise, and promotion opportunities.","zh":"公司的誘因制度可能包括獎金、培訓、表揚和晉升機會。"},{"en":"A weak incentive system can make employees feel that effort brings no reward.","zh":"薄弱的誘因制度會令員工覺得努力沒有回報。"},{"en":"A good incentive system includes both material and non-material rewards.","zh":"良好的誘因制度包括物質和非物質回報。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":20},{"front":"maximise self-interest","meaning":"將自身利益最大化","examples":[{"en":"Individuals try to maximise their self-interest under constraints.","zh":"個人在限制下嘗試將自身利益最大化。"},{"en":"To maximise self-interest means to choose the option that brings the greatest personal benefit.","zh":"將自身利益最大化是指選擇帶來最大個人利益的選項。"},{"en":"A worker may maximise self-interest by choosing a job with better pay and shorter travel time.","zh":"員工可能透過選擇薪酬更好且通勤更短的工作，將自身利益最大化。"},{"en":"People maximise self-interest differently because they value money, time, safety, and comfort differently.","zh":"人們以不同方式將自身利益最大化，因為他們對金錢、時間、安全和舒適的重視不同。"},{"en":"Public policy must consider how people try to maximise self-interest.","zh":"公共政策必須考慮人們如何嘗試將自身利益最大化。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":21},{"front":"budgetary resources","meaning":"預算資源","examples":[{"en":"The option refers to the effective use of budgetary resources.","zh":"該選項提到有效使用預算資源。"},{"en":"Budgetary resources are the money and financial limits available for a plan, department, or organisation.","zh":"預算資源是某計劃、部門或組織可用的金錢和財政限制。"},{"en":"A school uses budgetary resources when it decides how much to spend on books, staff, and repairs.","zh":"學校決定在書本、員工和維修上花多少錢時，就是在使用預算資源。"},{"en":"Budgetary resources should be used carefully because they are limited.","zh":"預算資源應小心使用，因為它們有限。"},{"en":"Poor planning can waste budgetary resources and leave important needs unfunded.","zh":"差劣規劃會浪費預算資源，並令重要需要得不到資助。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":21},{"front":"be used effectively","meaning":"被有效運用","examples":[{"en":"Resources and choices can be used effectively.","zh":"資源和選擇可以被有效運用。"},{"en":"To be used effectively means to be used in a way that produces good results without unnecessary waste.","zh":"被有效運用是指以能產生良好結果且避免不必要浪費的方式使用。"},{"en":"Classroom time is used effectively when students practise skills instead of only copying notes.","zh":"當學生練習技能而不只是抄筆記時，課堂時間就被有效運用。"},{"en":"Money is used effectively when it solves the most urgent problems first.","zh":"當金錢先解決最迫切問題時，它就被有效運用。"},{"en":"Public resources must be used effectively because they come from society and serve society.","zh":"公共資源必須被有效運用，因為它們來自社會並服務社會。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":21},{"front":"naturally dislike work","meaning":"天生不喜歡工作","examples":[{"en":"Theory X assumes that humans naturally dislike work.","zh":"X理論假設人類天生不喜歡工作。"},{"en":"To naturally dislike work means to have an inborn or automatic unwillingness to work.","zh":"天生不喜歡工作是指對工作有天生或自動的不願意。"},{"en":"A manager who thinks employees naturally dislike work may rely on strict control.","zh":"認為員工天生不喜歡工作的管理者，可能依賴嚴格控制。"},{"en":"Theory Y challenges the idea that people naturally dislike work.","zh":"Y理論挑戰人們天生不喜歡工作的想法。"},{"en":"People may dislike bad working conditions, but that does not mean they naturally dislike work itself.","zh":"人們可能不喜歡差劣工作條件，但這不代表他們天生不喜歡工作本身。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":21},{"front":"be forced and controlled","meaning":"被強迫和控制","examples":[{"en":"Theory X says people must be forced and controlled.","zh":"X理論認為人們必須被強迫和控制。"},{"en":"To be forced and controlled means to be made to act through pressure, rules, and close supervision.","zh":"被強迫和控制是指透過壓力、規則和密切監督被要求行動。"},{"en":"Children may feel forced and controlled if every minute of their day is decided by adults.","zh":"如果孩子一天中的每一分鐘都由成年人決定，他們可能感到被強迫和控制。"},{"en":"Employees who are forced and controlled may do the minimum but lose creativity.","zh":"被強迫和控制的員工可能只做最低限度，並失去創意。"},{"en":"Humanist management suggests that people work better when guided and trusted, not simply forced and controlled.","zh":"人文主義管理認為，人在被引導和信任時工作得更好，而不只是被強迫和控制。"}],"source":"159 - Development of Public management theory.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 160":[{"front":"coral reefs","meaning":"珊瑚礁","examples":[{"en":"Coral reefs are underwater structures made from calcium carbonate.","zh":"珊瑚礁是由碳酸鈣構成的水底結構。"},{"en":"Coral reefs are hard sea structures built by tiny animals over a long time.","zh":"珊瑚礁是由微小動物經過長時間建成的堅硬海洋結構。"},{"en":"Divers visit coral reefs because they are full of colourful fish and sea life.","zh":"潛水員會到珊瑚礁，因為那裡充滿色彩鮮艷的魚和海洋生物。"},{"en":"If coral reefs are damaged, many marine animals lose food and shelter.","zh":"如果珊瑚礁受損，許多海洋動物會失去食物和棲息地。"},{"en":"Coral reefs may look like rocks, but they are connected to living organisms.","zh":"珊瑚礁可能看起來像岩石，但它們與活生物有關。"}],"source":"160 - Coral reefs.pdf","sourcePage":1},{"front":"underwater structures","meaning":"水底結構","examples":[{"en":"Coral reefs are underwater structures made from calcium carbonate.","zh":"珊瑚礁是由碳酸鈣構成的水底結構。"},{"en":"Underwater structures are physical formations or objects found below the surface of water.","zh":"水底結構是位於水面以下的實體構造或物件。"},{"en":"A sunken ship can become an underwater structure where fish hide.","zh":"沉船可以成為魚類躲藏的水底結構。"},{"en":"Underwater structures can protect young sea animals from strong currents.","zh":"水底結構可以保護幼小海洋動物免受強勁水流影響。"},{"en":"Some underwater structures are natural, while others are built by humans.","zh":"有些水底結構是天然的，有些則是人類建造的。"}],"source":"160 - Coral reefs.pdf","sourcePage":1},{"front":"calcium carbonate","meaning":"碳酸鈣","examples":[{"en":"Corals secrete calcium carbonate to form reef structures.","zh":"珊瑚會分泌碳酸鈣來形成珊瑚礁結構。"},{"en":"Calcium carbonate is a hard mineral substance found in shells, limestone, and coral skeletons.","zh":"碳酸鈣是一種堅硬的礦物質，存在於貝殼、石灰岩和珊瑚骨骼中。"},{"en":"Eggshells contain calcium carbonate, which helps make them firm.","zh":"蛋殼含有碳酸鈣，因此較為堅固。"},{"en":"When corals produce calcium carbonate, they slowly build strong reef foundations.","zh":"當珊瑚產生碳酸鈣時，它們會慢慢建成堅固的珊瑚礁基礎。"},{"en":"Without enough calcium carbonate, reef structures would be weaker and less stable.","zh":"如果沒有足夠碳酸鈣，珊瑚礁結構會較脆弱和不穩定。"}],"source":"160 - Coral reefs.pdf","sourcePage":1},{"front":"secreted by","meaning":"由……分泌","examples":[{"en":"Coral reefs are made from calcium carbonate secreted by corals.","zh":"珊瑚礁由珊瑚分泌的碳酸鈣構成。"},{"en":"Secreted by means produced and released by a living organism.","zh":"secreted by 指由某種生物產生並釋放出來。"},{"en":"Sweat is a liquid secreted by the body when it needs to cool down.","zh":"汗液是身體需要降溫時分泌出來的液體。"},{"en":"Materials secreted by small animals can harden and form protective layers.","zh":"微小動物分泌的物質可以硬化並形成保護層。"},{"en":"A substance secreted by an organism often has a special biological function.","zh":"由生物分泌的物質通常具有特定生物功能。"}],"source":"160 - Coral reefs.pdf","sourcePage":1},{"front":"colonies of","meaning":"……的群落","examples":[{"en":"Coral reefs are colonies of tiny living animals.","zh":"珊瑚礁是微小活體動物的群落。"},{"en":"Colonies of living things are groups that live close together and often depend on one another.","zh":"生物群落是指生活在一起並常常互相依賴的群體。"},{"en":"Colonies of ants work together to find food and protect the nest.","zh":"螞蟻群落會合作尋找食物和保護巢穴。"},{"en":"Colonies of corals can grow larger when conditions are warm and stable.","zh":"當環境溫暖而穩定，珊瑚群落可以長得更大。"},{"en":"A single animal may be tiny, but colonies of them can form large structures.","zh":"單一動物可能很微小，但牠們的群落可以形成大型結構。"}],"source":"160 - Coral reefs.pdf","sourcePage":1},{"front":"tiny living animals","meaning":"微小活體動物","examples":[{"en":"Coral reefs are made up of colonies of tiny living animals.","zh":"珊瑚礁由微小活體動物的群落組成。"},{"en":"Tiny living animals are very small organisms that eat, grow, reproduce, and respond to their environment.","zh":"微小活體動物是非常細小、會進食、生長、繁殖並回應環境的生物。"},{"en":"A child may not see tiny living animals in pond water without a microscope.","zh":"孩子如果沒有顯微鏡，可能看不到池水中的微小活體動物。"},{"en":"Tiny living animals can still shape large ecosystems when they live in huge numbers.","zh":"當微小活體動物數量龐大時，仍能塑造大型生態系統。"},{"en":"Coral reefs remind us that tiny living animals can create something enormous over time.","zh":"珊瑚礁提醒我們，微小活體動物可以隨時間創造巨大事物。"}],"source":"160 - Coral reefs.pdf","sourcePage":1},{"front":"marine waters","meaning":"海洋水域","examples":[{"en":"Coral reefs are found in marine waters that contain few nutrients.","zh":"珊瑚礁存在於營養物很少的海洋水域中。"},{"en":"Marine waters are waters connected to seas or oceans.","zh":"海洋水域是與海或海洋相連的水域。"},{"en":"Fish farms in marine waters must be managed carefully to avoid pollution.","zh":"位於海洋水域的養魚場必須小心管理，以避免污染。"},{"en":"Warm marine waters can support coral growth when light and temperature are suitable.","zh":"當光照和溫度合適時，溫暖的海洋水域可以支持珊瑚生長。"},{"en":"Marine waters differ from freshwater because they contain salt.","zh":"海洋水域與淡水不同，因為它們含有鹽分。"}],"source":"160 - Coral reefs.pdf","sourcePage":1},{"front":"contain few nutrients","meaning":"含有很少營養物","examples":[{"en":"Many coral reefs grow in waters that contain few nutrients.","zh":"許多珊瑚礁生長在含有很少營養物的水域中。"},{"en":"Waters that contain few nutrients have only small amounts of substances that plants and animals use for growth.","zh":"含有很少營養物的水域，只有少量供植物和動物生長使用的物質。"},{"en":"A poor garden soil may contain few nutrients, so vegetables grow slowly.","zh":"貧瘠的花園土壤可能含有很少營養物，所以蔬菜生長緩慢。"},{"en":"If water contains few nutrients, algae may not grow as quickly.","zh":"如果水含有很少營養物，藻類可能不會快速生長。"},{"en":"It seems surprising that coral reefs can be rich in life where waters contain few nutrients.","zh":"珊瑚礁能在含有很少營養物的水域中孕育豐富生命，這似乎令人驚訝。"}],"source":"160 - Coral reefs.pdf","sourcePage":1},{"front":"stony corals","meaning":"石珊瑚","examples":[{"en":"Most coral reefs are built from stony corals.","zh":"大多數珊瑚礁由石珊瑚建成。"},{"en":"Stony corals are corals that produce hard skeletons and help build reef structures.","zh":"石珊瑚是會產生堅硬骨骼並幫助形成珊瑚礁結構的珊瑚。"},{"en":"In an aquarium, stony corals need stable water conditions to stay healthy.","zh":"在水族箱中，石珊瑚需要穩定水質才能保持健康。"},{"en":"Stony corals can form the solid framework that supports many reef animals.","zh":"石珊瑚可以形成支撐許多珊瑚礁動物的堅固框架。"},{"en":"Soft corals may bend with the water, but stony corals create harder reef foundations.","zh":"軟珊瑚可能會隨水流擺動，但石珊瑚會建立較硬的珊瑚礁基礎。"}],"source":"160 - Coral reefs.pdf","sourcePage":1},{"front":"consist of","meaning":"由……組成","examples":[{"en":"Stony corals consist of polyps that cluster in groups.","zh":"石珊瑚由聚集成群的珊瑚蟲組成。"},{"en":"Consist of means to be made up of particular parts or things.","zh":"consist of 指由某些部分或事物組成。"},{"en":"A simple breakfast may consist of bread, eggs, and tea.","zh":"一份簡單早餐可能由麵包、雞蛋和茶組成。"},{"en":"If a team consists of people with different skills, it can solve problems more easily.","zh":"如果一個團隊由具備不同技能的人組成，它會更容易解決問題。"},{"en":"The phrase consist of is useful when explaining what something contains.","zh":"consist of 這個片語在解釋某物包含甚麼時很有用。"}],"source":"160 - Coral reefs.pdf","sourcePage":1},{"front":"polyps","meaning":"珊瑚蟲；水螅體","examples":[{"en":"Stony corals consist of polyps that cluster in groups.","zh":"石珊瑚由聚集成群的珊瑚蟲組成。"},{"en":"Polyps are small soft-bodied animals that can build coral structures.","zh":"珊瑚蟲是身體柔軟、能建造珊瑚結構的小動物。"},{"en":"Coral polyps use their tiny tentacles to catch food from the water.","zh":"珊瑚蟲會用細小觸手從水中捕捉食物。"},{"en":"When many polyps live together, they can slowly form a reef.","zh":"當許多珊瑚蟲一起生活時，它們可以慢慢形成珊瑚礁。"},{"en":"Polyps are small, but their repeated growth can create large coral systems.","zh":"珊瑚蟲很小，但它們不斷生長可以創造大型珊瑚系統。"}],"source":"160 - Coral reefs.pdf","sourcePage":2},{"front":"cluster in groups","meaning":"聚集成群","examples":[{"en":"The polyps cluster in groups to form coral structures.","zh":"珊瑚蟲會聚集成群，形成珊瑚結構。"},{"en":"To cluster in groups means to gather closely together instead of spreading out separately.","zh":"cluster in groups 指緊密聚集在一起，而不是分散開來。"},{"en":"Students may cluster in groups outside a classroom before a lesson begins.","zh":"上課前，學生可能會在課室外聚集成群。"},{"en":"When animals cluster in groups, they may find protection or warmth more easily.","zh":"當動物聚集成群時，牠們可能更容易獲得保護或保暖。"},{"en":"Coral polyps cluster in groups, so many small bodies can build one larger structure.","zh":"珊瑚蟲聚集成群，因此許多小身體可以建成一個更大的結構。"}],"source":"160 - Coral reefs.pdf","sourcePage":2},{"front":"be estimated to","meaning":"估計……","examples":[{"en":"Coral reefs are estimated to cover 284,300 square kilometres.","zh":"據估計，珊瑚礁覆蓋284,300平方公里。"},{"en":"Be estimated to means experts believe a number is likely, although it may not be exact.","zh":"be estimated to 指專家認為某個數字大概如此，但未必完全準確。"},{"en":"The repair is estimated to cost several thousand dollars.","zh":"這次維修估計要花費數千元。"},{"en":"If a city is estimated to have ten million people, the real number may be slightly different.","zh":"如果一個城市估計有一千萬人口，實際數字可能略有不同。"},{"en":"Scientists use this phrase when exact measurement is difficult.","zh":"當準確測量有困難時，科學家會使用這個片語。"}],"source":"160 - Coral reefs.pdf","sourcePage":2},{"front":"just under","meaning":"略低於","examples":[{"en":"Coral reefs cover just under 0.1% of the oceans’ surface area.","zh":"珊瑚礁覆蓋略低於海洋表面面積的0.1%。"},{"en":"Just under means slightly less than a particular number or amount.","zh":"just under 指略少於某個數字或數量。"},{"en":"The journey took just under an hour, so we arrived earlier than expected.","zh":"旅程用了略低於一小時，所以我們比預期早到。"},{"en":"If a bill is just under $100, it is close to $100 but not quite that much.","zh":"如果帳單略低於100美元，它接近100美元但未到這個數目。"},{"en":"Just under is often used when a number is very near a limit.","zh":"just under 常用於表示某數字非常接近某個界線。"}],"source":"160 - Coral reefs.pdf","sourcePage":2},{"front":"oceans’ surface area","meaning":"海洋表面面積","examples":[{"en":"Coral reefs cover a small part of the oceans’ surface area.","zh":"珊瑚礁只覆蓋海洋表面面積的一小部分。"},{"en":"The oceans’ surface area is the total area covered by the top surface of the world’s oceans.","zh":"海洋表面面積是世界海洋表面所覆蓋的總面積。"},{"en":"Maps help students compare land area with the oceans’ surface area.","zh":"地圖幫助學生比較陸地面積和海洋表面面積。"},{"en":"Even a tiny percentage of the oceans’ surface area can represent a very large space.","zh":"即使是海洋表面面積中很小的百分比，也可能代表很大的空間。"},{"en":"Coral reefs cover little of the oceans’ surface area but support much marine life.","zh":"珊瑚礁覆蓋的海洋表面面積很小，卻支持大量海洋生命。"}],"source":"160 - Coral reefs.pdf","sourcePage":2},{"front":"about half the area of","meaning":"約為……面積的一半","examples":[{"en":"The total area of coral reefs is about half the area of France.","zh":"珊瑚礁總面積約為法國面積的一半。"},{"en":"About half the area of means roughly 50% as large as another place or space.","zh":"about half the area of 指面積大約是另一個地方或空間的百分之五十。"},{"en":"The park is about half the area of the old airport.","zh":"這個公園約為舊機場面積的一半。"},{"en":"If a lake is about half the area of a city, it is still very large.","zh":"如果一個湖約為一個城市面積的一半，它仍然非常大。"},{"en":"This phrase helps readers imagine size by comparing it with a familiar place.","zh":"這個片語透過與熟悉地方比較，幫助讀者想像大小。"}],"source":"160 - Coral reefs.pdf","sourcePage":2},{"front":"the Indo-Pacific region","meaning":"印度洋－太平洋地區","examples":[{"en":"The Indo-Pacific region accounts for most of the world’s coral reefs.","zh":"印度洋－太平洋地區佔世界珊瑚礁的大部分。"},{"en":"The Indo-Pacific region refers broadly to the ocean area linking the Indian Ocean and the Pacific Ocean.","zh":"印度洋－太平洋地區大致指連接印度洋和太平洋的海洋區域。"},{"en":"Many island nations in the Indo-Pacific region depend on healthy seas for food and jobs.","zh":"印度洋－太平洋地區的許多島國依賴健康海洋提供食物和就業。"},{"en":"Because the Indo-Pacific region contains many warm shallow seas, many reefs can grow there.","zh":"由於印度洋－太平洋地區有許多溫暖淺海，許多珊瑚礁能在那裡生長。"},{"en":"The Indo-Pacific region is important in discussions of marine biodiversity.","zh":"印度洋－太平洋地區在海洋生物多樣性的討論中十分重要。"}],"source":"160 - Coral reefs.pdf","sourcePage":2},{"front":"account for","meaning":"佔","examples":[{"en":"The Indo-Pacific region accounts for 91.9% of the total reef area.","zh":"印度洋－太平洋地區佔珊瑚礁總面積的91.9%。"},{"en":"Account for means to make up a particular part or percentage of a total.","zh":"account for 指佔某個總數中的特定部分或百分比。"},{"en":"Rent may account for a large part of a student’s monthly spending.","zh":"租金可能佔學生每月開支的一大部分。"},{"en":"If online sales account for half of a shop’s income, the website is very important.","zh":"如果網上銷售佔店舖收入的一半，網站就非常重要。"},{"en":"This phrase is useful when describing proportions in charts or reports.","zh":"這個片語在描述圖表或報告中的比例時很有用。"}],"source":"160 - Coral reefs.pdf","sourcePage":2},{"front":"total area","meaning":"總面積","examples":[{"en":"Southeast Asia accounts for a large share of the total area.","zh":"東南亞佔總面積中的很大一部分。"},{"en":"Total area means the full amount of space covered by something.","zh":"total area 指某物所覆蓋的全部空間大小。"},{"en":"The total area of a flat includes the living room, bedrooms, kitchen, and bathroom.","zh":"一個單位的總面積包括客廳、睡房、廚房和浴室。"},{"en":"If the total area of a park increases, more people can use it for exercise.","zh":"如果公園總面積增加，更多人可以用它來運動。"},{"en":"Total area helps us compare the size of different places or habitats.","zh":"總面積幫助我們比較不同地方或棲息地的大小。"}],"source":"160 - Coral reefs.pdf","sourcePage":2},{"front":"Southeast Asia","meaning":"東南亞","examples":[{"en":"Southeast Asia contains a large proportion of the world’s coral reefs.","zh":"東南亞包含世界珊瑚礁中的很大比例。"},{"en":"Southeast Asia is a region that includes countries such as Indonesia, Malaysia, Thailand, Vietnam, and the Philippines.","zh":"東南亞是一個地區，包括印尼、馬來西亞、泰國、越南和菲律賓等國家。"},{"en":"Many travellers visit Southeast Asia for its islands, food, cities, and beaches.","zh":"許多旅客到訪東南亞，是為了那裡的島嶼、食物、城市和海灘。"},{"en":"Warm seas around Southeast Asia help support many coral reef ecosystems.","zh":"東南亞周圍的溫暖海域有助支持許多珊瑚礁生態系統。"},{"en":"Southeast Asia is often discussed when people study tropical biodiversity.","zh":"人們研究熱帶生物多樣性時，常會討論東南亞。"}],"source":"160 - Coral reefs.pdf","sourcePage":2},{"front":"including Australia","meaning":"包括澳洲","examples":[{"en":"The Pacific, including Australia, accounts for 40.8% of coral reefs.","zh":"太平洋地區，包括澳洲，佔珊瑚礁的40.8%。"},{"en":"Including Australia means Australia is part of the group being described.","zh":"including Australia 指澳洲是所描述群體的一部分。"},{"en":"Several countries, including Australia, have large coastal areas and important marine habitats.","zh":"多個國家，包括澳洲，都擁有廣闊海岸地區和重要海洋棲息地。"},{"en":"If a report says the region includes Australia, Australia should not be counted separately.","zh":"如果報告說該地區包括澳洲，澳洲就不應另行計算。"},{"en":"This phrase helps make the membership of a group clearer.","zh":"這個片語有助更清楚說明某個群體包括哪些成員。"}],"source":"160 - Coral reefs.pdf","sourcePage":3},{"front":"Atlantic and Caribbean coral reefs","meaning":"大西洋和加勒比海珊瑚礁","examples":[{"en":"Atlantic and Caribbean coral reefs account for 7.6% of the total area.","zh":"大西洋和加勒比海珊瑚礁佔總面積的7.6%。"},{"en":"Atlantic and Caribbean coral reefs are reefs found in the Atlantic Ocean and Caribbean Sea area.","zh":"大西洋和加勒比海珊瑚礁是位於大西洋和加勒比海地區的珊瑚礁。"},{"en":"Many island communities near Atlantic and Caribbean coral reefs depend on tourism and fishing.","zh":"許多靠近大西洋和加勒比海珊瑚礁的島嶼社區依賴旅遊和捕魚。"},{"en":"If these reefs decline, local beaches and marine life may suffer.","zh":"如果這些珊瑚礁衰退，本地海灘和海洋生命可能受害。"},{"en":"Atlantic and Caribbean coral reefs form a smaller share of global reefs than Indo-Pacific reefs.","zh":"大西洋和加勒比海珊瑚礁佔全球珊瑚礁的比例小於印度洋－太平洋珊瑚礁。"}],"source":"160 - Coral reefs.pdf","sourcePage":3},{"front":"rainforests of the sea","meaning":"海中雨林","examples":[{"en":"Coral reefs are often called rainforests of the sea.","zh":"珊瑚礁常被稱為海中雨林。"},{"en":"Rainforests of the sea means coral reefs support an unusually rich variety of life.","zh":"海中雨林指珊瑚礁支持異常豐富的生命種類。"},{"en":"A teacher may use this phrase to help students imagine how lively reefs are.","zh":"老師可能使用這個說法，幫助學生想像珊瑚礁有多生機勃勃。"},{"en":"Because many species live there, damage to these rainforests of the sea affects whole ecosystems.","zh":"由於許多物種生活在那裡，海中雨林受損會影響整個生態系統。"},{"en":"The phrase is a metaphor, not a statement that reefs are actual forests.","zh":"這個說法是一個比喻，並不是指珊瑚礁是真正的森林。"}],"source":"160 - Coral reefs.pdf","sourcePage":3},{"front":"diverse ecosystems","meaning":"多樣化的生態系統","examples":[{"en":"Coral reefs form some of the most diverse ecosystems on Earth.","zh":"珊瑚礁形成地球上一些最多樣化的生態系統。"},{"en":"Diverse ecosystems contain many different species and relationships between living things.","zh":"多樣化的生態系統包含許多不同物種，以及生物之間的關係。"},{"en":"A healthy forest is a diverse ecosystem because it supports trees, insects, birds, and mammals.","zh":"健康森林是一個多樣化的生態系統，因為它支持樹木、昆蟲、鳥類和哺乳動物。"},{"en":"Diverse ecosystems are often more valuable because many organisms depend on them.","zh":"多樣化的生態系統通常更有價值，因為許多生物依賴它們。"},{"en":"Coral reefs are diverse ecosystems even though they cover a small ocean area.","zh":"雖然珊瑚礁只覆蓋小部分海洋面積，但它們是多樣化的生態系統。"}],"source":"160 - Coral reefs.pdf","sourcePage":3},{"front":"provide a home for","meaning":"為……提供棲息地","examples":[{"en":"Coral reefs provide a home for 25% of all marine species.","zh":"珊瑚礁為所有海洋物種的25%提供棲息地。"},{"en":"Provide a home for means to give living things a place where they can live, feed, or reproduce.","zh":"provide a home for 指為生物提供生活、覓食或繁殖的地方。"},{"en":"Old trees provide a home for birds, insects, and small animals.","zh":"老樹為鳥類、昆蟲和小動物提供棲息地。"},{"en":"If wetlands disappear, they no longer provide a home for many water birds.","zh":"如果濕地消失，它們就不再為許多水鳥提供棲息地。"},{"en":"Coral reefs provide a home for species that may not survive in open water.","zh":"珊瑚礁為一些可能無法在開闊水域生存的物種提供棲息地。"}],"source":"160 - Coral reefs.pdf","sourcePage":3},{"front":"marine species","meaning":"海洋物種","examples":[{"en":"Coral reefs provide habitats for many marine species.","zh":"珊瑚礁為許多海洋物種提供棲息地。"},{"en":"Marine species are plants, animals, and other organisms that live in the sea.","zh":"海洋物種是在海中生活的植物、動物和其他生物。"},{"en":"Dolphins, sea turtles, seaweed, and reef fish are all marine species.","zh":"海豚、海龜、海藻和珊瑚礁魚都是海洋物種。"},{"en":"Pollution can reduce the number of marine species in a coastal area.","zh":"污染可能減少沿海地區的海洋物種數量。"},{"en":"Protecting marine species often means protecting the habitats where they live.","zh":"保護海洋物種通常意味著保護牠們生活的棲息地。"}],"source":"160 - Coral reefs.pdf","sourcePage":3},{"front":"molluscs","meaning":"軟體動物","examples":[{"en":"Molluscs are among the marine species that live on coral reefs.","zh":"軟體動物是生活在珊瑚礁上的海洋物種之一。"},{"en":"Molluscs are soft-bodied animals, often with shells, such as clams, snails, and octopuses.","zh":"軟體動物是身體柔軟、通常有殼的動物，例如蛤蜊、蝸牛和八爪魚。"},{"en":"Children can find some molluscs in rock pools near the shore.","zh":"孩子可以在岸邊岩池中找到一些軟體動物。"},{"en":"If reef habitats decline, some molluscs may lose places to feed or hide.","zh":"如果珊瑚礁棲息地衰退，一些軟體動物可能失去覓食或躲藏的地方。"},{"en":"Molluscs are one example of the varied life supported by coral reefs.","zh":"軟體動物是珊瑚礁所支持的多樣生命之一。"}],"source":"160 - Coral reefs.pdf","sourcePage":3},{"front":"crustaceans","meaning":"甲殼類動物","examples":[{"en":"Crustaceans are one group of animals found around coral reefs.","zh":"甲殼類動物是在珊瑚礁周圍發現的一類動物。"},{"en":"Crustaceans are animals with hard outer shells, such as crabs, shrimps, and lobsters.","zh":"甲殼類動物是有堅硬外殼的動物，例如蟹、蝦和龍蝦。"},{"en":"A seafood market may sell several kinds of crustaceans.","zh":"海鮮市場可能出售多種甲殼類動物。"},{"en":"Crustaceans can hide among rocks and coral to avoid predators.","zh":"甲殼類動物可以躲在岩石和珊瑚之間，以避開捕食者。"},{"en":"Coral reefs support crustaceans by offering food, shelter, and breeding spaces.","zh":"珊瑚礁透過提供食物、庇護和繁殖空間來支持甲殼類動物。"}],"source":"160 - Coral reefs.pdf","sourcePage":3},{"front":"echinoderms","meaning":"棘皮動物","examples":[{"en":"Echinoderms are part of the diverse life supported by coral reefs.","zh":"棘皮動物是珊瑚礁所支持的多樣生命的一部分。"},{"en":"Echinoderms are sea animals with spiny skin, such as starfish and sea urchins.","zh":"棘皮動物是具有多刺皮膚的海洋動物，例如海星和海膽。"},{"en":"Students may see echinoderms in a marine biology lesson or aquarium.","zh":"學生可能在海洋生物課或水族館中看到棘皮動物。"},{"en":"Some echinoderms help clean the sea floor by feeding on small particles.","zh":"有些棘皮動物會以小顆粒為食，幫助清理海床。"},{"en":"Echinoderms show that reef life includes more than fish and corals.","zh":"棘皮動物顯示珊瑚礁生命不只包括魚和珊瑚。"}],"source":"160 - Coral reefs.pdf","sourcePage":3},{"front":"sponges","meaning":"海綿動物","examples":[{"en":"Sponges are found in coral reef ecosystems.","zh":"海綿動物存在於珊瑚礁生態系統中。"},{"en":"Sponges are simple sea animals that filter water to collect food.","zh":"海綿動物是簡單的海洋動物，會過濾水來收集食物。"},{"en":"In an aquarium, sponges may look like colourful soft lumps attached to rocks.","zh":"在水族館中，海綿動物可能看起來像附在岩石上的彩色軟塊。"},{"en":"Sponges can improve water clarity by filtering tiny particles.","zh":"海綿動物可以透過過濾細小顆粒改善水的清澈度。"},{"en":"Although sponges do not move like fish, they are still living animals.","zh":"雖然海綿動物不像魚一樣移動，但它們仍然是活生物。"}],"source":"160 - Coral reefs.pdf","sourcePage":3},{"front":"tunicates","meaning":"被囊動物","examples":[{"en":"Tunicates are included among the species found on coral reefs.","zh":"被囊動物包括在珊瑚礁上的物種之中。"},{"en":"Tunicates are small marine animals that filter seawater for food.","zh":"被囊動物是會過濾海水取食的小型海洋動物。"},{"en":"Some tunicates look like soft sacs attached to rocks or reef surfaces.","zh":"有些被囊動物看起來像附在岩石或珊瑚礁表面的柔軟囊狀物。"},{"en":"Tunicates can live quietly in reef communities while filtering tiny food particles.","zh":"被囊動物可以安靜地生活在珊瑚礁群落中，同時過濾細小食物顆粒。"},{"en":"Learning about tunicates helps students see how varied reef animals can be.","zh":"認識被囊動物幫助學生看見珊瑚礁動物可以多麼多樣化。"}],"source":"160 - Coral reefs.pdf","sourcePage":4},{"front":"cnidarians","meaning":"刺胞動物","examples":[{"en":"Coral reefs support cnidarians and many other marine animals.","zh":"珊瑚礁支持刺胞動物和許多其他海洋動物。"},{"en":"Cnidarians are animals such as corals, jellyfish, and sea anemones, often with stinging cells.","zh":"刺胞動物包括珊瑚、水母和海葵等動物，通常具有刺細胞。"},{"en":"A swimmer may avoid some cnidarians because their stings can hurt.","zh":"游泳者可能會避開某些刺胞動物，因為牠們的刺會令人疼痛。"},{"en":"Cnidarians can catch tiny prey using specialised body parts.","zh":"刺胞動物可以利用特殊身體部位捕捉細小獵物。"},{"en":"Corals themselves are cnidarians, so they are both reef builders and reef animals.","zh":"珊瑚本身就是刺胞動物，所以牠們既是珊瑚礁建造者，也是珊瑚礁動物。"}],"source":"160 - Coral reefs.pdf","sourcePage":4},{"front":"paradoxically","meaning":"矛盾的是","examples":[{"en":"Paradoxically, coral reefs flourish in waters with few nutrients.","zh":"矛盾的是，珊瑚礁在營養物很少的水域中繁盛生長。"},{"en":"Paradoxically means something seems surprising because it is opposite to what we expect.","zh":"paradoxically 指某事與我們預期相反，因此顯得令人驚訝。"},{"en":"Paradoxically, working fewer hours may help some people produce better work.","zh":"矛盾的是，工作時間較少可能幫助一些人做出更好的工作。"},{"en":"Paradoxically, a quiet student may understand the lesson more deeply than a talkative one.","zh":"矛盾的是，一個安靜的學生可能比健談的學生更深入理解課堂。"},{"en":"We use paradoxically when the result seems strange but is still true.","zh":"當結果看似奇怪但仍然真實時，我們會使用 paradoxically。"}],"source":"160 - Coral reefs.pdf","sourcePage":4},{"front":"flourish","meaning":"繁盛生長","examples":[{"en":"Coral reefs flourish even in nutrient-poor waters.","zh":"珊瑚礁即使在營養物貧乏的水域中也能繁盛生長。"},{"en":"Flourish means to grow well, develop strongly, or succeed in a healthy way.","zh":"flourish 指良好生長、強健發展或健康地成功。"},{"en":"Plants flourish when they receive enough light, water, and care.","zh":"植物在獲得足夠陽光、水分和照料時會繁盛生長。"},{"en":"A small business can flourish if customers trust its service.","zh":"如果顧客信任服務，小企業也可以蓬勃發展。"},{"en":"Coral reefs flourish only when the surrounding conditions support life.","zh":"珊瑚礁只有在周圍環境支持生命時才能繁盛生長。"}],"source":"160 - Coral reefs.pdf","sourcePage":4},{"front":"surrounded by","meaning":"被……包圍","examples":[{"en":"Coral reefs are surrounded by ocean waters that provide few nutrients.","zh":"珊瑚礁被提供很少營養物的海水包圍。"},{"en":"Surrounded by means having something all around on every side.","zh":"surrounded by 指四周都被某物圍繞。"},{"en":"The school is surrounded by trees, so the playground feels cool in summer.","zh":"學校被樹木包圍，所以操場在夏天感覺涼爽。"},{"en":"If a house is surrounded by floodwater, people may not be able to leave safely.","zh":"如果房屋被洪水包圍，人們可能無法安全離開。"},{"en":"A reef surrounded by clear water may still depend on careful nutrient recycling.","zh":"被清澈海水包圍的珊瑚礁，仍可能依賴精細的營養循環。"}],"source":"160 - Coral reefs.pdf","sourcePage":4},{"front":"nutrient-poor waters","meaning":"營養物貧乏的水域","examples":[{"en":"Coral reefs can flourish in nutrient-poor waters.","zh":"珊瑚礁可以在營養物貧乏的水域中繁盛生長。"},{"en":"Nutrient-poor waters contain low levels of substances needed for plant or animal growth.","zh":"營養物貧乏的水域含有較少供植物或動物生長所需的物質。"},{"en":"A lake with nutrient-poor waters may have fewer algal blooms.","zh":"營養物貧乏的湖泊可能較少出現藻華。"},{"en":"Coral reefs survive in nutrient-poor waters partly because their organisms recycle resources efficiently.","zh":"珊瑚礁能在營養物貧乏的水域中生存，部分原因是其中生物能有效循環資源。"},{"en":"Nutrient-poor waters are not necessarily lifeless, but life there must adapt.","zh":"營養物貧乏的水域不一定沒有生命，但那裡的生命必須適應。"}],"source":"160 - Coral reefs.pdf","sourcePage":4},{"front":"shallow depths","meaning":"淺水深度","examples":[{"en":"Coral reefs are most commonly found at shallow depths in tropical waters.","zh":"珊瑚礁最常見於熱帶水域中的淺水深度。"},{"en":"Shallow depths are areas where the water is not very deep.","zh":"淺水深度是指水不太深的地方。"},{"en":"Children usually learn to swim at shallow depths before entering deeper water.","zh":"孩子通常先在淺水深度學游泳，然後才進入更深水域。"},{"en":"Coral reefs often grow at shallow depths because sunlight can reach them more easily.","zh":"珊瑚礁常在淺水深度生長，因為陽光較容易到達。"},{"en":"Shallow depths can be safer for beginners, but reefs there may be easily damaged by people.","zh":"淺水深度對初學者可能較安全，但那裡的珊瑚礁也較容易被人破壞。"}],"source":"160 - Coral reefs.pdf","sourcePage":4},{"front":"tropical waters","meaning":"熱帶水域","examples":[{"en":"Shallow-water reefs usually form in tropical waters.","zh":"淺水珊瑚礁通常形成於熱帶水域。"},{"en":"Tropical waters are warm sea waters found near the equator.","zh":"熱帶水域是赤道附近的溫暖海水。"},{"en":"Many holiday islands attract visitors because of their clear tropical waters.","zh":"許多度假島嶼因清澈的熱帶水域吸引遊客。"},{"en":"Tropical waters can support coral growth when light and temperature remain suitable.","zh":"當光照和溫度保持合適，熱帶水域可以支持珊瑚生長。"},{"en":"Tropical waters are warm, but they can still be harmed by pollution and overfishing.","zh":"熱帶水域雖然溫暖，但仍會受到污染和過度捕魚傷害。"}],"source":"160 - Coral reefs.pdf","sourcePage":4},{"front":"deep-water corals","meaning":"深水珊瑚","examples":[{"en":"Deep-water corals exist at greater depths and colder temperatures.","zh":"深水珊瑚存在於更深水域和較低溫度中。"},{"en":"Deep-water corals are corals that live far below the surface, often without much sunlight.","zh":"深水珊瑚是生活在水面以下很深處、通常缺乏大量陽光的珊瑚。"},{"en":"Scientists may use special equipment to study deep-water corals.","zh":"科學家可能使用特殊設備研究深水珊瑚。"},{"en":"Deep-water corals can be damaged by fishing gear dragged along the sea floor.","zh":"深水珊瑚可能被沿海床拖行的捕魚器具破壞。"},{"en":"Unlike shallow reefs, deep-water corals do not depend on bright tropical sunlight in the same way.","zh":"與淺水珊瑚礁不同，深水珊瑚並不以同樣方式依賴明亮的熱帶陽光。"}],"source":"160 - Coral reefs.pdf","sourcePage":4},{"front":"cold-water corals","meaning":"冷水珊瑚","examples":[{"en":"Cold-water corals exist on smaller scales in other areas.","zh":"冷水珊瑚在其他地區以較小規模存在。"},{"en":"Cold-water corals are corals that can live in colder seas than tropical corals.","zh":"冷水珊瑚是能生活在比熱帶珊瑚更寒冷海域中的珊瑚。"},{"en":"Researchers may find cold-water corals in deep parts of the ocean.","zh":"研究人員可能在海洋深處發現冷水珊瑚。"},{"en":"Cold-water corals grow slowly, so damage to them can take a long time to recover.","zh":"冷水珊瑚生長緩慢，因此受損後可能需要很長時間恢復。"},{"en":"Cold-water corals show that not all corals live in warm shallow water.","zh":"冷水珊瑚顯示並非所有珊瑚都生活在溫暖淺水中。"}],"source":"160 - Coral reefs.pdf","sourcePage":4},{"front":"on smaller scales","meaning":"以較小規模","examples":[{"en":"Cold-water corals exist on smaller scales in some regions.","zh":"冷水珊瑚在一些地區以較小規模存在。"},{"en":"On smaller scales means in smaller amounts, areas, or levels than something else.","zh":"on smaller scales 指以較小的數量、範圍或層面存在或進行。"},{"en":"A city project may first be tested on smaller scales in two neighbourhoods.","zh":"一項城市計劃可能先在兩個社區以較小規模測試。"},{"en":"If a plan works on smaller scales, leaders may later expand it.","zh":"如果一個計劃以較小規模運作良好，領導者之後可能擴大它。"},{"en":"Cold-water corals exist on smaller scales than large tropical reef systems.","zh":"冷水珊瑚相對大型熱帶珊瑚礁系統，是以較小規模存在。"}],"source":"160 - Coral reefs.pdf","sourcePage":5},{"front":"temperate and tropical waters","meaning":"溫帶及熱帶水域","examples":[{"en":"Corals exist in both temperate and tropical waters.","zh":"珊瑚存在於溫帶及熱帶水域中。"},{"en":"Temperate and tropical waters include both moderately warm seas and very warm seas near the equator.","zh":"溫帶及熱帶水域包括較溫和的海域，以及赤道附近非常溫暖的海域。"},{"en":"Marine animals may live differently in temperate and tropical waters because temperatures vary.","zh":"由於溫度不同，海洋動物在溫帶及熱帶水域中的生活方式可能不同。"},{"en":"Studying temperate and tropical waters helps scientists compare different coral habitats.","zh":"研究溫帶及熱帶水域幫助科學家比較不同珊瑚棲息地。"},{"en":"Corals are not limited to one climate zone, although reef types differ.","zh":"珊瑚並不限於一個氣候帶，雖然珊瑚礁類型會有所不同。"}],"source":"160 - Coral reefs.pdf","sourcePage":5},{"front":"shallow-water reefs","meaning":"淺水珊瑚礁","examples":[{"en":"Shallow-water reefs form only in a limited zone near the equator.","zh":"淺水珊瑚礁只形成於赤道附近的有限地帶。"},{"en":"Shallow-water reefs are coral reef systems that grow in water close enough to the surface for sunlight to reach.","zh":"淺水珊瑚礁是在接近水面、陽光能到達的水域中生長的珊瑚礁系統。"},{"en":"Snorkelers often visit shallow-water reefs because they can see fish without diving deeply.","zh":"浮潛人士常到淺水珊瑚礁，因為不需深潛也能看見魚。"},{"en":"Shallow-water reefs depend on light, so cloudy or polluted water can harm them.","zh":"淺水珊瑚礁依賴光線，因此混濁或受污染的水可能傷害它們。"},{"en":"Shallow-water reefs are easier to reach, which can make them more vulnerable to careless tourism.","zh":"淺水珊瑚礁較容易到達，因此可能更容易受到不小心旅遊行為影響。"}],"source":"160 - Coral reefs.pdf","sourcePage":5},{"front":"a zone extending from","meaning":"從……延伸至……的地帶","examples":[{"en":"Shallow-water reefs form in a zone extending from 30°N to 30°S.","zh":"淺水珊瑚礁形成於從北緯30度延伸至南緯30度的地帶。"},{"en":"A zone extending from one point to another is an area that stretches between those two limits.","zh":"a zone extending from one point to another 指在兩個界線之間延伸的地區。"},{"en":"The school bus serves a zone extending from the town centre to the harbour.","zh":"校巴服務一個從市中心延伸至港口的地帶。"},{"en":"If a disease warning covers a zone extending from one city to another, people across that area should be careful.","zh":"如果疾病警告涵蓋從一個城市延伸至另一個城市的地帶，該區所有人都應小心。"},{"en":"This phrase is useful when describing a geographical range.","zh":"這個片語在描述地理範圍時很有用。"}],"source":"160 - Coral reefs.pdf","sourcePage":5},{"front":"the equator","meaning":"赤道","examples":[{"en":"Shallow-water reefs form near the equator.","zh":"淺水珊瑚礁形成於赤道附近。"},{"en":"The equator is the imaginary line around the middle of Earth, halfway between the North and South Poles.","zh":"赤道是環繞地球中部的想像線，位於北極和南極之間。"},{"en":"Countries near the equator often have warm weather throughout the year.","zh":"赤道附近的國家通常全年天氣溫暖。"},{"en":"Because sunlight is strong near the equator, some tropical ecosystems can grow well there.","zh":"由於赤道附近陽光強烈，一些熱帶生態系統能在那裡良好生長。"},{"en":"The equator helps geographers describe north-south positions on Earth.","zh":"赤道幫助地理學家描述地球上的南北位置。"}],"source":"160 - Coral reefs.pdf","sourcePage":5},{"front":"greater depths","meaning":"更深水域","examples":[{"en":"Deep-water corals can exist at greater depths.","zh":"深水珊瑚可以存在於更深水域。"},{"en":"Greater depths means deeper parts of water, far below the surface.","zh":"greater depths 指水面以下更深的地方。"},{"en":"Divers need special training before going to greater depths.","zh":"潛水員在前往更深水域前需要特殊訓練。"},{"en":"At greater depths, there is usually less light and stronger pressure.","zh":"在更深水域，通常光線較少，壓力較強。"},{"en":"Some animals can survive at greater depths where humans cannot easily go.","zh":"有些動物能在更深水域生存，而人類不易到達那裡。"}],"source":"160 - Coral reefs.pdf","sourcePage":5},{"front":"colder temperatures","meaning":"較低溫度","examples":[{"en":"Some corals can survive at colder temperatures.","zh":"有些珊瑚可以在較低溫度下生存。"},{"en":"Colder temperatures are lower temperatures than those normally expected in a place or system.","zh":"colder temperatures 指比某地或某系統通常預期更低的溫度。"},{"en":"Food lasts longer at colder temperatures because bacteria grow more slowly.","zh":"食物在較低溫度下能保存更久，因為細菌生長較慢。"},{"en":"Animals living at colder temperatures may need special adaptations.","zh":"生活在較低溫度中的動物可能需要特殊適應能力。"},{"en":"Cold-water corals show that some corals can live beyond warm tropical seas.","zh":"冷水珊瑚顯示有些珊瑚能生活在溫暖熱帶海域以外。"}],"source":"160 - Coral reefs.pdf","sourcePage":5},{"front":"higher latitudes","meaning":"較高緯度","examples":[{"en":"Deep-water corals can exist at much higher latitudes.","zh":"深水珊瑚可以存在於高得多的緯度。"},{"en":"Higher latitudes are places farther from the equator and closer to the poles.","zh":"較高緯度是指較遠離赤道、較接近兩極的地方。"},{"en":"Countries at higher latitudes often have colder winters.","zh":"位於較高緯度的國家通常冬天較寒冷。"},{"en":"Species living at higher latitudes may adapt to shorter days and lower temperatures.","zh":"生活在較高緯度的物種可能會適應較短日照和較低溫度。"},{"en":"Finding corals at higher latitudes shows that coral habitats are more varied than many people think.","zh":"在較高緯度發現珊瑚，顯示珊瑚棲息地比許多人想像中更多樣。"}],"source":"160 - Coral reefs.pdf","sourcePage":5},{"front":"as far north as","meaning":"北至……","examples":[{"en":"Deep-water corals can be found as far north as Norway.","zh":"深水珊瑚北至挪威也可以被發現。"},{"en":"As far north as means reaching a northern place that may seem surprisingly far away.","zh":"as far north as 指到達某個可能令人意外地偏北的地方。"},{"en":"Some migratory birds travel as far north as the Arctic in summer.","zh":"有些候鳥夏天會北至北極地區。"},{"en":"If a plant grows as far north as Scotland, it can survive relatively cool conditions.","zh":"如果一種植物北至蘇格蘭也能生長，它就能在相對寒冷的環境中生存。"},{"en":"This phrase helps show the outer limit of a northern range.","zh":"這個片語有助表示某個北方分布範圍的外限。"}],"source":"160 - Coral reefs.pdf","sourcePage":5},{"front":"be rare along","meaning":"在……沿岸罕見","examples":[{"en":"Coral reefs are rare along the American and African west coasts.","zh":"珊瑚礁在美洲和非洲西岸沿岸罕見。"},{"en":"Be rare along means not often found beside or near a particular line, road, river, or coast.","zh":"be rare along 指在某條線、道路、河流或海岸旁邊不常見。"},{"en":"Large trees are rare along the busy road because there is little space for roots.","zh":"大樹在繁忙道路沿線罕見，因為根部空間很少。"},{"en":"Coral reefs may be rare along some coasts when water is too cold or unclear.","zh":"當水太冷或太混濁時，珊瑚礁可能在某些海岸沿岸罕見。"},{"en":"Rare along does not mean impossible there; it means uncommon.","zh":"rare along 並不表示那裡完全不可能有，只表示不常見。"}],"source":"160 - Coral reefs.pdf","sourcePage":5},{"front":"west coasts","meaning":"西岸","examples":[{"en":"Coral reefs are uncommon along some west coasts.","zh":"珊瑚礁在一些西岸並不常見。"},{"en":"West coasts are coastlines on the western side of a country, continent, or island.","zh":"西岸是一個國家、大陸或島嶼西側的海岸線。"},{"en":"The west coast of a country may have different weather from its east coast.","zh":"一個國家的西岸可能與東岸有不同天氣。"},{"en":"Cold currents along some west coasts can make coral growth difficult.","zh":"一些西岸沿岸的寒流可能令珊瑚生長困難。"},{"en":"When describing marine habitats, west coasts and east coasts may need separate discussion.","zh":"描述海洋棲息地時，西岸和東岸可能需要分開討論。"}],"source":"160 - Coral reefs.pdf","sourcePage":6},{"front":"due primarily to","meaning":"主要由於","examples":[{"en":"This is due primarily to upwelling and cold coastal currents.","zh":"這主要由於上升流和寒冷沿岸洋流。"},{"en":"Due primarily to means mainly caused by something.","zh":"due primarily to 指主要由某事造成。"},{"en":"The delay was due primarily to heavy rain and road closures.","zh":"延誤主要由於大雨和道路封閉。"},{"en":"If poor sales are due primarily to high prices, lowering prices may help.","zh":"如果銷售差主要由於價格高，降低價格可能有幫助。"},{"en":"This phrase points to the main reason, not every possible reason.","zh":"這個片語指出主要原因，而不是所有可能原因。"}],"source":"160 - Coral reefs.pdf","sourcePage":6},{"front":"upwelling","meaning":"上升流","examples":[{"en":"Upwelling can reduce water temperatures near coasts.","zh":"上升流可以降低海岸附近的水溫。"},{"en":"Upwelling is the movement of deeper, colder water up towards the ocean surface.","zh":"上升流是較深、較冷的海水向海洋表面移動的現象。"},{"en":"Fishermen may benefit from upwelling because it can bring nutrients to surface waters.","zh":"漁民可能從上升流受惠，因為它可以把營養物帶到表層水域。"},{"en":"Upwelling can make some coastal areas too cold for warm-water corals.","zh":"上升流可以令一些沿岸地區對暖水珊瑚而言太冷。"},{"en":"Although upwelling can support fish, it may limit coral reef growth in certain places.","zh":"雖然上升流可以支持魚類，但它可能限制某些地方的珊瑚礁生長。"}],"source":"160 - Coral reefs.pdf","sourcePage":6},{"front":"coastal currents","meaning":"沿岸洋流","examples":[{"en":"Strong cold coastal currents reduce water temperatures.","zh":"強勁寒冷的沿岸洋流會降低水溫。"},{"en":"Coastal currents are moving flows of seawater that travel along coastlines.","zh":"沿岸洋流是沿海岸線流動的海水。"},{"en":"Swimmers should be careful when coastal currents are strong.","zh":"當沿岸洋流強勁時，游泳者應該小心。"},{"en":"Cold coastal currents can change local sea temperatures and affect marine life.","zh":"寒冷沿岸洋流可以改變本地海水溫度並影響海洋生命。"},{"en":"Coastal currents help explain why nearby coastlines may have different ecosystems.","zh":"沿岸洋流有助解釋為何相近海岸線可能有不同生態系統。"}],"source":"160 - Coral reefs.pdf","sourcePage":6},{"front":"reduce water temperatures","meaning":"降低水溫","examples":[{"en":"Cold currents reduce water temperatures in some coastal areas.","zh":"寒流會降低一些沿岸地區的水溫。"},{"en":"Reduce water temperatures means make the water colder.","zh":"reduce water temperatures 指使水變得更冷。"},{"en":"Shade from trees can reduce water temperatures in a small stream.","zh":"樹蔭可以降低小溪的水溫。"},{"en":"If currents reduce water temperatures too much, warm-water species may move away.","zh":"如果洋流過度降低水溫，暖水物種可能會離開。"},{"en":"Reducing water temperatures can benefit some animals but harm others.","zh":"降低水溫可能有利於某些動物，但傷害其他動物。"}],"source":"160 - Coral reefs.pdf","sourcePage":6},{"front":"respectively","meaning":"分別地","examples":[{"en":"The Peru, Benguela and Canary streams affect these areas respectively.","zh":"秘魯、班吉拉和加那利洋流分別影響這些地區。"},{"en":"Respectively means in the same order as the things already mentioned.","zh":"respectively 指按照前面提及事物的相同順序分別對應。"},{"en":"Tom, Anna, and Mei scored 80, 85, and 90 respectively.","zh":"Tom、Anna 和 Mei 分別取得80、85和90分。"},{"en":"If Monday, Tuesday, and Wednesday are assigned to reading, writing, and speaking respectively, each activity matches that order.","zh":"如果星期一、星期二和星期三分別安排閱讀、寫作和口語，每項活動就按那個順序對應。"},{"en":"This word prevents confusion when several items are matched with several details.","zh":"當多個項目要配對多個細節時，這個詞可以避免混淆。"}],"source":"160 - Coral reefs.pdf","sourcePage":6},{"front":"be seldom found","meaning":"很少被發現","examples":[{"en":"Corals are seldom found along the coastline of South Asia.","zh":"珊瑚很少在南亞海岸線沿岸被發現。"},{"en":"Be seldom found means rarely seen or discovered in a particular place.","zh":"be seldom found 指在某地方很少被看見或發現。"},{"en":"Snow is seldom found in very hot lowland cities.","zh":"雪很少在炎熱的低地城市被發現。"},{"en":"If a species is seldom found in an area, scientists may ask what conditions are missing.","zh":"如果某物種很少在某區被發現，科學家可能會研究缺少甚麼條件。"},{"en":"Seldom found is softer than saying something never exists there.","zh":"seldom found 比說某物絕不存在於那裡更溫和。"}],"source":"160 - Coral reefs.pdf","sourcePage":6},{"front":"coastline of","meaning":"……的海岸線","examples":[{"en":"Corals are seldom found along the coastline of South Asia.","zh":"珊瑚很少在南亞的海岸線沿岸被發現。"},{"en":"The coastline of a place is the land edge where it meets the sea.","zh":"某地的海岸線是該地陸地與海洋相接的邊緣。"},{"en":"The coastline of an island may include beaches, cliffs, ports, and villages.","zh":"一個島嶼的海岸線可能包括海灘、懸崖、港口和村莊。"},{"en":"Storms can damage the coastline of low-lying areas.","zh":"風暴可以破壞低窪地區的海岸線。"},{"en":"The phrase coastline of helps identify which coastal area is being discussed.","zh":"coastline of 這個片語有助指出正在討論哪個沿岸地區。"}],"source":"160 - Coral reefs.pdf","sourcePage":6},{"front":"eastern tip of","meaning":"……的東端","examples":[{"en":"Corals are rare from the eastern tip of India to nearby borders.","zh":"從印度東端到附近邊界，珊瑚都很罕見。"},{"en":"The eastern tip of a place is its farthest point towards the east.","zh":"某地的東端是該地最向東的部分。"},{"en":"The eastern tip of the island catches the sunrise first.","zh":"島嶼的東端最先看到日出。"},{"en":"If a storm reaches the eastern tip of a country, coastal villages there may be warned first.","zh":"如果風暴到達一個國家的東端，那裡的沿岸村莊可能最先收到警告。"},{"en":"This phrase is useful for describing an exact end of a region.","zh":"這個片語在描述一個地區的確切末端時很有用。"}],"source":"160 - Coral reefs.pdf","sourcePage":6},{"front":"due to freshwater released from","meaning":"由於……釋放的淡水","examples":[{"en":"Corals are rare there due to freshwater released from major rivers.","zh":"由於主要河流釋放的淡水，珊瑚在那裡很罕見。"},{"en":"Due to freshwater released from means caused by fresh water flowing out of a source into another area.","zh":"due to freshwater released from 指由某來源流出的淡水進入另一區域所造成。"},{"en":"Sea animals near a river mouth may be affected due to freshwater released from the river.","zh":"河口附近的海洋動物可能因河流釋放的淡水而受影響。"},{"en":"If too much freshwater is released from a dam, salinity in nearby waters can fall.","zh":"如果水壩釋放太多淡水，附近水域的鹽度可能下降。"},{"en":"This phrase explains how river water can change coastal conditions.","zh":"這個片語解釋河水如何改變沿岸環境。"}],"source":"160 - Coral reefs.pdf","sourcePage":6},{"front":"the Amazon and Ganges Rivers","meaning":"亞馬遜河和恆河","examples":[{"en":"The Amazon and Ganges Rivers release freshwater into nearby seas.","zh":"亞馬遜河和恆河會把淡水釋放到附近海域。"},{"en":"The Amazon and Ganges Rivers are major river systems that carry large amounts of freshwater.","zh":"亞馬遜河和恆河是大型河流系統，運載大量淡水。"},{"en":"Students often learn about the Amazon and Ganges Rivers when studying world geography.","zh":"學生在學習世界地理時常會認識亞馬遜河和恆河。"},{"en":"Freshwater from the Amazon and Ganges Rivers can influence coastal water conditions.","zh":"來自亞馬遜河和恆河的淡水可以影響沿岸水域環境。"},{"en":"These rivers show how land systems can affect the sea.","zh":"這些河流顯示陸地系統如何影響海洋。"}],"source":"160 - Coral reefs.pdf","sourcePage":7},{"front":"deliver ecosystem services","meaning":"提供生態系統服務","examples":[{"en":"Coral reefs deliver ecosystem services to tourism, fisheries and coastline protection.","zh":"珊瑚礁為旅遊、漁業和海岸線保護提供生態系統服務。"},{"en":"Deliver ecosystem services means provide natural benefits that people and communities depend on.","zh":"deliver ecosystem services 指提供人類和社區依賴的自然好處。"},{"en":"Wetlands deliver ecosystem services by filtering water and reducing floods.","zh":"濕地透過過濾水和減少洪水提供生態系統服務。"},{"en":"When reefs deliver ecosystem services, local economies can earn income and reduce risks.","zh":"當珊瑚礁提供生態系統服務，本地經濟可以獲得收入並減低風險。"},{"en":"Protecting nature often means protecting the services it quietly provides.","zh":"保護自然通常意味著保護它默默提供的服務。"}],"source":"160 - Coral reefs.pdf","sourcePage":7},{"front":"ecosystem services","meaning":"生態系統服務","examples":[{"en":"Coral reefs provide important ecosystem services.","zh":"珊瑚礁提供重要的生態系統服務。"},{"en":"Ecosystem services are benefits that nature provides to people, such as food, protection, clean water, or recreation.","zh":"生態系統服務是自然提供給人類的好處，例如食物、保護、清潔水源或休閒。"},{"en":"Trees provide ecosystem services by giving shade, storing carbon, and cooling streets.","zh":"樹木透過提供陰影、儲存碳和為街道降溫來提供生態系統服務。"},{"en":"If ecosystem services disappear, governments may need to spend money replacing them.","zh":"如果生態系統服務消失，政府可能需要花錢取代它們。"},{"en":"Coral reefs offer ecosystem services even when people do not notice them directly.","zh":"即使人們沒有直接注意到，珊瑚礁也提供生態系統服務。"}],"source":"160 - Coral reefs.pdf","sourcePage":7},{"front":"fisheries","meaning":"漁業","examples":[{"en":"Coral reefs support fisheries and tourism.","zh":"珊瑚礁支持漁業和旅遊業。"},{"en":"Fisheries are activities and industries connected with catching, raising, or selling fish.","zh":"漁業是與捕魚、養魚或售魚有關的活動和產業。"},{"en":"Coastal villages may depend on fisheries for food and income.","zh":"沿海村莊可能依賴漁業獲取食物和收入。"},{"en":"If fisheries are poorly managed, fish populations can decline quickly.","zh":"如果漁業管理不善，魚類種群可以迅速下降。"},{"en":"Healthy coral reefs can make fisheries more reliable for local people.","zh":"健康珊瑚礁可以令漁業對本地人更可靠。"}],"source":"160 - Coral reefs.pdf","sourcePage":7},{"front":"coastline protection","meaning":"海岸線保護","examples":[{"en":"Coral reefs contribute to coastline protection.","zh":"珊瑚礁有助於海岸線保護。"},{"en":"Coastline protection means reducing damage to coastal land from waves, storms, or erosion.","zh":"海岸線保護指減少海浪、風暴或侵蝕對沿岸土地的破壞。"},{"en":"Mangroves and reefs both help with coastline protection in some tropical areas.","zh":"在一些熱帶地區，紅樹林和珊瑚礁都幫助海岸線保護。"},{"en":"Without coastline protection, homes near the sea may face greater storm damage.","zh":"如果缺乏海岸線保護，海邊房屋可能面臨更大的風暴破壞。"},{"en":"Coral reefs protect coastlines naturally, while seawalls are human-built structures.","zh":"珊瑚礁自然保護海岸線，而海堤則是人造結構。"}],"source":"160 - Coral reefs.pdf","sourcePage":7},{"front":"global economic value","meaning":"全球經濟價值","examples":[{"en":"The global economic value of coral reefs is extremely high.","zh":"珊瑚礁的全球經濟價值極高。"},{"en":"Global economic value means the total money-related importance of something across the world.","zh":"全球經濟價值指某事物在世界各地與金錢相關的總體重要性。"},{"en":"The global economic value of clean oceans includes fishing, tourism, and storm protection.","zh":"清潔海洋的全球經濟價值包括漁業、旅遊和風暴保護。"},{"en":"If coral reefs decline, their global economic value may fall as tourism and fisheries suffer.","zh":"如果珊瑚礁衰退，旅遊和漁業受損，其全球經濟價值可能下降。"},{"en":"Economic value does not capture everything, but it helps people see why protection matters.","zh":"經濟價值不能反映所有東西，但它幫助人們明白保護為何重要。"}],"source":"160 - Coral reefs.pdf","sourcePage":7},{"front":"be estimated at as much as","meaning":"估計高達","examples":[{"en":"The value of coral reefs has been estimated at as much as US$375 billion per year.","zh":"珊瑚礁的價值估計高達每年3,750億美元。"},{"en":"Be estimated at as much as means experts think the value may reach a very high amount.","zh":"be estimated at as much as 指專家認為價值可能達到一個很高的數額。"},{"en":"The damage from the storm was estimated at as much as ten million dollars.","zh":"風暴造成的損失估計高達一千萬美元。"},{"en":"If costs are estimated at as much as this amount, planners must prepare a large budget.","zh":"如果成本估計高達這個數額，規劃者必須準備龐大預算。"},{"en":"This phrase suggests a high estimate, not an exact final number.","zh":"這個片語表示較高估算，而不是確切最終數字。"}],"source":"160 - Coral reefs.pdf","sourcePage":7},{"front":"per year","meaning":"每年","examples":[{"en":"Coral reefs may be worth hundreds of billions of dollars per year.","zh":"珊瑚礁每年可能價值數千億美元。"},{"en":"Per year means for each year or every year.","zh":"per year 指每一年或每年。"},{"en":"A gym membership may cost several thousand dollars per year.","zh":"健身會籍每年可能花費數千元。"},{"en":"If a farm produces 10 tonnes of fruit per year, that is its yearly output.","zh":"如果一個農場每年生產10噸水果，那就是它的年度產量。"},{"en":"Per year helps compare costs, income, or production over the same time period.","zh":"per year 有助用相同時間單位比較成本、收入或產量。"}],"source":"160 - Coral reefs.pdf","sourcePage":7},{"front":"protect shorelines","meaning":"保護海岸線","examples":[{"en":"Coral reefs protect shorelines by absorbing wave energy.","zh":"珊瑚礁透過吸收海浪能量來保護海岸線。"},{"en":"Protect shorelines means keep coastal land safer from waves, storms, and erosion.","zh":"protect shorelines 指令沿岸土地較少受到海浪、風暴和侵蝕傷害。"},{"en":"Mangroves protect shorelines by slowing water and holding soil in place.","zh":"紅樹林透過減慢水流和固定泥土來保護海岸線。"},{"en":"If reefs protect shorelines well, coastal villages may face less storm damage.","zh":"如果珊瑚礁有效保護海岸線，沿岸村莊可能較少受風暴破壞。"},{"en":"Natural systems can protect shorelines without needing concrete walls everywhere.","zh":"自然系統可以保護海岸線，而不需要到處建混凝土牆。"}],"source":"160 - Coral reefs.pdf","sourcePage":7},{"front":"absorb wave energy","meaning":"吸收海浪能量","examples":[{"en":"Reefs protect shorelines by absorbing wave energy.","zh":"珊瑚礁透過吸收海浪能量來保護海岸線。"},{"en":"Absorb wave energy means take in and reduce the force carried by waves.","zh":"absorb wave energy 指吸收並減少海浪所帶來的力量。"},{"en":"A breakwater can absorb wave energy before waves hit a harbour.","zh":"防波堤可以在海浪撞上海港前吸收海浪能量。"},{"en":"When reefs absorb wave energy, the water reaching the shore may be calmer.","zh":"當珊瑚礁吸收海浪能量，到達岸邊的水可能較平靜。"},{"en":"If reefs are destroyed, less wave energy is absorbed before storms reach land.","zh":"如果珊瑚礁被破壞，風暴到達陸地前被吸收的海浪能量就會減少。"}],"source":"160 - Coral reefs.pdf","sourcePage":7},{"front":"would not exist without","meaning":"沒有……便不會存在","examples":[{"en":"Many small islands would not exist without reefs to protect them.","zh":"許多小島如果沒有珊瑚礁保護，便不會存在。"},{"en":"Would not exist without means something depends so strongly on another thing that it could not be there without it.","zh":"would not exist without 指某物非常依賴另一物，沒有它便無法存在。"},{"en":"Some small businesses would not exist without loyal local customers.","zh":"有些小企業沒有忠實本地顧客便不會存在。"},{"en":"If a beach would not exist without natural protection, damaging that protection is risky.","zh":"如果一個海灘沒有自然保護便不會存在，破壞那種保護就很危險。"},{"en":"This phrase shows that one thing is essential for another thing’s survival.","zh":"這個片語顯示某事物對另一事物的生存至關重要。"}],"source":"160 - Coral reefs.pdf","sourcePage":8},{"front":"the value of reefs","meaning":"珊瑚礁的價值","examples":[{"en":"The value of reefs can be even higher in biodiverse regions.","zh":"在生物多樣性豐富的地區，珊瑚礁的價值可能更高。"},{"en":"The value of reefs means the benefits reefs provide, including economic, environmental, and social benefits.","zh":"珊瑚礁的價值指珊瑚礁提供的好處，包括經濟、環境和社會好處。"},{"en":"A local guide may understand the value of reefs because tourism supports his family.","zh":"本地導遊可能明白珊瑚礁的價值，因為旅遊支持他的家庭。"},{"en":"If fish populations decline, the value of reefs to local fishers may become clearer.","zh":"如果魚類數量下降，珊瑚礁對本地漁民的價值可能變得更清楚。"},{"en":"The value of reefs is not only money; it also includes protection and biodiversity.","zh":"珊瑚礁的價值不只是金錢，也包括保護和生物多樣性。"}],"source":"160 - Coral reefs.pdf","sourcePage":8},{"front":"biodiverse regions","meaning":"生物多樣性豐富的地區","examples":[{"en":"Reefs in biodiverse regions may be especially valuable.","zh":"生物多樣性豐富地區的珊瑚礁可能尤其有價值。"},{"en":"Biodiverse regions are areas with many different kinds of living things.","zh":"生物多樣性豐富的地區是有許多不同生物種類的區域。"},{"en":"A rainforest is a biodiverse region because it contains many plants, animals, and insects.","zh":"雨林是生物多樣性豐富的地區，因為它含有許多植物、動物和昆蟲。"},{"en":"Biodiverse regions can attract scientists and tourists because they contain unusual species.","zh":"生物多樣性豐富的地區可以吸引科學家和遊客，因為那裡有不尋常物種。"},{"en":"Protecting biodiverse regions helps preserve life that may not exist elsewhere.","zh":"保護生物多樣性豐富的地區有助保存其他地方可能不存在的生命。"}],"source":"160 - Coral reefs.pdf","sourcePage":8},{"front":"be worth","meaning":"價值為","examples":[{"en":"Some reefs are estimated to be worth US$1 million per square kilometre.","zh":"有些珊瑚礁估計每平方公里價值為100萬美元。"},{"en":"Be worth means to have a particular value in money, usefulness, or importance.","zh":"be worth 指在金錢、用途或重要性上具有某種價值。"},{"en":"A second-hand phone may be worth less than a new one.","zh":"二手手機的價值可能低於新手機。"},{"en":"A training course can be worth the time if it helps people get better jobs.","zh":"如果培訓課程幫助人們找到更好的工作，它就值得花時間。"},{"en":"Something can be worth a lot even if its value is not only financial.","zh":"某物可以很有價值，即使它的價值不只是金錢上的。"}],"source":"160 - Coral reefs.pdf","sourcePage":8},{"front":"per square kilometer","meaning":"每平方公里","examples":[{"en":"Some reefs are worth US$1 million per square kilometer.","zh":"有些珊瑚礁每平方公里價值100萬美元。"},{"en":"Per square kilometer means for each area measuring one kilometre by one kilometre.","zh":"per square kilometer 指每一個一公里乘一公里的面積單位。"},{"en":"Population density is often measured as people per square kilometer.","zh":"人口密度常以每平方公里多少人來量度。"},{"en":"If a forest stores more carbon per square kilometer, each unit of land is highly valuable.","zh":"如果森林每平方公里儲存更多碳，每個土地單位就非常有價值。"},{"en":"This phrase helps compare places of different sizes fairly.","zh":"這個片語有助公平比較不同大小的地方。"}],"source":"160 - Coral reefs.pdf","sourcePage":8},{"front":"be based on","meaning":"基於","examples":[{"en":"The estimate is based on beach maintenance and tourism value.","zh":"這項估算基於沙灘維護和旅遊價值。"},{"en":"Be based on means to use something as the reason, evidence, or foundation for a judgement.","zh":"be based on 指以某事作為判斷的原因、證據或基礎。"},{"en":"A teacher’s advice should be based on a student’s real needs.","zh":"老師的建議應基於學生的實際需要。"},{"en":"If a decision is based on weak data, it may lead to poor results.","zh":"如果決定基於薄弱數據，可能導致差劣結果。"},{"en":"This phrase helps explain where an idea or number comes from.","zh":"這個片語有助解釋一個想法或數字來自何處。"}],"source":"160 - Coral reefs.pdf","sourcePage":8},{"front":"the cost of maintaining","meaning":"維持……的成本","examples":[{"en":"The value is based partly on the cost of maintaining sandy beaches.","zh":"這項價值部分基於維持沙灘的成本。"},{"en":"The cost of maintaining something is the money needed to keep it in good condition.","zh":"the cost of maintaining something 指令某物保持良好狀態所需的金錢。"},{"en":"The cost of maintaining an old car may become higher than buying a newer one.","zh":"維持一輛舊車的成本可能變得高於購買一輛較新的車。"},{"en":"If the cost of maintaining a park rises, the city may need a larger budget.","zh":"如果維持公園的成本上升，城市可能需要更大預算。"},{"en":"Natural reefs can reduce the cost of maintaining beaches by protecting them from waves.","zh":"天然珊瑚礁可以透過保護海灘免受海浪影響，降低維持海灘的成本。"}],"source":"160 - Coral reefs.pdf","sourcePage":8},{"front":"sandy beaches","meaning":"沙灘","examples":[{"en":"Coral reefs help maintain sandy beaches.","zh":"珊瑚礁有助維持沙灘。"},{"en":"Sandy beaches are coastal areas covered mainly with sand.","zh":"沙灘是主要由沙覆蓋的沿岸地區。"},{"en":"Families often visit sandy beaches to swim, rest, and play.","zh":"家庭常到沙灘游泳、休息和玩耍。"},{"en":"If waves remove too much sand, sandy beaches can become narrower.","zh":"如果海浪帶走太多沙，沙灘可能變窄。"},{"en":"Coral reefs can help protect sandy beaches by reducing wave force.","zh":"珊瑚礁可以透過減少海浪力量來幫助保護沙灘。"}],"source":"160 - Coral reefs.pdf","sourcePage":8},{"front":"the value of attracting","meaning":"吸引……的價值","examples":[{"en":"The estimate includes the value of attracting snorkelers and scuba divers.","zh":"這項估算包括吸引浮潛人士和水肺潛水員的價值。"},{"en":"The value of attracting people means the benefit gained because people want to visit, buy, or participate.","zh":"the value of attracting people 指因人們想參觀、購買或參與而產生的好處。"},{"en":"A museum considers the value of attracting school groups when planning exhibitions.","zh":"博物館在規劃展覽時會考慮吸引學生團體的價值。"},{"en":"If a beach attracts more visitors, the value of attracting tourists can support local shops.","zh":"如果海灘吸引更多遊客，吸引旅客的價值可以支持本地商店。"},{"en":"This phrase is useful when visitor interest creates economic benefit.","zh":"當訪客興趣創造經濟好處時，這個片語很有用。"}],"source":"160 - Coral reefs.pdf","sourcePage":8},{"front":"snorkelers and scuba divers","meaning":"浮潛人士和水肺潛水員","examples":[{"en":"Coral reefs attract snorkelers and scuba divers.","zh":"珊瑚礁吸引浮潛人士和水肺潛水員。"},{"en":"Snorkelers and scuba divers are people who explore underwater environments using different breathing equipment.","zh":"浮潛人士和水肺潛水員是使用不同呼吸設備探索水底環境的人。"},{"en":"Snorkelers stay near the surface, while scuba divers can go deeper with air tanks.","zh":"浮潛人士留在水面附近，而水肺潛水員可帶氣瓶潛得更深。"},{"en":"If reefs are healthy, snorkelers and scuba divers may spend money on tours and equipment.","zh":"如果珊瑚礁健康，浮潛人士和水肺潛水員可能會在旅遊和裝備上消費。"},{"en":"Careless snorkelers and scuba divers can damage coral if they touch or kick it.","zh":"不小心的浮潛人士和水肺潛水員如果觸碰或踢到珊瑚，可能會造成破壞。"}],"source":"160 - Coral reefs.pdf","sourcePage":8},{"front":"the Great Barrier Reef","meaning":"大堡礁","examples":[{"en":"The Great Barrier Reef is worth more as an intact ecosystem.","zh":"大堡礁作為完整生態系統時價值更高。"},{"en":"The Great Barrier Reef is a famous large coral reef system off the coast of Australia.","zh":"大堡礁是澳洲海岸外著名的大型珊瑚礁系統。"},{"en":"Tourists visit the Great Barrier Reef to see coral, fish, turtles, and clear water.","zh":"遊客到訪大堡礁，是為了看珊瑚、魚、海龜和清澈海水。"},{"en":"If the Great Barrier Reef is damaged, both biodiversity and tourism may suffer.","zh":"如果大堡礁受損，生物多樣性和旅遊業都可能受害。"},{"en":"The Great Barrier Reef is often used as an example of why reef protection matters.","zh":"大堡礁常被用作例子，說明珊瑚礁保護為何重要。"}],"source":"160 - Coral reefs.pdf","sourcePage":9},{"front":"intact ecosystem","meaning":"完整生態系統","examples":[{"en":"The reef is worth more as an intact ecosystem than as a fishing reserve.","zh":"這個珊瑚礁作為完整生態系統時，比作為漁業保留區更有價值。"},{"en":"An intact ecosystem is a natural system that remains whole and functions properly.","zh":"完整生態系統是保持整體並正常運作的自然系統。"},{"en":"An intact forest ecosystem includes trees, soil, insects, birds, and water cycles working together.","zh":"完整森林生態系統包括樹木、土壤、昆蟲、鳥類和水循環一起運作。"},{"en":"If an intact ecosystem is broken into small damaged parts, many species may decline.","zh":"如果完整生態系統被破壞成細小受損部分，許多物種可能下降。"},{"en":"Keeping a reef as an intact ecosystem can protect more benefits than using it only for fishing.","zh":"把珊瑚礁保持為完整生態系統，可以保護比只用作捕魚更多的好處。"}],"source":"160 - Coral reefs.pdf","sourcePage":9},{"front":"extractive reserve","meaning":"採捕資源保留區","examples":[{"en":"The reef is worth more as an ecosystem than as an extractive reserve.","zh":"這個珊瑚礁作為生態系統時，比作為採捕資源保留區更有價值。"},{"en":"An extractive reserve is an area where natural resources are taken out for use or sale.","zh":"採捕資源保留區是可取出自然資源供使用或出售的地區。"},{"en":"A forest extractive reserve may allow people to collect rubber, nuts, or timber under rules.","zh":"森林採捕資源保留區可能在規則下容許人們採集橡膠、堅果或木材。"},{"en":"If a reef is treated only as an extractive reserve, its wider ecological value may be ignored.","zh":"如果珊瑚礁只被視為採捕資源保留區，其更廣泛生態價值可能被忽視。"},{"en":"Some areas are worth more when protected than when used mainly for extraction.","zh":"有些地區在受保護時，比主要用作採取資源時更有價值。"}],"source":"160 - Coral reefs.pdf","sourcePage":9},{"front":"reef-related industries","meaning":"與珊瑚礁相關的產業","examples":[{"en":"Tourists spend billions on reef-related industries.","zh":"遊客在與珊瑚礁相關的產業上花費數十億。"},{"en":"Reef-related industries are businesses connected to coral reefs, such as diving tours, boats, hotels, and equipment rental.","zh":"與珊瑚礁相關的產業是與珊瑚礁有關的生意，例如潛水團、船隻、酒店和器材租借。"},{"en":"A coastal town may depend on reef-related industries for jobs.","zh":"沿海城鎮可能依賴與珊瑚礁相關的產業提供就業。"},{"en":"If reefs decline, reef-related industries may lose customers and income.","zh":"如果珊瑚礁衰退，與珊瑚礁相關的產業可能失去顧客和收入。"},{"en":"Healthy reefs can support reef-related industries without being consumed directly.","zh":"健康珊瑚礁可以支持與珊瑚礁相關的產業，而不需要被直接消耗。"}],"source":"160 - Coral reefs.pdf","sourcePage":9},{"front":"boat rental","meaning":"租船","examples":[{"en":"Reef tourism includes diving, boat rental and resort stays.","zh":"珊瑚礁旅遊包括潛水、租船和度假村住宿。"},{"en":"Boat rental is the service of paying to use a boat for a period of time.","zh":"租船是付費在一段時間內使用船隻的服務。"},{"en":"A family may use boat rental to visit a nearby island for one afternoon.","zh":"一個家庭可能租船，在下午到附近島嶼遊玩。"},{"en":"Boat rental businesses can earn more when tourists visit coral reefs.","zh":"當遊客到訪珊瑚礁時，租船業務可以賺取更多收入。"},{"en":"Boat rental must be managed carefully so boats do not damage reefs.","zh":"租船必須小心管理，以免船隻破壞珊瑚礁。"}],"source":"160 - Coral reefs.pdf","sourcePage":9},{"front":"posh island resort stays","meaning":"高級海島度假村住宿","examples":[{"en":"Tourists spend money on posh island resort stays.","zh":"遊客會在高級海島度假村住宿上花錢。"},{"en":"Posh island resort stays are expensive and comfortable holidays at luxury resorts on islands.","zh":"高級海島度假村住宿是指在島上豪華度假村享受昂貴舒適假期。"},{"en":"Couples may choose posh island resort stays for honeymoons or special celebrations.","zh":"夫妻可能為蜜月或特別慶祝選擇高級海島度假村住宿。"},{"en":"Posh island resort stays can bring income, but they may also increase pressure on local environments.","zh":"高級海島度假村住宿可以帶來收入，但也可能增加本地環境壓力。"},{"en":"This phrase sounds informal because posh means stylish, expensive, and upper-class.","zh":"這個片語語氣較口語，因為 posh 指時尚、昂貴和上流。"}],"source":"160 - Coral reefs.pdf","sourcePage":9},{"front":"net annual benefits","meaning":"每年淨收益","examples":[{"en":"The Caribbean receives net annual benefits from diver tourism.","zh":"加勒比海從潛水旅遊中獲得每年淨收益。"},{"en":"Net annual benefits are the gains left over each year after costs are subtracted.","zh":"每年淨收益是扣除成本後每年剩下的收益。"},{"en":"A small shop calculates net annual benefits by comparing yearly income with yearly expenses.","zh":"小店透過比較年度收入和年度支出計算每年淨收益。"},{"en":"If tourism creates high income but also high costs, net annual benefits may be smaller than expected.","zh":"如果旅遊創造高收入但也帶來高成本，每年淨收益可能低於預期。"},{"en":"This phrase helps measure the real yearly gain, not just total income.","zh":"這個片語幫助量度真正的年度收益，而不只是總收入。"}],"source":"160 - Coral reefs.pdf","sourcePage":9},{"front":"diver tourism","meaning":"潛水旅遊","examples":[{"en":"Diver tourism brings major economic benefits to the Caribbean.","zh":"潛水旅遊為加勒比海帶來重大經濟利益。"},{"en":"Diver tourism is travel in which people visit places mainly to scuba dive or explore underwater sites.","zh":"潛水旅遊是人們主要為水肺潛水或探索水底景點而旅行。"},{"en":"A coastal town may build dive centres to attract diver tourism.","zh":"沿海城鎮可能建設潛水中心來吸引潛水旅遊。"},{"en":"If reefs are healthy, diver tourism can create jobs for guides, boat operators, and hotels.","zh":"如果珊瑚礁健康，潛水旅遊可以為導遊、船主和酒店創造工作。"},{"en":"Diver tourism must be controlled so visitors do not damage the reefs they come to see.","zh":"潛水旅遊必須受控制，以免遊客破壞他們前來觀賞的珊瑚礁。"}],"source":"160 - Coral reefs.pdf","sourcePage":9},{"front":"spent directly on","meaning":"直接花費於","examples":[{"en":"Large sums are spent directly on diving on reefs.","zh":"大筆款項直接花費於珊瑚礁潛水。"},{"en":"Spent directly on means money is paid specifically for that activity, product, or service.","zh":"spent directly on 指金錢專門花在某項活動、產品或服務上。"},{"en":"Parents may spend money directly on tutoring instead of general school supplies.","zh":"家長可能直接花錢於補習，而不是一般學校用品。"},{"en":"If tourists spend directly on local guides, the community receives clearer benefits.","zh":"如果遊客直接花費於本地導遊，社區會得到更明顯好處。"},{"en":"This phrase separates direct spending from wider indirect spending.","zh":"這個片語把直接開支與更廣泛的間接開支分開。"}],"source":"160 - Coral reefs.pdf","sourcePage":9},{"front":"an important source of employment","meaning":"重要就業來源","examples":[{"en":"Reef tourism is an important source of employment.","zh":"珊瑚礁旅遊是一個重要就業來源。"},{"en":"An important source of employment is something that creates many jobs for people.","zh":"重要就業來源是指為人們創造許多工作的事物。"},{"en":"A hospital can be an important source of employment in a small town.","zh":"醫院可以是小鎮的重要就業來源。"},{"en":"If reef tourism declines, an important source of employment may disappear for coastal communities.","zh":"如果珊瑚礁旅遊衰退，沿海社區可能失去一個重要就業來源。"},{"en":"This phrase is often used when an industry supports many families.","zh":"當某個產業支持許多家庭時，常會使用這個片語。"}],"source":"160 - Coral reefs.pdf","sourcePage":9},{"front":"especially for","meaning":"尤其對……","examples":[{"en":"Reef tourism is important especially for some of the world’s poorest people.","zh":"珊瑚礁旅遊很重要，尤其對世界上一些最貧窮的人而言。"},{"en":"Especially for means particularly important to a certain person, group, or situation.","zh":"especially for 指對某人、某群體或某情況特別重要。"},{"en":"Public libraries are useful especially for students who cannot buy many books.","zh":"公共圖書館很有用，尤其對買不起許多書的學生而言。"},{"en":"Clean water is vital especially for children, older people, and patients.","zh":"清潔食水很重要，尤其對兒童、長者和病人而言。"},{"en":"This phrase narrows a general statement to the group most affected.","zh":"這個片語把一般陳述收窄到最受影響的群體。"}],"source":"160 - Coral reefs.pdf","sourcePage":10},{"front":"small-scale fishers","meaning":"小規模漁民","examples":[{"en":"Many small-scale fishers depend on coral reefs.","zh":"許多小規模漁民依賴珊瑚礁。"},{"en":"Small-scale fishers are people who catch fish in limited amounts, often using small boats and simple equipment.","zh":"小規模漁民是以有限數量捕魚的人，通常使用小船和簡單設備。"},{"en":"A small-scale fisher may sell the morning catch at a local market.","zh":"小規模漁民可能在本地市場出售早上的漁獲。"},{"en":"If fish stocks fall, small-scale fishers may lose income quickly.","zh":"如果魚類資源下降，小規模漁民可能很快失去收入。"},{"en":"Small-scale fishers often depend more directly on local ecosystems than large fishing companies do.","zh":"小規模漁民通常比大型漁業公司更直接依賴本地生態系統。"}],"source":"160 - Coral reefs.pdf","sourcePage":10},{"front":"the developing world","meaning":"發展中國家","examples":[{"en":"Many small-scale fishers in the developing world depend on reefs.","zh":"發展中國家的許多小規模漁民依賴珊瑚礁。"},{"en":"The developing world refers to countries or regions with lower average income and fewer economic resources.","zh":"the developing world 指平均收入較低、經濟資源較少的國家或地區。"},{"en":"Some communities in the developing world rely on local farms, fisheries, and small businesses.","zh":"發展中國家的一些社區依賴本地農場、漁業和小型企業。"},{"en":"Environmental damage can hit the developing world hard because many people depend directly on nature.","zh":"環境破壞可能嚴重打擊發展中國家，因為許多人直接依賴自然。"},{"en":"This phrase is broad, so writers should use it carefully and avoid stereotypes.","zh":"這個片語範圍很廣，因此寫作者應謹慎使用並避免刻板印象。"}],"source":"160 - Coral reefs.pdf","sourcePage":10},{"front":"be dependent to a greater or lesser extent on","meaning":"或多或少依賴……","examples":[{"en":"Most small-scale fishers are dependent to a greater or lesser extent on coral reefs.","zh":"大多數小規模漁民都或多或少依賴珊瑚礁。"},{"en":"Be dependent to a greater or lesser extent on means rely on something, though the level of reliance may vary.","zh":"be dependent to a greater or lesser extent on 指依賴某物，但依賴程度可能不同。"},{"en":"Many students are dependent to a greater or lesser extent on family support.","zh":"許多學生都或多或少依賴家庭支持。"},{"en":"If a town is dependent to a greater or lesser extent on tourism, a travel ban will affect it.","zh":"如果一個城鎮或多或少依賴旅遊，旅遊禁令就會影響它。"},{"en":"This phrase is useful when dependence exists but is not the same for everyone.","zh":"當依賴存在但每個人的程度不相同時，這個片語很有用。"}],"source":"160 - Coral reefs.pdf","sourcePage":10},{"front":"depend directly on","meaning":"直接依賴","examples":[{"en":"More than one million fishers in the Philippines depend directly on coral reefs.","zh":"菲律賓有超過一百萬名漁民直接依賴珊瑚礁。"},{"en":"Depend directly on means rely on something in an immediate and clear way.","zh":"depend directly on 指以直接而明確的方式依賴某物。"},{"en":"A street seller may depend directly on daily customers for income.","zh":"街頭小販可能直接依賴每日顧客獲取收入。"},{"en":"If farmers depend directly on rain, drought can quickly threaten their harvest.","zh":"如果農民直接依賴雨水，乾旱可以很快威脅收成。"},{"en":"People who depend directly on reefs feel the effects of reef decline very quickly.","zh":"直接依賴珊瑚礁的人，會很快感受到珊瑚礁衰退的影響。"}],"source":"160 - Coral reefs.pdf","sourcePage":10},{"front":"livelihoods","meaning":"生計","examples":[{"en":"Many fishers depend on coral reefs for their livelihoods.","zh":"許多漁民依靠珊瑚礁維持生計。"},{"en":"Livelihoods are the ways people earn money or obtain what they need to live.","zh":"生計是人們賺錢或取得生活所需的方式。"},{"en":"A farmer’s livelihood may depend on good weather and healthy soil.","zh":"農民的生計可能依賴良好天氣和健康土壤。"},{"en":"When a factory closes, many workers may lose their livelihoods.","zh":"當工廠關閉，許多工人可能失去生計。"},{"en":"Protecting reefs can also mean protecting the livelihoods of coastal families.","zh":"保護珊瑚礁也可能意味著保護沿海家庭的生計。"}],"source":"160 - Coral reefs.pdf","sourcePage":10},{"front":"reef fisheries","meaning":"珊瑚礁漁業","examples":[{"en":"Reef fisheries are worth large sums per square kilometre each year.","zh":"珊瑚礁漁業每平方公里每年價值龐大。"},{"en":"Reef fisheries are fishing activities that depend on fish and other animals living around coral reefs.","zh":"珊瑚礁漁業是依賴生活在珊瑚礁周圍的魚類和其他動物的捕魚活動。"},{"en":"A village may rely on reef fisheries for both food and income.","zh":"一個村莊可能依賴珊瑚礁漁業獲取食物和收入。"},{"en":"If reef fisheries are overused, fish populations may not recover.","zh":"如果珊瑚礁漁業被過度使用，魚類種群可能無法恢復。"},{"en":"Reef fisheries can be valuable, but they need careful management.","zh":"珊瑚礁漁業可以很有價值，但需要小心管理。"}],"source":"160 - Coral reefs.pdf","sourcePage":10},{"front":"fish caught for aquariums","meaning":"供水族箱飼養的魚","examples":[{"en":"Fish caught for aquariums can be worth much more than food fish.","zh":"供水族箱飼養的魚可能比食用魚價值高得多。"},{"en":"Fish caught for aquariums are live fish taken from the wild to be kept in display tanks.","zh":"供水族箱飼養的魚是從野外捕捉、用於展示魚缸中的活魚。"},{"en":"Some colourful reef fish caught for aquariums are sold to collectors.","zh":"一些供水族箱飼養的彩色珊瑚礁魚會售予收藏者。"},{"en":"If fish caught for aquariums are taken unsustainably, reef ecosystems may suffer.","zh":"如果供水族箱飼養的魚以不可持續方式捕捉，珊瑚礁生態系統可能受害。"},{"en":"These fish are valued for appearance, not mainly for eating.","zh":"這些魚的價值在於外觀，而主要不是食用。"}],"source":"160 - Coral reefs.pdf","sourcePage":10},{"front":"against","meaning":"相比之下","examples":[{"en":"Aquarium fish were worth $500 a kilogram against $6 for food fish.","zh":"觀賞魚每公斤價值500美元，相比之下食用魚為6美元。"},{"en":"Against can be used to compare one figure with another contrasting figure.","zh":"against 可用來把一個數字與另一個形成對比的數字比較。"},{"en":"The school scored 90% in reading against 70% in writing.","zh":"這所學校閱讀得分90%，相比之下寫作得分70%。"},{"en":"If rent is $2,000 against a salary of $3,000, housing costs are extremely high.","zh":"如果租金是2,000美元，相比之下薪金是3,000美元，住房成本就極高。"},{"en":"In this use, against means compared with, not opposed to.","zh":"在這種用法中，against 指相比之下，不是反對。"}],"source":"160 - Coral reefs.pdf","sourcePage":10},{"front":"aquarium fish export industry","meaning":"觀賞魚出口業","examples":[{"en":"The aquarium fish export industry supports thousands of people.","zh":"觀賞魚出口業支持數以千計的人。"},{"en":"The aquarium fish export industry is the business of catching, selling, and sending live display fish to other countries.","zh":"觀賞魚出口業是捕捉、出售並把活展示魚運往其他國家的生意。"},{"en":"Workers in the aquarium fish export industry may catch fish, pack them, or arrange shipping.","zh":"觀賞魚出口業的工人可能負責捕魚、包裝或安排運輸。"},{"en":"If this industry uses harmful methods, reefs and fish populations may be damaged.","zh":"如果這個行業使用有害方法，珊瑚礁和魚類種群可能受損。"},{"en":"A responsible aquarium fish export industry should protect both income and marine life.","zh":"負責任的觀賞魚出口業應同時保護收入和海洋生命。"}],"source":"160 - Coral reefs.pdf","sourcePage":10},{"front":"support around","meaning":"支持約……","examples":[{"en":"The industry supports around 50,000 people in Sri Lanka.","zh":"該行業在斯里蘭卡支持約50,000人。"},{"en":"Support around means provide income or jobs for approximately that number of people.","zh":"support around 指為大約某個數量的人提供收入或工作。"},{"en":"The factory supports around 300 families in the town.","zh":"這間工廠支持鎮上約300個家庭。"},{"en":"If a market supports around 200 small sellers, closing it would affect many households.","zh":"如果一個市場支持約200名小販，關閉它會影響許多家庭。"},{"en":"Around shows the number is approximate, not exact.","zh":"around 顯示數字是大約，而不是精確。"}],"source":"160 - Coral reefs.pdf","sourcePage":11},{"front":"generate","meaning":"產生；帶來","examples":[{"en":"The aquarium fish export industry generates millions of dollars a year.","zh":"觀賞魚出口業每年帶來數百萬美元。"},{"en":"Generate means to produce or create something, especially income, energy, or results.","zh":"generate 指產生或創造某物，尤其是收入、能源或結果。"},{"en":"A busy restaurant can generate high income during holidays.","zh":"繁忙餐廳可以在假期產生高收入。"},{"en":"Solar panels generate electricity from sunlight.","zh":"太陽能板從陽光產生電力。"},{"en":"An industry can generate money, but it may also generate environmental pressure.","zh":"一個行業可以帶來金錢，但也可能產生環境壓力。"}],"source":"160 - Coral reefs.pdf","sourcePage":11},{"front":"dying around the world","meaning":"在世界各地死亡","examples":[{"en":"Coral reefs are dying around the world.","zh":"珊瑚礁正在世界各地死亡。"},{"en":"Dying around the world means declining or disappearing in many countries and regions.","zh":"dying around the world 指在許多國家和地區衰退或消失。"},{"en":"Some languages are dying around the world because fewer children learn them.","zh":"有些語言正在世界各地消亡，因為學習它們的孩子越來越少。"},{"en":"If reefs are dying around the world, the problem is global rather than local.","zh":"如果珊瑚礁正在世界各地死亡，問題就是全球性而非地方性。"},{"en":"This phrase signals a widespread and serious decline.","zh":"這個片語表示廣泛而嚴重的衰退。"}],"source":"160 - Coral reefs.pdf","sourcePage":11},{"front":"in particular","meaning":"尤其是","examples":[{"en":"In particular, mining and pollution threaten coral reefs.","zh":"尤其是，開採和污染威脅珊瑚礁。"},{"en":"In particular means especially or more specifically than the other things mentioned.","zh":"in particular 指尤其是，或比其他提及事物更具體。"},{"en":"I enjoy science subjects, in particular biology.","zh":"我喜歡科學科目，尤其是生物。"},{"en":"If many problems exist, in particular helps point to the most important one.","zh":"如果存在許多問題，in particular 幫助指出最重要的一個。"},{"en":"This phrase narrows attention from a general topic to a specific example.","zh":"這個片語把注意力從一般主題收窄到具體例子。"}],"source":"160 - Coral reefs.pdf","sourcePage":11},{"front":"coral mining","meaning":"珊瑚開採","examples":[{"en":"Coral mining is one threat to coral ecosystems.","zh":"珊瑚開採是珊瑚生態系統面臨的威脅之一。"},{"en":"Coral mining is the removal of coral from reefs for building materials, decoration, or other uses.","zh":"珊瑚開採是從珊瑚礁移除珊瑚，用作建築材料、裝飾或其他用途。"},{"en":"A community may ban coral mining to protect beaches and fish habitats.","zh":"社區可能禁止珊瑚開採，以保護海灘和魚類棲息地。"},{"en":"Coral mining can weaken reef structures and make coastlines more exposed to waves.","zh":"珊瑚開採可以削弱珊瑚礁結構，令海岸線更暴露於海浪之下。"},{"en":"Coral mining may bring short-term income but long-term environmental damage.","zh":"珊瑚開採可能帶來短期收入，但造成長期環境破壞。"}],"source":"160 - Coral reefs.pdf","sourcePage":11},{"front":"agricultural and urban runoff","meaning":"農業及城市徑流","examples":[{"en":"Agricultural and urban runoff can damage coral reefs.","zh":"農業及城市徑流可以破壞珊瑚礁。"},{"en":"Agricultural and urban runoff is water that carries chemicals, soil, oil, or waste from farms and cities into rivers or seas.","zh":"農業及城市徑流是從農場和城市帶著化學物、泥土、油污或廢物流入河流或海洋的水。"},{"en":"After heavy rain, agricultural and urban runoff may flow into coastal waters.","zh":"大雨後，農業及城市徑流可能流入沿岸水域。"},{"en":"This runoff can cause pollution and encourage algal growth near reefs.","zh":"這些徑流可以造成污染，並促進珊瑚礁附近藻類生長。"},{"en":"Better farming and city drainage can reduce agricultural and urban runoff.","zh":"更好的農業做法和城市排水可以減少農業及城市徑流。"}],"source":"160 - Coral reefs.pdf","sourcePage":11},{"front":"organic and inorganic pollution","meaning":"有機及無機污染","examples":[{"en":"Organic and inorganic pollution threaten coral ecosystems.","zh":"有機及無機污染威脅珊瑚生態系統。"},{"en":"Organic and inorganic pollution includes waste from living sources and chemicals or materials from non-living sources.","zh":"有機及無機污染包括來自生物來源的廢物，以及來自非生物來源的化學物或材料。"},{"en":"Sewage is organic pollution, while heavy metals are inorganic pollution.","zh":"污水屬於有機污染，而重金屬屬於無機污染。"},{"en":"When organic and inorganic pollution enter the sea, reef animals may become stressed or die.","zh":"當有機及無機污染進入海洋，珊瑚礁動物可能受壓或死亡。"},{"en":"Understanding both types helps people identify different sources of damage.","zh":"理解兩種污染有助人們識別不同破壞來源。"}],"source":"160 - Coral reefs.pdf","sourcePage":11},{"front":"the digging of canals","meaning":"挖掘運河","examples":[{"en":"The digging of canals can threaten coral ecosystems.","zh":"挖掘運河可以威脅珊瑚生態系統。"},{"en":"The digging of canals means creating long artificial waterways by removing earth, rock, or seabed material.","zh":"挖掘運河指移除泥土、岩石或海床物質，以建造長條人工水道。"},{"en":"The digging of canals may help boats move, but it can disturb nearby habitats.","zh":"挖掘運河可能幫助船隻通行，但也會擾亂附近棲息地。"},{"en":"If canal digging releases sediment, sunlight may not reach corals clearly.","zh":"如果挖掘運河釋放沉積物，陽光可能無法清楚到達珊瑚。"},{"en":"This activity can change water flow and damage sensitive marine areas.","zh":"這項活動可以改變水流並破壞敏感海洋地區。"}],"source":"160 - Coral reefs.pdf","sourcePage":11},{"front":"access channels","meaning":"通航水道","examples":[{"en":"Access channels into islands and bays can damage reefs.","zh":"進入島嶼和海灣的通航水道可能破壞珊瑚礁。"},{"en":"Access channels are passages made or used so boats can enter an area more easily.","zh":"通航水道是為了讓船隻更容易進入某區域而建造或使用的通道。"},{"en":"A harbour may deepen access channels to allow larger ships to arrive.","zh":"港口可能加深通航水道，以容許較大型船隻到達。"},{"en":"Creating access channels near reefs can stir up sediment and break coral.","zh":"在珊瑚礁附近建造通航水道可能攪起沉積物並打斷珊瑚。"},{"en":"Access channels may help transport, but they must be planned carefully.","zh":"通航水道可能有助交通，但必須小心規劃。"}],"source":"160 - Coral reefs.pdf","sourcePage":11},{"front":"localized threats","meaning":"局部威脅","examples":[{"en":"Several human activities are localized threats to coral ecosystems.","zh":"幾種人類活動是對珊瑚生態系統的局部威脅。"},{"en":"Localized threats are dangers that mainly affect a particular place rather than the whole world.","zh":"局部威脅是主要影響某個特定地方，而非整個世界的危險。"},{"en":"A leaking factory may create localized threats to one river.","zh":"漏污染物的工廠可能對一條河流造成局部威脅。"},{"en":"Localized threats can still be serious if they damage a valuable habitat.","zh":"如果局部威脅破壞有價值的棲息地，它仍然可能很嚴重。"},{"en":"Cleaning up local pollution can reduce some localized threats quickly.","zh":"清理本地污染可以快速減少一些局部威脅。"}],"source":"160 - Coral reefs.pdf","sourcePage":11},{"front":"coral ecosystems","meaning":"珊瑚生態系統","examples":[{"en":"Pollution and disease threaten coral ecosystems.","zh":"污染和疾病威脅珊瑚生態系統。"},{"en":"Coral ecosystems are communities of corals, fish, plants, and other organisms living together around reefs.","zh":"珊瑚生態系統是珊瑚、魚類、植物和其他生物在珊瑚礁周圍共同生活的群落。"},{"en":"Healthy coral ecosystems provide food and shelter for many species.","zh":"健康珊瑚生態系統為許多物種提供食物和庇護。"},{"en":"If coral ecosystems collapse, local fisheries and tourism may suffer.","zh":"如果珊瑚生態系統崩潰，本地漁業和旅遊業可能受害。"},{"en":"Coral ecosystems include both the reef structure and the living relationships around it.","zh":"珊瑚生態系統包括珊瑚礁結構，以及其周圍的生命關係。"}],"source":"160 - Coral reefs.pdf","sourcePage":12},{"front":"broader threats","meaning":"更廣泛的威脅","examples":[{"en":"Broader threats include sea temperature rise and ocean acidification.","zh":"更廣泛的威脅包括海水溫度上升和海洋酸化。"},{"en":"Broader threats are larger dangers that affect wide areas or whole systems.","zh":"更廣泛的威脅是影響廣闊地區或整個系統的較大危險。"},{"en":"Climate change is a broader threat than one polluted beach.","zh":"氣候變化是比一個受污染海灘更廣泛的威脅。"},{"en":"Broader threats can be harder to solve because they involve many countries and industries.","zh":"更廣泛的威脅可能較難解決，因為它們涉及許多國家和產業。"},{"en":"Local action helps, but broader threats often require wider cooperation.","zh":"本地行動有幫助，但更廣泛的威脅通常需要更廣泛合作。"}],"source":"160 - Coral reefs.pdf","sourcePage":12},{"front":"sea temperature rise","meaning":"海水溫度上升","examples":[{"en":"Sea temperature rise threatens coral reefs.","zh":"海水溫度上升威脅珊瑚礁。"},{"en":"Sea temperature rise means ocean water becomes warmer over time.","zh":"海水溫度上升指海洋水溫隨時間變暖。"},{"en":"A small sea temperature rise can stress animals that are adapted to stable conditions.","zh":"輕微的海水溫度上升也可能令適應穩定環境的動物受壓。"},{"en":"If sea temperature rise continues, some corals may bleach or die.","zh":"如果海水溫度上升持續，一些珊瑚可能白化或死亡。"},{"en":"Sea temperature rise is dangerous because many marine species have limited temperature ranges.","zh":"海水溫度上升很危險，因為許多海洋物種能承受的溫度範圍有限。"}],"source":"160 - Coral reefs.pdf","sourcePage":12},{"front":"sea-level rise","meaning":"海平面上升","examples":[{"en":"Sea-level rise is a broader threat to coral reefs.","zh":"海平面上升是珊瑚礁面臨的更廣泛威脅。"},{"en":"Sea-level rise means the average level of the ocean becomes higher over time.","zh":"海平面上升指海洋平均水位隨時間變高。"},{"en":"Low-lying islands face greater flooding risks because of sea-level rise.","zh":"低窪島嶼因海平面上升而面臨更大水浸風險。"},{"en":"If sea-level rise changes light conditions, some shallow reefs may be affected.","zh":"如果海平面上升改變光照條件，一些淺水珊瑚礁可能受影響。"},{"en":"Sea-level rise can combine with storms to increase coastal damage.","zh":"海平面上升可以與風暴結合，增加沿岸破壞。"}],"source":"160 - Coral reefs.pdf","sourcePage":12},{"front":"pH changes","meaning":"酸鹼值變化","examples":[{"en":"Ocean acidification causes pH changes in seawater.","zh":"海洋酸化會造成海水酸鹼值變化。"},{"en":"pH changes are shifts in how acidic or alkaline a liquid is.","zh":"酸鹼值變化是液體酸性或鹼性程度的改變。"},{"en":"A swimming pool needs careful control because pH changes can irritate skin and eyes.","zh":"游泳池需要小心控制，因為酸鹼值變化會刺激皮膚和眼睛。"},{"en":"In seawater, pH changes can make it harder for corals to build skeletons.","zh":"在海水中，酸鹼值變化可能令珊瑚更難建立骨骼。"},{"en":"Even small pH changes can matter in sensitive biological systems.","zh":"即使細小酸鹼值變化，在敏感生物系統中也可能很重要。"}],"source":"160 - Coral reefs.pdf","sourcePage":12},{"front":"ocean acidification","meaning":"海洋酸化","examples":[{"en":"Ocean acidification threatens coral reef health.","zh":"海洋酸化威脅珊瑚礁健康。"},{"en":"Ocean acidification is the process by which seawater becomes more acidic, often because it absorbs more carbon dioxide.","zh":"海洋酸化是海水變得更酸的過程，通常因為吸收更多二氧化碳。"},{"en":"Students can understand ocean acidification by comparing it with a drink becoming more acidic.","zh":"學生可以把海洋酸化理解成飲品變得更酸。"},{"en":"Ocean acidification can reduce the minerals corals need to build hard structures.","zh":"海洋酸化可以減少珊瑚建立堅硬結構所需的礦物質。"},{"en":"It is a broad threat because it affects chemistry across large areas of the sea.","zh":"它是一種廣泛威脅，因為它影響大範圍海域的化學狀況。"}],"source":"160 - Coral reefs.pdf","sourcePage":12},{"front":"be associated with","meaning":"與……有關","examples":[{"en":"These threats are associated with greenhouse gas emissions.","zh":"這些威脅與溫室氣體排放有關。"},{"en":"Be associated with means to be connected to or linked with something.","zh":"be associated with 指與某事有關或有聯繫。"},{"en":"Poor sleep is often associated with lower concentration.","zh":"睡眠不足常與較低專注力有關。"},{"en":"If a disease is associated with dirty water, improving sanitation may reduce it.","zh":"如果某種疾病與污水有關，改善衛生可能減少它。"},{"en":"Associated with does not always mean one thing is the only cause.","zh":"associated with 不一定表示某事是唯一原因。"}],"source":"160 - Coral reefs.pdf","sourcePage":12},{"front":"greenhouse gas emissions","meaning":"溫室氣體排放","examples":[{"en":"Greenhouse gas emissions contribute to ocean changes.","zh":"溫室氣體排放導致海洋變化。"},{"en":"Greenhouse gas emissions are gases released into the air that trap heat, such as carbon dioxide and methane.","zh":"溫室氣體排放是釋放到空氣中並困住熱量的氣體，例如二氧化碳和甲烷。"},{"en":"Cars, factories, and power stations can produce greenhouse gas emissions.","zh":"汽車、工廠和發電站可以產生溫室氣體排放。"},{"en":"Higher greenhouse gas emissions can lead to warmer seas and changing weather patterns.","zh":"較高的溫室氣體排放可以導致海洋變暖和天氣模式改變。"},{"en":"Reducing greenhouse gas emissions is important for limiting climate-related damage.","zh":"減少溫室氣體排放對限制氣候相關破壞很重要。"}],"source":"160 - Coral reefs.pdf","sourcePage":12},{"front":"current fishing practices","meaning":"當前捕魚做法","examples":[{"en":"Some current fishing practices are destructive and unsustainable.","zh":"一些當前捕魚做法具破壞性且不可持續。"},{"en":"Current fishing practices are the methods people are using now to catch fish.","zh":"當前捕魚做法是人們現在用來捕魚的方法。"},{"en":"Current fishing practices may include nets, lines, traps, or more harmful techniques.","zh":"當前捕魚做法可能包括漁網、魚線、陷阱或更有害的技術。"},{"en":"If current fishing practices remove too many fish, populations may not recover.","zh":"如果當前捕魚做法捕走太多魚，種群可能無法恢復。"},{"en":"Changing current fishing practices can protect both fishers and marine ecosystems.","zh":"改變當前捕魚做法可以同時保護漁民和海洋生態系統。"}],"source":"160 - Coral reefs.pdf","sourcePage":12},{"front":"destructive and unsustainable","meaning":"具破壞性且不可持續","examples":[{"en":"Cyanide fishing and blast fishing are destructive and unsustainable.","zh":"氰化物捕魚和炸魚具破壞性且不可持續。"},{"en":"Destructive and unsustainable means causing serious damage and unable to continue safely over time.","zh":"destructive and unsustainable 指造成嚴重破壞，並且無法長期安全持續。"},{"en":"Cutting all trees in a forest at once is destructive and unsustainable.","zh":"一次過砍掉森林中所有樹木是具破壞性且不可持續的。"},{"en":"If a business model is destructive and unsustainable, it may create profit now but loss later.","zh":"如果一種商業模式具破壞性且不可持續，它可能現在創造利潤但日後造成損失。"},{"en":"Fishing methods that destroy habitats are destructive and unsustainable.","zh":"破壞棲息地的捕魚方法具破壞性且不可持續。"}],"source":"160 - Coral reefs.pdf","sourcePage":12},{"front":"cyanide fishing","meaning":"氰化物捕魚","examples":[{"en":"Cyanide fishing is used to catch live reef fish.","zh":"氰化物捕魚被用來捕捉活珊瑚礁魚。"},{"en":"Cyanide fishing is a harmful method in which fishers use poison to stun fish.","zh":"氰化物捕魚是一種有害方法，漁民使用毒物令魚昏迷。"},{"en":"Fish caught by cyanide fishing may be easier to capture alive.","zh":"透過氰化物捕魚捕到的魚可能較容易活捉。"},{"en":"Cyanide fishing can damage coral and poison other marine organisms.","zh":"氰化物捕魚可以破壞珊瑚並毒害其他海洋生物。"},{"en":"This method is dangerous because it targets fish but harms the wider reef.","zh":"這種方法很危險，因為它針對魚類，卻傷害更廣泛的珊瑚礁。"}],"source":"160 - Coral reefs.pdf","sourcePage":13},{"front":"overfishing","meaning":"過度捕魚","examples":[{"en":"Overfishing is a leading cause of coral reef degradation.","zh":"過度捕魚是珊瑚礁退化的主要原因之一。"},{"en":"Overfishing happens when people catch fish faster than the population can replace itself.","zh":"過度捕魚指人們捕魚速度快過魚類種群自我補充的速度。"},{"en":"A lake can suffer from overfishing if too many fish are taken every season.","zh":"如果每季捕走太多魚，一個湖泊也可能遭受過度捕魚。"},{"en":"Overfishing can upset the food chain and leave fewer breeding adults.","zh":"過度捕魚可以擾亂食物鏈，並令繁殖成魚減少。"},{"en":"Controlling overfishing helps fish populations recover and supports long-term livelihoods.","zh":"控制過度捕魚有助魚類種群恢復並支持長遠生計。"}],"source":"160 - Coral reefs.pdf","sourcePage":13},{"front":"blast fishing","meaning":"炸魚","examples":[{"en":"Blast fishing destroys surrounding coral.","zh":"炸魚會摧毀周圍珊瑚。"},{"en":"Blast fishing is a fishing method that uses explosives to kill or stun fish.","zh":"炸魚是一種使用炸藥殺死或震昏魚類的捕魚方法。"},{"en":"Blast fishing may catch many fish quickly, but it breaks the habitat at the same time.","zh":"炸魚可能快速捕到許多魚，但同時破壞棲息地。"},{"en":"When explosives are used underwater, coral structures can be shattered.","zh":"當炸藥在水底使用時，珊瑚結構可能被炸碎。"},{"en":"Blast fishing is dangerous to people, fish, and the reef itself.","zh":"炸魚對人、魚和珊瑚礁本身都很危險。"}],"source":"160 - Coral reefs.pdf","sourcePage":13},{"front":"supply live reef fish","meaning":"供應活珊瑚礁魚","examples":[{"en":"Cyanide fishing supplies live reef fish for the aquarium market.","zh":"氰化物捕魚為水族市場供應活珊瑚礁魚。"},{"en":"Supply live reef fish means provide living reef fish for sale or use.","zh":"supply live reef fish 指提供活的珊瑚礁魚作出售或使用。"},{"en":"Some traders supply live reef fish to restaurants that display them in tanks.","zh":"有些商人向把魚展示在魚缸中的餐廳供應活珊瑚礁魚。"},{"en":"If suppliers use harmful methods to supply live reef fish, reefs may be damaged.","zh":"如果供應者使用有害方法供應活珊瑚礁魚，珊瑚礁可能受損。"},{"en":"The phrase focuses on the trade in fish that are kept alive.","zh":"這個片語重點在於活魚貿易。"}],"source":"160 - Coral reefs.pdf","sourcePage":13},{"front":"tropical aquarium market","meaning":"熱帶水族市場","examples":[{"en":"Cyanide fishing supplies fish for the tropical aquarium market.","zh":"氰化物捕魚為熱帶水族市場供應魚類。"},{"en":"The tropical aquarium market is the trade in colourful warm-water fish kept in display tanks.","zh":"熱帶水族市場是買賣放在展示魚缸中的彩色暖水魚的行業。"},{"en":"Pet shops may buy fish from the tropical aquarium market.","zh":"寵物店可能從熱帶水族市場購買魚類。"},{"en":"Demand from the tropical aquarium market can encourage harmful collection methods if rules are weak.","zh":"如果規管薄弱，熱帶水族市場的需求可能鼓勵有害採集方法。"},{"en":"A responsible tropical aquarium market should protect fish populations and reef habitats.","zh":"負責任的熱帶水族市場應保護魚類種群和珊瑚礁棲息地。"}],"source":"160 - Coral reefs.pdf","sourcePage":13},{"front":"be sold in restaurants","meaning":"在餐廳出售","examples":[{"en":"Most fish caught this way are sold in restaurants.","zh":"大多數以這種方式捕獲的魚都在餐廳出售。"},{"en":"Be sold in restaurants means customers can buy and eat the item in eating places.","zh":"be sold in restaurants 指顧客可在餐飲場所購買並食用該物品。"},{"en":"Some local vegetables are sold in restaurants as seasonal dishes.","zh":"一些本地蔬菜會作為時令菜式在餐廳出售。"},{"en":"If live reef fish are sold in restaurants, customers may pay more for freshness.","zh":"如果活珊瑚礁魚在餐廳出售，顧客可能因新鮮而支付更高價格。"},{"en":"Being sold in restaurants can create demand for certain foods.","zh":"在餐廳出售可以創造對某些食物的需求。"}],"source":"160 - Coral reefs.pdf","sourcePage":13},{"front":"primarily in Asia","meaning":"主要在亞洲","examples":[{"en":"Live reef fish are sold primarily in Asia.","zh":"活珊瑚礁魚主要在亞洲出售。"},{"en":"Primarily in Asia means mainly in Asian countries or markets.","zh":"primarily in Asia 指主要在亞洲國家或市場。"},{"en":"This snack is sold primarily in Asia, although tourists sometimes buy it elsewhere.","zh":"這種小食主要在亞洲出售，雖然遊客有時在其他地方也會購買。"},{"en":"If demand exists primarily in Asia, suppliers may focus on Asian restaurants and buyers.","zh":"如果需求主要在亞洲，供應者可能集中於亞洲餐廳和買家。"},{"en":"Primarily tells us the main location, not the only location.","zh":"primarily 告訴我們主要地點，而不是唯一地點。"}],"source":"160 - Coral reefs.pdf","sourcePage":13},{"front":"be prized for","meaning":"因……而受珍視","examples":[{"en":"Live fish are prized for their freshness.","zh":"活魚因新鮮而受珍視。"},{"en":"Be prized for means be highly valued because of a particular quality.","zh":"be prized for 指因某種特質而被高度重視。"},{"en":"This tea is prized for its delicate smell and smooth taste.","zh":"這種茶因細緻香氣和順滑味道而受珍視。"},{"en":"If a fish is prized for freshness, customers may prefer it alive before cooking.","zh":"如果一條魚因新鮮而受珍視，顧客可能偏好烹調前仍然活著。"},{"en":"People often pay more for products prized for quality, rarity, or tradition.","zh":"人們常為因品質、稀有性或傳統而受珍視的產品支付更高價格。"}],"source":"160 - Coral reefs.pdf","sourcePage":13},{"front":"squirt cyanide","meaning":"噴射氰化物","examples":[{"en":"Fishers squirt cyanide into coral crevices.","zh":"漁民把氰化物噴射進珊瑚縫隙。"},{"en":"Squirt cyanide means force a poisonous chemical liquid into a place in a small stream.","zh":"squirt cyanide 指把有毒化學液體以細小水流用力噴入某處。"},{"en":"This action is dangerous because the poison can spread beyond the target fish.","zh":"這個行為很危險，因為毒物可能擴散到目標魚以外。"},{"en":"If fishers squirt cyanide into reefs, corals and small animals may be harmed.","zh":"如果漁民把氰化物噴射進珊瑚礁，珊瑚和小動物可能受害。"},{"en":"The verb squirt suggests a quick jet of liquid, not a slow pour.","zh":"squirt 這個動詞表示快速噴出液體，而不是慢慢倒出。"}],"source":"160 - Coral reefs.pdf","sourcePage":13},{"front":"coral crevices","meaning":"珊瑚縫隙","examples":[{"en":"Fishers squirt cyanide into coral crevices.","zh":"漁民把氰化物噴入珊瑚縫隙。"},{"en":"Coral crevices are narrow cracks or gaps in coral structures.","zh":"珊瑚縫隙是珊瑚結構中的狹窄裂縫或空隙。"},{"en":"Small fish may hide in coral crevices when predators approach.","zh":"當捕食者接近時，小魚可能躲進珊瑚縫隙。"},{"en":"Poison or sediment trapped in coral crevices can harm animals living there.","zh":"被困在珊瑚縫隙中的毒物或沉積物可以傷害生活在那裡的動物。"},{"en":"Coral crevices are tiny spaces, but they can be important shelters.","zh":"珊瑚縫隙雖然細小，但可以是重要庇護處。"}],"source":"160 - Coral reefs.pdf","sourcePage":13},{"front":"fast-moving fish","meaning":"快速游動的魚","examples":[{"en":"Fishers use cyanide to stun fast-moving fish.","zh":"漁民使用氰化物令快速游動的魚昏迷。"},{"en":"Fast-moving fish are fish that swim quickly and are difficult to catch by hand.","zh":"快速游動的魚是游得很快、難以徒手捕捉的魚。"},{"en":"A child watching an aquarium may find fast-moving fish hard to follow with their eyes.","zh":"孩子觀看水族箱時，可能覺得快速游動的魚很難用眼睛跟上。"},{"en":"Because fast-moving fish escape easily, some fishers use harmful methods to catch them.","zh":"因為快速游動的魚容易逃走，有些漁民使用有害方法捕捉牠們。"},{"en":"Speed protects fast-moving fish, but poison can remove that advantage.","zh":"速度能保護快速游動的魚，但毒物會消除這個優勢。"}],"source":"160 - Coral reefs.pdf","sourcePage":14},{"front":"stun them","meaning":"令牠們昏迷","examples":[{"en":"Cyanide is used to stun fish and make them easy to catch.","zh":"氰化物被用來令魚昏迷，使牠們容易被捕捉。"},{"en":"Stun them means make them temporarily unable to move or react normally.","zh":"stun them 指令牠們暫時無法正常移動或反應。"},{"en":"Bright lights can stun small animals for a moment.","zh":"強光可能會短暫令小動物昏眩。"},{"en":"If poison is used to stun fish, other reef organisms may also be harmed.","zh":"如果使用毒物令魚昏迷，其他珊瑚礁生物也可能受害。"},{"en":"Stun does not necessarily mean kill immediately, but it can still be dangerous.","zh":"stun 不一定表示立即殺死，但仍可能很危險。"}],"source":"160 - Coral reefs.pdf","sourcePage":14},{"front":"leading cause of","meaning":"……的主要原因","examples":[{"en":"Overfishing is another leading cause of coral reef degradation.","zh":"過度捕魚是珊瑚礁退化的另一個主要原因。"},{"en":"A leading cause of something is one of the main reasons it happens.","zh":"leading cause of something 指某事發生的主要原因之一。"},{"en":"Poor diet is a leading cause of some health problems.","zh":"不良飲食是一些健康問題的主要原因。"},{"en":"If stress is a leading cause of staff leaving, managers should improve working conditions.","zh":"如果壓力是員工離職的主要原因，管理層應改善工作環境。"},{"en":"This phrase highlights a major cause, not a minor detail.","zh":"這個片語強調主要原因，而不是次要細節。"}],"source":"160 - Coral reefs.pdf","sourcePage":14},{"front":"coral reef degradation","meaning":"珊瑚礁退化","examples":[{"en":"Overfishing contributes to coral reef degradation.","zh":"過度捕魚會導致珊瑚礁退化。"},{"en":"Coral reef degradation means the decline or damage of reef health, structure, and life.","zh":"珊瑚礁退化指珊瑚礁健康、結構和生命的衰退或受損。"},{"en":"Pollution, careless tourism, and destructive fishing can all cause coral reef degradation.","zh":"污染、不小心旅遊和破壞性捕魚都可以造成珊瑚礁退化。"},{"en":"When coral reef degradation becomes severe, fish and tourists may disappear.","zh":"當珊瑚礁退化變得嚴重，魚類和遊客可能消失。"},{"en":"Coral reef degradation is a process, not just one sudden event.","zh":"珊瑚礁退化是一個過程，不只是一件突然事件。"}],"source":"160 - Coral reefs.pdf","sourcePage":14},{"front":"sustain a population","meaning":"維持某個種群","examples":[{"en":"Too many fish may be taken to sustain a population in that area.","zh":"捕走太多魚可能令該區無法維持某個種群。"},{"en":"Sustain a population means keep enough individuals alive so the group can continue over time.","zh":"sustain a population 指保留足夠個體生存，使該群體能長期延續。"},{"en":"A forest must have enough breeding animals to sustain a population of birds.","zh":"森林必須有足夠繁殖動物，才能維持鳥類種群。"},{"en":"If hunting is too heavy, the area may not sustain a population of deer.","zh":"如果狩獵過度，該區可能無法維持鹿的種群。"},{"en":"Sustainable fishing leaves enough fish to reproduce and maintain the population.","zh":"可持續捕魚會留下足夠魚類繁殖並維持種群。"}],"source":"160 - Coral reefs.pdf","sourcePage":14},{"front":"poor fishing practices","meaning":"不良捕魚做法","examples":[{"en":"Poor fishing practices can destroy coral formations.","zh":"不良捕魚做法可以摧毀珊瑚構造。"},{"en":"Poor fishing practices are careless, harmful, or badly managed ways of catching fish.","zh":"不良捕魚做法是粗心、有害或管理不善的捕魚方式。"},{"en":"Using nets that catch many young fish is one example of poor fishing practices.","zh":"使用捕走大量幼魚的漁網是不良捕魚做法的一個例子。"},{"en":"Poor fishing practices can reduce future catches by damaging habitats.","zh":"不良捕魚做法可以透過破壞棲息地減少未來漁獲。"},{"en":"Better rules and training can help replace poor fishing practices.","zh":"更好的規則和培訓可以幫助取代不良捕魚做法。"}],"source":"160 - Coral reefs.pdf","sourcePage":14},{"front":"bang on the reef","meaning":"用棍敲打珊瑚礁","examples":[{"en":"Some fishers bang on the reef with sticks.","zh":"有些漁民用棍敲打珊瑚礁。"},{"en":"Bang on the reef means hit the coral reef hard, usually to scare fish out.","zh":"bang on the reef 指用力敲打珊瑚礁，通常是為了把魚嚇出來。"},{"en":"A person who bangs on a table makes a loud striking sound.","zh":"用力敲桌子的人會發出很大的撞擊聲。"},{"en":"When fishers bang on the reef, fragile coral formations may break.","zh":"當漁民用棍敲打珊瑚礁，脆弱珊瑚構造可能破裂。"},{"en":"This action may seem simple, but it can cause lasting damage.","zh":"這個行為看似簡單，但可以造成長久破壞。"}],"source":"160 - Coral reefs.pdf","sourcePage":14},{"front":"coral formations","meaning":"珊瑚構造","examples":[{"en":"Poor fishing practices destroy coral formations.","zh":"不良捕魚做法會摧毀珊瑚構造。"},{"en":"Coral formations are the shapes and structures created by growing corals.","zh":"珊瑚構造是由生長中的珊瑚形成的形狀和結構。"},{"en":"Divers may see coral formations shaped like branches, plates, or large rounded rocks.","zh":"潛水員可能看到像樹枝、板狀或大型圓石般的珊瑚構造。"},{"en":"If coral formations break, fish lose hiding places and breeding areas.","zh":"如果珊瑚構造破裂，魚類會失去躲藏地和繁殖區。"},{"en":"Coral formations take a long time to grow, so damage is not quickly repaired.","zh":"珊瑚構造需要很長時間生長，因此損害不會很快修復。"}],"source":"160 - Coral reefs.pdf","sourcePage":14},{"front":"function as fish habitat","meaning":"作為魚類棲息地","examples":[{"en":"Coral formations normally function as fish habitat.","zh":"珊瑚構造通常作為魚類棲息地。"},{"en":"Function as fish habitat means serve as a place where fish can live, feed, hide, or reproduce.","zh":"function as fish habitat 指作為魚類生活、覓食、躲藏或繁殖的地方。"},{"en":"Old roots in a river can function as fish habitat for young fish.","zh":"河中的老樹根可以作為幼魚的魚類棲息地。"},{"en":"If coral formations are destroyed, they can no longer function as fish habitat.","zh":"如果珊瑚構造被摧毀，它們就不能再作為魚類棲息地。"},{"en":"This phrase explains the practical role of a structure in an ecosystem.","zh":"這個片語解釋某個結構在生態系統中的實際作用。"}],"source":"160 - Coral reefs.pdf","sourcePage":14},{"front":"in some instances","meaning":"在某些情況下","examples":[{"en":"In some instances, people fish with explosives.","zh":"在某些情況下，人們用炸藥捕魚。"},{"en":"In some instances means in some cases or situations.","zh":"in some instances 指在某些個案或情況下。"},{"en":"In some instances, students learn better by drawing diagrams than by reading notes.","zh":"在某些情況下，學生透過畫圖比閱讀筆記學得更好。"},{"en":"In some instances, a small mistake can cause a large delay.","zh":"在某些情況下，一個小錯誤可以造成很大延誤。"},{"en":"This phrase shows that something happens sometimes, but not always.","zh":"這個片語顯示某事有時會發生，但不是永遠如此。"}],"source":"160 - Coral reefs.pdf","sourcePage":14},{"front":"fish with explosives","meaning":"用炸藥捕魚","examples":[{"en":"Some people fish with explosives.","zh":"有些人用炸藥捕魚。"},{"en":"Fish with explosives means use bombs or explosive materials to kill or stun fish.","zh":"fish with explosives 指使用炸彈或爆炸物殺死或震昏魚類。"},{"en":"People may fish with explosives because it catches many fish quickly.","zh":"有些人用炸藥捕魚，因為它可以快速捕到許多魚。"},{"en":"Fishing with explosives can destroy coral, kill young fish, and endanger people.","zh":"用炸藥捕魚可以摧毀珊瑚、殺死幼魚並危及人命。"},{"en":"This method is harmful even if it produces a quick catch.","zh":"即使這種方法能快速取得漁獲，它仍然有害。"}],"source":"160 - Coral reefs.pdf","sourcePage":15},{"front":"blast apart","meaning":"炸裂","examples":[{"en":"Explosives blast apart the surrounding coral.","zh":"炸藥會把周圍珊瑚炸裂。"},{"en":"Blast apart means break something violently into pieces by an explosion or strong force.","zh":"blast apart 指透過爆炸或強大力量把某物猛烈打碎。"},{"en":"A powerful storm can blast apart weak wooden structures.","zh":"強烈風暴可以把脆弱木結構擊碎。"},{"en":"If explosives blast apart coral, the reef may take decades to recover.","zh":"如果炸藥把珊瑚炸裂，珊瑚礁可能需要數十年恢復。"},{"en":"This phrase suggests sudden, forceful, and serious destruction.","zh":"這個片語表示突然、有力而嚴重的破壞。"}],"source":"160 - Coral reefs.pdf","sourcePage":15},{"front":"surrounding coral","meaning":"周圍珊瑚","examples":[{"en":"Blast fishing destroys the surrounding coral.","zh":"炸魚會摧毀周圍珊瑚。"},{"en":"Surrounding coral means the coral located around a particular place or action.","zh":"surrounding coral 指位於某地方或行動周圍的珊瑚。"},{"en":"A dropped anchor can damage the surrounding coral near a boat.","zh":"拋下的錨可以破壞船隻附近的周圍珊瑚。"},{"en":"If poison spreads, surrounding coral may suffer even when it is not directly targeted.","zh":"如果毒物擴散，即使周圍珊瑚不是直接目標，也可能受害。"},{"en":"The word surrounding helps show that nearby coral is also affected.","zh":"surrounding 這個詞幫助顯示附近珊瑚也會受影響。"}],"source":"160 - Coral reefs.pdf","sourcePage":15},{"front":"tourist resorts","meaning":"旅遊度假村","examples":[{"en":"Tourist resorts can contribute to coral reef degradation.","zh":"旅遊度假村可能導致珊瑚礁退化。"},{"en":"Tourist resorts are places with hotels, restaurants, and leisure services for visitors.","zh":"旅遊度假村是為遊客提供酒店、餐廳和休閒服務的地方。"},{"en":"Families may stay in tourist resorts near beaches during holidays.","zh":"家庭可能在假期入住海灘附近的旅遊度假村。"},{"en":"If tourist resorts release waste into the sea, nearby reefs may be damaged.","zh":"如果旅遊度假村把廢物排入海中，附近珊瑚礁可能受損。"},{"en":"Tourist resorts can support local economies, but they need responsible management.","zh":"旅遊度假村可以支持本地經濟，但需要負責任管理。"}],"source":"160 - Coral reefs.pdf","sourcePage":15},{"front":"empty sewage directly into","meaning":"將污水直接排入","examples":[{"en":"Some resorts empty their sewage directly into reef waters.","zh":"有些度假村將污水直接排入珊瑚礁水域。"},{"en":"Empty sewage directly into means discharge waste water straight into a place without proper treatment.","zh":"empty sewage directly into 指未經適當處理便把污水直接排入某處。"},{"en":"A factory must not empty sewage directly into a river.","zh":"工廠不得將污水直接排入河流。"},{"en":"If resorts empty sewage directly into the sea, bacteria and nutrients can harm reefs.","zh":"如果度假村將污水直接排入海中，細菌和營養物可以傷害珊瑚礁。"},{"en":"Proper treatment systems can prevent sewage from entering sensitive waters.","zh":"適當處理系統可以防止污水進入敏感水域。"}],"source":"160 - Coral reefs.pdf","sourcePage":15},{"front":"surrounding coral reefs","meaning":"圍繞珊瑚礁的水域","examples":[{"en":"Pollution enters the water surrounding coral reefs.","zh":"污染進入圍繞珊瑚礁的水域。"},{"en":"Surrounding coral reefs means around or near coral reef areas.","zh":"surrounding coral reefs 指位於珊瑚礁周圍或附近。"},{"en":"Boats should slow down in waters surrounding coral reefs to avoid damage.","zh":"船隻在圍繞珊瑚礁的水域中應減速，以免造成破壞。"},{"en":"If construction mud enters water surrounding coral reefs, sunlight may be blocked.","zh":"如果工程泥沙進入圍繞珊瑚礁的水域，陽光可能被阻擋。"},{"en":"Conditions around reefs matter because nearby water directly affects reef health.","zh":"珊瑚礁周圍的環境很重要，因為附近水質直接影響珊瑚礁健康。"}],"source":"160 - Coral reefs.pdf","sourcePage":15},{"front":"contribute to coral reef degradation","meaning":"導致珊瑚礁退化","examples":[{"en":"Sewage and careless tourism contribute to coral reef degradation.","zh":"污水和粗心旅遊會導致珊瑚礁退化。"},{"en":"Contribute to coral reef degradation means help cause the decline or damage of coral reefs.","zh":"contribute to coral reef degradation 指促成珊瑚礁衰退或受損。"},{"en":"Dropping anchors on coral can contribute to coral reef degradation.","zh":"將錨拋在珊瑚上可以導致珊瑚礁退化。"},{"en":"If many small harms continue, they can together contribute to coral reef degradation.","zh":"如果許多小傷害持續發生，它們可以一起導致珊瑚礁退化。"},{"en":"The phrase shows that one action may be part of a larger problem.","zh":"這個片語顯示某個行動可能是較大問題的一部分。"}],"source":"160 - Coral reefs.pdf","sourcePage":15},{"front":"poorly maintained septic tanks","meaning":"保養不善的化糞池","examples":[{"en":"Poorly maintained septic tanks can leak waste into groundwater.","zh":"保養不善的化糞池可以把廢物滲漏到地下水中。"},{"en":"Poorly maintained septic tanks are waste treatment tanks that are not cleaned, checked, or repaired properly.","zh":"保養不善的化糞池是沒有被適當清潔、檢查或維修的廢水處理池。"},{"en":"A hotel with poorly maintained septic tanks may create smells and pollution.","zh":"擁有保養不善化糞池的酒店可能產生氣味和污染。"},{"en":"If septic tanks are poorly maintained, dirty water can seep into soil and groundwater.","zh":"如果化糞池保養不善，污水可以滲入土壤和地下水。"},{"en":"Regular inspection helps prevent poorly maintained septic tanks from becoming health risks.","zh":"定期檢查有助防止保養不善的化糞池變成健康風險。"}],"source":"160 - Coral reefs.pdf","sourcePage":15},{"front":"leak into","meaning":"滲漏到","examples":[{"en":"Waste can leak into surrounding groundwater.","zh":"廢物可以滲漏到周圍地下水中。"},{"en":"Leak into means slowly escape from one place and enter another place.","zh":"leak into 指慢慢從一個地方漏出並進入另一個地方。"},{"en":"Rainwater can leak into a house through a broken roof.","zh":"雨水可以透過破損屋頂滲漏到屋內。"},{"en":"If chemicals leak into a river, fish and people may be affected.","zh":"如果化學物滲漏到河流中，魚類和人類可能受影響。"},{"en":"Leak into often suggests unwanted or harmful movement.","zh":"leak into 通常暗示不想要或有害的移動。"}],"source":"160 - Coral reefs.pdf","sourcePage":15},{"front":"surrounding groundwater","meaning":"周圍地下水","examples":[{"en":"Waste may leak into surrounding groundwater.","zh":"廢物可能滲漏到周圍地下水中。"},{"en":"Surrounding groundwater is the water beneath the ground near a particular place.","zh":"周圍地下水是某地附近地底下的水。"},{"en":"A farm must protect surrounding groundwater from fertiliser and waste.","zh":"農場必須保護周圍地下水免受肥料和廢物污染。"},{"en":"If surrounding groundwater is polluted, wells and coastal waters may also be affected.","zh":"如果周圍地下水受污染，水井和沿岸水域也可能受影響。"},{"en":"Groundwater is hidden, so damage to it may not be noticed quickly.","zh":"地下水是隱藏的，因此其受損可能不會很快被察覺。"}],"source":"160 - Coral reefs.pdf","sourcePage":15},{"front":"seep out to","meaning":"滲出至","examples":[{"en":"Polluted groundwater can seep out to the reefs.","zh":"受污染地下水可以滲出至珊瑚礁。"},{"en":"Seep out to means slowly flow out and reach another place.","zh":"seep out to 指慢慢流出並到達另一個地方。"},{"en":"Oil can seep out to the road from a damaged engine.","zh":"機器受損時，油可以滲出至道路上。"},{"en":"If polluted water seeps out to the sea, it may harm coastal habitats.","zh":"如果受污染水滲出至海洋，可能傷害沿岸棲息地。"},{"en":"Seep suggests a slow movement that may be hard to notice at first.","zh":"seep 暗示緩慢移動，起初可能不易察覺。"}],"source":"160 - Coral reefs.pdf","sourcePage":16},{"front":"careless boating","meaning":"不小心駕船","examples":[{"en":"Careless boating can damage coral reefs.","zh":"不小心駕船可以破壞珊瑚礁。"},{"en":"Careless boating means operating a boat without enough attention to safety or the environment.","zh":"不小心駕船指在操作船隻時沒有足夠注意安全或環境。"},{"en":"A driver who ignores shallow reef areas is guilty of careless boating.","zh":"忽視淺水珊瑚礁區域的船隻駕駛者，就是不小心駕船。"},{"en":"Careless boating can break coral when boats hit reefs or drop anchors in the wrong place.","zh":"當船隻撞到珊瑚礁或把錨拋錯地方，不小心駕船可以折斷珊瑚。"},{"en":"Careful navigation helps prevent careless boating from harming marine life.","zh":"小心航行有助防止不小心駕船傷害海洋生命。"}],"source":"160 - Coral reefs.pdf","sourcePage":16},{"front":"snorkeling","meaning":"浮潛","examples":[{"en":"Careless snorkeling can damage coral reefs.","zh":"粗心浮潛可以破壞珊瑚礁。"},{"en":"Snorkeling is swimming near the surface while breathing through a tube and looking underwater.","zh":"浮潛是在水面附近游泳，透過呼吸管呼吸並觀看水底。"},{"en":"Tourists often try snorkeling in clear shallow water.","zh":"遊客常在清澈淺水中嘗試浮潛。"},{"en":"Snorkeling can harm coral if people kick reefs or stand on them.","zh":"如果人們踢到珊瑚礁或站在上面，浮潛可以傷害珊瑚。"},{"en":"Responsible snorkeling means keeping distance and not touching marine life.","zh":"負責任浮潛意味著保持距離並不觸碰海洋生命。"}],"source":"160 - Coral reefs.pdf","sourcePage":16},{"front":"grab, kick or walk on","meaning":"抓住、踢到或踩在……上","examples":[{"en":"People damage coral when they grab, kick or walk on it.","zh":"當人們抓住、踢到或踩在珊瑚上時，會破壞珊瑚。"},{"en":"Grab, kick or walk on describes direct physical actions that can break or stress coral.","zh":"grab, kick or walk on 描述可以折斷或令珊瑚受壓的直接身體動作。"},{"en":"A diver should not grab coral to keep balance in the water.","zh":"潛水員不應抓住珊瑚來在水中保持平衡。"},{"en":"If tourists kick or walk on coral, fragile living structures may be crushed.","zh":"如果遊客踢到或踩在珊瑚上，脆弱的活結構可能被壓碎。"},{"en":"These simple actions can cause damage even when people do not mean to.","zh":"即使人們並非有意，這些簡單動作也可以造成破壞。"}],"source":"160 - Coral reefs.pdf","sourcePage":16},{"front":"stir up sediment","meaning":"攪起沉積物","examples":[{"en":"Divers can damage reefs when they stir up sediment.","zh":"潛水員攪起沉積物時，可以破壞珊瑚礁。"},{"en":"Stir up sediment means disturb sand, mud, or small particles so they rise into the water.","zh":"stir up sediment 指擾動沙、泥或細小顆粒，使它們升入水中。"},{"en":"A swimmer may stir up sediment in a shallow muddy lake.","zh":"游泳者可能在淺而泥濘的湖中攪起沉積物。"},{"en":"When sediment is stirred up, it can block sunlight and cover coral surfaces.","zh":"當沉積物被攪起時，它可以阻擋陽光並覆蓋珊瑚表面。"},{"en":"Careful fin movement helps divers avoid stirring up sediment near reefs.","zh":"小心擺動蛙鞋有助潛水員避免在珊瑚礁附近攪起沉積物。"}],"source":"160 - Coral reefs.pdf","sourcePage":16},{"front":"coral reef destruction","meaning":"珊瑚礁破壞","examples":[{"en":"Physical contact can contribute to coral reef destruction.","zh":"身體接觸可以導致珊瑚礁破壞。"},{"en":"Coral reef destruction means severe damage or loss of reef structures and living communities.","zh":"珊瑚礁破壞指珊瑚礁結構和生命群落受到嚴重損害或消失。"},{"en":"Coral reef destruction can happen through pollution, explosives, anchors, and careless tourism.","zh":"珊瑚礁破壞可以透過污染、炸藥、錨和粗心旅遊發生。"},{"en":"When coral reef destruction occurs, fish habitats and coastal protection may disappear.","zh":"當珊瑚礁破壞出現時，魚類棲息地和海岸保護可能消失。"},{"en":"Preventing small harms early can reduce wider coral reef destruction.","zh":"及早防止小傷害可以減少更廣泛的珊瑚礁破壞。"}],"source":"160 - Coral reefs.pdf","sourcePage":16},{"front":"drop anchors on","meaning":"將錨拋在……上","examples":[{"en":"Corals are harmed when people drop anchors on them.","zh":"當人們將錨拋在珊瑚上，珊瑚會受傷害。"},{"en":"Drop anchors on means lower heavy boat anchors onto a surface or area.","zh":"drop anchors on 指把沉重船錨放落到某個表面或區域上。"},{"en":"Boats should not drop anchors on seagrass beds or coral reefs.","zh":"船隻不應將錨拋在海草床或珊瑚礁上。"},{"en":"If tourists drop anchors on living coral, the anchor may crush or break it.","zh":"如果遊客將錨拋在活珊瑚上，錨可能壓碎或折斷它。"},{"en":"Mooring buoys can reduce the need to drop anchors on sensitive habitats.","zh":"繫泊浮標可以減少將錨拋在敏感棲息地上的需要。"}],"source":"160 - Coral reefs.pdf","sourcePage":16},{"front":"collect coral","meaning":"採集珊瑚","examples":[{"en":"Corals are damaged when people collect coral.","zh":"當人們採集珊瑚，珊瑚會受損。"},{"en":"Collect coral means take pieces of coral from the sea, often as souvenirs or decorations.","zh":"collect coral 指從海中取走珊瑚碎片，常作紀念品或裝飾。"},{"en":"Tourists should not collect coral from beaches or reefs.","zh":"遊客不應從海灘或珊瑚礁採集珊瑚。"},{"en":"If many people collect coral, reef structures can become weaker over time.","zh":"如果許多人採集珊瑚，珊瑚礁結構會隨時間變弱。"},{"en":"Taking photos is better than collecting coral from a living habitat.","zh":"拍照比從活棲息地採集珊瑚更好。"}],"source":"160 - Coral reefs.pdf","sourcePage":16},{"front":"find answers for","meaning":"為……尋找答案","examples":[{"en":"Scientists study coral reefs to find answers for these problems.","zh":"科學家研究珊瑚礁，以為這些問題尋找答案。"},{"en":"Find answers for means discover solutions, explanations, or ways to deal with problems.","zh":"find answers for 指找出解決方法、解釋或處理問題的方式。"},{"en":"Doctors run tests to find answers for a patient’s symptoms.","zh":"醫生進行檢查，以為病人的症狀尋找答案。"},{"en":"If a city has traffic problems, planners must find answers for congestion and delays.","zh":"如果城市有交通問題，規劃者必須為擠塞和延誤尋找答案。"},{"en":"Research helps people find answers for complex environmental challenges.","zh":"研究幫助人們為複雜環境挑戰尋找答案。"}],"source":"160 - Coral reefs.pdf","sourcePage":16},{"front":"various factors","meaning":"各種因素","examples":[{"en":"Researchers study various factors that affect reefs.","zh":"研究人員研究影響珊瑚礁的各種因素。"},{"en":"Various factors are several different causes, conditions, or influences.","zh":"各種因素是多個不同原因、條件或影響。"},{"en":"A teacher considers various factors before deciding why a student is struggling.","zh":"老師在判斷學生為何吃力前，會考慮各種因素。"},{"en":"Various factors, such as sleep, diet, and stress, can affect exam performance.","zh":"各種因素，例如睡眠、飲食和壓力，都可以影響考試表現。"},{"en":"This phrase reminds readers that a problem may have more than one cause.","zh":"這個片語提醒讀者，一個問題可能有不只一個原因。"}],"source":"160 - Coral reefs.pdf","sourcePage":16},{"front":"affect reefs","meaning":"影響珊瑚礁","examples":[{"en":"Scientists study the factors that affect reefs.","zh":"科學家研究影響珊瑚礁的因素。"},{"en":"Affect reefs means change reef health, growth, structure, or the organisms living there.","zh":"affect reefs 指改變珊瑚礁的健康、生長、結構或生活在那裡的生物。"},{"en":"Pollution can affect reefs by making the water less clear.","zh":"污染可以透過令水變得較混濁來影響珊瑚礁。"},{"en":"Warmer seas may affect reefs by causing coral bleaching.","zh":"海洋變暖可能透過造成珊瑚白化來影響珊瑚礁。"},{"en":"Even activities far from the coast can affect reefs if waste reaches the ocean.","zh":"即使遠離海岸的活動，如果廢物流入海洋，也可以影響珊瑚礁。"}],"source":"160 - Coral reefs.pdf","sourcePage":17},{"front":"carbon dioxide sink","meaning":"二氧化碳匯","examples":[{"en":"The ocean’s role as a carbon dioxide sink affects reefs.","zh":"海洋作為二氧化碳匯的角色會影響珊瑚礁。"},{"en":"A carbon dioxide sink is a natural or artificial system that absorbs more carbon dioxide than it releases.","zh":"二氧化碳匯是吸收二氧化碳多於釋放二氧化碳的天然或人工系統。"},{"en":"Forests can act as a carbon dioxide sink when trees grow and store carbon.","zh":"當樹木生長並儲存碳時，森林可以作為二氧化碳匯。"},{"en":"When the ocean acts as a carbon dioxide sink, seawater chemistry can change.","zh":"當海洋作為二氧化碳匯，海水化學狀況可能改變。"},{"en":"This role helps reduce carbon in the air but may create pressure on marine systems.","zh":"這個角色有助減少空氣中的碳，但可能對海洋系統造成壓力。"}],"source":"160 - Coral reefs.pdf","sourcePage":17},{"front":"atmospheric changes","meaning":"大氣變化","examples":[{"en":"Atmospheric changes may affect coral reefs.","zh":"大氣變化可能影響珊瑚礁。"},{"en":"Atmospheric changes are changes in the gases, temperature, or conditions of the air around Earth.","zh":"大氣變化是地球周圍空氣中的氣體、溫度或狀況改變。"},{"en":"Atmospheric changes can influence rainfall, storms, and ocean temperatures.","zh":"大氣變化可以影響降雨、風暴和海洋溫度。"},{"en":"If atmospheric changes warm the sea, corals may become stressed.","zh":"如果大氣變化令海洋變暖，珊瑚可能受壓。"},{"en":"Reefs are underwater, but they can still be affected by changes in the atmosphere.","zh":"珊瑚礁雖然在水底，但仍可能受大氣變化影響。"}],"source":"160 - Coral reefs.pdf","sourcePage":17},{"front":"ultraviolet light","meaning":"紫外線","examples":[{"en":"Researchers study the effect of ultraviolet light on reefs.","zh":"研究人員研究紫外線對珊瑚礁的影響。"},{"en":"Ultraviolet light is a type of sunlight with energy that can affect living cells.","zh":"紫外線是一種具有能量、可以影響活細胞的陽光。"},{"en":"Sunscreen helps protect skin from ultraviolet light.","zh":"防曬霜有助保護皮膚免受紫外線影響。"},{"en":"Too much ultraviolet light can damage some organisms, especially when other stresses exist.","zh":"過多紫外線可以傷害一些生物，尤其在存在其他壓力時。"},{"en":"Scientists study ultraviolet light to understand how sunlight affects reef health.","zh":"科學家研究紫外線，以了解陽光如何影響珊瑚礁健康。"}],"source":"160 - Coral reefs.pdf","sourcePage":17},{"front":"impacts of dust storms","meaning":"沙塵暴的影響","examples":[{"en":"The impacts of dust storms on far-flung reefs are studied.","zh":"沙塵暴對遙遠珊瑚礁的影響正被研究。"},{"en":"Impacts of dust storms are the effects caused when strong winds carry dust over long distances.","zh":"沙塵暴的影響是強風把沙塵帶到遠處時造成的效果。"},{"en":"Dust storms can affect air quality and make breathing difficult.","zh":"沙塵暴可以影響空氣質素，並令人呼吸困難。"},{"en":"If dust reaches the sea, it may carry nutrients, microbes, or pollutants to reefs.","zh":"如果沙塵到達海洋，它可能把營養物、微生物或污染物帶到珊瑚礁。"},{"en":"Studying the impacts of dust storms shows that distant land events can affect oceans.","zh":"研究沙塵暴的影響顯示，遙遠陸地事件也可以影響海洋。"}],"source":"160 - Coral reefs.pdf","sourcePage":17},{"front":"carry agents to","meaning":"將物質帶到……","examples":[{"en":"Dust storms may carry agents to far-flung reefs.","zh":"沙塵暴可能將物質帶到遙遠的珊瑚礁。"},{"en":"Carry agents to means transport substances, organisms, or harmful materials to another place.","zh":"carry agents to 指把物質、生物或有害材料運送到另一地方。"},{"en":"Wind can carry agents to farms, including pollen, dust, or disease spores.","zh":"風可以將花粉、沙塵或病菌孢子等物質帶到農場。"},{"en":"If storms carry agents to reefs, the reef may receive materials from very far away.","zh":"如果風暴將物質帶到珊瑚礁，珊瑚礁可能收到來自很遠地方的材料。"},{"en":"This phrase is broad because agents can be helpful, neutral, or harmful.","zh":"這個片語含義廣泛，因為 agents 可以是有益、中性或有害的物質。"}],"source":"160 - Coral reefs.pdf","sourcePage":17},{"front":"far-flung reefs","meaning":"遙遠的珊瑚礁","examples":[{"en":"Dust storms can affect far-flung reefs.","zh":"沙塵暴可以影響遙遠的珊瑚礁。"},{"en":"Far-flung reefs are reefs located very far away from the source or main area being discussed.","zh":"遙遠的珊瑚礁是位於離來源或主要討論地區很遠的珊瑚礁。"},{"en":"Scientists may use satellites to study far-flung reefs that are hard to visit.","zh":"科學家可能使用衛星研究難以到訪的遙遠珊瑚礁。"},{"en":"Pollution can sometimes reach far-flung reefs through air or ocean currents.","zh":"污染有時可以透過空氣或洋流到達遙遠珊瑚礁。"},{"en":"Far-flung reefs may seem isolated, but they are still connected to global systems.","zh":"遙遠珊瑚礁看似孤立，但仍與全球系統相連。"}],"source":"160 - Coral reefs.pdf","sourcePage":17},{"front":"pollutants","meaning":"污染物","examples":[{"en":"Pollutants are among the factors that affect reefs.","zh":"污染物是影響珊瑚礁的因素之一。"},{"en":"Pollutants are harmful substances that contaminate air, water, or land.","zh":"污染物是污染空氣、水或土地的有害物質。"},{"en":"Plastic waste, oil, and chemicals can all be pollutants in the ocean.","zh":"塑膠廢物、油污和化學物都可以是海洋中的污染物。"},{"en":"Pollutants can weaken coral and make marine animals sick.","zh":"污染物可以削弱珊瑚並令海洋動物生病。"},{"en":"Reducing pollutants at the source is often easier than cleaning them up later.","zh":"在源頭減少污染物，通常比日後清理更容易。"}],"source":"160 - Coral reefs.pdf","sourcePage":17},{"front":"algal blooms","meaning":"藻華；藻類大量繁殖","examples":[{"en":"Algal blooms can affect coral reef ecosystems.","zh":"藻華可以影響珊瑚礁生態系統。"},{"en":"Algal blooms are sudden rapid increases in algae in water.","zh":"藻華是水中藻類突然快速增加的現象。"},{"en":"A lake may turn green during algal blooms after too much fertiliser enters it.","zh":"當太多肥料流入湖泊後，湖水可能因藻華而變綠。"},{"en":"Algal blooms can block sunlight and reduce oxygen in the water.","zh":"藻華可以阻擋陽光並降低水中氧氣。"},{"en":"Coral reefs may suffer when algal blooms grow over reef surfaces.","zh":"當藻華在珊瑚礁表面生長，珊瑚礁可能受害。"}],"source":"160 - Coral reefs.pdf","sourcePage":17},{"front":"well beyond coastal areas","meaning":"遠超沿岸地區","examples":[{"en":"Reefs are threatened well beyond coastal areas.","zh":"珊瑚礁受到的威脅遠超沿岸地區。"},{"en":"Well beyond coastal areas means much farther than places near the sea edge.","zh":"well beyond coastal areas 指遠遠超出靠近海邊的地方。"},{"en":"Pollution can begin well beyond coastal areas and still reach the ocean through rivers.","zh":"污染可以起源於遠超沿岸地區的地方，仍透過河流到達海洋。"},{"en":"If dust travels well beyond coastal areas, distant reefs may be affected.","zh":"如果沙塵移動到遠超沿岸地區，遙遠珊瑚礁可能受影響。"},{"en":"This phrase shows that reef threats are not limited to nearby beaches.","zh":"這個片語顯示珊瑚礁威脅不限於附近海灘。"}],"source":"160 - Coral reefs.pdf","sourcePage":17},{"front":"general estimates suggest that","meaning":"一般估計顯示","examples":[{"en":"General estimates suggest that many reefs are dead or at risk.","zh":"一般估計顯示，許多珊瑚礁已死亡或處於危險之中。"},{"en":"General estimates suggest that means broad calculations indicate something is likely true.","zh":"general estimates suggest that 指廣泛估算顯示某事很可能為真。"},{"en":"General estimates suggest that the city needs more schools in the next decade.","zh":"一般估計顯示，這個城市在未來十年需要更多學校。"},{"en":"If general estimates suggest that costs will rise, planners should prepare early.","zh":"如果一般估計顯示成本會上升，規劃者應及早準備。"},{"en":"This phrase is used when figures are approximate but still informative.","zh":"當數字是大約但仍有參考價值時，會使用這個片語。"}],"source":"160 - Coral reefs.pdf","sourcePage":18},{"front":"approximately 10%","meaning":"約百分之十","examples":[{"en":"Approximately 10% of the world’s coral reefs are dead.","zh":"世界上約百分之十的珊瑚礁已死亡。"},{"en":"Approximately 10% means about one tenth, not an exact figure.","zh":"approximately 10% 指大約十分之一，不是精確數字。"},{"en":"Approximately 10% of the class arrived late after the bus delay.","zh":"巴士延誤後，班上約百分之十的學生遲到。"},{"en":"If approximately 10% of a budget is saved, the organisation has some flexibility.","zh":"如果預算中約百分之十被節省，機構就有一些彈性。"},{"en":"Approximately shows the number is close, but not perfectly precise.","zh":"approximately 顯示數字接近但並非完全精確。"}],"source":"160 - Coral reefs.pdf","sourcePage":18},{"front":"at risk","meaning":"處於危險之中","examples":[{"en":"About 60% of the world’s reefs are at risk.","zh":"世界上約60%的珊瑚礁處於危險之中。"},{"en":"At risk means in danger of being harmed, damaged, or lost.","zh":"at risk 指處於可能受傷害、損壞或失去的危險中。"},{"en":"Children without clean water are at risk of disease.","zh":"沒有清潔食水的兒童處於患病風險之中。"},{"en":"If a building is old and unsafe, residents may be at risk.","zh":"如果建築物老舊而不安全，居民可能處於危險之中。"},{"en":"Coral reefs at risk need protection before damage becomes irreversible.","zh":"處於危險中的珊瑚礁需要在損害不可逆轉前受到保護。"}],"source":"160 - Coral reefs.pdf","sourcePage":18},{"front":"due to","meaning":"由於","examples":[{"en":"Many reefs are at risk due to destructive human activities.","zh":"許多珊瑚礁由於具破壞性的人類活動而處於危險之中。"},{"en":"Due to means because of a particular cause or reason.","zh":"due to 指因為某個原因或理由。"},{"en":"The picnic was cancelled due to heavy rain.","zh":"野餐由於大雨而取消。"},{"en":"If a train is delayed due to signal problems, passengers may arrive late.","zh":"如果火車由於信號問題而延誤，乘客可能遲到。"},{"en":"Due to is useful when explaining the cause of a situation.","zh":"due to 在解釋情況原因時很有用。"}],"source":"160 - Coral reefs.pdf","sourcePage":18},{"front":"human-related activities","meaning":"與人類有關的活動","examples":[{"en":"Human-related activities threaten coral reefs.","zh":"與人類有關的活動威脅珊瑚礁。"},{"en":"Human-related activities are actions caused by people, communities, industries, or governments.","zh":"與人類有關的活動是由個人、社區、產業或政府造成的行動。"},{"en":"Farming, building, fishing, and tourism are all human-related activities.","zh":"農業、建築、捕魚和旅遊都是與人類有關的活動。"},{"en":"If human-related activities are poorly managed, natural habitats may suffer.","zh":"如果與人類有關的活動管理不善，自然棲息地可能受害。"},{"en":"The phrase helps separate human causes from natural causes.","zh":"這個片語有助把人為原因與自然原因分開。"}],"source":"160 - Coral reefs.pdf","sourcePage":18},{"front":"threat to the health of","meaning":"對……健康的威脅","examples":[{"en":"The threat to the health of reefs is particularly strong in Southeast Asia.","zh":"對珊瑚礁健康的威脅在東南亞特別嚴重。"},{"en":"A threat to the health of something is a danger that can damage its normal condition or function.","zh":"threat to the health of something 指可以破壞某物正常狀況或功能的危險。"},{"en":"Dirty air is a threat to the health of children and older people.","zh":"污濁空氣是對兒童和長者健康的威脅。"},{"en":"If pollution is a threat to the health of a river, fish and people may suffer.","zh":"如果污染是對河流健康的威脅，魚類和人類可能受害。"},{"en":"This phrase is useful for discussing harm to living systems.","zh":"這個片語在討論對生命系統的傷害時很有用。"}],"source":"160 - Coral reefs.pdf","sourcePage":18},{"front":"particularly strong","meaning":"特別嚴重","examples":[{"en":"The threat to reefs is particularly strong in Southeast Asia.","zh":"對珊瑚礁的威脅在東南亞特別嚴重。"},{"en":"Particularly strong means much more serious, powerful, or noticeable than usual.","zh":"particularly strong 指比平常嚴重、有力或明顯得多。"},{"en":"The wind was particularly strong near the harbour.","zh":"港口附近的風特別強。"},{"en":"If demand is particularly strong, shops may sell out quickly.","zh":"如果需求特別強勁，商店可能很快售罄。"},{"en":"This phrase highlights an unusually high level of force or importance.","zh":"這個片語強調力量或重要性達到異常高的程度。"}],"source":"160 - Coral reefs.pdf","sourcePage":18},{"front":"be endangered","meaning":"瀕危","examples":[{"en":"In Southeast Asia, 80% of reefs are endangered.","zh":"在東南亞，80%的珊瑚礁瀕危。"},{"en":"Be endangered means be in danger of serious harm, decline, or disappearance.","zh":"be endangered 指處於嚴重受害、衰退或消失的危險中。"},{"en":"Some animals are endangered because their habitats are destroyed.","zh":"有些動物因棲息地被破壞而瀕危。"},{"en":"If a language is endangered, fewer young people are learning it.","zh":"如果一種語言瀕危，學習它的年輕人就越來越少。"},{"en":"Endangered reefs need urgent protection before they decline further.","zh":"瀕危珊瑚礁需要在進一步衰退前得到緊急保護。"}],"source":"160 - Coral reefs.pdf","sourcePage":18},{"front":"be protected by","meaning":"受到……保護","examples":[{"en":"The Great Barrier Reef is protected by a marine park authority.","zh":"大堡礁受到海洋公園管理局保護。"},{"en":"Be protected by means receive defence, care, or legal support from someone or something.","zh":"be protected by 指受到某人或某物的防護、照顧或法律支持。"},{"en":"A historical building may be protected by government law.","zh":"歷史建築可能受到政府法律保護。"},{"en":"If a beach is protected by a reef, waves lose some force before reaching land.","zh":"如果海灘受到珊瑚礁保護，海浪到達陸地前會失去部分力量。"},{"en":"This phrase shows what provides safety or protection.","zh":"這個片語顯示是甚麼提供安全或保護。"}],"source":"160 - Coral reefs.pdf","sourcePage":18},{"front":"Marine Park Authority","meaning":"海洋公園管理局","examples":[{"en":"The Great Barrier Reef Marine Park Authority protects the reef.","zh":"大堡礁海洋公園管理局保護該珊瑚礁。"},{"en":"A Marine Park Authority is an organisation responsible for managing and protecting a marine park.","zh":"海洋公園管理局是負責管理和保護海洋公園的機構。"},{"en":"A Marine Park Authority may set rules for fishing, boating, and tourism.","zh":"海洋公園管理局可能制定捕魚、駕船和旅遊規則。"},{"en":"If a Marine Park Authority works well, it can reduce damage to sensitive sea areas.","zh":"如果海洋公園管理局運作良好，它可以減少敏感海域受損。"},{"en":"Such an authority connects science, law, and public education.","zh":"這類管理局把科學、法律和公眾教育連繫起來。"}],"source":"160 - Coral reefs.pdf","sourcePage":18},{"front":"be the subject of","meaning":"是……的對象","examples":[{"en":"The Great Barrier Reef is the subject of much legislation.","zh":"大堡礁是許多法例的對象。"},{"en":"Be the subject of means be the main thing discussed, studied, controlled, or affected by something.","zh":"be the subject of 指成為某事討論、研究、規管或影響的主要對象。"},{"en":"The new airport plan is the subject of public debate.","zh":"新機場計劃是公眾辯論的對象。"},{"en":"If a building is the subject of preservation laws, it cannot be freely demolished.","zh":"如果一座建築是保育法例的對象，它就不能被隨意拆除。"},{"en":"This phrase often appears in formal writing about laws, studies, or discussions.","zh":"這個片語常出現在關於法律、研究或討論的正式寫作中。"}],"source":"160 - Coral reefs.pdf","sourcePage":19},{"front":"legislation","meaning":"法例","examples":[{"en":"Much legislation protects the Great Barrier Reef.","zh":"許多法例保護大堡礁。"},{"en":"Legislation means laws made by a government or law-making body.","zh":"legislation 指由政府或立法機構制定的法律。"},{"en":"Legislation can require factories to reduce pollution.","zh":"法例可以要求工廠減少污染。"},{"en":"If legislation is weak, companies may damage nature without serious punishment.","zh":"如果法例薄弱，公司可能破壞自然而不受嚴重懲罰。"},{"en":"Strong legislation can turn environmental protection from advice into legal duty.","zh":"強有力的法例可以把環境保護從建議變成法律責任。"}],"source":"160 - Coral reefs.pdf","sourcePage":19},{"front":"biodiversity action plan","meaning":"生物多樣性行動計劃","examples":[{"en":"A biodiversity action plan helps protect the Great Barrier Reef.","zh":"生物多樣性行動計劃有助保護大堡礁。"},{"en":"A biodiversity action plan is a planned set of steps for protecting different species and habitats.","zh":"生物多樣性行動計劃是一套用於保護不同物種和棲息地的計劃步驟。"},{"en":"A city may create a biodiversity action plan to protect parks, birds, and wetlands.","zh":"城市可能制定生物多樣性行動計劃，以保護公園、鳥類和濕地。"},{"en":"If a biodiversity action plan has clear targets, progress can be measured.","zh":"如果生物多樣性行動計劃有清晰目標，進展就可以被量度。"},{"en":"Such a plan turns general concern for nature into practical action.","zh":"這類計劃把對自然的一般關注轉化為實際行動。"}],"source":"160 - Coral reefs.pdf","sourcePage":19},{"front":"inhabitants of","meaning":"……的居民","examples":[{"en":"The inhabitants of Ahus Island restrict fishing in their lagoon.","zh":"Ahus島的居民限制在他們的潟湖捕魚。"},{"en":"Inhabitants of a place are the people or animals who live there.","zh":"某地的居民是生活在那裡的人或動物。"},{"en":"The inhabitants of a village may share wells, roads, and local traditions.","zh":"一條村的居民可能共享水井、道路和本地傳統。"},{"en":"If the inhabitants of an island protect reefs, fish populations may recover.","zh":"如果一個島的居民保護珊瑚礁，魚類種群可能恢復。"},{"en":"This phrase is more formal than residents of.","zh":"這個片語比 residents of 更正式。"}],"source":"160 - Coral reefs.pdf","sourcePage":19},{"front":"generations-old practice","meaning":"延續多代的做法","examples":[{"en":"The islanders follow a generations-old practice of restricting fishing.","zh":"島民遵循限制捕魚這一延續多代的做法。"},{"en":"A generations-old practice is a custom or method used by many generations over a long time.","zh":"延續多代的做法是經許多代人長期使用的習俗或方法。"},{"en":"A family may keep a generations-old practice of cooking a special festival dish.","zh":"一個家庭可能保留烹調特別節日菜式的延續多代做法。"},{"en":"Generations-old practices can protect nature when they limit overuse of resources.","zh":"當延續多代的做法限制資源過度使用時，它們可以保護自然。"},{"en":"This phrase suggests tradition, continuity, and shared memory.","zh":"這個片語暗示傳統、延續和共同記憶。"}],"source":"160 - Coral reefs.pdf","sourcePage":19},{"front":"restrict fishing","meaning":"限制捕魚","examples":[{"en":"Some communities restrict fishing in reef lagoons.","zh":"一些社區限制在珊瑚礁潟湖捕魚。"},{"en":"Restrict fishing means limit where, when, how, or how much people can fish.","zh":"restrict fishing 指限制人們可以在哪裡、何時、如何或捕多少魚。"},{"en":"A lake authority may restrict fishing during the breeding season.","zh":"湖泊管理機構可能在繁殖季節限制捕魚。"},{"en":"If communities restrict fishing, fish may have time to grow and reproduce.","zh":"如果社區限制捕魚，魚類可能有時間生長和繁殖。"},{"en":"Restricting fishing can protect future catches, not simply reduce today’s income.","zh":"限制捕魚可以保護未來漁獲，而不只是減少今天的收入。"}],"source":"160 - Coral reefs.pdf","sourcePage":19},{"front":"reef lagoon","meaning":"珊瑚礁潟湖","examples":[{"en":"The people restrict fishing in six areas of their reef lagoon.","zh":"人們限制在他們珊瑚礁潟湖的六個區域捕魚。"},{"en":"A reef lagoon is a shallow area of water separated from the open sea by a coral reef.","zh":"珊瑚礁潟湖是被珊瑚礁與外海分隔的淺水區。"},{"en":"Children may swim in a calm reef lagoon when conditions are safe.","zh":"在環境安全時，孩子可能在平靜的珊瑚礁潟湖游泳。"},{"en":"A reef lagoon can provide shelter for young fish and other marine life.","zh":"珊瑚礁潟湖可以為幼魚和其他海洋生命提供庇護。"},{"en":"If a reef lagoon is overfished, the whole local reef system may be affected.","zh":"如果珊瑚礁潟湖被過度捕魚，整個本地珊瑚礁系統可能受影響。"}],"source":"160 - Coral reefs.pdf","sourcePage":19},{"front":"cultural traditions","meaning":"文化傳統","examples":[{"en":"Cultural traditions can help protect coral reefs.","zh":"文化傳統可以幫助保護珊瑚礁。"},{"en":"Cultural traditions are customs, beliefs, rules, or practices passed down within a community.","zh":"文化傳統是在社區中代代相傳的習俗、信念、規則或做法。"},{"en":"Cultural traditions may include festivals, food, songs, fishing rules, and respect for sacred places.","zh":"文化傳統可能包括節日、食物、歌曲、捕魚規則和對神聖地方的尊重。"},{"en":"When cultural traditions limit harmful behaviour, they can support environmental protection.","zh":"當文化傳統限制有害行為時，它們可以支持環境保護。"},{"en":"Traditions are strongest when people understand their purpose, not only repeat them.","zh":"當人們理解傳統的目的，而不只是重複它們，傳統就最強。"}],"source":"160 - Coral reefs.pdf","sourcePage":19},{"front":"line fishing","meaning":"釣魚；用魚線捕魚","examples":[{"en":"Their traditions allow line fishing.","zh":"他們的傳統容許用魚線捕魚。"},{"en":"Line fishing is catching fish with a line and hook rather than a net or explosive.","zh":"line fishing 是用魚線和魚鉤捕魚，而不是用漁網或炸藥。"},{"en":"A person may practise line fishing from a small boat or pier.","zh":"一個人可能在小船或碼頭上用魚線捕魚。"},{"en":"Line fishing can be less damaging when it targets fewer fish and avoids breaking coral.","zh":"當用魚線捕魚只針對較少魚並避免破壞珊瑚時，破壞性可以較低。"},{"en":"It still needs rules if too many people fish in the same area.","zh":"如果太多人在同一地區捕魚，它仍然需要規則。"}],"source":"160 - Coral reefs.pdf","sourcePage":19},{"front":"net or spearfishing","meaning":"網捕或魚叉捕魚","examples":[{"en":"Their traditions do not allow net or spearfishing.","zh":"他們的傳統不容許網捕或魚叉捕魚。"},{"en":"Net or spearfishing means catching fish with nets or with spear-like tools.","zh":"net or spearfishing 指使用漁網或像魚叉的工具捕魚。"},{"en":"Some communities restrict net or spearfishing to protect young fish and reef habitats.","zh":"一些社區限制網捕或魚叉捕魚，以保護幼魚和珊瑚礁棲息地。"},{"en":"If net or spearfishing removes too many fish, local populations may decline.","zh":"如果網捕或魚叉捕魚捕走太多魚，本地種群可能下降。"},{"en":"These methods can be acceptable in some places but harmful if unmanaged.","zh":"這些方法在某些地方可以接受，但若缺乏管理則可能有害。"}],"source":"160 - Coral reefs.pdf","sourcePage":19},{"front":"as a result","meaning":"因此","examples":[{"en":"As a result, fish biomass is larger in protected areas.","zh":"因此，受保護區域中的魚類生物量較大。"},{"en":"As a result means because of what happened before, this consequence followed.","zh":"as a result 指由於前面發生的事，後面出現了這個結果。"},{"en":"The road was closed; as a result, many students arrived late.","zh":"道路封閉；因此，許多學生遲到了。"},{"en":"If fishing is restricted, as a result, fish may grow larger and more numerous.","zh":"如果捕魚受到限制，因此魚類可能長得更大、數量更多。"},{"en":"This phrase clearly connects cause and effect.","zh":"這個片語清楚連接原因和結果。"}],"source":"160 - Coral reefs.pdf","sourcePage":20},{"front":"biomass","meaning":"生物量","examples":[{"en":"The biomass is larger where fishing is restricted.","zh":"在限制捕魚的地方，生物量較大。"},{"en":"Biomass is the total mass of living organisms in a particular area or group.","zh":"生物量是某一地區或群體中活生物的總質量。"},{"en":"A forest with many large trees has high plant biomass.","zh":"擁有許多大樹的森林有較高植物生物量。"},{"en":"If fish biomass increases, there is more living fish matter in that area.","zh":"如果魚類生物量增加，該區就有更多活魚物質。"},{"en":"Biomass helps scientists measure life in an ecosystem, not just count species.","zh":"生物量幫助科學家量度生態系統中的生命，而不只是計算物種。"}],"source":"160 - Coral reefs.pdf","sourcePage":20},{"front":"individual fish sizes","meaning":"個別魚隻大小","examples":[{"en":"Individual fish sizes are larger in restricted areas.","zh":"在受限制區域中，個別魚隻大小較大。"},{"en":"Individual fish sizes refer to how big each separate fish is.","zh":"個別魚隻大小指每一條魚各自有多大。"},{"en":"A fisherman may record individual fish sizes to check whether the population is healthy.","zh":"漁民可能記錄個別魚隻大小，以檢查種群是否健康。"},{"en":"If small fish are allowed to grow, individual fish sizes may increase over time.","zh":"如果小魚獲准生長，個別魚隻大小可能隨時間增加。"},{"en":"Larger individual fish sizes can suggest that fishing pressure is lower.","zh":"較大的個別魚隻大小可以顯示捕魚壓力較低。"}],"source":"160 - Coral reefs.pdf","sourcePage":20},{"front":"significantly larger","meaning":"顯著較大","examples":[{"en":"Fish are significantly larger in areas where fishing is restricted.","zh":"在限制捕魚的區域中，魚顯著較大。"},{"en":"Significantly larger means clearly and meaningfully bigger, not just slightly bigger.","zh":"significantly larger 指明顯而有意義地更大，不只是稍微大一點。"},{"en":"The new classroom is significantly larger than the old one, so more students can sit comfortably.","zh":"新課室比舊課室顯著較大，所以更多學生可以舒適地坐下。"},{"en":"If protected fish are significantly larger, the rules may be working.","zh":"如果受保護的魚顯著較大，規則可能正在發揮作用。"},{"en":"This phrase is often used when a difference is important enough to notice.","zh":"當差異重要到足以被注意時，常使用這個片語。"}],"source":"160 - Coral reefs.pdf","sourcePage":20},{"front":"unrestricted","meaning":"不受限制的","examples":[{"en":"Fish sizes are smaller in places where fishing is unrestricted.","zh":"在捕魚不受限制的地方，魚的大小較小。"},{"en":"Unrestricted means not limited by rules, controls, or boundaries.","zh":"unrestricted 指不受規則、控制或界線限制。"},{"en":"Unrestricted phone use in class can make students lose focus.","zh":"課堂中不受限制地使用手機可以令學生失去專注。"},{"en":"If fishing is unrestricted, too many fish may be removed from one area.","zh":"如果捕魚不受限制，太多魚可能從一個地區被捕走。"},{"en":"Unrestricted freedom can create problems when people’s actions affect others.","zh":"當人的行動影響他人時，不受限制的自由可能造成問題。"}],"source":"160 - Coral reefs.pdf","sourcePage":20},{"front":"geographical distribution","meaning":"地理分布","examples":[{"en":"The passage describes the geographical distribution of the world’s coral reefs.","zh":"文章描述了世界珊瑚礁的地理分布。"},{"en":"Geographical distribution means how something is spread across different places or regions.","zh":"地理分布指某物在不同地方或地區中的分布方式。"},{"en":"A map can show the geographical distribution of schools in a city.","zh":"地圖可以顯示城市中學校的地理分布。"},{"en":"If the geographical distribution of clinics is uneven, some people may travel far for care.","zh":"如果診所的地理分布不均，有些人可能要走很遠才能得到照護。"},{"en":"This phrase is useful when describing where things are found.","zh":"這個片語在描述事物出現在哪裡時很有用。"}],"source":"160 - Coral reefs.pdf","sourcePage":20},{"front":"benefit local economies","meaning":"令本地經濟受惠","examples":[{"en":"Coral reefs benefit local economies through tourism and fishing.","zh":"珊瑚礁透過旅遊和捕魚令本地經濟受惠。"},{"en":"Benefit local economies means help nearby communities earn income and create jobs.","zh":"benefit local economies 指幫助附近社區獲得收入和創造工作。"},{"en":"A new market can benefit local economies by giving small farmers a place to sell food.","zh":"新市場可以給小農出售食物的地方，從而令本地經濟受惠。"},{"en":"If reefs attract tourists, they can benefit local economies through hotels, boats, and restaurants.","zh":"如果珊瑚礁吸引遊客，它們可以透過酒店、船隻和餐廳令本地經濟受惠。"},{"en":"Local economies benefit most when money stays in the community.","zh":"當金錢留在社區中，本地經濟最能受惠。"}],"source":"160 - Coral reefs.pdf","sourcePage":20},{"front":"economic significance","meaning":"經濟重要性","examples":[{"en":"The statistics demonstrate the economic significance of coral reefs.","zh":"這些統計數字展示了珊瑚礁的經濟重要性。"},{"en":"Economic significance means the importance of something in terms of money, jobs, trade, or livelihoods.","zh":"經濟重要性指某物在金錢、工作、貿易或生計方面的重要性。"},{"en":"A port has economic significance because it supports shipping and employment.","zh":"港口具有經濟重要性，因為它支持航運和就業。"},{"en":"If reef tourism earns millions, the economic significance of reefs becomes clear.","zh":"如果珊瑚礁旅遊賺取數百萬，珊瑚礁的經濟重要性就變得清楚。"},{"en":"This phrase is useful when numbers show why something matters financially.","zh":"當數字顯示某物在財政上為何重要時，這個片語很有用。"}],"source":"160 - Coral reefs.pdf","sourcePage":20},{"front":"decline in coral reefs","meaning":"珊瑚礁衰退","examples":[{"en":"The passage lists reasons for the decline in coral reefs.","zh":"文章列出珊瑚礁衰退的原因。"},{"en":"A decline in coral reefs means a reduction in their health, size, number, or quality.","zh":"珊瑚礁衰退指其健康、大小、數量或質素下降。"},{"en":"Scientists may measure a decline in coral reefs by checking coral cover over time.","zh":"科學家可能透過檢查珊瑚覆蓋隨時間變化來量度珊瑚礁衰退。"},{"en":"Pollution, warming seas, and destructive fishing can cause a decline in coral reefs.","zh":"污染、海洋變暖和破壞性捕魚都可以造成珊瑚礁衰退。"},{"en":"A decline in coral reefs affects wildlife, tourism, fishing, and coastal protection.","zh":"珊瑚礁衰退會影響野生生物、旅遊、捕魚和海岸保護。"}],"source":"160 - Coral reefs.pdf","sourcePage":20},{"front":"physical contact with","meaning":"與……的身體接觸","examples":[{"en":"Physical contact with coral reefs can damage them.","zh":"與珊瑚礁的身體接觸可以破壞它們。"},{"en":"Physical contact with means directly touching, hitting, stepping on, or rubbing against something.","zh":"physical contact with 指直接觸碰、撞擊、踩踏或摩擦某物。"},{"en":"Physical contact with a wet painting can ruin its surface.","zh":"與未乾畫作的身體接觸可以破壞其表面。"},{"en":"If tourists make physical contact with coral, they may break living structures.","zh":"如果遊客與珊瑚有身體接觸，他們可能折斷活結構。"},{"en":"Sometimes avoiding physical contact is the simplest way to protect fragile things.","zh":"有時避免身體接觸是保護脆弱事物最簡單的方法。"}],"source":"160 - Coral reefs.pdf","sourcePage":20},{"front":"unsustainable fishing methods","meaning":"不可持續的捕魚方法","examples":[{"en":"The passage describes unsustainable fishing methods used around the world.","zh":"文章描述世界各地使用的不可持續捕魚方法。"},{"en":"Unsustainable fishing methods are ways of catching fish that damage habitats or remove fish too quickly.","zh":"不可持續的捕魚方法是破壞棲息地或過快捕走魚類的方式。"},{"en":"Using explosives is an unsustainable fishing method because it destroys future breeding areas.","zh":"使用炸藥是一種不可持續的捕魚方法，因為它摧毀未來繁殖區。"},{"en":"If unsustainable fishing methods continue, fishers may lose their income later.","zh":"如果不可持續的捕魚方法持續，漁民日後可能失去收入。"},{"en":"Sustainable methods protect both today’s catch and tomorrow’s fish population.","zh":"可持續方法同時保護今天的漁獲和明天的魚類種群。"}],"source":"160 - Coral reefs.pdf","sourcePage":21},{"front":"agree with the information given","meaning":"與所給資料一致","examples":[{"en":"Students decide whether statements agree with the information given.","zh":"學生判斷陳述是否與所給資料一致。"},{"en":"Agree with the information given means match what the passage says.","zh":"agree with the information given 指與文章所說內容相符。"},{"en":"In a reading test, an answer agrees with the information given only if the text clearly supports it.","zh":"在閱讀測驗中，只有當文本清楚支持某答案，它才與所給資料一致。"},{"en":"If a statement changes the meaning of the text, it does not agree with the information given.","zh":"如果一個陳述改變文本意思，它就不是與所給資料一致。"},{"en":"This phrase is common in true, false, and not given questions.","zh":"這個片語常見於 true、false 和 not given 題目中。"}],"source":"160 - Coral reefs.pdf","sourcePage":21},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與文章中的資料相矛盾。"},{"en":"Contradict the information means say the opposite of what the text states.","zh":"contradict the information 指說出與文本陳述相反的內容。"},{"en":"If a text says the shop closes at six, “it closes at eight” contradicts the information.","zh":"如果文本說商店六點關門，「它八點關門」就與資料相矛盾。"},{"en":"A statement may look similar but still contradict the information by changing one key detail.","zh":"一個陳述可能看似相似，但改變一個關鍵細節後仍與資料相矛盾。"},{"en":"In reading tests, contradiction is different from missing information.","zh":"在閱讀測驗中，矛盾不同於資料缺失。"}],"source":"160 - Coral reefs.pdf","sourcePage":21},{"front":"no information on this","meaning":"沒有這方面的資料","examples":[{"en":"Write NOT GIVEN if there is no information on this.","zh":"如果沒有這方面的資料，寫 NOT GIVEN。"},{"en":"No information on this means the text does not say anything clear about that point.","zh":"no information on this 指文本沒有清楚說明那一點。"},{"en":"If an article describes a school but not its fees, there is no information on this cost.","zh":"如果一篇文章描述一所學校但沒有說學費，就沒有這方面的資料。"},{"en":"When there is no information on this, students should not guess from outside knowledge.","zh":"當沒有這方面的資料時，學生不應根據外部知識猜測。"},{"en":"This phrase helps separate unsupported ideas from true or false statements.","zh":"這個片語幫助把沒有支持的想法與正確或錯誤陳述分開。"}],"source":"160 - Coral reefs.pdf","sourcePage":21},{"front":"provide habitats for","meaning":"為……提供棲息地","examples":[{"en":"Coral reefs provide habitats for a variety of marine life.","zh":"珊瑚礁為各式各樣的海洋生物提供棲息地。"},{"en":"Provide habitats for means give living things places where they can live, feed, hide, or reproduce.","zh":"provide habitats for 指為生物提供生活、覓食、躲藏或繁殖的地方。"},{"en":"Street trees provide habitats for birds and insects.","zh":"街樹為鳥類和昆蟲提供棲息地。"},{"en":"If wetlands disappear, they no longer provide habitats for frogs and water birds.","zh":"如果濕地消失，它們就不再為青蛙和水鳥提供棲息地。"},{"en":"Coral reefs provide habitats for animals that need shelter from open water.","zh":"珊瑚礁為需要避開開闊水域的動物提供棲息地。"}],"source":"160 - Coral reefs.pdf","sourcePage":21},{"front":"a variety of marine life","meaning":"各式各樣的海洋生物","examples":[{"en":"Coral reefs support a variety of marine life.","zh":"珊瑚礁支持各式各樣的海洋生物。"},{"en":"A variety of marine life means many different kinds of sea organisms.","zh":"a variety of marine life 指許多不同種類的海洋生物。"},{"en":"A rock pool can contain a variety of marine life, such as crabs, small fish, and seaweed.","zh":"岩池可以包含各式各樣的海洋生物，例如蟹、小魚和海藻。"},{"en":"Healthy reefs support a variety of marine life by offering food and shelter.","zh":"健康珊瑚礁透過提供食物和庇護，支持各式各樣的海洋生物。"},{"en":"The phrase emphasises difference and richness, not just large numbers.","zh":"這個片語強調差異和豐富性，而不只是數量多。"}],"source":"160 - Coral reefs.pdf","sourcePage":21},{"front":"be distributed disproportionately","meaning":"分布不成比例；分布不均","examples":[{"en":"Coral reefs are distributed disproportionately throughout the oceans.","zh":"珊瑚礁在海洋中的分布不成比例。"},{"en":"Be distributed disproportionately means be spread unevenly, with much more in some places than others.","zh":"be distributed disproportionately 指分布不均，有些地方遠多於其他地方。"},{"en":"Parks may be distributed disproportionately across a city, leaving some districts with few green spaces.","zh":"公園可能在城市中分布不均，令某些地區幾乎沒有綠地。"},{"en":"If resources are distributed disproportionately, some communities may benefit far more than others.","zh":"如果資源分布不均，一些社區可能比其他社區受惠多得多。"},{"en":"This phrase helps explain unfair or uneven patterns.","zh":"這個片語有助解釋不公平或不平均的模式。"}],"source":"160 - Coral reefs.pdf","sourcePage":21},{"front":"throughout the oceans","meaning":"遍佈海洋","examples":[{"en":"Coral reefs are not evenly distributed throughout the oceans.","zh":"珊瑚礁並非均勻遍佈海洋。"},{"en":"Throughout the oceans means across many parts of the world’s seas and oceans.","zh":"throughout the oceans 指遍及世界海洋的許多部分。"},{"en":"Plastic waste has been found throughout the oceans, even far from cities.","zh":"塑膠廢物已在海洋各處被發現，甚至遠離城市的地方。"},{"en":"If a species spreads throughout the oceans, it may appear in many different regions.","zh":"如果某物種遍佈海洋，它可能出現在許多不同地區。"},{"en":"This phrase suggests a wide area, not one single sea.","zh":"這個片語表示廣闊範圍，而不是單一海域。"}],"source":"160 - Coral reefs.pdf","sourcePage":21},{"front":"scientific purposes","meaning":"科學用途","examples":[{"en":"The question asks whether coral reefs are becoming important for scientific purposes.","zh":"題目問珊瑚礁是否正變得對科學用途重要。"},{"en":"Scientific purposes are reasons connected with research, testing, observation, or gaining knowledge.","zh":"科學用途是與研究、測試、觀察或獲取知識有關的目的。"},{"en":"A university may collect water samples for scientific purposes.","zh":"大學可能為科學用途收集水樣本。"},{"en":"If coral reefs are studied for scientific purposes, researchers may learn how ecosystems respond to stress.","zh":"如果珊瑚礁被用於科學用途研究，研究人員可能了解生態系統如何回應壓力。"},{"en":"This phrase explains why something is used in science, not business or entertainment.","zh":"這個片語解釋某物為何用於科學，而不是商業或娛樂。"}],"source":"160 - Coral reefs.pdf","sourcePage":21},{"front":"widely traded and exported","meaning":"被廣泛買賣和出口","examples":[{"en":"The statement asks whether coral reefs are widely traded and exported.","zh":"該陳述問珊瑚礁是否被廣泛買賣和出口。"},{"en":"Widely traded and exported means bought, sold, and sent to other countries on a large scale.","zh":"widely traded and exported 指被大規模買賣並送往其他國家。"},{"en":"Coffee is widely traded and exported from many producing countries.","zh":"咖啡由許多生產國廣泛買賣和出口。"},{"en":"If a product is widely traded and exported, global demand may affect local prices.","zh":"如果一種產品被廣泛買賣和出口，全球需求可能影響本地價格。"},{"en":"Coral reef animals may be traded, but the reef itself is not usually treated like ordinary goods.","zh":"珊瑚礁動物可能被買賣，但珊瑚礁本身通常不會像普通商品一樣處理。"}],"source":"160 - Coral reefs.pdf","sourcePage":21},{"front":"reef tourism","meaning":"珊瑚礁旅遊","examples":[{"en":"Reef tourism is economically important for many communities.","zh":"珊瑚礁旅遊對許多社區具有經濟重要性。"},{"en":"Reef tourism is travel connected with visiting coral reefs for diving, snorkelling, boating, or sightseeing.","zh":"珊瑚礁旅遊是與到訪珊瑚礁進行潛水、浮潛、乘船或觀光有關的旅遊。"},{"en":"A village may earn income from reef tourism through guides, boats, and guesthouses.","zh":"一條村可能透過導遊、船隻和旅館從珊瑚礁旅遊中獲得收入。"},{"en":"If reefs become damaged, reef tourism may decline and local jobs may disappear.","zh":"如果珊瑚礁受損，珊瑚礁旅遊可能下降，本地工作可能消失。"},{"en":"Reef tourism works best when visitors enjoy reefs without harming them.","zh":"當遊客欣賞珊瑚礁而不傷害它們時，珊瑚礁旅遊最有效。"}],"source":"160 - Coral reefs.pdf","sourcePage":22},{"front":"economically important","meaning":"具經濟重要性","examples":[{"en":"Reef tourism is economically important, particularly for some poor people.","zh":"珊瑚礁旅遊具經濟重要性，尤其對一些貧窮人士而言。"},{"en":"Economically important means significant for income, jobs, trade, or financial survival.","zh":"economically important 指對收入、工作、貿易或財政生存具有重要性。"},{"en":"A local market is economically important because many small sellers depend on it.","zh":"本地市場具經濟重要性，因為許多小販依賴它。"},{"en":"If tourism is economically important to an island, reef damage can become a serious social problem.","zh":"如果旅遊對一個島嶼具經濟重要性，珊瑚礁破壞就可能變成嚴重社會問題。"},{"en":"This phrase explains why something matters in practical financial terms.","zh":"這個片語解釋某事為何在實際財政層面重要。"}],"source":"160 - Coral reefs.pdf","sourcePage":22},{"front":"particularly for","meaning":"尤其對……","examples":[{"en":"Reef tourism matters particularly for some poor people.","zh":"珊瑚礁旅遊很重要，尤其對一些貧窮人士而言。"},{"en":"Particularly for means especially important or relevant to a certain group.","zh":"particularly for 指對某一群體尤其重要或相關。"},{"en":"Free school meals matter particularly for children from low-income families.","zh":"免費校餐很重要，尤其對低收入家庭的兒童而言。"},{"en":"If a service matters particularly for older people, it should be easy to reach.","zh":"如果某項服務尤其對長者重要，它就應該容易到達。"},{"en":"This phrase shows which group is most affected.","zh":"這個片語顯示哪個群體最受影響。"}],"source":"160 - Coral reefs.pdf","sourcePage":22},{"front":"coral-reef fisheries","meaning":"珊瑚礁漁業","examples":[{"en":"Coral-reef fisheries support many small-scale fishers.","zh":"珊瑚礁漁業支持許多小規模漁民。"},{"en":"Coral-reef fisheries are fishing activities based around fish and sea life living on or near coral reefs.","zh":"珊瑚礁漁業是圍繞生活在珊瑚礁上或附近的魚類和海洋生命而進行的捕魚活動。"},{"en":"Families in coastal villages may depend on coral-reef fisheries for daily food.","zh":"沿海村莊的家庭可能依賴珊瑚礁漁業獲取日常食物。"},{"en":"If coral-reef fisheries are overused, fish populations and incomes may both fall.","zh":"如果珊瑚礁漁業被過度使用，魚類種群和收入可能同時下降。"},{"en":"Healthy coral-reef fisheries need healthy reef habitats.","zh":"健康的珊瑚礁漁業需要健康的珊瑚礁棲息地。"}],"source":"160 - Coral reefs.pdf","sourcePage":22},{"front":"unsuitable for","meaning":"不適合……","examples":[{"en":"The statement asks whether coral-reef fisheries are unsuitable for women and children.","zh":"該陳述問珊瑚礁漁業是否不適合婦女和兒童。"},{"en":"Unsuitable for means not appropriate, safe, or useful for a particular person, group, or purpose.","zh":"unsuitable for 指對特定人士、群體或目的而言不合適、不安全或無用。"},{"en":"A difficult hiking route may be unsuitable for young children.","zh":"困難的遠足路線可能不適合年幼兒童。"},{"en":"If equipment is unsuitable for beginners, they may get hurt or discouraged.","zh":"如果設備不適合初學者，他們可能受傷或感到挫敗。"},{"en":"This phrase explains a mismatch between something and the people who use it.","zh":"這個片語解釋某物與使用者之間的不配合。"}],"source":"160 - Coral reefs.pdf","sourcePage":22},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students must choose the correct letter from the options.","zh":"學生必須從選項中選出正確字母。"},{"en":"Choose the correct letter means select the answer label that matches the right option.","zh":"choose the correct letter 指選出與正確選項相符的答案字母。"},{"en":"In a multiple-choice question, students may choose the correct letter A, B, C, or D.","zh":"在選擇題中，學生可能要選出正確字母A、B、C或D。"},{"en":"If students choose the wrong letter, the answer may be marked incorrect even if their idea is close.","zh":"如果學生選錯字母，即使想法接近，答案也可能被判錯。"},{"en":"This instruction tells students to write the option label, not a full sentence.","zh":"這個指示告訴學生寫選項字母，而不是完整句子。"}],"source":"160 - Coral reefs.pdf","sourcePage":22},{"front":"main purpose of the passage","meaning":"文章主要目的","examples":[{"en":"The question asks for the main purpose of the passage.","zh":"題目詢問文章主要目的。"},{"en":"The main purpose of the passage is the writer’s central reason for writing it.","zh":"文章主要目的是作者寫作該文的核心原因。"},{"en":"A passage may have details, but its main purpose could be to explain a problem.","zh":"一篇文章可能有細節，但其主要目的可能是解釋一個問題。"},{"en":"If students confuse details with the main purpose of the passage, they may choose the wrong answer.","zh":"如果學生把細節與文章主要目的混淆，他們可能選錯答案。"},{"en":"This phrase asks what the whole text is mainly trying to do.","zh":"這個片語問整篇文章主要想做甚麼。"}],"source":"160 - Coral reefs.pdf","sourcePage":22},{"front":"demonstrate how","meaning":"展示……如何","examples":[{"en":"The option says the passage demonstrates how coral reefs grow.","zh":"該選項說文章展示珊瑚礁如何生長。"},{"en":"Demonstrate how means show or explain the way something happens or is done.","zh":"demonstrate how 指展示或解釋某事如何發生或如何完成。"},{"en":"A teacher may demonstrate how to solve a maths problem on the board.","zh":"老師可能在白板上展示如何解一道數學題。"},{"en":"Diagrams can demonstrate how water moves through a plant.","zh":"圖表可以展示水如何在植物中移動。"},{"en":"This phrase focuses on explaining a process clearly.","zh":"這個片語重點在於清楚解釋一個過程。"}],"source":"160 - Coral reefs.pdf","sourcePage":22},{"front":"be widely used in","meaning":"被廣泛用於","examples":[{"en":"The option says coral reefs are widely used in scientific projects.","zh":"該選項說珊瑚礁被廣泛用於科學項目。"},{"en":"Be widely used in means be used by many people or in many situations within a field.","zh":"be widely used in 指在某一領域中被許多人或許多情況使用。"},{"en":"Tablets are widely used in schools for reading and homework.","zh":"平板電腦被廣泛用於學校中的閱讀和功課。"},{"en":"If a method is widely used in hospitals, doctors and nurses often rely on it.","zh":"如果一種方法被廣泛用於醫院，醫生和護士常會依賴它。"},{"en":"Widely used in shows broad use, not just one example.","zh":"widely used in 顯示廣泛使用，而不只是單一例子。"}],"source":"160 - Coral reefs.pdf","sourcePage":22},{"front":"present the general benefits of","meaning":"呈現……的一般好處","examples":[{"en":"The passage presents the general benefits of coral reefs.","zh":"文章呈現珊瑚礁的一般好處。"},{"en":"Present the general benefits of means show the main advantages of something in a broad way.","zh":"present the general benefits of 指以概括方式展示某事物的主要優點。"},{"en":"A brochure may present the general benefits of exercise before giving a detailed plan.","zh":"宣傳冊可能先呈現運動的一般好處，再提供詳細計劃。"},{"en":"If a speech presents the general benefits of recycling, it may mention cleaner streets and less waste.","zh":"如果演講呈現回收的一般好處，它可能提到街道更清潔和廢物更少。"},{"en":"This phrase focuses on overall advantages rather than tiny details.","zh":"這個片語重點在於整體優點，而不是細小細節。"}],"source":"160 - Coral reefs.pdf","sourcePage":22},{"front":"alarming situation","meaning":"令人憂慮的情況","examples":[{"en":"The passage also presents the alarming situation coral reefs face.","zh":"文章也呈現珊瑚礁面對的令人憂慮的情況。"},{"en":"An alarming situation is a serious and worrying condition that needs attention.","zh":"令人憂慮的情況是需要關注的嚴重而令人擔心的狀況。"},{"en":"A sudden rise in hospital infections would be an alarming situation.","zh":"醫院感染突然上升會是令人憂慮的情況。"},{"en":"If many reefs are dying, this is an alarming situation for coastal communities.","zh":"如果許多珊瑚礁正在死亡，這對沿海社區而言是令人憂慮的情況。"},{"en":"Alarming does not just mean bad; it means serious enough to cause concern.","zh":"alarming 不只是不好，而是嚴重到令人關注。"}],"source":"160 - Coral reefs.pdf","sourcePage":23},{"front":"efforts being made to","meaning":"正在作出的努力","examples":[{"en":"The final paragraph mentions efforts being made to protect coral reefs.","zh":"最後一段提到正在作出的保護珊瑚礁努力。"},{"en":"Efforts being made to means actions currently being taken to achieve a goal.","zh":"efforts being made to 指目前為達成目標而採取的行動。"},{"en":"Efforts being made to reduce school bullying include counselling and clearer rules.","zh":"正在作出的減少校園欺凌努力包括輔導和更清晰規則。"},{"en":"If efforts being made to protect reefs continue, damaged areas may recover slowly.","zh":"如果正在作出的保護珊瑚礁努力持續，受損地區可能慢慢恢復。"},{"en":"This phrase shows that people are already trying to solve a problem.","zh":"這個片語顯示人們已經在嘗試解決問題。"}],"source":"160 - Coral reefs.pdf","sourcePage":23},{"front":"protect coral reefs","meaning":"保護珊瑚礁","examples":[{"en":"Some authorities and communities take action to protect coral reefs.","zh":"一些政府機構和社區採取行動保護珊瑚礁。"},{"en":"Protect coral reefs means keep reefs safe from damage, pollution, overuse, or destruction.","zh":"protect coral reefs 指保護珊瑚礁免受破壞、污染、過度使用或摧毀。"},{"en":"Tourists can protect coral reefs by not touching coral or dropping anchors on it.","zh":"遊客可以透過不觸碰珊瑚或不把錨拋在珊瑚上來保護珊瑚礁。"},{"en":"Governments protect coral reefs by creating marine parks and limiting harmful fishing.","zh":"政府透過建立海洋公園和限制有害捕魚來保護珊瑚礁。"},{"en":"Protecting coral reefs also protects fish, coastlines, jobs, and future generations.","zh":"保護珊瑚礁也保護魚類、海岸線、工作和未來世代。"}],"source":"160 - Coral reefs.pdf","sourcePage":23}],"ielts/reading/passage-2/Practice 161":[{"front":"El Niño and seabirds","meaning":"厄爾尼諾現象與海鳥","examples":[{"en":"The passage discusses how El Niño may affect seabirds and marine ecosystems.","zh":"文章討論厄爾尼諾現象可能如何影響海鳥和海洋生態系統。"},{"en":"El Niño and seabirds refers to the study of how this climate event affects birds that live and feed at sea.","zh":"「厄爾尼諾現象與海鳥」指研究這種氣候事件如何影響在海上生活和覓食的鳥類。"},{"en":"During an El Niño year, seabirds may have to fly farther because fish move to different waters.","zh":"在厄爾尼諾年份，海鳥可能要飛得更遠，因為魚會移到不同水域。"},{"en":"Warmer seas can reduce food for seabirds, so fewer chicks may survive.","zh":"較溫暖的海水可能減少海鳥的食物，因此較少雛鳥能存活。"},{"en":"Studying El Niño and seabirds helps scientists understand how climate changes affect ocean life.","zh":"研究厄爾尼諾現象與海鳥，能幫助科學家理解氣候變化如何影響海洋生命。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":1},{"front":"the rhythm of the seasons","meaning":"季節節奏","examples":[{"en":"The rhythm of the seasons cannot always be relied upon.","zh":"季節節奏不能總是被依賴。"},{"en":"The rhythm of the seasons means the usual yearly pattern of spring, summer, autumn and winter.","zh":"「季節節奏」指春、夏、秋、冬一年中通常出現的規律。"},{"en":"Farmers depend on the rhythm of the seasons when deciding when to plant crops.","zh":"農民在決定何時種植農作物時，會依靠季節節奏。"},{"en":"If the rhythm of the seasons changes, animals may breed or migrate at the wrong time.","zh":"如果季節節奏改變，動物可能會在錯誤時間繁殖或遷徙。"},{"en":"Climate change can make the rhythm of the seasons less predictable.","zh":"氣候變化可能令季節節奏變得較難預測。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":1},{"front":"cannot always be relied upon","meaning":"不能總是被依賴","examples":[{"en":"The rhythm of the seasons cannot always be relied upon.","zh":"季節節奏不能總是被依賴。"},{"en":"If something cannot always be relied upon, it is not dependable in every situation.","zh":"如果某事物不能總是被依賴，意思是它不是在每種情況下都可靠。"},{"en":"Weather forecasts cannot always be relied upon when storms develop suddenly.","zh":"當風暴突然形成時，天氣預報不能總是被依賴。"},{"en":"Old study methods cannot always be relied upon if the exam format changes.","zh":"如果考試形式改變，舊有溫習方法不能總是被依賴。"},{"en":"A single source of information cannot always be relied upon, so students should check carefully.","zh":"單一資訊來源不能總是被依賴，所以學生應仔細核對。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":1},{"front":"at times","meaning":"有時","examples":[{"en":"At times, the tropical Pacific Ocean behaves unpredictably.","zh":"有時，熱帶太平洋的運作會難以預測。"},{"en":"At times means sometimes, especially when something does not happen all the time.","zh":"「at times」意思是有時，尤其指某事不是一直發生。"},{"en":"At times, even a careful student may feel nervous before an exam.","zh":"有時，即使是細心的學生，在考試前也可能感到緊張。"},{"en":"Public transport can be crowded at times, especially during rush hour.","zh":"公共交通有時會很擠迫，特別是在繁忙時間。"},{"en":"A normally calm sea can, at times, become dangerous after strong winds.","zh":"平時平靜的大海，有時會在強風後變得危險。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":1},{"front":"the tropical Pacific Ocean","meaning":"熱帶太平洋","examples":[{"en":"El Niño begins with changes in the tropical Pacific Ocean.","zh":"厄爾尼諾現象始於熱帶太平洋的變化。"},{"en":"The tropical Pacific Ocean is the warm ocean area near the equator in the Pacific.","zh":"「熱帶太平洋」是太平洋中靠近赤道的溫暖海域。"},{"en":"Scientists watch the tropical Pacific Ocean closely because small temperature changes there can affect weather worldwide.","zh":"科學家密切觀察熱帶太平洋，因為那裡細微的溫度變化也可能影響全球天氣。"},{"en":"When the tropical Pacific Ocean becomes unusually warm, rainfall patterns may shift.","zh":"當熱帶太平洋變得異常溫暖，降雨模式可能會轉移。"},{"en":"Events in the tropical Pacific Ocean can influence storms, droughts and marine food supplies.","zh":"熱帶太平洋發生的事件，可以影響風暴、乾旱和海洋食物供應。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":1},{"front":"large expanses of","meaning":"大片……","examples":[{"en":"Large expanses of the global atmosphere can behave unusually.","zh":"大片全球大氣可能會異常運作。"},{"en":"Large expanses of something are very wide areas of it.","zh":"「large expanses of」指非常廣闊的大片範圍。"},{"en":"Large expanses of farmland were damaged after weeks without rain.","zh":"連續數星期沒有下雨後，大片農田受損。"},{"en":"Large expanses of sea ice can melt when temperatures remain high.","zh":"當溫度持續偏高，大片海冰可能融化。"},{"en":"From the plane, passengers could see large expanses of desert below.","zh":"從飛機上，乘客可以看見下方大片沙漠。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":1},{"front":"the global atmosphere","meaning":"全球大氣","examples":[{"en":"The global atmosphere can be affected by El Niño.","zh":"全球大氣可能受到厄爾尼諾現象影響。"},{"en":"The global atmosphere means the whole layer of air surrounding the Earth.","zh":"「全球大氣」指包圍地球的整個空氣層。"},{"en":"Changes in the global atmosphere can influence wind, rain and temperature patterns.","zh":"全球大氣的變化可以影響風、雨和氣溫模式。"},{"en":"Pollution affects the global atmosphere when gases spread far beyond one country.","zh":"當氣體擴散到遠超一個國家的範圍，污染就會影響全球大氣。"},{"en":"Scientists study the global atmosphere to understand climate systems across the planet.","zh":"科學家研究全球大氣，以理解整個地球的氣候系統。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":1},{"front":"march to the beat of a different drummer","meaning":"按不同節奏運作","examples":[{"en":"The ocean and atmosphere sometimes seem to march to the beat of a different drummer.","zh":"海洋和大氣有時似乎按不同節奏運作。"},{"en":"To march to the beat of a different drummer means to behave differently from the usual pattern.","zh":"「march to the beat of a different drummer」意思是以不同於通常模式的方式運作或行動。"},{"en":"A creative student may march to the beat of a different drummer by solving problems in an unusual way.","zh":"有創意的學生可能會用不尋常的方法解難，按不同節奏行事。"},{"en":"A market can march to the beat of a different drummer when it rises while others fall.","zh":"當某個市場在其他市場下跌時上升，它就像是在按不同節奏運作。"},{"en":"Nature sometimes marches to the beat of a different drummer, so scientists must keep observing it.","zh":"自然有時會按不同節奏運作，所以科學家必須持續觀察。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":1},{"front":"disrupting the normal patterns of","meaning":"擾亂……的正常模式","examples":[{"en":"El Niño disrupts the normal patterns of many species.","zh":"厄爾尼諾現象擾亂許多物種的正常模式。"},{"en":"Disrupting the normal patterns of something means interrupting its usual order or routine.","zh":"「disrupting the normal patterns of」意思是打斷某事物通常的秩序或規律。"},{"en":"A sudden school closure can disrupt the normal patterns of students’ study and sleep.","zh":"學校突然停課，可能擾亂學生學習和睡眠的正常模式。"},{"en":"Heavy traffic disrupts the normal patterns of buses and delays passengers.","zh":"嚴重交通擠塞會擾亂巴士的正常模式，令乘客延誤。"},{"en":"Climate change may disrupt the normal patterns of animal migration and breeding.","zh":"氣候變化可能擾亂動物遷徙和繁殖的正常模式。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":1},{"front":"countless species of","meaning":"無數種……","examples":[{"en":"Climate rhythms affect countless species of plants and animals.","zh":"氣候節奏影響無數種植物和動物。"},{"en":"Countless species of something means so many kinds that they are difficult to count.","zh":"「countless species of」意思是種類多到難以計算。"},{"en":"Rainforests contain countless species of insects, birds and plants.","zh":"雨林包含無數種昆蟲、鳥類和植物。"},{"en":"Pollution can harm countless species of fish when chemicals enter rivers.","zh":"當化學物質流入河流，污染可能傷害無數種魚類。"},{"en":"Protecting wetlands helps countless species of wildlife survive.","zh":"保護濕地有助無數種野生動物生存。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":1},{"front":"hundreds of millions of","meaning":"數以億計的……","examples":[{"en":"Climate changes can affect hundreds of millions of human beings.","zh":"氣候變化可能影響數以億計的人類。"},{"en":"Hundreds of millions of people means several hundred million people, a very large number.","zh":"「hundreds of millions of people」指幾億人，是非常龐大的數字。"},{"en":"Hundreds of millions of people use public transport in large cities every year.","zh":"大城市每年有數以億計的人使用公共交通。"},{"en":"A major drought can affect hundreds of millions of people if food prices rise.","zh":"如果糧食價格上升，嚴重乾旱可能影響數以億計的人。"},{"en":"Online education can reach hundreds of millions of learners across different countries.","zh":"網上教育可以接觸不同國家數以億計的學習者。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":1},{"front":"anticipate","meaning":"預測；預料","examples":[{"en":"Scientists try to anticipate changes in seasonal patterns.","zh":"科學家試圖預測季節模式的變化。"},{"en":"To anticipate something means to expect it before it happens and prepare for it.","zh":"「anticipate」意思是在某事發生前預料它，並作準備。"},{"en":"A teacher may anticipate common mistakes before giving a grammar test.","zh":"老師可能在文法測驗前預料學生常犯的錯誤。"},{"en":"Shops hire extra staff when they anticipate more customers during holidays.","zh":"商店預料假期會有更多顧客時，會聘請額外員工。"},{"en":"Good planning helps families anticipate expenses before they become a problem.","zh":"良好規劃幫助家庭在開支成為問題前預先預料。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":2},{"front":"occasional lapses","meaning":"偶發失常","examples":[{"en":"Scientists try to anticipate occasional lapses in the march of the seasons.","zh":"科學家試圖預測季節推移中的偶發失常。"},{"en":"Occasional lapses are rare failures or breaks in a normal pattern.","zh":"「occasional lapses」指正常模式中少數、不常出現的失誤或中斷。"},{"en":"Even a careful driver may have occasional lapses in concentration on a long journey.","zh":"即使是小心的司機，在長途旅程中也可能偶爾注意力失常。"},{"en":"Occasional lapses in attendance can make it harder for students to follow a course.","zh":"出席方面的偶發缺席，可能令學生較難跟上課程。"},{"en":"Climate records help scientists notice occasional lapses in regular seasonal behaviour.","zh":"氣候記錄幫助科學家注意到規律季節行為中的偶發失常。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":2},{"front":"the march of the seasons","meaning":"季節推移","examples":[{"en":"El Niño can interrupt the normal march of the seasons.","zh":"厄爾尼諾現象可以打斷正常的季節推移。"},{"en":"The march of the seasons means the steady movement from one season to the next.","zh":"「the march of the seasons」指季節由一個走向下一個的穩定推移。"},{"en":"Gardeners follow the march of the seasons when choosing what to plant.","zh":"園丁在選擇種植什麼時，會跟隨季節推移。"},{"en":"If the march of the seasons becomes irregular, crops may flower too early.","zh":"如果季節推移變得不規律，農作物可能過早開花。"},{"en":"The march of the seasons usually brings predictable changes in weather, daylight and animal behaviour.","zh":"季節推移通常帶來天氣、日照和動物行為上的可預測變化。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":2},{"front":"plan accordingly","meaning":"相應地作出規劃","examples":[{"en":"Better climate prediction can help societies plan accordingly.","zh":"更好的氣候預測可以幫助社會相應地作出規劃。"},{"en":"To plan accordingly means to make plans that match the situation you expect.","zh":"「plan accordingly」意思是根據預期情況作出相應計劃。"},{"en":"If heavy rain is forecast, schools can plan accordingly and move activities indoors.","zh":"如果天氣預報有大雨，學校可以相應地作出規劃，把活動移到室內。"},{"en":"Families plan accordingly when they save money before a large expense.","zh":"家庭在大額開支前儲錢，就是相應地作出規劃。"},{"en":"Farmers need reliable weather information so they can plan accordingly before planting.","zh":"農民需要可靠的天氣資訊，才能在種植前相應地作出規劃。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":2},{"front":"seeking to understand","meaning":"正試圖了解","examples":[{"en":"Scientists are seeking to understand competing climate rhythms.","zh":"科學家正試圖了解相互競爭的氣候節奏。"},{"en":"Seeking to understand means trying carefully to learn why something happens.","zh":"「seeking to understand」意思是仔細嘗試了解某事為何發生。"},{"en":"Doctors are seeking to understand why some patients recover faster than others.","zh":"醫生正試圖了解為什麼有些病人康復得較快。"},{"en":"A good manager seeks to understand a problem before blaming the team.","zh":"好的經理會先試圖了解問題，而不是責怪團隊。"},{"en":"Students seeking to understand a topic ask questions instead of memorising blindly.","zh":"正試圖了解某個課題的學生會提問，而不是盲目背誦。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":2},{"front":"competing rhythms","meaning":"相互競爭的節奏","examples":[{"en":"Scientists study competing rhythms in the climate system.","zh":"科學家研究氣候系統中相互競爭的節奏。"},{"en":"Competing rhythms are different patterns that happen at the same time and may affect one another.","zh":"「competing rhythms」指同時存在、並可能互相影響的不同規律。"},{"en":"A student may struggle when school deadlines and family duties create competing rhythms.","zh":"當學校截止日期和家庭責任形成相互競爭的節奏時，學生可能會感到吃力。"},{"en":"In a city, traffic, work hours and public transport follow competing rhythms.","zh":"在城市中，交通、工作時間和公共交通都跟隨相互競爭的節奏。"},{"en":"Climate scientists study competing rhythms to see which pattern becomes stronger in a given year.","zh":"氣候科學家研究相互競爭的節奏，以了解某一年哪種模式變得更強。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":2},{"front":"the alternation between","meaning":"……之間的交替","examples":[{"en":"El Niño involves the alternation between normal and unusual climatic conditions.","zh":"厄爾尼諾現象涉及正常和異常氣候狀況之間的交替。"},{"en":"The alternation between two things means they take turns or change from one to the other.","zh":"「the alternation between」兩件事物，意思是它們輪流出現或由一方轉到另一方。"},{"en":"The alternation between study and rest helps students avoid exhaustion.","zh":"學習與休息之間的交替，幫助學生避免筋疲力盡。"},{"en":"The alternation between dry and wet seasons shapes farming schedules.","zh":"乾季和雨季之間的交替塑造農務時間表。"},{"en":"In some jobs, the alternation between busy weeks and quiet weeks affects workers’ routines.","zh":"在一些工作中，繁忙星期與清閒星期之間的交替會影響員工日常規律。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":2},{"front":"normal climate","meaning":"正常氣候","examples":[{"en":"El Niño differs from the normal climate of the Pacific region.","zh":"厄爾尼諾現象不同於太平洋地區的正常氣候。"},{"en":"Normal climate means the usual weather pattern of a place over a long period.","zh":"「正常氣候」指某地長期以來通常的天氣模式。"},{"en":"The normal climate of a desert is dry, with very little rainfall.","zh":"沙漠的正常氣候是乾燥、降雨很少。"},{"en":"If the normal climate changes, farmers may need new crops or watering methods.","zh":"如果正常氣候改變，農民可能需要新的農作物或灌溉方法。"},{"en":"Scientists compare unusual years with the normal climate to understand change.","zh":"科學家把異常年份與正常氣候比較，以理解變化。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":2},{"front":"recurrent set of climatic conditions","meaning":"反覆出現的一組氣候狀況","examples":[{"en":"El Niño is a recurrent set of climatic conditions.","zh":"厄爾尼諾現象是一組反覆出現的氣候狀況。"},{"en":"A recurrent set of climatic conditions is a group of weather and ocean patterns that happens again and again.","zh":"「a recurrent set of climatic conditions」指一組一再出現的天氣和海洋模式。"},{"en":"Seasonal monsoons are a recurrent set of climatic conditions in some regions.","zh":"在一些地區，季風是一組反覆出現的氣候狀況。"},{"en":"When a recurrent set of climatic conditions changes, communities may face repeated floods or droughts.","zh":"當一組反覆出現的氣候狀況改變，社區可能面對重複的洪水或乾旱。"},{"en":"Scientists study recurrent climatic conditions because repeated patterns can still vary in strength.","zh":"科學家研究反覆出現的氣候狀況，因為重複模式仍可能在強度上有所不同。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":2},{"front":"the Pacific region","meaning":"太平洋地區","examples":[{"en":"El Niño affects climatic conditions in the Pacific region.","zh":"厄爾尼諾現象影響太平洋地區的氣候狀況。"},{"en":"The Pacific region means the areas in and around the Pacific Ocean.","zh":"「太平洋地區」指太平洋及其周邊地區。"},{"en":"Many island communities in the Pacific region depend on fishing and coastal resources.","zh":"太平洋地區許多島嶼社區依賴漁業和沿岸資源。"},{"en":"A storm in the Pacific region can affect travel, shipping and local food supplies.","zh":"太平洋地區的風暴可能影響旅遊、航運和本地食物供應。"},{"en":"Climate changes in the Pacific region may influence weather far beyond the ocean itself.","zh":"太平洋地區的氣候變化，可能影響遠超海洋本身的天氣。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":2},{"front":"marine ecosystems","meaning":"海洋生態系統","examples":[{"en":"Seabirds are important components of marine ecosystems.","zh":"海鳥是海洋生態系統的重要組成部分。"},{"en":"Marine ecosystems are communities of sea life and the physical environment around them.","zh":"「海洋生態系統」是海洋生物及其周圍物理環境組成的群落。"},{"en":"Coral reefs, open oceans and coastal waters are different types of marine ecosystems.","zh":"珊瑚礁、開放海洋和沿岸水域都是不同類型的海洋生態系統。"},{"en":"Pollution can damage marine ecosystems by killing fish and reducing oxygen in the water.","zh":"污染可能透過殺死魚類和減少水中氧氣，破壞海洋生態系統。"},{"en":"Healthy marine ecosystems support food, jobs and wildlife.","zh":"健康的海洋生態系統支撐食物、工作和野生動物。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":2},{"front":"prominent and highly visible components","meaning":"突出且容易看見的組成部分","examples":[{"en":"Seabirds are prominent and highly visible components of marine ecosystems.","zh":"海鳥是海洋生態系統中突出且容易看見的組成部分。"},{"en":"Prominent and highly visible components are important parts that can be easily noticed.","zh":"「prominent and highly visible components」指重要而且容易被注意到的部分。"},{"en":"Buses are prominent and highly visible components of a city’s transport system.","zh":"巴士是城市交通系統中突出且容易看見的組成部分。"},{"en":"If coral disappears, one prominent and highly visible component of a reef ecosystem is lost.","zh":"如果珊瑚消失，珊瑚礁生態系統就失去一個突出且容易看見的組成部分。"},{"en":"Teachers are prominent and highly visible components of school life because students meet them every day.","zh":"老師是學校生活中突出且容易看見的組成部分，因為學生每天都會見到他們。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":3},{"front":"affected by global climate change","meaning":"受全球氣候變化影響","examples":[{"en":"Seabirds will be affected by global climate change.","zh":"海鳥將會受全球氣候變化影響。"},{"en":"If something is affected by global climate change, its conditions, behaviour or survival are influenced by worldwide climate shifts.","zh":"如果某事物受全球氣候變化影響，意思是它的環境、行為或生存受到全球氣候轉變影響。"},{"en":"Farmers are affected by global climate change when rainfall becomes less reliable.","zh":"當降雨變得較不可靠，農民就會受全球氣候變化影響。"},{"en":"Coastal towns may be affected by global climate change through rising sea levels.","zh":"沿岸城鎮可能因海平面上升而受全球氣候變化影響。"},{"en":"Animals are affected by global climate change when food appears earlier or later than usual.","zh":"當食物比平時更早或更遲出現，動物就會受全球氣候變化影響。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":3},{"front":"global climate change","meaning":"全球氣候變化","examples":[{"en":"Global climate change can alter prey availability for seabirds.","zh":"全球氣候變化可以改變海鳥的獵物供應量。"},{"en":"Global climate change means long-term changes in temperature, rainfall, storms and sea levels across the Earth.","zh":"「全球氣候變化」指地球各地氣溫、降雨、風暴和海平面的長期變化。"},{"en":"Global climate change can make heatwaves more frequent in some regions.","zh":"全球氣候變化可能令某些地區更頻繁出現熱浪。"},{"en":"Global climate change may reduce crop yields if droughts become stronger.","zh":"如果乾旱變得更嚴重，全球氣候變化可能降低農作物產量。"},{"en":"Understanding global climate change helps governments prepare for future risks.","zh":"理解全球氣候變化能幫助政府為未來風險作準備。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":3},{"front":"Bering Sea region","meaning":"白令海地區","examples":[{"en":"The Bering Sea region is particularly important to seabirds.","zh":"白令海地區對海鳥尤其重要。"},{"en":"The Bering Sea region is the northern sea area between Alaska and Russia.","zh":"「白令海地區」是阿拉斯加與俄羅斯之間的北方海域。"},{"en":"Many seabirds feed, breed or migrate through the Bering Sea region.","zh":"許多海鳥在白令海地區覓食、繁殖或遷徙。"},{"en":"Changes in sea ice in the Bering Sea region can affect fish and seabird populations.","zh":"白令海地區海冰的變化，可能影響魚類和海鳥種群。"},{"en":"Scientists study the Bering Sea region because it is rich in marine wildlife.","zh":"科學家研究白令海地區，因為該地擁有豐富的海洋野生動物。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":3},{"front":"particularly important to","meaning":"對……尤其重要","examples":[{"en":"The Bering Sea region is particularly important to seabirds.","zh":"白令海地區對海鳥尤其重要。"},{"en":"If something is particularly important to someone or something, it matters more than usual.","zh":"如果某事物對某人或某物尤其重要，意思是它比一般情況更重要。"},{"en":"Sleep is particularly important to students before an examination.","zh":"睡眠對考試前的學生尤其重要。"},{"en":"Clean water is particularly important to hospitals because patients need safe care.","zh":"清潔食水對醫院尤其重要，因為病人需要安全照護。"},{"en":"Sea ice is particularly important to animals that depend on cold-water habitats.","zh":"海冰對依賴寒冷水域棲息地的動物尤其重要。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":3},{"front":"larger and more diverse than","meaning":"比……更大且更多樣化","examples":[{"en":"Seabird populations there are larger and more diverse than in similar regions.","zh":"那裡的海鳥種群比類似地區更大且更多樣化。"},{"en":"Larger and more diverse than means greater in number and containing more types.","zh":"「larger and more diverse than」意思是數量更大，而且種類更多。"},{"en":"A city library may be larger and more diverse than a small school library.","zh":"城市圖書館可能比小型學校圖書館更大且更多樣化。"},{"en":"A rainforest is usually larger and more diverse than a city park in terms of wildlife.","zh":"就野生動物而言，雨林通常比城市公園更大且更多樣化。"},{"en":"A class becomes larger and more diverse than before when students from many backgrounds join it.","zh":"當來自許多背景的學生加入，班級會比以前更大且更多樣化。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":3},{"front":"breeding in","meaning":"在……繁殖","examples":[{"en":"Many seabirds breeding in the continental United States are found in Alaska.","zh":"許多在美國本土繁殖的海鳥都見於阿拉斯加。"},{"en":"Breeding in a place means producing young there.","zh":"「breeding in」某地，意思是在那裡繁殖後代。"},{"en":"Birds breeding in wetlands need safe nests and enough food.","zh":"在濕地繁殖的鳥類需要安全的巢和足夠食物。"},{"en":"If animals stop breeding in an area, the local population may fall.","zh":"如果動物停止在某地繁殖，本地種群可能下降。"},{"en":"Scientists record which species are breeding in a region to measure its ecological health.","zh":"科學家記錄哪些物種在某地繁殖，以衡量該地的生態健康。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":3},{"front":"continental United States","meaning":"美國本土","examples":[{"en":"Many seabirds breeding in the continental United States are found in the Bering Sea region.","zh":"許多在美國本土繁殖的海鳥都見於白令海地區。"},{"en":"The continental United States means the main connected land area of the United States, excluding places such as Alaska and Hawaii.","zh":"「美國本土」指美國主要相連的陸地部分，不包括阿拉斯加和夏威夷等地。"},{"en":"Flights from Hawaii to the continental United States cross a large part of the Pacific Ocean.","zh":"從夏威夷飛往美國本土的航班會橫越太平洋大片海域。"},{"en":"Weather in Alaska can be very different from weather in the continental United States.","zh":"阿拉斯加的天氣可能與美國本土非常不同。"},{"en":"Some species are common in the continental United States but rare in remote islands.","zh":"有些物種在美國本土常見，但在偏遠島嶼罕見。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":3},{"front":"so named because","meaning":"之所以如此命名是因為","examples":[{"en":"Seabirds are so named because they spend most of their lives at sea.","zh":"海鳥之所以如此命名，是因為牠們一生大部分時間都在海上度過。"},{"en":"So named because means given this name for a particular reason.","zh":"「so named because」意思是因某個特定原因而被如此命名。"},{"en":"The red fox is so named because its fur is often reddish.","zh":"赤狐之所以如此命名，是因為牠的毛色通常偏紅。"},{"en":"A reading room may be so named because people go there mainly to read quietly.","zh":"閱覽室之所以如此命名，是因為人們主要到那裡安靜閱讀。"},{"en":"Some towns are so named because of a river, mountain or historical person nearby.","zh":"有些城鎮之所以如此命名，是因為附近有河流、山脈或歷史人物。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":3},{"front":"at least 80% of","meaning":"至少百分之八十的……","examples":[{"en":"Seabirds spend at least 80% of their lives at sea.","zh":"海鳥一生至少百分之八十的時間在海上度過。"},{"en":"At least 80% of something means no less than eighty percent of it.","zh":"「at least 80% of」某物，意思是不少於百分之八十。"},{"en":"At least 80% of the class passed the test, so most students did well.","zh":"至少百分之八十的班上學生通過測驗，所以大多數學生表現良好。"},{"en":"A phone battery should be charged to at least 80% before a long trip.","zh":"長途旅程前，手機電量應至少充至百分之八十。"},{"en":"If at least 80% of homes recycle waste, the community can greatly reduce rubbish.","zh":"如果至少百分之八十的家庭回收廢物，社區可以大幅減少垃圾。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":3},{"front":"dependent upon","meaning":"依賴……","examples":[{"en":"Seabirds are dependent upon marine resources for food.","zh":"海鳥依賴海洋資源作為食物。"},{"en":"Dependent upon something means needing it in order to live, work or succeed.","zh":"「dependent upon」某事物，意思是需要它才能生活、工作或成功。"},{"en":"Young children are dependent upon adults for food, safety and guidance.","zh":"年幼兒童依賴成年人提供食物、安全和指導。"},{"en":"A business may be dependent upon one supplier, which becomes risky if deliveries stop.","zh":"企業可能依賴單一供應商；如果送貨停止，這就會變得有風險。"},{"en":"Farmers are dependent upon rainfall when they do not have irrigation systems.","zh":"沒有灌溉系統時，農民依賴降雨。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":3},{"front":"marine resources","meaning":"海洋資源","examples":[{"en":"Seabirds depend on marine resources for food.","zh":"海鳥依賴海洋資源作為食物。"},{"en":"Marine resources are useful things from the sea, such as fish, shellfish, seaweed and ocean energy.","zh":"「海洋資源」是來自海洋的有用事物，例如魚類、貝類、海藻和海洋能源。"},{"en":"Coastal villages often depend on marine resources for jobs and food.","zh":"沿岸村莊常依賴海洋資源獲得工作和食物。"},{"en":"Overfishing can reduce marine resources and harm local communities.","zh":"過度捕魚可能減少海洋資源，並傷害本地社區。"},{"en":"Protecting marine resources helps both wildlife and people who live near the sea.","zh":"保護海洋資源能幫助野生動物，也幫助住在海邊的人。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":4},{"front":"prey availability","meaning":"獵物供應量","examples":[{"en":"Prey availability changes in response to climate-driven factors.","zh":"獵物供應量會因應由氣候驅動的因素而改變。"},{"en":"Prey availability means how much food is available for predators to catch and eat.","zh":"「prey availability」指捕食者可以捕捉和食用的食物有多少。"},{"en":"If fish move deeper into the sea, prey availability for seabirds may fall.","zh":"如果魚類移到更深的海域，海鳥的獵物供應量可能下降。"},{"en":"Low prey availability can cause chicks to grow slowly because parents bring back less food.","zh":"獵物供應量低可能令雛鳥成長緩慢，因為親鳥帶回較少食物。"},{"en":"Scientists monitor prey availability to understand whether animals have enough to eat.","zh":"科學家監測獵物供應量，以了解動物是否有足夠食物。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":4},{"front":"in response to","meaning":"回應；因應","examples":[{"en":"Prey availability changes in response to sea temperature.","zh":"獵物供應量會因應海水溫度而改變。"},{"en":"In response to something means as a reaction to it.","zh":"「in response to」某事，意思是作為對它的反應。"},{"en":"Schools may close early in response to a severe storm warning.","zh":"學校可能因應嚴重風暴警告而提早放學。"},{"en":"Prices can rise in response to higher demand.","zh":"價格可能因應需求上升而上升。"},{"en":"Animals may move to cooler areas in response to warmer weather.","zh":"動物可能因應較溫暖的天氣而移到較涼爽的地區。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":4},{"front":"climatically driven factors","meaning":"由氣候驅動的因素","examples":[{"en":"Surface sea temperature is one of the climatically driven factors affecting prey.","zh":"海面溫度是影響獵物的其中一個由氣候驅動的因素。"},{"en":"Climatically driven factors are causes or conditions shaped by climate.","zh":"「climatically driven factors」指由氣候塑造的原因或條件。"},{"en":"Rainfall, temperature and sea ice are climatically driven factors that affect farming and wildlife.","zh":"降雨、氣溫和海冰都是由氣候驅動的因素，會影響農業和野生動物。"},{"en":"Climatically driven factors can change food supplies when weather patterns shift.","zh":"當天氣模式轉變，由氣候驅動的因素可能改變食物供應。"},{"en":"Scientists separate climatically driven factors from human causes when studying environmental change.","zh":"科學家研究環境變化時，會把由氣候驅動的因素與人為原因分開。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":4},{"front":"surface sea temperature","meaning":"海面溫度","examples":[{"en":"Surface sea temperature can affect the food available to seabirds.","zh":"海面溫度可以影響海鳥可獲得的食物。"},{"en":"Surface sea temperature means the temperature of the top layer of seawater.","zh":"「海面溫度」指海水最上層的溫度。"},{"en":"Scientists measure surface sea temperature to detect warming in the ocean.","zh":"科學家測量海面溫度，以偵測海洋變暖。"},{"en":"If surface sea temperature rises, some fish may move to cooler waters.","zh":"如果海面溫度上升，一些魚類可能移到較冷的水域。"},{"en":"Changes in surface sea temperature can affect storms, plankton and marine food chains.","zh":"海面溫度的變化可以影響風暴、浮游生物和海洋食物鏈。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":4},{"front":"extent of sea ice","meaning":"海冰範圍","examples":[{"en":"The extent of sea ice can affect seabird populations.","zh":"海冰範圍可以影響海鳥種群。"},{"en":"The extent of sea ice means how much of the sea is covered by ice.","zh":"「extent of sea ice」指海洋有多少範圍被冰覆蓋。"},{"en":"Satellites help scientists measure the extent of sea ice each year.","zh":"衛星幫助科學家每年測量海冰範圍。"},{"en":"If the extent of sea ice shrinks, animals that hunt or rest on ice may suffer.","zh":"如果海冰範圍縮小，依靠冰面覓食或休息的動物可能受苦。"},{"en":"The extent of sea ice can influence ocean temperature and food supplies.","zh":"海冰範圍可以影響海洋溫度和食物供應。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":4},{"front":"seabird populations","meaning":"海鳥種群","examples":[{"en":"Seabird populations will be affected by changes in food supply.","zh":"海鳥種群將會受食物供應變化影響。"},{"en":"Seabird populations are groups of seabirds living in a particular area or belonging to a particular species.","zh":"「海鳥種群」指生活在特定地區或屬於特定物種的海鳥群體。"},{"en":"Seabird populations may fall if adult birds cannot find enough fish for their chicks.","zh":"如果成年鳥找不到足夠魚類餵養雛鳥，海鳥種群可能下降。"},{"en":"Scientists count seabird populations to see whether marine ecosystems are healthy.","zh":"科學家計算海鳥種群，以了解海洋生態系統是否健康。"},{"en":"Protecting nesting sites can help seabird populations recover.","zh":"保護築巢地可以幫助海鳥種群恢復。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":4},{"front":"valued as indicators of","meaning":"被視為……的指標","examples":[{"en":"Seabirds are valued as indicators of healthy marine ecosystems.","zh":"海鳥被視為健康海洋生態系統的指標。"},{"en":"If something is valued as an indicator of a condition, people use it as a sign of that condition.","zh":"如果某事物被視為某狀況的指標，意思是人們用它作為該狀況的跡象。"},{"en":"Clean rivers are valued as indicators of good environmental management.","zh":"清潔河流被視為良好環境管理的指標。"},{"en":"Student questions can be valued as indicators of real understanding.","zh":"學生提出的問題可以被視為真正理解的指標。"},{"en":"Falling bird numbers may be valued as indicators of problems in the food chain.","zh":"鳥類數量下降可能被視為食物鏈出問題的指標。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":4},{"front":"healthy marine ecosystems","meaning":"健康的海洋生態系統","examples":[{"en":"Seabirds can indicate healthy marine ecosystems.","zh":"海鳥可以顯示健康的海洋生態系統。"},{"en":"Healthy marine ecosystems have enough food, clean water and balanced relationships among sea organisms.","zh":"健康的海洋生態系統有足夠食物、清潔水質，以及海洋生物之間平衡的關係。"},{"en":"Coral reefs with many fish are often signs of healthy marine ecosystems.","zh":"有許多魚類的珊瑚礁通常是健康海洋生態系統的跡象。"},{"en":"Pollution makes it harder for healthy marine ecosystems to survive.","zh":"污染令健康的海洋生態系統更難生存。"},{"en":"Healthy marine ecosystems support fisheries, tourism and biodiversity.","zh":"健康的海洋生態系統支撐漁業、旅遊和生物多樣性。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":4},{"front":"vicarious use value","meaning":"代用價值；間接使用價值","examples":[{"en":"Seabirds provide a vicarious use value for people who never see them directly.","zh":"海鳥為從未直接看見牠們的人提供代用價值。"},{"en":"Vicarious use value means people value something by enjoying it indirectly through books, pictures or programmes.","zh":"「vicarious use value」指人們透過書籍、圖片或節目間接欣賞某事物而感到它有價值。"},{"en":"A child may gain vicarious use value from rainforest documentaries without visiting a rainforest.","zh":"孩子即使沒有到過雨林，也可能從雨林紀錄片中獲得代用價值。"},{"en":"Wildlife photos create vicarious use value because people can appreciate animals from far away.","zh":"野生動物照片創造代用價值，因為人們可以從遠處欣賞動物。"},{"en":"Museums and nature films help people gain vicarious use value from places they may never visit.","zh":"博物館和自然影片幫助人們從可能永遠不會親身到訪的地方獲得代用價值。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":4},{"front":"existence value","meaning":"存在價值","examples":[{"en":"Some people value seabirds simply because they exist.","zh":"有些人重視海鳥，只是因為牠們存在。"},{"en":"Existence value means people believe something is valuable even if they never use or see it.","zh":"「existence value」意思是人們認為某事物有價值，即使他們從不使用或看見它。"},{"en":"Many people feel whales have existence value, even if they never go whale-watching.","zh":"許多人覺得鯨魚有存在價值，即使他們從不去觀鯨。"},{"en":"A forest may have existence value because people want it to survive for future generations.","zh":"森林可能有存在價值，因為人們希望它為未來世代而存活。"},{"en":"Existence value reminds us that nature can matter beyond money or direct use.","zh":"存在價值提醒我們，自然的重要性可以超越金錢或直接使用。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":4},{"front":"appreciate and value","meaning":"欣賞並重視","examples":[{"en":"People appreciate and value seabirds simply because they are there.","zh":"人們欣賞並重視海鳥，只是因為牠們存在。"},{"en":"To appreciate and value something means to understand its importance and feel it is worth protecting.","zh":"「appreciate and value」某事物，意思是理解它的重要性並覺得它值得保護。"},{"en":"Students may appreciate and value clean classrooms when they help keep them tidy.","zh":"學生在幫忙保持課室整潔時，可能更欣賞並重視乾淨的課室。"},{"en":"Communities appreciate and value old buildings because they carry local memory.","zh":"社區欣賞並重視舊建築，因為它們承載本地記憶。"},{"en":"People often appreciate and value nature more after learning how easily it can be damaged.","zh":"人們學到自然多容易受破壞後，常會更欣賞並重視自然。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":5},{"front":"simply because","meaning":"只是因為","examples":[{"en":"Some people value seabirds simply because they exist.","zh":"有些人重視海鳥，只是因為牠們存在。"},{"en":"Simply because means for this one clear reason, without needing another explanation.","zh":"「simply because」意思是只因這一個清楚原因，不需要其他解釋。"},{"en":"A person may keep an old photo simply because it reminds them of home.","zh":"一個人可能保留舊照片，只是因為它令他想起家。"},{"en":"Students should not copy an answer simply because it looks long.","zh":"學生不應只是因為答案看起來很長就抄下來。"},{"en":"People may protect a small park simply because it gives children a safe place to play.","zh":"人們可能保護一個小公園，只是因為它給孩子安全玩耍的地方。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":5},{"front":"venues such as","meaning":"例如……的途徑","examples":[{"en":"People enjoy seabirds through venues such as pictures and nature programmes.","zh":"人們透過圖片和自然節目等途徑欣賞海鳥。"},{"en":"Venues such as means places, forms or channels like the examples that follow.","zh":"「venues such as」意思是像後面例子那樣的地方、形式或渠道。"},{"en":"Students learn outside class through venues such as museums, libraries and online courses.","zh":"學生透過博物館、圖書館和網上課程等途徑在課堂外學習。"},{"en":"Artists share their work through venues such as galleries, festivals and social media.","zh":"藝術家透過畫廊、節日和社交媒體等途徑分享作品。"},{"en":"Nature education can happen through venues such as documentaries, books and school trips.","zh":"自然教育可以透過紀錄片、書籍和學校旅行等途徑進行。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":5},{"front":"nature programs","meaning":"自然節目","examples":[{"en":"Nature programs allow people to learn about seabirds.","zh":"自然節目讓人們認識海鳥。"},{"en":"Nature programs are television, radio or online shows about animals, plants and the natural world.","zh":"「自然節目」是關於動物、植物和自然世界的電視、電台或網上節目。"},{"en":"Children may learn the names of animals by watching nature programs at home.","zh":"孩子在家觀看自然節目，可能學會動物的名稱。"},{"en":"Nature programs can make environmental problems easier to understand by showing real places.","zh":"自然節目透過展示真實地方，可以令環境問題更容易理解。"},{"en":"A good nature program teaches facts without making the topic too difficult.","zh":"好的自然節目會教授事實，而不會令主題過於困難。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":5},{"front":"written accounts","meaning":"書面記述","examples":[{"en":"Written accounts can help people appreciate seabirds.","zh":"書面記述可以幫助人們欣賞海鳥。"},{"en":"Written accounts are descriptions or reports recorded in words.","zh":"「written accounts」是用文字記錄的描述或報告。"},{"en":"A traveller’s written account can show what life was like in another country.","zh":"旅客的書面記述可以展示另一個國家的生活是怎樣的。"},{"en":"Written accounts from local people help historians understand past events.","zh":"本地人的書面記述幫助歷史學家理解過去事件。"},{"en":"Scientists use written accounts when photographs or videos are not available.","zh":"當沒有照片或影片時，科學家會使用書面記述。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":5},{"front":"directly observing","meaning":"直接觀察","examples":[{"en":"Many people value seabirds without directly observing them.","zh":"許多人即使沒有直接觀察海鳥，也重視牠們。"},{"en":"Directly observing something means seeing or watching it yourself, not through someone else’s report.","zh":"「directly observing」某事物，意思是親自看見或觀察它，而不是透過別人的報告。"},{"en":"Students learn more about plants by directly observing how they grow.","zh":"學生透過直接觀察植物如何生長，可以學到更多。"},{"en":"A doctor may need to directly observe a patient’s symptoms before deciding on treatment.","zh":"醫生在決定治療前，可能需要直接觀察病人的症狀。"},{"en":"People can care about wildlife even without directly observing it in nature.","zh":"人們即使沒有在自然中直接觀察野生動物，也可以關心它們。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":5},{"front":"native environment","meaning":"原生環境","examples":[{"en":"Seabirds are often appreciated without being seen in their native environment.","zh":"人們常在沒有於原生環境看見海鳥的情況下欣賞牠們。"},{"en":"A native environment is the natural place where a plant or animal normally lives.","zh":"「native environment」指植物或動物通常生活的自然地方。"},{"en":"Pandas behave differently in their native environment than in a zoo.","zh":"熊貓在原生環境中的行為與在動物園中不同。"},{"en":"Protecting a species means protecting its native environment, not only the animal itself.","zh":"保護一個物種，意思是不只保護動物本身，也要保護其原生環境。"},{"en":"Students understand animals better when they learn about their native environment.","zh":"學生了解動物的原生環境時，會更好理解牠們。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":5},{"front":"a direct measure of","meaning":"……的直接衡量","examples":[{"en":"Federal legislation provides a direct measure of seabirds’ value.","zh":"聯邦法例提供了海鳥價值的直接衡量。"},{"en":"A direct measure of something is a clear way to show or calculate its importance, size or effect.","zh":"「a direct measure of」某事物，是清楚顯示或計算其重要性、大小或影響的方法。"},{"en":"Exam scores are one direct measure of academic performance, but not the only one.","zh":"考試分數是學業表現的一種直接衡量，但不是唯一一種。"},{"en":"Hospital waiting time can be a direct measure of pressure on the healthcare system.","zh":"醫院輪候時間可以是醫療系統壓力的直接衡量。"},{"en":"The number of protected areas is a direct measure of how seriously a government treats conservation.","zh":"保護區數量是政府多重視保育的一種直接衡量。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":5},{"front":"demonstrated by","meaning":"由……顯示","examples":[{"en":"Their value is demonstrated by protective legislation.","zh":"牠們的價值由保護性法例顯示。"},{"en":"Demonstrated by means shown clearly through evidence, action or example.","zh":"「demonstrated by」意思是由證據、行動或例子清楚顯示。"},{"en":"A student’s progress is demonstrated by better writing and fewer mistakes.","zh":"學生的進步由更好的寫作和較少錯誤顯示。"},{"en":"Public concern is demonstrated by the number of people who join the meeting.","zh":"公眾關注由參加會議的人數顯示。"},{"en":"The danger of pollution is demonstrated by dead fish in the river.","zh":"污染的危險由河中的死魚顯示。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":5},{"front":"federal legislation","meaning":"聯邦法例","examples":[{"en":"Federal legislation established wildlife refuges to protect seabirds.","zh":"聯邦法例設立野生動物保護區來保護海鳥。"},{"en":"Federal legislation means laws made by a national government.","zh":"「federal legislation」指由國家層面的政府制定的法律。"},{"en":"Federal legislation can set safety standards that every state or region must follow.","zh":"聯邦法例可以訂立每個州或地區都必須遵守的安全標準。"},{"en":"Environmental groups may support federal legislation that protects endangered species.","zh":"環保團體可能支持保護瀕危物種的聯邦法例。"},{"en":"When local rules are not enough, federal legislation may provide wider protection.","zh":"當地方規則不足夠時，聯邦法例可以提供更廣泛的保護。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":5},{"front":"established specific national wildlife refuges","meaning":"設立特定國家野生動物保護區","examples":[{"en":"Federal legislation established specific national wildlife refuges for seabirds.","zh":"聯邦法例為海鳥設立特定國家野生動物保護區。"},{"en":"To establish specific national wildlife refuges means to officially create protected areas for certain wildlife.","zh":"「establish specific national wildlife refuges」意思是正式設立保護特定野生動物的區域。"},{"en":"A government may establish specific national wildlife refuges to protect rare birds and their nesting sites.","zh":"政府可能設立特定國家野生動物保護區，以保護稀有鳥類及其築巢地。"},{"en":"Establishing specific wildlife refuges can reduce hunting, building and disturbance in sensitive areas.","zh":"設立特定野生動物保護區，可以減少敏感地區的狩獵、建築和干擾。"},{"en":"National wildlife refuges work best when laws, funding and local support are all in place.","zh":"國家野生動物保護區在法律、資金和本地支持都到位時，最能發揮作用。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":5},{"front":"protect seabirds","meaning":"保護海鳥","examples":[{"en":"Wildlife refuges were established to protect seabirds.","zh":"野生動物保護區被設立來保護海鳥。"},{"en":"To protect seabirds means to keep seabirds safe from harm, habitat loss or human disturbance.","zh":"「protect seabirds」意思是保護海鳥免受傷害、棲息地喪失或人類干擾。"},{"en":"Keeping people away from nesting cliffs can protect seabirds during breeding season.","zh":"在繁殖季節讓人們遠離築巢懸崖，可以保護海鳥。"},{"en":"Reducing plastic waste helps protect seabirds from eating dangerous rubbish.","zh":"減少塑膠垃圾有助保護海鳥，避免牠們吃下危險垃圾。"},{"en":"Laws protect seabirds best when they also protect the fish and habitats they depend on.","zh":"法律在同時保護海鳥依賴的魚類和棲息地時，最能保護海鳥。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":6},{"front":"international treaty obligations","meaning":"國際條約義務","examples":[{"en":"International treaty obligations provide additional protection for seabirds.","zh":"國際條約義務為海鳥提供額外保護。"},{"en":"International treaty obligations are duties that countries agree to follow under international agreements.","zh":"「international treaty obligations」是各國根據國際協議同意遵守的責任。"},{"en":"Countries may have international treaty obligations to protect migratory birds.","zh":"各國可能有保護候鳥的國際條約義務。"},{"en":"International treaty obligations can force governments to cooperate across borders.","zh":"國際條約義務可以迫使政府跨境合作。"},{"en":"Wildlife protection is stronger when national laws match international treaty obligations.","zh":"當國內法律與國際條約義務一致時，野生動物保護會更強。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":6},{"front":"provide additional protection","meaning":"提供額外保護","examples":[{"en":"Treaty obligations provide additional protection for seabirds.","zh":"條約義務為海鳥提供額外保護。"},{"en":"To provide additional protection means to give extra safety beyond what already exists.","zh":"「provide additional protection」意思是在已有保護之外提供額外安全保障。"},{"en":"Wearing a helmet provides additional protection when cycling on busy roads.","zh":"在繁忙道路上踏單車時，戴頭盔提供額外保護。"},{"en":"Extra passwords provide additional protection for online bank accounts.","zh":"額外密碼為網上銀行帳戶提供額外保護。"},{"en":"Marine reserves provide additional protection for fish during breeding seasons.","zh":"海洋保護區在魚類繁殖季節提供額外保護。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":6},{"front":"subsistence resource","meaning":"維持生計的資源","examples":[{"en":"Seabirds are an important subsistence resource for many local people.","zh":"海鳥是許多本地人重要的維持生計資源。"},{"en":"A subsistence resource is something people use directly to meet basic needs such as food or survival.","zh":"「subsistence resource」指人們直接用來滿足食物或生存等基本需要的資源。"},{"en":"Fish can be a subsistence resource for families who catch them for daily meals.","zh":"對捕魚作日常食物的家庭來說，魚可以是維持生計的資源。"},{"en":"If a subsistence resource disappears, local people may lose an important food source.","zh":"如果維持生計的資源消失，本地人可能失去重要食物來源。"},{"en":"Protecting subsistence resources helps communities maintain traditional ways of life.","zh":"保護維持生計的資源有助社區維持傳統生活方式。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":6},{"front":"live within","meaning":"居住在……之內","examples":[{"en":"Many people live within the Bering Sea region.","zh":"許多人居住在白令海地區之內。"},{"en":"To live within an area means to live inside its boundaries or limits.","zh":"「live within」某個地區，意思是居住在其邊界或範圍之內。"},{"en":"Families who live within walking distance of school may not need a bus.","zh":"居住在學校步行距離之內的家庭，可能不需要巴士。"},{"en":"People who live within a national park must follow special conservation rules.","zh":"居住在國家公園範圍之內的人，必須遵守特別保育規則。"},{"en":"Communities that live within coastal areas often depend on the sea for work and food.","zh":"居住在沿岸地區之內的社區，常依賴海洋獲得工作和食物。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":6},{"front":"rich knowledge base","meaning":"豐富知識基礎","examples":[{"en":"A rich knowledge base makes seabirds useful as indicator species.","zh":"豐富知識基礎使海鳥成為有用的指標物種。"},{"en":"A rich knowledge base is a large amount of useful information built up over time.","zh":"「rich knowledge base」指長時間累積的大量有用資訊。"},{"en":"Doctors rely on a rich knowledge base when diagnosing difficult illnesses.","zh":"醫生診斷疑難疾病時，依靠豐富知識基礎。"},{"en":"A school creates a rich knowledge base when teachers record successful lesson methods.","zh":"當老師記錄成功的教學方法時，學校便建立豐富知識基礎。"},{"en":"Long-term research gives scientists a rich knowledge base for understanding environmental change.","zh":"長期研究為科學家提供豐富知識基礎，以理解環境變化。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":6},{"front":"valuable resource","meaning":"有價值的資源","examples":[{"en":"Seabirds are a valuable resource for measuring environmental change.","zh":"海鳥是測量環境變化的有價值資源。"},{"en":"A valuable resource is something useful, important and worth protecting or using carefully.","zh":"「valuable resource」指有用、重要，且值得保護或小心使用的事物。"},{"en":"Clean water is a valuable resource because people need it every day.","zh":"清潔食水是有價值的資源，因為人們每天都需要它。"},{"en":"Experienced workers are a valuable resource for training new staff.","zh":"有經驗的員工是培訓新人的有價值資源。"},{"en":"Data becomes a valuable resource when it helps people make better decisions.","zh":"當數據幫助人們作出更好決定，它就成為有價值的資源。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":6},{"front":"indicator species","meaning":"指標物種","examples":[{"en":"Seabirds are useful indicator species for marine change.","zh":"海鳥是研究海洋變化的有用指標物種。"},{"en":"Indicator species are organisms that show whether an environment is healthy or changing.","zh":"「indicator species」是能顯示環境是否健康或正在改變的生物。"},{"en":"Frogs can be indicator species because they are sensitive to water pollution.","zh":"青蛙可以是指標物種，因為牠們對水污染敏感。"},{"en":"If an indicator species declines, scientists may look for hidden environmental problems.","zh":"如果指標物種下降，科學家可能會尋找隱藏的環境問題。"},{"en":"Seabirds can act as indicator species because their food supply depends on ocean conditions.","zh":"海鳥可以作為指標物種，因為牠們的食物供應依賴海洋狀況。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":6},{"front":"measurement of change","meaning":"變化測量","examples":[{"en":"Seabirds help with the measurement of change in the marine environment.","zh":"海鳥有助測量海洋環境中的變化。"},{"en":"Measurement of change means collecting information to see how much something has altered.","zh":"「measurement of change」意思是收集資料，以了解某事物改變了多少。"},{"en":"Regular tests allow measurement of change in a student’s reading ability.","zh":"定期測驗可以測量學生閱讀能力的變化。"},{"en":"Temperature records help the measurement of change in climate over many years.","zh":"溫度記錄有助測量多年來氣候的變化。"},{"en":"Without measurement of change, people may not notice a problem until it becomes serious.","zh":"沒有變化測量，人們可能直到問題變嚴重才注意到它。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":6},{"front":"marine environment","meaning":"海洋環境","examples":[{"en":"Scientists use seabirds to study changes in the marine environment.","zh":"科學家利用海鳥研究海洋環境的變化。"},{"en":"The marine environment means the sea and all the living and non-living things in it.","zh":"「海洋環境」指海洋以及其中所有生物和非生物事物。"},{"en":"Plastic waste can remain in the marine environment for a long time.","zh":"塑膠垃圾可以長時間留在海洋環境中。"},{"en":"The marine environment provides food and shelter for fish, birds and mammals.","zh":"海洋環境為魚類、鳥類和哺乳動物提供食物和棲身之所。"},{"en":"Protecting the marine environment means reducing pollution and preserving habitats.","zh":"保護海洋環境，意思是減少污染並保存棲息地。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":6},{"front":"most abundant breeding species","meaning":"數量最多的繁殖物種","examples":[{"en":"The most abundant breeding species in Alaska include fulmars and puffins.","zh":"阿拉斯加數量最多的繁殖物種包括管鼻鸌和海鸚。"},{"en":"The most abundant breeding species are the species that reproduce there in the greatest numbers.","zh":"「most abundant breeding species」指在某地繁殖數量最多的物種。"},{"en":"In a pond, frogs may be the most abundant breeding species during spring.","zh":"在池塘中，青蛙可能是春季數量最多的繁殖物種。"},{"en":"Knowing the most abundant breeding species helps scientists decide which animals shape an ecosystem most.","zh":"了解數量最多的繁殖物種，有助科學家判斷哪些動物最能塑造生態系統。"},{"en":"If the most abundant breeding species decline, the whole food web may be affected.","zh":"如果數量最多的繁殖物種下降，整個食物網可能受影響。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":6},{"front":"northern fulmars","meaning":"北方管鼻鸌","examples":[{"en":"Northern fulmars are among the most abundant breeding seabirds in Alaska.","zh":"北方管鼻鸌是阿拉斯加數量最多的繁殖海鳥之一。"},{"en":"Northern fulmars are seabirds that live in northern oceans and often glide over the sea.","zh":"北方管鼻鸌是生活在北方海洋、常在海面上滑翔的海鳥。"},{"en":"Northern fulmars feed on fish, squid and other small marine animals.","zh":"北方管鼻鸌以魚、魷魚和其他小型海洋動物為食。"},{"en":"Scientists may count northern fulmars to monitor changes in northern marine ecosystems.","zh":"科學家可能計算北方管鼻鸌的數量，以監測北方海洋生態系統的變化。"},{"en":"Like many seabirds, northern fulmars depend on healthy ocean food supplies.","zh":"像許多海鳥一樣，北方管鼻鸌依賴健康的海洋食物供應。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":7},{"front":"storm-petrels","meaning":"海燕","examples":[{"en":"Storm-petrels are seabirds that nest below ground.","zh":"海燕是在地下築巢的海鳥。"},{"en":"Storm-petrels are small seabirds that often feed at sea and nest in hidden places.","zh":"海燕是小型海鳥，常在海上覓食，並在隱蔽地方築巢。"},{"en":"Storm-petrels may nest in burrows, which protects them from some predators.","zh":"海燕可能在洞穴中築巢，這可保護牠們免受一些捕食者侵害。"},{"en":"Because storm-petrels are often nocturnal, researchers may need night surveys to study them.","zh":"因為海燕通常是夜行性的，研究人員可能需要夜間調查來研究牠們。"},{"en":"Changes in ocean food supplies can affect storm-petrels and their chicks.","zh":"海洋食物供應的變化可能影響海燕及其雛鳥。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":7},{"front":"kittiwakes","meaning":"三趾鷗","examples":[{"en":"Kittiwakes are surface-feeding seabirds.","zh":"三趾鷗是表層覓食的海鳥。"},{"en":"Kittiwakes are gull-like seabirds that often feed near the sea surface.","zh":"三趾鷗是像海鷗的海鳥，常在接近海面處覓食。"},{"en":"Kittiwakes may nest on cliffs where they are safer from some land predators.","zh":"三趾鷗可能在懸崖築巢，避開一些陸地捕食者。"},{"en":"If small fish become scarce, kittiwakes may struggle to feed their chicks.","zh":"如果小魚變得稀少，三趾鷗可能難以餵養雛鳥。"},{"en":"Scientists watch kittiwakes because their breeding success can reflect ocean conditions.","zh":"科學家觀察三趾鷗，因為牠們的繁殖成功率可以反映海洋狀況。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":7},{"front":"murres","meaning":"海鴉","examples":[{"en":"Murres dive for their food.","zh":"海鴉會潛水覓食。"},{"en":"Murres are seabirds that use their wings to swim underwater after fish.","zh":"海鴉是用翅膀在水下游動追魚的海鳥。"},{"en":"Murres often nest in large groups on steep coastal cliffs.","zh":"海鴉常在陡峭沿岸懸崖上大群築巢。"},{"en":"When fish move deeper, murres may need to dive longer to find food.","zh":"當魚類移到更深水域，海鴉可能需要潛得更久來尋找食物。"},{"en":"Murres are useful for studying changes in the marine food web.","zh":"海鴉有助研究海洋食物網的變化。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":7},{"front":"auklets","meaning":"小海雀","examples":[{"en":"Auklets are seabirds that dive for food.","zh":"小海雀是會潛水覓食的海鳥。"},{"en":"Auklets are small seabirds that often feed by diving underwater.","zh":"小海雀是小型海鳥，常透過潛入水下覓食。"},{"en":"Auklets may eat plankton, small fish and other tiny sea animals.","zh":"小海雀可能吃浮游生物、小魚和其他微小海洋動物。"},{"en":"If ocean conditions change, auklets may have difficulty finding enough food.","zh":"如果海洋狀況改變，小海雀可能難以找到足夠食物。"},{"en":"Large colonies of auklets can show that nearby waters are rich in prey.","zh":"大型小海雀群落可以顯示附近水域獵物豐富。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":7},{"front":"puffins","meaning":"海鸚","examples":[{"en":"Puffins are diving seabirds found in Alaska.","zh":"海鸚是見於阿拉斯加的潛水海鳥。"},{"en":"Puffins are seabirds with colourful bills that catch fish by diving underwater.","zh":"海鸚是有彩色鳥喙的海鳥，透過潛入水下捕魚。"},{"en":"Puffins often carry several small fish in their bills to feed their chicks.","zh":"海鸚常用鳥喙叼著幾條小魚去餵雛鳥。"},{"en":"If fish are scarce, puffins may fail to raise healthy chicks.","zh":"如果魚類稀少，海鸚可能無法養育健康雛鳥。"},{"en":"Puffins attract public interest, but they also help scientists study ocean change.","zh":"海鸚能引起公眾興趣，同時也幫助科學家研究海洋變化。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":7},{"front":"form the largest colonies","meaning":"形成最大的群落","examples":[{"en":"These seabird species form the largest colonies.","zh":"這些海鳥物種形成最大的群落。"},{"en":"To form the largest colonies means to gather and breed in the biggest groups.","zh":"「form the largest colonies」意思是聚集並以最大群體繁殖。"},{"en":"Penguins form large colonies so adults and chicks can stay together in breeding areas.","zh":"企鵝形成大型群落，使成年鳥和雛鳥能留在繁殖區。"},{"en":"When birds form the largest colonies on an island, that island becomes important for conservation.","zh":"當鳥類在某島形成最大的群落，該島便對保育變得重要。"},{"en":"Species that form the largest colonies can be easier to count from the air or from boats.","zh":"形成最大群落的物種，可能較容易從空中或船上點算。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":7},{"front":"surface feeders","meaning":"表層覓食者","examples":[{"en":"Fulmars, storm-petrels and kittiwakes are surface feeders.","zh":"管鼻鸌、海燕和三趾鷗是表層覓食者。"},{"en":"Surface feeders are animals that take food from the surface or just below the surface of water.","zh":"「surface feeders」指從水面或水面下方不深處取食的動物。"},{"en":"Ducks can be surface feeders when they pick food from the top of a pond.","zh":"鴨子從池塘表面取食時，可以是表層覓食者。"},{"en":"Surface feeders may suffer if their prey moves deeper into the sea.","zh":"如果獵物移到更深海域，表層覓食者可能受影響。"},{"en":"Scientists compare surface feeders with diving birds to understand different feeding strategies.","zh":"科學家把表層覓食者與潛水鳥比較，以理解不同覓食策略。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":7},{"front":"picking their prey from","meaning":"從……拾取獵物","examples":[{"en":"Surface feeders pick their prey from the water surface.","zh":"表層覓食者從水面拾取獵物。"},{"en":"Picking their prey from a place means taking food directly from that place.","zh":"「picking their prey from」某處，意思是直接從那個地方取食。"},{"en":"Some birds pick their prey from mud after the tide goes out.","zh":"退潮後，有些鳥從泥地拾取獵物。"},{"en":"Ducks pick their prey from shallow water when insects gather there.","zh":"當昆蟲聚集在淺水處，鴨子會從淺水中拾取獵物。"},{"en":"If food no longer stays near the surface, birds that pick their prey from it may struggle.","zh":"如果食物不再停留在近水面處，從那裡拾取獵物的鳥類可能會吃力。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":7},{"front":"just below the surface","meaning":"就在水面以下","examples":[{"en":"Some seabirds feed just below the surface.","zh":"有些海鳥就在水面以下覓食。"},{"en":"Just below the surface means a little underneath the top layer of water or another material.","zh":"「just below the surface」意思是就在水或其他物質最上層下面一點。"},{"en":"Small fish were swimming just below the surface of the pond.","zh":"小魚正在池塘水面下方游動。"},{"en":"Ice can hide just below the surface of a road and make driving dangerous.","zh":"冰可能隱藏在路面下方不深處，使駕駛變得危險。"},{"en":"Birds that feed just below the surface need prey to stay near the top of the water.","zh":"就在水面以下覓食的鳥類，需要獵物留在水的上層附近。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":7},{"front":"dive for their food","meaning":"潛水覓食","examples":[{"en":"Murres, auklets and puffins dive for their food.","zh":"海鴉、小海雀和海鸚會潛水覓食。"},{"en":"To dive for their food means to go underwater to catch or collect something to eat.","zh":"「dive for their food」意思是潛入水下捕捉或取得食物。"},{"en":"Penguins dive for their food by chasing fish under the sea.","zh":"企鵝透過在海中追魚來潛水覓食。"},{"en":"Birds that dive for their food may be less affected when prey moves slightly deeper.","zh":"會潛水覓食的鳥類，在獵物稍微移到更深處時，可能受影響較小。"},{"en":"Diving for food requires energy, so animals need enough prey to make each dive worthwhile.","zh":"潛水覓食需要能量，所以動物需要足夠獵物，令每次潛水都值得。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":7},{"front":"nest primarily on","meaning":"主要在……築巢","examples":[{"en":"Fulmars nest primarily on island groups in the Bering Sea.","zh":"管鼻鸌主要在白令海的群島上築巢。"},{"en":"To nest primarily on a place means to build nests mainly there.","zh":"「nest primarily on」某地，意思是主要在那裡築巢。"},{"en":"Some birds nest primarily on cliffs because predators cannot reach them easily.","zh":"有些鳥主要在懸崖上築巢，因為捕食者不容易到達。"},{"en":"If a species nests primarily on one island, damage to that island can threaten the whole population.","zh":"如果某物種主要在一個島上築巢，該島受損可能威脅整個種群。"},{"en":"Conservationists protect places where birds nest primarily on the ground.","zh":"保育人員會保護鳥類主要在地面築巢的地方。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":8},{"front":"island groups","meaning":"群島","examples":[{"en":"Fulmars nest on island groups in and around the Bering Sea.","zh":"管鼻鸌在白令海及其周邊的群島築巢。"},{"en":"Island groups are sets of islands located near one another.","zh":"「island groups」指位置彼此接近的一組島嶼。"},{"en":"Tourists often visit island groups by boat because the islands are close together.","zh":"遊客常乘船遊覽群島，因為島嶼彼此相近。"},{"en":"Island groups can provide safe breeding places for seabirds away from mainland predators.","zh":"群島可以為海鳥提供遠離大陸捕食者的安全繁殖地。"},{"en":"If sea levels rise, low island groups may lose important nesting areas.","zh":"如果海平面上升，低窪群島可能失去重要築巢區。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":8},{"front":"in and around","meaning":"在……及其周邊","examples":[{"en":"Fulmars nest in and around the Bering Sea.","zh":"管鼻鸌在白令海及其周邊築巢。"},{"en":"In and around a place means inside that place and in the areas close to it.","zh":"「in and around」某地，意思是在該地之內以及附近地區。"},{"en":"Shops in and around the station become busy during rush hour.","zh":"車站及其周邊的商店在繁忙時間會很忙。"},{"en":"People living in and around coastal towns may depend on fishing.","zh":"居住在沿岸城鎮及其周邊的人可能依賴漁業。"},{"en":"Scientists collect samples in and around the bay to understand pollution sources.","zh":"科學家在海灣及其周邊收集樣本，以理解污染來源。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":8},{"front":"a wide variety of prey","meaning":"各式各樣的獵物","examples":[{"en":"Fulmars take a wide variety of prey.","zh":"管鼻鸌捕食各式各樣的獵物。"},{"en":"A wide variety of prey means many different kinds of animals that can be eaten by a predator.","zh":"「a wide variety of prey」指捕食者可以吃的許多不同種類動物。"},{"en":"Owls eat a wide variety of prey, including insects, mice and small birds.","zh":"貓頭鷹吃各式各樣的獵物，包括昆蟲、老鼠和小鳥。"},{"en":"Animals with a wide variety of prey may survive better when one food source declines.","zh":"擁有各式各樣獵物的動物，在某一食物來源下降時可能較能生存。"},{"en":"Studying a bird’s wide variety of prey helps scientists understand its role in the food web.","zh":"研究鳥類各式各樣的獵物，有助科學家理解牠在食物網中的角色。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":8},{"front":"zooplankton","meaning":"浮游動物","examples":[{"en":"Some seabirds feed on zooplankton.","zh":"有些海鳥以浮游動物為食。"},{"en":"Zooplankton are tiny animals that drift in water and are eaten by many fish and seabirds.","zh":"「zooplankton」是漂浮在水中的微小動物，許多魚類和海鳥都會吃它們。"},{"en":"Young fish often depend on zooplankton as an early food source.","zh":"幼魚常依賴浮游動物作為早期食物來源。"},{"en":"If warm water reduces zooplankton, the whole marine food chain can be affected.","zh":"如果溫暖海水減少浮游動物，整個海洋食物鏈都可能受影響。"},{"en":"Scientists collect water samples to measure how much zooplankton is available.","zh":"科學家收集水樣，以測量有多少浮游動物可用。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":8},{"front":"strictly nocturnal","meaning":"完全夜行性的","examples":[{"en":"Storm-petrels are strictly nocturnal.","zh":"海燕是完全夜行性的。"},{"en":"Strictly nocturnal means active only at night.","zh":"「strictly nocturnal」意思是只在夜間活動。"},{"en":"Some animals are strictly nocturnal to avoid heat and daytime predators.","zh":"有些動物是完全夜行性的，以避開高溫和日間捕食者。"},{"en":"A strictly nocturnal bird is difficult to study unless researchers work after dark.","zh":"完全夜行性的鳥很難研究，除非研究人員在天黑後工作。"},{"en":"If city lights disturb strictly nocturnal animals, their feeding and breeding may suffer.","zh":"如果城市燈光干擾完全夜行性的動物，牠們的覓食和繁殖可能受影響。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":8},{"front":"nest below ground","meaning":"在地下築巢","examples":[{"en":"Storm-petrels nest below ground in burrows or crevices.","zh":"海燕在洞穴或岩石縫隙中的地下築巢。"},{"en":"To nest below ground means to build or use a nest under the surface of the earth.","zh":"「nest below ground」意思是在地表以下築巢或使用巢穴。"},{"en":"Some birds nest below ground to hide their eggs from predators.","zh":"有些鳥在地下築巢，以隱藏牠們的蛋，避開捕食者。"},{"en":"Heavy rain can flood places where birds nest below ground.","zh":"大雨可能淹沒鳥類在地下築巢的地方。"},{"en":"Researchers must be careful not to damage burrows when birds nest below ground.","zh":"當鳥類在地下築巢時，研究人員必須小心不要破壞洞穴。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":8},{"front":"burrows","meaning":"洞穴","examples":[{"en":"Storm-petrels may nest in burrows.","zh":"海燕可能在洞穴中築巢。"},{"en":"Burrows are holes or tunnels in the ground used by animals for shelter or nesting.","zh":"「burrows」是動物用來棲身或築巢的地下洞或通道。"},{"en":"Rabbits live in burrows to stay safe from predators and bad weather.","zh":"兔子住在洞穴中，以避開捕食者和惡劣天氣。"},{"en":"If burrows collapse after heavy rain, young animals inside may die.","zh":"如果洞穴在大雨後倒塌，裡面的幼小動物可能死亡。"},{"en":"Scientists sometimes look for feathers near burrows to check whether birds are nesting there.","zh":"科學家有時在洞穴附近尋找羽毛，以檢查鳥類是否在那裡築巢。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":8},{"front":"crevices between rocks","meaning":"岩石縫隙","examples":[{"en":"Some storm-petrels nest in crevices between rocks.","zh":"有些海燕在岩石縫隙中築巢。"},{"en":"Crevices between rocks are narrow openings or cracks where rocks meet.","zh":"「crevices between rocks」指岩石相接處的狹窄開口或裂縫。"},{"en":"Small animals hide in crevices between rocks to avoid larger predators.","zh":"小動物躲在岩石縫隙中，以避開較大型捕食者。"},{"en":"Birds may use crevices between rocks when there are few trees or bushes for nesting.","zh":"當可供築巢的樹木或灌木很少時，鳥類可能使用岩石縫隙。"},{"en":"Heavy waves can make crevices between rocks unsafe for eggs and chicks.","zh":"強浪可能令岩石縫隙對鳥蛋和雛鳥變得不安全。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":8},{"front":"forage on","meaning":"以……覓食","examples":[{"en":"Storm-petrels forage on zooplankton and squid.","zh":"海燕以浮游動物和魷魚覓食。"},{"en":"To forage on something means to search for and eat that type of food.","zh":"「forage on」某物，意思是尋找並吃那類食物。"},{"en":"Bees forage on flowers to collect nectar and pollen.","zh":"蜜蜂在花上覓食，以收集花蜜和花粉。"},{"en":"Birds may forage on insects after rain brings them to the surface.","zh":"下雨把昆蟲帶到地面後，鳥類可能以昆蟲覓食。"},{"en":"If an animal cannot forage on its usual food, it may need to move or change diet.","zh":"如果動物不能以通常的食物覓食，牠可能需要遷移或改變飲食。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":8},{"front":"dependent upon small fish","meaning":"依賴小魚","examples":[{"en":"In some areas, storm-petrels are dependent upon small fish.","zh":"在一些地區，海燕依賴小魚。"},{"en":"Dependent upon small fish means needing small fish as an important food source.","zh":"「dependent upon small fish」意思是需要小魚作為重要食物來源。"},{"en":"A seabird colony may be dependent upon small fish during the chick-rearing season.","zh":"在育雛季節，海鳥群落可能依賴小魚。"},{"en":"If small fish disappear, animals dependent upon small fish may fail to raise young.","zh":"如果小魚消失，依賴小魚的動物可能無法養育幼崽或雛鳥。"},{"en":"Marine mammals and birds can both be dependent upon small fish in productive waters.","zh":"在生產力高的水域，海洋哺乳動物和鳥類都可能依賴小魚。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":8},{"front":"capelin and sand lance","meaning":"毛鱗魚和玉筋魚","examples":[{"en":"Capelin and sand lance are small fish eaten by some seabirds.","zh":"毛鱗魚和玉筋魚是一些海鳥會吃的小魚。"},{"en":"Capelin and sand lance are types of small fish that can be important prey in cold marine waters.","zh":"毛鱗魚和玉筋魚是小型魚類，在寒冷海域中可以是重要獵物。"},{"en":"Puffins may bring capelin and sand lance back to their chicks.","zh":"海鸚可能把毛鱗魚和玉筋魚帶回去餵雛鳥。"},{"en":"If capelin and sand lance decline, seabirds that depend on them may breed less successfully.","zh":"如果毛鱗魚和玉筋魚減少，依賴牠們的海鳥繁殖成功率可能下降。"},{"en":"Scientists study capelin and sand lance to understand changes in the marine food web.","zh":"科學家研究毛鱗魚和玉筋魚，以了解海洋食物網的變化。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":9},{"front":"caught at the surface","meaning":"在水面被捕食","examples":[{"en":"Some small fish are caught at the surface.","zh":"有些小魚在水面被捕食。"},{"en":"Caught at the surface means captured from the top layer of water.","zh":"「caught at the surface」意思是從水的最上層被捕捉。"},{"en":"Fish are easier to catch at the surface when they gather near floating plankton.","zh":"當魚聚集在漂浮浮游生物附近時，牠們較容易在水面被捕捉。"},{"en":"Birds that cannot dive deeply depend on prey that can be caught at the surface.","zh":"不能深潛的鳥類依賴可以在水面被捕食的獵物。"},{"en":"If prey stops being caught at the surface, surface-feeding birds may struggle.","zh":"如果獵物不再能在水面被捕食，表層覓食的鳥類可能會吃力。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":9},{"front":"black-legged kittiwakes","meaning":"黑腳三趾鷗","examples":[{"en":"Black-legged kittiwakes are widespread in Alaska, Canada and Eurasia.","zh":"黑腳三趾鷗廣泛分布於阿拉斯加、加拿大和歐亞大陸。"},{"en":"Black-legged kittiwakes are seabirds with dark legs that often feed near the ocean surface.","zh":"黑腳三趾鷗是有黑色腳的海鳥，常在海面附近覓食。"},{"en":"Black-legged kittiwakes nest on cliffs and may return to the same colonies each year.","zh":"黑腳三趾鷗在懸崖築巢，並可能每年回到同一群落。"},{"en":"If fish near the continental shelf decline, black-legged kittiwakes may have difficulty feeding chicks.","zh":"如果大陸架附近的魚類減少，黑腳三趾鷗可能難以餵養雛鳥。"},{"en":"Scientists monitor black-legged kittiwakes because their numbers can reflect marine conditions.","zh":"科學家監測黑腳三趾鷗，因為牠們的數量可以反映海洋狀況。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":9},{"front":"red-legged kittiwakes","meaning":"紅腳三趾鷗","examples":[{"en":"Red-legged kittiwakes are found only in the Bering Sea region.","zh":"紅腳三趾鷗只見於白令海地區。"},{"en":"Red-legged kittiwakes are seabirds with red legs and a limited breeding range.","zh":"紅腳三趾鷗是有紅色腳、繁殖範圍有限的海鳥。"},{"en":"Because red-legged kittiwakes live in a smaller area, local environmental change can affect them strongly.","zh":"因為紅腳三趾鷗生活範圍較小，本地環境變化可能強烈影響牠們。"},{"en":"Red-legged kittiwakes may forage farther from land than some other kittiwakes.","zh":"紅腳三趾鷗可能比一些其他三趾鷗在離陸地更遠處覓食。"},{"en":"Protecting the Bering Sea is important for red-legged kittiwakes because they are not widely distributed.","zh":"保護白令海對紅腳三趾鷗很重要，因為牠們並非廣泛分布。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":9},{"front":"widespread throughout","meaning":"廣泛分布於","examples":[{"en":"Black-legged kittiwakes are widespread throughout Alaska, Canada and Eurasia.","zh":"黑腳三趾鷗廣泛分布於阿拉斯加、加拿大和歐亞大陸。"},{"en":"Widespread throughout a place means found in many parts of that whole area.","zh":"「widespread throughout」某地，意思是在整個地區許多部分都能找到。"},{"en":"Mobile phones are widespread throughout most modern cities.","zh":"手機在大多數現代城市廣泛普及。"},{"en":"If a disease becomes widespread throughout a region, hospitals may face heavy pressure.","zh":"如果疾病廣泛傳播於某地區，醫院可能面對沉重壓力。"},{"en":"A species that is widespread throughout several countries may still need protection if its habitat declines.","zh":"即使某物種廣泛分布於幾個國家，如果其棲息地下降，仍可能需要保護。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":9},{"front":"found only in","meaning":"只見於","examples":[{"en":"Red-legged kittiwakes are found only in the Bering Sea region.","zh":"紅腳三趾鷗只見於白令海地區。"},{"en":"Found only in a place means existing or being seen only there, not elsewhere.","zh":"「found only in」某地，意思是只存在或只見於那裡，而不在其他地方。"},{"en":"Some plants are found only in one mountain valley.","zh":"有些植物只見於一個山谷。"},{"en":"Animals found only in a small area can be at greater risk if that habitat is damaged.","zh":"只見於小範圍地區的動物，如果棲息地受損，可能面對較大風險。"},{"en":"A word found only in one dialect may carry special local meaning.","zh":"只見於某一方言的詞語，可能承載特殊本地意義。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":9},{"front":"feed primarily on","meaning":"主要以……為食","examples":[{"en":"Black-legged kittiwakes feed primarily on small fish.","zh":"黑腳三趾鷗主要以小魚為食。"},{"en":"To feed primarily on something means to eat it as the main food source.","zh":"「feed primarily on」某物，意思是以它作為主要食物來源。"},{"en":"Pandas feed primarily on bamboo, although they may eat other things.","zh":"熊貓主要以竹子為食，雖然牠們也可能吃其他東西。"},{"en":"Birds that feed primarily on insects may suffer if pesticides reduce insect numbers.","zh":"主要以昆蟲為食的鳥類，在殺蟲劑減少昆蟲數量時可能受影響。"},{"en":"Knowing what animals feed primarily on helps scientists protect their food supply.","zh":"了解動物主要以什麼為食，有助科學家保護其食物供應。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":9},{"front":"continental shelf","meaning":"大陸架","examples":[{"en":"Black-legged kittiwakes forage over the continental shelf.","zh":"黑腳三趾鷗在大陸架上方覓食。"},{"en":"The continental shelf is the shallow seabed area that extends from the edge of a continent.","zh":"「大陸架」是從大陸邊緣延伸出去的較淺海床區域。"},{"en":"Many fish live over the continental shelf because sunlight and nutrients support food chains there.","zh":"許多魚生活在大陸架上方，因為陽光和營養物質支撐那裡的食物鏈。"},{"en":"Fishing boats often work near the continental shelf where marine life is abundant.","zh":"漁船常在大陸架附近作業，因為那裡海洋生物豐富。"},{"en":"Changes over the continental shelf can affect birds, fish and marine mammals.","zh":"大陸架上方的變化可以影響鳥類、魚類和海洋哺乳動物。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":9},{"front":"shelf break","meaning":"大陸架坡折","examples":[{"en":"Some kittiwakes forage near or beyond the shelf break.","zh":"有些三趾鷗在大陸架坡折附近或以外覓食。"},{"en":"The shelf break is the area where the shallow continental shelf drops into deeper ocean.","zh":"「shelf break」是較淺大陸架下降到深海的位置。"},{"en":"Fish may gather near the shelf break because currents bring nutrients there.","zh":"魚類可能聚集在大陸架坡折附近，因為海流會把營養物質帶到那裡。"},{"en":"Birds that feed near the shelf break may travel far from their nests.","zh":"在大陸架坡折附近覓食的鳥類，可能要離巢很遠。"},{"en":"Scientists study the shelf break because it can be an important feeding zone.","zh":"科學家研究大陸架坡折，因為它可以是重要覓食區。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":9},{"front":"beyond the shelf break","meaning":"在大陸架坡折以外","examples":[{"en":"Red-legged kittiwakes may forage beyond the shelf break.","zh":"紅腳三趾鷗可能在大陸架坡折以外覓食。"},{"en":"Beyond the shelf break means farther out than the point where shallow seabed drops into deep ocean.","zh":"「beyond the shelf break」意思是在淺海床下降到深海的位置之外更遠處。"},{"en":"Some fishing boats travel beyond the shelf break to reach deeper-water species.","zh":"有些漁船駛到大陸架坡折以外，以捕捉深水物種。"},{"en":"Birds feeding beyond the shelf break may need more energy to reach their food.","zh":"在大陸架坡折以外覓食的鳥類，可能需要更多能量去到食物所在地。"},{"en":"Ocean conditions beyond the shelf break can differ greatly from coastal waters.","zh":"大陸架坡折以外的海洋狀況，可能與沿岸水域大不相同。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":9},{"front":"marine mammals","meaning":"海洋哺乳動物","examples":[{"en":"Marine mammals have also shown signs of food stress.","zh":"海洋哺乳動物也顯示出食物壓力的跡象。"},{"en":"Marine mammals are warm-blooded animals that live in the sea, such as seals, whales and sea lions.","zh":"「marine mammals」是生活在海中的溫血動物，例如海豹、鯨魚和海獅。"},{"en":"Marine mammals breathe air, even though many spend most of their lives in water.","zh":"海洋哺乳動物呼吸空氣，雖然許多一生大部分時間都在水中。"},{"en":"If fish supplies decline, marine mammals may lose weight or have fewer young.","zh":"如果魚類供應下降，海洋哺乳動物可能體重下降或幼崽減少。"},{"en":"Protecting marine mammals often means protecting both their feeding areas and breeding sites.","zh":"保護海洋哺乳動物，常意味著保護牠們的覓食區和繁殖地。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":9},{"front":"exhibited similar signs of","meaning":"顯示出類似……跡象","examples":[{"en":"Marine mammals have exhibited similar signs of food stress.","zh":"海洋哺乳動物顯示出類似食物壓力的跡象。"},{"en":"Exhibited similar signs of something means showed the same kinds of evidence or symptoms.","zh":"「exhibited similar signs of」某事，意思是顯示出相同類型的證據或症狀。"},{"en":"Several students exhibited similar signs of stress before the final exam.","zh":"幾名學生在期末考試前顯示出類似壓力的跡象。"},{"en":"Trees in different parks exhibited similar signs of disease after the hot summer.","zh":"炎熱夏季後，不同公園的樹木顯示出類似疾病跡象。"},{"en":"If different animals exhibit similar signs of food stress, the problem may affect the whole ecosystem.","zh":"如果不同動物顯示出類似食物壓力的跡象，問題可能影響整個生態系統。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":10},{"front":"food stress","meaning":"食物壓力","examples":[{"en":"Food stress can affect seabirds and marine mammals.","zh":"食物壓力可以影響海鳥和海洋哺乳動物。"},{"en":"Food stress happens when animals cannot get enough suitable food.","zh":"「food stress」指動物無法獲得足夠合適食物的情況。"},{"en":"Food stress may cause adult birds to lose weight and feed their chicks less often.","zh":"食物壓力可能令成年鳥體重下降，並較少餵養雛鳥。"},{"en":"A drought can create food stress for livestock when grass stops growing.","zh":"當草停止生長時，乾旱可以為牲畜造成食物壓力。"},{"en":"Scientists look for food stress by checking body condition, birth rates and survival.","zh":"科學家透過檢查身體狀況、出生率和存活率來尋找食物壓力。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":10},{"front":"in recent years","meaning":"近年來","examples":[{"en":"Marine mammals have shown food stress in recent years.","zh":"海洋哺乳動物近年來顯示出食物壓力。"},{"en":"In recent years means during the last few years, not long ago.","zh":"「in recent years」意思是在過去幾年，即不久之前的期間。"},{"en":"In recent years, many schools have used more online learning tools.","zh":"近年來，許多學校使用了更多網上學習工具。"},{"en":"Housing has become more expensive in recent years in many large cities.","zh":"近年來，許多大城市的住屋變得更昂貴。"},{"en":"Scientists compare recent years with older records to see whether change is unusual.","zh":"科學家把近年與較舊記錄比較，以了解變化是否異常。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":10},{"front":"harbor seals","meaning":"港海豹","examples":[{"en":"Harbor seals declined sharply at Tugidak Island.","zh":"Tugidak 島的港海豹數量急劇下降。"},{"en":"Harbor seals are marine mammals that often live near coasts and rest on rocks or beaches.","zh":"港海豹是常生活在沿岸附近、並在岩石或海灘上休息的海洋哺乳動物。"},{"en":"Harbor seals feed on fish and can be affected when fish supplies change.","zh":"港海豹以魚為食，因此可能受魚類供應變化影響。"},{"en":"Scientists count harbor seals to understand whether coastal ecosystems are healthy.","zh":"科學家計算港海豹數量，以了解沿岸生態系統是否健康。"},{"en":"A decline in harbor seals may signal wider problems in the marine food web.","zh":"港海豹數量下降，可能顯示海洋食物網存在更廣泛問題。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":10},{"front":"Tugidak Island","meaning":"Tugidak 島","examples":[{"en":"Harbor seals declined at Tugidak Island in the Gulf of Alaska.","zh":"港海豹在阿拉斯加灣的 Tugidak 島數量下降。"},{"en":"Tugidak Island is an island in the Gulf of Alaska used in studies of seal populations.","zh":"Tugidak 島是阿拉斯加灣的一個島嶼，被用於研究海豹種群。"},{"en":"Scientists may study Tugidak Island because changes there can reveal problems in marine mammal health.","zh":"科學家可能研究 Tugidak 島，因為那裡的變化可以揭示海洋哺乳動物健康問題。"},{"en":"If seal numbers fall at Tugidak Island, researchers may examine food supply and breeding success.","zh":"如果 Tugidak 島的海豹數量下降，研究人員可能檢查食物供應和繁殖成功率。"},{"en":"Tugidak Island is important in this passage because it provides evidence of marine mammal decline.","zh":"Tugidak 島在本文中重要，因為它提供海洋哺乳動物下降的證據。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":10},{"front":"Gulf of Alaska","meaning":"阿拉斯加灣","examples":[{"en":"Several marine mammal populations declined in the Gulf of Alaska.","zh":"幾個海洋哺乳動物種群在阿拉斯加灣下降。"},{"en":"The Gulf of Alaska is a large body of water along the southern coast of Alaska.","zh":"「阿拉斯加灣」是阿拉斯加南岸沿線的一大片水域。"},{"en":"The Gulf of Alaska supports fish, seabirds and marine mammals.","zh":"阿拉斯加灣支撐魚類、海鳥和海洋哺乳動物。"},{"en":"Storms in the Gulf of Alaska can affect ships and coastal communities.","zh":"阿拉斯加灣的風暴可以影響船隻和沿岸社區。"},{"en":"Changes in the Gulf of Alaska may influence food supplies for both birds and mammals.","zh":"阿拉斯加灣的變化可能影響鳥類和哺乳動物的食物供應。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":10},{"front":"declined by about","meaning":"下降約","examples":[{"en":"Harbor seals declined by about 85%.","zh":"港海豹數量下降約百分之八十五。"},{"en":"Declined by about means decreased by approximately a certain amount.","zh":"「declined by about」意思是大約減少某個數量。"},{"en":"Sales declined by about 20% after the shop moved to a quieter street.","zh":"商店搬到較冷清的街道後，銷售額下降約百分之二十。"},{"en":"If rainfall declines by about half, farmers may face serious water shortages.","zh":"如果降雨量下降約一半，農民可能面對嚴重缺水。"},{"en":"A population that declines by about 85% has lost most of its members.","zh":"下降約百分之八十五的種群，已失去大部分成員。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":10},{"front":"Steller sea lion populations","meaning":"北海獅種群","examples":[{"en":"Steller sea lion populations declined in the Gulf of Alaska.","zh":"北海獅種群在阿拉斯加灣下降。"},{"en":"Steller sea lion populations are groups of Steller sea lions living in particular areas.","zh":"「Steller sea lion populations」指生活在特定地區的北海獅群體。"},{"en":"Scientists monitor Steller sea lion populations to check birth rates and survival.","zh":"科學家監測北海獅種群，以檢查出生率和存活率。"},{"en":"If Steller sea lion populations fall, the cause may include food shortage or disease.","zh":"如果北海獅種群下降，原因可能包括食物短缺或疾病。"},{"en":"Protecting Steller sea lion populations requires safe breeding places and enough prey.","zh":"保護北海獅種群需要安全的繁殖地和足夠獵物。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":10},{"front":"declined by another","meaning":"再下降……","examples":[{"en":"Steller sea lion populations declined by another 59% between 1985 and 1990.","zh":"北海獅種群在1985年至1990年間再下降百分之五十九。"},{"en":"Declined by another means decreased further by an additional amount.","zh":"「declined by another」意思是再進一步減少額外數量。"},{"en":"The shop’s income declined by another 10% after a new competitor opened nearby.","zh":"附近有新競爭者開業後，商店收入再下降百分之十。"},{"en":"If a population declines by another large amount, recovery becomes much harder.","zh":"如果一個種群再大幅下降，恢復會變得困難得多。"},{"en":"A student’s attendance declined by another week of absence after illness returned.","zh":"學生病情復發後，出席又再減少一星期。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":10},{"front":"northern fur seals","meaning":"北方海狗","examples":[{"en":"Northern fur seals declined from their average numbers in the 1970s.","zh":"北方海狗從1970年代的平均數量下降。"},{"en":"Northern fur seals are marine mammals with thick fur that live in northern ocean regions.","zh":"北方海狗是有厚毛、生活在北方海洋地區的海洋哺乳動物。"},{"en":"Northern fur seals come onto land to breed but feed mainly at sea.","zh":"北方海狗到陸地繁殖，但主要在海上覓食。"},{"en":"If food becomes scarce, northern fur seals may have fewer healthy pups.","zh":"如果食物變得稀少，北方海狗可能有較少健康幼崽。"},{"en":"Scientists track northern fur seals to understand long-term changes in marine ecosystems.","zh":"科學家追蹤北方海狗，以了解海洋生態系統的長期變化。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":10},{"front":"average numbers","meaning":"平均數量","examples":[{"en":"Northern fur seals declined from their average numbers in the 1970s.","zh":"北方海狗從1970年代的平均數量下降。"},{"en":"Average numbers are the usual or typical numbers calculated over a period.","zh":"「average numbers」是某段期間計算出的通常或典型數量。"},{"en":"A school compares this year’s absences with average numbers from previous years.","zh":"學校把今年缺席人數與往年的平均數量比較。"},{"en":"If rainfall falls below average numbers, farmers may need extra irrigation.","zh":"如果降雨量低於平均數量，農民可能需要額外灌溉。"},{"en":"Average numbers help scientists see whether a change is normal or worrying.","zh":"平均數量幫助科學家判斷某個變化是正常還是令人擔憂。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":10},{"front":"rebounded somewhat","meaning":"有所回升","examples":[{"en":"Northern fur seal numbers had rebounded somewhat by 1990.","zh":"到1990年，北方海狗數量已有所回升。"},{"en":"Rebounded somewhat means recovered a little after falling.","zh":"「rebounded somewhat」意思是在下降後稍微恢復。"},{"en":"Sales rebounded somewhat after the shop offered discounts.","zh":"商店提供折扣後，銷售額有所回升。"},{"en":"A student’s confidence rebounded somewhat after receiving helpful feedback.","zh":"學生收到有幫助的回饋後，信心有所回升。"},{"en":"Even if animal numbers rebound somewhat, they may still remain below earlier levels.","zh":"即使動物數量有所回升，仍可能低於早期水平。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":11},{"front":"associated with","meaning":"與……相關","examples":[{"en":"Several biological changes were associated with the declines.","zh":"幾種生物變化與這些下降相關。"},{"en":"Associated with means connected to something, though not always directly caused by it.","zh":"「associated with」意思是與某事有關聯，雖然不一定由它直接造成。"},{"en":"Poor sleep is associated with lower concentration at school.","zh":"睡眠不足與學校專注力較低相關。"},{"en":"Heavy rainfall may be associated with more flooding in low areas.","zh":"強降雨可能與低窪地區更多洪水相關。"},{"en":"Scientists look for factors associated with disease before deciding what causes it.","zh":"科學家在決定疾病成因前，會尋找與疾病相關的因素。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":11},{"front":"declines in birth rate","meaning":"出生率下降","examples":[{"en":"Declines in birth rate were associated with falling sea lion populations.","zh":"出生率下降與海獅種群下跌相關。"},{"en":"Declines in birth rate mean fewer babies or young animals are born over time.","zh":"「declines in birth rate」指隨時間有較少嬰兒或幼小動物出生。"},{"en":"Declines in birth rate can make a population age and shrink.","zh":"出生率下降可能令人口老化並縮小。"},{"en":"In animals, declines in birth rate may happen when adults lack enough food.","zh":"在動物中，出生率下降可能在成年個體缺乏足夠食物時發生。"},{"en":"Governments study declines in birth rate to plan schools, housing and healthcare.","zh":"政府研究出生率下降，以規劃學校、住屋和醫療。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":11},{"front":"breeding females","meaning":"繁殖雌性","examples":[{"en":"There were fewer breeding females among Steller sea lions.","zh":"北海獅中的繁殖雌性較少。"},{"en":"Breeding females are adult females that are able to produce young.","zh":"「breeding females」是能夠繁殖後代的成年雌性。"},{"en":"If there are fewer breeding females, a population may recover more slowly.","zh":"如果繁殖雌性較少，種群可能恢復得更慢。"},{"en":"Scientists count breeding females to estimate how many young animals may be born.","zh":"科學家計算繁殖雌性，以估計可能有多少幼小動物出生。"},{"en":"Protecting breeding females is important because they directly affect future population size.","zh":"保護繁殖雌性很重要，因為牠們直接影響未來種群規模。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":11},{"front":"fewer pups","meaning":"幼崽減少","examples":[{"en":"Declining populations were associated with fewer pups.","zh":"種群下降與幼崽減少相關。"},{"en":"Fewer pups means a smaller number of baby animals, especially baby seals or sea lions.","zh":"「fewer pups」意思是幼小動物數量較少，尤其指海豹或海獅幼崽。"},{"en":"If mothers are weak, there may be fewer pups born each year.","zh":"如果母獸身體虛弱，每年出生的幼崽可能較少。"},{"en":"Fewer pups can be an early warning that a marine mammal population is in trouble.","zh":"幼崽減少可以是海洋哺乳動物種群出問題的早期警告。"},{"en":"Scientists compare pup numbers over time to see whether reproduction is improving.","zh":"科學家比較不同年份的幼崽數量，以了解繁殖是否改善。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":11},{"front":"decreased adult body condition","meaning":"成年個體身體狀況下降","examples":[{"en":"Steller sea lions showed decreased adult body condition.","zh":"北海獅顯示出成年個體身體狀況下降。"},{"en":"Decreased adult body condition means adult animals are thinner, weaker or less healthy than before.","zh":"「decreased adult body condition」意思是成年動物比以前更瘦、更弱或較不健康。"},{"en":"A lack of food can lead to decreased adult body condition in wild animals.","zh":"食物不足可以導致野生動物成年個體身體狀況下降。"},{"en":"Decreased adult body condition may reduce breeding success.","zh":"成年個體身體狀況下降可能降低繁殖成功率。"},{"en":"Researchers check weight and fat levels to measure decreased adult body condition.","zh":"研究人員檢查體重和脂肪水平，以衡量成年個體身體狀況下降。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":11},{"front":"decreased juvenile survival","meaning":"幼年個體存活率下降","examples":[{"en":"The decline was linked with decreased juvenile survival.","zh":"這一下降與幼年個體存活率下降有關。"},{"en":"Decreased juvenile survival means fewer young animals live long enough to grow older.","zh":"「decreased juvenile survival」指較少年幼動物能活到長大。"},{"en":"Decreased juvenile survival can happen when young animals lack food or protection.","zh":"當年幼動物缺乏食物或保護時，幼年個體存活率可能下降。"},{"en":"If juvenile survival decreases, the population may shrink in future years.","zh":"如果幼年個體存活率下降，未來幾年種群可能縮小。"},{"en":"Scientists study decreased juvenile survival to understand why a species is not recovering.","zh":"科學家研究幼年個體存活率下降，以理解某物種為何沒有恢復。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":11},{"front":"population age structure","meaning":"種群年齡結構","examples":[{"en":"The population age structure also changed.","zh":"種群年齡結構也發生了變化。"},{"en":"Population age structure means the balance of young, adult and old members in a population.","zh":"「population age structure」指一個種群中幼年、成年和老年成員的比例平衡。"},{"en":"A country with many elderly people has a different population age structure from one with many children.","zh":"有很多長者的國家，其人口年齡結構與有很多兒童的國家不同。"},{"en":"If few young animals survive, the population age structure becomes older.","zh":"如果很少年幼動物存活，種群年齡結構會變得較老。"},{"en":"Population age structure helps scientists predict future growth or decline.","zh":"種群年齡結構幫助科學家預測未來增長或下降。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":11},{"front":"monsoon seasons","meaning":"季風季節","examples":[{"en":"Walker studied climate patterns during monsoon seasons.","zh":"Walker 研究季風季節期間的氣候模式。"},{"en":"Monsoon seasons are periods when seasonal winds bring heavy rain to certain regions.","zh":"「monsoon seasons」是季節性風向某些地區帶來大量降雨的時期。"},{"en":"Farmers may depend on monsoon seasons to water their crops.","zh":"農民可能依賴季風季節為農作物供水。"},{"en":"If monsoon seasons arrive late, food production can be delayed or reduced.","zh":"如果季風季節遲來，糧食生產可能延遲或減少。"},{"en":"Strong monsoon seasons can bring both useful rain and dangerous flooding.","zh":"強烈季風季節可以帶來有用雨水，也可以帶來危險洪水。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":11},{"front":"low-index conditions","meaning":"低指數狀態","examples":[{"en":"Low-index conditions are often linked with drought.","zh":"低指數狀態常與乾旱有關。"},{"en":"Low-index conditions refer to a particular measured climate pattern with lower-than-usual index values.","zh":"「low-index conditions」指某種被測量的氣候模式，其指數值低於通常水平。"},{"en":"Scientists may compare low-index conditions with rainfall records to see whether drought is likely.","zh":"科學家可能把低指數狀態與降雨記錄比較，以判斷乾旱是否可能發生。"},{"en":"Low-index conditions can help explain why distant regions experience unusual weather at the same time.","zh":"低指數狀態可以幫助解釋為什麼相距很遠的地區同時出現異常天氣。"},{"en":"Without enough data, low-index conditions may be difficult for beginners to interpret.","zh":"沒有足夠數據，低指數狀態對初學者可能難以解讀。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":11},{"front":"marked by drought","meaning":"以乾旱為特徵","examples":[{"en":"Some monsoon seasons are marked by drought.","zh":"有些季風季節以乾旱為特徵。"},{"en":"Marked by drought means clearly characterised by a serious lack of rain.","zh":"「marked by drought」意思是明顯以嚴重缺雨為特徵。"},{"en":"A summer marked by drought can leave parks brown and rivers low.","zh":"以乾旱為特徵的夏天，可能令公園變黃、河流水位偏低。"},{"en":"Farming regions marked by drought may need emergency water supplies.","zh":"以乾旱為特徵的農業地區，可能需要緊急供水。"},{"en":"When a year is marked by drought, food prices may rise because harvests fall.","zh":"當某一年以乾旱為特徵，收成下降可能令食物價格上升。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":11},{"front":"parts of Africa","meaning":"非洲部分地區","examples":[{"en":"Drought may affect Australia, Indonesia, India and parts of Africa.","zh":"乾旱可能影響澳洲、印尼、印度和非洲部分地區。"},{"en":"Parts of Africa means some areas of the African continent, not the whole continent.","zh":"「parts of Africa」指非洲大陸的一些地區，而不是整個大陸。"},{"en":"Parts of Africa experience long dry seasons, while other areas receive heavy rain.","zh":"非洲部分地區經歷漫長旱季，而其他地區則有大量降雨。"},{"en":"Disease control can be difficult in parts of Africa where clinics are far apart.","zh":"在診所相距很遠的非洲部分地區，疾病控制可能很困難。"},{"en":"It is more accurate to say parts of Africa than to treat the whole continent as one place.","zh":"說「非洲部分地區」比把整個大陸當成一個地方更準確。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":12},{"front":"low-index winters","meaning":"低指數冬季","examples":[{"en":"Low-index winters tend to be mild in western Canada.","zh":"低指數冬季在加拿大西部往往較溫和。"},{"en":"Low-index winters are winters that happen under a particular low-index climate pattern.","zh":"「low-index winters」是在某種低指數氣候模式下出現的冬季。"},{"en":"Scientists compare low-index winters with normal winters to find differences in temperature.","zh":"科學家把低指數冬季與正常冬季比較，以找出氣溫差異。"},{"en":"Low-index winters may bring unusual weather to places far apart.","zh":"低指數冬季可能為相距很遠的地方帶來異常天氣。"},{"en":"If low-index winters become more common, heating demand may change in some regions.","zh":"如果低指數冬季變得更常見，某些地區的供暖需求可能改變。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":12},{"front":"tend to be","meaning":"往往是","examples":[{"en":"Low-index winters tend to be unusually mild.","zh":"低指數冬季往往異常溫和。"},{"en":"Tend to be means usually are, although not always.","zh":"「tend to be」意思是通常是，但並非永遠如此。"},{"en":"Small classes tend to be easier for teachers to manage.","zh":"小班教學往往較容易讓老師管理。"},{"en":"Roads tend to be busier before long public holidays.","zh":"長公眾假期前，道路往往更繁忙。"},{"en":"Animals tend to be more active when food is easy to find.","zh":"當食物容易找到，動物往往更活躍。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":12},{"front":"unusually mild","meaning":"異常溫和","examples":[{"en":"Some winters in western Canada are unusually mild.","zh":"加拿大西部有些冬季異常溫和。"},{"en":"Unusually mild means warmer or less severe than expected.","zh":"「unusually mild」意思是比預期更暖或較不嚴寒。"},{"en":"An unusually mild winter may reduce heating costs.","zh":"異常溫和的冬季可能降低取暖成本。"},{"en":"If spring is unusually mild, flowers may bloom earlier than usual.","zh":"如果春天異常溫和，花可能比平時更早開。"},{"en":"Unusually mild weather can still cause problems if animals or crops respond too early.","zh":"即使天氣異常溫和，如果動物或農作物太早作出反應，仍可能造成問題。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":12},{"front":"western Canada","meaning":"加拿大西部","examples":[{"en":"Walker linked low-index winters with mild weather in western Canada.","zh":"Walker 把低指數冬季與加拿大西部的溫和天氣聯繫起來。"},{"en":"Western Canada means the western part of Canada, including provinces near the Pacific coast and the Rockies.","zh":"「western Canada」指加拿大西部，包括靠近太平洋沿岸和洛磯山脈的省份。"},{"en":"Western Canada can experience cold winters, mountain weather and coastal rain.","zh":"加拿大西部可能經歷寒冷冬季、山區天氣和沿岸降雨。"},{"en":"Farmers in western Canada pay close attention to snow and rainfall.","zh":"加拿大西部的農民密切留意降雪和降雨。"},{"en":"Weather changes in western Canada can affect forests, transport and energy use.","zh":"加拿大西部的天氣變化可以影響森林、交通和能源使用。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":12},{"front":"British colleagues","meaning":"英國同事","examples":[{"en":"One of Walker’s British colleagues criticised his idea.","zh":"Walker 的一位英國同事批評了他的想法。"},{"en":"British colleagues are people from Britain who work with someone in the same field or organisation.","zh":"「British colleagues」指來自英國、在同一領域或機構一起工作的人。"},{"en":"A scientist may discuss research results with British colleagues at a conference.","zh":"科學家可能在會議上與英國同事討論研究結果。"},{"en":"British colleagues can offer different views if they work in another academic tradition.","zh":"如果英國同事在另一種學術傳統中工作，他們可以提供不同看法。"},{"en":"Walker’s British colleagues were important because their criticism showed how unusual his idea seemed.","zh":"Walker 的英國同事很重要，因為他們的批評顯示他的想法當時多麼不尋常。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":12},{"front":"chided him in print","meaning":"在文章中責備他","examples":[{"en":"One colleague chided Walker in print.","zh":"一位同事在文章中責備 Walker。"},{"en":"Chided him in print means criticised him publicly in written form.","zh":"「chided him in print」意思是以書面形式公開批評他。"},{"en":"A reviewer chided the author in print for ignoring important evidence.","zh":"評論者在文章中責備作者忽略重要證據。"},{"en":"When a scientist is chided in print, other researchers can read the criticism.","zh":"當科學家在文章中被責備，其他研究人員都可以讀到批評。"},{"en":"Being chided in print can be embarrassing, but it may also force clearer explanation.","zh":"在文章中被責備可能令人尷尬，但也可能迫使人作出更清楚解釋。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":12},{"front":"suggesting that","meaning":"提出……","examples":[{"en":"The colleague criticised Walker for suggesting that distant climates were linked.","zh":"那位同事批評 Walker 提出遙遠地區的氣候有關聯。"},{"en":"Suggesting that means saying or implying that something may be true.","zh":"「suggesting that」意思是說出或暗示某事可能是真的。"},{"en":"A teacher may question a student for suggesting that evidence is unnecessary.","zh":"老師可能質疑學生提出證據並不必要。"},{"en":"The report is suggesting that poor sleep affects exam performance.","zh":"報告提出睡眠不足會影響考試表現。"},{"en":"Suggesting that two problems are connected can be useful, but it needs evidence.","zh":"提出兩個問題有關聯可以有用，但需要證據。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":12},{"front":"climatic conditions","meaning":"氣候狀況","examples":[{"en":"Climatic conditions in distant regions may be linked.","zh":"遙遠地區的氣候狀況可能有關聯。"},{"en":"Climatic conditions are the weather patterns and environmental conditions typical of a place over time.","zh":"「climatic conditions」是某地長期典型的天氣模式和環境條件。"},{"en":"Hot, dry climatic conditions can make farming difficult.","zh":"炎熱乾燥的氣候狀況可能令農業變得困難。"},{"en":"Animals adapt their behaviour to local climatic conditions.","zh":"動物會調整行為以適應本地氣候狀況。"},{"en":"When climatic conditions change suddenly, people may need new ways to manage water and food.","zh":"當氣候狀況突然改變，人們可能需要新的方式管理水和食物。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":12},{"front":"widely separated regions","meaning":"相距很遠的地區","examples":[{"en":"Walker linked climatic conditions over widely separated regions.","zh":"Walker 把相距很遠地區的氣候狀況聯繫起來。"},{"en":"Widely separated regions are areas that are very far apart from one another.","zh":"「widely separated regions」指彼此距離非常遠的地區。"},{"en":"Weather events in widely separated regions can sometimes be connected by atmospheric patterns.","zh":"相距很遠地區的天氣事件，有時可以由大氣模式連接起來。"},{"en":"Researchers compare schools in widely separated regions to see whether the same policy works everywhere.","zh":"研究人員比較相距很遠地區的學校，以了解同一政策是否到處有效。"},{"en":"If disease appears in widely separated regions at the same time, scientists look for a shared cause.","zh":"如果疾病同時出現在相距很遠的地區，科學家會尋找共同原因。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":12},{"front":"could be linked","meaning":"可能有關聯","examples":[{"en":"Walker believed that climate conditions in distant regions could be linked.","zh":"Walker 認為遙遠地區的氣候狀況可能有關聯。"},{"en":"Could be linked means might be connected, although this still needs evidence.","zh":"「could be linked」意思是可能有關聯，但仍需要證據。"},{"en":"A headache and poor sleep could be linked if both happen after stress.","zh":"如果頭痛和睡眠不足都在壓力後出現，兩者可能有關聯。"},{"en":"Falling fish numbers could be linked to warmer water or overfishing.","zh":"魚類數量下降可能與水溫上升或過度捕魚有關聯。"},{"en":"Scientists use data to test whether two events could be linked.","zh":"科學家使用數據來測試兩件事是否可能有關聯。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":12},{"front":"in his reply","meaning":"在他的回應中","examples":[{"en":"In his reply, Walker predicted that an explanation would be found.","zh":"在他的回應中，Walker 預測會找到解釋。"},{"en":"In his reply means in the answer or response he gave.","zh":"「in his reply」意思是在他給出的答案或回應中。"},{"en":"In his reply, the teacher explained why the student’s argument was incomplete.","zh":"在他的回應中，老師解釋了為什麼學生的論點不完整。"},{"en":"In his reply to the complaint, the manager promised to investigate the problem.","zh":"在他對投訴的回應中，經理承諾調查問題。"},{"en":"A scientist may correct misunderstandings in his reply to criticism.","zh":"科學家可能在他對批評的回應中糾正誤解。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":13},{"front":"predicted correctly","meaning":"正確預測","examples":[{"en":"Walker predicted correctly that an explanation would be forthcoming.","zh":"Walker 正確預測解釋即將出現。"},{"en":"Predicted correctly means said what would happen, and later it proved true.","zh":"「predicted correctly」意思是說出將會發生的事，而後來證明是真的。"},{"en":"The doctor predicted correctly that the patient would recover within a week.","zh":"醫生正確預測病人會在一星期內康復。"},{"en":"Weather experts predicted correctly that the storm would arrive at night.","zh":"天氣專家正確預測風暴會在夜間到達。"},{"en":"A student predicted correctly when the answer matched the evidence.","zh":"當答案與證據吻合，學生就是正確預測。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":13},{"front":"forthcoming","meaning":"即將出現的","examples":[{"en":"Walker believed that an explanation would be forthcoming.","zh":"Walker 認為解釋即將出現。"},{"en":"Forthcoming means coming soon or likely to appear soon.","zh":"「forthcoming」意思是很快會出現或很可能即將出現。"},{"en":"More details about the school trip will be forthcoming next week.","zh":"關於學校旅行的更多詳情將於下星期即將公布。"},{"en":"If evidence is forthcoming, the argument will become much stronger.","zh":"如果證據即將出現，論點會變得更有力。"},{"en":"Help was not forthcoming, so the family had to solve the problem alone.","zh":"幫助沒有即將出現，所以那個家庭不得不獨自解決問題。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":13},{"front":"require a knowledge of","meaning":"需要……方面的知識","examples":[{"en":"The explanation would require a knowledge of upper-level wind patterns.","zh":"這個解釋需要高空風向模式方面的知識。"},{"en":"To require a knowledge of something means to need understanding of that subject.","zh":"「require a knowledge of」某事，意思是需要對該主題有所理解。"},{"en":"Repairing this machine requires a knowledge of basic electronics.","zh":"修理這部機器需要基本電子學方面的知識。"},{"en":"Reading old maps may require a knowledge of local history.","zh":"閱讀舊地圖可能需要本地歷史方面的知識。"},{"en":"Understanding climate links can require a knowledge of winds, oceans and long-term data.","zh":"理解氣候關聯可能需要風、海洋和長期數據方面的知識。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":13},{"front":"wind patterns","meaning":"風向模式","examples":[{"en":"Walker said wind patterns above ground level would be important.","zh":"Walker 說地面以上的風向模式會很重要。"},{"en":"Wind patterns are the usual directions and movements of air over an area.","zh":"「wind patterns」是某地空氣通常的方向和流動方式。"},{"en":"Pilots study wind patterns before choosing a flight route.","zh":"飛行員在選擇航線前會研究風向模式。"},{"en":"Wind patterns can spread smoke, dust or pollution from one region to another.","zh":"風向模式可以把煙、塵或污染從一個地區帶到另一個地區。"},{"en":"Changes in wind patterns can alter rainfall and ocean temperatures.","zh":"風向模式的變化可以改變降雨和海洋溫度。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":13},{"front":"above ground level","meaning":"地面以上","examples":[{"en":"Wind patterns above ground level were not routinely observed.","zh":"地面以上的風向模式當時並未被常規觀測。"},{"en":"Above ground level means higher than the surface of the earth.","zh":"「above ground level」意思是高於地球表面。"},{"en":"The apartment is twenty metres above ground level, so it has a wide view.","zh":"這個單位位於地面以上二十米，所以視野開闊。"},{"en":"Air temperature above ground level can differ from temperature at the street surface.","zh":"地面以上的氣溫可能與街道路面的溫度不同。"},{"en":"Scientists use balloons to measure winds above ground level.","zh":"科學家使用氣球測量地面以上的風。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":13},{"front":"routinely being observed","meaning":"被常規觀測","examples":[{"en":"Such wind patterns were not routinely being observed at that time.","zh":"這類風向模式在當時並未被常規觀測。"},{"en":"Routinely being observed means being watched or measured regularly as part of normal practice.","zh":"「routinely being observed」意思是作為正常做法被定期觀察或測量。"},{"en":"Patient temperatures are routinely being observed in many hospital wards.","zh":"在許多醫院病房中，病人體溫被常規觀測。"},{"en":"If sea temperatures are not routinely being observed, sudden changes may be missed.","zh":"如果海水溫度沒有被常規觀測，突然變化可能會被錯過。"},{"en":"Data that is routinely being observed gives scientists a stronger basis for comparison.","zh":"被常規觀測的數據為科學家提供更強的比較基礎。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":13},{"front":"long-term time series","meaning":"長期時間序列","examples":[{"en":"Long-term time series are needed to understand El Niño.","zh":"了解厄爾尼諾現象需要長期時間序列。"},{"en":"Long-term time series are data records collected regularly over a long period.","zh":"「long-term time series」是長時間定期收集的數據記錄。"},{"en":"A long-term time series of rainfall helps scientists see whether droughts are becoming more common.","zh":"長期降雨時間序列幫助科學家了解乾旱是否變得更常見。"},{"en":"Without long-term time series, one unusual year may be mistaken for a trend.","zh":"沒有長期時間序列，一個異常年份可能被誤認為趨勢。"},{"en":"Schools can use long-term time series of test results to see whether teaching methods are improving.","zh":"學校可以使用考試結果的長期時間序列，了解教學方法是否改善。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":13},{"front":"baseline data","meaning":"基準數據","examples":[{"en":"Without good baseline data, scientists may misunderstand El Niño’s effects.","zh":"沒有良好的基準數據，科學家可能誤解厄爾尼諾現象的影響。"},{"en":"Baseline data is the starting information used for later comparison.","zh":"「baseline data」是用於日後比較的起始資料。"},{"en":"Doctors collect baseline data before treatment so they can measure improvement.","zh":"醫生在治療前收集基準數據，以便衡量改善。"},{"en":"If a forest has no baseline data, it is hard to know how much damage has occurred.","zh":"如果森林沒有基準數據，就很難知道已發生多少損害。"},{"en":"Baseline data helps researchers separate normal variation from real change.","zh":"基準數據幫助研究人員區分正常波動與真正變化。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":13},{"front":"ornithologists","meaning":"鳥類學家","examples":[{"en":"Ornithologists study birds.","zh":"鳥類學家研究鳥類。"},{"en":"Ornithologists are scientists who study birds, including their behaviour, habitats and populations.","zh":"「ornithologists」是研究鳥類的科學家，包括牠們的行為、棲息地和種群。"},{"en":"Ornithologists may count nests to estimate how many birds are breeding.","zh":"鳥類學家可能計算巢穴，以估計有多少鳥正在繁殖。"},{"en":"When birds disappear from an area, ornithologists look for changes in food, climate or habitat.","zh":"當鳥類從某地消失，鳥類學家會尋找食物、氣候或棲息地的變化。"},{"en":"Ornithologists help conservationists decide which bird species need protection.","zh":"鳥類學家幫助保育人員決定哪些鳥類物種需要保護。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":13},{"front":"doomed to be surprised by","meaning":"注定會被……弄得措手不及","examples":[{"en":"Without baseline data, ornithologists are doomed to be surprised by El Niño.","zh":"沒有基準數據，鳥類學家注定會被厄爾尼諾現象弄得措手不及。"},{"en":"Doomed to be surprised by something means certain to be caught unprepared by it.","zh":"「doomed to be surprised by」某事，意思是必然會被它弄得毫無準備。"},{"en":"Students who never practise listening are doomed to be surprised by fast exam recordings.","zh":"從不練習聆聽的學生，注定會被快速的考試錄音弄得措手不及。"},{"en":"A city that ignores flood maps is doomed to be surprised by heavy rain.","zh":"忽視洪水地圖的城市，注定會被強降雨弄得措手不及。"},{"en":"Scientists without long-term records may be doomed to be surprised by natural cycles.","zh":"沒有長期記錄的科學家，可能注定會被自然週期弄得措手不及。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":13},{"front":"the arrival of El Niño","meaning":"厄爾尼諾現象的到來","examples":[{"en":"Scientists need data before the arrival of El Niño.","zh":"科學家需要在厄爾尼諾現象到來之前取得數據。"},{"en":"The arrival of El Niño means the beginning or appearance of this climate event.","zh":"「the arrival of El Niño」指這種氣候事件的開始或出現。"},{"en":"Before the arrival of El Niño, researchers may set up extra monitoring stations.","zh":"在厄爾尼諾現象到來之前，研究人員可能設立額外監測站。"},{"en":"The arrival of El Niño can change rainfall, sea temperature and food supplies.","zh":"厄爾尼諾現象的到來可以改變降雨、海水溫度和食物供應。"},{"en":"If communities prepare before the arrival of El Niño, they may reduce damage.","zh":"如果社區在厄爾尼諾現象到來之前作準備，就可能減少損害。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":14},{"front":"every few years","meaning":"每隔幾年","examples":[{"en":"El Niño arrives every few years.","zh":"厄爾尼諾現象每隔幾年到來。"},{"en":"Every few years means once after several years, but not every year.","zh":"「every few years」意思是每過幾年一次，但不是每年。"},{"en":"The school updates its computer system every few years.","zh":"學校每隔幾年更新一次電腦系統。"},{"en":"Some families take a long overseas trip every few years.","zh":"有些家庭每隔幾年會去一次長途海外旅行。"},{"en":"If a climate event happens every few years, people need plans that can be used repeatedly.","zh":"如果氣候事件每隔幾年發生，人們需要可以重複使用的計劃。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":14},{"front":"ecologists","meaning":"生態學家","examples":[{"en":"Ecologists study relationships between organisms and their environment.","zh":"生態學家研究生物與其環境之間的關係。"},{"en":"Ecologists are scientists who study how living things interact with each other and their surroundings.","zh":"「ecologists」是研究生物如何彼此互動以及與周圍環境互動的科學家。"},{"en":"Ecologists may study how pollution affects fish, insects and plants in a river.","zh":"生態學家可能研究污染如何影響河中的魚、昆蟲和植物。"},{"en":"When a species declines, ecologists examine food, predators, climate and habitat.","zh":"當某物種下降，生態學家會檢查食物、捕食者、氣候和棲息地。"},{"en":"Ecologists help society understand why protecting one species can protect many others.","zh":"生態學家幫助社會理解，為何保護一個物種可以保護許多其他物種。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":14},{"front":"at hand","meaning":"在場；可用","examples":[{"en":"Even when experts are at hand, missing data creates problems.","zh":"即使專家在場，缺少數據仍會造成問題。"},{"en":"At hand means nearby, available or ready to help.","zh":"「at hand」意思是在附近、可用或準備好幫忙。"},{"en":"Keep your notes at hand during revision so you can check details quickly.","zh":"溫習時把筆記放在手邊，這樣你可以快速核對細節。"},{"en":"When a doctor is at hand, an emergency can be treated sooner.","zh":"當醫生在場，緊急情況可以更快得到處理。"},{"en":"Even with experts at hand, decisions are difficult without reliable evidence.","zh":"即使專家在場，沒有可靠證據也很難作決定。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":14},{"front":"take advantage of","meaning":"利用","examples":[{"en":"Scientists can take advantage of an incoming El Niño to study its effects.","zh":"科學家可以利用即將到來的厄爾尼諾現象來研究其影響。"},{"en":"To take advantage of something means to use an opportunity in a useful way.","zh":"「take advantage of」某事，意思是以有用方式利用機會。"},{"en":"Students can take advantage of free library resources to improve their writing.","zh":"學生可以利用免費圖書館資源來改善寫作。"},{"en":"Farmers take advantage of good weather to harvest crops quickly.","zh":"農民利用好天氣快速收割農作物。"},{"en":"Researchers take advantage of rare events because they may not happen again soon.","zh":"研究人員利用罕見事件，因為它們可能不會很快再次發生。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":14},{"front":"incoming El Niño","meaning":"即將到來的厄爾尼諾現象","examples":[{"en":"An incoming El Niño offers a chance for research.","zh":"即將到來的厄爾尼諾現象提供研究機會。"},{"en":"An incoming El Niño is an El Niño event that is approaching or beginning soon.","zh":"「incoming El Niño」是正在接近或即將開始的厄爾尼諾事件。"},{"en":"Scientists may prepare instruments when an incoming El Niño is detected.","zh":"當偵測到即將到來的厄爾尼諾現象，科學家可能準備儀器。"},{"en":"An incoming El Niño can give farmers warning that rainfall may change.","zh":"即將到來的厄爾尼諾現象可以提醒農民降雨可能改變。"},{"en":"Studying an incoming El Niño is easier when baseline data already exists.","zh":"當已有基準數據時，研究即將到來的厄爾尼諾現象會較容易。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":14},{"front":"lack of preexisting data","meaning":"缺乏已有數據","examples":[{"en":"Lack of preexisting data makes bird responses hard to interpret.","zh":"缺乏已有數據使鳥類反應難以解釋。"},{"en":"Lack of preexisting data means there was not enough information collected before the event.","zh":"「lack of preexisting data」意思是在事件發生前沒有收集足夠資料。"},{"en":"Without preexisting data, a doctor may not know whether a patient’s condition has truly worsened.","zh":"沒有已有數據，醫生可能不知道病人的情況是否真的惡化。"},{"en":"A lack of preexisting data can make it hard to measure damage after a storm.","zh":"缺乏已有數據可能令風暴後的損害難以測量。"},{"en":"Researchers avoid this problem by collecting data before major changes happen.","zh":"研究人員透過在重大變化發生前收集數據來避免這個問題。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":14},{"front":"monitoring afterwards","meaning":"事後監測","examples":[{"en":"Monitoring afterwards is needed to understand long-term effects.","zh":"需要事後監測來了解長期影響。"},{"en":"Monitoring afterwards means continuing to watch or measure something after an event.","zh":"「monitoring afterwards」意思是在事件之後繼續觀察或測量某事物。"},{"en":"After surgery, monitoring afterwards helps doctors notice complications early.","zh":"手術後，事後監測幫助醫生及早注意到併發症。"},{"en":"After a flood, monitoring afterwards shows whether water quality returns to normal.","zh":"洪水後，事後監測顯示水質是否恢復正常。"},{"en":"Monitoring afterwards is important because some effects appear slowly.","zh":"事後監測很重要，因為有些影響會慢慢出現。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":14},{"front":"successive El Niño, La Niña, and normal years","meaning":"連續的厄爾尼諾、拉尼娜和正常年份","examples":[{"en":"Scientists compare successive El Niño, La Niña, and normal years.","zh":"科學家比較連續的厄爾尼諾、拉尼娜和正常年份。"},{"en":"Successive El Niño, La Niña, and normal years are years that follow one another under different climate conditions.","zh":"「successive El Niño, La Niña, and normal years」是指在不同氣候狀況下相繼出現的年份。"},{"en":"Comparing successive El Niño, La Niña and normal years helps scientists separate one-year effects from longer patterns.","zh":"比較連續的厄爾尼諾、拉尼娜和正常年份，有助科學家把單一年份影響與較長期模式分開。"},{"en":"If seabirds behave differently across successive years, climate may be one possible cause.","zh":"如果海鳥在連續年份中的行為不同，氣候可能是其中一個原因。"},{"en":"Long records of successive climate years are more useful than data from one unusual year.","zh":"連續氣候年份的長期記錄，比單一異常年份的數據更有用。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":14},{"front":"according to","meaning":"根據","examples":[{"en":"According to Jaksic, there were 12 El Niño years in the last century.","zh":"根據 Jaksic，上個世紀有十二個厄爾尼諾年份。"},{"en":"According to means as stated by a person, report or source.","zh":"「according to」意思是根據某人、報告或資料來源所說。"},{"en":"According to the teacher, the test will include two writing questions.","zh":"根據老師，測驗會包括兩條寫作題。"},{"en":"According to the weather report, rain will begin tonight.","zh":"根據天氣報告，今晚會開始下雨。"},{"en":"Students should say according to the passage when an answer comes from the text, not from their own opinion.","zh":"當答案來自文章而不是個人意見時，學生應說「根據文章」。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":14},{"front":"during the last century","meaning":"在上一個世紀","examples":[{"en":"During the last century, there were 12 El Niño years and 12 La Niña years.","zh":"在上一個世紀，有十二個厄爾尼諾年份和十二個拉尼娜年份。"},{"en":"During the last century means over the period of the previous one hundred years.","zh":"「during the last century」意思是在之前一百年的期間。"},{"en":"During the last century, many cities grew rapidly.","zh":"在上一個世紀，許多城市迅速增長。"},{"en":"Medical treatment improved greatly during the last century.","zh":"在上一個世紀，醫療大幅改善。"},{"en":"Climate records from during the last century help scientists compare past and present conditions.","zh":"上一個世紀的氣候記錄幫助科學家比較過去和現在的狀況。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":14},{"front":"in between","meaning":"在其間","examples":[{"en":"There were about 76 normal years in between.","zh":"其間大約有七十六個正常年份。"},{"en":"In between means in the middle of two points, events or groups.","zh":"「in between」意思是在兩個點、事件或群體之間。"},{"en":"The school has two exams in June, with a short holiday in between.","zh":"學校六月有兩次考試，其間有一個短假期。"},{"en":"If buses arrive at 8 and 9, there may be no service in between.","zh":"如果巴士在八點和九點到達，其間可能沒有服務。"},{"en":"Scientists count unusual years and then study the normal years in between.","zh":"科學家計算異常年份，然後研究其間的正常年份。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":15},{"front":"concentrating heavily on","meaning":"過度集中於","examples":[{"en":"Scientists may distort the picture by concentrating heavily on El Niño years.","zh":"科學家如果過度集中於厄爾尼諾年份，可能會扭曲整體情況。"},{"en":"Concentrating heavily on something means giving it most of your attention.","zh":"「concentrating heavily on」某事，意思是把大部分注意力放在它上面。"},{"en":"A student concentrating heavily on grammar may forget to develop ideas.","zh":"學生過度集中於文法，可能忘記發展想法。"},{"en":"If news reports concentrate heavily on disasters, people may think nothing good is happening.","zh":"如果新聞報道過度集中於災難，人們可能以為沒有好事發生。"},{"en":"Researchers should avoid concentrating heavily on rare cases while ignoring normal patterns.","zh":"研究人員應避免過度集中於罕見個案，而忽略正常模式。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":15},{"front":"time span","meaning":"時間跨度","examples":[{"en":"El Niño years made up only part of the time span.","zh":"厄爾尼諾年份只佔該時間跨度的一部分。"},{"en":"A time span is the length of time covered by an event, study or record.","zh":"「time span」是事件、研究或記錄涵蓋的時間長度。"},{"en":"The time span of the project was six months.","zh":"該項目的時間跨度是六個月。"},{"en":"A longer time span gives researchers more evidence for judging trends.","zh":"較長的時間跨度給研究人員更多證據來判斷趨勢。"},{"en":"If the time span is too short, one unusual result may seem more important than it really is.","zh":"如果時間跨度太短，一個異常結果可能顯得比實際更重要。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":15},{"front":"neglecting","meaning":"忽略","examples":[{"en":"Researchers should avoid neglecting La Niña years.","zh":"研究人員應避免忽略拉尼娜年份。"},{"en":"Neglecting something means failing to give it enough attention or care.","zh":"「neglecting」某事，意思是沒有給予它足夠注意或照顧。"},{"en":"A student neglecting vocabulary may struggle to understand reading passages.","zh":"忽略詞彙的學生，可能難以理解閱讀文章。"},{"en":"Neglecting small health problems can make them worse later.","zh":"忽略小健康問題，可能令它們日後惡化。"},{"en":"Scientists risk drawing wrong conclusions if they keep neglecting important data.","zh":"如果科學家一直忽略重要數據，就有得出錯誤結論的風險。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":15},{"front":"essentially ignoring","meaning":"實際上忽略","examples":[{"en":"By focusing only on El Niño, researchers are essentially ignoring most years.","zh":"只集中於厄爾尼諾現象，研究人員實際上忽略了大多數年份。"},{"en":"Essentially ignoring means in effect not paying attention to something important.","zh":"「essentially ignoring」意思是實際上沒有注意重要事物。"},{"en":"If a teacher listens only to top students, they are essentially ignoring weaker learners.","zh":"如果老師只聽成績最好的學生，他們實際上忽略了較弱的學習者。"},{"en":"A health plan that discusses exercise but not sleep is essentially ignoring a major factor.","zh":"只討論運動而不討論睡眠的健康計劃，實際上忽略了一個主要因素。"},{"en":"Researchers essentially ignore the full pattern when they study only dramatic cases.","zh":"研究人員只研究戲劇性個案時，實際上忽略了完整模式。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":15},{"front":"can be remedied only by","meaning":"只能通過……補救","examples":[{"en":"This problem can be remedied only by collecting regular data.","zh":"這個問題只能通過收集定期數據來補救。"},{"en":"Can be remedied only by means can be fixed only through one necessary action.","zh":"「can be remedied only by」意思是只能透過某個必要行動來修正。"},{"en":"A lack of sleep can be remedied only by changing the student’s daily routine.","zh":"睡眠不足只能通過改變學生的日常規律來補救。"},{"en":"Poor water quality can be remedied only by stopping pollution at its source.","zh":"水質差只能通過從源頭停止污染來補救。"},{"en":"Weak evidence can be remedied only by collecting better and more regular data.","zh":"證據薄弱只能通過收集更好和更定期的數據來補救。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":15},{"front":"logging data regularly","meaning":"定期記錄數據","examples":[{"en":"Scientists need to keep logging data regularly.","zh":"科學家需要持續定期記錄數據。"},{"en":"Logging data regularly means recording information again and again at set times.","zh":"「logging data regularly」意思是在固定時間一次又一次記錄資訊。"},{"en":"A nurse logs data regularly by writing down a patient’s temperature every few hours.","zh":"護士每隔幾小時記下病人體溫，就是定期記錄數據。"},{"en":"Farmers logging data regularly can see whether crops grow better after certain treatments.","zh":"定期記錄數據的農民，可以看出農作物在某些處理後是否長得更好。"},{"en":"Without logging data regularly, researchers may miss slow but important changes.","zh":"沒有定期記錄數據，研究人員可能錯過緩慢但重要的變化。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":15},{"front":"continuously","meaning":"持續地","examples":[{"en":"Data should be collected regularly or continuously.","zh":"數據應定期或持續地收集。"},{"en":"Continuously means without stopping, or with no major gaps.","zh":"「continuously」意思是不停止地，或沒有重大間斷地。"},{"en":"The machine must run continuously during the safety test.","zh":"在安全測試期間，機器必須持續運行。"},{"en":"A baby’s breathing may be monitored continuously in intensive care.","zh":"在深切治療中，嬰兒的呼吸可能會被持續監測。"},{"en":"Continuously collected data can show changes that short surveys miss.","zh":"持續收集的數據可以顯示短期調查錯過的變化。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":15},{"front":"create long-term time series","meaning":"建立長期時間序列","examples":[{"en":"Regular data collection can create long-term time series.","zh":"定期數據收集可以建立長期時間序列。"},{"en":"To create long-term time series means to build data records over many years through repeated measurement.","zh":"「create long-term time series」意思是透過反覆測量，在多年中建立數據記錄。"},{"en":"A school can create long-term time series by recording exam results every year.","zh":"學校可以透過每年記錄考試結果來建立長期時間序列。"},{"en":"Scientists create long-term time series of sea temperature to detect climate trends.","zh":"科學家建立海水溫度的長期時間序列，以偵測氣候趨勢。"},{"en":"Regular monitoring creates long-term time series that make future research more reliable.","zh":"定期監測建立長期時間序列，使未來研究更可靠。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":15},{"front":"the recipe prescribed by","meaning":"由……提出的方法","examples":[{"en":"The recipe prescribed by Schreiber and Schreiber still stands.","zh":"由 Schreiber 和 Schreiber 提出的方法仍然有效。"},{"en":"The recipe prescribed by someone means the method or advice that person recommended.","zh":"「the recipe prescribed by」某人，意思是該人建議的方法或做法。"},{"en":"The recipe prescribed by the coach was simple: practise daily and rest properly.","zh":"教練提出的方法很簡單：每天練習並適當休息。"},{"en":"The recipe prescribed by health experts may include exercise, sleep and balanced meals.","zh":"健康專家提出的方法可能包括運動、睡眠和均衡飲食。"},{"en":"In research, the recipe prescribed by earlier scientists can guide later studies.","zh":"在研究中，早期科學家提出的方法可以指導後來的研究。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":15},{"front":"still stands","meaning":"仍然有效","examples":[{"en":"The advice to carry out long-term studies still stands.","zh":"進行長期研究的建議仍然有效。"},{"en":"Still stands means remains valid, true or accepted.","zh":"「still stands」意思是仍然有效、真確或被接受。"},{"en":"The teacher’s warning still stands: late homework will lose marks.","zh":"老師的警告仍然有效：遲交功課會扣分。"},{"en":"Even after new evidence, the main conclusion still stands.","zh":"即使有新證據，主要結論仍然有效。"},{"en":"A safety rule still stands until officials clearly replace it.","zh":"安全規則在官方明確取代前仍然有效。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":15},{"front":"carry out long-term studies","meaning":"進行長期研究","examples":[{"en":"Researchers should carry out long-term studies of birds and climate.","zh":"研究人員應進行鳥類和氣候的長期研究。"},{"en":"To carry out long-term studies means to conduct research over many years.","zh":"「carry out long-term studies」意思是多年進行研究。"},{"en":"Doctors carry out long-term studies to see whether a treatment stays effective.","zh":"醫生進行長期研究，以了解治療是否持續有效。"},{"en":"Ecologists carry out long-term studies because ecosystems change slowly.","zh":"生態學家進行長期研究，因為生態系統變化緩慢。"},{"en":"Long-term studies require patience, funding and consistent data collection.","zh":"長期研究需要耐心、資金和一致的數據收集。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":16},{"front":"shed further light on","meaning":"進一步闡明","examples":[{"en":"Long-term studies can shed further light on El Niño’s effects.","zh":"長期研究可以進一步闡明厄爾尼諾現象的影響。"},{"en":"To shed further light on something means to help people understand it better.","zh":"「shed further light on」某事，意思是幫助人們更好理解它。"},{"en":"New interviews may shed further light on why students drop out of school.","zh":"新訪問可能進一步闡明學生退學的原因。"},{"en":"A long medical study can shed further light on the side effects of a drug.","zh":"長期醫學研究可以進一步闡明藥物的副作用。"},{"en":"Better data can shed further light on whether climate change affects seabird breeding.","zh":"更好的數據可以進一步闡明氣候變化是否影響海鳥繁殖。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":16},{"front":"interactions between","meaning":"……之間的相互作用","examples":[{"en":"The studies examine interactions between climate cycles and bird populations.","zh":"這些研究考察氣候週期和鳥類種群之間的相互作用。"},{"en":"Interactions between two things are the ways they affect each other.","zh":"「interactions between」兩件事物，指它們互相影響的方式。"},{"en":"Teachers study interactions between students to understand classroom behaviour.","zh":"老師研究學生之間的相互作用，以了解課堂行為。"},{"en":"Interactions between plants and insects can affect crop growth.","zh":"植物和昆蟲之間的相互作用可以影響農作物生長。"},{"en":"Climate research often focuses on interactions between oceans, winds and living organisms.","zh":"氣候研究常集中於海洋、風和生物之間的相互作用。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":16},{"front":"global atmospheric cycles","meaning":"全球大氣循環","examples":[{"en":"El Niño is linked with global atmospheric cycles.","zh":"厄爾尼諾現象與全球大氣循環有關。"},{"en":"Global atmospheric cycles are repeated patterns of air movement and pressure across the planet.","zh":"「global atmospheric cycles」是全球空氣流動和氣壓的重複模式。"},{"en":"Global atmospheric cycles can influence rain, drought and storm tracks.","zh":"全球大氣循環可以影響降雨、乾旱和風暴路徑。"},{"en":"Scientists study global atmospheric cycles to explain weather links between distant regions.","zh":"科學家研究全球大氣循環，以解釋遙遠地區之間的天氣聯繫。"},{"en":"Changes in global atmospheric cycles may affect agriculture and water supplies worldwide.","zh":"全球大氣循環的變化可能影響全球農業和水供應。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":16},{"front":"oceanographic phenomena","meaning":"海洋學現象","examples":[{"en":"El Niño is an oceanographic phenomenon with wide effects.","zh":"厄爾尼諾現象是一種具有廣泛影響的海洋學現象。"},{"en":"Oceanographic phenomena are events or patterns that happen in the ocean.","zh":"「oceanographic phenomena」是發生在海洋中的事件或模式。"},{"en":"Ocean currents, tides and warming events are oceanographic phenomena.","zh":"洋流、潮汐和變暖事件都是海洋學現象。"},{"en":"Some oceanographic phenomena can change fish movement and coastal weather.","zh":"有些海洋學現象可以改變魚類移動和沿岸天氣。"},{"en":"Scientists study oceanographic phenomena to understand how the sea affects climate and life.","zh":"科學家研究海洋學現象，以理解海洋如何影響氣候和生命。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":16},{"front":"avian populations","meaning":"鳥類種群","examples":[{"en":"Long-term studies can explain changes in avian populations.","zh":"長期研究可以解釋鳥類種群的變化。"},{"en":"Avian populations are groups of birds living in a particular area or belonging to particular species.","zh":"「avian populations」指生活在特定地區或屬於特定物種的鳥類群體。"},{"en":"Habitat loss can reduce avian populations in forests and wetlands.","zh":"棲息地喪失可以減少森林和濕地中的鳥類種群。"},{"en":"Scientists count avian populations each year to see whether conservation is working.","zh":"科學家每年計算鳥類種群，以了解保育是否有效。"},{"en":"Changes in avian populations may reveal wider environmental problems.","zh":"鳥類種群的變化可能揭示更廣泛的環境問題。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":16},{"front":"larger and more diverse than","meaning":"比……更大且更多樣化","examples":[{"en":"Seabird populations in Alaska are larger and more diverse than elsewhere.","zh":"阿拉斯加的海鳥種群比其他地方更大且更多樣化。"},{"en":"Larger and more diverse than means greater in size and containing a wider range of types.","zh":"「larger and more diverse than」意思是規模更大，而且種類範圍更廣。"},{"en":"A university library is usually larger and more diverse than a small classroom bookshelf.","zh":"大學圖書館通常比小課室書架更大且更多樣化。"},{"en":"A coastal ecosystem may be larger and more diverse than a small pond ecosystem.","zh":"沿岸生態系統可能比小池塘生態系統更大且更多樣化。"},{"en":"When a group is larger and more diverse than another, it may offer more information for study.","zh":"當一個群體比另一個更大且更多樣化，它可能為研究提供更多資訊。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":16},{"front":"Northern Hemisphere","meaning":"北半球","examples":[{"en":"Alaska has unusually large seabird populations in the Northern Hemisphere.","zh":"阿拉斯加在北半球擁有異常龐大的海鳥種群。"},{"en":"The Northern Hemisphere is the half of the Earth north of the equator.","zh":"「Northern Hemisphere」是地球赤道以北的一半。"},{"en":"Countries in the Northern Hemisphere usually have winter when the Southern Hemisphere has summer.","zh":"北半球國家通常在南半球夏天時經歷冬天。"},{"en":"Many migratory birds travel across the Northern Hemisphere each year.","zh":"許多候鳥每年橫越北半球遷徙。"},{"en":"Climate changes in the Northern Hemisphere can affect forests, oceans and human societies.","zh":"北半球的氣候變化可以影響森林、海洋和人類社會。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":16},{"front":"extensive coastal estuaries","meaning":"廣闊沿岸河口","examples":[{"en":"Alaska has extensive coastal estuaries.","zh":"阿拉斯加擁有廣闊沿岸河口。"},{"en":"Extensive coastal estuaries are large areas where river water mixes with seawater along the coast.","zh":"「extensive coastal estuaries」是沿岸河水與海水混合的大面積地區。"},{"en":"Extensive coastal estuaries provide feeding grounds for fish, birds and shellfish.","zh":"廣闊沿岸河口為魚類、鳥類和貝類提供覓食地。"},{"en":"Pollution in extensive coastal estuaries can harm both freshwater and marine species.","zh":"廣闊沿岸河口中的污染可以傷害淡水和海洋物種。"},{"en":"Protecting extensive coastal estuaries helps preserve nurseries for young fish.","zh":"保護廣闊沿岸河口，有助保存幼魚的育幼場所。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":16},{"front":"offshore waters","meaning":"近海水域","examples":[{"en":"Offshore waters provide habitat for seabirds.","zh":"近海水域為海鳥提供棲息地。"},{"en":"Offshore waters are areas of sea away from the immediate coastline.","zh":"「offshore waters」是離開直接海岸線一段距離的海域。"},{"en":"Fishing boats often travel into offshore waters to find larger catches.","zh":"漁船常駛入近海水域，以尋找較大漁獲。"},{"en":"Seabirds may feed in offshore waters when fish gather far from land.","zh":"當魚群聚集在遠離陸地的地方，海鳥可能在近海水域覓食。"},{"en":"Oil spills in offshore waters can still damage beaches, birds and marine mammals.","zh":"近海水域的漏油仍可以破壞海灘、鳥類和海洋哺乳動物。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":16},{"front":"breeding, feeding and migrating habitats","meaning":"繁殖、覓食和遷徙棲息地","examples":[{"en":"Alaska provides breeding, feeding and migrating habitats for seabirds.","zh":"阿拉斯加為海鳥提供繁殖、覓食和遷徙棲息地。"},{"en":"Breeding, feeding and migrating habitats are places animals use to reproduce, find food and travel seasonally.","zh":"「breeding, feeding and migrating habitats」是動物用來繁殖、尋找食物和季節性遷徙的地方。"},{"en":"Wetlands can be breeding, feeding and migrating habitats for many birds.","zh":"濕地可以是許多鳥類的繁殖、覓食和遷徙棲息地。"},{"en":"If one of these habitats is damaged, a species may suffer at a different stage of life.","zh":"如果其中一種棲息地受損，物種可能在人生或生命週期的不同階段受害。"},{"en":"Conservation plans must protect breeding, feeding and migrating habitats, not just one nesting site.","zh":"保育計劃必須保護繁殖、覓食和遷徙棲息地，而不只是某一築巢地。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":16},{"front":"at least 38 species","meaning":"至少三十八個物種","examples":[{"en":"At least 38 species of seabirds breed in Alaska.","zh":"至少三十八種海鳥在阿拉斯加繁殖。"},{"en":"At least 38 species means no fewer than thirty-eight different kinds.","zh":"「at least 38 species」意思是不少於三十八個不同種類。"},{"en":"A nature reserve may contain at least 38 species of birds during migration season.","zh":"一個自然保護區在遷徙季節可能有至少三十八種鳥類。"},{"en":"If at least 38 species depend on one area, that area has high conservation value.","zh":"如果至少三十八個物種依賴一個地區，該地具有高保育價值。"},{"en":"The phrase at least 38 species leaves open the possibility that the true number is higher.","zh":"「至少三十八個物種」這個說法保留了真實數字更高的可能性。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":17},{"front":"over 50 million individuals","meaning":"超過五千萬隻個體","examples":[{"en":"Over 50 million seabirds breed in Alaska.","zh":"超過五千萬隻海鳥在阿拉斯加繁殖。"},{"en":"Over 50 million individuals means more than fifty million separate living organisms.","zh":"「over 50 million individuals」意思是超過五千萬個獨立生物個體。"},{"en":"A city with over 50 million public transport journeys a year needs a strong system.","zh":"一個每年有超過五千萬次公共交通旅程的城市，需要強大的系統。"},{"en":"If over 50 million individuals depend on a habitat, even small changes can have large effects.","zh":"如果超過五千萬隻個體依賴某棲息地，即使小變化也可能造成巨大影響。"},{"en":"Large numbers such as over 50 million individuals show why careful counting matters.","zh":"像超過五千萬隻個體這樣的大數字，顯示細心點算為何重要。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":17},{"front":"adjacent Siberia","meaning":"鄰近西伯利亞","examples":[{"en":"Eight Alaskan species breed only in Alaska and adjacent Siberia.","zh":"八種阿拉斯加物種只在阿拉斯加和鄰近西伯利亞繁殖。"},{"en":"Adjacent Siberia means the part of Siberia next to or near Alaska.","zh":"「adjacent Siberia」指靠近或鄰近阿拉斯加的西伯利亞部分。"},{"en":"Birds may move between Alaska and adjacent Siberia during their life cycle.","zh":"鳥類可能在生命週期中於阿拉斯加和鄰近西伯利亞之間移動。"},{"en":"Conservation plans for species in Alaska may need cooperation with adjacent Siberia.","zh":"阿拉斯加物種的保育計劃可能需要與鄰近西伯利亞合作。"},{"en":"The word adjacent shows that the two regions are geographically close.","zh":"「adjacent」這個字顯示兩個地區在地理上接近。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":17},{"front":"additional species","meaning":"另外五個物種","examples":[{"en":"Five additional species range through the North Pacific.","zh":"另外五個物種分布於北太平洋。"},{"en":"Additional species means extra species beyond those already mentioned.","zh":"「additional species」意思是已提及物種以外的額外物種。"},{"en":"The survey found ten common birds and three additional species near the river.","zh":"調查在河邊發現十種常見鳥類和三個另外的物種。"},{"en":"If additional species are discovered, the reserve may be more important than expected.","zh":"如果發現另外的物種，保護區可能比預期更重要。"},{"en":"Scientists list additional species separately when they do not belong to the first group.","zh":"當另外的物種不屬於第一組時，科學家會把它們分開列出。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":17},{"front":"range through","meaning":"分布於","examples":[{"en":"Some species range through the North Pacific.","zh":"有些物種分布於北太平洋。"},{"en":"To range through an area means to live, move or be found across that area.","zh":"「range through」某地，意思是在該地範圍內生活、移動或被發現。"},{"en":"Wolves may range through large forests in search of food.","zh":"狼可能分布並活動於大片森林中尋找食物。"},{"en":"Birds that range through several countries need international protection.","zh":"分布於幾個國家的鳥類需要國際保護。"},{"en":"A species that ranges through the North Pacific may depend on many different feeding areas.","zh":"分布於北太平洋的物種，可能依賴許多不同覓食區。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":17},{"front":"the North Pacific","meaning":"北太平洋","examples":[{"en":"Several seabird species range through the North Pacific.","zh":"幾種海鳥分布於北太平洋。"},{"en":"The North Pacific is the northern part of the Pacific Ocean.","zh":"「北太平洋」是太平洋的北部。"},{"en":"The North Pacific contains important fishing grounds and seabird habitats.","zh":"北太平洋包含重要漁場和海鳥棲息地。"},{"en":"Storms in the North Pacific can affect shipping routes and coastal weather.","zh":"北太平洋的風暴可以影響航運路線和沿岸天氣。"},{"en":"Climate changes in the North Pacific may influence marine food chains.","zh":"北太平洋的氣候變化可能影響海洋食物鏈。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":17},{"front":"concentrated in","meaning":"集中於","examples":[{"en":"Their populations are concentrated in Alaska.","zh":"牠們的種群集中於阿拉斯加。"},{"en":"Concentrated in a place means found mainly there rather than spread evenly everywhere.","zh":"「concentrated in」某地，意思是主要集中在那裡，而不是平均分布在各處。"},{"en":"Many technology companies are concentrated in certain city districts.","zh":"許多科技公司集中於某些城市區域。"},{"en":"If a species is concentrated in one area, damage there can be especially dangerous.","zh":"如果某物種集中於一個地區，該地受損可能特別危險。"},{"en":"Jobs concentrated in the city centre can create heavy commuter traffic.","zh":"工作集中於市中心，可能造成沉重通勤交通。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":17},{"front":"breeding grounds","meaning":"繁殖地","examples":[{"en":"Alaskan waters provide important breeding grounds.","zh":"阿拉斯加水域提供重要繁殖地。"},{"en":"Breeding grounds are places where animals reproduce and raise young.","zh":"「breeding grounds」是動物繁殖和養育幼小個體的地方。"},{"en":"Wetlands are breeding grounds for many frogs, insects and birds.","zh":"濕地是許多青蛙、昆蟲和鳥類的繁殖地。"},{"en":"If breeding grounds are destroyed, adult animals may have nowhere safe to nest.","zh":"如果繁殖地被破壞，成年動物可能沒有安全地方築巢。"},{"en":"Protecting breeding grounds is essential for maintaining future populations.","zh":"保護繁殖地對維持未來種群至關重要。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":17},{"front":"wintering habitat","meaning":"越冬棲息地","examples":[{"en":"Alaskan waters provide wintering habitat for some birds.","zh":"阿拉斯加水域為一些鳥類提供越冬棲息地。"},{"en":"Wintering habitat is the place where animals spend the winter.","zh":"「wintering habitat」是動物度過冬季的地方。"},{"en":"Some migratory birds need warm wintering habitat far from their breeding grounds.","zh":"有些候鳥需要遠離繁殖地的溫暖越冬棲息地。"},{"en":"If wintering habitat is polluted, birds may return weak to their nesting areas.","zh":"如果越冬棲息地受污染，鳥類可能虛弱地返回築巢區。"},{"en":"Conservation must protect both breeding habitat and wintering habitat.","zh":"保育必須同時保護繁殖棲息地和越冬棲息地。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":17},{"front":"breed in Canada and Eurasia","meaning":"在加拿大和歐亞大陸繁殖","examples":[{"en":"Some birds that breed in Canada and Eurasia winter in Alaska.","zh":"一些在加拿大和歐亞大陸繁殖的鳥類在阿拉斯加越冬。"},{"en":"To breed in Canada and Eurasia means to reproduce in those regions.","zh":"「breed in Canada and Eurasia」意思是在這些地區繁殖。"},{"en":"Birds that breed in Canada and Eurasia may travel thousands of kilometres each year.","zh":"在加拿大和歐亞大陸繁殖的鳥類，每年可能遷徙數千公里。"},{"en":"If birds breed in Canada and Eurasia but winter elsewhere, they need safe habitats in both places.","zh":"如果鳥類在加拿大和歐亞大陸繁殖但在其他地方越冬，牠們需要兩地都有安全棲息地。"},{"en":"Migration links birds that breed in Canada and Eurasia with ecosystems across the North Pacific.","zh":"遷徙把在加拿大和歐亞大陸繁殖的鳥類與北太平洋各地生態系統連繫起來。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":17},{"front":"shearwaters","meaning":"剪水鸌","examples":[{"en":"Shearwaters are very numerous in Alaskan waters during summer.","zh":"剪水鸌在夏季的阿拉斯加水域數量非常多。"},{"en":"Shearwaters are seabirds that often glide low over ocean waves.","zh":"剪水鸌是常貼近海浪低飛滑翔的海鳥。"},{"en":"Many shearwaters travel long distances between breeding and feeding areas.","zh":"許多剪水鸌在繁殖區和覓食區之間長距離遷移。"},{"en":"Shearwaters may gather where fish and plankton are abundant.","zh":"剪水鸌可能聚集在魚類和浮游生物豐富的地方。"},{"en":"Scientists observe shearwaters to understand seasonal changes in ocean food supplies.","zh":"科學家觀察剪水鸌，以理解海洋食物供應的季節變化。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":17},{"front":"Southern Hemisphere","meaning":"南半球","examples":[{"en":"Shearwaters breed in the Southern Hemisphere.","zh":"剪水鸌在南半球繁殖。"},{"en":"The Southern Hemisphere is the half of the Earth south of the equator.","zh":"「Southern Hemisphere」是地球赤道以南的一半。"},{"en":"When it is winter in the Northern Hemisphere, it is summer in the Southern Hemisphere.","zh":"當北半球是冬天時，南半球是夏天。"},{"en":"Some birds breed in the Southern Hemisphere and then migrate north to feed.","zh":"有些鳥類在南半球繁殖，然後向北遷徙覓食。"},{"en":"Climate patterns in the Southern Hemisphere can affect oceans, agriculture and wildlife.","zh":"南半球的氣候模式可以影響海洋、農業和野生動物。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":18},{"front":"the most numerous species","meaning":"數量最多的物種","examples":[{"en":"Shearwaters are the most numerous species in Alaskan waters during summer.","zh":"剪水鸌是夏季阿拉斯加水域中數量最多的物種。"},{"en":"The most numerous species is the species with the greatest number of individuals.","zh":"「the most numerous species」指個體數量最多的物種。"},{"en":"In some city parks, pigeons may be the most numerous species of bird.","zh":"在一些城市公園中，鴿子可能是數量最多的鳥類物種。"},{"en":"If the most numerous species suddenly declines, scientists may suspect a serious environmental change.","zh":"如果數量最多的物種突然下降，科學家可能懷疑出現嚴重環境變化。"},{"en":"Being the most numerous species does not mean a species is safe forever.","zh":"成為數量最多的物種，並不代表該物種永遠安全。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":18},{"front":"during the summer","meaning":"在夏季期間","examples":[{"en":"Shearwaters are common in Alaskan waters during the summer.","zh":"剪水鸌在夏季期間常見於阿拉斯加水域。"},{"en":"During the summer means in the summer season.","zh":"「during the summer」意思是在夏季期間。"},{"en":"Many students take part-time jobs during the summer.","zh":"許多學生在夏季期間做兼職。"},{"en":"Beaches become crowded during the summer when the weather is hot.","zh":"夏季期間天氣炎熱時，海灘會變得擠迫。"},{"en":"Some birds travel north during the summer to find rich feeding grounds.","zh":"有些鳥在夏季期間向北遷徙，以尋找豐富覓食地。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":18},{"front":"as another indication that","meaning":"另一個顯示……的跡象","examples":[{"en":"Large-scale die-offs are another indication that food has been limited.","zh":"大規模死亡事件是另一個顯示食物一直受限的跡象。"},{"en":"As another indication that means as one more sign showing that something may be true.","zh":"「as another indication that」意思是作為另一個顯示某事可能真實的跡象。"},{"en":"Empty shelves are another indication that demand has suddenly increased.","zh":"空貨架是另一個顯示需求突然上升的跡象。"},{"en":"Falling test scores are another indication that students need more support.","zh":"考試分數下降是另一個顯示學生需要更多支援的跡象。"},{"en":"Dead seabirds may be another indication that marine food supplies are under pressure.","zh":"死海鳥可能是另一個顯示海洋食物供應受壓的跡象。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":18},{"front":"food has been limiting","meaning":"食物一直受限","examples":[{"en":"Seabird die-offs may indicate that food has been limiting.","zh":"海鳥死亡事件可能顯示食物一直受限。"},{"en":"Food has been limiting means food supply has been too low and has restricted survival or growth.","zh":"「food has been limiting」意思是食物供應一直太少，限制了生存或成長。"},{"en":"If chicks are underweight, it may show that food has been limiting.","zh":"如果雛鳥體重不足，可能顯示食物一直受限。"},{"en":"In a drought, grass may become limiting for animals that graze.","zh":"在乾旱中，草對吃草動物來說可能變得受限。"},{"en":"When food has been limiting for several years, populations may decline slowly.","zh":"當食物多年來一直受限，種群可能緩慢下降。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":18},{"front":"large-scale die-offs","meaning":"大規模死亡事件","examples":[{"en":"Several large-scale die-offs of seabirds have been observed.","zh":"幾次海鳥大規模死亡事件已被觀察到。"},{"en":"Large-scale die-offs are events in which many animals die in a short period or across a wide area.","zh":"「large-scale die-offs」指大量動物在短時間內或大範圍內死亡的事件。"},{"en":"A large-scale die-off of fish may happen when water loses oxygen.","zh":"當水中失去氧氣，可能發生魚類大規模死亡事件。"},{"en":"Large-scale die-offs warn scientists that something serious may be wrong in the environment.","zh":"大規模死亡事件警告科學家環境中可能出現嚴重問題。"},{"en":"After large-scale die-offs, researchers collect bodies and water samples to find the cause.","zh":"大規模死亡事件後，研究人員會收集屍體和水樣以尋找原因。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":18},{"front":"mostly surface-feeding species","meaning":"主要為表層覓食物種","examples":[{"en":"The die-offs mostly affected surface-feeding species.","zh":"這些死亡事件主要影響表層覓食物種。"},{"en":"Mostly surface-feeding species means mainly animals that take food from the water surface or near it.","zh":"「mostly surface-feeding species」指主要從水面或近水面處取食的動物。"},{"en":"Mostly surface-feeding species may suffer first when prey sinks deeper.","zh":"當獵物下沉到更深處，主要為表層覓食物種可能最先受影響。"},{"en":"If a die-off affects mostly surface-feeding species, scientists may examine changes near the water surface.","zh":"如果死亡事件主要影響表層覓食物種，科學家可能檢查水面附近的變化。"},{"en":"Comparing diving birds with mostly surface-feeding species can reveal where food shortages occurred.","zh":"把潛水鳥與主要為表層覓食物種比較，可以揭示食物短缺發生的位置。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":18},{"front":"observed in","meaning":"在……被觀察到","examples":[{"en":"Large-scale seabird die-offs were observed in the Gulf of Alaska.","zh":"大規模海鳥死亡事件在阿拉斯加灣被觀察到。"},{"en":"Observed in means seen, recorded or noticed in a particular place or group.","zh":"「observed in」意思是在某個地方或群體中被看見、記錄或注意到。"},{"en":"A rise in flu cases was observed in several schools.","zh":"幾所學校中觀察到流感個案上升。"},{"en":"Strange behaviour was observed in the animals after the storm.","zh":"風暴後，動物身上觀察到奇怪行為。"},{"en":"If a pattern is observed in many places, scientists take it more seriously.","zh":"如果某模式在許多地方被觀察到，科學家會更認真看待。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":18},{"front":"during the last decade","meaning":"在過去十年","examples":[{"en":"Several die-offs occurred during the last decade.","zh":"幾次死亡事件發生在過去十年。"},{"en":"During the last decade means over the past ten years.","zh":"「during the last decade」意思是在過去十年期間。"},{"en":"During the last decade, online learning became much more common.","zh":"在過去十年，網上學習變得普遍得多。"},{"en":"Many cities built new railway lines during the last decade.","zh":"許多城市在過去十年興建了新鐵路線。"},{"en":"Environmental records from during the last decade can reveal recent changes.","zh":"過去十年的環境記錄可以揭示近期變化。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":18},{"front":"most notably","meaning":"最明顯的是","examples":[{"en":"Die-offs occurred most notably in 1983, 1989 and 1993.","zh":"死亡事件發生在幾個年份，最明顯的是1983年、1989年和1993年。"},{"en":"Most notably means most importantly or most clearly among the examples.","zh":"「most notably」意思是在例子中最重要或最明顯的是。"},{"en":"Several students improved, most notably those who practised every day.","zh":"幾名學生都有進步，最明顯的是每天練習的學生。"},{"en":"The town changed in many ways, most notably through the new railway station.","zh":"該鎮在很多方面改變，最明顯的是新鐵路站。"},{"en":"Seabird deaths were recorded in several years, most notably during years with unusual ocean conditions.","zh":"幾個年份都記錄到海鳥死亡，最明顯的是海洋狀況異常的年份。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":18},{"front":"too early to decide whether","meaning":"現在判斷……是否……為時過早","examples":[{"en":"Hatch thinks it is too early to decide whether the die-offs are linked to El Niño.","zh":"Hatch 認為現在判斷這些死亡事件是否與厄爾尼諾現象有關為時過早。"},{"en":"Too early to decide whether means there is not yet enough evidence to make a judgement.","zh":"「too early to decide whether」意思是還沒有足夠證據作出判斷。"},{"en":"It is too early to decide whether the new teaching method will improve exam results.","zh":"現在判斷新教學方法是否會改善考試成績為時過早。"},{"en":"Doctors said it was too early to decide whether the treatment had worked.","zh":"醫生說現在判斷治療是否有效為時過早。"},{"en":"Scientists should say it is too early to decide whether two events are linked when data is limited.","zh":"當數據有限時，科學家應說現在判斷兩件事是否有關為時過早。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":18},{"front":"reports of these die-offs","meaning":"這些死亡事件的報告","examples":[{"en":"Reports of these die-offs may or may not be linked to El Niño.","zh":"這些死亡事件的報告可能與厄爾尼諾現象有關，也可能無關。"},{"en":"Reports of these die-offs are written or spoken records describing these mass death events.","zh":"「reports of these die-offs」是描述這些大規模死亡事件的書面或口頭記錄。"},{"en":"Reports of these die-offs help scientists know when and where many animals died.","zh":"這些死亡事件的報告幫助科學家知道許多動物何時何地死亡。"},{"en":"If reports of these die-offs are incomplete, the cause may be hard to identify.","zh":"如果這些死亡事件的報告不完整，原因可能難以確認。"},{"en":"Researchers compare reports of these die-offs with weather and ocean data.","zh":"研究人員把這些死亡事件的報告與天氣和海洋數據比較。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":19},{"front":"connected with","meaning":"與……有關","examples":[{"en":"Scientists are unsure whether the die-offs are connected with El Niño.","zh":"科學家不確定這些死亡事件是否與厄爾尼諾現象有關。"},{"en":"Connected with means related to or associated with something.","zh":"「connected with」意思是與某事相關或有關。"},{"en":"Poor concentration may be connected with lack of sleep.","zh":"專注力差可能與睡眠不足有關。"},{"en":"A rise in food prices can be connected with drought or transport problems.","zh":"食物價格上升可能與乾旱或運輸問題有關。"},{"en":"Researchers need evidence before saying one event is connected with another.","zh":"研究人員在說一件事與另一件事有關前，需要證據。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":19},{"front":"the effects of El Niño","meaning":"厄爾尼諾現象的影響","examples":[{"en":"The effects of El Niño on seabirds remain difficult to confirm.","zh":"厄爾尼諾現象對海鳥的影響仍然難以確認。"},{"en":"The effects of El Niño are the changes or results caused by this climate event.","zh":"「the effects of El Niño」是由這種氣候事件造成的變化或結果。"},{"en":"The effects of El Niño may include drought, heavy rain or warmer seas in different regions.","zh":"厄爾尼諾現象的影響可能包括不同地區的乾旱、強降雨或較溫暖海水。"},{"en":"Farmers study the effects of El Niño to prepare for unusual weather.","zh":"農民研究厄爾尼諾現象的影響，以為異常天氣作準備。"},{"en":"Scientists need long-term data to separate the effects of El Niño from normal variation.","zh":"科學家需要長期數據，以把厄爾尼諾現象的影響與正常波動分開。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":19},{"front":"high rainfall","meaning":"高降雨量","examples":[{"en":"High rainfall may affect chick survival in burrows.","zh":"高降雨量可能影響洞穴中雛鳥的存活。"},{"en":"High rainfall means a large amount of rain over a period.","zh":"「high rainfall」指某段時間內大量降雨。"},{"en":"High rainfall can flood roads, homes and underground nests.","zh":"高降雨量可以淹沒道路、房屋和地下巢穴。"},{"en":"Farmers may welcome high rainfall after drought, but too much can damage crops.","zh":"乾旱後，農民可能歡迎高降雨量，但過多雨水會破壞農作物。"},{"en":"High rainfall during breeding season can be dangerous for birds nesting in soil.","zh":"繁殖季節期間的高降雨量，可能對在泥土中築巢的鳥類有危險。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":19},{"front":"affect survival of chicks","meaning":"影響雛鳥存活","examples":[{"en":"Heavy rain can affect survival of chicks.","zh":"大雨可以影響雛鳥存活。"},{"en":"To affect survival of chicks means to influence whether young birds live or die.","zh":"「affect survival of chicks」意思是影響幼鳥能否活下來。"},{"en":"Cold weather can affect survival of chicks if parents cannot keep them warm.","zh":"如果親鳥不能讓雛鳥保持溫暖，寒冷天氣可以影響雛鳥存活。"},{"en":"Lack of food affects survival of chicks because they need frequent feeding.","zh":"食物不足影響雛鳥存活，因為牠們需要頻繁餵食。"},{"en":"Scientists study storms, food and predators to understand what affects survival of chicks.","zh":"科學家研究風暴、食物和捕食者，以理解什麼會影響雛鳥存活。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":19},{"front":"earthen burrows","meaning":"泥土洞穴","examples":[{"en":"Some chicks live in earthen burrows.","zh":"有些雛鳥住在泥土洞穴中。"},{"en":"Earthen burrows are holes or tunnels dug in soil rather than rock or wood.","zh":"「earthen burrows」是在泥土中挖出的洞或通道，而不是在岩石或木頭中。"},{"en":"Rabbits often shelter in earthen burrows to stay hidden and warm.","zh":"兔子常躲在泥土洞穴中，以保持隱蔽和溫暖。"},{"en":"Heavy rain can collapse earthen burrows and trap animals inside.","zh":"大雨可以令泥土洞穴倒塌，並把動物困在裡面。"},{"en":"Birds that nest in earthen burrows need dry, stable ground.","zh":"在泥土洞穴中築巢的鳥類需要乾燥、穩定的地面。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":19},{"front":"occurrence of major storms","meaning":"大型風暴的出現","examples":[{"en":"The occurrence of major storms can endanger chicks.","zh":"大型風暴的出現可能危及雛鳥。"},{"en":"The occurrence of major storms means the happening of strong and serious storms.","zh":"「occurrence of major storms」意思是強烈而嚴重的風暴發生。"},{"en":"The occurrence of major storms during exam week can disrupt transport and school schedules.","zh":"考試週期間大型風暴的出現，可能擾亂交通和學校時間表。"},{"en":"The occurrence of major storms near the coast may damage nests and fishing boats.","zh":"沿岸附近大型風暴的出現，可能破壞巢穴和漁船。"},{"en":"Scientists record the occurrence of major storms to understand their effects on wildlife.","zh":"科學家記錄大型風暴的出現，以理解其對野生動物的影響。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":19},{"front":"high winds","meaning":"強風","examples":[{"en":"Major storms with high winds may kill chicks.","zh":"伴隨強風的大型風暴可能殺死雛鳥。"},{"en":"High winds are very strong winds that can move or damage objects.","zh":"「high winds」是可以移動或破壞物件的非常強烈的風。"},{"en":"High winds can knock down trees and delay flights.","zh":"強風可以吹倒樹木並延誤航班。"},{"en":"Birds nesting on cliffs may lose eggs during high winds.","zh":"在懸崖築巢的鳥類可能在強風期間失去鳥蛋。"},{"en":"People should secure loose objects before high winds arrive.","zh":"強風到來前，人們應固定鬆散物件。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":19},{"front":"chick-rearing period","meaning":"育雛期","examples":[{"en":"Storms during the chick-rearing period can be dangerous.","zh":"育雛期期間的風暴可能很危險。"},{"en":"The chick-rearing period is the time when parent birds feed and care for their chicks.","zh":"「chick-rearing period」是親鳥餵養和照顧雛鳥的時期。"},{"en":"During the chick-rearing period, adult birds need enough food for themselves and their young.","zh":"在育雛期期間，成年鳥需要足夠食物給自己和幼鳥。"},{"en":"Bad weather in the chick-rearing period may reduce the number of chicks that survive.","zh":"育雛期中的惡劣天氣可能減少存活雛鳥數量。"},{"en":"Scientists often monitor nests closely during the chick-rearing period.","zh":"科學家常在育雛期密切監測巢穴。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":19},{"front":"nest on cliff ledges","meaning":"在懸崖岩架上築巢","examples":[{"en":"Some seabirds nest on cliff ledges.","zh":"有些海鳥在懸崖岩架上築巢。"},{"en":"To nest on cliff ledges means to build nests on narrow flat parts of steep cliffs.","zh":"「nest on cliff ledges」意思是在陡峭懸崖上的狹窄平坦位置築巢。"},{"en":"Birds nest on cliff ledges to stay away from many land predators.","zh":"鳥類在懸崖岩架上築巢，以遠離許多陸地捕食者。"},{"en":"Strong winds can make it dangerous for chicks that nest on cliff ledges.","zh":"強風可能令在懸崖岩架上築巢的雛鳥處境危險。"},{"en":"Researchers need ropes and safety equipment to study birds that nest on cliff ledges.","zh":"研究在懸崖岩架上築巢的鳥類時，研究人員需要繩索和安全裝備。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":19},{"front":"kill chicks","meaning":"殺死雛鳥","examples":[{"en":"Storms can kill chicks of cliff-nesting species.","zh":"風暴可以殺死在懸崖築巢物種的雛鳥。"},{"en":"To kill chicks means to cause young birds to die.","zh":"「kill chicks」意思是導致幼鳥死亡。"},{"en":"Cold rain can kill chicks if they become wet and cannot stay warm.","zh":"如果雛鳥濕透而無法保暖，寒冷雨水可以殺死雛鳥。"},{"en":"Predators may kill chicks when nests are left unprotected.","zh":"當巢穴無人保護時，捕食者可能殺死雛鳥。"},{"en":"Conservation work tries to reduce dangers that kill chicks during breeding season.","zh":"保育工作試圖減少繁殖季節中會殺死雛鳥的危險。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":19},{"front":"considered convincing evidence","meaning":"被視為有說服力的證據","examples":[{"en":"This view has not been considered convincing evidence.","zh":"這個看法未被視為有說服力的證據。"},{"en":"Considered convincing evidence means judged to be strong enough to support a claim.","zh":"「considered convincing evidence」意思是被判斷為足夠有力去支持某個說法。"},{"en":"One photograph may not be considered convincing evidence if it can be easily misunderstood.","zh":"如果一張照片很容易被誤解，它可能不會被視為有說服力的證據。"},{"en":"Repeated measurements are often considered convincing evidence in scientific studies.","zh":"在科學研究中，重複測量常被視為有說服力的證據。"},{"en":"A claim should not be accepted until the evidence is considered convincing.","zh":"在證據被視為有說服力之前，不應接受某個說法。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":20},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Students choose the correct letter for each question.","zh":"學生為每條問題選出正確字母。"},{"en":"To choose the correct letter means to select the answer option marked by the right letter.","zh":"「choose the correct letter」意思是選擇由正確字母標示的答案選項。"},{"en":"In a multiple-choice test, students must choose the correct letter after reading all options.","zh":"在多項選擇題中，學生必須閱讀所有選項後選出正確字母。"},{"en":"If students choose the correct letter without understanding the text, they may only be guessing.","zh":"如果學生沒有理解文章就選出正確字母，他們可能只是猜測。"},{"en":"Careful reading helps students choose the correct letter more accurately.","zh":"仔細閱讀幫助學生更準確地選出正確字母。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":20},{"front":"investigate El Niño","meaning":"研究厄爾尼諾現象","examples":[{"en":"Scientists investigate El Niño to understand climate disruption.","zh":"科學家研究厄爾尼諾現象，以理解氣候擾亂。"},{"en":"To investigate El Niño means to study this climate event carefully to find causes and effects.","zh":"「investigate El Niño」意思是仔細研究這種氣候事件，以找出原因和影響。"},{"en":"Researchers investigate El Niño by measuring sea temperature, winds and rainfall.","zh":"研究人員透過測量海水溫度、風和降雨來研究厄爾尼諾現象。"},{"en":"Farmers benefit when scientists investigate El Niño because better forecasts help them prepare.","zh":"科學家研究厄爾尼諾現象時，農民會受益，因為更好的預報能幫助他們準備。"},{"en":"Investigating El Niño requires long-term data, not just observations from one year.","zh":"研究厄爾尼諾現象需要長期數據，而不只是某一年的觀察。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":20},{"front":"behaviour of creatures","meaning":"生物行為","examples":[{"en":"The option refers to the behaviour of creatures in marine environments.","zh":"該選項指海洋環境中的生物行為。"},{"en":"Behaviour of creatures means the ways animals act, move, feed, breed or respond to conditions.","zh":"「behaviour of creatures」指動物行動、移動、覓食、繁殖或回應環境的方式。"},{"en":"Students can observe the behaviour of creatures in a pond by watching frogs and insects.","zh":"學生可以透過觀察池塘中的青蛙和昆蟲來觀察生物行為。"},{"en":"Climate change may alter the behaviour of creatures when food or temperature changes.","zh":"當食物或溫度改變，氣候變化可能改變生物行為。"},{"en":"Understanding the behaviour of creatures helps scientists protect habitats more effectively.","zh":"理解生物行為幫助科學家更有效保護棲息地。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":20},{"front":"marine environments","meaning":"海洋環境","examples":[{"en":"Seabirds live and feed in marine environments.","zh":"海鳥在海洋環境中生活和覓食。"},{"en":"Marine environments are places in or near the sea where marine life exists.","zh":"「marine environments」是海中或海邊有海洋生命存在的地方。"},{"en":"Coral reefs, sandy coasts and open oceans are marine environments.","zh":"珊瑚礁、沙岸和開放海洋都是海洋環境。"},{"en":"Plastic pollution in marine environments can harm turtles, fish and seabirds.","zh":"海洋環境中的塑膠污染可以傷害海龜、魚類和海鳥。"},{"en":"Students studying marine environments learn how water, animals and climate interact.","zh":"研究海洋環境的學生會學到水、動物和氣候如何互動。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":20},{"front":"normal cycles","meaning":"正常週期","examples":[{"en":"El Niño disrupts normal cycles for wildlife and humans.","zh":"厄爾尼諾現象擾亂野生動物和人類的正常週期。"},{"en":"Normal cycles are regular patterns that repeat over time.","zh":"「normal cycles」是隨時間重複出現的規律模式。"},{"en":"Sleep and waking are normal cycles in daily life.","zh":"睡眠和清醒是日常生活中的正常週期。"},{"en":"If normal cycles of rain and dry weather change, farmers may struggle.","zh":"如果雨季和旱季的正常週期改變，農民可能會吃力。"},{"en":"Scientists compare unusual events with normal cycles to see what has been disrupted.","zh":"科學家把異常事件與正常週期比較，以了解什麼被擾亂。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":20},{"front":"wildlife and humans","meaning":"野生動物和人類","examples":[{"en":"Climate disruptions affect wildlife and humans.","zh":"氣候擾亂影響野生動物和人類。"},{"en":"Wildlife and humans means wild animals and people together.","zh":"「wildlife and humans」意思是野生動物和人類一起。"},{"en":"Clean rivers benefit both wildlife and humans.","zh":"清潔河流有益於野生動物和人類。"},{"en":"Drought can harm wildlife and humans by reducing water and food.","zh":"乾旱會透過減少水和食物傷害野生動物和人類。"},{"en":"Good environmental policy considers the needs of wildlife and humans at the same time.","zh":"良好環境政策同時考慮野生動物和人類的需要。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":20},{"front":"profound theoretical and practical implications","meaning":"深遠的理論和實際影響","examples":[{"en":"The option refers to profound theoretical and practical implications.","zh":"該選項指深遠的理論和實際影響。"},{"en":"Profound theoretical and practical implications are deep effects on both ideas and real-world action.","zh":"「profound theoretical and practical implications」指對思想理解和現實行動都有深遠影響。"},{"en":"A discovery about climate links can have profound theoretical and practical implications for science and farming.","zh":"關於氣候關聯的發現，可能對科學和農業有深遠的理論和實際影響。"},{"en":"New medical research may have profound theoretical and practical implications if it changes both understanding and treatment.","zh":"如果新的醫學研究改變理解和治療，它可能有深遠的理論和實際影響。"},{"en":"When a finding has profound implications, it matters beyond one small case.","zh":"當某發現具有深遠影響，它的重要性就超越一個小個案。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":20},{"front":"primarily affects","meaning":"主要影響","examples":[{"en":"The option asks whether El Niño primarily affects the tropical Pacific Ocean.","zh":"該選項問厄爾尼諾現象是否主要影響熱帶太平洋。"},{"en":"Primarily affects means mainly influences or has the strongest effect on something.","zh":"「primarily affects」意思是主要影響，或對某事物有最強影響。"},{"en":"Lack of sleep primarily affects concentration, but it can also affect mood.","zh":"睡眠不足主要影響專注力，但也可以影響心情。"},{"en":"A transport strike primarily affects commuters who rely on trains.","zh":"交通罷工主要影響依賴火車的通勤者。"},{"en":"Scientists ask what El Niño primarily affects before studying its wider consequences.","zh":"科學家在研究厄爾尼諾現象更廣泛後果前，會先問它主要影響什麼。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":20},{"front":"important subjects","meaning":"重要研究對象","examples":[{"en":"Scientists use seabirds as important subjects in climate research.","zh":"科學家把海鳥作為氣候研究的重要研究對象。"},{"en":"Important subjects are people, animals or topics that are useful to study.","zh":"「important subjects」是值得研究的人、動物或主題。"},{"en":"Children are important subjects in education research because policies affect them directly.","zh":"兒童是教育研究的重要研究對象，因為政策直接影響他們。"},{"en":"Seabirds are important subjects because their breeding success can show changes in the ocean.","zh":"海鳥是重要研究對象，因為牠們的繁殖成功率可以顯示海洋變化。"},{"en":"Choosing important subjects helps researchers answer meaningful questions.","zh":"選擇重要研究對象幫助研究人員回答有意義的問題。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":20},{"front":"observing climate change worldwide","meaning":"觀察全球氣候變化","examples":[{"en":"Seabirds can help scientists observe climate change worldwide.","zh":"海鳥可以幫助科學家觀察全球氣候變化。"},{"en":"Observing climate change worldwide means watching and measuring climate effects across the whole planet.","zh":"「observing climate change worldwide」意思是在全球範圍觀察和測量氣候影響。"},{"en":"Satellites help researchers observe climate change worldwide by tracking ice, forests and sea temperature.","zh":"衛星透過追蹤冰、森林和海水溫度，幫助研究人員觀察全球氣候變化。"},{"en":"Long-term bird records can help with observing climate change worldwide.","zh":"長期鳥類記錄可以有助觀察全球氣候變化。"},{"en":"Observing climate change worldwide is necessary because climate systems are connected across regions.","zh":"觀察全球氣候變化是必要的，因為氣候系統跨地區相互連結。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":20},{"front":"changes in response to","meaning":"因應……而改變","examples":[{"en":"Prey changes in response to temperature and sea-ice conditions.","zh":"獵物會因應溫度和海冰狀況而改變。"},{"en":"Changes in response to something are changes that happen because of that situation.","zh":"「changes in response to」某事，指因那種情況而發生的改變。"},{"en":"Students may make changes in response to feedback from a teacher.","zh":"學生可能因應老師的回饋而作出改變。"},{"en":"Shops make changes in response to customer complaints.","zh":"商店會因應顧客投訴而作出改變。"},{"en":"Animal behaviour changes in response to food supply, weather and danger.","zh":"動物行為會因應食物供應、天氣和危險而改變。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":21},{"front":"sea-ice conditions","meaning":"海冰狀況","examples":[{"en":"Sea-ice conditions can affect seabird food supplies.","zh":"海冰狀況可以影響海鳥食物供應。"},{"en":"Sea-ice conditions are the amount, thickness and seasonal behaviour of ice on the sea.","zh":"「sea-ice conditions」是海上冰的數量、厚度和季節性變化。"},{"en":"Poor sea-ice conditions can make hunting difficult for animals that depend on ice.","zh":"差劣海冰狀況可能令依賴冰的動物難以覓食。"},{"en":"Scientists monitor sea-ice conditions to understand changes in polar ecosystems.","zh":"科學家監測海冰狀況，以理解極地生態系統的變化。"},{"en":"When sea-ice conditions change, fish and plankton may also change.","zh":"當海冰狀況改變，魚類和浮游生物也可能改變。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":21},{"front":"large enough to be observed","meaning":"大得足以被觀察","examples":[{"en":"The option suggests that seabird populations are large enough to be observed.","zh":"該選項暗示海鳥種群大得足以被觀察。"},{"en":"Large enough to be observed means big or visible enough for people to notice or measure.","zh":"「large enough to be observed」意思是大到或明顯到人們可以注意或測量。"},{"en":"The change in water colour was large enough to be observed from the shore.","zh":"水色變化大得足以從岸邊被觀察到。"},{"en":"A class improvement must be large enough to be observed before teachers can trust it.","zh":"班級進步必須大得足以被觀察，老師才可以信任它。"},{"en":"Seabird colonies are often large enough to be observed from boats or cliffs.","zh":"海鳥群落通常大得足以從船上或懸崖上被觀察。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":21},{"front":"more than other marine creatures","meaning":"比其他海洋生物更多","examples":[{"en":"The option compares seabirds with other marine creatures.","zh":"該選項把海鳥與其他海洋生物作比較。"},{"en":"More than other marine creatures means to a greater degree than other animals living in the sea.","zh":"「more than other marine creatures」意思是程度上超過其他生活在海中的動物。"},{"en":"Some seabirds may be easier to observe more than other marine creatures because they nest on land.","zh":"有些海鳥可能比其他海洋生物更容易被觀察，因為牠們在陸地上築巢。"},{"en":"Scientists should not claim seabirds are affected more than other marine creatures without evidence.","zh":"沒有證據時，科學家不應聲稱海鳥比其他海洋生物受影響更多。"},{"en":"Comparing seabirds with other marine creatures can show which animals are most sensitive to change.","zh":"把海鳥與其他海洋生物比較，可以顯示哪些動物對變化最敏感。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":21},{"front":"the region most affected by","meaning":"最受……影響的地區","examples":[{"en":"The option asks whether North America is the region most affected by El Niño.","zh":"該選項問北美是否是最受厄爾尼諾現象影響的地區。"},{"en":"The region most affected by something is the area that experiences the strongest impact.","zh":"「the region most affected by」某事，指受到最強影響的地區。"},{"en":"The region most affected by flooding may need emergency shelters first.","zh":"最受洪水影響的地區可能最先需要緊急庇護所。"},{"en":"If a disease spreads unevenly, doctors identify the region most affected by it.","zh":"如果疾病不均勻地傳播，醫生會找出最受影響的地區。"},{"en":"Scientists need data before naming the region most affected by a climate event.","zh":"科學家在命名最受某氣候事件影響的地區前，需要數據。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":21},{"front":"marine mammals living on","meaning":"生活在……的海洋哺乳動物","examples":[{"en":"The question asks about marine mammals living on Tugidak Island.","zh":"問題問及生活在 Tugidak 島的海洋哺乳動物。"},{"en":"Marine mammals living on a place are sea mammals that use that place for resting, breeding or raising young.","zh":"「marine mammals living on」某地，指使用該地休息、繁殖或養育幼崽的海洋哺乳動物。"},{"en":"Marine mammals living on rocky beaches may be disturbed by tourists.","zh":"生活在岩石海灘上的海洋哺乳動物，可能受到遊客干擾。"},{"en":"Scientists count marine mammals living on islands to track population changes.","zh":"科學家計算生活在島上的海洋哺乳動物，以追蹤種群變化。"},{"en":"If food decreases nearby, marine mammals living on an island may produce fewer young.","zh":"如果附近食物減少，生活在島上的海洋哺乳動物可能產下較少幼崽。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":21},{"front":"during the late twentieth century","meaning":"在二十世紀後期","examples":[{"en":"Harbor seals declined during the late twentieth century.","zh":"港海豹在二十世紀後期數量下降。"},{"en":"During the late twentieth century means in the later part of the 1900s.","zh":"「during the late twentieth century」意思是在1900年代較後期。"},{"en":"Many countries expanded computer use during the late twentieth century.","zh":"許多國家在二十世紀後期擴大電腦使用。"},{"en":"Environmental awareness increased during the late twentieth century.","zh":"環境意識在二十世紀後期提高。"},{"en":"Records from during the late twentieth century help scientists compare past and present wildlife numbers.","zh":"二十世紀後期的記錄幫助科學家比較過去和現在的野生動物數量。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":21},{"front":"numbers declined while","meaning":"數量下降而……","examples":[{"en":"The option contrasts declining sea-lion numbers with harbor-seal numbers.","zh":"該選項把海獅數量下降與港海豹數量作對比。"},{"en":"Numbers declined while means one group’s numbers fell at the same time another situation was happening.","zh":"「numbers declined while」意思是某群體數量下降，同時另一種情況正在發生。"},{"en":"Sales numbers declined while rent continued to rise.","zh":"銷售數量下降，而租金繼續上升。"},{"en":"Student numbers declined while online courses became more popular.","zh":"學生人數下降，而網上課程變得更受歡迎。"},{"en":"If animal numbers declined while food also decreased, scientists may look for a connection.","zh":"如果動物數量下降，而食物也減少，科學家可能尋找兩者關聯。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":21},{"front":"birth rates","meaning":"出生率","examples":[{"en":"Birth rates declined among Steller sea lions.","zh":"北海獅的出生率下降。"},{"en":"Birth rates are the numbers of babies or young animals born in a population over a period.","zh":"「birth rates」是某段期間內一個群體出生的嬰兒或幼小動物數量。"},{"en":"Low birth rates can make a human population age over time.","zh":"低出生率可能令人口隨時間老化。"},{"en":"In wildlife studies, birth rates help scientists predict whether a population can recover.","zh":"在野生動物研究中，出生率幫助科學家預測種群能否恢復。"},{"en":"Food shortage may reduce birth rates because adults are less healthy.","zh":"食物短缺可能降低出生率，因為成年個體較不健康。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":21},{"front":"overall population","meaning":"整體種群","examples":[{"en":"The overall population of Steller sea lions declined.","zh":"北海獅的整體種群下降。"},{"en":"Overall population means the total number of individuals in a group.","zh":"「overall population」指一個群體中的總個體數。"},{"en":"The overall population of a town can rise even if some neighbourhoods lose residents.","zh":"即使有些社區居民減少，一個城鎮的整體人口仍可能上升。"},{"en":"Scientists examine overall population together with age structure and birth rates.","zh":"科學家會把整體種群與年齡結構和出生率一起檢查。"},{"en":"If the overall population falls for many years, conservation action may be needed.","zh":"如果整體種群多年下降，可能需要保育行動。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":21},{"front":"less serious than expected","meaning":"比預期不嚴重","examples":[{"en":"The option asks whether the situation was less serious than expected.","zh":"該選項問情況是否比預期不嚴重。"},{"en":"Less serious than expected means not as bad or dangerous as people thought it would be.","zh":"「less serious than expected」意思是沒有像人們原本以為那樣糟糕或危險。"},{"en":"The storm was less serious than expected, so schools reopened the next day.","zh":"風暴比預期不嚴重，所以學校第二天重開。"},{"en":"A patient’s injury may be less serious than expected after medical tests.","zh":"經醫學檢查後，病人的傷勢可能比預期不嚴重。"},{"en":"Even if a decline is less serious than expected, researchers should still monitor it.","zh":"即使下降比預期不嚴重，研究人員仍應監測。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":21},{"front":"according to Walker","meaning":"根據 Walker 的說法","examples":[{"en":"According to Walker, some monsoon seasons are marked by drought.","zh":"根據 Walker 的說法，有些季風季節以乾旱為特徵。"},{"en":"According to Walker means based on what Walker said, wrote or believed.","zh":"「according to Walker」意思是根據 Walker 所說、所寫或所相信的內容。"},{"en":"According to Walker, distant weather patterns may be connected.","zh":"根據 Walker 的說法，遙遠地區的天氣模式可能有關聯。"},{"en":"Students use according to Walker when they report his idea rather than their own view.","zh":"當學生報告 Walker 的想法而不是自己的看法時，會使用「according to Walker」。"},{"en":"According to Walker, more knowledge of upper-level winds would help explain the pattern.","zh":"根據 Walker 的說法，更多高空風方面的知識將有助解釋該模式。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":22},{"front":"during certain monsoon seasons","meaning":"在某些季風季節期間","examples":[{"en":"Drought occurs in some places during certain monsoon seasons.","zh":"在某些季風季節期間，一些地方會發生乾旱。"},{"en":"During certain monsoon seasons means in some particular monsoon periods, not all of them.","zh":"「during certain monsoon seasons」意思是在某些特定季風時期，而不是全部。"},{"en":"During certain monsoon seasons, farmers may receive too little rain for rice crops.","zh":"在某些季風季節期間，農民可能收到太少雨水，無法種植稻米。"},{"en":"Flooding may happen during certain monsoon seasons when rain is unusually heavy.","zh":"當降雨異常強烈時，洪水可能在某些季風季節期間發生。"},{"en":"Scientists compare rainfall during certain monsoon seasons with long-term averages.","zh":"科學家把某些季風季節期間的降雨與長期平均值比較。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":22},{"front":"floods and droughts","meaning":"洪水和乾旱","examples":[{"en":"The option refers to floods and droughts causing widespread damage.","zh":"該選項指洪水和乾旱造成廣泛破壞。"},{"en":"Floods and droughts are opposite water problems: too much water in one case and too little in the other.","zh":"「floods and droughts」是相反的水問題：一種是水太多，另一種是水太少。"},{"en":"Floods and droughts can both damage crops and homes.","zh":"洪水和乾旱都可以破壞農作物和房屋。"},{"en":"Climate disruption may make floods and droughts more difficult to predict.","zh":"氣候擾亂可能令洪水和乾旱更難預測。"},{"en":"Communities need different plans for floods and droughts because the dangers are different.","zh":"社區需要為洪水和乾旱制定不同計劃，因為危險不同。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":22},{"front":"severe damage","meaning":"嚴重破壞","examples":[{"en":"Extreme weather can cause severe damage.","zh":"極端天氣可以造成嚴重破壞。"},{"en":"Severe damage means very serious harm to people, buildings, crops or the environment.","zh":"「severe damage」指對人、建築、農作物或環境造成非常嚴重的傷害。"},{"en":"A strong earthquake can cause severe damage to roads and homes.","zh":"強烈地震可以對道路和房屋造成嚴重破壞。"},{"en":"Severe damage to crops may lead to food shortages.","zh":"農作物受到嚴重破壞，可能導致食物短缺。"},{"en":"Insurance helps families recover after severe damage, but prevention is still better.","zh":"保險幫助家庭在嚴重破壞後恢復，但預防仍然更好。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":22},{"front":"almost everywhere on the planet","meaning":"地球上幾乎所有地方","examples":[{"en":"The option suggests that damage occurs almost everywhere on the planet.","zh":"該選項暗示破壞發生在地球上幾乎所有地方。"},{"en":"Almost everywhere on the planet means in nearly all parts of the Earth.","zh":"「almost everywhere on the planet」意思是在地球上近乎所有地方。"},{"en":"Mobile phones are used almost everywhere on the planet, though access still differs.","zh":"手機在地球上幾乎所有地方都有使用，雖然取得方式仍有差異。"},{"en":"Climate change is discussed almost everywhere on the planet because its effects cross borders.","zh":"氣候變化在地球上幾乎所有地方被討論，因為其影響跨越國界。"},{"en":"It is a strong claim to say something happens almost everywhere on the planet.","zh":"說某事發生在地球上幾乎所有地方，是一個很強的說法。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":22},{"front":"quickly comes true","meaning":"很快成真","examples":[{"en":"The option says that Walker’s prediction quickly comes true.","zh":"該選項說 Walker 的預測很快成真。"},{"en":"Quickly comes true means becomes real or is proved correct soon after being predicted.","zh":"「quickly comes true」意思是在被預測後很快變成現實或被證明正確。"},{"en":"The warning quickly comes true when heavy rain floods the road within an hour.","zh":"當大雨在一小時內淹沒道路，警告很快成真。"},{"en":"A student’s fear quickly comes true if they skip revision and fail the quiz.","zh":"如果學生不溫習而測驗不合格，他們的擔心很快成真。"},{"en":"Not every scientific prediction quickly comes true; some require years of evidence.","zh":"不是每個科學預測都會很快成真；有些需要多年證據。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":22},{"front":"affects only","meaning":"只影響","examples":[{"en":"The option asks whether drought affects only parts of Africa.","zh":"該選項問乾旱是否只影響非洲部分地區。"},{"en":"Affects only means influences just one group, place or thing and not others.","zh":"「affects only」意思是只影響某一群體、地方或事物，而不影響其他。"},{"en":"The rule affects only new students, not those already enrolled.","zh":"該規則只影響新學生，不影響已入學的學生。"},{"en":"A power cut may affect only one building if the problem is local.","zh":"如果問題是本地性的，停電可能只影響一棟建築。"},{"en":"Be careful with affects only because it makes a narrow and strong claim.","zh":"使用「affects only」時要小心，因為它是一個狹窄而強烈的說法。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":22},{"front":"places such as","meaning":"例如……的地方","examples":[{"en":"Drought affects places such as Australia and Indonesia.","zh":"乾旱影響例如澳洲和印尼的地方。"},{"en":"Places such as introduces examples of locations, not a complete list.","zh":"「places such as」用來引出地點例子，而不是完整清單。"},{"en":"Students visit places such as museums and libraries to learn outside school.","zh":"學生到博物館和圖書館等地方，在校外學習。"},{"en":"Heatwaves can affect places such as cities, farms and coastal towns.","zh":"熱浪可以影響城市、農場和沿岸城鎮等地方。"},{"en":"When a passage says places such as, other similar places may also be included.","zh":"當文章說「places such as」時，其他類似地方也可能包括在內。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":22},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"Students decide whether the following statements agree with the passage.","zh":"學生判斷以下陳述是否與文章一致。"},{"en":"Do the following statements agree with means check whether the statements match the information given.","zh":"「do the following statements agree with」意思是檢查陳述是否符合所給資料。"},{"en":"In a reading test, students ask whether the following statements agree with the writer’s claims.","zh":"在閱讀測驗中，學生會判斷以下陳述是否與作者說法一致。"},{"en":"If a statement adds information not in the text, it may not agree with the passage.","zh":"如果陳述加入文章沒有的資料，它可能不與文章一致。"},{"en":"This instruction reminds students to compare each statement carefully with the source.","zh":"這條指示提醒學生仔細把每個陳述與來源比較。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":22},{"front":"information given in","meaning":"……中提供的資料","examples":[{"en":"The answers must match the information given in the passage.","zh":"答案必須符合文章中提供的資料。"},{"en":"Information given in a text means the facts or details directly provided there.","zh":"「information given in」文本中，意思是當中直接提供的事實或細節。"},{"en":"Students should answer according to the information given in the chart, not their own guesses.","zh":"學生應根據圖表中提供的資料回答，而不是憑自己猜測。"},{"en":"If information given in the article is limited, the correct answer may be Not Given.","zh":"如果文章中提供的資料有限，正確答案可能是 Not Given。"},{"en":"Careful readers separate information given in the text from outside knowledge.","zh":"細心讀者會把文本中提供的資料與外部知識分開。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":22},{"front":"if the statement agrees with","meaning":"如果陳述與……一致","examples":[{"en":"Students write TRUE if the statement agrees with the information.","zh":"如果陳述與資料一致，學生寫 TRUE。"},{"en":"If the statement agrees with means if it matches what the text says.","zh":"「if the statement agrees with」意思是如果該陳述符合文本所說。"},{"en":"Write TRUE if the statement agrees with the passage exactly.","zh":"如果陳述與文章完全一致，就寫 TRUE。"},{"en":"If the statement agrees with only part of the text but adds a false idea, it is not fully correct.","zh":"如果陳述只與文本一部分一致，但加入錯誤想法，它就不是完全正確。"},{"en":"Students must check whether the statement agrees with the information, not whether it sounds reasonable.","zh":"學生必須檢查陳述是否與資料一致，而不是它聽起來是否合理。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":22},{"front":"if the statement contradicts","meaning":"如果陳述與……矛盾","examples":[{"en":"Students write FALSE if the statement contradicts the information.","zh":"如果陳述與資料矛盾，學生寫 FALSE。"},{"en":"If the statement contradicts means if it says the opposite of what the text says.","zh":"「if the statement contradicts」意思是如果陳述說出與文本相反的內容。"},{"en":"Write FALSE if the statement contradicts a clear fact in the passage.","zh":"如果陳述與文章中的清楚事實矛盾，就寫 FALSE。"},{"en":"If a statement contradicts the data in a table, students should not choose TRUE.","zh":"如果某陳述與表格數據矛盾，學生不應選 TRUE。"},{"en":"Contradicting the text is different from adding information that the text does not mention.","zh":"與文本矛盾，不同於加入文本沒有提及的資料。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":23},{"front":"no information on this","meaning":"沒有這方面的資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有這方面的資料，學生寫 NOT GIVEN。"},{"en":"No information on this means the text does not say anything clear about that point.","zh":"「no information on this」意思是文本沒有清楚說明這一點。"},{"en":"If a passage gives no information on the writer’s age, students should not guess it.","zh":"如果文章沒有提供作者年齡方面的資料，學生不應猜測。"},{"en":"A statement may seem likely, but if there is no information on this, the answer is Not Given.","zh":"某陳述可能看似合理，但如果沒有這方面的資料，答案就是 Not Given。"},{"en":"Good reading requires noticing when there is no information on this, not forcing an answer.","zh":"良好閱讀需要注意何時沒有這方面的資料，而不是強行作答。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":23},{"front":"regarded as valuable indicators","meaning":"被視為有價值的指標","examples":[{"en":"Seabirds are regarded as valuable indicators of marine change.","zh":"海鳥被視為海洋變化的有價值指標。"},{"en":"Regarded as valuable indicators means considered useful signs that show a condition or change.","zh":"「regarded as valuable indicators」意思是被認為是顯示某種狀況或變化的有用跡象。"},{"en":"Frog populations are regarded as valuable indicators of water quality.","zh":"青蛙種群被視為水質的有價值指標。"},{"en":"Exam results can be regarded as valuable indicators of learning, but not the only ones.","zh":"考試成績可以被視為學習的有價值指標，但不是唯一指標。"},{"en":"Seabirds are regarded as valuable indicators because their feeding success reflects ocean conditions.","zh":"海鳥被視為有價值的指標，因為牠們的覓食成功率反映海洋狀況。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":23},{"front":"changes in the marine environment","meaning":"海洋環境的變化","examples":[{"en":"Seabirds help measure changes in the marine environment.","zh":"海鳥幫助測量海洋環境的變化。"},{"en":"Changes in the marine environment are alterations in ocean temperature, food supply, ice, pollution or habitats.","zh":"「changes in the marine environment」是海洋溫度、食物供應、冰、污染或棲息地方面的改變。"},{"en":"Fish movement can reveal changes in the marine environment.","zh":"魚類移動可以揭示海洋環境的變化。"},{"en":"Pollution creates changes in the marine environment that may harm birds and mammals.","zh":"污染造成海洋環境的變化，可能傷害鳥類和哺乳動物。"},{"en":"Long-term monitoring helps scientists understand changes in the marine environment.","zh":"長期監測幫助科學家理解海洋環境的變化。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":23},{"front":"feed in different ways","meaning":"以不同方式覓食","examples":[{"en":"Fulmars and murres feed in different ways.","zh":"管鼻鸌和海鴉以不同方式覓食。"},{"en":"Feed in different ways means obtain food by using different methods.","zh":"「feed in different ways」意思是用不同方法取得食物。"},{"en":"Ducks and hawks feed in different ways because one searches water and the other hunts from the air.","zh":"鴨子和鷹以不同方式覓食，因為一種在水中尋找食物，另一種從空中捕獵。"},{"en":"Animals that feed in different ways may respond differently when food moves deeper or farther away.","zh":"以不同方式覓食的動物，在食物移到更深或更遠處時，可能有不同反應。"},{"en":"Comparing species that feed in different ways helps scientists understand ecological roles.","zh":"比較以不同方式覓食的物種，有助科學家理解生態角色。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":23},{"front":"according to the nature of","meaning":"根據……的性質","examples":[{"en":"The option refers to feeding according to the nature of prey.","zh":"該選項指根據獵物性質覓食。"},{"en":"According to the nature of something means depending on its basic features or qualities.","zh":"「according to the nature of」某事，意思是根據它的基本特徵或性質。"},{"en":"Doctors choose treatment according to the nature of the illness.","zh":"醫生根據疾病的性質選擇治療。"},{"en":"Birds may hunt according to the nature of their prey, such as whether it swims or flies.","zh":"鳥類可能根據獵物的性質捕獵，例如牠是游泳還是飛行。"},{"en":"Students should choose examples according to the nature of the word they are learning.","zh":"學生應根據正在學習的字詞性質選擇例句。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":23},{"front":"lower birth rates","meaning":"較低出生率","examples":[{"en":"Steller sea lions showed lower birth rates and other problems.","zh":"北海獅顯示出較低出生率和其他問題。"},{"en":"Lower birth rates mean fewer babies or young animals are born than before.","zh":"「lower birth rates」意思是比以前出生的嬰兒或幼小動物更少。"},{"en":"Lower birth rates can lead to an ageing population.","zh":"較低出生率可能導致人口老化。"},{"en":"In wildlife, lower birth rates may show that adult animals are under stress.","zh":"在野生動物中，較低出生率可能顯示成年動物正承受壓力。"},{"en":"If lower birth rates continue for many years, the population may decline.","zh":"如果較低出生率持續多年，種群可能下降。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":23},{"front":"the overall population was unaffected","meaning":"整體種群未受影響","examples":[{"en":"The statement claims that the overall population was unaffected.","zh":"該陳述聲稱整體種群未受影響。"},{"en":"The overall population was unaffected means the total number of individuals did not change.","zh":"「the overall population was unaffected」意思是總個體數沒有改變。"},{"en":"If births fell but deaths also fell, the overall population might be unaffected for a short time.","zh":"如果出生減少但死亡也減少，整體種群可能短時間內未受影響。"},{"en":"A small local decline does not mean the overall population was unaffected or affected; more data is needed.","zh":"小範圍下降不代表整體種群未受影響或受影響；需要更多數據。"},{"en":"In reading tests, check whether the text really says the overall population was unaffected.","zh":"在閱讀測驗中，要檢查文章是否真的說整體種群未受影響。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":23},{"front":"in replying to","meaning":"在回應……時","examples":[{"en":"In replying to his colleague, Walker discussed wind patterns.","zh":"在回應他的同事時，Walker 討論了風向模式。"},{"en":"In replying to someone means when giving an answer or response to that person.","zh":"「in replying to」某人，意思是在給那個人答案或回應時。"},{"en":"In replying to the customer, the manager apologised and offered a solution.","zh":"在回應顧客時，經理道歉並提出解決方法。"},{"en":"In replying to criticism, a writer should explain evidence clearly.","zh":"在回應批評時，作者應清楚解釋證據。"},{"en":"Walker used his reply to defend the idea that distant climates could be linked.","zh":"Walker 利用他的回應來捍衛遙遠氣候可能有關聯的想法。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":23},{"front":"insufficient data and monitoring","meaning":"數據和監測不足","examples":[{"en":"Insufficient data and monitoring make El Niño difficult to study.","zh":"數據和監測不足使厄爾尼諾現象難以研究。"},{"en":"Insufficient data and monitoring means there is not enough information and not enough regular observation.","zh":"「insufficient data and monitoring」意思是沒有足夠資料，也沒有足夠定期觀察。"},{"en":"Doctors may make weaker decisions when there is insufficient data and monitoring.","zh":"當數據和監測不足，醫生可能作出較弱的決定。"},{"en":"Insufficient data and monitoring can hide slow changes in a forest or ocean.","zh":"數據和監測不足可能隱藏森林或海洋中的緩慢變化。"},{"en":"Long-term studies reduce the problem of insufficient data and monitoring.","zh":"長期研究可以減少數據和監測不足的問題。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":23},{"front":"similar in size and diversity to","meaning":"在規模和多樣性上與……相似","examples":[{"en":"The statement compares seabird populations in Alaska with those elsewhere.","zh":"該陳述把阿拉斯加的海鳥種群與其他地方的海鳥種群作比較。"},{"en":"Similar in size and diversity to means about the same in number and range of types as something else.","zh":"「similar in size and diversity to」意思是在數量和種類範圍上與另一事物大致相同。"},{"en":"This school is similar in size and diversity to the one across town.","zh":"這所學校在規模和多樣性上與城另一邊的學校相似。"},{"en":"A wetland may be similar in size and diversity to another, but still have different species.","zh":"一片濕地可能在規模和多樣性上與另一片相似，但仍有不同物種。"},{"en":"Students must check evidence before saying two populations are similar in size and diversity.","zh":"學生在說兩個種群在規模和多樣性上相似前，必須檢查證據。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":23},{"front":"elsewhere in the Northern Hemisphere","meaning":"北半球其他地方","examples":[{"en":"Alaska’s seabird populations differ from those elsewhere in the Northern Hemisphere.","zh":"阿拉斯加的海鳥種群不同於北半球其他地方的海鳥種群。"},{"en":"Elsewhere in the Northern Hemisphere means in other places north of the equator.","zh":"「elsewhere in the Northern Hemisphere」意思是在赤道以北的其他地方。"},{"en":"Weather in Alaska may differ from weather elsewhere in the Northern Hemisphere.","zh":"阿拉斯加的天氣可能與北半球其他地方的天氣不同。"},{"en":"Birds found elsewhere in the Northern Hemisphere may still migrate through Alaska.","zh":"見於北半球其他地方的鳥類仍可能遷徙經過阿拉斯加。"},{"en":"Comparing Alaska with elsewhere in the Northern Hemisphere helps show what is unusual about it.","zh":"把阿拉斯加與北半球其他地方比較，有助顯示它有何異常之處。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":24},{"front":"accepted as convincing evidence","meaning":"被接受為有說服力的證據","examples":[{"en":"The view has not been accepted as convincing evidence.","zh":"這個看法未被接受為有說服力的證據。"},{"en":"Accepted as convincing evidence means judged by others to be strong enough to prove a point.","zh":"「accepted as convincing evidence」意思是被他人判斷為足夠有力去證明某一點。"},{"en":"A single story is rarely accepted as convincing evidence in scientific research.","zh":"在科學研究中，單一故事很少被接受為有說服力的證據。"},{"en":"Repeated results from different studies are more likely to be accepted as convincing evidence.","zh":"來自不同研究的重複結果更可能被接受為有說服力的證據。"},{"en":"A claim may sound reasonable but still not be accepted as convincing evidence.","zh":"某個說法可能聽起來合理，但仍不被接受為有說服力的證據。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":24},{"front":"chick mortality","meaning":"雛鳥死亡","examples":[{"en":"Heavy rain and storms may cause chick mortality.","zh":"大雨和風暴可能造成雛鳥死亡。"},{"en":"Chick mortality means the death of young birds.","zh":"「chick mortality」意思是幼鳥死亡。"},{"en":"Chick mortality may increase when nests are flooded or parents cannot find food.","zh":"當巢穴被淹或親鳥找不到食物時，雛鳥死亡可能增加。"},{"en":"Scientists record chick mortality to understand whether a breeding season was successful.","zh":"科學家記錄雛鳥死亡，以了解繁殖季節是否成功。"},{"en":"Reducing chick mortality is important for helping bird populations recover.","zh":"減少雛鳥死亡對幫助鳥類種群恢復很重要。"}],"source":"161 - Elnino and Seabirds.pdf","sourcePage":24}],"ielts/reading/passage-2/Practice 162":[{"front":"Is Aid Hurting Africa?","meaning":"援助是否正在傷害非洲？","examples":[{"en":"The passage asks whether aid is hurting Africa.","zh":"文章問援助是否正在傷害非洲。"},{"en":"“Is Aid Hurting Africa?” asks if foreign help may be causing damage instead of solving problems.","zh":"「援助是否正在傷害非洲？」是在問外來幫助是否可能造成傷害，而不是解決問題。"},{"en":"A student might ask, “Is too much help hurting my progress?” if a tutor gives every answer.","zh":"如果補習老師給出每個答案，學生可能會問：「太多幫助是否正在傷害我的進步？」"},{"en":"Aid may hurt a country if it weakens local business or encourages dependence.","zh":"如果援助削弱本地生意或鼓勵依賴，它可能會傷害一個國家。"},{"en":"The question is not whether kindness is bad, but whether a certain kind of aid creates harmful results.","zh":"這個問題不是問善意是否不好，而是問某種援助是否會造成有害結果。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":1},{"front":"despite","meaning":"儘管","examples":[{"en":"Despite its population and resources, Africa remains poor.","zh":"儘管非洲有人口和資源，它仍然貧窮。"},{"en":"“Despite” means something is true even though another fact might suggest the opposite.","zh":"“Despite” 表示即使另一個事實可能暗示相反情況，某事仍然成立。"},{"en":"Despite studying hard, the student failed because he misunderstood the question.","zh":"儘管那名學生努力溫習，他仍因誤解題目而不合格。"},{"en":"Despite heavy rain, the buses continued running on time.","zh":"儘管下大雨，巴士仍然準時行駛。"},{"en":"We use “despite” to show contrast between expectation and reality.","zh":"我們用 “despite” 來表示預期與現實之間的對比。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":1},{"front":"population of more than","meaning":"超過……的人口","examples":[{"en":"Africa has a population of more than one billion.","zh":"非洲有超過十億人口。"},{"en":"A population of more than one billion means there are over one billion people living in a place.","zh":"“A population of more than one billion” 指一個地方有超過十億人居住。"},{"en":"A city with a population of more than ten million needs a strong transport system.","zh":"一個人口超過一千萬的城市需要強大的交通系統。"},{"en":"If a country has a population of more than 100 million, small policy changes can affect many people.","zh":"如果一個國家人口超過一億，細小的政策改變也可能影響很多人。"},{"en":"The phrase is useful when giving a large population figure approximately.","zh":"這個短語在大約說明龐大人口數字時很有用。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":1},{"front":"rich land and natural resources","meaning":"肥沃土地和天然資源","examples":[{"en":"Africa has rich land and natural resources.","zh":"非洲擁有肥沃土地和天然資源。"},{"en":"Rich land and natural resources are valuable soil, minerals, water, forests, oil, or other materials found in nature.","zh":"肥沃土地和天然資源是指有價值的土壤、礦物、水、森林、石油或其他自然物料。"},{"en":"A country with rich land and natural resources may grow food and sell minerals.","zh":"一個擁有肥沃土地和天然資源的國家可以種植食物並出售礦物。"},{"en":"Rich land and natural resources do not guarantee wealth if roads, education, and government are weak.","zh":"如果道路、教育和政府薄弱，肥沃土地和天然資源不一定保證財富。"},{"en":"Farmers depend on rich land, while factories may depend on natural resources such as metal and fuel.","zh":"農民依靠肥沃土地，而工廠可能依靠金屬和燃料等天然資源。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":1},{"front":"continent of Africa","meaning":"非洲大陸","examples":[{"en":"The continent of Africa remains poor despite its resources.","zh":"儘管非洲大陸擁有資源，它仍然貧窮。"},{"en":"The continent of Africa refers to Africa as one of the world’s major land masses.","zh":"“The continent of Africa” 指非洲作為世界主要大陸之一。"},{"en":"The continent of Africa includes many countries with different languages, climates, and histories.","zh":"非洲大陸包括許多擁有不同語言、氣候和歷史的國家。"},{"en":"When writers discuss the continent of Africa, they should not forget its internal diversity.","zh":"當作者討論非洲大陸時，不應忘記其內部多樣性。"},{"en":"Saying “the continent of Africa” is broader than naming one African country.","zh":"說「非洲大陸」比只提及某一個非洲國家更廣泛。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":1},{"front":"remain poor","meaning":"仍然貧窮","examples":[{"en":"The continent of Africa remains poor.","zh":"非洲大陸仍然貧窮。"},{"en":"To remain poor means to continue being poor over time.","zh":"“Remain poor” 指長時間繼續處於貧窮狀態。"},{"en":"A family may remain poor if wages are low and living costs keep rising.","zh":"如果工資低而生活成本持續上升，一個家庭可能仍然貧窮。"},{"en":"A region may remain poor when schools, hospitals, and roads are not improved.","zh":"當學校、醫院和道路沒有改善，一個地區可能仍然貧窮。"},{"en":"The phrase suggests that poverty has not changed, even after many years.","zh":"這個短語暗示即使多年過去，貧窮情況仍未改變。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":1},{"front":"combined economy","meaning":"合併經濟規模","examples":[{"en":"The combined economy of Africa’s 54 states equals that of the Netherlands.","zh":"非洲54個國家的合併經濟規模相當於荷蘭。"},{"en":"A combined economy is the total economic size of several places counted together.","zh":"“Combined economy” 指把幾個地方加起來計算的整體經濟規模。"},{"en":"The combined economy of three small towns may still be smaller than that of one large city.","zh":"三個小鎮的合併經濟規模可能仍小於一個大城市。"},{"en":"Economists use combined economy figures to compare groups of countries with single countries.","zh":"經濟學家使用合併經濟規模數字，把國家群體與單一國家作比較。"},{"en":"This phrase helps show the total strength of many economies as one figure.","zh":"這個短語有助用一個數字展示多個經濟體的總體力量。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":1},{"front":"equal that of","meaning":"相當於……的","examples":[{"en":"Africa’s combined economy equals that of one European country.","zh":"非洲的合併經濟規模相當於一個歐洲國家的經濟規模。"},{"en":"“Equal that of” means to be the same as the amount, level, or size of something already mentioned.","zh":"“Equal that of” 指數量、水平或規模與前面提到的事物相同。"},{"en":"Her monthly rent equals that of her friend’s salary.","zh":"她每月的租金相當於她朋友的薪金。"},{"en":"The cost of repairing the old car may equal that of buying a newer one.","zh":"維修舊車的費用可能相當於購買較新車的費用。"},{"en":"The phrase avoids repeating the noun after “that”.","zh":"這個短語可以避免在 “that” 後重複名詞。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":1},{"front":"speak of something as a unit","meaning":"把……視為一個整體來談論","examples":[{"en":"It is difficult to speak of Africa as a unit.","zh":"很難把非洲視為一個整體來談論。"},{"en":"To speak of something as a unit means to discuss many different parts as if they were one whole thing.","zh":"“Speak of something as a unit” 指把許多不同部分當成一個整體來討論。"},{"en":"It is not always fair to speak of all teenagers as a unit, because they have different interests.","zh":"把所有青少年視為一個整體來談論並不一定公平，因為他們有不同興趣。"},{"en":"A teacher may speak of a class as a unit when describing its average results.","zh":"老師描述平均成績時，可能會把一班學生視為一個整體來談論。"},{"en":"This phrase is useful when warning that a group contains important differences.","zh":"這個短語在提醒某個群體內部有重要差異時很有用。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":1},{"front":"differ from each other in","meaning":"在……方面彼此不同","examples":[{"en":"African states differ from each other in culture, climate and political system.","zh":"非洲國家在文化、氣候和政治制度方面彼此不同。"},{"en":"To differ from each other in something means to be different in that area.","zh":"“Differ from each other in” 指在某方面彼此有差異。"},{"en":"Schools differ from each other in rules, teaching styles, and facilities.","zh":"學校在規則、教學風格和設施方面彼此不同。"},{"en":"Two jobs may differ from each other in salary, pressure, and promotion chances.","zh":"兩份工作可能在薪金、壓力和晉升機會方面彼此不同。"},{"en":"This phrase is useful for comparing several things without saying one is better.","zh":"這個短語適合用來比較幾件事物，而不表示哪一個較好。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":1},{"front":"political system","meaning":"政治制度","examples":[{"en":"African states differ in political system.","zh":"非洲國家在政治制度方面不同。"},{"en":"A political system is the way a country is governed and how power is organised.","zh":"政治制度是一個國家的管治方式以及權力如何組織。"},{"en":"A political system may include elections, courts, parties, and government departments.","zh":"政治制度可能包括選舉、法院、政黨和政府部門。"},{"en":"If a political system is unstable, businesses may be afraid to invest.","zh":"如果政治制度不穩定，企業可能害怕投資。"},{"en":"Learning about a country’s political system helps explain how decisions are made.","zh":"了解一個國家的政治制度有助解釋決策如何作出。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":1},{"front":"gain independence","meaning":"取得獨立","examples":[{"en":"Many African states gained independence in the mid-twentieth century.","zh":"許多非洲國家在二十世紀中期取得獨立。"},{"en":"To gain independence means to become free from control by another country or authority.","zh":"“Gain independence” 指擺脫另一個國家或權力的控制。"},{"en":"A colony may gain independence after years of political struggle.","zh":"一個殖民地可能在多年政治鬥爭後取得獨立。"},{"en":"A young adult may gain independence by earning money and making personal decisions.","zh":"年輕成年人可以透過賺錢和作個人決定來取得獨立。"},{"en":"In history, this phrase often refers to a country beginning to govern itself.","zh":"在歷史中，這個短語常指一個國家開始自我管治。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":2},{"front":"mid-twentieth century","meaning":"二十世紀中期","examples":[{"en":"Many African states gained independence in the mid-twentieth century.","zh":"許多非洲國家在二十世紀中期取得獨立。"},{"en":"The mid-twentieth century means the middle part of the 1900s, especially around the 1940s to 1960s.","zh":"“The mid-twentieth century” 指1900年代的中段，尤其約1940年代至1960年代。"},{"en":"Many social changes took place in the mid-twentieth century.","zh":"許多社會變化在二十世紀中期發生。"},{"en":"Buildings from the mid-twentieth century often show the design style of that period.","zh":"二十世紀中期的建築常展現那個時期的設計風格。"},{"en":"This phrase is used when an exact year is not necessary.","zh":"當不需要精確年份時，可以使用這個短語。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":2},{"front":"pursue economic policies","meaning":"推行經濟政策","examples":[{"en":"Many African states have pursued different economic policies.","zh":"許多非洲國家推行了不同經濟政策。"},{"en":"To pursue economic policies means to choose and follow plans for managing money, trade, jobs, and growth.","zh":"“Pursue economic policies” 指選擇並實行管理金錢、貿易、就業和增長的計劃。"},{"en":"A government may pursue economic policies that support small businesses.","zh":"政府可能推行支持小型企業的經濟政策。"},{"en":"If leaders pursue poor economic policies, prices may rise and jobs may disappear.","zh":"如果領袖推行糟糕的經濟政策，物價可能上升，就業機會可能消失。"},{"en":"The phrase focuses on long-term government choices, not one single decision.","zh":"這個短語強調長期政府選擇，而不是單一決定。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":2},{"front":"overcome poverty","meaning":"克服貧窮","examples":[{"en":"None of the states has overcome poverty.","zh":"這些國家沒有一個克服貧窮。"},{"en":"To overcome poverty means to reduce or escape poverty successfully.","zh":"“Overcome poverty” 指成功減少或擺脫貧窮。"},{"en":"A family may overcome poverty when adults find stable work and children receive education.","zh":"當成年人找到穩定工作，孩子接受教育，一個家庭可能克服貧窮。"},{"en":"Countries can overcome poverty by improving schools, healthcare, roads, and job opportunities.","zh":"國家可以透過改善學校、醫療、道路和就業機會來克服貧窮。"},{"en":"The phrase suggests a serious problem has been beaten or greatly reduced.","zh":"這個短語暗示一個嚴重問題已被戰勝或大大減少。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":2},{"front":"one theory says","meaning":"有一種理論認為","examples":[{"en":"One theory says Africa is unlucky.","zh":"有一種理論認為非洲不幸。"},{"en":"“One theory says” introduces one possible explanation, not a proven fact.","zh":"“One theory says” 是提出一種可能解釋，而不是已證實的事實。"},{"en":"One theory says children learn better when they connect new words to stories.","zh":"有一種理論認為，孩子把新詞與故事連繫起來時學得更好。"},{"en":"One theory says high housing prices push young people to delay marriage.","zh":"有一種理論認為，高樓價令年輕人延遲結婚。"},{"en":"This phrase is useful when presenting an idea that others may disagree with.","zh":"這個短語適合用來提出別人可能不同意的想法。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":2},{"front":"sparsely populated","meaning":"人口稀疏的","examples":[{"en":"Africa is sparsely populated in many areas.","zh":"非洲許多地區人口稀疏。"},{"en":"A sparsely populated place has few people living across a large area.","zh":"“Sparsely populated” 指在大範圍土地上居住的人很少。"},{"en":"A sparsely populated village may have only one shop and one bus each day.","zh":"一個人口稀疏的村莊可能每天只有一間商店和一班巴士。"},{"en":"Sparsely populated areas often need more expensive roads and services per person.","zh":"人口稀疏地區通常需要更高的人均道路和服務成本。"},{"en":"This phrase contrasts with densely populated places, where many people live close together.","zh":"這個短語與人口密集的地方形成對比，即很多人住得很近。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":2},{"front":"diverse languages and cultures","meaning":"多元語言和文化","examples":[{"en":"Africa has diverse languages and cultures.","zh":"非洲有多元語言和文化。"},{"en":"Diverse languages and cultures means many different ways of speaking, living, believing, and celebrating.","zh":"多元語言和文化指許多不同的說話、生活、信仰和慶祝方式。"},{"en":"A school with diverse languages and cultures can help students learn from one another.","zh":"一間擁有多元語言和文化的學校可以幫助學生互相學習。"},{"en":"Diverse languages and cultures can enrich society, but they may also require careful communication.","zh":"多元語言和文化可以豐富社會，但也可能需要謹慎溝通。"},{"en":"The phrase highlights variety within a group or region.","zh":"這個短語強調一個群體或地區內部的多樣性。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":2},{"front":"landlocked countries","meaning":"內陸國家","examples":[{"en":"Africa contains numerous landlocked countries.","zh":"非洲有許多內陸國家。"},{"en":"Landlocked countries are countries with no coastline or direct access to the sea.","zh":"內陸國家是沒有海岸線或直接出海口的國家。"},{"en":"A landlocked country may depend on its neighbours’ ports for international trade.","zh":"內陸國家可能依賴鄰國港口進行國際貿易。"},{"en":"Transport costs can be higher for landlocked countries because goods must cross borders.","zh":"內陸國家的運輸成本可能較高，因為貨物必須跨越邊境。"},{"en":"This phrase is often used when discussing geography and economic development.","zh":"這個短語常用於討論地理和經濟發展。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":2},{"front":"far from international markets","meaning":"遠離國際市場","examples":[{"en":"Some African countries are far from international markets.","zh":"一些非洲國家遠離國際市場。"},{"en":"Being far from international markets means it is difficult or expensive to reach buyers and sellers in other countries.","zh":"遠離國際市場指難以或昂貴地接觸其他國家的買家和賣家。"},{"en":"A small factory far from international markets may pay more to export its products.","zh":"一間遠離國際市場的小工廠可能需要支付更多出口費用。"},{"en":"Farmers far from international markets may earn less because transport costs reduce profits.","zh":"遠離國際市場的農民可能收入較低，因為運輸成本減少利潤。"},{"en":"The phrase explains why distance can make trade harder.","zh":"這個短語解釋距離為何會令貿易更困難。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":2},{"front":"Zambian-born economist","meaning":"贊比亞出生的經濟學家","examples":[{"en":"Dambisa Moyo is a Zambian-born economist.","zh":"Dambisa Moyo 是一位贊比亞出生的經濟學家。"},{"en":"A Zambian-born economist is an economist who was born in Zambia.","zh":"贊比亞出生的經濟學家是指出生於贊比亞的經濟學家。"},{"en":"A Hong Kong-born teacher is a teacher who was born in Hong Kong.","zh":"香港出生的老師是指出生於香港的老師。"},{"en":"A Zambian-born economist may understand local issues through both study and personal background.","zh":"贊比亞出生的經濟學家可能透過學術研究和個人背景理解本地問題。"},{"en":"The phrase tells us both a person’s birthplace and professional field.","zh":"這個短語同時告訴我們一個人的出生地和專業領域。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":2},{"front":"have another theory","meaning":"有另一種理論","examples":[{"en":"Dambisa Moyo has another theory about African poverty.","zh":"Dambisa Moyo 對非洲貧窮有另一種理論。"},{"en":"To have another theory means to offer a different explanation from the one already mentioned.","zh":"“Have another theory” 指提出與已提及解釋不同的另一種說法。"},{"en":"The doctor had another theory about why the patient felt tired.","zh":"醫生對病人為何疲倦有另一種理論。"},{"en":"If one explanation does not fit the facts, researchers may have another theory.","zh":"如果一個解釋不符合事實，研究人員可能有另一種理論。"},{"en":"This phrase is useful when comparing different possible causes.","zh":"這個短語適合用來比較不同可能原因。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":2},{"front":"Dead Aid","meaning":"《Dead Aid》","examples":[{"en":"In Dead Aid, Moyo criticises international aid.","zh":"在《Dead Aid》中，Moyo 批評國際援助。"},{"en":"Dead Aid is the title of Moyo’s book about the possible damage caused by aid.","zh":"《Dead Aid》是 Moyo 關於援助可能造成傷害的一本書名。"},{"en":"A book title like Dead Aid suggests that aid may no longer be helping in the way people expect.","zh":"像《Dead Aid》這樣的書名暗示援助可能不再如人們預期般有幫助。"},{"en":"Students can use Dead Aid as an example when discussing development and poverty.","zh":"學生討論發展和貧窮時，可以使用《Dead Aid》作為例子。"},{"en":"The title is memorable because it challenges the usual positive image of aid.","zh":"這個書名令人記得，因為它挑戰援助通常正面的形象。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":3},{"front":"propose that","meaning":"提出；認為","examples":[{"en":"Moyo proposes that international aid is largely to blame.","zh":"Moyo 提出國際援助負有主要責任。"},{"en":"To propose that something is true means to suggest it as an idea or explanation.","zh":"“Propose that” 指提出某事為一種想法或解釋。"},{"en":"The teacher proposed that shorter lessons might help tired students concentrate.","zh":"老師提出較短課堂可能幫助疲倦學生集中精神。"},{"en":"Scientists may propose that pollution is causing changes in local wildlife.","zh":"科學家可能提出污染正在造成本地野生動物的變化。"},{"en":"This phrase sounds more formal than “say” and is common in academic writing.","zh":"這個短語比 “say” 更正式，常見於學術寫作。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":3},{"front":"international aid","meaning":"國際援助","examples":[{"en":"International aid is central to Moyo’s argument.","zh":"國際援助是 Moyo 論點的核心。"},{"en":"International aid is help given by one country, organisation, or community to another country in need.","zh":"國際援助是一個國家、組織或社群向有需要的另一個國家提供的幫助。"},{"en":"International aid may include food, medicine, money, training, or emergency support.","zh":"國際援助可能包括食物、藥物、金錢、培訓或緊急支援。"},{"en":"After a flood, international aid can help provide clean water and shelter.","zh":"水災後，國際援助可以幫助提供潔淨食水和住所。"},{"en":"The phrase often appears in discussions of poverty, disasters, and development.","zh":"這個短語常出現在關於貧窮、災難和發展的討論中。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":3},{"front":"be largely to blame for","meaning":"對……負有主要責任","examples":[{"en":"Moyo argues that aid is largely to blame for African poverty.","zh":"Moyo 認為援助對非洲貧窮負有主要責任。"},{"en":"To be largely to blame for something means to be one of the main causes of a bad result.","zh":"“Be largely to blame for” 指是某個壞結果的主要原因之一。"},{"en":"Poor planning was largely to blame for the project’s failure.","zh":"糟糕規劃對項目失敗負有主要責任。"},{"en":"If a student never revises, that may be largely to blame for weak exam results.","zh":"如果學生從不溫習，這可能對考試成績差負有主要責任。"},{"en":"The phrase does not mean the only cause, but a very important cause.","zh":"這個短語不表示唯一原因，而是表示非常重要的原因。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":3},{"front":"African poverty","meaning":"非洲貧窮問題","examples":[{"en":"Moyo links international aid to African poverty.","zh":"Moyo 把國際援助與非洲貧窮問題連繫起來。"},{"en":"African poverty refers to poverty experienced by people, communities, or countries in Africa.","zh":"非洲貧窮問題指非洲人民、社區或國家經歷的貧窮。"},{"en":"African poverty cannot be explained by one simple cause.","zh":"非洲貧窮問題不能由一個簡單原因解釋。"},{"en":"Discussions of African poverty often include history, geography, politics, education, and trade.","zh":"關於非洲貧窮問題的討論常包括歷史、地理、政治、教育和貿易。"},{"en":"The phrase describes a broad problem, not the condition of every African person.","zh":"這個短語描述一個廣泛問題，而不是每個非洲人的狀況。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":3},{"front":"encourage dependence and corruption","meaning":"鼓勵依賴和貪污","examples":[{"en":"She argues that aid has encouraged dependence and corruption.","zh":"她認為援助鼓勵了依賴和貪污。"},{"en":"To encourage dependence and corruption means to make people rely on help and make dishonest behaviour easier.","zh":"“Encourage dependence and corruption” 指令人依賴幫助，並令不誠實行為更容易出現。"},{"en":"Giving a child every answer may encourage dependence instead of learning.","zh":"給孩子每個答案可能鼓勵依賴，而不是學習。"},{"en":"Weak controls over public money can encourage corruption among officials.","zh":"對公款監管薄弱可能鼓勵官員貪污。"},{"en":"The phrase describes a situation where help creates unhealthy habits and dishonest systems.","zh":"這個短語描述幫助造成不健康習慣和不誠實制度的情況。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":3},{"front":"dependence and corruption","meaning":"依賴和貪污","examples":[{"en":"Moyo believes aid creates dependence and corruption.","zh":"Moyo 認為援助造成依賴和貪污。"},{"en":"Dependence is relying too much on others, while corruption is dishonest use of power or money.","zh":"依賴是過度依靠他人，而貪污是以不誠實方式使用權力或金錢。"},{"en":"A company may create dependence if workers cannot make any decision without the boss.","zh":"如果員工沒有老闆就不能作任何決定，公司可能造成依賴。"},{"en":"Corruption may occur when officials accept money to give unfair advantages.","zh":"當官員收錢以提供不公平利益時，貪污可能出現。"},{"en":"Dependence and corruption can weaken trust and slow development.","zh":"依賴和貪污可以削弱信任並拖慢發展。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":3},{"front":"divert talented people from","meaning":"使有才能的人離開……","examples":[{"en":"Aid may divert talented people from business.","zh":"援助可能使有才能的人離開商業。"},{"en":"To divert talented people from something means to pull skilled people away from an important activity.","zh":"“Divert talented people from” 指把有技能的人從重要活動中拉走。"},{"en":"High salaries in one industry may divert talented people from teaching.","zh":"某個行業的高薪可能使有才能的人離開教學。"},{"en":"Too much paperwork can divert talented doctors from patient care.","zh":"太多文書工作可能使有才能的醫生離開病人護理。"},{"en":"The phrase suggests that ability is being used in the wrong place.","zh":"這個短語暗示能力被用在錯誤地方。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":3},{"front":"talented people","meaning":"有才能的人","examples":[{"en":"Moyo says talented people are drawn away from business.","zh":"Moyo 說有才能的人被吸引離開商業。"},{"en":"Talented people are people with strong ability, skill, intelligence, or creativity.","zh":"有才能的人是指有強大能力、技能、智慧或創意的人。"},{"en":"Talented people in a school may become leaders, artists, scientists, or entrepreneurs.","zh":"學校中的有才能的人可能成為領袖、藝術家、科學家或創業者。"},{"en":"If talented people leave a country, local businesses may struggle to grow.","zh":"如果有才能的人離開一個國家，本地企業可能難以增長。"},{"en":"Talented people still need training and opportunity to use their abilities well.","zh":"有才能的人仍需要培訓和機會，才能好好運用能力。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":3},{"front":"one of her statistics","meaning":"她其中一項統計數據","examples":[{"en":"One of her statistics is that poverty rose while aid was high.","zh":"她其中一項統計數據是，在援助高企時貧窮率上升。"},{"en":"One of her statistics means one numerical fact she uses to support her argument.","zh":"“One of her statistics” 指她用來支持論點的一項數字資料。"},{"en":"One of her statistics shows how many students improved after extra practice.","zh":"她其中一項統計數據顯示有多少學生在額外練習後進步。"},{"en":"Writers use statistics to make an argument seem more factual.","zh":"作者使用統計數據，使論點看起來更有事實根據。"},{"en":"A statistic is useful only if readers understand where it came from and what it measures.","zh":"統計數據只有在讀者明白其來源和衡量內容時才有用。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":3},{"front":"from 1970 to 1998","meaning":"從1970年至1998年","examples":[{"en":"From 1970 to 1998, aid to Africa was high.","zh":"從1970年至1998年，對非洲的援助很高。"},{"en":"From 1970 to 1998 means during the period beginning in 1970 and ending in 1998.","zh":"“From 1970 to 1998” 指由1970年開始至1998年結束的期間。"},{"en":"From 2010 to 2020, the school added more classrooms and computers.","zh":"從2010年至2020年，學校增設了更多課室和電腦。"},{"en":"A chart may show changes from 1970 to 1998 to compare long-term trends.","zh":"圖表可能展示從1970年至1998年的變化，以比較長期趨勢。"},{"en":"The phrase marks a time range, not a single year.","zh":"這個短語標示一段時間，而不是單一年份。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":3},{"front":"aid to Africa","meaning":"對非洲的援助","examples":[{"en":"Aid to Africa was highest during the period discussed.","zh":"在討論的時期中，對非洲的援助最高。"},{"en":"Aid to Africa means help given to African countries or communities.","zh":"對非洲的援助指給予非洲國家或社區的幫助。"},{"en":"Aid to Africa may come from governments, charities, or international organisations.","zh":"對非洲的援助可能來自政府、慈善機構或國際組織。"},{"en":"Aid to Africa can support emergency relief, education, healthcare, or infrastructure.","zh":"對非洲的援助可以支援緊急救援、教育、醫療或基礎建設。"},{"en":"The phrase describes the direction of help: from outside donors to Africa.","zh":"這個短語描述幫助的方向：由外部捐助者到非洲。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":4},{"front":"poverty rose from...to...","meaning":"貧窮率由……升至……","examples":[{"en":"Poverty rose from 11% to 66%.","zh":"貧窮率由11%升至66%。"},{"en":"“Poverty rose from A to B” means the poverty rate increased from the first figure to the second.","zh":"“Poverty rose from A to B” 指貧窮率由第一個數字增加至第二個數字。"},{"en":"Unemployment rose from 4% to 9% after the factory closed.","zh":"工廠關閉後，失業率由4%升至9%。"},{"en":"If rent rises from $800 to $1,200, families may have less money for food.","zh":"如果租金由800美元升至1,200美元，家庭用於食物的金錢可能減少。"},{"en":"This pattern is useful for describing numerical increases clearly.","zh":"這個句式適合清楚描述數字上升。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":4},{"front":"if aid were cut","meaning":"如果援助被削減","examples":[{"en":"If aid were cut, Moyo believes Africans would use resources more creatively.","zh":"如果援助被削減，Moyo 相信非洲人會更有創意地運用資源。"},{"en":"If aid were cut means if the amount of help were reduced or stopped.","zh":"“If aid were cut” 指如果幫助的數量被減少或停止。"},{"en":"If school funding were cut, some clubs and activities might disappear.","zh":"如果學校經費被削減，一些學會和活動可能消失。"},{"en":"If aid were cut suddenly, vulnerable people could lose food, medicine, or shelter.","zh":"如果援助突然被削減，弱勢人士可能失去食物、藥物或住所。"},{"en":"This phrase describes an imagined situation, not necessarily something that has happened.","zh":"這個短語描述想像情況，不一定是已發生的事。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":4},{"front":"utilise their resources more creatively","meaning":"更有創意地運用資源","examples":[{"en":"Moyo believes Africans would utilise their resources more creatively.","zh":"Moyo 相信非洲人會更有創意地運用資源。"},{"en":"To utilise resources more creatively means to use what is available in smarter and more original ways.","zh":"“Utilise resources more creatively” 指以更聰明和更有創意的方式使用現有東西。"},{"en":"A small school can utilise its resources more creatively by sharing rooms for different activities.","zh":"小學校可以透過把課室用於不同活動，更有創意地運用資源。"},{"en":"Families utilise their resources more creatively when they repair old furniture instead of buying new items.","zh":"家庭修理舊家具而不是買新物品時，就是更有創意地運用資源。"},{"en":"The phrase suggests finding better uses for limited money, materials, or skills.","zh":"這個短語暗示為有限的金錢、物料或技能尋找更好用途。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":4},{"front":"lack the capacity to","meaning":"缺乏能力去……","examples":[{"en":"Some states lack the capacity to care for their people.","zh":"一些國家缺乏能力去照顧其人民。"},{"en":"To lack the capacity to do something means not to have enough ability, money, staff, or systems to do it.","zh":"“Lack the capacity to” 指沒有足夠能力、金錢、人手或制度去做某事。"},{"en":"A small clinic may lack the capacity to treat hundreds of patients in one day.","zh":"小診所可能缺乏能力一天內治療數百名病人。"},{"en":"If a school lacks the capacity to support disabled students, extra funding and training are needed.","zh":"如果學校缺乏能力支援殘疾學生，就需要額外資金和培訓。"},{"en":"The phrase describes a practical inability, not simply unwillingness.","zh":"這個短語描述實際能力不足，而不只是沒有意願。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":4},{"front":"care for its people","meaning":"照顧其人民","examples":[{"en":"A weak state may lack the capacity to care for its people.","zh":"弱國可能缺乏能力去照顧其人民。"},{"en":"To care for its people means to protect citizens and provide basic support such as health, safety, and education.","zh":"“Care for its people” 指保護公民並提供醫療、安全和教育等基本支援。"},{"en":"A government cares for its people when hospitals and schools are accessible.","zh":"當醫院和學校容易使用時，政府就是在照顧其人民。"},{"en":"If leaders ignore clean water and public safety, they are failing to care for their people.","zh":"如果領袖忽視潔淨食水和公共安全，他們就是未能照顧其人民。"},{"en":"The phrase is often used when judging the responsibility of a state.","zh":"這個短語常用於評價國家的責任。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":4},{"front":"non-governmental organisations","meaning":"非政府組織","examples":[{"en":"Non-governmental organisations may provide food or medical supplies.","zh":"非政府組織可能提供食物或醫療物資。"},{"en":"Non-governmental organisations are groups that work on public problems but are not part of the government.","zh":"非政府組織是處理公共問題但不屬於政府的團體。"},{"en":"Non-governmental organisations may run shelters, food banks, schools, or health projects.","zh":"非政府組織可能營運庇護所、食物銀行、學校或健康項目。"},{"en":"After a disaster, non-governmental organisations can reach communities before official help arrives.","zh":"災難後，非政府組織可以在官方援助到達前接觸社區。"},{"en":"The phrase is formal; “NGOs” is the shorter version.","zh":"這個短語較正式；“NGOs” 是較短寫法。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":4},{"front":"NGOs","meaning":"非政府組織","examples":[{"en":"NGOs sometimes assume the role of weak states.","zh":"非政府組織有時承擔弱國的角色。"},{"en":"NGOs are non-governmental organisations that provide help, services, or advocacy outside government.","zh":"NGOs 是非政府組織，指在政府以外提供幫助、服務或倡議的團體。"},{"en":"NGOs may teach children, deliver medicine, or protect the environment.","zh":"非政府組織可能教導兒童、運送藥物或保護環境。"},{"en":"If the government cannot provide clean water, NGOs may step in temporarily.","zh":"如果政府不能提供潔淨食水，非政府組織可能暫時介入。"},{"en":"NGOs can help quickly, but they cannot always replace a strong public system.","zh":"非政府組織可以快速提供幫助，但不一定能取代強大的公共制度。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":4},{"front":"assume this role","meaning":"承擔這個角色","examples":[{"en":"NGOs assume this role when states cannot provide basic services.","zh":"當國家不能提供基本服務時，非政府組織承擔這個角色。"},{"en":"To assume this role means to take on a responsibility that someone else normally has.","zh":"“Assume this role” 指承擔通常由其他人負責的責任。"},{"en":"When parents are busy, an older sibling may assume this role and care for younger children.","zh":"當父母忙碌時，年長兄姊可能承擔這個角色，照顧年幼孩子。"},{"en":"If a manager leaves suddenly, another worker may assume this role until a replacement arrives.","zh":"如果經理突然離職，另一名員工可能承擔這個角色，直到替補到任。"},{"en":"The phrase suggests taking responsibility, sometimes because there is no better option.","zh":"這個短語暗示承擔責任，有時是因為沒有更好選擇。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":4},{"front":"distribute food or medical supplies","meaning":"派發食物或醫療物資","examples":[{"en":"NGOs distribute food or medical supplies.","zh":"非政府組織派發食物或醫療物資。"},{"en":"To distribute food or medical supplies means to give them out to people who need them.","zh":"“Distribute food or medical supplies” 指把食物或醫療物資派給有需要的人。"},{"en":"Volunteers distribute food or medical supplies after storms damage local homes.","zh":"風暴破壞本地房屋後，義工派發食物或醫療物資。"},{"en":"If roads are blocked, it becomes harder to distribute food or medical supplies safely.","zh":"如果道路受阻，安全派發食物或醫療物資會變得更困難。"},{"en":"The phrase focuses on delivering useful items, not just collecting them.","zh":"這個短語強調運送和分發有用物品，而不只是收集它們。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":4},{"front":"medical supplies","meaning":"醫療物資","examples":[{"en":"International organisations often provide medical supplies.","zh":"國際組織經常提供醫療物資。"},{"en":"Medical supplies are items used for health treatment, such as bandages, medicine, gloves, and syringes.","zh":"醫療物資是用於健康治療的物品，例如繃帶、藥物、手套和針筒。"},{"en":"A clinic needs medical supplies before it can treat injured patients.","zh":"診所在治療受傷病人之前需要醫療物資。"},{"en":"During a disease outbreak, shortages of medical supplies can put doctors and patients at risk.","zh":"在疾病爆發期間，醫療物資短缺可能令醫生和病人面臨風險。"},{"en":"The phrase usually refers to practical materials used in healthcare.","zh":"這個短語通常指醫療中使用的實用物料。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":4},{"front":"reduce the ability of","meaning":"削弱……的能力","examples":[{"en":"Moyo argues that NGOs reduce the ability of the state to provide services.","zh":"Moyo 認為非政府組織削弱國家提供服務的能力。"},{"en":"To reduce the ability of someone or something means to make it less able to do a task well.","zh":"“Reduce the ability of” 指令某人或某事物較不能好好完成任務。"},{"en":"Too much noise can reduce the ability of students to concentrate.","zh":"太多噪音會削弱學生集中精神的能力。"},{"en":"Poor training can reduce the ability of staff to solve customer problems.","zh":"培訓不足會削弱員工解決顧客問題的能力。"},{"en":"The phrase shows that something weakens performance or capacity.","zh":"這個短語顯示某事削弱表現或能力。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":5},{"front":"provide basic services","meaning":"提供基本服務","examples":[{"en":"The state should provide basic services.","zh":"國家應該提供基本服務。"},{"en":"To provide basic services means to supply essential things such as water, healthcare, education, safety, and transport.","zh":"“Provide basic services” 指供應食水、醫療、教育、安全和交通等必需服務。"},{"en":"A city must provide basic services so residents can live safely and normally.","zh":"城市必須提供基本服務，使居民能安全而正常地生活。"},{"en":"If a village lacks electricity and clean water, the government is not providing basic services well.","zh":"如果村莊缺乏電力和潔淨食水，政府就沒有好好提供基本服務。"},{"en":"The phrase usually refers to duties expected from public authorities.","zh":"這個短語通常指公共機構應承擔的責任。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":5},{"front":"furthermore","meaning":"此外","examples":[{"en":"Furthermore, aid goods and money may be stolen.","zh":"此外，援助物資和金錢可能被偷走。"},{"en":"“Furthermore” means “in addition” and introduces another supporting point.","zh":"“Furthermore” 解作「此外」，用來提出另一個支持論點。"},{"en":"The course is expensive; furthermore, it requires three evenings a week.","zh":"這個課程很昂貴；此外，它每星期需要三個晚上。"},{"en":"The plan saves money; furthermore, it reduces waste.","zh":"這個計劃節省金錢；此外，它減少浪費。"},{"en":"This word is formal and useful for adding a second reason in writing.","zh":"這個詞較正式，適合在寫作中加入第二個理由。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":5},{"front":"during this process","meaning":"在這個過程中","examples":[{"en":"During this process, officials may siphon off aid money.","zh":"在這個過程中，官員可能挪用援助金錢。"},{"en":"During this process means while a particular set of actions is happening.","zh":"“During this process” 指在某一系列行動發生期間。"},{"en":"During this process, students check their answers and correct small mistakes.","zh":"在這個過程中，學生檢查答案並改正小錯誤。"},{"en":"During this process, food is packed, labelled, and delivered to families.","zh":"在這個過程中，食物被包裝、貼上標籤並送到家庭。"},{"en":"The phrase helps describe what happens in the middle of a longer activity.","zh":"這個短語有助描述較長活動中段發生的事情。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":5},{"front":"those in government and the military","meaning":"政府和軍方人士","examples":[{"en":"Those in government and the military may misuse aid.","zh":"政府和軍方人士可能濫用援助。"},{"en":"Those in government and the military means people who hold positions in political offices or armed forces.","zh":"“Those in government and the military” 指在政治機構或軍隊中擔任職位的人。"},{"en":"Those in government and the military often have power over public money and security.","zh":"政府和軍方人士通常掌握公款和安全方面的權力。"},{"en":"If those in government and the military act dishonestly, ordinary citizens may suffer.","zh":"如果政府和軍方人士不誠實行事，普通市民可能受苦。"},{"en":"The phrase identifies powerful groups rather than naming individuals.","zh":"這個短語指出有權力的群體，而不是點名個人。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":5},{"front":"siphon off","meaning":"私吞；挪用","examples":[{"en":"Officials may siphon off aid goods and money.","zh":"官員可能私吞援助物資和金錢。"},{"en":"To siphon off money or goods means to secretly take them for personal use.","zh":"“Siphon off” 金錢或物資指秘密拿走作私人用途。"},{"en":"A dishonest manager may siphon off company funds into a private account.","zh":"不誠實的經理可能把公司資金挪入私人帳戶。"},{"en":"If charity donations are siphoned off, fewer supplies reach people in need.","zh":"如果慈善捐款被挪用，到達有需要人士手中的物資會減少。"},{"en":"The phrase usually suggests hidden theft or misuse.","zh":"這個短語通常暗示隱蔽的盜竊或濫用。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":5},{"front":"aid goods and money","meaning":"援助物資和金錢","examples":[{"en":"Aid goods and money may be stolen by officials.","zh":"援助物資和金錢可能被官員偷走。"},{"en":"Aid goods and money are physical supplies and funds given to help people in need.","zh":"援助物資和金錢是給予有需要人士的實物供應和資金。"},{"en":"Aid goods and money may include rice, blankets, medicine, school materials, and cash support.","zh":"援助物資和金錢可能包括米、毛毯、藥物、學校用品和現金支援。"},{"en":"If aid goods and money are not monitored, they may not reach the intended families.","zh":"如果援助物資和金錢沒有受到監管，它們可能無法送到目標家庭手中。"},{"en":"The phrase covers both material help and financial help.","zh":"這個短語涵蓋物質幫助和財政幫助。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":5},{"front":"Transparency International","meaning":"透明國際","examples":[{"en":"Transparency International surveys corruption around the world.","zh":"透明國際調查世界各地的貪污情況。"},{"en":"Transparency International is an organisation known for studying and reporting corruption.","zh":"透明國際是一個以研究和報告貪污情況聞名的組織。"},{"en":"Reports from Transparency International may help people compare corruption levels between countries.","zh":"透明國際的報告可能幫助人們比較不同國家的貪污水平。"},{"en":"Governments may feel pressure when Transparency International rates them poorly.","zh":"當透明國際給予差評時，政府可能感到壓力。"},{"en":"The name is linked to openness, honesty, and anti-corruption work.","zh":"這個名稱與公開、誠實和反貪工作有關。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":5},{"front":"survey corruption","meaning":"調查貪污情況","examples":[{"en":"The organisation surveys corruption in different countries.","zh":"該組織調查不同國家的貪污情況。"},{"en":"To survey corruption means to collect information about dishonest use of power or money.","zh":"“Survey corruption” 指收集關於不誠實使用權力或金錢的資料。"},{"en":"Researchers may survey corruption by asking business owners about bribery.","zh":"研究人員可能透過詢問企業主賄賂情況來調查貪污。"},{"en":"When organisations survey corruption, they can compare risks across regions.","zh":"當組織調查貪污情況時，它們可以比較不同地區的風險。"},{"en":"The phrase describes investigation through data, reports, or public opinions.","zh":"這個短語描述透過數據、報告或公眾意見進行調查。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":5},{"front":"rate something poorly","meaning":"給予……較差評級","examples":[{"en":"Transparency International rates many African states poorly.","zh":"透明國際給許多非洲國家較差評級。"},{"en":"To rate something poorly means to give it a low score or negative evaluation.","zh":"“Rate something poorly” 指給某事物低分或負面評價。"},{"en":"Customers may rate a restaurant poorly if the food is cold and service is rude.","zh":"如果食物冷、服務無禮，顧客可能給餐廳較差評級。"},{"en":"A school may be rated poorly when exam results and safety are weak.","zh":"當考試成績和安全表現薄弱，學校可能被給予較差評級。"},{"en":"The phrase shows that an organisation or person judges something unfavourably.","zh":"這個短語顯示某個組織或人士對某事物作出不利評價。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":5},{"front":"the majority of","meaning":"大多數……","examples":[{"en":"The majority of African states are rated poorly.","zh":"大多數非洲國家被給予較差評級。"},{"en":"The majority of a group means more than half of it.","zh":"“The majority of” 某個群體指超過一半。"},{"en":"The majority of students passed the exam, so most students succeeded.","zh":"大多數學生通過考試，所以大部分學生成功了。"},{"en":"If the majority of workers support a change, management may accept it.","zh":"如果大多數員工支持改變，管理層可能接受。"},{"en":"This phrase is useful when describing what is true for most members of a group.","zh":"這個短語適合用來描述某個群體中大部分成員的情況。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":5},{"front":"provide another example","meaning":"提供另一個例子","examples":[{"en":"Moyo provides another example involving mosquito nets.","zh":"Moyo 提供另一個關於蚊帳的例子。"},{"en":"To provide another example means to give one more case to support or explain an idea.","zh":"“Provide another example” 指再給出一個案例來支持或解釋想法。"},{"en":"The teacher provided another example when students still looked confused.","zh":"當學生仍然看起來困惑時，老師提供另一個例子。"},{"en":"A writer may provide another example to make an argument clearer.","zh":"作者可能提供另一個例子，使論點更清晰。"},{"en":"The phrase is useful when adding evidence or explanation.","zh":"這個短語適合在加入證據或解釋時使用。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":6},{"front":"Hollywood star","meaning":"荷里活明星","examples":[{"en":"A Hollywood star may donate mosquito nets.","zh":"荷里活明星可能捐贈蚊帳。"},{"en":"A Hollywood star is a famous film actor or celebrity connected with the American film industry.","zh":"荷里活明星是與美國電影業有關的著名電影演員或名人。"},{"en":"A Hollywood star may use fame to raise money for charity.","zh":"荷里活明星可能利用名氣為慈善籌款。"},{"en":"When a Hollywood star supports a campaign, more people may notice it.","zh":"當荷里活明星支持一個運動時，更多人可能注意到它。"},{"en":"The phrase suggests public fame, not expert knowledge.","zh":"這個短語暗示公眾名氣，而不是專業知識。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":6},{"front":"donate","meaning":"捐贈","examples":[{"en":"A celebrity may donate American-made mosquito nets.","zh":"名人可能捐贈美國製造的蚊帳。"},{"en":"To donate means to give money, goods, blood, time, or help without expecting payment.","zh":"“Donate” 指捐出金錢、物品、血液、時間或幫助，而不期望付款。"},{"en":"People donate clothes to families who lost their homes in a fire.","zh":"人們把衣服捐贈給在火災中失去家園的家庭。"},{"en":"If many people donate small amounts, a charity can fund a large project.","zh":"如果許多人捐贈小額金錢，慈善機構可以資助大型項目。"},{"en":"The word focuses on giving for a helpful or public purpose.","zh":"這個詞強調為有益或公共目的而給予。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":6},{"front":"American-made mosquito nets","meaning":"美國製造的蚊帳","examples":[{"en":"American-made mosquito nets may be donated to Africa.","zh":"美國製造的蚊帳可能被捐贈到非洲。"},{"en":"American-made mosquito nets are mosquito nets produced in the United States.","zh":"美國製造的蚊帳是指在美國生產的蚊帳。"},{"en":"American-made mosquito nets may protect people from insect bites while they sleep.","zh":"美國製造的蚊帳可以在人們睡覺時保護他們免受昆蟲叮咬。"},{"en":"If donated nets replace local products, local sellers may lose customers.","zh":"如果捐贈的蚊帳取代本地產品，本地賣家可能失去顧客。"},{"en":"The phrase identifies both the product and where it was made.","zh":"這個短語同時指出產品和製造地。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":6},{"front":"malaria-prone areas","meaning":"瘧疾高發地區","examples":[{"en":"Mosquito nets benefit malaria-prone areas.","zh":"蚊帳有利於瘧疾高發地區。"},{"en":"Malaria-prone areas are places where malaria is likely to spread.","zh":"瘧疾高發地區是瘧疾較可能傳播的地方。"},{"en":"People in malaria-prone areas often need mosquito nets, medicine, and public health education.","zh":"瘧疾高發地區的人通常需要蚊帳、藥物和公共衛生教育。"},{"en":"Heavy rain and standing water can make some villages malaria-prone areas.","zh":"大雨和積水可以使一些村莊成為瘧疾高發地區。"},{"en":"The phrase describes places with a higher risk of malaria.","zh":"這個短語描述瘧疾風險較高的地方。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":6},{"front":"draw business away from","meaning":"搶走……的生意","examples":[{"en":"Imported mosquito nets may draw business away from local traders.","zh":"進口蚊帳可能搶走本地商人的生意。"},{"en":"To draw business away from someone means to take customers or sales away from them.","zh":"“Draw business away from” 指從某人那裡吸走顧客或銷售。"},{"en":"A new supermarket may draw business away from small grocery shops.","zh":"新超市可能搶走小雜貨店的生意。"},{"en":"Free imported goods can draw business away from local producers.","zh":"免費進口貨可能搶走本地生產者的生意。"},{"en":"The phrase often describes competition that weakens existing businesses.","zh":"這個短語常描述削弱現有企業的競爭。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":6},{"front":"local African traders","meaning":"本地非洲商人","examples":[{"en":"Local African traders may lose business because of donations.","zh":"本地非洲商人可能因捐贈而失去生意。"},{"en":"Local African traders are African sellers or businesspeople who operate in their own communities or regions.","zh":"本地非洲商人是指在自己社區或地區經營的非洲賣家或商人。"},{"en":"Local African traders may sell food, clothes, tools, medicine, or household goods.","zh":"本地非洲商人可能售賣食物、衣服、工具、藥物或家居用品。"},{"en":"If donations flood a market, local African traders may struggle to compete.","zh":"如果捐贈品湧入市場，本地非洲商人可能難以競爭。"},{"en":"The phrase emphasises small local business rather than foreign suppliers.","zh":"這個短語強調本地小生意，而不是外國供應商。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":6},{"front":"supply nets","meaning":"供應蚊帳","examples":[{"en":"Local traders supply nets to their communities.","zh":"本地商人向其社區供應蚊帳。"},{"en":"To supply nets means to provide or sell nets to people who need them.","zh":"“Supply nets” 指向有需要的人提供或出售蚊帳。"},{"en":"A shop may supply nets to families before the rainy season.","zh":"商店可能在雨季前向家庭供應蚊帳。"},{"en":"If local traders supply nets regularly, communities can replace damaged ones quickly.","zh":"如果本地商人定期供應蚊帳，社區可以迅速替換損壞的蚊帳。"},{"en":"The phrase focuses on making goods available, not only making them.","zh":"這個短語強調令貨品可取得，而不只是製造它們。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":6},{"front":"more consultation is needed","meaning":"需要更多諮詢","examples":[{"en":"More consultation is needed between foreigners and local communities.","zh":"外國人與本地社區之間需要更多諮詢。"},{"en":"More consultation is needed means people should discuss decisions with those affected before acting.","zh":"“More consultation is needed” 指人們在行動前應與受影響者討論決定。"},{"en":"More consultation is needed before a school changes its timetable.","zh":"學校改變時間表前需要更多諮詢。"},{"en":"If residents are not asked about a new road, more consultation is needed.","zh":"如果居民沒有被問及新道路，便需要更多諮詢。"},{"en":"The phrase suggests that better listening could prevent mistakes.","zh":"這個短語暗示更好的聆聽可以避免錯誤。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":6},{"front":"do-gooder foreigners","meaning":"好心辦壞事的外國人","examples":[{"en":"Do-gooder foreigners may fail to understand local needs.","zh":"好心辦壞事的外國人可能未能理解本地需要。"},{"en":"Do-gooder foreigners are outsiders who want to help but may act without enough local understanding.","zh":"“Do-gooder foreigners” 指想幫忙但可能缺乏足夠本地理解的外來者。"},{"en":"Do-gooder foreigners may donate items that people do not actually need.","zh":"好心辦壞事的外國人可能捐贈人們實際上不需要的物品。"},{"en":"If do-gooder foreigners ignore local advice, their help can create problems.","zh":"如果好心辦壞事的外國人忽視本地建議，他們的幫助可能製造問題。"},{"en":"The phrase can sound critical because good intentions are not always enough.","zh":"這個短語可以帶批評意味，因為好意不一定足夠。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":6},{"front":"local communities","meaning":"本地社區","examples":[{"en":"Foreign helpers should consult local communities.","zh":"外國援助者應諮詢本地社區。"},{"en":"Local communities are groups of people who live in the same area and share daily needs.","zh":"本地社區是居住在同一地區並有共同日常需要的人群。"},{"en":"Local communities understand their own schools, roads, jobs, and health problems best.","zh":"本地社區最了解自己的學校、道路、工作和健康問題。"},{"en":"Projects are more likely to succeed when local communities help design them.","zh":"當本地社區協助設計項目時，項目較可能成功。"},{"en":"The phrase focuses on ordinary residents, not only officials or experts.","zh":"這個短語強調普通居民，而不只是官員或專家。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":6},{"front":"increase their wealth through","meaning":"透過……增加財富","examples":[{"en":"African nations could increase their wealth through investment.","zh":"非洲國家可以透過投資增加財富。"},{"en":"To increase wealth through something means to become richer by using that method.","zh":"“Increase wealth through” 指透過某種方法變得更富有。"},{"en":"A family can increase its wealth through saving and careful investment.","zh":"家庭可以透過儲蓄和謹慎投資增加財富。"},{"en":"A city may increase its wealth through tourism, technology, or trade.","zh":"城市可能透過旅遊、科技或貿易增加財富。"},{"en":"The phrase links a method to financial improvement.","zh":"這個短語把某種方法與財政改善連繫起來。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":7},{"front":"investment in bonds","meaning":"債券投資","examples":[{"en":"Moyo suggests investment in bonds as one path to wealth.","zh":"Moyo 建議債券投資作為通往財富的一條道路。"},{"en":"Investment in bonds means putting money into loans issued by governments or companies in return for interest.","zh":"債券投資指把錢投入由政府或公司發行的貸款，以換取利息。"},{"en":"A retiree may choose investment in bonds because bonds can be more stable than shares.","zh":"退休人士可能選擇債券投資，因為債券可以比股票更穩定。"},{"en":"If interest rates change, investment in bonds may become more or less attractive.","zh":"如果利率改變，債券投資可能變得更吸引或較不吸引。"},{"en":"The phrase belongs to finance and describes one way of raising or growing money.","zh":"這個短語屬於金融，描述籌集或增長金錢的一種方式。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":7},{"front":"increased co-operation with","meaning":"加強與……合作","examples":[{"en":"Moyo suggests increased co-operation with China.","zh":"Moyo 建議加強與中國合作。"},{"en":"Increased co-operation with someone means more working together with that person, group, or country.","zh":"“Increased co-operation with” 指與某人、群體或國家有更多合作。"},{"en":"Schools need increased co-operation with parents to support weak students.","zh":"學校需要加強與家長合作，以支援能力較弱的學生。"},{"en":"Increased co-operation with local hospitals can improve emergency planning.","zh":"加強與本地醫院合作可以改善緊急規劃。"},{"en":"The phrase suggests a closer and more active relationship.","zh":"這個短語暗示更密切和更積極的關係。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":7},{"front":"strong supporters of","meaning":"……的堅定支持者","examples":[{"en":"The presidents of Rwanda and Senegal are strong supporters of Moyo.","zh":"盧旺達和塞內加爾的總統是 Moyo 的堅定支持者。"},{"en":"Strong supporters of someone are people who firmly agree with or defend that person’s ideas.","zh":"某人的堅定支持者是堅決同意或維護該人想法的人。"},{"en":"Many parents are strong supporters of smaller class sizes.","zh":"許多家長是小班教學的堅定支持者。"},{"en":"Strong supporters of public transport may argue for cheaper fares and more buses.","zh":"公共交通的堅定支持者可能主張更便宜票價和更多巴士。"},{"en":"The phrase shows clear approval, not mild interest.","zh":"這個短語表示明確贊同，而不是輕微興趣。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":7},{"front":"critics say that","meaning":"批評者認為","examples":[{"en":"Critics say that Moyo’s theories are simplistic.","zh":"批評者認為 Moyo 的理論過分簡化。"},{"en":"“Critics say that” introduces what people who disagree or analyse negatively believe.","zh":"“Critics say that” 用來引出反對者或負面分析者的看法。"},{"en":"Critics say that the new policy helps businesses more than workers.","zh":"批評者認為新政策幫助企業多於幫助工人。"},{"en":"Critics say that online learning cannot fully replace classroom discussion.","zh":"批評者認為網上學習不能完全取代課堂討論。"},{"en":"The phrase is useful for presenting an opposing view.","zh":"這個短語適合用來呈現相反觀點。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":7},{"front":"simplistic","meaning":"過分簡化的","examples":[{"en":"Some critics consider Moyo’s theories simplistic.","zh":"一些批評者認為 Moyo 的理論過分簡化。"},{"en":"Simplistic means too simple because important details or difficulties are ignored.","zh":"“Simplistic” 指過於簡單，因為忽略了重要細節或困難。"},{"en":"Saying “poor people just need to work harder” is simplistic because it ignores wages, health, and opportunity.","zh":"說「窮人只需要更努力工作」是過分簡化的，因為它忽視工資、健康和機會。"},{"en":"A simplistic solution may sound attractive but fail in real life.","zh":"過分簡化的解決方案可能聽起來吸引，但在現實中失敗。"},{"en":"The word is usually critical, not complimentary.","zh":"這個詞通常帶批評意味，而不是稱讚。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":7},{"front":"international aid community","meaning":"國際援助界","examples":[{"en":"The international aid community is not responsible for geography.","zh":"國際援助界不需要為地理因素負責。"},{"en":"The international aid community means organisations, governments, experts, and workers involved in giving aid across countries.","zh":"國際援助界指參與跨國援助的組織、政府、專家和工作者。"},{"en":"The international aid community often discusses how to deliver help fairly and effectively.","zh":"國際援助界常討論如何公平和有效地提供幫助。"},{"en":"If the international aid community ignores local voices, projects may fail.","zh":"如果國際援助界忽視本地聲音，項目可能失敗。"},{"en":"The phrase describes a network of people and institutions, not one single organisation.","zh":"這個短語描述一個人員和機構網絡，而不是單一組織。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":7},{"front":"be responsible for","meaning":"對……負責","examples":[{"en":"Critics say aid agencies are not responsible for Africa’s geography.","zh":"批評者說援助機構不需要為非洲的地理因素負責。"},{"en":"To be responsible for something means to cause it, manage it, or be expected to deal with it.","zh":"“Be responsible for” 指造成、管理或被期望處理某事。"},{"en":"Parents are responsible for keeping young children safe.","zh":"父母有責任保護年幼孩子的安全。"},{"en":"Poor wiring may be responsible for the fire.","zh":"糟糕電線可能是火災的原因。"},{"en":"The meaning depends on context: duty, cause, or blame.","zh":"意思取決於語境：責任、原因或責備。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":7},{"front":"have nothing to do with","meaning":"與……無關","examples":[{"en":"Aid has nothing to do with some military takeovers.","zh":"援助與某些軍事政變無關。"},{"en":"To have nothing to do with something means to be unrelated to it.","zh":"“Have nothing to do with” 指與某事沒有關係。"},{"en":"The delay had nothing to do with the driver; the road was closed.","zh":"延誤與司機無關；道路被封閉了。"},{"en":"Her low score had nothing to do with laziness; she was sick during the exam.","zh":"她低分與懶惰無關；她考試期間生病了。"},{"en":"The phrase is useful for separating one issue from another.","zh":"這個短語適合用來把一個問題與另一個問題分開。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":7},{"front":"military takeovers","meaning":"軍事政變","examples":[{"en":"Military takeovers have damaged many African economies.","zh":"軍事政變破壞了許多非洲經濟。"},{"en":"Military takeovers happen when the army seizes control of a government.","zh":"軍事政變指軍隊奪取政府控制權。"},{"en":"A military takeover may close parliament, suspend elections, and silence opponents.","zh":"軍事政變可能關閉議會、暫停選舉並壓制反對者。"},{"en":"Businesses may leave a country after military takeovers because the rules become uncertain.","zh":"軍事政變後，企業可能離開一個國家，因為規則變得不確定。"},{"en":"The phrase is usually linked to political instability and force.","zh":"這個短語通常與政治不穩和武力有關。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":7},{"front":"legislation that hampers trade","meaning":"阻礙貿易的法例","examples":[{"en":"Some laws hamper trade in African countries.","zh":"一些法律阻礙非洲國家的貿易。"},{"en":"Legislation that hampers trade means laws that make buying and selling across markets harder.","zh":"阻礙貿易的法例是指令市場買賣更困難的法律。"},{"en":"Complicated customs rules can become legislation that hampers trade.","zh":"複雜的海關規則可以成為阻礙貿易的法例。"},{"en":"If businesses spend weeks waiting for permits, legislation may be hampering trade.","zh":"如果企業花數星期等待許可證，法例可能正在阻礙貿易。"},{"en":"The phrase links legal rules with slower economic activity.","zh":"這個短語把法律規則與較慢的經濟活動連繫起來。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":7},{"front":"hamper trade","meaning":"阻礙貿易","examples":[{"en":"Poor legislation can hamper trade.","zh":"糟糕法例可以阻礙貿易。"},{"en":"To hamper trade means to make trade slower, harder, or more expensive.","zh":"“Hamper trade” 指令貿易更慢、更困難或更昂貴。"},{"en":"Long border checks can hamper trade between neighbouring countries.","zh":"漫長的邊境檢查會阻礙鄰國之間的貿易。"},{"en":"Bad roads hamper trade because goods cannot reach markets quickly.","zh":"惡劣道路阻礙貿易，因為貨物不能快速到達市場。"},{"en":"The phrase describes something that blocks economic exchange.","zh":"這個短語描述阻礙經濟交換的事物。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":8},{"front":"half a century of","meaning":"半個世紀的……","examples":[{"en":"Africans have had half a century of self-government.","zh":"非洲人已有半個世紀的自治。"},{"en":"Half a century of something means fifty years of it.","zh":"“Half a century of” 某事指五十年的某事。"},{"en":"The school celebrated half a century of teaching local children.","zh":"學校慶祝半個世紀以來教導本地孩子。"},{"en":"Half a century of poor planning can leave a city with serious housing problems.","zh":"半個世紀的糟糕規劃可以令城市留下嚴重住屋問題。"},{"en":"The phrase is a formal way to say a long period of fifty years.","zh":"這個短語是表達五十年長時期的正式說法。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":8},{"front":"self-government","meaning":"自治；自我管治","examples":[{"en":"Many African states have had decades of self-government.","zh":"許多非洲國家已有數十年的自治。"},{"en":"Self-government means people or a country govern themselves instead of being ruled by outsiders.","zh":"自治指人民或國家自我管治，而不是由外來者統治。"},{"en":"Student councils give pupils a small experience of self-government.","zh":"學生會讓學生有小規模的自我管治經驗。"},{"en":"After independence, self-government brings both freedom and responsibility.","zh":"獨立後，自治帶來自由，也帶來責任。"},{"en":"The phrase often appears in political and historical writing.","zh":"這個短語常出現在政治和歷史寫作中。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":8},{"front":"economic control","meaning":"經濟控制權","examples":[{"en":"African states have had economic control since independence.","zh":"非洲國家自獨立以來已有經濟控制權。"},{"en":"Economic control means the power to make decisions about money, trade, taxes, and resources.","zh":"經濟控制權指就金錢、貿易、稅項和資源作決定的權力。"},{"en":"A government has economic control when it can set budgets and regulate markets.","zh":"當政府能制定預算和規管市場時，它便擁有經濟控制權。"},{"en":"Losing economic control can make a country depend on outside lenders.","zh":"失去經濟控制權可能令國家依賴外部貸款者。"},{"en":"The phrase is about decision-making power over the economy.","zh":"這個短語關於對經濟的決策權。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":8},{"front":"as the population doubled","meaning":"隨着人口翻倍","examples":[{"en":"As Africa’s population doubled, its GDP rose only 60%.","zh":"隨着非洲人口翻倍，其本地生產總值只上升60%。"},{"en":"As the population doubled means while the number of people became twice as large.","zh":"“As the population doubled” 指在人口變成兩倍的同時。"},{"en":"As the population doubled, the town needed more schools and hospitals.","zh":"隨着人口翻倍，該城鎮需要更多學校和醫院。"},{"en":"If jobs do not grow as the population doubles, unemployment may rise.","zh":"如果人口翻倍時工作沒有增加，失業率可能上升。"},{"en":"The phrase connects population growth with another change happening at the same time.","zh":"這個短語把人口增長與同時發生的另一個變化連繫起來。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":8},{"front":"GDP","meaning":"本地生產總值","examples":[{"en":"Africa’s GDP has risen only 60% in the same period.","zh":"非洲的本地生產總值在同一時期只上升60%。"},{"en":"GDP is the total value of goods and services produced in a country or region over a period.","zh":"本地生產總值是一個國家或地區在某段時期內生產的商品和服務總值。"},{"en":"If GDP grows, an economy is producing more overall.","zh":"如果本地生產總值增長，經濟整體上正在生產更多。"},{"en":"GDP can rise while many people still remain poor, so it is not the only measure of welfare.","zh":"本地生產總值可以上升，但許多人仍然貧窮，所以它不是衡量福祉的唯一指標。"},{"en":"Economists use GDP to compare the size or growth of economies.","zh":"經濟學家使用本地生產總值比較經濟規模或增長。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":8},{"front":"in the same period","meaning":"在同一時期","examples":[{"en":"Malaysia and Vietnam developed rapidly in the same period.","zh":"馬來西亞和越南在同一時期快速發展。"},{"en":"In the same period means during the same span of time already mentioned.","zh":"“In the same period” 指在前面已提及的同一段時間內。"},{"en":"The school hired more teachers in the same period that student numbers increased.","zh":"在學生人數增加的同一時期，學校聘請了更多老師。"},{"en":"House prices rose, but wages stayed almost flat in the same period.","zh":"樓價上升，但工資在同一時期幾乎持平。"},{"en":"This phrase helps compare two changes across one shared time range.","zh":"這個短語有助比較同一時間範圍內的兩種變化。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":8},{"front":"throw off colonialism","meaning":"擺脫殖民主義","examples":[{"en":"Malaysia and Vietnam threw off colonialism and surged ahead.","zh":"馬來西亞和越南擺脫殖民主義並快速前進。"},{"en":"To throw off colonialism means to escape or remove foreign colonial rule.","zh":"“Throw off colonialism” 指擺脫或解除外國殖民統治。"},{"en":"Many countries struggled for years to throw off colonialism.","zh":"許多國家多年奮鬥以擺脫殖民主義。"},{"en":"After throwing off colonialism, a country must build its own institutions.","zh":"擺脫殖民主義後，國家必須建立自己的制度。"},{"en":"The phrase suggests breaking free from outside control.","zh":"這個短語暗示從外部控制中解放出來。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":8},{"front":"surge ahead economically","meaning":"經濟上快速前進","examples":[{"en":"Malaysia and Vietnam surged ahead economically.","zh":"馬來西亞和越南在經濟上快速前進。"},{"en":"To surge ahead economically means to make fast and strong economic progress.","zh":"“Surge ahead economically” 指在經濟上取得快速而強勁的進步。"},{"en":"A city may surge ahead economically after building a major port.","zh":"城市在建造大型港口後可能在經濟上快速前進。"},{"en":"Countries can surge ahead economically when education, trade, and investment improve together.","zh":"當教育、貿易和投資一同改善，國家可以在經濟上快速前進。"},{"en":"The phrase suggests rapid movement forward, not slow growth.","zh":"這個短語暗示快速向前，而不是緩慢增長。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":8},{"front":"invest in education, health and infrastructure","meaning":"投資於教育、醫療和基礎建設","examples":[{"en":"Some countries developed by investing in education, health and infrastructure.","zh":"一些國家透過投資於教育、醫療和基礎建設而發展。"},{"en":"To invest in education, health and infrastructure means to spend resources on schools, healthcare, roads, power, and public systems.","zh":"“Invest in education, health and infrastructure” 指把資源投放於學校、醫療、道路、電力和公共系統。"},{"en":"A government may invest in education, health and infrastructure to improve long-term living standards.","zh":"政府可能投資於教育、醫療和基礎建設，以改善長期生活水平。"},{"en":"If a country invests in education, health and infrastructure, workers may become healthier and more productive.","zh":"如果一個國家投資於教育、醫療和基礎建設，工人可能變得更健康和更具生產力。"},{"en":"The phrase describes spending money now to create future development.","zh":"這個短語描述現在花錢以創造未來發展。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":8},{"front":"infrastructure","meaning":"基礎建設","examples":[{"en":"Good infrastructure can support economic growth.","zh":"良好的基礎建設可以支持經濟增長。"},{"en":"Infrastructure means the basic systems a society needs, such as roads, electricity, water, internet, and transport.","zh":"基礎建設指社會所需的基本系統，例如道路、電力、水、互聯網和交通。"},{"en":"A business needs reliable infrastructure to deliver goods on time.","zh":"企業需要可靠的基礎建設，才能準時運送貨物。"},{"en":"Poor infrastructure can make hospitals, schools, and markets harder to reach.","zh":"糟糕的基礎建設會令醫院、學校和市場更難到達。"},{"en":"The word often refers to practical foundations for daily life and development.","zh":"這個詞常指日常生活和發展所需的實際基礎。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":8},{"front":"lower taxes on","meaning":"降低對……的稅項","examples":[{"en":"Successful countries lowered taxes on international trade.","zh":"成功國家降低了對國際貿易的稅項。"},{"en":"To lower taxes on something means to reduce the amount of tax charged on it.","zh":"“Lower taxes on” 某事指減少對它徵收的稅款。"},{"en":"A government may lower taxes on small businesses to encourage hiring.","zh":"政府可能降低對小型企業的稅項，以鼓勵招聘。"},{"en":"Lowering taxes on basic food can help poor families afford daily meals.","zh":"降低對基本食物的稅項可以幫助貧窮家庭負擔日常膳食。"},{"en":"The phrase links tax reduction with a specific product, activity, or group.","zh":"這個短語把減稅與特定產品、活動或群體連繫起來。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":9},{"front":"international trade","meaning":"國際貿易","examples":[{"en":"Lower taxes on international trade can encourage development.","zh":"降低對國際貿易的稅項可以鼓勵發展。"},{"en":"International trade is the buying and selling of goods or services between countries.","zh":"國際貿易是國家之間買賣商品或服務。"},{"en":"International trade allows countries to sell products abroad and buy what they cannot produce cheaply.","zh":"國際貿易讓國家把產品賣到海外，並購買自己不能便宜生產的東西。"},{"en":"Poor ports and high border fees can make international trade difficult.","zh":"糟糕港口和高邊境費用會令國際貿易困難。"},{"en":"The phrase is central to discussions of exports, imports, and economic growth.","zh":"這個短語是出口、進口和經濟增長討論的核心。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":9},{"front":"be fortunate to","meaning":"有幸能夠……","examples":[{"en":"Some countries were fortunate to be surrounded by successful neighbours.","zh":"一些國家有幸被成功鄰國包圍。"},{"en":"To be fortunate to do something means to be lucky enough to have or experience it.","zh":"“Be fortunate to” 指幸運地擁有或經歷某事。"},{"en":"Students are fortunate to have teachers who give clear feedback.","zh":"學生有幸擁有給予清晰回饋的老師。"},{"en":"A village is fortunate to have a clinic nearby during emergencies.","zh":"村莊在緊急情況中有幸附近有診所。"},{"en":"The phrase expresses advantage or luck in a positive situation.","zh":"這個短語表達在正面情況中的優勢或幸運。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":9},{"front":"be surrounded by","meaning":"被……包圍","examples":[{"en":"Malaysia and Vietnam were surrounded by other successful nations.","zh":"馬來西亞和越南被其他成功國家包圍。"},{"en":"To be surrounded by something means to have it all around you or near you on many sides.","zh":"“Be surrounded by” 指周圍或多個方向附近都有某事物。"},{"en":"A school surrounded by parks gives students more space to play.","zh":"被公園包圍的學校給學生更多遊玩空間。"},{"en":"A business surrounded by good suppliers may find it easier to grow.","zh":"被良好供應商包圍的企業可能較容易增長。"},{"en":"The phrase can describe physical location or a wider environment.","zh":"這個短語可以描述實際位置或更廣泛環境。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":9},{"front":"successful nations","meaning":"成功國家","examples":[{"en":"Nearby successful nations may help a country develop.","zh":"附近的成功國家可能幫助一個國家發展。"},{"en":"Successful nations are countries that have achieved strong development, stability, or wealth.","zh":"成功國家是取得強勁發展、穩定或財富的國家。"},{"en":"Successful nations often have reliable institutions, education systems, and infrastructure.","zh":"成功國家通常有可靠制度、教育系統和基礎建設。"},{"en":"Small countries may learn from successful nations nearby.","zh":"小國可能向附近的成功國家學習。"},{"en":"The phrase usually refers to national achievement, not individual success.","zh":"這個短語通常指國家成就，而不是個人成功。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":9},{"front":"speculate that","meaning":"推測","examples":[{"en":"Paul Collier has speculated that cutting aid would not reduce corruption.","zh":"Paul Collier 推測削減援助不會減少貪污。"},{"en":"To speculate that something is true means to suggest it without complete proof.","zh":"“Speculate that” 指在沒有完整證據下提出某事可能為真。"},{"en":"Doctors may speculate that stress is causing a patient’s headaches before test results arrive.","zh":"在檢查結果到達前，醫生可能推測壓力導致病人頭痛。"},{"en":"Economists speculate that prices may fall if supply increases.","zh":"經濟學家推測如果供應增加，價格可能下跌。"},{"en":"The phrase signals uncertainty and careful guessing.","zh":"這個短語表示不確定和謹慎猜測。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":9},{"front":"alternative sources of income","meaning":"替代收入來源","examples":[{"en":"African governments might not find alternative sources of income.","zh":"非洲政府可能找不到替代收入來源。"},{"en":"Alternative sources of income are other ways to earn money when one source is reduced or lost.","zh":"替代收入來源是當一個收入來源減少或失去時，其他賺錢方法。"},{"en":"A family may need alternative sources of income if one parent loses a job.","zh":"如果一名家長失業，家庭可能需要替代收入來源。"},{"en":"A museum may create alternative sources of income through workshops and online tours.","zh":"博物館可能透過工作坊和網上導覽創造替代收入來源。"},{"en":"The phrase is useful when discussing financial security and replacement income.","zh":"這個短語適合討論財務安全和替代收入。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":9},{"front":"reduce corruption","meaning":"減少貪污","examples":[{"en":"Cutting aid may not reduce corruption.","zh":"削減援助未必能減少貪污。"},{"en":"To reduce corruption means to make dishonest use of power or money less common.","zh":"“Reduce corruption” 指令不誠實使用權力或金錢的情況較少發生。"},{"en":"Clear public records can help reduce corruption in government contracts.","zh":"清晰的公共紀錄可以幫助減少政府合約中的貪污。"},{"en":"Strong punishments may reduce corruption if laws are applied fairly.","zh":"如果法律公平執行，嚴厲懲罰可能減少貪污。"},{"en":"The phrase focuses on lowering the level of corruption, not removing it completely.","zh":"這個短語強調降低貪污水平，而不是完全消除。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":9},{"front":"calculate that","meaning":"計算出","examples":[{"en":"Jeffrey Sachs has calculated that more aid is needed.","zh":"Jeffrey Sachs 計算出需要更多援助。"},{"en":"To calculate that something is true means to reach a conclusion by using numbers or data.","zh":"“Calculate that” 指透過數字或數據得出某個結論。"},{"en":"The engineer calculated that the bridge could carry 500 cars safely.","zh":"工程師計算出橋樑可以安全承載500輛汽車。"},{"en":"A family may calculate that moving closer to work will save money on transport.","zh":"家庭可能計算出搬近工作地點可節省交通費。"},{"en":"The phrase suggests a result based on measurement, not just opinion.","zh":"這個短語暗示結果基於量度，而不只是意見。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":9},{"front":"twice the amount of aid","meaning":"現時援助額的兩倍","examples":[{"en":"Twice the amount of aid currently given may be needed.","zh":"可能需要目前援助額的兩倍。"},{"en":"Twice the amount of aid means double the present level of help.","zh":"“Twice the amount of aid” 指現有幫助水平的兩倍。"},{"en":"If a shelter receives twice the amount of aid, it can serve more homeless people.","zh":"如果庇護所收到兩倍援助，它可以服務更多無家者。"},{"en":"A school may need twice the amount of aid after a storm destroys classrooms.","zh":"風暴摧毀課室後，學校可能需要兩倍援助。"},{"en":"The phrase compares a needed amount with the current amount.","zh":"這個短語把所需數量與目前數量作比較。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":9},{"front":"currently given","meaning":"目前給予的","examples":[{"en":"The aid currently given may not be enough.","zh":"目前給予的援助可能不足夠。"},{"en":"Currently given means being provided at the present time.","zh":"“Currently given” 指現時正在提供的。"},{"en":"The support currently given to new teachers may not be enough for difficult classes.","zh":"目前給予新老師的支援可能不足以應付困難班級。"},{"en":"If the medicine currently given does not work, doctors may try another treatment.","zh":"如果目前給予的藥物無效，醫生可能嘗試另一種治療。"},{"en":"The phrase focuses on what is happening now, not in the past or future.","zh":"這個短語強調現在正在發生的事，而不是過去或未來。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":9},{"front":"prevent suffering on a grand scale","meaning":"防止大規模苦難","examples":[{"en":"Sachs says more aid is needed to prevent suffering on a grand scale.","zh":"Sachs 說需要更多援助以防止大規模苦難。"},{"en":"To prevent suffering on a grand scale means to stop very large numbers of people from experiencing serious hardship.","zh":"“Prevent suffering on a grand scale” 指阻止大量人口經歷嚴重困苦。"},{"en":"Vaccination programmes can prevent suffering on a grand scale during disease outbreaks.","zh":"疫苗計劃可以在疾病爆發期間防止大規模苦難。"},{"en":"Early flood warnings may prevent suffering on a grand scale by helping people leave dangerous areas.","zh":"早期洪水警報可以幫助人們離開危險地區，從而防止大規模苦難。"},{"en":"The phrase is used for major human problems, not small daily difficulties.","zh":"這個短語用於重大人道問題，而不是日常小困難。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":10},{"front":"on a grand scale","meaning":"大規模地","examples":[{"en":"Without aid, suffering could occur on a grand scale.","zh":"沒有援助，苦難可能大規模地發生。"},{"en":"On a grand scale means happening in a very large or widespread way.","zh":"“On a grand scale” 指以非常大或廣泛的方式發生。"},{"en":"The city built housing on a grand scale to reduce overcrowding.","zh":"該城市大規模地興建房屋，以減少過度擠迫。"},{"en":"Pollution on a grand scale can damage rivers, farms, and public health.","zh":"大規模污染可以破壞河流、農田和公共健康。"},{"en":"The phrase adds a sense of size, seriousness, or ambition.","zh":"這個短語增加規模、嚴重性或雄心的感覺。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":10},{"front":"present her case through","meaning":"透過……提出她的論據","examples":[{"en":"Moyo presents her case through a fictitious country.","zh":"Moyo 透過一個虛構國家提出她的論據。"},{"en":"To present a case through something means to explain an argument by using that method or example.","zh":"“Present a case through” 某事指透過某種方法或例子解釋論點。"},{"en":"A teacher may present her case through a simple classroom story.","zh":"老師可能透過一個簡單課堂故事提出她的論據。"},{"en":"A lawyer presents a case through documents, witnesses, and evidence.","zh":"律師透過文件、證人和證據提出案件論據。"},{"en":"The phrase shows the method used to make an argument clearer.","zh":"這個短語顯示用來令論點更清晰的方法。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":10},{"front":"fictitious country","meaning":"虛構國家","examples":[{"en":"Moyo uses a fictitious country called Dongo.","zh":"Moyo 使用一個名為 Dongo 的虛構國家。"},{"en":"A fictitious country is an invented country that does not exist in real life.","zh":"虛構國家是現實中不存在、被創作出來的國家。"},{"en":"A novelist may create a fictitious country to explore political problems safely.","zh":"小說家可能創造一個虛構國家，以安全地探討政治問題。"},{"en":"Teachers sometimes use a fictitious country so students can discuss policy without bias.","zh":"老師有時使用虛構國家，讓學生無偏見地討論政策。"},{"en":"The phrase signals that the example is imaginary, not historical fact.","zh":"這個短語表示例子是想像的，而不是歷史事實。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":10},{"front":"nowhere does she provide","meaning":"她完全沒有提供……","examples":[{"en":"Nowhere does she provide examples of real aid organisations causing actual problems.","zh":"她完全沒有提供真實援助組織造成實際問題的例子。"},{"en":"“Nowhere does she provide” means she does not provide something anywhere in her work.","zh":"“Nowhere does she provide” 指她在作品任何地方都沒有提供某事。"},{"en":"Nowhere does the report provide evidence that the school broke the rules.","zh":"該報告完全沒有提供學校違規的證據。"},{"en":"Nowhere does the article explain how the figures were collected.","zh":"該文章完全沒有解釋數字如何收集。"},{"en":"This inverted structure sounds formal and emphasises complete absence.","zh":"這個倒裝結構較正式，並強調完全缺乏。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":10},{"front":"real aid organisations","meaning":"真實援助組織","examples":[{"en":"The book does not provide examples of real aid organisations causing problems.","zh":"這本書沒有提供真實援助組織造成問題的例子。"},{"en":"Real aid organisations are actual groups that provide aid, not imagined examples.","zh":"真實援助組織是實際提供援助的團體，而不是想像例子。"},{"en":"Real aid organisations may include charities, development agencies, and medical groups.","zh":"真實援助組織可能包括慈善機構、發展機構和醫療團體。"},{"en":"If an argument names real aid organisations, readers can check the evidence more easily.","zh":"如果論點點名真實援助組織，讀者較容易查證證據。"},{"en":"The phrase contrasts with fictional or general examples.","zh":"這個短語與虛構或籠統例子形成對比。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":10},{"front":"actual problems","meaning":"實際問題","examples":[{"en":"Critics say Moyo gives no real examples of actual problems.","zh":"批評者說 Moyo 沒有給出實際問題的真實例子。"},{"en":"Actual problems are real difficulties that have happened, not imagined or theoretical ones.","zh":"實際問題是已發生的真實困難，而不是想像或理論上的困難。"},{"en":"A teacher should discuss actual problems students face, such as time pressure and unclear instructions.","zh":"老師應討論學生面對的實際問題，例如時間壓力和指示不清。"},{"en":"If a policy creates actual problems, people will notice delays, costs, or harm.","zh":"如果政策造成實際問題，人們會注意到延誤、成本或傷害。"},{"en":"The phrase stresses real-world evidence.","zh":"這個短語強調現實世界證據。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":10},{"front":"her approach","meaning":"她的方法","examples":[{"en":"Her approach may be entertaining, but it is hardly academic.","zh":"她的方法可能有趣，但不太學術。"},{"en":"Her approach means the method or style she uses to explain her ideas.","zh":"“Her approach” 指她用來解釋想法的方法或風格。"},{"en":"A teacher’s approach may be strict, friendly, practical, or exam-focused.","zh":"老師的方法可能嚴格、友善、實用或以考試為本。"},{"en":"If her approach relies on stories but not evidence, scholars may criticise it.","zh":"如果她的方法依賴故事而不是證據，學者可能批評它。"},{"en":"The phrase points to how someone handles a topic.","zh":"這個短語指某人處理題目的方式。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":10},{"front":"entertaining but hardly academic","meaning":"有趣但不太學術","examples":[{"en":"Moyo’s approach may be entertaining but hardly academic.","zh":"Moyo 的方法可能有趣但不太學術。"},{"en":"Entertaining but hardly academic means interesting to read but not very scholarly or evidence-based.","zh":"“Entertaining but hardly academic” 指讀起來有趣，但不太具學術性或證據基礎。"},{"en":"A video full of jokes may be entertaining but hardly academic if it gives no sources.","zh":"如果影片充滿笑話但沒有資料來源，它可能有趣但不太學術。"},{"en":"A popular book can be entertaining but hardly academic when it simplifies complex research too much.","zh":"當暢銷書過度簡化複雜研究時，它可能有趣但不太學術。"},{"en":"The phrase contrasts enjoyment with serious academic quality.","zh":"這個短語把趣味與嚴肅學術質素作對比。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":10},{"front":"other scholars point out that","meaning":"其他學者指出","examples":[{"en":"Other scholars point out that Africa has deep political problems.","zh":"其他學者指出非洲有深層政治問題。"},{"en":"“Other scholars point out that” introduces an observation or argument made by different experts.","zh":"“Other scholars point out that” 用來引出其他專家的觀察或論點。"},{"en":"Other scholars point out that poverty is linked to housing, health, and education.","zh":"其他學者指出貧窮與住屋、健康和教育有關。"},{"en":"Other scholars point out that test scores do not measure creativity.","zh":"其他學者指出考試分數不能衡量創意。"},{"en":"The phrase is useful when adding another academic viewpoint.","zh":"這個短語適合用來加入另一個學術觀點。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":10},{"front":"be dominated by","meaning":"受……主導","examples":[{"en":"Africa is dominated by tribal societies with powerful elites.","zh":"非洲受擁有強大精英的部族社會主導。"},{"en":"To be dominated by something means to be strongly controlled or influenced by it.","zh":"“Be dominated by” 指受到某事物強烈控制或影響。"},{"en":"A market dominated by one company may offer customers fewer choices.","zh":"由一間公司主導的市場可能給顧客較少選擇。"},{"en":"If a school is dominated by exam pressure, students may lose interest in learning.","zh":"如果學校受考試壓力主導，學生可能失去學習興趣。"},{"en":"The phrase shows that one force has more power than others.","zh":"這個短語顯示一種力量比其他力量更有權勢。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":10},{"front":"tribal societies","meaning":"部族社會","examples":[{"en":"Africa is described as being dominated by tribal societies.","zh":"非洲被描述為受部族社會主導。"},{"en":"Tribal societies are communities organised around tribes, kinship, shared identity, or traditional authority.","zh":"部族社會是圍繞部族、親屬關係、共同身份或傳統權威組織起來的社區。"},{"en":"Tribal societies may have strong loyalty to family groups and local leaders.","zh":"部族社會可能對家族群體和本地領袖有強烈忠誠。"},{"en":"In some places, tribal societies influence voting, land use, and conflict.","zh":"在一些地方，部族社會影響投票、土地使用和衝突。"},{"en":"The phrase should be used carefully because societies can be complex and diverse.","zh":"這個短語應謹慎使用，因為社會可以複雜而多元。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":11},{"front":"military and government elites","meaning":"軍方和政府精英","examples":[{"en":"Military and government elites control much of the economy.","zh":"軍方和政府精英控制大部分經濟。"},{"en":"Military and government elites are powerful people in the army and political system.","zh":"軍方和政府精英是在軍隊和政治制度中的有權勢人士。"},{"en":"Military and government elites may control contracts, land, licences, or public money.","zh":"軍方和政府精英可能控制合約、土地、牌照或公款。"},{"en":"If military and government elites dominate the economy, ordinary businesses may struggle.","zh":"如果軍方和政府精英主導經濟，普通企業可能難以生存。"},{"en":"The phrase points to a small powerful group, not the general public.","zh":"這個短語指一小撮有權勢群體，而不是一般公眾。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":11},{"front":"joining the army","meaning":"參軍","examples":[{"en":"Joining the army was a route to wealth and power.","zh":"參軍曾是通往財富和權力的途徑。"},{"en":"Joining the army means becoming a member of the military forces.","zh":"“Joining the army” 指成為軍隊成員。"},{"en":"Some young people consider joining the army for training, income, or discipline.","zh":"一些年輕人考慮參軍，以獲得訓練、收入或紀律。"},{"en":"In unstable countries, joining the army may bring political influence as well as danger.","zh":"在不穩定國家，參軍可能帶來政治影響力，也帶來危險。"},{"en":"The phrase describes entering military service.","zh":"這個短語描述加入軍事服務。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":11},{"front":"rather than doing business","meaning":"而不是做生意","examples":[{"en":"Joining the army, rather than doing business, could bring wealth.","zh":"參軍，而不是做生意，可能帶來財富。"},{"en":"Rather than doing business means instead of building or running commercial activity.","zh":"“Rather than doing business” 指不是建立或經營商業活動。"},{"en":"Some graduates choose public service rather than doing business.","zh":"一些畢業生選擇公共服務，而不是做生意。"},{"en":"If power comes from politics rather than doing business, entrepreneurship may weaken.","zh":"如果權力來自政治而不是做生意，創業精神可能削弱。"},{"en":"The phrase clearly contrasts two possible paths.","zh":"這個短語清楚對比兩條可能道路。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":11},{"front":"the easiest route to","meaning":"通往……最容易的途徑","examples":[{"en":"Joining the army was the easiest route to personal wealth.","zh":"參軍曾是通往個人財富最容易的途徑。"},{"en":"The easiest route to something means the simplest or quickest way to reach it.","zh":"“The easiest route to” 某事指達到它最簡單或最快的方法。"},{"en":"For some students, daily practice is the easiest route to better pronunciation.","zh":"對一些學生來說，每日練習是通往更好發音最容易的途徑。"},{"en":"The easiest route to trust is honest communication over time.","zh":"通往信任最容易的途徑是長期誠實溝通。"},{"en":"The phrase can describe a path to success, power, money, or improvement.","zh":"這個短語可以描述通往成功、權力、金錢或改善的道路。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":11},{"front":"personal wealth and power","meaning":"個人財富和權力","examples":[{"en":"The army offered a route to personal wealth and power.","zh":"軍隊提供了一條通往個人財富和權力的途徑。"},{"en":"Personal wealth and power means money, influence, and control gained by an individual.","zh":"個人財富和權力指個人獲得的金錢、影響力和控制力。"},{"en":"Some leaders use public office to gain personal wealth and power.","zh":"一些領袖利用公職獲取個人財富和權力。"},{"en":"When personal wealth and power matter more than public service, corruption may grow.","zh":"當個人財富和權力比公共服務更重要，貪污可能滋長。"},{"en":"The phrase often has a negative meaning in political contexts.","zh":"這個短語在政治語境中常有負面含義。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":11},{"front":"unsurprisingly","meaning":"不出所料","examples":[{"en":"Unsurprisingly, military takeovers occurred in many African countries.","zh":"不出所料，軍事政變在許多非洲國家發生。"},{"en":"Unsurprisingly means something is not surprising because the situation already suggested it would happen.","zh":"“Unsurprisingly” 指某事不令人驚訝，因為情況已暗示它會發生。"},{"en":"The team did not practise; unsurprisingly, they lost the match.","zh":"球隊沒有練習；不出所料，他們輸了比賽。"},{"en":"The bus was delayed by heavy traffic; unsurprisingly, many passengers arrived late.","zh":"巴士因嚴重交通擠塞而延誤；不出所料，許多乘客遲到。"},{"en":"The word links a result to an expected cause.","zh":"這個詞把結果與預期原因連繫起來。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":11},{"front":"occur in","meaning":"在……發生","examples":[{"en":"Military takeovers have occurred in almost every African country.","zh":"軍事政變幾乎在每個非洲國家發生過。"},{"en":"To occur in a place means to happen there.","zh":"“Occur in” 某地指在該地發生。"},{"en":"Floods often occur in low-lying areas after heavy rain.","zh":"大雨後，洪水常在低窪地區發生。"},{"en":"Mistakes may occur in exams when students rush their answers.","zh":"當學生匆忙作答時，錯誤可能在考試中發生。"},{"en":"The phrase is more formal than “happen in”.","zh":"這個短語比 “happen in” 更正式。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":11},{"front":"European colonials","meaning":"歐洲殖民者","examples":[{"en":"European colonials were replaced by African generals.","zh":"歐洲殖民者被非洲將軍取代。"},{"en":"European colonials were Europeans who ruled, settled in, or controlled colonised places.","zh":"歐洲殖民者是統治、定居或控制被殖民地的歐洲人。"},{"en":"European colonials often controlled land, laws, and trade during colonial periods.","zh":"在殖民時期，歐洲殖民者常控制土地、法律和貿易。"},{"en":"After independence, European colonials left many countries they had governed.","zh":"獨立後，歐洲殖民者離開許多他們曾管治的國家。"},{"en":"The phrase refers to colonial rulers or settlers, not all Europeans.","zh":"這個短語指殖民統治者或定居者，而不是所有歐洲人。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":11},{"front":"be replaced by","meaning":"被……取代","examples":[{"en":"European colonials were replaced by African colonials.","zh":"歐洲殖民者被非洲殖民者取代。"},{"en":"To be replaced by someone or something means to have another person or thing take your place.","zh":"“Be replaced by” 指由另一個人或事物接替位置。"},{"en":"Old textbooks were replaced by digital materials.","zh":"舊教科書被數碼教材取代。"},{"en":"If a teacher leaves, she may be replaced by a temporary teacher.","zh":"如果老師離職，她可能被臨時老師取代。"},{"en":"The phrase shows that one thing ends and another takes over its role.","zh":"這個短語顯示一件事結束，另一件事接管其角色。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":11},{"front":"African generals","meaning":"非洲將軍","examples":[{"en":"African generals and their families gained power.","zh":"非洲將軍及其家族獲得權力。"},{"en":"African generals are high-ranking military leaders from African countries.","zh":"非洲將軍是來自非洲國家的高級軍事領袖。"},{"en":"African generals may control armies, security forces, or political decisions.","zh":"非洲將軍可能控制軍隊、安全部隊或政治決策。"},{"en":"If African generals take power by force, civilian government may weaken.","zh":"如果非洲將軍以武力奪權，文人政府可能削弱。"},{"en":"The phrase identifies military leaders by both region and rank.","zh":"這個短語同時以地區和軍階識別軍事領袖。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":11},{"front":"meanwhile","meaning":"與此同時","examples":[{"en":"Meanwhile, the educated bourgeoisie moved abroad.","zh":"與此同時，受過教育的中產階級移居海外。"},{"en":"Meanwhile means at the same time or during the same period.","zh":"“Meanwhile” 指同時或在同一時期。"},{"en":"The children did homework; meanwhile, their parents prepared dinner.","zh":"孩子做功課；與此同時，父母準備晚餐。"},{"en":"The company expanded online; meanwhile, its shops became less busy.","zh":"公司擴展網上業務；與此同時，其店舖變得較少人光顧。"},{"en":"The word helps connect two events happening alongside each other.","zh":"這個詞有助連接同時發生的兩件事。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":12},{"front":"educated bourgeoisie","meaning":"受過教育的中產階級","examples":[{"en":"The very small, educated bourgeoisie has moved abroad.","zh":"非常少數的受過教育的中產階級已移居海外。"},{"en":"The educated bourgeoisie refers to the educated middle class, especially people with professional skills and social influence.","zh":"“Educated bourgeoisie” 指受過教育的中產階級，尤其有專業技能和社會影響力的人。"},{"en":"An educated bourgeoisie may include teachers, doctors, lawyers, managers, and business owners.","zh":"受過教育的中產階級可能包括教師、醫生、律師、經理和企業主。"},{"en":"If the educated bourgeoisie leaves a country, local institutions may lose important skills.","zh":"如果受過教育的中產階級離開一個國家，本地制度可能失去重要技能。"},{"en":"The phrase is formal and often used in social or political analysis.","zh":"這個短語較正式，常用於社會或政治分析。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":12},{"front":"move abroad","meaning":"移居海外","examples":[{"en":"Many educated Africans have moved abroad.","zh":"許多受過教育的非洲人已移居海外。"},{"en":"To move abroad means to leave one’s own country and live in another country.","zh":"“Move abroad” 指離開自己的國家，到另一個國家生活。"},{"en":"A student may move abroad for university and later find work there.","zh":"學生可能為了大學移居海外，之後在當地找工作。"},{"en":"People often move abroad for safety, education, higher wages, or family reasons.","zh":"人們常因安全、教育、較高工資或家庭原因移居海外。"},{"en":"The phrase describes relocation across national borders.","zh":"這個短語描述跨越國界搬遷。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":12},{"front":"strongmen leaders","meaning":"強人領袖","examples":[{"en":"Strongmen leaders have ruled for a long time.","zh":"強人領袖已長期統治。"},{"en":"Strongmen leaders are powerful rulers who keep control through force, fear, or personal authority.","zh":"強人領袖是透過武力、恐懼或個人權威維持控制的有權勢統治者。"},{"en":"Strongmen leaders may weaken courts, media, and elections to stay in power.","zh":"強人領袖可能削弱法院、媒體和選舉以留在權力位置。"},{"en":"When strongmen leaders dominate politics, peaceful change becomes difficult.","zh":"當強人領袖主導政治，和平改變會變得困難。"},{"en":"The phrase is usually negative and suggests authoritarian rule.","zh":"這個短語通常帶負面意思，暗示威權統治。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":12},{"front":"rule for a long time","meaning":"長期統治","examples":[{"en":"Strongmen leaders have ruled for a long time in some countries.","zh":"強人領袖在一些國家長期統治。"},{"en":"To rule for a long time means to stay in power over many years.","zh":"“Rule for a long time” 指多年留在權力位置。"},{"en":"A king may rule for a long time if the political system allows it.","zh":"如果政治制度容許，國王可能長期統治。"},{"en":"If one leader rules for a long time without checks, corruption may grow.","zh":"如果一名領袖在沒有制衡下長期統治，貪污可能滋長。"},{"en":"The phrase focuses on the length of political control.","zh":"這個短語強調政治控制的時間長度。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":12},{"front":"unstable military regime","meaning":"不穩定的軍事政權","examples":[{"en":"One unstable military regime has often succeeded another.","zh":"一個不穩定的軍事政權往往接替另一個。"},{"en":"An unstable military regime is a government controlled by the army but lacking security, order, or public trust.","zh":"不穩定的軍事政權是由軍隊控制但缺乏安全、秩序或公眾信任的政府。"},{"en":"An unstable military regime may change laws suddenly and frighten investors.","zh":"不穩定的軍事政權可能突然改變法律並嚇怕投資者。"},{"en":"People may leave a country when an unstable military regime creates violence or uncertainty.","zh":"當不穩定的軍事政權造成暴力或不確定性，人們可能離開該國。"},{"en":"The phrase combines military rule with political weakness.","zh":"這個短語結合軍事統治和政治薄弱。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":12},{"front":"succeed another","meaning":"接替另一個","examples":[{"en":"One military regime may succeed another.","zh":"一個軍事政權可能接替另一個。"},{"en":"To succeed another means to come after it and take its place.","zh":"“Succeed another” 指在其後出現並取代其位置。"},{"en":"A new manager may succeed another manager after retirement.","zh":"新經理可能在另一名經理退休後接替他。"},{"en":"If one crisis succeeds another, people have little time to recover.","zh":"如果一場危機接替另一場，人們幾乎沒有時間恢復。"},{"en":"This formal verb means “follow”, not “achieve success”, in this context.","zh":"在這個語境中，這個正式動詞解作「接續」，不是「成功」。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":12},{"front":"as a result","meaning":"結果","examples":[{"en":"As a result, independent business is rare.","zh":"結果，獨立商業很少見。"},{"en":"As a result means because of what was just mentioned.","zh":"“As a result” 指由於剛才提到的事情。"},{"en":"The road was closed; as a result, many workers arrived late.","zh":"道路封閉；結果，許多工人遲到。"},{"en":"The company improved training; as a result, customer complaints fell.","zh":"公司改善培訓；結果，顧客投訴減少。"},{"en":"The phrase introduces a consequence.","zh":"這個短語用來引出後果。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":12},{"front":"separate from","meaning":"與……分開","examples":[{"en":"Business separate from the military government is rare.","zh":"與軍政府分開的商業很少見。"},{"en":"Separate from means not connected to or controlled by something else.","zh":"“Separate from” 指不與某事相連或不受其控制。"},{"en":"Students need a study area separate from their sleeping area.","zh":"學生需要一個與睡眠區分開的學習區。"},{"en":"A charity should keep its accounts separate from a founder’s personal money.","zh":"慈善機構應把帳目與創辦人的私人金錢分開。"},{"en":"The phrase shows independence or clear division.","zh":"這個短語表示獨立或清晰分隔。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":12},{"front":"international investment","meaning":"國際投資","examples":[{"en":"International investment is limited in many African economies.","zh":"在許多非洲經濟體中，國際投資受限制。"},{"en":"International investment is money put into businesses, projects, or markets in another country.","zh":"國際投資是把金錢投入另一個國家的企業、項目或市場。"},{"en":"International investment can help build factories, roads, hotels, and technology companies.","zh":"國際投資可以幫助建造工廠、道路、酒店和科技公司。"},{"en":"Political instability may reduce international investment because investors fear losses.","zh":"政治不穩可能減少國際投資，因為投資者害怕損失。"},{"en":"The phrase refers to cross-border financial support or business activity.","zh":"這個短語指跨境財政支持或商業活動。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":12},{"front":"be limited","meaning":"受限制","examples":[{"en":"International investment is limited.","zh":"國際投資受限制。"},{"en":"To be limited means to be restricted, small in amount, or not widely available.","zh":"“Be limited” 指受限制、數量少或不廣泛可得。"},{"en":"Seats are limited, so students must register early.","zh":"座位有限，所以學生必須及早登記。"},{"en":"If internet access is limited, online learning becomes difficult.","zh":"如果互聯網使用受限制，網上學習會變得困難。"},{"en":"The phrase shows that something is not enough or not freely available.","zh":"這個短語顯示某事不足夠或不能自由取得。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":12},{"front":"post-secondary education rates","meaning":"專上教育率","examples":[{"en":"Post-secondary education rates are low in Africa.","zh":"非洲的專上教育率偏低。"},{"en":"Post-secondary education rates show how many people continue studying after secondary school.","zh":"專上教育率顯示有多少人在中學後繼續升學。"},{"en":"A country with high post-secondary education rates may have more trained workers.","zh":"專上教育率高的國家可能有更多受訓工人。"},{"en":"Low post-secondary education rates can limit the number of nurses, engineers, and teachers.","zh":"專上教育率低會限制護士、工程師和教師的數量。"},{"en":"The phrase is useful in discussions of skills and development.","zh":"這個短語適合用於技能和發展的討論。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":13},{"front":"communications and transportation","meaning":"通訊和交通","examples":[{"en":"Communications and transportation remain basic.","zh":"通訊和交通仍然落後。"},{"en":"Communications and transportation are systems for sending information and moving people or goods.","zh":"通訊和交通是傳送資訊以及移動人員或貨物的系統。"},{"en":"Communications include phones and internet, while transportation includes roads, buses, trains, and ports.","zh":"通訊包括電話和互聯網，而交通包括道路、巴士、火車和港口。"},{"en":"Weak communications and transportation make business, education, and healthcare harder.","zh":"薄弱的通訊和交通令商業、教育和醫療更困難。"},{"en":"The phrase covers two important forms of connection.","zh":"這個短語涵蓋兩種重要連接形式。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":13},{"front":"remain basic","meaning":"仍然落後；仍然基礎","examples":[{"en":"Transportation systems remain basic in many areas.","zh":"許多地區的交通系統仍然落後。"},{"en":"To remain basic means to continue being simple, limited, or underdeveloped.","zh":"“Remain basic” 指繼續保持簡單、有限或發展不足。"},{"en":"Internet service remains basic in the village, so video calls often fail.","zh":"村莊的互聯網服務仍然基礎，所以視像通話常常失敗。"},{"en":"If hospital equipment remains basic, doctors cannot perform complex operations.","zh":"如果醫院設備仍然落後，醫生不能進行複雜手術。"},{"en":"The phrase suggests that improvement has been slow or insufficient.","zh":"這個短語暗示改善緩慢或不足。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":13},{"front":"have an impact","meaning":"產生影響","examples":[{"en":"Mobile phones are having an impact.","zh":"手機正在產生影響。"},{"en":"To have an impact means to affect someone or something in a noticeable way.","zh":"“Have an impact” 指以明顯方式影響某人或某事。"},{"en":"A kind teacher can have an impact on a student’s confidence.","zh":"一位善良老師可以對學生信心產生影響。"},{"en":"Rising prices have an impact on how families spend money.","zh":"物價上升會對家庭如何花錢產生影響。"},{"en":"The phrase can describe positive or negative effects.","zh":"這個短語可以描述正面或負面影響。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":13},{"front":"distances farmers must travel","meaning":"農民必須前往市場的距離","examples":[{"en":"The distances farmers must travel to market are vast.","zh":"農民必須前往市場的距離非常遙遠。"},{"en":"Distances farmers must travel means how far farmers need to go to sell goods or buy supplies.","zh":"“Distances farmers must travel” 指農民為出售貨物或購買物資而需要走的距離。"},{"en":"The distances farmers must travel can affect the freshness and price of their crops.","zh":"農民必須前往市場的距離會影響農作物的新鮮度和價格。"},{"en":"If roads are poor, even short distances farmers must travel may take many hours.","zh":"如果道路惡劣，即使農民必須前往的距離很短，也可能花上很多小時。"},{"en":"The phrase highlights a practical barrier in rural trade.","zh":"這個短語強調農村貿易中的實際障礙。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":13},{"front":"travel to market","meaning":"前往市場","examples":[{"en":"Farmers often travel long distances to market.","zh":"農民經常長途前往市場。"},{"en":"To travel to market means to go to a place where goods can be sold or bought.","zh":"“Travel to market” 指前往可以買賣貨品的地方。"},{"en":"A farmer may travel to market early in the morning to sell vegetables.","zh":"農民可能清晨前往市場售賣蔬菜。"},{"en":"If transport is expensive, travelling to market can reduce a farmer’s profit.","zh":"如果交通昂貴，前往市場會減少農民利潤。"},{"en":"The phrase is common in discussions of agriculture and trade.","zh":"這個短語常見於農業和貿易討論。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":13},{"front":"vast due to","meaning":"因……而非常遙遠","examples":[{"en":"The distances are vast due to poor roads.","zh":"這些距離因惡劣道路而非常遙遠。"},{"en":"Vast due to something means extremely large or great because of that cause.","zh":"“Vast due to” 某原因指因該原因而極大或極廣。"},{"en":"The delay was vast due to repeated system failures.","zh":"延誤因反覆系統故障而非常嚴重。"},{"en":"Travel time can become vast due to traffic, bad roads, or missing bridges.","zh":"交通擠塞、惡劣道路或橋樑缺失會令行程時間變得非常長。"},{"en":"The phrase connects a very large problem with its reason.","zh":"這個短語把非常大的問題與其原因連繫起來。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":13},{"front":"poor roads","meaning":"惡劣道路","examples":[{"en":"Poor roads make trade difficult.","zh":"惡劣道路令貿易困難。"},{"en":"Poor roads are roads in bad condition, often rough, broken, unsafe, or hard to use.","zh":"惡劣道路是狀況差的道路，通常崎嶇、破損、不安全或難以使用。"},{"en":"Poor roads can damage vehicles and delay deliveries.","zh":"惡劣道路可以損壞車輛並延誤送貨。"},{"en":"If villages have poor roads, children may struggle to reach school during rain.","zh":"如果村莊有惡劣道路，孩子在雨天可能難以上學。"},{"en":"The phrase is often used when discussing infrastructure problems.","zh":"這個短語常用於討論基礎建設問題。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":13},{"front":"cross-border taxes","meaning":"跨境稅項","examples":[{"en":"High cross-border taxes slow trade.","zh":"高跨境稅項拖慢貿易。"},{"en":"Cross-border taxes are charges placed on goods or services moving between countries.","zh":"跨境稅項是對國家之間流動的商品或服務徵收的費用。"},{"en":"Cross-border taxes can make imported food, clothes, or tools more expensive.","zh":"跨境稅項可以令進口食物、衣服或工具更昂貴。"},{"en":"If cross-border taxes are too high, small traders may stop selling abroad.","zh":"如果跨境稅項太高，小商人可能停止海外銷售。"},{"en":"The phrase is linked to trade barriers and international business.","zh":"這個短語與貿易壁壘和國際商業有關。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":13},{"front":"bureaucratic delays","meaning":"官僚程序延誤","examples":[{"en":"Long bureaucratic delays are common.","zh":"漫長的官僚程序延誤很常見。"},{"en":"Bureaucratic delays are slowdowns caused by official rules, forms, approvals, or departments.","zh":"官僚程序延誤是由官方規則、表格、批准或部門造成的拖延。"},{"en":"A family may face bureaucratic delays when applying for housing support.","zh":"家庭申請住屋支援時，可能面對官僚程序延誤。"},{"en":"Bureaucratic delays can stop businesses from opening on time.","zh":"官僚程序延誤可以阻止企業準時開業。"},{"en":"The phrase often suggests frustration with slow administration.","zh":"這個短語常暗示對緩慢行政的挫敗感。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":13},{"front":"par for the course","meaning":"司空見慣；意料之中","examples":[{"en":"High taxes and delays are par for the course.","zh":"高稅項和延誤是司空見慣的。"},{"en":"Par for the course means normal, expected, or unsurprising in a particular situation.","zh":"“Par for the course” 指在某情況下屬正常、預期或不令人驚訝。"},{"en":"Long queues are par for the course at popular restaurants on weekends.","zh":"週末在受歡迎餐廳排長隊是司空見慣的。"},{"en":"For new teachers, feeling nervous before the first lesson is par for the course.","zh":"對新老師來說，第一堂課前感到緊張是意料之中的。"},{"en":"The phrase often suggests something unpleasant but expected.","zh":"這個短語常暗示某事令人不快但在預期之內。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":13},{"front":"rural populations","meaning":"農村人口","examples":[{"en":"African rural populations exceed those elsewhere.","zh":"非洲農村人口超過其他地方。"},{"en":"Rural populations are people living in the countryside rather than towns or cities.","zh":"農村人口是居住在鄉郊而不是城鎮或城市的人。"},{"en":"Rural populations may depend more on farming, local markets, and long-distance transport.","zh":"農村人口可能更依賴農業、本地市場和長途交通。"},{"en":"If rural populations are large, governments must provide schools and clinics across wide areas.","zh":"如果農村人口龐大，政府必須在廣闊地區提供學校和診所。"},{"en":"The phrase is useful when comparing countryside and urban living.","zh":"這個短語適合比較鄉郊和城市生活。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":14},{"front":"exceed those elsewhere","meaning":"超過其他地方的……","examples":[{"en":"African rural populations exceed those elsewhere in the world.","zh":"非洲農村人口超過世界其他地方的農村人口。"},{"en":"To exceed those elsewhere means to be greater than the same figures in other places.","zh":"“Exceed those elsewhere” 指比其他地方的同類數字更高。"},{"en":"The city’s housing costs exceed those elsewhere in the region.","zh":"該城市的住屋成本超過該地區其他地方的住屋成本。"},{"en":"If local exam results exceed those elsewhere, other schools may study its methods.","zh":"如果本地考試成績超過其他地方，其他學校可能研究其方法。"},{"en":"The phrase compares one place’s figures with other places’ figures.","zh":"這個短語把一個地方的數字與其他地方的數字作比較。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":14},{"front":"decent infrastructure","meaning":"像樣的基礎建設","examples":[{"en":"Without decent infrastructure, business cannot prosper.","zh":"沒有像樣的基礎建設，生意無法興旺。"},{"en":"Decent infrastructure means reasonably good roads, power, water, internet, and transport systems.","zh":"像樣的基礎建設指相當良好的道路、電力、水、互聯網和交通系統。"},{"en":"A town with decent infrastructure can attract shops, clinics, and factories.","zh":"擁有像樣基礎建設的城鎮可以吸引商店、診所和工廠。"},{"en":"Without decent infrastructure, students may struggle to reach school and businesses may lose goods.","zh":"沒有像樣的基礎建設，學生可能難以上學，企業可能損失貨物。"},{"en":"The phrase does not mean perfect systems, but good enough systems.","zh":"這個短語不是指完美系統，而是指足夠好的系統。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":14},{"front":"educated urbanised workforce","meaning":"受過教育的城市化勞動人口","examples":[{"en":"A business needs an educated urbanised workforce.","zh":"企業需要受過教育的城市化勞動人口。"},{"en":"An educated urbanised workforce is a group of workers with schooling, skills, and experience of city-based work.","zh":"受過教育的城市化勞動人口是有教育、技能和城市工作經驗的工人群體。"},{"en":"Technology companies often need an educated urbanised workforce to fill skilled jobs.","zh":"科技公司通常需要受過教育的城市化勞動人口來填補技術職位。"},{"en":"Without an educated urbanised workforce, factories may struggle to find trained staff.","zh":"沒有受過教育的城市化勞動人口，工廠可能難以找到受訓員工。"},{"en":"The phrase connects education, city life, and labour supply.","zh":"這個短語把教育、城市生活和勞動供應連繫起來。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":14},{"front":"business cannot prosper","meaning":"生意無法興旺","examples":[{"en":"Without infrastructure, business cannot prosper.","zh":"沒有基礎建設，生意無法興旺。"},{"en":"Business cannot prosper means companies cannot grow, earn profits, or operate successfully.","zh":"“Business cannot prosper” 指企業不能增長、賺取利潤或成功營運。"},{"en":"If customers cannot reach a shop, the business cannot prosper.","zh":"如果顧客不能到達商店，生意無法興旺。"},{"en":"Business cannot prosper when electricity fails every day and deliveries are delayed.","zh":"當電力每天中斷且送貨延誤，生意無法興旺。"},{"en":"The phrase shows that success depends on supporting conditions.","zh":"這個短語顯示成功依賴支援條件。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":14},{"front":"World Bank statistics","meaning":"世界銀行統計數據","examples":[{"en":"World Bank statistics show weak internet use in southern Africa.","zh":"世界銀行統計數據顯示南部非洲互聯網使用薄弱。"},{"en":"World Bank statistics are data collected or published by the World Bank about economies and development.","zh":"世界銀行統計數據是世界銀行收集或發布的關於經濟和發展的數據。"},{"en":"World Bank statistics may show income levels, school enrolment, trade costs, or internet use.","zh":"世界銀行統計數據可能顯示收入水平、入學率、貿易成本或互聯網使用情況。"},{"en":"Researchers use World Bank statistics to compare countries over time.","zh":"研究人員使用世界銀行統計數據比較不同國家隨時間的變化。"},{"en":"The phrase suggests evidence from a major international institution.","zh":"這個短語暗示來自主要國際機構的證據。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":14},{"front":"use the internet for business","meaning":"使用互聯網做生意","examples":[{"en":"Fewer companies in southern Africa use the internet for business.","zh":"南部非洲較少公司使用互聯網做生意。"},{"en":"To use the internet for business means to sell, advertise, communicate, pay, or manage work online.","zh":"“Use the internet for business” 指在網上銷售、宣傳、溝通、付款或管理工作。"},{"en":"A small shop may use the internet for business by taking orders through a website.","zh":"小店可能透過網站接訂單來使用互聯網做生意。"},{"en":"Companies that use the internet for business can reach customers far away.","zh":"使用互聯網做生意的公司可以接觸遠方顧客。"},{"en":"The phrase shows how digital tools support commercial activity.","zh":"這個短語顯示數碼工具如何支援商業活動。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":14},{"front":"as opposed to","meaning":"相對於","examples":[{"en":"Only 20% of companies use the internet for business, as opposed to 80% in the US.","zh":"只有20%的公司使用互聯網做生意，相對於美國的80%。"},{"en":"As opposed to means in contrast with or compared with another figure, idea, or situation.","zh":"“As opposed to” 指與另一個數字、想法或情況形成對比。"},{"en":"The course focuses on speaking, as opposed to grammar drills.","zh":"這個課程集中於口語，相對於文法操練。"},{"en":"She prefers walking to work, as opposed to taking crowded buses.","zh":"她喜歡步行上班，相對於乘搭擁擠巴士。"},{"en":"The phrase is useful when making a clear comparison.","zh":"這個短語適合用來作清晰比較。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":14},{"front":"average cost of","meaning":"……的平均成本","examples":[{"en":"The average cost of sending a container from Africa is high.","zh":"從非洲運送一個貨櫃的平均成本很高。"},{"en":"The average cost of something is the usual cost calculated across many examples.","zh":"某事的平均成本是根據許多例子計算出的通常成本。"},{"en":"The average cost of lunch near the office is about eight dollars.","zh":"辦公室附近午餐的平均成本約為八美元。"},{"en":"If the average cost of childcare rises, many parents may struggle to work full-time.","zh":"如果 childcare 的平均成本上升，許多父母可能難以全職工作。"},{"en":"The phrase helps compare typical prices.","zh":"這個短語有助比較典型價格。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":14},{"front":"send one container","meaning":"運送一個貨櫃","examples":[{"en":"Sending one container to the US costs more from Africa than from East Asia.","zh":"從非洲運送一個貨櫃到美國，比從東亞運送成本更高。"},{"en":"To send one container means to ship one large metal box of goods by sea, road, or rail.","zh":"“Send one container” 指透過海運、道路或鐵路運送一個大型金屬貨箱的貨物。"},{"en":"A factory may send one container of clothes to an overseas buyer.","zh":"工廠可能向海外買家運送一個裝有衣服的貨櫃。"},{"en":"If it costs too much to send one container, exporters may lose profits.","zh":"如果運送一個貨櫃成本太高，出口商可能失去利潤。"},{"en":"The phrase is common in trade and shipping discussions.","zh":"這個短語常見於貿易和航運討論。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":14},{"front":"the result of","meaning":"……的結果","examples":[{"en":"All these problems are the result of poor state planning.","zh":"所有這些問題都是糟糕國家規劃的結果。"},{"en":"The result of something means the outcome or consequence caused by it.","zh":"“The result of” 某事指由它造成的結果或後果。"},{"en":"The flood was the result of heavy rain and blocked drains.","zh":"洪水是大雨和排水渠堵塞的結果。"},{"en":"Better exam scores may be the result of regular practice and clear feedback.","zh":"更好的考試成績可能是定期練習和清晰回饋的結果。"},{"en":"The phrase connects a cause with its effect.","zh":"這個短語把原因與結果連繫起來。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":14},{"front":"poor state planning","meaning":"糟糕的國家規劃","examples":[{"en":"Poor state planning causes many economic problems.","zh":"糟糕的國家規劃造成許多經濟問題。"},{"en":"Poor state planning means weak government decisions about roads, schools, cities, budgets, or public services.","zh":"糟糕的國家規劃指政府在道路、學校、城市、預算或公共服務方面作出薄弱決策。"},{"en":"Poor state planning can leave new housing estates without transport or clinics.","zh":"糟糕的國家規劃可能令新屋苑缺乏交通或診所。"},{"en":"If poor state planning continues for years, businesses and families both suffer.","zh":"如果糟糕的國家規劃持續多年，企業和家庭都會受苦。"},{"en":"The phrase criticises government organisation and long-term preparation.","zh":"這個短語批評政府組織和長期準備。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":15},{"front":"ethnic and linguistic diversity","meaning":"種族和語言多樣性","examples":[{"en":"Ethnic and linguistic diversity can contribute to political conflict.","zh":"種族和語言多樣性可以導致政治衝突。"},{"en":"Ethnic and linguistic diversity means the presence of different ethnic groups and languages in one society.","zh":"種族和語言多樣性指一個社會中存在不同種族群體和語言。"},{"en":"A city with ethnic and linguistic diversity may need translation services in hospitals and schools.","zh":"擁有種族和語言多樣性的城市可能在醫院和學校需要翻譯服務。"},{"en":"Ethnic and linguistic diversity can enrich culture, but unfair politics may turn difference into conflict.","zh":"種族和語言多樣性可以豐富文化，但不公平政治可能把差異變成衝突。"},{"en":"The phrase describes variety in identity and language.","zh":"這個短語描述身份和語言上的多樣性。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":15},{"front":"lead to","meaning":"導致","examples":[{"en":"Diversity within countries has led to tribal favouritism.","zh":"國內多樣性導致部族偏袒。"},{"en":"To lead to something means to cause it or make it happen.","zh":"“Lead to” 指造成某事或令其發生。"},{"en":"Poor sleep can lead to weak concentration in class.","zh":"睡眠不足可以導致課堂上專注力差。"},{"en":"Clear instructions can lead to fewer mistakes at work.","zh":"清晰指示可以導致工作中較少錯誤。"},{"en":"The phrase can introduce either good or bad results.","zh":"這個短語可以引出好或壞的結果。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":15},{"front":"tribal favouritism","meaning":"部族偏袒","examples":[{"en":"Tribal favouritism affects government and conflict.","zh":"部族偏袒影響政府和衝突。"},{"en":"Tribal favouritism means giving unfair advantages to one’s own tribe or allied groups.","zh":"部族偏袒指給予自己部族或結盟群體不公平優勢。"},{"en":"Tribal favouritism may influence who gets jobs, contracts, or protection.","zh":"部族偏袒可能影響誰獲得工作、合約或保護。"},{"en":"When tribal favouritism shapes politics, citizens may feel excluded and angry.","zh":"當部族偏袒塑造政治時，市民可能感到被排除和憤怒。"},{"en":"The phrase describes unfair preference based on tribal identity.","zh":"這個短語描述基於部族身份的不公平偏好。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":15},{"front":"be controlled by","meaning":"受……控制","examples":[{"en":"Governments are often controlled by one tribe or allied tribes.","zh":"政府經常受一個部族或結盟部族控制。"},{"en":"To be controlled by someone means to have decisions directed or dominated by that person or group.","zh":"“Be controlled by” 指決策受某人或某群體指揮或主導。"},{"en":"A company controlled by one family may give top jobs to relatives.","zh":"由一個家族控制的公司可能把高層職位給親戚。"},{"en":"If public money is controlled by a small group, corruption may become easier.","zh":"如果公款受一小群人控制，貪污可能變得更容易。"},{"en":"The phrase shows where real power lies.","zh":"這個短語顯示真正權力所在。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":15},{"front":"allied tribes","meaning":"結盟部族","examples":[{"en":"Governments may be controlled by one tribe or allied tribes.","zh":"政府可能受一個部族或結盟部族控制。"},{"en":"Allied tribes are tribes that support or cooperate with one another.","zh":"結盟部族是互相支持或合作的部族。"},{"en":"Allied tribes may share political power, land, or military support.","zh":"結盟部族可能共享政治權力、土地或軍事支援。"},{"en":"If allied tribes dominate government, other groups may feel excluded.","zh":"如果結盟部族主導政府，其他群體可能感到被排除。"},{"en":"The phrase describes a relationship of alliance between tribal groups.","zh":"這個短語描述部族群體之間的聯盟關係。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":15},{"front":"civil war","meaning":"內戰","examples":[{"en":"Civil war is often tribal.","zh":"內戰往往具有部族性質。"},{"en":"A civil war is a war fought between groups within the same country.","zh":"內戰是在同一國家內不同群體之間發生的戰爭。"},{"en":"Civil war can destroy homes, schools, hospitals, and trust between communities.","zh":"內戰可以摧毀房屋、學校、醫院和社區之間的信任。"},{"en":"If political arguments turn violent, civil war may become possible.","zh":"如果政治爭議變得暴力，內戰可能成為可能。"},{"en":"The phrase is different from war between two separate countries.","zh":"這個短語不同於兩個不同國家之間的戰爭。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":15},{"front":"it is estimated that","meaning":"據估計","examples":[{"en":"It is estimated that each civil war costs a country roughly $64 billion.","zh":"據估計，每場內戰令一個國家損失大約640億美元。"},{"en":"It is estimated that means experts or researchers have made an approximate calculation.","zh":"“It is estimated that” 指專家或研究人員作出了大約計算。"},{"en":"It is estimated that the project will take six months to finish.","zh":"據估計，該項目需要六個月完成。"},{"en":"It is estimated that many children miss school because of illness each year.","zh":"據估計，每年有許多孩子因病缺課。"},{"en":"The phrase is useful when giving figures that are not exact.","zh":"這個短語適合用於給出不精確的數字。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":15},{"front":"roughly","meaning":"大約","examples":[{"en":"Each civil war costs roughly $64 billion.","zh":"每場內戰造成大約640億美元損失。"},{"en":"Roughly means approximately, not exactly.","zh":"“Roughly” 指大約，而不是精確地。"},{"en":"The walk takes roughly twenty minutes.","zh":"步行大約需要二十分鐘。"},{"en":"The repair will cost roughly $300, depending on the parts needed.","zh":"維修費大約為300美元，視乎所需零件而定。"},{"en":"The word is useful when an exact figure is not necessary.","zh":"當不需要精確數字時，這個詞很有用。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":15},{"front":"such conflicts","meaning":"這類衝突","examples":[{"en":"Southern Africa had 34 such conflicts from 1940 to 2000.","zh":"從1940年至2000年，南部非洲有34場這類衝突。"},{"en":"Such conflicts means conflicts of the kind just mentioned.","zh":"“Such conflicts” 指剛才提到的那一類衝突。"},{"en":"The report discussed bullying, and such conflicts can damage students’ confidence.","zh":"報告討論了欺凌，而這類衝突會損害學生信心。"},{"en":"If neighbours argue over noise and rubbish, such conflicts may need mediation.","zh":"如果鄰居因噪音和垃圾爭吵，這類衝突可能需要調解。"},{"en":"The phrase avoids repeating a longer description.","zh":"這個短語可以避免重複較長描述。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":15},{"front":"the next most affected region","meaning":"第二受影響最嚴重的地區","examples":[{"en":"South Asia was the next most affected region.","zh":"南亞是第二受影響最嚴重的地區。"},{"en":"The next most affected region means the region with the second-highest level of impact.","zh":"“The next most affected region” 指受影響程度第二高的地區。"},{"en":"After the coastal area, the mountain villages were the next most affected region.","zh":"在沿海地區之後，山區村莊是第二受影響最嚴重的地區。"},{"en":"In a flu outbreak, schools may be the next most affected region after hospitals.","zh":"在流感爆發中，學校可能是繼醫院後第二受影響最嚴重的地區。"},{"en":"The phrase ranks places by how seriously they are affected.","zh":"這個短語按受影響嚴重程度排列地方。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":15},{"front":"in the same period","meaning":"在同一時期","examples":[{"en":"South Asia had fewer conflicts in the same period.","zh":"南亞在同一時期有較少衝突。"},{"en":"In the same period means within the same years or time span already being discussed.","zh":"“In the same period” 指在正在討論的同一年份或時間範圍內。"},{"en":"The company hired more staff in the same period that sales increased.","zh":"公司在銷售增加的同一時期聘請更多員工。"},{"en":"Rainfall fell, but water use rose in the same period.","zh":"降雨量下降，但用水量在同一時期上升。"},{"en":"This phrase helps compare two facts using one shared time frame.","zh":"這個短語有助用同一時間框架比較兩個事實。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":16},{"front":"to this day","meaning":"直至今天","examples":[{"en":"To this day, a number of bloody conflicts continue.","zh":"直至今天，一些血腥衝突仍在繼續。"},{"en":"To this day means even now, after a long time has passed.","zh":"“To this day” 指即使很長時間過去，直到現在仍然如此。"},{"en":"To this day, she remembers the teacher who encouraged her.","zh":"直至今天，她仍記得那位鼓勵她的老師。"},{"en":"The old bridge is still used to this day.","zh":"那座舊橋直至今天仍被使用。"},{"en":"The phrase stresses that something continues into the present.","zh":"這個短語強調某事延續至現在。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":16},{"front":"bloody conflicts","meaning":"血腥衝突","examples":[{"en":"A number of bloody conflicts continue.","zh":"一些血腥衝突仍在繼續。"},{"en":"Bloody conflicts are violent conflicts in which many people are injured or killed.","zh":"血腥衝突是有許多人受傷或死亡的暴力衝突。"},{"en":"Bloody conflicts can force families to leave their homes.","zh":"血腥衝突可以迫使家庭離開家園。"},{"en":"If bloody conflicts continue for years, schools and hospitals may collapse.","zh":"如果血腥衝突持續多年，學校和醫院可能崩潰。"},{"en":"The phrase strongly emphasises violence and human suffering.","zh":"這個短語強烈強調暴力和人類苦難。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":16},{"front":"opponents of Moyo","meaning":"Moyo 的反對者","examples":[{"en":"Other opponents of Moyo criticise her market focus.","zh":"Moyo 的其他反對者批評她對市場的重視。"},{"en":"Opponents of Moyo are people who disagree with Moyo’s arguments or proposals.","zh":"Moyo 的反對者是不同意 Moyo 論點或建議的人。"},{"en":"Opponents of a policy may accept the problem but reject the solution.","zh":"政策的反對者可能接受問題存在，但拒絕解決方案。"},{"en":"Opponents of Moyo may argue that geography and politics matter more than aid.","zh":"Moyo 的反對者可能認為地理和政治比援助更重要。"},{"en":"The phrase identifies critics of a particular person’s view.","zh":"這個短語指出某個人觀點的批評者。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":16},{"front":"focus on","meaning":"集中於……","examples":[{"en":"Moyo’s focus on market investment is criticised.","zh":"Moyo 集中於市場投資這一點受到批評。"},{"en":"To focus on something means to give most attention to it.","zh":"“Focus on” 某事指把大部分注意力放在它上面。"},{"en":"A student should focus on weak grammar points before the exam.","zh":"學生應在考試前集中於薄弱文法點。"},{"en":"If a company focuses only on profit, it may ignore workers’ health.","zh":"如果公司只集中於利潤，它可能忽視工人健康。"},{"en":"The phrase shows the main subject of attention.","zh":"這個短語顯示注意力的主要對象。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":16},{"front":"market investment","meaning":"市場投資","examples":[{"en":"Some critics doubt that market investment can solve Africa’s problems.","zh":"一些批評者懷疑市場投資能否解決非洲問題。"},{"en":"Market investment means putting money into financial markets, businesses, or commercial opportunities.","zh":"市場投資指把金錢投入金融市場、企業或商業機會。"},{"en":"Market investment can bring growth, but it can also involve risk.","zh":"市場投資可以帶來增長，但也可能涉及風險。"},{"en":"A city may attract market investment by improving rules and transport.","zh":"城市可以透過改善規則和交通來吸引市場投資。"},{"en":"The phrase is often contrasted with aid or government spending.","zh":"這個短語常與援助或政府開支形成對比。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":16},{"front":"short-sighted","meaning":"短視的","examples":[{"en":"Critics say Moyo’s focus on China is short-sighted.","zh":"批評者說 Moyo 對中國的重視是短視的。"},{"en":"Short-sighted means thinking only about immediate benefits and ignoring long-term risks.","zh":"“Short-sighted” 指只考慮眼前利益，而忽略長期風險。"},{"en":"Spending all your savings on one holiday may be short-sighted.","zh":"把所有積蓄花在一次旅行上可能是短視的。"},{"en":"A short-sighted policy may win votes now but create future problems.","zh":"短視政策可能現在贏得選票，但製造未來問題。"},{"en":"The word is usually critical and warns against narrow thinking.","zh":"這個詞通常帶批評意味，提醒人避免狹窄思考。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":16},{"front":"financial crisis","meaning":"金融危機","examples":[{"en":"The 2008 financial crisis caused investment losses.","zh":"2008年金融危機造成投資損失。"},{"en":"A financial crisis is a serious breakdown in banks, markets, credit, or the wider economy.","zh":"金融危機是銀行、市場、信貸或整體經濟出現嚴重崩潰。"},{"en":"During a financial crisis, people may lose jobs, savings, or homes.","zh":"在金融危機期間，人們可能失去工作、積蓄或房屋。"},{"en":"A financial crisis can reduce investment because people become afraid of risk.","zh":"金融危機可以減少投資，因為人們變得害怕風險。"},{"en":"The phrase refers to a major economic shock, not a small personal money problem.","zh":"這個短語指重大經濟衝擊，而不是個人小型金錢問題。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":16},{"front":"lose money","meaning":"虧損；損失金錢","examples":[{"en":"Countries with market investments lost money during the crisis.","zh":"擁有市場投資的國家在危機期間虧損。"},{"en":"To lose money means to end with less money than before after spending, investing, or trading.","zh":"“Lose money” 指在花費、投資或交易後，金錢比之前少。"},{"en":"A shop may lose money if rent is higher than sales income.","zh":"如果租金高於銷售收入，商店可能虧損。"},{"en":"Investors can lose money when share prices fall sharply.","zh":"當股價急跌時，投資者可能損失金錢。"},{"en":"The phrase describes financial loss, not simply spending money.","zh":"這個短語描述財務損失，而不只是花錢。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":16},{"front":"real intentions","meaning":"真正意圖","examples":[{"en":"China’s real intentions in Africa are unknown.","zh":"中國在非洲的真正意圖未知。"},{"en":"Real intentions are the true aims behind someone’s words or actions.","zh":"真正意圖是某人言語或行動背後的真實目的。"},{"en":"A company may say it wants to help customers, but its real intentions may be to collect data.","zh":"公司可能說想幫助顧客，但其真正意圖可能是收集數據。"},{"en":"If a person hides their real intentions, others may find it hard to trust them.","zh":"如果一個人隱藏真正意圖，其他人可能難以信任他。"},{"en":"The phrase contrasts public explanation with hidden motivation.","zh":"這個短語把公開解釋與隱藏動機作對比。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":16},{"front":"buy up","meaning":"大量買入","examples":[{"en":"China is buying up African farmland.","zh":"中國正在大量買入非洲農地。"},{"en":"To buy up something means to buy a large amount of it, often quickly or aggressively.","zh":"“Buy up” 指大量購買某物，通常快速或積極地購買。"},{"en":"Investors may buy up old buildings before an area becomes popular.","zh":"投資者可能在某區變得受歡迎前大量買入舊樓。"},{"en":"If large companies buy up local shops, small owners may disappear.","zh":"如果大型公司大量買入本地商店，小店主可能消失。"},{"en":"The phrase can suggest control through large-scale purchasing.","zh":"這個短語可以暗示透過大規模購買取得控制。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":16},{"front":"African farmland","meaning":"非洲農地","examples":[{"en":"China is buying up African farmland.","zh":"中國正在大量買入非洲農地。"},{"en":"African farmland is land in Africa used or suitable for growing crops or raising animals.","zh":"非洲農地是在非洲用於或適合種植作物或飼養動物的土地。"},{"en":"African farmland can be valuable for food production and export crops.","zh":"非洲農地對糧食生產和出口農作物可能很有價值。"},{"en":"If foreign companies control African farmland, local farmers may worry about land rights.","zh":"如果外國公司控制非洲農地，本地農民可能擔心土地權利。"},{"en":"The phrase identifies both the location and agricultural use of the land.","zh":"這個短語同時指出土地的位置和農業用途。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":17},{"front":"secure cheap oil supplies","meaning":"確保取得廉價石油供應","examples":[{"en":"China is securing cheap oil supplies.","zh":"中國正在確保取得廉價石油供應。"},{"en":"To secure cheap oil supplies means to obtain reliable access to oil at low prices.","zh":"“Secure cheap oil supplies” 指取得可靠而低價的石油來源。"},{"en":"A country may secure cheap oil supplies through long-term contracts.","zh":"一個國家可能透過長期合約確保取得廉價石油供應。"},{"en":"If a factory secures cheap fuel supplies, its production costs may fall.","zh":"如果工廠確保取得廉價燃料供應，其生產成本可能下降。"},{"en":"The phrase suggests protecting access to an important resource.","zh":"這個短語暗示保護對重要資源的取得。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":17},{"front":"untapped resources","meaning":"未開發資源","examples":[{"en":"Africa has many untapped resources.","zh":"非洲有許多未開發資源。"},{"en":"Untapped resources are valuable materials, skills, markets, or opportunities that have not yet been fully used.","zh":"未開發資源是尚未被充分使用的有價值材料、技能、市場或機會。"},{"en":"A village with strong sunlight has untapped resources for solar energy.","zh":"陽光充足的村莊擁有太陽能方面的未開發資源。"},{"en":"Young people’s language skills may be untapped resources for tourism businesses.","zh":"年輕人的語言能力可能是旅遊企業的未開發資源。"},{"en":"The phrase suggests hidden potential.","zh":"這個短語暗示隱藏潛力。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":17},{"front":"low population density","meaning":"低人口密度","examples":[{"en":"Low population density contributes to poverty.","zh":"低人口密度造成貧窮。"},{"en":"Low population density means few people live in each square kilometre or mile.","zh":"低人口密度指每平方公里或英里居住的人很少。"},{"en":"Areas with low population density may have fewer schools, shops, and hospitals nearby.","zh":"低人口密度地區附近可能有較少學校、商店和醫院。"},{"en":"Low population density can make public transport expensive to provide.","zh":"低人口密度會令公共交通提供成本昂貴。"},{"en":"The phrase describes how spread out people are.","zh":"這個短語描述人們分布得有多分散。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":17},{"front":"contribute to poverty","meaning":"造成貧窮；加劇貧窮","examples":[{"en":"Distance and low population density contribute to poverty.","zh":"距離和低人口密度造成貧窮。"},{"en":"To contribute to poverty means to be one of the causes that makes poverty worse or more likely.","zh":"“Contribute to poverty” 指成為使貧窮惡化或更可能出現的原因之一。"},{"en":"Low wages and high rent can contribute to poverty in big cities.","zh":"低工資和高租金可以加劇大城市中的貧窮。"},{"en":"Poor health may contribute to poverty because people cannot work regularly.","zh":"健康欠佳可能造成貧窮，因為人們不能定期工作。"},{"en":"The phrase does not mean the only cause, but an important part of the problem.","zh":"這個短語不是指唯一原因，而是問題的重要部分。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":17},{"front":"unreliable electricity","meaning":"不可靠的電力供應","examples":[{"en":"Unreliable electricity makes development difficult.","zh":"不可靠的電力供應令發展困難。"},{"en":"Unreliable electricity means power supply that often fails, stops, or changes suddenly.","zh":"不可靠的電力供應指經常故障、中斷或突然變化的供電。"},{"en":"A shop with unreliable electricity may lose frozen food and customers.","zh":"有不可靠電力供應的商店可能失去冷凍食物和顧客。"},{"en":"Unreliable electricity can interrupt online classes, hospital equipment, and factory machines.","zh":"不可靠的電力供應可以中斷網上課堂、醫療設備和工廠機器。"},{"en":"The phrase describes a basic service that people cannot depend on.","zh":"這個短語描述人們不能依賴的基本服務。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":17},{"front":"automatic weapons","meaning":"自動武器","examples":[{"en":"There seems to be money for automatic weapons.","zh":"似乎有錢購買自動武器。"},{"en":"Automatic weapons are guns that can fire repeatedly without reloading after every shot.","zh":"自動武器是可以連續射擊而不需每槍重新裝填的槍械。"},{"en":"Automatic weapons are extremely dangerous because they can injure many people quickly.","zh":"自動武器極度危險，因為它們可以迅速傷害許多人。"},{"en":"Money spent on automatic weapons cannot be spent on schools, clinics, or roads.","zh":"花在自動武器上的金錢不能用於學校、診所或道路。"},{"en":"The phrase is often used when discussing war, violence, and military spending.","zh":"這個短語常用於討論戰爭、暴力和軍事開支。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":17},{"front":"just the right size for","meaning":"大小剛好適合……","examples":[{"en":"The weapons are just the right size for young boys to use.","zh":"這些武器大小剛好適合年幼男孩使用。"},{"en":"Just the right size for something means exactly suitable in size for that purpose or person.","zh":"“Just the right size for” 某事指大小完全適合該用途或人士。"},{"en":"This small desk is just the right size for a child’s bedroom.","zh":"這張小書桌大小剛好適合孩子的睡房。"},{"en":"A pocket notebook is just the right size for quick notes on the bus.","zh":"一本口袋筆記簿大小剛好適合在巴士上快速記筆記。"},{"en":"The phrase can be neutral, positive, or disturbing depending on context.","zh":"這個短語可以是中性、正面或令人不安，視乎語境而定。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":17},{"front":"blaming the West for","meaning":"因……而責怪西方","examples":[{"en":"Blaming the West for assisting with aid misses deeper problems.","zh":"因西方以援助提供協助而責怪西方，會忽略更深層問題。"},{"en":"Blaming the West for something means saying Western countries are responsible for it.","zh":"“Blaming the West for” 某事指說西方國家要為它負責。"},{"en":"Blaming teachers for low scores may ignore students’ lack of practice.","zh":"因成績低而責怪老師，可能忽視學生缺乏練習。"},{"en":"Blaming the West for every problem can hide local responsibility.","zh":"因每個問題而責怪西方，可能掩蓋本地責任。"},{"en":"The phrase introduces an accusation and may be followed by a criticism of that accusation.","zh":"這個短語引出一項指責，其後可能接著對該指責的批評。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":17},{"front":"assist with aid","meaning":"以援助提供協助","examples":[{"en":"The West assists with aid.","zh":"西方以援助提供協助。"},{"en":"To assist with aid means to help by providing money, goods, services, or expertise.","zh":"“Assist with aid” 指透過提供金錢、物資、服務或專業知識來幫助。"},{"en":"Volunteers assist with aid by packing food and medicine after disasters.","zh":"災難後，義工透過包裝食物和藥物以援助提供協助。"},{"en":"Wealthier countries may assist with aid when poorer countries face emergencies.","zh":"當較貧窮國家面對緊急情況，較富裕國家可能以援助提供協助。"},{"en":"The phrase focuses on helping through organised support.","zh":"這個短語強調透過有組織支援來幫忙。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":17},{"front":"fail to address","meaning":"未能處理","examples":[{"en":"Blaming aid fails to address continuous conflict and weak government.","zh":"責怪援助未能處理持續衝突和弱政府。"},{"en":"To fail to address a problem means not to deal with its real cause or seriousness.","zh":"“Fail to address” 問題指沒有處理其真正原因或嚴重性。"},{"en":"Punishing a noisy class may fail to address why students are bored.","zh":"懲罰嘈吵的班級可能未能處理學生感到沉悶的原因。"},{"en":"Giving free medicine may fail to address poor water quality that causes illness.","zh":"派發免費藥物可能未能處理導致疾病的劣質食水問題。"},{"en":"The phrase criticises a solution for missing the main issue.","zh":"這個短語批評解決方案錯過主要問題。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":17},{"front":"continuous conflict","meaning":"持續衝突","examples":[{"en":"Continuous conflict damages African development.","zh":"持續衝突破壞非洲發展。"},{"en":"Continuous conflict means fighting, disagreement, or violence that goes on without stopping for a long time.","zh":"持續衝突指長時間不停的戰鬥、爭議或暴力。"},{"en":"Continuous conflict between neighbours can make daily life stressful.","zh":"鄰居之間的持續衝突可以令日常生活充滿壓力。"},{"en":"Continuous conflict in a country can close schools and scare away investors.","zh":"國內持續衝突可以關閉學校並嚇走投資者。"},{"en":"The phrase emphasises length and repeated harm.","zh":"這個短語強調時間長度和反覆傷害。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":18},{"front":"ineffective government","meaning":"無效能的政府","examples":[{"en":"Ineffective government is one of Africa’s major problems.","zh":"無效能的政府是非洲主要問題之一。"},{"en":"Ineffective government means a government that cannot make good decisions or provide services properly.","zh":"無效能的政府指不能作出良好決策或妥善提供服務的政府。"},{"en":"Ineffective government may leave roads broken, hospitals underfunded, and laws unenforced.","zh":"無效能的政府可能令道路破損、醫院資金不足、法律無法執行。"},{"en":"When ineffective government continues, citizens may lose trust in public institutions.","zh":"當無效能的政府持續，市民可能失去對公共機構的信任。"},{"en":"The phrase criticises weak performance, not simply a small government.","zh":"這個短語批評表現薄弱，而不只是政府規模小。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":18},{"front":"little infrastructure","meaning":"基礎建設不足","examples":[{"en":"Little infrastructure limits business and development.","zh":"基礎建設不足限制商業和發展。"},{"en":"Little infrastructure means there are not enough basic systems such as roads, electricity, water, and communications.","zh":"“Little infrastructure” 指道路、電力、水和通訊等基本系統不足。"},{"en":"A village with little infrastructure may have no paved roads or stable internet.","zh":"基礎建設不足的村莊可能沒有鋪好的道路或穩定互聯網。"},{"en":"Little infrastructure can make schools, clinics, and markets difficult to reach.","zh":"基礎建設不足會令學校、診所和市場難以到達。"},{"en":"The phrase describes a shortage of practical foundations for growth.","zh":"這個短語描述增長所需實際基礎的短缺。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":18},{"front":"prevent terrible suffering","meaning":"防止嚴重苦難","examples":[{"en":"Aid may prevent terrible suffering.","zh":"援助可能防止嚴重苦難。"},{"en":"To prevent terrible suffering means to stop people from experiencing severe pain, hunger, illness, or danger.","zh":"“Prevent terrible suffering” 指阻止人們經歷嚴重痛苦、飢餓、疾病或危險。"},{"en":"Emergency food can prevent terrible suffering after a crop failure.","zh":"農作物失收後，緊急糧食可以防止嚴重苦難。"},{"en":"Clean water can prevent terrible suffering during a disease outbreak.","zh":"疾病爆發期間，潔淨食水可以防止嚴重苦難。"},{"en":"The phrase highlights the human value of timely help.","zh":"這個短語強調及時幫助的人道價值。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":18},{"front":"strife","meaning":"衝突；苦難","examples":[{"en":"The passage asks whether Africa’s strife is of its own making.","zh":"文章問非洲的衝突是否由其自身造成。"},{"en":"Strife means serious conflict, struggle, or trouble within a society or group.","zh":"“Strife” 指社會或群體內部的嚴重衝突、鬥爭或麻煩。"},{"en":"Family strife may arise when relatives argue over money.","zh":"當親戚因金錢爭吵時，家庭衝突可能出現。"},{"en":"Political strife can make ordinary people feel unsafe and uncertain.","zh":"政治衝突可以令普通人感到不安全和不確定。"},{"en":"The word is formal and often used for social or political conflict.","zh":"這個詞較正式，常用於社會或政治衝突。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":18},{"front":"of its own making","meaning":"由其自身造成的","examples":[{"en":"Some argue that Africa’s strife is of its own making.","zh":"有人認為非洲的苦難是由其自身造成的。"},{"en":"If a problem is of its own making, it was caused by the person, group, or country experiencing it.","zh":"如果問題是 “of its own making”，即它由正在經歷問題的人、群體或國家造成。"},{"en":"The company’s debt was of its own making because it borrowed carelessly.","zh":"該公司的債務是由其自身造成的，因為它草率借貸。"},{"en":"A student’s stress may be of his own making if he delays all work until the last night.","zh":"如果學生把所有功課拖到最後一晚，他的壓力可能是由其自身造成的。"},{"en":"The phrase places responsibility on the affected side.","zh":"這個短語把責任放在受影響一方身上。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":18},{"front":"due to geography","meaning":"由地理因素造成","examples":[{"en":"Some problems may be due to geography.","zh":"一些問題可能由地理因素造成。"},{"en":"Due to geography means caused by physical location, distance, climate, land, or natural features.","zh":"“Due to geography” 指由實際位置、距離、氣候、土地或自然特徵造成。"},{"en":"A village may be isolated due to geography if mountains block easy travel.","zh":"如果山脈阻礙容易通行，村莊可能因地理因素而孤立。"},{"en":"Farming may be difficult due to geography when land is dry or rocky.","zh":"當土地乾燥或多石，農業可能因地理因素而困難。"},{"en":"The phrase explains a problem through natural or location-based factors.","zh":"這個短語透過自然或位置因素解釋問題。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":18},{"front":"whatever you think","meaning":"無論你怎樣想","examples":[{"en":"Whatever you think, Moyo’s book has generated discussion.","zh":"無論你怎樣想，Moyo 的書已引發討論。"},{"en":"Whatever you think means no matter what your opinion is.","zh":"“Whatever you think” 指無論你的意見是甚麼。"},{"en":"Whatever you think about the policy, it has made people discuss housing seriously.","zh":"無論你怎樣看這項政策，它已令人認真討論住屋問題。"},{"en":"Whatever you think of the film, it clearly attracted public attention.","zh":"無論你怎樣看這部電影，它明顯吸引了公眾注意。"},{"en":"The phrase introduces a point that remains true despite different opinions.","zh":"這個短語引出一個即使意見不同仍然成立的重點。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":18},{"front":"generate lively discussion","meaning":"引發熱烈討論","examples":[{"en":"Moyo’s book has generated lively discussion.","zh":"Moyo 的書已引發熱烈討論。"},{"en":"To generate lively discussion means to cause active, energetic, and often heated conversation.","zh":"“Generate lively discussion” 指引起積極、有活力且常常激烈的談話。"},{"en":"A controversial school rule can generate lively discussion among parents.","zh":"有爭議的校規可以在家長之間引發熱烈討論。"},{"en":"A good debate question should generate lively discussion, not silent agreement.","zh":"好的辯論題目應引發熱烈討論，而不是沉默同意。"},{"en":"The phrase shows that an idea makes people talk and think.","zh":"這個短語顯示某個想法令人們交談和思考。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":18},{"front":"beneficial to","meaning":"對……有益","examples":[{"en":"The discussion is beneficial to Africa.","zh":"這場討論對非洲有益。"},{"en":"Beneficial to someone or something means helpful or good for them.","zh":"“Beneficial to” 某人或某事指對其有幫助或有好處。"},{"en":"Regular exercise is beneficial to physical and mental health.","zh":"定期運動對身心健康有益。"},{"en":"Clear feedback is beneficial to students because it shows how to improve.","zh":"清晰回饋對學生有益，因為它顯示如何改善。"},{"en":"The phrase is formal and often used in essays.","zh":"這個短語較正式，常用於作文。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":18},{"front":"complete the chart below","meaning":"完成以下圖表","examples":[{"en":"Students complete the chart below using words from the passage.","zh":"學生使用文章中的詞語完成以下圖表。"},{"en":"Complete the chart below means fill in the missing information in the chart under the question.","zh":"“Complete the chart below” 指填寫題目下方圖表中的缺漏資料。"},{"en":"In the exam, students must complete the chart below with no more than two words.","zh":"在考試中，學生必須用不多於兩個詞完成以下圖表。"},{"en":"If you read the headings first, it is easier to complete the chart below.","zh":"如果你先閱讀標題，完成以下圖表會更容易。"},{"en":"The phrase is a common instruction in reading and listening tasks.","zh":"這個短語是閱讀和聆聽題中常見的指示。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":18},{"front":"one word or a number","meaning":"一個詞或一個數字","examples":[{"en":"Students should choose one word or a number from the passage.","zh":"學生應從文章中選擇一個詞或一個數字。"},{"en":"One word or a number means the answer must be either a single word or a numerical figure.","zh":"“One word or a number” 指答案必須是一個單詞或一個數字。"},{"en":"If the instruction says one word or a number, “sixty-four billion” may be too many words.","zh":"如果指示說一個詞或一個數字，“sixty-four billion” 可能太多詞。"},{"en":"Students lose marks when they write two words instead of one word or a number.","zh":"學生寫兩個詞而不是一個詞或一個數字時會失分。"},{"en":"The phrase tells candidates the exact answer limit.","zh":"這個短語告訴考生準確的答案限制。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":19},{"front":"overview","meaning":"概覽","examples":[{"en":"The chart gives an overview of Africa’s problems.","zh":"圖表給出非洲問題的概覽。"},{"en":"An overview is a general summary of the main points, not every detail.","zh":"概覽是主要重點的整體總結，而不是每個細節。"},{"en":"Before reading the full report, students should read the overview to understand the topic.","zh":"閱讀完整報告前，學生應先閱讀概覽以理解主題。"},{"en":"A good overview helps readers see the big picture quickly.","zh":"好的概覽幫助讀者快速看見整體情況。"},{"en":"The word is common in charts, reports, essays, and presentations.","zh":"這個詞常見於圖表、報告、作文和簡報。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":19},{"front":"largely responsible","meaning":"負有主要責任","examples":[{"en":"Moyo argues that international aid is largely responsible.","zh":"Moyo 認為國際援助負有主要責任。"},{"en":"Largely responsible means mainly responsible, though not necessarily the only cause.","zh":"“Largely responsible” 指負有主要責任，但不一定是唯一原因。"},{"en":"Poor time management was largely responsible for the missed deadline.","zh":"糟糕時間管理對錯過截止日期負有主要責任。"},{"en":"A lack of sleep may be largely responsible for a student’s weak concentration.","zh":"睡眠不足可能對學生專注力差負有主要責任。"},{"en":"The phrase assigns major responsibility while leaving room for other factors.","zh":"這個短語把主要責任歸於某因素，同時仍容許其他因素存在。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":19},{"front":"depend on","meaning":"依賴","examples":[{"en":"Some states depend on international aid.","zh":"一些國家依賴國際援助。"},{"en":"To depend on something means to need it in order to survive, work, or succeed.","zh":"“Depend on” 某事指需要它才能生存、運作或成功。"},{"en":"Young children depend on adults for food, safety, and care.","zh":"年幼孩子依賴成年人提供食物、安全和照顧。"},{"en":"A business may depend on tourists if most customers come from overseas.","zh":"如果大多數顧客來自海外，企業可能依賴遊客。"},{"en":"The phrase can show reliance, not just preference.","zh":"這個短語可以表示依靠，而不只是偏好。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":19},{"front":"be corrupt as a result","meaning":"因而貪污","examples":[{"en":"Some states depend on aid and are corrupt as a result.","zh":"一些國家依賴援助，因而貪污。"},{"en":"To be corrupt as a result means to become dishonest because of the situation just mentioned.","zh":"“Be corrupt as a result” 指因剛才提到的情況而變得不誠實。"},{"en":"If officials control large funds without checks, they may be corrupt as a result.","zh":"如果官員在沒有制衡下控制大量資金，他們可能因而貪污。"},{"en":"A system with secret payments may become corrupt as a result of weak rules.","zh":"有秘密付款的制度可能因規則薄弱而變得貪污。"},{"en":"The phrase connects corruption to a cause.","zh":"這個短語把貪污與原因連繫起來。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":19},{"front":"be drawn away from","meaning":"被吸引離開……","examples":[{"en":"Talented people have been drawn away from business.","zh":"有才能的人被吸引離開商業。"},{"en":"To be drawn away from something means to be attracted or pulled away from it.","zh":"“Be drawn away from” 某事指被吸引或拉離它。"},{"en":"Good students may be drawn away from science if there are no inspiring teachers.","zh":"如果沒有啟發人的老師，好學生可能被吸引離開科學。"},{"en":"Workers can be drawn away from farming by higher wages in cities.","zh":"工人可能被城市較高工資吸引離開農業。"},{"en":"The phrase suggests movement away from one activity towards another.","zh":"這個短語暗示從一項活動移向另一項活動。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":19},{"front":"involve local communities","meaning":"讓本地社區參與","examples":[{"en":"Foreigners ought to involve local communities more.","zh":"外國人應該更多讓本地社區參與。"},{"en":"To involve local communities means to let residents take part in planning, decisions, or action.","zh":"“Involve local communities” 指讓居民參與規劃、決策或行動。"},{"en":"A park project should involve local communities before trees are removed.","zh":"公園項目在移除樹木前應讓本地社區參與。"},{"en":"If charities involve local communities, they are more likely to understand real needs.","zh":"如果慈善機構讓本地社區參與，它們較可能理解真正需要。"},{"en":"The phrase emphasises participation, not just consultation from above.","zh":"這個短語強調參與，而不只是由上而下諮詢。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":19},{"front":"buy into bond markets","meaning":"投資債券市場","examples":[{"en":"Moyo suggests that African states should buy into bond markets.","zh":"Moyo 建議非洲國家應投資債券市場。"},{"en":"To buy into bond markets means to raise or invest money through markets where bonds are sold.","zh":"“Buy into bond markets” 指透過出售債券的市場籌集或投資金錢。"},{"en":"Governments may buy into bond markets to finance roads, schools, or power stations.","zh":"政府可能投資債券市場，以資助道路、學校或發電站。"},{"en":"Buying into bond markets can bring money, but it also creates repayment duties.","zh":"投資債券市場可以帶來金錢，但也會產生還款責任。"},{"en":"The phrase belongs to finance and development policy.","zh":"這個短語屬於金融和發展政策。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":19},{"front":"a closer relationship with","meaning":"與……更密切的關係","examples":[{"en":"Moyo suggests a closer relationship with China.","zh":"Moyo 建議與中國建立更密切的關係。"},{"en":"A closer relationship with someone means more contact, trust, co-operation, or dependence.","zh":"“A closer relationship with” 某人指更多接觸、信任、合作或依賴。"},{"en":"A school may build a closer relationship with parents through regular meetings.","zh":"學校可以透過定期會議與家長建立更密切的關係。"},{"en":"A closer relationship with suppliers can help a business receive goods faster.","zh":"與供應商更密切的關係可以幫助企業更快收到貨物。"},{"en":"The phrase can describe personal, business, or international relations.","zh":"這個短語可以描述個人、商業或國際關係。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":19},{"front":"other scholars’ theories","meaning":"其他學者的理論","examples":[{"en":"Other scholars’ theories emphasise geography, politics and infrastructure.","zh":"其他學者的理論強調地理、政治和基礎建設。"},{"en":"Other scholars’ theories are explanations proposed by academics other than the main writer being discussed.","zh":"其他學者的理論是由正在討論的主要作者以外的學者提出的解釋。"},{"en":"Other scholars’ theories may challenge Moyo’s view of aid.","zh":"其他學者的理論可能挑戰 Moyo 對援助的看法。"},{"en":"In an essay, other scholars’ theories help show that a topic has more than one explanation.","zh":"在作文中，其他學者的理論有助顯示一個題目有多於一種解釋。"},{"en":"The phrase introduces alternative academic viewpoints.","zh":"這個短語引入其他學術觀點。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":19},{"front":"culturally and politically diverse","meaning":"文化和政治上多元","examples":[{"en":"Africa is culturally and politically diverse.","zh":"非洲在文化和政治上多元。"},{"en":"Culturally and politically diverse means having many different traditions, languages, values, governments, and political systems.","zh":"“Culturally and politically diverse” 指擁有許多不同傳統、語言、價值觀、政府和政治制度。"},{"en":"A culturally and politically diverse region may need flexible laws and careful communication.","zh":"文化和政治上多元的地區可能需要靈活法律和謹慎溝通。"},{"en":"Culturally and politically diverse societies can be rich in ideas but difficult to govern fairly.","zh":"文化和政治上多元的社會可以充滿想法，但難以公平管治。"},{"en":"The phrase describes variety in both culture and politics.","zh":"這個短語描述文化和政治兩方面的多樣性。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":19},{"front":"control most of the economy","meaning":"控制大部分經濟","examples":[{"en":"Military and government elites control most of the economy.","zh":"軍方和政府精英控制大部分經濟。"},{"en":"To control most of the economy means to hold power over the majority of businesses, money, land, or resources.","zh":"“Control most of the economy” 指掌握大部分企業、金錢、土地或資源的權力。"},{"en":"If a few families control most of the economy, competition may be weak.","zh":"如果少數家族控制大部分經濟，競爭可能薄弱。"},{"en":"Groups that control most of the economy can influence prices and jobs.","zh":"控制大部分經濟的群體可以影響價格和工作。"},{"en":"The phrase suggests concentrated economic power.","zh":"這個短語暗示經濟權力集中。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":20},{"front":"remain underdeveloped","meaning":"仍然發展不足","examples":[{"en":"Education, communications and transportation remain underdeveloped.","zh":"教育、通訊和交通仍然發展不足。"},{"en":"To remain underdeveloped means to continue being poorly developed or not modern enough.","zh":"“Remain underdeveloped” 指繼續發展不足或不夠現代化。"},{"en":"Some rural schools remain underdeveloped because they lack teachers and computers.","zh":"一些農村學校因缺乏老師和電腦而仍然發展不足。"},{"en":"If transport remains underdeveloped, farmers cannot reach markets easily.","zh":"如果交通仍然發展不足，農民不能輕易到達市場。"},{"en":"The phrase suggests that progress has not reached a satisfactory level.","zh":"這個短語暗示進步尚未達到令人滿意的水平。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":20},{"front":"numerous civil wars","meaning":"多場內戰","examples":[{"en":"Numerous civil wars have been costly for Africa.","zh":"多場內戰對非洲代價高昂。"},{"en":"Numerous civil wars means many wars fought between groups within the same country.","zh":"多場內戰指許多在同一國家內不同群體之間發生的戰爭。"},{"en":"Numerous civil wars can destroy infrastructure and divide communities for generations.","zh":"多場內戰可以摧毀基礎建設，並令社區分裂數代。"},{"en":"A region affected by numerous civil wars may struggle to attract investment.","zh":"受多場內戰影響的地區可能難以吸引投資。"},{"en":"The phrase emphasises both number and seriousness.","zh":"這個短語同時強調數量和嚴重性。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":20},{"front":"mostly tribal","meaning":"主要屬部族性質","examples":[{"en":"Many civil wars are mostly tribal.","zh":"許多內戰主要屬部族性質。"},{"en":"Mostly tribal means mainly connected to tribes or tribal identity.","zh":"“Mostly tribal” 指主要與部族或部族身份有關。"},{"en":"A conflict may be mostly tribal if people fight along clan or ethnic lines.","zh":"如果人們沿着宗族或族群界線戰鬥，衝突可能主要屬部族性質。"},{"en":"Politics that is mostly tribal may reward loyalty to group identity over national interest.","zh":"主要屬部族性質的政治可能獎勵對群體身份的忠誠，而不是國家利益。"},{"en":"The phrase identifies the main nature of a conflict or issue.","zh":"這個短語指出衝突或問題的主要性質。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":20},{"front":"without international aid","meaning":"沒有國際援助","examples":[{"en":"Without international aid, Africa might experience more suffering.","zh":"沒有國際援助，非洲可能經歷更多苦難。"},{"en":"Without international aid means if help from other countries or organisations were not available.","zh":"“Without international aid” 指如果來自其他國家或組織的幫助不存在。"},{"en":"Without international aid, disaster-hit communities may lack food, medicine, and shelter.","zh":"沒有國際援助，受災社區可能缺乏食物、藥物和住所。"},{"en":"A hospital in crisis may close without international aid.","zh":"危機中的醫院沒有國際援助可能關閉。"},{"en":"The phrase describes a situation where outside help is absent.","zh":"這個短語描述缺乏外部幫助的情況。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":20},{"front":"experience enormous suffering","meaning":"經歷巨大苦難","examples":[{"en":"Some scholars believe Africans would experience enormous suffering without aid.","zh":"一些學者認為，沒有援助，非洲人會經歷巨大苦難。"},{"en":"To experience enormous suffering means to go through very great pain, hardship, or loss.","zh":"“Experience enormous suffering” 指經歷非常巨大的痛苦、困難或損失。"},{"en":"Refugees may experience enormous suffering when they lack food, safety, and medical care.","zh":"當難民缺乏食物、安全和醫療照顧時，他們可能經歷巨大苦難。"},{"en":"A community can experience enormous suffering after war destroys homes and hospitals.","zh":"戰爭摧毀房屋和醫院後，社區可能經歷巨大苦難。"},{"en":"The phrase emphasises the scale and seriousness of human pain.","zh":"這個短語強調人類痛苦的規模和嚴重性。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":20},{"front":"choose two letters","meaning":"選擇兩個字母","examples":[{"en":"Students choose two letters from the options.","zh":"學生從選項中選擇兩個字母。"},{"en":"Choose two letters means select two answer choices, usually from A, B, C, D, or E.","zh":"“Choose two letters” 指選擇兩個答案選項，通常來自 A、B、C、D 或 E。"},{"en":"In a reading question, students may choose two letters that match the writer’s opinion.","zh":"在閱讀題中，學生可能選擇兩個符合作者觀點的字母。"},{"en":"If the instruction says choose two letters, writing only one answer will lose marks.","zh":"如果指示說選擇兩個字母，只寫一個答案會失分。"},{"en":"The phrase is a common exam instruction.","zh":"這個短語是常見考試指示。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":20},{"front":"writer support","meaning":"作者支持","examples":[{"en":"The question asks which statements the writer supports.","zh":"題目問作者支持哪些陳述。"},{"en":"Writer support means the writer agrees with or presents evidence for an idea.","zh":"“Writer support” 指作者同意某個想法或為其提供證據。"},{"en":"In reading exams, students must identify which view the writer supports, not their own opinion.","zh":"在閱讀考試中，學生必須判斷作者支持哪個觀點，而不是自己的意見。"},{"en":"A writer may support a statement by giving examples, statistics, or expert opinions.","zh":"作者可能透過例子、統計數據或專家意見支持一個陳述。"},{"en":"The phrase is useful for understanding opinion-based questions.","zh":"這個短語有助理解觀點類題目。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":20},{"front":"ignore the role of","meaning":"忽視……的作用","examples":[{"en":"Some critics say Moyo has ignored the role of geography.","zh":"一些批評者說 Moyo 忽視了地理因素的作用。"},{"en":"To ignore the role of something means to fail to consider how important it is.","zh":"“Ignore the role of” 某事指未能考慮它的重要性。"},{"en":"A school should not ignore the role of sleep in student performance.","zh":"學校不應忽視睡眠在學生表現中的作用。"},{"en":"If a policy ignores the role of poverty, it may blame individuals unfairly.","zh":"如果政策忽視貧窮的作用，它可能不公平地責怪個人。"},{"en":"The phrase criticises an explanation for missing an important factor.","zh":"這個短語批評一個解釋遺漏重要因素。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":20},{"front":"role of geography","meaning":"地理因素的作用","examples":[{"en":"The role of geography may be important in African poverty.","zh":"地理因素的作用在非洲貧窮問題中可能很重要。"},{"en":"The role of geography means the influence of location, land, climate, distance, and natural features.","zh":"地理因素的作用指位置、土地、氣候、距離和自然特徵的影響。"},{"en":"The role of geography is clear when mountain villages are harder to reach.","zh":"當山區村莊較難到達時，地理因素的作用很明顯。"},{"en":"In trade, the role of geography can affect transport costs and market access.","zh":"在貿易中，地理因素的作用可以影響運輸成本和市場接觸。"},{"en":"The phrase explains how physical place shapes human problems.","zh":"這個短語解釋實體地方如何塑造人類問題。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":20},{"front":"convincing evidence","meaning":"有說服力的證據","examples":[{"en":"Critics argue that convincing evidence is lacking in Moyo’s theory.","zh":"批評者認為 Moyo 的理論缺乏有說服力的證據。"},{"en":"Convincing evidence is strong information that makes an argument believable.","zh":"有說服力的證據是令論點可信的有力資料。"},{"en":"A claim about health needs convincing evidence from careful research.","zh":"關於健康的主張需要來自嚴謹研究的有說服力證據。"},{"en":"Photos, records, and witness statements can provide convincing evidence in an investigation.","zh":"照片、紀錄和證人陳述可以在調查中提供有說服力的證據。"},{"en":"The phrase means evidence that is strong enough to persuade a reasonable reader.","zh":"這個短語指足以說服理性讀者的有力證據。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":20},{"front":"be lacking in","meaning":"在……中缺乏","examples":[{"en":"Convincing evidence is lacking in Moyo’s argument.","zh":"Moyo 的論點中缺乏有說服力的證據。"},{"en":"To be lacking in something means not to have enough of it.","zh":"“Be lacking in” 某事指沒有足夠的該事物。"},{"en":"The essay is lacking in examples, so the ideas feel vague.","zh":"這篇作文缺乏例子，所以想法感覺空泛。"},{"en":"A diet lacking in vegetables may not provide enough vitamins.","zh":"缺乏蔬菜的飲食可能不能提供足夠維他命。"},{"en":"The phrase identifies what is missing or insufficient.","zh":"這個短語指出缺少或不足的東西。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":21},{"front":"political leaders","meaning":"政治領袖","examples":[{"en":"The option refers to political leaders in Africa.","zh":"該選項提到非洲的政治領袖。"},{"en":"Political leaders are people who guide, govern, or influence public decision-making.","zh":"政治領袖是指引、管治或影響公共決策的人。"},{"en":"Political leaders may include presidents, ministers, legislators, and party heads.","zh":"政治領袖可能包括總統、部長、立法者和政黨領袖。"},{"en":"Honest political leaders can build public trust through fair decisions.","zh":"誠實的政治領袖可以透過公平決策建立公眾信任。"},{"en":"The phrase focuses on people with political authority or influence.","zh":"這個短語強調有政治權威或影響力的人。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":21},{"front":"agree with someone’s analysis","meaning":"同意某人的分析","examples":[{"en":"Some political leaders agree with Moyo’s analysis.","zh":"一些政治領袖同意 Moyo 的分析。"},{"en":"To agree with someone’s analysis means to accept their explanation of a problem or situation.","zh":"“Agree with someone’s analysis” 指接受某人對問題或情況的解釋。"},{"en":"The manager agreed with the accountant’s analysis of rising costs.","zh":"經理同意會計師對成本上升的分析。"},{"en":"Students may agree with a writer’s analysis but still question the solution.","zh":"學生可能同意作者的分析，但仍質疑解決方案。"},{"en":"The phrase means accepting the reasoning, not necessarily every detail.","zh":"這個短語指接受推理，不一定接受每個細節。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":21},{"front":"useful discussion","meaning":"有用的討論","examples":[{"en":"Moyo’s book has generated useful discussion about Africa.","zh":"Moyo 的書引發了關於非洲的有用討論。"},{"en":"Useful discussion is conversation that helps people understand a problem, compare views, or think of solutions.","zh":"有用的討論是幫助人理解問題、比較觀點或思考解決方案的談話。"},{"en":"A class debate becomes useful discussion when students listen and give reasons.","zh":"當學生聆聽並給出理由時，課堂辯論會成為有用的討論。"},{"en":"Useful discussion can reveal weak points in a plan before mistakes happen.","zh":"有用的討論可以在錯誤發生前揭示計劃中的弱點。"},{"en":"The phrase suggests conversation with practical or educational value.","zh":"這個短語暗示具有實用或教育價值的對話。"}],"source":"162 - IS AID HURTING AFRICA?.pdf","sourcePage":21}],"ielts/reading/passage-2/Practice 163":[{"front":"freshwater","meaning":"淡水","examples":[{"en":"The passage discusses the growing global crisis in freshwater supply.","zh":"文章討論了淡水供應日益嚴重的全球危機。"},{"en":"Freshwater is water with very little salt, so people can use it for drinking, washing, and growing food.","zh":"淡水是含鹽量很低的水，因此人們可以用它來飲用、清洗和種植食物。"},{"en":"A village without freshwater may need trucks to bring clean water every week.","zh":"沒有淡水的村莊可能需要貨車每週運送乾淨食水。"},{"en":"When rivers dry up, freshwater becomes harder to find and more expensive to supply.","zh":"當河流乾涸時，淡水變得更難取得，供應成本也更高。"},{"en":"Lakes, rivers, and groundwater are common sources of freshwater.","zh":"湖泊、河流和地下水是常見的淡水來源。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":1},{"front":"as in","meaning":"正如在……一樣","examples":[{"en":"As in New Delhi and Phoenix, policymakers worldwide influence water management.","zh":"正如在新德里和鳳凰城一樣，全球政策制定者都影響水資源管理。"},{"en":"As in means “in the same way as” when we compare one place, case, or situation with another.","zh":"as in 意思是「正如……一樣」，用來比較一個地方、個案或情況與另一個相同。"},{"en":"As in many schools, this library asks students to keep quiet while studying.","zh":"正如在很多學校一樣，這間圖書館要求學生溫習時保持安靜。"},{"en":"As in hospitals, restaurants must follow strict hygiene rules to protect people’s health.","zh":"正如在醫院一樣，餐廳必須遵守嚴格的衞生規則，以保障人們健康。"},{"en":"We use as in to show that one example follows the same pattern as another.","zh":"我們使用 as in 來表示一個例子跟另一個有相同模式。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":1},{"front":"policymakers worldwide","meaning":"全球政策制定者","examples":[{"en":"Policymakers worldwide wield great power over water resources.","zh":"全球政策制定者對水資源掌握巨大權力。"},{"en":"Policymakers worldwide are government leaders and officials in many countries who make important public rules.","zh":"全球政策制定者是許多國家中制定重要公共規則的政府領袖和官員。"},{"en":"Policymakers worldwide decide how schools, hospitals, transport systems, and water services should be run.","zh":"全球政策制定者決定學校、醫院、交通系統和供水服務應如何運作。"},{"en":"When policymakers worldwide ignore climate risks, cities may become less prepared for droughts and floods.","zh":"當全球政策制定者忽視氣候風險，城市可能更難準備應對乾旱和洪水。"},{"en":"Good decisions by policymakers worldwide can improve daily life for millions of people.","zh":"全球政策制定者作出良好決定，可以改善數以百萬計人的日常生活。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":1},{"front":"wield great power over","meaning":"對……掌握巨大權力","examples":[{"en":"Governments wield great power over how water resources are managed.","zh":"政府對水資源如何被管理掌握巨大權力。"},{"en":"To wield great power over something means to have strong control or influence over it.","zh":"wield great power over something 指對某事有強大的控制力或影響力。"},{"en":"A school principal can wield great power over school rules, timetables, and student discipline.","zh":"校長可以對校規、時間表和學生紀律掌握巨大權力。"},{"en":"Companies that control popular apps may wield great power over what information people see.","zh":"控制熱門應用程式的公司可能對人們看到甚麼資訊掌握巨大權力。"},{"en":"People who wield great power over public services should use that power responsibly.","zh":"對公共服務掌握巨大權力的人應負責任地使用權力。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":1},{"front":"water resources","meaning":"水資源","examples":[{"en":"Water resources must be managed wisely as demand increases.","zh":"隨着需求增加，水資源必須被明智管理。"},{"en":"Water resources are the supplies of water that people, farms, businesses, and ecosystems can use.","zh":"水資源是人類、農場、企業和生態系統可使用的水供應。"},{"en":"Rivers, lakes, reservoirs, rainwater, and groundwater are all important water resources.","zh":"河流、湖泊、水庫、雨水和地下水都是重要水資源。"},{"en":"If water resources are polluted, communities may lose safe drinking water.","zh":"如果水資源受到污染，社區可能失去安全飲用水。"},{"en":"Protecting water resources means saving enough clean water for both people and nature.","zh":"保護水資源意思是為人類和自然都保留足夠乾淨的水。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":1},{"front":"be managed","meaning":"被管理","examples":[{"en":"Water resources are managed differently in different countries.","zh":"水資源在不同國家以不同方式被管理。"},{"en":"If something is managed, people plan, control, and organise how it is used.","zh":"如果某事物 is managed，意思是人們計劃、控制和組織它如何被使用。"},{"en":"A school library is managed by deciding when it opens and how books are borrowed.","zh":"學校圖書館透過決定開放時間和借書方式被管理。"},{"en":"If money is not managed carefully, a family may struggle to pay bills.","zh":"如果金錢沒有被謹慎管理，家庭可能難以支付帳單。"},{"en":"Natural resources should be managed so that they do not run out too quickly.","zh":"自然資源應被管理，以免太快耗盡。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":1},{"front":"wise use of","meaning":"明智運用","examples":[{"en":"Wise use of political power will become increasingly important.","zh":"明智運用政治權力將變得越來越重要。"},{"en":"Wise use of something means using it carefully, sensibly, and for a good purpose.","zh":"wise use of something 指謹慎、合理並為良好目的使用某事物。"},{"en":"Wise use of study time means reviewing difficult points before doing easy exercises.","zh":"明智運用溫習時間，意思是先複習困難重點，再做容易練習。"},{"en":"Wise use of money can help a family avoid debt and save for emergencies.","zh":"明智運用金錢可以幫助家庭避免債務，並為緊急情況儲蓄。"},{"en":"Wise use of water means not wasting it when supplies are limited.","zh":"明智運用水資源意思是在供應有限時不浪費水。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":1},{"front":"become increasingly important","meaning":"變得越來越重要","examples":[{"en":"Water management will become increasingly important as the years go by.","zh":"隨着歲月過去，水資源管理將變得越來越重要。"},{"en":"Become increasingly important means to matter more and more over time.","zh":"become increasingly important 指隨時間變得越來越重要。"},{"en":"Digital skills become increasingly important as more jobs require computers.","zh":"隨着更多工作需要電腦，數碼技能變得越來越重要。"},{"en":"Exercise may become increasingly important as people get older and want to stay healthy.","zh":"當人們年紀漸長並希望保持健康，運動可能變得越來越重要。"},{"en":"This phrase is useful when a problem or need grows gradually.","zh":"當某個問題或需要逐漸增加時，這個片語很有用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":1},{"front":"as the years go by","meaning":"隨着歲月過去","examples":[{"en":"The need for careful water planning will grow as the years go by.","zh":"隨着歲月過去，謹慎水資源規劃的需要將會增加。"},{"en":"As the years go by means as time passes over many years.","zh":"as the years go by 指多年時間逐漸過去。"},{"en":"As the years go by, children often understand their parents’ advice more clearly.","zh":"隨着歲月過去，孩子往往更清楚理解父母的建議。"},{"en":"A building may need more repairs as the years go by.","zh":"隨着歲月過去，一座建築物可能需要更多維修。"},{"en":"This phrase often describes slow change, ageing, or gradual development.","zh":"這個片語常描述緩慢變化、老化或逐步發展。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":1},{"front":"demand for freshwater","meaning":"對淡水的需求","examples":[{"en":"The world’s demand for freshwater is rising rapidly.","zh":"世界對淡水的需求正迅速上升。"},{"en":"Demand for freshwater means the amount of clean, low-salt water that people need or want to use.","zh":"demand for freshwater 指人們需要或想使用的乾淨低鹽水的數量。"},{"en":"Demand for freshwater rises when a city grows and more homes need tap water.","zh":"當城市發展、更多家庭需要自來水時，對淡水的需求會上升。"},{"en":"Farming can increase demand for freshwater because crops need regular irrigation.","zh":"農業可以增加對淡水的需求，因為農作物需要定期灌溉。"},{"en":"If demand for freshwater rises faster than supply, shortages may occur.","zh":"如果對淡水的需求升得比供應更快，便可能出現短缺。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":1},{"front":"overtake its ready supply","meaning":"超過其現有供應","examples":[{"en":"Freshwater demand is overtaking its ready supply in many places.","zh":"在許多地方，淡水需求正超過其現有供應。"},{"en":"To overtake its ready supply means demand becomes greater than the amount immediately available.","zh":"overtake its ready supply 指需求變得大於可立即取得的數量。"},{"en":"A shop’s orders may overtake its ready supply if a product suddenly becomes popular.","zh":"如果某件產品突然受歡迎，商店訂單可能超過其現有供應。"},{"en":"When a city grows too quickly, housing demand can overtake its ready supply.","zh":"當城市發展太快，住房需求可能超過其現有供應。"},{"en":"If demand overtakes ready supply, people may have to wait, pay more, or use less.","zh":"如果需求超過現有供應，人們可能要等待、付更多錢或減少使用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":1},{"front":"ready supply","meaning":"現成供應","examples":[{"en":"The ready supply of freshwater is no longer enough in many regions.","zh":"在許多地區，淡水的現成供應已不再足夠。"},{"en":"Ready supply means the amount of something that is already available for use.","zh":"ready supply 指某物已經可供使用的數量。"},{"en":"A hospital needs a ready supply of masks, gloves, and medicine for emergencies.","zh":"醫院需要有口罩、手套和藥物的現成供應，以應付緊急情況。"},{"en":"If a bakery has no ready supply of flour, it cannot make bread quickly.","zh":"如果麵包店沒有麵粉的現成供應，就不能快速製作麵包。"},{"en":"Ready supply is different from future supply because it can be used now.","zh":"現成供應不同於未來供應，因為它現在就可以使用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":2},{"front":"in many places","meaning":"在許多地方","examples":[{"en":"Freshwater demand is exceeding supply in many places.","zh":"在許多地方，淡水需求正超過供應。"},{"en":"In many places means in a large number of areas, cities, or countries.","zh":"in many places 指在大量地區、城市或國家。"},{"en":"In many places, students now use tablets instead of paper textbooks.","zh":"在許多地方，學生現在使用平板電腦而不是紙本教科書。"},{"en":"In many places, rent has risen because housing supply is limited.","zh":"在許多地方，租金因住房供應有限而上升。"},{"en":"This phrase is useful when a problem is not limited to one location.","zh":"當問題不只限於一個地點時，這個片語很有用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":2},{"front":"show no sign of abating","meaning":"沒有減弱的跡象","examples":[{"en":"The freshwater crisis shows no sign of abating.","zh":"淡水危機沒有減弱的跡象。"},{"en":"Show no sign of abating means there is no evidence that a problem is becoming weaker or less serious.","zh":"show no sign of abating 指沒有證據顯示問題正在減弱或變得不那麼嚴重。"},{"en":"The traffic jam showed no sign of abating even after the rush hour ended.","zh":"即使繁忙時間結束，交通擠塞仍沒有減弱的跡象。"},{"en":"If price rises show no sign of abating, families may reduce non-essential spending.","zh":"如果物價上升沒有減弱的跡象，家庭可能會減少非必要開支。"},{"en":"We use this phrase when a bad situation continues strongly.","zh":"當壞情況持續強烈時，我們使用這個片語。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":2},{"front":"that the problem is well-known","meaning":"這個問題眾所周知","examples":[{"en":"That the problem is well-known makes it no less disturbing.","zh":"這個問題眾所周知，但這並不令它不那麼令人不安。"},{"en":"That the problem is well-known means the fact that many people already know about the problem.","zh":"that the problem is well-known 指許多人已經知道這個問題這件事。"},{"en":"That the problem is well-known does not mean leaders have solved it.","zh":"這個問題眾所周知，並不代表領袖已經解決它。"},{"en":"That the problem is well-known can create pressure on schools, companies, or governments to act.","zh":"這個問題眾所周知，可能對學校、公司或政府造成採取行動的壓力。"},{"en":"This structure often turns a whole idea into the subject of a sentence.","zh":"這種句子結構常把整個概念變成句子的主語。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":2},{"front":"no less disturbing","meaning":"同樣令人不安","examples":[{"en":"The shortage is no less disturbing simply because it is well known.","zh":"短缺不會只因為眾所周知就變得不那麼令人不安。"},{"en":"No less disturbing means still equally worrying, even when there is a reason people might ignore it.","zh":"no less disturbing 指即使有人可能因此忽略它，它仍同樣令人擔憂。"},{"en":"A familiar safety problem is no less disturbing just because people see it every day.","zh":"一個熟悉的安全問題不會只因人們每天看見它就不令人不安。"},{"en":"A child’s repeated illness is no less disturbing because the family expected it.","zh":"孩子反覆生病，不會因家人早有預期就不令人不安。"},{"en":"This phrase reminds readers that common problems can still be serious.","zh":"這個片語提醒讀者，常見問題仍然可以很嚴重。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":2},{"front":"more than a billion people","meaning":"超過十億人","examples":[{"en":"More than a billion people lack adequate access to safe freshwater.","zh":"超過十億人缺乏足夠途徑取得安全淡水。"},{"en":"More than a billion people means a number greater than one thousand million people.","zh":"more than a billion people 指超過十億人口。"},{"en":"More than a billion people using a service means it affects a huge part of the world.","zh":"如果超過十億人使用某項服務，意思是它影響世界很大一部分。"},{"en":"If more than a billion people face a problem, governments cannot treat it as small.","zh":"如果超過十億人面對某個問題，政府不能把它視為小問題。"},{"en":"This phrase is used to show a very large human scale.","zh":"這個片語用來顯示非常龐大的人口規模。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":2},{"front":"one in six worldwide","meaning":"全球六人中有一人","examples":[{"en":"One in six worldwide lacks adequate access to safe freshwater.","zh":"全球六人中有一人缺乏足夠途徑取得安全淡水。"},{"en":"One in six worldwide means one person out of every six people in the world.","zh":"one in six worldwide 指全世界每六個人中有一個。"},{"en":"If one in six students fails an exam, the school should ask why so many struggled.","zh":"如果每六個學生中有一個考試不合格，學校應該了解為何這麼多人有困難。"},{"en":"One in six worldwide is a clear way to explain a percentage in human terms.","zh":"one in six worldwide 是用人的角度清楚解釋百分比的方法。"},{"en":"This phrase helps readers imagine how common a problem is.","zh":"這個片語幫助讀者想像問題有多普遍。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":2},{"front":"lack adequate access to","meaning":"缺乏足夠途徑取得","examples":[{"en":"Many people lack adequate access to safe freshwater.","zh":"許多人缺乏足夠途徑取得安全淡水。"},{"en":"To lack adequate access to something means not having enough chances or ability to get and use it.","zh":"lack adequate access to something 指沒有足夠機會或能力取得並使用某物。"},{"en":"Children in remote villages may lack adequate access to good schools.","zh":"偏遠村莊的孩子可能缺乏足夠途徑取得良好教育。"},{"en":"Patients may suffer if they lack adequate access to doctors and medicine.","zh":"如果病人缺乏足夠途徑取得醫生和藥物，他們可能會受苦。"},{"en":"A service may exist, but people still lack adequate access to it if it is too far away or too expensive.","zh":"某項服務可能存在，但如果太遠或太貴，人們仍可能缺乏足夠途徑取得它。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":2},{"front":"safe freshwater","meaning":"安全淡水","examples":[{"en":"Safe freshwater is still unavailable to many people.","zh":"安全淡水對許多人來說仍然無法取得。"},{"en":"Safe freshwater is clean water with very little salt that people can use without becoming ill.","zh":"safe freshwater 是乾淨、含鹽量很低，而且人們使用後不會生病的水。"},{"en":"A school needs safe freshwater so students can drink, wash their hands, and stay healthy.","zh":"學校需要安全淡水，讓學生飲用、洗手和保持健康。"},{"en":"If floods pollute wells, safe freshwater may disappear for several days.","zh":"如果洪水污染水井，安全淡水可能會消失數天。"},{"en":"Safe freshwater is basic, but many communities still cannot depend on it.","zh":"安全淡水是基本需要，但許多社區仍不能穩定依賴它。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":2},{"front":"according to data released by","meaning":"根據……發布的數據","examples":[{"en":"According to data released by the United Nations, many countries will face water stress.","zh":"根據聯合國發布的數據，許多國家將面對水資源壓力。"},{"en":"According to data released by means the statement is based on information officially published by a group or organisation.","zh":"according to data released by 指某個說法是根據某個團體或機構正式發布的資料。"},{"en":"According to data released by the school, fewer students were absent this term.","zh":"根據學校發布的數據，本學期缺席學生較少。"},{"en":"According to data released by the hospital, waiting times fell after more nurses were hired.","zh":"根據醫院發布的數據，聘請更多護士後，輪候時間下降。"},{"en":"This phrase is useful when you want to show the source of a factual claim.","zh":"當你想顯示事實說法的來源時，這個片語很有用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":2},{"front":"the United Nations","meaning":"聯合國","examples":[{"en":"The United Nations has released data on freshwater resources.","zh":"聯合國已發布關於淡水資源的數據。"},{"en":"The United Nations is an international organisation where countries discuss global problems and cooperation.","zh":"聯合國是一個國際組織，各國在其中討論全球問題和合作。"},{"en":"The United Nations often reports on issues such as health, poverty, education, and climate change.","zh":"聯合國經常報告健康、貧窮、教育和氣候變化等議題。"},{"en":"When many countries face the same problem, the United Nations can help coordinate discussion.","zh":"當許多國家面對同一個問題時，聯合國可以協助協調討論。"},{"en":"Reports from the United Nations are often used to describe worldwide trends.","zh":"聯合國的報告常用來描述全球趨勢。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":2},{"front":"across the globe","meaning":"遍及全球","examples":[{"en":"Freshwater resources are under pressure across the globe.","zh":"淡水資源在全球各地都承受壓力。"},{"en":"Across the globe means all over the world or in many countries.","zh":"across the globe 指全世界或許多國家。"},{"en":"People across the globe use smartphones to study, work, and communicate.","zh":"全球各地的人使用智能電話學習、工作和溝通。"},{"en":"If food prices rise across the globe, poor families may suffer most.","zh":"如果食品價格遍及全球上升，貧困家庭可能最受影響。"},{"en":"This phrase makes a statement sound international rather than local.","zh":"這個片語令說法聽起來是國際性的，而不是本地性的。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":3},{"front":"undergo stress","meaning":"承受壓力","examples":[{"en":"Many countries’ freshwater resources will undergo stress by 2025.","zh":"到2025年，許多國家的淡水資源將承受壓力。"},{"en":"To undergo stress means to experience pressure, strain, or difficulty.","zh":"undergo stress 指經歷壓力、負荷或困難。"},{"en":"A bridge may undergo stress when too many heavy trucks cross it every day.","zh":"如果太多重型貨車每天經過，一條橋可能會承受壓力。"},{"en":"Students undergo stress when exams, homework, and family expectations all increase at once.","zh":"當考試、功課和家庭期望同時增加，學生會承受壓力。"},{"en":"Water systems undergo stress when demand rises but supply stays the same.","zh":"當需求上升但供應不變，供水系統便會承受壓力。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":3},{"front":"water stress","meaning":"水資源壓力","examples":[{"en":"Water stress occurs when demand increasingly exceeds available safe water.","zh":"當需求逐漸超過可用安全水量時，就會出現水資源壓力。"},{"en":"Water stress is a situation in which people need more water than the safe supply can easily provide.","zh":"water stress 是指人們需要的水比安全供應能輕易提供的更多。"},{"en":"A city may face water stress during a long dry season.","zh":"城市在漫長旱季可能面對水資源壓力。"},{"en":"Water stress can lead to restrictions on washing cars, watering gardens, or irrigating farms.","zh":"水資源壓力可能導致限制洗車、澆花或農田灌溉。"},{"en":"Water stress is not always total shortage, but it means the system is under pressure.","zh":"水資源壓力不一定是完全短缺，但意思是系統正承受壓力。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":3},{"front":"demand more water than is available","meaning":"需求超過可用水量","examples":[{"en":"People increasingly demand more water than is available or safe for use.","zh":"人們越來越需求超過可用或可安全使用水量的水。"},{"en":"To demand more water than is available means to need or use more water than the supply can provide.","zh":"demand more water than is available 指需要或使用的水超過供應能提供的數量。"},{"en":"A hotel area may demand more water than is available during the tourist season.","zh":"旅遊季節時，酒店區可能需求超過可用水量。"},{"en":"Farms may demand more water than is available when rainfall is too low.","zh":"當降雨太少時，農場可能需求超過可用水量。"},{"en":"If people demand more water than is available, authorities may have to limit use.","zh":"如果人們需求超過可用水量，當局可能必須限制使用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":3},{"front":"safe for use","meaning":"可安全使用的","examples":[{"en":"Not all available water is safe for use.","zh":"並非所有可用的水都是可安全使用的。"},{"en":"Safe for use means something can be used without causing harm.","zh":"safe for use 指某物可以使用而不會造成傷害。"},{"en":"After a flood, tap water may not be safe for use until it is tested.","zh":"洪水後，自來水在檢測前可能不可安全使用。"},{"en":"Medicine must be checked carefully before it is considered safe for use.","zh":"藥物必須經仔細檢查，才被視為可安全使用。"},{"en":"Water may look clear but still not be safe for use if it contains bacteria.","zh":"水看起來可能清澈，但如果含有細菌，仍未必可安全使用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":3},{"front":"outright shortages","meaning":"徹底短缺；嚴重短缺","examples":[{"en":"Some countries will face outright shortages of freshwater.","zh":"一些國家將面對淡水的嚴重短缺。"},{"en":"Outright shortages are clear and serious situations where there is simply not enough of something.","zh":"outright shortages 是清楚而嚴重的情況，當中某物根本不足。"},{"en":"A pharmacy may face outright shortages of medicine during a health crisis.","zh":"在健康危機期間，藥房可能面對藥物的嚴重短缺。"},{"en":"Outright shortages of food can cause prices to rise and families to panic.","zh":"食物嚴重短缺可能導致價格上升和家庭恐慌。"},{"en":"This phrase is stronger than “limited supply” because the lack is obvious and severe.","zh":"這個片語比「供應有限」更強，因為短缺明顯而嚴重。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":3},{"front":"by mid-century","meaning":"到本世紀中葉","examples":[{"en":"By mid-century, many more people may face freshwater scarcity.","zh":"到本世紀中葉，更多人可能面對淡水短缺。"},{"en":"By mid-century means by the middle of the current century, around the 2050s.","zh":"by mid-century 指到本世紀中段，大約2050年代。"},{"en":"By mid-century, many cities may need stronger flood defences.","zh":"到本世紀中葉，許多城市可能需要更強的防洪設施。"},{"en":"If emissions remain high, heatwaves may become more dangerous by mid-century.","zh":"如果排放維持高水平，到本世紀中葉，熱浪可能變得更危險。"},{"en":"This phrase is often used when discussing long-term future changes.","zh":"這個片語常用於討論長遠未來變化。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":3},{"front":"as much as three-quarters of","meaning":"高達四分之三的……","examples":[{"en":"As much as three-quarters of the Earth’s population could face freshwater scarcity.","zh":"高達四分之三的地球人口可能面對淡水短缺。"},{"en":"As much as three-quarters of means a surprisingly large amount, up to 75 percent.","zh":"as much as three-quarters of 指數量大得驚人，最多可達75%。"},{"en":"As much as three-quarters of a class may choose online lessons during bad weather.","zh":"惡劣天氣期間，高達四分之三的班級學生可能選擇網上課堂。"},{"en":"If as much as three-quarters of a budget goes to rent, little money remains for food or transport.","zh":"如果高達四分之三的預算用於租金，用於食物或交通的錢便所剩無幾。"},{"en":"This phrase stresses that the amount may be very high.","zh":"這個片語強調數量可能非常高。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":3},{"front":"the Earth’s population","meaning":"地球人口","examples":[{"en":"The Earth’s population may face growing pressure on freshwater supplies.","zh":"地球人口可能面對淡水供應上日益增加的壓力。"},{"en":"The Earth’s population means all the people living on the planet.","zh":"the Earth’s population 指生活在地球上的所有人。"},{"en":"The Earth’s population needs food, water, homes, transport, and energy every day.","zh":"地球人口每天都需要食物、水、住房、交通和能源。"},{"en":"As the Earth’s population grows, demand for land and resources increases.","zh":"隨着地球人口增長，對土地和資源的需求也增加。"},{"en":"This phrase is used when discussing humanity as a whole.","zh":"當討論全人類時，會使用這個片語。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":3},{"front":"face scarcities of","meaning":"面對……短缺","examples":[{"en":"Many people could face scarcities of freshwater.","zh":"許多人可能面對淡水短缺。"},{"en":"To face scarcities of something means to experience a lack of enough supply.","zh":"face scarcities of something 指經歷某物供應不足。"},{"en":"Hospitals may face scarcities of beds during a serious flu season.","zh":"在嚴重流感季節，醫院可能面對床位短缺。"},{"en":"Schools can face scarcities of teachers if many staff leave at the same time.","zh":"如果許多員工同時離職，學校可能面對教師短缺。"},{"en":"When communities face scarcities of basic goods, daily life becomes harder.","zh":"當社區面對基本物品短缺，日常生活會變得更困難。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":3},{"front":"water scarcity","meaning":"水資源短缺","examples":[{"en":"Scientists expect water scarcity to become more common.","zh":"科學家預期水資源短缺會變得更常見。"},{"en":"Water scarcity is a situation in which there is not enough usable water for people’s needs.","zh":"water scarcity 是指沒有足夠可用水滿足人們需要的情況。"},{"en":"Water scarcity may force families to store water carefully at home.","zh":"水資源短缺可能迫使家庭在家中小心儲水。"},{"en":"Long droughts and rising demand can make water scarcity worse.","zh":"長期乾旱和需求上升可以令水資源短缺惡化。"},{"en":"Water scarcity affects health, farming, schools, and local businesses.","zh":"水資源短缺影響健康、農業、學校和本地企業。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":3},{"front":"become more common","meaning":"變得更常見","examples":[{"en":"Water scarcity is expected to become more common in the future.","zh":"水資源短缺預期在未來會變得更常見。"},{"en":"Become more common means to happen more often or appear in more places.","zh":"become more common 指更頻繁發生或在更多地方出現。"},{"en":"Online meetings became more common when many people started working from home.","zh":"當許多人開始在家工作，網上會議變得更常見。"},{"en":"If summers become hotter, heat warnings may become more common.","zh":"如果夏天變得更熱，高溫警告可能變得更常見。"},{"en":"This phrase describes a trend that is increasing.","zh":"這個片語描述正在增加的趨勢。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":4},{"front":"in large part because","meaning":"很大程度上因為","examples":[{"en":"Water scarcity will increase in large part because population and wealth are rising.","zh":"水資源短缺將增加，很大程度上因為人口和財富正在上升。"},{"en":"In large part because means mainly because, though there may also be other reasons.","zh":"in large part because 指主要因為某個原因，雖然也可能有其他原因。"},{"en":"The café became popular in large part because its staff were friendly.","zh":"這間咖啡店變得受歡迎，很大程度上因為員工友善。"},{"en":"Students improved in large part because they practised a little every day.","zh":"學生進步，很大程度上因為他們每天稍作練習。"},{"en":"This phrase is useful when one reason explains much, but not all, of the result.","zh":"當一個原因解釋了大部分但不是全部結果時，這個片語很有用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":4},{"front":"the world’s population is rising","meaning":"世界人口正在上升","examples":[{"en":"The world’s population is rising, increasing the demand for water.","zh":"世界人口正在上升，增加了對水的需求。"},{"en":"The world’s population is rising means the total number of people on Earth is increasing.","zh":"the world’s population is rising 指地球上的總人口正在增加。"},{"en":"When the world’s population is rising, more homes, schools, hospitals, and farms are needed.","zh":"當世界人口正在上升，就需要更多住房、學校、醫院和農場。"},{"en":"If the world’s population is rising quickly, governments must plan resources carefully.","zh":"如果世界人口迅速上升，政府必須謹慎規劃資源。"},{"en":"This phrase often explains why pressure on food, water, and land increases.","zh":"這個片語常用來解釋為何食物、水和土地壓力增加。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":4},{"front":"expand demand","meaning":"擴大需求","examples":[{"en":"Rising wealth can expand demand for freshwater.","zh":"財富增加可以擴大對淡水的需求。"},{"en":"To expand demand means to increase the amount that people want or need.","zh":"expand demand 指增加人們想要或需要的數量。"},{"en":"A new shopping mall can expand demand for parking spaces nearby.","zh":"新商場可以擴大附近對泊車位的需求。"},{"en":"Better internet access may expand demand for online courses.","zh":"更好的互聯網連接可能擴大對網上課程的需求。"},{"en":"When incomes rise, families may buy more goods, which can expand demand for energy and water.","zh":"當收入上升，家庭可能購買更多商品，這可以擴大對能源和水的需求。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":4},{"front":"global climate change","meaning":"全球氣候變化","examples":[{"en":"Global climate change is worsening water shortages in many regions.","zh":"全球氣候變化正在令許多地區的水短缺惡化。"},{"en":"Global climate change refers to long-term changes in Earth’s weather patterns, including temperature and rainfall.","zh":"global climate change 指地球天氣模式的長期變化，包括氣溫和降雨。"},{"en":"Global climate change can make some areas hotter, drier, or more likely to flood.","zh":"全球氣候變化可以令某些地區更熱、更乾或更容易水浸。"},{"en":"Farmers may struggle when global climate change makes seasons less predictable.","zh":"當全球氣候變化令季節更難預測時，農民可能會遇到困難。"},{"en":"This phrase is used for a worldwide environmental problem, not just local weather.","zh":"這個片語用於全球性的環境問題，而不只是本地天氣。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":4},{"front":"exacerbate aridity","meaning":"加劇乾旱","examples":[{"en":"Climate change can exacerbate aridity in dry regions.","zh":"氣候變化可以加劇乾旱地區的乾旱。"},{"en":"To exacerbate aridity means to make dryness more severe.","zh":"exacerbate aridity 指令乾燥情況更嚴重。"},{"en":"Cutting down trees can exacerbate aridity because less moisture stays in the soil.","zh":"砍伐樹木可以加劇乾旱，因為泥土保留的水分更少。"},{"en":"Long heatwaves exacerbate aridity and make crops harder to grow.","zh":"長時間熱浪會加劇乾旱，令農作物更難生長。"},{"en":"This phrase is formal and often used in environmental writing.","zh":"這個片語較正式，常用於環境寫作。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":4},{"front":"reduce supply","meaning":"減少供應","examples":[{"en":"Climate change can reduce freshwater supply in many areas.","zh":"氣候變化可以減少許多地區的淡水供應。"},{"en":"To reduce supply means to make less of something available.","zh":"reduce supply 指令可用的某物數量減少。"},{"en":"A broken road can reduce supply of food to mountain villages.","zh":"道路損壞可以減少供應到山區村莊的食物。"},{"en":"Drought can reduce supply of water for homes, farms, and factories.","zh":"乾旱可以減少家庭、農場和工廠的用水供應。"},{"en":"When supply is reduced, prices may rise and people may need to use less.","zh":"當供應減少，價格可能上升，人們可能需要少用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":4},{"front":"in many regions","meaning":"在許多地區","examples":[{"en":"Water supply is being reduced in many regions.","zh":"在許多地區，水供應正在被減少。"},{"en":"In many regions means in many large areas or parts of the world.","zh":"in many regions 指在世界上許多大範圍地區或部分。"},{"en":"In many regions, schools close during severe storms for safety.","zh":"在許多地區，學校會在嚴重風暴期間停課以保障安全。"},{"en":"In many regions, older people need better access to healthcare.","zh":"在許多地區，長者需要更好的醫療服務途徑。"},{"en":"This phrase is useful when a trend appears across several areas.","zh":"當趨勢在多個地區出現時，這個片語很有用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":4},{"front":"what is more","meaning":"此外","examples":[{"en":"What is more, many water sources are threatened by pollution.","zh":"此外，許多水源受到污染威脅。"},{"en":"What is more means “in addition” and introduces another important point.","zh":"what is more 意思是「此外」，用來引入另一個重要重點。"},{"en":"The flat is near the station; what is more, the rent is reasonable.","zh":"這個單位接近車站；此外，租金合理。"},{"en":"The plan saves money; what is more, it reduces waste.","zh":"這個計劃節省金錢；此外，它減少浪費。"},{"en":"This phrase adds extra support to an argument.","zh":"這個片語為論點加入額外支持。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":4},{"front":"water sources","meaning":"水源","examples":[{"en":"Many water sources are threatened by pollution and overuse.","zh":"許多水源受到污染和過度使用威脅。"},{"en":"Water sources are places or supplies from which people can get water.","zh":"water sources 是人們可以取得水的地方或供應。"},{"en":"Rivers, lakes, wells, reservoirs, and springs can all be water sources.","zh":"河流、湖泊、水井、水庫和泉水都可以是水源。"},{"en":"If water sources are dirty, people may need expensive treatment before drinking the water.","zh":"如果水源骯髒，人們飲用前可能需要昂貴的處理。"},{"en":"Protecting water sources is easier than cleaning them after pollution occurs.","zh":"保護水源比污染後再清理更容易。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":4},{"front":"be threatened by","meaning":"受到……威脅","examples":[{"en":"Freshwater sources are threatened by faulty waste disposal.","zh":"淡水來源受到不當廢物處理威脅。"},{"en":"To be threatened by something means to be put in danger by it.","zh":"be threatened by something 指因某事而處於危險之中。"},{"en":"Small shops may be threatened by large chains that offer lower prices.","zh":"小店可能受到提供更低價格的大型連鎖店威脅。"},{"en":"A child’s health can be threatened by dirty water and poor food.","zh":"孩子的健康可能受到污水和劣質食物威脅。"},{"en":"When forests are threatened by fire, local people may need to leave quickly.","zh":"當森林受到火災威脅時，本地居民可能需要迅速離開。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":4},{"front":"faulty waste disposal","meaning":"不當廢物處理","examples":[{"en":"Faulty waste disposal can contaminate freshwater sources.","zh":"不當廢物處理可以污染淡水來源。"},{"en":"Faulty waste disposal means rubbish or sewage is handled in an unsafe or careless way.","zh":"faulty waste disposal 指垃圾或污水以不安全或粗心的方式處理。"},{"en":"A factory practises faulty waste disposal if it releases chemicals into a river.","zh":"如果工廠把化學品排入河流，就是在進行不當廢物處理。"},{"en":"Faulty waste disposal can spread disease when dirty water reaches homes.","zh":"當污水流入住家，不當廢物處理可以傳播疾病。"},{"en":"Good waste systems prevent faulty waste disposal from harming people and nature.","zh":"良好的廢物系統可防止不當廢物處理傷害人類和自然。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":5},{"front":"industrial pollutants","meaning":"工業污染物","examples":[{"en":"Industrial pollutants can damage rivers, lakes and aquifers.","zh":"工業污染物可以破壞河流、湖泊和含水層。"},{"en":"Industrial pollutants are harmful substances produced by factories, mines, or other industrial activities.","zh":"industrial pollutants 是由工廠、礦場或其他工業活動產生的有害物質。"},{"en":"Industrial pollutants may include chemicals, metals, oil, or dirty wastewater.","zh":"工業污染物可能包括化學品、金屬、石油或骯髒廢水。"},{"en":"If industrial pollutants enter a river, fish may die and drinking water may become unsafe.","zh":"如果工業污染物流入河流，魚類可能死亡，飲用水也可能變得不安全。"},{"en":"Strict rules help stop industrial pollutants from reaching water sources.","zh":"嚴格規則有助阻止工業污染物進入水源。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":5},{"front":"fertilizer runoff","meaning":"肥料逕流","examples":[{"en":"Fertilizer runoff threatens many water sources.","zh":"肥料逕流威脅許多水源。"},{"en":"Fertilizer runoff is fertiliser washed from farms into rivers, lakes, or groundwater by rain or irrigation.","zh":"fertilizer runoff 是肥料被雨水或灌溉水從農田沖入河流、湖泊或地下水。"},{"en":"After heavy rain, fertilizer runoff may carry farm chemicals into a nearby stream.","zh":"大雨後，肥料逕流可能把農業化學品帶入附近溪流。"},{"en":"Fertilizer runoff can cause too much plant growth in lakes and reduce oxygen for fish.","zh":"肥料逕流可以令湖泊植物過度生長，並減少魚類所需氧氣。"},{"en":"Farmers can reduce fertilizer runoff by using the right amount at the right time.","zh":"農民可透過在合適時間使用合適份量來減少肥料逕流。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":5},{"front":"coastal influxes of saltwater","meaning":"沿海鹹水湧入","examples":[{"en":"Coastal influxes of saltwater can affect aquifers.","zh":"沿海鹹水湧入可以影響含水層。"},{"en":"Coastal influxes of saltwater are movements of seawater into land-based water systems near the coast.","zh":"coastal influxes of saltwater 指海水流入沿海附近的陸地水系統。"},{"en":"When too much groundwater is pumped out, coastal influxes of saltwater may enter wells.","zh":"當過量抽取地下水，沿海鹹水湧入可能進入水井。"},{"en":"Coastal influxes of saltwater can make freshwater too salty to drink or use for crops.","zh":"沿海鹹水湧入可以令淡水變得太鹹，不適合飲用或種植農作物。"},{"en":"This problem is common in low coastal areas where fresh groundwater is heavily used.","zh":"這個問題常見於大量使用淡水地下水的低窪沿海地區。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":5},{"front":"aquifers","meaning":"含水層","examples":[{"en":"Saltwater can enter aquifers when groundwater is depleted.","zh":"當地下水被耗盡時，鹹水可以進入含水層。"},{"en":"Aquifers are underground layers of rock or soil that hold water.","zh":"aquifers 是地下能儲存水的岩石或泥土層。"},{"en":"Many towns pump water from aquifers when rivers and lakes are not enough.","zh":"當河流和湖泊不足時，許多城鎮會從含水層抽水。"},{"en":"If aquifers are polluted, the damage can last for many years.","zh":"如果含水層受到污染，損害可以持續多年。"},{"en":"Aquifers are important because they store water below the ground like natural reservoirs.","zh":"含水層很重要，因為它們像天然水庫一樣在地下儲水。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":5},{"front":"groundwater is depleted","meaning":"地下水被耗盡","examples":[{"en":"Saltwater enters aquifers as groundwater is depleted.","zh":"隨着地下水被耗盡，鹹水會進入含水層。"},{"en":"Groundwater is depleted means underground water is used faster than it is naturally replaced.","zh":"groundwater is depleted 指地下水被使用的速度快過自然補充速度。"},{"en":"Groundwater is depleted when farms pump too much water during dry seasons.","zh":"當農場在旱季抽取太多水，地下水會被耗盡。"},{"en":"If groundwater is depleted, wells may become dry and villages may lose drinking water.","zh":"如果地下水被耗盡，水井可能乾涸，村莊可能失去飲用水。"},{"en":"Careful pumping limits can prevent groundwater from being depleted too quickly.","zh":"謹慎的抽水限制可以防止地下水太快被耗盡。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":5},{"front":"lack of access to","meaning":"缺乏取得……的途徑","examples":[{"en":"Lack of access to water can lead to starvation and disease.","zh":"缺乏取得水的途徑可以導致饑荒和疾病。"},{"en":"Lack of access to something means people cannot easily get or use something they need.","zh":"lack of access to something 指人們不能輕易取得或使用所需事物。"},{"en":"Lack of access to public transport can make it hard for workers to reach jobs.","zh":"缺乏取得公共交通的途徑，可以令工人難以上班。"},{"en":"Lack of access to internet services can stop students from joining online lessons.","zh":"缺乏取得互聯網服務的途徑，可以令學生無法參與網上課堂。"},{"en":"Even when a service exists, lack of access to it can keep people disadvantaged.","zh":"即使某項服務存在，缺乏取得它的途徑也會令人民處於不利。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":5},{"front":"lead to","meaning":"導致","examples":[{"en":"Water shortages can lead to starvation, disease and conflict.","zh":"水短缺可以導致饑荒、疾病和衝突。"},{"en":"To lead to something means to cause it or make it happen later.","zh":"lead to something 指造成某事或令它之後發生。"},{"en":"Poor sleep can lead to mistakes at work or school.","zh":"睡眠不足可以導致工作或學校中的錯誤。"},{"en":"Heavy rain can lead to floods if drains are blocked.","zh":"如果排水渠堵塞，大雨可以導致水浸。"},{"en":"This phrase is useful for explaining cause and effect.","zh":"這個片語很適合用來解釋因果關係。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":5},{"front":"starvation","meaning":"饑荒；飢餓","examples":[{"en":"Lack of water can lead to starvation.","zh":"缺乏水可以導致饑荒。"},{"en":"Starvation is extreme hunger caused by not having enough food for a long time.","zh":"starvation 是長時間沒有足夠食物所造成的極度飢餓。"},{"en":"A drought can cause starvation if crops fail and food prices rise.","zh":"如果農作物失收並且食品價格上升，乾旱可以造成饑荒。"},{"en":"Children are especially at risk of starvation when families lose access to food and clean water.","zh":"當家庭失去取得食物和清潔食水的途徑時，孩子尤其有饑荒風險。"},{"en":"Starvation is more serious than ordinary hunger because it can damage health or cause death.","zh":"starvation 比普通飢餓嚴重，因為它可以損害健康或導致死亡。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":5},{"front":"political instability","meaning":"政治不穩","examples":[{"en":"Water shortages can contribute to political instability.","zh":"水短缺可以促成政治不穩。"},{"en":"Political instability means a country or government is not steady, peaceful, or easy to govern.","zh":"political instability 指一個國家或政府不穩定、不和平或難以治理。"},{"en":"Political instability may occur when people lose trust in leaders and public services fail.","zh":"當人民失去對領袖的信任，而公共服務失效時，可能出現政治不穩。"},{"en":"Rising food prices can create protests and increase political instability.","zh":"食品價格上升可以引發抗議，並增加政治不穩。"},{"en":"Political instability makes long-term planning harder for schools, businesses, and families.","zh":"政治不穩令學校、企業和家庭更難作長遠規劃。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":5},{"front":"armed conflict","meaning":"武裝衝突","examples":[{"en":"Competition for water may even lead to armed conflict.","zh":"對水的競爭甚至可能導致武裝衝突。"},{"en":"Armed conflict is fighting between groups or countries using weapons.","zh":"armed conflict 是團體或國家之間使用武器的戰鬥。"},{"en":"Armed conflict can force families to leave their homes and close schools.","zh":"武裝衝突可以迫使家庭離開家園，並令學校關閉。"},{"en":"Disputes over land, water, or political power can sometimes lead to armed conflict.","zh":"關於土地、水或政治權力的爭議有時可以導致武裝衝突。"},{"en":"Armed conflict is much more serious than disagreement because it involves violence.","zh":"武裝衝突比意見分歧嚴重得多，因為它涉及暴力。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":5},{"front":"failure to take action","meaning":"未能採取行動","examples":[{"en":"Failure to take action can have grave consequences.","zh":"未能採取行動可以造成嚴重後果。"},{"en":"Failure to take action means not doing what is needed when a problem requires a response.","zh":"failure to take action 指當問題需要回應時，沒有做應該做的事。"},{"en":"Failure to take action on a leaking pipe can waste water and damage a building.","zh":"未能對漏水水管採取行動，可以浪費水並損壞建築物。"},{"en":"Failure to take action against bullying may make students feel unsafe.","zh":"未能對欺凌採取行動，可能令學生感到不安全。"},{"en":"This phrase often warns that doing nothing can be harmful.","zh":"這個片語常警告，不作為也可以造成傷害。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":6},{"front":"broad and grave consequences","meaning":"廣泛而嚴重的後果","examples":[{"en":"Water shortages can have broad and grave consequences.","zh":"水短缺可以造成廣泛而嚴重的後果。"},{"en":"Broad and grave consequences are effects that are both wide-ranging and very serious.","zh":"broad and grave consequences 指影響範圍廣泛而且非常嚴重的後果。"},{"en":"A major power cut can have broad and grave consequences for hospitals, transport, and shops.","zh":"大規模停電可以對醫院、交通和商店造成廣泛而嚴重的後果。"},{"en":"Ignoring public health warnings may have broad and grave consequences for a community.","zh":"忽視公共健康警告可能對社區造成廣泛而嚴重的後果。"},{"en":"This phrase is formal and useful for describing serious social problems.","zh":"這個片語較正式，適合描述嚴重社會問題。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":6},{"front":"fortunately","meaning":"幸好","examples":[{"en":"Fortunately, many technologies and policy tools are already known.","zh":"幸好，許多技術和政策工具已經為人所知。"},{"en":"Fortunately means luckily, and it introduces a positive point after a problem.","zh":"fortunately 意思是「幸好」，用來在問題後引入正面重點。"},{"en":"Fortunately, the lost child was found before nightfall.","zh":"幸好，走失的孩子在入夜前被找到。"},{"en":"The road was blocked; fortunately, the ambulance found another route.","zh":"道路被封；幸好，救護車找到另一條路線。"},{"en":"This word helps show that a bad situation has some hope or relief.","zh":"這個詞幫助表達壞情況中仍有希望或緩解。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":6},{"front":"to a great extent","meaning":"在很大程度上","examples":[{"en":"To a great extent, the tools needed to conserve freshwater are known.","zh":"在很大程度上，保護淡水所需的工具已為人所知。"},{"en":"To a great extent means largely or mostly, but not completely.","zh":"to a great extent 指很大程度上或大部分如此，但不是完全如此。"},{"en":"To a great extent, exam success depends on steady practice.","zh":"在很大程度上，考試成功取決於穩定練習。"},{"en":"To a great extent, a restaurant’s reputation depends on service as well as food.","zh":"在很大程度上，餐廳聲譽取決於服務以及食物。"},{"en":"This phrase is useful when a statement is true in a strong but not total way.","zh":"當某個說法很大程度上正確但不是絕對時，這個片語很有用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":6},{"front":"policy tools","meaning":"政策工具","examples":[{"en":"Governments need effective policy tools to manage freshwater.","zh":"政府需要有效的政策工具來管理淡水。"},{"en":"Policy tools are rules, taxes, subsidies, programmes, or systems used by governments to solve problems.","zh":"policy tools 是政府用來解決問題的規則、稅項、補貼、計劃或制度。"},{"en":"Recycling laws and plastic bag charges are policy tools for reducing waste.","zh":"回收法例和膠袋收費是減少廢物的政策工具。"},{"en":"Policy tools can change behaviour by rewarding good choices or limiting harmful ones.","zh":"政策工具可以透過獎勵良好選擇或限制有害選擇來改變行為。"},{"en":"Good policy tools are practical, fair, and easy enough to enforce.","zh":"良好的政策工具應實用、公平，而且容易執行。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":6},{"front":"conserve existing freshwater","meaning":"保護現有淡水","examples":[{"en":"Technologies can help conserve existing freshwater.","zh":"技術可以幫助保護現有淡水。"},{"en":"To conserve existing freshwater means to protect and save the clean water already available.","zh":"conserve existing freshwater 指保護和節省已經可用的清潔水。"},{"en":"Fixing leaking pipes can conserve existing freshwater in a city.","zh":"維修漏水水管可以保護城市中的現有淡水。"},{"en":"Farmers conserve existing freshwater when they use irrigation systems that waste less water.","zh":"農民使用較少浪費水的灌溉系統時，就是在保護現有淡水。"},{"en":"Conserving existing freshwater is often cheaper than finding completely new sources.","zh":"保護現有淡水通常比尋找全新水源更便宜。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":6},{"front":"secure more of it","meaning":"獲取更多","examples":[{"en":"Countries need ways to secure more freshwater.","zh":"各國需要方法獲取更多淡水。"},{"en":"To secure more of it means to obtain, protect, or guarantee a larger supply of something.","zh":"secure more of it 指取得、保護或保證更多某物的供應。"},{"en":"A school may secure more of its funding by applying for community grants.","zh":"學校可以透過申請社區資助來獲取更多資金。"},{"en":"A family can secure more of its food supply by storing basic goods before a storm.","zh":"家庭可以在風暴前儲存基本物品，以確保獲取更多食物供應。"},{"en":"For water, securing more of it may involve reservoirs, recycling, or better distribution.","zh":"就水而言，獲取更多可能涉及水庫、回收用水或更好的分配。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":6},{"front":"particularly effective","meaning":"特別有效的","examples":[{"en":"Several measures seem particularly effective for water security.","zh":"有幾項措施似乎對水安全特別有效。"},{"en":"Particularly effective means especially successful in producing the desired result.","zh":"particularly effective 指在產生想要的結果方面特別成功。"},{"en":"Short daily revision is particularly effective for remembering new vocabulary.","zh":"每日短時間複習對記住新詞彙特別有效。"},{"en":"Handwashing is particularly effective in reducing the spread of some illnesses.","zh":"洗手在減少某些疾病傳播方面特別有效。"},{"en":"This phrase helps identify the methods that work better than others.","zh":"這個片語幫助指出比其他方法更有效的方法。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":6},{"front":"what is needed now is action","meaning":"現在需要的是行動","examples":[{"en":"What is needed now is action by governments and authorities.","zh":"現在需要的是政府和當局採取行動。"},{"en":"What is needed now is action means the most important thing at this moment is to do something practical.","zh":"what is needed now is action 指此刻最重要的是做實際事情。"},{"en":"After many meetings, what is needed now is action, not another report.","zh":"經過多次會議後，現在需要的是行動，而不是另一份報告。"},{"en":"When a school knows students are struggling, what is needed now is action to support them.","zh":"當學校知道學生有困難，現在需要的是採取行動支援他們。"},{"en":"This phrase is often used when discussion has lasted too long.","zh":"當討論已持續太久時，這個片語常被使用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":6},{"front":"governments and authorities","meaning":"政府和當局","examples":[{"en":"Governments and authorities must develop plans for water security.","zh":"政府和當局必須制定水安全計劃。"},{"en":"Governments and authorities are public bodies that make rules, manage services, and protect society.","zh":"governments and authorities 是制定規則、管理服務和保護社會的公共機構。"},{"en":"Governments and authorities decide how to organise transport, healthcare, education, and emergency services.","zh":"政府和當局決定如何組織交通、醫療、教育和緊急服務。"},{"en":"When a disease spreads, governments and authorities may issue health advice.","zh":"當疾病傳播時，政府和當局可能發布健康建議。"},{"en":"This phrase refers to official decision-makers, not ordinary private groups.","zh":"這個片語指官方決策者，而不是普通私人團體。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":6},{"front":"at every level","meaning":"在各個層面","examples":[{"en":"Authorities at every level must take action.","zh":"各個層面的當局都必須採取行動。"},{"en":"At every level means at all stages or parts of a system, from local to national.","zh":"at every level 指在系統的所有階段或部分，從本地到全國。"},{"en":"Schools need support at every level, from classroom teachers to education departments.","zh":"學校在各個層面都需要支援，從課室老師到教育部門。"},{"en":"Safety rules must be followed at every level of a company.","zh":"公司各個層面都必須遵守安全規則。"},{"en":"This phrase shows that responsibility is shared widely, not held by one group only.","zh":"這個片語顯示責任被廣泛分擔，而不是只由一個群體承擔。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":6},{"front":"formulate and execute plans","meaning":"制定並執行計劃","examples":[{"en":"Governments must formulate and execute plans for water security.","zh":"政府必須制定並執行水安全計劃。"},{"en":"To formulate and execute plans means to design plans and then put them into action.","zh":"formulate and execute plans 指設計計劃，然後把它們付諸實行。"},{"en":"A school must formulate and execute plans before moving lessons online.","zh":"學校在轉為網上課堂前必須制定並執行計劃。"},{"en":"A hospital must formulate and execute plans for handling emergencies.","zh":"醫院必須制定並執行處理緊急情況的計劃。"},{"en":"A plan is not useful unless leaders both formulate it clearly and execute it properly.","zh":"除非領袖清楚制定並妥善執行，否則計劃並不有用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":7},{"front":"implement measures","meaning":"實施措施","examples":[{"en":"Authorities need to implement political, economic and technological measures.","zh":"當局需要實施政治、經濟及技術措施。"},{"en":"To implement measures means to put specific actions, rules, or solutions into practice.","zh":"implement measures 指把具體行動、規則或解決方法付諸實行。"},{"en":"A school may implement measures to reduce bullying, such as reporting systems and teacher training.","zh":"學校可能實施措施減少欺凌，例如舉報系統和教師培訓。"},{"en":"Cities implement measures to save water when reservoirs become low.","zh":"當水庫水位變低，城市會實施節水措施。"},{"en":"This phrase is more practical than “discuss measures” because it means actually doing them.","zh":"這個片語比「討論措施」更實際，因為它指真正執行。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":7},{"front":"political, economic and technological measures","meaning":"政治、經濟及技術措施","examples":[{"en":"Water security requires political, economic and technological measures.","zh":"水安全需要政治、經濟及技術措施。"},{"en":"Political, economic and technological measures are actions involving laws, money systems, and practical tools or machines.","zh":"political, economic and technological measures 是涉及法律、金錢制度和實用工具或機器的行動。"},{"en":"A city may use political, economic and technological measures to reduce air pollution.","zh":"城市可以使用政治、經濟及技術措施來減少空氣污染。"},{"en":"Political measures set rules, economic measures change costs, and technological measures improve methods.","zh":"政治措施制定規則，經濟措施改變成本，技術措施改善方法。"},{"en":"Complex problems often need political, economic and technological measures working together.","zh":"複雜問題通常需要政治、經濟及技術措施共同配合。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":7},{"front":"ensure water security","meaning":"確保水安全","examples":[{"en":"Careful planning can help ensure water security.","zh":"謹慎規劃可以幫助確保水安全。"},{"en":"To ensure water security means to make sure people have enough safe and reliable water.","zh":"ensure water security 指確保人們有足夠、安全而可靠的水。"},{"en":"Repairing pipes and protecting reservoirs can help ensure water security in a city.","zh":"維修水管和保護水庫可以幫助城市確保水安全。"},{"en":"If governments fail to ensure water security, homes, farms, and hospitals may suffer.","zh":"如果政府未能確保水安全，家庭、農場和醫院可能受影響。"},{"en":"Water security is about both quantity and safety.","zh":"水安全涉及水量和安全兩方面。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":7},{"front":"in the coming decades","meaning":"在未來數十年","examples":[{"en":"Water security must be protected now and in the coming decades.","zh":"水安全現在及在未來數十年都必須受到保護。"},{"en":"In the coming decades means during the next several periods of ten years.","zh":"in the coming decades 指在未來幾個十年間。"},{"en":"In the coming decades, many jobs may require stronger digital skills.","zh":"在未來數十年，許多工作可能需要更強的數碼技能。"},{"en":"Cities must plan housing carefully in the coming decades as populations grow.","zh":"隨着人口增長，城市在未來數十年必須謹慎規劃住房。"},{"en":"This phrase is useful for discussing long-term future challenges.","zh":"這個片語適合用於討論長遠未來挑戰。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":7},{"front":"as a start","meaning":"作為起點","examples":[{"en":"The world’s water problems require, as a start, an understanding of basic water needs.","zh":"世界水問題作為起點需要理解基本用水需求。"},{"en":"As a start means as the first step before doing more.","zh":"as a start 指作為做更多事情之前的第一步。"},{"en":"As a start, a student can learn ten useful words before reading the whole article.","zh":"作為起點，學生可以先學十個有用詞語，再閱讀整篇文章。"},{"en":"As a start, a family can reduce waste by separating paper, plastic, and food scraps.","zh":"作為起點，家庭可以透過分類紙張、塑膠和廚餘來減少浪費。"},{"en":"This phrase suggests that the first action is useful but not enough by itself.","zh":"這個片語表示第一步有用，但本身並不足夠。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":7},{"front":"an understanding of","meaning":"對……的理解","examples":[{"en":"An understanding of freshwater needs is essential for water planning.","zh":"對淡水需求的理解對水資源規劃非常重要。"},{"en":"An understanding of something means knowledge about what it means, how it works, or why it matters.","zh":"an understanding of something 指知道某事的意思、運作方式或重要性。"},{"en":"Teachers need an understanding of students’ difficulties before choosing exercises.","zh":"老師在選擇練習前，需要對學生困難有理解。"},{"en":"A doctor needs an understanding of a patient’s habits before giving advice.","zh":"醫生在給建議前，需要對病人的習慣有理解。"},{"en":"Good decisions usually begin with an understanding of the real problem.","zh":"良好決定通常由對真正問題的理解開始。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":7},{"front":"along with knowledge of","meaning":"連同對……的認識","examples":[{"en":"Water planning requires data along with knowledge of supply factors.","zh":"水資源規劃需要數據，連同對供應因素的認識。"},{"en":"Along with knowledge of means together with understanding of another important thing.","zh":"along with knowledge of 指連同對另一個重要事物的理解。"},{"en":"A teacher needs patience along with knowledge of grammar.","zh":"老師需要耐性，連同對文法的認識。"},{"en":"A good manager needs communication skills along with knowledge of the company’s work.","zh":"好經理需要溝通技巧，連同對公司工作的認識。"},{"en":"This phrase adds another necessary type of knowledge or skill.","zh":"這個片語加入另一種必要知識或技能。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":7},{"front":"impede supply","meaning":"阻礙供應","examples":[{"en":"Several factors impede water supply in different regions.","zh":"幾個因素在不同地區阻礙供水。"},{"en":"To impede supply means to slow down, block, or reduce the delivery of something needed.","zh":"impede supply 指減慢、阻擋或減少所需物品的運送。"},{"en":"Bad roads can impede supply of food to remote villages.","zh":"惡劣道路可以阻礙食物供應到偏遠村莊。"},{"en":"Broken pipes impede water supply and leave homes without enough tap water.","zh":"爆裂水管會阻礙供水，令家庭沒有足夠自來水。"},{"en":"Removing obstacles can help prevent problems that impede supply.","zh":"移除障礙可以幫助防止阻礙供應的問題。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":7},{"front":"increase demand","meaning":"增加需求","examples":[{"en":"Population growth and wealth can increase demand for water.","zh":"人口增長和財富可以增加對水的需求。"},{"en":"To increase demand means to make more people want or need something.","zh":"increase demand 指令人們對某物的想要或需要增加。"},{"en":"A new housing estate can increase demand for buses and schools nearby.","zh":"新屋苑可以增加附近對巴士和學校的需求。"},{"en":"Hot weather can increase demand for electricity as people use air conditioning.","zh":"炎熱天氣可以增加對電力的需求，因為人們使用冷氣。"},{"en":"When demand increases faster than supply, shortages and higher prices may follow.","zh":"當需求增加得比供應更快，短缺和價格上升可能隨之而來。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":7},{"front":"different parts of the world","meaning":"世界不同地區","examples":[{"en":"Water problems vary in different parts of the world.","zh":"水問題在世界不同地區各不相同。"},{"en":"Different parts of the world means different countries, regions, or areas on Earth.","zh":"different parts of the world 指地球上不同國家、地區或地方。"},{"en":"People eat different breakfast foods in different parts of the world.","zh":"世界不同地區的人吃不同早餐食物。"},{"en":"Climate change affects different parts of the world in different ways.","zh":"氣候變化以不同方式影響世界不同地區。"},{"en":"This phrase helps compare global variety without naming every place.","zh":"這個片語幫助比較全球差異，而不用逐一列出所有地方。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":7},{"front":"on average","meaning":"平均而言","examples":[{"en":"On average, each person needs at least 1,000 cubic metres of water.","zh":"平均而言，每人至少需要1,000立方米的水。"},{"en":"On average means when the total is divided fairly among people, cases, or periods.","zh":"on average 指把總數在不同人、個案或時段中平均分配後。"},{"en":"On average, students in the class read for twenty minutes a day.","zh":"平均而言，班上的學生每天閱讀二十分鐘。"},{"en":"A bus may arrive every ten minutes on average, though some waits are longer.","zh":"巴士平均而言每十分鐘到達一次，雖然有些等待時間較長。"},{"en":"This phrase shows a general pattern, not what happens every single time.","zh":"這個片語顯示一般模式，而不是每一次都如此。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":8},{"front":"a minimum of","meaning":"最少","examples":[{"en":"Each person needs a minimum of 1,000 cubic metres of water.","zh":"每人最少需要1,000立方米的水。"},{"en":"A minimum of means the smallest amount that is required or acceptable.","zh":"a minimum of 指所需或可接受的最低數量。"},{"en":"The course requires a minimum of two hours of study each week.","zh":"這課程每週最少需要兩小時溫習。"},{"en":"A family should keep a minimum of basic food and water for emergencies.","zh":"家庭應為緊急情況保留最少基本食物和水。"},{"en":"This phrase sets the lowest acceptable level, not the ideal amount.","zh":"這個片語設定最低可接受水平，而不是理想數量。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":8},{"front":"cubic metres","meaning":"立方米","examples":[{"en":"Experts estimate freshwater needs in cubic metres.","zh":"專家以立方米估算淡水需求。"},{"en":"Cubic metres are units used to measure volume, especially large amounts of water, air, or space.","zh":"cubic metres 是用來量度體積的單位，特別是大量的水、空氣或空間。"},{"en":"A swimming pool may hold hundreds of cubic metres of water.","zh":"一個泳池可能容納數百立方米的水。"},{"en":"Water bills may show how many cubic metres a household has used.","zh":"水費單可能顯示一個家庭用了多少立方米水。"},{"en":"One cubic metre is the space inside a cube that is one metre on each side.","zh":"一立方米是一個每邊長一米的立方體內的空間。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":8},{"front":"hygiene","meaning":"衞生","examples":[{"en":"People need freshwater for drinking, hygiene and growing food.","zh":"人們需要淡水來飲用、保持衞生和種植食物。"},{"en":"Hygiene means practices that keep people and places clean and help prevent disease.","zh":"hygiene 指保持人和地方清潔、幫助預防疾病的做法。"},{"en":"Washing hands before eating is a simple part of good hygiene.","zh":"吃飯前洗手是良好衞生的簡單部分。"},{"en":"Poor hygiene can spread illness in schools, kitchens, and hospitals.","zh":"衞生欠佳可以在學校、廚房和醫院傳播疾病。"},{"en":"Clean water is essential for hygiene because people need it to wash bodies, clothes, and surfaces.","zh":"清潔食水對衞生非常重要，因為人們需要它清洗身體、衣物和表面。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":8},{"front":"growing food","meaning":"種植食物","examples":[{"en":"Freshwater is essential for growing food.","zh":"淡水對種植食物非常重要。"},{"en":"Growing food means producing crops, vegetables, fruit, or other food through farming or gardening.","zh":"growing food 指透過農業或園藝生產農作物、蔬菜、水果或其他食物。"},{"en":"A family may use a small garden for growing food such as tomatoes and herbs.","zh":"家庭可能用小花園種植番茄和香草等食物。"},{"en":"Without enough water, growing food becomes difficult and harvests may fail.","zh":"沒有足夠水，種植食物會變得困難，收成可能失敗。"},{"en":"Growing food connects water, land, weather, and human labour.","zh":"種植食物連繫水、土地、天氣和人類勞動。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":8},{"front":"be equivalent to","meaning":"相等於","examples":[{"en":"The required volume is equivalent to two-fifths of an Olympic-size swimming pool.","zh":"所需水量相等於五分之二個奧運標準泳池。"},{"en":"Be equivalent to means to be equal in value, size, meaning, or effect.","zh":"be equivalent to 指在價值、大小、意思或效果上相等。"},{"en":"One thousand metres is equivalent to one kilometre.","zh":"一千米相等於一公里。"},{"en":"Missing three small assignments may be equivalent to losing a large part of the final mark.","zh":"錯過三份小功課可能相等於失去期末成績的一大部分。"},{"en":"This phrase helps compare an unfamiliar amount with something easier to imagine.","zh":"這個片語幫助把陌生數量與較易想像的事物作比較。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":8},{"front":"two-fifths of","meaning":"五分之二的……","examples":[{"en":"The minimum amount is equivalent to two-fifths of an Olympic-size swimming pool.","zh":"最低數量相等於五分之二個奧運標準泳池。"},{"en":"Two-fifths of something means two parts out of five equal parts.","zh":"two-fifths of something 指五等份中的兩份。"},{"en":"If two-fifths of a class walk to school, less than half of the students do so.","zh":"如果一班中五分之二的學生步行上學，意思是少於一半學生這樣做。"},{"en":"A family may spend two-fifths of its income on rent.","zh":"一個家庭可能把收入的五分之二用於租金。"},{"en":"This fraction is the same as 40 percent.","zh":"這個分數等於40%。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":8},{"front":"Olympic-size swimming pool","meaning":"奧運標準泳池","examples":[{"en":"The volume is compared with an Olympic-size swimming pool.","zh":"這個水量被拿來與奧運標準泳池比較。"},{"en":"An Olympic-size swimming pool is a very large pool built to international competition standards.","zh":"Olympic-size swimming pool 是按照國際比賽標準建造的非常大型泳池。"},{"en":"People compare water amounts with an Olympic-size swimming pool because it is easy to picture.","zh":"人們把水量與奧運標準泳池比較，因為它較容易想像。"},{"en":"Filling an Olympic-size swimming pool requires a huge amount of water.","zh":"填滿一個奧運標準泳池需要大量的水。"},{"en":"This phrase helps readers understand large volumes more clearly.","zh":"這個片語幫助讀者更清楚理解大量體積。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":8},{"front":"abundant water supplies","meaning":"充足的水供應","examples":[{"en":"Much of the Americas and northern Eurasia enjoy abundant water supplies.","zh":"美洲大部分地區和歐亞大陸北部享有充足的水供應。"},{"en":"Abundant water supplies are large amounts of water that are easily available.","zh":"abundant water supplies 指容易取得的大量水供應。"},{"en":"A town with abundant water supplies can support homes, farms, and parks more easily.","zh":"擁有充足水供應的城鎮可以較容易支持家庭、農場和公園。"},{"en":"Heavy rainfall and many rivers can create abundant water supplies.","zh":"大量降雨和眾多河流可以形成充足的水供應。"},{"en":"Even places with abundant water supplies still need to avoid pollution and waste.","zh":"即使有充足水供應的地方，仍需要避免污染和浪費。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":8},{"front":"be beset by","meaning":"受……困擾","examples":[{"en":"Several regions are beset by physical water scarcity.","zh":"幾個地區受實質水資源短缺困擾。"},{"en":"To be beset by a problem means to be troubled or surrounded by it in a serious way.","zh":"be beset by a problem 指被某個問題嚴重困擾或包圍。"},{"en":"A school may be beset by staff shortages after many teachers resign.","zh":"如果許多老師辭職，學校可能受人手短缺困擾。"},{"en":"A city beset by traffic problems may need better buses and trains.","zh":"受交通問題困擾的城市可能需要更好的巴士和火車。"},{"en":"This phrase is formal and often describes difficult problems that keep affecting a place.","zh":"這個片語較正式，常描述持續影響某地的困難問題。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":8},{"front":"greater or lesser degrees of","meaning":"不同程度的……","examples":[{"en":"Regions experience greater or lesser degrees of water scarcity.","zh":"各地區經歷不同程度的水資源短缺。"},{"en":"Greater or lesser degrees of means different levels of seriousness, strength, or amount.","zh":"greater or lesser degrees of 指嚴重性、強度或數量上的不同水平。"},{"en":"Students may show greater or lesser degrees of confidence in speaking English.","zh":"學生在英語口語上可能表現出不同程度的信心。"},{"en":"Different neighbourhoods experience greater or lesser degrees of noise pollution.","zh":"不同社區經歷不同程度的噪音污染。"},{"en":"This phrase helps compare a problem that exists in many places but not equally.","zh":"這個片語幫助比較在多處存在但程度不同的問題。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":8},{"front":"physical scarcity","meaning":"實質水資源短缺","examples":[{"en":"Physical scarcity occurs when demand exceeds local water availability.","zh":"當需求超過本地水可供應量時，就會出現實質水資源短缺。"},{"en":"Physical scarcity means there is not enough natural supply of a resource in a place.","zh":"physical scarcity 指某地自然供應的資源不足。"},{"en":"A desert region may suffer physical scarcity of water because rainfall is very low.","zh":"沙漠地區可能因降雨極少而遭受實質水資源短缺。"},{"en":"Physical scarcity cannot be solved only by money if the local resource is truly limited.","zh":"如果本地資源真的有限，實質短缺不能單靠金錢解決。"},{"en":"This is different from poor access caused mainly by weak systems or poverty.","zh":"這不同於主要由制度薄弱或貧窮造成的取得困難。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":9},{"front":"whereby","meaning":"在這種情況下","examples":[{"en":"Physical scarcity refers to a situation whereby demand exceeds local availability.","zh":"實質短缺指一種情況，在這種情況下，需求超過本地可供應量。"},{"en":"Whereby means “by which” or “in which”, and it explains how a situation works.","zh":"whereby 意思是「透過這種方式」或「在這種情況下」，用來解釋情況如何運作。"},{"en":"The school introduced a system whereby students book rooms online.","zh":"學校引入一個制度，學生在這種制度下可網上預訂房間。"},{"en":"Some companies use a method whereby customers pay only after receiving the product.","zh":"一些公司使用一種方法，在這種方法下，顧客收貨後才付款。"},{"en":"This word is formal and often appears in explanations of systems or processes.","zh":"這個詞較正式，常見於制度或過程的解釋中。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":9},{"front":"exceed local availability","meaning":"超過本地可供應量","examples":[{"en":"Water demand may exceed local availability.","zh":"用水需求可能超過本地可供應量。"},{"en":"To exceed local availability means to be greater than what a local area can provide.","zh":"exceed local availability 指大於本地區域能提供的數量。"},{"en":"Tourist numbers may exceed local availability of hotel rooms during a festival.","zh":"節日期間，遊客人數可能超過本地酒店房間可供應量。"},{"en":"If demand for doctors exceeds local availability, patients must travel elsewhere.","zh":"如果對醫生的需求超過本地可供應量，病人必須到其他地方求醫。"},{"en":"This phrase shows a mismatch between need and local supply.","zh":"這個片語顯示需要與本地供應之間不配合。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":9},{"front":"contend with","meaning":"應對；面對","examples":[{"en":"Some areas contend with economic water scarcity.","zh":"一些地區面對經濟性水資源短缺。"},{"en":"To contend with a problem means to deal with it, often with difficulty.","zh":"contend with a problem 指應對某個問題，通常帶有困難。"},{"en":"Students may contend with stress when several exams happen in the same week.","zh":"當多個考試在同一星期進行，學生可能要面對壓力。"},{"en":"Small shops contend with rising rent and competition from online stores.","zh":"小店要應對租金上升和網店競爭。"},{"en":"This phrase suggests that the problem is challenging and cannot be ignored.","zh":"這個片語暗示問題具挑戰性，不能被忽視。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":9},{"front":"economic water scarcity","meaning":"經濟性水資源短缺","examples":[{"en":"Economic water scarcity occurs when resources and capacity restrict access.","zh":"當資源和能力限制取得水時，就會出現經濟性水資源短缺。"},{"en":"Economic water scarcity means water exists, but people cannot access it because money, systems, or infrastructure are insufficient.","zh":"economic water scarcity 指水是存在的，但人們因金錢、制度或基建不足而不能取得。"},{"en":"A village may suffer economic water scarcity if it has nearby rivers but no pipes or treatment plants.","zh":"如果村莊附近有河流但沒有水管或處理廠，它可能遭受經濟性水資源短缺。"},{"en":"Economic water scarcity can improve when investment builds wells, pumps, and safe distribution systems.","zh":"當投資建設水井、水泵和安全分配系統，經濟性水資源短缺可以改善。"},{"en":"This differs from physical scarcity because the main problem is access, not natural supply.","zh":"這不同於實質短缺，因為主要問題是取得途徑，而不是自然供應。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":9},{"front":"limited resources and capacity","meaning":"有限資源和能力","examples":[{"en":"Limited resources and capacity can restrict access to water.","zh":"有限資源和能力可以限制取得水的途徑。"},{"en":"Limited resources and capacity means there is not enough money, equipment, staff, knowledge, or organisational ability.","zh":"limited resources and capacity 指金錢、設備、員工、知識或組織能力不足。"},{"en":"A small clinic with limited resources and capacity may not treat many patients quickly.","zh":"資源和能力有限的小診所可能無法快速治療許多病人。"},{"en":"Limited resources and capacity can delay road repairs after a storm.","zh":"有限資源和能力可以令風暴後道路維修延遲。"},{"en":"This phrase explains why a place may fail to provide services even when the need is clear.","zh":"這個片語解釋為何即使需要清楚，一個地方仍可能無法提供服務。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":9},{"front":"restrict access","meaning":"限制取得","examples":[{"en":"Poor infrastructure can restrict access even when water exists.","zh":"即使有水存在，基建差劣也可以限制取得途徑。"},{"en":"To restrict access means to limit people’s ability to reach or use something.","zh":"restrict access 指限制人們接觸或使用某物的能力。"},{"en":"High ticket prices can restrict access to museums for low-income families.","zh":"高票價可以限制低收入家庭參觀博物館。"},{"en":"A lack of ramps can restrict access for wheelchair users.","zh":"缺乏斜道可以限制輪椅使用者進入。"},{"en":"Restrictions may be physical, financial, legal, or technological.","zh":"限制可以是實體、財務、法律或技術上的。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":9},{"front":"sufficient supplies","meaning":"充足供應","examples":[{"en":"Some regions have sufficient supplies but still lack access.","zh":"一些地區有充足供應，但仍缺乏取得途徑。"},{"en":"Sufficient supplies are enough amounts of something to meet people’s needs.","zh":"sufficient supplies 指足以滿足人們需要的某物數量。"},{"en":"A school needs sufficient supplies of textbooks, chairs, and clean drinking water.","zh":"學校需要充足供應的教科書、椅子和清潔飲用水。"},{"en":"If a hospital has sufficient supplies of medicine, doctors can treat patients more safely.","zh":"如果醫院有充足藥物供應，醫生可以更安全地治療病人。"},{"en":"Sufficient supplies do not help people if they cannot be delivered to the right place.","zh":"如果不能送到正確地方，充足供應也幫不到人。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":9},{"front":"precipitation","meaning":"降水","examples":[{"en":"More than half of the precipitation that falls on land is unavailable for use.","zh":"超過一半落在陸地上的降水不可供使用。"},{"en":"Precipitation is water that falls from the sky as rain, snow, sleet, or hail.","zh":"precipitation 是從天空落下的水，包括雨、雪、雨夾雪或冰雹。"},{"en":"Heavy precipitation can fill reservoirs but may also cause floods.","zh":"大量降水可以填滿水庫，但也可能造成洪水。"},{"en":"Farmers depend on precipitation because crops need regular water.","zh":"農民依賴降水，因為農作物需要定期水分。"},{"en":"Low precipitation over many months can lead to drought.","zh":"多個月低降水量可以導致乾旱。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":9},{"front":"fall on land","meaning":"落在陸地上","examples":[{"en":"Much precipitation falls on land but cannot be captured.","zh":"大量降水落在陸地上，但無法被收集。"},{"en":"Fall on land means to come down from the sky onto the Earth’s land surface.","zh":"fall on land 指從天空降落到地球陸地表面。"},{"en":"Rain that falls on land may enter rivers, soak into soil, or evaporate.","zh":"落在陸地上的雨水可能流入河流、滲入泥土或蒸發。"},{"en":"Snow that falls on land can later melt and feed streams.","zh":"落在陸地上的雪之後可以融化並補給溪流。"},{"en":"Not all water that falls on land becomes available for human use.","zh":"並非所有落在陸地上的水都可供人類使用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":9},{"front":"available for capture or storage","meaning":"可供收集或儲存","examples":[{"en":"Much rainfall is not available for capture or storage.","zh":"大量雨水不可供收集或儲存。"},{"en":"Available for capture or storage means water can be collected and kept for later use.","zh":"available for capture or storage 指水可以被收集並保存以供日後使用。"},{"en":"Rain that runs quickly into the sea may not be available for capture or storage.","zh":"很快流入大海的雨水可能不可供收集或儲存。"},{"en":"A city builds reservoirs so more stormwater is available for capture or storage.","zh":"城市建造水庫，讓更多雨水可供收集或儲存。"},{"en":"Water must be in the right place and form to be available for capture or storage.","zh":"水必須在合適地點和形態，才可供收集或儲存。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":9},{"front":"evaporate from the ground","meaning":"從地面蒸發","examples":[{"en":"Water evaporates from the ground before people can use it.","zh":"水在人們能使用之前從地面蒸發。"},{"en":"To evaporate from the ground means liquid water turns into vapour and leaves the soil or surface.","zh":"evaporate from the ground 指液態水變成水蒸氣並離開泥土或表面。"},{"en":"After rain, water may evaporate from the ground quickly on a hot day.","zh":"下雨後，在炎熱日子水可能很快從地面蒸發。"},{"en":"If water evaporates from the ground, less remains for plants, rivers, or people.","zh":"如果水從地面蒸發，留給植物、河流或人類的水便更少。"},{"en":"Covering soil with plants can reduce how much water evaporates from the ground.","zh":"用植物覆蓋泥土可以減少從地面蒸發的水量。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":10},{"front":"transpire from plants","meaning":"從植物蒸騰","examples":[{"en":"Water transpires from plants and returns to the air.","zh":"水從植物蒸騰並回到空氣中。"},{"en":"To transpire from plants means water passes out of plants into the air as vapour.","zh":"transpire from plants 指水以水蒸氣形式從植物排出到空氣中。"},{"en":"Trees take water from the soil, and some of that water transpires from plants through their leaves.","zh":"樹木從泥土吸水，而其中一些水會透過葉子從植物蒸騰。"},{"en":"When water transpires from plants, it becomes part of the movement of water through the environment.","zh":"當水從植物蒸騰時，它成為環境中水循環的一部分。"},{"en":"This process is natural, but it means not all rainfall stays available for people.","zh":"這個過程是自然的，但意思是並非所有降雨都留給人類使用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":10},{"front":"this fraction","meaning":"這一部分","examples":[{"en":"This fraction of rainfall is called green water.","zh":"降雨中的這一部分被稱為綠水。"},{"en":"This fraction means this part or proportion of a larger whole.","zh":"this fraction 指較大整體中的這一部分或比例。"},{"en":"If only ten students pass, this fraction of the class is too small for the teacher to ignore.","zh":"如果只有十名學生合格，班級中的這一部分太小，老師不能忽視。"},{"en":"This fraction of the budget is used for rent, while the rest pays for food and transport.","zh":"預算中的這一部分用於租金，其餘用於食物和交通。"},{"en":"This phrase helps refer back to a specific part of a total amount.","zh":"這個片語幫助指回總量中的特定部分。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":10},{"front":"green water","meaning":"綠水","examples":[{"en":"Green water is absorbed by soil and plants and is not available for withdrawal.","zh":"綠水被泥土和植物吸收，並不可供提取。"},{"en":"Green water is rainfall stored in soil or used by plants rather than collected in rivers or lakes.","zh":"green water 是儲存在泥土中或被植物使用的降雨，而不是聚集於河流或湖泊中的水。"},{"en":"Farmers depend on green water when crops grow from moisture held in the soil.","zh":"當農作物靠泥土中的水分生長時，農民依賴綠水。"},{"en":"Green water returns to the air when it evaporates or transpires from plants.","zh":"綠水在蒸發或從植物蒸騰時回到空氣中。"},{"en":"Green water is important for ecosystems, even though people cannot easily pump it out.","zh":"綠水對生態系統很重要，雖然人們不能輕易抽取它。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":10},{"front":"the remainder","meaning":"餘下部分","examples":[{"en":"The remainder flows into blue-water sources.","zh":"餘下部分流入藍水水源。"},{"en":"The remainder means the part that is left after other parts have been removed or counted.","zh":"the remainder 指其他部分被移走或計算後剩下的部分。"},{"en":"If half the class joins the trip, the remainder will stay at school.","zh":"如果一半班級參加旅行，餘下的學生會留在學校。"},{"en":"A family may spend some money on rent and save the remainder for food and transport.","zh":"一個家庭可能把部分金錢用於租金，並把餘下部分留作食物和交通。"},{"en":"This phrase helps divide a total amount into used and leftover parts.","zh":"這個片語幫助把總量分成已用部分和剩餘部分。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":10},{"front":"flow into","meaning":"流入","examples":[{"en":"The remaining water flows into rivers, lakes, wetlands and aquifers.","zh":"餘下的水流入河流、湖泊、濕地和含水層。"},{"en":"To flow into means to move naturally into another place, container, or body of water.","zh":"flow into 指自然移動到另一個地方、容器或水體。"},{"en":"Rainwater flows into drains during a storm.","zh":"暴風雨期間，雨水流入排水渠。"},{"en":"Wastewater can flow into rivers if treatment systems fail.","zh":"如果處理系統失效，污水可以流入河流。"},{"en":"This phrase is often used for liquids, traffic, money, or information moving from one place to another.","zh":"這個片語常用於液體、交通、金錢或資訊從一處移到另一處。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":10},{"front":"blue-water sources","meaning":"藍水水源","examples":[{"en":"Blue-water sources include rivers, lakes, wetlands and aquifers.","zh":"藍水水源包括河流、湖泊、濕地和含水層。"},{"en":"Blue-water sources are water bodies or underground stores that people can often collect or withdraw water from.","zh":"blue-water sources 是人們通常可以收集或提取水的水體或地下儲水。"},{"en":"A reservoir is a blue-water source because water can be stored and taken for use.","zh":"水庫是藍水水源，因為水可以被儲存並取用。"},{"en":"Pollution of blue-water sources can directly affect drinking water and irrigation.","zh":"藍水水源受到污染會直接影響飲用水和灌溉。"},{"en":"Blue-water sources are easier for people to use than water hidden in soil and plants.","zh":"藍水水源比藏在泥土和植物中的水更容易被人使用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":10},{"front":"wetlands","meaning":"濕地","examples":[{"en":"Wetlands are one kind of blue-water source.","zh":"濕地是一種藍水水源。"},{"en":"Wetlands are areas where land is covered or soaked with water for much of the time.","zh":"wetlands 是長時間被水覆蓋或浸濕的土地區域。"},{"en":"Marshes and swamps are common types of wetlands.","zh":"沼澤和濕沼是常見濕地類型。"},{"en":"Wetlands can clean water naturally and provide homes for birds, fish, and insects.","zh":"濕地可以自然淨化水，並為鳥類、魚類和昆蟲提供棲息地。"},{"en":"Destroying wetlands can increase flood risk and reduce wildlife habitats.","zh":"破壞濕地可以增加洪水風險，並減少野生動物棲息地。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":10},{"front":"tap directly","meaning":"直接取用","examples":[{"en":"People can tap blue-water sources directly.","zh":"人們可以直接取用藍水水源。"},{"en":"To tap directly means to take or use a resource straight from its source.","zh":"tap directly 指直接從來源取得或使用資源。"},{"en":"A village may tap directly into a nearby spring for drinking water.","zh":"村莊可能直接取用附近泉水作飲用水。"},{"en":"Factories that tap directly from rivers must avoid taking too much water.","zh":"直接從河流取水的工廠必須避免取用太多。"},{"en":"This phrase suggests using a source without many extra steps in between.","zh":"這個片語暗示在中間沒有太多額外步驟下使用來源。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":10},{"front":"farm irrigation","meaning":"農田灌溉","examples":[{"en":"Farm irrigation is the biggest single human use of freshwater.","zh":"農田灌溉是人類對淡水最大的單一用途。"},{"en":"Farm irrigation is the practice of supplying water to crops through canals, pipes, sprinklers, or other systems.","zh":"farm irrigation 是透過渠道、水管、灑水器或其他系統向農作物供水的做法。"},{"en":"Farmers use farm irrigation when rainfall is not enough for crops to grow.","zh":"當降雨不足以讓農作物生長時，農民會使用農田灌溉。"},{"en":"Poor farm irrigation can waste water if too much flows away or evaporates.","zh":"如果太多水流走或蒸發，差劣的農田灌溉會浪費水。"},{"en":"Efficient farm irrigation helps produce food while conserving water.","zh":"高效農田灌溉有助生產食物，同時保護水資源。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":10},{"front":"free-flowing bodies","meaning":"自由流動的水體","examples":[{"en":"Irrigation often uses water from free-flowing bodies.","zh":"灌溉經常使用來自自由流動水體的水。"},{"en":"Free-flowing bodies are natural waters, such as rivers or streams, that move without being fully blocked.","zh":"free-flowing bodies 是自然流動而未被完全阻擋的水體，例如河流或溪流。"},{"en":"A village may collect water from free-flowing bodies during the rainy season.","zh":"村莊可能在雨季從自由流動的水體收集水。"},{"en":"Dams can change free-flowing bodies by slowing or stopping the natural movement of water.","zh":"水壩可以透過減慢或停止水的自然流動來改變自由流動的水體。"},{"en":"Free-flowing bodies support fish, plants, and communities along their banks.","zh":"自由流動的水體支撐河岸上的魚類、植物和社區。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":10},{"front":"the biggest single human use of","meaning":"人類對……最大的單一用途","examples":[{"en":"Farm irrigation is the biggest single human use of freshwater resources.","zh":"農田灌溉是人類對淡水資源最大的單一用途。"},{"en":"The biggest single human use of something means the largest one category in which people use that resource.","zh":"the biggest single human use of something 指人類使用某資源時最大的單一類別。"},{"en":"Heating may be the biggest single human use of energy in a cold household.","zh":"在寒冷家庭中，暖氣可能是人類對能源最大的單一用途。"},{"en":"Transport can be the biggest single human use of fuel in some cities.","zh":"在一些城市，交通可以是人類對燃料最大的單一用途。"},{"en":"This phrase identifies the main area where a resource is consumed.","zh":"這個片語指出資源被消耗的主要領域。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":11},{"front":"intense local demand","meaning":"強烈本地需求","examples":[{"en":"Cities and industries create intense local demand for water.","zh":"城市和工業造成對水的強烈本地需求。"},{"en":"Intense local demand means very strong need for something in a particular area.","zh":"intense local demand 指某特定地區對某物有非常強烈的需要。"},{"en":"A popular school can create intense local demand for places in nearby housing estates.","zh":"受歡迎的學校可以在附近屋苑造成對學位的強烈本地需求。"},{"en":"A festival may create intense local demand for taxis, hotels, and restaurants.","zh":"節日可能造成對的士、酒店和餐廳的強烈本地需求。"},{"en":"When intense local demand appears suddenly, supply systems may become overloaded.","zh":"當強烈本地需求突然出現，供應系統可能超負荷。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":11},{"front":"drain the surroundings of","meaning":"耗盡周邊的……","examples":[{"en":"Urban demand can drain the surroundings of ready water supplies.","zh":"城市需求可以耗盡周邊的現成水供應。"},{"en":"To drain the surroundings of something means to use up resources in nearby areas.","zh":"drain the surroundings of something 指用盡附近地區的資源。"},{"en":"A large factory may drain the surroundings of skilled workers by hiring most of them.","zh":"大型工廠可能透過聘請大部分技術工人而耗盡周邊的人才。"},{"en":"A growing city can drain the surroundings of farmland, water, and building materials.","zh":"發展中的城市可以耗盡周邊的農地、水和建築材料。"},{"en":"This phrase suggests that one centre takes so much that nearby places are left with less.","zh":"這個片語暗示一個中心取得太多，令附近地方剩下更少。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":11},{"front":"ready supplies","meaning":"現成供應","examples":[{"en":"Cities can drain nearby areas of ready supplies.","zh":"城市可以耗盡附近地區的現成供應。"},{"en":"Ready supplies are materials or resources that are already available for immediate use.","zh":"ready supplies 指已經可立即使用的物資或資源。"},{"en":"A clinic needs ready supplies of bandages and basic medicine.","zh":"診所需要繃帶和基本藥物的現成供應。"},{"en":"If ready supplies run out during a storm, families may need emergency help.","zh":"如果現成供應在風暴期間耗盡，家庭可能需要緊急援助。"},{"en":"Ready supplies are useful because they can be used without waiting for new delivery.","zh":"現成供應很有用，因為它們不需等待新配送就能使用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":11},{"front":"there is plenty of","meaning":"有大量……","examples":[{"en":"There is plenty of water, but not always where it is needed.","zh":"有大量的水，但不一定在需要它的地方。"},{"en":"There is plenty of something means there is a large amount or more than enough.","zh":"there is plenty of something 指某物有大量或綽綽有餘。"},{"en":"There is plenty of food at the party, so guests will not go hungry.","zh":"聚會上有大量食物，所以客人不會餓。"},{"en":"A student may have plenty of notes but still need time to organise them.","zh":"學生可能有大量筆記，但仍需要時間整理它們。"},{"en":"This phrase shows abundance, but the next words may explain a remaining problem.","zh":"這個片語表示豐富，但後面的文字可能解釋仍存在的問題。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":11},{"front":"not always where it is needed","meaning":"並不總是在需要的地方","examples":[{"en":"Water is not always where it is needed.","zh":"水並不總是在需要的地方。"},{"en":"Not always where it is needed means something may exist, but not in the right place for people to use it.","zh":"not always where it is needed 指某物可能存在，但不在適合人們使用的地方。"},{"en":"Doctors are not always where they are needed in remote villages.","zh":"在偏遠村莊，醫生並不總是在需要的地方。"},{"en":"Food donations are not always where they are needed if transport is poorly organised.","zh":"如果交通安排欠佳，捐贈食物並不總是在需要的地方。"},{"en":"This phrase shows that location can be as important as total amount.","zh":"這個片語顯示位置可以和總量一樣重要。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":11},{"front":"cubic kilometres","meaning":"立方公里","examples":[{"en":"A vast amount of precipitation is measured in cubic kilometres.","zh":"大量降水以立方公里量度。"},{"en":"Cubic kilometres are units used to measure extremely large volumes.","zh":"cubic kilometres 是用來量度極大體積的單位。"},{"en":"Scientists may describe the water in a lake or glacier in cubic kilometres.","zh":"科學家可能以立方公里描述湖泊或冰川中的水量。"},{"en":"One cubic kilometre is far larger than the volume used in ordinary household measurements.","zh":"一立方公里遠大於普通家庭量度所用的體積。"},{"en":"This unit helps discuss water at regional or global scale.","zh":"這個單位幫助討論地區或全球規模的水量。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":11},{"front":"nearly 10 times the volume of","meaning":"接近……體積的十倍","examples":[{"en":"The annual precipitation is nearly 10 times the volume of Lake Superior.","zh":"每年降水量接近蘇必利爾湖體積的十倍。"},{"en":"Nearly 10 times the volume of means almost ten times as much space or amount as another thing contains.","zh":"nearly 10 times the volume of 指某物的空間或數量幾乎是另一物所容納量的十倍。"},{"en":"The new warehouse holds nearly 10 times the volume of the old storage room.","zh":"新倉庫可容納的體積接近舊儲物室的十倍。"},{"en":"If a flood carries nearly 10 times the volume of normal river flow, damage can be severe.","zh":"如果洪水水量接近正常河流流量的十倍，破壞可能很嚴重。"},{"en":"This phrase helps readers understand size through comparison.","zh":"這個片語幫助讀者透過比較理解大小。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":11},{"front":"fall from the sky onto","meaning":"從天而降到……","examples":[{"en":"Precipitation falls from the sky onto Earth’s land surface.","zh":"降水從天而降到地球陸地表面。"},{"en":"Fall from the sky onto means to come down from the air and land on a surface.","zh":"fall from the sky onto 指從空中降下並落在某個表面上。"},{"en":"Snow can fall from the sky onto rooftops, roads, and fields.","zh":"雪可以從天而降到屋頂、道路和田野。"},{"en":"When ash falls from the sky onto a town, people may need masks and shelter.","zh":"當火山灰從天而降到城鎮，人們可能需要口罩和庇護。"},{"en":"This phrase describes the direction of movement from above to below.","zh":"這個片語描述從上方到下方的移動方向。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":11},{"front":"Earth’s land surface","meaning":"地球陸地表面","examples":[{"en":"Huge amounts of rain fall onto Earth’s land surface every year.","zh":"每年有大量雨水落到地球陸地表面。"},{"en":"Earth’s land surface means the parts of the planet covered by land rather than oceans.","zh":"Earth’s land surface 指地球上由陸地而不是海洋覆蓋的部分。"},{"en":"Forests, deserts, farms, cities, and mountains are all part of Earth’s land surface.","zh":"森林、沙漠、農場、城市和山脈都是地球陸地表面的一部分。"},{"en":"Rainfall on Earth’s land surface may enter rivers, soil, plants, or groundwater.","zh":"落在地球陸地表面的雨水可能進入河流、泥土、植物或地下水。"},{"en":"This phrase helps distinguish land from the oceans.","zh":"這個片語幫助區分陸地和海洋。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":11},{"front":"huge quantity","meaning":"巨大數量","examples":[{"en":"This huge quantity of water could meet global needs if distributed properly.","zh":"如果分配得當，這巨大數量的水可以滿足全球需要。"},{"en":"A huge quantity is a very large amount of something.","zh":"huge quantity 指某物非常大的數量。"},{"en":"A supermarket may waste a huge quantity of food if storage systems fail.","zh":"如果儲存系統失效，超級市場可能浪費巨大數量的食物。"},{"en":"A huge quantity of rain in a short time can cause flooding.","zh":"短時間內巨大數量的降雨可以造成洪水。"},{"en":"This phrase is useful when the amount is too large to imagine easily.","zh":"當數量大得難以輕易想像時，這個片語很有用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":11},{"front":"fulfil the requirements of","meaning":"滿足……的需要","examples":[{"en":"The rainfall could fulfil the requirements of everyone on the planet.","zh":"這些降雨可以滿足地球上每一個人的需要。"},{"en":"To fulfil the requirements of someone or something means to provide what is needed.","zh":"fulfil the requirements of someone or something 指提供所需的東西。"},{"en":"A course must fulfil the requirements of the exam before students can rely on it.","zh":"課程必須滿足考試的要求，學生才可依靠它。"},{"en":"A building must fulfil the requirements of safety rules before it opens.","zh":"建築物必須滿足安全規則的要求，才可開放。"},{"en":"This phrase is formal and often used for needs, standards, or rules.","zh":"這個片語較正式，常用於需要、標準或規則。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":12},{"front":"everyone on the planet","meaning":"地球上每一個人","examples":[{"en":"There is enough water in theory for everyone on the planet.","zh":"理論上有足夠的水供地球上每一個人使用。"},{"en":"Everyone on the planet means every person living on Earth.","zh":"everyone on the planet 指生活在地球上的每一個人。"},{"en":"Clean air matters to everyone on the planet, not only one country.","zh":"清潔空氣對地球上每一個人都重要，不只是一個國家。"},{"en":"A disease can affect everyone on the planet if travel spreads it quickly.","zh":"如果旅行令疾病快速傳播，它可以影響地球上每一個人。"},{"en":"This phrase is used to emphasise the whole human population.","zh":"這個片語用來強調整個人類人口。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":12},{"front":"where and when people needed it","meaning":"在人們需要的地點和時間","examples":[{"en":"The problem is that water does not arrive where and when people need it.","zh":"問題是水沒有在人們需要的地點和時間到達。"},{"en":"Where and when people needed it means in the right place and at the right time for human use.","zh":"where and when people needed it 指在適合人類使用的正確地點和時間。"},{"en":"Food aid is useful only if it reaches families where and when people need it.","zh":"食物援助只有在到達人們需要的地點和時間時才有用。"},{"en":"A bus service must run where and when people need it, or passengers will not use it.","zh":"巴士服務必須在人們需要的地點和時間運行，否則乘客不會使用。"},{"en":"This phrase shows that timing and location both matter.","zh":"這個片語顯示時間和地點都重要。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":12},{"front":"be captured","meaning":"被收集","examples":[{"en":"Much rainfall cannot be captured before it disappears.","zh":"大量雨水在消失前無法被收集。"},{"en":"If water is captured, it is collected and kept instead of being lost.","zh":"如果水 be captured，意思是它被收集和保存，而不是流失。"},{"en":"Rainwater can be captured in tanks and used for gardens.","zh":"雨水可以被收集到水箱中，用於花園。"},{"en":"If stormwater is not captured, it may flow into drains and reach the sea.","zh":"如果雨水沒有被收集，它可能流入排水渠並到達大海。"},{"en":"Captured water can help communities during dry periods.","zh":"被收集的水可以在乾旱時期幫助社區。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":12},{"front":"be distributed unevenly","meaning":"分布不均","examples":[{"en":"The remaining water is distributed unevenly.","zh":"餘下的水分布不均。"},{"en":"Be distributed unevenly means something is spread in an unequal way across places or people.","zh":"be distributed unevenly 指某物在地方或人群之間不平均分布。"},{"en":"School funding may be distributed unevenly, leaving poorer areas with fewer resources.","zh":"學校資金可能分布不均，令較貧困地區資源較少。"},{"en":"Rainfall is often distributed unevenly, with some regions flooded and others dry.","zh":"降雨常分布不均，有些地區水浸，有些地區乾旱。"},{"en":"Uneven distribution can create unfairness even when the total amount seems enough.","zh":"即使總量看似足夠，分布不均也可以造成不公平。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":12},{"front":"absorbed by soil and plants","meaning":"被泥土和植物吸收","examples":[{"en":"Green water is absorbed by soil and plants.","zh":"綠水被泥土和植物吸收。"},{"en":"Absorbed by soil and plants means water is taken in and held by the ground and vegetation.","zh":"absorbed by soil and plants 指水被地面和植被吸入並保留。"},{"en":"After light rain, much water is absorbed by soil and plants instead of running into drains.","zh":"小雨後，大量水被泥土和植物吸收，而不是流入排水渠。"},{"en":"Water absorbed by soil and plants helps crops grow and keeps landscapes alive.","zh":"被泥土和植物吸收的水幫助農作物生長，並維持景觀生命。"},{"en":"This water is useful for nature, but it may not be easy for people to withdraw.","zh":"這些水對自然有用，但人們未必容易提取。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":12},{"front":"released back into the air","meaning":"被釋放回空氣中","examples":[{"en":"Green water is released back into the air.","zh":"綠水被釋放回空氣中。"},{"en":"Released back into the air means something returns to the atmosphere after being held somewhere else.","zh":"released back into the air 指某物在被其他地方保存後回到大氣中。"},{"en":"Water in wet clothes is released back into the air as the clothes dry.","zh":"濕衣服中的水在衣服變乾時被釋放回空氣中。"},{"en":"Plants release water back into the air through transpiration.","zh":"植物透過蒸騰把水釋放回空氣中。"},{"en":"This phrase helps describe how water moves through the natural cycle.","zh":"這個片語幫助描述水如何在自然循環中移動。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":12},{"front":"unavailable for withdrawal","meaning":"不可供提取","examples":[{"en":"Green water is unavailable for withdrawal.","zh":"綠水不可供提取。"},{"en":"Unavailable for withdrawal means it cannot easily be taken out and used directly.","zh":"unavailable for withdrawal 指它不能輕易被取出並直接使用。"},{"en":"Water held inside plant tissues is unavailable for withdrawal by households.","zh":"保存在植物組織內的水不可供家庭提取。"},{"en":"If water is trapped deep in rock, it may be unavailable for withdrawal without expensive equipment.","zh":"如果水被困在深層岩石中，沒有昂貴設備便可能不可供提取。"},{"en":"This phrase explains why not all water can become usable supply.","zh":"這個片語解釋為何並非所有水都能成為可用供應。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":12},{"front":"collected in","meaning":"聚集於","examples":[{"en":"Blue water is collected in rivers, lakes, wetlands and groundwater.","zh":"藍水聚集於河流、湖泊、濕地和地下水中。"},{"en":"Collected in means gathered or stored inside a place or system.","zh":"collected in 指被集中或儲存在某個地方或系統內。"},{"en":"Rainwater can be collected in tanks for later use.","zh":"雨水可以被收集在水箱中，以供日後使用。"},{"en":"Books are collected in a library so people can find them easily.","zh":"書籍被收集在圖書館中，讓人們容易找到。"},{"en":"When water is collected in reservoirs, cities can use it during dry months.","zh":"當水聚集於水庫，城市可以在乾旱月份使用它。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":12},{"front":"groundwater","meaning":"地下水","examples":[{"en":"Groundwater is one of the sources of blue water.","zh":"地下水是藍水的來源之一。"},{"en":"Groundwater is water stored below the ground in soil, sand, or rock.","zh":"groundwater 是儲存在地下泥土、沙或岩石中的水。"},{"en":"Wells allow people to reach groundwater for drinking and farming.","zh":"水井讓人們取得地下水作飲用和農業用途。"},{"en":"Groundwater can become polluted if chemicals leak into the soil.","zh":"如果化學品滲入泥土，地下水可以受到污染。"},{"en":"When rainfall is low, communities may depend more heavily on groundwater.","zh":"當降雨量低，社區可能更依賴地下水。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":12},{"front":"available for withdrawal","meaning":"可供提取","examples":[{"en":"Blue water is available for withdrawal before it evaporates.","zh":"藍水在蒸發前可供提取。"},{"en":"Available for withdrawal means water can be taken out and used directly.","zh":"available for withdrawal 指水可以被取出並直接使用。"},{"en":"Water in a reservoir is often available for withdrawal by a city’s water system.","zh":"水庫中的水通常可供城市供水系統提取。"},{"en":"Groundwater may be available for withdrawal if wells and pumps can reach it.","zh":"如果水井和水泵能到達地下水，它可能可供提取。"},{"en":"This phrase describes water that can become practical supply.","zh":"這個片語描述能成為實際供應的水。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":12},{"front":"before it reaches the ocean","meaning":"在到達海洋之前","examples":[{"en":"Blue water can be used before it reaches the ocean.","zh":"藍水可以在到達海洋之前被使用。"},{"en":"Before it reaches the ocean means before water flows into the sea.","zh":"before it reaches the ocean 指水流入大海之前。"},{"en":"A river can provide drinking water before it reaches the ocean.","zh":"河流可以在到達海洋之前提供飲用水。"},{"en":"If rainwater is stored before it reaches the ocean, cities may have more water during dry seasons.","zh":"如果雨水在到達海洋之前被儲存，城市在旱季可能有更多水。"},{"en":"Once freshwater reaches the ocean, it mixes with saltwater and becomes harder to use directly.","zh":"一旦淡水到達海洋，便會與鹹水混合，變得更難直接使用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":13},{"front":"add up to","meaning":"加起來等於","examples":[{"en":"The figures may not add up to 100% because of rounding.","zh":"這些數字可能因四捨五入而加起來不等於100%。"},{"en":"Add up to means to make a total amount when numbers are combined.","zh":"add up to 指數字合併後形成某個總數。"},{"en":"The costs of rent, food, and transport add up to most of the family budget.","zh":"租金、食物和交通費加起來等於家庭預算的大部分。"},{"en":"If the percentages do not add up to 100%, one category may be missing.","zh":"如果百分比加起來不等於100%，可能有一個類別遺漏。"},{"en":"Small daily expenses can add up to a large sum over a month.","zh":"每天的小開支在一個月內可以加起來成為一大筆錢。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":13},{"front":"because of rounding","meaning":"因四捨五入","examples":[{"en":"The percentages may differ slightly because of rounding.","zh":"這些百分比可能因四捨五入而略有不同。"},{"en":"Because of rounding means small differences appear because numbers are changed to simpler whole numbers or fewer decimal places.","zh":"because of rounding 指數字被改成較簡單的整數或較少小數位，因此出現小差異。"},{"en":"The total may show 99% because of rounding, even though no data is missing.","zh":"總數可能因四捨五入顯示為99%，即使沒有資料遺漏。"},{"en":"A price of 19.995 may become 20.00 because of rounding.","zh":"19.995的價格可能因四捨五入變成20.00。"},{"en":"This phrase explains small numerical differences that are not real errors.","zh":"這個片語解釋並非真正錯誤的小數字差異。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":13},{"front":"directly used by people","meaning":"被人類直接使用","examples":[{"en":"Only a small percentage of freshwater is directly used by people.","zh":"只有一小部分淡水被人類直接使用。"},{"en":"Directly used by people means taken and used by humans themselves rather than staying in nature or being used indirectly.","zh":"directly used by people 指被人類本身取得和使用，而不是留在自然中或被間接使用。"},{"en":"Tap water is directly used by people for drinking, cooking, and washing.","zh":"自來水被人類直接用於飲用、煮食和清洗。"},{"en":"Water held deep in soil is not directly used by people unless it can be withdrawn.","zh":"保存在深層泥土中的水不會被人類直接使用，除非它可以被提取。"},{"en":"This phrase separates human use from natural movement or storage.","zh":"這個片語把人類使用與自然流動或儲存區分開來。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":13},{"front":"fall to critically low levels","meaning":"下降至極低水平","examples":[{"en":"Water supplies fell to critically low levels during droughts.","zh":"在乾旱期間，水供應下降至極低水平。"},{"en":"To fall to critically low levels means to drop to a dangerously small amount.","zh":"fall to critically low levels 指下降至危險地低的數量。"},{"en":"A phone battery may fall to critically low levels if it is not charged all day.","zh":"如果一整天不充電，電話電量可能下降至極低水平。"},{"en":"Blood supplies can fall to critically low levels after a major accident.","zh":"大型事故後，血液供應可以下降至極低水平。"},{"en":"This phrase warns that the situation is close to becoming unsafe or unmanageable.","zh":"這個片語警告情況接近變得不安全或難以管理。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":13},{"front":"severe droughts","meaning":"嚴重乾旱","examples":[{"en":"Severe droughts reduced water supplies to dangerous levels.","zh":"嚴重乾旱把水供應減至危險水平。"},{"en":"Severe droughts are long, serious periods with far too little rain.","zh":"severe droughts 是長時間而嚴重、降雨遠遠不足的時期。"},{"en":"Severe droughts can dry up rivers, damage crops, and reduce drinking water.","zh":"嚴重乾旱可以令河流乾涸、破壞農作物並減少飲用水。"},{"en":"Farmers may lose income when severe droughts last through the growing season.","zh":"當嚴重乾旱持續整個生長季節，農民可能失去收入。"},{"en":"Severe droughts are more serious than ordinary dry weather.","zh":"嚴重乾旱比普通乾燥天氣更嚴重。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":13},{"front":"in recent years","meaning":"近年來","examples":[{"en":"Some regions have experienced severe droughts in recent years.","zh":"一些地區近年來經歷了嚴重乾旱。"},{"en":"In recent years means during the last few years, not long ago.","zh":"in recent years 指在過去幾年，即不久之前。"},{"en":"In recent years, many people have become more comfortable with online meetings.","zh":"近年來，許多人對網上會議變得更習慣。"},{"en":"House prices have risen quickly in recent years in some cities.","zh":"近年來，一些城市的樓價迅速上升。"},{"en":"This phrase is useful for describing a fairly new trend.","zh":"這個片語適合描述較新的趨勢。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":13},{"front":"economic actors","meaning":"經濟參與者","examples":[{"en":"Economic actors took what they regarded as a reasonable share of water.","zh":"經濟參與者取用了他們視為合理份額的水。"},{"en":"Economic actors are people, businesses, farms, or organisations that make economic decisions and use resources.","zh":"economic actors 是作出經濟決定並使用資源的人、企業、農場或組織。"},{"en":"Shops, factories, banks, and households can all be economic actors.","zh":"商店、工廠、銀行和家庭都可以是經濟參與者。"},{"en":"Economic actors may compete for land, labour, energy, or water.","zh":"經濟參與者可能競爭土地、勞動力、能源或水。"},{"en":"Good policy considers how different economic actors will respond to rules and prices.","zh":"良好政策會考慮不同經濟參與者會如何回應規則和價格。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":13},{"front":"regard something as","meaning":"將……視為","examples":[{"en":"Each group regarded its share of water as reasonable.","zh":"每個群體都將自己的用水份額視為合理。"},{"en":"To regard something as means to consider or think of it in a particular way.","zh":"regard something as 指以某種方式看待或認為某事物。"},{"en":"Many students regard regular practice as the safest way to improve.","zh":"許多學生將定期練習視為進步的最穩妥方法。"},{"en":"A company may regard customer trust as its most valuable asset.","zh":"公司可能將顧客信任視為最有價值的資產。"},{"en":"This phrase describes judgement, opinion, or attitude.","zh":"這個片語描述判斷、意見或態度。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":13},{"front":"a reasonable share","meaning":"合理份額","examples":[{"en":"Each economic actor took what seemed a reasonable share.","zh":"每個經濟參與者都取用了看似合理的份額。"},{"en":"A reasonable share is an amount that seems fair compared with what others receive or need.","zh":"a reasonable share 指與其他人獲得或需要的相比，似乎公平的數量。"},{"en":"In a group project, each student should do a reasonable share of the work.","zh":"在小組項目中，每個學生都應做合理份額的工作。"},{"en":"If one person takes more than a reasonable share of food, others may not have enough.","zh":"如果一個人取走超過合理份額的食物，其他人可能不夠。"},{"en":"What seems a reasonable share to one person may feel unfair to another.","zh":"對一個人來說看似合理份額的東西，對另一個人可能感覺不公平。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":13},{"front":"consider the needs of","meaning":"考慮……的需要","examples":[{"en":"They did not consider the needs of the natural environment.","zh":"他們沒有考慮自然環境的需要。"},{"en":"To consider the needs of someone or something means to think about what they require before deciding.","zh":"consider the needs of someone or something 指在決定前思考對方需要甚麼。"},{"en":"A school timetable should consider the needs of both students and teachers.","zh":"學校時間表應考慮學生和老師的需要。"},{"en":"City planners must consider the needs of older people and disabled residents.","zh":"城市規劃者必須考慮長者和殘疾居民的需要。"},{"en":"If leaders do not consider the needs of nature, human systems may suffer later.","zh":"如果領袖不考慮自然的需要，人類系統日後可能受害。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":13},{"front":"the natural environment","meaning":"自然環境","examples":[{"en":"The natural environment suffered from inadequate water supply.","zh":"自然環境因供水不足而受害。"},{"en":"The natural environment means the living and non-living parts of nature, such as forests, rivers, soil, air, and wildlife.","zh":"the natural environment 指自然界中有生命和無生命的部分，例如森林、河流、泥土、空氣和野生動物。"},{"en":"The natural environment provides clean air, water, food, and places for animals to live.","zh":"自然環境提供清潔空氣、水、食物和動物棲息地。"},{"en":"Pollution damages the natural environment when chemicals enter land or water.","zh":"當化學品進入土地或水中，污染會破壞自然環境。"},{"en":"Protecting the natural environment also protects human health and long-term resources.","zh":"保護自然環境也保護人類健康和長期資源。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":14},{"front":"suffer greatly","meaning":"深受其害","examples":[{"en":"The natural environment suffered greatly during droughts.","zh":"自然環境在乾旱期間深受其害。"},{"en":"To suffer greatly means to experience serious harm, pain, loss, or difficulty.","zh":"suffer greatly 指經歷嚴重傷害、痛苦、損失或困難。"},{"en":"A small business may suffer greatly if the road outside is closed for months.","zh":"如果門外道路關閉數月，小企業可能深受其害。"},{"en":"Children can suffer greatly when schools close for a long time.","zh":"當學校長時間關閉，孩子可能深受其害。"},{"en":"This phrase shows that the damage is not small or temporary.","zh":"這個片語顯示損害不是小型或暫時的。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":14},{"front":"inadequate supply","meaning":"不足的供應","examples":[{"en":"The environment was damaged when its inadequate supply was reduced further.","zh":"當自然環境本已不足的供應進一步減少時，它受到破壞。"},{"en":"Inadequate supply means there is not enough of something to meet needs.","zh":"inadequate supply 指某物不足以滿足需要。"},{"en":"A hospital with inadequate supply of nurses cannot treat patients quickly.","zh":"護士供應不足的醫院無法快速治療病人。"},{"en":"Inadequate supply of buses can make workers late every morning.","zh":"巴士供應不足可以令工人每天早上遲到。"},{"en":"When supply is inadequate, people may have to compete for limited resources.","zh":"當供應不足，人們可能要競爭有限資源。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":14},{"front":"be reduced to critical levels","meaning":"被減至危急水平","examples":[{"en":"Water supplies were reduced to critical levels by drought.","zh":"水供應因乾旱被減至危急水平。"},{"en":"Be reduced to critical levels means to be lowered to a dangerously serious point.","zh":"be reduced to critical levels 指被降低至危險而嚴重的水平。"},{"en":"Food stocks may be reduced to critical levels after weeks of blocked transport.","zh":"交通受阻數星期後，食物庫存可能被減至危急水平。"},{"en":"If hospital beds are reduced to critical levels, emergency care becomes difficult.","zh":"如果醫院床位被減至危急水平，緊急護理會變得困難。"},{"en":"This phrase signals that urgent action is needed.","zh":"這個片語表示需要緊急行動。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":14},{"front":"frantically trying to","meaning":"急切地嘗試","examples":[{"en":"The commission is frantically trying to solve the water-allocation problem.","zh":"委員會正急切地嘗試解決水分配問題。"},{"en":"Frantically trying to means trying very urgently, anxiously, and often under pressure.","zh":"frantically trying to 指非常急迫、焦慮，並常在壓力下嘗試做某事。"},{"en":"A student may be frantically trying to finish homework before the deadline.","zh":"學生可能在截止日期前急切地嘗試完成功課。"},{"en":"Parents may be frantically trying to find childcare when a school suddenly closes.","zh":"當學校突然關閉，父母可能急切地嘗試尋找托兒安排。"},{"en":"This phrase suggests stress, speed, and a strong need to solve something quickly.","zh":"這個片語暗示壓力、速度和迅速解決問題的強烈需要。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":14},{"front":"extricate oneself from","meaning":"使自己擺脫","examples":[{"en":"The commission tried to extricate itself from the disastrous results of misallocation.","zh":"委員會試圖使自己擺脫錯誤分配造成的災難性後果。"},{"en":"To extricate oneself from a problem means to free oneself from a difficult or messy situation.","zh":"extricate oneself from a problem 指使自己脫離困難或混亂的情況。"},{"en":"A company may try to extricate itself from debt by selling unused assets.","zh":"公司可能透過出售閒置資產，使自己擺脫債務。"},{"en":"A student who joined too many activities may need to extricate herself from some commitments.","zh":"參加太多活動的學生可能需要使自己擺脫部分承諾。"},{"en":"This phrase is formal and suggests that escape is difficult but necessary.","zh":"這個片語較正式，暗示脫身很困難但有必要。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":14},{"front":"disastrous results","meaning":"災難性後果","examples":[{"en":"The misallocation of water produced disastrous results.","zh":"水資源錯誤分配造成災難性後果。"},{"en":"Disastrous results are extremely harmful or damaging outcomes.","zh":"disastrous results 指極度有害或破壞性的結果。"},{"en":"Ignoring fire safety rules can have disastrous results in a crowded building.","zh":"在擁擠建築物中忽視消防安全規則，可以造成災難性後果。"},{"en":"Poor planning before a storm may lead to disastrous results for a coastal town.","zh":"風暴前規劃差劣，可能為沿海城鎮帶來災難性後果。"},{"en":"This phrase is stronger than “bad results” and suggests serious damage.","zh":"這個片語比「壞結果」更強，暗示嚴重損害。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":14},{"front":"misallocation","meaning":"錯誤分配","examples":[{"en":"Misallocation of water can damage both people and ecosystems.","zh":"水資源錯誤分配可以傷害人類和生態系統。"},{"en":"Misallocation means resources are distributed to the wrong places, people, or purposes.","zh":"misallocation 指資源被分配到錯誤的地方、人群或用途。"},{"en":"Misallocation of school funding may leave poor areas without enough teachers.","zh":"學校資金錯誤分配可能令貧困地區沒有足夠老師。"},{"en":"Misallocation of hospital beds can delay care for patients who need them most.","zh":"醫院床位錯誤分配可以延誤最需要床位的病人接受護理。"},{"en":"Good planning reduces misallocation by matching resources with real needs.","zh":"良好規劃透過把資源配合真正需要來減少錯誤分配。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":14},{"front":"total water resource","meaning":"總水資源","examples":[{"en":"The commission had to reconsider the total water resource.","zh":"委員會不得不重新考慮總水資源。"},{"en":"Total water resource means the full amount of water available in a system or region.","zh":"total water resource 指一個系統或地區中可用水的總量。"},{"en":"A city must know its total water resource before deciding how much households and farms can use.","zh":"城市在決定家庭和農場可用多少水之前，必須知道總水資源。"},{"en":"If drought reduces the total water resource, every user may need to cut consumption.","zh":"如果乾旱減少總水資源，每個使用者都可能需要減少消耗。"},{"en":"This phrase looks at the whole supply, not only one user’s share.","zh":"這個片語看的是整體供應，而不是只看某一使用者的份額。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":14},{"front":"given the difficulties of","meaning":"鑑於……的困難","examples":[{"en":"Given the difficulties of sharing water within one country, international basins are even harder.","zh":"鑑於在一個國家內共享水資源的困難，國際流域甚至更難處理。"},{"en":"Given the difficulties of means considering how hard something already is.","zh":"given the difficulties of 指考慮到某事本身已經很困難。"},{"en":"Given the difficulties of learning alone, many students join a study group.","zh":"鑑於獨自學習的困難，許多學生會加入溫習小組。"},{"en":"Given the difficulties of caring for elderly parents, families may need community support.","zh":"鑑於照顧年老父母的困難，家庭可能需要社區支援。"},{"en":"This phrase introduces a reason before making a judgement or comparison.","zh":"這個片語在作出判斷或比較前引入原因。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":14},{"front":"sensibly apportion","meaning":"合理分配","examples":[{"en":"Authorities must sensibly apportion the water supply.","zh":"當局必須合理分配水供應。"},{"en":"To sensibly apportion something means to divide it fairly and practically among different users.","zh":"sensibly apportion something 指公平而實際地把某物分給不同使用者。"},{"en":"A teacher must sensibly apportion group work so no student does everything alone.","zh":"老師必須合理分配小組工作，令沒有學生獨自完成全部。"},{"en":"During a shortage, officials may sensibly apportion food to families according to need.","zh":"在短缺期間，官員可能根據需要合理分配食物給家庭。"},{"en":"This phrase suggests careful sharing, not random or selfish distribution.","zh":"這個片語暗示謹慎共享，而不是隨意或自私分配。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":14},{"front":"water supply","meaning":"水供應","examples":[{"en":"The water supply must be shared among competing users.","zh":"水供應必須在互相競爭的使用者之間共享。"},{"en":"Water supply is the amount of water available for homes, farms, businesses, and public services.","zh":"water supply 是可供家庭、農場、企業和公共服務使用的水量。"},{"en":"A town’s water supply may come from rivers, reservoirs, or underground sources.","zh":"城鎮的水供應可能來自河流、水庫或地下來源。"},{"en":"If the water supply is polluted, people may need bottled water or treatment systems.","zh":"如果水供應受到污染，人們可能需要瓶裝水或處理系統。"},{"en":"Reliable water supply is essential for health, cooking, cleaning, and industry.","zh":"可靠的水供應對健康、煮食、清潔和工業非常重要。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":15},{"front":"within a single nation","meaning":"在單一國家之內","examples":[{"en":"Sharing water within a single nation can already be difficult.","zh":"在單一國家之內共享水資源已經可以很困難。"},{"en":"Within a single nation means inside one country, rather than between countries.","zh":"within a single nation 指在一個國家內，而不是國與國之間。"},{"en":"Transport rules may differ within a single nation if regions have different needs.","zh":"如果地區需要不同，在單一國家之內交通規則也可能不同。"},{"en":"Even within a single nation, rich and poor areas may receive different public services.","zh":"即使在單一國家之內，富裕和貧困地區也可能收到不同公共服務。"},{"en":"This phrase is useful when comparing internal issues with international ones.","zh":"當比較國內問題與國際問題時，這個片語很有用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":15},{"front":"international river basins","meaning":"國際河流流域","examples":[{"en":"International river basins create complex political challenges.","zh":"國際河流流域造成複雜政治挑戰。"},{"en":"International river basins are river systems whose water flows through or affects more than one country.","zh":"international river basins 是流經或影響多於一個國家的河流系統。"},{"en":"Countries sharing international river basins must discuss dams, pollution, and water withdrawals.","zh":"共享國際河流流域的國家必須討論水壩、污染和取水。"},{"en":"A dispute over international river basins may affect farmers, cities, and ecosystems on both sides of a border.","zh":"關於國際河流流域的爭議可能影響邊境兩邊的農民、城市和生態系統。"},{"en":"These basins require cooperation because one country’s actions can affect another.","zh":"這些流域需要合作，因為一個國家的行動可以影響另一個國家。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":15},{"front":"such as that of","meaning":"例如……的","examples":[{"en":"The passage mentions international river basins such as that of the Jordan River.","zh":"文章提到國際河流流域，例如約旦河的流域。"},{"en":"Such as that of means “for example, the one belonging to or connected with”.","zh":"such as that of 指「例如屬於或關於某事的那個」。"},{"en":"Some cities face housing problems, such as that of London.","zh":"一些城市面對住房問題，例如倫敦的住房問題。"},{"en":"The company studied successful systems, such as that of a small hospital using digital records.","zh":"公司研究成功系統，例如一間使用電子紀錄的小型醫院的系統。"},{"en":"This phrase avoids repeating a noun already mentioned.","zh":"這個片語避免重複前面已提及的名詞。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":15},{"front":"border","meaning":"與……接壤","examples":[{"en":"The Jordan River basin borders several political areas.","zh":"約旦河流域與幾個政治地區接壤。"},{"en":"To border a place means to be next to it or share an edge with it.","zh":"border a place 指位於某地旁邊或與它共享邊界。"},{"en":"A park may border a school, so children can walk there easily.","zh":"公園可能與學校接壤，所以孩子可以輕易步行到那裡。"},{"en":"Countries that border each other often share trade routes, rivers, and transport links.","zh":"彼此接壤的國家常共享貿易路線、河流和交通連接。"},{"en":"Border can be a verb or a noun connected with edges between places.","zh":"border 可以是動詞或名詞，與地方之間的邊界有關。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":15},{"front":"the Palestinian areas","meaning":"巴勒斯坦地區","examples":[{"en":"The Jordan River basin borders the Palestinian areas.","zh":"約旦河流域與巴勒斯坦地區接壤。"},{"en":"The Palestinian areas refers to areas associated with the Palestinian people and their political territory.","zh":"the Palestinian areas 指與巴勒斯坦人民及其政治地域相關的地區。"},{"en":"In geography writing, the Palestinian areas may be mentioned when discussing borders, water, and regional politics.","zh":"在地理寫作中，討論邊界、水和地區政治時可能提及巴勒斯坦地區。"},{"en":"Water planning in the Palestinian areas is affected by limited land, shared resources, and political arrangements.","zh":"巴勒斯坦地區的水資源規劃受有限土地、共享資源和政治安排影響。"},{"en":"This phrase identifies a specific region in the Middle East.","zh":"這個片語指出中東的一個特定地區。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":15},{"front":"have claims to","meaning":"對……有權利要求","examples":[{"en":"Several countries have claims to the shared water supply.","zh":"幾個國家對共享水供應有權利要求。"},{"en":"To have claims to something means to say one has a right to use, own, or control it.","zh":"have claims to something 指聲稱自己有權使用、擁有或控制某物。"},{"en":"Two relatives may have claims to the same family house after an inheritance dispute.","zh":"在遺產爭議後，兩名親屬可能對同一間祖屋有權利要求。"},{"en":"Farmers and cities may both have claims to water from a river.","zh":"農民和城市可能都對河流水源有權利要求。"},{"en":"Claims can create conflict when the resource is limited.","zh":"當資源有限，權利要求可以造成衝突。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":15},{"front":"shared, but limited, supply","meaning":"共享但有限的供應","examples":[{"en":"The countries compete for a shared, but limited, water supply.","zh":"這些國家爭奪共享但有限的水供應。"},{"en":"A shared, but limited, supply is a resource used by several groups but not large enough for everyone’s wishes.","zh":"shared, but limited, supply 是多個群體共同使用，但不足以滿足所有人願望的資源。"},{"en":"Students may compete for a shared, but limited, supply of computers in a school library.","zh":"學生可能爭奪學校圖書館中共享但有限的電腦供應。"},{"en":"A shared, but limited, supply of parking spaces can cause arguments among residents.","zh":"共享但有限的泊車位供應可以引發居民之間的爭執。"},{"en":"Fair rules are needed when a supply is shared but limited.","zh":"當供應共享但有限時，需要公平規則。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":15},{"front":"extremely parched region","meaning":"極度乾旱的地區","examples":[{"en":"The Jordan River lies in an extremely parched region.","zh":"約旦河位於極度乾旱的地區。"},{"en":"An extremely parched region is a very dry area with little water or rainfall.","zh":"extremely parched region 指水或降雨很少的非常乾燥地區。"},{"en":"Villages in an extremely parched region may depend on wells and water trucks.","zh":"極度乾旱地區的村莊可能依賴水井和水車。"},{"en":"Farming is difficult in an extremely parched region unless irrigation is available.","zh":"除非有灌溉，否則在極度乾旱地區務農很困難。"},{"en":"Parched is stronger and more descriptive than simply “dry”.","zh":"parched 比單純的 dry 更強烈、更具描述性。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":15},{"front":"the struggle for freshwater","meaning":"對淡水的爭奪","examples":[{"en":"The struggle for freshwater has contributed to disputes.","zh":"對淡水的爭奪促成了糾紛。"},{"en":"The struggle for freshwater means competition or difficulty in obtaining enough clean water.","zh":"the struggle for freshwater 指取得足夠清潔水方面的競爭或困難。"},{"en":"During a drought, the struggle for freshwater may affect farmers, families, and factories.","zh":"在乾旱期間，對淡水的爭奪可能影響農民、家庭和工廠。"},{"en":"The struggle for freshwater can become political when different groups all depend on the same river.","zh":"當不同群體都依賴同一條河，對淡水的爭奪可以變成政治問題。"},{"en":"This phrase suggests pressure, competition, and possible conflict.","zh":"這個片語暗示壓力、競爭和可能的衝突。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":15},{"front":"contribute to","meaning":"導致；促成","examples":[{"en":"The struggle for freshwater has contributed to civil and military disputes.","zh":"對淡水的爭奪促成了民事及軍事糾紛。"},{"en":"To contribute to something means to help cause it or make it more likely.","zh":"contribute to something 指幫助造成某事或令它更可能發生。"},{"en":"Poor sleep can contribute to stress and weak concentration.","zh":"睡眠不足可以促成壓力和專注力下降。"},{"en":"Heavy traffic contributes to air pollution in many cities.","zh":"嚴重交通擠塞促成許多城市的空氣污染。"},{"en":"This phrase shows that one factor is part of the cause, not always the only cause.","zh":"這個片語顯示某因素是原因之一，但不一定是唯一原因。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":15},{"front":"civil and military disputes","meaning":"民事及軍事糾紛","examples":[{"en":"Water shortages have contributed to civil and military disputes.","zh":"水短缺促成了民事及軍事糾紛。"},{"en":"Civil and military disputes are conflicts involving ordinary political groups, communities, governments, or armed forces.","zh":"civil and military disputes 是涉及普通政治團體、社區、政府或武裝力量的衝突。"},{"en":"Civil disputes may involve citizens or local groups, while military disputes involve armed forces.","zh":"民事糾紛可能涉及公民或本地團體，而軍事糾紛涉及武裝力量。"},{"en":"Control of land or water can sometimes lead to civil and military disputes.","zh":"對土地或水的控制有時可以導致民事及軍事糾紛。"},{"en":"This phrase covers both non-military and military conflict.","zh":"這個片語涵蓋非軍事和軍事衝突。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":16},{"front":"continuing negotiations","meaning":"持續談判","examples":[{"en":"Continuing negotiations are needed to manage water tensions.","zh":"需要持續談判來管理水資源緊張。"},{"en":"Continuing negotiations are discussions that keep going over time in order to reach or maintain agreement.","zh":"continuing negotiations 是為達成或維持協議而隨時間持續進行的討論。"},{"en":"Continuing negotiations between teachers and the school may improve working conditions.","zh":"老師與學校之間的持續談判可能改善工作條件。"},{"en":"Neighbouring cities may need continuing negotiations to share transport costs fairly.","zh":"鄰近城市可能需要持續談判，以公平分擔交通成本。"},{"en":"This phrase suggests that one meeting is not enough to solve the issue.","zh":"這個片語暗示一次會議不足以解決問題。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":16},{"front":"compromises","meaning":"妥協","examples":[{"en":"Compromises have helped keep the tense situation under control.","zh":"妥協有助使緊張局勢受控。"},{"en":"Compromises are agreements in which each side gives up part of what it wants.","zh":"compromises 是各方放棄部分想要的東西而達成的協議。"},{"en":"Friends may reach compromises when choosing a restaurant that suits everyone.","zh":"朋友選擇適合所有人的餐廳時，可能達成妥協。"},{"en":"In politics, compromises can prevent conflict when groups disagree strongly.","zh":"在政治中，當群體嚴重分歧時，妥協可以防止衝突。"},{"en":"A compromise is not perfect for anyone, but it may be fair enough for all sides.","zh":"妥協對任何一方都不是完美，但可能對各方都算公平。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":16},{"front":"keep something under control","meaning":"使……受控","examples":[{"en":"Negotiations have kept the tense water situation under control.","zh":"談判使緊張的水資源局勢保持受控。"},{"en":"To keep something under control means to prevent a problem from becoming worse or chaotic.","zh":"keep something under control 指防止問題惡化或變得混亂。"},{"en":"A teacher keeps a noisy class under control by setting clear rules.","zh":"老師透過設定清楚規則使吵鬧的班級受控。"},{"en":"Firefighters worked to keep the forest fire under control before it reached homes.","zh":"消防員努力使森林大火受控，防止它到達民居。"},{"en":"This phrase suggests careful management of a dangerous or difficult situation.","zh":"這個片語暗示對危險或困難情況進行謹慎管理。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":16},{"front":"tense situation","meaning":"緊張局勢","examples":[{"en":"The shared water supply has created a tense situation.","zh":"共享水供應造成了緊張局勢。"},{"en":"A tense situation is one in which people feel worried, angry, or close to conflict.","zh":"tense situation 是令人感到擔憂、憤怒或接近衝突的情況。"},{"en":"A meeting can become a tense situation when two departments blame each other.","zh":"當兩個部門互相指責，會議可以變成緊張局勢。"},{"en":"A shortage of food or water can create a tense situation in a community.","zh":"食物或水短缺可以在社區中造成緊張局勢。"},{"en":"Calm communication can prevent a tense situation from turning into an open argument.","zh":"冷靜溝通可以防止緊張局勢變成公開爭執。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":16},{"front":"agree with the information given in","meaning":"與文中資料一致","examples":[{"en":"Candidates decide whether statements agree with the information given in the passage.","zh":"考生判斷陳述是否與文章中給出的資料一致。"},{"en":"Agree with the information given in means match what the text says.","zh":"agree with the information given in 指與文本所說的內容相符。"},{"en":"In a reading test, an answer is true if it agrees with the information given in the article.","zh":"在閱讀測驗中，如果答案與文章中給出的資料一致，它就是正確的。"},{"en":"A summary must agree with the information given in the report, not with the writer’s guess.","zh":"摘要必須與報告中給出的資料一致，而不是與作者猜測一致。"},{"en":"This phrase is common in TRUE/FALSE/NOT GIVEN questions.","zh":"這個片語常見於 TRUE/FALSE/NOT GIVEN 題。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":16},{"front":"write TRUE if","meaning":"如果……則寫TRUE","examples":[{"en":"Students write TRUE if the statement agrees with the information.","zh":"如果陳述與資料一致，學生則寫 TRUE。"},{"en":"Write TRUE if means choose TRUE when a condition is satisfied.","zh":"write TRUE if 指當條件符合時選擇 TRUE。"},{"en":"Write TRUE if the sentence says the same thing as the passage.","zh":"如果句子與文章意思相同，則寫 TRUE。"},{"en":"In a form, write TRUE if the applicant has completed all required documents.","zh":"在表格中，如果申請人已完成所有所需文件，則寫 TRUE。"},{"en":"This instruction tells students exactly when to mark an answer as true.","zh":"這個指示清楚告訴學生何時把答案標為真。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":16},{"front":"contradict the information","meaning":"與資料矛盾","examples":[{"en":"A statement is false if it contradicts the information.","zh":"如果陳述與資料矛盾，它就是 false。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"contradict the information 指說出與文本內容相反的事情。"},{"en":"If a passage says the shop opens at nine, “It opens at ten” contradicts the information.","zh":"如果文章說商店九點開門，「它十點開門」就與資料矛盾。"},{"en":"A student should not choose TRUE if the statement contradicts the information in the text.","zh":"如果陳述與文本資料矛盾，學生不應選 TRUE。"},{"en":"Contradiction is different from missing information because the text clearly says something opposite.","zh":"矛盾不同於資料缺失，因為文本清楚說出相反內容。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":16},{"front":"there is no information on this","meaning":"文中沒有相關資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果文中沒有相關資料，學生則寫 NOT GIVEN。"},{"en":"There is no information on this means the text does not tell us about that point.","zh":"there is no information on this 指文本沒有告訴我們關於該點的內容。"},{"en":"If the passage describes a teacher’s age but not her salary, there is no information on this salary question.","zh":"如果文章描述老師的年齡但沒有描述她的薪金，關於薪金的問題就是文中沒有相關資料。"},{"en":"Students should choose NOT GIVEN when there is no information on this in the passage.","zh":"當文中沒有相關資料時，學生應選 NOT GIVEN。"},{"en":"This phrase warns students not to use outside knowledge or guesses.","zh":"這個片語提醒學生不要使用外部知識或猜測。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":16},{"front":"the outlook for","meaning":"……的前景","examples":[{"en":"The question asks about the outlook for worldwide freshwater demand.","zh":"這條問題問及全球淡水需求的前景。"},{"en":"The outlook for something means the expected future situation or trend.","zh":"the outlook for something 指某事預期的未來情況或趨勢。"},{"en":"The outlook for small shops may improve if rent falls and customers return.","zh":"如果租金下降、顧客回流，小店的前景可能改善。"},{"en":"The outlook for a student’s exam result depends on practice, feedback, and time.","zh":"學生考試成績的前景取決於練習、回饋和時間。"},{"en":"This phrase is useful when discussing what may happen later.","zh":"當討論日後可能發生的事情時，這個片語很有用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":16},{"front":"worldwide freshwater demand","meaning":"全球淡水需求","examples":[{"en":"The outlook for worldwide freshwater demand is a central issue.","zh":"全球淡水需求的前景是一個核心問題。"},{"en":"Worldwide freshwater demand means the total need for freshwater across the whole world.","zh":"worldwide freshwater demand 指全世界對淡水的總需求。"},{"en":"Worldwide freshwater demand rises when populations grow and people use more water at home and work.","zh":"當人口增長並且人們在家中和工作中用更多水，全球淡水需求會上升。"},{"en":"Farming, industry, and cities all contribute to worldwide freshwater demand.","zh":"農業、工業和城市都促成全球淡水需求。"},{"en":"Understanding worldwide freshwater demand helps governments plan future water security.","zh":"理解全球淡水需求有助政府規劃未來水安全。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":16},{"front":"general awareness of","meaning":"對……的普遍意識","examples":[{"en":"General awareness of the problem has not removed the freshwater challenge.","zh":"對這個問題的普遍意識並沒有消除淡水挑戰。"},{"en":"General awareness of something means many people know about it, at least in a basic way.","zh":"general awareness of something 指許多人至少基本知道某事。"},{"en":"General awareness of healthy eating does not mean everyone eats well.","zh":"對健康飲食的普遍意識並不代表每個人都吃得健康。"},{"en":"General awareness of cybercrime can help people become more careful online.","zh":"對網絡罪案的普遍意識可以幫助人們在網上更謹慎。"},{"en":"Awareness is useful, but action is still needed to solve problems.","zh":"意識有用，但解決問題仍需要行動。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":17},{"front":"partly ease","meaning":"部分緩解","examples":[{"en":"The question asks whether awareness has partly eased the challenge.","zh":"這條問題問意識是否已部分緩解這項挑戰。"},{"en":"To partly ease a problem means to make it less serious, but not solve it completely.","zh":"partly ease a problem 指令問題不那麼嚴重，但沒有完全解決。"},{"en":"Extra buses can partly ease traffic during the morning rush hour.","zh":"增加巴士可以部分緩解早上繁忙時間的交通。"},{"en":"Free school meals may partly ease pressure on low-income families.","zh":"免費校餐可能部分緩解低收入家庭的壓力。"},{"en":"This phrase shows improvement, but also reminds us that the problem remains.","zh":"這個片語顯示改善，但也提醒我們問題仍然存在。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":17},{"front":"freshwater challenge","meaning":"淡水挑戰","examples":[{"en":"The freshwater challenge remains serious despite public awareness.","zh":"儘管公眾有意識，淡水挑戰仍然嚴重。"},{"en":"The freshwater challenge is the difficulty of providing enough safe freshwater for people, farms, and ecosystems.","zh":"freshwater challenge 是為人類、農場和生態系統提供足夠安全淡水的困難。"},{"en":"A growing city faces a freshwater challenge when demand rises faster than reservoirs can supply.","zh":"當需求升得比水庫供應更快，發展中的城市便面對淡水挑戰。"},{"en":"Climate change can make the freshwater challenge harder by changing rainfall patterns.","zh":"氣候變化可以透過改變降雨模式令淡水挑戰更困難。"},{"en":"This phrase summarises the problem of freshwater shortage, access, and safety.","zh":"這個片語概括了淡水短缺、取得途徑和安全的問題。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":17},{"front":"several compelling factors","meaning":"幾個令人信服的因素","examples":[{"en":"Researchers expect scarcity to increase because of several compelling factors.","zh":"研究人員預期短缺會因幾個令人信服的因素而增加。"},{"en":"Several compelling factors are several strong and convincing reasons that help explain a situation.","zh":"several compelling factors 指幾個有力而令人信服的原因，用來解釋某種情況。"},{"en":"A student may choose a university because of several compelling factors, such as cost, location, and course quality.","zh":"學生可能因幾個令人信服的因素選擇大學，例如費用、地點和課程質素。"},{"en":"Several compelling factors can explain why families move away from expensive cities.","zh":"幾個令人信服的因素可以解釋為何家庭搬離昂貴城市。"},{"en":"This phrase is useful when more than one strong reason matters.","zh":"當多於一個強力原因重要時，這個片語很有用。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":17},{"front":"careful use of scarce water","meaning":"謹慎使用稀缺水資源","examples":[{"en":"The careful use of scarce water is essential.","zh":"謹慎使用稀缺水資源非常重要。"},{"en":"Careful use of scarce water means using limited water wisely and avoiding waste.","zh":"careful use of scarce water 指明智使用有限水資源並避免浪費。"},{"en":"During a drought, careful use of scarce water may include shorter showers and less garden watering.","zh":"在乾旱期間，謹慎使用稀缺水資源可能包括縮短淋浴時間和減少澆花。"},{"en":"Careful use of scarce water can help hospitals, farms, and homes continue operating.","zh":"謹慎使用稀缺水資源可以幫助醫院、農場和家庭繼續運作。"},{"en":"This phrase stresses responsibility when water is limited.","zh":"這個片語強調在水有限時的責任。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":17},{"front":"controversy over","meaning":"關於……的爭議","examples":[{"en":"Controversy over water resources may occur in dry regions.","zh":"在乾旱地區，可能出現關於水資源的爭議。"},{"en":"Controversy over something means public disagreement or argument about it.","zh":"controversy over something 指關於某事的公開分歧或爭論。"},{"en":"There was controversy over the new school rule because parents disagreed about fairness.","zh":"新校規引起爭議，因為家長對公平性有不同意見。"},{"en":"Controversy over land use can delay housing projects.","zh":"關於土地用途的爭議可以延誤住房項目。"},{"en":"This phrase is used when people have strong opposing views.","zh":"當人們有強烈對立看法時，會使用這個片語。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":17},{"front":"be unavoidable between","meaning":"在……之間不可避免","examples":[{"en":"The question asks whether controversy is unavoidable between neighbouring nations.","zh":"這條問題問爭議是否在鄰近國家之間不可避免。"},{"en":"Be unavoidable between groups means conflict or difficulty cannot easily be prevented when those groups interact.","zh":"be unavoidable between groups 指當這些群體互動時，衝突或困難不容易避免。"},{"en":"Some disagreement may be unavoidable between roommates who have very different habits.","zh":"生活習慣很不同的室友之間，某些分歧可能不可避免。"},{"en":"Competition can be unavoidable between shops selling the same products in the same street.","zh":"在同一條街賣相同產品的商店之間，競爭可能不可避免。"},{"en":"This phrase suggests that a problem is likely unless careful action is taken.","zh":"這個片語暗示除非謹慎行動，否則問題很可能發生。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":17},{"front":"neighbouring nations","meaning":"鄰近國家","examples":[{"en":"Neighbouring nations may compete for shared river water.","zh":"鄰近國家可能爭奪共享河流水源。"},{"en":"Neighbouring nations are countries located next to or near each other.","zh":"neighbouring nations 是位於彼此旁邊或附近的國家。"},{"en":"Neighbouring nations often trade with each other and share roads, rivers, or borders.","zh":"鄰近國家經常互相貿易，並共享道路、河流或邊界。"},{"en":"If neighbouring nations disagree over water, transport, or security, tension may rise.","zh":"如果鄰近國家在水、交通或安全上有分歧，緊張可能上升。"},{"en":"Cooperation between neighbouring nations can make regional problems easier to solve.","zh":"鄰近國家之間的合作可以令地區問題更容易解決。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":17},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"The task asks which paragraph contains particular information.","zh":"這項任務問哪一段包含特定資料。"},{"en":"Which paragraph contains means students must find the paragraph where certain information appears.","zh":"which paragraph contains 指學生必須找出某些資料出現在哪一段。"},{"en":"In a reading test, “which paragraph contains a cause?” asks students to locate the relevant section.","zh":"在閱讀測驗中，「哪一段包含原因？」是要求學生找出相關部分。"},{"en":"If paragraph C describes the solution, then paragraph C contains the answer.","zh":"如果C段描述解決方法，那麼C段包含答案。"},{"en":"This phrase is common in matching-information reading questions.","zh":"這個片語常見於配對資料閱讀題。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":17},{"front":"may use any letter more than once","meaning":"可多次使用任何字母","examples":[{"en":"Candidates may use any letter more than once.","zh":"考生可多次使用任何字母。"},{"en":"May use any letter more than once means the same answer choice can be selected repeatedly.","zh":"may use any letter more than once 指同一答案選項可以重複選擇。"},{"en":"In a matching task, students may use any letter more than once if one paragraph answers several questions.","zh":"在配對題中，如果一段回答多條問題，學生可多次使用任何字母。"},{"en":"If B contains two pieces of information, candidates may use B more than once.","zh":"如果B包含兩項資料，考生可多次使用B。"},{"en":"This instruction prevents students from assuming each letter can be used only once.","zh":"這個指示防止學生以為每個字母只能使用一次。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":17},{"front":"uneven distribution of","meaning":"……的不均分布","examples":[{"en":"The question asks about the uneven distribution of water around the world.","zh":"這條問題問及世界各地水的不均分布。"},{"en":"Uneven distribution of something means it is not spread fairly or equally.","zh":"uneven distribution of something 指某物沒有公平或平均分散。"},{"en":"Uneven distribution of schools can leave rural children with fewer choices.","zh":"學校的不均分布可以令農村孩子選擇較少。"},{"en":"Uneven distribution of rainfall can cause floods in one region and drought in another.","zh":"降雨的不均分布可以在一個地區造成洪水，在另一個地區造成乾旱。"},{"en":"This phrase explains why enough total supply may still not solve local shortages.","zh":"這個片語解釋為何總供應足夠仍未必能解決本地短缺。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":17},{"front":"around the world","meaning":"在世界各地","examples":[{"en":"Water is distributed unevenly around the world.","zh":"水在世界各地分布不均。"},{"en":"Around the world means in many countries or all parts of the Earth.","zh":"around the world 指在許多國家或地球所有地方。"},{"en":"Students around the world learn English for study, travel, or work.","zh":"世界各地的學生為學習、旅遊或工作而學英語。"},{"en":"Food habits vary around the world because climate and culture differ.","zh":"世界各地的飲食習慣不同，因為氣候和文化不同。"},{"en":"This phrase makes the topic global rather than local.","zh":"這個片語令主題變成全球性的，而不是本地性的。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":18},{"front":"natural factors","meaning":"自然因素","examples":[{"en":"Natural factors such as rainfall and climate also concern policymakers.","zh":"降雨和氣候等自然因素也令政策制定者關注。"},{"en":"Natural factors are features of the natural world that affect a situation.","zh":"natural factors 是影響某情況的自然世界特徵。"},{"en":"Natural factors such as soil, sunlight, and rainfall affect how well crops grow.","zh":"泥土、陽光和降雨等自然因素影響農作物生長得好不好。"},{"en":"Natural factors can make one region wetter, drier, hotter, or colder than another.","zh":"自然因素可以令一個地區比另一個更濕、更乾、更熱或更冷。"},{"en":"This phrase separates nature’s influence from human decisions.","zh":"這個片語把自然影響與人類決定區分開來。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":18},{"front":"coordinated action","meaning":"協調行動","examples":[{"en":"The passage calls for coordinated action on water security.","zh":"文章呼籲就水安全採取協調行動。"},{"en":"Coordinated action means different people or groups work together in an organised way.","zh":"coordinated action 指不同人或群體以有組織的方式共同工作。"},{"en":"During a fire, coordinated action by firefighters, police, and hospitals saves time.","zh":"火災期間，消防員、警察和醫院的協調行動可節省時間。"},{"en":"A school needs coordinated action from teachers, parents, and students to reduce bullying.","zh":"學校需要老師、家長和學生的協調行動來減少欺凌。"},{"en":"This phrase suggests teamwork, planning, and shared responsibility.","zh":"這個片語暗示團隊合作、規劃和共同責任。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":18},{"front":"involving political, economic and technological measures","meaning":"涉及政治、經濟及技術措施","examples":[{"en":"Water planning requires action involving political, economic and technological measures.","zh":"水資源規劃需要涉及政治、經濟及技術措施的行動。"},{"en":"Involving political, economic and technological measures means including laws, financial incentives, and practical technologies.","zh":"involving political, economic and technological measures 指包括法律、財政誘因和實用技術。"},{"en":"Reducing traffic may require action involving political, economic and technological measures.","zh":"減少交通擠塞可能需要涉及政治、經濟及技術措施的行動。"},{"en":"A city can save energy by involving political, economic and technological measures in one plan.","zh":"城市可以透過在一個計劃中涉及政治、經濟及技術措施來節省能源。"},{"en":"This phrase shows that complex problems need more than one type of solution.","zh":"這個片語顯示複雜問題需要不只一種解決方法。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":18},{"front":"a mismatch between","meaning":"……之間的不配合","examples":[{"en":"The passage describes a mismatch between rainfall and human need.","zh":"文章描述降雨與人類需要之間的不配合。"},{"en":"A mismatch between two things means they do not fit or correspond well.","zh":"a mismatch between two things 指兩件事不合適或不相符。"},{"en":"There is a mismatch between students’ skills and the exam’s requirements.","zh":"學生技能與考試要求之間存在不配合。"},{"en":"A mismatch between bus times and work hours can make commuting difficult.","zh":"巴士時間與上班時間之間的不配合可以令通勤困難。"},{"en":"This phrase explains a problem caused by poor fit, not total absence.","zh":"這個片語解釋由不配合而不是完全缺乏造成的問題。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":18},{"front":"when water is needed","meaning":"需要水的時候","examples":[{"en":"Rain does not always fall when water is needed.","zh":"雨並不總是在需要水的時候降下。"},{"en":"When water is needed means at the time people, crops, or systems require water.","zh":"when water is needed 指在人們、農作物或系統需要水的時間。"},{"en":"Farms need irrigation when water is needed but rainfall has not arrived.","zh":"當需要水但降雨未到，農場便需要灌溉。"},{"en":"A city should store water before the dry season, so supply exists when water is needed.","zh":"城市應在旱季前儲水，讓需要水的時候有供應。"},{"en":"This phrase focuses on timing, not only quantity.","zh":"這個片語聚焦於時間，而不只是數量。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":18},{"front":"when rain falls","meaning":"下雨的時候","examples":[{"en":"The timing of rain does not always match human demand.","zh":"下雨的時間並不總是配合人類需求。"},{"en":"When rain falls means at the time rain comes down from the sky.","zh":"when rain falls 指雨從天空降下的時候。"},{"en":"When rain falls heavily, streets may flood if drains are blocked.","zh":"當下大雨時，如果排水渠堵塞，街道可能水浸。"},{"en":"Farmers plan planting around when rain falls each year.","zh":"農民會根據每年下雨的時候安排種植。"},{"en":"The issue is not only how much rain falls, but also when rain falls.","zh":"問題不只是下多少雨，也包括下雨的時候。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":18},{"front":"minimum amount of freshwater","meaning":"每人所需的最低淡水量","examples":[{"en":"The passage gives the minimum amount of freshwater a person needs.","zh":"文章給出了每人所需的最低淡水量。"},{"en":"Minimum amount of freshwater means the smallest quantity of usable low-salt water needed for basic life.","zh":"minimum amount of freshwater 指基本生活所需的最少可用低鹽水量。"},{"en":"A household should know the minimum amount of freshwater needed during an emergency.","zh":"家庭應知道緊急情況下所需的最低淡水量。"},{"en":"If supply falls below the minimum amount of freshwater, health and hygiene may suffer.","zh":"如果供應低於最低淡水量，健康和衞生可能受影響。"},{"en":"This phrase sets a basic survival level, not a comfortable level.","zh":"這個片語設定基本生存水平，而不是舒適水平。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":18},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Candidates complete the summary below using words from the passage.","zh":"考生使用文章中的字詞完成以下摘要。"},{"en":"Complete the summary below means fill in the missing words in the short text that follows.","zh":"complete the summary below 指填上下面短文中缺少的字詞。"},{"en":"In reading tests, students complete the summary below by finding exact information in the passage.","zh":"在閱讀測驗中，學生透過在文章中找出準確資料來完成以下摘要。"},{"en":"To complete the summary below correctly, students must understand both grammar and meaning.","zh":"要正確完成以下摘要，學生必須理解文法和意思。"},{"en":"This instruction asks for careful reading, not personal opinion.","zh":"這個指示要求細心閱讀，而不是個人意見。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":18},{"front":"no more than three words","meaning":"不多於三個字","examples":[{"en":"Candidates choose no more than three words from the passage.","zh":"考生從文章中選擇不多於三個字。"},{"en":"No more than three words means the answer must contain three words or fewer.","zh":"no more than three words 指答案必須包含三個或更少英文單字。"},{"en":"If the limit says no more than three words, “clean drinking water” is allowed but “a source of clean drinking water” is too long.","zh":"如果限制是不多於三個字，clean drinking water 可以，但 a source of clean drinking water 太長。"},{"en":"Students lose marks if they write four words when the instruction says no more than three words.","zh":"如果指示說不多於三個字，而學生寫四個字，便會失分。"},{"en":"This phrase sets a strict word limit for answers.","zh":"這個片語為答案設定嚴格字數限制。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":18},{"front":"serious problems such as","meaning":"例如……的嚴重問題","examples":[{"en":"Water shortages can cause serious problems such as starvation and conflict.","zh":"水短缺可以造成例如饑荒和衝突的嚴重問題。"},{"en":"Serious problems such as introduces examples of important and harmful problems.","zh":"serious problems such as 用來引入重要而有害問題的例子。"},{"en":"Poor housing can cause serious problems such as illness, stress, and school absence.","zh":"住房差劣可以造成疾病、壓力和缺課等嚴重問題。"},{"en":"A lack of public transport may create serious problems such as unemployment and isolation.","zh":"缺乏公共交通可能造成失業和孤立等嚴重問題。"},{"en":"This phrase helps give concrete examples after a general statement.","zh":"這個片語幫助在一般說法後給出具體例子。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":18},{"front":"result from","meaning":"源於；由……造成","examples":[{"en":"Serious social problems can result from water shortages.","zh":"嚴重社會問題可以源於水短缺。"},{"en":"To result from something means to be caused by it.","zh":"result from something 指由某事造成。"},{"en":"Tiredness can result from poor sleep and long working hours.","zh":"疲倦可以源於睡眠不足和工作時間長。"},{"en":"Traffic delays may result from road repairs or accidents.","zh":"交通延誤可能由道路工程或事故造成。"},{"en":"This phrase points backwards to the cause of a problem.","zh":"這個片語向前指出問題的原因。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":19},{"front":"kind of scarcity","meaning":"短缺類型","examples":[{"en":"Different regions suffer different kinds of scarcity.","zh":"不同地區遭受不同短缺類型。"},{"en":"A kind of scarcity is a type of shortage or lack.","zh":"kind of scarcity 指短缺或缺乏的一種類型。"},{"en":"Food scarcity and water scarcity are different kinds of scarcity.","zh":"食物短缺和水資源短缺是不同短缺類型。"},{"en":"A city may face one kind of scarcity in housing and another in hospital beds.","zh":"城市可能面對一種住房短缺，另有一種醫院床位短缺。"},{"en":"This phrase helps classify shortages instead of treating them all as the same.","zh":"這個片語幫助分類短缺，而不是把所有短缺視為相同。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":19},{"front":"resources and institutions","meaning":"資源和制度","examples":[{"en":"Resources and institutions may be inadequate in some regions.","zh":"在一些地區，資源和制度可能不足。"},{"en":"Resources and institutions means the money, equipment, people, rules, and organisations needed to make a system work.","zh":"resources and institutions 指令系統運作所需的金錢、設備、人員、規則和組織。"},{"en":"A healthcare system needs resources and institutions such as hospitals, trained staff, and clear rules.","zh":"醫療系統需要醫院、受訓員工和清晰規則等資源和制度。"},{"en":"If resources and institutions are weak, clean water may not reach households even when rivers exist nearby.","zh":"如果資源和制度薄弱，即使附近有河流，清潔食水也未必能到達家庭。"},{"en":"This phrase combines practical supplies with the organisations that manage them.","zh":"這個片語結合實際供應和管理它們的組織。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":19},{"front":"be inadequate","meaning":"不足的；不充分的","examples":[{"en":"Access may be limited because resources and institutions are inadequate.","zh":"取得途徑可能受限，因為資源和制度不足。"},{"en":"Be inadequate means to be not enough or not good enough for what is needed.","zh":"be inadequate 指不足夠或不夠好，無法滿足需要。"},{"en":"A meal is inadequate if it does not provide enough nutrition.","zh":"如果一餐不能提供足夠營養，它就是不足的。"},{"en":"Training is inadequate when workers still do not know how to do the job safely.","zh":"當工人仍不知道如何安全工作，培訓就是不充分的。"},{"en":"If support is inadequate, small problems can become serious.","zh":"如果支援不足，小問題可以變得嚴重。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":19},{"front":"much of the rainfall","meaning":"大部分降雨","examples":[{"en":"Much of the rainfall is unavailable for human use.","zh":"大部分降雨不可供人類使用。"},{"en":"Much of the rainfall means a large part of the rain that falls.","zh":"much of the rainfall 指落下的雨中很大一部分。"},{"en":"Much of the rainfall in a storm may run into drains before it can be stored.","zh":"風暴中的大部分降雨可能在可被儲存前流入排水渠。"},{"en":"In forests, much of the rainfall is absorbed by soil and plants.","zh":"在森林中，大部分降雨被泥土和植物吸收。"},{"en":"This phrase refers to a large proportion, not necessarily all of the rain.","zh":"這個片語指很大比例，但不一定是全部雨水。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":19},{"front":"the remaining water","meaning":"餘下的水","examples":[{"en":"The remaining water enters blue-water sources.","zh":"餘下的水進入藍水水源。"},{"en":"The remaining water means the water left after another part has been removed, used, or absorbed.","zh":"the remaining water 指另一部分被移走、使用或吸收後剩下的水。"},{"en":"After plants absorb some rain, the remaining water may flow into a stream.","zh":"植物吸收部分雨水後，餘下的水可能流入溪流。"},{"en":"A family may drink some stored water and save the remaining water for cooking.","zh":"家庭可能飲用部分儲存水，並把餘下的水留作煮食。"},{"en":"This phrase helps show what happens to the leftover part.","zh":"這個片語幫助說明剩餘部分發生甚麼。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":19},{"front":"irrigation consumes","meaning":"灌溉消耗","examples":[{"en":"Irrigation consumes a considerable amount of freshwater.","zh":"灌溉消耗相當大量的淡水。"},{"en":"Irrigation consumes means watering crops uses up a certain amount of water.","zh":"irrigation consumes 指為農作物供水會用去一定數量的水。"},{"en":"Rice farming often consumes large amounts of water through irrigation.","zh":"稻米種植經常透過灌溉消耗大量水。"},{"en":"If irrigation consumes too much water, less may remain for homes and rivers.","zh":"如果灌溉消耗太多水，留給家庭和河流的水可能更少。"},{"en":"Efficient systems reduce how much water irrigation consumes.","zh":"高效系統可減少灌溉消耗的水量。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":19},{"front":"a considerable amount","meaning":"相當大的數量","examples":[{"en":"Irrigation consumes a considerable amount of available water.","zh":"灌溉消耗可用水中相當大的數量。"},{"en":"A considerable amount means a fairly large amount that is important enough to notice.","zh":"a considerable amount 指相當大、值得注意的數量。"},{"en":"A student needs a considerable amount of practice to improve pronunciation.","zh":"學生需要相當大的練習量來改善發音。"},{"en":"A leaky pipe can waste a considerable amount of water over a month.","zh":"漏水水管在一個月內可以浪費相當大的水量。"},{"en":"This phrase is stronger than “some” but usually less exact than a number.","zh":"這個片語比 some 更強，但通常不如數字精確。"}],"source":"Flash Cards - 163 - Crisis! freshwater.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 164":[{"front":"knowledge in medicine","meaning":"醫學中的知識","examples":[{"en":"The passage explores the nature of knowledge in medicine.","zh":"文章探討醫學中的知識本質。"},{"en":"Knowledge in medicine includes personal experience, expert diagnosis, scientific evidence and clinical judgement.","zh":"醫學中的知識包括個人經驗、專家診斷、科學證據和臨床判斷。"},{"en":"Doctors use knowledge in medicine to interpret symptoms and decide on treatment.","zh":"醫生使用醫學中的知識來詮釋症狀並決定治療。"},{"en":"Patients also contribute to knowledge in medicine by describing how they feel.","zh":"病人也透過描述自己的感受，為醫學中的知識作出貢獻。"},{"en":"The phrase shows that medical understanding comes from more than one source.","zh":"這個短語顯示醫學理解來自不只一個來源。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":1},{"front":"count as knowledge","meaning":"算作知識","examples":[{"en":"The passage asks what counts as knowledge.","zh":"文章詢問甚麼算作知識。"},{"en":"To count as knowledge means to be accepted as something we can reasonably say we know.","zh":"算作知識是指被接受為我們可以合理地說自己知道的東西。"},{"en":"A doctor’s diagnosis may count as knowledge because it is based on training and evidence.","zh":"醫生的診斷可能算作知識，因為它建基於訓練和證據。"},{"en":"A personal feeling may count as knowledge, but it may need confirmation.","zh":"個人感受可能算作知識，但也可能需要確認。"},{"en":"The phrase raises questions about authority, evidence and certainty.","zh":"這個短語提出關於權威、證據和確定性的問題。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":1},{"front":"what do we mean when","meaning":"當我們……時是甚麼意思","examples":[{"en":"What do we mean when we say that we know something?","zh":"當我們說自己知道某事時，是甚麼意思？"},{"en":"“What do we mean when” asks for the meaning behind a statement or expression.","zh":"「當我們……時是甚麼意思」詢問某句話或表達背後的含義。"},{"en":"What do we mean when we say that a patient is seriously ill?","zh":"當我們說一名病人病得嚴重時，是甚麼意思？"},{"en":"The phrase encourages readers to examine assumptions more carefully.","zh":"這個短語鼓勵讀者更仔細檢視假設。"},{"en":"It is often used to begin a philosophical or analytical question.","zh":"它常用於開始哲學性或分析性問題。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":1},{"front":"the status of","meaning":"……的地位","examples":[{"en":"The passage questions the status of different kinds of knowledge.","zh":"文章質疑不同種類知識的地位。"},{"en":"The status of something is its position, importance or authority in a system.","zh":"某事物的地位是它在一個系統中的位置、重要性或權威。"},{"en":"Medical knowledge has a special status in contemporary Western culture.","zh":"醫學知識在當代西方文化中具有特殊地位。"},{"en":"A patient’s experience may have a different status from a doctor’s diagnosis.","zh":"病人的經驗可能與醫生診斷具有不同地位。"},{"en":"The phrase is useful when comparing forms of authority.","zh":"這個短語適合用於比較不同形式的權威。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":1},{"front":"different kinds of knowledge","meaning":"不同種類的知識","examples":[{"en":"Medicine involves different kinds of knowledge.","zh":"醫學涉及不同種類的知識。"},{"en":"Different kinds of knowledge may include personal experience, scientific facts and expert judgement.","zh":"不同種類的知識可以包括個人經驗、科學事實和專家判斷。"},{"en":"Patients and doctors may rely on different kinds of knowledge when discussing illness.","zh":"病人和醫生在討論疾病時可能依賴不同種類的知識。"},{"en":"Some kinds of knowledge are socially accepted as more authoritative than others.","zh":"有些知識形式在社會上被視為比其他形式更具權威。"},{"en":"The phrase highlights variety rather than one single truth source.","zh":"這個短語強調多樣性，而不是單一真理來源。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":1},{"front":"in order to","meaning":"為了","examples":[{"en":"In order to explore these questions, the passage focuses on medicine.","zh":"為了探討這些問題，文章聚焦於醫學。"},{"en":"“In order to” means for the purpose of doing something.","zh":"「為了」表示以做某事為目的。"},{"en":"The doctor ordered tests in order to confirm the diagnosis.","zh":"醫生安排檢查，為了確認診斷。"},{"en":"Patients describe symptoms in order to help doctors understand their condition.","zh":"病人描述症狀，為了幫助醫生了解其情況。"},{"en":"The phrase introduces purpose or intention.","zh":"這個短語帶出目的或意圖。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":1},{"front":"explore these questions","meaning":"探討這些問題","examples":[{"en":"The writer explores these questions through the example of illness.","zh":"作者透過疾病的例子探討這些問題。"},{"en":"To explore these questions means to examine them carefully and thoughtfully.","zh":"探討這些問題是指仔細而深入地審視它們。"},{"en":"The passage explores these questions by comparing personal feelings and medical diagnosis.","zh":"文章透過比較個人感受和醫學診斷來探討這些問題。"},{"en":"Writers may explore questions without giving simple final answers.","zh":"作者可以探討問題，而不一定給出簡單最終答案。"},{"en":"The phrase suggests investigation and reflection.","zh":"這個短語暗示調查和反思。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":1},{"front":"focus on","meaning":"聚焦於","examples":[{"en":"The passage focuses on one particular area of knowledge.","zh":"文章聚焦於某一特定知識範疇。"},{"en":"To focus on something means to give special attention to it.","zh":"聚焦於某事是指特別注意它。"},{"en":"The doctor focused on the patient’s cough and tiredness.","zh":"醫生聚焦於病人的咳嗽和疲倦。"},{"en":"The passage focuses on medicine as an example of knowledge.","zh":"文章以醫學作為知識例子來聚焦討論。"},{"en":"The phrase narrows attention to a chosen topic.","zh":"這個短語把注意力收窄到所選主題。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":1},{"front":"one particular area of","meaning":"某一特定範疇的……","examples":[{"en":"The writer focuses on one particular area of knowledge.","zh":"作者聚焦於某一特定範疇的知識。"},{"en":"One particular area of something means one specific part or field within a larger subject.","zh":"某一特定範疇的某事，是指較大主題中的一個具體部分或領域。"},{"en":"Medicine is one particular area of knowledge examined in the passage.","zh":"醫學是文章審視的某一特定知識範疇。"},{"en":"A researcher may study one particular area of health rather than the whole system.","zh":"研究人員可能研究健康的某一特定範疇，而不是整個系統。"},{"en":"The phrase highlights a focused section of a broader topic.","zh":"這個短語強調廣泛主題中的集中部分。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":1},{"front":"this may seem to be","meaning":"這看似是","examples":[{"en":"This may seem to be an absurd question.","zh":"這看似是一個荒謬的問題。"},{"en":"“This may seem to be” means something may appear that way at first.","zh":"「這看似是」表示某事起初可能顯得如此。"},{"en":"This may seem to be a simple illness, but the diagnosis could be serious.","zh":"這看似是一種簡單疾病，但診斷可能很嚴重。"},{"en":"The phrase prepares readers for a deeper explanation.","zh":"這個短語為更深入的解釋作鋪墊。"},{"en":"It shows that first impressions may be misleading.","zh":"它顯示第一印象可能具誤導性。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":1},{"front":"an absurd question","meaning":"荒謬的問題","examples":[{"en":"The question of how we know we are ill may seem absurd.","zh":"我們如何知道自己生病這個問題可能看似荒謬。"},{"en":"An absurd question is a question that seems strange, unreasonable or unnecessary at first.","zh":"荒謬的問題是起初看似奇怪、不合理或沒有必要的問題。"},{"en":"Asking whether pain counts as knowledge may sound like an absurd question.","zh":"詢問疼痛是否算作知識，可能聽起來像荒謬的問題。"},{"en":"An absurd question can become meaningful after careful analysis.","zh":"荒謬的問題經過仔細分析後可以變得有意義。"},{"en":"The phrase signals that the writer will challenge common assumptions.","zh":"這個短語表示作者將挑戰常見假設。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":1},{"front":"feel ill","meaning":"感到不適","examples":[{"en":"You may know you are ill because you feel ill.","zh":"你可能因為感到不適而知道自己生病。"},{"en":"To feel ill means to experience bodily discomfort or sickness.","zh":"感到不適是指經歷身體不舒服或生病感。"},{"en":"A person may feel ill before any doctor confirms a diagnosis.","zh":"一個人在醫生確認診斷前可能已感到不適。"},{"en":"Feeling ill can be an important reason for seeking medical advice.","zh":"感到不適可以是尋求醫療意見的重要原因。"},{"en":"The phrase describes personal bodily experience.","zh":"這個短語描述個人的身體經驗。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":2},{"front":"your body tells you that","meaning":"你的身體告訴你","examples":[{"en":"Your body tells you that you are ill.","zh":"你的身體告訴你自己生病了。"},{"en":"“Your body tells you that” means bodily feelings give you information.","zh":"「你的身體告訴你」表示身體感覺給你資料。"},{"en":"Pain, tiredness and fever may be ways your body tells you that something is wrong.","zh":"疼痛、疲倦和發燒可能是身體告訴你有問題的方式。"},{"en":"The phrase treats physical symptoms as a kind of message.","zh":"這個短語把身體症狀視為一種訊息。"},{"en":"It links bodily experience with personal knowledge.","zh":"它把身體經驗與個人知識連接起來。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":2},{"front":"feel pain or discomfort","meaning":"感到疼痛或不適","examples":[{"en":"You may know that you feel pain or discomfort.","zh":"你可能知道自己感到疼痛或不適。"},{"en":"To feel pain or discomfort means to experience unpleasant physical sensations.","zh":"感到疼痛或不適是指經歷不愉快的身體感覺。"},{"en":"A patient may feel pain or discomfort before the illness is identified.","zh":"病人在疾病被確認前可能已感到疼痛或不適。"},{"en":"Doctors often ask where patients feel pain or discomfort.","zh":"醫生常問病人在何處感到疼痛或不適。"},{"en":"The phrase refers to subjective bodily experience.","zh":"這個短語指主觀身體經驗。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":2},{"front":"a bit more complex","meaning":"較為複雜","examples":[{"en":"Knowing that you are ill is a bit more complex.","zh":"知道自己生病這件事較為複雜。"},{"en":"A bit more complex means slightly more complicated than it first appears.","zh":"較為複雜表示比起初看來稍微更複雜。"},{"en":"The diagnosis is a bit more complex because symptoms can have many causes.","zh":"診斷較為複雜，因為症狀可以有許多原因。"},{"en":"Feeling tired may be a bit more complex than simply needing sleep.","zh":"感到疲倦可能比單純需要睡眠較為複雜。"},{"en":"The phrase warns that the issue needs deeper thought.","zh":"這個短語提醒該問題需要更深入思考。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":2},{"front":"at times","meaning":"有時候","examples":[{"en":"At times, people experience symptoms but are not truly ill.","zh":"有時候，人們出現症狀但並非真正生病。"},{"en":"“At times” means sometimes or on certain occasions.","zh":"「有時候」表示有時或在某些情況下。"},{"en":"At times, stress can feel like physical illness.","zh":"有時候，壓力可能感覺像身體疾病。"},{"en":"Patients may at times misinterpret tiredness as disease.","zh":"病人有時可能把疲倦誤解為疾病。"},{"en":"The phrase introduces occasional situations.","zh":"這個短語帶出偶爾出現的情況。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":2},{"front":"experience the symptoms of illness","meaning":"出現疾病症狀","examples":[{"en":"People may experience the symptoms of illness when they are tired.","zh":"人們疲倦時可能出現疾病症狀。"},{"en":"To experience the symptoms of illness means to feel signs that seem connected with being sick.","zh":"出現疾病症狀是指感到似乎與生病有關的徵象。"},{"en":"Someone may experience the symptoms of illness after several nights without sleep.","zh":"有人連續數晚睡眠不足後可能出現疾病症狀。"},{"en":"Symptoms do not always prove that a serious disease is present.","zh":"症狀不一定證明有嚴重疾病存在。"},{"en":"The phrase focuses on what a person feels or notices.","zh":"這個短語集中於個人感受到或注意到的東西。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":2},{"front":"in fact","meaning":"事實上","examples":[{"en":"In fact, they may simply be tired or overworked.","zh":"事實上，他們可能只是疲倦或過勞。"},{"en":"“In fact” introduces a clarification or correction.","zh":"「事實上」用來帶出澄清或修正。"},{"en":"You may think you are ill; in fact, you may be exhausted.","zh":"你可能以為自己生病；事實上，你可能只是太累。"},{"en":"The phrase can contrast appearance with reality.","zh":"這個短語可以把表面情況與實際情況作對比。"},{"en":"It helps the writer move from assumption to explanation.","zh":"它幫助作者由假設轉向解釋。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":2},{"front":"simply tired or overworked","meaning":"只是疲倦或過勞","examples":[{"en":"Some people are simply tired or overworked rather than ill.","zh":"有些人只是疲倦或過勞，而不是生病。"},{"en":"Simply tired or overworked means only exhausted from effort, stress or too much work.","zh":"只是疲倦或過勞表示只因努力、壓力或工作太多而精疲力盡。"},{"en":"A person who is simply tired or overworked may still feel physically uncomfortable.","zh":"只是疲倦或過勞的人仍可能感到身體不適。"},{"en":"Such feelings can be confused with illness.","zh":"這些感覺可能與疾病混淆。"},{"en":"The phrase contrasts ordinary exhaustion with disease.","zh":"這個短語把一般疲憊與疾病作對比。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":2},{"front":"have a hangover","meaning":"宿醉","examples":[{"en":"Some people may just have a hangover.","zh":"有些人可能只是宿醉。"},{"en":"To have a hangover means to feel unwell after drinking too much alcohol.","zh":"宿醉是指飲酒過多後感到不適。"},{"en":"Someone with a hangover may feel tired, sick or have a headache.","zh":"宿醉的人可能感到疲倦、噁心或頭痛。"},{"en":"A hangover can produce symptoms that feel like illness.","zh":"宿醉可以產生像疾病一樣的症狀。"},{"en":"The phrase gives an example of discomfort that may not be disease.","zh":"這個短語舉出一種不適但未必是疾病的例子。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":2},{"front":"at other times","meaning":"另一些時候","examples":[{"en":"At other times, people may have a disease without realising it.","zh":"另一些時候，人們可能患病而不自知。"},{"en":"“At other times” introduces a different situation from the one just mentioned.","zh":"「另一些時候」帶出與剛才提及情況不同的另一情況。"},{"en":"At other times, symptoms may be absent even when disease is present.","zh":"另一些時候，即使疾病存在，症狀也可能不明顯。"},{"en":"The phrase helps show contrast between different cases.","zh":"這個短語有助顯示不同情況之間的對比。"},{"en":"It suggests that illness knowledge can be uncertain in more than one way.","zh":"它暗示疾病知識可以以多於一種方式變得不確定。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":2},{"front":"suffer from a disease","meaning":"患有疾病","examples":[{"en":"People may be suffering from a disease without knowing it.","zh":"人們可能患有疾病而不自知。"},{"en":"To suffer from a disease means to have or be affected by an illness.","zh":"患有疾病是指有某種疾病或受其影響。"},{"en":"A patient may suffer from pneumonia before receiving a diagnosis.","zh":"病人在獲得診斷前可能已患有肺炎。"},{"en":"Some diseases develop quietly before people notice symptoms.","zh":"有些疾病在人們注意到症狀前會悄悄發展。"},{"en":"The phrase focuses on being affected by illness.","zh":"這個短語集中於受疾病影響。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":2},{"front":"fail to be aware of","meaning":"未能察覺","examples":[{"en":"Some people fail to be aware of their illness.","zh":"有些人未能察覺自己的疾病。"},{"en":"To fail to be aware of something means not to notice or understand it.","zh":"未能察覺某事是指沒有注意到或理解它。"},{"en":"A patient may fail to be aware of early symptoms.","zh":"病人可能未能察覺早期症狀。"},{"en":"People can fail to be aware of illness when signs are mild.","zh":"當徵象輕微時，人們可能未能察覺疾病。"},{"en":"The phrase shows lack of recognition or understanding.","zh":"這個短語顯示缺乏認知或理解。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":3},{"front":"reach a late stage","meaning":"到達後期階段","examples":[{"en":"The illness may reach a late stage before people notice it.","zh":"疾病可能在人們注意到之前已到達後期階段。"},{"en":"To reach a late stage means to develop to an advanced point.","zh":"到達後期階段是指發展到較晚或較嚴重的階段。"},{"en":"Some diseases reach a late stage before symptoms become obvious.","zh":"有些疾病在症狀明顯前已到達後期階段。"},{"en":"Late-stage illness may require more serious treatment.","zh":"後期疾病可能需要更嚴肅的治療。"},{"en":"The phrase describes progression over time.","zh":"這個短語描述隨時間推進的發展。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":3},{"front":"in its development","meaning":"在其發展過程中","examples":[{"en":"A disease may reach a late stage in its development.","zh":"疾病可能在其發展過程中到達後期階段。"},{"en":"“In its development” means during the process by which something grows or progresses.","zh":"「在其發展過程中」表示在某事成長或推進的過程中。"},{"en":"A disease can be hidden early in its development.","zh":"疾病在其發展早期可能不明顯。"},{"en":"Doctors try to identify illness early in its development.","zh":"醫生嘗試在疾病發展早期識別它。"},{"en":"The phrase focuses on the process of change.","zh":"這個短語集中於變化過程。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":3},{"front":"think about this example","meaning":"想想這個例子","examples":[{"en":"Think about this example of a person who feels unwell.","zh":"想想這個感到不適的人的例子。"},{"en":"“Think about this example” asks readers to consider a case carefully.","zh":"「想想這個例子」要求讀者仔細考慮一個個案。"},{"en":"Think about this example before deciding what counts as medical knowledge.","zh":"在決定甚麼算作醫學知識前，想想這個例子。"},{"en":"The phrase invites readers to use a concrete situation for analysis.","zh":"這個短語邀請讀者用具體情況作分析。"},{"en":"It helps move from abstract ideas to everyday experience.","zh":"它幫助由抽象概念轉向日常經驗。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":3},{"front":"feel unwell","meaning":"感到不適","examples":[{"en":"You feel unwell and decide to visit the doctor.","zh":"你感到不適，於是決定看醫生。"},{"en":"To feel unwell means to feel physically not right or not healthy.","zh":"感到不適是指身體感覺不對勁或不健康。"},{"en":"A person may feel unwell because of infection, stress or exhaustion.","zh":"一個人可能因感染、壓力或疲憊而感到不適。"},{"en":"Feeling unwell is often the first reason people seek medical help.","zh":"感到不適通常是人們尋求醫療幫助的第一個原因。"},{"en":"The phrase is general and does not name a specific illness.","zh":"這個短語很概括，沒有指出特定疾病。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":3},{"front":"have a bad cough","meaning":"咳得厲害","examples":[{"en":"You have a bad cough and always seem to be tired.","zh":"你咳得厲害，而且似乎總是很疲倦。"},{"en":"To have a bad cough means to cough frequently or severely.","zh":"咳得厲害是指經常或嚴重咳嗽。"},{"en":"A bad cough can be a symptom of infection or lung problems.","zh":"嚴重咳嗽可以是感染或肺部問題的症狀。"},{"en":"Doctors may ask how long you have had a bad cough.","zh":"醫生可能會問你咳得厲害已有多久。"},{"en":"The phrase describes one visible or noticeable symptom.","zh":"這個短語描述一個明顯或可察覺的症狀。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":3},{"front":"seem to be tired","meaning":"似乎很疲倦","examples":[{"en":"You always seem to be tired.","zh":"你似乎總是很疲倦。"},{"en":"To seem to be tired means to appear exhausted or low in energy.","zh":"似乎很疲倦是指看起來精疲力盡或缺乏精力。"},{"en":"A patient who seems to be tired may be overworked or ill.","zh":"似乎很疲倦的病人可能是過勞，也可能是生病。"},{"en":"Tiredness alone may not clearly identify the cause of illness.","zh":"單靠疲倦未必能清楚識別疾病原因。"},{"en":"The phrase shows uncertainty based on appearance or feeling.","zh":"這個短語顯示基於外表或感覺的不確定性。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":3},{"front":"stress at work","meaning":"工作壓力","examples":[{"en":"Perhaps the problem is stress at work.","zh":"問題也許是工作壓力。"},{"en":"Stress at work means pressure, worry or strain connected with employment.","zh":"工作壓力是與工作有關的壓力、憂慮或負擔。"},{"en":"Stress at work can affect sleep, mood and physical comfort.","zh":"工作壓力可以影響睡眠、情緒和身體舒適感。"},{"en":"People may explain tiredness and coughing as stress at work before seeing a doctor.","zh":"人們在看醫生前可能把疲倦和咳嗽解釋為工作壓力。"},{"en":"The phrase shows how social experience can shape illness explanations.","zh":"這個短語顯示社會經驗如何塑造疾病解釋。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":3},{"front":"give up smoking","meaning":"戒煙","examples":[{"en":"Perhaps you should give up smoking.","zh":"也許你應該戒煙。"},{"en":"To give up smoking means to stop smoking cigarettes or tobacco.","zh":"戒煙是指停止吸香煙或煙草。"},{"en":"A doctor may advise a patient with a cough to give up smoking.","zh":"醫生可能建議咳嗽的病人戒煙。"},{"en":"Giving up smoking can improve breathing and long-term health.","zh":"戒煙可以改善呼吸和長遠健康。"},{"en":"The phrase suggests a possible lifestyle explanation or treatment.","zh":"這個短語暗示一種可能的生活方式解釋或治療。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":3},{"front":"visit the doctor","meaning":"看醫生","examples":[{"en":"You visit the doctor when your symptoms get worse.","zh":"當症狀惡化時，你去看醫生。"},{"en":"To visit the doctor means to go to a medical professional for advice or treatment.","zh":"看醫生是指去找醫療專業人士尋求建議或治療。"},{"en":"People visit the doctor when personal judgement is not enough.","zh":"當個人判斷不足夠時，人們會看醫生。"},{"en":"A doctor’s examination can change how a patient understands symptoms.","zh":"醫生檢查可以改變病人對症狀的理解。"},{"en":"The phrase marks the move from personal knowledge to expert assessment.","zh":"這個短語標示由個人知識轉向專家評估。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":3},{"front":"listen to your chest and heart","meaning":"聽診胸口和心臟","examples":[{"en":"The doctor listens to your chest and heart.","zh":"醫生聽診你的胸口和心臟。"},{"en":"To listen to your chest and heart means to examine breathing and heartbeat, usually with a stethoscope.","zh":"聽診胸口和心臟是指通常用聽診器檢查呼吸和心跳。"},{"en":"The doctor listens to your chest and heart to look for signs of illness.","zh":"醫生聽診胸口和心臟，以尋找疾病徵象。"},{"en":"This examination can provide evidence beyond what the patient feels.","zh":"這項檢查可以提供超越病人感受的證據。"},{"en":"The phrase describes a basic part of medical assessment.","zh":"這個短語描述醫學評估的基本部分。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":3},{"front":"take your temperature","meaning":"量體溫","examples":[{"en":"The doctor takes your temperature.","zh":"醫生為你量體溫。"},{"en":"To take your temperature means to measure how hot your body is.","zh":"量體溫是指測量身體有多熱。"},{"en":"A high temperature may suggest infection.","zh":"體溫高可能顯示感染。"},{"en":"Doctors take temperature as one piece of evidence during examination.","zh":"醫生量體溫，把它作為檢查中的一項證據。"},{"en":"The phrase describes a common medical measurement.","zh":"這個短語描述常見醫學量度。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":4},{"front":"blood pressure","meaning":"血壓","examples":[{"en":"The doctor takes your blood pressure.","zh":"醫生為你量血壓。"},{"en":"Blood pressure is the force of blood pushing against the walls of blood vessels.","zh":"血壓是血液推向血管壁的力量。"},{"en":"Blood pressure can give doctors information about circulation and health.","zh":"血壓可以為醫生提供有關循環和健康的資料。"},{"en":"A medical examination may include checking blood pressure and temperature.","zh":"醫學檢查可能包括量血壓和體溫。"},{"en":"The phrase names a measurable sign used in diagnosis.","zh":"這個短語命名診斷中使用的可量度徵象。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":4},{"front":"prescribe antibiotics","meaning":"處方抗生素","examples":[{"en":"The doctor prescribes antibiotics for your cough.","zh":"醫生為你的咳嗽處方抗生素。"},{"en":"To prescribe antibiotics means to officially order antibiotic medicine for a patient.","zh":"處方抗生素是指正式為病人開抗生素藥物。"},{"en":"Doctors prescribe antibiotics when they suspect a bacterial infection.","zh":"醫生在懷疑細菌感染時會處方抗生素。"},{"en":"Antibiotics should be used according to medical instructions.","zh":"抗生素應按照醫療指示使用。"},{"en":"The phrase shows the doctor’s authority to provide treatment.","zh":"這個短語顯示醫生提供治療的權限。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":4},{"front":"things do not improve","meaning":"情況沒有改善","examples":[{"en":"Things do not improve after you take the medicine.","zh":"服藥後情況沒有改善。"},{"en":"“Things do not improve” means the situation or symptoms do not get better.","zh":"「情況沒有改善」表示情況或症狀沒有變好。"},{"en":"If things do not improve, a patient may need another appointment.","zh":"如果情況沒有改善，病人可能需要再次求診。"},{"en":"The phrase can signal that the first explanation or treatment may be wrong.","zh":"這個短語可以表示最初的解釋或治療可能有誤。"},{"en":"It shows continuing uncertainty in the illness scenario.","zh":"它顯示疾病情境中的持續不確定性。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":4},{"front":"struggle on","meaning":"勉強撐下去","examples":[{"en":"You struggle on even though you still feel unwell.","zh":"即使仍感到不適，你仍勉強撐下去。"},{"en":"To struggle on means to continue despite difficulty or discomfort.","zh":"勉強撐下去是指儘管困難或不適仍繼續。"},{"en":"A worker may struggle on because they think symptoms are only stress.","zh":"工人可能因為以為症狀只是壓力而勉強撐下去。"},{"en":"Struggling on can delay proper diagnosis.","zh":"勉強撐下去可能延誤正確診斷。"},{"en":"The phrase suggests effort and persistence under strain.","zh":"這個短語暗示在壓力下努力堅持。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":4},{"front":"pull yourself together","meaning":"振作起來","examples":[{"en":"You think you should pull yourself together and keep going.","zh":"你認為自己應該振作起來並繼續下去。"},{"en":"To pull yourself together means to regain self-control and continue functioning.","zh":"振作起來是指重新控制自己並繼續應付事情。"},{"en":"Someone may tell themselves to pull themselves together instead of seeking help.","zh":"有人可能叫自己振作起來，而不是尋求幫助。"},{"en":"The phrase can reflect a belief that symptoms are emotional rather than medical.","zh":"這個短語可能反映一種信念，即症狀屬情緒問題而非醫學問題。"},{"en":"It may lead people to underestimate illness.","zh":"它可能令人低估疾病。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":4},{"front":"ease off","meaning":"減輕；緩和","examples":[{"en":"Perhaps things will ease off at work soon.","zh":"也許工作上的情況很快會緩和。"},{"en":"To ease off means to become less intense, stressful or severe.","zh":"減輕或緩和是指變得較不強烈、較少壓力或較不嚴重。"},{"en":"Work pressure may ease off after a project ends.","zh":"項目結束後，工作壓力可能會減輕。"},{"en":"A patient may hope symptoms will ease off without medical treatment.","zh":"病人可能希望症狀不用醫療處理也會緩和。"},{"en":"The phrase suggests gradual reduction.","zh":"這個短語暗示逐漸減少。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":4},{"front":"a return visit to","meaning":"再次求診","examples":[{"en":"A return visit to your doctor shocks you.","zh":"再次求診令你震驚。"},{"en":"A return visit to someone means going back to see that person again.","zh":"再次求診是指再次去見某位醫生。"},{"en":"A return visit to the doctor may be needed if symptoms continue.","zh":"如果症狀持續，可能需要再次求診。"},{"en":"During a return visit, the doctor may reconsider the diagnosis.","zh":"在再次求診時，醫生可能重新考慮診斷。"},{"en":"The phrase indicates a second consultation.","zh":"這個短語表示第二次諮詢。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":4},{"front":"draw on years of training and experience","meaning":"憑藉多年訓練和經驗","examples":[{"en":"The doctor draws on years of training and experience.","zh":"醫生憑藉多年訓練和經驗。"},{"en":"To draw on years of training and experience means to use long-developed professional knowledge.","zh":"憑藉多年訓練和經驗是指使用長期培養的專業知識。"},{"en":"A doctor draws on training and experience when interpreting unclear symptoms.","zh":"醫生在詮釋不清楚症狀時會憑藉訓練和經驗。"},{"en":"This knowledge helps distinguish pneumonia from stress or tiredness.","zh":"這種知識有助區分肺炎與壓力或疲倦。"},{"en":"The phrase highlights expert judgement built over time.","zh":"這個短語強調經長時間建立的專家判斷。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":4},{"front":"diagnose pneumonia","meaning":"診斷出肺炎","examples":[{"en":"The doctor diagnoses pneumonia.","zh":"醫生診斷出肺炎。"},{"en":"To diagnose pneumonia means to identify pneumonia as the patient’s illness.","zh":"診斷出肺炎是指確認肺炎是病人的疾病。"},{"en":"A doctor may diagnose pneumonia after listening to the chest and assessing symptoms.","zh":"醫生可能在聽診胸口和評估症狀後診斷出肺炎。"},{"en":"Diagnosing pneumonia transforms vague discomfort into a recognised medical condition.","zh":"診斷出肺炎把模糊不適轉化為被認可的醫學狀況。"},{"en":"The phrase shows the power of expert medical judgement.","zh":"這個短語顯示專業醫學判斷的力量。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":4},{"front":"bed rest","meaning":"臥床休息","examples":[{"en":"You will need bed rest after the diagnosis.","zh":"診斷後你需要臥床休息。"},{"en":"Bed rest means staying in bed to recover from illness.","zh":"臥床休息是指留在床上以從疾病中恢復。"},{"en":"A patient with pneumonia may be advised to take bed rest.","zh":"肺炎病人可能被建議臥床休息。"},{"en":"Bed rest can be part of treatment when the body needs recovery time.","zh":"當身體需要恢復時間時，臥床休息可以是治療的一部分。"},{"en":"The phrase describes a medical recommendation.","zh":"這個短語描述醫學建議。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":4},{"front":"considerable time off work","meaning":"相當長時間不上班","examples":[{"en":"You will need a considerable time off work.","zh":"你需要相當長時間不上班。"},{"en":"Considerable time off work means a fairly long period away from work duties.","zh":"相當長時間不上班是指離開工作職責一段頗長時間。"},{"en":"Serious illness may require considerable time off work.","zh":"嚴重疾病可能需要相當長時間不上班。"},{"en":"A medical certificate may be needed for considerable time off work.","zh":"相當長時間不上班可能需要醫學證明書。"},{"en":"The phrase shows that the illness affects everyday responsibilities.","zh":"這個短語顯示疾病影響日常責任。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":5},{"front":"the scenario is transformed","meaning":"情況完全改變","examples":[{"en":"The scenario is transformed after the diagnosis.","zh":"診斷後情況完全改變。"},{"en":"If a scenario is transformed, the situation changes completely in meaning or understanding.","zh":"如果情況完全改變，表示其意義或理解方式徹底改變。"},{"en":"The diagnosis transformed the scenario from stress to serious illness.","zh":"診斷把情況由壓力轉變為嚴重疾病。"},{"en":"Expert knowledge can transform how patients interpret their symptoms.","zh":"專業知識可以改變病人對症狀的理解。"},{"en":"The phrase shows a major change in perspective.","zh":"這個短語顯示觀點上的重大改變。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":5},{"front":"have the same symptoms","meaning":"有相同症狀","examples":[{"en":"You still have the same symptoms after the diagnosis.","zh":"診斷後你仍有相同症狀。"},{"en":"To have the same symptoms means the bodily signs have not changed.","zh":"有相同症狀是指身體徵象沒有改變。"},{"en":"The cough and tiredness are the same symptoms, but their meaning changes after diagnosis.","zh":"咳嗽和疲倦是相同症狀，但診斷後其意義改變。"},{"en":"Symptoms can remain the same while understanding of them changes.","zh":"症狀可以保持相同，但對它們的理解會改變。"},{"en":"The phrase supports the contrast between experience and interpretation.","zh":"這個短語支持經驗與詮釋之間的對比。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":5},{"front":"be caused by","meaning":"由……引起","examples":[{"en":"You no longer think the symptoms are caused by work pressure.","zh":"你不再認為症狀是由工作壓力引起。"},{"en":"If symptoms are caused by something, that thing produces them.","zh":"如果症狀由某事引起，表示該事造成症狀。"},{"en":"The cough may be caused by pneumonia rather than stress.","zh":"咳嗽可能由肺炎而非壓力引起。"},{"en":"Medical diagnosis helps identify what symptoms are caused by.","zh":"醫學診斷幫助識別症狀由甚麼引起。"},{"en":"The phrase introduces a cause.","zh":"這個短語帶出原因。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":5},{"front":"pressure at work","meaning":"工作壓力","examples":[{"en":"You thought your symptoms were caused by pressure at work.","zh":"你以為自己的症狀由工作壓力引起。"},{"en":"Pressure at work means stress or demands connected with one’s job.","zh":"工作壓力是與工作相關的壓力或要求。"},{"en":"Pressure at work may lead people to explain illness as tiredness or stress.","zh":"工作壓力可能令人把疾病解釋為疲倦或壓力。"},{"en":"The patient first blamed the cough on pressure at work.","zh":"病人起初把咳嗽歸咎於工作壓力。"},{"en":"The phrase shows a common everyday explanation for discomfort.","zh":"這個短語顯示對不適的常見日常解釋。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":5},{"front":"proof that","meaning":"……的證據","examples":[{"en":"You now have proof that you are ill.","zh":"你現在有證據證明自己生病。"},{"en":"Proof that something is true means evidence strong enough to support belief.","zh":"某事為真的證據是足以支持信念的資料。"},{"en":"The doctor’s diagnosis provides proof that the symptoms are serious.","zh":"醫生的診斷提供證據，證明症狀嚴重。"},{"en":"A medical certificate can serve as proof that someone is too ill to work.","zh":"醫學證明書可以作為某人病得不能上班的證據。"},{"en":"The phrase connects evidence with certainty.","zh":"這個短語把證據與確定性連接起來。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":5},{"front":"the result of","meaning":"……的結果","examples":[{"en":"Your knowledge is the result of personal experience and expert diagnosis.","zh":"你的知識是個人經驗和專家診斷的結果。"},{"en":"The result of something is the outcome produced by it.","zh":"某事的結果是由它產生的後果。"},{"en":"The diagnosis is the result of examination, training and evidence.","zh":"診斷是檢查、訓練和證據的結果。"},{"en":"Medical knowledge may be the result of combining different sources.","zh":"醫學知識可能是結合不同來源的結果。"},{"en":"The phrase identifies how something comes about.","zh":"這個短語指出某事如何產生。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":5},{"front":"a combination of","meaning":"……的結合","examples":[{"en":"The diagnosis is based on a combination of experience and medical expertise.","zh":"診斷建基於經驗和醫學專業知識的結合。"},{"en":"A combination of things means two or more elements working together.","zh":"某些事物的結合是指兩個或更多元素共同作用。"},{"en":"Medical judgement may rely on a combination of symptoms, tests and experience.","zh":"醫學判斷可能依賴症狀、檢查和經驗的結合。"},{"en":"A combination of personal and expert knowledge can confirm illness.","zh":"個人知識和專家知識的結合可以確認疾病。"},{"en":"The phrase shows that several sources are involved.","zh":"這個短語顯示涉及多個來源。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":5},{"front":"subjective experience","meaning":"主觀經驗","examples":[{"en":"Your own subjective experience is one source of knowledge.","zh":"你自己的主觀經驗是一個知識來源。"},{"en":"Subjective experience is personal experience based on how something feels to an individual.","zh":"主觀經驗是基於個人如何感受某事的個人經驗。"},{"en":"Pain and tiredness are part of a patient’s subjective experience.","zh":"疼痛和疲倦是病人主觀經驗的一部分。"},{"en":"Subjective experience is important, but it may need medical interpretation.","zh":"主觀經驗很重要，但可能需要醫學詮釋。"},{"en":"The phrase contrasts personal feeling with external measurement.","zh":"這個短語把個人感受與外部量度作對比。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":5},{"front":"medical expert","meaning":"醫學專家","examples":[{"en":"The doctor has the status of a medical expert.","zh":"醫生具有醫學專家的身份。"},{"en":"A medical expert is a person with specialised training and authority in medicine.","zh":"醫學專家是具備醫學專門訓練和權威的人。"},{"en":"A medical expert can interpret symptoms using professional knowledge.","zh":"醫學專家可以運用專業知識詮釋症狀。"},{"en":"Patients often rely on a medical expert for diagnosis and treatment.","zh":"病人常依賴醫學專家進行診斷和治療。"},{"en":"The phrase emphasises professional authority.","zh":"這個短語強調專業權威。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":5},{"front":"have the status of","meaning":"具有……身份","examples":[{"en":"The doctor has the status of a medical expert.","zh":"醫生具有醫學專家的身份。"},{"en":"To have the status of something means to be recognised as having that role or authority.","zh":"具有某種身份是指被承認擁有該角色或權威。"},{"en":"A qualified doctor has the status of an authorised medical practitioner.","zh":"合資格醫生具有獲授權醫療從業員的身份。"},{"en":"Medical certificates have the status of official evidence in many workplaces.","zh":"醫學證明書在許多工作場所具有正式證據的地位。"},{"en":"The phrase describes social or professional recognition.","zh":"這個短語描述社會或專業認可。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":5},{"front":"medically authenticated diagnosis","meaning":"經醫學確認的診斷","examples":[{"en":"You have a medically authenticated diagnosis.","zh":"你有一個經醫學確認的診斷。"},{"en":"A medically authenticated diagnosis is a diagnosis confirmed by recognised medical authority.","zh":"經醫學確認的診斷是由被認可的醫學權威確認的診斷。"},{"en":"A patient may need a medically authenticated diagnosis to justify sick leave.","zh":"病人可能需要經醫學確認的診斷來證明病假合理。"},{"en":"Such a diagnosis carries more authority than personal suspicion.","zh":"這類診斷比個人懷疑更具權威。"},{"en":"The phrase shows that illness has been officially confirmed in medical terms.","zh":"這個短語顯示疾病已在醫學上正式確認。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":6},{"front":"appear that","meaning":"看來","examples":[{"en":"It appears that you are seriously ill.","zh":"看來你病得嚴重。"},{"en":"“Appear that” means it seems or looks as if something is true.","zh":"「看來」表示某事似乎是真實的。"},{"en":"It appears that the cough is not simply caused by stress.","zh":"看來咳嗽並非單純由壓力造成。"},{"en":"The phrase presents a conclusion based on evidence.","zh":"這個短語呈現基於證據的結論。"},{"en":"It can sound less absolute than “it is certain that.”","zh":"它的語氣可以比「確定」較不絕對。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":6},{"front":"seriously ill","meaning":"病得嚴重","examples":[{"en":"The diagnosis shows that you are seriously ill.","zh":"診斷顯示你病得嚴重。"},{"en":"Seriously ill means having a significant or severe medical condition.","zh":"病得嚴重表示患有重要或嚴重的醫學狀況。"},{"en":"A seriously ill patient may need rest, treatment and time away from work.","zh":"病得嚴重的病人可能需要休息、治療和請假。"},{"en":"Pneumonia can make a person seriously ill.","zh":"肺炎可以令人病得嚴重。"},{"en":"The phrase indicates more than minor discomfort.","zh":"這個短語表示不只是輕微不適。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":6},{"front":"evidence upon which to base","meaning":"作為……根據的證據","examples":[{"en":"You have evidence upon which to base your knowledge.","zh":"你有作為知識根據的證據。"},{"en":"Evidence upon which to base a claim is information used to support it.","zh":"作為某項說法根據的證據，是用來支持該說法的資料。"},{"en":"Symptoms and diagnosis provide evidence upon which to base the belief that you are ill.","zh":"症狀和診斷提供證據，作為相信自己生病的根據。"},{"en":"Good medical decisions need evidence upon which to base judgement.","zh":"良好的醫療決定需要作為判斷根據的證據。"},{"en":"The phrase is formal and emphasises support for knowledge.","zh":"這個短語較正式，強調知識的支持基礎。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":6},{"front":"base this knowledge","meaning":"以此作為知識根據","examples":[{"en":"You base this knowledge on symptoms and expert diagnosis.","zh":"你把症狀和專家診斷作為這項知識的根據。"},{"en":"To base knowledge on something means to support it with that evidence or source.","zh":"以某事作為知識根據，是指用該證據或來源支持知識。"},{"en":"The patient bases this knowledge on bodily experience and medical confirmation.","zh":"病人以身體經驗和醫學確認作為這項知識的根據。"},{"en":"Doctors base medical knowledge on training, observation and research.","zh":"醫生以訓練、觀察和研究作為醫學知識的根據。"},{"en":"The phrase explains the foundation of a belief.","zh":"這個短語解釋信念的基礎。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":6},{"front":"sources of knowledge","meaning":"知識來源","examples":[{"en":"The scenario shows many different sources of knowledge.","zh":"這個情境顯示許多不同知識來源。"},{"en":"Sources of knowledge are places, people or experiences from which knowledge comes.","zh":"知識來源是知識來自的地方、人物或經驗。"},{"en":"Symptoms, friends, doctors and textbooks can all be sources of knowledge.","zh":"症狀、朋友、醫生和教科書都可以是知識來源。"},{"en":"Different sources of knowledge may have different authority.","zh":"不同知識來源可能具有不同權威。"},{"en":"The phrase helps organise how people decide whether they are ill.","zh":"這個短語有助整理人們如何判斷自己是否生病。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":6},{"front":"decide to consult","meaning":"決定諮詢","examples":[{"en":"You decide to consult the doctor because you feel unwell.","zh":"你因感到不適而決定諮詢醫生。"},{"en":"To decide to consult someone means to choose to seek their advice.","zh":"決定諮詢某人是指選擇尋求該人的意見。"},{"en":"A patient may decide to consult a doctor when symptoms continue.","zh":"當症狀持續時，病人可能決定諮詢醫生。"},{"en":"Consulting a doctor brings expert knowledge into the situation.","zh":"諮詢醫生把專家知識帶入情境。"},{"en":"The phrase marks a choice to seek professional help.","zh":"這個短語標示尋求專業幫助的選擇。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":6},{"front":"in the first place","meaning":"起初；首先","examples":[{"en":"You consult the doctor in the first place because you feel unwell.","zh":"你起初因感到不適而諮詢醫生。"},{"en":"“In the first place” means originally or at the beginning.","zh":"「起初」表示原本或在一開始。"},{"en":"In the first place, the patient thought the problem was stress.","zh":"起初，病人以為問題是壓力。"},{"en":"The phrase explains the initial reason for an action.","zh":"這個短語解釋行動的最初原因。"},{"en":"It can also be used to organise the first point in an argument.","zh":"它也可用來組織論點中的第一點。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":6},{"front":"personal knowledge","meaning":"個人知識；個人認知","examples":[{"en":"Your feelings provide personal knowledge about your own body.","zh":"你的感受提供關於自己身體的個人知識。"},{"en":"Personal knowledge is knowledge based on one’s own experience or awareness.","zh":"個人知識是基於個人經驗或意識的知識。"},{"en":"A patient has personal knowledge of pain, tiredness and discomfort.","zh":"病人對疼痛、疲倦和不適具有個人認知。"},{"en":"Personal knowledge can prompt someone to seek medical advice.","zh":"個人知識可以促使某人尋求醫療意見。"},{"en":"The phrase contrasts private experience with expert knowledge.","zh":"這個短語把私人經驗與專家知識作對比。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":6},{"front":"expert diagnosis","meaning":"專家診斷","examples":[{"en":"The doctor’s expert diagnosis is based on training and experience.","zh":"醫生的專家診斷基於訓練和經驗。"},{"en":"Expert diagnosis is a medical judgement made by someone with professional knowledge.","zh":"專家診斷是由具專業知識的人作出的醫學判斷。"},{"en":"Expert diagnosis can confirm that symptoms indicate pneumonia.","zh":"專家診斷可以確認症狀顯示肺炎。"},{"en":"A patient’s personal belief may change after expert diagnosis.","zh":"病人的個人信念可能在專家診斷後改變。"},{"en":"The phrase highlights the authority of trained medical judgement.","zh":"這個短語強調受訓醫學判斷的權威。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":6},{"front":"be based on experience and training","meaning":"基於經驗和訓練","examples":[{"en":"The doctor’s diagnosis is based on experience and training.","zh":"醫生的診斷基於經驗和訓練。"},{"en":"If a judgement is based on experience and training, it relies on practice and education.","zh":"如果判斷基於經驗和訓練，表示它依賴實踐和教育。"},{"en":"Medical interpretation is often based on experience and training.","zh":"醫學詮釋通常基於經驗和訓練。"},{"en":"A doctor can recognise patterns because her knowledge is based on experience and training.","zh":"醫生能辨認模式，因為其知識基於經驗和訓練。"},{"en":"The phrase explains why expert judgement is trusted.","zh":"這個短語解釋專家判斷為何受到信任。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":6},{"front":"as diverse as","meaning":"如……般多樣化","examples":[{"en":"The doctor draws on sources as diverse as textbooks and laboratory reports.","zh":"醫生借助如教科書和化驗報告般多樣化的來源。"},{"en":"“As diverse as” means including very different kinds of things.","zh":"「如……般多樣化」表示包括非常不同種類的事物。"},{"en":"Medical knowledge can come from sources as diverse as patient stories and scientific tests.","zh":"醫學知識可以來自如病人敘述和科學檢查般多樣化的來源。"},{"en":"The phrase highlights variety within a group of sources.","zh":"這個短語強調來源群組中的多樣性。"},{"en":"It suggests that expert knowledge is built from many materials.","zh":"它暗示專家知識由許多材料建立而成。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":7},{"front":"laboratory reports","meaning":"化驗報告","examples":[{"en":"Laboratory reports may support a medical diagnosis.","zh":"化驗報告可能支持醫學診斷。"},{"en":"Laboratory reports are written results from scientific tests on samples.","zh":"化驗報告是對樣本進行科學測試後的書面結果。"},{"en":"Blood tests and tissue samples can produce laboratory reports.","zh":"血液測試和組織樣本可以產生化驗報告。"},{"en":"Doctors use laboratory reports to confirm or question a diagnosis.","zh":"醫生使用化驗報告來確認或質疑診斷。"},{"en":"The phrase represents scientific evidence in medical practice.","zh":"這個短語代表醫療實踐中的科學證據。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":7},{"front":"medical textbooks","meaning":"醫學教科書","examples":[{"en":"Medical textbooks are one source of doctors’ knowledge.","zh":"醫學教科書是醫生知識的一個來源。"},{"en":"Medical textbooks contain organised knowledge about diseases, symptoms and treatments.","zh":"醫學教科書包含關於疾病、症狀和治療的有系統知識。"},{"en":"Doctors study medical textbooks during training.","zh":"醫生在訓練期間學習醫學教科書。"},{"en":"Textbooks help standardise medical knowledge across practitioners.","zh":"教科書幫助醫療從業員之間標準化醫學知識。"},{"en":"The phrase represents formal written medical knowledge.","zh":"這個短語代表正式書面醫學知識。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":7},{"front":"years of experience","meaning":"多年經驗","examples":[{"en":"Doctors rely on training and years of experience.","zh":"醫生依賴訓練和多年經驗。"},{"en":"Years of experience means long practical involvement in a field.","zh":"多年經驗是指長期在某領域中的實際參與。"},{"en":"A doctor with years of experience may recognise subtle symptoms quickly.","zh":"具多年經驗的醫生可能很快辨認細微症狀。"},{"en":"Experience can help experts interpret evidence in context.","zh":"經驗可以幫助專家在情境中詮釋證據。"},{"en":"The phrase highlights knowledge gained over time.","zh":"這個短語強調隨時間獲得的知識。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":7},{"front":"experience of our own bodies","meaning":"對自己身體的經驗","examples":[{"en":"One source of knowledge is our experience of our own bodies.","zh":"一個知識來源是我們對自己身體的經驗。"},{"en":"Experience of our own bodies means what we feel, notice and understand physically.","zh":"對自己身體的經驗是指我們在身體上感到、注意和理解的東西。"},{"en":"Pain, tiredness and breathing difficulty are part of experience of our own bodies.","zh":"疼痛、疲倦和呼吸困難都是對自己身體經驗的一部分。"},{"en":"This experience can tell us that something may be wrong.","zh":"這種經驗可以告訴我們可能有問題。"},{"en":"The phrase emphasises first-person bodily knowledge.","zh":"這個短語強調第一身身體知識。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":7},{"front":"changes that might be significant","meaning":"可能重要的變化","examples":[{"en":"People notice changes that might be significant.","zh":"人們會注意到可能重要的變化。"},{"en":"Changes that might be significant are differences that may indicate something important.","zh":"可能重要的變化是可能顯示重要事情的差異。"},{"en":"A persistent cough may be one of the changes that might be significant.","zh":"持續咳嗽可能是可能重要的變化之一。"},{"en":"Patients often report changes that might be significant to doctors.","zh":"病人常向醫生報告可能重要的變化。"},{"en":"The phrase suggests uncertainty before interpretation.","zh":"這個短語暗示在詮釋前仍有不確定性。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":7},{"front":"be mediated by","meaning":"受……中介；受……影響","examples":[{"en":"Subjective experience is mediated by other forms of knowledge.","zh":"主觀經驗受其他形式的知識中介或影響。"},{"en":"If experience is mediated by something, it is shaped or filtered by it.","zh":"如果經驗受某事中介，表示它被該事塑造或過濾。"},{"en":"Our understanding of symptoms may be mediated by culture and language.","zh":"我們對症狀的理解可能受文化和語言影響。"},{"en":"Personal feelings are mediated by words, common sense and social ideas.","zh":"個人感受受詞語、常識和社會觀念中介。"},{"en":"The phrase shows that experience is not completely raw or isolated.","zh":"這個短語顯示經驗並非完全原始或孤立。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":7},{"front":"other forms of knowledge","meaning":"其他形式的知識","examples":[{"en":"Subjective experience is shaped by other forms of knowledge.","zh":"主觀經驗受其他形式的知識塑造。"},{"en":"Other forms of knowledge include language, common sense, culture and expert advice.","zh":"其他形式的知識包括語言、常識、文化和專家意見。"},{"en":"A person’s feeling of illness may be interpreted through other forms of knowledge.","zh":"一個人的疾病感受可能透過其他形式的知識被詮釋。"},{"en":"These forms influence how people describe and understand symptoms.","zh":"這些形式影響人們如何描述和理解症狀。"},{"en":"The phrase shows that knowledge sources interact.","zh":"這個短語顯示知識來源互相作用。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":7},{"front":"words we have available","meaning":"我們可用的詞語","examples":[{"en":"Our experience depends partly on the words we have available.","zh":"我們的經驗部分取決於我們可用的詞語。"},{"en":"Words we have available are the terms we can use to describe experience.","zh":"我們可用的詞語是可用來描述經驗的詞彙。"},{"en":"If we lack the right words, we may struggle to explain symptoms.","zh":"如果缺乏合適詞語，我們可能難以解釋症狀。"},{"en":"Medical and everyday vocabulary shape how illness is described.","zh":"醫學和日常詞彙塑造疾病如何被描述。"},{"en":"The phrase links language with knowledge.","zh":"這個短語把語言與知識連接起來。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":7},{"front":"describe our experience","meaning":"描述我們的經驗","examples":[{"en":"Words help us describe our experience of illness.","zh":"詞語幫助我們描述疾病經驗。"},{"en":"To describe our experience means to put personal feelings into words.","zh":"描述我們的經驗是指把個人感受化為語言。"},{"en":"Patients describe their experience so doctors can understand symptoms.","zh":"病人描述自己的經驗，以便醫生了解症狀。"},{"en":"Better vocabulary can help people describe illness more accurately.","zh":"更好的詞彙可以幫助人們更準確描述疾病。"},{"en":"The phrase connects personal feeling with communication.","zh":"這個短語把個人感受與溝通連接起來。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":7},{"front":"common sense","meaning":"常識","examples":[{"en":"Common sense can influence how we understand illness.","zh":"常識可以影響我們如何理解疾病。"},{"en":"Common sense is everyday practical understanding shared by many people.","zh":"常識是許多人共享的日常實用理解。"},{"en":"Common sense may suggest that tiredness comes from overwork.","zh":"常識可能認為疲倦來自過勞。"},{"en":"Medical diagnosis can challenge common sense explanations.","zh":"醫學診斷可以挑戰常識解釋。"},{"en":"The phrase refers to non-specialist everyday knowledge.","zh":"這個短語指非專業的日常知識。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":7},{"front":"families and friends","meaning":"家人和朋友","examples":[{"en":"The common sense of families and friends may shape our understanding.","zh":"家人和朋友的常識可能塑造我們的理解。"},{"en":"Families and friends are people close to us who may observe our behaviour and health.","zh":"家人和朋友是與我們親近、可能觀察我們行為和健康的人。"},{"en":"Families and friends may say that we look ill.","zh":"家人和朋友可能說我們看起來病了。"},{"en":"Their comments can influence whether we seek medical help.","zh":"他們的評語可以影響我們是否尋求醫療幫助。"},{"en":"The phrase identifies informal social sources of knowledge.","zh":"這個短語指出非正式的社會知識來源。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":8},{"front":"be drawn from","meaning":"來自；取自","examples":[{"en":"Some health ideas are drawn from popular culture.","zh":"一些健康觀念來自大眾文化。"},{"en":"To be drawn from something means to come from or be taken from it.","zh":"來自某事是指由它產生或取自它。"},{"en":"Ideas about stress may be drawn from media discussions.","zh":"關於壓力的觀念可能來自媒體討論。"},{"en":"Personal explanations of illness can be drawn from family beliefs.","zh":"對疾病的個人解釋可以來自家庭信念。"},{"en":"The phrase identifies the origin of an idea.","zh":"這個短語指出觀念的來源。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":8},{"front":"popular culture","meaning":"大眾文化","examples":[{"en":"Popular culture influences how people explain their symptoms.","zh":"大眾文化影響人們如何解釋自己的症狀。"},{"en":"Popular culture includes media, entertainment and everyday shared ideas.","zh":"大眾文化包括傳媒、娛樂和日常共享觀念。"},{"en":"Popular culture may make “stress” a common explanation for discomfort.","zh":"大眾文化可能令「壓力」成為解釋不適的常見說法。"},{"en":"Health ideas in popular culture can shape personal judgement.","zh":"大眾文化中的健康觀念可以塑造個人判斷。"},{"en":"The phrase refers to widely shared cultural messages.","zh":"這個短語指廣泛共享的文化訊息。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":8},{"front":"over the past decade","meaning":"在過去十年","examples":[{"en":"Over the past decade, Western culture has emphasised stress-related illness.","zh":"在過去十年，西方文化強調與壓力有關的疾病。"},{"en":"Over the past decade means during the last ten years.","zh":"在過去十年表示在最近十年期間。"},{"en":"Over the past decade, stress has become a common topic in workplaces.","zh":"在過去十年，壓力已成為工作場所常見話題。"},{"en":"Cultural explanations can change over the past decade.","zh":"文化解釋可以在過去十年改變。"},{"en":"The phrase gives a recent time frame.","zh":"這個短語提供近期時間框架。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":8},{"front":"Western culture","meaning":"西方文化","examples":[{"en":"Western culture has placed emphasis on stress-related illness.","zh":"西方文化重視與壓力有關的疾病。"},{"en":"Western culture refers broadly to social ideas and practices common in Western societies.","zh":"西方文化廣泛指西方社會常見的社會觀念和做法。"},{"en":"Western culture often discusses stress in relation to work and health.","zh":"西方文化常把壓力與工作和健康連繫起來討論。"},{"en":"The passage uses Western culture to explain common illness interpretations.","zh":"文章使用西方文化來解釋常見疾病詮釋。"},{"en":"The phrase provides a cultural context for knowledge.","zh":"這個短語提供知識的文化背景。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":8},{"front":"a significant emphasis on","meaning":"對……的顯著重視","examples":[{"en":"The media has placed a significant emphasis on stress-related illness.","zh":"傳媒對與壓力有關的疾病給予顯著重視。"},{"en":"A significant emphasis on something means strong attention or importance given to it.","zh":"對某事的顯著重視表示給予它強烈關注或重要性。"},{"en":"Newspapers have placed a significant emphasis on workplace stress.","zh":"報章對工作壓力給予顯著重視。"},{"en":"Such emphasis can shape how people interpret physical symptoms.","zh":"這種重視可以塑造人們如何詮釋身體症狀。"},{"en":"The phrase highlights cultural focus.","zh":"這個短語強調文化焦點。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":8},{"front":"stress-related illness","meaning":"與壓力有關的疾病","examples":[{"en":"Stress-related illness is often discussed in Western media.","zh":"與壓力有關的疾病常在西方傳媒中被討論。"},{"en":"Stress-related illness is illness or discomfort understood as connected to stress.","zh":"與壓力有關的疾病是被理解為與壓力有關的疾病或不適。"},{"en":"People may explain tiredness and pain as stress-related illness.","zh":"人們可能把疲倦和疼痛解釋為與壓力有關的疾病。"},{"en":"The idea of stress-related illness has become part of popular common sense.","zh":"與壓力有關的疾病這個觀念已成為大眾常識的一部分。"},{"en":"The phrase links mental pressure with bodily symptoms.","zh":"這個短語把精神壓力與身體症狀連接起來。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":8},{"front":"in the media","meaning":"在傳媒中","examples":[{"en":"Stress-related illness has received attention in the media.","zh":"與壓力有關的疾病在傳媒中受到關注。"},{"en":"In the media means in newspapers, television, radio, websites or other public communication channels.","zh":"在傳媒中表示在報章、電視、電台、網站或其他公共傳播渠道中。"},{"en":"Health stories in the media can influence public understanding.","zh":"傳媒中的健康故事可以影響公眾理解。"},{"en":"Stress is often discussed in the media as a cause of discomfort.","zh":"壓力常在傳媒中被討論為不適的原因。"},{"en":"The phrase identifies a public source of cultural knowledge.","zh":"這個短語指出文化知識的公共來源。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":8},{"front":"reference to","meaning":"提及……","examples":[{"en":"Reference to being stressed out has become common at work.","zh":"提及壓力爆煲在工作中已變得常見。"},{"en":"Reference to something means mentioning or alluding to it.","zh":"提及某事是指提到或暗示它。"},{"en":"The patient made reference to stress when explaining tiredness.","zh":"病人在解釋疲倦時提及壓力。"},{"en":"Frequent reference to stress can make it seem like a natural explanation.","zh":"頻繁提及壓力可以令它看似自然解釋。"},{"en":"The phrase describes the act of mentioning an idea.","zh":"這個短語描述提到某個觀念的行為。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":8},{"front":"stressed out","meaning":"壓力很大；壓力爆煲","examples":[{"en":"People often say they are stressed out in daily workplace exchanges.","zh":"人們在工作場所日常交流中常說自己壓力很大。"},{"en":"Stressed out means feeling very tense, pressured or emotionally overloaded.","zh":"壓力很大是指感到非常緊張、有壓力或情緒負荷過重。"},{"en":"Someone who is stressed out may also feel tired or physically uncomfortable.","zh":"壓力爆煲的人也可能感到疲倦或身體不適。"},{"en":"The phrase is common in everyday speech about work pressure.","zh":"這個短語在談論工作壓力的日常語言中很常見。"},{"en":"It can become a popular explanation for illness-like symptoms.","zh":"它可以成為解釋類似疾病症狀的流行說法。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":8},{"front":"a common response","meaning":"常見回應","examples":[{"en":"Saying one is stressed out has become a common response.","zh":"說自己壓力很大已成為常見回應。"},{"en":"A common response is an answer or reaction that many people often give.","zh":"常見回應是許多人經常給出的回答或反應。"},{"en":"Saying “I’m stressed” is a common response to feeling tired at work.","zh":"在工作中感到疲倦時，說「我壓力很大」是常見回應。"},{"en":"Common responses can reflect shared cultural ideas.","zh":"常見回應可以反映共享文化觀念。"},{"en":"The phrase points to repeated everyday behaviour.","zh":"這個短語指重複出現的日常行為。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":8},{"front":"daily exchanges","meaning":"日常交流","examples":[{"en":"The phrase is common in daily exchanges in the workplace.","zh":"這個短語在工作場所日常交流中很常見。"},{"en":"Daily exchanges are ordinary everyday conversations or interactions.","zh":"日常交流是普通每天的對話或互動。"},{"en":"Daily exchanges between colleagues often include comments about stress.","zh":"同事之間的日常交流常包括關於壓力的評語。"},{"en":"Such exchanges spread common-sense ideas about illness.","zh":"這些交流會傳播關於疾病的常識觀念。"},{"en":"The phrase refers to routine communication.","zh":"這個短語指例行溝通。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":9},{"front":"in the workplace","meaning":"在工作場所","examples":[{"en":"Stress is often mentioned in the workplace.","zh":"壓力常在工作場所被提及。"},{"en":"In the workplace means in the place where people do their jobs.","zh":"在工作場所表示在人們工作的地方。"},{"en":"Health and tiredness may be discussed in the workplace.","zh":"健康和疲倦可能在工作場所被討論。"},{"en":"Workplace culture can shape how people explain illness.","zh":"工作場所文化可以塑造人們如何解釋疾病。"},{"en":"The phrase identifies a social setting.","zh":"這個短語指出一個社會情境。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":9},{"front":"part of popular common-sense knowledge","meaning":"大眾常識的一部分","examples":[{"en":"Stress has become part of popular common-sense knowledge.","zh":"壓力已成為大眾常識的一部分。"},{"en":"Part of popular common-sense knowledge means widely accepted as everyday understanding.","zh":"大眾常識的一部分表示被廣泛接受為日常理解。"},{"en":"The idea that work stress causes illness has become part of common-sense knowledge.","zh":"工作壓力造成疾病這個想法已成為常識的一部分。"},{"en":"Such knowledge may influence people before they seek medical advice.","zh":"這類知識可能在人們尋求醫療意見前已影響他們。"},{"en":"The phrase describes socially shared non-expert knowledge.","zh":"這個短語描述社會共享的非專業知識。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":9},{"front":"it is thus not surprising that","meaning":"因此並不令人意外","examples":[{"en":"It is thus not surprising that people explain symptoms as stress.","zh":"因此，人們把症狀解釋為壓力並不令人意外。"},{"en":"“It is thus not surprising that” means the result is expected because of the reasons already given.","zh":"「因此並不令人意外」表示基於前述原因，結果是可預期的。"},{"en":"Stress is often discussed, so it is not surprising that people use it as an explanation.","zh":"壓力常被討論，因此人們用它作解釋並不奇怪。"},{"en":"The phrase connects cultural context with personal interpretation.","zh":"這個短語把文化背景與個人詮釋連接起來。"},{"en":"It introduces a logical consequence.","zh":"它帶出邏輯後果。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":9},{"front":"seek such an explanation","meaning":"尋求這種解釋","examples":[{"en":"People may seek such an explanation for physical discomfort.","zh":"人們可能為身體不適尋求這種解釋。"},{"en":"To seek such an explanation means to look for that kind of reason or cause.","zh":"尋求這種解釋是指尋找那類原因或說法。"},{"en":"A person may seek a stress explanation before considering disease.","zh":"一個人在考慮疾病前可能尋求壓力解釋。"},{"en":"People often seek explanations that fit familiar cultural ideas.","zh":"人們常尋求符合熟悉文化觀念的解釋。"},{"en":"The phrase describes active interpretation of symptoms.","zh":"這個短語描述對症狀的主動詮釋。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":9},{"front":"physical symptoms of discomfort","meaning":"身體不適症狀","examples":[{"en":"People may explain physical symptoms of discomfort as stress.","zh":"人們可能把身體不適症狀解釋為壓力。"},{"en":"Physical symptoms of discomfort are bodily signs such as pain, tiredness or coughing.","zh":"身體不適症狀是疼痛、疲倦或咳嗽等身體徵象。"},{"en":"Physical symptoms of discomfort can have medical or non-medical explanations.","zh":"身體不適症狀可以有醫學或非醫學解釋。"},{"en":"A patient may first interpret discomfort through everyday knowledge.","zh":"病人可能先透過日常知識詮釋不適。"},{"en":"The phrase refers to bodily signs that feel unpleasant.","zh":"這個短語指令人不愉快的身體徵象。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":9},{"front":"rely on the observations of others","meaning":"依賴他人的觀察","examples":[{"en":"We might rely on the observations of others who know us.","zh":"我們可能依賴認識我們的人所作的觀察。"},{"en":"To rely on the observations of others means to use other people’s comments or noticing as evidence.","zh":"依賴他人的觀察是指把別人的評語或注意到的事情作為證據。"},{"en":"A friend may notice that you look pale before you do.","zh":"朋友可能比你更早注意到你面色蒼白。"},{"en":"Others’ observations can influence whether we think we are ill.","zh":"他人的觀察可以影響我們是否認為自己生病。"},{"en":"The phrase identifies social observation as a knowledge source.","zh":"這個短語把社會觀察視為知識來源。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":9},{"front":"observations of others","meaning":"他人的觀察","examples":[{"en":"The observations of others can be another source of knowledge.","zh":"他人的觀察可以是另一個知識來源。"},{"en":"Observations of others are what other people notice about us.","zh":"他人的觀察是別人注意到我們身上的事情。"},{"en":"Family members’ observations may reveal changes in mood or appearance.","zh":"家人的觀察可能揭示情緒或外表變化。"},{"en":"Such observations can complement personal experience.","zh":"這些觀察可以補充個人經驗。"},{"en":"The phrase shows that knowledge is sometimes social.","zh":"這個短語顯示知識有時是社會性的。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":9},{"front":"comments from friends and family","meaning":"朋友和家人的評語","examples":[{"en":"Comments from friends and family may influence our judgement.","zh":"朋友和家人的評語可能影響我們的判斷。"},{"en":"Comments from friends and family are remarks made by people close to us.","zh":"朋友和家人的評語是親近的人所作的評論。"},{"en":"A comment that you look ill may encourage you to see a doctor.","zh":"一句你看起來病了的評語可能鼓勵你看醫生。"},{"en":"These comments can shape how seriously we take symptoms.","zh":"這些評語可以塑造我們如何看待症狀的嚴重性。"},{"en":"The phrase refers to informal everyday feedback.","zh":"這個短語指非正式的日常反饋。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":9},{"front":"look ill","meaning":"看起來病了","examples":[{"en":"A friend may say that you look ill.","zh":"朋友可能說你看起來病了。"},{"en":"To look ill means to appear sick or unhealthy to others.","zh":"看起來病了是指在別人眼中顯得生病或不健康。"},{"en":"Someone who looks ill may be pale, tired or weak.","zh":"看起來病了的人可能面色蒼白、疲倦或虛弱。"},{"en":"Looking ill can become evidence in another person’s judgement.","zh":"看起來病了可以成為別人判斷中的證據。"},{"en":"The phrase describes appearance rather than confirmed diagnosis.","zh":"這個短語描述外表，而不是已確認診斷。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":9},{"front":"another source of knowledge","meaning":"另一個知識來源","examples":[{"en":"Comments from people around us can be another source of knowledge.","zh":"身邊人的評語可以是另一個知識來源。"},{"en":"Another source of knowledge is an additional way we gain understanding.","zh":"另一個知識來源是我們獲得理解的額外方式。"},{"en":"Friends’ observations may be another source of knowledge about illness.","zh":"朋友的觀察可能是關於疾病的另一個知識來源。"},{"en":"Doctors’ tests are another source of knowledge beyond personal feeling.","zh":"醫生的檢查是超越個人感受的另一個知識來源。"},{"en":"The phrase adds one more category to the discussion.","zh":"這個短語為討論加入另一個類別。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":9},{"front":"complementary health practices","meaning":"輔助醫療做法","examples":[{"en":"Complementary health practices produce their own forms of knowledge.","zh":"輔助醫療做法產生其自身形式的知識。"},{"en":"Complementary health practices are health approaches used alongside or outside conventional medicine.","zh":"輔助醫療做法是與常規醫學並行或在其以外使用的健康方法。"},{"en":"Acupuncture, herbal therapy and massage may be considered complementary health practices.","zh":"針灸、草藥療法和按摩可被視為輔助醫療做法。"},{"en":"Such practices may offer different explanations of illness and treatment.","zh":"這些做法可能提供不同的疾病和治療解釋。"},{"en":"The phrase introduces non-mainstream medical knowledge sources.","zh":"這個短語帶出非主流醫學知識來源。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":10},{"front":"holistic medicine","meaning":"整全醫學","examples":[{"en":"Holistic medicine offers another way to understand illness.","zh":"整全醫學提供另一種理解疾病的方式。"},{"en":"Holistic medicine considers the whole person, including body, mind and lifestyle.","zh":"整全醫學考慮整個人，包括身體、思想和生活方式。"},{"en":"A holistic approach may ask about stress, diet, sleep and emotions.","zh":"整全方法可能詢問壓力、飲食、睡眠和情緒。"},{"en":"Holistic medicine may produce knowledge different from conventional diagnosis.","zh":"整全醫學可能產生不同於常規診斷的知識。"},{"en":"The phrase highlights a broader view of health.","zh":"這個短語強調較廣闊的健康觀。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":10},{"front":"produce their own sets of knowledge","meaning":"產生其自身的一套知識","examples":[{"en":"Complementary health practices produce their own sets of knowledge.","zh":"輔助醫療做法產生其自身的一套知識。"},{"en":"To produce their own sets of knowledge means to create distinct ideas, explanations and methods.","zh":"產生其自身的一套知識是指創造獨特的觀念、解釋和方法。"},{"en":"Holistic medicine may produce its own knowledge about balance and wellbeing.","zh":"整全醫學可能產生關於平衡和健康的自身知識。"},{"en":"Different health systems can produce different knowledge about the same symptoms.","zh":"不同健康系統可以對相同症狀產生不同知識。"},{"en":"The phrase shows that medical knowledge is not singular.","zh":"這個短語顯示醫學知識並非單一。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":10},{"front":"draw on","meaning":"借助；利用","examples":[{"en":"People may draw on different kinds of knowledge when deciding about health.","zh":"人們在判斷健康時可能借助不同種類的知識。"},{"en":"To draw on something means to use it as a resource.","zh":"借助某物是指把它作為資源使用。"},{"en":"Patients draw on personal experience when describing symptoms.","zh":"病人在描述症狀時借助個人經驗。"},{"en":"Doctors draw on training, textbooks and experience.","zh":"醫生利用訓練、教科書和經驗。"},{"en":"The phrase shows knowledge being used actively.","zh":"這個短語顯示知識被主動使用。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":10},{"front":"the nature and degree of","meaning":"……的性質和程度","examples":[{"en":"People decide the nature and degree of their ill health.","zh":"人們判斷自己健康欠佳的性質和程度。"},{"en":"The nature and degree of something means what kind it is and how serious or strong it is.","zh":"某事的性質和程度是指它是甚麼種類，以及有多嚴重或強烈。"},{"en":"A doctor assesses the nature and degree of a patient’s illness.","zh":"醫生評估病人疾病的性質和程度。"},{"en":"Symptoms help indicate both the nature and degree of ill health.","zh":"症狀有助顯示健康欠佳的性質和程度。"},{"en":"The phrase combines type and severity.","zh":"這個短語結合類型和嚴重程度。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":10},{"front":"ill health","meaning":"健康欠佳；疾病狀態","examples":[{"en":"People use different knowledge sources to understand ill health.","zh":"人們使用不同知識來源來理解健康欠佳。"},{"en":"Ill health means poor health or a state of being unwell.","zh":"健康欠佳是指健康不良或身體不適的狀態。"},{"en":"Ill health may be temporary, long-term, mild or severe.","zh":"健康欠佳可以是暫時、長期、輕微或嚴重的。"},{"en":"Personal feelings and medical diagnosis can both inform our understanding of ill health.","zh":"個人感受和醫學診斷都可以幫助我們理解疾病狀態。"},{"en":"The phrase is broader than a single named disease.","zh":"這個短語比單一具名疾病更廣泛。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":10},{"front":"possible treatments","meaning":"可能的治療方法","examples":[{"en":"Different knowledge sources may suggest possible treatments.","zh":"不同知識來源可能提出可能的治療方法。"},{"en":"Possible treatments are methods that may help relieve or cure a condition.","zh":"可能的治療方法是可能幫助紓緩或治癒狀況的方法。"},{"en":"Rest, antibiotics and time off work may be possible treatments for pneumonia.","zh":"休息、抗生素和請假可能是肺炎的治療方法。"},{"en":"Different medical traditions may suggest different possible treatments.","zh":"不同醫學傳統可能提出不同可能治療方法。"},{"en":"The phrase refers to options, not guaranteed cures.","zh":"這個短語指選項，而不是保證治癒。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":10},{"front":"the most influential and authoritative source","meaning":"最具影響力和權威性的來源","examples":[{"en":"The doctor may be the most influential and authoritative source of knowledge.","zh":"醫生可能是最具影響力和權威性的知識來源。"},{"en":"The most influential and authoritative source is the source with the greatest power and recognised authority.","zh":"最具影響力和權威性的來源，是最有力量並獲認可權威的來源。"},{"en":"In a workplace, a doctor’s certificate may be the most authoritative source of illness evidence.","zh":"在工作場所，醫生證明可能是疾病證據中最具權威性的來源。"},{"en":"This source can override personal judgement or informal advice.","zh":"這種來源可以凌駕個人判斷或非正式建議。"},{"en":"The phrase describes a hierarchy of knowledge.","zh":"這個短語描述知識的等級。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":10},{"front":"authoritative source of knowledge","meaning":"權威知識來源","examples":[{"en":"Medical knowledge is an authoritative source of knowledge.","zh":"醫學知識是一種權威知識來源。"},{"en":"An authoritative source of knowledge is trusted and recognised as legitimate.","zh":"權威知識來源是被信任並被承認為合法的知識來源。"},{"en":"Doctors are often treated as authoritative sources of knowledge about illness.","zh":"醫生常被視為關於疾病的權威知識來源。"},{"en":"An employer may require an authoritative source before approving sick leave.","zh":"僱主在批准病假前可能要求權威來源。"},{"en":"The phrase connects trust with social authority.","zh":"這個短語把信任與社會權威連接起來。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":10},{"front":"general practitioner","meaning":"普通科醫生","examples":[{"en":"The general practitioner provides influential medical knowledge.","zh":"普通科醫生提供具影響力的醫學知識。"},{"en":"A general practitioner is a doctor who provides ordinary first-contact medical care.","zh":"普通科醫生是提供一般初步醫療照護的醫生。"},{"en":"Patients often consult a general practitioner before seeing a specialist.","zh":"病人通常先諮詢普通科醫生，再看專科。"},{"en":"A general practitioner may diagnose common illnesses and issue certificates.","zh":"普通科醫生可以診斷常見疾病並發出證明書。"},{"en":"The phrase refers to a primary-care doctor.","zh":"這個短語指基層醫療醫生。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":10},{"front":"have access to","meaning":"能夠取得；接觸到","examples":[{"en":"We expect the doctor to have access to expert knowledge.","zh":"我們期望醫生能夠取得專業知識。"},{"en":"To have access to something means to be able to use or obtain it.","zh":"能夠取得某物是指可以使用或獲得它。"},{"en":"Doctors have access to medical textbooks, reports and professional training.","zh":"醫生能接觸到醫學教科書、報告和專業訓練。"},{"en":"Patients may not have access to the same specialist knowledge.","zh":"病人未必能取得同樣的專門知識。"},{"en":"The phrase describes availability of knowledge or resources.","zh":"這個短語描述知識或資源的可取得性。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":10},{"front":"expert knowledge","meaning":"專業知識","examples":[{"en":"The doctor has access to expert knowledge.","zh":"醫生能夠取得專業知識。"},{"en":"Expert knowledge is specialised knowledge gained through training and experience.","zh":"專業知識是透過訓練和經驗獲得的專門知識。"},{"en":"Medical expert knowledge helps doctors diagnose illness.","zh":"醫學專業知識幫助醫生診斷疾病。"},{"en":"Expert knowledge may be socially valued more than common sense.","zh":"專業知識在社會上可能比常識更受重視。"},{"en":"The phrase highlights professional understanding.","zh":"這個短語強調專業理解。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":11},{"front":"be socially sanctioned","meaning":"得到社會認可","examples":[{"en":"The doctor’s authority is socially sanctioned.","zh":"醫生的權威得到社會認可。"},{"en":"To be socially sanctioned means to be accepted or authorised by society.","zh":"得到社會認可是指被社會接受或授權。"},{"en":"Medical certificates are socially sanctioned evidence of illness.","zh":"醫學證明書是得到社會認可的疾病證據。"},{"en":"A doctor’s judgement is socially sanctioned in ways that informal advice is not.","zh":"醫生的判斷得到社會認可，而非正式建議則未必如此。"},{"en":"The phrase highlights social approval and legitimacy.","zh":"這個短語強調社會批准和合法性。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":11},{"front":"it would not be acceptable to","meaning":"……是不被接受的","examples":[{"en":"It would not be acceptable to miss work only because we feel unwell.","zh":"只因自己感到不適而不上班是不被接受的。"},{"en":"“It would not be acceptable to” means society or an institution would not regard an action as proper.","zh":"「……是不被接受的」表示社會或機構不會視某行動為恰當。"},{"en":"It would not be acceptable to claim long sick leave without evidence.","zh":"沒有證據便聲稱長期病假是不被接受的。"},{"en":"The phrase expresses social or workplace rules.","zh":"這個短語表達社會或工作場所規則。"},{"en":"It shows why medical authority matters.","zh":"它顯示醫學權威為何重要。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":11},{"front":"notify our employer","meaning":"通知僱主","examples":[{"en":"We may need to notify our employer if we are too ill to work.","zh":"如果我們病得不能上班，可能需要通知僱主。"},{"en":"To notify our employer means to officially inform the person or organisation we work for.","zh":"通知僱主是指正式告知我們工作的個人或機構。"},{"en":"Workers notify their employer when they need sick leave.","zh":"員工需要病假時會通知僱主。"},{"en":"An employer may ask for medical evidence after notification.","zh":"僱主在收到通知後可能要求醫學證據。"},{"en":"The phrase belongs to workplace procedures.","zh":"這個短語屬於工作場所程序。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":11},{"front":"turn up for work","meaning":"上班；出勤","examples":[{"en":"It may not be acceptable simply to say we are too unwell to turn up for work.","zh":"只是說自己太不適而不能上班，可能不被接受。"},{"en":"To turn up for work means to arrive at work as expected.","zh":"上班或出勤是指按預期到達工作地點。"},{"en":"A person with pneumonia may be too ill to turn up for work.","zh":"肺炎病人可能病得不能上班。"},{"en":"Employers may require a certificate if someone cannot turn up for work for several days.","zh":"如果某人數天不能出勤，僱主可能要求證明書。"},{"en":"The phrase is everyday language for attending work.","zh":"這個短語是表示到工的日常用語。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":11},{"front":"faith healer","meaning":"信仰治療師","examples":[{"en":"An employer may not accept the opinion of a faith healer.","zh":"僱主可能不接受信仰治療師的意見。"},{"en":"A faith healer is someone who claims to heal illness through religious or spiritual power.","zh":"信仰治療師是聲稱透過宗教或靈性力量治療疾病的人。"},{"en":"A faith healer may offer comfort, but their opinion may not count as medical evidence.","zh":"信仰治療師可能提供安慰，但其意見未必算作醫學證據。"},{"en":"The passage contrasts faith healers with authorised medical practitioners.","zh":"文章把信仰治療師與獲授權醫療從業員作對比。"},{"en":"The phrase represents a non-medical source of authority.","zh":"這個短語代表非醫學權威來源。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":11},{"front":"astrologer","meaning":"占星家","examples":[{"en":"An astrologer’s opinion is not treated like a medical diagnosis.","zh":"占星家的意見不會被視為醫學診斷。"},{"en":"An astrologer is someone who interprets human affairs through the positions of stars and planets.","zh":"占星家是透過星體和行星位置詮釋人事的人。"},{"en":"An employer would not normally accept an astrologer’s view as proof of illness.","zh":"僱主通常不會接受占星家的看法作為疾病證明。"},{"en":"The passage uses astrologers to show limits on acceptable knowledge.","zh":"文章使用占星家來顯示可接受知識的限制。"},{"en":"The phrase represents a non-medical form of belief.","zh":"這個短語代表非醫學形式的信念。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":11},{"front":"therapist","meaning":"治療師","examples":[{"en":"A therapist may offer advice, but it may not replace a medical certificate.","zh":"治療師可能提供建議，但未必能取代醫學證明書。"},{"en":"A therapist is a professional who provides treatment or support, often for mental or physical wellbeing.","zh":"治療師是提供治療或支援的專業人士，常涉及心理或身體健康。"},{"en":"Some therapists are recognised medical professionals, while others work in complementary fields.","zh":"有些治療師是獲認可醫療專業人士，另一些則屬輔助領域。"},{"en":"The passage suggests that not all therapeutic opinions carry the same workplace authority.","zh":"文章暗示並非所有治療意見都具有相同工作場所權威。"},{"en":"The phrase is used to contrast different kinds of health authority.","zh":"這個短語用來對比不同健康權威。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":11},{"front":"not a good idea","meaning":"不是好主意","examples":[{"en":"A priest’s view that work is not a good idea would not be enough.","zh":"神父認為上班不是好主意，這並不足夠。"},{"en":"“Not a good idea” means something is unwise or unsuitable.","zh":"「不是好主意」表示某事不明智或不合適。"},{"en":"Going to work with pneumonia is probably not a good idea.","zh":"患肺炎仍上班可能不是好主意。"},{"en":"Informal advice that work is not a good idea may lack official authority.","zh":"非正式建議說上班不是好主意，可能缺乏正式權威。"},{"en":"The phrase is everyday language, not a formal medical judgement.","zh":"這個短語是日常用語，不是正式醫學判斷。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":11},{"front":"expert medical diagnosis","meaning":"專業醫學診斷","examples":[{"en":"Workers may need an expert medical diagnosis to take sick leave.","zh":"員工可能需要專業醫學診斷才能請病假。"},{"en":"Expert medical diagnosis is a professional judgement made by a qualified medical practitioner.","zh":"專業醫學診斷是由合資格醫療從業員作出的專業判斷。"},{"en":"An expert medical diagnosis can confirm that a worker is genuinely ill.","zh":"專業醫學診斷可以確認員工確實生病。"},{"en":"It may be required before extended absence from work is accepted.","zh":"在長期缺勤獲接受前，可能需要它。"},{"en":"The phrase shows the institutional power of medical knowledge.","zh":"這個短語顯示醫學知識的制度性力量。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":11},{"front":"in order to obtain","meaning":"為了取得","examples":[{"en":"You need a medical diagnosis in order to obtain a certificate.","zh":"你需要醫學診斷，為了取得證明書。"},{"en":"“In order to obtain” means for the purpose of getting something.","zh":"「為了取得」表示以獲得某物為目的。"},{"en":"A patient may need an examination in order to obtain sick leave documentation.","zh":"病人可能需要檢查，為了取得病假文件。"},{"en":"Workers may consult a doctor in order to obtain official proof.","zh":"員工可能諮詢醫生，為了取得正式證明。"},{"en":"The phrase introduces the purpose behind an action.","zh":"這個短語帶出行動背後的目的。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":11},{"front":"necessary certificate","meaning":"必要證明書","examples":[{"en":"A necessary certificate may be required for extended sick leave.","zh":"長期病假可能需要必要證明書。"},{"en":"A necessary certificate is an official document required for a particular purpose.","zh":"必要證明書是為特定目的而要求的正式文件。"},{"en":"A doctor may issue the necessary certificate after diagnosis.","zh":"醫生可能在診斷後發出必要證明書。"},{"en":"Without the necessary certificate, an employer may not approve long absence.","zh":"沒有必要證明書，僱主可能不批准長期缺勤。"},{"en":"The phrase refers to required formal proof.","zh":"這個短語指所需正式證明。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":12},{"front":"off work","meaning":"不上班；請病假","examples":[{"en":"You may need to be off work for more than a short period.","zh":"你可能需要不上班超過一小段時間。"},{"en":"To be off work means not to attend work, often because of illness or leave.","zh":"不上班或請假是指不出勤，通常因疾病或休假。"},{"en":"A person with pneumonia may be off work for several weeks.","zh":"肺炎患者可能需要請病假數星期。"},{"en":"Being off work for longer may require medical certification.","zh":"較長時間不上班可能需要醫學證明。"},{"en":"The phrase is common in workplace illness contexts.","zh":"這個短語常見於工作場所疾病情境。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":12},{"front":"statutory self-certification period","meaning":"法定自我證明期","examples":[{"en":"A medical certificate is needed beyond the statutory self-certification period.","zh":"超過法定自我證明期後，需要醫學證明書。"},{"en":"A statutory self-certification period is the legally allowed time when workers can certify their own illness.","zh":"法定自我證明期是法律容許員工自行證明疾病的時間。"},{"en":"After this period, an employer may require a doctor’s certificate.","zh":"在這段期間後，僱主可能要求醫生證明書。"},{"en":"The phrase connects illness knowledge with workplace law.","zh":"這個短語把疾病知識與工作法律連接起來。"},{"en":"It shows that medical authority becomes necessary after a set period.","zh":"它顯示在指定期限後醫學權威變得必要。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":12},{"front":"the knowledge of the medical sciences","meaning":"醫學科學知識","examples":[{"en":"The knowledge of the medical sciences has a special status.","zh":"醫學科學知識具有特殊地位。"},{"en":"The knowledge of the medical sciences refers to organised scientific medical understanding.","zh":"醫學科學知識指有系統的科學醫學理解。"},{"en":"This knowledge includes diagnosis, treatment, anatomy and disease processes.","zh":"這種知識包括診斷、治療、解剖和疾病過程。"},{"en":"Society often gives medical science special authority in judging illness.","zh":"社會通常給予醫學科學在判斷疾病方面特殊權威。"},{"en":"The phrase contrasts formal science with informal knowledge.","zh":"這個短語把正式科學與非正式知識作對比。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":12},{"front":"be privileged in this respect","meaning":"在這方面享有特殊地位","examples":[{"en":"Medical knowledge is privileged in this respect.","zh":"醫學知識在這方面享有特殊地位。"},{"en":"To be privileged in this respect means to have special status or advantage in this particular way.","zh":"在這方面享有特殊地位是指在這一特定方面具有特殊地位或優勢。"},{"en":"Doctors’ opinions are privileged in this respect when sick leave is authorised.","zh":"在批准病假時，醫生意見在這方面享有特殊地位。"},{"en":"Personal feeling is not privileged in the same way as medical diagnosis.","zh":"個人感受並不像醫學診斷那樣享有同等特殊地位。"},{"en":"The phrase describes unequal authority among knowledge sources.","zh":"這個短語描述不同知識來源之間的不平等權威。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":12},{"front":"contemporary Western culture","meaning":"當代西方文化","examples":[{"en":"Medical knowledge is privileged in contemporary Western culture.","zh":"醫學知識在當代西方文化中享有特殊地位。"},{"en":"Contemporary Western culture means modern cultural practices and beliefs in Western societies.","zh":"當代西方文化是指西方社會中的現代文化做法和信念。"},{"en":"In contemporary Western culture, doctors are often trusted as experts.","zh":"在當代西方文化中，醫生常被信任為專家。"},{"en":"Medical certificates carry authority in many modern Western workplaces.","zh":"醫學證明書在許多現代西方工作場所具有權威。"},{"en":"The phrase gives social and historical context.","zh":"這個短語提供社會和歷史背景。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":12},{"front":"medical practitioners","meaning":"醫生；醫療從業員","examples":[{"en":"Medical practitioners have expert knowledge and legal authority.","zh":"醫療從業員具有專業知識和法律權限。"},{"en":"Medical practitioners are trained professionals authorised to practise medicine.","zh":"醫療從業員是受過訓練並獲授權行醫的專業人士。"},{"en":"Doctors and some specialists are medical practitioners.","zh":"醫生和一些專科人士都是醫療從業員。"},{"en":"Medical practitioners can diagnose illness and prescribe treatment.","zh":"醫療從業員可以診斷疾病並處方治療。"},{"en":"The phrase refers to recognised members of the medical profession.","zh":"這個短語指被認可的醫療專業成員。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":12},{"front":"be seen as having","meaning":"被視為擁有","examples":[{"en":"Doctors are seen as having expert knowledge.","zh":"醫生被視為擁有專業知識。"},{"en":"To be seen as having something means to be regarded by others as possessing it.","zh":"被視為擁有某物是指被他人認為具有它。"},{"en":"Medical practitioners are seen as having authority to diagnose illness.","zh":"醫療從業員被視為擁有診斷疾病的權威。"},{"en":"Patients are seen as having personal experience of symptoms.","zh":"病人被視為擁有對症狀的個人經驗。"},{"en":"The phrase describes social perception.","zh":"這個短語描述社會看法。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":12},{"front":"legal authority","meaning":"法律權限","examples":[{"en":"Doctors have the legal authority to prescribe treatment.","zh":"醫生具有處方治療的法律權限。"},{"en":"Legal authority is power recognised by law.","zh":"法律權限是由法律承認的權力。"},{"en":"Medical practitioners have legal authority to prescribe certain drugs.","zh":"醫療從業員具有處方某些藥物的法律權限。"},{"en":"An employer may accept documents backed by legal authority.","zh":"僱主可能接受具有法律權限支持的文件。"},{"en":"The phrase connects medical practice with law.","zh":"這個短語把醫療實踐與法律連接起來。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":12},{"front":"be required to","meaning":"被需要去","examples":[{"en":"Doctors have the authority required to prescribe drugs.","zh":"醫生具有處方藥物所需要的權限。"},{"en":"“Be required to” means to need to do something or to be necessary for a purpose.","zh":"「被需要去」表示需要做某事，或為某目的所必需。"},{"en":"A certificate may be required to approve extended sick leave.","zh":"可能需要證明書來批准長期病假。"},{"en":"Medical training is required to make certain diagnoses.","zh":"作出某些診斷需要醫學訓練。"},{"en":"The phrase expresses necessity or obligation.","zh":"這個短語表達必要性或義務。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":12},{"front":"prescribe drugs and treatment","meaning":"處方藥物和治療","examples":[{"en":"Medical practitioners can prescribe drugs and treatment.","zh":"醫療從業員可以處方藥物和治療。"},{"en":"To prescribe drugs and treatment means to officially recommend or order medical care.","zh":"處方藥物和治療是指正式建議或安排醫療照護。"},{"en":"Doctors prescribe drugs and treatment after assessing symptoms and evidence.","zh":"醫生在評估症狀和證據後處方藥物和治療。"},{"en":"Patients may not otherwise be able to obtain certain medicines.","zh":"病人否則可能無法取得某些藥物。"},{"en":"The phrase highlights authorised medical action.","zh":"這個短語強調獲授權的醫療行動。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":12},{"front":"otherwise have access","meaning":"否則可以取得","examples":[{"en":"Patients would not otherwise have access to certain treatments.","zh":"病人否則未必可以取得某些治療。"},{"en":"“Otherwise have access” means be able to obtain something without that condition.","zh":"「否則可以取得」表示在沒有該條件下能否獲得某物。"},{"en":"Without a doctor’s prescription, patients may not otherwise have access to some drugs.","zh":"沒有醫生處方，病人否則未必能取得某些藥物。"},{"en":"Medical authority controls access to certain treatments.","zh":"醫學權威控制某些治療的取得。"},{"en":"The phrase describes access that depends on professional approval.","zh":"這個短語描述取決於專業批准的取得途徑。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":13},{"front":"there is a range of","meaning":"有一系列……","examples":[{"en":"There is a range of different knowledge used in health decisions.","zh":"在健康決定中使用了一系列不同知識。"},{"en":"“There is a range of” means there are several different types or examples.","zh":"「有一系列……」表示有數種不同類型或例子。"},{"en":"There is a range of sources that patients use to understand illness.","zh":"病人用來理解疾病的來源有一系列。"},{"en":"A range of knowledge may include personal, social and medical sources.","zh":"一系列知識可能包括個人、社會和醫學來源。"},{"en":"The phrase introduces variety.","zh":"這個短語帶出多樣性。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":13},{"front":"make decisions about","meaning":"就……作決定","examples":[{"en":"People draw on different knowledge when making decisions about health.","zh":"人們在就健康作決定時借助不同知識。"},{"en":"To make decisions about something means to choose what to do regarding it.","zh":"就某事作決定是指選擇如何處理它。"},{"en":"Patients make decisions about whether to see a doctor.","zh":"病人就是否看醫生作決定。"},{"en":"Doctors make decisions about diagnosis and treatment.","zh":"醫生就診斷和治療作決定。"},{"en":"The phrase refers to judgement followed by action.","zh":"這個短語指判斷後採取行動。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":13},{"front":"state of health","meaning":"健康狀況","examples":[{"en":"People use different knowledge sources to judge their state of health.","zh":"人們使用不同知識來源來判斷自己的健康狀況。"},{"en":"State of health means a person’s overall physical or medical condition.","zh":"健康狀況是指一個人的整體身體或醫學情況。"},{"en":"A doctor may assess a patient’s state of health through examination and questions.","zh":"醫生可能透過檢查和提問評估病人的健康狀況。"},{"en":"Personal feelings may not fully reveal one’s state of health.","zh":"個人感受未必完全揭示健康狀況。"},{"en":"The phrase refers to general health condition.","zh":"這個短語指一般健康情況。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":13},{"front":"existing knowledge","meaning":"現有知識","examples":[{"en":"The story contains more than existing knowledge.","zh":"這個故事包含的不只是現有知識。"},{"en":"Existing knowledge is knowledge already available before a new event or investigation.","zh":"現有知識是在新事件或調查前已存在的知識。"},{"en":"The doctor uses existing knowledge from training and textbooks.","zh":"醫生使用來自訓練和教科書的現有知識。"},{"en":"Existing knowledge helps guide the first medical hypothesis.","zh":"現有知識幫助引導最初的醫學假設。"},{"en":"The phrase contrasts old knowledge with newly constructed knowledge.","zh":"這個短語把舊知識與新建構的知識作對比。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":13},{"front":"new knowledge is constructed","meaning":"新知識被建構出來","examples":[{"en":"New knowledge is constructed within the medical encounter.","zh":"新知識在醫療會面中被建構出來。"},{"en":"New knowledge is constructed when evidence, interpretation and experience create fresh understanding.","zh":"當證據、詮釋和經驗產生新的理解時，新知識便被建構出來。"},{"en":"A diagnosis can be a moment when new knowledge is constructed.","zh":"診斷可以是新知識被建構出來的時刻。"},{"en":"The doctor and patient together contribute to the construction of medical knowledge.","zh":"醫生和病人共同為醫學知識的建構作出貢獻。"},{"en":"The phrase shows knowledge as something actively made.","zh":"這個短語顯示知識是被主動創造的。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":13},{"front":"given the doctor’s medical training","meaning":"鑑於醫生的醫學訓練","examples":[{"en":"Given the doctor’s medical training, she may form a hypothesis.","zh":"鑑於醫生的醫學訓練，她可能形成一個假設。"},{"en":"“Given the doctor’s medical training” means considering her professional education and preparation.","zh":"「鑑於醫生的醫學訓練」表示考慮她的專業教育和準備。"},{"en":"Given the doctor’s medical training, she can interpret symptoms differently from the patient.","zh":"鑑於醫生的醫學訓練，她可以以不同於病人的方式詮釋症狀。"},{"en":"The phrase explains why the doctor can make expert judgements.","zh":"這個短語解釋醫生為何能作出專家判斷。"},{"en":"It introduces a condition that shapes reasoning.","zh":"它帶出塑造推理的條件。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":13},{"front":"medical training and background","meaning":"醫學訓練和背景","examples":[{"en":"The doctor’s medical training and background guide her judgement.","zh":"醫生的醫學訓練和背景引導她的判斷。"},{"en":"Medical training and background include education, clinical practice and professional experience.","zh":"醫學訓練和背景包括教育、臨床實踐和專業經驗。"},{"en":"A doctor’s background helps her recognise patterns in symptoms.","zh":"醫生的背景幫助她辨認症狀模式。"},{"en":"Medical training and background shape how evidence is interpreted.","zh":"醫學訓練和背景塑造證據如何被詮釋。"},{"en":"The phrase describes the foundation of expert reasoning.","zh":"這個短語描述專家推理的基礎。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":13},{"front":"hypothesise","meaning":"提出假設","examples":[{"en":"The doctor may hypothesise that the illness is pneumonia.","zh":"醫生可能提出假設，認為疾病是肺炎。"},{"en":"To hypothesise means to suggest a possible explanation before it is fully confirmed.","zh":"提出假設是指在完全確認前提出一個可能解釋。"},{"en":"The doctor may hypothesise infection after hearing the patient’s cough.","zh":"醫生聽到病人咳嗽後，可能提出感染的假設。"},{"en":"A hypothesis must be tested against evidence.","zh":"假設必須以證據驗證。"},{"en":"The phrase describes a key step in medical reasoning.","zh":"這個短語描述醫學推理中的關鍵步驟。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":13},{"front":"proceed to","meaning":"接着；進而","examples":[{"en":"The doctor may proceed to look for evidence.","zh":"醫生可能接着尋找證據。"},{"en":"To proceed to do something means to continue by doing the next step.","zh":"接着做某事是指繼續進行下一步。"},{"en":"After forming a hypothesis, the doctor proceeds to examine the patient.","zh":"形成假設後，醫生進而檢查病人。"},{"en":"Researchers proceed to test an idea after proposing it.","zh":"研究人員提出想法後，接着測試它。"},{"en":"The phrase marks movement from one stage to another.","zh":"這個短語標示由一個階段移向另一個階段。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":13},{"front":"look for evidence","meaning":"尋找證據","examples":[{"en":"The doctor looks for evidence to test her hypothesis.","zh":"醫生尋找證據來驗證她的假設。"},{"en":"To look for evidence means to search for information that supports or challenges an idea.","zh":"尋找證據是指尋找支持或挑戰某想法的資料。"},{"en":"The doctor looks for evidence in breathing sounds, temperature and blood pressure.","zh":"醫生在呼吸聲、體溫和血壓中尋找證據。"},{"en":"Evidence helps distinguish between stress and pneumonia.","zh":"證據幫助區分壓力和肺炎。"},{"en":"The phrase is central to scientific and medical reasoning.","zh":"這個短語是科學和醫學推理的核心。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":13},{"front":"use observations and instruments","meaning":"使用觀察和儀器","examples":[{"en":"The doctor uses observations and instruments to assess evidence.","zh":"醫生使用觀察和儀器來評估證據。"},{"en":"To use observations and instruments means to rely on what is seen, heard or measured with tools.","zh":"使用觀察和儀器是指依靠所見、所聽或用工具量度到的資料。"},{"en":"A stethoscope and thermometer are instruments used in examination.","zh":"聽診器和溫度計是檢查中使用的儀器。"},{"en":"Observations and instruments help make diagnosis more reliable.","zh":"觀察和儀器幫助令診斷更可靠。"},{"en":"The phrase combines human judgement with medical tools.","zh":"這個短語結合人的判斷與醫療工具。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":14},{"front":"assess the evidence","meaning":"評估證據","examples":[{"en":"The doctor assesses the evidence before making a diagnosis.","zh":"醫生在作出診斷前評估證據。"},{"en":"To assess the evidence means to judge the meaning, quality and relevance of information.","zh":"評估證據是指判斷資料的意義、質素和相關性。"},{"en":"Doctors assess evidence from symptoms, tests and examination.","zh":"醫生評估來自症狀、檢查和身體檢查的證據。"},{"en":"Evidence must be assessed in context before a conclusion is made.","zh":"證據必須在情境中被評估，然後才下結論。"},{"en":"The phrase describes careful evaluation.","zh":"這個短語描述仔細評價。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":14},{"front":"interpret it in light of","meaning":"根據……詮釋它","examples":[{"en":"The doctor interprets the evidence in light of her training.","zh":"醫生根據她的訓練詮釋證據。"},{"en":"To interpret something in light of something else means to understand it using that background or context.","zh":"根據某背景詮釋某事，是指使用該背景或情境理解它。"},{"en":"The doctor interprets a cough in light of medical knowledge about pneumonia.","zh":"醫生根據關於肺炎的醫學知識詮釋咳嗽。"},{"en":"A patient may interpret tiredness in light of work stress.","zh":"病人可能根據工作壓力詮釋疲倦。"},{"en":"The phrase shows that evidence does not speak for itself.","zh":"這個短語顯示證據並不會自行說明一切。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":14},{"front":"in light of","meaning":"根據；鑑於","examples":[{"en":"Evidence is interpreted in light of medical training and experience.","zh":"證據根據醫學訓練和經驗被詮釋。"},{"en":"“In light of” means considering or based on something.","zh":"「根據」或「鑑於」表示考慮或基於某事。"},{"en":"In light of the diagnosis, the symptoms now seem serious.","zh":"鑑於診斷，症狀現在看來很嚴重。"},{"en":"In light of new evidence, the doctor changed her view.","zh":"根據新證據，醫生改變了看法。"},{"en":"The phrase introduces the context used for judgement.","zh":"這個短語帶出用於判斷的情境。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":14},{"front":"result in new knowledge","meaning":"產生新知識","examples":[{"en":"The process results in new knowledge for the doctor and patient.","zh":"這個過程為醫生和病人產生新知識。"},{"en":"To result in new knowledge means to produce fresh understanding.","zh":"產生新知識是指帶來新的理解。"},{"en":"A medical examination can result in new knowledge about a patient’s illness.","zh":"醫學檢查可以產生關於病人疾病的新知識。"},{"en":"Diagnosis creates new knowledge by linking symptoms to a recognised condition.","zh":"診斷透過把症狀連接到被認可的病症來創造新知識。"},{"en":"The phrase shows knowledge emerging from a process.","zh":"這個短語顯示知識從過程中出現。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":14},{"front":"be added to","meaning":"被加入","examples":[{"en":"The new experience will be added to the doctor’s medical knowledge.","zh":"新經驗將被加入醫生的醫學知識中。"},{"en":"To be added to something means to become part of it.","zh":"被加入某物是指成為它的一部分。"},{"en":"Each diagnosis may be added to a doctor’s experience.","zh":"每次診斷都可能被加入醫生的經驗中。"},{"en":"New clinical cases are added to medical understanding over time.","zh":"新臨床個案會隨時間被加入醫學理解中。"},{"en":"The phrase shows knowledge accumulating.","zh":"這個短語顯示知識累積。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":14},{"front":"future diagnosis","meaning":"日後診斷","examples":[{"en":"The experience may help in the future diagnosis of pneumonia.","zh":"這次經驗可能有助日後診斷肺炎。"},{"en":"Future diagnosis means diagnosis made later, using knowledge gained earlier.","zh":"日後診斷是以早前獲得的知識在較後時間作出的診斷。"},{"en":"A doctor’s past cases can improve future diagnosis.","zh":"醫生過去的個案可以改善日後診斷。"},{"en":"Medical experience becomes useful when similar symptoms appear in future patients.","zh":"當未來病人出現相似症狀時，醫學經驗會變得有用。"},{"en":"The phrase links present learning with later medical judgement.","zh":"這個短語把目前學習與日後醫學判斷連接起來。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":14},{"front":"complete the table below","meaning":"完成下方表格","examples":[{"en":"Students complete the table below using words from the passage.","zh":"學生使用文章中的詞語完成下方表格。"},{"en":"To complete the table below means to fill missing information in a given table.","zh":"完成下方表格是指填入指定表格中的缺失資料。"},{"en":"Read the headings carefully before completing the table below.","zh":"完成下方表格前，應仔細閱讀標題。"},{"en":"The answers must fit the table’s categories and grammar.","zh":"答案必須符合表格類別和文法。"},{"en":"The phrase is a common instruction in reading tests.","zh":"這個短語是閱讀測驗中的常見指示。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":14},{"front":"no more than three words","meaning":"不多於三個字","examples":[{"en":"The answer should use no more than three words from the passage.","zh":"答案應使用文章中不多於三個字。"},{"en":"“No more than three words” means three words or fewer are allowed.","zh":"「不多於三個字」表示可以使用三個或更少詞語。"},{"en":"“Personal experience” fits the instruction because it has two words.","zh":"“Personal experience”符合指示，因為它有兩個詞。"},{"en":"Writing too many words may make an answer incorrect.","zh":"寫太多詞可能令答案錯誤。"},{"en":"The phrase gives a strict word limit.","zh":"這個短語給出嚴格字數限制。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":14},{"front":"from the passage","meaning":"從篇章中選取","examples":[{"en":"The answers must be taken from the passage.","zh":"答案必須從篇章中選取。"},{"en":"“From the passage” means using words or information in the reading text.","zh":"「從篇章中選取」表示使用閱讀文章中的詞語或資料。"},{"en":"Students should not use outside knowledge when the answer must come from the passage.","zh":"當答案必須來自篇章時，學生不應使用外部知識。"},{"en":"Exact wording from the passage may be required.","zh":"可能需要使用篇章中的確切措辭。"},{"en":"The phrase identifies the source of the answer.","zh":"這個短語指出答案來源。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":14},{"front":"source of knowledge","meaning":"知識來源","examples":[{"en":"The table lists each source of knowledge and its examples.","zh":"表格列出每個知識來源及其例子。"},{"en":"A source of knowledge is where knowledge comes from.","zh":"知識來源是知識來自的地方。"},{"en":"Personal experience, expert diagnosis and laboratory reports can be sources of knowledge.","zh":"個人經驗、專家診斷和化驗報告都可以是知識來源。"},{"en":"The passage compares how different sources of knowledge are valued.","zh":"文章比較不同知識來源如何被重視。"},{"en":"The phrase is central to the article’s argument.","zh":"這個短語是文章論點的核心。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":14},{"front":"personal experience","meaning":"個人經驗","examples":[{"en":"Personal experience includes symptoms such as coughing and tiredness.","zh":"個人經驗包括咳嗽和疲倦等症狀。"},{"en":"Personal experience is knowledge gained through one’s own feelings and observations.","zh":"個人經驗是透過自己的感受和觀察獲得的知識。"},{"en":"A patient’s personal experience helps explain why they seek medical help.","zh":"病人的個人經驗幫助解釋他們為何尋求醫療幫助。"},{"en":"Personal experience may be accurate, but it may also be incomplete.","zh":"個人經驗可能準確，但也可能不完整。"},{"en":"The phrase refers to first-person knowledge.","zh":"這個短語指第一身知識。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":15},{"front":"medical examination","meaning":"醫學檢查","examples":[{"en":"A medical examination may include checking temperature and blood pressure.","zh":"醫學檢查可能包括量體溫和血壓。"},{"en":"A medical examination is a doctor’s physical or clinical assessment of a patient.","zh":"醫學檢查是醫生對病人進行的身體或臨床評估。"},{"en":"Listening to the chest is part of a medical examination.","zh":"聽診胸口是醫學檢查的一部分。"},{"en":"A medical examination provides evidence beyond personal feelings.","zh":"醫學檢查提供超越個人感受的證據。"},{"en":"The phrase describes a formal process of checking health.","zh":"這個短語描述正式檢查健康的過程。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":15},{"front":"common judgement","meaning":"一般判斷","examples":[{"en":"Common judgement can come from people around us.","zh":"一般判斷可以來自身邊的人。"},{"en":"Common judgement is everyday judgement based on ordinary social understanding.","zh":"一般判斷是基於普通社會理解的日常判斷。"},{"en":"Friends may use common judgement when saying someone looks ill.","zh":"朋友說某人看起來病了時，可能使用一般判斷。"},{"en":"Common judgement can be helpful, but it is not the same as medical diagnosis.","zh":"一般判斷可以有幫助，但不同於醫學診斷。"},{"en":"The phrase refers to non-specialist interpretation.","zh":"這個短語指非專業詮釋。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":15},{"front":"scientific evidence","meaning":"科學證據","examples":[{"en":"Scientific evidence may come from medical knowledge and reports.","zh":"科學證據可能來自醫學知識和報告。"},{"en":"Scientific evidence is information gathered through systematic observation, testing or research.","zh":"科學證據是透過系統觀察、測試或研究收集的資料。"},{"en":"Laboratory reports can provide scientific evidence for diagnosis.","zh":"化驗報告可以為診斷提供科學證據。"},{"en":"Doctors use scientific evidence together with clinical experience.","zh":"醫生把科學證據與臨床經驗一起使用。"},{"en":"The phrase represents formal, research-based knowledge.","zh":"這個短語代表正式、以研究為基礎的知識。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":15},{"front":"construction of new knowledge","meaning":"新知識的建構","examples":[{"en":"The doctor’s testing of a hypothesis involves the construction of new knowledge.","zh":"醫生驗證假設涉及新知識的建構。"},{"en":"Construction of new knowledge means creating fresh understanding through evidence and interpretation.","zh":"新知識的建構是指透過證據和詮釋創造新的理解。"},{"en":"A medical encounter can involve the construction of new knowledge for both doctor and patient.","zh":"醫療會面可以涉及醫生和病人共同建構新知識。"},{"en":"Diagnosis is not only applying old knowledge but also constructing new knowledge.","zh":"診斷不只是應用舊知識，也是在建構新知識。"},{"en":"The phrase presents knowledge as an active process.","zh":"這個短語把知識呈現為主動過程。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":15},{"front":"testing a medical hypothesis","meaning":"驗證醫學假設","examples":[{"en":"The doctor tests a medical hypothesis using prior training and experience.","zh":"醫生使用既有訓練和經驗來驗證醫學假設。"},{"en":"Testing a medical hypothesis means checking whether a possible diagnosis is supported by evidence.","zh":"驗證醫學假設是指檢查一個可能診斷是否有證據支持。"},{"en":"The doctor tests the pneumonia hypothesis by examining symptoms and signs.","zh":"醫生透過檢查症狀和徵象來驗證肺炎假設。"},{"en":"Medical hypotheses guide what evidence doctors look for.","zh":"醫學假設引導醫生尋找哪些證據。"},{"en":"The phrase describes scientific reasoning in clinical practice.","zh":"這個短語描述臨床實踐中的科學推理。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":15},{"front":"prior training","meaning":"既有訓練","examples":[{"en":"Prior training helps doctors interpret medical evidence.","zh":"既有訓練幫助醫生詮釋醫學證據。"},{"en":"Prior training is education and practice gained before the current situation.","zh":"既有訓練是在目前情況之前獲得的教育和實踐。"},{"en":"A doctor’s prior training helps her recognise pneumonia symptoms.","zh":"醫生的既有訓練幫助她辨認肺炎症狀。"},{"en":"Prior training shapes how evidence is assessed.","zh":"既有訓練塑造證據如何被評估。"},{"en":"The phrase emphasises knowledge already acquired.","zh":"這個短語強調已經獲得的知識。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":15},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"The task asks which paragraph contains the following information.","zh":"題目詢問哪一段包含以下資料。"},{"en":"“Which paragraph contains” asks students to identify where information appears in the text.","zh":"「哪一段包含」要求學生識別資料出現在文章哪處。"},{"en":"Which paragraph contains the example of pneumonia?","zh":"哪一段包含肺炎的例子？"},{"en":"This question type tests scanning and locating skills.","zh":"這類題目測試掃讀和定位能力。"},{"en":"The phrase connects specific information with paragraph structure.","zh":"這個短語把特定資料與段落結構連接起來。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":15},{"front":"the following information","meaning":"以下資料","examples":[{"en":"Students identify the paragraph containing the following information.","zh":"學生識別包含以下資料的段落。"},{"en":"The following information means the details listed after the instruction.","zh":"以下資料是指指示後列出的細節。"},{"en":"Read the following information carefully before searching the passage.","zh":"搜尋文章前，先仔細閱讀以下資料。"},{"en":"Each item of following information must be matched with a paragraph.","zh":"每項以下資料都必須與一段配對。"},{"en":"The phrase points forward to a list.","zh":"這個短語指向後面的列表。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":15},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Students write the correct letter in the answer box.","zh":"學生在答案方格中寫上正確字母。"},{"en":"To write the correct letter means to record the letter that matches the answer.","zh":"寫上正確字母是指記錄與答案相配的字母。"},{"en":"In paragraph-matching tasks, each paragraph is usually represented by a letter.","zh":"在段落配對題中，每段通常以字母表示。"},{"en":"Students must write the correct letter rather than the paragraph number if instructed.","zh":"如果指示要求，學生必須寫正確字母，而不是段落號碼。"},{"en":"The phrase is an exam instruction.","zh":"這個短語是考試指示。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":15},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Answers should be written on the answer sheet.","zh":"答案應寫在答題紙上。"},{"en":"On your answer sheet means in the official place where exam answers are recorded.","zh":"在答題紙上是指在正式記錄考試答案的位置。"},{"en":"Students should transfer answers to the answer sheet before time ends.","zh":"學生應在時間結束前把答案轉寫到答題紙上。"},{"en":"Answers written only in notes may not be marked.","zh":"只寫在筆記中的答案可能不會評分。"},{"en":"The phrase identifies where to write the final response.","zh":"這個短語指出最終答案應寫在哪裏。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":15},{"front":"a contrast between","meaning":"……之間的對比","examples":[{"en":"The question asks for a contrast between personal judgement and diagnosis.","zh":"題目要求找出個人判斷與診斷之間的對比。"},{"en":"A contrast between two things is a clear difference between them.","zh":"兩者之間的對比是它們之間的清楚差異。"},{"en":"The passage shows a contrast between feeling ill and having a diagnosis.","zh":"文章顯示感到不適與獲得診斷之間的對比。"},{"en":"Personal judgement may be uncertain, while medical diagnosis can be authoritative.","zh":"個人判斷可能不確定，而醫學診斷可以具權威性。"},{"en":"The phrase highlights comparison through difference.","zh":"這個短語透過差異強調比較。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":16},{"front":"personal judgement","meaning":"個人判斷","examples":[{"en":"Personal judgement may differ from a doctor’s diagnosis.","zh":"個人判斷可能與醫生診斷不同。"},{"en":"Personal judgement is an individual’s own assessment of a situation.","zh":"個人判斷是個人對情況的自我評估。"},{"en":"A patient’s personal judgement may explain symptoms as stress.","zh":"病人的個人判斷可能把症狀解釋為壓力。"},{"en":"Medical examination can confirm or challenge personal judgement.","zh":"醫學檢查可以確認或挑戰個人判斷。"},{"en":"The phrase refers to non-expert self-assessment.","zh":"這個短語指非專業自我評估。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":16},{"front":"doctor’s diagnosis","meaning":"醫生診斷","examples":[{"en":"A doctor’s diagnosis can change how a patient understands symptoms.","zh":"醫生診斷可以改變病人如何理解症狀。"},{"en":"A doctor’s diagnosis is the medical identification of a patient’s condition.","zh":"醫生診斷是對病人病況的醫學識別。"},{"en":"The doctor’s diagnosis turned tiredness and coughing into evidence of pneumonia.","zh":"醫生診斷把疲倦和咳嗽轉化為肺炎證據。"},{"en":"A doctor’s diagnosis often carries social and legal authority.","zh":"醫生診斷通常具有社會和法律權威。"},{"en":"The phrase represents expert medical judgement.","zh":"這個短語代表專業醫學判斷。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":16},{"front":"a reference to","meaning":"提及……","examples":[{"en":"The question asks for a reference to cultural ideas about stress.","zh":"題目要求找出提及關於壓力的文化觀念之處。"},{"en":"A reference to something is a mention of it.","zh":"提及某事是指說到或指出它。"},{"en":"The passage makes a reference to stress in workplace exchanges.","zh":"文章提及工作場所交流中的壓力。"},{"en":"A reference to popular culture helps explain why people interpret symptoms as stress.","zh":"提及大眾文化有助解釋人們為何把症狀詮釋為壓力。"},{"en":"The phrase asks readers to locate a mentioned idea.","zh":"這個短語要求讀者找出被提到的觀念。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":16},{"front":"cultural ideas about stress","meaning":"關於壓力的文化觀念","examples":[{"en":"Cultural ideas about stress influence how people explain illness.","zh":"關於壓力的文化觀念影響人們如何解釋疾病。"},{"en":"Cultural ideas about stress are shared beliefs about how stress affects health.","zh":"關於壓力的文化觀念是關於壓力如何影響健康的共享信念。"},{"en":"If stress is often discussed in media, people may use it to explain symptoms.","zh":"如果傳媒經常討論壓力，人們可能用它來解釋症狀。"},{"en":"Cultural ideas can shape personal knowledge before medical diagnosis.","zh":"文化觀念可以在醫學診斷前塑造個人知識。"},{"en":"The phrase links illness interpretation with society.","zh":"這個短語把疾病詮釋與社會連接起來。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":16},{"front":"professional diagnosis","meaning":"專業診斷","examples":[{"en":"A professional diagnosis may be required before sick leave is authorised.","zh":"病假獲批准前可能需要專業診斷。"},{"en":"A professional diagnosis is a diagnosis made by a qualified expert.","zh":"專業診斷是由合資格專家作出的診斷。"},{"en":"Employers may trust professional diagnosis more than personal claims.","zh":"僱主可能比個人聲稱更信任專業診斷。"},{"en":"Professional diagnosis can provide official evidence of illness.","zh":"專業診斷可以提供疾病的正式證據。"},{"en":"The phrase highlights the authority of medical professionals.","zh":"這個短語強調醫療專業人士的權威。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":16},{"front":"sick leave","meaning":"病假","examples":[{"en":"A medical certificate may be needed for sick leave.","zh":"病假可能需要醫學證明書。"},{"en":"Sick leave is approved absence from work because of illness.","zh":"病假是因疾病而獲批准的工作缺勤。"},{"en":"A worker with pneumonia may need sick leave to recover.","zh":"患肺炎的員工可能需要病假來恢復。"},{"en":"Sick leave often requires some form of official notification or proof.","zh":"病假通常需要某種正式通知或證明。"},{"en":"The phrase belongs to workplace health procedures.","zh":"這個短語屬於工作場所健康程序。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":16},{"front":"be authorised","meaning":"被批准","examples":[{"en":"Sick leave may need to be authorised by a medical certificate.","zh":"病假可能需要由醫學證明書批准。"},{"en":"To be authorised means to be officially approved or permitted.","zh":"被批准是指獲正式同意或許可。"},{"en":"Long absence from work may be authorised after a doctor’s diagnosis.","zh":"長期缺勤可能在醫生診斷後被批准。"},{"en":"A medical certificate can authorise sick leave beyond a short period.","zh":"醫學證明書可以批准超過短期的病假。"},{"en":"The phrase describes institutional approval.","zh":"這個短語描述制度性批准。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":16},{"front":"be regarded in society","meaning":"在社會中被看待","examples":[{"en":"Doctors’ opinions are regarded as authoritative in society.","zh":"醫生意見在社會中被視為具權威性。"},{"en":"To be regarded in society in a certain way means to be viewed that way by the wider community.","zh":"在社會中以某種方式被看待，是指被更廣泛社群如此理解。"},{"en":"Medical knowledge is regarded in society as especially trustworthy.","zh":"醫學知識在社會中被視為特別可信。"},{"en":"Personal feelings may not be regarded in society as sufficient proof for sick leave.","zh":"個人感受在社會中未必被視為病假的充分證明。"},{"en":"The phrase focuses on social recognition.","zh":"這個短語集中於社會認可。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":16},{"front":"patient’s illness","meaning":"病人的疾病","examples":[{"en":"A patient’s illness can become part of new medical knowledge.","zh":"病人的疾病可以成為新醫學知識的一部分。"},{"en":"A patient’s illness is the condition or disease experienced by a patient.","zh":"病人的疾病是病人所經歷的病況或疾病。"},{"en":"Doctors learn from each patient’s illness and treatment response.","zh":"醫生會從每位病人的疾病和治療反應中學習。"},{"en":"A patient’s illness may help refine future diagnosis.","zh":"病人的疾病可能幫助完善日後診斷。"},{"en":"The phrase connects individual cases with broader medical learning.","zh":"這個短語把個別個案與更廣泛醫學學習連接起來。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":16},{"front":"become part of new knowledge","meaning":"成為新知識的一部分","examples":[{"en":"The doctor’s experience with a patient can become part of new knowledge.","zh":"醫生與病人的經驗可以成為新知識的一部分。"},{"en":"To become part of new knowledge means to be included in later understanding.","zh":"成為新知識的一部分是指被納入後來的理解中。"},{"en":"A difficult diagnosis may become part of a doctor’s future knowledge.","zh":"一次困難診斷可能成為醫生日後知識的一部分。"},{"en":"Each patient case can add to medical experience.","zh":"每個病人個案都可以增加醫學經驗。"},{"en":"The phrase shows how knowledge grows through practice.","zh":"這個短語顯示知識如何透過實踐增長。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":16},{"front":"non-specialist sources","meaning":"非專業來源","examples":[{"en":"People may draw knowledge from non-specialist sources.","zh":"人們可能從非專業來源取得知識。"},{"en":"Non-specialist sources are sources that do not come from trained experts.","zh":"非專業來源是並非來自受訓專家的來源。"},{"en":"Friends, family, media and common sense can be non-specialist sources.","zh":"朋友、家人、傳媒和常識都可以是非專業來源。"},{"en":"Non-specialist sources can influence how people explain symptoms.","zh":"非專業來源可以影響人們如何解釋症狀。"},{"en":"The phrase contrasts informal knowledge with expert knowledge.","zh":"這個短語把非正式知識與專家知識作對比。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":17},{"front":"other than personal experience","meaning":"除個人經驗以外","examples":[{"en":"The passage mentions knowledge sources other than personal experience.","zh":"文章提到除個人經驗以外的知識來源。"},{"en":"Other than personal experience means apart from what a person directly feels or notices.","zh":"除個人經驗以外表示除了個人直接感受或注意到的東西。"},{"en":"Doctors, friends and textbooks are sources other than personal experience.","zh":"醫生、朋友和教科書都是除個人經驗以外的來源。"},{"en":"The phrase expands the discussion beyond the patient’s own feelings.","zh":"這個短語把討論擴展到病人自身感受以外。"},{"en":"It highlights additional ways of knowing.","zh":"它強調額外的認知方式。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":17},{"front":"combine personal experience with","meaning":"把個人經驗與……結合","examples":[{"en":"The example combines personal experience with professional medical opinion.","zh":"這個例子把個人經驗與專業醫學意見結合。"},{"en":"To combine personal experience with something means to use both together.","zh":"把個人經驗與某事結合是指同時使用兩者。"},{"en":"A patient combines personal experience with a doctor’s diagnosis to understand illness.","zh":"病人把個人經驗與醫生診斷結合來理解疾病。"},{"en":"Combining experience with expert knowledge can make understanding stronger.","zh":"把經驗與專家知識結合可以令理解更有力。"},{"en":"The phrase shows interaction between different knowledge sources.","zh":"這個短語顯示不同知識來源之間的互動。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":17},{"front":"professional medical opinion","meaning":"專業醫學意見","examples":[{"en":"A professional medical opinion can confirm that someone is ill.","zh":"專業醫學意見可以確認某人生病。"},{"en":"Professional medical opinion is a judgement given by a qualified medical expert.","zh":"專業醫學意見是由合資格醫學專家給出的判斷。"},{"en":"Employers may require professional medical opinion before accepting extended sick leave.","zh":"僱主在接受長期病假前可能要求專業醫學意見。"},{"en":"Such opinion can transform personal symptoms into recognised illness.","zh":"這種意見可以把個人症狀轉化為被承認的疾病。"},{"en":"The phrase emphasises expert authority in medicine.","zh":"這個短語強調醫學中的專家權威。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":17},{"front":"realise that they are ill","meaning":"意識到自己生病","examples":[{"en":"Some people do not realise that they are ill until the disease is advanced.","zh":"有些人直到疾病已很嚴重才意識到自己生病。"},{"en":"To realise that they are ill means to become aware that they have a disease or medical condition.","zh":"意識到自己生病是指察覺自己有疾病或醫學狀況。"},{"en":"A person may fail to realise they are ill if symptoms are mild.","zh":"如果症狀輕微，一個人可能未能意識到自己生病。"},{"en":"Medical examination can help people realise that they are ill.","zh":"醫學檢查可以幫助人們意識到自己生病。"},{"en":"The phrase shows that illness may exist before awareness.","zh":"這個短語顯示疾病可能在意識到之前已存在。"}],"source":"Passage 2 Flash Cards 164 - Knowledge in medicine.pdf","sourcePage":17}],"ielts/reading/passage-2/Practice 165":[{"front":"renewable energy","meaning":"可再生能源","examples":[{"en":"Renewable energy can reduce pollution from electricity production.","zh":"可再生能源可以減少電力生產造成的污染。"},{"en":"Renewable energy is power from natural sources, such as sunlight, wind, water, or heat from the earth, that can be used again and again.","zh":"可再生能源是來自陽光、風、水或地熱等自然來源的能源，這些來源可以反覆使用。"},{"en":"A school may install solar panels to use renewable energy and lower its electricity bills.","zh":"學校可能安裝太陽能板，使用可再生能源並降低電費。"},{"en":"Using more renewable energy can reduce smoke, greenhouse gases, and dependence on coal.","zh":"使用更多可再生能源可以減少煙霧、溫室氣體和對煤炭的依賴。"},{"en":"Renewable energy is cleaner than fossil fuels, but it still needs good planning and reliable storage.","zh":"可再生能源比化石燃料更清潔，但仍需要良好規劃和可靠儲能。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":1},{"front":"an insight into","meaning":"對……的深入了解","examples":[{"en":"The passage gives an insight into the progress in renewable energy research.","zh":"這篇文章讓人深入了解可再生能源研究的進展。"},{"en":"An insight into something is a clear understanding of how it works or why it matters.","zh":"對某事的深入了解，是指清楚明白它如何運作或為何重要。"},{"en":"A diary can give readers an insight into a student’s daily worries and hopes.","zh":"日記可以讓讀者深入了解一名學生的日常憂慮和希望。"},{"en":"Interviewing workers can give managers an insight into why staff are unhappy.","zh":"訪問員工可以讓管理層深入了解員工為何不滿。"},{"en":"A good example gives learners an insight into a word, not just its spelling.","zh":"好例句能讓學習者深入了解一個詞，而不只是知道它的拼法。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":1},{"front":"progress in","meaning":"……方面的進展","examples":[{"en":"The article discusses progress in renewable energy research.","zh":"這篇文章討論可再生能源研究方面的進展。"},{"en":"Progress in something means improvement or development in that area over time.","zh":"……方面的進展，是指某個領域隨時間出現改善或發展。"},{"en":"Parents may notice progress in a child’s reading after several months of daily practice.","zh":"經過幾個月每天練習後，父母可能注意到孩子閱讀方面的進展。"},{"en":"Progress in public transport can reduce traffic and make commuting easier.","zh":"公共交通方面的進展可以減少交通擠塞，令通勤更容易。"},{"en":"Progress in one subject may be slow at first, but small gains still matter.","zh":"某一科方面的進展起初可能很慢，但小小進步仍然重要。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":1},{"front":"renewable energy research","meaning":"可再生能源研究","examples":[{"en":"Australia has made progress in renewable energy research.","zh":"澳洲在可再生能源研究方面取得了進展。"},{"en":"Renewable energy research studies how to produce cleaner power from sources such as wind, sunlight, waves, and underground heat.","zh":"可再生能源研究探討如何從風、陽光、海浪和地下熱能等來源生產更清潔的電力。"},{"en":"A university may receive funding for renewable energy research to improve solar panels.","zh":"大學可能獲得資助進行可再生能源研究，以改善太陽能板。"},{"en":"Renewable energy research can lead to cheaper electricity and less pollution.","zh":"可再生能源研究可以帶來更便宜的電力和更少污染。"},{"en":"Without renewable energy research, many clean technologies would remain too expensive or unreliable.","zh":"沒有可再生能源研究，許多清潔技術仍會太昂貴或不可靠。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":1},{"front":"the race is on for","meaning":"爭奪……的競賽已經展開","examples":[{"en":"The race is on for the ultimate goal of renewable energy.","zh":"爭奪可再生能源終極目標的競賽已經展開。"},{"en":"“The race is on for” means many people or groups are now competing to achieve something important first.","zh":"“The race is on for” 指許多人或團體正在競爭，希望率先達成重要目標。"},{"en":"The race is on for better batteries as more people buy electric cars.","zh":"隨着更多人購買電動車，爭奪更好電池的競賽已經展開。"},{"en":"When a disease spreads quickly, the race is on for a safe and effective vaccine.","zh":"當疾病迅速傳播時，爭奪安全有效疫苗的競賽便展開。"},{"en":"The phrase suggests urgency, competition, and a goal that many people want to reach.","zh":"這個片語帶有急迫感、競爭感，以及許多人想達成的目標。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":1},{"front":"the ultimate goal of","meaning":"……的終極目標","examples":[{"en":"The ultimate goal of renewable energy is cheap, clean electricity.","zh":"可再生能源的終極目標是便宜而清潔的電力。"},{"en":"The ultimate goal of something is its final and most important aim.","zh":"某事的終極目標，是指它最終而最重要的目的。"},{"en":"The ultimate goal of language learning is communication, not perfect memorisation of rules.","zh":"語言學習的終極目標是溝通，而不是完美背熟規則。"},{"en":"The ultimate goal of better transport is to help people move safely and easily.","zh":"改善交通的終極目標是幫助人安全而方便地出行。"},{"en":"A plan may have many small steps, but the ultimate goal shows what all the steps are for.","zh":"一個計劃可能有很多小步驟，但終極目標顯示這些步驟最終為了甚麼。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":1},{"front":"electricity production","meaning":"電力生產","examples":[{"en":"Renewable technologies aim to make electricity production cleaner.","zh":"可再生技術旨在令電力生產更清潔。"},{"en":"Electricity production is the process of generating power for homes, schools, businesses, and public services.","zh":"電力生產是為家庭、學校、企業和公共服務產生電力的過程。"},{"en":"A city may depend on gas, coal, wind, or solar energy for electricity production.","zh":"一個城市可能依靠天然氣、煤炭、風能或太陽能來進行電力生產。"},{"en":"Cleaner electricity production can reduce air pollution and improve public health.","zh":"更清潔的電力生產可以減少空氣污染並改善公共健康。"},{"en":"Electricity production is not only about making power; it also affects costs, jobs, and the environment.","zh":"電力生產不只是發電；它也影響成本、工作和環境。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":1},{"front":"at prices that are competitive with","meaning":"以可與……競爭的價格","examples":[{"en":"Researchers want electricity production at prices that are competitive with coal.","zh":"研究人員希望電力生產能以可與煤炭競爭的價格進行。"},{"en":"“At prices that are competitive with” means costing about the same as, or less than, another option.","zh":"“At prices that are competitive with” 指價格與另一選項差不多，甚至更低。"},{"en":"A small shop can survive if it sells fresh food at prices that are competitive with supermarkets.","zh":"如果小店以可與超級市場競爭的價格售賣新鮮食物，就能生存。"},{"en":"Solar power will spread faster if it is offered at prices that are competitive with traditional electricity.","zh":"如果太陽能以可與傳統電力競爭的價格提供，就會更快普及。"},{"en":"This phrase is useful when comparing cost, not just quality or popularity.","zh":"這個片語適合用來比較成本，而不只是比較質素或受歡迎程度。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":1},{"front":"coal-fired power stations","meaning":"燃煤發電站","examples":[{"en":"Renewable energy must compete with coal-fired power stations.","zh":"可再生能源必須與燃煤發電站競爭。"},{"en":"Coal-fired power stations are large facilities that burn coal to produce electricity.","zh":"燃煤發電站是燃燒煤炭來生產電力的大型設施。"},{"en":"A town near coal-fired power stations may worry about smoke and air quality.","zh":"靠近燃煤發電站的城鎮可能擔心煙霧和空氣質素。"},{"en":"Closing coal-fired power stations can reduce pollution but may also affect local jobs.","zh":"關閉燃煤發電站可以減少污染，但也可能影響本地工作。"},{"en":"Coal-fired power stations can produce steady electricity, but they create serious environmental costs.","zh":"燃煤發電站可以穩定發電，但會造成嚴重環境成本。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":1},{"front":"without coal’s pollution","meaning":"沒有煤炭污染","examples":[{"en":"The goal is to produce electricity without coal’s pollution.","zh":"目標是在沒有煤炭污染的情況下生產電力。"},{"en":"“Without coal’s pollution” means avoiding the dirty smoke, gases, and waste linked to burning coal.","zh":"“Without coal’s pollution” 指避免燃燒煤炭帶來的污煙、氣體和廢物。"},{"en":"Solar panels can help a building use electricity without coal’s pollution.","zh":"太陽能板可以幫助建築物使用沒有煤炭污染的電力。"},{"en":"Producing power without coal’s pollution can make the air safer for children and older people.","zh":"在沒有煤炭污染的情況下發電，可以令空氣對兒童和長者更安全。"},{"en":"The phrase shows the contrast between useful electricity and the environmental damage caused by coal.","zh":"這個片語顯示有用電力與煤炭造成的環境損害之間的對比。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":1},{"front":"aim to be the first to","meaning":"目標是率先……","examples":[{"en":"Some new technologies are aiming to be the first to replace coal.","zh":"一些新技術的目標是率先取代煤炭。"},{"en":"To aim to be the first to do something means to try to achieve it before all competitors.","zh":"To aim to be the first to do something 指努力比所有競爭者更早達成某事。"},{"en":"A company may aim to be the first to sell a cheap electric truck.","zh":"公司可能以率先銷售廉價電動貨車為目標。"},{"en":"Schools may aim to be the first to introduce a new teaching method in their district.","zh":"學校可能目標是在區內率先引入新的教學方法。"},{"en":"This phrase suggests ambition, competition, and a clear target.","zh":"這個片語帶有野心、競爭和明確目標的意思。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":1},{"front":"push coal from its position","meaning":"將煤炭從其地位推下來","examples":[{"en":"New technologies may push coal from its position as the main energy source.","zh":"新技術可能將煤炭從主要能源的地位推下來。"},{"en":"To push coal from its position means to replace coal or reduce its importance in the energy market.","zh":"To push coal from its position 指取代煤炭，或降低煤炭在能源市場中的重要性。"},{"en":"If solar power becomes cheaper, it may push coal from its position in many countries.","zh":"如果太陽能變得更便宜，它可能在許多國家將煤炭從其地位推下來。"},{"en":"Strong pollution rules can help push coal from its position by making dirty power less attractive.","zh":"嚴格污染規則可以令高污染電力較不吸引，從而幫助將煤炭從其地位推下來。"},{"en":"The phrase suggests that coal is currently powerful, but another technology may take its place.","zh":"這個片語暗示煤炭目前很有影響力，但另一種技術可能取代它。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":2},{"front":"chief source of electricity","meaning":"主要電力來源","examples":[{"en":"Coal is Australia’s chief source of electricity.","zh":"煤炭是澳洲的主要電力來源。"},{"en":"The chief source of electricity is the main way a country or area produces its power.","zh":"主要電力來源是指一個國家或地區生產電力的主要方式。"},{"en":"In some sunny regions, solar energy may become the chief source of electricity.","zh":"在一些陽光充足的地區，太陽能可能成為主要電力來源。"},{"en":"If a country depends on one chief source of electricity, a supply problem can affect many people.","zh":"如果一個國家依賴單一主要電力來源，供應問題可能影響很多人。"},{"en":"The phrase is useful for describing the most important energy source, not a small one.","zh":"這個片語適合描述最重要的能源來源，而不是小型來源。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":2},{"front":"at the moment","meaning":"目前","examples":[{"en":"At the moment, wind technology is the front-runner in renewable energy.","zh":"目前，風能技術是可再生能源中的領先者。"},{"en":"At the moment means now, or during the present period.","zh":"At the moment 指現在，或目前這段時間。"},{"en":"At the moment, many students are preparing for final exams.","zh":"目前，許多學生正在準備期末考試。"},{"en":"A shop may be busy at the moment because it is lunchtime.","zh":"一間商店目前可能很忙，因為現在是午餐時間。"},{"en":"This phrase often describes a temporary situation that may change later.","zh":"這個片語常用來描述一個之後可能改變的暫時情況。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":2},{"front":"front-runner in","meaning":"……中的領先者","examples":[{"en":"Wind technology is the front-runner in renewable energy.","zh":"風能技術是可再生能源中的領先者。"},{"en":"A front-runner in a field is the leading person, company, idea, or technology.","zh":"某領域中的 front-runner 是指領先的人、公司、想法或技術。"},{"en":"A student with the highest marks may be the front-runner in a scholarship competition.","zh":"成績最高的學生可能是獎學金競爭中的領先者。"},{"en":"A company can become the front-runner in online delivery if customers trust its service.","zh":"如果顧客信任某公司的服務，它可以成為網上送貨中的領先者。"},{"en":"The phrase suggests that others are competing, but one is clearly ahead.","zh":"這個片語暗示有其他競爭者，但其中一方明顯領先。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":2},{"front":"wind technology","meaning":"風能技術","examples":[{"en":"Wind technology is currently the leading form of renewable energy.","zh":"風能技術目前是可再生能源的主要形式。"},{"en":"Wind technology uses the movement of air to generate electricity, usually through wind turbines.","zh":"風能技術利用空氣流動來發電，通常透過風力渦輪機實現。"},{"en":"A coastal town may use wind technology because strong winds are common there.","zh":"沿海城鎮可能使用風能技術，因為那裡經常有強風。"},{"en":"Better wind technology can lower electricity costs and make turbines more reliable.","zh":"更好的風能技術可以降低電力成本，並令渦輪機更可靠。"},{"en":"Wind technology works best in suitable locations, so careful site selection is important.","zh":"風能技術在合適地點最有效，所以仔細選址很重要。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":2},{"front":"according to","meaning":"根據","examples":[{"en":"According to Peter Bergin, windmill design has not changed dramatically.","zh":"根據Peter Bergin的說法，風車設計多年來沒有劇烈改變。"},{"en":"According to means “as said, written, or reported by” a person, study, rule, or source.","zh":"According to 指「根據」某人、研究、規則或來源所說、所寫或所報告的內容。"},{"en":"According to the timetable, the next train leaves at 8:15.","zh":"根據時間表，下一班火車在8點15分開出。"},{"en":"According to the doctor, regular sleep can improve concentration.","zh":"根據醫生的說法，規律睡眠可以改善專注力。"},{"en":"This phrase helps show where information comes from, but it does not prove the information is true.","zh":"這個片語有助顯示資訊來源，但不代表資訊一定正確。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":2},{"front":"leading wind energy companies","meaning":"主要風能公司","examples":[{"en":"Australian Hydro is one of Australia’s leading wind energy companies.","zh":"Australian Hydro是澳洲主要風能公司之一。"},{"en":"Leading wind energy companies are major businesses that develop, build, or operate wind power projects.","zh":"主要風能公司是開發、興建或營運風力發電項目的大型企業。"},{"en":"Leading wind energy companies may test new turbine designs before smaller firms can afford them.","zh":"主要風能公司可能在較小公司負擔得起之前，先測試新的渦輪設計。"},{"en":"Government support can help leading wind energy companies expand into remote areas.","zh":"政府支援可以幫助主要風能公司擴展到偏遠地區。"},{"en":"These companies matter because their decisions can shape the future of clean electricity.","zh":"這些公司很重要，因為它們的決定可以塑造清潔電力的未來。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":2},{"front":"dramatic changes in","meaning":"……方面的重大變化","examples":[{"en":"There have been no dramatic changes in windmill design for many years.","zh":"多年來，風車設計方面沒有重大變化。"},{"en":"Dramatic changes in something are large, clear changes that people can easily notice.","zh":"……方面的重大變化，是指大而明顯、容易被人注意到的改變。"},{"en":"A school may see dramatic changes in behaviour after mobile phones are banned in class.","zh":"學校在課堂禁用手機後，可能看見學生行為方面的重大變化。"},{"en":"Dramatic changes in rent can force families to move away from their neighbourhood.","zh":"租金方面的重大變化可能迫使家庭搬離自己的社區。"},{"en":"The phrase is stronger than “small changes” or “gradual improvements”.","zh":"這個片語比「小改變」或「逐步改善」更強烈。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":2},{"front":"windmill design","meaning":"風車設計；風力渦輪設計","examples":[{"en":"Windmill design has improved gradually over many years.","zh":"風車設計多年來逐步改善。"},{"en":"Windmill design is the way wind turbines are shaped, built, and arranged to capture wind efficiently.","zh":"風車設計是指風力渦輪如何被塑形、建造和安排，以有效捕捉風力。"},{"en":"Better windmill design can make turbines quieter and safer for nearby communities.","zh":"更好的風車設計可以令渦輪更安靜，並對附近社區更安全。"},{"en":"Small improvements in windmill design can reduce repair costs and increase electricity output.","zh":"風車設計上的小改進可以降低維修成本並增加發電量。"},{"en":"Windmill design matters because a small change in the blades can affect performance.","zh":"風車設計很重要，因為葉片的小改動也可能影響表現。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":2},{"front":"cumulative effects","meaning":"累積效應","examples":[{"en":"The cumulative effects of small improvements have reduced costs.","zh":"小改進的累積效應已降低成本。"},{"en":"Cumulative effects are the total results that build up after many small changes happen over time.","zh":"累積效應是指許多小改變隨時間累積後形成的總體結果。"},{"en":"The cumulative effects of daily reading can greatly improve a student’s vocabulary.","zh":"每天閱讀的累積效應可以大大改善學生的詞彙量。"},{"en":"The cumulative effects of poor sleep may include stress, weak memory, and low energy.","zh":"睡眠不足的累積效應可能包括壓力、記憶力弱和精力低。"},{"en":"This phrase helps explain why small actions can become important when repeated.","zh":"這個片語有助解釋為何小行動重複後會變得重要。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":2},{"front":"numerous small improvements","meaning":"許多小改進","examples":[{"en":"Numerous small improvements have had a major impact on cost.","zh":"許多小改進對成本產生了重大影響。"},{"en":"Numerous small improvements are many little changes that together make something better.","zh":"許多小改進是指很多細小改變合起來令某事變得更好。"},{"en":"A teacher may make numerous small improvements to a lesson by adding examples, pauses, and clearer questions.","zh":"老師可能透過加入例子、停頓和更清晰問題，對課堂作出許多小改進。"},{"en":"Numerous small improvements in a factory can reduce waste and save money.","zh":"工廠中的許多小改進可以減少浪費並節省金錢。"},{"en":"The phrase shows that progress does not always come from one big invention.","zh":"這個片語顯示，進步不一定來自一項大型發明。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":2},{"front":"have a major impact on","meaning":"對……有重大影響","examples":[{"en":"Small design improvements have had a major impact on cost.","zh":"小型設計改進對成本有重大影響。"},{"en":"To have a major impact on something means to affect it strongly or significantly.","zh":"To have a major impact on something 指對某事有強烈或重要影響。"},{"en":"A good teacher can have a major impact on a child’s confidence.","zh":"好老師可以對孩子的信心有重大影響。"},{"en":"High rent can have a major impact on where young workers choose to live.","zh":"高租金可以對年輕工作者選擇住在哪裡有重大影響。"},{"en":"The phrase is stronger than “affect” because it suggests a large or important effect.","zh":"這個片語比 “affect” 更強，因為它暗示影響很大或很重要。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":3},{"front":"reap the benefits of","meaning":"享受……的成果","examples":[{"en":"Australia is reaping the benefits of 30 years of European research.","zh":"澳洲正在享受歐洲30年研究的成果。"},{"en":"To reap the benefits of something means to enjoy good results after effort, investment, or learning.","zh":"To reap the benefits of something 指在努力、投資或學習之後享受良好結果。"},{"en":"Students who revise regularly often reap the benefits of their hard work in exams.","zh":"定期溫習的學生常在考試中享受自己努力的成果。"},{"en":"A city may reap the benefits of better transport when fewer people drive.","zh":"當較少人駕車時，城市可能享受改善交通的成果。"},{"en":"This phrase often suggests that the reward comes after earlier work.","zh":"這個片語常暗示回報來自較早之前的努力。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":3},{"front":"without having to","meaning":"無需","examples":[{"en":"Australia has benefited without having to make the same mistakes.","zh":"澳洲受益了，而無需犯同樣錯誤。"},{"en":"Without having to means doing or gaining something while avoiding a difficult or unnecessary action.","zh":"Without having to 指做到或得到某事，同時避免困難或不必要的行動。"},{"en":"Online banking lets people pay bills without having to visit a bank branch.","zh":"網上銀行讓人無需前往銀行分行也能繳交帳單。"},{"en":"Students can learn from model answers without having to repeat every mistake themselves.","zh":"學生可以從範文學習，而無需自己重複每一個錯誤。"},{"en":"This phrase is useful when one benefit comes with less effort, risk, or inconvenience.","zh":"這個片語適合描述某項好處帶來時，所需努力、風險或不便較少。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":3},{"front":"make the same mistakes","meaning":"犯同樣錯誤","examples":[{"en":"Australia did not have to make the same mistakes as European researchers.","zh":"澳洲不需要犯歐洲研究人員曾犯的同樣錯誤。"},{"en":"To make the same mistakes means to repeat errors that other people have already made.","zh":"To make the same mistakes 指重複其他人已經犯過的錯誤。"},{"en":"A new restaurant can study failed businesses so it does not make the same mistakes.","zh":"新餐廳可以研究失敗企業，避免犯同樣錯誤。"},{"en":"If students read feedback carefully, they are less likely to make the same mistakes again.","zh":"如果學生仔細閱讀回饋，他們較不可能再次犯同樣錯誤。"},{"en":"The phrase often shows the value of learning from other people’s experience.","zh":"這個片語常顯示從他人經驗中學習的價值。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":3},{"front":"be produced from","meaning":"由……生產","examples":[{"en":"Electricity can be produced from coal at around 4 cents per kilowatt-hour.","zh":"電力可以由煤炭生產，成本大約為每千瓦時4仙。"},{"en":"To be produced from something means to be made or generated using that material or source.","zh":"To be produced from something 指用某種材料或來源製成或產生。"},{"en":"Paper can be produced from wood, but recycled paper uses old paper instead.","zh":"紙可以由木材生產，但再造紙則使用舊紙。"},{"en":"Electricity produced from sunlight creates less air pollution than electricity produced from coal.","zh":"由陽光生產的電力，比由煤炭生產的電力造成較少空氣污染。"},{"en":"This phrase is often used for materials, food, energy, and manufactured goods.","zh":"這個片語常用於材料、食物、能源和製成品。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":3},{"front":"at around","meaning":"大約以；大約在","examples":[{"en":"Coal electricity can be produced at around 4 cents per kilowatt-hour.","zh":"煤電可以大約以每千瓦時4仙的成本生產。"},{"en":"At around means approximately, especially when the exact number is not necessary.","zh":"At around 指大約，尤其在不需要精確數字時使用。"},{"en":"The meeting will start at around 3 p.m., so people should arrive a little earlier.","zh":"會議大約在下午3點開始，所以人們應早一點到達。"},{"en":"A basic lunch near the school costs at around fifty dollars.","zh":"學校附近一份基本午餐大約以50元的價格售賣。"},{"en":"This phrase is useful when giving a rough time, price, amount, or measurement.","zh":"這個片語適合用來表示大概時間、價格、數量或測量值。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":3},{"front":"cents per kilowatt-hour","meaning":"每千瓦時多少仙","examples":[{"en":"Wind power costs around 7 cents per kilowatt-hour.","zh":"風力發電成本約為每千瓦時7仙。"},{"en":"Cents per kilowatt-hour is a way to describe the cost of each unit of electricity used or produced.","zh":"Cents per kilowatt-hour 是描述每一單位電力使用或生產成本的方法。"},{"en":"If electricity costs 20 cents per kilowatt-hour, using more appliances will raise the bill.","zh":"如果電力成本是每千瓦時20仙，使用更多電器會令帳單增加。"},{"en":"Energy companies compare cents per kilowatt-hour to show which source is cheaper.","zh":"能源公司會比較每千瓦時多少仙，以顯示哪種來源較便宜。"},{"en":"This measure helps people compare electricity prices more clearly than total bills alone.","zh":"這個單位比只看總帳單更能幫助人清楚比較電價。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":3},{"front":"environmental costs","meaning":"環境成本","examples":[{"en":"The low price of coal ignores environmental costs.","zh":"煤炭的低價格忽略了環境成本。"},{"en":"Environmental costs are the damage to air, water, land, health, or climate caused by an activity.","zh":"環境成本是指某項活動對空氣、水、土地、健康或氣候造成的損害。"},{"en":"Cheap plastic bags may have high environmental costs if they become waste in the sea.","zh":"廉價膠袋如果變成海洋垃圾，可能有很高的環境成本。"},{"en":"When environmental costs are included, a dirty fuel may not be truly cheap.","zh":"當環境成本被計算在內，高污染燃料可能並不真正便宜。"},{"en":"This phrase reminds us that a low market price may hide real damage.","zh":"這個片語提醒我們，低市場價格可能隱藏真正的損害。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":3},{"front":"be ignored","meaning":"被忽略","examples":[{"en":"Coal power seems cheap only if environmental costs are ignored.","zh":"只有在環境成本被忽略時，煤電才看似便宜。"},{"en":"To be ignored means to receive no attention, even though attention may be needed.","zh":"To be ignored 指即使可能需要注意，某事或某人仍沒有得到注意。"},{"en":"If warning signs are ignored, a small health problem may become serious.","zh":"如果警告訊號被忽略，小健康問題可能變得嚴重。"},{"en":"Students feel discouraged when their questions are ignored in class.","zh":"當學生的問題在課堂上被忽略，他們會感到氣餒。"},{"en":"Important costs should not be ignored simply because they are hard to measure.","zh":"重要成本不應只因難以量度而被忽略。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":3},{"front":"make it difficult for","meaning":"令……難以","examples":[{"en":"Cheap electricity makes it difficult for renewable energy to compete.","zh":"便宜電力令可再生能源難以競爭。"},{"en":"To make it difficult for someone or something means to create a problem or barrier for them.","zh":"To make it difficult for someone or something 指為某人或某事製造問題或障礙。"},{"en":"Heavy rain can make it difficult for students to get to school on time.","zh":"大雨可能令學生難以準時上學。"},{"en":"High rent makes it difficult for small shops to survive in busy areas.","zh":"高租金令小店難以在繁忙地區生存。"},{"en":"This phrase is useful when explaining why an action, goal, or situation becomes harder.","zh":"這個片語適合用來解釋為何某個行動、目標或情況變得更困難。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":3},{"front":"compete","meaning":"競爭","examples":[{"en":"Renewable energy must compete with cheap coal electricity.","zh":"可再生能源必須與便宜煤電競爭。"},{"en":"To compete means to try to win, succeed, or be chosen against others.","zh":"To compete 指與他人比較，努力勝出、成功或被選中。"},{"en":"Two cafés on the same street compete for the same lunchtime customers.","zh":"同一條街上的兩間咖啡店會爭取同一批午餐顧客。"},{"en":"Students may compete for limited university places.","zh":"學生可能競爭有限的大學學位。"},{"en":"Competition can improve quality, but it can also create pressure.","zh":"競爭可以提高質素，但也可能造成壓力。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":3},{"front":"nevertheless","meaning":"然而；儘管如此","examples":[{"en":"Nevertheless, wind power has become much cheaper.","zh":"然而，風力發電已變得便宜得多。"},{"en":"Nevertheless means “despite what was just said” and introduces a contrasting point.","zh":"Nevertheless 指「儘管剛才所說的事情如此」，用來引出相反或轉折的重點。"},{"en":"The exam was difficult; nevertheless, many students passed.","zh":"考試很難；然而，許多學生都合格了。"},{"en":"The shop is small; nevertheless, it attracts many loyal customers.","zh":"這間店很小；儘管如此，它吸引了很多忠實顧客。"},{"en":"This word is useful when you want to admit one fact but still show another important fact.","zh":"當你想承認一個事實，但仍展示另一個重要事實時，這個詞很有用。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":4},{"front":"production cost","meaning":"生產成本","examples":[{"en":"The production cost of wind power has fallen sharply.","zh":"風力發電的生產成本已大幅下降。"},{"en":"Production cost is the money needed to make or generate a product or service.","zh":"生產成本是製造產品或提供服務所需的金錢。"},{"en":"If the production cost of bread rises, bakeries may raise their prices.","zh":"如果麵包的生產成本上升，麵包店可能會加價。"},{"en":"Lower production costs can make clean technology more affordable for ordinary families.","zh":"較低的生產成本可以令清潔技術對普通家庭更負擔得起。"},{"en":"This phrase focuses on the cost of making something, not the price customers finally pay.","zh":"這個片語著重製造某物的成本，而不是顧客最終支付的價格。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":4},{"front":"one-fifth of what it was","meaning":"是過去的五分之一","examples":[{"en":"The production cost of wind power is one-fifth of what it was 20 years ago.","zh":"風力發電的生產成本是20年前的五分之一。"},{"en":"One-fifth of what it was means the amount is now only 20% of the earlier amount.","zh":"One-fifth of what it was 指現在的數量只有以前的20%。"},{"en":"After a sale, the price of the old model was one-fifth of what it was last month.","zh":"減價後，舊型號的價格是上個月的五分之一。"},{"en":"If waste is one-fifth of what it was, the factory has reduced it greatly.","zh":"如果廢物量是過去的五分之一，工廠已大幅減少廢物。"},{"en":"This phrase shows a large decrease by comparing the present with the past.","zh":"這個片語透過比較現在與過去，顯示大幅下降。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":4},{"front":"wind power","meaning":"風力發電","examples":[{"en":"Wind power is cheaper than it was 20 years ago.","zh":"風力發電比20年前便宜。"},{"en":"Wind power is electricity generated by using moving air to turn turbines.","zh":"風力發電是利用流動空氣轉動渦輪而產生的電力。"},{"en":"A farm in a windy area may sell wind power to the local electricity grid.","zh":"位於多風地區的農場可能把風力發電出售給本地電網。"},{"en":"Wind power can reduce pollution, but it depends on weather and location.","zh":"風力發電可以減少污染，但它依賴天氣和地點。"},{"en":"Wind power is one clean energy option, not a complete solution on its own.","zh":"風力發電是一種清潔能源選項，但單靠它並不是完整解決方案。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":4},{"front":"wind monitoring stations","meaning":"風力監測站","examples":[{"en":"Australian Hydro has dozens of wind monitoring stations across Australia.","zh":"Australian Hydro在澳洲各地有數十個風力監測站。"},{"en":"Wind monitoring stations are places where equipment measures wind speed and direction over time.","zh":"風力監測站是安裝設備、長時間測量風速和風向的地方。"},{"en":"A company may build wind monitoring stations before deciding where to place turbines.","zh":"公司在決定在哪裡設置渦輪前，可能先建立風力監測站。"},{"en":"Wind monitoring stations can prevent costly mistakes by showing whether a site is truly windy enough.","zh":"風力監測站可以顯示地點是否真的有足夠風力，從而避免昂貴錯誤。"},{"en":"These stations collect data first, so energy projects can be planned more carefully.","zh":"這些監測站先收集數據，讓能源項目可以更仔細地規劃。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":4},{"front":"across Australia","meaning":"遍佈澳洲","examples":[{"en":"Australian Hydro operates monitoring stations across Australia.","zh":"Australian Hydro營運遍佈澳洲的監測站。"},{"en":"Across Australia means in many different parts of Australia, not just one place.","zh":"Across Australia 指在澳洲多個不同地區，而不只是某一個地方。"},{"en":"A charity may open food banks across Australia to help families in several states.","zh":"慈善機構可能在澳洲各地開設食物銀行，幫助多個州的家庭。"},{"en":"Heavy rain across Australia can affect farming, transport, and electricity supply.","zh":"遍佈澳洲的大雨可能影響農業、交通和電力供應。"},{"en":"The phrase gives a wide national scale to an action or situation.","zh":"這個片語為行動或情況帶出全國性的廣泛範圍。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":4},{"front":"as part of its aim to","meaning":"作為其……目標的一部分","examples":[{"en":"The company has monitoring stations as part of its aim to expand.","zh":"這間公司設有監測站，作為其擴展目標的一部分。"},{"en":"As part of its aim to means that an action helps support a larger goal.","zh":"As part of its aim to 指某個行動是為了支持一個更大的目標。"},{"en":"A school may offer free tutoring as part of its aim to improve exam results.","zh":"學校可能提供免費補習，作為其改善考試成績目標的一部分。"},{"en":"A city may plant more trees as part of its aim to reduce heat in summer.","zh":"城市可能種植更多樹木，作為其減少夏季高溫目標的一部分。"},{"en":"This phrase connects a specific action with a wider plan.","zh":"這個片語把具體行動與更廣泛計劃連接起來。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":4},{"front":"pre-eminent renewable energy company","meaning":"頂尖可再生能源公司","examples":[{"en":"Australian Hydro aims to become Australia’s pre-eminent renewable energy company.","zh":"Australian Hydro旨在成為澳洲頂尖可再生能源公司。"},{"en":"A pre-eminent renewable energy company is a leading company that stands above most others in clean energy.","zh":"頂尖可再生能源公司是指在清潔能源方面領先、多數公司難以相比的企業。"},{"en":"A firm may become pre-eminent by building reliable projects, lowering costs, and earning public trust.","zh":"公司可能透過建立可靠項目、降低成本和贏得公眾信任而變得頂尖。"},{"en":"To become pre-eminent, a company must usually show strong results over many years.","zh":"要成為頂尖公司，企業通常必須多年展示強勁成果。"},{"en":"This phrase is more formal than “top company” and suggests high status in the industry.","zh":"這個片語比 “top company” 更正式，並暗示在行業中地位很高。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":4},{"front":"despite all these developments","meaning":"儘管有這些發展","examples":[{"en":"Despite all these developments, Australia is not at the global cutting edge in wind power.","zh":"儘管有這些發展，澳洲在風力發電方面仍未達到全球最前沿。"},{"en":"Despite all these developments means that even after these improvements or changes, the following point is still true.","zh":"Despite all these developments 指即使已有這些改善或變化，接下來的重點仍然成立。"},{"en":"Despite all these developments, some rural areas still have poor internet access.","zh":"儘管有這些發展，一些鄉郊地區仍然網絡不佳。"},{"en":"Despite all these developments, many workers still cannot afford housing near their jobs.","zh":"儘管有這些發展，許多工人仍負擔不起工作地點附近的住房。"},{"en":"This phrase introduces a contrast between progress and a remaining problem.","zh":"這個片語引出進展與仍然存在的問題之間的對比。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":4},{"front":"alternative energy","meaning":"替代能源","examples":[{"en":"Wind power remains one area of alternative energy.","zh":"風力發電仍是替代能源的一個範疇。"},{"en":"Alternative energy means energy from sources other than traditional fossil fuels such as coal, oil, and gas.","zh":"替代能源是指來自煤炭、石油和天然氣等傳統化石燃料以外來源的能源。"},{"en":"Solar panels, wind turbines, and wave machines are examples of alternative energy.","zh":"太陽能板、風力渦輪和海浪發電機都是替代能源例子。"},{"en":"Interest in alternative energy rises when fuel prices increase or pollution becomes serious.","zh":"當燃料價格上升或污染變得嚴重時，人們對替代能源的興趣會增加。"},{"en":"Alternative energy is often discussed as a cleaner replacement for older energy systems.","zh":"替代能源常被討論為較清潔、可取代舊能源系統的選項。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":4},{"front":"nowhere near","meaning":"遠遠未達到","examples":[{"en":"Australia is nowhere near the global cutting edge in wind power.","zh":"澳洲在風力發電方面遠遠未達到全球最前沿。"},{"en":"Nowhere near means very far from reaching a level, amount, place, or standard.","zh":"Nowhere near 指離某個水平、數量、地方或標準非常遠。"},{"en":"A beginner who knows ten words is nowhere near fluent in a language.","zh":"只認識十個詞的初學者遠遠未達到語言流利。"},{"en":"The project is nowhere near finished if the main design has not been approved.","zh":"如果主要設計仍未獲批，項目就遠遠未完成。"},{"en":"This phrase is strong and shows that the gap is large, not small.","zh":"這個片語語氣強烈，表示差距很大，而不是很小。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":4},{"front":"the global cutting edge","meaning":"全球最前沿","examples":[{"en":"Australia is not at the global cutting edge in wind power.","zh":"澳洲在風力發電方面並不處於全球最前沿。"},{"en":"The global cutting edge is the most advanced level of research, technology, or practice in the world.","zh":"全球最前沿是指世界上研究、技術或實踐的最高級、最先進水平。"},{"en":"A hospital at the global cutting edge may use treatments that few other hospitals can offer.","zh":"處於全球最前沿的醫院可能使用很少其他醫院能提供的治療。"},{"en":"A country can reach the global cutting edge by investing heavily in science and training.","zh":"一個國家可以透過大量投資科學和培訓，達到全球最前沿。"},{"en":"The phrase suggests world-leading innovation, not ordinary progress.","zh":"這個片語暗示世界領先的創新，而不是普通進步。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":5},{"front":"replicate European designs","meaning":"複製歐洲設計","examples":[{"en":"Australia is mostly replicating European designs in wind power.","zh":"澳洲在風力發電方面大多是在複製歐洲設計。"},{"en":"To replicate European designs means to copy or reproduce designs first developed in Europe.","zh":"To replicate European designs 指複製或重現最初在歐洲開發的設計。"},{"en":"A company may replicate European designs if they have already been tested successfully.","zh":"如果歐洲設計已經成功測試，公司可能會複製歐洲設計。"},{"en":"Replicating European designs can save time, but it may limit local innovation.","zh":"複製歐洲設計可以節省時間，但可能限制本地創新。"},{"en":"The phrase suggests imitation rather than original invention.","zh":"這個片語暗示模仿，而不是原創發明。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":5},{"front":"currently lead the way","meaning":"目前領先","examples":[{"en":"Wind may currently lead the way in renewable energy.","zh":"風能目前可能在可再生能源方面領先。"},{"en":"To currently lead the way means to be the most successful or advanced option at the present time.","zh":"To currently lead the way 指目前是最成功或最先進的選項。"},{"en":"Online learning platforms currently lead the way in flexible adult education.","zh":"網上學習平台目前在靈活成人教育方面領先。"},{"en":"A hospital may currently lead the way in using robots for surgery.","zh":"醫院目前可能在使用機械人做手術方面領先。"},{"en":"This phrase shows present leadership, but it does not mean the leader will stay first forever.","zh":"這個片語表示目前領先，但不代表領先者會永遠保持第一。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":5},{"front":"technologies under development","meaning":"正在開發中的技術","examples":[{"en":"Some technologies under development may have more potential.","zh":"一些正在開發中的技術可能有更大潛力。"},{"en":"Technologies under development are technologies that are still being researched, tested, or improved.","zh":"正在開發中的技術是指仍在研究、測試或改善的技術。"},{"en":"A new medical device under development may not be ready for hospitals yet.","zh":"一項正在開發中的新醫療設備可能尚未準備好供醫院使用。"},{"en":"Technologies under development can fail, but they can also become major breakthroughs.","zh":"正在開發中的技術可能失敗，但也可能成為重大突破。"},{"en":"The phrase suggests promise, uncertainty, and ongoing work.","zh":"這個片語暗示潛力、不確定性和持續工作。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":5},{"front":"have more potential","meaning":"有更大潛力","examples":[{"en":"Several newer technologies may have more potential than wind power.","zh":"幾項較新的技術可能比風力發電有更大潛力。"},{"en":"To have more potential means to have a greater chance of becoming useful, successful, or important in the future.","zh":"To have more potential 指將來變得有用、成功或重要的可能性更大。"},{"en":"A quiet student may have more potential than their exam score first suggests.","zh":"一名安靜的學生可能比最初的考試成績所顯示的更有潛力。"},{"en":"A small business may have more potential if it solves a real problem for customers.","zh":"如果小企業能為顧客解決真正問題，它可能有更大潛力。"},{"en":"Potential is about future possibility, not guaranteed success.","zh":"潛力關乎未來可能性，而不是保證成功。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":5},{"front":"in several cases","meaning":"在幾個情況下","examples":[{"en":"In several cases, Australia is at the forefront of global research.","zh":"在幾個情況下，澳洲處於全球研究前沿。"},{"en":"In several cases means in a number of situations, examples, or instances.","zh":"In several cases 指在若干情況、例子或個案中。"},{"en":"In several cases, students improved after teachers gave clearer feedback.","zh":"在幾個情況下，老師給予更清晰回饋後，學生有所改善。"},{"en":"In several cases, small clinics solved problems faster than large hospitals.","zh":"在幾個情況下，小型診所比大型醫院更快解決問題。"},{"en":"This phrase does not mean “always”; it means there are multiple examples.","zh":"這個片語不等於「總是」；它表示有多個例子。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":5},{"front":"at the forefront of","meaning":"處於……前沿","examples":[{"en":"Australia is at the forefront of global research in some energy technologies.","zh":"澳洲在一些能源技術的全球研究中處於前沿。"},{"en":"To be at the forefront of something means to be among the most advanced or active leaders in that area.","zh":"To be at the forefront of something 指在某領域中屬於最先進或最積極的領先者之一。"},{"en":"A university may be at the forefront of cancer research if it develops new treatments.","zh":"如果大學開發新治療方法，它可能處於癌症研究前沿。"},{"en":"Cities at the forefront of transport reform often test new bus and rail systems first.","zh":"處於交通改革前沿的城市，常最先測試新的巴士和鐵路系統。"},{"en":"The phrase suggests leadership, innovation, and strong involvement.","zh":"這個片語暗示領導地位、創新和積極參與。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":5},{"front":"global research","meaning":"全球研究","examples":[{"en":"Australia leads global research in some renewable technologies.","zh":"澳洲在一些可再生技術的全球研究中領先。"},{"en":"Global research is research carried out, shared, or recognised across many countries.","zh":"全球研究是指在多個國家進行、分享或獲認可的研究。"},{"en":"Global research on climate change helps governments understand rising temperatures.","zh":"氣候變化的全球研究幫助政府理解氣溫上升。"},{"en":"Universities join global research projects when one country alone cannot collect enough data.","zh":"當單一國家無法收集足夠數據時，大學會加入全球研究項目。"},{"en":"This phrase shows that the work matters beyond one local area.","zh":"這個片語顯示該工作的重要性超越單一地區。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":5},{"front":"site-specific","meaning":"受地點限制的；特定地點適用的","examples":[{"en":"Some renewable technologies are very site-specific.","zh":"一些可再生技術非常受地點限制。"},{"en":"Site-specific means suitable only for particular places because of local conditions.","zh":"Site-specific 指由於本地條件，只適合特定地方。"},{"en":"A wave-power machine is site-specific because it needs strong and regular waves.","zh":"海浪發電機受地點限制，因為它需要強而穩定的海浪。"},{"en":"Site-specific projects may fail if planners ignore wind, sunlight, water, or land conditions.","zh":"如果規劃者忽略風、陽光、水或土地條件，受地點限制的項目可能失敗。"},{"en":"The phrase reminds us that a good technology in one place may not work everywhere.","zh":"這個片語提醒我們，在一個地方有效的技術未必到處適用。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":5},{"front":"dominant market players","meaning":"主導市場者","examples":[{"en":"Some site-specific technologies may never become dominant market players.","zh":"一些受地點限制的技術可能永遠不會成為主導市場者。"},{"en":"Dominant market players are companies, products, or technologies that control a large share of a market.","zh":"主導市場者是指控制市場很大份額的公司、產品或技術。"},{"en":"Large supermarket chains are dominant market players in many city shopping districts.","zh":"大型超市連鎖店是許多城市購物區的主導市場者。"},{"en":"A technology may fail to become a dominant market player if it is too expensive or difficult to use.","zh":"如果技術太昂貴或難以使用，它可能無法成為主導市場者。"},{"en":"This phrase is about market power, not just technical quality.","zh":"這個片語關乎市場力量，而不只是技術質素。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":5},{"front":"on the other hand","meaning":"另一方面","examples":[{"en":"On the other hand, newer developments may provide more reliable power.","zh":"另一方面，較新的發展可能提供更可靠的電力。"},{"en":"On the other hand introduces a different or contrasting point.","zh":"On the other hand 用來引出不同或相反的重點。"},{"en":"The flat is expensive; on the other hand, it is close to school and work.","zh":"這間公寓很貴；另一方面，它很接近學校和工作地點。"},{"en":"Online learning is flexible; on the other hand, some students miss face-to-face support.","zh":"網上學習很靈活；另一方面，有些學生會懷念面對面支援。"},{"en":"This phrase helps balance an argument by showing another side.","zh":"這個片語透過展示另一面，幫助平衡論點。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":5},{"front":"capable of","meaning":"有能力","examples":[{"en":"Newer technologies are capable of providing more reliable power.","zh":"較新的技術有能力提供更可靠的電力。"},{"en":"Capable of means having the ability, skill, or power to do something.","zh":"Capable of 指有能力、技能或力量去做某事。"},{"en":"A well-trained nurse is capable of handling emergencies calmly.","zh":"受過良好訓練的護士有能力冷靜處理緊急情況。"},{"en":"A small phone is capable of taking high-quality photos if it has a good camera.","zh":"如果相機好，小型手機也有能力拍攝高質素相片。"},{"en":"This phrase suggests real ability, not just hope or intention.","zh":"這個片語暗示真正能力，而不只是希望或意圖。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":6},{"front":"provide more reliable power","meaning":"提供更可靠的電力","examples":[{"en":"Newer developments may provide more reliable power than windmills.","zh":"較新的發展可能比風車提供更可靠的電力。"},{"en":"To provide more reliable power means to supply electricity more steadily and with fewer interruptions.","zh":"To provide more reliable power 指更穩定、較少中斷地供應電力。"},{"en":"Batteries can help provide more reliable power when solar panels stop working at night.","zh":"當太陽能板在夜間停止發電時，電池可以幫助提供更可靠的電力。"},{"en":"Hospitals need systems that provide more reliable power because equipment must keep running.","zh":"醫院需要提供更可靠電力的系統，因為設備必須持續運作。"},{"en":"This phrase is important when comparing energy sources that depend on changing weather.","zh":"比較依賴天氣變化的能源來源時，這個片語很重要。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":6},{"front":"avoid the major criticism of","meaning":"避免對……的主要批評","examples":[{"en":"Newer technologies may avoid the major criticism of windmills.","zh":"較新的技術可能避免對風車的主要批評。"},{"en":"To avoid the major criticism of something means to escape its biggest weakness or objection.","zh":"To avoid the major criticism of something 指避開某事最大的弱點或反對意見。"},{"en":"An online course with live feedback may avoid the major criticism of self-study apps.","zh":"有即時回饋的網上課程，可能避免對自學應用程式的主要批評。"},{"en":"A quiet electric bus can avoid the major criticism of noisy diesel buses.","zh":"安靜的電動巴士可以避免對嘈雜柴油巴士的主要批評。"},{"en":"This phrase is useful when a new solution fixes the main problem of an older one.","zh":"當新方案解決舊方案的主要問題時，這個片語很有用。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":6},{"front":"the need for back-up","meaning":"需要後備支援","examples":[{"en":"The major criticism of wind power is the need for back-up on calm days.","zh":"對風力發電的主要批評是在無風日子需要後備支援。"},{"en":"The need for back-up means another system is required when the main system cannot work well.","zh":"The need for back-up 指當主要系統無法良好運作時，需要另一套系統支援。"},{"en":"A hospital has the need for back-up power in case the main electricity supply fails.","zh":"醫院需要後備電力，以防主要電力供應失效。"},{"en":"Wind farms have the need for back-up when there is not enough wind to generate power.","zh":"當沒有足夠風力發電時，風電場需要後備支援。"},{"en":"This phrase shows that one system alone may not be reliable enough.","zh":"這個片語顯示單一系統可能不夠可靠。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":6},{"front":"on a calm day","meaning":"在無風的日子","examples":[{"en":"Windmills need back-up on a calm day.","zh":"風車在無風的日子需要後備支援。"},{"en":"On a calm day means on a day when there is little or no wind.","zh":"On a calm day 指在風很小或沒有風的一天。"},{"en":"On a calm day, sailors may move slowly because the wind cannot push the boat.","zh":"在無風的日子，水手可能移動緩慢，因為風不能推動船隻。"},{"en":"A wind turbine produces less electricity on a calm day.","zh":"風力渦輪在無風的日子發電較少。"},{"en":"This phrase is especially useful when explaining why wind power can be unreliable.","zh":"這個片語在解釋風力發電為何可能不可靠時特別有用。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":6},{"front":"one such development","meaning":"其中一項這類發展","examples":[{"en":"One such development uses hot, dry rocks.","zh":"其中一項這類發展使用乾熱岩。"},{"en":"One such development means one example of the type of development just mentioned.","zh":"One such development 指剛才提到的那類發展中的一個例子。"},{"en":"Many schools are testing new learning tools; one such development is an app that gives instant feedback.","zh":"許多學校正在測試新的學習工具；其中一項這類發展是一個提供即時回饋的應用程式。"},{"en":"Several cities are improving transport; one such development is a new electric bus route.","zh":"幾個城市正在改善交通；其中一項這類發展是一條新的電動巴士路線。"},{"en":"This phrase links a general idea to a specific example.","zh":"這個片語把概括想法與具體例子連接起來。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":6},{"front":"hot, dry rocks","meaning":"乾熱岩","examples":[{"en":"Hot, dry rocks can be used to generate energy.","zh":"乾熱岩可以用來產生能源。"},{"en":"Hot, dry rocks are underground rocks that contain heat but little natural water.","zh":"乾熱岩是地下含有熱力但天然水分很少的岩石。"},{"en":"Engineers may pump water into hot, dry rocks to turn it into steam.","zh":"工程師可能把水泵入乾熱岩，使其變成蒸汽。"},{"en":"Hot, dry rocks can provide energy because deep underground temperatures are very high.","zh":"乾熱岩可以提供能源，因為地下深處溫度很高。"},{"en":"This phrase is usually used in discussions of geothermal energy.","zh":"這個片語通常用於討論地熱能源。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":6},{"front":"deep beneath","meaning":"在……深處地下","examples":[{"en":"Hot rocks lie deep beneath South Australia.","zh":"熱岩位於南澳洲深處地下。"},{"en":"Deep beneath means far below the surface of the ground, sea, or another layer.","zh":"Deep beneath 指遠在地面、海面或另一層之下。"},{"en":"Miners work deep beneath the earth to reach valuable minerals.","zh":"礦工在地下深處工作，以取得有價值的礦物。"},{"en":"Water stored deep beneath a city may be protected from surface pollution.","zh":"儲存在城市深處地下的水可能免受地面污染。"},{"en":"This phrase helps describe something hidden far below what we can see.","zh":"這個片語有助描述某物隱藏在我們看得見的表面之下很深處。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":6},{"front":"radiation from","meaning":"來自……的輻射","examples":[{"en":"Radiation from elements in granite heats the rocks.","zh":"來自花崗岩中元素的輻射加熱岩石。"},{"en":"Radiation from something is energy released by a source, sometimes as heat or particles.","zh":"Radiation from something 指某來源釋放出的能量，有時以熱或粒子形式出現。"},{"en":"Radiation from the sun can warm the earth but can also damage skin.","zh":"來自太陽的輻射可以溫暖地球，但也可能傷害皮膚。"},{"en":"Radiation from underground elements may slowly increase rock temperature.","zh":"來自地下元素的輻射可能慢慢提高岩石溫度。"},{"en":"This phrase identifies the source of the radiation.","zh":"這個片語指出輻射的來源。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":6},{"front":"elements contained in","meaning":"……中所含的元素","examples":[{"en":"Radiation comes from elements contained in granite.","zh":"輻射來自花崗岩中所含的元素。"},{"en":"Elements contained in something are chemical substances found inside that material.","zh":"Elements contained in something 指某種材料內所含的化學物質。"},{"en":"Elements contained in soil can affect how well plants grow.","zh":"土壤中所含的元素會影響植物生長得好不好。"},{"en":"Harmful elements contained in old paint may create health risks.","zh":"舊油漆中所含的有害元素可能造成健康風險。"},{"en":"This phrase focuses on what is inside a material, not what is outside it.","zh":"這個片語著重材料內部有甚麼，而不是外部有甚麼。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":6},{"front":"granite","meaning":"花崗岩","examples":[{"en":"Granite deep underground can heat water into steam.","zh":"地下深處的花崗岩可以把水加熱成蒸汽。"},{"en":"Granite is a hard rock often used in buildings, kitchens, and monuments.","zh":"花崗岩是一種堅硬岩石，常用於建築、廚房和紀念碑。"},{"en":"A kitchen worktop made of granite is strong and difficult to scratch.","zh":"由花崗岩製成的廚房檯面很堅固，不易刮花。"},{"en":"In geothermal projects, hot granite can transfer heat to water pumped underground.","zh":"在地熱項目中，熱花崗岩可以把熱傳給泵入地下的水。"},{"en":"Granite is useful in energy discussions when it contains heat deep below the surface.","zh":"當花崗岩在地底深處含有熱力時，它在能源討論中很有用。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":6},{"front":"insulating sedimentation","meaning":"隔熱沉積層","examples":[{"en":"Layers of insulating sedimentation raise temperatures underground.","zh":"多層隔熱沉積層提高地下溫度。"},{"en":"Insulating sedimentation refers to layers of deposited material that trap heat below the surface.","zh":"Insulating sedimentation 指沉積物形成的層，能把熱困在地表以下。"},{"en":"Insulating sedimentation can act like a blanket over hot rocks.","zh":"隔熱沉積層可以像覆蓋熱岩的毛毯一樣。"},{"en":"When insulating sedimentation keeps heat from escaping, underground temperatures may rise.","zh":"當隔熱沉積層阻止熱量散失時，地下溫度可能上升。"},{"en":"This phrase is technical, but the basic idea is simple: some layers hold heat in.","zh":"這個片語較技術性，但基本意思很簡單：有些層會把熱留住。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":7},{"front":"raise the temperatures","meaning":"提高溫度","examples":[{"en":"Insulating sedimentation raises the temperatures in some locations.","zh":"隔熱沉積層會提高某些地點的溫度。"},{"en":"To raise the temperatures means to make temperatures higher.","zh":"To raise the temperatures 指令溫度變高。"},{"en":"A closed car under the sun can quickly raise the temperatures inside.","zh":"在陽光下密閉的汽車可以很快提高車內溫度。"},{"en":"Poor ventilation may raise the temperatures in a classroom during summer.","zh":"通風不佳可能在夏天提高課室溫度。"},{"en":"This phrase is often used when explaining heat, weather, climate, or machinery.","zh":"這個片語常用於解釋熱力、天氣、氣候或機械。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":7},{"front":"propose to","meaning":"提議；計劃","examples":[{"en":"Geoenergy is proposing to pump water deep into the earth.","zh":"Geoenergy正計劃把水泵入地下深處。"},{"en":"To propose to do something means to suggest or plan an action formally or seriously.","zh":"To propose to do something 指正式或認真地建議或計劃某項行動。"},{"en":"The school proposes to extend library hours during exam season.","zh":"學校提議在考試季延長圖書館開放時間。"},{"en":"A company may propose to build a new factory, but it still needs approval.","zh":"公司可能提議興建新工廠，但仍需要批准。"},{"en":"This phrase often appears before a plan that has not yet been fully carried out.","zh":"這個片語常出現在尚未完全實行的計劃之前。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":7},{"front":"pump water","meaning":"泵水","examples":[{"en":"Geoenergy plans to pump water into hot underground rocks.","zh":"Geoenergy計劃把水泵入地下熱岩。"},{"en":"To pump water means to move water by using a machine that pushes it through pipes or spaces.","zh":"To pump water 指用機器推動水經管道或空間流動。"},{"en":"Firefighters may pump water from a nearby river to put out a fire.","zh":"消防員可能從附近河流泵水來滅火。"},{"en":"Farmers pump water into fields when there is not enough rain.","zh":"當雨水不足時，農民會把水泵入農田。"},{"en":"In energy projects, pumping water can move heat from underground rocks to the surface.","zh":"在能源項目中，泵水可以把地下岩石的熱力帶到地面。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":7},{"front":"into the earth","meaning":"進入地下","examples":[{"en":"Water will be pumped 3.5 kilometres into the earth.","zh":"水會被泵入地下3.5公里。"},{"en":"Into the earth means down below the ground or into underground layers.","zh":"Into the earth 指往地面以下或地下層移動。"},{"en":"Builders may drive metal supports deep into the earth before constructing a tall building.","zh":"建築工人在興建高樓前，可能把金屬支柱打入地下深處。"},{"en":"Rainwater can sink into the earth and refill underground water stores.","zh":"雨水可以滲入地下並補充地下水儲存。"},{"en":"This phrase shows movement from the surface to below the ground.","zh":"這個片語顯示從地面移動到地底下。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":7},{"front":"tiny fissures","meaning":"微小裂縫","examples":[{"en":"Water will travel through tiny fissures in the granite.","zh":"水會穿過花崗岩中的微小裂縫。"},{"en":"Tiny fissures are very small cracks in rock, walls, or other hard materials.","zh":"Tiny fissures 是岩石、牆壁或其他硬材料中的很小裂縫。"},{"en":"Water can leak through tiny fissures in an old pipe or wall.","zh":"水可以從舊水管或牆壁的微小裂縫中滲出。"},{"en":"In hot rock systems, tiny fissures allow water to move and collect heat.","zh":"在熱岩系統中，微小裂縫讓水流動並吸收熱力。"},{"en":"The phrase is useful when describing small openings that are hard to see.","zh":"這個片語適合描述難以看見的小開口。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":7},{"front":"heat up as it goes","meaning":"在流動過程中升溫","examples":[{"en":"The water heats up as it goes through the granite.","zh":"水在穿過花崗岩時會在流動過程中升溫。"},{"en":"To heat up as it goes means to become warmer while moving through a place or process.","zh":"To heat up as it goes 指某物在通過某地或某過程時變得更熱。"},{"en":"Soup may heat up as it goes through a microwave cycle.","zh":"湯在微波爐加熱過程中可能升溫。"},{"en":"Air can heat up as it goes through a machine with a hot motor.","zh":"空氣通過有熱摩打的機器時可能升溫。"},{"en":"This phrase shows that heating happens during movement, not before it.","zh":"這個片語顯示加熱發生在移動期間，而不是移動之前。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":7},{"front":"escape as steam","meaning":"以蒸汽形式排出","examples":[{"en":"The heated water escapes as steam through another drilled hole.","zh":"被加熱的水會經另一個鑽孔以蒸汽形式排出。"},{"en":"To escape as steam means to come out in the form of hot vapour.","zh":"To escape as steam 指以熱蒸氣形式流出或排出。"},{"en":"When a kettle boils, water escapes as steam from the spout.","zh":"水壺煲滾時，水會從壺嘴以蒸汽形式排出。"},{"en":"If pressure builds up underground, heated water may escape as steam through cracks.","zh":"如果地下壓力增加，被加熱的水可能經裂縫以蒸汽形式排出。"},{"en":"This phrase describes both movement outward and a change into vapour.","zh":"這個片語同時描述向外移動和變成蒸氣。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":7},{"front":"drilled hole","meaning":"鑽孔","examples":[{"en":"Steam escapes through another drilled hole.","zh":"蒸汽經另一個鑽孔排出。"},{"en":"A drilled hole is an opening made by drilling into a surface such as earth, rock, wood, or metal.","zh":"鑽孔是用鑽探方法在地面、岩石、木材或金屬等表面製造的開口。"},{"en":"Workers may make a drilled hole in a wall to install pipes.","zh":"工人可能在牆上鑽孔以安裝管道。"},{"en":"In geothermal energy, a drilled hole can connect underground heat with surface equipment.","zh":"在地熱能源中，鑽孔可以把地下熱力與地面設備連接起來。"},{"en":"This phrase suggests a planned opening, not a natural crack.","zh":"這個片語暗示有計劃製造的開口，而不是天然裂縫。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":7},{"front":"greenhouse gases","meaning":"溫室氣體","examples":[{"en":"No greenhouse gases are produced by the system.","zh":"這個系統不會產生溫室氣體。"},{"en":"Greenhouse gases are gases that trap heat in the atmosphere and contribute to climate change.","zh":"溫室氣體是會把熱困在大氣中、並加劇氣候變化的氣體。"},{"en":"Cars, factories, and power stations can release greenhouse gases.","zh":"汽車、工廠和發電站都可能排放溫室氣體。"},{"en":"Reducing greenhouse gases can slow climate change and improve air quality.","zh":"減少溫室氣體可以減慢氣候變化並改善空氣質素。"},{"en":"This phrase is central to discussions of energy, transport, farming, and climate policy.","zh":"這個片語是能源、交通、農業和氣候政策討論中的核心詞。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":7},{"front":"additional features","meaning":"額外功能；附加設施","examples":[{"en":"The system needs additional features to be environmentally friendly.","zh":"這個系統需要額外功能才能環保。"},{"en":"Additional features are extra parts, functions, or details added to improve something.","zh":"Additional features 是為改善某物而加入的額外部分、功能或細節。"},{"en":"A phone may have additional features such as face recognition and waterproof protection.","zh":"手機可能有面容識別和防水保護等額外功能。"},{"en":"Additional features can raise the price but make a product safer or more useful.","zh":"額外功能可能提高價格，但令產品更安全或更有用。"},{"en":"This phrase suggests something is not complete with only the basic design.","zh":"這個片語暗示只有基本設計並不足夠完整。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":7},{"front":"environmentally friendly","meaning":"環保的","examples":[{"en":"The system needs extra features to be environmentally friendly.","zh":"這個系統需要額外設施才能環保。"},{"en":"Environmentally friendly means causing little harm to nature, air, water, land, or climate.","zh":"Environmentally friendly 指對自然、空氣、水、土地或氣候造成很少傷害。"},{"en":"Reusable bags are more environmentally friendly than single-use plastic bags.","zh":"可重用袋比一次性膠袋更環保。"},{"en":"A factory becomes more environmentally friendly when it reduces waste and saves energy.","zh":"當工廠減少廢物並節省能源時，它會變得更環保。"},{"en":"Something can be called environmentally friendly only if its whole impact is considered.","zh":"只有在考慮整體影響後，某物才能被稱為環保。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":8},{"front":"geophysicist","meaning":"地球物理學家","examples":[{"en":"Dr Prue Chopra is a geophysicist at the Australian National University.","zh":"Prue Chopra博士是澳洲國立大學的地球物理學家。"},{"en":"A geophysicist is a scientist who studies the physical structure, heat, movement, and forces of the earth.","zh":"地球物理學家是研究地球物理結構、熱力、運動和力量的科學家。"},{"en":"A geophysicist may study earthquakes to understand what happens below the ground.","zh":"地球物理學家可能研究地震，以了解地底下發生甚麼。"},{"en":"Energy companies may ask a geophysicist where underground heat or resources can be found.","zh":"能源公司可能請地球物理學家判斷地下熱力或資源在哪裡。"},{"en":"This word combines geology with physics, so it focuses on how the earth works physically.","zh":"這個詞結合地質學和物理學，所以重點是地球在物理上如何運作。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":8},{"front":"one of the founders of","meaning":"……的創辦人之一","examples":[{"en":"Dr Prue Chopra is one of the founders of Geoenergy.","zh":"Prue Chopra博士是Geoenergy的創辦人之一。"},{"en":"One of the founders of a company or group is one of the people who helped start it.","zh":"One of the founders of a company or group 指幫助創立該公司或團體的人之一。"},{"en":"One of the founders of the club still attends meetings every month.","zh":"這個社團的創辦人之一仍每月出席會議。"},{"en":"A person who is one of the founders often shapes the early direction of an organisation.","zh":"創辦人之一通常會塑造機構早期方向。"},{"en":"This phrase means the person was involved at the beginning, not just later as an employee.","zh":"這個片語表示該人在開始階段已參與，而不只是後來成為員工。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":8},{"front":"bring with it","meaning":"連同……帶來","examples":[{"en":"The steam will bring radon gas with it.","zh":"蒸汽會連同氡氣一起帶來。"},{"en":"To bring something with it means that one thing carries or causes another thing to come along.","zh":"To bring something with it 指一件事物帶着或導致另一件事物一同出現。"},{"en":"Heavy rain can bring flooding with it in low-lying areas.","zh":"大雨在低窪地區可能連同水浸一起帶來。"},{"en":"A new shopping centre may bring more traffic with it.","zh":"新購物中心可能連同更多交通流量一起帶來。"},{"en":"This phrase often shows an extra result, sometimes an unwanted one.","zh":"這個片語常顯示額外結果，有時是不想要的結果。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":8},{"front":"radon gas","meaning":"氡氣","examples":[{"en":"The steam will bring radon gas from underground.","zh":"蒸汽會從地下帶來氡氣。"},{"en":"Radon gas is a naturally occurring radioactive gas that can come from rocks and soil.","zh":"氡氣是一種自然產生的放射性氣體，可能來自岩石和土壤。"},{"en":"Some houses need testing because radon gas can collect indoors without being seen or smelled.","zh":"有些房屋需要檢測，因為氡氣可以在室內積聚，而且看不見、聞不到。"},{"en":"If radon gas is trapped in a system, it must be managed safely.","zh":"如果氡氣被困在系統中，就必須安全處理。"},{"en":"This phrase is important because radon can create health risks if exposure is high.","zh":"這個詞很重要，因為如果接觸量高，氡氣可能造成健康風險。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":8},{"front":"pass through","meaning":"通過","examples":[{"en":"The steam will pass through a heat exchanger.","zh":"蒸汽會通過熱交換器。"},{"en":"To pass through something means to move from one side or part of it to another.","zh":"To pass through something 指從某物的一邊或一部分移動到另一邊或另一部分。"},{"en":"Commuters pass through the station every morning on their way to work.","zh":"通勤者每天早上上班途中都會通過車站。"},{"en":"Water may pass through a filter to remove dirt.","zh":"水可能通過濾水器以去除污垢。"},{"en":"This phrase focuses on movement through a place, object, or system.","zh":"這個片語著重穿過地點、物件或系統的移動。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":8},{"front":"heat exchanger","meaning":"熱交換器","examples":[{"en":"The steam will pass through a heat exchanger before returning underground.","zh":"蒸汽返回地下之前會通過熱交換器。"},{"en":"A heat exchanger is a device that transfers heat from one fluid or gas to another without mixing them.","zh":"熱交換器是一種把熱量從一種液體或氣體轉移到另一種液體或氣體、但不讓它們混合的裝置。"},{"en":"Some air conditioners use a heat exchanger to move heat out of a room.","zh":"一些冷氣機使用熱交換器把熱帶出房間。"},{"en":"In a power system, a heat exchanger can capture useful heat while keeping substances separate.","zh":"在發電系統中，熱交換器可以捕捉有用熱力，同時保持物質分開。"},{"en":"This device is important when heat must be used safely and efficiently.","zh":"當熱力必須被安全而有效地使用時，這種裝置很重要。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":8},{"front":"be sent back underground","meaning":"被送回地下","examples":[{"en":"The steam will be sent back underground for another cycle.","zh":"蒸汽會被送回地下進行另一個循環。"},{"en":"To be sent back underground means to be returned below the earth’s surface after use.","zh":"To be sent back underground 指使用後被送回地表以下。"},{"en":"Water used in a geothermal plant may be sent back underground instead of being released outside.","zh":"地熱電廠使用過的水可能被送回地下，而不是排放到外面。"},{"en":"If steam is sent back underground, harmful gases may be kept inside the system.","zh":"如果蒸汽被送回地下，有害氣體可能被保留在系統內。"},{"en":"This phrase describes a return movement that helps create a closed cycle.","zh":"這個片語描述一種返回移動，有助形成封閉循環。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":8},{"front":"for another cycle","meaning":"進行另一個循環","examples":[{"en":"The steam will be sent back underground for another cycle.","zh":"蒸汽會被送回地下進行另一個循環。"},{"en":"For another cycle means so that the same process can happen again.","zh":"For another cycle 指為了讓同一過程再次發生。"},{"en":"In a washing machine, water may be used for another cycle if it is still clean enough.","zh":"在洗衣機中，如果水仍足夠乾淨，可能被用於另一個循環。"},{"en":"Reusing heat for another cycle can save energy and reduce waste.","zh":"把熱力重用於另一個循環可以節省能源並減少浪費。"},{"en":"This phrase is useful when describing repeated processes in machines, nature, or work.","zh":"這個片語適合描述機器、自然或工作中的重複過程。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":8},{"front":"technically speaking","meaning":"嚴格來說","examples":[{"en":"Technically speaking, hot, dry rocks are not a renewable source of energy.","zh":"嚴格來說，乾熱岩並不是可再生能源來源。"},{"en":"Technically speaking means according to the exact facts, rules, or scientific definition.","zh":"Technically speaking 指根據精確事實、規則或科學定義來說。"},{"en":"Technically speaking, a tomato is a fruit, although many people use it like a vegetable.","zh":"嚴格來說，番茄是水果，雖然很多人把它當蔬菜使用。"},{"en":"Technically speaking, the train was late even if it arrived only two minutes after the schedule.","zh":"嚴格來說，即使火車只比時間表遲了兩分鐘，它也是遲到。"},{"en":"This phrase often introduces a more precise point than everyday language.","zh":"這個片語常引出比日常說法更精確的重點。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":8},{"front":"renewable source of energy","meaning":"可再生能源來源","examples":[{"en":"Hot, dry rocks are not technically a renewable source of energy.","zh":"嚴格來說，乾熱岩不是可再生能源來源。"},{"en":"A renewable source of energy is an energy source that can naturally replace itself over a human timescale.","zh":"可再生能源來源是指在人類時間尺度內能自然補充的能源來源。"},{"en":"Sunlight is a renewable source of energy because it is available every day.","zh":"陽光是可再生能源來源，因為它每天都可取得。"},{"en":"A renewable source of energy can reduce dependence on fuels that will eventually run out.","zh":"可再生能源來源可以減少對最終會耗盡的燃料的依賴。"},{"en":"This phrase focuses on where the energy comes from, not just whether the technology is clean.","zh":"這個片語著重能源來自哪裡，而不只是技術是否清潔。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":8},{"front":"supply the entire country’s needs","meaning":"供應全國所需","examples":[{"en":"The Australian source could supply the entire country’s needs.","zh":"澳洲的這個來源可以供應全國所需。"},{"en":"To supply the entire country’s needs means to provide enough for all people, homes, and businesses in a country.","zh":"To supply the entire country’s needs 指為一個國家的所有人民、家庭和企業提供足夠供應。"},{"en":"A strong water system must supply the entire country’s needs during dry seasons.","zh":"強大的供水系統必須在旱季供應全國所需。"},{"en":"If one energy source can supply the entire country’s needs, it has enormous capacity.","zh":"如果一種能源來源能供應全國所需，它便有巨大容量。"},{"en":"This phrase describes national-scale supply, not a small local project.","zh":"這個片語描述全國規模的供應，而不是小型本地項目。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":9},{"front":"for thousands of years","meaning":"數千年之久","examples":[{"en":"The source could supply electricity for thousands of years.","zh":"這個來源可以供應電力數千年之久。"},{"en":"For thousands of years means for a very long period lasting many centuries.","zh":"For thousands of years 指持續很多世紀的非常長時間。"},{"en":"People have used simple tools for thousands of years.","zh":"人類使用簡單工具已有數千年之久。"},{"en":"If an energy source lasts for thousands of years, it is much longer-lasting than ordinary fuel reserves.","zh":"如果一種能源來源能持續數千年，它比普通燃料儲備持久得多。"},{"en":"This phrase often emphasises an extremely long timescale.","zh":"這個片語常強調極長時間尺度。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":9},{"front":"at current rates of consumption","meaning":"按目前消耗率計算","examples":[{"en":"The source could last for thousands of years at current rates of consumption.","zh":"按目前消耗率計算，這個來源可以持續數千年。"},{"en":"At current rates of consumption means if people continue using something at the same speed as now.","zh":"At current rates of consumption 指如果人們以目前同樣速度繼續使用某物。"},{"en":"A water supply may last only ten years at current rates of consumption.","zh":"按目前消耗率計算，供水可能只夠十年。"},{"en":"If electricity use rises sharply, earlier estimates based on current rates of consumption may become wrong.","zh":"如果用電量大幅上升，根據目前消耗率作出的早期估算可能會變錯。"},{"en":"This phrase is useful because future demand may not stay the same.","zh":"這個片語很有用，因為未來需求未必保持不變。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":9},{"front":"proposals for","meaning":"關於……的建議","examples":[{"en":"Two other proposals for harnessing sun and wind energy have appeared.","zh":"另外兩項關於利用太陽能和風能的建議已經出現。"},{"en":"Proposals for something are suggested plans or ideas about doing it.","zh":"Proposals for something 是指關於做某事的建議計劃或想法。"},{"en":"The council discussed proposals for a new public library.","zh":"市議會討論了關於新公共圖書館的建議。"},{"en":"Proposals for cleaner transport may include electric buses and safer cycle lanes.","zh":"關於更清潔交通的建議可能包括電動巴士和更安全的單車徑。"},{"en":"This phrase usually appears before plans that need discussion, funding, or approval.","zh":"這個片語通常出現在需要討論、資金或批准的計劃之前。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":9},{"front":"harness sun and wind energy","meaning":"利用太陽能和風能","examples":[{"en":"Engineers are developing ways to harness sun and wind energy.","zh":"工程師正在開發利用太陽能和風能的方法。"},{"en":"To harness sun and wind energy means to capture sunlight and wind and turn them into useful power.","zh":"To harness sun and wind energy 指捕捉陽光和風，並把它們轉化為有用電力。"},{"en":"A farm can harness sun and wind energy by using solar panels and small turbines.","zh":"農場可以透過太陽能板和小型渦輪來利用太陽能和風能。"},{"en":"Countries harness sun and wind energy to reduce pollution and fuel imports.","zh":"國家利用太陽能和風能，以減少污染和燃料進口。"},{"en":"The word “harness” suggests controlling a natural force and using it for a purpose.","zh":"“Harness” 這個字暗示控制自然力量並為某目的使用它。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":9},{"front":"surface recently","meaning":"近期浮現","examples":[{"en":"Two proposals have surfaced recently.","zh":"兩項建議近期浮現。"},{"en":"To surface recently means to appear, become known, or be discussed not long ago.","zh":"To surface recently 指不久前出現、被人知道或被討論。"},{"en":"New complaints about the building have surfaced recently.","zh":"關於該建築的新投訴近期浮現。"},{"en":"If old records surface recently, they may change how people understand an event.","zh":"如果舊紀錄近期浮現，可能改變人們對事件的理解。"},{"en":"This phrase suggests that information or ideas were not widely visible before.","zh":"這個片語暗示資訊或想法以前未被廣泛看見。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":9},{"front":"progress continues with","meaning":"……方面的進展持續","examples":[{"en":"Progress continues with EnviroPower’s plans for a solar chimney.","zh":"EnviroPower的太陽能煙囪計劃方面的進展持續。"},{"en":"Progress continues with something means development is still happening in that area or project.","zh":"Progress continues with something 指某領域或項目的發展仍在進行。"},{"en":"Progress continues with the school’s plan to improve its library.","zh":"學校改善圖書館的計劃方面的進展持續。"},{"en":"Progress continues with the new railway after engineers solve land problems.","zh":"工程師解決土地問題後，新鐵路方面的進展持續。"},{"en":"This phrase suggests that work has not stopped, even if the project is not finished.","zh":"這個片語暗示工作沒有停止，即使項目尚未完成。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":9},{"front":"solar chimney","meaning":"太陽能煙囪","examples":[{"en":"EnviroPower plans to build Australia’s first solar chimney.","zh":"EnviroPower計劃興建澳洲第一座太陽能煙囪。"},{"en":"A solar chimney is a structure that uses sun-heated air rising through a tall tower to generate electricity.","zh":"太陽能煙囪是一種利用被太陽加熱的空氣經高塔上升來發電的結構。"},{"en":"A solar chimney needs strong sunlight and a large area to heat the air below it.","zh":"太陽能煙囪需要強陽光和大面積地方來加熱下方空氣。"},{"en":"As hot air rises in a solar chimney, it can drive turbines and produce power.","zh":"當熱空氣在太陽能煙囪中上升時，它可以驅動渦輪並發電。"},{"en":"This technology combines sunlight, airflow, and turbine movement.","zh":"這項技術結合陽光、氣流和渦輪運動。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":9},{"front":"under this scheme","meaning":"在這項方案下","examples":[{"en":"Under this scheme, a tall tower will draw hot air from a greenhouse.","zh":"在這項方案下，一座高塔會從溫室抽取熱空氣。"},{"en":"Under this scheme means according to this plan, arrangement, or system.","zh":"Under this scheme 指根據這個計劃、安排或制度。"},{"en":"Under this scheme, students receive free meals if their families have low incomes.","zh":"在這項方案下，低收入家庭的學生可獲免費膳食。"},{"en":"Under this scheme, households can sell extra solar power back to the grid.","zh":"在這項方案下，家庭可以把多出的太陽能電力賣回電網。"},{"en":"This phrase tells the reader what will happen within a particular plan.","zh":"這個片語告訴讀者在特定計劃中會發生甚麼。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":9},{"front":"draw hot air from","meaning":"從……抽取熱空氣","examples":[{"en":"The tower will draw hot air from a greenhouse.","zh":"高塔會從溫室抽取熱空氣。"},{"en":"To draw hot air from a place means to pull warm air out of that place.","zh":"To draw hot air from a place 指從某地方抽出暖空氣。"},{"en":"A ventilation fan can draw hot air from a kitchen after cooking.","zh":"通風扇可以在煮食後從廚房抽取熱空氣。"},{"en":"Drawing hot air from a greenhouse can create airflow strong enough to move a turbine.","zh":"從溫室抽取熱空氣可以產生足以推動渦輪的氣流。"},{"en":"This phrase describes controlled movement of air, usually caused by a device or design.","zh":"這個片語描述空氣受裝置或設計控制而移動。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":9},{"front":"a greenhouse built to cover","meaning":"建成以覆蓋……的溫室","examples":[{"en":"The project uses a greenhouse built to cover the surrounding area.","zh":"該項目使用一個建成以覆蓋周邊地區的溫室。"},{"en":"A greenhouse built to cover an area is a glass or plastic structure designed to spread over that space.","zh":"A greenhouse built to cover an area 是指設計成覆蓋該空間的玻璃或塑膠結構。"},{"en":"A greenhouse built to cover vegetable beds can protect plants from cold weather.","zh":"建成以覆蓋菜床的溫室，可以保護植物免受寒冷天氣影響。"},{"en":"In a solar chimney, a greenhouse built to cover a large area helps collect heat from sunlight.","zh":"在太陽能煙囪中，建成以覆蓋大面積地方的溫室，有助收集陽光熱力。"},{"en":"This phrase explains the purpose of the greenhouse’s size and position.","zh":"這個片語解釋溫室大小和位置的目的。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":9},{"front":"surrounding area","meaning":"周邊地區","examples":[{"en":"The greenhouse will cover the surrounding 5 km².","zh":"溫室將覆蓋周邊5平方公里。"},{"en":"The surrounding area is the land or neighbourhood around a particular place.","zh":"周邊地區是指某個地方附近的土地或社區。"},{"en":"A new train station can increase shop activity in the surrounding area.","zh":"新火車站可以增加周邊地區的商店活動。"},{"en":"If a factory pollutes the air, people in the surrounding area may be affected.","zh":"如果工廠污染空氣，周邊地區的人可能受影響。"},{"en":"This phrase focuses on what is nearby, not the central point itself.","zh":"這個片語著重附近範圍，而不是中心點本身。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":10},{"front":"drive a turbine","meaning":"驅動渦輪機","examples":[{"en":"As the air rises, it will drive a turbine.","zh":"當空氣上升時，它會驅動渦輪機。"},{"en":"To drive a turbine means to make the turbine turn so that energy can be produced.","zh":"To drive a turbine 指使渦輪轉動，以產生能源。"},{"en":"Moving water can drive a turbine inside a hydroelectric dam.","zh":"流動的水可以驅動水力發電壩內的渦輪機。"},{"en":"Steam from hot rocks can drive a turbine and generate electricity.","zh":"來自熱岩的蒸汽可以驅動渦輪機並發電。"},{"en":"This phrase describes the force that makes a power-generating machine move.","zh":"這個片語描述令發電機器運轉的力量。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":10},{"front":"produce electricity","meaning":"發電","examples":[{"en":"The turbine will produce electricity.","zh":"渦輪機會發電。"},{"en":"To produce electricity means to generate electrical power for use by homes, machines, or systems.","zh":"To produce electricity 指產生供家庭、機器或系統使用的電力。"},{"en":"Solar panels produce electricity when sunlight hits their surface.","zh":"當陽光照到太陽能板表面時，太陽能板會發電。"},{"en":"A power station must produce electricity steadily to meet public demand.","zh":"發電站必須穩定發電以滿足公共需求。"},{"en":"This phrase is simple but important in explaining how energy sources become useful.","zh":"這個片語簡單但重要，用來解釋能源來源如何變得有用。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":10},{"front":"combine technologies","meaning":"結合多種技術","examples":[{"en":"The solar tower combines three old technologies.","zh":"太陽能塔結合了三種舊技術。"},{"en":"To combine technologies means to use two or more technologies together in one system.","zh":"To combine technologies 指在一個系統中一起使用兩種或多種技術。"},{"en":"A smart classroom may combine technologies such as screens, tablets, and online quizzes.","zh":"智慧課室可能結合螢幕、平板電腦和網上測驗等技術。"},{"en":"Combining technologies can solve problems that one tool alone cannot solve.","zh":"結合多種技術可以解決單一工具無法解決的問題。"},{"en":"This phrase suggests integration, not just placing separate tools beside each other.","zh":"這個片語暗示整合，而不只是把不同工具放在一起。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":10},{"front":"proven engineering principles","meaning":"已驗證的工程原理","examples":[{"en":"The project relies on proven engineering principles.","zh":"該項目依賴已驗證的工程原理。"},{"en":"Proven engineering principles are design ideas or methods that have already been tested and shown to work.","zh":"已驗證的工程原理是已經測試並證明有效的設計想法或方法。"},{"en":"Bridges must rely on proven engineering principles so they can carry heavy traffic safely.","zh":"橋樑必須依賴已驗證的工程原理，才能安全承受繁忙交通。"},{"en":"Using proven engineering principles can reduce risk in a new project.","zh":"使用已驗證的工程原理可以降低新項目的風險。"},{"en":"This phrase suggests reliability because the basic science is already trusted.","zh":"這個片語暗示可靠性，因為基本科學已受信任。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":10},{"front":"lead someone to state","meaning":"使某人表示","examples":[{"en":"This reliance led Richard Davies to state that the technology would work.","zh":"這種依賴使Richard Davies表示該技術會成功。"},{"en":"To lead someone to state something means to cause someone to say or conclude it.","zh":"To lead someone to state something 指令某人說出或得出某個結論。"},{"en":"Clear evidence led the doctor to state that the treatment was working.","zh":"清晰證據使醫生表示治療正在奏效。"},{"en":"Falling sales may lead managers to state that the business needs a new strategy.","zh":"銷售下跌可能使管理層表示企業需要新策略。"},{"en":"This phrase shows that a statement is based on a reason or situation.","zh":"這個片語顯示某個說法有原因或情況作基礎。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":10},{"front":"there is no doubt","meaning":"毫無疑問","examples":[{"en":"There is no doubt that this technology will work.","zh":"毫無疑問，這項技術會成功。"},{"en":"There is no doubt means something is certain or almost impossible to question.","zh":"There is no doubt 指某事確定或幾乎不可能被質疑。"},{"en":"There is no doubt that regular practice helps language learners improve.","zh":"毫無疑問，定期練習能幫助語言學習者進步。"},{"en":"There is no doubt that clean water is essential for public health.","zh":"毫無疑問，清潔食水對公共健康至關重要。"},{"en":"This phrase expresses strong certainty, so it should be used carefully.","zh":"這個片語表達強烈確定性，所以應謹慎使用。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":10},{"front":"none at all","meaning":"一點也沒有","examples":[{"en":"Richard Davies said there was no doubt at all.","zh":"Richard Davies說一點疑問也沒有。"},{"en":"None at all means not any, not even a small amount.","zh":"None at all 指完全沒有，甚至一點點也沒有。"},{"en":"There was no sugar left in the kitchen, none at all.","zh":"廚房裡沒有糖了，一點也沒有。"},{"en":"If a student has no preparation at all, the exam will feel much harder.","zh":"如果學生完全沒有準備，考試會感覺困難得多。"},{"en":"This phrase strongly emphasises zero amount, zero doubt, or zero possibility.","zh":"這個片語強烈強調數量、疑問或可能性為零。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":10},{"front":"recognise that","meaning":"意識到；承認","examples":[{"en":"EnviroPower recognised that the project required a larger collecting area.","zh":"EnviroPower意識到該項目需要更大的收集區。"},{"en":"To recognise that something is true means to realise, accept, or understand it.","zh":"To recognise that something is true 指意識到、接受或理解某事是真的。"},{"en":"A teacher may recognise that a quiet student needs more encouragement.","zh":"老師可能意識到一名安靜學生需要更多鼓勵。"},{"en":"Companies must recognise that customer trust can be lost quickly.","zh":"公司必須承認顧客信任可以很快失去。"},{"en":"This phrase often shows a change from not seeing a problem to understanding it.","zh":"這個片語常顯示從未看見問題到理解問題的轉變。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":10},{"front":"the quality of sunlight","meaning":"陽光質素","examples":[{"en":"The quality of sunlight in the Mildura district affects the project design.","zh":"Mildura地區的陽光質素影響項目設計。"},{"en":"The quality of sunlight refers to how strong, direct, and useful sunlight is in a place.","zh":"陽光質素是指某地陽光有多強、直接和有用。"},{"en":"Farmers consider the quality of sunlight when choosing where to grow certain crops.","zh":"農民選擇在哪裡種植某些作物時，會考慮陽光質素。"},{"en":"Poor quality of sunlight may mean a solar project needs a larger collecting area.","zh":"陽光質素較差可能表示太陽能項目需要更大的收集區。"},{"en":"This phrase is not only about brightness; it also includes how reliable the sunlight is.","zh":"這個片語不只關乎亮度；也包括陽光是否可靠。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":10},{"front":"require a substantially larger collecting area","meaning":"需要大得多的收集區","examples":[{"en":"The sunlight will require a substantially larger collecting area.","zh":"這種陽光將需要大得多的收集區。"},{"en":"To require a substantially larger collecting area means to need a much bigger space to gather enough sunlight, air, water, or energy.","zh":"To require a substantially larger collecting area 指需要大得多的空間來收集足夠陽光、空氣、水或能源。"},{"en":"If sunlight is weak, a solar farm may require a substantially larger collecting area.","zh":"如果陽光較弱，太陽能農場可能需要大得多的收集區。"},{"en":"A project may cost more if it requires a substantially larger collecting area than first planned.","zh":"如果項目需要比最初計劃大得多的收集區，成本可能增加。"},{"en":"This phrase links a technical need with a practical problem of space and cost.","zh":"這個片語把技術需求與空間和成本的實際問題連接起來。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":10},{"front":"substantially larger","meaning":"大得多","examples":[{"en":"The collecting area must be substantially larger than expected.","zh":"收集區必須比預期大得多。"},{"en":"Substantially larger means much larger, not just a little larger.","zh":"Substantially larger 指大很多，而不只是大一點。"},{"en":"A family may need a substantially larger flat after two children are born.","zh":"生了兩個孩子後，一個家庭可能需要大得多的單位。"},{"en":"A school with more students may require a substantially larger dining hall.","zh":"學生人數增加的學校可能需要大得多的飯堂。"},{"en":"This phrase is stronger and more formal than “a bit bigger”.","zh":"這個片語比 “a bit bigger” 更強烈和正式。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":11},{"front":"collecting area","meaning":"收集區","examples":[{"en":"The solar chimney will need a larger collecting area.","zh":"太陽能煙囪將需要更大的收集區。"},{"en":"A collecting area is the space used to gather something, such as sunlight, water, heat, or data.","zh":"收集區是用來收集陽光、水、熱力或數據等事物的空間。"},{"en":"A rainwater system needs a clean collecting area on the roof.","zh":"雨水系統需要屋頂上乾淨的收集區。"},{"en":"A larger collecting area can gather more energy but may also cost more to build.","zh":"更大的收集區可以收集更多能源，但建造成本也可能更高。"},{"en":"This phrase explains the part of a system that gathers the resource before it is used.","zh":"這個片語解釋系統中在使用資源前負責收集資源的部分。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":11},{"front":"previously thought","meaning":"以往所想","examples":[{"en":"The collecting area must be larger than previously thought.","zh":"收集區必須比以往所想更大。"},{"en":"Previously thought means believed or expected earlier, before new information appeared.","zh":"Previously thought 指在新資訊出現前，以前相信或預期的情況。"},{"en":"The repair was more expensive than previously thought after workers opened the wall.","zh":"工人打開牆壁後，維修費用比以往所想更高。"},{"en":"A student may need more practice than previously thought if the test is harder than expected.","zh":"如果測驗比預期困難，學生可能需要比以往所想更多練習。"},{"en":"This phrase shows that new evidence has changed an earlier estimate or belief.","zh":"這個片語顯示新證據改變了早前估算或信念。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":11},{"front":"spokesperson","meaning":"發言人","examples":[{"en":"Kay Firth is a spokesperson for EnviroPower.","zh":"Kay Firth是EnviroPower的發言人。"},{"en":"A spokesperson is a person who speaks officially for a company, organisation, or group.","zh":"發言人是代表公司、機構或團體正式發言的人。"},{"en":"A hospital spokesperson may explain a new policy to the media.","zh":"醫院發言人可能向傳媒解釋新政策。"},{"en":"A spokesperson must choose words carefully because they represent more than themselves.","zh":"發言人必須小心選詞，因為他們代表的不只是自己。"},{"en":"This word refers to an official role, not simply a person giving a private opinion.","zh":"這個詞指正式角色，而不只是發表私人意見的人。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":11},{"front":"enable someone to","meaning":"使某人能夠","examples":[{"en":"The new location will enable EnviroPower to balance increased costs with extra revenue.","zh":"新地點將使EnviroPower能夠以額外收入平衡增加的成本。"},{"en":"To enable someone to do something means to make it possible or easier for them to do it.","zh":"To enable someone to do something 指使某人能夠或更容易做某事。"},{"en":"Online lessons enable sick students to continue learning at home.","zh":"網上課堂使生病學生能夠在家繼續學習。"},{"en":"Better childcare can enable parents to return to work.","zh":"更好的托兒服務可以使父母能夠重返工作。"},{"en":"This phrase focuses on the condition or tool that makes an action possible.","zh":"這個片語著重令某行動成為可能的條件或工具。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":11},{"front":"balance increased costs with","meaning":"以……平衡增加的成本","examples":[{"en":"The company hopes to balance increased costs with extra revenue.","zh":"公司希望以額外收入平衡增加的成本。"},{"en":"To balance increased costs with something means to use another benefit or income source to offset higher expenses.","zh":"To balance increased costs with something 指用另一項好處或收入來源抵消較高開支。"},{"en":"A café may balance increased rent with higher weekend sales.","zh":"咖啡店可能以更高的週末銷售額平衡增加的租金。"},{"en":"A school trip can balance increased transport costs with donations from parents.","zh":"學校旅行可以以家長捐款平衡增加的交通成本。"},{"en":"This phrase is useful when explaining how a plan remains financially possible.","zh":"這個片語適合解釋一個計劃如何在財務上仍可行。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":11},{"front":"extra revenue","meaning":"額外收入","examples":[{"en":"The new site may bring extra revenue from tourism.","zh":"新地點可能帶來來自旅遊的額外收入。"},{"en":"Extra revenue is additional income that comes on top of the usual income.","zh":"額外收入是常規收入以外增加的收入。"},{"en":"A museum shop can bring extra revenue to support exhibitions.","zh":"博物館商店可以帶來額外收入，以支援展覽。"},{"en":"Extra revenue from weekend classes may help a school buy new equipment.","zh":"週末課程的額外收入可能幫助學校購買新設備。"},{"en":"This phrase focuses on money coming in, not money being saved.","zh":"這個片語著重流入的金錢，而不是節省下來的金錢。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":11},{"front":"besides saving in","meaning":"除了節省……之外","examples":[{"en":"Besides saving in transmission costs, the new site may increase revenue.","zh":"除了節省輸電成本之外，新地點可能增加收入。"},{"en":"Besides saving in something means in addition to reducing that particular cost.","zh":"Besides saving in something 指除了減少某一項特定成本之外。"},{"en":"Besides saving in rent, working from home can reduce travel time.","zh":"除了節省租金之外，在家工作還可以減少交通時間。"},{"en":"Besides saving in printing costs, online notices can reach students faster.","zh":"除了節省印刷成本之外，網上通告可以更快接觸學生。"},{"en":"This phrase introduces one benefit before adding another benefit.","zh":"這個片語先引出一項好處，再加入另一項好處。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":11},{"front":"transmission costs","meaning":"輸電成本","examples":[{"en":"The new location may reduce transmission costs.","zh":"新地點可能降低輸電成本。"},{"en":"Transmission costs are the costs of moving electricity from where it is produced to where it is used.","zh":"輸電成本是把電力從生產地輸送到使用地的成本。"},{"en":"A power station near a city may have lower transmission costs than one far away.","zh":"靠近城市的發電站可能比遠處的發電站有更低輸電成本。"},{"en":"High transmission costs can make electricity more expensive for consumers.","zh":"高輸電成本可能令消費者的電力更貴。"},{"en":"This phrase is important because electricity has to travel through cables and networks.","zh":"這個片語很重要，因為電力需要經電纜和網絡傳輸。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":11},{"front":"increased revenue from","meaning":"來自……的收入增加","examples":[{"en":"The site may mean increased revenue from tourism.","zh":"該地點可能意味着來自旅遊的收入增加。"},{"en":"Increased revenue from something means more income gained because of that source or activity.","zh":"Increased revenue from something 指因某來源或活動而獲得更多收入。"},{"en":"A town may enjoy increased revenue from visitors after opening a new museum.","zh":"小鎮開設新博物館後，可能享有來自遊客的收入增加。"},{"en":"Increased revenue from online sales can help a shop survive quiet weekdays.","zh":"來自網上銷售的收入增加，可以幫助商店度過平日淡市。"},{"en":"This phrase explains where extra income comes from.","zh":"這個片語解釋額外收入來自哪裡。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":11},{"front":"use of power for","meaning":"將電力用於……","examples":[{"en":"The project may provide power for telecommunications.","zh":"該項目可能提供電力用於電訊。"},{"en":"Use of power for something means electricity is applied to that purpose or service.","zh":"Use of power for something 指把電力應用於某個目的或服務。"},{"en":"The use of power for hospital equipment must be stable and carefully protected.","zh":"將電力用於醫院設備時，供電必須穩定並受到仔細保護。"},{"en":"In remote areas, the use of power for internet services can connect students with teachers.","zh":"在偏遠地區，將電力用於互聯網服務可以連接學生和老師。"},{"en":"This phrase links electricity supply with a particular practical function.","zh":"這個片語把電力供應與某個實際功能連接起來。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":11},{"front":"telecommunications","meaning":"電訊","examples":[{"en":"The project may supply power for telecommunications.","zh":"該項目可能為電訊供電。"},{"en":"Telecommunications means communication over distance by phone, internet, radio, or similar systems.","zh":"電訊是指透過電話、互聯網、無線電或類似系統進行遠距離通訊。"},{"en":"Telecommunications networks allow people to make calls and send messages across countries.","zh":"電訊網絡讓人跨國打電話和傳送訊息。"},{"en":"During a storm, reliable telecommunications help emergency teams coordinate rescue work.","zh":"在暴風雨期間，可靠電訊幫助緊急隊伍協調救援工作。"},{"en":"This word is broader than phones because it includes many forms of long-distance communication.","zh":"這個詞比電話更廣，因為它包括多種遠距離通訊形式。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":12},{"front":"outer 500 metres","meaning":"外圍500米","examples":[{"en":"The outer 500 metres may be used for agribusiness.","zh":"外圍500米可能用於農業企業。"},{"en":"The outer 500 metres means the outside ring or edge area extending 500 metres from a central point.","zh":"The outer 500 metres 指從中心點向外延伸500米的外圍或邊緣區域。"},{"en":"The outer 500 metres of a park may be used for walking paths and small gardens.","zh":"公園外圍500米可能用作步行徑和小花園。"},{"en":"If wind is too strong near the centre, the outer 500 metres may be safer for farming.","zh":"如果中心附近風太強，外圍500米可能較適合耕作。"},{"en":"This phrase describes a specific distance at the edge of an area.","zh":"這個片語描述某個區域邊緣的特定距離。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":12},{"front":"agribusiness","meaning":"農業企業；農業商業","examples":[{"en":"The outer area may be used for agribusiness.","zh":"外圍區域可能用於農業企業。"},{"en":"Agribusiness is farming treated as a business, including growing, processing, selling, and distributing food.","zh":"農業企業是把農業作為商業來經營，包括種植、加工、銷售和分銷食物。"},{"en":"A family farm becomes part of agribusiness when it sells produce to supermarkets.","zh":"當家庭農場把農產品賣給超級市場時，它就成為農業企業的一部分。"},{"en":"Agribusiness can create jobs but may also require careful water and land management.","zh":"農業企業可以創造工作，但也可能需要仔細管理水和土地。"},{"en":"This word connects agriculture with commercial planning and profit.","zh":"這個詞把農業與商業規劃和利潤連接起來。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":12},{"front":"wind speeds","meaning":"風速","examples":[{"en":"Wind speeds closer to the tower will be too high for farming.","zh":"靠近高塔的風速對耕作而言會太高。"},{"en":"Wind speeds are measurements of how fast the air is moving.","zh":"風速是空氣移動速度的測量值。"},{"en":"Weather reports give wind speeds so people know whether outdoor activities are safe.","zh":"天氣報告提供風速，讓人知道戶外活動是否安全。"},{"en":"High wind speeds can damage crops, buildings, and power lines.","zh":"高風速可以損壞農作物、建築物和電纜。"},{"en":"This phrase is important when planning turbines, farms, bridges, and airports.","zh":"規劃渦輪、農場、橋樑和機場時，這個片語很重要。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":12},{"front":"too high for","meaning":"對……而言太高","examples":[{"en":"Wind speeds near the tower will be too high for farming.","zh":"高塔附近的風速對耕作而言太高。"},{"en":"Too high for something means the level is above what is safe, suitable, or useful for that purpose.","zh":"Too high for something 指某個水平高於該目的所能安全、合適或有效接受的程度。"},{"en":"The shelf is too high for a small child to reach.","zh":"架子對小孩而言太高，伸手也夠不着。"},{"en":"The rent may be too high for a new business to afford.","zh":"租金對新企業而言可能太高，難以負擔。"},{"en":"This phrase shows that a number, position, or level creates a practical problem.","zh":"這個片語顯示數字、位置或水平造成實際問題。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":12},{"front":"achieve success with","meaning":"在……方面取得成功","examples":[{"en":"Wavetech is achieving success with a method of harvesting wave energy.","zh":"Wavetech正在一種收集海浪能量的方法方面取得成功。"},{"en":"To achieve success with something means to get good results by using a method, idea, or product.","zh":"To achieve success with something 指透過使用某種方法、想法或產品而取得良好成果。"},{"en":"A teacher may achieve success with weaker students by using clearer examples.","zh":"老師可能透過使用更清晰例子，在較弱學生方面取得成功。"},{"en":"A small company can achieve success with a simple product that solves a common problem.","zh":"小公司可以憑一件解決常見問題的簡單產品取得成功。"},{"en":"This phrase connects success to the tool or approach that helped create it.","zh":"這個片語把成功與促成成功的工具或方法連接起來。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":12},{"front":"harvesting the energy in waves","meaning":"收集海浪能量","examples":[{"en":"Wavetech has developed a method of harvesting the energy in waves.","zh":"Wavetech開發了一種收集海浪能量的方法。"},{"en":"Harvesting the energy in waves means capturing the movement of sea waves and turning it into usable power.","zh":"Harvesting the energy in waves 指捕捉海浪運動並把它轉化為可用電力。"},{"en":"Coastal communities may study harvesting the energy in waves to reduce their use of diesel.","zh":"沿海社區可能研究收集海浪能量，以減少柴油使用。"},{"en":"Harvesting the energy in waves can be difficult because the sea is powerful and unpredictable.","zh":"收集海浪能量可能很困難，因為海洋力量強大且難以預測。"},{"en":"The word “harvesting” suggests collecting a natural resource, like collecting crops from a field.","zh":"“Harvesting” 這個字暗示收集自然資源，就像從田裡收割農作物。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":12},{"front":"a curved surface","meaning":"彎曲表面","examples":[{"en":"Wavetech’s invention uses a curved surface to push waves into a chamber.","zh":"Wavetech的發明使用彎曲表面把海浪推入腔室。"},{"en":"A curved surface is a surface that bends or rounds instead of staying flat.","zh":"彎曲表面是會彎曲或呈圓形、而不是保持平面的表面。"},{"en":"A spoon has a curved surface that can hold liquid.","zh":"湯匙有彎曲表面，可以盛載液體。"},{"en":"A curved surface can guide water, air, or light in a particular direction.","zh":"彎曲表面可以把水、空氣或光引導到特定方向。"},{"en":"In wave-energy machines, a curved surface may help control the movement of waves.","zh":"在海浪能源機器中，彎曲表面可能幫助控制海浪移動。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":12},{"front":"push waves into","meaning":"將海浪推入……","examples":[{"en":"The curved surface pushes waves into a chamber.","zh":"彎曲表面將海浪推入腔室。"},{"en":"To push waves into something means to direct moving seawater into a particular space.","zh":"To push waves into something 指把流動的海水引導進某個特定空間。"},{"en":"A wall shape can push waves into a narrow channel.","zh":"牆壁形狀可以將海浪推入狹窄水道。"},{"en":"Pushing waves into a chamber can compress air and drive a turbine.","zh":"將海浪推入腔室可以壓縮空氣並驅動渦輪。"},{"en":"This phrase shows how wave movement is controlled before energy is produced.","zh":"這個片語顯示在產生能源之前如何控制海浪運動。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":12},{"front":"chamber","meaning":"腔室","examples":[{"en":"Waves are pushed into a chamber in Wavetech’s system.","zh":"在Wavetech的系統中，海浪被推入腔室。"},{"en":"A chamber is an enclosed space inside a machine, building, or natural structure.","zh":"腔室是機器、建築物或自然結構內的封閉空間。"},{"en":"Air is pumped into a chamber before being released through a valve.","zh":"空氣會先被泵入腔室，然後經閥門釋放。"},{"en":"In a wave generator, a chamber can hold water and air so pressure can build up.","zh":"在海浪發電機中，腔室可以容納水和空氣，讓壓力累積。"},{"en":"This word often describes a space where something is contained or controlled.","zh":"這個詞常描述用來容納或控制某物的空間。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":12},{"front":"flowing water column","meaning":"流動水柱","examples":[{"en":"The flowing water column pushes air through a turbine.","zh":"流動水柱把空氣推過渦輪機。"},{"en":"A flowing water column is a moving body of water inside a narrow space, often rising and falling together.","zh":"流動水柱是在狹窄空間內一起上升和下降的流動水體。"},{"en":"In a wave machine, a flowing water column can move up and down as waves enter.","zh":"在海浪機器中，當海浪進入時，流動水柱可以上下移動。"},{"en":"The movement of a flowing water column can push air strongly enough to turn a turbine.","zh":"流動水柱的運動可以把空氣推得足夠強，令渦輪轉動。"},{"en":"This phrase helps explain how wave motion becomes useful mechanical force.","zh":"這個片語幫助解釋海浪運動如何變成有用的機械力量。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":12},{"front":"back and forth","meaning":"來回地","examples":[{"en":"The water column pushes air back and forth through a turbine.","zh":"水柱把空氣來回地推過渦輪機。"},{"en":"Back and forth means repeatedly moving in one direction and then the opposite direction.","zh":"Back and forth 指反覆朝一個方向移動，然後再朝相反方向移動。"},{"en":"Children on a swing move back and forth.","zh":"盪鞦韆的孩子會來回移動。"},{"en":"During a debate, ideas may move back and forth between two sides.","zh":"在辯論中，想法可能在雙方之間來回交流。"},{"en":"This phrase can describe physical movement or repeated exchange in conversation.","zh":"這個片語可以描述身體移動，也可以描述對話中的反覆交流。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":13},{"front":"through a turbine","meaning":"通過渦輪機","examples":[{"en":"Air is pushed through a turbine to generate electricity.","zh":"空氣被推過渦輪機以發電。"},{"en":"Through a turbine means passing through the blades or parts of a turbine so that it can turn.","zh":"Through a turbine 指通過渦輪的葉片或部件，令它能夠轉動。"},{"en":"Steam moves through a turbine in many power stations.","zh":"蒸汽在許多發電站中通過渦輪機。"},{"en":"When air flows through a turbine, the spinning movement can be converted into electricity.","zh":"當空氣流經渦輪機時，旋轉運動可以轉化為電力。"},{"en":"This phrase explains the path taken by air, water, or steam inside a power system.","zh":"這個片語解釋空氣、水或蒸汽在發電系統中的路徑。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":13},{"front":"wave-generator manufacturer","meaning":"海浪發電機製造商","examples":[{"en":"Dr Devine offered his idea to a world-leading wave-generator manufacturer.","zh":"Devine博士把他的想法提供給一間世界領先的海浪發電機製造商。"},{"en":"A wave-generator manufacturer is a company that makes machines designed to produce electricity from waves.","zh":"海浪發電機製造商是製造利用海浪發電機器的公司。"},{"en":"A wave-generator manufacturer must test its equipment in rough sea conditions.","zh":"海浪發電機製造商必須在惡劣海況下測試設備。"},{"en":"A small inventor may approach a wave-generator manufacturer to turn an idea into a product.","zh":"小型發明者可能接觸海浪發電機製造商，把想法變成產品。"},{"en":"This phrase refers to the maker of the machine, not the energy source itself.","zh":"這個片語指機器製造者，而不是能源來源本身。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":13},{"front":"world-leading","meaning":"世界領先的","examples":[{"en":"The idea was offered to a world-leading manufacturer.","zh":"這個想法被提供給一間世界領先的製造商。"},{"en":"World-leading means among the best or most advanced in the world.","zh":"World-leading 指在世界上屬於最好或最先進之一。"},{"en":"A world-leading hospital may attract patients from many countries.","zh":"世界領先的醫院可能吸引來自許多國家的病人。"},{"en":"A university becomes world-leading by producing important research and excellent graduates.","zh":"大學透過產出重要研究和優秀畢業生而變得世界領先。"},{"en":"This adjective is strong, so it should describe truly high international status.","zh":"這個形容詞語氣很強，所以應描述真正高國際地位。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":13},{"front":"reject the idea","meaning":"拒絕這個想法","examples":[{"en":"The manufacturer rather surprisingly rejected the idea.","zh":"該製造商相當令人驚訝地拒絕了這個想法。"},{"en":"To reject the idea means to refuse to accept, use, or support the idea.","zh":"To reject the idea 指拒絕接受、使用或支持該想法。"},{"en":"A teacher may reject the idea of cancelling homework if practice is still needed.","zh":"如果仍需要練習，老師可能拒絕取消功課這個想法。"},{"en":"Investors may reject the idea if the costs are high and the risks are unclear.","zh":"如果成本高而風險不清晰，投資者可能拒絕這個想法。"},{"en":"Rejecting an idea does not always mean it is bad; it may not fit that person’s needs.","zh":"拒絕一個想法不一定代表它不好；它可能不符合該人的需要。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":13},{"front":"respond by","meaning":"以……作回應","examples":[{"en":"Dr Devine responded by establishing Wavetech.","zh":"Devine博士以創立Wavetech作回應。"},{"en":"To respond by doing something means to react to a situation through a particular action.","zh":"To respond by doing something 指透過某個具體行動對情況作出反應。"},{"en":"The school responded by adding extra classes after students asked for help.","zh":"學生求助後，學校以增加額外課堂作回應。"},{"en":"A shop may respond by lowering prices when sales fall.","zh":"當銷售下跌時，商店可能以降價作回應。"},{"en":"This phrase links a situation with the action taken because of it.","zh":"這個片語把某個情況與因此採取的行動連接起來。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":13},{"front":"establish Wavetech","meaning":"創立Wavetech","examples":[{"en":"Dr Devine established Wavetech after his idea was rejected.","zh":"Devine博士在他的想法被拒絕後創立了Wavetech。"},{"en":"To establish Wavetech means to create or set up the company called Wavetech.","zh":"To establish Wavetech 指創建或成立名為Wavetech的公司。"},{"en":"An entrepreneur may establish a company after finding a problem no one else solves well.","zh":"企業家在發現沒有人能妥善解決的問題後，可能創立公司。"},{"en":"Establishing a company can allow an inventor to develop an idea independently.","zh":"創立公司可以讓發明者獨立開發想法。"},{"en":"This phrase marks the beginning of an organisation.","zh":"這個片語標誌一個機構的開始。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":13},{"front":"make improvements to","meaning":"對……作出改進","examples":[{"en":"Dr Devine made a number of improvements to generator design.","zh":"Devine博士對發電機設計作出了多項改進。"},{"en":"To make improvements to something means to change it so that it works better.","zh":"To make improvements to something 指改變某物，令它運作得更好。"},{"en":"A teacher may make improvements to a worksheet after students find it confusing.","zh":"當學生覺得工作紙混亂時，老師可能對它作出改進。"},{"en":"Engineers make improvements to bridges to increase safety and reduce repairs.","zh":"工程師對橋樑作出改進，以提高安全性並減少維修。"},{"en":"This phrase suggests practical changes, not just criticism or discussion.","zh":"這個片語暗示實際改變，而不只是批評或討論。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":13},{"front":"generator design","meaning":"發電機設計","examples":[{"en":"Wavetech made improvements to generator design.","zh":"Wavetech對發電機設計作出了改進。"},{"en":"Generator design is the way a machine is planned and built to produce electricity.","zh":"發電機設計是指一部機器如何被規劃和建造以產生電力。"},{"en":"Better generator design can make a machine smaller, quieter, and more efficient.","zh":"更好的發電機設計可以令機器更小、更安靜和更高效。"},{"en":"If generator design is poor, energy may be wasted before it becomes electricity.","zh":"如果發電機設計差劣，能源在變成電力之前可能被浪費。"},{"en":"This phrase focuses on the structure and function of the electricity-producing machine.","zh":"這個片語著重產電機器的結構和功能。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":13},{"front":"claim that","meaning":"聲稱","examples":[{"en":"Wavetech claims that its technology can produce cheap electricity.","zh":"Wavetech聲稱其技術可以生產便宜電力。"},{"en":"To claim that something is true means to say it is true, often before everyone agrees.","zh":"To claim that something is true 指說某事是真的，常在所有人同意之前使用。"},{"en":"A company may claim that its product saves time, but customers still need evidence.","zh":"公司可能聲稱其產品節省時間，但顧客仍需要證據。"},{"en":"Scientists should test a result carefully before claiming that a treatment works.","zh":"科學家在聲稱某治療有效之前，應仔細測試結果。"},{"en":"This phrase can be neutral, but it often suggests the statement may need proof.","zh":"這個片語可以是中性的，但常暗示該說法可能需要證明。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":13},{"front":"at appropriate sites","meaning":"在合適地點","examples":[{"en":"Wavetech’s technology is effective at appropriate sites.","zh":"Wavetech的技術在合適地點有效。"},{"en":"At appropriate sites means in places that have the right conditions for the technology or activity.","zh":"At appropriate sites 指在具備該技術或活動所需正確條件的地方。"},{"en":"Wind turbines work best at appropriate sites with strong and steady wind.","zh":"風力渦輪在有強而穩定風力的合適地點運作最佳。"},{"en":"A school garden succeeds at appropriate sites with sunlight, water, and safe access.","zh":"學校花園在有陽光、水和安全通道的合適地點較易成功。"},{"en":"This phrase reminds us that location can decide whether a plan works.","zh":"這個片語提醒我們，地點可以決定計劃是否有效。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":13},{"front":"below 4 cents per kilowatt-hour","meaning":"低於每千瓦時4仙","examples":[{"en":"Wavetech claims its electricity could cost below 4 cents per kilowatt-hour.","zh":"Wavetech聲稱其電力成本可低於每千瓦時4仙。"},{"en":"Below 4 cents per kilowatt-hour means each unit of electricity costs less than four cents.","zh":"Below 4 cents per kilowatt-hour 指每一單位電力成本少於4仙。"},{"en":"If solar power falls below 4 cents per kilowatt-hour, it may compete strongly with coal.","zh":"如果太陽能跌至低於每千瓦時4仙，它可能強力與煤炭競爭。"},{"en":"A price below 4 cents per kilowatt-hour would be very attractive to electricity buyers.","zh":"低於每千瓦時4仙的價格對電力買家而言會非常吸引。"},{"en":"This phrase gives a precise cost target for comparing energy sources.","zh":"這個片語提供精確成本目標，用於比較能源來源。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":14},{"front":"diversity of forms","meaning":"形式多樣性","examples":[{"en":"The diversity of forms of renewable energy in Australia is remarkable.","zh":"澳洲可再生能源的形式多樣性十分值得注意。"},{"en":"Diversity of forms means there are many different types or versions of something.","zh":"Diversity of forms 指某事有許多不同類型或版本。"},{"en":"The diversity of forms in modern education includes online lessons, workshops, and one-to-one tutoring.","zh":"現代教育的形式多樣性包括網上課堂、工作坊和一對一補習。"},{"en":"A diversity of forms can make a system stronger because it does not depend on only one option.","zh":"形式多樣性可以令系統更強，因為它不只依賴單一選項。"},{"en":"This phrase highlights variety rather than quantity alone.","zh":"這個片語強調多樣，而不只是數量。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":14},{"front":"greenhouse-friendly energy","meaning":"對溫室氣體友善的能源","examples":[{"en":"Australia is developing many forms of greenhouse-friendly energy.","zh":"澳洲正在開發許多形式的對溫室氣體友善的能源。"},{"en":"Greenhouse-friendly energy is energy that produces little or no greenhouse gases.","zh":"Greenhouse-friendly energy 是指產生很少或不產生溫室氣體的能源。"},{"en":"Wind, solar, and wave power can be forms of greenhouse-friendly energy.","zh":"風能、太陽能和海浪能可以是對溫室氣體友善的能源形式。"},{"en":"Using greenhouse-friendly energy can help reduce the gases that heat the planet.","zh":"使用對溫室氣體友善的能源可以幫助減少令地球升溫的氣體。"},{"en":"This phrase focuses on climate impact rather than price alone.","zh":"這個片語著重氣候影響，而不只是價格。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":14},{"front":"under development","meaning":"正在開發中","examples":[{"en":"Many forms of greenhouse-friendly energy are under development.","zh":"許多形式的對溫室氣體友善的能源正在開發中。"},{"en":"Under development means still being designed, tested, or improved and not yet fully completed.","zh":"Under development 指仍在設計、測試或改善，尚未完全完成。"},{"en":"A new school app is under development, so students cannot use it yet.","zh":"一個新的學校應用程式正在開發中，所以學生尚未能使用。"},{"en":"Medicines under development must pass safety tests before doctors can prescribe them.","zh":"正在開發中的藥物必須通過安全測試，醫生才可處方。"},{"en":"This phrase suggests ongoing work and future possibility.","zh":"這個片語暗示持續工作和未來可能性。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":14},{"front":"remarkable","meaning":"非凡的；值得注意的","examples":[{"en":"The diversity of renewable energy projects is remarkable.","zh":"可再生能源項目的多樣性是值得注意的。"},{"en":"Remarkable means unusual, impressive, or worth noticing.","zh":"Remarkable 指不尋常、令人印象深刻或值得注意。"},{"en":"A student who improves from failing to top marks has made remarkable progress.","zh":"一名學生從不合格進步到高分，是取得了非凡進步。"},{"en":"A small village with excellent public transport is remarkable because it is unexpected.","zh":"一個擁有優秀公共交通的小村莊很值得注意，因為這出乎意料。"},{"en":"This word is stronger than “good” because it shows something stands out.","zh":"這個字比 “good” 更強，因為它顯示某事突出。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":14},{"front":"support at the national level","meaning":"國家層面的支持","examples":[{"en":"Support at the national level is disappointing.","zh":"國家層面的支持令人失望。"},{"en":"Support at the national level means help, funding, or policy backing from the central government or whole country.","zh":"Support at the national level 指來自中央政府或全國的幫助、資金或政策支持。"},{"en":"Public health programmes need support at the national level to reach every region.","zh":"公共健康計劃需要國家層面的支持，才能接觸每個地區。"},{"en":"Without support at the national level, clean-energy projects may remain small and scattered.","zh":"沒有國家層面的支持，清潔能源項目可能仍然小而分散。"},{"en":"This phrase contrasts national action with local or private efforts.","zh":"這個片語把國家行動與本地或私人努力作對比。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":14},{"front":"disappointing","meaning":"令人失望的","examples":[{"en":"National support for renewable energy is disappointing.","zh":"國家對可再生能源的支持令人失望。"},{"en":"Disappointing means not as good, strong, or successful as people hoped.","zh":"Disappointing 指不如人們希望般好、強或成功。"},{"en":"The exam result was disappointing because the student had worked very hard.","zh":"考試成績令人失望，因為那名學生曾非常努力。"},{"en":"A disappointing policy may fail to solve the problem it promised to address.","zh":"令人失望的政策可能未能解決它承諾處理的問題。"},{"en":"This word expresses unmet expectation, not complete disaster.","zh":"這個字表達期望未被滿足，而不是完全災難。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":14},{"front":"huge potential for","meaning":"在……方面有巨大潛力","examples":[{"en":"Australia has huge potential for wind, sun and wave technology.","zh":"澳洲在風能、太陽能和海浪能技術方面有巨大潛力。"},{"en":"Huge potential for something means a very strong possibility of future success or development in that area.","zh":"Huge potential for something 指某方面未來成功或發展的可能性很大。"},{"en":"A young athlete may have huge potential for international competition.","zh":"年輕運動員可能在國際比賽方面有巨大潛力。"},{"en":"A district with good transport has huge potential for small businesses.","zh":"交通便利的地區在小企業發展方面有巨大潛力。"},{"en":"This phrase praises future possibility, but it does not mean success has already happened.","zh":"這個片語稱讚未來可能性，但不代表成功已經發生。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":14},{"front":"wind, sun and wave technology","meaning":"風能、太陽能和海浪能技術","examples":[{"en":"Australia has potential for wind, sun and wave technology.","zh":"澳洲在風能、太陽能和海浪能技術方面有潛力。"},{"en":"Wind, sun and wave technology refers to systems that use wind, sunlight, and ocean waves to produce energy.","zh":"Wind, sun and wave technology 指利用風、陽光和海浪來生產能源的系統。"},{"en":"A coastal sunny country may be suitable for wind, sun and wave technology.","zh":"一個陽光充足的沿海國家可能適合風能、太陽能和海浪能技術。"},{"en":"Investing in wind, sun and wave technology can reduce dependence on coal and oil.","zh":"投資風能、太陽能和海浪能技術可以減少對煤炭和石油的依賴。"},{"en":"This phrase groups three natural energy sources together.","zh":"這個片語把三種自然能源來源放在一起。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":14},{"front":"be at the forefront","meaning":"處於前沿","examples":[{"en":"Australia should be at the forefront of renewable energy research.","zh":"澳洲應該處於可再生能源研究前沿。"},{"en":"To be at the forefront means to be among the leaders in a field or activity.","zh":"To be at the forefront 指在某領域或活動中位於領先位置。"},{"en":"A school can be at the forefront of digital learning if it trains teachers well.","zh":"如果學校好好培訓老師，它可以處於數碼學習前沿。"},{"en":"Cities at the forefront of recycling often make it easy for residents to sort waste.","zh":"處於回收前沿的城市，通常讓居民容易分類垃圾。"},{"en":"This phrase suggests active leadership, not passive participation.","zh":"這個片語暗示積極領導，而不是被動參與。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":14},{"front":"the reality is","meaning":"現實是","examples":[{"en":"The reality is that Australia is a long way behind.","zh":"現實是，澳洲遠遠落後。"},{"en":"The reality is introduces the true situation, especially when it is different from hopes or claims.","zh":"The reality is 用來引出真實情況，尤其當它與希望或說法不同時。"},{"en":"The reality is that many students need more practice than one lesson can provide.","zh":"現實是，許多學生需要的練習超過一堂課能提供的程度。"},{"en":"The reality is that cheap products may still carry hidden environmental costs.","zh":"現實是，便宜產品仍可能帶有隱藏環境成本。"},{"en":"This phrase is useful when moving from ideal thinking to actual facts.","zh":"這個片語適合從理想想法轉向實際事實。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":14},{"front":"a long way behind","meaning":"遠遠落後","examples":[{"en":"Australia is a long way behind in renewable energy development.","zh":"澳洲在可再生能源發展方面遠遠落後。"},{"en":"A long way behind means far behind others in progress, skill, or development.","zh":"A long way behind 指在進展、技能或發展方面遠遠落後於他人。"},{"en":"A student who has missed six months of lessons may be a long way behind classmates.","zh":"缺課六個月的學生可能遠遠落後於同學。"},{"en":"A company can be a long way behind if it ignores new technology for years.","zh":"如果公司多年忽視新科技，它可能遠遠落後。"},{"en":"This phrase suggests a serious gap, not a small delay.","zh":"這個片語暗示嚴重差距，而不是小小延誤。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":15},{"front":"agree with the information given","meaning":"與所給資料一致","examples":[{"en":"Students decide whether each statement agrees with the information given.","zh":"學生判斷每項陳述是否與所給資料一致。"},{"en":"To agree with the information given means to match what the passage says.","zh":"To agree with the information given 指與文章所說內容相符。"},{"en":"In a reading test, an answer agrees with the information given only if the text supports it.","zh":"在閱讀測驗中，只有文本支持某答案，它才與所給資料一致。"},{"en":"A statement may sound reasonable but still not agree with the information given.","zh":"一項陳述可能聽起來合理，但仍不與所給資料一致。"},{"en":"This phrase teaches students to check the text, not their own opinions.","zh":"這個片語教學生檢查文本，而不是依靠自己的意見。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":15},{"front":"in boxes","meaning":"在方格內","examples":[{"en":"Students write their answers in boxes on the answer sheet.","zh":"學生在答題紙上的方格內寫答案。"},{"en":"In boxes means inside the small spaces provided for answers, numbers, or letters.","zh":"In boxes 指在提供給答案、數字或字母的小空格內。"},{"en":"In an exam, students must write one letter in boxes clearly.","zh":"在考試中，學生必須在方格內清楚寫上一個字母。"},{"en":"If answers are written outside the boxes, the marking system may not read them.","zh":"如果答案寫在方格外，評分系統可能讀不到。"},{"en":"This phrase is practical and often appears in test instructions.","zh":"這個片語很實用，常出現在考試指示中。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":15},{"front":"contradict the information","meaning":"與資料矛盾","examples":[{"en":"A false statement contradicts the information in the passage.","zh":"錯誤陳述與文章中的資料矛盾。"},{"en":"To contradict the information means to say the opposite of what the text says.","zh":"To contradict the information 指說出與文本內容相反的意思。"},{"en":"If the passage says sales rose, an answer saying they fell contradicts the information.","zh":"如果文章說銷售上升，而答案說下降，那就與資料矛盾。"},{"en":"Students lose marks when they choose an answer that contradicts the information given.","zh":"當學生選擇與所給資料矛盾的答案時，便會失分。"},{"en":"This phrase is important in TRUE/FALSE/NOT GIVEN questions.","zh":"這個片語在TRUE/FALSE/NOT GIVEN題型中很重要。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":15},{"front":"no information on this","meaning":"沒有這方面資料","examples":[{"en":"Students write “NOT GIVEN” if there is no information on this.","zh":"如果沒有這方面資料，學生寫 “NOT GIVEN”。"},{"en":"No information on this means the passage does not tell us whether the statement is true or false.","zh":"No information on this 指文章沒有告訴我們該陳述是真還是假。"},{"en":"If a text describes a company’s cost but not its profit, there is no information on this profit question.","zh":"如果文本描述公司的成本但沒有描述利潤，那這道利潤問題就沒有這方面資料。"},{"en":"Students should not guess from common sense when there is no information on this in the passage.","zh":"當文章沒有這方面資料時，學生不應憑常識猜測。"},{"en":"This phrase reminds learners that absence of evidence is different from contradiction.","zh":"這個片語提醒學習者，沒有證據不同於矛盾。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":15},{"front":"conventional electricity","meaning":"傳統電力","examples":[{"en":"Alternative energy is compared with conventional electricity.","zh":"替代能源與傳統電力作比較。"},{"en":"Conventional electricity is electricity produced by traditional methods, often from coal, gas, or oil.","zh":"傳統電力是透過傳統方法生產的電力，通常來自煤炭、天然氣或石油。"},{"en":"Many homes still use conventional electricity supplied by large power stations.","zh":"許多家庭仍使用大型發電站供應的傳統電力。"},{"en":"Conventional electricity may seem cheap if pollution costs are not included.","zh":"如果不計算污染成本，傳統電力可能看似便宜。"},{"en":"This phrase is often used when comparing older energy systems with newer alternatives.","zh":"這個片語常用於比較舊能源系統與較新的替代方案。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":15},{"front":"less expensive than","meaning":"比……便宜","examples":[{"en":"The question asks whether alternative energy is less expensive than conventional electricity.","zh":"問題問替代能源是否比傳統電力便宜。"},{"en":"Less expensive than means cheaper than another option.","zh":"Less expensive than 指比另一個選項便宜。"},{"en":"Cooking at home is usually less expensive than eating in restaurants every day.","zh":"在家煮食通常比每天在餐廳用餐便宜。"},{"en":"A train ticket may be less expensive than parking in the city centre.","zh":"火車票可能比在市中心泊車便宜。"},{"en":"This phrase is a clear way to compare costs.","zh":"這個片語是比較成本的清晰方法。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":15},{"front":"adapt its system","meaning":"調整其系統","examples":[{"en":"Geoenergy needs to adapt its system to make it less harmful.","zh":"Geoenergy需要調整其系統，使其傷害較少。"},{"en":"To adapt its system means to change the system so it fits a new need, problem, or condition.","zh":"To adapt its system 指改變系統，使其配合新的需要、問題或條件。"},{"en":"A school may adapt its system for students who learn better online.","zh":"學校可能為較適合網上學習的學生調整其系統。"},{"en":"A company must adapt its system if new safety rules are introduced.","zh":"如果引入新的安全規則，公司必須調整其系統。"},{"en":"This phrase suggests practical adjustment rather than abandoning the whole system.","zh":"這個片語暗示實際調整，而不是放棄整個系統。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":15},{"front":"less harmful to","meaning":"對……較少傷害","examples":[{"en":"The system must become less harmful to the environment.","zh":"這個系統必須變得對環境較少傷害。"},{"en":"Less harmful to something means causing less damage or risk to it.","zh":"Less harmful to something 指對某物造成較少損害或風險。"},{"en":"Public transport is usually less harmful to air quality than private cars.","zh":"公共交通通常比私家車對空氣質素較少傷害。"},{"en":"A cleaner factory process can be less harmful to nearby rivers.","zh":"較清潔的工廠流程可以對附近河流較少傷害。"},{"en":"This phrase compares levels of damage, not complete safety.","zh":"這個片語比較傷害程度，而不是表示完全安全。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":15},{"front":"study the effects of","meaning":"研究……的影響","examples":[{"en":"The question asks whether Dr Chopra studied the effects of radon gas.","zh":"問題問Chopra博士是否研究了氡氣的影響。"},{"en":"To study the effects of something means to examine what changes, benefits, or harms it causes.","zh":"To study the effects of something 指研究某物造成的變化、好處或傷害。"},{"en":"Doctors study the effects of a new medicine before giving it to many patients.","zh":"醫生在把新藥給很多病人使用前，會研究它的影響。"},{"en":"Schools may study the effects of later start times on student sleep.","zh":"學校可能研究較晚上課時間對學生睡眠的影響。"},{"en":"This phrase focuses on results caused by something.","zh":"這個片語著重由某事造成的結果。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":15},{"front":"provide enough power for","meaning":"為……提供足夠電力","examples":[{"en":"Hot, dry rocks could provide enough power for the whole of Australia.","zh":"乾熱岩可以為整個澳洲提供足夠電力。"},{"en":"To provide enough power for something means to supply sufficient electricity or energy for its needs.","zh":"To provide enough power for something 指供應足以滿足其需要的電力或能源。"},{"en":"A small battery may provide enough power for a phone but not for a refrigerator.","zh":"小電池可能為手機提供足夠電力，但不能為雪櫃提供足夠電力。"},{"en":"Solar panels on a roof can provide enough power for a family during sunny hours.","zh":"屋頂太陽能板可以在陽光充足時為家庭提供足夠電力。"},{"en":"This phrase connects energy supply with a specific user, place, or purpose.","zh":"這個片語把能源供應與特定使用者、地點或目的連接起來。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":15},{"front":"the whole of Australia","meaning":"整個澳洲","examples":[{"en":"The energy source could supply the whole of Australia.","zh":"這種能源來源可以供應整個澳洲。"},{"en":"The whole of Australia means all parts of Australia, not only one region or city.","zh":"The whole of Australia 指澳洲所有地區，而不只是某個地區或城市。"},{"en":"A national campaign may try to reach the whole of Australia.","zh":"全國性宣傳活動可能試圖接觸整個澳洲。"},{"en":"Supplying the whole of Australia would require a very large and reliable energy system.","zh":"供應整個澳洲需要非常龐大而可靠的能源系統。"},{"en":"This phrase emphasises national coverage.","zh":"這個片語強調全國覆蓋。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":16},{"front":"discourage tourists","meaning":"令遊客卻步","examples":[{"en":"The question asks whether the new facility will discourage tourists.","zh":"問題問新設施是否會令遊客卻步。"},{"en":"To discourage tourists means to make visitors less willing to come to a place.","zh":"To discourage tourists 指令遊客較不願意前往某地方。"},{"en":"Dirty beaches can discourage tourists from visiting a coastal town.","zh":"骯髒海灘可能令遊客對沿海城鎮卻步。"},{"en":"High prices may discourage tourists even if the attractions are beautiful.","zh":"即使景點美麗，高價格也可能令遊客卻步。"},{"en":"This phrase focuses on what reduces people’s desire to travel somewhere.","zh":"這個片語著重甚麼會降低人們去某地旅遊的意願。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":16},{"front":"be established after","meaning":"在……之後成立","examples":[{"en":"Wavetech was established after another company rejected the proposal.","zh":"Wavetech是在另一間公司拒絕該建議之後成立的。"},{"en":"To be established after something means to be created or set up later than that event.","zh":"To be established after something 指在某事件之後被創立或設立。"},{"en":"A support group may be established after a serious accident in the community.","zh":"社區發生嚴重事故之後，可能成立支援小組。"},{"en":"A new rule was established after repeated complaints from residents.","zh":"居民多次投訴之後，一條新規則被設立。"},{"en":"This phrase shows the order of events and often explains the reason for creation.","zh":"這個片語顯示事件先後次序，並常解釋創立原因。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":16},{"front":"reject a proposal","meaning":"拒絕建議","examples":[{"en":"Another company rejected the founder’s proposal.","zh":"另一間公司拒絕了創辦人的建議。"},{"en":"To reject a proposal means to refuse a suggested plan or idea.","zh":"To reject a proposal 指拒絕一項被提出的計劃或想法。"},{"en":"The council may reject a proposal if it is too expensive or unsafe.","zh":"如果建議太昂貴或不安全，市議會可能拒絕該建議。"},{"en":"Investors rejected the proposal because the business plan lacked clear evidence.","zh":"投資者拒絕了該建議，因為商業計劃缺乏清晰證據。"},{"en":"This phrase is formal and often used in business, government, and academic contexts.","zh":"這個片語較正式，常用於商業、政府和學術語境。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":16},{"front":"world leader in","meaning":"……方面的世界領先者","examples":[{"en":"The question asks whether Australia is a world leader in renewable energy.","zh":"問題問澳洲是否是可再生能源方面的世界領先者。"},{"en":"A world leader in a field is one of the most advanced or successful countries, companies, or people in that area.","zh":"某領域的世界領先者，是指該領域中最先進或最成功的國家、公司或人物之一。"},{"en":"A hospital may be a world leader in cancer treatment if patients travel internationally to use it.","zh":"如果病人跨國前往某醫院接受癌症治療，它可能是癌症治療方面的世界領先者。"},{"en":"A country cannot be a world leader in clean energy without strong research and investment.","zh":"一個國家沒有強大研究和投資，就不能成為清潔能源方面的世界領先者。"},{"en":"This phrase suggests top international status, not just local success.","zh":"這個片語暗示頂尖國際地位，而不只是本地成功。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":16},{"front":"developing renewable energy","meaning":"發展可再生能源","examples":[{"en":"The AEA discusses Australia’s position in developing renewable energy.","zh":"AEA討論澳洲在發展可再生能源方面的地位。"},{"en":"Developing renewable energy means creating, improving, and expanding clean energy sources such as wind, solar, wave, and geothermal power.","zh":"Developing renewable energy 指創造、改善和擴展風能、太陽能、海浪能和地熱能等清潔能源來源。"},{"en":"A government can support developing renewable energy by funding research and building better grids.","zh":"政府可以透過資助研究和建設更好電網來支持發展可再生能源。"},{"en":"Developing renewable energy can create jobs while reducing pollution from fossil fuels.","zh":"發展可再生能源可以創造工作，同時減少化石燃料造成的污染。"},{"en":"This phrase describes an ongoing process, not one completed project.","zh":"這個片語描述持續過程，而不是已完成的一個項目。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":16},{"front":"look at the following statements","meaning":"查看以下陳述","examples":[{"en":"Students look at the following statements and match them with companies.","zh":"學生查看以下陳述，並把它們與公司配對。"},{"en":"Look at the following statements means read the list of sentences given after the instruction.","zh":"Look at the following statements 指閱讀指示後面列出的句子。"},{"en":"In a test, students should look at the following statements before searching the passage.","zh":"在測驗中，學生應先查看以下陳述，再搜尋文章。"},{"en":"If learners do not look at the following statements carefully, they may miss key words.","zh":"如果學習者沒有仔細查看以下陳述，可能會錯過關鍵詞。"},{"en":"This phrase is common in exam instructions and tells students what to focus on next.","zh":"這個片語常見於考試指示，告訴學生接下來要集中看甚麼。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":16},{"front":"the list of companies below","meaning":"以下公司列表","examples":[{"en":"The list of companies below gives four possible answers.","zh":"以下公司列表提供四個可能答案。"},{"en":"The list of companies below means the company names printed underneath the instruction.","zh":"The list of companies below 指印在指示下方的公司名稱。"},{"en":"Students should check the list of companies below before choosing a letter.","zh":"學生在選擇字母前，應查看以下公司列表。"},{"en":"If the list of companies below includes repeated options, one answer may be used more than once.","zh":"如果以下公司列表包括可重複選用的選項，一個答案可能使用多次。"},{"en":"This phrase points readers to information placed lower on the page.","zh":"這個片語把讀者指向頁面較下方的資訊。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":16},{"front":"match each statement with","meaning":"將每項陳述與……配對","examples":[{"en":"Students match each statement with the correct company.","zh":"學生將每項陳述與正確公司配對。"},{"en":"To match each statement with something means to connect every statement to the option that fits it best.","zh":"To match each statement with something 指把每項陳述連接到最合適的選項。"},{"en":"In a reading task, students may match each statement with a paragraph.","zh":"在閱讀任務中，學生可能將每項陳述與段落配對。"},{"en":"If students match each statement with the wrong speaker, they lose marks.","zh":"如果學生將每項陳述與錯誤說話者配對，便會失分。"},{"en":"This phrase describes a pairing task, not a simple true-or-false task.","zh":"這個片語描述配對任務，而不是簡單的是非題。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":16},{"front":"the correct company","meaning":"正確公司","examples":[{"en":"Each statement should be matched with the correct company.","zh":"每項陳述應與正確公司配對。"},{"en":"The correct company is the company that the passage says is linked to a particular statement.","zh":"The correct company 是指文章所說與某項陳述相關的公司。"},{"en":"Students should find evidence before choosing the correct company.","zh":"學生在選擇正確公司之前，應先找證據。"},{"en":"The correct company may appear in a different paragraph from the exact wording of the question.","zh":"正確公司可能出現在與題目原文不同的段落中。"},{"en":"This phrase reminds learners that the answer must come from the text.","zh":"這個片語提醒學習者，答案必須來自文本。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":16},{"front":"may use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"Students may use any letter more than once.","zh":"學生可重複使用任何字母。"},{"en":"May use any letter more than once means the same answer option can be chosen for two or more questions.","zh":"May use any letter more than once 指同一答案選項可以用於兩題或以上。"},{"en":"In a matching exercise, students may use any letter more than once if several statements refer to the same paragraph.","zh":"在配對練習中，如果幾項陳述都指同一段，學生可重複使用任何字母。"},{"en":"Learners should not avoid a repeated answer when the instruction says they may use any letter more than once.","zh":"當指示說可重複使用任何字母時，學習者不應避免重複答案。"},{"en":"This phrase prevents students from assuming every answer must be different.","zh":"這個片語防止學生以為每個答案都必須不同。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":16},{"front":"during the process","meaning":"在過程中","examples":[{"en":"During the process, harmful substances are prevented from escaping.","zh":"在過程中，有害物質被阻止逸出。"},{"en":"During the process means while a particular series of actions is happening.","zh":"During the process 指在某一連串行動發生期間。"},{"en":"During the process of cooking, children should stay away from hot oil.","zh":"在煮食過程中，孩子應遠離熱油。"},{"en":"During the process of applying for a job, applicants may need to submit documents and attend interviews.","zh":"在申請工作過程中，申請人可能需要提交文件並參加面試。"},{"en":"This phrase focuses on what happens in the middle of an action, not before or after it.","zh":"這個片語著重行動進行中的事情，而不是之前或之後。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":17},{"front":"harmful substances","meaning":"有害物質","examples":[{"en":"The system prevents harmful substances from escaping.","zh":"這個系統阻止有害物質逸出。"},{"en":"Harmful substances are materials or chemicals that can damage health, air, water, or the environment.","zh":"有害物質是可能損害健康、空氣、水或環境的材料或化學品。"},{"en":"Cleaning products may contain harmful substances if they are used without care.","zh":"如果不小心使用，清潔產品可能含有有害物質。"},{"en":"Factories must store harmful substances safely to protect nearby communities.","zh":"工廠必須安全儲存有害物質，以保護附近社區。"},{"en":"This phrase is broad and can refer to gases, liquids, solids, or chemicals.","zh":"這個片語很廣，可以指氣體、液體、固體或化學品。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":17},{"front":"be prevented from escaping","meaning":"被阻止逸出","examples":[{"en":"Harmful substances are prevented from escaping.","zh":"有害物質被阻止逸出。"},{"en":"To be prevented from escaping means to be stopped from getting out of a container, system, or place.","zh":"To be prevented from escaping 指被阻止從容器、系統或地方跑出來。"},{"en":"Gas is prevented from escaping when pipes are properly sealed.","zh":"當管道被妥善密封時，氣體就被阻止逸出。"},{"en":"In a laboratory, dangerous fumes must be prevented from escaping into the room.","zh":"在實驗室中，危險煙霧必須被阻止逸出到房間內。"},{"en":"This phrase focuses on controlling something that would be risky if released.","zh":"這個片語著重控制某些一旦釋放便有風險的東西。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":17},{"front":"force air through","meaning":"迫使空氣通過……","examples":[{"en":"Water is used to force air through a turbine.","zh":"水被用來迫使空氣通過渦輪機。"},{"en":"To force air through something means to push air strongly through a space or machine.","zh":"To force air through something 指強力把空氣推過某個空間或機器。"},{"en":"A fan can force air through a filter to remove dust.","zh":"風扇可以迫使空氣通過濾網以去除灰塵。"},{"en":"In a wave generator, moving water may force air through a turbine and produce electricity.","zh":"在海浪發電機中，流動的水可能迫使空氣通過渦輪機並發電。"},{"en":"This phrase suggests active pressure, not gentle natural movement.","zh":"這個片語暗示主動壓力，而不是溫和的自然流動。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":17},{"front":"special device","meaning":"特別裝置","examples":[{"en":"The system uses a special device to generate electricity.","zh":"這個系統使用特別裝置來發電。"},{"en":"A special device is a tool or machine designed for a particular purpose.","zh":"特別裝置是為特定目的而設計的工具或機器。"},{"en":"A doctor may use a special device to check a patient’s heart.","zh":"醫生可能使用特別裝置檢查病人的心臟。"},{"en":"A special device can make a difficult task safer, faster, or more accurate.","zh":"特別裝置可以令困難任務更安全、更快速或更準確。"},{"en":"This phrase is useful when the exact machine name is not the main focus.","zh":"當確切機器名稱不是重點時，這個片語很有用。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":17},{"front":"techniques used in other countries","meaning":"其他國家使用的技術","examples":[{"en":"Some techniques used in other countries are being copied.","zh":"一些其他國家使用的技術正在被複製。"},{"en":"Techniques used in other countries are methods or designs that have already been applied abroad.","zh":"Techniques used in other countries 是指已在海外應用的方法或設計。"},{"en":"A school may study techniques used in other countries to improve language teaching.","zh":"學校可能研究其他國家使用的技術，以改善語言教學。"},{"en":"Copying techniques used in other countries can save time, but local conditions still matter.","zh":"複製其他國家使用的技術可以節省時間，但本地條件仍然重要。"},{"en":"This phrase helps compare domestic practice with overseas experience.","zh":"這個片語有助比較本地做法與海外經驗。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":17},{"front":"be copied","meaning":"被複製","examples":[{"en":"Some European designs are being copied in Australia.","zh":"一些歐洲設計正在澳洲被複製。"},{"en":"To be copied means to be reproduced or imitated by someone else.","zh":"To be copied 指被其他人重現或模仿。"},{"en":"A student’s homework should not be copied from the internet.","zh":"學生的功課不應從網上被複製。"},{"en":"A successful shop design may be copied by competitors.","zh":"成功的店舖設計可能被競爭者複製。"},{"en":"This phrase can be neutral in technology, but negative when it means cheating or stealing ideas.","zh":"這個片語在科技中可以是中性的，但當它指作弊或偷取想法時則是負面。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":17},{"front":"provide services other than","meaning":"提供除……以外的服務","examples":[{"en":"The system can provide services other than energy production.","zh":"這個系統可以提供除能源生產以外的服務。"},{"en":"To provide services other than something means to offer additional functions besides the main one mentioned.","zh":"To provide services other than something 指除了已提到的主要功能外，還提供其他功能。"},{"en":"A library can provide services other than lending books, such as study rooms and workshops.","zh":"圖書館可以提供除借書以外的服務，例如自修室和工作坊。"},{"en":"A community centre may provide services other than sports, including counselling and childcare.","zh":"社區中心可能提供除運動以外的服務，包括輔導和托兒。"},{"en":"This phrase helps show that something has more than one use.","zh":"這個片語有助顯示某物有不止一種用途。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":17},{"front":"energy production","meaning":"能源生產","examples":[{"en":"Some projects offer benefits beyond energy production.","zh":"一些項目提供超越能源生產的好處。"},{"en":"Energy production is the process of creating usable power from sources such as coal, wind, sun, water, or waves.","zh":"能源生產是從煤炭、風、陽光、水或海浪等來源創造可用能源的過程。"},{"en":"Energy production affects daily life because homes, hospitals, and transport need power.","zh":"能源生產影響日常生活，因為家庭、醫院和交通都需要能源。"},{"en":"Cleaner energy production can reduce pollution and protect public health.","zh":"更清潔的能源生產可以減少污染並保護公共健康。"},{"en":"This phrase is broader than electricity production because it can include different forms of energy.","zh":"這個片語比電力生產更廣，因為它可以包括不同形式的能源。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":17},{"front":"force water deep underground","meaning":"將水迫入地下深處","examples":[{"en":"The company plans to force water deep underground.","zh":"公司計劃將水迫入地下深處。"},{"en":"To force water deep underground means to push water far below the earth’s surface, usually by pressure.","zh":"To force water deep underground 指通常利用壓力把水推到地表以下很深的位置。"},{"en":"Engineers may force water deep underground to reach hot rocks.","zh":"工程師可能將水迫入地下深處，以接觸熱岩。"},{"en":"If water is forced deep underground, it may return as hot water or steam.","zh":"如果水被迫入地下深處，它可能以熱水或蒸汽形式返回。"},{"en":"This phrase suggests a controlled technical process using pressure and drilling.","zh":"這個片語暗示使用壓力和鑽探的受控技術過程。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":17},{"front":"original estimates","meaning":"原本估算","examples":[{"en":"Original estimates for part of the project have been revised.","zh":"項目某部分的原本估算已被修訂。"},{"en":"Original estimates are the first calculations or predictions made before later information is available.","zh":"原本估算是在後來資訊出現之前最初作出的計算或預測。"},{"en":"The original estimates for building the school were too low.","zh":"興建學校的原本估算太低。"},{"en":"Original estimates may change after engineers find problems underground.","zh":"工程師在地下發現問題後，原本估算可能改變。"},{"en":"This phrase is useful when comparing early expectations with later figures.","zh":"這個片語適合比較早期預期與後來數字。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":17},{"front":"part of the project","meaning":"項目的一部分","examples":[{"en":"Part of the project now requires a larger area.","zh":"項目的一部分現在需要更大的區域。"},{"en":"Part of the project means one section, stage, or element of a larger plan.","zh":"Part of the project 指一個較大計劃中的某個部分、階段或元素。"},{"en":"Designing the website is only part of the project; testing it is also necessary.","zh":"設計網站只是項目的一部分；測試網站也很必要。"},{"en":"If one part of the project is delayed, the whole schedule may be affected.","zh":"如果項目的一部分延誤，整個時間表可能受影響。"},{"en":"This phrase helps break a large project into smaller pieces.","zh":"這個片語幫助把大型項目分成較小部分。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":18},{"front":"be revised","meaning":"被修訂","examples":[{"en":"Original estimates have been revised.","zh":"原本估算已被修訂。"},{"en":"To be revised means to be changed, corrected, or updated after review.","zh":"To be revised 指在檢視後被更改、修正或更新。"},{"en":"The exam timetable may be revised if a public holiday is announced.","zh":"如果宣布公眾假期，考試時間表可能被修訂。"},{"en":"A budget must be revised when costs turn out to be higher than expected.","zh":"當成本高於預期時，預算必須被修訂。"},{"en":"This phrase suggests that earlier information was not final.","zh":"這個片語暗示早前資訊並非最終版本。"}],"source":"Flash Cards - 165 - Renewable Energy.pdf","sourcePage":18}],"ielts/reading/passage-2/Practice 166":[{"front":"fair-trade movement","meaning":"公平貿易運動","examples":[{"en":"The fair-trade movement began in Europe in earnest in the post-war period.","zh":"公平貿易運動在戰後時期於歐洲正式開始。"},{"en":"The fair-trade movement is an organised effort to make international trade fairer for producers.","zh":"公平貿易運動是一項有組織的努力，旨在令國際貿易對生產者更公平。"},{"en":"It focuses especially on small producers in poorer countries.","zh":"它尤其關注較貧窮國家的小型生產者。"},{"en":"Supporters believe the movement helps reduce inequality in global trade.","zh":"支持者相信該運動有助減少全球貿易中的不平等。"},{"en":"The phrase refers to both the idea and the organisations behind fair trade.","zh":"這個詞組同時指公平貿易的理念和相關組織。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":1},{"front":"begin in earnest","meaning":"正式開始；認真展開","examples":[{"en":"The fair-trade movement began in earnest after the war.","zh":"公平貿易運動在戰後正式開始。"},{"en":"Begin in earnest means start seriously or with real effort.","zh":"正式開始或認真展開，指以嚴肅態度或真正努力開始。"},{"en":"A campaign may begin in earnest when people organise meetings and raise funds.","zh":"當人們組織會議和籌款時，一場運動可能正式展開。"},{"en":"The phrase suggests that earlier ideas existed, but stronger action came later.","zh":"這個詞組表示早前可能已有想法，但較強行動是後來才出現。"},{"en":"It is often used when something moves from discussion to serious activity.","zh":"它常用於某事由討論轉為認真活動時。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":1},{"front":"post-war period","meaning":"戰後時期","examples":[{"en":"The fair-trade movement grew in the post-war period.","zh":"公平貿易運動在戰後時期發展。"},{"en":"The post-war period means the years after a major war.","zh":"戰後時期，指一場重大戰爭之後的年代。"},{"en":"In this passage, it refers to the period after the Second World War.","zh":"在本文中，它指第二次世界大戰之後的時期。"},{"en":"Many social and political movements developed during the post-war period.","zh":"許多社會和政治運動在戰後時期發展起來。"},{"en":"The phrase gives historical context for the rise of fair trade.","zh":"這個詞組為公平貿易的興起提供歷史背景。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":1},{"front":"grow to include","meaning":"發展至包括……","examples":[{"en":"The movement has grown to include producers and consumers in many countries.","zh":"該運動已發展至包括許多國家的生產者和消費者。"},{"en":"Grow to include means expand until more people, places, or things are involved.","zh":"發展至包括，指擴展到有更多人、地方或事物參與。"},{"en":"A local campaign can grow to include supporters around the world.","zh":"一場本地運動可以發展至包括世界各地支持者。"},{"en":"Fair trade grew beyond Europe and became international.","zh":"公平貿易由歐洲擴展，變成國際性運動。"},{"en":"The phrase describes development over time.","zh":"這個詞組描述隨時間而來的發展。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":1},{"front":"producers and consumers","meaning":"生產者和消費者","examples":[{"en":"Fair trade now includes producers and consumers in over 60 countries.","zh":"公平貿易如今包括超過 60 個國家的生產者和消費者。"},{"en":"Producers make or grow goods, while consumers buy and use them.","zh":"生產者製造或種植商品，而消費者購買並使用商品。"},{"en":"Fair trade connects producers in poorer regions with consumers in richer markets.","zh":"公平貿易把較貧窮地區的生產者與較富裕市場的消費者連接起來。"},{"en":"Consumers may pay more because they want producers to be treated fairly.","zh":"消費者可能願意支付更多，因為他們希望生產者受到公平對待。"},{"en":"The phrase identifies the two main sides of trade.","zh":"這個詞組指出貿易中的兩個主要方面。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":1},{"front":"over 60 countries","meaning":"超過60個國家","examples":[{"en":"Fair trade now involves producers and consumers in over 60 countries.","zh":"公平貿易如今涉及超過 60 個國家的生產者和消費者。"},{"en":"Over 60 countries means more than sixty nations.","zh":"超過 60 個國家，指多於六十個國家。"},{"en":"The phrase shows that fair trade has become a global movement.","zh":"這個詞組顯示公平貿易已成為全球運動。"},{"en":"Participation across many countries makes fair trade international rather than local.","zh":"多國參與令公平貿易成為國際性，而不是本地性。"},{"en":"It gives a sense of the movement’s scale.","zh":"它提供該運動規模的概念。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":1},{"front":"the developed world","meaning":"已發展世界；已發展國家","examples":[{"en":"Many people in the developed world supported fair trade.","zh":"已發展世界中許多人支持公平貿易。"},{"en":"The developed world means wealthier industrialised countries.","zh":"已發展世界指較富裕、工業化程度較高的國家。"},{"en":"Consumers in the developed world often buy fair-trade products from poorer producers.","zh":"已發展國家的消費者經常購買來自較貧窮生產者的公平貿易產品。"},{"en":"The phrase contrasts richer countries with developing countries.","zh":"這個詞組把較富裕國家與發展中國家作對比。"},{"en":"It is used to discuss global economic inequality.","zh":"它用於討論全球經濟不平等。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":1},{"front":"feel passionately about","meaning":"對……感受強烈","examples":[{"en":"Many people felt passionately about global trade inequality.","zh":"許多人對全球貿易不平等感受強烈。"},{"en":"Feel passionately about means have very strong feelings or beliefs about something.","zh":"對某事感受強烈，指對它有非常強烈的感情或信念。"},{"en":"Fair-trade supporters felt passionately about helping poor producers.","zh":"公平貿易支持者對幫助貧困生產者感受強烈。"},{"en":"Strong feelings can lead people to join campaigns or change buying habits.","zh":"強烈感受可以令人參與運動或改變購買習慣。"},{"en":"The phrase shows emotional commitment.","zh":"這個詞組顯示情感上的投入。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":1},{"front":"enormous disparities","meaning":"巨大差距","examples":[{"en":"Supporters worried about enormous disparities between rich and poor countries.","zh":"支持者擔心富國與窮國之間的巨大差距。"},{"en":"Enormous disparities are very large differences or inequalities.","zh":"巨大差距，指非常大的差異或不平等。"},{"en":"In global trade, disparities may appear in income, power, and market access.","zh":"在全球貿易中，差距可能出現在收入、權力和市場准入方面。"},{"en":"Fair trade aims to reduce some of these gaps.","zh":"公平貿易旨在減少其中一些差距。"},{"en":"The phrase highlights serious inequality.","zh":"這個詞組突顯嚴重不平等。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":1},{"front":"developed and developing countries","meaning":"已發展國家和發展中國家","examples":[{"en":"Fair trade addresses disparities between developed and developing countries.","zh":"公平貿易處理已發展國家和發展中國家之間的差距。"},{"en":"Developed countries are wealthier, while developing countries are still building economic capacity.","zh":"已發展國家較富裕，而發展中國家仍在建立經濟能力。"},{"en":"The phrase is used to compare rich and poorer parts of the world.","zh":"這個詞組用來比較世界上較富裕和較貧窮的地區。"},{"en":"Fair trade often links consumers in developed countries with producers in developing countries.","zh":"公平貿易通常把已發展國家的消費者與發展中國家的生產者連接起來。"},{"en":"It is central to the passage’s discussion of trade inequality.","zh":"它是文章討論貿易不平等的核心。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":1},{"front":"the system of international trade","meaning":"國際貿易制度","examples":[{"en":"Critics believed the system of international trade excluded poorer producers.","zh":"批評者認為國際貿易制度排除了較貧窮的生產者。"},{"en":"The system of international trade means the rules and practices by which countries buy and sell goods globally.","zh":"國際貿易制度，指各國在全球買賣商品的規則和做法。"},{"en":"Small producers may struggle within this system if powerful companies dominate it.","zh":"如果強大公司支配制度，小型生產者可能難以生存。"},{"en":"Fair-trade supporters wanted to change how this system treated poorer farmers.","zh":"公平貿易支持者希望改變這個制度對待較貧窮農民的方式。"},{"en":"The phrase refers to global trade arrangements.","zh":"這個詞組指全球貿易安排。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":1},{"front":"shut out","meaning":"將……排除在外","examples":[{"en":"The trade system shut out many African, Asian and South American producers.","zh":"貿易制度將許多非洲、亞洲和南美洲生產者排除在外。"},{"en":"Shut out means exclude or prevent someone from taking part.","zh":"將某人排除在外，指排斥或阻止某人參與。"},{"en":"Poor producers may be shut out of profitable markets.","zh":"貧困生產者可能被排除在有利可圖的市場之外。"},{"en":"The phrase suggests unfair exclusion.","zh":"這個詞組暗示不公平的排斥。"},{"en":"It helps explain why fair trade was created.","zh":"它有助解釋公平貿易為何產生。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":2},{"front":"African, Asian, and South American producers","meaning":"非洲、亞洲和南美洲生產者","examples":[{"en":"Many African, Asian, and South American producers could not compete with multinational companies.","zh":"許多非洲、亞洲和南美洲生產者無法與跨國公司競爭。"},{"en":"This phrase refers to producers from three major world regions.","zh":"這個詞組指來自三個主要世界地區的生產者。"},{"en":"These producers may include farmers, craft workers, and small co-operatives.","zh":"這些生產者可能包括農民、手工藝人和小型合作社。"},{"en":"Fair trade aims to give such producers better access to markets.","zh":"公平貿易旨在讓這些生產者更容易進入市場。"},{"en":"The phrase identifies the groups fair trade was designed to help.","zh":"這個詞組指出公平貿易原本希望幫助的群體。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":2},{"front":"compete with","meaning":"與……競爭","examples":[{"en":"Small producers often could not compete with multinational companies.","zh":"小型生產者經常無法與跨國公司競爭。"},{"en":"Compete with means try to succeed against another person or organisation in the same market.","zh":"與某人或某機構競爭，指在同一市場中嘗試勝過對方。"},{"en":"Small farmers may struggle to compete with large corporations.","zh":"小農戶可能難以與大型企業競爭。"},{"en":"Fair trade tries to give weaker producers a more secure position.","zh":"公平貿易嘗試給較弱勢生產者更穩定的位置。"},{"en":"The phrase describes market rivalry.","zh":"這個詞組描述市場競爭。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":2},{"front":"multinational companies","meaning":"跨國公司","examples":[{"en":"Fair-trade supporters criticised the power of multinational companies.","zh":"公平貿易支持者批評跨國公司的力量。"},{"en":"Multinational companies are large businesses operating in several countries.","zh":"跨國公司是在多個國家營運的大型企業。"},{"en":"These companies may have more bargaining power than small producers.","zh":"這些公司可能比小型生產者有更大議價能力。"},{"en":"Critics argue that they can dominate international trade.","zh":"批評者認為它們可以支配國際貿易。"},{"en":"The phrase identifies powerful corporate actors in global markets.","zh":"這個詞組指出全球市場中的強大企業角色。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":2},{"front":"for political reasons","meaning":"出於政治原因","examples":[{"en":"Some states were not trading with the West for political reasons.","zh":"一些國家出於政治原因沒有與西方貿易。"},{"en":"For political reasons means because of government, ideology, diplomacy, or power relations.","zh":"出於政治原因，指因政府、意識形態、外交或權力關係。"},{"en":"A country may avoid trade with another country for political reasons.","zh":"一個國家可能出於政治原因避免與另一國貿易。"},{"en":"The phrase shows that trade is not only economic.","zh":"這個詞組顯示貿易不只是經濟問題。"},{"en":"It explains why some producers were excluded from Western markets.","zh":"它解釋為何一些生產者被排除在西方市場之外。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":2},{"front":"trade with the West","meaning":"與西方貿易","examples":[{"en":"Some producers came from states that were not trading with the West.","zh":"一些生產者來自沒有與西方貿易的國家。"},{"en":"Trade with the West means buy and sell goods with Western countries.","zh":"與西方貿易，指與西方國家買賣商品。"},{"en":"Political conflict may prevent trade with the West.","zh":"政治衝突可能阻止與西方貿易。"},{"en":"Producers outside Western trade networks may lose access to profitable buyers.","zh":"不在西方貿易網絡中的生產者可能失去有利可圖的買家。"},{"en":"The phrase links economics with international relations.","zh":"這個詞組把經濟與國際關係連接起來。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":2},{"front":"catchphrase","meaning":"口號；標語","examples":[{"en":"The catchphrase “Trade Not Aid” was used by early fair-trade supporters.","zh":"早期公平貿易支持者使用「要貿易，不要援助」這個口號。"},{"en":"A catchphrase is a short memorable expression used to represent an idea.","zh":"口號是簡短易記、用來代表某個想法的表達。"},{"en":"Catchphrases help social movements spread their message.","zh":"口號幫助社會運動傳播訊息。"},{"en":"“Trade Not Aid” summed up the early fair-trade argument.","zh":"「要貿易，不要援助」概括了早期公平貿易論點。"},{"en":"The phrase refers to a slogan-like expression.","zh":"這個詞組指類似標語的表達。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":2},{"front":"Trade Not Aid","meaning":"要貿易，不要援助","examples":[{"en":"“Trade Not Aid” was an early slogan of the fair-trade movement.","zh":"「要貿易，不要援助」是公平貿易運動的早期口號。"},{"en":"Trade Not Aid means poorer producers should gain fair trade opportunities rather than depend only on charity.","zh":"「要貿易，不要援助」意思是較貧窮生產者應獲得公平貿易機會，而不是只依賴慈善。"},{"en":"The slogan criticised international aid as inadequate or controlling.","zh":"這個口號批評國際援助不足或具控制性。"},{"en":"It argued that fair market access was better than small donations.","zh":"它主張公平市場准入比少量捐助更好。"},{"en":"The phrase captures the movement’s early political message.","zh":"這個詞組概括了該運動早期的政治訊息。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":2},{"front":"church groups","meaning":"教會團體","examples":[{"en":"Church groups were early supporters of fair trade.","zh":"教會團體是公平貿易的早期支持者。"},{"en":"Church groups are religious organisations or communities connected with churches.","zh":"教會團體，是與教會有關的宗教組織或群體。"},{"en":"They often supported fair trade because of moral concerns about poverty.","zh":"它們經常因對貧困的道德關注而支持公平貿易。"},{"en":"Church groups helped spread the message to consumers.","zh":"教會團體幫助把訊息傳播給消費者。"},{"en":"The phrase identifies one early support base of the movement.","zh":"這個詞組指出該運動的一個早期支持基礎。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":2},{"front":"trade unions","meaning":"工會","examples":[{"en":"Trade unions supported fair trade in its early years.","zh":"工會在公平貿易早期支持該運動。"},{"en":"Trade unions are organisations that represent workers’ interests.","zh":"工會是代表工人利益的組織。"},{"en":"They may support fair trade because it concerns labour conditions and fair pay.","zh":"它們可能支持公平貿易，因為公平貿易涉及勞動條件和公平報酬。"},{"en":"Trade unions often campaign for better treatment of workers.","zh":"工會經常為工人更好待遇而運動。"},{"en":"The phrase identifies another early supporter group.","zh":"這個詞組指出另一個早期支持群體。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":2},{"front":"early supporters of","meaning":"……的早期支持者","examples":[{"en":"Church groups and trade unions were early supporters of fair trade.","zh":"教會團體和工會是公平貿易的早期支持者。"},{"en":"Early supporters of something are people or groups who backed it near the beginning.","zh":"某事的早期支持者，是在其初期支持它的人或群體。"},{"en":"Early supporters helped fair trade gain public attention.","zh":"早期支持者幫助公平貿易獲得公眾關注。"},{"en":"Their involvement gave the movement moral and social credibility.","zh":"他們的參與給予該運動道德和社會可信度。"},{"en":"The phrase describes support during the first stages of a movement.","zh":"這個詞組描述一場運動初期的支持。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":2},{"front":"international aid","meaning":"國際援助","examples":[{"en":"Some supporters considered international aid inadequate or controlling.","zh":"一些支持者認為國際援助不足或具控制性。"},{"en":"International aid is assistance given by one country or organisation to another country or people.","zh":"國際援助，是一個國家或組織向另一國家或人民提供的協助。"},{"en":"Aid may include money, food, training, or emergency support.","zh":"援助可能包括金錢、食物、培訓或緊急支援。"},{"en":"Early fair-trade supporters argued that trade could be more empowering than aid.","zh":"早期公平貿易支持者認為貿易可能比援助更能賦權。"},{"en":"The phrase is contrasted with trade in the slogan “Trade Not Aid.”","zh":"這個詞組在「要貿易，不要援助」口號中與貿易形成對比。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":3},{"front":"a pittance","meaning":"少得可憐的一點錢","examples":[{"en":"Some people considered international aid to be a pittance.","zh":"有些人認為國際援助只是少得可憐的一點錢。"},{"en":"A pittance is a very small amount of money, especially one that seems inadequate.","zh":"少得可憐的一點錢，指非常少、尤其顯得不足的金額。"},{"en":"Critics argued that aid was only a pittance compared with global trade inequality.","zh":"批評者認為，與全球貿易不平等相比，援助只是微不足道。"},{"en":"The word carries a negative tone.","zh":"這個詞帶有負面語氣。"},{"en":"It suggests that the help given was far too little.","zh":"它表示所給予的幫助遠遠不夠。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":3},{"front":"covert form of subjugation","meaning":"隱蔽的支配形式","examples":[{"en":"Some critics saw aid as a covert form of subjugation.","zh":"一些批評者把援助視為隱蔽的支配形式。"},{"en":"A covert form of subjugation is hidden control or domination disguised as help.","zh":"隱蔽的支配形式，是偽裝成幫助的隱藏控制或支配。"},{"en":"Critics feared that aid could make poorer countries dependent.","zh":"批評者擔心援助會令較貧窮國家依賴他人。"},{"en":"The phrase presents aid as politically problematic.","zh":"這個詞組把援助呈現為政治上有問題。"},{"en":"It explains why some supporters preferred trade to aid.","zh":"它解釋為何一些支持者較喜歡貿易而不是援助。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":3},{"front":"these days","meaning":"現今；如今","examples":[{"en":"These days, much fair trade includes aid and training.","zh":"如今，許多公平貿易包括援助和培訓。"},{"en":"These days means nowadays or in the present time.","zh":"現今或如今，指現在這個時期。"},{"en":"The phrase contrasts current fair trade with its earlier form.","zh":"這個詞組把當前公平貿易與早期形式作對比。"},{"en":"Fair trade now often includes practical support as well as buying goods.","zh":"公平貿易現在經常包括實際支援以及購買商品。"},{"en":"It signals a change over time.","zh":"它標示隨時間出現的變化。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":3},{"front":"include aid","meaning":"包括援助","examples":[{"en":"Much fair trade now includes aid from developed-world volunteers.","zh":"現在許多公平貿易包括來自已發展國家義工的援助。"},{"en":"Include aid means contain assistance as part of the system.","zh":"包括援助，指把協助作為制度的一部分。"},{"en":"Aid may come as training, advice, or practical services.","zh":"援助可能以培訓、建議或實際服務形式出現。"},{"en":"This shows that modern fair trade is not purely trade-based.","zh":"這顯示現代公平貿易並非純粹以貿易為基礎。"},{"en":"The phrase describes an added form of support.","zh":"這個詞組描述一種額外支援形式。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":3},{"front":"developed-world volunteers","meaning":"已發展國家的義工","examples":[{"en":"Developed-world volunteers offer their services to fair-trade producers.","zh":"已發展國家的義工向公平貿易生產者提供服務。"},{"en":"Developed-world volunteers are unpaid helpers from wealthier countries.","zh":"已發展國家的義工，是來自較富裕國家的無薪協助者。"},{"en":"They may provide training, business advice, or technical support.","zh":"他們可能提供培訓、商業建議或技術支援。"},{"en":"Their involvement can help producers meet fair-trade standards.","zh":"他們的參與可以幫助生產者符合公平貿易標準。"},{"en":"The phrase identifies a group that supports producers.","zh":"這個詞組指出支持生產者的一個群體。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":3},{"front":"offer their services","meaning":"提供服務","examples":[{"en":"Volunteers offer their services to producers and workers.","zh":"義工向生產者和工人提供服務。"},{"en":"Offer their services means provide help, skills, or labour.","zh":"提供服務，指提供幫助、技能或勞力。"},{"en":"Volunteers may offer their services without asking for payment.","zh":"義工可能不要求報酬而提供服務。"},{"en":"Such services can include training or advice.","zh":"這些服務可以包括培訓或建議。"},{"en":"The phrase describes practical support.","zh":"這個詞組描述實際支援。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":3},{"front":"free training","meaning":"免費培訓","examples":[{"en":"Fair trade may provide free training for producers and workers.","zh":"公平貿易可能為生產者和工人提供免費培訓。"},{"en":"Free training is instruction or skills development provided without charge.","zh":"免費培訓，是不收費提供的指導或技能發展。"},{"en":"Training may help producers improve product quality or farming methods.","zh":"培訓可能幫助生產者改善產品質素或耕作方法。"},{"en":"It may also include literacy or environmental practices.","zh":"它也可能包括識字能力或環保做法。"},{"en":"The phrase identifies one benefit offered under fair trade.","zh":"這個詞組指出公平貿易下提供的一項好處。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":3},{"front":"fair-trade items","meaning":"公平貿易商品","examples":[{"en":"Tea, coffee, cocoa and cotton are major fair-trade items.","zh":"茶、咖啡、可可和棉花是主要公平貿易商品。"},{"en":"Fair-trade items are goods produced and sold under fair-trade principles.","zh":"公平貿易商品，是按公平貿易原則生產和銷售的商品。"},{"en":"They often include agricultural products and handicrafts.","zh":"它們通常包括農產品和手工藝品。"},{"en":"Consumers may choose these items because they believe producers are paid fairly.","zh":"消費者可能選擇這些商品，因為相信生產者獲得公平報酬。"},{"en":"The phrase refers to products carrying a fair-trade identity.","zh":"這個詞組指帶有公平貿易身份的產品。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":3},{"front":"major fair-trade items","meaning":"主要公平貿易商品","examples":[{"en":"Coffee and cocoa are major fair-trade items.","zh":"咖啡和可可是主要公平貿易商品。"},{"en":"Major fair-trade items are the most important or common products in fair trade.","zh":"主要公平貿易商品，是公平貿易中最重要或最常見的產品。"},{"en":"Coffee is especially visible in shops and café chains.","zh":"咖啡在商店和連鎖咖啡店中尤其常見。"},{"en":"Major items help consumers recognise the fair-trade system.","zh":"主要商品幫助消費者認識公平貿易制度。"},{"en":"The phrase highlights key product categories.","zh":"這個詞組突顯關鍵產品類別。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":3},{"front":"handicrafts","meaning":"手工藝品","examples":[{"en":"Handicrafts are among the major fair-trade items.","zh":"手工藝品屬於主要公平貿易商品。"},{"en":"Handicrafts are objects made by hand, often using traditional skills.","zh":"手工藝品，是通常使用傳統技能手工製作的物品。"},{"en":"Fair-trade handicrafts may include baskets, jewellery, textiles, or carvings.","zh":"公平貿易手工藝品可能包括籃子、首飾、紡織品或雕刻品。"},{"en":"Selling handicrafts can support small producers and local communities.","zh":"銷售手工藝品可以支持小型生產者和本地社區。"},{"en":"The word refers to handmade goods rather than factory products.","zh":"這個詞指手製商品，而不是工廠產品。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":3},{"front":"the most recognizable","meaning":"最容易辨認的","examples":[{"en":"Coffee is probably the most recognizable fair-trade item.","zh":"咖啡大概是最容易辨認的公平貿易商品。"},{"en":"The most recognizable means the easiest to identify or remember.","zh":"最容易辨認的，指最容易識別或記住的。"},{"en":"Many consumers recognise fair-trade coffee before other fair-trade goods.","zh":"許多消費者比其他公平貿易商品更先認識公平貿易咖啡。"},{"en":"A recognizable product helps a movement gain public awareness.","zh":"容易辨認的產品有助一場運動提高公眾意識。"},{"en":"The phrase describes familiarity.","zh":"這個詞組描述熟悉程度。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":4},{"front":"supermarket shelves","meaning":"超級市場貨架","examples":[{"en":"Fair-trade coffee is found on supermarket shelves.","zh":"公平貿易咖啡可以在超級市場貨架上找到。"},{"en":"Supermarket shelves are the display areas where products are placed for sale.","zh":"超級市場貨架，是商品擺放出售的展示區。"},{"en":"Seeing fair-trade goods on supermarket shelves makes them accessible to ordinary consumers.","zh":"在超級市場貨架上看到公平貿易商品，令普通消費者更容易購買。"},{"en":"Coffee on shelves can carry a fair-trade label.","zh":"貨架上的咖啡可以帶有公平貿易標籤。"},{"en":"The phrase describes a common retail location.","zh":"這個詞組描述常見零售地點。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":4},{"front":"café chains","meaning":"連鎖咖啡店","examples":[{"en":"Fair-trade coffee is also sold at café chains.","zh":"公平貿易咖啡也在連鎖咖啡店出售。"},{"en":"Café chains are groups of coffee shops operating under the same brand.","zh":"連鎖咖啡店，是以同一品牌營運的一組咖啡店。"},{"en":"Selling fair-trade coffee in café chains makes the product highly visible.","zh":"在連鎖咖啡店出售公平貿易咖啡，令產品更顯眼。"},{"en":"Large chains can influence consumer habits.","zh":"大型連鎖店可以影響消費者習慣。"},{"en":"The phrase identifies another place where fair-trade coffee is sold.","zh":"這個詞組指出公平貿易咖啡出售的另一地點。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":4},{"front":"in relation to","meaning":"相對於……而言","examples":[{"en":"Two million producers is a tiny number in relation to total global trade.","zh":"相對於全球貿易總量而言，二百萬生產者是一個很小的數字。"},{"en":"In relation to means compared with or considered against something else.","zh":"相對於某事而言，指與另一事物相比或對照來看。"},{"en":"Fair trade may be large socially but small in relation to all world trade.","zh":"公平貿易在社會意義上可能很大，但相對於整體世界貿易仍很小。"},{"en":"The phrase helps judge scale.","zh":"這個詞組有助判斷規模。"},{"en":"It often introduces a comparison.","zh":"它常引入比較。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":4},{"front":"total global trade","meaning":"全球貿易總量","examples":[{"en":"Fair-trade production is small compared with total global trade.","zh":"與全球貿易總量相比，公平貿易生產規模很小。"},{"en":"Total global trade means all international buying and selling of goods and services.","zh":"全球貿易總量，指所有國際商品和服務買賣。"},{"en":"Fair trade represents only a small part of this vast system.","zh":"公平貿易只代表這個龐大系統的一小部分。"},{"en":"The phrase gives the larger economic context.","zh":"這個詞組提供較大的經濟背景。"},{"en":"It helps readers understand the limits of fair trade’s scale.","zh":"它幫助讀者理解公平貿易規模上的限制。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":4},{"front":"fair-trade advocates","meaning":"公平貿易倡議者","examples":[{"en":"Fair-trade advocates maintain that the system has helped many people.","zh":"公平貿易倡議者主張該制度已幫助許多人。"},{"en":"Fair-trade advocates are people who support and promote fair trade.","zh":"公平貿易倡議者，是支持和推廣公平貿易的人。"},{"en":"They argue that producers benefit from fairer prices and better conditions.","zh":"他們認為生產者受惠於較公平價格和較好條件。"},{"en":"Advocates often defend the movement against criticism.","zh":"倡議者經常為該運動抵抗批評。"},{"en":"The phrase identifies supporters who actively argue for fair trade.","zh":"這個詞組指出積極為公平貿易發聲的支持者。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":4},{"front":"maintain that","meaning":"堅稱；主張","examples":[{"en":"Fair-trade advocates maintain that the system has had a positive impact.","zh":"公平貿易倡議者堅稱該制度帶來正面影響。"},{"en":"Maintain that means firmly state or argue that something is true.","zh":"堅稱或主張，指堅定地表示或論證某事為真。"},{"en":"Supporters maintain that fair trade improves producers’ lives.","zh":"支持者堅稱公平貿易改善生產者生活。"},{"en":"The phrase suggests confidence in a claim.","zh":"這個詞組表示對某項主張有信心。"},{"en":"It is often used when a view is disputed.","zh":"它常用於某觀點有爭議時。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":4},{"front":"have a positive impact on","meaning":"對……有正面影響","examples":[{"en":"Supporters believe fair trade has had a positive impact on many people.","zh":"支持者相信公平貿易對許多人有正面影響。"},{"en":"Have a positive impact on means produce a beneficial effect on someone or something.","zh":"對某人或某事有正面影響，指產生有益效果。"},{"en":"Fair trade may improve income, training, or working conditions.","zh":"公平貿易可能改善收入、培訓或工作條件。"},{"en":"A positive impact does not mean every problem is solved.","zh":"正面影響不代表每個問題都已解決。"},{"en":"The phrase describes beneficial influence.","zh":"這個詞組描述有益影響。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":4},{"front":"worldwide","meaning":"在全球各地","examples":[{"en":"Fair trade may have helped many people worldwide.","zh":"公平貿易可能幫助了全球各地許多人。"},{"en":"Worldwide means across the whole world.","zh":"在全球各地，指遍及整個世界。"},{"en":"The movement includes producers and consumers in many countries worldwide.","zh":"該運動包括全球多國的生產者和消費者。"},{"en":"The phrase stresses global reach.","zh":"這個詞組強調全球範圍。"},{"en":"It shows that fair trade is not limited to one region.","zh":"它顯示公平貿易不只限於一個地區。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":4},{"front":"critics claim that","meaning":"批評者聲稱","examples":[{"en":"Critics claim that fair-trade producers might earn more elsewhere.","zh":"批評者聲稱公平貿易生產者在其他地方可能賺得更多。"},{"en":"Critics claim that means opponents say or argue that something is true.","zh":"批評者聲稱，指反對者說或主張某事為真。"},{"en":"Critics claim that the system may not help the poorest farmers.","zh":"批評者聲稱該制度可能無法幫助最貧窮的農民。"},{"en":"The phrase introduces a negative or questioning view.","zh":"這個詞組引入負面或質疑觀點。"},{"en":"It signals that the writer is presenting criticism.","zh":"它表示作者正在呈現批評。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":4},{"front":"return to","meaning":"回到","examples":[{"en":"Some critics say producers should return to the mainstream trading system.","zh":"一些批評者說生產者應回到主流貿易制度。"},{"en":"Return to means go back to a previous place, system, or condition.","zh":"回到，指返回先前的地方、制度或狀態。"},{"en":"Producers might return to ordinary markets if fair trade does not pay enough.","zh":"如果公平貿易支付不足，生產者可能回到普通市場。"},{"en":"The phrase suggests leaving the fair-trade system.","zh":"這個詞組表示離開公平貿易制度。"},{"en":"It is used to discuss an alternative path.","zh":"它用於討論另一條路徑。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":4},{"front":"mainstream trading system","meaning":"主流貿易制度","examples":[{"en":"Critics argue that producers might earn more in the mainstream trading system.","zh":"批評者認為生產者在主流貿易制度中可能賺得更多。"},{"en":"The mainstream trading system is the normal open-market system outside fair trade.","zh":"主流貿易制度，是公平貿易以外的一般公開市場制度。"},{"en":"Critics believe ordinary markets may sometimes pay higher prices.","zh":"批評者相信普通市場有時可能支付較高價格。"},{"en":"The phrase contrasts with the alternative fair-trade model.","zh":"這個詞組與另類公平貿易模式形成對比。"},{"en":"It refers to the dominant way global trade usually works.","zh":"它指全球貿易通常運作的主導方式。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":5},{"front":"receive higher prices","meaning":"收到較高價格","examples":[{"en":"Critics claim producers would receive higher prices outside fair trade.","zh":"批評者聲稱生產者在公平貿易以外會收到較高價格。"},{"en":"Receive higher prices means be paid more money for goods or labour.","zh":"收到較高價格，指因商品或勞動而獲得更多金錢。"},{"en":"A farmer may receive higher prices when market demand is strong.","zh":"當市場需求強勁時，農民可能收到較高價格。"},{"en":"The phrase is used in criticism of fair-trade pricing.","zh":"這個詞組用於批評公平貿易定價。"},{"en":"It questions whether fair trade always benefits producers financially.","zh":"它質疑公平貿易是否總是在財務上有利於生產者。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":5},{"front":"goods or labour","meaning":"商品或勞動","examples":[{"en":"Producers may receive payment for their goods or labour.","zh":"生產者可能因其商品或勞動而獲得付款。"},{"en":"Goods are products, while labour is work done by people.","zh":"商品是產品，而勞動是人所做的工作。"},{"en":"Fair trade aims to pay producers fairly for both goods and labour.","zh":"公平貿易旨在公平支付生產者的商品和勞動。"},{"en":"The phrase covers what producers sell or contribute.","zh":"這個詞組涵蓋生產者出售或貢獻的東西。"},{"en":"It is central to discussions of fair payment.","zh":"它是公平報酬討論的核心。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":5},{"front":"be supposed to be","meaning":"理應是","examples":[{"en":"Fair trade is supposed to be a system that is fair to producers.","zh":"公平貿易理應是一個對生產者公平的制度。"},{"en":"Be supposed to be means be expected or intended to be something.","zh":"理應是，指被期望或設計成某種情況。"},{"en":"Fair trade is supposed to protect producers from unfair market conditions.","zh":"公平貿易理應保護生產者免受不公平市場條件影響。"},{"en":"The phrase can imply that reality may not match the intention.","zh":"這個詞組可以暗示現實未必符合原意。"},{"en":"It introduces the ideal purpose of the system.","zh":"它引入該制度的理想目的。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":5},{"front":"basic tenet","meaning":"基本原則","examples":[{"en":"The basic tenet of fair trade is that consumers pay slightly more.","zh":"公平貿易的基本原則是消費者支付略高價格。"},{"en":"A basic tenet is a central principle or belief.","zh":"基本原則，是核心原則或信念。"},{"en":"Fair trade’s basic tenet connects higher consumer prices with fairer producer payment.","zh":"公平貿易的基本原則把較高消費價格與較公平生產者報酬連接起來。"},{"en":"The phrase identifies the foundation of an idea.","zh":"這個詞組指出一個理念的基礎。"},{"en":"It is often used in formal discussion.","zh":"它常用於正式討論。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":5},{"front":"end products","meaning":"最終產品","examples":[{"en":"Consumers pay slightly more for end products under fair trade.","zh":"在公平貿易下，消費者為最終產品支付略高價格。"},{"en":"End products are finished goods sold to consumers.","zh":"最終產品，是出售給消費者的完成商品。"},{"en":"Coffee on a supermarket shelf is an end product.","zh":"超市貨架上的咖啡就是最終產品。"},{"en":"Fair-trade end products may cost more because of producer premiums and certification.","zh":"公平貿易最終產品可能因生產者補貼和認證而價格較高。"},{"en":"The phrase contrasts finished goods with raw materials.","zh":"這個詞組把完成商品與原材料作對比。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":5},{"front":"in the knowledge that","meaning":"知道……而","examples":[{"en":"Consumers pay more in the knowledge that producers are fairly paid.","zh":"消費者知道生產者獲得公平報酬而支付更多。"},{"en":"In the knowledge that means because they know or believe something is true.","zh":"知道某事而，指因知道或相信某事為真而做某事。"},{"en":"People may buy fair-trade coffee in the knowledge that farmers should benefit.","zh":"人們可能知道農民應該受益而購買公平貿易咖啡。"},{"en":"The phrase explains the moral reason behind paying more.","zh":"這個詞組解釋支付更多背後的道德理由。"},{"en":"It connects consumer choice with ethical belief.","zh":"它把消費者選擇與道德信念連接起來。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":5},{"front":"developing-world producers","meaning":"發展中國家的生產者","examples":[{"en":"Fair trade aims to remunerate developing-world producers fairly.","zh":"公平貿易旨在公平酬報發展中國家的生產者。"},{"en":"Developing-world producers are producers in poorer or less industrialised countries.","zh":"發展中國家的生產者，是較貧窮或工業化程度較低國家的生產者。"},{"en":"They may include farmers, craft workers, and plantation workers.","zh":"他們可能包括農民、手工藝人和種植園工人。"},{"en":"Fair trade claims to improve their income and working conditions.","zh":"公平貿易聲稱改善他們的收入和工作條件。"},{"en":"The phrase identifies the intended beneficiaries of the system.","zh":"這個詞組指出該制度原本希望受益的人。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":5},{"front":"be equitably remunerated","meaning":"獲得公平報酬","examples":[{"en":"Fair-trade producers should be equitably remunerated.","zh":"公平貿易生產者應獲得公平報酬。"},{"en":"Be equitably remunerated means be paid fairly and justly.","zh":"獲得公平報酬，指得到公平而公正的付款。"},{"en":"Producers should receive payment that reflects their work and needs.","zh":"生產者應獲得反映其工作和需要的報酬。"},{"en":"The phrase is formal and often used in labour or economic contexts.","zh":"這個詞組較正式，常用於勞工或經濟語境。"},{"en":"It expresses one of fair trade’s ethical goals.","zh":"它表達公平貿易其中一項道德目標。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":5},{"front":"decent circumstances","meaning":"合理而體面的環境","examples":[{"en":"Fair-trade goods should be made in decent circumstances.","zh":"公平貿易商品應在合理而體面的環境中製造。"},{"en":"Decent circumstances are acceptable, safe, and respectful working conditions.","zh":"合理而體面的環境，是可接受、安全且尊重人的工作條件。"},{"en":"Workers should not produce goods in dangerous or exploitative environments.","zh":"工人不應在危險或剝削性的環境中生產商品。"},{"en":"The phrase refers to more than wages alone.","zh":"這個詞組涉及的不只是工資。"},{"en":"It includes dignity, safety, and basic rights.","zh":"它包括尊嚴、安全和基本權利。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":5},{"front":"differ from","meaning":"與……不同","examples":[{"en":"The fair-trade system differs from the open market.","zh":"公平貿易制度與公開市場不同。"},{"en":"Differ from means be unlike or distinct from something else.","zh":"與某事不同，指不像某事或與某事有區別。"},{"en":"Fair-trade prices differ from ordinary market prices because they include minimum protections.","zh":"公平貿易價格與普通市場價格不同，因為它包含最低保障。"},{"en":"The phrase introduces contrast.","zh":"這個詞組引入對比。"},{"en":"It helps explain what makes fair trade unusual.","zh":"它有助解釋公平貿易有何特別。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":5},{"front":"the open market","meaning":"公開市場","examples":[{"en":"Fair-trade prices may be higher than those of the open market.","zh":"公平貿易價格可能高於公開市場價格。"},{"en":"The open market is the ordinary market where prices are determined by supply and demand.","zh":"公開市場，是由供應和需求決定價格的一般市場。"},{"en":"Farmers selling on the open market may receive changing prices.","zh":"在公開市場出售商品的農民可能收到波動價格。"},{"en":"Fair trade sets prices differently from the open market.","zh":"公平貿易設定價格的方式與公開市場不同。"},{"en":"The phrase represents mainstream trading conditions.","zh":"這個詞組代表主流貿易條件。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":6},{"front":"minimum price","meaning":"最低價格","examples":[{"en":"Fair trade sets a minimum price for goods.","zh":"公平貿易為商品設定最低價格。"},{"en":"A minimum price is the lowest price that may be paid.","zh":"最低價格，是可以支付的最低價格。"},{"en":"Minimum prices protect producers when market prices fall.","zh":"當市場價格下跌時，最低價格保護生產者。"},{"en":"This is one reason fair trade differs from the open market.","zh":"這是公平貿易不同於公開市場的原因之一。"},{"en":"The phrase describes a price safety net.","zh":"這個詞組描述價格安全網。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":6},{"front":"higher than","meaning":"高於","examples":[{"en":"The fair-trade price may be higher than the open-market price.","zh":"公平貿易價格可能高於公開市場價格。"},{"en":"Higher than means greater in amount or level than something else.","zh":"高於，指在數量或水平上比另一事物更大。"},{"en":"A fair-trade price can be higher than ordinary market rates.","zh":"公平貿易價格可以高於普通市場價格。"},{"en":"The phrase creates a direct comparison.","zh":"這個詞組建立直接比較。"},{"en":"It helps explain why consumers may pay more.","zh":"它有助解釋為何消費者可能支付更多。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":6},{"front":"a small premium","meaning":"小額額外補貼","examples":[{"en":"A small premium is added in good years.","zh":"在好年份會加入小額額外補貼。"},{"en":"A small premium is an extra payment added to the basic price.","zh":"小額額外補貼，是加在基本價格上的額外款項。"},{"en":"Fair-trade premiums may support schools, wells, or community projects.","zh":"公平貿易補貼可能支持學校、水井或社區項目。"},{"en":"The phrase suggests the extra amount is limited but purposeful.","zh":"這個詞組表示額外金額有限但有特定目的。"},{"en":"It is part of the fair-trade pricing system.","zh":"它是公平貿易定價制度的一部分。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":6},{"front":"be earmarked for","meaning":"被指定用於","examples":[{"en":"The premium is earmarked for community development.","zh":"補貼被指定用於社區發展。"},{"en":"Be earmarked for means be reserved or set aside for a specific purpose.","zh":"被指定用於，指被保留或撥作特定用途。"},{"en":"Extra payments may be earmarked for education or health projects.","zh":"額外款項可能被指定用於教育或健康項目。"},{"en":"The phrase shows that money cannot be used freely for anything.","zh":"這個詞組顯示金錢不能隨意用於任何事情。"},{"en":"It connects fair-trade premiums with community goals.","zh":"它把公平貿易補貼與社區目標連接起來。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":6},{"front":"community development","meaning":"社區發展","examples":[{"en":"Fair-trade premiums are often used for community development.","zh":"公平貿易補貼經常用於社區發展。"},{"en":"Community development means improving local facilities, services, and living conditions.","zh":"社區發展，指改善本地設施、服務和生活條件。"},{"en":"It may include schools, roads, healthcare, or clean water projects.","zh":"它可能包括學校、道路、醫療或清潔食水項目。"},{"en":"Fair trade claims to benefit not only individuals but also communities.","zh":"公平貿易聲稱不只令個人受惠，也令社區受惠。"},{"en":"The phrase describes a social purpose of fair-trade premiums.","zh":"這個詞組描述公平貿易補貼的社會用途。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":6},{"front":"coffee co-operatives","meaning":"咖啡合作社","examples":[{"en":"Coffee co-operatives in South America may receive extra payments.","zh":"南美洲的咖啡合作社可能收到額外款項。"},{"en":"Coffee co-operatives are groups of coffee producers who work together and share benefits.","zh":"咖啡合作社，是咖啡生產者共同合作並分享利益的團體。"},{"en":"Co-operatives can help small farmers sell collectively.","zh":"合作社可以幫助小農戶集體出售產品。"},{"en":"Fair trade often works with co-operatives rather than isolated individuals.","zh":"公平貿易通常與合作社合作，而不是與孤立個人合作。"},{"en":"The phrase identifies an organised producer group.","zh":"這個詞組指出有組織的生產者群體。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":6},{"front":"additional 25 cents per kilogram","meaning":"每公斤額外25美仙","examples":[{"en":"Some coffee co-operatives receive an additional 25 cents per kilogram.","zh":"一些咖啡合作社每公斤收到額外 25 美仙。"},{"en":"Additional 25 cents per kilogram means an extra payment of twenty-five cents for each kilogram sold.","zh":"每公斤額外 25 美仙，指每售出一公斤便額外支付二十五美仙。"},{"en":"This extra amount may form part of a fair-trade premium.","zh":"這筆額外款項可能構成公平貿易補貼的一部分。"},{"en":"The phrase gives a specific example of extra payment.","zh":"這個詞組提供額外付款的具體例子。"},{"en":"It helps make the pricing system concrete.","zh":"它令定價制度更具體。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":6},{"front":"purchasers of fair-trade products","meaning":"公平貿易產品買家","examples":[{"en":"Purchasers of fair-trade products may assist producers with financing.","zh":"公平貿易產品買家可能協助生產者融資。"},{"en":"Purchasers of fair-trade products are buyers who purchase goods under fair-trade conditions.","zh":"公平貿易產品買家，是在公平貿易條件下購買商品的買方。"},{"en":"They may include importers, companies, or retail organisations.","zh":"他們可能包括進口商、公司或零售組織。"},{"en":"These purchasers may support producers beyond simply buying goods.","zh":"這些買家可能不只是購買商品，也支持生產者。"},{"en":"The phrase identifies buyers within the fair-trade system.","zh":"這個詞組指出公平貿易制度中的買方。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":6},{"front":"assist with","meaning":"協助……","examples":[{"en":"Purchasers may assist with crop pre-financing or training.","zh":"買家可能協助農作物預先融資或培訓。"},{"en":"Assist with means help with a task, need, or process.","zh":"協助某事，指幫助完成某項任務、需要或過程。"},{"en":"Fair-trade buyers may assist with improving product quality.","zh":"公平貿易買家可能協助改善產品質素。"},{"en":"Assistance can be financial, technical, or educational.","zh":"協助可以是財務、技術或教育方面的。"},{"en":"The phrase describes practical help.","zh":"這個詞組描述實際幫助。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":6},{"front":"crop pre-financing","meaning":"農作物預先融資","examples":[{"en":"Some purchasers help with crop pre-financing.","zh":"一些買家幫助農作物預先融資。"},{"en":"Crop pre-financing means providing money before crops are harvested or sold.","zh":"農作物預先融資，指在作物收割或出售前提供金錢。"},{"en":"Pre-financing can help farmers buy seeds, tools, or fertilisers.","zh":"預先融資可以幫助農民購買種子、工具或肥料。"},{"en":"It reduces the pressure of waiting for payment after harvest.","zh":"它減少農民等到收成後才收款的壓力。"},{"en":"The phrase describes early financial support for producers.","zh":"這個詞組描述對生產者的早期財務支援。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":6},{"front":"take the form of","meaning":"以……形式出現","examples":[{"en":"Training may take the form of improving product quality.","zh":"培訓可能以改善產品質素的形式出現。"},{"en":"Take the form of means appear as or be provided as a particular type of activity.","zh":"以某形式出現，指呈現為或提供為某種活動形式。"},{"en":"Support may take the form of loans, advice, or education.","zh":"支援可能以貸款、建議或教育形式出現。"},{"en":"The phrase explains what an abstract idea looks like in practice.","zh":"這個詞組解釋抽象想法在實際上如何呈現。"},{"en":"It is useful when listing examples.","zh":"它適合用於列舉例子。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":7},{"front":"improving product quality","meaning":"改善產品質素","examples":[{"en":"Training may focus on improving product quality.","zh":"培訓可能集中於改善產品質素。"},{"en":"Improving product quality means making goods better, more reliable, or more attractive to buyers.","zh":"改善產品質素，指令商品更好、更可靠或更吸引買家。"},{"en":"Farmers may learn better processing methods to improve quality.","zh":"農民可能學習更好的加工方法來改善質素。"},{"en":"Higher quality can help producers sell goods more successfully.","zh":"較高質素可以幫助生產者更成功地出售商品。"},{"en":"The phrase describes one aim of fair-trade training.","zh":"這個詞組描述公平貿易培訓的一個目標。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":7},{"front":"environmentally friendly fertilisers","meaning":"環保肥料","examples":[{"en":"Producers may learn to use environmentally friendly fertilisers.","zh":"生產者可能學習使用環保肥料。"},{"en":"Environmentally friendly fertilisers are fertilisers that cause less harm to soil, water, and ecosystems.","zh":"環保肥料，是對土壤、水和生態系統傷害較少的肥料。"},{"en":"Training may encourage farmers to avoid damaging chemicals.","zh":"培訓可能鼓勵農民避免有害化學品。"},{"en":"Such fertilisers support the environmental side of fair trade.","zh":"這些肥料支持公平貿易中的環境面向。"},{"en":"The phrase links farming practice with ecological responsibility.","zh":"這個詞組把耕作方法與生態責任連接起來。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":7},{"front":"raising literacy","meaning":"提高識字能力","examples":[{"en":"Training may include raising literacy among workers.","zh":"培訓可能包括提高工人的識字能力。"},{"en":"Raising literacy means improving people’s ability to read and write.","zh":"提高識字能力，指改善人們閱讀和書寫的能力。"},{"en":"Literacy can help workers understand contracts, labels, and safety instructions.","zh":"識字能力可以幫助工人理解合約、標籤和安全指示。"},{"en":"Fair-trade training may therefore include basic education.","zh":"因此，公平貿易培訓可能包括基礎教育。"},{"en":"The phrase describes a social benefit beyond production.","zh":"這個詞組描述生產以外的社會效益。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":7},{"front":"research has shown that","meaning":"研究顯示","examples":[{"en":"Research has shown that some fair-trade practices are copied.","zh":"研究顯示一些公平貿易做法被模仿。"},{"en":"Research has shown that means studies have provided evidence for a claim.","zh":"研究顯示，指研究已為某項主張提供證據。"},{"en":"The phrase introduces findings rather than personal opinion.","zh":"這個詞組引入研究發現，而不是個人意見。"},{"en":"It gives the following statement more authority.","zh":"它令後面的陳述更具權威性。"},{"en":"In the passage, it supports the claim that fair-trade practices influence others.","zh":"在文章中，它支持公平貿易做法會影響其他人的說法。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":7},{"front":"non-fair-trade farmers","meaning":"非公平貿易農民","examples":[{"en":"Non-fair-trade farmers sometimes copy fair-trade farming practices.","zh":"非公平貿易農民有時會模仿公平貿易耕作方法。"},{"en":"Non-fair-trade farmers are farmers who are not part of the fair-trade system.","zh":"非公平貿易農民，是沒有參與公平貿易制度的農民。"},{"en":"They may still adopt techniques used by fair-trade producers.","zh":"他們仍可能採用公平貿易生產者使用的技術。"},{"en":"This suggests fair trade can influence people outside the system.","zh":"這表示公平貿易可以影響制度以外的人。"},{"en":"The phrase identifies farmers who are not certified fair-trade producers.","zh":"這個詞組指出並非公平貿易認證生產者的農民。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":7},{"front":"farming practices","meaning":"耕作方法","examples":[{"en":"Some fair-trade farming practices influence other farmers.","zh":"一些公平貿易耕作方法影響其他農民。"},{"en":"Farming practices are methods used to grow crops or manage farms.","zh":"耕作方法，是用來種植作物或管理農場的方法。"},{"en":"They may include fertiliser use, soil care, harvesting, and processing.","zh":"它們可能包括肥料使用、土壤護理、收割和加工。"},{"en":"Fair-trade farming practices may include environmental and labour standards.","zh":"公平貿易耕作方法可能包括環境和勞工標準。"},{"en":"The phrase describes how farming is actually done.","zh":"這個詞組描述農業實際如何進行。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":7},{"front":"encourage social progress","meaning":"促進社會進步","examples":[{"en":"Fair-trade practices may occasionally encourage social progress.","zh":"公平貿易做法有時可能促進社會進步。"},{"en":"Encourage social progress means help society become fairer, safer, or more educated.","zh":"促進社會進步，指幫助社會變得更公平、更安全或更有教育水平。"},{"en":"Literacy training and safer workplaces can encourage social progress.","zh":"識字培訓和安全工作場所可以促進社會進步。"},{"en":"The phrase suggests benefits beyond individual profit.","zh":"這個詞組表示好處不只限於個人利潤。"},{"en":"It presents fair trade as a possible driver of wider improvement.","zh":"它把公平貿易呈現為可能推動更廣泛改善的力量。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":7},{"front":"in exchange for","meaning":"作為……的交換","examples":[{"en":"Producers accept standards in exchange for ethical purchasing.","zh":"生產者接受標準，作為道德採購的交換。"},{"en":"In exchange for means in return for something else.","zh":"作為某事的交換，指作為回報而得到另一事物。"},{"en":"Producers may agree to rules in exchange for better market access.","zh":"生產者可能同意規則，以換取更好的市場准入。"},{"en":"The phrase describes a trade-off.","zh":"這個詞組描述交換或取捨。"},{"en":"It helps explain why producers accept fair-trade conditions.","zh":"它有助解釋生產者為何接受公平貿易條件。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":7},{"front":"ethical purchasing","meaning":"道德採購","examples":[{"en":"Fair-trade producers benefit from ethical purchasing.","zh":"公平貿易生產者受惠於道德採購。"},{"en":"Ethical purchasing is buying goods in a way that considers fairness, labour rights, and environmental impact.","zh":"道德採購，是以考慮公平、勞工權利和環境影響的方式購買商品。"},{"en":"Consumers choose fair-trade products because they see them as ethical.","zh":"消費者選擇公平貿易產品，因為他們認為這些產品合乎道德。"},{"en":"Ethical purchasing gives buyers a moral role in trade.","zh":"道德採購令買家在貿易中有道德角色。"},{"en":"The phrase links shopping decisions with values.","zh":"這個詞組把購物決定與價值觀連接起來。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":7},{"front":"child or slave labour","meaning":"童工或奴隸勞工","examples":[{"en":"Fair-trade producers agree not to use child or slave labour.","zh":"公平貿易生產者同意不使用童工或奴隸勞工。"},{"en":"Child labour involves children working in harmful or exploitative conditions.","zh":"童工涉及兒童在有害或剝削性條件下工作。"},{"en":"Slave labour means forced labour without freedom or fair payment.","zh":"奴隸勞工是沒有自由或公平報酬的強迫勞動。"},{"en":"Fair-trade standards reject both practices.","zh":"公平貿易標準拒絕這兩種做法。"},{"en":"The phrase identifies serious labour abuses.","zh":"這個詞組指出嚴重勞工剝削。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":7},{"front":"adhere to","meaning":"遵守","examples":[{"en":"Producers must adhere to international human-rights standards.","zh":"生產者必須遵守國際人權標準。"},{"en":"Adhere to means follow or obey rules, principles, or standards.","zh":"遵守，指跟從或服從規則、原則或標準。"},{"en":"Fair-trade producers must adhere to labour and environmental requirements.","zh":"公平貿易生產者必須遵守勞工和環境要求。"},{"en":"The phrase is formal and often used with laws or standards.","zh":"這個詞組較正式，常與法律或標準一起使用。"},{"en":"It describes compliance.","zh":"它描述合規行為。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":8},{"front":"United Nations Charter on Human Rights","meaning":"《聯合國人權憲章》","examples":[{"en":"Fair-trade producers agree to follow the United Nations Charter on Human Rights.","zh":"公平貿易生產者同意遵守《聯合國人權憲章》。"},{"en":"The United Nations Charter on Human Rights refers to international human-rights principles associated with the UN.","zh":"《聯合國人權憲章》指與聯合國相關的國際人權原則。"},{"en":"In the passage, it represents standards producers are expected to respect.","zh":"在文章中，它代表生產者被期望尊重的標準。"},{"en":"These standards relate to dignity, safety, and freedom from exploitation.","zh":"這些標準涉及尊嚴、安全和免受剝削。"},{"en":"The phrase gives fair-trade rules a global ethical basis.","zh":"這個詞組為公平貿易規則提供全球道德基礎。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":8},{"front":"provide safe workplaces","meaning":"提供安全工作場所","examples":[{"en":"Fair-trade producers must provide safe workplaces.","zh":"公平貿易生產者必須提供安全工作場所。"},{"en":"Provide safe workplaces means ensure workers are not exposed to unnecessary danger.","zh":"提供安全工作場所，指確保工人不會暴露於不必要危險中。"},{"en":"Safe workplaces may include proper equipment, training, and clean conditions.","zh":"安全工作場所可能包括適當設備、培訓和清潔環境。"},{"en":"This requirement is part of fair-trade labour standards.","zh":"這項要求是公平貿易勞工標準的一部分。"},{"en":"The phrase focuses on worker protection.","zh":"這個詞組集中於工人保護。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":8},{"front":"protect the environment","meaning":"保護環境","examples":[{"en":"Fair-trade producers must also protect the environment.","zh":"公平貿易生產者也必須保護環境。"},{"en":"Protect the environment means avoid damaging land, water, air, and ecosystems.","zh":"保護環境，指避免破壞土地、水、空氣和生態系統。"},{"en":"Farmers may protect the environment by using safer fertilisers.","zh":"農民可以透過使用較安全肥料來保護環境。"},{"en":"Environmental protection is part of many fair-trade standards.","zh":"環境保護是許多公平貿易標準的一部分。"},{"en":"The phrase links trade with ecological responsibility.","zh":"這個詞組把貿易與生態責任連接起來。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":8},{"front":"legally binding","meaning":"具法律約束力","examples":[{"en":"Some requirements are not legally binding in producers’ own countries.","zh":"一些要求在生產者自己的國家並不具法律約束力。"},{"en":"Legally binding means required by law and enforceable through legal authority.","zh":"具法律約束力，指由法律要求並可透過法律權力執行。"},{"en":"A rule may be morally important without being legally binding locally.","zh":"一項規則可能在道德上重要，但在本地並不具法律約束力。"},{"en":"Fair-trade standards may go beyond local legal requirements.","zh":"公平貿易標準可能超越本地法律要求。"},{"en":"The phrase distinguishes legal duty from voluntary agreement.","zh":"這個詞組區分法律義務與自願協議。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":8},{"front":"adopt these practices","meaning":"採納這些做法","examples":[{"en":"Few non-fair-trade farmers have adopted these practices.","zh":"很少非公平貿易農民採納這些做法。"},{"en":"Adopt these practices means begin to use these methods or standards.","zh":"採納這些做法，指開始使用這些方法或標準。"},{"en":"Farmers may adopt environmental practices after seeing fair-trade examples.","zh":"農民可能在看到公平貿易例子後採納環保做法。"},{"en":"The passage suggests adoption outside the system is limited.","zh":"文章表示制度以外的採納情況有限。"},{"en":"The phrase describes taking up new behaviour.","zh":"這個詞組描述接受新行為。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":8},{"front":"little more than","meaning":"只不過是","examples":[{"en":"Some farmers view these standards as little more than rich-world conceits.","zh":"一些農民把這些標準視為只不過是富裕國家自以為是的想法。"},{"en":"Little more than means almost only or merely.","zh":"只不過是，指幾乎只是或僅僅是。"},{"en":"Critics may see some standards as little more than symbolic gestures.","zh":"批評者可能把一些標準視為只不過是象徵姿態。"},{"en":"The phrase often reduces the importance of something.","zh":"這個詞組常降低某事的重要性。"},{"en":"It introduces a dismissive view.","zh":"它引入一種輕視的看法。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":8},{"front":"rich-world conceits","meaning":"富裕國家自以為是的想法","examples":[{"en":"Some farmers regard fair-trade standards as rich-world conceits.","zh":"一些農民把公平貿易標準視為富裕國家自以為是的想法。"},{"en":"Rich-world conceits are ideas from wealthy countries that may seem self-important or unrealistic.","zh":"富裕國家自以為是的想法，是來自富裕國家、可能顯得自大或不切實際的觀念。"},{"en":"Poor farmers may see some standards as imposed by outsiders.","zh":"貧困農民可能認為一些標準是外人強加的。"},{"en":"The phrase expresses resentment toward developed-world expectations.","zh":"這個詞組表達對已發展國家期望的不滿。"},{"en":"It presents a critical view of fair-trade conditions.","zh":"它呈現對公平貿易條件的批判看法。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":8},{"front":"under fair-trade conditions","meaning":"在公平貿易條件下","examples":[{"en":"Labels show whether goods are made under fair-trade conditions.","zh":"標籤顯示商品是否在公平貿易條件下製造。"},{"en":"Under fair-trade conditions means according to fair-trade rules and standards.","zh":"在公平貿易條件下，指按照公平貿易規則和標準。"},{"en":"These conditions may include fair pay, safe workplaces, and environmental protection.","zh":"這些條件可能包括公平報酬、安全工作場所和環境保護。"},{"en":"The phrase explains what certification is meant to indicate.","zh":"這個詞組解釋認證本應顯示甚麼。"},{"en":"It links labels with production standards.","zh":"它把標籤與生產標準連接起來。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":8},{"front":"single umbrella organisation","meaning":"單一傘式組織","examples":[{"en":"A single umbrella organisation supervises fair-trade labelling.","zh":"一個單一傘式組織監督公平貿易標籤工作。"},{"en":"A single umbrella organisation is one central body that coordinates several related activities or groups.","zh":"單一傘式組織，是協調多項相關活動或群體的一個中央機構。"},{"en":"It may oversee labelling, standards, and inspections.","zh":"它可能監督標籤、標準和審查。"},{"en":"The phrase suggests centralised control.","zh":"這個詞組表示集中式管理。"},{"en":"It helps explain how fair-trade certification is organised.","zh":"它有助解釋公平貿易認證如何組織。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":8},{"front":"supervise labelling","meaning":"監督標籤工作","examples":[{"en":"An umbrella organisation supervises labelling and inspection.","zh":"傘式組織監督標籤工作和審查。"},{"en":"Supervise labelling means oversee how products receive and display labels.","zh":"監督標籤工作，指監管產品如何取得和展示標籤。"},{"en":"This helps consumers identify fair-trade goods.","zh":"這有助消費者識別公平貿易商品。"},{"en":"Supervision is needed because labels can be misused.","zh":"由於標籤可能被濫用，因此需要監督。"},{"en":"The phrase describes one function of certification bodies.","zh":"這個詞組描述認證機構的一項功能。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":8},{"front":"standardisation","meaning":"標準化","examples":[{"en":"The organisation supervises labelling, standardisation and inspection.","zh":"該組織監督標籤、標準化和審查。"},{"en":"Standardisation means making rules or procedures consistent.","zh":"標準化，指令規則或程序保持一致。"},{"en":"Fair-trade standardisation helps different producers follow similar requirements.","zh":"公平貿易標準化幫助不同生產者遵守相似要求。"},{"en":"It allows consumers to trust that labels mean the same thing.","zh":"它讓消費者相信標籤代表同一意思。"},{"en":"The word refers to creating uniform standards.","zh":"這個詞指建立統一標準。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":9},{"front":"inspection","meaning":"檢查；審查","examples":[{"en":"Inspection is part of the fair-trade certification system.","zh":"檢查是公平貿易認證制度的一部分。"},{"en":"Inspection means checking whether rules or standards are being followed.","zh":"檢查或審查，指查看規則或標準是否被遵守。"},{"en":"Inspectors may examine workplaces, records, or farming methods.","zh":"檢查員可能檢視工作場所、記錄或耕作方法。"},{"en":"Without inspection, labels may become unreliable.","zh":"沒有檢查，標籤可能變得不可靠。"},{"en":"The word describes a monitoring process.","zh":"這個詞描述監察程序。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":9},{"front":"far from perfect","meaning":"遠非完美","examples":[{"en":"The fair-trade system is far from perfect.","zh":"公平貿易制度遠非完美。"},{"en":"Far from perfect means having many weaknesses or problems.","zh":"遠非完美，指有許多弱點或問題。"},{"en":"The system may help some producers while excluding others.","zh":"該制度可能幫助一些生產者，同時排除另一些人。"},{"en":"The phrase introduces criticism after describing ideals.","zh":"這個詞組在描述理想後引入批評。"},{"en":"It means something is useful but seriously flawed.","zh":"它表示某事可能有用，但仍有嚴重缺陷。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":9},{"front":"first and foremost","meaning":"首先；最重要的是","examples":[{"en":"First and foremost, certification can be expensive.","zh":"首先，認證可能很昂貴。"},{"en":"First and foremost means most importantly or before anything else.","zh":"首先或最重要的是，指最主要或先於其他事情。"},{"en":"The phrase introduces the writer’s main criticism.","zh":"這個詞組引入作者的主要批評。"},{"en":"Certification costs may stop the poorest farmers from joining.","zh":"認證費用可能阻止最貧窮農民加入。"},{"en":"It signals priority in an argument.","zh":"它在論證中標示優先次序。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":9},{"front":"expenses involved in","meaning":"涉及……的費用","examples":[{"en":"There are expenses involved in becoming a certified producer.","zh":"成為認證生產者涉及費用。"},{"en":"Expenses involved in something are the costs required to do it.","zh":"涉及某事的費用，是做該事所需的成本。"},{"en":"Certification may involve fees, inspections, paperwork, and changes to practice.","zh":"認證可能涉及費用、檢查、文書工作和做法改變。"},{"en":"These expenses can be too high for poor farmers.","zh":"這些費用對貧困農民而言可能太高。"},{"en":"The phrase highlights financial barriers.","zh":"這個詞組突顯財務障礙。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":9},{"front":"fair-trade-certified producer","meaning":"獲公平貿易認證的生產者","examples":[{"en":"It can be costly to become a fair-trade-certified producer.","zh":"成為獲公平貿易認證的生產者可能成本很高。"},{"en":"A fair-trade-certified producer is a producer officially approved under fair-trade standards.","zh":"獲公平貿易認證的生產者，是按公平貿易標準正式獲批准的生產者。"},{"en":"Certification allows products to be sold with a fair-trade label.","zh":"認證讓產品可以帶有公平貿易標籤出售。"},{"en":"The process may require inspection and compliance with rules.","zh":"該過程可能需要檢查和遵守規則。"},{"en":"The phrase identifies producers formally inside the fair-trade system.","zh":"這個詞組指出正式屬於公平貿易制度的生產者。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":9},{"front":"the desperately poor","meaning":"極度貧困的人","examples":[{"en":"The desperately poor rarely participate in fair trade.","zh":"極度貧困的人很少參與公平貿易。"},{"en":"The desperately poor are people who are extremely poor and lack basic resources.","zh":"極度貧困的人，是非常貧窮並缺乏基本資源的人。"},{"en":"They may not afford certification costs or required changes.","zh":"他們可能無法負擔認證費用或所需改變。"},{"en":"This is a serious criticism of fair trade.","zh":"這是對公平貿易的一項嚴重批評。"},{"en":"The phrase identifies the people fair trade most hoped to help.","zh":"這個詞組指出公平貿易最希望幫助的人。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":9},{"front":"rarely participate","meaning":"很少參與","examples":[{"en":"The poorest farmers rarely participate in the system.","zh":"最貧窮的農民很少參與該制度。"},{"en":"Rarely participate means seldom take part.","zh":"很少參與，指很少加入或參加。"},{"en":"Farmers may rarely participate because certification is expensive.","zh":"農民可能因認證昂貴而很少參與。"},{"en":"The phrase suggests that involvement is limited.","zh":"這個詞組表示參與程度有限。"},{"en":"It points to exclusion from the fair-trade system.","zh":"它指出人們被排除在公平貿易制度之外。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":9},{"front":"the very farmers","meaning":"正正是那些農民","examples":[{"en":"The very farmers fair-trade advocates hoped to help may be excluded.","zh":"公平貿易倡議者希望幫助的正正是那些農民，卻可能被排除在外。"},{"en":"The very farmers means exactly those farmers being discussed.","zh":"正正是那些農民，指正是正在討論的那些農民。"},{"en":"The phrase creates irony because the intended beneficiaries may not benefit.","zh":"這個詞組造成諷刺，因為原本希望受惠的人可能沒有受惠。"},{"en":"Fair trade may exclude the poorest farmers through high entry costs.","zh":"公平貿易可能透過高入場成本排除最貧窮農民。"},{"en":"It emphasises a contradiction in the system.","zh":"它強調制度中的矛盾。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":9},{"front":"be excluded","meaning":"被排除在外","examples":[{"en":"The poorest farmers are often excluded from fair trade.","zh":"最貧窮的農民經常被排除在公平貿易之外。"},{"en":"Be excluded means be left out or prevented from taking part.","zh":"被排除在外，指被排除或被阻止參與。"},{"en":"High certification costs may exclude poor producers.","zh":"高昂認證成本可能排除貧困生產者。"},{"en":"Exclusion weakens the claim that fair trade helps the poorest.","zh":"排除現象削弱了公平貿易幫助最貧困者的說法。"},{"en":"The phrase describes being kept outside a system.","zh":"這個詞組描述被阻隔在制度外。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":9},{"front":"conforming to","meaning":"符合；遵從","examples":[{"en":"Conforming to fair-trade standards is costly.","zh":"符合公平貿易標準成本很高。"},{"en":"Conforming to means meeting or following rules and requirements.","zh":"符合或遵從，指達到或跟隨規則和要求。"},{"en":"Producers may need to change farming or labour practices to conform.","zh":"生產者可能需要改變耕作或勞工做法來符合標準。"},{"en":"The phrase suggests effort and expense.","zh":"這個詞組表示需要努力和費用。"},{"en":"It describes compliance with certification standards.","zh":"它描述遵守認證標準。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":9},{"front":"standards of certification","meaning":"認證標準","examples":[{"en":"The standards of fair-trade certification can be expensive to meet.","zh":"公平貿易認證標準可能很昂貴才能達到。"},{"en":"Standards of certification are the rules producers must satisfy to be certified.","zh":"認證標準，是生產者必須符合才能獲認證的規則。"},{"en":"They may involve labour rights, environmental rules, and inspections.","zh":"它們可能涉及勞工權利、環境規則和檢查。"},{"en":"Meeting these standards can require money and organisation.","zh":"達到這些標準可能需要金錢和組織能力。"},{"en":"The phrase identifies the requirements of certification.","zh":"這個詞組指出認證要求。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":10},{"front":"deliberately mislabel","meaning":"故意錯誤標籤","examples":[{"en":"Some producers deliberately mislabel their goods.","zh":"一些生產者故意錯誤標籤其商品。"},{"en":"Deliberately mislabel means knowingly put an incorrect label on products.","zh":"故意錯誤標籤，指明知不正確仍把錯誤標籤貼在產品上。"},{"en":"Producers may mislabel goods as fair trade to gain higher prices.","zh":"生產者可能把商品錯誤標示為公平貿易，以取得較高價格。"},{"en":"The phrase suggests fraud or dishonesty.","zh":"這個詞組暗示欺詐或不誠實。"},{"en":"It is one problem caused by weak monitoring.","zh":"它是監察薄弱造成的一個問題。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":10},{"front":"monitoring process","meaning":"監察程序","examples":[{"en":"The fair-trade monitoring process is patchy.","zh":"公平貿易監察程序參差不齊。"},{"en":"A monitoring process is a system for checking whether rules are being followed.","zh":"監察程序，是檢查規則是否被遵守的制度。"},{"en":"Fair-trade monitoring should verify labels and production conditions.","zh":"公平貿易監察應核實標籤和生產條件。"},{"en":"If monitoring is weak, dishonest labelling can occur.","zh":"如果監察薄弱，便可能出現不誠實標籤。"},{"en":"The phrase refers to oversight and control.","zh":"這個詞組指監督和管控。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":10},{"front":"patchy","meaning":"不全面的；參差不齊的","examples":[{"en":"The monitoring process is patchy and unreliable in some cases.","zh":"監察程序在某些情況下不全面且不可靠。"},{"en":"Patchy means incomplete, uneven, or inconsistent.","zh":"不全面的或參差不齊的，指不完整、不均衡或不一致。"},{"en":"Patchy monitoring may check some producers carefully but miss others.","zh":"參差的監察可能仔細檢查一些生產者，卻遺漏另一些。"},{"en":"The word suggests that the system does not work reliably everywhere.","zh":"這個詞表示該制度並非到處都可靠運作。"},{"en":"It is used negatively in the passage.","zh":"它在文章中帶負面意思。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":10},{"front":"fair-trade-labelled produce","meaning":"標示為公平貿易的農產品","examples":[{"en":"Some fair-trade-labelled produce is not actually fair trade.","zh":"一些標示為公平貿易的農產品實際上並不是公平貿易。"},{"en":"Fair-trade-labelled produce is agricultural produce marked as fair trade.","zh":"標示為公平貿易的農產品，是帶有公平貿易標示的農產品。"},{"en":"Labels may mislead consumers if the goods were not produced under fair-trade conditions.","zh":"如果商品並非在公平貿易條件下生產，標籤可能誤導消費者。"},{"en":"The phrase highlights a problem with certification reliability.","zh":"這個詞組突顯認證可靠性的問題。"},{"en":"It distinguishes labels from actual production conditions.","zh":"它區分標籤與實際生產條件。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":10},{"front":"nothing of the kind","meaning":"根本不是那回事","examples":[{"en":"Around 12% of fair-trade-labelled produce is nothing of the kind.","zh":"約 12% 標示為公平貿易的農產品根本不是那回事。"},{"en":"Nothing of the kind means not that thing at all.","zh":"根本不是那回事，指完全不是那種東西。"},{"en":"A product labelled fair trade may be nothing of the kind if it was mislabelled.","zh":"如果產品被錯誤標籤，即使標示為公平貿易，也可能根本不是。"},{"en":"The phrase strongly rejects the label’s claim.","zh":"這個詞組強烈否定標籤聲稱。"},{"en":"It suggests serious misrepresentation.","zh":"它表示嚴重誤導。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":10},{"front":"genuinely be produced under","meaning":"確實在……條件下生產","examples":[{"en":"A crop may genuinely be produced under fair-trade conditions.","zh":"一種作物可能確實在公平貿易條件下生產。"},{"en":"Genuinely be produced under means truly be made according to certain conditions.","zh":"確實在某條件下生產，指真正按照某些條件製造或種植。"},{"en":"Some crops are truly fair trade even if they cannot be sold as fair trade.","zh":"有些作物確實是公平貿易，即使不能作為公平貿易出售。"},{"en":"The phrase distinguishes real production conditions from market labelling.","zh":"這個詞組區分真實生產條件與市場標籤。"},{"en":"It shows that production and sale category may differ.","zh":"它顯示生產情況和銷售類別可能不同。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":10},{"front":"due to a lack of demand","meaning":"由於需求不足","examples":[{"en":"Some fair-trade crops cannot be sold as fair trade due to a lack of demand.","zh":"一些公平貿易作物由於需求不足，不能作為公平貿易出售。"},{"en":"Due to a lack of demand means because not enough buyers want the product.","zh":"由於需求不足，指因為沒有足夠買家想要該產品。"},{"en":"If consumers do not buy enough fair-trade coffee, some certified crops enter ordinary markets.","zh":"如果消費者購買的公平貿易咖啡不足，一些認證作物便會進入普通市場。"},{"en":"The phrase explains a market limitation.","zh":"這個詞組解釋市場限制。"},{"en":"It shows that certification alone does not guarantee sales.","zh":"它顯示認證本身並不保證銷售。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":10},{"front":"be sold as","meaning":"作為……出售","examples":[{"en":"Some products cannot be sold as fair trade.","zh":"一些產品不能作為公平貿易出售。"},{"en":"Be sold as means be marketed or offered under a particular category or label.","zh":"作為某類別出售，指以某特定類別或標籤進行市場銷售。"},{"en":"A crop may be produced fairly but sold as ordinary coffee.","zh":"一種作物可能公平生產，但作為普通咖啡出售。"},{"en":"The phrase concerns how a product is presented in the market.","zh":"這個詞組涉及產品在市場中如何被呈現。"},{"en":"It separates production from sales classification.","zh":"它把生產與銷售分類分開。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":10},{"front":"go onto the open market","meaning":"進入公開市場","examples":[{"en":"Unsold fair-trade crops may go onto the open market.","zh":"未能售出的公平貿易作物可能進入公開市場。"},{"en":"Go onto the open market means be sold in the ordinary market rather than through fair trade.","zh":"進入公開市場，指在普通市場而不是透過公平貿易出售。"},{"en":"A certified crop may enter the open market if fair-trade demand is too low.","zh":"如果公平貿易需求太低，認證作物可能進入公開市場。"},{"en":"This can reduce the producer’s expected benefit.","zh":"這可能減少生產者預期得到的好處。"},{"en":"The phrase describes what happens to surplus fair-trade output.","zh":"這個詞組描述公平貿易剩餘產量的去向。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":10},{"front":"it is estimated that","meaning":"據估計","examples":[{"en":"It is estimated that only part of fair-trade output is sold as fair trade.","zh":"據估計，只有部分公平貿易產量作為公平貿易出售。"},{"en":"It is estimated that means people calculate or judge approximately that something is true.","zh":"據估計，指人們大約計算或判斷某事為真。"},{"en":"Estimates are used when exact figures are difficult to know.","zh":"當準確數字難以得知時，會使用估計。"},{"en":"The phrase introduces an approximate research-based claim.","zh":"這個詞組引入基於研究的近似說法。"},{"en":"It is common in economic discussion.","zh":"它常見於經濟討論。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":10},{"front":"fair-trade output","meaning":"公平貿易產量","examples":[{"en":"Only a percentage of fair-trade output is actually sold as fair trade.","zh":"只有一定比例的公平貿易產量實際上作為公平貿易出售。"},{"en":"Fair-trade output means the total amount of goods produced under fair-trade conditions.","zh":"公平貿易產量，指在公平貿易條件下生產的商品總量。"},{"en":"Output can exceed demand in fair-trade markets.","zh":"公平貿易市場中的產量可能超過需求。"},{"en":"When this happens, some goods may be sold outside fair trade.","zh":"當這種情況發生時，一些商品可能在公平貿易以外出售。"},{"en":"The phrase refers to production volume.","zh":"這個詞組指生產量。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":11},{"front":"actually sold as","meaning":"實際上以……出售","examples":[{"en":"Only some fair-trade output is actually sold as fair trade.","zh":"只有一些公平貿易產量實際上以公平貿易出售。"},{"en":"Actually sold as means really marketed and purchased under that label or category.","zh":"實際上以某類別出售，指真正以該標籤或類別進行銷售和購買。"},{"en":"A crop may be certified but not actually sold as fair trade.","zh":"一種作物可能已獲認證，但實際上並非以公平貿易出售。"},{"en":"The phrase highlights the difference between certification and final sale.","zh":"這個詞組突顯認證與最終銷售之間的差異。"},{"en":"It is important in judging producer benefits.","zh":"它對判斷生產者收益很重要。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":11},{"front":"reliable research","meaning":"可靠研究","examples":[{"en":"There is little reliable research on fair-trade farmers’ profits.","zh":"關於公平貿易農民利潤的可靠研究很少。"},{"en":"Reliable research is research that is trustworthy, careful, and based on good evidence.","zh":"可靠研究，是可信、仔細並基於良好證據的研究。"},{"en":"Without reliable research, it is hard to know whether farmers truly profit.","zh":"沒有可靠研究，便難以知道農民是否真正盈利。"},{"en":"The phrase points to a weakness in knowledge about fair trade.","zh":"這個詞組指出人們對公平貿易認識上的弱點。"},{"en":"It introduces uncertainty in the debate.","zh":"它引入爭論中的不確定性。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":11},{"front":"real relationship between","meaning":"……之間的真實關係","examples":[{"en":"Researchers know little about the real relationship between costs and revenue.","zh":"研究人員很少了解成本與收入之間的真實關係。"},{"en":"The real relationship between two things means how they actually affect each other.","zh":"兩件事之間的真實關係，指它們實際上如何互相影響。"},{"en":"A farmer may receive more revenue but also face higher costs.","zh":"農民可能收到更多收入，但也面對更高成本。"},{"en":"The phrase asks whether income truly exceeds expenses.","zh":"這個詞組詢問收入是否真正超過開支。"},{"en":"It is important for measuring profit.","zh":"它對量度利潤很重要。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":11},{"front":"costs incurred","meaning":"已產生的成本","examples":[{"en":"Costs incurred by fair-trade farmers may be difficult to calculate.","zh":"公平貿易農民已產生的成本可能難以計算。"},{"en":"Costs incurred are expenses that have been paid or become necessary.","zh":"已產生的成本，是已支付或已成為必要的費用。"},{"en":"Farmers may incur costs for certification, harvesting, transport, and processing.","zh":"農民可能因認證、收割、運輸和加工而產生成本。"},{"en":"Ignoring incurred costs can make profits look larger than they are.","zh":"忽略已產生成本會令利潤看起來比實際更大。"},{"en":"The phrase is common in financial analysis.","zh":"這個詞組常見於財務分析。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":11},{"front":"revenue","meaning":"收入","examples":[{"en":"Revenue does not always exceed farmers’ costs.","zh":"收入並不總是超過農民成本。"},{"en":"Revenue is income received from selling goods or services.","zh":"收入，是出售商品或服務所得到的金錢。"},{"en":"A farmer’s revenue may rise under fair trade but costs may rise too.","zh":"農民在公平貿易下收入可能上升，但成本也可能上升。"},{"en":"Profit depends on revenue minus costs.","zh":"利潤取決於收入減去成本。"},{"en":"The word is central to evaluating fair-trade benefits.","zh":"這個詞對評估公平貿易好處很重要。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":11},{"front":"empirical evidence","meaning":"實證證據","examples":[{"en":"Empirical evidence suggests that many farmers never realise a profit.","zh":"實證證據顯示許多農民從未實現盈利。"},{"en":"Empirical evidence is evidence based on observation, data, or experience.","zh":"實證證據，是基於觀察、數據或經驗的證據。"},{"en":"It is stronger than opinion because it relies on measurable information.","zh":"它比意見更有力，因為它依賴可量度資料。"},{"en":"The phrase introduces research-based criticism of fair trade.","zh":"這個詞組引入對公平貿易的研究式批評。"},{"en":"It suggests that actual outcomes may not match ideals.","zh":"它表示實際結果可能不符合理想。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":11},{"front":"realise a profit","meaning":"實現盈利","examples":[{"en":"Many fair-trade farmers may never realise a profit.","zh":"許多公平貿易農民可能從未實現盈利。"},{"en":"Realise a profit means actually make money after costs are deducted.","zh":"實現盈利，指扣除成本後真正賺到錢。"},{"en":"Higher prices do not guarantee profit if costs are also high.","zh":"如果成本也很高，較高價格並不保證盈利。"},{"en":"The phrase focuses on final financial gain.","zh":"這個詞組集中於最終財務收益。"},{"en":"It is used to question whether fair trade truly benefits farmers.","zh":"它用來質疑公平貿易是否真正令農民受益。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":11},{"front":"reporting from producers","meaning":"生產者提交的報告","examples":[{"en":"Reporting from producers is often inadequate.","zh":"生產者提交的報告經常不足。"},{"en":"Reporting from producers means information or records provided by producers.","zh":"生產者提交的報告，指由生產者提供的資訊或記錄。"},{"en":"Producers may report income but fail to report all costs.","zh":"生產者可能報告收入，但沒有報告所有成本。"},{"en":"Inadequate reporting makes profit difficult to measure.","zh":"報告不足令利潤難以量度。"},{"en":"The phrase refers to data supplied by producers themselves.","zh":"這個詞組指由生產者本人提供的數據。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":11},{"front":"inadequate","meaning":"不足；不充分","examples":[{"en":"Producer reporting is often inadequate.","zh":"生產者報告經常不足。"},{"en":"Inadequate means not enough or not good enough for a purpose.","zh":"不足或不充分，指數量或質素不夠達到目的。"},{"en":"Inadequate data can lead to weak conclusions.","zh":"數據不足會導致結論薄弱。"},{"en":"If cost reporting is inadequate, profit estimates may be unreliable.","zh":"如果成本報告不足，利潤估計可能不可靠。"},{"en":"The word describes insufficiency.","zh":"這個詞描述不充分。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":11},{"front":"methods of determining profit","meaning":"計算利潤的方法","examples":[{"en":"Methods of determining profit may not include all costs.","zh":"計算利潤的方法可能不包括所有成本。"},{"en":"Methods of determining profit are ways of calculating whether revenue exceeds expenses.","zh":"計算利潤的方法，是計算收入是否超過開支的方式。"},{"en":"A method may be flawed if it excludes transport or processing costs.","zh":"如果方法排除運輸或加工成本，它便可能有缺陷。"},{"en":"The phrase concerns financial measurement.","zh":"這個詞組涉及財務量度。"},{"en":"It is used to criticise unclear profit claims.","zh":"它用於批評不清晰的利潤聲稱。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":11},{"front":"harvesting, transport, or processing","meaning":"收割、運輸或加工","examples":[{"en":"Profit calculations may exclude harvesting, transport, or processing.","zh":"利潤計算可能排除收割、運輸或加工。"},{"en":"Harvesting means collecting crops, transport means moving them, and processing means preparing them for sale.","zh":"收割指採收作物，運輸指移動作物，加工指為出售作準備。"},{"en":"These activities all cost money.","zh":"這些活動都需要成本。"},{"en":"Excluding them can make profits seem higher than they really are.","zh":"排除它們會令利潤看起來比實際更高。"},{"en":"The phrase lists important production costs.","zh":"這個詞組列出重要生產成本。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":12},{"front":"price paid to","meaning":"支付給……的價格","examples":[{"en":"The price paid to fair-trade producers may be lower than the open-market price.","zh":"支付給公平貿易生產者的價格可能低於公開市場價格。"},{"en":"Price paid to someone means the amount of money given for their goods or labour.","zh":"支付給某人的價格，指因其商品或勞動而給予的金額。"},{"en":"A higher consumer price does not always mean a higher price paid to producers.","zh":"較高消費價格不一定表示支付給生產者的價格較高。"},{"en":"The phrase focuses on what producers actually receive.","zh":"這個詞組集中於生產者實際收到甚麼。"},{"en":"It is central to criticism of fair trade.","zh":"它是公平貿易批評的核心。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":12},{"front":"elsewhere it could have earned more","meaning":"在其他地方本可賺得更多","examples":[{"en":"A crop may earn less under fair trade than it could have earned elsewhere.","zh":"一種作物在公平貿易下可能賺得較少，而在其他地方本可賺得更多。"},{"en":"Elsewhere it could have earned more means it might have received a higher price in another market.","zh":"在其他地方本可賺得更多，指它在另一市場可能收到更高價格。"},{"en":"Critics use this idea to challenge fair-trade benefits.","zh":"批評者用這個想法挑戰公平貿易的好處。"},{"en":"A crop’s best price may depend on timing, quality, and demand.","zh":"作物的最佳價格可能取決於時間、質素和需求。"},{"en":"The phrase compares fair trade with alternative sales channels.","zh":"這個詞組把公平貿易與其他銷售渠道作比較。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":12},{"front":"profits are taken by","meaning":"利潤被……拿走","examples":[{"en":"Profits are often taken by corporate firms.","zh":"利潤經常被大企業拿走。"},{"en":"Profits are taken by means the financial gains go to a particular group.","zh":"利潤被某方拿走，指財務收益流向某一群體。"},{"en":"Critics argue that retailers and middlemen may take much of the profit.","zh":"批評者認為零售商和中間商可能拿走大部分利潤。"},{"en":"The phrase suggests producers may not receive the main benefit.","zh":"這個詞組表示生產者可能沒有得到主要好處。"},{"en":"It is used to criticise the distribution of money.","zh":"它用於批評金錢分配。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":12},{"front":"corporate firms","meaning":"大企業","examples":[{"en":"Corporate firms may buy fair-trade goods and sell them to retailers.","zh":"大企業可能購買公平貿易商品並轉售給零售商。"},{"en":"Corporate firms are large business companies.","zh":"大企業是大型商業公司。"},{"en":"They may play a role between producers and shops.","zh":"它們可能在生產者和商店之間扮演角色。"},{"en":"Critics argue that corporate firms can profit heavily from fair-trade branding.","zh":"批評者認為大企業可以從公平貿易品牌中獲取大量利潤。"},{"en":"The phrase identifies powerful commercial actors.","zh":"這個詞組指出強大的商業角色。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":12},{"front":"sell them on to retailers","meaning":"轉售給零售商","examples":[{"en":"Corporate firms sell the goods on to retailers.","zh":"大企業把商品轉售給零售商。"},{"en":"Sell them on to retailers means resell the goods to shops or sellers.","zh":"轉售給零售商，指把商品再賣給商店或銷售者。"},{"en":"Goods may pass through several middlemen before reaching consumers.","zh":"商品到達消費者前可能經過數個中間商。"},{"en":"Each stage can add cost and profit.","zh":"每個階段都可以增加成本和利潤。"},{"en":"The phrase describes part of the supply chain.","zh":"這個詞組描述供應鏈的一部分。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":12},{"front":"part of the equation","meaning":"問題的一部分","examples":[{"en":"There are problems with the developed-world part of the equation too.","zh":"已發展世界這一部分也有問題。"},{"en":"Part of the equation means one side or factor in a larger situation.","zh":"問題的一部分，指較大情況中的一個方面或因素。"},{"en":"The fair-trade equation includes producers, buyers, retailers, and consumers.","zh":"公平貿易這個問題包括生產者、買家、零售商和消費者。"},{"en":"The phrase suggests that problems exist not only among producers.","zh":"這個詞組表示問題不只存在於生產者一方。"},{"en":"It broadens the criticism to richer countries.","zh":"它把批評擴展到較富裕國家。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":12},{"front":"volunteer to work for","meaning":"自願為……工作","examples":[{"en":"Some people volunteer to work for fair-trade concerns.","zh":"有些人自願為公平貿易機構工作。"},{"en":"Volunteer to work for means offer labour without being forced and often without pay.","zh":"自願為某機構工作，指在非強迫下提供勞動，通常沒有報酬。"},{"en":"Volunteers may believe they are helping poor producers.","zh":"義工可能相信自己正在幫助貧困生產者。"},{"en":"The passage questions whether their labour always benefits farmers.","zh":"文章質疑他們的勞動是否總是令農民受益。"},{"en":"The phrase identifies unpaid support within fair trade.","zh":"這個詞組指出公平貿易中的無薪支援。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":12},{"front":"fair-trade concerns","meaning":"公平貿易企業；公平貿易機構","examples":[{"en":"Volunteers may work for fair-trade concerns.","zh":"義工可能為公平貿易企業或機構工作。"},{"en":"Fair-trade concerns are businesses or organisations involved in fair trade.","zh":"公平貿易企業或機構，是參與公平貿易的商業或組織。"},{"en":"They may sell fair-trade products, organise certification, or run campaigns.","zh":"它們可能銷售公平貿易產品、組織認證或進行宣傳。"},{"en":"The phrase is broad and can include commercial bodies.","zh":"這個詞組範圍較廣，可以包括商業機構。"},{"en":"It identifies organisations connected with the movement.","zh":"它指出與該運動有關的組織。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":12},{"front":"whereas","meaning":"然而；但其實","examples":[{"en":"Volunteers think they are helping farmers, whereas their labour may enrich retailers.","zh":"義工以為自己在幫助農民，但其實他們的勞動可能令零售商獲利。"},{"en":"Whereas introduces a contrast between two ideas.","zh":"然而或但其實，用來引入兩個想法之間的對比。"},{"en":"Volunteers may intend to help producers, whereas the benefit may go elsewhere.","zh":"義工可能意圖幫助生產者，但好處可能流向其他地方。"},{"en":"The word highlights contradiction or irony.","zh":"這個詞突出矛盾或諷刺。"},{"en":"It is useful for comparing intention and result.","zh":"它適合用於比較意圖和結果。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":12},{"front":"serve to","meaning":"起……作用","examples":[{"en":"Their labour may serve to enrich middlemen and retailers.","zh":"他們的勞動可能起到令中間商和零售商獲利的作用。"},{"en":"Serve to means have the effect of doing something.","zh":"起某種作用，指具有造成某結果的效果。"},{"en":"Volunteer work may serve to reduce company costs.","zh":"義工工作可能起到降低公司成本的作用。"},{"en":"The phrase can suggest an unintended result.","zh":"這個詞組可以表示非預期結果。"},{"en":"It explains what an action actually achieves.","zh":"它解釋一項行動實際達成甚麼。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":12},{"front":"enrich middlemen and retailers","meaning":"令中間商和零售商獲利","examples":[{"en":"Volunteer labour may enrich middlemen and retailers.","zh":"義工勞動可能令中間商和零售商獲利。"},{"en":"Enrich middlemen and retailers means make intermediaries and shops financially better off.","zh":"令中間商和零售商獲利，指令中介者和商店在財務上得益。"},{"en":"Critics argue that unpaid labour may increase profits for businesses.","zh":"批評者認為無薪勞動可能增加企業利潤。"},{"en":"The phrase suggests that benefits may not reach farmers.","zh":"這個詞組表示好處可能沒有到達農民。"},{"en":"It is a criticism of the developed-world side of fair trade.","zh":"它是對公平貿易已發展國家一方的批評。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":13},{"front":"middlemen","meaning":"中間商","examples":[{"en":"Middlemen may take profits from fair-trade products.","zh":"中間商可能從公平貿易產品中拿走利潤。"},{"en":"Middlemen are people or businesses between producers and final sellers or consumers.","zh":"中間商，是位於生產者與最終賣家或消費者之間的人或企業。"},{"en":"They may buy goods from producers and sell them onward.","zh":"他們可能從生產者手中購買商品，再轉售出去。"},{"en":"Critics argue that middlemen can absorb much of the value.","zh":"批評者認為中間商可以吸收大部分價值。"},{"en":"The word is important in supply-chain criticism.","zh":"這個詞在供應鏈批評中很重要。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":13},{"front":"West African cocoa production","meaning":"西非可可生產","examples":[{"en":"Companies involved in West African cocoa production have been criticised.","zh":"參與西非可可生產的公司曾受到批評。"},{"en":"West African cocoa production means cocoa farming and processing in West African countries.","zh":"西非可可生產，指西非國家的可可種植和加工。"},{"en":"Cocoa from this region is important in global chocolate supply.","zh":"該地區的可可對全球朱古力供應很重要。"},{"en":"Some companies involved in this production have faced ethical criticism.","zh":"一些參與該生產的公司曾面對道德批評。"},{"en":"The phrase identifies a specific fair-trade controversy.","zh":"這個詞組指出一項具體公平貿易爭議。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":13},{"front":"be criticised for","meaning":"因……而被批評","examples":[{"en":"Some companies have been criticised for their role in cocoa production.","zh":"一些公司因其在可可生產中的角色而被批評。"},{"en":"Be criticised for means receive negative judgment because of something.","zh":"因某事而被批評，指因某原因受到負面評價。"},{"en":"Companies may be criticised for unfair labour practices.","zh":"公司可能因不公平勞工做法而被批評。"},{"en":"The phrase introduces the reason for criticism.","zh":"這個詞組引入批評原因。"},{"en":"It is common in discussions of corporate responsibility.","zh":"它常見於企業責任討論。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":13},{"front":"the right to use","meaning":"使用……的權利","examples":[{"en":"The right to use a fair-trade logo is expensive.","zh":"使用公平貿易標誌的權利很昂貴。"},{"en":"The right to use means official permission to use something.","zh":"使用某物的權利，指正式獲准使用某物。"},{"en":"Retailers may pay for permission to display a fair-trade logo.","zh":"零售商可能支付費用以獲准展示公平貿易標誌。"},{"en":"The phrase links branding with cost.","zh":"這個詞組把品牌標示與成本連接起來。"},{"en":"It helps explain why fair-trade products may become expensive.","zh":"它有助解釋公平貿易產品為何可能變貴。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":13},{"front":"fair-trade logo","meaning":"公平貿易標誌","examples":[{"en":"Retailers pay for the right to use a fair-trade logo.","zh":"零售商支付費用以取得使用公平貿易標誌的權利。"},{"en":"A fair-trade logo is a symbol showing that a product is certified or marketed as fair trade.","zh":"公平貿易標誌，是顯示產品獲認證或以公平貿易銷售的符號。"},{"en":"Logos help consumers recognise ethical products quickly.","zh":"標誌幫助消費者快速識別道德產品。"},{"en":"The right to use the logo may add to product costs.","zh":"使用標誌的權利可能增加產品成本。"},{"en":"The phrase identifies the visual mark of fair trade.","zh":"這個詞組指出公平貿易的視覺標記。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":13},{"front":"packers and retailers","meaning":"包裝商和零售商","examples":[{"en":"Packers and retailers may charge high prices for fair-trade goods.","zh":"包裝商和零售商可能對公平貿易商品收取高價。"},{"en":"Packers prepare and package products, while retailers sell them to consumers.","zh":"包裝商負責準備和包裝產品，而零售商把產品賣給消費者。"},{"en":"Both groups can add costs and profits to the final price.","zh":"兩者都可以在最終價格中增加成本和利潤。"},{"en":"Critics argue that they may benefit more than producers.","zh":"批評者認為他們可能比生產者獲益更多。"},{"en":"The phrase identifies later stages of the supply chain.","zh":"這個詞組指出供應鏈較後階段。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":13},{"front":"a substantial amount of","meaning":"大量的……","examples":[{"en":"A substantial amount of sales money may be spent on marketing.","zh":"大量銷售所得款項可能用於市場推廣。"},{"en":"A substantial amount of means a large or significant quantity of something.","zh":"大量的某物，指很大或相當可觀的數量。"},{"en":"A substantial amount of revenue may go to advertising rather than farmers.","zh":"大量收入可能流向廣告，而不是農民。"},{"en":"The phrase stresses that the amount is not small.","zh":"這個詞組強調數量不小。"},{"en":"It is used to criticise how money is spent.","zh":"它用於批評金錢如何被使用。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":13},{"front":"money received from sales","meaning":"銷售所得款項","examples":[{"en":"Some money received from sales is ploughed back into marketing.","zh":"一些銷售所得款項被重新投入市場推廣。"},{"en":"Money received from sales means revenue earned by selling products.","zh":"銷售所得款項，指銷售產品所得收入。"},{"en":"Retailers may use sales money to advertise fair-trade products.","zh":"零售商可能使用銷售款項來宣傳公平貿易產品。"},{"en":"This may reduce the amount that reaches producers.","zh":"這可能減少到達生產者手中的金額。"},{"en":"The phrase refers to income from selling goods.","zh":"這個詞組指出銷售商品所得收入。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":13},{"front":"be ploughed back into","meaning":"被重新投入","examples":[{"en":"Sales revenue may be ploughed back into marketing.","zh":"銷售收入可能被重新投入市場推廣。"},{"en":"Be ploughed back into means be reinvested in a particular activity.","zh":"被重新投入，指被再投資於某項活動。"},{"en":"Profits may be ploughed back into advertising or expansion.","zh":"利潤可能被重新投入廣告或擴張。"},{"en":"The phrase suggests money is returned to a business process.","zh":"這個詞組表示金錢返回商業流程。"},{"en":"It may be positive or critical depending on context.","zh":"它可帶正面或批評意味，視乎語境。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":13},{"front":"notably in London","meaning":"尤其在倫敦","examples":[{"en":"High prices are charged in richer places, notably in London.","zh":"較富裕地方收取高價，尤其在倫敦。"},{"en":"Notably in London means especially or particularly in London.","zh":"尤其在倫敦，指特別是在倫敦。"},{"en":"The phrase gives London as a clear example of a rich market.","zh":"這個詞組把倫敦作為富裕市場的清楚例子。"},{"en":"Retail prices may be especially high in wealthy urban areas.","zh":"在富裕城市地區，零售價格可能特別高。"},{"en":"It highlights a specific location within a broader claim.","zh":"它在較廣泛主張中突出一個具體地點。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":13},{"front":"charge high prices","meaning":"收取高價","examples":[{"en":"Packers and retailers charge high prices for fair-trade products.","zh":"包裝商和零售商對公平貿易產品收取高價。"},{"en":"Charge high prices means ask consumers to pay a large amount.","zh":"收取高價，指要求消費者支付大量金錢。"},{"en":"Retailers may charge high prices because fair-trade branding attracts ethical consumers.","zh":"零售商可能因公平貿易品牌吸引道德消費者而收取高價。"},{"en":"Critics question whether high prices really benefit producers.","zh":"批評者質疑高價是否真正令生產者受益。"},{"en":"The phrase focuses on consumer cost.","zh":"這個詞組集中於消費者成本。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":14},{"front":"fair-trade products","meaning":"公平貿易產品","examples":[{"en":"Fair-trade products often cost more in richer markets.","zh":"公平貿易產品在較富裕市場中通常價格較高。"},{"en":"Fair-trade products are goods marketed as being produced under fair-trade standards.","zh":"公平貿易產品，是以符合公平貿易標準生產作為賣點的商品。"},{"en":"They may include coffee, cocoa, tea, cotton, and handicrafts.","zh":"它們可能包括咖啡、可可、茶、棉花和手工藝品。"},{"en":"Consumers may buy them because they regard them as ethical.","zh":"消費者可能因視它們為合乎道德而購買。"},{"en":"The phrase identifies goods connected with the movement.","zh":"這個詞組指出與該運動相關的商品。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":14},{"front":"imagine that","meaning":"以為；想像","examples":[{"en":"Consumers imagine that more money is returned to producers.","zh":"消費者以為更多金錢會交回給生產者。"},{"en":"Imagine that means believe or suppose something, sometimes without proof.","zh":"以為或想像，指相信或假設某事，有時沒有證據。"},{"en":"Consumers may imagine that higher prices go directly to farmers.","zh":"消費者可能以為較高價格會直接流向農民。"},{"en":"The passage suggests this belief may be naive.","zh":"文章表示這種信念可能太天真。"},{"en":"The phrase introduces a consumer assumption.","zh":"這個詞組引入消費者假設。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":14},{"front":"be returned to producers","meaning":"被交回給生產者","examples":[{"en":"Consumers think more money is returned to producers.","zh":"消費者認為更多金錢會被交回給生產者。"},{"en":"Be returned to producers means be given back or passed on to the people who made the goods.","zh":"被交回給生產者，指被給回或轉交給製造商品的人。"},{"en":"The passage questions how much of the extra charge reaches producers.","zh":"文章質疑額外收費有多少到達生產者手中。"},{"en":"Money may instead remain with retailers or middlemen.","zh":"金錢可能反而留在零售商或中間商手中。"},{"en":"The phrase focuses on where consumer payments finally go.","zh":"這個詞組集中於消費者付款最終流向哪裏。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":14},{"front":"profit-taking by retailers","meaning":"零售商賺取利潤","examples":[{"en":"Profit-taking by retailers may explain high prices.","zh":"零售商賺取利潤可能解釋高價格。"},{"en":"Profit-taking by retailers means shops keep a significant profit from selling products.","zh":"零售商賺取利潤，指商店從銷售產品中保留可觀利潤。"},{"en":"Critics argue that high fair-trade prices may benefit retailers more than farmers.","zh":"批評者認為，高公平貿易價格可能比農民更有利於零售商。"},{"en":"The phrase identifies one possible reason for expensive goods.","zh":"這個詞組指出昂貴商品的一個可能原因。"},{"en":"It is used in a critical discussion of fair-trade pricing.","zh":"它用於對公平貿易定價的批評討論。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":14},{"front":"more likely scenario","meaning":"更可能的情況","examples":[{"en":"Retailer profit-taking is a more likely scenario.","zh":"零售商賺取利潤是更可能的情況。"},{"en":"A more likely scenario is an explanation that is more probable than another.","zh":"更可能的情況，是比另一解釋更有可能的解釋。"},{"en":"The writer suggests high prices are more likely caused by retailer profits than producer payments.","zh":"作者表示高價格更可能由零售商利潤造成，而不是由生產者付款造成。"},{"en":"The phrase compares possible explanations.","zh":"這個詞組比較可能解釋。"},{"en":"It indicates the writer’s judgment about probability.","zh":"它表明作者對可能性的判斷。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":14},{"front":"be known to have","meaning":"據知曾經","examples":[{"en":"One café chain is known to have passed on only a small share.","zh":"據知有一間連鎖咖啡店曾只轉交一小部分。"},{"en":"Be known to have means there is information showing that something happened.","zh":"據知曾經，指有資料顯示某事曾發生。"},{"en":"The phrase introduces a reported example.","zh":"這個詞組引入一個被報道的例子。"},{"en":"It suggests the case is documented or publicly known.","zh":"它表示該案例有記錄或為公眾所知。"},{"en":"In the passage, it supports criticism of retailers.","zh":"在文章中，它支持對零售商的批評。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":14},{"front":"pass on","meaning":"轉交；傳遞","examples":[{"en":"The café chain passed on only 1.6% of the extra charge to producers.","zh":"該連鎖咖啡店只把額外收費的 1.6% 轉交給生產者。"},{"en":"Pass on means transfer or give something to another person or group.","zh":"轉交或傳遞，指把某物轉給另一人或群體。"},{"en":"Retailers may not pass on much of the extra charge to farmers.","zh":"零售商可能沒有把很多額外收費轉交給農民。"},{"en":"The phrase focuses on movement of money through the supply chain.","zh":"這個詞組集中於金錢如何在供應鏈中流動。"},{"en":"It is central to the criticism of fair-trade pricing.","zh":"它是公平貿易定價批評的核心。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":14},{"front":"extra charge","meaning":"額外收費","examples":[{"en":"Only a small part of the extra charge went to producers.","zh":"額外收費中只有很小一部分流向生產者。"},{"en":"Extra charge means an additional amount paid above the normal price.","zh":"額外收費，指正常價格以外支付的額外金額。"},{"en":"Consumers may assume the extra charge supports producers.","zh":"消費者可能假設額外收費會支持生產者。"},{"en":"The passage questions whether that assumption is correct.","zh":"文章質疑這個假設是否正確。"},{"en":"The phrase refers to the price premium paid by consumers.","zh":"這個詞組指消費者支付的價格溢價。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":14},{"front":"consumers are naive to believe","meaning":"消費者相信……可能太天真","examples":[{"en":"Consumers may be naive to believe fair-traders behave differently.","zh":"消費者相信公平貿易商會有不同做法，可能太天真。"},{"en":"Consumers are naive to believe means consumers are too trusting or unrealistic if they believe something.","zh":"消費者相信某事可能太天真，指如果相信某事，他們可能過於信任或不切實際。"},{"en":"The writer suggests shoppers may wrongly assume fair-trade companies are less profit-driven.","zh":"作者表示購物者可能錯誤地假設公平貿易公司較不追求利潤。"},{"en":"The phrase is critical of consumer assumptions.","zh":"這個詞組批評消費者假設。"},{"en":"It warns against simple moral certainty in shopping.","zh":"它提醒人們不要在購物中抱有簡單的道德確定感。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":14},{"front":"behave otherwise","meaning":"有不同做法","examples":[{"en":"Consumers may be naive to believe fair-traders behave otherwise.","zh":"消費者相信公平貿易商有不同做法，可能太天真。"},{"en":"Behave otherwise means act differently from what has just been described.","zh":"有不同做法，指以不同於剛才所述的方式行事。"},{"en":"The passage suggests fair-trade businesses may behave like ordinary businesses.","zh":"文章表示公平貿易企業可能像普通企業一樣行事。"},{"en":"The phrase challenges the idea that fair-traders are automatically more generous.","zh":"這個詞組挑戰公平貿易商必然更慷慨的想法。"},{"en":"It refers to commercial behaviour.","zh":"它指商業行為。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":14},{"front":"in addition","meaning":"此外","examples":[{"en":"In addition, there are struggling farmers in rich countries too.","zh":"此外，富裕國家也有掙扎求存的農民。"},{"en":"In addition means also or furthermore.","zh":"此外，指另外或再者。"},{"en":"The phrase introduces an extra point in the argument.","zh":"這個詞組在論證中引入額外重點。"},{"en":"The writer adds that poverty among farmers is not limited to developing countries.","zh":"作者補充指出，農民貧困並不只限於發展中國家。"},{"en":"It helps extend the criticism.","zh":"它有助擴展批評。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":15},{"front":"struggling farmers","meaning":"掙扎求存的農民","examples":[{"en":"Some critics point out that rich countries also have struggling farmers.","zh":"一些批評者指出富裕國家也有掙扎求存的農民。"},{"en":"Struggling farmers are farmers facing financial difficulty or hardship.","zh":"掙扎求存的農民，是面對財務困難或艱苦處境的農民。"},{"en":"They may have low income, high costs, or unstable markets.","zh":"他們可能收入低、成本高或面對不穩定市場。"},{"en":"Critics ask why fair trade does not certify such farmers too.","zh":"批評者問為何公平貿易也不為這些農民認證。"},{"en":"The phrase challenges the focus on developing-world producers only.","zh":"這個詞組挑戰只關注發展中國家生產者的做法。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":15},{"front":"fair-trade associations","meaning":"公平貿易協會","examples":[{"en":"Some critics think fair-trade associations should certify rich-country farmers.","zh":"一些批評者認為公平貿易協會應為富裕國家的農民認證。"},{"en":"Fair-trade associations are organisations connected with fair-trade certification or promotion.","zh":"公平貿易協會，是與公平貿易認證或推廣有關的組織。"},{"en":"They may set standards, approve producers, and manage labels.","zh":"它們可能制定標準、批准生產者和管理標籤。"},{"en":"Critics argue these associations should broaden who they help.","zh":"批評者認為這些協會應擴大幫助對象。"},{"en":"The phrase identifies formal organisations in the system.","zh":"這個詞組指出制度中的正式組織。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":15},{"front":"certify them","meaning":"為他們認證","examples":[{"en":"Some critics think fair-trade associations should certify struggling farmers in rich countries.","zh":"一些批評者認為公平貿易協會應為富裕國家的掙扎農民認證。"},{"en":"Certify them means officially approve them as meeting certain standards.","zh":"為他們認證，指正式確認他們符合某些標準。"},{"en":"Certification could allow farmers to sell goods with a fair-trade label.","zh":"認證可以讓農民以公平貿易標籤出售商品。"},{"en":"The phrase refers to extending fair-trade recognition.","zh":"這個詞組指擴展公平貿易認可。"},{"en":"It raises the question of who deserves certification.","zh":"它提出誰應獲認證的問題。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":15},{"front":"the entire fair-trade system","meaning":"整個公平貿易制度","examples":[{"en":"Some critics find the entire fair-trade system flawed.","zh":"一些批評者認為整個公平貿易制度有缺陷。"},{"en":"The entire fair-trade system means the whole structure of fair-trade rules, labels, buyers, and sellers.","zh":"整個公平貿易制度，指公平貿易規則、標籤、買家和賣家的整體結構。"},{"en":"Critics may object not only to details but to the system as a whole.","zh":"批評者可能不只反對細節，而是反對整個制度。"},{"en":"The phrase makes the criticism broad and fundamental.","zh":"這個詞組令批評變得廣泛而根本。"},{"en":"It suggests problems exist at many levels.","zh":"它表示問題存在於多個層面。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":15},{"front":"flawed","meaning":"有缺陷的","examples":[{"en":"Some critics argue that the fair-trade system is flawed.","zh":"一些批評者認為公平貿易制度有缺陷。"},{"en":"Flawed means having defects, weaknesses, or mistakes.","zh":"有缺陷的，指有缺點、弱點或錯誤。"},{"en":"A flawed system may have good intentions but poor results.","zh":"有缺陷的制度可能有良好意圖，但結果不佳。"},{"en":"Critics call fair trade flawed because of costs, labels, and retailer profits.","zh":"批評者因成本、標籤和零售商利潤而稱公平貿易有缺陷。"},{"en":"The word describes imperfection.","zh":"這個詞描述不完美。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":15},{"front":"nothing more than","meaning":"只不過是","examples":[{"en":"Some critics call fair trade nothing more than a marketing scam.","zh":"一些批評者稱公平貿易只不過是市場推廣騙局。"},{"en":"Nothing more than means merely or only.","zh":"只不過是，指僅僅是或只是。"},{"en":"The phrase dismisses fair trade as less noble than it appears.","zh":"這個詞組把公平貿易貶低為沒有表面上那麼高尚。"},{"en":"Critics use it to argue that fair trade is mainly commercial branding.","zh":"批評者用它來主張公平貿易主要是商業品牌包裝。"},{"en":"It strongly reduces the value of the system.","zh":"它強烈降低該制度的價值。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":15},{"front":"colossal marketing scam","meaning":"巨型市場推廣騙局","examples":[{"en":"Some critics describe fair trade as a colossal marketing scam.","zh":"一些批評者把公平貿易描述為巨型市場推廣騙局。"},{"en":"A colossal marketing scam is a very large dishonest promotional scheme.","zh":"巨型市場推廣騙局，是非常大型且不誠實的宣傳計劃。"},{"en":"This is one of the harshest criticisms of fair trade in the passage.","zh":"這是文章中對公平貿易最嚴厲的批評之一。"},{"en":"It suggests consumers are being misled by ethical branding.","zh":"它表示消費者被道德品牌包裝誤導。"},{"en":"The phrase is highly negative and accusatory.","zh":"這個詞組非常負面且帶指控意味。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":15},{"front":"genuinely poor","meaning":"真正貧困的人","examples":[{"en":"Critics would rather assist the genuinely poor in transparent ways.","zh":"批評者寧願以透明方式幫助真正貧困的人。"},{"en":"Genuinely poor means truly poor, not only officially or symbolically disadvantaged.","zh":"真正貧困的人，指確實貧困，而不只是名義上或象徵上處於不利。"},{"en":"Critics argue help should reach people who are really in need.","zh":"批評者認為幫助應到達真正有需要的人。"},{"en":"The phrase contrasts direct poverty relief with branded consumption.","zh":"這個詞組把直接扶貧與品牌消費作對比。"},{"en":"It identifies the intended target of more transparent help.","zh":"它指出更透明幫助的目標對象。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":15},{"front":"transparent ways","meaning":"透明度較高的方式","examples":[{"en":"Some critics prefer to help the poor in more transparent ways.","zh":"一些批評者較喜歡以透明度較高的方式幫助窮人。"},{"en":"Transparent ways are methods that are clear, open, and easy to verify.","zh":"透明度較高的方式，是清楚、公開且容易核實的方法。"},{"en":"Direct donations or clearly reported programmes may be more transparent.","zh":"直接捐款或報告清楚的計劃可能更透明。"},{"en":"The phrase suggests fair trade may hide where money really goes.","zh":"這個詞組表示公平貿易可能隱藏金錢真正流向。"},{"en":"It focuses on accountability.","zh":"它集中於問責性。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":15},{"front":"criticism may be overblown","meaning":"批評可能被誇大","examples":[{"en":"The criticism may be overblown because fair trade has endured.","zh":"批評可能被誇大，因為公平貿易經受住了批評。"},{"en":"Criticism may be overblown means the criticism may be exaggerated or too severe.","zh":"批評可能被誇大，指批評可能被誇張或過於嚴厲。"},{"en":"The passage acknowledges problems but suggests fair trade still has value.","zh":"文章承認問題，但表示公平貿易仍可能有價值。"},{"en":"If a system survives criticism, some supporters may see that as evidence of usefulness.","zh":"如果一個制度在批評下仍然存在，一些支持者可能把這視為有用的證據。"},{"en":"The phrase softens earlier criticisms.","zh":"這個詞組緩和早前批評。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":15},{"front":"endure","meaning":"持續存在；經受住","examples":[{"en":"Fair trade has endured despite criticism.","zh":"儘管受到批評，公平貿易仍持續存在。"},{"en":"Endure means continue to exist or survive through difficulty.","zh":"持續存在或經受住，指在困難中繼續存在或生存。"},{"en":"A movement that endures has lasting support.","zh":"能持續存在的運動有持久支持。"},{"en":"Fair trade has endured because many consumers and producers still value it.","zh":"公平貿易能持續存在，是因為許多消費者和生產者仍重視它。"},{"en":"The word suggests resilience.","zh":"這個詞表示韌性。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":16},{"front":"be praised in","meaning":"在……受到讚揚","examples":[{"en":"Fair trade has been praised in the developing world itself.","zh":"公平貿易在發展中國家本身受到讚揚。"},{"en":"Be praised in means receive positive comments or approval within a place or context.","zh":"在某處受到讚揚，指在某地方或語境中獲得正面評論或認可。"},{"en":"Fair trade being praised in producer countries supports its defenders.","zh":"公平貿易在生產者國家受到讚揚，支持了其辯護者。"},{"en":"Praise does not remove every criticism, but it shows some approval.","zh":"讚揚不能消除所有批評，但顯示有一定認可。"},{"en":"The phrase identifies where support comes from.","zh":"這個詞組指出支持來自哪裏。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":16},{"front":"the developing world itself","meaning":"發展中國家本身","examples":[{"en":"Fair trade has been praised in the developing world itself.","zh":"公平貿易在發展中國家本身受到讚揚。"},{"en":"The developing world itself means developing countries, especially from their own perspective rather than outsiders’ views.","zh":"發展中國家本身，指發展中國家，尤其是從其自身角度而非外人看法來說。"},{"en":"Praise from the developing world matters because producers are directly affected.","zh":"來自發展中國家的讚揚很重要，因為生產者直接受影響。"},{"en":"The phrase counters the idea that fair trade is only a rich-world fantasy.","zh":"這個詞組反駁公平貿易只是富裕國家幻想的想法。"},{"en":"It gives weight to local approval.","zh":"它加強本地認可的重要性。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":16},{"front":"answer the questions below","meaning":"回答以下問題","examples":[{"en":"Students must answer the questions below using words from the passage.","zh":"學生必須使用文章中的字詞回答以下問題。"},{"en":"Answer the questions below means respond to the following questions.","zh":"回答以下問題，指回應接下來的問題。"},{"en":"The instruction tells students to use information from the text.","zh":"該指示告訴學生使用文本中的資料。"},{"en":"Students should not use outside knowledge unless the task allows it.","zh":"除非題目允許，學生不應使用外部知識。"},{"en":"The phrase introduces a reading-comprehension task.","zh":"這個詞組引入閱讀理解任務。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":16},{"front":"no more than three words","meaning":"不超過三個詞","examples":[{"en":"The answers must use no more than three words from the passage.","zh":"答案必須使用文章中不超過三個詞。"},{"en":"No more than three words means the answer can contain one, two, or three words only.","zh":"不超過三個詞，指答案只能包含一個、兩個或三個詞。"},{"en":"Four words would break the instruction.","zh":"四個詞會違反指示。"},{"en":"Students should copy only the necessary words.","zh":"學生只應抄寫必要字詞。"},{"en":"The phrase sets a strict answer limit.","zh":"這個詞組設定嚴格答案限制。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":16},{"front":"early slogan","meaning":"早期口號","examples":[{"en":"The question asks for an early slogan about trade inequality.","zh":"問題詢問一個關於貿易不平等的早期口號。"},{"en":"An early slogan is a short memorable phrase used near the beginning of a movement.","zh":"早期口號，是運動初期使用的簡短易記語句。"},{"en":"“Trade Not Aid” was an early slogan of fair trade.","zh":"「要貿易，不要援助」是公平貿易的早期口號。"},{"en":"Slogans help express complex ideas simply.","zh":"口號幫助簡單表達複雜想法。"},{"en":"The phrase points students to a key historical detail.","zh":"這個詞組提示學生尋找關鍵歷史細節。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":16},{"front":"address the imbalance between","meaning":"處理……之間的不平衡","examples":[{"en":"The slogan addressed the imbalance between developed and developing worlds.","zh":"該口號處理已發展世界與發展中世界之間的不平衡。"},{"en":"Address the imbalance between means deal with or try to correct inequality between two sides.","zh":"處理兩者之間的不平衡，指處理或嘗試糾正雙方之間的不平等。"},{"en":"Fair trade aims to address imbalance in global markets.","zh":"公平貿易旨在處理全球市場中的不平衡。"},{"en":"The phrase suggests action toward fairness.","zh":"這個詞組表示朝公平採取行動。"},{"en":"It links the slogan with economic justice.","zh":"它把口號與經濟公義連接起來。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":16},{"front":"imbalance","meaning":"不平衡","examples":[{"en":"Fair trade aims to address an imbalance in global trade.","zh":"公平貿易旨在處理全球貿易中的不平衡。"},{"en":"An imbalance is a lack of equality or fairness between sides.","zh":"不平衡，是雙方之間缺乏平等或公平。"},{"en":"Rich countries and poor producers may face an imbalance of power.","zh":"富裕國家和貧困生產者之間可能存在權力不平衡。"},{"en":"Fair trade was created partly to correct this imbalance.","zh":"公平貿易部分是為糾正這種不平衡而產生。"},{"en":"The word identifies a central problem in the passage.","zh":"這個詞指出文章中的核心問題。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":16},{"front":"best-known fair-trade commodity","meaning":"最著名的公平貿易商品","examples":[{"en":"Coffee is probably the best-known fair-trade commodity.","zh":"咖啡大概是最著名的公平貿易商品。"},{"en":"The best-known fair-trade commodity is the fair-trade product most familiar to consumers.","zh":"最著名的公平貿易商品，是消費者最熟悉的公平貿易產品。"},{"en":"Coffee is widely seen on supermarket shelves and in café chains.","zh":"咖啡常見於超級市場貨架和連鎖咖啡店。"},{"en":"This familiarity makes it a symbol of fair trade.","zh":"這種熟悉度令它成為公平貿易的象徵。"},{"en":"The phrase identifies the most recognisable fair-trade good.","zh":"這個詞組指出最容易辨認的公平貿易商品。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":16},{"front":"commodity","meaning":"商品；大宗商品","examples":[{"en":"Coffee is a major fair-trade commodity.","zh":"咖啡是一種主要公平貿易商品。"},{"en":"A commodity is a raw material or basic good bought and sold in markets.","zh":"商品或大宗商品，是在市場中買賣的原材料或基本商品。"},{"en":"Coffee, cocoa, cotton, and tea can all be commodities.","zh":"咖啡、可可、棉花和茶都可以是大宗商品。"},{"en":"Commodity prices often change in the open market.","zh":"大宗商品價格在公開市場中經常變動。"},{"en":"The word is important in trade discussions.","zh":"這個詞在貿易討論中很重要。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":16},{"front":"according to the writer","meaning":"根據作者所說","examples":[{"en":"Students answer according to the writer’s view.","zh":"學生根據作者的觀點作答。"},{"en":"According to the writer means based on what the writer says or believes in the passage.","zh":"根據作者所說，指基於作者在文章中所說或所相信的內容。"},{"en":"Students should not answer according to personal opinion.","zh":"學生不應根據個人意見作答。"},{"en":"The phrase reminds readers to use the text as the authority.","zh":"這個詞組提醒讀者以文本為依據。"},{"en":"It is common in reading questions.","zh":"它常見於閱讀題目。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":16},{"front":"represent in relation to","meaning":"相對於……代表","examples":[{"en":"The question asks what producers represent in relation to global trade.","zh":"問題詢問生產者相對於全球貿易代表甚麼。"},{"en":"Represent in relation to means show the size, role, or meaning of something compared with a larger context.","zh":"相對於某事代表，指與較大背景相比，顯示某事的規模、角色或意義。"},{"en":"Two million producers represent only a tiny number in relation to total global trade.","zh":"相對於全球貿易總量，二百萬生產者只代表很小數目。"},{"en":"The phrase asks for comparative significance.","zh":"這個詞組詢問比較上的意義。"},{"en":"It helps test understanding of scale.","zh":"它有助測試對規模的理解。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":17},{"front":"supporters think","meaning":"支持者認為","examples":[{"en":"Supporters think fair trade has helped many people.","zh":"支持者認為公平貿易幫助了許多人。"},{"en":"Supporters think means people who favour an idea believe something is true.","zh":"支持者認為，指支持某想法的人相信某事為真。"},{"en":"Fair-trade supporters think the system has positive social effects.","zh":"公平貿易支持者認為該制度有正面社會影響。"},{"en":"The phrase introduces one side of the debate.","zh":"這個詞組引入爭論中的一方。"},{"en":"It contrasts with what critics claim.","zh":"它與批評者聲稱的內容形成對比。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":17},{"front":"affect many people","meaning":"影響許多人","examples":[{"en":"Fair trade may affect many people beyond its direct producers.","zh":"公平貿易可能影響直接生產者以外的許多人。"},{"en":"Affect many people means influence or have consequences for a large number of people.","zh":"影響許多人，指對大量人產生影響或後果。"},{"en":"Fair trade may affect producers, workers, consumers, and communities.","zh":"公平貿易可能影響生產者、工人、消費者和社區。"},{"en":"The phrase suggests impact beyond a small group.","zh":"這個詞組表示影響超出小群體。"},{"en":"It supports the idea that the movement has wider significance.","zh":"它支持該運動具有更廣泛意義的想法。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":17},{"front":"return to mainstream trade","meaning":"回到主流貿易","examples":[{"en":"Critics ask what producers would receive if they returned to mainstream trade.","zh":"批評者問如果生產者回到主流貿易會收到甚麼。"},{"en":"Return to mainstream trade means leave fair trade and sell through ordinary market channels.","zh":"回到主流貿易，指離開公平貿易並透過普通市場渠道出售。"},{"en":"Critics argue producers might receive higher prices there.","zh":"批評者認為生產者在那裏可能收到較高價格。"},{"en":"The phrase presents an alternative to fair trade.","zh":"這個詞組提出公平貿易以外的選擇。"},{"en":"It tests whether fair trade is financially beneficial.","zh":"它測試公平貿易在財務上是否有利。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":17},{"front":"complete each sentence with","meaning":"用……完成每句句子","examples":[{"en":"Students must complete each sentence with the correct ending.","zh":"學生必須用正確結尾完成每句句子。"},{"en":"Complete each sentence with means finish each sentence by choosing or adding the right words.","zh":"用某物完成每句句子，指透過選擇或加入正確字詞把句子補全。"},{"en":"The ending must match both grammar and meaning.","zh":"結尾必須同時符合文法和意思。"},{"en":"Students should connect sentence beginnings with suitable endings from the list.","zh":"學生應把句子開頭與清單中合適結尾連接起來。"},{"en":"The phrase describes a sentence-completion task.","zh":"這個詞組描述句子完成題。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":17},{"front":"correct ending","meaning":"正確結尾","examples":[{"en":"Each sentence must be completed with the correct ending.","zh":"每句句子必須以正確結尾完成。"},{"en":"A correct ending is the option that completes a sentence accurately.","zh":"正確結尾，是能準確完成句子的選項。"},{"en":"It must fit the passage information and sentence structure.","zh":"它必須符合文章資料和句子結構。"},{"en":"Choosing the wrong ending can change the meaning.","zh":"選錯結尾可能改變意思。"},{"en":"The phrase refers to an answer option in matching tasks.","zh":"這個詞組指配對題中的答案選項。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":17},{"front":"be willing to","meaning":"願意","examples":[{"en":"Consumers of fair-trade products are willing to pay more.","zh":"公平貿易產品消費者願意支付更多。"},{"en":"Be willing to means be prepared or ready to do something.","zh":"願意，指準備好或樂意做某事。"},{"en":"Ethical consumers may be willing to pay extra for fair-trade coffee.","zh":"道德消費者可能願意為公平貿易咖啡支付額外金額。"},{"en":"Willingness does not mean everyone can afford the higher price.","zh":"願意不代表每個人都負擔得起較高價格。"},{"en":"The phrase describes readiness to act.","zh":"這個詞組描述行動意願。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":17},{"front":"pay more for","meaning":"為……支付更多","examples":[{"en":"Fair-trade consumers are willing to pay more for ethical products.","zh":"公平貿易消費者願意為道德產品支付更多。"},{"en":"Pay more for means spend a higher price on something.","zh":"為某物支付更多，指為某物花較高價格。"},{"en":"Consumers may pay more for goods they believe are fairly produced.","zh":"消費者可能為他們相信公平生產的商品支付更多。"},{"en":"The phrase is central to fair trade’s consumer side.","zh":"這個詞組是公平貿易消費者面向的核心。"},{"en":"It links price with moral choice.","zh":"它把價格與道德選擇連接起來。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":17},{"front":"regard as ethical","meaning":"視為合乎道德","examples":[{"en":"Consumers pay more for products they regard as ethical.","zh":"消費者為他們視為合乎道德的產品支付更多。"},{"en":"Regard as ethical means consider something morally right or responsible.","zh":"視為合乎道德，指認為某事在道德上正確或負責任。"},{"en":"A product may be regarded as ethical if workers are treated fairly.","zh":"如果工人受到公平對待，產品可能被視為合乎道德。"},{"en":"The phrase explains why consumers choose fair-trade goods.","zh":"這個詞組解釋消費者為何選擇公平貿易商品。"},{"en":"It links perception with purchasing behaviour.","zh":"它把看法與購買行為連接起來。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":17},{"front":"loans or training","meaning":"貸款或培訓","examples":[{"en":"The system may include loans or training for producers.","zh":"該制度可能包括給生產者的貸款或培訓。"},{"en":"Loans are borrowed money, while training is instruction or skills development.","zh":"貸款是借來的金錢，而培訓是指導或技能發展。"},{"en":"Fair trade may support producers through both finance and education.","zh":"公平貿易可能透過財務和教育兩方面支持生產者。"},{"en":"These forms of help go beyond simply paying for goods.","zh":"這些幫助形式超越單純支付商品價款。"},{"en":"The phrase identifies practical support measures.","zh":"這個詞組指出實際支援措施。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":17},{"front":"producers and employees","meaning":"生產者和僱員","examples":[{"en":"Fair trade may include training for producers and employees.","zh":"公平貿易可能包括給生產者和僱員的培訓。"},{"en":"Producers make goods, while employees work for an organisation or producer.","zh":"生產者製造商品，而僱員為機構或生產者工作。"},{"en":"Training both groups can improve quality and working conditions.","zh":"培訓兩個群體可以改善質素和工作條件。"},{"en":"The phrase broadens support beyond owners or farmers alone.","zh":"這個詞組把支援對象擴展到不只是業主或農民。"},{"en":"It includes people involved in production work.","zh":"它包括參與生產工作的人。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":17},{"front":"social benefits","meaning":"社會效益","examples":[{"en":"Some practices are supported because of their social benefits.","zh":"一些做法因其社會效益而受到支持。"},{"en":"Social benefits are positive effects for people and communities.","zh":"社會效益，是對人和社區的正面影響。"},{"en":"Literacy, safer workplaces, and community development are social benefits.","zh":"識字、安全工作場所和社區發展都是社會效益。"},{"en":"Fair trade claims to create benefits beyond product sales.","zh":"公平貿易聲稱創造超越產品銷售的好處。"},{"en":"The phrase focuses on society rather than only profit.","zh":"這個詞組集中於社會，而不只是利潤。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":18},{"front":"influence non-fair-trade producers","meaning":"影響非公平貿易生產者","examples":[{"en":"Some fair-trade practices have influenced non-fair-trade producers.","zh":"一些公平貿易做法影響了非公平貿易生產者。"},{"en":"Influence non-fair-trade producers means affect the behaviour of producers outside the system.","zh":"影響非公平貿易生產者，指影響制度以外生產者的行為。"},{"en":"Non-certified farmers may copy environmental or quality practices.","zh":"未獲認證農民可能模仿環保或品質做法。"},{"en":"The phrase suggests fair trade may have wider indirect effects.","zh":"這個詞組表示公平貿易可能有更廣泛的間接影響。"},{"en":"It describes influence beyond direct membership.","zh":"它描述超出直接成員身份的影響。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":18},{"front":"international employment standards","meaning":"國際僱傭標準","examples":[{"en":"Fair-trade producers must adopt international employment standards.","zh":"公平貿易生產者必須採納國際僱傭標準。"},{"en":"International employment standards are labour rules recognised beyond one country.","zh":"國際僱傭標準，是超越單一國家而被承認的勞工規則。"},{"en":"They may include bans on child labour and requirements for safe workplaces.","zh":"它們可能包括禁止童工和要求安全工作場所。"},{"en":"Fair trade asks producers to follow standards that may exceed local law.","zh":"公平貿易要求生產者遵守可能高於本地法律的標準。"},{"en":"The phrase connects fair trade with workers’ rights.","zh":"這個詞組把公平貿易與工人權利連接起來。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":18},{"front":"be obliged to","meaning":"有義務","examples":[{"en":"Producers may follow standards although they are not obliged to do so locally.","zh":"生產者可能遵守標準，雖然在本地並沒有義務這樣做。"},{"en":"Be obliged to means be required or forced by rule, law, or duty.","zh":"有義務，指因規則、法律或責任而必須做。"},{"en":"A producer may not be legally obliged to follow certain international standards in their own country.","zh":"生產者在自己國家可能沒有法律義務遵守某些國際標準。"},{"en":"Fair trade can create obligations beyond local law.","zh":"公平貿易可以創造超越本地法律的義務。"},{"en":"The phrase describes requirement.","zh":"這個詞組描述要求。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":18},{"front":"in their own countries","meaning":"在他們自己的國家","examples":[{"en":"Some requirements are not legally binding in producers’ own countries.","zh":"一些要求在生產者自己的國家並不具法律約束力。"},{"en":"In their own countries means in the countries where the producers live or work.","zh":"在他們自己的國家，指在生產者生活或工作的國家。"},{"en":"Fair-trade standards may be stricter than local laws in producers’ own countries.","zh":"公平貿易標準可能比生產者本國法律更嚴格。"},{"en":"The phrase compares international standards with domestic law.","zh":"這個詞組比較國際標準與國內法律。"},{"en":"It helps explain why some standards may seem externally imposed.","zh":"它有助解釋為何一些標準可能看似外來強加。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":18},{"front":"United Nations obligations","meaning":"聯合國義務","examples":[{"en":"The option refers to United Nations obligations.","zh":"該選項提到聯合國義務。"},{"en":"United Nations obligations are duties connected with UN human-rights or labour principles.","zh":"聯合國義務，是與聯合國人權或勞工原則相關的責任。"},{"en":"In the passage, producers agree to follow human-rights standards associated with the UN.","zh":"在文章中，生產者同意遵守與聯合國相關的人權標準。"},{"en":"The phrase may appear as a possible answer choice.","zh":"這個詞組可能作為答案選項出現。"},{"en":"It relates to international ethical requirements.","zh":"它涉及國際道德要求。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":18},{"front":"too much corruption","meaning":"太多貪污腐敗","examples":[{"en":"The option suggests that the system involves too much corruption.","zh":"該選項表示該制度涉及太多貪污腐敗。"},{"en":"Too much corruption means excessive dishonesty, fraud, or abuse of power.","zh":"太多貪污腐敗，指過多不誠實、欺詐或濫用權力。"},{"en":"Mislabelled products may raise concerns about dishonesty in the system.","zh":"錯誤標籤產品可能引起人們對制度不誠實的關注。"},{"en":"The passage criticises monitoring, but students must check whether it states corruption directly.","zh":"文章批評監察，但學生必須核對它是否直接說有貪污。"},{"en":"The phrase describes a possible criticism.","zh":"這個詞組描述一種可能批評。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":18},{"front":"be adopted by","meaning":"被……採納","examples":[{"en":"Some practices may be adopted by non-fair-trade producers.","zh":"一些做法可能被非公平貿易生產者採納。"},{"en":"Be adopted by means be taken up or used by a person or group.","zh":"被某人採納，指被某人或群體接受並使用。"},{"en":"Environmental farming methods may be adopted by nearby farmers.","zh":"環保耕作方法可能被附近農民採納。"},{"en":"The phrase describes the spread of practices.","zh":"這個詞組描述做法的傳播。"},{"en":"It shows that fair trade may influence outsiders.","zh":"它顯示公平貿易可能影響外部人士。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":18},{"front":"agree with the claims of the writer","meaning":"與作者的說法一致","examples":[{"en":"Students must decide whether the statements agree with the writer’s claims.","zh":"學生必須判斷陳述是否與作者的說法一致。"},{"en":"Agree with the claims of the writer means match what the writer argues or believes.","zh":"與作者的說法一致，指符合作者的論點或信念。"},{"en":"Students should identify the writer’s view, not simply isolated facts.","zh":"學生應辨認作者觀點，而不只是孤立事實。"},{"en":"The phrase is common in YES/NO/NOT GIVEN tasks.","zh":"這個詞組常見於 YES/NO/NOT GIVEN 題型。"},{"en":"It focuses on the writer’s opinion.","zh":"它集中於作者意見。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":18},{"front":"contradict the writer’s claims","meaning":"與作者的說法相矛盾","examples":[{"en":"A “NO” answer contradicts the writer’s claims.","zh":"“NO” 答案與作者的說法相矛盾。"},{"en":"Contradict the writer’s claims means say the opposite of what the writer argues.","zh":"與作者的說法相矛盾，指說出與作者論點相反的內容。"},{"en":"If the writer says the poorest are excluded, a statement saying they are well assisted may contradict the claim.","zh":"如果作者說最貧窮者被排除，而陳述說他們得到良好幫助，便可能矛盾。"},{"en":"The phrase requires careful comparison with the writer’s view.","zh":"這個詞組需要仔細比較作者觀點。"},{"en":"It identifies disagreement with the text.","zh":"它指出與文本不一致。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":18},{"front":"impossible to say","meaning":"無法判斷","examples":[{"en":"Write “NOT GIVEN” if it is impossible to say what the writer thinks.","zh":"如果無法判斷作者怎樣想，便寫 “NOT GIVEN”。"},{"en":"Impossible to say means the passage does not provide enough evidence to decide.","zh":"無法判斷，指文章沒有提供足夠證據作決定。"},{"en":"A claim may sound reasonable but still be impossible to judge from the text.","zh":"一項說法可能聽起來合理，但仍無法從文本判斷。"},{"en":"Students should not guess the writer’s view.","zh":"學生不應猜測作者觀點。"},{"en":"The phrase explains when NOT GIVEN should be chosen.","zh":"這個詞組解釋何時應選 NOT GIVEN。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":18},{"front":"assist farmers who are extremely poor","meaning":"幫助極度貧困的農民","examples":[{"en":"The statement asks whether fair trade assists extremely poor farmers.","zh":"該陳述詢問公平貿易是否幫助極度貧困的農民。"},{"en":"Assist farmers who are extremely poor means help the poorest farmers improve their situation.","zh":"幫助極度貧困的農民，指協助最貧窮農民改善處境。"},{"en":"The passage says the desperately poor rarely participate.","zh":"文章說極度貧困者很少參與。"},{"en":"This suggests fair trade may not reach those it most wants to help.","zh":"這表示公平貿易可能未能接觸最希望幫助的人。"},{"en":"The phrase tests understanding of a key criticism.","zh":"這個詞組測試對關鍵批評的理解。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":19},{"front":"labelled as fair trade","meaning":"被標示為公平貿易","examples":[{"en":"Some products are labelled as fair trade.","zh":"一些產品被標示為公平貿易。"},{"en":"Labelled as fair trade means marked or described as meeting fair-trade standards.","zh":"被標示為公平貿易，指被標記或描述為符合公平貿易標準。"},{"en":"A label may influence consumers’ buying decisions.","zh":"標籤可能影響消費者購買決定。"},{"en":"The passage warns that some labelled goods may not truly be fair trade.","zh":"文章提醒一些標示商品可能並非真正公平貿易。"},{"en":"The phrase concerns product presentation.","zh":"這個詞組涉及產品呈現方式。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":19},{"front":"actually fair-trade products","meaning":"實際上的公平貿易產品","examples":[{"en":"Some labelled goods may not actually be fair-trade products.","zh":"一些標示商品可能實際上並不是公平貿易產品。"},{"en":"Actually fair-trade products are goods truly produced and sold according to fair-trade conditions.","zh":"實際上的公平貿易產品，是真正按照公平貿易條件生產和出售的商品。"},{"en":"Mislabelled goods may appear ethical without meeting standards.","zh":"錯誤標籤商品可能看似合乎道德，但沒有符合標準。"},{"en":"The phrase separates real status from label claims.","zh":"這個詞組把真實狀態與標籤聲稱分開。"},{"en":"It is important in judging certification reliability.","zh":"它對判斷認證可靠性很重要。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":19},{"front":"should not charge such high prices","meaning":"不應收取如此高價","examples":[{"en":"The statement asks whether retailers should not charge such high prices.","zh":"該陳述詢問零售商是否不應收取如此高價。"},{"en":"Should not charge such high prices means ought not ask consumers to pay so much.","zh":"不應收取如此高價，指不應要求消費者支付這麼多錢。"},{"en":"The passage criticises high prices when little money reaches producers.","zh":"文章批評在很少金錢到達生產者時仍收取高價。"},{"en":"The phrase concerns the writer’s view of retailer behaviour.","zh":"這個詞組涉及作者對零售商行為的看法。"},{"en":"It tests whether the reader can identify opinion, not just fact.","zh":"它測試讀者是否能辨認意見，而不只是事實。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":19},{"front":"marketing ploy","meaning":"市場推廣手段","examples":[{"en":"Some critics see fair trade as a marketing ploy.","zh":"一些批評者把公平貿易視為市場推廣手段。"},{"en":"A marketing ploy is a tactic used to sell products or attract customers.","zh":"市場推廣手段，是用來銷售產品或吸引顧客的策略。"},{"en":"Critics argue that ethical labels may be used mainly to raise prices.","zh":"批評者認為道德標籤可能主要被用來提高價格。"},{"en":"The phrase is less extreme than “colossal marketing scam” but still critical.","zh":"這個詞組比「巨型市場推廣騙局」較不極端，但仍帶批評。"},{"en":"It suggests commercial strategy rather than genuine help.","zh":"它表示商業策略，而不是真正幫助。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":19},{"front":"valid way of helping the poor","meaning":"幫助窮人的有效方法","examples":[{"en":"The statement asks whether fair trade is a valid way of helping the poor.","zh":"該陳述詢問公平貿易是否是幫助窮人的有效方法。"},{"en":"A valid way of helping the poor is a reasonable and effective method of reducing poverty.","zh":"幫助窮人的有效方法，是減少貧困的合理而有效方式。"},{"en":"The passage presents both criticism and defence of fair trade.","zh":"文章同時呈現對公平貿易的批評和辯護。"},{"en":"Critics question its transparency, while supporters point to its endurance and praise.","zh":"批評者質疑其透明度，而支持者則指出它持續存在並受到讚揚。"},{"en":"The phrase asks whether fair trade is genuinely useful.","zh":"這個詞組詢問公平貿易是否真正有用。"}],"source":"Passage 2 Flash Cards 166 - How Fair is Fair Trade?.pdf","sourcePage":19}],"ielts/reading/passage-2/Practice 167":[{"front":"Monday morning feeling","meaning":"星期一早上的感覺；星期一症候群","examples":[{"en":"The “Monday morning feeling” may be linked to stress after the weekend break.","zh":"「星期一早上的感覺」可能與週末休息後的壓力有關。"},{"en":"The phrase describes the tired, anxious feeling some people have when work begins again.","zh":"這個詞組描述一些人在重新開始工作時感到疲倦和焦慮。"},{"en":"For some workers, the Monday morning feeling may be more than a bad mood.","zh":"對某些上班族而言，星期一症候群可能不只是心情差。"},{"en":"Researchers studied whether this feeling is connected with heart attacks.","zh":"研究人員研究這種感覺是否與心臟病發作有關。"},{"en":"The passage links the Monday morning feeling with stress and health risk.","zh":"文章把星期一早上的感覺與壓力和健康風險連繫起來。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":1},{"front":"a crushing pain in the chest","meaning":"胸口壓迫般劇痛","examples":[{"en":"A heart attack can feel like a crushing pain in the chest.","zh":"心臟病發作可能感覺像胸口壓迫般劇痛。"},{"en":"The phrase describes severe pressure or tightness in the chest area.","zh":"這個詞組描述胸口位置嚴重受壓或繃緊。"},{"en":"A crushing pain in the chest may be a warning sign of a heart attack.","zh":"胸口壓迫般劇痛可能是心臟病發作的警號。"},{"en":"The pain may leave a person frightened, sweating and short of breath.","zh":"這種疼痛可能令人害怕、冒汗並喘不過氣。"},{"en":"The passage uses this phrase to describe a dramatic medical emergency.","zh":"文章用這個詞組描述戲劇性的醫療急症。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":1},{"front":"leave someone sweating and gasping for breath","meaning":"令某人冒汗並喘不過氣","examples":[{"en":"A severe chest pain may leave someone sweating and gasping for breath.","zh":"嚴重胸痛可能令某人冒汗並喘不過氣。"},{"en":"The phrase means to cause someone to sweat and struggle to breathe.","zh":"這個詞組指令某人出汗並努力呼吸。"},{"en":"A heart attack can leave a patient sweating and gasping for breath.","zh":"心臟病發作可能令病人冒汗並喘不過氣。"},{"en":"These symptoms suggest the body is under serious stress.","zh":"這些症狀表示身體正承受嚴重壓力。"},{"en":"The phrase creates a vivid picture of physical distress.","zh":"這個詞組生動描繪身體痛苦。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":1},{"front":"gasping for breath","meaning":"喘不過氣","examples":[{"en":"The patient was gasping for breath during the attack.","zh":"病人在發作期間喘不過氣。"},{"en":"Gasping for breath means struggling to breathe or taking quick, desperate breaths.","zh":"喘不過氣指呼吸困難，或急促而吃力地呼吸。"},{"en":"Someone gasping for breath needs urgent medical attention.","zh":"喘不過氣的人需要緊急醫療照顧。"},{"en":"The phrase often appears in descriptions of severe illness or panic.","zh":"這個詞組常出現在嚴重疾病或恐慌的描述中。"},{"en":"In the passage, it helps show how frightening a heart attack can be.","zh":"在文章中，它幫助顯示心臟病發作可以多麼可怕。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":1},{"front":"recent research from","meaning":"來自……的最新研究","examples":[{"en":"Recent research from Germany and Italy examined heart attacks on Monday mornings.","zh":"來自德國和意大利的最新研究檢視星期一早上的心臟病發作。"},{"en":"The phrase introduces studies carried out by researchers in particular places.","zh":"這個詞組引出由特定地方研究人員進行的研究。"},{"en":"Recent research from Europe found a pattern in heart-attack timing.","zh":"來自歐洲的最新研究發現心臟病發作時間有一種模式。"},{"en":"Such research helps doctors understand possible triggers.","zh":"這類研究幫助醫生了解可能的觸發因素。"},{"en":"In the passage, the phrase leads into evidence from two countries.","zh":"在文章中，這個詞組引出兩個國家的證據。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":1},{"front":"heart attacks","meaning":"心臟病發作","examples":[{"en":"Heart attacks are more common on Monday mornings.","zh":"心臟病發作在星期一早上較常見。"},{"en":"Heart attacks occur when blood flow to the heart is blocked.","zh":"心臟病發作是心臟血流受阻時發生的。"},{"en":"Researchers studied whether stress can trigger heart attacks.","zh":"研究人員研究壓力是否會觸發心臟病發作。"},{"en":"Monday mornings appear to be a high-risk time for heart attacks.","zh":"星期一早上似乎是心臟病發作的高風險時間。"},{"en":"The passage focuses on when heart attacks are most likely to happen.","zh":"文章集中於心臟病發作最可能在何時發生。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":1},{"front":"more common on","meaning":"在……較常見","examples":[{"en":"Heart attacks are more common on Monday mornings than on other days.","zh":"心臟病發作在星期一早上比其他日子較常見。"},{"en":"More common on means happening more often on a particular day or time.","zh":"在某時較常見，指在特定日子或時間發生得更頻密。"},{"en":"The studies found that attacks were more common on Mondays.","zh":"研究發現發作在星期一較常見。"},{"en":"Sunday, by contrast, had fewer heart attacks.","zh":"相比之下，星期日心臟病發作較少。"},{"en":"The phrase is used to compare frequency across days.","zh":"這個詞組用來比較不同日子的發生頻率。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":1},{"front":"blame the stress of","meaning":"把……歸咎於……的壓力","examples":[{"en":"Doctors blame the stress of returning to work after the weekend break.","zh":"醫生把這歸咎於週末休息後重返工作的壓力。"},{"en":"To blame the stress of something means to identify that stress as a possible cause.","zh":"把某事歸咎於某種壓力，指把該壓力視為可能原因。"},{"en":"Researchers blame work-related stress for part of the Monday risk.","zh":"研究人員把星期一部分風險歸咎於工作相關壓力。"},{"en":"The phrase introduces one explanation for the higher number of attacks.","zh":"這個詞組引出發作次數較高的一種解釋。"},{"en":"It suggests that emotional pressure can affect physical health.","zh":"它表示情緒壓力可以影響身體健康。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":1},{"front":"returning to work","meaning":"重返工作崗位","examples":[{"en":"Returning to work after the weekend may increase stress.","zh":"週末後重返工作崗位可能增加壓力。"},{"en":"Returning to work means going back to one’s job after time off.","zh":"重返工作崗位，指休息後回到自己的工作。"},{"en":"Monday morning often involves returning to work and facing new demands.","zh":"星期一早上通常涉及重返工作崗位並面對新要求。"},{"en":"The passage suggests this transition may affect the heart.","zh":"文章指出這種過渡可能影響心臟。"},{"en":"The phrase is central to the work-stress explanation.","zh":"這個詞組是工作壓力解釋的核心。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":1},{"front":"the weekend break","meaning":"週末休息","examples":[{"en":"The weekend break is followed by the pressures of work.","zh":"週末休息之後是工作壓力。"},{"en":"The weekend break means the period of rest away from work during the weekend.","zh":"週末休息指週末離開工作的休息時間。"},{"en":"After the weekend break, people may face a sudden change in routine.","zh":"週末休息後，人們可能面對日常規律的突然改變。"},{"en":"The contrast between rest and work may create stress.","zh":"休息與工作之間的對比可能造成壓力。"},{"en":"The phrase helps explain why Monday morning is different from Sunday.","zh":"這個詞組幫助解釋為何星期一早上不同於星期日。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":1},{"front":"the risk of having","meaning":"患上……的風險","examples":[{"en":"The risk of having a heart attack varies during the week.","zh":"患上心臟病發作的風險在一週中有所不同。"},{"en":"The risk of having something means the chance that it will happen to a person.","zh":"患上某事的風險，指某事發生在某人身上的機會。"},{"en":"The research measured the risk of having a heart attack on different days.","zh":"研究量度不同日子患上心臟病發作的風險。"},{"en":"Monday carried a higher risk than expected.","zh":"星期一的風險比預期高。"},{"en":"The phrase is useful in medical and statistical contexts.","zh":"這個詞組常用於醫學和統計語境。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":1},{"front":"on any given day","meaning":"在任何指定日子","examples":[{"en":"The risk should be the same on any given day.","zh":"風險在任何指定日子本應相同。"},{"en":"On any given day means on any particular day chosen at random.","zh":"在任何指定日子，指隨機選出的任何一個特定日子。"},{"en":"If risk were evenly spread, each day would have the same chance.","zh":"如果風險平均分布，每天的機會應該相同。"},{"en":"The studies showed that Monday did not fit this expectation.","zh":"研究顯示星期一不符合這種預期。"},{"en":"The phrase helps explain the statistical comparison.","zh":"這個詞組幫助解釋統計比較。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":2},{"front":"one in seven","meaning":"七分之一","examples":[{"en":"The expected daily risk should be one in seven.","zh":"預期的每日風險應是七分之一。"},{"en":"One in seven means one out of seven equal parts or chances.","zh":"七分之一，指七等份或七個機會中的一份。"},{"en":"If heart attacks were evenly spread through the week, each day would have a one-in-seven share.","zh":"如果心臟病發作在一週中平均分布，每天應佔七分之一。"},{"en":"Monday’s actual risk was higher than this expectation.","zh":"星期一的實際風險高於這個預期。"},{"en":"The phrase gives a simple statistical baseline.","zh":"這個詞組提供簡單統計基準。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":2},{"front":"a six-year study","meaning":"為期六年的研究","examples":[{"en":"A six-year study found a higher heart-attack risk on Mondays.","zh":"一項為期六年的研究發現星期一心臟病發作風險較高。"},{"en":"A six-year study is research carried out over six years.","zh":"為期六年的研究，是持續六年進行的研究。"},{"en":"The long study period made the findings more substantial.","zh":"較長研究時間令結果更具份量。"},{"en":"It involved more than 2,600 Germans.","zh":"它涉及超過二千六百名德國人。"},{"en":"The phrase introduces one major piece of evidence.","zh":"這個詞組引出一項主要證據。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":2},{"front":"coordinated by","meaning":"由……協調","examples":[{"en":"The study was coordinated by researchers at the Free University of Berlin.","zh":"該研究由柏林自由大學的研究人員協調。"},{"en":"Coordinated by means organised or managed by a particular group.","zh":"由某人協調，指由某個群體組織或管理。"},{"en":"Researchers in Berlin coordinated the German heart-attack study.","zh":"柏林的研究人員協調德國心臟病發作研究。"},{"en":"The phrase identifies who oversaw the research.","zh":"這個詞組指出誰負責統籌研究。"},{"en":"It adds academic context to the study.","zh":"它為研究加入學術背景。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":2},{"front":"involving more than","meaning":"涉及超過……","examples":[{"en":"The study involved more than 2,600 Germans.","zh":"該研究涉及超過二千六百名德國人。"},{"en":"Involving more than means including a number greater than the one stated.","zh":"涉及超過，指包括多於所述數字的數量。"},{"en":"A study involving more than 2,600 people provides a large sample.","zh":"涉及超過二千六百人的研究提供了大型樣本。"},{"en":"The phrase describes the scale of participation.","zh":"這個詞組描述參與規模。"},{"en":"It helps readers judge the size of the research.","zh":"它幫助讀者判斷研究大小。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":2},{"front":"revealed that","meaning":"顯示；揭示","examples":[{"en":"The study revealed that Monday carried a higher risk.","zh":"該研究顯示星期一帶有較高風險。"},{"en":"Revealed that means showed or made known through evidence.","zh":"顯示或揭示，指透過證據展示或使人知道。"},{"en":"The data revealed that heart attacks were not evenly distributed.","zh":"數據顯示心臟病發作並非平均分布。"},{"en":"The phrase introduces a research finding.","zh":"這個詞組引出研究發現。"},{"en":"It is commonly used when reporting study results.","zh":"它常用於報告研究結果。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":2},{"front":"the average person","meaning":"一般人","examples":[{"en":"The average person had a higher chance of having a heart attack on Monday.","zh":"一般人在星期一心臟病發作的機會較高。"},{"en":"The average person means a typical person in the study population.","zh":"一般人指研究人群中的典型人士。"},{"en":"The phrase does not refer to one named individual.","zh":"這個詞組不是指某一個具名個人。"},{"en":"It summarises a general risk pattern.","zh":"它概括一般風險模式。"},{"en":"The average person’s Monday risk was higher than on other days.","zh":"一般人的星期一風險比其他日子高。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":2},{"front":"a 20 per cent higher chance","meaning":"高出百分之二十的機會","examples":[{"en":"The average person had a 20 per cent higher chance of a heart attack on Monday.","zh":"一般人在星期一心臟病發作的機會高出百分之二十。"},{"en":"A 20 per cent higher chance means the risk was one-fifth higher than the comparison level.","zh":"高出百分之二十的機會，指風險比比較水平高五分之一。"},{"en":"This figure shows that the Monday effect was measurable.","zh":"這個數字顯示星期一效應可以被量度。"},{"en":"The phrase gives a precise statistical result.","zh":"這個詞組提供精確統計結果。"},{"en":"It helps show why researchers considered Monday a high-risk day.","zh":"它幫助顯示為何研究人員視星期一為高風險日。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":2},{"front":"than on any other day","meaning":"比任何其他日子","examples":[{"en":"The risk was higher on Monday than on any other day.","zh":"星期一的風險比任何其他日子都高。"},{"en":"Than on any other day means compared with all the other days of the week.","zh":"比任何其他日子，指與一週中所有其他日子相比。"},{"en":"Monday stood out as the day with the highest risk.","zh":"星期一成為風險最高的一天。"},{"en":"The phrase gives a strong comparison.","zh":"這個詞組作出強烈比較。"},{"en":"It supports the idea of a Monday morning peak.","zh":"它支持星期一早上高峰的想法。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":2},{"front":"working Germans","meaning":"在職德國人","examples":[{"en":"Working Germans are particularly vulnerable at the beginning of the week.","zh":"在職德國人在一週開始時特別容易受影響。"},{"en":"Working Germans means German people who are employed or working.","zh":"在職德國人指有工作或受僱的德國人。"},{"en":"The study found that this group faced a higher Monday risk.","zh":"研究發現這個群體面對較高星期一風險。"},{"en":"Their vulnerability supports the work-stress explanation.","zh":"他們的脆弱性支持工作壓力解釋。"},{"en":"The phrase identifies the subgroup most affected in the German study.","zh":"這個詞組指出德國研究中最受影響的子群體。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":2},{"front":"particularly vulnerable","meaning":"特別容易受影響","examples":[{"en":"Working Germans are particularly vulnerable on Monday mornings.","zh":"在職德國人在星期一早上特別容易受影響。"},{"en":"Particularly vulnerable means especially likely to be harmed or affected.","zh":"特別容易受影響，指尤其可能受傷害或被影響。"},{"en":"The start of the working week may make workers particularly vulnerable.","zh":"工作週開始可能令上班族特別容易受影響。"},{"en":"The phrase highlights a group at higher risk.","zh":"這個詞組突出較高風險群體。"},{"en":"It is used in the passage to describe employed Germans.","zh":"在文章中，它用來描述受僱德國人。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":2},{"front":"a higher risk","meaning":"較高風險","examples":[{"en":"Working Germans have a higher risk at the start of the week.","zh":"在職德國人在一週開始時有較高風險。"},{"en":"A higher risk means a greater chance that something bad will happen.","zh":"較高風險，指不良事件發生的機會更大。"},{"en":"Monday morning carries a higher risk for some people with heart disease.","zh":"對某些心臟病患者而言，星期一早上帶有較高風險。"},{"en":"The phrase is used to compare groups or times.","zh":"這個詞組用來比較群體或時間。"},{"en":"It helps describe the main research finding.","zh":"它有助描述主要研究發現。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":3},{"front":"at the beginning of","meaning":"在……開始時","examples":[{"en":"The risk rises at the beginning of the working week.","zh":"風險在工作週開始時上升。"},{"en":"At the beginning of means at the start of a period.","zh":"在……開始時，指在某段時期的起點。"},{"en":"Monday is at the beginning of the working week for many people.","zh":"對很多人而言，星期一是在工作週開始時。"},{"en":"The phrase helps explain the timing of stress.","zh":"這個詞組幫助解釋壓力出現的時間。"},{"en":"It links the calendar with heart-attack risk.","zh":"它把日曆與心臟病發作風險連接起來。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":3},{"front":"the working week","meaning":"工作週","examples":[{"en":"Monday marks the beginning of the working week for many people.","zh":"對很多人而言，星期一標誌工作週的開始。"},{"en":"The working week is the part of the week when people normally work.","zh":"工作週是一星期中人們通常工作的部分。"},{"en":"Returning to the working week may increase stress after rest.","zh":"週末休息後重返工作週可能增加壓力。"},{"en":"The phrase is central to the Monday-risk explanation.","zh":"這個詞組是星期一風險解釋的核心。"},{"en":"It contrasts with the weekend break.","zh":"它與週末休息形成對比。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":3},{"front":"non-workers","meaning":"非在職人士","examples":[{"en":"Non-workers do not appear to face the same Monday risk.","zh":"非在職人士看來沒有面對相同的星期一風險。"},{"en":"Non-workers are people who are not employed or not working.","zh":"非在職人士是沒有受僱或沒有工作的人。"},{"en":"The German study compared workers with non-workers.","zh":"德國研究比較了在職人士與非在職人士。"},{"en":"Non-workers were no more at risk on Monday than on other days.","zh":"非在職人士在星期一的風險並不比其他日子高。"},{"en":"The phrase helps support the idea that work stress matters.","zh":"這個詞組有助支持工作壓力重要的想法。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":3},{"front":"by comparison","meaning":"相比之下","examples":[{"en":"By comparison, non-workers are no more at risk on Mondays.","zh":"相比之下，非在職人士在星期一的風險並沒有更高。"},{"en":"By comparison means when compared with another group or situation.","zh":"相比之下，指與另一群體或情況比較時。"},{"en":"Workers had a higher Monday risk; by comparison, non-workers did not.","zh":"在職人士有較高星期一風險；相比之下，非在職人士沒有。"},{"en":"The phrase introduces a contrast.","zh":"這個詞組引出對比。"},{"en":"It helps readers see the difference between groups.","zh":"它幫助讀者看出群體之間的差異。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":3},{"front":"appear to be","meaning":"看來是","examples":[{"en":"Non-workers appear to be no more at risk on Monday.","zh":"非在職人士在星期一看來並沒有更高風險。"},{"en":"Appear to be means seem to be based on available evidence.","zh":"看來是，指根據現有證據似乎如此。"},{"en":"The phrase is cautious because the conclusion depends on study data.","zh":"這個詞組較謹慎，因為結論取決於研究數據。"},{"en":"It does not claim absolute certainty.","zh":"它沒有聲稱絕對確定。"},{"en":"It is common in scientific reporting.","zh":"它常見於科學報告。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":3},{"front":"no more at risk","meaning":"風險並沒有更高","examples":[{"en":"Non-workers are no more at risk on Monday than on other days.","zh":"非在職人士在星期一的風險並沒有比其他日子更高。"},{"en":"No more at risk means not facing a higher danger than usual.","zh":"風險並沒有更高，指沒有面對比平常更大的危險。"},{"en":"This contrasts with the pattern for working Germans.","zh":"這與在職德國人的模式形成對比。"},{"en":"The phrase suggests that employment may influence Monday risk.","zh":"這個詞組表示就業狀況可能影響星期一風險。"},{"en":"It helps interpret the German study results.","zh":"它有助解讀德國研究結果。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":3},{"front":"a study of","meaning":"一項關於……的研究","examples":[{"en":"A study of 11,000 Italians identified the most stressful time for the heart.","zh":"一項關於一萬一千名意大利人的研究指出對心臟而言壓力最大的時間。"},{"en":"A study of a group means research involving that group.","zh":"一項關於某群體的研究，指涉及該群體的研究。"},{"en":"The Italian study examined heart attacks among 11,000 people.","zh":"意大利研究檢視一萬一千人中的心臟病發作。"},{"en":"The phrase introduces the sample of a research project.","zh":"這個詞組引出研究項目的樣本。"},{"en":"It helps show the scale of the evidence.","zh":"它幫助顯示證據的規模。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":3},{"front":"identified","meaning":"確定；指出","examples":[{"en":"The study identified Monday morning as the most stressful time for the heart.","zh":"該研究確定星期一早上是對心臟而言壓力最大的時間。"},{"en":"Identified means found, recognised or pointed out.","zh":"確定或指出，指發現、辨認或指明。"},{"en":"The researchers identified a peak at eight o’clock on Monday morning.","zh":"研究人員指出星期一早上八點有一個高峰。"},{"en":"The phrase reports a conclusion from evidence.","zh":"這個詞組報告由證據得出的結論。"},{"en":"It is often used in scientific findings.","zh":"它常用於科學發現。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":3},{"front":"the most stressful time","meaning":"壓力最大的時間","examples":[{"en":"Eight o’clock on Monday morning was identified as the most stressful time.","zh":"星期一早上八點被指出是壓力最大的時間。"},{"en":"The most stressful time means the time with the greatest pressure or strain.","zh":"壓力最大的時間，指壓力或負荷最高的時刻。"},{"en":"For the heart, this time may involve physical and work-related stress.","zh":"對心臟而言，這個時間可能涉及身體和工作相關壓力。"},{"en":"The phrase highlights a specific high-risk moment.","zh":"這個詞組突出一個具體高風險時刻。"},{"en":"It links daily routine with heart stress.","zh":"它把日常生活規律與心臟壓力連接起來。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":3},{"front":"for the heart","meaning":"對心臟而言","examples":[{"en":"Monday morning may be the most stressful time for the heart.","zh":"星期一早上對心臟而言可能是壓力最大的時間。"},{"en":"For the heart means in relation to the heart’s condition or workload.","zh":"對心臟而言，指就心臟狀況或負荷而言。"},{"en":"Physical changes after waking can be stressful for the heart.","zh":"醒來後的身體變化可能對心臟造成壓力。"},{"en":"Work pressure may add further strain.","zh":"工作壓力可能再增加負荷。"},{"en":"The phrase focuses on the body organ affected.","zh":"這個詞組集中於受影響的身體器官。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":3},{"front":"both studies showed that","meaning":"兩項研究均顯示","examples":[{"en":"Both studies showed that Sunday was the least stressful day.","zh":"兩項研究均顯示星期日是壓力最小的一天。"},{"en":"Both studies showed that means two separate studies reached the same finding.","zh":"兩項研究均顯示，指兩個獨立研究得出相同發現。"},{"en":"The German and Italian studies both found fewer heart attacks on Sunday.","zh":"德國和意大利研究都發現星期日心臟病發作較少。"},{"en":"The phrase strengthens the reliability of the pattern.","zh":"這個詞組加強該模式的可靠性。"},{"en":"It introduces agreement between two sets of data.","zh":"它引出兩組數據之間的一致性。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":4},{"front":"the least stressful day","meaning":"壓力最小的一天","examples":[{"en":"Sunday is the least stressful day for the heart.","zh":"星期日是對心臟而言壓力最小的一天。"},{"en":"The least stressful day means the day with the lowest pressure or strain.","zh":"壓力最小的一天，指壓力或負荷最低的日子。"},{"en":"Sunday had fewer heart attacks in both countries.","zh":"在兩個國家，星期日心臟病發作較少。"},{"en":"The phrase contrasts Sunday with high-risk Monday.","zh":"這個詞組把星期日與高風險星期一作對比。"},{"en":"It supports the idea that work routines may influence risk.","zh":"它支持工作規律可能影響風險的想法。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":4},{"front":"fewer heart attacks","meaning":"較少心臟病發作","examples":[{"en":"There were fewer heart attacks on Sundays in both countries.","zh":"在兩個國家，星期日有較少心臟病發作。"},{"en":"Fewer heart attacks means a smaller number of heart attacks occurred.","zh":"較少心臟病發作，指發生的心臟病發作數量較少。"},{"en":"The phrase gives a comparison with other days.","zh":"這個詞組提供與其他日子的比較。"},{"en":"Sunday appeared safer for the heart than Monday.","zh":"星期日對心臟而言似乎比星期一更安全。"},{"en":"It is part of the evidence for a weekly pattern.","zh":"它是一週模式證據的一部分。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":4},{"front":"in both countries","meaning":"在兩個國家","examples":[{"en":"Fewer heart attacks occurred on Sundays in both countries.","zh":"在兩個國家，星期日心臟病發作較少。"},{"en":"In both countries means in Germany and Italy.","zh":"在兩個國家，指在德國和意大利。"},{"en":"The pattern appeared in two different national settings.","zh":"這個模式出現在兩個不同國家背景中。"},{"en":"This makes the finding more persuasive.","zh":"這令發現更具說服力。"},{"en":"The phrase supports the consistency of the research results.","zh":"這個詞組支持研究結果的一致性。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":4},{"front":"the findings","meaning":"研究結果","examples":[{"en":"The findings could improve our understanding of heart attacks.","zh":"研究結果可以改善我們對心臟病發作的理解。"},{"en":"The findings are the results of the studies.","zh":"研究結果是研究所得出的結果。"},{"en":"These findings show a Monday morning peak in heart attacks.","zh":"這些結果顯示星期一早上心臟病發作有高峰。"},{"en":"They may help researchers study triggers more closely.","zh":"它們可能幫助研究人員更仔細研究觸發因素。"},{"en":"The phrase refers to the evidence produced by the research.","zh":"這個詞組指研究產生的證據。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":4},{"front":"lead to","meaning":"導致；帶來","examples":[{"en":"The findings could lead to a better understanding of heart attacks.","zh":"研究結果可能帶來對心臟病發作更深入的理解。"},{"en":"Lead to means result in or cause something to happen.","zh":"導致或帶來，指造成某事發生或產生結果。"},{"en":"Better data may lead to better prevention advice.","zh":"更好的數據可能帶來更好的預防建議。"},{"en":"The phrase links research results with future benefits.","zh":"這個詞組把研究結果與未來好處連接起來。"},{"en":"It shows why the studies matter medically.","zh":"它顯示這些研究在醫學上為何重要。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":4},{"front":"a better understanding of","meaning":"對……有更深入了解","examples":[{"en":"The research may lead to a better understanding of what triggers heart attacks.","zh":"研究可能帶來對觸發心臟病發作原因的更深入了解。"},{"en":"A better understanding of something means deeper or clearer knowledge about it.","zh":"對某事有更深入了解，指對它有更深或更清楚的認識。"},{"en":"Doctors know long-term risks but need a better understanding of triggers.","zh":"醫生知道長期風險，但需要更深入了解觸發因素。"},{"en":"The phrase describes the goal of the research.","zh":"這個詞組描述研究目標。"},{"en":"It suggests current knowledge is incomplete.","zh":"它表示目前知識仍不完整。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":4},{"front":"what triggers heart attacks","meaning":"觸發心臟病發作的原因","examples":[{"en":"Doctors want to understand what triggers heart attacks.","zh":"醫生想了解觸發心臟病發作的原因。"},{"en":"What triggers heart attacks means the immediate causes that set them off.","zh":"觸發心臟病發作的原因，指引發發作的即時因素。"},{"en":"Stress, bodily changes and clots may all be part of the triggering process.","zh":"壓力、身體變化和血栓都可能是觸發過程的一部分。"},{"en":"The phrase distinguishes triggers from long-term risk factors.","zh":"這個詞組把觸發因素與長期風險因素區分開。"},{"en":"It is central to the medical question in the passage.","zh":"它是文章中的醫學核心問題。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":4},{"front":"according to","meaning":"根據","examples":[{"en":"According to Dr. Stefan Willich, scientists know more about long-term risks than triggers.","zh":"根據 Stefan Willich 醫生所說，科學家對長期風險的了解多於觸發因素。"},{"en":"According to means as stated by a person or source.","zh":"根據，指按照某人或某來源所說。"},{"en":"The phrase introduces expert opinion.","zh":"這個詞組引出專家意見。"},{"en":"It helps attribute the claim to Dr. Willich.","zh":"它幫助把該說法歸於 Willich 醫生。"},{"en":"It is common in academic and journalistic writing.","zh":"它常見於學術和新聞寫作。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":4},{"front":"long-term risk factors","meaning":"長期風險因素","examples":[{"en":"Smoking and cholesterol are long-term risk factors.","zh":"吸煙和膽固醇是長期風險因素。"},{"en":"Long-term risk factors are conditions or habits that increase danger over time.","zh":"長期風險因素是隨時間增加危險的狀況或習慣。"},{"en":"They are different from immediate triggers of a heart attack.","zh":"它們不同於心臟病發作的即時觸發因素。"},{"en":"Doctors understand some long-term risk factors better than short-term triggers.","zh":"醫生對某些長期風險因素的了解多於短期觸發因素。"},{"en":"The phrase is important in explaining what remains unknown.","zh":"這個詞組對解釋仍未知的內容很重要。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":4},{"front":"smoking and cholesterol","meaning":"吸煙和膽固醇","examples":[{"en":"Smoking and cholesterol are linked to heart disease risk.","zh":"吸煙和膽固醇與心臟病風險有關。"},{"en":"Smoking is a harmful habit, and cholesterol is a fatty substance in the blood.","zh":"吸煙是一種有害習慣，而膽固醇是血液中的脂肪物質。"},{"en":"Both are examples of long-term risk factors.","zh":"兩者都是長期風險因素的例子。"},{"en":"They do not fully explain why attacks peak on Monday mornings.","zh":"它們不能完全解釋為何發作在星期一早上達到高峰。"},{"en":"The phrase contrasts known risks with unknown triggers.","zh":"這個詞組把已知風險與未知觸發因素作對比。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":4},{"front":"don’t know what actually triggers","meaning":"不知道究竟是甚麼觸發","examples":[{"en":"Doctors do not know what actually triggers heart attacks.","zh":"醫生不知道究竟是甚麼觸發心臟病發作。"},{"en":"The phrase means the immediate cause is still uncertain.","zh":"這個詞組表示即時原因仍不確定。"},{"en":"Researchers can identify risk factors but still ask what sets off an attack.","zh":"研究人員可以識別風險因素，但仍追問甚麼引發發作。"},{"en":"Monday morning patterns may help answer this question.","zh":"星期一早上的模式可能有助回答這個問題。"},{"en":"It highlights a gap in medical knowledge.","zh":"它突出醫學知識中的空白。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":5},{"front":"specific recommendations","meaning":"具體建議","examples":[{"en":"Doctors cannot yet make specific recommendations about prevention.","zh":"醫生尚未能就預防提出具體建議。"},{"en":"Specific recommendations are detailed, practical pieces of advice.","zh":"具體建議是詳細而實際的意見。"},{"en":"More evidence is needed before doctors can give precise guidance.","zh":"醫生需要更多證據，才能給出精確指引。"},{"en":"The phrase shows caution in medical advice.","zh":"這個詞組顯示醫療建議上的謹慎。"},{"en":"It contrasts with general suggestions such as taking it easy.","zh":"它與「放鬆一點」等一般建議形成對比。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":5},{"front":"how to prevent them","meaning":"如何預防它們","examples":[{"en":"Researchers want to understand how to prevent heart attacks.","zh":"研究人員想了解如何預防心臟病發作。"},{"en":"How to prevent them means ways to stop them from happening.","zh":"如何預防它們，指阻止它們發生的方法。"},{"en":"Understanding triggers may help doctors learn how to prevent attacks.","zh":"理解觸發因素可能幫助醫生學會如何預防發作。"},{"en":"The phrase gives the practical goal of the research.","zh":"這個詞組給出研究的實際目標。"},{"en":"It connects scientific knowledge with health protection.","zh":"它把科學知識與健康保護連接起來。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":5},{"front":"a double helping of stress","meaning":"雙重壓力","examples":[{"en":"Monday mornings bring a double helping of stress for the working body.","zh":"星期一早上為上班族的身體帶來雙重壓力。"},{"en":"A double helping of stress means two sources or layers of stress at once.","zh":"雙重壓力，指同時出現兩種來源或層面的壓力。"},{"en":"The body moves from sleep to activity and from weekend rest to work pressure.","zh":"身體從睡眠轉向活動，也從週末休息轉向工作壓力。"},{"en":"This combination may increase strain on the heart.","zh":"這種組合可能增加心臟負荷。"},{"en":"The phrase vividly describes Monday morning’s twofold burden.","zh":"這個詞組生動描述星期一早上的雙重負擔。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":5},{"front":"the working body","meaning":"工作中的身體；上班族的身體","examples":[{"en":"The working body faces both physical and work-related stress on Monday mornings.","zh":"上班族的身體在星期一早上面對身體和工作相關壓力。"},{"en":"The working body means the body of a person returning to work.","zh":"工作中的身體，指重返工作的人之身體。"},{"en":"It must adjust to waking, movement and job demands.","zh":"它必須適應醒來、活動和工作要求。"},{"en":"The phrase personifies the body as part of working life.","zh":"這個詞組把身體擬人化為工作生活的一部分。"},{"en":"It links employment routines with physical strain.","zh":"它把就業規律與身體負荷連接起來。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":5},{"front":"makes a rapid transition from…to…","meaning":"從……迅速過渡到……","examples":[{"en":"The body makes a rapid transition from sleep to activity.","zh":"身體從睡眠迅速過渡到活動。"},{"en":"The phrase means it changes quickly from one state to another.","zh":"這個詞組表示從一種狀態快速轉變到另一種狀態。"},{"en":"On Monday, the body also moves from weekend relaxation to work pressure.","zh":"在星期一，身體也從週末放鬆迅速過渡到工作壓力。"},{"en":"A rapid transition may strain the circulatory system.","zh":"快速過渡可能令循環系統受壓。"},{"en":"It explains one physical part of the Monday morning risk.","zh":"它解釋星期一早上風險的一個身體因素。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":5},{"front":"from sleep to activity","meaning":"從睡眠到活動","examples":[{"en":"The body changes quickly from sleep to activity in the morning.","zh":"早上身體會從睡眠快速轉到活動。"},{"en":"From sleep to activity describes the shift that happens after waking.","zh":"從睡眠到活動描述醒來後發生的轉變。"},{"en":"This change raises blood pressure and heart rate.","zh":"這種變化會令血壓和心率上升。"},{"en":"The phrase focuses on the body’s daily morning adjustment.","zh":"這個詞組集中於身體每日早上的調整。"},{"en":"It is one part of the double stress described in the passage.","zh":"它是文章所述雙重壓力的一部分。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":5},{"front":"from the relaxing weekend to","meaning":"從輕鬆週末到……","examples":[{"en":"People move from the relaxing weekend to the pressures of work.","zh":"人們從輕鬆週末轉到工作壓力。"},{"en":"The phrase describes a change from rest to responsibility.","zh":"這個詞組描述由休息轉向責任的變化。"},{"en":"Monday morning makes this contrast especially sharp.","zh":"星期一早上令這種對比尤其明顯。"},{"en":"The sudden shift may create psychological stress.","zh":"突然轉變可能造成心理壓力。"},{"en":"It explains the work-related part of Monday morning strain.","zh":"它解釋星期一早上壓力中與工作相關的部分。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":5},{"front":"the pressures of work","meaning":"工作壓力","examples":[{"en":"The pressures of work may affect the body on Monday mornings.","zh":"工作壓力可能在星期一早上影響身體。"},{"en":"The pressures of work are demands, responsibilities and stress connected with a job.","zh":"工作壓力是與工作有關的要求、責任和壓力。"},{"en":"Meetings, deadlines and workload can all be work pressures.","zh":"會議、期限和工作量都可以是工作壓力。"},{"en":"These pressures may contribute to the Monday heart-attack peak.","zh":"這些壓力可能促成星期一心臟病發作高峰。"},{"en":"The phrase links employment with stress.","zh":"這個詞組把就業與壓力連接起來。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":5},{"front":"blood pressure","meaning":"血壓","examples":[{"en":"Blood pressure often rises when people get up.","zh":"人們起床時血壓通常會上升。"},{"en":"Blood pressure is the force of blood pushing against artery walls.","zh":"血壓是血液推動動脈壁的力量。"},{"en":"A rise in blood pressure can increase strain on the heart.","zh":"血壓上升可以增加心臟負荷。"},{"en":"Morning changes in blood pressure are part of the body’s transition to activity.","zh":"早晨血壓變化是身體轉向活動的一部分。"},{"en":"The phrase describes a key physical factor in the passage.","zh":"這個詞組描述文章中的一項關鍵身體因素。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":5},{"front":"heart rate","meaning":"心率","examples":[{"en":"Heart rate goes up when people become active.","zh":"當人們變得活躍時，心率會上升。"},{"en":"Heart rate is the number of times the heart beats in a period of time.","zh":"心率是心臟在一段時間內跳動的次數。"},{"en":"Rising heart rate after waking is a normal physical change.","zh":"醒來後心率上升是正常身體變化。"},{"en":"Together with stress, it may add strain to the circulatory system.","zh":"與壓力一起，它可能增加循環系統負荷。"},{"en":"The phrase helps explain the body’s Monday morning response.","zh":"這個詞組有助解釋身體在星期一早上的反應。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":5},{"front":"go up","meaning":"上升","examples":[{"en":"Blood pressure and heart rate go up after people get out of bed.","zh":"人們起床後，血壓和心率會上升。"},{"en":"Go up means increase or rise.","zh":"上升指增加或提高。"},{"en":"These physical measures go up as the body becomes active.","zh":"當身體變得活躍時，這些身體指標會上升。"},{"en":"Stress can make them go up further.","zh":"壓力可以令它們進一步上升。"},{"en":"The phrase describes a simple upward change.","zh":"這個詞組描述簡單的向上變化。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":6},{"front":"hormonal changes","meaning":"荷爾蒙變化","examples":[{"en":"There are hormonal changes in the body after waking.","zh":"醒來後，身體會出現荷爾蒙變化。"},{"en":"Hormonal changes are shifts in the body’s chemical messengers.","zh":"荷爾蒙變化是身體化學信使的變動。"},{"en":"These changes help prepare the body for activity.","zh":"這些變化幫助身體準備活動。"},{"en":"They may also affect the circulatory system.","zh":"它們也可能影響循環系統。"},{"en":"The phrase describes one biological factor after sleep.","zh":"這個詞組描述睡眠後的一項生物因素。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":6},{"front":"have an adverse effect on","meaning":"對……有不良影響","examples":[{"en":"Stress can have an adverse effect on the circulatory system.","zh":"壓力可以對循環系統有不良影響。"},{"en":"Have an adverse effect on means negatively affect or harm something.","zh":"對某物有不良影響，指負面影響或傷害它。"},{"en":"Sudden stress may have an adverse effect on heart function.","zh":"突然壓力可能對心臟功能有不良影響。"},{"en":"The phrase is common in medical writing.","zh":"這個詞組常見於醫學寫作。"},{"en":"It explains why Monday morning stress may matter.","zh":"它解釋為何星期一早上的壓力可能重要。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":6},{"front":"circulatory system","meaning":"循環系統","examples":[{"en":"The circulatory system may be affected by stress and hormonal changes.","zh":"循環系統可能受壓力和荷爾蒙變化影響。"},{"en":"The circulatory system includes the heart, blood and blood vessels.","zh":"循環系統包括心臟、血液和血管。"},{"en":"It carries oxygen and nutrients around the body.","zh":"它把氧氣和養分運送到全身。"},{"en":"A clot in the arteries can disrupt this system.","zh":"動脈中的血栓可以干擾這個系統。"},{"en":"The phrase identifies the body system involved in heart attacks.","zh":"這個詞組指出心臟病發作涉及的身體系統。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":6},{"front":"increase the risk of","meaning":"增加……的風險","examples":[{"en":"These changes can increase the risk of a clot in the arteries.","zh":"這些變化可以增加動脈中形成血栓的風險。"},{"en":"Increase the risk of means make something more likely to happen.","zh":"增加某事的風險，指令某事更有可能發生。"},{"en":"Stress may increase the risk of heart attack in vulnerable people.","zh":"壓力可能增加易受影響人士心臟病發作的風險。"},{"en":"The phrase is often used in health research.","zh":"這個詞組常用於健康研究。"},{"en":"It connects a cause with a greater chance of harm.","zh":"它把原因與更大傷害機會連接起來。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":6},{"front":"a clot in the arteries","meaning":"動脈中的血栓","examples":[{"en":"A clot in the arteries can cause a heart attack.","zh":"動脈中的血栓可以造成心臟病發作。"},{"en":"A clot is a mass of blood that can block normal flow.","zh":"血栓是一團可能阻塞正常血流的血液。"},{"en":"Artery clots can prevent blood from reaching the heart muscle.","zh":"動脈血栓可以阻止血液到達心肌。"},{"en":"Stress-related changes may increase the risk of such clots.","zh":"與壓力相關的變化可能增加這類血栓風險。"},{"en":"The phrase explains one physical pathway to a heart attack.","zh":"這個詞組解釋心臟病發作的一條身體途徑。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":6},{"front":"arteries","meaning":"動脈","examples":[{"en":"Blocked arteries can lead to a heart attack.","zh":"動脈阻塞可以導致心臟病發作。"},{"en":"Arteries are blood vessels that carry blood away from the heart.","zh":"動脈是把血液由心臟運走的血管。"},{"en":"Clots in the arteries can interrupt blood flow.","zh":"動脈中的血栓可以中斷血流。"},{"en":"The passage mentions arteries when discussing heart-attack triggers.","zh":"文章在討論心臟病發作觸發因素時提到動脈。"},{"en":"The phrase is part of the explanation of circulatory risk.","zh":"這個詞組是循環風險解釋的一部分。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":6},{"front":"return to work after","meaning":"在……後重返工作","examples":[{"en":"People return to work after a weekend off.","zh":"人們在一個不用上班的週末後重返工作。"},{"en":"Return to work after means go back to work following a period away.","zh":"在某事後重返工作，指離開工作一段時間後回去工作。"},{"en":"Returning to work after rest can involve a sudden change in routine.","zh":"休息後重返工作可能涉及日常規律的突然改變。"},{"en":"This shift may contribute to Monday stress.","zh":"這種轉變可能造成星期一壓力。"},{"en":"The phrase describes the start of the weekly work cycle.","zh":"這個詞組描述每週工作週期的開始。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":6},{"front":"a weekend off","meaning":"一個不用上班的週末","examples":[{"en":"A weekend off may be followed by a stressful Monday morning.","zh":"一個不用上班的週末之後可能是充滿壓力的星期一早上。"},{"en":"A weekend off means a weekend without work.","zh":"一個不用上班的週末，指沒有工作的週末。"},{"en":"After a weekend off, people may face a higher workload.","zh":"不用上班的週末後，人們可能面對更大工作量。"},{"en":"The phrase contrasts rest with the demands of work.","zh":"這個詞組把休息與工作要求作對比。"},{"en":"It is part of the explanation for Monday morning stress.","zh":"它是星期一早上壓力解釋的一部分。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":6},{"front":"the pace of life","meaning":"生活節奏","examples":[{"en":"The pace of life changes when people return to work.","zh":"當人們重返工作時，生活節奏會改變。"},{"en":"The pace of life means the speed and rhythm of daily activities.","zh":"生活節奏指日常活動的速度和規律。"},{"en":"The weekend pace may be slow, while Monday’s pace may be fast.","zh":"週末節奏可能較慢，而星期一節奏可能較快。"},{"en":"A sudden change in pace can create stress.","zh":"節奏突然改變可以造成壓力。"},{"en":"The phrase explains a lifestyle factor in Monday risk.","zh":"這個詞組解釋星期一風險中的生活方式因素。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":6},{"front":"higher workload","meaning":"更大的工作量","examples":[{"en":"People may face a higher workload on Monday.","zh":"人們在星期一可能面對更大的工作量。"},{"en":"Higher workload means more work or greater work demands.","zh":"更大的工作量指更多工作或更高工作要求。"},{"en":"A higher workload can increase stress after the weekend.","zh":"週末後更大的工作量可以增加壓力。"},{"en":"Monday may bring emails, meetings and unfinished tasks.","zh":"星期一可能帶來電郵、會議和未完成任務。"},{"en":"The phrase describes one possible source of work pressure.","zh":"這個詞組描述工作壓力的一個可能來源。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":6},{"front":"more physical activity","meaning":"更多體力活動","examples":[{"en":"Returning to work may involve more physical activity.","zh":"重返工作可能涉及更多體力活動。"},{"en":"More physical activity means greater movement or bodily effort.","zh":"更多體力活動指更多移動或身體用力。"},{"en":"Commuting, walking and job tasks may increase activity on Monday.","zh":"通勤、步行和工作任務可能增加星期一的活動量。"},{"en":"More activity after rest may affect heart rate and blood pressure.","zh":"休息後更多活動可能影響心率和血壓。"},{"en":"The phrase adds a bodily dimension to the work transition.","zh":"這個詞組為工作過渡加入身體層面。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":7},{"front":"cause changes in the body","meaning":"引起身體變化","examples":[{"en":"Researchers need to know how stress causes changes in the body.","zh":"研究人員需要知道壓力如何引起身體變化。"},{"en":"Cause changes in the body means produce physical effects inside the body.","zh":"引起身體變化，指在體內產生生理影響。"},{"en":"Stress may change hormones, blood pressure and heart rate.","zh":"壓力可能改變荷爾蒙、血壓和心率。"},{"en":"Understanding these changes may help explain heart-attack triggers.","zh":"理解這些變化可能幫助解釋心臟病發作觸發因素。"},{"en":"The phrase connects psychological stress with physical reactions.","zh":"這個詞組把心理壓力與身體反應連接起來。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":7},{"front":"before we can understand","meaning":"在我們能理解之前","examples":[{"en":"Doctors need more evidence before they can understand the causes.","zh":"醫生需要更多證據，在他們能理解成因之前。"},{"en":"Before we can understand means prior to reaching clear knowledge.","zh":"在我們能理解之前，指在獲得清楚知識之前。"},{"en":"Researchers must know how stress affects the body before they can explain the Monday peak.","zh":"研究人員必須知道壓力如何影響身體，才能解釋星期一高峰。"},{"en":"The phrase shows that current knowledge is incomplete.","zh":"這個詞組顯示目前知識仍不完整。"},{"en":"It introduces the need for further research.","zh":"它引出進一步研究的需要。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":7},{"front":"tempting to believe","meaning":"很容易令人相信","examples":[{"en":"It is tempting to believe that work stress explains the Monday risk.","zh":"很容易令人相信工作壓力解釋了星期一風險。"},{"en":"Tempting to believe means easy or attractive to accept as true.","zh":"很容易令人相信，指某說法容易或很吸引人接受為真。"},{"en":"The work-stress explanation seems reasonable at first.","zh":"工作壓力解釋初看似乎合理。"},{"en":"However, the passage says it is only a partial answer.","zh":"然而，文章說它只是部分答案。"},{"en":"The phrase introduces an explanation that must be qualified.","zh":"這個詞組引出需要修正的解釋。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":7},{"front":"increases the risk of","meaning":"增加……的風險","examples":[{"en":"Returning to work may increase the risk of a heart attack.","zh":"重返工作可能增加心臟病發作的風險。"},{"en":"Increases the risk of means makes something more likely to happen.","zh":"增加某事的風險，指令某事更可能發生。"},{"en":"Stress increases the risk of physical problems in vulnerable people.","zh":"壓力會增加易受影響人士出現身體問題的風險。"},{"en":"The phrase is often used in medical writing.","zh":"這個詞組常用於醫學寫作。"},{"en":"It connects a possible cause with a greater chance of illness.","zh":"它把可能原因與更大疾病機會連接起來。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":7},{"front":"admit that","meaning":"承認","examples":[{"en":"The researchers admit that work stress is only a partial answer.","zh":"研究人員承認工作壓力只是部分答案。"},{"en":"Admit that means acknowledge something as true, often despite it limiting one’s argument.","zh":"承認某事，指承認某事為真，通常即使它限制了自己的論點。"},{"en":"The researchers admit that not all Monday risk can be explained by employment.","zh":"研究人員承認並非所有星期一風險都可由就業解釋。"},{"en":"The phrase shows scientific caution.","zh":"這個詞組顯示科學上的謹慎。"},{"en":"It prepares readers for evidence involving older people.","zh":"它讓讀者準備理解涉及長者的證據。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":7},{"front":"a partial answer","meaning":"部分答案","examples":[{"en":"Returning to work is only a partial answer.","zh":"重返工作只是部分答案。"},{"en":"A partial answer explains some, but not all, of a problem.","zh":"部分答案只能解釋問題的一部分，而不是全部。"},{"en":"Work stress may explain workers’ risk but not the over-65s’ risk.","zh":"工作壓力可能解釋在職人士風險，但不能解釋六十五歲以上人士的風險。"},{"en":"The phrase shows that the cause is more complex.","zh":"這個詞組顯示成因更複雜。"},{"en":"It invites further investigation.","zh":"它引出進一步調查。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":7},{"front":"the over-65s","meaning":"六十五歲以上人士","examples":[{"en":"The over-65s are also vulnerable on Monday mornings.","zh":"六十五歲以上人士在星期一早上也容易受影響。"},{"en":"The over-65s means people older than 65 years of age.","zh":"六十五歲以上人士指年齡超過65歲的人。"},{"en":"Many over-65s no longer work, so work stress cannot fully explain their risk.","zh":"很多六十五歲以上人士不再工作，因此工作壓力不能完全解釋他們的風險。"},{"en":"The phrase identifies an older age group.","zh":"這個詞組指出一個較年長年齡群體。"},{"en":"It complicates the explanation of the Monday effect.","zh":"它令星期一效應的解釋更複雜。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":7},{"front":"are also vulnerable","meaning":"也容易受影響","examples":[{"en":"Older people are also vulnerable on Monday mornings.","zh":"長者在星期一早上也容易受影響。"},{"en":"Are also vulnerable means are also likely to be affected or harmed.","zh":"也容易受影響，指也可能受到影響或傷害。"},{"en":"The phrase shows that risk is not limited to workers.","zh":"這個詞組顯示風險不限於在職人士。"},{"en":"It suggests other factors may be involved.","zh":"它表示可能涉及其他因素。"},{"en":"It broadens the discussion beyond employment.","zh":"它把討論擴展到就業以外。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":7},{"front":"even though","meaning":"即使","examples":[{"en":"The over-65s are vulnerable even though most no longer work.","zh":"六十五歲以上人士即使大多不再工作，也容易受影響。"},{"en":"Even though means despite the fact that.","zh":"即使，指儘管某事實存在。"},{"en":"The phrase introduces a surprising contrast.","zh":"這個詞組引出令人意外的對比。"},{"en":"Older people face Monday risk even though work stress may not apply to them.","zh":"長者即使未必有工作壓力，也面對星期一風險。"},{"en":"It helps show why the cause remains unclear.","zh":"它幫助顯示為何成因仍不清楚。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":7},{"front":"no longer work","meaning":"不再工作","examples":[{"en":"Many people over 65 no longer work.","zh":"很多六十五歲以上人士不再工作。"},{"en":"No longer work means do not work anymore.","zh":"不再工作，指已經沒有工作。"},{"en":"If people no longer work, Monday job stress cannot fully explain their risk.","zh":"如果人們不再工作，星期一工作壓力便不能完全解釋他們的風險。"},{"en":"The phrase is important in challenging the simple work-stress theory.","zh":"這個詞組對挑戰簡單工作壓力理論很重要。"},{"en":"It refers to retirement or leaving employment.","zh":"它指退休或離開就業狀態。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":7},{"front":"the reason for this is not clear","meaning":"這種情況的原因尚不清楚","examples":[{"en":"The reason for this Monday effect is not clear.","zh":"這種星期一效應的原因尚不清楚。"},{"en":"The phrase means researchers do not yet know the cause.","zh":"這個詞組表示研究人員尚未知道原因。"},{"en":"Older people’s Monday vulnerability remains difficult to explain.","zh":"長者在星期一也容易受影響仍難以解釋。"},{"en":"It shows that current theories are incomplete.","zh":"它顯示目前理論並不完整。"},{"en":"The phrase introduces speculation about social interactions and weekly pressures.","zh":"這個詞組引出關於社交互動和一週壓力的推測。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":8},{"front":"speculate that","meaning":"推測","examples":[{"en":"The Italian team speculate that social interactions may play a part.","zh":"意大利團隊推測社交互動可能起作用。"},{"en":"Speculate that means suggest a possible explanation without full proof.","zh":"推測，指在沒有完整證明下提出可能解釋。"},{"en":"Researchers speculate that the thought of another week may create stress.","zh":"研究人員推測想到新一星期可能造成壓力。"},{"en":"The phrase signals uncertainty.","zh":"這個詞組表示不確定性。"},{"en":"It is used when evidence is not yet strong enough for a firm conclusion.","zh":"它用於證據尚不足以作出確定結論時。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":8},{"front":"social interactions","meaning":"社交互動","examples":[{"en":"Social interactions may contribute to Monday-morning stress.","zh":"社交互動可能造成星期一早上的壓力。"},{"en":"Social interactions are contacts or exchanges between people.","zh":"社交互動是人與人之間的接觸或交流。"},{"en":"Meetings, conversations and family responsibilities may all be social interactions.","zh":"會議、談話和家庭責任都可以是社交互動。"},{"en":"The Italian team suggested they may affect Monday risk.","zh":"意大利團隊提出它們可能影響星期一風險。"},{"en":"The phrase introduces a non-work explanation for stress.","zh":"這個詞組引出非工作層面的壓力解釋。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":8},{"front":"the thought of facing","meaning":"想到要面對……","examples":[{"en":"The thought of facing another week may create stress.","zh":"想到要面對新一星期可能造成壓力。"},{"en":"The thought of facing something means imagining or anticipating having to deal with it.","zh":"想到要面對某事，指想像或預期必須處理它。"},{"en":"Thinking about duties ahead may affect mood and body.","zh":"想到前方責任可能影響情緒和身體。"},{"en":"The phrase describes mental stress before events happen.","zh":"這個詞組描述事情發生前的心理壓力。"},{"en":"It may help explain risk among people who no longer work.","zh":"它可能幫助解釋不再工作人士的風險。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":8},{"front":"another week","meaning":"新一星期","examples":[{"en":"Some people feel stress at the thought of facing another week.","zh":"有些人想到要面對新一星期便感到壓力。"},{"en":"Another week means the new week about to begin.","zh":"新一星期，指即將開始的一週。"},{"en":"Monday can make people think about another week of duties and pressures.","zh":"星期一可能令人想到新一星期的責任和壓力。"},{"en":"The phrase is broader than work alone.","zh":"這個詞組比工作本身更廣泛。"},{"en":"It may include social, family and personal responsibilities.","zh":"它可能包括社交、家庭和個人責任。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":8},{"front":"all its pressures","meaning":"它所有的壓力","examples":[{"en":"The thought of another week and all its pressures may affect the heart.","zh":"想到新一星期及其所有壓力可能影響心臟。"},{"en":"All its pressures means all the stresses and demands connected with the week.","zh":"它所有的壓力，指與該週相關的所有壓力和要求。"},{"en":"These pressures may be work-related, social or personal.","zh":"這些壓力可能與工作、社交或個人生活有關。"},{"en":"The phrase emphasises the total burden people anticipate.","zh":"這個詞組強調人們預期的整體負擔。"},{"en":"It helps explain Monday-morning anxiety.","zh":"它有助解釋星期一早上的焦慮。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":8},{"front":"may play a part","meaning":"可能有影響；可能起作用","examples":[{"en":"Social interactions may play a part in the Monday heart-attack peak.","zh":"社交互動可能在星期一心臟病發作高峰中起作用。"},{"en":"May play a part means may contribute to the result.","zh":"可能起作用，指可能促成結果。"},{"en":"The phrase suggests one factor among several.","zh":"這個詞組表示它是多個因素之一。"},{"en":"It does not claim that social interactions are the only cause.","zh":"它沒有聲稱社交互動是唯一原因。"},{"en":"It reflects the researchers’ cautious explanation.","zh":"它反映研究人員謹慎的解釋。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":8},{"front":"what is clear","meaning":"清楚的是","examples":[{"en":"What is clear is that the Monday morning peak appears consistent.","zh":"清楚的是，星期一早上的高峰似乎一致。"},{"en":"What is clear introduces a point that seems certain despite other uncertainties.","zh":"清楚的是，用來引出即使仍有不確定也似乎確定的重點。"},{"en":"The cause may be unclear, but the timing pattern is clear.","zh":"成因可能不清楚，但時間模式很清楚。"},{"en":"The phrase helps separate evidence from speculation.","zh":"這個詞組幫助區分證據與推測。"},{"en":"It leads into the comparison across regions.","zh":"它引出跨地區比較。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":8},{"front":"the Monday morning peak","meaning":"星期一早上的高峰","examples":[{"en":"The Monday morning peak appears in both German and Italian data.","zh":"星期一早上的高峰出現在德國和意大利數據中。"},{"en":"The Monday morning peak means the highest number or risk of attacks on Monday morning.","zh":"星期一早上的高峰，指星期一早上發作數量或風險最高。"},{"en":"This peak suggests that timing matters in heart attacks.","zh":"這個高峰表示時間對心臟病發作很重要。"},{"en":"It appears despite differences in diet and lifestyle.","zh":"它在飲食和生活方式差異下仍出現。"},{"en":"The phrase names the central pattern found by the studies.","zh":"這個詞組命名研究發現的核心模式。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":8},{"front":"seems to be consistent","meaning":"似乎一致","examples":[{"en":"The Monday morning peak seems to be consistent across regions.","zh":"星期一早上的高峰似乎在不同地區一致。"},{"en":"Seems to be consistent means appears to follow the same pattern.","zh":"似乎一致，指看來遵循相同模式。"},{"en":"The pattern was found from northern Germany to southern Italy.","zh":"該模式由德國北部到意大利南部都被發現。"},{"en":"The phrase suggests reliability without claiming absolute certainty.","zh":"這個詞組表示可靠性，但不聲稱絕對確定。"},{"en":"It supports the importance of the finding.","zh":"它支持該發現的重要性。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":8},{"front":"northern Germany","meaning":"德國北部","examples":[{"en":"The pattern was observed from northern Germany to southern Italy.","zh":"該模式由德國北部到意大利南部都有觀察到。"},{"en":"Northern Germany refers to the northern part of Germany.","zh":"德國北部指德國的北方部分。"},{"en":"The phrase helps show the geographical spread of the finding.","zh":"這個詞組幫助顯示該發現的地理分布。"},{"en":"The Monday peak was not limited to one small area.","zh":"星期一高峰並不限於一個小地區。"},{"en":"It contributes to the argument that the pattern is consistent.","zh":"它有助支持該模式一致的論點。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":8},{"front":"southern Italy","meaning":"意大利南部","examples":[{"en":"The pattern was observed in southern Italy as well as northern Germany.","zh":"該模式在意大利南部以及德國北部都有觀察到。"},{"en":"Southern Italy refers to the southern part of Italy.","zh":"意大利南部指意大利的南方部分。"},{"en":"Finding the pattern there suggests it crosses regional differences.","zh":"在那裡發現該模式表示它跨越地區差異。"},{"en":"The phrase completes the geographical comparison.","zh":"這個詞組完成地理比較。"},{"en":"It strengthens the claim that the Monday effect is widespread.","zh":"它加強星期一效應廣泛存在的說法。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":9},{"front":"in spite of","meaning":"儘管","examples":[{"en":"The pattern remains in spite of differences in diet and lifestyle.","zh":"儘管飲食和生活方式有差異，該模式仍然存在。"},{"en":"In spite of means despite.","zh":"儘管，指雖然某事存在。"},{"en":"The Monday peak appeared in spite of regional differences.","zh":"星期一高峰在地區差異下仍出現。"},{"en":"The phrase introduces a contrast between expected variation and actual consistency.","zh":"這個詞組引出預期差異與實際一致之間的對比。"},{"en":"It strengthens the argument that the pattern is robust.","zh":"它加強該模式穩健的論點。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":9},{"front":"differences in diet and lifestyle","meaning":"飲食和生活方式的差異","examples":[{"en":"The results appeared despite differences in diet and lifestyle.","zh":"儘管飲食和生活方式有差異，研究結果仍然出現。"},{"en":"Differences in diet and lifestyle are variations in eating habits and daily routines.","zh":"飲食和生活方式的差異，是飲食習慣和日常規律上的不同。"},{"en":"Germany and Italy may differ in food, work habits and social customs.","zh":"德國和意大利在食物、工作習慣和社交習俗上可能不同。"},{"en":"The same Monday pattern appeared despite these differences.","zh":"儘管有這些差異，相同星期一模式仍出現。"},{"en":"The phrase helps rule out simple cultural or dietary explanations.","zh":"這個詞組有助排除簡單文化或飲食解釋。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":9},{"front":"reluctant at this stage to","meaning":"現階段不願意……","examples":[{"en":"Willich is reluctant at this stage to make specific recommendations.","zh":"Willich 現階段不願意提出具體建議。"},{"en":"Reluctant at this stage to means unwilling for now because more evidence is needed.","zh":"現階段不願意，指目前因需要更多證據而不願這樣做。"},{"en":"The phrase shows caution before giving medical advice.","zh":"這個詞組顯示在提供醫療建議前的謹慎。"},{"en":"Researchers do not want to overstate the findings.","zh":"研究人員不想誇大研究結果。"},{"en":"It introduces limited practical guidance.","zh":"它引出有限的實際指引。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":9},{"front":"make specific recommendations","meaning":"提出具體建議","examples":[{"en":"Willich is reluctant to make specific recommendations yet.","zh":"Willich 尚不願提出具體建議。"},{"en":"To make specific recommendations means to give detailed advice about what people should do.","zh":"提出具體建議，指給出關於人們應怎樣做的詳細建議。"},{"en":"Doctors need stronger evidence before making precise prevention advice.","zh":"醫生需要更強證據，才會提出精確預防建議。"},{"en":"The phrase appears near the practical conclusion of the passage.","zh":"這個詞組出現在文章接近實際結論的位置。"},{"en":"It contrasts with more general suggestions such as avoiding stress.","zh":"它與避免壓力等較一般建議形成對比。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":9},{"front":"suffers from heart disease","meaning":"患有心臟病","examples":[{"en":"Anyone who suffers from heart disease should be careful on Monday mornings.","zh":"任何患有心臟病的人都應在星期一早上小心。"},{"en":"Suffers from heart disease means has a heart-related medical condition.","zh":"患有心臟病，指有與心臟相關的醫療狀況。"},{"en":"Such people may be more vulnerable to stress and physical strain.","zh":"這些人可能更容易受壓力和身體負荷影響。"},{"en":"The phrase identifies the group that should be especially cautious.","zh":"這個詞組指出應特別謹慎的群體。"},{"en":"It introduces practical advice for high-risk individuals.","zh":"它引出給高風險人士的實際建議。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":9},{"front":"take it easy","meaning":"放鬆一點；不要太操勞","examples":[{"en":"People with heart disease should take it easy on Monday mornings.","zh":"患有心臟病的人應在星期一早上放鬆一點。"},{"en":"Take it easy means relax, slow down and avoid too much pressure.","zh":"放鬆一點，指減慢節奏並避免太大壓力。"},{"en":"A patient might take it easy by avoiding stressful meetings.","zh":"病人可以透過避免有壓力的會議來不要太操勞。"},{"en":"The phrase is informal but practical.","zh":"這個詞組較口語但實用。"},{"en":"It suggests reducing strain during a high-risk time.","zh":"它建議在高風險時間減少負荷。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":9},{"front":"potentially stressful meetings","meaning":"可能造成壓力的會議","examples":[{"en":"Patients may want to avoid potentially stressful meetings on Monday mornings.","zh":"病人可能想避免星期一早上可能造成壓力的會議。"},{"en":"Potentially stressful meetings are meetings that may cause pressure or anxiety.","zh":"可能造成壓力的會議，是可能引起壓力或焦慮的會議。"},{"en":"Moving them to midweek may reduce Monday morning strain.","zh":"把它們移到一週中段可能減少星期一早上的負荷。"},{"en":"The phrase gives a practical example of avoiding stress.","zh":"這個詞組提供避免壓力的實際例子。"},{"en":"It applies especially to people with heart disease.","zh":"它尤其適用於患有心臟病的人。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":9},{"front":"until midweek","meaning":"直到一週中段","examples":[{"en":"Stressful meetings could be left until midweek.","zh":"有壓力的會議可以留到一週中段。"},{"en":"Until midweek means until the middle part of the week.","zh":"直到一週中段，指直到星期中的中間部分。"},{"en":"Waiting until midweek may avoid the Monday morning peak.","zh":"等到一週中段可能避開星期一早上的高峰。"},{"en":"The phrase suggests rescheduling stressful events.","zh":"這個詞組建議重新安排有壓力的事件。"},{"en":"It is part of the passage’s practical advice.","zh":"它是文章實際建議的一部分。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":9},{"front":"create a pleasant working environment","meaning":"創造愉快的工作環境","examples":[{"en":"People should try to create a pleasant working environment.","zh":"人們應嘗試創造愉快的工作環境。"},{"en":"To create a pleasant working environment means to make the workplace more comfortable and less stressful.","zh":"創造愉快的工作環境，指令工作場所更舒適、壓力更少。"},{"en":"A pleasant workplace may reduce the feeling of Monday pressure.","zh":"愉快的工作場所可能減少星期一壓力感。"},{"en":"Supportive colleagues and manageable tasks can help.","zh":"支持性的同事和可管理的任務都可以幫助。"},{"en":"The phrase gives a general strategy for reducing stress.","zh":"這個詞組提供減壓的一般策略。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":9},{"front":"this risk applies only to","meaning":"這種風險只適用於……","examples":[{"en":"This risk may apply only to people who see work as a burden.","zh":"這種風險可能只適用於把工作視為負擔的人。"},{"en":"Applies only to means is relevant only for a particular group.","zh":"只適用於，指只與某特定群體相關。"},{"en":"The passage suggests people who enjoy work may be less at risk.","zh":"文章指出享受工作的人風險可能較低。"},{"en":"The phrase limits the scope of the warning.","zh":"這個詞組限制警告的適用範圍。"},{"en":"It connects personal attitude with health risk.","zh":"它把個人態度與健康風險連接起來。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":9},{"front":"see work as a burden","meaning":"把工作視為負擔","examples":[{"en":"Some people see work as a burden rather than a pleasure.","zh":"有些人把工作視為負擔，而不是樂趣。"},{"en":"To see work as a burden means to view one’s job as heavy, unpleasant or stressful.","zh":"把工作視為負擔，指把自己的工作看成沉重、不愉快或有壓力。"},{"en":"People with this attitude may feel more Monday morning stress.","zh":"有這種態度的人可能感到更多星期一早上壓力。"},{"en":"Enjoying work may reduce the sense of pressure.","zh":"享受工作可能減少壓力感。"},{"en":"The phrase explains why attitude toward work may matter.","zh":"這個詞組解釋為何對工作的態度可能重要。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":10},{"front":"not so much at risk","meaning":"風險沒那麼高","examples":[{"en":"People who enjoy their work may not be so much at risk.","zh":"享受工作的人風險可能沒那麼高。"},{"en":"Not so much at risk means less likely to be affected or harmed.","zh":"風險沒那麼高，指較不可能受影響或受傷害。"},{"en":"A positive attitude toward work may reduce Monday stress.","zh":"對工作持正面態度可能減少星期一壓力。"},{"en":"The phrase suggests that risk is not the same for everyone.","zh":"這個詞組表示風險並非人人相同。"},{"en":"It gives a hopeful contrast to the warning.","zh":"它為警告提供較樂觀的對比。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":10},{"front":"find out more","meaning":"了解更多","examples":[{"en":"Researchers need to find out more about Monday heart attacks.","zh":"研究人員需要了解更多關於星期一心臟病發作的事情。"},{"en":"Find out more means learn additional information.","zh":"了解更多，指獲得額外資料。"},{"en":"Scientists need to find out more before giving specific recommendations.","zh":"科學家在提出具體建議前需要了解更多。"},{"en":"The phrase shows that further research is necessary.","zh":"這個詞組顯示需要進一步研究。"},{"en":"It ends the discussion with caution and curiosity.","zh":"它以謹慎和求知態度結束討論。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":10},{"front":"do the following statements agree with","meaning":"以下陳述是否與……一致","examples":[{"en":"Students decide whether the following statements agree with the information.","zh":"學生判斷以下陳述是否與資料一致。"},{"en":"The phrase asks students to compare statements with the passage.","zh":"這個詞組要求學生把陳述與文章比較。"},{"en":"If a statement matches the text, the answer is TRUE.","zh":"如果陳述與文本相符，答案是 TRUE。"},{"en":"If it contradicts the text, the answer is FALSE.","zh":"如果陳述與文本矛盾，答案是 FALSE。"},{"en":"If the text gives no information, the answer is NOT GIVEN.","zh":"如果文本沒有資料，答案是 NOT GIVEN。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":10},{"front":"information given in","meaning":"……中提供的資料","examples":[{"en":"The answers must match the information given in the passage.","zh":"答案必須符合文章中提供的資料。"},{"en":"Information given in means facts or details stated in the text.","zh":"……中提供的資料，指文本中陳述的事實或細節。"},{"en":"Students should not use outside knowledge to decide the answer.","zh":"學生不應使用外部知識來決定答案。"},{"en":"The phrase reminds readers to rely only on the passage.","zh":"這個詞組提醒讀者只依賴文章。"},{"en":"It is important in TRUE/FALSE/NOT GIVEN tasks.","zh":"它對 TRUE/FALSE/NOT GIVEN 題型很重要。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":10},{"front":"write TRUE if","meaning":"如果……則寫 TRUE","examples":[{"en":"Students write TRUE if the statement agrees with the information.","zh":"如果陳述與資料一致，學生則寫 TRUE。"},{"en":"Write TRUE if means mark the answer as true under a stated condition.","zh":"如果……則寫 TRUE，指在指定條件成立時標示答案為真。"},{"en":"The condition is that the statement matches the passage.","zh":"條件是陳述與文章相符。"},{"en":"Students must check full meaning, not just similar words.","zh":"學生必須檢查完整意思，而不只是相似字眼。"},{"en":"The phrase gives a test instruction.","zh":"這個詞組提供測驗指示。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":10},{"front":"write FALSE if","meaning":"如果……則寫 FALSE","examples":[{"en":"Students write FALSE if the statement contradicts the information.","zh":"如果陳述與資料矛盾，學生則寫 FALSE。"},{"en":"Write FALSE if means mark the answer as false when the stated condition is met.","zh":"如果……則寫 FALSE，指在指定條件成立時標示答案為假。"},{"en":"The condition is a clear conflict with the passage.","zh":"條件是與文章有清楚衝突。"},{"en":"A statement is not false simply because it uses different words.","zh":"陳述不會只因用字不同便是假。"},{"en":"The phrase explains one answer category.","zh":"這個詞組解釋其中一種答案類別。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":10},{"front":"write NOT GIVEN if","meaning":"如果……則寫 NOT GIVEN","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有這方面的資料，學生則寫 NOT GIVEN。"},{"en":"Write NOT GIVEN if means mark the answer this way when the passage does not say.","zh":"如果……則寫 NOT GIVEN，指文章沒有說明時如此標示答案。"},{"en":"The passage must neither support nor contradict the statement.","zh":"文章必須既不支持也不反駁該陳述。"},{"en":"Students should avoid guessing.","zh":"學生應避免猜測。"},{"en":"The phrase gives the third answer category.","zh":"這個詞組提供第三種答案類別。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":10},{"front":"the statement agrees with","meaning":"陳述與……一致","examples":[{"en":"A TRUE statement agrees with the information in the text.","zh":"TRUE 陳述與文本中的資料一致。"},{"en":"The statement agrees with means its meaning matches what is written.","zh":"陳述與某資料一致，指其意思與所寫內容相符。"},{"en":"Agreement requires support from the passage.","zh":"一致需要文章支持。"},{"en":"A statement may agree even if the wording is paraphrased.","zh":"即使用字經過改寫，陳述仍可能一致。"},{"en":"The phrase is used to define TRUE answers.","zh":"這個詞組用來定義 TRUE 答案。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":10},{"front":"contradicts the information","meaning":"與資料相矛盾","examples":[{"en":"A FALSE statement contradicts the information in the text.","zh":"FALSE 陳述與文本中的資料相矛盾。"},{"en":"Contradicts the information means says something opposite to the passage.","zh":"與資料相矛盾，指說出與文章相反的內容。"},{"en":"Clear contradiction is needed for a FALSE answer.","zh":"FALSE 答案需要清楚矛盾。"},{"en":"Missing information should be marked NOT GIVEN instead.","zh":"缺少資料應標為 NOT GIVEN。"},{"en":"The phrase is central to reading-test logic.","zh":"這個詞組是閱讀測驗邏輯的核心。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":10},{"front":"no information on this","meaning":"沒有這方面的資料","examples":[{"en":"NOT GIVEN means that the passage gives no information on this.","zh":"NOT GIVEN 表示文章沒有這方面的資料。"},{"en":"No information on this means the text does not address the point.","zh":"沒有這方面的資料，指文本沒有處理該點。"},{"en":"Students must not infer beyond the passage.","zh":"學生不可超出文章作推論。"},{"en":"The phrase prevents unsupported conclusions.","zh":"這個詞組防止沒有根據的結論。"},{"en":"It is especially important when a statement sounds plausible but is not stated.","zh":"當陳述聽起來合理但文章沒有提及時，它尤其重要。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":10},{"front":"unemployed Germans","meaning":"失業德國人","examples":[{"en":"The question compares unemployed Germans with employed Germans.","zh":"題目比較失業德國人與受僱德國人。"},{"en":"Unemployed Germans are German people who do not have jobs.","zh":"失業德國人是沒有工作的德國人。"},{"en":"In the passage, non-workers are compared with workers.","zh":"在文章中，非在職人士與在職人士被比較。"},{"en":"The German study suggests workers had greater Monday vulnerability.","zh":"德國研究指出在職人士在星期一較容易受影響。"},{"en":"The phrase appears in a question testing careful comparison.","zh":"這個詞組出現在測試仔細比較的題目中。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":11},{"front":"employed Germans","meaning":"受僱德國人；在職德國人","examples":[{"en":"Employed Germans are described as more vulnerable at the start of the week.","zh":"受僱德國人被描述為在一週開始時較容易受影響。"},{"en":"Employed Germans are German people who have jobs.","zh":"受僱德國人是有工作的德國人。"},{"en":"They correspond to the working Germans in the passage.","zh":"他們對應文章中的在職德國人。"},{"en":"The study found a higher Monday risk among workers.","zh":"研究發現在職人士星期一風險較高。"},{"en":"The phrase helps distinguish workers from non-workers.","zh":"這個詞組有助區分工作人士與非工作人士。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":11},{"front":"a higher risk of heart attack","meaning":"較高心臟病發風險","examples":[{"en":"The statement asks whether unemployed Germans have a higher risk of heart attack.","zh":"陳述詢問失業德國人是否有較高心臟病發風險。"},{"en":"A higher risk of heart attack means a greater chance of suffering one.","zh":"較高心臟病發風險，指發生心臟病發作的機會更大。"},{"en":"The passage links higher Monday risk especially with working Germans.","zh":"文章把星期一較高風險尤其與在職德國人連繫起來。"},{"en":"Non-workers were not more at risk on Mondays.","zh":"非在職人士在星期一風險並沒有更高。"},{"en":"The phrase describes the comparison being tested.","zh":"這個詞組描述正在測試的比較。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":11},{"front":"unemployed Italians","meaning":"失業意大利人","examples":[{"en":"The question mentions unemployed Italians.","zh":"題目提到失業意大利人。"},{"en":"Unemployed Italians are Italian people who do not have jobs.","zh":"失業意大利人是沒有工作的意大利人。"},{"en":"The passage discusses Italian data but does not focus on unemployed Italians specifically.","zh":"文章討論意大利數據，但沒有特別集中於失業意大利人。"},{"en":"This phrase may appear in a NOT GIVEN-style statement.","zh":"這個詞組可能出現在 NOT GIVEN 類陳述中。"},{"en":"It tests whether students separate stated facts from assumptions.","zh":"它測試學生能否區分文章事實與假設。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":11},{"front":"a lower risk of","meaning":"較低……風險","examples":[{"en":"The option asks whether one group has a lower risk of heart attack.","zh":"選項詢問某一群體是否有較低心臟病發作風險。"},{"en":"A lower risk of something means a smaller chance of it happening.","zh":"較低某事風險，指某事發生的機會較小。"},{"en":"Sunday appears to have a lower risk of heart attacks than Monday.","zh":"星期日的心臟病發作風險似乎比星期一較低。"},{"en":"Non-workers were no more at risk on Mondays, but the passage is careful with comparisons.","zh":"非在職人士在星期一風險並沒有更高，但文章對比較十分謹慎。"},{"en":"The phrase is used in risk comparisons.","zh":"這個詞組用於風險比較。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":11},{"front":"consume large amounts of","meaning":"大量攝取","examples":[{"en":"The statement asks whether Germans consume large amounts of fatty food.","zh":"陳述詢問德國人是否大量攝取高脂食物。"},{"en":"Consume large amounts of means eat, drink or use a lot of something.","zh":"大量攝取，指吃、喝或使用很多某物。"},{"en":"The passage mentions diet differences but does not say Germans consume large amounts of fatty food.","zh":"文章提到飲食差異，但沒有說德國人大量攝取高脂食物。"},{"en":"The phrase may test whether information is actually stated.","zh":"這個詞組可能測試資料是否真正被提及。"},{"en":"It is often used in health and nutrition contexts.","zh":"它常用於健康和營養語境。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":11},{"front":"fatty food","meaning":"高脂食物","examples":[{"en":"The question mentions fatty food as a possible risk factor.","zh":"題目提到高脂食物作為可能風險因素。"},{"en":"Fatty food is food containing a high amount of fat.","zh":"高脂食物是含有大量脂肪的食物。"},{"en":"Diet can be a long-term health factor, but the passage focuses on Monday timing.","zh":"飲食可以是長期健康因素，但文章集中於星期一時間模式。"},{"en":"The passage does not make fatty food the main explanation.","zh":"文章沒有把高脂食物作為主要解釋。"},{"en":"The phrase appears in a test statement rather than the central argument.","zh":"這個詞組出現在測驗陳述中，而不是核心論點。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":11},{"front":"trigger heart attacks","meaning":"觸發心臟病發作","examples":[{"en":"Smoking and cholesterol are risk factors, but researchers ask what triggers heart attacks.","zh":"吸煙和膽固醇是風險因素，但研究人員追問甚麼會觸發心臟病發作。"},{"en":"To trigger heart attacks means to set them off or cause them to happen suddenly.","zh":"觸發心臟病發作，指引發它們或令它們突然發生。"},{"en":"Monday stress may be one possible trigger.","zh":"星期一壓力可能是一種可能觸發因素。"},{"en":"The phrase focuses on immediate causes rather than long-term risks.","zh":"這個詞組集中於即時原因，而不是長期風險。"},{"en":"It captures the main medical uncertainty in the passage.","zh":"它概括文章中的主要醫學不確定性。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":11},{"front":"choose the best heading","meaning":"選出最佳標題","examples":[{"en":"Students choose the best heading for each paragraph.","zh":"學生為每一段選出最佳標題。"},{"en":"Choose the best heading means select the title that best summarises a paragraph.","zh":"選出最佳標題，指選擇最能概括段落的題目。"},{"en":"The heading should match the main idea, not just one detail.","zh":"標題應符合主旨，而不只是某一細節。"},{"en":"Students must compare all headings carefully.","zh":"學生必須仔細比較所有標題。"},{"en":"The phrase is a common reading-test instruction.","zh":"這個詞組是常見閱讀測驗指示。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":11},{"front":"for each paragraph","meaning":"為每一段","examples":[{"en":"The task requires one heading for each paragraph.","zh":"該任務要求為每一段選一個標題。"},{"en":"For each paragraph means separately for every paragraph in the passage.","zh":"為每一段，指分別為文章中每個段落。"},{"en":"Students should identify the main idea of each paragraph.","zh":"學生應找出每段的主旨。"},{"en":"The phrase prevents students from using one answer for the whole text.","zh":"這個詞組防止學生用一個答案處理整篇文章。"},{"en":"It is part of heading-matching instructions.","zh":"它是標題配對指示的一部分。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":11},{"front":"from the list below","meaning":"從以下列表中","examples":[{"en":"The heading must be chosen from the list below.","zh":"標題必須從以下列表中選出。"},{"en":"From the list below means from the options printed underneath the instruction.","zh":"從以下列表中，指從指示下方列出的選項中。"},{"en":"Students should not invent their own headings.","zh":"學生不應自行創作標題。"},{"en":"The phrase limits the answer choices.","zh":"這個詞組限制答案選擇。"},{"en":"It helps structure a multiple-choice-style reading task.","zh":"它有助組織類似選擇題的閱讀任務。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":11},{"front":"write the appropriate number","meaning":"寫下適當編號","examples":[{"en":"Students write the appropriate number in the answer boxes.","zh":"學生在答案格中寫下適當編號。"},{"en":"The appropriate number is the number matching the correct heading.","zh":"適當編號是與正確標題相配的數字。"},{"en":"Students should write numbers, not the full heading text.","zh":"學生應寫數字，而不是完整標題文字。"},{"en":"The phrase gives the required answer format.","zh":"這個詞組提供所需答案格式。"},{"en":"It is common in IELTS-style heading tasks.","zh":"它常見於 IELTS 式標題題。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":12},{"front":"the exact cause of","meaning":"……的確切成因","examples":[{"en":"The heading refers to the exact cause of heart attacks.","zh":"該標題指心臟病發作的確切成因。"},{"en":"The exact cause of something means the precise reason it happens.","zh":"某事的確切成因，指它發生的精確原因。"},{"en":"The passage says doctors do not yet know what exactly triggers heart attacks.","zh":"文章說醫生尚未知道究竟是甚麼觸發心臟病發作。"},{"en":"The phrase fits a paragraph about medical uncertainty.","zh":"這個詞組適合關於醫學不確定性的段落。"},{"en":"It contrasts known risk factors with unknown triggers.","zh":"它把已知風險因素與未知觸發因素作對比。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":12},{"front":"the safest day","meaning":"最安全的一天","examples":[{"en":"Sunday is described as the safest day for the heart.","zh":"星期日被描述為對心臟最安全的一天。"},{"en":"The safest day means the day with the lowest risk.","zh":"最安全的一天，指風險最低的日子。"},{"en":"Both studies found fewer heart attacks on Sundays.","zh":"兩項研究都發現星期日心臟病發作較少。"},{"en":"The phrase contrasts with high-risk Monday.","zh":"這個詞組與高風險星期一形成對比。"},{"en":"It is suitable for a heading about Sunday’s low stress level.","zh":"它適合作為關於星期日低壓力水平的標題。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":12},{"front":"breathless, sweaty and crushed","meaning":"喘不過氣、冒汗、胸口受壓","examples":[{"en":"The heading describes someone who is breathless, sweaty and crushed by chest pain.","zh":"該標題描述一個喘不過氣、冒汗並因胸痛感到受壓的人。"},{"en":"Breathless means unable to breathe easily, and sweaty means covered with sweat.","zh":"喘不過氣指呼吸困難，冒汗指身上出汗。"},{"en":"Crushed refers to the crushing pain in the chest.","zh":"胸口受壓指胸口壓迫般劇痛。"},{"en":"The phrase summarises the dramatic symptoms of a heart attack.","zh":"這個詞組概括心臟病發作的戲劇性症狀。"},{"en":"It is suitable for an introductory paragraph about symptoms.","zh":"它適合作為關於症狀的引言段標題。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":12},{"front":"reducing the risk of","meaning":"減低……風險","examples":[{"en":"The final paragraph discusses reducing the risk of heart attack.","zh":"最後一段討論減低心臟病發作風險。"},{"en":"Reducing the risk of something means making it less likely to happen.","zh":"減低某事風險，指令它較不可能發生。"},{"en":"Taking it easy and avoiding stressful meetings may reduce risk.","zh":"放鬆一點和避免有壓力的會議可能減低風險。"},{"en":"The phrase fits advice for people with heart disease.","zh":"這個詞組適合給心臟病患者的建議。"},{"en":"It focuses on prevention rather than explanation.","zh":"它集中於預防，而不是解釋。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":12},{"front":"high-risk Monday","meaning":"高風險星期一","examples":[{"en":"The study presents Monday as a high-risk day for heart attacks.","zh":"研究把星期一呈現為心臟病發作的高風險日。"},{"en":"High-risk Monday means Monday is associated with a higher chance of heart attacks.","zh":"高風險星期一，指星期一與較高心臟病發作機會有關。"},{"en":"The German study found a 20 per cent higher chance on Monday.","zh":"德國研究發現星期一機會高出百分之二十。"},{"en":"The phrase summarises the main statistical finding.","zh":"這個詞組概括主要統計發現。"},{"en":"It is suitable for a heading about Monday risk.","zh":"它適合作為關於星期一風險的標題。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":12},{"front":"regardless of diet and lifestyle","meaning":"不論飲食和生活方式","examples":[{"en":"The Monday peak appears regardless of diet and lifestyle.","zh":"不論飲食和生活方式如何，星期一高峰都會出現。"},{"en":"Regardless of means despite or without being changed by.","zh":"不論，指儘管或不受其改變。"},{"en":"The pattern appeared in different regions with different habits.","zh":"該模式出現在有不同習慣的不同地區。"},{"en":"The phrase shows that the Monday effect may be robust.","zh":"這個詞組顯示星期一效應可能相當穩定。"},{"en":"It fits a heading about consistency across places.","zh":"它適合作為關於跨地區一致性的標題。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":12},{"front":"unemployed and safer","meaning":"失業人士較安全","examples":[{"en":"The heading suggests that unemployed people may be safer on Mondays.","zh":"該標題表示失業人士在星期一可能較安全。"},{"en":"Unemployed and safer means people without jobs may face less Monday risk.","zh":"失業人士較安全，指沒有工作的人可能面對較低星期一風險。"},{"en":"The passage says non-workers are no more at risk on Mondays.","zh":"文章說非在職人士在星期一風險並沒有更高。"},{"en":"The phrase connects employment status with heart-attack risk.","zh":"這個詞組把就業狀況與心臟病發作風險連接起來。"},{"en":"It is a heading-style summary rather than a full sentence from the passage.","zh":"它是標題式概括，而不是文章中的完整句子。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":12},{"front":"older people also at risk","meaning":"長者也有風險","examples":[{"en":"The passage says older people are also at risk on Monday mornings.","zh":"文章說長者在星期一早上也有風險。"},{"en":"Older people also at risk means the Monday danger is not limited to workers.","zh":"長者也有風險，指星期一危險不限於在職人士。"},{"en":"The over-65s may be vulnerable even though many no longer work.","zh":"六十五歲以上人士即使很多已不再工作，也可能容易受影響。"},{"en":"The phrase fits a paragraph that complicates the work-stress explanation.","zh":"這個詞組適合令工作壓力解釋更複雜的段落。"},{"en":"It highlights another vulnerable group.","zh":"它突出另一個易受影響群體。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":12},{"front":"bodily adaptations","meaning":"身體適應變化","examples":[{"en":"The heading refers to bodily adaptations after waking and returning to activity.","zh":"該標題指醒來並重新活動後的身體適應變化。"},{"en":"Bodily adaptations are physical adjustments the body makes to a new state.","zh":"身體適應變化，是身體為新狀態作出的生理調整。"},{"en":"Blood pressure, heart rate and hormones change after waking.","zh":"醒來後，血壓、心率和荷爾蒙會改變。"},{"en":"These adaptations may place strain on the circulatory system.","zh":"這些適應變化可能令循環系統受壓。"},{"en":"The phrase summarises the paragraph about physical Monday morning changes.","zh":"這個詞組概括關於星期一早上身體變化的段落。"}],"source":"Passage 2 Flash Cards 167 - Warning - Mondays are bad for your heart.pdf","sourcePage":12}],"ielts/reading/passage-2/Practice 168":[{"front":"ensuring our future food supply","meaning":"確保我們未來的食物供應","examples":[{"en":"Seed banks play an important role in ensuring our future food supply.","zh":"種子庫在確保我們未來的食物供應方面扮演重要角色。"},{"en":"Farmers and scientists are working together on ensuring our future food supply.","zh":"農民和科學家正合作確保我們未來的食物供應。"},{"en":"Preserving old crop varieties may be essential for ensuring our future food supply.","zh":"保存古老農作物品種可能對確保我們未來的食物供應至關重要。"},{"en":"Climate change makes ensuring our future food supply more difficult.","zh":"氣候變化令確保我們未來的食物供應更困難。"},{"en":"The passage discusses several ways of ensuring our future food supply.","zh":"文章討論了幾種確保我們未來的食物供應的方法。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":1},{"front":"climate change","meaning":"氣候變化","examples":[{"en":"Climate change threatens many traditional food crops.","zh":"氣候變化威脅許多傳統糧食作物。"},{"en":"Farmers must adapt to climate change.","zh":"農民必須適應氣候變化。"},{"en":"Climate change may make some regions too dry for certain crops.","zh":"氣候變化可能使某些地區過於乾旱，不適合某些作物生長。"},{"en":"Seed diversity can help agriculture respond to climate change.","zh":"種子多樣性可以幫助農業應對氣候變化。"},{"en":"Climate change is one reason old seed varieties matter.","zh":"氣候變化是古老種子品種重要的原因之一。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":1},{"front":"new diseases","meaning":"新疾病","examples":[{"en":"New diseases can destroy crops that lack resistance.","zh":"新疾病可以摧毀缺乏抗性的作物。"},{"en":"Seed banks may help farmers fight new diseases.","zh":"種子庫可能幫助農民抵抗新疾病。"},{"en":"New diseases are a serious threat to global agriculture.","zh":"新疾病是全球農業的嚴重威脅。"},{"en":"Scientists study old varieties for resistance to new diseases.","zh":"科學家研究古老品種，以尋找對新疾病的抗性。"},{"en":"A crop with little diversity may be vulnerable to new diseases.","zh":"多樣性不足的作物可能容易受到新疾病侵害。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":1},{"front":"threaten","meaning":"威脅","examples":[{"en":"Climate change and new diseases threaten seed varieties.","zh":"氣候變化和新疾病威脅種子品種。"},{"en":"A single fungus can threaten millions of tonnes of wheat.","zh":"一種真菌可以威脅數百萬噸小麥。"},{"en":"Loss of diversity may threaten future food security.","zh":"多樣性流失可能威脅未來糧食安全。"},{"en":"Modern farming practices sometimes threaten traditional crops.","zh":"現代耕作方式有時威脅傳統作物。"},{"en":"Rising temperatures threaten harvests in many countries.","zh":"氣溫上升威脅許多國家的收成。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":1},{"front":"limited varieties of seeds","meaning":"有限的種子品種","examples":[{"en":"We depend on limited varieties of seeds for much of our food.","zh":"我們大部分食物依賴有限的種子品種。"},{"en":"Limited varieties of seeds make agriculture less resilient.","zh":"有限的種子品種令農業較缺乏韌性。"},{"en":"Farmers may lose options if only limited varieties of seeds remain.","zh":"如果只剩有限的種子品種，農民可能失去選擇。"},{"en":"Seed banks protect us from relying on limited varieties of seeds.","zh":"種子庫保護我們免於只依賴有限的種子品種。"},{"en":"Disease spreads more easily when crops come from limited varieties of seeds.","zh":"當作物來自有限的種子品種時，疾病更容易蔓延。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":1},{"front":"depend on for food","meaning":"依賴……作為食物","examples":[{"en":"Humans depend on many crops for food.","zh":"人類依賴許多作物作為食物。"},{"en":"We depend on wheat, rice and corn for food.","zh":"我們依賴小麥、稻米和粟米作為食物。"},{"en":"Future generations may depend on old seed varieties for food.","zh":"未來世代可能依賴古老種子品種作為食物。"},{"en":"Communities often depend on local crops for food.","zh":"社區常依賴本地作物作為食物。"},{"en":"The plants we depend on for food must be protected.","zh":"我們依賴作為食物的植物必須受到保護。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":1},{"front":"luckily","meaning":"幸好","examples":[{"en":"Luckily, many traditional seeds still survive.","zh":"幸好，許多傳統種子仍然存活。"},{"en":"Luckily, some farmers saved old varieties.","zh":"幸好，一些農民保存了古老品種。"},{"en":"Luckily, seed banks have stored rare seeds.","zh":"幸好，種子庫已儲存稀有種子。"},{"en":"Luckily, people are becoming more interested in heirloom plants.","zh":"幸好，人們對傳家寶植物越來越感興趣。"},{"en":"Luckily, the lost variety was found in a private garden.","zh":"幸好，這個失落品種在私人花園中被找到。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":1},{"front":"seeds used in the past","meaning":"過去使用的種子","examples":[{"en":"Many seeds used in the past are no longer common.","zh":"許多過去使用的種子已不再常見。"},{"en":"Seeds used in the past may contain useful traits.","zh":"過去使用的種子可能含有有用特徵。"},{"en":"Farmers once depended on seeds used in the past for local conditions.","zh":"農民曾依靠過去使用的種子適應本地環境。"},{"en":"Seed banks preserve seeds used in the past.","zh":"種子庫保存過去使用的種子。"},{"en":"Scientists may need seeds used in the past to fight future diseases.","zh":"科學家可能需要過去使用的種子來對抗未來疾病。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":1},{"front":"take steps to","meaning":"採取措施去","examples":[{"en":"We must take steps to protect seed diversity.","zh":"我們必須採取措施去保護種子多樣性。"},{"en":"Farmers can take steps to preserve old varieties.","zh":"農民可以採取措施去保存古老品種。"},{"en":"Governments should take steps to support seed banks.","zh":"政府應採取措施去支持種子庫。"},{"en":"Communities need to take steps to reduce crop loss.","zh":"社區需要採取措施去減少作物流失。"},{"en":"The organisation decided to take steps to save traditional seeds.","zh":"該組織決定採取措施去保存傳統種子。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":1},{"front":"save them","meaning":"拯救它們；保存它們","examples":[{"en":"Traditional seeds may disappear unless we save them.","zh":"如果我們不保存它們，傳統種子可能會消失。"},{"en":"Seed banks collect rare seeds to save them.","zh":"種子庫收集稀有種子以保存它們。"},{"en":"Farmers save them by planting and sharing them.","zh":"農民透過種植和分享來保存它們。"},{"en":"If old varieties are useful, we should save them.","zh":"如果古老品種有用，我們應該保存它們。"},{"en":"Future food security may depend on whether we save them.","zh":"未來糧食安全可能取決於我們是否保存它們。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":1},{"front":"six miles outside","meaning":"在……外六英里","examples":[{"en":"Heritage Farm lies six miles outside Decorah.","zh":"傳承農場位於Decorah外六英里。"},{"en":"The seed bank is located six miles outside the town.","zh":"種子庫位於該鎮外六英里。"},{"en":"Visitors drive six miles outside Decorah to reach the farm.","zh":"遊客開車到Decorah外六英里到達農場。"},{"en":"Six miles outside the city, the landscape becomes quiet and rural.","zh":"在城市外六英里，景觀變得安靜而鄉郊。"},{"en":"The project began on land six miles outside a small town.","zh":"該項目在一個小鎮外六英里的土地上開始。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":1},{"front":"an 890-acre stretch of","meaning":"一片890英畝的……","examples":[{"en":"Heritage Farm is an 890-acre stretch of fields and woods.","zh":"傳承農場是一片890英畝的田野和樹林。"},{"en":"The organisation owns an 890-acre stretch of farmland.","zh":"該組織擁有一片890英畝的農地。"},{"en":"An 890-acre stretch of land gives the farm room for many plants.","zh":"一片890英畝的土地讓農場有空間種植許多植物。"},{"en":"Visitors can walk through an 890-acre stretch of rolling countryside.","zh":"遊客可以走過一片890英畝的起伏鄉郊。"},{"en":"The seed project operates on an 890-acre stretch of rural land.","zh":"這個種子項目在一片890英畝的鄉郊土地上運作。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":1},{"front":"rolling fields and woods","meaning":"起伏的田野和樹林","examples":[{"en":"Heritage Farm contains rolling fields and woods.","zh":"傳承農場包含起伏的田野和樹林。"},{"en":"The rolling fields and woods create a peaceful landscape.","zh":"起伏的田野和樹林形成寧靜景觀。"},{"en":"Old seed varieties grow among rolling fields and woods.","zh":"古老種子品種在起伏的田野和樹林之間生長。"},{"en":"Visitors enjoy walking through rolling fields and woods.","zh":"遊客喜歡走過起伏的田野和樹林。"},{"en":"The farm’s rolling fields and woods contrast with industrial farmland nearby.","zh":"農場起伏的田野和樹林與附近工業化農地形成對比。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":1},{"front":"Heritage Farm","meaning":"傳承農場","examples":[{"en":"Heritage Farm is home to the Seed Savers Exchange.","zh":"傳承農場是種子保存者交流會的所在地。"},{"en":"Heritage Farm preserves rare plant varieties.","zh":"傳承農場保存稀有植物品種。"},{"en":"Visitors can see heirloom vegetables at Heritage Farm.","zh":"遊客可以在傳承農場看到傳統品種蔬菜。"},{"en":"Heritage Farm is different from the surrounding farmland.","zh":"傳承農場與周邊農地不同。"},{"en":"Heritage Farm helps protect seeds for the future.","zh":"傳承農場幫助保護未來所需的種子。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":2},{"front":"let crops go to seed","meaning":"讓農作物結籽","examples":[{"en":"Heritage Farm lets crops go to seed.","zh":"傳承農場讓農作物結籽。"},{"en":"Farmers let crops go to seed when they want to save seeds.","zh":"農民想保存種子時會讓農作物結籽。"},{"en":"Letting crops go to seed is different from harvesting them for food.","zh":"讓農作物結籽不同於把它們收割作食物。"},{"en":"The gardeners let crops go to seed so the variety can continue.","zh":"園丁讓農作物結籽，使品種能延續。"},{"en":"Seed savers must sometimes let crops go to seed instead of eating them.","zh":"種子保存者有時必須讓農作物結籽，而不是食用它們。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":2},{"front":"in stark contrast to","meaning":"與……形成鮮明對比","examples":[{"en":"Heritage Farm is in stark contrast to the surrounding farmland.","zh":"傳承農場與周邊農地形成鮮明對比。"},{"en":"The diverse gardens stand in stark contrast to nearby cornfields.","zh":"多樣化花園與附近粟米田形成鮮明對比。"},{"en":"Heirloom varieties are in stark contrast to uniform supermarket produce.","zh":"傳統品種與外觀一致的超市農產品形成鮮明對比。"},{"en":"The old red barn is in stark contrast to modern storage buildings.","zh":"舊紅色穀倉與現代倉庫形成鮮明對比。"},{"en":"Traditional farming methods are in stark contrast to industrial agriculture.","zh":"傳統耕作方式與工業化農業形成鮮明對比。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":2},{"front":"surrounding acres","meaning":"周邊大片土地","examples":[{"en":"The surrounding acres are filled with corn and soybeans.","zh":"周邊大片土地種滿粟米和大豆。"},{"en":"The surrounding acres look very different from Heritage Farm.","zh":"周邊大片土地看起來與傳承農場非常不同。"},{"en":"Farmers cultivate the surrounding acres intensively.","zh":"農民對周邊大片土地進行集約耕作。"},{"en":"The surrounding acres show the pattern of modern agriculture.","zh":"周邊大片土地顯示現代農業的模式。"},{"en":"Few heirloom crops grow on the surrounding acres.","zh":"周邊大片土地很少種植傳統品種作物。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":2},{"front":"intensively farmed fields","meaning":"集約耕作的農田","examples":[{"en":"The surrounding area contains intensively farmed fields.","zh":"周邊地區包含集約耕作的農田。"},{"en":"Intensively farmed fields often grow only a few crops.","zh":"集約耕作的農田通常只種少數作物。"},{"en":"Corn and soybeans dominate the intensively farmed fields.","zh":"粟米和大豆主導這些集約耕作的農田。"},{"en":"Intensively farmed fields may reduce biodiversity.","zh":"集約耕作的農田可能減少生物多樣性。"},{"en":"Heritage Farm differs from the intensively farmed fields nearby.","zh":"傳承農場與附近集約耕作的農田不同。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":2},{"front":"corn and soybeans","meaning":"粟米和大豆","examples":[{"en":"Modern farms around Heritage Farm grow corn and soybeans.","zh":"傳承農場周圍的現代農場種植粟米和大豆。"},{"en":"Corn and soybeans are common in intensive agriculture.","zh":"粟米和大豆在集約農業中很常見。"},{"en":"Many surrounding fields are planted with corn and soybeans.","zh":"周邊許多田地都種上粟米和大豆。"},{"en":"Corn and soybeans represent a limited crop system.","zh":"粟米和大豆代表有限的作物系統。"},{"en":"Heritage Farm grows many crops, not just corn and soybeans.","zh":"傳承農場種植許多作物，而不只是粟米和大豆。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":2},{"front":"be typical of","meaning":"是……的典型","examples":[{"en":"Corn and soybean fields are typical of modern agriculture.","zh":"粟米和大豆田是現代農業的典型。"},{"en":"Uniform produce is typical of many supermarkets.","zh":"外觀一致的農產品是許多超市的典型。"},{"en":"Seed diversity is not typical of industrial farming.","zh":"種子多樣性不是工業化農業的典型。"},{"en":"Heirloom varieties are typical of older farming traditions.","zh":"傳統品種是較舊農業傳統的典型。"},{"en":"Large single-crop fields are typical of the surrounding acres.","zh":"大型單一作物田是周邊大片土地的典型。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":2},{"front":"modern agriculture","meaning":"現代農業","examples":[{"en":"Modern agriculture often relies on uniform crop varieties.","zh":"現代農業通常依賴一致的作物品種。"},{"en":"Modern agriculture produces large quantities of food.","zh":"現代農業生產大量食物。"},{"en":"Modern agriculture can reduce the diversity of seeds.","zh":"現代農業可能減少種子多樣性。"},{"en":"Heritage Farm looks different from modern agriculture around it.","zh":"傳承農場看起來與周圍現代農業不同。"},{"en":"Modern agriculture must adapt to climate change.","zh":"現代農業必須適應氣候變化。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":2},{"front":"be devoted to","meaning":"致力於","examples":[{"en":"Heritage Farm is devoted to preserving seeds.","zh":"傳承農場致力於保存種子。"},{"en":"The organisation is devoted to collecting heirloom varieties.","zh":"該組織致力於收集傳統品種。"},{"en":"Diane was devoted to saving traditional plants.","zh":"Diane致力於保存傳統植物。"},{"en":"The seed bank is devoted to protecting food diversity.","zh":"種子庫致力於保護食物多樣性。"},{"en":"Volunteers are devoted to keeping old seeds alive.","zh":"志願者致力於讓古老種子延續。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":2},{"front":"collecting rather than growing seeds","meaning":"收集種子而非種植種子","examples":[{"en":"Heritage Farm is devoted to collecting rather than growing seeds for sale.","zh":"傳承農場致力於收集種子，而非種植種子出售。"},{"en":"The project focuses on collecting rather than growing seeds commercially.","zh":"該項目集中於收集種子，而非商業種植種子。"},{"en":"Collecting rather than growing seeds helps preserve rare varieties.","zh":"收集種子而非種植種子有助保存稀有品種。"},{"en":"The farm’s main purpose is collecting rather than growing seeds as food.","zh":"農場的主要目的在於收集種子，而非把種子種成食物。"},{"en":"Visitors learn why collecting rather than growing seeds matters.","zh":"遊客學習為何收集種子而非種植種子很重要。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":2},{"front":"be home to","meaning":"是……的所在地","examples":[{"en":"Heritage Farm is home to the Seed Savers Exchange.","zh":"傳承農場是種子保存者交流會的所在地。"},{"en":"The valley is home to many old plant varieties.","zh":"這個山谷是許多古老植物品種的所在地。"},{"en":"The seed bank is home to thousands of rare seeds.","zh":"種子庫是數千種稀有種子的所在地。"},{"en":"The old barn is home to morning glory blossoms.","zh":"舊穀倉是牽牛花盛開的地方。"},{"en":"This region is home to several traditional crops.","zh":"這個地區是幾種傳統作物的所在地。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":2},{"front":"Seed Savers Exchange","meaning":"種子保存者交流會","examples":[{"en":"The Seed Savers Exchange preserves heirloom plant varieties.","zh":"種子保存者交流會保存傳家寶植物品種。"},{"en":"The Seed Savers Exchange has more than 13,000 members.","zh":"種子保存者交流會有超過13,000名會員。"},{"en":"Members of the Seed Savers Exchange donate seeds.","zh":"種子保存者交流會的會員捐贈種子。"},{"en":"The Seed Savers Exchange publishes a yearbook.","zh":"種子保存者交流會出版年鑑。"},{"en":"The Seed Savers Exchange protects food diversity.","zh":"種子保存者交流會保護食物多樣性。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":2},{"front":"non-government-owned seed banks","meaning":"非政府擁有的種子庫","examples":[{"en":"It is one of the largest non-government-owned seed banks in the United States.","zh":"它是美國最大的非政府擁有的種子庫之一。"},{"en":"Non-government-owned seed banks can preserve rare varieties independently.","zh":"非政府擁有的種子庫可以獨立保存稀有品種。"},{"en":"Many farmers trust non-government-owned seed banks.","zh":"許多農民信任非政府擁有的種子庫。"},{"en":"Non-government-owned seed banks may rely on members and donations.","zh":"非政府擁有的種子庫可能依賴會員和捐贈。"},{"en":"Heritage Farm is linked to one of these non-government-owned seed banks.","zh":"傳承農場與其中一個非政府擁有的種子庫有關。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":2},{"front":"seedlings","meaning":"幼苗","examples":[{"en":"Diane Ott Whealy was given the seedlings of two plant varieties.","zh":"Diane Ott Whealy獲贈兩種植物品種的幼苗。"},{"en":"The seedlings grew into heirloom plants.","zh":"這些幼苗長成傳家寶植物。"},{"en":"Farmers protect seedlings from frost.","zh":"農民保護幼苗免受霜害。"},{"en":"Seedlings are young plants grown from seeds.","zh":"幼苗是由種子長出的年幼植物。"},{"en":"The old seedlings inspired Diane to preserve traditional varieties.","zh":"這些古老幼苗啟發Diane保存傳統品種。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":3},{"front":"plant varieties","meaning":"植物品種","examples":[{"en":"The seedlings belonged to two traditional plant varieties.","zh":"這些幼苗屬於兩種傳統植物品種。"},{"en":"Many plant varieties have disappeared over time.","zh":"許多植物品種隨時間消失。"},{"en":"Seed banks preserve thousands of plant varieties.","zh":"種子庫保存數千種植物品種。"},{"en":"Different plant varieties may resist different diseases.","zh":"不同植物品種可能抵抗不同疾病。"},{"en":"Farmers once grew many more plant varieties.","zh":"農民過去曾種植更多植物品種。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":3},{"front":"great-grandfather","meaning":"曾祖父","examples":[{"en":"Her great-grandfather brought the seeds from Bavaria.","zh":"她的曾祖父從巴伐利亞帶來這些種子。"},{"en":"Diane’s great-grandfather preserved two special varieties.","zh":"Diane的曾祖父保存了兩個特別品種。"},{"en":"The story of her great-grandfather inspired the exchange.","zh":"她曾祖父的故事啟發了這個交流會。"},{"en":"A great-grandfather can pass seeds down through generations.","zh":"曾祖父可以把種子世代相傳。"},{"en":"Her great-grandfather’s plants became part of seed-saving history.","zh":"她曾祖父的植物成為種子保存史的一部分。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":3},{"front":"bring something to America from","meaning":"把……從……帶到美國","examples":[{"en":"Her great-grandfather brought seeds to America from Bavaria.","zh":"她的曾祖父把種子從巴伐利亞帶到美國。"},{"en":"Immigrants often bring food traditions to America from their homelands.","zh":"移民常把飲食傳統從故鄉帶到美國。"},{"en":"He helped bring a tomato variety to America from Europe.","zh":"他幫助把一種番茄品種從歐洲帶到美國。"},{"en":"Families may bring treasured seeds to America from distant countries.","zh":"家庭可能把珍貴種子從遙遠國家帶到美國。"},{"en":"Diane learned that her ancestor had brought plants to America from Bavaria.","zh":"Diane得知她的祖先把植物從巴伐利亞帶到美國。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":3},{"front":"Bavaria","meaning":"巴伐利亞","examples":[{"en":"The plant varieties came from Bavaria in 1870.","zh":"這些植物品種於1870年來自巴伐利亞。"},{"en":"Bavaria was the origin of the family seeds.","zh":"巴伐利亞是這些家族種子的來源地。"},{"en":"Her great-grandfather brought the seeds from Bavaria.","zh":"她的曾祖父從巴伐利亞帶來這些種子。"},{"en":"The German Pink tomato was linked to Bavaria.","zh":"German Pink番茄與巴伐利亞有關。"},{"en":"Seeds from Bavaria became part of an American seed bank.","zh":"來自巴伐利亞的種子成為美國種子庫的一部分。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":3},{"front":"morning glory","meaning":"牽牛花","examples":[{"en":"Grandpa Ott’s morning glory is preserved at Heritage Farm.","zh":"Grandpa Ott的牽牛花保存在傳承農場。"},{"en":"Morning glory blossoms cover the old red barn.","zh":"牽牛花花朵覆蓋舊紅色穀倉。"},{"en":"The morning glory is one of the heirloom plants.","zh":"牽牛花是傳家寶植物之一。"},{"en":"Visitors admire the morning glory flowers.","zh":"遊客欣賞牽牛花。"},{"en":"Diane received morning glory seedlings from her family.","zh":"Diane從家人那裏收到牽牛花幼苗。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":3},{"front":"German Pink tomato","meaning":"German Pink 番茄","examples":[{"en":"The German Pink tomato came from Bavaria.","zh":"German Pink番茄來自巴伐利亞。"},{"en":"Diane wanted to preserve the German Pink tomato.","zh":"Diane想保存German Pink番茄。"},{"en":"The German Pink tomato became an heirloom variety.","zh":"German Pink番茄成為傳統品種。"},{"en":"Gardeners value the German Pink tomato for its history.","zh":"園丁珍視German Pink番茄的歷史。"},{"en":"The Seed Savers Exchange helped keep the German Pink tomato alive.","zh":"種子保存者交流會幫助German Pink番茄延續。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":3},{"front":"preserve traditional varieties","meaning":"保存傳統品種","examples":[{"en":"Diane wanted to preserve traditional varieties.","zh":"Diane想保存傳統品種。"},{"en":"Seed banks preserve traditional varieties for future use.","zh":"種子庫保存傳統品種以供未來使用。"},{"en":"Farmers preserve traditional varieties by planting them each year.","zh":"農民透過每年種植來保存傳統品種。"},{"en":"It is important to preserve traditional varieties before they disappear.","zh":"在傳統品種消失前保存它們很重要。"},{"en":"Communities can preserve traditional varieties through seed exchanges.","zh":"社區可以透過種子交流保存傳統品種。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":3},{"front":"traditional varieties","meaning":"傳統品種","examples":[{"en":"Traditional varieties are often called heirloom plants.","zh":"傳統品種通常被稱為傳家寶植物。"},{"en":"Traditional varieties may have unusual colors and flavors.","zh":"傳統品種可能有不尋常的顏色和味道。"},{"en":"Many traditional varieties are missing from supermarkets.","zh":"許多傳統品種在超市中不見了。"},{"en":"Traditional varieties can carry useful genetic traits.","zh":"傳統品種可能帶有有用的基因特徵。"},{"en":"Farmers once grew many traditional varieties in local fields.","zh":"農民過去在本地田地種植許多傳統品種。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":3},{"front":"be known as","meaning":"被稱為","examples":[{"en":"Traditional varieties are known as heirloom plants.","zh":"傳統品種被稱為傳家寶植物。"},{"en":"Ug99 is known as a dangerous wheat fungus.","zh":"Ug99被稱為一種危險的小麥真菌。"},{"en":"The farm is known as Heritage Farm.","zh":"該農場被稱為傳承農場。"},{"en":"Sagarmartha is known as Goddess of the Sky.","zh":"薩加瑪塔被稱為天空女神。"},{"en":"Some old tomatoes are known as heirloom vegetables.","zh":"一些古老番茄被稱為傳統品種蔬菜。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":3},{"front":"heirloom plants","meaning":"傳家寶植物；傳統品種植物","examples":[{"en":"Heirloom plants are traditional varieties passed down over time.","zh":"傳家寶植物是隨時間傳承下來的傳統品種。"},{"en":"Heritage Farm preserves many heirloom plants.","zh":"傳承農場保存許多傳家寶植物。"},{"en":"Heirloom plants may have richer flavor than modern produce.","zh":"傳家寶植物可能比現代農產品味道更濃。"},{"en":"Gardeners exchange seeds from heirloom plants.","zh":"園丁交換傳家寶植物的種子。"},{"en":"Heirloom plants help protect food diversity.","zh":"傳家寶植物有助保護食物多樣性。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":3},{"front":"establish a place where","meaning":"建立一個……的地方","examples":[{"en":"Diane and Kent wanted to establish a place where old seeds could be kept.","zh":"Diane和Kent想建立一個可以保存古老種子的地方。"},{"en":"They decided to establish a place where members could trade seeds.","zh":"他們決定建立一個會員可以交換種子的地方。"},{"en":"Communities should establish a place where rare plants are protected.","zh":"社區應建立一個保護稀有植物的地方。"},{"en":"The founders helped establish a place where food history could survive.","zh":"創辦人幫助建立一個食物歷史能延續的地方。"},{"en":"The exchange began as an effort to establish a place where seeds had value.","zh":"交流會起初是為了建立一個重視種子的地方。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":3},{"front":"seeds of the past","meaning":"過去的種子","examples":[{"en":"The seeds of the past may help feed the future.","zh":"過去的種子可能幫助養活未來。"},{"en":"Heritage Farm protects the seeds of the past.","zh":"傳承農場保護過去的種子。"},{"en":"The seeds of the past carry stories of families and places.","zh":"過去的種子承載着家庭和地方故事。"},{"en":"Farmers once depended on the seeds of the past.","zh":"農民曾依賴過去的種子。"},{"en":"Scientists may need the seeds of the past to solve future problems.","zh":"科學家可能需要過去的種子來解決未來問題。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":3},{"front":"be kept and traded","meaning":"被保存和交換","examples":[{"en":"Traditional seeds could be kept and traded at the exchange.","zh":"傳統種子可以在交流會被保存和交換。"},{"en":"Rare varieties need to be kept and traded carefully.","zh":"稀有品種需要被小心保存和交換。"},{"en":"Seeds are kept and traded by members each year.","zh":"種子每年由會員保存和交換。"},{"en":"Heirloom plants survive when their seeds are kept and traded.","zh":"當種子被保存和交換時，傳家寶植物得以延續。"},{"en":"The yearbook lists seeds that can be kept and traded.","zh":"年鑑列出可被保存和交換的種子。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":4},{"front":"the exchange","meaning":"交流會","examples":[{"en":"The exchange now has more than 13,000 members.","zh":"交流會現在有超過13,000名會員。"},{"en":"Farmers join the exchange to share rare seeds.","zh":"農民加入交流會以分享稀有種子。"},{"en":"The exchange publishes a detailed yearbook.","zh":"交流會出版詳細年鑑。"},{"en":"Diane helped create the exchange with her husband.","zh":"Diane與丈夫共同創立了交流會。"},{"en":"The exchange protects thousands of heirloom varieties.","zh":"交流會保護數千種傳統品種。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":4},{"front":"more than 13,000 members","meaning":"超過13,000名會員","examples":[{"en":"The exchange has more than 13,000 members.","zh":"交流會有超過13,000名會員。"},{"en":"More than 13,000 members support the seed-saving effort.","zh":"超過13,000名會員支持種子保存工作。"},{"en":"The organisation grew to more than 13,000 members.","zh":"該組織發展到超過13,000名會員。"},{"en":"More than 13,000 members can share seeds through the yearbook.","zh":"超過13,000名會員可以透過年鑑分享種子。"},{"en":"Having more than 13,000 members shows strong public interest.","zh":"擁有超過13,000名會員顯示公眾興趣濃厚。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":4},{"front":"many thousands of","meaning":"數以千計的","examples":[{"en":"Many thousands of heirloom varieties have been donated.","zh":"數以千計的傳統品種已被捐贈。"},{"en":"The seed bank stores many thousands of seeds.","zh":"種子庫儲存數以千計的種子。"},{"en":"Many thousands of food varieties have disappeared.","zh":"數以千計的食物品種已經消失。"},{"en":"Many thousands of members read the yearbook.","zh":"數以千計的會員閱讀年鑑。"},{"en":"The farm protects many thousands of living plant histories.","zh":"農場保護數以千計仍存活的植物歷史。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":4},{"front":"donate","meaning":"捐贈","examples":[{"en":"Members donate heirloom seeds to the exchange.","zh":"會員向交流會捐贈傳統種子。"},{"en":"Gardeners donate rare beans and tomatoes.","zh":"園丁捐贈稀有豆類和番茄。"},{"en":"People donate seeds with family stories attached.","zh":"人們捐贈帶有家族故事的種子。"},{"en":"Archaeologists may donate unusual seeds to a seed bank.","zh":"考古學家可能向種子庫捐贈不尋常種子。"},{"en":"Anyone can donate a valuable traditional variety.","zh":"任何人都可以捐贈有價值的傳統品種。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":4},{"front":"walk-in coolers","meaning":"步入式冷藏室","examples":[{"en":"The seeds are kept in walk-in coolers.","zh":"這些種子保存在步入式冷藏室中。"},{"en":"Walk-in coolers help maintain stable temperatures.","zh":"步入式冷藏室有助維持穩定溫度。"},{"en":"Rare seeds last longer in walk-in coolers.","zh":"稀有種子在步入式冷藏室中保存更久。"},{"en":"Staff check the walk-in coolers regularly.","zh":"工作人員定期檢查步入式冷藏室。"},{"en":"The seed bank uses walk-in coolers for storage.","zh":"種子庫使用步入式冷藏室進行儲存。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":4},{"front":"freezers","meaning":"冰櫃","examples":[{"en":"The seed bank stores seeds in freezers.","zh":"種子庫把種子儲存在冰櫃中。"},{"en":"Freezers protect seeds from heat and moisture.","zh":"冰櫃保護種子免受高溫和潮濕影響。"},{"en":"Some seeds remain viable for years in freezers.","zh":"有些種子在冰櫃中多年仍可發芽。"},{"en":"The farm uses freezers for long-term storage.","zh":"農場使用冰櫃作長期儲存。"},{"en":"Workers label the freezers carefully.","zh":"工作人員仔細標示冰櫃。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":4},{"front":"root cellars","meaning":"根菜儲藏窖","examples":[{"en":"Some heirloom seeds are kept in root cellars.","zh":"有些傳統種子保存在根菜儲藏窖中。"},{"en":"Root cellars provide cool storage conditions.","zh":"根菜儲藏窖提供涼爽的儲存環境。"},{"en":"Farmers traditionally stored crops in root cellars.","zh":"農民傳統上把作物儲存在根菜儲藏窖中。"},{"en":"The farm uses root cellars alongside freezers.","zh":"農場同時使用根菜儲藏窖和冰櫃。"},{"en":"Root cellars help preserve certain plant materials.","zh":"根菜儲藏窖有助保存某些植物材料。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":4},{"front":"old red barn","meaning":"舊紅色穀倉","examples":[{"en":"An old red barn stands at Heritage Farm.","zh":"傳承農場有一座舊紅色穀倉。"},{"en":"The old red barn is covered in morning glory blossoms.","zh":"舊紅色穀倉覆蓋着牽牛花花朵。"},{"en":"Visitors often photograph the old red barn.","zh":"遊客常拍攝舊紅色穀倉。"},{"en":"The old red barn gives the farm a historic feeling.","zh":"舊紅色穀倉賦予農場歷史感。"},{"en":"Seeds are stored near the old red barn.","zh":"種子儲存在舊紅色穀倉附近。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":4},{"front":"be covered in","meaning":"覆蓋着","examples":[{"en":"The barn is covered in morning glory blossoms.","zh":"穀倉覆蓋着牽牛花花朵。"},{"en":"The field was covered in wildflowers.","zh":"田野覆蓋着野花。"},{"en":"Some plants are covered in seeds by late summer.","zh":"到夏末，有些植物覆蓋着種子。"},{"en":"The old fence was covered in vines.","zh":"舊圍欄覆蓋着藤蔓。"},{"en":"The table was covered in packets of heirloom seeds.","zh":"桌上覆蓋着一包包傳統種子。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":4},{"front":"blossoms","meaning":"花朵","examples":[{"en":"Morning glory blossoms cover the barn.","zh":"牽牛花花朵覆蓋穀倉。"},{"en":"The blossoms attract visitors to the farm.","zh":"花朵吸引遊客到農場。"},{"en":"Bright blossoms appear in early morning.","zh":"明亮的花朵在清晨出現。"},{"en":"Some heirloom plants are valued for their blossoms.","zh":"有些傳家寶植物因花朵而受到珍視。"},{"en":"The red barn looks beautiful under the blossoms.","zh":"舊紅色穀倉在花朵下顯得很美。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":4},{"front":"come across","meaning":"偶然看見；遇見","examples":[{"en":"Visitors come across many unusual vegetables at Heritage Farm.","zh":"遊客在傳承農場偶然看見許多不尋常蔬菜。"},{"en":"You may come across rare seeds in the yearbook.","zh":"你可能在年鑑中偶然看見稀有種子。"},{"en":"Gardeners sometimes come across forgotten family varieties.","zh":"園丁有時偶然遇見被遺忘的家族品種。"},{"en":"Researchers come across old crop names in archives.","zh":"研究人員在檔案中偶然看到古老作物名稱。"},{"en":"While walking through the farm, visitors come across herbs and flowers.","zh":"遊客走過農場時會遇見香草和花卉。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":4},{"front":"vegetables, herbs and flowers","meaning":"蔬菜、香草和花卉","examples":[{"en":"Heritage Farm grows vegetables, herbs and flowers.","zh":"傳承農場種植蔬菜、香草和花卉。"},{"en":"The yearbook lists vegetables, herbs and flowers.","zh":"年鑑列出蔬菜、香草和花卉。"},{"en":"Visitors see vegetables, herbs and flowers in the fields.","zh":"遊客在田野裏看到蔬菜、香草和花卉。"},{"en":"Seeds for vegetables, herbs and flowers are carefully stored.","zh":"蔬菜、香草和花卉的種子被小心儲存。"},{"en":"Heirloom vegetables, herbs and flowers preserve living history.","zh":"傳統品種蔬菜、香草和花卉保存了活的歷史。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":4},{"front":"hand over","meaning":"遞交","examples":[{"en":"Diane Ott Whealy hands over a copy of the yearbook.","zh":"Diane Ott Whealy遞交一本年鑑。"},{"en":"Members hand over rare seeds to the exchange.","zh":"會員把稀有種子遞交給交流會。"},{"en":"The gardener decided to hand over family seeds for preservation.","zh":"園丁決定遞交家族種子以作保存。"},{"en":"Volunteers hand over seed packets to visitors.","zh":"志願者把種子包遞交給遊客。"},{"en":"Farmers hand over information about each variety’s history.","zh":"農民遞交每個品種歷史的資料。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":5},{"front":"a copy of","meaning":"一本；一份","examples":[{"en":"Diane hands over a copy of the yearbook.","zh":"Diane遞交一本年鑑。"},{"en":"Each member may receive a copy of the seed list.","zh":"每位會員可能收到一份種子清單。"},{"en":"The visitor asked for a copy of the farm map.","zh":"遊客要求一份農場地圖。"},{"en":"A copy of the old catalogue was kept in the office.","zh":"辦公室保存了一份舊目錄。"},{"en":"Researchers studied a copy of the Seed Savers Exchange Yearbook.","zh":"研究人員研究了一本種子保存者交流會年鑑。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":5},{"front":"Seed Savers Exchange Yearbook","meaning":"種子保存者交流會年鑑","examples":[{"en":"The Seed Savers Exchange Yearbook lists members’ seeds.","zh":"種子保存者交流會年鑑列出會員的種子。"},{"en":"The Seed Savers Exchange Yearbook is very thick.","zh":"種子保存者交流會年鑑非常厚。"},{"en":"Members use the Seed Savers Exchange Yearbook to find varieties.","zh":"會員使用種子保存者交流會年鑑尋找品種。"},{"en":"The Seed Savers Exchange Yearbook contains personal seed histories.","zh":"種子保存者交流會年鑑包含種子的個別歷史。"},{"en":"Diane showed a visitor the Seed Savers Exchange Yearbook.","zh":"Diane向遊客展示種子保存者交流會年鑑。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":5},{"front":"as thick as","meaning":"厚得像……","examples":[{"en":"The yearbook is as thick as a big-city telephone directory.","zh":"年鑑厚得像大城市電話簿。"},{"en":"The seed catalogue is as thick as a textbook.","zh":"種子目錄厚得像教科書。"},{"en":"Her notes were as thick as a farm manual.","zh":"她的筆記厚得像農場手冊。"},{"en":"The file of seed records was as thick as a dictionary.","zh":"種子記錄文件厚得像字典。"},{"en":"The printed yearbook felt as thick as a phone book.","zh":"印刷年鑑摸起來厚得像電話簿。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":5},{"front":"big-city telephone directory","meaning":"大城市電話簿","examples":[{"en":"The yearbook is as thick as a big-city telephone directory.","zh":"年鑑厚得像大城市電話簿。"},{"en":"A big-city telephone directory contains many pages.","zh":"大城市電話簿包含許多頁。"},{"en":"The comparison to a big-city telephone directory shows the yearbook’s size.","zh":"與大城市電話簿作比較顯示年鑑的厚度。"},{"en":"Few catalogues are as thick as a big-city telephone directory.","zh":"很少目錄像大城市電話簿那麼厚。"},{"en":"The old yearbook resembled a big-city telephone directory.","zh":"舊年鑑像一本大城市電話簿。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":5},{"front":"page after page of","meaning":"一頁又一頁的……","examples":[{"en":"The yearbook contains page after page of exotic seeds.","zh":"年鑑包含一頁又一頁的外來種子。"},{"en":"Readers find page after page of beans and tomatoes.","zh":"讀者看到一頁又一頁的豆類和番茄。"},{"en":"The catalogue offers page after page of heirloom varieties.","zh":"目錄提供一頁又一頁的傳統品種。"},{"en":"The document includes page after page of seed histories.","zh":"文件包括一頁又一頁的種子歷史。"},{"en":"Members read page after page of unusual crop names.","zh":"會員閱讀一頁又一頁的不尋常作物名稱。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":5},{"front":"exotic beans","meaning":"外來品種豆類","examples":[{"en":"The yearbook lists exotic beans.","zh":"年鑑列出外來品種豆類。"},{"en":"Exotic beans may come from distant regions.","zh":"外來品種豆類可能來自遙遠地區。"},{"en":"Gardeners exchange exotic beans through the yearbook.","zh":"園丁透過年鑑交換外來品種豆類。"},{"en":"Some exotic beans have unusual colors.","zh":"有些外來品種豆類有不尋常顏色。"},{"en":"Exotic beans add diversity to local gardens.","zh":"外來品種豆類為本地花園增加多樣性。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":5},{"front":"garlic","meaning":"蒜頭","examples":[{"en":"Persian Star garlic appears in the yearbook.","zh":"Persian Star蒜頭出現在年鑑中。"},{"en":"Garlic varieties can have personal histories.","zh":"蒜頭品種可以有個別歷史。"},{"en":"Farmers grow garlic from saved cloves.","zh":"農民用保存下來的蒜瓣種植蒜頭。"},{"en":"The bazaar in Samarkand produced a famous garlic variety.","zh":"撒馬爾罕的市集產生了一個著名蒜頭品種。"},{"en":"Garlic is one of the crops listed by seed savers.","zh":"蒜頭是種子保存者列出的作物之一。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":5},{"front":"peppers","meaning":"甜椒；辣椒","examples":[{"en":"The yearbook lists peppers among many crops.","zh":"年鑑在許多作物中列出甜椒和辣椒。"},{"en":"Peppers may be sweet, hot, red, green, or yellow.","zh":"甜椒和辣椒可以是甜的、辣的、紅的、綠的或黃的。"},{"en":"Heirloom peppers often have unusual shapes.","zh":"傳統品種甜椒和辣椒常有不尋常形狀。"},{"en":"Farmers’ markets sell many types of peppers.","zh":"農夫市場出售許多種類的甜椒和辣椒。"},{"en":"Seed savers preserve old varieties of peppers.","zh":"種子保存者保存古老甜椒和辣椒品種。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":5},{"front":"apples, pears and plums","meaning":"蘋果、梨和李子","examples":[{"en":"The yearbook lists apples, pears and plums.","zh":"年鑑列出蘋果、梨和李子。"},{"en":"Old apples, pears and plums may no longer be grown.","zh":"古老的蘋果、梨和李子可能已不再被種植。"},{"en":"Farmers once cultivated many varieties of apples, pears and plums.","zh":"農民過去種植許多蘋果、梨和李子品種。"},{"en":"Apples, pears and plums are part of fruit diversity.","zh":"蘋果、梨和李子是水果多樣性的一部分。"},{"en":"Seed savers record the history of apples, pears and plums.","zh":"種子保存者記錄蘋果、梨和李子的歷史。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":5},{"front":"personal history","meaning":"個人故事；個別歷史","examples":[{"en":"Each seed variety has its own personal history.","zh":"每個種子品種都有自己的個別歷史。"},{"en":"The tomato’s personal history began with an elderly Russian lady.","zh":"這種番茄的個人故事始於一位年老俄羅斯女士。"},{"en":"A seed’s personal history can include family migration.","zh":"種子的個人故事可以包括家族遷移。"},{"en":"The yearbook records the personal history of many varieties.","zh":"年鑑記錄許多品種的個別歷史。"},{"en":"Personal history makes heirloom seeds more meaningful.","zh":"個人故事令傳統種子更有意義。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":5},{"front":"elderly Russian lady","meaning":"年老的俄羅斯女士","examples":[{"en":"An elderly Russian lady brought a tomato to the seed bank.","zh":"一位年老的俄羅斯女士把一種番茄帶到種子庫。"},{"en":"The elderly Russian lady preserved the variety for years.","zh":"這位年老的俄羅斯女士多年來保存該品種。"},{"en":"Diane remembered the story of the elderly Russian lady.","zh":"Diane記得這位年老的俄羅斯女士的故事。"},{"en":"The elderly Russian lady helped save an heirloom tomato.","zh":"這位年老的俄羅斯女士幫助保存一種傳統番茄。"},{"en":"A seed’s history may begin with an elderly Russian lady.","zh":"一粒種子的歷史可能始於一位年老的俄羅斯女士。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":5},{"front":"seed bank","meaning":"種子庫","examples":[{"en":"The tomato was brought to the seed bank.","zh":"這種番茄被帶到種子庫。"},{"en":"A seed bank stores seeds for future use.","zh":"種子庫儲存種子以供未來使用。"},{"en":"The seed bank protects rare varieties from extinction.","zh":"種子庫保護稀有品種免於滅絕。"},{"en":"Farmers can donate seeds to a seed bank.","zh":"農民可以向種子庫捐贈種子。"},{"en":"The seed bank at Heritage Farm is unusually large.","zh":"傳承農場的種子庫非常大。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":5},{"front":"bazaar","meaning":"市集","examples":[{"en":"The Persian Star garlic came from a bazaar in Samarkand.","zh":"Persian Star蒜頭來自撒馬爾罕的一個市集。"},{"en":"A bazaar can be a source of unusual seeds.","zh":"市集可以是不尋常種子的來源。"},{"en":"Travelers may find traditional foods in a bazaar.","zh":"旅客可能在市集中找到傳統食物。"},{"en":"The seed’s story began in a crowded bazaar.","zh":"這粒種子的故事始於一個擁擠市集。"},{"en":"A farmer bought rare garlic at the bazaar.","zh":"一位農民在市集買到稀有蒜頭。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":6},{"front":"archaeologists","meaning":"考古學家","examples":[{"en":"Archaeologists donated a bean found during fossil research.","zh":"考古學家捐贈了一種在化石研究中發現的豆。"},{"en":"Archaeologists sometimes find ancient seeds.","zh":"考古學家有時會發現古代種子。"},{"en":"The archaeologists were searching for fossils.","zh":"考古學家正在尋找化石。"},{"en":"Archaeologists helped add an unusual bean to the seed bank.","zh":"考古學家幫助把一種不尋常豆類加入種子庫。"},{"en":"Discoveries by archaeologists can reveal food history.","zh":"考古學家的發現可以揭示食物歷史。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":6},{"front":"search for fossils","meaning":"尋找化石","examples":[{"en":"Archaeologists were searching for fossils in New Mexico.","zh":"考古學家在新墨西哥尋找化石。"},{"en":"They discovered a bean while searching for fossils.","zh":"他們在尋找化石時發現了一種豆。"},{"en":"A search for fossils led to an unexpected seed discovery.","zh":"尋找化石導致一次意外的種子發現。"},{"en":"Scientists often search for fossils to understand the past.","zh":"科學家常尋找化石以了解過去。"},{"en":"During the search for fossils, they found evidence of old life.","zh":"在尋找化石期間，他們發現了古老生命的證據。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":6},{"front":"pygmy elephant fossils","meaning":"侏儒象化石","examples":[{"en":"Archaeologists were searching for pygmy elephant fossils.","zh":"考古學家正在尋找侏儒象化石。"},{"en":"Pygmy elephant fossils were found in New Mexico.","zh":"侏儒象化石在新墨西哥被發現。"},{"en":"The search for pygmy elephant fossils led to a bean discovery.","zh":"尋找侏儒象化石導致發現一種豆。"},{"en":"Pygmy elephant fossils reveal ancient animal life.","zh":"侏儒象化石揭示古代動物生命。"},{"en":"The bean was discovered during research on pygmy elephant fossils.","zh":"這種豆是在侏儒象化石研究期間被發現的。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":6},{"front":"heirloom vegetables","meaning":"傳統品種蔬菜","examples":[{"en":"Heirloom vegetables have become fashionable in recent years.","zh":"傳統品種蔬菜近年變得流行。"},{"en":"Farmers’ markets often sell heirloom vegetables.","zh":"農夫市場常出售傳統品種蔬菜。"},{"en":"Heirloom vegetables may have stronger flavor than supermarket produce.","zh":"傳統品種蔬菜可能比超市農產品味道更濃。"},{"en":"Chefs value heirloom vegetables for their uniqueness.","zh":"廚師珍視傳統品種蔬菜的獨特性。"},{"en":"Protecting heirloom vegetables helps preserve food diversity.","zh":"保護傳統品種蔬菜有助保存食物多樣性。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":6},{"front":"become fashionable","meaning":"變得流行","examples":[{"en":"Heirloom vegetables have become fashionable.","zh":"傳統品種蔬菜已變得流行。"},{"en":"Local food has become fashionable in many cities.","zh":"本地食物在許多城市變得流行。"},{"en":"Farmers’ markets have become fashionable among young shoppers.","zh":"農夫市場在年輕購物者中變得流行。"},{"en":"Old tomato varieties have become fashionable again.","zh":"古老番茄品種再次變得流行。"},{"en":"Eating seasonal produce has become fashionable in restaurants.","zh":"食用時令農產品在餐廳中變得流行。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":6},{"front":"over the past decade","meaning":"在過去十年","examples":[{"en":"Heirloom vegetables have become popular over the past decade.","zh":"傳統品種蔬菜在過去十年變得受歡迎。"},{"en":"Food awareness has increased over the past decade.","zh":"食物意識在過去十年有所提高。"},{"en":"Farmers’ markets have expanded over the past decade.","zh":"農夫市場在過去十年有所擴展。"},{"en":"Seed-saving groups have grown over the past decade.","zh":"種子保存團體在過去十年有所增長。"},{"en":"Climate concerns have intensified over the past decade.","zh":"氣候憂慮在過去十年加劇。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":6},{"front":"be prized by","meaning":"受到……珍視","examples":[{"en":"Heirloom vegetables are prized by chefs.","zh":"傳統品種蔬菜受到廚師珍視。"},{"en":"Old seed varieties are prized by gardeners.","zh":"古老種子品種受到園丁珍視。"},{"en":"Local foods are prized by the food movement.","zh":"本地食物受到飲食運動珍視。"},{"en":"Rare beans are prized by collectors.","zh":"稀有豆類受到收藏者珍視。"},{"en":"Flavorful tomatoes are prized by farmers’ market shoppers.","zh":"味道濃郁的番茄受到農夫市場顧客珍視。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":6},{"front":"food movement","meaning":"飲食運動","examples":[{"en":"The food movement emphasizes eating locally.","zh":"飲食運動強調本地飲食。"},{"en":"The food movement values flavor and uniqueness.","zh":"飲食運動重視味道和獨特性。"},{"en":"Heirloom vegetables are prized by the food movement.","zh":"傳統品種蔬菜受到飲食運動珍視。"},{"en":"The food movement supports farmers’ markets.","zh":"飲食運動支持農夫市場。"},{"en":"The food movement has helped revive old varieties.","zh":"飲食運動幫助復興古老品種。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":6},{"front":"emphasize eating locally","meaning":"強調本地飲食","examples":[{"en":"The movement emphasizes eating locally.","zh":"該運動強調本地飲食。"},{"en":"Many chefs emphasize eating locally to support farmers.","zh":"許多廚師強調本地飲食以支持農民。"},{"en":"Restaurants emphasize eating locally on their menus.","zh":"餐廳在菜單上強調本地飲食。"},{"en":"Food activists emphasize eating locally for freshness.","zh":"飲食倡議者為了新鮮而強調本地飲食。"},{"en":"Farmers’ markets emphasize eating locally and seasonally.","zh":"農夫市場強調本地和時令飲食。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":6},{"front":"preserving the flavor and uniqueness of","meaning":"保存……的味道和獨特性","examples":[{"en":"The movement focuses on preserving the flavor and uniqueness of heirloom varieties.","zh":"該運動集中於保存傳統品種的味道和獨特性。"},{"en":"Seed savers care about preserving the flavor and uniqueness of old crops.","zh":"種子保存者關心保存古老作物的味道和獨特性。"},{"en":"Farmers’ markets help in preserving the flavor and uniqueness of local produce.","zh":"農夫市場有助保存本地農產品的味道和獨特性。"},{"en":"Chefs support preserving the flavor and uniqueness of traditional vegetables.","zh":"廚師支持保存傳統蔬菜的味道和獨特性。"},{"en":"Preserving the flavor and uniqueness of food varieties protects culture.","zh":"保存食物品種的味道和獨特性也保護文化。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":6},{"front":"uniqueness","meaning":"獨特性","examples":[{"en":"Heirloom varieties are valued for their uniqueness.","zh":"傳統品種因其獨特性而受到重視。"},{"en":"The uniqueness of each seed is recorded in its story.","zh":"每粒種子的獨特性記錄在其故事中。"},{"en":"Supermarkets often sacrifice uniqueness for uniformity.","zh":"超市常為了一致性犧牲獨特性。"},{"en":"Farmers’ markets celebrate the uniqueness of local produce.","zh":"農夫市場讚揚本地農產品的獨特性。"},{"en":"Seed diversity protects the uniqueness of food traditions.","zh":"種子多樣性保護飲食傳統的獨特性。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":6},{"front":"farmers’ markets","meaning":"農墟；農夫市場","examples":[{"en":"Heirloom varieties are often found in farmers’ markets.","zh":"傳統品種常見於農夫市場。"},{"en":"Farmers’ markets sell locally grown food.","zh":"農夫市場出售本地種植食物。"},{"en":"Shoppers visit farmers’ markets for unusual vegetables.","zh":"購物者到農夫市場尋找不尋常蔬菜。"},{"en":"Farmers’ markets support small producers.","zh":"農夫市場支持小型生產者。"},{"en":"Old tomato varieties are popular at farmers’ markets.","zh":"古老番茄品種在農夫市場很受歡迎。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":6},{"front":"boutique groceries","meaning":"精品雜貨店","examples":[{"en":"Heirloom varieties are also found in boutique groceries.","zh":"傳統品種也可在精品雜貨店找到。"},{"en":"Boutique groceries often sell specialty foods.","zh":"精品雜貨店通常出售特色食品。"},{"en":"Shoppers may find rare apples in boutique groceries.","zh":"購物者可能在精品雜貨店找到稀有蘋果。"},{"en":"Boutique groceries value flavor and uniqueness.","zh":"精品雜貨店重視味道和獨特性。"},{"en":"Farmers sometimes supply boutique groceries with heirloom produce.","zh":"農民有時向精品雜貨店供應傳統品種農產品。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":7},{"front":"be squeezed out of","meaning":"被擠出","examples":[{"en":"Heirloom varieties have been squeezed out of supermarkets.","zh":"傳統品種已被擠出超市。"},{"en":"Small farmers can be squeezed out of large markets.","zh":"小農可能被擠出大型市場。"},{"en":"Flavorful crops were squeezed out of the mainstream food system.","zh":"味道好的作物被擠出主流食物系統。"},{"en":"Rare varieties may be squeezed out of production.","zh":"稀有品種可能被擠出生產。"},{"en":"Local foods are often squeezed out of supermarket shelves.","zh":"本地食物常被擠出超市貨架。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":7},{"front":"in favor of","meaning":"轉而支持；取而代之的是","examples":[{"en":"Heirloom varieties were replaced in favor of uniform produce.","zh":"傳統品種被外觀一致的農產品取代。"},{"en":"Supermarkets chose modern fruits in favor of older varieties.","zh":"超市轉而選擇現代水果，而不是古老品種。"},{"en":"Farmers abandoned some crops in favor of higher yields.","zh":"農民放棄某些作物，轉而支持更高產量。"},{"en":"Flavor was sometimes ignored in favor of transportability.","zh":"味道有時被忽略，取而代之的是適合運輸。"},{"en":"Diversity was reduced in favor of efficiency.","zh":"多樣性被削減，取而代之的是效率。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":7},{"front":"modern single-variety fruits and vegetables","meaning":"現代單一品種蔬果","examples":[{"en":"Supermarkets often sell modern single-variety fruits and vegetables.","zh":"超市常出售現代單一品種蔬果。"},{"en":"Modern single-variety fruits and vegetables usually look uniform.","zh":"現代單一品種蔬果通常外觀一致。"},{"en":"Consumers may not notice modern single-variety fruits and vegetables replacing older crops.","zh":"消費者可能沒有注意到現代單一品種蔬果正在取代古老作物。"},{"en":"Modern single-variety fruits and vegetables are bred for transport.","zh":"現代單一品種蔬果被培育成適合運輸。"},{"en":"Seed diversity declines when modern single-variety fruits and vegetables dominate.","zh":"當現代單一品種蔬果佔主導時，種子多樣性下降。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":7},{"front":"be bred to","meaning":"被培育成……","examples":[{"en":"Modern produce is bred to ship well.","zh":"現代農產品被培育成適合運輸。"},{"en":"Some fruits are bred to look uniform.","zh":"有些水果被培育成外觀一致。"},{"en":"Crops can be bred to resist disease.","zh":"作物可以被培育成能抵抗疾病。"},{"en":"Vegetables may be bred to mature quickly.","zh":"蔬菜可能被培育成快速成熟。"},{"en":"Many supermarket tomatoes are bred to survive transport.","zh":"許多超市番茄被培育成能承受運輸。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":7},{"front":"ship well","meaning":"適合運輸","examples":[{"en":"Modern produce is bred to ship well.","zh":"現代農產品被培育成適合運輸。"},{"en":"Fruit that ships well may not have the best flavor.","zh":"適合運輸的水果味道未必最好。"},{"en":"Supermarkets prefer vegetables that ship well.","zh":"超市偏好適合運輸的蔬菜。"},{"en":"Apples must ship well to reach distant markets.","zh":"蘋果必須適合運輸才能到達遠方市場。"},{"en":"Some heirloom tomatoes do not ship well.","zh":"有些傳統番茄並不適合運輸。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":7},{"front":"uniform appearance","meaning":"一致的外觀","examples":[{"en":"Modern produce is bred for uniform appearance.","zh":"現代農產品被培育成具有一致的外觀。"},{"en":"Supermarkets value uniform appearance in fruits and vegetables.","zh":"超市重視蔬果一致的外觀。"},{"en":"Uniform appearance makes produce easier to display.","zh":"一致的外觀令農產品更容易陳列。"},{"en":"Flavor may be sacrificed for uniform appearance.","zh":"味道可能為了一致的外觀而被犧牲。"},{"en":"Heirloom crops often lack uniform appearance.","zh":"傳統作物通常缺乏一致的外觀。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":7},{"front":"enhance flavor","meaning":"提升味道","examples":[{"en":"Modern varieties are often not bred to enhance flavor.","zh":"現代品種通常不是為提升味道而培育。"},{"en":"Chefs prefer crops that enhance flavor in dishes.","zh":"廚師偏好能提升菜式味道的作物。"},{"en":"Seed savers may preserve varieties that enhance flavor.","zh":"種子保存者可能保存能提升味道的品種。"},{"en":"Farmers sometimes choose older tomatoes to enhance flavor.","zh":"農民有時選擇古老番茄來提升味道。"},{"en":"Food movements try to enhance flavor and uniqueness.","zh":"飲食運動試圖提升味道和獨特性。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":7},{"front":"go way beyond","meaning":"遠遠超越","examples":[{"en":"The movement goes way beyond interest in tasty food.","zh":"這場運動遠遠超越對美味食物的興趣。"},{"en":"Seed saving goes way beyond gardening as a hobby.","zh":"保存種子遠遠超越把園藝當作嗜好。"},{"en":"The issue goes way beyond farmers’ markets.","zh":"這個問題遠遠超越農夫市場。"},{"en":"Food diversity goes way beyond personal taste.","zh":"食物多樣性遠遠超越個人口味。"},{"en":"Protecting seeds goes way beyond nostalgia.","zh":"保護種子遠遠超越懷舊。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":7},{"front":"current interest in","meaning":"目前對……的興趣","examples":[{"en":"The campaign goes beyond the current interest in local food.","zh":"這場運動超越目前對本地食物的興趣。"},{"en":"Current interest in heirloom vegetables is growing.","zh":"目前對傳統品種蔬菜的興趣正在增長。"},{"en":"Current interest in farmers’ markets helps seed savers.","zh":"目前對農夫市場的興趣幫助種子保存者。"},{"en":"The current interest in flavor may support old varieties.","zh":"目前對味道的興趣可能支持古老品種。"},{"en":"Current interest in food origins encourages better awareness.","zh":"目前對食物來源的興趣促進更高意識。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":7},{"front":"North America and Europe","meaning":"北美和歐洲","examples":[{"en":"Heirloom vegetables have become fashionable in North America and Europe.","zh":"傳統品種蔬菜在北美和歐洲變得流行。"},{"en":"Farmers’ markets are popular in North America and Europe.","zh":"農夫市場在北美和歐洲很受歡迎。"},{"en":"Food movements in North America and Europe value local produce.","zh":"北美和歐洲的飲食運動重視本地農產品。"},{"en":"Seed-saving groups operate across North America and Europe.","zh":"種子保存團體在北美和歐洲運作。"},{"en":"Consumers in North America and Europe are rediscovering old varieties.","zh":"北美和歐洲的消費者正重新發現古老品種。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":7},{"front":"tasty, locally grown food","meaning":"美味的本地種植食物","examples":[{"en":"The movement is not only about tasty, locally grown food.","zh":"這場運動不只是關於美味的本地種植食物。"},{"en":"Farmers’ markets offer tasty, locally grown food.","zh":"農夫市場提供美味的本地種植食物。"},{"en":"Shoppers enjoy tasty, locally grown food in summer.","zh":"購物者在夏天享用美味的本地種植食物。"},{"en":"Tasty, locally grown food can support small farms.","zh":"美味的本地種植食物可以支持小農場。"},{"en":"The campaign connects tasty, locally grown food with food security.","zh":"這場運動把美味的本地種植食物與糧食安全連接起來。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":7},{"front":"campaign to protect","meaning":"保護……的運動","examples":[{"en":"The movement is also a campaign to protect future food supply.","zh":"這場運動也是保護未來食物供應的運動。"},{"en":"Seed savers joined a campaign to protect old varieties.","zh":"種子保存者加入保護古老品種的運動。"},{"en":"The campaign to protect crop diversity needs public support.","zh":"保護作物多樣性的運動需要公眾支持。"},{"en":"Farmers started a campaign to protect local seeds.","zh":"農民發起保護本地種子的運動。"},{"en":"A campaign to protect food heritage can also protect survival.","zh":"保護食物傳承的運動也可以保護生存。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":7},{"front":"future food supply","meaning":"未來食物供應","examples":[{"en":"Seed preservation protects the world’s future food supply.","zh":"種子保存保護世界未來食物供應。"},{"en":"Climate change threatens our future food supply.","zh":"氣候變化威脅我們的未來食物供應。"},{"en":"Old varieties may help secure future food supply.","zh":"古老品種可能幫助確保未來食物供應。"},{"en":"Future food supply depends on crop diversity.","zh":"未來食物供應取決於作物多樣性。"},{"en":"Disease-resistant seeds are important for future food supply.","zh":"抗病種子對未來食物供應很重要。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":8},{"front":"well-fed world","meaning":"食物充足的世界","examples":[{"en":"Most people in the well-fed world rarely think about seeds.","zh":"食物充足的世界中，大多數人很少思考種子。"},{"en":"The well-fed world often forgets where food comes from.","zh":"食物充足的世界常忘記食物來自哪裏。"},{"en":"Consumers in the well-fed world shop in full supermarkets.","zh":"食物充足世界中的消費者在貨品充足的超市購物。"},{"en":"The well-fed world may ignore future food risks.","zh":"食物充足的世界可能忽視未來糧食風險。"},{"en":"People in the well-fed world may take food variety for granted.","zh":"食物充足世界中的人可能把食物多樣性視為理所當然。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":8},{"front":"give little thought to","meaning":"很少思考","examples":[{"en":"Many consumers give little thought to seed diversity.","zh":"許多消費者很少思考種子多樣性。"},{"en":"People often give little thought to where their food comes from.","zh":"人們常很少思考食物來自哪裏。"},{"en":"Shoppers give little thought to crop extinction.","zh":"購物者很少思考作物滅絕。"},{"en":"Supermarket customers may give little thought to how food is grown.","zh":"超市顧客可能很少思考食物如何種植。"},{"en":"The well-fed world gives little thought to future food problems.","zh":"食物充足的世界很少思考未來糧食問題。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":8},{"front":"where their food comes from","meaning":"食物來自哪裏","examples":[{"en":"Many people do not know where their food comes from.","zh":"許多人不知道食物來自哪裏。"},{"en":"Children should learn where their food comes from.","zh":"兒童應該學習食物來自哪裏。"},{"en":"Farmers’ markets show shoppers where their food comes from.","zh":"農夫市場向購物者展示食物來自哪裏。"},{"en":"Seed stories explain where their food comes from.","zh":"種子故事解釋食物來自哪裏。"},{"en":"Consumers often forget where their food comes from.","zh":"消費者常忘記食物來自哪裏。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":8},{"front":"how it’s grown","meaning":"它是如何種植的","examples":[{"en":"People often do not know how it’s grown.","zh":"人們常不知道它是如何種植的。"},{"en":"Food labels rarely explain how it’s grown.","zh":"食物標籤很少解釋它是如何種植的。"},{"en":"Farmers can teach consumers how it’s grown.","zh":"農民可以教消費者它是如何種植的。"},{"en":"Seed diversity affects how it’s grown.","zh":"種子多樣性影響它是如何種植的。"},{"en":"Knowing how it’s grown may change what we buy.","zh":"了解它是如何種植的可能改變我們購買甚麼。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":8},{"front":"wander through","meaning":"漫步穿過","examples":[{"en":"Consumers wander through well-stocked supermarkets.","zh":"消費者漫步穿過貨品充足的超級市場。"},{"en":"Visitors wander through Heritage Farm’s gardens.","zh":"遊客漫步穿過傳承農場的花園。"},{"en":"Shoppers wander through aisles without thinking about seeds.","zh":"購物者漫步穿過走道，卻沒有思考種子。"},{"en":"Children wander through fields of vegetables and flowers.","zh":"兒童漫步穿過蔬菜和花卉田。"},{"en":"Tourists wander through farmers’ markets looking for local food.","zh":"遊客漫步穿過農夫市場尋找本地食物。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":8},{"front":"well-stocked supermarkets","meaning":"貨品充足的超級市場","examples":[{"en":"Consumers shop in well-stocked supermarkets.","zh":"消費者在貨品充足的超級市場購物。"},{"en":"Well-stocked supermarkets can hide problems in food supply.","zh":"貨品充足的超級市場可能掩蓋食物供應問題。"},{"en":"People in wealthy countries rely on well-stocked supermarkets.","zh":"富裕國家的人依賴貨品充足的超級市場。"},{"en":"Well-stocked supermarkets often sell uniform produce.","zh":"貨品充足的超級市場通常出售外觀一致的農產品。"},{"en":"Shoppers in well-stocked supermarkets may ignore seed loss.","zh":"在貨品充足的超級市場購物的人可能忽視種子流失。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":8},{"front":"without realizing that","meaning":"沒有意識到","examples":[{"en":"Consumers shop without realizing that food diversity is declining.","zh":"消費者購物時沒有意識到食物多樣性正在下降。"},{"en":"People eat bread without realizing that wheat is under threat.","zh":"人們吃麵包時沒有意識到小麥正受威脅。"},{"en":"Shoppers buy apples without realizing that many varieties vanished.","zh":"購物者買蘋果時沒有意識到許多品種已消失。"},{"en":"Farmers may plant uniform crops without realizing that risk increases.","zh":"農民可能種植一致作物，卻沒有意識到風險增加。"},{"en":"We may depend on few crops without realizing that this is dangerous.","zh":"我們可能依賴少數作物，卻沒有意識到這很危險。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":8},{"front":"problems ahead","meaning":"前方的問題；未來問題","examples":[{"en":"There may be problems ahead for food supply.","zh":"食物供應可能面臨未來問題。"},{"en":"Seed loss suggests problems ahead.","zh":"種子流失暗示前方有問題。"},{"en":"Climate change creates problems ahead for farmers.","zh":"氣候變化為農民造成未來問題。"},{"en":"A narrow crop base means problems ahead.","zh":"作物基礎狹窄意味前方有問題。"},{"en":"Experts warn of problems ahead if diversity continues to decline.","zh":"專家警告，如果多樣性繼續下降，將有未來問題。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":8},{"front":"for some time","meaning":"一段時間以來","examples":[{"en":"We have heard about rainforest loss for some time.","zh":"一段時間以來，我們一直聽到熱帶雨林流失的消息。"},{"en":"Scientists have warned about crop diversity for some time.","zh":"一段時間以來，科學家一直警告作物多樣性問題。"},{"en":"Seed savers have worked on this issue for some time.","zh":"一段時間以來，種子保存者一直處理這個問題。"},{"en":"Consumers have discussed local food for some time.","zh":"一段時間以來，消費者一直討論本地食物。"},{"en":"The decline has been happening for some time.","zh":"這種下降已經發生了一段時間。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":8},{"front":"loss of flora and fauna","meaning":"動植物群的流失","examples":[{"en":"People hear about the loss of flora and fauna in rainforests.","zh":"人們聽到熱帶雨林中動植物群的流失。"},{"en":"The loss of flora and fauna is widely discussed.","zh":"動植物群的流失受到廣泛討論。"},{"en":"Food diversity loss is less discussed than the loss of flora and fauna.","zh":"食物多樣性流失較少被討論，不如動植物群的流失受關注。"},{"en":"Rainforest destruction causes loss of flora and fauna.","zh":"熱帶雨林破壞導致動植物群的流失。"},{"en":"The loss of flora and fauna is a major environmental issue.","zh":"動植物群的流失是重大環境問題。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":8},{"front":"rainforests","meaning":"熱帶雨林","examples":[{"en":"Species loss in rainforests is widely reported.","zh":"熱帶雨林中的物種流失受到廣泛報道。"},{"en":"Rainforests contain enormous biodiversity.","zh":"熱帶雨林包含龐大生物多樣性。"},{"en":"Plants are disappearing from rainforests.","zh":"植物正從熱帶雨林中消失。"},{"en":"People often know more about rainforests than food diversity.","zh":"人們通常比食物多樣性更了解熱帶雨林。"},{"en":"Protecting rainforests and protecting seeds are both important.","zh":"保護熱帶雨林和保護種子都很重要。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":8},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, little is said about food diversity.","zh":"相比之下，很少有人談論食物多樣性。"},{"en":"Rainforest loss is well known; by contrast, crop loss is overlooked.","zh":"熱帶雨林流失廣為人知；相比之下，作物流失被忽視。"},{"en":"Supermarkets look full; by contrast, seed diversity is shrinking.","zh":"超市看似貨品充足；相比之下，種子多樣性正在萎縮。"},{"en":"Modern produce travels well; by contrast, heirloom crops often taste better.","zh":"現代農產品適合運輸；相比之下，傳統作物通常味道更好。"},{"en":"Farmers’ markets sell varied crops; by contrast, supermarkets sell uniform produce.","zh":"農夫市場出售多樣作物；相比之下，超市出售一致農產品。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":8},{"front":"parallel decline","meaning":"同時發生的下降","examples":[{"en":"There is a parallel decline in the diversity of foods we eat.","zh":"我們所吃食物的多樣性正在同時下降。"},{"en":"The loss of wild species is matched by a parallel decline in food varieties.","zh":"野生物種流失伴隨着食物品種同時下降。"},{"en":"A parallel decline is happening in farms and forests.","zh":"農場和森林中正發生同時下降。"},{"en":"The passage highlights a parallel decline that many people ignore.","zh":"文章強調許多人忽視的同時下降。"},{"en":"Seed savers are trying to stop this parallel decline.","zh":"種子保存者正努力阻止這種同時下降。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":9},{"front":"diversity of the foods we eat","meaning":"我們所吃食物的多樣性","examples":[{"en":"The diversity of the foods we eat is declining.","zh":"我們所吃食物的多樣性正在下降。"},{"en":"Seed banks protect the diversity of the foods we eat.","zh":"種子庫保護我們所吃食物的多樣性。"},{"en":"Supermarkets may hide the loss of diversity of the foods we eat.","zh":"超市可能掩蓋我們所吃食物的多樣性流失。"},{"en":"Farmers’ markets can increase the diversity of the foods we eat.","zh":"農夫市場可以增加我們所吃食物的多樣性。"},{"en":"Climate change threatens the diversity of the foods we eat.","zh":"氣候變化威脅我們所吃食物的多樣性。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":9},{"front":"extinction of food varieties","meaning":"食物品種滅絕","examples":[{"en":"The extinction of food varieties is happening worldwide.","zh":"食物品種滅絕正在世界各地發生。"},{"en":"Seed savers work against the extinction of food varieties.","zh":"種子保存者努力對抗食物品種滅絕。"},{"en":"The extinction of food varieties reduces future choices.","zh":"食物品種滅絕減少未來選擇。"},{"en":"Disease may speed up the extinction of food varieties.","zh":"疾病可能加速食物品種滅絕。"},{"en":"Public awareness of the extinction of food varieties remains limited.","zh":"公眾對食物品種滅絕的意識仍然有限。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":9},{"front":"all over the world","meaning":"世界各地","examples":[{"en":"Food varieties are disappearing all over the world.","zh":"食物品種正在世界各地消失。"},{"en":"Seed banks exist all over the world.","zh":"種子庫存在於世界各地。"},{"en":"Farmers all over the world face climate change.","zh":"世界各地的農民都面對氣候變化。"},{"en":"Wheat is grown all over the world.","zh":"小麥在世界各地種植。"},{"en":"People all over the world depend on a handful of crops.","zh":"世界各地的人依賴少數幾種作物。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":9},{"front":"happen fast","meaning":"迅速發生","examples":[{"en":"The extinction of food varieties is happening fast.","zh":"食物品種滅絕正在迅速發生。"},{"en":"Crop disease can happen fast across large fields.","zh":"作物疾病可以在大片田地中迅速發生。"},{"en":"Climate damage may happen fast in vulnerable regions.","zh":"氣候損害可能在脆弱地區迅速發生。"},{"en":"Seed loss can happen fast when farmers stop growing a variety.","zh":"當農民停止種植某品種時，種子流失可能迅速發生。"},{"en":"Changes in modern agriculture often happen fast.","zh":"現代農業的變化常迅速發生。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":9},{"front":"an estimated 90 percent","meaning":"估計百分之九十","examples":[{"en":"An estimated 90 percent of historic varieties are no longer grown.","zh":"估計百分之九十的歷史品種已不再被種植。"},{"en":"An estimated 90 percent of wheat lacks defense against Ug99.","zh":"估計百分之九十的小麥對Ug99沒有防禦能力。"},{"en":"An estimated 90 percent shows the scale of the problem.","zh":"估計百分之九十顯示問題規模。"},{"en":"Scientists warned that an estimated 90 percent may be vulnerable.","zh":"科學家警告，估計百分之九十可能很脆弱。"},{"en":"An estimated 90 percent is not exact, but it is alarming.","zh":"估計百分之九十並非精確數字，但令人警惕。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":9},{"front":"historic fruit and vegetable varieties","meaning":"歷史悠久的蔬果品種","examples":[{"en":"Many historic fruit and vegetable varieties are no longer grown.","zh":"許多歷史悠久的蔬果品種已不再被種植。"},{"en":"Seed savers try to protect historic fruit and vegetable varieties.","zh":"種子保存者試圖保護歷史悠久的蔬果品種。"},{"en":"Historic fruit and vegetable varieties may have special flavors.","zh":"歷史悠久的蔬果品種可能有特殊味道。"},{"en":"Farmers once cultivated many historic fruit and vegetable varieties.","zh":"農民過去種植許多歷史悠久的蔬果品種。"},{"en":"Losing historic fruit and vegetable varieties means losing food history.","zh":"失去歷史悠久的蔬果品種意味失去食物歷史。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":9},{"front":"no longer grown","meaning":"不再被種植","examples":[{"en":"Many old varieties are no longer grown.","zh":"許多古老品種不再被種植。"},{"en":"Some apples are no longer grown commercially.","zh":"有些蘋果不再被商業種植。"},{"en":"A crop may disappear if it is no longer grown.","zh":"如果作物不再被種植，它可能消失。"},{"en":"Seeds become rare when the plant is no longer grown.","zh":"當植物不再被種植時，種子會變得稀有。"},{"en":"The yearbook helps revive varieties that are no longer grown.","zh":"年鑑幫助復興不再被種植的品種。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":9},{"front":"apple varieties","meaning":"蘋果品種","examples":[{"en":"Thousands of apple varieties were once grown in the United States.","zh":"美國過去曾種植數以千計的蘋果品種。"},{"en":"Fewer than a hundred old apple varieties remain.","zh":"古老蘋果品種剩下不足一百種。"},{"en":"Apple varieties differ in flavor, color and storage ability.","zh":"蘋果品種在味道、顏色和儲存能力上不同。"},{"en":"Seed savers record old apple varieties.","zh":"種子保存者記錄古老蘋果品種。"},{"en":"Modern supermarkets sell only a few apple varieties.","zh":"現代超市只出售少數蘋果品種。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":9},{"front":"fewer than a hundred remain","meaning":"剩下不足一百種","examples":[{"en":"Of the old apple varieties, fewer than a hundred remain.","zh":"古老蘋果品種中，剩下不足一百種。"},{"en":"Fewer than a hundred remain after years of agricultural change.","zh":"經過多年農業變化後，剩下不足一百種。"},{"en":"Experts worry because fewer than a hundred remain.","zh":"專家擔心，因為剩下不足一百種。"},{"en":"If fewer than a hundred remain, diversity is seriously reduced.","zh":"如果剩下不足一百種，多樣性已嚴重減少。"},{"en":"The phrase “fewer than a hundred remain” shows dramatic loss.","zh":"「剩下不足一百種」這個短語顯示巨大流失。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":9},{"front":"thousands of varieties of rice","meaning":"數以千計的稻米品種","examples":[{"en":"The Philippines once had thousands of varieties of rice.","zh":"菲律賓曾有數以千計的稻米品種。"},{"en":"Thousands of varieties of rice once thrived in local fields.","zh":"數以千計的稻米品種曾在本地田地蓬勃生長。"},{"en":"Seed loss reduced thousands of varieties of rice to far fewer.","zh":"種子流失使數以千計的稻米品種減少到少得多。"},{"en":"Farmers preserved thousands of varieties of rice through traditional farming.","zh":"農民透過傳統耕作保存數以千計的稻米品種。"},{"en":"Climate change may make thousands of varieties of rice important again.","zh":"氣候變化可能令數以千計的稻米品種再次重要。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":9},{"front":"once thrived","meaning":"曾經蓬勃生長","examples":[{"en":"Thousands of rice varieties once thrived in the Philippines.","zh":"數以千計的稻米品種曾在菲律賓蓬勃生長。"},{"en":"Many wheat varieties once thrived in China.","zh":"許多小麥品種曾在中國蓬勃生長。"},{"en":"Old vegetables once thrived in local gardens.","zh":"古老蔬菜曾在本地花園中蓬勃生長。"},{"en":"Crops that once thrived may now be rare.","zh":"曾經蓬勃生長的作物現在可能很稀有。"},{"en":"Seed banks preserve varieties that once thrived.","zh":"種子庫保存曾經蓬勃生長的品種。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":9},{"front":"wheat varieties","meaning":"小麥品種","examples":[{"en":"Many wheat varieties cultivated in China have disappeared.","zh":"中國種植過的許多小麥品種已經消失。"},{"en":"Wheat varieties differ in disease resistance.","zh":"小麥品種在抗病能力上不同。"},{"en":"Ug99 threatens modern wheat varieties.","zh":"Ug99威脅現代小麥品種。"},{"en":"Seed banks may contain old wheat varieties.","zh":"種子庫可能保存古老小麥品種。"},{"en":"Farmers need diverse wheat varieties for future security.","zh":"農民需要多樣化小麥品種來保障未來。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":9},{"front":"cultivate","meaning":"種植；培育","examples":[{"en":"China once cultivated many wheat varieties.","zh":"中國曾種植許多小麥品種。"},{"en":"Farmers cultivate crops suited to local conditions.","zh":"農民種植適合本地環境的作物。"},{"en":"It takes skill to cultivate heirloom vegetables.","zh":"培育傳統品種蔬菜需要技術。"},{"en":"Communities cultivate traditional plants for food and culture.","zh":"社區種植傳統植物作食物和文化用途。"},{"en":"Modern farms often cultivate fewer varieties than before.","zh":"現代農場通常比以前種植更少品種。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":10},{"front":"have disappeared","meaning":"已經消失","examples":[{"en":"Many wheat varieties have disappeared.","zh":"許多小麥品種已經消失。"},{"en":"Old apple varieties have disappeared from farms.","zh":"古老蘋果品種已經從農場消失。"},{"en":"Traditional foods have disappeared from supermarkets.","zh":"傳統食物已經從超市消失。"},{"en":"Some rice varieties have disappeared forever.","zh":"有些稻米品種已經永遠消失。"},{"en":"Experts worry that more crops have disappeared than people realize.","zh":"專家擔心消失的作物比人們意識到的更多。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":10},{"front":"experts estimate that","meaning":"專家估計","examples":[{"en":"Experts estimate that more than half of food varieties have been lost.","zh":"專家估計超過一半食物品種已經流失。"},{"en":"Experts estimate that wheat faces serious risk from Ug99.","zh":"專家估計小麥面臨Ug99的嚴重風險。"},{"en":"Experts estimate that population will continue to grow.","zh":"專家估計人口將繼續增長。"},{"en":"Experts estimate that food production must increase greatly.","zh":"專家估計糧食產量必須大幅增加。"},{"en":"Experts estimate that seed diversity is declining rapidly.","zh":"專家估計種子多樣性正在迅速下降。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":10},{"front":"in total","meaning":"總計","examples":[{"en":"In total, more than 50 percent of food varieties have been lost.","zh":"總計，超過百分之五十的食物品種已經流失。"},{"en":"In total, thousands of seeds are stored at the farm.","zh":"總計，農場儲存數以千計的種子。"},{"en":"The exchange has more than 13,000 members in total.","zh":"交流會總計有超過13,000名會員。"},{"en":"In total, the yearbook lists many kinds of crops.","zh":"總計，年鑑列出許多種類的作物。"},{"en":"In total, the losses are greater than most people imagine.","zh":"總計，這些流失比大多數人想像的更大。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":10},{"front":"more than 50 percent","meaning":"超過百分之五十","examples":[{"en":"More than 50 percent of food varieties have disappeared.","zh":"超過百分之五十的食物品種已經消失。"},{"en":"More than 50 percent is a serious loss.","zh":"超過百分之五十是嚴重流失。"},{"en":"Experts estimate that more than 50 percent has been lost.","zh":"專家估計已有超過百分之五十流失。"},{"en":"More than 50 percent of historic diversity may be gone.","zh":"超過百分之五十的歷史多樣性可能已消失。"},{"en":"Losing more than 50 percent of varieties reduces resilience.","zh":"失去超過百分之五十的品種會降低韌性。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":10},{"front":"over the past century","meaning":"在過去一個世紀","examples":[{"en":"Many food varieties have disappeared over the past century.","zh":"許多食物品種在過去一個世紀已經消失。"},{"en":"Agriculture has changed greatly over the past century.","zh":"農業在過去一個世紀發生巨大變化。"},{"en":"Supermarkets have become more uniform over the past century.","zh":"超市在過去一個世紀變得更加一致。"},{"en":"Seed diversity declined over the past century.","zh":"種子多樣性在過去一個世紀下降。"},{"en":"Modern farming expanded over the past century.","zh":"現代農業在過去一個世紀擴展。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":10},{"front":"if disease or future climate change affects","meaning":"如果疾病或未來氣候變化影響","examples":[{"en":"If disease or future climate change affects key crops, food supply may suffer.","zh":"如果疾病或未來氣候變化影響主要作物，食物供應可能受損。"},{"en":"If disease or future climate change affects wheat, millions could be at risk.","zh":"如果疾病或未來氣候變化影響小麥，數百萬人可能受威脅。"},{"en":"If disease or future climate change affects rice, old varieties may be needed.","zh":"如果疾病或未來氣候變化影響稻米，可能需要古老品種。"},{"en":"If disease or future climate change affects modern crops, diversity becomes crucial.","zh":"如果疾病或未來氣候變化影響現代作物，多樣性便變得關鍵。"},{"en":"If disease or future climate change affects food production, seed banks may help.","zh":"如果疾病或未來氣候變化影響糧食生產，種子庫可能有幫助。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":10},{"front":"a handful of plants","meaning":"少數幾種植物","examples":[{"en":"Humans depend on a handful of plants to feed the planet.","zh":"人類依賴少數幾種植物養活地球。"},{"en":"A handful of plants provide much of the world’s calories.","zh":"少數幾種植物提供世界大部分熱量。"},{"en":"Relying on a handful of plants is risky.","zh":"依賴少數幾種植物是有風險的。"},{"en":"Disease can threaten a handful of plants at once.","zh":"疾病可以同時威脅少數幾種植物。"},{"en":"Seed banks protect alternatives to a handful of plants.","zh":"種子庫保護少數幾種植物以外的替代選擇。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":10},{"front":"come to depend on","meaning":"逐漸變得依賴","examples":[{"en":"We have come to depend on a small number of crops.","zh":"我們逐漸變得依賴少數作物。"},{"en":"Modern agriculture has come to depend on uniform varieties.","zh":"現代農業逐漸依賴一致品種。"},{"en":"Consumers have come to depend on supermarkets.","zh":"消費者逐漸依賴超市。"},{"en":"Many countries have come to depend on wheat and rice.","zh":"許多國家逐漸依賴小麥和稻米。"},{"en":"Food systems have come to depend on technology-driven solutions.","zh":"食物系統逐漸依賴由科技推動的方案。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":10},{"front":"feed our growing planet","meaning":"養活人口增長中的地球","examples":[{"en":"A small number of crops feed our growing planet.","zh":"少數幾種作物養活人口增長中的地球。"},{"en":"Future farmers must feed our growing planet under climate pressure.","zh":"未來農民必須在氣候壓力下養活人口增長中的地球。"},{"en":"Old varieties may help feed our growing planet.","zh":"古老品種可能幫助養活人口增長中的地球。"},{"en":"Higher yields are needed to feed our growing planet.","zh":"需要更高產量來養活人口增長中的地球。"},{"en":"Seed diversity gives us more ways to feed our growing planet.","zh":"種子多樣性給我們更多方法養活人口增長中的地球。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":10},{"front":"desperately need","meaning":"迫切需要","examples":[{"en":"We may desperately need varieties that have disappeared.","zh":"我們可能迫切需要已消失的品種。"},{"en":"Farmers desperately need disease-resistant wheat.","zh":"農民迫切需要抗病小麥。"},{"en":"The world may desperately need more food by 2045.","zh":"到2045年，世界可能迫切需要更多食物。"},{"en":"Scientists desperately need access to old seeds.","zh":"科學家迫切需要取得古老種子。"},{"en":"Communities desperately need crops that can survive drought.","zh":"社區迫切需要能抵抗乾旱的作物。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":10},{"front":"let something become extinct","meaning":"任由……滅絕","examples":[{"en":"We have let many useful varieties become extinct.","zh":"我們任由許多有用品種滅絕。"},{"en":"Society should not let old seeds become extinct.","zh":"社會不應任由古老種子滅絕。"},{"en":"Farmers may let a crop become extinct by no longer growing it.","zh":"農民若不再種植某作物，可能任由它滅絕。"},{"en":"It is dangerous to let food varieties become extinct.","zh":"任由食物品種滅絕是危險的。"},{"en":"Seed savers work so we do not let traditional crops become extinct.","zh":"種子保存者努力工作，使我們不會任由傳統作物滅絕。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":10},{"front":"cereal diversity","meaning":"穀物多樣性","examples":[{"en":"The loss of cereal diversity is a serious concern.","zh":"穀物多樣性流失是嚴重問題。"},{"en":"Cereal diversity includes different varieties of wheat, rice and other grains.","zh":"穀物多樣性包括不同小麥、稻米和其他穀物品種。"},{"en":"Seed banks help preserve cereal diversity.","zh":"種子庫幫助保存穀物多樣性。"},{"en":"Disease threatens cereal diversity worldwide.","zh":"疾病威脅全球穀物多樣性。"},{"en":"Food security depends partly on cereal diversity.","zh":"糧食安全部分取決於穀物多樣性。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":10},{"front":"a particular cause for concern","meaning":"特別令人關注的原因","examples":[{"en":"The loss of cereal diversity is a particular cause for concern.","zh":"穀物多樣性流失是特別令人關注的原因。"},{"en":"Ug99 is a particular cause for concern among wheat scientists.","zh":"Ug99是小麥科學家特別關注的原因。"},{"en":"Climate change is a particular cause for concern for farmers.","zh":"氣候變化是農民特別關注的原因。"},{"en":"Dependence on few crops is a particular cause for concern.","zh":"依賴少數作物是特別令人關注的原因。"},{"en":"The decline in old varieties is a particular cause for concern.","zh":"古老品種減少是特別令人關注的原因。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":11},{"front":"fungus","meaning":"真菌","examples":[{"en":"A fungus called Ug99 is spreading across wheat crops.","zh":"一種名為Ug99的真菌正蔓延至小麥作物。"},{"en":"This fungus can damage wheat severely.","zh":"這種真菌可以嚴重損害小麥。"},{"en":"Scientists are searching for wheat resistant to the fungus.","zh":"科學家正在尋找能抵抗該真菌的小麥。"},{"en":"A dangerous fungus may threaten global food supply.","zh":"危險真菌可能威脅全球食物供應。"},{"en":"The fungus was first identified in Uganda.","zh":"這種真菌首次在烏干達被識別。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":11},{"front":"be first identified in","meaning":"首次在……被識別","examples":[{"en":"Ug99 was first identified in Uganda in 1999.","zh":"Ug99於1999年首次在烏干達被識別。"},{"en":"The disease was first identified in a wheat field.","zh":"該疾病首次在一片小麥田中被識別。"},{"en":"A new crop threat may be first identified in one country.","zh":"新作物威脅可能首先在某一國家被識別。"},{"en":"The fungus was first identified in East Africa.","zh":"這種真菌首次在東非被識別。"},{"en":"Scientists record where diseases are first identified.","zh":"科學家記錄疾病首次在哪裏被識別。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":11},{"front":"spread across","meaning":"蔓延至整個……","examples":[{"en":"The fungus is spreading across wheat crops.","zh":"這種真菌正蔓延至小麥作物。"},{"en":"Disease can spread across countries quickly.","zh":"疾病可以迅速蔓延至多個國家。"},{"en":"Ug99 may spread across Asia.","zh":"Ug99可能蔓延至亞洲。"},{"en":"Climate effects spread across farming regions.","zh":"氣候影響蔓延至農業地區。"},{"en":"Modern crop systems allow pests to spread across large areas.","zh":"現代作物系統使害蟲能蔓延至大片地區。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":11},{"front":"wheat crops","meaning":"小麥作物","examples":[{"en":"Ug99 threatens the world’s wheat crops.","zh":"Ug99威脅世界小麥作物。"},{"en":"Wheat crops feed millions of people.","zh":"小麥作物養活數百萬人。"},{"en":"Farmers inspect wheat crops for signs of disease.","zh":"農民檢查小麥作物是否有疾病跡象。"},{"en":"Climate change can reduce wheat crops.","zh":"氣候變化可以減少小麥作物。"},{"en":"Resistant wheat crops are urgently needed.","zh":"迫切需要具抗性的小麥作物。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":11},{"front":"jump the Persian Gulf","meaning":"跨越波斯灣","examples":[{"en":"By 2007, the fungus had jumped the Persian Gulf into Iran.","zh":"到2007年，這種真菌已跨越波斯灣進入伊朗。"},{"en":"A plant disease can jump the Persian Gulf through wind or trade.","zh":"植物疾病可以透過風或貿易跨越波斯灣。"},{"en":"Scientists worried when Ug99 jumped the Persian Gulf.","zh":"當Ug99跨越波斯灣時，科學家感到擔憂。"},{"en":"Once the fungus jumped the Persian Gulf, Asia seemed at risk.","zh":"真菌一旦跨越波斯灣，亞洲似乎面臨風險。"},{"en":"The ability to jump the Persian Gulf showed its danger.","zh":"能夠跨越波斯灣顯示其危險性。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":11},{"front":"predict that","meaning":"預測","examples":[{"en":"Scientists predict that the fungus will spread further.","zh":"科學家預測這種真菌會進一步蔓延。"},{"en":"Experts predict that food demand will rise.","zh":"專家預測食物需求會上升。"},{"en":"Researchers predict that climate change will affect yields.","zh":"研究人員預測氣候變化會影響產量。"},{"en":"Many analysts predict that seed banks will become more important.","zh":"許多分析人士預測種子庫會變得更重要。"},{"en":"Farmers predict that old varieties may return.","zh":"農民預測古老品種可能回歸。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":11},{"front":"make its way into","meaning":"逐漸進入","examples":[{"en":"The fungus may make its way into India and Pakistan.","zh":"這種真菌可能逐漸進入印度和巴基斯坦。"},{"en":"A disease can make its way into new farming regions.","zh":"疾病可以逐漸進入新的農業地區。"},{"en":"Rare produce can make its way into farmers’ markets.","zh":"稀有農產品可以逐漸進入農夫市場。"},{"en":"Old varieties may make their way into modern gardens.","zh":"古老品種可能逐漸進入現代花園。"},{"en":"Ug99 could make its way into major wheat-growing countries.","zh":"Ug99可能逐漸進入主要小麥種植國。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":11},{"front":"eventually","meaning":"最終","examples":[{"en":"The fungus may eventually reach the United States.","zh":"這種真菌最終可能傳到美國。"},{"en":"Old seeds may eventually prove useful.","zh":"古老種子最終可能證明有用。"},{"en":"Food diversity may eventually become a major public issue.","zh":"食物多樣性最終可能成為重大公共議題。"},{"en":"The population may eventually reach nine billion.","zh":"人口最終可能達到九十億。"},{"en":"If varieties disappear, we may eventually regret losing them.","zh":"如果品種消失，我們最終可能後悔失去它們。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":11},{"front":"roughly 90 percent","meaning":"大約百分之九十","examples":[{"en":"Roughly 90 percent of the world’s wheat has no defense against Ug99.","zh":"世界上大約百分之九十的小麥對Ug99沒有防禦能力。"},{"en":"Roughly 90 percent means about nine out of ten.","zh":"大約百分之九十表示十個中約有九個。"},{"en":"Roughly 90 percent of historic varieties may be gone.","zh":"大約百分之九十的歷史品種可能已消失。"},{"en":"The figure of roughly 90 percent alarms scientists.","zh":"大約百分之九十這個數字令科學家警惕。"},{"en":"If roughly 90 percent is vulnerable, the danger is enormous.","zh":"如果大約百分之九十都脆弱，危險便十分巨大。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":11},{"front":"have no defense against","meaning":"對……沒有防禦能力","examples":[{"en":"Most wheat has no defense against this fungus.","zh":"大多數小麥對這種真菌沒有防禦能力。"},{"en":"Crops with little diversity may have no defense against new diseases.","zh":"多樣性不足的作物可能對新疾病沒有防禦能力。"},{"en":"A plant may have no defense against unfamiliar pests.","zh":"植物可能對陌生害蟲沒有防禦能力。"},{"en":"Modern wheat may have no defense against Ug99.","zh":"現代小麥可能對Ug99沒有防禦能力。"},{"en":"Seed banks may contain varieties that are not without defense against disease.","zh":"種子庫可能保存對疾病並非沒有防禦能力的品種。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":11},{"front":"particular fungus","meaning":"這種特定真菌","examples":[{"en":"This particular fungus threatens most wheat crops.","zh":"這種特定真菌威脅大多數小麥作物。"},{"en":"Scientists are studying this particular fungus closely.","zh":"科學家正在仔細研究這種特定真菌。"},{"en":"This particular fungus was first identified in Uganda.","zh":"這種特定真菌首次在烏干達被識別。"},{"en":"Farmers fear this particular fungus because it spreads quickly.","zh":"農民害怕這種特定真菌，因為它蔓延迅速。"},{"en":"Resistant varieties may help fight this particular fungus.","zh":"抗性品種可能幫助對抗這種特定真菌。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":11},{"front":"reach the United States","meaning":"傳到美國","examples":[{"en":"The fungus may eventually reach the United States.","zh":"這種真菌最終可能傳到美國。"},{"en":"If Ug99 reached the United States, many crops would be at risk.","zh":"如果Ug99傳到美國，許多作物會處於危險中。"},{"en":"Scientists are worried it could reach the United States.","zh":"科學家擔心它可能傳到美國。"},{"en":"A disease can reach the United States through global movement.","zh":"疾病可以透過全球流動傳到美國。"},{"en":"The passage discusses what might happen if the fungus reached the United States.","zh":"文章討論如果真菌傳到美國可能會發生甚麼。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":11},{"front":"an estimated one billion dollars’ worth of","meaning":"估計價值十億美元的……","examples":[{"en":"An estimated one billion dollars’ worth of crops would be at risk.","zh":"估計價值十億美元的作物會處於危險中。"},{"en":"Disease could destroy an estimated one billion dollars’ worth of wheat.","zh":"疾病可能摧毀估計價值十億美元的小麥。"},{"en":"An estimated one billion dollars’ worth of food production may be threatened.","zh":"估計價值十億美元的糧食生產可能受威脅。"},{"en":"The report mentions an estimated one billion dollars’ worth of crops.","zh":"報告提到估計價值十億美元的作物。"},{"en":"Losing an estimated one billion dollars’ worth of harvests would be serious.","zh":"失去估計價值十億美元的收成會很嚴重。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":12},{"front":"be at risk","meaning":"處於危險中","examples":[{"en":"One billion dollars’ worth of crops would be at risk.","zh":"價值十億美元的作物會處於危險中。"},{"en":"Wheat supplies may be at risk from Ug99.","zh":"小麥供應可能因Ug99而處於危險中。"},{"en":"Food security is at risk when diversity declines.","zh":"當多樣性下降時，糧食安全處於危險中。"},{"en":"Old varieties are at risk if farmers stop planting them.","zh":"如果農民停止種植，古老品種會處於危險中。"},{"en":"Millions of people could be at risk during a famine.","zh":"饑荒期間，數百萬人可能處於危險中。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":12},{"front":"in danger","meaning":"處於危險中","examples":[{"en":"Scientists believe the portion currently in danger is enormous.","zh":"科學家認為目前處於危險中的部分十分龐大。"},{"en":"Wheat crops in several regions are in danger.","zh":"幾個地區的小麥作物處於危險中。"},{"en":"Food diversity is in danger worldwide.","zh":"食物多樣性在世界各地處於危險中。"},{"en":"Old seed varieties are in danger of disappearing.","zh":"古老種子品種處於消失的危險中。"},{"en":"People may be in danger if their primary food source fails.","zh":"如果主要食物來源失敗，人們可能處於危險中。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":12},{"front":"primary food source","meaning":"主要食物來源","examples":[{"en":"One billion people could lose their primary food source.","zh":"十億人可能失去主要食物來源。"},{"en":"Wheat is a primary food source for many communities.","zh":"小麥是許多社區的主要食物來源。"},{"en":"Rice is the primary food source in many countries.","zh":"稻米是許多國家的主要食物來源。"},{"en":"Losing a primary food source can lead to famine.","zh":"失去主要食物來源可能導致饑荒。"},{"en":"Seed diversity protects people who depend on one primary food source.","zh":"種子多樣性保護依賴單一主要食物來源的人。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":12},{"front":"famine","meaning":"饑荒","examples":[{"en":"A famine with serious consequences could follow.","zh":"隨後可能出現具有嚴重後果的饑荒。"},{"en":"Crop failure can lead to famine.","zh":"作物歉收可以導致饑荒。"},{"en":"Disease in wheat fields may cause famine.","zh":"小麥田中的疾病可能造成饑荒。"},{"en":"Seed diversity can reduce the risk of famine.","zh":"種子多樣性可以降低饑荒風險。"},{"en":"A major famine would have humanitarian consequences.","zh":"大規模饑荒會帶來人道後果。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":12},{"front":"significant humanitarian consequences","meaning":"重大人道後果","examples":[{"en":"A famine could have significant humanitarian consequences.","zh":"饑荒可能帶來重大人道後果。"},{"en":"Crop disease may create significant humanitarian consequences.","zh":"作物疾病可能造成重大人道後果。"},{"en":"Losing a primary food source has significant humanitarian consequences.","zh":"失去主要食物來源具有重大人道後果。"},{"en":"Food shortages with significant humanitarian consequences must be prevented.","zh":"必須防止具有重大人道後果的食物短缺。"},{"en":"Scientists warn of significant humanitarian consequences if Ug99 spreads.","zh":"科學家警告，如果Ug99蔓延，將有重大人道後果。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":12},{"front":"be expected to reach","meaning":"預計達到","examples":[{"en":"The world population is expected to reach nine billion.","zh":"世界人口預計達到九十億。"},{"en":"Food demand is expected to reach new highs.","zh":"食物需求預計達到新高。"},{"en":"Wheat losses could be expected to reach dangerous levels.","zh":"小麥損失可能預計達到危險水平。"},{"en":"The project is expected to reach more farmers next year.","zh":"該項目預計明年惠及更多農民。"},{"en":"Global seed awareness is expected to reach wider audiences.","zh":"全球種子意識預計將接觸更廣泛受眾。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":12},{"front":"nine billion","meaning":"九十億","examples":[{"en":"The population may reach nine billion by 2045.","zh":"到2045年，人口可能達到九十億。"},{"en":"Feeding nine billion people will require more food.","zh":"養活九十億人需要更多食物。"},{"en":"Nine billion is a huge number of mouths to feed.","zh":"九十億是需要養活的龐大人口。"},{"en":"Experts discuss how to feed nine billion people.","zh":"專家討論如何養活九十億人。"},{"en":"Food production must increase for a world of nine billion.","zh":"面對九十億人口的世界，糧食產量必須增加。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":12},{"front":"by 2045","meaning":"到2045年","examples":[{"en":"The world’s population may reach nine billion by 2045.","zh":"世界人口到2045年可能達到九十億。"},{"en":"Food production may need to double by 2045.","zh":"到2045年，糧食產量可能需要翻倍。"},{"en":"Climate pressure could intensify by 2045.","zh":"到2045年，氣候壓力可能加劇。"},{"en":"Farmers must prepare for higher demand by 2045.","zh":"農民必須為到2045年更高的需求作準備。"},{"en":"Seed diversity may become even more important by 2045.","zh":"到2045年，種子多樣性可能變得更加重要。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":12},{"front":"double our food production","meaning":"令糧食產量增加一倍","examples":[{"en":"Some experts say we must double our food production.","zh":"有些專家說我們必須令糧食產量增加一倍。"},{"en":"To feed nine billion people, we may need to double our food production.","zh":"為養活九十億人，我們可能需要令糧食產量增加一倍。"},{"en":"Climate change makes it harder to double our food production.","zh":"氣候變化使令糧食產量增加一倍更困難。"},{"en":"Increasing yield may help double our food production.","zh":"提高產量可能幫助令糧食產量增加一倍。"},{"en":"Old varieties could contribute to efforts to double our food production.","zh":"古老品種可能對令糧食產量增加一倍的努力有貢獻。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":12},{"front":"keep up with","meaning":"跟上","examples":[{"en":"Food production must keep up with population growth.","zh":"糧食生產必須跟上人口增長。"},{"en":"Farmers struggle to keep up with demand.","zh":"農民努力跟上需求。"},{"en":"Seed research must keep up with new diseases.","zh":"種子研究必須跟上新疾病。"},{"en":"Technology alone may not keep up with climate change.","zh":"單靠科技可能無法跟上氣候變化。"},{"en":"Crop yields must rise to keep up with future needs.","zh":"作物產量必須提高以跟上未來需求。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":12},{"front":"population growth","meaning":"人口增長","examples":[{"en":"Population growth increases demand for food.","zh":"人口增長增加食物需求。"},{"en":"Food production must respond to population growth.","zh":"糧食生產必須應對人口增長。"},{"en":"Population growth places pressure on agriculture.","zh":"人口增長對農業施加壓力。"},{"en":"Climate change and population growth create a difficult challenge.","zh":"氣候變化和人口增長造成艱難挑戰。"},{"en":"Experts link future food shortages to population growth.","zh":"專家把未來食物短缺與人口增長聯繫起來。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":12},{"front":"given the added challenge of","meaning":"鑑於……這項額外挑戰","examples":[{"en":"Given the added challenge of climate change, food production is under pressure.","zh":"鑑於氣候變化這項額外挑戰，糧食生產承受壓力。"},{"en":"Given the added challenge of disease, seed diversity is vital.","zh":"鑑於疾病這項額外挑戰，種子多樣性十分重要。"},{"en":"Given the added challenge of population growth, yield must rise.","zh":"鑑於人口增長這項額外挑戰，產量必須提高。"},{"en":"Given the added challenge of limited varieties, old seeds matter.","zh":"鑑於品種有限這項額外挑戰，古老種子很重要。"},{"en":"Given the added challenge of drought, farmers need resilient crops.","zh":"鑑於乾旱這項額外挑戰，農民需要具韌性的作物。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":12},{"front":"ever more urgent","meaning":"越來越迫切","examples":[{"en":"It is becoming ever more urgent to increase food yield.","zh":"增加糧食產量正變得越來越迫切。"},{"en":"Seed preservation is becoming ever more urgent.","zh":"種子保存正變得越來越迫切。"},{"en":"Fighting Ug99 is ever more urgent.","zh":"對抗Ug99越來越迫切。"},{"en":"Protecting crop diversity is ever more urgent under climate change.","zh":"在氣候變化下，保護作物多樣性越來越迫切。"},{"en":"Public awareness of food loss is ever more urgent.","zh":"提高公眾對食物流失的意識越來越迫切。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":13},{"front":"increase food yield","meaning":"增加糧食產量","examples":[{"en":"Scientists need ways to increase food yield.","zh":"科學家需要方法增加糧食產量。"},{"en":"Old varieties may help increase food yield in harsh climates.","zh":"古老品種可能幫助在惡劣氣候中增加糧食產量。"},{"en":"Farmers use better techniques to increase food yield.","zh":"農民使用更好技術來增加糧食產量。"},{"en":"Increasing seed diversity could help increase food yield.","zh":"增加種子多樣性可能有助增加糧食產量。"},{"en":"The pressure to increase food yield will grow by 2045.","zh":"到2045年，增加糧食產量的壓力將會增長。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":13},{"front":"food yield","meaning":"糧食產量","examples":[{"en":"Food yield must rise to meet future demand.","zh":"糧食產量必須提高以滿足未來需求。"},{"en":"Climate change can reduce food yield.","zh":"氣候變化可以降低糧食產量。"},{"en":"Farmers measure food yield after harvest.","zh":"農民在收成後量度糧食產量。"},{"en":"Disease-resistant crops may improve food yield.","zh":"抗病作物可能改善糧食產量。"},{"en":"Technology-driven agriculture often focuses on food yield.","zh":"科技推動型農業常集中於糧食產量。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":13},{"front":"increasingly dependent upon","meaning":"越來越依賴","examples":[{"en":"The world has become increasingly dependent upon technology-driven agriculture.","zh":"世界越來越依賴科技推動型農業。"},{"en":"Farmers are increasingly dependent upon a few crop varieties.","zh":"農民越來越依賴少數作物品種。"},{"en":"Consumers are increasingly dependent upon supermarkets.","zh":"消費者越來越依賴超市。"},{"en":"Food systems are increasingly dependent upon global transport.","zh":"食物系統越來越依賴全球運輸。"},{"en":"Modern agriculture is increasingly dependent upon uniform seeds.","zh":"現代農業越來越依賴一致種子。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":13},{"front":"technology-driven","meaning":"由科技推動的","examples":[{"en":"Modern food production often uses a technology-driven approach.","zh":"現代糧食生產常使用由科技推動的方法。"},{"en":"A technology-driven system can increase yields quickly.","zh":"由科技推動的系統可以快速提高產量。"},{"en":"Technology-driven farming may overlook seed diversity.","zh":"由科技推動的農業可能忽視種子多樣性。"},{"en":"The passage questions a purely technology-driven solution.","zh":"文章質疑純粹由科技推動的解決方案。"},{"en":"A technology-driven approach should be balanced with traditional knowledge.","zh":"由科技推動的方法應與傳統知識取得平衡。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":13},{"front":"one-size-fits-all approach","meaning":"一刀切的方法","examples":[{"en":"The world has adopted a one-size-fits-all approach to food supply.","zh":"世界已採用一刀切的方法處理食物供應。"},{"en":"A one-size-fits-all approach may ignore local conditions.","zh":"一刀切的方法可能忽視本地環境。"},{"en":"Seed diversity challenges the one-size-fits-all approach.","zh":"種子多樣性挑戰一刀切的方法。"},{"en":"Farmers need local solutions, not only a one-size-fits-all approach.","zh":"農民需要本地方案，而不只是一刀切的方法。"},{"en":"Climate change makes a one-size-fits-all approach risky.","zh":"氣候變化令一刀切的方法有風險。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":13},{"front":"food supply","meaning":"食物供應","examples":[{"en":"Seed diversity is important for food supply.","zh":"種子多樣性對食物供應很重要。"},{"en":"Disease can threaten food supply.","zh":"疾病可以威脅食物供應。"},{"en":"Future food supply depends on resilient crops.","zh":"未來食物供應取決於具韌性的作物。"},{"en":"Climate change places pressure on food supply.","zh":"氣候變化對食物供應施加壓力。"},{"en":"Preserving old varieties may protect food supply.","zh":"保存古老品種可能保護食物供應。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":13},{"front":"best hope for","meaning":"……的最大希望","examples":[{"en":"Old varieties may be the best hope for securing our food’s future.","zh":"古老品種可能是確保我們食物未來的最大希望。"},{"en":"Seed banks are the best hope for preserving rare crops.","zh":"種子庫是保存稀有作物的最大希望。"},{"en":"Disease-resistant seeds may be the best hope for farmers.","zh":"抗病種子可能是農民的最大希望。"},{"en":"Local knowledge is sometimes the best hope for adaptation.","zh":"本地知識有時是適應環境的最大希望。"},{"en":"Diversity may be our best hope for future food security.","zh":"多樣性可能是我們未來糧食安全的最大希望。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":13},{"front":"securing our food’s future","meaning":"確保我們食物的未來","examples":[{"en":"Preserving traditional foods may help in securing our food’s future.","zh":"保存傳統食物可能有助確保我們食物的未來。"},{"en":"Seed diversity is central to securing our food’s future.","zh":"種子多樣性是確保我們食物的未來的核心。"},{"en":"Scientists and farmers must work together on securing our food’s future.","zh":"科學家和農民必須合作確保我們食物的未來。"},{"en":"Old crop varieties may be essential for securing our food’s future.","zh":"古老作物品種可能對確保我們食物的未來至關重要。"},{"en":"The passage argues that securing our food’s future requires looking backward.","zh":"文章認為，確保我們食物的未來需要回望過去。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":13},{"front":"depend on our ability to","meaning":"取決於我們……的能力","examples":[{"en":"The future of food may depend on our ability to preserve old varieties.","zh":"食物的未來可能取決於我們保存古老品種的能力。"},{"en":"Survival may depend on our ability to adapt crops.","zh":"生存可能取決於我們使作物適應環境的能力。"},{"en":"Food security can depend on our ability to maintain seed diversity.","zh":"糧食安全可能取決於我們維持種子多樣性的能力。"},{"en":"Success will depend on our ability to respond to disease.","zh":"成功將取決於我們應對疾病的能力。"},{"en":"Future harvests may depend on our ability to use traditional seeds.","zh":"未來收成可能取決於我們使用傳統種子的能力。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":13},{"front":"locally cultivated foods","meaning":"本地栽培的食物","examples":[{"en":"Locally cultivated foods of the past may help future food supply.","zh":"過去本地栽培的食物可能幫助未來食物供應。"},{"en":"Farmers’ markets often sell locally cultivated foods.","zh":"農夫市場常出售本地栽培的食物。"},{"en":"Locally cultivated foods are adapted to local conditions.","zh":"本地栽培的食物適應本地環境。"},{"en":"Preserving locally cultivated foods protects regional culture.","zh":"保存本地栽培的食物能保護地區文化。"},{"en":"Climate change may renew interest in locally cultivated foods.","zh":"氣候變化可能重新激發人們對本地栽培食物的興趣。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":13},{"front":"foods of the past","meaning":"過去的食物","examples":[{"en":"The foods of the past may be important for the future.","zh":"過去的食物可能對未來很重要。"},{"en":"Seed savers protect the foods of the past.","zh":"種子保存者保護過去的食物。"},{"en":"Farmers are rediscovering foods of the past.","zh":"農民正在重新發現過去的食物。"},{"en":"Foods of the past can contain useful genetic traits.","zh":"過去的食物可以含有有用基因特徵。"},{"en":"The passage suggests that foods of the past may secure food’s future.","zh":"文章指出過去的食物可能確保食物的未來。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":13},{"front":"agree with the views of the writer","meaning":"與作者觀點一致","examples":[{"en":"Students decide whether statements agree with the views of the writer.","zh":"學生判斷陳述是否與作者觀點一致。"},{"en":"A statement may agree with the views of the writer even if the wording changes.","zh":"即使用詞改變，陳述仍可能與作者觀點一致。"},{"en":"Read carefully to see if the answer agrees with the views of the writer.","zh":"仔細閱讀，以判斷答案是否與作者觀點一致。"},{"en":"The task asks whether each claim agrees with the views of the writer.","zh":"題目要求判斷每項說法是否與作者觀點一致。"},{"en":"Do not use outside opinions when judging whether statements agree with the views of the writer.","zh":"判斷陳述是否與作者觀點一致時，不要使用外部意見。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":13},{"front":"Reading Passage","meaning":"閱讀文章","examples":[{"en":"The statements are based on the Reading Passage.","zh":"這些陳述根據閱讀文章。"},{"en":"Students should read the Reading Passage before answering.","zh":"學生應先閱讀文章再作答。"},{"en":"The Reading Passage discusses future food supply.","zh":"閱讀文章討論未來食物供應。"},{"en":"Answers must come from the Reading Passage.","zh":"答案必須來自閱讀文章。"},{"en":"The Reading Passage includes examples from Heritage Farm.","zh":"閱讀文章包括傳承農場的例子。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":14},{"front":"answer sheet","meaning":"答題紙","examples":[{"en":"Students write their answers on the answer sheet.","zh":"學生把答案寫在答題紙上。"},{"en":"The answer sheet must be filled in clearly.","zh":"答題紙必須清楚填寫。"},{"en":"Write TRUE, FALSE or NOT GIVEN on the answer sheet.","zh":"在答題紙上寫TRUE、FALSE或NOT GIVEN。"},{"en":"Check the answer sheet before time ends.","zh":"時間結束前檢查答題紙。"},{"en":"The answer sheet records the final responses.","zh":"答題紙記錄最終答案。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":14},{"front":"if the statement agrees with","meaning":"如果陳述與……一致","examples":[{"en":"Write TRUE if the statement agrees with the information.","zh":"如果陳述與資料一致，寫TRUE。"},{"en":"Choose TRUE if the statement agrees with the writer’s view.","zh":"如果陳述與作者觀點一致，選TRUE。"},{"en":"If the statement agrees with the passage, it is correct.","zh":"如果陳述與文章一致，它就是正確的。"},{"en":"Students must decide if the statement agrees with the text.","zh":"學生必須判斷陳述是否與文本一致。"},{"en":"A paraphrase may still be true if the statement agrees with the meaning.","zh":"如果陳述與意思一致，改寫句仍可能正確。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":14},{"front":"contradicts the information","meaning":"與資料相矛盾","examples":[{"en":"Students write FALSE if the statement contradicts the information.","zh":"如果陳述與資料相矛盾，學生寫FALSE。"},{"en":"The statement contradicts the information about seed storage.","zh":"該陳述與種子儲存資料相矛盾。"},{"en":"A wrong date may contradict the information in the passage.","zh":"錯誤日期可能與文章資料相矛盾。"},{"en":"If an answer contradicts the information, it cannot be TRUE.","zh":"如果答案與資料相矛盾，就不可能是TRUE。"},{"en":"Saying donated seeds are stored outdoors contradicts the information.","zh":"說捐贈種子存放在戶外與資料相矛盾。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":14},{"front":"there is no information on this","meaning":"沒有關於這方面的資料","examples":[{"en":"Students write NOT GIVEN if there is no information on this.","zh":"如果沒有關於這方面的資料，學生寫NOT GIVEN。"},{"en":"There is no information on this in the passage.","zh":"文章沒有關於這方面的資料。"},{"en":"If there is no information on this, do not infer too much.","zh":"如果沒有關於這方面的資料，不要過度推斷。"},{"en":"The statement may be NOT GIVEN because there is no information on this detail.","zh":"該陳述可能是NOT GIVEN，因為沒有關於這個細節的資料。"},{"en":"There is no information on this, even though the topic is related.","zh":"即使主題相關，也沒有關於這方面的資料。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":14},{"front":"nearby farms","meaning":"附近農場","examples":[{"en":"Heritage Farm is different from most nearby farms.","zh":"傳承農場與大多數附近農場不同。"},{"en":"Nearby farms mainly grow corn and soybeans.","zh":"附近農場主要種植粟米和大豆。"},{"en":"The nearby farms are intensively cultivated.","zh":"附近農場進行集約耕作。"},{"en":"Seed diversity is less visible on nearby farms.","zh":"附近農場較少看到種子多樣性。"},{"en":"Visitors compare Heritage Farm with nearby farms.","zh":"遊客把傳承農場與附近農場比較。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":14},{"front":"stored outdoors","meaning":"存放在戶外","examples":[{"en":"Donated seeds are not stored outdoors.","zh":"捐贈種子不是存放在戶外。"},{"en":"Seeds stored outdoors may be damaged by weather.","zh":"存放在戶外的種子可能被天氣損壞。"},{"en":"The statement asks whether seeds are stored outdoors.","zh":"該陳述詢問種子是否存放在戶外。"},{"en":"Seed banks usually avoid keeping rare seeds stored outdoors.","zh":"種子庫通常避免把稀有種子存放在戶外。"},{"en":"The passage says seeds are stored in coolers, not stored outdoors.","zh":"文章說種子存放在冷藏室，而不是存放在戶外。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":14},{"front":"choose which heirloom seeds to grow","meaning":"選擇種植哪些傳統種子","examples":[{"en":"The statement asks whether Diane and her husband choose which heirloom seeds to grow.","zh":"該陳述詢問Diane和丈夫是否選擇種植哪些傳統種子。"},{"en":"Farmers may choose which heirloom seeds to grow each season.","zh":"農民每季可能選擇種植哪些傳統種子。"},{"en":"Members can choose which heirloom seeds to grow from the yearbook.","zh":"會員可以從年鑑中選擇種植哪些傳統種子。"},{"en":"Gardeners choose which heirloom seeds to grow based on climate.","zh":"園丁根據氣候選擇種植哪些傳統種子。"},{"en":"Seed savers must choose which heirloom seeds to grow for preservation.","zh":"種子保存者必須選擇種植哪些傳統種子以作保存。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":14},{"front":"listed alphabetically","meaning":"按字母次序列出","examples":[{"en":"The question asks whether the seeds are listed alphabetically.","zh":"問題詢問種子是否按字母次序列出。"},{"en":"Items listed alphabetically are arranged from A to Z.","zh":"按字母次序列出的項目由A到Z排列。"},{"en":"A yearbook may be easier to use if seeds are listed alphabetically.","zh":"如果種子按字母次序列出，年鑑可能更易使用。"},{"en":"The passage does not clearly say the seeds are listed alphabetically.","zh":"文章沒有清楚說種子按字母次序列出。"},{"en":"Students must check whether varieties are listed alphabetically.","zh":"學生必須檢查品種是否按字母次序列出。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":14},{"front":"describe how each seed was obtained","meaning":"描述每種種子如何取得","examples":[{"en":"The yearbook may describe how each seed was obtained.","zh":"年鑑可能描述每種種子如何取得。"},{"en":"Seed histories describe how each seed was obtained.","zh":"種子歷史描述每種種子如何取得。"},{"en":"Members often describe how each seed was obtained from family or travel.","zh":"會員常描述每種種子如何從家庭或旅行中取得。"},{"en":"It is useful to describe how each seed was obtained.","zh":"描述每種種子如何取得很有用。"},{"en":"The passage includes examples that describe how each seed was obtained.","zh":"文章包括描述每種種子如何取得的例子。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":14},{"front":"complete the notes below","meaning":"完成以下筆記","examples":[{"en":"Students complete the notes below using words from the passage.","zh":"學生使用文章中的詞語完成以下筆記。"},{"en":"Complete the notes below with one word and/or a number.","zh":"用一個字及／或一個數字完成以下筆記。"},{"en":"Read the summary before you complete the notes below.","zh":"在完成以下筆記前，先閱讀摘要。"},{"en":"To complete the notes below, locate key facts in the passage.","zh":"要完成以下筆記，需在文章中找出關鍵事實。"},{"en":"Candidates must complete the notes below accurately.","zh":"考生必須準確完成以下筆記。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":14},{"front":"one word and/or a number","meaning":"一個字及／或一個數字","examples":[{"en":"Students choose one word and/or a number from the passage.","zh":"學生從文章中選擇一個字及／或一個數字。"},{"en":"The answer may be one word and/or a number.","zh":"答案可以是一個字及／或一個數字。"},{"en":"Do not write more than one word and/or a number.","zh":"不要寫超過一個字及／或一個數字。"},{"en":"The instruction allows one word and/or a number only.","zh":"指示只允許一個字及／或一個數字。"},{"en":"A correct answer must fit the limit of one word and/or a number.","zh":"正確答案必須符合一個字及／或一個數字的限制。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":14},{"front":"The Food We Grow and Eat","meaning":"我們種植和食用的食物","examples":[{"en":"The Food We Grow and Eat summarises the passage’s main ideas.","zh":"「我們種植和食用的食物」總結文章主要觀點。"},{"en":"The notes are titled The Food We Grow and Eat.","zh":"筆記題標題是「我們種植和食用的食物」。"},{"en":"The Food We Grow and Eat focuses on crop varieties.","zh":"「我們種植和食用的食物」集中於作物品種。"},{"en":"Students use the passage to complete The Food We Grow and Eat.","zh":"學生使用文章完成「我們種植和食用的食物」。"},{"en":"The Food We Grow and Eat includes facts about supermarkets and disease.","zh":"「我們種植和食用的食物」包括關於超市和疾病的事實。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":14},{"front":"travel well","meaning":"適合長途運輸","examples":[{"en":"Supermarkets sell fruit and vegetables that travel well.","zh":"超市出售適合長途運輸的蔬果。"},{"en":"Produce that travels well can survive long-distance transport.","zh":"適合長途運輸的農產品能承受遠距離運輸。"},{"en":"Heirloom tomatoes often do not travel well.","zh":"傳統品種番茄通常不適合長途運輸。"},{"en":"Modern apples are bred to travel well.","zh":"現代蘋果被培育成適合長途運輸。"},{"en":"Flavor may be sacrificed so produce can travel well.","zh":"味道可能被犧牲，以便農產品適合長途運輸。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":15},{"front":"be uniform in appearance","meaning":"外觀一致","examples":[{"en":"Supermarkets want fruit and vegetables to be uniform in appearance.","zh":"超市希望蔬果外觀一致。"},{"en":"Modern produce is bred to be uniform in appearance.","zh":"現代農產品被培育成外觀一致。"},{"en":"Heirloom vegetables are not always uniform in appearance.","zh":"傳統品種蔬菜並不總是外觀一致。"},{"en":"Crops that are uniform in appearance are easier to sell.","zh":"外觀一致的作物更容易出售。"},{"en":"Being uniform in appearance does not guarantee better flavor.","zh":"外觀一致並不保證味道更好。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":15},{"front":"public awareness","meaning":"公眾意識","examples":[{"en":"Public awareness of food-variety loss remains limited.","zh":"公眾對食物品種流失的意識仍然有限。"},{"en":"Public awareness can support seed-saving campaigns.","zh":"公眾意識可以支持種子保存運動。"},{"en":"Farmers’ markets help raise public awareness.","zh":"農夫市場幫助提高公眾意識。"},{"en":"Public awareness of climate change is growing.","zh":"公眾對氣候變化的意識正在提高。"},{"en":"The passage tries to increase public awareness of food diversity.","zh":"文章試圖提高公眾對食物多樣性的意識。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":15},{"front":"plants are disappearing from","meaning":"植物正從……消失","examples":[{"en":"People know that plants are disappearing from rainforests.","zh":"人們知道植物正從熱帶雨林中消失。"},{"en":"Plants are disappearing from many natural habitats.","zh":"植物正從許多自然棲息地中消失。"},{"en":"Traditional crops are disappearing from farms.","zh":"傳統作物正從農場中消失。"},{"en":"Old varieties are disappearing from supermarkets.","zh":"古老品種正從超市中消失。"},{"en":"Seeds are disappearing from local gardens when no one saves them.","zh":"如果無人保存，種子正從本地花園中消失。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":15},{"front":"decline in fruit and vegetable varieties","meaning":"蔬果品種減少","examples":[{"en":"Few people know about the decline in fruit and vegetable varieties.","zh":"很少人知道蔬果品種減少。"},{"en":"The decline in fruit and vegetable varieties is happening quickly.","zh":"蔬果品種減少正在迅速發生。"},{"en":"Seed banks respond to the decline in fruit and vegetable varieties.","zh":"種子庫應對蔬果品種減少。"},{"en":"Supermarket uniformity contributes to the decline in fruit and vegetable varieties.","zh":"超市一致化促成蔬果品種減少。"},{"en":"Public awareness of the decline in fruit and vegetable varieties must improve.","zh":"公眾對蔬果品種減少的意識必須提高。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":15},{"front":"current problems in food production","meaning":"目前糧食生產問題","examples":[{"en":"Ug99 is one of the current problems in food production.","zh":"Ug99是目前糧食生產問題之一。"},{"en":"Climate change creates current problems in food production.","zh":"氣候變化造成目前糧食生產問題。"},{"en":"Disease and uniform crops are current problems in food production.","zh":"疾病和一致作物是目前糧食生產問題。"},{"en":"The passage explains several current problems in food production.","zh":"文章解釋了幾個目前糧食生產問題。"},{"en":"Seed diversity may help solve current problems in food production.","zh":"種子多樣性可能幫助解決目前糧食生產問題。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":15},{"front":"attack wheat","meaning":"攻擊小麥","examples":[{"en":"A particular fungus can attack wheat.","zh":"一種特定真菌可以攻擊小麥。"},{"en":"Ug99 is known to attack wheat crops.","zh":"Ug99以攻擊小麥作物而聞名。"},{"en":"If disease continues to attack wheat, food supplies may suffer.","zh":"如果疾病繼續攻擊小麥，食物供應可能受損。"},{"en":"Scientists seek varieties that resist fungi that attack wheat.","zh":"科學家尋找能抵抗攻擊小麥真菌的品種。"},{"en":"A fungus that can attack wheat may threaten millions of people.","zh":"能攻擊小麥的真菌可能威脅數百萬人。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":15},{"front":"food supplies","meaning":"食物供應","examples":[{"en":"The threat to food supplies could lead to famine.","zh":"對食物供應的威脅可能導致饑荒。"},{"en":"Food supplies depend on healthy crops.","zh":"食物供應取決於健康作物。"},{"en":"Wheat disease can damage food supplies.","zh":"小麥疾病可以損害食物供應。"},{"en":"Climate change places pressure on food supplies.","zh":"氣候變化對食物供應施加壓力。"},{"en":"Seed banks help protect future food supplies.","zh":"種子庫幫助保護未來食物供應。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":15},{"front":"lead to a famine","meaning":"導致饑荒","examples":[{"en":"Rick Ward believes the threat could lead to a famine.","zh":"Rick Ward認為這種威脅可能導致饑荒。"},{"en":"Crop failure may lead to a famine.","zh":"作物歉收可能導致饑荒。"},{"en":"Losing a primary food source can lead to a famine.","zh":"失去主要食物來源可能導致饑荒。"},{"en":"A disease spreading through wheat could lead to a famine.","zh":"小麥疾病蔓延可能導致饑荒。"},{"en":"Experts fear that poor harvests may lead to a famine.","zh":"專家擔心收成不佳可能導致饑荒。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":15},{"front":"future food production","meaning":"未來糧食生產","examples":[{"en":"Future food production will face pressure from climate change.","zh":"未來糧食生產將面對氣候變化的壓力。"},{"en":"Seed diversity is important for future food production.","zh":"種子多樣性對未來糧食生產很重要。"},{"en":"Future food production may require old varieties.","zh":"未來糧食生產可能需要古老品種。"},{"en":"Population growth will increase demands on future food production.","zh":"人口增長會增加對未來糧食生產的需求。"},{"en":"Technology and traditional seeds may both shape future food production.","zh":"科技和傳統種子可能共同塑造未來糧食生產。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":15},{"front":"place pressure on","meaning":"對……施加壓力","examples":[{"en":"Climate change may place pressure on food production.","zh":"氣候變化可能對糧食生產施加壓力。"},{"en":"Population growth will place pressure on farmers.","zh":"人口增長會對農民施加壓力。"},{"en":"Disease can place pressure on wheat supplies.","zh":"疾病可以對小麥供應施加壓力。"},{"en":"Supermarket demands place pressure on growers.","zh":"超市需求對種植者施加壓力。"},{"en":"Future needs will place pressure on seed systems.","zh":"未來需求會對種子系統施加壓力。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":15},{"front":"twice as much food","meaning":"兩倍的食物","examples":[{"en":"Twice as much food may be required in the future.","zh":"未來可能需要兩倍的食物。"},{"en":"Feeding nine billion people may require twice as much food.","zh":"養活九十億人可能需要兩倍的食物。"},{"en":"Farmers may need to produce twice as much food by 2045.","zh":"到2045年，農民可能需要生產兩倍的食物。"},{"en":"Producing twice as much food will be difficult under climate change.","zh":"在氣候變化下，生產兩倍的食物會很困難。"},{"en":"Seed diversity may help us produce twice as much food.","zh":"種子多樣性可能幫助我們生產兩倍的食物。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":15},{"front":"growth in the population","meaning":"人口增長","examples":[{"en":"More food may be required because of growth in the population.","zh":"由於人口增長，可能需要更多食物。"},{"en":"Growth in the population increases pressure on farms.","zh":"人口增長增加農場壓力。"},{"en":"Future food supply must keep up with growth in the population.","zh":"未來食物供應必須跟上人口增長。"},{"en":"Growth in the population makes seed diversity more important.","zh":"人口增長使種子多樣性更加重要。"},{"en":"Experts link higher food demand to growth in the population.","zh":"專家把更高食物需求與人口增長聯繫起來。"}],"source":"Passage 2 Flash Cards 168 - Ensuring our future food supply.pdf","sourcePage":15}],"ielts/reading/passage-2/Practice 169":[{"front":"vibrant paintings and prints","meaning":"色彩鮮明的畫作和版畫","examples":[{"en":"Margaret Preston’s vibrant paintings and prints have delighted the Australian public.","zh":"Margaret Preston 色彩鮮明的畫作和版畫令澳洲公眾喜愛。"},{"en":"Her vibrant paintings and prints often feature strong colours and bold patterns.","zh":"她色彩鮮明的畫作和版畫常有強烈色彩和大膽圖案。"},{"en":"These vibrant paintings and prints helped make Australian flowers and landscapes popular subjects.","zh":"這些色彩鮮明的畫作和版畫令澳洲花卉和風景成為受歡迎題材。"},{"en":"Preston’s vibrant paintings and prints show her interest in colour, design, and national identity.","zh":"Preston 色彩鮮明的畫作和版畫顯示她對色彩、設計和民族身份的興趣。"},{"en":"The phrase describes the lively visual quality of her art.","zh":"這個詞組描述她藝術作品生動活潑的視覺特質。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":1},{"front":"Australian flowers, animals and landscapes","meaning":"澳洲花卉、動物和風景","examples":[{"en":"Her art often features Australian flowers, animals and landscapes.","zh":"她的藝術常以澳洲花卉、動物和風景為題材。"},{"en":"Australian flowers, animals and landscapes became important subjects in Preston’s work.","zh":"澳洲花卉、動物和風景成為 Preston 作品中的重要主題。"},{"en":"She used these subjects to create art with a distinctly Australian character.","zh":"她利用這些題材創作具有鮮明澳洲特色的藝術。"},{"en":"Native flowers were especially important in her paintings and prints.","zh":"本土花卉在她的畫作和版畫中特別重要。"},{"en":"The phrase summarises the natural themes in her art.","zh":"這個詞組概括她藝術中的自然主題。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":1},{"front":"delight the public","meaning":"令公眾喜愛","examples":[{"en":"Preston’s artworks have delighted the Australian public since the early 1920s.","zh":"Preston 的藝術作品自1920年代初以來一直令澳洲公眾喜愛。"},{"en":"To delight the public means to give people pleasure and admiration.","zh":"令公眾喜愛是指帶給人們愉悅和欣賞。"},{"en":"Her bright prints delighted viewers with their energy and design.","zh":"她鮮明的版畫以活力和設計感令觀眾喜愛。"},{"en":"Art can delight the public while also expressing serious ideas.","zh":"藝術既可以令公眾喜愛，也可以表達嚴肅思想。"},{"en":"The phrase shows the popularity of Preston’s work.","zh":"這個詞組顯示 Preston 作品的受歡迎程度。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":1},{"front":"since the early 1920s","meaning":"自1920年代初以來","examples":[{"en":"Her paintings and prints have been popular since the early 1920s.","zh":"她的畫作和版畫自1920年代初以來一直受歡迎。"},{"en":"Since the early 1920s means from that period until later times.","zh":"自1920年代初以來，是指從那段時期開始一直延續到後來。"},{"en":"Preston’s public reputation grew strongly since the early 1920s.","zh":"Preston 的公眾聲譽自1920年代初以來大幅提升。"},{"en":"Her works remained admired long after this period began.","zh":"她的作品在這段時期之後仍長期受到欣賞。"},{"en":"The phrase gives a historical starting point for her popularity.","zh":"這個詞組提供她受歡迎的歷史起點。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":1},{"front":"be born","meaning":"出生","examples":[{"en":"Margaret Preston was born Margaret Rose McPherson in Port Adelaide.","zh":"Margaret Preston 出生時名為 Margaret Rose McPherson，出生地是阿德萊德港。"},{"en":"To be born means to come into life at a particular time and place.","zh":"出生是指在某時間和地點來到世上。"},{"en":"She was born in South Australia before later living in Sydney.","zh":"她出生於南澳洲，後來住在悉尼。"},{"en":"Biographies often begin by saying where a person was born.","zh":"傳記通常先說明人物出生的地點。"},{"en":"The phrase introduces basic information about Preston’s early life.","zh":"這個詞組引出 Preston 早年生活的基本資料。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":1},{"front":"Port Adelaide","meaning":"阿德萊德港","examples":[{"en":"Margaret Preston was born in Port Adelaide, South Australia.","zh":"Margaret Preston 出生於南澳洲阿德萊德港。"},{"en":"Port Adelaide was Preston’s birthplace.","zh":"阿德萊德港是 Preston 的出生地。"},{"en":"Her early life began there before the family later moved.","zh":"她的早年生活從那裏開始，後來家庭搬遷。"},{"en":"The location connects her biography with South Australia.","zh":"這個地點把她的傳記與南澳洲連接起來。"},{"en":"The phrase identifies an important place in her life story.","zh":"這個詞組指出她人生故事中的重要地方。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":1},{"front":"South Australia","meaning":"南澳洲","examples":[{"en":"Port Adelaide is in South Australia.","zh":"阿德萊德港位於南澳洲。"},{"en":"South Australia is the Australian state where Preston was born.","zh":"南澳洲是 Preston 出生的澳洲州份。"},{"en":"Her connection with South Australia continued through her later return to Adelaide.","zh":"她後來回到阿德萊德，延續了與南澳洲的聯繫。"},{"en":"Preston studied and taught in South Australia after her father died.","zh":"父親去世後，Preston 在南澳洲學習和任教。"},{"en":"The phrase gives geographical context.","zh":"這個詞組提供地理背景。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":1},{"front":"the daughter of","meaning":"……的女兒","examples":[{"en":"Margaret Preston was the daughter of David McPherson and Prudence Lyle.","zh":"Margaret Preston 是 David McPherson 和 Prudence Lyle 的女兒。"},{"en":"The daughter of someone means that person’s female child.","zh":"某人的女兒是指那人的女性子女。"},{"en":"This phrase gives information about Preston’s parents.","zh":"這個詞組提供 Preston 父母的資料。"},{"en":"Her family background forms part of her early biography.","zh":"她的家庭背景是其早期傳記的一部分。"},{"en":"The phrase introduces a family relationship.","zh":"這個詞組引出家庭關係。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":1},{"front":"Scottish marine engineer","meaning":"蘇格蘭輪機工程師","examples":[{"en":"Her father was a Scottish marine engineer.","zh":"她的父親是一名蘇格蘭輪機工程師。"},{"en":"A Scottish marine engineer is an engineer from Scotland who works with ship machinery or marine systems.","zh":"蘇格蘭輪機工程師是來自蘇格蘭、從事船舶機械或海事系統工作的工程師。"},{"en":"Preston’s father’s occupation connected the family with technical maritime work.","zh":"Preston 父親的職業把家庭與海事技術工作連接起來。"},{"en":"This detail gives background about her family.","zh":"這個細節提供她家庭背景。"},{"en":"The phrase identifies her father’s nationality and profession.","zh":"這個詞組指出她父親的國籍和職業。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":1},{"front":"be sent at first to","meaning":"起初被送到……","examples":[{"en":"She and her sister were sent at first to a private school.","zh":"她和妹妹起初被送到一所私立學校。"},{"en":"Be sent at first to a place means initially be placed or taken there.","zh":"起初被送到某地，是指最初被安排或帶到那裏。"},{"en":"Margaret was sent at first to private education before later attending a public high school.","zh":"Margaret 起初被送到私立學校，後來就讀公立中學。"},{"en":"The phrase shows the first stage of her schooling.","zh":"這個詞組顯示她學校教育的第一階段。"},{"en":"It also suggests that her education changed as family circumstances changed.","zh":"它也暗示她的教育隨家庭情況改變而改變。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":1},{"front":"private school","meaning":"私立學校","examples":[{"en":"Margaret and her sister first attended a private school.","zh":"Margaret 和妹妹最初就讀私立學校。"},{"en":"A private school is a school not run directly by the public education system.","zh":"私立學校是不由公共教育系統直接營辦的學校。"},{"en":"Their early education began in a private school.","zh":"她們的早期教育在私立學校開始。"},{"en":"Later, Margaret attended a public high school in Sydney.","zh":"後來，Margaret 在悉尼就讀公立中學。"},{"en":"The phrase describes her first school setting.","zh":"這個詞組描述她最初的學校環境。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":1},{"front":"family circumstances changed","meaning":"家庭情況改變","examples":[{"en":"When family circumstances changed, her mother took the girls to Sydney.","zh":"當家庭情況改變時，她的母親帶兩個女孩到悉尼。"},{"en":"Family circumstances changed means the family situation became different.","zh":"家庭情況改變是指家庭處境變得不同。"},{"en":"The change affected where Margaret and her sister lived and studied.","zh":"這次改變影響 Margaret 和妹妹的居住及學習地點。"},{"en":"Family circumstances can influence a young person’s education.","zh":"家庭情況可以影響年輕人的教育。"},{"en":"The phrase explains why the family moved.","zh":"這個詞組解釋家庭搬遷的原因。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":2},{"front":"attend a public high school","meaning":"就讀公立中學","examples":[{"en":"Margaret attended a public high school in Sydney.","zh":"Margaret 在悉尼就讀公立中學。"},{"en":"To attend a public high school means to study at a government-supported secondary school.","zh":"就讀公立中學是指在政府支持的中學學習。"},{"en":"Her schooling changed after the family moved to Sydney.","zh":"家庭搬到悉尼後，她的學校教育改變。"},{"en":"Attending a public high school formed part of her early education.","zh":"就讀公立中學是她早期教育的一部分。"},{"en":"The phrase describes a stage in her school life.","zh":"這個詞組描述她求學生活的一個階段。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":2},{"front":"decide early in life to","meaning":"早年便決定……","examples":[{"en":"She decided early in life to become an artist.","zh":"她早年便決定成為藝術家。"},{"en":"Decide early in life to do something means make a major choice when young.","zh":"早年便決定做某事，是指年輕時作出重大選擇。"},{"en":"Preston decided early in life to follow an artistic career.","zh":"Preston 早年便決定走藝術道路。"},{"en":"Her early decision shaped her education and later work.","zh":"她的早期決定塑造了她的教育和後來作品。"},{"en":"The phrase shows strong purpose from a young age.","zh":"這個詞組顯示她年輕時已有明確目標。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":2},{"front":"become an artist","meaning":"成為藝術家","examples":[{"en":"Margaret decided early in life to become an artist.","zh":"Margaret 早年便決定成為藝術家。"},{"en":"To become an artist means to develop a career creating art.","zh":"成為藝術家是指發展創作藝術的事業。"},{"en":"She took lessons and enrolled in art schools to become an artist.","zh":"她上藝術課並入讀藝術學校，以成為藝術家。"},{"en":"Her later paintings and prints show the result of this ambition.","zh":"她後來的畫作和版畫顯示這個志向的成果。"},{"en":"The phrase states her chosen life direction.","zh":"這個詞組說明她選擇的人生方向。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":2},{"front":"take private art lessons","meaning":"上私人藝術課","examples":[{"en":"She took private art lessons before formal art training.","zh":"她在正式藝術訓練前上私人藝術課。"},{"en":"To take private art lessons means to study art with a private teacher.","zh":"上私人藝術課是指跟私人老師學習藝術。"},{"en":"These lessons helped prepare Preston for art school.","zh":"這些課程幫助 Preston 為藝術學校作準備。"},{"en":"Private art lessons were an early step in her artistic development.","zh":"私人藝術課是她藝術發展的早期一步。"},{"en":"The phrase describes informal training before institutional study.","zh":"這個詞組描述院校學習前的非正式訓練。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":2},{"front":"train for several months with","meaning":"跟隨……受訓數個月","examples":[{"en":"She trained for several months with Sydney landscape painter William Lister.","zh":"她跟隨悉尼風景畫家 William Lister 受訓數個月。"},{"en":"To train for several months with someone means to study under that person for a short period.","zh":"跟隨某人受訓數個月，是指在那人指導下學習一段短時間。"},{"en":"Preston trained with William Lister before entering formal art school.","zh":"Preston 在進入正式藝術學校前跟隨 William Lister 學習。"},{"en":"This training helped introduce her to landscape painting.","zh":"這段訓練幫助她接觸風景畫。"},{"en":"The phrase describes early artistic instruction.","zh":"這個詞組描述早期藝術指導。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":2},{"front":"landscape painter","meaning":"風景畫家","examples":[{"en":"William Lister was a Sydney landscape painter.","zh":"William Lister 是悉尼風景畫家。"},{"en":"A landscape painter creates artworks showing natural scenery.","zh":"風景畫家創作描繪自然景色的藝術作品。"},{"en":"Lister’s role as a landscape painter made him a suitable early teacher for Preston.","zh":"Lister 作為風景畫家，適合成為 Preston 的早期老師。"},{"en":"Landscape painting later remained relevant to Preston’s interest in Australian scenery.","zh":"風景畫後來仍與 Preston 對澳洲景色的興趣有關。"},{"en":"The phrase identifies an artist by subject matter.","zh":"這個詞組以題材識別藝術家。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":2},{"front":"enrol at","meaning":"入讀；註冊入學","examples":[{"en":"In 1893, Preston enrolled at the National Gallery of Victoria Art School.","zh":"1893年，Preston 入讀維多利亞國家美術館藝術學校。"},{"en":"To enrol at a school means to officially join it as a student.","zh":"入讀某學校是指正式成為該校學生。"},{"en":"Preston enrolled at a major art school to continue her training.","zh":"Preston 入讀一所重要藝術學校，繼續接受訓練。"},{"en":"Enrolling there marked a formal stage in her art education.","zh":"入讀該校標誌她藝術教育的正式階段。"},{"en":"The phrase describes official entry into study.","zh":"這個詞組描述正式開始學習。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":2},{"front":"National Gallery of Victoria Art School","meaning":"維多利亞國家美術館藝術學校","examples":[{"en":"Preston studied at the National Gallery of Victoria Art School.","zh":"Preston 在維多利亞國家美術館藝術學校學習。"},{"en":"The National Gallery of Victoria Art School was an important place in her formal training.","zh":"維多利亞國家美術館藝術學校是她正式訓練中的重要地方。"},{"en":"She enrolled there in 1893.","zh":"她於1893年入讀該校。"},{"en":"Her study there lasted just over four years.","zh":"她在那裏學習了剛超過四年。"},{"en":"The phrase identifies a key art institution in her education.","zh":"這個詞組指出她教育中的重要藝術機構。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":2},{"front":"study for just over","meaning":"學習了剛超過……","examples":[{"en":"She studied there for just over four years.","zh":"她在那裏學習了剛超過四年。"},{"en":"Study for just over a period means study for slightly more than that length of time.","zh":"學習了剛超過某段時間，是指學習時間稍多於該長度。"},{"en":"Preston studied for just over four years at the art school.","zh":"Preston 在藝術學校學習了剛超過四年。"},{"en":"The phrase gives an approximate but clear duration.","zh":"這個詞組提供大約但清楚的時間長度。"},{"en":"It helps describe the length of her formal training.","zh":"它有助描述她正式訓練的長短。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":2},{"front":"return to","meaning":"回到……","examples":[{"en":"After her father died, Margaret returned to Adelaide.","zh":"父親去世後，Margaret 回到阿德萊德。"},{"en":"To return to a place means to go back there.","zh":"回到某地是指返回那裏。"},{"en":"Preston returned to Adelaide for further study and teaching.","zh":"Preston 回到阿德萊德繼續學習和任教。"},{"en":"Returning there connected her again with South Australia.","zh":"回到那裏使她再次與南澳洲連接。"},{"en":"The phrase marks a movement back to an earlier place.","zh":"這個詞組標誌返回舊地。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":2},{"front":"study and then teach at","meaning":"先學習然後在……任教","examples":[{"en":"She returned to Adelaide to study and then teach at the Adelaide School of Design.","zh":"她回到阿德萊德，先在阿德萊德設計學校學習，然後在那裏任教。"},{"en":"Study and then teach at a school means first learn there and later work there as a teacher.","zh":"先學習然後在某校任教，是指先作為學生學習，後來成為教師。"},{"en":"Preston’s relationship with the school developed from student to teacher.","zh":"Preston 與該校的關係由學生發展為教師。"},{"en":"This shows her growing professional confidence.","zh":"這顯示她專業信心逐漸增長。"},{"en":"The phrase describes progression within one institution.","zh":"這個詞組描述在同一機構中的進展。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":3},{"front":"Adelaide School of Design","meaning":"阿德萊德設計學校","examples":[{"en":"Margaret taught at the Adelaide School of Design.","zh":"Margaret 在阿德萊德設計學校任教。"},{"en":"The Adelaide School of Design was part of Preston’s early professional life.","zh":"阿德萊德設計學校是 Preston 早期專業生活的一部分。"},{"en":"She studied there before teaching there.","zh":"她先在那裏學習，後來在那裏教學。"},{"en":"The school helped shape her early artistic development.","zh":"該校幫助塑造她早期藝術發展。"},{"en":"The phrase identifies an important Adelaide institution in her career.","zh":"這個詞組指出她事業中的重要阿德萊德機構。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":3},{"front":"early artwork","meaning":"早期藝術作品","examples":[{"en":"Her early artwork was influenced by the German aesthetic tradition.","zh":"她的早期藝術作品受德國美學傳統影響。"},{"en":"Early artwork means work created near the beginning of an artist’s career.","zh":"早期藝術作品是藝術家職業初期創作的作品。"},{"en":"Preston’s early artwork showed strong naturalism.","zh":"Preston 的早期藝術作品顯示強烈自然主義。"},{"en":"Later, her style became more decorative and experimental.","zh":"後來，她的風格變得更具裝飾性和實驗性。"},{"en":"The phrase refers to the first phase of her artistic production.","zh":"這個詞組指她藝術創作的第一階段。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":3},{"front":"be influenced by","meaning":"受……影響","examples":[{"en":"Her early artwork was influenced by the German aesthetic tradition.","zh":"她的早期藝術作品受德國美學傳統影響。"},{"en":"Be influenced by something means be shaped or affected by it.","zh":"受某事影響是指被它塑造或影響。"},{"en":"Preston was later influenced by Aboriginal art and Chinese art.","zh":"Preston 後來受澳洲原住民藝術和中國藝術影響。"},{"en":"Artistic styles often develop by being influenced by different traditions.","zh":"藝術風格常因受不同傳統影響而發展。"},{"en":"The phrase describes the source of creative impact.","zh":"這個詞組描述創作影響的來源。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":3},{"front":"German aesthetic tradition","meaning":"德國美學傳統","examples":[{"en":"The German aesthetic tradition influenced Preston’s early artwork.","zh":"德國美學傳統影響 Preston 的早期藝術作品。"},{"en":"This tradition encouraged realistic depictions of natural subjects.","zh":"這種傳統鼓勵對自然題材作寫實描繪。"},{"en":"Preston’s early work followed this naturalistic approach.","zh":"Preston 的早期作品遵循這種自然主義方法。"},{"en":"Later European study had little immediate impact on this naturalism.","zh":"後來的歐洲學習對這種自然主義起初影響不大。"},{"en":"The phrase names one early artistic influence.","zh":"這個詞組指出一項早期藝術影響。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":3},{"front":"subjects of the natural world","meaning":"自然界題材","examples":[{"en":"Subjects of the natural world were depicted realistically.","zh":"自然界題材被寫實地描繪。"},{"en":"Subjects of the natural world include plants, animals, and landscapes.","zh":"自然界題材包括植物、動物和風景。"},{"en":"Preston later made Australian native flowers important subjects.","zh":"Preston 後來把澳洲本土花卉變成重要題材。"},{"en":"Natural-world subjects helped her connect art with Australian identity.","zh":"自然界題材幫助她把藝術與澳洲身份連接。"},{"en":"The phrase describes the content of her early naturalistic work.","zh":"這個詞組描述她早期自然主義作品的內容。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":3},{"front":"be depicted in","meaning":"被描繪成……","examples":[{"en":"Natural subjects were depicted in a true-to-life manner.","zh":"自然題材被描繪成逼真的樣子。"},{"en":"Be depicted in a certain way means be shown or represented in that style.","zh":"被描繪成某種方式，是指以該風格呈現或表現。"},{"en":"Preston’s early flowers were depicted in a realistic way.","zh":"Preston 早期的花卉被描繪成寫實方式。"},{"en":"Later, her subjects were depicted more decoratively.","zh":"後來，她的題材被描繪得更具裝飾性。"},{"en":"The phrase describes artistic representation.","zh":"這個詞組描述藝術表現方式。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":3},{"front":"true-to-life manner","meaning":"逼真的方式","examples":[{"en":"The subjects were depicted in a true-to-life manner.","zh":"這些題材以逼真的方式描繪。"},{"en":"A true-to-life manner means a realistic and accurate way.","zh":"逼真的方式是指寫實而準確的方式。"},{"en":"Preston’s early naturalism involved painting nature in a true-to-life manner.","zh":"Preston 早期自然主義以逼真的方式描繪自然。"},{"en":"This style differed from her later bold patterns and symbolic elements.","zh":"這種風格不同於她後來的大膽圖案和象徵元素。"},{"en":"The phrase describes realistic artistic treatment.","zh":"這個詞組描述寫實的藝術處理。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":3},{"front":"first visit to Europe","meaning":"首次歐洲之行","examples":[{"en":"Margaret’s first visit to Europe had little impact on her naturalism.","zh":"Margaret 的首次歐洲之行對她的自然主義影響不大。"},{"en":"First visit to Europe means her earliest journey to European countries.","zh":"首次歐洲之行是指她第一次前往歐洲國家。"},{"en":"She studied in Paris during this period.","zh":"她在這段時期於巴黎學習。"},{"en":"The visit did not immediately change the naturalistic style of her work.","zh":"這次旅程沒有立即改變她作品中的自然主義風格。"},{"en":"The phrase marks an important travel event in her training.","zh":"這個詞組標誌她訓練中的重要旅行事件。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":3},{"front":"have little impact on","meaning":"對……影響不大","examples":[{"en":"Her studies in Paris had little impact on the naturalism in her work.","zh":"她在巴黎的學習對作品中的自然主義影響不大。"},{"en":"Have little impact on something means affect it only slightly.","zh":"對某事影響不大，是指只對它有輕微影響。"},{"en":"European study had little impact on her early naturalistic style.","zh":"歐洲學習對她早期自然主義風格影響不大。"},{"en":"Later experiences had a stronger effect on her art.","zh":"後來的經驗對她藝術影響更大。"},{"en":"The phrase describes limited influence.","zh":"這個詞組描述有限影響。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":3},{"front":"naturalism","meaning":"自然主義","examples":[{"en":"Naturalism dominated Preston’s early work.","zh":"自然主義主導 Preston 的早期作品。"},{"en":"Naturalism is an artistic approach that depicts subjects realistically.","zh":"自然主義是一種寫實描繪題材的藝術方法。"},{"en":"Her early naturalism focused on true-to-life representations of nature.","zh":"她早期自然主義集中於逼真呈現自然。"},{"en":"Preston later moved towards decorative design and symbolic forms.","zh":"Preston 後來轉向裝飾性設計和象徵形式。"},{"en":"The phrase names her early artistic style.","zh":"這個詞組指出她早期藝術風格。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":3},{"front":"dominate her work","meaning":"主導她的作品","examples":[{"en":"Naturalism dominated her work from this early period.","zh":"自然主義從這個早期階段起主導她的作品。"},{"en":"To dominate her work means to be the main style or influence in it.","zh":"主導她的作品是指成為其中主要風格或影響。"},{"en":"Naturalistic painting dominated Preston’s early artistic production.","zh":"自然主義繪畫主導 Preston 的早期藝術創作。"},{"en":"Later, Aboriginal and Chinese elements became more prominent.","zh":"後來，澳洲原住民和中國元素變得更突出。"},{"en":"The phrase describes a leading influence in an artist’s work.","zh":"這個詞組描述藝術家作品中的主要影響。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":4},{"front":"early period","meaning":"早期階段","examples":[{"en":"Naturalism was strong in her work from this early period.","zh":"自然主義在她早期階段的作品中很強。"},{"en":"Early period means the first stage of an artist’s career or development.","zh":"早期階段是指藝術家事業或發展的第一階段。"},{"en":"Preston’s early period was marked by realistic depictions of nature.","zh":"Preston 的早期階段以寫實描繪自然為特色。"},{"en":"Later periods showed more decorative and symbolic approaches.","zh":"後期階段呈現更具裝飾性和象徵性的方式。"},{"en":"The phrase helps divide her career into stages.","zh":"這個詞組有助把她的事業分成不同階段。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":4},{"front":"some eight years later","meaning":"大約八年後","examples":[{"en":"Some eight years later, she began to recognise new artistic possibilities.","zh":"大約八年後，她開始意識到新的藝術可能。"},{"en":"Some eight years later means about eight years after an earlier event.","zh":"大約八年後是指在之前某事件約八年之後。"},{"en":"Around this later time, her view of art began to change.","zh":"到這個較後時間，她對藝術的看法開始改變。"},{"en":"The phrase shows that artistic development took time.","zh":"這個詞組顯示藝術發展需要時間。"},{"en":"It marks a shift from naturalism toward decorative possibilities.","zh":"它標誌由自然主義轉向裝飾性可能的轉變。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":4},{"front":"begin to recognise","meaning":"開始意識到","examples":[{"en":"She began to recognise the decorative possibilities of art.","zh":"她開始意識到藝術的裝飾性可能。"},{"en":"Begin to recognise means start to understand or notice something.","zh":"開始意識到是指開始理解或注意到某事。"},{"en":"Preston began to recognise that art could be more than realistic depiction.","zh":"Preston 開始意識到藝術可以不只是寫實描繪。"},{"en":"This recognition influenced her later prints and designs.","zh":"這種認識影響她後來的版畫和設計。"},{"en":"The phrase describes a change in artistic awareness.","zh":"這個詞組描述藝術意識的轉變。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":4},{"front":"decorative possibilities of art","meaning":"藝術的裝飾性可能","examples":[{"en":"Preston began to recognise the decorative possibilities of art.","zh":"Preston 開始意識到藝術的裝飾性可能。"},{"en":"Decorative possibilities of art refer to pattern, colour, design, and visual arrangement.","zh":"藝術的裝飾性可能指圖案、色彩、設計和視覺安排。"},{"en":"This interest helped her move beyond strict naturalism.","zh":"這種興趣幫助她超越嚴格自然主義。"},{"en":"Her later prints often used decorative patterns and repetitions.","zh":"她後來的版畫常使用裝飾圖案和重複元素。"},{"en":"The phrase describes a new direction in her artistic thinking.","zh":"這個詞組描述她藝術思想的新方向。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":4},{"front":"outbreak of the First World War","meaning":"第一次世界大戰爆發","examples":[{"en":"With the outbreak of the First World War, Margaret travelled to England.","zh":"隨着第一次世界大戰爆發，Margaret 前往英國。"},{"en":"The outbreak of the First World War means the beginning of the war in 1914.","zh":"第一次世界大戰爆發是指1914年戰爭開始。"},{"en":"The war affected Preston’s travel and work in Europe.","zh":"戰爭影響 Preston 在歐洲的旅行和工作。"},{"en":"During this period, she continued her studies and taught servicemen.","zh":"在這段時期，她繼續學習並教授軍人。"},{"en":"The phrase gives historical context for her move to England.","zh":"這個詞組為她前往英國提供歷史背景。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":4},{"front":"travel to England","meaning":"前往英國","examples":[{"en":"Margaret travelled to England during the First World War.","zh":"Margaret 在第一次世界大戰期間前往英國。"},{"en":"To travel to England means to go there from another country.","zh":"前往英國是指從另一國到英國去。"},{"en":"Preston travelled to England and continued her artistic studies.","zh":"Preston 前往英國並繼續藝術學習。"},{"en":"Her time in England helped develop her interest in printmaking.","zh":"她在英國的時期幫助培養她對版畫的興趣。"},{"en":"The phrase describes an important period of overseas experience.","zh":"這個詞組描述一段重要海外經驗。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":4},{"front":"have exhibitions","meaning":"舉辦展覽","examples":[{"en":"In England, she had exhibitions and continued her art studies.","zh":"在英國，她舉辦展覽並繼續藝術學習。"},{"en":"To have exhibitions means to show artworks publicly.","zh":"舉辦展覽是指公開展示藝術作品。"},{"en":"Preston had exhibitions while developing her skills in England.","zh":"Preston 在英國發展技巧期間舉辦展覽。"},{"en":"Exhibitions helped present her work to viewers.","zh":"展覽幫助把她的作品呈現給觀眾。"},{"en":"The phrase describes public display of art.","zh":"這個詞組描述藝術的公開展示。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":4},{"front":"continue her studies of art","meaning":"繼續藝術學習","examples":[{"en":"She continued her studies of art while in England.","zh":"她在英國期間繼續藝術學習。"},{"en":"To continue her studies of art means to keep learning artistic skills and ideas.","zh":"繼續藝術學習是指持續學習藝術技巧和觀念。"},{"en":"Preston did not stop training after leaving Australia.","zh":"Preston 離開澳洲後並沒有停止訓練。"},{"en":"Her continued study helped broaden her artistic practice.","zh":"持續學習幫助拓寬她的藝術實踐。"},{"en":"The phrase describes ongoing artistic education.","zh":"這個詞組描述持續的藝術教育。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":4},{"front":"study pottery","meaning":"學習陶藝","examples":[{"en":"She studied pottery while developing her interest in printmaking.","zh":"她在培養版畫興趣的同時學習陶藝。"},{"en":"To study pottery means to learn how to make ceramic objects.","zh":"學習陶藝是指學習製作陶瓷物件。"},{"en":"Pottery study added craft knowledge to Preston’s artistic training.","zh":"陶藝學習為 Preston 的藝術訓練增添工藝知識。"},{"en":"Her interest in design may have been strengthened by such craft work.","zh":"這類工藝工作可能加強她對設計的興趣。"},{"en":"The phrase identifies one of her artistic studies in England.","zh":"這個詞組指出她在英國學習的一項藝術內容。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":4},{"front":"at the same time","meaning":"同時","examples":[{"en":"At the same time, she developed her interest in printmaking.","zh":"同時，她培養了對版畫製作的興趣。"},{"en":"At the same time means during the same period.","zh":"同時是指在相同時期。"},{"en":"Preston studied pottery and, at the same time, explored printmaking.","zh":"Preston 學習陶藝，同時探索版畫製作。"},{"en":"The phrase links two activities happening together.","zh":"這個詞組連接兩項同時發生的活動。"},{"en":"It shows that her artistic interests developed in parallel.","zh":"它顯示她的藝術興趣並行發展。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":4},{"front":"develop her interest in","meaning":"培養對……的興趣","examples":[{"en":"She developed her interest in various techniques of printmaking and design.","zh":"她培養了對各種版畫製作與設計技巧的興趣。"},{"en":"Develop her interest in something means gradually become more interested in it.","zh":"培養對某事的興趣是指逐漸對它更感興趣。"},{"en":"Preston developed her interest in printmaking while in England.","zh":"Preston 在英國期間培養了對版畫製作的興趣。"},{"en":"This interest became central to her later career.","zh":"這種興趣後來成為她事業的核心。"},{"en":"The phrase describes growing artistic curiosity.","zh":"這個詞組描述逐漸增長的藝術好奇心。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":5},{"front":"techniques of printmaking","meaning":"版畫製作技巧","examples":[{"en":"Preston developed her interest in techniques of printmaking.","zh":"Preston 培養了對版畫製作技巧的興趣。"},{"en":"Techniques of printmaking are methods used to create printed artworks.","zh":"版畫製作技巧是創作版畫作品的方法。"},{"en":"Later, she used methods such as stencilling.","zh":"後來，她使用模版印刷等方法。"},{"en":"Printmaking techniques allowed her to combine pattern, colour, and design.","zh":"版畫製作技巧讓她結合圖案、色彩和設計。"},{"en":"The phrase describes practical artistic methods.","zh":"這個詞組描述實用藝術方法。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":5},{"front":"printmaking and design","meaning":"版畫製作與設計","examples":[{"en":"She studied various techniques of printmaking and design.","zh":"她學習各種版畫製作與設計技巧。"},{"en":"Printmaking and design became important parts of Preston’s artistic practice.","zh":"版畫製作與設計成為 Preston 藝術實踐的重要部分。"},{"en":"Her later works show strong design structure.","zh":"她後來的作品顯示強烈設計結構。"},{"en":"Printmaking allowed her to create bold repeated patterns.","zh":"版畫製作讓她創造大膽重複圖案。"},{"en":"The phrase names two linked areas of artistic skill.","zh":"這個詞組指出兩個相連的藝術技能領域。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":5},{"front":"England’s West Country","meaning":"英格蘭西南部","examples":[{"en":"She taught basket-weaving in England’s West Country.","zh":"她在英格蘭西南部教授編籃工藝。"},{"en":"England’s West Country is a region in southwestern England.","zh":"英格蘭西南部是英國西南地區。"},{"en":"Preston worked there during the First World War period.","zh":"Preston 在第一次世界大戰期間於那裏工作。"},{"en":"Her teaching there was connected with a rehabilitation unit.","zh":"她在那裏的教學與康復中心有關。"},{"en":"The phrase identifies the location of one wartime activity.","zh":"這個詞組指出一項戰時活動的地點。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":5},{"front":"teach basket-weaving","meaning":"教授編籃工藝","examples":[{"en":"She taught basket-weaving at a rehabilitation unit.","zh":"她在康復中心教授編籃工藝。"},{"en":"To teach basket-weaving means to instruct others in making baskets by hand.","zh":"教授編籃工藝是指教人手工編製籃子。"},{"en":"Preston taught this craft to servicemen during the war period.","zh":"Preston 在戰爭時期向軍人教授這門工藝。"},{"en":"Basket-weaving was a practical craft activity.","zh":"編籃工藝是一種實用工藝活動。"},{"en":"The phrase describes one form of teaching she undertook in England.","zh":"這個詞組描述她在英國從事的一種教學工作。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":5},{"front":"rehabilitation unit","meaning":"康復中心","examples":[{"en":"She taught basket-weaving at a rehabilitation unit for servicemen.","zh":"她在軍人康復中心教授編籃工藝。"},{"en":"A rehabilitation unit helps people recover after injury, illness, or service.","zh":"康復中心幫助人們在受傷、患病或服役後恢復。"},{"en":"The unit where Preston taught was for servicemen.","zh":"Preston 任教的中心是為軍人而設。"},{"en":"Craft work may have supported recovery and training.","zh":"工藝工作可能有助復康和訓練。"},{"en":"The phrase identifies a wartime care setting.","zh":"這個詞組指出戰時照護場所。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":5},{"front":"servicemen","meaning":"軍人","examples":[{"en":"The rehabilitation unit was for servicemen.","zh":"這個康復中心是為軍人而設。"},{"en":"Servicemen are members of the armed forces.","zh":"軍人是武裝部隊成員。"},{"en":"Preston taught basket-weaving to servicemen in England.","zh":"Preston 在英國向軍人教授編籃工藝。"},{"en":"The war created a need for rehabilitation services for servicemen.","zh":"戰爭造成軍人復康服務的需要。"},{"en":"The phrase identifies the people she helped teach.","zh":"這個詞組指出她教導的對象。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":5},{"front":"on board a boat","meaning":"在船上","examples":[{"en":"She met William Preston on board a boat returning to Australia.","zh":"她在返回澳洲的船上遇見 William Preston。"},{"en":"On board a boat means on or inside a boat during travel.","zh":"在船上是指旅行期間在船隻上或船內。"},{"en":"Preston met her future husband while on board a ship.","zh":"Preston 在船上遇見未來丈夫。"},{"en":"The meeting happened during her return journey to Australia.","zh":"這次相遇發生在她返回澳洲途中。"},{"en":"The phrase describes the place where they met.","zh":"這個詞組描述他們相遇的地點。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":5},{"front":"returning to Australia","meaning":"返回澳洲途中","examples":[{"en":"She met William Preston while returning to Australia.","zh":"她在返回澳洲途中遇見 William Preston。"},{"en":"Returning to Australia means going back to Australia from another place.","zh":"返回澳洲途中是指從另一地回到澳洲的旅程中。"},{"en":"Her return journey changed her personal life because she met William.","zh":"她的回程改變了個人生活，因為她遇見 William。"},{"en":"After returning, she settled in Sydney after marriage.","zh":"回國後，她婚後定居悉尼。"},{"en":"The phrase describes the journey during which the meeting occurred.","zh":"這個詞組描述相遇發生的旅程。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":5},{"front":"wealthy businessman","meaning":"富有商人","examples":[{"en":"William Preston was a wealthy businessman.","zh":"William Preston 是一名富有商人。"},{"en":"A wealthy businessman is a man with business success and considerable money.","zh":"富有商人是指在商業上成功並擁有相當財富的男性。"},{"en":"William’s wealth helped provide a comfortable life in Mosman.","zh":"William 的財富幫助他們在 Mosman 過舒適生活。"},{"en":"His marriage to Margaret changed her surname to Preston.","zh":"Margaret 與他結婚後改姓 Preston。"},{"en":"The phrase identifies William Preston’s social and economic status.","zh":"這個詞組指出 William Preston 的社會和經濟地位。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":5},{"front":"settle in","meaning":"定居於……","examples":[{"en":"Margaret and William settled in Mosman after their marriage.","zh":"Margaret 和 William 婚後定居於 Mosman。"},{"en":"To settle in a place means to make it one’s home.","zh":"定居於某地是指把那裏作為家。"},{"en":"The couple settled in a Sydney harbourside suburb.","zh":"這對夫婦定居於悉尼海港旁的市郊。"},{"en":"Their home in Sydney became the base for many harbour subjects.","zh":"他們在悉尼的家成為許多海港題材的基礎。"},{"en":"The phrase marks a stable period after travel.","zh":"這個詞組標誌旅行後的穩定時期。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":5},{"front":"Sydney harbourside suburb","meaning":"悉尼海港旁的市郊","examples":[{"en":"Mosman is a Sydney harbourside suburb.","zh":"Mosman 是悉尼海港旁的市郊。"},{"en":"A Sydney harbourside suburb is a residential area near Sydney Harbour.","zh":"悉尼海港旁的市郊是靠近悉尼港的住宅區。"},{"en":"Living there gave Preston access to harbour views.","zh":"住在那裏讓 Preston 接觸海港景色。"},{"en":"These views appeared in her early Sydney prints.","zh":"這些景色出現在她早期悉尼版畫中。"},{"en":"The phrase describes Mosman’s location and character.","zh":"這個詞組描述 Mosman 的位置和特色。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":6},{"front":"the most characteristic prints","meaning":"最具代表性的版畫","examples":[{"en":"The most characteristic prints from this period show Sydney Harbour.","zh":"這一時期最具代表性的版畫描繪悉尼港。"},{"en":"The most characteristic prints are the works that best represent a period or style.","zh":"最具代表性的版畫是最能代表某時期或風格的作品。"},{"en":"Preston’s harbour prints became strongly associated with her early Sydney years.","zh":"Preston 的海港版畫與她在悉尼的早年密切相關。"},{"en":"These prints often showed boats and foreshore houses.","zh":"這些版畫常描繪船隻和海濱房屋。"},{"en":"The phrase identifies the defining works of a period.","zh":"這個詞組指出某時期的標誌性作品。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":6},{"front":"early years in Sydney","meaning":"在悉尼的早年","examples":[{"en":"Her early years in Sydney produced many harbour views.","zh":"她在悉尼的早年創作了許多海港景色。"},{"en":"Early years in Sydney means the first period she lived and worked there.","zh":"在悉尼的早年是指她最初在那裏生活和工作的時期。"},{"en":"During these years, Preston made prints of Sydney Harbour.","zh":"在這些年中，Preston 製作了悉尼港版畫。"},{"en":"The harbour became a major subject in her work.","zh":"海港成為她作品中的主要題材。"},{"en":"The phrase links place and artistic production.","zh":"這個詞組把地方和藝術創作連接起來。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":6},{"front":"views of boats floating","meaning":"船隻漂浮的景象","examples":[{"en":"Her prints showed views of boats floating on Sydney Harbour.","zh":"她的版畫描繪船隻漂浮在悉尼港上的景象。"},{"en":"Views of boats floating are scenes showing boats resting or moving on water.","zh":"船隻漂浮的景象是顯示船在水面停留或移動的場景。"},{"en":"Preston used such views to capture harbour life.","zh":"Preston 用這些景象捕捉海港生活。"},{"en":"Boats floating on the harbour became a repeated visual subject.","zh":"漂浮在港上的船隻成為反覆出現的視覺題材。"},{"en":"The phrase describes the content of her harbour prints.","zh":"這個詞組描述她海港版畫的內容。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":6},{"front":"Sydney Harbour","meaning":"悉尼港","examples":[{"en":"Many early Sydney prints showed boats on Sydney Harbour.","zh":"許多早期悉尼版畫描繪悉尼港上的船隻。"},{"en":"Sydney Harbour was a key subject in Preston’s early Sydney work.","zh":"悉尼港是 Preston 早期悉尼作品中的重要題材。"},{"en":"The harbour’s boats and foreshore hills appeared in her prints.","zh":"海港上的船隻和海濱山坡出現在她的版畫中。"},{"en":"Her 1925 exhibitions again included prominent harbour views.","zh":"她1925年的展覽再次突出海港景色。"},{"en":"The phrase identifies a major Australian location in her art.","zh":"這個詞組指出她藝術中的重要澳洲地點。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":6},{"front":"houses clustered on","meaning":"房屋聚集在……","examples":[{"en":"Some prints showed houses clustered on foreshore hills.","zh":"有些版畫描繪房屋聚集在海濱山坡上。"},{"en":"Houses clustered on a place means houses grouped closely together there.","zh":"房屋聚集在某地，是指房屋在那裏密集成群。"},{"en":"Preston depicted houses clustered above Sydney Harbour.","zh":"Preston 描繪房屋聚集在悉尼港上方。"},{"en":"This detail made her harbour scenes compact and busy.","zh":"這個細節令她的海港景象緊湊而繁複。"},{"en":"The phrase describes the arrangement of buildings in her prints.","zh":"這個詞組描述版畫中建築物的排列。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":6},{"front":"foreshore hills","meaning":"海濱山坡","examples":[{"en":"Her prints showed houses clustered on foreshore hills.","zh":"她的版畫描繪房屋聚集在海濱山坡上。"},{"en":"Foreshore hills are slopes near the edge of the water.","zh":"海濱山坡是靠近水邊的斜坡。"},{"en":"These hills formed part of the Sydney Harbour scenery.","zh":"這些山坡構成悉尼港景色的一部分。"},{"en":"Preston used them to create layered harbour compositions.","zh":"Preston 利用它們創造層次豐富的海港構圖。"},{"en":"The phrase describes a landscape feature in her prints.","zh":"這個詞組描述她版畫中的地貌特徵。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":6},{"front":"although Sydney was their home","meaning":"雖然悉尼是他們的家","examples":[{"en":"Although Sydney was their home, the couple travelled regularly.","zh":"雖然悉尼是他們的家，這對夫婦仍經常旅行。"},{"en":"Although Sydney was their home means despite living mainly in Sydney.","zh":"雖然悉尼是他們的家，是指儘管他們主要住在悉尼。"},{"en":"Preston and her husband kept travelling even after settling there.","zh":"Preston 和丈夫定居當地後仍繼續旅行。"},{"en":"The phrase contrasts a home base with frequent travel.","zh":"這個詞組把固定住所與頻繁旅行作對比。"},{"en":"It shows that travel remained important in their lives.","zh":"它顯示旅行在他們生活中仍很重要。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":6},{"front":"travel regularly","meaning":"經常旅行","examples":[{"en":"The couple travelled regularly overseas and within Australia.","zh":"這對夫婦經常到海外及澳洲境內旅行。"},{"en":"Travel regularly means travel often or repeatedly.","zh":"經常旅行是指頻繁或反覆旅行。"},{"en":"Preston’s regular travel exposed her to different places and cultures.","zh":"Preston 的經常旅行使她接觸不同地方和文化。"},{"en":"She later visited important Aboriginal sites throughout Australia.","zh":"她後來遍訪澳洲重要原住民遺址。"},{"en":"The phrase describes a continuing habit.","zh":"這個詞組描述持續習慣。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":6},{"front":"overseas and within Australia","meaning":"海外及澳洲境內","examples":[{"en":"They travelled overseas and within Australia.","zh":"他們到海外及澳洲境內旅行。"},{"en":"Overseas and within Australia means both outside the country and inside it.","zh":"海外及澳洲境內是指既到國外，也在澳洲國內。"},{"en":"Preston’s travels included international journeys and domestic trips.","zh":"Preston 的旅程包括國際旅行和國內旅行。"},{"en":"These journeys broadened her artistic sources.","zh":"這些旅程擴闊了她的藝術來源。"},{"en":"The phrase describes the range of their travel.","zh":"這個詞組描述他們旅行的範圍。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":6},{"front":"first major showing","meaning":"首次大型展出","examples":[{"en":"Her first major showing in Australia was with Thea Proctor.","zh":"她在澳洲的首次大型展出是與 Thea Proctor 一起舉行。"},{"en":"First major showing means an artist’s first important public exhibition.","zh":"首次大型展出是藝術家第一次重要公開展覽。"},{"en":"This showing helped present Preston’s work to Australian audiences.","zh":"這次展出幫助把 Preston 的作品呈現給澳洲觀眾。"},{"en":"It was shared with her friend Thea Proctor.","zh":"它與她的朋友 Thea Proctor 共同舉行。"},{"en":"The phrase marks an important moment in her public career.","zh":"這個詞組標誌她公開事業中的重要時刻。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":6},{"front":"with her friend","meaning":"與她的朋友","examples":[{"en":"Her first major showing was with her friend Thea Proctor.","zh":"她的首次大型展出是與她的朋友 Thea Proctor 一起舉行。"},{"en":"With her friend means together with someone she knew personally.","zh":"與她的朋友是指與她私下認識的人一起。"},{"en":"Preston and Proctor shared an important exhibition.","zh":"Preston 和 Proctor 共同舉辦重要展覽。"},{"en":"The phrase highlights both artistic and personal connection.","zh":"這個詞組突出藝術和私人關係。"},{"en":"It identifies Thea Proctor’s relationship to Preston.","zh":"它指出 Thea Proctor 與 Preston 的關係。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":7},{"front":"hand-coloured","meaning":"手工上色的","examples":[{"en":"Many of Preston’s prints were hand-coloured in rich colours.","zh":"Preston 許多版畫都以鮮艷色彩手工上色。"},{"en":"Hand-coloured means colour was added by hand after printing.","zh":"手工上色的是指印刷後由人手加上顏色。"},{"en":"Hand-coloured prints allowed Preston to use strong scarlet reds, blues and greens.","zh":"手工上色版畫讓 Preston 使用鮮艷猩紅、藍和綠色。"},{"en":"This technique made each print visually lively.","zh":"這種技法令每幅版畫視覺上更活潑。"},{"en":"The phrase describes a method of finishing prints.","zh":"這個詞組描述完成版畫的方法。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":7},{"front":"rich scarlet reds, blues and greens","meaning":"鮮艷的猩紅色、藍色和綠色","examples":[{"en":"Her prints were coloured in rich scarlet reds, blues and greens.","zh":"她的版畫以鮮艷的猩紅色、藍色和綠色上色。"},{"en":"Rich scarlet reds, blues and greens are strong, vivid colours.","zh":"鮮艷的猩紅色、藍色和綠色是強烈而生動的色彩。"},{"en":"These colours gave Preston’s prints a lively decorative effect.","zh":"這些色彩為 Preston 的版畫帶來活潑裝飾效果。"},{"en":"The strong colours helped attract public attention.","zh":"強烈色彩幫助吸引公眾注意。"},{"en":"The phrase describes the palette of some of her prints.","zh":"這個詞組描述她部分版畫的色彩配置。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":7},{"front":"set in frames","meaning":"裝在畫框中","examples":[{"en":"The prints were set in Chinese red lacquer frames.","zh":"這些版畫裝在中式紅漆畫框中。"},{"en":"Set in frames means placed or mounted inside frames.","zh":"裝在畫框中是指被放置或裱裝於畫框內。"},{"en":"Preston’s framing choices contributed to the visual impact of her works.","zh":"Preston 的畫框選擇增加了作品的視覺效果。"},{"en":"Chinese red lacquer frames added a distinctive decorative element.","zh":"中式紅漆畫框增添獨特裝飾元素。"},{"en":"The phrase describes how the prints were presented.","zh":"這個詞組描述版畫的展示方式。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":7},{"front":"Chinese red lacquer frames","meaning":"中式紅漆畫框","examples":[{"en":"Her prints were set in Chinese red lacquer frames.","zh":"她的版畫裝在中式紅漆畫框中。"},{"en":"Chinese red lacquer frames are red, glossy frames associated with Chinese decorative style.","zh":"中式紅漆畫框是與中國裝飾風格相關的紅色亮漆畫框。"},{"en":"These frames reflected Preston’s interest in Chinese art and design.","zh":"這些畫框反映 Preston 對中國藝術和設計的興趣。"},{"en":"The red frames strengthened the decorative presentation of her prints.","zh":"紅色畫框加強了她版畫的裝飾性展示。"},{"en":"The phrase identifies a specific framing style.","zh":"這個詞組指出一種具體畫框風格。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":7},{"front":"harbour views","meaning":"海港景色","examples":[{"en":"Harbour views were again prominent in her work.","zh":"海港景色再次在她的作品中突出。"},{"en":"Harbour views are scenes showing a harbour and its surroundings.","zh":"海港景色是描繪海港及其周圍環境的場景。"},{"en":"Preston’s harbour views often showed boats and foreshore hills.","zh":"Preston 的海港景色常描繪船隻和海濱山坡。"},{"en":"These views were prominent in her 1925 exhibitions.","zh":"這些景色在她1925年的展覽中十分突出。"},{"en":"The phrase names a repeated subject in her Sydney work.","zh":"這個詞組指出她悉尼作品中的反覆題材。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":7},{"front":"be prominent","meaning":"顯著；突出","examples":[{"en":"Harbour views were prominent in Preston’s 1925 exhibitions.","zh":"海港景色在 Preston 1925年的展覽中十分突出。"},{"en":"Be prominent means be noticeable, important, or strongly featured.","zh":"顯著或突出是指明顯、重要或被強烈呈現。"},{"en":"Native flora was also prominent in some of her prints.","zh":"本土植物在她一些版畫中也很突出。"},{"en":"Aboriginal symbols later became increasingly prominent in her work.","zh":"澳洲原住民符號後來在她作品中變得越來越突出。"},{"en":"The phrase describes visual or thematic importance.","zh":"這個詞組描述視覺或主題重要性。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":7},{"front":"compared with earlier works","meaning":"與較早期作品相比","examples":[{"en":"Compared with earlier works, the prints were compact and busy.","zh":"與較早期作品相比，這些版畫緊湊而繁複。"},{"en":"Compared with earlier works means judged against what she made before.","zh":"與較早期作品相比，是指以她之前的作品作比較。"},{"en":"The 1925 harbour prints were more crowded than earlier versions.","zh":"1925年的海港版畫比早期版本更密集。"},{"en":"The phrase helps show stylistic change over time.","zh":"這個詞組幫助顯示風格隨時間改變。"},{"en":"It introduces comparison within her career.","zh":"它引出她事業內部的比較。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":7},{"front":"compact and busy","meaning":"緊湊而繁複","examples":[{"en":"Her later harbour prints were compact and busy.","zh":"她後來的海港版畫緊湊而繁複。"},{"en":"Compact and busy means tightly arranged and full of visual detail.","zh":"緊湊而繁複是指安排密集且充滿視覺細節。"},{"en":"The harbour scenes included clustered houses and strong patterns.","zh":"這些海港景象包括密集房屋和強烈圖案。"},{"en":"This style differed from simpler earlier works.","zh":"這種風格不同於較簡單的早期作品。"},{"en":"The phrase describes the dense composition of her prints.","zh":"這個詞組描述她版畫的密集構圖。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":7},{"front":"striking contrasts of black and white","meaning":"強烈的黑白對比","examples":[{"en":"The prints used striking contrasts of black and white.","zh":"這些版畫使用強烈的黑白對比。"},{"en":"Striking contrasts of black and white are strong visual differences between dark and light areas.","zh":"強烈的黑白對比是深色和淺色區域之間鮮明的視覺差異。"},{"en":"Such contrasts gave Preston’s prints graphic power.","zh":"這種對比賦予 Preston 的版畫圖像力量。"},{"en":"Black-and-white contrast worked with elaborate patterns and repetitions.","zh":"黑白對比與精緻圖案和重複元素配合。"},{"en":"The phrase describes a bold visual technique.","zh":"這個詞組描述大膽的視覺技法。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":7},{"front":"elaborate patterns and repetitions","meaning":"精緻圖案和重複元素","examples":[{"en":"Her prints combined contrasts with elaborate patterns and repetitions.","zh":"她的版畫把對比與精緻圖案和重複元素結合。"},{"en":"Elaborate patterns and repetitions are detailed designs that repeat visual forms.","zh":"精緻圖案和重複元素是反覆出現的細緻設計。"},{"en":"Preston used them to create decorative energy.","zh":"Preston 利用它們創造裝飾性活力。"},{"en":"Repetition became an important feature of her print design.","zh":"重複元素成為她版畫設計的重要特徵。"},{"en":"The phrase describes the complexity of her compositions.","zh":"這個詞組描述她構圖的複雜性。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":7},{"front":"feature native flora","meaning":"以本土植物為題材","examples":[{"en":"Other prints from this period featured native flora.","zh":"這一時期的其他版畫以本土植物為題材。"},{"en":"Feature native flora means include local Australian plant life as a subject.","zh":"以本土植物為題材是指把澳洲本地植物作為主題。"},{"en":"Preston used native flora to promote Australian natural beauty.","zh":"Preston 使用本土植物來推廣澳洲自然美。"},{"en":"Her flower prints helped celebrate local plants.","zh":"她的花卉版畫幫助頌揚本地植物。"},{"en":"The phrase describes one major theme of her work.","zh":"這個詞組描述她作品的一個主要主題。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":8},{"front":"native flora","meaning":"本土植物群","examples":[{"en":"Preston’s prints often featured Australian native flora.","zh":"Preston 的版畫常以澳洲本土植物群為題材。"},{"en":"Native flora means plants that naturally belong to a region.","zh":"本土植物群是自然屬於某地區的植物。"},{"en":"Australian native flora became central to Preston’s still-life works.","zh":"澳洲本土植物群成為 Preston 靜物作品的核心。"},{"en":"She wanted the public to appreciate native flowers.","zh":"她希望公眾欣賞本土花卉。"},{"en":"The phrase identifies local plant life in her art.","zh":"這個詞組指出她藝術中的本地植物生命。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":8},{"front":"still-life subjects","meaning":"靜物題材","examples":[{"en":"She used still-life subjects to promote Australian native flowers.","zh":"她使用靜物題材推廣澳洲本土花卉。"},{"en":"Still-life subjects are objects such as flowers or fruit arranged for art.","zh":"靜物題材是為藝術而安排的物件，例如花或水果。"},{"en":"Preston’s still-life subjects often included native flowers.","zh":"Preston 的靜物題材常包括本土花卉。"},{"en":"Later, she moved away from arranging flowers in vases.","zh":"後來，她不再把花插在花瓶中描繪。"},{"en":"The phrase describes a traditional artistic subject type.","zh":"這個詞組描述一種傳統藝術題材類型。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":8},{"front":"convince the public that","meaning":"說服公眾相信","examples":[{"en":"She convinced the public that Australian native flowers were beautiful.","zh":"她說服公眾相信澳洲本土花卉很美。"},{"en":"To convince the public that something is true means to persuade people to believe it.","zh":"說服公眾相信某事是真，是指使人們接受該想法。"},{"en":"Preston’s prints convinced viewers of the beauty of local flora.","zh":"Preston 的版畫使觀眾相信本地植物的美。"},{"en":"Her art challenged the preference for exotic flowers.","zh":"她的藝術挑戰人們對外來花卉的偏好。"},{"en":"The phrase describes the persuasive role of her work.","zh":"這個詞組描述她作品的說服作用。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":8},{"front":"Australian native flowers","meaning":"澳洲本土花卉","examples":[{"en":"Preston celebrated Australian native flowers in her still-life prints.","zh":"Preston 在靜物版畫中讚頌澳洲本土花卉。"},{"en":"Australian native flowers are flowers naturally found in Australia.","zh":"澳洲本土花卉是自然生長於澳洲的花。"},{"en":"She believed they were equal in beauty to exotic species.","zh":"她相信它們在美感上不遜於外來物種。"},{"en":"Her prints helped make these flowers visually important.","zh":"她的版畫幫助使這些花在視覺上變得重要。"},{"en":"The phrase identifies one of her most important subjects.","zh":"這個詞組指出她最重要的題材之一。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":8},{"front":"be equal in beauty to","meaning":"在美感上不遜於……","examples":[{"en":"She showed that native flowers were equal in beauty to exotic species.","zh":"她顯示本土花卉在美感上不遜於外來物種。"},{"en":"Be equal in beauty to something means be just as beautiful as it.","zh":"在美感上不遜於某物，是指與它同樣美麗。"},{"en":"Preston wanted Australians to value their own native flowers.","zh":"Preston 希望澳洲人重視自己的本土花卉。"},{"en":"Her still-life works argued visually for this equality.","zh":"她的靜物作品以視覺方式表達這種平等。"},{"en":"The phrase expresses a comparison of aesthetic value.","zh":"這個詞組表達審美價值的比較。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":8},{"front":"exotic species","meaning":"外來物種","examples":[{"en":"Preston compared Australian native flowers with exotic species.","zh":"Preston 把澳洲本土花卉與外來物種比較。"},{"en":"Exotic species are plants or animals introduced from other regions.","zh":"外來物種是從其他地區引入的植物或動物。"},{"en":"Many people valued exotic flowers more than native ones.","zh":"許多人曾更重視外來花卉而非本土花卉。"},{"en":"Preston’s art challenged that attitude.","zh":"Preston 的藝術挑戰了這種態度。"},{"en":"The phrase contrasts foreign plants with Australian native flora.","zh":"這個詞組把外來植物與澳洲本土植物作對比。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":8},{"front":"move away from","meaning":"離開……","examples":[{"en":"From 1932 to 1939, Preston moved away from Sydney.","zh":"1932年至1939年間，Preston 離開悉尼。"},{"en":"Move away from a place means leave it to live somewhere else.","zh":"離開某地是指搬離那裏，到別處生活。"},{"en":"Preston moved away to Berowra on the Hawkesbury River.","zh":"Preston 搬到霍克斯伯里河畔的 Berowra。"},{"en":"This move changed the natural subjects available to her.","zh":"這次搬遷改變了她可接觸的自然題材。"},{"en":"The phrase marks a shift in location and artistic environment.","zh":"這個詞組標誌地點和藝術環境的轉變。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":8},{"front":"upper reaches of","meaning":"……的上游地區","examples":[{"en":"Berowra is on the upper reaches of the Hawkesbury River.","zh":"Berowra 位於霍克斯伯里河的上游地區。"},{"en":"Upper reaches of a river are the higher or upstream parts.","zh":"河流的上游地區是較高或較接近源頭的部分。"},{"en":"Preston lived near this section of the river.","zh":"Preston 住在河流這一段附近。"},{"en":"The location offered rugged natural beauty.","zh":"該地區具有粗獷的自然美。"},{"en":"The phrase describes a river’s geographical position.","zh":"這個詞組描述河流的地理位置。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":8},{"front":"Hawkesbury River","meaning":"霍克斯伯里河","examples":[{"en":"Preston lived near the Hawkesbury River at Berowra.","zh":"Preston 住在 Berowra 附近的霍克斯伯里河一帶。"},{"en":"The Hawkesbury River provided a rugged natural setting.","zh":"霍克斯伯里河提供粗獷自然環境。"},{"en":"Living near the river surrounded Preston with bush and native flowers.","zh":"住在河附近讓 Preston 被灌木林和本土花卉包圍。"},{"en":"This environment influenced her later flower prints.","zh":"這種環境影響她後來的花卉版畫。"},{"en":"The phrase identifies an important place in her middle career.","zh":"這個詞組指出她事業中期的重要地方。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":8},{"front":"rugged natural beauty","meaning":"粗獷的自然美","examples":[{"en":"The area was one of rugged natural beauty.","zh":"該地區具有粗獷的自然美。"},{"en":"Rugged natural beauty means rough, wild, and attractive scenery.","zh":"粗獷的自然美是指粗野、原始而吸引人的景色。"},{"en":"The bush around Berowra gave Preston new natural subjects.","zh":"Berowra 周圍的灌木林給 Preston 新的自然題材。"},{"en":"This beauty differed from the harbour scenes of Sydney.","zh":"這種美不同於悉尼海港景色。"},{"en":"The phrase describes the character of the landscape.","zh":"這個詞組描述景觀的特質。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":8},{"front":"for the first time","meaning":"第一次","examples":[{"en":"For the first time, Preston lived in a home surrounded by bush.","zh":"Preston 第一次住在被澳洲灌木林包圍的家中。"},{"en":"For the first time means something had not happened before.","zh":"第一次是指某事以前未曾發生。"},{"en":"This was the first time she lived so directly among native plants.","zh":"這是她第一次如此直接地生活在本土植物之中。"},{"en":"The experience changed how she painted flowers.","zh":"這種經驗改變了她描繪花卉的方式。"},{"en":"The phrase highlights a new personal and artistic situation.","zh":"這個詞組突出新的個人和藝術處境。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":9},{"front":"find herself living in","meaning":"發現自己住在……","examples":[{"en":"Preston found herself living in a home surrounded by bush.","zh":"Preston 發現自己住在被灌木林包圍的家中。"},{"en":"Find herself living in a place means come to be living there, sometimes unexpectedly.","zh":"發現自己住在某地，是指自己處於居住在那裏的狀態，有時帶有意外感。"},{"en":"This new setting placed her close to native plants.","zh":"這個新環境使她接近本土植物。"},{"en":"Her surroundings influenced the subjects of her prints.","zh":"她的周遭環境影響了版畫題材。"},{"en":"The phrase describes her changed living situation.","zh":"這個詞組描述她改變後的生活情況。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":9},{"front":"surrounded by bush","meaning":"被澳洲灌木林包圍","examples":[{"en":"Her home was surrounded by bush.","zh":"她的家被澳洲灌木林包圍。"},{"en":"Surrounded by bush means enclosed or bordered by native Australian vegetation.","zh":"被澳洲灌木林包圍是指四周被本土植被圍繞。"},{"en":"Living surrounded by bush gave Preston direct access to native flowers.","zh":"住在灌木林包圍中，使 Preston 能直接接觸本土花卉。"},{"en":"The bush setting influenced her Berowra works.","zh":"灌木林環境影響了她的 Berowra 作品。"},{"en":"The phrase describes her natural environment.","zh":"這個詞組描述她的自然環境。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":9},{"front":"prior to this","meaning":"在此之前","examples":[{"en":"Prior to this, she bought native flowers from local florists.","zh":"在此之前，她從本地花店購買本土花卉。"},{"en":"Prior to this means before this time or event.","zh":"在此之前是指在這個時間或事件以前。"},{"en":"Before living at Berowra, Preston did not gather flowers from her own surroundings.","zh":"住在 Berowra 前，Preston 並非從自己周圍採集花卉。"},{"en":"The phrase contrasts earlier practice with later direct observation.","zh":"這個詞組把早期做法與後來直接觀察作對比。"},{"en":"It helps show how her artistic sources changed.","zh":"它幫助顯示她的藝術來源如何改變。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":9},{"front":"feature in her paintings and prints","meaning":"出現在她的畫作和版畫中","examples":[{"en":"Native flowers featured in her paintings and prints.","zh":"本土花卉出現在她的畫作和版畫中。"},{"en":"Feature in her paintings and prints means appear as important subjects in them.","zh":"出現在她的畫作和版畫中，是指作為重要題材呈現。"},{"en":"Australian flowers repeatedly featured in Preston’s art.","zh":"澳洲花卉反覆出現在 Preston 的藝術中。"},{"en":"At Berowra, wild flowers featured more naturally in her work.","zh":"在 Berowra，野生花卉更自然地出現在她作品中。"},{"en":"The phrase describes recurring subject matter.","zh":"這個詞組描述反覆出現的題材。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":9},{"front":"be purchased from","meaning":"從……購買","examples":[{"en":"Before Berowra, the flowers had been purchased from local florists.","zh":"在 Berowra 之前，這些花是從本地花店購買的。"},{"en":"Be purchased from someone means be bought from that seller.","zh":"從某人購買是指向該賣方買下。"},{"en":"Preston purchased native flowers before she lived among them.","zh":"Preston 在親身生活於花卉環境前購買本土花卉。"},{"en":"Later, flowers grew naturally around her home.","zh":"後來，花朵在她家周圍自然生長。"},{"en":"The phrase describes the source of her earlier flower subjects.","zh":"這個詞組描述她早期花卉題材的來源。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":9},{"front":"local florists","meaning":"本地花店","examples":[{"en":"Preston had bought native flowers from local florists.","zh":"Preston 曾從本地花店購買本土花卉。"},{"en":"Local florists are nearby sellers of flowers.","zh":"本地花店是附近售賣花卉的商店。"},{"en":"Before Berowra, local florists supplied the flowers in her still lifes.","zh":"在 Berowra 之前，本地花店供應她靜物畫中的花。"},{"en":"This changed when native flowers grew around her home.","zh":"當本土花卉在她家附近生長後，這情況改變。"},{"en":"The phrase identifies the commercial source of flowers.","zh":"這個詞組指出花卉的商業來源。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":9},{"front":"grow in abundance","meaning":"大量生長","examples":[{"en":"Native flowers grew in abundance around her Berowra home.","zh":"本土花卉在她 Berowra 的家附近大量生長。"},{"en":"Grow in abundance means grow in large numbers.","zh":"大量生長是指以大量數目生長。"},{"en":"The abundant flowers gave Preston direct natural subjects.","zh":"豐富的花卉給 Preston 直接的自然題材。"},{"en":"This abundance changed her flower compositions.","zh":"這種豐富改變了她的花卉構圖。"},{"en":"The phrase describes plentiful plant growth.","zh":"這個詞組描述植物繁盛生長。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":9},{"front":"less reliant on","meaning":"較少依賴……","examples":[{"en":"Her prints became less reliant on bright colours.","zh":"她的版畫變得較少依賴鮮艷顏色。"},{"en":"Less reliant on something means depending on it less than before.","zh":"較少依賴某物是指比以前更少倚靠它。"},{"en":"Preston’s Berowra prints used fewer bright colours.","zh":"Preston 的 Berowra 版畫使用較少鮮艷顏色。"},{"en":"She relied more on natural forms and wild settings.","zh":"她更依賴自然形態和野外環境。"},{"en":"The phrase describes a stylistic change.","zh":"這個詞組描述風格變化。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":9},{"front":"bright colours","meaning":"鮮艷顏色","examples":[{"en":"Her Berowra prints used fewer bright colours.","zh":"她的 Berowra 版畫使用較少鮮艷顏色。"},{"en":"Bright colours are strong, vivid colours.","zh":"鮮艷顏色是強烈而生動的色彩。"},{"en":"Earlier prints often used bright reds, blues and greens.","zh":"早期版畫常使用鮮紅、藍和綠等鮮艷顏色。"},{"en":"Later Berowra works became less reliant on bright colours.","zh":"後來的 Berowra 作品較少依賴鮮艷顏色。"},{"en":"The phrase describes one visual quality of her art.","zh":"這個詞組描述她藝術的一種視覺特質。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":9},{"front":"be arranged in vases","meaning":"被插放在花瓶中","examples":[{"en":"Flowers were no longer arranged in vases.","zh":"花不再被插放在花瓶中。"},{"en":"Be arranged in vases means be placed in containers for display.","zh":"被插放在花瓶中是指被放在容器中展示。"},{"en":"Preston moved away from formal vase arrangements.","zh":"Preston 不再使用正式花瓶擺設。"},{"en":"She instead painted flowers growing wild.","zh":"她轉而描繪野外生長的花。"},{"en":"The phrase describes a traditional still-life setup.","zh":"這個詞組描述傳統靜物安排。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":9},{"front":"concentrate instead on","meaning":"轉而集中於……","examples":[{"en":"Preston began to concentrate instead on flowers growing wild.","zh":"Preston 開始轉而集中於野外生長的花。"},{"en":"Concentrate instead on something means shift attention to that thing rather than something else.","zh":"轉而集中於某事，是指把注意力從其他事物轉向它。"},{"en":"She concentrated on natural settings instead of vase arrangements.","zh":"她集中於自然環境，而不是花瓶擺設。"},{"en":"This shift reflected her new life surrounded by bush.","zh":"這種轉變反映她被灌木林包圍的新生活。"},{"en":"The phrase describes a change of artistic focus.","zh":"這個詞組描述藝術焦點改變。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":10},{"front":"growing wild","meaning":"野外生長","examples":[{"en":"She painted flowers that were growing wild.","zh":"她描繪野外生長的花。"},{"en":"Growing wild means growing naturally without cultivation or arrangement.","zh":"野外生長是指自然生長，沒有人工栽培或安排。"},{"en":"At Berowra, native flowers grew wild around her home.","zh":"在 Berowra，本土花卉在她家附近野外生長。"},{"en":"Preston’s prints began to show flowers in their natural setting.","zh":"Preston 的版畫開始呈現自然環境中的花。"},{"en":"The phrase contrasts wild nature with arranged still life.","zh":"這個詞組把野生自然與擺設靜物作對比。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":10},{"front":"while living at","meaning":"住在……期間","examples":[{"en":"While living at Berowra, Preston developed an interest in Aboriginal art.","zh":"住在 Berowra 期間，Preston 培養了對澳洲原住民藝術的興趣。"},{"en":"While living at a place means during the period she lived there.","zh":"住在某地期間是指她居住在那裏的時期。"},{"en":"Her time at Berowra brought her close to Aboriginal rock engravings.","zh":"她在 Berowra 的日子使她接近澳洲原住民岩石雕刻。"},{"en":"This period changed her later artistic direction.","zh":"這段時期改變了她後來的藝術方向。"},{"en":"The phrase links place of residence with new influence.","zh":"這個詞組把居住地與新影響連接起來。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":10},{"front":"undoubtedly prompted by","meaning":"無疑受到……啟發","examples":[{"en":"Her interest was undoubtedly prompted by nearby Aboriginal rock engravings.","zh":"她的興趣無疑受到附近澳洲原住民岩石雕刻啟發。"},{"en":"Undoubtedly prompted by means certainly encouraged or caused by something.","zh":"無疑受到某事啟發，是指肯定被某事鼓勵或引起。"},{"en":"The rock engravings near her property sparked her interest.","zh":"她物業附近的岩石雕刻激發了她的興趣。"},{"en":"This influence became important in her later work.","zh":"這種影響在她後來作品中變得重要。"},{"en":"The phrase expresses strong confidence about a cause.","zh":"這個詞組表達對原因的高度肯定。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":10},{"front":"Aboriginal rock engravings","meaning":"澳洲原住民岩石雕刻","examples":[{"en":"Aboriginal rock engravings were found near Preston’s property.","zh":"澳洲原住民岩石雕刻在 Preston 的物業附近被發現。"},{"en":"Aboriginal rock engravings are carved images or symbols made on rock by Aboriginal people.","zh":"澳洲原住民岩石雕刻是澳洲原住民刻在岩石上的圖像或符號。"},{"en":"These engravings helped prompt Preston’s interest in Aboriginal art.","zh":"這些雕刻幫助激發 Preston 對原住民藝術的興趣。"},{"en":"They became part of the visual culture that influenced her.","zh":"它們成為影響她的視覺文化之一。"},{"en":"The phrase names a direct source of inspiration.","zh":"這個詞組指出一個直接靈感來源。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":10},{"front":"near her property","meaning":"在她的物業附近","examples":[{"en":"The rock engravings were found near her property.","zh":"這些岩石雕刻在她的物業附近被發現。"},{"en":"Near her property means close to the land or home she owned or occupied.","zh":"在她的物業附近是指靠近她擁有或居住的土地或房子。"},{"en":"The engravings’ closeness made them easy for Preston to encounter.","zh":"雕刻距離很近，使 Preston 容易接觸到它們。"},{"en":"This local discovery influenced her lifelong interest.","zh":"這個本地發現影響了她的終身興趣。"},{"en":"The phrase describes the location of an artistic influence.","zh":"這個詞組描述藝術影響的位置。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":10},{"front":"lifelong interest in","meaning":"對……的終身興趣","examples":[{"en":"Preston developed a lifelong interest in Aboriginal art.","zh":"Preston 培養了對澳洲原住民藝術的終身興趣。"},{"en":"A lifelong interest in something lasts for the rest of a person’s life.","zh":"對某事的終身興趣是指在餘生一直持續的興趣。"},{"en":"Her interest in Aboriginal art continued after she returned to Sydney.","zh":"她返回悉尼後，對原住民藝術的興趣仍然持續。"},{"en":"This lifelong interest shaped many later prints.","zh":"這種終身興趣塑造了許多後期版畫。"},{"en":"The phrase describes a lasting artistic concern.","zh":"這個詞組描述持久的藝術關注。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":10},{"front":"Aboriginal art","meaning":"澳洲原住民藝術","examples":[{"en":"Preston believed Aboriginal art could help shape Australian art.","zh":"Preston 相信澳洲原住民藝術可以幫助塑造澳洲藝術。"},{"en":"Aboriginal art became a major influence in her later career.","zh":"澳洲原住民藝術成為她後期事業中的重大影響。"},{"en":"She visited Aboriginal sites throughout Australia.","zh":"她遍訪澳洲原住民遺址。"},{"en":"Aboriginal symbols and colours appeared in her prints.","zh":"澳洲原住民符號和色彩出現在她的版畫中。"},{"en":"The phrase names a central influence on Preston’s national art ideas.","zh":"這個詞組指出 Preston 民族藝術理念中的核心影響。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":10},{"front":"on returning to Sydney","meaning":"返回悉尼後","examples":[{"en":"On returning to Sydney, Preston joined an anthropological society.","zh":"返回悉尼後，Preston 加入了一個人類學學會。"},{"en":"On returning to a place means when or after she came back there.","zh":"返回某地後是指她回到那裏時或之後。"},{"en":"After returning to Sydney, she deepened her engagement with Aboriginal culture.","zh":"回到悉尼後，她加深了對澳洲原住民文化的參與。"},{"en":"The phrase marks a new stage after Berowra.","zh":"這個詞組標誌 Berowra 之後的新階段。"},{"en":"It links her return with further study and involvement.","zh":"它把她的返回與進一步學習和參與連接起來。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":10},{"front":"become a member of","meaning":"成為……的成員","examples":[{"en":"She became a member of the Anthropological Society of New South Wales.","zh":"她成為新南威爾斯人類學學會的成員。"},{"en":"Become a member of an organisation means officially join it.","zh":"成為某組織的成員是指正式加入該組織。"},{"en":"Preston joined the society after returning to Sydney.","zh":"Preston 返回悉尼後加入該學會。"},{"en":"Membership supported her interest in Aboriginal sites and culture.","zh":"會員身份支持她對原住民遺址和文化的興趣。"},{"en":"The phrase describes formal association with a group.","zh":"這個詞組描述與團體的正式關聯。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":10},{"front":"Anthropological Society of New South Wales","meaning":"新南威爾斯人類學學會","examples":[{"en":"Preston joined the Anthropological Society of New South Wales.","zh":"Preston 加入新南威爾斯人類學學會。"},{"en":"The Anthropological Society of New South Wales was connected with the study of human cultures.","zh":"新南威爾斯人類學學會與人類文化研究有關。"},{"en":"Joining it reflected Preston’s interest in Aboriginal culture.","zh":"加入該學會反映 Preston 對原住民文化的興趣。"},{"en":"It helped place her artistic interest within a broader cultural study context.","zh":"它幫助把她的藝術興趣放入更廣闊文化研究背景。"},{"en":"The phrase names the organisation she joined.","zh":"這個詞組指出她加入的組織。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":10},{"front":"Aboriginal sites","meaning":"澳洲原住民遺址","examples":[{"en":"Preston later visited many important Aboriginal sites.","zh":"Preston 後來參觀了許多重要澳洲原住民遺址。"},{"en":"Aboriginal sites are places connected with Aboriginal history, culture, or art.","zh":"澳洲原住民遺址是與原住民歷史、文化或藝術有關的地方。"},{"en":"Visiting these sites deepened Preston’s understanding of Aboriginal traditions.","zh":"參觀這些遺址加深 Preston 對原住民傳統的理解。"},{"en":"These visits influenced her later prints and titles.","zh":"這些參觀影響了她後來的版畫和標題。"},{"en":"The phrase identifies places of cultural significance.","zh":"這個詞組指出具有文化意義的地方。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":11},{"front":"throughout Australia","meaning":"遍及澳洲","examples":[{"en":"She visited Aboriginal sites throughout Australia.","zh":"她參觀遍及澳洲的原住民遺址。"},{"en":"Throughout Australia means across many parts of the country.","zh":"遍及澳洲是指橫跨澳洲許多地區。"},{"en":"Preston’s travels took her to important Aboriginal sites around Australia.","zh":"Preston 的旅行帶她到澳洲各地重要原住民遺址。"},{"en":"This wide travel supported her national artistic vision.","zh":"這種廣泛旅行支持她的民族藝術願景。"},{"en":"The phrase describes geographical breadth.","zh":"這個詞組描述地理範圍廣。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":11},{"front":"provide the key to","meaning":"提供……的關鍵","examples":[{"en":"Preston believed Aboriginal art provided the key to a national art.","zh":"Preston 相信澳洲原住民藝術提供民族藝術的關鍵。"},{"en":"Provide the key to something means offer the essential solution or basis for it.","zh":"提供某事的關鍵，是指提供其必要解決方法或基礎。"},{"en":"She believed Aboriginal art could unlock an authentic Australian style.","zh":"她相信原住民藝術能開啟真正澳洲風格。"},{"en":"This belief guided her later artistic experiments.","zh":"這種信念引導她後來的藝術實驗。"},{"en":"The phrase expresses central importance.","zh":"這個詞組表達核心重要性。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":11},{"front":"establish a national body of art","meaning":"建立一套民族藝術","examples":[{"en":"She wanted to establish a national body of art.","zh":"她想建立一套民族藝術。"},{"en":"Establish a national body of art means create a recognised collection or tradition of national art.","zh":"建立一套民族藝術是指創造受認可的國家藝術傳統或作品體系。"},{"en":"Preston wanted Australian art to reflect its own continent and culture.","zh":"Preston 希望澳洲藝術反映自身大陸和文化。"},{"en":"Aboriginal art was central to this goal.","zh":"澳洲原住民藝術是這個目標的核心。"},{"en":"The phrase describes her cultural ambition.","zh":"這個詞組描述她的文化抱負。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":11},{"front":"reflect the vast and ancient continent","meaning":"反映遼闊而古老的大陸","examples":[{"en":"She wanted Australian art to reflect the vast and ancient continent.","zh":"她希望澳洲藝術反映遼闊而古老的大陸。"},{"en":"Reflect the vast and ancient continent means express the scale, age, and character of Australia.","zh":"反映遼闊而古老的大陸，是指表達澳洲的規模、歷史和特質。"},{"en":"Preston believed national art should come from local land and culture.","zh":"Preston 相信民族藝術應源於本地土地和文化。"},{"en":"Aboriginal art helped her imagine such a national style.","zh":"澳洲原住民藝術幫助她想像這種民族風格。"},{"en":"The phrase describes her vision for Australian art.","zh":"這個詞組描述她對澳洲藝術的願景。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":11},{"front":"symbols used by Aboriginal people","meaning":"澳洲原住民使用的符號","examples":[{"en":"Symbols used by Aboriginal people became prominent in her prints.","zh":"澳洲原住民使用的符號在她的版畫中變得突出。"},{"en":"Symbols used by Aboriginal people are visual signs from Aboriginal cultural traditions.","zh":"澳洲原住民使用的符號是來自原住民文化傳統的視覺標記。"},{"en":"Preston incorporated these symbols into her later print designs.","zh":"Preston 把這些符號融入後期版畫設計中。"},{"en":"Their presence showed her engagement with Aboriginal sources.","zh":"它們的出現顯示她與原住民來源的連繫。"},{"en":"The phrase names a visual element in her work.","zh":"這個詞組指出她作品中的視覺元素。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":11},{"front":"together with","meaning":"連同；加上","examples":[{"en":"Aboriginal symbols, together with traditional colours, influenced her prints.","zh":"澳洲原住民符號連同傳統色彩影響了她的版畫。"},{"en":"Together with means along with or combined with.","zh":"連同或加上是指與某物一起或結合。"},{"en":"Symbols together with colours created a stronger Aboriginal influence in her art.","zh":"符號加上色彩，使她藝術中的原住民影響更強。"},{"en":"Preston also later combined Aboriginal ideas together with Chinese concepts.","zh":"Preston 後來也把原住民思想與中國概念結合。"},{"en":"The phrase links two elements acting together.","zh":"這個詞組連接共同作用的兩個元素。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":11},{"front":"dried, burnt colours","meaning":"乾燥、焦灼感的色彩","examples":[{"en":"Dried, burnt colours became prominent in her later prints.","zh":"乾燥、焦灼感的色彩在她後期版畫中變得突出。"},{"en":"Dried, burnt colours are earthy, muted tones suggesting dryness and heat.","zh":"乾燥、焦灼感的色彩是帶泥土感、較沉實、暗示乾燥和熱力的色調。"},{"en":"Preston drew these colours from traditional Aboriginal paintings.","zh":"Preston 從傳統澳洲原住民繪畫中汲取這些色彩。"},{"en":"They differed from the bright colours of some earlier prints.","zh":"它們不同於她部分早期版畫中的鮮艷顏色。"},{"en":"The phrase describes a later colour quality in her work.","zh":"這個詞組描述她作品後期的色彩特質。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":11},{"front":"traditional Aboriginal paintings","meaning":"傳統澳洲原住民繪畫","examples":[{"en":"Preston drew colours from traditional Aboriginal paintings.","zh":"Preston 從傳統澳洲原住民繪畫中汲取色彩。"},{"en":"Traditional Aboriginal paintings provided symbols and colour ideas for her work.","zh":"傳統澳洲原住民繪畫為她的作品提供符號和色彩想法。"},{"en":"She used these sources to develop a national Australian art.","zh":"她利用這些來源發展澳洲民族藝術。"},{"en":"Her titles often acknowledged such sources.","zh":"她的作品標題常承認這些來源。"},{"en":"The phrase identifies an important artistic source.","zh":"這個詞組指出重要藝術來源。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":11},{"front":"become increasingly prominent","meaning":"變得越來越突出","examples":[{"en":"Aboriginal symbols became increasingly prominent in her prints.","zh":"澳洲原住民符號在她的版畫中變得越來越突出。"},{"en":"Become increasingly prominent means become more noticeable over time.","zh":"變得越來越突出是指隨時間變得更明顯。"},{"en":"Aboriginal imagery grew stronger in Preston’s later work.","zh":"原住民圖像在 Preston 後期作品中更強烈。"},{"en":"This increasing prominence reflected her deepening interest.","zh":"這種日益突出反映她興趣逐漸加深。"},{"en":"The phrase describes gradual visual emphasis.","zh":"這個詞組描述逐漸增加的視覺強調。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":11},{"front":"artist’s titles","meaning":"藝術家的作品標題","examples":[{"en":"The artist’s titles frequently acknowledge her sources.","zh":"這位藝術家的作品標題經常承認其來源。"},{"en":"Artist’s titles are the names an artist gives to works.","zh":"藝術家的作品標題是藝術家為作品所取的名稱。"},{"en":"Preston’s titles often pointed to Aboriginal sources.","zh":"Preston 的標題常指向澳洲原住民來源。"},{"en":"Titles can reveal the inspiration behind an artwork.","zh":"標題可以揭示藝術作品背後的靈感。"},{"en":"The phrase refers to the naming of her works.","zh":"這個詞組指她作品的命名。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":11},{"front":"acknowledge her sources","meaning":"承認其來源","examples":[{"en":"Her titles frequently acknowledge her Aboriginal sources.","zh":"她的標題經常承認其澳洲原住民來源。"},{"en":"To acknowledge her sources means to openly recognise where ideas came from.","zh":"承認其來源是指公開承認想法來自何處。"},{"en":"Preston’s titles showed that she drew on Aboriginal art.","zh":"Preston 的標題顯示她借鑑澳洲原住民藝術。"},{"en":"Acknowledging sources can make artistic influence clearer.","zh":"承認來源可以使藝術影響更清楚。"},{"en":"The phrase describes honest recognition of inspiration.","zh":"這個詞組描述對靈感來源的明確認可。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":12},{"front":"reveal the extent to which","meaning":"顯示……的程度","examples":[{"en":"The titles reveal the extent to which she drew inspiration from Aboriginal art.","zh":"這些標題顯示她從澳洲原住民藝術汲取靈感的程度。"},{"en":"Reveal the extent to which means show how much something happened.","zh":"顯示某事的程度是指顯示它發生得有多深或多少。"},{"en":"Her titles reveal how deeply Aboriginal art influenced her work.","zh":"她的標題顯示原住民藝術對她作品影響多深。"},{"en":"The phrase introduces evidence of influence.","zh":"這個詞組引出影響的證據。"},{"en":"It helps explain the relationship between source and artwork.","zh":"它幫助解釋來源與作品之間的關係。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":12},{"front":"draw inspiration from","meaning":"從……汲取靈感","examples":[{"en":"Preston drew inspiration from traditional Aboriginal art.","zh":"Preston 從傳統澳洲原住民藝術汲取靈感。"},{"en":"To draw inspiration from something means to use it as a source of ideas.","zh":"從某事汲取靈感是指把它作為想法來源。"},{"en":"She also drew inspiration from Chinese art.","zh":"她也從中國藝術汲取靈感。"},{"en":"Her later prints drew inspiration from Aboriginal creation stories.","zh":"她後來的版畫從原住民創世故事汲取靈感。"},{"en":"The phrase describes creative borrowing and influence.","zh":"這個詞組描述創意借鑑和影響。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":12},{"front":"traditional Aboriginal art","meaning":"傳統澳洲原住民藝術","examples":[{"en":"Preston used traditional Aboriginal art to create her own art.","zh":"Preston 利用傳統澳洲原住民藝術創作自己的藝術。"},{"en":"Traditional Aboriginal art provided symbols, colours, and stories for her later prints.","zh":"傳統澳洲原住民藝術為她後來的版畫提供符號、色彩和故事。"},{"en":"She believed it could help create a national Australian art.","zh":"她相信它可以幫助創造澳洲民族藝術。"},{"en":"Her engagement with it became increasingly prominent.","zh":"她對它的運用變得越來越突出。"},{"en":"The phrase identifies a major source of her later style.","zh":"這個詞組指出她後期風格的主要來源。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":12},{"front":"create her own art","meaning":"創作自己的藝術","examples":[{"en":"She drew on Aboriginal art to create her own art.","zh":"她借鑑澳洲原住民藝術來創作自己的藝術。"},{"en":"Create her own art means produce personal original artworks.","zh":"創作自己的藝術是指產生個人原創作品。"},{"en":"Preston used existing traditions but transformed them into her own style.","zh":"Preston 使用既有傳統，但把它們轉化成自己的風格。"},{"en":"Her art combined Australian, Aboriginal, and Chinese influences.","zh":"她的藝術結合澳洲、原住民和中國影響。"},{"en":"The phrase describes artistic independence.","zh":"這個詞組描述藝術自主性。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":12},{"front":"at the age of","meaning":"在……歲時","examples":[{"en":"At the age of 78, Preston produced her most significant prints.","zh":"在78歲時，Preston 創作了她最重要的版畫。"},{"en":"At the age of means when someone was a particular age.","zh":"在某歲時是指某人處於特定年齡時。"},{"en":"Preston remained productive at the age of 78.","zh":"Preston 在78歲時仍然多產。"},{"en":"This detail shows that age did not stop her creativity.","zh":"這個細節顯示年齡沒有阻止她的創造力。"},{"en":"The phrase gives a precise biographical moment.","zh":"這個詞組提供精確傳記時刻。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":12},{"front":"produce her most significant prints","meaning":"創作她最重要的版畫","examples":[{"en":"Preston produced her most significant prints in 1953.","zh":"Preston 於1953年創作她最重要的版畫。"},{"en":"Produce her most significant prints means create her most important printed artworks.","zh":"創作她最重要的版畫，是指製作她最具分量的印刷藝術作品。"},{"en":"These prints were shown at Macquarie Galleries.","zh":"這些版畫在 Macquarie Galleries 展出。"},{"en":"They used the ancient technique of stencilling.","zh":"它們使用古老的模版印刷技法。"},{"en":"The phrase marks a major late achievement.","zh":"這個詞組標誌她晚期的重要成就。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":12},{"front":"exhibition at","meaning":"在……舉行的展覽","examples":[{"en":"The exhibition at Macquarie Galleries included 29 prints.","zh":"在 Macquarie Galleries 舉行的展覽包括29幅版畫。"},{"en":"Exhibition at a place means an art display held there.","zh":"在某地舉行的展覽是指在該處展示藝術作品。"},{"en":"Preston’s 1953 exhibition at Macquarie Galleries was important.","zh":"Preston 1953年在 Macquarie Galleries 的展覽很重要。"},{"en":"The exhibition showed many of her significant late prints.","zh":"這次展覽展示了她許多重要晚期版畫。"},{"en":"The phrase identifies the venue of an art event.","zh":"這個詞組指出藝術活動的地點。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":12},{"front":"Macquarie Galleries","meaning":"Macquarie Galleries 畫廊","examples":[{"en":"Her 1953 exhibition was held at Macquarie Galleries in Sydney.","zh":"她1953年的展覽在悉尼 Macquarie Galleries 畫廊舉行。"},{"en":"Macquarie Galleries was the venue for Preston’s major late exhibition.","zh":"Macquarie Galleries 是 Preston 重要晚期展覽的場地。"},{"en":"The exhibition included 29 prints.","zh":"這次展覽包括29幅版畫。"},{"en":"These works were made using stencilling.","zh":"這些作品使用模版印刷製作。"},{"en":"The phrase names an important Sydney gallery in her career.","zh":"這個詞組指出她事業中的重要悉尼畫廊。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":12},{"front":"made using","meaning":"使用……製作","examples":[{"en":"The prints were made using the ancient technique of stencilling.","zh":"這些版畫使用古老的模版印刷技法製作。"},{"en":"Made using means created with a particular method or material.","zh":"使用某方法製作是指以特定方法或材料創作。"},{"en":"Preston’s late prints were made using stencils.","zh":"Preston 的晚期版畫使用模板製作。"},{"en":"Many artworks are made using more than one technique.","zh":"許多藝術作品使用不止一種技法製作。"},{"en":"The phrase explains the method of production.","zh":"這個詞組解釋製作方法。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":12},{"front":"ancient technique","meaning":"古老技法","examples":[{"en":"Stencilling is described as an ancient technique.","zh":"模版印刷被描述為一種古老技法。"},{"en":"An ancient technique is a very old method of making something.","zh":"古老技法是製作某物的非常古老方法。"},{"en":"Preston used this old method in a modern artistic context.","zh":"Preston 在現代藝術背景中使用這種古老方法。"},{"en":"The technique suited her interest in pattern and symbol.","zh":"這種技法符合她對圖案和符號的興趣。"},{"en":"The phrase highlights historical depth in her method.","zh":"這個詞組突出其方法的歷史深度。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":12},{"front":"be known as","meaning":"被稱為","examples":[{"en":"The ancient technique is known as stencilling.","zh":"這種古老技法被稱為模版印刷。"},{"en":"Be known as means be called by a particular name.","zh":"被稱為是指以某個特定名稱叫作。"},{"en":"This technique is known as stencilling because it uses cut-out templates.","zh":"這種技法因使用鏤空模板而被稱為 stencilling。"},{"en":"Preston’s late prints used the method known as stencilling.","zh":"Preston 的晚期版畫使用被稱為模版印刷的方法。"},{"en":"The phrase introduces a term.","zh":"這個詞組引入術語。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":13},{"front":"stencilling","meaning":"模版印刷；鏤空模板技法","examples":[{"en":"Preston used stencilling to make some of her most important prints.","zh":"Preston 使用模版印刷創作她一些最重要的版畫。"},{"en":"Stencilling is a technique that uses cut-out shapes to apply colour or design.","zh":"模版印刷是一種利用鏤空形狀上色或製作設計的技法。"},{"en":"It suited Preston’s interest in bold shapes and symbols.","zh":"它適合 Preston 對大膽形狀和符號的興趣。"},{"en":"Her 1953 exhibition included prints made with stencilling.","zh":"她1953年的展覽包括使用模版印刷製作的版畫。"},{"en":"The phrase names an ancient printmaking method.","zh":"這個詞組指出一種古老版畫技法。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":13},{"front":"incorporate","meaning":"融入；包含","examples":[{"en":"Many artworks incorporated her fusion of Aboriginal and Chinese concepts.","zh":"許多作品融入了她對澳洲原住民與中國概念的融合。"},{"en":"To incorporate something means to include it as part of a work.","zh":"融入某物是指把它作為作品的一部分包含進去。"},{"en":"Preston incorporated Aboriginal symbols into her prints.","zh":"Preston 把澳洲原住民符號融入版畫。"},{"en":"She also incorporated Chinese ideas into later works.","zh":"她也把中國思想融入後期作品。"},{"en":"The phrase describes combining influences within art.","zh":"這個詞組描述在藝術中結合影響。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":13},{"front":"fusion of","meaning":"……的融合","examples":[{"en":"Her later works showed a fusion of Aboriginal and Chinese concepts.","zh":"她後來的作品顯示澳洲原住民與中國概念的融合。"},{"en":"Fusion of two things means a blending or combination of them.","zh":"兩者的融合是指把它們混合或結合。"},{"en":"Preston’s art fused Aboriginal symbols with Chinese design ideas.","zh":"Preston 的藝術把原住民符號與中國設計思想融合。"},{"en":"This fusion helped create her distinctive late style.","zh":"這種融合幫助形成她獨特的晚期風格。"},{"en":"The phrase describes creative combination.","zh":"這個詞組描述創意結合。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":13},{"front":"Aboriginal and Chinese concepts","meaning":"澳洲原住民與中國概念","examples":[{"en":"Preston combined Aboriginal and Chinese concepts in her later works.","zh":"Preston 在後期作品中結合澳洲原住民與中國概念。"},{"en":"Aboriginal and Chinese concepts influenced her symbols, colours, and compositions.","zh":"澳洲原住民與中國概念影響她的符號、色彩和構圖。"},{"en":"She admired Chinese art and also studied Aboriginal sources.","zh":"她欣賞中國藝術，也研究澳洲原住民來源。"},{"en":"These concepts came together in her significant late prints.","zh":"這些概念在她重要晚期版畫中結合。"},{"en":"The phrase names two major cultural influences.","zh":"這個詞組指出兩項主要文化影響。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":13},{"front":"admire Chinese art","meaning":"欣賞中國藝術","examples":[{"en":"Preston had admired Chinese art since 1915.","zh":"Preston 自1915年起已欣賞中國藝術。"},{"en":"Admire Chinese art means appreciate and value Chinese artistic traditions.","zh":"欣賞中國藝術是指重視並喜愛中國藝術傳統。"},{"en":"Her admiration led her to collect books on Chinese art.","zh":"她的欣賞促使她收藏關於中國藝術的書籍。"},{"en":"Chinese elements appeared in several earlier paintings.","zh":"中國元素出現在她幾幅較早期畫作中。"},{"en":"The phrase identifies a long-standing artistic interest.","zh":"這個詞組指出一項長期藝術興趣。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":13},{"front":"acquire the first of","meaning":"取得第一本……","examples":[{"en":"She acquired the first of her many books on Chinese art in 1915.","zh":"她於1915年取得第一本關於中國藝術的書。"},{"en":"Acquire the first of something means obtain the first item in a later larger collection.","zh":"取得第一本某物，是指獲得後來更大收藏中的第一件。"},{"en":"Preston’s first book on Chinese art began a wider interest.","zh":"Preston 第一本中國藝術書開啟了更廣泛的興趣。"},{"en":"She later collected many books on the subject.","zh":"她後來收藏了許多關於該主題的書。"},{"en":"The phrase marks the beginning of a collection.","zh":"這個詞組標誌收藏的開始。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":13},{"front":"books on the subject","meaning":"關於該主題的書籍","examples":[{"en":"She collected many books on the subject of Chinese art.","zh":"她收藏了許多關於中國藝術這一主題的書籍。"},{"en":"Books on the subject means books about that topic.","zh":"關於該主題的書籍是指討論那個題目的書。"},{"en":"Preston’s books on Chinese art helped deepen her understanding.","zh":"Preston 關於中國藝術的書幫助加深她的理解。"},{"en":"Such books may have influenced her later fusion of ideas.","zh":"這些書可能影響她後來對概念的融合。"},{"en":"The phrase refers to written sources of inspiration.","zh":"這個詞組指書面靈感來源。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":13},{"front":"visit China on two occasions","meaning":"兩次到訪中國","examples":[{"en":"Preston visited China on two occasions.","zh":"Preston 兩次到訪中國。"},{"en":"Visit China on two occasions means travel to China twice.","zh":"兩次到訪中國是指前往中國兩次。"},{"en":"These visits strengthened her direct contact with Chinese art and culture.","zh":"這些旅程加強她與中國藝術和文化的直接接觸。"},{"en":"Her interest in Chinese art had begun before these visits.","zh":"她對中國藝術的興趣在這些旅程前已開始。"},{"en":"The phrase describes repeated travel experience.","zh":"這個詞組描述重複旅行經驗。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":13},{"front":"Chinese elements","meaning":"中國元素","examples":[{"en":"Chinese elements may be found in several earlier paintings.","zh":"中國元素可在她幾幅較早期畫作中找到。"},{"en":"Chinese elements are visual or conceptual features influenced by Chinese art.","zh":"中國元素是受中國藝術影響的視覺或概念特徵。"},{"en":"Preston later combined Chinese ideas with Aboriginal creation stories.","zh":"Preston 後來把中國思想與原住民創世故事結合。"},{"en":"These elements formed part of her broader artistic fusion.","zh":"這些元素構成她更廣泛藝術融合的一部分。"},{"en":"The phrase identifies Chinese influence within her works.","zh":"這個詞組指出她作品中的中國影響。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":13},{"front":"may be found in","meaning":"可在……中找到","examples":[{"en":"Chinese elements may be found in several of her earlier paintings.","zh":"中國元素可在她幾幅較早期畫作中找到。"},{"en":"May be found in means can be seen or identified there.","zh":"可在某處找到是指可在那裏看見或識別。"},{"en":"Aboriginal symbols may be found in many of her later prints.","zh":"澳洲原住民符號可在她許多後期版畫中找到。"},{"en":"The phrase points to visible evidence within artworks.","zh":"這個詞組指作品中的可見證據。"},{"en":"It describes where an influence appears.","zh":"它描述影響出現的位置。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":13},{"front":"combine Chinese ideas with","meaning":"將中國思想與……結合","examples":[{"en":"Preston combined Chinese ideas with Aboriginal creation stories.","zh":"Preston 將中國思想與澳洲原住民創世故事結合。"},{"en":"Combine Chinese ideas with something means bring Chinese concepts together with another source.","zh":"將中國思想與某物結合，是指把中國概念和另一來源放在一起。"},{"en":"Her late works combined Chinese design ideas with Aboriginal themes.","zh":"她的晚期作品把中國設計思想與原住民主題結合。"},{"en":"This combination helped create a distinctive visual language.","zh":"這種結合幫助創造獨特視覺語言。"},{"en":"The phrase describes cross-cultural artistic synthesis.","zh":"這個詞組描述跨文化藝術綜合。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":14},{"front":"understanding of","meaning":"對……的理解","examples":[{"en":"Her prints reflected her understanding of Aboriginal creation stories.","zh":"她的版畫反映她對澳洲原住民創世故事的理解。"},{"en":"Understanding of something means knowledge or interpretation of it.","zh":"對某事的理解是指對它的知識或詮釋。"},{"en":"Preston’s understanding of Aboriginal art shaped her late prints.","zh":"Preston 對澳洲原住民藝術的理解塑造了她的晚期版畫。"},{"en":"Her titles often show the sources of this understanding.","zh":"她的標題常顯示這種理解的來源。"},{"en":"The phrase describes knowledge behind artistic choices.","zh":"這個詞組描述藝術選擇背後的知識。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":14},{"front":"Dreamtime creation stories","meaning":"Dreamtime 創世故事","examples":[{"en":"Preston used Dreamtime creation stories in her later prints.","zh":"Preston 在晚期版畫中使用 Dreamtime 創世故事。"},{"en":"Dreamtime creation stories are Aboriginal stories about origins and creation.","zh":"Dreamtime 創世故事是澳洲原住民關於起源和創造的故事。"},{"en":"These stories influenced the themes of some of her late works.","zh":"這些故事影響她部分晚期作品的主題。"},{"en":"Preston combined them with Chinese ideas in her art.","zh":"Preston 在藝術中把它們與中國思想結合。"},{"en":"The phrase identifies an Aboriginal cultural source.","zh":"這個詞組指出一項澳洲原住民文化來源。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":14},{"front":"Aboriginal Australians","meaning":"澳洲原住民","examples":[{"en":"Dreamtime stories belong to Aboriginal Australians.","zh":"Dreamtime 故事屬於澳洲原住民。"},{"en":"Aboriginal Australians are the Indigenous peoples of Australia.","zh":"澳洲原住民是澳洲的原住民族群。"},{"en":"Preston studied Aboriginal Australian art and sites.","zh":"Preston 研究澳洲原住民藝術和遺址。"},{"en":"Their symbols and stories influenced her later works.","zh":"他們的符號和故事影響她的後期作品。"},{"en":"The phrase identifies the people whose traditions she engaged with.","zh":"這個詞組指出她所接觸傳統的族群。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":14},{"front":"did not let age alter","meaning":"沒有讓年齡改變……","examples":[{"en":"Preston did not let age alter her habit of working hard.","zh":"Preston 沒有讓年齡改變她努力工作的習慣。"},{"en":"Did not let age alter something means did not allow getting older to change it.","zh":"沒有讓年齡改變某事，是指沒有讓變老改變它。"},{"en":"Even in old age, she continued painting, printmaking, and travelling.","zh":"即使年老，她仍繼續繪畫、製作版畫和旅行。"},{"en":"The phrase shows her determination and energy.","zh":"這個詞組顯示她的決心和活力。"},{"en":"It introduces the persistence of her later career.","zh":"它引出她晚年事業的持續性。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":14},{"front":"habit of working hard","meaning":"努力工作的習慣","examples":[{"en":"She kept her habit of working hard into old age.","zh":"她到晚年仍保持努力工作的習慣。"},{"en":"A habit of working hard is a regular pattern of serious effort.","zh":"努力工作的習慣是指持續認真付出的固定模式。"},{"en":"Preston’s long career shows this habit clearly.","zh":"Preston 漫長的事業清楚顯示這種習慣。"},{"en":"She produced important prints at the age of 78.","zh":"她在78歲時創作重要版畫。"},{"en":"The phrase describes her discipline as an artist.","zh":"這個詞組描述她作為藝術家的自律。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":14},{"front":"as she got older","meaning":"隨着她年紀漸長","examples":[{"en":"As she got older, her love of painting, printmaking and travel continued.","zh":"隨着她年紀漸長，她對繪畫、版畫和旅行的熱愛仍然持續。"},{"en":"As she got older means during the process of ageing.","zh":"隨着她年紀漸長，是指在變老的過程中。"},{"en":"Preston did not stop working as she got older.","zh":"Preston 年紀漸長時並沒有停止工作。"},{"en":"Her artistic interests remained active in later life.","zh":"她晚年仍保持活躍的藝術興趣。"},{"en":"The phrase links ageing with continued creativity.","zh":"這個詞組把年齡增長與持續創造力連接起來。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":14},{"front":"love of painting, printmaking and travel","meaning":"對繪畫、版畫和旅行的熱愛","examples":[{"en":"Her love of painting, printmaking and travel continued.","zh":"她對繪畫、版畫和旅行的熱愛仍然持續。"},{"en":"Love of painting, printmaking and travel means strong interest in these activities.","zh":"對繪畫、版畫和旅行的熱愛是指對這些活動有強烈興趣。"},{"en":"Preston’s later life still included artistic production and journeys.","zh":"Preston 的晚年仍包括藝術創作和旅行。"},{"en":"This love helped sustain her long career.","zh":"這種熱愛支撐了她漫長的事業。"},{"en":"The phrase describes three lasting passions.","zh":"這個詞組描述三項持久熱情。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":14},{"front":"by the time of her death","meaning":"到她去世時","examples":[{"en":"By the time of her death in 1963, she had produced over 400 works.","zh":"到她1963年去世時，她已創作超過400件作品。"},{"en":"By the time of her death means before or up to the moment she died.","zh":"到她去世時是指在她死亡之前或到死亡那一刻為止。"},{"en":"The phrase summarises what she had achieved by the end of her life.","zh":"這個詞組概括她一生結束前已達成的成就。"},{"en":"Preston’s output was large by the time of her death.","zh":"到她去世時，Preston 的作品數量很大。"},{"en":"It gives a final measure of her productivity.","zh":"它提供她生產力的最終衡量。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":14},{"front":"produce over 400 paintings and prints","meaning":"創作超過400幅畫作和版畫","examples":[{"en":"Preston produced over 400 paintings and prints.","zh":"Preston 創作超過400幅畫作和版畫。"},{"en":"Produce over 400 paintings and prints means create more than 400 artworks in these forms.","zh":"創作超過400幅畫作和版畫，是指創造超過400件這類藝術作品。"},{"en":"This output shows her long-term discipline and creativity.","zh":"這個產量顯示她長期自律和創造力。"},{"en":"Her works included both paintings and printmaking.","zh":"她的作品包括畫作和版畫。"},{"en":"The phrase gives the scale of her artistic achievement.","zh":"這個詞組顯示她藝術成就的規模。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":14},{"front":"career spanning almost 60 years","meaning":"橫跨近60年的事業","examples":[{"en":"She had a career spanning almost 60 years.","zh":"她擁有橫跨近60年的事業。"},{"en":"A career spanning almost 60 years lasts nearly six decades.","zh":"橫跨近60年的事業是指持續將近六十年的職業生涯。"},{"en":"Preston’s long career covered many stylistic changes.","zh":"Preston 的漫長事業涵蓋許多風格變化。"},{"en":"Her career extended from early naturalism to late symbolic prints.","zh":"她的事業從早期自然主義延伸到晚期象徵版畫。"},{"en":"The phrase emphasises duration and persistence.","zh":"這個詞組強調時間長度和堅持。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":14},{"front":"a body of work","meaning":"一系列作品","examples":[{"en":"Preston created a body of work that showed great originality.","zh":"Preston 創作了一系列展現高度原創性的作品。"},{"en":"A body of work is a collection of artworks produced over time.","zh":"一系列作品是藝術家隨時間創作的作品集合。"},{"en":"Her body of work included paintings, prints, and designs.","zh":"她的一系列作品包括畫作、版畫和設計。"},{"en":"It demonstrates her evolving ideas about Australian art.","zh":"它展現她對澳洲藝術觀念的發展。"},{"en":"The phrase refers to her total artistic production.","zh":"這個詞組指她的整體藝術創作。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":15},{"front":"demonstrate her extraordinary originality","meaning":"展現她非凡的原創性","examples":[{"en":"Her work demonstrates her extraordinary originality.","zh":"她的作品展現她非凡的原創性。"},{"en":"Demonstrate her extraordinary originality means clearly show her unusual creative independence.","zh":"展現她非凡的原創性是指清楚顯示她異常的創造獨立性。"},{"en":"Preston’s fusion of different traditions demonstrates originality.","zh":"Preston 對不同傳統的融合展現原創性。"},{"en":"Her bold use of Australian subjects also shows original vision.","zh":"她大膽使用澳洲題材也顯示原創眼光。"},{"en":"The phrase praises the distinctive quality of her work.","zh":"這個詞組讚揚她作品的獨特品質。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":15},{"front":"intensity of her commitment to","meaning":"對……投入之深","examples":[{"en":"Her career shows the intensity of her commitment to Australian art.","zh":"她的事業顯示她對澳洲藝術投入之深。"},{"en":"Intensity of her commitment to something means the strength of her dedication to it.","zh":"對某事投入之深，是指她對該事奉獻的強度。"},{"en":"Preston’s long career shows deep commitment to national artistic identity.","zh":"Preston 漫長的事業顯示她對民族藝術身份的深切投入。"},{"en":"Her study of native flora and Aboriginal art reflected this commitment.","zh":"她研究本土植物和原住民藝術反映這種投入。"},{"en":"The phrase describes the seriousness of her artistic purpose.","zh":"這個詞組描述她藝術目標的認真程度。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":15},{"front":"Australian art","meaning":"澳洲藝術","examples":[{"en":"Preston made a major contribution to Australian art.","zh":"Preston 對澳洲藝術作出重大貢獻。"},{"en":"Australian art was the central national project of her career.","zh":"澳洲藝術是她事業中的核心民族藝術工程。"},{"en":"She wanted Australian art to reflect the country’s ancient continent and cultures.","zh":"她希望澳洲藝術反映這個國家的古老大陸和文化。"},{"en":"Native flora and Aboriginal sources helped shape her version of Australian art.","zh":"本土植物和澳洲原住民來源幫助塑造她心目中的澳洲藝術。"},{"en":"The phrase names the field to which she was deeply committed.","zh":"這個詞組指出她深切投入的領域。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":15},{"front":"agree with the information given","meaning":"與文中資料一致","examples":[{"en":"Students decide whether the statements agree with the information given in the passage.","zh":"學生判斷陳述是否與文中資料一致。"},{"en":"Agree with the information given means match what the text says.","zh":"與文中資料一致是指與文本所說內容相符。"},{"en":"Students should compare each statement carefully with the passage.","zh":"學生應仔細把每項陳述與文章比較。"},{"en":"The answer should be based only on the information given.","zh":"答案應只根據文中資料。"},{"en":"The phrase belongs to reading-comprehension instructions.","zh":"這個詞組屬於閱讀理解指示。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":15},{"front":"contradict the information","meaning":"與資料相矛盾","examples":[{"en":"A FALSE answer means the statement contradicts the information.","zh":"FALSE 答案表示該陳述與資料相矛盾。"},{"en":"Contradict the information means state the opposite of what the passage says.","zh":"與資料相矛盾是指說出與文章相反的內容。"},{"en":"If the text says she met William on a boat, another claim may contradict it.","zh":"如果文本說她在船上遇見 William，另一種說法可能與之矛盾。"},{"en":"Students must identify clear disagreement with the passage.","zh":"學生必須識別與文章的清楚不一致。"},{"en":"The phrase explains the meaning of FALSE.","zh":"這個詞組解釋 FALSE 的意思。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":15},{"front":"no information on this","meaning":"沒有相關資料","examples":[{"en":"NOT GIVEN means there is no information on this.","zh":"NOT GIVEN 表示沒有相關資料。"},{"en":"No information on this means the passage does not confirm or deny the statement.","zh":"沒有相關資料是指文章沒有確認或否定該陳述。"},{"en":"Students should not use outside knowledge to answer.","zh":"學生不應使用外部知識作答。"},{"en":"Related details may not be enough to prove the statement.","zh":"相關細節未必足以證明該陳述。"},{"en":"The phrase explains when to choose NOT GIVEN.","zh":"這個詞組解釋何時選擇 NOT GIVEN。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":15},{"front":"portray nature realistically","meaning":"寫實地描繪自然","examples":[{"en":"Artists in the German aesthetic tradition portrayed nature realistically.","zh":"德國美學傳統中的藝術家寫實地描繪自然。"},{"en":"To portray nature realistically means to show natural subjects in a true-to-life way.","zh":"寫實地描繪自然是指以逼真方式呈現自然題材。"},{"en":"Preston’s early artwork followed this realistic approach.","zh":"Preston 的早期藝術作品遵循這種寫實方法。"},{"en":"Later, her work became more decorative and symbolic.","zh":"後來，她的作品變得更具裝飾性和象徵性。"},{"en":"The phrase describes naturalistic representation.","zh":"這個詞組描述自然主義表現。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":15},{"front":"famous art college","meaning":"著名藝術學院","examples":[{"en":"The statement asks whether Margaret attended a famous art college in Paris.","zh":"該陳述詢問 Margaret 是否曾在巴黎就讀著名藝術學院。"},{"en":"A famous art college is a well-known institution for art education.","zh":"著名藝術學院是知名的藝術教育機構。"},{"en":"The passage mentions studies in Paris but does not necessarily name a famous college there.","zh":"文章提到她在巴黎學習，但未必指明那裏的著名學院。"},{"en":"Students must check whether the text supports this claim.","zh":"學生必須檢查文本是否支持這個說法。"},{"en":"The phrase appears in a reading-test statement.","zh":"這個詞組出現在閱讀測驗陳述中。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":15},{"front":"while teaching a craft at","meaning":"在……教授工藝期間","examples":[{"en":"The question mentions meeting William while teaching a craft at a rehabilitation unit.","zh":"題目提到在康復中心教授工藝期間遇見 William。"},{"en":"While teaching a craft at a place means during the time she was instructing a practical skill there.","zh":"在某地教授工藝期間，是指在那裏教授實用技能的時候。"},{"en":"The passage says she met William on board a boat returning to Australia.","zh":"文章說她是在返回澳洲的船上遇見 William。"},{"en":"Students should compare this wording with the source text carefully.","zh":"學生應仔細把這種措辭與原文比較。"},{"en":"The phrase is part of a true-false reading statement.","zh":"這個詞組是判斷題陳述的一部分。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":15},{"front":"explore similar themes","meaning":"探索相似主題","examples":[{"en":"The statement asks whether Preston and Thea Proctor explored similar themes.","zh":"該陳述詢問 Preston 和 Thea Proctor 是否探索相似主題。"},{"en":"Explore similar themes means work with related subjects or ideas.","zh":"探索相似主題是指處理相關題材或想法。"},{"en":"The passage says they had a major showing together.","zh":"文章說她們共同舉辦大型展出。"},{"en":"It may not state whether their themes were similar.","zh":"它未必說明她們的主題是否相似。"},{"en":"The phrase requires evidence before choosing TRUE.","zh":"這個詞組需要證據才能選 TRUE。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":15},{"front":"artworks of Sydney Harbour","meaning":"悉尼港藝術作品","examples":[{"en":"Some of Preston’s artworks of Sydney Harbour were shown in 1925.","zh":"Preston 部分悉尼港藝術作品於1925年展出。"},{"en":"Artworks of Sydney Harbour are works depicting the harbour and its surroundings.","zh":"悉尼港藝術作品是描繪海港及其周邊的作品。"},{"en":"Harbour views were prominent in her 1925 exhibitions.","zh":"海港景色在她1925年的展覽中很突出。"},{"en":"These works often included boats and foreshore hills.","zh":"這些作品常包括船隻和海濱山坡。"},{"en":"The phrase identifies a subject in her Sydney-period art.","zh":"這個詞組指出她悉尼時期藝術中的題材。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":16},{"front":"simpler than","meaning":"比……更簡單","examples":[{"en":"The statement asks whether her 1925 harbour artworks were simpler than earlier ones.","zh":"該陳述詢問她1925年的海港作品是否比早期作品更簡單。"},{"en":"Simpler than means less complex or less detailed than something else.","zh":"比某物更簡單是指較不複雜或較少細節。"},{"en":"The passage describes the later harbour prints as compact and busy.","zh":"文章把後來的海港版畫描述為緊湊而繁複。"},{"en":"Therefore, students must compare the statement with the text carefully.","zh":"因此，學生必須仔細把陳述與文本比較。"},{"en":"The phrase introduces a comparison of complexity.","zh":"這個詞組引出複雜程度的比較。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":16},{"front":"natural setting","meaning":"自然環境","examples":[{"en":"The question asks whether Margaret painted flowers in their natural setting.","zh":"題目詢問 Margaret 是否在自然環境中描繪花卉。"},{"en":"Natural setting means the place where something grows or exists naturally.","zh":"自然環境是某物自然生長或存在的地方。"},{"en":"At Berowra, Preston painted flowers growing wild.","zh":"在 Berowra，Preston 描繪野外生長的花。"},{"en":"This differed from arranging flowers in vases.","zh":"這不同於把花插放在花瓶中。"},{"en":"The phrase describes a non-artificial environment.","zh":"這個詞組描述非人工環境。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":16},{"front":"complete the notes below","meaning":"完成以下筆記","examples":[{"en":"Students complete the notes below using words from the passage.","zh":"學生使用文章中的詞語完成以下筆記。"},{"en":"Complete the notes below means fill in missing information in a note summary.","zh":"完成以下筆記是指在筆記摘要中填上缺少資料。"},{"en":"The answers must come from the passage.","zh":"答案必須來自文章。"},{"en":"Students should follow the word limit carefully.","zh":"學生應仔細遵守字數限制。"},{"en":"The phrase introduces a note-completion task.","zh":"這個詞組引出筆記填充題。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":16},{"front":"one word and/or a number","meaning":"一個詞及／或一個數字","examples":[{"en":"Students should choose one word and/or a number from the passage.","zh":"學生應從文章中選擇一個詞及／或一個數字。"},{"en":"One word and/or a number means the answer may contain one word, one number, or both if allowed.","zh":"一個詞及／或一個數字是指答案可包含一個詞、一個數字，或在允許下兩者兼有。"},{"en":"A longer phrase would not follow the instruction.","zh":"較長詞組不符合指示。"},{"en":"Students must count words carefully.","zh":"學生必須仔細計算詞數。"},{"en":"The phrase gives the exact answer limit.","zh":"這個詞組提供精確答案限制。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":16},{"front":"later life","meaning":"晚年","examples":[{"en":"The notes focus on Margaret Preston’s later life.","zh":"這些筆記集中於 Margaret Preston 的晚年。"},{"en":"Later life means the later part of a person’s life or career.","zh":"晚年是指一個人人生或事業較後的部分。"},{"en":"Preston’s later life included major prints and continued travel.","zh":"Preston 晚年包括重要版畫和持續旅行。"},{"en":"She remained committed to art in later life.","zh":"她在晚年仍投入藝術。"},{"en":"The phrase identifies the time period of the notes.","zh":"這個詞組指出筆記的時間範圍。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":16},{"front":"Aboriginal influence","meaning":"澳洲原住民影響","examples":[{"en":"The notes describe the Aboriginal influence on Preston’s art.","zh":"這些筆記描述澳洲原住民影響對 Preston 藝術的作用。"},{"en":"Aboriginal influence means the effect of Aboriginal art, symbols, colours, and stories on her work.","zh":"澳洲原住民影響是指原住民藝術、符號、色彩和故事對她作品的影響。"},{"en":"This influence began strongly after she lived near rock engravings.","zh":"這種影響在她住近岩石雕刻後明顯開始。"},{"en":"It became increasingly prominent in her later prints.","zh":"它在她後期版畫中變得越來越突出。"},{"en":"The phrase names a major theme in her later career.","zh":"這個詞組指出她後期事業的重要主題。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":16},{"front":"be inspired by","meaning":"受……啟發","examples":[{"en":"Her interest in Aboriginal art was inspired by rock engravings.","zh":"她對澳洲原住民藝術的興趣受岩石雕刻啟發。"},{"en":"Be inspired by something means receive creative influence or motivation from it.","zh":"受某事啟發是指從它得到創作影響或動力。"},{"en":"Preston was inspired by Aboriginal rock engravings near her property.","zh":"Preston 受物業附近的澳洲原住民岩石雕刻啟發。"},{"en":"She was also inspired by books about Chinese art.","zh":"她也受關於中國藝術的書籍啟發。"},{"en":"The phrase describes the source of creative ideas.","zh":"這個詞組描述創意來源。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":16},{"front":"incorporate something into","meaning":"將……融入……","examples":[{"en":"She incorporated Aboriginal symbols and colours into her own work.","zh":"她將澳洲原住民符號和色彩融入自己的作品。"},{"en":"Incorporate something into a work means include it as part of that work.","zh":"將某物融入作品是指把它作為作品的一部分。"},{"en":"Preston incorporated Aboriginal sources into her prints.","zh":"Preston 將澳洲原住民來源融入版畫。"},{"en":"She later incorporated Chinese and Aboriginal concepts together.","zh":"她後來把中國與澳洲原住民概念一起融入作品。"},{"en":"The phrase describes artistic integration.","zh":"這個詞組描述藝術整合。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":16},{"front":"refer to","meaning":"提及；指涉","examples":[{"en":"Her artwork titles often refer to Aboriginal sources.","zh":"她的作品標題常提及澳洲原住民來源。"},{"en":"Refer to something means mention, point to, or indicate it.","zh":"提及或指涉某事是指說到、指向或表示它。"},{"en":"Preston’s titles refer to sources that inspired her prints.","zh":"Preston 的標題指涉啟發她版畫的來源。"},{"en":"A title can refer to a story, symbol, or cultural source.","zh":"標題可以指涉故事、符號或文化來源。"},{"en":"The phrase describes how her works acknowledge influence.","zh":"這個詞組描述她作品如何承認影響。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":16},{"front":"Aboriginal sources","meaning":"澳洲原住民來源","examples":[{"en":"Preston often referred to Aboriginal sources in her titles.","zh":"Preston 常在作品標題中提及澳洲原住民來源。"},{"en":"Aboriginal sources are cultural materials, symbols, stories, or artworks from Aboriginal traditions.","zh":"澳洲原住民來源是來自原住民傳統的文化材料、符號、故事或藝術。"},{"en":"These sources influenced her later prints.","zh":"這些來源影響她後來的版畫。"},{"en":"Her titles helped acknowledge these sources.","zh":"她的標題幫助承認這些來源。"},{"en":"The phrase identifies the origin of some of her inspiration.","zh":"這個詞組指出她部分靈感的來源。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":16},{"front":"the very old method of","meaning":"……這種古老方法","examples":[{"en":"The very old method of stencilling was used for some prints.","zh":"模版印刷這種古老方法被用於一些版畫。"},{"en":"The very old method of something means an ancient technique or practice.","zh":"某種古老方法是指古老的技術或做法。"},{"en":"Preston used the very old method of stencilling in significant late works.","zh":"Preston 在重要晚期作品中使用模版印刷這種古老方法。"},{"en":"This method suited her interest in symbols and strong shapes.","zh":"這種方法適合她對符號和強烈形狀的興趣。"},{"en":"The phrase describes a traditional technique.","zh":"這個詞組描述傳統技法。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":17},{"front":"be inspired by books about","meaning":"受關於……的書籍啟發","examples":[{"en":"Preston was inspired by books about Chinese art.","zh":"Preston 受關於中國藝術的書籍啟發。"},{"en":"Be inspired by books about a subject means gain ideas from reading those books.","zh":"受關於某主題的書籍啟發，是指從閱讀這些書得到想法。"},{"en":"Her first book on Chinese art was acquired in 1915.","zh":"她於1915年取得第一本中國藝術書。"},{"en":"Books helped build her long interest in Chinese art.","zh":"書籍幫助建立她對中國藝術的長期興趣。"},{"en":"The phrase describes written sources of artistic influence.","zh":"這個詞組描述書面藝術影響來源。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":17},{"front":"combine Chinese and Aboriginal elements","meaning":"結合中國與澳洲原住民元素","examples":[{"en":"Preston combined Chinese and Aboriginal elements in her work.","zh":"Preston 在作品中結合中國與澳洲原住民元素。"},{"en":"Combine Chinese and Aboriginal elements means bring features from both traditions together.","zh":"結合中國與澳洲原住民元素是指把兩種傳統的特徵放在一起。"},{"en":"Her late prints fused Chinese ideas with Aboriginal creation stories.","zh":"她的晚期版畫把中國思想與原住民創世故事融合。"},{"en":"This combination became part of her original style.","zh":"這種結合成為她原創風格的一部分。"},{"en":"The phrase describes her cross-cultural artistic method.","zh":"這個詞組描述她的跨文化藝術方法。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":17},{"front":"remain interested in","meaning":"仍然對……感興趣","examples":[{"en":"She remained interested in travel and art in old age.","zh":"她晚年仍然對旅行和藝術感興趣。"},{"en":"Remain interested in something means continue to care about or enjoy it.","zh":"仍然對某事感興趣是指繼續關心或享受它。"},{"en":"Preston remained interested in painting, printmaking, and travel as she got older.","zh":"Preston 年紀漸長時仍對繪畫、版畫和旅行感興趣。"},{"en":"Her continued interest helped sustain her long career.","zh":"她持續的興趣支撐了漫長事業。"},{"en":"The phrase describes lasting enthusiasm.","zh":"這個詞組描述持久熱情。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":17},{"front":"nearly six decades","meaning":"近六十年","examples":[{"en":"Preston worked for nearly six decades.","zh":"Preston 工作了近六十年。"},{"en":"Nearly six decades means almost sixty years.","zh":"近六十年是指差不多六十年。"},{"en":"Her career spanning nearly six decades showed great persistence.","zh":"她橫跨近六十年的事業顯示極大堅持。"},{"en":"Across nearly six decades, her style changed and developed.","zh":"在近六十年間，她的風格不斷改變和發展。"},{"en":"The phrase gives the length of her artistic career.","zh":"這個詞組提供她藝術事業的長度。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":17},{"front":"more than 400 artworks","meaning":"超過400件藝術作品","examples":[{"en":"She created more than 400 artworks.","zh":"她創作超過400件藝術作品。"},{"en":"More than 400 artworks means over four hundred works of art.","zh":"超過400件藝術作品是指多於四百件作品。"},{"en":"This number shows Preston’s productivity.","zh":"這個數字顯示 Preston 的創作力。"},{"en":"Her artworks included paintings and prints.","zh":"她的作品包括畫作和版畫。"},{"en":"The phrase gives a quantitative summary of her output.","zh":"這個詞組以數量概括她的產出。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":17},{"front":"long career","meaning":"漫長事業","examples":[{"en":"Her long career demonstrates her originality and dedication.","zh":"她的漫長事業展現她的原創性和奉獻。"},{"en":"A long career is a professional life lasting many years.","zh":"漫長事業是持續多年的專業人生。"},{"en":"Preston’s long career lasted almost 60 years.","zh":"Preston 的漫長事業持續近60年。"},{"en":"It included early naturalism, decorative prints, and late cultural fusion.","zh":"它包括早期自然主義、裝飾性版畫和晚期文化融合。"},{"en":"The phrase describes the duration and richness of her work.","zh":"這個詞組描述她工作的長度和豐富性。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":17},{"front":"dedication to","meaning":"對……的奉獻","examples":[{"en":"Her career shows her dedication to Australian art.","zh":"她的事業顯示她對澳洲藝術的奉獻。"},{"en":"Dedication to something means strong commitment and loyalty to it.","zh":"對某事的奉獻是指對它有強烈投入和忠誠。"},{"en":"Preston’s dedication to Australian art shaped her choice of subjects.","zh":"Preston 對澳洲藝術的奉獻塑造了她的題材選擇。"},{"en":"Her use of native flowers and Aboriginal sources reflected this dedication.","zh":"她使用本土花卉和澳洲原住民來源反映這種奉獻。"},{"en":"The phrase describes her serious commitment to a national artistic vision.","zh":"這個詞組描述她對民族藝術願景的認真投入。"}],"source":"Passage 2 Flash Cards 169 - Australian artist Margaret Preston.pdf","sourcePage":17}],"ielts/reading/passage-2/Practice 170":[{"front":"adaptation to habitat change","meaning":"對棲息地變化的適應","examples":[{"en":"The passage explains Australian parrots’ adaptation to habitat change.","zh":"文章解釋澳洲鸚鵡對棲息地變化的適應。"},{"en":"Adaptation to habitat change means the way animals or plants adjust when their living environment changes.","zh":"adaptation to habitat change 指動植物在生活環境改變時作出的調整。"},{"en":"Birds may show adaptation to habitat change by eating new foods in parks and gardens.","zh":"鳥類可能透過在公園和花園吃新食物，展現對棲息地變化的適應。"},{"en":"If forests disappear, adaptation to habitat change may help some species survive while others decline.","zh":"如果森林消失，對棲息地變化的適應可能幫助部分物種生存，但其他物種則衰退。"},{"en":"This phrase is often used when living things must change their behaviour, diet, or nesting habits.","zh":"這個短語常用於描述生物必須改變行為、飲食或築巢習慣的情況。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":1},{"front":"be found throughout","meaning":"遍布於……","examples":[{"en":"Parrots are found throughout the tropics.","zh":"鸚鵡遍布於熱帶地區。"},{"en":"To be found throughout a place means to exist or appear in many parts of that area.","zh":"be found throughout 某地，指存在或出現在該地許多部分。"},{"en":"Convenience stores are found throughout many large cities.","zh":"便利店遍布於許多大城市。"},{"en":"When a species is found throughout a region, it is not limited to one small location.","zh":"當一個物種遍布於某地區，它就不是只限於一個小地方。"},{"en":"The phrase describes wide distribution across an area.","zh":"這個短語描述在某範圍內廣泛分布。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":1},{"front":"the tropics","meaning":"熱帶地區","examples":[{"en":"Many parrot species live throughout the tropics.","zh":"許多鸚鵡物種生活在整個熱帶地區。"},{"en":"The tropics are the warm regions of the world near the equator.","zh":"the tropics 指靠近赤道的溫暖地區。"},{"en":"Fruit, insects, and bright flowers are often common in the tropics.","zh":"水果、昆蟲和鮮艷花朵在熱帶地區通常很常見。"},{"en":"Warm temperatures and rich forests make the tropics suitable for many birds.","zh":"溫暖氣溫和豐富森林令熱帶地區適合許多鳥類。"},{"en":"The phrase usually refers to hot, humid regions with abundant plant and animal life.","zh":"這個短語通常指炎熱、潮濕且動植物豐富的地區。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":1},{"front":"Southern Hemisphere continent","meaning":"南半球大陸","examples":[{"en":"Parrots are found on every Southern Hemisphere continent except Antarctica.","zh":"除南極洲外，每個南半球大陸都有鸚鵡。"},{"en":"A Southern Hemisphere continent is a continent located mainly or partly south of the equator.","zh":"Southern Hemisphere continent 指主要或部分位於赤道以南的大陸。"},{"en":"Australia is a Southern Hemisphere continent with many unusual animals.","zh":"澳洲是一個有許多獨特動物的南半球大陸。"},{"en":"Mentioning Southern Hemisphere continents helps explain where certain species naturally occur.","zh":"提及南半球大陸，有助解釋某些物種自然出現的位置。"},{"en":"The phrase places a landmass in the southern half of the Earth.","zh":"這個短語把一塊大陸放在地球南半部的位置上。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":1},{"front":"except Antarctica","meaning":"除南極洲外","examples":[{"en":"Parrots live on every Southern Hemisphere continent except Antarctica.","zh":"除南極洲外，每個南半球大陸都有鸚鵡生活。"},{"en":"Except Antarctica means Antarctica is the only place excluded from the statement.","zh":"except Antarctica 指南極洲是該陳述中唯一被排除的地方。"},{"en":"Students in every class except Class 6A joined the trip.","zh":"除6A班外，每班學生都參加了旅行。"},{"en":"This phrase is useful when one item is different from all the others.","zh":"當一項事物與其他全部不同時，這個短語很有用。"},{"en":"It clearly marks the exception in a general statement.","zh":"它清楚標示一般陳述中的例外。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":1},{"front":"display such richness of","meaning":"展現如此豐富的……","examples":[{"en":"Nowhere do parrots display such richness of diversity and form as in Australia.","zh":"沒有地方的鸚鵡像澳洲那樣展現如此豐富的多樣性和形態。"},{"en":"To display such richness of something means to show an unusually great variety or abundance of it.","zh":"display such richness of 某物，指展現出異常豐富的種類或數量。"},{"en":"A museum may display such richness of local history that visitors need several hours to see it all.","zh":"博物館可能展現如此豐富的本地歷史，以致訪客需要數小時才看完。"},{"en":"Richness of variety can make a place seem especially important for study.","zh":"豐富多樣性可以令一個地方顯得特別值得研究。"},{"en":"The phrase strongly emphasises how much variety is visible.","zh":"這個短語強烈強調可見的多樣性之多。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":1},{"front":"diversity and form","meaning":"多樣性和形態","examples":[{"en":"Australian parrots show remarkable diversity and form.","zh":"澳洲鸚鵡展現出非凡的多樣性和形態。"},{"en":"Diversity and form means variety in types, colours, shapes, sizes, or structures.","zh":"diversity and form 指在類型、顏色、形狀、大小或結構上的多樣。"},{"en":"A garden shows diversity and form when it has tall trees, low flowers, and many leaf shapes.","zh":"當花園有高樹、矮花和多種葉形時，就展現多樣性和形態。"},{"en":"Diversity and form help scientists compare how species adapt to different environments.","zh":"多樣性和形態幫助科學家比較物種如何適應不同環境。"},{"en":"The phrase describes both variety and physical appearance.","zh":"這個短語同時描述種類差異和外形特徵。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":1},{"front":"one-sixth of","meaning":"六分之一的……","examples":[{"en":"One-sixth of the world’s parrot species are found in Australia.","zh":"世界六分之一的鸚鵡物種分布於澳洲。"},{"en":"One-sixth of something means one part out of six equal parts.","zh":"one-sixth of 某物，指六等份中的一份。"},{"en":"If a class has 30 students, one-sixth of the class is 5 students.","zh":"如果一班有30名學生，六分之一就是5名學生。"},{"en":"Fractions such as one-sixth help readers understand proportion rather than only number.","zh":"六分之一這類分數幫助讀者理解比例，而不只是數字。"},{"en":"The phrase gives a clear share of a whole group.","zh":"這個短語清楚表示整體中的一部分。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":1},{"front":"parrot species","meaning":"鸚鵡物種","examples":[{"en":"Australia is home to many parrot species.","zh":"澳洲是許多鸚鵡物種的家園。"},{"en":"Parrot species are different biological kinds of parrots.","zh":"parrot species 指不同生物種類的鸚鵡。"},{"en":"A zoo may teach visitors to identify parrot species by colour, size, and beak shape.","zh":"動物園可能教訪客透過顏色、大小和鳥喙形狀辨認鸚鵡物種。"},{"en":"Protecting many parrot species requires protecting different habitats.","zh":"保護多種鸚鵡物種需要保護不同棲息地。"},{"en":"The phrase refers to the different types of parrots found in nature.","zh":"這個短語指自然界中不同類型的鸚鵡。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":1},{"front":"be renowned for","meaning":"以……聞名","examples":[{"en":"Australia has long been renowned for the variety of its parrots.","zh":"澳洲長久以來以鸚鵡種類繁多聞名。"},{"en":"To be renowned for something means to be famous or well known because of it.","zh":"be renowned for 某事，指因它而著名或廣為人知。"},{"en":"A school may be renowned for excellent music teaching.","zh":"一所學校可能以出色音樂教學聞名。"},{"en":"A place becomes renowned when many people repeatedly associate it with a special feature.","zh":"當許多人反覆把某地與某個特色聯繫起來，它就會聞名。"},{"en":"The phrase describes a strong and positive reputation.","zh":"這個短語描述強烈而正面的名聲。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":1},{"front":"the number and variety of","meaning":"……的數量和種類","examples":[{"en":"Australia is famous for the number and variety of its parrots.","zh":"澳洲以其鸚鵡的數量和種類聞名。"},{"en":"The number and variety of something means both how many there are and how many different kinds exist.","zh":"the number and variety of 某物，指其數量有多少，以及有多少不同種類。"},{"en":"A library may impress visitors with the number and variety of books it offers.","zh":"圖書館提供的書籍數量和種類可能令訪客留下深刻印象。"},{"en":"A high number alone is less meaningful if there is little variety.","zh":"如果種類很少，單是數量高意義就較低。"},{"en":"The phrase combines quantity with diversity.","zh":"這個短語結合數量與多樣性。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":2},{"front":"in the sixteenth century","meaning":"在16世紀","examples":[{"en":"In the sixteenth century, Mercator included a parrot-related place on his map.","zh":"在16世紀，Mercator 在他的地圖上加入一個與鸚鵡有關的地方。"},{"en":"In the sixteenth century means during the years from 1501 to 1600.","zh":"in the sixteenth century 指1501年至1600年間。"},{"en":"In the sixteenth century, maps often mixed discovery, guesswork, and imagination.","zh":"在16世紀，地圖常混合發現、推測和想像。"},{"en":"Historical dates help readers place events in the correct period.","zh":"歷史日期幫助讀者把事件放在正確時期。"},{"en":"The phrase identifies a time in early modern history.","zh":"這個短語指出近代早期的一段時間。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":2},{"front":"cartographer","meaning":"地圖製作家","examples":[{"en":"The German cartographer Mercator made a famous world map.","zh":"德國地圖製作家 Mercator 製作了一幅著名世界地圖。"},{"en":"A cartographer is a person who makes maps.","zh":"cartographer 是製作地圖的人。"},{"en":"A modern cartographer may use satellite images to draw accurate city maps.","zh":"現代地圖製作家可能使用衛星影像繪製準確城市地圖。"},{"en":"Cartographers are important because people rely on maps for travel, trade, and research.","zh":"地圖製作家很重要，因為人們依靠地圖旅行、貿易和研究。"},{"en":"The word describes someone whose work is map-making.","zh":"這個詞描述以製作地圖為工作的人。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":2},{"front":"make a world map","meaning":"製作世界地圖","examples":[{"en":"Mercator made a world map that referred to the Land of Parrots.","zh":"Mercator 製作了一幅提及「鸚鵡之地」的世界地圖。"},{"en":"To make a world map means to draw or produce a map showing the whole world.","zh":"make a world map 指繪畫或製作顯示整個世界的地圖。"},{"en":"Students may make a world map to show where different languages are spoken.","zh":"學生可能製作世界地圖，以顯示不同語言在哪些地方使用。"},{"en":"Making a world map requires choices about scale, shape, names, and missing information.","zh":"製作世界地圖需要就比例、形狀、名稱和缺失資料作選擇。"},{"en":"The phrase describes creating a map of global geography.","zh":"這個短語描述創造全球地理地圖。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":2},{"front":"present-day Australia","meaning":"現今澳洲","examples":[{"en":"Mercator named a place near present-day Australia Terra Psittacorum.","zh":"Mercator 將現今澳洲附近一個地方命名為 Terra Psittacorum。"},{"en":"Present-day Australia means Australia as it exists or is known today.","zh":"present-day Australia 指今天存在或為人所知的澳洲。"},{"en":"Present-day Hong Kong is very different from the fishing villages of the past.","zh":"現今香港與過去的漁村非常不同。"},{"en":"Writers use present-day to compare modern geography with older names or maps.","zh":"作者使用 present-day 來把現代地理與舊名稱或舊地圖比較。"},{"en":"The phrase connects a historical reference with a modern place.","zh":"這個短語把歷史稱呼與現代地方連接起來。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":2},{"front":"name something Terra Psittacorum","meaning":"將某地命名為 Terra Psittacorum","examples":[{"en":"Mercator named the area Terra Psittacorum, meaning the Land of Parrots.","zh":"Mercator 將該地命名為 Terra Psittacorum，意思是「鸚鵡之地」。"},{"en":"To name something Terra Psittacorum means to give it the Latin name meaning the Land of Parrots.","zh":"name something Terra Psittacorum 指把某地命名為這個拉丁名稱，意思是「鸚鵡之地」。"},{"en":"A mapmaker may name a place after an animal if that animal is strongly associated with the region.","zh":"如果某動物與某地區有強烈聯繫，地圖製作家可能用該動物命名地方。"},{"en":"Naming a place can show what early travellers or mapmakers thought was important about it.","zh":"命名地方可以顯示早期旅人或地圖製作家認為它有何重要特色。"},{"en":"The phrase describes a historical act of naming on a map.","zh":"這個短語描述在地圖上的一個歷史命名行動。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":2},{"front":"the Land of Parrots","meaning":"鸚鵡之地","examples":[{"en":"Terra Psittacorum means the Land of Parrots.","zh":"Terra Psittacorum 意思是「鸚鵡之地」。"},{"en":"The Land of Parrots is a descriptive name suggesting a place strongly associated with parrots.","zh":"the Land of Parrots 是一個描述性名稱，暗示某地方與鸚鵡有強烈聯繫。"},{"en":"A tourist brochure might call a wetland the Land of Birds if many species live there.","zh":"如果濕地有許多鳥類物種，旅遊小冊子可能稱它為「鳥類之地」。"},{"en":"Such names create an image of a place through its most noticeable wildlife.","zh":"這類名稱透過最顯眼的野生動物來塑造地方形象。"},{"en":"The phrase presents Australia as a place famous for parrots.","zh":"這個短語把澳洲呈現為以鸚鵡聞名的地方。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":2},{"front":"European settlers","meaning":"歐洲移民","examples":[{"en":"The first European settlers often referred to Australia as Parrot Land.","zh":"最早的歐洲移民常把澳洲稱為「鸚鵡之地」。"},{"en":"European settlers were people from Europe who moved to live permanently in a new land.","zh":"European settlers 是從歐洲遷往新土地並永久居住的人。"},{"en":"European settlers changed many landscapes by building farms, towns, and roads.","zh":"歐洲移民透過建立農場、城鎮和道路改變了許多地貌。"},{"en":"Settlement can affect native animals when forests are cleared or wetlands are drained.","zh":"當森林被清除或濕地被排乾，定居會影響本土動物。"},{"en":"The phrase refers to Europeans who established homes in another region.","zh":"這個短語指在另一地區建立家園的歐洲人。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":2},{"front":"refer to A as B","meaning":"將A稱為B","examples":[{"en":"Early European settlers referred to Australia as Parrot Land.","zh":"早期歐洲移民將澳洲稱為「鸚鵡之地」。"},{"en":"To refer to A as B means to call A by the name or description B.","zh":"refer to A as B 指把A稱作B這個名稱或描述。"},{"en":"Students often refer to their class teacher as Miss Chan.","zh":"學生常將班主任稱為 Chan 老師。"},{"en":"The phrase is useful when explaining names, labels, or descriptions.","zh":"這個短語在解釋名稱、標籤或描述時很有用。"},{"en":"It shows how people choose to identify or describe something.","zh":"它顯示人們如何識別或描述某事物。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":2},{"front":"celebrated British naturalist","meaning":"著名英國博物學家","examples":[{"en":"John Gould was a celebrated British naturalist and wildlife artist.","zh":"John Gould 是一位著名英國博物學家和野生動物畫家。"},{"en":"A celebrated British naturalist is a well-known British scientist who studies plants, animals, or nature.","zh":"celebrated British naturalist 指研究植物、動物或自然的著名英國科學家。"},{"en":"A celebrated naturalist may write books, collect specimens, and describe species.","zh":"著名博物學家可能寫書、收集標本並描述物種。"},{"en":"Such people become celebrated when their work changes public understanding of nature.","zh":"當他們的工作改變公眾對自然的理解，他們就會成名。"},{"en":"The phrase describes a famous expert in natural history.","zh":"這個短語描述自然史方面的著名專家。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":2},{"front":"wildlife artist","meaning":"野生動物畫家","examples":[{"en":"John Gould was both a naturalist and a wildlife artist.","zh":"John Gould 既是博物學家，也是野生動物畫家。"},{"en":"A wildlife artist is someone who creates pictures of animals, birds, plants, or natural scenes.","zh":"wildlife artist 是創作動物、鳥類、植物或自然景象圖畫的人。"},{"en":"A wildlife artist may visit forests to draw birds accurately from observation.","zh":"野生動物畫家可能到森林觀察並準確繪畫鳥類。"},{"en":"Wildlife art can help people recognise species before photography is available.","zh":"在攝影尚未普及前，野生動物藝術可以幫助人辨認物種。"},{"en":"The phrase describes an artist who focuses on nature and animals.","zh":"這個短語描述專注於自然和動物的藝術家。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":3},{"front":"give somewhere an air of","meaning":"令某地帶有……氣息","examples":[{"en":"Parrots gave Australia a tropical and benign air.","zh":"鸚鵡令澳洲帶有熱帶而宜人的氣息。"},{"en":"To give somewhere an air of something means to make a place seem to have a particular feeling or character.","zh":"give somewhere an air of 某物，指令某地方看似具有某種感覺或特色。"},{"en":"Flowers and music can give a school hall an air of celebration.","zh":"鮮花和音樂可以令學校禮堂帶有慶祝氣氛。"},{"en":"Bright birds can give a landscape an air of warmth and life.","zh":"鮮艷鳥類可以令景觀帶有溫暖和生命力的氣息。"},{"en":"The phrase describes the mood or impression created by something in a place.","zh":"這個短語描述某物在某地創造出的氣氛或印象。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":3},{"front":"tropical and benign","meaning":"熱帶而宜人的","examples":[{"en":"Gould thought parrots gave Australia a tropical and benign air.","zh":"Gould 認為鸚鵡令澳洲帶有熱帶而宜人的氣息。"},{"en":"Tropical and benign means warm, lush, gentle, and pleasant rather than harsh or threatening.","zh":"tropical and benign 指溫暖、繁茂、柔和而令人愉快，而不是惡劣或有威脅。"},{"en":"A garden with palm trees and bright birds may feel tropical and benign.","zh":"有棕櫚樹和鮮艷鳥類的花園可能感覺熱帶而宜人。"},{"en":"This description can soften a landscape by making it seem welcoming.","zh":"這種描述可以令景觀顯得更柔和、更友善。"},{"en":"The phrase combines climate, beauty, and a sense of safety.","zh":"這個短語結合氣候、美感和安全感。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":3},{"front":"numerous species","meaning":"眾多物種","examples":[{"en":"Australia is tenanted by numerous species of parrots.","zh":"澳洲有眾多鸚鵡物種棲息。"},{"en":"Numerous species means many different kinds of living things.","zh":"numerous species 指許多不同種類的生物。"},{"en":"A coral reef may contain numerous species of fish, shellfish, and plants.","zh":"珊瑚礁可能有眾多魚類、貝類和植物物種。"},{"en":"Numerous species make an ecosystem richer but also harder to protect fully.","zh":"眾多物種令生態系統更豐富，但也更難全面保護。"},{"en":"The phrase emphasises both quantity and biological variety.","zh":"這個短語強調數量和生物多樣性。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":3},{"front":"be tenanted by","meaning":"由……棲息","examples":[{"en":"Australia is tenanted by many species of parrots.","zh":"澳洲由許多鸚鵡物種棲息。"},{"en":"To be tenanted by animals means to be inhabited or occupied by them.","zh":"be tenanted by 動物，指由牠們居住或佔據。"},{"en":"An old tree may be tenanted by insects, birds, and small mammals.","zh":"一棵老樹可能由昆蟲、鳥類和小型哺乳動物棲息。"},{"en":"A habitat becomes valuable when it is tenanted by many living creatures.","zh":"當棲息地由許多生物棲息，它就變得有價值。"},{"en":"The phrase gives a literary way to say that a place is lived in.","zh":"這個短語以較文學的方式表示某地方被生物居住。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":3},{"front":"descend from","meaning":"源自；是……的後代","examples":[{"en":"Parrots descend from an ancient line.","zh":"鸚鵡源自一個古老譜系。"},{"en":"To descend from something means to come from it as a later generation or evolutionary result.","zh":"descend from 某物，指作為後代或演化結果源自它。"},{"en":"Modern dogs descend from wolf-like ancestors.","zh":"現代狗源自類似狼的祖先。"},{"en":"Knowing what a species descends from helps scientists understand its history.","zh":"了解一個物種源自甚麼，有助科學家理解其歷史。"},{"en":"The phrase connects present living things with their origins.","zh":"這個短語把現存生物與其起源連接起來。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":3},{"front":"an ancient line","meaning":"古老譜系","examples":[{"en":"Parrots come from an ancient evolutionary line.","zh":"鸚鵡來自一個古老演化譜系。"},{"en":"An ancient line is an old chain of ancestry or evolution stretching far back in time.","zh":"ancient line 是延伸到久遠過去的古老祖先或演化鏈。"},{"en":"Some plants belong to an ancient line that existed before flowering plants became common.","zh":"有些植物屬於一個古老譜系，早於開花植物普遍出現。"},{"en":"Ancient lines interest scientists because they preserve clues about early evolution.","zh":"古老譜系令科學家感興趣，因為它們保存早期演化線索。"},{"en":"The phrase describes a very old biological heritage.","zh":"這個短語描述非常古老的生物傳承。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":3},{"front":"given their great diversity","meaning":"鑑於牠們的巨大多樣性","examples":[{"en":"Given their great diversity, parrots probably have very ancient origins.","zh":"鑑於牠們的巨大多樣性，鸚鵡可能有非常古老的起源。"},{"en":"Given their great diversity means considering how many different forms or kinds they have.","zh":"given their great diversity 指考慮到牠們有多少不同形態或種類。"},{"en":"Given the great diversity of students’ needs, one teaching method cannot help everyone.","zh":"鑑於學生需要的巨大多樣性，一種教學方法不可能幫助所有人。"},{"en":"Diversity can suggest a long history of change and adaptation.","zh":"多樣性可以暗示長久的變化和適應歷史。"},{"en":"The phrase introduces a reason based on variety.","zh":"這個短語引出一個基於多樣性的理由。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":3},{"front":"inhabit","meaning":"棲息於","examples":[{"en":"Most parrot species inhabit Africa, Australia and South America.","zh":"大多數鸚鵡物種棲息於非洲、澳洲和南美洲。"},{"en":"To inhabit a place means to live there naturally or regularly.","zh":"inhabit 某地，指自然或經常地生活在那裏。"},{"en":"Fish inhabit rivers, lakes, oceans, and sometimes small ponds.","zh":"魚類棲息於河流、湖泊、海洋，有時也棲息於小池塘。"},{"en":"Animals can only inhabit places that provide enough food, shelter, and safety.","zh":"動物只能棲息於提供足夠食物、庇護和安全的地方。"},{"en":"The verb describes where living things make their home.","zh":"這個動詞描述生物把哪裏作為家。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":3},{"front":"it seems almost certain that","meaning":"幾乎可以肯定","examples":[{"en":"It seems almost certain that parrots originated on Gondwana.","zh":"幾乎可以肯定鸚鵡起源於岡瓦納古陸。"},{"en":"It seems almost certain that means the evidence strongly suggests something is true.","zh":"it seems almost certain that 指證據強烈顯示某事為真。"},{"en":"If dark clouds cover the sky, it seems almost certain that rain will come soon.","zh":"如果烏雲密布，幾乎可以肯定很快會下雨。"},{"en":"Writers use this phrase when they are highly confident but still cautious.","zh":"作者在非常有信心但仍保持謹慎時使用這個短語。"},{"en":"It expresses strong probability rather than absolute proof.","zh":"它表達高度可能性，而不是絕對證明。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":3},{"front":"originate millions of years ago","meaning":"起源於數百萬年前","examples":[{"en":"Parrots probably originated millions of years ago.","zh":"鸚鵡可能起源於數百萬年前。"},{"en":"To originate millions of years ago means to begin or first appear in the very distant past.","zh":"originate millions of years ago 指在非常遙遠的過去開始或首次出現。"},{"en":"Some mountain ranges originated millions of years ago when land plates collided.","zh":"有些山脈在數百萬年前因地殼板塊碰撞而形成。"},{"en":"Ancient origins help explain why a group has had time to diversify.","zh":"古老起源有助解釋某群體為何有時間分化。"},{"en":"The phrase places beginnings in deep geological or evolutionary time.","zh":"這個短語把起源放在深遠的地質或演化時間中。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":4},{"front":"ancient southern continent","meaning":"古老南方大陸","examples":[{"en":"Gondwana was an ancient southern continent.","zh":"岡瓦納古陸是一個古老南方大陸。"},{"en":"An ancient southern continent is a very old landmass that existed in the southern part of the world.","zh":"ancient southern continent 指曾存在於世界南部的非常古老陸塊。"},{"en":"Scientists study ancient southern continents to understand how plants and animals spread.","zh":"科學家研究古老南方大陸，以理解植物和動物如何擴散。"},{"en":"When such continents split, species could be separated and evolve differently.","zh":"當這些大陸分裂，物種可能被分隔並以不同方式演化。"},{"en":"The phrase refers to a prehistoric landmass in the Southern Hemisphere.","zh":"這個短語指位於南半球的史前陸塊。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":4},{"front":"Gondwana","meaning":"岡瓦納古陸","examples":[{"en":"Parrots may have originated on Gondwana before it broke apart.","zh":"鸚鵡可能在岡瓦納古陸分裂前已起源於那裏。"},{"en":"Gondwana was an ancient supercontinent that included lands now separated in the Southern Hemisphere.","zh":"Gondwana 是一個古老超大陸，包括現在在南半球分開的土地。"},{"en":"Australia, Antarctica, Africa, South America, and India were once connected through Gondwana.","zh":"澳洲、南極洲、非洲、南美洲和印度曾透過岡瓦納古陸連接。"},{"en":"Gondwana helps explain why related species can appear on continents now far apart.","zh":"岡瓦納古陸有助解釋為何相關物種會出現在如今相隔甚遠的大陸。"},{"en":"The word names a major ancient landmass in Earth’s history.","zh":"這個詞命名地球歷史上的一個主要古老陸塊。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":4},{"front":"break up into","meaning":"分裂成","examples":[{"en":"Gondwana broke up into separate Southern Hemisphere continents.","zh":"岡瓦納古陸分裂成各個南半球大陸。"},{"en":"To break up into parts means to split into smaller pieces or groups.","zh":"break up into 多個部分，指分裂成較小部分或群體。"},{"en":"A large class may break up into smaller groups for discussion.","zh":"大班級可能分成較小小組進行討論。"},{"en":"When a landmass breaks up, animals and plants may become isolated.","zh":"當陸塊分裂，動植物可能被隔離。"},{"en":"The phrase describes one whole separating into several parts.","zh":"這個短語描述一個整體分開成幾個部分。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":4},{"front":"separate continents","meaning":"分開的大陸","examples":[{"en":"The ancient landmass broke up into separate continents.","zh":"古老陸塊分裂成分開的大陸。"},{"en":"Separate continents are distinct large landmasses divided by oceans or major geographical barriers.","zh":"separate continents 是由海洋或主要地理屏障分隔的不同大陸。"},{"en":"Australia and South America are separate continents today.","zh":"今天澳洲和南美洲是分開的大陸。"},{"en":"Species on separate continents may evolve differently because they no longer mix.","zh":"分開大陸上的物種可能因不再混合而以不同方式演化。"},{"en":"The phrase stresses physical separation between major land areas.","zh":"這個短語強調主要陸地之間的物理分隔。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":4},{"front":"comprise","meaning":"包括；由……組成","examples":[{"en":"Much of Gondwana comprised vast rainforests.","zh":"岡瓦納古陸很大部分由廣闊雨林組成。"},{"en":"To comprise something means to consist of or be made up of it.","zh":"comprise 某物，指包括或由它組成。"},{"en":"A school timetable may comprise lessons, breaks, assemblies, and activities.","zh":"學校時間表可能包括課堂、小息、集會和活動。"},{"en":"The word helps describe what parts form a whole.","zh":"這個詞幫助描述哪些部分構成整體。"},{"en":"It is often used in formal explanations of structure or composition.","zh":"它常用於正式解釋結構或組成。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":4},{"front":"vast rainforests","meaning":"廣闊雨林","examples":[{"en":"Gondwana once contained vast rainforests.","zh":"岡瓦納古陸曾包含廣闊雨林。"},{"en":"Vast rainforests are extremely large forests in wet, warm areas with many plants and animals.","zh":"vast rainforests 是位於潮濕溫暖地區、擁有大量動植物的極大型森林。"},{"en":"Vast rainforests can support birds, insects, reptiles, mammals, and countless trees.","zh":"廣闊雨林可以支撐鳥類、昆蟲、爬行動物、哺乳動物和無數樹木。"},{"en":"If vast rainforests shrink, many species may lose food and shelter.","zh":"如果廣闊雨林縮小，許多物種可能失去食物和庇護。"},{"en":"The phrase emphasises both great size and rich forest life.","zh":"這個短語同時強調巨大面積和豐富森林生命。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":4},{"front":"be intersected by","meaning":"被……穿過","examples":[{"en":"The rainforests were intersected by huge rivers and lakes.","zh":"這些雨林被巨大的河流和湖泊穿過。"},{"en":"To be intersected by something means to be crossed or divided by it.","zh":"be intersected by 某物，指被它穿越或分隔。"},{"en":"A neighbourhood may be intersected by a busy road.","zh":"一個社區可能被一條繁忙道路穿過。"},{"en":"Rivers that intersect forests can create travel routes and different habitats.","zh":"穿過森林的河流可以形成通道和不同棲息地。"},{"en":"The phrase describes one feature cutting across another area.","zh":"這個短語描述一項地理特徵橫穿另一區域。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":4},{"front":"slow-flowing rivers","meaning":"緩慢流動的河流","examples":[{"en":"Gondwana had huge, slow-flowing rivers.","zh":"岡瓦納古陸有巨大而緩慢流動的河流。"},{"en":"Slow-flowing rivers are rivers whose water moves gently rather than rapidly.","zh":"slow-flowing rivers 是水流溫和而不是急速的河流。"},{"en":"Slow-flowing rivers may allow fish, plants, and birds to live along their banks.","zh":"緩慢流動的河流可能讓魚類、植物和鳥類生活在河岸附近。"},{"en":"Gentle water can create wetlands, lakes, and feeding areas for wildlife.","zh":"平緩水流可以形成濕地、湖泊和野生動物覓食區。"},{"en":"The phrase describes rivers with calm movement.","zh":"這個短語描述水流平靜的河流。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":4},{"front":"expansive lakes","meaning":"廣闊湖泊","examples":[{"en":"The ancient continent contained expansive lakes.","zh":"這個古老大陸包含廣闊湖泊。"},{"en":"Expansive lakes are very large lakes that cover wide areas.","zh":"expansive lakes 是覆蓋廣大範圍的非常大型湖泊。"},{"en":"Expansive lakes can provide water, fish, and resting places for birds.","zh":"廣闊湖泊可以為鳥類提供水、魚和休息地點。"},{"en":"Large lakes can influence local climate and support many habitats.","zh":"大型湖泊可以影響本地氣候並支撐許多棲息地。"},{"en":"The phrase stresses the broad size of lakes.","zh":"這個短語強調湖泊面積廣大。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":4},{"front":"changes were under way","meaning":"變化正在發生","examples":[{"en":"By eight million years ago, great environmental changes were under way.","zh":"到八百萬年前，重大的環境變化正在發生。"},{"en":"If changes are under way, they have already started and are continuing.","zh":"changes are under way 指變化已經開始並正在持續。"},{"en":"In a school renovation, changes are under way when walls are being painted and classrooms moved.","zh":"在學校翻新中，當牆壁正在粉刷、課室正在搬遷，變化就是正在發生。"},{"en":"Once major changes are under way, animals and people may need to adjust quickly.","zh":"一旦重大變化正在發生，動物和人可能需要迅速調整。"},{"en":"The phrase describes an ongoing process of change.","zh":"這個短語描述正在進行中的變化過程。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":5},{"front":"dry out","meaning":"變乾","examples":[{"en":"The centre of Australia began to dry out.","zh":"澳洲中部開始變乾。"},{"en":"To dry out means to lose water or become drier over time.","zh":"dry out 指逐漸失去水分或變得較乾。"},{"en":"Wet clothes dry out faster in the sun than in a dark room.","zh":"濕衣服在陽光下比在暗房中更快變乾。"},{"en":"When land dries out, plants may die and animals may move away.","zh":"當土地變乾，植物可能死亡，動物可能遷走。"},{"en":"The phrase describes a process of becoming less wet.","zh":"這個短語描述變得較不濕潤的過程。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":5},{"front":"gradually contract to","meaning":"逐漸收縮至","examples":[{"en":"Australia’s rainforests gradually contracted to the continental margins.","zh":"澳洲的雨林逐漸收縮至大陸邊緣。"},{"en":"To gradually contract to an area means to slowly shrink until only that area remains.","zh":"gradually contract to 某區域，指慢慢縮小，直到只剩該區域。"},{"en":"A crowd may gradually contract to one corner of a hall after an event ends.","zh":"活動結束後，人群可能逐漸收縮到禮堂一角。"},{"en":"If forests gradually contract, animals depending on them lose space over time.","zh":"如果森林逐漸收縮，依賴森林的動物會隨時間失去空間。"},{"en":"The phrase describes slow reduction in range or size.","zh":"這個短語描述範圍或大小的緩慢減少。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":5},{"front":"continental margins","meaning":"大陸邊緣","examples":[{"en":"Rainforests survived mainly around the continental margins.","zh":"雨林主要在大陸邊緣存活下來。"},{"en":"Continental margins are the outer edges of a continent.","zh":"continental margins 指一個大陸的外圍邊緣。"},{"en":"Many coastal cities are located near continental margins.","zh":"許多沿海城市位於大陸邊緣附近。"},{"en":"If forests remain only at continental margins, central areas may become much drier.","zh":"如果森林只留在大陸邊緣，中部地區可能變得乾燥得多。"},{"en":"The phrase describes the edge zones of a large landmass.","zh":"這個短語描述大型陸塊的邊緣地帶。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":5},{"front":"to a limited extent","meaning":"在有限程度上","examples":[{"en":"Rainforests still exist to a limited extent today.","zh":"雨林今天仍在有限程度上存在。"},{"en":"To a limited extent means only partly or in a small degree.","zh":"to a limited extent 指只是在部分或小程度上。"},{"en":"Online learning can help students to a limited extent, but some still need face-to-face support.","zh":"網上學習可以在有限程度上幫助學生，但有些人仍需要面對面支援。"},{"en":"The phrase prevents overstatement by showing that something is true only partly.","zh":"這個短語透過表示某事只部分為真，避免誇大。"},{"en":"It is useful when a result exists but is not large or complete.","zh":"當某結果存在但不大或不完整時，它很有用。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":5},{"front":"shrinking rainforests","meaning":"不斷縮小的雨林","examples":[{"en":"Some creatures remained in the shrinking rainforests.","zh":"有些生物留在不斷縮小的雨林中。"},{"en":"Shrinking rainforests are rainforests that are becoming smaller in area.","zh":"shrinking rainforests 是面積正在變小的雨林。"},{"en":"Shrinking rainforests may force animals to compete for fewer trees and food sources.","zh":"不斷縮小的雨林可能迫使動物爭奪更少的樹木和食物來源。"},{"en":"Forests can shrink because of climate change, farming, logging, or fire.","zh":"森林可能因氣候變化、農業、伐木或火災而縮小。"},{"en":"The phrase describes rainforest habitats losing size over time.","zh":"這個短語描述雨林棲息地隨時間失去面積。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":5},{"front":"adapt to drier conditions","meaning":"適應較乾旱的環境","examples":[{"en":"Animals had to adapt to drier conditions or face extinction.","zh":"動物必須適應較乾旱的環境，否則面臨滅絕。"},{"en":"To adapt to drier conditions means to change in order to survive where there is less water.","zh":"adapt to drier conditions 指為了在水分較少的地方生存而改變。"},{"en":"Farmers may adapt to drier conditions by growing crops that need less irrigation.","zh":"農民可能透過種植需水較少的作物來適應較乾旱的環境。"},{"en":"Animals that cannot find food or water in dry areas may disappear from them.","zh":"無法在乾旱地區找到食物或水的動物可能從該地消失。"},{"en":"The phrase describes adjustment to a less wet environment.","zh":"這個短語描述對較不潮濕環境的調整。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":5},{"front":"face extinction","meaning":"面臨滅絕","examples":[{"en":"Species that failed to adapt could face extinction.","zh":"未能適應的物種可能面臨滅絕。"},{"en":"To face extinction means to be at risk of disappearing completely as a species.","zh":"face extinction 指作為一個物種有完全消失的風險。"},{"en":"A rare frog may face extinction if its wetland is destroyed.","zh":"如果濕地被破壞，罕見青蛙可能面臨滅絕。"},{"en":"Habitat loss, hunting, disease, and climate change can make species face extinction.","zh":"棲息地流失、狩獵、疾病和氣候變化都可能令物種面臨滅絕。"},{"en":"The phrase describes a serious survival threat.","zh":"這個短語描述嚴重的生存威脅。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":5},{"front":"react to desperate circumstances","meaning":"因應絕境作出反應","examples":[{"en":"Parrots reacted to desperate circumstances by spreading into harsher environments.","zh":"鸚鵡因應絕境作出反應，擴散到更惡劣的環境中。"},{"en":"To react to desperate circumstances means to respond when conditions become extremely difficult.","zh":"react to desperate circumstances 指在情況變得極其困難時作出回應。"},{"en":"A family may react to desperate circumstances by cutting expenses and asking relatives for help.","zh":"家庭可能因應絕境削減開支並向親人求助。"},{"en":"Desperate circumstances often force quick decisions because ordinary options no longer work.","zh":"絕境常迫使人迅速決定，因為普通選項已不再有效。"},{"en":"The phrase describes behaviour under severe pressure.","zh":"這個短語描述在嚴重壓力下的行為。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":5},{"front":"typically found in","meaning":"通常見於","examples":[{"en":"Parrots are typically found in jungles elsewhere in the world.","zh":"在世界其他地方，鸚鵡通常見於叢林。"},{"en":"To be typically found in a place means to usually live or appear there.","zh":"be typically found in 某地，指通常生活或出現在那裏。"},{"en":"Penguins are typically found in cold southern regions rather than tropical forests.","zh":"企鵝通常見於寒冷的南方地區，而不是熱帶森林。"},{"en":"If an animal is found outside its typical habitat, scientists may ask why it moved.","zh":"如果動物出現在其通常棲息地以外，科學家可能會問牠為何移動。"},{"en":"The phrase describes the normal location of something.","zh":"這個短語描述某物的正常所在地。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":5},{"front":"harshest environments","meaning":"最惡劣的環境","examples":[{"en":"Some Australian parrots populated the country’s harshest environments.","zh":"有些澳洲鸚鵡在該國最惡劣的環境中生活繁衍。"},{"en":"The harshest environments are the most difficult places to live in because of heat, cold, dryness, or danger.","zh":"harshest environments 是因炎熱、寒冷、乾旱或危險而最難生存的地方。"},{"en":"Deserts are among the harshest environments because water and shade are scarce.","zh":"沙漠屬於最惡劣的環境之一，因為水和陰影都很稀少。"},{"en":"Animals living in harsh environments need special adaptations to survive.","zh":"生活在惡劣環境中的動物需要特殊適應才能生存。"},{"en":"The phrase describes extremely challenging natural conditions.","zh":"這個短語描述極具挑戰性的自然條件。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":6},{"front":"spread from ancestral forests","meaning":"從祖先森林擴散","examples":[{"en":"Parrots spread from ancestral forests into new habitats.","zh":"鸚鵡從祖先森林擴散到新棲息地。"},{"en":"To spread from ancestral forests means to move out from the original forest habitats of earlier generations.","zh":"spread from ancestral forests 指從早期世代原本棲息的森林向外移動。"},{"en":"A plant species may spread from mountain forests into farms if birds carry its seeds.","zh":"如果鳥類帶走種子，植物物種可能從山林擴散到農田。"},{"en":"Species spread when old habitats shrink or new opportunities appear.","zh":"當舊棲息地縮小或新機會出現，物種就會擴散。"},{"en":"The phrase connects movement with evolutionary origin.","zh":"這個短語把移動與演化起源連接起來。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":6},{"front":"eucalypt woodlands","meaning":"桉樹林地","examples":[{"en":"Parrots moved through eucalypt woodlands towards the deserts.","zh":"鸚鵡穿過桉樹林地，向沙漠方向移動。"},{"en":"Eucalypt woodlands are open areas with many eucalyptus trees.","zh":"eucalypt woodlands 是有許多桉樹的開闊地區。"},{"en":"Many Australian animals use eucalypt woodlands for food, shelter, and nesting sites.","zh":"許多澳洲動物利用桉樹林地覓食、藏身和築巢。"},{"en":"These woodlands can act as a transition between wetter forests and drier inland areas.","zh":"這些林地可以作為較濕森林與較乾內陸地區之間的過渡。"},{"en":"The phrase describes a common Australian tree habitat.","zh":"這個短語描述澳洲常見的樹木棲息地。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":6},{"front":"colonise","meaning":"移居並繁衍於","examples":[{"en":"Some parrots colonised the central deserts of Australia.","zh":"有些鸚鵡移居並繁衍於澳洲中部沙漠。"},{"en":"To colonise a habitat means to move into it and establish a living population there.","zh":"colonise 某棲息地，指移入該地並建立能生活的種群。"},{"en":"Weeds may colonise an empty garden if nobody removes them.","zh":"如果沒有人清除，雜草可能在空花園中移居並繁衍。"},{"en":"A species can colonise a new area when food, shelter, and breeding space are available.","zh":"當食物、庇護和繁殖空間可得，物種就能移居並繁衍於新地區。"},{"en":"The word describes settling and reproducing in a new place.","zh":"這個詞描述在新地方定居和繁殖。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":6},{"front":"central deserts","meaning":"中部沙漠","examples":[{"en":"Parrots adapted to life in the central deserts of Australia.","zh":"鸚鵡適應了澳洲中部沙漠的生活。"},{"en":"Central deserts are dry inland desert regions near the middle of a landmass.","zh":"central deserts 指靠近陸地中央的乾旱內陸沙漠地區。"},{"en":"Central deserts often have extreme heat, little rainfall, and scattered vegetation.","zh":"中部沙漠通常有極端高溫、少量降雨和分散植被。"},{"en":"Animals in central deserts must find water and food across large distances.","zh":"中部沙漠中的動物必須在大範圍內尋找水和食物。"},{"en":"The phrase describes dry interior desert areas.","zh":"這個短語描述乾旱的內陸沙漠地帶。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":6},{"front":"diversify into","meaning":"分化成","examples":[{"en":"Parrots diversified into a wide range of species.","zh":"鸚鵡分化成多種物種。"},{"en":"To diversify into different forms means to develop into many different types over time.","zh":"diversify into 不同形式，指隨時間發展成許多不同類型。"},{"en":"A company may diversify into online lessons, books, and exam courses instead of offering only tutoring.","zh":"公司可能分化出網上課程、書籍和考試課程，而不只提供補習。"},{"en":"In nature, diversification can happen when groups adapt to different habitats or foods.","zh":"在自然界，當群體適應不同棲息地或食物時，就可能發生分化。"},{"en":"The phrase describes becoming varied from an original source.","zh":"這個短語描述從原本來源變得多樣。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":6},{"front":"a wide range of species","meaning":"多種物種","examples":[{"en":"Australian parrots developed into a wide range of species.","zh":"澳洲鸚鵡發展成多種物種。"},{"en":"A wide range of species means many different biological types.","zh":"a wide range of species 指許多不同生物類型。"},{"en":"A healthy forest may support a wide range of species, from insects to birds.","zh":"健康森林可以支持多種物種，由昆蟲到鳥類都有。"},{"en":"A wide range of species usually needs varied habitats and food sources.","zh":"多種物種通常需要多樣棲息地和食物來源。"},{"en":"The phrase highlights broad biological variety.","zh":"這個短語強調廣泛生物多樣性。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":6},{"front":"adaptations reflect","meaning":"適應特徵反映","examples":[{"en":"Their adaptations reflect the changes needed for survival.","zh":"牠們的適應特徵反映生存所需的變化。"},{"en":"Adaptations reflect something means physical or behavioural features show the pressures that shaped them.","zh":"adaptations reflect 某事，指身體或行為特徵顯示塑造它們的壓力。"},{"en":"A cactus’s thick stem reflects its need to store water in dry places.","zh":"仙人掌粗厚的莖反映它在乾旱地方儲水的需要。"},{"en":"Animal features often reflect the food, weather, and dangers around them.","zh":"動物特徵常反映牠們周圍的食物、天氣和危險。"},{"en":"The phrase links a feature with the reason behind it.","zh":"這個短語把特徵與其背後原因連接起來。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":6},{"front":"survive in these areas","meaning":"在這些地區生存","examples":[{"en":"Animals and plants had to change to survive in these areas.","zh":"動物和植物必須改變，才能在這些地區生存。"},{"en":"To survive in these areas means to stay alive in particular places with specific conditions.","zh":"survive in these areas 指在具有特定條件的地方存活。"},{"en":"Plants in windy coastal areas must survive in salty air and poor soil.","zh":"多風沿海地區的植物必須在鹹空氣和貧瘠土壤中生存。"},{"en":"Survival in difficult areas often depends on special habits or body structures.","zh":"在困難地區生存常取決於特殊習性或身體結構。"},{"en":"The phrase focuses on living successfully in a certain environment.","zh":"這個短語聚焦於在某環境中成功存活。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":6},{"front":"evolutionary pressures","meaning":"進化壓力","examples":[{"en":"Evolutionary pressures helped shape parrots’ beaks.","zh":"進化壓力幫助塑造鸚鵡的鳥喙。"},{"en":"Evolutionary pressures are environmental challenges that influence which living things survive and reproduce.","zh":"evolutionary pressures 是影響哪些生物能生存和繁殖的環境挑戰。"},{"en":"Cold weather can be an evolutionary pressure that favours animals with thick fur.","zh":"寒冷天氣可以是一種進化壓力，有利於有厚毛的動物。"},{"en":"Over many generations, evolutionary pressures can change body shape, behaviour, and diet.","zh":"經過許多世代，進化壓力可以改變身體形狀、行為和飲食。"},{"en":"The phrase explains why species develop certain traits.","zh":"這個短語解釋物種為何發展出某些特徵。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":6},{"front":"help mould","meaning":"幫助塑造","examples":[{"en":"Evolutionary pressures helped mould keratin into useful tools.","zh":"進化壓力幫助把角蛋白塑造成有用工具。"},{"en":"To help mould something means to help shape or form it over time.","zh":"help mould 某物，指隨時間幫助塑造或形成它。"},{"en":"Good teachers help mould students’ confidence through feedback and practice.","zh":"好老師透過回饋和練習幫助塑造學生信心。"},{"en":"Environment can help mould behaviour by rewarding some habits and punishing others.","zh":"環境可以透過獎勵某些習慣、懲罰其他習慣來幫助塑造行為。"},{"en":"The phrase describes a shaping influence.","zh":"這個短語描述塑造性的影響。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":7},{"front":"keratin","meaning":"角蛋白","examples":[{"en":"Keratin is the substance from which beaks are made.","zh":"角蛋白是鳥喙由其製成的物質。"},{"en":"Keratin is a tough protein found in hair, nails, claws, feathers, and beaks.","zh":"keratin 是存在於毛髮、指甲、爪、羽毛和鳥喙中的堅韌蛋白質。"},{"en":"Human fingernails are made mainly of keratin.","zh":"人類手指甲主要由角蛋白構成。"},{"en":"Because keratin is hard and flexible, it can form protective body parts.","zh":"因為角蛋白堅硬而有彈性，它可以形成保護性身體部位。"},{"en":"The word names a natural material used in many animal structures.","zh":"這個詞命名許多動物結構所使用的天然材料。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":7},{"front":"the substance from which","meaning":"……由其製成的物質","examples":[{"en":"Keratin is the substance from which birds’ beaks are made.","zh":"角蛋白是鳥類鳥喙由其製成的物質。"},{"en":"The substance from which something is made is the material used to form it.","zh":"the substance from which 某物 is made 指形成某物所用的材料。"},{"en":"Cotton is the substance from which many T-shirts are made.","zh":"棉花是許多T恤由其製成的物質。"},{"en":"Knowing the substance from which an object is made helps explain its strength and use.","zh":"知道一件物件由甚麼物質製成，有助解釋其強度和用途。"},{"en":"The phrase identifies the material behind a thing.","zh":"這個短語指出事物背後的材料。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":7},{"front":"beaks are made","meaning":"鳥喙由……製成","examples":[{"en":"Parrots’ beaks are made from keratin.","zh":"鸚鵡的鳥喙由角蛋白製成。"},{"en":"Beaks are made from a tough material that allows birds to eat, cut, crack, or hold food.","zh":"鳥喙由堅韌材料製成，使鳥類能進食、切開、咬裂或抓住食物。"},{"en":"A bird’s beak is made in a shape that often matches its diet.","zh":"鳥喙的形狀常配合其飲食。"},{"en":"If beaks are strong, birds can open hard seeds or fruit.","zh":"如果鳥喙強壯，鳥類就能打開堅硬種子或果實。"},{"en":"The phrase describes what material forms a bird’s beak.","zh":"這個短語描述鳥喙由甚麼材料形成。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":7},{"front":"a range of tools","meaning":"一系列工具","examples":[{"en":"Different beaks became a range of tools for gathering food.","zh":"不同鳥喙成為採集食物的一系列工具。"},{"en":"A range of tools means several useful forms or instruments for different tasks.","zh":"a range of tools 指用於不同任務的幾種有用形式或工具。"},{"en":"A kitchen has a range of tools, including knives, pans, spoons, and bowls.","zh":"廚房有一系列工具，包括刀、鑊、匙羹和碗。"},{"en":"When animals have different natural tools, they can use different food sources.","zh":"當動物有不同天然工具，就能利用不同食物來源。"},{"en":"The phrase describes variety in useful functions.","zh":"這個短語描述有用功能上的多樣。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":7},{"front":"capable of","meaning":"能夠","examples":[{"en":"The beaks became tools capable of gathering different foods.","zh":"這些鳥喙成為能夠採集不同食物的工具。"},{"en":"Capable of doing something means able to do it.","zh":"capable of doing something 指有能力做某事。"},{"en":"A well-designed phone is capable of taking clear photos at night.","zh":"設計良好的手機能夠在夜間拍攝清晰照片。"},{"en":"If a bird’s beak is capable of cracking seeds, it can use a food source others cannot.","zh":"如果鳥喙能夠咬開種子，牠就可以利用其他動物不能利用的食物來源。"},{"en":"The phrase describes ability or practical power.","zh":"這個短語描述能力或實際功能。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":7},{"front":"gather new food types","meaning":"採集新食物種類","examples":[{"en":"Parrot beaks adapted to gather new food types.","zh":"鸚鵡鳥喙適應了採集新食物種類。"},{"en":"To gather new food types means to collect or obtain foods that were not previously used.","zh":"gather new food types 指收集或取得以前未使用的食物。"},{"en":"A bird may gather new food types from farms when natural fruits become scarce.","zh":"當天然果實變少，鳥類可能從農田採集新食物種類。"},{"en":"Finding new food types can help animals survive after habitats change.","zh":"找到新食物種類可以幫助動物在棲息地改變後生存。"},{"en":"The phrase describes expanding what an animal can eat.","zh":"這個短語描述動物擴大可食食物範圍。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":7},{"front":"be favoured by","meaning":"受……偏愛","examples":[{"en":"Different food types are favoured by different parrot species.","zh":"不同食物種類受不同鸚鵡物種偏愛。"},{"en":"To be favoured by a group means to be preferred or chosen by that group.","zh":"be favoured by 某群體，指受該群體喜歡或選擇。"},{"en":"Quiet study rooms are favoured by students preparing for exams.","zh":"安靜自修室受準備考試的學生偏愛。"},{"en":"Foods favoured by animals often shape the body parts they use to eat.","zh":"受動物偏愛的食物常塑造牠們用來進食的身體部位。"},{"en":"The phrase describes preference or advantage.","zh":"這個短語描述偏好或優勢。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":7},{"front":"short, blunt beak","meaning":"短而鈍的鳥喙","examples":[{"en":"A parrot’s short, blunt beak is related to its diet.","zh":"鸚鵡短而鈍的鳥喙與其飲食有關。"},{"en":"A short, blunt beak is a beak that is not long and has a rounded, strong end.","zh":"short, blunt beak 是不長且末端圓鈍、有力的鳥喙。"},{"en":"A bird with a short, blunt beak may be better at crushing food than reaching deep into flowers.","zh":"有短而鈍鳥喙的鳥可能較擅長壓碎食物，而不是深入花朵取食。"},{"en":"Beak shape matters because different foods require different feeding tools.","zh":"鳥喙形狀很重要，因為不同食物需要不同進食工具。"},{"en":"The phrase describes a compact beak suited to certain tasks.","zh":"這個短語描述適合某些任務的短而結實鳥喙。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":7},{"front":"curved upper section","meaning":"彎曲的上部","examples":[{"en":"The length of the curved upper section is related to the food eaten.","zh":"彎曲上部的長度與所吃食物有關。"},{"en":"The curved upper section is the bent top part of a bird’s beak.","zh":"curved upper section 指鳥喙彎曲的上方部分。"},{"en":"A longer curved upper section may help a bird pull seeds from fruit.","zh":"較長的彎曲上部可能幫助鳥類從果實中取出種子。"},{"en":"The shape of this section affects how the bird grips, cuts, or opens food.","zh":"這部分的形狀影響鳥類如何抓住、切開或打開食物。"},{"en":"The phrase describes a specific part of a beak.","zh":"這個短語描述鳥喙的一個特定部分。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":7},{"front":"be related to","meaning":"與……有關","examples":[{"en":"The size of the beak is related to the food the species eats.","zh":"鳥喙大小與該物種所吃食物有關。"},{"en":"To be related to something means to have a connection with it.","zh":"be related to 某事，指與它有連繫。"},{"en":"A student’s tiredness may be related to lack of sleep.","zh":"學生疲倦可能與睡眠不足有關。"},{"en":"In biology, body features are often related to diet, movement, or habitat.","zh":"在生物學中，身體特徵常與飲食、移動或棲息地有關。"},{"en":"The phrase describes a link between two things.","zh":"這個短語描述兩件事之間的關聯。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":8},{"front":"comparatively long beaks","meaning":"相對較長的鳥喙","examples":[{"en":"Some parrots have comparatively long beaks for extracting seeds.","zh":"有些鸚鵡有相對較長的鳥喙，用來取出種子。"},{"en":"Comparatively long beaks are beaks that are longer when compared with those of similar birds.","zh":"comparatively long beaks 指與相似鳥類相比較長的鳥喙。"},{"en":"A bird with a comparatively long beak may reach food hidden inside fruit or flowers.","zh":"有相對較長鳥喙的鳥可能夠到藏在果實或花中的食物。"},{"en":"Comparatively long beaks can give birds access to food that short-beaked birds cannot use.","zh":"相對較長的鳥喙可讓鳥類取得短喙鳥無法利用的食物。"},{"en":"The phrase describes relative length, not necessarily extreme length.","zh":"這個短語描述相對長度，而不一定是極端長度。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":8},{"front":"be perfect for","meaning":"非常適合","examples":[{"en":"Some beaks are perfect for extracting seeds from fruit.","zh":"有些鳥喙非常適合從果實中取出種子。"},{"en":"To be perfect for something means to be very suitable for that purpose.","zh":"be perfect for 某事，指非常適合該用途。"},{"en":"A quiet library is perfect for students who need to revise seriously.","zh":"安靜圖書館非常適合需要認真溫習的學生。"},{"en":"A tool is perfect for a task when its shape or function matches the job well.","zh":"當工具的形狀或功能與任務十分配合，它就非常適合該任務。"},{"en":"The phrase describes strong suitability.","zh":"這個短語描述高度適合。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":8},{"front":"extract seeds from fruit","meaning":"從果實中取出種子","examples":[{"en":"Longer beaks help parrots extract seeds from fruit.","zh":"較長鳥喙幫助鸚鵡從果實中取出種子。"},{"en":"To extract seeds from fruit means to remove seeds from inside fruit.","zh":"extract seeds from fruit 指把種子從果實內部取出。"},{"en":"A cook may extract seeds from fruit before making jam.","zh":"廚師製作果醬前可能從果實中取出種子。"},{"en":"Birds that can extract seeds from fruit can use a food source hidden from other animals.","zh":"能從果實中取出種子的鳥類，可以利用對其他動物隱藏的食物來源。"},{"en":"The phrase describes taking something out from within fruit.","zh":"這個短語描述從果實內部取出某物。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":8},{"front":"broader, stronger beaks","meaning":"更闊更強壯的鳥喙","examples":[{"en":"Some species have broader, stronger beaks.","zh":"有些物種有更闊更強壯的鳥喙。"},{"en":"Broader, stronger beaks are wider and more powerful beaks.","zh":"broader, stronger beaks 是較寬且較有力的鳥喙。"},{"en":"A bird with broader, stronger beaks may open nuts or hard seeds.","zh":"有更闊更強壯鳥喙的鳥可能打開堅果或硬種子。"},{"en":"Strong beaks help birds feed where softer-beaked species cannot.","zh":"強壯鳥喙幫助鳥類在軟喙物種不能取食的地方覓食。"},{"en":"The phrase describes beaks built for force rather than reach.","zh":"這個短語描述為力量而非伸展距離而形成的鳥喙。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":8},{"front":"be designed to","meaning":"被設計用來","examples":[{"en":"Some beaks are designed to crack hard seeds.","zh":"有些鳥喙被設計用來咬開堅硬種子。"},{"en":"To be designed to do something means to be made or shaped for that purpose.","zh":"be designed to do something 指被製造或塑造成適合該用途。"},{"en":"A raincoat is designed to keep people dry.","zh":"雨衣被設計用來保持人們乾爽。"},{"en":"In nature, a body part may seem designed for a task because evolution shaped it that way.","zh":"在自然界，身體部位可能看似為某任務而設計，因為演化把它塑造成那樣。"},{"en":"The phrase explains purpose or function.","zh":"這個短語解釋目的或功能。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":8},{"front":"crack hard seeds","meaning":"咬開堅硬種子","examples":[{"en":"Strong beaks allow parrots to crack hard seeds.","zh":"強壯鳥喙讓鸚鵡能咬開堅硬種子。"},{"en":"To crack hard seeds means to break open tough seed shells.","zh":"crack hard seeds 指打開堅韌的種子外殼。"},{"en":"People use nutcrackers to crack hard nuts in the same basic way.","zh":"人們用堅果鉗打開硬堅果，基本原理相似。"},{"en":"Birds that crack hard seeds can feed even when soft fruit is unavailable.","zh":"能咬開堅硬種子的鳥，即使沒有軟水果也能覓食。"},{"en":"The phrase describes breaking a hard outer covering to reach food inside.","zh":"這個短語描述打破堅硬外層以取得內裏食物。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":8},{"front":"differently shaped beaks","meaning":"不同形狀的鳥喙","examples":[{"en":"Differently shaped beaks are one adaptation to food sources.","zh":"不同形狀的鳥喙是對食物來源的一種適應。"},{"en":"Differently shaped beaks are beaks with different lengths, curves, widths, or strengths.","zh":"differently shaped beaks 是長度、彎度、寬度或力量不同的鳥喙。"},{"en":"Birds in one forest may have differently shaped beaks because they eat different foods.","zh":"同一森林中的鳥可能有不同形狀的鳥喙，因為牠們吃不同食物。"},{"en":"Beak differences reduce competition when species feed on separate food sources.","zh":"當物種取食不同食物來源，鳥喙差異可以減少競爭。"},{"en":"The phrase describes physical variety linked to feeding.","zh":"這個短語描述與覓食有關的身體多樣性。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":8},{"front":"the only adaptations","meaning":"唯一的適應特徵","examples":[{"en":"Beak shape is not the only adaptation produced by diet.","zh":"鳥喙形狀並不是由飲食造成的唯一適應特徵。"},{"en":"The only adaptations means the sole changes that help survival, with no others included.","zh":"the only adaptations 指唯一有助生存的變化，不包括其他變化。"},{"en":"Warm clothing is not the only adaptation people make in winter; they also change travel habits.","zh":"保暖衣物不是人們在冬天作出的唯一適應；他們也會改變出行習慣。"},{"en":"Saying something is not the only adaptation suggests there are other important changes too.","zh":"說某事不是唯一適應特徵，暗示還有其他重要變化。"},{"en":"The phrase helps widen the discussion beyond one example.","zh":"這個短語幫助把討論擴展到單一例子之外。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":8},{"front":"developing relationship between","meaning":"……之間逐漸形成的關係","examples":[{"en":"The passage describes the developing relationship between parrots and plants.","zh":"文章描述鸚鵡與植物之間逐漸形成的關係。"},{"en":"A developing relationship between two things is a connection that grows and changes over time.","zh":"developing relationship between 兩者，指隨時間增長和改變的連繫。"},{"en":"A developing relationship between a teacher and a class can improve learning.","zh":"老師與班級之間逐漸形成的關係可以改善學習。"},{"en":"In nature, long-term relationships may shape both animals and plants.","zh":"在自然界，長期關係可能同時塑造動物和植物。"},{"en":"The phrase describes a connection that is still forming or evolving.","zh":"這個短語描述仍在形成或演化中的關係。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":8},{"front":"food plants","meaning":"食用植物","examples":[{"en":"Parrots have evolved with their food plants.","zh":"鸚鵡與其食用植物共同演化。"},{"en":"Food plants are plants that animals use as a source of food.","zh":"food plants 是動物用作食物來源的植物。"},{"en":"Bees, birds, and insects may depend on different food plants in the same garden.","zh":"蜜蜂、鳥類和昆蟲可能依賴同一花園中的不同食用植物。"},{"en":"If food plants disappear, animals that rely on them may decline.","zh":"如果食用植物消失，依賴它們的動物可能減少。"},{"en":"The phrase identifies plants as part of an animal’s diet.","zh":"這個短語把植物識別為動物飲食的一部分。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":9},{"front":"honey-eating birds","meaning":"吸蜜鳥類","examples":[{"en":"Lorikeets are among Australia’s honey-eating birds.","zh":"吸蜜鸚鵡屬於澳洲的吸蜜鳥類。"},{"en":"Honey-eating birds are birds that feed on nectar from flowers.","zh":"honey-eating birds 是以花朵花蜜為食的鳥類。"},{"en":"A honey-eating bird may visit bright flowers every morning for food.","zh":"吸蜜鳥類可能每天早上到鮮艷花朵中覓食。"},{"en":"These birds can also help flowers reproduce by carrying pollen.","zh":"這些鳥也可以透過攜帶花粉幫助花朵繁殖。"},{"en":"The phrase describes birds whose diet is linked to nectar.","zh":"這個短語描述飲食與花蜜有關的鳥類。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":9},{"front":"rainbow-coloured lorikeets","meaning":"彩虹色吸蜜鸚鵡","examples":[{"en":"Rainbow-coloured lorikeets feed on flowers.","zh":"彩虹色吸蜜鸚鵡以花朵為食。"},{"en":"Rainbow-coloured lorikeets are brightly coloured parrots with many vivid colours.","zh":"rainbow-coloured lorikeets 是有多種鮮艷顏色的明亮鸚鵡。"},{"en":"Children may notice rainbow-coloured lorikeets because their feathers look like a living painting.","zh":"孩子可能注意到彩虹色吸蜜鸚鵡，因為牠們的羽毛像活的畫作。"},{"en":"Bright colours can make a bird easy to recognise in the wild.","zh":"鮮艷顏色可以令鳥類在野外容易辨認。"},{"en":"The phrase describes lorikeets with striking, multicoloured feathers.","zh":"這個短語描述有醒目多色羽毛的吸蜜鸚鵡。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":9},{"front":"feed on","meaning":"以……為食","examples":[{"en":"Lorikeets feed on nectar and pollen from flowers.","zh":"吸蜜鸚鵡以花朵中的花蜜和花粉為食。"},{"en":"To feed on something means to eat it as a regular food source.","zh":"feed on 某物，指把它作為常規食物來源來吃。"},{"en":"Cows feed on grass in open fields.","zh":"牛在開闊田野中以草為食。"},{"en":"Animals often develop body features that help them feed on their usual food.","zh":"動物常發展出幫助牠們取食常見食物的身體特徵。"},{"en":"The phrase describes what a living thing eats.","zh":"這個短語描述生物吃甚麼。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":9},{"front":"co-evolve","meaning":"共同進化","examples":[{"en":"Lorikeets and flowers have long co-evolved.","zh":"吸蜜鸚鵡和花朵長期共同進化。"},{"en":"To co-evolve means for two species to change over time in response to each other.","zh":"co-evolve 指兩個物種因彼此影響而隨時間改變。"},{"en":"Bees and flowers may co-evolve when flower shape and bee behaviour influence each other.","zh":"當花形和蜜蜂行為互相影響，蜜蜂和花朵可能共同進化。"},{"en":"Co-evolution can create close relationships between food sources and feeders.","zh":"共同進化可以在食物來源和取食者之間創造緊密關係。"},{"en":"The word describes mutual evolutionary influence.","zh":"這個詞描述相互的演化影響。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":9},{"front":"features such as","meaning":"例如……的特徵","examples":[{"en":"Features such as shape and colour have adapted to birds’ needs.","zh":"例如形狀和顏色的特徵已適應鳥類需要。"},{"en":"Features such as A and B means examples of characteristics include A and B.","zh":"features such as A and B 指特徵例子包括A和B。"},{"en":"A phone’s features such as battery life and camera quality affect whether people buy it.","zh":"手機例如電池壽命和相機質素等特徵會影響人們是否購買。"},{"en":"This phrase introduces examples without listing every possible feature.","zh":"這個短語引出例子，而不列出所有可能特徵。"},{"en":"It helps explain a general idea with specific details.","zh":"它幫助用具體細節解釋一般想法。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":9},{"front":"adapt to the birds’ needs","meaning":"適應鳥類的需要","examples":[{"en":"Flowers have adapted to the birds’ needs.","zh":"花朵已適應鳥類的需要。"},{"en":"To adapt to the birds’ needs means to develop features that suit what birds require for feeding or pollination.","zh":"adapt to the birds’ needs 指發展出配合鳥類覓食或授粉需要的特徵。"},{"en":"A flower may adapt to birds’ needs by producing nectar where a bird’s beak can reach it.","zh":"花朵可能透過在鳥喙能到達的位置產生花蜜來適應鳥類需要。"},{"en":"Such adaptation benefits the flower if birds carry pollen to other flowers.","zh":"如果鳥類把花粉帶到其他花朵，這種適應對花朵有利。"},{"en":"The phrase describes plants changing in ways useful to birds.","zh":"這個短語描述植物以有利於鳥類的方式改變。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":9},{"front":"be particularly attractive to","meaning":"對……特別有吸引力","examples":[{"en":"Red is particularly attractive to birds.","zh":"紅色對鳥類特別有吸引力。"},{"en":"To be particularly attractive to someone or something means to appeal strongly to them.","zh":"be particularly attractive to 某人或某物，指對其有強烈吸引力。"},{"en":"Bright packaging may be particularly attractive to young children.","zh":"鮮艷包裝可能對幼兒特別有吸引力。"},{"en":"If a colour is attractive to pollinators, it may help a plant reproduce.","zh":"如果顏色對授粉者有吸引力，它可能幫助植物繁殖。"},{"en":"The phrase describes strong appeal to a specific group.","zh":"這個短語描述對特定群體的強烈吸引。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":9},{"front":"depend on birds for pollination","meaning":"依靠鳥類授粉","examples":[{"en":"Some flowers depend on birds for pollination.","zh":"有些花朵依靠鳥類授粉。"},{"en":"To depend on birds for pollination means to rely on birds to move pollen between flowers.","zh":"depend on birds for pollination 指依靠鳥類在花朵之間傳送花粉。"},{"en":"A flower may depend on birds for pollination if insects cannot reach its nectar.","zh":"如果昆蟲不能到達花蜜，一種花可能依靠鳥類授粉。"},{"en":"If the birds disappear, the flowers that rely on them may produce fewer seeds.","zh":"如果鳥類消失，依賴牠們的花朵可能產生較少種子。"},{"en":"The phrase describes a plant’s reliance on birds for reproduction.","zh":"這個短語描述植物依靠鳥類繁殖。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":9},{"front":"pollination","meaning":"授粉","examples":[{"en":"Birds help some flowers with pollination.","zh":"鳥類幫助一些花朵授粉。"},{"en":"Pollination is the transfer of pollen that allows many plants to produce seeds.","zh":"pollination 是花粉的轉移，使許多植物能產生種子。"},{"en":"Bees, birds, wind, and even bats can help with pollination.","zh":"蜜蜂、鳥類、風，甚至蝙蝠都可以幫助授粉。"},{"en":"Without pollination, many fruits and seeds would not develop.","zh":"沒有授粉，許多果實和種子都不會形成。"},{"en":"The word describes a key step in plant reproduction.","zh":"這個詞描述植物繁殖中的關鍵步驟。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":9},{"front":"bristles","meaning":"硬毛","examples":[{"en":"Lorikeets’ tongues have bristles that help collect pollen.","zh":"吸蜜鸚鵡的舌頭有硬毛，幫助收集花粉。"},{"en":"Bristles are short, stiff hairs or hair-like structures.","zh":"bristles 是短而硬的毛或類似毛的結構。"},{"en":"A toothbrush has bristles that clean between teeth.","zh":"牙刷有硬毛，用來清潔牙齒之間。"},{"en":"On an animal’s tongue, bristles can help hold liquid, pollen, or small food pieces.","zh":"在動物舌頭上，硬毛可以幫助盛載液體、花粉或小食物碎片。"},{"en":"The word describes stiff little projections used for contact or collection.","zh":"這個詞描述用於接觸或收集的小硬突起。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":10},{"front":"collect as much pollen as possible","meaning":"收集盡可能多的花粉","examples":[{"en":"The bristles help lorikeets collect as much pollen as possible.","zh":"這些硬毛幫助吸蜜鸚鵡收集盡可能多的花粉。"},{"en":"To collect as much pollen as possible means to gather the greatest possible amount of pollen.","zh":"collect as much pollen as possible 指收集最大可能數量的花粉。"},{"en":"A bee visits many flowers to collect as much pollen as possible for the hive.","zh":"蜜蜂拜訪許多花朵，為蜂巢收集盡可能多的花粉。"},{"en":"Collecting more pollen can benefit both the animal and the plants it visits.","zh":"收集更多花粉可以同時有利於動物和牠拜訪的植物。"},{"en":"The phrase describes gathering the maximum amount of pollen.","zh":"這個短語描述收集最大量花粉。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":10},{"front":"inhabit woodland and open forest","meaning":"棲息於林地和開闊森林","examples":[{"en":"Most Australian parrots inhabit woodland and open forest.","zh":"大多數澳洲鸚鵡棲息於林地和開闊森林。"},{"en":"To inhabit woodland and open forest means to live in tree-covered areas that are not as dense as rainforest.","zh":"inhabit woodland and open forest 指生活在有樹但不像雨林那樣茂密的地方。"},{"en":"Many birds inhabit woodland and open forest because these places provide trees, seeds, and nesting holes.","zh":"許多鳥類棲息於林地和開闊森林，因為這些地方提供樹木、種子和巢洞。"},{"en":"Such habitats can support parrots while still allowing them to fly and feed in open spaces.","zh":"這些棲息地能支撐鸚鵡，同時讓牠們在開闊空間飛行和覓食。"},{"en":"The phrase describes the normal habitat of many Australian parrots.","zh":"這個短語描述許多澳洲鸚鵡的正常棲息地。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":10},{"front":"open forest","meaning":"開闊森林","examples":[{"en":"Many parrots live in open forest rather than dense rainforest.","zh":"許多鸚鵡生活在開闊森林，而不是茂密雨林。"},{"en":"Open forest is forest with trees spaced far enough apart to allow light and movement.","zh":"open forest 是樹木相隔較遠、容許光線和活動的森林。"},{"en":"A walker can often see farther in open forest than in thick jungle.","zh":"行山者在開闊森林中通常比在濃密叢林中看得更遠。"},{"en":"Open forest may provide both tree cover and feeding space on the ground.","zh":"開闊森林可以同時提供樹木遮蔽和地面覓食空間。"},{"en":"The phrase describes a less dense type of forest.","zh":"這個短語描述較不茂密的森林類型。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":10},{"front":"numbers decline towards","meaning":"數量朝……方向下降","examples":[{"en":"Parrot numbers decline towards deserts and wetter areas.","zh":"鸚鵡數量朝沙漠和較潮濕地區方向下降。"},{"en":"Numbers decline towards a place means the population becomes smaller as one moves in that direction.","zh":"numbers decline towards 某地，指越往該方向，數量越少。"},{"en":"Shop numbers may decline towards the edge of a town.","zh":"商店數量可能朝市鎮邊緣方向下降。"},{"en":"Species numbers decline where conditions become less suitable.","zh":"當環境變得較不適合，物種數量就會下降。"},{"en":"The phrase describes a decreasing pattern across space.","zh":"這個短語描述空間上的遞減模式。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":10},{"front":"wetter areas","meaning":"較潮濕地區","examples":[{"en":"Parrot numbers also decline towards wetter areas.","zh":"鸚鵡數量亦朝較潮濕地區方向下降。"},{"en":"Wetter areas are places with more rain, moisture, or humidity.","zh":"wetter areas 是有較多降雨、水分或濕度的地方。"},{"en":"Wetter areas may support dense plants but not always the food preferred by every bird.","zh":"較潮濕地區可能支持茂密植物，但未必總有每種鳥偏好的食物。"},{"en":"Too much moisture can change the type of vegetation and available nesting sites.","zh":"水分過多可以改變植被類型和可用築巢地點。"},{"en":"The phrase describes areas with higher water availability.","zh":"這個短語描述水分較多的地區。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":10},{"front":"nomadic to some degree","meaning":"在某程度上游牧式遷移的","examples":[{"en":"Most Australian parrots are nomadic to some degree.","zh":"大多數澳洲鸚鵡在某程度上是游牧式遷移的。"},{"en":"Nomadic to some degree means partly moving from place to place rather than staying permanently in one area.","zh":"nomadic to some degree 指在某程度上從一地移到另一地，而不是永久停留一處。"},{"en":"Some workers are nomadic to some degree if they travel between cities for projects.","zh":"如果員工因項目在城市之間移動，他們在某程度上也是游牧式的。"},{"en":"Animals may become nomadic when food and water appear unpredictably.","zh":"當食物和水源出現得不可預測，動物可能變得游牧式遷移。"},{"en":"The phrase describes partial or flexible movement.","zh":"這個短語描述部分或靈活的移動。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":10},{"front":"take advantage of","meaning":"利用","examples":[{"en":"Parrots move to take advantage of feeding and breeding sites.","zh":"鸚鵡移動以利用覓食和繁殖地點。"},{"en":"To take advantage of something means to use an opportunity or resource effectively.","zh":"take advantage of 某物，指有效利用機會或資源。"},{"en":"Students can take advantage of free library hours to revise after school.","zh":"學生可以利用免費圖書館開放時間，在放學後溫習。"},{"en":"Animals take advantage of seasonal food when it becomes available.","zh":"當季節性食物出現時，動物會利用它。"},{"en":"The phrase can be positive when it means making good use of something.","zh":"當意思是善用某物時，這個短語可以是正面的。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":10},{"front":"feeding and breeding sites","meaning":"覓食和繁殖地點","examples":[{"en":"Parrots move in search of feeding and breeding sites.","zh":"鸚鵡四處移動尋找覓食和繁殖地點。"},{"en":"Feeding and breeding sites are places where animals find food and reproduce.","zh":"feeding and breeding sites 是動物尋找食物和繁殖的地方。"},{"en":"A wetland may provide feeding and breeding sites for ducks and frogs.","zh":"濕地可能為鴨和青蛙提供覓食和繁殖地點。"},{"en":"If these sites disappear, animal populations may fall even if adults survive.","zh":"如果這些地點消失，即使成年動物存活，種群也可能下降。"},{"en":"The phrase links survival with reproduction.","zh":"這個短語把生存與繁殖連接起來。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":10},{"front":"dry-country parrots","meaning":"乾旱地區鸚鵡","examples":[{"en":"The galah and the corella are dry-country parrots.","zh":"粉紅鳳頭鸚鵡和小葵花鳳頭鸚鵡是乾旱地區鸚鵡。"},{"en":"Dry-country parrots are parrots adapted to drier inland or grassland areas.","zh":"dry-country parrots 是適應較乾旱內陸或草原地區的鸚鵡。"},{"en":"Dry-country parrots may travel widely to find water and seeds.","zh":"乾旱地區鸚鵡可能大範圍移動以尋找水和種子。"},{"en":"These birds often succeed where rainforest parrots would struggle.","zh":"這些鳥常能在雨林鸚鵡難以生存的地方成功生存。"},{"en":"The phrase identifies parrots suited to dry habitats.","zh":"這個短語指出適合乾旱棲息地的鸚鵡。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":10},{"front":"galah","meaning":"粉紅鳳頭鸚鵡","examples":[{"en":"The galah has expanded its range in recent years.","zh":"粉紅鳳頭鸚鵡近年來擴大了分布範圍。"},{"en":"A galah is an Australian cockatoo known for its pink and grey colouring.","zh":"galah 是一種以粉紅和灰色羽毛聞名的澳洲鳳頭鸚鵡。"},{"en":"People may see galahs feeding on open grasslands or near farms.","zh":"人們可能看見粉紅鳳頭鸚鵡在開闊草地或農場附近覓食。"},{"en":"Galahs can benefit when land clearing creates more open feeding areas.","zh":"當清除林地創造更多開闊覓食區，粉紅鳳頭鸚鵡可能受惠。"},{"en":"The word names a particular Australian parrot species.","zh":"這個詞命名一種特定澳洲鸚鵡物種。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":11},{"front":"corella","meaning":"小葵花鳳頭鸚鵡","examples":[{"en":"The corella has also adapted well to environmental change.","zh":"小葵花鳳頭鸚鵡也很好地適應了環境變化。"},{"en":"A corella is a type of Australian cockatoo, often pale-coloured and social.","zh":"corella 是一種澳洲鳳頭鸚鵡，通常顏色較淺且群居。"},{"en":"Corellas may gather in large noisy groups near fields or water.","zh":"小葵花鳳頭鸚鵡可能在田地或水源附近成群喧鬧聚集。"},{"en":"Like galahs, corellas can use open habitats created by human activity.","zh":"像粉紅鳳頭鸚鵡一樣，小葵花鳳頭鸚鵡能利用人類活動創造的開闊棲息地。"},{"en":"The word refers to a parrot species that can cope with changed landscapes.","zh":"這個詞指能應對改變後景觀的一種鸚鵡物種。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":11},{"front":"expand one’s range","meaning":"擴大分布範圍","examples":[{"en":"Some dry-country parrots have expanded their ranges.","zh":"有些乾旱地區鸚鵡擴大了分布範圍。"},{"en":"To expand one’s range means to spread into a larger area than before.","zh":"expand one’s range 指擴散到比以前更大的範圍。"},{"en":"A restaurant may expand its delivery range after buying more motorcycles.","zh":"餐廳買入更多電單車後，可能擴大外送範圍。"},{"en":"Animals expand their range when new habitats become suitable or barriers disappear.","zh":"當新棲息地變得適合或障礙消失，動物就會擴大分布範圍。"},{"en":"The phrase describes widening the area where something operates or lives.","zh":"這個短語描述擴闊某物運作或生活的範圍。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":11},{"front":"in recent years","meaning":"近年來","examples":[{"en":"Some parrot species have expanded their ranges in recent years.","zh":"有些鸚鵡物種近年來擴大了分布範圍。"},{"en":"In recent years means during the last few years or the near past.","zh":"in recent years 指在過去幾年或較近的過去。"},{"en":"In recent years, many students have used online tools for revision.","zh":"近年來，許多學生使用網上工具溫習。"},{"en":"The phrase signals that the change is modern or relatively new.","zh":"這個短語表示變化是現代或相對較新的。"},{"en":"It helps readers place a trend close to the present.","zh":"它幫助讀者把趨勢放近現在。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":11},{"front":"be among the species that","meaning":"屬於……的物種之一","examples":[{"en":"Galahs and corellas are among the species that adapted well.","zh":"粉紅鳳頭鸚鵡和小葵花鳳頭鸚鵡屬於適應良好的物種之一。"},{"en":"To be among the species that do something means to be included in that group of species.","zh":"be among the species that 做某事，指被包括在做該事的一組物種之中。"},{"en":"Dolphins are among the animals that show complex social behaviour.","zh":"海豚屬於展現複雜社交行為的動物之一。"},{"en":"This phrase places one example inside a wider category.","zh":"這個短語把一個例子放進更大類別之中。"},{"en":"It is useful when listing members of a larger group.","zh":"它在列舉較大群體成員時很有用。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":11},{"front":"adapt well to","meaning":"很好地適應","examples":[{"en":"Some parrots adapted well to changes caused by settlement.","zh":"有些鸚鵡很好地適應了由定居造成的變化。"},{"en":"To adapt well to something means to adjust successfully to it.","zh":"adapt well to 某事，指成功適應它。"},{"en":"A student may adapt well to a new school if classmates are friendly.","zh":"如果同學友善，學生可能很好地適應新學校。"},{"en":"Species that adapt well to change may increase while others decline.","zh":"很好地適應變化的物種可能增加，而其他物種則減少。"},{"en":"The phrase describes successful adjustment.","zh":"這個短語描述成功調整。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":11},{"front":"changes brought about by","meaning":"由……帶來的變化","examples":[{"en":"European settlement brought about major changes to the landscape.","zh":"歐洲人定居為地貌帶來重大變化。"},{"en":"Changes brought about by something are changes caused by it.","zh":"changes brought about by 某事，是由它造成的變化。"},{"en":"Changes brought about by online shopping include fewer visits to some physical stores.","zh":"由網上購物帶來的變化包括某些實體店到訪減少。"},{"en":"When a cause is named, readers can see why the situation changed.","zh":"當原因被指出，讀者就能看見情況為何改變。"},{"en":"The phrase links a change to its cause.","zh":"這個短語把變化與其原因連接起來。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":11},{"front":"European settlement","meaning":"歐洲人定居","examples":[{"en":"European settlement changed many Australian habitats.","zh":"歐洲人定居改變了許多澳洲棲息地。"},{"en":"European settlement means Europeans moving into and establishing communities in a place.","zh":"European settlement 指歐洲人遷入某地並建立社區。"},{"en":"European settlement often involved farming, road building, and clearing land.","zh":"歐洲人定居常涉及農業、修路和清理土地。"},{"en":"Such settlement can benefit some species but damage others.","zh":"這種定居可能有利於某些物種，但傷害其他物種。"},{"en":"The phrase describes a historical process of colonisation and land use change.","zh":"這個短語描述殖民和土地使用變化的歷史過程。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":11},{"front":"forest felling","meaning":"伐林","examples":[{"en":"Forest felling created grasslands for some parrots.","zh":"伐林為某些鸚鵡創造了草原。"},{"en":"Forest felling means cutting down trees in a forest.","zh":"forest felling 指砍伐森林中的樹木。"},{"en":"Forest felling may happen when land is cleared for farms or buildings.","zh":"當土地被清理作農田或建築用途時，可能發生伐林。"},{"en":"Removing trees can create open land but also destroy homes for forest animals.","zh":"移除樹木可以創造開闊土地，但也會破壞森林動物的家園。"},{"en":"The phrase describes deliberate tree removal.","zh":"這個短語描述有意砍樹。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":11},{"front":"create grasslands","meaning":"創造草原","examples":[{"en":"Forest felling created grasslands where galahs and corellas thrive.","zh":"伐林創造了粉紅鳳頭鸚鵡和小葵花鳳頭鸚鵡繁盛的草原。"},{"en":"To create grasslands means to turn an area into open land covered mainly with grass.","zh":"create grasslands 指把某區域變成主要覆蓋草的開闊土地。"},{"en":"Clearing trees for cattle may create grasslands around a farm.","zh":"為飼養牛隻清除樹木可能在農場周圍創造草原。"},{"en":"Grasslands can help some seed-eating birds but harm species needing old forests.","zh":"草原可以幫助某些食種子鳥類，但傷害需要老森林的物種。"},{"en":"The phrase describes a change from wooded land to open grassy land.","zh":"這個短語描述由林地變成開闊草地的改變。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":11},{"front":"thrive","meaning":"茁壯成長；繁盛","examples":[{"en":"Galahs and corellas thrive in grassland habitats.","zh":"粉紅鳳頭鸚鵡和小葵花鳳頭鸚鵡在草原棲息地繁盛。"},{"en":"To thrive means to grow, live, or succeed very well.","zh":"thrive 指生長、生活或成功得非常好。"},{"en":"A student may thrive in a small class where the teacher gives individual feedback.","zh":"如果老師給予個別回饋，學生可能在小班中茁壯成長。"},{"en":"Animals thrive when the habitat provides enough food, safety, and breeding space.","zh":"當棲息地提供足夠食物、安全和繁殖空間，動物就會繁盛。"},{"en":"The word describes strong success, not just survival.","zh":"這個詞描述強盛成功，而不只是存活。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":12},{"front":"fare so well","meaning":"過得同樣好；情況同樣理想","examples":[{"en":"Other parrot species did not fare so well after habitat change.","zh":"其他鸚鵡物種在棲息地改變後情況並不同樣理想。"},{"en":"To fare so well means to do as successfully or remain in as good a condition.","zh":"fare so well 指同樣成功或維持同樣良好狀態。"},{"en":"One shop may grow after a new road opens, while another does not fare so well.","zh":"新道路開通後，一間商店可能增長，另一間則未必同樣理想。"},{"en":"Species that cannot use changed habitats may not fare well after human development.","zh":"不能利用改變後棲息地的物種，在人類發展後可能情況不佳。"},{"en":"The phrase compares how well different people, groups, or species cope.","zh":"這個短語比較不同人、群體或物種應對得有多好。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":12},{"front":"environments were altered","meaning":"環境被改變","examples":[{"en":"Some parrots declined when their environments were altered.","zh":"當環境被改變，有些鸚鵡數量下降。"},{"en":"If environments were altered, the places where living things live were changed.","zh":"environments were altered 指生物生活的地方被改變。"},{"en":"A pond environment may be altered when roads are built nearby.","zh":"當附近建道路，池塘環境可能被改變。"},{"en":"Altered environments can remove food sources, shelter, or nesting places.","zh":"被改變的環境可以移除食物來源、庇護或築巢地點。"},{"en":"The phrase describes habitats being changed from their original state.","zh":"這個短語描述棲息地從原本狀態被改變。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":12},{"front":"clearing of large areas of rainforest","meaning":"清除大片雨林","examples":[{"en":"The clearing of large areas of rainforest harmed some species.","zh":"清除大片雨林傷害了一些物種。"},{"en":"Clearing of large areas of rainforest means removing trees from big rainforest regions.","zh":"clearing of large areas of rainforest 指移除大片雨林地區的樹木。"},{"en":"Clearing large forest areas for farms can destroy homes for birds and insects.","zh":"為農田清除大片森林可以破壞鳥類和昆蟲的家園。"},{"en":"When large areas are cleared, small forest-dependent species may disappear quickly.","zh":"當大片地區被清除，依賴森林的小型物種可能迅速消失。"},{"en":"The phrase describes major habitat destruction.","zh":"這個短語描述重大棲息地破壞。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":12},{"front":"be responsible for","meaning":"是……的原因","examples":[{"en":"Habitat clearing was probably responsible for the species’ disappearance.","zh":"棲息地清除很可能是該物種消失的原因。"},{"en":"To be responsible for something means to be the cause of it.","zh":"be responsible for 某事，指是它的成因。"},{"en":"Poor planning may be responsible for delays in a school project.","zh":"規劃不善可能是學校項目延誤的原因。"},{"en":"In environmental writing, the phrase often links human action with damage.","zh":"在環境寫作中，這個短語常把人類行動與破壞連接起來。"},{"en":"It identifies what likely caused a result.","zh":"它指出某結果的可能原因。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":12},{"front":"disappearance","meaning":"消失","examples":[{"en":"The disappearance of the double-eyed fig parrot was linked to rainforest clearing.","zh":"雙眼無花果鸚鵡的消失與雨林清除有關。"},{"en":"Disappearance means the act or process of no longer being seen or existing in a place.","zh":"disappearance 指不再被看見或不再存在於某地的行為或過程。"},{"en":"The disappearance of a small shop may leave a neighbourhood without basic services.","zh":"小店消失可能令社區失去基本服務。"},{"en":"In ecology, disappearance can mean local extinction after habitat loss.","zh":"在生態學中，消失可以指棲息地流失後的局部滅絕。"},{"en":"The word describes something vanishing from view or from an area.","zh":"這個詞描述某物從視野或某區域中消失。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":12},{"front":"double-eyed fig parrot","meaning":"雙眼無花果鸚鵡","examples":[{"en":"The double-eyed fig parrot disappeared after habitat loss.","zh":"雙眼無花果鸚鵡在棲息地流失後消失。"},{"en":"The double-eyed fig parrot is a parrot species associated with fig trees and rainforest habitat.","zh":"double-eyed fig parrot 是一種與無花果樹和雨林棲息地有關的鸚鵡物種。"},{"en":"A bird like the double-eyed fig parrot may suffer if the trees it depends on are removed.","zh":"像雙眼無花果鸚鵡這樣的鳥，如果依賴的樹木被移除，可能會受害。"},{"en":"Specialist species are often more vulnerable when their specific habitat disappears.","zh":"當特定棲息地消失，專門化物種常較脆弱。"},{"en":"The phrase names a particular parrot affected by habitat change.","zh":"這個短語命名一種受棲息地變化影響的特定鸚鵡。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":12},{"front":"ground-parrot numbers","meaning":"地鸚鵡數量","examples":[{"en":"Ground-parrot numbers declined after habitat destruction.","zh":"棲息地破壞後，地鸚鵡數量下降。"},{"en":"Ground-parrot numbers means the population size of ground parrots.","zh":"ground-parrot numbers 指地鸚鵡的種群數量。"},{"en":"Scientists may count ground-parrot numbers by listening for calls in suitable habitat.","zh":"科學家可能透過在合適棲息地聆聽叫聲來點算地鸚鵡數量。"},{"en":"Falling numbers can warn that a species is losing food, shelter, or breeding space.","zh":"數量下降可以警示物種正失去食物、庇護或繁殖空間。"},{"en":"The phrase describes how many ground parrots remain.","zh":"這個短語描述仍有多少地鸚鵡。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":12},{"front":"decline after","meaning":"在……之後下降","examples":[{"en":"Ground-parrot numbers declined after coastal swamps were drained.","zh":"沿海沼澤被排乾後，地鸚鵡數量下降。"},{"en":"To decline after something means to decrease following that event.","zh":"decline after 某事，指在該事件之後減少。"},{"en":"A student’s grades may decline after several weeks of poor sleep.","zh":"學生在數星期睡眠不足後，成績可能下降。"},{"en":"The phrase helps show a time relationship between a cause and a later fall.","zh":"這個短語幫助顯示原因與後來下降之間的時間關係。"},{"en":"It does not always prove cause, but it suggests a connection.","zh":"它不一定證明因果，但暗示有關聯。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":12},{"front":"habitat was destroyed","meaning":"棲息地被破壞","examples":[{"en":"Their habitat was destroyed by the draining of coastal swamps.","zh":"牠們的棲息地因沿海沼澤被排乾而被破壞。"},{"en":"If habitat was destroyed, the natural home of a species was damaged or removed.","zh":"habitat was destroyed 指某物種的天然家園被損壞或移除。"},{"en":"A frog’s habitat may be destroyed when a wetland is filled for construction.","zh":"當濕地被填平作建築用途，青蛙的棲息地可能被破壞。"},{"en":"Habitat destruction can cause animals to leave, fail to breed, or die.","zh":"棲息地破壞可以令動物離開、無法繁殖或死亡。"},{"en":"The phrase describes severe damage to a living environment.","zh":"這個短語描述生活環境受到嚴重損害。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":12},{"front":"draining of coastal swamps","meaning":"排乾沿海沼澤","examples":[{"en":"The draining of coastal swamps destroyed ground-parrot habitat.","zh":"排乾沿海沼澤破壞了地鸚鵡棲息地。"},{"en":"Draining of coastal swamps means removing water from wetlands near the sea.","zh":"draining of coastal swamps 指從靠近海岸的濕地移走水分。"},{"en":"Draining a swamp may create farmland, but it can destroy wetland animals’ homes.","zh":"排乾沼澤可能創造農田，但會破壞濕地動物的家園。"},{"en":"When wet areas are drained, plants and insects that depend on water may disappear.","zh":"當濕地被排乾，依賴水的植物和昆蟲可能消失。"},{"en":"The phrase describes a human action that dries out wetland habitat.","zh":"這個短語描述令濕地棲息地變乾的人類行動。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":13},{"front":"coastal swamps","meaning":"沿海沼澤","examples":[{"en":"Coastal swamps provided habitat for ground parrots.","zh":"沿海沼澤為地鸚鵡提供棲息地。"},{"en":"Coastal swamps are wetland areas near the sea.","zh":"coastal swamps 是靠近海洋的濕地區域。"},{"en":"Coastal swamps may contain reeds, muddy ground, insects, and nesting spaces.","zh":"沿海沼澤可能有蘆葦、泥地、昆蟲和築巢空間。"},{"en":"These wetlands can protect wildlife but are often drained for farms or buildings.","zh":"這些濕地可以保護野生動物，但常被排乾作農田或建築用途。"},{"en":"The phrase describes wet habitats along the coast.","zh":"這個短語描述沿海濕地棲息地。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":13},{"front":"initially benefited from","meaning":"起初受惠於","examples":[{"en":"Some species initially benefited from forest clearing.","zh":"有些物種起初受惠於清除森林。"},{"en":"To initially benefit from something means to gain an advantage at first.","zh":"initially benefit from 某事，指一開始從中獲得好處。"},{"en":"A shop may initially benefit from a new road because more customers pass by.","zh":"商店可能起初受惠於新道路，因為更多顧客經過。"},{"en":"Early benefits may disappear later if new problems develop.","zh":"如果後來出現新問題，早期好處可能消失。"},{"en":"The phrase describes a positive effect at the beginning.","zh":"這個短語描述開始時的正面影響。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":13},{"front":"face a shortage of","meaning":"面對……短缺","examples":[{"en":"Some parrots now face a shortage of nesting sites.","zh":"有些鸚鵡現在面對築巢地點短缺。"},{"en":"To face a shortage of something means to not have enough of it.","zh":"face a shortage of 某物，指沒有足夠該物。"},{"en":"A school may face a shortage of teachers if many staff leave at once.","zh":"如果許多教職員同時離職，學校可能面對教師短缺。"},{"en":"Shortages can force competition because several groups need the same limited resource.","zh":"短缺可以迫使競爭出現，因為幾個群體需要同一有限資源。"},{"en":"The phrase describes a serious lack of something necessary.","zh":"這個短語描述某種必需品嚴重不足。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":13},{"front":"nesting sites","meaning":"築巢地點","examples":[{"en":"Old trees often provide important nesting sites for parrots.","zh":"老樹常為鸚鵡提供重要築巢地點。"},{"en":"Nesting sites are places where birds or animals build nests and raise young.","zh":"nesting sites 是鳥類或動物築巢和養育幼崽的地方。"},{"en":"A bird may choose nesting sites in tree holes, cliffs, roofs, or bushes.","zh":"鳥類可能選擇樹洞、懸崖、屋頂或灌木作築巢地點。"},{"en":"Losing nesting sites can reduce the number of young animals that survive.","zh":"失去築巢地點可以減少能存活的幼鳥數量。"},{"en":"The phrase describes places used for reproduction and shelter.","zh":"這個短語描述用於繁殖和庇護的地方。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":13},{"front":"human-made changes","meaning":"人為變化","examples":[{"en":"Further human-made changes created new problems for parrots.","zh":"進一步人為變化為鸚鵡創造了新問題。"},{"en":"Human-made changes are changes caused by people rather than natural processes.","zh":"human-made changes 是由人類而非自然過程造成的變化。"},{"en":"Roads, farms, dams, and buildings are human-made changes to a landscape.","zh":"道路、農場、水壩和建築物都是景觀中的人為變化。"},{"en":"Human-made changes can help some species while harming others.","zh":"人為變化可以幫助某些物種，同時傷害其他物種。"},{"en":"The phrase describes environmental changes caused by human activity.","zh":"這個短語描述由人類活動造成的環境變化。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":13},{"front":"new conditions","meaning":"新環境","examples":[{"en":"New conditions sometimes favour incoming species.","zh":"新環境有時更有利於新遷入物種。"},{"en":"New conditions are changed circumstances or environments that did not exist before.","zh":"new conditions 是以前不存在的改變後情況或環境。"},{"en":"After a school changes its timetable, students must adjust to new conditions.","zh":"學校改變時間表後，學生必須適應新環境。"},{"en":"In nature, new conditions can alter which species survive best.","zh":"在自然界，新環境可以改變哪些物種最能生存。"},{"en":"The phrase describes a changed situation that affects behaviour or success.","zh":"這個短語描述影響行為或成功的改變後情況。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":13},{"front":"favour A over B","meaning":"相比B更有利於A","examples":[{"en":"New conditions may favour an incoming species over a native one.","zh":"新環境相比本土物種，可能更有利於新遷入物種。"},{"en":"To favour A over B means to give A an advantage compared with B.","zh":"favour A over B 指相比B給予A優勢。"},{"en":"Online booking may favour large hotels over small guesthouses.","zh":"網上預訂相比小型民宿，可能更有利於大型酒店。"},{"en":"Environmental change can favour species that use open land over species that need forests.","zh":"環境變化相比需要森林的物種，可能更有利於使用開闊土地的物種。"},{"en":"The phrase describes unequal advantage between two choices or groups.","zh":"這個短語描述兩個選項或群體之間不均等的優勢。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":13},{"front":"incoming species","meaning":"新遷入物種","examples":[{"en":"An incoming species may outcompete the species already living there.","zh":"新遷入物種可能在競爭中勝過原本生活在那裏的物種。"},{"en":"An incoming species is a species that moves into an area where it was not previously established.","zh":"incoming species 是移入以前未定居地區的物種。"},{"en":"A new fish introduced into a pond may become an incoming species.","zh":"被引入池塘的新魚可能成為新遷入物種。"},{"en":"Incoming species can create pressure if they compete for food, space, or nesting sites.","zh":"如果新遷入物種競爭食物、空間或築巢地點，就會造成壓力。"},{"en":"The phrase describes a species newly arriving in a habitat.","zh":"這個短語描述新到達某棲息地的物種。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":13},{"front":"originally inhabit","meaning":"原本棲息於","examples":[{"en":"One species originally inhabited the area before another arrived.","zh":"在另一物種到達之前，一個物種原本棲息於該地區。"},{"en":"To originally inhabit a place means to live there before later changes or arrivals.","zh":"originally inhabit 某地，指在後來變化或新來者到達之前生活在那裏。"},{"en":"A family may originally inhabit an old village before moving to the city.","zh":"一個家庭可能原本住在舊村落，後來才搬到城市。"},{"en":"In ecology, the species that originally inhabited an area may lose out to newcomers.","zh":"在生態學中，原本棲息於某地的物種可能輸給新來者。"},{"en":"The phrase describes the earlier natural resident of a place.","zh":"這個短語描述某地較早的自然居民。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":13},{"front":"Kangaroo Island","meaning":"袋鼠島","examples":[{"en":"Galahs colonised Kangaroo Island after farmers cleared forest.","zh":"農民清除森林後，粉紅鳳頭鸚鵡移居並繁衍於袋鼠島。"},{"en":"Kangaroo Island is an island off the coast of South Australia.","zh":"Kangaroo Island 是位於南澳洲海岸對開的島嶼。"},{"en":"Island habitats can be sensitive because species have limited space to move away.","zh":"島嶼棲息地可能很敏感，因為物種可遷離的空間有限。"},{"en":"Changes on Kangaroo Island affected which parrots could nest and survive there.","zh":"袋鼠島上的變化影響哪些鸚鵡能在那裏築巢和生存。"},{"en":"The phrase names the specific island used as an ecological example.","zh":"這個短語命名被用作生態例子的特定島嶼。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":14},{"front":"off the coast of","meaning":"位於……海岸對開","examples":[{"en":"Kangaroo Island lies off the coast of South Australia.","zh":"袋鼠島位於南澳洲海岸對開。"},{"en":"Off the coast of a place means in the sea near that place’s coastline.","zh":"off the coast of 某地，指位於該地海岸附近的海上。"},{"en":"A small island may lie off the coast of a fishing village.","zh":"小島可能位於漁村海岸對開。"},{"en":"Islands off the coast can have different wildlife from the mainland.","zh":"海岸對開的島嶼可能有與大陸不同的野生動物。"},{"en":"The phrase describes location near but not on the land.","zh":"這個短語描述靠近但不在陸地上的位置。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":14},{"front":"clear large areas of forest","meaning":"清除大片森林","examples":[{"en":"Farmers cleared large areas of forest on Kangaroo Island.","zh":"農民在袋鼠島清除大片森林。"},{"en":"To clear large areas of forest means to remove trees from wide forested land.","zh":"clear large areas of forest 指從廣大林地移除樹木。"},{"en":"Developers may clear large areas of forest to build roads or houses.","zh":"發展商可能清除大片森林來建道路或房屋。"},{"en":"Clearing forest can create farmland but remove nesting holes and food sources.","zh":"清除森林可以創造農田，但會移除巢洞和食物來源。"},{"en":"The phrase describes major tree removal over a broad area.","zh":"這個短語描述大範圍重大移除樹木。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":14},{"front":"colonise the island","meaning":"移居並繁衍於島上","examples":[{"en":"Galahs colonised the island after the forest was cleared.","zh":"森林被清除後，粉紅鳳頭鸚鵡移居並繁衍於島上。"},{"en":"To colonise the island means to move onto the island and establish a breeding population there.","zh":"colonise the island 指移到島上並在那裏建立繁殖種群。"},{"en":"Birds may colonise an island if storms carry them there and food is available.","zh":"如果風暴把鳥帶到島上，而當地有食物，鳥類可能移居並繁衍於島上。"},{"en":"Once a species colonises an island, it may compete with species already living there.","zh":"一旦某物種移居並繁衍於島上，就可能與原本生活在那裏的物種競爭。"},{"en":"The phrase describes successful settlement on an island.","zh":"這個短語描述在島上的成功定居。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":14},{"front":"nesting holes","meaning":"巢洞","examples":[{"en":"Galahs entered nesting holes used by black-cockatoos.","zh":"粉紅鳳頭鸚鵡進入黑鳳頭鸚鵡使用的巢洞。"},{"en":"Nesting holes are hollow spaces, often in trees, where birds can nest.","zh":"nesting holes 是常見於樹中的空洞，鳥類可在其中築巢。"},{"en":"Old trees may contain nesting holes large enough for parrots.","zh":"老樹可能有足夠大供鸚鵡使用的巢洞。"},{"en":"If nesting holes are scarce, birds may fight or compete for them.","zh":"如果巢洞稀少，鳥類可能為爭奪它們而打鬥或競爭。"},{"en":"The phrase describes natural cavities used for raising young.","zh":"這個短語描述用於養育幼鳥的天然洞穴。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":14},{"front":"black-cockatoo eggs","meaning":"黑鳳頭鸚鵡蛋","examples":[{"en":"Galahs destroyed black-cockatoo eggs.","zh":"粉紅鳳頭鸚鵡破壞黑鳳頭鸚鵡蛋。"},{"en":"Black-cockatoo eggs are eggs laid by black-cockatoos in nesting hollows.","zh":"black-cockatoo eggs 是黑鳳頭鸚鵡在樹洞巢中產下的蛋。"},{"en":"If another bird destroys black-cockatoo eggs, fewer young black-cockatoos will hatch.","zh":"如果另一種鳥破壞黑鳳頭鸚鵡蛋，孵化出的幼鳥就會減少。"},{"en":"Egg destruction can quickly reduce a small bird population.","zh":"蛋被破壞可以迅速減少小型鳥類種群。"},{"en":"The phrase identifies the vulnerable young stage of black-cockatoos.","zh":"這個短語指出黑鳳頭鸚鵡脆弱的幼年階段。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":14},{"front":"occupy the holes","meaning":"佔用巢洞","examples":[{"en":"Galahs destroyed eggs so they could occupy the holes.","zh":"粉紅鳳頭鸚鵡破壞鳥蛋，以便佔用巢洞。"},{"en":"To occupy the holes means to take and use the hollow spaces as nesting places.","zh":"occupy the holes 指取得並使用空洞作築巢地點。"},{"en":"A bird may occupy a hole in an old tree before another bird can use it.","zh":"鳥類可能在另一隻鳥使用前佔用老樹中的洞。"},{"en":"Occupying a nesting hole gives a bird shelter and a place to raise young.","zh":"佔用巢洞給鳥類庇護和養育幼鳥的地方。"},{"en":"The phrase describes taking control of limited nesting spaces.","zh":"這個短語描述取得有限築巢空間的控制權。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":14},{"front":"precipitate","meaning":"促成；引發","examples":[{"en":"The galahs’ success precipitated a collapse in the black-cockatoo population.","zh":"粉紅鳳頭鸚鵡的成功促成黑鳳頭鸚鵡種群崩潰。"},{"en":"To precipitate something means to cause it to happen suddenly or sooner.","zh":"precipitate 某事，指促使它突然或更早發生。"},{"en":"A sudden rent increase may precipitate the closure of a small shop.","zh":"租金突然上升可能促成小店結業。"},{"en":"In ecology, one species’ success can precipitate another species’ decline.","zh":"在生態學中，一個物種的成功可以引發另一物種衰退。"},{"en":"The word describes triggering a serious result.","zh":"這個詞描述觸發嚴重結果。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":14},{"front":"partial collapse","meaning":"局部崩潰","examples":[{"en":"The black-cockatoo population suffered a partial collapse.","zh":"黑鳳頭鸚鵡種群遭受局部崩潰。"},{"en":"A partial collapse is a serious decline that affects part of a system or population but does not destroy it completely.","zh":"partial collapse 是影響某系統或種群一部分、但未完全摧毀它的嚴重下降。"},{"en":"A school club may suffer a partial collapse if many members leave but a small group remains.","zh":"如果許多成員離開但仍有小組留下，學會可能遭受局部崩潰。"},{"en":"Partial collapse can still be dangerous because recovery may be difficult.","zh":"局部崩潰仍可能危險，因為復原可能困難。"},{"en":"The phrase describes severe but not total failure.","zh":"這個短語描述嚴重但非全面的失敗。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":14},{"front":"black-cockatoo population","meaning":"黑鳳頭鸚鵡種群","examples":[{"en":"The black-cockatoo population declined after losing nesting sites.","zh":"失去築巢地點後，黑鳳頭鸚鵡種群下降。"},{"en":"A black-cockatoo population is the group of black-cockatoos living in a particular area.","zh":"black-cockatoo population 是生活在特定地區的一群黑鳳頭鸚鵡。"},{"en":"Scientists may monitor a black-cockatoo population by counting nests and young birds.","zh":"科學家可能透過點算巢和幼鳥來監測黑鳳頭鸚鵡種群。"},{"en":"Population decline can show that a species lacks enough food or breeding places.","zh":"種群下降可以顯示物種缺乏足夠食物或繁殖地點。"},{"en":"The phrase describes the number and community of black-cockatoos in one area.","zh":"這個短語描述某地區黑鳳頭鸚鵡的數量和群體。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":14},{"front":"lose the struggle for","meaning":"在爭奪……中落敗","examples":[{"en":"Black-cockatoos lost the struggle for scarce nesting hollows.","zh":"黑鳳頭鸚鵡在爭奪稀缺樹洞巢位中落敗。"},{"en":"To lose the struggle for something means to fail in competition for a limited resource.","zh":"lose the struggle for 某物，指在爭奪有限資源中失敗。"},{"en":"Small shops may lose the struggle for customers when a large mall opens nearby.","zh":"當附近開大型商場，小店可能在爭奪顧客中落敗。"},{"en":"Animals can lose the struggle for food or nesting sites when stronger competitors arrive.","zh":"當更強競爭者到來，動物可能在爭奪食物或築巢地點中落敗。"},{"en":"The phrase describes losing in a difficult competition.","zh":"這個短語描述在艱難競爭中失敗。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":15},{"front":"scarce nesting hollows","meaning":"稀缺的樹洞巢位","examples":[{"en":"Nesting hollows became scarce after habitat change.","zh":"棲息地改變後，樹洞巢位變得稀缺。"},{"en":"Scarce nesting hollows are tree holes or cavities that are too few for the birds needing them.","zh":"scarce nesting hollows 是對需要它們的鳥類而言數量太少的樹洞或空洞。"},{"en":"Old forests often contain more nesting hollows than young plantations.","zh":"老森林通常比年輕人工林有更多樹洞巢位。"},{"en":"When nesting hollows are scarce, competition between species becomes stronger.","zh":"當樹洞巢位稀缺，物種之間的競爭會變得更強。"},{"en":"The phrase describes a limited supply of natural nest spaces.","zh":"這個短語描述天然築巢空間供應有限。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":15},{"front":"no final answer to","meaning":"對……沒有最終答案","examples":[{"en":"There may be no final answer to balancing different parrot species.","zh":"對如何平衡不同鸚鵡物種，可能沒有最終答案。"},{"en":"No final answer to a problem means there is no single complete solution that settles it forever.","zh":"no final answer to 某問題，指沒有一個能永遠解決它的單一完整方案。"},{"en":"There is no final answer to how schools should balance exams and creativity.","zh":"對學校應如何平衡考試與創意，沒有最終答案。"},{"en":"Complex problems often need ongoing adjustment rather than one perfect solution.","zh":"複雜問題常需要持續調整，而不是一個完美方案。"},{"en":"The phrase describes uncertainty in solving a difficult issue.","zh":"這個短語描述解決困難議題時的不確定性。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":15},{"front":"ensure an equitable balance","meaning":"確保公平平衡","examples":[{"en":"Conservationists try to ensure an equitable balance among parrot species.","zh":"保育人士嘗試確保鸚鵡物種之間的公平平衡。"},{"en":"To ensure an equitable balance means to make sure different groups are treated fairly and no one group dominates unfairly.","zh":"ensure an equitable balance 指確保不同群體得到公平對待，沒有一方不公平地佔優。"},{"en":"A teacher may ensure an equitable balance by giving quiet students chances to speak.","zh":"老師可能透過給安靜學生發言機會來確保公平平衡。"},{"en":"In conservation, balance is difficult when helping one species may harm another.","zh":"在保育中，當幫助一個物種可能傷害另一物種，平衡就很困難。"},{"en":"The phrase describes trying to achieve fairness between competing interests.","zh":"這個短語描述嘗試在競爭利益之間達至公平。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":15},{"front":"among parrot species","meaning":"在鸚鵡物種之間","examples":[{"en":"Competition among parrot species has increased in altered habitats.","zh":"在被改變的棲息地中，鸚鵡物種之間的競爭增加了。"},{"en":"Among parrot species means between or within different kinds of parrots.","zh":"among parrot species 指在不同種類鸚鵡之間或之中。"},{"en":"Differences among parrot species may include colour, beak shape, size, and diet.","zh":"鸚鵡物種之間的差異可能包括顏色、鳥喙形狀、大小和飲食。"},{"en":"Competition among species becomes serious when they need the same scarce resource.","zh":"當不同物種需要同一稀缺資源，物種之間的競爭會變得嚴重。"},{"en":"The phrase places the comparison inside the parrot group.","zh":"這個短語把比較放在鸚鵡群體內部。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":15},{"front":"nest-box programmes","meaning":"人工巢箱計劃","examples":[{"en":"Nest-box programmes help ease the shortage of nesting sites.","zh":"人工巢箱計劃有助紓緩築巢地點短缺。"},{"en":"Nest-box programmes are conservation projects that provide artificial boxes for birds to nest in.","zh":"nest-box programmes 是提供人工箱子讓鳥類築巢的保育項目。"},{"en":"A community group may install nest boxes in parks to help birds that have lost old trees.","zh":"社區團體可能在公園安裝巢箱，幫助失去老樹的鳥類。"},{"en":"These programmes can support breeding but cannot replace a complete natural habitat.","zh":"這些計劃可以支援繁殖，但不能取代完整天然棲息地。"},{"en":"The phrase describes organised help for animals lacking nest spaces.","zh":"這個短語描述為缺乏築巢空間的動物提供的有組織協助。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":15},{"front":"ease the shortage of","meaning":"紓緩……短缺","examples":[{"en":"Nest-box programmes can ease the shortage of nesting sites.","zh":"人工巢箱計劃可以紓緩築巢地點短缺。"},{"en":"To ease the shortage of something means to reduce the problem of not having enough of it.","zh":"ease the shortage of 某物，指減輕某物不足的問題。"},{"en":"Hiring part-time teachers may ease the shortage of staff during exam season.","zh":"聘請兼職老師可能在考試季節紓緩人手短缺。"},{"en":"A shortage is eased when supply increases or demand becomes less intense.","zh":"當供應增加或需求變得不太強烈，短缺就會被紓緩。"},{"en":"The phrase describes making a lack less severe.","zh":"這個短語描述令不足情況較不嚴重。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":15},{"front":"too few of them","meaning":"數量太少","examples":[{"en":"There are too few nest-box programmes to solve the problem fully.","zh":"人工巢箱計劃數量太少，無法完全解決問題。"},{"en":"Too few of them means the number is not enough.","zh":"too few of them 指數量不足。"},{"en":"A school may have computers, but too few of them for every student to use at once.","zh":"學校可能有電腦，但數量太少，不能讓每個學生同時使用。"},{"en":"When there are too few helpful resources, the problem can only be partly solved.","zh":"當有用資源數量太少，問題只能部分解決。"},{"en":"The phrase describes insufficient quantity.","zh":"這個短語描述數量不足。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":15},{"front":"no adequate substitute for","meaning":"不能充分替代","examples":[{"en":"Nest boxes are no adequate substitute for large, old trees.","zh":"人工巢箱不能充分替代高大的老樹。"},{"en":"No adequate substitute for something means nothing else can replace it fully or satisfactorily.","zh":"no adequate substitute for 某物，指沒有其他東西能完全或令人滿意地取代它。"},{"en":"Online messages are no adequate substitute for a doctor’s physical examination.","zh":"網上訊息不能充分替代醫生親身檢查。"},{"en":"A substitute may help partly but fail to provide all the original benefits.","zh":"替代品可能部分有幫助，但無法提供原物的所有好處。"},{"en":"The phrase stresses that replacement is incomplete.","zh":"這個短語強調替代並不完整。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":15},{"front":"large, old trees","meaning":"高大的老樹","examples":[{"en":"Large, old trees provide nesting sites and food sources.","zh":"高大的老樹提供築巢地點和食物來源。"},{"en":"Large, old trees are mature trees with big trunks, branches, hollows, flowers, or seeds.","zh":"large, old trees 是有粗大樹幹、樹枝、樹洞、花朵或種子的成熟樹木。"},{"en":"Birds often need large, old trees because young trees do not yet have nesting hollows.","zh":"鳥類常需要高大的老樹，因為年輕樹木尚未有巢洞。"},{"en":"Removing old trees can harm wildlife even if small new trees are planted later.","zh":"移除老樹會傷害野生動物，即使之後種下小樹也一樣。"},{"en":"The phrase describes mature trees that support many living things.","zh":"這個短語描述支撐許多生物的成熟樹木。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":15},{"front":"provide both A and B","meaning":"同時提供A和B","examples":[{"en":"Old trees provide both habitat and food for parrots.","zh":"老樹同時為鸚鵡提供棲息地和食物。"},{"en":"To provide both A and B means to offer two important things at the same time.","zh":"provide both A and B 指同時提供兩項重要東西。"},{"en":"A good library provides both quiet study space and useful books.","zh":"好圖書館同時提供安靜自修空間和有用書籍。"},{"en":"If one resource provides both shelter and food, losing it can cause serious harm.","zh":"如果一種資源同時提供庇護和食物，失去它可能造成嚴重傷害。"},{"en":"The phrase highlights two benefits together.","zh":"這個短語同時突出兩項好處。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":16},{"front":"nectar, pollen and seeds","meaning":"花蜜、花粉和種子","examples":[{"en":"Old trees provide nectar, pollen and seeds for parrots.","zh":"老樹為鸚鵡提供花蜜、花粉和種子。"},{"en":"Nectar, pollen and seeds are plant-based food sources used by many birds and insects.","zh":"nectar, pollen and seeds 是許多鳥類和昆蟲使用的植物性食物來源。"},{"en":"Bees collect pollen, while some birds feed on nectar and seeds.","zh":"蜜蜂收集花粉，而有些鳥以花蜜和種子為食。"},{"en":"Trees that provide these foods can support wildlife throughout different seasons.","zh":"提供這些食物的樹木可以在不同季節支撐野生動物。"},{"en":"The phrase lists key foods produced by flowering or seed-bearing plants.","zh":"這個短語列出開花或結籽植物產生的主要食物。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":16},{"front":"competition among","meaning":"……之間的競爭","examples":[{"en":"Competition among parrots for nesting sites is partly human-made.","zh":"鸚鵡之間對築巢地點的競爭部分是人為造成的。"},{"en":"Competition among a group means members of that group are trying to get the same limited resource.","zh":"competition among 某群體，指該群體成員試圖取得同一有限資源。"},{"en":"Competition among students can become unhealthy if only top scores are rewarded.","zh":"如果只獎勵最高分，學生之間的競爭可能變得不健康。"},{"en":"In nature, competition among animals increases when food or nesting places become scarce.","zh":"在自然界，當食物或築巢地點變得稀缺，動物之間的競爭會增加。"},{"en":"The phrase describes rivalry within a group.","zh":"這個短語描述群體內的競爭。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":16},{"front":"result from","meaning":"源於；由……造成","examples":[{"en":"Competition for nesting sites results from human changes to the Earth.","zh":"築巢地點競爭源於人類對地球造成的改變。"},{"en":"To result from something means to be caused by it.","zh":"result from 某事，指由它造成。"},{"en":"Traffic jams may result from poor road planning and too many cars.","zh":"交通擠塞可能源於道路規劃不善和車輛太多。"},{"en":"When a problem results from human action, people may also be able to reduce it.","zh":"當問題源於人類行動，人們也可能有能力減少它。"},{"en":"The phrase links an effect to its cause.","zh":"這個短語把結果與原因連接起來。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":16},{"front":"changes humans have made","meaning":"人類造成的改變","examples":[{"en":"The problem results from changes humans have made to the Earth.","zh":"這個問題源於人類對地球造成的改變。"},{"en":"Changes humans have made are alterations caused by human activity, such as farming, building, or clearing land.","zh":"changes humans have made 是由人類活動造成的改變，例如農業、建築或清理土地。"},{"en":"Roads and housing estates are changes humans have made to natural landscapes.","zh":"道路和屋苑是人類對自然景觀造成的改變。"},{"en":"Such changes can unintentionally create new competition among animals.","zh":"這些改變可能無意中在動物之間創造新競爭。"},{"en":"The phrase focuses responsibility on human actions.","zh":"這個短語把責任聚焦於人類行動。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":16},{"front":"widespread and dangerous competitors","meaning":"分布最廣且最危險的競爭者","examples":[{"en":"Humans are the most widespread and dangerous competitors parrots have faced.","zh":"人類是鸚鵡曾經面對過分布最廣且最危險的競爭者。"},{"en":"Widespread and dangerous competitors are rivals found in many places and able to cause serious harm.","zh":"widespread and dangerous competitors 是出現在許多地方並能造成嚴重傷害的競爭者。"},{"en":"An invasive plant can become a widespread and dangerous competitor for native flowers.","zh":"入侵植物可以成為本土花卉分布廣泛且危險的競爭者。"},{"en":"Humans compete with wildlife by changing land, taking resources, and destroying habitats.","zh":"人類透過改變土地、奪取資源和破壞棲息地與野生動物競爭。"},{"en":"The phrase describes competitors that are both common and harmful.","zh":"這個短語描述既常見又有害的競爭者。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":16},{"front":"have ever faced","meaning":"曾經面對過","examples":[{"en":"Humans are the most dangerous competitors parrots have ever faced.","zh":"人類是鸚鵡曾經面對過最危險的競爭者。"},{"en":"Have ever faced means have experienced at any time up to now.","zh":"have ever faced 指直到現在為止任何時候曾經經歷過。"},{"en":"A school may say a flood is the worst crisis it has ever faced.","zh":"學校可能說洪水是它曾經面對過最嚴重的危機。"},{"en":"The phrase emphasises that something is extreme compared with all previous experience.","zh":"這個短語強調某事相比所有過往經驗都極端。"},{"en":"It is used to show seriousness over a long period.","zh":"它用來顯示長時間尺度下的嚴重性。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":16},{"front":"have the knowledge and skill to","meaning":"有知識和能力去","examples":[{"en":"Humans have the knowledge and skill to protect parrot diversity.","zh":"人類有知識和能力去保護鸚鵡多樣性。"},{"en":"To have the knowledge and skill to do something means to know how to do it and be able to do it well.","zh":"have the knowledge and skill to do something 指知道如何做，並有能力做好。"},{"en":"A trained nurse has the knowledge and skill to care for patients safely.","zh":"受過訓練的護士有知識和能力安全照顧病人。"},{"en":"Knowledge alone is not enough if people lack the practical skill to act.","zh":"如果人們缺乏實際行動能力，單有知識並不足夠。"},{"en":"The phrase describes both understanding and ability.","zh":"這個短語同時描述理解和能力。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":16},{"front":"maintain diversity","meaning":"維持多樣性","examples":[{"en":"People can help maintain Australia’s rich diversity of parrots.","zh":"人們可以幫助維持澳洲豐富的鸚鵡多樣性。"},{"en":"To maintain diversity means to keep many different types alive or present.","zh":"maintain diversity 指保留許多不同類型，使其繼續存在。"},{"en":"A school can maintain diversity by welcoming students from different backgrounds.","zh":"學校可以透過歡迎不同背景的學生來維持多樣性。"},{"en":"In nature, maintaining diversity protects ecosystems from becoming too simple and fragile.","zh":"在自然界，維持多樣性可以防止生態系統變得過於簡單和脆弱。"},{"en":"The phrase describes preserving variety over time.","zh":"這個短語描述隨時間保存多樣性。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":16},{"front":"wonderfully rich diversity","meaning":"非常豐富的多樣性","examples":[{"en":"Australia has a wonderfully rich diversity of parrots.","zh":"澳洲有非常豐富的鸚鵡多樣性。"},{"en":"Wonderfully rich diversity means an impressive and beautiful variety of many different kinds.","zh":"wonderfully rich diversity 指令人印象深刻而美麗的多種類型。"},{"en":"A city market may show wonderfully rich diversity through foods from many cultures.","zh":"城市街市可能透過多種文化的食物展現非常豐富的多樣性。"},{"en":"Such diversity is valuable because it gives a place character and resilience.","zh":"這種多樣性很有價值，因為它賦予地方特色和韌性。"},{"en":"The phrase expresses strong admiration for variety.","zh":"這個短語表達對多樣性的強烈欣賞。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":16},{"front":"the will to do so","meaning":"這樣做的意願","examples":[{"en":"All people need is the will to protect parrot diversity.","zh":"人們所需要的只是保護鸚鵡多樣性的意願。"},{"en":"The will to do so means the determination or willingness to take action.","zh":"the will to do so 指採取行動的決心或意願。"},{"en":"A community may have the money to clean a beach but still need the will to do so.","zh":"社區可能有清潔海灘的金錢，但仍需要這樣做的意願。"},{"en":"Knowledge and skill matter less if people lack the will to act.","zh":"如果人們缺乏行動意願，知識和能力的重要性就會減少。"},{"en":"The phrase describes motivation to carry out a known action.","zh":"這個短語描述實行已知行動的動機。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":17},{"front":"which paragraph contains","meaning":"哪一段包含","examples":[{"en":"The task asks which paragraph contains specific information.","zh":"題目問哪一段包含特定資料。"},{"en":"Which paragraph contains means students must identify the paragraph where certain information appears.","zh":"which paragraph contains 指學生必須找出某些資料出現在哪一段。"},{"en":"In a reading test, students may ask which paragraph contains an example of animal adaptation.","zh":"在閱讀測驗中，學生可能要判斷哪一段包含動物適應的例子。"},{"en":"This question type tests scanning and understanding of paragraph content.","zh":"這種題型測試掃讀和理解段落內容的能力。"},{"en":"The phrase is common in IELTS matching-information tasks.","zh":"這個短語常見於 IELTS 資料配對題。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":17},{"front":"following information","meaning":"以下資料","examples":[{"en":"Candidates match the paragraphs with the following information.","zh":"考生把段落與以下資料配對。"},{"en":"Following information means the information listed after the instruction.","zh":"following information 指指示之後列出的資料。"},{"en":"Students should read the following information carefully before looking for paragraph matches.","zh":"學生在尋找段落配對前，應仔細閱讀以下資料。"},{"en":"Misreading the listed information can lead to choosing the wrong paragraph.","zh":"誤讀列出的資料可能導致選錯段落。"},{"en":"The phrase points forward to details that come next.","zh":"這個短語指向接下來的細節。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":17},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Candidates write the correct letter on the answer sheet.","zh":"考生在答題紙上寫上正確字母。"},{"en":"To write the correct letter means to record the option letter that matches the answer.","zh":"write the correct letter 指記下與答案相符的選項字母。"},{"en":"If paragraph C contains the answer, students should write C clearly.","zh":"如果C段包含答案，學生應清楚寫上C。"},{"en":"A correct idea can lose marks if the wrong letter is written.","zh":"即使想法正確，寫錯字母也可能失分。"},{"en":"The phrase describes the required answer format in many tests.","zh":"這個短語描述許多測驗中的指定作答格式。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":17},{"front":"an example of","meaning":"……的一個例子","examples":[{"en":"The question asks for an example of one parrot species surviving at another’s expense.","zh":"題目要求找出一個鸚鵡物種以犧牲另一物種為代價而生存的例子。"},{"en":"An example of something is a specific case that shows the general idea.","zh":"an example of 某事，是展示一般概念的具體個案。"},{"en":"A teacher may ask for an example of teamwork from school life.","zh":"老師可能要求學生舉出學校生活中團隊合作的一個例子。"},{"en":"Examples help students understand abstract ideas through real situations.","zh":"例子幫助學生透過真實情況理解抽象概念。"},{"en":"The phrase introduces a concrete instance.","zh":"這個短語引出具體事例。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":17},{"front":"at the expense of","meaning":"以犧牲……為代價","examples":[{"en":"One species may survive at the expense of another.","zh":"一個物種可能以犧牲另一物種為代價而生存。"},{"en":"At the expense of something means by harming, reducing, or sacrificing it.","zh":"at the expense of 某物，指透過傷害、減少或犧牲它而達成。"},{"en":"A student should not improve exam results at the expense of sleep and health.","zh":"學生不應以犧牲睡眠和健康為代價來提高考試成績。"},{"en":"In nature, one species may benefit at the expense of another when resources are scarce.","zh":"在自然界，當資源稀缺，一個物種可能以犧牲另一物種為代價而受益。"},{"en":"The phrase describes gain that comes with a cost to someone or something else.","zh":"這個短語描述某種收穫伴隨他人或他物的代價。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":17},{"front":"adapt to attract birds","meaning":"適應以吸引鳥類","examples":[{"en":"Some plants adapt to attract birds for pollination.","zh":"有些植物適應以吸引鳥類授粉。"},{"en":"To adapt to attract birds means to develop features that make birds more likely to visit.","zh":"adapt to attract birds 指發展出令鳥類更可能到訪的特徵。"},{"en":"Flowers may adapt to attract birds by becoming red or producing more nectar.","zh":"花朵可能透過變成紅色或產生更多花蜜來適應以吸引鳥類。"},{"en":"Attracting birds can help plants transfer pollen and produce seeds.","zh":"吸引鳥類可以幫助植物轉移花粉並產生種子。"},{"en":"The phrase describes plant features shaped to appeal to birds.","zh":"這個短語描述為吸引鳥類而形成的植物特徵。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":17},{"front":"benefit from environmental change","meaning":"從環境變化中受益","examples":[{"en":"Some parrot species benefited from environmental change.","zh":"有些鸚鵡物種從環境變化中受益。"},{"en":"To benefit from environmental change means to gain an advantage when the habitat or landscape changes.","zh":"benefit from environmental change 指當棲息地或景觀改變時獲得優勢。"},{"en":"Some weeds benefit from environmental change when forests are cleared for open land.","zh":"當森林被清除成開闊土地，有些雜草會從環境變化中受益。"},{"en":"Not all environmental change is harmful to every species, although it may hurt others.","zh":"並非所有環境變化都對每個物種有害，雖然它可能傷害其他物種。"},{"en":"The phrase describes gaining from changed natural conditions.","zh":"這個短語描述從改變後自然條件中得到好處。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":17},{"front":"varied landscape","meaning":"多樣化地貌","examples":[{"en":"Australia’s varied landscape helped produce many parrot species.","zh":"澳洲的多樣化地貌有助產生許多鸚鵡物種。"},{"en":"A varied landscape contains many different types of land, such as forests, grasslands, deserts, and wetlands.","zh":"varied landscape 包含許多不同土地類型，例如森林、草原、沙漠和濕地。"},{"en":"A country with a varied landscape may support many kinds of animals.","zh":"擁有多樣化地貌的國家可能支持多種動物。"},{"en":"Landscape variety creates different habitats, so species can adapt in different ways.","zh":"地貌多樣性創造不同棲息地，使物種能以不同方式適應。"},{"en":"The phrase describes physical diversity across land.","zh":"這個短語描述土地上的自然形態多樣性。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":17},{"front":"produce a great variety of","meaning":"產生大量不同的……","examples":[{"en":"Habitat change helped produce a great variety of parrot species.","zh":"棲息地變化有助產生大量不同的鸚鵡物種。"},{"en":"To produce a great variety of something means to create or lead to many different kinds.","zh":"produce a great variety of 某物，指創造或導致許多不同種類。"},{"en":"A school with many clubs can produce a great variety of student talents.","zh":"有許多學會的學校可以培養出大量不同的學生才能。"},{"en":"Different environments can produce a great variety of adaptations.","zh":"不同環境可以產生大量不同的適應特徵。"},{"en":"The phrase describes creating many types rather than just many individuals.","zh":"這個短語描述產生許多種類，而不只是許多個體。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":17},{"front":"be native to","meaning":"原產於","examples":[{"en":"Many parrot species are native to the Southern Hemisphere.","zh":"許多鸚鵡物種原產於南半球。"},{"en":"To be native to a place means to occur there naturally, not only because humans introduced it.","zh":"be native to 某地，指自然出現在那裏，而不只是由人類引入。"},{"en":"Pandas are native to parts of China.","zh":"熊貓原產於中國部分地區。"},{"en":"Native species often fit local habitats because they have evolved there over time.","zh":"本土物種常適合本地棲息地，因為牠們隨時間在那裏演化。"},{"en":"The phrase identifies the natural home of a species.","zh":"這個短語指出物種的自然家園。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":18},{"front":"did not survive changes to","meaning":"未能在……變化中存活","examples":[{"en":"Some parrots did not survive changes to their habitat.","zh":"有些鸚鵡未能在其棲息地變化中存活。"},{"en":"Did not survive changes to something means failed to remain alive or present after it changed.","zh":"did not survive changes to 某事，指在它改變後未能繼續存活或存在。"},{"en":"A small shop may not survive changes to rent and customer habits.","zh":"小店可能未能在租金和顧客習慣變化中存活。"},{"en":"Species may not survive habitat changes if they need very specific food or nesting places.","zh":"如果物種需要非常特定的食物或築巢地點，牠們可能未能在棲息地變化中存活。"},{"en":"The phrase describes failure to cope with change.","zh":"這個短語描述未能應對變化。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":18},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Candidates choose the correct letter for each question.","zh":"考生為每題選出正確字母。"},{"en":"To choose the correct letter means to select the option letter that matches the answer.","zh":"choose the correct letter 指選出與答案相符的選項字母。"},{"en":"In multiple-choice questions, students must choose the correct letter, not write a full sentence.","zh":"在選擇題中，學生必須選出正確字母，而不是寫完整句子。"},{"en":"Reading the instruction carefully prevents choosing too many letters.","zh":"仔細閱讀指示可避免選太多字母。"},{"en":"The phrase describes a common exam-answer action.","zh":"這個短語描述常見的考試作答動作。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":18},{"front":"the writer believes that","meaning":"作者認為","examples":[{"en":"The question asks what the writer believes about parrot origins.","zh":"題目問作者對鸚鵡起源有何看法。"},{"en":"The writer believes that introduces the author’s opinion or conclusion.","zh":"the writer believes that 引出作者的意見或結論。"},{"en":"In a reading test, students must separate what the writer believes from what other people think.","zh":"在閱讀測驗中，學生必須分辨作者認為甚麼和其他人認為甚麼。"},{"en":"The phrase points to viewpoint, not just factual detail.","zh":"這個短語指向觀點，而不只是事實細節。"},{"en":"It asks readers to understand the author’s position.","zh":"它要求讀者理解作者立場。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":18},{"front":"most parrot species","meaning":"大多數鸚鵡物種","examples":[{"en":"The question discusses the origins of most parrot species.","zh":"題目討論大多數鸚鵡物種的起源。"},{"en":"Most parrot species means the majority of different kinds of parrots.","zh":"most parrot species 指不同種類鸚鵡中的大多數。"},{"en":"Most parrot species need trees or other safe places for nesting.","zh":"大多數鸚鵡物種需要樹木或其他安全地方築巢。"},{"en":"Saying “most” allows for exceptions, so not every species must fit the statement.","zh":"說 “most” 容許例外，因此不是每個物種都必須符合陳述。"},{"en":"The phrase describes the larger part of all parrot types.","zh":"這個短語描述所有鸚鵡種類中的較大部分。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":18},{"front":"have ancestors in","meaning":"在……有祖先","examples":[{"en":"Modern parrots may have ancestors in an ancient southern continent.","zh":"現代鸚鵡可能在一個古老南方大陸有祖先。"},{"en":"To have ancestors in a place means earlier members of a group lived there in the past.","zh":"have ancestors in 某地，指某群體較早期成員過去住在那裏。"},{"en":"A family may have ancestors in a village even if its members now live in a city.","zh":"一個家庭即使現在住在城市，也可能在村落有祖先。"},{"en":"Species origins can be traced by asking where their ancestors lived.","zh":"物種起源可透過追問其祖先生活在哪裏來追溯。"},{"en":"The phrase connects present groups with earlier history.","zh":"這個短語把現存群體與早期歷史連接起來。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":18},{"front":"later split apart","meaning":"後來分裂","examples":[{"en":"The continent later split apart into separate landmasses.","zh":"該大陸後來分裂成不同陸塊。"},{"en":"Later split apart means separated into pieces after an earlier period of being joined.","zh":"later split apart 指在早期連在一起之後，後來分開成多部分。"},{"en":"A large study group may later split apart into smaller project teams.","zh":"大型學習小組可能後來分裂成較小項目小隊。"},{"en":"When landmasses split apart, populations can become isolated.","zh":"當陸塊後來分裂，種群可能被隔離。"},{"en":"The phrase describes separation happening at a later time.","zh":"這個短語描述較後時間發生的分離。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":18},{"front":"be covered by water","meaning":"被水覆蓋","examples":[{"en":"The option refers to a continent now covered by water.","zh":"該選項指一個現在被水覆蓋的大陸。"},{"en":"To be covered by water means to have water over the surface.","zh":"be covered by water 指表面有水覆蓋。"},{"en":"Low streets may be covered by water after heavy rain.","zh":"暴雨後，低窪街道可能被水覆蓋。"},{"en":"If land is covered by water permanently, plants and animals living on land cannot remain there.","zh":"如果土地永久被水覆蓋，陸地植物和動物就不能留在那裏。"},{"en":"The phrase describes water lying over an area.","zh":"這個短語描述水覆蓋某區域。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":18},{"front":"what does the writer say about","meaning":"作者對……有何說法","examples":[{"en":"The question asks what the writer says about parrots’ beaks.","zh":"題目問作者對鸚鵡鳥喙有何說法。"},{"en":"What does the writer say about something asks readers to identify the author’s statement on that topic.","zh":"what does the writer say about 某事，要求讀者找出作者對該主題的陳述。"},{"en":"A reading question may ask what the writer says about school meals.","zh":"閱讀題可能問作者對學校膳食有何說法。"},{"en":"Students should answer from the passage, not from outside knowledge.","zh":"學生應根據文章作答，而不是根據外部知識。"},{"en":"The phrase focuses on the writer’s information or opinion.","zh":"這個短語聚焦於作者的資訊或看法。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":18},{"front":"be made from","meaning":"由……製成","examples":[{"en":"Parrots’ beaks are made from keratin.","zh":"鸚鵡鳥喙由角蛋白製成。"},{"en":"To be made from something means to be formed using that material.","zh":"be made from 某物，指使用該材料形成。"},{"en":"Paper is made from plant fibres.","zh":"紙張由植物纖維製成。"},{"en":"Knowing what something is made from helps explain its strength, texture, or use.","zh":"知道某物由甚麼製成，有助解釋其強度、質地或用途。"},{"en":"The phrase identifies the material of an object.","zh":"這個短語指出物件的材料。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":18},{"front":"unique material","meaning":"獨特材料","examples":[{"en":"The option asks whether parrots’ beaks are made from a unique material.","zh":"該選項問鸚鵡鳥喙是否由獨特材料製成。"},{"en":"Unique material means a material that is special and not shared with others.","zh":"unique material 指特殊且不與其他事物共享的材料。"},{"en":"A phone case made from a unique material may feel different from ordinary plastic.","zh":"由獨特材料製成的手機殼可能與普通塑膠手感不同。"},{"en":"In exam options, “unique” is often too strong if the passage only says what something is made from.","zh":"在考試選項中，如果文章只說某物由甚麼製成，“unique” 常太強。"},{"en":"The phrase describes a material unlike others.","zh":"這個短語描述與其他材料不同的材料。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":19},{"front":"be used efficiently","meaning":"被有效使用","examples":[{"en":"The option asks whether parrots’ beaks are used more efficiently than other birds’ beaks.","zh":"該選項問鸚鵡鳥喙是否比其他鳥類鳥喙被更有效使用。"},{"en":"To be used efficiently means to be used in a way that wastes little effort or resource.","zh":"be used efficiently 指以少浪費努力或資源的方式使用。"},{"en":"A library room is used efficiently when many students can study there without crowding.","zh":"當許多學生能在圖書館房間自修而不擠迫，該房間就是被有效使用。"},{"en":"Efficient use depends on purpose, design, and conditions.","zh":"有效使用取決於目的、設計和條件。"},{"en":"The phrase describes effective use with little waste.","zh":"這個短語描述低浪費而有效的使用。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":19},{"front":"be specially adapted to","meaning":"特別適應以配合","examples":[{"en":"Parrots’ beaks are specially adapted to suit their diets.","zh":"鸚鵡鳥喙特別適應以配合牠們的飲食。"},{"en":"To be specially adapted to something means to have features shaped for that particular need or condition.","zh":"be specially adapted to 某事，指具有為特定需要或環境塑造的特徵。"},{"en":"A desert plant is specially adapted to store water.","zh":"沙漠植物特別適應以儲存水分。"},{"en":"Special adaptation helps living things use food or habitats that others cannot use easily.","zh":"特殊適應幫助生物利用其他生物不易利用的食物或棲息地。"},{"en":"The phrase describes a close match between feature and function.","zh":"這個短語描述特徵與功能之間的緊密配合。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":19},{"front":"suit the birds’ diets","meaning":"配合鳥類的飲食","examples":[{"en":"Different beaks suit the birds’ different diets.","zh":"不同鳥喙配合鳥類不同飲食。"},{"en":"To suit the birds’ diets means to match what the birds eat.","zh":"suit the birds’ diets 指配合鳥類所吃的食物。"},{"en":"A long beak may suit a bird’s diet if it feeds inside deep flowers.","zh":"如果鳥類在深花中取食，長鳥喙可能配合其飲食。"},{"en":"Body parts that suit a diet make feeding easier and more efficient.","zh":"配合飲食的身體部位令覓食更容易、更有效。"},{"en":"The phrase describes a fit between feeding tools and food.","zh":"這個短語描述進食工具與食物之間的配合。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":19},{"front":"be mentioned as","meaning":"被提及為","examples":[{"en":"The question asks which disadvantage is not mentioned as a problem.","zh":"題目問哪一個缺點沒有被提及為問題。"},{"en":"To be mentioned as something means to be stated or referred to in that role.","zh":"be mentioned as 某物，指被陳述或提及為該角色。"},{"en":"A report may mention noise as a reason people dislike the new road.","zh":"報告可能把噪音提及為人們不喜歡新道路的原因。"},{"en":"In reading tests, students must check whether an idea is actually mentioned as evidence.","zh":"在閱讀測驗中，學生必須檢查某想法是否真正被提及為證據。"},{"en":"The phrase asks whether the text directly refers to something.","zh":"這個短語問文本是否直接提到某事。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":19},{"front":"disadvantage of","meaning":"……的缺點","examples":[{"en":"The question focuses on the disadvantages of nesting boxes.","zh":"題目聚焦於人工巢箱的缺點。"},{"en":"A disadvantage of something is a weakness, problem, or negative effect it has.","zh":"disadvantage of 某事，是它具有的弱點、問題或負面影響。"},{"en":"A disadvantage of online lessons is that some students cannot focus at home.","zh":"網上課堂的一個缺點是有些學生在家無法專心。"},{"en":"Identifying disadvantages helps people judge whether a solution is complete.","zh":"找出缺點幫助人判斷某方案是否完整。"},{"en":"The phrase introduces the negative side of something.","zh":"這個短語引出某事的負面一面。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":19},{"front":"nesting boxes","meaning":"人工巢箱","examples":[{"en":"Nesting boxes may help parrots but cannot replace old trees.","zh":"人工巢箱可能幫助鸚鵡，但不能取代老樹。"},{"en":"Nesting boxes are artificial containers placed for birds to nest in.","zh":"nesting boxes 是放置給鳥類築巢的人造容器。"},{"en":"A park may install nesting boxes to help birds that cannot find tree holes.","zh":"公園可能安裝人工巢箱，幫助找不到樹洞的鳥類。"},{"en":"Nesting boxes provide shelter, but they do not provide food like flowers or seeds.","zh":"人工巢箱提供庇護，但不提供像花朵或種子那樣的食物。"},{"en":"The phrase describes man-made nest spaces for wildlife.","zh":"這個短語描述給野生動物使用的人造築巢空間。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":19},{"front":"need to be maintained","meaning":"需要維修保養","examples":[{"en":"The option asks whether nesting boxes need to be maintained.","zh":"該選項問人工巢箱是否需要維修保養。"},{"en":"To need to be maintained means to require regular checking, repair, or care.","zh":"need to be maintained 指需要定期檢查、維修或照顧。"},{"en":"School computers need to be maintained so they do not fail during lessons.","zh":"學校電腦需要維修保養，才不會在上課期間故障。"},{"en":"Artificial wildlife structures may become unsafe if nobody maintains them.","zh":"如果無人保養，人工野生動物設施可能變得不安全。"},{"en":"The phrase describes the need for continuing care.","zh":"這個短語描述持續照顧的需要。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":19},{"front":"provide shelter but not food","meaning":"提供庇護但不提供食物","examples":[{"en":"Nesting boxes provide shelter but not food such as nectar or seeds.","zh":"人工巢箱提供庇護，但不提供花蜜或種子等食物。"},{"en":"To provide shelter but not food means to give a safe place to stay without supplying nourishment.","zh":"provide shelter but not food 指提供安全停留地方，但不供應營養。"},{"en":"A bus stop provides shelter from rain but not food for waiting passengers.","zh":"巴士站為等車乘客提供避雨庇護，但不提供食物。"},{"en":"For animals, shelter alone may not be enough if nearby food sources are gone.","zh":"對動物來說，如果附近食物來源消失，單有庇護可能不足夠。"},{"en":"The phrase shows a partial solution with an important limitation.","zh":"這個短語顯示一個有重要限制的部分解決方案。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":19},{"front":"complete the summary below","meaning":"完成以下摘要","examples":[{"en":"Candidates complete the summary below using words from the passage.","zh":"考生使用文章中的字詞完成以下摘要。"},{"en":"To complete the summary below means to fill gaps in a short overview placed after the instruction.","zh":"complete the summary below 指填補指示後短摘要中的空格。"},{"en":"Students should read the whole summary first so they understand the meaning before filling blanks.","zh":"學生應先讀完整個摘要，理解意思後再填空。"},{"en":"Summary completion tests both locating information and fitting words grammatically.","zh":"摘要填空同時測試定位資料和文法配合。"},{"en":"The phrase describes a common IELTS reading task.","zh":"這個短語描述常見 IELTS 閱讀題型。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":19},{"front":"no more than two words and/or a number","meaning":"不多於兩個字及／或一個數字","examples":[{"en":"Candidates choose no more than two words and/or a number from the passage.","zh":"考生從文章中選擇不多於兩個字及／或一個數字。"},{"en":"No more than two words and/or a number means the answer may contain up to two words, plus a number if needed.","zh":"no more than two words and/or a number 指答案可包含最多兩個詞，並在需要時加一個數字。"},{"en":"“sixteenth century” uses two words, while “one-sixth” is a number-like answer.","zh":"“sixteenth century” 有兩個詞，而 “one-sixth” 屬於類似數字的答案。"},{"en":"Students must obey the word limit even when a longer phrase seems clearer.","zh":"即使較長短語看似更清楚，學生仍必須遵守字數限制。"},{"en":"The phrase gives a strict answer-length rule.","zh":"這個短語給出嚴格的答案長度規則。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":20},{"front":"in existence","meaning":"現存","examples":[{"en":"The summary refers to the number of parrot species in existence.","zh":"摘要提到現存鸚鵡物種的數量。"},{"en":"In existence means currently existing or present in the world.","zh":"in existence 指目前在世界上存在的。"},{"en":"Some languages in existence today may disappear within a century.","zh":"今天現存的某些語言可能在一個世紀內消失。"},{"en":"Counting what is in existence helps scientists measure biodiversity.","zh":"點算現存事物幫助科學家衡量生物多樣性。"},{"en":"The phrase describes things that still exist now.","zh":"這個短語描述現在仍然存在的事物。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":20},{"front":"as early as","meaning":"早在……","examples":[{"en":"As early as the sixteenth century, parrots were linked with Australia.","zh":"早在16世紀，鸚鵡已與澳洲聯繫起來。"},{"en":"As early as means already at that surprisingly early time.","zh":"as early as 指早在那個令人意外的早期時間已經如此。"},{"en":"As early as primary school, some children show strong interest in science.","zh":"早在小學階段，有些孩子已展現對科學的強烈興趣。"},{"en":"The phrase emphasises that something happened earlier than readers might expect.","zh":"這個短語強調某事發生得比讀者可能預期更早。"},{"en":"It is useful when highlighting early evidence or recognition.","zh":"它在突出早期證據或認知時很有用。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":20},{"front":"mapmaker","meaning":"地圖製作家","examples":[{"en":"The mapmaker Mercator recognised the association between parrots and Australia.","zh":"地圖製作家 Mercator 意識到鸚鵡與澳洲之間的聯繫。"},{"en":"A mapmaker is a person who creates maps.","zh":"mapmaker 是製作地圖的人。"},{"en":"A mapmaker must decide which names, borders, and landmarks to include.","zh":"地圖製作家必須決定包括哪些名稱、邊界和地標。"},{"en":"Early mapmakers sometimes recorded what explorers believed about distant lands.","zh":"早期地圖製作家有時記錄探險者對遙遠土地的看法。"},{"en":"The word is a simple alternative to cartographer.","zh":"這個詞是 cartographer 的較簡單說法。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":20},{"front":"recognise that","meaning":"意識到；承認","examples":[{"en":"The mapmaker recognised that parrots lived in this part of the world.","zh":"這位地圖製作家意識到鸚鵡生活在世界這個地區。"},{"en":"To recognise that something is true means to realise, accept, or understand it.","zh":"recognise that 某事為真，指意識到、接受或理解它。"},{"en":"A teacher may recognise that a student is tired rather than lazy.","zh":"老師可能意識到學生是疲倦，而不是懶惰。"},{"en":"Recognition can change decisions because people understand the situation more accurately.","zh":"意識到某事可以改變決定，因為人們更準確理解情況。"},{"en":"The phrase introduces an understanding or acknowledgement.","zh":"這個短語引出理解或承認。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":20},{"front":"this part of the world","meaning":"世界這個地區","examples":[{"en":"Parrots were associated with this part of the world on early maps.","zh":"在早期地圖上，鸚鵡與世界這個地區有關。"},{"en":"This part of the world means this region or area of the Earth.","zh":"this part of the world 指地球上的這個區域或地區。"},{"en":"In this part of the world, summer can be hot and humid.","zh":"在世界這個地區，夏天可能炎熱潮濕。"},{"en":"Writers use the phrase when referring broadly to a region without naming every country.","zh":"作者在泛指某區域而不列出每個國家時會使用這個短語。"},{"en":"The phrase points to a general geographical area.","zh":"這個短語指向一個大致地理區域。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":20},{"front":"famous painter of animals and birds","meaning":"著名動物及鳥類畫家","examples":[{"en":"John Gould was a famous painter of animals and birds.","zh":"John Gould 是著名動物及鳥類畫家。"},{"en":"A famous painter of animals and birds is an artist known for drawing or painting wildlife.","zh":"famous painter of animals and birds 指以繪畫野生動物而聞名的藝術家。"},{"en":"Before photography was common, such painters helped people see distant species clearly.","zh":"在攝影普及前，這類畫家幫助人們清楚看見遙遠物種。"},{"en":"Accurate animal paintings could support science as well as art.","zh":"準確的動物畫既可以支持科學，也可以屬於藝術。"},{"en":"The phrase describes a well-known wildlife artist.","zh":"這個短語描述一位著名野生動物畫家。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":20},{"front":"comment on","meaning":"評論……","examples":[{"en":"John Gould commented on the number and beauty of Australian parrots.","zh":"John Gould 評論了澳洲鸚鵡的數量和美態。"},{"en":"To comment on something means to express an opinion or observation about it.","zh":"comment on 某事，指對它表達意見或觀察。"},{"en":"A teacher may comment on a student’s essay structure before correcting grammar.","zh":"老師可能先評論學生文章結構，再改正文法。"},{"en":"Comments can draw attention to what is important, unusual, or impressive.","zh":"評論可以把注意力引向重要、異常或令人印象深刻的地方。"},{"en":"The phrase describes making a remark about a topic.","zh":"這個短語描述就某主題作出評語。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":20},{"front":"number and beauty","meaning":"數量和美態","examples":[{"en":"Gould commented on the number and beauty of Australian parrots.","zh":"Gould 評論了澳洲鸚鵡的數量和美態。"},{"en":"Number and beauty means both how many there are and how attractive they are.","zh":"number and beauty 指既有多少數量，也有多吸引人的外觀。"},{"en":"Visitors may admire the number and beauty of flowers in a public garden.","zh":"訪客可能欣賞公共花園中花朵的數量和美態。"},{"en":"A place becomes memorable when it has both many examples and striking appearance.","zh":"當一個地方既有大量例子又有醒目外觀，它就會令人難忘。"},{"en":"The phrase combines quantity with visual appeal.","zh":"這個短語結合數量與視覺吸引力。"}],"source":"Passage 2 Flash Cards 170 - Australian parrots and their adaptation to habitat change.pdf","sourcePage":20}],"ielts/reading/passage-2/Practice 171":[{"front":"Coffee Then and Now","meaning":"咖啡的過去與現在","examples":[{"en":"Coffee Then and Now describes coffee from its discovery to modern production.","zh":"《咖啡的過去與現在》描述咖啡從發現到現代生產的歷史。"},{"en":"The passage Coffee Then and Now explains how coffee spread across the world.","zh":"《咖啡的過去與現在》解釋咖啡如何傳播到世界各地。"},{"en":"Coffee Then and Now also describes how coffee beans are processed.","zh":"《咖啡的過去與現在》也描述咖啡豆如何被加工。"},{"en":"The title Coffee Then and Now contrasts coffee’s history with its present production.","zh":"這個標題把咖啡的歷史與現在的生產作對比。"},{"en":"Coffee Then and Now is a suitable title for a passage about coffee’s development.","zh":"《咖啡的過去與現在》適合作為關於咖啡發展的文章標題。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":1},{"front":"a history of coffee","meaning":"咖啡歷史","examples":[{"en":"The passage presents a history of coffee and explains how it is produced.","zh":"文章呈現咖啡歷史，並解釋它如何生產。"},{"en":"A history of coffee begins with its discovery in East Africa.","zh":"咖啡歷史始於它在東非被發現。"},{"en":"A history of coffee also includes its spread to Arabia and Europe.","zh":"咖啡歷史也包括它傳播到阿拉伯和歐洲。"},{"en":"The passage gives a history of coffee through legend, cultivation, and trade.","zh":"文章透過傳說、栽培和貿易講述咖啡歷史。"},{"en":"A history of coffee helps readers understand the drink’s modern importance.","zh":"咖啡歷史幫助讀者理解這種飲品在現代的重要性。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":1},{"front":"be first discovered in","meaning":"首次在……被發現","examples":[{"en":"Coffee was first discovered in East Africa.","zh":"咖啡首次在東非被發現。"},{"en":"The drink’s story begins when coffee was first discovered in Ethiopia.","zh":"這種飲品的故事始於咖啡首次在埃塞俄比亞被發現。"},{"en":"Many foods were first discovered in one region before spreading elsewhere.","zh":"很多食物都是首次在某一地區被發現，然後傳播到別處。"},{"en":"Coffee was first discovered in a place known today as Ethiopia.","zh":"咖啡首次在現今稱為埃塞俄比亞的地方被發現。"},{"en":"The phrase means to be found for the first time in a particular place.","zh":"這個詞組表示某物第一次在某地被找到。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":1},{"front":"East Africa","meaning":"東非","examples":[{"en":"Coffee was first discovered in East Africa.","zh":"咖啡首次在東非被發現。"},{"en":"East Africa is important in the early history of coffee.","zh":"東非在咖啡早期歷史中十分重要。"},{"en":"The legend of Kaldi is set in East Africa.","zh":"Kaldi 的傳說發生在東非。"},{"en":"Coffee later travelled from East Africa to the Arabian Peninsula.","zh":"咖啡後來從東非傳到阿拉伯半島。"},{"en":"The phrase identifies the eastern region of Africa.","zh":"這個詞組指出非洲東部地區。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":1},{"front":"an area now known as","meaning":"現稱為……的地區","examples":[{"en":"Coffee was discovered in an area now known as Ethiopia.","zh":"咖啡在現稱為埃塞俄比亞的地區被發現。"},{"en":"An area now known as Ethiopia was once the setting of the coffee legend.","zh":"現稱為埃塞俄比亞的地區曾是咖啡傳說的背景。"},{"en":"The phrase connects an old place with its modern name.","zh":"這個詞組把古代地點與現代名稱連繫起來。"},{"en":"Coffee began in an area now known as Ethiopia before spreading to Arabia.","zh":"咖啡起源於現稱為埃塞俄比亞的地區，然後傳到阿拉伯。"},{"en":"This wording is useful when historical names have changed.","zh":"當歷史地名有改變時，這種說法很有用。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":1},{"front":"Ethiopia","meaning":"埃塞俄比亞","examples":[{"en":"Coffee was first discovered in an area now known as Ethiopia.","zh":"咖啡首次在現稱為埃塞俄比亞的地區被發現。"},{"en":"Ethiopia is central to the legend of coffee’s discovery.","zh":"埃塞俄比亞是咖啡發現傳說的核心地點。"},{"en":"Coffee berries were later transported from Ethiopia to Arabia.","zh":"咖啡漿果後來從埃塞俄比亞被運到阿拉伯。"},{"en":"The history of coffee begins in Ethiopia.","zh":"咖啡歷史始於埃塞俄比亞。"},{"en":"The phrase identifies the modern country linked with coffee’s origin.","zh":"這個詞組指出與咖啡起源有關的現代國家。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":1},{"front":"a popular legend","meaning":"流行傳說","examples":[{"en":"A popular legend refers to a goat herder named Kaldi.","zh":"一個流行傳說提到一位名叫 Kaldi 的牧山羊人。"},{"en":"A popular legend explains how coffee was first discovered.","zh":"一個流行傳說解釋咖啡如何首次被發現。"},{"en":"The story of Kaldi is a popular legend rather than a scientific record.","zh":"Kaldi 的故事是流行傳說，而不是科學記錄。"},{"en":"A popular legend often spreads because it is memorable.","zh":"流行傳說通常因為容易記住而傳開。"},{"en":"The phrase means a well-known traditional story.","zh":"這個詞組表示廣為人知的傳統故事。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":1},{"front":"refer to","meaning":"提到；指的是","examples":[{"en":"A popular legend refers to a goat herder by the name of Kaldi.","zh":"一個流行傳說提到一位名叫 Kaldi 的牧山羊人。"},{"en":"The passage refers to Ethiopia as coffee’s place of discovery.","zh":"文章提到埃塞俄比亞是咖啡被發現的地方。"},{"en":"The diagram refers to different parts of the coffee bean.","zh":"圖表指的是咖啡豆的不同部分。"},{"en":"To refer to something means to mention or point to it.","zh":"refer to 表示提及或指向某事。"},{"en":"The phrase is often used when explaining a source or idea.","zh":"這個詞組常用於解釋來源或概念。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":1},{"front":"goat herder","meaning":"牧山羊人","examples":[{"en":"A goat herder observed his goats behaving unusually after eating berries.","zh":"一位牧山羊人觀察到他的山羊吃了漿果後行為異常。"},{"en":"The goat herder in the legend was called Kaldi.","zh":"傳說中的牧山羊人名叫 Kaldi。"},{"en":"A goat herder looks after goats.","zh":"牧山羊人照顧山羊。"},{"en":"The goat herder became curious about the berries.","zh":"這位牧山羊人對那些漿果感到好奇。"},{"en":"The phrase describes a person who tends goats.","zh":"這個詞組描述照料山羊的人。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":1},{"front":"by the name of","meaning":"名叫……","examples":[{"en":"The legend refers to a goat herder by the name of Kaldi.","zh":"傳說提到一位名叫 Kaldi 的牧山羊人。"},{"en":"A man by the name of Kaldi noticed the goats acting strangely.","zh":"一名叫 Kaldi 的男子注意到山羊行為奇怪。"},{"en":"The phrase introduces a person’s name.","zh":"這個詞組用來引入人的名字。"},{"en":"A goat herder by the name of Kaldi is central to the coffee legend.","zh":"一位名叫 Kaldi 的牧山羊人是咖啡傳說的核心。"},{"en":"It means “called” or “named.”","zh":"它的意思是「叫做」或「名為」。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":1},{"front":"observe someone doing something","meaning":"觀察到某人做某事","examples":[{"en":"Kaldi observed his goats acting unusually friskily.","zh":"Kaldi 觀察到他的山羊表現得異常活躍。"},{"en":"The goat herder observed the animals eating berries from a bush.","zh":"這位牧山羊人觀察到動物正在吃灌木上的漿果。"},{"en":"To observe someone doing something means to watch them while they are doing it.","zh":"observe someone doing something 表示觀看某人正在做某事。"},{"en":"Kaldi observed his goats becoming energetic after eating the fruit.","zh":"Kaldi 觀察到山羊吃了果實後變得精力充沛。"},{"en":"Observation led him to try the berries himself.","zh":"觀察使他親自嘗試那些漿果。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":1},{"front":"act unusually friskily","meaning":"表現得異常活躍","examples":[{"en":"The goats acted unusually friskily after eating berries.","zh":"山羊吃了漿果後表現得異常活躍。"},{"en":"To act unusually friskily means to behave with unexpected energy and liveliness.","zh":"act unusually friskily 表示行為出乎意料地精力充沛而活潑。"},{"en":"Kaldi noticed that his goats acted unusually friskily.","zh":"Kaldi 注意到他的山羊表現得異常活躍。"},{"en":"Their lively behaviour made him curious about the berries.","zh":"牠們活潑的行為令他對漿果感到好奇。"},{"en":"The phrase describes energetic and playful movement.","zh":"這個詞組描述充滿活力和玩樂感的動作。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":2},{"front":"berries from a bush","meaning":"灌木上的漿果","examples":[{"en":"The goats ate berries from a bush.","zh":"山羊吃了灌木上的漿果。"},{"en":"Kaldi wondered why berries from a bush made his goats lively.","zh":"Kaldi 想知道為甚麼灌木上的漿果令山羊活躍。"},{"en":"Coffee was first noticed because of berries from a bush.","zh":"咖啡最初是因灌木上的漿果而受到注意。"},{"en":"These berries later became known as coffee berries.","zh":"這些漿果後來被稱為咖啡漿果。"},{"en":"The phrase describes small fruit growing on a shrub.","zh":"這個詞組描述長在灌木上的小果實。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":2},{"front":"curious about","meaning":"對……感到好奇","examples":[{"en":"Kaldi was curious about this phenomenon.","zh":"Kaldi 對這個現象感到好奇。"},{"en":"He became curious about the effect of the berries.","zh":"他對漿果的效果感到好奇。"},{"en":"Readers may be curious about how coffee spread from Africa to Europe.","zh":"讀者可能對咖啡如何從非洲傳到歐洲感到好奇。"},{"en":"To be curious about something means to want to know more about it.","zh":"curious about 表示想知道更多。"},{"en":"Curiosity led Kaldi to try the fruit himself.","zh":"好奇心使 Kaldi 親自嘗試這種果實。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":2},{"front":"this phenomenon","meaning":"這個現象","examples":[{"en":"Kaldi tried the berries because he was curious about this phenomenon.","zh":"Kaldi 因對這個現象感到好奇而嘗試那些漿果。"},{"en":"This phenomenon was the goats’ unusual liveliness after eating berries.","zh":"這個現象是山羊吃漿果後異常活躍。"},{"en":"The goat herder wanted to understand this phenomenon.","zh":"這位牧山羊人想了解這個現象。"},{"en":"This phenomenon led to the discovery of coffee’s stimulating effect.","zh":"這個現象導致人們發現咖啡的提神效果。"},{"en":"The phrase refers to an observed event or situation.","zh":"這個詞組指被觀察到的事件或情況。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":2},{"front":"renewed energy","meaning":"恢復的活力；重新充沛的精力","examples":[{"en":"Kaldi found that the berries gave him renewed energy.","zh":"Kaldi 發現那些漿果給他重新充沛的精力。"},{"en":"Renewed energy means fresh strength or liveliness after tiredness.","zh":"renewed energy 表示疲倦後重新出現的力量或活力。"},{"en":"Coffee became valued because it seemed to give renewed energy.","zh":"咖啡因似乎能帶來恢復的活力而受到重視。"},{"en":"The goats’ behaviour suggested that the fruit produced renewed energy.","zh":"山羊的行為暗示這種果實能產生重新充沛的精力。"},{"en":"The phrase describes a return of physical or mental vigour.","zh":"這個詞組描述身心活力的恢復。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":2},{"front":"energy-laden fruit","meaning":"富含能量的果實","examples":[{"en":"News of this energy-laden fruit spread throughout the region.","zh":"這種富含能量的果實的消息傳遍該地區。"},{"en":"Energy-laden fruit means fruit believed to contain or provide energy.","zh":"energy-laden fruit 表示被認為含有或提供能量的果實。"},{"en":"Coffee berries became known as an energy-laden fruit.","zh":"咖啡漿果被視為富含能量的果實。"},{"en":"The goats’ lively behaviour made the fruit seem energy-laden.","zh":"山羊活躍的行為令這種果實看似富含能量。"},{"en":"The phrase describes fruit with a stimulating effect.","zh":"這個詞組描述具有提神效果的果實。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":2},{"front":"spread throughout","meaning":"傳遍……","examples":[{"en":"News of coffee quickly spread throughout the region.","zh":"咖啡的消息很快傳遍該地區。"},{"en":"The story of the energy-laden fruit spread throughout East Africa.","zh":"這種富含能量果實的故事傳遍東非。"},{"en":"Coffee later spread throughout Arabia and beyond.","zh":"咖啡後來傳遍阿拉伯及更遠地方。"},{"en":"To spread throughout a place means to become known or present across it.","zh":"spread throughout 表示在某地廣泛傳播或出現。"},{"en":"The phrase describes wide movement or circulation.","zh":"這個詞組描述廣泛流動或流傳。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":2},{"front":"the region","meaning":"該地區","examples":[{"en":"News of coffee berries quickly spread throughout the region.","zh":"咖啡漿果的消息很快傳遍該地區。"},{"en":"The region refers to the area where Kaldi lived.","zh":"the region 指 Kaldi 所居住的地區。"},{"en":"People in the region learned about the energy-laden fruit.","zh":"該地區的人們得知這種富含能量的果實。"},{"en":"Coffee later moved beyond the region to Arabia.","zh":"咖啡後來從該地區傳到阿拉伯。"},{"en":"The phrase identifies a particular area.","zh":"這個詞組指出特定區域。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":2},{"front":"coffee berries","meaning":"咖啡漿果","examples":[{"en":"Coffee berries were transported from Ethiopia to the Arabian Peninsula.","zh":"咖啡漿果從埃塞俄比亞被運到阿拉伯半島。"},{"en":"Coffee berries contain seeds that later become coffee beans.","zh":"咖啡漿果含有後來成為咖啡豆的種子。"},{"en":"The goats ate coffee berries from a bush.","zh":"山羊吃了灌木上的咖啡漿果。"},{"en":"Coffee berries look like red fruit before processing.","zh":"咖啡漿果在加工前看起來像紅色果實。"},{"en":"The phrase refers to the fruit of the coffee plant.","zh":"這個詞組指咖啡植物的果實。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":2},{"front":"be transported from…to…","meaning":"從……被運送到……","examples":[{"en":"Coffee berries were transported from Ethiopia to the Arabian Peninsula.","zh":"咖啡漿果從埃塞俄比亞被運送到阿拉伯半島。"},{"en":"Goods can be transported from one region to another by traders.","zh":"貨物可以由商人從一個地區被運送到另一地區。"},{"en":"Coffee was transported from Africa to Arabia before spreading further.","zh":"咖啡從非洲被運送到阿拉伯，然後進一步傳播。"},{"en":"The phrase describes movement between two places.","zh":"這個詞組描述兩地之間的移動。"},{"en":"It is often used for trade or travel routes.","zh":"它常用於貿易或旅行路線。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":2},{"front":"the Arabian Peninsula","meaning":"阿拉伯半島","examples":[{"en":"Coffee berries were transported to the Arabian Peninsula.","zh":"咖啡漿果被運到阿拉伯半島。"},{"en":"The Arabian Peninsula became important in coffee cultivation.","zh":"阿拉伯半島在咖啡栽培中變得重要。"},{"en":"Coffee was first cultivated in what is now Yemen on the Arabian Peninsula.","zh":"咖啡首次在阿拉伯半島上現今的也門被栽培。"},{"en":"The drink later spread from Arabia to Turkey and Europe.","zh":"這種飲品後來從阿拉伯傳到土耳其和歐洲。"},{"en":"The phrase identifies a region in southwest Asia.","zh":"這個詞組指出西南亞的一個地區。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":2},{"front":"be first cultivated in","meaning":"首次在……被栽培","examples":[{"en":"Coffee was first cultivated in what is now Yemen.","zh":"咖啡首次在現今的也門被栽培。"},{"en":"To be first cultivated in a place means to be first grown there intentionally.","zh":"be first cultivated in 表示首次在某地被有意種植。"},{"en":"Coffee was discovered in Ethiopia but first cultivated in Arabia.","zh":"咖啡在埃塞俄比亞被發現，但首次在阿拉伯被栽培。"},{"en":"The phrase distinguishes discovery from farming.","zh":"這個詞組區分發現與農業種植。"},{"en":"It describes the beginning of organised crop production.","zh":"它描述有組織作物生產的開始。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":3},{"front":"what is now","meaning":"現今的……","examples":[{"en":"Coffee was first cultivated in what is now Yemen.","zh":"咖啡首次在現今的也門被栽培。"},{"en":"What is now Yemen was once part of early coffee history.","zh":"現今的也門曾是早期咖啡歷史的一部分。"},{"en":"The phrase uses a modern place name for a historical location.","zh":"這個詞組用現代地名指歷史地點。"},{"en":"Coffee farming began in what is now a recognised coffee region.","zh":"咖啡種植始於現今被認可的一個咖啡地區。"},{"en":"It means “the place currently called.”","zh":"它表示「現在稱為……的地方」。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":3},{"front":"remain a secret","meaning":"一直是秘密","examples":[{"en":"Coffee remained a secret in Arabia before spreading elsewhere.","zh":"咖啡在傳播到其他地方之前，在阿拉伯一直是秘密。"},{"en":"For a time, coffee production remained a secret.","zh":"有一段時間，咖啡生產一直是秘密。"},{"en":"Traders may have wanted coffee to remain a secret.","zh":"商人可能希望咖啡一直是秘密。"},{"en":"To remain a secret means to stay unknown to outsiders.","zh":"remain a secret 表示對外人保持未知。"},{"en":"The phrase shows that knowledge was controlled for a period.","zh":"這個詞組顯示知識曾被控制一段時間。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":3},{"front":"spreading to","meaning":"傳播到","examples":[{"en":"Coffee spread to Turkey and then to Europe.","zh":"咖啡傳播到土耳其，然後到歐洲。"},{"en":"The drink continued spreading to new regions.","zh":"這種飲品繼續傳播到新地區。"},{"en":"Spreading to Europe changed coffee’s global history.","zh":"傳播到歐洲改變了咖啡的全球歷史。"},{"en":"The phrase describes movement from one place to another.","zh":"這個詞組描述從一地到另一地的移動。"},{"en":"It is often used for ideas, products, or plants.","zh":"它常用於思想、產品或植物。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":3},{"front":"the European continent","meaning":"歐洲大陸","examples":[{"en":"Coffee eventually spread to the European continent.","zh":"咖啡最終傳播到歐洲大陸。"},{"en":"Venetian merchants helped coffee reach the European continent.","zh":"威尼斯商人幫助咖啡到達歐洲大陸。"},{"en":"Coffeehouses later opened across the European continent.","zh":"咖啡館後來在歐洲大陸各地開設。"},{"en":"The phrase refers to mainland Europe.","zh":"這個詞組指歐洲本土。"},{"en":"It helps describe coffee’s spread beyond Arabia and Turkey.","zh":"它幫助描述咖啡從阿拉伯和土耳其向外傳播。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":3},{"front":"via Venetian merchants","meaning":"透過威尼斯商人","examples":[{"en":"Coffee reached Europe via Venetian merchants.","zh":"咖啡透過威尼斯商人到達歐洲。"},{"en":"Via Venetian merchants means through traders from Venice.","zh":"via Venetian merchants 表示經由來自威尼斯的商人。"},{"en":"Venetian merchants played a role in bringing coffee to Europe.","zh":"威尼斯商人在把咖啡帶到歐洲方面發揮作用。"},{"en":"Goods often entered Europe via important trading cities.","zh":"貨物常透過重要貿易城市進入歐洲。"},{"en":"The phrase identifies the route or agents of transmission.","zh":"這個詞組指出傳播路線或媒介。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":3},{"front":"be first eaten as food","meaning":"最初被當作食物食用","examples":[{"en":"Coffee was first eaten as food.","zh":"咖啡最初被當作食物食用。"},{"en":"Before it became a drink, coffee may have been eaten as food.","zh":"在成為飲品之前，咖啡可能被當作食物食用。"},{"en":"People later learned to make coffee into a beverage.","zh":"人們後來學會把咖啡製成飲品。"},{"en":"The phrase shows that coffee was not originally consumed as today’s drink.","zh":"這個詞組顯示咖啡最初並不是以今天的飲品形式被消費。"},{"en":"It describes the earliest form of consumption.","zh":"它描述最早的食用方式。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":3},{"front":"make a drink by","meaning":"透過……製成飲品","examples":[{"en":"People in Arabia later made a drink by boiling the beans.","zh":"阿拉伯人後來透過煮咖啡豆製成飲品。"},{"en":"They made a drink by crushing and boiling roasted beans.","zh":"他們透過壓碎和煮烘焙豆製成飲品。"},{"en":"To make a drink by doing something means to produce a beverage through that process.","zh":"make a drink by doing something 表示透過某過程製作飲品。"},{"en":"Coffee drinkers later refined the method.","zh":"咖啡飲用者後來改良了這種方法。"},{"en":"The phrase introduces the method of preparation.","zh":"這個詞組引入製作方法。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":3},{"front":"boiling the beans","meaning":"煮咖啡豆","examples":[{"en":"People made a drink by boiling the coffee beans.","zh":"人們透過煮咖啡豆製成飲品。"},{"en":"Boiling the beans was an early way of preparing coffee.","zh":"煮咖啡豆是早期準備咖啡的方法。"},{"en":"The beans were crushed before being boiled in water.","zh":"咖啡豆在水中煮沸前先被壓碎。"},{"en":"Boiling the beans created a crude version of modern coffee.","zh":"煮咖啡豆製成了現代咖啡的原始版本。"},{"en":"The phrase describes cooking coffee beans in hot water.","zh":"這個詞組描述把咖啡豆放在熱水中烹煮。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":3},{"front":"narcotic effects","meaning":"麻醉作用；致醉作用","examples":[{"en":"People boiled coffee beans for their narcotic effects.","zh":"人們煮咖啡豆是為了它們的麻醉作用。"},{"en":"Narcotic effects refer to mind-altering or stimulating effects in this context.","zh":"narcotic effects 在此指影響精神或刺激身體的作用。"},{"en":"Early drinkers valued coffee for its effects on the body and mind.","zh":"早期飲用者重視咖啡對身心的效果。"},{"en":"The phrase explains one reason people prepared coffee as a drink.","zh":"這個詞組解釋人們把咖啡製成飲品的一個原因。"},{"en":"It shows that coffee was first valued partly for its physical effects.","zh":"它顯示咖啡最初部分因身體效果而受到重視。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":3},{"front":"medicinal value","meaning":"藥用價值","examples":[{"en":"Coffee beans were boiled for their medicinal value.","zh":"咖啡豆因藥用價值而被煮沸。"},{"en":"Medicinal value means usefulness for health or treatment.","zh":"medicinal value 表示對健康或治療有用。"},{"en":"Early users may have believed coffee had medicinal value.","zh":"早期使用者可能相信咖啡有藥用價值。"},{"en":"The phrase explains another reason for boiling coffee beans.","zh":"這個詞組解釋煮咖啡豆的另一原因。"},{"en":"It connects coffee with early health beliefs.","zh":"它把咖啡與早期健康觀念連繫起來。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":3},{"front":"for a time","meaning":"有一段時間","examples":[{"en":"For a time, coffee was known by Muslims as Arabian wine.","zh":"有一段時間，咖啡被穆斯林稱為阿拉伯酒。"},{"en":"For a time means during a limited period.","zh":"for a time 表示在有限的一段時期內。"},{"en":"Coffee remained a secret for a time before spreading widely.","zh":"咖啡在廣泛傳播前有一段時間一直是秘密。"},{"en":"The phrase shows that the name or situation later changed.","zh":"這個詞組顯示名稱或情況後來改變了。"},{"en":"It is used to describe a temporary historical stage.","zh":"它用來描述暫時的歷史階段。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":4},{"front":"be known as","meaning":"被稱為","examples":[{"en":"Coffee was known by Muslims as Arabian wine.","zh":"咖啡被穆斯林稱為阿拉伯酒。"},{"en":"Coffea Canephora is usually known as Robusta.","zh":"Coffea Canephora 通常被稱為羅布斯塔咖啡。"},{"en":"To be known as something means to be called by that name.","zh":"be known as 表示被叫作某名稱。"},{"en":"The dried beans are known as parchment at one stage.","zh":"曬乾的咖啡豆在某一階段被稱為 parchment。"},{"en":"The phrase introduces a name or label.","zh":"這個詞組引入名稱或標籤。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":4},{"front":"Arabian wine","meaning":"阿拉伯酒","examples":[{"en":"Coffee was called Arabian wine because Islam forbade alcohol.","zh":"咖啡被稱為阿拉伯酒，因為伊斯蘭教禁止飲酒。"},{"en":"Arabian wine was an early name for coffee among Muslims.","zh":"阿拉伯酒是穆斯林對咖啡的早期稱呼。"},{"en":"The name suggests coffee served as an alternative to alcoholic drink.","zh":"這個名稱暗示咖啡可作為酒精飲品的替代品。"},{"en":"The phrase reflects coffee’s cultural setting in Arabia.","zh":"這個詞組反映咖啡在阿拉伯的文化背景。"},{"en":"It shows how coffee was understood before modern coffee culture.","zh":"它顯示現代咖啡文化出現前人們如何理解咖啡。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":4},{"front":"forbid alcohol","meaning":"禁止飲酒","examples":[{"en":"Islam forbade alcohol.","zh":"伊斯蘭教禁止飲酒。"},{"en":"Because Islam forbade alcohol, coffee became known as Arabian wine.","zh":"由於伊斯蘭教禁止飲酒，咖啡被稱為阿拉伯酒。"},{"en":"To forbid alcohol means to prohibit drinking alcoholic beverages.","zh":"forbid alcohol 表示禁止飲用含酒精飲品。"},{"en":"Religious rules can influence food and drink culture.","zh":"宗教規則可以影響飲食文化。"},{"en":"The phrase explains why coffee received its early name.","zh":"這個詞組解釋咖啡早期名稱的原因。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":4},{"front":"probably by accident","meaning":"很可能是偶然地","examples":[{"en":"Probably by accident in Turkey, people discovered that roasting beans made coffee taste better.","zh":"很可能是在土耳其偶然地，人們發現烘焙咖啡豆令咖啡更好喝。"},{"en":"Probably by accident means likely not by deliberate planning.","zh":"probably by accident 表示很可能不是有意計劃。"},{"en":"The discovery of roasted coffee may have happened accidentally.","zh":"烘焙咖啡的發現可能是偶然發生的。"},{"en":"Many food discoveries happen probably by accident.","zh":"很多食物發現很可能是偶然地出現。"},{"en":"The phrase suggests uncertainty about the exact cause.","zh":"這個詞組暗示對確切原因有不確定性。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":4},{"front":"roasting the beans","meaning":"烘焙咖啡豆","examples":[{"en":"Roasting the beans could produce a delicious drink.","zh":"烘焙咖啡豆可以製成美味飲品。"},{"en":"People discovered that roasting the beans improved coffee’s taste.","zh":"人們發現烘焙咖啡豆改善了咖啡味道。"},{"en":"Roasting changes the colour, smell, and flavour of coffee beans.","zh":"烘焙會改變咖啡豆的顏色、香氣和味道。"},{"en":"The roasted beans were later crushed and boiled.","zh":"烘焙過的咖啡豆後來被壓碎和煮沸。"},{"en":"The phrase describes heating coffee beans before brewing.","zh":"這個詞組描述沖泡前加熱咖啡豆。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":4},{"front":"produce a delicious drink","meaning":"製成美味飲品","examples":[{"en":"Roasting coffee beans could produce a delicious drink.","zh":"烘焙咖啡豆可以製成美味飲品。"},{"en":"The improved process helped produce a delicious drink.","zh":"改良過程幫助製成美味飲品。"},{"en":"Crushed roasted beans boiled in water produced early coffee.","zh":"壓碎的烘焙豆在水中煮沸，製成早期咖啡。"},{"en":"To produce a delicious drink means to make a beverage that tastes good.","zh":"produce a delicious drink 表示製作味道好的飲品。"},{"en":"The phrase describes the result of better preparation.","zh":"這個詞組描述更好製作方法的結果。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":4},{"front":"roasted beans","meaning":"烘焙過的咖啡豆","examples":[{"en":"The roasted beans were first crushed and then boiled in water.","zh":"烘焙過的咖啡豆先被壓碎，然後在水中煮沸。"},{"en":"Roasted beans have been heated to develop flavour.","zh":"烘焙過的咖啡豆已被加熱以發展風味。"},{"en":"The roasted beans produced a more pleasant drink.","zh":"烘焙過的咖啡豆製成更好喝的飲品。"},{"en":"Modern coffee still depends on properly roasted beans.","zh":"現代咖啡仍依靠妥善烘焙過的咖啡豆。"},{"en":"The phrase refers to coffee beans after roasting.","zh":"這個詞組指經過烘焙的咖啡豆。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":4},{"front":"be crushed","meaning":"被壓碎","examples":[{"en":"The roasted beans were crushed before being boiled.","zh":"烘焙過的咖啡豆在煮沸前被壓碎。"},{"en":"To be crushed means to be broken into smaller pieces.","zh":"be crushed 表示被弄成較小碎片。"},{"en":"Crushed beans release flavour more easily in water.","zh":"被壓碎的咖啡豆更容易在水中釋放味道。"},{"en":"The beans were first roasted and then crushed.","zh":"咖啡豆先被烘焙，然後被壓碎。"},{"en":"The phrase describes one step in early coffee preparation.","zh":"這個詞組描述早期咖啡製作的一個步驟。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":4},{"front":"boiled in water","meaning":"在水中煮沸","examples":[{"en":"The crushed beans were boiled in water.","zh":"被壓碎的咖啡豆在水中煮沸。"},{"en":"Beans boiled in water produced a crude coffee drink.","zh":"在水中煮沸的咖啡豆製成原始咖啡飲品。"},{"en":"The process involved roasting, crushing, and boiling in water.","zh":"這個過程包括烘焙、壓碎和在水中煮沸。"},{"en":"To be boiled in water means to be cooked in hot water.","zh":"boiled in water 表示在熱水中烹煮。"},{"en":"The phrase describes the brewing stage.","zh":"這個詞組描述沖泡階段。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":4},{"front":"a crude version of","meaning":"……的原始版本","examples":[{"en":"The process created a crude version of the beverage we enjoy today.","zh":"這個過程製成了我們今天享用飲品的原始版本。"},{"en":"A crude version of something is an early and simple form of it.","zh":"a crude version of something 表示某物早期而簡單的形式。"},{"en":"Early coffee was a crude version of modern coffee.","zh":"早期咖啡是現代咖啡的原始版本。"},{"en":"The drink lacked later refinements such as filtering and milk.","zh":"這種飲品缺少後來的過濾和加奶等改良。"},{"en":"The phrase contrasts early simplicity with modern improvement.","zh":"這個詞組把早期簡單形式與現代改良作對比。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":4},{"front":"the beverage we enjoy today","meaning":"我們今天享用的飲品","examples":[{"en":"Early coffee was a crude version of the beverage we enjoy today.","zh":"早期咖啡是我們今天享用的飲品的原始版本。"},{"en":"The beverage we enjoy today developed through many improvements.","zh":"我們今天享用的飲品經過許多改良發展而來。"},{"en":"Modern coffee differs from the early boiled drink.","zh":"現代咖啡不同於早期煮沸飲品。"},{"en":"The phrase refers to coffee as it is commonly drunk now.","zh":"這個詞組指現在人們通常飲用的咖啡。"},{"en":"It connects historical preparation with present-day coffee.","zh":"它把歷史製作方式與今天的咖啡連繫起來。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":5},{"front":"coffeehouses","meaning":"咖啡館","examples":[{"en":"The first coffeehouses were opened in Europe in the seventeenth century.","zh":"第一批咖啡館於十七世紀在歐洲開設。"},{"en":"Coffeehouses became places where people drank and discussed coffee.","zh":"咖啡館成為人們飲用和討論咖啡的地方。"},{"en":"European coffeehouses helped spread coffee culture.","zh":"歐洲咖啡館幫助傳播咖啡文化。"},{"en":"A coffeehouse is a public place where coffee is served.","zh":"coffeehouse 是供應咖啡的公共場所。"},{"en":"The phrase refers to early cafés.","zh":"這個詞組指早期咖啡店。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":5},{"front":"in the seventeenth century","meaning":"在十七世紀","examples":[{"en":"The first European coffeehouses opened in the seventeenth century.","zh":"第一批歐洲咖啡館在十七世紀開設。"},{"en":"In the seventeenth century, coffee became more familiar in Europe.","zh":"在十七世紀，咖啡在歐洲變得更為人熟悉。"},{"en":"The phrase refers to the years from 1601 to 1700.","zh":"這個詞組指1601年至1700年。"},{"en":"Coffeehouses appeared in Europe in the seventeenth century.","zh":"咖啡館在十七世紀於歐洲出現。"},{"en":"It provides a historical time period.","zh":"它提供歷史時期。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":5},{"front":"establish the habit of","meaning":"建立……的習慣","examples":[{"en":"The Viennese established the habit of refining the brew.","zh":"維也納人建立了改良沖泡飲品的習慣。"},{"en":"To establish the habit of doing something means to begin doing it regularly.","zh":"establish the habit of doing something 表示開始定期做某事。"},{"en":"Coffee drinkers established the habit of filtering out the grounds.","zh":"咖啡飲用者建立了濾走咖啡渣的習慣。"},{"en":"The Viennese established the habit of adding milk and sugar.","zh":"維也納人建立了加奶和糖的習慣。"},{"en":"The phrase describes the beginning of a repeated practice.","zh":"這個詞組描述反覆做法的開始。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":5},{"front":"refining the brew","meaning":"改良沖泡飲品","examples":[{"en":"The Viennese refined the brew by filtering it and adding milk.","zh":"維也納人透過過濾和加奶改良沖泡飲品。"},{"en":"Refining the brew made coffee smoother and more pleasant.","zh":"改良沖泡飲品令咖啡更順口、更好喝。"},{"en":"The brew was improved by removing grounds and sweetening it.","zh":"這種飲品透過去除咖啡渣和加甜得到改善。"},{"en":"To refine the brew means to improve the prepared drink.","zh":"refine the brew 表示改善沖泡好的飲品。"},{"en":"The phrase describes making coffee more acceptable to drinkers.","zh":"這個詞組描述令咖啡更受飲用者接受。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":5},{"front":"filter out","meaning":"濾走","examples":[{"en":"The Viennese filtered out the grounds before drinking coffee.","zh":"維也納人在飲用咖啡前濾走咖啡渣。"},{"en":"To filter out something means to remove it using a filter.","zh":"filter out 表示用濾器除去某物。"},{"en":"Filtering out coffee grounds improved the texture of the drink.","zh":"濾走咖啡渣改善了飲品口感。"},{"en":"Modern brewing often filters out unwanted particles.","zh":"現代沖泡通常會濾走不需要的顆粒。"},{"en":"The phrase describes separating solids from liquid.","zh":"這個詞組描述把固體與液體分離。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":5},{"front":"the grounds","meaning":"咖啡渣","examples":[{"en":"The grounds were filtered out to improve the drink.","zh":"咖啡渣被濾走，以改善飲品。"},{"en":"Coffee grounds are the small pieces left after coffee is crushed or brewed.","zh":"coffee grounds 是咖啡被壓碎或沖泡後留下的小顆粒。"},{"en":"Removing the grounds made the drink smoother.","zh":"去除咖啡渣令飲品更順口。"},{"en":"The Viennese refined coffee by filtering out the grounds.","zh":"維也納人透過濾走咖啡渣來改良咖啡。"},{"en":"The phrase refers to used or crushed coffee particles.","zh":"這個詞組指用過或壓碎的咖啡顆粒。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":5},{"front":"sweetening it","meaning":"把它加甜","examples":[{"en":"The Viennese refined coffee by sweetening it.","zh":"維也納人透過把咖啡加甜來改良它。"},{"en":"Sweetening it means adding sugar or something sweet.","zh":"sweetening it 表示加入糖或甜味物質。"},{"en":"Sweetening coffee changed its taste and made it more pleasant.","zh":"把咖啡加甜改變了味道，令它更好喝。"},{"en":"The brew was filtered, sweetened, and mixed with milk.","zh":"這種沖泡飲品被過濾、加甜並加入牛奶。"},{"en":"The phrase describes one way coffee was improved.","zh":"這個詞組描述咖啡的一種改良方式。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":5},{"front":"a dash of milk","meaning":"少量牛奶","examples":[{"en":"The Viennese added a dash of milk to coffee.","zh":"維也納人在咖啡中加入少量牛奶。"},{"en":"A dash of milk means a small amount of milk.","zh":"a dash of milk 表示少量牛奶。"},{"en":"Adding a dash of milk softened the flavour of coffee.","zh":"加入少量牛奶令咖啡味道較柔和。"},{"en":"Many modern coffee drinks still include milk.","zh":"很多現代咖啡飲品仍含有牛奶。"},{"en":"The phrase describes a small addition to a drink.","zh":"這個詞組描述向飲品加入少量東西。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":5},{"front":"explore the planet for","meaning":"在全球尋找……","examples":[{"en":"If you explored the planet for coffee, you would find many wild species.","zh":"如果你在全球尋找咖啡，會發現很多野生物種。"},{"en":"To explore the planet for something means to search around the world for it.","zh":"explore the planet for something 表示在世界各地搜尋某物。"},{"en":"Botanists could explore the planet for wild coffee plants.","zh":"植物學家可以在全球尋找野生咖啡植物。"},{"en":"The phrase gives a global perspective on coffee varieties.","zh":"這個詞組提供關於咖啡品種的全球視角。"},{"en":"It suggests that coffee grows in many regions.","zh":"它暗示咖啡生長於許多地區。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":5},{"front":"coffee plants","meaning":"咖啡樹；咖啡植物","examples":[{"en":"About 60 species of coffee plants grow wild in different regions.","zh":"約60種咖啡植物在不同地區野生生長。"},{"en":"Coffee plants produce berries that contain coffee beans.","zh":"咖啡植物會結出含有咖啡豆的漿果。"},{"en":"Cultivated coffee plants are kept shorter for easier harvesting.","zh":"栽培咖啡植物會被控制得較矮，以便採收。"},{"en":"Coffee plants need special conditions to produce a good crop.","zh":"咖啡植物需要特殊條件才能產出好收成。"},{"en":"The phrase refers to the plants from which coffee comes.","zh":"這個詞組指咖啡來源的植物。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":5},{"front":"grow wild","meaning":"野生生長","examples":[{"en":"Many coffee plants grow wild in Africa and Malaysia.","zh":"很多咖啡植物在非洲和馬來西亞野生生長。"},{"en":"To grow wild means to grow naturally without cultivation.","zh":"grow wild 表示在沒有人工栽培下自然生長。"},{"en":"Around 60 species of coffee plants grow wild.","zh":"約60種咖啡植物野生生長。"},{"en":"Wild plants may differ from cultivated plants in height.","zh":"野生植物在高度上可能不同於栽培植物。"},{"en":"The phrase describes natural growth.","zh":"這個詞組描述自然生長。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":6},{"front":"only about ten of them","meaning":"其中只有約十種","examples":[{"en":"Only about ten of the coffee plant species are actually cultivated.","zh":"咖啡植物物種中只有約十種實際上被栽培。"},{"en":"Only about ten of them are grown for human use.","zh":"其中只有約十種被種植供人類使用。"},{"en":"The phrase shows that most wild coffee species are not cultivated.","zh":"這個詞組顯示大多數野生咖啡物種沒有被栽培。"},{"en":"Out of many species, only about ten are used commercially.","zh":"在許多物種中，只有約十種用於商業用途。"},{"en":"It gives an approximate small number within a larger group.","zh":"它在較大群體中提供一個約略小數字。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":6},{"front":"be actually cultivated","meaning":"實際上被栽培","examples":[{"en":"Only some coffee species are actually cultivated.","zh":"只有一些咖啡物種實際上被栽培。"},{"en":"To be actually cultivated means to be deliberately grown by people.","zh":"be actually cultivated 表示被人有意種植。"},{"en":"Many species grow wild, but only a few are actually cultivated.","zh":"很多物種野生生長，但只有少數實際上被栽培。"},{"en":"Arabica and Robusta are among the species actually cultivated for coffee production.","zh":"阿拉比卡和羅布斯塔是實際上被栽培用於咖啡生產的物種。"},{"en":"The phrase contrasts wild growth with farming.","zh":"這個詞組把野生生長與農業種植作對比。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":6},{"front":"be responsible for","meaning":"是……的來源；負責","examples":[{"en":"Two species are responsible for almost all the coffee produced in the world.","zh":"兩個物種是世界上幾乎所有咖啡的來源。"},{"en":"Arabica and Robusta are responsible for most commercial coffee.","zh":"阿拉比卡和羅布斯塔負責大部分商業咖啡。"},{"en":"To be responsible for something means to be the main cause or source of it.","zh":"be responsible for 表示是某結果的主要原因或來源。"},{"en":"Certain plants are responsible for most global coffee production.","zh":"某些植物是全球大部分咖啡生產的來源。"},{"en":"The phrase identifies the source of an outcome.","zh":"這個詞組指出結果來源。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":6},{"front":"almost all the coffee produced","meaning":"幾乎所有生產出來的咖啡","examples":[{"en":"Two species produce almost all the coffee in the world.","zh":"兩個物種生產世界上幾乎所有咖啡。"},{"en":"Almost all the coffee produced comes from Arabica and Robusta.","zh":"幾乎所有生產出來的咖啡都來自阿拉比卡和羅布斯塔。"},{"en":"The phrase means nearly the entire global coffee supply.","zh":"這個詞組表示接近整個全球咖啡供應。"},{"en":"Few species are responsible for almost all commercial coffee.","zh":"少數物種是幾乎所有商業咖啡的來源。"},{"en":"It highlights the dominance of two coffee species.","zh":"它突出兩種咖啡物種的主導地位。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":6},{"front":"Coffea Arabica","meaning":"阿拉比卡咖啡","examples":[{"en":"Coffea Arabica is one of the two main coffee species.","zh":"阿拉比卡咖啡是兩種主要咖啡物種之一。"},{"en":"Coffea Arabica produces arabica beans.","zh":"阿拉比卡咖啡產出阿拉比卡咖啡豆。"},{"en":"This species is responsible for a major share of world coffee.","zh":"這個物種負責全球咖啡的重要部分。"},{"en":"Coffee varieties have developed from species such as Coffea Arabica.","zh":"咖啡品種由阿拉比卡咖啡等物種發展而來。"},{"en":"The phrase is the scientific name for Arabica coffee.","zh":"這個詞組是阿拉比卡咖啡的學名。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":6},{"front":"Coffea Canephora","meaning":"中果咖啡；羅布斯塔咖啡","examples":[{"en":"Coffea Canephora is usually known as Robusta.","zh":"Coffea Canephora 通常稱為羅布斯塔咖啡。"},{"en":"Coffea Canephora is one of the two main cultivated coffee species.","zh":"中果咖啡是兩種主要栽培咖啡物種之一。"},{"en":"It produces robusta beans.","zh":"它產出羅布斯塔咖啡豆。"},{"en":"The passage names Coffea Canephora alongside Coffea Arabica.","zh":"文章把中果咖啡與阿拉比卡咖啡並列。"},{"en":"The phrase is the scientific name of Robusta coffee.","zh":"這個詞組是羅布斯塔咖啡的學名。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":6},{"front":"usually known as","meaning":"通常稱為","examples":[{"en":"Coffea Canephora is usually known as Robusta.","zh":"Coffea Canephora 通常稱為羅布斯塔咖啡。"},{"en":"Usually known as means commonly called.","zh":"usually known as 表示通常被叫作。"},{"en":"Coffee species often have scientific names and common names.","zh":"咖啡物種通常有學名和通稱。"},{"en":"The dried beans are sometimes known by processing terms.","zh":"曬乾的咖啡豆有時以加工術語稱呼。"},{"en":"The phrase introduces the common name of something.","zh":"這個詞組引入某物的常用名稱。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":6},{"front":"Robusta","meaning":"羅布斯塔咖啡","examples":[{"en":"Robusta is one of the two main coffee species.","zh":"羅布斯塔咖啡是兩種主要咖啡物種之一。"},{"en":"Robusta is the common name for Coffea Canephora.","zh":"羅布斯塔咖啡是 Coffea Canephora 的通稱。"},{"en":"Robusta beans are produced by cultivated coffee plants.","zh":"羅布斯塔咖啡豆由栽培咖啡植物產出。"},{"en":"The passage compares Robusta with Arabica.","zh":"文章把羅布斯塔咖啡與阿拉比卡咖啡作比較。"},{"en":"The phrase refers to a major commercial coffee type.","zh":"這個詞組指主要商業咖啡類型。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":6},{"front":"ecological differences","meaning":"生態差異","examples":[{"en":"Ecological differences among coffee-producing countries have caused variation.","zh":"咖啡生產國之間的生態差異造成了變化。"},{"en":"Ecological differences include climate, soil, altitude, and rainfall.","zh":"生態差異包括氣候、土壤、海拔和降雨。"},{"en":"Such differences influence coffee plants and their mutations.","zh":"這些差異影響咖啡植物及其變異。"},{"en":"The phrase explains why coffee varieties differ among regions.","zh":"這個詞組解釋為何不同地區的咖啡品種不同。"},{"en":"It refers to differences in natural growing environments.","zh":"它指自然生長環境的差異。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":6},{"front":"coffee-producing countries","meaning":"咖啡生產國","examples":[{"en":"Coffee-producing countries have different growing conditions.","zh":"咖啡生產國有不同生長條件。"},{"en":"Harvesting time varies among coffee-producing countries.","zh":"咖啡生產國之間的收成時間不同。"},{"en":"Coffee-producing countries may differ in climate and altitude.","zh":"咖啡生產國在氣候和海拔方面可能不同。"},{"en":"These countries grow coffee as an agricultural product.","zh":"這些國家把咖啡作為農產品種植。"},{"en":"The phrase refers to countries where coffee is produced.","zh":"這個詞組指生產咖啡的國家。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":6},{"front":"undergo many mutations","meaning":"經歷多次變異","examples":[{"en":"Both coffee species have undergone many mutations.","zh":"兩種咖啡物種都經歷多次變異。"},{"en":"To undergo many mutations means to experience many genetic changes.","zh":"undergo many mutations 表示經歷許多基因變化。"},{"en":"Ecological differences can lead plants to undergo mutations over time.","zh":"生態差異可以使植物隨時間經歷變異。"},{"en":"These mutations created many coffee subspecies.","zh":"這些變異形成了許多咖啡亞種。"},{"en":"The phrase describes biological change.","zh":"這個詞組描述生物變化。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":7},{"front":"now exist in","meaning":"現以……形式存在","examples":[{"en":"The two main coffee species now exist in many subspecies.","zh":"兩種主要咖啡物種現以許多亞種形式存在。"},{"en":"Coffee now exists in several cultivated forms.","zh":"咖啡現在以幾種栽培形式存在。"},{"en":"The phrase means that something is currently found in particular forms.","zh":"這個詞組表示某物目前以特定形式出現。"},{"en":"Arabica and Robusta now exist in many regional varieties.","zh":"阿拉比卡和羅布斯塔現以許多地區品種形式存在。"},{"en":"It describes present-day forms after development.","zh":"它描述發展後的現代形式。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":7},{"front":"subspecies","meaning":"亞種","examples":[{"en":"Arabica and Robusta now exist in many subspecies.","zh":"阿拉比卡和羅布斯塔現在以許多亞種形式存在。"},{"en":"Subspecies are smaller groups within a species.","zh":"亞種是一個物種內較小的分類群。"},{"en":"Ecological differences can produce different subspecies.","zh":"生態差異可以產生不同亞種。"},{"en":"Coffee subspecies may vary in flavour, growth, and resistance.","zh":"咖啡亞種可能在風味、生長和抗性上不同。"},{"en":"The phrase is a biological classification term.","zh":"這個詞組是生物分類術語。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":7},{"front":"wild plants","meaning":"野生植物","examples":[{"en":"Wild coffee plants can reach 10 to 12 metres in height.","zh":"野生咖啡植物可以高達10至12米。"},{"en":"Wild plants grow naturally rather than in cultivation.","zh":"野生植物自然生長，而不是人工栽培。"},{"en":"Wild coffee plants may be much taller than cultivated plants.","zh":"野生咖啡植物可能比栽培植物高很多。"},{"en":"The passage compares wild plants with cultivated plants.","zh":"文章把野生植物與栽培植物作比較。"},{"en":"The phrase refers to plants growing without farming.","zh":"這個詞組指沒有農業栽培而生長的植物。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":7},{"front":"reach…in height","meaning":"高達……","examples":[{"en":"Wild coffee plants can reach 10 to 12 metres in height.","zh":"野生咖啡植物可以高達10至12米。"},{"en":"To reach a certain height means to grow that tall.","zh":"reach a certain height 表示長到某高度。"},{"en":"Cultivated plants reach a much lower height.","zh":"栽培植物達到的高度低得多。"},{"en":"Coffee plants are kept shorter to make harvesting easier.","zh":"咖啡植物被保持較矮，以令採收更容易。"},{"en":"The phrase describes plant size.","zh":"這個詞組描述植物大小。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":7},{"front":"cultivated plants","meaning":"栽培植物","examples":[{"en":"Cultivated plants reach a height of around four metres.","zh":"栽培植物達到約四米高度。"},{"en":"Cultivated plants are grown and managed by people.","zh":"栽培植物由人種植和管理。"},{"en":"Coffee farmers keep cultivated plants shorter than wild plants.","zh":"咖啡農把栽培植物控制得比野生植物矮。"},{"en":"Cultivated plants are easier to harvest.","zh":"栽培植物較容易採收。"},{"en":"The phrase contrasts farmed plants with wild plants.","zh":"這個詞組把人工種植植物與野生植物作對比。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":7},{"front":"reach a height of","meaning":"達到……高度","examples":[{"en":"Cultivated coffee plants reach a height of around four metres.","zh":"栽培咖啡植物達到約四米高度。"},{"en":"Wild plants can reach a height of 10 to 12 metres.","zh":"野生植物可以達到10至12米高度。"},{"en":"The phrase means to grow to a particular height.","zh":"這個詞組表示長到特定高度。"},{"en":"Shorter plants make harvesting easier and more economical.","zh":"較矮的植物令採收更容易且更具經濟效益。"},{"en":"It is often used to describe plant growth.","zh":"它常用於描述植物生長。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":7},{"front":"make harvesting easier","meaning":"令採收更容易","examples":[{"en":"Shorter plants make harvesting easier.","zh":"較矮的植物令採收更容易。"},{"en":"Farmers keep coffee plants short to make harvesting easier.","zh":"農民讓咖啡植物保持較矮，以令採收更容易。"},{"en":"Easier harvesting reduces labour and time.","zh":"採收更容易可以減少勞力和時間。"},{"en":"The phrase means to make collecting the crop less difficult.","zh":"這個詞組表示令收集作物不那麼困難。"},{"en":"It explains why cultivated coffee plants are not allowed to grow too tall.","zh":"它解釋為何栽培咖啡植物不會被讓其長得太高。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":7},{"front":"make cultivation more economical","meaning":"令栽培更具經濟效益","examples":[{"en":"Shorter coffee plants make cultivation more economical.","zh":"較矮的咖啡植物令栽培更具經濟效益。"},{"en":"More economical cultivation costs less and uses labour efficiently.","zh":"更具經濟效益的栽培成本較低，並有效使用勞力。"},{"en":"Easier harvesting can make cultivation more economical.","zh":"採收更容易可以令栽培更具經濟效益。"},{"en":"Farmers prefer methods that make coffee production more economical.","zh":"農民偏好令咖啡生產更具經濟效益的方法。"},{"en":"The phrase connects plant management with cost efficiency.","zh":"這個詞組把植物管理與成本效益連繫起來。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":7},{"front":"smell sweet","meaning":"聞起來香甜","examples":[{"en":"The flowers are white and smell sweet.","zh":"這些花是白色的，聞起來香甜。"},{"en":"Coffee flowers smell sweet like Spanish jasmine.","zh":"咖啡花聞起來像西班牙茉莉般香甜。"},{"en":"Sweet-smelling flowers later give way to red berries.","zh":"香甜的花後來變成紅色漿果。"},{"en":"The phrase describes a pleasant fragrance.","zh":"這個詞組描述令人愉快的香氣。"},{"en":"It helps readers imagine the coffee plant.","zh":"它幫助讀者想像咖啡植物。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":7},{"front":"Spanish jasmine","meaning":"西班牙茉莉","examples":[{"en":"Coffee flowers smell sweet, like Spanish jasmine.","zh":"咖啡花聞起來香甜，像西班牙茉莉。"},{"en":"Spanish jasmine is used as a comparison for the flowers’ fragrance.","zh":"西班牙茉莉被用來比較花的香氣。"},{"en":"The passage compares the smell of coffee flowers to Spanish jasmine.","zh":"文章把咖啡花的氣味與西班牙茉莉作比較。"},{"en":"The phrase helps describe a sweet floral scent.","zh":"這個詞組幫助描述香甜花香。"},{"en":"It is used to make the description more vivid.","zh":"它用來令描述更生動。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":7},{"front":"give way to","meaning":"變成；讓位予","examples":[{"en":"Coffee flowers give way to a dark-red berry.","zh":"咖啡花會變成深紅色漿果。"},{"en":"To give way to something means to be replaced by it or develop into it.","zh":"give way to 表示被某物取代或發展成某物。"},{"en":"The white flowers give way to coffee fruit.","zh":"白色花朵變成咖啡果實。"},{"en":"In the plant’s growth cycle, flowers give way to berries.","zh":"在植物生長週期中，花朵讓位予漿果。"},{"en":"The phrase describes natural change.","zh":"這個詞組描述自然變化。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":8},{"front":"a dark-red berry","meaning":"深紅色漿果","examples":[{"en":"The flower gives way to a dark-red berry.","zh":"花朵會變成深紅色漿果。"},{"en":"A dark-red berry is the fruit of the coffee plant.","zh":"深紅色漿果是咖啡植物的果實。"},{"en":"At first sight, the dark-red berry looks like a cherry.","zh":"乍看之下，深紅色漿果像櫻桃。"},{"en":"Inside the berry are the seeds that become coffee beans.","zh":"漿果內有後來成為咖啡豆的種子。"},{"en":"The phrase describes the mature coffee fruit.","zh":"這個詞組描述成熟咖啡果實。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":8},{"front":"at first sight","meaning":"乍看之下","examples":[{"en":"At first sight, the coffee fruit looks like a big cherry.","zh":"乍看之下，咖啡果實像一顆大櫻桃。"},{"en":"At first sight means when first seen.","zh":"at first sight 表示第一次看到時。"},{"en":"At first sight, the berry resembles a cherry in size and colour.","zh":"乍看之下，這漿果在大小和顏色上都像櫻桃。"},{"en":"The phrase introduces an immediate visual impression.","zh":"這個詞組引入即時視覺印象。"},{"en":"It helps describe appearance before closer examination.","zh":"它有助在仔細觀察前描述外觀。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":8},{"front":"both in size and in colour","meaning":"在大小和顏色上都","examples":[{"en":"The fruit is like a big cherry both in size and in colour.","zh":"這果實在大小和顏色上都像一顆大櫻桃。"},{"en":"Both in size and in colour means in both dimensions and appearance.","zh":"both in size and in colour 表示在尺寸和外觀顏色兩方面都。"},{"en":"The berry resembles a cherry in two ways.","zh":"這漿果在兩方面像櫻桃。"},{"en":"The phrase makes the comparison more specific.","zh":"這個詞組令比較更具體。"},{"en":"It describes visual similarity.","zh":"它描述視覺相似性。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":8},{"front":"be coated with","meaning":"被……覆蓋","examples":[{"en":"The coffee berry is coated with a thin red film.","zh":"咖啡漿果被一層薄薄的紅色外皮覆蓋。"},{"en":"To be coated with something means to be covered by a layer of it.","zh":"be coated with 表示被某一層東西覆蓋。"},{"en":"The beans are coated with parchment and a silvery film.","zh":"咖啡豆被羊皮紙狀外層和銀色薄膜覆蓋。"},{"en":"The berry’s outer layer is called the epicarp.","zh":"漿果的外層稱為外果皮。"},{"en":"The phrase describes a covering layer.","zh":"這個詞組描述覆蓋層。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":8},{"front":"a thin red film","meaning":"一層薄薄的紅色外皮","examples":[{"en":"The berry is coated with a thin red film called the epicarp.","zh":"這漿果被一層稱為外果皮的薄薄紅色外皮覆蓋。"},{"en":"A thin red film covers the outside of the coffee berry.","zh":"一層薄薄的紅色外皮覆蓋咖啡漿果外面。"},{"en":"This film is the berry’s outer skin.","zh":"這層外皮是漿果的外層皮。"},{"en":"The phrase describes the first layer of the coffee fruit.","zh":"這個詞組描述咖啡果實的第一層。"},{"en":"It helps label the structure of the coffee bean diagram.","zh":"它有助標示咖啡豆圖表的結構。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":8},{"front":"epicarp","meaning":"外果皮","examples":[{"en":"The epicarp is the thin red film around the coffee berry.","zh":"外果皮是包圍咖啡漿果的一層薄紅色外皮。"},{"en":"The epicarp forms the outer covering of the fruit.","zh":"外果皮形成果實的外層覆蓋物。"},{"en":"In a diagram, the epicarp would label the outer red layer.","zh":"在圖表中，外果皮會標示外面的紅色層。"},{"en":"The phrase is a botanical term.","zh":"這個詞是植物學術語。"},{"en":"It refers to the outer part of the coffee fruit.","zh":"它指咖啡果實的外層部分。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":8},{"front":"contain","meaning":"含有","examples":[{"en":"The red film contains a white, sugary flesh.","zh":"紅色外皮內含有白色含糖果肉。"},{"en":"The coffee berry contains seeds in the form of two beans.","zh":"咖啡漿果含有以兩粒豆形式存在的種子。"},{"en":"To contain something means to have it inside.","zh":"contain 表示內部有某物。"},{"en":"Each coffee cherry contains important layers and seeds.","zh":"每顆咖啡櫻桃含有重要層次和種子。"},{"en":"The phrase describes what is inside something.","zh":"這個詞描述某物內部有甚麼。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":8},{"front":"sugary flesh","meaning":"含糖果肉","examples":[{"en":"The coffee berry contains a white, sugary flesh.","zh":"咖啡漿果含有白色含糖果肉。"},{"en":"Sugary flesh is the sweet soft part inside the fruit.","zh":"含糖果肉是果實內部甜而柔軟的部分。"},{"en":"The sugary flesh surrounds the seeds.","zh":"含糖果肉包圍種子。"},{"en":"This layer is also called the mesocarp.","zh":"這一層也稱為中果皮。"},{"en":"The phrase describes the edible-looking part of the berry.","zh":"這個詞組描述漿果中看似可食用的部分。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":8},{"front":"mucilaginous flesh","meaning":"黏質果肉","examples":[{"en":"The berry contains a white, sugary mucilaginous flesh.","zh":"這漿果含有白色、含糖的黏質果肉。"},{"en":"Mucilaginous flesh is sticky or jelly-like flesh inside the fruit.","zh":"黏質果肉是果實內部黏稠或啫喱狀的果肉。"},{"en":"The coffee bean is surrounded by this sticky layer.","zh":"咖啡豆被這層黏性物質包圍。"},{"en":"Processing removes the mucilaginous flesh from the beans.","zh":"加工會去除咖啡豆上的黏質果肉。"},{"en":"The phrase describes the texture of the fruit pulp.","zh":"這個詞組描述果肉質感。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":8},{"front":"mesocarp","meaning":"中果皮","examples":[{"en":"The mesocarp is the white, sugary flesh inside the berry.","zh":"中果皮是漿果內部白色含糖果肉。"},{"en":"The mesocarp lies beneath the epicarp.","zh":"中果皮位於外果皮之下。"},{"en":"In coffee fruit, the mesocarp is soft and sugary.","zh":"在咖啡果中，中果皮柔軟而含糖。"},{"en":"The phrase is a botanical term for the middle layer of fruit.","zh":"這個詞是指果實中間層的植物學術語。"},{"en":"It helps describe the structure of the coffee cherry.","zh":"它有助描述咖啡櫻桃的結構。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":8},{"front":"inside the pulp","meaning":"在果肉內","examples":[{"en":"Inside the pulp are the seeds in the form of two beans.","zh":"在果肉內，有以兩粒豆形式存在的種子。"},{"en":"Inside the pulp means within the soft fruit flesh.","zh":"inside the pulp 表示在柔軟果肉之中。"},{"en":"Coffee beans are hidden inside the pulp of the fruit.","zh":"咖啡豆藏在果實的果肉內。"},{"en":"Processing removes the pulp to reach the beans.","zh":"加工會去除果肉，以取得咖啡豆。"},{"en":"The phrase describes the location of the seeds.","zh":"這個詞組描述種子的位置。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":9},{"front":"in the form of","meaning":"以……的形式","examples":[{"en":"The seeds are in the form of two beans joined together.","zh":"種子以兩粒連在一起的豆的形式存在。"},{"en":"In the form of means shaped or arranged as something.","zh":"in the form of 表示以某形狀或形式呈現。"},{"en":"Coffee seeds appear in the form of beans.","zh":"咖啡種子以豆的形式出現。"},{"en":"Information may also be presented in the form of a diagram.","zh":"資料也可以圖表形式呈現。"},{"en":"The phrase describes shape or presentation.","zh":"這個詞組描述形狀或呈現方式。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":9},{"front":"joined along","meaning":"沿着……連接","examples":[{"en":"The two beans are joined along their flat surfaces.","zh":"兩粒咖啡豆沿着它們的平面連接。"},{"en":"Joined along means connected at a particular side or line.","zh":"joined along 表示沿着某一邊或線連接。"},{"en":"The beans fit together along their flat sides.","zh":"這兩粒豆沿着平坦一面貼合。"},{"en":"The phrase describes how the two seeds touch each other.","zh":"這個詞組描述兩顆種子如何互相接觸。"},{"en":"It is useful for explaining the coffee bean’s structure.","zh":"它適合用來解釋咖啡豆的結構。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":9},{"front":"flat surfaces","meaning":"平面","examples":[{"en":"The two coffee beans are joined along their flat surfaces.","zh":"兩粒咖啡豆沿着它們的平面連接。"},{"en":"Flat surfaces are smooth, level sides.","zh":"flat surfaces 是平滑而平坦的表面。"},{"en":"Coffee beans have curved outer sides and flat inner surfaces.","zh":"咖啡豆有彎曲外側和平坦內面。"},{"en":"The flat surfaces face each other inside the fruit.","zh":"這些平面在果實內彼此相對。"},{"en":"The phrase describes the shape of the beans.","zh":"這個詞組描述豆的形狀。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":9},{"front":"in turn","meaning":"繼而；反過來","examples":[{"en":"The beans are in turn coated with a resistant parchment.","zh":"咖啡豆繼而被堅韌的羊皮紙狀外層覆蓋。"},{"en":"In turn means next in sequence.","zh":"in turn 表示按次序接下來。"},{"en":"The berry contains flesh, and the beans are in turn covered by parchment.","zh":"漿果含有果肉，而咖啡豆繼而被羊皮紙狀外層包裹。"},{"en":"Each layer surrounds another layer in turn.","zh":"每一層繼而包圍另一層。"},{"en":"The phrase helps explain a sequence of layers.","zh":"這個詞組有助解釋層次順序。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":9},{"front":"resistant golden-yellow parchment","meaning":"堅韌的金黃色羊皮紙狀外層","examples":[{"en":"The beans are coated with a resistant golden-yellow parchment.","zh":"咖啡豆被一層堅韌的金黃色羊皮紙狀外層覆蓋。"},{"en":"Resistant parchment is a tough protective layer.","zh":"堅韌的羊皮紙狀外層是保護層。"},{"en":"The golden-yellow parchment surrounds each coffee bean.","zh":"金黃色羊皮紙狀外層包圍每粒咖啡豆。"},{"en":"Milling later removes this parchment from the beans.","zh":"後來研磨加工會去除這層外層。"},{"en":"The phrase describes the endocarp around the bean.","zh":"這個詞組描述包圍咖啡豆的內果皮。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":9},{"front":"endocarp","meaning":"內果皮","examples":[{"en":"The endocarp is the resistant parchment around the coffee bean.","zh":"內果皮是包圍咖啡豆的堅韌羊皮紙狀外層。"},{"en":"The endocarp protects the seed inside the fruit.","zh":"內果皮保護果實內的種子。"},{"en":"In processing, the endocarp is removed by milling.","zh":"在加工中，內果皮會由研磨機去除。"},{"en":"The phrase is a botanical term for the inner fruit layer.","zh":"這個詞是指果實內層的植物學術語。"},{"en":"It corresponds to the parchment layer of the coffee bean.","zh":"它對應咖啡豆的羊皮紙狀外層。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":9},{"front":"beneath the parchment","meaning":"在羊皮紙狀外層之下","examples":[{"en":"Beneath the parchment, each bean is covered by a thin film.","zh":"在羊皮紙狀外層之下，每粒豆被一層薄膜覆蓋。"},{"en":"Beneath the parchment means under the protective parchment layer.","zh":"beneath the parchment 表示在保護性羊皮紙狀外層下面。"},{"en":"A silvery film lies beneath the parchment.","zh":"一層銀色薄膜位於羊皮紙狀外層之下。"},{"en":"Milling removes the parchment and silver skin.","zh":"研磨加工會去除羊皮紙狀外層和銀皮。"},{"en":"The phrase describes the position of an inner layer.","zh":"這個詞組描述內層的位置。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":9},{"front":"silvery film","meaning":"銀色薄膜","examples":[{"en":"Each bean is covered by a very thin, silvery film.","zh":"每粒咖啡豆都被一層非常薄的銀色薄膜覆蓋。"},{"en":"The silvery film lies beneath the parchment.","zh":"銀色薄膜位於羊皮紙狀外層之下。"},{"en":"This layer is later removed during milling.","zh":"這一層後來會在研磨加工中被去除。"},{"en":"The phrase describes a delicate covering around the bean.","zh":"這個詞組描述包圍咖啡豆的細薄覆蓋物。"},{"en":"It is also called silver skin in processing.","zh":"在加工中，它也稱為銀皮。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":9},{"front":"bluish green","meaning":"帶藍的綠色","examples":[{"en":"The coffee bean is bluish green before roasting.","zh":"咖啡豆在烘焙前呈帶藍的綠色。"},{"en":"Bluish green means green with a slight blue shade.","zh":"bluish green 表示帶有一點藍色調的綠色。"},{"en":"Green beans suitable for roasting may appear bluish green.","zh":"適合烘焙的生咖啡豆可能呈帶藍的綠色。"},{"en":"Roasting changes the bean’s colour from bluish green to brown.","zh":"烘焙會把豆的顏色從帶藍的綠色變成棕色。"},{"en":"The phrase describes the colour of unroasted coffee beans.","zh":"這個詞組描述未烘焙咖啡豆的顏色。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":9},{"front":"verging on bronze","meaning":"接近青銅色","examples":[{"en":"The bean is bluish green verging on bronze.","zh":"咖啡豆呈帶藍的綠色，接近青銅色。"},{"en":"Verging on bronze means almost becoming bronze in colour.","zh":"verging on bronze 表示顏色幾乎接近青銅色。"},{"en":"The phrase gives a precise colour description.","zh":"這個詞組提供精確顏色描述。"},{"en":"The unroasted bean has a green colour close to bronze.","zh":"未烘焙咖啡豆帶有接近青銅色的綠色。"},{"en":"It describes a colour between bluish green and bronze.","zh":"它描述介乎帶藍綠色和青銅色之間的顏色。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":9},{"front":"at most","meaning":"最多；至多","examples":[{"en":"The bean is at most 11 millimetres long.","zh":"咖啡豆最多11毫米長。"},{"en":"At most means no more than.","zh":"at most 表示不超過。"},{"en":"A coffee bean is at most 8 millimetres wide.","zh":"一粒咖啡豆最多8毫米闊。"},{"en":"The phrase gives an upper limit.","zh":"這個詞組提供上限。"},{"en":"It is used when describing maximum size.","zh":"它用於描述最大尺寸。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":10},{"front":"millimetres long","meaning":"……毫米長","examples":[{"en":"The bean is at most 11 millimetres long.","zh":"咖啡豆最多11毫米長。"},{"en":"Millimetres long describes the length of a small object.","zh":"millimetres long 描述小物件的長度。"},{"en":"Coffee beans are measured in millimetres because they are small.","zh":"咖啡豆很小，因此以毫米量度。"},{"en":"The phrase gives precise size information.","zh":"這個詞組提供精確尺寸資料。"},{"en":"It is useful for labelling the coffee bean’s dimensions.","zh":"它適合標示咖啡豆尺寸。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":10},{"front":"millimetres wide","meaning":"……毫米闊","examples":[{"en":"The bean is at most 8 millimetres wide.","zh":"咖啡豆最多8毫米闊。"},{"en":"Millimetres wide describes the width of a small object.","zh":"millimetres wide 描述小物件的闊度。"},{"en":"The coffee bean’s width is less than its length.","zh":"咖啡豆的闊度小於長度。"},{"en":"The phrase gives a precise measurement.","zh":"這個詞組提供精確量度。"},{"en":"It helps readers imagine the size of a coffee bean.","zh":"它幫助讀者想像咖啡豆大小。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":10},{"front":"special conditions","meaning":"特殊條件","examples":[{"en":"Coffee plants need special conditions to give a satisfactory crop.","zh":"咖啡植物需要特殊條件才能產出令人滿意的收成。"},{"en":"Special conditions include climate, soil, rainfall, and altitude.","zh":"特殊條件包括氣候、土壤、降雨和海拔。"},{"en":"Without special conditions, coffee plants may not produce well.","zh":"沒有特殊條件，咖啡植物可能無法良好生產。"},{"en":"The phrase refers to particular requirements for successful growth.","zh":"這個詞組指成功生長所需的特定要求。"},{"en":"It introduces the environmental needs of coffee.","zh":"它引入咖啡的環境需求。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":10},{"front":"give a satisfactory crop","meaning":"產出令人滿意的收成","examples":[{"en":"Coffee plants need suitable conditions to give a satisfactory crop.","zh":"咖啡植物需要合適條件才能產出令人滿意的收成。"},{"en":"To give a satisfactory crop means to produce an acceptable harvest.","zh":"give a satisfactory crop 表示產出令人接受的收穫。"},{"en":"Soil and rainfall help coffee plants give a satisfactory crop.","zh":"土壤和降雨幫助咖啡植物產出令人滿意的收成。"},{"en":"Poor conditions may reduce the crop.","zh":"條件不佳可能減少收成。"},{"en":"The phrase links plant health with harvest quality.","zh":"這個詞組把植物健康與收成質量連繫起來。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":10},{"front":"hot and wet","meaning":"炎熱潮濕","examples":[{"en":"The climate for coffee needs to be hot and wet.","zh":"咖啡所需氣候要炎熱潮濕。"},{"en":"Hot and wet conditions support coffee growth in many regions.","zh":"炎熱潮濕的條件支援許多地區的咖啡生長。"},{"en":"Coffee plants often require warmth and frequent rain.","zh":"咖啡植物通常需要溫暖和頻繁降雨。"},{"en":"The phrase describes a tropical climate.","zh":"這個詞組描述熱帶氣候。"},{"en":"It is one of the suitable climates for coffee.","zh":"它是適合咖啡生長的氣候之一。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":10},{"front":"warm and temperate","meaning":"溫暖溫和","examples":[{"en":"Coffee can grow in a warm and temperate climate.","zh":"咖啡可以在溫暖溫和的氣候中生長。"},{"en":"Warm and temperate means mild, not extremely hot or cold.","zh":"warm and temperate 表示溫和，不極熱也不極冷。"},{"en":"Some coffee varieties prefer warm and temperate regions.","zh":"一些咖啡品種偏好溫暖溫和的地區。"},{"en":"The phrase describes another suitable climate for coffee.","zh":"這個詞組描述另一種適合咖啡的氣候。"},{"en":"It contrasts with very harsh climates.","zh":"它與非常惡劣的氣候形成對比。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":10},{"front":"the Tropic of Cancer","meaning":"北回歸線","examples":[{"en":"Coffee grows between the Tropic of Cancer and the Tropic of Capricorn.","zh":"咖啡生長於北回歸線和南回歸線之間。"},{"en":"The Tropic of Cancer marks the northern boundary of the tropical zone.","zh":"北回歸線標示熱帶地區的北部邊界。"},{"en":"Many coffee-growing areas lie near the Tropic of Cancer.","zh":"許多咖啡種植區位於北回歸線附近。"},{"en":"The phrase is a geographical term.","zh":"這個詞組是地理術語。"},{"en":"It helps define coffee’s suitable growing belt.","zh":"它幫助界定適合咖啡生長的地帶。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":10},{"front":"the Tropic of Capricorn","meaning":"南回歸線","examples":[{"en":"Coffee grows between the Tropic of Cancer and the Tropic of Capricorn.","zh":"咖啡生長於北回歸線和南回歸線之間。"},{"en":"The Tropic of Capricorn marks the southern boundary of the tropical zone.","zh":"南回歸線標示熱帶地區的南部邊界。"},{"en":"Coffee cultivation is common in the belt between the two tropics.","zh":"咖啡栽培常見於兩條回歸線之間的地帶。"},{"en":"The phrase is used to describe global coffee-growing regions.","zh":"這個詞組用來描述全球咖啡種植地區。"},{"en":"It identifies an important latitude line.","zh":"它指出一條重要緯線。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":10},{"front":"frequent rains","meaning":"頻繁降雨","examples":[{"en":"Coffee plants need frequent rains.","zh":"咖啡植物需要頻繁降雨。"},{"en":"Frequent rains provide water needed for coffee growth.","zh":"頻繁降雨提供咖啡生長所需水分。"},{"en":"Too little rain may reduce the crop.","zh":"降雨太少可能減少收成。"},{"en":"The phrase means rain that happens often.","zh":"這個詞組表示經常下雨。"},{"en":"It describes one requirement of coffee cultivation.","zh":"它描述咖啡栽培的一項要求。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":10},{"front":"temperatures ranging from…to…","meaning":"溫度介乎……至……","examples":[{"en":"Coffee grows best with temperatures ranging from 15 to 25°C.","zh":"咖啡在溫度介乎15至25°C時生長最佳。"},{"en":"Temperatures ranging from one number to another describe a temperature range.","zh":"temperatures ranging from one number to another 描述溫度範圍。"},{"en":"Coffee prefers temperatures ranging from moderate to warm.","zh":"咖啡偏好介乎溫和至溫暖的溫度。"},{"en":"The phrase gives minimum and maximum temperatures.","zh":"這個詞組提供最低和最高溫度。"},{"en":"It is useful for describing climate requirements.","zh":"它適合描述氣候要求。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":10},{"front":"deep and permeable","meaning":"深厚且透水的","examples":[{"en":"The soil should be deep and permeable.","zh":"土壤應深厚且透水。"},{"en":"Deep and permeable soil allows roots and water to move properly.","zh":"深厚且透水的土壤讓根系和水分適當移動。"},{"en":"Coffee plants grow better in deep, well-drained soil.","zh":"咖啡植物在深厚且排水良好的土壤中生長較好。"},{"en":"Permeable soil lets water pass through.","zh":"透水土壤能讓水通過。"},{"en":"The phrase describes suitable soil structure.","zh":"這個詞組描述合適土壤結構。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":11},{"front":"well irrigated","meaning":"灌溉良好的","examples":[{"en":"The soil should be well irrigated.","zh":"土壤應灌溉良好。"},{"en":"Well irrigated soil receives enough water for plant growth.","zh":"灌溉良好的土壤得到足夠水分供植物生長。"},{"en":"Coffee needs water, but the soil must also drain properly.","zh":"咖啡需要水，但土壤也必須排水良好。"},{"en":"Irrigation helps plants during dry periods.","zh":"灌溉在乾旱時期幫助植物。"},{"en":"The phrase describes managed water supply.","zh":"這個詞組描述受管理的供水。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":11},{"front":"well-drained subsoil","meaning":"排水良好的底土","examples":[{"en":"Coffee plants need well-drained subsoil.","zh":"咖啡植物需要排水良好的底土。"},{"en":"Well-drained subsoil allows excess water to move away.","zh":"排水良好的底土讓多餘水分流走。"},{"en":"Poor drainage may damage coffee roots.","zh":"排水不佳可能損害咖啡根部。"},{"en":"The phrase describes the lower layer of soil beneath the surface.","zh":"這個詞組描述表土下方的土壤層。"},{"en":"It is one of the soil conditions suitable for coffee.","zh":"它是適合咖啡的土壤條件之一。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":11},{"front":"hillsides","meaning":"山坡地","examples":[{"en":"The best land for coffee is hillsides or newly cleared woodland.","zh":"最適合咖啡的土地是山坡地或新開墾林地。"},{"en":"Hillsides can provide good drainage for coffee plants.","zh":"山坡地可以為咖啡植物提供良好排水。"},{"en":"Many coffee plantations are located on hillsides.","zh":"許多咖啡種植園位於山坡地。"},{"en":"The phrase refers to the sloping sides of hills.","zh":"這個詞組指山丘的斜坡部分。"},{"en":"It describes suitable land for coffee cultivation.","zh":"它描述適合咖啡栽培的土地。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":11},{"front":"newly cleared woodland","meaning":"新開墾林地","examples":[{"en":"Newly cleared woodland can be good for coffee cultivation.","zh":"新開墾林地可能適合咖啡栽培。"},{"en":"Newly cleared woodland is forest land recently cleared for planting.","zh":"新開墾林地是最近被清理以供種植的林地。"},{"en":"Coffee may grow well on land that has just been opened for agriculture.","zh":"咖啡可能在剛開墾作農業用途的土地上生長良好。"},{"en":"The phrase describes a type of suitable cultivation land.","zh":"這個詞組描述一種合適栽培土地。"},{"en":"It connects coffee farming with land preparation.","zh":"它把咖啡種植與土地準備連繫起來。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":11},{"front":"ideal altitude","meaning":"理想海拔","examples":[{"en":"The ideal altitude for coffee is between 600 and 1,200 metres.","zh":"咖啡的理想海拔是600至1,200米之間。"},{"en":"Ideal altitude means the best height above sea level for growth.","zh":"理想海拔表示最適合生長的海拔高度。"},{"en":"Some coffee varieties thrive above the ideal altitude range.","zh":"一些咖啡品種在理想海拔範圍以上茁壯成長。"},{"en":"Altitude affects temperature and coffee quality.","zh":"海拔影響溫度和咖啡品質。"},{"en":"The phrase describes an important growing condition.","zh":"這個詞組描述重要生長條件。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":11},{"front":"thrive at","meaning":"在……茁壯成長","examples":[{"en":"Some coffee varieties thrive at higher altitudes.","zh":"一些咖啡品種在較高海拔茁壯成長。"},{"en":"To thrive at a place or level means to grow very well there.","zh":"thrive at 表示在某地或某水平下生長得很好。"},{"en":"Coffee plants may thrive at certain temperatures and altitudes.","zh":"咖啡植物可能在特定溫度和海拔茁壯成長。"},{"en":"A variety that thrives at high altitude may produce a good crop.","zh":"在高海拔茁壯成長的品種可能產出好收成。"},{"en":"The phrase describes successful growth under conditions.","zh":"這個詞組描述在某些條件下成功生長。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":11},{"front":"careful cultivation","meaning":"細心栽培","examples":[{"en":"Careful cultivation is needed to protect coffee plants.","zh":"需要細心栽培來保護咖啡植物。"},{"en":"Careful cultivation includes sowing, transplanting, and shielding seedlings.","zh":"細心栽培包括播種、移植和保護幼苗。"},{"en":"Coffee requires careful cultivation at every stage of growth.","zh":"咖啡在每個生長階段都需要細心栽培。"},{"en":"Without careful cultivation, young plants may be damaged.","zh":"沒有細心栽培，幼苗可能受損。"},{"en":"The phrase means attentive and planned farming.","zh":"這個詞組表示用心而有計劃的耕種。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":11},{"front":"every stage of growth","meaning":"每個生長階段","examples":[{"en":"Coffee plants need protection at every stage of growth.","zh":"咖啡植物在每個生長階段都需要保護。"},{"en":"Every stage of growth means each period from seed to mature plant.","zh":"every stage of growth 表示從種子到成熟植物的每一時期。"},{"en":"Seedlings and mature plants have different needs.","zh":"幼苗和成熟植物有不同需要。"},{"en":"Careful cultivation protects coffee at every stage.","zh":"細心栽培保護每個階段的咖啡。"},{"en":"The phrase stresses continuous care.","zh":"這個詞組強調持續照顧。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":11},{"front":"sowing","meaning":"播種","examples":[{"en":"Sowing should take place in sheltered nurseries.","zh":"播種應在受保護的苗圃中進行。"},{"en":"Sowing means planting seeds.","zh":"sowing 表示種下種子。"},{"en":"Coffee cultivation begins with sowing seeds in nurseries.","zh":"咖啡栽培始於在苗圃播種。"},{"en":"Proper sowing protects young coffee plants.","zh":"妥善播種可以保護幼小咖啡植物。"},{"en":"The phrase refers to the first planting stage.","zh":"這個詞組指第一個種植階段。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":11},{"front":"sheltered nurseries","meaning":"受保護的苗圃","examples":[{"en":"Coffee seeds should be sown in sheltered nurseries.","zh":"咖啡種子應在受保護的苗圃中播種。"},{"en":"Sheltered nurseries protect young plants from harsh weather.","zh":"受保護的苗圃保護幼小植物免受惡劣天氣影響。"},{"en":"Farmers start coffee seedlings in sheltered nurseries.","zh":"農民在受保護的苗圃培育咖啡幼苗。"},{"en":"The phrase describes protected places for growing young plants.","zh":"這個詞組描述培育幼小植物的保護場所。"},{"en":"It is part of careful cultivation.","zh":"它是細心栽培的一部分。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":11},{"front":"seedlings","meaning":"幼苗","examples":[{"en":"The seedlings are moved to plantations after about six months.","zh":"幼苗約六個月後被移到種植園。"},{"en":"Seedlings are young plants grown from seeds.","zh":"seedlings 是由種子長出的幼小植物。"},{"en":"Coffee seedlings need protection from wind and excessive sunlight.","zh":"咖啡幼苗需要保護，避免受風和過度日照影響。"},{"en":"Seedlings are usually moved during the rainy season.","zh":"幼苗通常在雨季期間移植。"},{"en":"The phrase refers to young coffee plants.","zh":"這個詞組指年幼咖啡植物。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":12},{"front":"be moved to plantations","meaning":"被移到種植園","examples":[{"en":"Seedlings should be moved to plantations during the rainy season.","zh":"幼苗應在雨季期間被移到種植園。"},{"en":"To be moved to plantations means to be transplanted to larger growing fields.","zh":"be moved to plantations 表示被移植到較大的種植田地。"},{"en":"Coffee seedlings are first grown in nurseries, then moved to plantations.","zh":"咖啡幼苗先在苗圃生長，然後被移到種植園。"},{"en":"The timing of moving seedlings is important.","zh":"移植幼苗的時間很重要。"},{"en":"The phrase describes a stage in coffee cultivation.","zh":"這個詞組描述咖啡栽培的一個階段。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":12},{"front":"during the rainy season","meaning":"在雨季期間","examples":[{"en":"Seedlings are moved to plantations during the rainy season.","zh":"幼苗在雨季期間被移到種植園。"},{"en":"During the rainy season, young plants receive more natural water.","zh":"在雨季期間，幼小植物得到更多天然水分。"},{"en":"Farmers choose the rainy season for transplanting coffee seedlings.","zh":"農民選擇雨季移植咖啡幼苗。"},{"en":"The phrase identifies the wet period of the year.","zh":"這個詞組指出一年中的潮濕時期。"},{"en":"It explains the timing of planting.","zh":"它解釋種植時間。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":12},{"front":"be interplanted with","meaning":"與……間種","examples":[{"en":"Coffee seedlings are interplanted with other species.","zh":"咖啡幼苗與其他物種間種。"},{"en":"To be interplanted with other species means to be planted among different plants.","zh":"be interplanted with other species 表示與不同植物一起種植。"},{"en":"Other species protect coffee seedlings from wind and sunlight.","zh":"其他物種保護咖啡幼苗免受風和陽光影響。"},{"en":"Interplanting helps young coffee plants survive.","zh":"間種幫助年幼咖啡植物生存。"},{"en":"The phrase describes mixed planting.","zh":"這個詞組描述混合種植。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":12},{"front":"shield them from","meaning":"保護它們免受……","examples":[{"en":"Other species shield coffee plants from wind and excessive sunlight.","zh":"其他物種保護咖啡植物免受風和過度日照影響。"},{"en":"To shield them from something means to protect them from it.","zh":"shield them from 表示保護它們免受某事傷害。"},{"en":"Shade plants shield seedlings from strong sun.","zh":"遮蔭植物保護幼苗免受強烈陽光影響。"},{"en":"Farmers use interplanting to shield young coffee plants.","zh":"農民使用間種來保護年幼咖啡植物。"},{"en":"The phrase describes protective action.","zh":"這個詞組描述保護行動。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":12},{"front":"excessive sunlight","meaning":"過度日照","examples":[{"en":"Young coffee plants need protection from excessive sunlight.","zh":"年幼咖啡植物需要保護，免受過度日照影響。"},{"en":"Excessive sunlight means too much direct sunlight.","zh":"excessive sunlight 表示過多直接陽光。"},{"en":"Other plants can shield seedlings from excessive sunlight.","zh":"其他植物可以保護幼苗免受過度日照。"},{"en":"Too much sun may damage young coffee plants.","zh":"太多陽光可能損害年幼咖啡植物。"},{"en":"The phrase describes a harmful growing condition.","zh":"這個詞組描述有害生長條件。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":12},{"front":"be relied upon to","meaning":"可以依靠……去","examples":[{"en":"A coffee plant can be relied upon to give a regular yield only when it is five years old.","zh":"咖啡植物只有到五歲時，才可以依靠它提供穩定產量。"},{"en":"To be relied upon to do something means to be depended on to do it.","zh":"be relied upon to do something 表示可被依賴去做某事。"},{"en":"Young coffee plants cannot yet be relied upon to produce regular crops.","zh":"年幼咖啡植物還不能依靠它產出穩定收成。"},{"en":"Farmers wait until mature plants can be relied upon for yield.","zh":"農民等待成熟植物能可靠地提供產量。"},{"en":"The phrase describes dependable performance.","zh":"這個詞組描述可靠表現。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":12},{"front":"regular yield","meaning":"穩定產量","examples":[{"en":"A five-year-old coffee plant can give a regular yield.","zh":"五歲的咖啡植物可以提供穩定產量。"},{"en":"Regular yield means a steady and repeated crop.","zh":"regular yield 表示穩定而反覆的收成。"},{"en":"Farmers value plants that produce a regular yield.","zh":"農民重視能產出穩定產量的植物。"},{"en":"The yield may range from 400 grams to two kilos per plant.","zh":"產量可由每株400克至兩公斤不等。"},{"en":"The phrase refers to predictable harvest output.","zh":"這個詞組指可預測的收成產出。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":12},{"front":"range from…to…","meaning":"介乎……至……","examples":[{"en":"A regular yield ranges from 400 grams to two kilos per plant.","zh":"穩定產量介乎每株400克至兩公斤。"},{"en":"Range from one amount to another means vary between those limits.","zh":"range from one amount to another 表示在兩個限度之間變化。"},{"en":"Coffee bean output can range from small to larger quantities.","zh":"咖啡豆產量可以介乎較少至較多。"},{"en":"The phrase gives a lower and upper boundary.","zh":"這個詞組提供下限和上限。"},{"en":"It is useful for describing yield, height, or temperature.","zh":"它適合描述產量、高度或溫度。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":12},{"front":"arabica beans","meaning":"阿拉比卡咖啡豆","examples":[{"en":"Each plant can produce up to two kilos of arabica beans.","zh":"每株植物可產出多達兩公斤阿拉比卡咖啡豆。"},{"en":"Arabica beans come from Coffea Arabica plants.","zh":"阿拉比卡咖啡豆來自阿拉比卡咖啡植物。"},{"en":"Arabica beans are one of the main types of coffee beans.","zh":"阿拉比卡咖啡豆是主要咖啡豆類型之一。"},{"en":"The passage mentions arabica beans with robusta beans.","zh":"文章把阿拉比卡咖啡豆與羅布斯塔咖啡豆一同提及。"},{"en":"The phrase refers to beans from the Arabica species.","zh":"這個詞組指來自阿拉比卡物種的咖啡豆。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":12},{"front":"robusta beans","meaning":"羅布斯塔咖啡豆","examples":[{"en":"Each plant can produce up to two kilos of robusta beans.","zh":"每株植物可產出多達兩公斤羅布斯塔咖啡豆。"},{"en":"Robusta beans come from Coffea Canephora plants.","zh":"羅布斯塔咖啡豆來自中果咖啡植物。"},{"en":"Robusta beans are one of the two main commercial coffee beans.","zh":"羅布斯塔咖啡豆是兩種主要商業咖啡豆之一。"},{"en":"The passage discusses robusta beans alongside arabica beans.","zh":"文章把羅布斯塔咖啡豆與阿拉比卡咖啡豆一同討論。"},{"en":"The phrase refers to beans from the Robusta species.","zh":"這個詞組指來自羅布斯塔物種的咖啡豆。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":12},{"front":"harvesting time","meaning":"收成時間","examples":[{"en":"Harvesting time depends on geography.","zh":"收成時間取決於地理位置。"},{"en":"Harvesting time is the period when ripe coffee cherries are collected.","zh":"收成時間是成熟咖啡果被採集的時期。"},{"en":"The harvesting time varies among producing countries.","zh":"生產國之間的收成時間不同。"},{"en":"Pickers work during harvesting time to collect ripe beans.","zh":"採摘工人在收成時間收集成熟咖啡豆。"},{"en":"The phrase refers to the crop collection season.","zh":"這個詞組指作物收集季節。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":13},{"front":"depend on geography","meaning":"取決於地理位置","examples":[{"en":"Harvesting time depends on geography.","zh":"收成時間取決於地理位置。"},{"en":"Depend on geography means be influenced by location and local conditions.","zh":"depend on geography 表示受地點和本地條件影響。"},{"en":"Climate and altitude change according to geography.","zh":"氣候和海拔會因地理位置而改變。"},{"en":"Coffee production methods may depend on geography.","zh":"咖啡生產方法可能取決於地理位置。"},{"en":"The phrase connects place with timing or method.","zh":"這個詞組把地點與時間或方法連繫起來。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":13},{"front":"vary greatly among","meaning":"在……之間差異很大","examples":[{"en":"Harvesting time varies greatly among producing countries.","zh":"收成時間在生產國之間差異很大。"},{"en":"To vary greatly among places means to differ a lot between them.","zh":"vary greatly among places 表示不同地方之間差異很大。"},{"en":"Coffee harvest seasons vary greatly among regions.","zh":"咖啡收成季節在不同地區之間差異很大。"},{"en":"Climate differences cause harvest times to vary greatly.","zh":"氣候差異導致收成時間差異很大。"},{"en":"The phrase emphasises large differences.","zh":"這個詞組強調巨大差異。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":13},{"front":"producing countries","meaning":"生產國","examples":[{"en":"Harvesting time varies among producing countries.","zh":"收成時間在生產國之間不同。"},{"en":"Producing countries are countries that grow and export coffee.","zh":"生產國是種植並出口咖啡的國家。"},{"en":"Different producing countries have different climates.","zh":"不同生產國有不同氣候。"},{"en":"Coffee production depends on conditions in producing countries.","zh":"咖啡生產取決於生產國的條件。"},{"en":"The phrase refers to countries involved in producing coffee.","zh":"這個詞組指參與生產咖啡的國家。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":13},{"front":"ripe beans","meaning":"成熟咖啡豆","examples":[{"en":"First, the ripe beans are picked from the branches.","zh":"首先，成熟咖啡豆從樹枝上摘下。"},{"en":"Ripe beans are mature coffee seeds inside coffee cherries.","zh":"成熟咖啡豆是咖啡果內成熟的種子。"},{"en":"Pickers collect ripe beans during harvest.","zh":"採摘工人在收成期間收集成熟咖啡豆。"},{"en":"Only ripe fruit should be selected for better quality.","zh":"為了更好品質，應只選成熟果實。"},{"en":"The phrase refers to mature coffee beans ready for picking.","zh":"這個詞組指準備採摘的成熟咖啡豆。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":13},{"front":"be picked from","meaning":"從……摘下","examples":[{"en":"The ripe beans are picked from the branches.","zh":"成熟咖啡豆從樹枝上摘下。"},{"en":"To be picked from something means to be removed by hand or tool.","zh":"be picked from 表示用手或工具從某處摘下。"},{"en":"Coffee cherries are picked from coffee plants.","zh":"咖啡果從咖啡植物上摘下。"},{"en":"Pickers selectively pick ripe fruit from the branches.","zh":"採摘工人從樹枝上有選擇地摘成熟果實。"},{"en":"The phrase describes harvesting by removal.","zh":"這個詞組描述採收時的摘取動作。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":13},{"front":"pickers","meaning":"採摘工人","examples":[{"en":"Pickers can collect hundreds of pounds of coffee cherries a day.","zh":"採摘工人一天可以收集數百磅咖啡櫻桃。"},{"en":"Pickers are workers who harvest coffee fruit.","zh":"採摘工人是收成咖啡果的工人。"},{"en":"Coffee pickers may selectively pick ripe cherries.","zh":"咖啡採摘工人可能有選擇地摘成熟果實。"},{"en":"At the end of the day, pickers bring bags to pulping mills.","zh":"在一天結束時，採摘工人把袋子帶到去皮加工廠。"},{"en":"The phrase refers to people who collect coffee cherries.","zh":"這個詞組指收集咖啡果的人。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":13},{"front":"selectively pick","meaning":"有選擇地採摘","examples":[{"en":"Pickers can selectively pick coffee cherries from the branches.","zh":"採摘工人可以從樹枝上有選擇地採摘咖啡櫻桃。"},{"en":"To selectively pick means to choose only particular items.","zh":"selectively pick 表示只選取特定物品。"},{"en":"Workers selectively pick ripe cherries to improve quality.","zh":"工人有選擇地採摘成熟咖啡果，以改善品質。"},{"en":"Selective picking takes more care than stripping all fruit.","zh":"有選擇地採摘比一次摘下所有果實更費心。"},{"en":"The phrase describes careful harvesting.","zh":"這個詞組描述細心採收。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":13},{"front":"approximately","meaning":"大約","examples":[{"en":"Pickers can collect approximately 250 to 300 pounds of coffee cherries a day.","zh":"採摘工人一天可以收集大約250至300磅咖啡櫻桃。"},{"en":"Approximately means about or roughly.","zh":"approximately 表示大約或約略。"},{"en":"The number is not exact but gives a close estimate.","zh":"這個數字不是精確值，但提供接近估計。"},{"en":"Approximately 250 pounds is a large amount for one day.","zh":"大約250磅對一天工作來說是很大量。"},{"en":"The phrase is used when giving approximate figures.","zh":"這個詞用於提供約略數字。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":13},{"front":"coffee cherries","meaning":"咖啡櫻桃；咖啡果","examples":[{"en":"Pickers collect coffee cherries and take them to pulping mills.","zh":"採摘工人收集咖啡櫻桃，並把它們送到去皮加工廠。"},{"en":"Coffee cherries are the red fruits of the coffee plant.","zh":"咖啡櫻桃是咖啡植物的紅色果實。"},{"en":"Each coffee cherry contains coffee beans inside.","zh":"每顆咖啡果內都含有咖啡豆。"},{"en":"The cherries are pulped before the beans are dried.","zh":"咖啡果在咖啡豆乾燥前會被去皮去果肉。"},{"en":"The phrase refers to coffee fruit before processing.","zh":"這個詞組指加工前的咖啡果實。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":13},{"front":"at the end of the day","meaning":"在一天結束時","examples":[{"en":"At the end of the day, pickers bring their bags to pulping mills.","zh":"在一天結束時，採摘工人把袋子帶到去皮加工廠。"},{"en":"At the end of the day means when the working day is finished.","zh":"at the end of the day 表示工作日結束時。"},{"en":"The harvested cherries are collected after a day of picking.","zh":"一天採摘後，收成的咖啡果被集中起來。"},{"en":"The phrase gives timing in the production process.","zh":"這個詞組提供生產過程中的時間。"},{"en":"It is also a common expression for the close of daily work.","zh":"它也是描述一天工作結束的常用表達。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":13},{"front":"heavy hessian bags","meaning":"沉重的粗麻袋","examples":[{"en":"Pickers bring heavy hessian bags to pulping mills.","zh":"採摘工人把沉重的粗麻袋帶到去皮加工廠。"},{"en":"Heavy hessian bags are strong sacks made from coarse woven fabric.","zh":"heavy hessian bags 是由粗織布料製成的堅固袋子。"},{"en":"The bags contain harvested coffee cherries.","zh":"這些袋子裝着收成的咖啡櫻桃。"},{"en":"Workers carry heavy hessian bags at the end of the day.","zh":"工人在一天結束時搬運沉重的粗麻袋。"},{"en":"The phrase describes the containers used in harvesting.","zh":"這個詞組描述採收時使用的容器。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":14},{"front":"pulping mills","meaning":"去皮加工廠","examples":[{"en":"Coffee cherries are taken to pulping mills.","zh":"咖啡櫻桃被送到去皮加工廠。"},{"en":"Pulping mills remove the outer fruit flesh from coffee cherries.","zh":"去皮加工廠會去除咖啡果外面的果肉。"},{"en":"Pickers bring their bags to pulping mills after harvesting.","zh":"採摘工人收成後把袋子帶到去皮加工廠。"},{"en":"The beans are pulped or wet milled there.","zh":"咖啡豆在那裏被去皮去果肉或濕法加工。"},{"en":"The phrase refers to processing facilities.","zh":"這個詞組指加工設施。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":14},{"front":"be pulped","meaning":"被去皮去果肉","examples":[{"en":"The coffee cherries can be pulped at the mill.","zh":"咖啡櫻桃可以在加工廠被去皮去果肉。"},{"en":"To be pulped means to have the fruit flesh removed.","zh":"be pulped 表示果肉被去除。"},{"en":"Pulping separates the beans from the surrounding fruit.","zh":"去皮去果肉把咖啡豆與周圍果肉分離。"},{"en":"After being pulped, the beans are covered in rainwater.","zh":"被去皮去果肉後，咖啡豆會浸在雨水中。"},{"en":"The phrase describes an early processing step.","zh":"這個詞組描述早期加工步驟。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":14},{"front":"wet milled","meaning":"濕法加工","examples":[{"en":"The coffee cherries are pulped, or wet milled.","zh":"咖啡櫻桃被去皮去果肉，即濕法加工。"},{"en":"Wet milled means processed using water to remove fruit material.","zh":"wet milled 表示使用水去除果實物質的加工方式。"},{"en":"Wet milling prepares the beans for fermentation and drying.","zh":"濕法加工為咖啡豆發酵和乾燥作準備。"},{"en":"This process is part of coffee production.","zh":"這個過程是咖啡生產的一部分。"},{"en":"The phrase refers to a water-based processing method.","zh":"這個詞組指以水為基礎的加工方法。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":14},{"front":"rest covered in","meaning":"浸泡在……中靜置","examples":[{"en":"The pulped beans rest covered in pure rainwater.","zh":"去皮後的咖啡豆浸泡在純淨雨水中靜置。"},{"en":"Rest covered in means remain lying under a covering of liquid or material.","zh":"rest covered in 表示被液體或物質覆蓋並保持靜置。"},{"en":"The beans rest in water before fermenting overnight.","zh":"咖啡豆在水中靜置，然後發酵一夜。"},{"en":"This stage helps prepare the beans for drying.","zh":"這個階段幫助咖啡豆準備乾燥。"},{"en":"The phrase describes a soaking stage.","zh":"這個詞組描述浸泡階段。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":14},{"front":"pure rainwater","meaning":"純淨雨水","examples":[{"en":"The pulped beans are covered in pure rainwater.","zh":"去皮後的咖啡豆被純淨雨水覆蓋。"},{"en":"Pure rainwater is clean rainwater used in processing.","zh":"純淨雨水是加工中使用的乾淨雨水。"},{"en":"The beans ferment overnight in pure rainwater.","zh":"咖啡豆在純淨雨水中發酵一夜。"},{"en":"Water quality matters during this stage.","zh":"在這個階段，水質很重要。"},{"en":"The phrase describes the liquid used to soak the beans.","zh":"這個詞組描述浸泡咖啡豆所用的液體。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":14},{"front":"ferment overnight","meaning":"發酵一夜","examples":[{"en":"The beans ferment overnight in rainwater.","zh":"咖啡豆在雨水中發酵一夜。"},{"en":"To ferment overnight means to undergo fermentation during the night.","zh":"ferment overnight 表示在夜間進行發酵。"},{"en":"Fermentation helps change the beans before drying.","zh":"發酵在乾燥前幫助改變咖啡豆。"},{"en":"After they ferment overnight, the beans are spread on a drying floor.","zh":"咖啡豆發酵一夜後，會鋪在曬豆場上。"},{"en":"The phrase describes a time-based processing step.","zh":"這個詞組描述一個以時間為基礎的加工步驟。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":14},{"front":"the next day","meaning":"第二天","examples":[{"en":"The next day, the wet beans are spread across the drying floor.","zh":"第二天，濕咖啡豆被鋪在曬豆場上。"},{"en":"The next day means the day after the previous process.","zh":"the next day 表示前一個過程之後的那一天。"},{"en":"After fermenting overnight, the beans are handled the next day.","zh":"發酵一夜後，咖啡豆在第二天被處理。"},{"en":"The phrase marks the next stage in the process.","zh":"這個詞組標示過程中的下一階段。"},{"en":"It helps show the order of coffee production.","zh":"它有助顯示咖啡生產順序。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":14},{"front":"wet beans","meaning":"濕咖啡豆","examples":[{"en":"The wet beans are spread by hand across the drying floor.","zh":"濕咖啡豆被用手鋪在曬豆場上。"},{"en":"Wet beans are beans still covered with moisture after soaking or fermentation.","zh":"濕咖啡豆是浸泡或發酵後仍含水分的咖啡豆。"},{"en":"The wet beans must be dried in the sun.","zh":"濕咖啡豆必須在太陽下曬乾。"},{"en":"Workers spread wet beans carefully to help them dry evenly.","zh":"工人小心鋪開濕咖啡豆，幫助它們均勻乾燥。"},{"en":"The phrase refers to coffee beans before drying.","zh":"這個詞組指乾燥前的咖啡豆。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":14},{"front":"spread by hand","meaning":"用手鋪開","examples":[{"en":"The wet beans are spread by hand.","zh":"濕咖啡豆被用手鋪開。"},{"en":"Spread by hand means placed and distributed manually.","zh":"spread by hand 表示用人手放置並分散。"},{"en":"Workers spread the beans by hand across the drying floor.","zh":"工人用手把咖啡豆鋪在曬豆場上。"},{"en":"This careful spreading helps the beans dry properly.","zh":"這種細心鋪開幫助咖啡豆適當乾燥。"},{"en":"The phrase describes manual labour in coffee production.","zh":"這個詞組描述咖啡生產中的人手勞動。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":14},{"front":"drying floor","meaning":"曬豆場","examples":[{"en":"The wet beans are spread across the drying floor.","zh":"濕咖啡豆被鋪在曬豆場上。"},{"en":"A drying floor is a surface where beans are laid out to dry.","zh":"drying floor 是用來鋪放咖啡豆以乾燥的地面。"},{"en":"Coffee beans are sun-dried on the drying floor.","zh":"咖啡豆在曬豆場上被曬乾。"},{"en":"Workers rake the beans many times on the drying floor.","zh":"工人在曬豆場上多次耙動咖啡豆。"},{"en":"The phrase refers to an area used for drying coffee.","zh":"這個詞組指用於乾燥咖啡的區域。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":14},{"front":"sun-dried","meaning":"曬乾的","examples":[{"en":"The beans are sun-dried after fermentation.","zh":"咖啡豆發酵後被曬乾。"},{"en":"Sun-dried means dried by exposure to sunlight.","zh":"sun-dried 表示透過陽光照射乾燥。"},{"en":"Sun-dried beans later become known as parchment.","zh":"曬乾的咖啡豆後來被稱為 parchment。"},{"en":"The drying time depends on sunny days available.","zh":"乾燥時間取決於可用晴天數目。"},{"en":"The phrase describes natural drying under the sun.","zh":"這個詞組描述在太陽下自然乾燥。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":15},{"front":"drying process","meaning":"乾燥過程","examples":[{"en":"The drying process takes from one to two weeks.","zh":"乾燥過程需時一至兩星期。"},{"en":"The drying process removes moisture from the wet beans.","zh":"乾燥過程去除濕咖啡豆中的水分。"},{"en":"Weather affects the length of the drying process.","zh":"天氣影響乾燥過程的長短。"},{"en":"Beans must be raked during the drying process.","zh":"在乾燥過程中，咖啡豆必須被耙動。"},{"en":"The phrase refers to the stage of drying coffee beans.","zh":"這個詞組指乾燥咖啡豆的階段。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":15},{"front":"depending on","meaning":"取決於","examples":[{"en":"The drying process takes one to two weeks depending on the weather.","zh":"乾燥過程需時一至兩星期，取決於天氣。"},{"en":"Depending on means controlled or influenced by something.","zh":"depending on 表示受某事控制或影響。"},{"en":"Harvesting time varies depending on geography.","zh":"收成時間取決於地理位置。"},{"en":"Drying time changes depending on sunny days available.","zh":"乾燥時間取決於可用晴天數目。"},{"en":"The phrase introduces a condition that affects the result.","zh":"這個詞組引入影響結果的條件。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":15},{"front":"sunny days available","meaning":"可用的晴天數目","examples":[{"en":"The drying time depends on the number of sunny days available.","zh":"乾燥時間取決於可用的晴天數目。"},{"en":"Sunny days available means days with enough sunshine for drying.","zh":"sunny days available 表示有足夠陽光用於乾燥的日子。"},{"en":"More sunny days available can shorten the drying process.","zh":"可用的晴天數目越多，乾燥過程可能越短。"},{"en":"Cloudy weather slows drying.","zh":"多雲天氣會減慢乾燥。"},{"en":"The phrase refers to weather conditions needed for sun-drying.","zh":"這個詞組指曬乾所需的天氣條件。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":15},{"front":"dry evenly","meaning":"均勻乾燥","examples":[{"en":"The beans need to be raked so that they dry evenly.","zh":"咖啡豆需要被耙動，以便均勻乾燥。"},{"en":"To dry evenly means to dry at the same rate on all sides.","zh":"dry evenly 表示所有面以相同速度乾燥。"},{"en":"Uneven drying can affect bean quality.","zh":"乾燥不均可能影響咖啡豆品質。"},{"en":"Workers rake coffee beans to help them dry evenly.","zh":"工人耙動咖啡豆，幫助它們均勻乾燥。"},{"en":"The phrase describes the desired result of raking.","zh":"這個詞組描述耙動想達到的結果。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":15},{"front":"be raked","meaning":"被耙動；被耙平","examples":[{"en":"The beans need to be raked many times.","zh":"咖啡豆需要被多次耙動。"},{"en":"To be raked means to be moved or turned with a rake.","zh":"be raked 表示用耙移動或翻動。"},{"en":"Coffee beans are raked during drying so they dry evenly.","zh":"咖啡豆在乾燥期間被耙動，以便均勻乾燥。"},{"en":"Workers rake the beans repeatedly during this period.","zh":"工人在這段期間反覆耙動咖啡豆。"},{"en":"The phrase describes manual movement of drying beans.","zh":"這個詞組描述乾燥咖啡豆的人手移動。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":15},{"front":"during this period","meaning":"在這段期間","examples":[{"en":"The beans are raked many times during this period.","zh":"咖啡豆在這段期間被多次耙動。"},{"en":"During this period refers to the drying process.","zh":"during this period 指乾燥過程期間。"},{"en":"Workers must monitor the beans during this period.","zh":"工人必須在這段期間監察咖啡豆。"},{"en":"The phrase means throughout this length of time.","zh":"這個詞組表示在這段時間之內。"},{"en":"It connects an action with a stage in the process.","zh":"它把動作與過程階段連繫起來。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":15},{"front":"sun-dried beans","meaning":"曬乾的咖啡豆","examples":[{"en":"The sun-dried beans are now called parchment.","zh":"曬乾的咖啡豆現在被稱為 parchment。"},{"en":"Sun-dried beans are coffee beans dried under sunlight.","zh":"sun-dried beans 是在陽光下乾燥的咖啡豆。"},{"en":"After drying, the beans are scooped up and bagged.","zh":"乾燥後，咖啡豆被收集並裝袋。"},{"en":"Sun-dried beans still need milling before roasting.","zh":"曬乾的咖啡豆在烘焙前仍需研磨加工。"},{"en":"The phrase refers to beans after the drying stage.","zh":"這個詞組指乾燥階段後的咖啡豆。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":15},{"front":"be scooped up","meaning":"被舀起；被收集起來","examples":[{"en":"The sun-dried beans are scooped up and bagged.","zh":"曬乾的咖啡豆被收集起來並裝袋。"},{"en":"To be scooped up means to be gathered or lifted together.","zh":"be scooped up 表示被舀起或集中收集。"},{"en":"Workers scoop up the beans after drying.","zh":"工人在乾燥後收集咖啡豆。"},{"en":"The beans are then placed into bags.","zh":"咖啡豆之後被放進袋子。"},{"en":"The phrase describes collecting dried beans.","zh":"這個詞組描述收集乾豆。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":15},{"front":"bagged","meaning":"被裝袋","examples":[{"en":"The beans are scooped up, bagged and taken to be milled.","zh":"咖啡豆被收集、裝袋，然後送去研磨加工。"},{"en":"Bagged means placed into bags.","zh":"bagged 表示被放進袋子。"},{"en":"After drying, the coffee beans are bagged for transport.","zh":"乾燥後，咖啡豆被裝袋以便運輸。"},{"en":"Bagged beans can be moved to milling machines.","zh":"被裝袋的咖啡豆可以運到研磨機。"},{"en":"The phrase describes a packaging step before milling.","zh":"這個詞組描述研磨前的包裝步驟。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":15},{"front":"be taken to be milled","meaning":"被送去研磨加工","examples":[{"en":"The beans are taken to be milled after drying.","zh":"咖啡豆乾燥後被送去研磨加工。"},{"en":"To be taken to be milled means to be sent for machine processing.","zh":"be taken to be milled 表示被送去作機械加工。"},{"en":"Milling removes parchment and silver skin.","zh":"研磨加工會去除羊皮紙狀外層和銀皮。"},{"en":"After the beans are bagged, they are taken to be milled.","zh":"咖啡豆裝袋後會被送去研磨加工。"},{"en":"The phrase describes transport to the next processing stage.","zh":"這個詞組描述運往下一加工階段。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":15},{"front":"huge milling machines","meaning":"大型研磨機","examples":[{"en":"Huge milling machines remove the parchment and silver skin.","zh":"大型研磨機去除羊皮紙狀外層和銀皮。"},{"en":"Huge milling machines process dried coffee beans.","zh":"大型研磨機加工乾咖啡豆。"},{"en":"These machines prepare green beans for roasting.","zh":"這些機器把生咖啡豆準備好，以便烘焙。"},{"en":"The phrase refers to large industrial machines.","zh":"這個詞組指大型工業機器。"},{"en":"It describes the equipment used after drying.","zh":"它描述乾燥後使用的設備。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":16},{"front":"remove the parchment","meaning":"去除羊皮紙狀外層","examples":[{"en":"Milling machines remove the parchment from the beans.","zh":"研磨機從咖啡豆上去除羊皮紙狀外層。"},{"en":"To remove the parchment means to take off the protective outer layer.","zh":"remove the parchment 表示除去保護性外層。"},{"en":"The parchment must be removed before roasting.","zh":"羊皮紙狀外層必須在烘焙前被去除。"},{"en":"Milling removes both parchment and silver skin.","zh":"研磨加工會去除羊皮紙狀外層和銀皮。"},{"en":"The phrase describes a key milling function.","zh":"這個詞組描述研磨加工的重要功能。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":16},{"front":"silver skin","meaning":"銀皮","examples":[{"en":"The silver skin is removed during milling.","zh":"銀皮在研磨加工中被去除。"},{"en":"Silver skin is the thin silvery film covering the coffee bean.","zh":"銀皮是覆蓋咖啡豆的薄薄銀色薄膜。"},{"en":"It lies beneath the parchment.","zh":"它位於羊皮紙狀外層之下。"},{"en":"Milling removes the silver skin to produce green beans.","zh":"研磨加工會去除銀皮，以產出生咖啡豆。"},{"en":"The phrase refers to a delicate inner covering.","zh":"這個詞組指細薄的內層覆蓋物。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":16},{"front":"green beans","meaning":"生咖啡豆","examples":[{"en":"Milling produces green beans suitable for roasting.","zh":"研磨加工產生適合烘焙的生咖啡豆。"},{"en":"Green beans are unroasted coffee beans.","zh":"生咖啡豆是未經烘焙的咖啡豆。"},{"en":"Green beans are packaged or roasted according to customers’ needs.","zh":"生咖啡豆會按客戶需要包裝或烘焙。"},{"en":"The beans are called green before roasting changes their colour.","zh":"烘焙改變顏色前，咖啡豆被稱為生豆。"},{"en":"The phrase refers to coffee beans ready for roasting.","zh":"這個詞組指準備烘焙的咖啡豆。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":16},{"front":"suitable for roasting","meaning":"適合烘焙","examples":[{"en":"The green beans are suitable for roasting.","zh":"生咖啡豆適合烘焙。"},{"en":"Suitable for roasting means ready to be roasted.","zh":"suitable for roasting 表示準備好被烘焙。"},{"en":"Milling prepares the beans so they are suitable for roasting.","zh":"研磨加工使咖啡豆適合烘焙。"},{"en":"Beans unsuitable for roasting may produce poor coffee.","zh":"不適合烘焙的咖啡豆可能製成品質差的咖啡。"},{"en":"The phrase describes readiness for the next process.","zh":"這個詞組描述進入下一工序的準備狀態。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":16},{"front":"according to customers’ specifications","meaning":"按照客戶規格","examples":[{"en":"The green beans are roasted according to customers’ specifications.","zh":"生咖啡豆按照客戶規格被烘焙。"},{"en":"Customers’ specifications are the particular requirements requested by buyers.","zh":"客戶規格是買家要求的特定要求。"},{"en":"Roasting can vary according to customers’ specifications.","zh":"烘焙方式可以按照客戶規格而不同。"},{"en":"Some customers may want darker or lighter roasted beans.","zh":"一些客戶可能想要較深或較淺烘焙的豆。"},{"en":"The phrase means following the customer’s exact requirements.","zh":"這個詞組表示遵照客戶的確切要求。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":16},{"front":"after cooling","meaning":"冷卻後","examples":[{"en":"After cooling, the beans are packaged and sent to customers.","zh":"冷卻後，咖啡豆被包裝並送到客戶手上。"},{"en":"After cooling means once the roasted beans have cooled down.","zh":"after cooling 表示烘焙後咖啡豆降溫之後。"},{"en":"Beans must cool before packaging.","zh":"咖啡豆必須冷卻後才能包裝。"},{"en":"The phrase marks the final stage after roasting.","zh":"這個詞組標示烘焙後的最後階段。"},{"en":"It describes timing in the production process.","zh":"它描述生產過程中的時間。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":16},{"front":"be packaged","meaning":"被包裝","examples":[{"en":"The roasted beans are packaged after cooling.","zh":"烘焙咖啡豆冷卻後被包裝。"},{"en":"To be packaged means to be put into containers for sale or transport.","zh":"be packaged 表示被放入容器，以供出售或運輸。"},{"en":"Packaged beans are then sent to customers.","zh":"被包裝的咖啡豆之後送到客戶手上。"},{"en":"Packaging protects roasted coffee beans.","zh":"包裝可以保護烘焙咖啡豆。"},{"en":"The phrase describes the final preparation step.","zh":"這個詞組描述最後準備步驟。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":16},{"front":"be sent to customers","meaning":"被送到客戶手上","examples":[{"en":"The packaged beans are sent to customers.","zh":"包裝好的咖啡豆被送到客戶手上。"},{"en":"To be sent to customers means to be delivered to buyers.","zh":"be sent to customers 表示被交付給買家。"},{"en":"After cooling and packaging, coffee beans are sent to customers.","zh":"冷卻和包裝後，咖啡豆被送到客戶手上。"},{"en":"This is the final step in the described production process.","zh":"這是所描述生產過程的最後一步。"},{"en":"The phrase describes distribution.","zh":"這個詞組描述配送。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":16},{"front":"the reading passage","meaning":"閱讀篇章","examples":[{"en":"The reading passage has seven paragraphs.","zh":"閱讀篇章有七個段落。"},{"en":"The reading passage explains coffee’s history and production.","zh":"閱讀篇章解釋咖啡的歷史和生產。"},{"en":"Students answer questions based on the reading passage.","zh":"學生根據閱讀篇章回答問題。"},{"en":"The phrase refers to the text used in the reading task.","zh":"這個詞組指閱讀題所使用的文本。"},{"en":"It is common in exam instructions.","zh":"它常見於考試指示。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":16},{"front":"the most suitable headings","meaning":"最合適的標題","examples":[{"en":"Students choose the most suitable headings for the paragraphs.","zh":"學生為各段選出最合適的標題。"},{"en":"The most suitable headings best summarise each paragraph.","zh":"最合適的標題最能概括每一段。"},{"en":"A heading about discovery fits the paragraph about Kaldi.","zh":"關於發現的標題適合講 Kaldi 的段落。"},{"en":"Students must compare all headings with paragraph content.","zh":"學生必須把所有標題與段落內容比較。"},{"en":"The phrase refers to the best matching titles.","zh":"這個詞組指最匹配的標題。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":16},{"front":"appropriate number","meaning":"適當編號","examples":[{"en":"Students write the appropriate number in the answer box.","zh":"學生在答案格中寫上適當編號。"},{"en":"The appropriate number corresponds to the correct heading.","zh":"適當編號對應正確標題。"},{"en":"Choosing the wrong number gives the wrong answer.","zh":"選錯編號會令答案錯誤。"},{"en":"The phrase refers to the required answer format.","zh":"這個詞組指所需答案格式。"},{"en":"It is used in heading-matching questions.","zh":"它用於標題配對題。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":17},{"front":"more headings than paragraphs","meaning":"標題數目多於段落數目","examples":[{"en":"There are more headings than paragraphs.","zh":"標題數目多於段落數目。"},{"en":"More headings than paragraphs means some options will not be used.","zh":"more headings than paragraphs 表示一些選項不會被使用。"},{"en":"Students must choose carefully because extra headings are included.","zh":"因為有額外標題，學生必須小心選擇。"},{"en":"The phrase describes the structure of the matching task.","zh":"這個詞組描述配對題的結構。"},{"en":"It warns students not to expect every heading to be used.","zh":"它提醒學生不要以為每個標題都會用上。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":17},{"front":"you will not use them all","meaning":"不會全部使用","examples":[{"en":"Students will not use all the headings.","zh":"學生不會全部使用所有標題。"},{"en":"You will not use them all means some choices are unnecessary.","zh":"you will not use them all 表示有些選項不需要用。"},{"en":"Extra headings are included to test careful reading.","zh":"額外標題用來測試仔細閱讀。"},{"en":"Students should not force every heading into an answer.","zh":"學生不應硬把每個標題都用上。"},{"en":"The phrase is an exam instruction.","zh":"這個詞組是考試指示。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":17},{"front":"problems with production","meaning":"生產問題","examples":[{"en":"One heading refers to problems with production.","zh":"一個標題提到生產問題。"},{"en":"Problems with production may involve climate, soil, or processing difficulties.","zh":"生產問題可能涉及氣候、土壤或加工困難。"},{"en":"Students should check whether a paragraph actually discusses production problems.","zh":"學生應檢查某段是否真的討論生產問題。"},{"en":"The phrase describes difficulties in making or growing a product.","zh":"這個詞組描述製造或種植產品時的困難。"},{"en":"It is one possible heading in the task.","zh":"它是題目中的一個可能標題。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":17},{"front":"processing the bean","meaning":"加工咖啡豆","examples":[{"en":"The final paragraph describes processing the bean.","zh":"最後一段描述加工咖啡豆。"},{"en":"Processing the bean includes pulping, fermenting, drying, milling, and roasting.","zh":"加工咖啡豆包括去皮、發酵、乾燥、研磨和烘焙。"},{"en":"Coffee processing changes cherries into beans ready for customers.","zh":"咖啡加工把咖啡櫻桃變成可供客戶使用的咖啡豆。"},{"en":"The phrase refers to preparing the coffee bean after harvest.","zh":"這個詞組指收成後準備咖啡豆。"},{"en":"It is a suitable heading for the production-process paragraph.","zh":"它適合作為生產過程段落的標題。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":17},{"front":"the first discovery","meaning":"首次發現","examples":[{"en":"The first discovery of coffee is described through a legend.","zh":"咖啡的首次發現透過一個傳說描述。"},{"en":"The first discovery involved a goat herder and energetic goats.","zh":"首次發現涉及一位牧山羊人和精力充沛的山羊。"},{"en":"The phrase refers to the earliest finding of coffee’s effects.","zh":"這個詞組指最早發現咖啡效果。"},{"en":"Kaldi’s story explains the first discovery in a memorable way.","zh":"Kaldi 的故事以令人難忘的方式解釋首次發現。"},{"en":"It is a possible heading for the opening historical paragraph.","zh":"它可作為開首歷史段落的標題。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":17},{"front":"coffee varieties","meaning":"咖啡品種","examples":[{"en":"The passage describes different coffee varieties.","zh":"文章描述不同咖啡品種。"},{"en":"Coffee varieties include Arabica, Robusta, and many subspecies.","zh":"咖啡品種包括阿拉比卡、羅布斯塔和許多亞種。"},{"en":"Ecological differences help produce different coffee varieties.","zh":"生態差異幫助產生不同咖啡品種。"},{"en":"The phrase refers to different types of coffee plants or beans.","zh":"這個詞組指不同類型的咖啡植物或咖啡豆。"},{"en":"It is a suitable heading for the paragraph about species.","zh":"它適合作為關於物種段落的標題。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":17},{"front":"modern coffee","meaning":"現代咖啡","examples":[{"en":"The heading refers to modern coffee.","zh":"這個標題指現代咖啡。"},{"en":"Modern coffee is produced through organised cultivation and processing.","zh":"現代咖啡透過有組織的栽培和加工生產。"},{"en":"The beverage we enjoy today developed from crude early coffee.","zh":"我們今天享用的飲品由原始早期咖啡發展而來。"},{"en":"Modern coffee can be roasted according to customers’ specifications.","zh":"現代咖啡可以按照客戶規格烘焙。"},{"en":"The phrase contrasts present-day coffee with its early forms.","zh":"這個詞組把今天的咖啡與早期形式作對比。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":17},{"front":"the spread of coffee","meaning":"咖啡的傳播","examples":[{"en":"The passage explains the spread of coffee from Ethiopia to Europe.","zh":"文章解釋咖啡從埃塞俄比亞到歐洲的傳播。"},{"en":"The spread of coffee involved Arabia, Turkey, and Venetian merchants.","zh":"咖啡的傳播涉及阿拉伯、土耳其和威尼斯商人。"},{"en":"Coffeehouses helped continue the spread of coffee in Europe.","zh":"咖啡館幫助咖啡在歐洲繼續傳播。"},{"en":"The phrase refers to coffee moving across regions and cultures.","zh":"這個詞組指咖啡跨地區和文化移動。"},{"en":"It is a suitable heading for the paragraph about coffee’s journey.","zh":"它適合作為咖啡旅程段落的標題。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":17},{"front":"consuming coffee","meaning":"飲用或食用咖啡","examples":[{"en":"The passage describes early ways of consuming coffee.","zh":"文章描述早期飲用或食用咖啡的方式。"},{"en":"Consuming coffee first meant eating it as food.","zh":"最初飲用或食用咖啡是把它當作食物。"},{"en":"Later, people consumed coffee by boiling the beans.","zh":"後來，人們透過煮咖啡豆來飲用咖啡。"},{"en":"Coffee consumption changed after roasting was discovered.","zh":"烘焙被發現後，咖啡消費方式改變了。"},{"en":"The phrase refers to eating or drinking coffee.","zh":"這個詞組指食用或飲用咖啡。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":17},{"front":"suitable climates for coffee","meaning":"適合咖啡生長的氣候","examples":[{"en":"The passage explains suitable climates for coffee cultivation.","zh":"文章解釋適合咖啡栽培的氣候。"},{"en":"Suitable climates for coffee may be hot and wet or warm and temperate.","zh":"適合咖啡生長的氣候可能是炎熱潮濕或溫暖溫和。"},{"en":"Coffee grows best between the two tropics with frequent rains.","zh":"咖啡在兩條回歸線之間、且有頻繁降雨的地方生長最佳。"},{"en":"Temperature, rainfall, and altitude all matter.","zh":"溫度、降雨和海拔都很重要。"},{"en":"The phrase refers to environmental conditions needed by coffee plants.","zh":"這個詞組指咖啡植物所需的環境條件。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":17},{"front":"the coffee plant","meaning":"咖啡植物","examples":[{"en":"The passage describes the structure of the coffee plant and bean.","zh":"文章描述咖啡植物和咖啡豆的結構。"},{"en":"The coffee plant has white flowers and red berries.","zh":"咖啡植物有白色花朵和紅色漿果。"},{"en":"Coffee beans are the seeds inside the coffee plant’s fruit.","zh":"咖啡豆是咖啡植物果實內的種子。"},{"en":"The phrase refers to the plant that produces coffee.","zh":"這個詞組指生產咖啡的植物。"},{"en":"It is a suitable heading for the paragraph about plant structure.","zh":"它適合作為關於植物結構段落的標題。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":18},{"front":"complete the labels on","meaning":"完成……上的標籤","examples":[{"en":"Students complete the labels on the diagram of a coffee bean.","zh":"學生完成咖啡豆圖表上的標籤。"},{"en":"To complete the labels on a diagram means to fill in the missing names.","zh":"complete the labels on a diagram 表示填上圖表中缺少的名稱。"},{"en":"Students may label parts such as epicarp, mesocarp, or endocarp.","zh":"學生可能要標示外果皮、中果皮或內果皮等部分。"},{"en":"The phrase describes a diagram-labelling task.","zh":"這個詞組描述圖表標籤題。"},{"en":"It asks students to use information from the passage.","zh":"它要求學生使用文章中的資料。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":18},{"front":"diagram of a coffee bean","meaning":"咖啡豆圖表","examples":[{"en":"The question includes a diagram of a coffee bean.","zh":"題目包括一個咖啡豆圖表。"},{"en":"A diagram of a coffee bean may show layers such as epicarp and endocarp.","zh":"咖啡豆圖表可能顯示外果皮和內果皮等層次。"},{"en":"Students use the passage to label the diagram.","zh":"學生使用文章來標示圖表。"},{"en":"The diagram helps visualise the structure of the bean.","zh":"圖表幫助理解咖啡豆結構。"},{"en":"The phrase refers to a labelled picture or illustration.","zh":"這個詞組指有標籤的圖片或插圖。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":18},{"front":"choose your answers from","meaning":"從……選出答案","examples":[{"en":"Students choose their answers from the passage.","zh":"學生從文章中選出答案。"},{"en":"Choose your answers from means select words from a given source.","zh":"choose your answers from 表示從指定來源選取字詞。"},{"en":"Students should not invent answers outside the passage.","zh":"學生不應在文章外自創答案。"},{"en":"The phrase tells candidates where the answers must come from.","zh":"這個詞組告訴考生答案必須來自哪裏。"},{"en":"It is common in reading tasks.","zh":"它常見於閱讀題。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":18},{"front":"using the information in","meaning":"使用……中的資料","examples":[{"en":"Students complete the flowchart using the information in the passage.","zh":"學生使用文章中的資料完成流程圖。"},{"en":"Using the information in the passage means relying on the text’s details.","zh":"using the information in the passage 表示依靠文本細節。"},{"en":"Students must use the passage rather than general knowledge.","zh":"學生必須使用文章，而不是一般知識。"},{"en":"The phrase explains the basis for completing the task.","zh":"這個詞組解釋完成題目的依據。"},{"en":"It is often used in summary or flowchart questions.","zh":"它常用於摘要或流程圖題。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":18},{"front":"complete the flowchart","meaning":"完成流程圖","examples":[{"en":"Students complete the flowchart about coffee production.","zh":"學生完成關於咖啡生產的流程圖。"},{"en":"To complete the flowchart means to fill in missing stages or words.","zh":"complete the flowchart 表示填入缺少的階段或字詞。"},{"en":"The flowchart summarises the coffee production process.","zh":"流程圖概括咖啡生產過程。"},{"en":"Students must follow the order of events in the passage.","zh":"學生必須按照文章中的事件順序。"},{"en":"The phrase describes an exam task.","zh":"這個詞組描述考試題型。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":18},{"front":"no more than three words","meaning":"不多於三個字","examples":[{"en":"Students should choose no more than three words from the passage.","zh":"學生應從文章中選擇不多於三個字。"},{"en":"No more than three words means one, two, or three words only.","zh":"no more than three words 表示只可用一、二或三個詞。"},{"en":"The answer must not exceed the word limit.","zh":"答案不可超過字數限制。"},{"en":"Students should copy concise words from the passage.","zh":"學生應從文章中抄寫簡潔字詞。"},{"en":"The phrase gives a strict answer limit.","zh":"這個詞組提供嚴格答案限制。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":18},{"front":"coffee production process","meaning":"咖啡生產過程","examples":[{"en":"The flowchart summarises the coffee production process.","zh":"流程圖概括咖啡生產過程。"},{"en":"The coffee production process begins with picking ripe coffee cherries.","zh":"咖啡生產過程始於採摘成熟咖啡櫻桃。"},{"en":"It includes pulping, fermenting, drying, milling, roasting, and packaging.","zh":"它包括去皮、發酵、乾燥、研磨、烘焙和包裝。"},{"en":"Understanding the coffee production process helps explain modern coffee.","zh":"理解咖啡生產過程有助解釋現代咖啡。"},{"en":"The phrase refers to all stages from harvest to finished beans.","zh":"這個詞組指從收成到成品咖啡豆的所有階段。"}],"source":"Passage 2 Flash Cards 171 - Coffee then and now (History of coffee).pdf","sourcePage":18}],"ielts/reading/passage-2/Practice 172":[{"front":"chinstrap penguin","meaning":"帽帶企鵝","examples":[{"en":"A chinstrap penguin waddled across the icy beach.","zh":"一隻帽帶企鵝搖搖擺擺地走過冰冷海灘。"},{"en":"The chinstrap penguin is easy to recognise because of its dark “strap”.","zh":"帽帶企鵝因為深色「帽帶」而容易辨認。"},{"en":"Scientists counted each chinstrap penguin nest on the island.","zh":"科學家點算島上每個帽帶企鵝巢穴。"},{"en":"A chinstrap penguin can travel far to find food.","zh":"帽帶企鵝可以走很遠尋找食物。"},{"en":"The documentary followed a chinstrap penguin through the breeding season.","zh":"該紀錄片跟隨一隻帽帶企鵝度過繁殖季。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":1},{"front":"in the last 50 years","meaning":"在過去50年","examples":[{"en":"The coastline has changed greatly in the last 50 years.","zh":"海岸線在過去50年大幅改變。"},{"en":"Penguin numbers have fallen in the last 50 years.","zh":"企鵝數量在過去50年下降。"},{"en":"Scientific equipment has improved in the last 50 years.","zh":"科學設備在過去50年有所改善。"},{"en":"The island’s climate has become warmer in the last 50 years.","zh":"該島氣候在過去50年變暖。"},{"en":"Researchers have collected more accurate data in the last 50 years.","zh":"研究人員在過去50年收集了更準確數據。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":1},{"front":"a cap of black plumage","meaning":"一片黑色羽毛冠","examples":[{"en":"The bird had a cap of black plumage on its head.","zh":"那隻鳥頭上有一片黑色羽毛冠。"},{"en":"A cap of black plumage made the penguin look as if it wore a hat.","zh":"一片黑色羽毛冠令企鵝看起來像戴着帽子。"},{"en":"The guide pointed out the cap of black plumage to visitors.","zh":"導賞員向遊客指出那片黑色羽毛冠。"},{"en":"A cap of black plumage contrasts strongly with the penguin’s pale face.","zh":"一片黑色羽毛冠與企鵝淺色面部形成強烈對比。"},{"en":"Young students drew a penguin with a cap of black plumage.","zh":"年輕學生畫了一隻有黑色羽毛冠的企鵝。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":1},{"front":"plumage","meaning":"鳥類羽毛","examples":[{"en":"The penguin’s plumage looked smooth after it left the water.","zh":"企鵝離開水面後，羽毛看起來很平滑。"},{"en":"Birds rely on plumage for warmth and protection.","zh":"鳥類依靠羽毛保暖和保護身體。"},{"en":"The scientist photographed the penguin’s plumage from several angles.","zh":"科學家從多個角度拍攝企鵝羽毛。"},{"en":"Dirty plumage can make it harder for seabirds to stay warm.","zh":"羽毛骯髒會令海鳥較難保暖。"},{"en":"The chick’s plumage changed as it grew older.","zh":"雛鳥長大時，羽毛也會改變。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":1},{"front":"a white face","meaning":"白色面部","examples":[{"en":"The penguin’s white face stood out against the dark rocks.","zh":"企鵝的白色面部在深色岩石前很突出。"},{"en":"A white face helps distinguish the bird from darker species.","zh":"白色面部有助把這種鳥與較深色物種區分開。"},{"en":"The chick did not yet have the adult’s white face.","zh":"雛鳥尚未有成年企鵝的白色面部。"},{"en":"Tourists noticed the penguin’s white face first.","zh":"遊客最先注意到企鵝的白色面部。"},{"en":"The drawing showed a black head and a white face.","zh":"圖畫展示黑色頭部和白色面部。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":1},{"front":"a continuous band of","meaning":"一條連續的……帶","examples":[{"en":"A continuous band of cloud stretched across the sky.","zh":"一條連續的雲帶橫跨天空。"},{"en":"The bird has a continuous band of dark feathers under its head.","zh":"這種鳥頭部下方有一條連續的深色羽毛帶。"},{"en":"A continuous band of ice blocked the ship’s path.","zh":"一條連續的冰帶阻擋了船的路線。"},{"en":"Researchers followed a continuous band of footprints across the snow.","zh":"研究人員沿着雪地上一條連續的足跡帶前進。"},{"en":"The map showed a continuous band of protected coastline.","zh":"地圖顯示一條連續的受保護海岸帶。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":1},{"front":"black feathers","meaning":"黑色羽毛","examples":[{"en":"Black feathers framed the penguin’s face.","zh":"黑色羽毛圍住企鵝的面部。"},{"en":"The bird’s black feathers absorbed warmth from the weak sun.","zh":"那隻鳥的黑色羽毛吸收微弱陽光的熱力。"},{"en":"A few black feathers floated on the snow.","zh":"幾根黑色羽毛漂浮在雪上。"},{"en":"The chick slowly developed black feathers on its head.","zh":"雛鳥頭上慢慢長出黑色羽毛。"},{"en":"Researchers used the pattern of black feathers to identify the species.","zh":"研究人員利用黑色羽毛的圖案辨認物種。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":1},{"front":"extend from one side to the other","meaning":"從一邊延伸至另一邊","examples":[{"en":"The dark line seemed to extend from one side to the other.","zh":"那條深色線似乎從一邊延伸至另一邊。"},{"en":"A bridge will extend from one side of the bay to the other.","zh":"一座橋將從海灣一邊延伸至另一邊。"},{"en":"The crack extended from one side of the ice sheet to the other.","zh":"裂縫從冰蓋一邊延伸至另一邊。"},{"en":"The band of feathers extends from one side of the penguin’s head to the other.","zh":"那條羽毛帶從企鵝頭部一邊延伸至另一邊。"},{"en":"The survey area extended from one side of the island to the other.","zh":"調查區域從島的一邊延伸至另一邊。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":1},{"front":"the Antarctic Peninsula","meaning":"南極半島","examples":[{"en":"The team travelled near the Antarctic Peninsula to study penguins.","zh":"團隊前往南極半島附近研究企鵝。"},{"en":"The Antarctic Peninsula is one of the fastest-warming parts of Antarctica.","zh":"南極半島是南極洲變暖最快的地區之一。"},{"en":"Several penguin species breed around the Antarctic Peninsula.","zh":"幾種企鵝在南極半島周圍繁殖。"},{"en":"The ship sailed along the coast of the Antarctic Peninsula.","zh":"船沿着南極半島海岸航行。"},{"en":"Climate records from the Antarctic Peninsula show major changes.","zh":"來自南極半島的氣候紀錄顯示重大變化。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":1},{"front":"subantarctic islands","meaning":"亞南極島嶼","examples":[{"en":"Some seabirds breed on subantarctic islands.","zh":"一些海鳥在亞南極島嶼繁殖。"},{"en":"The expedition stopped near several subantarctic islands.","zh":"考察隊停靠在幾個亞南極島嶼附近。"},{"en":"Subantarctic islands can be important habitats for penguins.","zh":"亞南極島嶼可以是企鵝的重要棲息地。"},{"en":"Weather on subantarctic islands can change very quickly.","zh":"亞南極島嶼的天氣可以變化很快。"},{"en":"Researchers compared colonies on Antarctic and subantarctic islands.","zh":"研究人員比較南極和亞南極島嶼上的群落。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":1},{"front":"uninhabited islands","meaning":"無人居住的島嶼","examples":[{"en":"The researchers landed on several uninhabited islands.","zh":"研究人員登上幾個無人居住的島嶼。"},{"en":"Uninhabited islands may still support rich wildlife.","zh":"無人居住的島嶼仍可能支持豐富野生動物。"},{"en":"Penguins often breed safely on uninhabited islands.","zh":"企鵝常在無人居住的島嶼上安全繁殖。"},{"en":"The map marked remote uninhabited islands in the Southern Ocean.","zh":"地圖標出南大洋中偏遠無人居住的島嶼。"},{"en":"Scientific teams need special permission to visit some uninhabited islands.","zh":"科學團隊需要特別許可才能到訪一些無人居住的島嶼。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":1},{"front":"habitats of the species","meaning":"該物種的棲息地","examples":[{"en":"The islands are important habitats of the species.","zh":"這些島嶼是該物種的重要棲息地。"},{"en":"Climate change may alter the habitats of the species.","zh":"氣候變化可能改變該物種的棲息地。"},{"en":"Researchers mapped the main habitats of the species.","zh":"研究人員繪製該物種主要棲息地的地圖。"},{"en":"Protecting the habitats of the species is essential for conservation.","zh":"保護該物種的棲息地對保育至關重要。"},{"en":"The report compared old and new habitats of the species.","zh":"報告比較了該物種的新舊棲息地。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":1},{"front":"Antarctic penguin colonies","meaning":"南極企鵝群落","examples":[{"en":"Antarctic penguin colonies are sensitive to changes in sea ice.","zh":"南極企鵝群落對海冰變化很敏感。"},{"en":"Scientists monitor Antarctic penguin colonies every breeding season.","zh":"科學家每個繁殖季都監察南極企鵝群落。"},{"en":"Some Antarctic penguin colonies have become smaller.","zh":"一些南極企鵝群落變小了。"},{"en":"Drone images helped researchers count Antarctic penguin colonies.","zh":"無人機影像幫助研究人員點算南極企鵝群落。"},{"en":"Protecting Antarctic penguin colonies requires international cooperation.","zh":"保護南極企鵝群落需要國際合作。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":1},{"front":"in some parts of","meaning":"在……某些地區","examples":[{"en":"Penguin numbers have declined in some parts of Antarctica.","zh":"企鵝數量在南極洲某些地區下降。"},{"en":"Sea ice remains stable in some parts of the region.","zh":"海冰在該地區某些部分仍然穩定。"},{"en":"Krill abundance has changed in some parts of the Southern Ocean.","zh":"磷蝦數量在南大洋某些地區發生變化。"},{"en":"Tourism is restricted in some parts of the islands.","zh":"旅遊在這些島嶼某些地區受到限制。"},{"en":"Scientists found stronger warming in some parts of the peninsula.","zh":"科學家在半島某些地區發現更強烈暖化。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":2},{"front":"decline during","meaning":"在……期間下降","examples":[{"en":"Penguin numbers may decline during years with poor food supply.","zh":"食物供應不足的年份，企鵝數量可能下降。"},{"en":"Sea ice can decline during unusually warm seasons.","zh":"海冰可能在異常溫暖季節期間下降。"},{"en":"The population began to decline during the late twentieth century.","zh":"種群在二十世紀後期開始下降。"},{"en":"Breeding success may decline during severe storms.","zh":"繁殖成功率可能在嚴重風暴期間下降。"},{"en":"Krill numbers can decline during periods of ocean warming.","zh":"磷蝦數量可能在海洋變暖期間下降。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":2},{"front":"mostly because of","meaning":"主要因為","examples":[{"en":"The colony shrank mostly because of food shortages.","zh":"該群落縮小主要因為食物短缺。"},{"en":"The survey was delayed mostly because of bad weather.","zh":"調查延遲主要因為惡劣天氣。"},{"en":"The birds moved mostly because of changing ice conditions.","zh":"鳥類遷移主要因為冰況改變。"},{"en":"The population fell mostly because of environmental pressure.","zh":"種群下降主要因為環境壓力。"},{"en":"The route changed mostly because of dangerous sea ice.","zh":"路線改變主要因為危險海冰。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":2},{"front":"climate change","meaning":"氣候變化","examples":[{"en":"Climate change is altering Antarctic ecosystems.","zh":"氣候變化正在改變南極生態系統。"},{"en":"Many seabirds are affected by climate change.","zh":"許多海鳥受到氣候變化影響。"},{"en":"Climate change can reduce sea ice and food supply.","zh":"氣候變化可以減少海冰和食物供應。"},{"en":"The report linked penguin decline to climate change.","zh":"報告把企鵝下降與氣候變化連繫起來。"},{"en":"Climate change is a major concern for marine scientists.","zh":"氣候變化是海洋科學家的主要關注。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":2},{"front":"populations in colonies of","meaning":"……群落中的種群數量","examples":[{"en":"Scientists measured populations in colonies of chinstrap penguins.","zh":"科學家量度帽帶企鵝群落中的種群數量。"},{"en":"Populations in colonies of seabirds can change quickly.","zh":"海鳥群落中的種群數量可以快速改變。"},{"en":"The study compared populations in colonies of different penguin species.","zh":"該研究比較不同企鵝物種群落中的種群數量。"},{"en":"Drone surveys helped estimate populations in colonies of remote birds.","zh":"無人機調查幫助估算偏遠鳥類群落中的種群數量。"},{"en":"Populations in colonies of penguins reflect wider environmental conditions.","zh":"企鵝群落中的種群數量反映更廣泛環境狀況。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":2},{"front":"also known as","meaning":"亦稱為","examples":[{"en":"Chinstrap penguins are also known as bearded penguins.","zh":"帽帶企鵝亦稱為鬍鬚企鵝。"},{"en":"Krill are also known as a key food source for many marine animals.","zh":"磷蝦亦稱為許多海洋動物的重要食物來源。"},{"en":"The island is also known as an important breeding site.","zh":"該島亦稱為重要繁殖地。"},{"en":"The species is also known as a strong swimmer.","zh":"該物種亦稱為強壯游泳者。"},{"en":"The research vessel is also known as a floating laboratory.","zh":"該研究船亦稱為浮動實驗室。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":2},{"front":"ringed penguins","meaning":"環紋企鵝","examples":[{"en":"Ringed penguins are another name for chinstrap penguins.","zh":"環紋企鵝是帽帶企鵝的另一名稱。"},{"en":"Some older field guides use the name ringed penguins.","zh":"一些較舊野外指南使用環紋企鵝這個名稱。"},{"en":"Visitors confused ringed penguins with another species.","zh":"遊客把環紋企鵝與另一物種混淆。"},{"en":"The dark facial line gives ringed penguins their name.","zh":"深色面部線條令牠們得名環紋企鵝。"},{"en":"The lecture explained why they are sometimes called ringed penguins.","zh":"講座解釋牠們為何有時被稱為環紋企鵝。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":2},{"front":"bearded penguins","meaning":"鬍鬚企鵝","examples":[{"en":"Bearded penguins are named for the dark line under the face.","zh":"鬍鬚企鵝因面部下方深色線條而得名。"},{"en":"Some researchers refer to chinstrap penguins as bearded penguins.","zh":"一些研究人員把帽帶企鵝稱為鬍鬚企鵝。"},{"en":"Bearded penguins breed on rocky Antarctic islands.","zh":"鬍鬚企鵝在南極岩石島嶼上繁殖。"},{"en":"The children laughed at the name bearded penguins.","zh":"孩子們聽到鬍鬚企鵝這個名稱時笑了。"},{"en":"Bearded penguins are easy to identify in photographs.","zh":"鬍鬚企鵝在照片中容易辨認。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":2},{"front":"decline dramatically","meaning":"急劇下降","examples":[{"en":"The colony began to decline dramatically after several warm years.","zh":"幾個暖年後，該群落開始急劇下降。"},{"en":"Krill numbers may decline dramatically when sea ice disappears.","zh":"海冰消失時，磷蝦數量可能急劇下降。"},{"en":"If breeding fails repeatedly, penguin populations can decline dramatically.","zh":"如果繁殖反覆失敗，企鵝種群可能急劇下降。"},{"en":"The survey showed that numbers had declined dramatically.","zh":"調查顯示數量已急劇下降。"},{"en":"Conservationists worry when any species starts to decline dramatically.","zh":"任何物種開始急劇下降時，保育人士都會擔憂。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":2},{"front":"since they were last surveyed","meaning":"自上次被調查以來","examples":[{"en":"The colonies have changed since they were last surveyed.","zh":"自上次被調查以來，這些群落已改變。"},{"en":"Numbers have fallen sharply since they were last surveyed.","zh":"自上次被調查以來，數量大幅下降。"},{"en":"Scientists returned to the island decades after the birds were last surveyed.","zh":"科學家在鳥類上次被調查數十年後重返該島。"},{"en":"Conditions have become warmer since they were last surveyed.","zh":"自上次被調查以來，環境變得更暖。"},{"en":"The researchers compared new figures with data from when they were last surveyed.","zh":"研究人員把新數字與上次被調查時的數據比較。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":2},{"front":"almost 50 years ago","meaning":"近50年前","examples":[{"en":"The first survey was carried out almost 50 years ago.","zh":"第一次調查在近50年前進行。"},{"en":"The old photographs were taken almost 50 years ago.","zh":"舊照片是在近50年前拍攝的。"},{"en":"Scientists compared today’s data with records from almost 50 years ago.","zh":"科學家把今日數據與近50年前的紀錄比較。"},{"en":"The colony was much larger almost 50 years ago.","zh":"近50年前，該群落大得多。"},{"en":"Almost 50 years ago, researchers used only manual counting methods.","zh":"近50年前，研究人員只使用人手點算方法。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":2},{"front":"the findings were surprising","meaning":"研究結果令人意外","examples":[{"en":"The findings were surprising because the decline was so large.","zh":"研究結果令人意外，因為下降幅度很大。"},{"en":"The findings were surprising even to experienced scientists.","zh":"研究結果甚至令有經驗科學家意外。"},{"en":"The findings were surprising because every colony had changed.","zh":"研究結果令人意外，因為每個群落都有變化。"},{"en":"The findings were surprising and led to further questions.","zh":"研究結果令人意外，並引出更多問題。"},{"en":"The findings were surprising enough to attract international attention.","zh":"研究結果令人意外，足以引起國際關注。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":2},{"front":"until now","meaning":"直到現在","examples":[{"en":"Until now, the species was thought to be secure.","zh":"直到現在，該物種一直被認為安全。"},{"en":"Until now, researchers had little recent data from the island.","zh":"直到現在，研究人員幾乎沒有該島的近期數據。"},{"en":"Until now, the colony had not been surveyed with drones.","zh":"直到現在，該群落尚未用無人機調查。"},{"en":"Until now, few people realised how quickly the population was falling.","zh":"直到現在，很少人意識到種群下降得多快。"},{"en":"Until now, the changes had gone largely unnoticed.","zh":"直到現在，這些變化大多未被注意。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":2},{"front":"be deemed","meaning":"被認為","examples":[{"en":"The species may be deemed vulnerable after new surveys.","zh":"新調查後，該物種可能被認為易危。"},{"en":"The area was deemed too dangerous for tourists.","zh":"該地區被認為對遊客太危險。"},{"en":"The colony was deemed stable before recent data arrived.","zh":"在近期數據出現前，該群落被認為穩定。"},{"en":"A site can be deemed important for conservation.","zh":"一個地點可以被認為對保育重要。"},{"en":"The evidence was deemed strong enough for further action.","zh":"證據被認為足夠有力，可採取進一步行動。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":3},{"front":"Least Concern","meaning":"無危；低關注級別","examples":[{"en":"The bird was once listed as Least Concern.","zh":"該鳥曾被列為無危。"},{"en":"A species classed as Least Concern may still face local threats.","zh":"被列為無危的物種仍可能面對本地威脅。"},{"en":"New population data can change a Least Concern assessment.","zh":"新種群數據可以改變無危評估。"},{"en":"Least Concern does not mean a species should be ignored.","zh":"無危不代表該物種應被忽視。"},{"en":"Conservationists questioned whether the penguin should remain Least Concern.","zh":"保育人士質疑該企鵝是否應繼續列為無危。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":3},{"front":"International Union for Conservation of Nature","meaning":"國際自然保護聯盟","examples":[{"en":"The International Union for Conservation of Nature assesses species risk.","zh":"國際自然保護聯盟評估物種風險。"},{"en":"Researchers often cite the International Union for Conservation of Nature.","zh":"研究人員常引用國際自然保護聯盟。"},{"en":"The International Union for Conservation of Nature maintains a global Red List.","zh":"國際自然保護聯盟維持全球紅色名錄。"},{"en":"A new survey may influence the International Union for Conservation of Nature’s assessment.","zh":"新調查可能影響國際自然保護聯盟的評估。"},{"en":"The International Union for Conservation of Nature helps standardise conservation status.","zh":"國際自然保護聯盟幫助統一保育狀態標準。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":3},{"front":"know what to expect","meaning":"知道會有甚麼結果","examples":[{"en":"The team did not know what to expect before landing.","zh":"團隊登陸前不知道會有甚麼結果。"},{"en":"New researchers rarely know what to expect in Antarctica.","zh":"新研究人員很少知道在南極會遇到甚麼。"},{"en":"The old data helped scientists know what to expect.","zh":"舊數據幫助科學家知道會有甚麼結果。"},{"en":"Visitors should read the safety guide so they know what to expect.","zh":"遊客應閱讀安全指南，以知道會遇到甚麼。"},{"en":"After several surveys, the team began to know what to expect.","zh":"幾次調查後，團隊開始知道會有甚麼結果。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":3},{"front":"a huge decline","meaning":"大幅下降","examples":[{"en":"The survey revealed a huge decline in the colony.","zh":"調查顯示該群落大幅下降。"},{"en":"A huge decline in krill could harm many animals.","zh":"磷蝦大幅下降可能傷害許多動物。"},{"en":"Researchers were alarmed by a huge decline in nest numbers.","zh":"巢穴數量大幅下降令研究人員震驚。"},{"en":"A huge decline over decades suggests major environmental stress.","zh":"數十年間大幅下降暗示重大環境壓力。"},{"en":"The graph showed a huge decline after the 1970s.","zh":"圖表顯示1970年代後大幅下降。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":3},{"front":"ornithologist","meaning":"鳥類學家","examples":[{"en":"An ornithologist studies birds and their behaviour.","zh":"鳥類學家研究鳥類及其行為。"},{"en":"The ornithologist counted nests on the rocky slope.","zh":"鳥類學家在岩石斜坡上點算巢穴。"},{"en":"An experienced ornithologist identified the species immediately.","zh":"有經驗的鳥類學家立即辨認出該物種。"},{"en":"The expedition included an ornithologist and a climate scientist.","zh":"考察隊包括一名鳥類學家和一名氣候科學家。"},{"en":"The ornithologist explained why penguin numbers matter.","zh":"鳥類學家解釋企鵝數量為何重要。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":3},{"front":"penguin researcher","meaning":"企鵝研究員","examples":[{"en":"The penguin researcher spent weeks on the island.","zh":"企鵝研究員在島上逗留數星期。"},{"en":"A penguin researcher must work in harsh weather.","zh":"企鵝研究員必須在惡劣天氣下工作。"},{"en":"The penguin researcher compared old records with new counts.","zh":"企鵝研究員比較舊紀錄和新點算結果。"},{"en":"A penguin researcher often studies diet, breeding and survival.","zh":"企鵝研究員通常研究飲食、繁殖和存活。"},{"en":"The penguin researcher warned that the decline was serious.","zh":"企鵝研究員警告下降情況很嚴重。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":3},{"front":"aboard the Greenpeace ship","meaning":"在綠色和平船上","examples":[{"en":"Scientists worked aboard the Greenpeace ship for several weeks.","zh":"科學家在綠色和平船上工作數星期。"},{"en":"The researcher gave an interview aboard the Greenpeace ship.","zh":"研究員在綠色和平船上接受訪問。"},{"en":"Equipment was stored aboard the Greenpeace ship.","zh":"設備存放在綠色和平船上。"},{"en":"The team planned the next survey aboard the Greenpeace ship.","zh":"團隊在綠色和平船上計劃下一次調查。"},{"en":"Life aboard the Greenpeace ship was busy and cold.","zh":"在綠色和平船上的生活忙碌而寒冷。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":3},{"front":"it’s a little bit worrying","meaning":"這有點令人擔憂","examples":[{"en":"It’s a little bit worrying that every colony declined.","zh":"每個群落都下降，這有點令人擔憂。"},{"en":"It’s a little bit worrying when food supplies change so quickly.","zh":"食物供應變化如此迅速，這有點令人擔憂。"},{"en":"It’s a little bit worrying to see fewer chicks each year.","zh":"每年看到更少雛鳥，這有點令人擔憂。"},{"en":"It’s a little bit worrying that the trend appears widespread.","zh":"這個趨勢似乎很廣泛，這有點令人擔憂。"},{"en":"It’s a little bit worrying, even if more research is needed.","zh":"即使需要更多研究，這也有點令人擔憂。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":3},{"front":"something is shifting","meaning":"某些事情正在轉變","examples":[{"en":"The data suggests something is shifting in the ecosystem.","zh":"數據顯示生態系統中某些事情正在轉變。"},{"en":"When predators move north, something is shifting in the food web.","zh":"當捕食者向北移動，食物網中某些事情正在轉變。"},{"en":"Scientists realised something was shifting after comparing old surveys.","zh":"比較舊調查後，科學家意識到某些事情正在轉變。"},{"en":"Fewer breeding pairs may mean something is shifting below the surface.","zh":"繁殖配偶對減少可能表示表面之下某些事情正在轉變。"},{"en":"The warming ocean suggests something is shifting in the region.","zh":"變暖的海洋顯示該地區某些事情正在轉變。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":3},{"front":"in the ecosystem","meaning":"在生態系統中","examples":[{"en":"Krill play a central role in the ecosystem.","zh":"磷蝦在生態系統中扮演核心角色。"},{"en":"A small change in the ecosystem can affect many species.","zh":"生態系統中的小變化可以影響許多物種。"},{"en":"Penguins are indicators of change in the ecosystem.","zh":"企鵝是生態系統變化的指標。"},{"en":"Scientists found signs of stress in the ecosystem.","zh":"科學家在生態系統中發現壓力跡象。"},{"en":"Warming water can disturb balance in the ecosystem.","zh":"變暖的海水可以打亂生態系統中的平衡。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":3},{"front":"the fall in penguin numbers","meaning":"企鵝數量下降","examples":[{"en":"The fall in penguin numbers alarmed conservationists.","zh":"企鵝數量下降令保育人士震驚。"},{"en":"Researchers linked the fall in penguin numbers to food shortages.","zh":"研究人員把企鵝數量下降與食物短缺連繫起來。"},{"en":"The fall in penguin numbers was clear in the new survey.","zh":"新調查清楚顯示企鵝數量下降。"},{"en":"Climate scientists studied the fall in penguin numbers carefully.","zh":"氣候科學家仔細研究企鵝數量下降。"},{"en":"The fall in penguin numbers may signal a wider problem.","zh":"企鵝數量下降可能顯示更廣泛問題。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":3},{"front":"reflect that shift","meaning":"反映那種轉變","examples":[{"en":"Penguin numbers may reflect that shift in food supply.","zh":"企鵝數量可能反映食物供應的那種轉變。"},{"en":"Changes in breeding success reflect that shift in the ecosystem.","zh":"繁殖成功率變化反映生態系統中的那種轉變。"},{"en":"The new survey figures reflect that shift clearly.","zh":"新調查數字清楚反映那種轉變。"},{"en":"Declining colonies reflect that shift in ocean conditions.","zh":"群落下降反映海洋狀況的那種轉變。"},{"en":"Gentoo increases may also reflect that shift.","zh":"巴布亞企鵝增加也可能反映那種轉變。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":3},{"front":"every colony","meaning":"每個群落","examples":[{"en":"Every colony showed signs of change.","zh":"每個群落都顯示變化跡象。"},{"en":"Scientists counted nests in every colony.","zh":"科學家點算每個群落中的巢穴。"},{"en":"Every colony on the island was smaller than before.","zh":"島上每個群落都比以前小。"},{"en":"The expedition visited every colony it could safely reach.","zh":"考察隊到訪了每個能安全到達的群落。"},{"en":"Every colony provides clues about local environmental conditions.","zh":"每個群落都提供本地環境狀況的線索。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":4},{"front":"Elephant Island","meaning":"象島","examples":[{"en":"Elephant Island is an important site for penguin surveys.","zh":"象島是企鵝調查的重要地點。"},{"en":"The expedition reached Elephant Island after several days at sea.","zh":"考察隊在海上數日後到達象島。"},{"en":"Researchers compared current data from Elephant Island with old records.","zh":"研究人員把象島的現時數據與舊紀錄比較。"},{"en":"Elephant Island lies in a remote part of the Southern Ocean.","zh":"象島位於南大洋偏遠地區。"},{"en":"The team found major changes on Elephant Island.","zh":"團隊在象島發現重大變化。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":4},{"front":"a crucial penguin habitat","meaning":"重要企鵝棲息地","examples":[{"en":"The island is a crucial penguin habitat.","zh":"該島是重要企鵝棲息地。"},{"en":"A crucial penguin habitat must be protected from disturbance.","zh":"重要企鵝棲息地必須免受干擾。"},{"en":"Scientists identified the bay as a crucial penguin habitat.","zh":"科學家把該海灣確定為重要企鵝棲息地。"},{"en":"Losing a crucial penguin habitat would harm breeding success.","zh":"失去重要企鵝棲息地會損害繁殖成功率。"},{"en":"Conservation plans focused on a crucial penguin habitat near the peninsula.","zh":"保育計劃集中於半島附近的重要企鵝棲息地。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":4},{"front":"northeast of","meaning":"在……東北面","examples":[{"en":"Elephant Island lies northeast of the Antarctic Peninsula.","zh":"象島位於南極半島東北面。"},{"en":"The research station is northeast of the main colony.","zh":"研究站位於主要群落東北面。"},{"en":"A storm formed northeast of the island.","zh":"一場風暴在該島東北面形成。"},{"en":"The ship anchored northeast of the bay.","zh":"船停泊在海灣東北面。"},{"en":"The map shows several small islands northeast of the peninsula.","zh":"地圖顯示半島東北面有幾個小島。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":4},{"front":"experience a population decline","meaning":"經歷種群數量下降","examples":[{"en":"Many colonies experience a population decline after food shortages.","zh":"許多群落在食物短缺後經歷種群數量下降。"},{"en":"The species may experience a population decline if sea ice keeps shrinking.","zh":"如果海冰持續縮小，該物種可能經歷種群數量下降。"},{"en":"Researchers found that every colony experienced a population decline.","zh":"研究人員發現每個群落都經歷種群數量下降。"},{"en":"A population decline can be difficult to detect without old records.","zh":"沒有舊紀錄，種群數量下降可能難以發現。"},{"en":"Conservationists worry when long-lived animals experience a population decline.","zh":"當長壽動物經歷種群數量下降時，保育人士會擔憂。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":4},{"front":"according to","meaning":"根據","examples":[{"en":"According to the survey, the colony has shrunk.","zh":"根據調查，該群落已縮小。"},{"en":"According to researchers, krill numbers are changing.","zh":"根據研究人員所說，磷蝦數量正在改變。"},{"en":"According to the report, warmer oceans affect penguins.","zh":"根據報告，變暖的海洋影響企鵝。"},{"en":"According to local records, the island was surveyed decades ago.","zh":"根據本地紀錄，該島數十年前曾被調查。"},{"en":"According to satellite images, sea ice has declined.","zh":"根據衛星影像，海冰已下降。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":4},{"front":"independent researchers","meaning":"獨立研究人員","examples":[{"en":"Independent researchers joined the survey team.","zh":"獨立研究人員加入調查團隊。"},{"en":"Independent researchers checked the counting methods.","zh":"獨立研究人員檢查點算方法。"},{"en":"The report was reviewed by independent researchers.","zh":"報告由獨立研究人員審閱。"},{"en":"Independent researchers can provide credibility to environmental studies.","zh":"獨立研究人員可以提高環境研究的可信度。"},{"en":"Greenpeace invited independent researchers to examine the colonies.","zh":"綠色和平邀請獨立研究人員檢視群落。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":4},{"front":"join an expedition","meaning":"加入考察隊","examples":[{"en":"Several scientists agreed to join an expedition to Antarctica.","zh":"幾名科學家同意加入前往南極的考察隊。"},{"en":"Students hoped to join an expedition one day.","zh":"學生希望有一天加入考察隊。"},{"en":"A photographer joined the expedition to document wildlife.","zh":"一名攝影師加入考察隊記錄野生動物。"},{"en":"Researchers must train before they join an expedition.","zh":"研究人員加入考察隊前必須接受訓練。"},{"en":"She joined an expedition to survey remote penguin colonies.","zh":"她加入考察隊調查偏遠企鵝群落。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":4},{"front":"Greenpeace expedition","meaning":"綠色和平考察","examples":[{"en":"The Greenpeace expedition carried scientists to remote islands.","zh":"綠色和平考察把科學家送到偏遠島嶼。"},{"en":"A Greenpeace expedition surveyed several penguin colonies.","zh":"一次綠色和平考察調查了幾個企鵝群落。"},{"en":"The Greenpeace expedition used drones and manual counts.","zh":"綠色和平考察使用無人機和人手點算。"},{"en":"Reports from the Greenpeace expedition raised public awareness.","zh":"綠色和平考察的報告提高了公眾意識。"},{"en":"The Greenpeace expedition focused on threats to marine ecosystems.","zh":"綠色和平考察集中於海洋生態系統面對的威脅。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":4},{"front":"to the region","meaning":"前往該地區","examples":[{"en":"The ship returned to the region in summer.","zh":"船在夏季返回該地區。"},{"en":"Scientists travelled to the region to collect new data.","zh":"科學家前往該地區收集新數據。"},{"en":"Warmer water has brought new species to the region.","zh":"較暖海水把新物種帶到該地區。"},{"en":"The expedition carried equipment to the region by sea.","zh":"考察隊以海路把設備帶往該地區。"},{"en":"Researchers compared old maps to recent visits to the region.","zh":"研究人員把舊地圖與最近前往該地區的紀錄比較。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":4},{"front":"last surveyed in","meaning":"上次於……被調查","examples":[{"en":"The colony was last surveyed in the 1970s.","zh":"該群落上次於1970年代被調查。"},{"en":"The island was last surveyed in winter.","zh":"該島上次於冬季被調查。"},{"en":"The site was last surveyed in 2010 by a small team.","zh":"該地點上次於2010年由小隊調查。"},{"en":"The bay was last surveyed in difficult weather.","zh":"該海灣上次於惡劣天氣中被調查。"},{"en":"The nesting area was last surveyed in a much earlier expedition.","zh":"該築巢區上次於更早的考察中被調查。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":4},{"front":"pairs of penguins","meaning":"企鵝配偶對","examples":[{"en":"Researchers counted thousands of pairs of penguins.","zh":"研究人員點算了數千對企鵝配偶。"},{"en":"Pairs of penguins guarded their nests carefully.","zh":"企鵝配偶對小心守護牠們的巢。"},{"en":"The number of breeding pairs of penguins fell sharply.","zh":"繁殖企鵝配偶對數量大幅下降。"},{"en":"Drone images helped identify pairs of penguins from above.","zh":"無人機影像幫助從上方辨認企鵝配偶對。"},{"en":"Each rocky ledge held several pairs of penguins.","zh":"每個岩石平台上都有幾對企鵝配偶。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":4},{"front":"across all colonies","meaning":"在所有群落中","examples":[{"en":"The decline was measured across all colonies.","zh":"在所有群落中都量度到下降。"},{"en":"Researchers compared nest numbers across all colonies.","zh":"研究人員比較所有群落中的巢穴數量。"},{"en":"Across all colonies, the trend was negative.","zh":"在所有群落中，趨勢都是負面的。"},{"en":"The team found fewer chicks across all colonies.","zh":"團隊在所有群落中發現更少雛鳥。"},{"en":"Weather conditions were recorded across all colonies during the survey.","zh":"調查期間，所有群落中的天氣狀況都被記錄。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":4},{"front":"the recent count","meaning":"最近一次點算","examples":[{"en":"The recent count showed far fewer breeding pairs.","zh":"最近一次點算顯示繁殖配偶對少得多。"},{"en":"Scientists trusted the recent count because they used drones.","zh":"科學家信任最近一次點算，因為他們使用無人機。"},{"en":"The recent count was compared with data from decades ago.","zh":"最近一次點算與數十年前數據作比較。"},{"en":"The recent count surprised the whole research team.","zh":"最近一次點算令整個研究團隊意外。"},{"en":"The recent count revealed different trends among colonies.","zh":"最近一次點算顯示不同群落之間有不同趨勢。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":5},{"front":"reveal just","meaning":"顯示只有","examples":[{"en":"The survey revealed just a few hundred nests.","zh":"調查顯示只有數百個巢。"},{"en":"The count revealed just half the expected number.","zh":"點算顯示只有預期數量的一半。"},{"en":"The images revealed just one active colony on the slope.","zh":"影像顯示斜坡上只有一個活躍群落。"},{"en":"The data revealed just how quickly the population had fallen.","zh":"數據顯示種群下降得究竟有多快。"},{"en":"The old map revealed just how remote the island was.","zh":"舊地圖顯示該島有多偏遠。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":5},{"front":"a drop of almost","meaning":"下降接近……","examples":[{"en":"The colony showed a drop of almost 60%.","zh":"該群落顯示下降接近60%。"},{"en":"A drop of almost half would worry any conservationist.","zh":"下降接近一半會令任何保育人士擔心。"},{"en":"The chart showed a drop of almost 10,000 nests.","zh":"圖表顯示巢穴下降接近一萬個。"},{"en":"A drop of almost one third occurred in one breeding season.","zh":"一個繁殖季內下降接近三分之一。"},{"en":"Researchers reported a drop of almost 70% in one area.","zh":"研究人員報告某一地區下降接近70%。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":5},{"front":"vary from colony to colony","meaning":"因群落而異","examples":[{"en":"Population changes vary from colony to colony.","zh":"種群變化因群落而異。"},{"en":"Breeding success can vary from colony to colony.","zh":"繁殖成功率可能因群落而異。"},{"en":"The amount of available food varies from colony to colony.","zh":"可得食物數量因群落而異。"},{"en":"Survey difficulty may vary from colony to colony.","zh":"調查難度可能因群落而異。"},{"en":"The decline did not look the same because conditions vary from colony to colony.","zh":"下降情況看起來不一樣，因為條件因群落而異。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":5},{"front":"the most significant decline","meaning":"最顯著的下降","examples":[{"en":"The most significant decline occurred on the exposed coast.","zh":"最顯著的下降發生在暴露海岸。"},{"en":"Researchers focused on the most significant decline in the data.","zh":"研究人員集中於數據中最顯著的下降。"},{"en":"The most significant decline was found in the largest colony.","zh":"最顯著的下降出現在最大群落。"},{"en":"The most significant decline raised urgent conservation concerns.","zh":"最顯著的下降引起緊急保育關注。"},{"en":"The chart highlighted the most significant decline in red.","zh":"圖表以紅色突出最顯著的下降。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":5},{"front":"be recorded at","meaning":"在……錄得","examples":[{"en":"The highest temperature was recorded at the research station.","zh":"最高溫在研究站錄得。"},{"en":"A major decline was recorded at the northern colony.","zh":"主要下降在北部群落錄得。"},{"en":"Wind speeds were recorded at several sites.","zh":"風速在幾個地點錄得。"},{"en":"The lowest chick survival was recorded at the exposed beach.","zh":"最低雛鳥存活率在暴露海灘錄得。"},{"en":"New data were recorded at the end of the breeding season.","zh":"新數據在繁殖季結束時錄得。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":5},{"front":"be known as","meaning":"被稱為","examples":[{"en":"The colony is known as Chinstrap Camp.","zh":"該群落被稱為 Chinstrap Camp。"},{"en":"The species is also known as the ringed penguin.","zh":"該物種亦被稱為環紋企鵝。"},{"en":"The ship is known as a platform for ocean research.","zh":"該船被稱為海洋研究平台。"},{"en":"The island is known as an important breeding site.","zh":"該島被稱為重要繁殖地。"},{"en":"The narrow black line is known as the chinstrap marking.","zh":"那條窄黑線被稱為帽帶標記。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":5},{"front":"fall by","meaning":"下降了……","examples":[{"en":"The population may fall by another 10% next decade.","zh":"種群未來十年可能再下降10%。"},{"en":"Nest numbers fell by half in one colony.","zh":"一個群落的巢穴數量下降了一半。"},{"en":"Krill availability can fall by large amounts after warm winters.","zh":"暖冬後，磷蝦可得量可能大幅下降。"},{"en":"The temperature did not fall by much overnight.","zh":"夜間氣溫沒有下降很多。"},{"en":"The colony’s size fell by a worrying percentage.","zh":"該群落大小下降了令人擔憂的百分比。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":5},{"front":"the latest study","meaning":"最新研究","examples":[{"en":"The latest study used both drones and manual counts.","zh":"最新研究同時使用無人機和人手點算。"},{"en":"The latest study confirmed a sharp population decline.","zh":"最新研究確認種群急劇下降。"},{"en":"The latest study raised questions about food supply.","zh":"最新研究提出關於食物供應的問題。"},{"en":"The latest study attracted attention from conservation groups.","zh":"最新研究引起保育團體注意。"},{"en":"The latest study compared current figures with older surveys.","zh":"最新研究把現時數字與較舊調查比較。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":5},{"front":"be published just days after","meaning":"在……後僅數天發表","examples":[{"en":"The report was published just days after the temperature record.","zh":"報告在溫度紀錄後僅數天發表。"},{"en":"The study was published just days after the expedition returned.","zh":"研究在考察隊返回後僅數天發表。"},{"en":"The findings were published just days after new climate data appeared.","zh":"研究結果在新氣候數據出現後僅數天發表。"},{"en":"The article was published just days after the island survey ended.","zh":"文章在島嶼調查結束後僅數天發表。"},{"en":"The warning was published just days after scientists confirmed the decline.","zh":"警告在科學家確認下降後僅數天發表。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":5},{"front":"an all-time Antarctic high","meaning":"南極有紀錄以來最高溫","examples":[{"en":"Scientists reported an all-time Antarctic high in temperature.","zh":"科學家報告南極有紀錄以來最高溫。"},{"en":"An all-time Antarctic high alarmed climate researchers.","zh":"南極有紀錄以來最高溫令氣候研究人員警覺。"},{"en":"The station recorded an all-time Antarctic high during summer.","zh":"研究站在夏季錄得南極有紀錄以來最高溫。"},{"en":"An all-time Antarctic high can signal unusual warming.","zh":"南極有紀錄以來最高溫可能顯示異常暖化。"},{"en":"News of an all-time Antarctic high spread quickly.","zh":"南極有紀錄以來最高溫的消息迅速傳開。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":5},{"front":"be recorded on","meaning":"於……錄得","examples":[{"en":"The temperature was recorded on a summer afternoon.","zh":"該溫度於一個夏日下午錄得。"},{"en":"The highest reading was recorded on 6 February.","zh":"最高讀數於2月6日錄得。"},{"en":"Nest numbers were recorded on the final survey day.","zh":"巢穴數字於最後調查日錄得。"},{"en":"Wind speed was recorded on the ship’s instruments.","zh":"風速於船上的儀器錄得。"},{"en":"The decline was recorded on both maps and spreadsheets.","zh":"下降情況於地圖和試算表中均有記錄。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":5},{"front":"the previous high","meaning":"之前的最高紀錄","examples":[{"en":"The new record was higher than the previous high.","zh":"新紀錄高於之前的最高紀錄。"},{"en":"The previous high had stood for several years.","zh":"之前的最高紀錄已維持數年。"},{"en":"Scientists compared the recent reading with the previous high.","zh":"科學家把最近讀數與之前的最高紀錄比較。"},{"en":"The previous high was already considered unusual.","zh":"之前的最高紀錄已被認為不尋常。"},{"en":"The station broke the previous high during a warm spell.","zh":"研究站在一段暖期打破之前的最高紀錄。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":5},{"front":"meteorological agency","meaning":"氣象機構","examples":[{"en":"The meteorological agency confirmed the temperature reading.","zh":"氣象機構確認了溫度讀數。"},{"en":"A national meteorological agency monitors weather records.","zh":"國家氣象機構監察天氣紀錄。"},{"en":"The meteorological agency issued a warning about extreme heat.","zh":"氣象機構發布極端高溫警告。"},{"en":"Researchers checked data from the meteorological agency.","zh":"研究人員檢查來自氣象機構的數據。"},{"en":"The meteorological agency compared the reading with past records.","zh":"氣象機構把該讀數與過往紀錄比較。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":6},{"front":"research station","meaning":"研究站","examples":[{"en":"The research station recorded unusually high temperatures.","zh":"研究站錄得異常高溫。"},{"en":"Scientists lived at the research station during the summer.","zh":"科學家在夏季住在研究站。"},{"en":"The research station provided weather data for the report.","zh":"研究站為報告提供天氣數據。"},{"en":"Supplies were flown to the research station.","zh":"補給品被空運到研究站。"},{"en":"The research station became a key source of climate records.","zh":"研究站成為氣候紀錄的重要來源。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":6},{"front":"reduced sea ice","meaning":"減少了的海冰","examples":[{"en":"Reduced sea ice can affect krill habitat.","zh":"減少了的海冰會影響磷蝦棲息地。"},{"en":"Penguins may struggle when reduced sea ice changes food supply.","zh":"當減少了的海冰改變食物供應時，企鵝可能會吃力。"},{"en":"Reduced sea ice is one sign of a warming region.","zh":"減少了的海冰是地區變暖的跡象之一。"},{"en":"Seals and whales may also be affected by reduced sea ice.","zh":"海豹和鯨魚也可能受到減少了的海冰影響。"},{"en":"The study linked reduced sea ice with ecological change.","zh":"該研究把減少了的海冰與生態變化連繫起來。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":6},{"front":"warmer oceans","meaning":"變暖的海洋","examples":[{"en":"Warmer oceans can reduce krill availability.","zh":"變暖的海洋可以減少磷蝦可得量。"},{"en":"Many marine species are shifting because of warmer oceans.","zh":"許多海洋物種因變暖的海洋而轉移。"},{"en":"Warmer oceans may change where penguins can feed.","zh":"變暖的海洋可能改變企鵝覓食地點。"},{"en":"Scientists measure warmer oceans with long-term temperature records.","zh":"科學家用長期溫度紀錄量度變暖的海洋。"},{"en":"Warmer oceans are a major concern for Antarctic ecosystems.","zh":"變暖的海洋是南極生態系統的主要關注。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":6},{"front":"caused by climate change","meaning":"由氣候變化造成","examples":[{"en":"The shrinking ice may be caused by climate change.","zh":"冰面縮小可能由氣候變化造成。"},{"en":"Some shifts in penguin distribution are caused by climate change.","zh":"一些企鵝分布轉變由氣候變化造成。"},{"en":"Warmer ocean temperatures are caused by climate change in many regions.","zh":"許多地區海洋溫度上升由氣候變化造成。"},{"en":"The report examined problems caused by climate change.","zh":"報告檢視由氣候變化造成的問題。"},{"en":"Food-chain disruption can be caused by climate change.","zh":"食物鏈擾亂可以由氣候變化造成。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":6},{"front":"reduce the amount of","meaning":"減少……的數量","examples":[{"en":"Warmer water can reduce the amount of krill.","zh":"較暖海水可以減少磷蝦數量。"},{"en":"Storms may reduce the amount of time available for feeding.","zh":"風暴可能減少可用於覓食的時間。"},{"en":"Conservation rules can reduce the amount of human disturbance.","zh":"保育規則可以減少人類干擾的數量。"},{"en":"Melting ice may reduce the amount of habitat for some species.","zh":"融冰可能減少某些物種的棲息地數量。"},{"en":"Overfishing could reduce the amount of prey in the ocean.","zh":"過度捕魚可能減少海洋中獵物的數量。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":6},{"front":"krill","meaning":"磷蝦","examples":[{"en":"Krill are tiny crustaceans eaten by penguins and whales.","zh":"磷蝦是企鵝和鯨魚食用的小型甲殼動物。"},{"en":"Chinstrap penguins depend heavily on krill.","zh":"帽帶企鵝高度依賴磷蝦。"},{"en":"A decline in krill can affect the whole food web.","zh":"磷蝦下降可以影響整個食物網。"},{"en":"Scientists measured krill abundance near the colonies.","zh":"科學家量度群落附近的磷蝦豐富度。"},{"en":"Sea ice provides important habitat for young krill.","zh":"海冰為幼年磷蝦提供重要棲息地。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":6},{"front":"the main component of","meaning":"……的主要成分","examples":[{"en":"Krill is the main component of the penguin’s diet.","zh":"磷蝦是企鵝飲食的主要成分。"},{"en":"Sea ice is the main component of some Antarctic habitats.","zh":"海冰是一些南極棲息地的主要成分。"},{"en":"Data analysis is the main component of the research project.","zh":"數據分析是該研究項目的主要成分。"},{"en":"Fieldwork was the main component of the expedition.","zh":"野外工作是該考察的主要成分。"},{"en":"Public support is the main component of successful conservation.","zh":"公眾支持是成功保育的主要成分。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":6},{"front":"the penguins’ diet","meaning":"企鵝的飲食","examples":[{"en":"Krill forms a major part of the penguins’ diet.","zh":"磷蝦構成企鵝飲食的主要部分。"},{"en":"Changes in the penguins’ diet can reveal changes in the ocean.","zh":"企鵝飲食的變化可以揭示海洋變化。"},{"en":"Scientists studied the penguins’ diet through feeding observations.","zh":"科學家透過覓食觀察研究企鵝的飲食。"},{"en":"A shortage of krill affects the penguins’ diet.","zh":"磷蝦短缺影響企鵝的飲食。"},{"en":"The penguins’ diet may vary from year to year.","zh":"企鵝的飲食可能每年不同。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":6},{"front":"underlying factor","meaning":"根本因素","examples":[{"en":"Climate change may be the underlying factor behind the decline.","zh":"氣候變化可能是下降背後的根本因素。"},{"en":"Food shortage was an underlying factor in breeding failure.","zh":"食物短缺是繁殖失敗的根本因素。"},{"en":"Researchers searched for the underlying factor in the population change.","zh":"研究人員尋找種群變化中的根本因素。"},{"en":"Ocean warming could be an underlying factor affecting krill.","zh":"海洋變暖可能是影響磷蝦的根本因素。"},{"en":"The underlying factor may not be obvious from simple counts.","zh":"根本因素未必能從簡單點算中看出。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":6},{"front":"the effects are rippling through","meaning":"影響正蔓延至……","examples":[{"en":"The effects are rippling through the food chain.","zh":"影響正蔓延至食物鏈。"},{"en":"The effects are rippling through penguin breeding sites.","zh":"影響正蔓延至企鵝繁殖地。"},{"en":"The effects of warming oceans are rippling through marine ecosystems.","zh":"變暖海洋的影響正蔓延至海洋生態系統。"},{"en":"The effects are rippling through local wildlife populations.","zh":"影響正蔓延至本地野生動物種群。"},{"en":"The effects of reduced krill are rippling through the region.","zh":"磷蝦減少的影響正蔓延至該地區。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":6},{"front":"the food chain","meaning":"食物鏈","examples":[{"en":"Krill occupies a key position in the food chain.","zh":"磷蝦在食物鏈中佔重要位置。"},{"en":"Penguins are one link in the food chain.","zh":"企鵝是食物鏈中的一環。"},{"en":"Climate change can disrupt the food chain.","zh":"氣候變化可以擾亂食物鏈。"},{"en":"A change at the bottom of the food chain affects predators.","zh":"食物鏈底部的變化會影響捕食者。"},{"en":"Scientists studied how warming affects the food chain.","zh":"科學家研究暖化如何影響食物鏈。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":6},{"front":"depend on","meaning":"依賴","examples":[{"en":"Chinstrap penguins depend on krill for food.","zh":"帽帶企鵝依賴磷蝦作食物。"},{"en":"Many whales depend on healthy ocean ecosystems.","zh":"許多鯨魚依賴健康海洋生態系統。"},{"en":"Conservation decisions depend on reliable data.","zh":"保育決策依賴可靠數據。"},{"en":"The success of the survey depended on good weather.","zh":"調查成功依賴良好天氣。"},{"en":"Young chicks depend on adults for protection.","zh":"雛鳥依賴成年鳥保護。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":6},{"front":"impact on everything else","meaning":"影響其他一切","examples":[{"en":"A change in sea ice can impact on everything else.","zh":"海冰變化可以影響其他一切。"},{"en":"Reduced krill may impact on everything else in the food web.","zh":"磷蝦減少可能影響食物網中的其他一切。"},{"en":"Ocean warming does not affect one species only; it can impact on everything else.","zh":"海洋變暖不只影響一個物種；它可以影響其他一切。"},{"en":"If breeding sites disappear, that will impact on everything else.","zh":"如果繁殖地消失，那會影響其他一切。"},{"en":"The loss of one key species may impact on everything else.","zh":"一個關鍵物種消失可能影響其他一切。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":7},{"front":"associate professor","meaning":"副教授","examples":[{"en":"An associate professor led part of the research.","zh":"一名副教授領導部分研究。"},{"en":"The associate professor specialises in Antarctic ecology.","zh":"該副教授專門研究南極生態。"},{"en":"Students interviewed the associate professor about penguin decline.","zh":"學生訪問副教授有關企鵝下降的問題。"},{"en":"The associate professor reviewed the survey results.","zh":"副教授審閱調查結果。"},{"en":"An associate professor often combines teaching with research.","zh":"副教授通常同時從事教學和研究。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":7},{"front":"ecology and evolution","meaning":"生態學與演化","examples":[{"en":"She teaches ecology and evolution at the university.","zh":"她在大學教授生態學與演化。"},{"en":"Ecology and evolution help explain changes in species distribution.","zh":"生態學與演化有助解釋物種分布變化。"},{"en":"The study combined climate science with ecology and evolution.","zh":"該研究結合氣候科學與生態學與演化。"},{"en":"Students of ecology and evolution often study food webs.","zh":"學習生態學與演化的學生常研究食物網。"},{"en":"Ecology and evolution are important for understanding penguin adaptation.","zh":"生態學與演化對理解企鵝適應很重要。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":7},{"front":"research leads","meaning":"研究負責人","examples":[{"en":"The research leads coordinated the fieldwork.","zh":"研究負責人協調野外工作。"},{"en":"Several research leads reviewed the final report.","zh":"幾名研究負責人審閱最終報告。"},{"en":"The research leads decided which colonies to survey first.","zh":"研究負責人決定先調查哪些群落。"},{"en":"Experienced research leads trained the drone team.","zh":"有經驗的研究負責人訓練無人機團隊。"},{"en":"The research leads explained the findings to the media.","zh":"研究負責人向媒體解釋研究結果。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":7},{"front":"significant declines in","meaning":"……的顯著下降","examples":[{"en":"Scientists observed significant declines in chinstrap-penguin numbers.","zh":"科學家觀察到帽帶企鵝數量顯著下降。"},{"en":"Significant declines in krill may affect many predators.","zh":"磷蝦顯著下降可能影響許多捕食者。"},{"en":"The report showed significant declines in several colonies.","zh":"報告顯示幾個群落顯著下降。"},{"en":"Significant declines in sea ice worry climate researchers.","zh":"海冰顯著下降令氣候研究人員擔憂。"},{"en":"Significant declines in breeding success were recorded over time.","zh":"繁殖成功率的顯著下降隨時間被記錄。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":7},{"front":"suggest that","meaning":"顯示；暗示","examples":[{"en":"The results suggest that the ecosystem is changing.","zh":"結果顯示生態系統正在改變。"},{"en":"The data suggest that food supply has become less reliable.","zh":"數據暗示食物供應變得較不可靠。"},{"en":"Warmer water may suggest that krill habitats are shifting.","zh":"較暖海水可能暗示磷蝦棲息地正在轉移。"},{"en":"The survey results suggest that conservation action is needed.","zh":"調查結果顯示需要保育行動。"},{"en":"The increase in gentoo penguins may suggest that species are moving.","zh":"巴布亞企鵝增加可能暗示物種正在移動。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":7},{"front":"the Southern Ocean’s ecosystem","meaning":"南大洋生態系統","examples":[{"en":"The Southern Ocean’s ecosystem depends heavily on krill.","zh":"南大洋生態系統高度依賴磷蝦。"},{"en":"Scientists are studying how the Southern Ocean’s ecosystem is changing.","zh":"科學家正在研究南大洋生態系統如何改變。"},{"en":"Warming may disrupt the Southern Ocean’s ecosystem.","zh":"暖化可能擾亂南大洋生態系統。"},{"en":"Penguins are important indicators within the Southern Ocean’s ecosystem.","zh":"企鵝是南大洋生態系統中的重要指標。"},{"en":"Protecting the Southern Ocean’s ecosystem requires global cooperation.","zh":"保護南大洋生態系統需要全球合作。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":7},{"front":"fundamentally changed","meaning":"根本上改變","examples":[{"en":"The ecosystem may have fundamentally changed over decades.","zh":"生態系統可能在數十年間根本上改變。"},{"en":"Ocean conditions have fundamentally changed in some regions.","zh":"一些地區的海洋狀況已根本上改變。"},{"en":"The survey suggests that the food web has fundamentally changed.","zh":"調查顯示食物網已根本上改變。"},{"en":"Technology has fundamentally changed how scientists count penguins.","zh":"科技根本上改變了科學家點算企鵝的方式。"},{"en":"The warming trend has fundamentally changed conservation priorities.","zh":"暖化趨勢根本上改變了保育優先事項。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":7},{"front":"the impacts of this","meaning":"這件事的影響","examples":[{"en":"The impacts of this are visible in penguin colonies.","zh":"這件事的影響在企鵝群落中可見。"},{"en":"The impacts of this may spread through the food web.","zh":"這件事的影響可能蔓延至食物網。"},{"en":"Scientists are still measuring the impacts of this warming.","zh":"科學家仍在量度這種暖化的影響。"},{"en":"The impacts of this decline could reach other species.","zh":"這種下降的影響可能波及其他物種。"},{"en":"The impacts of this change are not limited to penguins.","zh":"這件事的影響不限於企鵝。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":7},{"front":"ripple up the food web","meaning":"沿食物網向上蔓延","examples":[{"en":"Krill shortages can ripple up the food web.","zh":"磷蝦短缺可以沿食物網向上蔓延。"},{"en":"Changes at the base of the ecosystem ripple up the food web.","zh":"生態系統底部的變化會沿食物網向上蔓延。"},{"en":"Reduced sea ice may ripple up the food web to penguins.","zh":"海冰減少可能沿食物網向上蔓延至企鵝。"},{"en":"The effects of warming oceans can ripple up the food web quickly.","zh":"海洋變暖的影響可以迅速沿食物網向上蔓延。"},{"en":"Scientists studied how small changes ripple up the food web.","zh":"科學家研究小變化如何沿食物網向上蔓延。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":7},{"front":"food web","meaning":"食物網","examples":[{"en":"Krill are central to the Antarctic food web.","zh":"磷蝦是南極食物網的核心。"},{"en":"A food web shows how species depend on one another.","zh":"食物網顯示物種如何互相依賴。"},{"en":"Penguins, seals and whales are connected through the food web.","zh":"企鵝、海豹和鯨魚透過食物網相互連繫。"},{"en":"Climate change can disturb the whole food web.","zh":"氣候變化可以擾亂整個食物網。"},{"en":"Scientists used the food web to explain the decline.","zh":"科學家用食物網解釋下降情況。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":7},{"front":"have a role to play","meaning":"有作用；可發揮作用","examples":[{"en":"Sea ice may have a role to play in krill survival.","zh":"海冰可能對磷蝦存活有作用。"},{"en":"Ocean temperature has a role to play in penguin distribution.","zh":"海洋溫度在企鵝分布中有作用。"},{"en":"Fishing pressure could have a role to play in food shortages.","zh":"捕魚壓力可能在食物短缺中有作用。"},{"en":"Protected areas have a role to play in conservation.","zh":"保護區在保育中可發揮作用。"},{"en":"Every country has a role to play in ocean protection.","zh":"每個國家在海洋保護中都有作用。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":7},{"front":"all the evidence points to","meaning":"所有證據都指向","examples":[{"en":"All the evidence points to climate change as a major cause.","zh":"所有證據都指向氣候變化是主要原因。"},{"en":"All the evidence points to a decline in food supply.","zh":"所有證據都指向食物供應下降。"},{"en":"All the evidence points to long-term environmental change.","zh":"所有證據都指向長期環境變化。"},{"en":"All the evidence points to the need for urgent monitoring.","zh":"所有證據都指向需要緊急監察。"},{"en":"All the evidence points to warmer oceans affecting the colonies.","zh":"所有證據都指向變暖海洋正在影響群落。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":7},{"front":"be responsible for","meaning":"對……負責；是……的原因","examples":[{"en":"Climate change may be responsible for the decline.","zh":"氣候變化可能是下降的原因。"},{"en":"Warmer oceans are responsible for changes in krill distribution.","zh":"變暖海洋是磷蝦分布變化的原因。"},{"en":"Human activity is partly responsible for rising global temperatures.","zh":"人類活動對全球氣溫上升負有部分責任。"},{"en":"Reduced food supply may be responsible for breeding failure.","zh":"食物供應減少可能是繁殖失敗的原因。"},{"en":"The report asked which factors were responsible for the changes.","zh":"報告詢問哪些因素是這些變化的原因。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":8},{"front":"the changes we are seeing","meaning":"我們正在看到的變化","examples":[{"en":"The changes we are seeing may continue for decades.","zh":"我們正在看到的變化可能持續數十年。"},{"en":"Scientists linked the changes we are seeing to ocean warming.","zh":"科學家把我們正在看到的變化與海洋變暖連繫起來。"},{"en":"The changes we are seeing affect more than one penguin species.","zh":"我們正在看到的變化影響不只一種企鵝。"},{"en":"The changes we are seeing require stronger protection measures.","zh":"我們正在看到的變化需要更強保護措施。"},{"en":"The changes we are seeing are consistent with climate predictions.","zh":"我們正在看到的變化與氣候預測一致。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":8},{"front":"some good news","meaning":"一些好消息","examples":[{"en":"There was some good news about gentoo penguins.","zh":"關於巴布亞企鵝有一些好消息。"},{"en":"The report included some good news despite the decline.","zh":"儘管出現下降，報告仍包括一些好消息。"},{"en":"Some good news came from neighbouring colonies.","zh":"一些好消息來自鄰近群落。"},{"en":"Conservationists welcomed some good news after months of concern.","zh":"數月擔憂後，保育人士歡迎一些好消息。"},{"en":"Some good news does not erase the wider problem.","zh":"一些好消息並不能抹去更廣泛問題。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":8},{"front":"report an increase in","meaning":"報告……有所增加","examples":[{"en":"Researchers reported an increase in gentoo penguins.","zh":"研究人員報告巴布亞企鵝有所增加。"},{"en":"The survey reported an increase in nests on one island.","zh":"調查報告某島巢穴有所增加。"},{"en":"Scientists reported an increase in ocean temperature.","zh":"科學家報告海洋溫度有所增加。"},{"en":"The report noted an increase in drone-based surveys.","zh":"報告指出無人機調查有所增加。"},{"en":"Conservationists reported an increase in public concern.","zh":"保育人士報告公眾關注有所增加。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":8},{"front":"gentoo-penguin populations","meaning":"巴布亞企鵝種群","examples":[{"en":"Gentoo-penguin populations increased in some areas.","zh":"巴布亞企鵝種群在一些地區增加。"},{"en":"Researchers compared gentoo-penguin populations with chinstrap populations.","zh":"研究人員比較巴布亞企鵝種群與帽帶企鵝種群。"},{"en":"Gentoo-penguin populations may respond differently to warming.","zh":"巴布亞企鵝種群可能對暖化有不同反應。"},{"en":"The rise in gentoo-penguin populations surprised some observers.","zh":"巴布亞企鵝種群上升令一些觀察者意外。"},{"en":"Gentoo-penguin populations are expanding near certain colonies.","zh":"巴布亞企鵝種群正在某些群落附近擴張。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":8},{"front":"neighbouring colonies","meaning":"鄰近群落","examples":[{"en":"Neighbouring colonies showed a different trend.","zh":"鄰近群落顯示不同趨勢。"},{"en":"Researchers visited neighbouring colonies after surveying the main island.","zh":"研究人員調查主島後到訪鄰近群落。"},{"en":"Some neighbouring colonies had more gentoo penguins.","zh":"一些鄰近群落有更多巴布亞企鵝。"},{"en":"Comparing neighbouring colonies helps explain local differences.","zh":"比較鄰近群落有助解釋本地差異。"},{"en":"The team used boats to reach neighbouring colonies.","zh":"團隊使用小船到達鄰近群落。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":8},{"front":"beyond Elephant Island","meaning":"在象島以外","examples":[{"en":"The survey also examined colonies beyond Elephant Island.","zh":"調查也檢視象島以外的群落。"},{"en":"Gentoo penguins were increasing beyond Elephant Island.","zh":"巴布亞企鵝在象島以外有所增加。"},{"en":"Researchers planned further work beyond Elephant Island.","zh":"研究人員計劃在象島以外進行進一步工作。"},{"en":"Conditions beyond Elephant Island may differ from those on the island itself.","zh":"象島以外的條件可能與島上本身不同。"},{"en":"The expedition gathered evidence beyond Elephant Island.","zh":"考察隊在象島以外收集證據。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":8},{"front":"a tale of two penguins","meaning":"兩種企鵝的不同故事","examples":[{"en":"The results became a tale of two penguins.","zh":"結果成為兩種企鵝的不同故事。"},{"en":"The phrase “a tale of two penguins” describes opposite trends.","zh":"「兩種企鵝的不同故事」描述相反趨勢。"},{"en":"A tale of two penguins shows one species declining and another increasing.","zh":"兩種企鵝的不同故事顯示一種下降，另一種增加。"},{"en":"The documentary used a tale of two penguins to explain climate effects.","zh":"紀錄片用兩種企鵝的不同故事解釋氣候影響。"},{"en":"Researchers called it a tale of two penguins because the species responded differently.","zh":"研究人員稱之為兩種企鵝的不同故事，因為物種反應不同。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":8},{"front":"a species from further north","meaning":"來自更北方的物種","examples":[{"en":"The gentoo is a species from further north.","zh":"巴布亞企鵝是來自更北方的物種。"},{"en":"A species from further north may benefit from warmer conditions.","zh":"來自更北方的物種可能受惠於較暖條件。"},{"en":"Researchers noticed that a species from further north was spreading south.","zh":"研究人員注意到來自更北方的物種正在向南擴展。"},{"en":"A species from further north can change local competition.","zh":"來自更北方的物種可以改變本地競爭。"},{"en":"The arrival of a species from further north may signal climate change.","zh":"來自更北方物種的到來可能顯示氣候變化。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":8},{"front":"appear to be colonising","meaning":"似乎正在殖民；似乎正在進駐","examples":[{"en":"Gentoo penguins appear to be colonising new areas.","zh":"巴布亞企鵝似乎正在進駐新地區。"},{"en":"The birds appear to be colonising beaches once used by other species.","zh":"這些鳥似乎正在進駐曾由其他物種使用的海灘。"},{"en":"A species may appear to be colonising when nests increase rapidly.","zh":"當巢穴快速增加時，一個物種可能似乎正在殖民。"},{"en":"Researchers said the penguins appear to be colonising the region.","zh":"研究人員說這些企鵝似乎正在進駐該地區。"},{"en":"Warmer conditions may help gentoo penguins appear to be colonising farther south.","zh":"較暖條件可能幫助巴布亞企鵝似乎正在向更南方進駐。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":8},{"front":"increase in numbers","meaning":"數量增加","examples":[{"en":"Gentoo penguins continue to increase in numbers.","zh":"巴布亞企鵝數量繼續增加。"},{"en":"An increase in numbers can signal successful breeding.","zh":"數量增加可以顯示繁殖成功。"},{"en":"Researchers observed an increase in numbers near the coast.","zh":"研究人員在海岸附近觀察到數量增加。"},{"en":"Not every species will increase in numbers under warming conditions.","zh":"並非每個物種在暖化條件下都會數量增加。"},{"en":"The increase in numbers contrasted with chinstrap decline.","zh":"數量增加與帽帶企鵝下降形成對比。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":8},{"front":"document the threat to","meaning":"記錄對……的威脅","examples":[{"en":"The ship helped document the threat to ocean life.","zh":"該船幫助記錄對海洋生物的威脅。"},{"en":"Scientists used photographs to document the threat to penguin colonies.","zh":"科學家用照片記錄對企鵝群落的威脅。"},{"en":"The expedition aimed to document the threat to remote ecosystems.","zh":"考察旨在記錄對偏遠生態系統的威脅。"},{"en":"Researchers document the threat to krill through long-term monitoring.","zh":"研究人員透過長期監察記錄對磷蝦的威脅。"},{"en":"The report documents the threat to marine species from climate change.","zh":"報告記錄氣候變化對海洋物種的威脅。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":8},{"front":"the oceans worldwide","meaning":"全球海洋","examples":[{"en":"Climate change affects the oceans worldwide.","zh":"氣候變化影響全球海洋。"},{"en":"Plastic pollution threatens the oceans worldwide.","zh":"塑膠污染威脅全球海洋。"},{"en":"Researchers collect data from the oceans worldwide.","zh":"研究人員從全球海洋收集數據。"},{"en":"Protecting the oceans worldwide requires international agreements.","zh":"保護全球海洋需要國際協議。"},{"en":"The campaign focuses on threats to the oceans worldwide.","zh":"該運動集中於全球海洋面對的威脅。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":8},{"front":"transport scientists","meaning":"運送科學家","examples":[{"en":"The ship can transport scientists to remote islands.","zh":"該船可以運送科學家到偏遠島嶼。"},{"en":"Special vessels transport scientists across dangerous waters.","zh":"特殊船隻運送科學家穿越危險水域。"},{"en":"Helicopters sometimes transport scientists to research stations.","zh":"直升機有時運送科學家到研究站。"},{"en":"The expedition used boats to transport scientists and equipment.","zh":"考察隊使用小船運送科學家和設備。"},{"en":"Without ships, it would be hard to transport scientists to Antarctica.","zh":"沒有船隻，很難運送科學家到南極。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":9},{"front":"overseas expeditions","meaning":"海外考察","examples":[{"en":"Scientists joined overseas expeditions to study marine life.","zh":"科學家加入海外考察研究海洋生物。"},{"en":"Overseas expeditions require careful planning.","zh":"海外考察需要仔細規劃。"},{"en":"The university funded several overseas expeditions.","zh":"大學資助了幾次海外考察。"},{"en":"Young researchers gained experience on overseas expeditions.","zh":"年輕研究人員在海外考察中獲得經驗。"},{"en":"Weather can delay overseas expeditions in polar regions.","zh":"天氣可以延誤極地地區的海外考察。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":9},{"front":"for the first time","meaning":"首次","examples":[{"en":"Low Island was surveyed properly for the first time.","zh":"洛島首次被妥善調查。"},{"en":"The team used drones for the first time on that island.","zh":"團隊首次在該島使用無人機。"},{"en":"For the first time, researchers had detailed images of the colony.","zh":"研究人員首次擁有該群落的詳細影像。"},{"en":"She visited Antarctica for the first time as a student.","zh":"她作為學生首次到訪南極。"},{"en":"The species was recorded there for the first time.","zh":"該物種首次在那裏被記錄。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":9},{"front":"Low Island","meaning":"洛島","examples":[{"en":"Low Island is part of the South Shetland Islands.","zh":"洛島是南設得蘭群島的一部分。"},{"en":"Researchers planned a detailed survey of Low Island.","zh":"研究人員計劃對洛島作詳細調查。"},{"en":"Low Island had not been properly surveyed before.","zh":"洛島以前未被妥善調查。"},{"en":"Chinstrap penguins breed on Low Island.","zh":"帽帶企鵝在洛島繁殖。"},{"en":"The ship approached Low Island in calm weather.","zh":"船在平靜天氣中接近洛島。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":9},{"front":"South Shetland Islands","meaning":"南設得蘭群島","examples":[{"en":"The South Shetland Islands lie north of the Antarctic Peninsula.","zh":"南設得蘭群島位於南極半島以北。"},{"en":"Several penguin species breed in the South Shetland Islands.","zh":"幾種企鵝在南設得蘭群島繁殖。"},{"en":"The expedition visited the South Shetland Islands in summer.","zh":"考察隊在夏季到訪南設得蘭群島。"},{"en":"Weather around the South Shetland Islands can be unpredictable.","zh":"南設得蘭群島周圍天氣可能難以預測。"},{"en":"Scientists use the South Shetland Islands as a key research area.","zh":"科學家把南設得蘭群島用作重要研究區域。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":9},{"front":"be surveyed properly","meaning":"被妥善調查","examples":[{"en":"The island needs to be surveyed properly before conclusions are drawn.","zh":"在得出結論前，該島需要被妥善調查。"},{"en":"Low Island was finally surveyed properly using drones.","zh":"洛島最終使用無人機被妥善調查。"},{"en":"A colony cannot be assessed unless it is surveyed properly.","zh":"群落若未被妥善調查，就不能被評估。"},{"en":"The area was too dangerous to be surveyed properly in winter.","zh":"該地區冬季太危險，無法被妥善調查。"},{"en":"Researchers returned so the site could be surveyed properly.","zh":"研究人員返回，以便該地點能被妥善調查。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":9},{"front":"manual and drone techniques","meaning":"人手及無人機技術","examples":[{"en":"Researchers used manual and drone techniques to count nests.","zh":"研究人員使用人手及無人機技術點算巢穴。"},{"en":"Manual and drone techniques produced more reliable data.","zh":"人手及無人機技術產生更可靠數據。"},{"en":"The team combined manual and drone techniques during the survey.","zh":"團隊在調查期間結合人手及無人機技術。"},{"en":"Manual and drone techniques helped cover difficult terrain.","zh":"人手及無人機技術幫助覆蓋困難地形。"},{"en":"Training was needed before using manual and drone techniques.","zh":"使用人手及無人機技術前需要訓練。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":9},{"front":"survey a series of","meaning":"調查一系列……","examples":[{"en":"The team planned to survey a series of penguin colonies.","zh":"團隊計劃調查一系列企鵝群落。"},{"en":"Scientists will survey a series of islands next season.","zh":"科學家下季將調查一系列島嶼。"},{"en":"Drones helped survey a series of remote breeding sites.","zh":"無人機幫助調查一系列偏遠繁殖地。"},{"en":"The expedition aimed to survey a series of little-known habitats.","zh":"考察旨在調查一系列鮮為人知的棲息地。"},{"en":"Researchers returned each year to survey a series of coastal areas.","zh":"研究人員每年返回調查一系列沿海地區。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":9},{"front":"significant but relatively unknown","meaning":"重要但相對不為人知","examples":[{"en":"The colony is significant but relatively unknown.","zh":"該群落重要但相對不為人知。"},{"en":"Scientists focused on habitats that were significant but relatively unknown.","zh":"科學家集中於重要但相對不為人知的棲息地。"},{"en":"A significant but relatively unknown island may hold important data.","zh":"一個重要但相對不為人知的島嶼可能含有重要數據。"},{"en":"The report highlighted significant but relatively unknown penguin sites.","zh":"報告突出重要但相對不為人知的企鵝地點。"},{"en":"Many significant but relatively unknown ecosystems remain poorly studied.","zh":"許多重要但相對不為人知的生態系統仍研究不足。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":9},{"front":"chinstrap-penguin colonies","meaning":"帽帶企鵝群落","examples":[{"en":"Chinstrap-penguin colonies were surveyed by drone.","zh":"帽帶企鵝群落由無人機調查。"},{"en":"Several chinstrap-penguin colonies showed sharp declines.","zh":"幾個帽帶企鵝群落顯示急劇下降。"},{"en":"The team mapped chinstrap-penguin colonies along the coast.","zh":"團隊繪製沿岸帽帶企鵝群落地圖。"},{"en":"Chinstrap-penguin colonies can be noisy during breeding season.","zh":"帽帶企鵝群落在繁殖季可能很嘈雜。"},{"en":"Protecting chinstrap-penguin colonies helps conserve Antarctic biodiversity.","zh":"保護帽帶企鵝群落有助保育南極生物多樣性。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":9},{"front":"not yet available","meaning":"尚未可得","examples":[{"en":"The final results are not yet available.","zh":"最終結果尚未可得。"},{"en":"Data from the drone survey are not yet available.","zh":"無人機調查數據尚未可得。"},{"en":"The report is not yet available to the public.","zh":"報告尚未供公眾查閱。"},{"en":"Full temperature records are not yet available.","zh":"完整溫度紀錄尚未可得。"},{"en":"The team said the colony count was not yet available.","zh":"團隊表示群落點算結果尚未可得。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":9},{"front":"campaign for","meaning":"爭取；倡議","examples":[{"en":"Greenpeace continues to campaign for ocean protection.","zh":"綠色和平繼續倡議海洋保護。"},{"en":"Scientists campaign for stronger conservation measures.","zh":"科學家爭取更強保育措施。"},{"en":"Local groups campaign for cleaner beaches.","zh":"本地團體爭取更潔淨海灘。"},{"en":"The organisation will campaign for Antarctic sanctuaries.","zh":"該組織將爭取南極保護區。"},{"en":"Students campaign for policies based on climate science.","zh":"學生倡議以氣候科學為基礎的政策。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":9},{"front":"the establishment of","meaning":"……的設立","examples":[{"en":"The group supports the establishment of marine sanctuaries.","zh":"該團體支持海洋保護區的設立。"},{"en":"The establishment of protected areas can reduce human disturbance.","zh":"保護區的設立可以減少人類干擾。"},{"en":"Scientists called for the establishment of stronger monitoring systems.","zh":"科學家呼籲設立更強監察系統。"},{"en":"The treaty may lead to the establishment of ocean reserves.","zh":"該條約可能導致海洋保護區的設立。"},{"en":"The establishment of new rules requires international agreement.","zh":"新規則的設立需要國際協議。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":9},{"front":"Antarctic sanctuaries","meaning":"南極保護區","examples":[{"en":"Antarctic sanctuaries could protect penguin colonies.","zh":"南極保護區可以保護企鵝群落。"},{"en":"Campaigners want Antarctic sanctuaries to limit human activity.","zh":"倡議者希望南極保護區限制人類活動。"},{"en":"Antarctic sanctuaries may help wildlife adapt to warming.","zh":"南極保護區可能幫助野生動物適應暖化。"},{"en":"The treaty could support new Antarctic sanctuaries.","zh":"該條約可以支持新的南極保護區。"},{"en":"Scientists identified areas suitable for Antarctic sanctuaries.","zh":"科學家確定適合設立南極保護區的地區。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":10},{"front":"protect many of","meaning":"保護許多……","examples":[{"en":"The proposed sanctuary would protect many of the colonies.","zh":"擬議保護區將保護許多群落。"},{"en":"Stronger rules could protect many of the breeding sites.","zh":"更強規則可以保護許多繁殖地。"},{"en":"Ocean reserves may protect many of the species at risk.","zh":"海洋保護區可能保護許多受威脅物種。"},{"en":"Better monitoring can protect many of the most vulnerable areas.","zh":"更好監察可以保護許多最脆弱地區。"},{"en":"International cooperation would protect many of the habitats studied.","zh":"國際合作將保護許多已研究棲息地。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":10},{"front":"colonies surveyed","meaning":"已調查的群落","examples":[{"en":"The sanctuaries would protect the colonies surveyed.","zh":"保護區將保護已調查的群落。"},{"en":"Scientists compared all colonies surveyed during the expedition.","zh":"科學家比較考察期間所有已調查的群落。"},{"en":"The colonies surveyed showed different population trends.","zh":"已調查的群落顯示不同種群趨勢。"},{"en":"Drone images were collected for each of the colonies surveyed.","zh":"每個已調查的群落都有無人機影像。"},{"en":"The report listed the colonies surveyed by location.","zh":"報告按地點列出已調查的群落。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":10},{"front":"be off-limits to","meaning":"禁止……進入","examples":[{"en":"The sanctuary would be off-limits to tourists.","zh":"該保護區將禁止遊客進入。"},{"en":"Some breeding areas are off-limits to humans.","zh":"一些繁殖區禁止人類進入。"},{"en":"The beach was off-limits to protect nesting birds.","zh":"該海灘被禁止進入，以保護築巢鳥類。"},{"en":"During the survey, dangerous cliffs were off-limits to students.","zh":"調查期間，危險懸崖禁止學生進入。"},{"en":"Protected zones may be off-limits to fishing vessels.","zh":"受保護區域可能禁止漁船進入。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":10},{"front":"oceans campaigner","meaning":"海洋保育倡議者","examples":[{"en":"An oceans campaigner called for stronger marine protection.","zh":"一名海洋保育倡議者呼籲加強海洋保護。"},{"en":"The oceans campaigner spoke about penguin decline.","zh":"該海洋保育倡議者談及企鵝下降。"},{"en":"An oceans campaigner works to protect marine ecosystems.","zh":"海洋保育倡議者致力保護海洋生態系統。"},{"en":"The statement was written by a Greenpeace oceans campaigner.","zh":"該聲明由一名綠色和平海洋保育倡議者撰寫。"},{"en":"The oceans campaigner urged governments to act.","zh":"海洋保育倡議者敦促政府採取行動。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":10},{"front":"say in a statement","meaning":"在聲明中表示","examples":[{"en":"The campaigner said in a statement that action was urgent.","zh":"倡議者在聲明中表示行動很迫切。"},{"en":"Scientists said in a statement that the decline was alarming.","zh":"科學家在聲明中表示下降情況令人警覺。"},{"en":"The organisation said in a statement that sanctuaries were needed.","zh":"該組織在聲明中表示需要保護區。"},{"en":"Researchers said in a statement that the data were still being analysed.","zh":"研究人員在聲明中表示數據仍在分析。"},{"en":"The agency said in a statement that the temperature record was under review.","zh":"該機構在聲明中表示溫度紀錄正在審查。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":10},{"front":"iconic species","meaning":"標誌性物種","examples":[{"en":"Penguins are an iconic species of Antarctica.","zh":"企鵝是南極的標誌性物種。"},{"en":"An iconic species can draw public attention to conservation.","zh":"標誌性物種可以吸引公眾關注保育。"},{"en":"Protecting an iconic species may also protect its ecosystem.","zh":"保護標誌性物種也可能保護其生態系統。"},{"en":"The chinstrap penguin is an iconic species for polar wildlife campaigns.","zh":"帽帶企鵝是極地野生動物宣傳中的標誌性物種。"},{"en":"The loss of an iconic species would be deeply symbolic.","zh":"標誌性物種的消失具有深刻象徵意義。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":10},{"front":"new research shows how","meaning":"新研究顯示……如何","examples":[{"en":"New research shows how warming affects penguin colonies.","zh":"新研究顯示暖化如何影響企鵝群落。"},{"en":"New research shows how sea ice supports krill.","zh":"新研究顯示海冰如何支持磷蝦。"},{"en":"New research shows how climate change reaches remote wildlife.","zh":"新研究顯示氣候變化如何影響偏遠野生動物。"},{"en":"New research shows how drone surveys improve counting accuracy.","zh":"新研究顯示無人機調查如何提高點算準確性。"},{"en":"New research shows how one species can decline while another increases.","zh":"新研究顯示一個物種如何下降，而另一個物種如何增加。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":10},{"front":"climate emergency","meaning":"氣候緊急狀態","examples":[{"en":"The climate emergency is affecting polar wildlife.","zh":"氣候緊急狀態正在影響極地野生動物。"},{"en":"Campaigners used the term climate emergency to stress urgency.","zh":"倡議者使用氣候緊急狀態一詞強調迫切性。"},{"en":"The climate emergency can be seen in shrinking ice.","zh":"氣候緊急狀態可以從冰面縮小中看出。"},{"en":"Governments are under pressure to respond to the climate emergency.","zh":"政府正面臨壓力，要回應氣候緊急狀態。"},{"en":"The climate emergency threatens ecosystems far from cities.","zh":"氣候緊急狀態威脅遠離城市的生態系統。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":10},{"front":"decimate their numbers","meaning":"大幅削減牠們的數量","examples":[{"en":"Food shortages can decimate their numbers.","zh":"食物短缺可以大幅削減牠們的數量。"},{"en":"Repeated breeding failure may decimate their numbers over time.","zh":"反覆繁殖失敗可能隨時間大幅削減牠們的數量。"},{"en":"Climate change could decimate their numbers if krill decline continues.","zh":"如果磷蝦持續下降，氣候變化可能大幅削減牠們的數量。"},{"en":"A severe storm can decimate their numbers in one season.","zh":"嚴重風暴可以在一個季節內大幅削減牠們的數量。"},{"en":"Conservationists fear that warming oceans will decimate their numbers.","zh":"保育人士擔心變暖海洋會大幅削減牠們的數量。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":10},{"front":"far-reaching impacts on","meaning":"對……造成深遠影響","examples":[{"en":"Climate change has far-reaching impacts on Antarctic wildlife.","zh":"氣候變化對南極野生動物造成深遠影響。"},{"en":"Ocean warming can have far-reaching impacts on food webs.","zh":"海洋變暖可以對食物網造成深遠影響。"},{"en":"Reduced sea ice has far-reaching impacts on krill and predators.","zh":"海冰減少對磷蝦和捕食者造成深遠影響。"},{"en":"Human activity can have far-reaching impacts on marine life.","zh":"人類活動可以對海洋生物造成深遠影響。"},{"en":"The treaty could have far-reaching impacts on ocean protection.","zh":"該條約可能對海洋保護造成深遠影響。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":10},{"front":"wildlife","meaning":"野生動物","examples":[{"en":"Antarctic wildlife is vulnerable to rapid warming.","zh":"南極野生動物容易受快速暖化影響。"},{"en":"The expedition documented threats to wildlife.","zh":"考察隊記錄對野生動物的威脅。"},{"en":"Wildlife in remote regions can still be affected by human activity.","zh":"偏遠地區的野生動物仍可受人類活動影響。"},{"en":"Protecting wildlife often means protecting entire habitats.","zh":"保護野生動物通常意味保護整個棲息地。"},{"en":"Penguins are among the most recognisable Antarctic wildlife.","zh":"企鵝是最易辨認的南極野生動物之一。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":10},{"front":"the most remote corners of Earth","meaning":"地球最偏遠的角落","examples":[{"en":"Climate change reaches the most remote corners of Earth.","zh":"氣候變化影響到地球最偏遠的角落。"},{"en":"Scientists travel to the most remote corners of Earth for fieldwork.","zh":"科學家前往地球最偏遠的角落進行野外工作。"},{"en":"Pollution can be found in the most remote corners of Earth.","zh":"污染可在地球最偏遠的角落被發現。"},{"en":"Wildlife in the most remote corners of Earth is not fully protected.","zh":"地球最偏遠角落的野生動物並未完全受保護。"},{"en":"The survey took place in one of the most remote corners of Earth.","zh":"該調查在地球最偏遠角落之一進行。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":10},{"front":"a critical year for","meaning":"對……來說關鍵的一年","examples":[{"en":"This is a critical year for ocean protection.","zh":"這是海洋保護關鍵的一年。"},{"en":"The next breeding season may be a critical year for the colony.","zh":"下一個繁殖季可能是該群落關鍵的一年。"},{"en":"2025 was described as a critical year for climate action.","zh":"2025年被描述為氣候行動關鍵的一年。"},{"en":"A critical year for policy can shape decades of conservation.","zh":"對政策來說關鍵的一年可以塑造數十年的保育。"},{"en":"Scientists called it a critical year for Antarctic research.","zh":"科學家稱這是南極研究關鍵的一年。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":11},{"front":"respond to the science","meaning":"回應科學證據","examples":[{"en":"Governments must respond to the science with stronger policy.","zh":"政府必須以更強政策回應科學證據。"},{"en":"The treaty should respond to the science, not political delay.","zh":"該條約應回應科學證據，而不是政治拖延。"},{"en":"Campaigners asked leaders to respond to the science quickly.","zh":"倡議者要求領袖迅速回應科學證據。"},{"en":"If the data are clear, officials should respond to the science.","zh":"如果數據清楚，官員應回應科學證據。"},{"en":"Conservation plans need to respond to the science on climate change.","zh":"保育計劃需要回應關於氣候變化的科學證據。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":11},{"front":"agree on","meaning":"就……達成共識","examples":[{"en":"Governments need to agree on stronger ocean rules.","zh":"政府需要就更強海洋規則達成共識。"},{"en":"Scientists and campaigners agree on the need for protection.","zh":"科學家和倡議者就保護需要達成共識。"},{"en":"Countries failed to agree on the treaty deadline.","zh":"各國未能就條約期限達成共識。"},{"en":"Negotiators worked late to agree on final wording.","zh":"談判者工作至深夜，以就最終措辭達成共識。"},{"en":"It is difficult to agree on policy when interests conflict.","zh":"當利益衝突時，很難就政策達成共識。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":11},{"front":"Global Ocean Treaty","meaning":"全球海洋條約","examples":[{"en":"A Global Ocean Treaty could protect marine life.","zh":"全球海洋條約可以保護海洋生物。"},{"en":"Campaigners urged governments to support a Global Ocean Treaty.","zh":"倡議者敦促政府支持全球海洋條約。"},{"en":"A strong Global Ocean Treaty may create ocean sanctuaries.","zh":"強而有力的全球海洋條約可能建立海洋保護區。"},{"en":"Negotiations for a Global Ocean Treaty attracted international attention.","zh":"全球海洋條約談判引起國際關注。"},{"en":"Scientists said a Global Ocean Treaty should reflect climate evidence.","zh":"科學家說全球海洋條約應反映氣候證據。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":11},{"front":"at the United Nations","meaning":"在聯合國","examples":[{"en":"Governments discussed ocean protection at the United Nations.","zh":"政府在聯合國討論海洋保護。"},{"en":"The treaty was debated at the United Nations.","zh":"該條約在聯合國被辯論。"},{"en":"Campaigners presented scientific evidence at the United Nations.","zh":"倡議者在聯合國提交科學證據。"},{"en":"Negotiators met at the United Nations to discuss marine life.","zh":"談判者在聯合國會面討論海洋生物。"},{"en":"A decision at the United Nations could affect global oceans.","zh":"聯合國的決定可能影響全球海洋。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":11},{"front":"create a network of","meaning":"建立一個……網絡","examples":[{"en":"The treaty could create a network of ocean sanctuaries.","zh":"該條約可以建立一個海洋保護區網絡。"},{"en":"Scientists want to create a network of monitoring stations.","zh":"科學家希望建立一個監察站網絡。"},{"en":"Conservationists hope to create a network of protected habitats.","zh":"保育人士希望建立一個受保護棲息地網絡。"},{"en":"Universities created a network of polar researchers.","zh":"大學建立了一個極地研究人員網絡。"},{"en":"The project aims to create a network of long-term survey sites.","zh":"該項目旨在建立一個長期調查地點網絡。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":11},{"front":"ocean sanctuaries","meaning":"海洋保護區","examples":[{"en":"Ocean sanctuaries can reduce pressure on marine life.","zh":"海洋保護區可以減少海洋生物承受的壓力。"},{"en":"The campaign called for more ocean sanctuaries.","zh":"該運動呼籲建立更多海洋保護區。"},{"en":"Ocean sanctuaries may protect feeding areas for penguins.","zh":"海洋保護區可能保護企鵝覓食區。"},{"en":"A network of ocean sanctuaries could help species adapt.","zh":"海洋保護區網絡可以幫助物種適應。"},{"en":"Ocean sanctuaries need clear rules and enforcement.","zh":"海洋保護區需要清晰規則和執法。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":11},{"front":"marine life","meaning":"海洋生物","examples":[{"en":"Marine life depends on healthy oceans.","zh":"海洋生物依賴健康海洋。"},{"en":"Plastic pollution threatens marine life.","zh":"塑膠污染威脅海洋生物。"},{"en":"Ocean sanctuaries can protect marine life from disturbance.","zh":"海洋保護區可以保護海洋生物免受干擾。"},{"en":"Penguins are part of a wider system of marine life.","zh":"企鵝是更廣泛海洋生物系統的一部分。"},{"en":"Climate change is altering conditions for marine life.","zh":"氣候變化正在改變海洋生物的生存條件。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":11},{"front":"help these creatures adapt to","meaning":"幫助這些生物適應……","examples":[{"en":"Protected areas may help these creatures adapt to climate change.","zh":"保護區可能幫助這些生物適應氣候變化。"},{"en":"Reducing human pressure can help these creatures adapt to warmer oceans.","zh":"減少人類壓力可以幫助這些生物適應變暖海洋。"},{"en":"More food protection may help these creatures adapt to environmental stress.","zh":"更多食物保護可能幫助這些生物適應環境壓力。"},{"en":"Scientists hope sanctuaries will help these creatures adapt to rapid change.","zh":"科學家希望保護區幫助這些生物適應快速變化。"},{"en":"Conservation plans should help these creatures adapt to new conditions.","zh":"保育計劃應幫助這些生物適應新條件。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":11},{"front":"rapidly changing climate","meaning":"急速變化的氣候","examples":[{"en":"Penguins must survive in a rapidly changing climate.","zh":"企鵝必須在急速變化的氣候中生存。"},{"en":"A rapidly changing climate affects food supply and breeding success.","zh":"急速變化的氣候影響食物供應和繁殖成功率。"},{"en":"Conservation plans must consider a rapidly changing climate.","zh":"保育計劃必須考慮急速變化的氣候。"},{"en":"Marine species may struggle under a rapidly changing climate.","zh":"海洋物種在急速變化的氣候下可能很吃力。"},{"en":"The rapidly changing climate makes old records especially valuable.","zh":"急速變化的氣候令舊紀錄尤其有價值。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":11},{"front":"contains the following information","meaning":"包含以下資料","examples":[{"en":"The question asks which paragraph contains the following information.","zh":"題目詢問哪一段包含以下資料。"},{"en":"A paragraph may contain the following information in paraphrased form.","zh":"段落可能以改寫形式包含以下資料。"},{"en":"Students should scan carefully for the section that contains the following information.","zh":"學生應仔細掃讀包含以下資料的部分。"},{"en":"The passage contains the following information about temperature records.","zh":"文章包含以下關於溫度紀錄的資料。"},{"en":"The answer depends on where the text contains the following information.","zh":"答案取決於文本哪裏包含以下資料。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":11},{"front":"write the correct letter","meaning":"寫上正確字母","examples":[{"en":"Students must write the correct letter on the answer sheet.","zh":"學生必須在答題紙上寫上正確字母。"},{"en":"Do not write a word if the task says to write the correct letter.","zh":"如果題目要求寫上正確字母，不要寫詞語。"},{"en":"Candidates write the correct letter after matching the paragraph.","zh":"考生配對段落後寫上正確字母。"},{"en":"The correct letter may be used more than once.","zh":"正確字母可能可使用多於一次。"},{"en":"Check your spelling is not needed when you write the correct letter.","zh":"寫上正確字母時不需要檢查串字。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":11},{"front":"on your answer sheet","meaning":"在答題紙上","examples":[{"en":"Write your answers on your answer sheet.","zh":"把答案寫在答題紙上。"},{"en":"Do not write notes only in the booklet; put answers on your answer sheet.","zh":"不要只在題簿做筆記；要把答案寫在答題紙上。"},{"en":"The examiner will mark what appears on your answer sheet.","zh":"考官會評改你答題紙上的內容。"},{"en":"Transfer the correct letters on your answer sheet carefully.","zh":"小心把正確字母轉寫在答題紙上。"},{"en":"Use pencil if the instructions require it on your answer sheet.","zh":"如果指示要求，請在答題紙上使用鉛筆。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":11},{"front":"may use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"You may use any letter more than once in this task.","zh":"在這題中，你可重複使用任何字母。"},{"en":"If two answers come from the same paragraph, you may use any letter more than once.","zh":"如果兩個答案來自同一段，你可重複使用任何字母。"},{"en":"The instruction says candidates may use any letter more than once.","zh":"指示說考生可重複使用任何字母。"},{"en":"Do not eliminate a paragraph just because you used it; you may use any letter more than once.","zh":"不要因已用過某段而排除它；你可重複使用任何字母。"},{"en":"This task is harder because you may use any letter more than once.","zh":"這題較難，因為你可重複使用任何字母。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":12},{"front":"highest temperatures ever recorded","meaning":"有紀錄以來最高溫","examples":[{"en":"Antarctica recently saw one of the highest temperatures ever recorded.","zh":"南極最近出現有紀錄以來最高溫之一。"},{"en":"The highest temperatures ever recorded can signal unusual climate conditions.","zh":"有紀錄以來最高溫可以顯示異常氣候狀況。"},{"en":"Scientists compare new readings with the highest temperatures ever recorded.","zh":"科學家把新讀數與有紀錄以來最高溫比較。"},{"en":"The report mentioned the highest temperatures ever recorded in the region.","zh":"報告提到該地區有紀錄以來最高溫。"},{"en":"The highest temperatures ever recorded alarmed climate experts.","zh":"有紀錄以來最高溫令氣候專家警覺。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":12},{"front":"current and past records","meaning":"目前與過往紀錄","examples":[{"en":"Researchers compared current and past records of penguin populations.","zh":"研究人員比較企鵝種群的目前與過往紀錄。"},{"en":"Current and past records reveal long-term change.","zh":"目前與過往紀錄揭示長期變化。"},{"en":"The report used current and past records to estimate decline.","zh":"報告使用目前與過往紀錄估算下降幅度。"},{"en":"Current and past records are both needed for conservation planning.","zh":"保育規劃需要目前與過往紀錄。"},{"en":"Differences between current and past records surprised the scientists.","zh":"目前與過往紀錄之間的差異令科學家意外。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":12},{"front":"penguin populations","meaning":"企鵝種群數量","examples":[{"en":"Penguin populations can respond quickly to food shortages.","zh":"企鵝種群數量可以對食物短缺迅速作出反應。"},{"en":"Scientists monitor penguin populations across Antarctica.","zh":"科學家監察南極各地的企鵝種群數量。"},{"en":"Penguin populations are useful indicators of ocean health.","zh":"企鵝種群數量是海洋健康的有用指標。"},{"en":"Some penguin populations decline while others increase.","zh":"一些企鵝種群數量下降，而另一些增加。"},{"en":"Climate change may affect penguin populations differently by species.","zh":"氣候變化可能按物種不同而影響企鵝種群數量。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":12},{"front":"be prohibited from entering","meaning":"被禁止進入","examples":[{"en":"Tourists may be prohibited from entering protected breeding areas.","zh":"遊客可能被禁止進入受保護繁殖區。"},{"en":"Fishing vessels are prohibited from entering some sanctuaries.","zh":"漁船被禁止進入一些保護區。"},{"en":"Visitors were prohibited from entering the beach during nesting season.","zh":"築巢季期間，遊客被禁止進入該海灘。"},{"en":"People may be prohibited from entering fragile wildlife zones.","zh":"人們可能被禁止進入脆弱野生動物區。"},{"en":"Researchers without permits are prohibited from entering the reserve.","zh":"沒有許可的研究人員被禁止進入保護區。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":12},{"front":"places where","meaning":"……居住的地方","examples":[{"en":"The map shows places where chinstrap penguins breed.","zh":"地圖顯示帽帶企鵝繁殖的地方。"},{"en":"Scientists searched for places where krill are abundant.","zh":"科學家尋找磷蝦豐富的地方。"},{"en":"Protected areas include places where wildlife is most vulnerable.","zh":"保護區包括野生動物最脆弱的地方。"},{"en":"The survey focused on places where old records existed.","zh":"調查集中於有舊紀錄的地方。"},{"en":"Tourists should avoid places where birds are nesting.","zh":"遊客應避開鳥類築巢的地方。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":12},{"front":"measures intended to","meaning":"旨在……的措施","examples":[{"en":"The treaty includes measures intended to protect marine life.","zh":"該條約包括旨在保護海洋生物的措施。"},{"en":"The government announced measures intended to reduce pollution.","zh":"政府宣布旨在減少污染的措施。"},{"en":"Scientists proposed measures intended to limit disturbance near colonies.","zh":"科學家提出旨在限制群落附近干擾的措施。"},{"en":"The campaign supports measures intended to safeguard ocean habitats.","zh":"該運動支持旨在保護海洋棲息地的措施。"},{"en":"Measures intended to protect penguins must also protect their food supply.","zh":"旨在保護企鵝的措施也必須保護牠們的食物供應。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":12},{"front":"protect marine species","meaning":"保護海洋物種","examples":[{"en":"Ocean sanctuaries help protect marine species.","zh":"海洋保護區有助保護海洋物種。"},{"en":"Stronger fishing rules can protect marine species.","zh":"更嚴格捕魚規則可以保護海洋物種。"},{"en":"The treaty aims to protect marine species in international waters.","zh":"該條約旨在保護國際水域中的海洋物種。"},{"en":"Scientists urged governments to protect marine species from climate stress.","zh":"科學家敦促政府保護海洋物種免受氣候壓力。"},{"en":"Protecting krill can help protect marine species higher in the food web.","zh":"保護磷蝦可以幫助保護食物網中較高層的海洋物種。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":12},{"front":"factors contributing to","meaning":"導致……的因素","examples":[{"en":"Researchers studied factors contributing to the decline.","zh":"研究人員研究導致下降的因素。"},{"en":"Warmer oceans are among the factors contributing to food shortages.","zh":"變暖的海洋是導致食物短缺的因素之一。"},{"en":"The report listed factors contributing to penguin population change.","zh":"報告列出導致企鵝種群變化的因素。"},{"en":"Reduced sea ice is one of the factors contributing to krill decline.","zh":"海冰減少是導致磷蝦下降的因素之一。"},{"en":"Scientists disagreed about the factors contributing to breeding failure.","zh":"科學家對導致繁殖失敗的因素意見不一。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":12},{"front":"food supply","meaning":"食物供應","examples":[{"en":"Penguins depend on a reliable food supply.","zh":"企鵝依賴可靠食物供應。"},{"en":"Reduced sea ice can affect the food supply.","zh":"海冰減少會影響食物供應。"},{"en":"The chicks struggled when the food supply was low.","zh":"食物供應不足時，雛鳥很難生存。"},{"en":"Researchers measured changes in the food supply near colonies.","zh":"研究人員量度群落附近食物供應的變化。"},{"en":"Protecting krill helps protect the penguins’ food supply.","zh":"保護磷蝦有助保護企鵝的食物供應。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":12},{"front":"a description of","meaning":"對……的描述","examples":[{"en":"The first paragraph gives a description of the penguin.","zh":"第一段提供對該企鵝的描述。"},{"en":"The guide provided a description of the bird’s markings.","zh":"導賞員提供對該鳥標記的描述。"},{"en":"Students wrote a description of the Antarctic habitat.","zh":"學生寫了對南極棲息地的描述。"},{"en":"The report includes a description of the survey method.","zh":"報告包括對調查方法的描述。"},{"en":"A clear description of the species helps readers identify it.","zh":"對物種的清晰描述幫助讀者辨認它。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":12},{"front":"a particular species","meaning":"某一特定物種","examples":[{"en":"The passage begins with a particular species of penguin.","zh":"文章以某一特定企鵝物種開始。"},{"en":"Scientists focused on a particular species during the survey.","zh":"科學家在調查中集中於某一特定物種。"},{"en":"A particular species may respond differently to warming.","zh":"某一特定物種可能對暖化有不同反應。"},{"en":"Conservation plans often target a particular species at risk.","zh":"保育計劃通常針對有風險的某一特定物種。"},{"en":"Students identified a particular species from its feather pattern.","zh":"學生從羽毛圖案辨認某一特定物種。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":12},{"front":"agree with the information given","meaning":"與所給資料一致","examples":[{"en":"Students decide whether each statement agrees with the information given.","zh":"學生判斷每項陳述是否與所給資料一致。"},{"en":"A statement may agree with the information given even if it uses different words.","zh":"即使用詞不同，陳述仍可能與所給資料一致。"},{"en":"Check the passage carefully before saying it agrees with the information given.","zh":"說它與所給資料一致前，要仔細檢查文章。"},{"en":"If a statement agrees with the information given, write TRUE.","zh":"如果陳述與所給資料一致，便寫 TRUE。"},{"en":"Do not use outside knowledge to decide whether it agrees with the information given.","zh":"不要用外部知識判斷它是否與所給資料一致。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":12},{"front":"contradict the information","meaning":"與資料矛盾","examples":[{"en":"A false statement will contradict the information in the text.","zh":"錯誤陳述會與文本資料矛盾。"},{"en":"The answer is FALSE if it contradicts the information.","zh":"如果答案與資料矛盾，便是 FALSE。"},{"en":"One word can make a sentence contradict the information.","zh":"一個字也可以令句子與資料矛盾。"},{"en":"Students should underline the part that contradicts the information.","zh":"學生應劃出與資料矛盾的部分。"},{"en":"Do not choose NOT GIVEN if the statement clearly contradicts the information.","zh":"如果陳述明顯與資料矛盾，不要選 NOT GIVEN。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":13},{"front":"no information on this","meaning":"沒有這方面資料","examples":[{"en":"Write NOT GIVEN if there is no information on this.","zh":"如果沒有這方面資料，便寫 NOT GIVEN。"},{"en":"There may be no information on this even if the statement sounds likely.","zh":"即使陳述聽起來可能，也可能沒有這方面資料。"},{"en":"Students should not guess when there is no information on this.","zh":"當沒有這方面資料時，學生不應猜測。"},{"en":"If the passage gives no information on this, the answer is not TRUE.","zh":"如果文章沒有這方面資料，答案不是 TRUE。"},{"en":"Many candidates confuse FALSE with no information on this.","zh":"許多考生把 FALSE 與沒有這方面資料混淆。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":13},{"front":"show little concern about","meaning":"對……不太關注","examples":[{"en":"The organisation did not show little concern about the new decline.","zh":"該組織並沒有對新的下降不太關注。"},{"en":"Critics said officials seemed to show little concern about wildlife loss.","zh":"批評者說官員似乎對野生動物喪失不太關注。"},{"en":"No conservation group should show little concern about such data.","zh":"任何保育團體都不應對這類數據不太關注。"},{"en":"The statement asks whether the IUCN showed little concern about the decline.","zh":"該陳述詢問 IUCN 是否對下降不太關注。"},{"en":"People may show little concern about remote species until numbers fall sharply.","zh":"人們可能在數量急跌前對偏遠物種不太關注。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":13},{"front":"the decline in numbers","meaning":"數量下降","examples":[{"en":"The decline in numbers worried penguin researchers.","zh":"數量下降令企鵝研究人員擔憂。"},{"en":"Scientists tried to explain the decline in numbers.","zh":"科學家嘗試解釋數量下降。"},{"en":"The decline in numbers was larger than expected.","zh":"數量下降比預期更大。"},{"en":"Climate change may be linked to the decline in numbers.","zh":"氣候變化可能與數量下降有關。"},{"en":"The decline in numbers was clearest in long-term records.","zh":"數量下降在長期紀錄中最清楚。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":13},{"front":"one reason for","meaning":"……的原因之一","examples":[{"en":"Reduced sea ice is one reason for krill decline.","zh":"海冰減少是磷蝦下降的原因之一。"},{"en":"Climate change is one reason for shifting penguin populations.","zh":"氣候變化是企鵝種群轉移的原因之一。"},{"en":"Food shortage may be one reason for breeding failure.","zh":"食物短缺可能是繁殖失敗的原因之一。"},{"en":"Better counting methods are one reason for improved data.","zh":"更好的點算方法是數據改善的原因之一。"},{"en":"Human disturbance can be one reason for colony movement.","zh":"人類干擾可以是群落移動的原因之一。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":13},{"front":"changes in the food chain","meaning":"食物鏈變化","examples":[{"en":"Changes in the food chain can affect penguins quickly.","zh":"食物鏈變化可以迅速影響企鵝。"},{"en":"Scientists linked population decline to changes in the food chain.","zh":"科學家把種群下降與食物鏈變化連繫起來。"},{"en":"Warmer oceans may cause changes in the food chain.","zh":"變暖海洋可能造成食物鏈變化。"},{"en":"Changes in the food chain are often difficult to measure directly.","zh":"食物鏈變化通常難以直接量度。"},{"en":"Krill decline is one sign of changes in the food chain.","zh":"磷蝦下降是食物鏈變化的一個跡象。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":13},{"front":"be affected by","meaning":"受……影響","examples":[{"en":"Penguins can be affected by climate change.","zh":"企鵝會受氣候變化影響。"},{"en":"Krill may be affected by reduced sea ice.","zh":"磷蝦可能受海冰減少影響。"},{"en":"Breeding success is affected by food supply.","zh":"繁殖成功率受食物供應影響。"},{"en":"Remote islands are still affected by global warming.","zh":"偏遠島嶼仍受全球暖化影響。"},{"en":"Marine life can be affected by human activity and pollution.","zh":"海洋生物會受人類活動和污染影響。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":13},{"front":"complete the notes below","meaning":"完成以下筆記","examples":[{"en":"Students must complete the notes below using passage words.","zh":"學生必須使用文章字詞完成以下筆記。"},{"en":"Read the paragraph carefully before you complete the notes below.","zh":"完成以下筆記前，要仔細閱讀段落。"},{"en":"The task asks candidates to complete the notes below with one word.","zh":"題目要求考生用一個詞完成以下筆記。"},{"en":"To complete the notes below, look for keywords in the text.","zh":"要完成以下筆記，應在文本中找關鍵詞。"},{"en":"Do not use your own words when you complete the notes below.","zh":"完成以下筆記時，不要使用自己的字詞。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":13},{"front":"choose one word","meaning":"選擇一個字","examples":[{"en":"The instruction says to choose one word only.","zh":"指示說只可選擇一個字。"},{"en":"Students must choose one word from the passage.","zh":"學生必須從文章中選擇一個字。"},{"en":"If you choose two words, the answer may be wrong.","zh":"如果選擇兩個字，答案可能錯。"},{"en":"Choose one word that fits both meaning and grammar.","zh":"選擇一個同時符合意思和文法的字。"},{"en":"Candidates should choose one word carefully from the relevant sentence.","zh":"考生應從相關句子中小心選擇一個字。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":13},{"front":"record the threat to","meaning":"記錄對……的威脅","examples":[{"en":"The expedition aimed to record the threat to marine life.","zh":"考察旨在記錄對海洋生物的威脅。"},{"en":"Scientists used video to record the threat to penguin habitats.","zh":"科學家用影片記錄對企鵝棲息地的威脅。"},{"en":"The report records the threat to oceans from warming.","zh":"報告記錄暖化對海洋的威脅。"},{"en":"Campaigners record the threat to wildlife to raise awareness.","zh":"倡議者記錄對野生動物的威脅以提高意識。"},{"en":"Satellite images help record the threat to sea ice.","zh":"衛星影像幫助記錄對海冰的威脅。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":13},{"front":"around the world","meaning":"世界各地","examples":[{"en":"Ocean warming affects ecosystems around the world.","zh":"海洋變暖影響世界各地的生態系統。"},{"en":"Researchers share climate data around the world.","zh":"研究人員在世界各地分享氣候數據。"},{"en":"Penguin stories attract attention around the world.","zh":"企鵝故事吸引世界各地的注意。"},{"en":"Marine pollution is a problem around the world.","zh":"海洋污染是世界各地的問題。"},{"en":"Governments around the world must cooperate on ocean protection.","zh":"世界各地政府必須在海洋保護上合作。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":13},{"front":"support the creation of","meaning":"支持建立……","examples":[{"en":"Greenpeace supports the creation of Antarctic sanctuaries.","zh":"綠色和平支持建立南極保護區。"},{"en":"Scientists support the creation of protected feeding areas.","zh":"科學家支持建立受保護覓食區。"},{"en":"The treaty may support the creation of ocean reserves.","zh":"該條約可能支持建立海洋保護區。"},{"en":"Public pressure can support the creation of stronger laws.","zh":"公眾壓力可以支持建立更強法律。"},{"en":"The report supports the creation of long-term monitoring programmes.","zh":"該報告支持建立長期監察計劃。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":13},{"front":"protect surveyed colonies","meaning":"保護已調查的群落","examples":[{"en":"The proposed sanctuaries would protect surveyed colonies.","zh":"擬議保護區將保護已調查的群落。"},{"en":"New rules are needed to protect surveyed colonies from disturbance.","zh":"需要新規則保護已調查的群落免受干擾。"},{"en":"Conservationists want to protect surveyed colonies before numbers fall further.","zh":"保育人士希望在數量進一步下降前保護已調查的群落。"},{"en":"Ocean sanctuaries could protect surveyed colonies and nearby feeding areas.","zh":"海洋保護區可以保護已調查的群落和附近覓食區。"},{"en":"The treaty may help protect surveyed colonies in remote regions.","zh":"該條約可能幫助保護偏遠地區已調查的群落。"}],"source":"Passage 2 Flash Cards 172 - Chinstrap Penguin Population In The Last 50 Years.pdf","sourcePage":13}],"ielts/reading/passage-2/Practice 173":[{"front":"bovids","meaning":"牛科動物","examples":[{"en":"Bovids include cattle, sheep, goats and many antelopes.","zh":"牛科動物包括牛、綿羊、山羊和許多羚羊。"},{"en":"Many bovids have horns and cloven hooves.","zh":"許多牛科動物都有角和分趾蹄。"},{"en":"Bovids live in habitats ranging from forests to deserts.","zh":"牛科動物生活在由森林到沙漠的棲息地。"},{"en":"Some bovids are wild, while others are domestic animals.","zh":"有些牛科動物是野生的，另一些則是家畜。"},{"en":"The passage explains how diverse bovids can be.","zh":"文章解釋牛科動物可以多麼多樣化。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":1},{"front":"family of mammals","meaning":"哺乳動物科","examples":[{"en":"Bovids are a family of mammals with many species.","zh":"牛科動物是一個包含許多物種的哺乳動物科。"},{"en":"This family of mammals includes animals of very different sizes.","zh":"這個哺乳動物科包括體型非常不同的動物。"},{"en":"A family of mammals may contain both wild and domestic species.","zh":"一個哺乳動物科可能包含野生和家養物種。"},{"en":"The bovid family of mammals is especially diverse in Africa.","zh":"牛科這個哺乳動物科在非洲尤其多樣化。"},{"en":"Scientists classify cattle and antelopes within the same family of mammals.","zh":"科學家把牛和羚羊歸入同一個哺乳動物科。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":1},{"front":"order Artiodactyla","meaning":"偶蹄目","examples":[{"en":"Bovids belong to the order Artiodactyla.","zh":"牛科動物屬於偶蹄目。"},{"en":"The order Artiodactyla includes even-toed hoofed mammals.","zh":"偶蹄目包括偶數趾的有蹄哺乳動物。"},{"en":"Giraffes are also placed in the order Artiodactyla.","zh":"長頸鹿也被歸入偶蹄目。"},{"en":"The order Artiodactyla contains many familiar grazing animals.","zh":"偶蹄目包含許多常見的吃草動物。"},{"en":"Classification within the order Artiodactyla helps scientists compare related species.","zh":"偶蹄目中的分類幫助科學家比較相關物種。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":1},{"front":"highly diverse group","meaning":"高度多樣化的群體","examples":[{"en":"Bovids are a highly diverse group of animals.","zh":"牛科動物是一個高度多樣化的動物群體。"},{"en":"A highly diverse group can include species with very different habits.","zh":"高度多樣化的群體可以包括習性非常不同的物種。"},{"en":"Antelopes and cattle show why bovids are a highly diverse group.","zh":"羚羊和牛顯示了為何牛科動物是高度多樣化的群體。"},{"en":"Their habitats make bovids a highly diverse group.","zh":"牠們的棲息地令牛科動物成為高度多樣化的群體。"},{"en":"The passage presents bovids as a highly diverse group of mammals.","zh":"文章把牛科動物呈現為高度多樣化的哺乳動物群體。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":1},{"front":"consist of","meaning":"由……組成","examples":[{"en":"The bovid family consists of many species.","zh":"牛科由許多物種組成。"},{"en":"A herd may consist of females, young animals and one male.","zh":"一個獸群可能由雌性、幼獸和一隻雄性組成。"},{"en":"Their diet may consist of grass, leaves and shoots.","zh":"牠們的飲食可能由草、葉和嫩芽組成。"},{"en":"The group consists of several important subfamilies.","zh":"這個群體由幾個重要亞科組成。"},{"en":"Some habitats consist of open grassland and scattered scrub.","zh":"一些棲息地由開闊草原和零散灌木地組成。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":1},{"front":"domestic animals","meaning":"家畜","examples":[{"en":"Cattle, sheep and goats are important domestic animals.","zh":"牛、綿羊和山羊是重要家畜。"},{"en":"Some bovids became domestic animals thousands of years ago.","zh":"一些牛科動物在數千年前成為家畜。"},{"en":"Domestic animals provide humans with meat, milk and wool.","zh":"家畜為人類提供肉、奶和羊毛。"},{"en":"The passage notes that some bovids are major domestic animals.","zh":"文章指出一些牛科動物是主要家畜。"},{"en":"Domestic animals often differ from their wild ancestors.","zh":"家畜通常與牠們的野生祖先不同。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":1},{"front":"be well represented in","meaning":"在……中分布廣泛","examples":[{"en":"Bovids are well represented in Africa.","zh":"牛科動物在非洲分布廣泛。"},{"en":"This animal family is well represented in Eurasia.","zh":"這個動物科在歐亞大陸分布廣泛。"},{"en":"Antelopes are well represented in open grasslands.","zh":"羚羊在開闊草原中分布廣泛。"},{"en":"Several subfamilies are well represented in the passage.","zh":"文章中多個亞科都有廣泛介紹。"},{"en":"Species adapted to deserts are well represented in some bovid groups.","zh":"適應沙漠的物種在一些牛科群體中分布廣泛。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":1},{"front":"most parts of","meaning":"……大部分地區","examples":[{"en":"Bovids live in most parts of Eurasia.","zh":"牛科動物生活在歐亞大陸大部分地區。"},{"en":"The species is absent from most parts of the island.","zh":"該物種在島上大部分地區都不存在。"},{"en":"Grassland covers most parts of the plain.","zh":"草原覆蓋了平原大部分地區。"},{"en":"Most parts of Africa contain some type of bovid habitat.","zh":"非洲大部分地區都有某種牛科動物棲息地。"},{"en":"The animal can survive in most parts of its range.","zh":"這種動物能在其分布範圍的大部分地區生存。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":1},{"front":"Eurasia","meaning":"歐亞大陸","examples":[{"en":"Many bovids are found in Eurasia.","zh":"許多牛科動物見於歐亞大陸。"},{"en":"Eurasia contains a wide range of climates and habitats.","zh":"歐亞大陸包含廣泛的氣候和棲息地。"},{"en":"Some wild cattle species once lived across Eurasia.","zh":"一些野牛物種曾生活在歐亞大陸各地。"},{"en":"Bovids in Eurasia include sheep, goats and cattle relatives.","zh":"歐亞大陸的牛科動物包括綿羊、山羊和牛的近親。"},{"en":"The distribution of bovids extends through parts of Eurasia.","zh":"牛科動物的分布延伸至歐亞大陸部分地區。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":1},{"front":"Southeast Asia","meaning":"東南亞","examples":[{"en":"Some bovids live on islands in Southeast Asia.","zh":"一些牛科動物生活在東南亞的島嶼上。"},{"en":"Southeast Asia has forests suitable for certain bovid species.","zh":"東南亞有適合某些牛科物種的森林。"},{"en":"The banteng is associated with parts of Southeast Asia.","zh":"爪哇野牛與東南亞部分地區有關。"},{"en":"Bovids in Southeast Asia may live in woodland or grassland.","zh":"東南亞的牛科動物可能生活在林地或草原。"},{"en":"The passage mentions Southeast Asia in describing bovid distribution.","zh":"文章在描述牛科動物分布時提到東南亞。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":1},{"front":"by far","meaning":"遠遠；明顯地","examples":[{"en":"Africa has by far the greatest diversity of bovids.","zh":"非洲遠遠擁有最多樣化的牛科動物。"},{"en":"The bison is by far larger than the royal antelope.","zh":"野牛明顯比倭羚大得多。"},{"en":"This species is by far the fastest in the herd.","zh":"這個物種明顯是群體中跑得最快的。"},{"en":"By far the most common habitat is open grassland.","zh":"最常見的棲息地明顯是開闊草原。"},{"en":"Antelopes are by far the most familiar wild bovids to many readers.","zh":"對許多讀者而言，羚羊明顯是最熟悉的野生牛科動物。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":1},{"front":"numerous and diverse","meaning":"數量多且種類多樣","examples":[{"en":"Bovids are especially numerous and diverse in Africa.","zh":"牛科動物在非洲尤其數量多且種類多樣。"},{"en":"Antelopes are numerous and diverse on open plains.","zh":"羚羊在開闊平原上數量多且種類多樣。"},{"en":"A numerous and diverse group may occupy many habitats.","zh":"數量多且種類多樣的群體可能佔據許多棲息地。"},{"en":"The family is both numerous and diverse compared with some others.","zh":"與一些其他動物科相比，這個科數量多且種類多樣。"},{"en":"Africa’s bovids are numerous and diverse because habitats vary greatly.","zh":"非洲牛科動物數量多且種類多樣，因為棲息地差異很大。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":1},{"front":"solitary","meaning":"獨居的","examples":[{"en":"Some duikers are solitary animals.","zh":"一些遁羚是獨居動物。"},{"en":"A solitary bovid may live alone in thick forest.","zh":"獨居的牛科動物可能獨自生活在茂密森林中。"},{"en":"Solitary species often avoid large herds.","zh":"獨居物種通常避開大型獸群。"},{"en":"The royal antelope is small and often solitary.","zh":"倭羚體型細小，通常獨居。"},{"en":"Solitary animals may be harder to observe in the wild.","zh":"獨居動物在野外可能較難觀察。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":1},{"front":"live in large groups","meaning":"群居","examples":[{"en":"Some bovids live in large groups on open plains.","zh":"一些牛科動物在開闊平原上群居。"},{"en":"Animals that live in large groups can watch for predators together.","zh":"群居動物可以一起留意掠食者。"},{"en":"Gazelles often live in large groups during migration.","zh":"瞪羚在遷徙期間常常群居。"},{"en":"Species that live in large groups may develop social rules.","zh":"群居物種可能發展出社會規則。"},{"en":"Bovids that live in large groups are easier to spot from far away.","zh":"群居的牛科動物從遠處較容易被看見。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":2},{"front":"complex social structures","meaning":"複雜社會結構","examples":[{"en":"Some bovids have complex social structures.","zh":"一些牛科動物有複雜社會結構。"},{"en":"Complex social structures may include leaders, rivals and family groups.","zh":"複雜社會結構可能包括領袖、競爭者和家庭群體。"},{"en":"Herds with complex social structures can be difficult to study.","zh":"擁有複雜社會結構的獸群可能難以研究。"},{"en":"Large groups sometimes develop complex social structures.","zh":"大型群體有時會發展出複雜社會結構。"},{"en":"Complex social structures help animals coordinate movement and defence.","zh":"複雜社會結構幫助動物協調移動和防禦。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":2},{"front":"adapt to","meaning":"適應……","examples":[{"en":"Bovids adapt to many different habitats.","zh":"牛科動物適應許多不同棲息地。"},{"en":"Some sheep adapt to arid deserts.","zh":"一些羊適應乾旱沙漠。"},{"en":"Musk oxen adapt to cold tundra conditions.","zh":"麝牛適應寒冷苔原環境。"},{"en":"Animals adapt to their environment over many generations.","zh":"動物經過許多世代適應環境。"},{"en":"The sitatunga has adapted to swampy ground.","zh":"澤羚已適應沼澤地。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":2},{"front":"a wide range of habitats","meaning":"廣泛的棲息地","examples":[{"en":"Bovids occupy a wide range of habitats.","zh":"牛科動物佔據廣泛的棲息地。"},{"en":"A wide range of habitats allows many species to survive.","zh":"廣泛的棲息地讓許多物種得以生存。"},{"en":"The family has adapted to a wide range of habitats.","zh":"這個科已適應廣泛的棲息地。"},{"en":"From tundra to forest, bovids use a wide range of habitats.","zh":"從苔原到森林，牛科動物使用廣泛的棲息地。"},{"en":"A wide range of habitats explains the group’s diversity.","zh":"廣泛的棲息地解釋了這個群體的多樣性。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":2},{"front":"arctic tundra","meaning":"北極苔原","examples":[{"en":"Musk oxen can survive in arctic tundra.","zh":"麝牛能在北極苔原中生存。"},{"en":"Arctic tundra is cold, open and difficult for many animals.","zh":"北極苔原寒冷、開闊，對許多動物而言很艱難。"},{"en":"Few bovids are adapted to arctic tundra.","zh":"很少牛科動物適應北極苔原。"},{"en":"Thick coats help animals live in arctic tundra.","zh":"厚毛幫助動物生活在北極苔原。"},{"en":"The passage mentions arctic tundra as an extreme habitat.","zh":"文章把北極苔原列為極端棲息地。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":2},{"front":"deep tropical forests","meaning":"熱帶森林深處","examples":[{"en":"Some bovids live in deep tropical forests.","zh":"一些牛科動物生活在熱帶森林深處。"},{"en":"Deep tropical forests provide cover for small solitary species.","zh":"熱帶森林深處為細小獨居物種提供掩護。"},{"en":"Duikers are often found in deep tropical forests.","zh":"遁羚常見於熱帶森林深處。"},{"en":"Animals in deep tropical forests may be hard to observe.","zh":"熱帶森林深處的動物可能很難觀察。"},{"en":"Deep tropical forests differ greatly from open grasslands.","zh":"熱帶森林深處與開闊草原大不相同。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":2},{"front":"the majority of species","meaning":"大多數物種","examples":[{"en":"The majority of species favour open habitats.","zh":"大多數物種偏好開闊棲息地。"},{"en":"The majority of species in the group are herbivorous.","zh":"這個群體中大多數物種是草食性的。"},{"en":"The majority of species have horns in males.","zh":"大多數物種的雄性都有角。"},{"en":"The majority of species are adapted for browsing or grazing.","zh":"大多數物種適應吃嫩葉或吃草。"},{"en":"The majority of species described in the passage live on land.","zh":"文章描述的大多數物種生活在陸地上。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":2},{"front":"favour open grassland","meaning":"偏好開闊草原","examples":[{"en":"Many bovids favour open grassland.","zh":"許多牛科動物偏好開闊草原。"},{"en":"Antelopes often favour open grassland because they can run fast there.","zh":"羚羊常偏好開闊草原，因為牠們可在那裏快速奔跑。"},{"en":"Species that favour open grassland may live in large herds.","zh":"偏好開闊草原的物種可能群居。"},{"en":"Bovids that favour open grassland need good eyesight.","zh":"偏好開闊草原的牛科動物需要良好視力。"},{"en":"The passage says most bovids favour open grassland, scrub or desert.","zh":"文章指出大多數牛科動物偏好開闊草原、灌木地或沙漠。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":2},{"front":"scrub","meaning":"灌木地","examples":[{"en":"Some bovids live in dry scrub.","zh":"一些牛科動物生活在乾燥灌木地。"},{"en":"Scrub provides food and cover for small antelopes.","zh":"灌木地為小型羚羊提供食物和掩護。"},{"en":"The habitat included grassland, scrub and desert.","zh":"該棲息地包括草原、灌木地和沙漠。"},{"en":"Animals in scrub may browse on leaves and twigs.","zh":"灌木地中的動物可能吃葉和嫩枝。"},{"en":"Scrub can be an important habitat for grazing mammals.","zh":"灌木地可以是吃草哺乳動物的重要棲息地。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":2},{"front":"diversity of habitat","meaning":"棲息地多樣性","examples":[{"en":"The diversity of habitat among bovids is remarkable.","zh":"牛科動物的棲息地多樣性十分驚人。"},{"en":"Diversity of habitat helps explain diversity in form.","zh":"棲息地多樣性有助解釋形態多樣性。"},{"en":"This family shows great diversity of habitat.","zh":"這個科展現出很大的棲息地多樣性。"},{"en":"Diversity of habitat ranges from deserts to tropical forests.","zh":"棲息地多樣性由沙漠延伸至熱帶森林。"},{"en":"Scientists link diversity of habitat with evolutionary adaptation.","zh":"科學家把棲息地多樣性與進化適應聯繫起來。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":2},{"front":"be matched by","meaning":"與……相配；同樣有……","examples":[{"en":"Their habitat diversity is matched by diversity in size.","zh":"牠們的棲息地多樣性同樣有體型多樣性相配。"},{"en":"The animal’s speed is matched by its sharp eyesight.","zh":"這種動物的速度與其敏銳視力相配。"},{"en":"The variety of forms is matched by variety in behaviour.","zh":"形態的多樣性同樣有行為多樣性相配。"},{"en":"The harshness of the habitat is matched by the animal’s toughness.","zh":"棲息地的嚴酷程度與動物的強韌相配。"},{"en":"Their ecological range is matched by physical diversity.","zh":"牠們的生態範圍同樣有身體多樣性相配。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":2},{"front":"diversity in size and form","meaning":"體型和形態的多樣性","examples":[{"en":"Bovids show great diversity in size and form.","zh":"牛科動物展現出很大的體型和形態多樣性。"},{"en":"Diversity in size and form can be seen in antelopes and bison.","zh":"體型和形態的多樣性可見於羚羊和野牛。"},{"en":"The family’s diversity in size and form is striking.","zh":"這個科的體型和形態多樣性十分顯著。"},{"en":"Diversity in size and form reflects adaptation to different habitats.","zh":"體型和形態的多樣性反映對不同棲息地的適應。"},{"en":"Scientists compare species to understand diversity in size and form.","zh":"科學家比較物種以理解體型和形態的多樣性。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":2},{"front":"at one extreme","meaning":"在一個極端","examples":[{"en":"At one extreme is the tiny royal antelope.","zh":"在一個極端是細小的倭羚。"},{"en":"At one extreme, a species may weigh only a few kilograms.","zh":"在一個極端，某個物種可能只重幾公斤。"},{"en":"At one extreme, bovids can be very small.","zh":"在一個極端，牛科動物可以非常細小。"},{"en":"At one extreme, forest species may be shy and solitary.","zh":"在一個極端，森林物種可能害羞而獨居。"},{"en":"At one extreme, the smallest bovids contrast sharply with bison.","zh":"在一個極端，最小的牛科動物與野牛形成鮮明對比。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":2},{"front":"royal antelope","meaning":"倭羚；皇家羚羊","examples":[{"en":"The royal antelope is one of the smallest bovids.","zh":"倭羚是最小的牛科動物之一。"},{"en":"A royal antelope stands only about twenty-five centimetres at the shoulder.","zh":"倭羚肩高只有約二十五厘米。"},{"en":"The royal antelope lives in West Africa.","zh":"倭羚生活在西非。"},{"en":"The passage uses the royal antelope as one size extreme.","zh":"文章用倭羚作為體型的一個極端。"},{"en":"The royal antelope is tiny compared with a bison.","zh":"與野牛相比，倭羚非常細小。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":3},{"front":"stand a mere","meaning":"僅有……高","examples":[{"en":"The royal antelope stands a mere 25 centimetres at the shoulder.","zh":"倭羚肩高僅有25厘米。"},{"en":"Some young animals stand a mere half metre tall.","zh":"一些幼獸僅有半米高。"},{"en":"The tiny calf stood a mere few inches above the grass.","zh":"那隻細小幼獸僅比草高幾英寸。"},{"en":"At birth, the animal may stand a mere short distance from the ground.","zh":"出生時，這種動物離地僅有很短高度。"},{"en":"This species stands a mere fraction of a bison’s height.","zh":"這個物種僅有野牛高度的一小部分。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":3},{"front":"at the shoulder","meaning":"肩高","examples":[{"en":"The animal measures 25 centimetres at the shoulder.","zh":"這種動物肩高25厘米。"},{"en":"Shoulder height is measured at the shoulder.","zh":"肩高是在肩部量度的高度。"},{"en":"A bison can reach over two metres at the shoulder.","zh":"野牛肩高可超過兩米。"},{"en":"Scientists often compare bovids by height at the shoulder.","zh":"科學家常以肩高比較牛科動物。"},{"en":"The royal antelope is very low at the shoulder.","zh":"倭羚的肩高非常低。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":3},{"front":"at the other extreme","meaning":"在另一個極端","examples":[{"en":"At the other extreme is the massively built bison.","zh":"在另一個極端是體格魁梧的野牛。"},{"en":"At the other extreme, some bovids are enormous.","zh":"在另一個極端，一些牛科動物非常巨大。"},{"en":"At the other extreme, bison tower over small antelopes.","zh":"在另一個極端，野牛比小型羚羊高大得多。"},{"en":"At the other extreme, body weight may be very high.","zh":"在另一個極端，體重可能非常高。"},{"en":"At the other extreme, large bovids need strong bodies.","zh":"在另一個極端，大型牛科動物需要強壯身體。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":3},{"front":"massively built","meaning":"體格魁梧的","examples":[{"en":"The bison is a massively built animal.","zh":"野牛是一種體格魁梧的動物。"},{"en":"A massively built body helps the animal survive harsh winters.","zh":"體格魁梧的身體幫助動物熬過嚴冬。"},{"en":"The massively built bovid looked powerful and heavy.","zh":"那隻體格魁梧的牛科動物看起來強壯而沉重。"},{"en":"Bison are massively built compared with gazelles.","zh":"與瞪羚相比，野牛體格魁梧。"},{"en":"A massively built animal may move more slowly than a slender antelope.","zh":"體格魁梧的動物可能比纖細羚羊移動得慢。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":3},{"front":"bison","meaning":"野牛","examples":[{"en":"The bison is one of the largest bovids.","zh":"野牛是最大的牛科動物之一。"},{"en":"Bison live in North America and Europe.","zh":"野牛生活在北美洲和歐洲。"},{"en":"A bison can reach a great shoulder height.","zh":"野牛可以達到很高的肩高。"},{"en":"The passage contrasts the bison with the royal antelope.","zh":"文章把野牛與倭羚作對比。"},{"en":"Bison are massively built grazing mammals.","zh":"野牛是體格魁梧的吃草哺乳動物。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":3},{"front":"shoulder height","meaning":"肩高","examples":[{"en":"The bison can reach a shoulder height of 2.2 metres.","zh":"野牛肩高可達2.2米。"},{"en":"Shoulder height is useful for comparing animal size.","zh":"肩高對比較動物體型很有用。"},{"en":"The royal antelope has a very small shoulder height.","zh":"倭羚肩高非常低。"},{"en":"Researchers recorded the shoulder height of each species.","zh":"研究人員記錄每個物種的肩高。"},{"en":"A large shoulder height makes the bison look imposing.","zh":"高肩高令野牛看起來很威武。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":3},{"front":"despite differences in","meaning":"儘管在……方面有差異","examples":[{"en":"Despite differences in size, bovids share common features.","zh":"儘管在體型方面有差異，牛科動物仍有共同特徵。"},{"en":"Despite differences in habitat, all bovids are ruminants.","zh":"儘管在棲息地方面有差異，所有牛科動物都是反芻動物。"},{"en":"Despite differences in appearance, cattle and antelopes are related.","zh":"儘管在外貌方面有差異，牛和羚羊有親緣關係。"},{"en":"Despite differences in behaviour, they belong to the same family.","zh":"儘管在行為方面有差異，牠們屬於同一科。"},{"en":"Despite differences in horn shape, bovid horns have similar structure.","zh":"儘管在角形方面有差異，牛科動物的角有相似結構。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":3},{"front":"size and appearance","meaning":"體型和外貌","examples":[{"en":"Bovids vary greatly in size and appearance.","zh":"牛科動物在體型和外貌上差異很大。"},{"en":"Size and appearance help distinguish different species.","zh":"體型和外貌有助區分不同物種。"},{"en":"The royal antelope and bison differ in size and appearance.","zh":"倭羚和野牛在體型和外貌上不同。"},{"en":"Scientists compare size and appearance when classifying animals.","zh":"科學家分類動物時會比較體型和外貌。"},{"en":"Size and appearance alone do not explain all relationships.","zh":"單靠體型和外貌不能解釋所有親緣關係。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":3},{"front":"be united by","meaning":"因……而歸為一類","examples":[{"en":"Bovids are united by common anatomical features.","zh":"牛科動物因共同解剖特徵而歸為一類。"},{"en":"These species are united by their ruminant digestion.","zh":"這些物種因反芻消化方式而歸為一類。"},{"en":"The group is united by the possession of horns.","zh":"這個群體因有角而歸為一類。"},{"en":"Animals may be united by shared evolutionary history.","zh":"動物可能因共同進化歷史而歸為一類。"},{"en":"Despite variety, bovids are united by several traits.","zh":"儘管多樣，牛科動物因幾項特徵而歸為一類。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":3},{"front":"common features","meaning":"共同特徵","examples":[{"en":"All bovids share common features.","zh":"所有牛科動物都有共同特徵。"},{"en":"Common features include cloven hooves and ruminant stomachs.","zh":"共同特徵包括分趾蹄和反芻胃。"},{"en":"Horn structure is one of their common features.","zh":"角的結構是牠們的共同特徵之一。"},{"en":"Scientists use common features to classify animals.","zh":"科學家利用共同特徵來分類動物。"},{"en":"These common features unite very different species.","zh":"這些共同特徵把非常不同的物種聯繫起來。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":3},{"front":"ruminants","meaning":"反芻動物","examples":[{"en":"Bovids are ruminants.","zh":"牛科動物是反芻動物。"},{"en":"Ruminants digest food in a specialised way.","zh":"反芻動物以特殊方式消化食物。"},{"en":"Cattle, sheep and goats are ruminants.","zh":"牛、綿羊和山羊都是反芻動物。"},{"en":"Ruminants can regurgitate food and chew it again.","zh":"反芻動物可以把食物反吐出來再咀嚼。"},{"en":"The passage states that all bovid species are ruminants.","zh":"文章指出所有牛科物種都是反芻動物。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":3},{"front":"retain undigested food","meaning":"保留未消化食物","examples":[{"en":"Ruminants retain undigested food in their stomachs.","zh":"反芻動物在胃中保留未消化食物。"},{"en":"Bovids retain undigested food before chewing it again.","zh":"牛科動物在再次咀嚼前保留未消化食物。"},{"en":"Animals that retain undigested food can process tough plants effectively.","zh":"能保留未消化食物的動物可以有效處理堅韌植物。"},{"en":"Special stomach chambers help them retain undigested food.","zh":"特殊胃室幫助牠們保留未消化食物。"},{"en":"The ability to retain undigested food supports grazing and browsing.","zh":"保留未消化食物的能力支持吃草和吃嫩葉。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":3},{"front":"regurgitate","meaning":"反芻；使食物回到口中","examples":[{"en":"Bovids regurgitate food when necessary.","zh":"牛科動物有需要時會反芻食物。"},{"en":"Ruminants regurgitate plant material and chew it again.","zh":"反芻動物會把植物材料反芻出來再咀嚼。"},{"en":"The cow began to regurgitate its food after grazing.","zh":"那頭牛吃草後開始反芻。"},{"en":"Animals that regurgitate food can digest grass more efficiently.","zh":"能反芻食物的動物可以更有效消化草。"},{"en":"The ability to regurgitate is part of ruminant digestion.","zh":"反芻能力是反芻消化的一部分。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":4},{"front":"almost exclusively herbivorous","meaning":"幾乎完全草食的","examples":[{"en":"Bovids are almost exclusively herbivorous.","zh":"牛科動物幾乎完全草食。"},{"en":"An almost exclusively herbivorous animal feeds mainly on plants.","zh":"幾乎完全草食的動物主要以植物為食。"},{"en":"Most antelopes are almost exclusively herbivorous.","zh":"大多數羚羊幾乎完全草食。"},{"en":"The passage notes that bovids are almost exclusively herbivorous.","zh":"文章指出牛科動物幾乎完全草食。"},{"en":"Duikers are unusual because some are not almost exclusively herbivorous.","zh":"遁羚很特殊，因為有些並非幾乎完全草食。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":4},{"front":"highly modified for","meaning":"高度適應於……","examples":[{"en":"Bovid teeth are highly modified for grazing.","zh":"牛科動物的牙齒高度適應於吃草。"},{"en":"Their mouths are highly modified for cropping vegetation.","zh":"牠們的口部高度適應於咬斷植物。"},{"en":"Hooves may be highly modified for swampy ground.","zh":"蹄可能高度適應於沼澤地。"},{"en":"Horns are highly modified for display and defence.","zh":"角高度適應於展示和防禦。"},{"en":"The animal’s body is highly modified for life on cliffs.","zh":"這種動物的身體高度適應於峭壁生活。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":4},{"front":"browsing and grazing","meaning":"吃嫩葉和吃草","examples":[{"en":"Bovid teeth are adapted for browsing and grazing.","zh":"牛科動物的牙齒適應吃嫩葉和吃草。"},{"en":"Browsing and grazing require strong cheek teeth.","zh":"吃嫩葉和吃草需要強壯頰齒。"},{"en":"Antelopes may switch between browsing and grazing.","zh":"羚羊可能在吃嫩葉和吃草之間轉換。"},{"en":"The habitat supports both browsing and grazing animals.","zh":"該棲息地支持吃嫩葉和吃草的動物。"},{"en":"Bovids use their lips and teeth during browsing and grazing.","zh":"牛科動物在吃嫩葉和吃草時使用嘴唇和牙齒。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":4},{"front":"foliage","meaning":"葉子；植物葉叢","examples":[{"en":"Many bovids feed on grass and foliage.","zh":"許多牛科動物以草和葉子為食。"},{"en":"Foliage provides food for browsing animals.","zh":"植物葉叢為吃嫩葉的動物提供食物。"},{"en":"The antelope stretched its neck to reach foliage.","zh":"那隻羚羊伸長脖子去吃葉子。"},{"en":"Forest bovids often depend on foliage.","zh":"森林牛科動物常依賴植物葉叢。"},{"en":"Dry seasons can reduce the amount of fresh foliage.","zh":"旱季可能減少新鮮葉子的數量。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":4},{"front":"be cropped with","meaning":"以……咬斷","examples":[{"en":"Grass is cropped with the lips and lower incisors.","zh":"草以嘴唇和下門齒咬斷。"},{"en":"Foliage may be cropped with the upper lip.","zh":"葉子可能以上唇咬斷。"},{"en":"Vegetation is cropped with specialised teeth.","zh":"植物以特化牙齒咬斷。"},{"en":"Tough grass can be cropped with strong mouth parts.","zh":"堅韌的草可以用強壯口部咬斷。"},{"en":"Food is cropped with the animal’s lips before being chewed.","zh":"食物先以動物的嘴唇咬斷，然後被咀嚼。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":4},{"front":"upper lip","meaning":"上唇","examples":[{"en":"Bovids use the upper lip to crop vegetation.","zh":"牛科動物使用上唇咬斷植物。"},{"en":"The upper lip helps pull grass into the mouth.","zh":"上唇幫助把草拉入口中。"},{"en":"A flexible upper lip is useful for browsing.","zh":"靈活的上唇對吃嫩葉很有用。"},{"en":"The animal pressed its upper lip against the leaves.","zh":"那隻動物用上唇貼住葉子。"},{"en":"The upper lip works with the lower incisors.","zh":"上唇與下門齒配合。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":4},{"front":"lower incisors","meaning":"下門齒","examples":[{"en":"Bovids crop grass with their lower incisors.","zh":"牛科動物用下門齒咬斷草。"},{"en":"Lower incisors help cut vegetation.","zh":"下門齒幫助切斷植物。"},{"en":"The lower incisors press against the upper lip.","zh":"下門齒壓向上唇。"},{"en":"Strong lower incisors are useful for grazing.","zh":"強壯的下門齒對吃草很有用。"},{"en":"Bovids usually lack upper incisors but have lower incisors.","zh":"牛科動物通常沒有上門齒，但有下門齒。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":4},{"front":"upper incisors","meaning":"上門齒","examples":[{"en":"Upper incisors are usually absent in bovids.","zh":"牛科動物通常沒有上門齒。"},{"en":"The absence of upper incisors affects how bovids crop grass.","zh":"缺少上門齒會影響牛科動物咬斷草的方式。"},{"en":"Instead of upper incisors, bovids use the upper lip.","zh":"牛科動物不用上門齒，而使用上唇。"},{"en":"Scientists note that upper incisors are missing in many ruminants.","zh":"科學家指出許多反芻動物缺少上門齒。"},{"en":"Lack of upper incisors is one common bovid feature.","zh":"缺少上門齒是牛科動物的一個共同特徵。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":4},{"front":"be ground down by","meaning":"被……磨碎","examples":[{"en":"Food is ground down by the cheek teeth.","zh":"食物被頰齒磨碎。"},{"en":"Tough grass is ground down by strong teeth.","zh":"堅韌的草被強壯牙齒磨碎。"},{"en":"Plant material must be ground down by repeated chewing.","zh":"植物材料必須透過反覆咀嚼被磨碎。"},{"en":"Leaves are ground down by the animal’s molars.","zh":"葉子被動物的臼齒磨碎。"},{"en":"The food is ground down by specialised chewing surfaces.","zh":"食物被特化咀嚼面磨碎。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":4},{"front":"cheek teeth","meaning":"頰齒","examples":[{"en":"Bovids grind food with their cheek teeth.","zh":"牛科動物用頰齒磨碎食物。"},{"en":"Cheek teeth are important for processing tough plants.","zh":"頰齒對處理堅韌植物很重要。"},{"en":"The cheek teeth wear down from constant grazing.","zh":"頰齒因不斷吃草而磨損。"},{"en":"Strong cheek teeth help ruminants digest vegetation.","zh":"強壯頰齒幫助反芻動物消化植物。"},{"en":"Scientists examine cheek teeth to understand diet.","zh":"科學家檢查頰齒以了解飲食。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":4},{"front":"cloven hooves","meaning":"分趾蹄；裂蹄","examples":[{"en":"Bovids have cloven hooves.","zh":"牛科動物有分趾蹄。"},{"en":"Cloven hooves are divided into two main parts.","zh":"分趾蹄分成兩個主要部分。"},{"en":"Cloven hooves help animals move over uneven ground.","zh":"分趾蹄幫助動物在不平地面上移動。"},{"en":"Cattle and goats both have cloven hooves.","zh":"牛和山羊都有分趾蹄。"},{"en":"Cloven hooves are a common feature of many hoofed mammals.","zh":"分趾蹄是許多有蹄哺乳動物的共同特徵。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":4},{"front":"split hooves","meaning":"裂開的蹄","examples":[{"en":"Cloven hooves are split hooves.","zh":"分趾蹄就是裂開的蹄。"},{"en":"Split hooves can improve balance on rough ground.","zh":"裂開的蹄可以改善在崎嶇地面上的平衡。"},{"en":"Goats use their split hooves on steep slopes.","zh":"山羊在陡坡上使用牠們裂開的蹄。"},{"en":"Split hooves distinguish many bovids from horses.","zh":"裂開的蹄把許多牛科動物與馬區分開。"},{"en":"The animal left marks from its split hooves in the mud.","zh":"那隻動物在泥中留下裂開的蹄印。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":4},{"front":"carry horns","meaning":"長有角","examples":[{"en":"The males of all bovid species carry horns.","zh":"所有牛科物種的雄性都長有角。"},{"en":"Some females also carry horns in certain species.","zh":"某些物種的雌性也長有角。"},{"en":"Animals that carry horns may use them in contests.","zh":"長有角的動物可能在競爭中使用角。"},{"en":"Bovids carry horns with bony cores.","zh":"牛科動物長有帶骨質核心的角。"},{"en":"Large males carry horns that can look impressive.","zh":"大型雄性長有看起來很壯觀的角。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":5},{"front":"bony cores","meaning":"骨質核心","examples":[{"en":"Bovid horns have bony cores.","zh":"牛科動物的角有骨質核心。"},{"en":"Bony cores give the horns strength.","zh":"骨質核心賦予角強度。"},{"en":"A sheath covers the bony cores of the horns.","zh":"外鞘覆蓋着角的骨質核心。"},{"en":"The bony cores are not shed each year.","zh":"骨質核心不會每年脫落。"},{"en":"Scientists can study bony cores in fossil skulls.","zh":"科學家可以研究化石頭骨中的骨質核心。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":5},{"front":"be covered in","meaning":"覆蓋着……","examples":[{"en":"The bony core is covered in horny material.","zh":"骨質核心覆蓋着角質材料。"},{"en":"The animal was covered in thick winter hair.","zh":"這種動物覆蓋着厚厚冬毛。"},{"en":"The ground was covered in hoof prints.","zh":"地面覆蓋着蹄印。"},{"en":"Some horns are covered in a hard sheath.","zh":"一些角覆蓋着堅硬外鞘。"},{"en":"The calf was covered in mud after crossing the swamp.","zh":"幼獸穿過沼澤後滿身覆蓋着泥。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":5},{"front":"sheath of horny material","meaning":"角質外鞘","examples":[{"en":"Bovid horns have a sheath of horny material.","zh":"牛科動物的角有角質外鞘。"},{"en":"The sheath of horny material covers the bony core.","zh":"角質外鞘覆蓋骨質核心。"},{"en":"This sheath of horny material is renewed from within.","zh":"這層角質外鞘由內部更新。"},{"en":"A damaged sheath of horny material may affect the horn’s appearance.","zh":"受損的角質外鞘可能影響角的外觀。"},{"en":"The horn’s sheath of horny material is never shed like antlers.","zh":"角的角質外鞘不像鹿角那樣脫落。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":5},{"front":"be constantly renewed","meaning":"不斷更新","examples":[{"en":"The horn covering is constantly renewed from within.","zh":"角的覆蓋層由內部不斷更新。"},{"en":"The animal’s hair is constantly renewed throughout the year.","zh":"這種動物的毛全年不斷更新。"},{"en":"Horny material is constantly renewed as the horn grows.","zh":"隨着角生長，角質材料不斷更新。"},{"en":"The surface layer is constantly renewed by new growth.","zh":"表面層透過新生長不斷更新。"},{"en":"Because it is constantly renewed, the horn remains strong.","zh":"由於不斷更新，角保持強韌。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":5},{"front":"unbranched","meaning":"不分叉的","examples":[{"en":"Bovid horns are unbranched.","zh":"牛科動物的角是不分叉的。"},{"en":"Unbranched horns do not divide into smaller points.","zh":"不分叉的角不會分成較小分支。"},{"en":"Gazelles have elegant but unbranched horns.","zh":"瞪羚有優美但不分叉的角。"},{"en":"Unbranched horns differ from branched deer antlers.","zh":"不分叉的角不同於分叉的鹿角。"},{"en":"The passage notes that bovid horns are unbranched.","zh":"文章指出牛科動物的角是不分叉的。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":5},{"front":"never shed","meaning":"永不脫落","examples":[{"en":"Bovid horns are never shed.","zh":"牛科動物的角永不脫落。"},{"en":"Unlike deer antlers, these horns are never shed.","zh":"不像鹿角，這些角永不脫落。"},{"en":"Horns that are never shed remain part of the skull.","zh":"永不脫落的角會一直是頭骨的一部分。"},{"en":"The animal’s horns are never shed during adulthood.","zh":"這種動物成年後角永不脫落。"},{"en":"Scientists distinguish horns from antlers because horns are never shed.","zh":"科學家以角永不脫落這一點區分角和鹿角。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":5},{"front":"vary in shape and size","meaning":"在形狀和大小上各異","examples":[{"en":"Bovid horns vary in shape and size.","zh":"牛科動物的角在形狀和大小上各異。"},{"en":"Species vary in shape and size according to habitat.","zh":"物種會按棲息地在形狀和大小上各異。"},{"en":"Antelope horns vary in shape and size across subfamilies.","zh":"不同亞科的羚羊角在形狀和大小上各異。"},{"en":"Hooves vary in shape and size depending on terrain.","zh":"蹄會因地形而在形狀和大小上各異。"},{"en":"The passage explains how bovids vary in shape and size.","zh":"文章解釋牛科動物如何在形狀和大小上各異。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":5},{"front":"Indian buffalo","meaning":"印度水牛","examples":[{"en":"The Indian buffalo can have very large horns.","zh":"印度水牛可以有非常大的角。"},{"en":"An Indian buffalo may measure several metres from horn tip to tip.","zh":"印度水牛兩角尖端之間可能長達數米。"},{"en":"The passage uses the Indian buffalo as an example of horn size.","zh":"文章用印度水牛作為角大小的例子。"},{"en":"Indian buffalo horns curve widely outward.","zh":"印度水牛的角向外大幅彎曲。"},{"en":"The Indian buffalo belongs to the larger bovid forms.","zh":"印度水牛屬於體型較大的牛科形態。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":5},{"front":"from tip to tip","meaning":"從一端到另一端","examples":[{"en":"The horns measured four metres from tip to tip.","zh":"兩角從一端到另一端長四米。"},{"en":"From tip to tip, the buffalo’s horns were enormous.","zh":"從一端到另一端看，水牛的角非常巨大。"},{"en":"Scientists measured the horn span from tip to tip.","zh":"科學家從一端到另一端量度角距。"},{"en":"The distance from tip to tip showed the horn’s full width.","zh":"從一端到另一端的距離顯示角的完整寬度。"},{"en":"From tip to tip, the horns stretched wider than the animal’s body.","zh":"從一端到另一端，兩角比動物身體還寬。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":5},{"front":"along the outer curve","meaning":"沿外側曲線","examples":[{"en":"The horn measured four metres along the outer curve.","zh":"那隻角沿外側曲線長四米。"},{"en":"Scientists measured the buffalo’s horns along the outer curve.","zh":"科學家沿外側曲線量度水牛角。"},{"en":"Along the outer curve, the horn looked even longer.","zh":"沿外側曲線看，角顯得更長。"},{"en":"Horn length can be recorded along the outer curve.","zh":"角長可以沿外側曲線記錄。"},{"en":"The distance along the outer curve differs from a straight-line measurement.","zh":"沿外側曲線的距離不同於直線量度。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":5},{"front":"gazelles","meaning":"瞪羚","examples":[{"en":"Gazelles are graceful antelopes.","zh":"瞪羚是優雅的羚羊。"},{"en":"Gazelles often live in open grasslands.","zh":"瞪羚常生活在開闊草原。"},{"en":"Many gazelles can run at high speed.","zh":"許多瞪羚能高速奔跑。"},{"en":"Gazelles may have horns with elegant curves.","zh":"瞪羚可能有帶優美曲線的角。"},{"en":"Predators often chase gazelles across the plains.","zh":"掠食者常在平原上追逐瞪羚。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":5},{"front":"elegant curves","meaning":"優美曲線","examples":[{"en":"Some gazelles have horns with elegant curves.","zh":"一些瞪羚有帶優美曲線的角。"},{"en":"The elegant curves of the horns make the animal distinctive.","zh":"角的優美曲線令這種動物很有特色。"},{"en":"Elegant curves can be seen in several antelope species.","zh":"幾種羚羊都可見優美曲線。"},{"en":"The horns rose in elegant curves above the head.","zh":"兩角以優美曲線從頭上升起。"},{"en":"Artists often admire the elegant curves of gazelle horns.","zh":"藝術家常欣賞瞪羚角的優美曲線。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":5},{"front":"subfamilies","meaning":"亞科","examples":[{"en":"Bovids are divided into several subfamilies.","zh":"牛科動物被分成幾個亞科。"},{"en":"The passage discusses five bovid subfamilies.","zh":"文章討論五個牛科亞科。"},{"en":"Subfamilies help organise related species.","zh":"亞科有助整理相關物種。"},{"en":"Each of the subfamilies has different characteristics.","zh":"每個亞科都有不同特徵。"},{"en":"Scientists compare subfamilies to study evolution.","zh":"科學家比較亞科以研究進化。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":6},{"front":"be distinguished","meaning":"可被區分","examples":[{"en":"Five main groups may be distinguished.","zh":"五個主要群體可被區分。"},{"en":"Species can be distinguished by horn shape.","zh":"物種可憑角形被區分。"},{"en":"The subfamilies are distinguished by size, habitat and behaviour.","zh":"亞科可憑體型、棲息地和行為被區分。"},{"en":"Bovids may be distinguished from deer by their horns.","zh":"牛科動物可憑其角與鹿區分。"},{"en":"Similar species are sometimes difficult to be distinguished.","zh":"相似物種有時難以被區分。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":6},{"front":"Bovinae","meaning":"牛亞科","examples":[{"en":"Bovinae includes many larger bovids.","zh":"牛亞科包括許多體型較大的牛科動物。"},{"en":"Cattle and bison belong to Bovinae.","zh":"牛和野牛屬於牛亞科。"},{"en":"Members of Bovinae are often non-territorial.","zh":"牛亞科成員通常無領域性。"},{"en":"The passage lists several animals in Bovinae.","zh":"文章列出幾種牛亞科動物。"},{"en":"Bovinae contains important domestic cattle relatives.","zh":"牛亞科包含重要家牛近親。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":6},{"front":"comprise","meaning":"包括；由……組成","examples":[{"en":"Bovinae comprises many large bovids.","zh":"牛亞科包括許多大型牛科動物。"},{"en":"The group comprises cattle, bison and related animals.","zh":"這個群體包括牛、野牛和相關動物。"},{"en":"The family comprises species of many sizes.","zh":"這個科由許多不同體型的物種組成。"},{"en":"This subfamily comprises both wild and domestic forms.","zh":"這個亞科包括野生和家養形態。"},{"en":"The list comprises several examples from the passage.","zh":"這份列表包括文章中的幾個例子。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":6},{"front":"larger bovids","meaning":"體型較大的牛科動物","examples":[{"en":"Bovinae contains many of the larger bovids.","zh":"牛亞科包含許多體型較大的牛科動物。"},{"en":"Larger bovids include bison, cattle and eland.","zh":"體型較大的牛科動物包括野牛、牛和大羚羊。"},{"en":"Larger bovids often have heavy bodies.","zh":"體型較大的牛科動物通常身體沉重。"},{"en":"The passage contrasts larger bovids with tiny antelopes.","zh":"文章把體型較大的牛科動物與細小羚羊作對比。"},{"en":"Larger bovids may need more food than smaller species.","zh":"體型較大的牛科動物可能比小型物種需要更多食物。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":6},{"front":"African bongo","meaning":"非洲邦戈羚","examples":[{"en":"The African bongo belongs to Bovinae.","zh":"非洲邦戈羚屬於牛亞科。"},{"en":"The African bongo is a forest-dwelling antelope.","zh":"非洲邦戈羚是一種森林羚羊。"},{"en":"An African bongo has striking markings on its body.","zh":"非洲邦戈羚身上有醒目的斑紋。"},{"en":"The passage lists the African bongo among larger bovids.","zh":"文章把非洲邦戈羚列於體型較大的牛科動物之中。"},{"en":"The African bongo is one example of bovid diversity.","zh":"非洲邦戈羚是牛科動物多樣性的一個例子。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":6},{"front":"nilgai","meaning":"藍牛羚","examples":[{"en":"The nilgai is included in Bovinae.","zh":"藍牛羚被歸入牛亞科。"},{"en":"The nilgai is sometimes called the blue bull.","zh":"藍牛羚有時被稱為藍牛。"},{"en":"A nilgai can be larger than many antelopes.","zh":"藍牛羚可以比許多羚羊更大。"},{"en":"The passage mentions the nilgai as a bovid example.","zh":"文章提到藍牛羚作為牛科動物例子。"},{"en":"Nilgai live in parts of South Asia.","zh":"藍牛羚生活在南亞部分地區。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":6},{"front":"eland","meaning":"大羚羊","examples":[{"en":"The eland is one of the larger bovids.","zh":"大羚羊是體型較大的牛科動物之一。"},{"en":"An eland can be much heavier than a gazelle.","zh":"大羚羊可以比瞪羚重得多。"},{"en":"Eland belong to the Bovinae group.","zh":"大羚羊屬於牛亞科。"},{"en":"The passage lists eland with other large bovids.","zh":"文章把大羚羊與其他大型牛科動物一起列出。"},{"en":"An eland’s size shows the range within antelope-like animals.","zh":"大羚羊的體型顯示羚羊類動物內部的範圍。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":6},{"front":"cattle","meaning":"牛；家牛","examples":[{"en":"Cattle are members of the bovid family.","zh":"牛是牛科成員。"},{"en":"Domestic cattle are important to human agriculture.","zh":"家牛對人類農業很重要。"},{"en":"Wild relatives of cattle include the gaur and banteng.","zh":"牛的野生近親包括印度野牛和爪哇野牛。"},{"en":"Cattle are ruminants with cloven hooves.","zh":"牛是有分趾蹄的反芻動物。"},{"en":"The ancestors of cattle are rare or extinct in the wild.","zh":"牛的祖先在野外已稀有或滅絕。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":6},{"front":"unlike most other bovids","meaning":"與大多數其他牛科動物不同","examples":[{"en":"Unlike most other bovids, Bovinae members are non-territorial.","zh":"與大多數其他牛科動物不同，牛亞科成員無領域性。"},{"en":"Unlike most other bovids, these animals may not defend fixed areas.","zh":"與大多數其他牛科動物不同，這些動物可能不保衛固定區域。"},{"en":"Unlike most other bovids, some species gather in loose herds.","zh":"與大多數其他牛科動物不同，一些物種聚成鬆散獸群。"},{"en":"Unlike most other bovids, cattle relatives can be less territorial.","zh":"與大多數其他牛科動物不同，牛的近親可能較少領域性。"},{"en":"Unlike most other bovids, this group includes many large domestic forms.","zh":"與大多數其他牛科動物不同，這個群體包括許多大型家養形態。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":6},{"front":"non-territorial","meaning":"無領域性的；不佔地盤的","examples":[{"en":"Members of Bovinae are non-territorial.","zh":"牛亞科成員是無領域性的。"},{"en":"Non-territorial animals do not defend a fixed area.","zh":"無領域性的動物不保衛固定區域。"},{"en":"A non-territorial species may move widely in search of food.","zh":"無領域性的物種可能廣泛移動尋找食物。"},{"en":"Cattle relatives are often described as non-territorial.","zh":"牛的近親常被描述為無領域性的。"},{"en":"Non-territorial behaviour differs from the behaviour of many antelopes.","zh":"無領域性行為不同於許多羚羊的行為。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":6},{"front":"ancestors of","meaning":"……的祖先","examples":[{"en":"The auroch was one of the ancestors of domestic cattle.","zh":"原牛是家牛的祖先之一。"},{"en":"Some ancestors of cattle are now rare.","zh":"牛的一些祖先現在已很稀有。"},{"en":"Scientists study the ancestors of modern livestock.","zh":"科學家研究現代家畜的祖先。"},{"en":"Wild ancestors of domestic animals often look different.","zh":"家養動物的野生祖先通常外貌不同。"},{"en":"The passage mentions several ancestors of domestic cattle.","zh":"文章提到幾種家牛的祖先。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":6},{"front":"domestic cattle","meaning":"家牛","examples":[{"en":"Domestic cattle descended from wild relatives.","zh":"家牛由野生近親演變而來。"},{"en":"Domestic cattle are economically important worldwide.","zh":"家牛在全球經濟上很重要。"},{"en":"The auroch was an ancestor of European domestic cattle.","zh":"原牛是歐洲家牛的祖先。"},{"en":"Domestic cattle are kept for milk, meat and labour.","zh":"家牛被飼養來提供牛奶、肉和勞力。"},{"en":"Several wild species are related to domestic cattle.","zh":"幾種野生物種與家牛有親緣關係。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":6},{"front":"banteng","meaning":"爪哇野牛","examples":[{"en":"The banteng is a wild cattle relative.","zh":"爪哇野牛是野生牛類近親。"},{"en":"Banteng are among the ancestors of domestic cattle.","zh":"爪哇野牛是家牛祖先之一。"},{"en":"The passage lists the banteng with other cattle relatives.","zh":"文章把爪哇野牛與其他牛類近親一起列出。"},{"en":"Banteng populations are threatened in some areas.","zh":"爪哇野牛種群在一些地區受到威脅。"},{"en":"The banteng shows how diverse Bovinae can be.","zh":"爪哇野牛顯示牛亞科可以多麼多樣化。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":7},{"front":"gaur","meaning":"印度野牛","examples":[{"en":"The gaur is a large wild cattle relative.","zh":"印度野牛是一種大型野生牛類近親。"},{"en":"Gaur belong to the Bovinae subfamily.","zh":"印度野牛屬於牛亞科。"},{"en":"The passage mentions the gaur among domestic cattle relatives.","zh":"文章在家牛近親中提到印度野牛。"},{"en":"A gaur can be larger than many domestic cattle.","zh":"印度野牛可以比許多家牛更大。"},{"en":"The gaur is one example of a powerful bovid.","zh":"印度野牛是強壯牛科動物的一個例子。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":7},{"front":"yak","meaning":"犛牛","examples":[{"en":"The yak is related to domestic cattle.","zh":"犛牛與家牛有親緣關係。"},{"en":"Yaks are adapted to cold mountain environments.","zh":"犛牛適應寒冷山地環境。"},{"en":"The passage lists the yak among Bovinae relatives.","zh":"文章把犛牛列為牛亞科近親之一。"},{"en":"Domestic yaks are important to people in high mountains.","zh":"家養犛牛對高山地區的人很重要。"},{"en":"A yak has long hair that helps it survive cold weather.","zh":"犛牛有長毛，幫助牠在寒冷天氣中生存。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":7},{"front":"water buffalo","meaning":"水牛","examples":[{"en":"The water buffalo is a cattle relative.","zh":"水牛是牛類近親。"},{"en":"Water buffalo are important domestic animals in many regions.","zh":"水牛在許多地區是重要家畜。"},{"en":"The passage includes water buffalo in Bovinae.","zh":"文章把水牛列入牛亞科。"},{"en":"Water buffalo can live in wet habitats.","zh":"水牛可以生活在潮濕棲息地。"},{"en":"Farmers often use water buffalo for work in flooded fields.","zh":"農民常用水牛在水浸田地工作。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":7},{"front":"rare and endangered","meaning":"稀有且瀕危","examples":[{"en":"Some cattle ancestors are rare and endangered.","zh":"一些牛的祖先稀有且瀕危。"},{"en":"Rare and endangered species need protection.","zh":"稀有且瀕危物種需要保護。"},{"en":"The passage says several wild relatives are rare and endangered.","zh":"文章指出幾種野生近親稀有且瀕危。"},{"en":"Habitat loss can make animals rare and endangered.","zh":"棲息地喪失會令動物稀有且瀕危。"},{"en":"Conservationists monitor rare and endangered bovids.","zh":"保育人士監測稀有且瀕危的牛科動物。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":7},{"front":"in the wild","meaning":"在野外","examples":[{"en":"Several cattle relatives are endangered in the wild.","zh":"幾種牛類近親在野外瀕危。"},{"en":"The auroch no longer exists in the wild.","zh":"原牛在野外已不存在。"},{"en":"Some domestic animals have rare ancestors in the wild.","zh":"一些家畜在野外有稀有祖先。"},{"en":"Animals in the wild face predators and habitat loss.","zh":"野外動物面對掠食者和棲息地喪失。"},{"en":"Scientists study bovids in the wild to understand natural behaviour.","zh":"科學家研究野外牛科動物，以了解自然行為。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":7},{"front":"auroch","meaning":"原牛","examples":[{"en":"The auroch is now extinct.","zh":"原牛現在已滅絕。"},{"en":"The auroch was an ancestor of European domestic cattle.","zh":"原牛是歐洲家牛的祖先。"},{"en":"Scientists know the auroch from historical records and remains.","zh":"科學家從歷史記錄和遺骸認識原牛。"},{"en":"The passage uses the auroch as an example of extinction.","zh":"文章用原牛作為滅絕例子。"},{"en":"The auroch once lived in the wild.","zh":"原牛曾生活在野外。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":7},{"front":"be extinct","meaning":"已滅絕","examples":[{"en":"The auroch is extinct.","zh":"原牛已滅絕。"},{"en":"A species may become extinct if its habitat disappears.","zh":"如果棲息地消失，物種可能滅絕。"},{"en":"The passage states that the auroch is extinct.","zh":"文章指出原牛已滅絕。"},{"en":"Once a species is extinct, it no longer survives anywhere.","zh":"一個物種滅絕後，便不再在任何地方生存。"},{"en":"Conservation efforts aim to prevent rare bovids from becoming extinct.","zh":"保育工作旨在防止稀有牛科動物滅絕。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":7},{"front":"precise zoological name","meaning":"精確的動物學名稱","examples":[{"en":"Antelope is not a precise zoological name.","zh":"羚羊並不是一個精確的動物學名稱。"},{"en":"A precise zoological name must describe a clear scientific group.","zh":"精確的動物學名稱必須描述清楚的科學群體。"},{"en":"Common names are often less exact than a precise zoological name.","zh":"俗名通常不如精確的動物學名稱準確。"},{"en":"Scientists prefer a precise zoological name when classifying animals.","zh":"科學家分類動物時偏好精確的動物學名稱。"},{"en":"The passage warns that antelope is not a precise zoological name.","zh":"文章提醒羚羊並非精確的動物學名稱。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":7},{"front":"be used loosely","meaning":"被寬泛地使用","examples":[{"en":"The term antelope is used loosely.","zh":"羚羊這個詞被寬泛地使用。"},{"en":"Common animal names are often used loosely.","zh":"常見動物名稱經常被寬泛地使用。"},{"en":"The word may be used loosely to describe several bovids.","zh":"這個詞可能被寬泛地用來描述幾種牛科動物。"},{"en":"When a term is used loosely, it may lack scientific precision.","zh":"當一個詞被寬泛地使用時，它可能缺乏科學精確性。"},{"en":"The passage says antelope is used loosely rather than precisely.","zh":"文章指出羚羊一詞被寬泛使用，而不是精確使用。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":7},{"front":"lines of development","meaning":"發展路線","examples":[{"en":"Different antelopes followed different lines of development.","zh":"不同羚羊走上不同發展路線。"},{"en":"Evolution can produce several lines of development within one family.","zh":"進化可以在同一科內產生幾條發展路線。"},{"en":"The passage compares different lines of development among antelopes.","zh":"文章比較羚羊之間不同的發展路線。"},{"en":"Each line of development produced different body forms.","zh":"每條發展路線產生不同身體形態。"},{"en":"Habitat pressure can influence lines of development.","zh":"棲息地壓力可以影響發展路線。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":7},{"front":"long-legged","meaning":"長腿的","examples":[{"en":"Antelopes are often long-legged animals.","zh":"羚羊通常是長腿動物。"},{"en":"A long-legged body helps an animal run quickly.","zh":"長腿身體幫助動物快速奔跑。"},{"en":"Long-legged species are common on open grasslands.","zh":"長腿物種常見於開闊草原。"},{"en":"The long-legged antelope escaped across the plain.","zh":"那隻長腿羚羊越過平原逃走。"},{"en":"Many fast-running bovids are long-legged.","zh":"許多跑得快的牛科動物都是長腿的。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":7},{"front":"fast-running species","meaning":"跑得快的物種","examples":[{"en":"Many antelopes are fast-running species.","zh":"許多羚羊是跑得快的物種。"},{"en":"Fast-running species can escape predators on open plains.","zh":"跑得快的物種可以在開闊平原上逃離掠食者。"},{"en":"Gazelles are examples of fast-running species.","zh":"瞪羚是跑得快的物種例子。"},{"en":"Fast-running species often have slender bodies.","zh":"跑得快的物種通常有纖細身體。"},{"en":"The passage associates antelopes with fast-running species.","zh":"文章把羚羊與跑得快的物種聯繫起來。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":7},{"front":"be laid along","meaning":"沿着……放平","examples":[{"en":"Some horns may be laid along the back during flight.","zh":"一些角在逃跑時可能沿着背部放平。"},{"en":"The antelope’s horns can be laid along its body.","zh":"羚羊的角可以沿着身體放平。"},{"en":"Horns laid along the back reduce resistance while running.","zh":"沿背部放平的角可減少奔跑時的阻力。"},{"en":"The animal’s ears were laid along its head in fear.","zh":"那隻動物因恐懼把耳朵沿頭部放平。"},{"en":"In full flight, the horns may be laid along the back.","zh":"全速逃跑時，角可能沿背部放平。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":8},{"front":"in full flight","meaning":"全速逃跑時","examples":[{"en":"The antelope lowered its horns in full flight.","zh":"羚羊在全速逃跑時放低了角。"},{"en":"In full flight, the herd crossed the plain quickly.","zh":"全速逃跑時，獸群迅速穿過平原。"},{"en":"A gazelle in full flight can be difficult to catch.","zh":"全速逃跑時的瞪羚可能很難被抓住。"},{"en":"The animal’s body stretched forward in full flight.","zh":"那隻動物全速逃跑時身體向前伸展。"},{"en":"Horns may lie back when the animal is in full flight.","zh":"動物全速逃跑時，角可能向後貼伏。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":8},{"front":"main subgroups","meaning":"主要亞群","examples":[{"en":"Antelopes have two main subgroups.","zh":"羚羊有兩個主要亞群。"},{"en":"The passage identifies main subgroups within the antelope category.","zh":"文章指出羚羊類別中的主要亞群。"},{"en":"Main subgroups help organise similar animals.","zh":"主要亞群有助整理相似動物。"},{"en":"Hippotraginae and Antilopinae are main subgroups.","zh":"馬羚亞科和羚羊亞科是主要亞群。"},{"en":"Students should remember the main subgroups for the matching task.","zh":"學生應記住主要亞群以應付配對題。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":8},{"front":"Hippotraginae","meaning":"馬羚亞科","examples":[{"en":"Hippotraginae includes the oryx and the addax.","zh":"馬羚亞科包括劍羚和旋角羚。"},{"en":"Animals in Hippotraginae are antelope relatives.","zh":"馬羚亞科中的動物是羚羊近親。"},{"en":"The passage names Hippotraginae as one main subgroup.","zh":"文章把馬羚亞科列為一個主要亞群。"},{"en":"Hippotraginae contains species adapted to open habitats.","zh":"馬羚亞科包含適應開闊棲息地的物種。"},{"en":"Students may need to match oryx with Hippotraginae.","zh":"學生可能需要把劍羚與馬羚亞科配對。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":8},{"front":"oryx","meaning":"劍羚","examples":[{"en":"The oryx belongs to Hippotraginae.","zh":"劍羚屬於馬羚亞科。"},{"en":"Oryx are antelopes adapted to dry conditions.","zh":"劍羚是適應乾燥環境的羚羊。"},{"en":"The passage lists the oryx with the addax.","zh":"文章把劍羚與旋角羚一起列出。"},{"en":"An oryx has long, straight horns.","zh":"劍羚有長而直的角。"},{"en":"The oryx is a good example of a desert-adapted antelope.","zh":"劍羚是適應沙漠的羚羊好例子。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":8},{"front":"addax","meaning":"旋角羚","examples":[{"en":"The addax belongs to Hippotraginae.","zh":"旋角羚屬於馬羚亞科。"},{"en":"Addax are antelopes associated with desert environments.","zh":"旋角羚是與沙漠環境有關的羚羊。"},{"en":"The passage mentions the addax as a subgroup example.","zh":"文章提到旋角羚作為亞群例子。"},{"en":"An addax can survive in very dry habitats.","zh":"旋角羚可以在非常乾燥的棲息地生存。"},{"en":"The addax shows how antelopes adapt to harsh conditions.","zh":"旋角羚顯示羚羊如何適應嚴酷環境。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":8},{"front":"Antilopinae","meaning":"羚羊亞科","examples":[{"en":"Antilopinae contains slighter and more graceful animals.","zh":"羚羊亞科包含較纖細且較優雅的動物。"},{"en":"Springboks are included in Antilopinae.","zh":"跳羚包括在羚羊亞科中。"},{"en":"The passage contrasts Antilopinae with Hippotraginae.","zh":"文章把羚羊亞科與馬羚亞科作對比。"},{"en":"Antilopinae includes many elegant antelope species.","zh":"羚羊亞科包括許多優雅羚羊物種。"},{"en":"Students should associate graceful forms with Antilopinae.","zh":"學生應把優雅形態與羚羊亞科聯繫起來。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":8},{"front":"slighter and more graceful","meaning":"較纖細且較優雅","examples":[{"en":"Antilopinae animals are often slighter and more graceful.","zh":"羚羊亞科動物通常較纖細且較優雅。"},{"en":"A slighter and more graceful body helps with speed.","zh":"較纖細且較優雅的身體有助速度。"},{"en":"Springboks look slighter and more graceful than cattle.","zh":"跳羚看起來比牛較纖細且較優雅。"},{"en":"The passage describes this subgroup as slighter and more graceful.","zh":"文章描述這個亞群較纖細且較優雅。"},{"en":"Slighter and more graceful antelopes are common on open plains.","zh":"較纖細且較優雅的羚羊常見於開闊平原。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":8},{"front":"springboks","meaning":"跳羚","examples":[{"en":"Springboks are members of Antilopinae.","zh":"跳羚是羚羊亞科成員。"},{"en":"Springboks are famous for graceful movement.","zh":"跳羚以優雅動作聞名。"},{"en":"The passage lists springboks among lighter antelopes.","zh":"文章把跳羚列於較輕盈羚羊之中。"},{"en":"Springboks can move quickly across grassland.","zh":"跳羚可以迅速穿過草原。"},{"en":"Springboks are often associated with open plains.","zh":"跳羚常與開闊平原聯繫起來。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":8},{"front":"grassland species","meaning":"草原物種","examples":[{"en":"Many antelopes are grassland species.","zh":"許多羚羊是草原物種。"},{"en":"Grassland species often need speed to escape predators.","zh":"草原物種通常需要速度逃離掠食者。"},{"en":"Open plains support many grassland species.","zh":"開闊平原支持許多草原物種。"},{"en":"Some grassland species live in large herds.","zh":"一些草原物種群居。"},{"en":"The passage describes antelopes mainly as grassland species.","zh":"文章主要把羚羊描述為草原物種。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":8},{"front":"adapt to flooded grasslands","meaning":"適應水浸草原","examples":[{"en":"Some antelopes adapt to flooded grasslands.","zh":"一些羚羊適應水浸草原。"},{"en":"Pukus and lechwes adapt to flooded grasslands.","zh":"普庫羚和沼羚適應水浸草原。"},{"en":"Species that adapt to flooded grasslands often swim well.","zh":"適應水浸草原的物種通常擅長游泳。"},{"en":"Long legs may help animals adapt to flooded grasslands.","zh":"長腿可能幫助動物適應水浸草原。"},{"en":"The passage explains how certain antelopes adapt to flooded grasslands.","zh":"文章解釋某些羚羊如何適應水浸草原。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":8},{"front":"flooded grasslands","meaning":"水浸草原","examples":[{"en":"Flooded grasslands support specialised antelopes.","zh":"水浸草原支持特化羚羊。"},{"en":"Waterbucks can live near flooded grasslands.","zh":"水羚可以生活在水浸草原附近。"},{"en":"Animals in flooded grasslands may need to swim.","zh":"水浸草原中的動物可能需要游泳。"},{"en":"Flooded grasslands contain both grass and standing water.","zh":"水浸草原同時有草和積水。"},{"en":"The sitatunga is adapted to wet areas near flooded grasslands.","zh":"澤羚適應水浸草原附近的潮濕地區。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":8},{"front":"pukus","meaning":"普庫羚","examples":[{"en":"Pukus are antelopes adapted to wet habitats.","zh":"普庫羚是適應潮濕棲息地的羚羊。"},{"en":"Pukus are good at swimming.","zh":"普庫羚擅長游泳。"},{"en":"Pukus may feed in deep water.","zh":"普庫羚可能在深水中覓食。"},{"en":"The passage groups pukus with waterbucks and lechwes.","zh":"文章把普庫羚與水羚和沼羚歸在一起。"},{"en":"Pukus show how antelopes can adapt to flooded grasslands.","zh":"普庫羚顯示羚羊如何適應水浸草原。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":8},{"front":"waterbucks","meaning":"水羚","examples":[{"en":"Waterbucks are antelopes associated with wet grassland.","zh":"水羚是與濕草原有關的羚羊。"},{"en":"Waterbucks can swim well.","zh":"水羚擅長游泳。"},{"en":"The passage mentions waterbucks with pukus and lechwes.","zh":"文章把水羚與普庫羚和沼羚一起提及。"},{"en":"Waterbucks may feed near deep water.","zh":"水羚可能在深水附近覓食。"},{"en":"Waterbucks are adapted to habitats close to rivers and marshes.","zh":"水羚適應接近河流和沼澤的棲息地。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":9},{"front":"lechwes","meaning":"沼羚","examples":[{"en":"Lechwes are adapted to flooded habitats.","zh":"沼羚適應水浸棲息地。"},{"en":"Lechwes are good swimmers.","zh":"沼羚擅長游泳。"},{"en":"Lechwes may feed in deep water.","zh":"沼羚可能在深水中覓食。"},{"en":"The passage lists lechwes among wetland antelopes.","zh":"文章把沼羚列為濕地羚羊之一。"},{"en":"Lechwes have habits suited to flooded grasslands.","zh":"沼羚有適合水浸草原的習性。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":9},{"front":"be good at swimming","meaning":"擅長游泳","examples":[{"en":"Pukus are good at swimming.","zh":"普庫羚擅長游泳。"},{"en":"Wetland antelopes are often good at swimming.","zh":"濕地羚羊通常擅長游泳。"},{"en":"Animals that are good at swimming can feed in deeper water.","zh":"擅長游泳的動物可以在較深水域覓食。"},{"en":"Waterbucks and lechwes are good at swimming.","zh":"水羚和沼羚擅長游泳。"},{"en":"Being good at swimming helps animals survive flooded habitats.","zh":"擅長游泳幫助動物在水浸棲息地生存。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":9},{"front":"feed in deep water","meaning":"在深水中覓食","examples":[{"en":"Some antelopes feed in deep water.","zh":"一些羚羊在深水中覓食。"},{"en":"Lechwes may feed in deep water during floods.","zh":"沼羚在水浸期間可能在深水中覓食。"},{"en":"Animals that feed in deep water need swimming ability.","zh":"在深水中覓食的動物需要游泳能力。"},{"en":"Pukus can feed in deep water when grass is submerged.","zh":"當草被水淹沒時，普庫羚可以在深水中覓食。"},{"en":"The passage notes that some bovids feed in deep water.","zh":"文章指出一些牛科動物在深水中覓食。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":9},{"front":"sitatunga","meaning":"澤羚","examples":[{"en":"The sitatunga has long, splayed hooves.","zh":"澤羚有長而張開的蹄。"},{"en":"The sitatunga can walk on swampy ground.","zh":"澤羚可以在沼澤地上行走。"},{"en":"Sitatunga are adapted to wetland environments.","zh":"澤羚適應濕地環境。"},{"en":"The passage uses the sitatunga as an example of hoof adaptation.","zh":"文章用澤羚作為蹄部適應的例子。"},{"en":"A sitatunga moves more easily over marshy terrain than many other bovids.","zh":"澤羚比許多其他牛科動物更容易在沼澤地形上移動。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":9},{"front":"splayed hooves","meaning":"張開的蹄","examples":[{"en":"The sitatunga has splayed hooves.","zh":"澤羚有張開的蹄。"},{"en":"Splayed hooves help spread the animal’s weight.","zh":"張開的蹄幫助分散動物體重。"},{"en":"Animals with splayed hooves can walk on soft ground.","zh":"有張開的蹄的動物可以在柔軟地面上行走。"},{"en":"Splayed hooves are useful in swampy habitats.","zh":"張開的蹄在沼澤棲息地很有用。"},{"en":"The passage explains how splayed hooves help the sitatunga.","zh":"文章解釋張開的蹄如何幫助澤羚。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":9},{"front":"enable it to","meaning":"使牠能夠……","examples":[{"en":"Its hooves enable it to walk on swampy ground.","zh":"牠的蹄使牠能夠在沼澤地上行走。"},{"en":"Long legs enable it to move through deep water.","zh":"長腿使牠能夠穿過深水。"},{"en":"Strong horns enable it to defend itself.","zh":"強壯的角使牠能夠自衛。"},{"en":"A thick coat may enable it to survive cold weather.","zh":"厚毛可能使牠能夠在寒冷天氣中生存。"},{"en":"Flexible lips enable it to crop vegetation.","zh":"靈活嘴唇使牠能夠咬斷植物。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":9},{"front":"swampy ground","meaning":"沼澤地","examples":[{"en":"The sitatunga can walk freely on swampy ground.","zh":"澤羚可以在沼澤地上自由行走。"},{"en":"Swampy ground is soft and wet.","zh":"沼澤地柔軟而潮濕。"},{"en":"Splayed hooves are useful on swampy ground.","zh":"張開的蹄在沼澤地上很有用。"},{"en":"Many animals sink easily into swampy ground.","zh":"許多動物很容易陷入沼澤地。"},{"en":"Wetland bovids are adapted to swampy ground.","zh":"濕地牛科動物適應沼澤地。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":9},{"front":"Caprinae","meaning":"羊亞科","examples":[{"en":"Caprinae includes sheep, goats and their relatives.","zh":"羊亞科包括綿羊、山羊和牠們的近親。"},{"en":"Many Caprinae species live in mountains.","zh":"許多羊亞科物種生活在山地。"},{"en":"Caprinae members are often woolly or long-haired.","zh":"羊亞科成員通常長有羊毛或長毛。"},{"en":"The passage links Caprinae with extreme environments.","zh":"文章把羊亞科與極端環境聯繫起來。"},{"en":"Ibex and chamois are associated with Caprinae.","zh":"野山羊和岩羚羊與羊亞科有關。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":9},{"front":"sheep and goats","meaning":"綿羊和山羊","examples":[{"en":"Caprinae includes sheep and goats.","zh":"羊亞科包括綿羊和山羊。"},{"en":"Sheep and goats are important domestic animals.","zh":"綿羊和山羊是重要家畜。"},{"en":"Wild sheep and goats often live in rugged terrain.","zh":"野生綿羊和山羊常生活在崎嶇地形。"},{"en":"Sheep and goats are ruminants.","zh":"綿羊和山羊是反芻動物。"},{"en":"Many sheep and goats have woolly or long hair.","zh":"許多綿羊和山羊長有羊毛或長毛。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":9},{"front":"various relatives","meaning":"各種近親","examples":[{"en":"Caprinae includes sheep, goats and various relatives.","zh":"羊亞科包括綿羊、山羊和各種近親。"},{"en":"Various relatives of goats live in mountains.","zh":"山羊的各種近親生活在山地。"},{"en":"The passage lists various relatives such as goral and tahr.","zh":"文章列出各種近親，如斑羚和塔爾羊。"},{"en":"Scientists compare various relatives to understand adaptation.","zh":"科學家比較各種近親以了解適應。"},{"en":"Various relatives may differ in size, coat and habitat.","zh":"各種近親可能在體型、毛皮和棲息地上不同。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":9},{"front":"goral","meaning":"斑羚","examples":[{"en":"The goral is related to sheep and goats.","zh":"斑羚與綿羊和山羊有親緣關係。"},{"en":"Goral are included in the Caprinae group.","zh":"斑羚包括在羊亞科中。"},{"en":"A goral is adapted to rugged terrain.","zh":"斑羚適應崎嶇地形。"},{"en":"The passage names the goral as a Caprinae relative.","zh":"文章把斑羚列為羊亞科近親。"},{"en":"Goral often live in mountainous areas.","zh":"斑羚常生活在山區。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":9},{"front":"tahr","meaning":"塔爾羊","examples":[{"en":"The tahr is a relative of sheep and goats.","zh":"塔爾羊是綿羊和山羊的近親。"},{"en":"Tahr are included in Caprinae.","zh":"塔爾羊包括在羊亞科中。"},{"en":"A tahr may live on steep mountain slopes.","zh":"塔爾羊可能生活在陡峭山坡上。"},{"en":"The passage lists the tahr among goat relatives.","zh":"文章把塔爾羊列為山羊近親之一。"},{"en":"Tahr have bodies suited to rugged terrain.","zh":"塔爾羊的身體適合崎嶇地形。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":9},{"front":"woolly","meaning":"長有羊毛的","examples":[{"en":"Many Caprinae species are woolly.","zh":"許多羊亞科物種長有羊毛。"},{"en":"A woolly coat helps animals survive cold climates.","zh":"羊毛狀外皮幫助動物在寒冷氣候中生存。"},{"en":"Sheep are well known for being woolly.","zh":"綿羊以長有羊毛而聞名。"},{"en":"Woolly animals may tolerate high mountains better.","zh":"長有羊毛的動物可能更能忍受高山環境。"},{"en":"The passage describes many sheep relatives as woolly.","zh":"文章描述許多綿羊近親長有羊毛。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":10},{"front":"have long hair","meaning":"長有長毛","examples":[{"en":"Many Caprinae species have long hair.","zh":"許多羊亞科物種長有長毛。"},{"en":"Animals that have long hair may be protected from cold.","zh":"長有長毛的動物可能受保護免受寒冷。"},{"en":"Yaks have long hair for mountain climates.","zh":"犛牛長有長毛以適應山地氣候。"},{"en":"Sheep relatives that have long hair can survive harsh weather.","zh":"長有長毛的綿羊近親可以在惡劣天氣中生存。"},{"en":"The passage notes that many members have long hair.","zh":"文章指出許多成員長有長毛。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":10},{"front":"agile cliff-dwellers","meaning":"靈活的峭壁棲居動物","examples":[{"en":"Some wild goats are agile cliff-dwellers.","zh":"一些野山羊是靈活的峭壁棲居動物。"},{"en":"Agile cliff-dwellers move easily on steep rock faces.","zh":"靈活的峭壁棲居動物能輕易在陡峭岩面上移動。"},{"en":"Ibex are famous agile cliff-dwellers.","zh":"野山羊以靈活的峭壁棲居動物聞名。"},{"en":"Agile cliff-dwellers need excellent balance.","zh":"靈活的峭壁棲居動物需要極佳平衡力。"},{"en":"The passage describes certain goats as agile cliff-dwellers.","zh":"文章把某些山羊描述為靈活的峭壁棲居動物。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":10},{"front":"mountain-dwellers","meaning":"山地棲居動物","examples":[{"en":"Ibex are agile mountain-dwellers.","zh":"野山羊是靈活的山地棲居動物。"},{"en":"Mountain-dwellers must cope with cold and steep terrain.","zh":"山地棲居動物必須應付寒冷和陡峭地形。"},{"en":"Several Caprinae species are mountain-dwellers.","zh":"幾種羊亞科物種是山地棲居動物。"},{"en":"Mountain-dwellers often have strong hooves.","zh":"山地棲居動物通常有強壯蹄。"},{"en":"Chamois are examples of mountain-dwellers.","zh":"岩羚羊是山地棲居動物的例子。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":10},{"front":"chamois","meaning":"岩羚羊","examples":[{"en":"The chamois is an agile mountain-dwelling bovid.","zh":"岩羚羊是靈活的山地牛科動物。"},{"en":"Chamois can move quickly across rocky slopes.","zh":"岩羚羊可以迅速穿過岩石斜坡。"},{"en":"The passage lists chamois among Caprinae examples.","zh":"文章把岩羚羊列為羊亞科例子之一。"},{"en":"A chamois is adapted to mountain environments.","zh":"岩羚羊適應山地環境。"},{"en":"Chamois rely on balance and speed to escape danger.","zh":"岩羚羊依靠平衡和速度逃離危險。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":10},{"front":"ibex","meaning":"野山羊","examples":[{"en":"The ibex is adapted to cliffs and mountains.","zh":"野山羊適應峭壁和山地。"},{"en":"Ibex can climb steep rocky slopes.","zh":"野山羊可以攀爬陡峭岩坡。"},{"en":"The passage describes ibex as agile mountain-dwellers.","zh":"文章把野山羊描述為靈活的山地棲居動物。"},{"en":"An ibex has strong hooves for rocky terrain.","zh":"野山羊有強壯蹄以適應岩石地形。"},{"en":"Ibex are associated with the Caprinae subfamily.","zh":"野山羊與羊亞科有關。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":10},{"front":"tolerance of extreme conditions","meaning":"對極端環境的耐受力","examples":[{"en":"Tolerance of extreme conditions is strong in Caprinae.","zh":"羊亞科對極端環境的耐受力很強。"},{"en":"Musk oxen show tolerance of extreme conditions.","zh":"麝牛展現對極端環境的耐受力。"},{"en":"Desert sheep need tolerance of extreme conditions.","zh":"沙漠羊需要對極端環境的耐受力。"},{"en":"Tolerance of extreme conditions helps animals survive heat, cold or drought.","zh":"對極端環境的耐受力幫助動物在炎熱、寒冷或乾旱中生存。"},{"en":"The passage highlights this group’s tolerance of extreme conditions.","zh":"文章突顯這個群體對極端環境的耐受力。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":10},{"front":"most marked","meaning":"最明顯的","examples":[{"en":"This tolerance is most marked in Caprinae.","zh":"這種耐受力在羊亞科中最明顯。"},{"en":"The difference is most marked among mountain species.","zh":"這種差異在山地物種中最明顯。"},{"en":"Adaptation to cold is most marked in musk oxen.","zh":"對寒冷的適應在麝牛中最明顯。"},{"en":"The contrast is most marked between royal antelopes and bison.","zh":"倭羚和野牛之間的對比最明顯。"},{"en":"Desert adaptation is most marked in Barbary sheep.","zh":"沙漠適應在鬃羊中最明顯。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":10},{"front":"Barbary sheep","meaning":"鬃羊","examples":[{"en":"Barbary sheep have adapted to arid deserts.","zh":"鬃羊已適應乾旱沙漠。"},{"en":"Barbary sheep are members of Caprinae.","zh":"鬃羊是羊亞科成員。"},{"en":"The passage uses Barbary sheep as an example of desert tolerance.","zh":"文章用鬃羊作為沙漠耐受力的例子。"},{"en":"Barbary sheep can survive with limited water.","zh":"鬃羊能在水源有限情況下生存。"},{"en":"Barbary sheep inhabit harsh dry terrain.","zh":"鬃羊棲息於嚴酷乾燥地形。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":10},{"front":"bighorn sheep","meaning":"大角羊","examples":[{"en":"Bighorn sheep have adapted to arid deserts.","zh":"大角羊已適應乾旱沙漠。"},{"en":"Bighorn sheep are named for their large horns.","zh":"大角羊因其大角而得名。"},{"en":"The passage lists bighorn sheep with Barbary sheep.","zh":"文章把大角羊與鬃羊一起列出。"},{"en":"Bighorn sheep can move across rocky desert slopes.","zh":"大角羊可以穿越岩石沙漠斜坡。"},{"en":"Bighorn sheep show tolerance of harsh environments.","zh":"大角羊展現對惡劣環境的耐受力。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":10},{"front":"arid deserts","meaning":"乾旱沙漠","examples":[{"en":"Some sheep have adapted to arid deserts.","zh":"一些羊已適應乾旱沙漠。"},{"en":"Arid deserts contain little water.","zh":"乾旱沙漠水分很少。"},{"en":"Animals in arid deserts must tolerate heat and dryness.","zh":"乾旱沙漠中的動物必須忍受炎熱和乾燥。"},{"en":"Barbary sheep inhabit arid deserts.","zh":"鬃羊棲息於乾旱沙漠。"},{"en":"Survival in arid deserts requires special adaptations.","zh":"在乾旱沙漠中生存需要特殊適應。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":10},{"front":"Rocky Mountain sheep","meaning":"洛磯山羊","examples":[{"en":"Rocky Mountain sheep survive high up in mountains.","zh":"洛磯山羊在高山上生存。"},{"en":"Rocky Mountain sheep are adapted to cold and rugged terrain.","zh":"洛磯山羊適應寒冷和崎嶇地形。"},{"en":"The passage mentions Rocky Mountain sheep as an extreme example.","zh":"文章提到洛磯山羊作為極端例子。"},{"en":"Rocky Mountain sheep live where few animals can survive.","zh":"洛磯山羊生活在很少動物能生存的地方。"},{"en":"Rocky Mountain sheep show the toughness of Caprinae.","zh":"洛磯山羊顯示羊亞科的強韌。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":10},{"front":"high up in mountains","meaning":"在高山上","examples":[{"en":"Some sheep survive high up in mountains.","zh":"一些羊在高山上生存。"},{"en":"Animals high up in mountains face cold and thin air.","zh":"在高山上的動物面對寒冷和稀薄空氣。"},{"en":"Ibex can live high up in mountains.","zh":"野山羊可以生活在高山上。"},{"en":"Food may be scarce high up in mountains.","zh":"在高山上，食物可能很稀少。"},{"en":"Caprinae species are often found high up in mountains.","zh":"羊亞科物種常見於高山上。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":10},{"front":"musk oxen","meaning":"麝牛","examples":[{"en":"Musk oxen survive in arctic tundra.","zh":"麝牛在北極苔原中生存。"},{"en":"Musk oxen have thick coats for cold weather.","zh":"麝牛有厚毛以應付寒冷天氣。"},{"en":"The passage mentions musk oxen as extremely tolerant animals.","zh":"文章提到麝牛是極具耐受力的動物。"},{"en":"Musk oxen belong to the broader bovid family.","zh":"麝牛屬於較廣義的牛科。"},{"en":"Musk oxen show how bovids adapt to cold habitats.","zh":"麝牛顯示牛科動物如何適應寒冷棲息地。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":11},{"front":"African duikers","meaning":"非洲遁羚","examples":[{"en":"African duikers belong to Cephalophinae.","zh":"非洲遁羚屬於遁羚亞科。"},{"en":"African duikers are often small and solitary.","zh":"非洲遁羚通常體型小且獨居。"},{"en":"African duikers live in thick forest.","zh":"非洲遁羚生活在茂密森林中。"},{"en":"Some African duikers may eat more than plants.","zh":"一些非洲遁羚可能不只吃植物。"},{"en":"The passage treats African duikers as unusual bovids.","zh":"文章把非洲遁羚視為特殊牛科動物。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":11},{"front":"belong to","meaning":"屬於","examples":[{"en":"African duikers belong to Cephalophinae.","zh":"非洲遁羚屬於遁羚亞科。"},{"en":"Cattle belong to the bovid family.","zh":"牛屬於牛科。"},{"en":"The pronghorn does not belong to Bovidae.","zh":"叉角羚不屬於牛科。"},{"en":"Sheep and goats belong to Caprinae.","zh":"綿羊和山羊屬於羊亞科。"},{"en":"The oryx belongs to Hippotraginae.","zh":"劍羚屬於馬羚亞科。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":11},{"front":"Cephalophinae","meaning":"遁羚亞科","examples":[{"en":"Cephalophinae includes African duikers.","zh":"遁羚亞科包括非洲遁羚。"},{"en":"Members of Cephalophinae are generally small.","zh":"遁羚亞科成員通常體型小。"},{"en":"Cephalophinae species often live in forests.","zh":"遁羚亞科物種常生活在森林中。"},{"en":"The passage describes Cephalophinae as a bovid subfamily.","zh":"文章把遁羚亞科描述為牛科亞科。"},{"en":"Students should connect duikers with Cephalophinae.","zh":"學生應把遁羚與遁羚亞科聯繫起來。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":11},{"front":"generally small and solitary","meaning":"通常體型小且獨居","examples":[{"en":"Duikers are generally small and solitary.","zh":"遁羚通常體型小且獨居。"},{"en":"Generally small and solitary animals are hard to observe.","zh":"通常體型小且獨居的動物很難觀察。"},{"en":"This group is generally small and solitary compared with herd species.","zh":"與群居物種相比，這個群體通常體型小且獨居。"},{"en":"Forest bovids may be generally small and solitary.","zh":"森林牛科動物可能通常體型小且獨居。"},{"en":"The passage describes African duikers as generally small and solitary.","zh":"文章描述非洲遁羚通常體型小且獨居。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":11},{"front":"thick forest","meaning":"茂密森林","examples":[{"en":"Duikers often live in thick forest.","zh":"遁羚常生活在茂密森林中。"},{"en":"Thick forest provides cover from predators.","zh":"茂密森林提供躲避掠食者的掩護。"},{"en":"Small solitary bovids may prefer thick forest.","zh":"小型獨居牛科動物可能偏好茂密森林。"},{"en":"It is difficult to track animals in thick forest.","zh":"在茂密森林中追蹤動物很困難。"},{"en":"Thick forest habitats differ from wide-open grasslands.","zh":"茂密森林棲息地不同於廣闊開放草原。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":11},{"front":"feed mainly on","meaning":"主要以……為食","examples":[{"en":"Duikers feed mainly on grass and leaves.","zh":"遁羚主要以草和葉為食。"},{"en":"Bovids feed mainly on plant material.","zh":"牛科動物主要以植物材料為食。"},{"en":"Some species feed mainly on foliage in forests.","zh":"一些物種在森林中主要以葉子為食。"},{"en":"Grazing animals feed mainly on grass.","zh":"吃草動物主要以草為食。"},{"en":"The passage says most bovids feed mainly on vegetation.","zh":"文章指出大多數牛科動物主要以植物為食。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":11},{"front":"unlike most other bovids","meaning":"與大多數其他牛科動物不同","examples":[{"en":"Unlike most other bovids, some duikers may eat insects.","zh":"與大多數其他牛科動物不同，一些遁羚可能吃昆蟲。"},{"en":"Unlike most other bovids, duikers may feed on carcasses.","zh":"與大多數其他牛科動物不同，遁羚可能以屍體為食。"},{"en":"Unlike most other bovids, some species may supplement their diet with meat.","zh":"與大多數其他牛科動物不同，一些物種可能以肉類補充飲食。"},{"en":"Unlike most other bovids, these animals are not strictly herbivorous.","zh":"與大多數其他牛科動物不同，這些動物並非嚴格草食。"},{"en":"Unlike most other bovids, certain duikers may even kill small animals.","zh":"與大多數其他牛科動物不同，某些遁羚甚至可能殺死小動物。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":11},{"front":"be believed to","meaning":"被認為","examples":[{"en":"Some duikers are believed to eat insects.","zh":"一些遁羚被認為會吃昆蟲。"},{"en":"The animal is believed to live mainly in thick forest.","zh":"這種動物被認為主要生活在茂密森林中。"},{"en":"This species is believed to be rare in the wild.","zh":"這個物種被認為在野外很稀有。"},{"en":"The pronghorn is believed to resemble Old World antelope.","zh":"叉角羚被認為與舊大陸羚羊相似。"},{"en":"Several cattle ancestors are believed to be endangered.","zh":"幾種牛的祖先被認為已瀕危。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":11},{"front":"feed on dead animal carcasses","meaning":"以動物屍體為食","examples":[{"en":"Some duikers may feed on dead animal carcasses.","zh":"一些遁羚可能以動物屍體為食。"},{"en":"Animals that feed on dead animal carcasses are not strictly herbivorous.","zh":"以動物屍體為食的動物並非嚴格草食。"},{"en":"The passage says certain duikers feed on dead animal carcasses.","zh":"文章說某些遁羚以動物屍體為食。"},{"en":"Feeding on dead animal carcasses is unusual for bovids.","zh":"以動物屍體為食對牛科動物而言很不尋常。"},{"en":"Duikers may feed on dead animal carcasses when plant food is limited.","zh":"當植物食物有限時，遁羚可能以動物屍體為食。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":11},{"front":"animal carcasses","meaning":"動物屍體","examples":[{"en":"Some duikers may eat animal carcasses.","zh":"一些遁羚可能吃動物屍體。"},{"en":"Animal carcasses can provide protein for unusual feeders.","zh":"動物屍體可以為特殊取食者提供蛋白質。"},{"en":"Feeding on animal carcasses is rare among bovids.","zh":"以動物屍體為食在牛科動物中很罕見。"},{"en":"The passage mentions animal carcasses in relation to duikers.","zh":"文章在談到遁羚時提到動物屍體。"},{"en":"Scavengers are often attracted to animal carcasses.","zh":"食腐動物常被動物屍體吸引。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":11},{"front":"may even kill","meaning":"甚至可能殺死","examples":[{"en":"Some duikers may even kill small animals.","zh":"一些遁羚甚至可能殺死小動物。"},{"en":"A hungry animal may even kill prey if food is scarce.","zh":"如果食物稀少，飢餓動物甚至可能殺死獵物。"},{"en":"The passage says certain duikers may even kill small creatures.","zh":"文章說某些遁羚甚至可能殺死小型生物。"},{"en":"This behaviour may even kill the idea that all bovids are strict herbivores.","zh":"這種行為甚至可能推翻所有牛科動物都是嚴格草食的想法。"},{"en":"A normally gentle animal may even kill when survival is difficult.","zh":"當生存困難時，通常溫順的動物甚至可能殺死其他動物。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":11},{"front":"pronghorn","meaning":"叉角羚","examples":[{"en":"The pronghorn is found in North America.","zh":"叉角羚見於北美洲。"},{"en":"The pronghorn resembles Old World antelope.","zh":"叉角羚像舊大陸羚羊。"},{"en":"The pronghorn is not a true bovid.","zh":"叉角羚並不是真正的牛科動物。"},{"en":"The pronghorn uses a white rump patch as a warning signal.","zh":"叉角羚使用臀部白斑作警示信號。"},{"en":"The pronghorn is the sole surviving member of Antilocapridae.","zh":"叉角羚是叉角羚科唯一現存成員。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":11},{"front":"sole surviving member","meaning":"唯一現存成員","examples":[{"en":"The pronghorn is the sole surviving member of its family.","zh":"叉角羚是其科的唯一現存成員。"},{"en":"A sole surviving member represents the last living branch of a group.","zh":"唯一現存成員代表某群體最後仍活着的一支。"},{"en":"The passage calls the pronghorn the sole surviving member of Antilocapridae.","zh":"文章稱叉角羚為叉角羚科唯一現存成員。"},{"en":"Conservationists pay attention to a sole surviving member.","zh":"保育人士會關注唯一現存成員。"},{"en":"The sole surviving member may preserve unique evolutionary history.","zh":"唯一現存成員可能保存獨特進化歷史。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":12},{"front":"Antilocapridae","meaning":"叉角羚科","examples":[{"en":"Antilocapridae is represented today by the pronghorn.","zh":"叉角羚科現今由叉角羚代表。"},{"en":"The pronghorn belongs to Antilocapridae.","zh":"叉角羚屬於叉角羚科。"},{"en":"Antilocapridae is separate from the bovid family.","zh":"叉角羚科與牛科分開。"},{"en":"The passage mentions Antilocapridae after discussing bovids.","zh":"文章在討論牛科動物後提到叉角羚科。"},{"en":"Antilocapridae once had more members than it does today.","zh":"叉角羚科過去的成員比現在更多。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":12},{"front":"New World","meaning":"新大陸","examples":[{"en":"The pronghorn belongs to a New World group.","zh":"叉角羚屬於新大陸群體。"},{"en":"New World animals live in the Americas.","zh":"新大陸動物生活在美洲。"},{"en":"The passage contrasts New World forms with Old World antelopes.","zh":"文章把新大陸形態與舊大陸羚羊作對比。"},{"en":"The pronghorn is a New World herbivorous ruminant.","zh":"叉角羚是新大陸草食反芻動物。"},{"en":"New World species evolved separately from many Eurasian forms.","zh":"新大陸物種與許多歐亞形態分開演化。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":12},{"front":"herbivorous ruminants","meaning":"草食反芻動物","examples":[{"en":"Pronghorns are herbivorous ruminants.","zh":"叉角羚是草食反芻動物。"},{"en":"Bovids are also herbivorous ruminants.","zh":"牛科動物也是草食反芻動物。"},{"en":"Herbivorous ruminants digest plant food in specialised stomachs.","zh":"草食反芻動物在特化胃中消化植物食物。"},{"en":"Cattle and sheep are familiar herbivorous ruminants.","zh":"牛和綿羊是常見草食反芻動物。"},{"en":"The passage describes the pronghorn as one of the herbivorous ruminants.","zh":"文章把叉角羚描述為草食反芻動物之一。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":12},{"front":"be found in","meaning":"見於……","examples":[{"en":"The pronghorn is found in North America.","zh":"叉角羚見於北美洲。"},{"en":"Bovids are found in many parts of Eurasia.","zh":"牛科動物見於歐亞大陸許多地區。"},{"en":"Some species are found in deep tropical forests.","zh":"一些物種見於熱帶森林深處。"},{"en":"Musk oxen are found in arctic tundra.","zh":"麝牛見於北極苔原。"},{"en":"Different antelopes are found in different habitats.","zh":"不同羚羊見於不同棲息地。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":12},{"front":"similar in appearance and habits to","meaning":"在外貌和習性上與……相似","examples":[{"en":"The pronghorn is similar in appearance and habits to Old World antelope.","zh":"叉角羚在外貌和習性上與舊大陸羚羊相似。"},{"en":"This species is similar in appearance and habits to gazelles.","zh":"這個物種在外貌和習性上與瞪羚相似。"},{"en":"Some unrelated animals are similar in appearance and habits to each other.","zh":"一些無親緣關係的動物在外貌和習性上彼此相似。"},{"en":"The pronghorn looks similar in appearance and habits to antelope but belongs elsewhere.","zh":"叉角羚在外貌和習性上像羚羊，但屬於另一科。"},{"en":"Animals in open grasslands may become similar in appearance and habits to one another.","zh":"開闊草原中的動物可能在外貌和習性上彼此相似。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":12},{"front":"Old World antelope","meaning":"舊大陸羚羊","examples":[{"en":"The pronghorn resembles Old World antelope.","zh":"叉角羚像舊大陸羚羊。"},{"en":"Old World antelope are found in Africa and Eurasia.","zh":"舊大陸羚羊見於非洲和歐亞大陸。"},{"en":"The passage compares the pronghorn with Old World antelope.","zh":"文章把叉角羚與舊大陸羚羊作比較。"},{"en":"Old World antelope include many grassland species.","zh":"舊大陸羚羊包括許多草原物種。"},{"en":"Similar habits make the pronghorn look like Old World antelope.","zh":"相似習性令叉角羚看起來像舊大陸羚羊。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":12},{"front":"greatly reduced in numbers","meaning":"數量大幅減少","examples":[{"en":"The pronghorn was greatly reduced in numbers after Europeans arrived.","zh":"歐洲人到來後，叉角羚數量大幅減少。"},{"en":"Habitat loss greatly reduced the numbers of some species.","zh":"棲息地喪失令一些物種數量大幅減少。"},{"en":"A population greatly reduced in numbers may need protection.","zh":"數量大幅減少的種群可能需要保護。"},{"en":"Hunting greatly reduced numbers across the grasslands.","zh":"狩獵令草原各地的數量大幅減少。"},{"en":"The passage says pronghorns were greatly reduced in numbers.","zh":"文章指出叉角羚數量大幅減少。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":12},{"front":"arrival of Europeans","meaning":"歐洲人的到來","examples":[{"en":"The pronghorn declined after the arrival of Europeans.","zh":"歐洲人到來後，叉角羚數量下降。"},{"en":"The arrival of Europeans changed North American grasslands.","zh":"歐洲人的到來改變了北美草原。"},{"en":"After the arrival of Europeans, many habitats were enclosed.","zh":"歐洲人到來後，許多棲息地被圈佔。"},{"en":"The passage links population decline with the arrival of Europeans.","zh":"文章把種群下降與歐洲人的到來聯繫起來。"},{"en":"The arrival of Europeans affected several native species.","zh":"歐洲人的到來影響了幾種本土物種。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":12},{"front":"subsequent enclosure of grasslands","meaning":"隨後對草原的圈佔","examples":[{"en":"The subsequent enclosure of grasslands reduced pronghorn numbers.","zh":"隨後對草原的圈佔令叉角羚數量減少。"},{"en":"Subsequent enclosure of grasslands limited animal movement.","zh":"隨後對草原的圈佔限制了動物移動。"},{"en":"Fences were part of the subsequent enclosure of grasslands.","zh":"圍欄是隨後對草原的圈佔的一部分。"},{"en":"The passage mentions subsequent enclosure of grasslands after European arrival.","zh":"文章在歐洲人到來後提到隨後對草原的圈佔。"},{"en":"Subsequent enclosure of grasslands damaged open-habitat species.","zh":"隨後對草原的圈佔損害了開闊棲息地物種。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":12},{"front":"considerable numbers","meaning":"相當大的數量","examples":[{"en":"Pronghorns are still found in considerable numbers.","zh":"叉角羚仍以相當大的數量存在。"},{"en":"Considerable numbers of animals survived in protected areas.","zh":"相當大的數量動物在保護區中存活。"},{"en":"The herd gathered in considerable numbers on the plain.","zh":"獸群以相當大的數量聚集在平原上。"},{"en":"A species in considerable numbers is not immediately rare.","zh":"以相當大數量存在的物種並非立即稀有。"},{"en":"The passage notes that pronghorns remain in considerable numbers.","zh":"文章指出叉角羚仍有相當大的數量。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":12},{"front":"throughout North America","meaning":"遍佈北美洲","examples":[{"en":"The pronghorn is found throughout North America.","zh":"叉角羚遍佈北美洲。"},{"en":"Grassland habitats occur throughout North America.","zh":"草原棲息地遍佈北美洲。"},{"en":"Conservation programmes operate throughout North America.","zh":"保育計劃遍佈北美洲。"},{"en":"The species once ranged widely throughout North America.","zh":"該物種曾廣泛遍佈北美洲。"},{"en":"Pronghorn herds can be seen throughout North America in suitable areas.","zh":"在合適地區，叉角羚群可遍佈北美洲被看見。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":12},{"front":"be alarmed by","meaning":"被……驚動","examples":[{"en":"The pronghorn is alarmed by approaching wolves.","zh":"叉角羚被靠近的狼驚動。"},{"en":"Herd animals are easily alarmed by predators.","zh":"群居動物很容易被掠食者驚動。"},{"en":"The antelope was alarmed by a sudden movement.","zh":"那隻羚羊被突然動作驚動。"},{"en":"Animals alarmed by danger may flee together.","zh":"被危險驚動的動物可能一起逃跑。"},{"en":"The pronghorn’s rump hairs rise when it is alarmed by danger.","zh":"叉角羚被危險驚動時，臀部毛會豎起。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":12},{"front":"approach of wolves","meaning":"狼的靠近","examples":[{"en":"The approach of wolves alarms the pronghorn.","zh":"狼的靠近會驚動叉角羚。"},{"en":"The herd noticed the approach of wolves.","zh":"獸群注意到狼的靠近。"},{"en":"The approach of wolves caused the animals to flee.","zh":"狼的靠近令動物逃跑。"},{"en":"A warning signal may appear after the approach of wolves.","zh":"狼的靠近後可能出現警示信號。"},{"en":"The passage uses the approach of wolves as a danger example.","zh":"文章用狼的靠近作為危險例子。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":13},{"front":"predators","meaning":"掠食者","examples":[{"en":"Pronghorns flee when predators approach.","zh":"掠食者靠近時，叉角羚會逃跑。"},{"en":"Predators include wolves and other hunting animals.","zh":"掠食者包括狼和其他捕獵動物。"},{"en":"Open grassland species must watch for predators.","zh":"開闊草原物種必須留意掠食者。"},{"en":"A warning signal can alert the herd to predators.","zh":"警示信號可以提醒獸群有掠食者。"},{"en":"Fast-running species may escape predators by speed.","zh":"跑得快的物種可能靠速度逃離掠食者。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":13},{"front":"rump","meaning":"臀部","examples":[{"en":"The pronghorn has a white patch on its rump.","zh":"叉角羚臀部有白色斑塊。"},{"en":"Hairs on the rump stand erect when danger appears.","zh":"危險出現時，臀部的毛會豎立。"},{"en":"The rump patch acts as a warning signal.","zh":"臀部斑塊作為警示信號。"},{"en":"The animal’s rump became more visible as the hairs rose.","zh":"毛豎起時，動物的臀部變得更顯眼。"},{"en":"Other herd members noticed the bright rump signal.","zh":"其他獸群成員注意到明亮的臀部信號。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":13},{"front":"stand erect","meaning":"豎立","examples":[{"en":"The hairs on the rump stand erect.","zh":"臀部的毛會豎立。"},{"en":"When alarmed, the animal’s hairs stand erect.","zh":"受驚時，動物的毛會豎立。"},{"en":"Hairs that stand erect reveal the white patch.","zh":"豎立的毛會顯露白色斑塊。"},{"en":"The signal appears when the rump hairs stand erect.","zh":"當臀部毛豎立時，信號便出現。"},{"en":"Muscles under the skin make the hairs stand erect.","zh":"皮膚下的肌肉令毛豎立。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":13},{"front":"thereby","meaning":"因而","examples":[{"en":"The hairs stand erect, thereby revealing the white patch.","zh":"毛豎立，因而顯露白色斑塊。"},{"en":"The signal spreads quickly, thereby warning the whole herd.","zh":"信號迅速傳開，因而警告整個獸群。"},{"en":"The animal gallops off, thereby escaping the predator.","zh":"動物飛奔離開，因而逃離掠食者。"},{"en":"The horns lie back, thereby reducing resistance.","zh":"角向後貼伏，因而減少阻力。"},{"en":"The hooves spread out, thereby helping the sitatunga walk on soft ground.","zh":"蹄向外張開，因而幫助澤羚在柔軟地面上行走。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":13},{"front":"reveal and emphasise","meaning":"顯露並突出","examples":[{"en":"The raised hairs reveal and emphasise the white patch.","zh":"豎起的毛顯露並突出白色斑塊。"},{"en":"The movement helps reveal and emphasise the warning signal.","zh":"這個動作幫助顯露並突出警示信號。"},{"en":"Bright colour can reveal and emphasise a body marking.","zh":"鮮明顏色可以顯露並突出身體標記。"},{"en":"Standing hair may reveal and emphasise the rump pattern.","zh":"豎立的毛可能顯露並突出臀部圖案。"},{"en":"The signal is designed to reveal and emphasise danger to the herd.","zh":"這個信號旨在向獸群顯露並突出危險。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":13},{"front":"white patch","meaning":"白色斑塊","examples":[{"en":"The pronghorn has a white patch on its rump.","zh":"叉角羚臀部有白色斑塊。"},{"en":"The white patch becomes visible when the hairs rise.","zh":"當毛豎起時，白色斑塊變得可見。"},{"en":"A white patch can act as a warning signal.","zh":"白色斑塊可以作為警示信號。"},{"en":"Other pronghorns notice the white patch quickly.","zh":"其他叉角羚很快注意到白色斑塊。"},{"en":"The passage describes how the white patch alerts the herd.","zh":"文章描述白色斑塊如何提醒獸群。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":13},{"front":"warning signal","meaning":"警示信號","examples":[{"en":"The white patch acts as a warning signal.","zh":"白色斑塊作為警示信號。"},{"en":"A warning signal helps the herd react to danger.","zh":"警示信號幫助獸群對危險作出反應。"},{"en":"Pronghorns use the rump patch as a warning signal.","zh":"叉角羚使用臀部斑塊作為警示信號。"},{"en":"The warning signal causes the whole herd to flee.","zh":"警示信號令整群飛奔離開。"},{"en":"Visual warning signals are useful in open habitats.","zh":"視覺警示信號在開闊棲息地很有用。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":13},{"front":"whole herd","meaning":"整群","examples":[{"en":"The whole herd gallops off when danger appears.","zh":"危險出現時，整群會飛奔離開。"},{"en":"A warning signal can alert the whole herd.","zh":"警示信號可以提醒整群。"},{"en":"The whole herd moved across the grassland together.","zh":"整群一起穿過草原。"},{"en":"Predators may target the edge of the whole herd.","zh":"掠食者可能瞄準整群邊緣。"},{"en":"The whole herd reacted to the pronghorn’s signal.","zh":"整群對叉角羚的信號作出反應。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":13},{"front":"gallop off","meaning":"飛奔離開","examples":[{"en":"The whole herd gallops off at high speed.","zh":"整群以高速飛奔離開。"},{"en":"Pronghorns gallop off when predators approach.","zh":"掠食者靠近時，叉角羚會飛奔離開。"},{"en":"The antelope galloped off across the plain.","zh":"那隻羚羊飛奔離開，穿過平原。"},{"en":"A sudden warning made the herd gallop off.","zh":"突然警示令獸群飛奔離開。"},{"en":"Animals that gallop off quickly may escape danger.","zh":"能快速飛奔離開的動物可能逃離危險。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":13},{"front":"at a speed of over","meaning":"以超過……的速度","examples":[{"en":"The herd gallops off at a speed of over 60 kilometres per hour.","zh":"獸群以超過每小時60公里的速度飛奔離開。"},{"en":"A pronghorn can run at a speed of over many other grassland animals.","zh":"叉角羚能以超過許多其他草原動物的速度奔跑。"},{"en":"The animal escaped at a speed of over fifty kilometres per hour.","zh":"那隻動物以超過每小時50公里的速度逃走。"},{"en":"Gazelles may flee at a speed of over the predator’s pace.","zh":"瞪羚可能以超過掠食者步速的速度逃跑。"},{"en":"Fast-running bovids can move at a speed of over ordinary livestock.","zh":"跑得快的牛科動物能以超過普通家畜的速度移動。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":13},{"front":"choose the correct letter","meaning":"選出正確字母","examples":[{"en":"Candidates choose the correct letter for each question.","zh":"考生為每題選出正確字母。"},{"en":"Read all options before you choose the correct letter.","zh":"選出正確字母前，先閱讀所有選項。"},{"en":"You should choose the correct letter based on the passage.","zh":"你應根據文章選出正確字母。"},{"en":"Do not guess if evidence helps you choose the correct letter.","zh":"如果證據能幫助你選出正確字母，就不要亂猜。"},{"en":"The instruction asks students to choose the correct letter, not write a full sentence.","zh":"指示要求學生選出正確字母，而不是寫完整句子。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":13},{"front":"greatest variety of","meaning":"最大種類的……","examples":[{"en":"Africa has the greatest variety of bovids.","zh":"非洲有最大種類的牛科動物。"},{"en":"The question asks which region has the greatest variety of species.","zh":"題目問哪個地區有最大種類的物種。"},{"en":"The greatest variety of habitats occurs in the tropics.","zh":"最大種類的棲息地出現在熱帶。"},{"en":"Students must identify where the greatest variety of bovids is found.","zh":"學生必須辨認最大種類的牛科動物在哪裏出現。"},{"en":"The passage links the greatest variety of bovids with Africa.","zh":"文章把最大種類的牛科動物與非洲聯繫起來。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":13},{"front":"prefer to live","meaning":"偏好生活在……","examples":[{"en":"Most bovids prefer to live in open habitats.","zh":"大多數牛科動物偏好生活在開闊棲息地。"},{"en":"Some species prefer to live in thick forest.","zh":"一些物種偏好生活在茂密森林中。"},{"en":"Musk oxen prefer to live in cold tundra.","zh":"麝牛偏好生活在寒冷苔原。"},{"en":"Antelopes often prefer to live on grassland.","zh":"羚羊通常偏好生活在草原上。"},{"en":"The question asks where most bovids prefer to live.","zh":"題目問大多數牛科動物偏好生活在哪裏。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":14},{"front":"in isolation","meaning":"獨自；孤立地","examples":[{"en":"Some animals live in isolation.","zh":"一些動物獨自生活。"},{"en":"The question asks whether most bovids live in isolation.","zh":"題目問大多數牛科動物是否獨自生活。"},{"en":"Solitary species may spend much of their lives in isolation.","zh":"獨居物種可能大部分生命都孤立地生活。"},{"en":"Animals in isolation may be harder to find.","zh":"孤立生活的動物可能較難尋找。"},{"en":"Most bovids do not necessarily live in isolation.","zh":"大多數牛科動物不一定獨自生活。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":14},{"front":"in small groups","meaning":"小群體中","examples":[{"en":"Some bovids live in small groups.","zh":"一些牛科動物生活在小群體中。"},{"en":"The option asks whether most bovids live in small groups.","zh":"這個選項問大多數牛科動物是否生活在小群體中。"},{"en":"Animals in small groups may still have social rules.","zh":"生活在小群體中的動物仍可能有社會規則。"},{"en":"Forest species sometimes move in small groups.","zh":"森林物種有時以小群體移動。"},{"en":"Living in small groups can reduce the risk from predators.","zh":"生活在小群體中可以降低受掠食者威脅的風險。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":14},{"front":"wide-open spaces","meaning":"廣闊開放空間","examples":[{"en":"Most bovids prefer wide-open spaces.","zh":"大多數牛科動物偏好廣闊開放空間。"},{"en":"Wide-open spaces help fast-running species escape predators.","zh":"廣闊開放空間幫助跑得快的物種逃離掠食者。"},{"en":"Grasslands and deserts are wide-open spaces.","zh":"草原和沙漠是廣闊開放空間。"},{"en":"Antelopes are often seen in wide-open spaces.","zh":"羚羊常見於廣闊開放空間。"},{"en":"The passage connects most bovids with wide-open spaces.","zh":"文章把大多數牛科動物與廣闊開放空間聯繫起來。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":14},{"front":"feature in common","meaning":"共同特徵","examples":[{"en":"The question asks which feature all bovids have in common.","zh":"題目問所有牛科動物有哪項共同特徵。"},{"en":"Horns in males are one feature in common.","zh":"雄性有角是一項共同特徵。"},{"en":"Ruminant digestion is a feature in common among bovids.","zh":"反芻消化是牛科動物的一項共同特徵。"},{"en":"A feature in common can help classify animals.","zh":"共同特徵可以幫助分類動物。"},{"en":"Cloven hooves are another feature in common.","zh":"分趾蹄是另一項共同特徵。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":14},{"front":"store undigested food","meaning":"儲存未消化食物","examples":[{"en":"Bovids store undigested food in their stomachs.","zh":"牛科動物在胃中儲存未消化食物。"},{"en":"Ruminants store undigested food before regurgitating it.","zh":"反芻動物在反芻前儲存未消化食物。"},{"en":"Special stomach chambers allow them to store undigested food.","zh":"特殊胃室讓牠們儲存未消化食物。"},{"en":"Animals that store undigested food can process grass efficiently.","zh":"儲存未消化食物的動物可以有效處理草。"},{"en":"The question asks which animals store undigested food.","zh":"題目問哪些動物儲存未消化食物。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":14},{"front":"look at the following characteristics","meaning":"查看以下特徵","examples":[{"en":"Candidates look at the following characteristics before matching answers.","zh":"考生在配對答案前查看以下特徵。"},{"en":"Look at the following characteristics and identify the correct subfamily.","zh":"查看以下特徵，並辨認正確亞科。"},{"en":"Students should look at the following characteristics carefully.","zh":"學生應仔細查看以下特徵。"},{"en":"The task asks readers to look at the following characteristics of bovids.","zh":"這項任務要求讀者查看以下牛科動物特徵。"},{"en":"After you look at the following characteristics, compare them with the passage.","zh":"查看以下特徵後，把它們與文章比較。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":14},{"front":"match each characteristic with","meaning":"將每項特徵與……配對","examples":[{"en":"Students match each characteristic with the correct subfamily.","zh":"學生將每項特徵與正確亞科配對。"},{"en":"Match each characteristic with the group described in the passage.","zh":"將每項特徵與文章描述的群體配對。"},{"en":"Candidates must match each characteristic with one letter.","zh":"考生必須將每項特徵與一個字母配對。"},{"en":"It is important to match each characteristic with evidence from the text.","zh":"將每項特徵與文本證據配對很重要。"},{"en":"The task asks readers to match each characteristic with a bovid subfamily.","zh":"這項任務要求讀者將每項特徵與牛科亞科配對。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":14},{"front":"correct subfamily","meaning":"正確亞科","examples":[{"en":"Each characteristic must be matched with the correct subfamily.","zh":"每項特徵都必須與正確亞科配對。"},{"en":"Caprinae is the correct subfamily for sheep and goats.","zh":"羊亞科是綿羊和山羊的正確亞科。"},{"en":"Cephalophinae is the correct subfamily for duikers.","zh":"遁羚亞科是遁羚的正確亞科。"},{"en":"Students must choose the correct subfamily from the list.","zh":"學生必須從列表中選擇正確亞科。"},{"en":"The correct subfamily can be found by reading the relevant paragraph.","zh":"正確亞科可以透過閱讀相關段落找到。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":14},{"front":"may use any letter more than once","meaning":"可重複使用任何字母","examples":[{"en":"Candidates may use any letter more than once.","zh":"考生可重複使用任何字母。"},{"en":"The instruction says you may use any letter more than once.","zh":"指示說你可重複使用任何字母。"},{"en":"If two answers refer to the same group, you may use any letter more than once.","zh":"如果兩個答案指同一群體，你可重複使用任何字母。"},{"en":"Students should not avoid repetition because they may use any letter more than once.","zh":"學生不應避免重複，因為可重複使用任何字母。"},{"en":"In matching tasks, you may use any letter more than once when allowed.","zh":"在配對題中，如指示容許，你可重複使用任何字母。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":14},{"front":"endure very harsh environments","meaning":"忍受極惡劣環境","examples":[{"en":"Some bovids can endure very harsh environments.","zh":"一些牛科動物能忍受極惡劣環境。"},{"en":"Musk oxen endure very harsh environments in arctic tundra.","zh":"麝牛在北極苔原中忍受極惡劣環境。"},{"en":"Barbary sheep endure very harsh environments in deserts.","zh":"鬃羊在沙漠中忍受極惡劣環境。"},{"en":"Species that endure very harsh environments need special adaptations.","zh":"能忍受極惡劣環境的物種需要特殊適應。"},{"en":"Caprinae members often endure very harsh environments.","zh":"羊亞科成員常能忍受極惡劣環境。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":14},{"front":"supplement its diet with meat","meaning":"以肉類補充飲食","examples":[{"en":"Some duikers may supplement their diet with meat.","zh":"一些遁羚可能以肉類補充飲食。"},{"en":"An animal that supplements its diet with meat is not strictly herbivorous.","zh":"以肉類補充飲食的動物並非嚴格草食。"},{"en":"The passage suggests that certain duikers supplement their diet with meat.","zh":"文章暗示某些遁羚以肉類補充飲食。"},{"en":"Insects and carcasses may supplement its diet with meat.","zh":"昆蟲和屍體可能讓牠以肉類補充飲食。"},{"en":"This behaviour allows a bovid to supplement its diet with meat.","zh":"這種行為使牛科動物能以肉類補充飲食。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":14},{"front":"move at high speed","meaning":"高速移動","examples":[{"en":"Antelopes can move at high speed.","zh":"羚羊可以高速移動。"},{"en":"Fast-running species move at high speed to escape predators.","zh":"跑得快的物種高速移動以逃離掠食者。"},{"en":"The pronghorn can move at high speed across open plains.","zh":"叉角羚可以在開闊平原上高速移動。"},{"en":"Animals in wide-open spaces often need to move at high speed.","zh":"廣闊開放空間中的動物通常需要高速移動。"},{"en":"Gazelles move at high speed when alarmed.","zh":"瞪羚受驚時會高速移動。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":14},{"front":"defend a particular territory","meaning":"保衛特定領域","examples":[{"en":"Some bovids defend a particular territory.","zh":"一些牛科動物會保衛特定領域。"},{"en":"Bovinae members generally do not defend a particular territory.","zh":"牛亞科成員通常不保衛特定領域。"},{"en":"Animals that defend a particular territory may mark boundaries.","zh":"保衛特定領域的動物可能標記邊界。"},{"en":"The question asks which group does not defend a particular territory.","zh":"題目問哪一群體不保衛特定領域。"},{"en":"Territorial antelopes may defend a particular territory from rivals.","zh":"有領域性的羚羊可能保衛特定領域以防競爭者。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":15},{"front":"answer the questions below","meaning":"回答以下問題","examples":[{"en":"Candidates answer the questions below using words from the passage.","zh":"考生使用文章中的字詞回答以下問題。"},{"en":"Read the passage carefully before you answer the questions below.","zh":"回答以下問題前，仔細閱讀文章。"},{"en":"Students should answer the questions below with short phrases.","zh":"學生應用短語回答以下問題。"},{"en":"The instruction asks candidates to answer the questions below directly.","zh":"指示要求考生直接回答以下問題。"},{"en":"To answer the questions below, locate the relevant paragraph first.","zh":"要回答以下問題，先找出相關段落。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":15},{"front":"no more than three words","meaning":"不超過三個詞","examples":[{"en":"Candidates should write no more than three words.","zh":"考生應寫不超過三個詞。"},{"en":"The answer must contain no more than three words from the passage.","zh":"答案必須包含不超過三個來自文章的詞。"},{"en":"If you write four words, you break the no more than three words rule.","zh":"如果你寫四個詞，就違反不超過三個詞的規則。"},{"en":"No more than three words means one, two or three words only.","zh":"不超過三個詞意思是只可用一個、兩個或三個詞。"},{"en":"Always check the instruction no more than three words before answering.","zh":"作答前務必檢查不超過三個詞這項指示。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":15},{"front":"smallest species of bovid","meaning":"最小的牛科物種","examples":[{"en":"The royal antelope is the smallest species of bovid mentioned.","zh":"倭羚是文中提到的最小牛科物種。"},{"en":"The question asks for the smallest species of bovid.","zh":"題目問最小的牛科物種。"},{"en":"The smallest species of bovid stands only a short height at the shoulder.","zh":"最小的牛科物種肩高很低。"},{"en":"Students should identify the smallest species of bovid from the first paragraph.","zh":"學生應從第一段找出最小的牛科物種。"},{"en":"The smallest species of bovid contrasts with the bison.","zh":"最小的牛科物種與野牛形成對比。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":15},{"front":"species of Bovinae","meaning":"牛亞科物種","examples":[{"en":"The auroch is a species of Bovinae that is extinct.","zh":"原牛是一種已滅絕的牛亞科物種。"},{"en":"The question asks which species of Bovinae is now extinct.","zh":"題目問哪一種牛亞科物種現已滅絕。"},{"en":"Cattle are a domestic species related to Bovinae.","zh":"牛是與牛亞科有關的家養物種。"},{"en":"Several species of Bovinae are rare in the wild.","zh":"幾種牛亞科物種在野外很稀有。"},{"en":"Students should find the extinct species of Bovinae in the passage.","zh":"學生應在文章中找出已滅絕的牛亞科物種。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":15},{"front":"move over wetland","meaning":"在濕地上行走","examples":[{"en":"The sitatunga’s hooves help it move over wetland.","zh":"澤羚的蹄幫助牠在濕地上行走。"},{"en":"Animals need special feet to move over wetland.","zh":"動物需要特殊足部才能在濕地上行走。"},{"en":"Splayed hooves allow the sitatunga to move over wetland.","zh":"張開的蹄讓澤羚能在濕地上行走。"},{"en":"It is difficult for heavy animals to move over wetland.","zh":"重型動物很難在濕地上行走。"},{"en":"The question asks what helps the sitatunga move over wetland.","zh":"題目問甚麼幫助澤羚在濕地上行走。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":15},{"front":"kind of terrain","meaning":"地形類型","examples":[{"en":"The question asks what kind of terrain Barbary sheep inhabit.","zh":"題目問鬃羊棲息於哪種地形類型。"},{"en":"Arid deserts are the kind of terrain mentioned for Barbary sheep.","zh":"乾旱沙漠是文中提到鬃羊棲息的地形類型。"},{"en":"Mountain slopes are a difficult kind of terrain.","zh":"山坡是一種困難的地形類型。"},{"en":"The sitatunga is adapted to a wet kind of terrain.","zh":"澤羚適應潮濕的地形類型。"},{"en":"Each species is suited to a different kind of terrain.","zh":"每個物種都適合不同地形類型。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":15},{"front":"inhabit","meaning":"棲息於","examples":[{"en":"Barbary sheep inhabit arid deserts.","zh":"鬃羊棲息於乾旱沙漠。"},{"en":"Musk oxen inhabit arctic tundra.","zh":"麝牛棲息於北極苔原。"},{"en":"Duikers inhabit thick forest.","zh":"遁羚棲息於茂密森林。"},{"en":"Many antelopes inhabit open grasslands.","zh":"許多羚羊棲息於開闊草原。"},{"en":"The passage explains which habitats different bovids inhabit.","zh":"文章解釋不同牛科動物棲息於哪些棲息地。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":15},{"front":"only surviving member","meaning":"唯一現存成員","examples":[{"en":"The pronghorn is the only surviving member of Antilocapridae.","zh":"叉角羚是叉角羚科唯一現存成員。"},{"en":"An only surviving member may represent a once larger group.","zh":"唯一現存成員可能代表一個曾經較大的群體。"},{"en":"The question asks for the only surviving member of that family.","zh":"題目問該科的唯一現存成員。"},{"en":"The only surviving member can be especially important to conservationists.","zh":"唯一現存成員對保育人士可能特別重要。"},{"en":"Students should answer “pronghorn” for the only surviving member.","zh":"學生應以“pronghorn”回答唯一現存成員。"}],"source":"Passage 2 Flash Cards 173 - Bovids.pdf","sourcePage":15}]};
